@final
@doc(where, klass=_shared_doc_kwargs['klass'], cond='False', cond_rev='True', name='mask', name_other='where')
def mask(self, cond, other=lib.no_default, *, inplace: bool=False, axis: Axis | None=None, level: Level | None=None) -> Self | None:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if <MASK>:
        if not PYPY and (not WARNING_CHECK_DISABLED):
            if sys.getrefcount(self) <= REF_COUNT:
                warnings.warn(_chained_assignment_method_msg, ChainedAssignmentError, stacklevel=2)
    cond = common.apply_if_callable(cond, self)
    other = common.apply_if_callable(other, self)
    if not hasattr(cond, '__invert__'):
        cond = np.array(cond)
    return self._where(~cond, other=other, inplace=inplace, axis=axis, level=level)

def visit_FunctionDef(self, node):
    compose_dec = []
    for dec in node.decorator_list:
        if isinstance(dec, ast.Call):
            if isinstance(dec.func, ast.Attribute) and dec.func.attr == 'Composite':
                compose_dec.append(dec)
            if isinstance(dec.func, ast.Name) and dec.func.id == 'Composite':
                compose_dec.append(dec)
    if not compose_dec:
        return
    elif len(compose_dec) > 1:
        raise KeyError('More than one TF ops decomposes for.')
    all_dec_args = {}
    for (arg_name, arg_value) in zip(_COMPOSITE_ARG_LIST, compose_dec[0].args):
        all_dec_args[arg_name] = self.visit(arg_value)
    kw_dec_args = dict([self.visit(kw) for kw in compose_dec[0].keywords])
    if all_dec_args.keys() & kw_dec_args.keys():
        raise KeyError('More arguments than expected.')
    all_dec_args.update(kw_dec_args)
    op_name = all_dec_args['op_name']
    op_def = op_def_registry.get(op_name)
    if op_def:
        if <MASK>:
            raise ValueError('Op has been registered: ' + op_name)
        else:
            return
    inputs = all_dec_args.get('inputs', [])
    attrs = all_dec_args.get('attrs', [])
    expected_args = [arg.split(':')[0] for arg in inputs + attrs]
    all_func_args = self.visit(node.args)
    if len(expected_args) != len(all_func_args):
        raise KeyError('Composition arguments for {} do not match the registration. {} vs {}'.format(op_name, expected_args, all_func_args))
    cxx_reg_code = ['\nREGISTER_OP("{}")'.format(op_name)]
    for input_ in inputs:
        cxx_reg_code.append('.Input("{}")'.format(input_))
    for attr in attrs:
        py_str = attr.replace('"', "'")
        cxx_reg_code.append('.Attr("{}")'.format(py_str))
    for attr in all_dec_args.get('derived_attrs', []):
        py_str = attr.replace('"', "'")
        cxx_reg_code.append('.Attr("{}")'.format(py_str))
    for output_ in all_dec_args.get('outputs', []):
        cxx_reg_code.append('.Output("{}")'.format(output_))
    cxx_reg_code[-1] += ';\n'
    self.emit('\n    '.join(cxx_reg_code))

def _run_policy(self, root_module: nn.Module, ignored_modules: set[nn.Module], root_kwargs: dict[str, Any]) -> dict[nn.Module, dict[str, Any]]:
    module_classes = tuple(self._module_classes)
    target_module_to_kwargs: dict[nn.Module, dict[str, Any]] = {}
    for module in root_module.modules():
        if module in ignored_modules:
            continue
        elif <MASK>:
            target_module_to_kwargs[module] = copy.copy(root_kwargs)
    return target_module_to_kwargs

def run_impl(self, use_fuser):
    warmups = 10
    if self.device == 'cuda':
        iters = 1000
    else:
        iters = 10
    engine = tensor_engine.get_engine()
    self.bm_jit = None
    for i in range(warmups + iters):
        if i == warmups:
            if self.device == 'cuda':
                engine.sync_cuda()
            time_start = time.time()
        if i == 0:
            if self.jit_mode == 'trace' and use_fuser:
                self.bm_jit = torch.jit.trace(self.forward, example_inputs=self.inputs, check_trace=False)
            if <MASK>:
                self.check()
            else:
                print('Warning: no reference result for ', self.module())
        elif i == 1:
            if self.jit_mode == 'trace' and use_fuser and self.print_ir:
                print(self.bm_jit.graph_for(*self.inputs))
        z = self.compute()
        if self.mode == 'both':
            if self.result_grad is None:
                self.result_grad = engine.rand_like(z)
            engine.backward([z], [self.result_grad], self.grad_variables)
    if self.device == 'cuda':
        engine.sync_cuda()
    duration = time.time() - time_start
    iter_time = duration / iters
    memory_workload = self.memory_workload()
    compute_workload = self.compute_workload()
    result_dict = {'desc': self.desc(), 'us': iter_time * 1000000.0, 'sol': memory_workload['sol'] * self.dtype_to_bytes() / iter_time / 1000000000.0, 'algorithmic': memory_workload['algorithmic'] * self.dtype_to_bytes() / iter_time / 1000000000.0}
    if compute_workload:
        result_dict['compute_workload'] = compute_workload / iter_time / 1000000000.0
    self.dump_result(result_dict)

def _interleave(lists, cycle_length, block_length, num_parallel_calls=None):
    """Reference implementation of interleave used for testing.

  Args:
    lists: a list of lists to interleave
    cycle_length: the length of the interleave cycle
    block_length: the length of the interleave block
    num_parallel_calls: the number of parallel calls

  Yields:
    Elements of `lists` interleaved in the order determined by `cycle_length`
    and `block_length`.
  """
    num_open = 0
    all_iterators = [iter(l) for l in lists]
    open_iterators = []
    if <MASK>:
        cpu_count = multiprocessing.cpu_count()
        if hasattr(os, 'sched_getaffinity'):
            try:
                cpu_count = len(os.sched_getaffinity(0))
            except NotImplementedError:
                pass
        if num_parallel_calls is None:
            cycle_length = cpu_count
        elif num_parallel_calls == dataset_ops.AUTOTUNE:
            cycle_length = (cpu_count + 2) // 3
        else:
            cycle_length = min(num_parallel_calls, cpu_count)
    for i in range(cycle_length):
        if all_iterators:
            open_iterators.append(all_iterators.pop(0))
            num_open += 1
        else:
            open_iterators.append(None)
    while num_open or all_iterators:
        for i in range(cycle_length):
            if open_iterators[i] is None:
                if all_iterators:
                    open_iterators[i] = all_iterators.pop(0)
                    num_open += 1
                else:
                    continue
            for _ in range(block_length):
                try:
                    yield next(open_iterators[i])
                except StopIteration:
                    open_iterators[i] = None
                    num_open -= 1
                    break

def display_for_field(value, field, empty_value_display, avoid_link=False):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon
    if field.name == 'password' and field.model == get_user_model():
        return render_password_as_hash(value)
    elif getattr(field, 'flatchoices', None):
        try:
            return dict(field.flatchoices).get(value, empty_value_display)
        except TypeError:
            flatchoices = make_hashable(field.flatchoices)
            value = make_hashable(value)
            return dict(flatchoices).get(value, empty_value_display)
    elif isinstance(field, models.BooleanField):
        return _boolean_icon(value)
    elif value in field.empty_values:
        return empty_value_display
    elif isinstance(field, models.DateTimeField):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(field, (models.DateField, models.TimeField)):
        return formats.localize(value)
    elif isinstance(field, models.DecimalField):
        return formats.number_format(value, field.decimal_places)
    elif isinstance(field, (models.IntegerField, models.FloatField)):
        return formats.number_format(value)
    elif isinstance(field, models.FileField) and value and (not avoid_link):
        return format_html('<a href="{}">{}</a>', value.url, value)
    elif isinstance(field, models.URLField) and value and (not avoid_link):
        return format_html('<a href="{}">{}</a>', value, value)
    elif <MASK>:
        try:
            return json.dumps(value, ensure_ascii=False, cls=field.encoder)
        except TypeError:
            return display_for_value(value, empty_value_display)
    else:
        return display_for_value(value, empty_value_display)

@classmethod
def _check_swappable(cls):
    """Check if the swapped model exists."""
    errors = []
    if <MASK>:
        try:
            apps.get_model(cls._meta.swapped)
        except ValueError:
            errors.append(checks.Error("'%s' is not of the form 'app_label.app_name'." % cls._meta.swappable, id='models.E001'))
        except LookupError:
            (app_label, model_name) = cls._meta.swapped.split('.')
            errors.append(checks.Error("'%s' references '%s.%s', which has not been installed, or is abstract." % (cls._meta.swappable, app_label, model_name), id='models.E002'))
    return errors

def _transfer_attrs(fr, to):
    for attr_name in dir(fr):
        attr_val = getattr(fr, attr_name)
        if <MASK>:
            setattr(to, attr_name, attr_val)

def _run_symbolic_function(graph: _C.Graph, block: _C.Block, node: _C.Node, inputs: Any, env: dict[_C.Value, _C.Value], values_in_env: set[_C.Value], new_nodes: list[_C.Node], operator_export_type=_C_onnx.OperatorExportTypes.ONNX) -> _C.Value | Sequence[_C.Value | None] | None:
    """Runs a symbolic function.

    The function is used in C++ to export the node to ONNX.

    Returns:
        A single or a tuple of Values.
        None when the node gets cloned as is into the new graph.
    """
    opset_version = GLOBALS.export_onnx_opset_version
    node_kind = node.kind()
    if node_kind.endswith('_'):
        ns_op_name = node_kind[:-1]
    else:
        ns_op_name = node_kind
    (namespace, op_name) = jit_utils.parse_node_kind(ns_op_name)
    graph_context = jit_utils.GraphContext(graph=graph, block=block, opset=opset_version, original_node=node, params_dict=_params_dict, env=env, values_in_env=values_in_env, new_nodes=new_nodes)
    if _should_aten_fallback(ns_op_name, opset_version, operator_export_type):
        attrs = {k + '_' + node.kindOf(k)[0]: symbolic_helper._node_get(node, k) for k in node.attributeNames()}
        outputs = node.outputsSize()
        attrs['outputs'] = outputs
        return graph_context.aten_op(op_name, *inputs, overload_name=_get_aten_op_overload_name(node), **attrs)
    try:
        domain = namespace
        symbolic_function_name = f'{domain}::{op_name}'
        symbolic_function_group = registration.registry.get_function_group(symbolic_function_name)
        if symbolic_function_group is not None:
            symbolic_fn = symbolic_function_group.get(opset_version)
            if symbolic_fn is not None:
                attrs = {k: symbolic_helper._node_get(node, k) for k in node.attributeNames()}
                return symbolic_fn(graph_context, *inputs, **attrs)
        attrs = {k + '_' + node.kindOf(k)[0]: symbolic_helper._node_get(node, k) for k in node.attributeNames()}
        if namespace == 'onnx':
            return graph_context.op(op_name, *inputs, **attrs, outputs=node.outputsSize())
        raise errors.UnsupportedOperatorError(symbolic_function_name, opset_version, symbolic_function_group.get_min_supported() if symbolic_function_group else None)
    except RuntimeError:
        if <MASK>:
            return None
        elif operator_export_type == _C_onnx.OperatorExportTypes.ONNX_ATEN_FALLBACK:
            attrs = {k + '_' + node.kindOf(k)[0]: symbolic_helper._node_get(node, k) for k in node.attributeNames()}
            return graph_context.aten_op(op_name, *inputs, overload_name=_get_aten_op_overload_name(node), **attrs)
        raise
    except TypeError as e:
        e.args = (f'{e.args[0]} \n(Occurred when translating {op_name}).',)
        raise

def _get_openmp_args(cpp_compiler: str) -> tuple[list[str], list[str], list[str], list[str], list[str], list[str]]:
    cflags: list[str] = []
    ldflags: list[str] = []
    include_dir_paths: list[str] = []
    lib_dir_paths: list[str] = []
    libs: list[str] = []
    passthrough_args: list[str] = []
    if config.aot_inductor.cross_target_platform == 'windows':
        return (cflags, ldflags, include_dir_paths, lib_dir_paths, libs, passthrough_args)
    if _IS_MACOS:
        cflags.append('Xclang')
        cflags.append('fopenmp')
        omp_available = not _is_apple_clang(cpp_compiler)
        omp_prefix = os.getenv('OMP_PREFIX')
        if omp_prefix is not None:
            header_path = os.path.join(omp_prefix, 'include', 'omp.h')
            valid_env = os.path.exists(header_path)
            if valid_env:
                include_dir_paths.append(os.path.join(omp_prefix, 'include'))
                lib_dir_paths.append(os.path.join(omp_prefix, 'lib'))
            else:
                warnings.warn('environment variable `OMP_PREFIX` is invalid.')
            omp_available = omp_available or valid_env
        if not omp_available:
            libs.append('omp')
        conda_prefix = os.getenv('CONDA_PREFIX')
        if not omp_available and conda_prefix is not None:
            omp_available = is_conda_llvm_openmp_installed()
            if omp_available:
                conda_lib_path = os.path.join(conda_prefix, 'lib')
                include_dir_paths.append(os.path.join(conda_prefix, 'include'))
                lib_dir_paths.append(conda_lib_path)
                if os.uname().machine == 'x86_64' and os.path.exists(os.path.join(conda_lib_path, 'libiomp5.dylib')):
                    libs.append('iomp5')
        if not omp_available:
            (omp_available, libomp_path) = homebrew_libomp()
            if omp_available:
                include_dir_paths.append(os.path.join(libomp_path, 'include'))
                lib_dir_paths.append(os.path.join(libomp_path, 'lib'))
    elif _IS_WINDOWS:
        "\n        On Windows, `clang` and `icx` have their specific openmp implenmention.\n        And the openmp lib is in compiler's some sub-directory.\n        For dynamic library(DLL) load, the Windows native APIs are `LoadLibraryA` and `LoadLibraryExA`, and their search\n        dependencies have some rules:\n        https://learn.microsoft.com/en-us/windows/win32/api/libloaderapi/nf-libloaderapi-loadlibraryexa#searching-for-dlls-and-dependencies\n        In some case, the rules may not include compiler's sub-directories.\n        So, it can't search and load compiler's openmp library correctly.\n        And then, the whole application would be broken.\n\n        To avoid the openmp load failed, we can automatic locate the openmp binary and preload it.\n        1. For clang, the function is `perload_clang_libomp_win`.\n        2. For icx, the function is `perload_icx_libomp_win`.\n        "
        if <MASK>:
            cflags.append('openmp')
            libs.append('libomp')
            perload_clang_libomp_win(cpp_compiler, 'libomp.dll')
        elif _is_intel_compiler(cpp_compiler):
            cflags.append('Qiopenmp')
            libs.append('libiomp5md')
            perload_icx_libomp_win(cpp_compiler)
        else:
            cflags.append('openmp')
            cflags.append('openmp:experimental')
    elif config.is_fbcode():
        include_dir_paths.append(build_paths.openmp_include)
        openmp_lib = build_paths.openmp_lib_so
        fb_openmp_extra_flags = f'-Wp,-fopenmp {openmp_lib}'
        passthrough_args.append(fb_openmp_extra_flags)
        libs.append('omp')
    elif _is_clang(cpp_compiler):
        cflags.append('fopenmp')
        libs.append('gomp')
    elif _is_intel_compiler(cpp_compiler):
        cflags.append('fiopenmp')
    else:
        cflags.append('fopenmp')
        libs.append('gomp')
    return (cflags, ldflags, include_dir_paths, lib_dir_paths, libs, passthrough_args)

def compile_fn(self, gm: fx.GraphModule, example_inputs: list[torch.Tensor]) -> CompiledFn:
    """
        Implements graph splitting, first determining a set of of buckets by counting
        parameter sizes in reverse graph order, then invoking the user/backend compiler
        to compile each subgraph. Finally, stiches compiled graphs into one graphmodule
        and returns its callable.
        """
    buckets = [Bucket()]
    processed_modules: set[torch.nn.Module] = set()
    for node in reversed(gm.graph.nodes):
        if node.op in ('output', 'placeholder'):
            continue
        if buckets[0].size >= self.bucket_bytes_cap or (len(buckets) == 1 and buckets[0].size >= self.first_bucket_cap):
            if bucket_has_external_output(buckets[0]):
                buckets.insert(0, Bucket())
            else:
                if buckets[0].opcount_increased_to_capture_external_output == 0:
                    buckets[0].paramsize_before_opcount_increase = buckets[0].size
                buckets[0].opcount_increased_to_capture_external_output += 1
        if node.op == 'call_function':
            self.add_param_args(buckets[0], node)
        elif node.op == 'call_module':
            target_mod = gm.get_submodule(node.target)
            if <MASK>:
                self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
        elif node.op == 'call_method':
            if isinstance(node.args[0].target, str):
                target_mod = None
                try:
                    target_mod = gm.get_submodule(node.args[0].target)
                except AttributeError:
                    pass
                if target_mod is not None and target_mod not in processed_modules:
                    self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
                self.add_param_args(buckets[0], node)
        elif node.op == 'get_attr':
            maybe_param = getattr(gm, node.target)
            if isinstance(maybe_param, torch.nn.Parameter) and maybe_param.requires_grad and (not self._ignore_parameter(maybe_param)):
                self.add_param(buckets[0], maybe_param, node.target)
        buckets[0].nodes.append(node)
    if len(buckets) > 1 and buckets[0].size == 0:
        buckets[1].nodes.extend(buckets[0].nodes)
        assert len(buckets[0].params) == 0, 'Params should be empty if size is 0'
        del buckets[0]
    self.buckets = buckets
    pretty_print_buckets(buckets, self.bucket_bytes_cap)
    if len(buckets) == 1:
        return self.backend_compile_fn(gm, example_inputs)
    partition_map = {}
    for (idx, b) in enumerate(buckets):
        for node in b.nodes:
            partition_map[node] = idx
    split_gm = fx.passes.split_module.split_module(gm, None, lambda node: partition_map[node])
    propagate_dynamo_source(gm, split_gm)
    propagate_metadata(gm, split_gm)
    debug_str = f'\n---orig graph---\n{gm.graph}\n' + f'\n---split graph---\n{split_gm.graph}\n'
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            debug_str += f'\n---{name} graph---\n{module.graph}\n'
    debug_str += '\n---------------\n'
    ddp_graph_log.debug(debug_str)
    trace_structured('optimize_ddp_split_graph', payload_fn=lambda : split_gm.print_readable(print_output=False))
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            trace_structured('optimize_ddp_split_child', lambda : {'name': name}, payload_fn=lambda : module.print_readable(print_output=False))
    fake_mode = detect_fake_mode(example_inputs)
    if fake_mode is None:
        fake_mode = torch._subclasses.fake_tensor.FakeTensorMode()
    submod_compiler = SubmodCompiler(split_gm, self.backend_compile_fn, fake_mode)
    with torch._dynamo.utils._disable_saved_tensors_hooks_during_tracing():
        submod_compiler.run(*example_inputs)
    split_gm.recompile()
    ddp_graph_log.debug('\n---final graph---\n%s\n---------------\n', split_gm.graph)
    return split_gm

def run_node(self, node: torch.fx.Node) -> Any:
    if node.target == 'output':

        def set_env(arg: torch.fx.Node) -> None:
            self.env[arg] = self.unknown_value
        pytree.tree_map_only_(torch.fx.Node, set_env, node.args)
        return super().run_node(node)
    (args, kwargs) = self.fetch_args_kwargs_from_env(node)
    flattened_inputs = pytree.arg_tree_leaves(*args, **kwargs)
    if any((type(self.unknown_value) is type(input_) and self.unknown_value == input_ for input_ in flattened_inputs)):
        return self.unknown_value
    if node.op == 'call_function' and node.target == aten._efficientzerotensor.default:
        return self.unknown_value
    if node.op == 'call_function' and node.name == 'triton_kernel_wrapper_functional_proxy':
        return self.unknown_value
    if <MASK>:
        return self.unknown_value
    if isinstance(node.target, torch._ops.OpOverload) and torch.Tag.nondeterministic_seeded in node.target.tags:
        return self.unknown_value
    if node.op == 'call_function' and isinstance(node.target, torch._ops.HigherOrderOperator):
        return self.unknown_value
    out = self._deduce_value(node)
    if isinstance(out, torch._C.ScriptObject):
        return out
    if out == self.unknown_value:
        return self.unknown_value
    if not is_const_source(node, self.lifted_constant_names) and (isinstance(out, torch.Tensor) or out == self.deferred_value):
        if out != self.deferred_value and out.device.type == 'meta':
            return out
        if not self.insertable_tensor_check(out):
            return out
        if self.is_impure(node):
            return self.unknown_value
        self.add_node_replacement(node, out)
        flattened_node_inps = pytree.arg_tree_leaves(*node.args, **node.kwargs)
        for n in flattened_node_inps:
            if not isinstance(n, torch.fx.Node):
                continue
            self.replaced_uses[n] += 1
        for to_delete in self.user_to_last_uses.get(node, []):
            if self.replaced_uses[to_delete] == len(to_delete.users):
                self.node_replacements.pop(to_delete, None)
    return out

def should_swap(idx_a, idx_b):

    def ge(a, b):
        """
            Returns true if a is symbolically greater than or equal to b, assuming a >= 0, b >= 0.
            """
        if guard_or_false(b == 0):
            return True
        elif guard_or_false(a == 0):
            return False
        return guard_or_false(a >= b) or guard_or_false(a % b == 0)
    for tensor in tensors:
        stride_a = tensor.stride()[idx_a]
        stride_b = tensor.stride()[idx_b]
        if <MASK>:
            continue
        if guard_or_false(stride_a == stride_b):
            if ge(shape[idx_b], shape[idx_a]):
                continue
            return 1
        if ge(stride_b, stride_a):
            return -1
        if ge(stride_a, stride_b):
            return 1
    return 0

def sanitize_array(data, index: Index | None, dtype: DtypeObj | None=None, copy: bool=False, *, allow_2d: bool=False) -> ArrayLike:
    """
    Sanitize input data to an ndarray or ExtensionArray, copy if specified,
    coerce to the dtype if specified.

    Parameters
    ----------
    data : Any
    index : Index or None, default None
    dtype : np.dtype, ExtensionDtype, or None, default None
    copy : bool, default False
    allow_2d : bool, default False
        If False, raise if we have a 2D Arraylike.

    Returns
    -------
    np.ndarray or ExtensionArray
    """
    original_dtype = dtype
    if isinstance(data, ma.MaskedArray):
        data = sanitize_masked_array(data)
    if isinstance(dtype, NumpyEADtype):
        dtype = dtype.numpy_dtype
    infer_object = not isinstance(data, (ABCIndex, ABCSeries))
    data = extract_array(data, extract_numpy=True, extract_range=True)
    if isinstance(data, np.ndarray) and data.ndim == 0:
        if dtype is None:
            dtype = data.dtype
        data = lib.item_from_zerodim(data)
    elif isinstance(data, range):
        data = range_to_ndarray(data)
        copy = False
    if not is_list_like(data):
        if index is None:
            raise ValueError('index must be specified when data is not list-like')
        if isinstance(data, str) and using_string_dtype() and (original_dtype is None):
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
        data = construct_1d_arraylike_from_scalar(data, len(index), dtype)
        return data
    elif isinstance(data, ABCExtensionArray):
        if dtype is not None:
            subarr = data.astype(dtype, copy=copy)
        elif copy:
            subarr = data.copy()
        else:
            subarr = data
    elif isinstance(dtype, ExtensionDtype):
        _sanitize_non_ordered(data)
        cls = dtype.construct_array_type()
        if not hasattr(data, '__array__'):
            data = list(data)
        subarr = cls._from_sequence(data, dtype=dtype, copy=copy)
    elif isinstance(data, np.ndarray):
        if isinstance(data, np.matrix):
            data = data.A
        if dtype is None:
            subarr = data
            if data.dtype == object and infer_object:
                subarr = lib.maybe_convert_objects(data, convert_numeric=False, convert_non_numeric=True, convert_to_nullable_dtype=False, dtype_if_all_nat=np.dtype('M8[s]'))
            elif data.dtype.kind == 'U' and using_string_dtype():
                from pandas.core.arrays.string_ import StringDtype
                dtype = StringDtype(na_value=np.nan)
                subarr = dtype.construct_array_type()._from_sequence(data, dtype=dtype)
            if (subarr is data or (subarr.dtype == 'str' and subarr.dtype.storage == 'python')) and copy:
                subarr = subarr.copy()
        else:
            subarr = _try_cast(data, dtype, copy)
    elif hasattr(data, '__array__'):
        if not copy:
            data = np.asarray(data)
        else:
            data = np.array(data, copy=copy)
        return sanitize_array(data, index=index, dtype=dtype, copy=False, allow_2d=allow_2d)
    else:
        _sanitize_non_ordered(data)
        data = list(data)
        if <MASK>:
            subarr = np.array([], dtype=np.float64)
        elif dtype is not None:
            subarr = _try_cast(data, dtype, copy)
        else:
            subarr = maybe_convert_platform(data)
            if subarr.dtype == object:
                subarr = cast(np.ndarray, subarr)
                subarr = lib.maybe_convert_objects(subarr, convert_numeric=False, convert_non_numeric=True, convert_to_nullable_dtype=False, dtype_if_all_nat=np.dtype('M8[s]'))
    subarr = _sanitize_ndim(subarr, data, dtype, index, allow_2d=allow_2d)
    if isinstance(subarr, np.ndarray):
        dtype = cast(np.dtype, dtype)
        subarr = _sanitize_str_dtypes(subarr, data, dtype, copy)
    return subarr

def _logical_method(self, other, op) -> Self:
    if <MASK>:
        return self._evaluate_op_method(other, op, ARROW_BIT_WISE_FUNCS)
    elif (pa.types.is_string(self._pa_array.type) or pa.types.is_large_string(self._pa_array.type)) and op in (roperator.ror_, roperator.rand_, roperator.rxor) and isinstance(other, np.ndarray) and (other.dtype == bool):
        op_name = op.__name__[1:].strip('_')
        warnings.warn(f"'{op_name}' operations between boolean dtype and {self.dtype} are deprecated and will raise in a future version. Explicitly cast the strings to a boolean dtype before operating instead.", Pandas4Warning, stacklevel=find_stack_level())
        return op(other, self.astype(bool))
    else:
        return self._evaluate_op_method(other, op, ARROW_LOGICAL_FUNCS)

def get_isa_from_cpu_capability(capability: Union[str, None], vec_isa_list: list[VecISA], invalid_vec_isa: InvalidVecISA):
    capability_to_isa_str = {'default': 'INVALID_VEC_ISA', 'zvector': 'zvector', 'vsx': 'vsx', 'avx2': 'avx2', 'avx512': 'avx512'}
    if capability in capability_to_isa_str.keys():
        isa_str = capability_to_isa_str[capability]
        if isa_str == 'INVALID_VEC_ISA':
            return invalid_vec_isa
        for vec_isa in vec_isa_list:
            if <MASK>:
                return vec_isa
    if capability:
        warnings.warn(f'ignoring invalid value for ATEN_CPU_CAPABILITY {capability}')
    return vec_isa_list[0]

@convert_phase(Component.CONVERT_TF_TO_TFLITE_MODEL, SubComponent.CONVERT_JAX_HLO)
def convert_jax_hlo(input_content, input_names, is_proto_format, **kwargs):
    """Converts a Jax hlo-based model using TFLite converter."""
    model_flags = _model_flags_pb2.ModelFlags()
    model_flags.use_hlo_import = True
    if <MASK>:
        model_flags.hlo_file_type = _model_flags_pb2.ModelFlags.HLO_PROTO
    else:
        model_flags.hlo_file_type = _model_flags_pb2.ModelFlags.HLO_TEXT
    for input_name in input_names:
        input_array = model_flags.input_arrays.add()
        input_array.name = input_name
