    data = convert(model_flags, conversion_flags, input_data_str=input_content, debug_info_str=None)
    return data

def get_libraries(self):
    opt = FCompiler.get_libraries(self)
    if self.get_version() >= '11.0':
        opt.extend(['af90math', 'afio', 'af77math', 'amisc'])
    elif self.get_version() >= '10.0':
        opt.extend(['af90math', 'afio', 'af77math', 'U77'])
    elif self.get_version() >= '8.0':
        opt.extend(['f90math', 'fio', 'f77math', 'U77'])
    else:
        opt.extend(['fio', 'f90math', 'fmath', 'U77'])
    if <MASK>:
        opt.append('COMDLG32')
    return opt

def _get_next_no_partial_batch_handling(self, name=None):
    replicas = []
    for (i, worker) in enumerate(self._input_workers.worker_devices):
        if name is not None:
            d = tf_device.DeviceSpec.from_string(worker)
            new_name = '%s_%s_%d' % (name, d.job, d.task)
        else:
            new_name = None
        with ops.device(worker):
            replicas.extend(self._iterators[i].get_next_as_list(new_name))
    if <MASK>:
        replicas = self._reorder_replicas(replicas)
    return _create_per_replica(replicas, self._strategy)

def check_rocm():
    import torch
    from torch.torch_version import TorchVersion
    if <MASK>:
        return None
    torch_rocm_ver = TorchVersion('.'.join(list(torch.version.hip.split('.')[0:2])))
    rocm_ver = get_rocm_version()
    if rocm_ver != torch_rocm_ver:
        warnings.warn(f'ROCm version mismatch, `torch` version: {torch_rocm_ver}, env version: {rocm_ver}')
    if torch_rocm_ver < MIN_ROCM_VERSION:
        warnings.warn(f'(`torch`) ROCm version not supported: {torch_rocm_ver} - minimum requirement: {MIN_ROCM_VERSION}')
    if rocm_ver < MIN_ROCM_VERSION:
        warnings.warn(f'(env) ROCm version not supported: {rocm_ver} - minimum requirement: {MIN_ROCM_VERSION}')
    return rocm_ver if torch.version.hip else 'None'

def _get_loc_level(self, key, level: int | list[int]=0):
    """
        get_loc_level but with `level` known to be positional, not name-based.
        """

    def maybe_mi_droplevels(indexer, levels):
        """
            If level does not exist or all levels were dropped, the exception
            has to be handled outside.
            """
        new_index = self[indexer]
        for i in sorted(levels, reverse=True):
            new_index = new_index._drop_level_numbers([i])
        return new_index
    if isinstance(level, (tuple, list)):
        if len(key) != len(level):
            raise AssertionError('Key for location must have same length as number of levels')
        result = None
        for (lev, k) in zip(level, key, strict=True):
            (loc, new_index) = self._get_loc_level(k, level=lev)
            if isinstance(loc, slice):
                mask = np.zeros(len(self), dtype=bool)
                mask[loc] = True
                loc = mask
            result = loc if result is None else result & loc
        try:
            mi = maybe_mi_droplevels(result, level)
        except ValueError:
            mi = self[result]
        return (result, mi)
    if isinstance(key, list):
        key = tuple(key)
    if isinstance(key, tuple) and level == 0:
        try:
            if key in self.levels[0]:
                indexer = self._get_level_indexer(key, level=level)
                new_index = maybe_mi_droplevels(indexer, [0])
                return (indexer, new_index)
        except (TypeError, InvalidIndexError):
            pass
        if not any((isinstance(k, slice) for k in key)):
            if len(key) == self.nlevels and self.is_unique:
                try:
                    return (self._engine.get_loc(key), None)
                except KeyError as err:
                    raise KeyError(key) from err
                except TypeError:
                    pass
            indexer = self.get_loc(key)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            if len(ilevels) == self.nlevels:
                if <MASK>:
                    return (indexer, None)
                ilevels = [i for i in range(len(key)) if (not isinstance(key[i], str) or not self.levels[i]._supports_partial_string_indexing) and key[i] != slice(None, None)]
                if len(ilevels) == self.nlevels:
                    ilevels = []
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
        else:
            indexer = None
            for (i, k) in enumerate(key):
                if not isinstance(k, slice):
                    loc_level = self._get_level_indexer(k, level=i)
                    if isinstance(loc_level, slice):
                        if com.is_null_slice(loc_level) or com.is_full_slice(loc_level, len(self)):
                            continue
                        k_index = np.zeros(len(self), dtype=bool)
                        k_index[loc_level] = True
                    else:
                        k_index = loc_level
                elif com.is_null_slice(k):
                    continue
                else:
                    raise TypeError(f'Expected label or tuple of labels, got {key}')
                if indexer is None:
                    indexer = k_index
                else:
                    indexer &= k_index
            if indexer is None:
                indexer = slice(None, None)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
    else:
        indexer = self._get_level_indexer(key, level=level)
        if isinstance(key, str) and self.levels[level]._supports_partial_string_indexing:
            check = self.levels[level].get_loc(key)
            if not is_integer(check):
                return (indexer, self[indexer])
        try:
            result_index = maybe_mi_droplevels(indexer, [level])
        except ValueError:
            result_index = self[indexer]
        return (indexer, result_index)

def _register_strategy(strategy: Callable, name: str):

    @wraps(strategy)
    def new_func(old_state: ReproState, granularity=1):
        print(file=sys.stderr)
        print(f'Strategy: {name} (G: {granularity}) ({len(old_state.graph.nodes)} nodes, {len(old_state.inps)} inputs)', file=sys.stderr)
        new_state = strategy(deepcopy_fx_graph(old_state.graph), list(old_state.inps), granularity)
        if new_state is not None:
            new_nodes = len(new_state.graph.nodes)
            old_nodes = len(old_state.graph.nodes)
            new_inps = len(new_state.inps)
            old_inps = len(old_state.inps)
            new_outs = len(get_outputs(new_state.graph))
            old_outs = len(get_outputs(old_state.graph))
            progress_made = False
            if new_nodes < old_nodes:
                progress_made = True
                print(f'SUCCESS: Went from {old_nodes} to {new_nodes} nodes', file=sys.stderr)
            if new_inps > old_inps:
                progress_made = True
                print(f'SUCCESS: Went from {old_inps} to {new_inps} inputs', file=sys.stderr)
            if new_outs < old_outs:
                progress_made = True
                print(f'SUCCESS: Went from {old_outs} to {new_outs} outputs', file=sys.stderr)
            if <MASK>:
                raise RuntimeError('Success raised but no progress made?')
            if not graph_fails(new_state.graph, new_state.inps):
                print('WARNING: Something went wrong, not applying this minification', file=sys.stderr)
                return None
            return new_state
        else:
            print(f'FAIL: {name}', file=sys.stderr)
        return None
    return new_func

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    out = kwargs.get('out', ())
    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(self, ufunc, method, *inputs, **kwargs)
    if result is not NotImplemented:
        return result
    if 'out' in kwargs:
        return arraylike.dispatch_ufunc_with_out(self, ufunc, method, *inputs, **kwargs)
    if <MASK>:
        result = arraylike.dispatch_reduction_ufunc(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    inputs = tuple((x._ndarray if isinstance(x, NumpyExtensionArray) else x for x in inputs))
    if out:
        kwargs['out'] = tuple((x._ndarray if isinstance(x, NumpyExtensionArray) else x for x in out))
    result = getattr(ufunc, method)(*inputs, **kwargs)
    if ufunc.nout > 1:
        return tuple((type(self)(x) for x in result))
    elif method == 'at':
        return None
    elif method == 'reduce':
        if isinstance(result, np.ndarray):
            return type(self)(result)
        return result
    else:
        if self.dtype.type is str:
            self = cast('StringArray', self)
            try:
                return type(self)(result, dtype=self.dtype)
            except ValueError:
                return result
        return type(self)(result)

@staticmethod
def get_device_list() -> Sequence[Optional[int]]:
    """
        Gather the list of devices to be used in the pool.
        """
    if not config.autotune_multi_device:
        return [None]
    gpu_type = get_gpu_type()
    device_interface = get_interface_for_device(gpu_type)
    count = device_interface.device_count()
    if <MASK>:
        devices = [int(d) for d in os.environ[CUDA_VISIBLE_DEVICES].split(',')]
        assert len(devices) <= count
        return devices
    return list(range(count))

def run(self):
    if <MASK>:
        logging.warning('TPUPollingThread is running in a non-GCE environment, exiting...')
        self._running = False
        return
    while self._running:
        recoverable = self._cluster._cloud_tpu_client.recoverable()
        if not recoverable:
            logging.warning('TPUPollingThread found TPU %s in state %s', self._cluster._tpu, self._cluster._cloud_tpu_client.state())
            os._exit(1)
        time.sleep(self._interval)

def experimental_get_compiler_ir(self, *args, **kwargs):
    context.ensure_initialized()
    if not self._jit_compile:
        raise ValueError("Compiler IR can only be returned for functions marked with 'jit_compile=True'")
    is_tensor_spec = lambda x: isinstance(x, tensor_spec.TensorSpec)

    def _check_inputs(args, kwargs):
        all_inputs = list(args) + list(kwargs.values())
        if not all_inputs:
            return
        if any(map(is_tensor_spec, all_inputs)) and any(map(lambda x: not is_tensor_spec(x), all_inputs)):
            raise ValueError('experimental_get_compiler_ir supports either (1) all inputs are TensorSpec  or (2) all inputs are tf.Tensor/python variables')
    _check_inputs(args, kwargs)
    if <MASK>:
        concrete_fn = self.get_concrete_function(*args, **kwargs)
        return compiler_ir.from_concrete_function(concrete_fn)
    concrete_fn = self.get_concrete_function(*args, **kwargs)
    fn_name = concrete_fn.name
    bound_args = function_type_utils.canonicalize_function_inputs(args, kwargs, concrete_fn.function_type)
    filtered_flat_args = concrete_fn.function_type.unpack_inputs(bound_args)

    def compiler_ir_generator(stage='hlo', device_name=None, platform_name=None):
        """Gets the compiler IR bytes.

      Args:
        stage: The exported stage for the given function.
        device_name: The name of the device with the form as
          "/job:localhost/replica:0/task:0/device:CPU:0", "/device:TPU:0" etc.
          When this is used, actual device is used for getting the compiler IR.
        platform_name: The name of the platform, e.g. "TPU". See the comment in
          `get_compiler_ir` in `context.py`.

      Returns:
        The compiler IR bytes.
      """
        if device_name is not None:
            if platform_name is not None:
                raise ValueError('device_name and platform_name cannot be provided at the same time.')
            warnings.warn('device_name is being deprecated. Use platform_name.')
        device_name = compiler_ir.maybe_get_device_name(device_name)
        res_bytes = context.context().get_compiler_ir(device_name=device_name, platform_name=platform_name, function_name=fn_name, flat_args=list(filtered_flat_args), captured_inputs=concrete_fn.captured_inputs, stage=stage)
        if stage in ('stablehlo_serialized', 'hlo_serialized', 'optimized_hlo_serialized', 'optimized_hlo_proto_serialized'):
            return res_bytes
        else:
            return res_bytes.decode('utf-8')
    return compiler_ir_generator

def hipsparse_version_numbers(path):
    possible_version_files = ['include/hipsparse/hipsparse-version.h', 'hipsparse/include/hipsparse-version.h']
    version_file = None
    for f in possible_version_files:
        version_file_path = os.path.join(path, f)
        if os.path.exists(version_file_path):
            version_file = version_file_path
            break
    if <MASK>:
        raise ConfigError('hipsparse version file not found in {}'.format(possible_version_files))
    major = _get_header_version(version_file, 'hipsparseVersionMajor')
    minor = _get_header_version(version_file, 'hipsparseVersionMinor')
    patch = _get_header_version(version_file, 'hipsparseVersionPatch')
    return (major, minor, patch)

def generate_compiler_repro_string(gm: torch.fx.GraphModule, args: Sequence[Any], *, stable_output: bool=False, save_dir: Optional[str]=None, stable_hash: bool=False, has_distributed_ops: bool=False) -> str:
    if save_dir is not None:
        save_dir = normalize_path_separator(save_dir)
    distributed_imports = ''
    if has_distributed_ops:
        distributed_imports = textwrap.dedent('\nimport torch.distributed as dist\nfrom torch.testing._internal.distributed.fake_pg import FakeStore\n        ').strip()
    triton_imports = ''
    if len(kernel_side_table.id_to_kernel) > 0:
        triton_imports = textwrap.dedent('\nimport triton\nimport triton.language as tl\n        ').strip()
    model_str = textwrap.dedent(f'\n{generate_env_vars_string(stable_output=stable_output)}\nimport torch\nfrom torch import tensor, device\nimport torch.fx as fx\nfrom torch._dynamo.testing import rand_strided\nfrom math import inf\nimport torch._inductor.inductor_prims\n{distributed_imports}\n{triton_imports}\n\n{generate_config_string(stable_output=stable_output)}\n\nisolate_fails_code_str = None\n\n{extra_imports}\n\n{maybe_fbcode_instructions()}\n     ')
    if not stable_output:
        model_str += f'# torch version: {torch.version.__version__}\n'
        if hasattr(torch.version, 'cuda'):
            model_str += f'# torch cuda version: {torch.version.cuda}\n'
        if hasattr(torch.version, 'git_version'):
            model_str += f'# torch git version: {torch.version.git_version}\n\n\n'
        model_str += _cuda_system_info_comment()
    kernel_side_table_prefix = 'torch._higher_order_ops.triton_kernel_wrap.kernel_side_table'
    for id in kernel_side_table.id_to_kernel:
        kernel = kernel_side_table.get_kernel(id)
        try:
            if isinstance(kernel, Autotuner):
                if <MASK>:
                    model_str += 'ERROR: Repro will not work as intended, '
                    model_str += 'triton.runtime.autotuner.Heuristics is not currently supported\n'
                    break
                config_strs = []
                for kernel_config in kernel.configs:
                    config_strs.append(f'triton.Config(\n                            {str(kernel_config.kwargs)},\n                            num_warps={kernel_config.num_warps},\n                            num_stages={kernel_config.num_stages},\n                        )')
                config_str = ','.join(config_strs)
                model_str += textwrap.dedent(f'\n                @triton.autotune(\n                    configs=[\n                        {config_str}\n                    ],\n                    key=[]\n                )\n                ').strip()
            model_str += '\n@triton.jit\n'
            src_code = kernel.src if isinstance(kernel, JITFunction) else kernel.fn.src
            fn_name = kernel._fn_name if isinstance(kernel, JITFunction) else kernel.fn._fn_name
            fn_name = fn_name.split('.')[-1]
            model_str += src_code
            model_str += '\n'
            model_str += f'{kernel_side_table_prefix}.add_kernel({fn_name})\n'
        except AttributeError as e:
            model_str += 'ERROR: Repro will not work as intended, '
            model_str += f'User defined triton kernel exception: {e}\n'
    if len(kernel_side_table.constant_args) > 0:
        model_str += f'{kernel_side_table_prefix}.constant_args={kernel_side_table.constant_args}\n'
    model_str += NNModuleToString.convert(gm)
    writer = InputWriter(save_dir, stable_hash=stable_hash)
    used_syms = {}
    placeholder_targets = fx_placeholder_targets(gm)
    for (placeholder, arg) in zip(placeholder_targets, args):
        if isinstance(arg, (int, torch.SymInt)):
            writer.symint(placeholder, arg)
        elif isinstance(arg, torch.Tensor):
            writer.tensor(placeholder, arg)
        elif arg is None:
            writer.const(placeholder)
        else:
            writer.unsupported(placeholder, arg)
        if isinstance(arg, torch.SymInt):
            sym_name = str(arg.node)
            if arg.node.hint is not None:
                used_syms[sym_name] = arg.node.hint
        elif isinstance(arg, torch.Tensor):
            for dim in arg.shape:
                if isinstance(dim, torch.SymInt) and dim.node.hint is not None:
                    used_syms[str(dim.node)] = dim.node.hint
            for stride in arg.stride():
                if isinstance(stride, torch.SymInt) and stride.node.hint is not None:
                    used_syms[str(stride.node)] = stride.node.hint
    if used_syms:
        hint_lines = '\n'.join((f'{name} = {hint}' for (name, hint) in sorted(used_syms.items())))
        model_str = f'{hint_lines}\n\n{model_str}'
    load_args_lines = writer.lines()
    load_args_code = '\n'.join(load_args_lines)
    model_str += load_args_code + '\n'
    model_str += 'mod = Repro()\n'
    return model_str

def __init__(self, out_channels: int, kernel_size: _size_3_t, stride: _size_3_t=1, padding: _size_3_t=0, dilation: _size_3_t=1, groups: int=1, bias: bool=True, padding_mode: Literal['zeros', 'reflect', 'replicate', 'circular']='zeros', device=None, dtype=None) -> None:
    factory_kwargs = {'device': device, 'dtype': dtype}
    super().__init__(0, 0, kernel_size, stride, padding, dilation, groups, False, padding_mode, **factory_kwargs)
    self.weight = UninitializedParameter(**factory_kwargs)
    self.out_channels = out_channels
    if <MASK>:
        self.bias = UninitializedParameter(**factory_kwargs)

@tf_export('linalg.expm')
@dispatch.add_dispatch_support
def matrix_exponential(input, name=None):
    """Computes the matrix exponential of one or more square matrices.

  $$exp(A) = \\sum_{n=0}^\\infty A^n/n!$$

  The exponential is computed using a combination of the scaling and squaring
  method and the Pade approximation. Details can be found in:
  Nicholas J. Higham, "The scaling and squaring method for the matrix
  exponential revisited," SIAM J. Matrix Anal. Applic., 26:1179-1193, 2005.

  The input is a tensor of shape `[..., M, M]` whose inner-most 2 dimensions
  form square matrices. The output is a tensor of the same shape as the input
  containing the exponential for all input submatrices `[..., :, :]`.

  Args:
    input: A `Tensor`. Must be `float16`, `float32`, `float64`, `complex64`, or
      `complex128` with shape `[..., M, M]`.
    name:  A name to give this `Op` (optional).

  Returns:
    the matrix exponential of the input.

  Raises:
    ValueError: An unsupported type is provided as input.

  @compatibility(scipy)
  Equivalent to scipy.linalg.expm
  @end_compatibility
  """
    with ops.name_scope(name, 'matrix_exponential', [input]):
        matrix = ops.convert_to_tensor(input, name='input')
        if matrix.shape[-2:] == [0, 0]:
            return matrix
        batch_shape = matrix.shape[:-2]
        if not batch_shape.is_fully_defined():
            batch_shape = array_ops.shape(matrix)[:-2]
        matrix = array_ops.reshape(matrix, array_ops.concat(([-1], array_ops.shape(matrix)[-2:]), axis=0))
        l1_norm = math_ops.reduce_max(math_ops.reduce_sum(math_ops.abs(matrix), axis=array_ops.size(array_ops.shape(matrix)) - 2), axis=-1)[..., array_ops.newaxis, array_ops.newaxis]
        const = lambda x: constant_op.constant(x, l1_norm.dtype)

        def _nest_where(vals, cases):
            assert len(vals) == len(cases) - 1
            if <MASK>:
                return array_ops.where_v2(math_ops.less(l1_norm, const(vals[0])), cases[0], cases[1])
            else:
                return array_ops.where_v2(math_ops.less(l1_norm, const(vals[0])), cases[0], _nest_where(vals[1:], cases[1:]))
        if matrix.dtype in [dtypes.float16, dtypes.float32, dtypes.complex64]:
            maxnorm = const(3.92572478313866)
            squarings = math_ops.maximum(math_ops.floor(math_ops.log(l1_norm / maxnorm) / math_ops.log(const(2.0))), 0)
            (u3, v3) = _matrix_exp_pade3(matrix)
            (u5, v5) = _matrix_exp_pade5(matrix)
            (u7, v7) = _matrix_exp_pade7(matrix / math_ops.cast(math_ops.pow(const(2.0), squarings), matrix.dtype))
            conds = (0.4258730016922831, 1.880152677804762)
            u = _nest_where(conds, (u3, u5, u7))
            v = _nest_where(conds, (v3, v5, v7))
        elif matrix.dtype in [dtypes.float64, dtypes.complex128]:
            maxnorm = const(5.371920351148152)
            squarings = math_ops.maximum(math_ops.floor(math_ops.log(l1_norm / maxnorm) / math_ops.log(const(2.0))), 0)
            (u3, v3) = _matrix_exp_pade3(matrix)
            (u5, v5) = _matrix_exp_pade5(matrix)
            (u7, v7) = _matrix_exp_pade7(matrix)
            (u9, v9) = _matrix_exp_pade9(matrix)
            (u13, v13) = _matrix_exp_pade13(matrix / math_ops.cast(math_ops.pow(const(2.0), squarings), matrix.dtype))
            conds = (0.01495585217958292, 0.253939833006323, 0.9504178996162932, 2.097847961257068)
            u = _nest_where(conds, (u3, u5, u7, u9, u13))
            v = _nest_where(conds, (v3, v5, v7, v9, v13))
        else:
            raise ValueError('tf.linalg.expm does not support matrices of type %s' % matrix.dtype)
        is_finite = math_ops.is_finite(math_ops.reduce_max(l1_norm))
        nan = constant_op.constant(np.nan, matrix.dtype)
        result = tf_cond.cond(is_finite, lambda : linalg_ops.matrix_solve(-u + v, u + v), lambda : array_ops.fill(array_ops.shape(matrix), nan))
        max_squarings = math_ops.reduce_max(squarings)
        i = const(0.0)

        def c(i, _):
            return tf_cond.cond(is_finite, lambda : math_ops.less(i, max_squarings), lambda : constant_op.constant(False))

        def b(i, r):
            return (i + 1, array_ops.where_v2(math_ops.less(i, squarings), math_ops.matmul(r, r), r))
        (_, result) = while_loop.while_loop(c, b, [i, result])
        if not matrix.shape.is_fully_defined():
            return array_ops.reshape(result, array_ops.concat((batch_shape, array_ops.shape(result)[-2:]), axis=0))
        return array_ops.reshape(result, batch_shape.concatenate(result.shape[-2:]))

def sym_min(a, b):
    """SymInt-aware utility for min()."""
    if <MASK>:
        return overrides.handle_torch_function(sym_min, (a, b), a, b)
    if isinstance(a, (SymInt, SymFloat)):
        return a.__sym_min__(b)
    elif isinstance(b, (SymInt, SymFloat)):
        return b.__sym_min__(a)
    (all_types, float_types) = __all_and_float_types()
    assert isinstance(a, all_types), type(a)
    assert isinstance(b, all_types), type(b)
    if isinstance(a, float_types) or isinstance(b, float_types):
        return builtins.float(builtins.min(a, b))
    else:
        return builtins.min(a, b)

def validate_metadata(self, handler: AppendableTable) -> None:
    """validate that kind=category does not change the categories"""
    if <MASK>:
        new_metadata = self.metadata
        cur_metadata = handler.read_metadata(self.cname)
        if new_metadata is not None and cur_metadata is not None and (not array_equivalent(new_metadata, cur_metadata, strict_nan=True, dtype_equal=True)):
            raise ValueError('cannot append a categorical with different categories to the existing')

def testMultiFunctionModel(self):
    """Test a basic model with multiple tf.functions."""

    class BasicModel(autotrackable.AutoTrackable):

        def __init__(self):
            self.y = None
            self.z = None

        @def_function.function
        def add(self, x):
            if <MASK>:
                self.y = variables.Variable(2.0)
            return x + self.y

        @def_function.function
        def sub(self, x):
            if self.z is None:
                self.z = variables.Variable(3.0)
            return x - self.z
    with ops.Graph().as_default():
        with session_lib.Session() as sess:
            input_data = {'x': constant_op.constant(1.0, shape=[1])}
            root = BasicModel()
            input_func = root.add.get_concrete_function(input_data['x'])
            variable_graph_def = input_func.graph.as_graph_def()
            self.assertEqual(1, get_num_variables(variable_graph_def))
            output_func = convert_to_constants.convert_var_to_const_function_in_v1(input_func)
            self._testConvertedFunction(sess, root, root.add, output_func, input_data)

def _get_current_quantization_mode(self) -> _CurrentQuantizationMode:
    """Retrieves the current quantization mode based on all configurations."""
    qat_state = None
    dynamic_state = None
    for qconfig in list(self.module_name_qconfig.values()) + list(self.operator_type_qconfig.values()) + [self.global_config]:
        if qconfig is not None:
            if qat_state is None:
                qat_state = qconfig.is_qat
            else:
                assert qat_state == qconfig.is_qat, f'All non-None quantization configs should have the same `is_qat`,but got {qat_state} and {qconfig.is_qat}.'
            input_activation_spec = qconfig.input_activation
            if <MASK>:
                if dynamic_state is None:
                    dynamic_state = input_activation_spec.is_dynamic
                else:
                    assert dynamic_state == input_activation_spec.is_dynamic, f'All non-None `input_activation_spec` should have the same `is_dynamic`,but got {dynamic_state} and {input_activation_spec.is_dynamic}.'
    return _CurrentQuantizationMode(qat_state=qat_state, dynamic_state=dynamic_state)

def __exit__(self, unused_type, unused_value, unused_traceback):
    if context.executing_eagerly():
        return
    if self._graph is not ops.get_default_graph():
        raise RuntimeError(f'Within the automatic control dependency context, the default graph cannot change. Upon entry it was {self._graph}, but on exit it changed to {ops.get_default_graph()}')
    outer_graph = getattr(self._graph, 'outer_graph', None)
    if outer_graph is not None:
        self._graph._add_control_dependencies = outer_graph._add_control_dependencies
    else:
        self._graph._add_control_dependencies = False
    self._graph.experimental_acd_manager = None
    last_write_to_resource = {}
    reads_since_last_write_to_resource = collections.defaultdict(list)
    collective_manager_scopes_opened = {}
    collective_manager_scopes_used = {}
    ops_which_must_run = set()
    merge_for_resource = {}
    new_operations = self._graph.get_operations()[self._n_operations:]
    for op in new_operations:
        if <MASK>:
            continue
        control_inputs = set()
        if op.type in MUST_RUN_ORDER_INSENSITIVE_STATEFUL_OPS:
            self.run_independently(op)
        if op in self._independent_ops:
            ops_which_must_run.add(op)
            continue
        if op_def_registry.get(op.type) is None or (op_is_stateful(op) and (op.type not in utils.RESOURCE_READ_OPS or any((output.consumers() for output in op.outputs)))):
            ops_which_must_run.add(op)
        if op.type == 'NoOp':
            try:
                collective_manager_scopes_opened[op.get_attr('_collective_manager_id')] = op
            except ValueError:
                pass
        if op.type == 'Switch' and op.inputs[0].dtype == dtypes_module.resource:
            continue
        if op.type == 'Merge':
            for o in ops_which_must_run:
                op._add_control_input(o)
                for inp in o.inputs:
                    input_id = ops.tensor_id(inp)
                    if input_id in last_write_to_resource:
                        last_write_to_resource[input_id] = op
            ops_which_must_run = set([op])
            continue
        resource_inputs = set()
        for (inp, resource_type) in _get_resource_inputs(op):
            is_read = resource_type == ResourceType.READ_ONLY
            input_id = ops.tensor_id(inp)
            if input_id in resource_inputs:
                continue
            resource_inputs.add(input_id)
            if inp.op.type == 'Switch':
                self._process_switch(inp.op, ops_which_must_run, last_write_to_resource, merge_for_resource)
            is_building_function = op.graph.building_function
            if input_id in last_write_to_resource:
                if is_building_function or last_write_to_resource[input_id]._control_flow_context is op._control_flow_context:
                    control_inputs.add(last_write_to_resource[input_id])
            if input_id in merge_for_resource:
                merge_for_resource[input_id]._add_control_input(op)
            if is_read:
                reads_since_last_write_to_resource[input_id].append(op)
            else:
                control_inputs.update(reads_since_last_write_to_resource[input_id])
                reads_since_last_write_to_resource[input_id] = []
                last_write_to_resource[input_id] = op
        if op_is_stateful(op) and (not resource_inputs) and (op._control_flow_context is None):
            if None in last_write_to_resource:
                op._add_control_input(last_write_to_resource[None])
            last_write_to_resource[None] = op
        manager_ids = collective_manager_ids_from_op(op)
        for manager_id in manager_ids:
            if manager_id in collective_manager_scopes_opened:
                op._add_control_input(collective_manager_scopes_opened[manager_id])
                collective_manager_scopes_opened[manager_id] = op
            else:
                if manager_id in collective_manager_scopes_used:
                    op._add_control_input(collective_manager_scopes_used[manager_id])
                collective_manager_scopes_used[manager_id] = op
        if control_inputs and (not is_building_function):
            control_inputs = [c for c in control_inputs if c._control_flow_context is op._control_flow_context]
        op._add_control_inputs(control_inputs)
    self.ops_which_must_run.update(ops_which_must_run)
    control_output_op = None
    for (idx, r) in enumerate(nest.flatten(list(self._returned_tensors), expand_composites=True)):
        if self.ops_which_must_run:
            updated_ops_which_must_run = []
            if r.graph.building_function:
                if idx == 0:
                    control_output_op = control_flow_ops.no_op()
                    control_output_op._add_control_inputs(self.ops_which_must_run)
                updated_ops_which_must_run = [control_output_op]
            else:
                updated_ops_which_must_run = [o for o in self.ops_which_must_run if o._control_flow_context is r.op._control_flow_context]
            r.op._add_control_inputs(updated_ops_which_must_run)
    self.collective_manager_ids_used = collective_manager_scopes_used

def _hstack(self, Xs, *, n_samples):
    """Stacks Xs horizontally.

        This allows subclasses to control the stacking behavior, while reusing
        everything else from ColumnTransformer.

        Parameters
        ----------
        Xs : list of {array-like, sparse matrix, dataframe}
            The container to concatenate.
        n_samples : int
            The number of samples in the input data to checking the transformation
            consistency.
        """
    if self.sparse_output_:
        try:
            converted_Xs = [check_array(X, accept_sparse=True, ensure_all_finite=False) for X in Xs]
        except ValueError as e:
            raise ValueError('For a sparse output, all columns should be a numeric or convertible to a numeric.') from e
        return sparse.hstack(converted_Xs).tocsr()
    else:
        Xs = [f.toarray() if sparse.issparse(f) else f for f in Xs]
        adapter = _get_container_adapter('transform', self)
        if adapter and all((adapter.is_supported_container(X) for X in Xs)):
            transformer_names = [t[0] for t in self._iter(fitted=True, column_as_labels=False, skip_drop=True, skip_empty_columns=True)]
            feature_names_outs = [X.columns for X in Xs if X.shape[1] != 0]
            if self.verbose_feature_names_out:
                feature_names_outs = self._add_prefix_for_feature_names_out(list(zip(transformer_names, feature_names_outs)))
            else:
                feature_names_outs = list(chain.from_iterable(feature_names_outs))
                feature_names_count = Counter(feature_names_outs)
                if <MASK>:
                    duplicated_feature_names = sorted((name for (name, count) in feature_names_count.items() if count > 1))
                    err_msg = f'Duplicated feature names found before concatenating the outputs of the transformers: {duplicated_feature_names}.\n'
                    for (transformer_name, X) in zip(transformer_names, Xs):
                        if X.shape[1] == 0:
                            continue
                        dup_cols_in_transformer = sorted(set(X.columns).intersection(duplicated_feature_names))
                        if len(dup_cols_in_transformer):
                            err_msg += f'Transformer {transformer_name} has conflicting columns names: {dup_cols_in_transformer}.\n'
                    raise ValueError(err_msg + 'Either make sure that the transformers named above do not generate columns with conflicting names or set verbose_feature_names_out=True to automatically prefix to the output feature names with the name of the transformer to prevent any conflicting names.')
            names_idx = 0
            for X in Xs:
                if X.shape[1] == 0:
                    continue
                names_out = feature_names_outs[names_idx:names_idx + X.shape[1]]
                adapter.rename_columns(X, names_out)
                names_idx += X.shape[1]
            output = adapter.hstack(Xs)
            output_samples = output.shape[0]
            if output_samples != n_samples:
                raise ValueError("Concatenating DataFrames from the transformer's output lead to an inconsistent number of samples. The output may have Pandas Indexes that do not match, or that transformers are returning number of samples which are not the same as the number input samples.")
            return output
        return np.hstack(Xs)

def remove_no_ops(gm: torch.fx.GraphModule, zeros: OrderedSet[torch.fx.Node], ones: OrderedSet[torch.fx.Node]):
    with torch.utils._python_dispatch._disable_current_modes():
        'Removes no-ops: (+ 0, - 0, * 1, / 1)'
        graph = gm.graph

        def fake_tensors_eq(t1, t2, fields=('shape', 'dtype', 'device')):
            if any((not isinstance(t, torch.Tensor) for t in (t1, t2))):
                return False
            for field in fields:
                if getattr(t1, field) != getattr(t2, field):
                    return False
            return True

        def replace_no_op(node, replace_input_index):
            replacement = node.args[replace_input_index]
            if not all((isinstance(arg, torch.fx.Node) for arg in node.args)):
                return
            if not fake_tensors_eq(node.meta['val'], replacement.meta['val']):
                if fake_tensors_eq(node.meta['val'], replacement.meta['val'], ('shape', 'device')):
                    with graph.inserting_after(node):
                        replacement = graph.call_function(torch.ops.prims.convert_element_type.default, args=(replacement, node.meta['val'].dtype))
                else:
                    return
            node.replace_all_uses_with(replacement)
            replacement.meta.update(node.meta)
            graph.erase_node(node)
        for node in graph.find_nodes(op='call_function', target=aten.add.Tensor):
            if len(node.args) == 2:
                if not any((e in zeros for e in node.args)) or node.kwargs.get('alpha', 1) != 1:
                    continue
                replace_index = 1 if node.args[0] in zeros else 0
                replace_no_op(node, replace_index)
        for node in graph.find_nodes(op='call_function', target=aten.sub.Tensor):
            if len(node.args) == 2:
                if node.args[1] not in zeros or node.kwargs.get('alpha', 1) != 1:
                    continue
                replace_no_op(node, 0)
        for node in graph.find_nodes(op='call_function', target=aten.mul.Tensor):
            if len(node.args) == 2:
                if not any((e in ones for e in node.args)):
                    continue
                replace_input_index = 1 if node.args[0] in ones else 0
                replace_no_op(node, replace_input_index)
        for node in graph.find_nodes(op='call_function', target=aten.div.Tensor):
            if len(node.args) == 2 and node.args[1] in ones:
                replace_no_op(node, 0)
        for output_node in graph.find_nodes(op='output'):
            had_meta_return = False

            def visit(n):
                nonlocal had_meta_return
                val = n.meta.get('val')
                if <MASK>:
                    with graph.inserting_before(output_node):
                        n.replace_all_uses_with(graph.call_function(torch.ops.aten.empty_strided.default, args=(val.size(), val.stride()), kwargs={'dtype': val.dtype, 'device': val.device}))
                    had_meta_return = True
            torch.fx.map_arg(output_node.args, visit)
            if had_meta_return:
                graph.eliminate_dead_code()

def ifftn(x: Array, /, xp: Namespace, *, s: Sequence[int] | None=None, axes: Sequence[int] | None=None, norm: _Norm='backward') -> Array:
    res = xp.fft.ifftn(x, s=s, axes=axes, norm=norm)
    if <MASK>:
        return res.astype(xp.complex64)
    return res

def get_expand_dim_for_pointwise_nodes(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode) -> Optional[tuple[int, SchedulerNode, sympy.Expr]]:
    """
        Fusing two small pointwise nodes significantly reduces kernel overhead
        and launch overhead. However, slightly different sizes would prevent fusion.
        Here, we decide if expanding sizes of one node is profitible by allowing
        fusion, and returns the dimension to expand, node with smaller sizes,
        and new size after expand.
        """
    if not isinstance(node1, SchedulerNode) or not isinstance(node2, SchedulerNode):
        return None
    if not (isinstance(node1.node, ir.ComputedBuffer) and isinstance(node2.node, ir.ComputedBuffer)):
        return None
    if node1.has_aliasing_or_mutation() or node2.has_aliasing_or_mutation():
        return None
    if config.cpu_backend == 'halide':
        return None
    (n1_sizes, n2_sizes) = (node1._sizes, node2._sizes)
    (n1_iter_sizes, n1_reduce_sizes) = n1_sizes
    (n2_iter_sizes, n2_reduce_sizes) = n2_sizes
    if node1.is_reduction() or node2.is_reduction() or n1_reduce_sizes != n2_reduce_sizes or (len(n1_iter_sizes) != len(n2_iter_sizes)):
        return None
    if len(node1.read_writes.writes) > 1 or len(node2.read_writes.writes) > 1:
        return None
    node1_write_memory = self.dep_size_hint(next(iter(node1.read_writes.writes)))
    node2_write_memory = self.dep_size_hint(next(iter(node1.read_writes.writes)))
    if max(node1_write_memory, node2_write_memory) > config.small_memory_access_threshold:
        return None

    def has_reusable_buffer(node: BaseSchedulerNode) -> bool:
        for read in node.read_writes.reads:
            input_buf: Optional[Union[SchedulerBuffer, SchedulerDonatedBuffer]]
            if read.name in self.name_to_donated_buffer:
                input_buf = self.name_to_donated_buffer[read.name]
            else:
                input_buf = self.name_to_buf.get(read.name)
            if input_buf and V.graph.wrapper_code.can_reuse(input_buf, node) and (not isinstance(input_buf.defining_op, NopKernelSchedulerNode)):
                return True
        return False
    if has_reusable_buffer(node1) or has_reusable_buffer(node2):
        return None
    mismatch_dimensions = []
    for (idx, (n1_size, n2_size)) in enumerate(zip(n1_iter_sizes, n2_iter_sizes)):
        if <MASK>:
            mismatch_dimensions.append(idx)
    if len(mismatch_dimensions) != 1:
        return None
    mismatch_dim = mismatch_dimensions[0]
    (mismatch_size1, mismatch_size2) = (n1_iter_sizes[mismatch_dim], n2_iter_sizes[mismatch_dim])
    if V.graph.sizevars.statically_known_lt(mismatch_size1, mismatch_size2):
        return (mismatch_dim, node1, mismatch_size2)
    elif V.graph.sizevars.statically_known_lt(mismatch_size2, mismatch_size1):
        return (mismatch_dim, node2, mismatch_size1)
    else:
        return None

def _astype_nansafe(arr: np.ndarray, dtype: DtypeObj, copy: bool=True, skipna: bool=False) -> ArrayLike:
    """
    Cast the elements of an array to a given dtype a nan-safe manner.

    Parameters
    ----------
    arr : ndarray
    dtype : np.dtype or ExtensionDtype
    copy : bool, default True
        If False, a view will be attempted but may fail, if
        e.g. the item sizes don't align.
    skipna: bool, default False
        Whether or not we should skip NaN when casting as a string-type.

    Raises
    ------
    ValueError
        The dtype was a datetime64/timedelta64 dtype, but it had no unit.
    """
    if isinstance(dtype, ExtensionDtype):
        return dtype.construct_array_type()._from_sequence(arr, dtype=dtype, copy=copy)
    elif not isinstance(dtype, np.dtype):
        raise ValueError('dtype must be np.dtype or ExtensionDtype')
    if arr.dtype.kind in 'mM':
        from pandas.core.construction import ensure_wrapped_if_datetimelike
        arr = ensure_wrapped_if_datetimelike(arr)
        res = arr.astype(dtype, copy=copy)
        return np.asarray(res)
    if issubclass(dtype.type, str):
        shape = arr.shape
        if arr.ndim > 1:
            arr = arr.ravel()
        return lib.ensure_string_array(arr, skipna=skipna, convert_na_value=False).reshape(shape)
    elif np.issubdtype(arr.dtype, np.floating) and dtype.kind in 'iu':
        return _astype_float_to_int_nansafe(arr, dtype, copy)
    elif arr.dtype == object:
        if <MASK>:
            from pandas.core.arrays import DatetimeArray
            dta = DatetimeArray._from_sequence(arr, dtype=dtype)
            return dta._ndarray
        elif lib.is_np_dtype(dtype, 'm'):
            from pandas.core.construction import ensure_wrapped_if_datetimelike
            tdvals = array_to_timedelta64(arr).view('m8[ns]')
            tda = ensure_wrapped_if_datetimelike(tdvals)
            return tda.astype(dtype, copy=False)._ndarray
    if dtype.name in ('datetime64', 'timedelta64'):
        msg = f"The '{dtype.name}' dtype has no unit. Please pass in '{dtype.name}[ns]' instead."
        raise ValueError(msg)
    if copy or arr.dtype == object or dtype == object:
        return arr.astype(dtype, copy=True)
    return arr.astype(dtype, copy=copy)

def _linop_matmul(self, left_operator: 'LinearOperator', right_operator: 'LinearOperator') -> 'LinearOperator':
    if <MASK>:
        return left_operator
    elif hasattr(right_operator, '_zeros_diag'):
        if not right_operator.is_square or not left_operator.is_square:
            raise ValueError('Matmul with non-square `LinearOperator`s or non-square `LinearOperatorZeros` not supported at this time.')
        return right_operator
    else:
        is_square = property_hint_util.is_square(left_operator, right_operator)
        is_non_singular = None
        is_self_adjoint = None
        is_positive_definite = None
        if is_square:
            is_non_singular = property_hint_util.combined_non_singular_hint(left_operator, right_operator)
        elif is_square is False:
            is_non_singular = False
            is_self_adjoint = False
            is_positive_definite = False
        from tensorflow.python.ops.linalg import linear_operator_composition
        return linear_operator_composition.LinearOperatorComposition(operators=[left_operator, right_operator], is_non_singular=is_non_singular, is_self_adjoint=is_self_adjoint, is_positive_definite=is_positive_definite, is_square=is_square)

def get_operator_enum(reduce_, use_new_options=False):
    if use_new_options:
        if reduce_ == 'sum':
            return 'REDUCE_ADD'
        elif reduce_ == 'prod':
            return 'REDUCE_MULTIPLY'
        elif reduce_ == 'mean':
            return 'REDUCE_MEAN'
        elif <MASK>:
            return 'REDUCE_MAXIMUM'
        elif reduce_ == 'amin':
            return 'REDUCE_MINIMUM'
        torch._check(False, lambda : 'reduce argument must be either sum, prod, mean, amax or amin.')
        return
    else:
        if reduce_ == 'add':
            return 'REDUCE_ADD'
        elif reduce_ == 'multiply':
            return 'REDUCE_MULTIPLY'
        torch._check(False, lambda : 'reduce argument must be either add or multiply.')
        return

@register_decomposition(aten.logsumexp)
@out_wrapper()
@elementwise_type_promotion_wrapper(type_promoting_args=('self',), type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.INT_TO_FLOAT)
def logsumexp(self: TensorLikeType, dim: DimsType, keepdim: bool=False) -> TensorLikeType:
    if <MASK>:
        dim = (dim,)
    if self.numel() == 0:
        return torch.sum(torch.exp(self), dim, keepdim).log()
    maxes = torch.amax(torch.real(self), dim, keepdim=True)
    maxes = torch.masked_fill(maxes, maxes.abs() == float('inf'), 0)
    maxes_squeezed = maxes if keepdim else torch.squeeze(maxes, dim)
    result = torch.sum(torch.exp(self - maxes), dim, keepdim)
    return result.log().add(maxes_squeezed)

def autoDiffErrorMessage(self, should_autodiff_node, nodes_not_in_diff_graph, fusion_nodes_not_found, non_fusible_nodes_being_fused, fusion_nodes_found, nodes_in_diff_graph):
    err_msg = "\nFailure in testing nodes' autodifferentiation. "
    if should_autodiff_node:
        err_msg += 'One or more nodes were expected to be autodiffed, but were not found in specified fusible/nonfusible DifferentiableGraph groups. \nSpecifically:'
        diff_nodes_missing = []
        diff_nodes_in_fusion = []
        fusion_nodes_missing = []
        fusion_nodes_in_diff = []
        for node in nodes_not_in_diff_graph:
            if node in non_fusible_nodes_being_fused:
                diff_nodes_in_fusion.append(node)
            else:
                diff_nodes_missing.append(node)
        for node in fusion_nodes_not_found:
            if node in nodes_in_diff_graph:
                fusion_nodes_in_diff.append(node)
            else:
                fusion_nodes_missing.append(node)
        if len(diff_nodes_missing) > 0:
            err_msg += f'\n  {diff_nodes_missing} were not in one of the DifferentiableGraphs when they were expected to be. Did you intend for these nodes to be autodiffed? If not, remove them from the list of nonfusible nodes.'
        if len(diff_nodes_in_fusion) > 0:
            err_msg += f'\n  {diff_nodes_in_fusion} were found in one of the FusionGroups when they were expected to be just in a DifferentiableGraph. If it was intended for these nodes to be in FusionGroups, reclassify these nodes as fusible nodes. If these nodes were not intended to be fused, your autodifferentiation logic might be wrong.'
        if len(fusion_nodes_missing) > 0:
            err_msg += f"\n  {fusion_nodes_missing} were not in one of the FusionGroups of the DifferentiableGraphs when they were expected to be. They were also not found in an outer DifferentiableGraph. Did you intend for these nodes to be autodifferentiated? If not, you should remove these nodes from the test's fusible nodes. Otherwise your autodifferentiation logic might be wrong."
        if len(fusion_nodes_in_diff) > 0:
            err_msg += f"\n  {fusion_nodes_in_diff} were not in one of the FusionGroups of the DifferentiableGraphs when they were expected to be, instead they were found just in an outer DifferentiableGraph. Did you intend for these nodes to be fused? If not, you should move these nodes into the test's nonfusible nodes. Otherwise your autodifferentiation logic might be wrong."
    else:
        err_msg += 'One or more nodes were not expected to be autodiffed but were found in a DifferentiableGraph or in a FusionGroup of a DifferentiableGraph. Did you intend for these nodes to be autodiffed? If so, change this test to expect autodifferentiation. \nSpecifically:'
        if <MASK>:
            err_msg += f'\n  {fusion_nodes_found} were not expected to be in one of the DifferentiableGraphs, but appeared in a FusionGroup of a DifferentiableGraph. '
        if len(nodes_in_diff_graph) > 0:
            err_msg += f'\n  {nodes_in_diff_graph} were not expected to be in one of the DifferentiableGraphs but were.'
    return err_msg

