def signature_str_pyi_vararg(self, *, skip_outputs: bool=False) -> str | None:
    args = self.arguments(skip_outputs=skip_outputs)
    schema_formals: list[str] = [a.argument_str_pyi(method=self.method) for a in args]
    num_args = self.arguments_count()
    if num_args == 0:
        return None
    num_positionalargs = len(self.input_args)
    vararg_type = args[0].type
    if <MASK>:
        return None
    assert isinstance(vararg_type, ListType)
    schema_formals[0] = '*' + args[0].name + ': ' + argument_type_str_pyi(vararg_type.elem)
    returns_str = returns_str_pyi(self)
    if self.method:
        schema_formals.insert(0, 'self')
    return format_function_signature(self.name, schema_formals, returns_str)

@register.filter('timezone')
def do_timezone(value, arg):
    """
    Convert a datetime to local time in a given time zone.

    The argument must be an instance of a tzinfo subclass or a time zone name.

    Naive datetimes are assumed to be in local time in the default time zone.
    """
    if not isinstance(value, datetime):
        return ''
    try:
        if timezone.is_naive(value):
            default_timezone = timezone.get_default_timezone()
            value = timezone.make_aware(value, default_timezone)
    except Exception:
        return ''
    if <MASK>:
        tz = arg
    elif isinstance(arg, str):
        try:
            tz = zoneinfo.ZoneInfo(arg)
        except zoneinfo.ZoneInfoNotFoundError:
            return ''
    else:
        return ''
    result = timezone.localtime(value, tz)
    result = datetimeobject(result.year, result.month, result.day, result.hour, result.minute, result.second, result.microsecond, result.tzinfo)
    result.convert_to_local_time = False
    return result

