def register_flop_formula(targets, get_raw=False) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:

    def register_fun(flop_formula: Callable[_P, _T]) -> Callable[_P, _T]:
        if not get_raw:
            flop_formula = shape_wrapper(flop_formula)

        def register(target):
            if not isinstance(target, torch._ops.OpOverloadPacket):
                raise ValueError(f'register_flop_formula(targets): expected each target to be OpOverloadPacket (i.e. torch.ops.mylib.foo), got {target} which is of type {type(target)}')
            if <MASK>:
                raise RuntimeError(f'duplicate registrations for {target}')
            flop_registry[target] = flop_formula
        torch.utils._pytree.tree_map_(register, targets)
        return flop_formula
    return register_fun

def assert_array_compare(comparison, x, y, err_msg='', verbose=True, header='', precision=6, equal_nan=True, equal_inf=True, *, strict=False):
    __tracebackhide__ = True
    from torch._numpy import all, array, asarray, bool_, inf, isnan, max
    x = asarray(x)
    y = asarray(y)

    def array2string(a):
        return str(a)
    (ox, oy) = (x, y)

    def func_assert_same_pos(x, y, func=isnan, hasval='nan'):
        """Handling nan/inf.

        Combine results of running func on x and y, checking that they are True
        at the same locations.

        """
        __tracebackhide__ = True
        x_id = func(x)
        y_id = func(y)
        if (x_id == y_id).all().item() is not True:
            msg = build_err_msg([x, y], err_msg + f'\nx and y {hasval} location mismatch:', verbose=verbose, header=header, names=('x', 'y'), precision=precision)
            raise AssertionError(msg)
        if isinstance(x_id, bool) or x_id.ndim == 0:
            return bool_(x_id)
        elif isinstance(y_id, bool) or y_id.ndim == 0:
            return bool_(y_id)
        else:
            return y_id
    try:
        if strict:
            cond = x.shape == y.shape and x.dtype == y.dtype
        else:
            cond = (x.shape == () or y.shape == ()) or x.shape == y.shape
        if not cond:
            if x.shape != y.shape:
                reason = f'\n(shapes {x.shape}, {y.shape} mismatch)'
            else:
                reason = f'\n(dtypes {x.dtype}, {y.dtype} mismatch)'
            msg = build_err_msg([x, y], err_msg + reason, verbose=verbose, header=header, names=('x', 'y'), precision=precision)
            raise AssertionError(msg)
        flagged = bool_(False)
        if equal_nan:
            flagged = func_assert_same_pos(x, y, func=isnan, hasval='nan')
        if equal_inf:
            flagged |= func_assert_same_pos(x, y, func=lambda xy: xy == +inf, hasval='+inf')
            flagged |= func_assert_same_pos(x, y, func=lambda xy: xy == -inf, hasval='-inf')
        if flagged.ndim > 0:
            (x, y) = (x[~flagged], y[~flagged])
            if x.size == 0:
                return
        elif flagged:
            return
        val = comparison(x, y)
        if isinstance(val, bool):
            cond = val
            reduced = array([val])
        else:
            reduced = val.ravel()
            cond = reduced.all()
        if not cond:
            n_mismatch = reduced.size - int(reduced.sum(dtype=intp))
            n_elements = flagged.size if flagged.ndim != 0 else reduced.size
            percent_mismatch = 100 * n_mismatch / n_elements
            remarks = [f'Mismatched elements: {n_mismatch} / {n_elements} ({percent_mismatch:.3g}%)']
            with contextlib.suppress(TypeError, RuntimeError):
                error = abs(x - y)
                if <MASK>:
                    error2 = abs(y - x)
                    np.minimum(error, error2, out=error)
                max_abs_error = max(error)
                remarks.append('Max absolute difference: ' + array2string(max_abs_error.item()))
                nonzero = bool_(y != 0)
                if all(~nonzero):
                    max_rel_error = array(inf)
                else:
                    max_rel_error = max(error[nonzero] / abs(y[nonzero]))
                remarks.append('Max relative difference: ' + array2string(max_rel_error.item()))
            err_msg += '\n' + '\n'.join(remarks)
            msg = build_err_msg([ox, oy], err_msg, verbose=verbose, header=header, names=('x', 'y'), precision=precision)
            raise AssertionError(msg)
    except ValueError:
        import traceback
        efmt = traceback.format_exc()
        header = f'error during assertion:\n\n{efmt}\n\n{header}'
        msg = build_err_msg([x, y], err_msg, verbose=verbose, header=header, names=('x', 'y'), precision=precision)
        raise ValueError(msg)

@classmethod
def call_nn_parameter(cls, tx, data=None, requires_grad=True):
    """A call to torch.nn.Parameter() gets lifted to before the graph"""
    if tx.export:
        unimplemented_v2(gb_type='Attempted to use `torch.nn.Parameter()` with export', context='', explanation='Dynamo does not support this.', hints=['Do not use `torch.nn.Parameter()` with export.', *graph_break_hints.SUPPORTABLE])
    if isinstance(requires_grad, variables.VariableTracker):
        try:
            requires_grad = requires_grad.as_python_constant()
        except NotImplementedError:
            unimplemented_v2(gb_type='non-constant `requires_grad` argument to `torch.nn.Parameter`', context=f'requires_grad={requires_grad}', explanation='Dynamo does not support this.', hints=['Change `requires_grad` to be a bool.', *graph_break_hints.USER_ERROR])
    if not isinstance(data, variables.TensorVariable):
        unimplemented_v2(gb_type='`torch.nn.Parameter()` with unsupported data type', context=f'data={data}', explanation='Called `torch.nn.Parameter()` with non-Tensor argument.', hints=['Ensure the argument to `torch.nn.Parameter()` is a `torch.Tensor`.', *graph_break_hints.USER_ERROR])
    if <MASK>:
        return cls._nn_param_via_prefix_insert(tx, data, requires_grad)
    if config.graph_break_on_nn_param_ctor:
        unimplemented_v2(gb_type='Attempted to use `torch.nn.Parameter()` constructor with Dynamo', context='', explanation='Dynamo does not support this', hints=['Try to construct `torch.nn.Parameter()` outside the compiled region.', 'If this is not possible, turn `graph_break_on_nn_param_ctor` off', *graph_break_hints.SUPPORTABLE])
    if isinstance(data, TensorWithTFOverrideVariable) or is_traceable_wrapper_subclass_type(data.class_type):
        unimplemented_v2(gb_type='Attempted to use torch.nn.Parameter constructor with tensor subclass', context=str(data), explanation='Dynamo does not support this.', hints=[*graph_break_hints.SUPPORTABLE])
    if not can_convert_to_tracable_parameter():
        unimplemented_v2(gb_type='`torch.nn.Parameter`: cannot convert to traceable tracable', context='', explanation='convert_tracable_parameter is set to False.', hints=['Check usage of context manager: do_not_convert_to_tracable_parameter', *graph_break_hints.DIFFICULT])
    try:
        shape = tuple(data.var_getattr(tx, 'shape').as_python_constant())
        dtype = data.var_getattr(tx, 'dtype').as_python_constant()
        device = data.var_getattr(tx, 'device').as_python_constant()
    except NotImplementedError as e:
        unimplemented_v2(gb_type='`torch.nn.Parameter` with non-constant Tensor attributes', context=f'data={data}', explanation='Dynamo does not support this.', hints=["Ensure the Tensor argument's shape, dtype, and device are correct.", *graph_break_hints.USER_ERROR], from_exc=e)
    placeholder = tx.output.synthetic_graph_input(new_parameter_placeholder, [shape, dtype, device, requires_grad])
    if data.requires_grad:
        data = data.call_method(tx, 'detach', [], {})
    from .builder import wrap_fx_proxy
    result = wrap_fx_proxy(tx, tx.output.create_proxy('call_function', tracable_create_parameter, (data.as_proxy(), placeholder.as_proxy()), {}), source=placeholder.source)
    assert isinstance(result, variables.TensorVariable)
    result.class_type = torch.nn.Parameter
    result.has_grad_fn = False
    return result

def _check_list_display_links(self, obj):
    """Check that list_display_links is a unique subset of list_display."""
    from django.contrib.admin.options import ModelAdmin
    if <MASK>:
        return []
    elif not isinstance(obj.list_display_links, (list, tuple)):
        return must_be('a list, a tuple, or None', option='list_display_links', obj=obj, id='admin.E110')
