def generate_input_output_runtime_checks(self):
    """
        In debug_compile mode, we generate checks to ensure the dtype/shape/stride/device of each
        real input/output tensor match ones provided at compile time via sample
        input/output.
        """

    def gen_check(handle_kind, idx, name, tensor):
        self.prefix.writeline(f'ConstantHandle {name} = ConstantHandle({handle_kind}[{idx}]);')
        self.codegen_tensor_dtype_var_decl(self.prefix, name)
        expected_dtype_name = DTYPE_TO_ATEN[tensor.dtype]
        dtype_str = str(tensor.dtype).split('.')[-1]
        self.prefix.splice(f'
                    int32_t {name}_expected_dtype = aoti_torch_dtype_{dtype_str}();
                    if ({name}_expected_dtype != {name}_dtype) {{
                        std::stringstream ss;
                        ss << "{handle_kind}[{idx}]: unmatched dtype, "
                           << "expected: " << {name}_expected_dtype << "({expected_dtype_name}), "
                           << "but got: " << {name}_dtype << "\n";
                        throw std::runtime_error(ss.str());
                    }}
                ')
        self.codegen_input_size_var_decl(self.prefix, name)
        for (dim_idx, d) in enumerate(tensor.get_size()):
            if isinstance(d, (int, sympy.Integer)):
                self.prefix.splice(f'
                            if ({d} != {name}_size[{dim_idx}]) {{
                                std::stringstream ss;
                                ss << "{handle_kind}[{idx}]: unmatched dim value at {dim_idx}, "
                                   << "expected: {d}, " << "but got: " << {name}_size[{dim_idx}]
                                   << "\n";
                                throw std::runtime_error(ss.str());
                            }}
                        ')
            else:
                from torch.utils._sympy.value_ranges import bound_sympy
                sym_range = bound_sympy(d, V.graph.sizevars.shape_env.var_to_range)
                if not math.isinf(sym_range.lower):
                    self.prefix.splice(f'
                                if ({name}_size[{dim_idx}] < {sym_range.lower}) {{
                                    std::stringstream ss;
                                    ss << "{handle_kind}[{idx}]: dim value is too small at {dim_idx}, "
                                       << "expected it to be >= {sym_range.lower}, " << "but got: "
                                       << {name}_size[{dim_idx}] << "\n";
                                    throw std::runtime_error(ss.str());
                                }}
                            ')
                if not math.isinf(sym_range.upper):
                    max_long_long = ctypes.c_longlong(2 ** 63 - 1).value
                    upper_bound = min(sym_range.upper, max_long_long)
                    self.prefix.splice(f'
                                if ({name}_size[{dim_idx}] > {upper_bound}) {{
                                    std::stringstream ss;
                                    ss << "{handle_kind}[{idx}]: dim value is too large at {dim_idx}, "
                                       << "expected to be <= {upper_bound}, " << "but got: "
                                       << {name}_size[{dim_idx}] << "\n";
                                    throw std::runtime_error(ss.str());
                                }}
                            ')
        self.codegen_input_stride_var_decl(self.prefix, name)
        for (stride_idx, s) in enumerate(tensor.get_stride()):
            if not isinstance(s, (int, sympy.Integer)):
                continue
            self.prefix.splice(f'
                        if ({s} != {name}_stride[{stride_idx}]) {{
                            std::stringstream ss;
                            ss << "{handle_kind}[{idx}]: unmatched stride value at {stride_idx}, "
                               << "expected: {s}, " << "but got: " << {name}_stride[{stride_idx}]
                               << "\n";
                            throw std::runtime_error(ss.str());
                        }}
                    ')
        if isinstance(tensor, ir.TensorBox):
            tensor_device = tensor.get_device()
            if <MASK>:
                expected_device_type = DEVICE_TO_INT.get(tensor_device.type)
                if expected_device_type is not None:
                    self.codegen_input_device_type_var_decl(self.prefix, name)
                    device_type_str = str(tensor_device.type)
                    self.prefix.splice(f'
                                int32_t {name}_expected_device_type = {expected_device_type};
                                if ({name}_expected_device_type != {name}_device_type) {{
                                    std::stringstream ss;
                                    ss << "{handle_kind}[{idx}]: unmatched device type, "
                                    << "expected: " << {name}_expected_device_type << "{expected_device_type}({device_type_str}), "
                                    << "but got: " << {name}_device_type << "\n";
                                    throw std::runtime_error(ss.str());
                                }}
                            ')
    for (idx, (name, tensor)) in enumerate(V.graph.graph_inputs.items()):
        self.prefix.splice(f'
                AOTI_NOINLINE static void check_input_{idx}(
                    AtenTensorHandle* input_handles
                ) {{
                ')
        with self.prefix.indent():
            gen_check('input_handles', idx, name, tensor)
        self.prefix.writeline('}')
    self.prefix.splice('
            static bool _check_aoti_runtime_check_inputs_env() {
                const static char* env_var_value = getenv("AOTI_RUNTIME_CHECK_INPUTS");
                const static bool result = env_var_value != nullptr && env_var_value[0] != '0';
                return result;
            }

            AOTI_NOINLINE static void __check_inputs_outputs(
                AtenTensorHandle* input_handles,
                AtenTensorHandle* output_handles) {
                if (!_check_aoti_runtime_check_inputs_env()){
                    return;
                }
            ')
    with self.prefix.indent():
        for idx in range(len(V.graph.graph_inputs)):
            self.prefix.writeline(f'check_input_{idx}(input_handles);')
    self.prefix.writeline('}')

def _add_type_spec(cls):
    """Creates a nested TypeSpec class for tf.ExtensionType subclass `cls`."""
    spec_name = cls.__name__ + '.Spec'
    spec_qualname = cls.__qualname__ + '.Spec'
    spec_dict = {'value_type': cls, '__module__': cls.__module__}
    user_spec = cls.__dict__.get('Spec', None)
    if <MASK>:
        for (name, value) in user_spec.__dict__.items():
            if extension_type_field.ExtensionTypeField.is_reserved_name(name):
                raise ValueError(f"TypeSpec {spec_qualname} uses reserved name '{name}'.")
            if cls._tf_extension_type_has_field(name):
                raise ValueError(f"TypeSpec {spec_qualname} defines a variable '{name}' which shadows a field in {cls.__qualname__}")
            if name in ('__module__', '__dict__', '__weakref__'):
                continue
            spec_dict[name] = value
    if issubclass(cls, BatchableExtensionType):
        type_spec_base = BatchableExtensionTypeSpec
        if hasattr(cls, '__batch_encoder__') and '__batch_encoder__' not in spec_dict:
            spec_dict['__batch_encoder__'] = cls.__batch_encoder__
    else:
        type_spec_base = ExtensionTypeSpec
        if hasattr(cls, '__batch_encoder__') or '__batch_encoder__' in spec_dict:
            raise ValueError('__batch_encoder__ should only be defined for BatchableExtensionType classes.')
    spec = type(spec_name, (type_spec_base,), spec_dict)
    spec.__qualname__ = spec_qualname
    setattr(cls, 'Spec', spec)
    if '__init__' in spec.__dict__:
        _wrap_user_constructor(spec)
    else:
        _build_spec_constructor(spec)
    cls.__abstractmethods__ -= {'_type_spec'}
    if '__name__' in cls.__dict__:
        type_spec_registry.register(cls.__dict__['__name__'] + '.Spec')(spec)

def _serialize(self):
    if <MASK>:
        return (self._shape, self._dtype, self._ragged_rank, self._row_splits_dtype)
    else:
        return (self._shape, self._dtype, self._ragged_rank, self._row_splits_dtype, self._flat_values_spec)

def clip(x: Array, /, min: float | Array | None=None, max: float | Array | None=None) -> Array:
    """
    Array API compatibility wrapper for clip().

    See the corresponding documentation in the array library and/or the array API
    specification for more details.
    """

    def _isscalar(a: float | Array | None, /) -> TypeIs[float | None]:
        return a is None or isinstance(a, (int, float))
    min_shape = () if _isscalar(min) else min.shape
    max_shape = () if _isscalar(max) else max.shape
    result_shape = np.broadcast_shapes(x.shape, min_shape, max_shape)
    if min is not None:
        min = da.broadcast_to(da.asarray(min), result_shape)
    if max is not None:
        max = da.broadcast_to(da.asarray(max), result_shape)
    if min is None and max is None:
        return da.positive(x)
    if min is None:
        return astype(da.minimum(x, max), x.dtype)
    if <MASK>:
        return astype(da.maximum(x, min), x.dtype)
    return astype(da.minimum(da.maximum(x, min), max), x.dtype)

@classmethod
def create(cls, kernel: _OpOverloads, *args: Any, **kwargs: Any) -> FallbackKernel:
    """Create an instance of FallbackKernel from an _OpOverloads"""
    fake_incorrect_kernels = (aten._fused_moving_avg_obs_fq_helper_functional,)
    if kernel not in fake_incorrect_kernels:
        context = cast(AbstractContextManager[None], V.graph.fake_mode)
    else:
        context = nullcontext()
    with context:
        (example_output, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings) = cls.process_kernel(kernel, *args, **kwargs)
    has_unaligned_input = any((is_unaligned(arg) for arg in tensor_args))
    device = cls.find_device(tensor_args, example_output)
    if not device and isinstance(kernel, torch._higher_order_ops.torchbind.CallTorchBind):
        device = torch.device('cpu')
    if example_output is None:
        packed = cls(NoneLayout(device=device), kernel, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings=unbacked_bindings)
    else:
        assert device, 'Not sure where to find device info'
        packed = cls(MultiOutputLayout(device=device), kernel, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings=unbacked_bindings)

    def generate_output(output: Any, indices: list[tuple[Any, int]]) -> Any:
        if isinstance(output, (list, tuple)):
            return type(output)((generate_output(output[i], indices + [(type(output), i)]) for i in range(len(output))))
        elif isinstance(output, dict):
            return {key: generate_output(val, indices + [(type(output), key)]) for (key, val) in output.items()}
        elif isinstance(output, torch.Tensor):
            buf = MultiOutput(cls.tensor_to_layout(output), packed, indices)
            if <MASK>:
                V.graph.unaligned_buffers.add(buf.name)
            return buf
        elif isinstance(output, int):
            return output
        elif isinstance(output, torch.SymInt):
            return output.node.expr
        else:
            assert output is None, f'FallbackKernel output type {type(output)} is not supported'
            return None
    outputs = generate_output(example_output, [])
    if isinstance(outputs, (list, tuple)):
        packed.outputs = outputs
    elif isinstance(outputs, dict):
        packed.outputs = tuple(outputs)
    else:
        packed.outputs = [outputs]
    return outputs

def encode_arg(arg, path):
    """A representation for this argument, for converting into signatures."""
    if isinstance(arg, tensor_lib.Tensor):
        user_specified_name = None
        try:
            user_specified_name = compat.as_str(arg.op.get_attr('_user_specified_name'))
        except (ValueError, AttributeError):
            pass
        if path and user_specified_name and (user_specified_name != path[0]):
            name = user_specified_name
        else:
            name = tensor_lib.sanitize_spec_name('_'.join((str(p) for p in path)))
        return tensor_lib.TensorSpec(arg.shape, arg.dtype, name)
    if isinstance(arg, resource_variable_ops.ResourceVariable):
        return trace_type.from_value(arg, signature_context)
    if isinstance(arg, composite_tensor.CompositeTensor):
        return arg._type_spec
    if <MASK>:
        return arg
    return UnknownArgument()

def as_exact_strides(self, exact_strides: Sequence[_IntLike], allow_padding: bool=False) -> FixedLayout:
    new_stride = exact_strides
    if <MASK>:
        new_stride = self._pad_strides(new_stride, self.size, self.dtype)
    return FixedLayout(self.device, self.dtype, self.size, new_stride, self.offset, self.is_pinned)

def __init__(self, layout: OutputSpec, kernel: _OpOverloads, tensor_args: Sequence[IRNode], nontensor_args: Sequence[Any], unflatten_args: Callable[..., Any], kwargs: Optional[dict[str, Any]]=None, *, unbacked_bindings: Optional[dict[sympy.Symbol, pytree.KeyPath]]=None) -> None:
    super().__init__(layout, tuple(tensor_args), tuple(nontensor_args), op_overload=kernel)
    self.use_runtime_dispatch = False
    self.unbacked_bindings = unbacked_bindings or {}
    assert isinstance(kernel, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)), f'Fails to create FallbackKernel for {kernel}: {type(kernel)} not supported'
    self.op_overload = kernel
    self.unflatten_args = unflatten_args
    self.kwargs = {} if kwargs is None else kwargs
    assert self.python_kernel_name is not None
    V.graph.warn_fallback(self.python_kernel_name)
    self.alias_names: list[str] = []
    self.mutation_names: list[str] = []
    if isinstance(self.op_overload, torch._ops.HigherOrderOperator):
        return
    if '_c10d_functional' in self.op_overload.name():
        return
    schema = self.op_overload._schema
    if torch._library.utils.mutates_and_returns_first_arg(self.op_overload):
        self.mutation_names.append(tensor_args[0].get_name())
        return
    if schema.is_mutable and (not can_auto_functionalize(kernel)):
        raise NotImplementedError(f"NYI: Can't generate FallbackKernel for {kernel}")
    (args, kwargs) = self.unflatten_args(self.inputs, self.constant_args)

    def handle_aliasing_and_mutation(info: torch._C.Argument, arg: Any) -> None:
        if isinstance(info.type, torch.ListType):
            assert isinstance(arg, (list, tuple)), type(arg)
        if library_utils.is_tensor_like_type(info.type):
            assert not isinstance(arg, (tuple, list))
        if arg is None:
            return
        if info.alias_info is None:
            return

        def add_alias(t: IRNode) -> None:
            self.alias_names.append(t.get_name())
            assert info.alias_info is not None
            if <MASK>:
                self.mutation_outputs.append(MutationOutput(NoneLayout(device=t.get_device()), t, self))
        if library_utils.is_tensorlist_like_type(info.type):
            if arg is not None:
                for optional_tensor_arg in arg:
                    add_alias(optional_tensor_arg)
        else:
            assert library_utils.is_tensor_like_type(info.type)
            add_alias(arg)
    for (info, arg) in torch._library.utils.zip_schema(schema, args, kwargs):
        handle_aliasing_and_mutation(info, arg)

def __contains__(self, element: Any, /) -> bool:
    """Check if `element` is present in tensor

        Args:
            element (Tensor or scalar): element to be checked
                for presence in current tensor"
        """
    if has_torch_function_unary(self):
        return handle_torch_function(Tensor.__contains__, (self,), self, element)
    if <MASK>:
        return bool((element == self).any().item())
    raise RuntimeError(f'Tensor.__contains__ only supports Tensor or scalar, but you passed in a {type(element)}.')

def generate_output(self, output_args: Argument, *, descs: Optional[Any]=None) -> str:
    """
        Given the output arguments, generates the return statement of the FX function.
        Note: The returned statement should not be indented.
        """
    if <MASK>:
        return self._format_multiline_container(output_args, descs, 'return ')
    else:
        return f'return {repr(output_args)}'

