def _lower_dynamic_weighted_ref_functional(model: GraphModule, qconfig_map: dict[str, QConfigAny]):
    """
    Traverse the graph and replace functional reference patterns with their dynamically
    quantized versions.
    Examples:
    quantize_per_tensor_dynamic - dequantize - functional linear --> linear_dynamic
    to(torch.float16) - dequantize - functional linear --> linear_dynamic_fp16
    """
    modules = dict(model.named_modules(remove_duplicate=False))
    for n in reversed(model.graph.nodes):
        func_node = n
        if func_node.op == 'call_function' and func_node.target == F.relu or (func_node.op == 'call_module' and type(modules[str(func_node.target)]) is torch.nn.ReLU):
            relu_node = func_node
            func_node = relu_node.args[0]
        else:
            relu_node = None
        if should_skip_lowering(func_node, qconfig_map):
            continue
        if func_node.op != 'call_function' or func_node.target not in DYNAMIC_LOWER_FUNCTIONAL_MAP:
            continue
        (input_dq_node, weight_dq_node, *remaining_func_args) = func_node.args
        if input_dq_node.op != 'call_method' or input_dq_node.target != 'dequantize' or weight_dq_node.op != 'call_method' or (weight_dq_node.target != 'dequantize'):
            continue
        input_dynamic_q_node = input_dq_node.args[0]
        if input_dynamic_q_node.op != 'call_function' or input_dynamic_q_node.target != torch.quantize_per_tensor_dynamic:
            continue
        reduce_range_node = None
        (pattern_input, activation_dtype, reduce_range_node) = input_dynamic_q_node.args
        is_fp16 = activation_dtype == torch.float16
        is_int8 = activation_dtype in [torch.quint8, torch.qint8]
        if not is_int8 and (not is_fp16):
            continue
        quantized_weight = weight_dq_node.args[0]
        weight_dtype = quantized_weight.args[-1]
        dynamic_quant_dtype_key = (activation_dtype, weight_dtype)
        if dynamic_quant_dtype_key not in DYNAMIC_LOWER_FUNCTIONAL_MAP[func_node.target]:
            print(f"Didn't find dtype combination {dynamic_quant_dtype_key} during dynamic quantized op lowering for {func_node.target}")
            continue
        (q_func, q_relu_func) = DYNAMIC_LOWER_FUNCTIONAL_MAP[func_node.target][dynamic_quant_dtype_key]
        if q_func is None or q_relu_func is None:
            print(f"Didn't find corresponding quantized function or quantized relu function for {func_node.target}, {dynamic_quant_dtype_key}")
            continue
        prepack_args = [quantized_weight] + remaining_func_args
        prepack_kwargs = {}
        if func_node.target == F.linear:
            prepack_op = get_linear_prepack_op_for_dtype(weight_dtype)
            kwargs = func_node.kwargs.copy()
            if 'bias' in kwargs:
                prepack_kwargs['B'] = kwargs['bias']
                del kwargs['bias']
                func_node.kwargs = kwargs
        elif func_node.target in CONV_FUNCTIONAL_OPS:
            prepack_op = get_qconv_prepack_op(func_node.target)
            if func_node.target == F.conv1d:
                for i in [2, 3, 4]:
                    if len(prepack_args) > i and isinstance(prepack_args[i], int):
                        prepack_args[i] = (prepack_args[i],)
        else:
            raise ValueError(f"Lowering is not supported for op '{func_node.target}'")
        with model.graph.inserting_before(func_node):
            packed_weight = model.graph.create_node('call_function', prepack_op, tuple(prepack_args), prepack_kwargs)
        func_node.target = q_relu_func if relu_node is not None else q_func
        if <MASK>:
            func_node.args = (pattern_input, packed_weight, reduce_range_node)
        else:
            func_node.args = (pattern_input, packed_weight)
        if relu_node is not None:
            relu_node.replace_all_uses_with(func_node)
        if relu_node is not None:
            model.graph.erase_node(relu_node)

def visualize_rec(graph, value_map, name_prefix, pb_graph, executors_it=None):
    """Recursive part of visualize (basically skips setting up the input and output nodes)."""

    def inline_graph(subgraph, name, node):
        rec_value_map = {inp.unique(): value_map[val.unique()] for (inp, val) in zip(subgraph.inputs(), node.inputs())}
        visualize_rec(graph=subgraph, value_map=rec_value_map, name_prefix=name, pb_graph=pb_graph)
        for (out, val) in zip(subgraph.outputs(), node.outputs()):
            value_map[val.unique()] = rec_value_map[out.unique()]
    op_id_counter: defaultdict[str, int] = defaultdict(int)

    def name_for(node):
        kind = node.kind()[node.kind().index('::') + 2:]
        op_id_counter[kind] += 1
        return (kind, name_prefix + kind + '_' + str(op_id_counter[kind]))

    def add_fusion_group(node):
        (op, name) = name_for(node)
        inline_graph(node.g('Subgraph'), name + '/', node)

    def add_graph_executor(node):
        (op, name) = name_for(node)
        if <MASK>:
            add_node(node)
        else:
            ge = next(executors_it)
            visualize_graph_executor(ge, name + '/', pb_graph, partial(inline_graph, node=node))

    def add_node(node):
        if node.kind() == 'prim::FusionGroup':
            return add_fusion_group(node)
        elif node.kind() == 'prim::GraphExecutor':
            return add_graph_executor(node)
        (op, name) = name_for(node)
        pb_node = pb_graph.node.add(op=op, name=name)
        for value in node.inputs():
            pb_node.input.append(value_map[value.unique()])
        for (i, value) in enumerate(node.outputs()):
            value_map[value.unique()] = name + ':' + str(i)
    for node in graph.nodes():
        add_node(node)

@parameterized.named_parameters(('_method', 'method'), ('_function', 'function'), ('_lambda_function', 'lambda_function'))
def testInputSignaturePartialFuncMissingTensorSpecs(self, func_type):
    if func_type == 'method':

        class MyModule(module.Module):

            def f(self, arg1, arg2, arg3, arg4=4):
                return arg1 + arg2 + arg3 + arg4
        f = MyModule().f
    elif <MASK>:

        def f(arg1, arg2, arg3, arg4=4):
            return arg1 + arg2 + arg3 + arg4
    else:
        f = lambda arg1, arg2, arg3, arg4=4: arg1 + arg2 + arg3 + arg4
    error_message = 'input_signature missing type constraint'
    tf_func_dec = polymorphic_function.function(input_signature=(tensor_lib.TensorSpec([], dtypes.int32),))
    with self.assertRaisesRegex(TypeError, error_message):
        tf_func_dec(functools.partial(f, 1))(2, 3)
    with self.assertRaisesRegex(TypeError, error_message):
        tf_func_dec(functools.partial(f, arg4=5))(1, 2, 3)
    with self.assertRaisesRegex(TypeError, error_message):
        tf_func_dec(functools.partial(f, 1, arg4=5))(2, 3)
    self.assertAllEqual(tf_func_dec(functools.partial(f, 1, 2, arg4=5))(3), array_ops.constant(11))

def aot_inductor_minifier_wrapper(func: Callable[..., str], exported_program: torch.export.ExportedProgram, *, inductor_configs: dict[str, Any], package_path: Optional[FileLike]=None) -> str:
    from torch._dynamo.debug_utils import AccuracyError
    from torch._dynamo.repro.aoti import dump_to_minify
    from torch._inductor import config
    from torch._inductor.compile_fx import _aoti_flatten_inputs
    use_minifier = config.aot_inductor.dump_aoti_minifier
    gm = exported_program.module(check_guards=False)
    assert isinstance(gm, torch.fx.GraphModule)
    (args, kwargs) = exported_program.example_inputs
    try:
        if use_minifier and config.aot_inductor.repro_level == 3:
            dump_to_minify(exported_program, 'aot_inductor', options=inductor_configs)
        if use_minifier and config.aot_inductor.repro_level == 4:
            gm_copy = copy.deepcopy(gm)
            example_inputs_copy = copy.deepcopy(exported_program.example_inputs)
            config_copy = copy.deepcopy(inductor_configs)
            (flat_example_inputs, config_copy) = _aoti_flatten_inputs(gm_copy, example_inputs_copy[0], example_inputs_copy[1], options=config_copy)
            tuple_inputs = tuple(flat_example_inputs)
            flattened_ep = torch.export.export(gm_copy, tuple_inputs, strict=False)
            func(flattened_ep.module(check_guards=False), tuple_inputs, inductor_configs=config_copy, package_path=package_path, load_and_run=True, check_accuracy='accuracy')
        return func(gm, args, kwargs, inductor_configs=inductor_configs, package_path=package_path, load_and_run=use_minifier)
    except AccuracyError as e:
        dump_to_minify(exported_program, 'aot_inductor_accuracy', command='minify', options=inductor_configs)
        log.warning('Accuracy failed')
        raise e
    except Exception as e:
        if <MASK>:
            command = 'minify'
            if config.aot_inductor.repro_level == 1:
                command = 'run'
            dump_to_minify(exported_program, 'aot_inductor', command=command, options=inductor_configs)
        raise e

def __str__(self) -> str:
    output = f'Graph Count: {self.graph_count}\n'
    output += f'Graph Break Count: {self.graph_break_count}\n'
    output += f'Op Count: {self.op_count}\n'
    output += 'Break Reasons:\n'
    for (idx, break_reason) in enumerate(self.break_reasons):
        output += f'  Break Reason {idx + 1}:\n'
        output += f'    Reason: {break_reason.reason}\n'
        output += '    User Stack:\n'
        for frame_summary in break_reason.user_stack:
            output += f'      {frame_summary}\n'
    if <MASK>:
        output += 'Ops per Graph:\n'
        for (idx, ops) in enumerate(self.ops_per_graph):
            output += f'  Ops {idx + 1}:\n'
            for op in ops:
                output += f'    {op}\n'
    if self.out_guards is not None:
        output += 'Out Guards:\n'
        for (i, guard) in enumerate(self.out_guards):
            output += f'  Guard {i + 1}:\n'
            output += f'    {str(guard)}'
    if self.compile_times is not None:
        output += f'Compile Times: {self.compile_times}\n'
    return output

