def _constant_value(ragged_factory, inner_factory, pylist, dtype, ragged_rank, inner_shape):
    """Constructs a constant RaggedTensor or RaggedTensorValue.

  Args:
    ragged_factory: A factory function with the signature:
      `ragged_factory(values, row_splits)`
    inner_factory: A factory function with the signature: `inner_factory(pylist,
      dtype, shape, name)`
    pylist: A nested `list`, `tuple` or `np.ndarray`.
    dtype: Data type for returned value.
    ragged_rank: Ragged rank for returned value.
    inner_shape: Inner value shape for returned value.

  Returns:
    A value returned by `ragged_factory` or `inner_factory`.

  Raises:
    ValueError: If the scalar values in `pylist` have inconsistent nesting
      depth; or if ragged_rank or inner_shape are incompatible with `pylist`.
  """
    if ragged_tensor.is_ragged(pylist):
        raise TypeError('pylist may not be a RaggedTensor or RaggedTensorValue.')
    if not isinstance(pylist, (list, tuple)) and np.ndim(pylist) == 0:
        if ragged_rank is not None and ragged_rank != 0:
            raise ValueError('Invalid pylist=%r: incompatible with ragged_rank=%d' % (pylist, ragged_rank))
        if inner_shape is not None and inner_shape:
            raise ValueError('Invalid pylist=%r: incompatible with dim(inner_shape)=%d' % (pylist, len(inner_shape)))
        return inner_factory(pylist, dtype, ())
    if ragged_rank is not None and ragged_rank < 0:
        raise ValueError('Invalid ragged_rank=%r: must be nonnegative' % ragged_rank)
    (scalar_depth, max_depth) = _find_scalar_and_max_depth(pylist)
    if scalar_depth is not None:
        if max_depth > scalar_depth:
            raise ValueError('Invalid pylist=%r: empty list nesting is greater than scalar value nesting' % pylist)
        if ragged_rank is not None and max_depth < ragged_rank:
            raise ValueError(f'Invalid pylist={pylist}, max depth smaller than ragged_rank={ragged_rank}')
    if inner_shape is not None and ragged_rank is not None:
        expected_depth = ragged_rank + len(inner_shape) + 1
        if scalar_depth is not None and expected_depth != scalar_depth or (scalar_depth is None and expected_depth < max_depth):
            raise ValueError('Invalid pylist=%r: incompatible with ragged_rank=%d and dim(inner_shape)=%d' % (pylist, ragged_rank, len(inner_shape)))
    if <MASK>:
        return inner_factory(pylist, dtype, inner_shape)
    if inner_shape is None:
        if ragged_rank is None:
            inner_shape = ()
        else:
            inner_shape = _default_inner_shape_for_pylist(pylist, ragged_rank)
    if ragged_rank is None:
        if scalar_depth is None:
            ragged_rank = max(1, max_depth - 1)
        else:
            ragged_rank = max(1, scalar_depth - 1 - len(inner_shape))
    nested_splits = []
    values = pylist
    for dim in range(ragged_rank):
        nested_splits.append([0])
        concatenated_values = []
        for row in values:
            nested_splits[dim].append(nested_splits[dim][-1] + len(row))
            concatenated_values.extend(row)
        values = concatenated_values
    values = inner_factory(values, dtype=dtype, shape=(len(values),) + inner_shape, name='values')
    for row_splits in reversed(nested_splits):
        values = ragged_factory(values, row_splits)
    return values

def get_ema_multi_avg_fn(decay=0.999):
    """Get the function applying exponential moving average (EMA) across multiple params."""
    if decay < 0.0 or decay > 1.0:
        raise ValueError(f'Invalid decay value {decay} provided. Please provide a value in [0,1] range.')

    @torch.no_grad()
    def ema_update(ema_param_list: PARAM_LIST, current_param_list: PARAM_LIST, _):
        if <MASK>:
            torch._foreach_lerp_(ema_param_list, current_param_list, 1 - decay)
        else:
            for (p_ema, p_model) in zip(ema_param_list, current_param_list):
                p_ema.copy_(p_ema * decay + p_model * (1 - decay))
    return ema_update

@array_function_dispatch(_sort_complex)
def sort_complex(a):
    """
    Sort a complex array using the real part first, then the imaginary part.

    Parameters
    ----------
    a : array_like
        Input array

    Returns
    -------
    out : complex ndarray
        Always returns a sorted complex array.

    Examples
    --------
    >>> import numpy as np
    >>> np.sort_complex([5, 3, 6, 2, 1])
    array([1.+0.j, 2.+0.j, 3.+0.j, 5.+0.j, 6.+0.j])

    >>> np.sort_complex([1 + 2j, 2 - 1j, 3 - 2j, 3 - 3j, 3 + 5j])
    array([1.+2.j,  2.-1.j,  3.-3.j,  3.-2.j,  3.+5.j])

    """
    b = array(a, copy=True)
    b.sort()
    if not issubclass(b.dtype.type, _nx.complexfloating):
        if b.dtype.char in 'bhBH':
            return b.astype('F')
        elif <MASK>:
            return b.astype('G')
        else:
            return b.astype('D')
    else:
        return b

def repl(m):
    f = m.group(1)
    filename = os.path.basename(f)
    if f.startswith(('ATen/cuda', 'ATen/native/cuda', 'ATen/native/nested/cuda', 'ATen/native/quantized/cuda', 'ATen/native/sparse/cuda', 'ATen/native/transformers/cuda', 'THC/')) or (f.startswith('THC') and (not f.startswith('THCP'))):
        return templ.format(get_hip_file_path(m.group(1), is_pytorch_extension))
    if is_pytorch_extension and any((s.endswith(filename) for s in all_files)):
        header_dir = None
        header_filepath = None
        if include_current_dir:
            header_dir_to_check = os.path.dirname(fin_path)
            header_path_to_check = os.path.abspath(os.path.join(header_dir_to_check, f))
            if os.path.exists(header_path_to_check):
                header_dir = header_dir_to_check
                header_filepath = header_path_to_check
        if <MASK>:
            for header_include_dir in header_include_dirs:
                header_dir_to_check = os.path.join(output_directory, header_include_dir)
                header_path_to_check = os.path.abspath(os.path.join(header_dir_to_check, f))
                if os.path.exists(header_path_to_check):
                    header_dir = header_dir_to_check
                    header_filepath = header_path_to_check
        if header_filepath is None:
            return m.group(0)
        if header_filepath not in HIPIFY_FINAL_RESULT:
            preprocess_file_and_save_result(output_directory, header_filepath, all_files, header_include_dirs, stats, hip_clang_launch, is_pytorch_extension, clean_ctx, show_progress)
        elif header_filepath in HIPIFY_FINAL_RESULT:
            header_result = HIPIFY_FINAL_RESULT[header_filepath]
            if header_result.current_state == CurrentState.INITIALIZED:
                header_rel_path = os.path.relpath(header_filepath, output_directory)
                header_fout_path = os.path.abspath(os.path.join(output_directory, get_hip_file_path(header_rel_path, is_pytorch_extension)))
                header_result.hipified_path = header_fout_path
                HIPIFY_FINAL_RESULT[header_filepath] = header_result
                return templ.format(os.path.relpath(header_fout_path if header_fout_path is not None else header_filepath, header_dir))
        hipified_header_filepath = HIPIFY_FINAL_RESULT[header_filepath].hipified_path
        return templ.format(_to_unix_path(os.path.relpath(hipified_header_filepath if hipified_header_filepath is not None else header_filepath, header_dir)))
    return m.group(0)

def _check_on_delete(self, databases):
    on_delete = getattr(self.remote_field, 'on_delete', None)
    errors = []
    if on_delete in [DB_SET_NULL, SET_NULL] and (not self.null):
        errors.append(checks.Error(f'Field specifies on_delete={on_delete.__name__}, but cannot be null.', hint='Set null=True argument on the field, or change the on_delete rule.', obj=self, id='fields.E320'))
    elif on_delete == SET_DEFAULT and (not self.has_default()):
        errors.append(checks.Error('Field specifies on_delete=SET_DEFAULT, but has no default value.', hint='Set a default value, or change the on_delete rule.', obj=self, id='fields.E321'))
    elif <MASK>:
        if self.db_default is NOT_PROVIDED:
            errors.append(checks.Error('Field specifies on_delete=DB_SET_DEFAULT, but has no db_default value.', hint='Set a db_default value, or change the on_delete rule.', obj=self, id='fields.E322'))
        for db in databases:
            if not router.allow_migrate_model(db, self.model):
                continue
            connection = connections[db]
            if not ('supports_on_delete_db_default' in self.model._meta.required_db_features or connection.features.supports_on_delete_db_default):
                errors.append(checks.Error(f'{connection.display_name} does not support a DB_SET_DEFAULT.', hint='Change the on_delete rule to SET_DEFAULT.', obj=self, id='fields.E324'))
    elif not isinstance(self.remote_field.model, str) and on_delete != DO_NOTHING:
        is_db_on_delete = isinstance(on_delete, DatabaseOnDelete)
        ref_model_related_fields = (ref_model_field.remote_field for ref_model_field in self.remote_field.model._meta.get_fields() if ref_model_field.related_model and hasattr(ref_model_field.remote_field, 'on_delete'))
        for ref_remote_field in ref_model_related_fields:
            if ref_remote_field.on_delete is not None and ref_remote_field.on_delete != DO_NOTHING and (isinstance(ref_remote_field.on_delete, DatabaseOnDelete) is not is_db_on_delete):
                on_delete_type = 'database' if is_db_on_delete else 'Python'
                ref_on_delete_type = 'Python' if is_db_on_delete else 'database'
                errors.append(checks.Error(f'Field specifies {on_delete_type}-level on_delete variant, but referenced model uses {ref_on_delete_type}-level variant.', hint='Use either database or Python on_delete variants uniformly in the references chain.', obj=self, id='fields.E323'))
                break
    return errors

def _slow_forward(self, *input, **kwargs):
    tracing_state = torch._C._get_tracing_state()
    if not tracing_state or isinstance(self.forward, torch._C.ScriptMethod):
        return self.forward(*input, **kwargs)
    recording_scopes = torch.jit._trace._trace_module_map is not None
    if <MASK>:
        name = torch.jit._trace._trace_module_map.get(self, None)
        if name:
            tracing_state.push_scope(name)
        else:
            recording_scopes = False
    try:
        result = self.forward(*input, **kwargs)
    finally:
        if recording_scopes:
            tracing_state.pop_scope()
    return result

def _to_dot(self, graph_module: torch.fx.GraphModule, name: str, ignore_getattr: bool, ignore_parameters_and_buffers: bool, skip_node_names_in_args: bool, parse_stack_trace: bool) -> pydot.Dot:
    """
            Actual interface to visualize a fx.Graph. Note that it takes in the GraphModule instead of the Graph.
            If ignore_parameters_and_buffers is True, the parameters and buffers
            created with the module will not be added as nodes and edges.
            """
    dot_graph = pydot.Dot(name, rankdir='TB')
    buf_name_to_subgraph = {}
    for node in graph_module.graph.nodes:
        if ignore_getattr and node.op == 'get_attr':
            continue
        style = self._get_node_style(node)
        dot_node = pydot.Node(node.name, label=self._get_node_label(graph_module, node, skip_node_names_in_args, parse_stack_trace), **style)
        current_graph = dot_graph
        buf_meta = node.meta.get('buf_meta', None)
        if buf_meta is not None and buf_meta.n_origin > 1:
            buf_name = buf_meta.name
            if buf_name not in buf_name_to_subgraph:
                buf_name_to_subgraph[buf_name] = pydot.Cluster(buf_name, label=buf_name)
            current_graph = buf_name_to_subgraph.get(buf_name)
        current_graph.add_node(dot_node)

        def get_module_params_or_buffers():
            for (pname, ptensor) in chain(leaf_module.named_parameters(), leaf_module.named_buffers()):
                pname1 = node.name + '.' + pname
                label1 = pname1 + '|op_code=get_' + 'parameter' if isinstance(ptensor, torch.nn.Parameter) else 'buffer' + '\\l'
                dot_w_node = pydot.Node(pname1, label='{' + label1 + self._get_tensor_label(ptensor) + '}', **_WEIGHT_TEMPLATE)
                dot_graph.add_node(dot_w_node)
                dot_graph.add_edge(pydot.Edge(pname1, node.name))
        if node.op == 'call_module':
            leaf_module = self._get_leaf_node(graph_module, node)
            if <MASK>:
                get_module_params_or_buffers()
    for subgraph in buf_name_to_subgraph.values():
        subgraph.set('color', 'royalblue')
        subgraph.set('penwidth', '2')
        dot_graph.add_subgraph(subgraph)
    for node in graph_module.graph.nodes:
        if ignore_getattr and node.op == 'get_attr':
            continue
        for user in node.users:
            dot_graph.add_edge(pydot.Edge(node.name, user.name))
    return dot_graph

@classmethod
def _with_infer(cls, *args, **kwargs):
    """
        Constructor that uses the 1.0.x behavior inferring numeric dtypes
        for ndarray[object] inputs.
        """
    result = cls(*args, **kwargs)
    if <MASK>:
        values = lib.maybe_convert_objects(result._values)
        if values.dtype.kind in 'iufb':
            return Index(values, name=result.name)
    return result

