def date_hierarchy(cl):
    """
    Display the date hierarchy for date drill-down functionality.
    """
    if cl.date_hierarchy:
        field_name = cl.date_hierarchy
        field = get_fields_from_path(cl.model, field_name)[-1]
        if isinstance(field, models.DateTimeField):
            dates_or_datetimes = 'datetimes'
        else:
            dates_or_datetimes = 'dates'
        year_field = '%s__year' % field_name
        month_field = '%s__month' % field_name
        day_field = '%s__day' % field_name
        field_generic = '%s__' % field_name
        year_lookup = cl.params.get(year_field)
        month_lookup = cl.params.get(month_field)
        day_lookup = cl.params.get(day_field)

        def link(filters):
            return cl.get_query_string(filters, [field_generic])
        if not (year_lookup or month_lookup or day_lookup):
            date_range = cl.queryset.aggregate(first=models.Min(field_name), last=models.Max(field_name))
            if date_range['first'] and date_range['last']:
                if dates_or_datetimes == 'datetimes':
                    date_range = {k: timezone.localtime(v) if timezone.is_aware(v) else v for (k, v) in date_range.items()}
                if <MASK>:
                    year_lookup = date_range['first'].year
                    if date_range['first'].month == date_range['last'].month:
                        month_lookup = date_range['first'].month
        if year_lookup and month_lookup and day_lookup:
            day = datetime.date(int(year_lookup), int(month_lookup), int(day_lookup))
            return {'show': True, 'back': {'link': link({year_field: year_lookup, month_field: month_lookup}), 'title': capfirst(formats.date_format(day, 'YEAR_MONTH_FORMAT'))}, 'choices': [{'title': capfirst(formats.date_format(day, 'MONTH_DAY_FORMAT'))}]}
        elif year_lookup and month_lookup:
            days = getattr(cl.queryset, dates_or_datetimes)(field_name, 'day')
            return {'show': True, 'back': {'link': link({year_field: year_lookup}), 'title': str(year_lookup)}, 'choices': [{'link': link({year_field: year_lookup, month_field: month_lookup, day_field: day.day}), 'title': capfirst(formats.date_format(day, 'MONTH_DAY_FORMAT'))} for day in days]}
        elif year_lookup:
            months = getattr(cl.queryset, dates_or_datetimes)(field_name, 'month')
            return {'show': True, 'back': {'link': link({}), 'title': _('All dates')}, 'choices': [{'link': link({year_field: year_lookup, month_field: month.month}), 'title': capfirst(formats.date_format(month, 'YEAR_MONTH_FORMAT'))} for month in months]}
        else:
            years = getattr(cl.queryset, dates_or_datetimes)(field_name, 'year')
            return {'show': True, 'back': None, 'choices': [{'link': link({year_field: str(year.year)}), 'title': str(year.year)} for year in years]}

def _simplify_with_ranges(self, expr: Expr, var_ranges: VarRanges) -> Expr:
    """
        Simplify indexing expression with knowledge of the ranges of
        iteration variables.
        """
    expr = join_dimensions(self.simplify(expr))
    original_expr = expr
    var_to_range = dict(self.shape_env.var_to_range)
    var_to_range.update({k: ValueRanges(0, max(0, v - 1) if not has_free_symbols([v]) else IntInfinity()) for (k, v) in var_ranges.items()})
    for var in expr.free_symbols:
        if var not in var_to_range:
            var_to_range[var] = ValueRanges(0, IntInfinity())
    var_to_range_tuple = cast(tuple[tuple[sympy.Symbol, ValueRanges[sympy.Expr]]], tuple(var_to_range.items()))
    axioms = []
    for (var, upper_bound) in var_ranges.items():
        axioms.append(0 <= var)
        axioms.append(var < upper_bound)
    axioms = tuple(axioms) + self.shape_env.get_axioms()

    def statically_known(expr):
        evaluated = self.shape_env._maybe_evaluate_static(expr, axioms=axioms, var_to_range=var_to_range_tuple)
        return bool(evaluated)

    def remove_zero_terms(base, divisor):
        """Symbols smaller than the divisor are zero"""
        if not statically_known(base >= 0):
            return base
        for v in base.free_symbols:
            if v in var_ranges:
                rest = sympy.Wild('_rest', exclude=[v])
                m = base.match(v + rest)
                if m and v not in m[rest].free_symbols:
                    gcd = sympy.gcd(m[rest], divisor)
                    if gcd == divisor:
                        if <MASK>:
                            base = m[rest]
        return base

    def visit_indexing_div(base, divisor):
        return FloorDiv(remove_zero_terms(base, divisor), divisor)

    def visit_modular_indexing(base, divisor, modulus):
        base = remove_zero_terms(base, divisor)
        can_remove_mod = statically_known(base >= 0) and statically_known(base < modulus * divisor)
        if can_remove_mod:
            return FloorDiv(base, divisor)
        return ModularIndexing(base, divisor, modulus)
    if expr.has(ModularIndexing):
        expr = expr.replace(ModularIndexing(sympy.Wild('base', integer=True), sympy.Wild('divisor', integer=True), sympy.Wild('modulus', integer=True)), visit_modular_indexing)
    if expr.has(FloorDiv):
        expr = expr.replace(FloorDiv(sympy.Wild('base', integer=True), sympy.Wild('divisor', integer=True)), visit_indexing_div)
    if expr != original_expr:
        return self._simplify_with_ranges(expr, var_ranges)
    return expr

@staticmethod
def num_splits(device: torch.device, dst_dtype: torch.dtype, src_dtype: torch.dtype, inner_fn: Callable[_P, OpsValue], ranges: Sequence[_IntLike], reduction_ranges: Sequence[_IntLike], reduction_type: Union[ReductionType, Literal['scan']], reduction_numel: Expr, input_node: Optional[IRNode]=None) -> tuple[ReductionHint, _IntLike]:
    reduction_numel_hint = V.graph.sizevars.symbolic_hint(reduction_numel)
    numel_hint = V.graph.sizevars.symbolic_hint(sympy_product(ranges))
    should_split = reduction_type == 'scan' or (not V.graph.has_feature(device, BackendFeature.REDUCE_TO_SINGLE_ELEMENT) and reduction_type not in ('argmax', 'argmin') and config.split_reductions)
    if not (_is_static(reduction_numel_hint) and _is_static(numel_hint)):
        return (ReductionHint.DEFAULT, 1)
    if reduction_type == 'dot':
        return (ReductionHint.DEFAULT, 1)
    props = DeviceProperties.create(device)
    num_sm = props.multi_processor_count
    min_elements_per_thread = 32
    if should_split:
        inner_reduction_splits: Callable[[int, int], int] = functools.partial(V.choices.reduction_split_factor, device, inner_reduction=True)
        outer_reduction_splits: Callable[[int, int], int] = functools.partial(V.choices.reduction_split_factor, device, inner_reduction=False)
    else:

        def inner_reduction_splits(reduction_numel_hint: int, numel_hint: int) -> int:
            return 1
        outer_reduction_splits = inner_reduction_splits
    if numel_hint == 1:
        split = inner_reduction_splits(reduction_numel_hint, numel_hint)
        if split == 1:
            return (ReductionHint.INNER, split)
        if input_node is not None and isinstance(input_node, TensorBox):
            with patch.object(FlexibleLayout, 'allow_indexing', True):
                (new_ranges, new_reduction_ranges) = extract_input_node_reduction_ranges(input_node)
            if <MASK>:
                extracted_numel_hint = V.graph.sizevars.symbolic_hint(sympy_product(new_ranges + new_reduction_ranges))
                if reduction_numel_hint == extracted_numel_hint:
                    log.debug("Use previous IRNode's range and reduction_ranges instead of split. current ranges: %s, current reduction ranges: %s, current split: %d, new ranges: %s, new reduction ranges: %s", ranges, reduction_ranges, split, new_ranges, new_reduction_ranges)
                    return (ReductionHint.INNER, -1)
        return (ReductionHint.INNER, split)
    if reduction_numel_hint <= min_elements_per_thread or numel_hint >= num_sm * 2 * 32:
        return (ReductionHint.DEFAULT, 1)
    r = Reduction(device=device, dtype=dst_dtype, inner_fn=inner_fn, ranges=ranges, reduction_ranges=reduction_ranges, reduction_type=reduction_type if reduction_type != 'scan' else 'sum', src_dtype=src_dtype, reduction_hint=ReductionHint.DEFAULT)

    def get_read_indices(r: Reduction) -> tuple[Sequence[Expr], bool]:
        device = r.get_device()
        assert device is not None
        cb = ComputedBuffer(name=None, layout=FlexibleLayout(device=device, dtype=r.get_dtype(), size=r.get_size()), data=r)
        read_writes = cb.get_read_writes()
        assert read_writes.range_vars is not None
        range_vars = [r for r in read_writes.range_vars if isinstance(r, Expr) and (not isinstance(r, sympy.Number))]
        indices = []
        changed = False
        for md in sorted(read_writes.reads, key=lambda x: x.name):
            if all((r in md.index.free_symbols for r in range_vars)):
                indices.append(md.index)
                if md.name in V.graph.name_to_buffer:
                    buf = V.graph.name_to_buffer[md.name]
                    original_stride = getattr(buf.layout, 'stride', None)
                    buf.decide_layout()
                    if getattr(buf.layout, 'stride', None) != original_stride:
                        changed = True
        return (indices, changed)
    (indices, changed) = get_read_indices(r)
    if changed:
        (indices, _) = get_read_indices(r)
    if len(indices) == 0:
        return (ReductionHint.DEFAULT, 1)
    ((_, reduction_vars), ranges1) = dependencies.index_vars_squeeze(r.get_size(), r.get_reduction_size())
    num_outer = 0
    num_inner = 0
    for i in indices:
        j = V.graph.sizevars.simplify_with_ranges(i, ranges1)
        strides = V.graph.sizevars.stride_hints(j, reduction_vars, list(ranges1.keys()))
        outer = all((s > 1 for s in strides))
        if outer:
            num_outer += 1
        else:
            num_inner += 1
    if num_inner > num_outer:
        return (ReductionHint.INNER, inner_reduction_splits(reduction_numel_hint, numel_hint))
    else:
        return (ReductionHint.OUTER, outer_reduction_splits(reduction_numel_hint, numel_hint))

def maybe_tangent(t):
    assert type(t) is not CCT
    if <MASK>:
        return torch.randn_like(t)
    elif is_tensorlist(t):
        return [torch.randn_like(e) if e.requires_grad else None for e in t]
    return None

def show_path(from_op, tensors, sources):
    """Find one path from `from_op` to any of `tensors`, ignoring `sources`.

  Args:
    from_op: A `tf.Operation`.
    tensors: A `tf.Operation`, a `tf.Tensor`, or a list thereof.
    sources: A list of `tf.Tensor`.

  Returns:
    A python string containing the path, or "??" if none is found.
  """
    if <MASK>:
        from_op = from_op.op
    if not isinstance(tensors, list):
        tensors = [tensors]
    final_ops = [_as_operation(tensor) for tensor in tensors]
    visited_ops = set((x.op for x in sources))
    ops_to_visit = list(final_ops)
    some_op_output = {}
    while ops_to_visit:
        op = ops_to_visit.pop()
        if op in visited_ops:
            continue
        visited_ops.add(op)
        if op == from_op:
            path_op = op
            path = [path_op]
            while path_op not in final_ops:
                path_op = some_op_output[path_op]
                path.append(path_op)
            return ' <- '.join(('%s (%s)' % (x.name, x.type) for x in reversed(path)))
        else:
            for inp in graph_inputs(op):
                if inp not in visited_ops and inp not in sources:
                    some_op_output[inp] = op
                    ops_to_visit.append(inp)
    return '??'

def set_logical_devices_to_at_least(device, num):
    """Create logical devices of at least a given number."""
    if <MASK>:
        raise ValueError('`num` must be at least 1 not %r' % (num,))
    physical_devices = config.list_physical_devices(device)
    if not physical_devices:
        raise RuntimeError('No {} found'.format(device))
    if len(physical_devices) >= num:
        return
    num = num - len(physical_devices) + 1
    logical_devices = []
    for _ in range(num):
        if device.upper() == 'GPU':
            logical_devices.append(context.LogicalDeviceConfiguration(memory_limit=2048))
        else:
            logical_devices.append(context.LogicalDeviceConfiguration())
    config.set_logical_device_configuration(physical_devices[-1], logical_devices)

@bottleneck_switch()
def nanmedian(values: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, mask=None) -> float | np.ndarray:
    """
    Parameters
    ----------
    values : ndarray
    axis : int, optional
    skipna : bool, default True
    mask : ndarray[bool], optional
        nan-mask if known

    Returns
    -------
    result : float | ndarray
        Unless input is a float array, in which case use the same
        precision as the input array.

    Examples
    --------
    >>> from pandas.core import nanops
    >>> s = pd.Series([1, np.nan, 2, 2])
    >>> nanops.nanmedian(s.values)
    2.0

    >>> s = pd.Series([np.nan, np.nan, np.nan])
    >>> nanops.nanmedian(s.values)
    nan
    """
    using_nan_sentinel = values.dtype.kind == 'f' and mask is None

    def get_median(x: np.ndarray, _mask=None):
        if _mask is None:
            _mask = notna(x)
        else:
            _mask = ~_mask
        if not skipna and (not _mask.all()):
            return np.nan
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
            warnings.filterwarnings('ignore', 'Mean of empty slice', RuntimeWarning)
            res = np.nanmedian(x[_mask])
        return res
    dtype = values.dtype
    (values, mask) = _get_values(values, skipna, mask=mask, fill_value=None)
    if values.dtype.kind != 'f':
        if values.dtype == object:
            inferred = lib.infer_dtype(values)
            if inferred in ['string', 'mixed']:
                raise TypeError(f'Cannot convert {values} to numeric')
        try:
            values = values.astype('f8')
        except ValueError as err:
            raise TypeError(str(err)) from err
    if <MASK>:
        if not values.flags.writeable:
            values = values.copy()
        values[mask] = np.nan
    notempty = values.size
    res: float | np.ndarray
    if values.ndim > 1 and axis is not None:
        if notempty:
            if not skipna:
                res = np.apply_along_axis(get_median, axis, values)
            else:
                with warnings.catch_warnings():
                    warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
                    if values.shape[1] == 1 and axis == 0 or (values.shape[0] == 1 and axis == 1):
                        res = np.nanmedian(np.squeeze(values), keepdims=True)
                    else:
                        res = np.nanmedian(values, axis=axis)
        else:
            res = _get_empty_reduction_result(values.shape, axis)
    else:
        res = get_median(values, mask) if notempty else np.nan
    return _wrap_results(res, dtype)

def _convert_from_string(data):
    for char in '[]':
        data = data.replace(char, '')
    rows = data.split(';')
    newdata = []
    for (count, row) in enumerate(rows):
        trow = row.split(',')
        newrow = []
        for col in trow:
            temp = col.split()
            newrow.extend(map(ast.literal_eval, temp))
        if <MASK>:
            Ncols = len(newrow)
        elif len(newrow) != Ncols:
            raise ValueError('Rows not the same size.')
        newdata.append(newrow)
    return newdata

