@test_util.run_in_graph_and_eager_modes
def test_name_scopes_for_variable_scopes(self):

    def linear_module(x, output_size):
        w = variable_scope.get_variable('w', shape=[x.get_shape()[1], output_size], initializer=init_ops.zeros_initializer())
        b = variable_scope.get_variable('b', shape=[output_size], initializer=init_ops.zeros_initializer())
        return (math_ops.matmul(x, w) + b, w)

    def make_linear_module(output_size, name):
        return template.make_template(name, linear_module, output_size=output_size, create_scope_now_=True)
    inputs = array_ops.ones((3, 4))
    linear1 = make_linear_module(output_size=2, name='foo')
    (outputs_a, w1) = linear1(inputs)
    (outputs_b, _) = linear1(inputs)
    self.assertEqual('foo', linear1.variable_scope.name)
    self.assertEqual('foo/w:0', w1.name)
    if <MASK>:
        self.assertEqual('foo/add:0', outputs_a.name, 'First application of template should get same name scope as variables.')
        self.assertEqual('foo_1/add:0', outputs_b.name, 'Second application of template should get a freshly uniquified name scope.')
    linear2 = make_linear_module(output_size=2, name='foo')
    (outputs_c, w2) = linear2(inputs)
    (outputs_d, _) = linear2(inputs)
    self.assertEqual('foo_1', linear2.variable_scope.name, "New template gets a freshly uniquified variable scope because 'foo' is already taken.")
    self.assertEqual('foo_1/w:0', w2.name)
    if not context.executing_eagerly():
        self.assertEqual('foo_1_1/add:0', outputs_c.name, "First application of template would get same name scope as variables, but 'foo_1' is already a name scope.")
        self.assertEqual('foo_1_2/add:0', outputs_d.name, 'Second application of template should also get a freshly uniquified name scope.')

def check_cacheable(gm: torch.fx.GraphModule):
    """
    Checks that the graph module only uses supported operators
    """
    nodes = gm.graph.nodes
    if torch._inductor.config.freezing:
        raise BypassAOTAutogradCache('Cannot cache a graph with freezing enabled')
    if not (torch._inductor.config.fx_graph_cache or should_use_remote_fx_graph_cache()):
        raise BypassAOTAutogradCache('FX graph cache is not enabled')
    tracing_context = torch._guards.TracingContext.try_get()
    if tracing_context and tracing_context.fakify_first_call:
        raise BypassAOTAutogradCache("Won't cache a graph with fakify_first_call enabled")
    for node in nodes:
        check_node_safe(node)
    if <MASK>:
        check_cacheable(gm.saved_tensors_hooks_pack_0)
        check_cacheable(gm.saved_tensors_hooks_unpack_0)

def failures_histogram(eager_dir, dynamo_dir, verbose=False, format_issues=False):
    fail_keys = compute_pass_rate(eager_dir, dynamo_dir)
    xmls = open_test_results(dynamo_dir)
    testcases = get_testcases(xmls)
    testcases = [t for t in testcases if key(t) in fail_keys]
    dct = get_failures(testcases)
    result = []
    for (count, reason, testcases) in dct:
        if <MASK>:
            row = (count, reason, repro(testcases[0]), [all_tests(t) for t in testcases])
        else:
            row = (count, reason, repro(testcases[0]))
        result.append(row)
    header = '(num_failed_tests, error_msg, sample_test, all_tests)' if verbose else '(num_failed_tests, error_msg, sample_test)'
    print(header)
    sum_counts = sum((r[0] for r in result))
    for row in result:
        if format_issues:
            print(as_issue(*row))
        else:
            print(row)
    print('[counts]', sum_counts)

def testMinMax(self):
    for datatype_enum in types_pb2.DataType.values():
        if not _is_numeric_dtype_enum(datatype_enum):
            continue
        dtype = dtypes.as_dtype(datatype_enum)
        numpy_dtype = dtype.as_numpy_dtype
        if dtype.is_quantized or dtype.base_dtype == dtypes.bool or dtype.base_dtype == dtypes.string or (dtype.base_dtype == dtypes.complex64) or (dtype.base_dtype == dtypes.complex128):
            continue
        print('%s: %s - %s' % (dtype, dtype.min, dtype.max))
        if numpy_dtype == np.bool_:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 1)
        if numpy_dtype == np.int8:
            self.assertEqual(dtype.min, -128)
            self.assertEqual(dtype.max, 127)
        if numpy_dtype == np.int16:
            self.assertEqual(dtype.min, -32768)
            self.assertEqual(dtype.max, 32767)
        if numpy_dtype == np.int32:
            self.assertEqual(dtype.min, -2147483648)
            self.assertEqual(dtype.max, 2147483647)
        if numpy_dtype == np.int64:
            self.assertEqual(dtype.min, -9223372036854775808)
            self.assertEqual(dtype.max, 9223372036854775807)
        if numpy_dtype == np.uint8:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 255)
        if numpy_dtype == np.uint16:
            if dtype == dtypes.uint16:
                self.assertEqual(dtype.min, 0)
                self.assertEqual(dtype.max, 65535)
            elif dtype == dtypes.bfloat16:
                self.assertEqual(dtype.min, 0)
                self.assertEqual(dtype.max, 4294967295)
        if numpy_dtype == np.uint32:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 4294967295)
        if <MASK>:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 18446744073709551615)
        if numpy_dtype in (np.float16, np.float32, np.float64):
            self.assertEqual(dtype.min, np.finfo(numpy_dtype).min)
            self.assertEqual(dtype.max, np.finfo(numpy_dtype).max)
        if numpy_dtype == dtypes.bfloat16.as_numpy_dtype:
            self.assertEqual(dtype.min, float.fromhex('-0x1.FEp127'))
            self.assertEqual(dtype.max, float.fromhex('0x1.FEp127'))
        if numpy_dtype == dtypes.float8_e5m2.as_numpy_dtype:
            self.assertEqual(dtype.min, -57344.0)
            self.assertEqual(dtype.max, 57344.0)
        if numpy_dtype == dtypes.float8_e4m3fn.as_numpy_dtype:
            self.assertEqual(dtype.min, -448.0)
            self.assertEqual(dtype.max, 448.0)
        if numpy_dtype == dtypes.float8_e4m3fnuz.as_numpy_dtype:
            self.assertEqual(dtype.min, -240.0)
            self.assertEqual(dtype.max, 240.0)
        if numpy_dtype == dtypes.float8_e4m3b11fnuz.as_numpy_dtype:
            self.assertEqual(dtype.min, -30.0)
            self.assertEqual(dtype.max, 30.0)
        if numpy_dtype == dtypes.float8_e5m2fnuz.as_numpy_dtype:
            self.assertEqual(dtype.min, -57344.0)
            self.assertEqual(dtype.max, 57344.0)
        if numpy_dtype == dtypes.int4.as_numpy_dtype:
            self.assertEqual(dtype.min, -8)
            self.assertEqual(dtype.max, 7)
        if numpy_dtype == dtypes.uint4.as_numpy_dtype:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 15)
        if numpy_dtype == dtypes.int2.as_numpy_dtype:
            self.assertEqual(dtype.min, -2)
            self.assertEqual(dtype.max, 1)
        if numpy_dtype == dtypes.uint2.as_numpy_dtype:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 3)

def argument_type_str_pyi(t: Type) -> str:
    add_optional = False
    if isinstance(t, OptionalType):
        t = t.elem
        add_optional = True
    ret = ''
    if isinstance(t, BaseType):
        if t.name in [BaseTy.int, BaseTy.DeviceIndex]:
            ret = '_int'
        if t.name == BaseTy.SymInt:
            ret = '_int | SymInt'
        elif t.name == BaseTy.float:
            ret = '_float'
        elif t.name == BaseTy.str:
            ret = 'str'
        elif t.name == BaseTy.Scalar:
            ret = 'Number | _complex'
        elif t.name == BaseTy.ScalarType:
            ret = '_dtype'
        elif t.name == BaseTy.bool:
            ret = '_bool'
        elif t.name == BaseTy.QScheme:
            ret = '_qscheme'
        elif t.name == BaseTy.Layout:
            ret = '_layout'
        elif t.name == BaseTy.Device:
            ret = 'DeviceLikeType | None'
        elif <MASK>:
            ret = 'memory_format'
        elif t.name == BaseTy.Dimname:
            ret = 'str | EllipsisType | None'
        elif t.name == BaseTy.Storage:
            ret = 'Storage | UntypedStorage'
        elif t.name in [BaseTy.Tensor, BaseTy.Generator, BaseTy.Stream]:
            ret = t.name.name
    elif isinstance(t, ListType):
        if str(t.elem) == 'int':
            ret = '_int | _size' if t.size is not None else '_size'
        elif t.is_tensor_like():
            add_optional = True
            ret = 'Tensor | tuple[Tensor, ...] | list[Tensor]' if t.size is not None else 'tuple[Tensor, ...] | list[Tensor]'
        elif str(t.elem) == 'float':
            ret = 'Sequence[_float]'
        elif str(t.elem) == 'SymInt' and t.size is not None:
            elem = argument_type_str_pyi(t.elem)
            ret = f'{elem} | Sequence[{elem}]'
        else:
            elem = argument_type_str_pyi(t.elem)
            ret = f'Sequence[{elem}]'
    else:
        raise RuntimeError(f'unrecognized type {repr(t)}')
    if add_optional:
        ret = f'{ret} | None'.replace(' | None | None', ' | None')
    return ret

def scalable_frobenius_norm_discrepancy(X, U, s, V):
    if <MASK>:
        A = X - U.dot(np.diag(s).dot(V))
        return norm_diff(A, norm='fro')
    print('... computing fro norm by batches...')
    batch_size = 1000
    Vhat = np.diag(s).dot(V)
    cum_norm = 0.0
    for batch in gen_batches(X.shape[0], batch_size):
        M = X[batch, :] - U[batch, :].dot(Vhat)
        cum_norm += norm_diff(M, norm='fro', msg=False)
    return np.sqrt(cum_norm)

def get_prep_value(self, value):
    obj = super().get_prep_value(value)
    if obj is None:
        return None
    if <MASK>:
        pass
    else:
        is_candidate = isinstance(obj, (bytes, str)) or hasattr(obj, '__geo_interface__')
        raster = self.get_raster_prep_value(obj, is_candidate)
        if raster:
            obj = raster
        elif is_candidate:
            try:
                obj = GEOSGeometry(obj)
            except (GEOSException, GDALException):
                raise ValueError("Couldn't create spatial object from lookup value '%s'." % obj)
        else:
            raise ValueError('Cannot use object with type %s for a spatial lookup parameter.' % type(obj).__name__)
    obj.srid = self.get_srid(obj)
    return obj

@numba.jit(nopython=nopython, nogil=nogil, parallel=parallel)
def ewm_table(values: np.ndarray, begin: np.ndarray, end: np.ndarray, minimum_periods: int) -> np.ndarray:
    alpha = 1.0 / (1.0 + com)
    old_wt_factor = 1.0 - alpha
    new_wt = 1.0 if adjust else alpha
    old_wt = np.ones(values.shape[1])
    result = np.empty(values.shape)
    weighted = values[0].copy()
    nobs = (~np.isnan(weighted)).astype(np.int64)
    result[0] = np.where(nobs >= minimum_periods, weighted, np.nan)
    for i in range(1, len(values)):
        cur = values[i]
        is_observations = ~np.isnan(cur)
        nobs += is_observations.astype(np.int64)
        for j in numba.prange(len(cur)):
            if not np.isnan(weighted[j]):
                if is_observations[j] or not ignore_na:
                    if normalize:
                        old_wt[j] *= old_wt_factor ** deltas[i - 1]
                        if not adjust and com == 1:
                            new_wt = 1.0 - old_wt[j]
                    else:
                        weighted[j] = old_wt_factor * weighted[j]
                    if is_observations[j]:
                        if normalize:
                            if weighted[j] != cur[j]:
                                weighted[j] = old_wt[j] * weighted[j] + new_wt * cur[j]
                                if normalize:
                                    weighted[j] = weighted[j] / (old_wt[j] + new_wt)
                            if <MASK>:
                                old_wt[j] += new_wt
                            else:
                                old_wt[j] = 1.0
                        else:
                            weighted[j] += cur[j]
            elif is_observations[j]:
                weighted[j] = cur[j]
        result[i] = np.where(nobs >= minimum_periods, weighted, np.nan)
    return result

def get_action(self, action):
    """
        Return a given action from a parameter, which can either be a callable,
        or the name of a method on the ModelAdmin. Return is a tuple of
        (callable, name, description).
        """
    if callable(action):
        func = action
        action = action.__name__
    elif <MASK>:
        func = getattr(self.__class__, action)
    else:
        try:
            func = self.admin_site.get_action(action)
        except KeyError:
            return None
    description = self._get_action_description(func, action)
    return (func, action, description)

def _get_formatdict(data, *, precision, floatmode, suppress, sign, legacy, formatter, **kwargs):
    formatdict = {'bool': lambda : BoolFormat(data), 'int': lambda : IntegerFormat(data, sign), 'float': lambda : FloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'longfloat': lambda : FloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'complexfloat': lambda : ComplexFloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'longcomplexfloat': lambda : ComplexFloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'datetime': lambda : DatetimeFormat(data, legacy=legacy), 'timedelta': lambda : TimedeltaFormat(data), 'object': lambda : _object_format, 'void': lambda : str_format, 'numpystr': lambda : repr_format}

    def indirect(x):
        return lambda : x
    if formatter is not None:
        fkeys = [k for k in formatter.keys() if formatter[k] is not None]
        if 'all' in fkeys:
            for key in formatdict.keys():
                formatdict[key] = indirect(formatter['all'])
        if 'int_kind' in fkeys:
            for key in ['int']:
                formatdict[key] = indirect(formatter['int_kind'])
        if 'float_kind' in fkeys:
            for key in ['float', 'longfloat']:
                formatdict[key] = indirect(formatter['float_kind'])
        if 'complex_kind' in fkeys:
            for key in ['complexfloat', 'longcomplexfloat']:
                formatdict[key] = indirect(formatter['complex_kind'])
        if 'str_kind' in fkeys:
            formatdict['numpystr'] = indirect(formatter['str_kind'])
        for key in formatdict.keys():
            if <MASK>:
                formatdict[key] = indirect(formatter[key])
    return formatdict

