def _convert_tensor(value, path, context):
    """Converts `value` to a `Tensor`."""
    if context == _ConversionContext.SPEC:
        if <MASK>:
            raise TypeError(f"{''.join(path)}: expected a TensorSpec, got {type(value).__name__!r}")
        return value
    if not isinstance(value, tensor.Tensor):
        if context == _ConversionContext.DEFAULT:
            return value
        try:
            value = ops.convert_to_tensor(value)
        except (ValueError, TypeError) as e:
            raise TypeError(f"{''.join(path)}: expected a Tensor, got {type(value).__name__!r}") from e
    return value

def _get_ax_freq(ax: Axes):
    """
    Get the freq attribute of the ax object if set.
    Also checks shared axes (eg when using secondary yaxis, sharex=True
    or twinx)
    """
    ax_freq = getattr(ax, 'freq', None)
    if ax_freq is None:
        if hasattr(ax, 'left_ax'):
            ax_freq = getattr(ax.left_ax, 'freq', None)
        elif hasattr(ax, 'right_ax'):
            ax_freq = getattr(ax.right_ax, 'freq', None)
    if ax_freq is None:
        shared_axes = ax.get_shared_x_axes().get_siblings(ax)
        if <MASK>:
            for shared_ax in shared_axes:
                ax_freq = getattr(shared_ax, 'freq', None)
                if ax_freq is not None:
                    break
    return ax_freq

def _process_unlinkable_fobjects(self, objects, libraries, fcompiler, library_dirs, unlinkable_fobjects):
    libraries = list(libraries)
    objects = list(objects)
    unlinkable_fobjects = list(unlinkable_fobjects)
    for lib in libraries[:]:
        for libdir in library_dirs:
            fake_lib = os.path.join(libdir, lib + '.fobjects')
            if os.path.isfile(fake_lib):
                libraries.remove(lib)
                with open(fake_lib) as f:
                    unlinkable_fobjects.extend(f.read().splitlines())
                c_lib = os.path.join(libdir, lib + '.cobjects')
                with open(c_lib) as f:
                    objects.extend(f.read().splitlines())
    if <MASK>:
        fobjects = [os.path.abspath(obj) for obj in unlinkable_fobjects]
        wrapped = fcompiler.wrap_unlinkable_objects(fobjects, output_dir=self.build_temp, extra_dll_dir=self.extra_dll_dir)
        objects.extend(wrapped)
    return (objects, libraries)

def _maybe_promote_arg(self, node: torch.fx.Node, fx_arg: torch.fx.node.Argument, dtype: torch.dtype | None) -> torch.fx.node.Argument:
    """Promote fx_arg to dtype if necessary."""
    if dtype is None:
        logger.info('Argument %s is not promoted. Not mentioned by type promotion rule.', fx_arg)
        return fx_arg
    if isinstance(fx_arg, torch.fx.Node):
        arg_val = self.env[fx_arg]
        if <MASK>:
            if (old_dtype := arg_val.dtype) != dtype:
                graph = node.graph
                with graph.inserting_before(node):
                    logger.info('Argument %s(%s) is promoted to %s.', fx_arg, old_dtype, dtype)
                    return self._create_node(graph, 'call_function', torch.ops.prims.convert_element_type.default, (fx_arg,), {'dtype': dtype})
            logger.info('Argument %s is not promoted. Already %s.', fx_arg, dtype)
            return fx_arg
        elif fx_type_utils.is_torch_symbolic_type(arg_val):
            arg_type = type(arg_val)
            equivalent_dtype = fx_type_utils.from_scalar_type_to_torch_dtype(arg_type)
            assert equivalent_dtype is not None, f'Unexpected arg_type: {arg_type}'
            if equivalent_dtype != dtype:
                graph = node.graph
                with graph.inserting_before(node):
                    logger.info('Argument %s(Scalar of equivalent dtype: %s) is promoted to %s.', fx_arg, equivalent_dtype, dtype)
                    return self._create_node(graph, 'call_function', torch.ops.aten.scalar_tensor.default, (fx_arg,), {'dtype': dtype})
            logger.info('Argument %s is not promoted. Already %s.', fx_arg, dtype)
            return fx_arg
    elif (equivalent_dtype := fx_type_utils.from_scalar_type_to_torch_dtype(type(fx_arg))) is not None:
        if equivalent_dtype != dtype:
            graph = node.graph
            with graph.inserting_before(node):
                logger.info('Argument %s(Scalar of equivalent dtype: %s) is promoted to %s.', fx_arg, equivalent_dtype, dtype)
                return self._create_node(graph, 'call_function', torch.ops.aten.scalar_tensor.default, (fx_arg,), {'dtype': dtype})
        logger.info('Argument %s is not promoted. Already %s.', fx_arg, dtype)
        return fx_arg
    elif isinstance(fx_arg, (tuple, list)):
        logger.info('Argument %s is a tuple/list. Promoting each element.', fx_arg)
        return type(fx_arg)((self._maybe_promote_arg(node, fx_arg_elem, dtype) for fx_arg_elem in fx_arg))
    raise NotImplementedError(f'Unknown fx arg type: {type(fx_arg)}')

