def propagate_annotation(model: torch.fx.GraphModule) -> None:
    for n in model.graph.nodes:
        if n.op != 'call_function' or not _is_share_obs_or_fq_op(n.target):
            continue
        prev_node = n.args[0]
        if not isinstance(prev_node, Node):
            continue
        quantization_annotation = prev_node.meta.get('quantization_annotation', None)
        if not quantization_annotation:
            continue
        output_qspec = quantization_annotation.output_qspec
        if <MASK>:
            continue
        if 'quantization_annotation' in n.meta and n.meta['quantization_annotation']._annotated:
            continue
        shared_qspec = SharedQuantizationSpec(prev_node)
        n.meta['quantization_annotation'] = QuantizationAnnotation(input_qspec_map={prev_node: shared_qspec}, output_qspec=shared_qspec, _annotated=True)

def _has_same_id_matched_objs(frame: DynamoFrameType, cache_entry: Any) -> bool:
    """
    Checks if the ID_MATCH'd objects saved on cache_entry are same as the ones
    in frame.f_locals.
    """
    if not cache_entry:
        return False
    for (local_name, weakref_from_cache_entry) in cache_entry.guard_manager.id_matched_objs.items():
        if weakref_from_cache_entry() is not None:
            weakref_from_frame = _get_weakref_from_f_locals(frame, local_name)
            if <MASK>:
                return False
    return True

@require_backend_is_available({'gloo'})
@skip_but_pass_in_sandcastle_if(IS_MACOS or IS_WINDOWS, 'MacOS uses uv transport which does not have as robust error handling as tcp transport')
def test_monitored_barrier_gloo(self):
    tensors = [torch.ones(10) * self.rank]
    for _ in range(10):
        dist.all_reduce(torch.cat(tensors))
    timeout = timedelta(seconds=2)
    dist.monitored_barrier(timeout=timeout)
    for _ in range(10):
        dist.all_reduce(torch.cat(tensors))
    dist.monitored_barrier(timeout=timeout, wait_all_ranks=True)
    failed_rank = 1
    src_rank = 0
    if self.rank == src_rank:
        with self.assertRaisesRegex(RuntimeError, f'Rank {failed_rank} failed to pass monitoredBarrier'):
            dist.monitored_barrier(timeout=timeout)
    elif <MASK>:
        err_regex = f'Rank {self.rank} successfully reached monitoredBarrier, but received errors while waiting for send/recv from rank {src_rank}'
        with self.assertRaisesRegex(RuntimeError, err_regex):
            dist.monitored_barrier(timeout=timeout)
    self._barrier(timeout=30)

def check_and_broadcast_indices(indices, device):
