        self.assertAllClose(jacob_t, jacob_n, rtol=1e-05, atol=1e-05)

def decorator(func):

    def _pre_process_request(request, *args, **kwargs):
        res_last_modified = None
        if last_modified_func:
            if (dt := last_modified_func(request, *args, **kwargs)):
                if not timezone.is_aware(dt):
                    dt = timezone.make_aware(dt, datetime.UTC)
                res_last_modified = int(dt.timestamp())
        res_etag = etag_func(request, *args, **kwargs) if etag_func else None
        res_etag = quote_etag(res_etag) if res_etag is not None else None
        response = get_conditional_response(request, etag=res_etag, last_modified=res_last_modified)
        return (response, res_etag, res_last_modified)

    def _post_process_request(request, response, res_etag, res_last_modified):
        if request.method in ('GET', 'HEAD'):
            if res_last_modified and (not response.has_header('Last-Modified')):
                response.headers['Last-Modified'] = http_date(res_last_modified)
            if res_etag:
                response.headers.setdefault('ETag', res_etag)
    if iscoroutinefunction(func):

        @wraps(func)
        async def inner(request, *args, **kwargs):
            (response, res_etag, res_last_modified) = _pre_process_request(request, *args, **kwargs)
            if <MASK>:
                response = await func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response
    else:

        @wraps(func)
        def inner(request, *args, **kwargs):
            (response, res_etag, res_last_modified) = _pre_process_request(request, *args, **kwargs)
            if response is None:
                response = func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response
    return inner

def _align(self, axis):
    """A convenience function for operations that need to preserve axis
        orientation.
        """
    if axis is None:
        return self[0, 0]
    elif <MASK>:
        return self
    elif axis == 1:
        return self.transpose()
    else:
        raise ValueError('unsupported axis')

def github_linkcode_resolve(domain, info, *, version, next_version):
    if domain != 'py':
        return None
    if <MASK>:
        return None
    try:
        (path, lineno) = get_path_and_line(module=module, fullname=info['fullname'])
    except CodeNotFound:
        return None
    branch = get_branch(version=version, next_version=next_version)
    relative_path = path.relative_to(pathlib.Path(__file__).parents[2])
    url_path = '/'.join(relative_path.parts)
    return f'https://github.com/django/django/blob/{branch}/{url_path}#L{lineno}'

