def combo_grid_meta(self) -> dict[str, Any]:
    dynamic_shape = bool(self.dynamic_shape_args)
    num_kernels = len(self.sub_kernels)
    min_blocks = max(self.min_x_blocks_list) * num_kernels if not dynamic_shape else None
    if not self.enable_autotune:
        if <MASK>:
            default_config = {'XBLOCK': self.block_size_2d, 'YBLOCK': self.block_size_2d}
        else:
            default_config = {'XBLOCK': self.block_size_1d}
    else:
        default_config = None
    meta = {'num_kernels': num_kernels, 'min_blocks': min_blocks, 'default_config': default_config}
    for (num, sub_kernel) in enumerate(self.sub_kernels):
        meta[f'no_x_dim_{num}'] = sub_kernel.no_x_dim
        for (i, tree) in enumerate(sub_kernel.range_trees):
            if not tree.is_reduction:
                numel_name = f'{tree.prefix}numel_{num}'
                if numel_name in self.dynamic_shape_args:
                    meta[numel_name] = None
                else:
                    meta[numel_name] = int(V.graph.sizevars.simplify(tree.numel))
    return meta

def merge_devices(t: object) -> None:
    nonlocal common_device
    nonlocal is_cpu_zero_dim
    if not isinstance(t, FakeTensor):
        return
    if common_device is None:
        common_device = t.device
        is_cpu_zero_dim = cpu_zero_dim(t)
        return
    t_is_cpu_zero_dim = cpu_zero_dim(t)
    if <MASK>:
        if is_cpu_zero_dim:
            is_cpu_zero_dim = t_is_cpu_zero_dim
        return
    is_bypass_zero_dim_cpu_tensor_check_op = func in bypass_zero_dim_cpu_tensor_check_ops
    if t_is_cpu_zero_dim and (not is_bypass_zero_dim_cpu_tensor_check_op):
        return
    if is_cpu_zero_dim and (not is_bypass_zero_dim_cpu_tensor_check_op):
        common_device = t.device
        is_cpu_zero_dim = t_is_cpu_zero_dim
        return
    if func in mixed_device_fns:
        if any(map(check_cpu_device, (common_device, t.device))):
            return
    prefer_device_type = torch._functorch.config.fake_tensor_prefer_device_type
    if prefer_device_type is not None:
        common_has_preferred = prefer_device_type in common_device.type
        t_has_preferred = prefer_device_type in t.device.type
        if not common_has_preferred and t_has_preferred:
            common_device = t.device
            is_cpu_zero_dim = t_is_cpu_zero_dim
            return
        elif common_has_preferred and (not t_has_preferred):
            return
    raise RuntimeError(f'Unhandled FakeTensor Device Propagation for {func}, found two different devices {common_device}, {t.device}')

def __mul__(self, other):
    other = as_expr(other)
    if isinstance(other, Expr):
        if self.op is other.op:
            if self.op in (Op.INTEGER, Op.REAL):
                return as_number(self.data[0] * other.data[0], max(self.data[1], other.data[1]))
            elif self.op is Op.COMPLEX:
                (r1, i1) = self.data
                (r2, i2) = other.data
                return as_complex(r1 * r2 - i1 * i2, r1 * i2 + r2 * i1)
            if self.op is Op.FACTORS:
                r = Expr(self.op, dict(self.data))
                for (k, v) in other.data.items():
                    _pairs_add(r.data, k, v)
                return normalize(r)
            elif self.op is Op.TERMS:
                r = Expr(self.op, {})
                for (t1, c1) in self.data.items():
                    for (t2, c2) in other.data.items():
                        _pairs_add(r.data, t1 * t2, c1 * c2)
                return normalize(r)
        if self.op is Op.COMPLEX and other.op in (Op.INTEGER, Op.REAL):
            return self * as_complex(other)
        elif other.op is Op.COMPLEX and self.op in (Op.INTEGER, Op.REAL):
            return as_complex(self) * other
        elif <MASK>:
            return self * as_real(other, kind=self.data[1])
        elif self.op is Op.INTEGER and other.op is Op.REAL:
            return as_real(self, kind=other.data[1]) * other
        if self.op is Op.TERMS:
            return self * as_terms(other)
        elif other.op is Op.TERMS:
            return as_terms(self) * other
        return as_factors(self) * as_factors(other)
    return NotImplemented

def _substitute_quantized_function_name_template(module: str) -> str:
    """Generates the quantized function name."""
    compiled_regex = re.compile('GenerateQuantizedFunctionName(\\([\\w\\s\\\'\\"\\[\\],]+\\))')
    while True:
        func_match = re.search(compiled_regex, module)
        if func_match is None:
            break
        argument_string = func_match.group(1)
        if not argument_string.endswith(',)'):
            argument_string = argument_string[:-1] + ',)'
        arguments = ast.literal_eval(argument_string)
        if <MASK>:
            raise ValueError('Wrong number of arguments to GenerateQuantizedFunctionName')
        quantized_ops = arguments[0]
        if not quantized_ops:
            raise ValueError('The quantized_ops list must not be empty')
        function_name = 'quantized_{}'.format(_format_snake_case_op_name(quantized_ops[0]))
        if len(quantized_ops) > 1:
            function_name += '_with_{}'.format(_format_snake_case_op_name(quantized_ops[1]))
        if len(quantized_ops) > 1:
            for quantized_op in quantized_ops[2:]:
                function_name += '_and_{}'.format(_format_snake_case_op_name(quantized_op))
        suffix = '_fn'
        if len(arguments) > 1 and arguments[1] == 'f32':
            suffix = '_float_output_fn'
        function_name += suffix
        module = re.sub(compiled_regex, function_name, module, count=1)
    return module

def test_function_compile_with_xla(self, enable_packed_var):
    if <MASK>:
        self.skipTest('This test triggers _XlaCompile and XlaLaunch which are not supported in tfrt yet. We should avoid using these kernels on TPU. However, it is a workaround to support b/129842431. We need more discussion about how to support it in the long term.')
    strategy = get_tpu_strategy(enable_packed_var)
    with strategy.scope():
        v = variables.Variable(1.0)

    @def_function.function
    def func():
