def export_for_aoti_minifier(gm: torch.nn.Module, tuple_inputs: tuple[Any], strict: bool=False, skip_export_error: bool=True) -> Optional[torch.nn.Module]:
    from torch._dynamo.exc import UserError, UserErrorType
    try:
        ep = torch.export.export(gm, tuple_inputs, strict=strict)
        gm = ep.module(check_guards=False)
        return gm
    except Exception as e:
        if skip_export_error:
            return None
        if <MASK>:
            return None
        if isinstance(e, RuntimeError):
            pattern = 'Found .* in output, which is not a known type\\.'
            if re.search(pattern, str(e)) is not None:
                return None
        raise AOTIMinifierError(e) from e
    return None

def matcher(self, version_string):
    version_string = version_string.replace('\n', ' ')
    pos = 0
    if start:
        m = re.match(start, version_string)
        if <MASK>:
            return None
        pos = m.end()
    while True:
        m = re.search(pat, version_string[pos:])
        if not m:
            return None
        if ignore and re.match(ignore, m.group(0)):
            pos = m.end()
            continue
        break
    return m.group(0)

def __init__(self, *expressions, distinct=False, filter=None, default=None, order_by=None, **extra):
    if distinct and (not self.allow_distinct):
        raise TypeError('%s does not allow distinct.' % self.__class__.__name__)
    if order_by and (not self.allow_order_by):
        raise TypeError('%s does not allow order_by.' % self.__class__.__name__)
    if <MASK>:
        raise TypeError(f'{self.__class__.__name__} does not allow default.')
    self.distinct = distinct
    self.filter = None if filter is None else AggregateFilter(filter)
    self.default = default
    self.order_by = AggregateOrderBy.from_param(f'{self.__class__.__name__}.order_by', order_by)
    super().__init__(*expressions, **extra)

