def most_specific_common_subtype(self, others: Sequence['FunctionType']) -> Optional['FunctionType']:
    """Returns a common subtype (if exists)."""
    subtyped_parameters = []
    for (i, parameter) in enumerate(self.parameters.values()):
        subtyped_parameter = parameter.most_specific_common_supertype([list(other.parameters.values())[i] for other in others])
        if subtyped_parameter is None:
            return None
        subtyped_parameters.append(subtyped_parameter)
    if <MASK>:
        return None
    capture_names = set(self.captures.keys())
    for other in others:
        capture_names = capture_names.union(other.captures.keys())
    subtyped_captures = collections.OrderedDict()
    for name in capture_names:
        containing = [t for t in [self, *others] if name in t.captures]
        base = containing[0]
        relevant_others = containing[1:]
        common_type = base.captures[name].most_specific_common_supertype([other.captures[name] for other in relevant_others])
        if common_type is None:
            return None
        else:
            subtyped_captures[name] = common_type
    return FunctionType(subtyped_parameters, subtyped_captures)

def visit_Call(self, node):
    if hasattr(node.func, 'id') and node.func.id == '__import__':
        try:
            name = self._grab_node_str(node.args[0])
            fromlist: list[str] = []
            level = 0
            if len(node.args) > 3:
                fromlist.extend((self._grab_node_str(v) for v in node.args[3].elts))
            elif hasattr(node, 'keywords'):
                for keyword in node.keywords:
                    if <MASK>:
                        fromlist.extend((self._grab_node_str(v) for v in keyword.value.elts))
            if len(node.args) > 4:
                level = self._grab_node_int(node.args[4])
            elif hasattr(node, 'keywords'):
                for keyword in node.keywords:
                    if keyword.arg == 'level':
                        level = self._grab_node_int(keyword.value)
            if fromlist == []:
                self.references[name, None] = True
                top_name = name.rsplit('.', maxsplit=1)[0]
                if top_name != name:
                    top_name = self._absmodule(top_name, level)
                    self.references[top_name, None] = True
            else:
                name = self._absmodule(name, level)
                for alias in fromlist:
                    if alias != '*':
                        self.references[name, alias] = True
                    else:
                        self.references[name, None] = True
        except Exception:
            return

def maybe_has_backedge(self) -> bool:
    cur_tx: Optional[InstructionTranslatorBase] = self
    while cur_tx is not None:
        cur_offset = cur_tx.current_instruction.offset
        assert cur_tx.instruction_pointer is not None
        for inst in cur_tx.instructions[cur_tx.instruction_pointer:]:
            if <MASK>:
                break
            if inst.opname in JUMP_OPNAMES:
                jump_offset = inst.argval
                if jump_offset < cur_offset:
                    return True
        cur_tx = cur_tx.parent
    return False

def call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if inspect.getattr_static(self.value, '__new__', None) == object.__new__ and self.source:
        new_obj = object.__new__(self.value)
        var = PlacementVariable(new_obj)
        if <MASK>:
            var.call_method(tx, '__init__', args, kwargs)
            return var
    return super().call_function(tx, args, kwargs)

def isdouble(var):
    if not isscalar(var):
