def _pick_config():
    nonlocal configs
    assert len(configs) > 0
    if <MASK>:
        return configs[0]
    configs = _pick_second_largest(_r0_block)
    if len(configs) == 1:
        return configs[0]
    configs = _pick_second_largest(_num_warps)
    if len(configs) == 1:
        return configs[0]
    configs = _pick_second_largest(_xblock)
    return configs[0]

