def convert_value(self, value, expression, connection):
    if isinstance(self.output_field, DateTimeField):
        if not settings.USE_TZ:
            pass
        elif <MASK>:
            value = value.replace(tzinfo=None)
            value = timezone.make_aware(value, self.tzinfo)
        elif not connection.features.has_zoneinfo_database:
            raise ValueError('Database returned an invalid datetime value. Are time zone definitions for your database installed?')
    elif isinstance(value, datetime):
        if isinstance(self.output_field, DateField):
            value = value.date()
        elif isinstance(self.output_field, TimeField):
            value = value.time()
    return value

def generate_constraints_node(self, n: Node, counter):
    """
        Generate constraints the given node:
        Currently supported operations:
        - Reshape
        - Add
        - conv2d
        """
    if n.op == 'placeholder':
        (x, counter) = gen_tvar(counter)
        self.symbol_dict[n] = x
        my_type = n.type
        if n.type != Dyn and (not isinstance(n.type, TensorType)):
            if n.type == torch.nn.parameter.Parameter:
                assert 'example_value' in n.meta
                my_type = TensorType(n.meta['example_value'].size())
            else:
                my_type = Dyn
        c1 = BinConstraintT(my_type, x, op_precision)
        c2 = BinConstraintT(x, MAX_TENSOR_RANK, op_leq)
        return ([c1, c2], counter)
    elif n.op == 'call_function':
        if n.target in _INFERENCE_RULES:
            return _INFERENCE_RULES[n.target](n, self.symbol_dict, self.constraints, counter)
        else:
            raise RuntimeError(f'No inference rule registered for target {n.target}!')
    elif n.op == 'call_module':
        module_instance = self.traced.get_submodule(n.target)
        if type(module_instance) in _INFERENCE_RULES:
            return _INFERENCE_RULES[type(module_instance)](n, module_instance, self.symbol_dict, self.constraints, counter)
        else:
            raise RuntimeError(f'No inference rule registered for class {type(module_instance)}!')
    elif <MASK>:
        if n.target in _INFERENCE_RULES:
            return _INFERENCE_RULES[n.target](n, self.symbol_dict, self.constraints, counter)
        else:
            raise RuntimeError(f'No inference rule registered for target {n.target}!')
    elif n.op == 'get_attr':
        t = self.traced_params.get(n.target, None)
        if isinstance(t, torch.Tensor):
            if len(t.shape) > 0:
                res = list(t.shape)
                attr_type = TensorType(res)
                (output, counter) = gen_tvar(counter)
                self.symbol_dict[n] = output
                return ([BinConstraintT(output, attr_type, op_eq)], counter)
            else:
                return ([], counter)
        else:
            return ([], counter)
    elif n.op == 'output':
        return ([], counter)
    else:
        raise NotImplementedError(f'Method {n.op} not yet implemented')

def persistent_load(saved_id):
    assert isinstance(saved_id, tuple)
    typename = _maybe_decode_ascii(saved_id[0])
    data = saved_id[1:]
    if typename == 'module':
        if all(data[1:]):
            _check_container_source(*data)
        return data[0]
    elif typename == 'storage':
        (storage_type, root_key, location, numel, view_metadata) = data
        location = _maybe_decode_ascii(location)
        dtype = storage_type.dtype
        nbytes = numel * torch._utils._element_size(dtype)
        if root_key not in deserialized_objects:
            if torch._guards.active_fake_mode() is not None:
                obj = cast(Storage, torch.UntypedStorage(nbytes, device='meta'))
            elif <MASK>:
                obj = cast(Storage, torch.UntypedStorage(nbytes))
                obj = restore_location(obj, location)
            else:
                obj = cast(Storage, torch.UntypedStorage(nbytes))
                obj._torch_load_uninitialized = True
                obj = restore_location(obj, location)
            typed_storage = torch.storage.TypedStorage(wrap_storage=obj, dtype=dtype, _internal=True)
            deserialized_objects[root_key] = typed_storage
        else:
            typed_storage = deserialized_objects[root_key]
            if typed_storage._data_ptr() == 0:
                typed_storage = torch.storage.TypedStorage(device=typed_storage._untyped_storage.device, dtype=dtype, _internal=True)
        if view_metadata is not None:
            (view_key, offset, view_size) = view_metadata
            offset_bytes = offset * torch._utils._element_size(dtype)
            view_size_bytes = view_size * torch._utils._element_size(dtype)
            if view_key not in deserialized_objects:
                deserialized_objects[view_key] = torch.storage.TypedStorage(wrap_storage=typed_storage._untyped_storage[offset_bytes:offset_bytes + view_size_bytes], dtype=dtype, _internal=True)
            res = deserialized_objects[view_key]
        else:
            res = typed_storage
        return res
    else:
        raise RuntimeError(f'Unknown saved id type: {saved_id[0]}')

def var_getattr(self, tx: 'InstructionTranslator', name):
    from ..utils import numpy_attr_wrapper
    from .builder import wrap_fx_proxy
    result = None
    example_value = self.as_proxy().node.meta['example_value']
    example_ndarray = tnp.ndarray(example_value)

    def insert_into_graph():
        return wrap_fx_proxy(tx, tx.output.create_proxy('call_function', numpy_attr_wrapper, (self.as_proxy(), name), {}))
    if name in ['T', 'real', 'imag']:
        proxy = tx.output.create_proxy('call_function', numpy_attr_wrapper, (self.as_proxy(), name), {})
        result = NumpyNdarrayVariable.create(tx, proxy)
    elif name in ('ndim', 'itemsize'):
        return ConstantVariable.create(getattr(example_ndarray, name))
    elif name in ('shape', 'stride'):
        if not has_free_symbols((r := getattr(example_ndarray, name))):
            return ConstantVariable.create(tuple((int(r) for r in r)))
        return insert_into_graph()
    elif <MASK>:
        if not has_free_symbols((r := example_ndarray.size)):
            return ConstantVariable.create(int(r))
        return insert_into_graph()
    elif name in ['base', 'flags', 'dtype']:
        unimplemented_v2(gb_type='Unsupported ndarray attribute access', context=f'var_getattr {self} {name}', explanation=f'Dynamo currently does not support tracing `ndarray.{name}`.', hints=[])
    elif name == '__version__':
        unimplemented_v2(gb_type='Unsupported ndarray.__version__ access', context=f'var_getattr {self} {name}', explanation=f'Dynamo currently does not support tracing `ndarray.{name}`.', hints=[])
    if result is None:
        raise NotImplementedError
    return result

def _graph_execution_trace_from_debug_event_proto(self, debug_event, locator):
    """Convert a DebugEvent proto into a GraphExecutionTrace data object."""
    trace_proto = debug_event.graph_execution_trace
    graph_ids = [trace_proto.tfdbg_context_id]
    while True:
        graph = self.graph_by_id(graph_ids[0])
        if <MASK>:
            graph_ids.insert(0, graph.outer_graph_id)
        else:
            break
    if trace_proto.tensor_debug_mode == debug_event_pb2.TensorDebugMode.FULL_TENSOR:
        debug_tensor_value = None
    else:
        debug_tensor_value = _parse_tensor_value(trace_proto.tensor_proto, return_list=True)
    return GraphExecutionTrace(self._graph_execution_trace_digest_from_debug_event_proto(debug_event, locator), graph_ids=graph_ids, tensor_debug_mode=trace_proto.tensor_debug_mode, debug_tensor_value=debug_tensor_value, device_name=trace_proto.device_name or None)

def freeze_graph_with_def_protos(input_graph_def: Optional[graph_pb2.GraphDef], input_saver_def: Optional[saver_pb2.SaverDef], input_checkpoint: Optional[str], output_node_names: str, restore_op_name: Optional[str], filename_tensor_name: Optional[str], output_graph: str, clear_devices: bool, initializer_nodes: str, variable_names_whitelist: str='', variable_names_denylist: str='', input_meta_graph_def: Optional[meta_graph_pb2.MetaGraphDef]=None, input_saved_model_dir: Optional[str]=None, saved_model_tags: Optional[List[str]]=None, checkpoint_version: int=saver_pb2.SaverDef.V2) -> graph_pb2.GraphDef:
    """Converts all variables in a graph and checkpoint into constants.

  Args:
    input_graph_def: A `GraphDef`.
    input_saver_def: A `SaverDef` (optional).
    input_checkpoint: The prefix of a V1 or V2 checkpoint, with V2 taking
      priority.  Typically the result of `Saver.save()` or that of
      `tf.train.latest_checkpoint()`, regardless of sharded/non-sharded or
      V1/V2.
    output_node_names: The name(s) of the output nodes, comma separated.
    restore_op_name: Unused.
    filename_tensor_name: Unused.
    output_graph: String where to write the frozen `GraphDef`.
    clear_devices: A Bool whether to remove device specifications.
    initializer_nodes: Comma separated string of initializer nodes to run before
      freezing.
    variable_names_whitelist: The set of variable names to convert (optional, by
      default, all variables are converted).
    variable_names_denylist: The set of variable names to omit converting to
      constants (optional).
    input_meta_graph_def: A `MetaGraphDef` (optional),
    input_saved_model_dir: Path to the dir with TensorFlow 'SavedModel' file and
      variables (optional).
    saved_model_tags: Group of comma separated tag(s) of the MetaGraphDef to
      load, in string format (optional).
    checkpoint_version: Tensorflow variable file format (saver_pb2.SaverDef.V1
      or saver_pb2.SaverDef.V2)

  Returns:
    Location of the output_graph_def.
  """
    del restore_op_name, filename_tensor_name
    if <MASK>:
        raise ValueError("Input checkpoint '" + input_checkpoint + "' doesn't exist!")
    if not output_node_names:
        raise ValueError('You need to supply the name of a node to --output_node_names.')
    if clear_devices:
        if input_meta_graph_def:
            for node in input_meta_graph_def.graph_def.node:
                node.device = ''
        elif input_graph_def:
            for node in input_graph_def.node:
                node.device = ''
    if input_graph_def:
        _ = importer.import_graph_def(input_graph_def, name='')
    with session.Session() as sess:
        if input_saver_def:
            saver = saver_lib.Saver(saver_def=input_saver_def, write_version=checkpoint_version)
            saver.restore(sess, input_checkpoint)
        elif input_meta_graph_def:
            restorer = saver_lib.import_meta_graph(input_meta_graph_def, clear_devices=True)
            restorer.restore(sess, input_checkpoint)
            if initializer_nodes:
                sess.run(initializer_nodes.replace(' ', '').split(','))
        elif input_saved_model_dir:
            if saved_model_tags is None:
                saved_model_tags = []
            loader.load(sess, saved_model_tags, input_saved_model_dir)
        else:
            var_list = {}
            reader = py_checkpoint_reader.NewCheckpointReader(input_checkpoint)
            var_to_shape_map = reader.get_variable_to_shape_map()
            all_partition_variable_names = [tensor.name.split(':')[0] for op in sess.graph.get_operations() for tensor in op.values() if re.search('/part_\\d+/', tensor.name)]
            has_partition_var = False
            for key in var_to_shape_map:
                try:
                    tensor = sess.graph.get_tensor_by_name(key + ':0')
                    if any((key in name for name in all_partition_variable_names)):
                        has_partition_var = True
                except KeyError:
                    continue
                var_list[key] = tensor
            try:
                saver = saver_lib.Saver(var_list=var_list, write_version=checkpoint_version)
            except TypeError as e:
                if has_partition_var:
                    raise ValueError('Models containing partition variables cannot be converted from checkpoint files. Please pass in a SavedModel using the flag --input_saved_model_dir.')
                elif _has_no_variables(sess):
                    raise ValueError('No variables were found in this model. It is likely the model was frozen previously. You cannot freeze a graph twice.')
                else:
                    raise e
            saver.restore(sess, input_checkpoint)
            if initializer_nodes:
                sess.run(initializer_nodes.replace(' ', '').split(','))
        variable_names_whitelist = variable_names_whitelist.replace(' ', '').split(',') if variable_names_whitelist else None
        variable_names_denylist = variable_names_denylist.replace(' ', '').split(',') if variable_names_denylist else None
        if input_meta_graph_def:
            output_graph_def = convert_to_constants.convert_variables_to_constants(sess, input_meta_graph_def.graph_def, output_node_names.replace(' ', '').split(','), variable_names_whitelist=variable_names_whitelist, variable_names_blacklist=variable_names_denylist)
        else:
            output_graph_def = convert_to_constants.convert_variables_to_constants(sess, input_graph_def, output_node_names.replace(' ', '').split(','), variable_names_whitelist=variable_names_whitelist, variable_names_blacklist=variable_names_denylist)
    if output_graph:
        with gfile.GFile(output_graph, 'wb') as f:
            f.write(output_graph_def.SerializeToString(deterministic=True))
    return output_graph_def

def decorator(f: _F) -> _F:

    @functools.wraps(f)
    def decorated(*args, **kwargs):
        original_xla_flags = os.environ.get('XLA_FLAGS')
        new_xla_flags = flag
        if <MASK>:
            new_xla_flags = new_xla_flags + ' ' + original_xla_flags
        os.environ['XLA_FLAGS'] = new_xla_flags
        try:
            return f(*args, **kwargs)
        finally:
            if original_xla_flags is None:
                del os.environ['XLA_FLAGS']
            else:
                os.environ['XLA_FLAGS'] = original_xla_flags
    return decorated

def _parse_tables(self, document, match, attrs):
    element_name = 'table'
    tables = document.find_all(element_name, attrs=attrs)
    if <MASK>:
        raise ValueError('No tables found')
    result = []
    unique_tables = set()
    tables = self._handle_hidden_tables(tables, 'attrs')
    for table in tables:
        if self.displayed_only:
            for elem in table.find_all('style'):
                elem.decompose()
            for elem in table.find_all(style=re.compile('display:\\s*none')):
                elem.decompose()
        if table not in unique_tables and table.find(string=match) is not None:
            result.append(table)
        unique_tables.add(table)
    if not result:
        raise ValueError(f'No tables found matching pattern {match.pattern!r}')
    return result

def __call__(self, func):
    if <MASK>:
        raise ValueError(f'Function {func} must be a callable.')
    argspec = tf_inspect.getargspec(func)
    if argspec.keywords or argspec.defaults:
        raise ValueError(f'Functions with argument defaults or keywords arguments are not supported. {func} has defaults {argspec.defaults} and keywords {argspec.keywords}.')
    min_args = len(argspec.args)
    max_args = min_args
    if argspec.varargs:
        max_args = 1000000
    argnames = argspec.args
    if tf_inspect.ismethod(func):
        min_args -= 1
        argnames = argnames[1:]
    if self._input_types:
        num = len(self._input_types)
        if num < min_args or num > max_args:
            raise ValueError(f'The number of tf.function input types is not compatible with the allowed arguments of {func}. The tf.function have {num} input types, while the python function allows minimum {min_args} and maximum {max_args} arguments.')
        return _DefinedFunction(func, argnames, self._input_types, self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)
    if min_args == 0 and max_args == 0:
        return _DefinedFunction(func, [], [], self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)
    return _OverloadedFunction(func, argnames, self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)

@register_lowering(aten.constant_pad_nd, type_promotion_kind=None)
def constant_pad_nd(x, padding, fill_value=0):
    assert len(padding) % 2 == 0
    if all((p == 0 for p in padding)):
        return clone(x)
    if config.inplace_padding:
        out = inplace_constant_pad_nd(x, padding, fill_value)
        if <MASK>:
            return out
    sizes = x.get_size()
    bounds = list(reversed(list(zip(padding[::2], padding[1::2]))))
    n = len(sizes) - len(bounds)
    bounds_precomp: list[tuple[sympy.Symbol, Any]] = []
    for (l, h) in bounds:
        bounds_precomp.append((V.graph.sizevars.lookup_precomputed_size(l), h))
    output_size = list(sizes[:n])
    mask_sizes = []
    for ((low, high), size) in zip(bounds, sizes[n:]):
        mask_sizes.append(size)
        output_size.append(sympy.expand(size + low + high))
    assert len(output_size) == len(sizes)
    fill_value = dtype_to_type(x.get_dtype())(fill_value)

    def mask(index):
        mask = []
        for (idx, (low, high), length) in zip(index[n:], bounds, mask_sizes):
            if low != 0:
                mask.append(range_mask_low(idx, 0))
            if high != 0:
                mask.append(range_mask_high(idx, length))
        mask = functools.reduce(ops.and_, mask)
        return ops.masked(mask, lambda : x_loader(index), fill_value)

    def offset_fn(index):
        new_index = list(index[:n])
        for (idx, (low, _high)) in zip(index[n:], bounds_precomp):
            new_index.append(idx - low)
        assert len(new_index) == len(index)
        return mask(new_index)
    x_loader = x.make_loader()
    return Pointwise.create(device=x.get_device(), dtype=x.get_dtype(), inner_fn=offset_fn, ranges=output_size)

@classmethod
def can_fuse(cls, producer: BaseSchedulerNode, consumer: BaseSchedulerNode) -> bool:
    why = WhyNoFuse(producer, consumer)
    if producer.is_foreach() and consumer.is_foreach():
        producer = typing.cast(ForeachKernelSchedulerNode, producer)
        consumer = typing.cast(ForeachKernelSchedulerNode, consumer)
        foreach_match = len(producer.snodes) == len(consumer.snodes)
        if not foreach_match:
            why('foreach do not have same length')
        return foreach_match and all((producer.scheduler.can_fuse(l, r) for (l, r) in zip(producer.snodes, consumer.snodes)))
    elif consumer.is_foreach():
        if <MASK>:
            why('candidate producer is a reduction, foreach ops cannot be fused with reductions currently')
            return False
        consumer = typing.cast(ForeachKernelSchedulerNode, consumer)
        consumer_subnode = consumer.get_consumer_subnode_for(producer)
        if consumer_subnode is not None:
            return consumer.scheduler.can_fuse(producer, consumer_subnode)
        why('candidate producer is not dep of any foreach consumer')
        return False
    elif producer.is_foreach():
        if consumer.is_reduction():
            why('candidate consumer is a reduction, foreach ops cannot be fused with reductions currently')
            return False
        producer = typing.cast(ForeachKernelSchedulerNode, producer)
        producer_subnode = producer.get_producer_subnode_for(consumer)
        if producer_subnode is not None:
            return producer.scheduler.can_fuse(producer_subnode, consumer)
        why('candidate consumer has no dep in any foreach producer')
        return False
    raise AssertionError('At least one node passed to ForeachKernelSchedulerNode.can_fuse should be a foreach node')

def __iter__(self):
    if <MASK>:
        raise TypeError('iteration over a 0-d tensor')
    if torch._C._get_tracing_state():
        warnings.warn("Iterating over a tensor might cause the trace to be incorrect. Passing a tensor of different shape won't change the number of iterations executed (and might lead to errors or silently give incorrect results).", category=torch.jit.TracerWarning, stacklevel=2)
    return iter(self.unbind(0))

def _check_for_import_lib():
    """Check if an import library for the Python runtime already exists."""
    (major_version, minor_version) = tuple(sys.version_info[:2])
    patterns = ['libpython%d%d.a', 'libpython%d%d.dll.a', 'libpython%d.%d.dll.a']
    stems = [sys.prefix]
    if hasattr(sys, 'base_prefix') and sys.base_prefix != sys.prefix:
        stems.append(sys.base_prefix)
    elif <MASK>:
        stems.append(sys.real_prefix)
    sub_dirs = ['libs', 'lib']
    candidates = []
    for pat in patterns:
        filename = pat % (major_version, minor_version)
        for stem_dir in stems:
            for folder in sub_dirs:
                candidates.append(os.path.join(stem_dir, folder, filename))
    for fullname in candidates:
        if os.path.isfile(fullname):
            return (True, fullname)
    return (False, candidates[0])

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName) -> NamedCType:
    r = cpp.valuetype_type(t, symint=False, binds=binds, mutable=mutable)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if <MASK>:
            return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, BaseCType(optionalTensorRefT))
        elif t.elem == BaseType(BaseTy.Scalar):
            return NamedCType(binds, BaseCType(optionalScalarRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
        elif t.elem == OptionalType(BaseType(BaseTy.Tensor)):
            return NamedCType(binds, BaseCType(iOptTensorListRefT))
        elif str(t.elem) == 'int':
            return NamedCType(binds, BaseCType(intArrayRefT))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

def _tensors_match(a, b, exact=True, rtol=1e-05, atol=1e-08):
    if is_masked_tensor(a) or is_masked_tensor(b):
        raise ValueError('Neither `a` nor `b` can be a MaskedTensor.')
    if <MASK>:
        raise ValueError(f'`a` and `b` must have the same layout. Got {a.layout} and {b.layout}')
    if a.dtype != b.dtype:
        b = b.type(a.dtype)
    if a.layout == b.layout == torch.sparse_coo:
        return _tensors_match(a.values(), b.values(), exact) and _tensors_match(a.indices(), b.indices(), exact)
    elif a.layout == b.layout == torch.sparse_csr:
        return _tensors_match(a.crow_indices(), b.crow_indices(), exact) and _tensors_match(a.col_indices(), b.col_indices(), exact) and _tensors_match(a.values(), b.values(), exact)
    if exact:
        return a.dim() == b.dim() and torch.eq(a, b).all().item()
    return a.dim() == b.dim() and torch.allclose(a, b, rtol=rtol, atol=atol)

@staticmethod
def create_debug_dir(folder_name: str) -> Optional[str]:
    debug_dir = config.trace.debug_dir or get_debug_dir()
    for n in DebugContext._counter:
        dirname = os.path.join(debug_dir, 'torchinductor', f'{folder_name}.{n}')
        if <MASK>:
            os.makedirs(dirname)
            return dirname
    return None

@classmethod
def _add_delegate_accessors(cls, delegate, accessors: list[str], typ: str, overwrite: bool=False, accessor_mapping: Callable[[str], str]=lambda x: x, raise_on_missing: bool=True) -> None:
    """
        Add accessors to cls from the delegate class.

        Parameters
        ----------
        cls
            Class to add the methods/properties to.
        delegate
            Class to get methods/properties and docstrings.
        accessors : list of str
            List of accessors to add.
        typ : {'property', 'method'}
        overwrite : bool, default False
            Overwrite the method/property in the target class if it exists.
        accessor_mapping: Callable, default lambda x: x
            Callable to map the delegate's function to the cls' function.
        raise_on_missing: bool, default True
            Raise if an accessor does not exist on delegate.
            False skips the missing accessor.
        """

    def _create_delegator_property(name: str):

        def _getter(self):
            return self._delegate_property_get(name)

        def _setter(self, new_values):
            return self._delegate_property_set(name, new_values)
        _getter.__name__ = name
        _setter.__name__ = name
        return property(fget=_getter, fset=_setter, doc=getattr(delegate, accessor_mapping(name)).__doc__)

    def _create_delegator_method(name: str):
        method = getattr(delegate, accessor_mapping(name))

        @functools.wraps(method)
        def f(self, *args, **kwargs):
            return self._delegate_method(name, *args, **kwargs)
        return f
    for name in accessors:
        if not raise_on_missing and getattr(delegate, accessor_mapping(name), None) is None:
            continue
        if typ == 'property':
            f = _create_delegator_property(name)
        else:
            f = _create_delegator_method(name)
        if <MASK>:
            setattr(cls, name, f)

def isValueType(typ: CType, properties: LazyIrProperties | None=None) -> bool:
    """
    Given a type, determine if it is a Value-like type.  This is equivalent to
    being Tensor-like, but assumes the type has already been transformed.
    """
    if isinstance(typ, BaseCType):
        treat_scalars_as_constants = properties and properties.TreatScalarsAsConstants
        return typ.type == getValueT() or (typ.type == scalarT and (not treat_scalars_as_constants)) or typ.type == SymIntT
    elif <MASK>:
        return False
    elif isinstance(typ, (OptionalCType, ListCType, VectorCType)):
        return isValueType(typ.elem, properties)
    return False

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    """
        Fit the OrdinalEncoder to X.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            The data to determine the categories of each feature.

        y : None
            Ignored. This parameter exists only for compatibility with
            :class:`~sklearn.pipeline.Pipeline`.

        Returns
        -------
        self : object
            Fitted encoder.
        """
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif self.unknown_value is not None:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if <MASK>:
        for (feature_idx, infrequent) in enumerate(self.infrequent_categories_):
            if infrequent is not None:
                cardinalities[feature_idx] -= len(infrequent)
    for (cat_idx, categories_for_idx) in enumerate(self.categories_):
        if is_scalar_nan(categories_for_idx[-1]):
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for (cat_idx, cardinality) in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

def visit_Constant(self, node):
    cst_name = self._ssa_name('cst')
    if node.value is None:
        cst_ty = TFRTypes.NONE
    elif <MASK>:
        cst_ty = self._get_inferred_type(node)
        cst_val = str(node.value).lower()
        self._emit_with_loc('\n{} = arith.constant {}'.format(cst_name, cst_val), node)
    else:
        cst_ty = self._get_inferred_type(node)
        cst_val = node.value
        if cst_ty == TFRTypes.ATTR:
            self._emit_with_loc('\n{} = tfr.constant "{}" -> {}'.format(cst_name, cst_val, cst_ty), node)
        else:
            self._emit_with_loc('\n{} = arith.constant {} : {}'.format(cst_name, cst_val, cst_ty), node)
    return (cst_name, cst_ty)

def inner(self):
    try:
        op = torch._library.utils.lookup_op(qualname)
    except AttributeError as e:
        raise unittest.SkipTest(f"Can't import operator {qualname}") from e
    op_marked_as_compliant = torch.Tag.pt2_compliant_tag in op.tags
    if <MASK>:
        return
    if not definitely_not_pt2_compliant:
        return
    raise AssertionError(f"op '{qualname}' was tagged with torch.Tag.pt2_compliant_tag but it failed some of the generated opcheck tests ({xfailed_tests}). This may lead to silent correctness issues, please fix this.")

def filter_reduction_configs_for_determinism(inductor_meta: dict[str, Any], configs: list[Config]) -> list[Config]:
    """
    Filter configs for reduction so the numerics can be deterministic.

    Heuristics:
    - skip reduction configs with too small RBLOCK
    - skip reduction configs with XBLOCK==1 if we are confident it will not perform well
    - if there is a tie, pick the config with second largest RBLOCK
    - if there is still a tie, pick the config with second largest num_warps
    - if there is still a tie, pick the config with second largest XBLOCK
    """
    configs = unique_configs(configs)
    assert len(configs) > 0

    def _do_filter_due_to_inductor_config():
        return (inductor_meta.get('deterministic', False) or inductor_meta.get('force_filter_reduction_configs', False)) or inductor_meta.get('are_deterministic_algorithms_enabled')
    if not _do_filter_due_to_inductor_config() or len(configs) == 1:
        return configs
    if log.isEnabledFor(logging.DEBUG):
        log.debug('reduction configs before filtering:')
        for c in configs:
            log.debug('%s', c)
            log.debug('')

    def _has_too_small_rblock(config):
        rblock = config.kwargs.get('R0_BLOCK')
        return rblock is not None and rblock <= 4

    def _nonpromising_xblock_1(config):
        return config.kwargs['XBLOCK'] == 1 and (not inductor_meta.get('has_loadstore_with_contiguous_rdim', True))
    newconfigs = [*filter(lambda x: not _has_too_small_rblock(x), configs)]
    if <MASK>:
        configs = newconfigs
    newconfigs = [*filter(lambda x: not _nonpromising_xblock_1(x), configs)]
    if len(newconfigs) > 0:
        configs = newconfigs
    assert len(configs) > 0

    def _r0_block(c):
        return c.kwargs.get('R0_BLOCK', -1)

    def _xblock(c):
        return c.kwargs.get('XBLOCK', -1)

    def _num_warps(c):
        return c.num_warps

    def _pick_second_largest(accessor):
        nonlocal configs
        configs = sorted(configs, key=lambda x: accessor(x))
        if accessor(configs[0]) != accessor(configs[-1]):
            max_val = accessor(configs[-1])
            configs = [*filter(lambda x: accessor(x) != max_val, configs)]
            second_max_val = accessor(configs[-1])
            configs = [*filter(lambda x: accessor(x) == second_max_val, configs)]
        return configs

    def _pick_config():
        nonlocal configs
        assert len(configs) > 0
        if len(configs) == 1:
            return configs[0]
        configs = _pick_second_largest(_r0_block)
        if len(configs) == 1:
            return configs[0]
        configs = _pick_second_largest(_num_warps)
        if len(configs) == 1:
            return configs[0]
        configs = _pick_second_largest(_xblock)
        return configs[0]
    configs = [_pick_config()]
    if log.isEnabledFor(logging.DEBUG):
        log.debug('reduction configs after filtering:')
        for c in configs:
            log.debug('%s', c)
            log.debug('')
    return configs

@property
