                        else:
                            af |= bf
                _recursive_or(_data._mask, mask)
            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

def fixup_branch_inps(graph, lifted_freevars, shared, unique_l, unique_r):

    def _insert_or_replace_phs(new_args, name_suffix):
        for arg in new_args:
            new_ph = graph.placeholder(arg.node.name + name_suffix)
            new_ph.meta = arg.node.meta
            if <MASK>:
                old_ph = lifted_freevars[arg].node
                old_ph.replace_all_uses_with(new_ph)
                old_ph.users = {}
                graph.erase_node(old_ph)
    first_not_ph_node = next((node for node in graph.nodes if node.op != 'placeholder'))
    with graph.inserting_before(first_not_ph_node):
        _insert_or_replace_phs(shared, '')
        _insert_or_replace_phs(unique_l, '_' + l_name)
        _insert_or_replace_phs(unique_r, '_' + r_name)

def _validate_cache_key(self, func: OpOverload, args: Sequence[object], kwargs: Mapping[str, object]) -> None:
    """
        Validate that the cache key generated by _cache_key will be
        reasonable.
        """
    from torch._higher_order_ops.utils import registered_hop_fake_fns
    if isinstance(func, torch._ops.HigherOrderOperator) and func in registered_hop_fake_fns:
        return
    if torch.Tag.data_dependent_output in func.tags:
        raise _BypassDispatchCache('data dependent output')
    if torch.Tag.dynamic_output_shape in func.tags:
        if func is aten.index.Tensor:
            (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
            for index in new_kwargs['indices']:
                if isinstance(index, torch.Tensor) and index.dtype in (torch.bool, torch.int8):
                    raise _BypassDispatchCache('dynamic output shape')
            return
        raise _BypassDispatchCache('dynamic output shape')
    if torch.Tag.inplace_view in func.tags:
        raise _BypassDispatchCache('inplace view')
    if func == aten._unsafe_view.default:
        raise _BypassDispatchCache('unsafe view')
    if func in self.lift_fns:
        raise _BypassDispatchCache('lift')
    if <MASK>:
        raise _BypassDispatchCache('inductor::resize_storage_bytes_')
    if not torch._library.utils.is_builtin(func):
        raise _BypassDispatchCache('non-builtin')
    if func.is_view and torch._C._dispatch_has_kernel_for_dispatch_key(func.name(), torch._C.DispatchKey.CompositeImplicitAutograd):
        raise _BypassDispatchCache('CompositeImplicitAutograd')

@numba.jit(nopython=True, nogil=True, parallel=False)
def sliding_mean(values: np.ndarray, result_dtype: np.dtype, start: np.ndarray, end: np.ndarray, min_periods: int) -> tuple[np.ndarray, list[int]]:
    N = len(start)
    nobs = 0
    sum_x = 0.0
    neg_ct = 0
    compensation_add = 0.0
    compensation_remove = 0.0
    is_monotonic_increasing_bounds = is_monotonic_increasing(start) and is_monotonic_increasing(end)
    output = np.empty(N, dtype=result_dtype)
    for i in range(N):
        s = start[i]
        e = end[i]
        if i == 0 or not is_monotonic_increasing_bounds:
            prev_value = values[s]
            num_consecutive_same_value = 0
            for j in range(s, e):
                val = values[j]
                (nobs, sum_x, neg_ct, compensation_add, num_consecutive_same_value, prev_value) = add_mean(val, nobs, sum_x, neg_ct, compensation_add, num_consecutive_same_value, prev_value)
        else:
            for j in range(start[i - 1], s):
                val = values[j]
                (nobs, sum_x, neg_ct, compensation_remove) = remove_mean(val, nobs, sum_x, neg_ct, compensation_remove)
            for j in range(end[i - 1], e):
                val = values[j]
                (nobs, sum_x, neg_ct, compensation_add, num_consecutive_same_value, prev_value) = add_mean(val, nobs, sum_x, neg_ct, compensation_add, num_consecutive_same_value, prev_value)
        if nobs >= min_periods and nobs > 0:
            result = sum_x / nobs
            if num_consecutive_same_value >= nobs:
                result = prev_value
            elif neg_ct == 0 and result < 0:
                result = 0
            elif neg_ct == nobs and result > 0:
                result = 0
        else:
            result = np.nan
        output[i] = result
        if <MASK>:
            nobs = 0
            sum_x = 0.0
            neg_ct = 0
            compensation_remove = 0.0
    na_pos = [0 for i in range(0)]
    return (output, na_pos)

def ragged_to_dense_outside_compilation(inp, weight, batch_size, feature):
    if weight is None:
        weight = ragged_tensor.RaggedTensor.from_row_splits(array_ops.ones_like(inp.values, dtype=dtypes.float32), inp.row_splits)
    if not feature.output_shape and feature.max_sequence_length > 0:
        inp = inp.to_tensor(shape=(batch_size, feature.max_sequence_length))
        weight = array_ops.ones_like(inp, dtype=dtypes.float32)
    elif feature.output_shape:
        with ops.init_scope():
            output_batch_size = math_ops.reduce_prod(feature.output_shape).numpy()
        if output_batch_size == batch_size:
            (inp, weight) = (inp.to_tensor(), weight.to_tensor())
        elif <MASK>:
            seq_length = output_batch_size // batch_size
            inp = inp.to_tensor(shape=(batch_size, seq_length))
            weight = array_ops.ones_like(inp, dtype=dtypes.float32)
        else:
            raise ValueError('Output shape set in the FeatureConfig should be the factor of the input data batch size. But instead got output shape {}, input data batch size {}'.format(feature.output_shape, batch_size))
    else:
        (inp, weight) = (inp.to_tensor(), weight.to_tensor())
    return (inp, weight)

def _verify_state_dict(model_state_dict: dict[str, ValueType], optim_state_dict: OptimizerStateType, info: _StateDictInfo) -> None:
    for module in info.fsdp_modules:
        fsdp_state = _get_module_fsdp_state_if_fully_sharded_module(module)
        if <MASK>:
            raise AssertionError('Expected a fsdp_state with a fsdp module.')
    if info.handle_model and (not model_state_dict) and (not info.submodule_prefixes) and (not info.ignore_frozen_params) and (not (info.cpu_offload and info.full_state_dict)) and info.strict and (not info.broadcast_from_rank0):
        raise RuntimeError(f'The option indicates that model state_dict is required to save or load, but model state_dict is empty.rank = dist.get_rank()={dist.get_rank()!r}.')
    if info.handle_optim:
        if not optim_state_dict and (not (info.cpu_offload and info.full_state_dict)) and (not info.broadcast_from_rank0):
            raise RuntimeError(f'The option indicates that model state_dict is required to save, or load but optim state_dict is empty. {optim_state_dict}')
    for key in model_state_dict.keys():
        if _FLAT_PARAM in key:
            raise RuntimeError(f'{key} contains {_FLAT_PARAM}. This can happen if the model is not the root module.')

def call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if <MASK>:
        return call_random_fn(tx, self.value, args, kwargs)
    elif istype(self.value, types.MethodType):
        func = self.value.__func__
        obj = self.value.__self__
        if func is torch.utils._contextlib._DecoratorContextManager.clone and variables.TorchCtxManagerClassVariable.is_matching_cls(obj.__class__) and (not (args or kwargs)):
            return variables.TorchCtxManagerClassVariable(obj.__class__).call_function(tx, args, kwargs)
        if func is torch.autograd.grad_mode.inference_mode.clone and obj.__class__ is torch.autograd.grad_mode.inference_mode:
            var = variables.ConstantVariable(obj.mode)
            return variables.TorchCtxManagerClassVariable(obj.__class__).call_function(tx, [var], kwargs)
        if self.source is None:
            unimplemented_v2(gb_type='attempted to call sourceless user-defined object as a method', context=f'object={self.value}, function={func}, args={args}, kwargs={kwargs}', explanation='Dynamo does not support this.', hints=[f'Ensure the user-defined object {self.value} is constructed outside the compiled region.'])
        func_src = AttrSource(self.source, '__func__')
        func_var = VariableTracker.build(tx, func, func_src)
        obj_src = AttrSource(self.source, '__self__')
        obj_var = VariableTracker.build(tx, obj, obj_src)
        return func_var.call_function(tx, [obj_var] + args, kwargs)
    elif callable(self.value):
        if self.source:
            source = AttrSource(self.cls_source, '__call__')
            install_guard(source.make_guard(GuardBuilder.FUNCTION_MATCH))
        return self.call_method(tx, '__call__', args, kwargs)
    return super().call_function(tx, args, kwargs)

def check_function_argument_count(func, input_arity, infeed_queue):
    """Validate the number of input arguments to an XLA function.

  Args:
    func: the Python function that will be called to generate the body of an XLA
      computation graph.
    input_arity: the number of explicit arguments supplied by the caller.
    infeed_queue: if not None, the infeed queue that will supply
      additional arguments to the function.

  Returns:
    None if function can be called with the supplied number of
      arguments, or an error string if it cannot.
  """

    def format_error(complaint, quantity):
        return '%s %d argument%s' % (complaint, quantity, '' if quantity == 1 else 's')
    num_args_supplied = input_arity
    if infeed_queue is not None:
        num_args_supplied += infeed_queue.number_of_tuple_elements
    arg_spec = tf_inspect.getargspec(func)
    num_func_args = len(arg_spec.args)
    if arg_spec.defaults is None:
        num_func_defaults = 0
    else:
        num_func_defaults = len(arg_spec.defaults)
    min_func_args = num_func_args - num_func_defaults
    if num_args_supplied < min_func_args:
        if num_func_defaults == 0 and arg_spec.varargs is None:
            return format_error('exactly', num_func_args)
        else:
            return format_error('at least', min_func_args)
    if <MASK>:
        if num_func_defaults == 0:
            return format_error('exactly', num_func_args)
        else:
            return format_error('at most', num_func_args)
    return None

def handle_is(tx: 'InstructionTranslator', left, right):
    if type(left) is not type(right):
        return ConstantVariable.create(op.__name__ != 'is_')
    if <MASK>:
        return ConstantVariable.create(op(left, right))
    if istype(left, variables.ExceptionVariable) and istype(right, variables.ExceptionVariable) and (left.exc_type is not right.exc_type):
        return ConstantVariable.create(op(left, right))

def _is_literal(arg):
    if <MASK>:
        return True
    if isinstance(arg, (tuple, list)):
        return all(map(_is_literal, arg))
    return False

def wrap_node(x):
    if isinstance(x, SymNode) and x.constant is not None:
        return x.constant
    if x.is_int():
        return SymInt(x)
    elif x.is_float():
        return SymFloat(x)
    elif <MASK>:
        return SymBool(x)
    else:
        raise AssertionError(f'unrecognized return type {x}')

def update(self, op_code, cur, max=None, message=''):
    msg = self._cur_line or message
    if max and cur:
        percent = int(cur / max * 100)
        if <MASK>:
            self._last_percent = percent
            logger.info('Progress: %d%% - %s', percent, msg)
    elif msg:
        logger.info(msg)

@register_lowering(aten.bucketize, type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.NO_OPMATH)
def bucketize(input: TensorBox, boundaries: TensorBox, *, out_int32: bool=False, right: bool=False):
    assert len(boundaries.get_size()) == 1
    if <MASK>:
        return fallback_handler(aten.bucketize.Tensor, add_to_fallback_set=False)(input, boundaries, out_int32=out_int32, right=right)
    boundaries.realize()
    device = input.get_device()
    input_loader = input.make_loader()
    index_dtype = torch.int32 if out_int32 else torch.int64

    def inner_fn(index):
        val = input_loader(index)
        indices = ops.bucketize(val, _boundaries_helper(boundaries), 0, index_dtype, right)
        return indices
    result = Pointwise.create(device=device, dtype=index_dtype, inner_fn=inner_fn, ranges=input.get_size())
    result.realize()
    return result

def int_padding_for_string_padding(func, padding_style, dilation, kernel_size):

    def get_dilation(i):
        return dilation[i] if isinstance(dilation, tuple) else dilation
    if <MASK>:
        padding: list[int] = []
        for i in range(conv_picker(func, 0, 1, 2), -1, -1):
            padding += conv_padding_for_same(get_dilation(i), kernel_size[i])
        return padding
    elif padding_style == 'valid':
        return conv_picker(func, 2, 4, 6) * (0,)
    else:
        raise RuntimeError(f"got padding type of {padding_style}, only accept 'same' or 'valid'")

@classmethod
def __torch_function__(cls, func, types, args=(), kwargs=None):
