    if isinstance(result, cls):
        if <MASK>:
            result.extra_state = deepcopy(args[0].extra_state)
        else:
            result.extra_state = {'last_func_called': func.__name__}
    return result

@staticmethod
@functools.cache
def find_header(name: str) -> str:
    if 'HALIDE_INCLUDE' in os.environ:
        path = os.path.join(os.environ['HALIDE_INCLUDE'], name)
        if <MASK>:
            return path
    if 'HALIDE_LIB' in os.environ:
        path = os.path.abspath(os.path.join(os.environ['HALIDE_LIB'], f'../include/{name}'))
        if os.path.exists(path):
            return path
    errmsg = f"Can't find {name}, set env HALIDE_INCLUDE to the directory containing it"
    return HalideCodeCache._search_for_file(f'../include/{name}', errmsg)

def _difference(self, other, sort=None):
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    (other, result_name) = self._convert_can_do_setop(other)
    if not isinstance(other, RangeIndex):
        return super()._difference(other, sort=sort)
    if <MASK>:
        return self[::-1]._difference(other)
    res_name = ops.get_op_result_name(self, other)
    first = self._range[::-1] if self.step < 0 else self._range
    overlap = self.intersection(other)
    if overlap.step < 0:
        overlap = overlap[::-1]
    if len(overlap) == 0:
        return self.rename(name=res_name)
    if len(overlap) == len(self):
        return self[:0].rename(res_name)
    if len(overlap) == 1:
        if overlap[0] == self[0]:
            return self[1:]
        elif overlap[0] == self[-1]:
            return self[:-1]
        elif len(self) == 3 and overlap[0] == self[1]:
            return self[::2]
        else:
            return super()._difference(other, sort=sort)
    elif len(overlap) == 2 and overlap[0] == first[0] and (overlap[-1] == first[-1]):
        return self[1:-1]
    if overlap.step == first.step:
        if overlap[0] == first.start:
            new_rng = range(overlap[-1] + first.step, first.stop, first.step)
        elif overlap[-1] == first[-1]:
            new_rng = range(first.start, overlap[0], first.step)
        elif overlap._range == first[1:-1]:
            step = len(first) - 1
            new_rng = first[::step]
        else:
            return super()._difference(other, sort=sort)
    else:
        assert len(self) > 1
        if overlap.step == first.step * 2:
            if overlap[0] == first[0] and overlap[-1] in (first[-1], first[-2]):
                new_rng = first[1::2]
            elif overlap[0] == first[1] and overlap[-1] in (first[-1], first[-2]):
                new_rng = first[::2]
            else:
                return super()._difference(other, sort=sort)
        else:
            return super()._difference(other, sort=sort)
    if first is not self._range:
        new_rng = new_rng[::-1]
    new_index = type(self)._simple_new(new_rng, name=res_name)
    return new_index

def _find_names(obj):
    import gc
    import inspect
    frame = inspect.currentframe()
    while frame is not None:
        frame.f_locals
        frame = frame.f_back
    obj_names = []
    for referrer in gc.get_referrers(obj):
        if isinstance(referrer, dict):
            for (k, v) in referrer.items():
                if <MASK>:
                    obj_names.append(k)
    return obj_names

def read_data(self, plan: LoadPlan, planner: LoadPlanner) -> Future[None]:
    """
        Reads torch save data on the coordinator rank, and broadcast afterwards
        this incurrs a communication cost, but avoids having to load
        the entire checkpoint on each rank, hopefully preventing OOM issues
        """
    planner = cast(DefaultLoadPlanner, planner)
    if self.is_coordinator:
        if <MASK>:
            raise AssertionError('checkpoint_id must be set before reading data')
        torch_state_dict = torch.load(self.checkpoint_id, map_location='cpu', weights_only=False)
        if planner.flatten_state_dict:
            (torch_state_dict, _) = flatten_state_dict(torch_state_dict)
    else:
        torch_state_dict = None
    for req in plan.items:
        if req.type == LoadItemType.BYTE_IO:
            raise RuntimeError(f'Non-tensor value identified at {req.storage_index.fqn}. At this time {type(self).__name__} only supports loading Tensors.')
        if self.is_coordinator:
            pg_device = dist.distributed_c10d._get_pg_default_device()
            tensor = torch_state_dict[req.storage_index.fqn].to(pg_device)
        else:
            tensor = torch.empty_like(planner.state_dict[req.storage_index.fqn])
        dist.broadcast(tensor, src=self.coordinator_rank, async_op=False)
        tensor = narrow_tensor_by_index(tensor, req.storage_offsets, req.lengths)
        target_tensor = planner.resolve_tensor(req).detach()
        if not target_tensor.size() == tensor.size():
            raise AssertionError(f'req {req.storage_index} mismatch sizes, {target_tensor.size()} vs {tensor.size()}')
        target_tensor.copy_(tensor)
        planner.commit_tensor(req, target_tensor)
    fut: Future = Future()
    fut.set_result(None)
    return fut

def _covhelper(x, y=None, rowvar=True, allow_masked=True):
    """
    Private function for the computation of covariance and correlation
    coefficients.

    """
    x = ma.array(x, ndmin=2, copy=True, dtype=float)
    xmask = ma.getmaskarray(x)
    if not allow_masked and xmask.any():
        raise ValueError('Cannot process masked data.')
    if x.shape[0] == 1:
        rowvar = True
    rowvar = int(bool(rowvar))
    axis = 1 - rowvar
    if rowvar:
        tup = (slice(None), None)
    else:
        tup = (None, slice(None))
    if y is None:
        if <MASK>:
            xnm_dtype = np.float64
        else:
            xnm_dtype = np.float32
        xnotmask = np.logical_not(xmask).astype(xnm_dtype)
    else:
        y = array(y, copy=False, ndmin=2, dtype=float)
        ymask = ma.getmaskarray(y)
        if not allow_masked and ymask.any():
            raise ValueError('Cannot process masked data.')
        if xmask.any() or ymask.any():
            if y.shape == x.shape:
                common_mask = np.logical_or(xmask, ymask)
                if common_mask is not nomask:
                    xmask = x._mask = y._mask = ymask = common_mask
                    x._sharedmask = False
                    y._sharedmask = False
        x = ma.concatenate((x, y), axis)
        if x.shape[0] > 2 ** 24 or x.shape[1] > 2 ** 24:
            xnm_dtype = np.float64
        else:
            xnm_dtype = np.float32
        xnotmask = np.logical_not(np.concatenate((xmask, ymask), axis)).astype(xnm_dtype)
    x -= x.mean(axis=rowvar)[tup]
    return (x, xnotmask, rowvar)

def _save_conversion_params_metric(self, graph_def=None, inference_type=None, inference_input_type=None):
    """Set conversion parameter metrics."""
    converter_kwargs = self._collected_converter_params
    converter_kwargs.update(self._get_base_converter_args())
    quant_mode = QuantizationMode(self.optimizations, self.target_spec, self.representative_dataset, graph_def, self._experimental_disable_per_channel, self.experimental_new_dynamic_range_quantizer, self._experimental_low_bit_qat, self._experimental_full_integer_quantization_bias_type, self._experimental_variable_quantization, self._experimental_strict_qdq)
    converter_kwargs.update({'tf_version': self._metadata.environment.tensorflowVersion, 'api_version': self._metadata.environment.apiVersion, 'original_model_format': self._metadata.environment.modelType, 'optimization_default': quant_mode.is_any_optimization_enabled(), 'optimization_post_training_dynamic_range': quant_mode.is_post_training_dynamic_range_quantization(), 'optimization_post_training_float16': quant_mode.is_post_training_float16_quantization(), 'optimization_post_training_integer_quantize': quant_mode.is_post_training_integer_quantization(), 'optimization_qat': quant_mode.is_quantization_aware_training(), 'optimization_low_bit_qat': quant_mode.is_low_bit_quantize_aware_training(), 'optimization_sparsify': self._sparsify_model(), 'activations_type': quant_mode.activations_type()})
    converter_kwargs.update(quant_mode.converter_flags(inference_type, inference_input_type))
    if self.target_spec._experimental_supported_accumulation_type:
        converter_kwargs.update({'accumulation_type': self.target_spec._experimental_supported_accumulation_type})

    def format_element(elem):
        if isinstance(elem, enum.Enum):
            return str(elem.value)
        return pprint.pformat(elem)

    def format_param(param):
        if isinstance(param, (list, tuple, set)):
            if not param:
                return 'None'
            string_list = [format_element(x) for x in param]
            return ','.join(sorted(string_list))
        return format_element(param)
    for (key, value) in converter_kwargs.items():
        self._tflite_metrics.set_converter_param(key, format_param(value))
    self._tflite_metrics.set_export_required()
    self._metadata.options.allowCustomOps = self.allow_custom_ops
    self._metadata.options.enableSelectTfOps = OpsSet.SELECT_TF_OPS in self.target_spec.supported_ops
    self._metadata.options.forceSelectTfOps = set([OpsSet.SELECT_TF_OPS]) == set(self.target_spec.supported_ops)
    self._metadata.options.modelOptimizationModes = []
    if quant_mode.is_post_training_float16_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_FLOAT16)
    if quant_mode.is_post_training_dynamic_range_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_DYNAMIC_RANGE)
    if quant_mode.is_post_training_int8_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_FULL_INTEGER)
    if <MASK>:
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_INT16)
    if quant_mode.is_quantization_aware_training():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.QUANTIZATION_AWARE_TRAINING)

def convert(self, values: np.ndarray, nan_rep, encoding: str, errors: str):
    """
        Convert the data from this selection to the appropriate pandas type.

        Parameters
        ----------
        values : np.ndarray
        nan_rep :
        encoding : str
        errors : str

        Returns
        -------
        index : listlike to become an Index
        data : ndarraylike to become a column
        """
    assert isinstance(values, np.ndarray), type(values)
    if values.dtype.fields is not None:
        values = values[self.cname]
    assert self.typ is not None
    if self.dtype is None:
        (converted, dtype_name) = _get_data_and_dtype_name(values)
        kind = _dtype_to_kind(dtype_name)
    else:
        converted = values
        dtype_name = self.dtype
        kind = self.kind
    assert isinstance(converted, np.ndarray)
    meta = self.meta
    metadata = self.metadata
    ordered = self.ordered
    tz = self.tz
    assert dtype_name is not None
    dtype = dtype_name
    if dtype.startswith('datetime64'):
        converted = _set_tz(converted, tz, dtype)
    elif dtype == 'timedelta64':
        converted = np.asarray(converted, dtype='m8[ns]')
    elif <MASK>:
        try:
            converted = np.asarray([date.fromordinal(v) for v in converted], dtype=object)
        except ValueError:
            converted = np.asarray([date.fromtimestamp(v) for v in converted], dtype=object)
    elif meta == 'category':
        categories = metadata
        codes = converted.ravel()
        if categories is None:
            categories = Index([], dtype=np.float64)
        else:
            mask = isna(categories)
            if mask.any():
                categories = categories[~mask]
                codes[codes != -1] -= mask.astype(int).cumsum()._values
        converted = Categorical.from_codes(codes, categories=categories, ordered=ordered, validate=False)
    else:
        try:
            converted = converted.astype(dtype, copy=False)
        except TypeError:
            converted = converted.astype('O', copy=False)
    if kind == 'string':
        converted = _unconvert_string_array(converted, nan_rep=nan_rep, encoding=encoding, errors=errors)
    return (self.values, converted)

def prune_conv2d_activation_conv2d(conv2d_1: nn.Conv2d, activation: Optional[Callable[[Tensor], Tensor]], conv2d_2: nn.Conv2d):
    """
    Fusion Pattern for conv2d -> some activation module / function -> conv2d layers
    """
    parametrization_dict = cast(nn.ModuleDict, conv2d_1.parametrizations)
    weight_parameterizations = cast(ParametrizationList, parametrization_dict.weight)
    for p in weight_parameterizations:
        if isinstance(p, FakeStructuredSparsity):
            mask = cast(Tensor, p.mask)
    prune_bias = getattr(conv2d_1, 'prune_bias', False)
    if hasattr(conv2d_2, 'padding') and cast(tuple[int], conv2d_2.padding) > (0, 0) and (conv2d_1.bias is not None or getattr(conv2d_1, '_bias', None) is not None):
        prune_conv2d_padded(conv2d_1)
    else:
        mask = _prune_conv2d_helper(conv2d_1)
        if prune_bias:
            _prune_module_bias(conv2d_1, mask)
        else:
            pruned_biases = _propagate_module_bias(conv2d_1, mask)
            if pruned_biases is not None:
                if <MASK>:
                    pruned_biases = activation(pruned_biases)
                conv2d_2.bias = _get_adjusted_next_layer_bias(conv2d_2, pruned_biases, mask)
        if not (hasattr(conv2d_2, 'padding') and cast(tuple[int], conv2d_2.padding) > (0, 0)) or conv2d_1.bias is None:
            with torch.no_grad():
                if parametrize.is_parametrized(conv2d_2):
                    parametrization_dict = cast(nn.ModuleDict, conv2d_2.parametrizations)
                    weight_parameterizations = cast(ParametrizationList, parametrization_dict.weight)
                    weight_parameterizations.original = nn.Parameter(weight_parameterizations.original[:, mask])
                    conv2d_2.in_channels = weight_parameterizations.original.shape[1]
                else:
                    conv2d_2.weight = nn.Parameter(conv2d_2.weight[:, mask])
                    conv2d_2.in_channels = conv2d_2.weight.shape[1]

def decorator(fn):

    @functools.wraps(fn)
    def wrapper(g, *args, **kwargs):
        nonlocal scale
        nonlocal zero_point
        if scale is not None:
            _scale = g.op('Constant', value_t=torch.tensor(scale))
        else:
            _scale = None
        if <MASK>:
            _zero_point = g.op('Constant', value_t=torch.tensor(zero_point))
        else:
            _zero_point = None
        arg_q_descriptors_extended = arg_q_descriptors + (False,) * (len(args) - len(arg_q_descriptors))
        descriptor_args = tuple(zip(arg_q_descriptors_extended, args))

        def _is_arg_quantized(descriptor, arg):
            return descriptor and _is_value(arg) and _is_tuple_construct(arg)
        is_quantized: list[bool] = []
        for (descriptor, arg) in descriptor_args:
            if _is_packed_list(arg):
                is_quantized.extend((_is_arg_quantized(descriptor, arg_input) for arg_input in arg.node().inputs()))
            else:
                is_quantized.append(_is_arg_quantized(descriptor, arg))
        if not any(is_quantized):
            return fn(g, *args, **kwargs)
        non_quantized_args = []
        for (descriptor, arg) in descriptor_args:
            if _is_arg_quantized(descriptor, arg):
                (dequantized_arg, arg_scale, arg_zero_point, _) = dequantize_helper(g, arg)
                non_quantized_args.append(dequantized_arg)
                if _scale is None:
                    _scale = arg_scale
                if _zero_point is None:
                    _zero_point = arg_zero_point
            elif _is_packed_list(arg):
                for arg_input in arg.node().inputs():
                    if _is_arg_quantized(descriptor, arg_input):
                        (dequantized_arg, arg_scale, arg_zero_point, _) = dequantize_helper(g, arg_input)
                        if _scale is None:
                            _scale = arg_scale
                        if _zero_point is None:
                            _zero_point = arg_zero_point
                        arg_input.replaceAllUsesWith(dequantized_arg)
                non_quantized_args.append(arg)
            else:
                non_quantized_args.append(arg)
        output = fn(g, *non_quantized_args, **kwargs)
        assert _scale is not None, 'Bug: Scale must be set for quantized operator'
        assert _zero_point is not None, 'Bug: Zero point must be set for quantized operator'
        if quantize_output:
            return quantize_helper(g, output, _scale, _zero_point)
        return output
    return wrapper

def _is_type_subset(a, b):
    """Returns true if `b` is a subset of type `a` (or if a is not a TypeSpec.)"""
    if <MASK>:
        return a.most_specific_compatible_type(b) == a
    return True

@register_op_impl([aten.convolution.default, aten.convolution_backward.default])
def conv(fake_mode, func, *args, **kwargs):
    (_, kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    device = kwargs['input'].fake_device
    with fake_mode:
        k = kwargs['weight'].ndim
        batch = kwargs['input'].shape[0]
        from torch.fx.experimental.symbolic_shapes import has_hint
        if not has_hint(batch):
            mem_fmt = None
        else:
            if func is aten.convolution.default:
                conv_backend = torch._C._select_conv_backend(**kwargs)
            else:
                conv_backend = torch._C._select_conv_backend(kwargs['input'], kwargs['weight'], bias=None, stride=kwargs['stride'], padding=kwargs['padding'], dilation=kwargs['dilation'], transposed=kwargs['transposed'], output_padding=kwargs['output_padding'], groups=kwargs['groups'], bias_sizes=kwargs['bias_sizes'])
            if <MASK>:
                kwargs['input'] = kwargs['input'].contiguous().unsqueeze(2)
                kwargs['weight'] = kwargs['weight'].unsqueeze(2)
                if len(kwargs['stride']) == 1:
                    kwargs['stride'].insert(0, 1)
                    kwargs['padding'].insert(0, 0)
                    kwargs['dilation'].insert(0, 1)
                    kwargs['output_padding'].insert(0, 0)
            mem_fmt = torch._C._conv_determine_backend_memory_format(kwargs['input'], kwargs['weight'], conv_backend)
            if k == 3 and (not kwargs['input'].is_mkldnn) and (not kwargs['input'].is_xpu):
                kwargs['input'] = kwargs['input'].squeeze(2)
                kwargs['weight'] = kwargs['weight'].squeeze(2)
                if len(kwargs['stride']) == 2:
                    kwargs['stride'].pop(0)
                    kwargs['padding'].pop(0)
                    kwargs['dilation'].pop(0)
                    kwargs['output_padding'].pop(0)

    def convert(t, mem_fmt):
        if t is None:
            return t
        if mem_fmt is not None:
            if t.dim() == 3 and mem_fmt == torch.channels_last:
                t = t.unsqueeze(2).to(memory_format=mem_fmt).squeeze(2)
            else:
                t = t.to(memory_format=mem_fmt)
        return FakeTensor(fake_mode, t, device)
    with in_kernel_invocation_manager(fake_mode):
        out = func(**kwargs)
        if func is aten.convolution.default:
            return convert(out, mem_fmt)
        else:
            return (convert(out[0], mem_fmt), convert(out[1], mem_fmt), convert(out[2], None))

def get_allocation_size(self, node: Union[ir.TensorBox, ir.StorageBox, ir.Buffer, WorkspaceArg, ir.TorchBindObject]) -> Sequence[Expr]:
    if <MASK>:
        node = node.data
    if isinstance(node, ir.StorageBox):
        node = node.data
    if isinstance(node, ir.ComputedBuffer) and node.name in self.buffer_to_padded_size:
        return self.buffer_to_padded_size[node.name]
    else:
        return node.get_size()

def __init__(self, tensor):
    self.floating_dtype = tensor.dtype.is_floating_point
    self.int_mode = True
    self.sci_mode = False
    self.max_width = 1
    with torch.no_grad():
        tensor_view = tensor.reshape(-1)
    if not self.floating_dtype:
        for value in tensor_view:
            value_str = f'{value}'
            self.max_width = max(self.max_width, len(value_str))
    else:
        if tensor.dtype == torch.float4_e2m1fn_x2:
            tensor_view = tensor_view.view(torch.uint8)
        nonzero_finite_vals = torch.masked_select(tensor_view, torch.isfinite(tensor_view) & tensor_view.ne(0))
        if nonzero_finite_vals.numel() == 0:
            return
        if tensor.dtype == torch.float8_e8m0fnu:
            nonzero_finite_vals = nonzero_finite_vals.float()
        nonzero_finite_abs = tensor_totype(nonzero_finite_vals.abs())
        nonzero_finite_min = tensor_totype(nonzero_finite_abs.min())
        nonzero_finite_max = tensor_totype(nonzero_finite_abs.max())
        for value in nonzero_finite_vals:
            if <MASK>:
                self.int_mode = False
                break
        self.sci_mode = nonzero_finite_max / nonzero_finite_min > 1000.0 or nonzero_finite_max > 100000000.0 or nonzero_finite_min < 0.0001 if PRINT_OPTS.sci_mode is None else PRINT_OPTS.sci_mode
        if self.int_mode:
            if self.sci_mode:
                for value in nonzero_finite_vals:
                    value_str = f'{{:.{PRINT_OPTS.precision}e}}'.format(value)
                    self.max_width = max(self.max_width, len(value_str))
            else:
                for value in nonzero_finite_vals:
                    value_str = f'{value:.0f}'
                    self.max_width = max(self.max_width, len(value_str) + 1)
        elif self.sci_mode:
            for value in nonzero_finite_vals:
                value_str = f'{{:.{PRINT_OPTS.precision}e}}'.format(value)
                self.max_width = max(self.max_width, len(value_str))
        else:
            for value in nonzero_finite_vals:
                value_str = f'{{:.{PRINT_OPTS.precision}f}}'.format(value)
                self.max_width = max(self.max_width, len(value_str))

def assert_timedelta_array_equal(left, right, obj: str='TimedeltaArray', check_freq: bool=True) -> None:
    __tracebackhide__ = True
    _check_isinstance(left, right, TimedeltaArray)
    assert_numpy_array_equal(left._ndarray, right._ndarray, obj=f'{obj}._ndarray')
    if <MASK>:
        assert_attr_equal('freq', left, right, obj=obj)

def __init__(self, value):
    """Creates a new Dimension with the given value."""
    if isinstance(value, int):
        if <MASK>:
            raise ValueError('Dimension %d must be >= 0' % value)
        self._value = value
    elif value is None:
        self._value = None
    elif isinstance(value, Dimension):
        self._value = value._value
    else:
        try:
            self._value = int(value.__index__())
        except AttributeError:
            raise TypeError("Dimension value must be integer or None or have an __index__ method, got value '{0!r}' with type '{1!r}'".format(value, type(value))) from None
        if self._value < 0:
            raise ValueError('Dimension %d must be >= 0' % self._value)

def build_chunks(self):
    if not isinstance(self._proto, saved_model_pb2.SavedModel):
        raise TypeError(f'SavedModelSplitter can only split SavedModel protos. Got {type(self._proto)}.')
    if <MASK>:
