def concatenate_managers(mgrs_indexers, axes: list[Index], concat_axis: AxisInt, copy: bool) -> BlockManager:
    """
    Concatenate block managers into one.

    Parameters
    ----------
    mgrs_indexers : list of (BlockManager, {axis: indexer,...}) tuples
    axes : list of Index
    concat_axis : int
    copy : bool

    Returns
    -------
    BlockManager
    """
    needs_copy = copy and concat_axis == 0
    if concat_axis == 0:
        mgrs = _maybe_reindex_columns_na_proxy(axes, mgrs_indexers, needs_copy)
        return mgrs[0].concat_horizontal(mgrs, axes)
    if len(mgrs_indexers) > 0 and mgrs_indexers[0][0].nblocks > 0:
        first_dtype = mgrs_indexers[0][0].blocks[0].dtype
        if <MASK>:
            if all((_is_homogeneous_mgr(mgr, first_dtype) for (mgr, _) in mgrs_indexers)) and len(mgrs_indexers) > 1:
                shape = tuple((len(x) for x in axes))
                nb = _concat_homogeneous_fastpath(mgrs_indexers, shape, first_dtype)
                return BlockManager((nb,), axes)
    mgrs = _maybe_reindex_columns_na_proxy(axes, mgrs_indexers, needs_copy)
    if len(mgrs) == 1:
        mgr = mgrs[0]
        out = mgr.copy(deep=False)
        out.axes = axes
        return out
    blocks = []
    values: ArrayLike
    for (placement, join_units) in _get_combined_plan(mgrs):
        unit = join_units[0]
        blk = unit.block
        if _is_uniform_join_units(join_units):
            vals = [ju.block.values for ju in join_units]
            if not blk.is_extension:
                values = np.concatenate(vals, axis=1)
            elif is_1d_only_ea_dtype(blk.dtype):
                values = concat_compat(vals, axis=0, ea_compat_axis=True)
                values = ensure_block_shape(values, ndim=2)
            else:
                values = concat_compat(vals, axis=1)
            values = ensure_wrapped_if_datetimelike(values)
            fastpath = blk.values.dtype == values.dtype
        else:
            values = _concatenate_join_units(join_units, copy=copy)
            fastpath = False
        if fastpath:
            b = blk.make_block_same_class(values, placement=placement)
        else:
            b = new_block_2d(values, placement=placement)
        blocks.append(b)
    return BlockManager(tuple(blocks), axes)

def make_guard_filter_entry(guard: Guard) -> GuardFilterEntry:
    MISSING = object()
    name = strip_local_scope(guard.name)
    if <MASK>:
        has_value = False
        value = MISSING
    else:
        try:
            value = builder.get(guard.name)
            has_value = True
        except:
            value = MISSING
            has_value = False
    is_global = get_global_source_name(guard.originating_source) is not None
    return GuardFilterEntry(name=name, has_value=has_value, value=value, guard_type=guard.create_fn_name(), derived_guard_types=tuple(guard.guard_types) if guard.guard_types else (), is_global=is_global, orig_guard=guard)

def __call__(self, a, b, *args, **kwargs):
    """Execute the call behavior."""
    (da, db) = (getdata(a), getdata(b))
    with np.errstate(divide='ignore', invalid='ignore'):
        result = self.f(da, db, *args, **kwargs)
    m = ~umath.isfinite(result)
    m |= getmask(a)
    m |= getmask(b)
    domain = ufunc_domain.get(self.f, None)
    if <MASK>:
        m |= domain(da, db)
    if not m.ndim:
        if m:
            return masked
        else:
            return result
    try:
        np.copyto(result, 0, casting='unsafe', where=m)
        masked_da = umath.multiply(m, da)
        if np.can_cast(masked_da.dtype, result.dtype, casting='safe'):
            result += masked_da
    except Exception:
        pass
    masked_result = result.view(get_masked_subclass(a, b))
    masked_result._mask = m
    if isinstance(a, MaskedArray):
        masked_result._update_from(a)
    elif isinstance(b, MaskedArray):
        masked_result._update_from(b)
    return masked_result

def map_out(e):
    if id(e) not in inp_impls and (isinstance(e, torch.Tensor) and (not e.is_sparse) and (e._typed_storage()._cdata in storages)):
        raise orig_not_implemented_exception
    if <MASK>:
        if id(e) in inp_impls:
            return inp_impls[id(e)]
        else:
            return cls.fake_mode.fake_tensor_converter.from_real_tensor(cls.fake_mode, e)
    else:
        return e

def _annotate_qat_conv2d_bn_binary_unary(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = find_sequential_partitions(gm, [torch.nn.Conv2d, torch.nn.BatchNorm2d, operator.add, torch.nn.ReLU])
    for fused_partition in fused_partitions:
        (conv_partition, bn_partition, binary_partition, unary_partition) = fused_partition
        (conv_node, bn_output_node, binary_node, unary_node) = self._get_output_nodes_of_partitions([conv_partition, bn_partition, binary_partition, unary_partition])
        if len(bn_output_node.users) != 1:
            continue
        (bn_output_node_idx, extra_input_node_idx) = self._get_input_idx_for_binary_node(bn_output_node, binary_node)
        if bn_output_node_idx is None or extra_input_node_idx is None:
            continue
        if bn_output_node != binary_node.args[bn_output_node_idx]:
            raise ValueError(f"{bn_output_node} doesn't match input of binary node")
        extra_input_node = binary_node.args[extra_input_node_idx]
        if conv_node.op != 'call_function' or conv_node.target != torch.ops.aten.conv2d.default:
            continue
        if <MASK>:
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        if quantization_config is not None:
            binary_node_input_qspec_map = {}
            binary_node_input_qspec_map[extra_input_node] = get_input_act_qspec(quantization_config)
            binary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(input_qspec_map=binary_node_input_qspec_map, _annotated=True)
            unary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(output_qspec=get_output_act_qspec(quantization_config), _annotated=True, _is_output_of_quantized_pattern=True)
        else:
            _annotate_nodes_not_quantize([binary_node, unary_node])
        nodes_to_mark_annotated = list(conv_partition.nodes)
        nodes_to_mark_annotated.extend(list(bn_partition.nodes))
        nodes_to_mark_annotated.extend(list(binary_partition.nodes))
        nodes_to_mark_annotated.extend(list(unary_partition.nodes))
        _mark_nodes_as_annotated(nodes_to_mark_annotated)

def insert_custom_op_guards(gm: torch.fx.GraphModule, ops_to_guard: set[str]) -> None:
    """
    This is used by draft_export to insert guards in front of calls to custom
    operators which have a generated fake kernel.
