def add_ordering(self, *ordering):
    """
        Add items from the 'ordering' sequence to the query's "order by"
        clause. These items are either field names (not column names) --
        possibly with a direction prefix ('-' or '?') -- or OrderBy
        expressions.

        If 'ordering' is empty, clear all ordering from the query.
        """
    errors = []
    for item in ordering:
        if isinstance(item, str):
            if <MASK>:
                continue
            item = item.removeprefix('-')
            if item in self.annotations:
                continue
            if self.extra and item in self.extra:
                continue
            self.names_to_path(item.split(LOOKUP_SEP), self.model._meta)
        elif not hasattr(item, 'resolve_expression'):
            errors.append(item)
        if getattr(item, 'contains_aggregate', False):
            raise FieldError('Using an aggregate in order_by() without also including it in annotate() is not allowed: %s' % item)
    if errors:
        raise FieldError('Invalid order_by arguments: %s' % errors)
    if ordering:
        self.order_by += ordering
    else:
        self.default_ordering = False

def _get_saveable_from_factory(saveable_factories, serialized_tensor, created_compat_names):
    """Returns the saveable generated from the factory method."""
    matched_factory = None
    expected_factory_name = serialized_tensor.name
    factory_input_name = serialized_tensor.checkpoint_key
    if <MASK>:
        matched_factory = saveable_factories[expected_factory_name]
    if matched_factory is None:
        for (factory_name, factory) in saveable_factories.items():
            if expected_factory_name.startswith(factory_name):
                if matched_factory is not None:
                    raise ValueError('Forward compatibility load error: Unable to load checkpoint saved in future version of TensorFlow. Please update your version of TensorFlow to the version in which the checkpoint was saved.')
                matched_factory = factory
                factory_input_name = _extract_saveable_name(serialized_tensor.checkpoint_key) + factory_name
                created_compat_names.add(factory_name)
    if callable(matched_factory):
        return matched_factory(name=factory_input_name)
    return matched_factory

def parse_output(fpath: str, inclusive: bool) -> FunctionCounts:
    (_annotate_invocation, annotate_invocation_output) = run(['callgrind_annotate', f"--inclusive={('yes' if inclusive else 'no')}", '--threshold=100', '--show-percs=no', fpath], check=True)
    total_pattern = re.compile('^([0-9,]+)\\s+PROGRAM TOTALS')
    begin_pattern = re.compile('Ir\\s+file:function')
    function_pattern = re.compile('^\\s*([0-9,]+)\\s+(.+:.+)$')

    class ScanState(enum.Enum):
        SCANNING_FOR_TOTAL = 0
        SCANNING_FOR_START = 1
        PARSING = 2
    scan_state = ScanState.SCANNING_FOR_TOTAL
    fn_counts = []
    for l in annotate_invocation_output.splitlines(keepends=False):
        if scan_state == ScanState.SCANNING_FOR_TOTAL:
            total_match = total_pattern.match(l)
            if total_match:
                program_totals = int(total_match.groups()[0].replace(',', ''))
                scan_state = ScanState.SCANNING_FOR_START
        elif scan_state == ScanState.SCANNING_FOR_START:
            if begin_pattern.match(l):
                scan_state = ScanState.PARSING
        else:
            if scan_state != ScanState.PARSING:
                raise AssertionError('Failed to enter PARSING state while parsing callgrind_annotate output')
            fn_match = function_pattern.match(l)
            if fn_match:
                (ir_str, file_function) = fn_match.groups()
                ir = int(ir_str.replace(',', ''))
                if ir == program_totals:
                    continue
                fn_counts.append(FunctionCount(ir, file_function))
            elif <MASK>:
                continue
            else:
                break
    if scan_state != ScanState.PARSING:
        raise AssertionError(f'Failed to parse {fpath}')
    return FunctionCounts(tuple(sorted(fn_counts, reverse=True)), inclusive=inclusive)

def gen_functionalization_registration(selector: SelectiveBuilder, g: NativeFunction | NativeFunctionsGroup | NativeFunctionsViewGroup, composite_implicit_autograd_index: BackendIndex) -> list[str]:

    @with_native_function
    def emit_registration_helper(f: NativeFunction) -> str:
        assert not f.has_composite_implicit_autograd_kernel
        registration_str = f'TORCH_FN(functionalization::{wrapper_name(f.func)})'
        return f'm.impl("{f.func.name}", {registration_str});'
    if not selector.include_all_operators:
        return []
    if isinstance(g, NativeFunctionsViewGroup):
        if str(g.view.func.name) == 'lift_fresh':
            return []
        view_str = []
        if not g.view.has_composite_implicit_autograd_kernel:
            view_str.append(emit_registration_helper(g.view))
        if g.view_inplace is not None and (not g.view_inplace.has_composite_implicit_autograd_kernel):
            assert g.view_inplace.is_view_op
            view_str.append(emit_registration_helper(g.view_inplace))
        return view_str
    elif isinstance(g, NativeFunctionsGroup):
        if g.inplace is not None and str(g.inplace.func.name) == 'set_.source_Tensor':
            fns = []
        else:
            fns = list(g.functions())
    else:
        if str(g.func.name) in MUTABLE_OPS_NOT_USING_FUNCTIONALIZATION:
            return []
        fns = [g]
    registrations = []
    for f in fns:
        if f.has_composite_implicit_autograd_kernel:
            continue
        if <MASK>:
            return []
        if str(f.func.name) == 'resize_':
            return []
        if str(f.func.name.name) != 'set_':
            assert not f.is_view_op
        if modifies_arguments(f):
            registrations.append(emit_registration_helper(f))
    return registrations

def _breadth_first_traversal(self):
    """Returns all trackable objects in the SavedObjectGraph."""
    (trackable_objects, _) = super(_AugmentedGraphView, self)._breadth_first_traversal()
    asset_paths = object_identity.ObjectIdentityDictionary()
    constant_captures = object_identity.ObjectIdentityDictionary()
    for obj in trackable_objects:
        if isinstance(obj, asset.Asset):
            asset_paths[obj.asset_path] = obj
        if isinstance(obj, saved_model_utils.TrackableConstant):
            constant_captures[obj.capture] = obj

    def _get_merged_trackable(x):
        if isinstance(x, asset.Asset):
            return asset_paths[x.asset_path]
        if <MASK>:
            if x.capture in asset_paths:
                return asset_paths[x.capture]
            else:
                return constant_captures[x.capture]
        return x
    for obj in list(self._children_cache.keys()):
        if _get_merged_trackable(obj) is not obj:
            del self._children_cache[obj]
            continue
        for (name, child) in self._children_cache[obj].items():
            self._children_cache[obj][name] = _get_merged_trackable(child)
    return super(_AugmentedGraphView, self)._breadth_first_traversal()

def testMemoryLeakInGlobalGradientRegistry(self):
    if <MASK>:
        self.skipTest('memory_profiler required to run this test')

    def f():

        @def_function.function(autograph=False)
        def graph(x):

            @def_function.function(autograph=False)
            def cubed(a):
                return a * a * a
            y = cubed(x)
            del cubed
            return gradient_ops.gradients(gradient_ops.gradients(y, x), x)
        return graph(constant_op.constant(1.5))[0].numpy()
    memory_test_util.assert_no_leak(f, num_iters=300, increase_threshold_absolute_mb=50)

def __init__(self, dataset: Dataset[_T_co], batch_size: Optional[int]=1, shuffle: Optional[bool]=None, sampler: Union[Sampler, Iterable, None]=None, batch_sampler: Union[Sampler[list], Iterable[list], None]=None, num_workers: int=0, collate_fn: Optional[_collate_fn_t]=None, pin_memory: bool=False, drop_last: bool=False, timeout: float=0, worker_init_fn: Optional[_worker_init_fn_t]=None, multiprocessing_context=None, generator=None, *, prefetch_factor: Optional[int]=None, persistent_workers: bool=False, pin_memory_device: str='', in_order: bool=True) -> None:
    torch._C._log_api_usage_once('python.data_loader')
    if num_workers < 0:
        raise ValueError('num_workers option should be non-negative; use num_workers=0 to disable multiprocessing.')
    if timeout < 0:
        raise ValueError('timeout option should be non-negative')
    if num_workers == 0 and prefetch_factor is not None:
        raise ValueError('prefetch_factor option could only be specified in multiprocessing.let num_workers > 0 to enable multiprocessing, otherwise set prefetch_factor to None.')
    elif num_workers > 0 and prefetch_factor is None:
        prefetch_factor = 2
    elif prefetch_factor is not None and prefetch_factor < 0:
        raise ValueError('prefetch_factor option should be non-negative')
    if persistent_workers and num_workers == 0:
        raise ValueError('persistent_workers option needs num_workers > 0')
    self.dataset = dataset
    self.num_workers = num_workers
    self.prefetch_factor = prefetch_factor
    self.pin_memory = pin_memory
    self.pin_memory_device = pin_memory_device
    self.timeout = timeout
    self.worker_init_fn = worker_init_fn
    self.multiprocessing_context = multiprocessing_context
    self.in_order = in_order
    if isinstance(self.dataset, IterDataPipe):
        self.dataset = _IterDataPipeSerializationWrapper(self.dataset)
    elif isinstance(self.dataset, MapDataPipe):
        self.dataset = _MapDataPipeSerializationWrapper(self.dataset)
    if isinstance(dataset, IterableDataset):
        self._dataset_kind = _DatasetKind.Iterable
        if isinstance(dataset, IterDataPipe):
            if shuffle is not None:
                dataset = torch.utils.data.graph_settings.apply_shuffle_settings(dataset, shuffle=shuffle)
        elif shuffle not in {False, None}:
            raise ValueError(f'DataLoader with IterableDataset: expected unspecified shuffle option, but got shuffle={shuffle}')
        if sampler is not None:
            raise ValueError(f'DataLoader with IterableDataset: expected unspecified sampler option, but got sampler={sampler}')
        elif batch_sampler is not None:
            raise ValueError(f'DataLoader with IterableDataset: expected unspecified batch_sampler option, but got batch_sampler={batch_sampler}')
    else:
        shuffle = bool(shuffle)
        self._dataset_kind = _DatasetKind.Map
    if <MASK>:
        raise ValueError('sampler option is mutually exclusive with shuffle')
    if batch_sampler is not None:
        if batch_size != 1 or shuffle or sampler is not None or drop_last:
            raise ValueError('batch_sampler option is mutually exclusive with batch_size, shuffle, sampler, and drop_last')
        batch_size = None
        drop_last = False
    elif batch_size is None:
        if drop_last:
            raise ValueError('batch_size=None option disables auto-batching and is mutually exclusive with drop_last')
    if sampler is None:
        if self._dataset_kind == _DatasetKind.Iterable:
            sampler = _InfiniteConstantSampler()
        elif shuffle:
            sampler = RandomSampler(dataset, generator=generator)
        else:
            sampler = SequentialSampler(dataset)
    if batch_size is not None and batch_sampler is None:
        batch_sampler = BatchSampler(sampler, batch_size, drop_last)
    self.batch_size = batch_size
    self.drop_last = drop_last
    self.sampler = sampler
    self.batch_sampler = batch_sampler
    self.generator = generator
    if collate_fn is None:
        if self._auto_collation:
            collate_fn = _utils.collate.default_collate
        else:
            collate_fn = _utils.collate.default_convert
    self.collate_fn = collate_fn
    self.persistent_workers = persistent_workers
    self.__initialized = True
    self._IterableDataset_len_called = None
    self._iterator = None
    self.check_worker_number_rationality()
    torch.set_vital('Dataloader', 'enabled', 'True')

def fn_to_trace(*args):
    nonlocal num_fw_outs
    out = functional_call(*args)
    if <MASK>:
        raise RuntimeError('If trace_joint=Trueit is required that one of your forward outputs must be a scalar loss.\nYou must specify the which (index) output is the loss with output_loss_index.')
    if isinstance(out, torch.Tensor):
        out = (out,)
    if not isinstance(out, (tuple, list)):
        raise RuntimeError(f'Expected forward output to be either a tensor or a list/tuple of tensors. found {type(out)}')
    for (i, o) in enumerate(out):
        if o.requires_grad and i != output_loss_index:
            raise RuntimeError(f'Found an output of the forward that requires gradients, that was not the scalar loss.\nWe require all outputs to the forward that are not the scalar loss to not require gradient,\nbecause we will only compute a backward graph against the scalar loss.\nYou can fix this by calling .detach() on each of your forward outputs that is not the loss.\nYou specified that output index {output_loss_index} is the loss, but we found that\nthe output at index {i} requires gradients.')
    out_loss = out[output_loss_index]
    num_fw_outs = len(out)
    if not out_loss.requires_grad:
        raise RuntimeError(f'The output at index {output_loss_index} was marked as the loss, but it does not require gradients')
    if out_loss.numel() != 1:
        raise RuntimeError(f'We require the output marked as the loss (at index {output_loss_index}) to be a scalar, but it has shape {out_loss.shape}')
    return out

def run_benchmark(func, num_iters, execution_mode=None):
    ctx = context.context()
    with context.execution_mode(execution_mode):
        func()
        if <MASK>:
            ctx.executor.wait()
        start = time.time()
        for _ in xrange(num_iters):
            func()
        if execution_mode == context.ASYNC:
            ctx.executor.wait()
        end = time.time()
        return end - start

