def populate_namespace_from_OP_to_IO(self):
    for node in self.nodes_op:
        for (node_output, outputSize) in zip(node.outputs, node.outputstensor_size):
            self.scope_name_appeared.append(node.scopeName)
            self.nodes_io[node_output] = NodeBase(node_output, node.inputs, node.scopeName, outputSize, op_type=node.kind, attributes=node.attributes)
    self.find_common_root()
    for node in self.nodes_op:
        for input_node_id in node.inputs:
            self.unique_name_to_scoped_name[input_node_id] = node.scopeName + '/' + input_node_id
    for (key, node) in self.nodes_io.items():
        if type(node) is NodeBase:
            self.unique_name_to_scoped_name[key] = node.scope + '/' + node.debugName
        if hasattr(node, 'input_or_output'):
            self.unique_name_to_scoped_name[key] = node.input_or_output + '/' + node.debugName
        if hasattr(node, 'scope') and node.scope is not None:
            self.unique_name_to_scoped_name[key] = node.scope + '/' + node.debugName
            if node.scope == '' and self.shallowest_scope_name:
                self.unique_name_to_scoped_name[node.debugName] = self.shallowest_scope_name + '/' + node.debugName
    for (key, node) in self.nodes_io.items():
        self.nodes_io[key].inputs = [self.unique_name_to_scoped_name[node_input_id] for node_input_id in node.inputs]
        if <MASK>:
            self.nodes_io[key].debugName = self.unique_name_to_scoped_name[node.debugName]

def module_name_to_file_path(module_name):
    for suffix in ['.py', '/__init__.py']:
        file_path = pathlib.Path(__file__).parents[2] / (module_name.replace('.', '/') + suffix)
        if <MASK>:
            return file_path
    raise CodeNotFound

def conversion_visitor(unused_path, unused_parent, children):
    for child in children:
        (_, attr) = tf_decorator.unwrap(child[1])
        if not tf_inspect.isfunction(attr):
            continue
        names_v1 = tf_export.get_v1_names(attr)
        arg_names_v1 = get_args(attr)
        for name in names_v1:
            tf_name = 'tf.%s' % name
            if tf_name in function_warnings or tf_name in function_transformers:
                continue
            if tf_name in v1_name_exceptions:
                continue
            args = ','.join(['%s=%d' % (from_name, from_index) for (from_index, from_name) in enumerate(arg_names_v1)])
            text_input = '%s(%s)' % (tf_name, args)
            (_, _, _, text) = self._upgrade(text_input)
            (new_function_name, new_args) = get_func_and_args_from_str(text)
            if '__internal__' in new_function_name:
                continue
            if new_function_name == 'tf.compat.v1.%s' % name:
                if tf_name in keyword_renames:
                    self.fail("Function '%s' is not in 2.0 when converting\n%s\nto\n%s" % (new_function_name, text_input, text))
                continue
            if <MASK>:
                self.assertIn(new_function_name.replace('tf.compat.v2.', 'tf.'), self.v2_symbols)
                continue
            args_v2 = get_args(self.v2_symbols[new_function_name])
            args_v2.extend(v2_arg_exceptions)
            for new_arg in new_args:
                self.assertIn(new_arg, args_v2, "Invalid argument '%s' in 2.0 when converting\n%s\nto\n%s.\nSupported arguments: %s" % (new_arg, text_input, text, str(args_v2)))
            if new_function_name in set(['tf.nn.ctc_loss', 'tf.saved_model.save']):
                continue
            args_v1 = get_args(self.v1_symbols[new_function_name])
            args_v1.extend(v2_arg_exceptions)
            for new_arg in new_args:
                self.assertIn(new_arg, args_v1, "Invalid argument '%s' in 1.0 when converting\n%s\nto\n%s.\nSupported arguments: %s" % (new_arg, text_input, text, str(args_v1)))

def _reduction_identity(op_name: str, input: Tensor, *args):
    """Return identity value as scalar tensor of a reduction operation on
    given input, or None, if the identity value cannot be uniquely
    defined for the given input.

    The identity value of the operation is defined as the initial
    value to reduction operation that has a property ``op(op_identity,
    value) == value`` for any value in the domain of the operation.
    Or put it another way, including or excluding the identity value in
    a list of operands will not change the reduction result.

    See https://github.com/pytorch/rfcs/pull/27 for more information.

    """
    dtype: DType = input.dtype
    device = input.device
    op_name = op_name.rsplit('.', 1)[-1]
    if op_name in {'sum', 'cumsum'}:
        return torch.tensor(0, dtype=dtype, device=device)
    elif op_name in {'prod', 'cumprod'}:
        return torch.tensor(1, dtype=dtype, device=device)
    elif op_name in {'amax', 'argmax', 'logaddexp'}:
        if torch.is_floating_point(input):
            return torch.tensor(-torch.inf, dtype=dtype, device=device)
        elif <MASK>:
            return torch.tensor(torch.iinfo(dtype).min, dtype=dtype, device=device)
    elif op_name == 'logsumexp':
        if torch.is_floating_point(input):
            return torch.tensor(-torch.inf, dtype=dtype, device=device)
        elif torch.is_complex(input):
            return torch.tensor(-torch.inf + 0j, dtype=dtype, device=device)
        elif torch.is_signed(input) or dtype == torch.uint8:
            return torch.tensor(torch.iinfo(dtype).min, dtype=dtype, device=device)
    elif op_name in {'amin', 'argmin'}:
        if torch.is_floating_point(input):
            return torch.tensor(torch.inf, dtype=dtype, device=device)
        elif torch.is_signed(input) or dtype == torch.uint8:
            return torch.tensor(torch.iinfo(dtype).max, dtype=dtype, device=device)
    elif op_name == 'mean':
        return None
    elif op_name == 'norm':
        ord = args[0] if args else 2
        if ord == float('-inf'):
            assert torch.is_floating_point(input), input.dtype
            return torch.tensor(torch.inf, dtype=dtype, device=device)
        return torch.tensor(0, dtype=dtype, device=device)
    elif op_name == 'median':
        dtype = input.dtype if torch.is_floating_point(input) else torch.float
        return torch.tensor(torch.nan, dtype=dtype, device=device)
    elif op_name in {'var', 'std'}:
        return None
    raise NotImplementedError(f'identity of {op_name} on {dtype} input')

def decorator(func):
    reason = None
    if TEST_WITH_ROCM:
        rocm_version = str(torch.version.hip)
        rocm_version = rocm_version.split('-', maxsplit=1)[0]
        rocm_version_tuple = tuple((int(x) for x in rocm_version.split('.')))
        if <MASK>:
            reason = f'skip_if_rocm_ver_lessthan_multiprocess: ROCm {rocm_version_tuple} is available but {version} required'
    return unittest.skipIf(reason is not None, reason)(func)

def replace(old: Union[torch.fx.Node, None], new: Union[torch.fx.Node, Sequence[torch.fx.Node], None]) -> None:

    def filter_nodes_in_newly_added_nodes(node: torch.fx.Node) -> bool:
        return node not in added_replacement_nodes
    if old is None:
        assert new is None
        return
    assert isinstance(old, torch.fx.Node)
    if new is None:
        old.replace_all_uses_with(None, delete_user_cb=filter_nodes_in_newly_added_nodes)
        if <MASK>:
            graph.erase_node(old)
        return
    if isinstance(new, torch.fx.Node):
        if 'val' not in new.meta:
            new.meta.update(old.meta)
        for tag_name in ['recompute', 'ac_graph_id']:
            if tag_name in old.meta:
                percolate_tags(new, tag_name, old.meta[tag_name], OrderedSet(args))
        old.replace_all_uses_with(new, delete_user_cb=filter_nodes_in_newly_added_nodes)
        if len(old.users) == 0:
            graph.erase_node(old)
        return
    old_uses = list(old.users.keys())
    for user in old_uses:
        idx = maybe_getitem(user)
        if idx is None:
            raise AssertionError('Deleted index from getitem, did you erase the index and not properly replace it?')
        replace(user, new[idx])
    graph.erase_node(old)

def register_tensor_type(tensor_type):
    global TENSOR
    if <MASK>:
        TENSOR = tensor_type
    else:
        raise AssertionError('Tensor type is already registered.')

def _broadcast_to_ragged_shape(rt_input, dst_shape, broadcast_inner_dimensions):
    """Broadcasts rt_input to the ragged shape `dst_shape`."""
    if isinstance(rt_input, ragged_tensor.RaggedTensor) and rt_input.row_splits.dtype != dst_shape.dim_size_dtype:
        if not ragged_config.auto_cast_partition_dtype():
            raise ValueError('rt_input and dst_shape have different row_split dtypes; use RaggedTensor.with_row_splits_dtype() or RaggedTensorDynamicShape.with_dim_size_dtype() to convert to a compatible dtype.')
        rt_input = rt_input.with_row_splits_dtype(dtypes.int64)
        dst_shape = dst_shape.with_dim_size_dtype(dtypes.int64)
    if rt_input.shape.ndims is None or dst_shape.rank is None:
        raise ValueError('Unable to broadcast: unknown rank')
    if <MASK>:
        raise ValueError('Incompatible with shape: rank mismatch')
    if isinstance(rt_input, ragged_tensor.RaggedTensor) and rt_input.ragged_rank >= dst_shape.num_partitioned_dimensions:
        raise ValueError('Incompatible with shape: ragged rank mismatch')
    src_shape = RaggedTensorDynamicShape.from_tensor(rt_input)
    src_shape = src_shape.broadcast_to_rank(dst_shape.rank)
    if dst_shape.rank > rt_input.shape.ndims:
        if rt_input.shape.ndims < dst_shape.num_inner_dimensions + 1:
            rt_input = array_ops.reshape(rt_input, array_ops.concat([[-1], dst_shape.inner_dim_sizes], axis=0))
        for _ in range(dst_shape.rank - rt_input.shape.ndims):
            if ragged_tensor.is_ragged(rt_input):
                nrows = rt_input.nrows()
            else:
                nrows = array_ops.shape(rt_input, out_type=dst_shape.dim_size_dtype)[0]
            rt_input = ragged_tensor.RaggedTensor.from_row_lengths(rt_input, [nrows], validate=False)
    if ragged_tensor.is_ragged(rt_input):
        inner_rank_diff = rt_input.flat_values.shape.ndims - 1 - dst_shape.num_inner_dimensions
        if inner_rank_diff > 0:
            rt_input = rt_input.with_flat_values(ragged_tensor.RaggedTensor.from_tensor(rt_input.flat_values, ragged_rank=inner_rank_diff, row_splits_dtype=dst_shape.dim_size_dtype))
    else:
        rt_input = ragged_tensor.RaggedTensor.from_tensor(rt_input, ragged_rank=dst_shape.num_partitioned_dimensions - 1, row_splits_dtype=dst_shape.dim_size_dtype)
    multiples = [1] * dst_shape.rank
    for axis in range(dst_shape.num_partitioned_dimensions):
        if not src_shape.is_ragged(axis) and (not dst_shape.is_ragged(axis)):
            src_size = src_shape.dimension_size(axis)
            dst_size = dst_shape.dimension_size(axis)
            if tensor_util.constant_value(src_size) in (1, None) and tensor_util.constant_value(dst_size) != 1:
                multiples[axis] = array_ops.where(math_ops.equal(src_size, 1), dst_size, 1)
    if not all((isinstance(v, int) and v == 1 for v in multiples)):
        multiples = array_ops_stack.stack(multiples, axis=0)
        rt_input = ragged_array_ops.tile(rt_input, multiples)
    if broadcast_inner_dimensions:
        new_shape = array_ops.broadcast_dynamic_shape(array_ops.shape(rt_input.flat_values, out_type=dst_shape.dim_size_dtype), array_ops.concat([[1], dst_shape.inner_dim_sizes], axis=0))
        rt_input = rt_input.with_flat_values(array_ops.broadcast_to(rt_input.flat_values, new_shape))
    for axis in range(dst_shape.num_partitioned_dimensions):
        if not src_shape.is_ragged(axis) and dst_shape.is_ragged(axis):
            dst_size = dst_shape.dimension_size(axis)
            rt_input = _ragged_tile_axis(rt_input, axis, dst_size, dst_shape.dim_size_dtype)
    return rt_input

