def do_collect(*args, **kwargs):
    nonlocal enabled
    if not self_return[0]:
        self_return[0] = True
    else:
        sys.setprofile(orig_trace)
        enabled = False
        try:
            if info['generation'] != 2:
                gc.collect()
            observer(gc.garbage)
            gc.garbage.clear()
            gc.set_debug(0)
            before = torch.cuda.memory_allocated()
            gc.collect()
            after = torch.cuda.memory_allocated()
            if <MASK>:
                logger.warning('CUDA Memory changed during GC, %d bytes freed.', before - after)
        finally:
            enabled = True
    if orig_trace is not None:
        return orig_trace(*args, **kwargs)

def __init__(self, op, data):
    assert isinstance(op, Op)
    if op is Op.INTEGER:
        assert isinstance(data, tuple) and len(data) == 2
        assert isinstance(data[0], int)
        assert isinstance(data[1], (int, str)), data
    elif op is Op.REAL:
        assert isinstance(data, tuple) and len(data) == 2
        assert isinstance(data[0], float)
        assert isinstance(data[1], (int, str)), data
    elif <MASK>:
        assert isinstance(data, tuple) and len(data) == 2
    elif op is Op.STRING:
        assert isinstance(data, tuple) and len(data) == 2
        assert isinstance(data[0], str) and data[0][::len(data[0]) - 1] in ('""', "''", '@@')
        assert isinstance(data[1], (int, str)), data
    elif op is Op.SYMBOL:
        assert hash(data) is not None
    elif op in (Op.ARRAY, Op.CONCAT):
        assert isinstance(data, tuple)
        assert all((isinstance(item, Expr) for item in data)), data
    elif op in (Op.TERMS, Op.FACTORS):
        assert isinstance(data, dict)
    elif op is Op.APPLY:
        assert isinstance(data, tuple) and len(data) == 3
        assert hash(data[0]) is not None
        assert isinstance(data[1], tuple)
        assert isinstance(data[2], dict)
    elif op is Op.INDEXING:
        assert isinstance(data, tuple) and len(data) == 2
        assert hash(data[0]) is not None
    elif op is Op.TERNARY:
        assert isinstance(data, tuple) and len(data) == 3
    elif op in (Op.REF, Op.DEREF):
        assert isinstance(data, Expr)
    elif op is Op.RELATIONAL:
        assert isinstance(data, tuple) and len(data) == 3
    else:
        raise NotImplementedError(f'unknown op or missing sanity check: {op}')
    self.op = op
    self.data = data

def forward(self, input):
    if len(input.shape) != 4:
        raise ValueError('Input shape must be `(N, C, H, W)`!')
    if <MASK>:
        _reversed_padding_repeated_twice = _reverse_repeat_padding(self.padding)
        input = F.pad(input, _reversed_padding_repeated_twice, mode=self.padding_mode)
    return torch.ops.quantized.conv2d_relu(input, self._packed_params, self.scale, self.zero_point)

def _maybe_get_loss(self, stage, mb_index):
    valid_index = 0 <= mb_index < len(self._internal_losses)
    if <MASK>:
        return self._internal_losses[mb_index]
    elif len(self._internal_losses) != 0 and (not valid_index):
        raise RuntimeError(f'Loss for microbatch {mb_index} is not available. Available losses for microbatches: {self._internal_losses}')
    else:
        return None

def parallel_apply(modules: Sequence[Module], inputs: Sequence[Any], kwargs_tup: Optional[Sequence[dict[str, Any]]]=None, devices: Optional[Sequence[Optional[Union[int, torch.device]]]]=None) -> list[Any]:
    """Apply each `module` in :attr:`modules` in parallel on each of :attr:`devices`.

    Args:
        modules (Module): modules to be parallelized
        inputs (tensor): inputs to the modules
        devices (list of int or torch.device): CUDA devices

    :attr:`modules`, :attr:`inputs`, :attr:`kwargs_tup` (if given), and
    :attr:`devices` (if given) should all have same length. Moreover, each
    element of :attr:`inputs` can either be a single object as the only argument
    to a module, or a collection of positional arguments.
    """
    assert len(modules) == len(inputs), f'The number of modules {len(modules)} is not equal to the number of inputs {len(inputs)}'
    if kwargs_tup is not None:
        assert len(modules) == len(kwargs_tup)
    else:
        kwargs_tup = (cast(dict[str, Any], {}),) * len(modules)
    if devices is not None:
        assert len(modules) == len(devices)
    else:
        devices = [None] * len(modules)
    devices = [_get_device_index(x, True) for x in devices]
    streams = [torch.accelerator.current_stream(x) for x in devices]
    assert torch.accelerator.is_available(), 'No available accelerator found.'
    device_type = torch.accelerator.current_accelerator().type
    lock = threading.Lock()
    results = {}
    (grad_enabled, autocast_enabled) = (torch.is_grad_enabled(), torch.is_autocast_enabled())

    def _worker(i: int, module: Module, input: Any, kwargs: dict[str, Any], device: Optional[Union[int, torch.device]]=None, stream: Optional[torch.Stream]=None) -> None:
        torch.set_grad_enabled(grad_enabled)
        if device is None:
            t = get_a_var(input)
            if t is None:
                with lock:
                    results[i] = ExceptionWrapper(where=f'in replica {i}, no device was provided and no tensor input was found; device cannot be resolved')
                return
            device = t.get_device()
        if isinstance(device, torch.device):
            device = device.index
        if <MASK>:
            stream = torch.accelerator.current_stream(device)
        try:
            with torch.accelerator.device_index(device), stream, torch.amp.autocast(device_type, enabled=autocast_enabled):
                if not isinstance(input, (list, tuple)):
                    input = (input,)
                output = module(*input, **kwargs)
            with lock:
                results[i] = output
        except Exception:
            with lock:
                results[i] = ExceptionWrapper(where=f'in replica {i} on device {device}')
    if len(modules) > 1:
        threads = [threading.Thread(target=_worker, args=(i, module, input, kwargs, device, stream)) for (i, (module, input, kwargs, device, stream)) in enumerate(zip(modules, inputs, kwargs_tup, devices, streams))]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
    else:
        _worker(0, modules[0], inputs[0], kwargs_tup[0], devices[0], streams[0])
    outputs = []
    for i in range(len(inputs)):
        output = results[i]
        if isinstance(output, ExceptionWrapper):
            output.reraise()
        outputs.append(output)
    return outputs

@final
def _maybe_right_yaxis(self, ax: Axes, axes_num: int) -> Axes:
    if not self.on_right(axes_num):
        return self._get_ax_layer(ax)
    if <MASK>:
        return ax.right_ax
    elif hasattr(ax, 'left_ax'):
        return ax
    else:
        (orig_ax, new_ax) = (ax, ax.twinx())
        new_ax._get_lines = orig_ax._get_lines
        new_ax._get_patches_for_fill = orig_ax._get_patches_for_fill
        (orig_ax.right_ax, new_ax.left_ax) = (new_ax, orig_ax)
        if not self._has_plotted_object(orig_ax):
            orig_ax.get_yaxis().set_visible(False)
        if self.logy is True or self.loglog is True:
            new_ax.set_yscale('log')
        elif self.logy == 'sym' or self.loglog == 'sym':
            new_ax.set_yscale('symlog')
