def read(self, queue, name=None):
    """Returns the next record (key, value) pair produced by a reader.

    Will dequeue a work unit from queue if necessary (e.g. when the
    Reader needs to start reading from a new file since it has
    finished with the previous file).

    Args:
      queue: A Queue or a mutable string Tensor representing a handle
        to a Queue, with string work items.
      name: A name for the operation (optional).

    Returns:
      A tuple of Tensors (key, value).
      key: A string scalar Tensor.
      value: A string scalar Tensor.
    """
    if <MASK>:
        queue_ref = queue
    else:
        queue_ref = queue.queue_ref
    if self._reader_ref.dtype == dtypes.resource:
        return gen_io_ops.reader_read_v2(self._reader_ref, queue_ref, name=name)
    else:
        old_queue_op = gen_data_flow_ops.fake_queue(queue_ref)
        return gen_io_ops.reader_read(self._reader_ref, old_queue_op, name=name)

@ops.RegisterGradient('BatchMatMulV2')
@ops.RegisterGradient('BatchMatMulV3')
def _BatchMatMulV2(op: ops.Operation, grad):
    """Returns the gradient of x and y given the gradient of x * y."""
    x = op.inputs[0]
    y = op.inputs[1]
    adj_x = op.get_attr('adj_x')
    adj_y = op.get_attr('adj_y')
    if not adj_x:
        if <MASK>:
            grad_x = math_ops.matmul(grad, y, adjoint_a=False, adjoint_b=True, grad_a=True)
            grad_y = math_ops.matmul(x, grad, adjoint_a=True, adjoint_b=False, grad_b=True)
        else:
            grad_x = math_ops.matmul(grad, y, adjoint_a=False, adjoint_b=False, grad_a=True)
            grad_y = math_ops.matmul(grad, x, adjoint_a=True, adjoint_b=False, grad_b=True)
    elif not adj_y:
        grad_x = math_ops.matmul(y, grad, adjoint_a=False, adjoint_b=True, grad_a=True)
        grad_y = math_ops.matmul(x, grad, adjoint_a=False, adjoint_b=False, grad_b=True)
    else:
        grad_x = math_ops.matmul(y, grad, adjoint_a=True, adjoint_b=True, grad_a=True)
        grad_y = math_ops.matmul(grad, x, adjoint_a=True, adjoint_b=True, grad_b=True)
    shape_x_static = x.get_shape()
    shape_y_static = y.get_shape()
    output_may_have_non_empty_batch_shape = (shape_x_static.rank is None or shape_x_static.rank > 2) or (shape_y_static.rank is None or shape_y_static.rank > 2)
    batch_shapes_match = shape_x_static[:-2].is_fully_defined() and shape_y_static[:-2].is_fully_defined() and (shape_x_static[:-2] == shape_y_static[:-2])
    if not output_may_have_non_empty_batch_shape or batch_shapes_match:
        return (grad_x, grad_y)
    sx = array_ops.shape(x)
    sy = array_ops.shape(y)
    (rx, ry) = gen_array_ops.broadcast_gradient_args(sx[:-2], sy[:-2])
    grad_x = array_ops.reshape(math_ops.reduce_sum(grad_x, rx), sx)
    grad_y = array_ops.reshape(math_ops.reduce_sum(grad_y, ry), sy)
    return (grad_x, grad_y)

def _alter_column_type_sql(self, table, old_field, new_field, new_type, old_collation, new_collation):
    """
        Special case when dimension changed.
