    return ((sql_alter % {'column': self.quote_name(new_field.column), 'type': new_type, 'collation': ''}, []), [])

def _is_local_fn(fn):
    if hasattr(fn, '__code__'):
        return fn.__code__.co_flags & inspect.CO_NESTED
    else:
        if <MASK>:
            return '<locals>' in fn.__qualname__
        fn_type = type(fn)
        if hasattr(fn_type, '__qualname__'):
            return '<locals>' in fn_type.__qualname__
    return False

def visit_FunctionDef(self, node):
    compose_dec = []
    for dec in node.decorator_list:
        if isinstance(dec, ast.Call):
            if isinstance(dec.func, ast.Attribute) and dec.func.attr == 'Composite':
                compose_dec.append(dec)
            if isinstance(dec.func, ast.Name) and dec.func.id == 'Composite':
                compose_dec.append(dec)
    if not compose_dec:
        return
    elif <MASK>:
        raise KeyError('More than one TF ops decomposes for.')
    all_dec_args = {}
    for (arg_name, arg_value) in zip(_COMPOSITE_ARG_LIST, compose_dec[0].args):
        all_dec_args[arg_name] = self.visit(arg_value)
    kw_dec_args = dict([self.visit(kw) for kw in compose_dec[0].keywords])
    if all_dec_args.keys() & kw_dec_args.keys():
        raise KeyError('More arguments than expected.')
    all_dec_args.update(kw_dec_args)
    op_name = all_dec_args['op_name']
    op_def = op_def_registry.get(op_name)
    if op_def:
        if len(all_dec_args) > 1:
            raise ValueError('Op has been registered: ' + op_name)
        else:
            return
    inputs = all_dec_args.get('inputs', [])
    attrs = all_dec_args.get('attrs', [])
    expected_args = [arg.split(':')[0] for arg in inputs + attrs]
    all_func_args = self.visit(node.args)
    if len(expected_args) != len(all_func_args):
        raise KeyError('Composition arguments for {} do not match the registration. {} vs {}'.format(op_name, expected_args, all_func_args))
    cxx_reg_code = ['\nREGISTER_OP("{}")'.format(op_name)]
    for input_ in inputs:
        cxx_reg_code.append('.Input("{}")'.format(input_))
    for attr in attrs:
        py_str = attr.replace('"', "'")
        cxx_reg_code.append('.Attr("{}")'.format(py_str))
    for attr in all_dec_args.get('derived_attrs', []):
        py_str = attr.replace('"', "'")
        cxx_reg_code.append('.Attr("{}")'.format(py_str))
    for output_ in all_dec_args.get('outputs', []):
        cxx_reg_code.append('.Output("{}")'.format(output_))
    cxx_reg_code[-1] += ';\n'
    self.emit('\n    '.join(cxx_reg_code))

@register_lowering(torch.ops.mkldnn._linear_pointwise)
def linear_unary(x: TensorBox, w: TensorBox, b: TensorBox, attr, scalars, algorithm, layout=None):
    x_size = x.get_size()
    if len(x_size) > 2:
        x = view(x, [-1, x_size[-1]])
    if <MASK>:
        b = ir.ExternKernel.realize_input(b)
    choices: list[ChoiceCaller] = []
    if config.max_autotune or config.max_autotune_gemm:
        transposed_w = permute(w, [1, 0])
        (*_, layout, x, transposed_w) = mm_args(x, transposed_w, layout=layout)
        if use_cpp_gemm_template(layout, x, transposed_w):

            def epilogue_creator(buf):
                return create_epilogue_with_attr(buf, attr, scalars=scalars, algorithm=algorithm)
            kwargs = {'has_bias': b is not None, 'trans_w': True, 'epilogue_creator': None if attr == 'none' else epilogue_creator}
            if b is not None:
                kwargs['input_indices'] = [2, 0, 1]
            CppGemmTemplate.add_choices(choices, layout, [x, w] if b is None else [x, w, b], **kwargs)
    if len(choices) == 0 or use_aten_gemm_kernels():
        kwargs = dict(attr=attr, scalars=scalars, algorithm=algorithm)
        if b is None:
            kwargs['B'] = None
        choices.append(aten_mkldnn_linear_unary.bind([x, w] if b is None else [x, w, b], layout, **kwargs))
    assert w.get_name() in V.graph.constants
    input_gen_fns = {1: lambda x: V.graph.constants[x.get_name()]}
    result = autotune_select_algorithm('linear_unary', choices, [x, w] if b is None else [x, w, b], layout, input_gen_fns=input_gen_fns)
    if len(x_size) > 2:
        result = view(result, (*x_size[:-1], result.get_size()[-1]))
    return result

def _deprecate_estimator_name(estimator_name, name, version):
    """Deprecate `estimator_name` in favour of `name`."""
    version = parse_version(version)
    version_remove = f'{version.major}.{version.minor + 2}'
    if <MASK>:
        if name:
            raise ValueError(f'Cannot provide both `estimator_name` and `name`. `estimator_name` is deprecated in {version} and will be removed in {version_remove}. Use `name` only.')
        warnings.warn(f'`estimator_name` is deprecated in {version} and will be removed in {version_remove}. Use `name` instead.', FutureWarning)
        return estimator_name
    return name

def collect_stats(files, fd, pattern):
    line_regexs = [re.compile('(?P<lineno>[0-9]+)(\\s[0-9]+)+'), re.compile('((jump)|(jcnd))=([0-9]+)\\s(?P<lineno>[0-9]+)')]
    current_file = None
    current_function = None
    for line in fd:
        if re.match('f[lie]=.+', line):
            path = line.split('=', 2)[1].strip()
            if os.path.exists(path) and re.search(pattern, path):
                current_file = files.get_file(path)
            else:
                current_file = None
        elif re.match('fn=.+', line):
            current_function = line.split('=', 2)[1].strip()
        elif <MASK>:
            for regex in line_regexs:
                match = regex.match(line)
                if match:
                    lineno = int(match.group('lineno'))
                    current_file.mark_line(lineno, current_function)

def __call__(self, gm: torch.fx.GraphModule, example_inputs: list[Any], **kwargs: Any) -> torch.fx.GraphModule:
    compiler_fn = functools.partial(self._torchdynamo_orig_backend, **kwargs)
    assert config.repro_after in ('dynamo', 'aot', None)
    if config.repro_after == 'dynamo':

        def add_paths(exc: Exception) -> None:
            exc.minifier_path = os.path.join(minifier_dir(), 'minifier_launcher.py')
            if use_buck:
                exc.buck_command = ' '.join(BUCK_CMD_PREFIX + [BuckTargetWriter(exc.minifier_path).cmd_line_path])
        if config.repro_level == 3:
            dump_to_minify_after_dynamo(gm, example_inputs, self._compiler_name)
        if config.repro_level == 4:
            compiled_gm = compiler_fn(copy.deepcopy(gm), example_inputs)
            if _accuracy_fails(gm, example_inputs, compiler_fn):
                log.warning('Accuracy failed for the TorchDynamo produced graph. Creating script to minify the error.')
                dump_to_minify_after_dynamo(fx.GraphModule(gm, copy.deepcopy(gm.graph)), example_inputs, self._compiler_name)
                exc = AccuracyError('Bad accuracy detected.')
                add_paths(exc)
                raise exc
        else:
            try:
                compiled_gm = compiler_fn(copy.deepcopy(gm), example_inputs)
                run_fwd_maybe_bwd(compiled_gm, example_inputs)
            except Exception as exc:
                log.warning('Compiled Fx GraphModule failed. Creating script to minify the error.')
                if config.repro_level == 1:
                    dump_state_fn = functools.partial(dump_backend_state, compiler_name=self._compiler_name)
                    dump_state_fn(fx.GraphModule(gm, copy.deepcopy(gm.graph)), example_inputs)
                elif <MASK>:
                    dump_to_minify_after_dynamo(fx.GraphModule(gm, copy.deepcopy(gm.graph)), example_inputs, self._compiler_name)
                add_paths(exc)
                raise
    else:
        compiled_gm = compiler_fn(gm, example_inputs)
    return compiled_gm

def _collect_nodes(self, start: Optional[str], end: Optional[str]) -> NodeList:
    """
        Collect nodes in the model that between nodes with name of `start` and `end`.
        These two nodes are also included.
        """
    nodes: NodeList = []
    add_node = start is None
    for node in self.module.graph.nodes:
        if node.op not in CALLABLE_NODE_OPS:
            continue
        if node.name == start:
            add_node = True
        if <MASK>:
            nodes.append(node)
        if node.name == end:
            break
    return nodes

def _to_proto(self):
    pb = dataset_options_pb2.DistributeOptions()
    pb.auto_shard_policy = AutoShardPolicy._to_proto(self.auto_shard_policy)
    if <MASK>:
        pb.num_devices = self.num_devices
    return pb

def __exit__(self, type: Any, value: Any, traceback: Any):
    cur_stream = self.stream
    if <MASK>:
        return
    if self.src_prev_stream.device != cur_stream.device:
        torch.cuda.set_stream(self.dst_prev_stream)
    torch.cuda.set_stream(self.src_prev_stream)

def _extract_logger_info_one_model(model: nn.Module, results: NSResultsType, logger_cls: Callable) -> None:
    torch._C._log_api_usage_once('quantization_api._numeric_suite_fx._extract_logger_info_one_model')
    for (_gm_name, mod) in model.named_modules():
        is_logger = isinstance(mod, logger_cls) or (isinstance(mod, torch.jit.RecursiveScriptModule) and mod.original_name == 'OutputLogger')
        if is_logger:
            key = mod.ref_name
            if key not in results:
                results[key] = {}
            if mod.model_name in results[key]:
                raise AssertionError(f'{mod.model_name} is already present in results')
            if mod.results_type not in results[key]:
                results[key][mod.results_type] = {}
            if mod.model_name not in results[key][mod.results_type]:
                results[key][mod.results_type][mod.model_name] = []
            stats_to_use = mod.stats
            if len(mod.stats_rnn) > 0:
                stats_to_use = mod.stats_rnn
            data = {'type': mod.results_type, 'values': stats_to_use, 'ref_node_name': mod.ref_node_name, 'ref_node_target_type': mod.ref_node_target_type, 'prev_node_name': mod.prev_node_name, 'prev_node_target_type': mod.prev_node_target_type, 'index_within_arg': mod.index_within_arg, 'index_of_arg': mod.index_of_arg, 'fqn': mod.fqn, 'qconfig_str': mod.qconfig_str}
            if <MASK>:
                data['comparisons'] = mod.comparisons
                data['comparison_fn_name'] = mod.comparison_fn_name
            else:
                data['comparisons'] = []
                data['comparison_fn_name'] = ''
            results[key][mod.results_type][mod.model_name].append(data)
            results[key][mod.results_type][mod.model_name].sort(key=lambda res: f"{res['index_of_arg']}:{res['index_within_arg']}")

def build_graph(parameters):
    """Build graph for stride_slice test."""
    input_tensor = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input', shape=parameters['input_shape'])
    if parameters['constant_indices']:
        begin = parameters['begin']
        end = parameters['end']
        strides = parameters['strides']
        tensors = [input_tensor]
    else:
        begin = tf.compat.v1.placeholder(dtype=parameters['index_type'], name='begin', shape=[len(parameters['begin'])])
        end = tf.compat.v1.placeholder(dtype=parameters['index_type'], name='end', shape=[len(parameters['end'])])
        strides = None
        if parameters['strides'] is not None:
            strides = tf.compat.v1.placeholder(dtype=parameters['index_type'], name='strides', shape=[len(parameters['strides'])])
        tensors = [input_tensor, begin, end]
        if strides is not None:
            tensors.append(strides)
    kwargs = {}
    if parameters.get('ellipsis_mask', None):
        kwargs.update({'ellipsis_mask': parameters['ellipsis_mask']})
    if <MASK>:
        kwargs.update({'new_axis_mask': parameters['new_axis_mask']})
    out = tf.strided_slice(input_tensor, begin, end, strides, begin_mask=parameters['begin_mask'], end_mask=parameters['end_mask'], shrink_axis_mask=parameters['shrink_axis_mask'], **kwargs)
    return (tensors, [out])

@capture_provenance
def binary_magic_impl(self, other):
    from torch.fx.experimental.proxy_tensor import get_proxy_mode, handle_sym_dispatch
    op = method_to_operator(method)
    out_hint = None
    if self.hint is not None and other.hint is not None:
        out_hint = op(self.hint, other.hint)
    if get_proxy_mode():
        return to_node(self, handle_sym_dispatch(op, (wrap_node(self), wrap_node(other)), {}))
    assert isinstance(other, SymNode)
    optimized_summation = False
    try:
        if method == 'mod':
            from torch.utils._sympy.functions import Mod, PythonMod
            shape_env = self.shape_env
            if (self.expr.is_nonnegative or shape_env.bound_sympy(self.expr).lower >= 0) and (other.expr.is_nonnegative or shape_env.bound_sympy(other.expr).lower >= 0):
                out = Mod(self.expr, other.expr)
            else:
                out = PythonMod(self.expr, other.expr)
        elif method == 'add':
            (optimized_summation, out) = func(self.expr, other.expr, self._optimized_summation, other._optimized_summation)
        else:
            out = func(self.expr, other.expr)
    except Exception:
        log.warning('failed to eval %s(%s, %s)', method, self.expr, other.expr)
        raise
    sym_node_log.debug('%s %s %s -> %s', method, self.expr, other.expr, out)
    pytype: type
    if <MASK>:
        pytype = float
    elif method in always_bool_magic_methods:
        pytype = bool
    elif self.pytype is float or other.pytype is float:
        pytype = float
    else:
        pytype = self.pytype
    if pytype is not None and out_hint is not None and (not isinstance(out_hint, SymTypes)):
        out_hint = pytype(out_hint)
    (fx_node, _) = self.shape_env._create_fx_call_function(op, (self.fx_node, other.fx_node))
    result = SymNode(out, self.shape_env, pytype, out_hint, fx_node=fx_node, optimized_summation=optimized_summation)
    return result

def remove_noop_ops(graph: torch.fx.Graph):
    """
    Removes both operations that are essentially aten.clone and operations that are essentially aten.alias from the graph.
    """
    inputs = OrderedSet[torch.fx.Node]()
    input_storages = OrderedSet[int | None]()
    output_storages = OrderedSet[int | None]()
    for node in graph.find_nodes(op='placeholder'):
        inputs.add(node)
        input_storages.add(get_node_storage(node))
    output_node = next(iter(reversed(graph.nodes)))
    assert output_node.op == 'output'
    outputs = output_node.args[0]
    if not isinstance(outputs, (list, tuple)):
        outputs = (outputs,)
    for out in outputs:
        if isinstance(out, torch.fx.Node):
            output_storages.add(get_node_storage(out))
    for node in graph.nodes:
        if node.target in noop_registry:
            (cond, src_index) = noop_registry[node.target]
            if <MASK>:
                src = node.args[src_index]
            else:
                src = src_index(node.args)
            if not isinstance(src, torch.fx.Node):
                continue
            node_storage = get_node_storage(node)
            src_storage = get_node_storage(src)
            node_is_view = node_storage == src_storage
            if not node_is_view and node_storage in output_storages and (src_storage in input_storages or src_storage in output_storages):
                continue
            if node_is_view and node in output_node.args and (src in inputs or src in output_node.args):
                continue
            (is_valid, args, kwargs) = get_fake_args_kwargs(node)
            if not is_valid:
                continue
            if same_meta(node, src) and cond(*args, **kwargs):
                node.replace_all_uses_with(src)
                graph.erase_node(node)

def model_fn(x):
    """A very simple model written by the user."""

    def loss_fn():
        y = array_ops.reshape(layer(x), []) - constant_op.constant(1.0)
        return y * y
    if strategy_test_lib.is_optimizer_v2_instance(optimizer):
        return optimizer.minimize(loss_fn, lambda : layer.trainable_variables)
    elif <MASK>:
        return optimizer.minimize(loss_fn)
    else:
        return optimizer.minimize(loss_fn())

def _binop(self, other):

    def convert_values(param):
        if isinstance(param, ExtensionArray) or is_list_like(param):
            ovalues = param
        else:
            ovalues = [param] * len(self)
        return ovalues
    if isinstance(other, (ABCSeries, ABCIndex, ABCDataFrame)):
        return NotImplemented
    lvalues = self
    rvalues = convert_values(other)
    res = [op(a, b) for (a, b) in zip(lvalues, rvalues, strict=True)]

    def _maybe_convert(arr):
        if coerce_to_dtype:
            res = self._cast_pointwise_result(arr)
            if <MASK>:
                res = np.asarray(arr)
        else:
            res = np.asarray(arr, dtype=result_dtype)
        return res
    if op.__name__ in {'divmod', 'rdivmod'}:
        (a, b) = zip(*res, strict=True)
        return (_maybe_convert(a), _maybe_convert(b))
    return _maybe_convert(res)

def _form_blocks(arrays: list[ArrayLike], consolidate: bool, refs: list) -> list[Block]:
    tuples = enumerate(arrays)
    if not consolidate:
        return _tuples_to_blocks_no_consolidate(tuples, refs)
    grouper = itertools.groupby(tuples, _grouping_func)
    nbs: list[Block] = []
    for ((_, dtype), tup_block) in grouper:
        block_type = get_block_type(dtype)
        if isinstance(dtype, np.dtype):
            is_dtlike = dtype.kind in 'mM'
            if <MASK>:
                dtype = np.dtype(object)
            (values, placement) = _stack_arrays(tup_block, dtype)
            if is_dtlike:
                values = ensure_wrapped_if_datetimelike(values)
            blk = block_type(values, placement=BlockPlacement(placement), ndim=2)
            nbs.append(blk)
        elif is_1d_only_ea_dtype(dtype):
            dtype_blocks = [block_type(x[1], placement=BlockPlacement(x[0]), ndim=2) for x in tup_block]
            nbs.extend(dtype_blocks)
        else:
            dtype_blocks = [block_type(ensure_block_shape(x[1], 2), placement=BlockPlacement(x[0]), ndim=2) for x in tup_block]
            nbs.extend(dtype_blocks)
    return nbs

def process_jobs(workflow: str, job_name: str, test_matrix: dict[str, list[Any]], issue_type: IssueType, url: str) -> dict[str, list[Any]]:
    """
    Both disabled and unstable jobs are in the following format:

    {
        "WORKFLOW / PLATFORM / JOB (CONFIG)": [
            AUTHOR,
            ISSUE_NUMBER,
            ISSUE_URL,
            WORKFLOW,
            PLATFORM,
            JOB (CONFIG),
        ],
        "pull / linux-bionic-py3.8-clang9 / test (dynamo)": [
            "pytorchbot",
            "94861",
            "https://github.com/pytorch/pytorch/issues/94861",
            "pull",
            "linux-bionic-py3.8-clang9",
            "test (dynamo)",
        ],
    }
    """
    try:
        (current_platform, _) = (n.strip() for n in job_name.split(JOB_NAME_SEP, 1) if n)
    except ValueError:
        warnings.warn(f'Invalid job name {job_name}, returning')
        return test_matrix
    for record in download_json(url=url, headers={}).values():
        (author, _, target_url, target_workflow, target_platform, target_job_cfg) = record
        if target_workflow != workflow:
            continue
        cleanup_regex = f'(-{BUILD_JOB_NAME}|-{TEST_JOB_NAME})$'
        target_platform_no_suffix = re.sub(cleanup_regex, '', target_platform)
        current_platform_no_suffix = re.sub(cleanup_regex, '', current_platform)
        if target_platform != current_platform and target_platform_no_suffix != current_platform_no_suffix:
            continue
        if not target_job_cfg:
            msg = f'Issue {target_url} created by {author} has {issue_type.value} ' + f'all CI jobs for {workflow} / {job_name}'
            info(msg)
            return _filter_jobs(test_matrix=test_matrix, issue_type=issue_type)
        if target_job_cfg == BUILD_JOB_NAME:
            msg = f'Issue {target_url} created by {author} has {issue_type.value} ' + f'the build job for {workflow} / {job_name}'
            info(msg)
            return _filter_jobs(test_matrix=test_matrix, issue_type=issue_type)
        if <MASK>:
            msg = f'Issue {target_url} created by {author} has {issue_type.value} ' + f'all the test jobs for {workflow} / {job_name}'
            info(msg)
            return _filter_jobs(test_matrix=test_matrix, issue_type=issue_type)
        m = JOB_NAME_CFG_REGEX.match(target_job_cfg)
        if m:
            target_job = m.group('job')
            if target_job in (TEST_JOB_NAME, BUILD_AND_TEST_JOB_NAME):
                target_cfg = m.group('cfg')
                test_matrix = _filter_jobs(test_matrix=test_matrix, issue_type=issue_type, target_cfg=target_cfg)
        else:
            warnings.warn(f'Found a matching {issue_type.value} issue {target_url} for {workflow} / {job_name}, ' + f'but the name {target_job_cfg} is invalid')
    return test_matrix

def _validate_fill_value(self, value):
    """
        Check if the value can be inserted into our array without casting,
        and convert it to an appropriate native type if necessary.

        Raises
        ------
        TypeError
            If the value cannot be inserted into an array of this dtype.
        """
    dtype = self.dtype
    if isinstance(dtype, np.dtype) and dtype.kind not in 'mM':
        try:
            return np_can_hold_element(dtype, value)
        except LossySetitemError as err:
            raise TypeError from err
    elif <MASK>:
        raise TypeError
    return value

@np.errstate(over='ignore', invalid='ignore')
def __setitem__(self, indx, value):
    """
        x.__setitem__(i, y) <==> x[i]=y

        Set item described by index. If value is masked, masks those
        locations.

        """
    if self is masked:
        raise MaskError('Cannot alter the masked element.')
    _data = self._data
    _mask = self._mask
    if isinstance(indx, str):
        _data[indx] = value
        if _mask is nomask:
            self._mask = _mask = make_mask_none(self.shape, self.dtype)
        _mask[indx] = getmask(value)
        return
    _dtype = _data.dtype
    if value is masked:
        if _mask is nomask:
            _mask = self._mask = make_mask_none(self.shape, _dtype)
        if <MASK>:
            _mask[indx] = tuple([True] * len(_dtype.names))
        else:
            _mask[indx] = True
        return
    dval = getattr(value, '_data', value)
    mval = getmask(value)
    if _dtype.names is not None and mval is nomask:
        mval = tuple([False] * len(_dtype.names))
    if _mask is nomask:
        _data[indx] = dval
        if mval is not nomask:
            _mask = self._mask = make_mask_none(self.shape, _dtype)
            _mask[indx] = mval
    elif not self._hardmask:
        if isinstance(indx, masked_array) and (not isinstance(value, masked_array)):
            _data[indx.data] = dval
        else:
            _data[indx] = dval
            _mask[indx] = mval
    elif hasattr(indx, 'dtype') and indx.dtype == MaskType:
        indx = indx * umath.logical_not(_mask)
        _data[indx] = dval
    else:
        if _dtype.names is not None:
            err_msg = "Flexible 'hard' masks are not yet supported."
            raise NotImplementedError(err_msg)
        mindx = mask_or(_mask[indx], mval, copy=True)
        dindx = self._data[indx]
        if dindx.size > 1:
            np.copyto(dindx, dval, where=~mindx)
        elif mindx is nomask:
            dindx = dval
        _data[indx] = dindx
        _mask[indx] = mindx
    return

def start(self) -> 'TailLog':
    if not self._threadpool or not self._dst:
        return self
    for (local_rank, file) in self._log_files.items():
        header = f'[{self._name}{local_rank}]:'
        if <MASK>:
            header = self._log_line_prefixes[local_rank]
        self._futs.append(self._threadpool.submit(tail_logfile, header=header, file=file, dst=self._dst, finished=self._finished_events[local_rank], interval_sec=self._interval_sec, log_line_filter=self._log_line_filter))
    return self

