@functools.cache
def check_msvc_cl_language_id(compiler: str) -> None:
    """
    Torch.compile() is only work on MSVC with English language pack well.
    Check MSVC's language pack: https://github.com/pytorch/pytorch/issues/157673#issuecomment-3051682766
    """

    def get_msvc_cl_path() -> tuple[bool, str]:
        """
        Finds the path to cl.exe using vswhere.exe.
        """
        vswhere_path = os.path.join(os.environ.get('ProgramFiles(x86)', 'C:\\Program Files (x86)'), 'Microsoft Visual Studio', 'Installer', 'vswhere.exe')
        if not os.path.exists(vswhere_path):
            vswhere_path = os.path.join(os.environ.get('ProgramFiles', 'C:\\Program Files'), 'Microsoft Visual Studio', 'Installer', 'vswhere.exe')
            if not os.path.exists(vswhere_path):
                return (False, '')
        try:
            cmd = [vswhere_path, '-latest', '-prerelease', '-products', '*', '-requires', 'Microsoft.VisualStudio.Component.VC.Tools.x86.x64', '-property', 'installationPath']
            vs_install_path = subprocess.check_output(cmd, text=True, encoding='utf-8').strip()
            if not vs_install_path:
                return (False, '')
            msvc_tools_path = os.path.join(vs_install_path, 'VC', 'Tools', 'MSVC')
            if not os.path.exists(msvc_tools_path):
                return (False, '')
            toolset_versions = [d for d in os.listdir(msvc_tools_path) if os.path.isdir(os.path.join(msvc_tools_path, d))]
            if not toolset_versions:
                return (False, '')
            latest_toolset_version = sorted(toolset_versions, reverse=True)[0]
            cl_path = os.path.join(msvc_tools_path, latest_toolset_version, 'bin', 'HostX64', 'x64', 'cl.exe')
            if os.path.exists(cl_path):
                return (True, cl_path)
            else:
                cl_path = os.path.join(msvc_tools_path, latest_toolset_version, 'bin', 'HostX86', 'x86', 'cl.exe')
                if os.path.exists(cl_path):
                    return (True, cl_path)
        except (subprocess.CalledProcessError, FileNotFoundError):
            return (False, '')
        return (False, '')
    if <MASK>:
        return
    if os.path.exists(compiler):
        cl_exe_path = compiler
    else:
        (b_ret, cl_exe_path) = get_msvc_cl_path()
        if b_ret is False:
            return
    version_info = WinPeFileVersionInfo(cl_exe_path)
    lang_id = version_info.get_language_id()
    if lang_id != 1033:
        raise RuntimeError('Torch.compile() is only support MSVC with English language pack,Please reinstall its language pack to English.')

def reduction_reference(op, sample):
    assert sample.input.is_nested
    assert op._extra_op_data.dim_args is not None
    (single_dim_argname, dimlist_argname) = op._extra_op_data.get_dim_argnames()
    assert single_dim_argname is not None
    dim = sample.kwargs.get(dimlist_argname, sample.kwargs.get(single_dim_argname, None))
    keepdim = sample.kwargs.get('keepdim', False)
    assert dim != 0, 'reductions over just the batch dim are not supported'
    if <MASK>:
        reduce_on_ragged = sample.input._ragged_idx in dim
        reduce_on_batch = 0 in dim
    else:
        reduce_on_ragged = sample.input._ragged_idx == dim
        reduce_on_batch = dim == 0
    if dim is None:
        return op.op(sample.input.values(), *sample.args, **sample.kwargs)
    if reduce_on_ragged and reduce_on_batch:
        from torch.nested._internal.ops import _outer_to_inner_dim
        ref_kwargs = dict(sample.kwargs)
        assert dimlist_argname is not None
        ref_kwargs[dimlist_argname] = _outer_to_inner_dim(sample.input.dim(), dim, sample.input._ragged_idx, canonicalize=True)
        out = op.op(sample.input.values(), *sample.args, **ref_kwargs)
        if keepdim:
            if isinstance(out, (tuple, list)):
                out = type(out)((o.unsqueeze(0) for o in out))
            else:
                out = out.unsqueeze(0)
        return out
    if reduce_on_ragged and (not reduce_on_batch):
        out_ref_components = unbind_reference(op, sample, wrap_output_as_njt=False)
        if len(out_ref_components) > 0 and isinstance(out_ref_components[0], (tuple, list)):
            num_returns = len(out_ref_components[0])
            assert all((len(o) == num_returns for o in out_ref_components))
            stacked_returns = [torch.stack([o[r] for o in out_ref_components], dim=0) for r in range(num_returns)]
            return type(out_ref_components[0])(stacked_returns)
        return torch.stack(out_ref_components, dim=0)
    return unbind_reference(op, sample)

@classmethod
def create(cls, device: torch.device, dst_dtype: torch.dtype, src_dtype: torch.dtype, inner_fn: Callable[..., Any], ranges: Sequence[Expr], reduction_ranges: Sequence[Expr], reduction_type: ReductionType, reduction_hint: ReductionHint=ReductionHint.DEFAULT, input_node: Optional[IRNode]=None) -> Union[TensorBox, ShapeAsConstantBuffer]:
    reduction_numel = V.graph.sizevars.simplify(sympy_product(reduction_ranges))
    if reduction_numel == 0:

        def py_cnst(val: object) -> Union[bool, float, int]:
            if dst_dtype == torch.bool:
                return bool(val)
            elif dst_dtype.is_floating_point:
                assert isinstance(val, SupportsFloat), type(val)
                return float(val)
            else:
                assert isinstance(val, SupportsInt), type(val)
                return int(val)
        rtypes_to_inits = {'sum': py_cnst(0), 'xor_sum': py_cnst(0), 'prod': py_cnst(1), 'any': py_cnst(0)}
        assert reduction_type in rtypes_to_inits.keys(), f'{reduction_type} not supported for zero-dimension tensors!'

        def const_fn(index: int) -> OpsValue:
            return ops.constant(rtypes_to_inits[reduction_type], dst_dtype)
        return Pointwise.create(device=device, dtype=src_dtype, inner_fn=const_fn, ranges=list(ranges))
    if reduction_numel == 1:
        if reduction_type in ('argmin', 'argmax'):

            def fn(index: int) -> OpsValue:
                return ops.constant(0, dst_dtype)
        else:

            def fn(index: int) -> OpsValue:
                reduction_index = [sympy.S.Zero for _ in reduction_ranges]
                return inner_fn(index, reduction_index)
        return Pointwise.create(device=device, dtype=dst_dtype, inner_fn=fn, ranges=ranges)
    if isinstance(reduction_numel, Integer) and V.graph.sizevars.size_hint_or_throw(reduction_numel) < config.unroll_reductions_threshold and (sympy_product(ranges) != 1 or is_gpu(device.type)) and (reduction_type != 'dot'):
        return Pointwise.create(device=device, dtype=dst_dtype, inner_fn=cls._unroll_reduction_fn(inner_fn, reduction_ranges, reduction_type, src_dtype), ranges=ranges)
    (hint, split) = cls.num_splits(device, dst_dtype, src_dtype, inner_fn, ranges, reduction_ranges, reduction_type, reduction_numel, input_node)

    def _maybe_increase_split(split: int) -> int:
        if <MASK>:
            return split
        if split > 1:
            return max(split, config.min_num_split)
        else:
            return split
    split = _maybe_increase_split(split)
    if reduction_hint == ReductionHint.DEFAULT:
        reduction_hint = hint
    if split == -1:
        assert input_node is not None
        with patch.object(FlexibleLayout, 'allow_indexing', True):
            (new_ranges, new_reduction_ranges) = extract_input_node_reduction_ranges(input_node)
        assert new_ranges is not None
        assert new_reduction_ranges is not None
        return cls.create_multilayer_existing_ranges(device, dst_dtype, src_dtype, inner_fn, ranges, reduction_ranges, new_ranges, new_reduction_ranges, reduction_type, reduction_hint)
    elif split > 1:
        return cls.create_multilayer(device, dst_dtype, src_dtype, inner_fn, ranges, reduction_ranges, reduction_type, split, reduction_hint, input_node)
    return TensorBox.create(Reduction(device=device, dtype=dst_dtype, inner_fn=inner_fn, ranges=ranges, reduction_ranges=reduction_ranges, reduction_type=reduction_type, src_dtype=src_dtype, reduction_hint=reduction_hint))

def _create_symbol_for_source(self, source: Source) -> Optional[sympy.Symbol]:
    if not self._translation_validation_enabled:
        return None
    srcname = source.name()
    if <MASK>:
        self.source_to_symbol[srcname] = sympy.Symbol(srcname, integer=True)
    return self.source_to_symbol[srcname]

def sample_inputs_scatter(op_info, device, dtype, requires_grad, **kwargs):

    def _tensor(shape, dtype=dtype, low=None, high=None):
        return make_tensor(shape, dtype=dtype, device=device, low=low, high=high, requires_grad=requires_grad)

    def _gather(shape, index_dim, max_indices):
        return gather_variable(shape, index_dim, max_indices, device=device)
    zero = torch.tensor(0, dtype=torch.long, device=device)
    test_cases = ((_tensor((M, S)), (0, _gather((S, S), 1, M), _tensor((S, S)))), (_tensor((M, S)), (0, _gather((S, S), 1, M).to(torch.int32), _tensor((S, S)))), (_tensor((M, S)), (1, _gather((S, S), 0, S), _tensor((S, S)))), (_tensor((M, S)), (-1, _gather((S, S), 0, S), _tensor((S, S)))), (_tensor((M, S)), (0, _gather((M, S // 2), 1, M), _tensor((M, S // 2)))), (_tensor((M, S)), (1, _gather((M, S // 2), 0, S), _tensor((M, S // 2)))), (_tensor((M, S)), (-1, _gather((M, S // 2), 0, S), _tensor((M, S // 2)))), (_tensor(()), (0, zero.detach().clone(), _tensor(()))), (_tensor(()), (0, zero.detach().clone(), 2.5)))
    for (tensor, args) in test_cases:
        yield SampleInput(tensor, *args)
        if not requires_grad:
            yield SampleInput(tensor.detach().clone(), *args, reduce='add')
            if <MASK>:
                yield SampleInput(tensor.detach().clone(), *args, reduce='multiply')

@cached_property
def base_manager(self):
    base_manager_name = self.base_manager_name
    if <MASK>:
        for parent in self.model.mro()[1:]:
            if hasattr(parent, '_meta'):
                if parent._base_manager.name != '_base_manager':
                    base_manager_name = parent._base_manager.name
                break
    if base_manager_name:
        try:
            return self.managers_map[base_manager_name]
        except KeyError:
            raise ValueError('%s has no manager named %r' % (self.object_name, base_manager_name))
    manager = Manager()
    manager.name = '_base_manager'
    manager.model = self.model
    manager.auto_created = True
    return manager

def extract_normalized_read_writes(node: Union['FusedSchedulerNode', 'SchedulerNode']) -> Optional[FusedNormalizedReadsWrites]:
    """Extracts index variables, reduce variables, read/write expressions, and variable ranges from a fused node."""
    reads: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
    writes: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
    all_output_names = node.get_buffer_names()
    op_names = node.get_operation_names()
    outputs: OrderedSet[str] = OrderedSet()
    removed_buffers: OrderedSet[str] = OrderedSet()
    for buf_name in all_output_names:
        if V.graph.scheduler.can_buffer_be_removed_through_fusion(buf_name, op_names):
            removed_buffers.add(buf_name)
        else:
            outputs.add(buf_name)
    inputs = OrderedSet((dep.name for dep in node.read_writes.reads if dep.name not in removed_buffers))
    pointwise_numel: sympy.Expr = node.group[1][0]
    red_numel: sympy.Expr = node.group[1][1]
    if any((isinstance(var, sympy.Expr) and (not var.is_constant()) for var in (pointwise_numel, red_numel))):
        return None
    (pw_splits, red_splits) = NodeSplitGetter(node).get_node_splits()
    ((norm_pw_vars, norm_red_vars), ranges) = index_vars_no_squeeze(pw_splits, red_splits, prefix='n')
    for n in list(node.get_nodes()):
        if <MASK>:
            continue
        body = n._body
        if body.indirect_vars:
            return None
        n_reads: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
        n_writes: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
        for inp in inputs:
            for expr in body.get_all_read_expr(inp):
                n_reads[expr].add(inp)
        for out in outputs:
            for expr in body.get_all_write_expr(out):
                n_writes[expr].add(out)
        if not n_reads and (not n_writes):
            continue
        ((iter_vars, n_pw_splits), (red_vars, n_red_splits)) = get_pw_red_splits(n, pointwise_numel, red_numel)
        groups = pw_splits + red_splits
        lengths = (n_pw_splits, n_red_splits)
        lengths = torch._inductor.codegen.simd.SIMDKernel.prepare_split_iteration_lengths(groups, lengths, red_numel)
        (new_ranges, return_getters_groups) = torch._inductor.codegen.simd.SIMDKernel._split_iteration_ranges(groups, lengths)
        var_map = apply_var_mapping(iter_vars, red_vars, norm_pw_vars, norm_red_vars, new_ranges, return_getters_groups)

        def remove_identity(expr: sympy.Expr) -> sympy.Expr:
            return expr.replace(Identity, lambda x: x)
        n_reads_new = {sympy_subs(remove_identity(read), var_map): v for (read, v) in n_reads.items()}
        n_writes_new = {sympy_subs(remove_identity(write), var_map): v for (write, v) in n_writes.items()}
        for (expr, buf_names) in n_reads_new.items():
            reads[expr] |= buf_names
        for (expr, buf_names) in n_writes_new.items():
            writes[expr] |= buf_names
    reads = {V.graph.sizevars.simplify_with_ranges(r, ranges): v for (r, v) in reads.items()}
    writes = {V.graph.sizevars.simplify_with_ranges(w, ranges): v for (w, v) in writes.items()}
    fused_out = FusedNormalizedReadsWrites(norm_pw_vars, norm_red_vars, reads, writes, ranges)
    loop_tiling_log.info('Normalized Fused reads: %s', fused_out)
    return fused_out

def find_functions(filename, tag='API'):
    """
    Scan the file, looking for tagged functions.

    Assuming ``tag=='API'``, a tagged function looks like::

        /*API*/
        static returntype*
        function_name(argtype1 arg1, argtype2 arg2)
        {
        }

    where the return type must be on a separate line, the function
    name must start the line, and the opening ``{`` must start the line.

    An optional documentation comment in ReST format may follow the tag,
    as in::

        /*API
          This function does foo...
         */
    """
    if filename.endswith(('.c.src', '.h.src')):
        fo = io.StringIO(process_c_file(filename))
    else:
        fo = open(filename, 'r')
    functions = []
    return_type = None
    function_name = None
    function_args = []
    doclist = []
    (SCANNING, STATE_DOC, STATE_RETTYPE, STATE_NAME, STATE_ARGS) = list(range(5))
    state = SCANNING
    tagcomment = '/*' + tag
    for (lineno, line) in enumerate(fo):
        try:
            line = line.strip()
            if state == SCANNING:
                if line.startswith(tagcomment):
                    if line.endswith('*/'):
                        state = STATE_RETTYPE
                    else:
                        state = STATE_DOC
            elif state == STATE_DOC:
                if line.startswith('*/'):
                    state = STATE_RETTYPE
                else:
                    line = line.lstrip(' *')
                    doclist.append(line)
            elif state == STATE_RETTYPE:
                m = re.match('NPY_NO_EXPORT\\s+(.*)$', line)
                if m:
                    line = m.group(1)
                return_type = line
                state = STATE_NAME
            elif <MASK>:
                m = re.match('(\\w+)\\s*\\(', line)
                if m:
                    function_name = m.group(1)
                else:
                    raise ParseError(filename, lineno + 1, 'could not find function name')
                function_args.append(line[m.end():])
                state = STATE_ARGS
            elif state == STATE_ARGS:
                if line.startswith('{'):
                    fargs_str = ' '.join(function_args).rstrip()[:-1].rstrip()
                    fargs = split_arguments(fargs_str)
                    f = Function(function_name, return_type, fargs, '\n'.join(doclist))
                    functions.append(f)
                    return_type = None
                    function_name = None
                    function_args = []
                    doclist = []
                    state = SCANNING
                else:
                    function_args.append(line)
        except ParseError:
            raise
        except Exception as e:
            msg = 'see chained exception for details'
            raise ParseError(filename, lineno + 1, msg) from e
    fo.close()
    return functions

@_make_elementwise_binary_reference(type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.BOOL_TO_LONG)
def pow(a: Union[TensorLikeType, NumberType], b: Union[TensorLikeType, NumberType]) -> TensorLikeType:
    assert isinstance(a, TensorLikeType) or isinstance(b, TensorLikeType)
    if <MASK>:
        if b == 1.0:
            return a.clone()
        elif b == 2.0:
            return a * a
        elif b == 0.5:
            return torch.sqrt(a)
    elif isinstance(a, Number):
        if a == 1.0:
            return torch.fill(b, True)
        if a == 2.0 and (utils.is_float_dtype(b.dtype) or utils.is_complex_dtype(b.dtype)):
            return torch.exp2(b)
    return prims.pow(a, b)

@staticmethod
def should_use_persistent_reduction(features: SIMDKernelFeatures, cooperative_reduction: bool) -> bool:
    """
        Heuristic to decide if a persistent reduction should be used.
        """
    if not config.triton.persistent_reductions:
        return False
    threshold = {ReductionHint.INNER: 1024}.get(features.get_reduction_hint(), 64)
    if features.get_reduction_hint() not in (ReductionHint.INNER, ReductionHint.OUTER_TINY):
        bounds = bound_sympy(features.reduction_numel)
        lower = bounds.lower
        upper = bounds.upper
        if not all(((isinstance(bound, int) or bound.is_constant()) and bound != torch.utils._sympy.numbers.IntInfinity() for bound in (lower, upper))):
            return False
        lower = next_power_of_2(int(lower))
        upper = next_power_of_2(int(upper))
        if lower != upper:
            return False
    if cooperative_reduction:
        try:
            threshold *= 32 // min(V.graph.sizevars.size_hint_or_throw(features.numel), 32)
        except ValueError:
            pass
    if <MASK>:
        threshold *= 16
    return V.graph.sizevars.statically_known_leq(features.reduction_numel, threshold)

def _get_ordinal_range(start, end, periods, freq, mult: int=1):
    if <MASK>:
        raise ValueError('Of the three parameters: start, end, and periods, exactly two must be specified')
    if freq is not None:
        freq = to_offset(freq, is_period=True)
        mult = freq.n
    if start is not None:
        start = Period(start, freq)
    if end is not None:
        end = Period(end, freq)
    is_start_per = isinstance(start, Period)
    is_end_per = isinstance(end, Period)
    if is_start_per and is_end_per and (start.freq != end.freq):
        raise ValueError('start and end must have same freq')
    if start is NaT or end is NaT:
        raise ValueError('start and end must not be NaT')
    if freq is None:
        if is_start_per:
            freq = start.freq
        elif is_end_per:
            freq = end.freq
        else:
            raise ValueError('Could not infer freq from start/end')
        mult = freq.n
    if periods is not None:
        periods = periods * mult
        if start is None:
            data = np.arange(end.ordinal - periods + mult, end.ordinal + 1, mult, dtype=np.int64)
        else:
            data = np.arange(start.ordinal, start.ordinal + periods, mult, dtype=np.int64)
    else:
        data = np.arange(start.ordinal, end.ordinal + 1, mult, dtype=np.int64)
    return (data, freq)

def load_dlmc_dataset(dataset_path, operation, hidden_size, sparsity, device, requires_grad, n_limit=math.inf):
    """load_dlmc_dataset loads a DLMC dataset for a matmul performance test.
    Args:
        dataset_path:
            path of the dataset from DLMC collection.
        operation:
            This value allows tensors for `sparse@sparse`|`sparse@dense`|`sparse@vector` operations.
        hidden_size
            This value allows tensors of varying sizes.
        sparsity:
            This value allows tensors of varying sparsities.
        device:
            Whether to place the Tensor on a GPU or CPU.
        requires_grad:
            Loads the dataset for backward test.
        n_limit:
            This value allows a dataset with some limit size.
    """
    if <MASK>:
        collection = load_spmm_dataset(dataset_path, hidden_size, sparsity, operation, device, n_limit)
    elif operation == 'sparse@vector':
        collection = load_spmv_dataset(dataset_path, hidden_size, sparsity, device, n_limit)
    scipy_vars = {}
    backward_vars = {}
    for (x, y) in collection:
        if device == 'cpu':
            scipy_vars = {'sx': to_coo_scipy(x) if x.is_sparse else x.numpy(), 'sy': to_coo_scipy(y) if y.is_sparse else y.numpy()}
        if not requires_grad:
            dx = x.to_dense() if x.is_sparse else x
            dy = y.to_dense() if y.is_sparse else y
        else:
            c = sparse_grad_output(x, y)
            backward_vars = {'sparse_grad_output': c, 'grad_output': c.to_dense() if c.is_sparse else c}
            x.requires_grad_(True)
            y.requires_grad_(True)
            dx = x.to_dense().detach() if x.is_sparse else x.clone().detach()
            dy = y.to_dense().detach() if y.is_sparse else y.clone().detach()
            dx.requires_grad_(True)
            dy.requires_grad_(True)
        yield {'x': x, 'y': y, 'dx': dx, 'dy': dy, **scipy_vars, **backward_vars}

def _codegen(self, nodes: list[BaseSchedulerNode]) -> None:
    if config.check_stack_no_cycles_TESTING_ONLY:
        import torch._dynamo.convert_frame
        stack = traceback.extract_stack()
        seen: OrderedSet[tuple[str, int | None]] = OrderedSet()
        for frame in reversed(stack):
            if frame.name == '_compile_inner' and frame.filename == torch._dynamo.convert_frame.__file__:
                break
            key = (frame.filename, frame.lineno)
            assert key not in seen, f'Duplicate stack frame {frame.filename}:{frame.lineno}; did you add a decorator to one of the functions in this stack trace?  If so, try using a context manager instead.'
            seen.add(key)
    self.current_device = self.default_device_context
    if self.default_device_context and config.triton.autotune_at_compile_time:
        V.graph.wrapper_code.write_get_raw_stream_header()
    for node in nodes:
        if log.isEnabledFor(logging.DEBUG):
            try:
                log.debug('Generating code for node %s with estimated runtime %f', node.get_name(), node.get_estimated_runtime())
            except Exception:
                log.debug('Generating code for node %s with estimated runtime 0.0', node.get_name())
        self.enter_context(node)
        if (device := node.get_device()):
            if device != self.current_device or node.is_extern() or node.is_template():
                self.flush()
            if device != self.current_device:
                if self.current_device and device_need_guard(self.current_device.type):
                    V.graph.wrapper_code.codegen_device_guard_exit()
                self.current_device = device
                if device_need_guard(device.type):
                    assert device.index is not None, 'device should have an index'
                    V.graph.wrapper_code.codegen_device_guard_enter(device.index)
        self.current_node = node
        self.buffer_names_to_free.update(node.last_usage)
        if node.is_template():
            (prologue, template_node, epilogue) = node.get_prologue_template_epilogue(list(node.get_nodes()))
            self.get_backend(device).codegen_template(template_node, epilogue, prologue)
        elif node.is_extern():
            node = typing.cast(ExternKernelSchedulerNode, node)
            self.codegen_extern_call(node)
        elif node.is_foreach():
            node = typing.cast(ForeachKernelSchedulerNode, node)
            backend_ = self.get_backend(device)
            from .codegen.cuda_combined_scheduling import CUDACombinedScheduling
            from .codegen.simd import SIMDScheduling
            if isinstance(backend_, (SIMDScheduling, CUDACombinedScheduling)):
                backend = backend_
            else:
                raise AssertionError(f'type(self)={type(self)!r}')
            backend.codegen_combo_kernel(node)
        elif isinstance(node, (FusedSchedulerNode, SchedulerNode)):
            self.get_backend(device).codegen_node(node)
        else:
            assert isinstance(node, NopKernelSchedulerNode)
            node.mark_run()
        if config.triton.debug_sync_kernel:
            self.get_backend(device).codegen_sync()
        self.available_buffer_names.update(node.get_buffer_names())
        self.completed_operations.update(node.get_operation_names())
        if not isinstance(node, NopKernelSchedulerNode):
            device = node.get_device()
            if <MASK>:
                self.flush()
    if self.current_device != self.default_device_context:
        assert self.current_device is not None
        if device_need_guard(self.current_device.type):
            V.graph.wrapper_code.codegen_device_guard_exit()
    self.flush()

@functools.lru_cache(maxsize=1000)
def _parse_accept_lang_header(lang_string):
    """
    Parse the lang_string, which is the body of an HTTP Accept-Language
    header, and return a tuple of (lang, q-value), ordered by 'q' values.

    Return an empty tuple if there are any format errors in lang_string.
    """
    result = []
    pieces = accept_language_re.split(lang_string.lower())
    if pieces[-1]:
        return ()
    for i in range(0, len(pieces) - 1, 3):
        (first, lang, priority) = pieces[i:i + 3]
        if first:
            return ()
        if <MASK>:
            priority = float(priority)
        else:
            priority = 1.0
        result.append((lang, priority))
    result.sort(key=lambda k: k[1], reverse=True)
    return tuple(result)

def _python_agg_general(self, func, *args, **kwargs):
    f = lambda x: func(x, *args, **kwargs)
    if <MASK>:
        return self._python_apply_general(f, self._selected_obj, is_agg=True)
    obj = self._obj_with_exclusions
    if not len(obj.columns):
        return self._python_apply_general(f, self._selected_obj)
    output: dict[int, ArrayLike] = {}
    for (idx, (name, ser)) in enumerate(obj.items()):
        result = self._grouper.agg_series(ser, f)
        output[idx] = result
    res = self.obj._constructor(output)
    res.columns = obj.columns.copy(deep=False)
    return self._wrap_aggregated_output(res)

def _cmp_method(self, other, op):
    res_name = ops.get_op_result_name(self, other)
    if <MASK>:
        raise ValueError('Can only compare identically-labeled Series objects')
    lvalues = self._values
    rvalues = extract_array(other, extract_numpy=True, extract_range=True)
    res_values = ops.comparison_op(lvalues, rvalues, op)
    return self._construct_result(res_values, name=res_name, other=other)

def _apply_series(self, homogeneous_func: Callable[..., ArrayLike], name: str | None=None) -> Series:
    """
        Series version of _apply_columnwise
        """
    obj = self._create_data(self._selected_obj)
    if <MASK>:
        obj = notna(obj).astype(int)
    try:
        values = self._prep_values(obj._values)
    except (TypeError, NotImplementedError) as err:
        raise DataError('No numeric types to aggregate') from err
    result = homogeneous_func(values)
    index = self._slice_axis_for_step(obj.index, result)
    return obj._constructor(result, index=index, name=obj.name)

def execute_sql(self, result_type=MULTI, chunked_fetch=False, chunk_size=GET_ITERATOR_CHUNK_SIZE):
    """
        Run the query against the database and return the result(s). The
        return value depends on the value of result_type.

        When result_type is:
        - MULTI: Retrieves all rows using fetchmany(). Wraps in an iterator for
           chunked reads when supported.
        - SINGLE: Retrieves a single row using fetchone().
        - ROW_COUNT: Retrieves the number of rows in the result.
        - CURSOR: Runs the query, and returns the cursor object. It is the
           caller's responsibility to close the cursor.
        """
    result_type = result_type or NO_RESULTS
    try:
        (sql, params) = self.as_sql()
        if not sql:
            raise EmptyResultSet
    except EmptyResultSet:
        if result_type == MULTI:
            return iter([])
        else:
            return
    if chunked_fetch:
        cursor = self.connection.chunked_cursor()
    else:
        cursor = self.connection.cursor()
    try:
        cursor.execute(sql, params)
    except Exception:
        cursor.close()
        raise
    if result_type == ROW_COUNT:
        try:
            return cursor.rowcount
        finally:
            cursor.close()
    if result_type == CURSOR:
        return cursor
    if result_type == SINGLE:
        try:
            val = cursor.fetchone()
            if val:
                return val[0:self.col_count]
            return val
        finally:
            cursor.close()
    if result_type == NO_RESULTS:
        cursor.close()
        return
    result = cursor_iter(cursor, self.connection.features.empty_fetchmany_value, self.col_count if self.has_extra_select else None, chunk_size)
    if <MASK>:
        return list(result)
    return result

def _compare_attributes(self, actual: torch.Tensor, expected: torch.Tensor) -> None:
    """Checks if the attributes of two tensors match.

        Always checks

        - the :attr:`~torch.Tensor.shape`,
        - whether both inputs are quantized or not,
        - and if they use the same quantization scheme.

        Checks for

        - :attr:`~torch.Tensor.layout`,
        - :meth:`~torch.Tensor.stride`,
        - :attr:`~torch.Tensor.device`, and
        - :attr:`~torch.Tensor.dtype`

        are optional and can be disabled through the corresponding ``check_*`` flag during construction of the pair.
        """

    def raise_mismatch_error(attribute_name: str, actual_value: Any, expected_value: Any) -> NoReturn:
        self._fail(AssertionError, f"The values for attribute '{attribute_name}' do not match: {actual_value} != {expected_value}.")
    if <MASK>:
        raise_mismatch_error('shape', actual.shape, expected.shape)
    if actual.is_quantized != expected.is_quantized:
        raise_mismatch_error('is_quantized', actual.is_quantized, expected.is_quantized)
    elif actual.is_quantized and actual.qscheme() != expected.qscheme():
        raise_mismatch_error('qscheme()', actual.qscheme(), expected.qscheme())
    if actual.layout != expected.layout:
        if self.check_layout:
            raise_mismatch_error('layout', actual.layout, expected.layout)
    elif actual.layout == torch.strided and self.check_stride and (actual.stride() != expected.stride()):
        raise_mismatch_error('stride()', actual.stride(), expected.stride())
    if self.check_device and actual.device != expected.device:
        raise_mismatch_error('device', actual.device, expected.device)
    if self.check_dtype and actual.dtype != expected.dtype:
        raise_mismatch_error('dtype', actual.dtype, expected.dtype)

def _maybe_modify_args(self, node, full_name, name):
    """Rename keyword args if the function called full_name requires it."""
    renamed_keywords = self._get_applicable_dict('function_keyword_renames', full_name, name)
    if <MASK>:
        return False
    if uses_star_kwargs_in_call(node):
        self.add_log(WARNING, node.lineno, node.col_offset, '(Manual check required) upgrading %s may require renaming or removing call arguments, but it was passed variable-length *args or **kwargs. The upgrade script cannot handle these automatically.' % (full_name or name))
    modified = False
    new_keywords = []
    for keyword in node.keywords:
        argkey = keyword.arg
        if argkey in renamed_keywords:
            modified = True
            if renamed_keywords[argkey] is None:
                lineno = getattr(keyword, 'lineno', node.lineno)
                col_offset = getattr(keyword, 'col_offset', node.col_offset)
                self.add_log(INFO, lineno, col_offset, 'Removed argument %s for function %s' % (argkey, full_name or name))
            else:
                keyword.arg = renamed_keywords[argkey]
                lineno = getattr(keyword, 'lineno', node.lineno)
                col_offset = getattr(keyword, 'col_offset', node.col_offset)
                self.add_log(INFO, lineno, col_offset, 'Renamed keyword argument for %s from %s to %s' % (full_name, argkey, renamed_keywords[argkey]))
                new_keywords.append(keyword)
        else:
            new_keywords.append(keyword)
    if modified:
        node.keywords = new_keywords
    return modified

def __setattr__(self, name: str, value: Any) -> None:
    if name == 'name' and hasattr(self, 'name'):
        m = self.graph.owning_module
        if getattr(m, '_replace_hooks', None):
            assert isinstance(value, str)
            for user in self.users:
                for replace_hook in m._replace_hooks:
                    replace_hook(old=self, new=value, user=user)
    update = False
    if hasattr(self, name) and hasattr(self.graph, '_find_nodes_lookup_table') and (self in self.graph._find_nodes_lookup_table):
        update = True
        self.graph._find_nodes_lookup_table.remove(self)
    object.__setattr__(self, name, value)
    if <MASK>:
        self.graph._find_nodes_lookup_table.insert(self)

@deprecate_nonkeyword_arguments(Pandas4Warning, allowed_args=['self'], name='min')
@doc(make_doc('min', ndim=2))
def min(self, axis: Axis | None=0, skipna: bool=True, numeric_only: bool=False, **kwargs) -> Series | Any:
    result = super().min(axis=axis, skipna=skipna, numeric_only=numeric_only, **kwargs)
    if <MASK>:
