    return result

def allocate_non_dup_const_name(self, name: Optional[str], data: Union[Tensor]) -> str:
    if not config.aot_inductor.use_runtime_constant_folding:
        for (constant_name, value) in self.constants.items():
            if <MASK>:
                return constant_name
    if name is None:
        name = f'constant{len(self.constants)}'
    orig_name = name
    if name[0].isdigit():
        name = f'constant_{name}'
    name = self.qualify_name(name)
    prefix = normalize_name(name)
    name = prefix
    cnt = 0
    while name in self.constants:
        name = f'{prefix}_{cnt}'
        cnt += 1
    self.constants[name] = data
    self.constant_reprs[name] = f'{data.device!r} {data.dtype!r} {tuple(data.size())!r} {tuple(data.stride())!r} {hash(data):x}'
    self.allocated_constant_name[name] = orig_name
    return name

@parameterized.parameters([(polymorphic_function.function, dummy_tf_decorator), (dummy_tf_decorator, polymorphic_function.function), (polymorphic_function.function, polymorphic_function.function)])
def testWithExtraWrapperRedundantArgs(self, decorator1, decorator2):

    class Foo(module.Module):

        def __init__(self):
            super().__init__()
            self.var = None

        @decorator1
        @decorator2
        def add1(self, x, y):
            if <MASK>:
                return x + y
    foo = Foo()
    with self.assertRaisesRegex(TypeError, 'multiple values for argument'):
        foo.add1(2, x=3)

def _apply_on_tensors(self, fn, args):
    tensors_idx = []
    tensors = []
    requires_grad = False
    for (i, arg) in enumerate(args):
        if <MASK>:
            tensors_idx.append(i)
            tensors.append(arg)
            requires_grad |= arg.requires_grad
    if not (requires_grad and torch.is_grad_enabled()):
        return (args, None)
    new_tensors = torch.nn.modules._functions.BackwardHookFunction.apply(*tensors)
    if len(new_tensors) == 0:
        raise RuntimeError('Cannot set Module backward hook for a Module with no input Tensors.')
    grad_fns = [t.grad_fn for t in new_tensors if t.grad_fn is not None and t.grad_fn.name() == 'BackwardHookFunctionBackward']
    if len(grad_fns) == 0:
        raise RuntimeError('Error while setting up backward hooks. Please open an issue with a code sample to reproduce this.')
    fn(grad_fns[0])
    arg_list = list(args)
    for (idx, val) in zip(tensors_idx, new_tensors):
        arg_list[idx] = val
    if type(args) is tuple:
        out = tuple(arg_list)
    else:
        out = type(args)(*arg_list)
    return (out, tensors_idx)

def _quantile(self, qs: npt.NDArray[np.float64], interpolation: str) -> BaseMaskedArray:
    """
        Dispatch to quantile_with_mask, needed because we do not have
        _from_factorized.

        Notes
        -----
        We assume that all impacted cases are 1D-only.
        """
    res = quantile_with_mask(self._data, mask=self._mask, fill_value=np.nan, qs=qs, interpolation=interpolation)
    if <MASK>:
        if self.ndim == 2:
            raise NotImplementedError
        if self.isna().all():
            out_mask = np.ones(res.shape, dtype=bool)
            if is_integer_dtype(self.dtype):
                res = np.zeros(res.shape, dtype=self.dtype.numpy_dtype)
        else:
            out_mask = np.zeros(res.shape, dtype=bool)
    else:
        out_mask = np.zeros(res.shape, dtype=bool)
    return self._maybe_mask_result(res, mask=out_mask)

def _fft_c2r(func_name: str, input: TensorLikeType, n: Optional[int], dim: int, norm: NormType, forward: bool) -> TensorLikeType:
    """Common code for performing any complex to real FFT (irfft or hfft)"""
    input = _maybe_promote_tensor_fft(input, require_complex=True)
    dims = (utils.canonicalize_dim(input.ndim, dim, wrap_scalar=False),)
    last_dim_size = n if n is not None else 2 * (input.shape[dim] - 1)
    torch._check(last_dim_size >= 1, lambda : f'Invalid number of data points ({last_dim_size}) specified')
    if <MASK>:
        input = _resize_fft_input(input, dims=dims, sizes=(last_dim_size // 2 + 1,))
    if forward:
        input = torch.conj(input)
    output = prims.fft_c2r(input, dim=dims, last_dim_size=last_dim_size)
    return _apply_norm(output, norm=norm, signal_numel=last_dim_size, forward=forward)

def extract_df(self, metric, testing):
    for iter in itertools.product(self.suites, self.devices, self.dtypes):
        (suite, device, dtype) = iter
        frames = []
        for compiler in self.compilers:
            output_filename = f'{self.output_dir}/{compiler}_{suite}_{dtype}_{self.mode}_{device}_{testing}.csv'
            df = self.read_csv(output_filename)
            if metric not in df:
                df.insert(len(df.columns), metric, np.nan)
            df = df[['dev', 'name', 'batch_size', metric]]
            df.rename(columns={metric: compiler}, inplace=True)
            df['batch_size'] = df['batch_size'].astype(int)
            frames.append(df)
        frames = self.clean_batch_sizes(frames)
        if len(self.compilers) == 1:
            df = frames[0]
        else:
            df = pd.merge(frames[0], frames[1], on=['dev', 'name', 'batch_size'])
            for idx in range(2, len(frames)):
                df = pd.merge(df, frames[idx], on=['dev', 'name', 'batch_size'])
        if testing == 'performance':
            for compiler in self.compilers:
                df[compiler] = pd.to_numeric(df[compiler], errors='coerce').fillna(0)
        df_copy = df.copy()
        df_copy = df_copy.sort_values(by=list(reversed(self.compilers)), ascending=False)
        if 'inductor' in self.compilers:
            df_copy = df_copy.sort_values(by='inductor', ascending=False)
        self.untouched_parsed_frames[suite][metric] = df_copy
        if testing == 'performance':
            df_accuracy = self.parsed_frames[suite]['accuracy']
            perf_rows = []
            for model_name in df['name']:
                perf_row = df[df['name'] == model_name].copy()
                acc_row = df_accuracy[df_accuracy['name'] == model_name]
                for compiler in self.compilers:
                    if <MASK>:
                        if acc_row.empty:
                            perf_row[compiler] = 0.0
                        elif acc_row[compiler].iloc[0] in ('model_fail_to_load', 'eager_fail_to_run'):
                            perf_row = pd.DataFrame()
                        elif acc_row[compiler].iloc[0] not in ('pass', 'pass_due_to_skip'):
                            perf_row[compiler] = 0.0
                if not perf_row.empty:
                    perf_rows.append(perf_row)
            df = pd.concat(perf_rows)
        df = df.sort_values(by=list(reversed(self.compilers)), ascending=False)
        if 'inductor' in self.compilers:
            df = df.sort_values(by='inductor', ascending=False)
        self.parsed_frames[suite][metric] = df

def deregister(self, full_qualname: str) -> Any:
    if <MASK>:
        log.warning('Cannot deregister %s. Please use register_fake_class to register it first. Or do you dereigster it twice?', full_qualname)
    else:
        return self._registered_class.pop(full_qualname)

@click.command()
@click.argument('directory', default='artifacts')
@click.option('--amp', is_flag=True)
@click.option('--float32', is_flag=True)
@click.option('--perf-compare', is_flag=True, help='Set if the CSVs were generated by running manually the action rather than picking them from the nightly job')
def main(directory, amp, float32, perf_compare):
    """
    Given a directory containing multiple CSVs from --performance benchmark
    runs, aggregates and generates summary statistics similar to the web UI at
    https://torchci-git-fork-huydhn-add-compilers-bench-74abf8-fbopensource.vercel.app/benchmark/compilers

    This is most useful if you've downloaded CSVs from CI and need to quickly
    look at aggregate stats.  The CSVs are expected to follow exactly the same
    naming convention that is used in CI.

    You may also be interested in
    https://docs.google.com/document/d/1DQQxIgmKa3eF0HByDTLlcJdvefC4GwtsklJUgLs09fQ/edit#
    which explains how to interpret the raw csv data.
    """
    dtypes = ['amp', 'float32']
    if amp and (not float32):
        dtypes = ['amp']
    if float32 and (not amp):
        dtypes = ['float32']
    dfs = defaultdict(list)
    for f in find_csv_files(directory, perf_compare):
        try:
            dfs[os.path.basename(f)].append(pd.read_csv(f))
        except Exception:
            log.warning('failed parsing %s', f)
            raise
    results = defaultdict(lambda : defaultdict(lambda : defaultdict(dict)))
    for (k, v) in sorted(dfs.items()):
        if <MASK>:
            regex = 'training_(torchbench|huggingface|timm_models)\\.csv'
            m = re.match(regex, k)
            assert m is not None, k
            compiler = 'inductor'
            benchmark = m.group(1)
            dtype = 'float32'
            mode = 'training'
            device = 'cuda'
        else:
            regex = '(.+)_(torchbench|huggingface|timm_models)_(float32|amp)_(inference|training)_(cpu|cuda)_performance\\.csv'
            m = re.match(regex, k)
            compiler = m.group(1)
            benchmark = m.group(2)
            dtype = m.group(3)
            mode = m.group(4)
            device = m.group(5)
        df = pd.concat(v)
        df = df.dropna().query('speedup != 0')
        statistics = {'speedup': gmean(df['speedup']), 'comptime': df['compilation_latency'].mean(), 'memory': gmean(df['compression_ratio'])}
        if dtype not in dtypes:
            continue
        for (statistic, v) in statistics.items():
            results[f'{device} {dtype} {mode}'][statistic][benchmark][compiler] = v
    descriptions = {'speedup': 'Geometric mean speedup', 'comptime': 'Mean compilation time', 'memory': 'Peak memory compression ratio'}
    for (dtype_mode, r) in results.items():
        print(f'# {dtype_mode} performance results')
        for (statistic, data) in r.items():
            print(f'## {descriptions[statistic]}')
            table = []
            for row_name in data[next(iter(data.keys()))]:
                row = [row_name]
                for col_name in data:
                    row.append(round(data[col_name][row_name], 2))
                table.append(row)
            headers = list(data.keys())
            print(tabulate(table, headers=headers))
            print()

def compute(regid, InType, use_weights, isa, prefetch):
    code = []
    if InType == 'float':
        code.append(f'        vop{regid:d} = _mm256_fmadd_ps(vwgt, _mm256_loadu_ps(ip + ({regid:d})), vop{regid:d});')
    elif InType == 'at::Half':
        code.append(f'        vop{regid:d} = _mm256_fmadd_ps(\n            vwgt,\n            _mm256_cvtph_ps(\n                _mm_loadu_si128(reinterpret_cast<const __m128i*>(ip + ({regid:d})))),\n            vop{regid:d});')
    elif <MASK>:
        code.append(f'        vop{regid:d} = _mm256_fmadd_ps(\n            vwgt,\n            _mm256_castsi256_ps(_mm256_slli_epi32(\n                _mm256_cvtepu16_epi32(_mm_loadu_si128(\n                    reinterpret_cast<const __m128i*>(ip + ({regid:d})))),\n                16)),\n            vop{regid:d});')
    elif InType == 'uint8_t':
        code.append(f'        vop{regid:d} = _mm256_fmadd_ps(\n            vwgt,\n            _mm256_cvtepi32_ps(_mm256_cvtepu8_epi32(\n                _mm_loadl_epi64(reinterpret_cast<const __m128i*>(ip + ({regid:d}))))),\n            _mm256_add_ps(vop{regid:d}, vbio));')
    else:
        raise AssertionError
    if prefetch:
        code.append(f'        _mm_prefetch(\n            reinterpret_cast<const char*>(&ip_next_T0[{regid:d}]), _MM_HINT_T0);')
    else:
        code.append(f'        // skip unnecessary prefetch of (&ip_next_T0[{regid:d}])')
    return code

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    if name == '__getitem__':
        from .tensor import TensorVariable
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if isinstance(args[0], TensorVariable):
            value = get_fake_value(args[0].as_proxy().node, tx)
            if value.constant is not None and value.constant.numel() == 1:
                value = variables.ConstantVariable.create(value.constant.item())
            else:
                unimplemented_v2(gb_type='Indexing list with non-scalar tensor', context=f'call_method {self} {name} {args} {kwargs}', explanation='Attempted to index list-like object with tensor with > 1 element.', hints=[*graph_break_hints.USER_ERROR])
        else:
            value = args[0]
        if value.python_type() not in (int, slice):
            msg = f'indices must be integers or slices, not {value.python_type()}'
            raise_observed_exception(TypeError, tx, args=[ConstantVariable(msg)])
        return self.getitem_const(tx, value)
    elif name == '__contains__':
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return iter_contains(self.unpack_var_sequence(tx), args[0], tx)
    elif name == 'index':
        if not len(args):
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return tx.inline_user_function_return(VariableTracker.build(tx, polyfills.index), [self] + list(args), kwargs)
    elif name == 'count':
        if len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return VariableTracker.build(tx, operator.countOf).call_function(tx, [self, args[0]], kwargs)
    elif name in ('__add__', '__iadd__'):
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if type(self) is not type(args[0]):
            tp_name = self.python_type_name()
            other = args[0].python_type_name()
            msg = ConstantVariable.create(f'can only concatenate {tp_name} (not "{other}") to {tp_name}')
            raise_observed_exception(TypeError, tx, args=[msg])
        if name == '__add__':
            return type(self)(self.items + args[0].items, source=self.source)
        else:
            self.items += args[0].items
            return self
    elif name in ('__mul__', '__imul__'):
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not (args[0].is_python_constant() and args[0].python_type() is int):
            msg = ConstantVariable.create(f"can't multiply sequence by non-int type of '{args[0].python_type_name()}'")
            raise_observed_exception(TypeError, tx, args=[msg])
        val = args[0].as_python_constant()
        if name == '__mul__':
            return type(self)(self.items * val, source=self.source)
        else:
            self.items *= val
            return self
    elif <MASK>:
        if len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        left = self
        right = args[0]
        if not isinstance(left, BaseListVariable) or not isinstance(right, BaseListVariable):
            if name == '__eq__':
                return variables.BuiltinVariable(operator.is_).call_function(tx, (left, right), {})
            elif name == '__ne__':
                return variables.BuiltinVariable(operator.is_not).call_function(tx, (left, right), {})
            else:
                op_str = cmp_name_to_op_str_mapping[name]
                left_ty = left.python_type_name()
                right_ty = right.python_type_name()
                msg = f"{op_str} not supported between instances of '{left_ty}' and '{right_ty}'"
                raise_observed_exception(TypeError, tx, args=[msg])
        return variables.UserFunctionVariable(polyfills.list_cmp).call_function(tx, [variables.BuiltinVariable(cmp_name_to_op_mapping[name]), left, right], {})
    return super().call_method(tx, name, args, kwargs)

def __create_write_items__(self, fqn: str, object: Any):
    self._raise_if_contains_partial_placements()
    from torch.distributed.checkpoint.planner_helpers import _create_write_items_for_dtensor
    if <MASK>:
        return self._local_tensor.__create_write_items__(fqn, object)
    elif isinstance(self._local_tensor, torch.Tensor):
        return [_create_write_items_for_dtensor(fqn, object)]
    else:
        raise RuntimeError('Unsupported tensor type!')

def save_variables(saved_variables: Sequence[SavedAttribute], is_output: bool, guard_for: Callable[[SavedAttribute], str | None]=lambda name: None) -> Sequence[str]:
    stmts: list[str] = []
    for arg in sorted(saved_variables, key=lambda sa: str(sa.nctype.name)):
        name = arg.nctype.name.name if isinstance(arg.nctype.name, SpecialArgName) else arg.nctype.name
        foreacharg: Argument | None = None
        is_foreacharg_list_type: bool = False
        type = arg.nctype.type
        expr = arg.expr
        stmts_prepend = None
        if is_inplace_foreach and info is not None:
            name_to_query = name.split('_scalar_type')[0]
            if name_to_query in refargname2inplace_foreacharg:
                foreacharg = refargname2inplace_foreacharg[name_to_query]
                is_foreacharg_list_type = isinstance(foreacharg.type, ListType)
            if foreacharg is not None:
                name_in_expr = f"{foreacharg.name}{('[i]' if is_foreacharg_list_type else '')}"
                src_name = name
                if '_scalar_type' in src_name:
                    split_src_name = src_name.split('_scalar_type')
                    assert len(split_src_name) == 2
                    src_name = split_src_name[0]
                expr = expr.replace(src_name, name_in_expr)
        if type == BaseCType(tensorT) or type == OptionalCType(BaseCType(tensorT)) or type == MutRefCType(OptionalCType(BaseCType(tensorT))) or (is_output and type == BaseCType(scalarT)):
            var = name
            name += '_'
            if var == 'self' and inplace:
                original_self_var = 'original_self' if not is_inplace_foreach else 'original_selfs[i]'
                self_var = var if not is_inplace_foreach else var + '[i]'
                stmts_prepend = f'if (!{original_self_var}.has_value()) {original_self_var} = {self_var}.clone()'
                var = f'{original_self_var}.value()'
                assert not is_output
            if inplace and is_output:
                assert name == 'result_'
                var = 'self[i]' if is_inplace_foreach or is_foreacharg_list_type else 'self'
                is_inplace_view = f'{var}.is_view()'
                expr = f'SavedVariable({var}, {str(is_output).lower()}, {is_inplace_view})'
            else:
                expr = f'SavedVariable({var}, {str(is_output).lower()})'
                if foreacharg is not None and 'original_selfs' not in expr:
                    expr = expr.replace(src_name, name_in_expr)
        elif type == BaseCType(tensorListT) or type == ListCType(OptionalCType(BaseCType(tensorT))) or type == BaseCType(iTensorListRefT) or (type == VectorCType(BaseCType(tensorT))):
            if type == VectorCType(BaseCType(tensorT)):
                assert is_foreach and is_output
            expr = f'make_saved_variable_list({name}, {str(is_foreach and is_output).lower()})'
            name += '_'
        elif type == BaseCType(intArrayRefT):
            expr = expr + '.vec()'
        elif type == BaseCType(symIntArrayRefT):
            expr = expr + '.vec()'
        elif type == BaseCType(stringT):
            expr = f'std::string({expr})'
        elif type == OptionalCType(BaseCType(stringT)):
            expr = f'{expr}.has_value() ? ::std::optional<std::string>(std::string({expr}.value())) : ::std::nullopt'
        elif type == ArrayRefCType(elem=BaseCType(type=BaseCppType(ns='at', name='Scalar'))):
            expr = expr + '.vec()'
        guard = guard_for(arg)
        if <MASK>:
            if stmts_prepend:
                stmts.append(f'{stmts_prepend};')
            stmts.append(f'grad_fn->{name} = {expr};')
        else:
            stmts.append(f'if ({guard}) {{')
            if stmts_prepend:
                stmts.append(f'  {stmts_prepend};')
            stmts.append(f'  grad_fn->{name} = {expr};')
            stmts.append('}')
    return stmts

def get_flex_attn_fwd_configs(self, head_dim: int, dtype: Any) -> list[FlexConfig]:
    flex_attn_fwd_configs: list[FlexConfig] = []
    if config.max_autotune:
        if <MASK>:
            return self.exhaustive_flex_attn_fwd_configs
        flex_attn_fwd_configs += self.flex_attn_fwd_autotune_configs
    if head_dim <= 256:
        if dtype == torch.float32:
            default_config = FlexConfig(64, 64, 3, 4)
        else:
            default_config = FlexConfig(128, 64, 3, 4)
    elif dtype == torch.float32:
        default_config = FlexConfig(32, 16, 3, 4)
    else:
        default_config = FlexConfig(64, 32, 3, 4)
    if default_config not in flex_attn_fwd_configs:
        flex_attn_fwd_configs.append(default_config)
    return flex_attn_fwd_configs

def _AssertCompatible(values, dtype):
    if dtype is None:
        fn = _check_not_tensor
    else:
        try:
            fn = _TF_TO_IS_OK[dtype]
        except KeyError:
            if dtype.is_integer:
                fn = _check_int
            elif dtype.is_floating:
                fn = _check_float
            elif dtype.is_complex:
                fn = _check_complex
            elif <MASK>:
                fn = _check_quantized
            else:
                fn = _check_not_tensor
    try:
        fn(values)
    except ValueError as e:
        [mismatch] = e.args
        if dtype is None:
            raise TypeError('Expected any non-tensor type, but got a tensor instead.')
        else:
            raise TypeError(f"Expected {dtype.name}, but got {mismatch} of type '{type(mismatch).__name__}'.")

def main(output_file=DEFAULT_OUTPUT_FILE, only_model=None):
    results = []
    if <MASK>:
        experiments = all_experiments.values()
    else:
        if only_model not in all_experiments:
            print(f'Unknown model: {only_model}, all available models: {all_experiments.keys()}')
        experiments = [all_experiments[only_model]]
    for func in experiments:
        try:
            device = 'cuda' if torch.cuda.is_available() else 'cpu'
        except AssertionError:
            device = 'cpu'
        torch.compiler.cudagraph_mark_step_begin()
        lst = func(device)
        for x in lst:
            results.append(dataclasses.astuple(x))
    headers = [field.name for field in dataclasses.fields(Experiment)]
    for row in results:
        output_csv(output_file, headers, row)
        output_json(output_file, headers, row)

def as_json(self, describer_id: _DescriberId) -> dict[str, object]:

    def json(k: str, v: object) -> object:
        if <MASK>:
            return None
        if k in MetaTensorDesc._UNSERIALIZABLE:
            return repr(v)
        if isinstance(v, (torch.device, torch.dtype, torch.layout)):
            return repr(v)
        if isinstance(v, torch.SymInt):
            return repr(v)
        if isinstance(v, (tuple, list)):
            return [json(k, v1) for v1 in v]
        if isinstance(v, (MetaStorageDesc, MetaTensorDesc)):
            return v.id
        if isinstance(v, CreationMeta):
            return str(v)
        if k == 'attrs' and isinstance(v, dict):
            return {k1: v1.id for (k1, v1) in v.items()}
        return v
    r = {field.name: json(field.name, getattr(self, field.name)) for field in dataclasses.fields(self) if not (getattr(self, field.name) is field.default or (field.name == 'dynamo_dynamic_indices' and (not getattr(self, field.name))))}
    r.update({'describer_id': describer_id})
    return r

def __getitem__(self, index):
    """Returns a dimension or a slice of the shape.

    Ragged shapes can have ragged dimensions that depend upon other dimensions.
    Therefore, if you ask for a dimension that is ragged, this function returns
    a ValueError. For similar reasons, if a slice is selected that includes
    a ragged dimension without including the zero dimension, then this fails.

    Any slice that does not start at zero will return a shape
    with num_row_partitions == 0.

    Args:
      index: the index: can be an int or a slice.

    Raises:
      IndexError: if the index is not in range.
      ValueError: if the rank is unknown, or a ragged rank is requested
      incorrectly.
    """
    rank = self.rank
    if <MASK>:
        if index.step is not None and index.step != 1:
            raise IndexError('Cannot stride through a shape')
        start = index.start
        stop = index.stop
        if start is None:
            start = 0
        start = _fix_start_index(start, rank, self.num_row_partitions)
        stop = _fix_stop_index(stop, rank)
        return self._slice_shape(start, stop)
    elif isinstance(index, int):
        if index < 0:
            if rank is None:
                raise ValueError('Rank must be known to use __getitem__ with a negative index.')
            return self._dimension(rank + index)
        return self._dimension(index)
    else:
        raise TypeError('Argument is not an int or a slice')

def main(argv, output_stream=None):
    if len(argv) != 2:
        if <MASK>:
            raise Exception('Pass argv of length 2.')
        sys.stderr.write('usage: show_pickle PICKLE_FILE\n')
        sys.stderr.write('  PICKLE_FILE can be any of:\n')
        sys.stderr.write('    path to a pickle file\n')
        sys.stderr.write('    file.zip@member.pkl\n')
        sys.stderr.write('    file.zip@*/pattern.*\n')
        sys.stderr.write('      (shell glob pattern for members)\n')
        sys.stderr.write('      (only first match will be shown)\n')
        return 2
    fname = argv[1]
    handle: IO[bytes]
    if '@' not in fname:
        with open(fname, 'rb') as handle:
            DumpUnpickler.dump(handle, output_stream)
    else:
        (zfname, mname) = fname.split('@', 1)
        with zipfile.ZipFile(zfname) as zf:
            if '*' not in mname:
                with zf.open(mname) as handle:
                    DumpUnpickler.dump(handle, output_stream)
            else:
                found = False
                for info in zf.infolist():
                    if fnmatch.fnmatch(info.filename, mname):
                        with zf.open(info) as handle:
                            DumpUnpickler.dump(handle, output_stream)
                        found = True
                        break
                if not found:
                    raise Exception(f'Could not find member matching {mname} in {zfname}')

def computation(x):
    x = x + 1.0
    if <MASK>:
        scalar_summary_v2.scalar('x', x, step=0)
        x = x * 2.0
    return x + 1.0

@cache_on_self
def _get_atomic_add_buffers(self) -> OrderedSet[str]:
    buffers_store_as_atomic_add: OrderedSet[str] = OrderedSet()
    if isinstance(self._body, LoopBody):
        for node in self._body.get_nodes():
            if <MASK>:
                buffers_store_as_atomic_add.add(node.kwargs['name'] if 'name' in node.kwargs else node.args[1] if len(node.args) >= 2 else '')
    return buffers_store_as_atomic_add

def _script_impl(obj, optimize=None, _frames_up=0, _rcb=None, example_inputs: Union[list[tuple], dict[Callable, list[tuple]], None]=None):
    global type_trace_db
    if optimize is not None:
        warnings.warn('`optimize` is deprecated and has no effect. Use `with torch.jit.optimized_execution()` instead', FutureWarning, stacklevel=3)
    if isinstance(obj, RecursiveScriptClass):
        return obj
    if isinstance(obj, ScriptModule):
        return obj
    if isinstance(obj, ScriptFunction):
        return obj
    if example_inputs:
        type_trace_db = JitTypeTraceStore()
        if monkeytype_trace:
            monkeytype_config = JitTypeTraceConfig(type_trace_db)
            with monkeytype_trace(monkeytype_config):
                if isinstance(example_inputs, dict):
                    for (module, example_input) in example_inputs.items():
                        for example in example_input:
                            module(*example)
                elif isinstance(example_inputs, list):
                    for examples in example_inputs:
                        obj(*examples)
                else:
                    raise ValueError('Error: Unable to infer types. Please format the inputs to type `List[Tuple]` or `Dict[Callable, List[Tuple]]` to be run with MonkeyType.')
        else:
            warnings.warn('Warning: monkeytype is not installed. Please install https://github.com/Instagram/MonkeyType to enable Profile-Directed Typing in TorchScript. Refer to https://github.com/Instagram/MonkeyType/blob/master/README.rst to install MonkeyType. ')
    if isinstance(obj, torch.nn.Module):
        obj = call_prepare_scriptable_func(obj)
        return torch.jit._recursive.create_script_module(obj, torch.jit._recursive.infer_methods_to_compile)
    else:
        obj = obj.__prepare_scriptable__() if hasattr(obj, '__prepare_scriptable__') else obj
    if isinstance(obj, dict):
        return create_script_dict(obj)
    if isinstance(obj, list):
        return create_script_list(obj)
    if inspect.isclass(obj):
        qualified_name = _qualified_name(obj)
        if issubclass(obj, torch.nn.Module):
            raise RuntimeError(f"Type '{obj}' cannot be compiled since it inherits from nn.Module, pass an instance instead")
        if issubclass(obj, enum.Enum):
            return obj
        if not _is_new_style_class(obj):
            raise RuntimeError("TorchScript classes must be new-style classes. Please inherit from 'object'.")
        if <MASK>:
            raise RuntimeError("TorchScript classes does not support inheritance yet. Please directly inherit from 'object'.")
        if _rcb is None:
            _rcb = _jit_internal.createResolutionCallbackFromFrame(_frames_up + 1)
        _compile_and_register_class(obj, _rcb, qualified_name)
        return obj
    elif inspect.isfunction(obj) or inspect.ismethod(obj):
        qualified_name = _qualified_name(obj)
        if hasattr(obj, '__script_if_tracing_wrapper'):
            obj = obj.__original_fn
            _rcb = _jit_internal.createResolutionCallbackFromClosure(obj)
        if hasattr(obj, '__script_unsupported'):
            raise RuntimeError('TorchScript error: ' + obj.__script_unsupported)
        _check_directly_compile_overloaded(obj)
        maybe_already_compiled_fn = _try_get_jit_cached_function(obj)
        if maybe_already_compiled_fn:
            maybe_already_compiled_fn._torchdynamo_inline = obj
            return maybe_already_compiled_fn
        ast = get_jit_def(obj, obj.__name__)
        if _rcb is None:
            _rcb = _jit_internal.createResolutionCallbackFromClosure(obj)
        fn = torch._C._jit_script_compile(qualified_name, ast, _rcb, get_default_args(obj))
        fn.__doc__ = obj.__doc__
        fn.__name__ = 'ScriptFunction'
        fn.__qualname__ = 'torch.jit.ScriptFunction'
        fn._torchdynamo_inline = obj
        _set_jit_function_cache(obj, fn)
        return fn
    else:
        return torch.jit._recursive.create_script_class(obj)

@final
@classmethod
def _validate_frequency(cls, index, freq: BaseOffset, **kwargs) -> None:
    """
        Validate that a frequency is compatible with the values of a given
        Datetime Array/Index or Timedelta Array/Index

        Parameters
        ----------
        index : DatetimeIndex or TimedeltaIndex
            The index on which to determine if the given frequency is valid
        freq : DateOffset
            The frequency to validate
        """
    inferred = index.inferred_freq
    if index.size == 0 or inferred == freq.freqstr:
        return None
    try:
        on_freq = cls._generate_range(start=index[0], end=None, periods=len(index), freq=freq, unit=index.unit, **kwargs)
        if <MASK>:
            raise ValueError
    except ValueError as err:
        if 'non-fixed' in str(err):
            raise err
        raise ValueError(f'Inferred frequency {inferred} from passed values does not conform to passed frequency {freq.freqstr}') from err

def pack_to_cpu(tensor: torch.Tensor) -> tuple[torch.device, torch.Tensor]:
    if <MASK>:
        return (tensor.device, tensor.cpu())
    packed = torch.empty(tensor.size(), dtype=tensor.dtype, layout=tensor.layout, pin_memory=device_module.is_available() and (not tensor.is_sparse))
    packed.copy_(tensor)
    return (tensor.device, packed)

def __iter__(self):
    queryset = self.queryset
    if <MASK>:
        names = queryset._fields
    else:
        query = queryset.query
        names = [*query.extra_select, *query.values_select, *query.annotation_select]
    tuple_class = create_namedtuple_class(*names)
    new = tuple.__new__
    for row in super().__iter__():
        yield new(tuple_class, row)

def _free_unbacked_symbols_with_path(a: object, path: pytree.KeyPath, real: Optional[object]=None, shape_env: Optional[ShapeEnv]=None, pending: Optional[set[sympy.Symbol]]=None, simplify: bool=False) -> dict[sympy.Symbol, pytree.KeyPath]:
    """
    Recursively traverses a structure to find unbacked symbols and their access paths.

    This function walks through tensors, lists, tuples, and symbolic values to locate
    unbacked symbols that are in the pending set, and returns a mapping from those
    symbols to their access paths in the structure.

    Args:
        a: The object to traverse (tensor, list, tuple, SymInt, etc.)
        path: The current path in the object tree
        real: Optional real tensor corresponding to the fake tensor being traversed
        shape_env: Optional ShapeEnv to register unbacked values with
        pending: Set of unbacked symbols to look for (will be modified in-place)
        simplify: Whether to use simplified expressions

    Returns:
        A dictionary mapping unbacked symbols to their access paths
    """
    go = functools.partial(_free_unbacked_symbols_with_path, shape_env=shape_env, pending=pending, simplify=simplify)

    def expr(s: Union[SymInt, SymFloat, SymBool]) -> sympy.Expr:
        if simplify:
            return s.node.expr
        return s.node._expr
    if pending is None:
        pending = set()
    r = {}
    if isinstance(a, (tuple, list)):
        for i in range(len(a)):
            r.update(go(a[i], path + (pytree.SequenceKey(i),), real=real[i] if real is not None else None))
    elif is_traceable_wrapper_subclass(a):
        (attrs, _) = a.__tensor_flatten__()
        for attr in attrs:
            sub = getattr(a, attr)
            r.update(go(sub, path + (InnerTensorKey(attr),)))
    elif isinstance(a, torch.Tensor) and is_batchedtensor(a):
        unwrapped_tensor = get_unwrapped(a)
        r.update(go(unwrapped_tensor, path))
    elif isinstance(a, torch.Tensor) and (not is_batchedtensor(a)):
        from torch._subclasses.fake_tensor import FakeTensor
        assert isinstance(a, FakeTensor)
        r.update(go(a.size(), path + (CallMethodKey('size'),), real=a.real_tensor.size() if a.real_tensor is not None else None))
        if a.layout not in [torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc]:
            r.update(go(a.stride(), path + (CallMethodKey('stride'),), real=a.real_tensor.stride() if a.real_tensor is not None else None))
        r.update(go(a.storage_offset(), path + (CallMethodKey('storage_offset'),), real=a.real_tensor.storage_offset() if a.real_tensor is not None else None))
    elif isinstance(a, (torch.SymInt, torch.SymFloat)) and isinstance((s := expr(a)), sympy.Symbol) and (s in pending):
        r[s] = path
        if <MASK>:
            assert isinstance(real, (int, float))
            shape_env.set_unbacked_var_to_val(s, real)
        pending.remove(s)
    elif isinstance(a, torch.SymInt) and isinstance((s := expr(a)), sympy.Mul) and (len(s.args) == 2) and isinstance((lhs := s.args[0]), (sympy.Integer, sympy.Symbol)) and isinstance((rhs := s.args[1]), sympy.Symbol) and ((rhs in pending) ^ (lhs in pending)) and (isinstance((coeff := (lhs if lhs not in pending else rhs)), sympy.Integer) or (shape_env and coeff in shape_env.var_to_val)):

        def _symint_wrap(s: sympy.Symbol) -> SymInt:
            return shape_env.create_symintnode(s, hint=int(shape_env.var_to_val[s]), source=shape_env.var_to_sources.get(s, [None])[0])
        unbacked = lhs if lhs in pending else rhs
        divisor: IntLikeType = int(coeff) if shape_env and isinstance(coeff, sympy.Integer) else _symint_wrap(coeff)
        r[unbacked] = path + (DivideByKey(divisor),)
        if real is not None:
            assert isinstance(real, int)
            val = real // int(coeff) if isinstance(coeff, sympy.Integer) else CleanDiv(real, coeff)
            if shape_env:
                shape_env.set_unbacked_var_to_val(unbacked, val)
        pending.remove(unbacked)
    elif isinstance(a, torch.SymBool) and isinstance((s := expr(a)), sympy.Eq) and isinstance(s.lhs, sympy.Symbol) and (s.rhs == 1) and (s.lhs in pending):
        r[s.lhs] = path + (ConvertIntKey(),)
        if real is not None:
            assert type(real) is bool
            if shape_env:
                shape_env.set_unbacked_var_to_val(s, int(real))
        pending.remove(s.lhs)
    return r

def _pre_forward(self, *inputs, **kwargs):
    if self._use_python_reducer:
        return (inputs, kwargs)
    if not self._lazy_init_ran and (not torch.compiler.is_compiling()):
        self._lazy_init()
    if self._delay_all_reduce_all_params:
        return (inputs, kwargs)
    if torch.is_grad_enabled() and self.require_backward_grad_sync:
        assert self.logger is not None
        self.logger.set_runtime_stats_and_log()
        self.reducer.prepare_for_forward()
    work = Join.notify_join_context(self)
    if work:
        self.reducer._set_forward_pass_work_handle(work, self._divide_by_initial_world_size)
    if torch.is_grad_enabled() and self.reducer._rebuild_buckets():
        logger.info('Reducer buckets have been rebuilt in this iteration.')
        self._has_rebuilt_buckets = True
    if <MASK>:
        self._sync_buffers()
    if self._join_config.enable:
        self._check_global_requires_backward_grad_sync(is_joined_rank=False)
    if self.device_ids:
        (moved_inputs, moved_kwargs) = _to_kwargs(inputs, kwargs, torch.device(self.device_type, self.device_ids[0]), self.use_side_stream_for_tensor_copies)
        (args, kwargs) = (moved_inputs[0], moved_kwargs[0])
        if self.mixed_precision is not None:
            (args, kwargs) = _cast_forward_inputs(self.mixed_precision.param_dtype, *args, **kwargs)
        return (args, kwargs)
    else:
        if self.mixed_precision is not None:
            (inputs, kwargs) = _cast_forward_inputs(self.mixed_precision.param_dtype, *inputs, **kwargs)
        return (inputs, kwargs)

def preview_type_promotion(self, args: tuple, kwargs: dict) -> TypePromotionSnapshot:
    assert len(args) >= 1, f'Reduction op torch.ops.{self.namespace}.{self.op_name} expects at least one argument'
    arg = args[0]
    assert isinstance(arg, torch.Tensor), f'type(arg)={type(arg)!r} is not torch.Tensor'
    dtype: torch.dtype | None = kwargs.get('dtype')
    if <MASK>:
        if _prims_common.is_boolean_dtype(arg.dtype) or _prims_common.is_integer_dtype(arg.dtype):
            dtype = torch.int64
        else:
            dtype = arg.dtype
    return super().preview_type_promotion(args, {'dtype': dtype})

def _fsdp_state_pre_forward(self, fsdp_mod: FSDPModule, orig_fsdp_state_pre_fw: Callable[_P, tuple[tuple[Unpack[_Ts]], dict[str, Any]]]) -> Callable[_P, tuple[tuple[Unpack[_Ts]], dict[str, Any]]]:

    @wraps(orig_fsdp_state_pre_fw)
    def inner(*args: _P.args, **kwargs: _P.kwargs) -> tuple[tuple[Unpack[_Ts]], dict[str, Any]]:
        self._fsdp_state = _FSDPState.PRE_FW
        mod_fqn = self._mod_tracker.get_known_fqn(fsdp_mod)
        assert mod_fqn is not None
        if <MASK>:
            mod_stat = _FSDPModMemStats(mod_fqn)
            self.memory_tracking[fsdp_mod] = mod_stat
            snapshot = self.get_tracker_snapshot()
            mod_stat.local_peak = {dev: dev_snap[_TOTAL_KEY] for (dev, dev_snap) in snapshot.items()}
            mod_stat.snapshots.setdefault(_FSDPModState.PEAK_FW, []).append(snapshot)
            mod_stat.snapshots.setdefault(_FSDPModState.BEF_PRE_FW, []).append(deepcopy(snapshot))
        elif not self._mod_tracker.is_bw:
            parents = self._mod_tracker.parents - {mod_fqn}
            if len(parents) == 1 and 'Global' in parents:
                raise NotImplementedError('FSDPMemTracker does not support memory tracking for multiple iterative calls. Either use ``reset_mod_stats`` to clear module memory stats for the previous iteration or file a github issue if you need this feature.')
        (args, kwargs) = orig_fsdp_state_pre_fw(*args, **kwargs)
        fsdp_state = fsdp_mod._get_fsdp_state()
        if (fsdp_param_group := fsdp_state._fsdp_param_group):
            for fsdp_param in fsdp_param_group.fsdp_params:
                self._update_and_maybe_create_winfos(fsdp_param.unsharded_param, _FSDPRefType.UNSHARDED_PARAM)
        mod_stat = self.memory_tracking[fsdp_mod]
        if self._mod_tracker.is_bw:
            state = _FSDPModState.PRE_FW_AC
            if self._ac_mod is None:
                self._ac_mod = weakref.ref(fsdp_mod)
                self._in_ac = True
        else:
            state = _FSDPModState.AFT_PRE_FW
        mod_stat.snapshots.setdefault(state, []).append(self.get_tracker_snapshot())
        self._fsdp_state = _FSDPState.FW
        return (args, kwargs)
    return inner

def default_partition(joint_module: fx.GraphModule, _joint_inputs, *, num_fwd_outputs, static_lifetime_input_indices: Optional[list[int]]=None, static_lifetime_input_nodes: Optional[OrderedSet[fx.Node]]=None) -> tuple[fx.GraphModule, fx.GraphModule]:
    """
    Partitions the :attr:`joint_module` in a manner that closely resembles the
    behavior observed in the original ``.forward()`` and ``.backward()`` of the
    callable, i.e., the resulting forward graph contains those operators that
    are executed in the original ``.forward()`` callable passed to
    :func:`aot_function`.

    The default partitioner collects the operators that are between the forward
    inputs and the forward outputs. This helps in finding the tensors which have
    to be stashed for the backward pass. These stashed tensors become the output
    of the generated forward graph. The remaining operators are then placed in
    the backward graph.

    .. warning::
        This API is experimental and likely to change.

    Args:
        joint_module(fx.GraphModule): The joint forward and backward graph. This
            is the result of AOT Autograd tracing.

    Returns:
        Returns the generated forward and backward Fx graph modules.
    """
    if has_recomputable_ops(joint_module):
        return min_cut_rematerialization_partition(joint_module, _joint_inputs, num_fwd_outputs=num_fwd_outputs, static_lifetime_input_indices=static_lifetime_input_indices)
    primal_inputs = list(filter(_is_primal, joint_module.graph.nodes))
    fwd_seed_offset_inputs = list(filter(_is_fwd_seed_offset, joint_module.graph.nodes))
    inputs = primal_inputs + fwd_seed_offset_inputs
    (fwd_outputs, bwd_outputs, fwd_outputs_descs, bwd_outputs_descs) = _extract_fwd_bwd_outputs(joint_module, num_fwd_outputs=num_fwd_outputs)
    forward_only_graph = _extract_graph_with_inputs_outputs(joint_module.graph, inputs, fwd_outputs, fwd_outputs_descs, 'forward')
    forward_node_names = OrderedSet((node.name for node in forward_only_graph.nodes if node.op != 'output'))
    order = {node: idx for (idx, node) in enumerate(joint_module.graph.nodes)}
    saved_values = []
    saved_sym_nodes = []

    def is_mutated_later_in_fw(node):
        if _has_tag_is_backward(node):
            return False
        tensor_arg_aliases = [x for x in node.args if isinstance(x, fx.Node) and 'val' in x.meta and isinstance(x.meta['val'], torch.Tensor)]
        while len(tensor_arg_aliases) > 0:
            a = tensor_arg_aliases.pop()
            for u in a.users:
                if not isinstance(u.target, torch._ops.OpOverload):
                    continue
                if u.target._schema.is_mutable and order[u] > order[node] and (not (_has_tag_is_backward(u) or _has_tag_must_be_in_backward(u))):
                    for (idx, alias_info) in enumerate(u.target._schema.arguments):
                        if <MASK>:
                            return True
                elif u.target.is_view:
                    tensor_arg_aliases.append(u)
        return False
    for node in joint_module.graph.nodes:
        if node.name not in forward_node_names:
            if is_mutated_later_in_fw(node):
                saved_values.append(node)
            continue
        if is_sym_node(node):
            saved_sym_nodes.append(node)
        elif 'tensor_meta' not in node.meta and node.op == 'call_function' and (not isinstance(node.meta.get('val'), torch._subclasses.FakeTensor)):
            users = node.users
            assert all((user.target == operator.getitem for user in users))
            saved_values.extend(users)
        else:
            backward_usages = [n for n in node.users if n.name not in forward_node_names]
            if 'tensor_meta' in node.meta and all((is_sym_node(n) for n in backward_usages)):
                saved_sym_nodes.extend(backward_usages)
            else:
                saved_values.append(node)
    saved_values = list(dict.fromkeys(saved_values).keys())
    saved_sym_nodes = list(dict.fromkeys(saved_sym_nodes).keys())
    return _extract_fwd_bwd_modules(joint_module, saved_values, saved_sym_nodes=saved_sym_nodes, num_fwd_outputs=num_fwd_outputs, static_lifetime_input_nodes=static_lifetime_input_nodes)

