def _global_clustering(self, X=None):
    """
        Global clustering for the subclusters obtained after fitting
        """
    clusterer = self.n_clusters
    centroids = self.subcluster_centers_
    compute_labels = X is not None and self.compute_labels
    not_enough_centroids = False
    if isinstance(clusterer, Integral):
        clusterer = AgglomerativeClustering(n_clusters=self.n_clusters)
        if len(centroids) < self.n_clusters:
            not_enough_centroids = True
    self._subcluster_norms = row_norms(self.subcluster_centers_, squared=True)
    if <MASK>:
        self.subcluster_labels_ = np.arange(len(centroids))
        if not_enough_centroids:
            warnings.warn('Number of subclusters found (%d) by BIRCH is less than (%d). Decrease the threshold.' % (len(centroids), self.n_clusters), ConvergenceWarning)
    else:
        self.subcluster_labels_ = clusterer.fit_predict(self.subcluster_centers_)
    if compute_labels:
        self.labels_ = self._predict(X)

def _stop_run(self) -> None:
    command = ['strobeclient', 'stopRun', '--run-id', str(self.current_run_id)]
    logger.debug('running command: %s', _command_to_string(command))
    result = subprocess.run(command, capture_output=True)
    output = result.stderr.decode('utf-8')
    logger.debug('output:\n{%s}', output)
    if <MASK>:
        raise StrobelightCLIProfilerError(f'failed to stop strobelight profiling, return code is not 0 :{output}')
    if (match := re.search('INFO ::1:(.*)', output)):
        current_status = match.group(1)
        if current_status.__contains__('Success!'):
            return
        else:
            raise StrobelightCLIProfilerError(f'failed to stop strobelight profiling, got {current_status} result')
    raise StrobelightCLIProfilerError(f'unexpected output\n: {output} ')

