@classmethod
def settings_to_cmd_args_env(cls, settings_dict, parameters):
    args = [cls.executable_name]
    env = None
    database = settings_dict['OPTIONS'].get('database', settings_dict['OPTIONS'].get('db', settings_dict['NAME']))
    user = settings_dict['OPTIONS'].get('user', settings_dict['USER'])
    password = settings_dict['OPTIONS'].get('password', settings_dict['OPTIONS'].get('passwd', settings_dict['PASSWORD']))
    host = settings_dict['OPTIONS'].get('host', settings_dict['HOST'])
    port = settings_dict['OPTIONS'].get('port', settings_dict['PORT'])
    server_ca = settings_dict['OPTIONS'].get('ssl', {}).get('ca')
    client_cert = settings_dict['OPTIONS'].get('ssl', {}).get('cert')
    client_key = settings_dict['OPTIONS'].get('ssl', {}).get('key')
    defaults_file = settings_dict['OPTIONS'].get('read_default_file')
    charset = settings_dict['OPTIONS'].get('charset')
    if defaults_file:
        args += ['--defaults-file=%s' % defaults_file]
    if user:
        args += ['--user=%s' % user]
    if <MASK>:
        env = {'MYSQL_PWD': password}
    if host:
        if '/' in host:
            args += ['--socket=%s' % host]
        else:
            args += ['--host=%s' % host]
    if port:
        args += ['--port=%s' % port]
    if server_ca:
        args += ['--ssl-ca=%s' % server_ca]
    if client_cert:
        args += ['--ssl-cert=%s' % client_cert]
    if client_key:
        args += ['--ssl-key=%s' % client_key]
    if charset:
        args += ['--default-character-set=%s' % charset]
    if database:
        args += [database]
    args.extend(parameters)
    return (args, env)

@compatibility(is_backward_compatible=False)
def getattr(self, attr: str, attr_val: Any, parameter_proxy_cache: dict[str, Any]):
    """
        Method that specifies the behavior of this ``Tracer`` when we call getattr
        on a call to an ``nn.Module`` instance.

        By default, the behavior is to return a proxy value for the attribute. It
        also stores the proxy value in the ``parameter_proxy_cache``, so that future
        calls will reuse the proxy rather than creating a new one.

        This method can be overridden to --for example-- not return proxies when
        querying parameters.

        Args:

            attr (str): The name of the attribute being queried
            attr_val (Any): The value of the attribute
            parameter_proxy_cache (Dict[str, Any]): A cache of attr names to proxies

        Return:

            The return value from the getattr call.
        """

    def maybe_get_proxy_for_attr(attr_val, collection_to_search, parameter_proxy_cache):
        for (n, p) in collection_to_search:
            if attr_val is p:
                if n not in parameter_proxy_cache:
                    kwargs = {}
                    if 'proxy_factory_fn' in inspect.signature(self.create_proxy).parameters:
                        kwargs['proxy_factory_fn'] = None if not self.param_shapes_constant else lambda node: ParameterProxy(self, node, n, attr_val)
                    val_proxy = self.create_proxy('get_attr', n, (), {}, **kwargs)
                    parameter_proxy_cache[n] = val_proxy
                return parameter_proxy_cache[n]
        return None
    if <MASK>:
        maybe_parameter_proxy = maybe_get_proxy_for_attr(attr_val, self.root.named_parameters(), parameter_proxy_cache)
        if maybe_parameter_proxy is not None:
            return maybe_parameter_proxy
    if self.proxy_buffer_attributes and isinstance(attr_val, torch.Tensor):
        maybe_buffer_proxy = maybe_get_proxy_for_attr(attr_val, self.root.named_buffers(), parameter_proxy_cache)
        if maybe_buffer_proxy is not None:
            return maybe_buffer_proxy
    return attr_val

def argsort(a, axis=np._NoValue, kind=None, order=None, endwith=True, fill_value=None, *, stable=None):
    """Function version of the eponymous method."""
    a = np.asanyarray(a)
    if axis is np._NoValue:
        axis = _deprecate_argsort_axis(a)
    if <MASK>:
        return a.argsort(axis=axis, kind=kind, order=order, endwith=endwith, fill_value=fill_value, stable=None)
    else:
        return a.argsort(axis=axis, kind=kind, order=order, stable=None)

def handle(self, *args, **options):
    locale = options['locale']
    exclude = options['exclude']
    self.domain = options['domain']
    self.verbosity = options['verbosity']
    process_all = options['all']
    extensions = options['extensions']
    self.symlinks = options['symlinks']
    ignore_patterns = options['ignore_patterns']
    if options['use_default_ignore_patterns']:
        ignore_patterns += ['CVS', '.*', '*~', '*.pyc']
    self.ignore_patterns = list(set(ignore_patterns))
    if options['no_wrap']:
        self.msgmerge_options = self.msgmerge_options[:] + ['--no-wrap']
        self.msguniq_options = self.msguniq_options[:] + ['--no-wrap']
        self.msgattrib_options = self.msgattrib_options[:] + ['--no-wrap']
        self.xgettext_options = self.xgettext_options[:] + ['--no-wrap']
    if options['no_location']:
        self.msgmerge_options = self.msgmerge_options[:] + ['--no-location']
        self.msguniq_options = self.msguniq_options[:] + ['--no-location']
        self.msgattrib_options = self.msgattrib_options[:] + ['--no-location']
        self.xgettext_options = self.xgettext_options[:] + ['--no-location']
    if options['add_location']:
        arg_add_location = '--add-location=%s' % options['add_location']
        self.msgmerge_options = self.msgmerge_options[:] + [arg_add_location]
        self.msguniq_options = self.msguniq_options[:] + [arg_add_location]
        self.msgattrib_options = self.msgattrib_options[:] + [arg_add_location]
        self.xgettext_options = self.xgettext_options[:] + [arg_add_location]
    self.no_obsolete = options['no_obsolete']
    self.keep_pot = options['keep_pot']
    if self.domain not in ('django', 'djangojs'):
        raise CommandError("currently makemessages only supports domains 'django' and 'djangojs'")
    if self.domain == 'djangojs':
        exts = extensions or ['js']
    else:
        exts = extensions or ['html', 'txt', 'py']
    self.extensions = handle_extensions(exts)
    if not locale and (not exclude) and (not process_all) or self.domain is None:
        raise CommandError("Type '%s help %s' for usage information." % (os.path.basename(sys.argv[0]), sys.argv[1]))
    if self.verbosity > 1:
        self.stdout.write('examining files with the extensions: %s' % get_text_list(list(self.extensions), 'and'))
    self.invoked_for_django = False
    self.locale_paths = []
    self.default_locale_path = None
    if os.path.isdir(os.path.join('conf', 'locale')):
        self.locale_paths = [os.path.abspath(os.path.join('conf', 'locale'))]
        self.default_locale_path = self.locale_paths[0]
        self.ignore_patterns.append('views/templates/i18n_catalog.js')
        self.invoked_for_django = True
    else:
        if self.settings_available:
            for path in settings.LOCALE_PATHS:
                locale_path = os.path.abspath(path)
                if <MASK>:
                    self.locale_paths.append(locale_path)
        if os.path.isdir('locale'):
            locale_path = os.path.abspath('locale')
            if locale_path not in self.locale_paths:
                self.locale_paths.append(locale_path)
        if self.locale_paths:
            self.default_locale_path = self.locale_paths[0]
            os.makedirs(self.default_locale_path, exist_ok=True)
    looks_like_locale = re.compile('[a-z]{2}')
    locale_dirs = filter(os.path.isdir, glob.glob('%s/*' % self.default_locale_path))
    all_locales = [lang_code for lang_code in map(os.path.basename, locale_dirs) if looks_like_locale.match(lang_code)]
    if process_all:
        locales = all_locales
    else:
        locales = locale or all_locales
        locales = set(locales).difference(exclude)
    if locales:
        check_programs('msguniq', 'msgmerge', 'msgattrib')
    check_programs('xgettext')
    try:
        potfiles = self.build_potfiles()
        for locale in locales:
            if not is_valid_locale(locale):
                match = re.match('^(?P<language>[a-zA-Z]+)(?P<separator>[^a-zA-Z])(?P<territory>.+)$', locale)
                if match:
                    locale_parts = match.groupdict()
                    language = locale_parts['language'].lower()
                    territory = locale_parts['territory'][:2].upper() + locale_parts['territory'][2:]
                    proposed_locale = f'{language}_{territory}'
                else:
                    proposed_locale = locale.lower()
                if is_valid_locale(proposed_locale):
                    self.stdout.write('invalid locale %s, did you mean %s?' % (locale, proposed_locale))
                else:
                    self.stdout.write('invalid locale %s' % locale)
                continue
            if self.verbosity > 0:
                self.stdout.write('processing locale %s' % locale)
            for potfile in potfiles:
                self.write_po_file(potfile, locale)
    finally:
        if not self.keep_pot:
            self.remove_potfiles()

def _activation_post_process_satisfies_dtype_config_constraints(activation_post_process: Union[ObserverBase, FakeQuantizeBase], dtype_with_constraints: DTypeWithConstraints, debug_string: str) -> bool:
    observer = _get_observer_from_activation_post_process(activation_post_process)
    app_quant_min = getattr(observer, 'quant_min', None)
    app_quant_max = getattr(observer, 'quant_max', None)
    app_scale_min = getattr(observer, 'eps', None)
    backend_quant_min = dtype_with_constraints.quant_min_lower_bound
    backend_quant_max = dtype_with_constraints.quant_max_upper_bound
    backend_scale_min = dtype_with_constraints.scale_min_lower_bound
    backend_scale_exact_match = dtype_with_constraints.scale_exact_match
    backend_zero_point_exact_match = dtype_with_constraints.zero_point_exact_match
    if backend_quant_min is not None and backend_quant_max is not None:
        if app_quant_min is None or app_quant_max is None:
            warnings.warn(f"QConfig {debug_string} must specify 'quant_min' and 'quant_max', ignoring {qconfig}")
            return False
        elif app_quant_min < backend_quant_min or app_quant_max > backend_quant_max:
            warnings.warn(f"QConfig {debug_string} quantization range must fall within the backend's:\nQConfig range = ({app_quant_min}, {app_quant_max}), BackendConfig range = ({backend_quant_min}, {backend_quant_max}), ignoring {qconfig}")
            return False
    if backend_scale_min is not None:
        if app_scale_min is None:
            warnings.warn(f"QConfig {debug_string} must specify 'eps', ignoring {qconfig}")
            return False
        if <MASK>:
            warnings.warn(f"QConfig {debug_string} eps ({app_scale_min}) must be greater than or equal to the backend's min scale value ({backend_scale_min}), ignoring {qconfig}")
            return False
    if backend_scale_exact_match is not None and backend_zero_point_exact_match is not None:
        for accepted_qconfig in [float16_static_qconfig, float16_dynamic_qconfig]:
            if qconfig_equals(qconfig, accepted_qconfig):
                return True
        suggestion_str = 'Please use torch.ao.quantization.get_default_qconfig_mapping or torch.ao.quantization.get_default_qat_qconfig_mapping. Example:\n    qconfig_mapping = get_default_qconfig_mapping("fbgemm")\n    model = prepare_fx(model, qconfig_mapping, example_inputs)'
        if not isinstance(activation_post_process, FixedQParamsObserver) and (not isinstance(activation_post_process, FixedQParamsFakeQuantize)):
            warnings.warn(f'QConfig must specify a FixedQParamsObserver or a FixedQParamsFakeQuantize for fixed qparams ops, ignoring {qconfig}.\n{suggestion_str}')
            return False
        if observer.scale != backend_scale_exact_match or observer.zero_point != backend_zero_point_exact_match:
            warnings.warn(f"QConfig fixed scale ({observer.scale}) and zero point ({observer.zero_point}) do not match the backend's ({backend_scale_exact_match} and {backend_zero_point_exact_match}), ignoring {qconfig}.\n{suggestion_str}")
            return False
    return True

def _wrap_backward_function(self, forward_graph: func_graph_module.FuncGraph, backward, outputs):
    """Create a backward function given `outputs` from the forward function."""
    capture_mapping = dict(zip((ops.tensor_id(t) for t in forward_graph.outputs), outputs))
    captured_inputs = backward.captured_inputs
    remapped_captures = [capture_mapping.get(ops.tensor_id(capture), capture) for capture in captured_inputs]
    if any((t.graph is forward_graph for t in remapped_captures if not isinstance(t, ops.EagerTensor))):
        incorrect_mapping = [t for t in remapped_captures if not isinstance(t, ops.EagerTensor) and t.graph is not forward_graph]
        raise errors.InternalError(f'Failed to map all backward graph captures to the forward graph. Incorrectly mapped: {incorrect_mapping}.')
    variant_zeros_like = {}
    backward_function_inputs = len(backward.inputs) - len(captured_inputs)
    recorded_outputs = []
    trainable_recorded_outputs = 0
    skip_positions = []
    if <MASK>:
        relevant_outputs = outputs[:self._num_inference_outputs] + outputs[self._num_inference_outputs + self._num_forwardprop_outputs:]
    else:
        relevant_outputs = outputs
    for (output_index, output) in enumerate(relevant_outputs):
        if trainable_recorded_outputs < backward_function_inputs:
            recorded_outputs.append(output)
        if backprop_util.IsTrainable(output):
            trainable_recorded_outputs += 1
        else:
            skip_positions.append(output_index)
        if output.dtype == dtypes.variant:
            variant_zeros_like[output_index] = default_gradient.zeros_like(output)

    def _backward_function_wrapper(*args):
        """Process output gradients and call the backward function."""
        if not backward.outputs:
            return backward.structured_outputs
        processed_args = []
        input_index = 0
        for (output_index, arg) in enumerate(args):
            if isinstance(arg, indexed_slices.IndexedSlices):
                arg = ops.convert_to_tensor(arg)
            if output_index in skip_positions:
                continue
            if arg is None:
                input_placeholder = backward.inputs[input_index]
                if input_placeholder.dtype == dtypes.variant:
                    arg = variant_zeros_like[output_index]
                else:
                    arg = array_ops.zeros(*default_gradient.shape_and_dtype(input_placeholder))
            processed_args.append(arg)
            input_index += 1
            if input_index >= backward_function_inputs:
                break
        return backward._call_flat(processed_args, remapped_captures)
    return (_backward_function_wrapper, recorded_outputs)

def _handle_insert_op_in_graph(self, tx: 'InstructionTranslator', args, kwargs):
    from .builder import wrap_fx_proxy, wrap_fx_proxy_cls
    if kwargs and (not self.tensor_args(*args, *kwargs.values())):
        return
    from .builder import SourcelessBuilder
    from .torch_function import can_dispatch_torch_function, dispatch_torch_function
    global BUILTIN_TO_TENSOR_RFN_MAP, BUILTIN_TO_TENSOR_FN_MAP
    if can_dispatch_torch_function(tx, args, kwargs):
        if not tx.export:
            populate_builtin_to_tensor_fn_map()
            if not isinstance(args[0], TensorVariable):
                if self.fn in BUILTIN_TO_TENSOR_RFN_MAP:
                    func = BUILTIN_TO_TENSOR_RFN_MAP[self.fn]
                else:
                    func = BUILTIN_TO_TENSOR_FN_MAP[self.fn]
                tmp = args[0]
                args[0] = args[1]
                args[1] = tmp
            else:
                func = BUILTIN_TO_TENSOR_FN_MAP[self.fn]
        else:
            func = self.fn
        fn_var = SourcelessBuilder.create(tx, func)
        return dispatch_torch_function(tx, fn_var, args, kwargs)
    fn = self.fn
    try:
        if self.python_and_tensor_constant_only(*args, **kwargs):
            from ..bytecode_transformation import unique_id
            from .functions import invoke_and_store_as_constant
            return invoke_and_store_as_constant(tx, fn, unique_id(fn.__name__), args, kwargs)
        if fn in IN_PLACE_DESUGARING_MAP and isinstance(args[0], variables.ConstantVariable):
            (fn, args) = (IN_PLACE_DESUGARING_MAP[fn], [args[0], args[1]])
        if fn is operator.getitem and isinstance(args[1], SymNodeVariable):
            (fn, args) = (torch.select, [args[0], variables.ConstantVariable.create(0), args[1]])
        if check_numpy_ndarray_args(args, kwargs) and (not any((type(arg) is variables.TensorVariable for arg in args))):
            proxy = tx.output.create_proxy('call_function', numpy_operator_wrapper(fn), *proxy_args_kwargs(args, kwargs))
            return wrap_fx_proxy_cls(variables.NumpyNdarrayVariable, tx, proxy)
        if fn is operator.eq and len(args) == 2 and isinstance(args[0], variables.TensorVariable):
            return args[0].call_method(tx, '__eq__', args[1:], kwargs)
        proxy = tx.output.create_proxy('call_function', fn, *proxy_args_kwargs(args, kwargs))
        if any((isinstance(arg, FakeItemVariable) for arg in args)):
            return wrap_fx_proxy_cls(FakeItemVariable, tx, proxy)
        elif check_unspec_python_args(args, kwargs):
            (_args, _kwargs) = self.unwrap_unspec_args_kwargs(args, kwargs)
            raw_value = fn(*_args, **_kwargs)
            need_unwrap = any((x.need_unwrap for x in itertools.chain(args, kwargs.values()) if isinstance(x, variables.UnspecializedPythonVariable)))
            return wrap_fx_proxy_cls(UnspecializedPythonVariable, tx, proxy, raw_value=raw_value, need_unwrap=need_unwrap)
        elif <MASK>:
            return SymNodeVariable.create(tx, proxy, None)
        else:
            if fn is operator.truediv and isinstance(args[0], variables.UnspecializedPythonVariable):
                args[0] = args[0].as_python_constant()
            return wrap_fx_proxy(tx, proxy)
    except NotImplementedError:
        unimplemented_v2(gb_type='unimplemented builtin op on tensor arguments', context=f'partial tensor op: {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace builtin operator {self.fn} with tensor arguments', hints=[*graph_break_hints.SUPPORTABLE])

def wrap_in_placeholder(self, arg, shape_info):
    """Wraps `arg` in a placeholder to limit static shape info.

    Args:
      arg: The value to wrap.  A Tensor, RaggedTensor, or TensorShape.
      shape_info: One of ['known', 'unknown_dims', 'unknown_rank'].

    Returns:
      * If shape_info is 'known': returns `arg`.
      * If shape_info is 'unknown_dims': returns a placeholder wrapping `arg`
        where the dimension sizes are unknown.  If `arg` is a TensorShape,
        then convert it to a vector first.  If `arg` is a RaggedTensor, then
        wrap the flat_values.
      * If shape_info is 'unknown_rank': returns a placeholder wrapping `arg`
        where the rank is unknown.  If `arg` is a TensorShape, then convert it
        to a vector first.  If `arg` is a RaggedTensor, then wrap the
        flat_values.
    """
    if shape_info == 'known':
        return arg
    if isinstance(arg, ragged_tensor.RaggedTensor):
        return arg.with_flat_values(self.wrap_in_placeholder(arg.flat_values, shape_info))
    if <MASK>:
        if arg.ndims is None:
            return arg
        arg = constant_op.constant(arg.as_list())
    if shape_info == 'unknown_rank':
        return array_ops.placeholder_with_default(arg, None)
    if shape_info == 'unknown_dims':
        return array_ops.placeholder_with_default(arg, [None] * arg.shape.rank)
    raise AssertionError('Unexpected shape_info %r' % shape_info)

@dispatch.dispatch_for_api(array_ops.one_hot)
def ragged_one_hot(indices: ragged_tensor.Ragged, depth, on_value=None, off_value=None, axis=None, dtype=None, name=None):
    """Applies tf.one_hot along the values of a RaggedTensor."""
    if isinstance(axis, int) and axis >= 0:
        if <MASK>:
            raise ValueError('axis (%d) must be greater than indices.ragged_rank (%d).' % (axis, indices.ragged_rank))
        axis -= indices.ragged_rank
    with ops.name_scope(name, 'RaggedOneHot', [indices, depth, on_value, off_value, axis]):
        indices = ragged_tensor.convert_to_tensor_or_ragged_tensor(indices, name='indices')
        return indices.with_flat_values(array_ops.one_hot(indices.flat_values, depth, on_value, off_value, axis, dtype, name))

def _test(self, kwargs, expected_context_values=None, expected_feat_list_values=None, expected_length_values=None, expected_err=None, batch=False):
    expected_context_values = expected_context_values or {}
    expected_feat_list_values = expected_feat_list_values or {}
    expected_length_values = expected_length_values or {}
    if expected_err:
        with self.assertRaisesWithPredicateMatch(expected_err[0], expected_err[1]):
            if <MASK>:
                self.evaluate(parsing_ops.parse_sequence_example(**kwargs))
            else:
                self.evaluate(parsing_ops.parse_single_sequence_example(**kwargs))
    else:
        if batch:
            (context_out, feat_list_out, lengths_out) = parsing_ops.parse_sequence_example(**kwargs)
        else:
            (context_out, feat_list_out) = parsing_ops.parse_single_sequence_example(**kwargs)
            lengths_out = {}
        _compare_output_to_expected(self, context_out, expected_context_values)
        _compare_output_to_expected(self, feat_list_out, expected_feat_list_values)
        _compare_output_to_expected(self, lengths_out, expected_length_values)
    if 'context_features' in kwargs:
        for (k, f) in kwargs['context_features'].items():
            if isinstance(f, parsing_ops.FixedLenFeature) and f.shape is not None:
                if batch:
                    self.assertEqual(tuple(context_out[k].shape.as_list()[1:]), f.shape)
                else:
                    self.assertEqual(tuple(context_out[k].shape.as_list()), f.shape)
            elif isinstance(f, parsing_ops.VarLenFeature) and batch:
                if context.executing_eagerly():
                    context_out[k].indices.shape.assert_is_compatible_with([None, 2])
                    context_out[k].values.shape.assert_is_compatible_with([None])
                    context_out[k].dense_shape.shape.assert_is_compatible_with([2])
                else:
                    self.assertEqual(context_out[k].indices.shape.as_list(), [None, 2])
                    self.assertEqual(context_out[k].values.shape.as_list(), [None])
                    self.assertEqual(context_out[k].dense_shape.shape.as_list(), [2])
            elif isinstance(f, parsing_ops.VarLenFeature) and (not batch):
                if context.executing_eagerly():
                    context_out[k].indices.shape.assert_is_compatible_with([None, 1])
                    context_out[k].values.shape.assert_is_compatible_with([None])
                    context_out[k].dense_shape.shape.assert_is_compatible_with([1])
                else:
                    self.assertEqual(context_out[k].indices.shape.as_list(), [None, 1])
                    self.assertEqual(context_out[k].values.shape.as_list(), [None])
                    self.assertEqual(context_out[k].dense_shape.shape.as_list(), [1])

def parse_readable_size_str(size_str):
    """Convert a human-readable str representation to number of bytes.

  Only the units "kB", "MB", "GB" are supported. The "B character at the end
  of the input `str` may be omitted.

  Args:
    size_str: (`str`) A human-readable str representing a number of bytes
      (e.g., "0", "1023", "1.1kB", "24 MB", "23GB", "100 G".

  Returns:
    (`int`) The parsed number of bytes.

  Raises:
    ValueError: on failure to parse the input `size_str`.
  """
    size_str = size_str.strip()
    if size_str.endswith('B'):
        size_str = size_str[:-1]
    if <MASK>:
        return int(size_str)
    elif size_str.endswith('k'):
        return int(float(size_str[:-1]) * 1024)
    elif size_str.endswith('M'):
        return int(float(size_str[:-1]) * 1048576)
    elif size_str.endswith('G'):
        return int(float(size_str[:-1]) * 1073741824)
    else:
        raise ValueError('Failed to parsed human-readable byte size str: "%s"' % size_str)

def wrapper_singleton() -> _ValgrindWrapper:
