def _iterparse_nodes(self, iterparse: Callable) -> list[dict[str, str | None]]:
    """
        Iterparse xml nodes.

        This method will read in local disk, decompressed XML files for elements
        and underlying descendants using iterparse, a method to iterate through
        an XML tree without holding entire XML tree in memory.

        Raises
        ------
        TypeError
            * If ``iterparse`` is not a dict or its dict value is not list-like.
        ParserError
            * If ``path_or_buffer`` is not a physical file on disk or file-like object.
            * If no data is returned from selected items in ``iterparse``.

        Notes
        -----
        Namespace URIs will be removed from return node values. Also,
        elements with missing children or attributes in submitted list
        will have optional keys filled with None values.
        """
    dicts: list[dict[str, str | None]] = []
    row: dict[str, str | None] | None = None
    if not isinstance(self.iterparse, dict):
        raise TypeError(f'{type(self.iterparse).__name__} is not a valid type for iterparse')
    row_node = next(iter(self.iterparse.keys())) if self.iterparse else ''
    if <MASK>:
        raise TypeError(f'{type(self.iterparse[row_node])} is not a valid type for value in iterparse')
    if not hasattr(self.path_or_buffer, 'read') and (not isinstance(self.path_or_buffer, (str, PathLike)) or is_url(self.path_or_buffer) or is_fsspec_url(self.path_or_buffer) or (isinstance(self.path_or_buffer, str) and self.path_or_buffer.startswith(('<?xml', '<'))) or (infer_compression(self.path_or_buffer, 'infer') is not None)):
        raise ParserError('iterparse is designed for large XML files that are fully extracted on local disk and not as compressed files or online sources.')
    iterparse_repeats = len(self.iterparse[row_node]) != len(set(self.iterparse[row_node]))
    for (event, elem) in iterparse(self.path_or_buffer, events=('start', 'end')):
        curr_elem = elem.tag.split('}')[1] if '}' in elem.tag else elem.tag
        if event == 'start':
            if curr_elem == row_node:
                row = {}
        if row is not None:
            if self.names and iterparse_repeats:
                for (col, nm) in zip(self.iterparse[row_node], self.names, strict=True):
                    if curr_elem == col:
                        elem_val = elem.text if elem.text else None
                        if elem_val not in row.values() and nm not in row:
                            row[nm] = elem_val
                    if col in elem.attrib:
                        if elem.attrib[col] not in row.values() and nm not in row:
                            row[nm] = elem.attrib[col]
            else:
                for col in self.iterparse[row_node]:
                    if curr_elem == col:
                        row[col] = elem.text if elem.text else None
                    if col in elem.attrib:
                        row[col] = elem.attrib[col]
        if event == 'end':
            if curr_elem == row_node and row is not None:
                dicts.append(row)
                row = None
            elem.clear()
            if hasattr(elem, 'getprevious'):
                while elem.getprevious() is not None and elem.getparent() is not None:
                    del elem.getparent()[0]
    if dicts == []:
        raise ParserError('No result from selected items in iterparse.')
    keys = list(dict.fromkeys([k for d in dicts for k in d.keys()]))
    dicts = [{k: d[k] if k in d.keys() else None for k in keys} for d in dicts]
    if self.names:
        dicts = [dict(zip(self.names, d.values(), strict=True)) for d in dicts]
    return dicts

def get_possible_fusions(self, nodes: list[BaseSchedulerNode], is_reorder_round: bool) -> list[tuple[BaseSchedulerNode, BaseSchedulerNode]]:
    """
        Helper to find all legal fusion opportunities, sorted by self.score_fusion()
        """
    possible_fusions = []
    seen = OrderedSet[tuple[BaseSchedulerNode, BaseSchedulerNode]]()

    def check_all_pairs(nodes: list[BaseSchedulerNode]) -> None:
        for (node1_index, node1) in enumerate(nodes):
            for node2 in nodes[node1_index + 1:node1_index + 1 + config.max_fusion_buffer_group_pairwise_attempts]:
                key = (node1, node2)
                if <MASK>:
                    continue
                seen.add(key)
                if self.can_fuse(node1, node2, is_reorder_round):
                    possible_fusions.append(key)
                elif (node2.is_template() or node2.is_foreach()) and self.can_fuse(node2, node1, is_reorder_round):
                    possible_fusions.append((node2, node1))
    buffer_names_grouping = collections.defaultdict(list)
    for node in nodes:
        if self.unfusable_node(node):
            continue
        for buf in node.used_buffer_names():
            buffer_names_grouping[buf].append(node)
    for node_grouping in buffer_names_grouping.values():
        check_all_pairs(node_grouping)
    if config.aggressive_fusion:
        group_grouping = collections.defaultdict(list)
        for node in nodes:
            group = getattr(node, 'group', None)
            if group:
                group_grouping[group].append(node)
        for node_grouping in group_grouping.values():
            check_all_pairs(node_grouping)
    possible_fusions = self.get_possible_fusions_with_highest_priority(possible_fusions)
    possible_fusions.sort(key=self.score_fusion_key, reverse=True)
    fusion_log.debug('found %d possible fusions', len(possible_fusions))
    return possible_fusions

def _get_foreign_key(parent_model, model, fk_name=None, can_fail=False):
    """
    Find and return the ForeignKey from model to parent if there is one
    (return None if can_fail is True and no such field exists). If fk_name is
    provided, assume it is the name of the ForeignKey field. Unless can_fail is
    True, raise an exception if there isn't a ForeignKey from model to
    parent_model.
    """
    from django.db.models import ForeignKey
    opts = model._meta
    if fk_name:
        fks_to_parent = [f for f in opts.fields if f.name == fk_name]
        if len(fks_to_parent) == 1:
            fk = fks_to_parent[0]
            all_parents = (*parent_model._meta.all_parents, parent_model)
            if not isinstance(fk, ForeignKey) or (fk.remote_field.model._meta.proxy and fk.remote_field.model._meta.proxy_for_model not in all_parents) or (not fk.remote_field.model._meta.proxy and fk.remote_field.model != parent_model and (fk.remote_field.model not in all_parents)):
                raise ValueError("fk_name '%s' is not a ForeignKey to '%s'." % (fk_name, parent_model._meta.label))
        elif <MASK>:
            raise ValueError("'%s' has no field named '%s'." % (model._meta.label, fk_name))
    else:
        all_parents = (*parent_model._meta.all_parents, parent_model)
        fks_to_parent = [f for f in opts.fields if isinstance(f, ForeignKey) and (f.remote_field.model == parent_model or f.remote_field.model in all_parents or (f.remote_field.model._meta.proxy and f.remote_field.model._meta.proxy_for_model in all_parents))]
        if len(fks_to_parent) == 1:
            fk = fks_to_parent[0]
        elif not fks_to_parent:
            if can_fail:
                return
            raise ValueError("'%s' has no ForeignKey to '%s'." % (model._meta.label, parent_model._meta.label))
        else:
            raise ValueError("'%s' has more than one ForeignKey to '%s'. You must specify a 'fk_name' attribute." % (model._meta.label, parent_model._meta.label))
    return fk

def get_flags_linker_so(self):
    opt = self.linker_so[1:]
    if <MASK>:
        target = os.environ.get('MACOSX_DEPLOYMENT_TARGET', None)
        if not target:
            import sysconfig
            target = sysconfig.get_config_var('MACOSX_DEPLOYMENT_TARGET')
            if not target:
                target = '10.9'
                s = f'Env. variable MACOSX_DEPLOYMENT_TARGET set to {target}'
                warnings.warn(s, stacklevel=2)
            os.environ['MACOSX_DEPLOYMENT_TARGET'] = str(target)
        opt.extend(['-undefined', 'dynamic_lookup', '-bundle'])
    else:
        opt.append('-shared')
    if sys.platform.startswith('sunos'):
        opt.append('-mimpure-text')
    return opt

def transform_from(self, input: IO[bytes]) -> IO[bytes]:

    class Reader(io.RawIOBase):

        def __init__(self, input: IO[bytes]) -> None:
            self.input = input

        def readable(self) -> bool:
            return True

        def readinto(self, b: Buffer) -> Optional[int]:
            if hasattr(self.input, 'readinto'):
                count = self.input.readinto(b)
            else:
                view = memoryview(b)
                r = self.input.read(len(view))
                if <MASK>:
                    count = None
                else:
                    count = len(r)
                    view[:count] = r
            if count == 0 or count is None:
                return count
            Rot13Example._rot13bytes(b, count)
            return count

        def seekable(self) -> bool:
            return self.input.seekable()

        def seek(self, offset: int, whence: int=os.SEEK_SET) -> int:
            return self.input.seek(offset, whence)

        def tell(self) -> int:
            return self.input.tell()
    return cast(IO[bytes], Reader(input))

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName) -> NamedCType:
    r = cpp.valuetype_type(t, symint=False, binds=binds, mutable=mutable)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif <MASK>:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, BaseCType(optionalTensorRefT))
        elif t.elem == BaseType(BaseTy.Scalar):
            return NamedCType(binds, BaseCType(optionalScalarRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
        elif t.elem == OptionalType(BaseType(BaseTy.Tensor)):
            return NamedCType(binds, BaseCType(iOptTensorListRefT))
        elif str(t.elem) == 'int':
            return NamedCType(binds, BaseCType(intArrayRefT))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

def __getstate__(self):
    memory_format = self.memory_format
    if <MASK>:
        mem_format_encoding = _MEM_FORMAT_ENCODING.TORCH_CONTIGUOUS_FORMAT
    elif memory_format == torch.channels_last:
        mem_format_encoding = _MEM_FORMAT_ENCODING.TORCH_CHANNELS_LAST
    elif memory_format == torch.preserve_format:
        mem_format_encoding = _MEM_FORMAT_ENCODING.TORCH_PRESERVE_FORMAT
    else:
        raise RuntimeError(f'Invalid torch.memory_format: {memory_format}')
    return (self.dtype, self.layout, self.requires_grad, mem_format_encoding, self.pin_memory)

def _unique_python(values, *, return_inverse, return_counts):
    try:
        uniques_set = set(values)
        (uniques_set, missing_values) = _extract_missing(uniques_set)
        uniques = sorted(uniques_set)
        uniques.extend(missing_values.to_list())
        uniques = np.array(uniques, dtype=values.dtype)
    except TypeError:
        types = sorted((t.__qualname__ for t in set((type(v) for v in values))))
        raise TypeError(f'Encoders require their input argument must be uniformly strings or numbers. Got {types}')
    ret = (uniques,)
    if <MASK>:
        ret += (_map_to_integer(values, uniques),)
    if return_counts:
        ret += (_get_counts(values, uniques),)
    return ret[0] if len(ret) == 1 else ret

def multiply(data, N, i, j, cs, sn, left=True):
    for k in range(N):
        if <MASK>:
            (ik, jk) = ((k, i), (k, j))
        else:
            (ik, jk) = ((i, k), (j, k))
        (aik, ajk) = (data.get(ik, 0), data.get(jk, 0))
        (aik, ajk) = (cs * aik + sn * ajk, -sn * aik + cs * ajk)
        if aik:
            data[ik] = aik
        else:
            data.pop(ik, None)
        if ajk:
            data[jk] = ajk
        else:
            data.pop(jk, None)

@staticmethod
def tag_nodes(gmod, is_sac):
