            new_tensor.grad = self.grad.__deepcopy__(memo)
        if type(self) is not Tensor:
            if type(new_tensor) is not type(self):
                raise RuntimeError("Type of deepcopy result does not match the type of the source tensor. If you encounter this, please open an issue on PyTorch's GitHub.")
            slots_to_save = copyreg._slotnames(self.__class__)
            for slot in slots_to_save:
                if hasattr(self, slot):
                    setattr(new_tensor, slot, deepcopy(getattr(self, slot), memo))
        self._clear_non_serializable_cached_data()
        new_tensor.__dict__ = deepcopy(self.__dict__, memo)
        memo[id(self)] = new_tensor
        return new_tensor

@classmethod
def from_parameter(cls, config):
    if <MASK>:
        return config
    return cls(config)

def repl(x):
    if <MASK>:
        return array_ops.placeholder_with_default(x, shape=None)
    else:
        return x

def create_graph_input(self, name: str, type_expr: Any, example_value: Any, before: bool=False, source: Optional[Source]=None) -> fx.Proxy:
    if <MASK>:
        self._input_versions_at_beginning.append(example_value._version)
    log.debug('create_graph_input %s %s %s at debug_level %s before=%s', name, source.name() if source is not None else '(none)', example_value, self.debug_level, before)
    if source is None:
        assert self.parent is not None, f'you are required to provide a source for inputs {name} example_val {example_value} on the root tracer'
    if self.is_export and self.parent is None:
        assert source is not None
        if not is_from_local_source(source, only_allow_input=True):
            self.output_graph.source_to_user_stacks.setdefault(source, []).append(TracingContext.extract_stack())
    name = get_unique_name_wrt(name, self._used_names)
    if self.input_name_to_proxy:
        prev_name = next(reversed(self.input_name_to_proxy))
        node = self.input_name_to_proxy[prev_name].node
        if before:
            ctx = self.graph.inserting_before(node)
        else:
            ctx = self.graph.inserting_after(node)
    else:
        ctx = self.graph.inserting_before(None)
    with ctx:
        proxy = self.create_proxy('placeholder', name, (), {}, type_expr=type_expr)
        set_example_value(proxy.node, example_value)
        if self.input_name_to_proxy and before:
            (k, v) = self.input_name_to_proxy.popitem()
            self.input_name_to_proxy[name] = proxy
            self.input_name_to_proxy[k] = v
        else:
            self.input_name_to_proxy[name] = proxy
        self._used_names.add(name)
        is_strict_export = self.is_export
        is_non_strict_export = torch.compiler.is_compiling()
        if not is_strict_export and (not is_non_strict_export):
            if isinstance(example_value, torch.Tensor):
                self._lift_basic_symbols(example_value, source)
            elif isinstance(example_value, (list, tuple)):
                for (i, e) in enumerate(example_value):
                    if not isinstance(e, torch.Tensor):
                        continue
                    e_source = None
                    if source:
                        e_source = GetItemSource(base=source, index=i, index_is_slice=False)
                    self._lift_basic_symbols(e, e_source)
        if isinstance(example_value, torch.SymInt) and isinstance(example_value.node.expr, sympy.Symbol):
            self.bound_symbols[example_value.node.expr] = proxy
        return proxy

def as_array(self, dtype: np.dtype | None=None, copy: bool=False, na_value: object=lib.no_default) -> np.ndarray:
    """
        Convert the blockmanager data into an numpy array.

        Parameters
        ----------
        dtype : np.dtype or None, default None
            Data type of the return array.
        copy : bool, default False
            If True then guarantee that a copy is returned. A value of
            False does not guarantee that the underlying data is not
            copied.
        na_value : object, default lib.no_default
            Value to be used as the missing value sentinel.

        Returns
        -------
        arr : ndarray
        """
    passed_nan = lib.is_float(na_value) and isna(na_value)
    if <MASK>:
        arr = np.empty(self.shape, dtype=float)
        return arr.transpose()
    if self.is_single_block:
        blk = self.blocks[0]
        if na_value is not lib.no_default:
            if lib.is_np_dtype(blk.dtype, 'f') and passed_nan:
                pass
            else:
                copy = True
        if blk.is_extension:
            arr = blk.values.to_numpy(dtype=dtype, na_value=na_value, copy=copy).reshape(blk.shape)
        elif not copy:
            arr = np.asarray(blk.values, dtype=dtype)
        else:
            arr = np.array(blk.values, dtype=dtype, copy=copy)
        if passed_nan and blk.dtype.kind in 'mM':
            arr[isna(blk.values)] = na_value
        if not copy:
            arr = arr.view()
            arr.flags.writeable = False
    else:
        arr = self._interleave(dtype=dtype, na_value=na_value)
    if na_value is lib.no_default:
        pass
    elif arr.dtype.kind == 'f' and passed_nan:
        pass
    else:
        arr[isna(arr)] = na_value
    return arr.transpose()

def reconstruct_items(self, codegen: 'PyCodegen'):
    for it in self.iterables:
        if <MASK>:
            remaining_items = it[self.index:]
            codegen.foreach(remaining_items)
            codegen.append_output(create_build_tuple(len(remaining_items)))
        else:
            codegen(it)

def var(self, ddof: int=1, numeric_only: bool=False, engine: Literal['cython', 'numba'] | None=None, engine_kwargs: dict[str, bool] | None=None):
    if <MASK>:
        if self.method == 'table':
            raise NotImplementedError("var not supported with method='table'")
        from pandas.core._numba.kernels import sliding_var
        return self._numba_apply(sliding_var, engine_kwargs, ddof=ddof)
    window_func = partial(window_aggregations.roll_var, ddof=ddof)
    return self._apply(window_func, name='var', numeric_only=numeric_only)

def _ctc_loss_impl(labels, inputs=None, sequence_length=None, preprocess_collapse_repeated=False, ctc_merge_repeated=True, ignore_longer_outputs_than_inputs=False, time_major=True, logits=None, use_cudnn=False):
    if not isinstance(labels, sparse_tensor.SparseTensor):
        raise TypeError(f'Expected argument `labels` to be a SparseTensor. Received labels={labels} of type: {type(labels).__name__}')
    inputs = deprecation.deprecated_argument_lookup('logits', logits, 'inputs', inputs)
    inputs = ops.convert_to_tensor(inputs, name='logits')
    if <MASK>:
        inputs = array_ops.transpose(inputs, [1, 0, 2])
    orig_dtype = inputs.dtype
    if orig_dtype in (dtypes.float16, dtypes.bfloat16):
        inputs = math_ops.cast(inputs, dtypes.float32)
    if use_cudnn:
        ctc_loss_func = gen_ctc_ops.ctc_loss_v2
    else:
        ctc_loss_func = gen_ctc_ops.ctc_loss
    (loss, _) = ctc_loss_func(inputs, labels.indices, labels.values, sequence_length, preprocess_collapse_repeated=preprocess_collapse_repeated, ctc_merge_repeated=ctc_merge_repeated, ignore_longer_outputs_than_inputs=ignore_longer_outputs_than_inputs)
    if orig_dtype in (dtypes.float16, dtypes.bfloat16):
        loss = math_ops.cast(loss, orig_dtype)
    return loss

def _reshape_for_efficiency(a, b, transpose_a=False, transpose_b=False, adjoint_a=False, adjoint_b=False):
    """Maybe reshape a, b, and return an inverse map.  For matmul/solve."""

    def identity(x):
        return x
    still_need_to_transpose = True
    if a.shape.ndims is None or b.shape.ndims is None:
        return (a, b, identity, still_need_to_transpose)
    if a.shape.ndims >= b.shape.ndims:
        return (a, b, identity, still_need_to_transpose)
    b_extra_ndims = b.shape.ndims - a.shape.ndims
    b_extra_sh = array_ops.shape(b)[:b_extra_ndims]
    b_main_sh = array_ops.shape(b)[b_extra_ndims:]
    a_domain_sz_ = a.shape[-2 if adjoint_a or transpose_a else -1]
    b_eq_sz_ = b.shape[-2 if adjoint_b or transpose_b else -1]
    b_extra_sz_ = np.prod(b.shape[:b_extra_ndims].as_list()) if b.shape[:b_extra_ndims].is_fully_defined() else None
    if a_domain_sz_ is not None and b_eq_sz_ is not None and (b_extra_sz_ is not None):
        if b_extra_sz_ < 2 or a_domain_sz_ <= b_eq_sz_:
            return (a, b, identity, still_need_to_transpose)
    if adjoint_a:
        a = array_ops.matrix_transpose(a, conjugate=True)
    elif transpose_a:
        a = array_ops.matrix_transpose(a, conjugate=False)
    if <MASK>:
        b = array_ops.matrix_transpose(b, conjugate=True)
    elif transpose_a:
        b = array_ops.matrix_transpose(b, conjugate=False)
    still_need_to_transpose = False
    b_extra_sh = array_ops.shape(b)[:b_extra_ndims]
    b_main_sh = array_ops.shape(b)[b_extra_ndims:]
    perm = np.concatenate((np.arange(b_extra_ndims, b.shape.ndims), np.arange(0, b_extra_ndims)), 0)
    b_extra_on_end = array_ops.transpose(b, perm=perm)
    b_squashed_end = array_ops.reshape(b_extra_on_end, array_ops.concat((b_main_sh[:-1], [-1]), 0))

    def reshape_inv(y):
        y_extra_shape = array_ops.concat((array_ops.shape(y)[:-1], [b_main_sh[-1]], b_extra_sh), 0)
        y_extra_on_end = array_ops.reshape(y, y_extra_shape)
        inverse_perm = np.argsort(perm)
        return array_ops.transpose(y_extra_on_end, perm=inverse_perm)
    return (a, b_squashed_end, reshape_inv, still_need_to_transpose)

def _port_metadata_for_output_quant_nodes(node: torch.fx.Node, qspec: Optional[QuantizationSpecBase]):
    if qspec is None:
        return
    node_users = _filter_sym_size_users(node)
    if len(node.users) == 0:
        return
    if len(node_users) != 1:
        logger.warning(f'Expecting {node} to have single user')
    q_node = node_users.pop()
    if <MASK>:
        logger.warning(f'Expecting {node} user to be a quantized op but got {q_node}')
        return
    _add_metadata(q_node, node)

@classmethod
def profile_compile_time(cls, func: Any, phase_name: str, *args: Any, **kwargs: Any) -> Any:

    def skip() -> Any:
        return func(*args, **kwargs)
    if not cls.enabled:
        return skip()
    if cls.profiler is None:
        logger.error('profiler is not set')
        return
    frame_id = cls.get_frame()
    if <MASK>:
        cls.ignored_profile_runs += 1
        logger.info('profile_compile_time is requested for phase: %s, frame %s, while already in running phase: %s,frame %s, recursive call ignored', phase_name, frame_id, cls.current_phase, frame_id)
        return skip()
    if cls.frame_id_filter is not None:
        should_run = re.match(cls.frame_id_filter, frame_id) is not None
        if not should_run:
            logger.info('profiling frame %s is skipped due to frame_id_filter %s', frame_id, cls.frame_id_filter)
            return skip()
    cls.inside_profile_compile_time = True
    cls.current_phase = phase_name
    logger.info('profiling frame %s', frame_id)
    work_result = cls.profiler.profile(func, *args, **kwargs)
    if cls.profiler.profile_result is not None:
        cls.success_profile_count += 1
    else:
        cls.failed_profile_count += 1
    cls._log_stats()
    cls.inside_profile_compile_time = False
    return work_result

@staticmethod
def get_comm_tensor_size(func, res, args, kwargs) -> int:
    """Compute the communication tensor size, except for `wait_tensor`, `barrier`, and `monitored_barrier`."""
    if func in CollectiveOp.COMM_TENSOR_ARG_0:
        return CollectiveOp.sum_tensors(args[0])
    if <MASK>:
        return CollectiveOp.sum_tensors(args[1])
    if func in CollectiveOp.COMM_TENSOR_ARG_RES:
        return res.untyped_storage().nbytes()
    if func in CollectiveOp.COMM_TENSOR_SINGLE_UNTYPED_STORAGE:
        return args[0].untyped_storage().nbytes()
    if func == c10d._reduce_scatter_base_.default:
        return args[1].untyped_storage().nbytes()
    if func == c10d.alltoall_.default:
        return max(CollectiveOp.sum_tensors(args[0]), CollectiveOp.sum_tensors(args[1]))
    if func == c10d.alltoall_base_.default:
        return max(args[0].untyped_storage().nbytes(), args[1].untyped_storage().nbytes())
    if func == _c10d_functional.all_gather_into_tensor_out.default:
        return args[-1].untyped_storage().nbytes()
    if func in CollectiveOp.COMM_TENSOR_RES_SUM:
        return CollectiveOp.sum_tensors(res)
    if func in CollectiveOp.COMM_TENSOR_ARG_0_AND_RES:
        return args[0].untyped_storage().nbytes() + res.untyped_storage().nbytes()
    raise TypeError(f'Unknown function: {func} in {collective_ops}')

def build_fbcode_re(self) -> None:
    with dynamo_timed('compile_file'):
        command = self.get_command_line().split()
        try:
            output_path = self._target_file
            torch_includes_path = os.path.join(_TORCH_PATH, 'include')
            with tempfile.TemporaryDirectory() as tmp_dir:
                shutil.copy(_LINKER_SCRIPT, os.path.join(tmp_dir, 'script.ld'))
                for src in self._orig_source_paths:
                    shutil.copy(src, os.path.join(tmp_dir, os.path.basename(src)))
                dest_include_path = os.path.join(tmp_dir, 'include')
                shutil.copytree(torch_includes_path, dest_include_path)
                tmp_output_path = _run_build_command(command, tmp_dir, os.path.basename(output_path))
                if os.path.exists(output_path):
                    os.remove(output_path)
                shutil.copy(tmp_output_path, output_path)
                if <MASK>:
                    os.chmod(output_path, 420)
                elif output_path.endswith('.so'):
                    os.chmod(output_path, 493)
        except subprocess.CalledProcessError as e:
            output = e.output.decode('utf-8')
            raise exc.CppCompileError(command, output) from e

def _all_reduce(self, reduce_op, value, replica_id, options):
    """Implements CrossDeviceOps.all_reduce."""
    flat_values = nest.flatten(value)
    if self._limited_nccl and options.implementation == collective_util.CommunicationImplementation.NCCL and (len(flat_values) == 1):
        options = options.merge(collective_util.Options(implementation=collective_util.CommunicationImplementation.RING))
    launcher = self._launchers[replica_id]
    (dense_values, dense_indices, sparse_values, sparse_indices) = cross_device_utils.split_by_sparsity(flat_values)
    dense_results = []
    sparse_results = []
    if dense_values:
        dense_values.reverse()
        packs = cross_device_utils.group_by_size(dense_values, options.bytes_per_pack)
        if not context.executing_eagerly() and replica_id == 0:
            logging.info('Collective all_reduce tensors: %d all_reduces, num_devices = %d, group_size = %d, implementation = %s, num_packs = %d', len(dense_values), len(self._launchers), self._group_size, options.implementation, len(packs))
        dense_results = launcher.batch_all_reduce(packs, options)
        if <MASK>:
            for (i, v) in enumerate(dense_results):
                with ops.device(self._devices[replica_id]):
                    dense_results[i] = v / self._group_size
        dense_results.reverse()
    if sparse_values:
        if not context.executing_eagerly() and replica_id == 0:
            logging.info('Collective all_reduce IndexedSlices: %d all_reduces, num_devices =%d, group_size = %d, implementation = %s', len(sparse_values), len(self._launchers), self._group_size, options.implementation)
        for indexed_slice in sparse_values:
            sparse_results.append(launcher.all_reduce_indexed_slices(indexed_slice, options))
        if reduce_op == reduce_util.ReduceOp.MEAN:
            for (i, v) in enumerate(sparse_results):
                with ops.device(self._devices[replica_id]):
                    sparse_results[i] = indexed_slices.IndexedSlices(values=sparse_results[i].values / self._group_size, indices=sparse_results[i].indices, dense_shape=sparse_results[i].dense_shape)
    flat_results = cross_device_utils.stitch_values(((dense_results, dense_indices), (sparse_results, sparse_indices)))
    return nest.pack_sequence_as(value, flat_results)

def maybe_wrap_dim(dim: int, dim_post_expr: int, wrap_scalar: bool=True):
    if dim_post_expr <= 0:
        assert wrap_scalar
        dim_post_expr = 1
    min = -dim_post_expr
    max = dim_post_expr - 1
    assert not (dim < min or dim > max), f'dim {dim} out of bounds ({min}, {max})'
    if <MASK>:
        dim += dim_post_expr
    return dim

def __init__(self, n, **kwargs):
    super(RepeatVector, self).__init__(**kwargs)
    self.n = n
    if <MASK>:
        raise TypeError(f'Expected an integer value for `n`, got {type(n)}.')
    self.input_spec = InputSpec(ndim=2)

def logical_op(left: ArrayLike, right: Any, op) -> ArrayLike:
    """
    Evaluate a logical operation `|`, `&`, or `^`.

    Parameters
    ----------
    left : np.ndarray or ExtensionArray
    right : object
        Cannot be a DataFrame, Series, or Index.
    op : {operator.and_, operator.or_, operator.xor}
        Or one of the reversed variants from roperator.

    Returns
    -------
    ndarray or ExtensionArray
    """

    def fill_bool(x, left=None):
        if x.dtype.kind in 'cfO':
            mask = isna(x)
            if mask.any():
                x = x.astype(object)
                x[mask] = False
        if left is None or left.dtype.kind == 'b':
            x = x.astype(bool)
        return x
    right = lib.item_from_zerodim(right)
    if is_list_like(right) and (not hasattr(right, 'dtype')):
        raise TypeError('Logical ops (and, or, xor) between Pandas objects and dtype-less sequences (e.g. list, tuple) are no longer supported. Wrap the object in a Series, Index, or np.array before operating instead.')
    lvalues = ensure_wrapped_if_datetimelike(left)
    rvalues = right
    if should_extension_dispatch(lvalues, rvalues):
        res_values = op(lvalues, rvalues)
    else:
        if isinstance(rvalues, np.ndarray):
            is_other_int_dtype = rvalues.dtype.kind in 'iu'
            if <MASK>:
                rvalues = fill_bool(rvalues, lvalues)
        else:
            is_other_int_dtype = lib.is_integer(rvalues)
        res_values = na_logical_op(lvalues, rvalues, op)
        if not (left.dtype.kind in 'iu' and is_other_int_dtype):
            res_values = fill_bool(res_values)
    return res_values

@final
@_maybe_return_indexers
def join(self, other: Index, *, how: JoinHow='left', level: Level | None=None, return_indexers: bool=False, sort: bool=False) -> Index | tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    """
        Compute join_index and indexers to conform data structures to the new index.

        Parameters
        ----------
        other : Index
            The other index on which join is performed.
        how : {'left', 'right', 'inner', 'outer'}
        level : int or level name, default None
            It is either the integer position or the name of the level.
        return_indexers : bool, default False
            Whether to return the indexers or not for both the index objects.
        sort : bool, default False
            Sort the join keys lexicographically in the result Index. If False,
            the order of the join keys depends on the join type (how keyword).

        Returns
        -------
        join_index, (left_indexer, right_indexer)
            The new index.

        See Also
        --------
        DataFrame.join : Join columns with `other` DataFrame either on index
            or on a key.
        DataFrame.merge : Merge DataFrame or named Series objects with a
            database-style join.

        Examples
        --------
        >>> idx1 = pd.Index([1, 2, 3])
        >>> idx2 = pd.Index([4, 5, 6])
        >>> idx1.join(idx2, how="outer")
        Index([1, 2, 3, 4, 5, 6], dtype='int64')
        >>> idx1.join(other=idx2, how="outer", return_indexers=True)
        (Index([1, 2, 3, 4, 5, 6], dtype='int64'),
        array([ 0,  1,  2, -1, -1, -1]), array([-1, -1, -1,  0,  1,  2]))
        """
    other = ensure_index(other)
    sort = sort or how == 'outer'
    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex):
        if (self.tz is None) ^ (other.tz is None):
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
    if <MASK>:
        (pself, pother) = self._maybe_downcast_for_indexing(other)
        if pself is not self or pother is not other:
            return pself.join(pother, how=how, level=level, return_indexers=True, sort=sort)
    if level is None and (self._is_multi or other._is_multi):
        if self.names == other.names:
            pass
        else:
            return self._join_multi(other, how=how)
    if level is not None and (self._is_multi or other._is_multi):
        return self._join_level(other, level, how=how)
    if len(self) == 0 or len(other) == 0:
        try:
            return self._join_empty(other, how, sort)
        except TypeError:
            pass
    if self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        other = other.astype(dtype, copy=False)
        return this.join(other, how=how, return_indexers=True)
    elif isinstance(self, ABCCategoricalIndex) and isinstance(other, ABCCategoricalIndex) and (not self.ordered) and (not self.categories.equals(other.categories)):
        other = Index(other._values.reorder_categories(self.categories))
    _validate_join_method(how)
    if self.is_monotonic_increasing and other.is_monotonic_increasing and self._can_use_libjoin and other._can_use_libjoin and (self.is_unique or other.is_unique):
        try:
            return self._join_monotonic(other, how=how)
        except TypeError:
            pass
    elif not self.is_unique or not other.is_unique:
        return self._join_non_unique(other, how=how, sort=sort)
    return self._join_via_get_indexer(other, how, sort)

def _GetSvdOpTest(dtype_, shape_, use_static_shape_, compute_uv_, full_matrices_):

    def CompareSingularValues(self, x, y, tol):
        atol = (x[0] + y[0]) * tol if len(x) else tol
        self.assertAllClose(x, y, atol=atol)

    def CompareSingularVectors(self, x, y, rank, tol):
        x = x[..., 0:rank]
        y = y[..., 0:rank]
        sum_of_ratios = np.sum(np.divide(y, x), -2, keepdims=True)
        phases = np.divide(sum_of_ratios, np.abs(sum_of_ratios))
        x *= phases
        self.assertAllClose(x, y, atol=2 * tol)

    def CheckApproximation(self, a, u, s, v, full_matrices_, tol):
        batch_shape = a.shape[:-2]
        m = a.shape[-2]
        n = a.shape[-1]
        diag_s = math_ops.cast(array_ops.matrix_diag(s), dtype=dtype_)
        if full_matrices_:
            if m > n:
                zeros = array_ops.zeros(batch_shape + (m - n, n), dtype=dtype_)
                diag_s = array_ops.concat([diag_s, zeros], a.ndim - 2)
            elif n > m:
                zeros = array_ops.zeros(batch_shape + (m, n - m), dtype=dtype_)
                diag_s = array_ops.concat([diag_s, zeros], a.ndim - 1)
        a_recon = math_ops.matmul(u, diag_s)
        a_recon = math_ops.matmul(a_recon, v, adjoint_b=True)
        self.assertAllClose(a_recon, a, rtol=tol, atol=tol)

    def CheckUnitary(self, x, tol):
        xx = math_ops.matmul(x, x, adjoint_a=True)
        identity = array_ops.matrix_band_part(array_ops.ones_like(xx), 0, 0)
        self.assertAllClose(identity, xx, atol=tol)

    @test_util.run_in_graph_and_eager_modes(use_gpu=True)
    def Test(self):
        if not use_static_shape_ and context.executing_eagerly():
            return
        is_complex = dtype_ in (np.complex64, np.complex128)
        is_single = dtype_ in (np.float32, np.complex64)
        tol = 0.0003 if is_single else 1e-12
        if <MASK>:
            tol *= 200
        np.random.seed(42)
        x_np = np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape_)).reshape(shape_).astype(dtype_)
        if is_complex:
            x_np += 1j * np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape_)).reshape(shape_).astype(dtype_)
        if use_static_shape_:
            x_tf = constant_op.constant(x_np)
        else:
            x_tf = array_ops.placeholder(dtype_)
        if compute_uv_:
            (s_tf, u_tf, v_tf) = linalg_ops.svd(x_tf, compute_uv=compute_uv_, full_matrices=full_matrices_)
            if use_static_shape_:
                (s_tf_val, u_tf_val, v_tf_val) = self.evaluate([s_tf, u_tf, v_tf])
            else:
                with self.session() as sess:
                    (s_tf_val, u_tf_val, v_tf_val) = sess.run([s_tf, u_tf, v_tf], feed_dict={x_tf: x_np})
        else:
            s_tf = linalg_ops.svd(x_tf, compute_uv=compute_uv_, full_matrices=full_matrices_)
            if use_static_shape_:
                s_tf_val = self.evaluate(s_tf)
            else:
                with self.session() as sess:
                    s_tf_val = sess.run(s_tf, feed_dict={x_tf: x_np})
        if compute_uv_:
            (u_np, s_np, v_np) = np.linalg.svd(x_np, compute_uv=compute_uv_, full_matrices=full_matrices_)
        else:
            s_np = np.linalg.svd(x_np, compute_uv=compute_uv_, full_matrices=full_matrices_)
        s_np = np.reshape(s_np, s_tf_val.shape)
        CompareSingularValues(self, s_np, s_tf_val, tol)
        if compute_uv_:
            CompareSingularVectors(self, u_np, u_tf_val, min(shape_[-2:]), tol)
            CompareSingularVectors(self, np.conj(np.swapaxes(v_np, -2, -1)), v_tf_val, min(shape_[-2:]), tol)
            CheckApproximation(self, x_np, u_tf_val, s_tf_val, v_tf_val, full_matrices_, tol)
            CheckUnitary(self, u_tf_val, tol)
            CheckUnitary(self, v_tf_val, tol)
    return Test

def operator_and_matrix(self, shape_info, dtype, use_placeholder, ensure_self_adjoint_and_pd=False):
    shape = shape_info.shape
    spectrum = _spectrum_for_symmetric_circulant(spectrum_shape=self._shape_to_spectrum_shape(shape), d=1, ensure_self_adjoint_and_pd=ensure_self_adjoint_and_pd, dtype=dtype)
    lin_op_spectrum = spectrum
    if <MASK>:
        lin_op_spectrum = array_ops.placeholder_with_default(spectrum, shape=None)
    operator = linalg.LinearOperatorCirculant(lin_op_spectrum, input_output_dtype=dtype, is_positive_definite=True if ensure_self_adjoint_and_pd else None, is_self_adjoint=True if ensure_self_adjoint_and_pd else None)
    mat = self._spectrum_to_circulant_1d(spectrum, shape, dtype=dtype)
    return (operator, mat)

def setup(self, index_type):
    N = 10 ** 5
    if <MASK>:
        self.idx = pd.MultiIndex.from_product([pd.date_range('1/1/2000', freq='min', periods=N // 2), ['a', 'b']])
    elif index_type == 'DatetimeIndex':
        self.idx = pd.date_range('1/1/2000', freq='min', periods=N)
    elif index_type == 'Int64Index':
        self.idx = pd.Index(range(N), dtype='int64')
    elif index_type == 'PeriodIndex':
        self.idx = pd.period_range('1/1/2000', freq='min', periods=N)
    elif index_type == 'RangeIndex':
        self.idx = pd.RangeIndex(start=0, stop=N)
    elif index_type == 'IntervalIndex':
        self.idx = pd.IntervalIndex.from_arrays(range(N), range(1, N + 1))
    elif index_type == 'TimedeltaIndex':
        self.idx = pd.TimedeltaIndex(range(N))
    elif index_type == 'Float64Index':
        self.idx = pd.Index(range(N), dtype='float64')
    elif index_type == 'UInt64Index':
        self.idx = pd.Index(range(N), dtype='uint64')
    elif index_type == 'CategoricalIndex':
        self.idx = pd.CategoricalIndex(range(N), range(N))
    else:
        raise ValueError
    assert len(self.idx) == N
    self.idx._cache = {}

def format_build_command(compiler: str, sources: str, include_dirs_args: str, definitions_args: str, cflags_args: str, ldflags_args: str, libraries_args: str, libraries_dirs_args: str, passthrough_args: str, output: str) -> str:
    if _IS_WINDOWS:
        cmd = f'{compiler} {include_dirs_args} {definitions_args} {cflags_args} {sources} {passthrough_args} {output}'
        if <MASK>:
            cmd += f' /LD /link {libraries_dirs_args} {libraries_args} {ldflags_args}'
        cmd = normalize_path_separator(cmd)
    else:
        cmd = f'{compiler} {sources} {definitions_args} {cflags_args} {include_dirs_args} {passthrough_args} {output}'
        if self._do_link:
            cmd += f' {ldflags_args} {libraries_args} {libraries_dirs_args}'
    return cmd

def at_least_x_gpu(x):
    if <MASK>:
        return True
    if TEST_HPU and torch.hpu.device_count() >= x:
        return True
    if TEST_XPU and torch.xpu.device_count() >= x:
        return True
    return False

def __init__(self, input_shape=None, batch_size=None, dtype=None, input_tensor=None, sparse=None, name=None, ragged=None, type_spec=None, **kwargs):
    self._init_input_shape = input_shape
    self._init_batch_size = batch_size
    self._init_dtype = dtype
    self._init_sparse = sparse
    self._init_ragged = ragged
    self._init_type_spec = type_spec
    strategy = distribute_lib.get_strategy()
    if strategy and batch_size is not None and distributed_training_utils.global_batch_size_supported(strategy):
        if batch_size % strategy.num_replicas_in_sync != 0:
            raise ValueError('The `batch_size` argument ({}) must be divisible by the number of replicas ({})'.format(batch_size, strategy.num_replicas_in_sync))
        batch_size = batch_size // strategy.num_replicas_in_sync
    if 'batch_input_shape' in kwargs:
        batch_input_shape = kwargs.pop('batch_input_shape')
        if input_shape and batch_input_shape:
            raise ValueError('Only provide the input_shape OR batch_input_shape argument to InputLayer, not both at the same time.')
        if batch_input_shape:
            batch_size = batch_input_shape[0]
            input_shape = batch_input_shape[1:]
    if kwargs:
        raise ValueError('Unrecognized keyword arguments:', kwargs.keys())
    if <MASK>:
        raise ValueError('Cannot set both sparse and ragged to True in a Keras input.')
    if not name:
        prefix = 'input'
        name = prefix + '_' + str(backend.get_uid(prefix))
    if not dtype:
        if input_tensor is None:
            dtype = backend.floatx()
        else:
            dtype = backend.dtype(input_tensor)
    elif input_tensor is not None and input_tensor.dtype != dtype:
        raise ValueError('`input_tensor.dtype` differs from `dtype`: %s vs. %s' % (input_tensor.dtype, dtype))
    super(InputLayer, self).__init__(dtype=dtype, name=name)
    self.built = True
    self.sparse = True if sparse else False
    self.ragged = True if ragged else False
    self.batch_size = batch_size
    self.supports_masking = True
    if isinstance(input_shape, tensor_shape.TensorShape):
        input_shape = tuple(input_shape.as_list())
    elif isinstance(input_shape, int):
        input_shape = (input_shape,)
    if type_spec is not None:
        args_that_must_be_none = [('(input_)shape', self._init_input_shape), ('batch_size', self._init_batch_size), ('dtype', self._init_dtype), ('input_tensor', input_tensor), ('sparse', self._init_sparse), ('ragged', self._init_ragged)]
        for (arg_name, arg) in args_that_must_be_none:
            _assert_other_arg_none(arg_name, arg)
        if not ops.executing_eagerly_outside_functions():
            raise ValueError('Creating Keras inputs from a type_spec is only supported when eager execution is enabled.')
        input_tensor = keras_tensor.keras_tensor_from_type_spec(type_spec)
        if isinstance(input_tensor, keras_tensor.SparseKerasTensor):
            self.sparse = True
        if isinstance(input_tensor, keras_tensor.RaggedKerasTensor):
            self.ragged = True
        self.is_placeholder = True
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    elif input_tensor is None:
        if input_shape is not None:
            batch_input_shape = (batch_size,) + tuple(input_shape)
        else:
            batch_input_shape = None
        graph = backend.get_graph()
        with graph.as_default():
            input_tensor = backend.placeholder(shape=batch_input_shape, dtype=dtype, name=self.name, sparse=sparse, ragged=ragged)
        self.is_placeholder = True
        self._batch_input_shape = batch_input_shape
    else:
        if ops.executing_eagerly_outside_functions():
            if not isinstance(input_tensor, keras_tensor.KerasTensor):
                input_tensor = keras_tensor.keras_tensor_from_tensor(input_tensor)
        elif not tf_utils.is_symbolic_tensor(input_tensor):
            raise ValueError('You should not pass an EagerTensor to `Input`. For example, instead of creating an InputLayer, you should instantiate your model and directly call it on your input.')
        self.is_placeholder = False
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    input_tensor._keras_mask = None
    node_module.Node(layer=self, outputs=input_tensor)
    if isinstance(input_tensor, keras_tensor.KerasTensor) or tf_utils.is_extension_type(input_tensor):
        self._type_spec = input_tensor._type_spec
    else:
        self._type_spec = tensor_spec.TensorSpec(shape=input_tensor.shape, dtype=input_tensor.dtype, name=self.name)

def _infer_fake_from_real_tensor(mode: FakeTensorMode, op: torch._ops.OpOverload, real_out: torch.Tensor) -> torch.Tensor:

    def unsupported(reason: str) -> None:
        raise RuntimeError(f'propagate_real_tensors: we cannot infer a Fake kernel (meta kernel) for operator {op._name} because {reason}. Please use torch.library.register_fake to add a Fake kernel.')
    if real_out.storage_offset() != 0:
        unsupported(f'a return has a non-zero storage offset {real_out.storage_offset()}')
    fake_shape = [torch._library.fake_impl.allocate_size(mode.shape_env) for _ in range(real_out.dim())]
    fake_strides = [-1] * real_out.dim()
    strides = [(s, idx) for (idx, s) in enumerate(real_out.stride())]
    strides.sort(key=lambda x: (x[0], -x[1]))
    expected = 1
    fake_stride = expected
    for (s, idx) in strides:
        if <MASK>:
            unsupported(f'a return was not dense in memory (sizes {real_out.shape} strides {real_out.stride()})')
        fake_strides[idx] = fake_stride
        expected = expected * real_out.shape[idx]
        fake_stride = fake_stride * fake_shape[idx]
    with mode:
        return torch.empty_strided(fake_shape, fake_strides, device=real_out.device, dtype=real_out.dtype, layout=real_out.layout)

def _select_tiling_indices(self, fn_list, var_sizes_list, tiling_factor):
    all_index = []
    for (fn, var_sizes) in zip(fn_list, var_sizes_list):
        rw = dependencies.extract_read_writes(fn, *var_sizes)
        all_index += [dep.index for dep in itertools.chain(rw.reads, rw.writes)]
    contig_vars = OrderedSet[int]()
    contig_vars_list = []
    non_contig_stride_const = OrderedSet[int]()
    non_contig_stride_other = OrderedSet[int]()
    for index in all_index:
        for var in index.free_symbols:
            if not re.search('^d\\d+$', var.name):
                continue
            stride = stride_at_vec_range(index, var, tiling_factor)
            if stride == 0:
                continue
            elif stride == 1:
                contig_vars.add(int(var.name[1:]))
                contig_vars_list.append(int(var.name[1:]))
            elif all((symbol_is_type(s, SymT.SIZE) for s in stride.free_symbols)):
                non_contig_stride_const.add(int(var.name[1:]))
            else:
                non_contig_stride_other.add(int(var.name[1:]))
    contig_only = contig_vars - non_contig_stride_const - non_contig_stride_other
    (group, reduction_group) = max(var_sizes_list, key=lambda sizes: len(sizes[1]))
    num_itervars = len(group) + len(reduction_group)
    if len(contig_vars) == 0:
        return [num_itervars - 1]
    if contig_only:
        return sorted(contig_only)[-1:]
    contig_and_const_stride = (contig_vars & non_contig_stride_const) - non_contig_stride_other
    contig_vars_sorted = sorted(contig_vars)
    if <MASK>:
        return contig_vars_sorted
    return sorted(contig_vars_sorted, key=contig_vars_list.count)[-1:]

def _validate_arguments(num_mel_bins, sample_rate, lower_edge_hertz, upper_edge_hertz, dtype):
    """Checks the inputs to linear_to_mel_weight_matrix."""
    if num_mel_bins <= 0:
        raise ValueError('num_mel_bins must be positive. Got: %s' % num_mel_bins)
    if lower_edge_hertz < 0.0:
        raise ValueError('lower_edge_hertz must be non-negative. Got: %s' % lower_edge_hertz)
    if <MASK>:
        raise ValueError('lower_edge_hertz %.1f >= upper_edge_hertz %.1f' % (lower_edge_hertz, upper_edge_hertz))
    if not isinstance(sample_rate, tensor.Tensor):
        if sample_rate <= 0.0:
            raise ValueError('sample_rate must be positive. Got: %s' % sample_rate)
        if upper_edge_hertz > sample_rate / 2:
            raise ValueError('upper_edge_hertz must not be larger than the Nyquist frequency (sample_rate / 2). Got %s for sample_rate: %s' % (upper_edge_hertz, sample_rate))
    if not dtype.is_floating:
        raise ValueError('dtype must be a floating point type. Got: %s' % dtype)

def handle(self, **options):
    db = options['database']
    include_stale_apps = options['include_stale_apps']
    interactive = options['interactive']
    verbosity = options['verbosity']
    if not router.allow_migrate_model(db, ContentType):
        return
    ContentType.objects.clear_cache()
    apps_content_types = itertools.groupby(ContentType.objects.using(db).order_by('app_label', 'model'), lambda obj: obj.app_label)
    for (app_label, content_types) in apps_content_types:
        if not include_stale_apps and app_label not in apps.app_configs:
            continue
        to_remove = [ct for ct in content_types if ct.model_class() is None]
        using = router.db_for_write(ContentType)
        if to_remove:
            if interactive:
                ct_info = []
                for ct in to_remove:
                    ct_info.append('    - Content type for %s.%s' % (ct.app_label, ct.model))
                    collector = Collector(using=using, origin=ct, force_collection=True)
                    collector.collect([ct])
                    for (obj_type, objs) in collector.data.items():
                        if objs != {ct}:
                            ct_info.append('    - %s %s object(s)' % (len(objs), obj_type._meta.label))
                content_type_display = '\n'.join(ct_info)
                self.stdout.write(f"Some content types in your database are stale and can be deleted.\nAny objects that depend on these content types will also be deleted.\nThe content types and dependent objects that would be deleted are:\n\n{content_type_display}\n\nThis list doesn't include any cascade deletions to data outside of Django\nmodels (uncommon).\n\nAre you sure you want to delete these content types?\nIf you're unsure, answer 'no'.")
                ok_to_delete = input("Type 'yes' to continue, or 'no' to cancel: ")
            else:
                ok_to_delete = 'yes'
            if ok_to_delete == 'yes':
                for ct in to_remove:
                    if <MASK>:
                        self.stdout.write("Deleting stale content type '%s | %s'" % (ct.app_label, ct.model))
                    ct.delete()
            elif verbosity >= 2:
                self.stdout.write('Stale content types remain.')

def _validate_global_plan(global_plan: list[SavePlan], metadata: Metadata) -> bool:
    all_good = True
    for (key, value) in metadata.state_dict_metadata.items():
        if isinstance(value, BytesStorageMetadata):
            continue
        if len(value.size) == 0:
            continue
        chunks_volume = 0
        for (chunk_idx, chunk0) in enumerate(value.chunks):
            if <MASK>:
                logger.warning('\n                        key:%s has out of bounds chunk:\n                        tensor-size:%s chunk: %s\n                    ', key, value.size, chunk0)
                all_good = False
            chunks_volume += reduce(operator.mul, chunk0.sizes, 1)
            for chunk1 in value.chunks[chunk_idx + 1:]:
                if _check_box_overlap(chunk0, chunk1):
                    logger.warning('key:%s has overlapping chunks: %s %s', key, chunk0, chunk1)
                    all_good = False
        tensor_volume = reduce(operator.mul, value.size, 1)
        if len(global_plan) > 1 and chunks_volume != tensor_volume:
            logger.warning('\n                    key:%s invalid fill tensor-volume:\n                    %s chunks-volume: %s\n                ', key, tensor_volume, chunks_volume)
            all_good = False
    return all_good

def _fit(vander_f, x, y, deg, rcond=None, full=False, w=None):
    """
    Helper function used to implement the ``<type>fit`` functions.

    Parameters
    ----------
    vander_f : function(array_like, int) -> ndarray
        The 1d vander function, such as ``polyvander``
    c1, c2
        See the ``<type>fit`` functions for more detail
    """
    x = np.asarray(x) + 0.0
    y = np.asarray(y) + 0.0
    deg = np.asarray(deg)
    if deg.ndim > 1 or deg.dtype.kind not in 'iu' or deg.size == 0:
        raise TypeError('deg must be an int or non-empty 1-D array of int')
    if deg.min() < 0:
        raise ValueError('expected deg >= 0')
    if x.ndim != 1:
        raise TypeError('expected 1D vector for x')
    if x.size == 0:
        raise TypeError('expected non-empty vector for x')
    if <MASK>:
        raise TypeError('expected 1D or 2D array for y')
    if len(x) != len(y):
        raise TypeError('expected x and y to have same length')
    if deg.ndim == 0:
        lmax = deg
        order = lmax + 1
        van = vander_f(x, lmax)
    else:
        deg = np.sort(deg)
        lmax = deg[-1]
        order = len(deg)
        van = vander_f(x, lmax)[:, deg]
    lhs = van.T
    rhs = y.T
    if w is not None:
        w = np.asarray(w) + 0.0
        if w.ndim != 1:
            raise TypeError('expected 1D vector for w')
        if len(x) != len(w):
            raise TypeError('expected x and w to have same length')
        lhs = lhs * w
        rhs = rhs * w
    if rcond is None:
        rcond = len(x) * np.finfo(x.dtype).eps
    if issubclass(lhs.dtype.type, np.complexfloating):
        scl = np.sqrt((np.square(lhs.real) + np.square(lhs.imag)).sum(1))
    else:
        scl = np.sqrt(np.square(lhs).sum(1))
    scl[scl == 0] = 1
    (c, resids, rank, s) = np.linalg.lstsq(lhs.T / scl, rhs.T, rcond)
    c = (c.T / scl).T
    if deg.ndim > 0:
        if c.ndim == 2:
            cc = np.zeros((lmax + 1, c.shape[1]), dtype=c.dtype)
        else:
            cc = np.zeros(lmax + 1, dtype=c.dtype)
        cc[deg] = c
        c = cc
    if rank != order and (not full):
        msg = 'The fit may be poorly conditioned'
        warnings.warn(msg, RankWarning, stacklevel=2)
    if full:
        return (c, [resids, rank, s, rcond])
    else:
        return c

def _interpolate_scipy_wrapper(x: np.ndarray, y: np.ndarray, new_x: np.ndarray, method: str, fill_value=None, bounds_error: bool=False, order=None, **kwargs):
    """
    Passed off to scipy.interpolate.interp1d. method is scipy's kind.
    Returns an array interpolated at new_x.  Add any new methods to
    the list in _clean_interp_method.
    """
    extra = f'{method} interpolation requires SciPy.'
    import_optional_dependency('scipy', extra=extra)
    from scipy import interpolate
    new_x = np.asarray(new_x)
    alt_methods: dict[str, Callable[..., np.ndarray]] = {'barycentric': interpolate.barycentric_interpolate, 'krogh': interpolate.krogh_interpolate, 'from_derivatives': _from_derivatives, 'piecewise_polynomial': _from_derivatives, 'cubicspline': _cubicspline_interpolate, 'akima': _akima_interpolate, 'pchip': interpolate.pchip_interpolate}
    interp1d_methods = ['nearest', 'zero', 'slinear', 'quadratic', 'cubic', 'polynomial']
    terp: Callable[..., np.ndarray] | None
    if method in interp1d_methods:
        if method == 'polynomial':
            kind = order
        else:
            kind = method
        terp = interpolate.interp1d(x, y, kind=kind, fill_value=fill_value, bounds_error=bounds_error)
        new_y = terp(new_x)
    elif method == 'spline':
        if isna(order) or order <= 0:
            raise ValueError(f'order needs to be specified and greater than 0; got order: {order}')
        terp = interpolate.UnivariateSpline(x, y, k=order, **kwargs)
        new_y = terp(new_x)
    else:
        if not x.flags.writeable:
            x = x.copy()
        if not y.flags.writeable:
            y = y.copy()
        if not new_x.flags.writeable:
            new_x = new_x.copy()
        terp = alt_methods.get(method, None)
        if <MASK>:
            raise ValueError(f'Can not interpolate with method={method}.')
        kwargs.pop('downcast', None)
        new_y = terp(x, y, new_x, **kwargs)
    return new_y

def restore_nodes(save_path, nodes_to_restore):
    """Restores nodes from a dict.

  Requires that the `Trackable` Python object has been bound to an object
  ID in the checkpoint.

  Args:
    save_path: a string represents path to the checkpoint.
    nodes_to_restore: a dict maps `node_id` to `trackable` to be restored.
  """
    if save_path is None:
        raise ValueError('save_path cannot be empty.')
    if <MASK>:
        raise ValueError('Expecting a dictionary of node_id to Trackable for nodes_to_restore.')
    ckpt_view = checkpoint_view.CheckpointView(save_path)
    ckpt_view_descendants = ckpt_view.descendants()
    for (node_id, trackable) in nodes_to_restore.items():
        if node_id not in ckpt_view_descendants or ckpt_view._object_graph_proto.nodes[node_id] is None:
            raise ValueError(f'The expected node_id: {node_id} to Trackable {trackable} to restore does not exist in the checkpoint.')
        if trackable is None or not isinstance(trackable, base.Trackable):
            raise ValueError(f'Expecting a valid Trackable to node_id: {node_id} but got trackable: {trackable}.')
    serialized_tensors = object_identity.ObjectIdentityDictionary()
    for (node_id, current_trackable) in nodes_to_restore.items():
        ckpt_contains_serialized_tensors = ckpt_view._object_graph_proto.nodes[node_id].attributes
        node = ckpt_view._object_graph_proto.nodes[node_id]
        trackable_has_serialize_to_tensor = saveable_object_util.trackable_has_serialize_to_tensor(current_trackable)
        if not trackable_has_serialize_to_tensor:
            if not node.attributes:
                if saveable_object_util.saveable_objects_from_trackable(current_trackable):
                    raise ValueError(f'Trackable {current_trackable} expects checkpointed values but checkpoint does not contain serialized tensors for node_id: {node_id}.')
                else:
                    continue
            object_names = object_identity.ObjectIdentityDictionary()
            object_names[current_trackable] = trackable_utils.extract_object_name(node.attributes[0].checkpoint_key)
            (checkpoint_factory_map, _) = save_util_v1.get_checkpoint_factories_and_keys(object_names, None)
            saveable_objects = save_util_v1.generate_saveable_objects(checkpoint_factory_map)[0]
            if len(node.attributes) != len(saveable_objects):
                raise ValueError(f'Size for saveable_objects for Trackable: {len(saveable_objects)} did not match the size for serialized_tensors for checkpoint: {len(node.attributes)}.')
            current_trackable = saveable_object_util.SaveableCompatibilityConverter(current_trackable, saveable_objects)
        serialized_tensors[current_trackable] = current_trackable._serialize_to_tensors()
        trackable_expects_ckpted_value = bool(serialized_tensors[current_trackable])
        if trackable_expects_ckpted_value and (not ckpt_contains_serialized_tensors):
            raise ValueError(f'Trackable {current_trackable} expects checkpointed values but checkpoint does not contain serialized tensors for node_id: {node_id}.')
        if not trackable_expects_ckpted_value and ckpt_contains_serialized_tensors:
            raise ValueError(f'Trackable {current_trackable} does not expect checkpointed values but checkpoint contains serialized tensors: {ckpt_contains_serialized_tensors} for node_id: {node_id}.')
        if len(node.attributes) != len(serialized_tensors[current_trackable]):
            raise ValueError(f'Size for serialized_tensors for Trackable: {len(serialized_tensors[current_trackable])} did not match size for serialized_tensors for checkpoint: {len(node.attributes)}.')
        if not trackable_has_serialize_to_tensor:
            functional_saver.MultiDeviceSaver(serialized_tensors).restore(save_path)
        else:
            serialized_tensors_renamed = object_identity.ObjectIdentityDictionary()
            serialized_tensors_renamed[current_trackable] = {}
            for attribute in node.attributes:
                name = attribute.name
                checkpoint_key = attribute.checkpoint_key
                serialized_tensors_renamed[current_trackable][checkpoint_key] = serialized_tensors[current_trackable][name]
            functional_saver.MultiDeviceSaver(serialized_tensors_renamed).restore(save_path)

