def wrap_to_fake_tensor_and_record(e, tx, *, source: Optional[Source], is_tensor: bool, parent_context=None):
    if type(e) in (torch.Tensor, torch.nn.Parameter, FakeTensor) or isinstance(e, torch.Tensor) or is_traceable_wrapper_subclass(e):
        assert source is not None
        (static_shapes, _reason) = tensor_always_has_static_shape(e, is_tensor, tensor_source=source)
        if not parent_context:
            symbolic_context = _automatic_dynamic(e, tx, source, static_shapes)
        else:
            assert isinstance(source, AttrSource)
            inner_context_name = source.member
            symbolic_context = parent_context.inner_contexts[inner_context_name]
        log.debug('wrap_to_fake %s %s %s %s', source.name(), tuple(e.shape), symbolic_context, type(e))
        with enable_python_dispatcher():
            fake_e = wrap_fake_exception(lambda : tx.fake_mode.from_tensor(e, source=source, symbolic_context=symbolic_context))
        if source is not None and isinstance(fake_e, FakeTensor) and ((sym_val := fake_e.item_memo) is not None):
            tx.output.tracked_fakes.append(TrackedFake(sym_val, CallMethodItemSource(source), symbolic_context))
        if is_traceable_wrapper_subclass(fake_e):
            (attrs, _) = fake_e.__tensor_flatten__()
            for attr in attrs:
                fake_inner = getattr(fake_e, attr)
                inner = getattr(e, attr)
                inner_source = AttrSource(source, attr)
                wrap_to_fake_tensor_and_record(inner, tx, source=inner_source, is_tensor=isinstance(fake_inner, torch.Tensor), parent_context=symbolic_context)
        tx.output.tracing_context.tensor_to_context[e] = symbolic_context
        if is_sparse_any(fake_e):
            values = fake_e._values() if fake_e.is_sparse else fake_e.values()
            tx.output.input_source_to_sizes_strides[source] = {'size': fake_e.size(), 'stride': (1,) * fake_e.ndim, 'values_size': values.size(), 'values_stride': values.stride()}
        else:
            tx.output.input_source_to_sizes_strides[source] = {'size': fake_e.size(), 'stride': fake_e.stride()}
        if <MASK>:
            tx.output.tracked_fakes.append(TrackedFake(fake_e, source, symbolic_context))
            tx.output.tracked_fakes_id_to_source[id(e)].append(source)
        return fake_e
    else:
        return e

def run_node(tracer: Any, node: torch.fx.Node, args: Any, kwargs: Any, nnmodule: Any) -> Any:
    """
    Runs a given node, with the given args and kwargs.

    Behavior is dictated by a node's op.

    run_node is useful for extracting real values out of nodes.
    See get_real_value for more info on common usage.

    Note: The tracer arg is only used for 'get_attr' ops
    Note: The nnmodule arg is only used for 'call_module' ops

    Nodes that are not call_function, call_method, call_module, or get_attr will
    raise an AssertionError.
    """
    op = node.op
    with set_current_node(node):

        def make_error_message(e: Any) -> str:
            return f'Dynamo failed to run FX node with fake tensors: {op} {node.target}(*{args}, **{kwargs}): got ' + repr(e)
        from .exc import Unsupported
        try:
            if op == 'call_function':
                return node.target(*args, **kwargs)
            elif op == 'call_method':
                if <MASK>:
                    from .exc import unimplemented_v2
                    unimplemented_v2(gb_type='Missing attribute when running call_method node', context='', explanation=make_error_message('attribute not defined'), hints=[])
                return getattr(args[0], node.target)(*args[1:], **kwargs)
            elif op == 'call_module':
                assert nnmodule is not None
                return nnmodule(*args, **kwargs)
            elif op == 'get_attr':
                return tracer.output_graph.get_submodule(node.target)
            elif op == 'placeholder':
                assert 'example_value' in node.meta
                return node.meta['example_value']
        except (NotImplementedError, UnsupportedFakeTensorException) as e:
            from .exc import unimplemented_v2
            hints = []
            if isinstance(e, NotImplementedError):
                hints = ['If the op is a PyTorch op, please file an issue to PyTorch.']
            unimplemented_v2(gb_type='NotImplementedError/UnsupportedFakeTensorException when running FX node', context='', explanation=make_error_message(e), hints=hints, from_exc=e)
        except Unsupported:
            raise
        except Exception as e:
            raise RuntimeError(make_error_message(e)).with_traceback(e.__traceback__) from e
    raise AssertionError(op)

def to_python(self, value):
    if value is None:
        return value
    if isinstance(value, datetime.datetime):
        if <MASK>:
            default_timezone = timezone.get_default_timezone()
            value = timezone.make_naive(value, default_timezone)
        return value.date()
    if isinstance(value, datetime.date):
        return value
    try:
        parsed = parse_date(value)
        if parsed is not None:
            return parsed
    except ValueError:
        raise exceptions.ValidationError(self.error_messages['invalid_date'], code='invalid_date', params={'value': value})
    raise exceptions.ValidationError(self.error_messages['invalid'], code='invalid', params={'value': value})

def astype(self, dtype, copy: bool=True):
    dtype = pandas_dtype(dtype)
    if <MASK>:
        if self.dtype.kind == 'M':
            self = cast('DatetimeArray', self)
            i8data = self.asi8
            converted = ints_to_pydatetime(i8data, tz=self.tz, box='timestamp', reso=self._creso)
            return converted
        elif self.dtype.kind == 'm':
            return ints_to_pytimedelta(self._ndarray, box=True)
        return self._box_values(self.asi8.ravel()).reshape(self.shape)
    elif is_string_dtype(dtype):
        if isinstance(dtype, ExtensionDtype):
            arr_object = self._format_native_types(na_rep=dtype.na_value)
            cls = dtype.construct_array_type()
            return cls._from_sequence(arr_object, dtype=dtype, copy=False)
        else:
            return self._format_native_types()
    elif isinstance(dtype, ExtensionDtype):
        return super().astype(dtype, copy=copy)
    elif dtype.kind in 'iu':
        values = self.asi8
        if dtype != np.int64:
            raise TypeError(f"Converting from {self.dtype} to {dtype} is not supported. Do obj.astype('int64').astype(dtype) instead")
        if copy:
            values = values.copy()
        return values
    elif dtype.kind in 'mM' and self.dtype != dtype or dtype.kind == 'f':
        msg = f'Cannot cast {type(self).__name__} to dtype {dtype}'
        raise TypeError(msg)
    else:
        return np.asarray(self, dtype=dtype)

def _add_batched_ragged_partition(rt, partition, tensor_dict, feature_key, validate, outer_splits=None):
    """Adds a batched ragged partition tensor to a batched ragged tensor.

  Args:
    rt: A RaggedTensor with shape [batch_size, ...].
    partition: The partition configuration object.  Specifies the key that
      should be used to look up the partition tensor (unless partition is a
      RaggedFeature.UniformRowLength, in which case there is no partition
      tensor).  The specified tensor must have shape [batch_size, ...].
    tensor_dict: The dictionary mapping keys to tensors.
    feature_key: The name of the feature being parsed (for error messages).
    validate: Whether to validate that the values form a valid RaggedTensor.
    outer_splits: If not None, then we have two batch dimensions, and this
      is the row-splits for the collapsed batch dimension.  Every partition
      tensor must have an outer row_splits that matches this value.

  Returns:
    A new RaggedTensor where each batch item `rt[i]` has been partitioned
    using the `partition_t[i]`.
  """
    if <MASK>:
        if rt.ragged_rank > 1:
            length = ops.convert_to_tensor(partition.length, rt.row_splits.dtype)
            return ragged_tensor.RaggedTensor.from_row_splits(ragged_tensor.RaggedTensor.from_uniform_row_length(rt.values, length, validate=validate), rt.row_splits // length, validate=validate)
        else:
            reshaped_vals = array_ops.reshape(rt.values, array_ops.concat([[-1, partition.length], array_ops.shape(rt.values)[1:]], axis=0))
            return ragged_tensor.RaggedTensor.from_row_splits(reshaped_vals, rt.row_splits // partition.length, validate=validate)
    partition_t = tensor_dict[partition.key]
    if partition_t.values.dtype != rt.row_splits.dtype:
        partition_t = math_ops.cast(partition_t, rt.row_splits.dtype)
    checks = []
    if outer_splits is not None:
        if validate:
            checks.append(check_ops.assert_equal(outer_splits, partition_t.row_splits, message='Feature %s: values and partitions are not aligned' % feature_key))
        partition_t = partition_t.values
    with ops.control_dependencies(checks):
        if isinstance(partition, (RaggedFeature.RowSplits, RaggedFeature.RowLimits)):
            if isinstance(partition, RaggedFeature.RowSplits):
                partition_t = partition_t[:, 1:]
            adjusted_limits = partition_t.values + array_ops.repeat(rt.row_starts(), partition_t.row_lengths())
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_limits(rt.values, adjusted_limits, validate=validate))
        elif isinstance(partition, RaggedFeature.RowStarts):
            adjusted_starts = partition_t.values + array_ops.repeat(rt.row_starts(), partition_t.row_lengths())
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_starts(rt.values, adjusted_starts, validate=validate))
        elif isinstance(partition, RaggedFeature.RowLengths):
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_lengths(rt.values, partition_t.values, validate=validate))
        elif isinstance(partition, RaggedFeature.ValueRowIds):
            nrows = math_ops.maximum(ragged_math_ops.reduce_max(partition_t + 1, axis=1), 0)
            adjusted_rowids = partition_t.values + array_ops.repeat(math_ops.cumsum(nrows, exclusive=True), partition_t.row_lengths())
            return ragged_tensor.RaggedTensor.from_row_lengths(ragged_tensor.RaggedTensor.from_value_rowids(rt.values, adjusted_rowids, validate=validate), nrows, validate=validate)
        raise ValueError(f'Unhandled partition type {partition!r}')

@dist_init(clean_shutdown=False)
def test_multiple_backward_with_errors(self):
    initialize_pg(self.file_init_method, self.rank, self.world_size)
    t1 = torch.rand((3, 3), requires_grad=True)
    t2 = torch.rand((3, 3), requires_grad=True)
    with dist_autograd.context() as context_id:
        loss = rpc.rpc_sync(f'worker{self._next_rank()}', DistAutogradTest._python_udf_with_backward_error, args=(t1, t2)).sum()
        try:
            for i in range(100):
                if i < 50:
                    with self.assertRaisesRegex(RuntimeError, 'Simulate error on backward pass'):
                        dist_autograd.backward(context_id, [loss], retain_graph=True)
                elif <MASK>:
                    dist_autograd.backward(context_id, [loss], retain_graph=True)
                else:
                    dist.barrier()
                    SimulateBackwardError._simulate_error = False
                    dist.barrier()
        finally:
            dist.barrier()
            SimulateBackwardError._simulate_error = True

