def draft_export(mod: torch.nn.Module, args: tuple[Any, ...], kwargs: Optional[Mapping[str, Any]]=None, *, dynamic_shapes: Optional[Union[dict[str, Any], tuple[Any], list[Any]]]=None, preserve_module_call_signature: tuple[str, ...]=(), strict: bool=False, pre_dispatch: bool=True, prefer_deferred_runtime_asserts_over_guards: bool=False) -> ExportedProgram:
    start_time = time.time()
    kwargs = kwargs or {}
    dynamic_shapes = dynamic_shapes or {}
    constraint_violation_msg = None
    capture_structured_log = CaptureStructuredTrace()
    with torch._functorch.config.patch(fake_tensor_propagate_real_tensors=True, generate_fake_kernels_from_real_mismatches=True), capture_structured_log:
        try:
            new_shapes = None
            ep = _export(mod, args, kwargs, dynamic_shapes=dynamic_shapes, strict=strict, pre_dispatch=pre_dispatch, preserve_module_call_signature=preserve_module_call_signature, prefer_deferred_runtime_asserts_over_guards=prefer_deferred_runtime_asserts_over_guards)
        except Exception as exc:
            if isinstance(exc, UserError) and exc.error_type == UserErrorType.CONSTRAINT_VIOLATION:
                constraint_violation_msg = exc.msg

                def convert_dim_to_auto(dim: Any) -> Any:
                    if isinstance(dim, Dim):
                        return Dim.AUTO(min=dim.min, max=dim.max)
                    elif isinstance(dim, _DimHint) and dim.type == _DimHintType.DYNAMIC:
                        return Dim.AUTO(min=dim.min, max=dim.max)
                    return dim
                new_shapes = pytree.tree_map(convert_dim_to_auto, dynamic_shapes)
                ep = _export(mod, args, kwargs, dynamic_shapes=new_shapes, strict=strict, pre_dispatch=pre_dispatch, preserve_module_call_signature=preserve_module_call_signature, prefer_deferred_runtime_asserts_over_guards=prefer_deferred_runtime_asserts_over_guards)
            else:
                log_draft_export_usage(error=True, export_time=time.time() - start_time, strict=strict, message=str(exc), type=f'{type(exc).__name__}.{type(exc).__qualname__}')
                raise exc
        torch._logging.dtrace_structured('exported_program', payload_fn=lambda : str(ep))
        str_to_filename: dict[int, str] = {}
        failures: list[FailureReport] = []
        incorrect_custom_ops: set[str] = set()
        expressions_created: dict[int, dict[str, Any]] = {}
        for (log_name, log_contents) in capture_structured_log.log_record.logs:
            failure_type = None
            if log_name == 'str':
                str_to_filename[log_contents[1]] = log_contents[0]
                continue
            elif log_name == 'propagate_real_tensors_provenance':
                log_contents['occurrences'] = capture_structured_log.log_record.get_log_count((log_name, log_contents))
                failure_type = FailureType.DATA_DEPENDENT_ERROR
            elif log_name == 'guard_added':
                if new_shapes is None:
                    continue
                failure_type = FailureType.GUARD_ADDED
                log_contents['new_dynamic_shapes'] = new_shapes
            elif <MASK>:
                failure_type = FailureType.MISSING_FAKE_KERNEL
                incorrect_custom_ops.add(log_contents['op'])
            elif log_name == 'mismatched_fake_kernel':
                failure_type = FailureType.MISMATCHED_FAKE_KERNEL
                incorrect_custom_ops.add(log_contents['op'])
            else:
                continue
            assert failure_type is not None
            failures.append(FailureReport(failure_type, log_contents))
        for (k, v) in capture_structured_log.expression_created_logs.items():
            if v.visited:
                expressions_created[k] = v.record
        op_profiles = get_op_profiles(ep.graph_module, incorrect_custom_ops)
        report = DraftExportReport(failures, str_to_filename, expressions_created, op_profiles)
        insert_custom_op_guards(ep.graph_module, incorrect_custom_ops)
    ep._report = report
    if not report.successful():
        log_filename = capture_structured_log.stream.name
        warning_msg = f'\n###################################################################################################\nWARNING: {len(report.failures)} issue(s) found during export, and it was not able to soundly produce a graph.\nTo view the report of failures in an html page, please run the command:\n    `tlparse {log_filename} --export`\nOr, you can view the errors in python by inspecting `print(ep._report)`.\n'
        if len(report.op_profiles) > 0:
            warning_msg += f'\nWhile tracing we found {len(report.op_profiles)} operator(s) which do not have a fake kernel registered.\nIf you intend to retrace the exported graph or run it with fake tensors, please run it under the\nfollowing context manager, which will register a fake kernel for those operators.\n```\nwith torch._library.fake_profile.unsafe_generate_fake_kernels(ep._report.op_profiles):\n    # run with fake tensors\n```\n'
        warning_msg += '#################################################################################################'
        log.warning(warning_msg)
    else:
        log.info('\n##############################################################################################\nCongratuations: No issues are found during export, and it was able to soundly produce a graph.\nYou can now change back to torch.export.export()\n##############################################################################################\n    ')
    log_draft_export_usage(error=False, export_time=time.time() - start_time, strict=strict, constraint_violations=constraint_violation_msg, report=ep._report, **get_ep_stats(ep))
    return ep

def default_expr(d: str, t: Type, *, symint: bool) -> str:
    if d == 'None' and str(t) == 'Tensor?':
        return '{}'
    if isinstance(t, BaseType) and t.name is BaseTy.str:
        if len(d) >= 2 and d[0] == "'" and (d[-1] == "'"):
            s = ''
            i = 1
            while i + 1 < len(d):
                if d[i] != '\\':
                    if d[i] == '"':
                        s += '\\"'
                    else:
                        s += d[i]
                    i += 1
                else:
                    if d[i + 1] == "'":
                        s += "'"
                    else:
                        s += d[i:i + 2]
                    i += 2
            return f'"{s}"'
    if isinstance(t, OptionalType):
        if d == 'None':
            return '::std::nullopt'
        return default_expr(d, t.elem, symint=symint)
    if <MASK>:
        if d.startswith('[') and d.endswith(']'):
            return '{' + d[1:-1] + '}'
        elif symint and d.isdigit() and (str(t.elem) == 'SymInt'):
            return f'c10::SymInt({d})'
        elif t.size is None:
            raise ValueError(f"Expected a list default '[...]' but found: '{d}'")
    return JIT_TO_CPP_DEFAULT.get(d, d)

def _ogrinspect(data_source, model_name, geom_name='geom', layer_key=0, srid=None, multi_geom=False, name_field=None, imports=True, decimal=False, blank=False, null=False):
    """
    Helper routine for `ogrinspect` that generates GeoDjango models
    corresponding to the given data source. See the `ogrinspect` docstring for
    more details.
    """
    if isinstance(data_source, str):
        data_source = DataSource(data_source)
    elif isinstance(data_source, DataSource):
        pass
    else:
        raise TypeError('Data source parameter must be a string or a DataSource object.')
    layer = data_source[layer_key]
    ogr_fields = layer.fields

    def process_kwarg(kwarg):
        if isinstance(kwarg, (list, tuple)):
            return [s.lower() for s in kwarg]
        elif kwarg:
            return [s.lower() for s in ogr_fields]
        else:
            return []
    null_fields = process_kwarg(null)
    blank_fields = process_kwarg(blank)
    decimal_fields = process_kwarg(decimal)

    def get_kwargs_str(field_name):
        kwlist = []
        if field_name.lower() in null_fields:
            kwlist.append('null=True')
        if field_name.lower() in blank_fields:
            kwlist.append('blank=True')
        if kwlist:
            return ', ' + ', '.join(kwlist)
        else:
            return ''
    if imports:
        yield '# This is an auto-generated Django model module created by ogrinspect.'
        yield 'from django.contrib.gis.db import models'
        yield ''
        yield ''
    yield ('class %s(models.Model):' % model_name)
    for (field_name, width, precision, field_type) in zip(ogr_fields, layer.field_widths, layer.field_precisions, layer.field_types):
        mfield = field_name.lower()
        if mfield[-1:] == '_':
            mfield += 'field'
        kwargs_str = get_kwargs_str(field_name)
        if field_type is OFTReal:
            if field_name.lower() in decimal_fields:
                yield ('    %s = models.DecimalField(max_digits=%d, decimal_places=%d%s)' % (mfield, width, precision, kwargs_str))
            else:
                yield ('    %s = models.FloatField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTInteger:
            yield ('    %s = models.IntegerField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTInteger64:
            yield ('    %s = models.BigIntegerField(%s)' % (mfield, kwargs_str[2:]))
        elif <MASK>:
            yield ('    %s = models.CharField(max_length=%s%s)' % (mfield, width, kwargs_str))
        elif field_type is OFTDate:
            yield ('    %s = models.DateField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTDateTime:
            yield ('    %s = models.DateTimeField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTTime:
            yield ('    %s = models.TimeField(%s)' % (mfield, kwargs_str[2:]))
        else:
            raise TypeError('Unknown field type %s in %s' % (field_type, mfield))
    gtype = layer.geom_type
    if multi_geom:
        gtype.to_multi()
    geom_field = gtype.django
    if srid is None:
        if layer.srs is None:
            srid_str = 'srid=-1'
        else:
            srid = layer.srs.srid
            if srid is None:
                srid_str = 'srid=-1'
            elif srid == 4326:
                srid_str = ''
            else:
                srid_str = 'srid=%s' % srid
    else:
        srid_str = 'srid=%s' % srid
    yield ('    %s = models.%s(%s)' % (geom_name, geom_field, srid_str))
    if name_field:
        yield ''
        yield ('    def __str__(self): return self.%s' % name_field)

def process_messages(self, obj):
    if isinstance(obj, list) and obj:
        if obj[0] == MessageEncoder.message_key:
            if <MASK>:
                obj[3] = mark_safe(obj[3])
            return Message(*obj[2:])
        return [self.process_messages(item) for item in obj]
    if isinstance(obj, dict):
        return {key: self.process_messages(value) for (key, value) in obj.items()}
    return obj

@staticmethod
def _get_base_knot_positions(X, n_knots=10, knots='uniform', sample_weight=None):
    """Calculate base knot positions for `knots` either "uniform" or "quantile".

        Base knots such that first knot <= feature <= last knot. For the
        B-spline construction with scipy.interpolate.BSpline, 2*degree knots
        beyond the base interval are added.

        Returns
        -------
        knots : ndarray of shape (n_knots, n_features), dtype=np.float64
            Knot positions (points) of base interval.
        """
    if knots == 'quantile':
        percentile_ranks = 100 * np.linspace(start=0, stop=1, num=n_knots, dtype=np.float64)
        if <MASK>:
            knots = np.nanpercentile(X, percentile_ranks, axis=0)
        else:
            knots = np.array([_weighted_percentile(X, sample_weight, percentile_rank) for percentile_rank in percentile_ranks])
    else:
        mask = slice(None, None, 1) if sample_weight is None else sample_weight > 0
        x_min = np.zeros(X.shape[1], dtype=np.float64)
        x_max = np.zeros(X.shape[1], dtype=np.float64)
        for feature_idx in range(X.shape[1]):
            x = X[mask, feature_idx]
            if np.all(np.isnan(x)):
                continue
            else:
                x_min[feature_idx] = np.nanmin(x)
                x_max[feature_idx] = np.nanmax(x)
        knots = np.linspace(start=x_min, stop=x_max, num=n_knots, endpoint=True, dtype=np.float64)
    return knots

def __setstate__(self, state):
    self._sharded_tensor_id = None
    if not distributed_c10d.is_initialized():
        raise RuntimeError('Need to initialize default process group using "init_process_group" before loading ShardedTensor')
    (self._local_shards, self._metadata, pg_state, self._sharding_spec, self._init_rrefs) = state
    from torch.distributed._shard.api import _get_current_process_group
    self._process_group = _get_current_process_group()
    local_rank = distributed_c10d.get_rank(self._process_group)
    if pg_state.local_rank != local_rank:
        raise RuntimeError(f'Local rank at save time was {pg_state.local_rank}, but at load time was {local_rank}')
    global_rank = distributed_c10d.get_rank()
    if pg_state.global_rank != global_rank:
        raise RuntimeError(f'Global rank at save time was {pg_state.global_rank}, but at load time was {global_rank}')
    local_world_size = distributed_c10d.get_world_size(self._process_group)
    if pg_state.local_world_size != local_world_size:
        raise RuntimeError(f'Local world size at save time was {pg_state.local_world_size}, but at load time was {local_world_size}')
    global_world_size = distributed_c10d.get_world_size()
    if <MASK>:
        raise RuntimeError(f'Global world size at save time was {pg_state.global_world_size}, but at load time was {global_world_size}')
    self._post_init()

@final
def _concat_objects(self, values, not_indexed_same: bool=False, is_transform: bool=False):
    from pandas.core.reshape.concat import concat
    if self.group_keys and (not is_transform):
        if self.as_index:
            group_keys = self._grouper.result_index
            group_levels = self._grouper.levels
            group_names = self._grouper.names
            result = concat(values, axis=0, keys=group_keys, levels=group_levels, names=group_names, sort=False)
        else:
            result = concat(values, axis=0)
    elif not not_indexed_same:
        result = concat(values, axis=0)
        ax = self._selected_obj.index
        if self.dropna:
            labels = self._grouper.ids
            mask = labels != -1
            ax = ax[mask]
        if ax.has_duplicates and (not result.axes[0].equals(ax)):
            target = algorithms.unique1d(ax._values)
            (indexer, _) = result.index.get_indexer_non_unique(target)
            result = result.take(indexer, axis=0)
        else:
            result = result.reindex(ax, axis=0)
    else:
        result = concat(values, axis=0)
    if <MASK>:
        name = self.obj.name
    elif is_hashable(self._selection):
        name = self._selection
    else:
        name = None
    if isinstance(result, Series) and name is not None:
        result.name = name
    return result.__finalize__(self.obj, method='groupby')

def _create_global_plan_with_caching(self, all_plans: list[SavePlan]) -> tuple[list[SavePlan], list[SavePlan], Metadata]:
    """
        Create global plan with caching.
        Returns a tuple of global_plan_delta, global_plan, metadata.
        """
    global_plan_delta: list[SavePlan] = []
    if self._cached_plans_key not in SavePlanner._cached_all_plans:
        SavePlanner._cached_all_plans[self._cached_plans_key] = all_plans
        (global_plan, metadata) = self._create_global_plan(all_plans)
        SavePlanner._cached_global_plan[self._cached_plans_key] = global_plan
        SavePlanner._cached_metadata[self._cached_plans_key] = metadata
        return (global_plan, global_plan, metadata)
    if not _contains_usable_plan(all_plans):
        global_plan_delta = [SavePlan([], usable=False)] * len(all_plans)
        global_plan = SavePlanner._cached_global_plan[self._cached_plans_key]
        metadata = SavePlanner._cached_metadata[self._cached_plans_key]
    else:
        merged_plans = _merge_delta_local_plans(SavePlanner._cached_all_plans[self._cached_plans_key], all_plans)
        SavePlanner._cached_all_plans[self._cached_plans_key] = merged_plans
        (global_plan, metadata) = self._create_global_plan(merged_plans)
        if <MASK>:
            for (cached_plan, new_plan) in zip(SavePlanner._cached_global_plan[self._cached_plans_key], global_plan):
                if _compare_save_plans(cached_plan, new_plan):
                    global_plan_delta.append(SavePlan([], usable=False))
                else:
                    global_plan_delta.append(new_plan)
        SavePlanner._cached_global_plan[self._cached_plans_key] = global_plan
        SavePlanner._cached_metadata[self._cached_plans_key] = metadata
    return (global_plan_delta, global_plan, metadata)

@staticmethod
def check_inlineable(func: Any) -> trace_rules.SkipResult:
    if <MASK>:
        unimplemented_v2(gb_type='Inline attempt with __self__', context=str(func), explanation='Attempted to inline a function with the `__self__` attribute. Dynamo is expected to decompose method calls into function calls with a `self` argument.', hints=[])
    if isinstance(func, UserFunctionVariable) and inspect.getattr_static(func.get_function(), '_torchdynamo_disable', False):
        msg = inspect.getattr_static(func.get_function(), '_torchdynamo_disable_msg', None)
        unimplemented_v2(gb_type='Skip inlining `torch.compiler.disable()`d function', context=str(func.get_function()), explanation=f'Skip inlining function {func.get_function()} since it was wrapped with `torch.compiler.disable` (reason: {msg})', hints=['Remove the `torch.compiler.disable` call'])
    result = trace_rules.check_verbose(func, is_inlined_call=True)
    if result.skipped:
        from torch._dynamo.variables.misc import produce_trampoline_autograd_apply
        if hasattr(getattr(func, 'fn', None), '_origin') and func.fn._origin is produce_trampoline_autograd_apply:
            return trace_rules.SkipResult(False, 'allowlist in dynamo known function')
        fn_qualname = func.fn.__qualname__ if hasattr(func, 'fn') else ''
        hints = [f'Avoid calling the function `{fn_qualname}`.']
        if '_dynamo' not in func.get_filename():
            hints += [f'Apply `@torch._dynamo.dont_skip_tracing` to the function `{fn_qualname}` to force tracing into the function. More graph breaks may occur as a result of attempting to trace into the function.', 'Please file an issue to PyTorch.']
        unimplemented_v2(gb_type='Attempted to inline function marked as skipped', context=f'qualname: {fn_qualname}, name: {func.get_name()}, filename: `{func.get_filename()}`, skip reason: {result.reason}', explanation=f'Dynamo developers have intentionally marked that the function `{fn_qualname}` should not be traced.', hints=hints)
    return result

def _get_dummies_1d(data, prefix, prefix_sep: str | Iterable[str] | dict[str, str]='_', dummy_na: bool=False, sparse: bool=False, drop_first: bool=False, dtype: NpDtype | None=None) -> DataFrame:
    from pandas.core.reshape.concat import concat
    (codes, levels) = factorize_from_iterable(Series(data, copy=False))
    if dtype is None and hasattr(data, 'dtype'):
        input_dtype = data.dtype
        if isinstance(input_dtype, CategoricalDtype):
            input_dtype = input_dtype.categories.dtype
        if isinstance(input_dtype, ArrowDtype):
            import pyarrow as pa
            dtype = ArrowDtype(pa.bool_())
        elif isinstance(input_dtype, StringDtype) and input_dtype.na_value is libmissing.NA:
            dtype = pandas_dtype('boolean')
        else:
            dtype = np.dtype(bool)
    elif dtype is None:
        dtype = np.dtype(bool)
    _dtype = pandas_dtype(dtype)
    if is_object_dtype(_dtype):
        raise ValueError('dtype=object is not a valid dtype for get_dummies')

    def get_empty_frame(data) -> DataFrame:
        index: Index | np.ndarray
        if isinstance(data, Series):
            index = data.index
        else:
            index = default_index(len(data))
        return DataFrame(index=index)
    if not dummy_na and len(levels) == 0:
        return get_empty_frame(data)
    codes = codes.copy()
    if dummy_na:
        codes[codes == -1] = len(levels)
        levels = levels.insert(len(levels), np.nan)
    if drop_first and len(levels) == 1:
        return get_empty_frame(data)
    number_of_cols = len(levels)
    if prefix is None:
        dummy_cols = levels
    else:
        dummy_cols = Index([f'{prefix}{prefix_sep}{level}' for level in levels])
    index: Index | None
    if isinstance(data, Series):
        index = data.index
    else:
        index = None
    if <MASK>:
        fill_value: bool | float
        if is_integer_dtype(dtype):
            fill_value = 0
        elif dtype == np.dtype(bool):
            fill_value = False
        else:
            fill_value = 0.0
        sparse_series = []
        N = len(data)
        sp_indices: list[list] = [[] for _ in range(len(dummy_cols))]
        mask = codes != -1
        codes = codes[mask]
        n_idx = np.arange(N)[mask]
        for (ndx, code) in zip(n_idx, codes):
            sp_indices[code].append(ndx)
        if drop_first:
            sp_indices = sp_indices[1:]
            dummy_cols = dummy_cols[1:]
        for (col, ixs) in zip(dummy_cols, sp_indices):
            sarr = SparseArray(np.ones(len(ixs), dtype=dtype), sparse_index=IntIndex(N, ixs), fill_value=fill_value, dtype=dtype)
            sparse_series.append(Series(data=sarr, index=index, name=col, copy=False))
        return concat(sparse_series, axis=1)
    else:
        shape = (len(codes), number_of_cols)
        dummy_dtype: NpDtype
        if isinstance(_dtype, np.dtype):
            dummy_dtype = _dtype
        else:
            dummy_dtype = np.bool_
        dummy_mat = np.zeros(shape=shape, dtype=dummy_dtype, order='F')
        dummy_mat[np.arange(len(codes)), codes] = 1
        if not dummy_na:
            dummy_mat[codes == -1] = 0
        if drop_first:
            dummy_mat = dummy_mat[:, 1:]
            dummy_cols = dummy_cols[1:]
        return DataFrame(dummy_mat, index=index, columns=dummy_cols, dtype=_dtype)

def saved_variables(formula: str, nctypes: list[NamedCType], var_names: tuple[str, ...]) -> tuple[str, tuple[SavedAttribute, ...]]:

    def stride_expr(name: str) -> str:
        assert var_names == (name,), 'Replacement for ".strides()" is currently only supported for single derivatives of the same tensor that ".strides()" is being called on.'
        return f'strides_or_error({name}, "{name}")'
    REPLACEMENTS: list[tuple[str, dict[str, Any]]] = [('{}.sym_sizes\\(\\)', {'suffix': '_sym_sizes', 'nctype': lambda name: NamedCType(name, BaseCType(symIntArrayRefT))}), ('{}->sym_sizes\\(\\)', {'suffix': '_sym_sizes_opt', 'nctype': lambda name: NamedCType(name, OptionalCType(BaseCType(symIntArrayRefT))), 'expr': lambda name: f'{name}.has_value() ? std::optional<c10::SymIntArrayRef>({name}->sym_sizes()) : std::nullopt'}), ('{}.sym_blocksize\\(\\)', {'suffix': '_self_sym_blocksize_opt', 'nctype': lambda name: NamedCType(name, OptionalCType(BaseCType(symIntArrayRefT))), 'expr': lambda name: f'at::sparse_csr::getSymIntBlockSize({name})'}), ('{}.options\\(\\)', {'suffix': '_options', 'nctype': lambda name: NamedCType(name, BaseCType(tensorOptionsT))}), ('zeros_like\\({}\\)', {'suffix': '_info', 'nctype': lambda name: NamedCType(name, BaseCType(typeAndSizeT)), 'expr': lambda name: name, 'res': lambda name: name + '_info.zeros()'}), ('{}.sym_size\\((-?\\w+)\\)', {'suffix': lambda m: f"_sym_argsize_{m.groups()[0].replace('-', 'minus_')}", 'nctype': lambda name: NamedCType(name, BaseCType(SymIntT))}), ('{}.numel\\(\\)', {'suffix': '_numel', 'nctype': lambda name: NamedCType(name, BaseCType(longT))}), ('{}.sym_numel\\(\\)', {'suffix': '_sym_numel', 'nctype': lambda name: NamedCType(name, BaseCType(SymIntT))}), ('to_args_sizes\\({}\\)', {'suffix': '_args_sizes', 'nctype': lambda name: NamedCType(name, VectorCType(VectorCType(BaseCType(longT))))}), ('to_args_sizes_symint\\({}\\)', {'suffix': '_args_sizes_symint', 'nctype': lambda name: NamedCType(name, VectorCType(VectorCType(BaseCType(SymIntT))))}), ('to_args_scalartypes\\({}\\)', {'suffix': '_args_scalartypes', 'nctype': lambda name: NamedCType(name, VectorCType(BaseCType(scalarTypeT)))}), ('TensorGeometry\\({}\\)', {'suffix': '_geometry', 'nctype': lambda name: NamedCType(name, BaseCType(tensorGeometryT))}), ('{}.scalar_type\\(\\)', {'suffix': '_scalar_type', 'nctype': lambda name: NamedCType(name, BaseCType(scalarTypeT))}), ('{}.dim\\(\\)', {'suffix': '_dim', 'nctype': lambda name: NamedCType(name, BaseCType(longT))}), ('{}.sym_strides\\(\\)', {'suffix': '_sym_strides', 'nctype': lambda name: NamedCType(name, BaseCType(symIntArrayRefT)), 'expr': stride_expr}), ('{}.layout\\(\\)', {'suffix': '_layout', 'nctype': lambda name: NamedCType(name, BaseCType(layoutT))}), ('{}.is_conj\\(\\)', {'suffix': '_conjugate', 'nctype': lambda name: NamedCType(name, BaseCType(boolT))})]
    saved: list[SavedAttribute] = []
    if '.sizes()' in formula or '->sizes()' in formula:
        raise RuntimeError('.sizes() is not supported in derivative formulas. Instead, please use the SymInt version,' + f'.sym_sizes(), which returned a c10::SymIntArrayRef. formula={formula}')
    if re.search('\\.size\\([-]?\\d+\\)', formula) or re.search('->size\\([-]?\\d+\\)', formula):
        raise RuntimeError('.size(int) is not supported in derivative formulas. Instead, please use the SymInt version,' + f'.sym_size(int), which returned a c10::SymIntArrayRef. formula={formula}')
    if '.strides()' in formula or '->strides()' in formula:
        raise RuntimeError('.strides() is not supported in derivative formulas. Instead, please use the SymInt version,' + f'.sym_strides(), which returned a c10::SymIntArrayRef. formula={formula}')
    for nctype in nctypes:
        name = nctype.name.name if isinstance(nctype.name, SpecialArgName) else nctype.name
        for (regex, info) in REPLACEMENTS:

            def repl(m: re.Match[str]) -> str:
                suffix: str = info['suffix'](m) if callable(info['suffix']) else info['suffix']
                expr: str = info['expr'](name) if 'expr' in info else m.group(0)
                saved.append(SavedAttribute(nctype=info['nctype'](name + suffix), expr=expr))
                if <MASK>:
                    replacement: str = info['res'](name)
                    return replacement
                return name + suffix
            formula = re.sub(regex.format(name), repl, formula)
        if nctype.type == OptionalCType(BaseCType(stringT)):
            formula = re.sub(f'\\b{name}\\b', f'{name}.has_value() ? std::optional<std::string_view>({name}.value()) : std::nullopt', formula)
        if re.search(IDENT_REGEX.format(name), formula):
            saved.append(SavedAttribute(nctype=nctype, expr=name))
    return (formula, tuple(saved))

def _capture_helper(self, tensor, name):
    if tensor.graph is not self._forward_graph or any((tensor is t for t in self._forward_graph.inputs)) or any((tensor is t for t in self._forward_graph.outputs)):
        return super(_CondGradFuncGraph, self)._capture_helper(tensor, name)
    tensor_id = ops.tensor_id(tensor)
    if tensor_id in self._captured_constants:
        return self._captured_constants[tensor_id]
    elif <MASK>:
        self._captured_constants[tensor_id] = constant_op.constant(tensor_util.constant_value(tensor), dtype=tensor.dtype)
        return self._captured_constants[tensor_id]
    if not context.optionals_in_gradients_enabled() or control_flow_util.GraphOrParentsInXlaContext(ops.get_default_graph()):
        if all((tensor is not capture for capture in self.external_captures)):
            self.xla_intermediates.append(tensor)
            self.op_needs_rewrite = True
        return super(_CondGradFuncGraph, self)._capture_helper(tensor, name)
    captured_tensor = self._indirect_captures.get(tensor_id)
    if captured_tensor is not None:
        return captured_tensor
    if tensor.dtype == dtypes.resource:
        index = util.resource_input_index(tensor.name, [t.name for t in self._forward_graph.inputs], {op.name: op.node_def for op in self._forward_graph.get_operations()}, self._forward_graph._functions)
        captured_tensor = super(_CondGradFuncGraph, self)._capture_helper(self._forward_graph.inputs[index], name)
    else:
        if tensor_id not in self._wrapped_intermediates:
            for consumer in tensor.consumers():
                if consumer.type == 'OptionalFromValue' and any((consumer.outputs[0] is output for output in self._forward_graph.outputs)):
                    optional = consumer.outputs[0]
                    break
            else:
                with self._forward_graph.as_default():
                    optional = gen_optional_ops.optional_from_value([tensor])
                self.op_needs_rewrite = True
            self._wrapped_intermediates[tensor_id] = optional
        optional = self._wrapped_intermediates[tensor_id]
        captured_optional = super(_CondGradFuncGraph, self)._capture_helper(optional, name)
        captured_tensor = gen_optional_ops.optional_get_value(captured_optional, [tensor.dtype], [tensor.shape])[0]
    self._indirect_captures[tensor_id] = captured_tensor
    return captured_tensor

@doc(ExtensionArray.searchsorted)
def searchsorted(self, value: NumpyValueArrayLike | ExtensionArray, side: Literal['left', 'right']='left', sorter: NumpySorter | None=None) -> npt.NDArray[np.intp] | np.intp:
    if <MASK>:
        raise ValueError('searchsorted requires array to be sorted, which is impossible with NAs present.')
    if isinstance(value, ExtensionArray):
        value = value.astype(object)
    dtype = None
    if isinstance(self.dtype, ArrowDtype):
        pa_dtype = self.dtype.pyarrow_dtype
        if (pa.types.is_timestamp(pa_dtype) or pa.types.is_duration(pa_dtype)) and pa_dtype.unit == 'ns':
            dtype = object
    return self.to_numpy(dtype=dtype).searchsorted(value, side=side, sorter=sorter)

def var_mean_welford_(x, axis, *, correction, keepdim, return_mean):
    if <MASK>:
        correction = 1
    kwargs = _make_reduction_inner(x, axis=axis, keepdims=keepdim, dtype=None, override_return_dtype=None)
    loader = kwargs.pop('inner_fn')
    kwargs.pop('dst_dtype')
    kwargs.pop('src_dtype')
    (mean, m2, _) = ir.WelfordReduction.create(inner_fns=(loader,), reduction_type='welford_reduce', dtype=x.get_dtype(), **kwargs)
    m2.realize()
    dtype = x.get_dtype()
    size = x.get_size()
    axis = _validate_reduction_axis(x, axis)
    rnumel = sympy_product((size[i] for i in axis))

    def get_constant_or_index_expr(x, dtype):
        if isinstance(x, sympy.Expr) and (not x.is_number):
            return ops.to_dtype(ops.index_expr(x, torch.int64), dtype)
        return ops.constant(x, dtype)

    def scale_fn(data):
        c = get_constant_or_index_expr(correction, dtype)
        N = get_constant_or_index_expr(rnumel, dtype)
        zero = ops.constant(0, dtype)
        return data / ops.maximum(zero, N - c)
    var = make_pointwise(scale_fn)(m2)
    if return_mean:
        mean.realize()
        return (var, mean)
    return (var,)

def treespec_dumps(treespec: TreeSpec, protocol: Optional[int]=None) -> str:
    if <MASK>:
        raise TypeError(f'treespec_dumps(treespec, protocol): Expected `treespec` to be instance of TreeSpec but got item of type {type(treespec)}.')
    if protocol is None:
        protocol = DEFAULT_TREESPEC_SERIALIZATION_PROTOCOL
    if protocol in _SUPPORTED_PROTOCOLS:
        json_spec = _SUPPORTED_PROTOCOLS[protocol].treespec_to_json(treespec)
    else:
        raise ValueError(f'Unknown protocol {protocol}. Available protocols: {list(_SUPPORTED_PROTOCOLS.keys())}')
    str_spec = json.dumps((protocol, dataclasses.asdict(json_spec)), cls=EnumEncoder)
    return str_spec

def _compare(self, x, reduction_axes, keepdims, use_gpu=False):
    np_ans = x
    if <MASK>:
        np_ans = np.any(np_ans, keepdims=keepdims)
    else:
        for ra in reduction_axes[::-1]:
            np_ans = np.any(np_ans, axis=ra, keepdims=keepdims)
    with self.cached_session(use_gpu=use_gpu):
        if reduction_axes is not None:
            reduction_axes = np.array(reduction_axes).astype(np.int32)
        tf_ans = math_ops.reduce_any(x, reduction_axes, keepdims)
        out = self.evaluate(tf_ans)
    self.assertAllEqual(np_ans, out)
    self.assertShapeEqual(np_ans, tf_ans)

