def _post_convert_dtypes(df: pd.DataFrame, dtype_backend: DtypeBackend | Literal['numpy'] | lib.NoDefault, dtype: DtypeArg | None, names: Sequence[Hashable] | None) -> pd.DataFrame:
    if dtype is not None and (dtype_backend is lib.no_default or dtype_backend == 'numpy'):
        if <MASK>:
            if names is not None:
                df.columns = names
            cmp_dtypes = {pd.Int8Dtype(), pd.Int16Dtype(), pd.Int32Dtype(), pd.Int64Dtype()}
            for col in df.columns:
                if col not in dtype and df[col].dtype in cmp_dtypes:
                    dtype[col] = df[col].dtype.numpy_dtype
            dtype = {key: pandas_dtype(dtype[key]) for key in dtype if key in df.columns}
        else:
            dtype = pandas_dtype(dtype)
        try:
            df = df.astype(dtype)
        except TypeError as err:
            raise ValueError(str(err)) from err
    return df

def on_epoch_end(self, epoch, logs=None):
    current = self.get_monitor_value(logs)
    if <MASK>:
        return
    if self.restore_best_weights and self.best_weights is None:
        self.best_weights = self.model.get_weights()
    self.wait += 1
    if self._is_improvement(current, self.best):
        self.best = current
        if self.restore_best_weights:
            self.best_weights = self.model.get_weights()
        if self.baseline is None or self._is_improvement(current, self.baseline):
            self.wait = 0
    if self.wait >= self.patience:
        self.stopped_epoch = epoch
        self.model.stop_training = True
        if self.restore_best_weights and self.best_weights is not None:
            if self.verbose > 0:
                print('Restoring model weights from the end of the best epoch.')
            self.model.set_weights(self.best_weights)

def dataset_fn(delay_ms):

    def sleep(x):
        time.sleep(delay_ms / 1000)
        return x

    def map_function(x):
        if <MASK>:
            return script_ops.py_func(sleep, [x], x.dtype)
        else:
            return x
    dataset = dataset_ops.Dataset.from_tensor_slices(elements)
    dataset = apply_map(dataset, map_function, num_parallel_calls=2, deterministic=local_determinism)
    opts = options_lib.Options()
    opts.deterministic = global_determinism
    dataset = dataset.with_options(opts)
    return dataset

def _placeholder_value(like, shape_invariant, original=None):
    """Constructs a (dummy) placeholder value for a loop-initialized variable.

  Args:
    like: Any object. The value created by the first iteration of the loop. If a
      Python scalar, the placeholder will be the zero value of that type. If a
      Tensor, the placeholder will be a zero tensor of matching shape and dtype.
      If a list, dict or tuple, the placeholder will be an identical structure
      of placeholders.
    shape_invariant: The shape invariant specified by the user (or None, if
      nothing was specified) for the respective variable.
    original: Any object. The value of the variable prior to entering the loop.
      Typically, this is one of the special "Undefined" value, because that's
      when a placeholder is needed.

  Returns:
    Either a zero value of structure, shape and dtype matching 'like', or
    'original', if no such zero value could be created.
  """
    if like is None:
        return (original, None)
    elif isinstance(like, (variables.Undefined, variables.UndefinedReturnValue)):
        return (original, None)
    elif isinstance(like, (int, float, bool)):
        return (type(like)(0), None)
    elif tensor_util.is_tf_type(like):
        like_shape = shape_invariant if shape_invariant is not None else like.shape
        if like_shape is None or like_shape.rank is None:
            return (array_ops.zeros((), like.dtype), like_shape)
        placeholder_shape = []
        has_dynamic_dims = False
        for (s, i) in zip(like.shape, like_shape):
            if i is None:
                like_dim = 0
            elif isinstance(i, tensor_shape.Dimension):
                if i.value is None:
                    like_dim = 0
                else:
                    like_dim = i.value
            else:
                like_dim = i
            if s is None:
                placeholder_shape.append(like_dim)
                has_dynamic_dims = True
            elif isinstance(s, tensor_shape.Dimension):
                if s.value is None:
                    placeholder_shape.append(like_dim)
                    has_dynamic_dims = True
                else:
                    placeholder_shape.append(s.value)
            else:
                placeholder_shape.append(s)
        if has_dynamic_dims:
            invariant = like_shape
        else:
            invariant = None
        return (array_ops.zeros(placeholder_shape, like.dtype), invariant)
    elif <MASK>:
        if shape_invariant is None:
            zipped = nest.map_structure(lambda v: _placeholder_value(v, None), nest.flatten(like))
        else:
            zipped = nest.map_structure(_placeholder_value, nest.flatten(like), nest.flatten(shape_invariant))
        (vals, invars) = zip(*zipped)
        return (nest.pack_sequence_as(like, vals), nest.pack_sequence_as(like, invars))
    raise TypeError("Found an unsupported type '{}' while creating placeholder for {}. Supported types include Tensor, int, float, bool, list, tuple or dict.".format(type(like).__name__, like))

@final
@property
def _is_mixed_type(self) -> bool:
    if <MASK>:
        return False
    if self._mgr.any_extension_types:
        return True
    return self.dtypes.nunique() > 1

def crack2fortrangen(block, tab='\n', as_interface=False):
    global skipfuncs, onlyfuncs
    setmesstext(block)
    ret = ''
    if isinstance(block, list):
        for g in block:
            if g and g['block'] in ['function', 'subroutine']:
                if g['name'] in skipfuncs:
                    continue
                if onlyfuncs and g['name'] not in onlyfuncs:
                    continue
            ret = ret + crack2fortrangen(g, tab, as_interface=as_interface)
        return ret
    prefix = ''
    name = ''
    args = ''
    blocktype = block['block']
    if blocktype == 'program':
        return ''
    argsl = []
    if 'name' in block:
        name = block['name']
    if 'args' in block:
        vars = block['vars']
        for a in block['args']:
            a = expr2name(a, block, argsl)
            if not isintent_callback(vars[a]):
                argsl.append(a)
        if block['block'] == 'function' or argsl:
            args = f"({','.join(argsl)})"
    f2pyenhancements = ''
    if 'f2pyenhancements' in block:
        for k in list(block['f2pyenhancements'].keys()):
            f2pyenhancements = '%s%s%s %s' % (f2pyenhancements, tab + tabchar, k, block['f2pyenhancements'][k])
    intent_lst = block.get('intent', [])[:]
    if blocktype == 'function' and 'callback' in intent_lst:
        intent_lst.remove('callback')
    if intent_lst:
        f2pyenhancements = '%s%sintent(%s) %s' % (f2pyenhancements, tab + tabchar, ','.join(intent_lst), name)
    use = ''
    if 'use' in block:
        use = use2fortran(block['use'], tab + tabchar)
    common = ''
    if 'common' in block:
        common = common2fortran(block['common'], tab + tabchar)
    if name == 'unknown_interface':
        name = ''
    result = ''
    if 'result' in block:
        result = f" result ({block['result']})"
        if block['result'] not in argsl:
            argsl.append(block['result'])
    body = crack2fortrangen(block['body'], tab + tabchar, as_interface=as_interface)
    vars = vars2fortran(block, block['vars'], argsl, tab + tabchar, as_interface=as_interface)
    mess = ''
    if <MASK>:
        mess = f"! in {block['from']}"
    if 'entry' in block:
        entry_stmts = ''
        for (k, i) in list(block['entry'].items()):
            entry_stmts = f"{entry_stmts}{tab + tabchar}entry {k}({','.join(i)})"
        body = body + entry_stmts
    if blocktype == 'block data' and name == '_BLOCK_DATA_':
        name = ''
    ret = '%s%s%s %s%s%s %s%s%s%s%s%s%send %s %s' % (tab, prefix, blocktype, name, args, result, mess, f2pyenhancements, use, vars, common, body, tab, blocktype, name)
    return ret

@deco_stream
def random_sample(size=None):
    if <MASK>:
        size = ()
    dtype = _dtypes_impl.default_dtypes().float_dtype
    values = torch.empty(size, dtype=dtype).uniform_()
    return array_or_scalar(values, return_scalar=size == ())

def _determine_input_dtype(param: _schemas.Parameter, arg: AllowedArgType, type_binding: Mapping[_schemas.TypeConstraintParam, ir.TypeProtocol]) -> ir.DataType:
    """Determine the dtype of the input that is a mix of Python constants and ir.Value."""
    if param.type_constraint in type_binding:
        return type_binding[param.type_constraint].dtype
    if len(param.type_constraint.allowed_types) == 1:
        return next(iter(param.type_constraint.allowed_types)).dtype
    if isinstance(arg, bool):
        return ir.DataType.BOOL
    if isinstance(arg, float):
        return ir.DataType.FLOAT
    if isinstance(arg, int):
        return ir.DataType.INT64
    if isinstance(arg, str):
        return ir.DataType.STRING
    if isinstance(arg, (ir.Tensor, ir.TensorProtocol)):
        return arg.dtype
    if isinstance(arg, complex):
        return ir.DataType.FLOAT
    if <MASK>:
        return ir.DataType.UNDEFINED
    if isinstance(arg, (tuple, list)):
        if len(arg) == 0:
            return ir.DataType.INT64
        for val in arg:
            if isinstance(val, ir.Value) and val.dtype is not None:
                return val.dtype
        if any((isinstance(val, float) for val in arg)):
            return ir.DataType.FLOAT
        elif any((isinstance(val, int) for val in arg)):
            return ir.DataType.INT64
    raise ValueError(f"Could not determine the dtype for the input '{param.name}'. param={param}, arg={arg}, param_type_constraint={param.type_constraint}, type_binding={type_binding}")

def is_aten_to_device_only(args):
    if <MASK>:
        return args[0].node().kind() == 'prim::device' or args[0].type().isSubtypeOf(_C.ListType.ofInts()) or isinstance(args[0].type(), _C.DeviceObjType)
    elif len(args) == 5:
        dtype = symbolic_helper._get_const(args[1], 'i', 'dtype')
        return dtype is None
    elif len(args) in (6, 7):
        dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
        return dtype is None
    return False

def iter_contains(items: Iterable[Any], search: Any, tx: InstructionTranslator, check_tensor_identity: bool=False) -> Any:
    from .variables import BuiltinVariable, ConstantVariable, TensorVariable
    if search.is_python_constant():
        found_const = any((x.is_python_constant() and x.as_python_constant() == search.as_python_constant() for x in items))
        return ConstantVariable.create(found_const)
    must_check_tensor_id = False
    if check_tensor_identity and isinstance(search, TensorVariable):
        must_check_tensor_id = True
        search = _get_fake_tensor(search)
    found: Optional[VariableTracker] = None
    for x in items:
        if <MASK>:
            if isinstance(x, TensorVariable):
                if search is _get_fake_tensor(x):
                    return ConstantVariable.create(True)
        else:
            check = BuiltinVariable(operator.eq).call_function(tx, [x, search], {})
            if found is None:
                found = check
            else:
                found = BuiltinVariable(operator.or_).call_function(tx, [check, found], {})
    if found is None:
        found = ConstantVariable.create(False)
    return found

def _value_formatter(self, float_format: FloatFormatType | None=None, threshold: float | None=None) -> Callable:
    """Returns a function to be applied on each value to format it"""
    if float_format is None:
        float_format = self.float_format
    if float_format:

        def base_formatter(v):
            assert float_format is not None
            return float_format(value=v) if notna(v) else self.na_rep
    else:

        def base_formatter(v):
            return str(v) if notna(v) else self.na_rep
    if <MASK>:

        def decimal_formatter(v):
            return base_formatter(v).replace('.', self.decimal, 1)
    else:
        decimal_formatter = base_formatter
    if threshold is None:
        return decimal_formatter

    def formatter(value):
        if notna(value):
            if abs(value) > threshold:
                return decimal_formatter(value)
            else:
                return decimal_formatter(0.0)
        else:
            return self.na_rep
    return formatter

def regurgitate(depth, use_pyyaml_formatter=False):
    data = yaml.safe_load(sys.stdin)
    if <MASK>:
        output = yaml.dump(data, sort_keys=True)
        sys.stdout.write(output)
    else:
        miniyaml.render(sys.stdout, data, depth)

def _get_arg(self, name, unpack):
    assert name in self._required_arg_names
    if name not in self._arg_cache:
        fn_name = name + '_fn'
        size_name = name + '_size'
        if name in self._extra_kwargs:
            self._arg_cache[name] = self._extra_kwargs[name]
        elif fn_name in self._extra_kwargs:
            self._arg_cache[name] = self._extra_kwargs[fn_name]()
        else:
            assert size_name in self._extra_kwargs, f'Missing `{name}`, `{size_name}` or `{fn_name}` for {self.get_name()}'

            def map_tensor_sizes(sizes):
                if <MASK>:
                    return [map_tensor_sizes(s) for s in sizes]
                elif isinstance(sizes, torch.Tensor):
                    return sizes.double()
                else:
                    return torch.randn(sizes)
            self._arg_cache[name] = map_tensor_sizes(self._extra_kwargs[size_name])
    return self._unpack(self._arg_cache[name]) if unpack else self._arg_cache[name]

@register_dispatch_func([torch.ops.aten.is_strides_like_format])
def is_strides_like_format(func, *args, **kwargs):
    data = _get_data(args[0])
    if <MASK>:
        raise ValueError('MaskedTensors with sparse data do not have is_strides_like_format')
    return func(data, *args[1:], **kwargs)

def _get_cython_vals(self, values: np.ndarray) -> np.ndarray:
    """
        Cast numeric dtypes to float64 for functions that only support that.

        Parameters
        ----------
        values : np.ndarray

        Returns
        -------
        values : np.ndarray
        """
    how = self.how
    if how in ['median', 'std', 'sem', 'skew', 'kurt']:
        values = ensure_float64(values)
    elif values.dtype.kind in 'iu':
        if how in ['var', 'mean'] or (self.kind == 'transform' and self.has_dropped_na):
            values = ensure_float64(values)
        elif <MASK>:
            if values.dtype.kind == 'i':
                values = ensure_int64(values)
            else:
                values = ensure_uint64(values)
    return values

def __str__(self) -> str:
    type = f'{self.type}'
    if self.annotation:
        assert type in ['Tensor', 'Tensor?', 'Tensor[]']
        type = type.replace('Tensor', f'Tensor({self.annotation})')
    if <MASK>:
        return type
    else:
        return f'{type} {self.name}'

def __post_init__(self) -> None:
    for (arg, ret) in zip(self.arguments.out, self.returns):
        assert arg.annotation == ret.annotation, 'Out arguments must have matching return Tensor; furthermore, the ith-argument needs to correspond to the ith return'
    for a in self.arguments.post_self_positional_mutable:
        assert not any((a.annotation == r.annotation for r in self.returns)), f'If you have a schema with mutable positional args, we expect them to not be returned. schema: {str(self)}'
    out_and_self = list(self.arguments.out) + [arg for arg in self.arguments.flat_positional if arg.name == 'self']
    mutable_returns = [ret for ret in self.returns if ret.annotation is not None and ret.annotation.is_write]
    immutable_returns = [ret for ret in self.returns if ret.annotation is None or not ret.annotation.is_write]
    assert len(mutable_returns) == 0 or len(immutable_returns) == 0, f'NativeFunctions must have either only mutable returns, or only immutable returns. Found: {str(self)}'
    for ret in mutable_returns:
        assert any((ret.annotation == arg.annotation for arg in out_and_self)), 'All mutable returns must be aliased either to a keyword argument, or to "self". Did you forget to mark an out argument as keyword-only?'
    if self.arguments.out:
        if any((a.type != BaseType(BaseTy.Tensor) for a in self.arguments.out)):
            assert len(self.returns) == 0, 'out= ops that accept tensor lists as out arguments '
            "are expected to have no return type (since you can't do method chaining on them)"
        else:
            assert len([arg for arg in self.arguments.out if not arg.name.startswith('_scratch_')]) == len(self.returns), 'Must return as many arguments as there are out arguments, or no return at all'
    if <MASK>:
        self_a = self.arguments.self_arg
        assert self_a and self_a.argument.annotation and self_a.argument.annotation.is_write
        if self_a.argument.type == BaseType(BaseTy.Tensor):
            assert len(self.returns) == 1 and self.returns[0].annotation == self_a.argument.annotation
        else:
            assert len(self.returns) == 0
    if self.arguments.tensor_options is not None:
        assert self.kind() == SchemaKind.functional, f'Found an operator that is not functional or out variant, but has tensor options arguments.This is not allowed- tensor options arguments are only allowed for factory functions.schema: {str(self)}'
    if self.is_functional_fn():
        assert self.kind() == SchemaKind.functional, f"Found an operator that is not functional, but its overload contains the string 'functional'.This is a special keyword in the codegen, please use a different overload name.schema: {str(self)}"

def test_composite_state_complex(self):

    class TestClassX(object):

        def __init__(self, x):
            self.x = x

    class TestClassY(object):

        def __init__(self, y):
            self.y = y

    def f(n):
        tc = TestClassX(TestClassY({'z': TestClassX(n)}))
        if <MASK>:
            while n > 0:
                if n < 2:
                    tc.x.y['z'].x += 1
                n -= 1
        return (n, tc)
    tr = self.transform(f, control_flow)
    (n, tc) = tr(constant_op.constant(5))
    self.assertValuesEqual((n, tc.x.y['z'].x), (0, 6))

def _train_for_several_steps(self, model: nn.Module, num_steps: int, autocast: bool, lr: float=0.01, fsdp_cpu_offload: Optional[CPUOffload]=None, save_model: bool=False, mixed_precision: Optional[MixedPrecision]=None, enable_sharded_grad_scaler: bool=False, use_pure_fp16: bool=False, sharded_grad_scaler_kwargs: Optional[dict[str, Any]]=None):
    cpu_offload_params = fsdp_cpu_offload and fsdp_cpu_offload.offload_params
    model_device = next(model.parameters()).device
    if sharded_grad_scaler_kwargs is None:
        sharded_grad_scaler_kwargs = {}
    sharded_grad_scaler = ShardedGradScaler(enabled=enable_sharded_grad_scaler, **sharded_grad_scaler_kwargs)
    optim = torch.optim.SGD(model.parameters(), lr=lr, momentum=0.9)
    for _ in range(num_steps):
        optim.zero_grad()
        with torch.amp.autocast(DEVICE_TYPE, enabled=autocast):
            input = model.module.get_input(torch.device(DEVICE_TYPE))
            if use_pure_fp16 or (mixed_precision and (not isinstance(model, FSDP))):
                if isinstance(input, torch.Tensor):
                    input = input.half()
                else:
                    input = tuple((x.half() for x in input))
            output = model(*input)
            if cpu_offload_params and isinstance(model, FSDP) and (model.sharding_strategy not in NO_RESHARD_AFTER_FORWARD_STRATEGIES):
                for p in model.parameters():
                    self.assertEqual(p.device, torch.device('cpu'))
            loss = model.module.get_loss(input, output).to(model_device)
        loss = sharded_grad_scaler.scale(loss)
        if <MASK>:
            assert loss.dtype == torch.float32, 'loss data type should be float32, as the original                     parameter data type is float32.'
        elif use_pure_fp16:
            self.assertEqual(loss.dtype, torch.float16)
        elif isinstance(model, FSDP):
            assert mixed_precision is not None
            self.assertEqual(loss.dtype, mixed_precision.param_dtype)
        else:
            self.assertEqual(loss.dtype, torch.float32)
        model.module.run_backward(loss)
        if cpu_offload_params and isinstance(model, FSDP):
            for p in model.parameters():
                self.assertEqual(p.device, torch.device('cpu'))
        sharded_grad_scaler.step(optim)
        sharded_grad_scaler.update()
        if save_model:
            state_dict = {k: v.clone() for (k, v) in model.state_dict().items()}
            _zero_model(model)
            model.load_state_dict(state_dict)
    if isinstance(model, FSDP):
        model._assert_state(TrainingState.IDLE)
    return loss.detach()

def _dp_init_subclass(sub_cls, *args, **kwargs):
    sub_cls.reinforce_type = reinforce_type
    if getattr(sub_cls, '__type_class__', False):
        return
    if isinstance(sub_cls.type.param, ForwardRef):
        base_globals = sys.modules[sub_cls.__module__].__dict__
        try:
            param = _eval_type(sub_cls.type.param, base_globals, locals())
            sub_cls.type.param = param
        except TypeError as e:
            raise TypeError(f'{sub_cls.type.param.__forward_arg__} is not supported by Python typing') from e
    if '__iter__' in sub_cls.__dict__:
        iter_fn = sub_cls.__dict__['__iter__']
        hints = get_type_hints(iter_fn)
        if <MASK>:
            return_hint = hints['return']
            if return_hint == Iterator:
                return
            if not (hasattr(return_hint, '__origin__') and (return_hint.__origin__ == Iterator or return_hint.__origin__ == collections.abc.Iterator)):
                raise TypeError("Expected 'Iterator' as the return annotation for `__iter__` of {}, but found {}".format(sub_cls.__name__, _type_repr(hints['return'])))
            data_type = return_hint.__args__[0]
            if not issubtype(data_type, sub_cls.type.param):
                raise TypeError(f"Expected return type of '__iter__' as a subtype of {sub_cls.type}, but found {_type_repr(data_type)} for {sub_cls.__name__}")

def assert_replica_context(strategy):
    replica_context = distribute_lib.get_replica_context()
    if <MASK>:
        raise RuntimeError('Replica-local variables may only be assigned in a replica context.')
    if replica_context.strategy is not strategy:
        raise RuntimeError('Replica-local variables may only be assigned in a replica context.')

@RegisterPFor('TensorArrayGatherV3')
def _convert_tensor_array_gather_v3(pfor_input: _PforInput):
    handle = pfor_input.unstacked_input(0)
    (indices, indices_stacked, _) = pfor_input.input(1)
    indices = array_ops.reshape(indices, [-1])
    (flow, flow_stacked, _) = pfor_input.input(2)
    if flow_stacked:
        flow = _unstack_flow(flow)
    dtype = pfor_input.get_attr('dtype')
    n = pfor_input.pfor.loop_len_vector
    value = data_flow_ops.tensor_array_gather_v3(handle, indices, flow, dtype=dtype)
    is_inside = _handle_inside_pfor(pfor_input, pfor_input.op.inputs[0])
    if is_inside:
        if <MASK>:
            if flow_stacked:
                raise ValueError('It looks like TensorArrayGatherV3 was called on a TensorArray whose values are not loop-invariant, and the indices were also not loop invariant. This is currently unsupported.')
            else:
                value = _unflatten_first_dim(value, n)
                return wrap(value, True)
        else:
            if flow_stacked:
                value = _transpose_first_two_dims(value)
            return wrap(value, flow_stacked)
    else:
        if indices_stacked:
            value = _unflatten_first_dim(value, n)
        return wrap(value, indices_stacked)

def _create_dataset_reader(dataset_creator, filenames, num_parallel_reads=None, name=None):
    """Creates a dataset that reads the given files using the given reader.

  Args:
    dataset_creator: A function that takes in a single file name and returns a
      dataset.
    filenames: A `tf.data.Dataset` containing one or more filenames.
    num_parallel_reads: The number of parallel reads we should do.
    name: (Optional.) A name for the tf.data operation.

  Returns:
    A `Dataset` that reads data from `filenames`.
  """

    def read_one_file(filename):
        filename = ops.convert_to_tensor(filename, dtypes.string, name='filename')
        return dataset_creator(filename)
    if <MASK>:
        return filenames.flat_map(read_one_file, name=name)
    elif num_parallel_reads == dataset_ops.AUTOTUNE:
        return filenames.interleave(read_one_file, num_parallel_calls=num_parallel_reads, name=name)
    else:
        return ParallelInterleaveDataset(filenames, read_one_file, cycle_length=num_parallel_reads, block_length=1, sloppy=False, buffer_output_elements=None, prefetch_input_elements=None, name=name)

@contextlib.contextmanager
def _unshard_fsdp_state_params(module: nn.Module, state: _FSDPState, writeback: bool, rank0_only: bool, offload_to_cpu: bool, with_grads: bool):
    """
    This unshards the parameters for a single FSDP state ``state`` that
    corresponds to ``module``.
    """
    _validate_unshard_params_args(state, writeback, rank0_only, offload_to_cpu, with_grads)
    state._device_handle.synchronize()
    maybe_handle = _module_handle(state, module)
    handle = None
    if maybe_handle and maybe_handle._training_state != HandleTrainingState.SUMMON_FULL_PARAMS:
        handle = maybe_handle
    if not handle:
        yield
        return
    if handle._training_state != HandleTrainingState.IDLE:
        raise AssertionError(f'Expects the handle training to be IDLE but got {handle._training_state}')
    handle._training_state = HandleTrainingState.SUMMON_FULL_PARAMS
    _reset_flat_param_grad_info_if_needed(handle)
    free_unsharded_flat_param = handle.needs_unshard()
    computation_stream = state._device_handle.current_stream()
    _unshard(state, handle, computation_stream, computation_stream)
    if with_grads:
        _unshard_grads(handle)
    if <MASK>:
        _reshard(state, handle, free_unsharded_flat_param)
        if with_grads:
            _reshard_grads(handle)
        try:
            yield
        finally:
            handle._training_state = HandleTrainingState.IDLE
    else:
        with contextlib.ExitStack() as stack:
            if offload_to_cpu and handle.uses_sharded_strategy:
                stack.enter_context(handle.to_cpu())
            if not state._use_orig_params:
                stack.enter_context(_unflatten_as_params(state, module))
            try:
                yield
            finally:
                stack.close()
                if writeback:
                    _writeback_to_local_shard(handle, with_grads)
                _reshard(state, handle, free_unsharded_flat_param)
                if with_grads:
                    _reshard_grads(handle)
                handle._training_state = HandleTrainingState.IDLE

def get(self, key, otherwise=None):
    for d in reversed(self.dicts):
        if <MASK>:
            return d[key]
    return otherwise

def construct_cat_args(graph: torch.fx.Graph, cat_or_stack_node: torch.fx.Node, inputs: list[torch.fx.Node], split_or_unbind_node: torch.fx.Node, threshold_to_cat: int=2, run_update_func: Callable=update_args_from_split_getitem) -> tuple[list[torch.fx.Node], list[torch.Tensor]]:
    (new_cat_args, parents_seen, getitem_indices, idx_to_getitems) = ([], [], [], {})
    new_cat_args_meta = []
    for input in inputs:
        if input.target != operator.getitem:
            if <MASK>:
                run_update_func(graph, cat_or_stack_node, getitem_indices, parents_seen, new_cat_args, new_cat_args_meta, idx_to_getitems, threshold_to_cat)
            new_cat_args.append(input)
            new_cat_args_meta.append(input.meta['example_value'])
            (getitem_indices, idx_to_getitems) = ([], {})
        else:
            (parent, idx) = (input.args[0], input.args[1])
            if parent.target != split_or_unbind_node.target:
                new_cat_args.append(input)
                new_cat_args_meta.append(input.meta['example_value'])
                continue
            if len(parents_seen) == 0:
                parents_seen.append(parent)
                idx_to_getitems[idx] = input
                getitem_indices.append(idx)
                if input == inputs[-1]:
                    new_cat_args.append(input)
                    new_cat_args_meta.append(input.meta['example_value'])
                continue
            if parent != parents_seen[-1] or input == inputs[-1]:
                if input == inputs[-1]:
                    getitem_indices.append(idx)
                    idx_to_getitems[idx] = input
                run_update_func(graph, cat_or_stack_node, getitem_indices, parents_seen, new_cat_args, new_cat_args_meta, idx_to_getitems, threshold_to_cat)
                parents_seen.append(parent)
                (getitem_indices, idx_to_getitems) = ([idx], {idx: input})
            else:
                getitem_indices.append(idx)
                idx_to_getitems[idx] = input
    return (new_cat_args, new_cat_args_meta)

def __getitem__(self, key):
    """Returns the value of a dimension or a shape, depending on the key.

    Args:
      key: If `key` is an integer, returns the dimension at that index;
        otherwise if `key` is a slice, returns a TensorShape whose dimensions
        are those selected by the slice from `self`.

    Returns:
      An integer if `key` is an integer, or a `TensorShape` if `key` is a
      slice.

    Raises:
      ValueError: If `key` is a slice and `self` is completely unknown and
        the step is set.
    """
    if <MASK>:
        if isinstance(key, slice):
            return TensorShape(self._dims[key])
        elif self._v2_behavior:
            return self._dims[key]
        else:
            return self.dims[key]
    elif isinstance(key, slice):
        start = key.start if key.start is not None else 0
        stop = key.stop
        if key.step is not None:
            raise ValueError('Steps are not yet handled')
        if stop is None:
            return unknown_shape()
        elif start < 0 or stop < 0:
            return unknown_shape()
        else:
            return unknown_shape(rank=stop - start)
    elif self._v2_behavior:
        return None
    else:
        return Dimension(None)

def _isin(ar1, ar2, assume_unique=False, invert=False, *, kind=None):
    ar1 = np.asarray(ar1).ravel()
    ar2 = np.asarray(ar2).ravel()
    if ar2.dtype == object:
        ar2 = ar2.reshape(-1, 1)
    if kind not in {None, 'sort', 'table'}:
        raise ValueError(f"Invalid kind: '{kind}'. Please use None, 'sort' or 'table'.")
    is_int_arrays = all((ar.dtype.kind in ('u', 'i', 'b') for ar in (ar1, ar2)))
    use_table_method = is_int_arrays and kind in {None, 'table'}
    if use_table_method:
        if ar2.size == 0:
            if invert:
                return np.ones_like(ar1, dtype=bool)
            else:
                return np.zeros_like(ar1, dtype=bool)
        if ar1.dtype == bool:
            ar1 = ar1.astype(np.uint8)
        if ar2.dtype == bool:
            ar2 = ar2.astype(np.uint8)
        ar2_min = int(np.min(ar2))
        ar2_max = int(np.max(ar2))
        ar2_range = ar2_max - ar2_min
        below_memory_constraint = ar2_range <= 6 * (ar1.size + ar2.size)
        range_safe_from_overflow = ar2_range <= np.iinfo(ar2.dtype).max
        if range_safe_from_overflow and (below_memory_constraint or kind == 'table'):
            if invert:
                outgoing_array = np.ones_like(ar1, dtype=bool)
            else:
                outgoing_array = np.zeros_like(ar1, dtype=bool)
            if invert:
                isin_helper_ar = np.ones(ar2_range + 1, dtype=bool)
                isin_helper_ar[ar2 - ar2_min] = 0
            else:
                isin_helper_ar = np.zeros(ar2_range + 1, dtype=bool)
                isin_helper_ar[ar2 - ar2_min] = 1
            basic_mask = (ar1 <= ar2_max) & (ar1 >= ar2_min)
            in_range_ar1 = ar1[basic_mask]
            if in_range_ar1.size == 0:
                return outgoing_array
            try:
                ar2_min = np.array(ar2_min, dtype=np.intp)
                dtype = np.intp
            except OverflowError:
                dtype = ar2.dtype
            out = np.empty_like(in_range_ar1, dtype=np.intp)
            outgoing_array[basic_mask] = isin_helper_ar[np.subtract(in_range_ar1, ar2_min, dtype=dtype, out=out, casting='unsafe')]
            return outgoing_array
        elif <MASK>:
            raise RuntimeError("You have specified kind='table', but the range of values in `ar2` or `ar1` exceed the maximum integer of the datatype. Please set `kind` to None or 'sort'.")
    elif kind == 'table':
        raise ValueError("The 'table' method is only supported for boolean or integer arrays. Please select 'sort' or None for kind.")
    contains_object = ar1.dtype.hasobject or ar2.dtype.hasobject
    if len(ar2) < 10 * len(ar1) ** 0.145 or contains_object:
        if invert:
            mask = np.ones(len(ar1), dtype=bool)
            for a in ar2:
                mask &= ar1 != a
        else:
            mask = np.zeros(len(ar1), dtype=bool)
            for a in ar2:
                mask |= ar1 == a
        return mask
    if not assume_unique:
        (ar1, rev_idx) = np.unique(ar1, return_inverse=True)
        ar2 = np.unique(ar2)
    ar = np.concatenate((ar1, ar2))
    order = ar.argsort(kind='mergesort')
    sar = ar[order]
    if invert:
        bool_ar = sar[1:] != sar[:-1]
    else:
        bool_ar = sar[1:] == sar[:-1]
    flag = np.concatenate((bool_ar, [invert]))
    ret = np.empty(ar.shape, dtype=bool)
    ret[order] = flag
    if assume_unique:
        return ret[:len(ar1)]
    else:
        return ret[rev_idx]

def call_obj_hasattr(self, tx: 'InstructionTranslator', name: str) -> 'VariableTracker':
    if <MASK>:
        source = AttrSource(self.source, name)
        install_guard(source.make_guard(GuardBuilder.HASATTR))
        return variables.ConstantVariable(hasattr(self.value, name))
    return super().call_obj_hasattr(tx, name)

def _try_isolate_lhs(e: sympy.Basic, thing: sympy.Basic, floordiv_inequality: bool) -> sympy.Basic:
    op = type(e)
    if <MASK>:
        lhs_not_thing = sum((a for a in e.lhs.args if not a.has(thing))) if isinstance(e.lhs, sympy.Add) else 0
        e = op(e.lhs - lhs_not_thing, e.rhs - lhs_not_thing)
    if isinstance(e, sympy.Rel) and isinstance(e.lhs, sympy.Mul):
        (lhs, rhs) = e.args
        other = sympy.Mul(*[a for a in lhs.args if not a.has(thing)])
        if not (isinstance(e, INEQUALITY_TYPES) and other.is_negative is None) and (not (not isinstance(e, INEQUALITY_TYPES) and rhs.is_zero)):
            lhs = lhs / other
            rhs = rhs / other
            if isinstance(e, INEQUALITY_TYPES) and other.is_negative:
                op = mirror_rel_op(op)
            if op is None:
                raise AssertionError('expected op to be not None')
            e = op(lhs, rhs)
    if floordiv_inequality and isinstance(e, sympy.Rel) and isinstance(e.lhs, FloorDiv) and e.lhs.divisor.is_positive and e.rhs.is_integer:
        if isinstance(e, sympy.Eq):
            (numerator, denominator) = e.lhs.args
            return sympy.And(sympy.Ge(numerator, e.rhs * denominator), sympy.Lt(numerator, (e.rhs + 1) * denominator))
        if isinstance(e, sympy.Ne):
            (numerator, denominator) = e.lhs.args
            return sympy.Or(sympy.Lt(numerator, e.rhs * denominator), sympy.Ge(numerator, (e.rhs + 1) * denominator))
        if isinstance(e, (sympy.Gt, sympy.Ge)):
            quotient = e.rhs if isinstance(e, sympy.Ge) else e.rhs + 1
            return sympy.Ge(e.lhs.args[0], quotient * e.lhs.args[1])
        if isinstance(e, (sympy.Lt, sympy.Le)):
            quotient = e.rhs if isinstance(e, sympy.Lt) else e.rhs + 1
            return sympy.Lt(e.lhs.args[0], quotient * e.lhs.args[1])
    return e

@tf_export(v1=['saved_model.build_signature_def', 'saved_model.signature_def_utils.build_signature_def'])
@deprecation.deprecated_endpoints('saved_model.signature_def_utils.build_signature_def')
def build_signature_def(inputs=None, outputs=None, method_name=None, defaults=None):
    """Utility function to build a SignatureDef protocol buffer.

  Args:
    inputs: Inputs of the SignatureDef defined as a proto map of string to
      tensor info.
    outputs: Outputs of the SignatureDef defined as a proto map of string to
      tensor info.
    method_name: Method name of the SignatureDef as a string.
    defaults: Defaults of the SignatureDef defined as a proto map of string to
      TensorProto.

  Returns:
    A SignatureDef protocol buffer constructed based on the supplied arguments.
  """
    signature_def = meta_graph_pb2.SignatureDef()
    if inputs is not None:
        for item in inputs:
            signature_def.inputs[item].CopyFrom(inputs[item])
    if outputs is not None:
        for item in outputs:
            signature_def.outputs[item].CopyFrom(outputs[item])
    if method_name is not None:
        signature_def.method_name = method_name
    if defaults is not None:
        for (arg_name, default) in defaults.items():
            if isinstance(default, ops.EagerTensor):
                signature_def.defaults[arg_name].CopyFrom(tensor_util.make_tensor_proto(default.numpy()))
            elif <MASK>:
                signature_def.defaults[arg_name].CopyFrom(default.op.get_attr('value'))
            else:
                raise ValueError(f'Unable to convert object {str(default)} of type {type(default)} to TensorProto.')
    return signature_def

