def _run(self, new_inputs: list[InputType], function_id: FunctionID) -> OutputType:
    if self.in_recording:
        self.try_end_curr_recording(function_id)
    if self.in_warmup:
        self.try_end_curr_warmup(function_id)
    node_id = self._get_node_id()
    if function_id not in self.non_cudagraph_managed_mutation_hint[node_id]:
        self._update_non_cudagraph_managed_mutation(function_id, new_inputs)
    if <MASK>:
        return self.ids_to_funcs[function_id].model(new_inputs)
    if not (function_id in self.warmed_up_functions or config.triton.skip_cudagraph_warmup) or self.in_warmup or config.triton.force_cudagraphs_warmup:
        if self.path_state == ExecutionState.EXECUTION:
            self.apply_checkpoint_execution_state_in_allocator()
        return self.run_eager(new_inputs, function_id)
    assert not isinstance(self.current_node, CUDAWarmupNode)
    child_nodes = self.roots if self.current_node is None else self.current_node.children
    if not self.in_recording:
        (unexpected_rerecord, unexpected_rerecord_reason) = (False, lambda : '')
        for child in child_nodes[function_id]:
            (status, status_logger) = child.check_invariants(new_inputs)
            if status == CheckInvariantStatus.SUCCESS:
                return self.execute_node(child, new_inputs)
            if status == CheckInvariantStatus.StaticInputIdxMismatch or status == CheckInvariantStatus.CudagraphManagedIdxMismatch:
                unexpected_rerecord = True
                unexpected_rerecord_reason = status_logger
        if self.current_node is not None and function_id in self.roots:
            self.try_end_curr_execution()
            if self.current_node is None:
                return self.run(new_inputs, function_id)
        if len(self.ids_to_funcs[function_id].mutated_input_idxs) > 0:
            self._update_non_cudagraph_managed_mutation(function_id, new_inputs)
            if self.non_cudagraph_managed_mutation_hint[self._get_node_id()][function_id]:
                return self.ids_to_funcs[function_id].model(new_inputs)
        if unexpected_rerecord:
            curr_node_id = self._get_node_id()
            self.num_rerecord[curr_node_id][function_id] += 1
            if self.exceed_rerecord_limit(curr_node_id, function_id):
                _id = curr_node_id.id if curr_node_id else None
                log_cudagraph_skip_and_bump_counter(f'skipping cudagraph due to function {function_id.id} exceeding max re-recording limit (={torch._inductor.config.triton.cudagraph_unexpected_rerecord_limit}) on cudagraph node {_id} due to {unexpected_rerecord_reason()}.')
                return self.ids_to_funcs[function_id].model(new_inputs)
        self.debug_fail_counter += 1
        self.try_end_curr_execution()
        if self.current_node is not None:
            self.apply_checkpoint_execution_state_in_allocator()
    return self.record_function(new_inputs, function_id)

def create_deferred_runtime_asserts(self, n: torch.fx.Node, new_unbacked_defs: OrderedSet[sympy.Symbol]) -> None:

    def make_assert(expr: SympyBoolean, msg: str) -> None:
        assert_op = ir.AssertScalar(expr, msg)
        self.register_buffer(assert_op, set_name=True)
        self.register_operation(assert_op)
    if full_aoti_runtime_assert() and n.target == torch.ops.aten._assert_scalar.default and self.aot_mode:
        (node_args, _) = self.fetch_args_kwargs_from_env(n)
        if node_args[0] != True:
            make_assert(node_args[0], f'{node_args[0]} to be True')
    else:
        self.bound_unbacked_symbols |= new_unbacked_defs
        shape_env = V.graph.sizevars.shape_env
        for i0 in new_unbacked_defs:
            ras = self.ras_by_symbol.pop(i0, [])
            vr = shape_env.var_to_range[i0]
            if not shape_env._default_unspecified_value_range().issubset(vr):

                def is_convertible(s: Expr) -> bool:
                    if s in (int_oo, -int_oo):
                        return False
                    try:
                        int(s)
                        return True
                    except TypeError:
                        return False
                if is_convertible(vr.lower):
                    make_assert(i0 >= vr.lower, f'{i0} >= {vr.lower}')
                if <MASK>:
                    make_assert(i0 <= vr.upper, f'{i0} <= {vr.upper}')
            for ra in ras:
                fvs = free_unbacked_symbols(ra.expr)
                missing = fvs - self.bound_unbacked_symbols
                if missing:
                    i1 = min(missing, key=str)
                    self.ras_by_symbol.setdefault(i1, []).append(ra)
                else:
                    make_assert(ra.expr, f'{ra.expr}')

@tf_utils.shape_type_conversion
def build(self, input_shape):
    if not isinstance(input_shape[0], tuple):
        raise ValueError('A merge layer should be called on a list of inputs.')
    if len(input_shape) < 2:
        raise ValueError('A merge layer should be called on a list of at least 2 inputs. Got ' + str(len(input_shape)) + ' inputs.')
    batch_sizes = {s[0] for s in input_shape if s} - {None}
    if len(batch_sizes) > 1:
        raise ValueError('Can not merge tensors with different batch sizes. Got tensors with shapes : ' + str(input_shape))
    if input_shape[0] is None:
        output_shape = None
    else:
        output_shape = input_shape[0][1:]
    for i in range(1, len(input_shape)):
        if <MASK>:
            shape = None
        else:
            shape = input_shape[i][1:]
        output_shape = self._compute_elemwise_op_output_shape(output_shape, shape)
    if None not in input_shape and len(set(map(len, input_shape))) == 1:
        self._reshape_required = False
    else:
        self._reshape_required = True

def calc_info(self):
    lib_dirs = self.get_lib_dirs()
    info = {}
    opt = self.get_option_single('atlas_libs', 'libraries')
    atlas_libs = self.get_libs(opt, self._lib_names + self._lib_atlas)
    lapack_libs = self.get_libs('lapack_libs', self._lib_lapack)
    atlas = None
    lapack = None
    atlas_1 = None
    for d in lib_dirs:
        atlas = self.check_libs2(d, atlas_libs, [])
        if atlas is not None:
            lib_dirs2 = [d] + self.combine_paths(d, ['atlas*', 'ATLAS*'])
            lapack = self.check_libs2(lib_dirs2, lapack_libs, [])
            if lapack is not None:
                break
        if atlas:
            atlas_1 = atlas
    log.info(self.__class__)
    if atlas is None:
        atlas = atlas_1
    if atlas is None:
        return
    include_dirs = self.get_include_dirs()
    h = self.combine_paths(lib_dirs + include_dirs, 'cblas.h') or [None]
    h = h[0]
    if h:
        h = os.path.dirname(h)
        dict_append(info, include_dirs=[h])
    info['language'] = 'c'
    if lapack is not None:
        dict_append(info, **lapack)
        dict_append(info, **atlas)
    elif 'lapack_atlas' in atlas['libraries']:
        dict_append(info, **atlas)
        dict_append(info, define_macros=[('ATLAS_WITH_LAPACK_ATLAS', None)])
        self.set_info(**info)
        return
    else:
        dict_append(info, **atlas)
        dict_append(info, define_macros=[('ATLAS_WITHOUT_LAPACK', None)])
        message = textwrap.dedent('\n                *********************************************************************\n                    Could not find lapack library within the ATLAS installation.\n                *********************************************************************\n                ')
        warnings.warn(message, stacklevel=2)
        self.set_info(**info)
        return
    lapack_dir = lapack['library_dirs'][0]
    lapack_name = lapack['libraries'][0]
    lapack_lib = None
    lib_prefixes = ['lib']
    if sys.platform == 'win32':
        lib_prefixes.append('')
    for e in self.library_extensions():
        for prefix in lib_prefixes:
            fn = os.path.join(lapack_dir, prefix + lapack_name + e)
            if os.path.exists(fn):
                lapack_lib = fn
                break
        if lapack_lib:
            break
    if lapack_lib is not None:
        sz = os.stat(lapack_lib)[6]
        if <MASK>:
            message = textwrap.dedent('\n                    *********************************************************************\n                        Lapack library (from ATLAS) is probably incomplete:\n                          size of %s is %sk (expected >4000k)\n\n                        Follow the instructions in the KNOWN PROBLEMS section of the file\n                        numpy/INSTALL.txt.\n                    *********************************************************************\n                    ') % (lapack_lib, sz / 1024)
            warnings.warn(message, stacklevel=2)
        else:
            info['language'] = 'f77'
    (atlas_version, atlas_extra_info) = get_atlas_version(**atlas)
    dict_append(info, **atlas_extra_info)
    self.set_info(**info)

def blocks(tokens: Sequence[TokenInfo]) -> BlocksResult:
    blocks: list[Block] = []
    indent_to_dedent = _make_indent_dict(tokens)
    errors: dict[str, str] = {}

    def starts_block(t: TokenInfo) -> bool:
        return t.type == token.NAME and t.string in ('class', 'def')
    it = (i for (i, t) in enumerate(tokens) if starts_block(t))
    blocks = [_make_block(tokens, i, indent_to_dedent, errors) for i in it]
    for (i, parent) in enumerate(blocks):
        for j in range(i + 1, len(blocks)):
            if <MASK>:
                child.parent = i
                parent.children.append(j)
            else:
                break
    for (i, b) in enumerate(blocks):
        b.index = i
        parents = [b]
        while (p := parents[-1].parent) is not None:
            parents.append(blocks[p])
        parents = parents[1:]
        b.is_local = not all((p.is_class for p in parents))
        b.is_method = not b.is_class and bool(parents) and parents[0].is_class
    _add_full_names(blocks, [b for b in blocks if b.parent is None])
    return BlocksResult(blocks, errors)

def validate_synchronization_aggregation_trainable(synchronization, aggregation, trainable, name):
    """Given user-provided variable properties, sets defaults and validates."""
    if <MASK>:
        aggregation = variables.VariableAggregation.NONE
    elif not isinstance(aggregation, (variables.VariableAggregation, variables.VariableAggregationV2)):
        try:
            aggregation = variables.VariableAggregationV2(aggregation)
        except ValueError:
            raise ValueError('Invalid variable aggregation mode: {} for variable: {}'.format(aggregation, name))
    if synchronization is None:
        synchronization = variables.VariableSynchronization.AUTO
    else:
        try:
            synchronization = variables.VariableSynchronization(synchronization)
        except ValueError:
            raise ValueError('Invalid variable synchronization mode: {} for variable: {}'.format(synchronization, name))
    if trainable is None:
        trainable = synchronization != variables.VariableSynchronization.ON_READ
    return (synchronization, aggregation, trainable)

def _callback_from_stance(callback: DynamoCallback) -> DynamoCallback:
    if _stance.stance == 'default':
        if _stance.backend is not None and callback not in (False, None):
            callback = _create_wrapped_callback(get_compiler_fn(_stance.backend))
        return callback
    elif <MASK>:
        if callback not in (False, None):
            return _create_delayed_compile_callback(callback, _stance.stance)
        return callback
    elif _stance.stance == 'aot_eager_then_compile':
        if callback not in (False, None):
            return _create_delayed_compile_callback(callback, _stance.stance)
        return callback
    elif _stance.stance == 'force_eager':
        return None
    elif _stance.stance == 'eager_on_recompile':
        return False
    elif _stance.stance == 'fail_on_recompile':
        if callback in (False, None):
            return callback

        def fail_callback(frame: DynamoFrameType, *args: Any, **kwargs: Any) -> ConvertFrameReturn:
            if trace_rules.check(frame.f_code):
                return ConvertFrameReturn()
            if not convert_frame.has_tensor_in_frame(frame):
                return ConvertFrameReturn()
            from torch._C._dynamo.eval_frame import _debug_get_cache_entry_list, _debug_get_precompile_entries
            from torch._dynamo.guards import get_and_maybe_log_recompilation_reasons
            message = "Detected recompile when torch.compile stance is 'fail_on_recompile'. " + f"filename: '{frame.f_code.co_filename}', " + f"function name: '{frame.f_code.co_name}', " + f'line number: {frame.f_lineno}'
            cache_entries = _debug_get_cache_entry_list(frame.f_code)
            if cache_entries:
                reasons = get_and_maybe_log_recompilation_reasons(cache_entries[0], frame, skip_logging=True)
                if reasons:
                    failures = textwrap.indent('\n'.join(reasons), '- ')
                    guard_failure_details = f'triggered by the following guard failure(s):\n{failures}'
                    message += f"\n{textwrap.indent(guard_failure_details, '    ')}"
            precompile_entries = _debug_get_precompile_entries(frame.f_code)
            if len(precompile_entries) > 0:
                message += '\nFailed on the following precompiled guards: '
                for entry in precompile_entries:
                    message += f'\n{entry.guard_manager}{entry.guard_manager.check_verbose(frame.f_locals)}'
            raise RuntimeError(message)
        fail_callback._torchdynamo_orig_backend = callback
        return fail_callback
    else:
        raise RuntimeError(f"invalid torch.compile stance '{_stance}'")

def _serialize_keras_tensor(t):
    """Serializes a single Tensor passed to `call`."""
    if hasattr(t, '_keras_history'):
        kh = t._keras_history
        node_index = kh.node_index
        node_key = make_node_key(kh.layer.name, node_index)
        new_node_index = node_conversion_map.get(node_key, 0)
        return [kh.layer.name, new_node_index, kh.tensor_index]
    if isinstance(t, np.ndarray):
        return t.tolist()
    if <MASK>:
        return backend.get_value(t).tolist()
    return t

def __init__(self, optimizer: Optimizer, max_lr: Union[float, list[float]], total_steps: Optional[int]=None, epochs: Optional[int]=None, steps_per_epoch: Optional[int]=None, pct_start: float=0.3, anneal_strategy: Literal['cos', 'linear']='cos', cycle_momentum: bool=True, base_momentum: Union[float, list[float]]=0.85, max_momentum: Union[float, list[float]]=0.95, div_factor: float=25.0, final_div_factor: float=10000.0, three_phase: bool=False, last_epoch: int=-1):
    if not isinstance(optimizer, Optimizer):
        raise TypeError(f'{type(optimizer).__name__} is not an Optimizer')
    self.optimizer = optimizer
    if total_steps is not None:
        if <MASK>:
            raise ValueError(f'Expected positive integer total_steps, but got {total_steps}')
        self.total_steps = total_steps
    elif epochs is not None and steps_per_epoch is not None:
        if not isinstance(epochs, int) or epochs <= 0:
            raise ValueError(f'Expected positive integer epochs, but got {epochs}')
        if not isinstance(steps_per_epoch, int) or steps_per_epoch <= 0:
            raise ValueError(f'Expected positive integer steps_per_epoch, but got {steps_per_epoch}')
        self.total_steps = epochs * steps_per_epoch
    else:
        raise ValueError('You must define either total_steps OR (epochs AND steps_per_epoch)')
    self._schedule_phases: list[_SchedulePhase]
    if three_phase:
        self._schedule_phases = [{'end_step': float(pct_start * self.total_steps) - 1, 'start_lr': 'initial_lr', 'end_lr': 'max_lr', 'start_momentum': 'max_momentum', 'end_momentum': 'base_momentum'}, {'end_step': float(2 * pct_start * self.total_steps) - 2, 'start_lr': 'max_lr', 'end_lr': 'initial_lr', 'start_momentum': 'base_momentum', 'end_momentum': 'max_momentum'}, {'end_step': self.total_steps - 1, 'start_lr': 'initial_lr', 'end_lr': 'min_lr', 'start_momentum': 'max_momentum', 'end_momentum': 'max_momentum'}]
    else:
        self._schedule_phases = [{'end_step': float(pct_start * self.total_steps) - 1, 'start_lr': 'initial_lr', 'end_lr': 'max_lr', 'start_momentum': 'max_momentum', 'end_momentum': 'base_momentum'}, {'end_step': self.total_steps - 1, 'start_lr': 'max_lr', 'end_lr': 'min_lr', 'start_momentum': 'base_momentum', 'end_momentum': 'max_momentum'}]
    if pct_start < 0 or pct_start > 1 or (not isinstance(pct_start, float)):
        raise ValueError(f'Expected float between 0 and 1 pct_start, but got {pct_start}')
    if anneal_strategy not in ['cos', 'linear']:
        raise ValueError(f"anneal_strategy must be one of 'cos' or 'linear', instead got {anneal_strategy}")
    else:
        self._anneal_func_type = anneal_strategy
    max_lrs = _format_param('max_lr', self.optimizer, max_lr)
    if last_epoch == -1:
        for (idx, group) in enumerate(self.optimizer.param_groups):
            group['initial_lr'] = max_lrs[idx] / div_factor
            group['max_lr'] = max_lrs[idx]
            group['min_lr'] = group['initial_lr'] / final_div_factor
    self.cycle_momentum = cycle_momentum
    if self.cycle_momentum:
        if 'momentum' not in self.optimizer.defaults and 'betas' not in self.optimizer.defaults:
            raise ValueError('optimizer must support momentum or beta1 with `cycle_momentum` option enabled')
        self.use_beta1 = 'betas' in self.optimizer.defaults
        max_momentums = _format_param('max_momentum', optimizer, max_momentum)
        base_momentums = _format_param('base_momentum', optimizer, base_momentum)
        if last_epoch == -1:
            for (m_momentum, b_momentum, group) in zip(max_momentums, base_momentums, optimizer.param_groups):
                if self.use_beta1:
                    group['betas'] = (m_momentum, *group['betas'][1:])
                else:
                    group['momentum'] = m_momentum
                group['max_momentum'] = m_momentum
                group['base_momentum'] = b_momentum
    super().__init__(optimizer, last_epoch)

def tensor(data, *, dtype=None, device=None, pin_memory=False, requires_grad=False):
    if isinstance(data, torch.Tensor):
        warnings.warn('To copy construct from a tensor, it is recommended to use sourceTensor.detach().clone() or sourceTensor.detach().clone().requires_grad_(True), rather than torch.tensor(sourceTensor)', UserWarning, stacklevel=2)
    type_inference = dtype is None
    new_tensor = _internal_new_from_data({'device': 'cpu'}, dtype if dtype is not None else torch.get_default_dtype(), device, data, copy_variables=True, copy_numpy=True, type_inference=type_inference, pin_memory=pin_memory)
    new_tensor.detach_()
    if <MASK>:
        new_tensor.requires_grad_(requires_grad)
    return new_tensor

def _setitem_with_indexer_split_path(self, indexer, value, name: str):
    """
        Setitem column-wise.
        """
    assert self.ndim == 2
    if not isinstance(indexer, tuple):
        indexer = _tuplify(self.ndim, indexer)
    if len(indexer) > self.ndim:
        raise IndexError('too many indices for array')
    if isinstance(indexer[0], np.ndarray) and indexer[0].ndim > 2:
        raise ValueError('Cannot set values with ndim > 2')
    if isinstance(value, ABCSeries) and name != 'iloc' or isinstance(value, dict):
        from pandas import Series
        value = self._align_series(indexer, Series(value))
    info_axis = indexer[1]
    ilocs = self._ensure_iterable_column_indexer(info_axis)
    pi = indexer[0]
    lplane_indexer = length_of_indexer(pi, self.obj.index)
    if is_list_like_indexer(value) and getattr(value, 'ndim', 1) > 0:
        if isinstance(value, ABCDataFrame):
            self._setitem_with_indexer_frame_value(indexer, value, name)
        elif <MASK>:
            self._setitem_with_indexer_2d_value(indexer, value)
        elif len(ilocs) == 1 and lplane_indexer == len(value) and (not is_scalar(pi)):
            self._setitem_single_column(ilocs[0], value, pi)
        elif len(ilocs) == 1 and 0 != lplane_indexer != len(value):
            if len(value) == 1 and (not is_integer(info_axis)):
                return self._setitem_with_indexer((pi, info_axis[0]), value[0])
            raise ValueError('Must have equal len keys and value when setting with an iterable')
        elif lplane_indexer == 0 and len(value) == len(self.obj.index):
            pass
        elif self._is_scalar_access(indexer) and is_object_dtype(self.obj.dtypes._values[ilocs[0]]):
            self._setitem_single_column(indexer[1], value, pi)
        elif len(ilocs) == len(value):
            for (loc, v) in zip(ilocs, value, strict=True):
                self._setitem_single_column(loc, v, pi)
        elif len(ilocs) == 1 and com.is_null_slice(pi) and (len(self.obj) == 0):
            self._setitem_single_column(ilocs[0], value, pi)
        else:
            raise ValueError('Must have equal len keys and value when setting with an iterable')
    else:
        for loc in ilocs:
            self._setitem_single_column(loc, value, pi)

def _check(self):
    if hasattr(self, 'estimators_'):
        return all((hasattr(est, attr) for est in self.estimators_))
    if <MASK>:
        return True
    return False

def __getattr__(self, key: str) -> OpOverload[_P, _T]:
    try:
        if <MASK>:
            return getattr(self._op, key)
    except AttributeError:
        raise AttributeError(f"'{str(self)}' can't have an overload name beginning with '__' and the underlying op {str(self._op)} has no attribute {key} either.") from None
    try:
        use_key = '' if key == 'default' else key
        op_dk_tags = torch._C._get_operation_overload(self._qualified_op_name, use_key)
        if op_dk_tags is None:
            raise AttributeError(f"The underlying op of '{str(self)}' has no overload name '{key}'")
        (op_, op_dk_, tags) = op_dk_tags
        schema = torch._C._get_schema(self._qualified_op_name, use_key)
        overload: OpOverload[_P, _T] = OpOverload(self, op_, op_dk_, schema, tags) if not _has_script_object_arg(schema) else TorchBindOpOverload(self, op_, op_dk_, schema, tags)
        setattr(self, key, overload)
        self._dir.append(key)
        return overload
    except RuntimeError:
        raise AttributeError(f"The underlying op of '{str(self)}' has no overload name '{key}'") from None

def __init__(self, concentration: Tensor, validate_args: Optional[bool]=None) -> None:
    if <MASK>:
        raise ValueError('`concentration` parameter must be at least one-dimensional.')
    self.concentration = concentration
    (batch_shape, event_shape) = (concentration.shape[:-1], concentration.shape[-1:])
    super().__init__(batch_shape, event_shape, validate_args=validate_args)

def _fit_stages(self, X, y, raw_predictions, sample_weight, random_state, X_val, y_val, sample_weight_val, begin_at_stage=0, monitor=None):
    """Iteratively fits the stages.

        For each stage it computes the progress (OOB, train score)
        and delegates to ``_fit_stage``.
        Returns the number of stages fit; might differ from ``n_estimators``
        due to early stopping.
        """
    n_samples = X.shape[0]
    do_oob = self.subsample < 1.0
    sample_mask = np.ones((n_samples,), dtype=bool)
    n_inbag = max(1, int(self.subsample * n_samples))
    if self.verbose:
        verbose_reporter = VerboseReporter(verbose=self.verbose)
        verbose_reporter.init(self, begin_at_stage)
    X_csc = csc_matrix(X) if issparse(X) else None
    X_csr = csr_matrix(X) if issparse(X) else None
    if <MASK>:
        loss_history = np.full(self.n_iter_no_change, np.inf)
        y_val_pred_iter = self._staged_raw_predict(X_val, check_input=False)
    if isinstance(self._loss, (HalfSquaredError, HalfBinomialLoss)):
        factor = 2
    else:
        factor = 1
    i = begin_at_stage
    for i in range(begin_at_stage, self.n_estimators):
        if do_oob:
            sample_mask = _random_sample_mask(n_samples, n_inbag, random_state)
            y_oob_masked = y[~sample_mask]
            sample_weight_oob_masked = sample_weight[~sample_mask]
            if i == 0:
                initial_loss = factor * self._loss(y_true=y_oob_masked, raw_prediction=raw_predictions[~sample_mask], sample_weight=sample_weight_oob_masked)
        raw_predictions = self._fit_stage(i, X, y, raw_predictions, sample_weight, sample_mask, random_state, X_csc=X_csc, X_csr=X_csr)
        if do_oob:
            self.train_score_[i] = factor * self._loss(y_true=y[sample_mask], raw_prediction=raw_predictions[sample_mask], sample_weight=sample_weight[sample_mask])
            self.oob_scores_[i] = factor * self._loss(y_true=y_oob_masked, raw_prediction=raw_predictions[~sample_mask], sample_weight=sample_weight_oob_masked)
            previous_loss = initial_loss if i == 0 else self.oob_scores_[i - 1]
            self.oob_improvement_[i] = previous_loss - self.oob_scores_[i]
            self.oob_score_ = self.oob_scores_[-1]
        else:
            self.train_score_[i] = factor * self._loss(y_true=y, raw_prediction=raw_predictions, sample_weight=sample_weight)
        if self.verbose > 0:
            verbose_reporter.update(i, self)
        if monitor is not None:
            early_stopping = monitor(i, self, locals())
            if early_stopping:
                break
        if self.n_iter_no_change is not None:
            validation_loss = factor * self._loss(y_val, next(y_val_pred_iter), sample_weight_val)
            if np.any(validation_loss + self.tol < loss_history):
                loss_history[i % len(loss_history)] = validation_loss
            else:
                break
    return i + 1

def update(self, parameters: Union[Mapping[str, Any], ParameterDict]) -> None:
    """Update the :class:`~torch.nn.ParameterDict` with key-value pairs from ``parameters``, overwriting existing keys.

        .. note::
            If :attr:`parameters` is an ``OrderedDict``, a :class:`~torch.nn.ParameterDict`, or
            an iterable of key-value pairs, the order of new elements in it is preserved.

        Args:
            parameters (iterable): a mapping (dictionary) from string to
                :class:`~torch.nn.Parameter`, or an iterable of
                key-value pairs of type (string, :class:`~torch.nn.Parameter`)
        """
    if not isinstance(parameters, container_abcs.Iterable):
        raise TypeError('ParametersDict.update should be called with an iterable of key/value pairs, but got ' + type(parameters).__name__)
    if <MASK>:
        for (key, parameter) in parameters.items():
            self[key] = parameter
    elif isinstance(parameters, container_abcs.Mapping):
        for (key, parameter) in sorted(parameters.items()):
            self[key] = parameter
    else:
        for (j, p) in enumerate(parameters):
            if not isinstance(p, container_abcs.Iterable):
                raise TypeError('ParameterDict update sequence element #' + str(j) + ' should be Iterable; is' + type(p).__name__)
            if not len(p) == 2:
                raise ValueError('ParameterDict update sequence element #' + str(j) + ' has length ' + str(len(p)) + '; 2 is required')
            self[p[0]] = p[1]

def _clean_form(self):
    try:
