def __init__(self, kernel_size: _size_3_t, output_size: Optional[_size_3_t]=None, output_ratio: Optional[_ratio_3_t]=None, return_indices: bool=False, _random_samples=None) -> None:
    super().__init__()
    if isinstance(kernel_size, int) and kernel_size <= 0 or (isinstance(kernel_size, (tuple, list)) and (not all((k > 0 for k in kernel_size)))):
        raise ValueError(f'kernel_size must greater than 0, but got {kernel_size}')
    self.kernel_size = _triple(kernel_size)
    self.return_indices = return_indices
    self.register_buffer('_random_samples', _random_samples)
    self.output_size = _triple(output_size) if output_size is not None else None
    self.output_ratio = _triple(output_ratio) if output_ratio is not None else None
    if <MASK>:
        raise ValueError('FractionalMaxPool3d requires specifying either an output size, or a pooling ratio')
    if output_size is not None and output_ratio is not None:
        raise ValueError('only one of output_size and output_ratio may be specified')
    if self.output_ratio is not None:
        if not (0 < self.output_ratio[0] < 1 and 0 < self.output_ratio[1] < 1 and (0 < self.output_ratio[2] < 1)):
            raise ValueError(f'output_ratio must be between 0 and 1 (got {output_ratio})')

def reference_sgn(x):
    if x.dtype not in [np.complex64, np.complex128]:
        return reference_sign(x)
    out = x / np.abs(x)
    if out.ndim == 0:
        if <MASK>:
            return np.array(complex(0, 0), dtype=x.dtype)
        return out
    mask = x == 0
    out[mask] = complex(0, 0)
    return out

def add_constants_to_call_args(call_args: Sequence[Any], cfg: Config) -> tuple[Any, ...]:
    """
            Add constant kwargs to the arg list.
            """
    new_call_args = []
    constants = triton_meta['constants']
    call_kwargs = {key: val for (key, val) in zip(signature, call_args) if key not in constants and key not in cfg.kwargs}
    call_kwargs |= constants
    new_call_args = [call_kwargs[key] for key in signature if key not in cfg.kwargs]
    if <MASK>:
        new_call_args.extend(call_args[len(call_args) - len(extra_launcher_args):])
    return tuple(new_call_args)

@final
@cache_readonly
def _axes_and_fig(self) -> tuple[Sequence[Axes], Figure]:
    import matplotlib.pyplot as plt
    if self.subplots:
        naxes = self.nseries if isinstance(self.subplots, bool) else len(self.subplots)
        (fig, axes) = create_subplots(naxes=naxes, sharex=self.sharex, sharey=self.sharey, figsize=self.figsize, ax=self.ax, layout=self.layout, layout_type=self._layout_type)
    elif self.ax is None:
        fig = plt.figure(figsize=self.figsize)
        axes = fig.add_subplot(111)
    else:
        fig = self.ax.get_figure()
        if self.figsize is not None:
            fig.set_size_inches(self.figsize)
        axes = self.ax
    axes = np.fromiter(flatten_axes(axes), dtype=object)
    if <MASK>:
        [a.set_xscale('log') for a in axes]
    elif self.logx == 'sym' or self.loglog == 'sym':
        [a.set_xscale('symlog') for a in axes]
    if self.logy is True or self.loglog is True:
        [a.set_yscale('log') for a in axes]
    elif self.logy == 'sym' or self.loglog == 'sym':
        [a.set_yscale('symlog') for a in axes]
    axes_seq = cast(Sequence['Axes'], axes)
    return (axes_seq, fig)

@register_op_strategy(aten.slice.Tensor, schema_info=RuntimeSchemaInfo(1))
def gen_slice_strategy(op_schema: OpSchema) -> StrategyType:
    """Forward all shardings except the slice dimension."""
    defaults = (None, 0, None, None, 1)
    (input_strategy, dim, start, end, step) = op_schema.args_schema + defaults[len(op_schema.args_schema):]
    if not isinstance(input_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(input_strategy)}')
    mesh = input_strategy.mesh
    input_shape = input_strategy.shape
    input_ndim = input_strategy.ndim
    if not isinstance(dim, int):
        raise AssertionError(f'Expected int, got {type(dim)}')
    if start is None:
        start = 0
    if end is None or end > input_shape[dim]:
        end = input_shape[dim]
    if not isinstance(start, IntLike):
        raise AssertionError(f'Expected IntLike, got {type(start)}')
    if not isinstance(end, IntLike):
        raise AssertionError(f'Expected IntLike, got {type(end)}')
    if not isinstance(step, IntLike):
        raise AssertionError(f'Expected IntLike, got {type(step)}')
    slice_dim = normalize_dim(dim, input_ndim)
    start = normalize_dim(start, input_shape[dim])
    end = normalize_dim(end, input_shape[dim])
    redundant_slice = start == 0 and end == input_shape[dim] and (step == 1)
    slice_strategy = OpStrategy([])
    for arg_strategy in input_strategy.strategies:
        arg_spec = arg_strategy.output_spec
        if not is_tensor_dim_sharded(arg_spec, dim=slice_dim) or redundant_slice:
            out_spec = DTensorSpec(mesh, arg_spec.placements)
            slice_strategy.strategies.append(OpSpec(output_specs=out_spec, input_specs=(arg_spec,), redistribute_cost=[[0.0] * len(input_strategy.strategies)]))
    if <MASK>:
        for arg_strategy in input_strategy.strategies:
            arg_spec = arg_strategy.output_spec
            unshard_spec = DTensorSpec(mesh, unshard_tensor_dim(arg_spec.placements, dim=slice_dim))
            slice_strategy.strategies.append(OpSpec(output_specs=unshard_spec, redistribute_cost=[generate_redistribute_costs(input_strategy, unshard_spec)]))
    return slice_strategy

def make_decorator(target, decorator_func, decorator_name=None, decorator_doc='', decorator_argspec=None):
    """Make a decorator from a wrapper and a target.

  Args:
    target: The final callable to be wrapped.
    decorator_func: The wrapper function.
    decorator_name: The name of the decorator. If `None`, the name of the
      function calling make_decorator.
    decorator_doc: Documentation specific to this application of
      `decorator_func` to `target`.
    decorator_argspec: Override the signature using FullArgSpec.

  Returns:
    The `decorator_func` argument with new metadata attached.
  """
    if decorator_name is None:
        decorator_name = inspect.currentframe().f_back.f_code.co_name
    decorator = TFDecorator(decorator_name, target, decorator_doc, decorator_argspec)
    setattr(decorator_func, '_tf_decorator', decorator)
    if hasattr(target, '__name__'):
        decorator_func.__name__ = target.__name__
    if hasattr(target, '__qualname__'):
        decorator_func.__qualname__ = target.__qualname__
    if hasattr(target, '__module__'):
        decorator_func.__module__ = target.__module__
    if hasattr(target, '__dict__'):
        for name in target.__dict__:
            if name not in decorator_func.__dict__:
                decorator_func.__dict__[name] = target.__dict__[name]
    if hasattr(target, '__doc__'):
        decorator_func.__doc__ = decorator.__doc__
    decorator_func.__wrapped__ = target
    decorator_func.__original_wrapped__ = target
    if <MASK>:
        decorator_func.__signature__ = fullargspec_to_signature(decorator_argspec)
    elif callable(target):
        try:
            signature = inspect.signature(target)
        except (TypeError, ValueError):
            pass
        else:
            bound_instance = _get_bound_instance(target)
            if bound_instance and 'self' in signature.parameters:
                signature = inspect.Signature(list(signature.parameters.values())[1:])
                decorator_func.__self__ = bound_instance
            decorator_func.__signature__ = signature
    return decorator_func

@_onnx_symbolic('aten::__getitem_')
def __getitem_(g: jit_utils.GraphContext, self, i):
    if <MASK>:
        return g.op('SequenceAt', self, i)
    else:
