        return getitem(g, self, i)

def _run(self, sess, enqueue_op, coord=None):
    """Execute the enqueue op in a loop, close the queue in case of error.

    Args:
      sess: A Session.
      enqueue_op: The Operation to run.
      coord: Optional Coordinator object for reporting errors and checking
        for stop conditions.
    """
    decremented = False
    try:
        enqueue_callable = sess.make_callable(enqueue_op)
        while True:
            if coord and coord.should_stop():
                break
            try:
                enqueue_callable()
            except self._queue_closed_exception_types:
                with self._lock:
                    self._runs_per_session[sess] -= 1
                    decremented = True
                    if self._runs_per_session[sess] == 0:
                        try:
                            sess.run(self._close_op)
                        except Exception as e:
                            logging.vlog(1, 'Ignored exception: %s', str(e))
                    return
    except Exception as e:
        if <MASK>:
            coord.request_stop(e)
        else:
            logging.error('Exception in QueueRunner: %s', str(e))
            with self._lock:
                self._exceptions_raised.append(e)
            raise
    finally:
        if not decremented:
            with self._lock:
                self._runs_per_session[sess] -= 1

@register_jagged_func(torch.ops.aten.broadcast_to.default, 'self: jt_all, size: any')
def broadcast_to(func, *args, **kwargs):
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    inp = new_kwargs.pop('input')
    size = new_kwargs.pop('size')
    if <MASK>:
        return inp.expand([*(1 for _ in range(inp.dim() - len(size))), *size])
    raise ValueError('broadcast_to(): broadcasting to a higher-dim shape is currently not supported for nested tensors with the jagged layout')

def _multiplicative_update_h(X, W, H, beta_loss, l1_reg_H, l2_reg_H, gamma, A=None, B=None, rho=None):
    """update H in Multiplicative Update NMF."""
    if beta_loss == 2:
        numerator = safe_sparse_dot(W.T, X)
        denominator = np.linalg.multi_dot([W.T, W, H])
    else:
        WH_safe_X = _special_sparse_dot(W, H, X)
        if sp.issparse(X):
            WH_safe_X_data = WH_safe_X.data
            X_data = X.data
        else:
            WH_safe_X_data = WH_safe_X
            X_data = X
            WH = WH_safe_X.copy()
            if beta_loss - 1.0 < 0:
                WH[WH < EPSILON] = EPSILON
        if beta_loss - 2.0 < 0:
            WH_safe_X_data[WH_safe_X_data < EPSILON] = EPSILON
        if beta_loss == 1:
            np.divide(X_data, WH_safe_X_data, out=WH_safe_X_data)
        elif beta_loss == 0:
            WH_safe_X_data **= -1
            WH_safe_X_data **= 2
            WH_safe_X_data *= X_data
        else:
            WH_safe_X_data **= beta_loss - 2
            WH_safe_X_data *= X_data
        numerator = safe_sparse_dot(W.T, WH_safe_X)
        if beta_loss == 1:
            W_sum = np.sum(W, axis=0)
            W_sum[W_sum == 0] = 1.0
            denominator = W_sum[:, np.newaxis]
        else:
            if sp.issparse(X):
                WtWH = np.empty(H.shape)
                for i in range(X.shape[1]):
                    WHi = np.dot(W, H[:, i])
                    if beta_loss - 1 < 0:
                        WHi[WHi < EPSILON] = EPSILON
                    WHi **= beta_loss - 1
                    WtWH[:, i] = np.dot(W.T, WHi)
            else:
                WH **= beta_loss - 1
                WtWH = np.dot(W.T, WH)
            denominator = WtWH
    if l1_reg_H > 0:
        denominator += l1_reg_H
    if l2_reg_H > 0:
        denominator = denominator + l2_reg_H * H
    denominator[denominator == 0] = EPSILON
    if <MASK>:
        if gamma != 1:
            H **= 1 / gamma
        numerator *= H
        A *= rho
        B *= rho
        A += numerator
        B += denominator
        H = A / B
        if gamma != 1:
            H **= gamma
    else:
        delta_H = numerator
        delta_H /= denominator
        if gamma != 1:
            delta_H **= gamma
        H *= delta_H
    return H

def _determine_key_type(key, accept_slice=True):
    """Determine the data type of key.

    Parameters
    ----------
    key : scalar, slice or array-like
        The key from which we want to infer the data type.

    accept_slice : bool, default=True
        Whether or not to raise an error if the key is a slice.

    Returns
    -------
    dtype : {'int', 'str', 'bool', None}
        Returns the data type of key.
    """
    err_msg = 'No valid specification of the columns. Only a scalar, list or slice of all integers or all strings, or boolean mask is allowed'
    dtype_to_str = {int: 'int', str: 'str', bool: 'bool', np.bool_: 'bool'}
    array_dtype_to_str = {'i': 'int', 'u': 'int', 'b': 'bool', 'O': 'str', 'U': 'str', 'S': 'str'}
    if key is None:
        return None
    if isinstance(key, tuple(dtype_to_str.keys())):
        try:
            return dtype_to_str[type(key)]
        except KeyError:
            raise ValueError(err_msg)
    if isinstance(key, slice):
        if <MASK>:
            raise TypeError('Only array-like or scalar are supported. A Python slice was given.')
        if key.start is None and key.stop is None:
            return None
        key_start_type = _determine_key_type(key.start)
        key_stop_type = _determine_key_type(key.stop)
        if key_start_type is not None and key_stop_type is not None:
            if key_start_type != key_stop_type:
                raise ValueError(err_msg)
        if key_start_type is not None:
            return key_start_type
        return key_stop_type
    if isinstance(key, (list, tuple, UserList)):
        unique_key = set(key)
        key_type = {_determine_key_type(elt) for elt in unique_key}
        if not key_type:
            return None
        if len(key_type) != 1:
            raise ValueError(err_msg)
        return key_type.pop()
    if hasattr(key, 'dtype'):
        (xp, is_array_api) = get_namespace(key)
        if is_array_api and (not _is_numpy_namespace(xp)):
            if xp.isdtype(key.dtype, 'bool'):
                return 'bool'
            elif xp.isdtype(key.dtype, 'integral'):
                return 'int'
            else:
                raise ValueError(err_msg)
        else:
            try:
                return array_dtype_to_str[key.dtype.kind]
            except KeyError:
                raise ValueError(err_msg)
    raise ValueError(err_msg)

def _prepare_feed_values(model, inputs, targets, sample_weights, mode):
    """Prepare feed values to the model execution function.

  Args:
    model: Model to prepare feed values for.
    inputs: List or dict of model inputs.
    targets: Optional list of model targets.
    sample_weights: Optional list of sample weight arrays.
    mode: One of ModeKeys.TRAIN/ModeKeys.TEST/ModeKeys.PREDICT.

  Returns:
    Feed values for the model in the given mode.
  """
    strategy = model._distribution_strategy
    (inputs, targets, sample_weights) = _get_input_from_iterator(inputs, model)
    if <MASK>:
        if sample_weights is not None:
            raise ValueError('TPUStrategy does not support sample weights.')
    if isinstance(inputs, dict):
        inputs = [inputs[key] for key in model._feed_input_names]
    if is_distributing_by_cloning(model):
        inputs = flatten_per_replica_values(strategy, inputs)
        targets = flatten_per_replica_values(strategy, targets)
        (inputs, targets) = nest.map_structure(training_utils_v1.standardize_single_array, (inputs, targets))
    else:
        inputs = training_utils_v1.ModelInputs(inputs).as_list()
    if mode == ModeKeys.PREDICT:
        sample_weights = []
        targets = []
    elif sample_weights is not None and is_distributing_by_cloning(model):
        if context.executing_eagerly() and (not model._compile_distribution):
            raise NotImplementedError('`sample_weight` is not supported when using tf.distribute.Strategy in eager mode and cloning=True.')
        sample_weights = flatten_per_replica_values(strategy, sample_weights)
    ins = [inputs, targets, sample_weights]
    return tuple(ins)

@register_make_test_function()
def make_gather_tests(options):
    """Make a set of tests to do gather."""
    test_parameters = [{'params_dtype': [tf.float32, tf.int32, tf.int64, tf.int16], 'params_shape': [[1, 2, 20]], 'indices_dtype': [tf.int32, tf.int64], 'indices_shape': [[3], [5]], 'axis': [-1, 0, 1], 'batch_dims': [0], 'constant_params': [False, True]}, {'params_dtype': [tf.string], 'params_shape': [[8]], 'indices_dtype': [tf.int32], 'indices_shape': [[3], [3, 2]], 'axis': [0], 'batch_dims': [0], 'constant_params': [False, True]}, {'params_dtype': [tf.float32], 'params_shape': [[1, 2, 20]], 'indices_dtype': [tf.int32, tf.int64], 'indices_shape': [[3], [5]], 'axis': [-1, 0, 1], 'batch_dims': [0], 'constant_params': [False], 'constant_indices': [True], 'fully_quantize': [True], 'input_range': [(-10, 10)]}, {'params_dtype': [tf.float32, tf.int32], 'params_shape': [[2, 2, 3, 5]], 'indices_dtype': [tf.int32], 'indices_shape': [[2, 2, 2]], 'axis': [0, 2], 'batch_dims': [1, 2], 'constant_params': [False, True]}]

    def build_graph(parameters):
        """Build the gather op testing graph."""
        inputs = []
        if parameters['constant_params']:
            params = create_tensor_data(parameters['params_dtype'], parameters['params_shape'])
        else:
            params = tf.compat.v1.placeholder(dtype=parameters['params_dtype'], name='params', shape=parameters['params_shape'])
            inputs.append(params)
        if parameters.get('constant_indices', False):
            indices = create_tensor_data(parameters['indices_dtype'], parameters['indices_shape'], min_value=0, max_value=parameters['params_shape'][0] - 1)
        else:
            indices = tf.compat.v1.placeholder(dtype=parameters['indices_dtype'], name='indices', shape=parameters['indices_shape'])
            inputs.append(indices)
        axis = min(len(parameters['params_shape']), parameters['axis'])
        out = tf.gather(params, indices, axis=axis, batch_dims=parameters['batch_dims'])
        return (inputs, [out])

    def build_inputs(parameters, sess, inputs, outputs):
        input_values = []
        (min_value, max_value) = parameters.get('input_range', (-10, 10))
        if not parameters['constant_params']:
            params = create_tensor_data(parameters['params_dtype'], parameters['params_shape'], min_value=min_value, max_value=max_value)
            input_values.append(params)
        if <MASK>:
            indices = create_tensor_data(parameters['indices_dtype'], parameters['indices_shape'], min_value=0, max_value=parameters['params_shape'][0] - 1)
            input_values.append(indices)
        return (input_values, sess.run(outputs, feed_dict=dict(zip(inputs, input_values))))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs, expected_tf_failures=0)

def creator_with_resource_vars(next_creator, **kwargs):
    """Variable creator to use in `_CurrentDistributionContext`."""
    if ops.inside_function():
        if_graph_building = 'graph_building'
    else:
        if_graph_building = 'not_graph_building'
    with monitoring.MonitoredTimer(distributed_variable_creation_time_counter.get_cell(strategy.__class__.__name__, if_graph_building)):
        _require_strategy_scope_extended(self)
        kwargs['use_resource'] = True
        kwargs['distribute_strategy'] = strategy
        if isinstance(kwargs['initial_value'], trackable.CheckpointInitialValue):
            checkpoint_restore_uid = kwargs['initial_value'].checkpoint_position.restore_uid
            kwargs['initial_value'] = kwargs['initial_value'].wrapped_value
        elif isinstance(kwargs['initial_value'], trackable.CheckpointInitialValueCallable):
            checkpoint_restore_uid = kwargs['initial_value'].checkpoint_position.restore_uid
        elif <MASK>:
            checkpoint_restore_uid = kwargs['initial_value'].func.checkpoint_position.restore_uid
        else:
            checkpoint_restore_uid = None
        created = self._create_variable(next_creator, **kwargs)
        if checkpoint_restore_uid is not None:
            created._maybe_initialize_trackable()
            created._update_uid = checkpoint_restore_uid
        return created

def compute_elementwise_output_strides(*tensors) -> tuple[int, ...]:
    """
    Computes the output strides for elementwise operations.
    """
    if len(tensors) == 0:
        msg = "Can't compute elementwise output strides for zero tensors!"
        raise ValueError(msg)
    check_same_shape(*tensors, allow_cpu_scalar_tensors=True)
    tensors = tuple((a for a in tensors if isinstance(a, TensorLike) and (not is_cpu_scalar_tensor(a))))
    if len(tensors) == 0:
        return ()
    ndim = tensors[0].ndim
    shape = tensors[0].shape
    if <MASK>:
        return ()
    if ndim == 1:
        return (1,)
    (logical_to_physical_perm, _) = compute_elementwise_output_logical_to_physical_perm(*tensors, _skip_checks=True)
    permuted_shape = apply_perm(shape, logical_to_physical_perm)
    new_strides = make_contiguous_strides_for(permuted_shape)
    permuted_strides = apply_perm(new_strides, invert_perm(logical_to_physical_perm))
    return tuple(permuted_strides)

@with_native_function
def compute_ufunc_cpu_kernel(g: NativeFunctionsGroup) -> str:
    stub_sig = StubSignature(g)
    loops = g.out.ufunc_inner_loop
    ufunc_sigs: dict[ScalarType, dict[UfuncKey, UfuncSignature]] = {}
    for k in [UfuncKey.CPUScalar, UfuncKey.CPUVector]:
        lks = []
        if k in loops:
            lks.append(k)
        if <MASK>:
            lks.append(UfuncKey.ScalarOnly)
        if UfuncKey.Generic in loops:
            lks.append(UfuncKey.Generic)
        for lk in lks:
            for dtype in loops[lk].supported_dtypes:
                compute_t: CType
                if k is UfuncKey.CPUScalar:
                    compute_t = BaseCType(scalar_t)
                elif k is UfuncKey.CPUVector:
                    compute_t = VectorizedCType(BaseCType(scalar_t))
                else:
                    raise AssertionError
                inner_ufunc_sigs = ufunc_sigs.setdefault(dtype, {})
                if k not in inner_ufunc_sigs:
                    inner_ufunc_sigs[k] = UfuncSignature(g, name=f'ufunc::{loops[lk].name}', compute_t=compute_t)
    dtype_cases = []
    for (dtype, inner_ufunc_sigs) in ufunc_sigs.items():
        dtype_cases.append(f'\nAT_DISPATCH_CASE(at::ScalarType::{dtype},\n  [&]() {{\n    {compute_ufunc_cpu_dtype_body(g, dtype, inner_ufunc_sigs, stub_sig.arguments())}\n  }}\n)\n')
    dtype_cases_str = '\n'.join(dtype_cases)
    return f'\nnamespace {{\n\n{stub_sig.kernel_defn()} {{\n  AT_DISPATCH_SWITCH(iter.common_dtype(), "{stub_sig.name}",\n    {dtype_cases_str}\n  );\n}}\n\n}} // anonymous namespace\n\n{stub_sig.type_defn()};\n{stub_sig.dispatch_decl()}\nREGISTER_DISPATCH({stub_sig.name}, &{stub_sig.kernel_name})\n'

def _concrete_function_callable_with(function, inputs, allow_conversion):
    """Returns whether concrete `function` can be called with `inputs`."""
    expected_structure = function.graph.structured_input_signature
    try:
        flatten_inputs = nest.flatten_up_to(expected_structure, inputs)
    except (TypeError, ValueError):
        return False
    for (arg, expected) in zip(flatten_inputs, nest.flatten(expected_structure)):
        if isinstance(expected, tensor.TensorSpec):
            if allow_conversion:
                arg = _try_convert_to_tensor_spec(arg, dtype_hint=expected.dtype)
            if not _is_tensor(arg) and (not isinstance(arg, tensor.TensorSpec)):
                return False
            if arg.dtype != expected.dtype:
                return False
            if <MASK>:
                return False
        elif isinstance(expected, type_spec.TypeSpec):
            if not expected.is_compatible_with(arg):
                return False
        elif _is_tensor(arg):
            if id(arg) != id(expected):
                return False
        elif arg != expected:
            return False
    return True

def visit_While(self, node):
    assert not self._pending_statements
    self.visit(node.test)
    node.test = self._ensure_node_in_anf(node, 'test', node.test)
    if <MASK>:
        msg = 'While with nontrivial test not supported yet (need to avoid precomputing the test).'
        raise ValueError(msg)
    return self.generic_visit(node)

def _from_proto(self, pb):
    if pb.WhichOneof('optional_deterministic') is not None:
        self.deterministic = pb.deterministic
    self.autotune._from_proto(pb.autotune_options)
    self.experimental_distribute._from_proto(pb.distribute_options)
    if pb.WhichOneof('optional_external_state_policy') is not None:
        self.experimental_external_state_policy = ExternalStatePolicy._from_proto(pb.external_state_policy)
    self.experimental_optimization._from_proto(pb.optimization_options)
    if pb.WhichOneof('optional_slack') is not None:
        self.experimental_slack = pb.slack
    if pb.WhichOneof('optional_symbolic_checkpoint') is not None:
        self.experimental_symbolic_checkpoint = pb.symbolic_checkpoint
    if pb.WhichOneof('optional_warm_start') is not None:
        self.experimental_warm_start = pb.warm_start
    if pb.WhichOneof('optional_dataset_name') is not None:
        self.dataset_name = pb.dataset_name
    if <MASK>:
        self.framework_type = []
        for framework_type in pb.framework_type:
            self.framework_type.append(framework_type)
    self.experimental_service._from_proto(pb.service_options)
    self.threading._from_proto(pb.threading_options)

def to_dtype_bitcast(x: TensorBox, dtype: torch.dtype, *, copy=False):
    x_dtype = x.get_dtype()
    if <MASK>:
        return clone(x) if copy else x

    def _get_primitive_bitwidth(dtype):
        if dtype.is_floating_point:
            return torch.finfo(dtype).bits
        else:
            return torch.iinfo(dtype).bits
    src_bits = _get_primitive_bitwidth(x_dtype)
    dst_bits = _get_primitive_bitwidth(dtype)
    if src_bits != dst_bits:
        return fallback_handler(aten.view.dtype)(x, dtype)
    else:
        return TensorBox(DtypeView.create(x, dtype))

def _derive_follow_placements_from_tuple_strategy(op: torch._ops.OpOverload, tuple_strategy: TupleStrategy) -> Sequence[Placement]:
    """
    derive the placements to follow from the tuple strategy, mainly used by
    aten.stack, aten.cat, where each operand have the same shape, and correspondingly
    expecting the same sharding
    """

    def merge_placement(cur_placement: Placement, new_placement: Placement) -> Placement:
        if cur_placement == new_placement:
            return cur_placement
        if <MASK>:
            if new_placement.is_shard():
                return new_placement
            elif new_placement.is_partial():
                return Replicate()
            else:
                return cur_placement
        elif cur_placement.is_shard():
            if new_placement.is_shard():
                return Replicate()
            else:
                return cur_placement
        else:
            return new_placement
    follow_placements: Optional[list[Placement]] = None
    mesh = tuple_strategy.child_mesh(0)
    for arg_strategy in tuple_strategy.children:
        if not isinstance(arg_strategy, OpStrategy):
            raise AssertionError(f'Expected OpStrategy, got {type(arg_strategy)}')
        if arg_strategy.mesh != mesh:
            raise ValueError(f'All operands in {op} must have the same mesh, but got {arg_strategy.mesh} and {mesh}.')
        for placement_strategy in arg_strategy.strategies:
            arg_placements = placement_strategy.output_spec.placements
            if follow_placements is None:
                follow_placements = list(arg_placements)
                continue
            if follow_placements is None:
                raise AssertionError('follow_placements should not be None at this point')
            for mesh_idx in range(mesh.ndim):
                follow_placements[mesh_idx] = merge_placement(follow_placements[mesh_idx], arg_placements[mesh_idx])
    if follow_placements is None:
        raise AssertionError('follow placements should not be None!')
    return follow_placements

def date_converter(date_col, col: Hashable, dayfirst: bool=False, cache_dates: bool=True, date_format: dict[Hashable, str] | str | None=None):
    if date_col.dtype.kind in 'Mm':
        return date_col
    date_fmt = date_format.get(col) if isinstance(date_format, dict) else date_format
    str_objs = lib.ensure_string_array(np.asarray(date_col))
    try:
        result = tools.to_datetime(str_objs, format=date_fmt, utc=False, dayfirst=dayfirst, cache=cache_dates)
    except (ValueError, TypeError):
        return str_objs
    if <MASK>:
        arr = result.to_numpy()
        arr.flags.writeable = True
        return arr
    return result._values

def fuzz_inputs_specs(self, output_spec: Spec) -> list[Spec]:
    """Generate input spec for flatten operation."""
    if not isinstance(output_spec, TensorSpec):
        raise ValueError('FlattenOperator can only produce TensorSpec outputs')
    output_numel = 1
    for dim in output_spec.size:
        output_numel *= dim
    if <MASK>:
        input_size = fuzz_tensor_size()
        if len(input_size) < 2:
            input_size = (2, 2)
    else:
        input_size = fuzz_tensor_size()
        if len(input_size) < 3:
            input_size = (2, 2, 2)
    input_numel = 1
    for dim in input_size:
        input_numel *= dim
    if input_numel != output_numel:
        if output_numel == 0:
            input_size = tuple(list(input_size)[:-1] + [0])
        elif len(input_size) > 0 and output_numel > 0:
            prefix_numel = 1
            for dim in input_size[:-1]:
                prefix_numel *= dim
            if prefix_numel > 0:
                last_dim = output_numel // prefix_numel
                if last_dim * prefix_numel == output_numel:
                    input_size = tuple(list(input_size)[:-1] + [last_dim])
                else:
                    input_size = (output_numel,)
            else:
                input_size = (output_numel,)
    from torchfuzz.tensor_fuzzer import fuzz_valid_stride
    input_stride = fuzz_valid_stride(tuple(input_size))
    return [TensorSpec(size=tuple(input_size), stride=input_stride, dtype=output_spec.dtype)]

def rename_symbols(node, name_map):
    """Renames symbols in an AST. Requires qual_names annotations."""
    renamer = SymbolRenamer(name_map)
    if isinstance(node, list):
        return [renamer.visit(n) for n in node]
    elif <MASK>:
        return tuple((renamer.visit(n) for n in node))
    return renamer.visit(node)

