def _check_valid_to_preserve(op_overload: 'OperatorBase'):
    from torch._decomp import _should_decompose_because_unsafe_op
    if <MASK>:
        return False
    if op_overload in FunctionalTensor.metadata_fns:
        return False
    if not hasattr(op_overload, '_schema'):
        return False
    alias_info = len([i for i in op_overload._schema.arguments if i.alias_info is not None])
    is_mutating_or_aliasing = alias_info != 0 or op_overload._schema.is_mutable
    if is_mutating_or_aliasing:
        return False
    if not torch._C._dispatch_has_kernel(op_overload.name()):
        return False
    return True

@staticmethod
def check_trace_mode(device_type, trace_mode):
    """Checks if the given trace mode work on the given device type.

    Args:
      device_type: Device type, TPU, GPU, CPU.
      trace_mode: Tensor tracer trace mode.
    Raises:
      ValueError: If the given trace mode is not supported for the device.
    """
    if <MASK>:
        if device_type != _DEVICE_TYPE_TPU:
            raise ValueError('Device_type "%s" is not yet supported for trace mode "%s"' % (device_type, trace_mode))

def _calculate_potential_peak_memory(candidate, group_ns, group_n_to_bufs_after_swap_dealloc_instead_of_candidate):
    pre_group_mem = _curr_memory[group_head][0] - snodes_allocfree[group_head].size_alloc
    _post_alloc_update: dict[BaseSchedulerNode, int] = {}
    _size_free_delta_update: dict[BaseSchedulerNode, int] = {}
    potential_peak = 0
    if <MASK>:
        potential_peak = max(group_peak_memory + candidate_delta_mem, pre_group_mem + candidate_allocfree.size_alloc)
        return (potential_peak, _post_alloc_update, _size_free_delta_update)
    candidate_post_alloc = pre_group_mem + candidate_allocfree.size_alloc
    _post_alloc_update[candidate] = candidate_post_alloc
    potential_peak = candidate_post_alloc
    candidate_size_free_to_move = sum((buf.mpi_buffer.size_free for buf in itertools.chain.from_iterable(group_n_to_bufs_after_swap_dealloc_instead_of_candidate.values())))
    _size_free_delta_update[candidate] = -candidate_size_free_to_move
    delta_mem = candidate_delta_mem + candidate_size_free_to_move
    for gn in gns:
        gn_post_alloc = _curr_memory[gn][0] + delta_mem
        _post_alloc_update[gn] = gn_post_alloc
        potential_peak = max(potential_peak, gn_post_alloc)
        gn_size_free_to_add = 0
        if gn in group_n_to_bufs_after_swap_dealloc_instead_of_candidate:
            bufs = group_n_to_bufs_after_swap_dealloc_instead_of_candidate[gn]
            for buf in bufs:
                gn_size_free_to_add += buf.mpi_buffer.size_free
            _size_free_delta_update[gn] = gn_size_free_to_add
        delta_mem -= gn_size_free_to_add
    return (potential_peak, _post_alloc_update, _size_free_delta_update)

def __init__(self, connector, num_children, negated):
    self.connector = connector
    self.negated = negated
    if <MASK>:
        if connector == AND:
            self.effective_connector = OR
        else:
            self.effective_connector = AND
    else:
        self.effective_connector = self.connector
    self.num_children = num_children
    self.votes = Counter()

def _quantize_weight(weight: torch.Tensor, weight_qscheme: torch.qscheme, weight_dtype: torch.dtype, weight_scale: torch.Tensor, weight_zero_point: torch.Tensor, weight_axis_int: int) -> torch.Tensor:
    if weight_dtype == torch.float16:
        weight = weight.to(weight_dtype)
        return weight
    if weight_qscheme == torch.per_tensor_affine:
        if <MASK>:
            weight = torch.quantize_per_tensor(weight, weight_scale, weight_zero_point, weight_dtype)
            return weight
    elif weight_qscheme in [torch.per_channel_affine, torch.per_channel_affine_float_qparams]:
        if weight_dtype in [torch.quint8, torch.qint8, torch.quint4x2, torch.qint32]:
            weight = torch.quantize_per_channel(weight, weight_scale, weight_zero_point, weight_axis_int, weight_dtype)
            return weight
    raise ValueError(f'Unsupported dtype and qscheme: {weight_dtype}, {weight_qscheme}')

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    """
        Build a forest of trees from the training set (X, y).

        Parameters
        ----------
        X : {array-like, sparse matrix} of shape (n_samples, n_features)
            The training input samples. Internally, its dtype will be converted
            to ``dtype=np.float32``. If a sparse matrix is provided, it will be
            converted into a sparse ``csc_matrix``.

        y : array-like of shape (n_samples,) or (n_samples, n_outputs)
            The target values (class labels in classification, real numbers in
            regression).

        sample_weight : array-like of shape (n_samples,), default=None
            Sample weights. If None, then samples are equally weighted. Splits
            that would create child nodes with net zero or negative weight are
            ignored while searching for a split in each node. In the case of
            classification, splits are also ignored if they would result in any
            single class carrying a negative weight in either child node.

        Returns
        -------
        self : object
            Fitted estimator.
        """
    if issparse(y):
        raise ValueError('sparse multilabel-indicator for y is not supported.')
    (X, y) = validate_data(self, X, y, multi_output=True, accept_sparse='csc', dtype=DTYPE, ensure_all_finite=False)
    estimator = type(self.estimator)(criterion=self.criterion)
    missing_values_in_feature_mask = estimator._compute_missing_values_in_feature_mask(X, estimator_name=self.__class__.__name__)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if issparse(X):
        X.sort_indices()
    y = np.atleast_1d(y)
    if y.ndim == 2 and y.shape[1] == 1:
        warn('A column-vector y was passed when a 1d array was expected. Please change the shape of y to (n_samples,), for example using ravel().', DataConversionWarning, stacklevel=2)
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    if self.criterion == 'poisson':
        if np.any(y < 0):
            raise ValueError('Some value(s) of y are negative which is not allowed for Poisson regression.')
        if np.sum(y) <= 0:
            raise ValueError('Sum of y is not strictly positive which is necessary for Poisson regression.')
    (self._n_samples, self.n_outputs_) = y.shape
    (y, expanded_class_weight) = self._validate_y_class_weight(y)
    if getattr(y, 'dtype', None) != DOUBLE or not y.flags.contiguous:
        y = np.ascontiguousarray(y, dtype=DOUBLE)
    if expanded_class_weight is not None:
        if sample_weight is not None:
            sample_weight = sample_weight * expanded_class_weight
        else:
            sample_weight = expanded_class_weight
    if <MASK>:
        raise ValueError('`max_sample` cannot be set if `bootstrap=False`. Either switch to `bootstrap=True` or set `max_sample=None`.')
    elif self.bootstrap:
        n_samples_bootstrap = _get_n_samples_bootstrap(n_samples=X.shape[0], max_samples=self.max_samples)
    else:
        n_samples_bootstrap = None
    self._n_samples_bootstrap = n_samples_bootstrap
    self._validate_estimator()
    if not self.bootstrap and self.oob_score:
        raise ValueError('Out of bag estimation only available if bootstrap=True')
    random_state = check_random_state(self.random_state)
    if not self.warm_start or not hasattr(self, 'estimators_'):
        self.estimators_ = []
    n_more_estimators = self.n_estimators - len(self.estimators_)
    if n_more_estimators < 0:
        raise ValueError('n_estimators=%d must be larger or equal to len(estimators_)=%d when warm_start==True' % (self.n_estimators, len(self.estimators_)))
    elif n_more_estimators == 0:
        warn('Warm-start fitting without increasing n_estimators does not fit new trees.')
    else:
        if self.warm_start and len(self.estimators_) > 0:
            random_state.randint(MAX_INT, size=len(self.estimators_))
        trees = [self._make_estimator(append=False, random_state=random_state) for i in range(n_more_estimators)]
        trees = Parallel(n_jobs=self.n_jobs, verbose=self.verbose, prefer='threads')((delayed(_parallel_build_trees)(t, self.bootstrap, X, y, sample_weight, i, len(trees), verbose=self.verbose, class_weight=self.class_weight, n_samples_bootstrap=n_samples_bootstrap, missing_values_in_feature_mask=missing_values_in_feature_mask) for (i, t) in enumerate(trees)))
        self.estimators_.extend(trees)
    if self.oob_score and (n_more_estimators > 0 or not hasattr(self, 'oob_score_')):
        y_type = type_of_target(y)
        if y_type == 'unknown' or (is_classifier(self) and y_type == 'multiclass-multioutput'):
            raise ValueError(f'The type of target cannot be used to compute OOB estimates. Got {y_type} while only the following are supported: continuous, continuous-multioutput, binary, multiclass, multilabel-indicator.')
        if callable(self.oob_score):
            self._set_oob_score_and_attributes(X, y, scoring_function=self.oob_score)
        else:
            self._set_oob_score_and_attributes(X, y)
    if hasattr(self, 'classes_') and self.n_outputs_ == 1:
        self.n_classes_ = self.n_classes_[0]
        self.classes_ = self.classes_[0]
    return self

def create_proxy(self, kind: str, target: Any, args: Any, kwargs: Any, name: Optional[str]=None, type_expr: Optional[Any]=None, proxy_factory_fn: Optional[Callable[[fx.Node], fx.Proxy]]=None) -> fx.Proxy:
    if self.parent is not None:
        (flat_args, tree_spec) = pytree.tree_flatten((args, kwargs))
        new_flat_args = []
        for arg in flat_args:
            maybe_new_arg = self.maybe_lift_tracked_freevar_to_input(arg)
            new_flat_args.append(maybe_new_arg)
        (args, kwargs) = pytree.tree_unflatten(new_flat_args, tree_spec)
    rv = super().create_proxy(kind, target, args, kwargs, name, type_expr, proxy_factory_fn)
    tx = self.output_graph.current_tx
    if sys.version_info >= (3, 11) and kind in ('call_function', 'call_method', 'call_module'):
        cur_inst = tx.current_instruction
        if cur_inst is not self.prev_inst and cur_inst.positions is not None and (cur_inst.positions.lineno is not None):
            tx_code = tx.f_code
            header = tx.get_line_of_code_header(lineno=cur_inst.positions.lineno)

            def get_trace_call_log_str() -> str:
                line = get_instruction_source_311(tx_code, cur_inst).rstrip()
                return f'TRACE FX call {rv.node.name} from {header}\n{line}'
            trace_call_log.debug('%s', LazyString(get_trace_call_log_str))
            self.prev_inst = cur_inst
    is_retracing = False
    if tx.f_code is not self._cur_code:
        orig_graphmodule_maybe = code_context.get_context(tx.f_code).get('orig_graphmodule', lambda : None)()
        if isinstance(orig_graphmodule_maybe, torch.fx.GraphModule):
            is_retracing = True
            self._orig_gm_meta = [nd.meta for nd in orig_graphmodule_maybe.graph.nodes]
            self._orig_gm_lineno_map = orig_graphmodule_maybe._lineno_map
            self._orig_gm_firstlineno = orig_graphmodule_maybe.forward.__code__.co_firstlineno
        else:
            self._orig_gm_meta = None
            self._orig_gm_lineno_map = None
            self._orig_gm_firstlineno = None
    nn_module_stack = tx.nn_module_stack
    if <MASK>:
        rv.node.meta['nn_module_stack'] = nn_module_stack.copy()
    if kind in {'call_function', 'call_method'}:
        stack = (rv.node.name, target)
        if nn_module_stack:
            current_nn_module = list(rv.node.meta['nn_module_stack'].values())[-1][1]
            if current_nn_module.__module__.startswith(('torch.nn.modules', 'torch.ao.')) and (not current_nn_module.__module__.startswith('torch.nn.modules.container')):
                stack = (rv.node.name, current_nn_module)
        rv.node.meta['source_fn_stack'] = self.source_fn_stack + [stack]
    elif kind == 'call_module':
        if self.parent is not None:
            unimplemented_v2(gb_type='Invoking an nn.Module inside a higher order operator', context=f'Higher order op name: {self.source_target}', explanation='This is not supported.', hints=[])
        rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, next((ty for (k, (_, ty)) in rv.node.meta['nn_module_stack'].items() if k.split('@')[0] == target)))]
    self._maybe_preserve_original_meta(tx, rv.node)
    if not is_retracing:
        if 'nn_module_stack' not in rv.node.meta:
            nn_module_stack = tx.nn_module_stack
            if nn_module_stack:
                rv.node.meta['nn_module_stack'] = nn_module_stack.copy()
        if 'source_fn_stack' not in rv.node.meta:
            if kind in {'call_function', 'call_method'}:
                rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, target)]
            elif kind == 'call_module':
                if self.parent is not None:
                    unimplemented_v2(gb_type='Invoking an nn.Module inside a HigherOrderOperator', context='', explanation='This is not supported.', hints=[])
                rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, rv.node.meta['nn_module_stack'][target][1])]
    if 'stack_trace' not in rv.node.meta:
        frame_summaries: list[traceback.FrameSummary] = []
        while tx:
            if not tx.is_co_filename_from_nn_modules():
                frame_summaries.append(tx.frame_summary())
            tx = getattr(tx, 'parent', None)
        filtered_frame_summaries = [frame for frame in frame_summaries if frame.filename not in uninteresting_files()]
        filtered_frame_summaries.reverse()
        msgs = traceback.StackSummary.from_list(filtered_frame_summaries).format()
        rv.node.stack_trace = ''.join(msgs)
    if torch._dynamo.config.use_graph_deduplication or torch._dynamo.config.track_nodes_for_deduplication:
        self.output_graph.region_tracker.track_node(self.output_graph.current_tx, rv.node)
    return rv

@register_decomposition(aten.huber_loss)
@out_wrapper()
@elementwise_type_promotion_wrapper(type_promoting_args=('input', 'target'), type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
def huber_loss(input: TensorLikeType, target: TensorLikeType, reduction: Union[str, int]='mean', delta: float=1.0) -> TensorLikeType:
    """
    Reference implementation of torch.nn.functional.huber_loss
    """
    if <MASK>:
        reduction = _reduction_int_to_str(reduction)
    _check_reduction_value(reduction)
    torch._check(delta > 0, lambda : 'huber_loss does not support non-positive values for delta.')
    z = (input - target).abs()
    loss = torch.where(z < delta, 0.5 * z * z, delta * (z - 0.5 * delta))
    return _apply_loss_reduction(loss, reduction)

