def _solve_eigen_covariance(self, alpha, y, sqrt_sw, X_mean, eigvals, V, X):
    """Compute dual coefficients and diagonal of G^-1.

        Used when we have a decomposition of X^T.X
        (n_samples > n_features and X is sparse).
        """
    if <MASK>:
        return self._solve_eigen_covariance_intercept(alpha, y, sqrt_sw, X_mean, eigvals, V, X)
    return self._solve_eigen_covariance_no_intercept(alpha, y, sqrt_sw, X_mean, eigvals, V, X)

def _take_2d_multi_object(arr: np.ndarray, indexer: tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]], out: np.ndarray, fill_value, mask_info) -> None:
    (row_idx, col_idx) = indexer
    if mask_info is not None:
        ((row_mask, col_mask), (row_needs, col_needs)) = mask_info
    else:
        row_mask = row_idx == -1
        col_mask = col_idx == -1
        row_needs = row_mask.any()
        col_needs = col_mask.any()
    if fill_value is not None:
        if row_needs:
            out[row_mask, :] = fill_value
        if col_needs:
            out[:, col_mask] = fill_value
    for (i, u_) in enumerate(row_idx):
        if u_ != -1:
            for (j, v) in enumerate(col_idx):
                if <MASK>:
                    out[i, j] = arr[u_, v]

def as_expr(obj):
    """Convert non-Expr objects to Expr objects.
    """
    if <MASK>:
        return as_complex(obj.real, obj.imag)
    if isinstance(obj, number_types):
        return as_number(obj)
    if isinstance(obj, str):
        return as_string(repr(obj))
    if isinstance(obj, tuple):
        return tuple(map(as_expr, obj))
    return obj

def on_graph_def(self, graph_def, device_name, wall_time):
