def var_getattr(self, tx: 'InstructionTranslator', name: str) -> 'VariableTracker':
    if name == 'get' and type(self.value).get in (collections.abc.Mapping.get, dict.get):
        return variables.UserMethodVariable(polyfills.mapping_get, self)
    elif <MASK>:
        self.generic_dict_vt = variables.LazyVariableTracker.create(self.value.__dict__, AttrSource(self.source, '__dict__'))
        return self.generic_dict_vt
    elif (out := self.generic_dict_vt.maybe_getitem_const(variables.ConstantVariable(name))):
        return out
    else:
        return super().var_getattr(tx, name)

def _get_cross_device_ops(self, value):
    if isinstance(value, values.DistributedValues):
        num_devices = len(value._values)
    else:
        num_devices = 1
    if <MASK>:
        return self._cross_device_ops
    else:
