def _tpu_function_creator(self, fn, options):
    if context.executing_eagerly() and fn in self._tpu_function_cache:
        return self._tpu_function_cache[fn]
    strategy = self._container_strategy()

    def tpu_function(args, kwargs):
        """TF Function used to replicate the user computation."""
        logging.vlog(1, '`TPUStrategy.run` is called with [args: %s] [kwargs: %s]', args, kwargs)
        if kwargs is None:
            kwargs = {}
        result = [[]]

        def replicated_fn(replica_id, replica_args, replica_kwargs):
            """Wraps user function to provide replica ID and `Tensor` inputs."""
            with _TPUReplicaContext(strategy, replica_id_in_sync_group=replica_id):
                result[0] = fn(*replica_args, **replica_kwargs)
            return result[0]
        replicate_inputs = []
        for i in range(strategy.num_replicas_in_sync):
            replicate_inputs.append([constant_op.constant(i, dtype=dtypes.int32), distribute_utils.select_replica(i, args), distribute_utils.select_replica(i, kwargs)])
        if options.experimental_enable_dynamic_batch_size and replicate_inputs:
            maximum_shapes = []
            flattened_list = nest.flatten(replicate_inputs[0])
            for input_tensor in flattened_list:
                if tensor_util.is_tf_type(input_tensor):
                    rank = input_tensor.shape.rank
                else:
                    rank = np.ndim(input_tensor)
                if <MASK>:
                    raise ValueError('input tensor {} to TPUStrategy.run() has unknown rank, which is not allowed'.format(input_tensor))
                maximum_shape = tensor_shape.TensorShape([None] * rank)
                maximum_shapes.append(maximum_shape)
            maximum_shapes = nest.pack_sequence_as(replicate_inputs[0], maximum_shapes)
        else:
            maximum_shapes = None
        if options.experimental_bucketizing_dynamic_shape:
            padding_spec = tpu.PaddingSpec.POWER_OF_TWO
        else:
            padding_spec = None
        with strategy.scope():
            xla_options = options.experimental_xla_options or tpu.XLAOptions(use_spmd_for_xla_partitioning=self._use_spmd_for_xla_partitioning)
            replicate_outputs = tpu.replicate(replicated_fn, replicate_inputs, device_assignment=self._device_assignment, maximum_shapes=maximum_shapes, padding_spec=padding_spec, xla_options=xla_options)
        filter_ops = lambda x: [o for o in x if not isinstance(o, ops.Operation)]
        if isinstance(result[0], list):
            result[0] = filter_ops(result[0])
        if result[0] is None or isinstance(result[0], ops.Operation):
            replicate_outputs = [None] * len(replicate_outputs)
        else:
            replicate_outputs = [nest.pack_sequence_as(result[0], filter_ops(nest.flatten(output))) for output in replicate_outputs]
        return distribute_utils.regroup(replicate_outputs)
    if context.executing_eagerly():
        tpu_function = def_function.function(tpu_function)
        self._tpu_function_cache[fn] = tpu_function
    return tpu_function

def _get_activation_fn(activation: str) -> Callable[[Tensor], Tensor]:
    if <MASK>:
        return F.relu
    elif activation == 'gelu':
        return F.gelu
    raise RuntimeError(f'activation should be relu/gelu, not {activation}')

def test_frequent_retracing_warning_on_reinstantiation(self):
    if <MASK>:
        self.skipTest('self.assertLogs() call is not available in Python 2.')
    with self.assertLogs(level='WARN') as logs:
        for i in range(5):

            @polymorphic_function.function
            def f(x):
                return x
            f(i)
            if i < 4:
                self.assertEmpty(logs.output)
    self.assertLen(logs.output, 1)
    self.assertIn('Tracing is expensive', logs.output[0])

def __torch_dispatch__(self, func, types, args=(), kwargs=None):
    if kwargs is None:
        kwargs = {}
    is_factory = bool(FACTORY_FUNCTION_REGEX.match(func._schema.name))
    argument_handler = ArgumentHandler()
    argument_handler.parse_inputs(func._schema, args, kwargs, is_factory=is_factory)
    outputs = func(*args, **kwargs)
    argument_handler.parse_outputs(func._schema, outputs, is_factory=is_factory)
    errors = self.event_handler._handle_kernel_launch(torch.cuda.current_stream().cuda_stream, argument_handler.dataptrs_read - argument_handler.dataptrs_written, argument_handler.dataptrs_written, argument_handler.outputs, func._schema, argument_handler.tensor_aliases)
    if <MASK>:
        for error in errors:
            print(error, file=sys.stderr)
        raise CUDASanitizerErrors(errors)
    return outputs

def describe(obj: Any, denylist: Collection[Any], leaves_only: bool=False) -> str:
    """Returns a custom human-readable summary of obj.

    Args:
      obj: the value to describe.
      denylist: same as denylist in get_ignore_reason.
      leaves_only: boolean flag used when calling describe recursively. Useful
        for summarizing collections.
    """
    if get_ignore_reason(obj, denylist):
        return '{}{}'.format(get_ignore_reason(obj, denylist), type(obj))
    if <MASK>:
        return 'frame: {}'.format(tf_inspect.getframeinfo(obj))
    elif tf_inspect.ismodule(obj):
        return 'module: {}'.format(obj.__name__)
    elif leaves_only:
        return '{}, {}'.format(type(obj), id(obj))
    elif isinstance(obj, list):
        return 'list({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
    elif isinstance(obj, tuple):
        return 'tuple({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
    elif isinstance(obj, dict):
        return 'dict({}): {} keys'.format(id(obj), len(obj.keys()))
    elif tf_inspect.isfunction(obj):
        return 'function({}) {}; globals ID: {}'.format(id(obj), obj.__name__, id(obj.__globals__))
    else:
        return '{}, {}'.format(type(obj), id(obj))

def _to_proto(self):
    pb = dataset_options_pb2.Options()
    if self.deterministic is not None:
        pb.deterministic = self.deterministic
    pb.autotune_options.CopyFrom(self.autotune._to_proto())
    pb.distribute_options.CopyFrom(self.experimental_distribute._to_proto())
    if self.experimental_external_state_policy is not None:
        pb.external_state_policy = ExternalStatePolicy._to_proto(self.experimental_external_state_policy)
    pb.optimization_options.CopyFrom(self.experimental_optimization._to_proto())
    if self.experimental_slack is not None:
        pb.slack = self.experimental_slack
    if self.experimental_symbolic_checkpoint is not None:
        pb.symbolic_checkpoint = self.experimental_symbolic_checkpoint
    if self.experimental_warm_start is not None:
        pb.warm_start = self.experimental_warm_start
    if <MASK>:
        pb.dataset_name = self.dataset_name
    if self.framework_type:
        for framework_type in self.framework_type:
            pb.framework_type.append(framework_type)
    pb.service_options.CopyFrom(self.experimental_service._to_proto())
    pb.threading_options.CopyFrom(self.threading._to_proto())
    return pb

def get_symbolic_inputs(self, return_single_as_list=False):
    """Returns inputs to be set as self.inputs for a model."""
    for (i, (k, v)) in enumerate(zip(self._input_names, self._flattened_inputs)):
        if isinstance(v, (list, float, int)):
            v = numpy_compat.np_asarray(v)
            if v.ndim == 1:
                v = np.expand_dims(v, 1)
        if isinstance(v, np.ndarray):
            shape = (None,) + tuple(v.shape[1:])
            if <MASK>:
                shape = (None, 1)
            dtype = dtypes.as_dtype(v.dtype)
            if dtype.is_floating:
                dtype = backend.floatx()
            v = backend.placeholder(shape=shape, name=k, dtype=dtype)
        elif isinstance(v, tensor_spec.TensorSpec):
            shape = (None,) + tuple(v.shape.as_list()[1:])
            if shape == (None,):
                shape = (None, 1)
            v = backend.placeholder(shape=shape, name=k, dtype=v.dtype)
        self._flattened_inputs[i] = v
    if self._is_dict:
        return dict(zip(self._input_names, self._flattened_inputs))
    if self._is_single_input and (not return_single_as_list):
        return self._flattened_inputs[0]
    return self._flattened_inputs

@final
def _adorn_subplots(self, fig: Figure) -> None:
    """Common post process unrelated to data"""
    if len(self.axes) > 0:
        all_axes = self._get_subplots(fig)
        (nrows, ncols) = self._get_axes_layout(fig)
        handle_shared_axes(axarr=all_axes, nplots=len(all_axes), naxes=nrows * ncols, nrows=nrows, ncols=ncols, sharex=self.sharex, sharey=self.sharey)
    for ax in self.axes:
        ax = getattr(ax, 'right_ax', ax)
        if self.yticks is not None:
            ax.set_yticks(self.yticks)
        if self.xticks is not None:
            ax.set_xticks(self.xticks)
        if self.ylim is not None:
            ax.set_ylim(self.ylim)
        if self.xlim is not None:
            ax.set_xlim(self.xlim)
        if <MASK>:
            ax.set_ylabel(pprint_thing(self.ylabel))
        ax.grid(self.grid)
    if self.title:
        if self.subplots:
            if is_list_like(self.title):
                if not isinstance(self.subplots, bool):
                    if len(self.subplots) != len(self.title):
                        raise ValueError(f'The number of titles ({len(self.title)}) must equal the number of subplots ({len(self.subplots)}).')
                elif len(self.title) != self.nseries:
                    raise ValueError(f'The length of `title` must equal the number of columns if using `title` of type `list` and `subplots=True`.\nlength of title = {len(self.title)}\nnumber of columns = {self.nseries}')
                for (ax, title) in zip(self.axes, self.title, strict=False):
                    ax.set_title(title)
            else:
                fig.suptitle(self.title)
        else:
            if is_list_like(self.title):
                msg = 'Using `title` of type `list` is not supported unless `subplots=True` is passed'
                raise ValueError(msg)
            self.axes[0].set_title(self.title)

def _maybe_insert_input_observer_for_arg_or_kwarg(node: Union[Node, Any], arg: Argument, qconfig: QConfigAny, model: torch.nn.Module, named_modules: dict[str, torch.nn.Module], obs_or_fq_map: dict[EdgeOrNode, ObserverOrFakeQuantize], is_qat: bool, model_device: Optional[torch.device]=None) -> Argument:
    """
    Given a `node` and an `arg`, inserts an input observer between
    `node` and `arg` if necessary.
    """
    if isinstance(arg, (list, tuple)):
        new_arg_to_return = []
        for inner_arg in arg:
            new_inner_arg = _maybe_insert_input_observer_for_arg_or_kwarg(node, inner_arg, qconfig, model, named_modules, obs_or_fq_map, is_qat, model_device)
            new_arg_to_return.append(new_inner_arg)
        return type(arg)(new_arg_to_return)
    if not isinstance(arg, Node):
        return arg
    if not isinstance(arg, Node):
        raise AssertionError(f'expect original argument to be a Node, but got: {type(arg)}')
    new_arg = arg
    original_arg = arg
    while _is_activation_post_process_node(original_arg, named_modules):
        original_arg = original_arg.args[0]
    if <MASK>:
        raise AssertionError(f'expect original argument to be a Node, but got: {type(original_arg)}')
    input_edge = (original_arg, node)
    if input_edge not in obs_or_fq_map:
        return new_arg
    input_edge_obs_or_fq = obs_or_fq_map[input_edge]
    if input_edge_obs_or_fq is None:
        return new_arg
    arg_as_output_obs_or_fq = obs_or_fq_map.get(original_arg)
    if arg_as_output_obs_or_fq is not None and id(arg_as_output_obs_or_fq) == id(input_edge_obs_or_fq):
        return new_arg
    for maybe_obs_node in arg.users.keys():
        if not _is_activation_post_process_node(maybe_obs_node, named_modules):
            continue
        maybe_obs_mod = named_modules[maybe_obs_node.target]
        if id(maybe_obs_mod) == id(input_edge_obs_or_fq):
            return maybe_obs_node
    if not isinstance(model.graph, Graph):
        raise AssertionError(f'Expected model.graph to be a torch.fx.Graph, got {type(model.graph)}')
    new_arg = _insert_obs_or_fq(arg, input_edge_obs_or_fq, model, named_modules, model.graph, model_device)
    return new_arg

def _plot_curve(self, x_data, *, ax=None, negate_score=False, score_name=None, score_type='test', std_display_style='fill_between', line_kw=None, fill_between_kw=None, errorbar_kw=None):
    check_matplotlib_support(f'{self.__class__.__name__}.plot')
    import matplotlib.pyplot as plt
    if ax is None:
        (_, ax) = plt.subplots()
    if negate_score:
        (train_scores, test_scores) = (-self.train_scores, -self.test_scores)
    else:
        (train_scores, test_scores) = (self.train_scores, self.test_scores)
    if std_display_style not in ('errorbar', 'fill_between', None):
        raise ValueError(f"Unknown std_display_style: {std_display_style}. Should be one of 'errorbar', 'fill_between', or None.")
    if score_type not in ('test', 'train', 'both'):
        raise ValueError(f"Unknown score_type: {score_type}. Should be one of 'test', 'train', or 'both'.")
    if score_type == 'train':
        scores = {'Train': train_scores}
    elif score_type == 'test':
        scores = {'Test': test_scores}
    else:
        scores = {'Train': train_scores, 'Test': test_scores}
    if std_display_style in ('fill_between', None):
        if line_kw is None:
            line_kw = {}
        self.lines_ = []
        for (line_label, score) in scores.items():
            self.lines_.append(*ax.plot(x_data, score.mean(axis=1), label=line_label, **line_kw))
        self.errorbar_ = None
        self.fill_between_ = None
    if std_display_style == 'errorbar':
        if errorbar_kw is None:
            errorbar_kw = {}
        self.errorbar_ = []
        for (line_label, score) in scores.items():
            self.errorbar_.append(ax.errorbar(x_data, score.mean(axis=1), score.std(axis=1), label=line_label, **errorbar_kw))
        (self.lines_, self.fill_between_) = (None, None)
    elif <MASK>:
        if fill_between_kw is None:
            fill_between_kw = {}
        default_fill_between_kw = {'alpha': 0.5}
        fill_between_kw = {**default_fill_between_kw, **fill_between_kw}
        self.fill_between_ = []
        for (line_label, score) in scores.items():
            self.fill_between_.append(ax.fill_between(x_data, score.mean(axis=1) - score.std(axis=1), score.mean(axis=1) + score.std(axis=1), **fill_between_kw))
    score_name = self.score_name if score_name is None else score_name
    ax.legend()
    if _interval_max_min_ratio(x_data) > 5:
        xscale = 'symlog' if x_data.min() <= 0 else 'log'
    else:
        xscale = 'linear'
    ax.set_xscale(xscale)
    ax.set_ylabel(f'{score_name}')
    self.ax_ = ax
    self.figure_ = ax.figure

def __init__(self, wrapped, preprocessor, postprocessor) -> None:
    self._wrapped = wrapped
    if preprocessor is not None:
        self._preprocessor = preprocessor
    else:
        self._preprocessor = lambda x, y: (x, y)
    if <MASK>:
        self._postprocessor = postprocessor
    else:
        self._postprocessor = lambda x: x

def _build_graph(self):
    """Matrix representing a fully connected graph between each sample."""
    if <MASK>:
        self.nn_fit = None
    affinity_matrix = self._get_kernel(self.X_)
    normalizer = affinity_matrix.sum(axis=1)
    if sparse.isspmatrix(affinity_matrix):
        normalizer = np.ravel(normalizer)
    if sparse.issparse(affinity_matrix):
        inv_normalizer = sparse.diags(1.0 / normalizer)
        affinity_matrix = inv_normalizer @ affinity_matrix
    else:
        affinity_matrix /= normalizer[:, np.newaxis]
    return affinity_matrix

def reduction_combine_vec(self, reduction_type, var, next_value, helper_val=None, index: Optional[sympy.Symbol]=None, horizontal_reduction: Optional[bool]=None, src_dtype: Optional[torch.dtype]=torch.float32):
    is_bool = src_dtype == torch.bool
    if reduction_type == 'max':
        if <MASK>:
            return f'max_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} | {next_value}' if is_bool else f'at::vec::maximum({var}, {next_value})'
    elif reduction_type == 'min':
        if self.tail_size:
            return f'min_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} & {next_value}' if is_bool else f'at::vec::minimum({var}, {next_value})'
    elif reduction_type == 'sum':
        if helper_val:
            if self.tail_size:
                return f'cascade_sum_combine({next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'cascade_sum_combine({next_value}, &{helper_val})'
        elif self.tail_size:
            return f'sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            conjunction = '|' if is_bool else '+'
            return f'{var} {conjunction} {next_value}'
    elif reduction_type == 'prod':
        if self.tail_size:
            return f'prod_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} * {next_value}'
    elif reduction_type == 'xor_sum':
        if self.tail_size:
            return f'xor_sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} ^ {next_value}'
    elif reduction_type == 'welford_reduce':
        if helper_val:
            if self.tail_size:
                return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'welford_combine({var}, {next_value}, &{helper_val})'
        elif self.tail_size:
            return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {next_value})'
    elif reduction_type == 'welford_combine':
        if isinstance(next_value, tuple):
            (mean, m2, weight) = next_value
        else:
            (mean, m2, weight) = reduction_project(reduction_type, next_value)
        if self.tail_size:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}})'
    elif reduction_type in ('argmin', 'argmax'):
        assert src_dtype is not None
        cdtype = DTYPE_TO_CPP[src_dtype]
        if src_dtype == torch.bool:
            cdtype = DTYPE_TO_CPP[torch.float]
        n_src = self._get_num_vectors(src_dtype)
        n_idx = self._get_num_vectors(torch.int64)
        t_extra = ''
        arg_extra = ''
        if index is not None:
            assert horizontal_reduction is not None
            t_extra = f', {str(horizontal_reduction).lower()}'
            arg_extra = f', {index}'
        if self.tail_size:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra}, {cexpr_index(self.tail_size)})'
        else:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra})'
    elif reduction_type == 'any':
        if isinstance(next_value, CppCSEVariable):
            assert next_value.dtype == torch.bool
            (next_value,) = unify_mask_base_type(V.kernel.compute, (next_value,))
        return f'{var} | {next_value}'
    else:
        raise NotImplementedError

@classmethod
def increment_step(cls, requester: str) -> int:
    """Increments the step count for the requester.

        Additionally if the max over all step counts has incremented then
        trigger the _kineto_step() returns global step count
        """
    if requester not in cls._step_dict:
        cls.init_step_count(requester)
    cls._step_dict[requester] += 1
    new_step = max(cls._step_dict.values())
    if new_step > cls._current_step:
        delta = new_step - cls._current_step
        if <MASK>:
            warn(f'Profiler step count has increased more than 1 - current_step = {cls._current_step} step dict =  {cls._step_dict}')
        for _ in range(delta):
            _kineto_step()
        cls._current_step = new_step
    return cls._current_step

def _modify_model_input_type_per_subgraph(model, subgraph_index, signature_index, inference_input_type):
    """Modify model input type per subgraph."""
    subgraph = model.subgraphs[subgraph_index]
    tensors = subgraph.tensors
    operators = subgraph.operators
    quant_opcode_idxs = get_quantize_opcode_idx(model)
    if operators and (not quant_opcode_idxs):
        for input_idx in subgraph.inputs:
            input_type = _convert_tflite_enum_type_to_tf_type(tensors[input_idx].type)
            if <MASK>:
                raise ValueError('Model input is not dequantized.')
        return
    input_quant_ops = []
    for op in operators:
        if op.opcodeIndex in quant_opcode_idxs and op.inputs[0] in subgraph.inputs:
            (float_tensor, quant_tensor) = (tensors[op.inputs[0]], tensors[op.outputs[0]])
            float_type = _convert_tflite_enum_type_to_tf_type(float_tensor.type)
            if float_type != dtypes.float32:
                if float_type == inference_input_type:
                    continue
                else:
                    raise ValueError("Initial model input type must be tf.float32. Expected type for tensor with name '{}' is tf.float32, instead type is {}".format(float_tensor.name, get_tf_type_name(float_type)))
            quant_type = _convert_tflite_enum_type_to_tf_type(quant_tensor.type)
            if quant_type not in _MAP_QUANT_TO_IO_TYPES:
                raise ValueError("Initial model input is not quantized. Expected type for tensor with name '{}' should be in {}, instead type is {}".format(quant_tensor.name, tuple((get_tf_type_name(t) for t in _MAP_QUANT_TO_IO_TYPES.keys())), get_tf_type_name(quant_type)))
            else:
                inference_io_types = _MAP_QUANT_TO_IO_TYPES[quant_type]
                if inference_input_type not in inference_io_types:
                    raise ValueError('Unsupported `inference_input_type` value. Expected to be in {}, instead got {}.'.format(tuple((get_tf_type_name(t) for t in inference_io_types)), get_tf_type_name(inference_input_type)))
            input_quant_ops.append(op)
    if len(subgraph.inputs) != len(input_quant_ops):
        logging.warning('For model inputs containing unsupported operations which cannot be quantized, the `inference_input_type` attribute will default to the original type.')
    if inference_input_type == dtypes.uint8:
        for op in input_quant_ops:
            int8_quantization = tensors[op.outputs[0]].quantization
            uint8_quantization = schema_fb.QuantizationParametersT()
            uint8_quantization.scale = [int8_quantization.scale[0]]
            uint8_quantization.zeroPoint = [int8_quantization.zeroPoint[0] + 128]
            tensors[op.inputs[0]].quantization = uint8_quantization
            tensors[op.inputs[0]].type = schema_fb.TensorType.UINT8
    elif inference_input_type in _MAP_QUANT_TO_IO_TYPES:
        remove_tensors_idxs = set()
        for op in input_quant_ops:
            subgraph.inputs[subgraph.inputs == op.inputs[0]] = op.outputs[0]
            if signature_index >= 0:
                signature_def = model.signatureDefs[signature_index]
                for i in range(len(signature_def.inputs)):
                    if signature_def.inputs[i].tensorIndex == op.inputs[0]:
                        signature_def.inputs[i].tensorIndex = op.outputs[0]
            remove_tensors_idxs.add(op.inputs[0])
            operators.remove(op)
        _remove_tensors_from_model(model, remove_tensors_idxs)
    else:
        raise ValueError('Unsupported `inference_input_type` value {}.'.format(get_tf_type_name(inference_input_type)))

def plan(self, state: MemoryPlanningState) -> MemoryPlanningLine:
    if len(self.node.get_inputs_that_alias_output()) > 0:
        return self
    if <MASK>:
        return self
    assert not self.is_reused
    if self.node.get_name() in V.graph.removed_buffers:
        return NullLine(self.wrapper)
    if config.allow_buffer_reuse:
        state.push(buffer_reuse_key(self.node), self)
    return self

def raise_assert_detail(obj, message, left, right, diff=None, first_diff=None, index_values=None) -> NoReturn:
    __tracebackhide__ = True
    msg = f'{obj} are different\n\n{message}'
    if isinstance(index_values, Index):
        index_values = np.asarray(index_values)
    if isinstance(index_values, np.ndarray):
        msg += f'\n[index]: {pprint_thing(index_values)}'
    if isinstance(left, np.ndarray):
        left = pprint_thing(left)
    elif isinstance(left, (CategoricalDtype, StringDtype, NumpyEADtype)):
        left = repr(left)
    if <MASK>:
        right = pprint_thing(right)
    elif isinstance(right, (CategoricalDtype, StringDtype, NumpyEADtype)):
        right = repr(right)
    msg += f'\n[left]:  {left}\n[right]: {right}'
    if diff is not None:
        msg += f'\n[diff]: {diff}'
    if first_diff is not None:
        msg += f'\n{first_diff}'
    raise AssertionError(msg)

def pad_addmm(input: Tensor | None, mat1: Tensor, mat2: Tensor, m_padded_length: int, k_padded_length: int, n_padded_length: int, beta: float=1.0, alpha: float=1.0, mat1_pre_padded: bool=False, mat2_pre_padded: bool=False) -> Tensor:
    if not mat1_pre_padded:
        mat1 = pad_mat1(mat1, m_padded_length=m_padded_length, k_padded_length=k_padded_length)
    if <MASK>:
        mat2 = pad_mat2(mat2, k_padded_length=k_padded_length, n_padded_length=n_padded_length)
    if input is not None:
        if n_padded_length != 0:
            if input.dim() == 2 and input.shape[1] != 1:
                input = pad_dim(input, n_padded_length, 1)
            elif input.dim() == 1 and input.shape[0] != 1:
                input = pad_dim(input, n_padded_length, 0)
        if m_padded_length != 0 and input.dim() == 2 and (input.shape[0] != 1):
            input = pad_dim(input, m_padded_length, 0)
    res = aten.addmm(input, mat1, mat2, beta=beta, alpha=alpha)
    if m_padded_length != 0:
        res = res[:-m_padded_length, :]
    if n_padded_length != 0:
        res = res[:, :-n_padded_length]
    return res

def construct_graph(node: Node, base_mod_env: dict[str, Node], base_mod_attrs: dict[str, torch.fx.graph_module.GraphModule]):
    if node.op == 'placeholder':
        default_value = node.args[0] if len(node.args) > 0 else inspect.Signature.empty
        if <MASK>:
            args = () if default_value is inspect.Signature.empty else (default_value,)
            base_mod_env[node.name] = base_mod_graph.create_node('placeholder', node.name, args=args, type_expr=node.type)
        else:
            base_mod_env[node.name] = base_mod_graph.placeholder(node.target, type_expr=node.type, default_value=default_value)
        base_mod_env[node.name].meta = node.meta.copy()
    elif node.op == 'get_attr':
        base_mod_env[node.name] = base_mod_graph.get_attr(node.target)
        base_mod_env[node.name].meta = node.meta.copy()
        assert isinstance(node.target, str)
        attr_val = _get_attr_from_qualname(m, node.target)
        base_mod_attrs[node.target] = attr_val
    return (base_mod_env, base_mod_attrs)

def _get_format_function(data, **options):
    """
    find the right formatting function for the dtype_
    """
    dtype_ = data.dtype
    dtypeobj = dtype_.type
    formatdict = _get_formatdict(data, **options)
    if dtypeobj is None:
        return formatdict['numpystr']()
    elif issubclass(dtypeobj, _nt.bool):
        return formatdict['bool']()
    elif <MASK>:
        if issubclass(dtypeobj, _nt.timedelta64):
            return formatdict['timedelta']()
        else:
            return formatdict['int']()
    elif issubclass(dtypeobj, _nt.floating):
        if issubclass(dtypeobj, _nt.longdouble):
            return formatdict['longfloat']()
        else:
            return formatdict['float']()
    elif issubclass(dtypeobj, _nt.complexfloating):
        if issubclass(dtypeobj, _nt.clongdouble):
            return formatdict['longcomplexfloat']()
        else:
            return formatdict['complexfloat']()
    elif issubclass(dtypeobj, (_nt.str_, _nt.bytes_)):
        return formatdict['numpystr']()
    elif issubclass(dtypeobj, _nt.datetime64):
        return formatdict['datetime']()
    elif issubclass(dtypeobj, _nt.object_):
        return formatdict['object']()
    elif issubclass(dtypeobj, _nt.void):
        if dtype_.names is not None:
            return StructuredVoidFormat.from_data(data, **options)
        else:
            return formatdict['void']()
    else:
        return formatdict['numpystr']()

def _value_with_fmt(self, val) -> tuple[int | float | bool | str | datetime.datetime | datetime.date, str | None]:
    """
        Convert numpy types to Python types for the Excel writers.

        Parameters
        ----------
        val : object
            Value to be written into cells

        Returns
        -------
        Tuple with the first element being the converted value and the second
            being an optional format
        """
    fmt = None
    if <MASK>:
        val = int(val)
    elif is_float(val):
        val = float(val)
    elif is_bool(val):
        val = bool(val)
    elif is_decimal(val):
        val = Decimal(val)
    elif isinstance(val, datetime.datetime):
        fmt = self._datetime_format
    elif isinstance(val, datetime.date):
        fmt = self._date_format
    elif isinstance(val, datetime.timedelta):
        val = val.total_seconds() / 86400
        fmt = '0'
    else:
        val = str(val)
        if len(val) > 32767:
            warnings.warn(f'Cell contents too long ({len(val)}), truncated to 32767 characters', UserWarning, stacklevel=find_stack_level())
    return (val, fmt)

def _coalesce_timeline(self, device_str):
    """Convert the memory timeline and categories into a memory plot
        consisting of timestamps and their respective sizes by category
        for a given device.

        Input: device
        Output: [timestamps, sizes by category]
        """
    device = torch.device(device_str)
    times: list[int] = []
    sizes: list[list[int]] = []

    def update(key, version, delta) -> None:
        category = self.categories.get(key, version) if isinstance(key, TensorKey) else None
        index = _CATEGORY_TO_INDEX[category] + 1
        sizes[-1][index] += int(delta)
    t_min = -1
    for (t, action, (key, version), numbytes) in self.timeline:
        if key.device != device:
            continue
        if t != -1:
            t = int(t / 1000)
        if <MASK>:
            t_min = t
        if len(times) == 0:
            times.append(t)
            sizes.append([0] + [0 for _ in _CATEGORY_TO_INDEX])
        elif t != times[-1]:
            times.append(t)
            sizes.append(sizes[-1].copy())
        if action in (Action.PREEXISTING, Action.CREATE):
            update(key, version, numbytes)
        elif action == Action.INCREMENT_VERSION:
            update(key, version, -numbytes)
            update(key, version + 1, numbytes)
        elif action == Action.DESTROY:
            update(key, version, -numbytes)
        else:
            raise ValueError(f'Unknown action: {action}')
    times = [t_min if t < 0 else t for t in times]
    return (times, sizes)

def _maybe_modify_args(self, node, full_name, name):
    """Rename keyword args if the function called full_name requires it."""
    renamed_keywords = self._get_applicable_dict('function_keyword_renames', full_name, name)
    if not renamed_keywords:
        return False
    if <MASK>:
        self.add_log(WARNING, node.lineno, node.col_offset, '(Manual check required) upgrading %s may require renaming or removing call arguments, but it was passed variable-length *args or **kwargs. The upgrade script cannot handle these automatically.' % (full_name or name))
    modified = False
    new_keywords = []
    for keyword in node.keywords:
        argkey = keyword.arg
        if argkey in renamed_keywords:
            modified = True
            if renamed_keywords[argkey] is None:
                lineno = getattr(keyword, 'lineno', node.lineno)
                col_offset = getattr(keyword, 'col_offset', node.col_offset)
                self.add_log(INFO, lineno, col_offset, 'Removed argument %s for function %s' % (argkey, full_name or name))
            else:
                keyword.arg = renamed_keywords[argkey]
                lineno = getattr(keyword, 'lineno', node.lineno)
                col_offset = getattr(keyword, 'col_offset', node.col_offset)
                self.add_log(INFO, lineno, col_offset, 'Renamed keyword argument for %s from %s to %s' % (full_name, argkey, renamed_keywords[argkey]))
                new_keywords.append(keyword)
        else:
            new_keywords.append(keyword)
    if modified:
        node.keywords = new_keywords
    return modified

@classmethod
def new(cls, dim: DimSpec, times: int) -> DimSpec:
    if <MASK>:
        return dim
    elif isinstance(dim, Singleton):
        return Broadcast(dim, times)
    else:
        return Repeat(dim, times)

def check_signature_rewritable(graph: torch.fx.GraphModule) -> None:
    input_errors = []
    for node in graph.graph.find_nodes(op='placeholder'):
        assert hasattr(node, '_dynamo_source')
        assert hasattr(graph, '_source_to_user_stacks')
        source = node._dynamo_source
        user_stacks = graph._source_to_user_stacks.get(source)
        if <MASK>:
            continue
        assert len(user_stacks) > 0
        stack = None
        for s in user_stacks:
            if len(s) == 0:
                continue
            stack = s
            break
        if stack is None:
            msg = f'{source.name()}, a closed over free variable'
        else:
            tb = ''.join(traceback.format_list(stack))
            extra = ''
            if len(user_stacks) > 1:
                extra = f'(elided {len(user_stacks) - 1} more accesses)'
            msg = f'{source.name()}, accessed at:\n{tb}{extra}'
        input_errors.append(msg)
    if input_errors:
        raise UserError(UserErrorType.INVALID_INPUT, "Cannot export model which references tensors that are neither buffers/parameters/constants nor are direct inputs.  For each tensor, if you'd like this tensor to be an explicit input, add it as a dummy argument to the top-level model definition you are exporting; if you would like its value to be embedded as an exported constant, wrap its access in a function marked with @assume_constant_result.\n\n" + '\n\n'.join(input_errors))

def module_has_exports(mod):
    for name in dir(mod):
        if <MASK>:
            item = getattr(mod, name)
            if callable(item):
                if get_torchscript_modifier(item) is FunctionModifiers.EXPORT:
                    return True
    return False

@register_annotator('add_relu')
def _annotate_add_relu(gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[Callable[[Node], bool]]=None) -> Optional[list[list[Node]]]:
    annotated_partitions = []
    for node in gm.graph.nodes:
        if node.op != 'call_function' or node.target not in [torch.ops.aten.relu.default, torch.ops.aten.relu_.default]:
            continue
        relu_node = node
        maybe_add = node.args[0]
        if not isinstance(maybe_add, Node) or maybe_add.op != 'call_function' or maybe_add.target not in [torch.ops.aten.add.Tensor, torch.ops.aten.add_.Tensor]:
            continue
        add_node = maybe_add
        if len(add_node.users) > 1:
            continue
        partition = [relu_node, add_node]
        if _is_annotated(partition):
            continue
        if filter_fn and any((not filter_fn(n) for n in partition)):
            continue
        input_act_qspec = get_input_act_qspec(quantization_config)
        output_act_qspec = get_output_act_qspec(quantization_config)
        input_qspec_map = {}
        input_act0 = add_node.args[0]
        if isinstance(input_act0, Node):
            if _is_input_large_scalar(input_act0, gm):
                continue
            if _is_input_non_float_tensor(input_act0):
                continue
            partition.append(input_act0)
            input_qspec_map[input_act0] = input_act_qspec
        input_act1 = add_node.args[1]
        if isinstance(input_act1, Node):
            if <MASK>:
                continue
            if _is_input_non_float_tensor(input_act1):
                continue
            partition.append(input_act1)
            input_qspec_map[input_act1] = input_act_qspec
        add_node.meta['quantization_annotation'] = QuantizationAnnotation(input_qspec_map=input_qspec_map, _annotated=True)
        relu_node.meta['quantization_annotation'] = QuantizationAnnotation(output_qspec=output_act_qspec, _annotated=True)
        annotated_partitions.append(partition)
    return annotated_partitions

def visit_Tuple(self, node):
    if <MASK>:
        elt_types = ()
        for elt in node.elts:
            types_ = self.visit(elt)
            if types_ is None:
                return None
            elt_types += (types_,)
        return set(itertools.product(*elt_types))
    return self._apply_unpacking(node)

def trim_joins(self, targets, joins, path):
    """
        The 'target' parameter is the final field being joined to, 'joins'
        is the full list of join aliases. The 'path' contain the PathInfos
        used to create the joins.

        Return the final target field and table alias and the new active
        joins.

        Always trim any direct join if the target column is already in the
        previous table. Can't trim reverse joins as it's unknown if there's
        anything on the other side of the join.
        """
    joins = joins[:]
    for (pos, info) in enumerate(reversed(path)):
        if len(joins) == 1 or not info.direct:
            break
        if <MASK>:
            break
        join_targets = {t.column for t in info.join_field.foreign_related_fields}
        cur_targets = {t.column for t in targets}
        if not cur_targets.issubset(join_targets):
            break
        targets_dict = {r[1].column: r[0] for r in info.join_field.related_fields if r[1].column in cur_targets}
        targets = tuple((targets_dict[t.column] for t in targets))
        self.unref_alias(joins.pop())
    return (targets, joins[-1], joins)

def get_filters(self, request):
    lookup_params = self.get_filters_params()
    may_have_duplicates = False
    has_active_filters = False
    for (key, value_list) in lookup_params.items():
        for value in value_list:
            if not self.model_admin.lookup_allowed(key, value, request):
                raise DisallowedModelAdminLookup(f'Filtering by {key} not allowed')
    filter_specs = []
    for list_filter in self.list_filter:
        lookup_params_count = len(lookup_params)
        if callable(list_filter):
            spec = list_filter(request, lookup_params, self.model, self.model_admin)
        else:
            field_path = None
            if isinstance(list_filter, (tuple, list)):
                (field, field_list_filter_class) = list_filter
            else:
                (field, field_list_filter_class) = (list_filter, FieldListFilter.create)
            if not isinstance(field, Field):
                field_path = field
                field = get_fields_from_path(self.model, field_path)[-1]
            spec = field_list_filter_class(field, request, lookup_params, self.model, self.model_admin, field_path=field_path)
            if lookup_params_count > len(lookup_params):
                may_have_duplicates |= lookup_spawns_duplicates(self.lookup_opts, field_path)
        if spec and spec.has_output():
            filter_specs.append(spec)
            if lookup_params_count > len(lookup_params):
                has_active_filters = True
    if self.date_hierarchy:
        year = lookup_params.pop('%s__year' % self.date_hierarchy, None)
        if year is not None:
            month = lookup_params.pop('%s__month' % self.date_hierarchy, None)
            day = lookup_params.pop('%s__day' % self.date_hierarchy, None)
            try:
                from_date = datetime(int(year[-1]), int(month[-1] if month is not None else 1), int(day[-1] if day is not None else 1))
            except ValueError as e:
                raise IncorrectLookupParameters(e) from e
            if day:
                to_date = from_date + timedelta(days=1)
            elif month:
                to_date = (from_date + timedelta(days=32)).replace(day=1)
            else:
                to_date = from_date.replace(year=from_date.year + 1)
            if <MASK>:
                from_date = make_aware(from_date)
                to_date = make_aware(to_date)
            lookup_params.update({'%s__gte' % self.date_hierarchy: [from_date], '%s__lt' % self.date_hierarchy: [to_date]})
    try:
        for (key, value) in lookup_params.items():
            lookup_params[key] = prepare_lookup_value(key, value)
            may_have_duplicates |= lookup_spawns_duplicates(self.lookup_opts, key)
        return (filter_specs, bool(filter_specs), lookup_params, may_have_duplicates, has_active_filters)
    except FieldDoesNotExist as e:
        raise IncorrectLookupParameters(e) from e

@classmethod
def from_config(cls, config, custom_objects=None):
    config = config.copy()
    function = cls._parse_function_from_config(config, custom_objects, 'function', 'module', 'function_type')
    output_shape = cls._parse_function_from_config(config, custom_objects, 'output_shape', 'output_shape_module', 'output_shape_type')
    if 'mask' in config:
        mask = cls._parse_function_from_config(config, custom_objects, 'mask', 'mask_module', 'mask_type')
    else:
        mask = None
    config['function'] = function
    config['output_shape'] = output_shape
    config['mask'] = mask
    if <MASK>:
        for key in config['arguments']:
            if isinstance(config['arguments'][key], dict):
                arg_dict = config['arguments'][key]
                if 'type' in arg_dict and arg_dict['type'] == 'ndarray':
                    config['arguments'][key] = np.array(arg_dict['value'])
    return cls(**config)

@classmethod
def normalize_start_end(cls, x: IRNode, dim: int, start: int, end: int) -> tuple[int, int]:
    """
        Normalize start and end such that both are in the range
        [0, x.get_size()[dim]] and start <= end.
        """
    sizevars = V.graph.sizevars
    dim_size = x.get_size()[dim]
    if <MASK>:
        min_func = sympy.Min
        max_func = sympy.Max
    else:
        min_func = sizevars.evaluate_min
        max_func = sizevars.evaluate_max

    def clamp(x: Expr, lower: int, upper: int) -> Expr:
        clamped_lower = x if sizevars.statically_known_geq(x, lower) else max_func(x, lower)
        clamped_full = clamped_lower if sizevars.statically_known_leq(clamped_lower, upper) else min_func(clamped_lower, upper)
        return clamped_full

    def clamp_wrap(val: Union[int, None], lower: int, upper: int, default: Union[Expr, int]) -> Union[Expr, int]:
        if val is None:
            return default
        val = cls.handle_negative_index(val, dim_size)
        return clamp(val, lower, upper)
    start = clamp_wrap(start, 0, dim_size, 0)
    end = clamp_wrap(end, start, dim_size, dim_size)
    return (start, end)

@tf_export.tf_export('experimental.numpy.argsort', v1=[])
@np_utils.np_doc('argsort')
def argsort(a, axis=-1, kind='quicksort', order=None):
    if kind not in ('quicksort', 'stable'):
        raise ValueError(f'Invalid value for argument `kind`. Only kind="quicksort" and kind="stable" are supported. Received: kind={kind}')
    if <MASK>:
        raise ValueError('The `order` argument is not supported. Pass order=None')
    stable = kind == 'stable'
    a = np_array_ops.array(a)
    if a.dtype in (dtypes.complex64, dtypes.complex128):
        raise TypeError(f'argsort does not support complex64/complex128 dtypes. Received dtype: {a.dtype}')

    def _argsort(a, axis, stable):
        if axis is None:
            a = array_ops.reshape(a, [-1])
            axis = 0
        return sort_ops.argsort(a, axis, stable=stable)
    tf_ans = np_utils.cond(math_ops.equal(array_ops.rank(a), 0), lambda : constant_op.constant([0]), lambda : _argsort(a, axis, stable))
    if ops.is_auto_dtype_conversion_enabled():
        return np_array_ops.array(tf_ans, dtype=int)
    else:
        return np_array_ops.array(tf_ans, dtype=np.intp)

def _get_variable_nodes_from_graph_def(graph_def):
    """Get the list of Variable nodes from `graph_def`.

  Args:
    graph_def: An instance of `GraphDef`.  This GraphDef *must*
      have already been optimized by Grappler.  In particular, function
      inlining must have already happened.

  Returns:
    A dict mapping string names of variables to tuples `(node_def, modified)`,
    where `node_def` is the `NodeDef` corresponding to variable, and `modified`
    is a python bool describing whether the variable is modified during runtime.
  """
    variables = [n for n in graph_def.node if n.op == 'VarHandleOp']
    variable_name_map = dict(((n.name, n) for n in variables))
    child_map = collections.defaultdict(lambda : [])
    for n in graph_def.node:
        for inp in n.input:
            if not inp.startswith('^'):
                child_map[inp].append(n)
    variables = {}
    for (v_name, v_node) in variable_name_map.items():
        queue = list(child_map[v_name])
        processed = set([])
        while queue:
            n_current = queue.pop()
            if n_current.name in processed:
                continue
            processed.add(n_current.name)
            if n_current.op in _PASS_THROUGH_VARIABLE_OPS:
                children = child_map.get(n_current.name, [])
                queue.extend(children)
            elif n_current.op not in _READ_ONLY_VARIABLE_OPS:
                variables[v_name] = (v_node, True)
                queue = []
        if <MASK>:
            variables[v_name] = (v_node, False)
    return variables

def construct_constants(constants_list_from_yaml: list[Any]) -> str:
    constants_list_part = []
    for constant_from_yaml in constants_list_from_yaml:
        convert_constant = None
        if isinstance(constant_from_yaml, str):
            convert_constant = f'"{constant_from_yaml}"'
        elif isinstance(constant_from_yaml, bool):
            convert_constant = 'true' if constant_from_yaml else 'false'
        elif constant_from_yaml is None:
            convert_constant = ''
        elif <MASK>:
            convert_constant = str(constant_from_yaml)
        else:
            raise ValueError(f'The type of {constant_from_yaml} is {type(constant_from_yaml)}. Please add change in construct_constants function in gen_mobile_upgraders.py.')
        constants_list_part.append(ONE_CONSTANT.substitute(constant=convert_constant))
    if len(constants_list_part) == 0:
        return CONSTANTS_LIST_EMPTY
    return CONSTANT_LIST.substitute(constant_list=''.join(constants_list_part).lstrip('\n'))

def convert_value(self, conv_val) -> TermValue:
    """
        convert the expression that is in the term to something that is
        accepted by pytables
        """

    def stringify(value):
        if self.encoding is not None:
            return pprint_thing_encoded(value, encoding=self.encoding)
        return pprint_thing(value)
    kind = ensure_decoded(self.kind)
    meta = ensure_decoded(self.meta)
    if kind == 'datetime' or (kind and kind.startswith('datetime64')):
        if isinstance(conv_val, (int, float)):
            conv_val = stringify(conv_val)
        conv_val = ensure_decoded(conv_val)
        conv_val = Timestamp(conv_val).as_unit('ns')
        if <MASK>:
            conv_val = conv_val.tz_convert('UTC')
        return TermValue(conv_val, conv_val._value, kind)
    elif kind in ('timedelta64', 'timedelta'):
        if isinstance(conv_val, str):
            conv_val = Timedelta(conv_val)
        else:
            conv_val = Timedelta(conv_val, unit='s')
        conv_val = conv_val.as_unit('ns')._value
        return TermValue(int(conv_val), conv_val, kind)
    elif meta == 'category':
        metadata = extract_array(self.metadata, extract_numpy=True)
        result: npt.NDArray[np.intp] | np.intp | int
        if conv_val not in metadata:
            result = -1
        else:
            result = np.flatnonzero(metadata == conv_val)[0]
        return TermValue(result, result, 'integer')
    elif kind == 'integer':
        try:
            v_dec = Decimal(conv_val)
        except InvalidOperation:
            float(conv_val)
        else:
            conv_val = int(v_dec.to_integral_exact(rounding='ROUND_HALF_EVEN'))
        return TermValue(conv_val, conv_val, kind)
    elif kind == 'float':
        conv_val = float(conv_val)
        return TermValue(conv_val, conv_val, kind)
    elif kind == 'bool':
        if isinstance(conv_val, str):
            conv_val = conv_val.strip().lower() not in ['false', 'f', 'no', 'n', 'none', '0', '[]', '{}', '']
        else:
            conv_val = bool(conv_val)
        return TermValue(conv_val, conv_val, kind)
    elif isinstance(conv_val, str):
        return TermValue(conv_val, stringify(conv_val), 'string')
    else:
        raise TypeError(f'Cannot compare {conv_val} of type {type(conv_val)} to {kind} column')

def deserialize_argument_spec(self, x: Argument) -> ep.ArgumentSpec:
    log.debug('[deserialize_argument_spec] %s', x)
    if x.type == 'as_tensor':
        return ep.TensorArgument(name=x.as_tensor.name)
    elif <MASK>:
        return ep.SymIntArgument(name=x.as_sym_int.as_name)
    elif x.type == 'as_sym_float':
        return ep.SymFloatArgument(name=x.as_sym_float.as_name)
    elif x.type == 'as_custom_obj':
        return ep.ConstantArgument(name=x.as_custom_obj.name, value=self.deserialize_input(x))
    else:
        return ep.ConstantArgument(name='', value=self.deserialize_input(x))

def fuzz_inputs_specs(self, output_spec: Spec) -> list[Spec]:
    """Generate input spec for flatten operation."""
    if not isinstance(output_spec, TensorSpec):
        raise ValueError('FlattenOperator can only produce TensorSpec outputs')
    output_numel = 1
    for dim in output_spec.size:
        output_numel *= dim
    if len(output_spec.size) == 1:
        input_size = fuzz_tensor_size()
        if len(input_size) < 2:
            input_size = (2, 2)
    else:
        input_size = fuzz_tensor_size()
        if len(input_size) < 3:
            input_size = (2, 2, 2)
    input_numel = 1
    for dim in input_size:
        input_numel *= dim
    if input_numel != output_numel:
        if output_numel == 0:
            input_size = tuple(list(input_size)[:-1] + [0])
        elif <MASK>:
            prefix_numel = 1
            for dim in input_size[:-1]:
                prefix_numel *= dim
            if prefix_numel > 0:
                last_dim = output_numel // prefix_numel
                if last_dim * prefix_numel == output_numel:
                    input_size = tuple(list(input_size)[:-1] + [last_dim])
                else:
                    input_size = (output_numel,)
            else:
                input_size = (output_numel,)
    from torchfuzz.tensor_fuzzer import fuzz_valid_stride
    input_stride = fuzz_valid_stride(tuple(input_size))
    return [TensorSpec(size=tuple(input_size), stride=input_stride, dtype=output_spec.dtype)]

def __deepcopy__(self, memo):
    no_copy = set(['_graph', '_thread_local', '_metrics_lock'])
    shallow_copy = set(['_scope', '_always_reuse_variable_scope'])
    cls = self.__class__
    result = cls.__new__(cls)
    memo[id(self)] = result
    for (k, v) in self.__dict__.items():
        if k in no_copy:
            setattr(result, k, v)
        elif k in shallow_copy:
            setattr(result, k, copy.copy(v))
        elif <MASK>:
            setattr(result, k, v)
        else:
            setattr(result, k, copy.deepcopy(v, memo))
    return result

def run(self) -> None:
    ignores = (CWD / '.gitignore').read_text(encoding='utf-8')
    for wildcard in filter(None, ignores.splitlines()):
        if <MASK>:
            if 'BEGIN NOT-CLEAN-FILES' in wildcard:
                break
        else:
            wildcard = wildcard.lstrip('./')
            for filename in glob.iglob(wildcard):
                try:
                    os.remove(filename)
                except OSError:
                    shutil.rmtree(filename, ignore_errors=True)

def create_collation(self, schema_editor):
    args = {'locale': schema_editor.quote_name(self.locale)}
    if self.provider != 'libc':
        args['provider'] = schema_editor.quote_name(self.provider)
    if <MASK>:
        args['deterministic'] = 'false'
    schema_editor.execute('CREATE COLLATION %(name)s (%(args)s)' % {'name': schema_editor.quote_name(self.name), 'args': ', '.join((f'{option}={value}' for (option, value) in args.items()))})

def _formatter(x):
    if x is None or (is_scalar(x) and isna(x)):
        return nat_rep
    if not isinstance(x, Timedelta):
        x = Timedelta(x)
    result = x._repr_base(format=format)
    if <MASK>:
        result = f"'{result}'"
    return result

def file_summary(blocks: Sequence[dict[str, Any]], report_all: bool=False) -> dict[str, str]:

    def to_line(v: dict[str, Any]) -> str | None:
        if (status := v['status']) == 'good':
            if not report_all:
                return None
            fail = ''
        elif <MASK>:
            fail = ': (grandfathered)'
        else:
            assert status == 'bad'
            fail = ': FAIL'
        name = v['name']
        lines = v['lines']
        docs = v['docstring_len']
        parens = '()' if name.startswith('def ') else ''
        return f'{name}{parens}: lines={lines!r}, docs={docs!r}{fail}'
    t = make_terse(blocks)
    r = {k: line for (k, v) in t.items() if (line := to_line(v))}
    while r and all((k.startswith(' ') for k in r)):
        r = {k[1:]: v for (k, v) in r.items()}
    return r

@final
def _validate_key_length(self, key: tuple) -> tuple:
    if len(key) > self.ndim:
        if key[0] is Ellipsis:
            key = key[1:]
            if <MASK>:
                raise IndexingError(_one_ellipsis_message)
            return self._validate_key_length(key)
        raise IndexingError('Too many indexers')
    return key

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName, remove_non_owning_ref_types: bool=False, symint: bool=False) -> NamedCType:
    r = valuetype_type(t, binds=binds, mutable=mutable, symint=symint)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            if mutable and (not local.use_const_ref_for_mutable_tensors()):
                return NamedCType(binds, MutRefCType(BaseCType(tensorT)))
            else:
                return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if str(t.elem) == 'Tensor':
            if mutable and (not local.use_const_ref_for_mutable_tensors()):
                return NamedCType(binds, MutRefCType(BaseCType(tensorT)))
            else:
                return NamedCType(binds, ConstRefCType(OptionalCType(BaseCType(tensorT))))
        elif str(t.elem) == 'Scalar':
            return NamedCType(binds, ConstRefCType(OptionalCType(BaseCType(scalarT))))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'SymInt':
            if symint:
                return NamedCType(binds, BaseCType(optionalSymIntArrayRefT))
            else:
                return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds, symint=symint)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if str(t.elem) == 'int':
            if remove_non_owning_ref_types:
                return NamedCType(binds, VectorCType(BaseCType(longT)))
            else:
                return NamedCType(binds, BaseCType(intArrayRefT))
        if str(t.elem) == 'SymInt':
            if remove_non_owning_ref_types:
                if symint:
                    return NamedCType(binds, VectorCType(BaseCType(SymIntT)))
                else:
                    return NamedCType(binds, VectorCType(BaseCType(longT)))
            elif symint:
                return NamedCType(binds, BaseCType(symIntArrayRefT))
            else:
                return NamedCType(binds, BaseCType(intArrayRefT))
        if str(t.elem) == 'Tensor':
            if local.use_ilistref_for_tensor_lists():
                return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
            else:
                return NamedCType(binds, BaseCType(tensorListT))
        elif str(t.elem) == 'Scalar':
            return NamedCType(binds, ArrayRefCType(BaseCType(scalarT)))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elif <MASK>:
            return NamedCType(binds, ConstRefCType(ListCType(OptionalCType(BaseCType(tensorT)))))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds, symint=symint)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

@classmethod
def call_nn_parameter(cls, tx, data=None, requires_grad=True):
    """A call to torch.nn.Parameter() gets lifted to before the graph"""
    if tx.export:
        unimplemented_v2(gb_type='Attempted to use `torch.nn.Parameter()` with export', context='', explanation='Dynamo does not support this.', hints=['Do not use `torch.nn.Parameter()` with export.', *graph_break_hints.SUPPORTABLE])
    if isinstance(requires_grad, variables.VariableTracker):
        try:
            requires_grad = requires_grad.as_python_constant()
        except NotImplementedError:
            unimplemented_v2(gb_type='non-constant `requires_grad` argument to `torch.nn.Parameter`', context=f'requires_grad={requires_grad}', explanation='Dynamo does not support this.', hints=['Change `requires_grad` to be a bool.', *graph_break_hints.USER_ERROR])
    if not isinstance(data, variables.TensorVariable):
        unimplemented_v2(gb_type='`torch.nn.Parameter()` with unsupported data type', context=f'data={data}', explanation='Called `torch.nn.Parameter()` with non-Tensor argument.', hints=['Ensure the argument to `torch.nn.Parameter()` is a `torch.Tensor`.', *graph_break_hints.USER_ERROR])
    if data.source:
        return cls._nn_param_via_prefix_insert(tx, data, requires_grad)
    if config.graph_break_on_nn_param_ctor:
        unimplemented_v2(gb_type='Attempted to use `torch.nn.Parameter()` constructor with Dynamo', context='', explanation='Dynamo does not support this', hints=['Try to construct `torch.nn.Parameter()` outside the compiled region.', 'If this is not possible, turn `graph_break_on_nn_param_ctor` off', *graph_break_hints.SUPPORTABLE])
    if <MASK>:
        unimplemented_v2(gb_type='Attempted to use torch.nn.Parameter constructor with tensor subclass', context=str(data), explanation='Dynamo does not support this.', hints=[*graph_break_hints.SUPPORTABLE])
    if not can_convert_to_tracable_parameter():
        unimplemented_v2(gb_type='`torch.nn.Parameter`: cannot convert to traceable tracable', context='', explanation='convert_tracable_parameter is set to False.', hints=['Check usage of context manager: do_not_convert_to_tracable_parameter', *graph_break_hints.DIFFICULT])
    try:
        shape = tuple(data.var_getattr(tx, 'shape').as_python_constant())
        dtype = data.var_getattr(tx, 'dtype').as_python_constant()
        device = data.var_getattr(tx, 'device').as_python_constant()
    except NotImplementedError as e:
        unimplemented_v2(gb_type='`torch.nn.Parameter` with non-constant Tensor attributes', context=f'data={data}', explanation='Dynamo does not support this.', hints=["Ensure the Tensor argument's shape, dtype, and device are correct.", *graph_break_hints.USER_ERROR], from_exc=e)
    placeholder = tx.output.synthetic_graph_input(new_parameter_placeholder, [shape, dtype, device, requires_grad])
    if data.requires_grad:
        data = data.call_method(tx, 'detach', [], {})
    from .builder import wrap_fx_proxy
    result = wrap_fx_proxy(tx, tx.output.create_proxy('call_function', tracable_create_parameter, (data.as_proxy(), placeholder.as_proxy()), {}), source=placeholder.source)
    assert isinstance(result, variables.TensorVariable)
    result.class_type = torch.nn.Parameter
    result.has_grad_fn = False
    return result

def inner(prim: Callable):
    nonlocal aten_op

    @wraps(prim)
    @out_wrapper(exact_dtype=exact_dtype)
    @elementwise_unary_scalar_wrapper
    @elementwise_type_promotion_wrapper(type_promoting_args=('a',), type_promotion_kind=type_promotion_kind)
    def _ref(a: TensorLikeType) -> TensorLikeType:
        if <MASK>:
            extra_meta(a)
        output = prim(a)
        return handle_noncontiguous_outputs([a], output)
    if aten_op is infer_aten_op:
        aten_op = utils.get_aten_op(prim, prim.__name__)
    if aten_op is not None:
        register_decomposition(aten_op)(_ref)
    return _ref

def _fixed_indexer(size: Sequence[int], stride: Optional[Sequence[int]]=None, offset: Expr=Integer(0)) -> Callable[[Sequence[Expr]], Expr]:
    """A closure containing math to read a given element"""

    def indexer(index: Sequence[int]) -> int:
        assert stride is not None and len(index) == len(stride)
        assert len(index) == len(size)
        result = offset
        for (idx, st, sz) in zip(index, stride, size):
            if <MASK>:
                result = result + idx * st
        return result
    return indexer

def _get_dependencies(self, src: str, module_name: str, is_package: bool) -> list[str]:
    """Return all modules that this source code depends on.

        Dependencies are found by scanning the source code for import-like statements.

        Arguments:
            src: The Python source code to analyze for dependencies.
            module_name: The name of the module that ``src`` corresponds to.
            is_package: Whether this module should be treated as a package.
                See :py:meth:`save_source_string` for more info.

        Returns:
            A list containing modules detected as direct dependencies in
            ``src``.  The items in the list are guaranteed to be unique.
        """
    package_name = module_name if is_package else module_name.rsplit('.', maxsplit=1)[0]
    try:
        dep_pairs = find_files_source_depends_on(src, package_name)
    except Exception as e:
        self.dependency_graph.add_node(module_name, error=PackagingErrorReason.DEPENDENCY_RESOLUTION_FAILED, error_context=str(e))
        return []
    dependencies = {}
    for (dep_module_name, dep_module_obj) in dep_pairs:
        if dep_module_obj is not None:
            possible_submodule = f'{dep_module_name}.{dep_module_obj}'
            if <MASK>:
                dependencies[possible_submodule] = True
                continue
        if self._module_exists(dep_module_name):
            dependencies[dep_module_name] = True
    return list(dependencies.keys())

def _unsqueeze_helper(g: jit_utils.GraphContext, input, axes_i):
    if len(axes_i) == 0:
        return input
    elif _is_constant(axes_i[0]):
        if g.opset >= 13:
            axes = g.op('Constant', value_t=torch.tensor(axes_i, dtype=torch.long))
            return g.op('Unsqueeze', input, axes)
        return g.op('Unsqueeze', input, axes_i=axes_i)
    if <MASK>:
        raise errors.SymbolicValueError('Opset version must be >= 13 for Unsqueeze with dynamic axes.', input)
    return g.op('Unsqueeze', input, axes_i[0])

