def find_common_type(types):
    """
    Find a common data type among the given dtypes.

    Parameters
    ----------
    types : list of dtypes

    Returns
    -------
    pandas extension or numpy dtype

    See Also
    --------
    numpy.find_common_type

    """
    if not types:
        raise ValueError('no types given')
    first = types[0]
    if lib.dtypes_all_equal(list(types)):
        return first
    types = list(dict.fromkeys(types).keys())
    if any((isinstance(t, ExtensionDtype) for t in types)):
        for t in types:
            if isinstance(t, ExtensionDtype):
                res = t._get_common_dtype(types)
                if res is not None:
                    return res
        return np.dtype('object')
    if <MASK>:
        return np.dtype(max(types))
    if all((lib.is_np_dtype(t, 'm') for t in types)):
        return np.dtype(max(types))
    has_bools = any((t.kind == 'b' for t in types))
    if has_bools:
        for t in types:
            if t.kind in 'iufc':
                return np.dtype('object')
    return np_find_common_type(*types)

def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    key = lib.item_from_zerodim(key)
    key = com.apply_if_callable(key, self)
    if is_hashable(key) and (not is_iterator(key)) and (not isinstance(key, slice)):
        is_mi = isinstance(self.columns, MultiIndex)
        if not is_mi and (self.columns.is_unique and key in self.columns or key in self.columns.drop_duplicates(keep=False)):
            return self._get_item(key)
        elif is_mi and self.columns.is_unique and (key in self.columns):
            return self._getitem_multilevel(key)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    if isinstance(key, DataFrame):
        return self.where(key)
    if com.is_bool_indexer(key):
        return self._getitem_bool_array(key)
    is_single_key = isinstance(key, tuple) or not is_list_like(key)
    if is_single_key:
        if self.columns.nlevels > 1:
            return self._getitem_multilevel(key)
        indexer = self.columns.get_loc(key)
        if is_integer(indexer):
            indexer = [indexer]
    else:
        if is_iterator(key):
            key = list(key)
        indexer = self.columns._get_indexer_strict(key, 'columns')[1]
    if <MASK>:
        indexer = np.where(indexer)[0]
    if isinstance(indexer, slice):
        return self._slice(indexer, axis=1)
    data = self.take(indexer, axis=1)
    if is_single_key:
        if data.shape[1] == 1 and (not isinstance(self.columns, MultiIndex)):
            return data._get_item(key)
    return data

def explicit_super(code: types.CodeType, instructions: list[Instruction]) -> None:
    """convert super() with no args into explicit arg form"""
    cell_and_free = (code.co_cellvars or ()) + (code.co_freevars or ())
    if not len(code.co_varnames):
        return
    output = []
    for (idx, inst) in enumerate(instructions):
        output.append(inst)
        if inst.opname == 'LOAD_GLOBAL' and inst.argval == 'super':
            nexti = instructions[idx + 1]
            if nexti.arg == 0 and (sys.version_info >= (3, 12) and nexti.opname == 'CALL' or (sys.version_info >= (3, 11) and sys.version_info < (3, 12) and (nexti.opname == 'PRECALL')) or (sys.version_info < (3, 11) and nexti.opname == 'CALL_FUNCTION')):
                assert '__class__' in cell_and_free
                output.append(create_instruction('LOAD_DEREF', argval='__class__'))
                first_var = code.co_varnames[0]
                if <MASK>:
                    output.append(create_instruction('LOAD_DEREF', argval=first_var))
                else:
                    output.append(create_instruction('LOAD_FAST', argval=first_var))
                nexti.arg = 2
                nexti.argval = 2
                if nexti.opname == 'PRECALL':
                    call_inst = instructions[idx + 2]
                    call_inst.arg = 2
                    call_inst.argval = 2
    instructions[:] = output

