def get_step_logger(logger: logging.Logger) -> Callable[..., None]:
    if not disable_progress:
        pbar.update(1)
        if <MASK>:
            pbar.set_postfix_str(f'{logger.name}')
    step = next(_step_counter)

    def log(level: int, msg: str, **kwargs: Any) -> None:
        if 'stacklevel' not in kwargs:
            kwargs['stacklevel'] = 2
        logger.log(level, 'Step %s: %s', step, msg, **kwargs)
    return log

def request_stop(self, ex=None):
    """Request that the threads stop.

    After this is called, calls to `should_stop()` will return `True`.

    Note: If an exception is being passed in, in must be in the context of
    handling the exception (i.e. `try: ... except Exception as ex: ...`) and not
    a newly created one.

    Args:
      ex: Optional `Exception`, or Python `exc_info` tuple as returned by
        `sys.exc_info()`.  If this is the first call to `request_stop()` the
        corresponding exception is recorded and re-raised from `join()`.
    """
    with self._lock:
        ex = self._filter_exception(ex)
        if <MASK>:
            if isinstance(ex, tuple):
                (_, ex_instance, _) = ex
                raise ex_instance
            elif ex is not None:
                (_, ex_instance, _) = sys.exc_info()
                raise ex_instance
        if not self._stop_event.is_set():
            if ex and self._exc_info_to_raise is None:
                if isinstance(ex, tuple):
                    logging.info('Error reported to Coordinator: %s', compat.as_str_any(ex[1]), exc_info=ex)
                    self._exc_info_to_raise = ex
                else:
                    logging.info('Error reported to Coordinator: %s, %s', type(ex), compat.as_str_any(ex))
                    self._exc_info_to_raise = sys.exc_info()
                if len(self._exc_info_to_raise) != 3 or not self._exc_info_to_raise[0] or (not self._exc_info_to_raise[1]):
                    try:
                        raise ValueError('ex must be a tuple or sys.exc_info must return the current exception: %s' % self._exc_info_to_raise)
                    except ValueError:
                        self._exc_info_to_raise = sys.exc_info()
            self._stop_event.set()

def __init__(self, params: ParamsT, lr: Union[float, Tensor]=0.001, momentum: float=0, dampening: float=0, weight_decay: Union[float, Tensor]=0, nesterov: bool=False, *, maximize: bool=False, foreach: Optional[bool]=None, differentiable: bool=False, fused: Optional[bool]=None):
    if isinstance(lr, Tensor) and lr.numel() != 1:
        raise ValueError('Tensor lr must be 1-element')
    if lr < 0.0:
        raise ValueError(f'Invalid learning rate: {lr}')
    if momentum < 0.0:
        raise ValueError(f'Invalid momentum value: {momentum}')
    if weight_decay < 0.0:
        raise ValueError(f'Invalid weight_decay value: {weight_decay}')
    defaults = {'lr': lr, 'momentum': momentum, 'dampening': dampening, 'weight_decay': weight_decay, 'nesterov': nesterov, 'maximize': maximize, 'foreach': foreach, 'differentiable': differentiable, 'fused': fused}
    if <MASK>:
        raise ValueError('Nesterov momentum requires a momentum and zero dampening')
    super().__init__(params, defaults)
    if fused:
        self._step_supports_amp_scaling = True
        self._need_device_dtype_check_for_fused = True
        if differentiable:
            raise RuntimeError('`fused` does not support `differentiable`')
        if foreach:
            raise RuntimeError('`fused` and `foreach` cannot be `True` together.')

def __init__(self, var):
    self.var = var
    self.literal = None
    self.lookups = None
    self.translate = False
    self.message_context = None
    if <MASK>:
        raise TypeError('Variable must be a string or number, got %s' % type(var))
    try:
        if '.' in var or 'e' in var.lower():
            self.literal = float(var)
            if var[-1] == '.':
                raise ValueError
        else:
            self.literal = int(var)
    except ValueError:
        if var[0:2] == '_(' and var[-1] == ')':
            self.translate = True
            var = var[2:-1]
        try:
            self.literal = mark_safe(unescape_string_literal(var))
        except ValueError:
            if VARIABLE_ATTRIBUTE_SEPARATOR + '_' in var or var[0] == '_':
                raise TemplateSyntaxError("Variables and attributes may not begin with underscores: '%s'" % var)
            for c in ['+', '-']:
                if c in var:
                    raise TemplateSyntaxError("Invalid character ('%s') in variable name: '%s'" % (c, var))
            self.lookups = tuple(var.split(VARIABLE_ATTRIBUTE_SEPARATOR))

def render(self) -> str:

    def render_single(s: Union[int, AutoDynamic, AutoUnset, InferStride]) -> str:
        if s is auto_dynamic:
            return '?'
        elif s is auto_unset:
            return 'auto unset'
        elif <MASK>:
            return f'S({s.dim})'
        else:
            return str(s)

    def render_tuple(ss: tuple[Union[int, AutoDynamic, InferStride], ...]) -> str:
        return '[' + ', '.join((render_single(s) for s in ss)) + ']'
    if self.size is auto_dynamic and self.stride is auto_dynamic:
        if self.scalar is auto_dynamic:
            return 'fully dynamic scalar or tensor'
        else:
            return f'scalar {self.scalar}'
    elif self.scalar is auto_dynamic:
        if isinstance(self.size, tuple) and isinstance(self.stride, tuple):
            return f'tensor size={render_tuple(self.size)} stride={render_tuple(self.stride)}'
    return f'unusual {repr(self)}'

