def __init__(self, param, cursor, strings_only=False):
    if settings.USE_TZ and (isinstance(param, datetime.datetime) and (not isinstance(param, Oracle_datetime))):
        param = Oracle_datetime.from_datetime(param)
    string_size = 0
    has_boolean_data_type = cursor.database.features.supports_boolean_expr_in_select_clause
    if not has_boolean_data_type:
        if param is True:
            param = 1
        elif param is False:
            param = 0
    if hasattr(param, 'bind_parameter'):
        self.force_bytes = param.bind_parameter(cursor)
    elif <MASK>:
        self.force_bytes = param
    else:
        self.force_bytes = force_str(param, cursor.charset, strings_only)
        if isinstance(self.force_bytes, str):
            string_size = len(force_bytes(param, cursor.charset, strings_only))
    if hasattr(param, 'input_size'):
        self.input_size = param.input_size
    elif string_size > 4000:
        self.input_size = Database.DB_TYPE_CLOB
    elif isinstance(param, datetime.datetime):
        self.input_size = Database.DB_TYPE_TIMESTAMP
    elif has_boolean_data_type and isinstance(param, bool):
        self.input_size = Database.DB_TYPE_BOOLEAN
    else:
        self.input_size = None

@simple_wraps(fn)
def inner_fn(*args):
    args_maybe_cloned = [maybe_to_fresh_input(i, t, meta) for (i, t) in enumerate(args)]
    (outs, outs_descs) = call_and_expect_output_descs(fn, args_maybe_cloned)
    assert isinstance(outs, (tuple, list))
    outs = list(outs)
    assert len(meta.output_info) == len(outs)
    mutated_input_pairs = [(x, InputMutationAOTOutput(src)) for (i, (x, src)) in enumerate(zip(args_maybe_cloned, args_descs)) if i in meta.mutated_inp_runtime_indices]
    if <MASK>:
        (mutated_inputs_to_return, mutated_inputs_to_return_descs) = zip(*mutated_input_pairs)
    else:
        (mutated_inputs_to_return, mutated_inputs_to_return_descs) = ((), ())
    intermediate_bases = []
    intermediate_bases_descs = []
    for (o, info, o_desc) in zip(outs, meta.output_info, outs_descs):
        if info.output_type == OutputType.alias_of_intermediate_save_as_output:
            assert isinstance(o, torch.Tensor), f'Expected tensor for intermediate base, got {type(o)}'
            intermediate_bases.append(o._base)
            intermediate_bases_descs.append(IntermediateBaseAOTOutput(o_desc))
    assert meta.num_intermediate_bases == len(intermediate_bases)
    fw_outs_to_return = (*mutated_inputs_to_return, *outs, *intermediate_bases)
    fw_outs_to_return_descs = (*mutated_inputs_to_return_descs, *outs_descs, *intermediate_bases_descs)
    mutated_inputs_grad_mask = [meta.input_info[meta.mutated_inp_runtime_indices[i]].mutates_data and meta.input_info[meta.mutated_inp_runtime_indices[i]].requires_grad for (i, x) in enumerate(mutated_inputs_to_return)]
    output_grad_mask = [meta.output_info[i].output_type in [OutputType.non_alias, OutputType.unsafe_view_alias, OutputType.custom_function_view] and issubclass(meta.output_info[i].raw_type, Tensor) and meta.output_info[i].requires_grad for (i, x) in enumerate(outs)]
    intermediate_base_grad_mask = [True for _ in range(len(intermediate_bases))]
    out_grad_mask = mutated_inputs_grad_mask + output_grad_mask + intermediate_base_grad_mask
    assert len(out_grad_mask) == len(fw_outs_to_return)
    if not aot_config.disable_functionalization:
        for arg in args_maybe_cloned:
            if not isinstance(arg, Tensor):
                continue
            sync_functional_tensor(arg)
    return ((fw_outs_to_return, out_grad_mask), (fw_outs_to_return_descs, out_grad_mask))

def dtype_name(dtype):
    """Returns the string name for this `dtype`."""
    dtype = dtypes.as_dtype(dtype)
    if hasattr(dtype, 'name'):
        return dtype.name
    if <MASK>:
        return dtype.__name__
    return str(dtype)

def inner(e: PySymType) -> Union[int, bool, float, Proxy]:
    n = e.node
    if n.constant is not None:
        return n.constant
    if e.node.expr.is_number:
        if isinstance(e, SymBool):
            return bool(e.node.expr)
        elif <MASK>:
            return int(e.node.expr)
        return float(e.node.expr)
    else:
        assert isinstance(e, py_sym_types)
        return get_proxy_slot(e, tracer).force()

@staticmethod
def _find_common_device(func: OpOverload, flat_args: Sequence[object]) -> tuple[torch.device, bool]:
    common_device = None
    has_scalar_only_inputs = False
    is_cpu_zero_dim = None
    mixed_device_fns = ordered_set(aten._foreach_copy.default)
    bypass_zero_dim_cpu_tensor_check_ops = ordered_set(aten.nextafter.default)

    def check_cpu_device(device: torch.device) -> bool:
        return device.type == 'cpu'

    def cpu_zero_dim(t: Tensor) -> bool:
        return check_cpu_device(t.device) and t.dim() == 0

    def merge_devices(t: object) -> None:
        nonlocal common_device
        nonlocal is_cpu_zero_dim
        if not isinstance(t, FakeTensor):
            return
        if common_device is None:
            common_device = t.device
            is_cpu_zero_dim = cpu_zero_dim(t)
            return
        t_is_cpu_zero_dim = cpu_zero_dim(t)
        if t.device == common_device:
            if is_cpu_zero_dim:
                is_cpu_zero_dim = t_is_cpu_zero_dim
            return
        is_bypass_zero_dim_cpu_tensor_check_op = func in bypass_zero_dim_cpu_tensor_check_ops
        if t_is_cpu_zero_dim and (not is_bypass_zero_dim_cpu_tensor_check_op):
            return
        if <MASK>:
            common_device = t.device
            is_cpu_zero_dim = t_is_cpu_zero_dim
            return
        if func in mixed_device_fns:
            if any(map(check_cpu_device, (common_device, t.device))):
                return
        prefer_device_type = torch._functorch.config.fake_tensor_prefer_device_type
        if prefer_device_type is not None:
            common_has_preferred = prefer_device_type in common_device.type
            t_has_preferred = prefer_device_type in t.device.type
            if not common_has_preferred and t_has_preferred:
                common_device = t.device
                is_cpu_zero_dim = t_is_cpu_zero_dim
                return
            elif common_has_preferred and (not t_has_preferred):
                return
        raise RuntimeError(f'Unhandled FakeTensor Device Propagation for {func}, found two different devices {common_device}, {t.device}')
    for arg in flat_args:
        merge_devices(arg)
    if should_allow_numbers_as_tensors(func) and common_device is None:
        has_scalar_only_inputs = True
        common_device = torch.device('cpu')
    assert common_device is not None, f'Could not find common device for {func}'
    return (common_device, has_scalar_only_inputs)

def create_micro_gemm(name, m, n, k, input_dtype, input2_dtype, output_dtype=None, compute_dtype=None, alpha=1, num_threads=-1, use_ref=True, q_group_size=None) -> Optional[CppMicroGemm]:
    """
    Based on the provided info, try to find the config of the micro-kernel that would
    deliver the best performance in terms of lower latency for this case.
    """

    def create_from_config(cls, config: CppMicroGemmConfig):
        return cls(name, config.input_dtype, config.input2_dtype, config.output_dtype, config.compute_dtype, config.register_blocking, alpha)

    def skip_amx_kernel_for_woq(dynamic_M):
        if dynamic_M or input_dtype != torch.bfloat16 or input2_dtype not in [torch.int8, torch.uint8]:
            return False
        m_threshold = 5
        return m < m_threshold
    assert isinstance(n, int) or n.is_number, n
    assert isinstance(k, int) or k.is_number, k
    from ..utils import has_free_symbols
    dynamic_M = has_free_symbols((m,))
    m = V.graph.sizevars.size_hint(m, fallback=1) if dynamic_M else m
    assert isinstance(m, int) or m.is_number, m
    if output_dtype is None:
        output_dtype = input_dtype
    if compute_dtype is None:
        compute_dtype = output_dtype
    if num_threads < 0:
        num_threads = parallel_num_threads()
    vec_isa = pick_vec_isa()
    matched_configs = []
    for (cls, configs) in micro_gemm_configs.items():
        for config in configs:
            if <MASK>:
                continue
            if config.input_dtype == input_dtype and config.compute_dtype == compute_dtype and (config.input2_dtype == input2_dtype) and (config.output_dtype == output_dtype):
                if config.extra_check is not None and (not config.extra_check(config, m, n, k, alpha, num_threads, dynamic_M=dynamic_M, q_group_size=q_group_size, vec_isa=vec_isa)):
                    continue
                (block_m, block_n, block_k) = config.register_blocking
                if config.vec_isa_cls == VecAMX and skip_amx_kernel_for_woq(dynamic_M):
                    continue
                isa_score = 0
                if config.vec_isa_cls == VecAMX:
                    isa_score += 1
                dividable_score = 0
                if m % block_m == 0:
                    dividable_score += 1
                if n % block_n == 0:
                    dividable_score += 1
                if k % block_k == 0:
                    dividable_score += 1
                occupancy_score = 0
                n_blocks = (n + block_n - 1) // block_n
                total_mxn_blocks = n_blocks * ((m + block_m - 1) // block_m)
                if n_blocks >= num_threads:
                    occupancy_score += 1
                if total_mxn_blocks >= num_threads:
                    occupancy_score += 1
                register_bytes = block_m * block_n * config.compute_dtype.itemsize + (block_m * block_k + block_k * block_n) * config.input_dtype.itemsize
                size_score = register_bytes
                if occupancy_score == 0:
                    size_score = 0 - register_bytes
                matched_configs.append(((isa_score, dividable_score, occupancy_score, size_score), cls, config))
    if len(matched_configs) == 0:
        if use_ref:
            return CppMicroGemmRef(name, input_dtype, input2_dtype, output_dtype, compute_dtype, alpha)
        else:
            return None
    return create_from_config(*max(matched_configs, key=operator.itemgetter(0))[1:])

def forward(self, args: list[torch.Tensor]) -> list[torch.Tensor]:
    if <MASK>:
        self.init(args)
    comp = self.comp
    assert comp is not None
    outs = [torch.empty_like(out) for out in self.out_templates]
    assert len(args) == len(self.inp_mem_fmts)
    fixed_args = []
    for idx in range(len(args)):
        fmt = self.inp_mem_fmts[idx]
        if fmt == 0:
            fixed_args.append(args[idx].contiguous())
        elif fmt == 1:
            fixed_args.append(args[idx].permute(0, 2, 3, 1).contiguous())
        else:
            raise ValueError('Invalid mem_fmt')
    comp.run(fixed_args, outs)
    assert len(outs) == len(self.out_mem_fmts)
    for idx in range(len(self.out_templates)):
        fmt = self.out_mem_fmts[idx]
        if fmt in (0, 2):
            pass
        elif fmt == 1:
            outs[idx] = outs[idx].permute(0, 3, 1, 2)
        else:
            raise ValueError('Invalid mem_fmt')
    return outs

def init(self, R, V, dim, contiguous, device):
