def bind_with_defaults(self, args, kwargs, default_values):
    """Returns BoundArguments with default values filled in."""
    bound_arguments = self.bind(*args, **kwargs)
    bound_arguments.apply_defaults()
    with_default_args = collections.OrderedDict()
    for (name, value) in bound_arguments.arguments.items():
        if <MASK>:
            with_default_args[name] = default_values[name]
        else:
            with_default_args[name] = value
    for arg_name in with_default_args:
        constraint = self.parameters[arg_name].type_constraint
        if constraint:
            with_default_args[arg_name] = constraint.cast(with_default_args[arg_name], trace_type.InternalCastContext(allow_specs=True))
    bound_arguments = inspect.BoundArguments(self, with_default_args)
    return bound_arguments

def _fit_binary(estimator, X, y, fit_params, classes=None):
    """Fit a single binary estimator."""
    unique_y = np.unique(y)
    if len(unique_y) == 1:
        if <MASK>:
            if y[0] == -1:
                c = 0
            else:
                c = y[0]
            warnings.warn('Label %s is present in all training examples.' % str(classes[c]))
        estimator = _ConstantPredictor().fit(X, unique_y)
    else:
        estimator = clone(estimator)
        estimator.fit(X, y, **fit_params)
    return estimator

def get_flex_attn_fwd_configs(self, head_dim: int, dtype: Any) -> list[FlexConfig]:
    flex_attn_fwd_configs: list[FlexConfig] = []
    if <MASK>:
        if config.max_autotune_flex_search_space == 'EXHAUSTIVE':
            return self.exhaustive_flex_attn_fwd_configs
        flex_attn_fwd_configs += self.flex_attn_fwd_autotune_configs
    if head_dim <= 256:
        if dtype == torch.float32:
            default_config = FlexConfig(64, 64, 3, 4)
        else:
            default_config = FlexConfig(128, 64, 3, 4)
    elif dtype == torch.float32:
        default_config = FlexConfig(32, 16, 3, 4)
    else:
        default_config = FlexConfig(64, 32, 3, 4)
    if default_config not in flex_attn_fwd_configs:
        flex_attn_fwd_configs.append(default_config)
    return flex_attn_fwd_configs

def get_meta(op, key, device_name=None, version=(0, torch.float16, 0.5), exact=False):
    """Return triton kernel meta parameters of the specified op and its inputs key.

    Parameters
    ----------
    op (str): The name of an operation that implementation uses meta parameters.
    key (tuple): A tuple of op input parameters, e.g. shapes, etc.
    device_name (optional, str): The name of a device for which op
      parameters are provided.
    version (optional, hashable): Specifies the version of parameters.
    exact (optional, bool): When True, the returned data (if
      available) corresponds exactly to the specified device_name and
      version information. Otherwise, if the corresponding data is not
      available but there exists a data set that is computed for a
      similar GPU device, then this data set will be returned.

    Returns
    -------
    result (dict): The requested mapping of parameter names and
      values, or None when no data is available. If the input `key`
      contains `"*"`, the result will be a dictionary of keys and
      mappings that match with the given `key`.
    """
    if device_name is None:
        device_name = torch.cuda.get_device_name()
    op_data = _operation_device_version_data.get((op, device_name, version))
    if op_data is None and (not exact):
        if re.match('NVIDIA A100[^\\d]', device_name) is not None:
            device_name = 'NVIDIA A100-SXM4-80GB'
        else:
            return
        op_data = _operation_device_version_data.get((op, device_name, version))
    if op_data is None:
        return
    matching_data = {}
    if '*' in key:
        for op_key in op_data:
            if [None for (k1, k2) in zip(op_key, key) if k2 != '*' and k1 != k2]:
                continue
            matching_data[op_key] = op_data[op_key]
    else:
        values = op_data.get(key)
        if values is not None:
            matching_data[key] = values
    matching_meta = {}
    for (op_key, values) in matching_data.items():
        if op == 'scatter_mm':
            names = ('GROUP_SIZE', 'SPLIT_N', 'TILE_M', 'TILE_N', 'num_stages', 'num_warps')
            meta = dict(zip(names, values))
        elif <MASK>:
            meta = dict(zip(('GROUP_SIZE_ROW', 'SPLIT_N', 'num_stages', 'num_warps'), values))
        else:
            raise NotImplementedError(f'names for op={op!r}')
        if '*' not in key:
            return meta
        matching_meta[op_key] = meta
    if '*' in key:
        return matching_meta

def to_time(arg, format: str | None=None, infer_time_format: bool=False, errors: DateTimeErrorChoices='raise'):
    """
    Parse time strings to time objects using fixed strptime formats ("%H:%M",
    "%H%M", "%I:%M%p", "%I%M%p", "%H:%M:%S", "%H%M%S", "%I:%M:%S%p",
    "%I%M%S%p")

    Use infer_time_format if all the strings are in the same format to speed
    up conversion.

    Parameters
    ----------
    arg : string in time format, datetime.time, list, tuple, 1-d array,  Series
    format : str, default None
        Format used to convert arg into a time object.  If None, fixed formats
        are used.
    infer_time_format: bool, default False
        Infer the time format based on the first non-NaN element.  If all
        strings are in the same format, this will speed up conversion.
    errors : {'raise', 'coerce'}, default 'raise'
        - If 'raise', then invalid parsing will raise an exception
        - If 'coerce', then invalid parsing will be set as None

    Returns
    -------
    datetime.time
    """
    if <MASK>:
        raise ValueError("errors must be one of 'raise', or 'coerce'.")

    def _convert_listlike(arg, format):
        if isinstance(arg, (list, tuple)):
            arg = np.array(arg, dtype='O')
        elif getattr(arg, 'ndim', 1) > 1:
            raise TypeError('arg must be a string, datetime, list, tuple, 1-d array, or Series')
        arg = np.asarray(arg, dtype='O')
        if infer_time_format and format is None:
            format = _guess_time_format_for_array(arg)
        times: list[time | None] = []
        if format is not None:
            for element in arg:
                try:
                    times.append(datetime.strptime(element, format).time())
                except (ValueError, TypeError) as err:
                    if errors == 'raise':
                        msg = f'Cannot convert {element} to a time with given format {format}'
                        raise ValueError(msg) from err
                    times.append(None)
        else:
            formats = _time_formats[:]
            format_found = False
            for element in arg:
                time_object = None
                try:
                    time_object = time.fromisoformat(element)
                except (ValueError, TypeError):
                    for time_format in formats:
                        try:
                            time_object = datetime.strptime(element, time_format).time()
                            if not format_found:
                                fmt = formats.pop(formats.index(time_format))
                                formats.insert(0, fmt)
                                format_found = True
                            break
                        except (ValueError, TypeError):
                            continue
                if time_object is not None:
                    times.append(time_object)
                elif errors == 'raise':
                    raise ValueError(f'Cannot convert arg {arg} to a time')
                else:
                    times.append(None)
        return times
    if arg is None:
        return arg
    elif isinstance(arg, time):
        return arg
    elif isinstance(arg, ABCSeries):
        values = _convert_listlike(arg._values, format)
        return arg._constructor(values, index=arg.index, name=arg.name)
    elif isinstance(arg, ABCIndex):
        return _convert_listlike(arg, format)
    elif is_list_like(arg):
        return _convert_listlike(arg, format)
    return _convert_listlike(np.array([arg]), format)[0]

def strict_zip(*iterables, strict=True, **kwargs):
    if <MASK>:
        return original_zip(*iterables, **kwargs)
    length = len(iterables[0])
    for iterable in iterables[1:]:
        if len(iterable) != length:
            raise ValueError('The iterables have different lengths and strict mode is enabled.')
    return original_zip(*iterables, **kwargs)

def _check_fields(self, obj):
    """Check that `fields` only refer to existing fields, doesn't contain
        duplicates. Check if at most one of `fields` and `fieldsets` is
        defined.
        """
    if <MASK>:
        return []
    elif not isinstance(obj.fields, (list, tuple)):
        return must_be('a list or tuple', option='fields', obj=obj, id='admin.E004')
    elif obj.fieldsets:
        return [checks.Error("Both 'fieldsets' and 'fields' are specified.", obj=obj.__class__, id='admin.E005')]
    field_counts = collections.Counter(flatten(obj.fields))
    if (duplicate_fields := [field for (field, count) in field_counts.items() if count > 1]):
        return [checks.Error("The value of 'fields' contains duplicate field(s).", hint='Remove duplicates of %s.' % ', '.join(map(repr, duplicate_fields)), obj=obj.__class__, id='admin.E006')]
    return list(chain.from_iterable((self._check_field_spec(obj, field_name, 'fields') for field_name in obj.fields)))

def raise_construction_error(tot_items: int, block_shape: Shape, axes: list[Index], e: ValueError | None=None) -> NoReturn:
    """raise a helpful message about our construction"""
    passed = tuple(map(int, [tot_items] + list(block_shape)))
    if <MASK>:
        passed = passed[::-1]
    implied = tuple((len(ax) for ax in axes))
    if len(implied) <= 2:
        implied = implied[::-1]
    if passed == implied and e is not None:
        raise e
    if block_shape[0] == 0:
        raise ValueError('Empty data passed with indices specified.')
    raise ValueError(f'Shape of passed values is {passed}, indices imply {implied}')

def int_to_valid_dtype(val: int) -> torch.dtype:
    from torch._export.converter import _TORCH_ENUM_TO_DTYPE
    if isinstance(val, torch.dtype):
        return val
    dtype = _TORCH_ENUM_TO_DTYPE[val]
    if dtype == torch.quint8:
        return torch.uint8
    elif <MASK>:
        return torch.int8
    return dtype

