def _train_for_several_steps(self, model: nn.Module, num_steps: int, autocast: bool, lr: float=0.01, fsdp_cpu_offload: Optional[CPUOffload]=None, save_model: bool=False, mixed_precision: Optional[MixedPrecision]=None, enable_sharded_grad_scaler: bool=False, use_pure_fp16: bool=False, sharded_grad_scaler_kwargs: Optional[dict[str, Any]]=None):
    cpu_offload_params = fsdp_cpu_offload and fsdp_cpu_offload.offload_params
    model_device = next(model.parameters()).device
    if <MASK>:
        sharded_grad_scaler_kwargs = {}
    sharded_grad_scaler = ShardedGradScaler(enabled=enable_sharded_grad_scaler, **sharded_grad_scaler_kwargs)
    optim = torch.optim.SGD(model.parameters(), lr=lr, momentum=0.9)
    for _ in range(num_steps):
        optim.zero_grad()
        with torch.amp.autocast(DEVICE_TYPE, enabled=autocast):
            input = model.module.get_input(torch.device(DEVICE_TYPE))
            if use_pure_fp16 or (mixed_precision and (not isinstance(model, FSDP))):
                if isinstance(input, torch.Tensor):
                    input = input.half()
                else:
                    input = tuple((x.half() for x in input))
            output = model(*input)
            if cpu_offload_params and isinstance(model, FSDP) and (model.sharding_strategy not in NO_RESHARD_AFTER_FORWARD_STRATEGIES):
                for p in model.parameters():
                    self.assertEqual(p.device, torch.device('cpu'))
            loss = model.module.get_loss(input, output).to(model_device)
        loss = sharded_grad_scaler.scale(loss)
        if not mixed_precision and (not use_pure_fp16):
            assert loss.dtype == torch.float32, 'loss data type should be float32, as the original                     parameter data type is float32.'
        elif use_pure_fp16:
            self.assertEqual(loss.dtype, torch.float16)
        elif isinstance(model, FSDP):
            assert mixed_precision is not None
            self.assertEqual(loss.dtype, mixed_precision.param_dtype)
        else:
            self.assertEqual(loss.dtype, torch.float32)
        model.module.run_backward(loss)
        if cpu_offload_params and isinstance(model, FSDP):
            for p in model.parameters():
                self.assertEqual(p.device, torch.device('cpu'))
        sharded_grad_scaler.step(optim)
        sharded_grad_scaler.update()
        if save_model:
            state_dict = {k: v.clone() for (k, v) in model.state_dict().items()}
            _zero_model(model)
            model.load_state_dict(state_dict)
    if isinstance(model, FSDP):
        model._assert_state(TrainingState.IDLE)
    return loss.detach()

@simple_wraps(compiled_fn)
def runtime_wrapper(args: list[Any]):
    cm = record_runtime_wrapper_prologue_enter()
    orig_inputs = {i: args[i] for i in epilogue_args_idx}
    if keep_input_mutations:
        mutated_args = (args[i] for i in runtime_metadata.mutated_graph_handled_indices_seen_by_autograd)
        torch.autograd.graph.increment_version(mutated_args)
    if trace_joint:
        args_ = list(args)
        for idx in indices_of_inps_to_detach:
            if isinstance(args_[idx], torch.Tensor):
                args_[idx] = args_[idx].detach()
        with torch.autograd._force_original_view_tracking(True), torch.enable_grad():
            record_runtime_wrapper_prologue_exit(cm)
            all_outs = call_func_at_runtime_with_args(compiled_fn, args_, disable_amp=disable_amp, steal_args=True)
    else:
        grad_enabled = torch.is_grad_enabled()
        try:
            if grad_enabled:
                torch._C._set_grad_enabled(False)
            record_runtime_wrapper_prologue_exit(cm)
            all_outs = call_func_at_runtime_with_args(compiled_fn, args, disable_amp=disable_amp, steal_args=True)
        finally:
            if grad_enabled:
                torch._C._set_grad_enabled(True)
    del args
    num_mutated_runtime_inps = runtime_metadata.num_mutated_inp_runtime_indices
    num_intermediate_bases = runtime_metadata.num_intermediate_bases
    assert len(all_outs) == num_mutated_runtime_inps + runtime_metadata.num_outputs + num_intermediate_bases
    num_mutations_to_apply = runtime_metadata.num_mutated_inp_runtime_indices
    if num_mutations_to_apply > 0:
        updated_inputs = all_outs[:num_mutations_to_apply]
        fw_outs = all_outs[num_mutations_to_apply:]
        for (i, inpt_idx) in enumerate(runtime_metadata.mutated_inp_runtime_indices):
            meta = runtime_metadata.input_info[inpt_idx]
            if not meta.mutates_data and (not meta.mutates_metadata):
                continue
            original_inpt = orig_inputs[inpt_idx]
            updated_inpt = updated_inputs[i]
            if <MASK>:
                if trace_joint:
                    assert isinstance(updated_inpt, TensorAlias)
                    updated_inpt = updated_inpt.alias
                with torch.no_grad():
                    original_inpt.set_(updated_inpt)
                continue
            if meta.mutates_metadata and (not meta.mutates_data):
                if trace_joint:
                    assert isinstance(updated_inpt, TensorAlias)
                    updated_inpt = updated_inpt.alias
                original_inpt.as_strided_(updated_inpt.size(), updated_inpt.stride(), updated_inpt.storage_offset())
            else:
                if meta.mutates_data and meta.mutates_metadata:
                    original_inpt.as_strided_(updated_inpt.size(), updated_inpt.stride(), updated_inpt.storage_offset())
                else:
                    assert meta.mutates_data
                if meta.is_leaf and original_inpt.requires_grad:
                    original_inpt.detach().copy_(updated_inpt)
                else:
                    original_inpt.copy_(updated_inpt)
    else:
        fw_outs = all_outs
    if runtime_metadata.num_outputs_aliased > 0:
        expect_num_outputs = len(output_handlers) + runtime_metadata.num_intermediate_bases
        assert len(fw_outs) == expect_num_outputs
        ret_outs = [handler(orig_inputs, fw_outs, out) for (out, handler) in builtins.zip(fw_outs, output_handlers)]
    else:
        ret_outs = fw_outs
    if runtime_metadata.dynamic_outputs:
        for (t, o) in zip(ret_outs, runtime_metadata.output_info):
            if o.dynamic_dims is None:
                continue
            maybe_mark_dynamic_helper(t, o.dynamic_dims)
    if runtime_metadata.grad_enabled_mutation is not None:
        torch._C._set_grad_enabled(runtime_metadata.grad_enabled_mutation)
    return ret_outs

def _fit_stochastic(self, X, y, sample_weight, activations, deltas, coef_grads, intercept_grads, layer_units, incremental):
    params = self.coefs_ + self.intercepts_
    if not incremental or not hasattr(self, '_optimizer'):
        if self.solver == 'sgd':
            self._optimizer = SGDOptimizer(params, self.learning_rate_init, self.learning_rate, self.momentum, self.nesterovs_momentum, self.power_t)
        elif self.solver == 'adam':
            self._optimizer = AdamOptimizer(params, self.learning_rate_init, self.beta_1, self.beta_2, self.epsilon)
    if self.early_stopping and incremental:
        raise ValueError('partial_fit does not support early_stopping=True')
    early_stopping = self.early_stopping
    if early_stopping:
        should_stratify = is_classifier(self) and self.n_outputs_ == 1
        stratify = y if should_stratify else None
        if sample_weight is None:
            (X_train, X_val, y_train, y_val) = train_test_split(X, y, random_state=self._random_state, test_size=self.validation_fraction, stratify=stratify)
            sample_weight_train = sample_weight_val = None
        else:
            (X_train, X_val, y_train, y_val, sample_weight_train, sample_weight_val) = train_test_split(X, y, sample_weight, random_state=self._random_state, test_size=self.validation_fraction, stratify=stratify)
        if X_val.shape[0] < 2:
            raise ValueError("The validation set is too small. Increase 'validation_fraction' or the size of your dataset.")
        if is_classifier(self):
            y_val = self._label_binarizer.inverse_transform(y_val)
    else:
        (X_train, y_train, sample_weight_train) = (X, y, sample_weight)
        X_val = y_val = sample_weight_val = None
    n_samples = X_train.shape[0]
    sample_idx = np.arange(n_samples, dtype=int)
    if self.batch_size == 'auto':
        batch_size = min(200, n_samples)
    else:
        if self.batch_size > n_samples:
            warnings.warn('Got `batch_size` less than 1 or larger than sample size. It is going to be clipped')
        batch_size = np.clip(self.batch_size, 1, n_samples)
    try:
        self.n_iter_ = 0
        for it in range(self.max_iter):
            if self.shuffle:
                sample_idx = shuffle(sample_idx, random_state=self._random_state)
            accumulated_loss = 0.0
            for batch_slice in gen_batches(n_samples, batch_size):
                if self.shuffle:
                    batch_idx = sample_idx[batch_slice]
                    X_batch = _safe_indexing(X_train, batch_idx)
                else:
                    batch_idx = batch_slice
                    X_batch = X_train[batch_idx]
                y_batch = y_train[batch_idx]
                if sample_weight is None:
                    sample_weight_batch = None
                else:
                    sample_weight_batch = sample_weight_train[batch_idx]
                activations[0] = X_batch
                (batch_loss, coef_grads, intercept_grads) = self._backprop(X_batch, y_batch, sample_weight_batch, activations, deltas, coef_grads, intercept_grads)
                accumulated_loss += batch_loss * (batch_slice.stop - batch_slice.start)
                grads = coef_grads + intercept_grads
                self._optimizer.update_params(params, grads)
            self.n_iter_ += 1
            self.loss_ = accumulated_loss / X_train.shape[0]
            self.t_ += n_samples
            self.loss_curve_.append(self.loss_)
            if self.verbose:
                print('Iteration %d, loss = %.8f' % (self.n_iter_, self.loss_))
            self._update_no_improvement_count(early_stopping, X_val, y_val, sample_weight_val)
            self._optimizer.iteration_ends(self.t_)
            if <MASK>:
                if early_stopping:
                    msg = 'Validation score did not improve more than tol=%f for %d consecutive epochs.' % (self.tol, self.n_iter_no_change)
                else:
                    msg = 'Training loss did not improve more than tol=%f for %d consecutive epochs.' % (self.tol, self.n_iter_no_change)
                is_stopping = self._optimizer.trigger_stopping(msg, self.verbose)
                if is_stopping:
                    break
                else:
                    self._no_improvement_count = 0
            if incremental:
                break
            if self.n_iter_ == self.max_iter:
                warnings.warn("Stochastic Optimizer: Maximum iterations (%d) reached and the optimization hasn't converged yet." % self.max_iter, ConvergenceWarning)
    except KeyboardInterrupt:
        warnings.warn('Training interrupted by user.')
    if early_stopping:
        self.coefs_ = self._best_coefs
        self.intercepts_ = self._best_intercepts

@contextlib.contextmanager
def _enable(compiler_fn: Callable[..., Any], dynamic: bool=True, ignore_active_disable_ctx: bool=True) -> Generator[None, None, None]:
    if not ignore_active_disable_ctx and active_disable_ctx:
        yield
    else:
        if dynamic:
            assert type(dynamic) is bool
        from torch._dynamo import eval_frame
        if eval_frame._stance.stance == 'force_eager':
            global compiled_autograd_enabled_force_eager
            compiled_autograd_enabled_force_eager = True
            try:
                yield
            finally:
                compiled_autograd_enabled_force_eager = False
        else:
            if torch.cuda.is_available():
                from torch._inductor import cudagraph_trees
            (prior_compiler, prior_dynamic) = torch._C._dynamo.compiled_autograd.set_autograd_compiler(functools.partial(AutogradCompilerInstance, compiler_fn), dynamic)
            if snapshot_verbose_logging_enabled():
                torch._C._dynamo.compiled_autograd.set_verbose_logger(verbose_log)
            global compiled_autograd_enabled
            compiled_autograd_enabled = True
            global depth
            prior_depth = depth
            depth += 1
            try:
                with torch.autograd.set_multithreading_enabled(False):
                    yield
            finally:
                if <MASK>:
                    compiled_autograd_enabled = False
                torch._C._dynamo.compiled_autograd.set_autograd_compiler(prior_compiler, prior_dynamic)
                depth -= 1
                assert depth == prior_depth, 'Nested Compiled Autograd Contexts must return before their parent context'

def LOAD_SUPER_ATTR(self, inst: Instruction) -> None:
    self.CALL_FUNCTION(dataclasses.replace(inst, argval=2))
    assert inst.arg is not None
    if <MASK>:
        self.LOAD_METHOD(inst)
    else:
        self._load_attr(inst.argval)

def delete(self, loc) -> Index:
    if is_integer(loc):
        if <MASK>:
            return self[1:]
        if loc in (-1, len(self) - 1):
            return self[:-1]
        if len(self) == 3 and loc in (1, -2):
            return self[::2]
    elif lib.is_list_like(loc):
        slc = lib.maybe_indices_to_slice(np.asarray(loc, dtype=np.intp), len(self))
        if isinstance(slc, slice):
            other = self[slc]
            return self.difference(other, sort=False)
    return super().delete(loc)

def emit_ck_instance(self, op: 'CKGemmOperation'):
    struct_name = 'DeviceBatchedGemmMultiD_Xdl_CShuffle_V3' if self.is_batched else 'DeviceGemmMultiD_Xdl_CShuffle_V3'
    template_definition = '\n    // Gemm operator {{operation_name}}\n    using Operation_{{operation_name}} =\n        ck::tensor_operation::device::{{struct_name}}<\n            {{template_params}}>;\n\n'
    template_type = '\n    Operation_{{operation_name}}\n'
    template_params = []
    for (field_name, field_value) in op.dict_items():
        if isinstance(field_value, tuple):
            tuple_elements = ', '.join(map(str, iter(field_value)))
            if 'ds' in field_name:
                arg = f'/* {field_name} */ Tuple<{tuple_elements}>'
            else:
                arg = f'/* {field_name} */ S<{tuple_elements}>'
            template_params.append(arg)
        elif <MASK>:
            template_params.append(f'/* {field_name} */ {field_value}')
    operation_name = op.name().replace('(', '').replace(',', '').replace(')', '')
    return (self._template_from_string(template_definition).render(operation_name=operation_name, template_params=(',\n' + 12 * ' ').join(template_params), struct_name=struct_name), self._template_from_string(template_type).render(operation_name=operation_name))

def build_graph(parameters):
    """Build a conv graph given `parameters`."""
    (input_shape, filter_shape) = get_tensor_shapes(parameters)
    input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=input_shape)
    if <MASK>:
        filter_input = create_tensor_data(np.float32, filter_shape, min_value=-10, max_value=10)
        input_tensors = [input_tensor]
    else:
        filter_input = tf.compat.v1.placeholder(dtype=tf.float32, name='filter', shape=filter_shape)
        input_tensors = [input_tensor, filter_input]
    out = tf.nn.conv2d(input=input_tensor, filters=filter_input, strides=parameters['strides'], dilations=parameters['dilations'], padding=parameters['padding'], data_format=parameters['data_format'])
    return (input_tensors, [out])

def _inv_call(self, y):
    """
        Inverts the transform `y => x`.
        """
    if self._cache_size == 0:
        return self._inverse(y)
    (x_old, y_old) = self._cached_x_y
    if <MASK>:
        return x_old
    x = self._inverse(y)
    self._cached_x_y = (x, y)
    return x

def _maximum_aten(a: Union[TensorLikeType, NumberType], b: Union[TensorLikeType, NumberType]) -> TensorLikeType:
    if isinstance(a, TensorLike) and isinstance(b, Number):
        b = scalar_tensor(b, dtype=a.dtype, device=a.device)
    elif <MASK>:
        a = scalar_tensor(a, dtype=b.dtype, device=b.device)
    return torch.maximum(a, b)

def _EmbeddingParams(num_shards, vocab_size, dtype=dtypes.float32, shape=None, use_shapeless_placeholder=False):
    p = []
    params = {}
    feed_dict = {}
    if not shape:
        shape = [10]
    for i in range(num_shards):
        shard_shape = [vocab_size // num_shards] + shape
        if i < vocab_size % num_shards:
            shard_shape[0] += 1
        param_name = _PName(i)
        if <MASK>:
            param = array_ops.placeholder(dtype, shape=None, name=param_name)
        else:
            param = constant_op.constant(1.0, shape=shard_shape, dtype=dtype, name=param_name)
        p.append(param)
        np_type = 'f' if dtype == dtypes.float32 else 'd'
        val = np.random.rand(*shard_shape).astype(np_type) + 1
        params[param_name + ':0'] = val
        feed_dict[param.name] = val
    return (p, params, feed_dict)

def unknown_shape(rank=None, **kwargs) -> 'TensorShape':
    """Returns an unknown TensorShape, optionally with a known rank.

  Args:
    rank: (Optional) If specified, the number of dimensions in the shape.
    **kwargs: For backwards compatibility.

  Returns:
    An unknown TensorShape.

  Raises:
    TypeError: In case of invalid arguments.
  """
    if <MASK>:
        rank = kwargs.pop('ndims')
    if kwargs:
        raise TypeError('Unknown argument: %s' % kwargs)
    if rank is None:
        return TensorShape(None)
    else:
        return TensorShape([Dimension(None)] * rank)

def call_obj_hasattr(self, tx: 'InstructionTranslator', name):
    from . import GetAttrVariable
    from .builtin import BuiltinVariable
    if <MASK>:
        return ConstantVariable(True)
    try:
        var = BuiltinVariable(getattr).call_function(tx, [self, ConstantVariable(name)], {})
        ret_val = not isinstance(var, GetAttrVariable)
    except AttributeError:
        ret_val = False
    if self.source:
        install_guard(AttrSource(self.source, name).make_guard(GuardBuilder.HASATTR))
    return ConstantVariable(ret_val)

@staticmethod
def _string_to_components(spec=None):
    """Stateless portion of device spec string parsing.

    Args:
      spec: An optional string specifying a device specification.

    Returns:
      The parsed components of `spec`. Note that the result of this function
      must go through attribute setters of DeviceSpec, and should therefore NOT
      be used directly.
    """
    cached_result = _STRING_TO_COMPONENTS_CACHE.get(spec)
    if cached_result is not None:
        return cached_result
    raw_spec = spec
    (job, replica, task, device_type, device_index) = (None, None, None, None, None)
    spec = spec or ''
    splits = [x.split(':') for x in spec.split('/')]
    valid_device_types = DeviceSpecV2._get_valid_device_types()
    for y in splits:
        ly = len(y)
        if y:
            if ly == 2 and y[0] == 'job':
                job = y[1]
            elif ly == 2 and y[0] == 'replica':
                replica = y[1]
            elif ly == 2 and y[0] == 'task':
                task = y[1]
            elif (ly == 1 or ly == 2) and y[0].upper() in valid_device_types:
                if device_type is not None:
                    raise ValueError(f'Multiple device types are not allowed while parsing the device spec: {spec}.')
                device_type = y[0].upper()
                if <MASK>:
                    device_index = int(y[1])
            elif ly == 3 and y[0] == 'device':
                if device_type is not None:
                    raise ValueError(f'Multiple device types are not allowed while parsing the device spec: {spec}.')
                device_type = y[1]
                if y[2] != '*':
                    device_index = int(y[2])
            elif ly and y[0] != '':
                raise ValueError(f"Unknown attribute '{y[0]}' is encountered while parsing the device spec: '{spec}'.")
    output = (job, replica, task, device_type, device_index)
    _STRING_TO_COMPONENTS_CACHE[raw_spec] = output
    return output

@staticmethod
def masked(mask, body, other):
    if mask is not None and torch.version.hip is not None:
        mask = V.kernel.cse.generate(V.kernel.compute, f'{mask}.to(tl.int1)', dtype=torch.bool, shape=mask.shape)
    nodes = body.graph.find_nodes(op='output')
    assert nodes, 'graph for body does not contain an output'
    need_where = False
    for node in nodes:
        for arg in node.args:
            if arg.target != 'load' or should_unwrap_unspec_arg(arg.args[1]):
                need_where = True
                break
    value = None if need_where else other
    with V.kernel.mask_loads(mask, value=value) as new_mask:
        result = body()
    if need_where:
        if <MASK>:
            other = bool(other)
        other = V.kernel.cse.generate(V.kernel.compute, f'tl.full({result}.shape, {constant_repr(other)}, {result}.dtype)', bounds=ValueRanges.wrap(other), dtype=result.dtype, shape=result.shape)
        ret = ops.where(new_mask, result, other)
    else:
        ret = result
    ret.mask_vars.discard(new_mask)
    return ret

def _should_save_eager_input_vals(target: Any, args_kwargs: Optional[tuple[tuple[Argument, ...], dict[str, Argument]]]=None) -> bool:
    from torch._higher_order_ops.invoke_subgraph import InvokeSubgraphHOP
    if not callable(target):
        return False
    if isinstance(target, (torch._higher_order_ops.triton_kernel_wrap.TritonKernelWrapperFunctional, torch._higher_order_ops.triton_kernel_wrap.TritonKernelWrapperMutation, InvokeSubgraphHOP)):
        return True
    if args_kwargs is not None and (target is torch.ops.higher_order.auto_functionalized or target is torch.ops.higher_order.auto_functionalized_v2):
        args = args_kwargs[0]
        assert isinstance(args[0], (torch._ops.OpOverload, torch._ops.HigherOrderOperator))
        return _should_save_eager_input_vals(args[0], None)
    if target is torch.ops.higher_order.with_effects:
        return False
    if isinstance(target, torch._ops.HigherOrderOperator):
        if <MASK>:
            raise RuntimeError(f'NYI: The HOP {target} has an input that is an OpOverload that needs exact strides. We probably need special logic to propagate the FakeTensor vals. Please file an issue.')
    if isinstance(target, torch._ops.OpOverload):
        from torch._library.utils import get_layout_constraint_tag
        return get_layout_constraint_tag(target) == torch._C.Tag.needs_exact_strides
    return False

def _get_secret(self, request):
    """
        Return the CSRF secret originally associated with the request, or None
        if it didn't have one.

        If the CSRF_USE_SESSIONS setting is false, raises InvalidTokenFormat if
        the request's secret has invalid characters or an invalid length.
        """
    if settings.CSRF_USE_SESSIONS:
        try:
            csrf_secret = request.session.get(CSRF_SESSION_KEY)
        except AttributeError:
            raise ImproperlyConfigured('CSRF_USE_SESSIONS is enabled, but request.session is not set. SessionMiddleware must appear before CsrfViewMiddleware in MIDDLEWARE.')
    else:
        try:
            csrf_secret = request.COOKIES[settings.CSRF_COOKIE_NAME]
        except KeyError:
            csrf_secret = None
        else:
            _check_token_format(csrf_secret)
    if csrf_secret is None:
        return None
    if <MASK>:
        csrf_secret = _unmask_cipher_token(csrf_secret)
    return csrf_secret

def is_main_has_gpu(tree: ast.AST) -> bool:

    def _contains_has_gpu(node: ast.AST) -> bool:
        if isinstance(node, ast.Name) and node.id in ['HAS_GPU', 'RUN_GPU']:
            return True
        elif isinstance(node, ast.BoolOp):
            return any((_contains_has_gpu(value) for value in node.values))
        elif <MASK>:
            return _contains_has_gpu(node.operand)
        elif isinstance(node, ast.Compare):
            return _contains_has_gpu(node.left) or any((_contains_has_gpu(comp) for comp in node.comparators))
        elif isinstance(node, (ast.IfExp, ast.Call)):
            return False
        return False
    for node in ast.walk(tree):
        if isinstance(node, ast.If):
            if isinstance(node.test, ast.Compare) and isinstance(node.test.left, ast.Name) and (node.test.left.id == '__name__'):
                if any((isinstance(comp, ast.Constant) and comp.value == '__main__' for comp in node.test.comparators)):
                    for inner_node in node.body:
                        if isinstance(inner_node, ast.If) and _contains_has_gpu(inner_node.test):
                            return True
    return False

def init_fn(script_module):
    for name in concrete_type.get_attributes().keys():
        orig_value = getattr(nn_module, name)
        orig_value = orig_value.value if isinstance(orig_value, torch.jit.Attribute) else orig_value
        cpp_module.setattr(name, orig_value)
    for (name, sub_concrete_type) in concrete_type.get_modules():
        orig_value = getattr(nn_module, name)
        assert isinstance(orig_value, Module), f'Expected Module but got {type(orig_value)}'
        module_type = sub_concrete_type.jit_type
        if <MASK>:
            scripted = interface_script(module_type, orig_value)
        elif isinstance(orig_value, torch.jit.ScriptModule):
            scripted = orig_value
        else:
            scripted = create_script_module_impl(orig_value, sub_concrete_type, stubs_fn)
        cpp_module.setattr(name, scripted)
        script_module._modules[name] = scripted
    for name in dir(nn_module):
        if name in ignored_properties:
            continue
        item = getattr(nn_module, name, None)
        if inspect.ismethod(item) and _jit_internal.is_ignored_fn(item):
            unbound_function = getattr(nn_module, name).__func__
            bound_method = unbound_function.__get__(script_module)
            setattr(script_module, name, bound_method)
        elif concrete_type.is_ignored_attribute(name):
            setattr(script_module, name, item)
    script_module._concrete_type = concrete_type

def check_min_max_valid(min_val: torch.Tensor, max_val: torch.Tensor) -> bool:
    """Checks if the given minimum and maximum values are valid, meaning that
    they exist and the min value is less than the max value.
    """
    if <MASK>:
        warnings.warn('must run observer before calling calculate_qparams. ' + 'Returning default values.')
        return False
    if min_val.dim() == 0 or max_val.dim() == 0:
        if min_val == float('inf') and max_val == float('-inf'):
            warnings.warn('must run observer before calling calculate_qparams. ' + 'Returning default values.')
            return False
        assert min_val <= max_val, f'min {min_val} should be less than max {max_val}'
    else:
        assert torch.all(min_val <= max_val), f'min {min_val} should be less than max {max_val}'
    return True

def view(self, dtype=None, type=None):
    """
        Returns a view of the mrecarray.

        """
    if dtype is None:
        if <MASK>:
            output = np.ndarray.view(self)
        else:
            output = np.ndarray.view(self, type)
    elif type is None:
        try:
            if issubclass(dtype, np.ndarray):
                output = np.ndarray.view(self, dtype)
            else:
                output = np.ndarray.view(self, dtype)
        except TypeError:
            dtype = np.dtype(dtype)
            if dtype.fields is None:
                basetype = self.__class__.__bases__[0]
                output = self.__array__().view(dtype, basetype)
                output._update_from(self)
            else:
                output = np.ndarray.view(self, dtype)
            output._fill_value = None
    else:
        output = np.ndarray.view(self, dtype, type)
    if getattr(output, '_mask', ma.nomask) is not ma.nomask:
        mdtype = ma.make_mask_descr(output.dtype)
        output._mask = self._mask.view(mdtype, np.ndarray)
        output._mask.shape = output.shape
    return output

def _test_input_fn_iterator(self, task_type, task_id, num_gpus, input_fn, expected_values, test_reinitialize=True, ignore_order=False, use_devices_arg=False):
    (distribution, master_target) = self._get_test_object(task_type, task_id, num_gpus, use_devices_arg=use_devices_arg)
    devices = distribution.extended.worker_devices
    with ops.Graph().as_default(), self.cached_session(target=master_target) as sess:
        iterator = distribution.make_input_fn_iterator(input_fn)
        sess.run(iterator.initializer)
        for expected_value in expected_values:
            next_element = iterator.get_next()
            computed_value = sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
            if <MASK>:
                self.assertCountEqual(list(expected_value), list(computed_value))
            else:
                self.assertEqual(list(expected_value), list(computed_value))
        with self.assertRaises(errors.OutOfRangeError):
            next_element = iterator.get_next()
            sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
        if test_reinitialize:
            sess.run(iterator.initializer)
            for expected_value in expected_values:
                next_element = iterator.get_next()
                computed_value = sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
                if ignore_order:
                    self.assertCountEqual(list(expected_value), list(computed_value))
                else:
                    self.assertEqual(list(expected_value), list(computed_value))

