def maybe_free_unbacked_symbols(s: object) -> OrderedSet[Symbol]:
    if isinstance(s, (SymTypes, Expr)):
        return free_unbacked_symbols(s)
    elif <MASK>:
        r = OrderedSet[sympy.Symbol]()
        for t in s:
            r |= maybe_free_unbacked_symbols(t)
        return r
    elif isinstance(s, torch.Tensor):
        return free_unbacked_symbols(s)
    else:
        return OrderedSet()

def parse_expr(tokens, name, context=()):
    if isinstance(tokens[0], basestring_):
        return (tokens[0], tokens[1:])
    (expr, pos) = tokens[0]
    expr = expr.strip()
    if <MASK>:
        expr = expr[3:].lstrip(' \t')
        if expr.startswith(('\n', '\r')):
            expr = expr.lstrip('\r\n')
            if '\r' in expr:
                expr = expr.replace('\r\n', '\n')
                expr = expr.replace('\r', '')
            expr += '\n'
        elif '\n' in expr:
            raise TemplateError('Multi-line py blocks must start with a newline', position=pos, name=name)
        return (('py', pos, expr), tokens[1:])
    elif expr in ('continue', 'break'):
        if 'for' not in context:
            raise TemplateError('continue outside of for loop', position=pos, name=name)
        return ((expr, pos), tokens[1:])
    elif expr.startswith('if '):
        return parse_cond(tokens, name, context)
    elif expr.startswith('elif ') or expr == 'else':
        raise TemplateError('%s outside of an if block' % expr.split()[0], position=pos, name=name)
    elif expr in ('if', 'elif', 'for'):
        raise TemplateError('%s with no expression' % expr, position=pos, name=name)
    elif expr in ('endif', 'endfor', 'enddef'):
        raise TemplateError('Unexpected %s' % expr, position=pos, name=name)
    elif expr.startswith('for '):
        return parse_for(tokens, name, context)
    elif expr.startswith('default '):
        return parse_default(tokens, name, context)
    elif expr.startswith('inherit '):
        return parse_inherit(tokens, name, context)
    elif expr.startswith('def '):
        return parse_def(tokens, name, context)
    elif expr.startswith('#'):
        return (('comment', pos, tokens[0][0]), tokens[1:])
    return (('expr', pos, tokens[0][0]), tokens[1:])

def _generate(self, state):
    strict_params: dict[str, Union[float, int, ParameterAlias]] = {}
    for _ in range(1000):
        candidate_params: dict[str, Union[float, int, ParameterAlias]] = {}
        for p in self._parameters:
            if p.strict:
                if p.name in strict_params:
                    candidate_params[p.name] = strict_params[p.name]
                else:
                    candidate_params[p.name] = p.sample(state)
                    strict_params[p.name] = candidate_params[p.name]
            else:
                candidate_params[p.name] = p.sample(state)
        candidate_params = self._resolve_aliases(candidate_params)
        self._total_generated += 1
        if <MASK>:
            self._rejections += 1
            continue
        if not all((t.satisfies_constraints(candidate_params) for t in self._tensors)):
            self._rejections += 1
            continue
        return candidate_params
    raise ValueError('Failed to generate a set of valid parameters.')

@compatibility(is_backward_compatible=False)
def setattr_recursive(obj, attr, value):
    if <MASK>:
        setattr(obj, attr, value)
    else:
        layer = attr.split('.')
        setattr_recursive(getattr(obj, layer[0]), '.'.join(layer[1:]), value)

@_sharded_op_impl(torch.Tensor.requires_grad_)
def tensor_requires_grad_set(types, args=(), kwargs=None, pg=None):
    self_st = args[0]
    if not isinstance(self_st, ShardedTensor):
        raise TypeError('input needs to be a ShardedTensor')
    if kwargs is None:
        kwargs = {}
    requires_grad = args[1] if len(args) > 1 else kwargs.get('requires_grad', True)
    if <MASK>:
        return self_st
    for local_shard in self_st.local_shards():
        local_shard.tensor.requires_grad_(requires_grad)
    with torch._C.DisableTorchFunctionSubclass():
        self_st.requires_grad_(requires_grad)
    self_st._metadata.tensor_properties.requires_grad = requires_grad
    return self_st

