        for group in self.value.param_groups:
            for p in group['params']:
                mark_static_address(p, guard=True)
        self._set_capturable(tx)
    return super().var_getattr(tx, name)

@register_lowering(aten.mm, type_promotion_kind=None)
def tuned_mm(mat1, mat2, out_dtype=None, *, layout=None):
    """
    Lowering for autotuning aten.mm with different backends (Aten, Triton, CUTLASS, etc.)
    """
    if out_dtype is not None:
        input_dtype = mat1.get_dtype()
        torch._check(mat2.get_dtype() == input_dtype, lambda : 'input dtypes must be the same')
        torch._check(mat1.get_device().type == 'cuda', lambda : 'out_dtype is only supported for CUDA')
        torch._check(out_dtype == input_dtype or (out_dtype == torch.float32 and input_dtype in (torch.float16, torch.bfloat16)), lambda : 'out_dtype must be the same as input dtype or fp32 for fp16/bf16 inputs')
    if use_native_matmul(mat1, mat2):
        mat1 = lowerings[aten.unsqueeze](mat1, -1)
        mat2 = lowerings[aten.unsqueeze](mat2, 0)
        (args, kwargs) = transform_args(args=[mat1, mat2], kwargs={}, broadcast=True, type_promotion_kind=None, convert_input_to_bool=False)
        if inductor_config.triton.codegen_upcast_to_fp32 and mat1.dtype in [torch.float16, torch.bfloat16]:

            def _to_dtype(x):
                return ops.to_dtype(x, mat1.dtype, use_compute_types=False)
            args = [make_pointwise(_to_dtype)(x) for x in args]
        mul_pointwise = make_pointwise(ops.dot)(*args)
        dot_reduction = make_reduction('dot')(mul_pointwise, 1)
        return dot_reduction
    (m, n, k, layout, mat1, mat2) = mm_args(mat1, mat2, layout=layout, out_dtype=out_dtype)
    (static_shape, is_nonzero) = _is_static_problem(layout)
    name = 'mm'
    kernel_inputs = MMKernelInputs([mat1, mat2], out_dtype=out_dtype)
    counters['aten_mm_info'][f'aten.mm_{m}_{n}_{k}'] += 1
    log.info('Tuned aten.mm: m=%s, n=%s, k=%s, mat1_dtype=%s, mat2_dtype=%s, output_layout=%s', m, n, k, mat1.get_dtype(), mat2.get_dtype(), layout)
    choices: list[ChoiceCaller] = []
    (static_shape, is_nonzero) = _is_static_problem(layout)
    aten_handler: ExternKernelChoice = aten_mm
    aten_extra_kwargs: dict[str, Any] = {}
    if out_dtype is not None:
        aten_handler = aten_mm_dtype
        aten_extra_kwargs = {'out_dtype': out_dtype}
    templates_to_use: list[Union[ExternKernelChoice, KernelTemplate]] = []
    kwarg_overrides: dict[str, dict[str, Any]] = {}
    if <MASK>:
        templates_to_use.append(aten_handler)
        if aten_extra_kwargs:
            kwarg_overrides[aten_handler.uid] = aten_extra_kwargs
    if out_dtype is None and is_nonzero and use_triton_template(layout, check_max_autotune=True):
        if use_decompose_k_choice(m, n, k):
            templates_to_use.append(decompose_k_subgraph_template)
        is_exhaustive = inductor_config.max_autotune_gemm_search_space == 'exhaustive'
        if is_exhaustive or not use_decompose_k_choice(m, n, k, threshold_multiple=2):
            templates_to_use.append(mm_template)
            if use_triton_tma_template(mat1, mat2, output_layout=layout):
                templates_to_use.append(persistent_tma_mm_template)
            if use_triton_blackwell_tma_template(mat1, mat2, output_layout=layout):
                templates_to_use.append(blackwell_ws_persistent_device_tma_mm_template)
        templates_to_use.append(mm_contiguous_subgraph_template)
    choices.extend(V.choices.get_template_configs(kernel_inputs, templates_to_use, 'mm', kwarg_overrides=kwarg_overrides))
    if out_dtype is None and is_nonzero and use_cutlass_template(layout, m, n, k) and _use_cutlass_for_op('mm'):
        CUTLASS3xGemmTemplate.add_cutlass_gemm_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and is_nonzero and use_ck_gemm_template(layout, m, n, k):
        CKGemmTemplate.add_ck_gemm_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and is_nonzero and use_ck_tile_gemm_template(layout, m, n, k):
        CKTileGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and use_cpp_gemm_template(layout, mat1, mat2):
        CppGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    input_nodes = [mat1, mat2]
    if out_dtype is None and is_nonzero and use_triton_template(layout) and torch._inductor.config.run_autoheuristic(name) and is_triton(mat1):
        always_included = []
        if use_aten_gemm_kernels():
            always_included.append('extern_mm')
        num_choices_before_extra_configs = len(choices)
        choices.extend(V.choices.get_template_configs(kernel_inputs, [mm_template], 'mm-ah'))
        ah_choices = mm_autoheuristic(mat1, mat2, m, n, k, choices, name, input_nodes, mm_operations(), None, top_k=10, always_included=always_included)
        if not torch._inductor.config.collect_autoheuristic(name):
            if ah_choices is not None and len(ah_choices) > 0:
                choices = [choice for choice in choices if choice in ah_choices]
            else:
                choices = choices[:num_choices_before_extra_configs]
    if out_dtype is None:
        for k in inductor_config.external_matmul:
            choices.append(lazy_register_extern_choice(k).bind(kernel_inputs.nodes(), layout))
    best_config_future = None
    if out_dtype is None and torch._inductor.config.remote_gemm_autotune_cache:
        best_config_future = gen_best_config(mat1, mat2)
    return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout, best_config_future=best_config_future)

def __eq__(self, other):
    if <MASK>:
        return self.res == other.res and self.tensor_size == other.tensor_size and (self.index_tuple == other.index_tuple) and (self.input_var == other.input_var)
    else:
        return False

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    from . import ConstantVariable, UserMethodVariable
    method = self._maybe_get_baseclass_method(name)
    if method is not None:
        if method is object.__init__:
            return ConstantVariable.create(None)
        if is_standard_setattr(method) or isinstance(self.value, threading.local):
            return self.method_setattr_standard(tx, *args, **kwargs)
        if is_standard_delattr(method):
            return self.method_setattr_standard(tx, args[0], variables.DeletedVariable())
        if method is object.__eq__ and len(args) == 1 and (not kwargs):
            other = args[0]
            if not isinstance(other, UserDefinedObjectVariable):
                return variables.ConstantVariable.create(NotImplemented)
            return ConstantVariable.create(self.value is other.value)
        if torch._dynamo.config.enable_faithful_generator_behavior and isinstance(self.value, types.GeneratorType):
            unimplemented_v2(gb_type='call_method on generator', context=f'object={self.value}, method={name}, args={args}, kwargs={kwargs}', explanation='Detected a method call to a user-defined generator object. This is not fully supported.', hints=['Set `torch._dynamo.config.enable_faithful_generator_behavior = False`. Note that this may cause silent incorrectness, since we will eagerly unpack generators instead of lazily evaluating them.'])
        if <MASK>:
            source = self.source
            source_fn = None
            if source:
                source_fn = self.get_source_by_walking_mro(name)
            from ..mutation_guard import unpatched_nn_module_init
            if method is torch.nn.Module.__init__:
                method = unpatched_nn_module_init
            return UserMethodVariable(method, self, source_fn=source_fn, source=source).call_function(tx, args, kwargs)
        if method is list.__len__ and self.source and (not (args or kwargs)):
            install_guard(self.source.make_guard(GuardBuilder.SEQUENCE_LENGTH))
            return ConstantVariable(len(self.value))
    return super().call_method(tx, name, args, kwargs)

def _get_code(input_file):
    """Loads the ipynb file and returns a list of CodeLines."""
    raw_code = []
    with open(input_file) as in_file:
        notebook = json.load(in_file)
    cell_index = 0
    for cell in notebook['cells']:
        if <MASK>:
            cell_lines = cell['source']
            is_line_split = False
            for (line_idx, code_line) in enumerate(cell_lines):
                if skip_magic(code_line, ['%', '!', '?']) or is_line_split:
                    code_line = '###!!!' + code_line
                    is_line_split = check_line_split(code_line)
                if is_line_split:
                    is_line_split = check_line_split(code_line)
                if line_idx == len(cell_lines) - 1 and code_line.endswith('\n'):
                    code_line = code_line.replace('\n', '###===')
                raw_code.append(CodeLine(cell_index, code_line.rstrip().replace('\n', '###===')))
            cell_index += 1
    return (raw_code, notebook)

def gen_binary_op_func(python_op, inplace=False):
    src_lines = ['def f(lhs, rhs):']
    if 'torch' in python_op:
        src_lines.append(f'  return {python_op}(lhs, rhs)\n')
    elif <MASK>:
        src_lines.append(f'  lhs {python_op}= rhs\n  return lhs\n')
    else:
        src_lines.append(f'  return lhs {python_op} rhs\n')
    code_str = '\n'.join(src_lines)
    g = {'torch': torch}
    builtins.exec(code_str, g)
    return g['f']

def as_string(self):
    """Return a string of the file contents."""
    items = {'replaces_str': '', 'initial_str': '', 'run_before_str': '', 'atomic_str': ''}
    imports = set()
    operations = []
    for operation in self.migration.operations:
        (operation_string, operation_imports) = OperationWriter(operation).serialize()
        imports.update(operation_imports)
        operations.append(operation_string)
    items['operations'] = '\n'.join(operations) + '\n' if operations else ''
    dependencies = []
    for dependency in self.migration.dependencies:
        if dependency[0] == '__setting__':
            dependencies.append('        migrations.swappable_dependency(settings.%s),' % dependency[1])
            imports.add('from django.conf import settings')
        else:
            dependencies.append('        %s,' % self.serialize(dependency)[0])
    items['dependencies'] = '\n'.join(sorted(dependencies)) + '\n' if dependencies else ''
    migration_imports = set()
    for line in list(imports):
        if re.match('^import (.*)\\.\\d+[^\\s]*$', line):
            migration_imports.add(line.split('import')[1].strip())
            imports.remove(line)
            self.needs_manual_porting = True
    if 'from django.db import models' in imports:
        imports.discard('from django.db import models')
        imports.add('from django.db import migrations, models')
    else:
        imports.add('from django.db import migrations')
    sorted_imports = sorted(imports, key=lambda i: (i.split()[0] == 'from', i.split()[1]))
    items['imports'] = '\n'.join(sorted_imports) + '\n' if imports else ''
    if <MASK>:
        items['imports'] += '\n\n# Functions from the following migrations need manual copying.\n# Move them and any dependencies into this file, then update the\n# RunPython operations to refer to the local versions:\n# %s' % '\n# '.join(sorted(migration_imports))
    if self.migration.replaces:
        items['replaces_str'] = '\n    replaces = %s\n' % self.serialize(self.migration.replaces)[0]
    if self.migration.run_before:
        items['run_before_str'] = '\n    run_before = %s\n' % self.serialize(self.migration.run_before)[0]
    if self.include_header:
        items['migration_header'] = MIGRATION_HEADER_TEMPLATE % {'version': get_version(), 'timestamp': now().strftime('%Y-%m-%d %H:%M')}
    else:
        items['migration_header'] = ''
    if self.migration.initial:
        items['initial_str'] = '\n    initial = True\n'
    if not self.migration.atomic:
        items['atomic_str'] = '\n    atomic = False\n'
    return MIGRATION_TEMPLATE % items

