@register.tag
def get_admin_log(parser, token):
    """
    Populate a template variable with the admin log for the given criteria.

    Usage::

        {% get_admin_log [limit] as [varname] for_user [user_id_or_varname] %}

    Examples::

        {% get_admin_log 10 as admin_log for_user 23 %}
        {% get_admin_log 10 as admin_log for_user user %}
        {% get_admin_log 10 as admin_log %}

    Note that ``user_id_or_varname`` can be a hard-coded integer (user ID)
    or the name of a template context variable containing the user object
    whose ID you want.
    """
    tokens = token.contents.split()
    if len(tokens) < 4:
        raise template.TemplateSyntaxError("'get_admin_log' statements require two arguments")
    if not tokens[1].isdigit():
        raise template.TemplateSyntaxError("First argument to 'get_admin_log' must be an integer")
    if tokens[2] != 'as':
        raise template.TemplateSyntaxError("Second argument to 'get_admin_log' must be 'as'")
    if len(tokens) > 4:
        if <MASK>:
            raise template.TemplateSyntaxError("Fourth argument to 'get_admin_log' must be 'for_user'")
    return AdminLogNode(limit=tokens[1], varname=tokens[3], user=tokens[5] if len(tokens) > 5 else None)

def _groupby_op(self, *, how: str, has_dropped_na: bool, min_count: int, ngroups: int, ids: npt.NDArray[np.intp], **kwargs):
    dtype = self.dtype
    if dtype.kind == 'M':
        if how in ['sum', 'prod', 'cumsum', 'cumprod', 'var', 'skew', 'kurt']:
            raise TypeError(f"datetime64 type does not support operation '{how}'")
        if how in ['any', 'all']:
            raise TypeError(f"'{how}' with datetime64 dtypes is no longer supported. Use (obj != pd.Timestamp(0)).{how}() instead.")
    elif isinstance(dtype, PeriodDtype):
        if how in ['sum', 'prod', 'cumsum', 'cumprod', 'var', 'skew', 'kurt']:
            raise TypeError(f'Period type does not support {how} operations')
        if how in ['any', 'all']:
            raise TypeError(f"'{how}' with PeriodDtype is no longer supported. Use (obj != pd.Period(0, freq)).{how}() instead.")
    elif how in ['prod', 'cumprod', 'skew', 'kurt', 'var']:
        raise TypeError(f'timedelta64 type does not support {how} operations')
    npvalues = self._ndarray.view('M8[ns]')
    from pandas.core.groupby.ops import WrappedCythonOp
    kind = WrappedCythonOp.get_kind_from_how(how)
    op = WrappedCythonOp(how=how, kind=kind, has_dropped_na=has_dropped_na)
    res_values = op._cython_op_ndim_compat(npvalues, min_count=min_count, ngroups=ngroups, comp_ids=ids, mask=None, **kwargs)
    if op.how in op.cast_blocklist:
        return res_values
    assert res_values.dtype == 'M8[ns]'
    if how in ['std', 'sem']:
        from pandas.core.arrays import TimedeltaArray
        if <MASK>:
            raise TypeError("'std' and 'sem' are not valid for PeriodDtype")
        self = cast('DatetimeArray | TimedeltaArray', self)
        new_dtype = f'm8[{self.unit}]'
        res_values = res_values.view(new_dtype)
        return TimedeltaArray._simple_new(res_values, dtype=res_values.dtype)
    res_values = res_values.view(self._ndarray.dtype)
    return self._from_backing_data(res_values)

def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if ann is None:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if is_dict(ann):
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if value is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if ann is str:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if ann is Any:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if ann is torch.qscheme:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if <MASK>:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

@_onnx_symbolic('aten::native_layer_norm')
@symbolic_helper.quantized_args(True, False, False, False)
@symbolic_helper.parse_args('v', 'is', 'v', 'v', 'f')
def native_layer_norm(g: jit_utils.GraphContext, input: _C.Value, normalized_shape: Sequence[int], weight: _C.Value, bias: _C.Value, eps: float) -> tuple[_C.Value, _C.Value, _C.Value]:
    axes = [-i for i in range(len(normalized_shape), 0, -1)]
    two_cst = symbolic_helper._generate_wrapped_number(g, 2.0)
    eps_cst = symbolic_helper._generate_wrapped_number(g, eps)
    if <MASK>:
        mean = g.op('ReduceMean', input, axes_i=axes)
    else:
        mean = g.op('ReduceMean', input, g.op('Constant', value_t=torch.tensor(axes, dtype=torch.long)))
    numerator = sub(g, input, mean)
    is_type_half = _type_utils.JitScalarType.from_value(numerator) == _type_utils.JitScalarType.HALF
    if is_type_half:
        eps_dtype = _type_utils.JitScalarType.from_value(eps_cst)
        numerator = g.op('Cast', numerator, to_i=_type_utils.JitScalarType(eps_dtype).onnx_type())
    if g.opset < 18:
        variance = g.op('ReduceMean', pow(g, numerator, two_cst), axes_i=axes)
    else:
        variance = g.op('ReduceMean', pow(g, numerator, two_cst), g.op('Constant', value_t=torch.tensor(axes, dtype=torch.long)))
    denominator = sqrt(g, g.op('Add', variance, eps_cst))
    normalized = g.op('Div', numerator, denominator)
    if is_type_half:
        input_dtype = _type_utils.JitScalarType.from_value(input)
        normalized = g.op('Cast', normalized, to_i=_type_utils.JitScalarType(input_dtype).onnx_type())
    if not (weight is None or symbolic_helper._is_none(weight)):
        normalized = mul(g, normalized, weight)
    if not (bias is None or symbolic_helper._is_none(bias)):
        normalized = add(g, normalized, bias)
    if is_type_half:
        denominator = g.op('Cast', denominator, to_i=_type_utils.JitScalarType(input_dtype).onnx_type())
        rdenominator = g.op('Reciprocal', denominator)
    else:
        rdenominator = reciprocal(g, denominator)
    return (normalized, mean, rdenominator)

def __init__(self, dirs=None, app_dirs=False, context_processors=None, debug=False, loaders=None, string_if_invalid='', file_charset='utf-8', libraries=None, builtins=None, autoescape=True):
    if dirs is None:
        dirs = []
    if context_processors is None:
        context_processors = []
    if <MASK>:
        loaders = ['django.template.loaders.filesystem.Loader']
        if app_dirs:
            loaders += ['django.template.loaders.app_directories.Loader']
        loaders = [('django.template.loaders.cached.Loader', loaders)]
    elif app_dirs:
        raise ImproperlyConfigured('app_dirs must not be set when loaders is defined.')
    if libraries is None:
        libraries = {}
    if builtins is None:
        builtins = []
    self.dirs = dirs
    self.app_dirs = app_dirs
    self.autoescape = autoescape
    self.context_processors = context_processors
    self.debug = debug
    self.loaders = loaders
    self.string_if_invalid = string_if_invalid
    self.file_charset = file_charset
    self.libraries = libraries
    self.template_libraries = self.get_template_libraries(libraries)
    self.builtins = self.default_builtins + builtins
    self.template_builtins = self.get_template_builtins(self.builtins)

def set_command(self, key, value):
    if <MASK>:
        raise ValueError("unknown executable '%s' for class %s" % (key, self.__class__.__name__))
    if is_string(value):
        value = split_quoted(value)
    assert value is None or is_sequence_of_strings(value[1:]), (key, value)
    self.executables[key] = value

def get_matching_overload(node: torch.fx.Node, overloads: Sequence[_registration.OnnxDecompMeta]) -> tuple[Callable | None, str]:
    """Get the overload that matches the node's arguments.

    Args:
        node: The node to match.
        overloads: The OnnxDecompMeta with overloads and their signatures to match against.

    Returns:
        A tuple containing the matched overload and a string describing the reason for failure or success.
    """
    if not hasattr(node.target, '_schema'):
        return (overloads[0].onnx_function, 'The node target does not have a schema. Return the first one.')
    named_args = _get_named_fx_node_args(node)
    schema_args: dict[str, torch.Argument] = {arg.name: arg for arg in node.target._schema.arguments}
    failure_messages: list[str] = []
    for overload in overloads:
        assigned_types: dict[str, ir.TypeProtocol] = {}
        fail_reason = ''
        if overload.signature is None:
            return (overload.onnx_function, 'The overload does not have a signature. Assuming it is a custom op and matching it.')
        for param in overload.signature:
            if param.name not in schema_args and param.required:
                fail_reason = 'Required parameter not supplied'
                break
            if param.name in named_args:
                arg = named_args[param.name]
            elif param.name in schema_args and schema_args[param.name].has_default_value():
                arg = schema_args[param.name].default_value
            elif param.has_default():
                arg = param.default
            else:
                fail_reason = 'Parameter not provided'
                break
            if isinstance(param, _schemas.Parameter):
                if <MASK>:
                    arg = _get_type_from_tensor(arg)
                if isinstance(arg, (list, tuple)) and any((isinstance(t, torch.fx.Node) for t in arg)):
                    first_tensor = _get_first_tensor_in_node_list(arg)
                    assert first_tensor is not None
                    arg = ir.SequenceType(_get_type_from_tensor(first_tensor))
                elif isinstance(arg, torch.fx.Node):
                    meta_val = arg.meta['val']
                    arg = _get_type_from_tensor(meta_val)
                if not _param_type_compatible_with_arg(param, arg, assigned_types):
                    fail_reason = f'Parameter type not compatible with argument: param=`{param}`, assigned_types=`{assigned_types}`, arg=`{arg}`'
                    break
            elif isinstance(param, _schemas.AttributeParameter):
                if not _attribute_type_compatible_with_arg(param, arg):
                    fail_reason = f'Attribute type not compatible with argument: param=`{param}`, arg=`{arg}`'
                    break
            else:
                raise TypeError(f'Unknown parameter type: {type(param)}')
        if not fail_reason:
            return (overload.onnx_function, 'Successfully matched overload')
        else:
            failure_messages.append(f'- Failed to match overload `{overload}`: {fail_reason}')
    return (None, f'All overloads did not match the node `{node.format_node()}`.\n' + '\n'.join(failure_messages))

def find_info(f: NativeFunction) -> tuple[dict[str, DifferentiabilityInfo] | None, bool]:
    if 'generated' in f.tags and f.func.kind() == SchemaKind.out:
        return (None, False)
    if f.func in differentiability_infos:
        return (differentiability_infos[f.func], True)
    f_sig = f.func.signature(strip_default=True)
    if f_sig in functional_info_by_signature and (not is_foreach_func(f)):
        return (functional_info_by_signature[f_sig], False)
    if 'generated' in f.tags and f_sig in non_functional_info_by_signature:
        info_dict = non_functional_info_by_signature[f_sig]
        assert not any((any(('self' in str(input.nctype.name) for input in info.all_saved_inputs)) for info in info_dict.values())), f'''Attempted to convert a derivative formula for a mutable operator\n to be used by automatically by its functional variant ("{str(f.func)}").\n this is not currently supported (we'd need to fix up the formula in the codegen).'''
        return (info_dict, False)
    if is_foreach_func(f):
        assert f.func not in differentiability_infos
        (diff_info, is_generated) = gen_foreach_derivativeinfo(f, functional_info_by_signature, non_functional_info_by_signature)
        if diff_info is None:
            return (None, False)
        diff_info_dict = {'Default': diff_info}
        if <MASK>:
            differentiability_infos[f.func] = diff_info_dict
            functional_info_by_signature[f.func] = diff_info_dict
        return (diff_info_dict, is_generated)
    return (None, False)

def _mean_shift_single_seed(my_mean, X, nbrs, max_iter):
    bandwidth = nbrs.get_params()['radius']
    stop_thresh = 0.001 * bandwidth
    completed_iterations = 0
    while True:
        i_nbrs = nbrs.radius_neighbors([my_mean], bandwidth, return_distance=False)[0]
        points_within = X[i_nbrs]
        if <MASK>:
            break
        my_old_mean = my_mean
        my_mean = np.mean(points_within, axis=0)
        if np.linalg.norm(my_mean - my_old_mean) <= stop_thresh or completed_iterations == max_iter:
            break
        completed_iterations += 1
    return (tuple(my_mean), len(points_within), completed_iterations)

def test_concrete_function_editing_via_mlir_pass_tfg_dialect(self):
