def _is_named_tuple(instance):
    """Returns True iff `instance` is a `namedtuple`.

  Args:
    instance: An instance of a Python object.

  Returns:
    True if `instance` is a `namedtuple`.
  """
    if <MASK>:
        return False
    return hasattr(instance, '_fields') and isinstance(instance._fields, collections_abc.Sequence) and all((isinstance(f, str) for f in instance._fields))

def _check_ignored_states(ignored_states: list[Any], passed_as_ignored_states: bool) -> None:
    """
    Check that the ignored states are uniformly parameters or uniformly modules.

    We may remove this check in the future if we permit mixing.
    """
    if len(ignored_states) == 0:
        return
    if passed_as_ignored_states:
        all_params = all((isinstance(state, nn.Parameter) for state in ignored_states))
        all_modules = all((isinstance(state, nn.Module) for state in ignored_states))
        if <MASK>:
            sorted_types = sorted({type(state) for state in ignored_states}, key=repr)
            raise ValueError(f'ignored_states expects all nn.Parameter or all nn.Module list elements but got types {sorted_types}')
    elif not all((isinstance(state, nn.Module) for state in ignored_states)):
        sorted_types = sorted({type(state) for state in ignored_states}, key=repr)
        raise ValueError(f'ignored_modules expects nn.Module list elements but got types {sorted_types}')

def get_variable_cls(self, user_cls: type) -> type:
    from torch.overrides import TorchFunctionMode
    from .variables.ctx_manager import GenericContextWrappingVariable
    from .variables.torch_function import TorchFunctionModeVariable
    from .variables.user_defined import is_forbidden_context_manager
    variable_cls: type[variables.UserDefinedObjectVariable] = variables.UserDefinedObjectVariable
    if issubclass(user_cls, TorchFunctionMode) and TorchFunctionModeVariable.is_supported_torch_function_mode(user_cls):
        variable_cls = TorchFunctionModeVariable
    elif hasattr(user_cls, '__enter__') and hasattr(user_cls, '__exit__') and (not is_forbidden_context_manager(user_cls)):
        variable_cls = GenericContextWrappingVariable
    elif issubclass(user_cls, torch.nn.Module):
        variable_cls = variables.UnspecializedNNModuleVariable
    elif <MASK>:
        variable_cls = variables.UserDefinedDictVariable
    elif issubclass(user_cls, (set, frozenset)):
        variable_cls = variables.UserDefinedSetVariable
    elif issubclass(user_cls, tuple):
        variable_cls = variables.UserDefinedTupleVariable
    elif issubclass(user_cls, list):
        variable_cls = variables.UserDefinedListVariable
    elif issubclass(user_cls, MutableMapping):
        variable_cls = variables.MutableMappingVariable
    elif is_frozen_dataclass(user_cls):
        variable_cls = FrozenDataClassVariable
    elif issubclass(user_cls, BaseException):
        variable_cls = variables.UserDefinedExceptionObjectVariable
    assert issubclass(variable_cls, variables.UserDefinedObjectVariable)
    return variable_cls

@torch.no_grad()
def _init_sharded_param(self, param: nn.Parameter, device: torch.device, shard_placement_fn: Optional[Callable]):
    if param.device != device and param.device.type != 'meta':
        raise AssertionError(f'Expects the parameter to already be moved to device {device} but got {param.device}')
    if not param.is_contiguous():
        raise NotImplementedError(f'FSDP does not support non-contiguous parameters yet: param.shape={param.shape!r} param.stride()={param.stride()!r}')
    fsdp_placement = shard_placement_fn(param) if shard_placement_fn else None
    if fsdp_placement is None:
        fsdp_placement = Shard(0)
    elif fsdp_placement.dim < 0:
        fsdp_placement = Shard(fsdp_placement.dim + param.ndim)
    if not isinstance(fsdp_placement, Shard):
        raise AssertionError(f'Expected Shard, got {type(fsdp_placement)}: {fsdp_placement}')
    self.fsdp_placement = fsdp_placement
    shard_dim = fsdp_placement.dim
    self.is_dtensor = isinstance(param, DTensor)
    if self.is_dtensor:
        self._tp_spec = cast(DTensor, param)._spec
        (dp_mesh, tp_mesh) = (self.mesh_info.mesh, self._tp_spec.mesh)
        dp_global_mesh = dp_mesh._get_root_mesh() if dp_mesh is not None else None
        tp_global_mesh = tp_mesh._get_root_mesh() if tp_mesh is not None else None
        if dp_global_mesh != tp_global_mesh or (dp_global_mesh is None or tp_global_mesh is None):
            raise AssertionError(f"FSDP requires the DP and model parallel TP/EP mesh to have the same parent mesh but got: \nDP's global mesh: {dp_global_mesh}\nTP/EP's global mesh: {tp_global_mesh}")
        name_dims_error = 'FSDP requires named DeviceMesh dims for ND parallelism'
        if dp_mesh.mesh_dim_names is None:
            raise AssertionError(name_dims_error)
        if tp_mesh.mesh_dim_names is None:
            raise AssertionError(name_dims_error)
        submesh_names = dp_mesh.mesh_dim_names + tp_mesh.mesh_dim_names
        self._spmd_mesh = dp_global_mesh[submesh_names]
        if len(self._tp_spec.placements) > 2:
            raise NotImplementedError(f'FSDP only supports 1D TP/EP or 2D EP+TP, not {self._tp_spec.placements}')
        split_factor = self._tp_spec.num_shards_map[shard_dim]
        if not 2 <= self._spmd_mesh.ndim <= 4:
            raise AssertionError(f'_spmd_mesh.ndim can only be 2 (FSDP+TP/EP), 3 (FSDP+EP+TP, HSDP+TP/EP), or 4 (HSDP+EP+TP) but got {self._spmd_mesh.ndim}.')
        self._spmd_placements: tuple[Placement, ...]
        dp_shard_tp_placement = (_StridedShard(shard_dim, split_factor=split_factor) if split_factor > 1 else fsdp_placement, *self._tp_spec.placements)
        if dp_mesh.ndim == 1:
            self._spmd_placements = dp_shard_tp_placement
        else:
            if self.mesh_info.replicate_mesh_dim != 0:
                raise AssertionError(f'Expected replicate_mesh_dim to be 0, got {self.mesh_info.replicate_mesh_dim}')
            self._spmd_placements = (Replicate(),) + dp_shard_tp_placement
        self._sharding_spec = DTensorSpec(self._spmd_mesh, self._spmd_placements, tensor_meta=self._tp_spec.tensor_meta)
        param_data = cast(DTensor, param)._local_tensor
    else:
        self._spmd_mesh = self.mesh_info.mesh
        if isinstance(self.mesh_info, HSDPMeshInfo):
            self._spmd_placements = (Replicate(), fsdp_placement)
        else:
            self._spmd_placements = (fsdp_placement,)
        self._sharding_spec = DTensorSpec(self._spmd_mesh, self._spmd_placements, tensor_meta=TensorMeta(param.size(), param.stride(), param.dtype))
        param_data = param
    if not param_data.is_contiguous():
        raise AssertionError(f'Expected contiguous tensor, got param_data.shape={param_data.shape!r} param_data.stride()={param_data.stride()!r}')
    shard_dim = fsdp_placement.dim
    if shard_dim >= param_data.ndim:
        raise AssertionError(f'Shard dim {shard_dim} is invalid for {param_data.ndim}D tensor: {param.shape}')
    self._orig_size = param_data.size()
    self._contiguous_orig_stride = make_contiguous_strides_for(self._orig_size)
    shard_rank = self.mesh_info.shard_mesh_rank
    shard_world_size = self.mesh_info.shard_mesh_size
    if shard_dim > 0 and param_data.size(shard_dim) % shard_world_size != 0:
        raise NotImplementedError(f'FSDP does not support uneven sharding on dim {shard_dim}: {param_data.size()} (world size: {shard_world_size})')
    chunks = _chunk_with_empty(param_data, shard_world_size, dim=shard_dim)
    sharded_param = chunks[shard_rank]
    self.sharded_size = _get_dim_chunked_size(sharded_param, param_data.size(), dim=shard_dim)
    self.contiguous_sharded_stride = make_contiguous_strides_for(self.sharded_size)
    padded_sharded_size = chunks[0].size()
    self.padded_sharded_param_size = padded_sharded_size
    padded_sharded_param = param_data.new_zeros(padded_sharded_size)
    if <MASK>:
        padded_sharded_param.narrow(dim=shard_dim, start=0, length=sharded_param.size(shard_dim)).copy_(sharded_param)
    if self.offload_to_cpu and (not padded_sharded_param.is_meta):
        padded_sharded_param = padded_sharded_param.cpu()
        if self.pin_memory:
            padded_sharded_param = padded_sharded_param.pin_memory()
    self._sharded_param_data = padded_sharded_param.view(-1)
    length = sharded_param.size(shard_dim) if sharded_param.numel() > 0 else 0
    sharded_param = padded_sharded_param.narrow(dim=shard_dim, start=0, length=length)
    if not sharded_param.is_contiguous():
        raise AssertionError(f'Expected contiguous tensor with self.fsdp_placement={self.fsdp_placement!r}')
    self.sharded_param = nn.Parameter(self.to_sharded_dtensor(sharded_param))
    self.sharded_param.requires_grad_(param.requires_grad)
    self._setattr_on_modules(self.sharded_param)
    self.sharded_state = ShardedState.SHARDED

def suffix_product(a: IntTuple, init: IntTuple=1) -> IntTuple:
    if is_tuple(a):
        if <MASK>:
            assert len(a) == len(init)
            return tuple((suffix_product(x, i) for (x, i) in zip(a, init)))
        else:
            r = []
            for i in range(len(a) - 1, -1, -1):
                r.append(suffix_product(a[i], init))
                init = init * product(a[i])
            r.reverse()
            return tuple(r)
    elif is_tuple(init):
        raise AssertionError('Invalid combination: int with tuple init')
    else:
        return init

def wrap_module(self, value: torch.nn.Module):
    from ..eval_frame import OptimizedModule
    if len(value.__dict__) == 0:
        unimplemented_v2(gb_type='Uninitialized nn.Module', context=typestr(value), explanation=f'Attempted to trace an uninitialized nn.Module of type {typestr(value)}.', hints=[*graph_break_hints.USER_ERROR, 'Ensure your nn.Module instance has called `super().__init__()`.'])
    if istype(value, OptimizedModule):
        if inspect.getattr_static(value.forward, '_torchdynamo_disable', False):
            msg = inspect.getattr_static(value.forward, '_torchdynamo_disable_msg', None)
            return DelayGraphBreakVariable(source=self.source, msg=f'Optimized `nn.Module` is wrapped with `torch.compiler.disable` (reason: {msg})')
        self.install_guards(GuardBuilder.TYPE_MATCH)
        self.source = AttrSource(self.source, '_orig_mod')
        return self.wrap_module(value._orig_mod)
    if isinstance(value, (torch.nn.RNN, torch.nn.GRU, torch.nn.LSTM)) and (not config.allow_rnn):
        unimplemented_v2(gb_type='Attempted to wrap RNN, GRU, or LSTM', context=str(value), explanation='Dynamo does not support RNN, GRU, or LSTM.', hints=[*graph_break_hints.SUPPORTABLE])
    if getattr(value, '_is_fsdp_managed_module', False):
        if not getattr(value, '_fsdp_use_orig_params', False):
            unimplemented_v2(gb_type='FSDP with use_orig_params=False', context='', explanation='Dynamo only supports FSDP with use_orig_params=True', hints=[])
        self.install_guards(GuardBuilder.TYPE_MATCH)
        result = FSDPManagedNNModuleVariable(value, source=self.get_source())
        if not SideEffects.cls_supports_mutation_side_effects(type(value)):
            return result
        return self.tx.output.side_effects.track_object_existing(value, result)
    elif mutation_guard.is_dynamic_nn_module(value, self.tx.export):
        if isinstance(value, torch.fx.experimental.proxy_tensor._AttrProxy):
            value = value.get_base()
            self.source = AttrProxySource(self.source)
        if torch._dynamo.config.inline_inbuilt_nn_modules:
            freezing = is_parameter_freezing()
            if callable(value.named_parameters) and value.named_parameters.__func__ is og_module_named_parameters_fn_ptr:
                try:
                    for (_, p) in value.named_parameters():
                        self.mark_static_input(p, guard=freezing)
                except TypeError as e:
                    raise_observed_exception(type(e), self.tx, args=list(e.args))
            if callable(value.named_buffers) and value.named_buffers.__func__ is og_module_named_buffers_fn_ptr:
                try:
                    for (_, b) in value.named_buffers():
                        self.mark_static_input(b, guard=freezing)
                except TypeError as e:
                    raise_observed_exception(type(e), self.tx, args=list(e.args))
            if freezing:
                self.tx.output.nn_modules[self.name] = value
        if value.__module__.startswith(('torch.nn.modules', 'torch.ao.')) and (not value.__module__.startswith('torch.nn.modules.container')) or getattr(value.__class__, '_dynamo_marked_static', False):
            new_source = self.source
            if config.inline_inbuilt_nn_modules and (not self.tx.output.export or config.install_free_tensors):
                new_source = UnspecializedBuiltinNNModuleSource(self.source)
            result = UnspecializedBuiltinNNModuleVariable(value, source=new_source)
            install_guard(new_source.make_guard(GuardBuilder.TYPE_MATCH))
        else:
            new_source = self.source
            if config.inline_inbuilt_nn_modules and (not self.tx.output.export or config.install_free_tensors):
                new_source = UnspecializedNNModuleSource(self.source)
            result = UnspecializedNNModuleVariable(value, source=new_source)
            install_guard(new_source.make_guard(GuardBuilder.TYPE_MATCH))
        self.tx.output.add_fqn_info_for_inlined_modules(value, self.source)
        if not SideEffects.cls_supports_mutation_side_effects(type(value)):
            return result
        return self.tx.output.side_effects.track_object_existing(value, result)
    elif <MASK>:
        self.install_guards(GuardBuilder.TYPE_MATCH)
        return UnspecializedNNModuleVariable(value, source=self.get_source())
    else:
        return self.tx.output.register_attr_or_module(value, self.name, source=self.get_source())

def _interpret_code(self, code, ns, out, defs):
    __traceback_hide__ = True
    (name, pos) = (code[0], code[1])
    if name == 'py':
        self._exec(code[2], ns, pos)
    elif name == 'continue':
        raise _TemplateContinue()
    elif name == 'break':
        raise _TemplateBreak()
    elif name == 'for':
        (vars, expr, content) = (code[2], code[3], code[4])
        expr = self._eval(expr, ns, pos)
        self._interpret_for(vars, expr, content, ns, out, defs)
    elif name == 'cond':
        parts = code[2:]
        self._interpret_if(parts, ns, out, defs)
    elif name == 'expr':
        parts = code[2].split('|')
        base = self._eval(parts[0], ns, pos)
        for part in parts[1:]:
            func = self._eval(part, ns, pos)
            base = func(base)
        out.append(self._repr(base, pos))
    elif name == 'default':
        (var, expr) = (code[2], code[3])
        if var not in ns:
            result = self._eval(expr, ns, pos)
            ns[var] = result
    elif <MASK>:
        expr = code[2]
        value = self._eval(expr, ns, pos)
        defs['__inherit__'] = value
    elif name == 'def':
        name = code[2]
        signature = code[3]
        parts = code[4]
        ns[name] = defs[name] = TemplateDef(self, name, signature, body=parts, ns=ns, pos=pos)
    elif name == 'comment':
        return
    else:
        assert 0, 'Unknown code: %r' % name

def _update_snap(self, u_type: _UpdateType, winfo: _WeakRefInfo, old_mem_consumed: Optional[int]=None, old_reftype: Optional[_RefType]=None) -> None:
    maybe_zero = False
    dev_snap = self._curr_mem_snap.setdefault(winfo.device, dict.fromkeys(self._ref_class, 0))
    dev_snap.setdefault(_TOTAL_KEY, 0)
    if u_type == _UpdateType.ADD:
        dev_snap[winfo.reftype] += winfo.mem_consumed
        dev_snap[_TOTAL_KEY] += winfo.mem_consumed
    elif u_type == _UpdateType.DEL:
        dev_snap[winfo.reftype] -= winfo.mem_consumed
        dev_snap[_TOTAL_KEY] -= winfo.mem_consumed
        maybe_zero = True
    elif u_type == _UpdateType.REF:
        assert old_reftype is not None
        dev_snap[old_reftype] -= winfo.mem_consumed
        dev_snap[winfo.reftype] += winfo.mem_consumed
    elif u_type == _UpdateType.SIZE:
        assert old_mem_consumed is not None
        change = winfo.mem_consumed - old_mem_consumed
        dev_snap[winfo.reftype] += change
        dev_snap[_TOTAL_KEY] += change
        maybe_zero = True
    else:
        raise ValueError(f'Invalid update type: {u_type}')
    if maybe_zero:
        if <MASK>:
            del self._curr_mem_snap[winfo.device]

def post_compile(self, compiled_fn, _aot_config, *, runtime_metadata: ViewAndMutationMeta):
    num_tokens = len(runtime_metadata.tokens)

    @wraps(compiled_fn)
    def inner_fn(args: list[Any]):
        if num_tokens > 0:
            old_args = args
            args = [*[None] * num_tokens, *args]
            old_args.clear()
        outs = compiled_fn(args)
        if <MASK>:
            return None
        return outs[num_tokens:] if num_tokens != 0 else outs
    inner_fn._boxed_call = True
    return inner_fn

def process_rhs_params(self):
    if self.rhs_params:
        if len(self.rhs_params) == (2 if self.lookup_name == 'relate' else 1):
            self.process_band_indices()
        elif <MASK>:
            raise ValueError('Tuple too long for lookup %s.' % self.lookup_name)
    elif isinstance(self.lhs, RasterBandTransform):
        self.process_band_indices(only_lhs=True)

def get_arch_list() -> list[str]:
    """Return list CUDA architectures this library was compiled for."""
    if <MASK>:
        return []
    arch_flags = torch._C._cuda_getArchFlags()
    if arch_flags is None:
        return []
    return arch_flags.split()

@combinations.generate(combinations.combine(tf_api_version=2, mode=['eager'], distribution=[strategy_combinations.mirrored_strategy_with_gpu_and_cpu, strategy_combinations.central_storage_strategy_with_gpu_and_cpu, strategy_combinations.multi_worker_mirrored_2x1_cpu, strategy_combinations.multi_worker_mirrored_2x1_gpu, strategy_combinations.multi_worker_mirrored_2x2_gpu], input_type=['dataset', 'input_fn'], drop_remainder=[False, True]))
def testRaggedSparseGetNextAsOptionalInLoop(self, distribution, input_type, drop_remainder):
    """Test with `RaggedTensor`s and `SparseTensor`s."""
    global_batch_size = 8

    def dataset_fn(ctx=None):
        ctx = ctx or distribute_lib.InputContext()
        batch_size = ctx.get_per_replica_batch_size(global_batch_size)
        row_lengths = np.mod(np.arange(20), 4).astype(np.int64)
        ragged_tensor = ragged_tensor_lib.RaggedTensor.from_row_lengths(np.repeat(np.arange(20, dtype=np.float32), row_lengths), row_lengths)
        dataset = dataset_ops.DatasetV2.from_tensor_slices({'dense': ragged_tensor.to_tensor(), 'ragged': ragged_tensor, 'sparse': ragged_tensor.to_sparse()})
        dataset = dataset.batch(batch_size, drop_remainder=drop_remainder)
        return dataset.shard(ctx.num_input_pipelines, ctx.input_pipeline_id)
    if input_type == 'dataset':
        ds = distribution.experimental_distribute_dataset(dataset_fn(distribute_lib.InputContext()))
    else:
        ds = distribution.distribute_datasets_from_function(dataset_fn)

    def sum_batch(per_replica_features):
        """Sums the `PerReplica` values in the `per_replica_features` map."""

        def map_fn(per_replica_values):

            def _sum(value):
                if sparse_tensor.is_sparse(value):
                    return math_ops.reduce_sum(value.values)
                else:
                    return math_ops.reduce_sum(value)
            per_replica_sums = distribution.run(_sum, args=(per_replica_values,))
            return distribution.reduce(reduce_util.ReduceOp.SUM, per_replica_sums, axis=None)
        return nest.map_structure(map_fn, per_replica_features)

    def _reduce(state, batch):
        sums = sum_batch(batch)
        return {name: value + sums[name] for (name, value) in state.items()}

    def sum_while_loop(ds):
        iterator = iter(ds)
        sums = {'dense': 0.0, 'ragged': 0.0, 'sparse': 0.0}
        try_next = constant_op.constant(True)
        while try_next:
            opt_iterate = iterator.get_next_as_optional()
            if opt_iterate.has_value():
                sums = _reduce(sums, opt_iterate.get_value())
            else:
                try_next = False
        return sums
    sums = def_function.function(sum_while_loop)(ds)
    expected_for_sum = 200.0
    if <MASK>:
        expected_for_sum = 310.0
    self.assertAllEqual(nest.flatten(sums), [expected_for_sum] * 3)

def __call__(self, ctx: _RendezvousContext, deadline: float) -> _Action:
    state = ctx.state
    if state.closed:
        if ctx.node in state.redundancy_list:
            msg = f"The rendezvous '{ctx.settings.run_id}' is closed, terminating pending rendezvous."
            raise RendezvousGracefulExitError(msg)
        return _Action.ERROR_CLOSED
    if ctx.node in state.redundancy_list:
        msg = f'The node {ctx.node} is in redundancy list'
        logger.debug(msg)
        if len(state.participants) == ctx.settings.max_nodes:
            if _should_keep_alive(ctx):
                return _Action.KEEP_ALIVE
            else:
                return _Action.SYNC
        else:
            msg = f'The node {ctx.node} is removed from redundancy list'
            logger.debug(msg)
            return _Action.REMOVE_FROM_REDUNDANCY_LIST
    is_participant = ctx.node in state.participants
    if state.complete and is_participant:
        return _Action.FINISH
    now = time.monotonic()
    if now > deadline:
        rollback_period = 5
        if now <= deadline + rollback_period:
            if <MASK>:
                return _Action.REMOVE_FROM_PARTICIPANTS
            if ctx.node in state.wait_list:
                return _Action.REMOVE_FROM_WAIT_LIST
        return _Action.ERROR_TIMEOUT
    if state.complete:
        if len(state.participants) < ctx.settings.max_nodes:
            if ctx.node not in state.wait_list:
                return _Action.ADD_TO_WAIT_LIST
        elif len(state.participants) >= ctx.settings.max_nodes:
            if ctx.node not in state.redundancy_list and ctx.node not in state.wait_list:
                return _Action.ADD_TO_REDUNDANCY_LIST
    elif is_participant:
        if len(state.participants) >= ctx.settings.min_nodes and len(state.participants) <= ctx.settings.max_nodes and (state.deadline is not None):
            if state.deadline < datetime.now(timezone.utc):
                msg = f"The node '{ctx.node}' marking the rendezvous complete, quorum established within deadline"
                logger.debug(msg)
                return _Action.MARK_RENDEZVOUS_COMPLETE
            else:
                msg = f"The node '{ctx.node}' can't complete rendezvous: deadline reached"
                logger.debug(msg)
        else:
            msg = f"The node '{ctx.node}' can't complete rendezvous: not enough participants"
            logger.debug(msg)
    else:
        return _Action.ADD_TO_PARTICIPANTS
    if _should_keep_alive(ctx):
        return _Action.KEEP_ALIVE
    return _Action.SYNC

def __init__(self, expression, partition_by=None, order_by=None, frame=None, output_field=None):
    self.partition_by = partition_by
    self.order_by = order_by
    self.frame = frame
    if not getattr(expression, 'window_compatible', False):
        raise ValueError("Expression '%s' isn't compatible with OVER clauses." % expression.__class__.__name__)
    if self.partition_by is not None:
        if <MASK>:
            self.partition_by = (self.partition_by,)
        self.partition_by = ExpressionList(*self.partition_by)
    self.order_by = OrderByList.from_param('Window.order_by', self.order_by)
    super().__init__(output_field=output_field)
    self.source_expression = self._parse_expressions(expression)[0]

def with_perm(self, perm, is_active=True, include_superusers=True, backend=None, obj=None):
    if backend is None:
        backends = auth.get_backends()
        if len(backends) == 1:
            backend = backends[0]
        else:
            raise ValueError('You have multiple authentication backends configured and therefore must provide the `backend` argument.')
    elif <MASK>:
        raise TypeError('backend must be a dotted import path string (got %r).' % backend)
    else:
        backend = auth.load_backend(backend)
    if hasattr(backend, 'with_perm'):
        return backend.with_perm(perm, is_active=is_active, include_superusers=include_superusers, obj=obj)
    return self.none()

def _build_tensor_data(self):
    """Caches the tensor data for all Placeholders in the given function."""
    map_index_to_variable = {}
    for var in self._func.graph.variables:
        for (idx, captured_input) in enumerate(self._func.captured_inputs):
            if var.handle is captured_input:
                map_index_to_variable[idx] = var
                break
    for (idx, (val_tensor, name_tensor)) in enumerate(self._func.graph.captures):
        tensor_name = name_tensor.name.split(':')[0]
        if <MASK>:
            continue
        if idx in map_index_to_variable:
            data = self._eval(map_index_to_variable[idx])
        else:
            if val_tensor.dtype == dtypes.resource:
                logging.vlog(1, 'Skip converting resource tensor %s' % tensor_name)
                continue
            data = np.array(self._eval(val_tensor))
        self._tensor_data[tensor_name] = _TensorData(numpy=data, dtype=dtypes.as_dtype(data.dtype).as_datatype_enum, index=idx)
    for node in self.node_defs.values():
        if node.op == 'VariableV2':
            if not self._should_convert(node.name):
                continue
            if node.name not in self.tensor_data:
                with self._func.graph.as_default():
                    identity_node = array_ops.identity(self._func.graph.as_graph_element(node.name + ':0'))
                pruned_graph = self._func.prune([], [identity_node.name])()[0]
                self._tensor_data[node.name] = _TensorData(numpy=pruned_graph.numpy(), dtype=node.attr['dtype'].type, index=None)

def convert_to_absolute_paths_inplace(paths):
    if <MASK>:
        for i in range(len(paths)):
            if not os.path.isabs(paths[i]):
                paths[i] = os.path.abspath(paths[i])

def _to_placeholder(self):
    ragged_spec = self.type_spec
    if ragged_spec.ragged_rank == 0 or ragged_spec.shape.rank is None:
        return super(RaggedKerasTensor, self)._to_placeholder()
    flat_shape = ragged_spec.shape[ragged_spec.ragged_rank:]
    result = array_ops.placeholder(ragged_spec.dtype, flat_shape)
    known_num_splits = []
    prod = 1
    for axis_size in ragged_spec.shape:
        if prod is not None:
            if axis_size is None or getattr(axis_size, 'value', True) is None:
                prod = None
            else:
                prod = prod * axis_size
        known_num_splits.append(prod)
    for axis in range(ragged_spec.ragged_rank, 0, -1):
        axis_size = ragged_spec.shape[axis]
        if axis_size is None or getattr(axis_size, 'value', True) is None:
            num_splits = known_num_splits[axis - 1]
            if <MASK>:
                num_splits = num_splits + 1
            splits = array_ops.placeholder(ragged_spec.row_splits_dtype, [num_splits])
            result = ragged_tensor.RaggedTensor.from_row_splits(result, splits, validate=False)
        else:
            rowlen = constant_op.constant(axis_size, ragged_spec.row_splits_dtype)
            result = ragged_tensor.RaggedTensor.from_uniform_row_length(result, rowlen, validate=False)
    return result

def _rekey_sharded_optim_state_dict(sharded_osd: dict[str, Any], model: nn.Module, optim: torch.optim.Optimizer, optim_input: Optional[Union[list[dict[str, Any]], Iterable[nn.Parameter]]], using_optim_input: bool, is_named_optimizer: bool=False) -> dict[str, Any]:
    """
    Rekeys the optimizer state dict from unflattened parameter names to flat
    parameter IDs according to the calling rank's ``optim``, which may be
    different across ranks. In particular, the unflattened parameter names are
    represented as :class:`_OptimStateKey` s.
    """
    param_to_fqns = _get_param_to_fqns(model)
    flat_param_to_fqn = _get_flat_param_to_fqn(model)
    param_to_param_key: dict[nn.Parameter, Union[int, str]] = cast(dict[nn.Parameter, Union[int, str]], _get_param_to_param_id_from_optim_input(model, optim_input) if using_optim_input else _get_param_to_param_key(optim, model, is_named_optimizer, param_to_fqns, flat_param_to_fqn))
    if <MASK>:
        raise AssertionError(f'Expected len(param_to_param_key) <= len(param_to_fqns), got {len(param_to_param_key)} > {len(param_to_fqns)}')
    unflat_param_names_to_flat_param_key: dict[tuple[str, ...], Union[int, str]] = {}
    unflat_param_name_to_flat_param_key: dict[str, Union[int, str]] = {}
    for (param, unflat_param_names) in param_to_fqns.items():
        if param not in param_to_param_key:
            continue
        flat_param_key = param_to_param_key[param]
        unflat_param_names_to_flat_param_key[tuple(unflat_param_names)] = flat_param_key
        for unflat_param_name in unflat_param_names:
            unflat_param_name_to_flat_param_key[unflat_param_name] = flat_param_key
    sharded_osd_state = sharded_osd['state']
    rekeyed_osd_state: dict[Union[str, int], Any] = {}
    for (key, param_state) in sharded_osd_state.items():
        if isinstance(key, str):
            rekeyed_osd_state[key] = param_state
            continue
        flat_param_key = unflat_param_names_to_flat_param_key.get(key.unflat_param_names, key.unflat_param_names)
        rekeyed_osd_state[flat_param_key] = param_state
    if 'param_groups' in sharded_osd:
        rekeyed_osd_param_groups: list[dict[str, Any]] = []
        for unflat_param_group in sharded_osd['param_groups']:
            flat_param_group = copy.deepcopy(unflat_param_group)
            flat_param_keys = sorted({unflat_param_name_to_flat_param_key[unflat_param_name] for unflat_param_name in unflat_param_group['params']})
            flat_param_group['params'] = flat_param_keys
            rekeyed_osd_param_groups.append(flat_param_group)
        return {'state': rekeyed_osd_state, 'param_groups': rekeyed_osd_param_groups}
    else:
        return {'state': rekeyed_osd_state}

def _constant_eager_impl(ctx, value, dtype, shape, verify_shape) -> ops._EagerTensorBase:
    """Creates a constant on the current device."""
    t = convert_to_eager_tensor(value, ctx, dtype)
    if shape is None:
        return t
    shape = tensor_shape.as_shape(shape)
    if shape == t.shape:
        return t
    if verify_shape:
        raise TypeError(f'Expected Tensor {t} (converted from {value}) with shape {tuple(shape)}, but got shape {tuple(t.shape)}.')
    num_t = t.shape.num_elements()
    if num_t == shape.num_elements():
        return _eager_reshape(t, shape.as_list(), ctx)
    if num_t == 1:
        if <MASK>:
            with ops.device('/device:CPU:0'):
                x = _eager_fill(shape.as_list(), _eager_identity(t, ctx), ctx)
            return _eager_identity(x, ctx)
        else:
            return _eager_fill(shape.as_list(), t, ctx)
    raise TypeError(f'Eager execution of tf.constant with unsupported shape. Tensor {t} (converted from {value}) has {num_t:d} elements, but got `shape` {shape} with {shape.num_elements()} elements).')

def solve_for_tiling(expr: sympy.Expr) -> Optional[sympy.Expr]:
    """
    Giving an expr with a single free symbol, try to find a tiling that would
    make the expression coalesced with respect to that symbol.

    Tiling an expression `x` by `y` means that the expression will now be indexed
    by both the original (x) and by (x * y). So we are looking for a
    multiplicative factor that will make ((x + 1) * y) - (x * y) == 1.

    To simplify things for sympy, we'll try just x * y == 1, check x(1) and x(0).
    """
    if len(expr.free_symbols) == 0:
        return None
    free_symbol = next(iter(expr.free_symbols))

    def _solve_simple_expr(expr: sympy.Expr) -> Optional[sympy.Expr]:
        assert not expr.has(ModularIndexing) and (not expr.has(FloorDiv))
        if len(expr.free_symbols) != 1:
            return None
        out = try_solve(sympy.Eq(expr, 1), free_symbol)
        if not out or not out[1].is_constant():
            return None
        return out[1]
    if not expr.has(ModularIndexing) and (not expr.has(FloorDiv)):
        return _solve_simple_expr(expr)
    required_values = []
    eq_1_expressions = []
    for arg in sympy.Add.make_args(expr):
        if <MASK>:
            seen = False
            for mul_arg in arg.args:
                out = solve_for_zero(mul_arg)
                if out is None:
                    continue
                assert out.is_constant()
                seen = True
                required_values.append(out)
            if not seen:
                return None
        else:
            eq_1_expressions.append(arg)
    if not eq_1_expressions:
        return None
    eq_1_expr = sum(eq_1_expressions)

    def indexing_div_rep(x: sympy.Expr, y: sympy.Expr, z: Optional[sympy.Expr]=None) -> sympy.Expr:
        return x / y
    eq_1_expr_simplified = eq_1_expr.replace(ModularIndexing, indexing_div_rep).replace(FloorDiv, indexing_div_rep)
    out = _solve_simple_expr(eq_1_expr_simplified)
    if not out or sympy_subs(eq_1_expr, {free_symbol: out}) != 1:
        return None
    required_values.append(out)
    if len(OrderedSet(required_values)) == 1:
        return required_values[0]
    return None

def get_tolerance_and_cosine_flag(self, is_training, current_device, name):
    cosine = self.args.cosine
    tolerance = 0.001
    if <MASK>:
        tolerance = 8 * 0.01
    if is_training:
        from torch._inductor import config as inductor_config
        if name in REQUIRE_EVEN_HIGHER_TOLERANCE or (inductor_config.max_autotune and name in REQUIRE_EVEN_HIGHER_TOLERANCE_MAX_AUTOTUNE):
            tolerance = 8 * 0.01
        elif name in REQUIRE_HIGHER_TOLERANCE or (self.args.amp and name in REQUIRE_HIGHER_TOLERANCE_AMP):
            tolerance = 4 * 0.01
        else:
            tolerance = 0.01
    return (tolerance, cosine)

def set_annotation_mask(self, names):
    """Set the mask of annotations that will be returned by the SELECT."""
    if <MASK>:
        self.annotation_select_mask = None
    else:
        self.annotation_select_mask = set(names)
        if self.selected:
            self.selected = {key: value for (key, value) in self.selected.items() if not isinstance(value, str) or value in self.annotation_select_mask}
            for name in names:
                self.selected[name] = name
    self._annotation_select_cache = None

def sanitize_array(data, index: Index | None, dtype: DtypeObj | None=None, copy: bool=False, *, allow_2d: bool=False) -> ArrayLike:
    """
    Sanitize input data to an ndarray or ExtensionArray, copy if specified,
    coerce to the dtype if specified.

    Parameters
    ----------
    data : Any
    index : Index or None, default None
    dtype : np.dtype, ExtensionDtype, or None, default None
    copy : bool, default False
    allow_2d : bool, default False
        If False, raise if we have a 2D Arraylike.

    Returns
    -------
    np.ndarray or ExtensionArray
    """
    original_dtype = dtype
    if isinstance(data, ma.MaskedArray):
        data = sanitize_masked_array(data)
    if isinstance(dtype, NumpyEADtype):
        dtype = dtype.numpy_dtype
    infer_object = not isinstance(data, (ABCIndex, ABCSeries))
    data = extract_array(data, extract_numpy=True, extract_range=True)
    if isinstance(data, np.ndarray) and data.ndim == 0:
        if dtype is None:
            dtype = data.dtype
        data = lib.item_from_zerodim(data)
    elif isinstance(data, range):
        data = range_to_ndarray(data)
        copy = False
    if not is_list_like(data):
        if index is None:
            raise ValueError('index must be specified when data is not list-like')
        if isinstance(data, str) and using_string_dtype() and (original_dtype is None):
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
        data = construct_1d_arraylike_from_scalar(data, len(index), dtype)
        return data
    elif isinstance(data, ABCExtensionArray):
        if dtype is not None:
            subarr = data.astype(dtype, copy=copy)
        elif copy:
            subarr = data.copy()
        else:
            subarr = data
    elif isinstance(dtype, ExtensionDtype):
        _sanitize_non_ordered(data)
        cls = dtype.construct_array_type()
        if not hasattr(data, '__array__'):
            data = list(data)
        subarr = cls._from_sequence(data, dtype=dtype, copy=copy)
    elif isinstance(data, np.ndarray):
        if isinstance(data, np.matrix):
            data = data.A
        if dtype is None:
            subarr = data
            if data.dtype == object and infer_object:
                subarr = lib.maybe_convert_objects(data, convert_numeric=False, convert_non_numeric=True, convert_to_nullable_dtype=False, dtype_if_all_nat=np.dtype('M8[s]'))
            elif data.dtype.kind == 'U' and using_string_dtype():
                from pandas.core.arrays.string_ import StringDtype
                dtype = StringDtype(na_value=np.nan)
                subarr = dtype.construct_array_type()._from_sequence(data, dtype=dtype)
            if (subarr is data or (subarr.dtype == 'str' and subarr.dtype.storage == 'python')) and copy:
                subarr = subarr.copy()
        else:
            subarr = _try_cast(data, dtype, copy)
    elif hasattr(data, '__array__'):
        if <MASK>:
            data = np.asarray(data)
        else:
            data = np.array(data, copy=copy)
        return sanitize_array(data, index=index, dtype=dtype, copy=False, allow_2d=allow_2d)
    else:
        _sanitize_non_ordered(data)
        data = list(data)
        if len(data) == 0 and dtype is None:
            subarr = np.array([], dtype=np.float64)
        elif dtype is not None:
            subarr = _try_cast(data, dtype, copy)
        else:
            subarr = maybe_convert_platform(data)
            if subarr.dtype == object:
                subarr = cast(np.ndarray, subarr)
                subarr = lib.maybe_convert_objects(subarr, convert_numeric=False, convert_non_numeric=True, convert_to_nullable_dtype=False, dtype_if_all_nat=np.dtype('M8[s]'))
    subarr = _sanitize_ndim(subarr, data, dtype, index, allow_2d=allow_2d)
    if isinstance(subarr, np.ndarray):
        dtype = cast(np.dtype, dtype)
        subarr = _sanitize_str_dtypes(subarr, data, dtype, copy)
    return subarr

def _check_frozen(self, expr: sympy.Basic, concrete_val: sympy.Basic) -> None:
    if <MASK>:
        self.counter['ignored_backward_guard'] += 1
        signpost_event('dynamic', 'evaluate_expr_frozen', {**self.co_fields, 'ignored_guard': f'{expr} == {concrete_val}', 'version': 2})
        log.info('Ignored guard %s == %s, this could result in accuracy problems', expr, concrete_val, stack_info=log.getEffectiveLevel() < logging.WARNING)

@register_lowering(aten.cat)
def cat(inputs, dim=0):
    cpu_device = inputs[0].get_device().type == 'cpu'
    if cpu_device and all((input.get_dtype() in [torch.int8, torch.uint8] for input in inputs)):
        for input in inputs:
            input.realize()
        if all((len(input.get_size()) == 4 for input in inputs)):
            (inputs, _) = require_channels_last(aten.cat, *inputs)
        return fallback_handler(aten.cat.default)(inputs, dim)
    if len(inputs) == 1:
        return clone(inputs[0])
    dim = _validate_dim(inputs[0], dim, 0)
    dtype = get_promoted_dtype(*inputs, type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
    inputs = [to_dtype(inp, dtype) for inp in inputs]

    def unwrap_tensor(x: Union[TensorBox, ir.StorageBox]) -> ir.IRNode:
        if isinstance(x, TensorBox):
            if isinstance(x.data, ir.BaseView):
                return x.data.unwrap_view()
            else:
                return x.data
        if isinstance(x, ir.StorageBox):
            return x.data
        return x

    def is_reduction(t):
        return isinstance(t, ir.ComputedBuffer) and isinstance(t.data, ir.Reduction)

    def can_fuse_reduction(t):
        if isinstance(t, (TensorBox, ir.StorageBox)):
            return can_fuse_reduction(unwrap_tensor(t))
        return is_reduction(t) or (isinstance(t, ir.Pointwise) and any((can_fuse_reduction(V.graph.get_buffer(read)) for read in t.get_read_names())))
    fusable_reduction = any((can_fuse_reduction(t) for t in inputs))

    def should_lower_cat_input(x) -> bool:
        if ir.is_storage_and_layout(x):
            (storage, _) = ir.as_storage_and_layout(x, freeze=False)
            return not ir.ConcatKernel.can_realize_into_without_copy(storage)
        if <MASK>:
            return should_lower_cat_input(unwrap_tensor(x))
        if isinstance(x, ir.Pointwise):
            return True
        return False
    if config.force_pointwise_cat:
        return pointwise_cat(inputs, dim)
    if cpu_device:
        return TensorBox(ir.ConcatKernel.create(inputs, dim))

    def op_count(x):
        if isinstance(x, (TensorBox, ir.StorageBox)):
            return op_count(unwrap_tensor(x))
        if not isinstance(x, ir.Pointwise):
            return 0
        count = x.inner_fn_opcount().num_ops
        for read in x.get_read_names():
            count += op_count(V.graph.get_buffer(read))
        return count
    MAX_COMPLEX_POINTWISE_CAT = 8
    MAX_SIMPLE_OP_COUNT = 2

    def additional_pointwise_ops(op: torch._ops.OpOverload):
        return op in (aten.cat.default, aten.constant_pad_nd.default)
    if len(inputs) <= MAX_COMPLEX_POINTWISE_CAT or (len(inputs) <= config.max_pointwise_cat_inputs and all((op_count(t) <= MAX_SIMPLE_OP_COUNT for t in inputs))):
        pointwise_uses = all((is_pointwise_use(use, additional_pointwise_ops) for use in V.current_node.users))
        fuse_pointwise_use = any((should_lower_cat_input(inp) for inp in inputs)) and pointwise_uses
        horizontal_fuse_cat = all((should_lower_cat_input(inp) for inp in inputs)) and (not any((can_fuse_reduction(t) for t in inputs)))
        if fuse_pointwise_use or (horizontal_fuse_cat and (not fusable_reduction)):
            return pointwise_cat(inputs, dim)
    return TensorBox(ir.ConcatKernel.create(inputs, dim))

def get_graph_partition_symbol_inputs(self, partition: PartitionType, input_nodes: dict[str, Union[ir.IRNode, ir.TorchBindObject, sympy.Expr]]) -> OrderedSet[sympy.Symbol]:
    """
        Returns all symbol inputs which are required to be in scope to successfully
        perform codegen for this graph partition, including:
        - free symbols used in partition nodes
        - free symbols in partition input/node shapes, strides, and offsets. This is needed
          for recording cudagraphs for tensors with dynamic shapes.
        """

    def get_layout_symints(node: ir.IRNode) -> OrderedSet[sympy.Symbol]:
        free_symbol_uses: OrderedSet[sympy.Symbol] = OrderedSet()
        layout = node.maybe_get_layout()
        if isinstance(layout, ir.Layout):
            free_symbol_uses.update(free_symbols(layout.size) | free_symbols(layout.stride) | free_symbols(layout.offset))
            if isinstance(layout, ir.MutationLayoutSHOULDREMOVE):
                free_symbol_uses.update(get_layout_symints(layout.target))
        else:
            assert layout is None, f'Expect layout to be None but found layout={layout}'
        return free_symbol_uses

    def get_scheduler_node_symbol_uses(node: BaseSchedulerNode) -> OrderedSet[sympy.Symbol]:
        """
            Gets symbols used in node.
            """
        if <MASK>:
            return OrderedSet().union(*(get_scheduler_node_symbol_uses(snode) for snode in node.snodes))
        assert node.node is not None
        free_symbol_uses = node.node.get_free_symbol_uses()
        free_symbol_uses.update(*(get_layout_symints(ir_node) for ir_node in node.node.get_outputs()))
        return free_symbol_uses

    def get_input_node_symbols(node: Union[ir.IRNode, sympy.Expr, ir.TorchBindObject]) -> OrderedSet[sympy.Symbol]:
        """
            Gets symbols used in input node shapes, strides, and offsets.
            """
        if isinstance(node, ir.TorchBindObject):
            return OrderedSet()
        elif isinstance(node, ir.IRNode):
            return get_layout_symints(node)
        else:
            raise NotImplementedError(f'Unsupported input node type: {type(node)}')

    def filter_symbols(symbols: OrderedSet[sympy.Symbol]) -> OrderedSet[sympy.Symbol]:
        """
            Filters a set of symbols that are required for codegen. Skip symbols
            that are always internal to kernels, such as SymT.TMP, SymT.INDEX,
            and SymT.R0_INDEX.
            """
        return OrderedSet((s for s in symbols if symbol_is_type(s, (SymT.SIZE, SymT.FLOAT, SymT.UNBACKED_INT, SymT.UNBACKED_FLOAT))))
    candidate_symbols: OrderedSet[sympy.Symbol] = OrderedSet().union(*(get_scheduler_node_symbol_uses(node) for node in partition))
    candidate_symbols.union(*(get_input_node_symbols(node) for (_, node) in input_nodes.items()))
    candidate_symbols = filter_symbols(candidate_symbols)
    res: OrderedSet[sympy.Symbol] = OrderedSet()
    for s in candidate_symbols:
        symplified_s = V.graph.sizevars.simplify(s)
        res.update(symplified_s.free_symbols)
    return OrderedSet(sorted(res, key=operator.attrgetter('name')))

def maybe_merge_partition(self_id: int, other_id: int):
    self_nodes = partitions_by_id[self_id].nodes
    other_nodes = partitions_by_id[other_id].nodes

    def dfs_iter_find_cycle(all_user_nodes: set[Node]):
        for user_node in all_user_nodes:
            visited_partition_ids = set()
            for path_node in self.dependency_viewer.downstreams_of(user_node):
                if path_node in self_nodes or path_node in other_nodes:
                    return True
                if path_node in assignment:
                    partition_id = assignment[path_node]
                    if partition_id in visited_partition_ids:
                        continue
                    p_map = partition_map[partition_id]
                    if <MASK>:
                        return True
                    visited_partition_ids.add(partition_id)
        return False
    all_user_nodes = partition_users[self_id] | partition_users[other_id]
    all_user_nodes.difference_update(other_nodes, self_nodes)
    if dfs_iter_find_cycle(all_user_nodes):
        return (self_id, False)
    (merge_id, removed_id) = (self_id, other_id)
    if len(self_nodes) < len(other_nodes):
        (merge_id, removed_id) = (removed_id, merge_id)
    partitions_by_id[merge_id].nodes.update(partitions_by_id[removed_id].nodes)
    for node in partitions_by_id[removed_id].nodes:
        assignment[node] = merge_id
    del partitions_by_id[removed_id]
    partitions_order[merge_id] = min(partitions_order[merge_id], partitions_order[removed_id])
    del partitions_order[removed_id]
    partition_map[merge_id] = partition_map[merge_id].union(partition_map[removed_id])
    del partition_map[removed_id]
    partition_users[merge_id] = all_user_nodes
    del partition_users[removed_id]
    return (merge_id, True)

def check_block_tiles(self, op: 'CKTileGemmOperation'):
    """
        The contiguous dimension of a tensor must be divisible by the block tile size
        This helper function enforces it for the inputs and the output.
        """
    (M, N, K) = self.get_gemm_problem_size()

    def check(dim_size, tile_size, is_padded):
        if is_static_int(dim_size) and dim_size % tile_size != 0 and (is_padded == 'false'):
            return False
        return True
    if op.layout_a == 'Row':
        return True
    elif op.layout_a == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_a={op.layout_a!r}')
    if <MASK>:
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_b == 'Col':
        return True
    else:
        raise AssertionError(f'Invalid op.layout_b={op.layout_b!r}')
    if op.layout_c == 'Row':
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_c == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_c={op.layout_c!r}')
    return True

