def _get_self_obj_from_closure(fn):
    """Get the object that `self` keyword refers to within a function.

  Args:
    fn: A python function object

  Returns:
    A class object that `self` refers to. Return None if not found.

  Here is an example demonstrating how this helper function works.

  ```
  class Foo():

    def __init__(self):
      self.val = 1

    def bar(self):
      x = 2

      def fn():
        return self.val + x

      return fn

  foo = Foo()
  fn = foo.bar()
  self_obj = _get_self_obj_from_closure(fn)
  assert self_obj is foo
  ```

  The goal is to get the `self_obj` (foo) from `fn`, so that it's feasible to
  access attributes of `foo`, like self.val in this case.

  This function first parses fn.qual_name, "Foo.bar.<locals>.fn", and finds the
  closure whose class name appear in fn.qual_name first.
  """
    assert hasattr(fn, '__closure__')
    qual_name = fn.__qualname__.split('.')
    qual_name = qual_name[::-1]
    if fn.__closure__:
        for cls_name in qual_name:
            for cell in fn.__closure__:
                try:
                    closure = cell.cell_contents
                except ValueError:
                    continue
                if inspect.isclass(type(closure)):
                    if <MASK>:
                        obj = closure
                        return obj
    return None

def visit_keyword(self, node):
    if node.arg not in self.replacements:
        return self.generic_visit(node)
    repl = self._prepare_replacement(node, node.arg)
    if isinstance(repl, gast.keyword):
        return repl
    elif <MASK>:
        return repl
    raise ValueError('a keyword argument may only be replaced by another keyword or a non-empty list of keywords. Found: {} for keyword {}'.format(repl, node.arg))

@parameterized.named_parameters(('to_tf_per_tensor', quant_opts_pb2.TF, False), ('to_xla_per_tensor', quant_opts_pb2.XLA, False), ('to_uniform_quantized_per_tensor', quant_opts_pb2.UNIFORM_QUANTIZED, False), ('to_uniform_quantized_per_channel', quant_opts_pb2.UNIFORM_QUANTIZED, True))
@test_util.run_in_graph_and_eager_modes
def test_conv_model(self, target_opset: quant_opts_pb2.OpSet, enable_per_channel_quantization: bool):
    filter_shape = (2, 3, 512, 2)
    model = self._create_conv2d_model(input_shape=(1, 3, 4, 512), filter_shape=filter_shape, has_bias=True, has_batch_norm=True, activation_fn=nn_ops.relu6)
    saved_model_save.save(model, self._input_saved_model_path)
    tags = {tag_constants.SERVING}
    quantization_options = quant_opts_pb2.QuantizationOptions(quantization_method=quant_opts_pb2.QuantizationMethod(preset_method=_PresetMethod.METHOD_DYNAMIC_RANGE_INT8), tags=tags, signature_keys=['serving_default'], op_set=target_opset, enable_per_channel_quantization=enable_per_channel_quantization)
    converted_model = quantize_model.quantize(self._input_saved_model_path, self._output_saved_model_path, quantization_options)
    self.assertIsNotNone(converted_model)
    self.assertCountEqual(converted_model.signatures._signatures.keys(), {'serving_default'})
    output_loader = saved_model_loader.SavedModelLoader(self._output_saved_model_path)
    output_graphdef = output_loader.get_meta_graph_def_from_tags(tags).graph_def
    if <MASK>:
        quantized_axis = 3
        quantized_axis_attr = attr_value_pb2.AttrValue(i=quantized_axis)
        quantized_dim_size_attr = attr_value_pb2.AttrValue(list=attr_value_pb2.AttrValue.ListValue(shape=[tensor_shape_pb2.TensorShapeProto(dim=[tensor_shape_pb2.TensorShapeProto.Dim(size=filter_shape[quantized_axis])])]))
    if target_opset == quant_opts_pb2.UNIFORM_QUANTIZED:
        self.assertTrue(self._contains_op(output_graphdef, 'UniformQuantizedConvolutionHybrid'))
        self.assertFalse(self._contains_op(output_graphdef, 'Conv2D'))
        if enable_per_channel_quantization:
            self.assertTrue(self._contains_op(output_graphdef, 'UniformQuantizedConvolutionHybrid', 'rhs_quantization_axis', quantized_axis_attr))
            self.assertTrue(self._contains_op(output_graphdef, 'Const', '_output_shapes', quantized_dim_size_attr))
    elif target_opset == quant_opts_pb2.XLA:
        self.assertTrue(self._contains_op(output_graphdef, 'XlaConvV2'))
        self.assertFalse(self._contains_op(output_graphdef, 'Conv2D'))
    else:
        self.assertTrue(self._contains_quantized_function_call(output_graphdef))
        self.assertTrue(self._contains_op(output_graphdef, 'Conv2D'))

def transform_algebraic_expression(expr, counter, dimension_dict):
    """
        Transforms an algebraic expression to z3 format
        Args:
            expr: An expression is either a dimension variable or an algebraic-expression


        Returns: the transformed expression

        """
    assert is_algebraic_expression(expr) or is_dim(expr)
    if is_dim(expr):
        (transformed, counter) = transform_dimension(expr, counter, dimension_dict)
        return (transformed.arg(1), counter)
    elif isinstance(expr, Prod):
        dims = []
        for dim in expr.products:
            assert is_dim(dim)
            (d, counter) = transform_dimension(dim, counter, dimension_dict)
            dims.append(d.arg(1))
        return (z3.Product(dims), counter)
    elif is_algebraic_expression(expr):
        (lhs, counter) = transform_algebraic_expression(expr.lhs, counter, dimension_dict)
        (rhs, counter) = transform_algebraic_expression(expr.rhs, counter, dimension_dict)
        if expr.op == op_sub:
            c = lhs - rhs
        elif <MASK>:
            c = lhs + rhs
        elif expr.op == op_div:
            c = lhs / rhs
        elif expr.op == op_mul:
            c = lhs * rhs
        elif expr.op == op_mod:
            c = lhs % rhs
        else:
            raise NotImplementedError('operation not yet implemented')
        return (c, counter)
    else:
        raise RuntimeError

def _clone_sequential_model(model, input_tensors=None, layer_fn=_clone_layer):
    """Clone a `Sequential` model instance.

  Model cloning is similar to calling a model on new inputs,
  except that it creates new layers (and thus new weights) instead
  of sharing the weights of the existing layers.

  Args:
      model: Instance of `Sequential`.
      input_tensors: optional list of input tensors
          to build the model upon. If not provided,
          placeholders will be created.
      layer_fn: callable to be applied on non-input layers in the model. By
          default it clones the layer. Another example is to preserve the layer
          to share the weights. This is required when we create a per-replica
          copy of the model with distribution strategy; we want the weights to
          be shared but still feed inputs separately so we create new input
          layers.

  Returns:
      An instance of `Sequential` reproducing the behavior
      of the original model, on top of new inputs tensors,
      using newly instantiated weights.

  Raises:
      ValueError: in case of invalid `model` argument value or `layer_fn`
      argument value.
  """
    if not isinstance(model, Sequential):
        raise ValueError('Expected `model` argument to be a `Sequential` model instance, but got:', model)
    if not callable(layer_fn):
        raise ValueError('Expected `layer_fn` argument to be a callable.')
    layers = []
    layer_map = {}
    for layer in model._flatten_layers(include_self=False, recursive=False):
        if isinstance(layer, InputLayer) and input_tensors is not None:
            continue
        cloned_layer = _clone_layer(layer) if isinstance(layer, InputLayer) else layer_fn(layer)
        layers.append(cloned_layer)
        layer_map[layer] = cloned_layer
    (layers, ancillary_layers) = _remove_ancillary_layers(model, layer_map, layers)
    if input_tensors is None:
        cloned_model = Sequential(layers=layers, name=model.name)
    elif <MASK>:
        raise ValueError('To clone a `Sequential` model, we expect  at most one tensor as part of `input_tensors`.')
    else:
        if isinstance(input_tensors, tuple):
            input_tensors = list(input_tensors)
        x = generic_utils.to_list(input_tensors)[0]
        if backend.is_keras_tensor(x):
            origin_layer = x._keras_history.layer
            if isinstance(origin_layer, InputLayer):
                cloned_model = Sequential(layers=[origin_layer] + layers, name=model.name)
            else:
                raise ValueError('Cannot clone a `Sequential` model on top of a tensor that comes from a Keras layer other than an `InputLayer`. Use the functional API instead.')
        else:
            input_tensor = Input(tensor=x, name='input_wrapper_for_' + str(x.name))
            input_layer = input_tensor._keras_history.layer
            cloned_model = Sequential(layers=[input_layer] + layers, name=model.name)
    if not ancillary_layers:
        return cloned_model
    tensor_map = {}
    for (depth, cloned_nodes) in cloned_model._nodes_by_depth.items():
        nodes = model._nodes_by_depth[depth]
        for (cloned_node, node) in zip(cloned_nodes, nodes):
            if isinstance(cloned_node.output_tensors, list):
                for (j, output_tensor) in enumerate(cloned_node.output_tensors):
                    tensor_map[node.output_tensors[j]] = output_tensor
            else:
                tensor_map[node.output_tensors] = cloned_node.output_tensors
    new_nodes = _make_new_nodes({depth: nodes for (depth, nodes) in model._nodes_by_depth.items() if depth < 0}, layer_fn, layer_map, tensor_map)
    _insert_ancillary_layers(cloned_model, ancillary_layers, model.metrics_names, new_nodes)
    return cloned_model

def __init__(self, layout: OutputSpec, kernel: _OpOverloads, tensor_args: Sequence[IRNode], nontensor_args: Sequence[Any], unflatten_args: Callable[..., Any], kwargs: Optional[dict[str, Any]]=None, *, unbacked_bindings: Optional[dict[sympy.Symbol, pytree.KeyPath]]=None) -> None:
    super().__init__(layout, tuple(tensor_args), tuple(nontensor_args), op_overload=kernel)
    self.use_runtime_dispatch = False
    self.unbacked_bindings = unbacked_bindings or {}
    assert isinstance(kernel, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)), f'Fails to create FallbackKernel for {kernel}: {type(kernel)} not supported'
    self.op_overload = kernel
    self.unflatten_args = unflatten_args
    self.kwargs = {} if kwargs is None else kwargs
    assert self.python_kernel_name is not None
    V.graph.warn_fallback(self.python_kernel_name)
    self.alias_names: list[str] = []
    self.mutation_names: list[str] = []
    if isinstance(self.op_overload, torch._ops.HigherOrderOperator):
        return
    if '_c10d_functional' in self.op_overload.name():
        return
    schema = self.op_overload._schema
    if <MASK>:
        self.mutation_names.append(tensor_args[0].get_name())
        return
    if schema.is_mutable and (not can_auto_functionalize(kernel)):
        raise NotImplementedError(f"NYI: Can't generate FallbackKernel for {kernel}")
    (args, kwargs) = self.unflatten_args(self.inputs, self.constant_args)

    def handle_aliasing_and_mutation(info: torch._C.Argument, arg: Any) -> None:
        if isinstance(info.type, torch.ListType):
            assert isinstance(arg, (list, tuple)), type(arg)
        if library_utils.is_tensor_like_type(info.type):
            assert not isinstance(arg, (tuple, list))
        if arg is None:
            return
        if info.alias_info is None:
            return

        def add_alias(t: IRNode) -> None:
            self.alias_names.append(t.get_name())
            assert info.alias_info is not None
            if info.alias_info.is_write:
                self.mutation_outputs.append(MutationOutput(NoneLayout(device=t.get_device()), t, self))
        if library_utils.is_tensorlist_like_type(info.type):
            if arg is not None:
                for optional_tensor_arg in arg:
                    add_alias(optional_tensor_arg)
        else:
            assert library_utils.is_tensor_like_type(info.type)
            add_alias(arg)
    for (info, arg) in torch._library.utils.zip_schema(schema, args, kwargs):
        handle_aliasing_and_mutation(info, arg)

def forward(self, input, hx=None):
    """
        Runs the forward pass.
        """
    self._update_flat_weights()
    num_directions = 2 if self.bidirectional else 1
    orig_input = input
    if isinstance(orig_input, PackedSequence):
        (input, batch_sizes, sorted_indices, unsorted_indices) = input
        max_batch_size = batch_sizes[0]
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    else:
        batch_sizes = None
        if <MASK>:
            raise ValueError(f'RNN: Expected input to be 2D or 3D, got {input.dim()}D tensor instead')
        is_batched = input.dim() == 3
        batch_dim = 0 if self.batch_first else 1
        if not is_batched:
            input = input.unsqueeze(batch_dim)
            if hx is not None:
                if hx.dim() != 2:
                    raise RuntimeError(f'For unbatched 2-D input, hx should also be 2-D but got {hx.dim()}-D tensor')
                hx = hx.unsqueeze(1)
        elif hx is not None and hx.dim() != 3:
            raise RuntimeError(f'For batched 3-D input, hx should also be 3-D but got {hx.dim()}-D tensor')
        max_batch_size = input.size(0) if self.batch_first else input.size(1)
        sorted_indices = None
        unsorted_indices = None
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    assert hx is not None
    self.check_forward_args(input, hx, batch_sizes)
    assert self.mode == 'RNN_TANH' or self.mode == 'RNN_RELU'
    if batch_sizes is None:
        if self.mode == 'RNN_TANH':
            result = _VF.rnn_tanh(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
        else:
            result = _VF.rnn_relu(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
    elif self.mode == 'RNN_TANH':
        result = _VF.rnn_tanh(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    else:
        result = _VF.rnn_relu(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    output = result[0]
    hidden = result[1]
    if isinstance(orig_input, PackedSequence):
        output_packed = PackedSequence(output, batch_sizes, sorted_indices, unsorted_indices)
        return (output_packed, self.permute_hidden(hidden, unsorted_indices))
    if not is_batched:
        output = output.squeeze(batch_dim)
        hidden = hidden.squeeze(1)
    return (output, self.permute_hidden(hidden, unsorted_indices))

def ragged_binary_elementwise_op(op, x, y):
    """Binary elementwise api handler for RaggedTensors."""
    x_is_ragged = ragged_tensor.is_ragged(x)
    y_is_ragged = ragged_tensor.is_ragged(y)
    x = ragged_tensor.convert_to_tensor_or_ragged_tensor(x, preferred_dtype=y.dtype if y_is_ragged else None)
    y = ragged_tensor.convert_to_tensor_or_ragged_tensor(y, preferred_dtype=x.dtype)
    if x_is_ragged and y_is_ragged:
        (x, y) = ragged_tensor.match_row_splits_dtypes(x, y)
    if x_is_ragged and y_is_ragged or (x_is_ragged and x.flat_values.shape.ndims <= y.shape.ndims) or (y_is_ragged and y.flat_values.shape.ndims <= x.shape.ndims):
        if x_is_ragged:
            dim_size_dtype = x.row_splits.dtype
        else:
            dim_size_dtype = y.row_splits.dtype
        shape_x = ragged_tensor_shape.RaggedTensorDynamicShape.from_tensor(x, dim_size_dtype=dim_size_dtype)
        shape_y = ragged_tensor_shape.RaggedTensorDynamicShape.from_tensor(y, dim_size_dtype=dim_size_dtype)
        bcast_shape = ragged_tensor_shape.broadcast_dynamic_shape(shape_x, shape_y)
        x = ragged_tensor_shape.broadcast_to(x, bcast_shape, broadcast_inner_dimensions=False)
        y = ragged_tensor_shape.broadcast_to(y, bcast_shape, broadcast_inner_dimensions=False)
    x_values = x.flat_values if ragged_tensor.is_ragged(x) else x
    y_values = y.flat_values if ragged_tensor.is_ragged(y) else y
    mapped_values = op(x_values, y_values)
    if <MASK>:
        return mapped_values
    if ragged_tensor.is_ragged(x):
        return x.with_flat_values(mapped_values)
    else:
        return y.with_flat_values(mapped_values)

def _should_convert_dates(convert_dates: bool | list[str], keep_default_dates: bool, col: Hashable) -> bool:
    """
    Return bool whether a DataFrame column should be cast to datetime.
    """
    if convert_dates is False:
        return False
    elif <MASK>:
        return True
    elif not keep_default_dates:
        return False
    elif not isinstance(col, str):
        return False
    col_lower = col.lower()
    if col_lower.endswith(('_at', '_time')) or col_lower in {'modified', 'date', 'datetime'} or col_lower.startswith('timestamp'):
        return True
    return False

def testBasicTrainLoopRetryOnAborted(self):
    logdir = _test_dir('basic_train_loop_exception_aborts')

    class AbortAndRetry:

        def __init__(self):
            self.num_calls = 0
            self.retries_left = 2

        def train_fn(self, unused_sess):
            self.num_calls += 1
            if <MASK>:
                self.retries_left -= 1
            if self.retries_left > 0:
                raise errors_impl.AbortedError(None, None, 'Aborted here')
            else:
                raise RuntimeError('Failed Again')
    with ops.Graph().as_default():
        sv = supervisor.Supervisor(logdir=logdir)
        aar = AbortAndRetry()
        with self.assertRaisesRegex(RuntimeError, 'Failed Again'):
            basic_loops.basic_train_loop(sv, aar.train_fn)
        self.assertEqual(0, aar.retries_left)

def get_attr(self, target: str, args: tuple[()], kwargs: dict[str, object]) -> Union[Constant, TensorBox, ShapeAsConstantBuffer, ir.Subgraph, TorchBindObject]:
    value = getattr_recursive(self.module, target)
    if isinstance(value, torch.fx.GraphModule):
        if <MASK>:
            return self.seen_subgraphs[target]
        out = ir.Subgraph(name=target, graph_module=value)
        self.seen_subgraphs[target] = out
        return out
    if isinstance(value, torch._C.ScriptObject):
        self.torchbind_constants[target] = value
        self.constant_reprs[target] = ''
        return TorchBindObject(name=target, value=value)
    elif isinstance(value, FakeScriptObject):
        self.torchbind_constants[target] = value
        self.constant_reprs[target] = ''
        return TorchBindObject(name=target, value=value)
    assert isinstance(value, torch.Tensor)
    if config.aot_inductor.use_runtime_constant_folding or config.always_keep_tensor_constants or unsupported_output_tensor(value):
        return self.add_tensor_constant(value, target)
    with no_dispatch():
        if value.shape == ():
            return Constant(value=value.item(), dtype=value.dtype, device=value.device)
        if self.can_inline_constant(value):
            log.debug('Inlining constant: %s ', str(target))
            from .lowering import tensor
            return tensor(value.tolist(), dtype=value.dtype, device=value.device)
    return self.add_tensor_constant(value, target)

def _pad_or_backfill(self, *, method: FillnaOptions, limit: int | None=None, limit_area: Literal['inside', 'outside'] | None=None, copy: bool=True) -> Self:
    mask = self._mask
    if mask.any():
        func = missing.get_fill_func(method, ndim=self.ndim)
        npvalues = self._data.T
        new_mask = mask.T
        if copy:
            npvalues = npvalues.copy()
            new_mask = new_mask.copy()
        elif limit_area is not None:
            mask = mask.copy()
        func(npvalues, limit=limit, mask=new_mask)
        if limit_area is not None and (not mask.all()):
            mask = mask.T
            neg_mask = ~mask
            first = neg_mask.argmax()
            last = len(neg_mask) - neg_mask[::-1].argmax() - 1
            if limit_area == 'inside':
                new_mask[:first] |= mask[:first]
                new_mask[last + 1:] |= mask[last + 1:]
            elif <MASK>:
                new_mask[first + 1:last] |= mask[first + 1:last]
        if copy:
            return self._simple_new(npvalues.T, new_mask.T)
        else:
            return self
    elif copy:
        new_values = self.copy()
    else:
        new_values = self
    return new_values

def to_pyval(self):
    """Returns this StructuredTensor as a nested Python dict or list of dicts.

    Converts this `StructuredTensor` to a nested python value:

    * `StructTensors` with `rank=0` are converted into a dictionary, with an
      entry for each field.  Field names are used as keys and field values are
      converted to python values.  In particular:

      * Scalar Tensor fields are converted to simple values (such as
        `int` or `float` or `string`)
      * Non-scalar Tensor fields and RaggedTensor fields are converted to
        nested lists of simple values.
      * StructuredTensor fields are converted recursively using `to_pyval`.

    * `StructTensors` with `rank>0` are converted to nested python `list`s,
      containing one dictionary for each structure (where each structure's
      dictionary is defined as described above).

    Requires that all fields are Eager tensors.

    >>> tf.experimental.StructuredTensor.from_fields(
    ...     {'a': [1, 2, 3]}, [3]).to_pyval()
    [{'a': 1}, {'a': 2}, {'a': 3}]

    Note that `StructuredTensor.from_pyval(pyval).to_pyval() == pyval`.

    Returns:
      A nested Python dict or list of dicts.
    """
    if <MASK>:
        raise ValueError('StructuredTensor.to_pyval() is only supported in eager mode.')
    result = {}
    for (key, value) in self._fields.items():
        if isinstance(value, ops.EagerTensor):
            value = value.numpy()
        if isinstance(value, np.ndarray):
            value = value.tolist()
        elif isinstance(value, ragged_tensor.RaggedTensor):
            value = value.to_list()
        elif isinstance(value, StructuredTensor):
            value = value.to_pyval()
        result[key] = value
    if len(self.shape) > 0:
        if not result:
            return _empty_dict_pylist_from_row_partitions(self.row_partitions, self.nrows())
        return _pyval_field_major_to_node_major(list(result.keys()), list(result.values()), self.rank)
    else:
        return result

def _signature(model) -> inspect.Signature:
    should_be_callable = getattr(model, 'forward', model)
    if <MASK>:
        return inspect.signature(should_be_callable)
    raise ValueError('model has no forward method and is not callable')

def _compute_elemwise_op_output_shape(self, shape1, shape2):
    """Computes the shape of the resultant of an elementwise operation.

    Args:
        shape1: tuple or None. Shape of the first tensor
        shape2: tuple or None. Shape of the second tensor

    Returns:
        expected output shape when an element-wise operation is
        carried out on 2 tensors with shapes shape1 and shape2.
        tuple or None.

    Raises:
        ValueError: if shape1 and shape2 are not compatible for
            element-wise operations.
    """
    if None in [shape1, shape2]:
        return None
    elif len(shape1) < len(shape2):
        return self._compute_elemwise_op_output_shape(shape2, shape1)
    elif <MASK>:
        return shape1
    output_shape = list(shape1[:-len(shape2)])
    for (i, j) in zip(shape1[-len(shape2):], shape2):
        if i is None or j is None:
            output_shape.append(None)
        elif i == 1:
            output_shape.append(j)
        elif j == 1:
            output_shape.append(i)
        else:
            if i != j:
                raise ValueError('Operands could not be broadcast together with shapes ' + str(shape1) + ' ' + str(shape2))
            output_shape.append(i)
    return tuple(output_shape)

def create_exception(self, source_error):
    """Creates exception from source_error."""
    preferred_type = type(source_error)
    to_ret = None
    if preferred_type.__init__ is Exception.__init__:
        to_ret = preferred_type(self.get_message())
    if preferred_type in KNOWN_STRING_CONSTRUCTOR_ERRORS:
        to_ret = preferred_type(self.get_message())
    elif preferred_type is KeyError:
        to_ret = MultilineMessageKeyError(self.get_message(), self.cause_message)
    if <MASK>:
        return to_ret.with_traceback(source_error.__traceback__)

def _maybe_evaluate_binop(self, op, op_class, lhs, rhs, eval_in_python=('in', 'not in'), maybe_eval_in_python=('==', '!=', '<', '>', '<=', '>=')):
    res = op(lhs, rhs)
    if res.has_invalid_return_type:
        raise TypeError(f"unsupported operand type(s) for {res.op}: '{lhs.type}' and '{rhs.type}'")
    if self.engine != 'pytables' and (res.op in CMP_OPS_SYMS and getattr(lhs, 'is_datetime', False) or getattr(rhs, 'is_datetime', False)):
        return self._maybe_eval(res, self.binary_ops)
    if <MASK>:
        return self._maybe_eval(res, eval_in_python)
    elif self.engine != 'pytables':
        if getattr(lhs, 'return_type', None) == object or is_string_dtype(getattr(lhs, 'return_type', None)) or getattr(rhs, 'return_type', None) == object or is_string_dtype(getattr(rhs, 'return_type', None)):
            return self._maybe_eval(res, eval_in_python + maybe_eval_in_python)
    return res

def format(number, decimal_sep, decimal_pos=None, grouping=0, thousand_sep='', force_grouping=False, use_l10n=None):
    """
    Get a number (as a number or string), and return it as a string,
    using formats defined as arguments:

    * decimal_sep: Decimal separator symbol (for example ".")
    * decimal_pos: Number of decimal positions
    * grouping: Number of digits in every group limited by thousand separator.
        For non-uniform digit grouping, it can be a sequence with the number
        of digit group sizes following the format used by the Python locale
        module in locale.localeconv() LC_NUMERIC grouping (e.g. (3, 2, 0)).
    * thousand_sep: Thousand separator symbol (for example ",")
    """
    if number is None or number == '':
        return mark_safe(number)
    if use_l10n is None:
        use_l10n = True
    use_grouping = use_l10n and settings.USE_THOUSAND_SEPARATOR
    use_grouping = use_grouping or force_grouping
    use_grouping = use_grouping and grouping != 0
    if isinstance(number, int) and (not use_grouping) and (not decimal_pos):
        return mark_safe(number)
    sign = ''
    if isinstance(number, float) and 'e' in str(number).lower():
        number = Decimal(str(number))
    if isinstance(number, Decimal):
        if decimal_pos is not None:
            cutoff = Decimal('0.' + '1'.rjust(decimal_pos, '0'))
            if <MASK>:
                number = Decimal('0')
        (_, digits, exponent) = number.as_tuple()
        if abs(exponent) + len(digits) > 200:
            number = '{:e}'.format(number)
            (coefficient, exponent) = number.split('e')
            coefficient = format(coefficient, decimal_sep, decimal_pos, grouping, thousand_sep, force_grouping, use_l10n)
            return '{}e{}'.format(coefficient, exponent)
        else:
            str_number = '{:f}'.format(number)
    else:
        str_number = str(number)
    if str_number[0] == '-':
        sign = '-'
        str_number = str_number[1:]
    if '.' in str_number:
        (int_part, dec_part) = str_number.split('.')
        if decimal_pos is not None:
            dec_part = dec_part[:decimal_pos]
    else:
        (int_part, dec_part) = (str_number, '')
    if decimal_pos is not None:
        dec_part += '0' * (decimal_pos - len(dec_part))
    dec_part = dec_part and decimal_sep + dec_part
    if use_grouping:
        try:
            intervals = list(grouping)
        except TypeError:
            intervals = [grouping, 0]
        active_interval = intervals.pop(0)
        int_part_gd = ''
        cnt = 0
        for digit in int_part[::-1]:
            if cnt and cnt == active_interval:
                if intervals:
                    active_interval = intervals.pop(0) or active_interval
                int_part_gd += thousand_sep[::-1]
                cnt = 0
            int_part_gd += digit
            cnt += 1
        int_part = int_part_gd[::-1]
    return sign + int_part + dec_part

def __init__(self, settings_module):
    for setting in dir(global_settings):
        if setting.isupper():
            setattr(self, setting, getattr(global_settings, setting))
    self.SETTINGS_MODULE = settings_module
    mod = importlib.import_module(self.SETTINGS_MODULE)
    tuple_settings = ('ALLOWED_HOSTS', 'INSTALLED_APPS', 'TEMPLATE_DIRS', 'LOCALE_PATHS', 'SECRET_KEY_FALLBACKS')
    self._explicit_settings = set()
    for setting in dir(mod):
        if setting.isupper():
            setting_value = getattr(mod, setting)
            if setting in tuple_settings and (not isinstance(setting_value, (list, tuple))):
                raise ImproperlyConfigured('The %s setting must be a list or a tuple.' % setting)
            setattr(self, setting, setting_value)
            self._explicit_settings.add(setting)
    if hasattr(time, 'tzset') and self.TIME_ZONE:
        zoneinfo_root = Path('/usr/share/zoneinfo')
        zone_info_file = zoneinfo_root.joinpath(*self.TIME_ZONE.split('/'))
        if <MASK>:
            raise ValueError('Incorrect timezone setting: %s' % self.TIME_ZONE)
        os.environ['TZ'] = self.TIME_ZONE
        time.tzset()

def reference_searchsorted(sorted_sequence, boundary, out_int32=False, right=False, side='left', sorter=None):
    side = 'right' if right or side == 'right' else 'left'
    if len(sorted_sequence.shape) == 1:
        ret = np.searchsorted(sorted_sequence, boundary, side=side, sorter=sorter)
        return ret.astype(np.int32) if out_int32 else ret
    elif sorted_sequence.shape[0] == 0:
        if <MASK>:
            sorter = sorter.flatten()
        ret = np.searchsorted(sorted_sequence.flatten(), boundary.flatten(), side=side, sorter=sorter)
        ret = ret.astype(np.int32) if out_int32 else ret
        return ret.reshape(boundary.shape)
    else:
        orig_shape = boundary.shape
        num_splits = np.prod(sorted_sequence.shape[:-1])
        splits = range(num_splits)
        (sorted_sequence, boundary) = (sorted_sequence.reshape(num_splits, -1), boundary.reshape(num_splits, -1))
        if sorter is not None:
            sorter = sorter.reshape(num_splits, -1)
        split_sequence = [sorted_sequence[i] for i in splits]
        split_boundary = [boundary[i] for i in splits]
        split_sorter = [sorter[i] if sorter is not None else None for i in splits]
        split_ret = [np.searchsorted(s_seq, b, side=side, sorter=s_sort) for (s_seq, b, s_sort) in zip(split_sequence, split_boundary, split_sorter, strict=True)]
        split_ret = [i.astype(np.int32) for i in split_ret] if out_int32 else split_ret
        return np.stack(split_ret).reshape(orig_shape)

def _basic_validation(op, args=(), kwargs=None):
    """
    Common validation across all ops go in here.
    """
    from torch.distributed._shard.sharded_tensor import ShardedTensor
    if len(args) == 0 and (kwargs is None or len(kwargs) == 0):
        raise ValueError(f" No input for '{op.__name__}'!")
    has_distributed_tensor = False

    def is_distributed_tensor(e):
        nonlocal has_distributed_tensor
        if <MASK>:
            has_distributed_tensor = True
    pytree.tree_map_(is_distributed_tensor, args)
    pytree.tree_map_(is_distributed_tensor, kwargs)
    if not has_distributed_tensor:
        raise TypeError(f"torch function '{op.__name__}', with args: {args} and kwargs: {kwargs} are called without any distributed tensor!")
    cur_pg: Optional[torch.distributed.ProcessGroup] = None

    def validate_pg(e):
        nonlocal cur_pg
        if isinstance(e, ShardedTensor):
            if cur_pg is not None and e._process_group is not cur_pg:
                raise RuntimeError('All distributed tensors should use the same ProcessGroup if used together in an op.')
            cur_pg = e._process_group
    pytree.tree_map_(validate_pg, args)
    pytree.tree_map_(validate_pg, kwargs)

def check_if_enable(test: unittest.TestCase):
    classname = str(test.__class__).split("'")[1].split('.')[-1]
    sanitized_testname = remove_device_and_dtype_suffixes(test._testMethodName)

    def matches_test(target: str):
        target_test_parts = target.split()
        if len(target_test_parts) < 2:
            return False
        target_testname = target_test_parts[0]
        target_classname = target_test_parts[1][1:-1].split('.')[-1]
        return classname.startswith(target_classname) and target_testname in (test._testMethodName, sanitized_testname)
    if any((matches_test(x) for x in slow_tests_dict.keys())):
        getattr(test, test._testMethodName).__dict__['slow_test'] = True
        if <MASK>:
            raise unittest.SkipTest('test is slow; run with PYTORCH_TEST_WITH_SLOW to enable test')
    if not IS_SANDCASTLE:
        should_skip = False
        skip_msg = ''
        for (disabled_test, (issue_url, platforms)) in disabled_tests_dict.items():
            if matches_test(disabled_test):
                platform_to_conditional: dict = {'mac': IS_MACOS, 'macos': IS_MACOS, 'win': IS_WINDOWS, 'windows': IS_WINDOWS, 'linux': IS_LINUX, 'rocm': TEST_WITH_ROCM, 'xpu': TEST_XPU, 'asan': TEST_WITH_ASAN, 'dynamo': TEST_WITH_TORCHDYNAMO, 'dynamo_wrapped': TEST_WITH_TORCHDYNAMO, 'inductor': TEST_WITH_TORCHINDUCTOR, 'slow': TEST_WITH_SLOW}
                invalid_platforms = list(filter(lambda p: p not in platform_to_conditional, platforms))
                if len(invalid_platforms) > 0:
                    invalid_plats_str = ', '.join(invalid_platforms)
                    valid_plats = ', '.join(platform_to_conditional.keys())
                    print(f'Test {disabled_test} is disabled for some unrecognized ', f'platforms: [{invalid_plats_str}]. Please edit issue {issue_url} to fix the platforms ', 'assigned to this flaky test, changing "Platforms: ..." to a comma separated ', f'subset of the following (or leave it blank to match all platforms): {valid_plats}')
                    platforms = list(filter(lambda p: p in platform_to_conditional, platforms))
                if platforms == [] or any((platform_to_conditional[platform] for platform in platforms)):
                    should_skip = True
                    skip_msg = f"Test is disabled because an issue exists disabling it: {issue_url} for {('all' if platforms == [] else '')}platform(s) {', '.join(platforms)}. If you're seeing this on your local machine and would like to enable this test, please make sure CI is not set and you are not using the flag --import-disabled-tests."
                    break
        if should_skip and (not RERUN_DISABLED_TESTS):
            raise unittest.SkipTest(skip_msg)
        if not should_skip and RERUN_DISABLED_TESTS:
            skip_msg = 'Test is enabled but --rerun-disabled-tests verification mode is set, so only disabled tests are run'
            raise unittest.SkipTest(skip_msg)
    if TEST_SKIP_FAST:
        if hasattr(test, test._testMethodName) and (not getattr(test, test._testMethodName).__dict__.get('slow_test', False)):
            raise unittest.SkipTest('test is fast; we disabled it with PYTORCH_TEST_SKIP_FAST')

def _unpool_output_size(input: Tensor, kernel_size: list[int], stride: list[int], padding: list[int], output_size: Optional[list[int]]) -> list[int]:
    input_size = input.size()
    default_size = torch.jit.annotate(list[int], [])
    for d in range(len(kernel_size)):
        default_size.append((input_size[-len(kernel_size) + d] - 1) * stride[d] + kernel_size[d] - 2 * padding[d])
    if output_size is None:
        ret = default_size
    else:
        if <MASK>:
            output_size = output_size[2:]
        if len(output_size) != len(kernel_size):
            raise ValueError(f"output_size should be a sequence containing {len(kernel_size)} or {len(kernel_size) + 2} elements, but it has a length of '{len(output_size)}'")
        for d in range(len(kernel_size)):
            min_size = default_size[d] - stride[d]
            max_size = default_size[d] + stride[d]
            if not min_size < output_size[d] < max_size:
                raise ValueError(f'invalid output_size "{output_size}" (dim {d} must be between {min_size} and {max_size})')
        ret = output_size
    return ret

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif <MASK>:
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
        if isinstance(idx, SymNodeVariable):
            const_idx = idx.evaluate_expr()
        else:
            const_idx = idx.as_python_constant()
        tx.output.side_effects.mutation(self)
        self.items.insert(const_idx, value)
        return ConstantVariable.create(None)
    elif name == 'pop' and self.is_mutable():
        if kwargs or len(args) > 1:
            raise_args_mismatch(tx, name, 'at most 1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if len(self.items) == 0:
            msg = ConstantVariable.create('pop from empty list')
            raise_observed_exception(IndexError, tx, args=[msg])
        if len(args):
            idx = args[0].as_python_constant()
            if idx > len(self.items):
                msg = ConstantVariable.create('pop index out of range')
                raise_observed_exception(IndexError, tx, args=[msg])
        tx.output.side_effects.mutation(self)
        return self.items.pop(*[a.as_python_constant() for a in args])
    elif name == 'clear' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        self.items.clear()
        return ConstantVariable.create(None)
    elif name == '__setitem__' and self.is_mutable() and args and (args[0].is_python_constant() or isinstance(args[0], SymNodeVariable) or (isinstance(args[0], SliceVariable) and all((s.is_python_constant() or isinstance(s, SymNodeVariable) for s in args[0].items)))):
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        (key, value) = args
        tx.output.side_effects.mutation(self)
        if isinstance(key, SymNodeVariable):
            self.items[key.evaluate_expr()] = value
        elif isinstance(key, SliceVariable):
            if key.is_python_constant():
                self.items[key.as_python_constant()] = list(value.items)
            else:
                items = slice(*[s.evaluate_expr() if isinstance(s, SymNodeVariable) else s.as_python_constant() for s in key.items])
                self.items[items] = list(value.items)
        else:
            self.items[key.as_python_constant()] = value
        return ConstantVariable.create(None)
    elif name == '__delitem__' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        if args[0].is_python_constant() and isinstance(args[0].as_python_constant(), (int, slice)):
            if isinstance(args[0], SymNodeVariable):
                idx = args[0].evaluate_expr()
            else:
                idx = args[0].as_python_constant()
            try:
                self.items.__delitem__(idx)
            except (IndexError, ValueError) as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            msg = ConstantVariable.create(f'list indices must be integers or slices, not {args[0].python_type_name()}')
            raise_observed_exception(TypeError, tx, args=[msg])
        return ConstantVariable.create(None)
    elif name == 'copy':
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        items = list(self.items)
        return self.modified(items, mutation_type=ValueMutationNew())
    elif name == 'reverse' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        self.items.reverse()
        tx.output.side_effects.mutation(self)
        return ConstantVariable.create(None)
    elif name == 'remove' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        idx = self.call_method(tx, 'index', args, kwargs)
        self.call_method(tx, 'pop', [idx], {})
        return ConstantVariable.create(None)
    else:
        return super().call_method(tx, name, args, kwargs)

def add_item_elements(self, handler, item):
    handler.addQuickElement('title', item['title'])
    handler.addQuickElement('link', item['link'])
    if item['description'] is not None:
        handler.addQuickElement('description', item['description'])
    if item['author_name'] and item['author_email']:
        handler.addQuickElement('author', '%s (%s)' % (item['author_email'], item['author_name']))
    elif item['author_email']:
        handler.addQuickElement('author', item['author_email'])
    elif <MASK>:
        handler.addQuickElement('dc:creator', item['author_name'], {'xmlns:dc': 'http://purl.org/dc/elements/1.1/'})
    if item['pubdate'] is not None:
        handler.addQuickElement('pubDate', rfc2822_date(item['pubdate']))
    if item['comments'] is not None:
        handler.addQuickElement('comments', item['comments'])
    if item['unique_id'] is not None:
        guid_attrs = {}
        if isinstance(item.get('unique_id_is_permalink'), bool):
            guid_attrs['isPermaLink'] = str(item['unique_id_is_permalink']).lower()
        handler.addQuickElement('guid', item['unique_id'], guid_attrs)
    if item['ttl'] is not None:
        handler.addQuickElement('ttl', item['ttl'])
    if item['enclosures']:
        enclosures = list(item['enclosures'])
        if len(enclosures) > 1:
            raise ValueError('RSS feed items may only have one enclosure, see http://www.rssboard.org/rss-profile#element-channel-item-enclosure')
        enclosure = enclosures[0]
        handler.addQuickElement('enclosure', '', {'url': enclosure.url, 'length': enclosure.length, 'type': enclosure.mime_type})
    for cat in item['categories']:
        handler.addQuickElement('category', cat)

def _copy_layer(layer):
    if layer in input_layers:
        created_layers[layer.name] = input_layers[layer]
    elif <MASK>:
        created_layers[layer.name] = InputLayer(**layer.get_config())
    else:
        created_layers[layer.name] = layer_fn(layer)
    return {}

def choices(self, changelist):
    add_facets = changelist.add_facets
    facet_counts = self.get_facet_queryset(changelist) if add_facets else None
    yield {'selected': self.lookup_val is None and self.lookup_val_isnull is None, 'query_string': changelist.get_query_string(remove=[self.lookup_kwarg, self.lookup_kwarg_isnull]), 'display': _('All')}
    include_none = False
    count = None
    empty_title = self.empty_value_display
    for (i, val) in enumerate(self.lookup_choices):
        if add_facets:
            count = facet_counts[f'{i}__c']
        if val is None:
            include_none = True
            empty_title = f'{empty_title} ({count})' if add_facets else empty_title
            continue
        val = str(val)
        yield {'selected': self.lookup_val is not None and val in self.lookup_val, 'query_string': changelist.get_query_string({self.lookup_kwarg: val}, [self.lookup_kwarg_isnull]), 'display': f'{val} ({count})' if add_facets else val}
    if <MASK>:
        yield {'selected': bool(self.lookup_val_isnull), 'query_string': changelist.get_query_string({self.lookup_kwarg_isnull: 'True'}, [self.lookup_kwarg]), 'display': empty_title}

def call(self, gm: torch.fx.GraphModule) -> Optional[PassResult]:

    def get_arg_spec(arg) -> Union[TensorArgument, ConstantArgument]:
        if isinstance(arg, torch.fx.Node):
            if isinstance(arg.meta.get('val'), torch.Tensor):
                return TensorArgument(name=arg.name)
            else:
                raise AssertionError('Symint input is not implemented yet for submodule call signature.')
        else:
            return ConstantArgument(name='', value=arg)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        nn_module_stack = None
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if <MASK>:
                kind = node.kwargs['kind']
                if kind == 'module_call_outputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_inputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None
        nn_module_stack = None
        for node in reversed(module.graph.nodes):
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_inputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_outputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None

    def copy_sig(sig) -> ModuleCallSignature:
        from torch.export.exported_program import ModuleCallSignature
        return ModuleCallSignature(inputs=[], outputs=[], in_spec=sig.in_spec, out_spec=sig.out_spec, forward_arg_names=None)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                path = node.kwargs['path']
                (fqn, _) = next(reversed(node.meta['nn_module_stack'].values()))
                module_key = next(reversed(node.meta['nn_module_stack']))
                if '@' in module_key:
                    suffix = module_key.split('@')[-1]
                    path = f'{path}@{suffix}'
                    call_fqn = f'{fqn}@{suffix}'
                    if call_fqn not in self.specs:
                        self.specs[call_fqn] = copy_sig(self.specs[fqn])
                    fqn = call_fqn
                kind = node.kwargs['kind']
                for (i, arg) in enumerate(node.args):
                    if fqn == path:
                        if kind == 'module_call_inputs':
                            self.specs[path].inputs.append(get_arg_spec(arg))
                        elif kind == 'module_call_outputs':
                            self.specs[path].outputs.append(get_arg_spec(arg))
                        else:
                            raise AssertionError(f'Unknown tracepoint kind: {kind}')
                    if isinstance(arg, torch.fx.Node):
                        for user in node.users:
                            assert user.op == 'call_function'
                            assert user.target == operator.getitem
                            assert isinstance(user.args[1], int)
                            if user.args[1] == i:
                                user.replace_all_uses_with(arg)
                                self.sig.replace_all_uses(user.name, arg.name)
                                break
                users = list(node.users)
                for user in users:
                    assert len(user.users) == 0
                    gm.graph.erase_node(user)
                gm.graph.erase_node(node)
        return PassResult(gm, True)
    return None

def _create_flatten_mesh(self, mesh_dim_name: Optional[str]=None, backend_override: BackendConfig=(None, None)) -> 'DeviceMesh':
    root_mesh = self._get_root_mesh()
    if not mesh_dim_name:
        mesh_dim_name = '_'.join(not_none(self._mesh_dim_names))
    if self.ndim == 1 and mesh_dim_name in not_none(self._mesh_dim_names):
        return self
    invalid_dim_names = not_none(root_mesh._mesh_dim_names)
    if mesh_dim_name in invalid_dim_names:
        raise ValueError(f'{mesh_dim_name} already exists for submesh of the {root_mesh}. ', f'The mesh_dim_names of submesh and flattened mesh are {invalid_dim_names}. Please specify another valid mesh_dim_name.')
    flattened_mesh_layout = self._layout.coalesce()
    if len(flattened_mesh_layout) > 1:
        flattened_mesh_layout = flattened_mesh_layout.nest()
    if <MASK>:
        if flattened_mesh_layout == root_mesh._flatten_mapping[mesh_dim_name]._layout:
            return root_mesh._flatten_mapping[mesh_dim_name]
        else:
            raise ValueError(f'Flatten mesh with mesh_dim_name {mesh_dim_name} has been created before, Please specify another valid mesh_dim_name.')
    res_flattened_mesh = DeviceMesh(root_mesh._device_type, _layout=flattened_mesh_layout, _rank_map=root_mesh._rank_map, mesh_dim_names=(mesh_dim_name,), _root_mesh=root_mesh, backend_override=(backend_override,))
    root_mesh._flatten_mapping[mesh_dim_name] = res_flattened_mesh
    return res_flattened_mesh

def linear_permute_fusion(module: torch.fx.GraphModule) -> torch.fx.GraphModule:
    for node in module.graph.find_nodes(op='call_method', target='permute'):
        if <MASK>:
            if len(node.args) > 0:
                input_node = node.args[0]
            else:
                input_node = node.kwargs['input']
            if input_node.op == 'call_function' and input_node.target == torch.nn.functional.linear:
                normalized = NormalizedLinearNode(input_node)
                input = normalized.get_input()
                weight = normalized.get_weight()
                bias = normalized.get_bias()
                with module.graph.inserting_before(node):
                    fused_node = module.graph.call_function(linear_transpose, args=(input, weight, bias))
                    node.replace_all_uses_with(fused_node)
                    module.graph.erase_node(node)
                    if len(input_node.users) == 0:
                        module.graph.erase_node(input_node)
    module.graph.lint()
    module.recompile()
    return module

def exposed_communication_time(collective_snode: BaseSchedulerNode, remaining_snodes: list[BaseSchedulerNode]) -> float:
    comm_time = estimate_op_runtime(collective_snode)
    compute_time = 0.0
    for snode in remaining_snodes:
        if contains_collective(snode):
            continue
        if <MASK>:
            break

        def accumulate_time(_snode: BaseSchedulerNode) -> None:
            nonlocal compute_time
            compute_time += runtimes[_snode]
        _temp_group_visit_leaves(snode, accumulate_time)
    return max(0, comm_time - compute_time)

def register_comm_lowerings():
    try:
        torch.ops._c10d_functional.all_reduce
    except AttributeError:
        log.info('Inductor support for distributed collectives depends on building torch.distributed')
        return
    from .lowering import add_layout_constraint, clone, constrain_to_fx_strides, copy_, register_lowering

    def register_comm_lowering(fn):
        add_layout_constraint(fn, constrain_to_fx_strides)
        return register_lowering(fn)
    c10d = torch.ops._c10d_functional

    @register_comm_lowering(c10d.all_reduce)
    def _all_reduce(inp: ir.TensorBox, reduce_op: str, group_name: str) -> ir.TensorBox:
        if _should_lower_as_one_shot_all_reduce(inp, reduce_op, group_name):
            return _one_shot_all_reduce(inp, reduce_op, group_name)
        inp = clone(inp)
        if <MASK>:
            inp.realize()
            V.graph.no_fuse_buffer_names.add(inp.get_name())
        inp = ir.ExternKernel.require_contiguous(inp)
        ir._AllReduce_Kernel.create_inplace(c10d.all_reduce_.default, inp, reduce_op, group_name)
        return inp

    @register_comm_lowering(c10d.all_reduce_)
    def _all_reduce_(inp: ir.TensorBox, reduce_op: str, group_name: str) -> ir.TensorBox:
        if _should_lower_as_one_shot_all_reduce(inp, reduce_op, group_name):
            ret = copy_(inp, _one_shot_all_reduce(inp, reduce_op, group_name))
            mark_as_skip_wait(ret)
            return inp
        inp = ir.ExternKernel.require_contiguous(inp)
        ir._AllReduce_Kernel.create_inplace(c10d.all_reduce_.default, inp, reduce_op, group_name)
        return inp

    @register_comm_lowering(c10d.all_reduce_coalesced)
    def _all_reduce_coalesced(inputs, reduce_op, group_name):
        inputs = [clone(inp) for inp in inputs]
        ir._CollectiveKernel.create_inplace(c10d.all_reduce_coalesced_.default, inputs, reduce_op, group_name)
        return inputs

    @register_comm_lowering(c10d.all_reduce_coalesced_)
    def _all_reduce_coalesced_(inputs, reduce_op, group_name):
        ir._CollectiveKernel.create_inplace(c10d.all_reduce_coalesced_.default, inputs, reduce_op, group_name)
        return inputs

    def _create_out_of_place(kernel, inputs, *args) -> ir.IRNode:
        node = ir._CollectiveKernel.create_out_of_place(kernel, inputs, *args)
        assert isinstance(node, ir.IRNode)
        return ir.TensorBox.create(node)

    @register_comm_lowering(c10d.all_gather_into_tensor)
    def _all_gather_into_tensor(inp, group_size, group_name):
        return _create_out_of_place(c10d.all_gather_into_tensor.default, inp, group_size, group_name)

    @register_comm_lowering(c10d.all_gather_into_tensor_coalesced)
    def _all_gather_into_tensor_coalesced(inputs, group_size, group_name):
        return pytree.tree_map(ir.TensorBox.create, ir._CollectiveKernel.create_out_of_place(c10d.all_gather_into_tensor_coalesced.default, inputs, group_size, group_name))

    @register_comm_lowering(c10d.all_gather_into_tensor_out)
    def _all_gather_into_tensor_out(inp, group_size, group_name, *, out):
        ir._CollectiveKernel.create_inplace(c10d.all_gather_into_tensor_out.default, inp, group_size, group_name, out=out)
        return out

    @register_comm_lowering(c10d.reduce_scatter_tensor)
    def _reduce_scatter_tensor(inp, reduce_op, group_size, group_name):
        return _create_out_of_place(c10d.reduce_scatter_tensor.default, inp, reduce_op, group_size, group_name)

    @register_comm_lowering(c10d.reduce_scatter_tensor_coalesced)
    def _reduce_scatter_tensor_coalesced(inputs, reduce_op, group_size, group_name):
        return pytree.tree_map(ir.TensorBox.create, ir._CollectiveKernel.create_out_of_place(c10d.reduce_scatter_tensor_coalesced.default, inputs, reduce_op, group_size, group_name))

    @register_comm_lowering(c10d.all_to_all_single)
    def _all_to_all_single(inp, output_split_sizes, input_split_sizes, group_name):
        return _create_out_of_place(c10d.all_to_all_single.default, inp, output_split_sizes, input_split_sizes, group_name)

    @register_comm_lowering(c10d.broadcast)
    def _broadcast(inp, src, group_name):
        inp = clone(inp)
        ir._CollectiveKernel.create_inplace(c10d.broadcast_.default, inp, src, group_name)
        return inp

    @register_comm_lowering(c10d.broadcast_)
    def _broadcast_(inp, src, group_name):
        ir._CollectiveKernel.create_inplace(c10d.broadcast_.default, inp, src, group_name)
        return inp

    @register_comm_lowering(torch.ops._dtensor.shard_dim_alltoall)
    def _shard_dim_alltoall(inp, gather_dim, shard_dim, group_name):
        return _create_out_of_place(torch.ops._dtensor.shard_dim_alltoall.default, inp, gather_dim, shard_dim, group_name)

    @register_comm_lowering(c10d.wait_tensor)
    def _wait_tensor(inp):
        if should_skip_wait(inp):
            return inp
        ir._WaitKernel.create_wait(c10d.wait_tensor.default, inp)
        return inp

@register_make_test_function()
def make_expand_dims_tests(options):
    """Make a set of tests to do expand_dims."""
    test_parameters = [{'input_type': [tf.float32, tf.int32], 'input_shape': [[5, 4], [1, 5, 4]], 'axis_value': [0, 1, 2, -1, -2, -3], 'constant_axis': [True, False], 'fully_quantize': [False]}, {'input_type': [tf.float32], 'input_shape': [[5, 4], [1, 5, 4]], 'axis_value': [0, 1, 2, -1, -2, -3], 'constant_axis': [True], 'fully_quantize': [True]}]

    def build_graph(parameters):
        """Build the where op testing graph."""
        inputs = []
        input_value = tf.compat.v1.placeholder(dtype=parameters['input_type'], name='input', shape=parameters['input_shape'])
        inputs.append(input_value)
        if <MASK>:
