@functools.wraps(func)
def wrap_generator(*args, **kwargs):
    gen = func(*args, **kwargs)
    datapipe = args[0]
    if datapipe._fast_forward_iterator:
        it = datapipe._fast_forward_iterator
        datapipe._fast_forward_iterator = None
        datapipe._snapshot_state = _SnapshotState.Iterating
        while True:
            try:
                yield next(it)
            except StopIteration:
                return
    iterator_id = _set_datapipe_valid_iterator_id(datapipe)
    _profiler_enabled = torch.autograd._profiler_enabled()
    try:
        if _profiler_enabled:
            with profiler_record_fn_context(datapipe):
                response = gen.send(None)
        else:
            response = gen.send(None)
        while True:
            datapipe._number_of_samples_yielded += 1
            request = (yield response)
            if _profiler_enabled:
                with profiler_record_fn_context(datapipe):
                    _check_iterator_valid(datapipe, iterator_id)
                    response = gen.send(request)
            else:
                _check_iterator_valid(datapipe, iterator_id)
                response = gen.send(request)
    except StopIteration:
        return
    except Exception as e:
        datapipe = args[0]
        msg = 'thrown by __iter__ of'
        single_iterator_msg = 'single iterator per IterDataPipe constraint'
        if hasattr(e.args, '__len__'):
            full_msg = f'{msg} {datapipe.__class__.__name__}({_generate_input_args_string(datapipe)})'
            if <MASK>:
                e.args = (f'\nThis exception is {full_msg}',)
            elif msg not in e.args[0] and single_iterator_msg not in e.args[0]:
                e.args = (e.args[0] + f'\nThis exception is {full_msg}',) + e.args[1:]
        raise

def AddOp(self, op: ops.Operation):
    """Add `op` to the current context."""
    if not util.IsInXLAContext(op) and op.type in {'Shape', 'Size', 'Rank'}:
        grad_ctxt = ops.get_default_graph()._get_control_flow_context()
        if <MASK>:
            grad_ctxt = grad_ctxt.GetWhileContext()
            if grad_ctxt.grad_state:
                op_input_forward_ctxt = util.GetWhileContext(op.inputs[0].op)
                if op_input_forward_ctxt == grad_ctxt.grad_state.forward_context:
                    op_input_ctxt = op.inputs[0].op._get_control_flow_context()
                    op._set_control_flow_context(op_input_ctxt)
                    op_input_ctxt._AddOpInternal(op)
                    return
    self._AddOpInternal(op)

def _local_reduce(reduce_op: ReduceOp, tensors: list[torch.Tensor]) -> torch.Tensor:
    if reduce_op == ReduceOp.SUM:
        op = operator.add
    elif reduce_op == ReduceOp.AVG:
        op = None
    elif reduce_op == ReduceOp.PRODUCT:
        op = operator.mul
    elif reduce_op == ReduceOp.MIN:
        op = torch.minimum
    elif reduce_op == ReduceOp.MAX:
        op = torch.maximum
    elif reduce_op == ReduceOp.BAND:
        op = torch.bitwise_and
    elif <MASK>:
        op = torch.bitwise_or
    elif reduce_op == ReduceOp.BXOR:
        op = torch.bitwise_xor
    elif reduce_op == ReduceOp.PREMUL_SUM:
        raise NotImplementedError('PREMUL_SUM: need to add binding for scaling factor')
    else:
        raise NotImplementedError(f'ReduceOp {reduce_op} not implemented')
    if reduce_op == ReduceOp.AVG:
        return functools.reduce(operator.add, tensors) / len(tensors)
    else:
        assert op is not None
        return functools.reduce(op, tensors)

@final
def putmask(self, mask, new) -> list[Block]:
    """
        See Block.putmask.__doc__
        """
    mask = extract_bool_array(mask)
    if new is lib.no_default:
        new = self.fill_value
    orig_new = new
    orig_mask = mask
    new = self._maybe_squeeze_arg(new)
    mask = self._maybe_squeeze_arg(mask)
    if not mask.any():
        return [self.copy(deep=False)]
    self = self._maybe_copy(inplace=True)
    values = self.values
    if values.ndim == 2:
        values = values.T
    try:
        values._putmask(mask, new)
    except OutOfBoundsDatetime:
        raise
    except (TypeError, ValueError):
        if self.ndim == 1 or self.shape[0] == 1:
            if <MASK>:
                blk = self.coerce_to_target_dtype(orig_new, raise_on_upcast=True)
                return blk.putmask(orig_mask, orig_new)
            elif isinstance(self, NDArrayBackedExtensionBlock):
                blk = self.coerce_to_target_dtype(orig_new, raise_on_upcast=True)
                return blk.putmask(orig_mask, orig_new)
            else:
                raise
        else:
            is_array = isinstance(orig_new, (np.ndarray, ExtensionArray))
            res_blocks = []
            for (i, nb) in enumerate(self._split()):
                n = orig_new
                if is_array:
                    n = orig_new[:, i:i + 1]
                submask = orig_mask[:, i:i + 1]
                rbs = nb.putmask(submask, n)
                res_blocks.extend(rbs)
            return res_blocks
    return [self]

