def check(self, **kwargs):
    errors = super().check(**kwargs)
    if self.base_field.remote_field:
        errors.append(checks.Error('Base field for array cannot be a related field.', obj=self, id='postgres.E002'))
    else:
        base_checks = self.base_field.check()
        if base_checks:
            error_messages = '\n    '.join(('%s (%s)' % (base_check.msg, base_check.id) for base_check in base_checks if isinstance(base_check, checks.Error) and (not base_check.id == 'postgres.E005')))
            if <MASK>:
                errors.append(checks.Error('Base field for array has errors:\n    %s' % error_messages, obj=self, id='postgres.E001'))
            warning_messages = '\n    '.join(('%s (%s)' % (base_check.msg, base_check.id) for base_check in base_checks if isinstance(base_check, checks.Warning)))
            if warning_messages:
                errors.append(checks.Warning('Base field for array has warnings:\n    %s' % warning_messages, obj=self, id='postgres.W004'))
    return errors

def _pull_field(js: dict[str, Any], spec: list | str, extract_record: bool=False) -> Scalar | Iterable:
    """Internal function to pull field"""
    result = js
    try:
        if isinstance(spec, list):
            for field in spec:
                if <MASK>:
                    raise KeyError(field)
                result = result[field]
        else:
            result = result[spec]
    except KeyError as e:
        if extract_record:
            raise KeyError(f'Key {e} not found. If specifying a record_path, all elements of data should have the path.') from e
        if errors == 'ignore':
            return np.nan
        else:
            raise KeyError(f"Key {e} not found. To replace missing values of {e} with np.nan, pass in errors='ignore'") from e
    return result

def _reduction_identity(op_name: str, input: Tensor, *args):
    """Return identity value as scalar tensor of a reduction operation on
    given input, or None, if the identity value cannot be uniquely
    defined for the given input.

    The identity value of the operation is defined as the initial
    value to reduction operation that has a property ``op(op_identity,
    value) == value`` for any value in the domain of the operation.
    Or put it another way, including or excluding the identity value in
    a list of operands will not change the reduction result.

    See https://github.com/pytorch/rfcs/pull/27 for more information.

    """
    dtype: DType = input.dtype
    device = input.device
    op_name = op_name.rsplit('.', 1)[-1]
    if op_name in {'sum', 'cumsum'}:
        return torch.tensor(0, dtype=dtype, device=device)
    elif op_name in {'prod', 'cumprod'}:
        return torch.tensor(1, dtype=dtype, device=device)
    elif op_name in {'amax', 'argmax', 'logaddexp'}:
        if <MASK>:
            return torch.tensor(-torch.inf, dtype=dtype, device=device)
        elif torch.is_signed(input) or dtype == torch.uint8:
            return torch.tensor(torch.iinfo(dtype).min, dtype=dtype, device=device)
    elif op_name == 'logsumexp':
        if torch.is_floating_point(input):
            return torch.tensor(-torch.inf, dtype=dtype, device=device)
        elif torch.is_complex(input):
            return torch.tensor(-torch.inf + 0j, dtype=dtype, device=device)
        elif torch.is_signed(input) or dtype == torch.uint8:
            return torch.tensor(torch.iinfo(dtype).min, dtype=dtype, device=device)
    elif op_name in {'amin', 'argmin'}:
        if torch.is_floating_point(input):
            return torch.tensor(torch.inf, dtype=dtype, device=device)
        elif torch.is_signed(input) or dtype == torch.uint8:
            return torch.tensor(torch.iinfo(dtype).max, dtype=dtype, device=device)
    elif op_name == 'mean':
        return None
    elif op_name == 'norm':
        ord = args[0] if args else 2
        if ord == float('-inf'):
            assert torch.is_floating_point(input), input.dtype
            return torch.tensor(torch.inf, dtype=dtype, device=device)
        return torch.tensor(0, dtype=dtype, device=device)
    elif op_name == 'median':
        dtype = input.dtype if torch.is_floating_point(input) else torch.float
        return torch.tensor(torch.nan, dtype=dtype, device=device)
    elif op_name in {'var', 'std'}:
        return None
    raise NotImplementedError(f'identity of {op_name} on {dtype} input')

def __init__(self, func, role='func', doc=None, config=None):
    self._f = func
    self._role = role
    if <MASK>:
        if func is None:
            raise ValueError('No function or docstring given')
        doc = inspect.getdoc(func) or ''
    if config is None:
        config = {}
    NumpyDocString.__init__(self, doc, config)

def _default(self, name: str, args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
    val = getattr(self._inner, name)(*args, **kwargs)
    if <MASK>:
        return val
    return f'({val})'

def custom_op_wrapper(op: str, *args: Any) -> list[c_void_p] | c_void_p | None:

    def convert_arg(arg: Any) -> Any:
        if <MASK>:
            return torch._C._aoti.alloc_tensor_by_stealing_from_void_ptr(arg)
        elif isinstance(arg, (list, tuple)):
            return type(arg)((convert_arg(a) for a in arg))
        else:
            return arg
    converted_args = [convert_arg(arg) for arg in args]
    assert op.startswith('torch.ops.'), op + ' can not be called through custom_op_wrapper'
    func = None
    for (i, s) in enumerate(op.split('.')):
        if i == 0:
            func = importlib.import_module(s)
        func = getattr(func, s)
    assert callable(func), op + ' can not be loaded through custom_op_wrapper'
    kwargs = dict()
    for (func_arg, conv_arg) in zip(func._schema.arguments, converted_args):
        if func_arg.kwarg_only:
            kwargs[func_arg.name] = conv_arg
    if kwargs:
        del converted_args[-len(kwargs):]
    result = func(*converted_args, **kwargs)
    if result is None:
        return None
    if isinstance(result, (list, tuple)):
        result = [torch.tensor([]) if r is None else r for r in result]
        for (i, r) in enumerate(result):
            assert isinstance(r, torch.Tensor), op + ' returns a list of non-tensors'
        return torch._C._aoti.unsafe_alloc_void_ptrs_from_tensors(result)
    assert isinstance(result, torch.Tensor), op + ' returns a non-tensor'
    return torch._C._aoti.unsafe_alloc_void_ptr_from_tensor(result)

@final
def _compute_plot_data(self) -> None:
    data = self.data
    if self.by is not None:
        self.subplots = True
        data = reconstruct_data_with_by(self.data, by=self.by, cols=self.columns)
    data = data.infer_objects()
    include_type = [np.number, 'datetime', 'datetimetz', 'timedelta']
    if self.include_bool is True:
        include_type.append(np.bool_)
    exclude_type = None
    if self._kind == 'box':
        include_type = [np.number]
        exclude_type = ['timedelta']
    if self._kind == 'scatter':
        include_type.extend(['object', 'category', 'string'])
    numeric_data = data.select_dtypes(include=include_type, exclude=exclude_type)
    is_empty = numeric_data.shape[-1] == 0
    if <MASK>:
        raise TypeError('no numeric data to plot')
    self.data = numeric_data.apply(type(self)._convert_to_ndarray)

def dataset_fn(count=5, buffer_size=None, seed=0):
    repeat_dataset = dataset_ops.Dataset.from_tensor_slices(components).repeat(count)
    if <MASK>:
        shuffle_dataset = repeat_dataset.shuffle(buffer_size, seed)
        self.assertEqual(tuple([c.shape[1:] for c in components]), dataset_ops.get_legacy_output_shapes(shuffle_dataset))
        return shuffle_dataset
    else:
        return repeat_dataset

