def parse_readable_time_str(time_str):
    """Parses a time string in the format N, Nus, Nms, Ns.

  Args:
    time_str: (`str`) string consisting of an integer time value optionally
      followed by 'us', 'ms', or 's' suffix. If suffix is not specified,
      value is assumed to be in microseconds. (e.g. 100us, 8ms, 5s, 100).

  Returns:
    Microseconds value.
  """

    def parse_positive_float(value_str):
        value = float(value_str)
        if value < 0:
            raise ValueError('Invalid time %s. Time value must be positive.' % value_str)
        return value
    time_str = time_str.strip()
    if time_str.endswith('us'):
        return int(parse_positive_float(time_str[:-2]))
    elif <MASK>:
        return int(parse_positive_float(time_str[:-2]) * 1000.0)
    elif time_str.endswith('s'):
        return int(parse_positive_float(time_str[:-1]) * 1000000.0)
    return int(parse_positive_float(time_str))

@register_lowering(quantized_decomposed.dequantize_per_tensor.tensor, type_promotion_kind=None)
def quantized_decomposed_dequantize_per_tensor_tensor(input: TensorBox, scale: TensorBox, zero_point: TensorBox, quant_min: int, quant_max: int, dtype: torch.dtype, *, out_dtype: Optional[torch.dtype]=None) -> Union[TensorBox, ShapeAsConstantBuffer]:
    assert len(scale.get_size()) == 0 or (len(scale.get_size()) == 1 and scale.get_size()[0] == 1), 'expect scale as scalar tensor'
    assert len(zero_point.get_size()) == 0 or (len(zero_point.get_size()) == 1 and zero_point.get_size()[0] == 1), 'expect zero_point as scalar tensor'
    assert input.get_dtype() == dtype, f'Expecting input to have dtype {dtype}, but got dtype: {input.get_dtype()}'
    if out_dtype is None:
        out_dtype = torch.float32
    input_loader = input.make_loader()
    scale_loader = scale.make_loader()
    zero_point_loader = zero_point.make_loader()

    def inner_fn(idx):
        input = input_loader(idx)
        _scale = scale_loader((0,) if len(scale.get_size()) == 1 else ())
        _zero_point = zero_point_loader((0,) if len(scale.get_size()) == 1 else ())
        if scale.dtype != torch.float32:
            _scale = ops.to_dtype(_scale, torch.float32)
        if <MASK>:
            _zero_point = ops.to_dtype(_zero_point, torch.float32)
        val = ops.sub(ops.to_dtype(input, torch.float32), _zero_point) * _scale
        val = ops.to_dtype(val, out_dtype)
        return val
    return Pointwise.create(device=input.get_device(), dtype=out_dtype, inner_fn=inner_fn, ranges=input.get_size())

def log_instant_event(self, event_name: str, time_ns: int, metadata: Optional[dict[str, Any]]=None, log_pt2_compile_event: bool=False) -> None:
    """
        Log an instant event with no associated duration.
        :param str event_name: Name of event to appear in trace
        :param int time_ns Timestamp in nanoseconds
        :param Optional[Dict[str, Any]] metadata: Any extra metadata associated with this event
        :param str cname optional color for the arrow in the trace
        """
    if <MASK>:
        metadata = {}
    compile_id = str(torch._guards.CompileContext.current_compile_id())
    metadata['compile_id'] = compile_id
    event = {'name': event_name, 'ts': time_ns / 1000, 'args': metadata, 'ph': 'i', 'cat': 'dynamo_timed', 'tid': 0, 'pid': 0, 's': 'p'}
    torch._logging.trace_structured('chromium_event', payload_fn=lambda : event, suppress_context=False, expect_trace_id=True)
    if log_pt2_compile_event:
        log_chromium_event_internal(event, self.get_pt2_compile_substack(), self.id_, time_ns)

def gen_returns(schema: FunctionSchema) -> tuple[list[str], list[str]]:
    types = []
    names = []
    for (idx, ret) in enumerate(schema.returns):
        names.append(f'ret{idx}')
        if <MASK>:
            types.append(base_type_to_c_type[ret.type.name] + '*')
        else:
            raise NotImplementedError(f'TODO: add support for return type {repr(ret.type)}')

    def convert_return(typ: BaseType, val: str) -> str:
        if typ.name == BaseTy.Tensor:
            return f'new_tensor_handle(std::move({val}))'
        elif typ.name == BaseTy.SymInt:
            return f'{val}.expect_int()'
        elif typ.name == BaseTy.Scalar:
            return f'{val}.toDouble()'
        else:
            return val
    ret_pointer_can_be_null = False
    unambiguous_name = schema.name.unambiguous_name()
    for name in ('_functional_sym_constrain_range', '_scaled_dot_product_cudnn_attention', '_scaled_dot_product_efficient_attention_backward', '_scaled_dot_product_efficient_attention', '_scaled_dot_product_flash_attention', '_scaled_dot_product_fused_attention_overrideable', '_thhn_fused_lstm_cell_backward_impl', 'convolution_backward', 'grid_sampler_2d_backward', 'grid_sampler_3d_backward', 'linear_backward'):
        if name in unambiguous_name:
            ret_pointer_can_be_null = True
            break
    callsite_exprs: list[str] = []
    for (idx, ret) in enumerate(schema.returns):
        tmp = 'tmp_result' if len(names) == 1 else f'std::get<{idx}>(tmp_result)'
        assert isinstance(ret.type, BaseType)
        rval = convert_return(ret.type, tmp)
        if ret_pointer_can_be_null:
            callsite_exprs.append(f'if ({names[idx]}) {{ *{names[idx]} = {rval}; }}')
        else:
            callsite_exprs.append(f'*{names[idx]} = {rval};')
    return (zip_type_and_name(types, names), callsite_exprs)

def _GetSelfAdjointEigGradTest(dtype_, shape_, compute_v_):

    def Test(self):
        np.random.seed(1)
        n = shape_[-1]
        batch_shape = shape_[:-2]
        np_dtype = dtype_.as_numpy_dtype

        def RandomInput():
            a = np.random.uniform(low=-1.0, high=1.0, size=n * n).reshape([n, n]).astype(np_dtype)
            if dtype_.is_complex:
                a += 1j * np.random.uniform(low=-1.0, high=1.0, size=n * n).reshape([n, n]).astype(np_dtype)
            a += np.conj(a.T)
            a = np.tile(a, batch_shape + (1, 1))
            return a
        epsilon = np.finfo(np_dtype).eps
        delta = 0.1 * epsilon ** (1.0 / 3.0)
        _ = RandomInput()
        if <MASK>:
            tol = 0.02
        else:
            tol = 1e-07
        with self.session():

            def Compute(x):
                (e, v) = linalg_ops.self_adjoint_eig(x)
                top_rows = v[..., 0:1, :]
                if dtype_.is_complex:
                    angle = -math_ops.angle(top_rows)
                    phase = math_ops.complex(math_ops.cos(angle), math_ops.sin(angle))
                else:
                    phase = math_ops.sign(top_rows)
                v *= phase
                return (e, v)
            if compute_v_:
                funcs = [lambda x: Compute(x)[0], lambda x: Compute(x)[1]]
            else:
                funcs = [linalg_ops.self_adjoint_eigvals]
            for f in funcs:
                (theoretical, numerical) = gradient_checker_v2.compute_gradient(f, [RandomInput()], delta=delta)
                self.assertAllClose(theoretical, numerical, atol=tol, rtol=tol)
    return Test

