        return Collective(id=id, group_id=self.pg_name, record_id=self.record_id, pg_desc=self.pg_desc, pass_check=False, collective_seq_id=self.collective_seq_id, p2p_seq_id=self.p2p_seq_id, collective_name=self.profiling_name, input_sizes=self.input_sizes, output_sizes=self.output_sizes, expected_ranks=self.expected_ranks, collective_state=self.collective_state, collective_frames=self.collective_frames, input_numel=self.input_numel if hasattr(self, 'input_numel') else None, output_numel=self.output_numel if hasattr(self, 'output_numel') else None, missing_ranks=self.missing_ranks if hasattr(self, 'missing_ranks') else None, mismatch_collectives=mismatch_collectives)

def _finalize_mm_configs(self, configs: list[BaseConfig]) -> Generator[TritonConfig, None, None]:
    """
        Finalizes configs after scaling, applying additional constraints.
        """
    used: OrderedSet[tuple[Optional[int], ...]] = OrderedSet()
    max_mm_configs = config.test_configs.max_mm_configs
    for conf in configs:
        num_warps = min(conf.num_warps, conf.block_m * conf.block_n // 256)
        key: tuple[Optional[int], ...] = (conf.block_m, conf.block_n, conf.block_k, conf.num_stages, conf.hint_override, num_warps)
        group_m = getattr(conf, 'group_m', None)
        if <MASK>:
            key += (group_m,)
        if key not in used and (max_mm_configs is None or len(used) < max_mm_configs):
            used.add(key)
            kwargs = {'BLOCK_M': conf.block_m, 'BLOCK_N': conf.block_n, 'BLOCK_K': conf.block_k, 'hint_override': conf.hint_override}
            if group_m is not None:
                kwargs['GROUP_M'] = group_m
            yield self.triton_config(conf.num_stages, num_warps, **kwargs)

