def _comparison_with_tensor(self, tx: 'InstructionTranslator', left, right):
    from .builder import wrap_fx_proxy_cls
    from .tensor import supported_tensor_comparison_op_values
    op = self.fn
    if op in [operator.is_, operator.is_not]:
        is_result = isinstance(left, TensorVariable) and isinstance(right, TensorVariable) and (id(extract_fake_example_value(left.as_proxy().node)) == id(extract_fake_example_value(right.as_proxy().node)))
        if <MASK>:
            return ConstantVariable.create(is_result)
        else:
            return ConstantVariable.create(not is_result)
    if op not in supported_tensor_comparison_op_values:
        unimplemented_v2(gb_type='unsupported Tensor comparison op', context=f'{op.__name__}({left}, {right})', explanation=f'Dynamo does not support the comparison op {op.__name__} with Tensor arguments {left}, {right}', hints=[*graph_break_hints.SUPPORTABLE])
    if isinstance(left, TensorVariable) and isinstance(right, TensorVariable) and ((left.size and right.size) is not None) and (left.size != right.size):
        try:
            torch.broadcast_shapes(left.size, right.size)
        except RuntimeError:
            unimplemented_v2(gb_type='failed to broadcast when attempting Tensor comparison op', context=f'{op.__name__}({left}, {right})', explanation=f'Dynamo was unable to broad cast the arguments {left}, {right} when attempting to trace the comparison op {op.__name__}.', hints=[*graph_break_hints.USER_ERROR])
    tensor_cls = left if isinstance(left, TensorVariable) else right
    proxy = tx.output.create_proxy('call_function', op, (left.as_proxy(), right.as_proxy()), {})
    return wrap_fx_proxy_cls(type(tensor_cls), tx, proxy)

