def _verify_input_symbol_assignment(value: ir.TensorBox, bound_vars: OrderedSet[sympy.Symbol]):
    for expr in chain.from_iterable([value.get_size(), value.get_stride()]):
        if not isinstance(expr, Expr) or isinstance(expr, sympy.Symbol):
            continue
        undefined_symbols = [sym for sym in expr.free_symbols if sym not in bound_vars]
        if <MASK>:
            raise AssertionError(f'For {expr}, expected {undefined_symbols} to have been codegen-ed.')

def match(self, event: _ProfilerEvent):
    if <MASK>:
        return False
    if len(input_dtypes(event)) < 3 or input_dtypes(event)[2] is None:
        return False
    event = self.go_up_until(event, lambda e: e.name.startswith('nn.Module: Conv2d'))
    if not event:
        return False
    event = self.next_of(event)
    if not event:
        return False
    return event.name.startswith('nn.Module: BatchNorm2d')

def getarrdims(a, var, verbose=0):
    ret = {}
    if isstring(var) and (not isarray(var)):
        ret['size'] = getstrlength(var)
        ret['rank'] = '0'
        ret['dims'] = ''
    elif isscalar(var):
        ret['size'] = '1'
        ret['rank'] = '0'
        ret['dims'] = ''
    elif isarray(var):
        dim = copy.copy(var['dimension'])
        ret['size'] = '*'.join(dim)
        try:
            ret['size'] = repr(eval(ret['size']))
        except Exception:
            pass
        ret['dims'] = ','.join(dim)
        ret['rank'] = repr(len(dim))
        ret['rank*[-1]'] = repr(len(dim) * [-1])[1:-1]
        for i in range(len(dim)):
            v = []
            if dim[i] in depargs:
                v = [dim[i]]
            else:
                for va in depargs:
                    if re.match('.*?\\b%s\\b.*' % va, dim[i]):
                        v.append(va)
            for va in v:
                if depargs.index(va) > depargs.index(a):
                    dim[i] = '*'
                    break
        (ret['setdims'], i) = ('', -1)
        for d in dim:
            i = i + 1
            if d not in ['*', ':', '(*)', '(:)']:
                ret['setdims'] = '%s#varname#_Dims[%d]=%s,' % (ret['setdims'], i, d)
        if ret['setdims']:
            ret['setdims'] = ret['setdims'][:-1]
        (ret['cbsetdims'], i) = ('', -1)
        for d in var['dimension']:
            i = i + 1
            if d not in ['*', ':', '(*)', '(:)']:
                ret['cbsetdims'] = '%s#varname#_Dims[%d]=%s,' % (ret['cbsetdims'], i, d)
            elif isintent_in(var):
                outmess('getarrdims:warning: assumed shape array, using 0 instead of %r\n' % d)
                ret['cbsetdims'] = '%s#varname#_Dims[%d]=%s,' % (ret['cbsetdims'], i, 0)
            elif <MASK>:
                errmess(f'getarrdims: If in call-back function: array argument {repr(a)} must have bounded dimensions: got {repr(d)}\n')
        if ret['cbsetdims']:
            ret['cbsetdims'] = ret['cbsetdims'][:-1]
    return ret

def _restore_output_tensor_names(graph_def: graph_pb2.GraphDef) -> graph_pb2.GraphDef:
    """Restores the output tensor names of the converted model.

  During the conversion, the output tensor names of the original model are
  embedded in the `tf_saved_model.index_path` attribute of the RetVal nodes and
  might become the name of Retval nodes as well (with an index suffix if there
  are multiple output tensors from one node). Since Retval nodes are not used in
  SavedModel, this function removes them and restore the names to the actual
  output tensors.

  Args:
    graph_def: the converted GraphDef.

  Returns:
    The GraphDef with Retval nodes removed and output tensor names restored.
  """
    output_renaming_map = {}
    with session.Session(graph=ops.Graph()):
        importer.import_graph_def(graph_def, name='')
        graph = ops.get_default_graph()
        for op in graph.get_operations():
            if op.type == '_Retval':
                expected_node_name = op.name
                if op.get_attr('tf_saved_model.index_path') is not None:
                    index_path_name = op.get_attr('tf_saved_model.index_path')[0]
                    index_path_name = index_path_name.decode('utf-8').split(':')[0]
                    try:
                        index_path_node = graph.get_operation_by_name(index_path_name)
                        if index_path_node.type == '_Retval':
                            expected_node_name = index_path_name
                    except KeyError:
                        pass
                retval_input_node_name = op.inputs[0].op.name
                output_renaming_map[retval_input_node_name] = expected_node_name
    for node in reversed(graph_def.node):
        if <MASK>:
            node.name = output_renaming_map[node.name]
        elif node.op == '_Retval':
            graph_def.node.remove(node)
        else:
            for (idx, input_name) in enumerate(node.input):
                if input_name in output_renaming_map:
                    node.input[idx] = output_renaming_map[input_name]
            updating_inputs = []
            for input_name in reversed(node.input):
                if input_name.startswith('^') and input_name[1:] in output_renaming_map:
                    updating_inputs.append(input_name[1:])
                    node.input.remove(input_name)
            for updating_input in updating_inputs:
                node.input.append('^' + output_renaming_map[updating_input])
    return graph_def

