def _storage_setup(storage: Union[StorageReader, StorageWriter, None], checkpoint_id: Union[str, os.PathLike, None], reader: bool=False) -> Union[None, StorageReader, StorageWriter]:
    if storage:
        if checkpoint_id is not None:
            storage.reset(checkpoint_id)
        return storage
    if not checkpoint_id:
        raise RuntimeError('`checkpoint_id` must be specified if storage_reader/storage_writer is None.')
    targets: list[type[Union[StorageReader, StorageWriter]]] = []
    if reader:
        targets = [FileSystemReader]
    else:
        targets = [FileSystemWriter]
    try:
        from ._fsspec_filesystem import FsspecReader, FsspecWriter
        targets.append(FsspecReader if reader else FsspecWriter)
    except Exception:
        pass
    for target in targets:
        if <MASK>:
            storage = target(checkpoint_id)
            storage.reset(checkpoint_id)
            return storage
    raise RuntimeError('Cannot detect which StorageReader or StorageWriter to use. Please specify the storage_reader/storage_writer.')

def AddValue(self, val):
    """Add `val` to the current context and its outer context recursively."""
    result = val
    new_value = val.name not in self._values
    new_value &= val.op._control_flow_context is not self
    if new_value:
        self._values.add(val.name)
        grad_ctxt = ops.get_default_graph()._get_control_flow_context()
        if <MASK>:
            grad_ctxt = grad_ctxt.GetWhileContext()
            if grad_ctxt.grad_state:
                forward_ctxt = util.GetWhileContext(val.op)
                if util.IsLoopExit(val.op):
                    forward_ctxt = forward_ctxt.outer_context
                    if forward_ctxt:
                        forward_ctxt = forward_ctxt.GetWhileContext()
                if forward_ctxt == grad_ctxt.grad_state.forward_context:
                    real_val = grad_ctxt.grad_state.GetRealValue(val)
                    self._external_values[val.name] = real_val
                    return real_val
        if self._outer_context is not None:
            result = self._outer_context.AddValue(val)
        with ops.control_dependencies(None):
            enter = _Enter(result, self._name, is_constant=True, parallel_iterations=self._parallel_iterations)
            enter.graph.prevent_feeding(enter)
            if self._outer_context:
                self._outer_context.AddInnerOp(enter.op)
        self._FixControlInputsAndContext([enter])
        self._values.add(enter.name)
        self._external_values[val.name] = enter
        result = enter
    else:
        actual_val = self._external_values.get(val.name)
        if actual_val is not None:
            result = actual_val
    return result

def inner_fn(idx):
    idx_dim = ops.index_expr(idx[dim], torch.int64)
    masks = []
    masked_loads = []
    for i in range(len(inputs)):
        start = ops.constant(0, torch.int64) if i == 0 else ops.index_expr(inputs_ranges[i][0], torch.int64)
        end = ops.index_expr(inputs_ranges[i][1], torch.int64)
        start_cond = ops.ge(idx_dim, start)
        end_cond = ops.lt(idx_dim, end)
        if i == 0:
            mask = end_cond
        elif <MASK>:
            mask = start_cond
        else:
            mask = ops.and_(start_cond, end_cond)
        masks.append(mask)
        idx_load = list(idx)
        idx_load[dim] = Identity(idx_load[dim] - inputs_ranges[i][0])
        masked_loads.append(ops.masked(mask, lambda : inputs_loaders[i](idx_load), 0.0))
    next_val = masked_loads[-1]
    for i in range(len(inputs) - 2, -1, -1):
        next_val = ops.where(masks[i], masked_loads[i], next_val)
    return next_val

