def _yeo_johnson_transform(self, x, lmbda):
    """Return transformed input x following Yeo-Johnson transform with
        parameter lambda.
        """
    out = np.zeros_like(x)
    pos = x >= 0
    if <MASK>:
        out[pos] = np.log1p(x[pos])
    else:
        out[pos] = (np.power(x[pos] + 1, lmbda) - 1) / lmbda
    if abs(lmbda - 2) > np.spacing(1.0):
        out[~pos] = -(np.power(-x[~pos] + 1, 2 - lmbda) - 1) / (2 - lmbda)
    else:
        out[~pos] = -np.log1p(-x[~pos])
    return out

def skipIfNoDynamoSupport(fn):
    reason = "dynamo doesn't support."
    if <MASK>:
        if not torchdynamo.is_dynamo_supported():
            fn.__unittest_skip__ = True
            fn.__unittest_skip_why__ = reason
        return fn

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        if not torchdynamo.is_dynamo_supported():
            raise unittest.SkipTest(reason)
        else:
            fn(*args, **kwargs)
    return wrapper

def _get_type_from_tensor(tensor: torch.Tensor | torch.SymBool | torch.SymInt | torch.SymFloat | Sequence[torch.Tensor]) -> ir.TypeProtocol:
    if isinstance(tensor, torch.Tensor):
        return ir.TensorType(_torch_dtype_to_onnx_compatible_dtype(tensor.dtype))
    if <MASK>:
        return ir.TensorType(ir.DataType.BOOL)
    if isinstance(tensor, torch.SymInt):
        return ir.TensorType(ir.DataType.INT64)
    if isinstance(tensor, torch.SymFloat):
        return ir.TensorType(ir.DataType.FLOAT)
    first_tensor = next((item for item in tensor if item is not None), None)
    if first_tensor is None:
        return ir.SequenceType(ir.TensorType(ir.DataType.UNDEFINED))
    return ir.SequenceType(ir.TensorType(_torch_dtype_to_onnx_compatible_dtype(first_tensor.dtype)))

def _wrap_backward_function(self, forward_graph: func_graph_module.FuncGraph, backward, outputs):
    """Create a backward function given `outputs` from the forward function."""
    capture_mapping = dict(zip((ops.tensor_id(t) for t in forward_graph.outputs), outputs))
    captured_inputs = backward.captured_inputs
    remapped_captures = [capture_mapping.get(ops.tensor_id(capture), capture) for capture in captured_inputs]
    if any((t.graph is forward_graph for t in remapped_captures if not isinstance(t, ops.EagerTensor))):
        incorrect_mapping = [t for t in remapped_captures if not isinstance(t, ops.EagerTensor) and t.graph is not forward_graph]
        raise errors.InternalError(f'Failed to map all backward graph captures to the forward graph. Incorrectly mapped: {incorrect_mapping}.')
    variant_zeros_like = {}
    backward_function_inputs = len(backward.inputs) - len(captured_inputs)
    recorded_outputs = []
    trainable_recorded_outputs = 0
    skip_positions = []
    if self._num_forwardprop_outputs and (not self._need_gradients_for_jvps):
        relevant_outputs = outputs[:self._num_inference_outputs] + outputs[self._num_inference_outputs + self._num_forwardprop_outputs:]
    else:
        relevant_outputs = outputs
    for (output_index, output) in enumerate(relevant_outputs):
        if trainable_recorded_outputs < backward_function_inputs:
            recorded_outputs.append(output)
        if backprop_util.IsTrainable(output):
            trainable_recorded_outputs += 1
        else:
            skip_positions.append(output_index)
        if output.dtype == dtypes.variant:
            variant_zeros_like[output_index] = default_gradient.zeros_like(output)

    def _backward_function_wrapper(*args):
        """Process output gradients and call the backward function."""
        if not backward.outputs:
            return backward.structured_outputs
        processed_args = []
        input_index = 0
        for (output_index, arg) in enumerate(args):
            if isinstance(arg, indexed_slices.IndexedSlices):
                arg = ops.convert_to_tensor(arg)
            if output_index in skip_positions:
                continue
            if arg is None:
                input_placeholder = backward.inputs[input_index]
                if input_placeholder.dtype == dtypes.variant:
                    arg = variant_zeros_like[output_index]
                else:
                    arg = array_ops.zeros(*default_gradient.shape_and_dtype(input_placeholder))
            processed_args.append(arg)
            input_index += 1
            if <MASK>:
                break
        return backward._call_flat(processed_args, remapped_captures)
    return (_backward_function_wrapper, recorded_outputs)

def _replace_literals_with_existing_placeholders(gm: torch.fx.GraphModule, exclude_literals: Optional[list[Any]]=None, literal_to_ph_idx: Optional[dict[Union[float, int, bool, torch.dtype], int]]=None):
    """Replace the literals in the graph with **existing** placeholder nodes, so that the literal arguments
    in the graph can be matched and replaced

    To use this, all literal args in the graph should be unique and each of them should correspond
    to exactly one placeholder node

    # 1. Original Graph
    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        return torch.dequantize_per_tensor(x_i8, scale, zero_point, quant_min, quant_max)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        x_i8 = torch.clamp(x_i8, quant_min, quant_max)
        return ((x_i8.to(torch.float32) - zero_point) * scale).to(dtype=torch.float32)

    example_inputs = (
        torch.randn(1, 3, 3, 3),
        1.0,
        0,
        -128,
        127,
    )
    pattern_gm = _get_aten_graph_module_for_pattern(pattern, example_inputs)
    replacement_gm = _get_aten_graph_module_for_pattern(pattern, example_inptus)

    # 2. Before calling replace literals we'll see the following graph:
    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        return torch.dequantize_per_tensor(x_i8, 1.0, 0, -128, 127)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        x_i8 = torch.clamp(x_i8, -128, 127)
        return ((x_i8.to(torch.float32) - 0) * 1.0).to(dtype=torch.float32)

    # Note that literal args appear in different order in pattern and replacement graph, so
    # we can't use _replace_literals_with_new_placeholders

    literal_to_ph_idx = {1.0: 1, 0: 2, -128: 3, 127: 4}
    pattern_gm = _replace_literals_with_existing_placeholders(pattern_gm, literal_to_ph_idx)
    replacement_gm = _replace_literals_with_existing_placeholders(replacement_gm, literal_to_ph_idx)

    # 3. After replacing literals with existing placeholder nodes

    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        return torch.dequantize_per_tensor(x_i8, scale, zero_point, quant_min, quant_max)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        x_i8 = torch.clamp(x_i8, quant_min, quant_max)
        return ((x_i8.to(torch.float32) - zero_point) * scale).to(dtype=torch.float32)
    """
    if <MASK>:
        exclude_literals = []
    if literal_to_ph_idx is None:
        literal_to_ph_idx = {}
    phs = [node for node in gm.graph.nodes if node.op == 'placeholder']
    for node in gm.graph.nodes:
        if node.op != 'call_function':
            continue
        new_args = []
        for arg in node.args:
            if _is_literal(arg) and arg not in exclude_literals and (arg in literal_to_ph_idx):
                ph_idx = literal_to_ph_idx[arg]
                ph_node = phs[ph_idx]
                new_args.append(ph_node)
            else:
                new_args.append(arg)
        new_args = tuple(new_args)
        node.args = new_args
    return gm

def sample_inputs_sparse_reduction(op_info, device, dtype, requires_grad, layout, blocksize=None, **kwargs):
    """Sample inputs for reduction operations on sparse tensors."""
    layout_name = str(layout).split('.', 1)[-1].rsplit('_coo', 1)[0]
    op_supports_layout = getattr(op_info, 'supports_' + layout_name)
    if <MASK>:
        return
    for sample_input in sample_inputs_reduction(op_info, device, dtype, requires_grad, **kwargs):
        if sample_input.input.ndim == 0:
            continue
        if layout in {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}:
            if sample_input.input.ndim < 2:
                continue
            if sample_input.input.ndim > 2 and (sample_input.input == 0).any():
                continue
        if layout in {torch.sparse_bsr, torch.sparse_bsc} and blocksize is None:
            blocksize = (1, 1)
        yield SampleInput(sample_input.input.detach().to_sparse(layout=layout, blocksize=blocksize).requires_grad_(requires_grad), args=sample_input.args, kwargs=sample_input.kwargs)
        if layout is torch.sparse_coo and (dtype.is_floating_point or dtype.is_complex):
            inp = sample_input.input.detach().to_sparse(layout=layout)
            inp = torch.sparse_coo_tensor(inp.indices().repeat(1, 2), inp.values().repeat(2), inp.shape, dtype=inp.dtype, device=inp.device)
            assert not inp.is_coalesced()
            yield SampleInput(inp.requires_grad_(requires_grad), args=sample_input.args, kwargs=sample_input.kwargs)
        if sample_input.input.ndim > 2:
            yield SampleInput(sample_input.input.detach().to_sparse(layout=layout, blocksize=blocksize, dense_dim=sample_input.input.ndim - 2).requires_grad_(requires_grad), args=sample_input.args, kwargs=sample_input.kwargs)

def patterns_to_regex(allowed_patterns: list[str]) -> Any:
    """
    pattern is glob-like, i.e. the only special sequences it has are:
      - ? - matches single character
      - * - matches any non-folder separator characters or no character
      - ** - matches any characters or no character
      Assuming that patterns are free of braces and backslashes
      the only character that needs to be escaped are dot and plus
    """
    rc = '('
    for (idx, pattern) in enumerate(allowed_patterns):
        if idx > 0:
            rc += '|'
        pattern_ = PeekableIterator(pattern)
        assert not any((c in pattern for c in '{}()[]\\'))
        for c in pattern_:
            if c == '.':
                rc += '\\.'
            elif <MASK>:
                rc += '\\+'
            elif c == '*':
                if pattern_.peek() == '*':
                    next(pattern_)
                    rc += '.*'
                else:
                    rc += '[^/]*'
            else:
                rc += c
    rc += ')'
    return re.compile(rc)

def l1_loss(input: Tensor, target: Tensor, size_average: Optional[bool]=None, reduce: Optional[bool]=None, reduction: str='mean', weight: Optional[Tensor]=None) -> Tensor:
    """Compute the L1 loss, with optional weighting.

    Function that takes the mean element-wise absolute value difference.

    See :class:`~torch.nn.L1Loss` for details.

    Args:
        input (Tensor): Predicted values.
        target (Tensor): Ground truth values.
        size_average (bool, optional): Deprecated (see :attr:`reduction`).
        reduce (bool, optional): Deprecated (see :attr:`reduction`).
        reduction (str, optional): Specifies the reduction to apply to the output:
                                   'none' | 'mean' | 'sum'. 'mean': the mean of the output is taken.
                                   'sum': the output will be summed. 'none': no reduction will be applied.
                                   Default: 'mean'.
        weight (Tensor, optional): Weights for each sample. Default: None.

    Returns:
        Tensor: L1 loss (optionally weighted).
    """
    if has_torch_function_variadic(input, target):
        return handle_torch_function(l1_loss, (input, target, weight), input, target, size_average=size_average, reduce=reduce, reduction=reduction)
    if target.size() != input.size():
        warnings.warn(f'Using a target size ({target.size()}) that is different to the input size ({input.size()}). This will likely lead to incorrect results due to broadcasting. Please ensure they have the same size.', stacklevel=2)
    if size_average is not None or reduce is not None:
        reduction = _Reduction.legacy_get_string(size_average, reduce)
    (expanded_input, expanded_target) = torch.broadcast_tensors(input, target)
    if weight is not None:
        if weight.size() != input.size():
            raise ValueError('Weights and input must have the same size.')
        absolute_errors = torch.abs(expanded_input - expanded_target)
        weighted_absolute_errors = absolute_errors * weight
        if <MASK>:
            return weighted_absolute_errors
        elif reduction == 'sum':
            return torch.sum(weighted_absolute_errors)
        elif reduction == 'mean':
            return torch.sum(weighted_absolute_errors) / torch.sum(weight)
        else:
            raise ValueError(f"Invalid reduction mode: {reduction}. Expected one of 'none', 'mean', 'sum'.")
    else:
        return torch._C._nn.l1_loss(expanded_input, expanded_target, _Reduction.get_enum(reduction))

def _get_openmp_args(cpp_compiler: str) -> tuple[list[str], list[str], list[str], list[str], list[str], list[str]]:
    cflags: list[str] = []
    ldflags: list[str] = []
    include_dir_paths: list[str] = []
    lib_dir_paths: list[str] = []
    libs: list[str] = []
    passthrough_args: list[str] = []
    if config.aot_inductor.cross_target_platform == 'windows':
        return (cflags, ldflags, include_dir_paths, lib_dir_paths, libs, passthrough_args)
    if _IS_MACOS:
        cflags.append('Xclang')
        cflags.append('fopenmp')
        omp_available = not _is_apple_clang(cpp_compiler)
        omp_prefix = os.getenv('OMP_PREFIX')
        if omp_prefix is not None:
            header_path = os.path.join(omp_prefix, 'include', 'omp.h')
            valid_env = os.path.exists(header_path)
            if valid_env:
                include_dir_paths.append(os.path.join(omp_prefix, 'include'))
                lib_dir_paths.append(os.path.join(omp_prefix, 'lib'))
            else:
                warnings.warn('environment variable `OMP_PREFIX` is invalid.')
            omp_available = omp_available or valid_env
        if not omp_available:
            libs.append('omp')
        conda_prefix = os.getenv('CONDA_PREFIX')
        if not omp_available and conda_prefix is not None:
            omp_available = is_conda_llvm_openmp_installed()
            if <MASK>:
                conda_lib_path = os.path.join(conda_prefix, 'lib')
                include_dir_paths.append(os.path.join(conda_prefix, 'include'))
                lib_dir_paths.append(conda_lib_path)
                if os.uname().machine == 'x86_64' and os.path.exists(os.path.join(conda_lib_path, 'libiomp5.dylib')):
                    libs.append('iomp5')
        if not omp_available:
            (omp_available, libomp_path) = homebrew_libomp()
            if omp_available:
                include_dir_paths.append(os.path.join(libomp_path, 'include'))
                lib_dir_paths.append(os.path.join(libomp_path, 'lib'))
    elif _IS_WINDOWS:
        "\n        On Windows, `clang` and `icx` have their specific openmp implenmention.\n        And the openmp lib is in compiler's some sub-directory.\n        For dynamic library(DLL) load, the Windows native APIs are `LoadLibraryA` and `LoadLibraryExA`, and their search\n        dependencies have some rules:\n        https://learn.microsoft.com/en-us/windows/win32/api/libloaderapi/nf-libloaderapi-loadlibraryexa#searching-for-dlls-and-dependencies\n        In some case, the rules may not include compiler's sub-directories.\n        So, it can't search and load compiler's openmp library correctly.\n        And then, the whole application would be broken.\n\n        To avoid the openmp load failed, we can automatic locate the openmp binary and preload it.\n        1. For clang, the function is `perload_clang_libomp_win`.\n        2. For icx, the function is `perload_icx_libomp_win`.\n        "
        if _is_clang(cpp_compiler):
            cflags.append('openmp')
            libs.append('libomp')
            perload_clang_libomp_win(cpp_compiler, 'libomp.dll')
        elif _is_intel_compiler(cpp_compiler):
            cflags.append('Qiopenmp')
            libs.append('libiomp5md')
            perload_icx_libomp_win(cpp_compiler)
        else:
            cflags.append('openmp')
            cflags.append('openmp:experimental')
    elif config.is_fbcode():
        include_dir_paths.append(build_paths.openmp_include)
        openmp_lib = build_paths.openmp_lib_so
        fb_openmp_extra_flags = f'-Wp,-fopenmp {openmp_lib}'
        passthrough_args.append(fb_openmp_extra_flags)
        libs.append('omp')
    elif _is_clang(cpp_compiler):
        cflags.append('fopenmp')
        libs.append('gomp')
    elif _is_intel_compiler(cpp_compiler):
        cflags.append('fiopenmp')
    else:
        cflags.append('fopenmp')
        libs.append('gomp')
    return (cflags, ldflags, include_dir_paths, lib_dir_paths, libs, passthrough_args)

def get_next_element_by_instance(self, instance_id: int):
    if self._datapipe_iterator is None and self._child_stop[instance_id]:
        self._datapipe_iterator = iter(self.main_datapipe)
        self._snapshot_state = _SnapshotState.Iterating
        for i in range(self.num_instances):
            self._child_stop[i] = False
    try:
        while not self._child_stop[instance_id]:
            self.child_pointers[instance_id] += 1
            if self.end_ptr is not None and self.child_pointers[instance_id] == self.end_ptr:
                self._child_stop[instance_id] = True
                break
            if self.buffer and self.child_pointers[instance_id] <= self.leading_ptr:
                idx = self.child_pointers[instance_id] - self.slowest_ptr - 1
                return_val = self.buffer[idx]
            else:
                self.leading_ptr = self.child_pointers[instance_id]
                try:
                    return_val = next(self._datapipe_iterator)
                    self.buffer.append(return_val)
                except StopIteration:
                    self._child_stop[instance_id] = True
                    self._datapipe_iterator = None
                    self.end_ptr = self.leading_ptr
                    continue
            if <MASK>:
                new_min = min(self.child_pointers)
                if self.slowest_ptr < new_min:
                    self.slowest_ptr = new_min
                    self.buffer.popleft()
            if self.buffer_size >= 0 and self.leading_ptr > self.buffer_size + self.slowest_ptr:
                raise BufferError('ForkerIterDataPipe buffer overflow,' + f'buffer size {self.buffer_size} is insufficient.')
            yield self.copy_fn(return_val)
    finally:
        self._child_stop[instance_id] = True
        if all(self._child_stop):
            self._datapipe_iterator = None
            self._cleanup()

def contribute_to_class(self, cls, name):
    from django.db import connection
    from django.db.backends.utils import truncate_name
    cls._meta = self
    self.model = cls
    self.object_name = cls.__name__
    self.model_name = self.object_name.lower()
    self.verbose_name = camel_case_to_spaces(self.object_name)
    self.original_attrs = {}
    if self.meta:
        meta_attrs = self.meta.__dict__.copy()
        for name in self.meta.__dict__:
            if name.startswith('_'):
                del meta_attrs[name]
        for attr_name in DEFAULT_NAMES:
            if attr_name in meta_attrs:
                setattr(self, attr_name, meta_attrs.pop(attr_name))
                self.original_attrs[attr_name] = getattr(self, attr_name)
            elif hasattr(self.meta, attr_name):
                setattr(self, attr_name, getattr(self.meta, attr_name))
                self.original_attrs[attr_name] = getattr(self, attr_name)
        self.unique_together = normalize_together(self.unique_together)
        if not self.abstract:
            self.constraints = self._format_names(self.constraints)
            self.indexes = self._format_names(self.indexes)
        if <MASK>:
            self.verbose_name_plural = format_lazy('{}s', self.verbose_name)
        self._ordering_clash = bool(self.ordering and self.order_with_respect_to)
        if meta_attrs != {}:
            raise TypeError("'class Meta' got invalid attribute(s): %s" % ','.join(meta_attrs))
    else:
        self.verbose_name_plural = format_lazy('{}s', self.verbose_name)
    del self.meta
    if not self.db_table:
        self.db_table = '%s_%s' % (self.app_label, self.model_name)
        self.db_table = truncate_name(self.db_table, connection.ops.max_name_length())
    if self.swappable:
        setting_changed.connect(self.setting_changed)

def f(a, b):
    dtype = a.dtype
    if <MASK>:
        rtol_ = ops.convert_to_tensor(rtol, dtype.real_dtype)
        atol_ = ops.convert_to_tensor(atol, dtype.real_dtype)
        result = math_ops.abs(a - b) <= atol_ + rtol_ * math_ops.abs(b)
        if equal_nan:
            result = result | math_ops.is_nan(a) & math_ops.is_nan(b)
        return result
    else:
        return a == b

def control_dependency_on_returns(return_value):
    """Create a TF control dependency on the return values of a function.

  If the function had no return value, a no-op context is returned.

  Args:
    return_value: The return value to set as control dependency.

  Returns:
    A context manager.
  """

    def control_dependency_handle(t):
        if isinstance(t, tensor_array_ops.TensorArray):
            return t.flow
        return t
    if return_value is None:
        return contextlib.contextmanager(lambda : (yield))()
    if <MASK>:
        return_value = (return_value,)
    return_value = tuple((control_dependency_handle(t) for t in return_value))
    return ops.control_dependencies(return_value)

@register_meta([aten._flash_attention_forward])
def meta__flash_attention_forward(query: Tensor, key: Tensor, value: Tensor, cum_seq_q: Optional[Tensor], cum_seq_k: Optional[Tensor], max_q: int, max_k: int, dropout_p: float, is_causal: bool, return_debug_mask: bool, scale: Optional[float]=None, window_size_left: Optional[int]=None, window_size_right: Optional[int]=None, seqused_k: Optional[Tensor]=None, alibi_slopes: Optional[Tensor]=None):
    batch_size = query.size(0) if cum_seq_q is None else cum_seq_q.numel() - 1
    max_seqlen_batch_q = query.size(1) if cum_seq_q is None else max_q
    max_seqlen_batch_k = key.size(1) if cum_seq_k is None else max_k
    num_heads = query.size(-2)
    head_dim = query.size(-1)
    attention = torch.empty_like(query)
    if cum_seq_q is None:
        logsumexp = torch.empty((batch_size, num_heads, max_seqlen_batch_q), dtype=torch.float, device=query.device)
    else:
        total_q = query.size(0)
        logsumexp = torch.empty((num_heads, total_q), dtype=torch.float, device=query.device)
    if return_debug_mask:
        blocksize_c = 128 if head_dim > 64 else 256
        max_seqlen_k = math.ceil(max_seqlen_batch_q / blocksize_c)
        if max_seqlen_batch_k <= 128:
            max_seqlen_k = 128
        elif <MASK>:
            max_seqlen_k = 256
        debug_mask = torch.empty((batch_size, num_heads, max_seqlen_batch_q, max_seqlen_k), dtype=query.dtype, device=query.device)
    else:
        debug_mask = torch.empty(0, dtype=query.dtype, device=query.device)
    (seed, offset) = (None, None)
    if torch.version.hip and torch.cuda.is_available():
        seed = torch.empty((), dtype=torch.long, device='meta')
        offset = torch.empty((), dtype=torch.long, device='meta')
    else:
        seed = torch.empty(2, dtype=torch.uint64, device='meta')
        offset = torch.empty((), dtype=torch.uint64, device='meta')
    return (attention, logsumexp, seed, offset, debug_mask)

def _assert_scalar(value, name):
    """Asserts that `value` is scalar, and returns `value`."""
    value_rank = value.shape.rank
    if <MASK>:
        check = control_flow_assert.Assert(math_ops.equal(array_ops.rank(value), 0), ['Input %s must be a scalar' % name], name='%sIsScalar' % name.capitalize())
        result = control_flow_ops.with_dependencies([check], value, name='%sDependencies' % name)
        result.set_shape([])
        return result
    elif value_rank == 0:
        return value
    else:
        raise ValueError('Input %s must be a scalar' % name)

