def jit_lines(self):
    if <MASK>:
        return '@triton.jit'
    (argdefs, _, signature, _) = self.args.python_argdefs()
    triton_meta: dict[str, Any] = {'signature': signature_to_meta(signature, size_dtype=self.index_dtype, argdefs=argdefs, is_template=True), 'device': DeviceProperties.create(self.output_node.get_device()), 'constants': {}}
    triton_meta['configs'] = [config_of(signature)]
    for arg_num in equal_1_arg_indices(signature):
        triton_meta['constants'][signature[arg_num].name] = 1
    matrix_instr_nonkdim = self.meta.get('matrix_instr_nonkdim', None)
    waves_per_eu = self.meta.get('waves_per_eu', None)
    kpack = self.meta.get('kpack', None)
    if matrix_instr_nonkdim:
        triton_meta['matrix_instr_nonkdim'] = matrix_instr_nonkdim
    if waves_per_eu:
        triton_meta['waves_per_eu'] = waves_per_eu
    if kpack:
        triton_meta['kpack'] = kpack
    self.triton_meta = triton_meta
    inductor_meta = {'kernel_name': str(Placeholder.DESCRIPTIVE_NAME), **self.inductor_meta_common(), **FixedGrid.setup_grid_as_args()}
    if config.profile_bandwidth or config.benchmark_kernel:
        num_gb = self.estimate_kernel_num_bytes() / 1000000000.0
        inductor_meta['kernel_num_gb'] = num_gb
    if config.benchmark_kernel:
        flops = self.estimate_flops()
        inductor_meta['kernel_flop'] = flops
    inductor_meta['config_args'] = self.meta
    template_args = f'\n            num_stages={self.num_stages},\n            num_warps={self.num_warps},\n            triton_meta={triton_meta!r},\n            inductor_meta={inductor_meta!r},\n        '
    if HAS_WARP_SPEC:
        template_args += f'\n            num_consumer_groups={self.num_consumer_groups},\n            num_buffers_warp_spec={self.num_buffers_warp_spec},\n        '
    return f'\n            @triton_heuristics.template(\n                {template_args}\n            )\n            @triton.jit\n        '

def _format_strings(self) -> list[str]:
    if <MASK>:
        float_format = get_option('display.float_format')
        if float_format is None:
            precision = get_option('display.precision')
            float_format = lambda x: _trim_zeros_single_float(f'{x: .{precision:d}f}')
    else:
        float_format = self.float_format
    if self.formatter is not None:
        formatter = self.formatter
    elif self.fallback_formatter is not None:
        formatter = self.fallback_formatter
    else:
        quote_strings = self.quoting is not None and self.quoting != QUOTE_NONE
        formatter = partial(printing.pprint_thing, escape_chars=('\t', '\r', '\n'), quote_strings=quote_strings)

    def _format(x):
        if self.na_rep is not None and is_scalar(x) and isna(x):
            if x is None:
                return 'None'
            elif x is NA:
                return str(NA)
            elif x is NaT or isinstance(x, (np.datetime64, np.timedelta64)):
                return 'NaT'
            return self.na_rep
        elif isinstance(x, PandasObject):
            return str(x)
        else:
            return str(formatter(x))
    vals = self.values
    if not isinstance(vals, np.ndarray):
        raise TypeError('ExtensionArray formatting should use _ExtensionArrayFormatter')
    inferred = lib.map_infer(vals, is_float)
    is_float_type = inferred & np.all(notna(vals), axis=tuple(range(1, len(vals.shape))))
    leading_space = self.leading_space
    if leading_space is None:
        leading_space = is_float_type.any()
    fmt_values = []
    for (i, v) in enumerate(vals):
        if (not is_float_type[i] or self.formatter is not None) and leading_space:
            fmt_values.append(f' {_format(v)}')
        elif is_float_type[i]:
            fmt_values.append(float_format(v))
        else:
            if leading_space is False:
                tpl = '{v}'
            else:
                tpl = ' {v}'
            fmt_values.append(tpl.format(v=_format(v)))
    return fmt_values

def signature_of(arg: KernelArgType, *, size_dtype: Optional[str]) -> str:
    if isinstance(arg, TensorArg):
        if <MASK>:
            typ = '*fp8e4nv'
        elif arg.dtype == torch.float8_e5m2:
            typ = '*fp8e5'
        elif arg.dtype == torch.float8_e4m3fnuz:
            typ = '*fp8e4b8'
        elif arg.dtype == torch.float8_e5m2fnuz:
            typ = '*fp8e5b16'
        else:
            typ = _type_of(arg.dtype)
        if should_unwrap_unspec_arg(arg.buffer):
            new_typ = typ.lstrip('*')
            if new_typ in ['fp16', 'bf16']:
                return 'fp32'
            else:
                return new_typ
        else:
            return typ
    if isinstance(arg, SizeArg):
        if arg.expr is None:
            if triton_version_uses_attrs_dict():
                return 'constexpr'
            else:
                return '*i8'
        elif _arg_equals_1(arg) and triton_version_uses_attrs_dict():
            return 'constexpr'
        elif isinstance(arg.expr, (float, sympy.Float)):
            return 'fp32'
        elif isinstance(arg.expr, bool):
            return 'i1'
        if size_dtype == 'tl.int32':
            return 'i32'
        elif size_dtype == 'tl.int64':
            return 'i64'
        elif size_dtype is None:
            int_max = torch.iinfo(torch.int32).max
            if expr_fits_within_32bit(arg.expr):
                V.graph.sizevars.check_leq(arg.expr, int_max)
                return 'i32'
            else:
                return 'i64'
        else:
            raise NotImplementedError(f'unhandled size_dtype {size_dtype}')
    if isinstance(arg, WorkspaceArg):
        return _type_of(arg.dtype)
    if isinstance(arg, TMADescriptorArg):
        if arg.api_type == 'experimental':
            return 'nvTmaDesc'
        else:
            assert arg.api_type == 'stable'
            assert arg.block_shape is not None
            assert arg.dtype is not None
            inner = _type_of(arg.dtype)[1:]
            return f'tensordesc<{inner}{list(arg.block_shape)}>'
    if isinstance(arg, ConstexprArg):
        return 'constexpr'
    raise NotImplementedError(f'unhandled {type(arg)}: {arg}')

def get_parameters(vars, global_params={}):
    params = copy.copy(global_params)
    g_params = copy.copy(global_params)
    for (name, func) in [('kind', _kind_func), ('selected_int_kind', _selected_int_kind_func), ('selected_real_kind', _selected_real_kind_func)]:
        if name not in g_params:
            g_params[name] = func
    param_names = []
    for n in get_sorted_names(vars):
        if 'attrspec' in vars[n] and 'parameter' in vars[n]['attrspec']:
            param_names.append(n)
    kind_re = re.compile('\\bkind\\s*\\(\\s*(?P<value>.*)\\s*\\)', re.I)
    selected_int_kind_re = re.compile('\\bselected_int_kind\\s*\\(\\s*(?P<value>.*)\\s*\\)', re.I)
    selected_kind_re = re.compile('\\bselected_(int|real)_kind\\s*\\(\\s*(?P<value>.*)\\s*\\)', re.I)
    for n in param_names:
        if '=' in vars[n]:
            v = vars[n]['=']
            if islogical(vars[n]):
                v = v.lower()
                for repl in [('.false.', 'False'), ('.true.', 'True')]:
                    v = v.replace(*repl)
            v = kind_re.sub('kind("\\1")', v)
            v = selected_int_kind_re.sub('selected_int_kind(\\1)', v)
            is_replaced = False
            if 'kindselector' in vars[n]:
                if <MASK>:
                    orig_v_len = len(v)
                    v = v.replace('_' + vars[n]['kindselector']['kind'], '')
                    is_replaced = len(v) < orig_v_len
            if not is_replaced:
                if not selected_kind_re.match(v):
                    v_ = v.split('_')
                    if len(v_) > 1:
                        v = ''.join(v_[:-1]).lower().replace(v_[-1].lower(), '')
            if isdouble(vars[n]):
                tt = list(v)
                for m in real16pattern.finditer(v):
                    tt[m.start():m.end()] = list(v[m.start():m.end()].lower().replace('d', 'e'))
                v = ''.join(tt)
            elif iscomplex(vars[n]):
                outmess(f'get_parameters[TODO]: implement evaluation of complex expression {v}\n')
            dimspec = ([s.removeprefix('dimension').strip() for s in vars[n]['attrspec'] if s.startswith('dimension')] or [None])[0]
            if real16pattern.search(v):
                v = 8
            elif real8pattern.search(v):
                v = 4
            try:
                params[n] = param_eval(v, g_params, params, dimspec=dimspec)
            except Exception as msg:
                params[n] = v
                outmess(f'get_parameters: got "{msg}" on {n!r}\n')
            if isstring(vars[n]) and isinstance(params[n], int):
                params[n] = chr(params[n])
            nl = n.lower()
            if nl != n:
                params[nl] = params[n]
        else:
            print(vars[n])
            outmess(f'get_parameters:parameter {n!r} does not have value?!\n')
    return params

def keep_tensor_guards_unsafe(guard_entries, keep_parameters=False):
    """
    A common function to keep tensor guards on all tensors. This is unsafe to
    use by default. But if you don't expect any changes in the model code, you
    can just keep the tensor guards.


    >> opt_mod = torch.compile(
    >>     mod,
    >>     options={"guard_filter_fn": torch.compiler.keep_tensor_guards},
    >> )
    """
    keep_flags = []
    for entry in guard_entries:
        if entry.guard_type == 'TENSOR_MATCH':
            if not isinstance(entry.value, torch.nn.Parameter):
                keep_flags.append(True)
            elif <MASK>:
                keep_flags.append(True)
            else:
                keep_flags.append(False)
        else:
            keep_flags.append(False)
    return keep_flags

