def _get_allowed_types_from_type_annotation(type_: TypeAnnotationValue) -> set[ir.TypeProtocol]:
    """Obtain the allowed types from a type annotation."""
    if <MASK>:
        return {ir.TensorType(dtype) for dtype in ir.DataType}
    allowed_types: set[ir.TypeProtocol]
    if isinstance(type_, TypeVar):
        allowed_types = set()
        if (constraints := type_.__constraints__):
            for constraint in constraints:
                allowed_types.update(_get_allowed_types_from_type_annotation(constraint))
        else:
            bound = type_.__bound__
            if bound is None:
                allowed_types = _ALL_VALUE_TYPES
            else:
                allowed_types.update(_get_allowed_types_from_type_annotation(bound))
        return allowed_types
    if hasattr(type_, 'dtype'):
        return {ir.TensorType(ir.DataType(type_.dtype))}
    if _is_optional(type_):
        allowed_types = set()
        subtypes = typing.get_args(type_)
        for subtype in subtypes:
            if subtype is type(None):
                continue
            allowed_types.update(_get_allowed_types_from_type_annotation(subtype))
        return allowed_types
    origin_type = typing.get_origin(type_)
    if origin_type is Union:
        allowed_types = set()
        subtypes = typing.get_args(type_)
        for subtype in subtypes:
            assert subtype is not type(None), 'Union should not contain None type because it is handled by _is_optional.'
            allowed_types.update(_get_allowed_types_from_type_annotation(subtype))
        return allowed_types
    if isinstance(origin_type, type) and issubclass(origin_type, Sequence):
        subtypes = typing.get_args(type_)
        return {ir.SequenceType(t) for t in _get_allowed_types_from_type_annotation(subtypes[0])}
    return _ALL_VALUE_TYPES

def fill_object_graph_proto(self, proto: saved_object_graph_pb2.SavedObjectGraph):
    """Populate the nodes, children and slot_variables of a SavedObjectGraph."""
    for (node_id, node) in enumerate(self.nodes):
        assert self.node_ids[node] == node_id
        object_proto = proto.nodes.add()
        object_proto.slot_variables.extend(self._slot_variables.get(node, ()))
        if isinstance(node, _CapturedTensor):
            continue
        for child in self.augmented_graph_view.list_children(node):
            child_proto = object_proto.children.add()
            child_proto.node_id = self.node_ids[child.ref]
            child_proto.local_name = child.name
        for (name, ref) in self.augmented_graph_view.list_dependencies(node):
            child_proto = object_proto.dependencies.add()
            child_proto.node_id = self.node_ids[ref]
            child_proto.local_name = name
        if node in self._saveable_objects_map:
            assert node not in self._obj_to_registered_saver, "Objects can't have both SaveableObjects and a registered saver"
            for (local_name, (save_fn, restore_fn)) in self._saveable_objects_map[node].items():
                saveable_object_proto = object_proto.saveable_objects[local_name]
                saveable_object_proto.save_function = self.node_ids[save_fn]
                saveable_object_proto.restore_function = self.node_ids[restore_fn]
        elif <MASK>:
            object_proto.registered_saver = self._obj_to_registered_saver[node]

def call_frozenset(self, tx: 'InstructionTranslator', *args, **kwargs):
    assert not kwargs
    if not args:
        return FrozensetVariable([])
    if <MASK>:
        raise_observed_exception(TypeError, tx, args=[ConstantVariable.create(f'frozenset() takes 1 positional argument but {len(args)} were given')])
    arg = args[0]
    if istype(arg, variables.FrozensetVariable):
        return FrozensetVariable([x.vt for x in arg.set_items])
    elif arg.has_force_unpack_var_sequence(tx):
        items = arg.force_unpack_var_sequence(tx)
        return FrozensetVariable(items)
    raise_observed_exception(TypeError, tx, args=[ConstantVariable.create('failed to construct builtin frozenset()')])

def check_min(nodes, mm=0, mam=0, mcm=0, mb=0, mpb=0, mrb=0, mob=0):
    for n in nodes:
        if mm > 0:
            self.assertGreaterEqual(n.exec_micros, mm)
        if mam > 0:
            self.assertGreaterEqual(n.accelerator_exec_micros, mam)
        if mcm > 0:
            self.assertGreaterEqual(n.cpu_exec_micros, mcm)
        if mb > 0:
            self.assertGreaterEqual(n.requested_bytes, mb)
        if mpb > 0:
            self.assertGreaterEqual(n.peak_bytes, mpb)
        if mrb > 0:
            self.assertGreaterEqual(n.residual_bytes, mrb)
        if <MASK>:
            self.assertGreaterEqual(n.output_bytes, mob)
        check_min(n.children, mm, mam, mcm, mb, mpb, mrb, mob)

def arrays_to_mgr(arrays, columns: Index, index, *, dtype: DtypeObj | None=None, verify_integrity: bool=True, consolidate: bool=True) -> Manager:
    """
    Segregate Series based on type and coerce into matrices.

    Needs to handle a lot of exceptional cases.
    """
    if verify_integrity:
        if index is None:
            index = _extract_index(arrays)
        else:
            index = ensure_index(index)
        (arrays, refs) = _homogenize(arrays, index, dtype)
    else:
        index = ensure_index(index)
        arrays = [extract_array(x, extract_numpy=True) for x in arrays]
        refs = [None] * len(arrays)
        for arr in arrays:
            if not isinstance(arr, (np.ndarray, ExtensionArray)) or arr.ndim != 1 or len(arr) != len(index):
                raise ValueError('Arrays must be 1-dimensional np.ndarray or ExtensionArray with length matching len(index)')
    columns = ensure_index(columns)
    if <MASK>:
        raise ValueError('len(arrays) must match len(columns)')
    axes = [columns, index]
    return create_block_manager_from_column_arrays(arrays, axes, consolidate=consolidate, refs=refs)

def var2fixfortran(vars, a, fa=None, f90mode=None):
    if fa is None:
        fa = a
    if a not in vars:
        show(vars)
        outmess(f'var2fixfortran: No definition for argument "{a}".\n')
        return ''
    if 'typespec' not in vars[a]:
        show(vars[a])
        outmess(f'var2fixfortran: No typespec for argument "{a}".\n')
        return ''
    vardef = vars[a]['typespec']
    if vardef == 'type' and 'typename' in vars[a]:
        vardef = f"{vardef}({vars[a]['typename']})"
    selector = {}
    lk = ''
    if 'kindselector' in vars[a]:
        selector = vars[a]['kindselector']
        lk = 'kind'
    elif 'charselector' in vars[a]:
        selector = vars[a]['charselector']
        lk = 'len'
    if '*' in selector:
        if f90mode:
            if selector['*'] in ['*', ':', '(*)']:
                vardef = f'{vardef}(len=*)'
            else:
                vardef = f"{vardef}({lk}={selector['*']})"
        elif selector['*'] in ['*', ':']:
            vardef = f"{vardef}*({selector['*']})"
        else:
            vardef = f"{vardef}*{selector['*']}"
    elif <MASK>:
        vardef = f"{vardef}(len={selector['len']}"
        if 'kind' in selector:
            vardef = f"{vardef},kind={selector['kind']})"
        else:
            vardef = f'{vardef})'
    elif 'kind' in selector:
        vardef = f"{vardef}(kind={selector['kind']})"
    vardef = f'{vardef} {fa}'
    if 'dimension' in vars[a]:
        vardef = f"{vardef}({','.join(vars[a]['dimension'])})"
    return vardef

def _uniform_random_(t: torch.Tensor, low: float, high: float) -> torch.Tensor:
    if <MASK>:
        return t.uniform_(low / 2, high / 2).mul_(2)
    else:
        return t.uniform_(low, high)

def _quantize_weight_decomposed(weight: torch.Tensor, weight_qscheme: torch.qscheme, weight_dtype: torch.dtype, weight_scale: torch.Tensor, weight_zero_point: torch.Tensor, weight_axis: int, weight_quant_min: typing.Optional[int], weight_quant_max: typing.Optional[int]) -> torch.Tensor:
    _DTYPE_TO_QVALUE_BOUNDS: dict[torch.dtype, tuple[int, int]] = {torch.uint8: (0, 255), torch.int8: (-128, 127), torch.int32: (-2 ** 31, 2 ** 31 - 1)}
    _QDTYPE_TO_UNDERLYING_INT_REPR_DTYPE = {torch.quint8: torch.uint8, torch.qint8: torch.int8, torch.qint32: torch.int32}
    if <MASK>:
        if weight_dtype in [torch.quint8, torch.qint8, torch.qint32]:
            weight_dtype_ = _QDTYPE_TO_UNDERLYING_INT_REPR_DTYPE[weight_dtype]
            if weight_quant_min is None or weight_quant_max is None:
                (weight_quant_min, weight_quant_max) = _DTYPE_TO_QVALUE_BOUNDS[weight_dtype_]
            weight = torch.ops.quantized_decomposed.quantize_per_tensor(weight, weight_scale, weight_zero_point, weight_quant_min, weight_quant_max, weight_dtype_)
            return weight
    elif weight_qscheme in [torch.per_channel_affine, torch.per_channel_affine_float_qparams]:
        if weight_dtype in [torch.quint8, torch.qint8, torch.qint32]:
            weight_dtype_ = _QDTYPE_TO_UNDERLYING_INT_REPR_DTYPE[weight_dtype]
            if weight_quant_min is None or weight_quant_max is None:
                (weight_quant_min, weight_quant_max) = _DTYPE_TO_QVALUE_BOUNDS[weight_dtype_]
            weight = torch.ops.quantized_decomposed.quantize_per_channel(weight, weight_scale, weight_zero_point, weight_axis, weight_quant_min, weight_quant_max, weight_dtype_)
            return weight
    raise ValueError(f'Unsupported dtype and qscheme: {weight_dtype}, {weight_qscheme}')

@ops.RegisterGradient('MatrixDiagPartV2')
def _MatrixDiagPartV2Grad(op: ops.Operation, grad):
    """Gradient for MatrixDiagPartV2."""
    matrix_shape = op.inputs[0].get_shape()[-2:]
    if <MASK>:
        return (array_ops.matrix_diag(grad, k=op.inputs[1], num_rows=matrix_shape[0], num_cols=matrix_shape[1]), None, None)
    else:
        return (array_ops.matrix_set_diag(array_ops.zeros_like(op.inputs[0]), grad, k=op.inputs[1]), None, None)

def get_overloads(aten_fn):
    if not isinstance(aten_fn, (list, tuple)):
        aten_fn = [aten_fn]
    else:
        aten_fn = list(aten_fn)
    for fn in list(aten_fn):
        if isinstance(fn, torch._ops.OpOverloadPacket):
            for overload in fn.overloads():
                other_fn = getattr(fn, overload)
                if <MASK>:
                    aten_fn.append(other_fn)
    return aten_fn

def _broadcast_to_ragged_shape(rt_input, dst_shape, broadcast_inner_dimensions):
    """Broadcasts rt_input to the ragged shape `dst_shape`."""
    if isinstance(rt_input, ragged_tensor.RaggedTensor) and rt_input.row_splits.dtype != dst_shape.dim_size_dtype:
        if not ragged_config.auto_cast_partition_dtype():
            raise ValueError('rt_input and dst_shape have different row_split dtypes; use RaggedTensor.with_row_splits_dtype() or RaggedTensorDynamicShape.with_dim_size_dtype() to convert to a compatible dtype.')
        rt_input = rt_input.with_row_splits_dtype(dtypes.int64)
        dst_shape = dst_shape.with_dim_size_dtype(dtypes.int64)
    if rt_input.shape.ndims is None or dst_shape.rank is None:
        raise ValueError('Unable to broadcast: unknown rank')
    if rt_input.shape.ndims > dst_shape.rank:
        raise ValueError('Incompatible with shape: rank mismatch')
    if isinstance(rt_input, ragged_tensor.RaggedTensor) and rt_input.ragged_rank >= dst_shape.num_partitioned_dimensions:
        raise ValueError('Incompatible with shape: ragged rank mismatch')
    src_shape = RaggedTensorDynamicShape.from_tensor(rt_input)
    src_shape = src_shape.broadcast_to_rank(dst_shape.rank)
    if dst_shape.rank > rt_input.shape.ndims:
        if rt_input.shape.ndims < dst_shape.num_inner_dimensions + 1:
            rt_input = array_ops.reshape(rt_input, array_ops.concat([[-1], dst_shape.inner_dim_sizes], axis=0))
        for _ in range(dst_shape.rank - rt_input.shape.ndims):
            if ragged_tensor.is_ragged(rt_input):
                nrows = rt_input.nrows()
            else:
                nrows = array_ops.shape(rt_input, out_type=dst_shape.dim_size_dtype)[0]
            rt_input = ragged_tensor.RaggedTensor.from_row_lengths(rt_input, [nrows], validate=False)
    if ragged_tensor.is_ragged(rt_input):
        inner_rank_diff = rt_input.flat_values.shape.ndims - 1 - dst_shape.num_inner_dimensions
        if inner_rank_diff > 0:
            rt_input = rt_input.with_flat_values(ragged_tensor.RaggedTensor.from_tensor(rt_input.flat_values, ragged_rank=inner_rank_diff, row_splits_dtype=dst_shape.dim_size_dtype))
    else:
        rt_input = ragged_tensor.RaggedTensor.from_tensor(rt_input, ragged_rank=dst_shape.num_partitioned_dimensions - 1, row_splits_dtype=dst_shape.dim_size_dtype)
    multiples = [1] * dst_shape.rank
    for axis in range(dst_shape.num_partitioned_dimensions):
        if <MASK>:
            src_size = src_shape.dimension_size(axis)
            dst_size = dst_shape.dimension_size(axis)
            if tensor_util.constant_value(src_size) in (1, None) and tensor_util.constant_value(dst_size) != 1:
                multiples[axis] = array_ops.where(math_ops.equal(src_size, 1), dst_size, 1)
    if not all((isinstance(v, int) and v == 1 for v in multiples)):
        multiples = array_ops_stack.stack(multiples, axis=0)
        rt_input = ragged_array_ops.tile(rt_input, multiples)
    if broadcast_inner_dimensions:
        new_shape = array_ops.broadcast_dynamic_shape(array_ops.shape(rt_input.flat_values, out_type=dst_shape.dim_size_dtype), array_ops.concat([[1], dst_shape.inner_dim_sizes], axis=0))
        rt_input = rt_input.with_flat_values(array_ops.broadcast_to(rt_input.flat_values, new_shape))
    for axis in range(dst_shape.num_partitioned_dimensions):
        if not src_shape.is_ragged(axis) and dst_shape.is_ragged(axis):
            dst_size = dst_shape.dimension_size(axis)
            rt_input = _ragged_tile_axis(rt_input, axis, dst_size, dst_shape.dim_size_dtype)
    return rt_input

def _handle_compute(self, node: fx.Node) -> None:
    """Handle scheduling compute and finding overlaps."""
    compute_time = benchmark_node(node)
    available_compute = compute_time * self.compute_overlap_multipler
    for info in self.in_flight.values():
        if info.exposed_time_ms == 0:
            continue
        overlap_amount = min(info.exposed_time_ms, available_compute)
        info.exposed_time_ms -= overlap_amount
        available_compute -= overlap_amount
        if info.exposed_time_ms == 0:
            info.hiding_node = node
        elif <MASK>:
            break
    if available_compute:
        self._schedule_collectives_for_overlap(node, available_compute)
    self._schedule(node)
    self.current_compute_index += 1

def _check_gcv_mode(X, gcv_mode):
    if <MASK>:
        return gcv_mode
    if X.shape[0] > X.shape[1]:
        return 'svd'
    return 'eigen'

def _remove_nan_1d(arr1d, second_arr1d=None, overwrite_input=False):
    """
    Equivalent to arr1d[~arr1d.isnan()], but in a different order

    Presumably faster as it incurs fewer copies

    Parameters
    ----------
    arr1d : ndarray
        Array to remove nans from
    second_arr1d : ndarray or None
        A second array which will have the same positions removed as arr1d.
    overwrite_input : bool
        True if `arr1d` can be modified in place

    Returns
    -------
    res : ndarray
        Array with nan elements removed
    second_res : ndarray or None
        Second array with nan element positions of first array removed.
    overwrite_input : bool
        True if `res` can be modified in place, given the constraint on the
        input
    """
    if arr1d.dtype == object:
        c = np.not_equal(arr1d, arr1d, dtype=bool)
    else:
        c = np.isnan(arr1d)
    s = np.nonzero(c)[0]
    if s.size == arr1d.size:
        warnings.warn('All-NaN slice encountered', RuntimeWarning, stacklevel=6)
        if second_arr1d is None:
            return (arr1d[:0], None, True)
        else:
            return (arr1d[:0], second_arr1d[:0], True)
    elif <MASK>:
        return (arr1d, second_arr1d, overwrite_input)
    else:
        if not overwrite_input:
            arr1d = arr1d.copy()
        enonan = arr1d[-s.size:][~c[-s.size:]]
        arr1d[s[:enonan.size]] = enonan
        if second_arr1d is None:
            return (arr1d[:-s.size], None, True)
        else:
            if not overwrite_input:
                second_arr1d = second_arr1d.copy()
            enonan = second_arr1d[-s.size:][~c[-s.size:]]
            second_arr1d[s[:enonan.size]] = enonan
            return (arr1d[:-s.size], second_arr1d[:-s.size], True)

def _solve(self, rhs, adjoint=False, adjoint_arg=False):
    diagonals = self.diagonals
    if <MASK>:
        diagonals = self._construct_adjoint_diagonals(diagonals)
    rhs_shape = array_ops.shape(rhs)
    k = self._shape_tensor(diagonals)[-1]
    broadcast_shape = array_ops.broadcast_dynamic_shape(self._shape_tensor(diagonals)[:-2], rhs_shape[:-2])
    rhs = array_ops.broadcast_to(rhs, array_ops.concat([broadcast_shape, rhs_shape[-2:]], axis=-1))
    if self.diagonals_format == _MATRIX:
        diagonals = array_ops.broadcast_to(diagonals, array_ops.concat([broadcast_shape, [k, k]], axis=-1))
    elif self.diagonals_format == _COMPACT:
        diagonals = array_ops.broadcast_to(diagonals, array_ops.concat([broadcast_shape, [3, k]], axis=-1))
    else:
        diagonals = [array_ops.broadcast_to(d, array_ops.concat([broadcast_shape, [k]], axis=-1)) for d in diagonals]
    y = linalg.tridiagonal_solve(diagonals, rhs, diagonals_format=self.diagonals_format, transpose_rhs=adjoint_arg, conjugate_rhs=adjoint_arg)
    return y

def _validate_key(ctx: click.Context, param: click.Parameter, value: t.Any) -> t.Any:
    """The ``--key`` option must be specified when ``--cert`` is a file.
    Modifies the ``cert`` param to be a ``(cert, key)`` pair if needed.
    """
    cert = ctx.params.get('cert')
    is_adhoc = cert == 'adhoc'
    try:
        import ssl
    except ImportError:
        is_context = False
    else:
        is_context = isinstance(cert, ssl.SSLContext)
    if value is not None:
        if is_adhoc:
            raise click.BadParameter('When "--cert" is "adhoc", "--key" is not used.', ctx, param)
        if <MASK>:
            raise click.BadParameter('When "--cert" is an SSLContext object, "--key" is not used.', ctx, param)
        if not cert:
            raise click.BadParameter('"--cert" must also be specified.', ctx, param)
        ctx.params['cert'] = (cert, value)
    elif cert and (not (is_adhoc or is_context)):
        raise click.BadParameter('Required when using "--cert".', ctx, param)
    return value

def _get_test_objects(self, task_type, task_id, num_gpus=0, communication=CollectiveCommunication.AUTO, use_strategy_object=False, local_mode=False):
    collective_keys = cross_device_utils.CollectiveKeys(group_key_start=10 + CollectiveAllReduceTest.collective_key_base)
    if local_mode:
        if <MASK>:
            devices = ['/device:GPU:%d' % i for i in range(num_gpus)]
        else:
            devices = ['/device:CPU:0']
        comm_options = collective_util.Options(implementation=communication)
        if use_strategy_object:
            strategy = mwms_lib.CollectiveAllReduceStrategy._from_local_devices(devices, comm_options)
            return (strategy, devices, '')
        else:
            collective_all_reduce_ops = cross_device_ops_lib.CollectiveAllReduce(devices=devices, group_size=len(devices), options=comm_options, collective_keys=collective_keys)
            return (collective_all_reduce_ops, devices, '')
    else:
        assert communication != CollectiveCommunication.NCCL
        if num_gpus:
            devices = ['/job:%s/task:%d/replica:0/device:GPU:%d' % (task_type, task_id, i) for i in range(num_gpus)]
        else:
            devices = ['/job:%s/task:%d/replica:0/device:CPU:0' % (task_type, task_id)]
        comm_options = collective_util.Options(implementation=communication)
        if use_strategy_object:
            resolver = cluster_resolver.SimpleClusterResolver(cluster_spec=multi_worker_util.normalize_cluster_spec(self._cluster_spec), task_type=task_type, task_id=task_id, num_accelerators={'GPU': num_gpus})
            strategy = mwms_lib.CollectiveAllReduceStrategy(communication_options=comm_options, cluster_resolver=resolver)
            return (strategy, devices, 'grpc://' + self._cluster_spec[task_type][task_id])
        else:
            collective_all_reduce_ops = cross_device_ops_lib.CollectiveAllReduce(devices=devices, group_size=len(devices) * NUM_WORKERS, options=comm_options, collective_keys=collective_keys)
            return (collective_all_reduce_ops, devices, 'grpc://' + self._cluster_spec[task_type][task_id])

def _take_with_fill(self, indices, fill_value=None) -> np.ndarray:
    if <MASK>:
        fill_value = self.dtype.na_value
    if indices.min() < -1:
        raise ValueError("Invalid value in 'indices'. Must be between -1 and the length of the array.")
    if indices.max() >= len(self):
        raise IndexError("out of bounds value in 'indices'.")
    if len(self) == 0:
        if (indices == -1).all():
            dtype = np.result_type(self.sp_values, type(fill_value))
            taken = np.empty_like(indices, dtype=dtype)
            taken.fill(fill_value)
            return taken
        else:
            raise IndexError('cannot do a non-empty take from an empty axes.')
    sp_indexer = self.sp_index.lookup_array(indices)
    new_fill_indices = indices == -1
    old_fill_indices = (sp_indexer == -1) & ~new_fill_indices
    if self.sp_index.npoints == 0 and old_fill_indices.all():
        taken = np.full(sp_indexer.shape, fill_value=self.fill_value, dtype=self.dtype.subtype)
    elif self.sp_index.npoints == 0:
        _dtype = np.result_type(self.dtype.subtype, type(fill_value))
        taken = np.full(sp_indexer.shape, fill_value=fill_value, dtype=_dtype)
        taken[old_fill_indices] = self.fill_value
    else:
        taken = self.sp_values.take(sp_indexer)
        m0 = sp_indexer[old_fill_indices] < 0
        m1 = sp_indexer[new_fill_indices] < 0
        result_type = taken.dtype
        if m0.any():
            result_type = np.result_type(result_type, type(self.fill_value))
            taken = taken.astype(result_type)
            taken[old_fill_indices] = self.fill_value
        if m1.any():
            result_type = np.result_type(result_type, type(fill_value))
            taken = taken.astype(result_type)
            taken[new_fill_indices] = fill_value
    return taken

def format_trace_inputs(f: NativeFunction) -> str:

    def dispatch_trace_input(arg: Argument | TensorOptionsArguments) -> Sequence[str]:
        if <MASK>:
            name = 'options'
            return [ADD_TRACE_INPUT.substitute(name=name, input='c10::optTypeMetaToScalarType(options.dtype_opt())'), ADD_TRACE_INPUT.substitute(name=name, input='options.layout()'), ADD_TRACE_INPUT.substitute(name=name, input='options.device()'), ADD_TRACE_INPUT.substitute(name=name, input='options.pinned_memory()')]
        else:
            name = arg.name
            if str(arg.type) == 'Tensor?[]':
                return [f'jit::tracer::addInputs(node, "{name}", {name});']
            else:
                return [ADD_TRACE_INPUT.substitute(name=name, input=name)]
    args: list[Argument | TensorOptionsArguments] = list(f.func.schema_order_arguments())
    if f.func.is_out_fn():
        num_out_args = len(f.func.arguments.out)
        args = args[:-num_out_args]
    trace_inputs = itertools.chain.from_iterable((dispatch_trace_input(arg) for arg in args))
    if f.func.is_out_fn():
        inplace = [ADD_TRACE_INPUT.substitute(name=f.func.arguments.out[i].name, input=f.func.arguments.out[i].name) for i in range(num_out_args)]
        has_tensor_return = any((r.type.is_tensor_like() for r in f.func.returns))
        has_tensor_input_arg = any((a.type.is_tensor_like() for a in f.func.arguments.flat_non_out))
        is_factory_method = f.category_override == 'factory' or (has_tensor_return and (not has_tensor_input_arg))
        if f.func.name.name.base == 'normal':
            is_factory_method = True
        if is_factory_method:
            outplace = [ADD_TRACE_INPUT.substitute(name='out', input='c10::optTypeMetaToScalarType(out.options().dtype_opt())'), ADD_TRACE_INPUT.substitute(name='out', input='out.options().layout()'), ADD_TRACE_INPUT.substitute(name='out', input='out.options().device()'), ADD_TRACE_INPUT.substitute(name='out', input='out.options().pinned_memory()')]
        else:
            outplace = []
        trace_inputs = itertools.chain(trace_inputs, [SELECT.substitute(cond='tracer_state->force_outplace', true='\n'.join(outplace), false='\n'.join(inplace))])
    return '\n'.join(trace_inputs)

def infer_dtype_from_scalar(val) -> tuple[DtypeObj, Any]:
    """
    Interpret the dtype from a scalar.

    Parameters
    ----------
    val : object
    """
    dtype: DtypeObj = _dtype_obj
    if isinstance(val, np.ndarray):
        if val.ndim != 0:
            msg = 'invalid ndarray passed to infer_dtype_from_scalar'
            raise ValueError(msg)
        dtype = val.dtype
        val = lib.item_from_zerodim(val)
    elif <MASK>:
        dtype = _dtype_obj
        if using_string_dtype():
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
    elif isinstance(val, (np.datetime64, dt.datetime)):
        try:
            val = Timestamp(val)
        except OutOfBoundsDatetime:
            return (_dtype_obj, val)
        if val is NaT or val.tz is None:
            val = val.to_datetime64()
            dtype = val.dtype
        else:
            dtype = DatetimeTZDtype(unit=val.unit, tz=val.tz)
    elif isinstance(val, (np.timedelta64, dt.timedelta)):
        try:
            val = Timedelta(val)
        except (OutOfBoundsTimedelta, OverflowError):
            dtype = _dtype_obj
        else:
            if val is NaT:
                val = np.timedelta64('NaT', 'ns')
            else:
                val = val.asm8
            dtype = val.dtype
    elif is_bool(val):
        dtype = np.dtype(np.bool_)
    elif is_integer(val):
        if isinstance(val, np.integer):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.int64)
        try:
            np.array(val, dtype=dtype)
        except OverflowError:
            dtype = np.array(val).dtype
    elif is_float(val):
        if isinstance(val, np.floating):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.float64)
    elif is_complex(val):
        dtype = np.dtype(np.complex128)
    if isinstance(val, Period):
        dtype = PeriodDtype(freq=val.freq)
    elif isinstance(val, Interval):
        subtype = infer_dtype_from_scalar(val.left)[0]
        dtype = IntervalDtype(subtype=subtype, closed=val.closed)
    return (dtype, val)

