def _fallback_converter(pfor_input: _PforInput, root_cause='', warn=False):
    msg = f'Using a while_loop for converting {pfor_input.op_type} cause {root_cause}'
    if warn:
        logging.warning(msg)
    else:
        logging.debug(msg)
    output_dtypes = [x.dtype for x in pfor_input.outputs]
    iter_vec = pfor_input.pfor.loop_len_vector
    iter_vec_value = tensor_util.constant_value(iter_vec)
    if <MASK>:
        iters = iter_vec_value[0].item()
    else:
        iters = iter_vec[0]

    def while_body(i, *ta_list):
        """Body of while loop."""
        inputs = [x[i, ...] if stacked else x for (x, stacked, _) in pfor_input.inputs]
        op_outputs = _create_op(pfor_input.op_type, inputs, output_dtypes, attrs=pfor_input.op.node_def.attr).outputs
        outputs = []
        for (out, ta) in zip(op_outputs, ta_list):
            assert isinstance(out, tensor_lib.Tensor)
            outputs.append(ta.write(i, out))
        return tuple([i + 1] + outputs)
    ta_list = while_loop.while_loop(lambda i, *ta: i < iters, while_body, [0] + [tensor_array_ops.TensorArray(dtype, iters) for dtype in output_dtypes])[1:]
    return tuple([wrap(ta.stack(), True) for ta in ta_list])

def compute_output_shape(self, input_shape):
    input_shape = tensor_shape.TensorShape(input_shape).as_list()
    if self.data_format == 'channels_first':
        if input_shape[2] is not None:
            dim1 = input_shape[2] + self.padding[0][0] + self.padding[0][1]
        else:
            dim1 = None
        if input_shape[3] is not None:
            dim2 = input_shape[3] + self.padding[1][0] + self.padding[1][1]
        else:
            dim2 = None
        if <MASK>:
            dim3 = input_shape[4] + self.padding[2][0] + self.padding[2][1]
        else:
            dim3 = None
        return tensor_shape.TensorShape([input_shape[0], input_shape[1], dim1, dim2, dim3])
    elif self.data_format == 'channels_last':
        if input_shape[1] is not None:
            dim1 = input_shape[1] + self.padding[0][0] + self.padding[0][1]
        else:
            dim1 = None
        if input_shape[2] is not None:
            dim2 = input_shape[2] + self.padding[1][0] + self.padding[1][1]
        else:
            dim2 = None
        if input_shape[3] is not None:
            dim3 = input_shape[3] + self.padding[2][0] + self.padding[2][1]
        else:
            dim3 = None
        return tensor_shape.TensorShape([input_shape[0], dim1, dim2, dim3, input_shape[4]])

def _find_buckets(self, collective_group: OrderedSet[fx.Node]) -> list[CollBucket]:
    """Find valid buckets within a group of similar collectives."""
    max_bucket_bytes = int(self.max_bucket_memory_gb * 1024 * 1024 * 1024)
    buckets = []
    processed: OrderedSet[fx.Node] = OrderedSet()
    for start_node in collective_group:
        if start_node in processed:
            continue
        bucket_info = CollBucket(collectives=[start_node], total_bytes=self.collective_info[start_node].size_bytes)
        processed.add(start_node)
        start_node_idx = self.node_idx[start_node]
        for candidate in collective_group:
            if candidate in processed:
                continue
            candidate_idx = self.node_idx[candidate]
            if abs(candidate_idx - start_node_idx) > self.max_coll_distance:
                continue
            candidate_bytes = self.collective_info[candidate].size_bytes
            if bucket_info.total_bytes + candidate_bytes > max_bucket_bytes:
                continue
            if <MASK>:
                bucket_info.collectives.append(candidate)
                bucket_info.total_bytes += candidate_bytes
                processed.add(candidate)
        if len(bucket_info.collectives) > 1:
            buckets.append(bucket_info)
    return buckets

def _ensure_iterable_column_indexer(self, column_indexer):
    """
        Ensure that our column indexer is something that can be iterated over.
        """
    ilocs: Sequence[int | np.integer] | np.ndarray | range
    if <MASK>:
        ilocs = [column_indexer]
    elif isinstance(column_indexer, slice):
        ilocs = range(len(self.obj.columns))[column_indexer]
    elif isinstance(column_indexer, np.ndarray) and column_indexer.dtype.kind == 'b':
        ilocs = np.arange(len(column_indexer))[column_indexer]
    else:
        ilocs = column_indexer
    return ilocs

def unscale_(self, optimizer: torch.optim.Optimizer) -> None:
    if not self._enabled:
        return
    self._check_scale_growth_tracker('unscale_')
    optimizer_state = self._per_optimizer_states[id(optimizer)]
    if optimizer_state['stage'] is OptState.UNSCALED:
        raise RuntimeError('unscale_() has already been called on this optimizer since the last update().')
    elif optimizer_state['stage'] is OptState.STEPPED:
        raise RuntimeError('unscale_() is being called after step().')
    if self._scale is None:
        raise AssertionError('Expected _scale to be initialized, got None')
    inv_scale = self._scale.double().reciprocal().float()
    found_inf = torch.full((1,), 0.0, dtype=torch.float32, device=self._scale.device)
    optimizer_state['found_inf_per_device'] = self._unscale_grads_(optimizer, inv_scale, found_inf, True)
    optimizer_state['stage'] = OptState.UNSCALED
    optimizer_state = self._per_optimizer_states[id(optimizer)]
    works = []
    found_inf_on_cpus = []
    found_inf_on_devices = []
    for found_inf in optimizer_state['found_inf_per_device'].values():
        if self._device != 'cpu' and found_inf.device.type == 'cpu':
            found_inf_on_cpus.append(found_inf)
            found_inf_on_device = found_inf.to(self._device)
            found_inf_on_devices.append(found_inf_on_device)
            works.append(dist.all_reduce(found_inf_on_device, async_op=True, group=self.process_group))
        else:
            works.append(dist.all_reduce(found_inf, async_op=True, group=self.process_group))
    for work in works:
        work.wait()
    if <MASK>:
        torch._foreach_copy_(found_inf_on_cpus, found_inf_on_devices)

