    return None

@classmethod
def from_value(cls, value):
    if <MASK>:
        return cls(value.shape, value.dtype)
    if isinstance(value, SparseTensorValue):
        if isinstance(value.values, np.ndarray):
            return cls(value.dense_shape, value.values.dtype)
        else:
            return cls.from_value(SparseTensor.from_value(value))
    else:
        raise TypeError(f'Expected SparseTensor or SparseTensorValue. Received: {value} of type {type(value).__name__}.')

@classmethod
def from_value(cls, value: None | torch._C.Value | torch.Tensor, default=None) -> JitScalarType:
    """Create a JitScalarType from an value's scalar type.

        Args:
            value: An object to fetch scalar type from.
            default: The JitScalarType to return if a valid scalar cannot be fetched from value

        Returns:
            JitScalarType.

        Raises:
            OnnxExporterError: if value does not have a valid scalar type and default is None.
            SymbolicValueError: when value.type()'s info are empty and default is None
        """
    if not isinstance(value, (torch._C.Value, torch.Tensor)) or (isinstance(value, torch._C.Value) and value.node().mustBeNone()):
        if default is None:
            raise errors.OnnxExporterError('value must be either torch._C.Value or torch.Tensor objects.')
        elif not isinstance(default, JitScalarType):
            raise errors.OnnxExporterError('default value must be a JitScalarType object.')
        return default
    if isinstance(value, torch.Tensor):
        return cls.from_dtype(value.dtype)
    if <MASK>:
        try:
            return cls.from_dtype(value.type().getElementType().dtype())
        except RuntimeError:
            return cls._from_name(str(value.type().getElementType()))
    if isinstance(value.type(), torch._C.OptionalType):
        if value.type().getElementType().dtype() is None:
            if isinstance(default, JitScalarType):
                return default
            raise errors.OnnxExporterError('default value must be a JitScalarType object.')
        return cls.from_dtype(value.type().getElementType().dtype())
    scalar_type = None
    if value.node().kind() != 'prim::Constant' or not isinstance(value.type(), torch._C.NoneType):
        scalar_type = value.type().scalarType()
    if scalar_type is not None:
        return cls._from_name(scalar_type)
    if default is not None:
        return default
    raise errors.SymbolicValueError(f"Cannot determine scalar type for this '{type(value.type())}' instance and a default value was not provided.", value)

def _load_imgs(file_paths, slice_, color, resize):
    """Internally used to load images"""
    try:
        from PIL import Image
    except ImportError:
        raise ImportError('The Python Imaging Library (PIL) is required to load data from jpeg files. Please refer to https://pillow.readthedocs.io/en/stable/installation.html for installing PIL.')
    default_slice = (slice(0, 250), slice(0, 250))
    if slice_ is None:
        slice_ = default_slice
    else:
        slice_ = tuple((s or ds for (s, ds) in zip(slice_, default_slice)))
    (h_slice, w_slice) = slice_
    h = (h_slice.stop - h_slice.start) // (h_slice.step or 1)
    w = (w_slice.stop - w_slice.start) // (w_slice.step or 1)
    if <MASK>:
        resize = float(resize)
        h = int(resize * h)
        w = int(resize * w)
    n_faces = len(file_paths)
    if not color:
        faces = np.zeros((n_faces, h, w), dtype=np.float32)
    else:
        faces = np.zeros((n_faces, h, w, 3), dtype=np.float32)
    for (i, file_path) in enumerate(file_paths):
        if i % 1000 == 0:
            logger.debug('Loading face #%05d / %05d', i + 1, n_faces)
        with Image.open(file_path) as pil_img:
            pil_img = pil_img.crop((w_slice.start, h_slice.start, w_slice.stop, h_slice.stop))
            if resize is not None:
                pil_img = pil_img.resize((w, h))
            face = np.asarray(pil_img, dtype=np.float32)
        if face.ndim == 0:
            raise RuntimeError('Failed to read the image file %s, Please make sure that libjpeg is installed' % file_path)
        face /= 255.0
        if not color:
            face = face.mean(axis=2)
        faces[i, ...] = face
    return faces

def build_all_signature_defs(receiver_tensors, export_outputs, receiver_tensors_alternatives=None, serving_only=True):
    """Build `SignatureDef`s for all export outputs.

  Args:
    receiver_tensors: a `Tensor`, or a dict of string to `Tensor`, specifying
      input nodes where this receiver expects to be fed by default.  Typically,
      this is a single placeholder expecting serialized `tf.Example` protos.
    export_outputs: a dict of ExportOutput instances, each of which has
      an as_signature_def instance method that will be called to retrieve
      the signature_def for all export output tensors.
    receiver_tensors_alternatives: a dict of string to additional
      groups of receiver tensors, each of which may be a `Tensor` or a dict of
      string to `Tensor`.  These named receiver tensor alternatives generate
      additional serving signatures, which may be used to feed inputs at
      different points within the input receiver subgraph.  A typical usage is
      to allow feeding raw feature `Tensor`s *downstream* of the
      tf.io.parse_example() op.  Defaults to None.
    serving_only: boolean; if true, resulting signature defs will only include
      valid serving signatures. If false, all requested signatures will be
      returned.

  Returns:
    signature_def representing all passed args.

  Raises:
    ValueError: if export_outputs is not a dict
  """
    if not isinstance(receiver_tensors, dict):
        receiver_tensors = {SINGLE_RECEIVER_DEFAULT_NAME: receiver_tensors}
    if export_outputs is None or not isinstance(export_outputs, dict):
        raise ValueError(f'`export_outputs` must be a dict. Received {export_outputs} with type {type(export_outputs).__name__}.')
    signature_def_map = {}
    excluded_signatures = {}
    input_tensors = receiver_tensors.values()
    for (output_key, export_output) in export_outputs.items():
        signature_name = '{}'.format(output_key or 'None')
        try:
            signature = export_output.as_signature_def(receiver_tensors)
            _ensure_servable(input_tensors, signature.outputs)
            signature_def_map[signature_name] = signature
        except ValueError as e:
            excluded_signatures[signature_name] = str(e)
    if receiver_tensors_alternatives:
        for (receiver_name, receiver_tensors_alt) in receiver_tensors_alternatives.items():
            if <MASK>:
                receiver_tensors_alt = {SINGLE_RECEIVER_DEFAULT_NAME: receiver_tensors_alt}
            alt_input_tensors = receiver_tensors_alt.values()
            for (output_key, export_output) in export_outputs.items():
                signature_name = '{}:{}'.format(receiver_name or 'None', output_key or 'None')
                try:
                    signature = export_output.as_signature_def(receiver_tensors_alt)
                    _ensure_servable(alt_input_tensors, signature.outputs)
                    signature_def_map[signature_name] = signature
                except ValueError as e:
                    excluded_signatures[signature_name] = str(e)
    _log_signature_report(signature_def_map, excluded_signatures)
    if serving_only:
        signature_def_map = {k: v for (k, v) in signature_def_map.items() if signature_def_utils.is_valid_signature(v)}
    return signature_def_map

@Appender(_read_method_doc)
def read(self, nrows: int | None=None) -> pd.DataFrame:
    if nrows is None:
        nrows = self.nobs
    read_lines = min(nrows, self.nobs - self._lines_read)
    read_len = read_lines * self.record_length
    if read_len <= 0:
        self.close()
        raise StopIteration
    raw = self.filepath_or_buffer.read(read_len)
    data = np.frombuffer(raw, dtype=self._dtype, count=read_lines)
    df_data = {}
    for (j, x) in enumerate(self.columns):
        vec = data['s' + str(j)]
        ntype = self.fields[j]['ntype']
        if <MASK>:
            vec = _handle_truncated_float_vec(vec, self.fields[j]['field_length'])
            miss = self._missing_double(vec)
            v = _parse_float_vec(vec)
            v[miss] = np.nan
        elif self.fields[j]['ntype'] == 'char':
            v = [y.rstrip() for y in vec]
            if self._encoding is not None:
                v = [y.decode(self._encoding) for y in v]
        df_data.update({x: v})
    df = pd.DataFrame(df_data)
    if self._index is None:
        df.index = pd.Index(range(self._lines_read, self._lines_read + read_lines))
    else:
        df = df.set_index(self._index)
    self._lines_read += read_lines
    return df

def _sqlalchemy_type(self, col: Index | Series):
    dtype: DtypeArg = self.dtype or {}
    if is_dict_like(dtype):
        dtype = cast(dict, dtype)
        if col.name in dtype:
            return dtype[col.name]
    col_type = lib.infer_dtype(col, skipna=True)
    from sqlalchemy.types import TIMESTAMP, BigInteger, Boolean, Date, DateTime, Float, Integer, SmallInteger, Text, Time
    if col_type in ('datetime64', 'datetime'):
        try:
            if col.dt.tz is not None:
                return TIMESTAMP(timezone=True)
        except AttributeError:
            if getattr(col, 'tz', None) is not None:
                return TIMESTAMP(timezone=True)
        return DateTime
    if col_type == 'timedelta64':
        warnings.warn("the 'timedelta' type is not supported, and will be written as integer values (ns frequency) to the database.", UserWarning, stacklevel=find_stack_level())
        return BigInteger
    elif col_type == 'floating':
        if col.dtype == 'float32':
            return Float(precision=23)
        else:
            return Float(precision=53)
    elif col_type == 'integer':
        if col.dtype.name.lower() in ('int8', 'uint8', 'int16'):
            return SmallInteger
        elif col.dtype.name.lower() in ('uint16', 'int32'):
            return Integer
        elif col.dtype.name.lower() == 'uint64':
            raise ValueError('Unsigned 64 bit integer datatype is not supported')
        else:
            return BigInteger
    elif col_type == 'boolean':
        return Boolean
    elif <MASK>:
        return Date
    elif col_type == 'time':
        return Time
    elif col_type == 'complex':
        raise ValueError('Complex datatypes not supported')
    return Text

def setup(self, dtype):
    if dtype == 'numeric':
        self.series = pd.Series([1, 2, 3])
    elif <MASK>:
        self.series = pd.Series(['a', 'b', 'c'], dtype=object)
    elif dtype == 'category':
        self.series = pd.Series(['a', 'b', 'c'], dtype='category')
    elif dtype == 'datetime64':
        self.series = pd.Series(pd.date_range('2013', periods=3))
    elif dtype == 'datetime64tz':
        self.series = pd.Series(pd.date_range('2013', periods=3, tz='UTC'))

def auto_shard_dataset(dataset, num_shards, index, num_replicas_in_sync=None):
    """Shard the input pipeline by sharding the underlying list of files.

  Args:
    dataset: A `tf.data.Dataset` instance, typically the result of a bunch of
      dataset transformations.
    num_shards: A `tf.int64` scalar `tf.Tensor`, representing the number of
        shards operating in parallel. Same usage as in `tf.data.Dataset.shard`.
    index: A `tf.int64` scalar `tf.Tensor`, representing the worker index.
      Same usage as in `tf.data.Dataset.shard`.
    num_replicas_in_sync: An integer representing the total number of replicas
      across all workers. This is used in the rewrite when sharding by data.

  Returns:
    A modified `Dataset` obtained by updating the pipeline sharded by the
    files. The input dataset will be returned if we cannot automatically
    determine a good way to shard the input dataset.
  """
    if isinstance(dataset, distribute_types.DistributedDatasetInterface):
        return dataset.auto_shard(num_shards, index)
    if dataset.options().experimental_distribute.auto_shard_policy != AutoShardPolicy.OFF:
        if <MASK>:
            num_replicas_in_sync = 1
        if isinstance(dataset, data_types.DatasetV1):
            return distribute._AutoShardDatasetV1(dataset, num_shards, index, num_replicas_in_sync)
        else:
            return distribute._AutoShardDataset(dataset, num_shards, index, num_replicas_in_sync)
    else:
        return dataset

