@_onnx_symbolic('aten::__or_')
def __or_(g: jit_utils.GraphContext, input, other):
    if <MASK>:
        raise errors.SymbolicValueError('ONNX export does NOT support exporting bitwise OR for non-boolean input values', input)
    if not symbolic_helper._is_bool(other):
