def print_op_coverage_summary(model: nn.Module, args, kwargs, *, output_csv=False):
    """
    Util to print the operator coverage summary of a certain model with tabulute.

    Must have tabulate module installed.
    """
    import csv
    from tabulate import tabulate
    (fwd_graph, bwd_graph) = get_inductor_decomp_graphs(model, args, kwargs)
    op_counts = {}
    for node in fwd_graph.graph.nodes:
        if node.op == 'call_function' and isinstance(node.target, torch._ops.OpOverload):
            if <MASK>:
                op_counts[node.target] = 0
            op_counts[node.target] += 1
    for node in bwd_graph.graph.nodes:
        if node.op == 'call_function' and isinstance(node.target, torch._ops.OpOverload):
            if node.target not in op_counts:
                op_counts[node.target] = 0
            op_counts[node.target] += 1
    op_infos = []
    for (op, count) in op_counts.items():
        supported = op in DTensor._op_dispatcher.sharding_propagator.op_to_rules
        op_infos.append([op, str(op._schema), count, supported])
    count_idx = 2
    op_infos.sort(key=itemgetter(count_idx), reverse=True)
    headers = ['Operator', 'Schema', 'Total Count', 'Supported']
    print(tabulate(op_infos, headers=headers))
    if output_csv:
        with open('op_summary.csv', 'w', newline='') as csv_file:
            csv_writer = csv.writer(csv_file)
            csv_writer.writerow(headers)
            for row in op_infos:
                csv_writer.writerow(row)

def CheckInputFromValidContext(op, input_op):
    """Returns whether `input_op` can be used from `op`s context.

  Conceptually, only inputs from op's while context or any ancestor while
  context (including outside of any context) are valid. In practice, there are
  many other edge cases as well.

  Args:
    op: Operation
    input_op: Operation

  Raises:
    ValueError: if input_op is from an invalid context.
  """
    op_ctxt = op._get_control_flow_context()
    input_ctxt = GetOutputContext(input_op)
    valid = False
    if not input_ctxt:
        valid = True
    elif op_ctxt is input_ctxt:
        valid = True
    else:
        while_ctxt = GetContainingWhileContext(op_ctxt)
        input_while_ctxt = GetContainingWhileContext(input_ctxt)
        if while_ctxt is None:
            if input_while_ctxt is None:
                valid = True
            if <MASK>:
                valid = True
            if IsSwitch(op):
                valid = True
        elif IsContainingContext(while_ctxt, input_while_ctxt):
            valid = True
        elif while_ctxt.grad_state and IsContainingContext(while_ctxt.grad_state.forward_context, input_while_ctxt):
            valid = True
        elif while_ctxt.grad_state and while_ctxt.grad_state.forward_context is input_while_ctxt._outer_context:
            valid = True
        elif input_while_ctxt.grad_state and input_while_ctxt.grad_state.forward_context is while_ctxt:
            valid = True
        elif input_while_ctxt.grad_state and input_ctxt.grad_state.forward_context.grad_state and (input_ctxt.grad_state.forward_context.grad_state.forward_context is while_ctxt):
            valid = True
    if not valid:
        if while_ctxt:
            error_msg = f"Cannot use '{input_op.name}' as input to '{op.name}' because they are in different while loops."
        else:
            error_msg = f"Cannot use '{input_op.name}' as input to '{op.name}' because '{input_op.name}' is in a while loop."
        log_msg = error_msg
        log_msg += '\n\n%s while context: %s' % (op.name, while_ctxt)
        log_msg += '\n%s while context: %s' % (input_op.name, input_while_ctxt)
        log_msg += '\n\nTraceback for %s:\n%s\nTraceback for %s:\n%s\n' % (op.name, ''.join(traceback.format_list(op.traceback)), input_op.name, ''.join(traceback.format_list(input_op.traceback)))
        logging.info(log_msg)
        raise ValueError(error_msg + ' See info log for more details.')

def tf_tensor_list_new(elements, element_dtype=None, element_shape=None):
    """Overload of new_list that stages a Tensor list creation."""
    if tensor_util.is_tf_type(elements):
        if element_shape is not None:
            raise ValueError('element shape may not be specified when creating list from tensor')
        element_shape = array_ops.shape(elements)[1:]
        l = list_ops.tensor_list_from_tensor(elements, element_shape=element_shape)
        return l
    elements = tuple((ops.convert_to_tensor(el) for el in elements))
    all_dtypes = set((el.dtype for el in elements))
    if len(all_dtypes) == 1:
        inferred_dtype = tuple(all_dtypes)[0]
        if element_dtype is not None and element_dtype != inferred_dtype:
            raise ValueError('incompatible dtype; specified: {}, inferred from {}: {}'.format(element_dtype, elements, inferred_dtype))
    elif all_dtypes:
        if element_dtype is not None:
            raise ValueError('specified dtype {} is inconsistent with that of elements {}'.format(element_dtype, elements))
        inferred_dtype = dtypes.variant
    else:
        inferred_dtype = dtypes.variant
    all_shapes = set((tuple(el.shape.as_list()) for el in elements))
    if len(all_shapes) == 1:
        inferred_shape = array_ops.shape(elements[0])
        if element_shape is not None and element_shape != inferred_shape:
            raise ValueError('incompatible shape; specified: {}, inferred from {}: {}'.format(element_shape, elements, inferred_shape))
    elif all_shapes:
        if element_shape is not None:
            raise ValueError('specified shape {} is inconsistent with that of elements {}'.format(element_shape, elements))
        inferred_shape = constant_op.constant(-1)
    else:
        inferred_shape = constant_op.constant(-1)
    if <MASK>:
        element_dtype = inferred_dtype
    if element_shape is None:
        element_shape = inferred_shape
    element_shape = ops.convert_to_tensor(element_shape, dtype=dtypes.int32)
    l = list_ops.empty_tensor_list(element_shape=element_shape, element_dtype=element_dtype)
    for el in elements:
        l = list_ops.tensor_list_push_back(l, el)
    return l

def set_state(self, state: bytes, token: Optional[Token]=None) -> Optional[tuple[bytes, Token, bool]]:
    """See base class."""
    base64_state = b64encode(state).decode()
    kwargs = {}

    def get_state():
        result = self.get_state()
        if result is not None:
            return (*result, False)
        return None
    if <MASK>:
        try:
            token = int(token)
        except ValueError:
            return get_state()
    if token:
        kwargs['prevIndex'] = token
    else:
        kwargs['prevExist'] = False
    try:
        result = self._client.write(self._key, base64_state, self._ttl, **kwargs)
    except (etcd.EtcdAlreadyExist, etcd.EtcdCompareFailed):
        result = None
    except (etcd.EtcdException, urllib3.exceptions.TimeoutError) as exc:
        raise RendezvousConnectionError('The connection to etcd has failed. See inner exception for details.') from exc
    if result is None:
        return get_state()
    tmp = (*self._decode_state(result), True)
    return tmp

def _match(self, node: torch.fx.Node, ctx: MatchContext) -> MatchResult:
    if not self._match_fns(node) or len(node.args) != len(self.args):
        return FailedMatch('function_mismatch: node={}, pattern={}', node, self)
    if not self._match_users(node, ctx):
        return FailedMatch('multiple_users {}', self)
    _args = node.args
    _kwargs = node.kwargs
    if <MASK>:
        from torch.fx.operator_schemas import normalize_function
        assert callable(node.target)
        normalized_args_and_kwargs = normalize_function(node.target, node.args, node.kwargs)
        if normalized_args_and_kwargs is None:
            return FailedMatch('function_mismatch: node={}, pattern={}', node, self)
        else:
            (_args, _kwargs) = normalized_args_and_kwargs
            if len(_args) == len(self.args) and len(_kwargs) >= len(self.kwargs):
                _kwargs = {i: _kwargs[i] for i in _kwargs if i in self.kwargs}
            else:
                return FailedMatch('function_mismatch: node={}, pattern={}', node, self)
    else:
        _kwargs = {i: _kwargs[i] for i in _kwargs if i in self.kwargs}
    (node_items, node_spec) = self.flatten(_args, _kwargs)
    (self_items, self_spec) = self.flat_args_kwargs
    if node_spec != self_spec:
        return FailedMatch('args_structure {} {}', node_spec, self_spec)
    assert len(node_items) == len(self_items)
    m = Match(ctx, self)
    for (i, pattern, child_node) in zip(itertools.count(), self_items, node_items):
        if isinstance(pattern, PatternExpr):
            child_match = ctx.match(pattern, child_node)
            if not is_match(child_match):
                return child_match
            m.extend(child_match)
        elif isinstance(child_node, torch.fx.Node) or child_node != pattern:
            return FailedMatch('constant_args: {} {!r}!={pattern!r}', node, child_node)
    m.nodes.append(node)
    m.targets[self] = node.target
    return m

def _build_app_dict(self, request, label=None):
    """
        Build the app dictionary. The optional `label` parameter filters models
        of a specific app.
        """
    app_dict = {}
    if label:
        models = {m: m_a for (m, m_a) in self._registry.items() if m._meta.app_label == label}
    else:
        models = self._registry
    for (model, model_admin) in models.items():
        app_label = model._meta.app_label
        has_module_perms = model_admin.has_module_permission(request)
        if <MASK>:
            continue
        perms = model_admin.get_model_perms(request)
        if True not in perms.values():
            continue
        info = (app_label, model._meta.model_name)
        model_dict = {'model': model, 'name': capfirst(model._meta.verbose_name_plural), 'object_name': model._meta.object_name, 'perms': perms, 'admin_url': None, 'add_url': None}
        if perms.get('change') or perms.get('view'):
            model_dict['view_only'] = not perms.get('change')
            try:
                model_dict['admin_url'] = reverse('admin:%s_%s_changelist' % info, current_app=self.name)
            except NoReverseMatch:
                pass
        if perms.get('add'):
            try:
                model_dict['add_url'] = reverse('admin:%s_%s_add' % info, current_app=self.name)
            except NoReverseMatch:
                pass
        if app_label in app_dict:
            app_dict[app_label]['models'].append(model_dict)
        else:
            app_dict[app_label] = {'name': apps.get_app_config(app_label).verbose_name, 'app_label': app_label, 'app_url': reverse('admin:app_list', kwargs={'app_label': app_label}, current_app=self.name), 'has_module_perms': has_module_perms, 'models': [model_dict]}
    return app_dict

@classmethod
def get_atom_coltype(cls, kind: str) -> type[Col]:
    """return the PyTables column class for this column"""
    if kind.startswith('uint'):
        k4 = kind[4:]
        col_name = f'UInt{k4}Col'
    elif <MASK>:
        col_name = 'Int64Col'
    else:
        kcap = kind.capitalize()
        col_name = f'{kcap}Col'
    return getattr(_tables(), col_name)

def __new__(subtype, data, dtype=None, copy=True):
    warnings.warn('the matrix subclass is not the recommended way to represent matrices or deal with linear algebra (see https://docs.scipy.org/doc/numpy/user/numpy-for-matlab-users.html). Please adjust your code to use regular ndarray.', PendingDeprecationWarning, stacklevel=2)
    if isinstance(data, matrix):
        dtype2 = data.dtype
        if dtype is None:
            dtype = dtype2
        if dtype2 == dtype and (not copy):
            return data
        return data.astype(dtype)
    if isinstance(data, N.ndarray):
        if dtype is None:
            intype = data.dtype
        else:
            intype = N.dtype(dtype)
        new = data.view(subtype)
        if intype != data.dtype:
            return new.astype(intype)
        if copy:
            return new.copy()
        else:
            return new
    if isinstance(data, str):
        data = _convert_from_string(data)
    copy = None if not copy else True
    arr = N.array(data, dtype=dtype, copy=copy)
    ndim = arr.ndim
    shape = arr.shape
    if ndim > 2:
        raise ValueError('matrix must be 2-dimensional')
    elif ndim == 0:
        shape = (1, 1)
    elif ndim == 1:
        shape = (1, shape[0])
    order = 'C'
    if ndim == 2 and arr.flags.fortran:
        order = 'F'
    if <MASK>:
        arr = arr.copy()
    ret = N.ndarray.__new__(subtype, shape, arr.dtype, buffer=arr, order=order)
    return ret

def compare(all_dict, others, names, module_name):
    """
    Return sets of objects from all_dict.
    Will return three sets:
     {in module_name.__all__},
     {in REFGUIDE*},
     and {missing from others}

    Parameters
    ----------
    all_dict : list
        List of non deprecated sub modules for module_name
    others : list
        List of sub modules for module_name
    names : set
        Set of function names or special directives present in
        docstring of module_name
    module_name : ModuleType

    Returns
    -------
    only_all : set
    only_ref : set
    missing : set
    """
    only_all = set()
    for name in all_dict:
        if name not in names:
            for pat in REFGUIDE_AUTOSUMMARY_SKIPLIST:
                if <MASK>:
                    break
            else:
                only_all.add(name)
    only_ref = set()
    missing = set()
    for name in names:
        if name not in all_dict:
            for pat in REFGUIDE_ALL_SKIPLIST:
                if re.match(pat, module_name + '.' + name):
                    if name not in others:
                        missing.add(name)
                    break
            else:
                only_ref.add(name)
    return (only_all, only_ref, missing)

def forward(self, x, opt_1, opt_2, opt_nested):
    x = F.relu(self.fc1(x))
    x = self.fc2(x)
    if opt_1 is None:
        opt_1 = self.__init_opt()
    if opt_2 is None:
        opt_2 = self.__init_opt()
    if <MASK>:
        opt_nested = self.__init_opt()
    return (x, opt_1, opt_2, {'tensor': opt_nested})

@substitute_in_graph(itertools.islice, is_embedded_type=True)
def islice(iterable: Iterable[_T], /, *args: int | None) -> Iterator[_T]:
    s = slice(*args)
    start = 0 if s.start is None else s.start
    stop = s.stop
    step = 1 if s.step is None else s.step
    if start < 0 or (stop is not None and stop < 0) or step <= 0:
        raise ValueError('Indices for islice() must be None or an integer: 0 <= x <= sys.maxsize.')
    if <MASK>:
        next_i = start
        for (i, element) in enumerate(iterable):
            if i == next_i:
                yield element
                next_i += step
    else:
        indices = range(max(start, stop))
        next_i = start
        for (i, element) in zip(indices, iterable):
            if i == next_i:
                yield element
                next_i += step

def _modify_input_for_dct(signals, n=None):
    """Pad or trim the provided NumPy array's innermost axis to length n."""
    signal = np.array(signals)
    if n is None or n == signal.shape[-1]:
        signal_mod = signal
    elif n >= 1:
        signal_len = signal.shape[-1]
        if <MASK>:
            signal_mod = signal[..., 0:n]
        else:
            output_shape = list(signal.shape)
            output_shape[-1] = n
            signal_mod = np.zeros(output_shape)
            signal_mod[..., 0:signal.shape[-1]] = signal
    if n:
        assert signal_mod.shape[-1] == n
    return signal_mod

def AddOp(self, op: ops.Operation):
    """Create op in XLACompileContext and notifies outer context recursively."""
    if op.type in _DENYLISTED_OPS:
        logging.error('Operation of type %s (%s) is not supported in XLA. Execution will fail if this op is used in the graph. ', op.type, op.name)
    if op.type in _UNSUPPORTED_OPS:
        self._unsupported_ops.append(op)
    if any((x.dtype._is_ref_dtype for x in op.inputs)):
        raise NotImplementedError('Non-resource Variables are not supported inside XLA computations (operator name: %s)' % op.name)
    if _XLA_COMPILE_ATTR in op.node_def.attr:
        raise ValueError('XLA compiled computations cannot be nested, (operator name: %s)' % op.name)
    op._set_attr(_XLA_COMPILE_ATTR, attr_value_pb2.AttrValue(s=self._name_as_bytes))
    op.graph.prevent_feeding(op)
    op.graph.prevent_fetching(op)
    (internal_control_inputs, external_control_inputs) = self._RemoveExternalControlEdges(op)
    if not op.inputs:
        if <MASK>:
            op._add_control_input(self._pivot)
    else:
        for index in range(len(op.inputs)):
            x = op.inputs[index]
            real_x = self.AddValue(x)
            if real_x is not x:
                op._update_input(index, real_x)
    if external_control_inputs:
        with ops.control_dependencies(None):
            self.Enter()
            external_control_inputs = [array_ops.identity(x.outputs[0]).op for x in external_control_inputs if x.outputs]
            self.Exit()
        op._add_control_inputs(external_control_inputs)
    output_names = [x.name for x in op.outputs]
    context = self
    while context is not None:
        context._values.update(output_names)
        context = context._outer_context
    if self._outer_context:
        self._outer_context.AddInnerOp(op)

def _orthogonal_kernel(self, ksize, cin, cout):
    """Construct orthogonal kernel for convolution.

    Args:
      ksize: Kernel size.
      cin: Number of input channels.
      cout: Number of output channels.

    Returns:
      An [ksize, ksize, ksize, cin, cout] orthogonal kernel.
    Raises:
      ValueError: If cin > cout.
    """
    if <MASK>:
        raise ValueError(f'The number of input channels (cin={cin}) cannot exceed the number of output channels (cout={cout}).')
    orth = self._orthogonal_matrix(cout)[0:cin, :]
    if ksize == 1:
        return array_ops.expand_dims(array_ops.expand_dims(array_ops.expand_dims(orth, 0), 0), 0)
    p = self._block_orth(self._symmetric_projection(cout), self._symmetric_projection(cout), self._symmetric_projection(cout))
    for _ in range(ksize - 2):
        temp = self._block_orth(self._symmetric_projection(cout), self._symmetric_projection(cout), self._symmetric_projection(cout))
        p = self._matrix_conv(p, temp)
    for i in range(ksize):
        for j in range(ksize):
            for k in range(ksize):
                p[i, j, k] = math_ops.matmul(orth, p[i, j, k])
    return self._dict_to_tensor(p, ksize, ksize, ksize)

