@property
def static_nrows(self):
    """The number of rows in this partition, if statically known.

    ```python
    self.row_lengths().shape == [self.static_nrows]
    self.row_starts().shape == [self.static_nrows]
    self.row_limits().shape == [self.static_nrows]
    self.row_splits().shape == [self.static_nrows + 1]
    ```

    Returns:
      The number of rows in this partition as an `int` (if statically known);
      or `None` (otherwise).
    """
    if self._row_splits is not None:
        nrows_plus_one = tensor_shape.dimension_value(self._row_splits.shape[0])
        if nrows_plus_one is not None:
            return nrows_plus_one - 1
    if self._row_lengths is not None:
        nrows = tensor_shape.dimension_value(self._row_lengths.shape[0])
        if <MASK>:
            return nrows
    if self._nrows is not None:
        return tensor_util.constant_value(self._nrows)
    return None

def codegen_static_numels(self, code):
    """
        We get a small speedup from hard coding numels if they are static.

        This code stomps on the passed-in values by writing an constant to the top of the kernel.

        In a kernel like:
        def KERNEL_NAME(in_ptr0, in_ptr1, out_ptr2, xnumel, r0_numel, XBLOCK : tl.constexpr, R0_BLOCK : tl.constexpr):

        We would add
        xnumel = 4096
        r0_numel = 768

        After the signature, before the kernel code, if we decided to make these static. As its hardcoded, it becomes
        a better signal to triton on how to unroll and do some static indexing. So, it's not so much that downstream
        knows that its a static numel, as that you just plop a constant into the kernel.
        """

    def is_static_integer(expr: sympy.Expr) -> bool:
        return isinstance(expr, (sympy.Integer, int))
    for tree in self.range_trees:
        if <MASK>:
            simplified_tree_numel = V.graph.sizevars.simplify(tree.numel)
            if is_static_integer(simplified_tree_numel):
                code.writeline(f'{tree.prefix}numel = {int(simplified_tree_numel)}')
        if tree.is_reduction and self.persistent_reduction:
            if self.cooperative_reduction:
                numel = self.kexpr(self.rename_indexing(tree.numel))
                val = f'triton_helpers.constexpr_next_power_of_2(({numel} + RSPLIT - 1) // RSPLIT)'
            else:
                val = self._get_persistent_RBLOCK(tree.numel)
                if self.is_native_matmul:
                    val = max(val, 16)
            code.writeline(f'{tree.prefix.upper()}BLOCK: tl.constexpr = {val}')
        if tree.prefix == 'x' and self.no_x_dim:
            code.writeline('XBLOCK: tl.constexpr = 1')

def select_tiling(self, fn_list, var_sizes_list) -> tuple[list[int], list[int]]:
    loop_bodies = _get_loop_body(fn_list)
    all_dtypes = _get_dtype_from_loopbodies(loop_bodies)
    assert all_dtypes
    if any((dtype not in VECTORIZABLE_DTYPES for dtype in all_dtypes)):
        return ([], [])
    dtype = torch.float
    _lowp_fp_dtype = get_loop_body_lowp_fp(loop_bodies[0])[0]
    if _lowp_fp_dtype and all((get_loop_body_lowp_fp(loop_body)[0] == _lowp_fp_dtype for loop_body in loop_bodies[1:])):
        dtype = _lowp_fp_dtype
    tiling_factor = cpu_vec_isa.pick_vec_isa().nelements(dtype=dtype)
    tiling_indices = self._select_tiling_indices(fn_list, var_sizes_list, tiling_factor)
    if tiling_indices:
        (group, reduction_group) = max(var_sizes_list, key=lambda sizes: len(sizes[1]))
        call_ranges = tuple(group) + tuple(reduction_group)
        if <MASK>:

            def _try_get_stride(index, itervars, tiling_factor, tiling_indices):
                itervar = itervars[tiling_indices[0]]
                stride = stride_at_vec_range(index, itervar, tiling_factor)
                return stride if stride.is_number else None

            def _update_negative_op_count(node_name, non_contig_indexing_op_counter):
                if node_name not in non_contig_indexing_op_counter:
                    non_contig_indexing_op_counter[node_name] = 1
                else:
                    non_contig_indexing_op_counter[node_name] += 1

            def _is_valid_indices(itervars, tiling_indices):
                return len(tiling_indices) == 1 and len(itervars) > 0 and ((tiling_indices[0] if tiling_indices[0] >= 0 else tiling_indices[0] + len(itervars)) < len(itervars))
            itervars = [sympy_index_symbol_with_prefix(SymT.XBLOCK, n) for n in range(len(call_ranges))]
            reduction_depth = len(group)
            (vars, reduction_vars) = (itervars[:reduction_depth], itervars[reduction_depth:])
            op_counter: dict[str, int] = {}
            non_contig_indexing_op_counter: dict[str, int] = {}
            for _body in loop_bodies:
                sub_blocks = [_body.root_block] + list(_body.subblocks.values())
                for sub_block in sub_blocks:
                    for _node in sub_block.graph.nodes:
                        if _node.target in ['index_expr', 'load', 'store']:
                            arg_idx = 1 if _node.target == 'index_expr' else 2
                            index = sub_block.body.indexing_from_args((vars, reduction_vars))[_node.args[arg_idx].args[0]]
                            if _is_valid_indices(itervars, tiling_indices):
                                stride = _try_get_stride(index, itervars, tiling_factor, tiling_indices)
                                if stride is None if _node.target == 'index_expr' else stride not in [0, 1]:
                                    _update_negative_op_count(_node.target, non_contig_indexing_op_counter)
                        if isinstance(_node.target, str) and (not (_node.target.startswith('masked_subblock') or _node.target in ['ops', 'output', 'constant', 'get_index'])):
                            if _node.target not in op_counter:
                                op_counter[_node.target] = 1
                            else:
                                op_counter[_node.target] += 1
            op_num = sum(op_counter.values())
            non_contig_indexing_op_num = sum(non_contig_indexing_op_counter.values())
            ratio_threshold = 0.12
            quantity_threshold = 35
            if non_contig_indexing_op_num >= quantity_threshold or (op_num > 0 and non_contig_indexing_op_num / op_num >= ratio_threshold):
                return ([], [])
            if not reduction_group and group and (len(tiling_indices) == 1) and (not has_free_symbols([group[tiling_indices[0]]])) and (group[tiling_indices[0]] < tiling_factor / 4) and (op_num < 10):
                return ([], [])
        if dtype in DTYPE_LOWP_FP:
            factor_lowp = cpu_vec_isa.pick_vec_isa().nelements(dtype=dtype)
            for tiling_indice in tiling_indices:
                if tiling_indice < 0:
                    tiling_indice = tiling_indice + len(call_ranges)
                if tiling_indice < 0 or tiling_indice >= len(call_ranges):
                    continue
                if has_free_symbols(call_ranges):
                    call_range = V.graph.sizevars.size_hint(call_ranges[tiling_indice], fallback=0)
                    if call_range < factor_lowp:
                        V.graph.sizevars.check_lt(call_range, factor_lowp)
                        tiling_factor = factor_lowp // 2
                        break
                elif call_ranges[tiling_indice] < factor_lowp:
                    tiling_factor = factor_lowp // 2
                    break
        if len(tiling_indices) == 1:
            return ([tiling_factor], tiling_indices)
        if len(tiling_indices) == 2:
            return ([tiling_factor, tiling_factor], tiling_indices)
    return ([], [])

def can_generate_trivial_fake_impl(op: OpOverload) -> bool:
    assert isinstance(op, OpOverload)
    if is_builtin(op):
        return False
    schema = op._schema
    if not schema.is_mutable:
        return False
    if <MASK>:
        return False
    return True

def get_latency_of_one_partition(partition: Partition, node_to_latency_mapping: dict[Node, NodeLatency]) -> PartitionLatency:
    """Given a partition and its nodes' latency, return a PartitionLatency for this partition"""

    def get_top_nodes(partition: Partition) -> list[Node]:
        """Given a partition, return a list of nodes on the top bfs level"""
        top_nodes: list[Node] = []
        for node in partition.nodes:
            if node.op in {'placeholder', 'get_attr'}:
                continue
            input_nodes: dict[Node, None] = {}
            map_arg(node.args, input_nodes.setdefault)
            map_arg(node.kwargs, input_nodes.setdefault)
            if <MASK>:
                top_nodes.append(node)
        return top_nodes

    def dfs_helper(node: Node, partition_latency) -> PartitionLatency:
        """Given a top node of a partition, this function returns
        the latency of the critical path in the partition
        """
        node_latency = node_to_latency_mapping[node]
        overall_latency_sec = partition_latency.overall_latency_sec + max(node_latency.computer_latency_sec, node_latency.mem_latency_sec)
        mem_latency_sec = partition_latency.mem_latency_sec + node_latency.mem_latency_sec
        computer_latency_sec = partition_latency.computer_latency_sec + node_latency.computer_latency_sec
        users = set(node.users).intersection(partition.nodes)
        if users:
            max_latency = PartitionLatency(mem_latency_sec=0.0, computer_latency_sec=0.0, overall_latency_sec=0.0)
            for n in users:
                new_partition_latency = dfs_helper(n, PartitionLatency(mem_latency_sec, computer_latency_sec, overall_latency_sec))
                if new_partition_latency.overall_latency_sec > max_latency.overall_latency_sec:
                    max_latency = new_partition_latency
            return max_latency
        return PartitionLatency(mem_latency_sec, computer_latency_sec, overall_latency_sec)
    top_nodes = get_top_nodes(partition)
    critical_path_latency = PartitionLatency(mem_latency_sec=0.0, computer_latency_sec=0.0, overall_latency_sec=0.0)
    for node in top_nodes:
        partition_latency = dfs_helper(node, PartitionLatency(mem_latency_sec=0.0, computer_latency_sec=0.0, overall_latency_sec=0.0))
        if partition_latency.overall_latency_sec > critical_path_latency.overall_latency_sec:
            critical_path_latency = partition_latency
    return critical_path_latency

def testUnweighted(self):
    for reduction in losses.Reduction.all():
        with ops.Graph().as_default() as g:
            self.assertEqual(0, len(util.get_losses()))
            raw_losses = self._raw_losses
            unweighted_losses = (losses.compute_weighted_loss(raw_losses, reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((1, 1, 1)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((1, 1, 4)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((1, 2, 1)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((1, 2, 4)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((3, 1, 1)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((3, 1, 4)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones((3, 2, 1)), reduction=reduction), losses.compute_weighted_loss(raw_losses, weights=np.ones(self._shape), reduction=reduction))
            self.assertEqual(9, len(util.get_losses()))
            with self.session(g):
                for unweighted_loss in unweighted_losses:
                    if <MASK>:
                        self.assertAllClose(self._raw_losses, self.evaluate(unweighted_loss))
                    elif reduction == losses.Reduction.SUM:
                        self.assertAllClose(np.sum(self._raw_losses), self.evaluate(unweighted_loss))
                    else:
                        self.assertAllClose(np.mean(self._raw_losses), self.evaluate(unweighted_loss))

def __init__(self, obj: NDFrame, com: float | None=None, span: float | None=None, halflife: float | TimedeltaConvertibleTypes | None=None, alpha: float | None=None, min_periods: int | None=0, adjust: bool=True, ignore_na: bool=False, times: np.ndarray | NDFrame | None=None, method: str='single', *, selection=None) -> None:
    super().__init__(obj=obj, min_periods=1 if min_periods is None else max(int(min_periods), 1), on=None, center=False, closed=None, method=method, selection=selection)
    self.com = com
    self.span = span
    self.halflife = halflife
    self.alpha = alpha
    self.adjust = adjust
    self.ignore_na = ignore_na
    self.times = times
    if self.times is not None:
        times_dtype = getattr(self.times, 'dtype', None)
        if <MASK>:
            raise ValueError('times must be datetime64 dtype.')
        if len(self.times) != len(obj):
            raise ValueError('times must be the same length as the object.')
        if not isinstance(self.halflife, (str, datetime.timedelta, np.timedelta64)):
            raise ValueError('halflife must be a timedelta convertible object')
        if isna(self.times).any():
            raise ValueError('Cannot convert NaT values to integer')
        self._deltas = _calculate_deltas(self.times, self.halflife)
        if common.count_not_none(self.com, self.span, self.alpha) > 0:
            if not self.adjust:
                raise NotImplementedError('None of com, span, or alpha can be specified if times is provided and adjust=False')
            self._com = get_center_of_mass(self.com, self.span, None, self.alpha)
        else:
            self._com = 1.0
    else:
        if self.halflife is not None and isinstance(self.halflife, (str, datetime.timedelta, np.timedelta64)):
            raise ValueError('halflife can only be a timedelta convertible argument if times is not None.')
        self._deltas = np.ones(max(self.obj.shape[0] - 1, 0), dtype=np.float64)
        self._com = get_center_of_mass(self.com, self.span, self.halflife, self.alpha)

def _generate_linear_dynamic_fp16_pattern(_dequant_weight_pattern, input_dim_exceeds_two=False, input_contiguous=True, relu_fused=False):
    dtype = torch.float32
    t_pattern = _generate_linear_t_pattern(_dequant_weight_pattern, dtype)
    if input_dim_exceeds_two and (not input_contiguous):
        pattern_no_bias = CallFunction(aten.bmm.default, CallFunction(aten.expand.default, KeywordArg('x'), KeywordArg('act_expand_size')), CallFunction(aten.expand.default, t_pattern, KeywordArg('wgt_expand_size')))
        pattern_with_bias = CallFunction(aten.add.Tensor, pattern_no_bias, KeywordArg('b'))
        if <MASK>:
            pattern_with_bias = CallFunction(aten.relu.default, pattern_with_bias)
            pattern_no_bias = CallFunction(aten.relu.default, pattern_no_bias)
        return (pattern_with_bias, pattern_no_bias)
    x_pattern_with_reshape = _may_generate_pattern_with_reshape(KeywordArg('x'), KeywordArg('act_reshape_size'), input_dim_exceeds_two)
    dequant_linear_bias_pattern = generate_pattern_with_unary(_may_generate_pattern_with_reshape(CallFunction(aten.addmm.default, KeywordArg('b'), x_pattern_with_reshape, t_pattern), KeywordArg('output_reshape_size'), input_dim_exceeds_two), aten.relu.default if relu_fused else None)
    dequant_linear_no_bias_pattern = generate_pattern_with_unary(_may_generate_pattern_with_reshape(CallFunction(aten.mm.default, x_pattern_with_reshape, t_pattern), KeywordArg('output_reshape_size'), input_dim_exceeds_two), aten.relu.default if relu_fused else None)
    return (dequant_linear_bias_pattern, dequant_linear_no_bias_pattern)

def __pow__(self, val):
    if <MASK>:
        raise ValueError('Power to non-negative integers only.')
    res = [1]
    for _ in range(val):
        res = polymul(self.coeffs, res)
    return poly1d(res)

def __init__(self, values, dtype: Dtype | None=None, copy: bool=False) -> None:
    if dtype is not None:
        dtype = pandas_dtype(dtype)
        if not isinstance(dtype, PeriodDtype):
            raise ValueError(f'Invalid dtype {dtype} for PeriodArray')
    if isinstance(values, ABCSeries):
        values = values._values
        if not isinstance(values, type(self)):
            raise TypeError('Incorrect dtype')
    elif <MASK>:
        values = values._values
    if isinstance(values, type(self)):
        if dtype is not None and dtype != values.dtype:
            raise raise_on_incompatible(values, dtype.freq)
        (values, dtype) = (values._ndarray, values.dtype)
    if not copy:
        values = np.asarray(values, dtype='int64')
    else:
        values = np.array(values, dtype='int64', copy=copy)
    if dtype is None:
        raise ValueError('dtype is not specified and cannot be inferred')
    dtype = cast(PeriodDtype, dtype)
    NDArrayBacked.__init__(self, values, dtype)

def common_repr(self, shorten: bool=True) -> Sequence[str]:
    origins = f"origins={getattr(self, 'origins', '')}"
    if <MASK>:
        origins = f'{origins[:61]}...'
    if not self.get_stack_traces():
        return [origins]
    stack_trace_str = []
    for stack_trace in self.get_stack_traces():
        stack_trace_str.append('stack_traces = {')
        stack_trace_str += stack_trace.split('\n')
        stack_trace_str.append('}')
    return [origins] + stack_trace_str

def _modify_graph_op_device(gm: torch.fx.GraphModule, new_device: torch.device):
    """
    Modify the device argument of all "call_function" nodes in the graph.  This
    is useful for moving the graph to a different device. In particular for
    generator ops, like torch.ones.
    """
    modified = False
    for node in gm.graph.nodes:
        if node.op == 'call_function':
            if 'device' in node.kwargs and node.kwargs['device'] != new_device:
                logger.debug(f"Changing device of Node {node.name} from {node.kwargs['device']} to {new_device}")
                node.update_kwarg('device', new_device)
                modified = True
        elif node.op == 'call_module':
            submod = gm.get_submodule(node.target)
            if isinstance(submod, torch.fx.GraphModule):
                _modify_graph_op_device(submod, new_device)
            elif isinstance(submod, InterpreterModule):
                _modify_graph_op_device(submod.graph_module, new_device)
            else:
                logger.warning(f'Skipping device modification for submodule {node.target} because it is a {type(submod)}')
    if <MASK>:
        gm.recompile()

def get_any_has_fw_grad_cond(derivative: ForwardDerivative | None) -> str:
    if <MASK>:
        to_check: list[str] = []
        for inp in list(mapMaybe(gen_differentiable_input, f.func.arguments.non_out + list(f.func.arguments.out))):
            if is_tensor_type(inp.type):
                to_check.append(FW_DERIVATIVE_CHECK_TEMPLATE.substitute(req_inp=inp.name))
            elif is_tensor_list_type(inp.type):
                to_check.append(FW_DERIVATIVE_TENSORLIST_CHECK_TEMPLATE.substitute(req_inp=inp.name))
            else:
                raise RuntimeError(f'Unsupported input type for "{name}" when forbidding forward AD usage.')
        return f"({' || '.join(to_check)})"
    else:
        assert derivative.required_inputs_fw_grad is not None
        if len(derivative.required_inputs_fw_grad) == 0:
            if not (len(differentiable_inputs) == 1 and is_tensor_list_type(differentiable_inputs[0].type)):
                raise RuntimeError(f'No differentiable input to "{name}" is a differentiable Tensor (as the provided forward AD formula does not use any input tangent) even though a forward gradient formula has been defined for it. This case should only happen for function that take a single TensorList as input. All other cases are not supported right now.')
            any_has_fw_grad = 'true'
        else:
            any_has_fw_grad = ' || '.join([(FW_DERIVATIVE_TENSORLIST_CHECK_TEMPLATE if is_tensor_list_type(inp.type) else FW_DERIVATIVE_CHECK_TEMPLATE).substitute(req_inp=inp.name) for inp in differentiable_inputs if inp.name in derivative.required_inputs_fw_grad])
            any_has_fw_grad = f'({any_has_fw_grad})'
        return any_has_fw_grad

def halide_kernel_meta(self) -> HalideMeta:
    """Compute metadata required by codecache.py"""
    argtypes = []
    for (_, arg) in self.halide_argdefs():
        if isinstance(arg, SizeArg):
            shape = None
            stride = None
            offset = None
            dtype = 'long'
        else:
            shape = [cexpr(self.rename_indexing(x.size)) for x in self.buffer_dimensions[arg.name]]
            stride = [cexpr(self.rename_indexing(x.stride)) for x in self.buffer_dimensions[arg.name]]
            assert len(shape) == len(stride)
            offset = cexpr(self.buffer_offsets[arg.name])
            dtype = f'{DTYPE_TO_CPP[arg.dtype]}*'
        argtypes.append(HalideInputSpec(dtype, arg.name, shape=shape, stride=stride, offset=offset, alias_of=arg.alias_of))
    current_device = V.graph.get_current_device_or_throw()
    if current_device.type == 'cpu':
        target = [config.halide.cpu_target]
        scheduler = config.halide.scheduler_cpu
        scheduler_flags = {'parallelism': parallel_num_threads()}
        cuda_device = None
    else:
        assert current_device.type == 'cuda', 'only cpu/cuda supported'
        assert current_device.index <= 0, 'only default device supported'
        target = [config.halide.gpu_target]
        scheduler = config.halide.scheduler_cuda
        capability = torch.cuda.get_device_properties(current_device)
        if 'cuda_capability' not in target[0]:
            for (major, minor) in [(8, 6), (8, 0), (7, 5), (7, 0), (6, 1)]:
                if capability.major >= major and capability.minor >= minor:
                    target.append(f'cuda_capability_{major}{minor}')
                    break
        target.append('user_context')
        scheduler_flags = {'parallelism': capability.multi_processor_count}
        cuda_device = max(0, current_device.index)
    target.append('strict_float')
    target.append('no_runtime')
    if <MASK>:
        target.append('no_asserts')
    if config.halide.debug:
        target.append('debug')
    if '64' in self.index_dtype:
        target.append('large_buffers')
    return HalideMeta(argtypes, target='-'.join(target), scheduler=scheduler, scheduler_flags=scheduler_flags, cuda_device=cuda_device)

def decorator(func):
    if <MASK>:
        sensitive_variables_wrapper = func
        wrapped_func = func
        while getattr(wrapped_func, '__wrapped__', None) is not None:
            wrapped_func = wrapped_func.__wrapped__
        try:
            file_path = inspect.getfile(wrapped_func)
        except TypeError:
            raise ValueError(f'{func.__name__} cannot safely be wrapped by @sensitive_variables, make it either non-async or defined in a Python file (not a builtin or from a native extension).')
        else:
            first_line_number = wrapped_func.__code__.co_firstlineno
            key = hash(f'{file_path}:{first_line_number}')
        if variables:
            coroutine_functions_to_sensitive_variables[key] = variables
        else:
            coroutine_functions_to_sensitive_variables[key] = '__ALL__'
    else:

        @wraps(func)
        def sensitive_variables_wrapper(*func_args, **func_kwargs):
            if variables:
                sensitive_variables_wrapper.sensitive_variables = variables
            else:
                sensitive_variables_wrapper.sensitive_variables = '__ALL__'
            return func(*func_args, **func_kwargs)
    return sensitive_variables_wrapper

def is_constant(tensor_or_op):
    if <MASK>:
        op = tensor_or_op.op
    else:
        op = tensor_or_op
    return op.type == 'Const'

def _move_states_to_device(params: list[nn.Parameter], buffers: list[torch.Tensor], device_from_device_id: Optional[torch.device]) -> None:
    """
    Move states to the specified device.

    Precondition: ``_check_single_device_module()`` and module's parameters and
    buffers have been materialized if needed.
    """
    if <MASK>:
        return
    if len(params) > 0:
        current_device = params[0].device
    elif len(buffers) > 0:
        current_device = buffers[0].device
    cpu_device = torch.device('cpu')
    if device_from_device_id is not None:
        for param in params:
            with torch.no_grad():
                param.data = param.to(device_from_device_id)
                if param.grad is not None:
                    param.grad.data = param.grad.to(device_from_device_id)
        for buffer in buffers:
            buffer.data = buffer.to(device_from_device_id)
    elif current_device == cpu_device:
        _warn_cpu_init()

def replace(expr: sympy.Expr) -> sympy.Expr:
    expr = sympy.together(expr)
    (numerator, denominator) = (sympy.S.One,) * 2
    for arg in sympy.Mul.make_args(expr):
        if isinstance(arg, sympy.Rational):
            numerator *= arg.numerator
            denominator *= arg.denominator
        elif <MASK>:
            denominator *= arg.base ** (-arg.exp)
        else:
            numerator *= arg
    return FloorDiv(numerator, denominator)

def _median(a, axis=None, out=None, overwrite_input=False):
    if np.issubdtype(a.dtype, np.inexact):
        fill_value = np.inf
    else:
        fill_value = None
    if overwrite_input:
        if axis is None:
            asorted = a.ravel()
            asorted.sort(fill_value=fill_value)
        else:
            a.sort(axis=axis, fill_value=fill_value)
            asorted = a
    else:
        asorted = sort(a, axis=axis, fill_value=fill_value)
    if axis is None:
        axis = 0
    else:
        axis = normalize_axis_index(axis, asorted.ndim)
    if asorted.shape[axis] == 0:
        indexer = [slice(None)] * asorted.ndim
        indexer[axis] = slice(0, 0)
        indexer = tuple(indexer)
        return np.ma.mean(asorted[indexer], axis=axis, out=out)
    if asorted.ndim == 1:
        (idx, odd) = divmod(count(asorted), 2)
        mid = asorted[idx + odd - 1:idx + 1]
        if np.issubdtype(asorted.dtype, np.inexact) and asorted.size > 0:
            s = mid.sum(out=out)
            if not odd:
                s = np.true_divide(s, 2.0, casting='safe', out=out)
            s = np.lib._utils_impl._median_nancheck(asorted, s, axis)
        else:
            s = mid.mean(out=out)
        if <MASK>:
            return np.ma.minimum_fill_value(asorted)
        return s
    counts = count(asorted, axis=axis, keepdims=True)
    h = counts // 2
    odd = counts % 2 == 1
    l = np.where(odd, h, h - 1)
    lh = np.concatenate([l, h], axis=axis)
    low_high = np.take_along_axis(asorted, lh, axis=axis)

    def replace_masked(s):
        if np.ma.is_masked(s):
            rep = ~np.all(asorted.mask, axis=axis, keepdims=True) & s.mask
            s.data[rep] = np.ma.minimum_fill_value(asorted)
            s.mask[rep] = False
    replace_masked(low_high)
    if np.issubdtype(asorted.dtype, np.inexact):
        s = np.ma.sum(low_high, axis=axis, out=out)
        np.true_divide(s.data, 2.0, casting='unsafe', out=s.data)
        s = np.lib._utils_impl._median_nancheck(asorted, s, axis)
    else:
        s = np.ma.mean(low_high, axis=axis, out=out)
    return s

def old_np_asarray(values, dtype=None, order=None, copy=None):
    if <MASK>:
        if dtype is not None and np.issubdtype(dtype, np.number):
            return np.asarray(values, order=order, copy=copy).astype(dtype)
        else:
            return np.asarray(values, dtype=dtype, order=order, copy=copy)
    else:
        return np.asarray(values, dtype=dtype, order=order)

def _compute_error(grad):
    if <MASK>:
        grad = [grad]
    error = 0
    for (j_t, j_n) in grad:
        if j_t.size or j_n.size:
            error = np.maximum(error, np.fabs(j_t - j_n).max())
    return error

def __init__(self, loc: Tensor, covariance_matrix: Optional[Tensor]=None, precision_matrix: Optional[Tensor]=None, scale_tril: Optional[Tensor]=None, validate_args: Optional[bool]=None) -> None:
    if loc.dim() < 1:
        raise ValueError('loc must be at least one-dimensional.')
    if (covariance_matrix is not None) + (scale_tril is not None) + (precision_matrix is not None) != 1:
        raise ValueError('Exactly one of covariance_matrix or precision_matrix or scale_tril may be specified.')
    if scale_tril is not None:
        if <MASK>:
            raise ValueError('scale_tril matrix must be at least two-dimensional, with optional leading batch dimensions')
        batch_shape = torch.broadcast_shapes(scale_tril.shape[:-2], loc.shape[:-1])
        self.scale_tril = scale_tril.expand(batch_shape + (-1, -1))
    elif covariance_matrix is not None:
        if covariance_matrix.dim() < 2:
            raise ValueError('covariance_matrix must be at least two-dimensional, with optional leading batch dimensions')
        batch_shape = torch.broadcast_shapes(covariance_matrix.shape[:-2], loc.shape[:-1])
        self.covariance_matrix = covariance_matrix.expand(batch_shape + (-1, -1))
    else:
        assert precision_matrix is not None
        if precision_matrix.dim() < 2:
            raise ValueError('precision_matrix must be at least two-dimensional, with optional leading batch dimensions')
        batch_shape = torch.broadcast_shapes(precision_matrix.shape[:-2], loc.shape[:-1])
        self.precision_matrix = precision_matrix.expand(batch_shape + (-1, -1))
    self.loc = loc.expand(batch_shape + (-1,))
    event_shape = self.loc.shape[-1:]
    super().__init__(batch_shape, event_shape, validate_args=validate_args)
    if scale_tril is not None:
        self._unbroadcasted_scale_tril = scale_tril
    elif covariance_matrix is not None:
        self._unbroadcasted_scale_tril = torch.linalg.cholesky(covariance_matrix)
    else:
        self._unbroadcasted_scale_tril = _precision_to_scale_tril(precision_matrix)

def operator_and_matrix(self, build_info, dtype, use_placeholder, ensure_self_adjoint_and_pd=False):
    shape = list(build_info.shape)
    perm = math_ops.range(0, shape[-1])
    perm = array_ops.broadcast_to(perm, shape[:-1])
    perm = random_ops.random_shuffle(perm)
    if <MASK>:
        perm = array_ops.placeholder_with_default(perm, shape=None)
    operator = permutation.LinearOperatorPermutation(perm, dtype=dtype)
    matrix = math_ops.cast(math_ops.equal(math_ops.range(0, shape[-1]), perm[..., array_ops.newaxis]), dtype)
    return (operator, matrix)

def remove(k, selfref=ref(self)):
    self = selfref()
    if self is not None:
        if <MASK>:
            self._pending_removals.append(k)
        else:
            try:
                del self.data[k]
            except KeyError:
                pass

def my_map(x):
    if <MASK>:
        return dataset_ops.Dataset.from_tensor_slices([0, 1, 2, 3])
    elif x == 1:
        return dataset_ops.Dataset.from_tensor_slices([4, 5, 6, 7])
    else:
        return dataset_ops.Dataset.from_tensor_slices([8, 9, 10, 11])

def _verify_exported_program_signature(exported_program) -> None:
    gs = exported_program.graph_signature
    input_node_names = [node.name for node in exported_program.graph.nodes if node.op == 'placeholder']
    if len(input_node_names) != len(gs.input_specs):
        raise SpecViolationError(f'Number of graph inputs ({len(input_node_names)}) does not match number of inputs in the graph signature ({len(gs.input_specs)})')
    for (input_spec, node) in zip(gs.input_specs, input_node_names):
        if isinstance(input_spec.arg, (TensorArgument, SymIntArgument, SymFloatArgument, SymBoolArgument)):
            if <MASK>:
                raise SpecViolationError(f'Input spec name {input_spec.arg.name} does not match node name {node}')
        if input_spec.kind == InputKind.USER_INPUT:
            continue
        elif input_spec.kind == InputKind.PARAMETER:
            if not isinstance(input_spec.arg, TensorArgument):
                raise SpecViolationError(f'Parameter {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            param = input_spec.target
            if param not in exported_program.state_dict:
                raise SpecViolationError(f'Parameter {param} is not in the state dict.')
            if not isinstance(exported_program.state_dict[param], torch.nn.Parameter):
                raise SpecViolationError(f'State dict entry for parameter {param} is not an instance of torch.nn.Parameter.')
        elif input_spec.kind == InputKind.BUFFER:
            if not isinstance(input_spec.arg, TensorArgument):
                raise SpecViolationError(f'Buffer {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            buffer = input_spec.target
            if input_spec.persistent is None:
                raise SpecViolationError(f'Buffer {buffer} is missing a persistence flag')
            if input_spec.persistent is True and buffer not in exported_program.state_dict:
                raise SpecViolationError(f'Buffer {buffer} is not in the state dict.')
            if input_spec.persistent is False and buffer in exported_program.state_dict:
                raise SpecViolationError(f'Non-persistent buffer {buffer} is in the state dict, it should not be.')
        elif input_spec.kind == InputKind.CONSTANT_TENSOR:
            if not isinstance(input_spec.arg, TensorArgument):
                raise SpecViolationError(f'Constant tensor {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            tensor_const = input_spec.target
            if tensor_const not in exported_program.constants:
                raise SpecViolationError(f'Constant tensor {tensor_const} is not in the constants dictionary.')
        elif input_spec.kind == InputKind.CUSTOM_OBJ:
            if not isinstance(input_spec.arg, CustomObjArgument):
                raise SpecViolationError(f'Custom object {input_spec.name} is not a custom object argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            custom_obj = input_spec.target
            if custom_obj not in exported_program.constants:
                raise SpecViolationError(f'Custom object {custom_obj} is not in the constants dictionary.')
        elif input_spec.kind == InputKind.TOKEN:
            if not isinstance(input_spec.arg, TokenArgument):
                raise SpecViolationError(f'Constant tensor {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
        else:
            raise SpecViolationError(f'Unknown InputKind {input_spec.kind}.')
    output_node = list(exported_program.graph.nodes)[-1]
    assert output_node.op == 'output'
    output_nodes = [arg.name if isinstance(arg, torch.fx.Node) else arg for arg in output_node.args[0]]
    if len(output_nodes) != len(gs.output_specs):
        raise SpecViolationError(f'Number of output nodes {len(output_nodes)} is different Than the number of outputs specified by the graph signature: \nNumber of mutated buffers: {len(gs.buffers_to_mutate)}. \nNumber of user outputs: {len(gs.user_outputs)}. \n')
    num_tokens = len(gs.output_tokens)
    end = len(gs.buffers_to_mutate) + len(gs.parameters_to_mutate) + len(gs.user_inputs_to_mutate) + num_tokens
    mutate_nodes: list[str] = output_nodes[num_tokens:end]
    user_output_nodes = output_nodes[end:end + len(gs.user_outputs)]
    for mutation_node in mutate_nodes:
        if mutation_node in gs.buffers_to_mutate:
            if gs.buffers_to_mutate[mutation_node] not in gs.buffers:
                raise SpecViolationError(f'Buffer output {mutation_node} does not point to a buffer that exists. \nDict of buffers that are mutated, in order: {gs.buffers_to_mutate} \nBuffer nodes available: {gs.buffers} \n')
        elif mutation_node in gs.parameters_to_mutate:
            if gs.parameters_to_mutate[mutation_node] not in gs.parameters:
                raise SpecViolationError(f'Parameter output {mutation_node} does not point to a parameter that exists. \nDict of parameters that are mutated, in order: {gs.parameters_to_mutate} \nParameter nodes available: {gs.parameters} \n')
        elif mutation_node in gs.user_inputs_to_mutate:
            if gs.user_inputs_to_mutate[mutation_node] not in gs.user_inputs:
                raise SpecViolationError(f'User input output {mutation_node} does not point to a user input that exists. \nDict of user inputs that are mutated, in order: {gs.user_inputs_to_mutate} \nUser input nodes available: {gs.user_inputs} \n')
        else:
            raise SpecViolationError(f'Mutation node {mutation_node} is neither a buffer nor a user input. Buffers to mutate: {gs.buffers_to_mutate}, User inputs to mutate: {gs.user_inputs_to_mutate}')
    for (user_output_node, user_output_name) in zip(user_output_nodes, gs.user_outputs):
        if user_output_node != user_output_name:
            raise SpecViolationError(f"User output {user_output_node} is not in the correct order or is not found in the exported program's user_output list: {gs.user_outputs}. ")

def _cmp_method(self, other, op):
    from pandas.arrays import ArrowExtensionArray, BooleanArray
    if isinstance(other, BaseStringArray) and self.dtype.na_value is not libmissing.NA and (other.dtype.na_value is libmissing.NA):
        return op(self.astype(other.dtype, copy=False), other)
    if isinstance(other, ArrowExtensionArray):
        if isinstance(other, BaseStringArray):
            if not (self.dtype.na_value is libmissing.NA and other.dtype.na_value is not libmissing.NA):
                return NotImplemented
        else:
            return NotImplemented
    if isinstance(other, StringArray):
        other = other._ndarray
    mask = isna(self) | isna(other)
    valid = ~mask
    if lib.is_list_like(other):
        if len(other) != len(self):
            raise ValueError(f'Lengths of operands do not match: {len(self)} != {len(other)}')
        if not is_array_like(other):
            other = np.asarray(other)
        other = other[valid]
    other_dtype = getattr(other, 'dtype', None)
    if op.__name__.strip('_') in ['mul', 'rmul'] and (lib.is_bool(other) or lib.is_np_dtype(other_dtype, 'b')):
        raise TypeError('Cannot multiply StringArray by bools. Explicitly cast to integers instead.')
    if op.__name__ in ops.ARITHMETIC_BINOPS:
        result = np.empty_like(self._ndarray, dtype='object')
        result[mask] = self.dtype.na_value
        result[valid] = op(self._ndarray[valid], other)
        if <MASK>:
            return result
        return self._from_backing_data(result)
    else:
        result = np.zeros(len(self._ndarray), dtype='bool')
        result[valid] = op(self._ndarray[valid], other)
        res_arr = BooleanArray(result, mask)
        if self.dtype.na_value is np.nan:
            if op == operator.ne:
                return res_arr.to_numpy(np.bool_, na_value=True)
            else:
                return res_arr.to_numpy(np.bool_, na_value=False)
        return res_arr

def worker_fn(self, checkpoint_dir, cluster_spec, strategy_option, input_arg='checkpoint', training_started_event=None, raise_app_error_on_worker=None, training_restarted=None, training_finished=None, termination_config=failure_handling.TerminationConfig(), api_wrapping_train=True):
    if strategy_option == 'MS':
        strategy = mirrored_strategy.MirroredStrategy()
    elif strategy_option == 'OneDevice':
        if config.list_physical_devices('GPU'):
            strategy = one_device_lib.OneDeviceStrategy(device='/gpu:0')
        else:
            strategy = one_device_lib.OneDeviceStrategy(device='/cpu:0')
    else:
        strategy = collective_all_reduce_strategy.CollectiveAllReduceStrategy()

    class Model(module.Module):

        def __init__(self):
            self.v = variables_lib.Variable(0.0, synchronization=variables_lib.VariableSynchronization.ON_WRITE, aggregation=variables_lib.VariableAggregation.SUM)

        @def_function.function(input_signature=[])
        def __call__(self):
            return self.v.read_value()
    with mock.patch.object(failure_handling_util, 'on_gcp', lambda : False):
        with strategy.scope():
            model = Model()
            fh_ckpt = tracking_util.Checkpoint(model=model)
            if input_arg == 'checkpoint':
                checkpoint_or_manager = fh_ckpt
            else:
                checkpoint_or_manager = _make_checkpoint_manager(fh_ckpt, checkpoint_dir, strategy.cluster_resolver)
            preemption_handler = failure_handling.PreemptionCheckpointHandler(strategy.cluster_resolver, checkpoint_or_manager, checkpoint_dir, termination_config)

        def distributed_train_step(current_epoch, current_step):

            @def_function.function
            def train_step():
                if cluster_spec and distribute_lib.get_distribution_strategy().cluster_resolver.task_id == raise_app_error_on_worker:
                    raise errors_impl.ResourceExhaustedError(node_def=None, op=None, message='Running out of resources')
                model.v.assign_add(constant_op.constant(1.0))
            strategy.run(train_step)
            if <MASK>:
                logging.info('epoch %d finished', current_epoch)
        logging.info('Start training at %d', preemption_handler.total_run_calls)
        if training_restarted and training_restarted.is_set() and (not training_finished.is_set()):
            logging.info('training restarted')
            match_group = [re.search('.*ckpt-(\\d+).index', a_file) for a_file in gfile.ListDirectory(checkpoint_dir)]
            checkpoint_index = [a_match.group(1) for a_match in match_group if a_match]
            if getattr(termination_config, 'grace_period', 0):
                self.assertEqual(int(checkpoint_index[0]), 2)
            else:
                self.assertEqual(int(checkpoint_index[0]), 1)
        for epoch in range(preemption_handler.total_run_calls // STEPS_PER_EPOCH, EPOCHS_TO_RUN):
            for step in range(preemption_handler.total_run_calls % STEPS_PER_EPOCH, STEPS_PER_EPOCH):
                if api_wrapping_train:
                    preemption_handler.run(distributed_train_step, epoch, step)
                else:
                    preemption_handler.save_checkpoint_if_preempted()
                    distributed_train_step(epoch, step)
            if epoch >= EPOCHS_TO_RUN - 2:
                trigger_it = True
            else:
                trigger_it = False
            self._maybe_trigger_a_preemption(training_started_event, trigger_it)
        training_finished.set()
        logging.info('Training finished.')
        self.assertEqual(model.v.numpy(), strategy.num_replicas_in_sync * EPOCHS_TO_RUN * STEPS_PER_EPOCH)

@register_custom_op
def _dequantize_affine(input: torch.Tensor, block_size: list[int], scale: torch.Tensor, zero_point: Optional[torch.Tensor], input_dtype: torch.dtype, quant_min: Optional[Union[int, float, bool]]=None, quant_max: Optional[Union[int, float, bool]]=None, zero_point_domain: Optional[str]=ZeroPointDomain.INT.name, output_dtype: torch.dtype=torch.float32) -> torch.Tensor:
    """op definition that has compatible signatures with custom op library"""
    if input_dtype not in _SUB_BYTE_UINT_BOUNDS:
        if <MASK>:
            raise AssertionError(f'Expected: {input_dtype}, got: {input.dtype}')
    if output_dtype not in [torch.float32, torch.float16, torch.bfloat16]:
        raise AssertionError(f'Unsupported output dtype: {output_dtype}')
    (quant_min, quant_max) = _get_and_check_qmin_qmax(input_dtype, quant_min, quant_max)
    return _dequantize_affine_no_dtype_check(input, block_size, scale, zero_point, quant_min, quant_max, zero_point_domain, output_dtype)

@property
def _is_v2_column(self):
    for key in _collect_leaf_level_keys(self):
        if isinstance(key, six.string_types):
            continue
        if <MASK>:
            return False
        if not key._is_v2_column:
            return False
    return True

def __init__(self, inner_optimizer, dynamic=True, initial_scale=None, dynamic_growth_steps=None):
    if not isinstance(inner_optimizer, optimizer_v2.OptimizerV2):
        raise TypeError('"inner_optimizer" must be an instance of OptimizerV2, but got: %s' % inner_optimizer)
    if not isinstance(dynamic, bool):
        raise TypeError('"dynamic" argument to LossScaleOptimizer.__init__ must be a bool, but got: %r' % (dynamic,))
    if isinstance(inner_optimizer, LossScaleOptimizer):
        raise TypeError('LossScaleOptimizer cannot wrap another LossScaleOptimizer, but got: %s' % (inner_optimizer,))
    self._raise_if_strategy_unsupported()
    if getattr(inner_optimizer, '_is_wrapped_by_loss_scale_optimizer', False):
        raise ValueError('"inner_optimizer" is already wrapped by a LossScaleOptimizer. An optimizer can only be wrapped by a single LossScaleOptimizer')
    self._optimizer = inner_optimizer
    self._optimizer._is_wrapped_by_loss_scale_optimizer = True
    base_delegate.DelegatingTrackableMixin.__init__(self, self._optimizer)
    if dynamic:
        if initial_scale is None:
            initial_scale = _DEFAULT_INITIAL_SCALE
        if dynamic_growth_steps is None:
            dynamic_growth_steps = _DEFAULT_GROWTH_STEPS
        self._loss_scale = _DynamicLossScaleState(initial_scale, dynamic_growth_steps, multiplier=2)
        self._track_trackable(self._loss_scale, 'loss_scale')
    else:
        if initial_scale is None:
            raise ValueError('"initial_scale" must be specified if "dynamic" is False')
        self._loss_scale = float(initial_scale)
        if <MASK>:
            raise ValueError('"dynamic_growth_steps" must be None if "dynamic" is False, but got: %s' % (dynamic_growth_steps,))
    self._track_trackable(FakeOptimizerForRestoration(self._optimizer), 'base_optimizer')

def _wrap_applied_output_series(self, values: list[Series], not_indexed_same: bool, first_not_none, key_index: Index | None, is_transform: bool) -> DataFrame | Series:
    kwargs = first_not_none._construct_axes_dict()
    backup = Series(**kwargs)
    values = [x if x is not None else backup for x in values]
    all_indexed_same = all_indexes_same((x.index for x in values))
    if not all_indexed_same:
        return self._concat_objects(values, not_indexed_same=True, is_transform=is_transform)
    stacked_values = np.vstack([np.asarray(v) for v in values])
    index = key_index
    columns = first_not_none.index.copy()
    if columns.name is None:
        names = {v.name for v in values}
        if <MASK>:
            columns.name = next(iter(names))
    if stacked_values.dtype == object:
        stacked_values = stacked_values.tolist()
    result = self.obj._constructor(stacked_values, index=index, columns=columns)
    if not self.as_index:
        result = self._insert_inaxis_grouper(result)
    return result.__finalize__(self.obj, method='groupby')

def unlift_tokens(fw_module, fw_metadata, aot_config, bw_module=None):
    num_forward_tokens = len(fw_metadata.tokens)
    num_backward_tokens = fw_metadata.num_backward_tokens

    def rewrite_with_effects_input_token(module, node):
        with module.graph.inserting_before(node):
            new_token_node = module.graph.call_function(torch.ops.prims._make_token.default, ())
            new_token_node.meta['val'] = torch.tensor([])
            new_token_node.meta['tensor_meta'] = torch.tensor([])
            args = list(node.args)
            args[0] = new_token_node
            node.args = tuple(args)

    def rewrite_output(module, node, output_token_nodes, other_output_args):
        for output_token_node in output_token_nodes:
            assert output_token_node.op == 'call_function' and output_token_node.target == operator.getitem and (output_token_node.args[1] == 0)
        with module.graph.inserting_before(node):
            module.graph.call_function(torch.ops.prims._sink_tokens.default, (output_token_nodes,))
            node.args = (other_output_args,)

    def do(module, subgraph, expected_num_erased):
        num_erased_inputs = 0
        num_erased_outs = 0
        input_nodes = []
        input_token_nodes = set()
        with_effect_nodes = []
        output_token_nodes = []
        other_output_nodes = []
        for node in module.graph.nodes:
            if <MASK>:
                input_nodes.append(node)
            elif is_with_effects(node):
                with_effect_nodes.append(node)
                if node.args[0] in input_nodes:
                    input_token_nodes.add(node.args[0])
                    rewrite_with_effects_input_token(module, node)
            elif node.op == 'output':
                outs = node.args[0]
                for out in outs:
                    if isinstance(out, torch.fx.node.Node) and out.op == 'call_function' and (out.target == operator.getitem) and (out.args[1] == 0) and (out.args[0] in with_effect_nodes):
                        output_token_nodes.append(out)
                    else:
                        other_output_nodes.append(out)
                rewrite_output(module, node, output_token_nodes, other_output_nodes)
                num_erased_outs = len(output_token_nodes)
        for input_token_node in input_token_nodes:
            module.graph.erase_node(input_token_node)
        num_erased_inputs = len(input_token_nodes)
        assert num_erased_inputs == expected_num_erased, f'{subgraph} num_erased_inputs:{num_erased_inputs} {input_token_nodes}!=expected {expected_num_erased}'
        assert num_erased_outs == expected_num_erased, f'{subgraph} num_erased_outs:{num_erased_outs} {output_token_nodes}!=expected {expected_num_erased}'
        module.recompile()
    if num_forward_tokens > 0:
        if aot_config.enable_log:
            from torch._dynamo.utils import lazy_format_graph_code
            aot_graphs_effects_log.debug('%s', lazy_format_graph_code('Forward graph before unlifting tokens', fw_module, aot_config.aot_id, include_stride=True, include_device=True, colored=True))
        do(fw_module, 'forward', num_forward_tokens)
    if bw_module is not None and num_backward_tokens > 0:
        if aot_config.enable_log:
            from torch._dynamo.utils import lazy_format_graph_code
            aot_graphs_effects_log.debug('%s', lazy_format_graph_code('Backward graph before unlifting tokens', bw_module, aot_config.aot_id, include_stride=True, include_device=True, colored=True))
        do(bw_module, 'backward', num_backward_tokens)
    fw_metadata.tokens = {}
    fw_metadata.num_backward_tokens = 0

def _to_placeholder(self):
    ragged_spec = self.type_spec
    if ragged_spec.ragged_rank == 0 or ragged_spec.shape.rank is None:
        return super(RaggedKerasTensor, self)._to_placeholder()
    flat_shape = ragged_spec.shape[ragged_spec.ragged_rank:]
    result = array_ops.placeholder(ragged_spec.dtype, flat_shape)
    known_num_splits = []
    prod = 1
    for axis_size in ragged_spec.shape:
        if <MASK>:
            if axis_size is None or getattr(axis_size, 'value', True) is None:
                prod = None
            else:
                prod = prod * axis_size
        known_num_splits.append(prod)
    for axis in range(ragged_spec.ragged_rank, 0, -1):
        axis_size = ragged_spec.shape[axis]
        if axis_size is None or getattr(axis_size, 'value', True) is None:
            num_splits = known_num_splits[axis - 1]
            if num_splits is not None:
                num_splits = num_splits + 1
            splits = array_ops.placeholder(ragged_spec.row_splits_dtype, [num_splits])
            result = ragged_tensor.RaggedTensor.from_row_splits(result, splits, validate=False)
        else:
            rowlen = constant_op.constant(axis_size, ragged_spec.row_splits_dtype)
            result = ragged_tensor.RaggedTensor.from_uniform_row_length(result, rowlen, validate=False)
    return result

@staticmethod
def validate_categories(categories, fastpath: bool=False) -> Index:
    """
        Validates that we have good categories

        Parameters
        ----------
        categories : array-like
        fastpath : bool
            Whether to skip nan and uniqueness checks

        Returns
        -------
        categories : Index
        """
    from pandas.core.indexes.base import Index
    if not fastpath and (not is_list_like(categories)):
        raise TypeError(f"Parameter 'categories' must be list-like, was {categories!r}")
    if <MASK>:
        categories = Index._with_infer(categories, tupleize_cols=False)
    if not fastpath:
        if categories.hasnans:
            raise ValueError('Categorical categories cannot be null')
        if not categories.is_unique:
            raise ValueError('Categorical categories must be unique')
    if isinstance(categories, ABCCategoricalIndex):
        categories = categories.categories
    return categories

def collect_stats(files, fd, pattern):
    line_regexs = [re.compile('(?P<lineno>[0-9]+)(\\s[0-9]+)+'), re.compile('((jump)|(jcnd))=([0-9]+)\\s(?P<lineno>[0-9]+)')]
    current_file = None
    current_function = None
    for line in fd:
        if re.match('f[lie]=.+', line):
            path = line.split('=', 2)[1].strip()
            if os.path.exists(path) and re.search(pattern, path):
                current_file = files.get_file(path)
            else:
                current_file = None
        elif <MASK>:
            current_function = line.split('=', 2)[1].strip()
        elif current_file is not None:
            for regex in line_regexs:
                match = regex.match(line)
                if match:
                    lineno = int(match.group('lineno'))
                    current_file.mark_line(lineno, current_function)

def getsetitem(self: Any, index: Any, tensors_have_dims: bool) -> IndexingInfo:
    from . import DimList
    can_call_original_getitem = not tensors_have_dims
    input_list = []
    if has_dims(index):
        input_list.append(index)
    else:
        is_sequence = extractIndices(index, input_list)
        if can_call_original_getitem and (not is_sequence):
            return IndexingInfo(can_call_original=True)
    dims_indexed = 0
    expanding_object = -1
    unbound_dim_list = None
    dimlists = []

    def check_expanding(i: int) -> None:
        nonlocal expanding_object
        if expanding_object != -1:
            from . import DimensionBindError
            raise DimensionBindError(f'at most one ... or unbound dimension list can exist in indexing list but found 2 at offsets {expanding_object} and {i}')
        expanding_object = i

    def is_dimpack(s: Any) -> bool:
        from . import Dim
        return isinstance(s, (tuple, list)) and len(s) > 0 and all((Dim.check_exact(item) for item in s))
    has_dimpacks_or_none = False
    for (i, s) in enumerate(input_list):
        if has_dims(s):
            can_call_original_getitem = False
            dims_indexed += 1
        elif s is ...:
            check_expanding(i)
        elif isinstance(s, DimList):
            can_call_original_getitem = False
            if not s.is_bound:
                check_expanding(i)
                unbound_dim_list = s
            else:
                dims_indexed += len(s._dims)
            dimlists.append(i)
        elif s is None:
            has_dimpacks_or_none = True
        elif is_dimpack(s):
            can_call_original_getitem = False
            has_dimpacks_or_none = True
            dims_indexed += 1
        else:
            dims_indexed += 1
    if <MASK>:
        return IndexingInfo(can_call_original=True)
    self_info = TensorInfo.create(self, False, True)
    total_dims = len(self_info.levels)
    if dims_indexed > total_dims:
        raise ValueError(f'at least {dims_indexed} indices were supplied but the tensor only has {total_dims} dimensions')
    expanding_dims = total_dims - dims_indexed
    if expanding_object != -1:
        if unbound_dim_list is not None:
            unbound_dim_list.bind_len(expanding_dims)
        else:
            no_slices = [slice(None)] * expanding_dims
            input_list = input_list[:expanding_object] + no_slices + input_list[expanding_object + 1:]
    for i in range(len(dimlists) - 1, -1, -1):
        idx = dimlists[i]
        if unbound_dim_list is None and expanding_object != -1 and (idx > expanding_object):
            idx += expanding_dims
        dl = input_list[idx]
        input_list = input_list[:idx] + dl._dims + input_list[idx + 1:]
    return getsetitem_flat(self_info, input_list, [], [], has_dimpacks_or_none)

def generate_py_arg(self, py_args_var, idx, raw_arg, arg_type):

    def generate_py_arg_inner(lines, raw_arg, arg_type):

        def handle_scalar(scalar):
            if isinstance(scalar, int):
                return f'PyLong_FromLongLong({scalar})'
            if isinstance(scalar, float):
                return f'PyFloat_FromDouble({self.generate_float_value(scalar)})'
            if isinstance(scalar, bool):
                return f'PyBool_FromLong({(1 if scalar else 0)})'
            if isinstance(scalar, complex):
                real = self.generate_float_value(scalar.real)
                imag = self.generate_float_value(scalar.imag)
                return f'PyComplex_FromDoubles({real}, {imag})'
            if isinstance(scalar, SymTypes):
                scalar_var = cexpr(scalar.node.expr)
                if isinstance(scalar, torch.SymBool):
                    return f'PyBool_FromLong({scalar_var})'
                if isinstance(scalar, torch.SymFloat):
                    return f'PyFloat_FromDouble({scalar_var})'
                return f'PyLong_FromLongLong({scalar_var})'
            raise NotImplementedError(f'scalar {scalar}, {type(scalar)} cannot be handled by handle_scalar')
        if raw_arg is None:
            lines.append('Py_INCREF(Py_None);\n')
            return 'Py_None'
        elif isinstance(arg_type, torch.TensorType):
            if not hasattr(raw_arg, 'codegen_reference'):
                return handle_scalar(raw_arg)
            base_handle = self.create_tmp_raii_handle_var_if_needed(raw_arg.codegen_reference(), lines)
            return f'PyCapsule_New(reinterpret_cast<void*>({base_handle}.get()), NULL, NULL)'
        elif isinstance(arg_type, torch.OptionalType):
            return generate_py_arg_inner(lines, raw_arg, arg_type.getElementType())
        elif isinstance(arg_type, torch.IntType):
            return f'PyLong_FromLongLong({raw_arg})'
        elif <MASK>:
            expr = raw_arg.node.expr if isinstance(raw_arg, torch.SymInt) else raw_arg
            return f'PyLong_FromLongLong({cexpr(expr)})'
        elif isinstance(arg_type, torch.FloatType):
            return f'PyFloat_FromDouble({self.generate_float_value(raw_arg)})'
        elif isinstance(arg_type, torch.BoolType):
            return f'PyBool_FromLong({(1 if raw_arg else 0)})'
        elif isinstance(arg_type, torch.StringType):
            return f'PyUnicode_FromString("{raw_arg}")'
        elif isinstance(arg_type, torch.NumberType):
            return handle_scalar(raw_arg)
        elif isinstance(raw_arg, torch.device):
            (device_str, device_index) = self.codegen_device(raw_arg).split(', ')
            return f'THPDevice_New(c10::Device(static_cast<c10::DeviceType>({device_str}), {device_index}))'
        elif isinstance(raw_arg, torch.dtype):
            return f'Py_NewRef(torch::getTHPDtype(static_cast<c10::ScalarType>({self.codegen_dtype(raw_arg)})))'
        elif isinstance(raw_arg, torch.layout):
            return f'Py_NewRef(torch::getTHPLayout(static_cast<c10::Layout>({self.codegen_layout(raw_arg)})))'
        elif isinstance(raw_arg, torch.memory_format):
            return f'Py_NewRef(torch::utils::getTHPMemoryFormat(static_cast<c10::MemoryFormat>({self.codegen_memory_format(raw_arg)})))'
        else:
            raise NotImplementedError(f'arg type {arg_type} is not yet supported by custom_op_wrapper')
    lines = []
    if isinstance(arg_type, torch.ListType):
        assert isinstance(raw_arg, (list, tuple)), str(raw_arg) + ' is not a list'
        lines.append(f'PyObject* {py_args_var}_{idx} = PyList_New({len(raw_arg)});\n')
        for (i, elem) in enumerate(raw_arg):
            lines.append(f'PyList_SetItem({py_args_var}_{idx}, {i}, {generate_py_arg_inner(lines, elem, arg_type.getElementType())});\n')
        lines.append(f'PyTuple_SetItem({py_args_var}, {idx}, {py_args_var}_{idx});\n')
    else:
        lines.append(f'PyTuple_SetItem({py_args_var}, {idx}, {generate_py_arg_inner(lines, raw_arg, arg_type)});\n')
    return ''.join(lines)

def _create_batched_inputs(in_dims: in_dims_t, args: tuple, vmap_level: int, func: Callable) -> tuple[tuple, int]:
    if not isinstance(in_dims, int) and (not isinstance(in_dims, tuple)):
        raise ValueError(f'vmap({_get_name(func)}, in_dims={in_dims}, ...)(<inputs>): expected `in_dims` to be int or a (potentially nested) tuple matching the structure of inputs, got: {type(in_dims)}.')
    if len(args) == 0:
        raise ValueError(f'vmap({_get_name(func)})(<inputs>): got no inputs. Maybe you forgot to add inputs, or you are trying to vmap over a function with no inputs. The latter is unsupported.')
    (flat_args, args_spec) = tree_flatten(args)
    flat_in_dims = _broadcast_to_and_flatten(in_dims, args_spec)
    if flat_in_dims is None:
        raise ValueError(f'vmap({_get_name(func)}, in_dims={in_dims}, ...)(<inputs>): in_dims is not compatible with the structure of `inputs`. in_dims has structure {tree_flatten(in_dims)[1]} but inputs has structure {args_spec}.')
    for (arg, in_dim) in zip(flat_args, flat_in_dims):
        if not isinstance(in_dim, int) and in_dim is not None:
            raise ValueError(f'vmap({_get_name(func)}, in_dims={in_dims}, ...)(<inputs>): Got in_dim={in_dim} for an input but in_dim must be either an integer dimension or None.')
        if isinstance(in_dim, int) and (not isinstance(arg, Tensor)):
            raise ValueError(f'vmap({_get_name(func)}, in_dims={in_dims}, ...)(<inputs>): Got in_dim={in_dim} for an input but the input is of type {type(arg)}. We cannot vmap over non-Tensor arguments, please use None as the respective in_dim')
        if <MASK>:
            raise ValueError(f'vmap({_get_name(func)}, in_dims={in_dims}, ...)(<inputs>): Got in_dim={in_dim} for some input, but that input is a Tensor of dimensionality {arg.dim()} so expected in_dim to satisfy 0 <= in_dim < {arg.dim()}.')
    batch_size = _validate_and_get_batch_size(flat_in_dims, flat_args)
    batched_inputs = [arg if in_dim is None else torch._add_batch_dim(arg, in_dim, vmap_level) for (in_dim, arg) in zip(flat_in_dims, flat_args)]
    return (tree_unflatten(batched_inputs, args_spec), batch_size)

def __init__(self, *, expression, output_field, db_persist, **kwargs):
    if kwargs.setdefault('editable', False):
        raise ValueError('GeneratedField cannot be editable.')
    if <MASK>:
        raise ValueError('GeneratedField must be blank.')
    if kwargs.get('default', NOT_PROVIDED) is not NOT_PROVIDED:
        raise ValueError('GeneratedField cannot have a default.')
    if kwargs.get('db_default', NOT_PROVIDED) is not NOT_PROVIDED:
        raise ValueError('GeneratedField cannot have a database default.')
    if db_persist not in (True, False):
        raise ValueError('GeneratedField.db_persist must be True or False.')
    self.expression = expression
    self.output_field = output_field
    self.db_persist = db_persist
    super().__init__(**kwargs)

def add_lib_preload(self, lib_type):
    """Enable TCMalloc/JeMalloc/intel OpenMP."""
    library_paths = []
    if 'CONDA_PREFIX' in os.environ:
        library_paths.append(f"{os.environ['CONDA_PREFIX']}/lib")
    if <MASK>:
        library_paths.append(f"{os.environ['VIRTUAL_ENV']}/lib")
    library_paths += [f"{expanduser('~')}/.local/lib", '/usr/local/lib', '/usr/local/lib64', '/usr/lib', '/usr/lib64']
    lib_find = False
    lib_set = False
    for item in os.getenv('LD_PRELOAD', '').split(':'):
        if item.endswith(f'lib{lib_type}.so'):
            lib_set = True
            break
    if not lib_set:
        for lib_path in library_paths:
            library_file = os.path.join(lib_path, f'lib{lib_type}.so')
            matches = glob.glob(library_file)
            if len(matches) > 0:
                ld_preloads = [f'{matches[0]}', os.getenv('LD_PRELOAD', '')]
                os.environ['LD_PRELOAD'] = os.pathsep.join([p.strip(os.pathsep) for p in ld_preloads if p])
                lib_find = True
                break
    return lib_set or lib_find

@functools.lru_cache(maxsize=1)
def get_np_to_tnp_map():
    """
    This generates a mapping from numpy modules to their torch._numpy
    modules equivalents.
    """
    from ..utils import NP_TO_TNP_MODULE
    np_fn_to_tnp_fn = {}
    for (np_mod, tnp_mod) in NP_TO_TNP_MODULE.items():
        for (fn_name, tnp_fn) in tnp_mod.__dict__.items():
            if callable(tnp_fn):
                if <MASK>:
                    np_fn_to_tnp_fn[np_fn] = tnp_fn
    return np_fn_to_tnp_fn

def _explicit_order_placements(mesh_shape: ShapeType, placements: Sequence[Placement]) -> Sequence[tuple[int, Placement]]:
    """
    Replace Strided Shards with regular shards in an adjusted order.

    Returns a list of (mesh_dim, placement) tuples where the list order is the sharding order.

    ex.
    [Shard(0), _StridedShard(0, split_factor=2), Shard(0)] ->
    [(0, Shard(0)), (2, Shard(0)), (1, Shard(0))]

    """
    if not len(placements) == len(mesh_shape):
        raise RuntimeError(f'Expected one placement per mesh dim, but found {len(placements)} placements and {len(mesh_shape)} mesh dims.')
    ordered = []
    deferred_strided_placements = defaultdict(list)
    strided_part_ended_for_dim = set()
    for (mesh_dim, p) in enumerate(placements):
        if isinstance(p, _StridedShard):
            deferred_strided_placements[p.dim].append((mesh_dim, p))
        else:
            ordered.append((mesh_dim, p))
            if isinstance(p, Shard):
                if p.dim in strided_part_ended_for_dim:
                    raise NotImplementedError(f'Strided sharding does not allow Shard() to appear after the strided part has ended. {p} at mesh dim {mesh_dim} in {placements} violates this assumption.')
                if p.dim in deferred_strided_placements:
                    strided_part_ended_for_dim.add(p.dim)
                    strided_placements = deferred_strided_placements.pop(p.dim)
                    aggregate_size = mesh_shape[mesh_dim]
                    while len(strided_placements) > 0:
                        (strided_mesh_dim, strided) = strided_placements.pop()
                        if <MASK>:
                            raise RuntimeError(f'Can only convert _StridedShard to ordered Shard if split_factor({strided.split_factor}) == aggregate mesh size ({aggregate_size})')
                        aggregate_size *= mesh_shape[strided_mesh_dim]
                        ordered.append((strided_mesh_dim, Shard(p.dim)))
    return ordered

def make_terse(blocks: Sequence[dict[str, Any]], index_by_line: bool=True) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    max_line = max((b['start_line'] for b in blocks)) if blocks else 0
    line_field_width = len(str(max_line))
    for b in blocks:
        root = f"{b['category']} {b['full_name']}"
        for i in itertools.count():
            name = root + bool(i) * f'[{i + 1}]'
            if name not in result:
                break
        d = {'docstring_len': len(b['docstring']), 'lines': b['line_count'], 'status': b.get('status', 'good')}
        start_line = b['start_line']
        if <MASK>:
            d['name'] = name
            result[f'{start_line:>{line_field_width}}'] = d
        else:
            d['line'] = start_line
            result[name] = d
        if (kids := b['children']):
            if not all((isinstance(k, int) for k in kids)):
                assert all((isinstance(k, dict) for k in kids))
                d['children'] = make_terse(kids)
    return result

def collect_replacements(expressions):
    while expressions:
        expr = expressions.pop()
        if expr in replacements:
            continue
        elif (select_alias := select.get(expr)):
            replacements[expr] = select_alias
        elif isinstance(expr, Lookup):
            expressions.extend(expr.get_source_expressions())
        elif <MASK>:
            if expr.refs not in select_aliases:
                expressions.extend(expr.get_source_expressions())
        else:
            num_qual_alias = len(qual_aliases)
            select_alias = f'qual{num_qual_alias}'
            qual_aliases.add(select_alias)
            inner_query.add_annotation(expr, select_alias)
            replacements[expr] = select_alias

def astype(self, dtype, copy: bool=True):
    dtype = pandas_dtype(dtype)
    if dtype == self._dtype:
        if not copy:
            return self
        else:
            return self.copy()
    if isinstance(dtype, PeriodDtype):
        return self.asfreq(dtype.freq)
    if <MASK>:
        tz = getattr(dtype, 'tz', None)
        unit = dtl.dtype_to_unit(dtype)
        return self.to_timestamp().tz_localize(tz).as_unit(unit)
    return super().astype(dtype, copy=copy)

@torch.no_grad()
def _init_sharded_param(self, param: nn.Parameter, device: torch.device, shard_placement_fn: Optional[Callable]):
    if param.device != device and param.device.type != 'meta':
        raise AssertionError(f'Expects the parameter to already be moved to device {device} but got {param.device}')
    if not param.is_contiguous():
        raise NotImplementedError(f'FSDP does not support non-contiguous parameters yet: param.shape={param.shape!r} param.stride()={param.stride()!r}')
    fsdp_placement = shard_placement_fn(param) if shard_placement_fn else None
    if fsdp_placement is None:
        fsdp_placement = Shard(0)
    elif fsdp_placement.dim < 0:
        fsdp_placement = Shard(fsdp_placement.dim + param.ndim)
    if not isinstance(fsdp_placement, Shard):
        raise AssertionError(f'Expected Shard, got {type(fsdp_placement)}: {fsdp_placement}')
    self.fsdp_placement = fsdp_placement
    shard_dim = fsdp_placement.dim
    self.is_dtensor = isinstance(param, DTensor)
    if self.is_dtensor:
        self._tp_spec = cast(DTensor, param)._spec
        (dp_mesh, tp_mesh) = (self.mesh_info.mesh, self._tp_spec.mesh)
        dp_global_mesh = dp_mesh._get_root_mesh() if dp_mesh is not None else None
        tp_global_mesh = tp_mesh._get_root_mesh() if tp_mesh is not None else None
        if dp_global_mesh != tp_global_mesh or (dp_global_mesh is None or tp_global_mesh is None):
            raise AssertionError(f"FSDP requires the DP and model parallel TP/EP mesh to have the same parent mesh but got: \nDP's global mesh: {dp_global_mesh}\nTP/EP's global mesh: {tp_global_mesh}")
        name_dims_error = 'FSDP requires named DeviceMesh dims for ND parallelism'
        if dp_mesh.mesh_dim_names is None:
            raise AssertionError(name_dims_error)
        if tp_mesh.mesh_dim_names is None:
            raise AssertionError(name_dims_error)
        submesh_names = dp_mesh.mesh_dim_names + tp_mesh.mesh_dim_names
        self._spmd_mesh = dp_global_mesh[submesh_names]
        if len(self._tp_spec.placements) > 2:
            raise NotImplementedError(f'FSDP only supports 1D TP/EP or 2D EP+TP, not {self._tp_spec.placements}')
        split_factor = self._tp_spec.num_shards_map[shard_dim]
        if not 2 <= self._spmd_mesh.ndim <= 4:
            raise AssertionError(f'_spmd_mesh.ndim can only be 2 (FSDP+TP/EP), 3 (FSDP+EP+TP, HSDP+TP/EP), or 4 (HSDP+EP+TP) but got {self._spmd_mesh.ndim}.')
        self._spmd_placements: tuple[Placement, ...]
        dp_shard_tp_placement = (_StridedShard(shard_dim, split_factor=split_factor) if split_factor > 1 else fsdp_placement, *self._tp_spec.placements)
        if dp_mesh.ndim == 1:
            self._spmd_placements = dp_shard_tp_placement
        else:
            if self.mesh_info.replicate_mesh_dim != 0:
                raise AssertionError(f'Expected replicate_mesh_dim to be 0, got {self.mesh_info.replicate_mesh_dim}')
            self._spmd_placements = (Replicate(),) + dp_shard_tp_placement
        self._sharding_spec = DTensorSpec(self._spmd_mesh, self._spmd_placements, tensor_meta=self._tp_spec.tensor_meta)
        param_data = cast(DTensor, param)._local_tensor
    else:
        self._spmd_mesh = self.mesh_info.mesh
        if isinstance(self.mesh_info, HSDPMeshInfo):
            self._spmd_placements = (Replicate(), fsdp_placement)
        else:
            self._spmd_placements = (fsdp_placement,)
        self._sharding_spec = DTensorSpec(self._spmd_mesh, self._spmd_placements, tensor_meta=TensorMeta(param.size(), param.stride(), param.dtype))
        param_data = param
    if not param_data.is_contiguous():
        raise AssertionError(f'Expected contiguous tensor, got param_data.shape={param_data.shape!r} param_data.stride()={param_data.stride()!r}')
    shard_dim = fsdp_placement.dim
    if shard_dim >= param_data.ndim:
        raise AssertionError(f'Shard dim {shard_dim} is invalid for {param_data.ndim}D tensor: {param.shape}')
    self._orig_size = param_data.size()
    self._contiguous_orig_stride = make_contiguous_strides_for(self._orig_size)
    shard_rank = self.mesh_info.shard_mesh_rank
    shard_world_size = self.mesh_info.shard_mesh_size
    if shard_dim > 0 and param_data.size(shard_dim) % shard_world_size != 0:
        raise NotImplementedError(f'FSDP does not support uneven sharding on dim {shard_dim}: {param_data.size()} (world size: {shard_world_size})')
    chunks = _chunk_with_empty(param_data, shard_world_size, dim=shard_dim)
    sharded_param = chunks[shard_rank]
    self.sharded_size = _get_dim_chunked_size(sharded_param, param_data.size(), dim=shard_dim)
    self.contiguous_sharded_stride = make_contiguous_strides_for(self.sharded_size)
    padded_sharded_size = chunks[0].size()
    self.padded_sharded_param_size = padded_sharded_size
    padded_sharded_param = param_data.new_zeros(padded_sharded_size)
    if sharded_param.numel() > 0:
        padded_sharded_param.narrow(dim=shard_dim, start=0, length=sharded_param.size(shard_dim)).copy_(sharded_param)
    if self.offload_to_cpu and (not padded_sharded_param.is_meta):
        padded_sharded_param = padded_sharded_param.cpu()
        if self.pin_memory:
            padded_sharded_param = padded_sharded_param.pin_memory()
    self._sharded_param_data = padded_sharded_param.view(-1)
    length = sharded_param.size(shard_dim) if sharded_param.numel() > 0 else 0
    sharded_param = padded_sharded_param.narrow(dim=shard_dim, start=0, length=length)
    if <MASK>:
        raise AssertionError(f'Expected contiguous tensor with self.fsdp_placement={self.fsdp_placement!r}')
    self.sharded_param = nn.Parameter(self.to_sharded_dtensor(sharded_param))
    self.sharded_param.requires_grad_(param.requires_grad)
    self._setattr_on_modules(self.sharded_param)
    self.sharded_state = ShardedState.SHARDED

def _initialize_formatters(self, formatters: FormattersType | None) -> FormattersType:
    if formatters is None:
        return {}
    elif <MASK>:
        return formatters
    else:
        raise ValueError(f'Formatters length({len(formatters)}) should match DataFrame number of columns({len(self.frame.columns)})')

@property
def name(self):
