@rpc.functions.async_execution
def async_add_multi_fanout(to, x, num, step):
    futs = []
    for i in range(num):
        if i == 0:
            futs.append(rpc.rpc_async(to, torch.add, args=(x, step)))
        else:
            futs.append(rpc.rpc_async(to, torch.add, args=(0, step)))
    lock = Lock()
    state = {'cnt': 0, 'ret': torch.zeros_like(x)}
    ret_future = torch.futures.Future()

    def inc_and_set(fut):
        with lock:
            state['cnt'] += 1
            state['ret'] += fut.wait()
            if <MASK>:
                ret_future.set_result(state['ret'])
    for fut in futs:
        fut.then(inc_and_set)
    return ret_future

def get_assignments_with_compile_ignored_comments(module: ModuleType) -> set[str]:
    source_code = inspect.getsource(module)
    assignments = set()
    tokens = tokenize.tokenize(io.BytesIO(source_code.encode('utf-8')).readline)
    current_comment = ('', -1)
    prev_name = ''
    for token in tokens:
        if token.type == tokenize.COMMENT:
            prev_name = ''
            maybe_current = token.string.strip()
            if <MASK>:
                assert current_comment == ('', -1), f'unconsumed {COMPILE_IGNORED_MARKER}'
                current_comment = (maybe_current, token.start[0])
        elif token.type == tokenize.NAME:
            if not prev_name:
                prev_name = token.string
        elif token.type == tokenize.OP and token.string == '=':
            if COMPILE_IGNORED_MARKER in current_comment[0] and current_comment[1] == token.start[0] - 1:
                assignments.add(prev_name)
                current_comment = ('', -1)
            prev_name = ''
    assert current_comment == ('', -1), f'unconsumed {COMPILE_IGNORED_MARKER}'
    return assignments

def adapt_datetimefield_value(self, value):
    if value is None:
        return None
    if timezone.is_aware(value):
        if <MASK>:
            value = timezone.make_naive(value, self.connection.timezone)
        else:
            raise ValueError('SQLite backend does not support timezone-aware datetimes when USE_TZ is False.')
    return str(value)

def __arrow_array__(self, type=None):
    """
        Convert myself into a pyarrow Array.
        """
    import pyarrow
    from pandas.core.arrays.arrow.extension_types import ArrowIntervalType
    try:
        subtype = pyarrow.from_numpy_dtype(self.dtype.subtype)
    except TypeError as err:
        raise TypeError(f"Conversion to arrow with subtype '{self.dtype.subtype}' is not supported") from err
    interval_type = ArrowIntervalType(subtype, self.closed)
    storage_array = pyarrow.StructArray.from_arrays([pyarrow.array(self._left, type=subtype, from_pandas=True), pyarrow.array(self._right, type=subtype, from_pandas=True)], names=['left', 'right'])
    mask = self.isna()
    if mask.any():
        null_bitmap = pyarrow.array(~mask).buffers()[1]
        storage_array = pyarrow.StructArray.from_buffers(storage_array.type, len(storage_array), [null_bitmap], children=[storage_array.field(0), storage_array.field(1)])
    if <MASK>:
        if type.equals(interval_type.storage_type):
            return storage_array
        elif isinstance(type, ArrowIntervalType):
            if not type.equals(interval_type):
                raise TypeError(f"Not supported to convert IntervalArray to type with different 'subtype' ({self.dtype.subtype} vs {type.subtype}) and 'closed' ({self.closed} vs {type.closed}) attributes")
        else:
            raise TypeError(f"Not supported to convert IntervalArray to '{type}' type")
    return pyarrow.ExtensionArray.from_storage(interval_type, storage_array)

def __enter__(self):
    ctx = self._ctx
    old_device_name = ctx.device_name
    old_device_spec = ctx.device_spec
    new_device_name = self._device_name
    cache_key = (old_device_name, new_device_name)
    try:
        (new_device_name, new_device_spec) = _device_parsing_cache[cache_key]
    except TypeError as exc:
        raise ValueError('Expecting a string device name. Got %s(%s)' % (type(new_device_name), new_device_name)) from exc
    except KeyError as exc:
        if new_device_name is not None:
            if not isinstance(new_device_name, str):
                raise ValueError('Expecting a string device name. Got %s(%s)' % (type(new_device_name), new_device_name)) from exc
            device_spec = pydev.DeviceSpec.from_string(new_device_name)
            if <MASK>:
                new_device_spec = copy.copy(old_device_spec)
            else:
                ctx.ensure_initialized()
                new_device_spec = pydev.DeviceSpec.from_string(ctx._context_devices[0])
            new_device_spec = new_device_spec.make_merged_spec(device_spec)
        else:
            new_device_spec = pydev.DeviceSpec.from_string('')
        new_device_name = new_device_spec.to_string()
        _device_parsing_cache[cache_key] = (new_device_name, new_device_spec)
    ctx._set_device(new_device_name, new_device_spec)
    self._stack.append((old_device_name, old_device_spec, new_device_spec))

def check_can_launch() -> StaticallyLaunchedCudaKernel:
    if triton_meta.get('device_type') != 'cuda':
        raise CannotStaticallyLaunchKernel('Non-cuda device')
    if <MASK>:
        raise CannotStaticallyLaunchKernel('Cpp wrapper enabled')
    if heuristic_type == HeuristicType.USER_AUTOTUNE and (not torch._inductor.config.static_launch_user_defined_triton_kernels):
        raise CannotStaticallyLaunchKernel('User defined triton kernel')
    if inductor_meta.get('store_cubin'):
        raise CannotStaticallyLaunchKernel('store_cubin is enabled')
    if getattr(kernel.metadata, 'launch_pdl', False) or getattr(kernel.metadata, 'launch_cooperative_grid', False):
        raise CannotStaticallyLaunchKernel('static launch does not support launch attributes')
    cubin_location = os.path.join(triton_cache_dir(triton_meta.get('device', 0)), triton_hash_to_path_key(kernel.hash), f'{kernel.src.fn.__name__}.cubin')
    if not os.path.exists(cubin_location):
        raise CannotStaticallyLaunchKernel(f'Cubin path not found: {cubin_location}')
    else:
        kernel._cubin_path = cubin_location
    try:
        static_kernel = StaticallyLaunchedCudaKernel(kernel)
    except NotImplementedError as e:
        raise CannotStaticallyLaunchKernel(f'NotImplemented: {str(e)}') from e
    return static_kernel

def GetLiftedIdx(d):
    if <MASK>:
        return array_ops.reshape(op.outputs[1], lifted_idx_shape)
    iota_len = idx_shape[d]
    iota_shape = list(itertools.repeat(1, rank + 1))
    iota_shape[d] = iota_len
    iota = array_ops.reshape(math_ops.range(iota_len), iota_shape)
    return array_ops.broadcast_to(iota, lifted_idx_shape)

@register_lowering(aten.diagonal, type_promotion_kind=None)
def diagonal(input, offset: int=0, dim1: int=0, dim2: int=1):
    original_shape = input.get_size()
    num_dims = len(original_shape)
    dim1 = canonicalize_dim(idx=dim1, rank=num_dims)
    dim2 = canonicalize_dim(idx=dim2, rank=num_dims)
    check(dim1 != dim2, lambda : f'diagonal dimensions cannot be identical {dim1}, {dim2}')
    offset_negative = V.graph.sizevars.evaluate_expr(sympy.Lt(offset, 0))
    if <MASK>:
        diag_size = V.graph.sizevars.evaluate_max(V.graph.sizevars.evaluate_min(original_shape[dim1] + offset, original_shape[dim2]), 0)
    else:
        diag_size = V.graph.sizevars.evaluate_max(V.graph.sizevars.evaluate_min(original_shape[dim1], original_shape[dim2] - offset), 0)
    base_idx = (0, 0)
    if offset_negative:
        base_idx = (-offset, 0)
    else:
        base_idx = (0, offset)
    sizes = [s for (i, s) in enumerate(original_shape) if i not in (dim1, dim2)]
    sizes.append(diag_size)

    def reindexer(idx):
        diag_idx = idx[-1]
        original_idx = [0] * len(original_shape)
        cur_dim = 0
        for d in range(num_dims):
            if d == dim1:
                original_idx[d] = diag_idx + base_idx[0]
            elif d == dim2:
                original_idx[d] = diag_idx + base_idx[1]
            else:
                original_idx[d] = idx[cur_dim]
                cur_dim += 1
        assert cur_dim == len(original_shape) - 2
        return original_idx
    return TensorBox(ir.GenericView.create(input, sizes, reindexer))

def _DefaultGradYs(grad_ys, ys, colocate_gradients_with_ops, gradient_uid='__unsupported__'):
    """Fill in default values for grad_ys.

  Args:
    grad_ys: List of gradients, can contain None.
    ys: List of tensors.
    colocate_gradients_with_ops: If True, try colocating gradients with
      the corresponding op.
    gradient_uid: A unique identifier within the graph indicating
      which invocation of gradients is being executed. Used to cluster
      ops for compilation.

  Returns:
    A list of gradients to use, without None.

  Raises:
    ValueError: If sizes of gradients and inputs don't match
    TypeError: If type of any gradient is not valid for its input.
  """
    if len(grad_ys) != len(ys):
        raise ValueError(f'Length mismatch. Passed {len(grad_ys)} grad_ys for {len(ys)} ys')
    grad_ys = indexed_slices.convert_n_to_tensor_or_indexed_slices(grad_ys, name='grad_y')
    new_grad_ys = []
    for (i, (y, grad_y)) in enumerate(zip(ys, grad_ys)):
        with _maybe_colocate_with(y.op, gradient_uid, colocate_gradients_with_ops):
            if grad_y is None:
                if y.dtype.is_complex:
                    raise TypeError(f'Gradients of complex tensors ({y}) must set grad_ys (y.dtype = {dtypes.as_dtype(y.dtype).name})')
                new_grad_ys.append(array_ops.ones(array_ops.shape(y), dtype=y.dtype, name='grad_ys_%d' % i))
                continue
            if y.dtype.is_floating or y.dtype.is_integer:
                if not grad_y.dtype.is_floating and (not grad_y.dtype.is_integer):
                    raise TypeError(f'Gradient type {dtypes.as_dtype(grad_y.dtype).name} generated for real or integer-valued tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be real or integer')
            elif y.dtype.is_complex:
                if not grad_y.dtype.is_complex:
                    raise TypeError(f'Gradient type {dtypes.as_dtype(grad_y.dtype).name} generated for complex-valued tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be real')
            elif y.dtype == dtypes.variant:
                if <MASK>:
                    raise TypeError(f'Gradient type {dtypes.as_dtype(grad_y.dtype).name} generated for variant tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be variant')
            elif y.dtype == dtypes.resource:
                if grad_y.dtype == dtypes.resource:
                    raise TypeError(f'Input gradient {grad_y} for resource tensor {y} should not be a resource')
            else:
                raise TypeError(f'Tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be numeric to obtain a default gradient')
            if isinstance(grad_y, indexed_slices.IndexedSlices):
                new_grad_ys.append(indexed_slices.IndexedSlices(indices=array_ops.identity(grad_y.indices, name='grad_ys_%d_indices' % i) if isinstance(grad_y.indices, tensor_lib.Tensor) else grad_y.indices, values=array_ops.identity(grad_y.values, name='grad_ys_%d_values' % i) if isinstance(grad_y.values, tensor_lib.Tensor) else grad_y.values, dense_shape=array_ops.identity(grad_y.dense_shape, name='grad_ys_%d_shape' % i) if isinstance(grad_y.dense_shape, tensor_lib.Tensor) else grad_y.dense_shape))
            else:
                new_grad_ys.append(array_ops.identity(grad_y, name='grad_ys_%d' % i))
    return new_grad_ys

def flat_fn(*flat_args):
    nonlocal out_spec
    (args, kwargs) = pytree.tree_unflatten(flat_args, tensor_args_spec)
    tree_out = fn(*args, **kwargs)
    (flat_out, spec) = pytree.tree_flatten(tree_out)
    for i in flat_out:
        is_known_type = False
        for j in KNOWN_TYPES:
            if isinstance(i, j):
                is_known_type = True
                break
        if <MASK>:
            raise RuntimeError(f"Found {type(i)} in output, which is not a known type. If this type holds tensors, you need to register a pytree for it. See https://github.com/pytorch/functorch/issues/475 for a brief explanation why. If you don't need to register a pytree, please leave a comment explaining your use case and we'll make this more ergonomic to deal with")
    out_spec.set(spec)
    return flat_out

def mirror_files_into_torchgen() -> None:
    paths = [(CWD / 'torchgen/packaged/ATen/native/native_functions.yaml', CWD / 'aten/src/ATen/native/native_functions.yaml'), (CWD / 'torchgen/packaged/ATen/native/tags.yaml', CWD / 'aten/src/ATen/native/tags.yaml'), (CWD / 'torchgen/packaged/ATen/templates', CWD / 'aten/src/ATen/templates'), (CWD / 'torchgen/packaged/autograd', CWD / 'tools/autograd'), (CWD / 'torchgen/packaged/autograd/templates', CWD / 'tools/autograd/templates')]
    for (new_path, orig_path) in paths:
        if <MASK>:
            new_path.parent.mkdir(parents=True, exist_ok=True)
        if orig_path.is_file():
            shutil.copyfile(orig_path, new_path)
            continue
        if orig_path.is_dir():
            if new_path.exists():
                shutil.rmtree(new_path)
            shutil.copytree(orig_path, new_path)
            continue
        raise RuntimeError('Check the file paths in `mirror_files_into_torchgen()`')

def __maybe_broadcast(x, shape):
    if <MASK>:
        return None
    elif isinstance(x, Number):
        return x
    elif isinstance(x, TensorLike):
        if preserve_cpu_scalar_tensors and utils.is_cpu_scalar_tensor(x):
            return x
        if should_expand(x.shape, common_shape):
            return x.expand(common_shape)
        return x
    else:
        raise RuntimeError('Unexpected type when broadcasting: ' + str(type(x)) + '!')

def module_to_nested_dict(module: torch.nn.Module) -> dict[str, Any]:
    """Recursively converts an nn.Module into a nested dictionary with explicit 'parameters' and 'modules' keys."""
    self_dict: dict[str, Any] = {}
    self_dict['_parameters'] = {}
    self_dict['_modules'] = {}
    for attr_name in dir(module):
        try:
            if not attr_name.startswith('_') and (not callable(getattr(module, attr_name))):
                attr_value = getattr(module, attr_name)
                if <MASK>:
                    self_dict[attr_name] = attr_value
        except NotImplementedError:
            continue
    for (name, param) in module.named_parameters(recurse=False):
        self_dict['_parameters'][name] = param
    for (name, buffer) in module.named_buffers(recurse=False):
        self_dict['_parameters'][name] = buffer
    for (name, submodule) in module.named_children():
        self_dict['_modules'][name] = module_to_nested_dict(submodule)
    return self_dict

def _compute_numerical_jvps_wrt_specific_input(jvp_fn, delta, input_is_complex, is_forward_ad=False) -> list[torch.Tensor]:
    jvps: list[torch.Tensor] = []
    ds_dx_tup = jvp_fn(delta[0] if isinstance(delta, tuple) else delta)
    if input_is_complex:
        ds_dy_tup = jvp_fn(delta[1] * 1j) if isinstance(delta, tuple) else jvp_fn(delta * 1j)
        for (ds_dx, ds_dy) in zip(ds_dx_tup, ds_dy_tup):
            if <MASK>:
                raise AssertionError('Expected ds_dx to be real-valued, not complex')
            conj_w_d = ds_dx + ds_dy * 1j
            jvps.append(conj_w_d)
    else:
        for ds_dx in ds_dx_tup:
            if not is_forward_ad and ds_dx.is_complex():
                raise AssertionError('Expected ds_dx to be real-valued, not complex.')
            jvps.append(ds_dx)
    return jvps

@staticmethod
def backward(ctx, grad_output: 'dtensor.DTensor'):
    previous_spec = ctx.current_spec
    async_op = ctx.async_op
    backward_dtype = ctx.backward_dtype or ctx.original_dtype
    if backward_dtype != grad_output._local_tensor.dtype:
        local_tensor = grad_output._local_tensor.to(dtype=backward_dtype)
        current_spec = DTensorSpec(mesh=grad_output._spec.device_mesh, placements=grad_output._spec.placements, tensor_meta=TensorMeta(shape=grad_output.shape, stride=grad_output.stride(), dtype=backward_dtype))
        previous_spec = DTensorSpec(mesh=previous_spec.device_mesh, placements=previous_spec.placements, tensor_meta=current_spec.tensor_meta)
    else:
        local_tensor = grad_output._local_tensor
        current_spec = grad_output._spec
    output = redistribute_local_tensor(local_tensor, current_spec, previous_spec, async_op=async_op, is_backward=True)
    if <MASK>:
        output = output.to(ctx.original_dtype)
    normalized_placements: list[Placement] = []
    for previous_placement in previous_spec.placements:
        if previous_placement.is_partial():
            normalized_placements.append(Replicate())
        else:
            normalized_placements.append(previous_placement)
    spec = DTensorSpec(previous_spec.device_mesh, tuple(normalized_placements), tensor_meta=TensorMeta(shape=grad_output.shape, stride=grad_output.stride(), dtype=output.dtype))
    output_dtensor = dtensor.DTensor(output, spec, requires_grad=grad_output.requires_grad)
    return (output_dtensor, None, None, None, None, None)

def _create_tpu_strategy():
    FLAGS = flags.FLAGS
    global _did_connect_to_cluster
    global _topology
    try:
        resolver = tpu_cluster_resolver.TPUClusterResolver()
        did_automatically_resolve = True
    except ValueError:
        did_automatically_resolve = False
        resolver = tpu_cluster_resolver.TPUClusterResolver(tpu=hasattr(FLAGS, 'tpu') and FLAGS.tpu or '', zone=hasattr(FLAGS, 'zone') and FLAGS.zone or None, project=hasattr(FLAGS, 'project') and FLAGS.project or None)
    if not _did_connect_to_cluster:
        if <MASK>:
            remote.connect_to_cluster(resolver)
            _did_connect_to_cluster = True
        _topology = tpu_cluster_resolver.initialize_tpu_system(resolver)
    device_assignment = None
    if use_single_core:
        device_assignment = device_assignment_lib.DeviceAssignment(_topology, core_assignment=device_assignment_lib.SINGLE_CORE_ASSIGNMENT)
    if tf2.enabled():
        strategy = tpu_lib.TPUStrategyV2(resolver, device_assignment, experimental_spmd_xla_partitioning=enable_spmd_xla_paritioning, **kwargs)
    else:
        strategy = tpu_lib.TPUStrategyV1(resolver, steps_per_run, device_assignment, **kwargs)
    if enable_packed_variable and enable_spmd_xla_paritioning:
        raise ValueError('Packed Variable is not compatible with SPMD mode')
    strategy._enable_packed_variable_in_eager_mode = enable_packed_variable
    return strategy

