def get_msvc_cl_path() -> tuple[bool, str]:
    """
        Finds the path to cl.exe using vswhere.exe.
        """
    vswhere_path = os.path.join(os.environ.get('ProgramFiles(x86)', 'C:\\Program Files (x86)'), 'Microsoft Visual Studio', 'Installer', 'vswhere.exe')
    if not os.path.exists(vswhere_path):
        vswhere_path = os.path.join(os.environ.get('ProgramFiles', 'C:\\Program Files'), 'Microsoft Visual Studio', 'Installer', 'vswhere.exe')
        if not os.path.exists(vswhere_path):
            return (False, '')
    try:
        cmd = [vswhere_path, '-latest', '-prerelease', '-products', '*', '-requires', 'Microsoft.VisualStudio.Component.VC.Tools.x86.x64', '-property', 'installationPath']
        vs_install_path = subprocess.check_output(cmd, text=True, encoding='utf-8').strip()
        if not vs_install_path:
            return (False, '')
        msvc_tools_path = os.path.join(vs_install_path, 'VC', 'Tools', 'MSVC')
        if not os.path.exists(msvc_tools_path):
            return (False, '')
        toolset_versions = [d for d in os.listdir(msvc_tools_path) if os.path.isdir(os.path.join(msvc_tools_path, d))]
        if not toolset_versions:
            return (False, '')
        latest_toolset_version = sorted(toolset_versions, reverse=True)[0]
        cl_path = os.path.join(msvc_tools_path, latest_toolset_version, 'bin', 'HostX64', 'x64', 'cl.exe')
        if <MASK>:
            return (True, cl_path)
        else:
            cl_path = os.path.join(msvc_tools_path, latest_toolset_version, 'bin', 'HostX86', 'x86', 'cl.exe')
            if os.path.exists(cl_path):
                return (True, cl_path)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return (False, '')
    return (False, '')

def codegen(self, output_name: str, input_names: list[str], output_spec: Spec) -> str:
    """Generate code for layer_norm operation."""
    if <MASK>:
        raise ValueError('LayerNorm requires 1-3 inputs: input, optional weight, optional bias')
    if not isinstance(output_spec, TensorSpec):
        raise ValueError('LayerNormOperator can only produce TensorSpec outputs')
    normalized_shape = f'({output_spec.size[-1]},)'
    target_dtype = str(output_spec.dtype)
    input_name = input_names[0]
    if len(input_names) == 1:
        return f'{output_name} = torch.nn.functional.layer_norm({input_name}.to({target_dtype}), {normalized_shape})'
    elif len(input_names) == 2:
        weight_name = input_names[1]
        return f'{output_name} = torch.nn.functional.layer_norm({input_name}.to({target_dtype}), {normalized_shape}, weight={weight_name}.to({target_dtype}))'
    else:
        (weight_name, bias_name) = (input_names[1], input_names[2])
        return f'{output_name} = torch.nn.functional.layer_norm({input_name}.to({target_dtype}), {normalized_shape}, weight={weight_name}.to({target_dtype}), bias={bias_name}.to({target_dtype}))'

