def process_request(self, request):
    if not hasattr(request, 'user'):
        raise ImproperlyConfigured("The Django remote user auth middleware requires the authentication middleware to be installed. Edit your MIDDLEWARE setting to insert 'django.contrib.auth.middleware.AuthenticationMiddleware' before the RemoteUserMiddleware class.")
    try:
        username = request.META[self.header]
    except KeyError:
        if self.force_logout_if_no_header and request.user.is_authenticated:
            self._remove_invalid_user(request)
        return
    if request.user.is_authenticated:
        if request.user.get_username() == self.clean_username(username, request):
            return
        else:
            self._remove_invalid_user(request)
    user = auth.authenticate(request, remote_user=username)
    if <MASK>:
        request.user = user
        auth.login(request, user)

def gelu(x, approximate=False):
    if <MASK>:
        return 0.5 * x * (1.0 + np.tanh(np.sqrt(2.0 / np.pi) * (x + 0.044715 * np.power(x, 3))))
    else:
        from scipy.stats import norm
        return x * norm.cdf(x)

def codegen_with_cpp_wrapper(self) -> tuple[ValueWithLineMap, ValueWithLineMap]:
    """
        For GPU, Triton kernels are autotuned and stored as cubin files
        """
    if any((device in self.device_types for device in ['cuda', 'xpu'])):

        def extract_real_inputs() -> list[Union[int, float, torch.Tensor]]:

            def materialize(x: Union[torch.SymInt, torch.SymFloat, torch.Tensor]) -> Union[int, float, torch.Tensor]:
                if x is None:
                    return None
                elif isinstance(x, (torch.SymInt, torch.SymFloat)):
                    return x.node.hint
                elif isinstance(x, FakeTensor):
                    return defake(x)
                else:
                    assert isinstance(x, torch.Tensor), 'Unknown type when creating real inputs' + str(type(x))
                    return x
            tracing_context = torch._guards.TracingContext.try_get()
            if tracing_context is not None and (not isinstance(V.real_inputs, NullHandler)):
                if tracing_context.output_strides:
                    tracing_context.output_strides.clear()
                params_flat = [param for param in tracing_context.params_flat if param is not None]
                real_inputs = [materialize(x) for x in itertools.chain(params_flat, V.real_inputs)]
            else:
                real_inputs = [materialize(x) for x in (self.example_inputs if isinstance(V.real_inputs, NullHandler) else V.real_inputs)]
            if self.mutated_inputs:
                from .compile_fx import clone_preserve_strides
                mutated_input_idxs = [idx for (idx, name) in enumerate(self.graph_inputs) if name in self.mutated_inputs and isinstance(real_inputs[idx], torch.Tensor)]
                for idx in mutated_input_idxs:
                    mutated_inp = real_inputs[idx]
                    assert isinstance(mutated_inp, torch.Tensor)
                    real_inputs[idx] = clone_preserve_strides(mutated_inp)
                    del mutated_inp
            return real_inputs
        if config.triton.autotune_at_compile_time:
            if config.triton.autotune_with_sample_inputs:
                user_defined_kernels = False
                for op in self.operations:
                    if <MASK>:
                        user_defined_kernels = True
                        break
                if user_defined_kernels:
                    real_inputs = extract_real_inputs()
                    self.extract_autotune_inputs(real_inputs)
            return self.codegen()
        else:
            self.cpp_wrapper = False
            compiled = self.compile_to_module().call
            real_inputs = extract_real_inputs()
            with torch.utils._python_dispatch._disable_current_modes():
                compiled(real_inputs)
            del real_inputs
            self.cpp_wrapper = True
            self.removed_buffers.clear()
            self.removed_operations.clear()
            self.inplaced_to_remove.clear()
            V.graph.sizevars.precomputed_replacements.clear()
            V.graph.sizevars.inv_precomputed_replacements.clear()
            metrics.reset()
            with config.patch({'triton.autotune_at_compile_time': False}):
                return self.codegen()
    else:
        return self.codegen()

