def log_abs_det_jacobian(self, x, y):
    assert -x.dim() <= self.dim < x.dim()
    assert x.size(self.dim) == self.length
    assert -y.dim() <= self.dim < y.dim()
    assert y.size(self.dim) == self.length
    logdetjacs = []
    start = 0
    for (trans, length) in zip(self.transforms, self.lengths):
        xslice = x.narrow(self.dim, start, length)
        yslice = y.narrow(self.dim, start, length)
        logdetjac = trans.log_abs_det_jacobian(xslice, yslice)
        if trans.event_dim < self.event_dim:
            logdetjac = _sum_rightmost(logdetjac, self.event_dim - trans.event_dim)
        logdetjacs.append(logdetjac)
        start = start + length
    dim = self.dim
    if <MASK>:
        dim = dim - x.dim()
    dim = dim + self.event_dim
    if dim < 0:
        return torch.cat(logdetjacs, dim=dim)
    else:
        return sum(logdetjacs)

def load_model(self, device, model_name, batch_size=None, part=None, extra_args=None):
    if self.args.enable_activation_checkpointing:
        raise NotImplementedError('Activation checkpointing not implemented for Torchbench models')
    is_training = self.args.training
    use_eval_mode = self.args.use_eval_mode
    candidates = [f'torchbenchmark.models.{model_name}', f'torchbenchmark.canary_models.{model_name}', f'torchbenchmark.models.fb.{model_name}']
    for c in candidates:
        try:
            module = importlib.import_module(c)
            break
        except ModuleNotFoundError as e:
            if e.name != c:
                raise
    else:
        raise ImportError(f'could not import any of {candidates}')
    benchmark_cls = getattr(module, 'Model', None)
    if benchmark_cls is None:
        raise NotImplementedError(f'{model_name}.Model is None')
    if not hasattr(benchmark_cls, 'name'):
        benchmark_cls.name = model_name
    cant_change_batch_size = not getattr(benchmark_cls, 'ALLOW_CUSTOMIZE_BSIZE', True) or model_name in self._config['dont_change_batch_size']
    if cant_change_batch_size:
        batch_size = None
    if batch_size is None and is_training and (model_name in self._batch_size['training']):
        batch_size = self._batch_size['training'][model_name]
    elif batch_size is None and (not is_training) and (model_name in self._batch_size['inference']):
        batch_size = self._batch_size['inference'][model_name]
    if self.args.accuracy and model_name in self._accuracy['max_batch_size']:
        batch_size = min(batch_size, self._accuracy['max_batch_size'][model_name])
    torch.backends.__allow_nonbracketed_mutation_flag = True
    if extra_args is None:
        extra_args = []
    if part:
        extra_args += ['--part', part]
    if model_name == 'sam_fast':
        self.args.amp = True
        self.setup_amp()
    if model_name == 'vision_maskrcnn' and is_training:
        model_kwargs = {'box_detections_per_img': 4}
        benchmark = benchmark_cls(test='train', device=device, batch_size=batch_size, extra_args=extra_args, model_kwargs=model_kwargs)
        use_eval_mode = True
    elif is_training:
        benchmark = benchmark_cls(test='train', device=device, batch_size=batch_size, extra_args=extra_args)
    else:
        benchmark = benchmark_cls(test='eval', device=device, batch_size=batch_size, extra_args=extra_args)
    (model, example_inputs) = benchmark.get_module()
    if model_name in ['basic_gnn_edgecnn', 'basic_gnn_gcn', 'basic_gnn_sage', 'basic_gnn_gin']:
        _reassign_parameters(model)
    if is_training and (not use_eval_mode or model_name in self._config['only_training']):
        model.train()
    else:
        model.eval()
    gc.collect()
    batch_size = benchmark.batch_size
    if model_name == 'torchrec_dlrm':
        batch_namedtuple = namedtuple('Batch', 'dense_features sparse_features labels')
        example_inputs = tuple((batch_namedtuple(dense_features=batch.dense_features, sparse_features=batch.sparse_features, labels=batch.labels) for batch in example_inputs))
    if model_name == 'yolov3':
        example_inputs = (torch.rand(batch_size, 3, 384, 512).to(device),)
    if <MASK>:
        batch_size = 5
        assert example_inputs[0].shape[0] == batch_size
    if model_name == 'vision_maskrcnn':
        batch_size = 1
    if self.args.trace_on_xla:
        import torch_xla
    if model_name.startswith('hf') and hasattr(model, 'config') and hasattr(model.config, 'use_cache'):
        model.config.use_cache = False
    self.validate_model(model, example_inputs)
    return (device, benchmark.name, model, example_inputs, batch_size)

