def _reduce_to_lowest_terms(expr: sympy.Expr) -> sympy.Expr:
    """
    Eliminates any integer factor from a given expression.
    E.g., 6x + 4y reduces to 3x + 2y.

    Useful when an expression is == or != to 0.
    """

    def integer_coefficient(x: sympy.Expr) -> int:
        if x.is_Integer:
            return abs(int(x))
        elif x.is_Mul:
            return abs(int(x.args[0])) if x.args[0].is_Integer else 1
        else:
            return 1

    def div_by_factor(x: sympy.Expr, factor: int) -> sympy.Expr:
        if x.is_Integer:
            return x / factor
        elif x.is_Mul:
            if x.args[0] != factor:
                args = [x.args[0] / sympy.Integer(factor), *x.args[1:]]
            else:
                args = list(x.args[1:])
            return _sympy_from_args(sympy.Mul, args, is_commutative=x.is_commutative)
        else:
            raise AssertionError(f'illegal arg to div_by_factor: {x}')
    if expr.is_Add:
        atoms = cast(Sequence[sympy.Expr], expr.args)
        factor = functools.reduce(math.gcd, map(integer_coefficient, atoms))
        if <MASK>:
            return expr
        atoms = [div_by_factor(x, factor) for x in atoms]
        return _sympy_from_args(sympy.Add, atoms, sort=True, is_commutative=expr.is_commutative)
    elif expr.is_Integer:
        return S.One
    elif expr.is_Mul:
        return div_by_factor(expr, integer_coefficient(expr))
    return expr

def __init__(self, name: str, sources: Union[str, list[str]], BuildOption: BuildOptionsBase, output_dir: str='') -> None:
    self._compiler = ''
    self._cflags_args = ''
    self._definitions_args = ''
    self._include_dirs_args = ''
    self._ldflags_args = ''
    self._libraries_dirs_args = ''
    self._libraries_args = ''
    self._passthrough_parameters_args = ''
    self._orig_source_paths = []
    self._output_dir = ''
    self._target_file = ''
    self._use_relative_path: bool = False
    self._aot_mode: bool = False
    self._name = name
    self._target_name = config.aot_inductor.model_name_for_generated_files or 'aoti_model'
    self._build_option = BuildOption
    self._compiler = BuildOption.get_compiler()
    self._use_relative_path = BuildOption.get_use_relative_path()
    self._aot_mode = BuildOption.get_aot_mode()
    self._output_dir = output_dir
    self._compile_only = BuildOption.get_compile_only()
    self._precompiling = BuildOption.get_precompiling()
    self._preprocessing = BuildOption.get_preprocessing()
    assert sum((self._compile_only, self._precompiling, self._preprocessing)) <= 1
    self._do_link = not (self._compile_only or self._precompiling or self._preprocessing)
    assert not _IS_WINDOWS or not self._precompiling, 'Cannot currently precompile headers on Windows!'
    if self._compile_only:
        (file_ext, output_flags) = self.__get_object_flags()
    elif self._precompiling:
        (file_ext, output_flags) = self.__get_precompiled_header_flags()
    elif self._preprocessing:
        (file_ext, output_flags) = self.__get_preprocessor_output_flags()
    else:
        (file_ext, output_flags) = self.__get_python_module_flags()
    self._target_file = os.path.join(self._output_dir, f'{self._name}{file_ext}')
    relative_target_file = os.path.basename(self._target_file) if self._use_relative_path else self._target_file
    if <MASK>:
        if self._preprocessing:
            self._output = output_flags
        else:
            self._output = f'{output_flags}{relative_target_file}'
    else:
        self._output = f'{output_flags} {relative_target_file}'
    if isinstance(sources, str):
        sources = [sources]
    if config.is_fbcode() and self._use_relative_path:
        self._orig_source_paths = list(sources)
        sources = [os.path.basename(i) for i in sources]
    if self._precompiling:
        assert len(sources) == 1
        self._sources_args = f'-x c++-header {sources[0]}'
    else:
        self._sources_args = ' '.join(sources)
    for cflag in BuildOption.get_cflags():
        if _IS_WINDOWS:
            self._cflags_args += f'/{cflag} '
        else:
            self._cflags_args += f'-{cflag} '
    for definition in BuildOption.get_definitions():
        if _IS_WINDOWS:
            self._definitions_args += f'/D {definition} '
        else:
            self._definitions_args += f'-D {definition} '
    if (precompiled_header := BuildOption.precompiled_header):
        if _IS_WINDOWS:
            log.warning('Precompiled header support for MSVC is currently unavailable; ignoring %s', precompiled_header)
        else:
            self._include_dirs_args = f'-include {precompiled_header} '
    for inc_dir in BuildOption.get_include_dirs():
        if _IS_WINDOWS:
            self._include_dirs_args += f'/I "{inc_dir}" '
        else:
            self._include_dirs_args += f'-I{shlex.quote(inc_dir)} '
    for ldflag in BuildOption.get_ldflags():
        if _IS_WINDOWS:
            self._ldflags_args += f'/{ldflag} '
        else:
            self._ldflags_args += f'-{ldflag} '
    for lib_dir in BuildOption.get_libraries_dirs():
        if _IS_WINDOWS:
            self._libraries_dirs_args += f'/LIBPATH:"{lib_dir}" '
        else:
            self._libraries_dirs_args += f'-L{lib_dir} '
    for lib in BuildOption.get_libraries():
        if _IS_WINDOWS:
            self._libraries_args += f'"{lib}.lib" '
        else:
            self._libraries_args += f'-l{lib} '
    for passthrough_arg in BuildOption.get_passthrough_args():
        self._passthrough_parameters_args += f'{passthrough_arg} '

def _collapse_view_helper(a: TensorLikeType, start: int, end: int, must_be_valid: Optional[str]) -> tuple[Optional[ShapeType], Optional[StrideType]]:
    assert isinstance(a, TensorLike)
    from torch.fx.experimental.symbolic_shapes import guard_or_false, guard_or_true, sym_and, sym_or
    _validate_collapse_args(a, start, end)
    if a.ndim == 0:
        shape = (1,)
        strides = (1,)
    else:
        shape = a.shape
        strides = a.stride()
    if a.ndim == 0 or end == start:
        return (shape, strides)
    valid_op = True
    if guard_or_false(a.numel() != 0):
        for idx in range(end - 1, start - 1, -1):
            valid_op = sym_and(valid_op, sym_or(shape[idx] == 1, shape[idx + 1] == 1, strides[idx] == strides[idx + 1] * shape[idx + 1]))
            if guard_or_false(valid_op is False):
                break
    valid_op = sym_or(valid_op, a.numel() == 0)
    if must_be_valid:
        torch._check(valid_op, lambda : must_be_valid)
    elif not guard_or_false(valid_op):
        return (None, None)
    stride = strides[end]
    for idx in range(end - 1, start - 1, -1):
        if shape[idx] != 1:
            stride = min(stride, strides[idx])
    length = shape[end]
    if guard_or_true(length != 0):
        for idx in range(end - 1, start - 1, -1):
            if <MASK>:
                length = 0
                stride = 0
                break
            length = length * shape[idx]
    else:
        stride = 0
    new_shape = shape[:start] + (length,) + shape[end + 1:]
    new_strides = strides[:start] + (stride,) + strides[end + 1:]
    if guard_or_false(a.numel() == 0):
        new_strides = utils.make_contiguous_strides_for(new_shape)
    return (new_shape, new_strides)

def _annotate(self, args, kwargs, select=True):
    self._validate_values_are_expressions(args + tuple(kwargs.values()), method_name='annotate')
    annotations = {}
    for arg in args:
        try:
            if arg.default_alias in kwargs:
                raise ValueError("The named annotation '%s' conflicts with the default name for another annotation." % arg.default_alias)
        except (TypeError, AttributeError):
            raise TypeError('Complex annotations require an alias')
        annotations[arg.default_alias] = arg
    annotations.update(kwargs)
    clone = self._chain()
    names = self._fields
    if names is None:
        names = set(chain.from_iterable(((field.name, field.attname) if hasattr(field, 'attname') else (field.name,) for field in self.model._meta.get_fields())))
    for (alias, annotation) in annotations.items():
        if alias in names:
            raise ValueError("The annotation '%s' conflicts with a field on the model." % alias)
        if isinstance(annotation, FilteredRelation):
            clone.query.add_filtered_relation(annotation, alias)
        else:
            clone.query.add_annotation(annotation, alias, select=select)
    for (alias, annotation) in clone.query.annotations.items():
        if <MASK>:
            if clone._fields is None:
                clone.query.group_by = True
            else:
                clone.query.set_group_by()
            break
    return clone

def reinplace_fsdp_all_gather(graph: torch.fx.Graph) -> None:
    try:
        import torch.distributed.fsdp._fully_shard._fsdp_collectives
        assert torch.distributed.is_available()
        assert torch.ops._c10d_functional.all_gather_into_tensor and torch.ops._c10d_functional.all_gather_into_tensor_out
    except (ImportError, AttributeError, AssertionError):
        return
    from .pattern_matcher import CallFunction, KeywordArg, Match, PatternMatcherPass, register_graph_pattern
    '\n    all_gather_copy_in = torch.ops.fsdp.all_gather_copy_in.default(...);\n    getitem = all_gather_copy_in[0];\n    (getitem_1 = all_gather_copy_in[1];)  # optional\n\n    all_gather_into_tensor = torch.ops._c10d_functional.all_gather_into_tensor.default(getitem, ...);\n\n    ->\n\n    all_gather_copy_in = torch.ops.fsdp.all_gather_copy_in.default(...);\n    getitem = all_gather_copy_in[0];\n    getitem_1 = all_gather_copy_in[1];\n\n    all_gather_into_tensor = torch.ops._c10d_functional.all_gather_into_tensor_out.default(getitem, ..., out=getitem_1);\n    '

    def remove_unused_getitem(g):
        node_list = list(g.nodes)
        for n in node_list:
            if <MASK>:
                g.erase_node(n)
    graph_pass = PatternMatcherPass()

    @register_graph_pattern(CallFunction(torch.ops._c10d_functional.all_gather_into_tensor.default, CallFunction(operator.getitem, CallFunction(torch.ops.fsdp.all_gather_copy_in.default, KeywordArg('all_gather_inputs'), KeywordArg('all_gather_output'), KeywordArg('inp_split_sizes'), KeywordArg('all_gather_input_numel'), KeywordArg('rank')), KeywordArg('item_idx')), KeywordArg('group_size'), KeywordArg('group_name')), pass_dict=graph_pass, extra_check=lambda match: match.kwargs['item_idx'] == 0)
    def reinplace_all_gather(match: Match, *args, **kwargs):

        def repl(*args):
            copy_in_args = args[:-2]
            group_size = args[-2]
            group_name = args[-1]
            all_gather_copy_in = torch.ops.fsdp.all_gather_copy_in.default(*copy_in_args)
            getitem = all_gather_copy_in[0]
            getitem_1 = all_gather_copy_in[1]
            all_gather_into_tensor = torch.ops._c10d_functional.all_gather_into_tensor_out.default(getitem, group_size, group_name, out=getitem_1)
            return all_gather_into_tensor
        match.replace_by_example(repl, [kwargs['all_gather_inputs'], kwargs['all_gather_output'], kwargs['inp_split_sizes'], kwargs['all_gather_input_numel'], kwargs['rank'], kwargs['group_size'], kwargs['group_name']])
    remove_unused_getitem(graph)
    graph_pass.apply(graph)

def _get_max_seqlen(self):
    max_seqlen_tensor = self._max_seqlen_tensor
    if <MASK>:
        max_val = _get_sdpa_extreme_seqlen(torch.max, self._offsets.diff() if self._lengths is None else self._lengths)
        max_seqlen_tensor = _store_val_in_tensor(max_val)
