def get_loc(self, key):
    """
        Get integer location for requested label

        Returns
        -------
        loc : int
        """
    self._check_indexing_error(key)
    orig_key = key
    if is_valid_na_for_dtype(key, self.dtype):
        key = NaT
    if isinstance(key, self._data._recognized_scalars):
        self._disallow_mismatched_indexing(key)
        key = Timestamp(key)
    elif isinstance(key, str):
        try:
            (parsed, reso) = self._parse_with_reso(key)
        except ValueError as err:
            raise KeyError(key) from err
        self._disallow_mismatched_indexing(parsed)
        if self._can_partial_date_slice(reso):
            try:
                return self._partial_date_slice(reso, parsed)
            except KeyError as err:
                raise KeyError(key) from err
        key = parsed
    elif isinstance(key, dt.timedelta):
        raise TypeError(f'Cannot index {type(self).__name__} with {type(key).__name__}')
    elif <MASK>:
        return self.indexer_at_time(key)
    else:
        raise KeyError(key)
    try:
        return Index.get_loc(self, key)
    except KeyError as err:
        raise KeyError(orig_key) from err

def _record_and_ignore_transient_timeouts(self, e):
    """Records observed timeout error and return if it should be ignored."""
    if self._transient_timeouts_threshold <= 0:
        return False
    if not isinstance(e, errors.DeadlineExceededError):
        return False
    with self._transient_timeouts_lock:
        self._transient_timeouts_count += 1
        if <MASK>:
            return False
    return True

def _df(func):
    name = func.__name__
    if ismethod(func):
        dispatcher = inspect.currentframe().f_back.f_locals.get(name, MethodDispatcher(name))
    else:
        if <MASK>:
            namespace[name] = Dispatcher(name)
        dispatcher = namespace[name]
    dispatcher.add(types_tuple, func)
    return dispatcher

def _dimension(self, index):
    """Return a dimension, if the dimension is not ragged (see __getitem__)."""
    rank = self.rank
    if not isinstance(index, int):
        raise TypeError('index should be an int')
    if self.num_row_partitions == 0 or index > self.num_row_partitions + 1:
        if rank is None:
            raise ValueError('Rank must be known to use __getitem__ on a large index.')
        if index >= rank:
            raise IndexError('Index is too big: ' + str(index) + '>=' + str(rank))
    if index < 0:
        raise IndexError('Index must be non-negative: ' + str(index))
    elif not self.is_uniform(index):
        raise ValueError('Index ' + str(index) + ' is not uniform')
    elif index == 0 and self.num_row_partitions > 0:
        static_nrows = self.row_partitions[0].static_nrows
        if static_nrows is not None:
            return constant_op.constant(static_nrows, dtype=self.dtype)
        return self.row_partitions[0].nrows()
    elif self.num_row_partitions == 0:
        static_result = tensor_shape.dimension_value(self._static_inner_shape[index])
        if <MASK>:
            return constant_op.constant(static_result, dtype=self.dtype)
        return self.inner_shape[index]
    elif index > self.num_row_partitions:
        static_result = tensor_shape.dimension_value(self._static_inner_shape[index - self.num_row_partitions])
        if static_result is not None:
            return constant_op.constant(static_result, dtype=self.dtype)
        return self.inner_shape[index - self.num_row_partitions]
    else:
        return self.row_partitions[index - 1].uniform_row_length()

@compatibility(is_backward_compatible=False)
def check_for_mutable_operation(target: Callable, args: tuple['Argument', ...], kwargs: dict[str, 'Argument']):
    (signatures, schemas) = get_signature_for_torch_op(target, return_schemas=True)
    if signatures and schemas:
        matched_schemas = []
        for (candidate_signature, schema) in zip(signatures, schemas):
            try:
                candidate_signature.bind(*args, **kwargs)
                matched_schemas.append((candidate_signature, schema))
            except TypeError:
                continue

        def throw_if_mutable(schema):
            if schema.is_mutable:
                raise RuntimeError(f'Tried to trace mutable operation {schema}. FX only supports functional code, so operations that mutate operands in-place (e.g. via `out` arguments) are not supported')
        if <MASK>:
            pass
        elif len(matched_schemas) == 1:
            (_, schema_to_check) = matched_schemas[0]
            throw_if_mutable(schema_to_check)
        else:
            pass

def take_2d_multi(arr: np.ndarray, indexer: tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]], fill_value=np.nan) -> np.ndarray:
    """
    Specialized Cython take which sets NaN values in one pass.
    """
    assert indexer is not None
    assert indexer[0] is not None
    assert indexer[1] is not None
    (row_idx, col_idx) = indexer
    row_idx = ensure_platform_int(row_idx)
    col_idx = ensure_platform_int(col_idx)
    indexer = (row_idx, col_idx)
    mask_info = None
    (dtype, fill_value) = maybe_promote(arr.dtype, fill_value)
    if <MASK>:
        row_mask = row_idx == -1
        col_mask = col_idx == -1
        row_needs = row_mask.any()
        col_needs = col_mask.any()
        mask_info = ((row_mask, col_mask), (row_needs, col_needs))
        if not (row_needs or col_needs):
            (dtype, fill_value) = (arr.dtype, arr.dtype.type())
    out_shape = (len(row_idx), len(col_idx))
    out = np.empty(out_shape, dtype=dtype)
    func = _take_2d_multi_dict.get((arr.dtype.name, out.dtype.name), None)
    if func is None and arr.dtype != out.dtype:
        func = _take_2d_multi_dict.get((out.dtype.name, out.dtype.name), None)
        if func is not None:
            func = _convert_wrapper(func, out.dtype)
    if func is not None:
        func(arr, indexer, out=out, fill_value=fill_value)
    else:
        _take_2d_multi_object(arr, indexer, out, fill_value=fill_value, mask_info=mask_info)
    return out

@staticmethod
def check_inlineable(func: Any) -> trace_rules.SkipResult:
    if func.has_self():
        unimplemented_v2(gb_type='Inline attempt with __self__', context=str(func), explanation='Attempted to inline a function with the `__self__` attribute. Dynamo is expected to decompose method calls into function calls with a `self` argument.', hints=[])
    if isinstance(func, UserFunctionVariable) and inspect.getattr_static(func.get_function(), '_torchdynamo_disable', False):
        msg = inspect.getattr_static(func.get_function(), '_torchdynamo_disable_msg', None)
        unimplemented_v2(gb_type='Skip inlining `torch.compiler.disable()`d function', context=str(func.get_function()), explanation=f'Skip inlining function {func.get_function()} since it was wrapped with `torch.compiler.disable` (reason: {msg})', hints=['Remove the `torch.compiler.disable` call'])
    result = trace_rules.check_verbose(func, is_inlined_call=True)
    if result.skipped:
        from torch._dynamo.variables.misc import produce_trampoline_autograd_apply
        if <MASK>:
            return trace_rules.SkipResult(False, 'allowlist in dynamo known function')
        fn_qualname = func.fn.__qualname__ if hasattr(func, 'fn') else ''
        hints = [f'Avoid calling the function `{fn_qualname}`.']
        if '_dynamo' not in func.get_filename():
            hints += [f'Apply `@torch._dynamo.dont_skip_tracing` to the function `{fn_qualname}` to force tracing into the function. More graph breaks may occur as a result of attempting to trace into the function.', 'Please file an issue to PyTorch.']
        unimplemented_v2(gb_type='Attempted to inline function marked as skipped', context=f'qualname: {fn_qualname}, name: {func.get_name()}, filename: `{func.get_filename()}`, skip reason: {result.reason}', explanation=f'Dynamo developers have intentionally marked that the function `{fn_qualname}` should not be traced.', hints=hints)
    return result

def setitem(self: Any, index: Any, rhs: Any) -> None:
    """Set values in tensor using first-class dimensions."""
    from . import DimensionBindError, TensorInfo
    iinfo = getsetitem(self, index, has_dims(self) or has_dims(rhs))
    if iinfo.can_call_original:
        torch._C.TensorBase.__setitem__(self, index, rhs)
        return
    rhs_info = TensorInfo.create(rhs, False, False)
    if rhs_info:
        for l in rhs_info.levels:
            if not l.is_positional():
                found = False
                for result_level in iinfo.result_levels:
                    if <MASK>:
                        found = True
                        break
                if not found:
                    result_dims: list[Union[int, Dim]] = []
                    for rl in iinfo.result_levels:
                        if rl.is_positional():
                            result_dims.append(rl.position())
                        else:
                            result_dims.append(rl.dim())
                    raise DimensionBindError(f'rhs of setitem contains dimension {l.dim()!r} which is not in the dimension on the left ({tuple(result_dims)!r})')
        assert rhs_info.tensor is not None, 'Cannot match levels on None tensor'
        matched_rhs = _match_levels(rhs_info.tensor, rhs_info.levels, iinfo.result_levels)
    else:
        matched_rhs = rhs
    if iinfo.advanced_indexing:
        tup = slice_to_tuple(iinfo.flat_inputs)
        if iinfo.self_tensor is None:
            raise RuntimeError('Cannot setitem on None tensor')
        torch._C.TensorBase.__setitem__(iinfo.self_tensor, tup, matched_rhs)
    else:
        if iinfo.self_tensor is None:
            raise RuntimeError('Cannot copy to None tensor')
        iinfo.self_tensor.copy_(matched_rhs)

def _lookup_inner(obj: Any, name: Optional[str]=None, filename: Optional[str]=None, is_direct_call: bool=True, reasons: Optional[set[str]]=None) -> Optional[type[VariableTracker]]:
    try:
        can_hash = hashable(obj)
    except Exception:
        can_hash = False
    if not can_hash:
        if <MASK>:
            reasons.add('obj is not hashable')
        return None
    if obj is not None:
        if is_aten_op_or_tensor_method(obj):
            return TorchInGraphFunctionVariable
        rule = get_torch_obj_rule_map().get(obj, None)
        if rule is not None:
            if reasons is not None:
                reasons.add('get_torch_obj_rule_map')
            return rule
    elif name is not None and filename is not None and (not is_direct_call):
        if name.startswith(TORCH_DYNAMO_RESUME_IN_PREFIX):
            rule = get_torch_obj_rule_map().get(filename + '#' + TORCH_DYNAMO_RESUME_IN_PREFIX, None)
        else:
            rule = get_torch_obj_rule_map().get(filename + '#' + name, None)
        if rule is not None:
            if reasons is not None:
                reasons.add('get_torch_obj_rule_map')
            return rule
    elif name == '<listcomp>':
        if reasons is not None:
            reasons.add('inlining frame from list comprehension')
        return UserFunctionVariable
    if is_direct_call:
        if name == 'patched_init':
            if reasons is not None:
                reasons.add('func name is patched_init')
            return SkipFunctionVariable
        elif name == '__torch_function__' or (obj and getattr(obj, '__name__', None) == '__torch_function__'):
            if reasons is not None:
                reasons.add('func name is __torch_function__')
            return UserFunctionVariable
    if not is_direct_call:
        if name == '__getattr__':
            if reasons is not None:
                reasons.add('Tracing __getattr__ as the top level frame, unsuitable for tracing.')
            return SkipFunctionVariable
    if filename is None:
        filename = getfile(obj)
    skip_result = check_file(filename, is_direct_call)
    if reasons is not None and skip_result.reason is not None:
        reasons.add(skip_result.reason)
    if skip_result.skipped:
        return SkipFunctionVariable
    else:
        return UserFunctionVariable

def _populate(self):
    if getattr(self._local, 'populating', False):
        return
    try:
        self._local.populating = True
        lookups = MultiValueDict()
        namespaces = {}
        apps = {}
        language_code = get_language()
        for url_pattern in reversed(self.url_patterns):
            p_pattern = url_pattern.pattern.regex.pattern
            p_pattern = p_pattern.removeprefix('^')
            if isinstance(url_pattern, URLPattern):
                self._callback_strs.add(url_pattern.lookup_str)
                bits = normalize(url_pattern.pattern.regex.pattern)
                lookups.appendlist(url_pattern.callback, (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters))
                if url_pattern.name is not None:
                    lookups.appendlist(url_pattern.name, (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters))
            else:
                url_pattern._populate()
                if <MASK>:
                    apps.setdefault(url_pattern.app_name, []).append(url_pattern.namespace)
                    namespaces[url_pattern.namespace] = (p_pattern, url_pattern)
                else:
                    for name in url_pattern.reverse_dict:
                        for (matches, pat, defaults, converters) in url_pattern.reverse_dict.getlist(name):
                            new_matches = normalize(p_pattern + pat)
                            lookups.appendlist(name, (new_matches, p_pattern + pat, {**defaults, **url_pattern.default_kwargs}, {**self.pattern.converters, **url_pattern.pattern.converters, **converters}))
                    for (namespace, (prefix, sub_pattern)) in url_pattern.namespace_dict.items():
                        current_converters = url_pattern.pattern.converters
                        sub_pattern.pattern.converters.update(current_converters)
                        namespaces[namespace] = (p_pattern + prefix, sub_pattern)
                    for (app_name, namespace_list) in url_pattern.app_dict.items():
                        apps.setdefault(app_name, []).extend(namespace_list)
                self._callback_strs.update(url_pattern._callback_strs)
        self._namespace_dict[language_code] = namespaces
        self._app_dict[language_code] = apps
        self._reverse_dict[language_code] = lookups
        self._populated = True
    finally:
        self._local.populating = False

def call_blocking_wrapper(*args, timeout_in_ms=0):
    (status_or, deleter) = gen_rpc_ops.rpc_call(client_handle, args=validate_and_get_flat_inputs(*args), method_name=method_name, timeout_in_ms=timeout_in_ms)
    status_or = StatusOrResult(status_or, deleter, output_specs)
    if <MASK>:
        return status_or.get_value()
    else:
        (error_code, error_msg) = status_or.get_error()
        raise errors.exception_type_from_error_code(error_code.numpy())(None, None, error_msg.numpy())

def forward(self, x: Tensor, hidden: Optional[tuple[Tensor, Tensor]]=None):
    if self.batch_first:
        x = x.transpose(0, 1)
    max_batch_size = x.size(1)
    num_directions = 2 if self.bidirectional else 1
    if hidden is None:
        zeros = torch.zeros(num_directions, max_batch_size, self.hidden_size, dtype=torch.float, device=x.device)
        zeros.squeeze_(0)
        if <MASK>:
            zeros = torch.quantize_per_tensor(zeros, scale=1.0, zero_point=0, dtype=x.dtype)
        hxcx = [(zeros, zeros) for _ in range(self.num_layers)]
    else:
        hidden_non_opt = torch.jit._unwrap_optional(hidden)
        if isinstance(hidden_non_opt[0], Tensor):
            hx = hidden_non_opt[0].reshape(self.num_layers, num_directions, max_batch_size, self.hidden_size)
            cx = hidden_non_opt[1].reshape(self.num_layers, num_directions, max_batch_size, self.hidden_size)
            hxcx = [(hx[idx].squeeze(0), cx[idx].squeeze(0)) for idx in range(self.num_layers)]
        else:
            hxcx = hidden_non_opt
    hx_list = []
    cx_list = []
    for (idx, layer) in enumerate(self.layers):
        (x, (h, c)) = layer(x, hxcx[idx])
        hx_list.append(torch.jit._unwrap_optional(h))
        cx_list.append(torch.jit._unwrap_optional(c))
    hx_tensor = torch.stack(hx_list)
    cx_tensor = torch.stack(cx_list)
    hx_tensor = hx_tensor.reshape(-1, hx_tensor.shape[-2], hx_tensor.shape[-1])
    cx_tensor = cx_tensor.reshape(-1, cx_tensor.shape[-2], cx_tensor.shape[-1])
    if self.batch_first:
        x = x.transpose(0, 1)
    return (x, (hx_tensor, cx_tensor))

def keras_layer_tracepoint(layer, checkpoint_name):
    """An interface for adding the tensor outputs of a keras layer.

  Encapsulates trace_tensor.

  Args:
     layer: A keras layer.
     checkpoint_name: a string name for the checkpoint. This name has to be a
     unique name if used within model comparison. The tensors that have the same
     checkpoint identifier is compared in model comparison.

  Returns:
    The provided layer.
  """
    try:
        outputs = layer.output
        if <MASK>:
            trace_tensor(outputs, '%s' % checkpoint_name)
        else:
            idx = 0
            for output_tensor in outputs:
                if tensor_util.is_tf_type(outputs):
                    trace_tensor(output_tensor, '%s_%d' % (checkpoint_name, idx))
                idx += 1
    except AttributeError:
        pass
    except RuntimeError:
        pass
    return layer

def parse_env(self, name, default, true_message, false_message):
    value = os.environ.get(name)
    if <MASK>:
        return default
    if value.lower() in {'1', 'true', 'yes'}:
        return True
    elif value.lower() in {'0', 'false', 'no'}:
        return False
    if value == '1v':
        print(true_message)
        return True
    elif value == '0v':
        print(false_message)
        return False
    raise ValueError(f'Unknown setting of {name}. Try using 0 or 1.')

def reduction_combine_vec(self, reduction_type, var, next_value, helper_val=None, index: Optional[sympy.Symbol]=None, horizontal_reduction: Optional[bool]=None, src_dtype: Optional[torch.dtype]=torch.float32):
    is_bool = src_dtype == torch.bool
    if reduction_type == 'max':
        if <MASK>:
            return f'max_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} | {next_value}' if is_bool else f'at::vec::maximum({var}, {next_value})'
    elif reduction_type == 'min':
        if self.tail_size:
            return f'min_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} & {next_value}' if is_bool else f'at::vec::minimum({var}, {next_value})'
    elif reduction_type == 'sum':
        if helper_val:
            if self.tail_size:
                return f'cascade_sum_combine({next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'cascade_sum_combine({next_value}, &{helper_val})'
        elif self.tail_size:
            return f'sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            conjunction = '|' if is_bool else '+'
            return f'{var} {conjunction} {next_value}'
    elif reduction_type == 'prod':
        if self.tail_size:
            return f'prod_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} * {next_value}'
    elif reduction_type == 'xor_sum':
        if self.tail_size:
            return f'xor_sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} ^ {next_value}'
    elif reduction_type == 'welford_reduce':
        if helper_val:
            if self.tail_size:
                return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'welford_combine({var}, {next_value}, &{helper_val})'
        elif self.tail_size:
            return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {next_value})'
    elif reduction_type == 'welford_combine':
        if isinstance(next_value, tuple):
            (mean, m2, weight) = next_value
        else:
            (mean, m2, weight) = reduction_project(reduction_type, next_value)
        if self.tail_size:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}})'
    elif reduction_type in ('argmin', 'argmax'):
        assert src_dtype is not None
        cdtype = DTYPE_TO_CPP[src_dtype]
        if src_dtype == torch.bool:
            cdtype = DTYPE_TO_CPP[torch.float]
        n_src = self._get_num_vectors(src_dtype)
        n_idx = self._get_num_vectors(torch.int64)
        t_extra = ''
        arg_extra = ''
        if index is not None:
            assert horizontal_reduction is not None
            t_extra = f', {str(horizontal_reduction).lower()}'
            arg_extra = f', {index}'
        if self.tail_size:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra}, {cexpr_index(self.tail_size)})'
        else:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra})'
    elif reduction_type == 'any':
        if isinstance(next_value, CppCSEVariable):
            assert next_value.dtype == torch.bool
            (next_value,) = unify_mask_base_type(V.kernel.compute, (next_value,))
        return f'{var} | {next_value}'
    else:
        raise NotImplementedError

def tag_to_layout_constraint(tag):
    if tag == torch._C.Tag.needs_exact_strides:
        return constrain_to_fake_tensors
    if tag == torch._C.Tag.needs_contiguous_strides:
        return require_contiguous_strides
    if <MASK>:
        return constrain_to_fx_strides
    if tag == torch._C.Tag.flexible_layout:
        return None
    raise AssertionError(f'Unknown layout constraint tag: {tag}')

def _union(self, other, sort) -> MultiIndex:
    (other, result_names) = self._convert_can_do_setop(other)
    if other.has_duplicates:
        result = super(MultiIndex, self.rename(result_names))._union(other.rename(result_names), sort)
        if isinstance(result, MultiIndex):
            return result
        return MultiIndex.from_arrays(zip(*result, strict=True), sortorder=None, names=result_names)
    else:
        right_missing = other.difference(self, sort=False)
        if <MASK>:
            result = self.append(right_missing)
        else:
            result = self._get_reconciled_name_object(other)
        if sort is not False:
            try:
                result = result.sort_values()
            except TypeError:
                if sort is True:
                    raise
                warnings.warn('The values in the array are unorderable. Pass `sort=False` to suppress this warning.', RuntimeWarning, stacklevel=find_stack_level())
        return result

@final
def _cast_types(self, values: ArrayLike, cast_type: DtypeObj, column) -> ArrayLike:
    """
        Cast values to specified type

        Parameters
        ----------
        values : ndarray or ExtensionArray
        cast_type : np.dtype or ExtensionDtype
           dtype to cast values to
        column : string
            column name - used only for error reporting

        Returns
        -------
        converted : ndarray or ExtensionArray
        """
    if <MASK>:
        known_cats = cast_type.categories is not None
        if not is_object_dtype(values.dtype) and (not known_cats):
            values = lib.ensure_string_array(values, skipna=False, convert_na_value=False)
        cats = Index(values).unique().dropna()
        values = Categorical._from_inferred_categories(cats, cats.get_indexer(values), cast_type, true_values=self.true_values)
    elif isinstance(cast_type, ExtensionDtype):
        array_type = cast_type.construct_array_type()
        try:
            if isinstance(cast_type, BooleanDtype):
                values_str = [str(val) for val in values]
                return array_type._from_sequence_of_strings(values_str, dtype=cast_type, true_values=self.true_values, false_values=self.false_values, none_values=self.na_values)
            else:
                return array_type._from_sequence_of_strings(values, dtype=cast_type)
        except NotImplementedError as err:
            raise NotImplementedError(f'Extension Array: {array_type} must implement _from_sequence_of_strings in order to be used in parser methods') from err
    elif isinstance(values, ExtensionArray):
        values = values.astype(cast_type, copy=False)
    elif issubclass(cast_type.type, str):
        values = lib.ensure_string_array(values, skipna=True, convert_na_value=False)
    else:
        try:
            values = astype_array(values, cast_type, copy=True)
        except ValueError as err:
            raise ValueError(f'Unable to convert column {column} to type {cast_type}') from err
    return values

def _link_wrapper_lib(self, objects, output_dir, extra_dll_dir, chained_dlls, is_archive):
    """Create a wrapper shared library for the given objects

        Return an MSVC-compatible lib
        """
    c_compiler = self.c_compiler
    if c_compiler.compiler_type != 'msvc':
        raise ValueError('This method only supports MSVC')
    object_hash = self._hash_files(list(objects) + list(chained_dlls))
    if is_win64():
        tag = 'win_amd64'
    else:
        tag = 'win32'
    basename = 'lib' + os.path.splitext(os.path.basename(objects[0]))[0][:8]
    root_name = basename + '.' + object_hash + '.gfortran-' + tag
    dll_name = root_name + '.dll'
    def_name = root_name + '.def'
    lib_name = root_name + '.lib'
    dll_path = os.path.join(extra_dll_dir, dll_name)
    def_path = os.path.join(output_dir, def_name)
    lib_path = os.path.join(output_dir, lib_name)
    if os.path.isfile(lib_path):
        return (lib_path, dll_path)
    if <MASK>:
        objects = ['-Wl,--whole-archive'] + list(objects) + ['-Wl,--no-whole-archive']
    self.link_shared_object(objects, dll_name, output_dir=extra_dll_dir, extra_postargs=list(chained_dlls) + ['-Wl,--allow-multiple-definition', '-Wl,--output-def,' + def_path, '-Wl,--export-all-symbols', '-Wl,--enable-auto-import', '-static', '-mlong-double-64'])
    if is_win64():
        specifier = '/MACHINE:X64'
    else:
        specifier = '/MACHINE:X86'
    lib_args = ['/def:' + def_path, '/OUT:' + lib_path, specifier]
    if not c_compiler.initialized:
        c_compiler.initialize()
    c_compiler.spawn([c_compiler.lib] + lib_args)
    return (lib_path, dll_path)

def _create_variables(self, stacked_tables: List[tpu_embedding_v2_utils.TableConfig], stacked_table_name: str, initialized_tensors: dict[str, dict[str, List[tensor.Tensor]]]) -> Dict[str, tf_variables.Variable]:
    """Create all variables including table variables and slot variables."""
    total_vocab_size = sum([table.vocabulary_size for table in stacked_tables])
    table_dim = stacked_tables[0].dim
    variable_shape = (total_vocab_size, table_dim)
    variable_dtype = dtypes.float32
    optimizer = stacked_tables[0].optimizer

    def table_initialize_fn_non_batch(shape, dtype, shard_info=None):
        if self._sparse_core_embedding_config.enable_fast_table_initialization:
            return stacked_tables[0].initializer(shape=(shard_info.shape[0], stacked_tables[0].dim), dtype=dtype)
        concat_tensors = []
        for i in range(self._num_sc_per_chip):
            for table in stacked_tables:
                arg_spec = tf_inspect.getfullargspec(table.initializer)
                sharding_aware = 'shard_info' in arg_spec.args or 'shard_info' in arg_spec.kwonlyargs
                if shard_info:
                    sc_shard_info = self._compute_sc_shard_info(table, shard_info.shape, shard_info.offset, total_vocab_size, i)
                    if not sharding_aware:
                        (shard_index, shard_offset) = self._compute_sc_shard_idx_and_offset(table.name, sc_shard_info)
                        sc_shard = table.initializer(shape=(table.vocabulary_size, table.dim), dtype=dtype)[shard_index::shard_offset, :]
                    else:
                        sc_shard = table.initializer(shape=(table.vocabulary_size, table.dim), dtype=dtype, shard_info=sc_shard_info)
                else:
                    sc_shard = table.initializer(shape=(table.vocabulary_size * shape[0] // total_vocab_size // self._num_sc_per_chip, table.dim), dtype=dtype)
                concat_tensors.append(sc_shard)
        return array_ops.concat(concat_tensors, axis=0)

    def batch_initialize_fn(name, shard_info, replicated=False):
        if not initialized_tensors:
            initialized_tensors.update(self._batch_initialize_tables())
        if not replicated:
            shard_id = shard_info.offset[0] // shard_info.shape[0]
        else:
            shard_id = shard_info.offset[0]
        res = initialized_tensors[stacked_table_name][name][shard_id]
        assert shard_info.shape == res.shape
        return res

    def table_initialize_fn(shape, dtype, shard_info=None):
        if not shard_info or not self._initializers_shard_info_by_default:
            return table_initialize_fn_non_batch(shape, dtype, shard_info)
        return batch_initialize_fn(_PARAMETER_NAME, shard_info)

    def slot_initialize_fn(name, shape, dtype, initializer, shard_info=None, replicated=False):
        if not shard_info or not self._initializers_shard_info_by_default:
            return initializer(shape, dtype)
        return batch_initialize_fn(name, shard_info, replicated)

    def getter(name, shape, dtype, initializer, trainable):
        initial_value = functools.partial(initializer, shape=shape, dtype=dtype)
        return tf_variables.Variable(name=name, initial_value=initial_value, shape=shape, dtype=dtype, trainable=trainable)

    def variable_creator(name, initializer, shape, dtype):
        return self._add_variable_with_custom_getter(name=name, initializer=initializer, shape=shape, dtype=dtype, getter=getter, trainable=False)
    with variable_scope.variable_creator_scope(self._variable_creator):
        parameters = variable_creator(stacked_table_name, table_initialize_fn, variable_shape, variable_dtype)

    def slot_creator(name, initializer, shape, dtype):
        return variable_creator(stacked_table_name + '/' + name, initializer, shape, dtype)
    slot_vars = {}
    if <MASK>:
        with variable_scope.variable_creator_scope(self._variable_creator):
            slot_vars = optimizer._create_slots(parameters, variable_creator=functools.partial(slot_creator, shape=variable_shape, dtype=variable_dtype), initializer_wrapper=lambda slot, initializer: functools.partial(slot_initialize_fn, name=slot, initializer=initializer, replicated=False))
    slot_vars[_PARAMETER_NAME] = parameters
    return slot_vars

def get_linear_fun_weight(node: Node, gm: GraphModule) -> torch.Tensor:
    linear_second_arg = node.args[1]
    if not isinstance(linear_second_arg, Node):
        raise AssertionError(f'Expected Node, got {type(linear_second_arg)}')
    if linear_second_arg.op == 'call_module':
        weight_arg_node = node.args[1]
        if not isinstance(weight_arg_node, Node):
            raise AssertionError(f'Expected Node, got {type(weight_arg_node)}')
        weight_node = weight_arg_node.args[0]
        if <MASK>:
            raise AssertionError(f'Expected Node, got {type(weight_node)}')
        if weight_node.op != 'get_attr':
            raise AssertionError(f'Expected get_attr, got {weight_node.op}')
        weight = getattr_from_fqn(gm, weight_node.target)
        return weight.detach()
    elif linear_second_arg.op == 'call_method':
        if linear_second_arg.op != 'call_method':
            raise AssertionError(f'Expected call_method, got {linear_second_arg.op}')
        dequant_node = node.args[1]
        if not isinstance(dequant_node, Node):
            raise AssertionError(f'Expected Node, got {type(dequant_node)}')
        to_fp16_node = dequant_node.args[0]
        if not isinstance(to_fp16_node, Node):
            raise AssertionError(f'Expected Node, got {type(to_fp16_node)}')
        target_dtype = to_fp16_node.args[1]
        weight_node = to_fp16_node.args[0]
        if not isinstance(weight_node, Node):
            raise AssertionError(f'Expected Node, got {type(weight_node)}')
        if weight_node.op != 'get_attr':
            raise AssertionError(f'Expected get_attr, got {weight_node.op}')
        weight = getattr_from_fqn(gm, weight_node.target)
        return weight.detach().to(target_dtype)
    else:
        if linear_second_arg.op != 'get_attr':
            raise AssertionError(f'Expected get_attr, got {linear_second_arg.op}')
        weight = getattr_from_fqn(gm, linear_second_arg.target)
        return weight.detach()

def _parse_latex_css_conversion(styles: CSSList) -> CSSList:
    """
    Convert CSS (attribute,value) pairs to equivalent LaTeX (command,options) pairs.

    Ignore conversion if tagged with `--latex` option, skipped if no conversion found.
    """

    def font_weight(value, arg) -> tuple[str, str] | None:
        if value in ('bold', 'bolder'):
            return ('bfseries', f'{arg}')
        return None

    def font_style(value, arg) -> tuple[str, str] | None:
        if value == 'italic':
            return ('itshape', f'{arg}')
        if <MASK>:
            return ('slshape', f'{arg}')
        return None

    def color(value, user_arg, command, comm_arg):
        """
        CSS colors have 5 formats to process:

         - 6 digit hex code: "#ff23ee"     --> [HTML]{FF23EE}
         - 3 digit hex code: "#f0e"        --> [HTML]{FF00EE}
         - rgba: rgba(128, 255, 0, 0.5)    --> [rgb]{0.502, 1.000, 0.000}
         - rgb: rgb(128, 255, 0,)          --> [rbg]{0.502, 1.000, 0.000}
         - string: red                     --> {red}

        Additionally rgb or rgba can be expressed in % which is also parsed.
        """
        arg = user_arg if user_arg != '' else comm_arg
        if value[0] == '#' and len(value) == 7:
            return (command, f'[HTML]{{{value[1:].upper()}}}{arg}')
        if value[0] == '#' and len(value) == 4:
            val = f'{value[1].upper() * 2}{value[2].upper() * 2}{value[3].upper() * 2}'
            return (command, f'[HTML]{{{val}}}{arg}')
        elif value[:3] == 'rgb':
            r = re.findall('(?<=\\()[0-9\\s%]+(?=,)', value)[0].strip()
            r = float(r[:-1]) / 100 if '%' in r else int(r) / 255
            g = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[0].strip()
            g = float(g[:-1]) / 100 if '%' in g else int(g) / 255
            if value[3] == 'a':
                b = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[1].strip()
            else:
                b = re.findall('(?<=,)[0-9\\s%]+(?=\\))', value)[0].strip()
            b = float(b[:-1]) / 100 if '%' in b else int(b) / 255
            return (command, f'[rgb]{{{r:.3f}, {g:.3f}, {b:.3f}}}{arg}')
        else:
            return (command, f'{{{value}}}{arg}')
    CONVERTED_ATTRIBUTES: dict[str, Callable] = {'font-weight': font_weight, 'background-color': partial(color, command='cellcolor', comm_arg='--lwrap'), 'color': partial(color, command='color', comm_arg=''), 'font-style': font_style}
    latex_styles: CSSList = []
    for (attribute, value) in styles:
        if isinstance(value, str) and '--latex' in value:
            latex_styles.append((attribute, value.replace('--latex', '')))
        if attribute in CONVERTED_ATTRIBUTES:
            arg = ''
            for x in ['--wrap', '--nowrap', '--lwrap', '--dwrap', '--rwrap']:
                if x in str(value):
                    (arg, value) = (x, _parse_latex_options_strip(value, x))
                    break
            latex_style = CONVERTED_ATTRIBUTES[attribute](value, arg)
            if latex_style is not None:
                latex_styles.extend([latex_style])
    return latex_styles

def MATCH_KEYS(self, inst: Instruction) -> None:
    tos = self.stack[-1]
    assert isinstance(tos, TupleVariable)
    keys = tos.unpack_var_sequence(self)
    tos1 = self.stack[-2]
    assert isinstance(tos1, ConstDictVariable)
    if all((k in tos1 for k in keys)):
        self.push(TupleVariable([tos1.getitem_const(self, k) for k in keys]))
        if <MASK>:
            self.push(ConstantVariable.create(True))
    else:
        self.push(ConstantVariable.create(None))
        if sys.version_info < (3, 11):
            self.push(ConstantVariable.create(False))

def _call_iter_tuple_list(self, tx: 'InstructionTranslator', obj=None, *args, **kwargs):
    assert not isinstance(obj, variables.IteratorVariable)
    if self._dynamic_args(*args, **kwargs):
        return self._dyn_proxy(tx, *args, **kwargs)
    cls = variables.BaseListVariable.cls_for(self.fn)
    if obj is None:
        return cls([], mutation_type=ValueMutationNew())
    elif obj.has_unpack_var_sequence(tx):
        if obj.source and (not is_constant_source(obj.source)):
            if <MASK>:
                install_guard(obj.source.make_guard(GuardBuilder.TUPLE_ITERATOR_LEN))
            else:
                if getattr(obj, 'source', False) and isinstance(obj, ConstDictVariable) and (not istype(obj, (SetVariable, FrozensetVariable))):
                    tx.output.guard_on_key_order.add(obj.source)
                if isinstance(obj, variables.MappingProxyVariable):
                    install_guard(obj.source.make_guard(GuardBuilder.MAPPING_KEYS_CHECK))
                elif not isinstance(obj, variables.UnspecializedNNModuleVariable):
                    install_guard(obj.source.make_guard(GuardBuilder.SEQUENCE_LENGTH))
        return cls(list(obj.unpack_var_sequence(tx)), mutation_type=ValueMutationNew())

def _pfor_impl(loop_fn, iters, fallback_to_while_loop, parallel_iterations=None, pfor_config=None, warn=False):
    """Implementation of pfor."""
    assert not context.executing_eagerly()
    loop_fn_has_config = _loop_fn_has_config(loop_fn)
    existing_ops = set(ops.get_default_graph().get_operations())
    iters_value = tensor_util.constant_value(iters)
    with ops.name_scope('loop_body'):
        loop_var = array_ops.placeholder_with_default(0, shape=[])
        if loop_fn_has_config:
            if pfor_config is None:
                pfor_config = PForConfig()
                pfor_config._set_iters(iters)
            loop_fn_outputs = loop_fn(loop_var, **{PFOR_CONFIG_ARG: pfor_config})
        else:
            assert pfor_config is None
            f = autograph.tf_convert(loop_fn, autograph_ctx.control_status_ctx())
            loop_fn_outputs = f(loop_var)
        loop_fn_output_tensors = nest.map_structure(_composite_to_tensors, loop_fn_outputs)
    tmp_loop_fn_outputs = []
    for loop_fn_output in nest.flatten(loop_fn_output_tensors):
        if loop_fn_output is not None and (not isinstance(loop_fn_output, (ops.Operation, tensor.Tensor, sparse_tensor.SparseTensor))):
            if isinstance(loop_fn_output, indexed_slices.IndexedSlices):
                logging.warn('Converting %s to a dense representation may make it slow. Alternatively, output the indices and values of the IndexedSlices separately, and handle the vectorized outputs directly.' % loop_fn_output)
                loop_fn_output = ops.convert_to_tensor(loop_fn_output)
            else:
                loop_fn_output = ops.convert_to_tensor(loop_fn_output)
        tmp_loop_fn_outputs.append(loop_fn_output)
    loop_fn_output_tensors = nest.pack_sequence_as(loop_fn_output_tensors, tmp_loop_fn_outputs)
    new_ops = set(ops.get_default_graph().get_operations()) - existing_ops
    iters = ops.convert_to_tensor(iters)
    if parallel_iterations is not None:
        if <MASK>:
            raise ValueError(f'Argument `parallel_iterations` must be None or a positive integer. Received: {parallel_iterations}.')
        if parallel_iterations == 1:
            raise ValueError('Found `parallel_iterations == 1`. Use `for_loop` instead.')
        if iters_value is not None and iters_value < parallel_iterations:
            parallel_iterations = None
    if parallel_iterations is None:
        with ops.name_scope('pfor'):
            converter = PFor(loop_var, iters, new_ops, fallback_to_while_loop=fallback_to_while_loop, pfor_config=pfor_config, warn=warn)
            flattened_output_tensors = []
            for loop_fn_output in nest.flatten(loop_fn_output_tensors):
                output = converter.convert(loop_fn_output)
                flattened_output_tensors.append(output)
    else:
        if pfor_config is not None and pfor_config._has_reductions():
            raise ValueError('Setting `parallel_iterations` currently unsupported if reductions across iterations are performed.')
        num_tiled_iterations = iters // parallel_iterations
        num_remaining_iterations = iters % parallel_iterations
        with ops.name_scope('pfor_untiled'):
            converter = PFor(loop_var, num_remaining_iterations, new_ops, fallback_to_while_loop=fallback_to_while_loop, pfor_config=pfor_config)
            remaining_output_tensors = []
            flattened_output_tensors = nest.flatten(loop_fn_output_tensors)
            for loop_fn_output in flattened_output_tensors:
                output = converter.convert(loop_fn_output)
                remaining_output_tensors.append(output)
        with ops.name_scope('pfor_tiled'):
            loop_fn_dtypes = [ops.convert_to_tensor(x).dtype for x in flattened_output_tensors]

            def tiled_loop_body(j):
                offset = j * parallel_iterations + num_remaining_iterations

                def tiled_loop_fn(i, pfor_config=None):
                    if loop_fn_has_config:
                        loop_fn_outputs = loop_fn(i + offset, pfor_config=pfor_config)
                    else:
                        loop_fn_outputs = loop_fn(i + offset)
                    return nest.flatten(nest.map_structure(_composite_to_tensors, loop_fn_outputs))
                return _pfor_impl(tiled_loop_fn, parallel_iterations, fallback_to_while_loop=fallback_to_while_loop, pfor_config=pfor_config)
            tiled_output_tensors = for_loop(tiled_loop_body, loop_fn_dtypes, num_tiled_iterations, parallel_iterations=1)
            tiled_output_tensors = [_flatten_first_two_dims(y) for y in tiled_output_tensors]
        with ops.name_scope('pfor'):
            if iters_value is None or iters_value % parallel_iterations:
                output_tensors = cond.cond(math_ops.equal(num_remaining_iterations, 0), lambda : tiled_output_tensors, lambda : [array_ops.concat([x, y], axis=0) for (x, y) in zip(remaining_output_tensors, tiled_output_tensors)])
            else:
                output_tensors = tiled_output_tensors
            flattened_output_tensors = nest.flatten(output_tensors)
            for (output, original_output) in zip(flattened_output_tensors, nest.flatten(loop_fn_output_tensors)):
                output.set_shape(tensor_shape.TensorShape([iters_value]).concatenate(original_output.shape))
    return nest.map_structure_up_to(loop_fn_outputs, functools.partial(_composite_from_tensors, batch_size=iters_value), nest.pack_sequence_as(loop_fn_output_tensors, flattened_output_tensors), loop_fn_outputs)

def equals(self, other) -> bool:
    if type(self) is not type(other):
        return False
    if <MASK>:
        return False
    return bool(array_equivalent(self._ndarray, other._ndarray, dtype_equal=True))

def _create_grouped_mm_output_tensor(mat1, mat2, offs, out_dtype):
    mat1_is_2d = mat1.dim() == 2
    mat2_is_2d = mat2.dim() == 2
    if <MASK>:
        if mat2_is_2d:
            out_size = [offs.size(0), mat1.size(0), mat2.size(1)]
        else:
            torch._check(offs.size(0) == mat2.size(0), lambda : 'matrix batch sizes have to match')
            out_size = [mat1.size(0), mat2.size(-1)]
    elif mat2_is_2d:
        torch._check(offs.size(0) == mat1.size(0), lambda : 'matrix batch sizes have to match')
        out_size = [mat1.size(1), mat2.size(1)]
    else:
        torch._check(mat1.size(0) == mat2.size(0), lambda : 'batched dimension has to match')
        out_size = [mat1.size(0), mat1.size(1), mat2.size(-1)]
    out_dtype = out_dtype or mat1.dtype
    if torch.version.cuda:
        alignment = 16 // out_dtype.itemsize
        size_padded = (out_size[-1] + alignment - 1) // alignment * alignment
        if mat1_is_2d == mat2_is_2d:
            out_stride = [out_size[1] * size_padded, size_padded, 1]
        else:
            out_stride = [size_padded, 1]
        out = torch.empty_strided(out_size, out_stride, dtype=out_dtype, device=mat1.device)
    else:
        out = torch.empty(out_size, dtype=out_dtype, device=mat1.device)
    return out

def reference_group_norm(inp: npt.NDArray, num_groups: int, weight=None, bias=None, eps=1e-05):
    inp_view = inp
    if np.prod(inp.shape) != 0:
        inp_view = inp.reshape((inp.shape[0], num_groups, -1))
    mean = inp_view.mean(axis=-1, keepdims=True)
    var = inp_view.var(axis=-1, ddof=0, keepdims=True)
    Y = (inp_view - mean) / np.sqrt(var + eps)
    Y = Y.reshape(inp.shape)
    if <MASK>:
        if len(Y.shape) > 2:
            weight = np.expand_dims(weight, [0] + [idx + 2 for idx in range(inp.ndim - 2)])
        Y = Y * weight
    if bias is not None:
        if len(Y.shape) > 2:
            bias = np.expand_dims(bias, [0] + [idx + 2 for idx in range(inp.ndim - 2)])
        Y = Y + bias
    return Y

@register_backend
def eager_debug(gm: torch.fx.GraphModule, fake_tensor_inputs: list[torch.Tensor], **kwargs: Any) -> Callable[..., Any]:
    if <MASK>:
        log.warning('eager_debug backend ignoring extra kwargs %s', kwargs)
    from torch._subclasses.schema_check_mode import SchemaCheckMode

    def inner(*args: Any) -> Any:
        with SchemaCheckMode():
            return torch.fx.Interpreter(gm).run(*args)
    return inner

def checkGraphModuleNodes(self, graph_module, expected_node=None, expected_node_occurrence=None, expected_node_list=None):
    """Check if GraphModule contains the target node
        Args:
            graph_module: the GraphModule instance we want to check
            expected_node, expected_node_occurrence, expected_node_list:
               see docs for checkGraphModeFxOp
        """
    nodes_in_graph = {}
    node_list = []
    modules = dict(graph_module.named_modules(remove_duplicate=False))
    for node in graph_module.graph.nodes:
        n = None
        if node.op == 'call_function' or node.op == 'call_method':
            n = NodeSpec(node.op, node.target)
        elif node.op == 'call_module':
            n = NodeSpec(node.op, type(modules[node.target]))
        if n is not None:
            node_list.append(n)
            if n in nodes_in_graph:
                nodes_in_graph[n] += 1
            else:
                nodes_in_graph[n] = 1
    if expected_node is not None:
        self.assertTrue(expected_node in nodes_in_graph, 'node:' + str(expected_node) + ' not found in the graph module')
    if expected_node_occurrence is not None:
        for (expected_node, occurrence) in expected_node_occurrence.items():
            if <MASK>:
                self.assertTrue(expected_node in nodes_in_graph, 'Check failed for node:' + str(expected_node) + ' not found')
                self.assertTrue(nodes_in_graph[expected_node] == occurrence, 'Check failed for node:' + str(expected_node) + ' Expected occurrence:' + str(occurrence) + ' Found occurrence:' + str(nodes_in_graph[expected_node]))
            else:
                self.assertTrue(expected_node not in nodes_in_graph, 'Check failed for node:' + str(expected_node) + ' expected no occurrence but found')
    if expected_node_list is not None:
        cur_index = 0
        for n in node_list:
            if cur_index == len(expected_node_list):
                return
            if n == expected_node_list[cur_index]:
                cur_index += 1
        self.assertTrue(cur_index == len(expected_node_list), 'Check failed for graph:' + self.printGraphModule(graph_module, print_str=False) + 'Expected ordered list:' + str(expected_node_list))

def _rescale_data(X, y, sample_weight, inplace=False):
    """Rescale data sample-wise by square root of sample_weight.

    For many linear models, this enables easy support for sample_weight because

        (y - X w)' S (y - X w)

    with S = diag(sample_weight) becomes

        ||y_rescaled - X_rescaled w||_2^2

    when setting

        y_rescaled = sqrt(S) y
        X_rescaled = sqrt(S) X

    The parameter `inplace` only takes effect for dense X and dense y.

    Returns
    -------
    X_rescaled : {array-like, sparse matrix}

    y_rescaled : {array-like, sparse matrix}

    sample_weight_sqrt : array-like of shape (n_samples,)
    """
    (xp, _) = get_namespace(X, y, sample_weight)
    n_samples = X.shape[0]
    sample_weight_sqrt = xp.sqrt(sample_weight)
    if <MASK>:
        sw_matrix = sparse.dia_matrix((sample_weight_sqrt, 0), shape=(n_samples, n_samples))
    if sp.issparse(X):
        X = safe_sparse_dot(sw_matrix, X)
    elif inplace:
        X *= sample_weight_sqrt[:, None]
    else:
        X = X * sample_weight_sqrt[:, None]
    if sp.issparse(y):
        y = safe_sparse_dot(sw_matrix, y)
    elif inplace:
        if y.ndim == 1:
            y *= sample_weight_sqrt
        else:
            y *= sample_weight_sqrt[:, None]
    elif y.ndim == 1:
        y = y * sample_weight_sqrt
    else:
        y = y * sample_weight_sqrt[:, None]
    return (X, y, sample_weight_sqrt)

def run(self):
    build_clib_cmd = get_cmd('build_clib')
    if not build_clib_cmd.build_clib:
        build_clib_cmd.finalize_options()
    build_dir = build_clib_cmd.build_clib
    if <MASK>:
        compiler = new_compiler(compiler=None)
        compiler.customize(self.distribution)
    else:
        compiler = build_clib_cmd.compiler
    for l in self.distribution.installed_libraries:
        target_dir = os.path.join(self.install_dir, l.target_dir)
        name = compiler.library_filename(l.name)
        source = os.path.join(build_dir, name)
        self.mkpath(target_dir)
        self.outfiles.append(self.copy_file(source, target_dir)[0])

@record_shapeenv_event()
def create_symintnode(self, sym: sympy.Expr, *, hint: Optional[int], source: Optional[Source]=None) -> IntLikeType:
    """Create a SymInt value from a symbolic expression

        If you know what the current hint value of the SymInt to be created
        is, pass it into hint.  Otherwise, pass None and we will make our best
        guess

        """
    if self._translation_validation_enabled and source is not None:
        symbol = self._create_symbol_for_source(source)
        assert symbol is not None
        fx_node = self._create_fx_placeholder_and_z3var(symbol, int)
        self._add_assertion(sympy.Eq(symbol, sym))
    else:
        fx_node = None
    out: IntLikeType
    if isinstance(sym, sympy.Integer):
        if <MASK>:
            assert int(sym) == hint
        out = int(sym)
    else:
        if free_unbacked_symbols(sym):
            hint = None
        out = SymInt(SymNode(sym, self, int, hint, fx_node=fx_node))
    return out

@st.composite
def tensor(draw, shapes=None, elements=None, qparams=None, dtype=np.float32):
    if isinstance(shapes, SearchStrategy):
        _shape = draw(shapes)
    else:
        _shape = draw(st.sampled_from(shapes))
    if qparams is None:
        if <MASK>:
            elements = floats(-1000000.0, 1000000.0, allow_nan=False, width=32)
        X = draw(stnp.arrays(dtype=dtype, elements=elements, shape=_shape))
        assume(not (np.isnan(X).any() or np.isinf(X).any()))
        return (X, None)
    qparams = draw(qparams)
    if elements is None:
        (min_value, max_value) = _get_valid_min_max(qparams)
        elements = floats(min_value, max_value, allow_infinity=False, allow_nan=False, width=32)
    X = draw(stnp.arrays(dtype=dtype, elements=elements, shape=_shape))
    (scale, zp) = _calculate_dynamic_qparams(X, qparams[2])
    enforced_zp = _ENFORCED_ZERO_POINT.get(qparams[2], None)
    if enforced_zp is not None:
        zp = enforced_zp
    return (X, (scale, zp, qparams[2]))

@symbolic_helper.parse_args('v', 'v', 'i', 'none')
def reduce_dim(g, self, dim, keepdim, dtype):
    dtype_onnx = None
    if dtype.node().kind() == 'onnx::Constant':
        dtype = symbolic_helper._get_const(dtype, 'i', 'dtype')
        dtype_onnx = _type_utils.JitScalarType(dtype).onnx_type()
        self = g.op('Cast', self, to_i=dtype_onnx)
    elif dtype.node().kind() != 'prim::Constant':
        return symbolic_helper._unimplemented(name, 'dtype', dtype)
    result = symbolic(g, self, dim, keepdim)
    if <MASK>:
        result_dtype_onnx = _type_utils.JitScalarType.from_value(result).onnx_type()
        if result_dtype_onnx != dtype_onnx:
            result = g.op('Cast', result, to_i=dtype_onnx)
    return result

def _get_weekday(self, date):
    """
        Return the weekday for a given date.

        The first day according to the week format is 0 and the last day is 6.
        """
    week_format = self.get_week_format()
    if week_format in {'%W', '%V'}:
        return date.weekday()
    elif <MASK>:
        return (date.weekday() + 1) % 7
    else:
        raise ValueError('unknown week format: %s' % week_format)

def _find_loss_from_output_and_spec(output_val, spec_val):
    if spec_val is False:
        return None
    if spec_val is True:
        if not isinstance(output_val, fx.Node):
            raise RuntimeError(f'Loss spec must specify a dynamic value but got {output_val}')
        return output_val
    if isinstance(spec_val, (tuple, list)):
        if not isinstance(output_val, (tuple, list)):
            raise RuntimeError(f'Output value {output_val} must match type of loss specification {spec_val}')
        if len(output_val) != len(spec_val):
            raise RuntimeError(f'Output value {output_val} must match length of loss specification {spec_val}')
        for (out, spec) in zip(output_val, spec_val):
            loss_val = _find_loss_from_output_and_spec(out, spec)
            if loss_val is not None:
                return loss_val
        raise RuntimeError(f'Did not find loss value in specification {spec_val}')
    if isinstance(spec_val, dict):
        if not isinstance(output_val, dict):
            raise RuntimeError(f'Output value {output_val} must match type of loss specification {spec_val}')
        if <MASK>:
            raise RuntimeError(f'Output value {output_val} must match keys of loss specification {spec_val}')
        for k in spec_val:
            loss_val = _find_loss_from_output_and_spec(output_val[k], spec_val[k])
            if loss_val is not None:
                return loss_val
        raise RuntimeError(f'Did not find loss value in specification {spec_val}')
    raise RuntimeError(f'Unsupported type {type(spec_val)} in loss specification')

def get_submodule(self, name: str) -> 'torch.nn.Module':
    """
        Return the submodule specified by the given path.

        For example, to get the submodule mod.layer1.conv1,
        use accessor.get_submodule("layer1.conv1")

        Compare to mod.get_submodule("layer1.conv1"), this method will cache the
        intermediate submodule access to speed up future lookups.
        """
    if not name:
        return self.module
    if name in self.memo:
        return self.memo[name]
    else:
        (prefix, dot, attr) = name.rpartition('.')
        if <MASK>:
            module = self.get_submodule(prefix)
        else:
            module = self.module
        try:
            submodule = getattr(module, attr)
        except AttributeError as ex:
            raise AttributeError(f'{module._get_name()} has no attribute `{attr}`') from ex
        if not isinstance(submodule, torch.nn.Module):
            raise TypeError(f'submodule `{name}`: {submodule} is not an instance of torch.nn.Module')
        self.memo[name] = submodule
        return submodule

def _unicode_decode(input, input_encoding, errors, replacement_char, replace_control_characters, with_offsets):
    """Decodes each string into a sequence of codepoints."""
    input = ragged_tensor.convert_to_tensor_or_ragged_tensor(input, name='input')
    input_ndims = input.shape.ndims
    if input_ndims is None:
        raise ValueError('Rank of `input` must be statically known.')
    if input_ndims > 1:
        if not ragged_tensor.is_ragged(input):
            input = ragged_tensor.RaggedTensor.from_tensor(input, ragged_rank=input_ndims - 1)
        elif input.ragged_rank < input_ndims - 1:
            input = input.with_flat_values(ragged_tensor.RaggedTensor.from_tensor(input.flat_values, ragged_rank=input_ndims - input.ragged_rank - 1))
    if ragged_tensor.is_ragged(input):
        flat_input = array_ops.reshape(input.flat_values, [-1])
    else:
        flat_input = array_ops.reshape(input, [-1])
    if <MASK>:
        decode_op = gen_string_ops.unicode_decode_with_offsets
    else:
        decode_op = gen_string_ops.unicode_decode
    flat_result = decode_op(input=flat_input, input_encoding=input_encoding, errors=errors, replacement_char=replacement_char, replace_control_characters=replace_control_characters)
    if input_ndims == 0:
        codepoints = flat_result.char_values
        if with_offsets:
            offsets = flat_result.char_to_byte_starts
    else:
        codepoints = ragged_tensor.RaggedTensor.from_row_splits(flat_result.char_values, flat_result.row_splits, validate=False)
        if input_ndims > 1:
            codepoints = input.with_flat_values(codepoints)
        if with_offsets:
            offsets = ragged_tensor.RaggedTensor.from_row_splits(flat_result.char_to_byte_starts, flat_result.row_splits, validate=False)
            if input_ndims > 1:
                offsets = input.with_flat_values(offsets)
    if with_offsets:
        return (codepoints, offsets)
    else:
        return codepoints

@contextlib.contextmanager
def _distribute_region(self, spec: DTensorSpec, generator: Optional[torch.Generator]=None):
    if generator is not None:
        state = _PhiloxState(generator.get_state())
    else:
        state = _PhiloxState(self._get_device_state())
    if <MASK>:
        if self._device.type == 'hpu':
            self._device_handle.set_rng_ctx('philox')
        old_offset = state.offset
        self._set_pre_op_offset(state, spec)
        with torch.random.fork_rng(devices=[self._device], device_type=self._device.type):
            assert self._device_handle is not None
            self._device_handle.set_rng_state(state.state)
            try:
                yield
            finally:
                self._set_post_op_offset(state, spec, old_offset)
        if self._device.type == 'hpu':
            self._device_handle.unset_rng_ctx('philox')
    else:
        yield
    if generator is not None:
        generator.set_state(state.state)
    else:
        self._set_device_state(state.state)

def _execute(self, sql, params, *ignored_wrapper_args):
    if <MASK>:
        warnings.warn(self.APPS_NOT_READY_WARNING_MSG, category=RuntimeWarning)
    self.db.validate_no_broken_transaction()
    with self.db.wrap_database_errors:
        if params is None:
            return self.cursor.execute(sql)
        else:
            return self.cursor.execute(sql, params)

def check_step_delta(self, expected_allocated: list[str], expected_freed: list[str], is_final_step: bool) -> None:
    """Check only the delta changes since last step"""
    if not is_final_step:
        missing_deaths = OrderedSet(expected_freed) - self.died_since_last_step
        if missing_deaths:
            self.log_or_raise(f'Expected tensors to die but still alive: {missing_deaths}')
    unexpected_deaths = self.died_since_last_step - OrderedSet(expected_freed)
    if unexpected_deaths:
        self.log_or_raise(f'Unexpected tensor deaths: {unexpected_deaths}')
    actual_allocated = self.added_since_last_step
    expected_allocated_set = OrderedSet(expected_allocated)
    extra_alive = actual_allocated - expected_allocated_set
    if extra_alive:
        self.log_or_raise(f'Unexpected allocated tensors: {extra_alive}')
    missing_alive = expected_allocated_set - actual_allocated
    if <MASK>:
        self.log_or_raise(f'Expected allocated tensors but missing: {missing_alive}')
    self.advance_step()
    if is_final_step:
        local.memory_tracker = None

def out_wrapper(*out_names: str, exact_dtype: bool=False, pass_is_out: bool=False, preserve_memory_format: bool=False) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:
    default_out_names = ('out',)
    if len(out_names) == 0:
        out_names = default_out_names
    is_tensor = len(out_names) == 1

    def maybe_compute_memory_format(t):
        return utils.suggest_memory_format(t) if preserve_memory_format else None

    def _out_wrapper(fn: Callable[_P, _T]) -> Callable[_P, _T]:
        """
        Adds the out parameter to a Python reference.
        """
        out_type = TensorLikeType if is_tensor else GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
        bc_out_type = TensorLikeType if is_tensor else types.GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
        return_type = TensorLikeType if is_tensor else NamedTuple(f'return_types_{fn.__name__}', [(o, TensorLikeType) for o in out_names])
        sig = inspect.signature(fn)
        factory_kwargs = ('device', 'dtype')
        is_factory_fn = all((p in sig.parameters for p in factory_kwargs))

        @wraps(fn)
        def _fn(*args: _P.args, **kwargs: _P.kwargs):
            out = kwargs.pop('out', None)
            if is_factory_fn and out is not None:
                for k in factory_kwargs:
                    out_attr = getattr(out, k)
                    if <MASK>:
                        kwargs[k] = out_attr

            def maybe_check_copy_devices(out):
                if isinstance(out, TensorLike) and isinstance(args[0], TensorLike):
                    check_copy_devices(copy_from=args[0], copy_to=out)
            if isinstance(out, (tuple, list)):
                for o in out:
                    maybe_check_copy_devices(o)
            else:
                maybe_check_copy_devices(out)
            if pass_is_out:
                result = fn(*args, is_out=out is not None, **kwargs)
            else:
                result = fn(*args, **kwargs)
            if result is NotImplemented:
                return NotImplemented
            assert isinstance(result, TensorLike) and is_tensor or (isinstance(result, tuple) and len(result) == len(out_names)) or (fn.__name__ == 'unbind' and isinstance(result, (list, tuple)))
            if out is not None:
                if is_tensor and fn.__name__ != 'unbind':
                    assert isinstance(out, TensorLike)
                    _maybe_resize_out(out, result.shape, maybe_compute_memory_format(result))
                    _safe_copy_out(copy_from=result, copy_to=out, exact_dtype=exact_dtype)
                else:
                    if fn.__name__ != 'unbind':
                        assert isinstance(out, tuple)
                    else:
                        assert isinstance(out, (list, tuple))
                    torch._check_type(len(out) == len(result), lambda : f'expected tuple of {len(result)} elements but got {len(out)}')
                    for (r, o) in zip(result, out):
                        _maybe_resize_out(o, r.shape, maybe_compute_memory_format(r))
                        _safe_copy_out(copy_from=r, copy_to=o, exact_dtype=exact_dtype)
            else:
                out = result
            return out if is_tensor else return_type(*out)
        out_param = inspect.Parameter('out', kind=inspect.Parameter.KEYWORD_ONLY, default=None, annotation=out_type)
        assert isinstance(sig.return_annotation, (str, TypeVar)) or sig.return_annotation in (sig.empty, out_type, bc_out_type)
        params = (*sig.parameters.values(), out_param)
        params = sorted(params, key=lambda p: p.kind)
        _fn.__signature__ = inspect.Signature(parameters=params, return_annotation=return_type)
        _fn.__annotations__ = dict(getattr(fn, '__annotations__', {}))
        _fn.__annotations__['out'] = out_type
        _fn.__annotations__['return'] = return_type
        if is_tensor and out_names != default_out_names:
            _fn.__annotations__[CustomOutParamAnnotation] = out_names[0]
        _fn._torch_decompositions_out_wrapper = f'This function is wrapped by {out_wrapper.__module__}.out_wrapper'
        return _fn
    return _out_wrapper

def __init__(self, sparsity_level: float=0.5, sparse_block_shape: tuple[int, int]=(1, 4), zeros_per_block: Optional[int]=None, norm: Optional[Union[Callable, int]]=None):
    if zeros_per_block is None:
        zeros_per_block = reduce(operator.mul, sparse_block_shape)
    defaults = {'sparsity_level': sparsity_level, 'sparse_block_shape': sparse_block_shape, 'zeros_per_block': zeros_per_block}
    if norm is None:
        norm = 2
    if <MASK>:
        self.norm_fn = norm
    elif norm == 1:
        self.norm_fn = lambda T: T.abs()
    elif norm == 2:
        self.norm_fn = lambda T: T * T
    else:
        raise NotImplementedError(f'L-{norm} is not yet implemented.')
    super().__init__(defaults=defaults)

def get_cpu_info(run_lambda):
    (rc, out, err) = (0, '', '')
    if get_platform() == 'linux':
        (rc, out, err) = run_lambda('lscpu')
    elif get_platform() == 'win32':
        (rc, out, err) = run_lambda('powershell.exe "gwmi -Class Win32_Processor | Select-Object -Property Name,Manufacturer,Family,            Architecture,ProcessorType,DeviceID,CurrentClockSpeed,MaxClockSpeed,L2CacheSize,L2CacheSpeed,Revision            | ConvertTo-Json"')
        if rc == 0:
            lst = []
            try:
                obj = json.loads(out)
                if <MASK>:
                    for o in obj:
                        lst.append('----------------------')
                        lst.extend([f'{k}: {v}' for (k, v) in o.items()])
                else:
                    lst.extend([f'{k}: {v}' for (k, v) in obj.items()])
            except ValueError as e:
                lst.append(out)
                lst.append(str(e))
            out = '\n'.join(lst)
    elif get_platform() == 'darwin':
        (rc, out, err) = run_lambda('sysctl -n machdep.cpu.brand_string')
    cpu_info = 'None'
    if rc == 0:
        cpu_info = out
    else:
        cpu_info = err
    return cpu_info

def visualize_overlap(order):
    total_est_runtime: float = 0.0
    cur_comm_node = None

    def step_log(step, msg):
        overlap_log.debug(f'{step:>6}: {msg}')
    for (step, snode) in enumerate(order):
        if cur_comm_node is None:
            if <MASK>:
                total_est_runtime += estimate_op_runtime(snode)
                cur_comm_node = snode.node
            elif is_wait(snode.node):
                pass
            else:
                total_est_runtime += estimate_op_runtime(snode)
            step_log(step, f'{node_summary(snode)}')
        elif contains_collective(snode):
            total_est_runtime += estimate_op_runtime(snode)
            cur_comm_node = snode.node
            step_log(step, f'{node_summary(snode)}')
        elif is_wait(snode.node):
            step_log(step, f'{node_summary(snode)}')
            cur_comm_node = None
        else:
            step_log(step, f'| {node_summary(snode)}')
    overlap_log.debug(f'Est. runtime (ms): {total_est_runtime / 1000 / 1000}')

def __eq__(self, other: object) -> bool:
    if isinstance(other, str):
        try:
            other = self.construct_from_string(other)
        except TypeError:
            return False
    if isinstance(other, type(self)):
        subtype = self.subtype == other.subtype
        if <MASK>:
            fill_value = isinstance(self.fill_value, type(other.fill_value)) or isinstance(other.fill_value, type(self.fill_value))
        else:
            with warnings.catch_warnings():
                warnings.filterwarnings('ignore', 'elementwise comparison failed', category=DeprecationWarning)
                fill_value = self.fill_value == other.fill_value
        return subtype and fill_value
    return False

def _check_compiler(self):
    old_config._check_compiler(self)
    from numpy.distutils.fcompiler import FCompiler, new_fcompiler
    if sys.platform == 'win32' and self.compiler.compiler_type in ('msvc', 'intelw', 'intelemw'):
        if not self.compiler.initialized:
            try:
                self.compiler.initialize()
            except OSError as e:
                msg = textwrap.dedent('                        Could not initialize compiler instance: do you have Visual Studio\n                        installed?  If you are trying to build with MinGW, please use "python setup.py\n                        build -c mingw32" instead.  If you have Visual Studio installed, check it is\n                        correctly installed, and the right version (VS 2015 as of this writing).\n\n                        Original exception was: %s, and the Compiler class was %s\n                        ============================================================================') % (e, self.compiler.__class__.__name__)
                print(textwrap.dedent('                        ============================================================================'))
                raise distutils.errors.DistutilsPlatformError(msg) from e
        from distutils import msvc9compiler
        if msvc9compiler.get_build_version() >= 10:
            for ldflags in [self.compiler.ldflags_shared, self.compiler.ldflags_shared_debug]:
                if '/MANIFEST' not in ldflags:
                    ldflags.append('/MANIFEST')
    if not isinstance(self.fcompiler, FCompiler):
        self.fcompiler = new_fcompiler(compiler=self.fcompiler, dry_run=self.dry_run, force=1, c_compiler=self.compiler)
        if <MASK>:
            self.fcompiler.customize(self.distribution)
            if self.fcompiler.get_version():
                self.fcompiler.customize_cmd(self)
                self.fcompiler.show_customization()

def _validate_input(flattened_layouts: Sequence[layout_lib.Layout], flattened_elem_spec: Sequence[tensor_spec.TensorSpec], dataset_already_batched: bool):
    """Checks that the dataset's layouts and element specs are compatible.

  Args:
    flattened_layouts: the flattened list of layouts used to distribute the
      dataset.
    flattened_elem_spec: the flattened list of element specs used in the
      dataset's components.
    dataset_already_batched: whether the dataset to be validated is already
      batched.

  Raises:
    ValueError: if the dataset's inputs are incompatible.
  """
    if not flattened_elem_spec:
        raise ValueError('Expected input element spec of at least one element, was empty.')
    first_elem_shape = flattened_elem_spec[0].shape
    for (layout, elem_spec) in zip(flattened_layouts, flattened_elem_spec):
        if elem_spec.shape.rank is None:
            raise ValueError('Dataset element shape must have a valid rank, got spec %s.' % elem_spec)
        expected_rank = elem_spec.shape.rank
        if <MASK>:
            expected_rank += 1
        if layout.rank != expected_rank:
            raise ValueError('Expected layout with rank %d for element spec %s, got layout %s. Check that the dataset is not batched before passing to DTensorDataset.' % (expected_rank, elem_spec, layout.sharding_specs))
        if dataset_already_batched:
            batch_dim_size = first_elem_shape.as_list()[0]
            if batch_dim_size is None:
                raise ValueError('Size of batch dimension of element spec %s is None. Ensure drop_remainder=True when batching the dataset.' % elem_spec)
            if elem_spec.shape.as_list()[0] != batch_dim_size:
                raise ValueError('Size of batch dimension of element spec %s does not match expected size %d.' % (elem_spec, batch_dim_size))

def _floats_wrapper(*args, **kwargs):
    if <MASK>:
        no_nan_and_inf = ('allow_nan' in kwargs and (not kwargs['allow_nan']) or 'allow_nan' not in kwargs) and ('allow_infinity' in kwargs and (not kwargs['allow_infinity']) or 'allow_infinity' not in kwargs)
        min_and_max_not_specified = len(args) == 0 and 'min_value' not in kwargs and ('max_value' not in kwargs)
        if no_nan_and_inf and min_and_max_not_specified:
            if kwargs['width'] == 16:
                kwargs['min_value'] = torch.finfo(torch.float16).min
                kwargs['max_value'] = torch.finfo(torch.float16).max
            elif kwargs['width'] == 32:
                kwargs['min_value'] = torch.finfo(torch.float32).min
                kwargs['max_value'] = torch.finfo(torch.float32).max
            elif kwargs['width'] == 64:
                kwargs['min_value'] = torch.finfo(torch.float64).min
                kwargs['max_value'] = torch.finfo(torch.float64).max
        kwargs.pop('width')
    return st.floats(*args, **kwargs)

