def _verify_stack_trace(graph_module: torch.fx.GraphModule) -> None:
    """
    Perform stack trace checks on the graph.
    Constraints:
        - None or non-empty str for 'call_function', 'get_attr'
        - None for 'placeholder', 'output'
    """
    for mod in [graph_module, *graph_module.modules()]:
        if <MASK>:
            continue
        for node in graph_module.graph.nodes:
            stack_trace = node.meta.get('stack_trace', None)
            if node.op in ['call_function', 'get_attr']:
                if not (stack_trace is None or isinstance(stack_trace, str)):
                    raise SpecViolationError(f'Node {node} of type {node.op} has invalid stack_trace metadata, expected a string or None but instead found: {stack_trace}')
            elif node.op in ['placeholder', 'output']:
                if stack_trace:
                    raise SpecViolationError(f'Node {node} of type {node.op} contains stack_trace metadata, expected None but instead found: {stack_trace}')

def build_filter(self, filter_expr, branch_negated=False, current_negated=False, can_reuse=None, allow_joins=True, split_subq=True, check_filterable=True, summarize=False, update_join_types=True):
    """
        Build a WhereNode for a single filter clause but don't add it
        to this Query. Query.add_q() will then add this filter to the where
        Node.

        The 'branch_negated' tells us if the current branch contains any
        negations. This will be used to determine if subqueries are needed.

        The 'current_negated' is used to determine if the current filter is
        negated or not and this will be used to determine if IS NULL filtering
        is needed.

        The difference between current_negated and branch_negated is that
        branch_negated is set on first negation, but current_negated is
        flipped for each negation.

        Note that add_filter will not do any negating itself, that is done
        upper in the code by add_q().

        The 'can_reuse' is a set of reusable joins for multijoins.

        The method will create a filter clause that can be added to the current
        query. However, if the filter isn't added to the query then the caller
        is responsible for unreffing the joins used.
        """
    if isinstance(filter_expr, dict):
        raise FieldError('Cannot parse keyword query as dict')
    if isinstance(filter_expr, Q):
        return self._add_q(filter_expr, branch_negated=branch_negated, current_negated=current_negated, used_aliases=can_reuse, allow_joins=allow_joins, split_subq=split_subq, check_filterable=check_filterable, summarize=summarize, update_join_types=update_join_types)
    if hasattr(filter_expr, 'resolve_expression'):
        if not getattr(filter_expr, 'conditional', False):
            raise TypeError('Cannot filter against a non-conditional expression.')
        condition = filter_expr.resolve_expression(self, allow_joins=allow_joins, reuse=can_reuse, summarize=summarize)
        if not isinstance(condition, Lookup):
            condition = self.build_lookup(['exact'], condition, True)
        return (WhereNode([condition], connector=AND), [])
    (arg, value) = filter_expr
    if not arg:
        raise FieldError('Cannot parse keyword query %r' % arg)
    (lookups, parts, reffed_expression) = self.solve_lookup_type(arg, summarize)
    if check_filterable:
        self.check_filterable(reffed_expression)
    if not allow_joins and len(parts) > 1:
        raise FieldError('Joined field references are not permitted in this query')
    pre_joins = self.alias_refcount.copy()
    value = self.resolve_lookup_value(value, can_reuse, allow_joins, summarize)
    used_joins = {k for (k, v) in self.alias_refcount.items() if v > pre_joins.get(k, 0)}
    if check_filterable:
        self.check_filterable(value)
    if reffed_expression:
        condition = self.build_lookup(lookups, reffed_expression, value)
        return (WhereNode([condition], connector=AND), [])
    opts = self.get_meta()
    alias = self.get_initial_alias()
    allow_many = not branch_negated or not split_subq
    try:
        join_info = self.setup_joins(parts, opts, alias, can_reuse=can_reuse, allow_many=allow_many)
        if isinstance(value, Iterator):
            value = list(value)
        self.check_related_objects(join_info.final_field, value, join_info.opts)
        self._lookup_joins = join_info.joins
    except MultiJoin as e:
        return self.split_exclude(filter_expr, can_reuse, e.names_with_path)
    used_joins.update(join_info.joins)
    (targets, alias, join_list) = self.trim_joins(join_info.targets, join_info.joins, join_info.path)
    if <MASK>:
        can_reuse.update(join_list)
    if join_info.final_field.is_relation:
        if len(targets) == 1:
            col = self._get_col(targets[0], join_info.final_field, alias)
        else:
            col = ColPairs(alias, targets, join_info.targets, join_info.final_field)
    else:
        col = self._get_col(targets[0], join_info.final_field, alias)
    condition = self.build_lookup(lookups, col, value)
    lookup_type = condition.lookup_name
    clause = WhereNode([condition], connector=AND)
    require_outer = lookup_type == 'isnull' and condition.rhs is True and (not current_negated)
    if current_negated and (lookup_type != 'isnull' or condition.rhs is False) and (condition.rhs is not None):
        require_outer = True
        if lookup_type != 'isnull':
            if self.is_nullable(targets[0]) or self.alias_map[join_list[-1]].join_type == LOUTER:
                lookup_class = targets[0].get_lookup('isnull')
                col = self._get_col(targets[0], join_info.targets[0], alias)
                clause.add(lookup_class(col, False), AND)
            if isinstance(value, Col) and self.is_nullable(value.target):
                lookup_class = value.target.get_lookup('isnull')
                clause.add(lookup_class(value, False), AND)
    return (clause, used_joins if not require_outer else ())

def issubtype(left, right, recursive=True):
    """
    Check if the left-side type is a subtype of the right-side type.

    If any of type is a composite type like `Union` and `TypeVar` with
    bounds, it would be expanded into a list of types and check all
    of left-side types are subtypes of either one from right-side types.
    """
    left = TYPE2ABC.get(left, left)
    right = TYPE2ABC.get(right, right)
    if <MASK>:
        return True
    if isinstance(right, _GenericAlias):
        if getattr(right, '__origin__', None) is Generic:
            return True
    if right is type(None):
        return False
    constraints = _decompose_type(right)
    if len(constraints) == 0 or Any in constraints:
        return True
    if left is Any:
        return False
    variants = _decompose_type(left)
    if len(variants) == 0:
        return False
    return all((_issubtype_with_constraints(variant, constraints, recursive) for variant in variants))

def reduce(self, target, axis=0, dtype=None):
    """
        Reduce `target` along the given `axis`.

        """
    tclass = get_masked_subclass(target)
    m = getmask(target)
    t = filled(target, self.filly)
    if <MASK>:
        t = t.reshape(1)
        if m is not nomask:
            m = make_mask(m, copy=True)
            m.shape = (1,)
    if m is nomask:
        tr = self.f.reduce(t, axis)
        mr = nomask
    else:
        tr = self.f.reduce(t, axis, dtype=dtype)
        mr = umath.logical_and.reduce(m, axis)
    if not tr.shape:
        if mr:
            return masked
        else:
            return tr
    masked_tr = tr.view(tclass)
    masked_tr._mask = mr
    return masked_tr

@while_loop_op.py_impl(DispatchKey.CompositeExplicitAutograd)
def while_loop_dense(cond_fn, body_fn, carried_inputs, additional_inputs, stack_output=False):
    carried_vals = carried_inputs

    def _validate_cond_output(pred):
        if isinstance(pred, torch.Tensor) and pred.size() == torch.Size([]) and (pred.dtype == torch.bool) or isinstance(pred, bool):
            return
        else:
            raise RuntimeError(f'cond_fn must return a boolean scalar tensor or a boolean but got {pred}')
    if not isinstance(carried_inputs, (tuple, list)):
        raise RuntimeError(f'carried_inputs must be a tuple or list but got {type(carried_inputs)}')
    should_loop = cond_fn(*carried_vals, *additional_inputs)
    _validate_cond_output(should_loop)
    if not should_loop:
        if <MASK>:
            return tuple((val.unsqueeze(0).clone() if isinstance(val, torch.Tensor) else val for val in carried_vals))
        else:
            return tuple((val.clone() if isinstance(val, torch.Tensor) else val for val in carried_vals))
    outputs: list[list[torch.Tensor]] = [[] for _ in carried_vals]
    while should_loop:
        out = body_fn(*carried_vals, *additional_inputs)
        if stack_output:
            for (i, o) in enumerate(out):
                outputs[i].append(o)
        assert isinstance(out, tuple), f'body_fn should return a tuple but got {type(out)}'
        assert len(out) == len(carried_inputs), 'body_fn should return the same number of elements as carried_inputs'
        carried_vals = out
        should_loop = cond_fn(*carried_vals, *additional_inputs)
    if stack_output:
        outs: list[torch.Tensor] = []
        for (i, out) in enumerate(outputs):
            outs.append(torch.stack(out, dim=0))
        return tuple(outs)
    return carried_vals

@symbolic_helper.parse_args('v', 'v', 'i', 'none')
def reduce_dim(g, self, dim, keepdim, dtype):
    dtype_onnx = None
    if dtype.node().kind() == 'onnx::Constant':
        dtype = symbolic_helper._get_const(dtype, 'i', 'dtype')
        dtype_onnx = _type_utils.JitScalarType(dtype).onnx_type()
        self = g.op('Cast', self, to_i=dtype_onnx)
    elif <MASK>:
        return symbolic_helper._unimplemented(name, 'dtype', dtype)
    result = symbolic(g, self, dim, keepdim)
    if dtype_onnx is not None:
        result_dtype_onnx = _type_utils.JitScalarType.from_value(result).onnx_type()
        if result_dtype_onnx != dtype_onnx:
            result = g.op('Cast', result, to_i=dtype_onnx)
    return result

