        return a.as_custom_obj
    elif a.type == 'as_operator':
        return None
    else:
        raise AssertionError(f'Unknown input type to the ExportedProgram: {a}')

def reduce(self, operation, app_label):
    if isinstance(operation, DeleteModel) and self.name_lower == operation.name_lower and (not self.options.get('proxy', False)):
        return []
    elif isinstance(operation, RenameModel) and self.name_lower == operation.old_name_lower:
        return [replace(self, name=operation.new_name)]
    elif isinstance(operation, AlterModelOptions) and self.name_lower == operation.name_lower:
        options = {**self.options, **operation.options}
        for key in operation.ALTER_OPTION_KEYS:
            if key not in operation.options:
                options.pop(key, None)
        return [replace(self, options=options)]
    elif isinstance(operation, AlterModelManagers) and self.name_lower == operation.name_lower:
        return [replace(self, managers=operation.managers)]
    elif <MASK>:
        return [replace(self, options={**self.options, 'db_table': operation.table})]
    elif isinstance(operation, AlterModelTableComment) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, 'db_table_comment': operation.table_comment})]
    elif isinstance(operation, AlterTogetherOptionOperation) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, **{operation.option_name: operation.option_value}})]
    elif isinstance(operation, AlterOrderWithRespectTo) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, 'order_with_respect_to': operation.order_with_respect_to})]
    elif isinstance(operation, FieldOperation) and self.name_lower == operation.model_name_lower:
        if isinstance(operation, AddField):
            return [replace(self, fields=[*self.fields, (operation.name, operation.field)])]
        elif isinstance(operation, AlterField):
            return [replace(self, fields=[(n, operation.field if n == operation.name else v) for (n, v) in self.fields])]
        elif isinstance(operation, RemoveField):
            options = self.options.copy()
            for option_name in ('unique_together', 'index_together'):
                option = options.pop(option_name, None)
                if option:
                    option = set(filter(bool, (tuple((f for f in fields if f != operation.name_lower)) for fields in option)))
                    if option:
                        options[option_name] = option
            order_with_respect_to = options.get('order_with_respect_to')
            if order_with_respect_to == operation.name_lower:
                del options['order_with_respect_to']
            return [replace(self, fields=[(n, v) for (n, v) in self.fields if n.lower() != operation.name_lower], options=options)]
        elif isinstance(operation, RenameField):
            options = self.options.copy()
            for option_name in ('unique_together', 'index_together'):
                option = options.get(option_name)
                if option:
                    options[option_name] = {tuple((operation.new_name if f == operation.old_name else f for f in fields)) for fields in option}
            order_with_respect_to = options.get('order_with_respect_to')
            if order_with_respect_to == operation.old_name:
                options['order_with_respect_to'] = operation.new_name
            return [replace(self, fields=[(operation.new_name if n == operation.old_name else n, v) for (n, v) in self.fields], options=options)]
    elif isinstance(operation, IndexOperation) and self.name_lower == operation.model_name_lower:
        if isinstance(operation, AddIndex):
            return [replace(self, options={**self.options, 'indexes': [*self.options.get('indexes', []), operation.index]})]
        elif isinstance(operation, RemoveIndex):
            options_indexes = [index for index in self.options.get('indexes', []) if index.name != operation.name]
            return [replace(self, options={**self.options, 'indexes': options_indexes})]
        elif isinstance(operation, AddConstraint):
            return [replace(self, options={**self.options, 'constraints': [*self.options.get('constraints', []), operation.constraint]})]
        elif isinstance(operation, AlterConstraint):
            options_constraints = [constraint for constraint in self.options.get('constraints', []) if constraint.name != operation.name] + [operation.constraint]
            return [replace(self, options={**self.options, 'constraints': options_constraints})]
        elif isinstance(operation, RemoveConstraint):
            options_constraints = [constraint for constraint in self.options.get('constraints', []) if constraint.name != operation.name]
            return [replace(self, options={**self.options, 'constraints': options_constraints})]
    return super().reduce(operation, app_label)

def graph_placeholder(dtype, shape, name=None):
    """Graph-only version of tf.compat.v1.placeholder(), for internal use only."""
    dtype = dtype.base_dtype
    dtype_value = attr_value_pb2.AttrValue(type=dtype.as_datatype_enum)
    if <MASK>:
        shape = tensor_shape.TensorShape(shape)
    shape = attr_value_pb2.AttrValue(shape=shape.as_proto())
    g = ops.get_default_graph()
    attrs = {'dtype': dtype_value, 'shape': shape}
    op = g._create_op_internal('Placeholder', [], [dtype], input_types=[], attrs=attrs, name=name)
    (result,) = op.outputs
    if op_callbacks.should_invoke_op_callbacks():
        callback_outputs = op_callbacks.invoke_op_callbacks('Placeholder', tuple(), attrs, tuple(op.outputs), op_name=name, graph=g)
        if callback_outputs is not None:
            (result,) = callback_outputs
    return result

def __init__(self, orig, id_set=None, _compilation_unit=None):
    super().__init__()
    assert isinstance(orig, torch.nn.Module)
    id_set = set()

    class QualnameWrapper(torch.nn.Module):
        pass
    QualnameWrapper._jit_override_qualname = torch._jit_internal._qualified_name(type(orig))
    tmp_module = QualnameWrapper()

    def check_unique(param):
        if param in id_set:
            raise ValueError("TracedModules don't support parameter sharing between modules")
        id_set.add(param)
    tmp_module.training = orig.training
    for (name, param) in orig._parameters.items():
        if param is not None:
            tmp_module._parameters[name] = param
            check_unique(param)
    for (name, buf) in orig._buffers.items():
        if buf is not None:
            tmp_module._buffers[name] = buf
            check_unique(buf)
    for (name, val) in orig.__dict__.items():
        if torch._C._jit_is_script_object(val) and name not in orig._parameters and (name not in orig._buffers):
            setattr(tmp_module, name, val)
    if orig._backward_hooks:
        raise ValueError("Modules that have backward hooks assigned can't be compiled: " + str(orig))
    for (name, submodule) in orig._modules.items():
        if <MASK>:
            continue
        tmp_module._modules[name] = make_module(submodule, TracedModule, _compilation_unit=None)
    script_module = torch.jit._recursive.create_script_module(tmp_module, lambda module: (), share_types=False, is_tracing=True)
    self.__dict__['_name'] = type(orig).__name__
    self.__dict__['_actual_script_module'] = script_module
    for name in ('_parameters', '_buffers', '_modules', 'training'):
        delattr(self, name)

def _should_disable_fastpath(self, opinfo, rightmost_arg, rightmost_arg_type, dtype):
    if self.arity == 1:
        if 'foreach_abs' in opinfo.name and dtype in complex_types():
            return True
        if <MASK>:
            return False
        if opinfo.ref_inplace == torch.Tensor.zero_:
            return False
        return dtype in integral_types_and(torch.bool)
    if self.arity < 2 or rightmost_arg_type == ForeachRightmostArgType.Tensor:
        return None
    if 'foreach_pow' in opinfo.name and dtype in integral_types_and(torch.bool):
        return True
    if any((foreach_name in opinfo.name for foreach_name in ('foreach_clamp_max', 'foreach_clamp_min', 'foreach_maximum', 'foreach_minimum'))) and dtype in integral_types_and(torch.bool):
        return True
    if rightmost_arg_type == ForeachRightmostArgType.TensorList:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if 'foreach_add' in opinfo.name and dtype == torch.bool:
            disable_fastpath = True
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.Scalar:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if isinstance(rightmost_arg, bool):
            disable_fastpath |= dtype == torch.bool
            if opinfo.ref in (torch.add, torch.mul):
                disable_fastpath = False
        elif isinstance(rightmost_arg, int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg, float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg, complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalar of type {rightmost_arg_type} - {rightmost_arg}')
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.ScalarList:
        disable_fastpath = opinfo.ref == torch.div and dtype in integral_types_and(torch.bool)
        elmt_t = type(rightmost_arg[0])
        has_same_type = all((isinstance(v, elmt_t) for v in rightmost_arg))
        if not has_same_type:
            return dtype not in complex_types()
        if isinstance(rightmost_arg[0], bool):
            if ('foreach_add' in opinfo.name or 'foreach_mul' in opinfo.name) and dtype == torch.bool:
                disable_fastpath = False
        elif isinstance(rightmost_arg[0], int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg[0], float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg[0], complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalarlist of {rightmost_arg}')
        return disable_fastpath
    else:
        raise AssertionError(f'Invalid rightmost_arg_type of {rightmost_arg_type}')

def add_var(self, symbol: sympy.Symbol, type: type) -> z3.ExprRef:
    if <MASK>:
        return self.symbols[symbol]
    log.debug('new variable: %s (%s)', symbol.name, type.__name__)
    if type is int:
        var = z3.Int(symbol.name)
        if symbol.is_positive:
            self._target_exprs.add(var > 0)
    elif type is float:
        var = z3.Real(symbol.name)
    elif type is bool:
        var = z3.Bool(symbol.name)
    else:
        raise RuntimeError(f'unsupported type for Z3 variable: {type}')
    self.symbols[symbol] = var
    return var

def __str__(self) -> str:
    parts = []
    if self.epoch != 0:
        parts.append(f'{self.epoch}!')
    parts.append('.'.join((str(x) for x in self.release)))
    if self.pre is not None:
        parts.append(''.join((str(x) for x in self.pre)))
    if self.post is not None:
        parts.append(f'.post{self.post}')
    if self.dev is not None:
        parts.append(f'.dev{self.dev}')
    if <MASK>:
        parts.append(f'+{self.local}')
    return ''.join(parts)

def __eq__(self, other):
    if <MASK>:
        return self._scalar_type == other._scalar_type
    try:
        other_instance = DType(other)
    except TypeError:
        return False
    return self._scalar_type == other_instance._scalar_type

def wrapped_func(*flat_inp):
    structured_inp = nest.pack_sequence_as(in_structure, flat_inp, expand_composites=True)
    out = func(*structured_inp)
    if <MASK>:
        return []
    if not isinstance(out, (list, tuple)):
        out = [out]
    flat_out = []
    for (elt, expected_type) in zip(out, out_structure):
        if isinstance(expected_type, type_spec.TypeSpec) and (not isinstance(expected_type, tensor_spec.TensorSpec)):
            if not expected_type.is_compatible_with(elt):
                raise ValueError(f'py_function: func={func} returned {out!r}, which did not match Tout={out_structure!r}.\nIn particular, {elt!r} is not compatible with {expected_type!r}.')
            flat_out.extend(nest.flatten(elt, expand_composites=True))
        else:
            if isinstance(elt, composite_tensor.CompositeTensor):
                raise ValueError(f'py_function: func={func} returned {out!r}, which did not match Tout={out_structure!r}.\nIn particular, {elt!r} is not a Tensor.')
            flat_out.append(elt)
    return flat_out

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName) -> NamedCType:
    r = cpp.valuetype_type(t, symint=False, binds=binds, mutable=mutable)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif <MASK>:
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, BaseCType(optionalTensorRefT))
        elif t.elem == BaseType(BaseTy.Scalar):
            return NamedCType(binds, BaseCType(optionalScalarRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
        elif t.elem == OptionalType(BaseType(BaseTy.Tensor)):
            return NamedCType(binds, BaseCType(iOptTensorListRefT))
        elif str(t.elem) == 'int':
            return NamedCType(binds, BaseCType(intArrayRefT))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

@classmethod
def eval(cls, number):
    if <MASK>:
        return int_oo
    if number in (-sympy.oo, int_oo):
        return -int_oo
    if isinstance(number, sympy.Integer):
        return number
    if isinstance(number, sympy.Number):
        return sympy.Integer(math.floor(float(number)))

