def asfreq(obj: NDFrameT, freq, method=None, how=None, normalize: bool=False, fill_value=None) -> NDFrameT:
    """
    Utility frequency conversion method for Series/DataFrame.

    See :meth:`pandas.NDFrame.asfreq` for full documentation.
    """
    if isinstance(obj.index, PeriodIndex):
        if method is not None:
            raise NotImplementedError("'method' argument is not supported")
        if how is None:
            how = 'E'
        if isinstance(freq, BaseOffset):
            if hasattr(freq, '_period_dtype_code'):
                freq = PeriodDtype(freq)._freqstr
        new_obj = obj.copy()
        new_obj.index = obj.index.asfreq(freq, how=how)
    elif len(obj.index) == 0:
        new_obj = obj.copy()
        new_obj.index = _asfreq_compat(obj.index, freq)
    else:
        unit: TimeUnit = 'ns'
        if isinstance(obj.index, DatetimeIndex):
            unit = obj.index.unit
        dti = date_range(obj.index.min(), obj.index.max(), freq=freq, unit=unit)
        dti.name = obj.index.name
        new_obj = obj.reindex(dti, method=method, fill_value=fill_value)
        if <MASK>:
            new_obj.index = new_obj.index.normalize()
    return new_obj

def get_cxx_compiler():
    if <MASK>:
        compiler = os.environ.get('CXX', 'cl')
    else:
        compiler = os.environ.get('CXX', 'c++')
    return compiler

def evaluate(self, model, x=None, y=None, batch_size=None, verbose=1, sample_weight=None, steps=None, callbacks=None, **kwargs):
    """Evaluate loop for Distribution Strategies."""
    dist_utils.validate_inputs(x, y)
    (batch_size, steps) = dist_utils.process_batch_and_step_size(model._distribution_strategy, x, batch_size, steps, ModeKeys.TEST)
    batch_size = model._validate_or_infer_batch_size(batch_size, steps, x)
    dataset = model._distribution_standardize_user_data(x, y, sample_weight=sample_weight, batch_size=batch_size, allow_partial_batch=True)
    if backend.is_tpu_strategy(model._distribution_strategy):
        steps = training_utils_v1.infer_steps_for_dataset(model, dataset, steps, steps_name='steps')
        if <MASK>:
            raise ValueError('Number of steps could not be inferred from the data, please pass the steps argument.')
        if not context.executing_eagerly():
            return experimental_tpu_test_loop(model, dataset, verbose=verbose, steps=steps, callbacks=callbacks)
    return training_arrays_v1.test_loop(model, inputs=dataset, batch_size=batch_size, verbose=verbose, steps=steps, callbacks=callbacks)

def get_flex_attn_bwd_configs(self, head_dim: int, dtype: Any) -> list[FlexBwDConfig]:
    capability = torch.cuda.get_device_capability()
    flex_attn_bwd_configs: list[FlexBwDConfig] = []
    if config.max_autotune:
        if config.max_autotune_flex_search_space == 'EXHAUSTIVE':
            return self.exhaustive_flex_attn_bwd_configs
        flex_attn_bwd_configs += self.flex_attn_bwd_autotune_configs
    (major, minor) = capability
    if <MASK>:
        capability_class = 'float32'
    elif major >= 10:
        capability_class = 'sm10x'
    elif capability == (9, 0):
        capability_class = 'sm90'
    elif major >= 8:
        capability_class = 'sm8x'
    else:
        capability_class = 'baseline'
    config_map = {'float32': lambda h: FlexBwDConfig(16, 16, 16, 16, 1, 4), 'baseline': lambda h: FlexBwDConfig(16, 16, 16, 16, 1, 4), 'sm90': lambda h: FlexBwDConfig(64, 64, 64, 64, 3, 4) if h < 64 else FlexBwDConfig(64, 128, 128, 64, 3, 8) if h <= 128 else FlexBwDConfig(64, 64, 64, 64, 2, 4), 'sm10x': lambda h: FlexBwDConfig(64, 128, 128, 64, 3, 4) if h <= 128 else FlexBwDConfig(64, 64, 64, 64, 1, 8) if h <= 192 else FlexBwDConfig(64, 64, 64, 64, 1, 4), 'sm8x': lambda h: FlexBwDConfig(32, 128, 128, 32, 3, 4) if h < 64 else FlexBwDConfig(64, 64, 64, 64, 3 if minor == 6 and h == 128 else 2, 4)}
    if head_dim <= 256:
        default_config = config_map[capability_class](head_dim)
    else:
        default_config = FlexBwDConfig(16, 16, 16, 16, 1, 4)
    if default_config not in flex_attn_bwd_configs:
        flex_attn_bwd_configs.append(default_config)
    return flex_attn_bwd_configs

def livevars_analysis(instructions: list['Instruction'], instruction: 'Instruction') -> set[Any]:
    indexof = get_indexof(instructions)
    must = ReadsWrites(set(), set(), set())
    may = ReadsWrites(set(), set(), set())

    def walk(state: ReadsWrites, start: int) -> None:
        if start in state.visited:
            return
        state.visited.add(start)
        for i in range(start, len(instructions)):
            inst = instructions[i]
            if inst.opcode in HASLOCAL or inst.opcode in HASFREE:
                if 'LOAD' in inst.opname or 'DELETE' in inst.opname:
                    if inst.argval not in must.writes:
                        state.reads.add(inst.argval)
                elif <MASK>:
                    state.writes.add(inst.argval)
                elif inst.opname == 'MAKE_CELL':
                    pass
                else:
                    raise NotImplementedError(f'unhandled {inst.opname}')
            if inst.exn_tab_entry:
                walk(may, indexof[inst.exn_tab_entry.target])
            if inst.opcode in JUMP_OPCODES:
                assert inst.target is not None
                walk(may, indexof[inst.target])
                state = may
            if inst.opcode in TERMINAL_OPCODES:
                return
    walk(must, indexof[instruction])
    return must.reads | may.reads

def __init__(self, ds_input, write=False):
    self._write = 1 if write else 0
    Driver.ensure_registered()
    if isinstance(ds_input, str) and json_regex.match(ds_input):
        ds_input = json.loads(ds_input)
    if <MASK>:
        ds_input = str(ds_input)
        if not ds_input.startswith(VSI_FILESYSTEM_PREFIX) and (not os.path.exists(ds_input)):
            raise GDALException('Unable to read raster source input "%s".' % ds_input)
        try:
            self._ptr = capi.open_ds(force_bytes(ds_input), self._write)
        except GDALException as err:
            raise GDALException('Could not open the datasource at "{}" ({}).'.format(ds_input, err))
    elif isinstance(ds_input, bytes):
        self._write = 1
        size = sys.getsizeof(ds_input)
        self._ds_input = c_buffer(ds_input)
        vsi_path = os.path.join(VSI_MEM_FILESYSTEM_BASE_PATH, str(uuid.uuid4()))
        capi.create_vsi_file_from_mem_buffer(force_bytes(vsi_path), byref(self._ds_input), size, VSI_TAKE_BUFFER_OWNERSHIP)
        try:
            self._ptr = capi.open_ds(force_bytes(vsi_path), self._write)
        except GDALException:
            capi.unlink_vsi_file(force_bytes(vsi_path))
            raise GDALException('Failed creating VSI raster from the input buffer.')
    elif isinstance(ds_input, dict):
        self._write = 1
        driver = Driver(ds_input.get('driver', 'MEM'))
        if driver.name != 'MEM' and 'name' not in ds_input:
            raise GDALException('Specify name for creation of raster with driver "{}".'.format(driver.name))
        if 'width' not in ds_input or 'height' not in ds_input:
            raise GDALException('Specify width and height attributes for JSON or dict input.')
        if 'srid' not in ds_input:
            raise GDALException('Specify srid for JSON or dict input.')
        papsz_options = []
        for (key, val) in ds_input.get('papsz_options', {}).items():
            option = '{}={}'.format(key, val)
            papsz_options.append(option.upper().encode())
        papsz_options.append(None)
        papsz_options = (c_char_p * len(papsz_options))(*papsz_options)
        self._ptr = capi.create_ds(driver._ptr, force_bytes(ds_input.get('name', '')), ds_input['width'], ds_input['height'], ds_input.get('nr_of_bands', len(ds_input.get('bands', []))), ds_input.get('datatype', 6), byref(papsz_options))
        for (i, band_input) in enumerate(ds_input.get('bands', [])):
            band = self.bands[i]
            if 'nodata_value' in band_input:
                band.nodata_value = band_input['nodata_value']
                if band.nodata_value is not None and ('data' not in band_input or 'size' in band_input or 'shape' in band_input):
                    band.data(data=(band.nodata_value,), shape=(1, 1))
            band.data(data=band_input.get('data'), size=band_input.get('size'), shape=band_input.get('shape'), offset=band_input.get('offset'))
        self.srs = ds_input.get('srid')
        if 'origin' in ds_input:
            (self.origin.x, self.origin.y) = ds_input['origin']
        if 'scale' in ds_input:
            (self.scale.x, self.scale.y) = ds_input['scale']
        if 'skew' in ds_input:
            (self.skew.x, self.skew.y) = ds_input['skew']
    elif isinstance(ds_input, c_void_p):
        self._ptr = ds_input
    else:
        raise GDALException('Invalid data source input type: "{}".'.format(type(ds_input)))

def __call__(self, *args, **kwargs):
    plot_backend = _get_plot_backend(kwargs.pop('backend', None))
    (x, y, kind, kwargs) = self._get_call_args(plot_backend.__name__, self._parent, args, kwargs)
    kind = self._kind_aliases.get(kind, kind)
    if plot_backend.__name__ != 'pandas.plotting._matplotlib':
        return plot_backend.plot(self._parent, x=x, y=y, kind=kind, **kwargs)
    if <MASK>:
        raise ValueError(f'{kind} is not a valid plot kind Valid plot kinds: {self._all_kinds}')
    data = self._parent
    if isinstance(data, ABCSeries):
        kwargs['reuse_plot'] = True
    if kind in self._dataframe_kinds:
        if isinstance(data, ABCDataFrame):
            return plot_backend.plot(data, x=x, y=y, kind=kind, **kwargs)
        else:
            raise ValueError(f'plot kind {kind} can only be used for data frames')
    elif kind in self._series_kinds:
        if isinstance(data, ABCDataFrame):
            if y is None and kwargs.get('subplots') is False:
                raise ValueError(f"{kind} requires either y column or 'subplots=True'")
            if y is not None:
                if is_integer(y) and (not holds_integer(data.columns)):
                    y = data.columns[y]
                data = data[y].copy(deep=False)
                data.index.name = y
    elif isinstance(data, ABCDataFrame):
        data_cols = data.columns
        if x is not None:
            if is_integer(x) and (not holds_integer(data.columns)):
                x = data_cols[x]
            elif not isinstance(data[x], ABCSeries):
                raise ValueError('x must be a label or position')
            data = data.set_index(x)
        if y is not None:
            int_ylist = is_list_like(y) and all((is_integer(c) for c in y))
            int_y_arg = is_integer(y) or int_ylist
            if int_y_arg and (not holds_integer(data.columns)):
                y = data_cols[y]
            label_kw = kwargs['label'] if 'label' in kwargs else False
            for kw in ['xerr', 'yerr']:
                if kw in kwargs and (isinstance(kwargs[kw], str) or is_integer(kwargs[kw])):
                    try:
                        kwargs[kw] = data[kwargs[kw]]
                    except (IndexError, KeyError, TypeError):
                        pass
            data = data[y]
            if isinstance(data, ABCSeries):
                label_name = label_kw or y
                data.name = label_name
            else:
                match = is_list_like(label_kw) and len(label_kw) == len(y)
                if label_kw and (not match):
                    raise ValueError('label should be list-like and same length as y')
                label_name = label_kw or data.columns
                data.columns = label_name
    return plot_backend.plot(data, kind=kind, **kwargs)

@torch.library.impl('debugprims::load_tensor', 'BackendSelect')
def load_tensor_factory(name: str, size: Sequence[int], stride: Sequence[int], dtype: torch.dtype, device: torch.device) -> torch.Tensor:
    if <MASK>:
        from torch._dynamo.testing import rand_strided
        return rand_strided(size, stride, dtype, device)
    else:
        from torch._dynamo.utils import clone_input
        r = LOAD_TENSOR_READER.read_tensor(name, device=device)
        assert list(r.size()) == size, f'{r.size()} != {size}'
        assert list(r.stride()) == stride, f'{r.stride()} != {stride}'
        assert r.device == device, f'{r.device} != {device}'
        if r.dtype != dtype:
            r = clone_input(r, dtype=dtype)
        return r

def _allocate(self, block: Allocation, is_last: bool):
    slot_size = self.get_size_hint()
    block_size = block.get_size_hint()
    if not is_last and block_size > slot_size:
        return False
    block_live = block.get_live_ranges()
    overlapping = [s for s in self.allocations if s.get_live_ranges().overlaps(block_live)]
    if len(overlapping) > 1:
        return False
    elif len(overlapping) == 1:
        return overlapping[0].allocate(block, is_last)
    else:
        block.mark_allocated()
        if len(self.allocations) == 1 and isinstance(self.allocations[-1], Empty):
            self.allocations.pop()
        if <MASK>:
            self.allocations.append(block)
        elif slot_size > block_size:
            self.allocations.append(SpatialSplit.create(block, slot_size - block_size))
        else:
            assert is_last
            self.allocations = [*(SpatialSplit.create(a, block_size - slot_size) for a in self.allocations), block]
        return True

def _cmp_method(self, other, op):
    if is_list_like(other):
        if len(self) != len(other):
            raise ValueError('Lengths must match to compare')
        other = pd_array(other)
    elif not isinstance(other, Interval):
        if other is NA:
            from pandas.core.arrays import BooleanArray
            arr = np.empty(self.shape, dtype=bool)
            mask = np.ones(self.shape, dtype=bool)
            return BooleanArray(arr, mask)
        return invalid_comparison(self, other, op)
    if isinstance(other, Interval):
        other_dtype = pandas_dtype('interval')
    elif not isinstance(other.dtype, CategoricalDtype):
        other_dtype = other.dtype
    else:
        other_dtype = other.categories.dtype
        if isinstance(other_dtype, IntervalDtype):
            if self.closed != other.categories.closed:
                return invalid_comparison(self, other, op)
            other = other.categories._values.take(other.codes, allow_fill=True, fill_value=other.categories._na_value)
    if isinstance(other_dtype, IntervalDtype):
        if self.closed != other.closed:
            return invalid_comparison(self, other, op)
        elif not isinstance(other, Interval):
            other = type(self)(other)
        if op is operator.eq:
            return (self._left == other.left) & (self._right == other.right)
        elif op is operator.ne:
            return (self._left != other.left) | (self._right != other.right)
        elif op is operator.gt:
            return (self._left > other.left) | (self._left == other.left) & (self._right > other.right)
        elif op is operator.ge:
            return (self == other) | (self > other)
        elif <MASK>:
            return (self._left < other.left) | (self._left == other.left) & (self._right < other.right)
        else:
            return (self == other) | (self < other)
    if not is_object_dtype(other_dtype):
        return invalid_comparison(self, other, op)
    result = np.zeros(len(self), dtype=bool)
    for (i, obj) in enumerate(other):
        try:
            result[i] = op(self[i], obj)
        except TypeError:
            if obj is NA:
                result = result.astype(object)
                result[i] = NA
            else:
                raise
    return result

def filter_op(self, op_info: InductorROCmOp):
    """
        Determines whether a given op definition is suitable for the current
        input / output of the operation that this template implements.

        Filter is based on inputs' dtype, layout and statically inferred size.

        Returns None if the op is not suitable, otherwise returns the op to be used.
        """
    (op, kBatch) = (op_info.op, op_info.kBatch)
    metas = [T.get_layout() for T in [*self.input_nodes, self.output_node]]
    X_meta = metas[0]
    W_meta = metas[1]
    Y_meta = metas[-1]
    if op.a_element_dtype != self._TORCH_DTYPE_TO_CK[X_meta.dtype]:
        return None
    if op.b_element_dtype != self._TORCH_DTYPE_TO_CK[W_meta.dtype]:
        return None
    if op.c_element_dtype != self._TORCH_DTYPE_TO_CK[Y_meta.dtype]:
        return None
    if op.a_layout != torch_layout_to_ck_layout(X_meta):
        return None
    if op.b_layout != torch_layout_to_ck_layout(W_meta):
        return None
    if op.c_layout != torch_layout_to_ck_layout(Y_meta):
        return None
    M = X_meta.size[-2]
    K = X_meta.size[-1]
    N = W_meta.size[-1]
    if is_static_int(M):
        if not self._has_padding('M', op.gemm_specialization):
            if M % op.m_per_block != 0:
                return None
    if is_static_int(N):
        if not self._has_padding('N', op.gemm_specialization):
            if N % op.n_per_block != 0:
                return None
    if is_static_int(K):
        if not self._has_padding('K', op.gemm_specialization):
            if K % op.k_per_block != 0:
                return None
            K_t = kBatch * op.k_per_block
            if K % K_t != 0:
                return None
        else:
            lcm = abs(op.a_k1 * op.b_k1) // math.gcd(op.a_k1, op.b_k1)
            K_t = kBatch * lcm
            k_read_pad_splited = math.ceil(K / K_t) * lcm
            if k_read_pad_splited * (kBatch - 1) >= K:
                return None
    a_contig_size = K if op.a_layout == 'Row' else M if op.a_layout == 'Col' else None
    if <MASK>:
        return None
    b_contig_size = N if op.b_layout == 'Row' else K if op.b_layout == 'Col' else None
    if is_static_int(b_contig_size) and b_contig_size % op.b_block_transfer_src_scalar_per_vector != 0:
        return None
    c_contig_size = N if op.c_layout == 'Row' else M if op.c_layout == 'Col' else None
    c_shuffle_block_transfer_scalar_per_vector_n_per_block = op.c_shuffle_block_transfer_scalar_per_vector_n_per_block[0] if isinstance(op.c_shuffle_block_transfer_scalar_per_vector_n_per_block, tuple) else op.c_shuffle_block_transfer_scalar_per_vector_n_per_block
    if is_static_int(c_contig_size) and c_contig_size % c_shuffle_block_transfer_scalar_per_vector_n_per_block != 0:
        return None
    if not self._check_num_k_loops(op, kBatch):
        return None
    return op

@staticmethod
def vmap(info, in_dims, x, ind, ind_inv, dim):
    (x_bdim, ind_bdim, ind_inv_bdim, _) = in_dims
    logical_dim = x.dim() if x_bdim is None else x_bdim - 1
    dim = dim if dim >= 0 else dim + logical_dim

    def expand_bdim(x, x_bdim):
        if <MASK>:
            return x.expand(info.batch_size, *x.shape)
        return x.movedim(x_bdim, 0)
    x = expand_bdim(x, x_bdim)
    ind = expand_bdim(ind, ind_bdim)
    ind_inv = expand_bdim(ind_inv, ind_inv_bdim)
    return (NumpyTake.apply(x, ind, ind_inv, dim + 1), 0)

def forward(self, input):
    for (i, module) in enumerate(self):
        input = module(input)
        if <MASK>:
            pipe_split()
    return input

def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    key = com.apply_if_callable(key, self)
    if <MASK>:
        return self.copy(deep=False)
    key_is_scalar = is_scalar(key)
    if isinstance(key, (list, tuple)):
        key = unpack_1tuple(key)
    elif key_is_scalar:
        return self._get_value(key)
    if is_iterator(key):
        key = list(key)
    if is_hashable(key) and (not isinstance(key, slice)):
        try:
            result = self._get_value(key)
            return result
        except (KeyError, TypeError, InvalidIndexError):
            if isinstance(key, tuple) and isinstance(self.index, MultiIndex):
                return self._get_values_tuple(key)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    if com.is_bool_indexer(key):
        key = check_bool_indexer(self.index, key)
        key = np.asarray(key, dtype=bool)
        return self._get_rows_with_mask(key)
    return self._get_with(key)

def _normalize_backend_override(backend_override: dict[Union[int, str], Union[str, C10dBackend.Options, tuple[str, C10dBackend.Options]]], ndim: int, mesh_dim_names: Optional[tuple[str, ...]]=None) -> Iterator[BackendConfig]:
    if mesh_dim_names is None:
        mesh_dim_names = ()
    for (dim_idx, dim_name) in zip_longest(range(ndim), mesh_dim_names):
        if <MASK>:
            if dim_idx in backend_override:
                raise RuntimeError(f'Found redundant dim index {dim_idx} and name {dim_name} in backend_override')
            val = backend_override.pop(dim_name)
        elif dim_idx in backend_override:
            val = backend_override.pop(dim_idx)
        else:
            yield (None, None)
            continue
        if isinstance(val, str):
            yield (val, None)
        elif isinstance(val, C10dBackend.Options):
            yield (None, val)
        else:
            yield val
    if backend_override:
        raise RuntimeError(f'Found invalid keys in backend_override: got {list(backend_override.keys())}, expected integers in range [0, {ndim}) or one of {mesh_dim_names}')

@classmethod
def _wrap_iter_in_set(cls, other: Any) -> Any:
    """
        Wrap non-Set Iterables in OrderedSets

        Some of the magic methods are more strict on input types than
        the public apis, so we need to wrap inputs in sets.
        """
    if <MASK>:
        return cls(other)
    else:
        return other

@convert_phase(Component.OPTIMIZE_TFLITE_MODEL)
def _optimize_tflite_model(self, model, quant_mode, debug_options, quant_io=True):
    """Apply optimizations on a TFLite model."""
    if <MASK>:
        (in_type, out_type) = (self.inference_input_type, self.inference_output_type)
        if quant_mode.is_post_training_integer_quantization():
            q_in_type = in_type if in_type and quant_io else _dtypes.float32
            q_out_type = out_type if out_type and quant_io else _dtypes.float32
            q_activations_type = quant_mode.activations_type()
            q_bias_type = quant_mode.bias_type()
            q_allow_float = quant_mode.is_allow_float()
            q_variable_quantization = quant_mode.enable_mlir_variable_quantization
            model = self._quantize(model, q_in_type, q_out_type, q_activations_type, q_bias_type, q_allow_float, q_variable_quantization, debug_options)
        m_in_type = in_type if in_type else _dtypes.float32
        m_out_type = out_type if out_type else _dtypes.float32
        if not (quant_mode.is_post_training_integer_quantization() and self.experimental_new_quantizer and quant_io and (m_in_type in [_dtypes.int8, _dtypes.uint8, _dtypes.float32]) and (m_out_type in [_dtypes.int8, _dtypes.uint8, _dtypes.float32])):
            model = _modify_model_io_type(model, m_in_type, m_out_type)
    if self._sparsify_model():
        model = _mlir_sparsify(model)
    if not self._experimental_use_buffer_offset:
        try:
            model_object = flatbuffer_utils.convert_bytearray_to_object(model)
            if _check_model_use_buffer_offset(model_object):
                return model
            model = _deduplicate_readonly_buffers(model)
        except Exception:
            logging.warning('Buffer deduplication procedure will be skipped when flatbuffer library is not properly loaded')
    return model

def __setattr__(self, name, value):
    if name == '_wrapped':
