    elif mem_format_encoding == _MEM_FORMAT_ENCODING.TORCH_PRESERVE_FORMAT:
        memory_format = torch.preserve_format
    else:
        raise RuntimeError(f'Invalid torch.memory_format encoding: {mem_format_encoding}')
    self.memory_format = memory_format

def main(output_file=DEFAULT_OUTPUT_FILE, only_model=None):
    results = []
    if not only_model:
        experiments = all_experiments.values()
    else:
        if <MASK>:
            print(f'Unknown model: {only_model}, all available models: {all_experiments.keys()}')
        experiments = [all_experiments[only_model]]
    for func in experiments:
        try:
            device = 'cuda' if torch.cuda.is_available() else 'cpu'
        except AssertionError:
            device = 'cpu'
        torch.compiler.cudagraph_mark_step_begin()
        lst = func(device)
        for x in lst:
            results.append(dataclasses.astuple(x))
    headers = [field.name for field in dataclasses.fields(Experiment)]
    for row in results:
        output_csv(output_file, headers, row)
        output_json(output_file, headers, row)

def sample_inputs_searchsorted(op_info, device, dtype, requires_grad, **kwargs):
    make_arg = partial(make_tensor, dtype=dtype, device=device, requires_grad=requires_grad)
    sizes = (((0,), ((0,),), False), ((M,), ((), (M,), (M, M)), False), ((0, 0), ((0, 0),), False), ((M, M), ((M, M),), False), ((0, 0, 0), ((0, 0, 0),), False), ((M, M, M), ((M, M, M),), False), ((L,), ((),), True))
    for ((size, input_sizes, is_scalar), noncontiguous, out_int32, right) in product(sizes, [False, True], [False, True], [False, True]):
        unsorted_tensor = make_arg(size, noncontiguous=noncontiguous)
        for input_size in input_sizes:
            input = make_arg(input_size, noncontiguous=noncontiguous)
            if is_scalar:
                input = input.item()
            if <MASK>:
                boundary_tensor = unsorted_tensor
                sorter = make_tensor(size, dtype=torch.int64, device=device, noncontiguous=noncontiguous)
            else:
                (boundary_tensor, sorter) = torch.sort(unsorted_tensor)
            side = 'right' if right else 'left'
            yield SampleInput(boundary_tensor, input, out_int32=out_int32, right=right)
            yield SampleInput(boundary_tensor, input, out_int32=out_int32, side=side)
            yield SampleInput(unsorted_tensor, input, out_int32=out_int32, right=right, sorter=sorter)
            yield SampleInput(unsorted_tensor, input, out_int32=out_int32, side=side, sorter=sorter)

def _get_time_stamp(self) -> str:
    if self._format_version >= 118:
        strlen = self._read_int8()
        return self._path_or_buf.read(strlen).decode('utf-8')
    elif self._format_version == 117:
        strlen = self._read_int8()
        return self._decode(self._path_or_buf.read(strlen))
    elif <MASK>:
        return self._decode(self._path_or_buf.read(18))
    else:
        raise ValueError

def array(obj, dtype=None, *, copy=True, order='K', subok=False, ndmin=0, like=None):
    if subok is not False:
        raise NotImplementedError("'subok' parameter is not supported.")
    if like is not None:
        raise NotImplementedError("'like' parameter is not supported.")
    if order != 'K':
        raise NotImplementedError
    if isinstance(obj, ndarray) and copy is False and (dtype is None) and (ndmin <= obj.ndim):
        return obj
    if isinstance(obj, (list, tuple)):
        if obj and all((isinstance(x, torch.Tensor) for x in obj)):
            obj = torch.stack(obj)
        else:
            obj = _tolist(obj)
    if isinstance(obj, ndarray):
        obj = obj.tensor
