@custom_gradient
def inner(*args, **kwargs):
    """Inner function closure for calculating gradients."""
    current_var_scope = variable_scope.get_variable_scope()
    with record.stop_recording():
        result = f(*args, **kwargs)

    def grad_wrapper(*wrapper_args, variables=None):
        """Wrapper function to accomodate lack of kwargs in graph mode custom_gradient."""

        @custom_gradient
        def inner_recompute_grad(*dresult):
            """Nested custom gradient function for computing grads in reverse and forward mode autodiff."""
            with backprop.GradientTape() as t:
                id_args = nest.map_structure(gen_array_ops.identity, args)
                assert len(dresult) >= 1
                if <MASK>:
                    elem = math_ops.reduce_max(array_ops.reshape(dresult[0], [-1])[:1])
                    elem_bool = math_ops.cast(elem, dtypes.bool)
                    dresult_dep = array_ops.where_v2(elem_bool == elem_bool, 0.0, float('nan'))
                    id_args = nest.map_structure(lambda x: x + math_ops.cast(dresult_dep, x.dtype), id_args)
                t.watch(id_args)
                if variables is not None:
                    t.watch(variables)
                with variable_scope.variable_scope(current_var_scope):
                    recomputed_result = f(*id_args, **kwargs)
            kw_vars = []
            if variables is not None:
                kw_vars = list(variables)
            grads = t.gradient(recomputed_result, list(id_args) + kw_vars, output_gradients=dresult, unconnected_gradients=UnconnectedGradients.ZERO)

            def transpose(*t_args, **t_kwargs):
                """Gradient function calculation for forward mode autodiff."""
                raise NotImplementedError('recompute_grad tried to transpose grad of {}. Consider not using recompute_grad in forward modeautodiff'.format(f.__name__))
            return ((grads[:len(id_args)], grads[len(id_args):]), transpose)
        return inner_recompute_grad(*wrapper_args)
    return (result, grad_wrapper)

def is_unstable(check: JobCheckState, drci_classifications: Any) -> bool:
    if not check or not drci_classifications:
        return False
    name = check.name
    job_id = check.job_id
    if <MASK>:
        return True
    return any((name == unstable['name'] or (job_id and job_id == unstable['id']) for unstable in drci_classifications.get('UNSTABLE', [])))

def summarize_range(self, start: int, end: int) -> T:
    """
        Query a range of values in the segment tree.

        Args:
            start: Start index of the range to query (inclusive)
            end: End index of the range to query (inclusive)

        Returns:
            Summary value for the range according to the summary operation

        Raises:
            ValueError: If start > end or indices are out of bounds
        """
    if start > end:
        raise ValueError('Start index must be less than or equal to end index')
    if start < 0 or start >= self.n:
        raise ValueError(f'Start index {start} out of bounds [0, {self.n - 1}]')
    if <MASK>:
        raise ValueError(f'End index {end} out of bounds [0, {self.n - 1}]')
    return self._query_range_helper(1, 0, self.n - 1, start, end)

def _align_frame(self, indexer, df: DataFrame) -> DataFrame:
    is_frame = self.ndim == 2
    if isinstance(indexer, tuple):
        (idx, cols) = (None, None)
        sindexers = []
        for (i, ix) in enumerate(indexer):
            ax = self.obj.axes[i]
            if is_sequence(ix) or isinstance(ix, slice):
                if isinstance(ix, np.ndarray):
                    ix = ix.reshape(-1)
                if idx is None:
                    idx = ax[ix]
                elif cols is None:
                    cols = ax[ix]
                else:
                    break
            else:
                sindexers.append(i)
        if idx is not None and cols is not None:
            if df.index.equals(idx) and df.columns.equals(cols):
                val = df.copy()
            else:
                val = df.reindex(idx, columns=cols)
            return val
    elif (isinstance(indexer, slice) or is_list_like_indexer(indexer)) and is_frame:
        ax = self.obj.index[indexer]
        if df.index.equals(ax):
            val = df.copy()
        else:
            if <MASK>:
                raise TypeError('cannot align on a multi-index with out specifying the join levels')
            val = df.reindex(index=ax)
        return val
    raise ValueError('Incompatible indexer with DataFrame')

def update_op(self, optimizer, g):
    if isinstance(g, indexed_slices.IndexedSlices):
        if <MASK>:
            raise RuntimeError('Cannot use a constraint function on a sparse variable.')
        return optimizer._resource_apply_sparse_duplicate_indices(g.values, self._v, g.indices)
    if context.xla_sharding_for_resource_variables_enabled():
        assign_ops = []
        for variable_dict in optimizer._slots.values():
            for slot_var in variable_dict.values():
                if isinstance(slot_var, resource_variable_ops.BaseResourceVariable) and slot_var._get_xla_sharding() is not None:
                    assign_ops.append(slot_var.assign(slot_var.read_value()))
        with ops.control_dependencies(assign_ops):
            update_op = optimizer._resource_apply_dense(g, self._v)
    else:
        update_op = optimizer._resource_apply_dense(g, self._v)
    if self._v.constraint is not None:
        with ops.control_dependencies([update_op]):
            return self._v.assign(self._v.constraint(self._v))
    else:
        return update_op

@classmethod
def _from_proto(cls, pb):
    """Convert proto to enum."""
    if pb == dataset_options_pb2.AutoShardPolicy.OFF:
        return cls.OFF
    if pb == dataset_options_pb2.AutoShardPolicy.FILE:
        return cls.FILE
    if pb == dataset_options_pb2.AutoShardPolicy.DATA:
        return cls.DATA
    if <MASK>:
        return cls.AUTO
    if pb == dataset_options_pb2.AutoShardPolicy.HINT:
        return cls.HINT
    raise ValueError(f'Invalid `pb.` Supported values include `OFF`, `FILE`, `DATA`,`AUTO`, and `HINT`. Got {pb}.')

def _unflatten_orig_param_states(fsdp_param_info: FSDPParamInfo, output_states: dict[str, dict[str, Any]], state_name: str, shard_state: bool, to_save: bool, cpu_offload: bool) -> None:
    """
    Given a output state dict, ``output_states``, which the keys are FQNs to the
    original parameters (not FlatParameters nor parameter ID), and the values
    are gathered states, unflatten the states to the original dimensions.

    This function performs the unflattening process in-place.
    """
    if not to_save:
        return
    flat_param = fsdp_param_info.handle.flat_param
    fsdp_state = fsdp_param_info.state
    for (fqn, gathered_state) in output_states.items():
        value = gathered_state[state_name]
        param_idx = fsdp_param_info.param_indices[fqn]
        if isinstance(value, DTensor):
            placement = value.placements[0]
            if placement != Replicate():
                placement_dim = placement.dim
                value.redistribute(placements=(Replicate(),))
                reshape_size = list(flat_param._shapes[param_idx])
                reshape_size[placement_dim] *= value.device_mesh.size(0)
                reshape_size = torch.Size(reshape_size)
                value = value.reshape(reshape_size)
            else:
                value = value.reshape(flat_param._shapes[param_idx])
        else:
            value = value.reshape(flat_param._shapes[param_idx])
        if <MASK>:
            osd_config = fsdp_state._optim_state_dict_config
            if getattr(osd_config, '_use_dtensor', False):
                if fsdp_state._device_mesh is None:
                    raise AssertionError(f'Expected _device_mesh to be not None, got {fsdp_state._device_mesh}')
                value = _ext_chunk_dtensor(value, fsdp_state.rank, fsdp_state._device_mesh, fsdp_state._fsdp_extension)
            else:
                if fsdp_state.process_group is None:
                    raise AssertionError(f'Expected process_group to be not None, got {fsdp_state.process_group}')
                value = _ext_chunk_tensor(value, fsdp_state.rank, fsdp_state.world_size, fsdp_state._device_handle.device_count(), fsdp_state.process_group, fsdp_state._fsdp_extension)
        elif not cpu_offload:
            with SimpleProfiler.profile('clone'):
                value = value.detach().clone()
        if cpu_offload:
            with SimpleProfiler.profile(SimpleProfiler.Type.D2H):
                value = value.cpu()
        gathered_state[state_name] = value

@classmethod
def _check_long_column_names(cls, databases):
    """
        Check that any auto-generated column names are shorter than the limits
        for each database in which the model will be created.
        """
    if not databases:
        return []
    errors = []
    allowed_len = None
    db_alias = None
    for db in databases:
        if not router.allow_migrate_model(db, cls):
            continue
        connection = connections[db]
        max_name_length = connection.ops.max_name_length()
        if max_name_length is None or connection.features.truncates_names:
            continue
        elif allowed_len is None:
            allowed_len = max_name_length
            db_alias = db
        elif max_name_length < allowed_len:
            allowed_len = max_name_length
            db_alias = db
    if allowed_len is None:
        return errors
    for f in cls._meta.local_fields:
        if <MASK>:
            errors.append(checks.Error('Autogenerated column name too long for field "%s". Maximum length is "%s" for database "%s".' % (column_name, allowed_len, db_alias), hint="Set the column name manually using 'db_column'.", obj=cls, id='models.E018'))
    for f in cls._meta.local_many_to_many:
        if isinstance(f.remote_field.through, str):
            continue
        for m2m in f.remote_field.through._meta.local_fields:
            if m2m.db_column is None and (rel_name := m2m.column) is not None and (len(rel_name) > allowed_len):
                errors.append(checks.Error('Autogenerated column name too long for M2M field "%s". Maximum length is "%s" for database "%s".' % (rel_name, allowed_len, db_alias), hint="Use 'through' to create a separate model for M2M and then set column_name using 'db_column'.", obj=cls, id='models.E019'))
    return errors

@generic_utils.default
def build(self, input_shape):
    """Builds the model based on input shapes received.

    This is to be used for subclassed models, which do not know at instantiation
    time what their inputs look like.

    This method only exists for users who want to call `model.build()` in a
    standalone way (as a substitute for calling the model on real data to
    build it). It will never be called by the framework (and thus it will
    never throw unexpected errors in an unrelated workflow).

    Args:
     input_shape: Single tuple, TensorShape, or list/dict of shapes, where
         shapes are tuples, integers, or TensorShapes.

    Raises:
      ValueError:
        1. In case of invalid user-provided data (not of type tuple,
           list, TensorShape, or dict).
        2. If the model requires call arguments that are agnostic
           to the input shapes (positional or kwarg in call signature).
        3. If not all layers were properly built.
        4. If float type inputs are not supported within the layers.

      In each of these cases, the user should build their model by calling it
      on real tensor data.
    """
    if self._is_graph_network:
        super(Model, self).build(input_shape)
        return
    if input_shape is None:
        raise ValueError('Input shape must be defined when calling build on a model subclass network.')
    valid_types = (tuple, list, tensor_shape.TensorShape, dict)
    if not isinstance(input_shape, valid_types):
        raise ValueError('Specified input shape is not one of the valid types. Please specify a batch input shape of type tuple or list of input shapes. User provided input type: {}'.format(type(input_shape)))
    if input_shape and (not self.inputs):
        if context.executing_eagerly():
            graph = func_graph.FuncGraph('build_graph')
        else:
            graph = backend.get_graph()
        with graph.as_default():
            if <MASK>:
                input_shape = tuple(input_shape)
            if isinstance(input_shape, list):
                x = [base_layer_utils.generate_placeholders_from_shape(shape) for shape in input_shape]
            elif isinstance(input_shape, dict):
                x = {k: base_layer_utils.generate_placeholders_from_shape(shape) for (k, shape) in input_shape.items()}
            else:
                x = base_layer_utils.generate_placeholders_from_shape(input_shape)
            kwargs = {}
            call_signature = self._call_full_argspec
            call_args = call_signature.args
            if len(call_args) > 2:
                if call_signature.defaults:
                    call_args = call_args[2:-len(call_signature.defaults)]
                else:
                    call_args = call_args[2:]
                for arg in call_args:
                    if arg == 'training':
                        kwargs['training'] = False
                    else:
                        raise ValueError('Currently, you cannot build your model if it has positional or keyword arguments that are not inputs to the model, but are required for its `call` method. Instead, in order to instantiate and build your model, `call` your model on real tensor data with all expected call arguments.')
            elif len(call_args) < 2:
                raise ValueError('You can only call `build` on a model if its `call` method accepts an `inputs` argument.')
            try:
                self.call(x, **kwargs)
            except (errors.InvalidArgumentError, TypeError):
                raise ValueError('You cannot build your model by calling `build` if your layers do not support float type inputs. Instead, in order to instantiate and build your model, `call` your model on real tensor data (of the correct dtype).')
    super(Model, self).build(input_shape)

def alloc_with_matching_layout(query: Tensor, res_shape: tuple[int, ...]):
    if <MASK>:
        query_t = query.transpose(1, 2)
        res = torch.empty_like(query_t).transpose(1, 2)
    else:
        dim_order = sorted([0, 1, 2, 3], key=lambda idx: query.stride()[idx], reverse=True)
        permuted_shape = [res_shape[idx] for idx in dim_order]
        final_permute = [dim_order.index(i) for i in range(len(dim_order))]
        res = torch.empty(permuted_shape, dtype=query.dtype, device=query.device).permute(final_permute)
    return res

def transform_load_stream(self, read_item: ReadItem, transform_descriptors: Sequence[str], raw_stream: IO[bytes]) -> IO[bytes]:
    extensions = self.extension_registry.from_descriptor_list(transform_descriptors)
    transform_from = raw_stream
    for ex in extensions:
        if <MASK>:
            transform_from = ex.transform_from(transform_from)
    return transform_from

@classmethod
def process_subsystem(cls, curr_backend: str, curr_subsystem: Subsystem, fn: Callable[[], bool], cli_interface: bool=True) -> bool:
    """
        Process the current subsystem. Returns True if the issue is found, False otherwise.
        """
    assert isinstance(curr_subsystem, Subsystem)
    while True:
        run_state = cls.get_run_state(curr_backend, curr_subsystem.name)
        reset_counters()
        if run_state == 'test_disable':
            if not fn():
                next_subsystem = cls.advance_subsystem(curr_backend, curr_subsystem)
                if not next_subsystem:
                    return False
                curr_subsystem = next_subsystem
            else:
                if isinstance(curr_subsystem, ConfigChange):
                    print(f'Setting config {curr_subsystem.config_name} field {curr_subsystem.config_field} to {curr_subsystem.config_value} fixed the issue')
                else:
                    print(f'Disabling {curr_subsystem.name} fixed the issue.')
                if <MASK>:
                    return True
                print('Starting bisect by getting upper bound.')
                cls.update_run_state(curr_backend, curr_subsystem, 'find_max_bounds')
        elif run_state == 'find_max_bounds':
            if fn():
                raise RuntimeError(f"Function succeeded with 'find_max_bounds' status for {curr_backend} - {curr_subsystem.name}.")
            else:
                (_, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
                print(f'Upper bound of {high} found for {curr_backend}.')
                cls.update_run_state(curr_backend, curr_subsystem, 'bisect')
        elif run_state == 'bisect':
            (low, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
            midpoint = (low + high) // 2
            print(f'Bisecting {curr_backend} - {curr_subsystem.name} (Range: [{low}, {high}], Midpoint: {midpoint})')
            if fn():
                cls.update_bisect_range(curr_backend, curr_subsystem.name, midpoint + 1, high)
            else:
                cls.update_bisect_range(curr_backend, curr_subsystem.name, low, midpoint)
            (low, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
            if low == high:
                print(f"Binary search completed for {curr_backend} - {curr_subsystem.name}. The bisect number is {low}. Debug info: {call_counter_debug_info.get(low, 'not found')}")
                return True
        else:
            raise RuntimeError(f'Unexpected run_state {run_state}')
        if cli_interface:
            sys.exit(0)

def decorator(f):

    @wraps(f)
    def wrapper(*args, **kwargs):
        retry_counter = n_retries
        while True:
            try:
                return f(*args, **kwargs)
            except (URLError, TimeoutError) as e:
                if <MASK>:
                    raise
                if retry_counter == 0:
                    raise
                warn(f'A network error occurred while downloading {url}. Retrying...')
                if isinstance(e, HTTPError):
                    e.close()
                retry_counter -= 1
                time.sleep(delay)
    return wrapper

def as_shape(shape):
    """Converts the given object to a TensorShape."""
    if <MASK>:
        return shape
    else:
        return tensor_shape.TensorShape(shape)

def __getitem__(self, key: PositionalIndexer | tuple[int | EllipsisType, ...]) -> Self | Any:
    if isinstance(key, tuple):
        key = unpack_tuple_and_ellipses(key)
        if key is ...:
            raise ValueError('Cannot slice with Ellipsis')
    if is_integer(key):
        return self._get_val_at(key)
    elif isinstance(key, tuple):
        data_slice = self.to_dense()[key]
    elif isinstance(key, slice):
        if key.step is None or key.step == 1:
            start = 0 if key.start is None else key.start
            if start < 0:
                start += len(self)
            end = len(self) if key.stop is None else key.stop
            if end < 0:
                end += len(self)
            indices = self.sp_index.indices
            keep_inds = np.flatnonzero((indices >= start) & (indices < end))
            sp_vals = self.sp_values[keep_inds]
            sp_index = indices[keep_inds].copy()
            if start > 0:
                sp_index -= start
            new_len = len(range(len(self))[key])
            new_sp_index = make_sparse_index(new_len, sp_index, self.kind)
            return type(self)._simple_new(sp_vals, new_sp_index, self.dtype)
        else:
            indices = np.arange(len(self), dtype=np.int32)[key]
            return self.take(indices)
    elif not is_list_like(key):
        raise IndexError('only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) and integer or boolean arrays are valid indices')
    else:
        if isinstance(key, SparseArray):
            if is_bool_dtype(key):
                if isna(key.fill_value):
                    return self.take(key.sp_index.indices[key.sp_values])
                if not key.fill_value:
                    return self.take(key.sp_index.indices)
                n = len(self)
                mask = np.full(n, True, dtype=np.bool_)
                mask[key.sp_index.indices] = False
                return self.take(np.arange(n)[mask])
            else:
                key = np.asarray(key)
        key = check_array_indexer(self, key)
        if com.is_bool_indexer(key):
            key = cast(np.ndarray, key)
            return self.take(np.arange(len(key), dtype=np.int32)[key])
        elif <MASK>:
            return self.take(key)
        else:
            raise ValueError(f"Cannot slice with '{key}'")
    return type(self)(data_slice, kind=self.kind)

@_onnx_symbolic('aten::as_strided')
@symbolic_helper.quantized_args(True)
@symbolic_helper.parse_args('v', 'v', 'is', 'i')
def as_strided(g: jit_utils.GraphContext, self, sizes, strides, offset=None):
    sizes = symbolic_helper._maybe_get_const(sizes, 'is')
    rank = len(strides)
    self_1d = symbolic_helper._reshape_helper(g, self, g.op('Constant', value_t=torch.tensor([-1], dtype=torch.int64)))
    ind: torch.Tensor | None
    if not symbolic_helper._is_value(sizes):
        ind = torch.tensor([0], dtype=torch.long)
        for (i, (size, stride)) in enumerate(zip(sizes, strides)):
            r_size = [1] * rank
            r_size[i] = -1
            ind = ind + torch.arange(size).view(r_size) * stride
        if <MASK>:
            ind = ind + offset
        return g.op('Gather', self_1d, g.op('Constant', value_t=ind))
    else:
        ind = None
        for (i, stride) in enumerate(strides):
            r_size = [1] * rank
            r_size[i] = -1
            size = select(g, sizes, g.op('Constant', value_t=torch.tensor([0])), g.op('Constant', value_t=torch.tensor(i)))
            tmp_ind = symbolic_helper._reshape_helper(g, arange(g, size, 4, None, None, None), g.op('Constant', value_t=torch.tensor(r_size)))
            tmp_ind = g.op('Mul', tmp_ind, g.op('Constant', value_t=torch.tensor([stride])))
            if ind is None:
                ind = tmp_ind
            else:
                ind = g.op('Add', ind, tmp_ind)
        if offset:
            ind = g.op('Add', ind, g.op('Constant', torch.tensor([offset])))
        return g.op('Gather', self_1d, ind)

def _true_getter(name, shape=None, dtype=dtypes.float32, initializer=None, regularizer=None, reuse=None, trainable=None, collections=None, caching_device=None, partitioner=None, validate_shape=True, use_resource=None, constraint=None, synchronization=vs.VariableSynchronization.AUTO, aggregation=vs.VariableAggregation.NONE):
    if <MASK>:
        raise ValueError('`partitioner` arg for `get_variable` is unsupported in TF2.File a bug if you need help. You passed %s' % partitioner)
    if '%s/part_0' % name in self._vars:
        raise ValueError('No partitioner was provided, but a partitioned version of the variable was found: %s/part_0. Perhaps a variable of the same name was already created with partitioning?' % name)
    return self._get_single_variable(name=name, shape=shape, dtype=dtype, initializer=initializer, regularizer=regularizer, reuse=reuse, trainable=trainable, caching_device=caching_device, validate_shape=validate_shape, constraint=constraint, synchronization=synchronization, aggregation=aggregation)

def create_index(self, columns=None, optlevel=None, kind: str | None=None) -> None:
    """
        Create a pytables index on the specified columns.

        Parameters
        ----------
        columns : None, bool, or listlike[str]
            Indicate which columns to create an index on.

            * False : Do not create any indexes.
            * True : Create indexes on all columns.
            * None : Create indexes on all columns.
            * listlike : Create indexes on the given columns.

        optlevel : int or None, default None
            Optimization level, if None, pytables defaults to 6.
        kind : str or None, default None
            Kind of index, if None, pytables defaults to "medium".

        Raises
        ------
        TypeError if trying to create an index on a complex-type column.

        Notes
        -----
        Cannot index Time64Col or ComplexCol.
        Pytables must be >= 3.0.
        """
    if not self.infer_axes():
        return
    if columns is False:
        return
    if columns is None or columns is True:
        columns = [a.cname for a in self.axes if a.is_data_indexable]
    if not isinstance(columns, (tuple, list)):
        columns = [columns]
    kw = {}
    if optlevel is not None:
        kw['optlevel'] = optlevel
    if kind is not None:
        kw['kind'] = kind
    table = self.table
    for c in columns:
        v = getattr(table.cols, c, None)
        if v is not None:
            if v.is_indexed:
                index = v.index
                cur_optlevel = index.optlevel
                cur_kind = index.kind
                if kind is not None and cur_kind != kind:
                    v.remove_index()
                else:
                    kw['kind'] = cur_kind
                if optlevel is not None and cur_optlevel != optlevel:
                    v.remove_index()
                else:
                    kw['optlevel'] = cur_optlevel
            if <MASK>:
                if v.type.startswith('complex'):
                    raise TypeError('Columns containing complex values can be stored but cannot be indexed when using table format. Either use fixed format, set index=False, or do not include the columns containing complex values to data_columns when initializing the table.')
                v.create_index(**kw)
        elif c in self.non_index_axes[0][1]:
            raise AttributeError(f'column {c} is not a data_column.\nIn order to read column {c} you must reload the dataframe \ninto HDFStore and include {c} with the data_columns argument.')

def resolve(self, args):
    n = len(args)
    for signature in self.ordering:
        if len(signature) != n:
            continue
        s = unify(freeze(args), signature)
        if <MASK>:
            result = self.funcs[signature]
            return (result, s)
    raise NotImplementedError('No match found. \nKnown matches: ' + str(self.ordering) + '\nInput: ' + str(args))

@_onnx_symbolic('aten::unsafe_chunk')
@symbolic_helper.parse_args('v', 'i', 'i', 'i')
def unsafe_chunk(g: jit_utils.GraphContext, self, chunks, dim, _outputs=None):
    if _outputs is None:
        return symbolic_helper._onnx_opset_unsupported_detailed('unsafe_chunk', 9, 11, 'Dynamic number of outputs not supported', self)
    size = symbolic_helper._get_tensor_dim_size(self, dim)
    if size is None:
        return symbolic_helper._unimplemented('unsafe_chunk', 'unknown dimension size', self)
    split_size = (size + chunks - 1) // chunks
    splits = [split_size] * (size // split_size)
    leftover = size % split_size
    if <MASK>:
        splits.append(leftover)
    return g.op('Split', self, split_i=splits, axis_i=dim, outputs=_outputs)

def sample_inputs_unflatten(op_info, device, dtype, requires_grad, **kwargs):
    for sample_input in sample_inputs_unary_dimwise(op_info, device, dtype, requires_grad, **kwargs):
        if <MASK>:
            continue
        D = sample_input.input.size(sample_input.kwargs['dim'])
        yield _update_sample(sample_input, {'sizes': [D, 1]})
        yield _update_sample(sample_input, {'sizes': [1, D]})
        if D % 2 == 0:
            yield _update_sample(sample_input, {'sizes': [D // 2, 2]})
            yield _update_sample(sample_input, {'sizes': [2, D // 2]})

def check_forward_ad_formula(op: Callable, args, kwargs, gradcheck_wrapper=None, assert_equal_fn=None):
    (CCT, cct_mode) = generate_cct_and_mode(autograd_view_consistency=False)

    def maybe_tangent(t):
        assert type(t) is not CCT
        if isinstance(t, torch.Tensor) and t.requires_grad:
            return torch.randn_like(t)
        elif is_tensorlist(t):
            return [torch.randn_like(e) if e.requires_grad else None for e in t]
        return None
    tangent_args = tuple((maybe_tangent(arg) for arg in args))
    (flat_kwargs, spec) = tree_flatten(kwargs)
    flat_tangent_kwargs = tuple((maybe_tangent(arg) for arg in flat_kwargs))
    tangent_kwargs = tree_unflatten(flat_tangent_kwargs, spec)
    with fwAD.dual_level():

        def maybe_make_dual(dual):
            (primal, tangent) = dual
            if isinstance(primal, torch.Tensor) and primal.requires_grad:
                return fwAD.make_dual(primal.detach(), tangent)
            elif is_tensorlist(primal):
                return tuple((fwAD.make_dual(pri.detach(), tang) if tang is not None else pri for (pri, tang) in zip(primal, tangent, strict=True)))
            return primal

        def compute_expected_grad(args, tangent_args, kwargs, tangent_kwargs):
            op_args = tuple(map(maybe_make_dual, zip(args, tangent_args, strict=True)))
            op_kwargs = {k: maybe_make_dual((v, tangent_kwargs[k])) for (k, v) in kwargs.items()}
            if <MASK>:
                return op(*op_args, **op_kwargs)
            return gradcheck_wrapper(op, *op_args, **op_kwargs)
        expected = compute_expected_grad(args, tangent_args, kwargs, tangent_kwargs)
        expected = tree_map(fwAD.unpack_dual, expected)
        expected_primals = tree_map(lambda x: x.primal, expected, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
        expected_tangents = tree_map(lambda x: x.tangent, expected, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
        for choice in generate_subclass_choices_args_kwargs(args, kwargs, CCT, cct_mode):
            (new_args, new_kwargs, which_args_are_wrapped, which_kwargs_are_wrapped) = choice
            for tang_choice in generate_subclass_choices_args_kwargs(tangent_args, tangent_kwargs, CCT, cct_mode):
                (new_tang_args, new_tang_kwargs, which_tang_args_are_wrapped, which_tang_kwargs_are_wrapped) = tang_choice
                op_args = tuple(map(maybe_make_dual, zip(new_args, new_tang_args, strict=True)))
                op_kwargs = {k: maybe_make_dual((v, new_tang_kwargs[k])) for (k, v) in new_kwargs.items()}
                try:
                    if gradcheck_wrapper is None:
                        actual = op(*op_args, **op_kwargs)
                    else:
                        actual = gradcheck_wrapper(op, *op_args, **op_kwargs)
                except RuntimeError as err:
                    raise_composite_compliance_error(err, f'- wrapped_args: {which_args_are_wrapped}\n- wrapped_kwargs: {which_kwargs_are_wrapped}\n- wrapped_tangent_args: {which_tang_args_are_wrapped}\n- wrapped_tangent_kwargs: {which_tang_kwargs_are_wrapped}\n')

                def unwrap(e):
                    return e.elem if isinstance(e, CCT) else e
                actual = tree_map(fwAD.unpack_dual, actual)
                actual_primals = tree_map(lambda x: unwrap(x.primal), actual, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
                actual_tangents = tree_map(lambda x: unwrap(x.tangent), actual, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
                assert_equal_fn(actual_primals, expected_primals, equal_nan=True)
                assert_equal_fn(actual_tangents, expected_tangents, equal_nan=True)

def _load_dynamic_shapes(spec: Union[DynamicShapesSpec, dict[str, Any]], from_dict: Optional[bool]=False) -> Union[dict[str, Any], tuple[Any], list[Any], None]:
    """
    Utility function for dynamic shapes serialization.
    Deserializes a DynamicShapesSpec or corresponding dictionary into a dynamic_shapes input to export().
    """
    import sympy
    from torch.fx.experimental.symbolic_shapes import _is_supported_equivalence
    if from_dict:
        if not isinstance(spec, dict):
            raise UserError(UserErrorType.INVALID_INPUT, f'With from_dict=True, expected `spec` to be a dict, got {type(spec)}')
        if sorted(spec.keys()) != ['dims', 'dynamic_shapes']:
            raise UserError(UserErrorType.INVALID_INPUT, f'With from_dict=True, expected `spec` to have keys `dims` and `dynamic_shapes`, instead found {spec.keys()}')
        dims = {}
        for (k, v) in spec['dims'].items():
            if not isinstance(k, str):
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected `spec['dims']` keys to be strings for symbols, got key {type(k)}")
            if sorted(v.keys()) != ['derived', 'max', 'min']:
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected `spec['dims']` values to have keys `derived`, `max`, and `min`, instead found {v.keys()}")
            if not isinstance(v['min'], int):
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dims']` to map `min` to an int, got {k}: {v['min']}")
            if not isinstance(v['max'], int) or v['max'] is None:
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dims']` to map `max` to an int or None, got {k}: {v['max']}")
            if not isinstance(v['derived'], list) or any((not isinstance(d, str) for d in v['derived'])):
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dims']` to map `derived` to a list of derived expressions, got {k}: {v['derived']}")
            dims[k] = RootDim(**v)
        dynamic_shapes = spec['dynamic_shapes']
    else:
        if not isinstance(spec, DynamicShapesSpec):
            raise UserError(UserErrorType.INVALID_INPUT, f'Expected `spec` to be a DynamicShapesSpec, got {type(spec)}')
        dims = spec.dims
        dynamic_shapes = spec.dynamic_shapes
    if dynamic_shapes is None:
        return None
    dim_cache = {}
    for (name, info) in dims.items():
        symbol = sympy.sympify(name)
        if not isinstance(symbol, sympy.Symbol):
            raise UserError(UserErrorType.INVALID_INPUT, f"Expected `spec['dims']` keys to be symbols, got {name}")
        dim_cache[name] = Dim(name, min=info.min, max=info.max)
        for _expr in info.derived:
            expr = sympy.sympify(_expr)
            if len(expr.free_symbols) != 1 or symbol not in expr.free_symbols:
                raise UserError(UserErrorType.INVALID_INPUT, f'Expected derived expressions in to have {name} as the only free symbol, got {expr}')
            if not _is_supported_equivalence(expr):
                raise UserError(UserErrorType.INVALID_INPUT, f'Expected derived expressions to be linear expressions, got {expr}')
            (modulus, remainder) = sympy.polys.polytools.div(expr, symbol)
            ddim = dim_cache[name]
            if modulus != 1:
                ddim = int(modulus) * ddim
            if <MASK>:
                ddim = ddim + int(remainder)
            dim_cache[_expr] = ddim

    def deserialize_shape(val: Union[None, int, str]) -> Union[None, int, Dim, _DimHint]:
        if val is None or isinstance(val, int):
            return val
        elif val == '_DimHint.AUTO':
            return _DimHint.AUTO()
        elif val == '_DimHint.DYNAMIC':
            return _DimHint.DYNAMIC()
        elif val == '_DimHint.STATIC':
            return _DimHint.STATIC()
        if not isinstance(val, str):
            raise UserError(UserErrorType.INVALID_INPUT, f"Expected leaves in `spec['dynamic_shapes']` to be ints, None, Dim.AUTO/STATIC, symbols,  or derived expressions, got {val}")
        if val not in dim_cache:
            raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dynamic_shapes']` to be tracked in `spec['dims']`, got {val} which is not in {dims.keys()}")
        return dim_cache[val]
    return tree_map(deserialize_shape, dynamic_shapes)

def val_to_arg_str_for_prim_type(self, val, type_) -> str:
    if isinstance(val, bool):
        return '1' if val else '0'
    elif isinstance(val, int):
        return f'{val}LL' if sys.platform in ['darwin', 'win32'] else f'{val}L'
    elif isinstance(val, complex):
        return f'c10::complex<double>{{ {self.generate_float_value(val.real)}, {self.generate_float_value(val.imag)} }}'
    elif isinstance(val, str):
        return f'"{val}"'
    elif isinstance(val, (ir.Buffer, ir.ReinterpretView, ir.StorageBox, ir.TensorBox)):
        return val.codegen_reference()
    elif isinstance(val, torch.device):
        return self.codegen_device(val)
    elif <MASK>:
        return self.codegen_dtype(val)
    elif isinstance(val, torch.layout):
        return self.codegen_layout(val)
    elif isinstance(val, torch.memory_format):
        return self.codegen_memory_format(val)
    elif isinstance(val, float):
        return self.generate_float_value(val)
    elif isinstance(val, (list, tuple)):
        return f"{{{', '.join((self.val_to_arg_str(x, None) for x in val))}}}"
    elif isinstance(val, SymTypes):
        return cexpr(val.node.expr)
    elif isinstance(val, sympy.Expr):
        return cexpr(val)
    else:
        return repr(val)

def apply_match(pattern, node, match, matched_node_pattern, node_to_subpattern):
    if isinstance(pattern, tuple):
        (s, *args) = pattern
        current_node_pattern: list[Node] = []
        apply_match(s, node, match, current_node_pattern, node_to_subpattern)
        for (subpattern, arg) in zip(args, node.args):
            apply_match(subpattern, arg, match, current_node_pattern, node_to_subpattern)
        matched_node_pattern.append(tuple(current_node_pattern))
    elif node.name not in match_map:
        matched_node_pattern.append(node)
        if <MASK>:
            node_to_subpattern[node] = pattern
            (root_node, pattern, handler) = match
            match_map[node.name] = (root_node, pattern, matched_node_pattern, handler, node_to_subpattern)

def get_buffer(self) -> Buffer:

    def unwrap_views(target: Any) -> Any:
        if <MASK>:
            return unwrap_views(target.target)
        if isinstance(target, BaseView):
            return unwrap_views(target.unwrap_view())
        if isinstance(target, MutableBox):
            return unwrap_views(target.data)
        return target
    result = unwrap_views(self.target)
    assert isinstance(result, Buffer), type(result)
    return result

@method_with_native_function
def gen_one(self, f: NativeFunction) -> str | None:
    assert not f.manual_kernel_registration
    if self.target is Target.REGISTRATION and (not self.selector.is_native_function_selected(f)):
        return None
    if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional and f.func.kind() is SchemaKind.out:
        return None
    cpp_sig_group = CppSignatureGroup.from_native_function(f, method=False, fallback_binding=False)
    kern = self.backend_index.get_kernel(f)
    sig = NativeSignature(f.func, prefix=f'wrapper_{self.backend_index.dispatch_key}_', symint=kern is not None and kern.supports_symint())
    if self.target is Target.NAMESPACED_DECLARATION:
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += f'TORCH_API {cpp_sig.decl()};\n'
        return result
    elif self.target is Target.NAMESPACED_DEFINITION:

        def generate_defn(cpp_sig: CppSignature) -> str:
            return f"\n{cpp_sig.defn()} {{\nreturn {sig.name()}({', '.join((e.expr for e in translate(cpp_sig.arguments(), sig.arguments())))});\n}}\n"
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += generate_defn(cpp_sig)
        return result
    elif self.target is Target.ANONYMOUS_DEFINITION:
        k = f.func.kind()
        sig_body = []
        context: list[Binding | Expr] = list(sig.arguments())
        if self.backend_index.dispatch_key is DispatchKey.Meta:
            class_name = f'structured_{meta.name(self.g)}_meta_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        elif self.backend_index.dispatch_key is DispatchKey.CompositeExplicitAutogradNonFunctional:
            class_name = f'structured_{meta.name(self.g)}_default_backend_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        else:
            metadata = self.backend_index.get_kernel(self.g)
            assert metadata is not None
            class_name = f'structured_{metadata.kernel}_{k.name}'
            parent_class = f'{metadata.cpp_namespace}::structured_{metadata.kernel}'
        if <MASK>:
            device_check_args = itertools.chain(f.func.arguments.out, f.func.arguments.flat_positional)
            sig_body.append(RegisterDispatchKey.gen_device_check(f.device_check, list(device_check_args), sig.name()))
        if k is SchemaKind.functional:
            sig_body.append(f'{class_name} op;')
        elif k is SchemaKind.inplace:
            sig_body.append(f'{class_name} op(self);')
        elif k is SchemaKind.out:
            out_args_str = ', '.join((a.name for a in f.func.arguments.out))
            sig_body.append(f'{class_name} op({out_args_str});')
        meta_exprs = ', '.join((e.expr for e in translate(context, structured.meta_arguments(self.g), method=False)))
        if self.g.out.precomputed:
            sig_body.append(f'auto precompute = op.meta({meta_exprs});')
            precomputed_values = [*self.g.out.precomputed.replace.values(), self.g.out.precomputed.add]
            for precomputed_elems in precomputed_values:
                context.extend((Expr(expr=f'precompute.{arg.name}', type=structured.argument_type(arg, binds=arg.name)) for arg in precomputed_elems))
            sig_body.append('(void)precompute;')
        else:
            sig_body.append(f'op.meta({meta_exprs});')
        out_args = structured.out_arguments(self.g)
        for (i, out_arg) in enumerate(out_args):
            assert ConstRefCType(BaseCType(tensorT)) == out_arg.nctype.type
            if k is SchemaKind.out:
                expr = f'op.maybe_get_output({i})'
            else:
                expr = f'op.outputs_[{i}]'
            context.append(Expr(expr=expr, type=NamedCType(out_arg.nctype.name, MutRefCType(BaseCType(tensorT)))))
        if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional:
            out_sig_group = CppSignatureGroup.from_native_function(self.g.out, method=False, fallback_binding=f.manual_cpp_binding)
            out_sig = out_sig_group.most_faithful_signature()
            api_name = out_sig.name()
            out_exprs = ', '.join((e.expr for e in translate(context, out_sig.arguments(), method=False)))
            sig_body.append(f'at::{api_name}({out_exprs});')
        elif self.backend_index.dispatch_key != DispatchKey.Meta:
            impl_exprs = ', '.join((e.expr for e in translate(context, structured.impl_arguments(self.g), method=False)))
            sig_body.append(f'op.impl({impl_exprs});')
        if k is SchemaKind.out or k is SchemaKind.inplace:
            for i in range(len(f.func.returns)):
                sig_body.append(f'if (op.proxy_outputs_[{i}].has_value()) op.outputs_[{i}].get().copy_(*op.proxy_outputs_[{i}]);')
        if k is SchemaKind.functional:
            if len(f.func.returns) == 1:
                ret_expr = 'std::move(op.outputs_[0])'
            else:
                moved = ', '.join((f'std::move(op.outputs_[{i}])' for i in range(len(f.func.returns))))
                ret_expr = f'std::make_tuple({moved})'
        elif k is SchemaKind.inplace:
            ret_expr = 'self'
        elif k is SchemaKind.out:
            if len(f.func.returns) == 1:
                ret_expr = f.func.arguments.out[0].name
            else:
                refs = ', '.join((a.name for a in f.func.arguments.out))
                ret_expr = f'std::forward_as_tuple({refs})'
        sig_body.append(f'return {ret_expr};')
        sig_body_str = '\n'.join(sig_body)
        return f'{self.gen_class(f, k, class_name=class_name, parent_class=parent_class, generate_super=self.g.out.structured_inherits is not None)}\n\n{sig.defn()} {{\n{sig_body_str}\n}}\n'
    elif self.target is Target.REGISTRATION:
        return f'm.impl("{f.func.name}", TORCH_FN({sig.name()}));'
    else:
        assert_never(self.target)
        return None

