def _broadcast_state_dict(full_state_dict: dict[str, Any], local_state_dict: dict[str, Any], device: torch.device, pg: Optional[dist.ProcessGroup]=None, strict: bool=False, cpu_offload: bool=False) -> None:
    ret = {}
    if dist.get_rank() == 0:
        for (key, value) in full_state_dict.items():
            if not torch.is_tensor(value):
                ret[key] = value
            elif value.dim() == 0:
                ret[key] = value.cpu()
            else:
                ret[key] = _TensorInfo(value.size(), value.dtype)
    broadcast_list = [ret]
    dist.broadcast_object_list(broadcast_list, src=0, group=pg)
    ret = broadcast_list[0]
    keys = []
    local_state_dict_keys = set(local_state_dict.keys())
    global_keys = set()
    for (key, value) in ret.items():
        global_keys.add(key)
        if not isinstance(value, _TensorInfo):
            if key in local_state_dict:
                local_state_dict[key] = value
            continue
        if dist.get_rank() == 0:
            ret[key] = full_state_dict[key]
        keys.append(key)
        if len(keys) >= 1:
            _broadcast_tensors(ret, local_state_dict, keys, device, pg)
            if cpu_offload:
                for key in keys:
                    local_state_dict[key] = local_state_dict[key].cpu()
            keys.clear()
    if <MASK>:
        if (missing_keys := (local_state_dict_keys - global_keys)):
            for key in missing_keys:
                local_state_dict.pop(key)
    if keys:
        _broadcast_tensors(ret, local_state_dict, keys, device, pg)
        if cpu_offload:
            for key in keys:
                local_state_dict[key] = local_state_dict[key].cpu()

def add_node(node):
    if node.kind() == 'prim::FusionGroup':
        return add_fusion_group(node)
    elif <MASK>:
        return add_graph_executor(node)
    (op, name) = name_for(node)
    pb_node = pb_graph.node.add(op=op, name=name)
    for value in node.inputs():
        pb_node.input.append(value_map[value.unique()])
    for (i, value) in enumerate(node.outputs()):
        value_map[value.unique()] = name + ':' + str(i)

@staticmethod
def build_Name(ctx, expr):
    r = ctx.make_range(expr.lineno, expr.col_offset, expr.col_offset + len(expr.id))
    if <MASK>:
        raise NotSupportedError(r, "names of variables used in JIT-ed functions can't start with " + _reserved_prefix)
    if expr.id == 'True':
        return TrueLiteral(r)
    elif expr.id == 'False':
        return FalseLiteral(r)
    elif expr.id == 'None':
        return NoneLiteral(r)
    elif expr.id == 'Ellipsis':
        return Dots(r)
    return Var(Ident(r, expr.id))

def ast(self):
    """AST representation."""
    if self.has_subscript():
        return gast.Subscript(value=self.parent.ast(), slice=self.qn[-1].ast(), ctx=CallerMustSetThis)
    if <MASK>:
        return gast.Attribute(value=self.parent.ast(), attr=self.qn[-1], ctx=CallerMustSetThis)
    base = self.qn[0]
    if isinstance(base, str):
        return gast.Name(base, ctx=CallerMustSetThis, annotation=None, type_comment=None)
    elif isinstance(base, Literal):
        return gast.Constant(base.value, kind=None)
    else:
        assert False, 'the constructor should prevent types other than str and Literal'

def indirect_indexing(self, var: CSEVariable, size: Union[sympy.Expr, int], check: bool=True, wrap_neg: bool=True) -> sympy.Symbol:
    if isinstance(size, int):
        size = sympy.Integer(size)
    assert isinstance(size, sympy.Expr), (type(size), size)
    if var.bounds.lower < 0:
        if wrap_neg:
            stm = ops.add(var, ops.index_expr(size, torch.long))
            if <MASK>:
                lt = ops.lt(var, 0)
                stm = ops.where(lt, stm, var)
        else:
            stm = var
        new_bounds = ValueRanges.unknown()
        if var.bounds != ValueRanges.unknown() and isinstance(size, sympy.Number):
            neg_bounds = var.bounds & ValueRanges(-int_oo, -1)
            new_bounds = ValueRanges(neg_bounds.lower + size, neg_bounds.upper + size)
            if var.bounds.upper >= 0:
                pos = var.bounds & ValueRanges(0, int_oo)
                new_bounds = new_bounds | pos
        var = self.kernel.cse.generate(self.kernel.compute, stm, bounds=new_bounds, dtype=var.dtype, shape=var.shape)
    sympy_var = self.parent_handler.indirect_indexing(var, size, check)
    if generate_assert(check):
        assert_lower = not var.bounds.lower >= 0
        assert_upper = not isinstance(size, sympy.Number) or not var.bounds.upper < size
        self.kernel.check_bounds(sympy_var, size, assert_lower, assert_upper)
    return sympy_var

def sort(x: Array, /, xp: Namespace, *, axis: int=-1, descending: bool=False, stable: bool=True, **kwargs: object) -> Array:
    if stable:
        kwargs['kind'] = 'stable'
    res = xp.sort(x, axis=axis, **kwargs)
    if <MASK>:
        res = xp.flip(res, axis=axis)
    return res

def _test(self, kwargs, expected_values=None, expected_err=None):
    if expected_err:
        if not context.executing_eagerly():
            with self.assertRaisesWithPredicateMatch(expected_err[0], expected_err[1]):
                self.evaluate(parsing_ops.parse_example(**kwargs))
        else:
            with self.assertRaises(Exception):
                parsing_ops.parse_example(**kwargs)
        return
    else:
        out = parsing_ops.parse_example(**kwargs)
        _compare_output_to_expected(self, out, expected_values)
    serialized = kwargs['serialized']
    batch_size = self.evaluate(serialized).size if isinstance(serialized, tensor_lib.Tensor) else np.asarray(serialized).size
    for (k, f) in kwargs['features'].items():
        if isinstance(f, parsing_ops.FixedLenFeature) and f.shape is not None:
            self.assertEqual(tuple(out[k].shape.as_list()), (batch_size,) + f.shape)
        elif isinstance(f, parsing_ops.VarLenFeature):
            if <MASK>:
                out[k].indices.shape.assert_is_compatible_with([None, 2])
                out[k].values.shape.assert_is_compatible_with([None])
                out[k].dense_shape.shape.assert_is_compatible_with([2])
            else:
                self.assertEqual(out[k].indices.shape.as_list(), [None, 2])
                self.assertEqual(out[k].values.shape.as_list(), [None])
                self.assertEqual(out[k].dense_shape.shape.as_list(), [2])

def __init__(self, x=None, y=None, z=None, srid=None):
    """
        The Point object may be initialized with either a tuple, or individual
        parameters.

        For example:
        >>> p = Point((5, 23))  # 2D point, passed in as a tuple
        >>> p = Point(5, 23, 8)  # 3D point, passed as individual parameters
        """
    if x is None:
        coords = []
    elif isinstance(x, (tuple, list)):
        coords = x
    elif <MASK>:
        if isinstance(z, (float, int)):
            coords = [x, y, z]
        else:
            coords = [x, y]
    else:
        raise TypeError('Invalid parameters given for Point initialization.')
    point = self._create_point(len(coords), coords)
    super().__init__(point, srid=srid)

def sequence_list(self):
    """
        Return a list of information about all DB sequences for all models in
        all apps.
        """
    sequence_list = []
    with self.connection.cursor() as cursor:
        for model in self.get_migratable_models():
            if <MASK>:
                continue
            if model._meta.swapped:
                continue
            sequence_list.extend(self.get_sequences(cursor, model._meta.db_table, model._meta.local_fields))
            for f in model._meta.local_many_to_many:
                if f.remote_field.through._meta.auto_created:
                    sequence = self.get_sequences(cursor, f.m2m_db_table())
                    sequence_list.extend(sequence or [{'table': f.m2m_db_table(), 'column': None}])
    return sequence_list

@staticmethod
def from_ewkt(ewkt):
    ewkt = force_bytes(ewkt)
    srid = None
    parts = ewkt.split(b';', 1)
    if len(parts) == 2:
        (srid_part, wkt) = parts
        match = re.match(b'SRID=(?P<srid>\\-?\\d+)', srid_part)
        if <MASK>:
            raise ValueError('EWKT has invalid SRID part.')
        srid = int(match['srid'])
    else:
        wkt = ewkt
    if not wkt:
        raise ValueError('Expected WKT but got an empty string.')
    return GEOSGeometry(GEOSGeometry._from_wkt(wkt), srid=srid)

def assign_on_each_device(var, assign_func, value, read_value):
    """Update the variable on each replica with the given assign_func and value."""
    if <MASK>:
        update = control_flow_ops.group(tuple((assign_func(d, var._packed_variable, value) for d in var._devices)))
    else:
        update = control_flow_ops.group(tuple((assign_func(v.device, v, value) for v in var._values)))
    if not read_value:
        return update
    with ops.control_dependencies([update] if update else []):
        return var.read_value()

