def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    if name == '__contains__':
        return self.dv_dict.call_method(tx, name, args, kwargs)
    elif <MASK>:
        m = getattr(self.set_items, name)
        r = m(args[0].set_items)
        return SetVariable(r)
    if name in cmp_name_to_op_mapping:
        if not isinstance(args[0], (SetVariable, DictKeysVariable)):
            return ConstantVariable.create(NotImplemented)
        return ConstantVariable.create(cmp_name_to_op_mapping[name](self.set_items, args[0].set_items))
    return super().call_method(tx, name, args, kwargs)

def init(self, module: nn.Module, ignored_modules: set[nn.Module], **kwargs) -> None:
    if self.has_initialized:
        return
    self.has_initialized = True
    self.module = module
    ignored_params = {p for m in ignored_modules for p in m.parameters()}
    for submodule in module.modules():
        if _is_fully_sharded(submodule):
            ignored_params.update(submodule.parameters())
    from torch.distributed.tensor.parallel.ddp import _localize_dtensor
    _localize_dtensor(module, ignored_params=ignored_params)
    self._collect_params(module, ignored_modules, ignored_params)
    if 'device_id' in kwargs:
        if kwargs['device_id'] is not None:
            device_id = kwargs['device_id']
            if <MASK>:
                kwargs['device_ids'] = None
            else:
                kwargs['device_ids'] = [device_id]
        else:
            kwargs['device_ids'] = None
        kwargs.pop('device_id')
    self._ddp = DistributedDataParallel(self._param_list, **kwargs)
    replicate.state(self.module)._ddp_weakref = weakref.ref(self._ddp)

def process_axes(self, obj, selection: Selection, columns=None) -> DataFrame:
    """process axes filters"""
    if <MASK>:
        columns = list(columns)
    if columns is not None and self.is_multi_index:
        assert isinstance(self.levels, list)
        for n in self.levels:
            if n not in columns:
                columns.insert(0, n)
    for (axis, labels) in self.non_index_axes:
        obj = _reindex_axis(obj, axis, labels, columns)

        def process_filter(field, filt, op):
            for axis_name in obj._AXIS_ORDERS:
                axis_number = obj._get_axis_number(axis_name)
                axis_values = obj._get_axis(axis_name)
                assert axis_number is not None
                if field == axis_name:
                    if self.is_multi_index:
                        filt = filt.union(Index(self.levels))
                    takers = op(axis_values, filt)
                    return obj.loc(axis=axis_number)[takers]
                elif field in axis_values:
                    values = ensure_index(getattr(obj, field).values)
                    filt = ensure_index(filt)
                    if isinstance(obj, DataFrame):
                        axis_number = 1 - axis_number
                    takers = op(values, filt)
                    return obj.loc(axis=axis_number)[takers]
            raise ValueError(f'cannot find the field [{field}] for filtering!')
    if selection.filter is not None:
        for (field, op, filt) in selection.filter.format():
            obj = process_filter(field, filt, op)
    return obj

def __rtruediv__(self, other):
    if <MASK>:
        return sym_float(self).__rfloat_truediv__(other)
    if not isinstance(other, (builtins.int, SymInt)):
        return NotImplemented
    return self.__rint_truediv__(other)

def _build_kml_sources(self, sources):
    """
        Go through the given sources and return a 3-tuple of the application
        label, module name, and field name of every GeometryField encountered
        in the sources.

        If no sources are provided, then all models.
        """
    kml_sources = []
    if <MASK>:
        sources = apps.get_models()
    for source in sources:
        if isinstance(source, models.base.ModelBase):
            for field in source._meta.fields:
                if isinstance(field, GeometryField):
                    kml_sources.append((source._meta.app_label, source._meta.model_name, field.name))
        elif isinstance(source, (list, tuple)):
            if len(source) != 3:
                raise ValueError('Must specify a 3-tuple of (app_label, module_name, field_name).')
            kml_sources.append(source)
        else:
            raise TypeError('KML Sources must be a model or a 3-tuple.')
    return kml_sources

@simple_wraps(fn)
def _functionalized_f_helper(*args: list[FxValue]) -> tuple[tuple[list[FxValue], list[Tensor]], list[Optional[AOTOutput]]]:
    with maybe_enable_thunkify():
        disable_above = torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize))
        with disable_above:
            f_args = pytree.tree_map(to_fun, args)
            if trace_joint and has_input_mutated_in_graph and joint_fn_handle:

                def _post_forward(primals):
                    nonlocal primals_after_forward
                    primals_after_forward = pytree.tree_map(from_fun, primals)
                    nonlocal f_args_after_forward
                    f_args_after_forward = f_args[0]
                    nonlocal f_args_mutation_counters_after_forward
                    f_args_mutation_counters_after_forward = [MutationCounters(-1, -1, -1) if not inputs_mutated_in_graph[i] else _get_mutation_counters(f_arg) for (i, f_arg) in enumerate(f_args_after_forward)]
                joint_fn_handle.post_forward = _post_forward
            (f_outs, f_outs_descs) = call_and_expect_output_descs(fn, f_args)
        if trace_joint:
            assert isinstance(args, tuple) and len(args) == 2 and isinstance(args[0], (list, tuple))
            primals_before = args[0]
            primals_after = pytree.tree_map(from_fun, f_args[0])
            for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args[0], primals_before, primals_after, meta.input_info)):
                joint_mutates_data = has_data_mutation(f_inpt)
                joint_mutates_metadata = has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False)
                if not inpt_info.mutates_metadata:
                    assert not joint_mutates_metadata, 'Found a graph input that had its metadata mutated in the backward. This is not supported'
                if not inpt_info.mutation_inductor_storage_resize:
                    assert not was_inductor_storage_resized(f_inpt), 'Found a graph input that had storage resizing in the backward. This is not supported'
                if joint_mutates_data and (not inpt_info.mutates_data) and (not inpt_info.mutates_storage_metadata):
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
                    meta.indices_of_inputs_that_requires_grad_with_mutations_in_bw.append(idx)
            tangents_before = args[1]
            tangents_after = pytree.tree_map(from_fun, f_args[1])
            for (f_inpt, before, after) in zip(f_args[1], tangents_before, tangents_after):
                assert not has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False), 'Found an input to the backward that had metadata mutated during the backward pass. This is not supported'
                if has_data_mutation(f_inpt):
                    can_be_in_graph = _check_if_mutation_can_be_in_graph(keep_input_mutations=True, mutates_data=True, mutates_metadata=False, mutations_hidden_from_autograd=are_all_mutations_hidden_from_autograd(f_inpt), mutations_under_no_grad_or_inference_mode=are_all_mutations_under_no_grad_or_inference_mode(f_inpt), mutates_storage_metadata=False, mutation_inductor_storage_resize=was_inductor_storage_resized(f_inpt), requires_grad=f_inpt.requires_grad)
                    assert can_be_in_graph, 'a backward input that had data mutated in an autograd-aware way. This is not supported'
                    with torch.fx.traceback.preserve_node_meta():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
        if aot_config.keep_inference_input_mutations:
            mcs_applied: list[MutationCounters] = [MutationCounters(0, 0, 0)] * len(meta.input_info)
            if <MASK>:
                primals_before = args[0]
                for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args_after_forward, primals_before, primals_after_forward, meta.input_info)):
                    if inpt_info.mutation_type != MutationType.MUTATED_IN_GRAPH:
                        continue
                    mcs_after_forward = f_args_mutation_counters_after_forward[idx]
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_forward(), _proxy_tensor_disable_update_tensor_tracker():
                        apply_in_graph_mutations(inpt_info, before, after, f_inpt, idx, mcs_after_forward, mcs_applied[idx])
                        mcs_applied[idx] = mcs_after_forward
            for (idx, (inpt_old, f_inpt)) in enumerate(zip(args, f_args) if not trace_joint else zip(args[0], f_args[0])):
                if not isinstance(f_inpt, torch.Tensor):
                    continue
                assert is_fun(f_inpt)
                inpt_new = from_fun(f_inpt)
                if meta.input_info[idx].mutation_type != MutationType.MUTATED_IN_GRAPH:
                    continue
                mcs: Optional[MutationCounters] = None
                if f_args_mutation_counters_after_forward is not None:
                    mcs = _get_mutation_counters(f_inpt)
                    if mcs == mcs_applied[idx]:
                        continue
                with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                    apply_in_graph_mutations(meta.input_info[idx], inpt_old, inpt_new, f_inpt, idx, mcs, mcs_applied[idx])
            (flat_outs, outs_spec) = pytree.tree_flatten(f_outs)
            flat_outs = [from_fun(o) for o in flat_outs]
            num_outs = len(meta.output_info)
            for i in range(num_outs):
                info = meta.output_info[i]
                if info.output_type != OutputType.is_input:
                    continue
                assert info.base_idx is not None
                if meta.input_info[info.base_idx].mutation_type == MutationType.MUTATED_IN_GRAPH:
                    fw_args = args[0] if trace_joint else args
                    flat_outs[i] = fw_args[info.base_idx]
            return (pytree.tree_unflatten(flat_outs, outs_spec), f_outs_descs)
        return (pytree.tree_map(from_fun, f_outs), f_outs_descs)

def can_fuse(self, node1, node2):
    """
        Hook called by Scheduler to determine if the Triton backend
        can fuse node1 and node2.  These nodes might already be
        FusedSchedulerNodes.
        """
    if isinstance(node1, scheduler.ForeachKernelSchedulerNode) or isinstance(node2, scheduler.ForeachKernelSchedulerNode):
        return scheduler.ForeachKernelSchedulerNode.can_fuse(node1, node2)
    (_, (numel1, rnumel1)) = node1.group
    (_, (numel2, rnumel2)) = node2.group
    why = WhyNoFuse(node1, node2)
    if node1.is_split_scan() and (not node2.is_split_scan()):
        if node2.is_reduction():
            why('Split scan cannot fuse with reductions')
    elif node2.is_split_scan() and (not node1.is_split_scan()):
        if node1.is_reduction():
            why('Split scan cannot fuse with reductions')
    if node1.is_reduction() and node2.is_reduction():
        reduction_can_fuse = numel1 == numel2 and rnumel1 == rnumel2
        if <MASK>:
            why('numel/rnumel mismatch (reduce) (%s, %s), (%s, %s)', numel1, numel2, rnumel1, rnumel2)
        if reduction_can_fuse and (node1.is_native_matmul() or node2.is_native_matmul()):
            if not node1.is_native_matmul():
                (node1, node2) = (node2, node1)
            tiling = self.select_tiling(node1.get_nodes(), numel1, rnumel1)
            if not all((SIMDKernel.is_compatible(tiling.values(), n2.get_ranges(), reduction_numel=rnumel1) for n2 in node2.get_nodes())):
                why('invalid loop order and tiling for native matmul')
                return False
        return reduction_can_fuse
    if not node1.is_reduction() and (not node2.is_reduction()):
        if not (numel1 == numel2 and rnumel1 == rnumel2):
            if not node2.is_template():
                why('numel/rnumel mismatch (non-reduce) (%s, %s), (%s, %s)', numel1, numel2, rnumel1, rnumel2)
                return False
            else:
                for node in node2.get_nodes():
                    if node.is_template():
                        break
                    if not node.used_buffer_names() & node1.get_buffer_names():
                        continue
                    (_, (pro_numel, pro_rnumel)) = node.group
                    if not (numel1 == pro_numel and rnumel1 == pro_rnumel):
                        why('numel/rnumel mismatch prologue mismatch (%s, %s), (%s, %s)', numel1, pro_numel, rnumel1, pro_rnumel)
                        return False
        for n in (node1, node2):
            if n.is_template():
                return True
        tiling1 = self.select_tiling(node1.get_nodes(), numel1, rnumel1)
        tiling2 = self.select_tiling(node2.get_nodes(), numel1, rnumel1)
        tiling3 = self.select_tiling(node1.get_nodes() + node2.get_nodes(), numel1, rnumel1)
        if config.triton.tiling_prevents_pointwise_fusion:
            cond = True
            if len(tiling1) > 2:
                if len(tiling2) > 2:
                    cond = tiling1 == tiling2 == tiling3
                else:
                    cond = tiling1 == tiling3
            elif len(tiling2) > 2:
                cond = tiling2 == tiling3
            if not cond:
                why('tiling mismatch (%s, %s, %s)', tiling1, tiling2, tiling3)
                return False
        return True
    if not node1.is_reduction() and node2.is_reduction():
        assert rnumel1 == 1 and rnumel2 != 1
        if numel1 == numel2 * rnumel2:
            if not all((SIMDKernel.is_compatible((numel2, rnumel2), n.get_ranges()) for n in node1.get_nodes())):
                why('nodes numel/rnumel incompatibility')
                return False
            if config.triton.tiling_prevents_reduction_fusion and (not node1.is_template()):
                is_reduction_tiling_valid = tuple(self.select_tiling(node1.get_nodes(), numel1).values()) in ((numel1, 1), (numel2, rnumel2, 1))
                if not is_reduction_tiling_valid:
                    why('invalid tiling for reduction')
                return is_reduction_tiling_valid
            return True
        if numel1 != numel2:
            why('nodes numel incompatibility')
        return numel1 == numel2
    assert node1.is_reduction() and (not node2.is_reduction())
    return self.can_fuse_horizontal(node2, node1)

@doc(NDFrame.shift, klass=_shared_doc_kwargs['klass'])
def shift(self, periods: int | Sequence[int]=1, freq: Frequency | None=None, axis: Axis=0, fill_value: Hashable=lib.no_default, suffix: str | None=None) -> DataFrame:
    if freq is not None and fill_value is not lib.no_default:
        raise ValueError("Passing a 'freq' together with a 'fill_value' is not allowed.")
    if self.empty and freq is None:
        return self.copy()
    axis = self._get_axis_number(axis)
    if <MASK>:
        periods = cast(Sequence, periods)
        if axis == 1:
            raise ValueError('If `periods` contains multiple shifts, `axis` cannot be 1.')
        if len(periods) == 0:
            raise ValueError('If `periods` is an iterable, it cannot be empty.')
        from pandas.core.reshape.concat import concat
        shifted_dataframes = []
        for period in periods:
            if not is_integer(period):
                raise TypeError(f'Periods must be integer, but {period} is {type(period)}.')
            period = cast(int, period)
            shifted_dataframes.append(super().shift(periods=period, freq=freq, axis=axis, fill_value=fill_value).add_suffix(f'{suffix}_{period}' if suffix else f'_{period}'))
        return concat(shifted_dataframes, axis=1)
    elif suffix:
        raise ValueError('Cannot specify `suffix` if `periods` is an int.')
    periods = cast(int, periods)
    ncols = len(self.columns)
    if axis == 1 and periods != 0 and (ncols > 0) and (freq is None):
        if fill_value is lib.no_default:
            label = self.columns[0]
            if periods > 0:
                result = self.iloc[:, :-periods]
                for col in range(min(ncols, abs(periods))):
                    filler = self.iloc[:, 0].shift(len(self))
                    result.insert(0, label, filler, allow_duplicates=True)
            else:
                result = self.iloc[:, -periods:]
                for col in range(min(ncols, abs(periods))):
                    filler = self.iloc[:, -1].shift(len(self))
                    result.insert(len(result.columns), label, filler, allow_duplicates=True)
            result.columns = self.columns.copy()
            return result
        elif len(self._mgr.blocks) > 1 or not can_hold_element(self._mgr.blocks[0].values, fill_value):
            nper = abs(periods)
            nper = min(nper, ncols)
            if periods > 0:
                indexer = np.array([-1] * nper + list(range(ncols - periods)), dtype=np.intp)
            else:
                indexer = np.array(list(range(nper, ncols)) + [-1] * nper, dtype=np.intp)
            mgr = self._mgr.reindex_indexer(self.columns, indexer, axis=0, fill_value=fill_value, allow_dups=True)
            res_df = self._constructor_from_mgr(mgr, axes=mgr.axes)
            return res_df.__finalize__(self, method='shift')
        else:
            return self.T.shift(periods=periods, fill_value=fill_value).T
    return super().shift(periods=periods, freq=freq, axis=axis, fill_value=fill_value)

def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    key = com.apply_if_callable(key, self)
    if key is Ellipsis:
        return self.copy(deep=False)
    key_is_scalar = is_scalar(key)
    if <MASK>:
        key = unpack_1tuple(key)
    elif key_is_scalar:
        return self._get_value(key)
    if is_iterator(key):
        key = list(key)
    if is_hashable(key) and (not isinstance(key, slice)):
        try:
            result = self._get_value(key)
            return result
        except (KeyError, TypeError, InvalidIndexError):
            if isinstance(key, tuple) and isinstance(self.index, MultiIndex):
                return self._get_values_tuple(key)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    if com.is_bool_indexer(key):
        key = check_bool_indexer(self.index, key)
        key = np.asarray(key, dtype=bool)
        return self._get_rows_with_mask(key)
    return self._get_with(key)

def decorating_function(f):
    repr_running = set()

    @functools.wraps(f)
    def wrapper(self, *args, **kwargs):
        key = (id(self), get_ident())
        if <MASK>:
            return fillvalue
        repr_running.add(key)
        try:
            return f(self, *args, **kwargs)
        finally:
            repr_running.discard(key)
    return wrapper

def fuzz_valid_stride(size: tuple[int, ...]) -> tuple[int, ...]:
    """
    Fuzzes PyTorch tensor strides by generating valid stride patterns for a given size.

    Args:
        size: Tensor shape/size as a tuple of integers

    Returns:
        Tuple[int, ...]: A tuple representing valid tensor strides
    """
    if len(size) == 0:
        return ()
    stride_types = ['contiguous', 'transposed', 'custom_gaps', 'minimal', 'nonoverlapping_and_dense', 'nonoverlapping_and_dense_non_contig', 'overlapping', 'sparse_gaps']
    stride_type: str = random.choice(stride_types)
    if stride_type in ['contiguous', 'nonoverlapping_and_dense']:
        return tuple(_compute_contiguous_strides(size))
    elif stride_type == 'transposed':
        base_strides = list(_compute_contiguous_strides(size))
        if len(base_strides) >= 2:
            (i, j) = random.sample(range(len(base_strides)), 2)
            (base_strides[i], base_strides[j]) = (base_strides[j], base_strides[i])
        return tuple(base_strides)
    elif stride_type == 'custom_gaps':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] != 0 and random.random() < 0.3:
                gap_multiplier: int = random.randint(2, 5)
                base_strides[i] *= gap_multiplier
        return tuple(base_strides)
    elif stride_type == 'minimal':
        return tuple([1] * len(size))
    elif <MASK>:
        return tuple(_compute_non_contiguous_dense_strides(size))
    elif stride_type == 'overlapping':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] > 1 and random.random() < 0.4:
                base_strides[i] = 0
        return tuple(base_strides)
    elif stride_type == 'sparse_gaps':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] > 1:
                gap_multiplier: int = random.randint(10, 100)
                base_strides[i] *= gap_multiplier
        return tuple(base_strides)
    return tuple(_compute_contiguous_strides(size))

def _cmp_method(self, other, op) -> BooleanArray:
    from pandas.core.arrays import BooleanArray
    mask = None
    if isinstance(other, ExtensionArray) and isinstance(other.dtype, ArrowDtype):
        return NotImplemented
    elif isinstance(other, BaseMaskedArray):
        (other, mask) = (other._data, other._mask)
    elif <MASK>:
        other = np.asarray(other)
        if other.ndim > 1:
            raise NotImplementedError('can only perform ops with 1-d structures')
        if len(self) != len(other):
            raise ValueError('Lengths must match to compare')
    if other is libmissing.NA:
        result = np.zeros(self._data.shape, dtype='bool')
        mask = np.ones(self._data.shape, dtype='bool')
    else:
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'elementwise', FutureWarning)
            warnings.filterwarnings('ignore', 'elementwise', DeprecationWarning)
            method = getattr(self._data, f'__{op.__name__}__')
            result = method(other)
            if result is NotImplemented:
                result = invalid_comparison(self._data, other, op)
    mask = self._propagate_mask(mask, other)
    return BooleanArray(result, mask, copy=False)

def _get_input_shape_for_ragged_tensor(self, tensor, feature, per_replica, path) -> TensorShape:
    """Get the input shape for the ragged tensor."""
    del per_replica
    shape = tensor.shape.as_list()
    if <MASK>:
        raise ValueError('Only rank 2 ragged tensor is supported, find rank {} ragged tensor for input {}'.format(len(shape), path))
    if not feature.output_shape and feature.max_sequence_length > 0:
        shape.insert(len(shape) - 1, feature.max_sequence_length)
    return TensorShape(shape)

def main(argv: list[str] | None=None) -> int:
    suspicious_funcs: tuple[str, ...] = ('PyList_GetItem', 'PyDict_GetItem', 'PyDict_GetItemWithError', 'PyDict_GetItemString', 'PyDict_SetDefault', 'PyDict_Next', 'PyWeakref_GetObject', 'PyWeakref_GET_OBJECT', 'PyList_GET_ITEM', '_PyDict_GetItemStringWithError', 'PySequence_Fast')
    func_rx = build_func_rx(suspicious_funcs)
    noqa_markers = ('noqa: borrowed-ref OK', 'noqa: borrowed-ref - manual fix needed')
    default_exts = {'.c', '.h', '.c.src', '.cpp'}
    default_excludes = {'pythoncapi-compat'}
    ap = argparse.ArgumentParser(description='Borrow-ref C API linter (Python).')
    ap.add_argument('--quiet', action='store_true', help='Suppress normal output; exit status alone indicates result (useful              for CI).')
    ap.add_argument('-j', '--jobs', type=int, default=0, help='Number of worker threads (0=auto, 1=sequential).')
    ap.add_argument('--root', default='numpy', type=str, help='Root directory to scan (default: numpy)')
    ap.add_argument('--ext', action='append', default=None, help=f'File extension(s) to include (repeatable). Defaults to {default_exts}')
    ap.add_argument('--exclude', action='append', default=None, help=f'Directory name(s) to exclude (repeatable). Default: {default_excludes}')
    args = ap.parse_args(argv)
    if args.ext:
        exts = {e if e.startswith('.') else f'.{e}' for e in args.ext}
    else:
        exts = set(default_exts)
    excludes = set(args.exclude) if args.exclude else set(default_excludes)
    root = Path(args.root)
    if not root.exists():
        print(f"error: root '{root}' does not exist", file=sys.stderr)
        return 2
    files = sorted(iter_source_files(root, exts, excludes), key=str)
    if args.jobs is None or args.jobs <= 0:
        max_workers = min(32, (os.cpu_count() or 1) * 5)
    else:
        max_workers = max(1, args.jobs)
    print(f'Scanning {len(files)} C/C++ source files...\n')
    tmpdir = Path('.tmp')
    tmpdir.mkdir(exist_ok=True)
    findings = 0
    all_hits: list[tuple[str, int, str, str]] = []
    if max_workers == 1:
        for p in files:
            all_hits.extend(scan_file(p, func_rx, noqa_markers))
    else:
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            fut_to_file = {ex.submit(scan_file, p, func_rx, noqa_markers): p for p in files}
            for fut in as_completed(fut_to_file):
                try:
                    all_hits.extend(fut.result())
                except Exception as e:
                    print(f'Failed to scan {fut_to_file[fut]}: {e}')
    all_hits.sort(key=lambda t: (t[2], t[1]))
    if not all_hits:
        if <MASK>:
            print('All checks passed! C API borrow-ref linter found no issues.\n')
        return 0
    with tempfile.NamedTemporaryFile(prefix='c_api_usage_report.', suffix='.txt', dir=tmpdir, mode='w+', encoding='utf-8', delete=False) as out:
        report_path = Path(out.name)
        out.write('Running Suspicious C API usage report workflow...\n\n')
        for (func, lineo, pstr, raw) in all_hits:
            findings += 1
            out.write(f'Found suspicious call to {func} in file: {pstr}\n')
            out.write(f' -> {pstr}:{lineo}a:{raw}\n')
            out.write('Recommendation:\n')
            out.write("If this use is intentional and safe, add '// noqa: borrowed-ref OK' on the same line to silence this warning.\n")
            out.write('Otherwise, consider replacing the call with a thread-safe API function.\n\n')
        out.flush()
        if not args.quiet:
            out.seek(0)
            sys.stdout.write(out.read())
            print(f'Report written to: {report_path}\n\nC API borrow-ref linter FAILED.')
    return 1

@register_meta([aten.sort.default, aten.sort.stable, aten.sort.values, aten.sort.values_stable])
def meta_sort(self, stable=None, dim=-1, descending=False, values=None, indices=None):
    (v, i) = (torch.empty_like(self), torch.empty_like(self, dtype=torch.int64))
    if <MASK>:
        assert isinstance(values, TensorLike)
        assert isinstance(indices, TensorLike)
        out_shape = v.shape
        out_stride = v.stride()
        values = _maybe_resize_out(values, out_shape)
        indices = _maybe_resize_out(indices, out_shape)
        values.as_strided_(out_shape, out_stride)
        indices.as_strided_(out_shape, out_stride)
        _safe_copy_out(copy_from=v, copy_to=values)
        _safe_copy_out(copy_from=i, copy_to=indices)
        return (values, indices)
    return (v, i)

def initialize_parameters(self, input) -> None:
    if self.has_uninitialized_params():
        self.num_features = input.shape[1]
        if self.affine:
            assert isinstance(self.weight, UninitializedParameter)
            assert isinstance(self.bias, UninitializedParameter)
            self.weight.materialize((self.num_features,))
            self.bias.materialize((self.num_features,))
        if <MASK>:
            self.running_mean.materialize((self.num_features,))
            self.running_var.materialize((self.num_features,))
        self.reset_parameters()

def get_atlas_version(**config):
    libraries = config.get('libraries', [])
    library_dirs = config.get('library_dirs', [])
    key = (tuple(libraries), tuple(library_dirs))
    if key in _cached_atlas_version:
        return _cached_atlas_version[key]
    c = cmd_config(Distribution())
    atlas_version = None
    info = {}
    try:
        (s, o) = c.get_output(atlas_version_c_text, libraries=libraries, library_dirs=library_dirs)
        if s and re.search('undefined reference to `_gfortran', o, re.M):
            (s, o) = c.get_output(atlas_version_c_text, libraries=libraries + ['gfortran'], library_dirs=library_dirs)
            if <MASK>:
                warnings.warn(textwrap.dedent('\n                    *****************************************************\n                    Linkage with ATLAS requires gfortran. Use\n\n                      python setup.py config_fc --fcompiler=gnu95 ...\n\n                    when building extension libraries that use ATLAS.\n                    Make sure that -lgfortran is used for C++ extensions.\n                    *****************************************************\n                    '), stacklevel=2)
                dict_append(info, language='f90', define_macros=[('ATLAS_REQUIRES_GFORTRAN', None)])
    except Exception:
        for o in library_dirs:
            m = re.search('ATLAS_(?P<version>\\d+[.]\\d+[.]\\d+)_', o)
            if m:
                atlas_version = m.group('version')
            if atlas_version is not None:
                break
        if atlas_version is None:
            atlas_version = os.environ.get('ATLAS_VERSION', None)
        if atlas_version:
            dict_append(info, define_macros=[('ATLAS_INFO', _c_string_literal(atlas_version))])
        else:
            dict_append(info, define_macros=[('NO_ATLAS_INFO', -1)])
        return (atlas_version or '?.?.?', info)
    if not s:
        m = re.search('ATLAS version (?P<version>\\d+[.]\\d+[.]\\d+)', o)
        if m:
            atlas_version = m.group('version')
    if atlas_version is None:
        if re.search('undefined symbol: ATL_buildinfo', o, re.M):
            atlas_version = '3.2.1_pre3.3.6'
        else:
            log.info('Status: %d', s)
            log.info('Output: %s', o)
    elif atlas_version == '3.2.1_pre3.3.6':
        dict_append(info, define_macros=[('NO_ATLAS_INFO', -2)])
    else:
        dict_append(info, define_macros=[('ATLAS_INFO', _c_string_literal(atlas_version))])
    result = _cached_atlas_version[key] = (atlas_version, info)
    return result

def get_swig_modulename(source):
    with open(source) as f:
        name = None
        for line in f:
            m = _swig_module_name_match(line)
            if <MASK>:
                name = m.group('name')
                break
    return name

def sample_inputs_to(op_info, device, dtype, requires_grad, op_kwargs=None, **kwargs):
    for njt in _sample_njts(device=device, dtype=dtype, requires_grad=requires_grad, dims=[2, 3, 4]):
        other_dtypes = (d for d in (torch.float32, torch.half, torch.double) if d is not dtype)
        for other_dtype in other_dtypes:
            sample_name = f'{njt.dim()}D: {dtype} -> {other_dtype}'
            yield SampleInput(_clone(njt), kwargs={'dtype': dtype}, name=sample_name)
        if <MASK>:
            other_device = 'cpu'
            sample_name = f'{_describe_njt(njt)}: {device} -> {other_device}'
            yield SampleInput(_clone(njt), kwargs={'device': other_device}, name=sample_name)

def get_center_of_mass(comass: float | None, span: float | None, halflife: float | None, alpha: float | None) -> float:
    valid_count = common.count_not_none(comass, span, halflife, alpha)
    if valid_count > 1:
        raise ValueError('comass, span, halflife, and alpha are mutually exclusive')
    if comass is not None:
        if <MASK>:
            raise ValueError('comass must satisfy: comass >= 0')
    elif span is not None:
        if span < 1:
            raise ValueError('span must satisfy: span >= 1')
        comass = (span - 1) / 2
    elif halflife is not None:
        if halflife <= 0:
            raise ValueError('halflife must satisfy: halflife > 0')
        decay = 1 - np.exp(np.log(0.5) / halflife)
        comass = 1 / decay - 1
    elif alpha is not None:
        if alpha <= 0 or alpha > 1:
            raise ValueError('alpha must satisfy: 0 < alpha <= 1')
        comass = (1 - alpha) / alpha
    else:
        raise ValueError('Must pass one of comass, span, halflife, or alpha')
    return float(comass)

def render(self, context):
    old_setting = context.autoescape
    context.autoescape = self.setting
    output = self.nodelist.render(context)
    context.autoescape = old_setting
    if <MASK>:
        return mark_safe(output)
    else:
        return output

def _create_gather_model(self, input_type, use_variable) -> module.Module:

    class GatherModel(module.Module):
        """A simple model with a single gather."""

        def __init__(self, use_variable):
            """Initializes a GatherModel.

        Args:
          use_variable: If True, creates a variable for weight.
        """
            super().__init__()
            w_val = np.random.randn(128, 32).astype('f4')
            if <MASK>:
                self.w = variables.Variable(w_val)
            else:
                self.w = w_val

        @def_function.function(input_signature=[tensor_spec.TensorSpec(shape=[6], dtype=input_type, name='input_tensor')])
        def __call__(self, input_tensor: core.Tensor) -> Mapping[str, core.Tensor]:
            """Performs a gather operation."""
            out = array_ops.gather_v2(self.w, input_tensor)
            return {'output': out}
    return GatherModel(use_variable)

def _trace_variant_creation(self):
    """Traces a function which outputs a variant `tf.Tensor` for this dataset.

    Note that creating this function involves evaluating an op, and is currently
    only supported when executing eagerly.

    Returns:
      A zero-argument `ConcreteFunction` which outputs a variant `tf.Tensor`.
    """
    variant = self._variant_tensor
    if not isinstance(variant, ops.EagerTensor):
        raise NotImplementedError('Constructing a tf.function that reproduces a given dataset is only supported for datasets created eagerly. Please file a feature request if this is important to you.')
    with context.eager_mode(), ops.device('CPU'):
        graph_def = graph_pb2.GraphDef().FromString(self._as_serialized_graph(external_state_policy=options_lib.ExternalStatePolicy.FAIL).numpy())
    output_node_names = []
    for node in graph_def.node:
        if node.op == '_Retval':
            output_node_names = node.input
    if len(output_node_names) != 1:
        raise AssertionError(f'Dataset graph is expected to only have one return value but found {len(output_node_names)} return values: {output_node_names}.')
    output_node_name = output_node_names[0]
    file_path_nodes = {}
    if <MASK>:
        asset_tracker = self._maybe_track_assets(graph_def)
        for key in asset_tracker:
            assets_list = [array_ops.expand_dims(asset.asset_path, axis=0) for asset in asset_tracker[key]]
            file_path_nodes[key] = array_ops.concat(assets_list, axis=0)
    variant_function = wrap_function.function_from_graph_def(graph_def, inputs=[], outputs=output_node_name + ':0', captures=file_path_nodes)
    for used_function in self._functions():
        used_function.function.add_to_graph(variant_function.graph)
    return variant_function

def recurse(module: nn.Module, curr_fqn: str) -> Generator:
    visited_modules.add(module)
    curr_fqn = f'{curr_fqn}.' if curr_fqn else ''
    for (name, submodule) in module.named_children():
        if submodule in visited_modules:
            continue
        if hasattr(module, dsd_fqn_modifiers) and name in getattr(module, dsd_fqn_modifiers)().values():
            new_fqn = curr_fqn[:-1]
        else:
            new_fqn = f'{curr_fqn}{name}'
        yield from recurse(submodule, new_fqn)
    for (name, obj) in chain(module.named_buffers(recurse=False), module.named_parameters(recurse=False)):
        if name in module._non_persistent_buffers_set:
            continue
        new_fqn = f'{curr_fqn}{name}'
        yield (new_fqn, obj)
    if <MASK>:
        new_fqn = f'{curr_fqn}{nn.modules.module._EXTRA_STATE_KEY_SUFFIX}'
        yield (new_fqn, _EXTRA_STATE())

def _check_unique_non_empty(argnums):
    if isinstance(argnums, tuple):
        if len(argnums) == 0:
            raise RuntimeError('argnums must be non-empty')
        if <MASK>:
            raise RuntimeError(f'argnums elements must be unique, got {argnums}')

def _parametrize_test(self, test, generic_cls, device_cls):
    """Parameterizes the given test function across each op and its associated dtypes."""
    if device_cls is None:
        raise RuntimeError('The @ops decorator is only intended to be used in a device-specific context; use it with instantiate_device_type_tests() instead of instantiate_parametrized_tests()')
    op = check_exhausted_iterator = object()
    for op in self.op_list:
        dtypes: Union[set[torch.dtype], set[None]]
        if isinstance(self.opinfo_dtypes, Sequence):
            dtypes = set(self.opinfo_dtypes)
        elif self.opinfo_dtypes == OpDTypes.unsupported_backward:
            dtypes = set(get_all_dtypes()).difference(op.supported_backward_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported_backward:
            dtypes = op.supported_backward_dtypes(device_cls.device_type)
        elif self.opinfo_dtypes == OpDTypes.unsupported:
            dtypes = set(get_all_dtypes()).difference(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported:
            dtypes = set(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.any_one:
            supported = op.supported_dtypes(device_cls.device_type)
            supported_backward = op.supported_backward_dtypes(device_cls.device_type)
            supported_both = supported.intersection(supported_backward)
            dtype_set = supported_both if len(supported_both) > 0 else supported
            for dtype in ANY_DTYPE_ORDER:
                if dtype in dtype_set:
                    dtypes = {dtype}
                    break
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.any_common_cpu_cuda_one:
            supported = set(op.dtypes).intersection(op.dtypesIfCUDA)
            if supported:
                dtypes = {next((dtype for dtype in ANY_DTYPE_ORDER if dtype in supported))}
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.none:
            dtypes = {None}
        else:
            raise RuntimeError(f'Unknown OpDType: {self.opinfo_dtypes}')
        if self.allowed_dtypes is not None:
            dtypes = dtypes.intersection(self.allowed_dtypes)
        test_name = op.formatted_name
        sample_skips_and_xfails = getattr(test, 'sample_skips_and_xfails', None)
        if <MASK>:
            sample_skips_and_xfails = [rule for rule in sample_skips_and_xfails if rule.op_match_fn(device_cls.device_type, op)]
        for dtype in dtypes:
            param_kwargs = {'op': op}
            _update_param_kwargs(param_kwargs, 'dtype', dtype)
            try:

                @wraps(test)
                def test_wrapper(*args, **kwargs):
                    try:
                        return test(*args, **kwargs)
                    except unittest.SkipTest as e:
                        raise e
                    except Exception as e:
                        tracked_input = get_tracked_input()
                        if PRINT_REPRO_ON_FAILURE and tracked_input is not None:
                            e_tracked = Exception(f'{str(e)}\n\nCaused by {tracked_input.type_desc} at index {tracked_input.index}: {_serialize_sample(tracked_input.val)}')
                            e_tracked._tracked_input = tracked_input
                            raise e_tracked from e
                        raise e
                    finally:
                        clear_tracked_input()
                if self.skip_if_dynamo and (not TEST_WITH_TORCHINDUCTOR):
                    test_wrapper = skipIfTorchDynamo("Policy: we don't run OpInfo tests w/ Dynamo")(test_wrapper)
                test.tracked_input = None
                decorator_fn = partial(op.get_decorators, generic_cls.__name__, test.__name__, device_cls.device_type, dtype)
                if sample_skips_and_xfails is not None:
                    test_wrapper.sample_skips_and_xfails = sample_skips_and_xfails
                yield (test_wrapper, test_name, param_kwargs, decorator_fn)
            except Exception as ex:
                print(f'Failed to instantiate {test_name} for op {op.name}!')
                raise ex
    if op is check_exhausted_iterator:
        raise ValueError('An empty op_list was passed to @ops. Note that this may result from reuse of a generator.')

@cache_on_self
def get_reduction_hint(self) -> ReductionHint:
    reductions = self.reduction_nodes()
    if <MASK>:
        hints = [self.reduction_hint(n) for n in reductions]
        if hints.count(hints[0]) == len(hints):
            reduction_hint_val = hints[0]
        else:
            reduction_hint_val = ReductionHint.DEFAULT
        if reduction_hint_val == ReductionHint.INNER and self.has_non_contiguous_pw_in_reduction_kernel():
            reduction_hint_val = ReductionHint.DEFAULT
    else:
        reduction_hint_val = ReductionHint.DEFAULT
    return reduction_hint_val

def _deserialize_keras_object(identifier, module_objects=None, custom_objects=None, printable_module_name='object'):
    """Turns the serialized form of a Keras object back into an actual object."""
    if identifier is None:
        return None
    if isinstance(identifier, dict):
        config = identifier
        (cls, cls_config) = _class_and_config_for_serialized_keras_object(config, module_objects, custom_objects, printable_module_name)
        if hasattr(cls, 'from_config'):
            arg_spec = tf_inspect.getfullargspec(cls.from_config)
            custom_objects = custom_objects or {}
            if 'custom_objects' in arg_spec.args:
                return cls.from_config(cls_config, custom_objects=dict(list(custom_objects.items())))
            return cls.from_config(cls_config)
        else:
            custom_objects = custom_objects or {}
            return cls(**cls_config)
    elif <MASK>:
        object_name = identifier
        if custom_objects and object_name in custom_objects:
            obj = custom_objects.get(object_name)
        else:
            obj = module_objects.get(object_name)
            if obj is None:
                raise ValueError('Unknown ' + printable_module_name + ': ' + object_name)
        if tf_inspect.isclass(obj):
            return obj()
        return obj
    elif tf_inspect.isfunction(identifier):
        return identifier
    else:
        raise ValueError('Could not interpret serialized %s: %s' % (printable_module_name, identifier))

def _codegen(self, nodes: list[BaseSchedulerNode]) -> None:
    if config.check_stack_no_cycles_TESTING_ONLY:
        import torch._dynamo.convert_frame
        stack = traceback.extract_stack()
        seen: OrderedSet[tuple[str, int | None]] = OrderedSet()
        for frame in reversed(stack):
            if frame.name == '_compile_inner' and frame.filename == torch._dynamo.convert_frame.__file__:
                break
            key = (frame.filename, frame.lineno)
            assert key not in seen, f'Duplicate stack frame {frame.filename}:{frame.lineno}; did you add a decorator to one of the functions in this stack trace?  If so, try using a context manager instead.'
            seen.add(key)
    self.current_device = self.default_device_context
    if self.default_device_context and config.triton.autotune_at_compile_time:
        V.graph.wrapper_code.write_get_raw_stream_header()
    for node in nodes:
        if log.isEnabledFor(logging.DEBUG):
            try:
                log.debug('Generating code for node %s with estimated runtime %f', node.get_name(), node.get_estimated_runtime())
            except Exception:
                log.debug('Generating code for node %s with estimated runtime 0.0', node.get_name())
        self.enter_context(node)
        if (device := node.get_device()):
            if <MASK>:
                self.flush()
            if device != self.current_device:
                if self.current_device and device_need_guard(self.current_device.type):
                    V.graph.wrapper_code.codegen_device_guard_exit()
                self.current_device = device
                if device_need_guard(device.type):
                    assert device.index is not None, 'device should have an index'
                    V.graph.wrapper_code.codegen_device_guard_enter(device.index)
        self.current_node = node
        self.buffer_names_to_free.update(node.last_usage)
        if node.is_template():
            (prologue, template_node, epilogue) = node.get_prologue_template_epilogue(list(node.get_nodes()))
            self.get_backend(device).codegen_template(template_node, epilogue, prologue)
        elif node.is_extern():
            node = typing.cast(ExternKernelSchedulerNode, node)
            self.codegen_extern_call(node)
        elif node.is_foreach():
            node = typing.cast(ForeachKernelSchedulerNode, node)
            backend_ = self.get_backend(device)
            from .codegen.cuda_combined_scheduling import CUDACombinedScheduling
            from .codegen.simd import SIMDScheduling
            if isinstance(backend_, (SIMDScheduling, CUDACombinedScheduling)):
                backend = backend_
            else:
                raise AssertionError(f'type(self)={type(self)!r}')
            backend.codegen_combo_kernel(node)
        elif isinstance(node, (FusedSchedulerNode, SchedulerNode)):
            self.get_backend(device).codegen_node(node)
        else:
            assert isinstance(node, NopKernelSchedulerNode)
            node.mark_run()
        if config.triton.debug_sync_kernel:
            self.get_backend(device).codegen_sync()
        self.available_buffer_names.update(node.get_buffer_names())
        self.completed_operations.update(node.get_operation_names())
        if not isinstance(node, NopKernelSchedulerNode):
            device = node.get_device()
            if device is not None and device.type != 'meta' and self.get_backend(device).ready_to_flush():
                self.flush()
    if self.current_device != self.default_device_context:
        assert self.current_device is not None
        if device_need_guard(self.current_device.type):
            V.graph.wrapper_code.codegen_device_guard_exit()
    self.flush()

@final
@staticmethod
def _parse_errorbars(label: str, err, data: NDFrameT, nseries: int) -> tuple[Any, NDFrameT]:
    """
        Look for error keyword arguments and return the actual errorbar data
        or return the error DataFrame/dict

        Error bars can be specified in several ways:
            Series: the user provides a pandas.Series object of the same
                    length as the data
            ndarray: provides a np.ndarray of the same length as the data
            DataFrame/dict: error values are paired with keys matching the
                    key in the plotted DataFrame
            str: the name of the column within the plotted DataFrame

        Asymmetrical error bars are also supported, however raw error values
        must be provided in this case. For a ``N`` length :class:`Series`, a
        ``2xN`` array should be provided indicating lower and upper (or left
        and right) errors. For a ``MxN`` :class:`DataFrame`, asymmetrical errors
        should be in a ``Mx2xN`` array.
        """
    if err is None:
        return (None, data)

    def match_labels(data, e):
        e = e.reindex(data.index)
        return e
    if isinstance(err, ABCDataFrame):
        err = match_labels(data, err)
    elif isinstance(err, dict):
        pass
    elif isinstance(err, ABCSeries):
        err = match_labels(data, err)
        err = np.atleast_2d(err)
        err = np.tile(err, (nseries, 1))
    elif isinstance(err, str):
        evalues = data[err].values
        data = data[data.columns.drop(err)]
        err = np.atleast_2d(evalues)
        err = np.tile(err, (nseries, 1))
    elif is_list_like(err):
        if is_iterator(err):
            err = np.atleast_2d(list(err))
        else:
            err = np.atleast_2d(err)
        err_shape = err.shape
        if <MASK>:
            err = np.expand_dims(err, 0)
            err_shape = err.shape
            if err_shape[2] != len(data):
                raise ValueError(f'Asymmetrical error bars should be provided with the shape (2, {len(data)})')
        elif isinstance(data, ABCDataFrame) and err.ndim == 3:
            if err_shape[0] != nseries or err_shape[1] != 2 or err_shape[2] != len(data):
                raise ValueError(f'Asymmetrical error bars should be provided with the shape ({nseries}, 2, {len(data)})')
        if len(err) == 1:
            err = np.tile(err, (nseries, 1))
    elif is_number(err):
        err = np.tile([err], (nseries, len(data)))
    else:
        msg = f'No valid {label} detected'
        raise ValueError(msg)
    return (err, data)

def lines(self):
    offset_expr = cexpr_index(self.offset)
    size_expr = cexpr_index(self.size)
    if config.cpp.no_redundant_loops and offset_expr == size_expr:
        return None
    simd = f'simd simdlen({self.simd_nelements}) ' if self.simd_omp and self.simd_nelements > 1 else ''
    if <MASK>:
        line1 = '#pragma omp for'
        if self.parallel > 1:
            line1 += f' collapse({self.parallel})'
        if self.simd_omp:
            line1 = line1.replace(' for ', f' for {simd}')
    elif self.simd_vec:
        line1 = ''
    elif self.simd_omp:
        line1 = f'#pragma omp {simd}'
    elif not self.is_reduction and cpp_builder.is_gcc():
        line1 = '#pragma GCC ivdep'
    else:
        line1 = ''
    offset_str = f'{INDEX_TYPE} {self.var}={offset_expr}'
    size_str = f'{self.var}<{size_expr}'
    if self.steps.is_number:
        steps_str = f'{self.var}+={cexpr_index(self.steps)}'
    else:
        steps_str = f'{self.var}+=({cexpr_index(self.steps)} == 0 ? 1 : {cexpr_index(self.steps)})'
    line2 = f'for({offset_str}; {size_str}; {steps_str})'
    if self.collapsed or not line1:
        return [line2]
    return [line1, line2]

