def expectedFailureMPSPre15(fn):
    import platform
    version = float('.'.join(platform.mac_ver()[0].split('.')[:2]) or -1)
    if <MASK>:
        return fn
    if version < 15.0:
        return expectedFailure('mps')(fn)
    return fn

def crd2idx(crd: Optional[IntTuple], shape: IntTuple, stride: Optional[IntTuple]=None) -> int:
    if stride is None:
        stride = suffix_product(shape)
    if is_tuple(crd):
        if is_tuple(shape) and is_tuple(stride):
            assert len(crd) == len(shape) and len(stride) == len(shape)
            return sum((crd2idx(c, s, d) for (c, s, d) in zip(crd, shape, stride)))
        else:
            raise AssertionError(f'Invalid combination: crd={crd}, shape={shape}')
    else:
        if crd is None:
            crd = 0
        if is_tuple(shape) and is_tuple(stride):
            assert len(shape) == len(stride)
            result = 0
            for i in range(len(shape) - 1, 0, -1):
                result += crd2idx(crd % product(shape[i]), shape[i], stride[i])
                crd = crd // product(shape[i])
            if <MASK>:
                result += crd2idx(crd, shape[0], stride[0])
            return result
        else:
            assert not is_tuple(shape) and (not is_tuple(stride))
            return crd * stride

def _find_loss_from_output_and_spec(output_val, spec_val):
    if spec_val is False:
        return None
    if spec_val is True:
        if not isinstance(output_val, fx.Node):
            raise RuntimeError(f'Loss spec must specify a dynamic value but got {output_val}')
        return output_val
    if isinstance(spec_val, (tuple, list)):
        if not isinstance(output_val, (tuple, list)):
            raise RuntimeError(f'Output value {output_val} must match type of loss specification {spec_val}')
        if len(output_val) != len(spec_val):
            raise RuntimeError(f'Output value {output_val} must match length of loss specification {spec_val}')
        for (out, spec) in zip(output_val, spec_val):
            loss_val = _find_loss_from_output_and_spec(out, spec)
            if loss_val is not None:
                return loss_val
        raise RuntimeError(f'Did not find loss value in specification {spec_val}')
    if <MASK>:
        if not isinstance(output_val, dict):
            raise RuntimeError(f'Output value {output_val} must match type of loss specification {spec_val}')
        if set(output_val.keys()) != set(spec_val.keys()):
            raise RuntimeError(f'Output value {output_val} must match keys of loss specification {spec_val}')
        for k in spec_val:
            loss_val = _find_loss_from_output_and_spec(output_val[k], spec_val[k])
            if loss_val is not None:
                return loss_val
        raise RuntimeError(f'Did not find loss value in specification {spec_val}')
    raise RuntimeError(f'Unsupported type {type(spec_val)} in loss specification')

@register.tag('localize')
def localize_tag(parser, token):
    """
    Force or prevents localization of values.

    Sample usage::

        {% localize off %}
            var pi = {{ 3.1415 }};
        {% endlocalize %}
    """
    use_l10n = None
    bits = list(token.split_contents())
    if <MASK>:
        use_l10n = True
    elif len(bits) > 2 or bits[1] not in ('on', 'off'):
        raise TemplateSyntaxError("%r argument should be 'on' or 'off'" % bits[0])
    else:
        use_l10n = bits[1] == 'on'
    nodelist = parser.parse(('endlocalize',))
    parser.delete_first_token()
    return LocalizeNode(nodelist, use_l10n)

def _get_only_select_mask(self, opts, mask, select_mask=None):
    if select_mask is None:
        select_mask = {}
    select_mask[opts.pk] = {}
    for (field_name, field_mask) in mask.items():
        field = opts.get_field(field_name)
        field_select_mask = select_mask.setdefault(field, {})
        if <MASK>:
            if not field.is_relation:
                raise FieldError(next(iter(field_mask)))
            related_model = field.remote_field.model._meta.concrete_model
            self._get_only_select_mask(related_model._meta, field_mask, field_select_mask)
    return select_mask

def codegen(self, output_name: str, input_names: list[str], output_spec: Spec) -> str:
    """Generate code for softmax operation."""
    if <MASK>:
        raise ValueError('Softmax requires exactly 1 input')
    input_name = input_names[0]
    return f'{output_name} = torch.nn.functional.softmax({input_name}, dim=-1)'

def call_method(self, tx: 'InstructionTranslator', name: str, args: list[VariableTracker], kwargs: dict[str, VariableTracker]) -> 'VariableTracker':
    assert hasattr(self.value, name), f'no stream method found named {name}'
    from ..utils import cmp_name_to_op_mapping, proxy_args_kwargs
    from .builder import wrap_fx_proxy_cls
    if name in ('wait_stream', 'synchronize', 'wait_event'):
        tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self] + args, kwargs))
        return ConstantVariable(None)
    elif name == 'query':
        return wrap_fx_proxy_cls(target_cls=ConstantVariable, tx=tx, proxy=tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self] + args, kwargs)))
    elif name == 'record_event':
        return wrap_fx_proxy_cls(target_cls=EventVariable, tx=tx, proxy=tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self] + args, kwargs)))
    elif name in cmp_name_to_op_mapping and len(args) == 1 and (not kwargs):
        from ..guards import GuardBuilder, install_guard
        if <MASK>:
            install_guard(self.source.make_guard(GuardBuilder.EQUALS_MATCH))
        other = args[0]
        if not isinstance(other, StreamVariable):
            return ConstantVariable.create(NotImplemented)
        if other.source:
            install_guard(self.source.make_guard(GuardBuilder.EQUALS_MATCH))
        return ConstantVariable.create(cmp_name_to_op_mapping[name](self.value, other.value))
    return super().call_method(tx, name, args, kwargs)

def _register_smooth_quant_int_mm_pattern():
    """
    The pattern is:
      (no bias) reshape -> _int_mm -> convert_element_type -> (expand ->) mul -> mul -> reshape
    or
      (with bias) pattern_no_bias -> add (-> reshape -> reshape)
    """

    def get_pattern_no_bias(expand_a_scale: bool, reshape_a: bool=True):
        return CallFunction(aten.mul.Tensor, CallFunction(aten.mul.Tensor, CallFunction(prims.convert_element_type.default, CallFunction(aten._int_mm.default, CallFunction(aten.reshape.default, KeywordArg('a'), KeywordArg('in_shape')) if reshape_a else KeywordArg('a'), KeywordArg('b')), KeywordArg('dtype')), CallFunction(aten.expand.default, KeywordArg('x_scale'), Arg()) if expand_a_scale else KeywordArg('x_scale')), KeywordArg('w_scale'))

    def _with_outer_reshape(pattern):
        return CallFunction(aten.reshape.default, pattern, KeywordArg('out_shape_no_bias'))
    pattern_no_bias_1 = _with_outer_reshape(get_pattern_no_bias(expand_a_scale=False))
    pattern_with_bias_1 = CallFunction(aten.add.Tensor, pattern_no_bias_1, KeywordArg('bias'))
    pattern_no_bias_2 = _with_outer_reshape(get_pattern_no_bias(expand_a_scale=True))
    pattern_with_bias_2 = CallFunction(aten.reshape.default, CallFunction(aten.reshape.default, CallFunction(aten.add.Tensor, pattern_no_bias_2, KeywordArg('bias')), Arg()), KeywordArg('out_shape_with_bias'))
    pattern1_with_no_outer_or_act_reshape = get_pattern_no_bias(expand_a_scale=False, reshape_a=False)
    pattern2_with_no_outer_or_act_reshape = get_pattern_no_bias(expand_a_scale=True, reshape_a=False)

    def _validate_pattern(match: Match):
        if len(match.nodes) not in [4, 5, 6, 7, 10]:
            return False
        aten_int_mm_node = filter_nodes(match.nodes, aten._int_mm.default)[0]
        if not isinstance(aten_int_mm_node.args[1], torch.fx.node.Node):
            return False
        if aten_int_mm_node.args[1].op != 'get_attr':
            return False
        if len(match.nodes) == 10:
            if match.nodes[9].args[1] != match.nodes[6].args[1]:
                return False
        if len(match.nodes) == 10 or (len(match.nodes) == 7 and match.nodes[6].target is aten.add.Tensor):
            bias_idx = 7 if len(match.nodes) == 10 else 6
            bias_node = match.nodes[bias_idx].args[1]
            if not isinstance(bias_node, torch.fx.node.Node):
                return False
            if len(bias_node.meta.get('tensor_meta').shape) != 1:
                return False
        return True
    pattern_to_pass_number = {pattern_no_bias_2: 0, pattern_with_bias_2: 0, pattern_no_bias_1: 1, pattern_with_bias_1: 1, pattern1_with_no_outer_or_act_reshape: 2, pattern2_with_no_outer_or_act_reshape: 2}
    for (pattern, pass_number) in pattern_to_pass_number.items():

        @register_freezing_graph_pattern(pattern, extra_check=_validate_pattern, pass_number=pass_number)
        def _int_mm_weight_prepack(match: Match, *args, **kwargs):
            bias = kwargs.get('bias')
            x = kwargs['a']
            weight = kwargs['b']
            dtype = kwargs['dtype']
            x_scale = kwargs['x_scale']
            w_scale = kwargs['w_scale']
            x_shape = x.meta.get('tensor_meta').shape
            if has_free_symbols(x_shape):
                x_shape = None
            out_node = match.output_node()
            with match.graph.inserting_before(out_node):
                transpose_node = match.graph.call_function(aten.permute.default, args=(weight, [1, 0]))
                contig_node = match.graph.call_function(aten.contiguous.default, args=(transpose_node,))
                packed_weight_inputs = (contig_node, x_shape)
                packed_weight_op = torch.ops.onednn.qlinear_prepack
                prepack_weight_node = match.graph.call_function(packed_weight_op, args=packed_weight_inputs)
                dummy_zp = None
                w_scale = match.graph.call_function(prims.convert_element_type.default, args=(w_scale, torch.float32))
                x_scale_shape = x_scale.meta.get('tensor_meta').shape
                x_scale_is_scalar = False
                if <MASK>:
                    prod = 1
                    for d in x_scale_shape:
                        prod *= d
                    x_scale_is_scalar = prod == 1
                new_args: tuple[Any, ...]
                if x_scale_is_scalar:
                    new_args = (x, x_scale, dummy_zp, prepack_weight_node, w_scale, dummy_zp, bias, 1.0, 0, dtype, 'none', [], '')
                    new_linear_node = match.graph.call_function(torch.ops.onednn.qlinear_pointwise.tensor, args=new_args)
                    out_node.replace_all_uses_with(new_linear_node)
                    new_linear_node.meta.update(out_node.meta)
                else:
                    in_shape = kwargs.get('in_shape')
                    if in_shape is None:
                        x_reshaped = x
                    else:
                        x_reshaped = match.graph.call_function(aten.reshape.default, args=(x, in_shape))
                    new_args = (x_reshaped, 1.0, 0, prepack_weight_node, w_scale, dummy_zp, None, 1.0, 0, dtype, 'none', [], '')
                    new_linear_node = match.graph.call_function(torch.ops.onednn.qlinear_pointwise, args=new_args)
                    new_out_node = match.graph.call_function(aten.mul.Tensor, args=(new_linear_node, x_scale))
                    has_outer_reshape = kwargs.get('out_shape_with_bias') is not None or kwargs.get('out_shape_no_bias') is not None
                    if has_outer_reshape:
                        out_shape = kwargs.get('out_shape_with_bias', kwargs['out_shape_no_bias'])
                    if bias is not None:
                        new_out_node = match.graph.call_function(aten.add.Tensor, args=(new_out_node, bias))
                        if has_outer_reshape:
                            new_out_node = match.graph.call_function(aten.reshape.default, args=(new_out_node, out_shape))
                    elif has_outer_reshape:
                        new_out_node = match.graph.call_function(aten.reshape.default, args=(new_out_node, out_shape))
                    out_node.replace_all_uses_with(new_out_node)
                    new_out_node.meta.update(out_node.meta)
                for node in reversed(match.nodes):
                    match.graph.erase_node(node)
                counters['inductor']['qlinear_weight_prepack_matcher_count'] += 1
                counters['inductor']['qlinear_weight_prepack_matcher_nodes'] += len(match.nodes)

def get_operator_range(chars_range):
    """Generates the characters from chars_range inclusive."""
    if chars_range == 'None' or chars_range is None:
        return None
    if all((item not in chars_range for item in [',', '-'])):
        raise ValueError('The correct format for operator_range is <start>-<end>, or <point>, <start>-<end>')
    ops_start_chars_set = set()
    ranges = chars_range.split(',')
    for item in ranges:
        if <MASK>:
            ops_start_chars_set.add(item.lower())
            continue
        (start, end) = item.split('-')
        ops_start_chars_set.update((chr(c).lower() for c in range(ord(start), ord(end) + 1)))
    return ops_start_chars_set

def _flatten_optim_state(fsdp_param_info: FSDPParamInfo, unflat_osd_state: dict[str, dict[str, Any]], unflat_param_names: list[str]) -> dict[str, Any]:
    """
    Flattens the optimizer state in ``full_optim_state_dict`` for a single
    flat parameter in ``fsdp_param_info`` corresponding to the unflattened
    parameter names in ``unflat_param_names``.

    Args:
        fsdp_param_info (FSDPParamInfo): The FSDP state, the handle, and a
            mapping from FQN to original parameter index.
        unflat_osd_state (Dict[str, Dict[str, Any]]): The "state" part of the
            optimizer state dict corresponding to the unflattened parameters.
        unflat_param_names (List[str]): A :class:`list` of unflattened
            parameter names corresponding to the flat parameter ``flat_param``.

    Returns:
        Dict[str, Any]: A :class:`dict` mapping state names to their values for
        a particular flat parameter. The sharded optimizer state dict's "state"
        part will map a key to this returned value.
    """
    fsdp_state = fsdp_param_info.state
    handle = fsdp_param_info.handle
    flat_param = handle.flat_param
    num_unflat_params = len(unflat_param_names)
    if num_unflat_params <= 0:
        raise AssertionError('Expects at least one unflattened parameter corresponding to the flat parameter')
    unflat_param_shapes = flat_param._shapes
    num_unflat_param_shapes = len(unflat_param_shapes)
    if num_unflat_params != num_unflat_param_shapes:
        raise AssertionError(f'Expects {num_unflat_params} shapes but got {num_unflat_param_shapes}')
    has_state = [bool(unflat_param_name in unflat_osd_state) for unflat_param_name in unflat_param_names]
    if not any(has_state):
        return {}
    unflat_param_states = [_gather_state_dict(unflat_osd_state[unflat_param_name], pg=fsdp_state.process_group, device=fsdp_state.compute_device) if unflat_param_name in unflat_osd_state else None for unflat_param_name in unflat_param_names]
    state_names = None
    for unflat_param_state in unflat_param_states:
        if unflat_param_state is None:
            continue
        if state_names is None:
            state_names = set(unflat_param_state.keys())
        elif state_names != set(unflat_param_state.keys()):
            raise ValueError(f'Differing optimizer state names for the unflattened parameters: {unflat_param_names}')
    if state_names is None:
        raise AssertionError(f'Expected state_names to be not None, got {state_names}')
    flat_state: dict[str, Optional[torch.Tensor]] = {}
    for state_name in state_names:
        state_values = [unflat_param_state[state_name] if unflat_param_state is not None else None for unflat_param_state in unflat_param_states]
        non_none_state_values = [v for v in state_values if v is not None]
        if not non_none_state_values:
            flat_state[state_name] = None
            continue
        are_pos_dim_tensors = are_zero_dim_tensors = are_non_tensors = True
        for v in non_none_state_values:
            are_pos_dim_tensors &= torch.is_tensor(v) and v.dim() > 0
            are_zero_dim_tensors &= _is_zero_dim_tensor(v)
            are_non_tensors &= not torch.is_tensor(v)
        types = {type(v) for v in non_none_state_values}
        if len(types) != 1 or not (are_pos_dim_tensors or are_zero_dim_tensors or are_non_tensors):
            raise ValueError(f'Differing optimizer state types for state {state_name}, values {non_none_state_values}, and unflattened parameter names {unflat_param_names}')
        if are_pos_dim_tensors:
            flat_tensor = _flatten_tensor_optim_state(state_name, state_values, unflat_param_names, unflat_param_shapes, handle)
            if fsdp_state.world_size != 1 and fsdp_state.sharding_strategy != ShardingStrategy.NO_SHARD:
                (sharded_flat_tensor, _) = FlatParamHandle._get_shard(flat_tensor, fsdp_state.rank, fsdp_state.world_size)
            else:
                sharded_flat_tensor = flat_tensor
            flat_state[state_name] = sharded_flat_tensor
        elif are_zero_dim_tensors:
            flat_state[state_name] = _flatten_zero_dim_tensor_optim_state(state_name, state_values, unflat_param_names)
        else:
            if <MASK>:
                raise AssertionError(f'Expected are_non_tensors to be True, got {are_non_tensors}')
            flat_state[state_name] = _flatten_non_tensor_optim_state(state_name, state_values, unflat_param_names)
    return flat_state

def __init__(self, *args, **kwargs) -> None:
    super().__init__(*args, **kwargs)
    self.no_python_abi_suffix = kwargs.get('no_python_abi_suffix', False)
    self.use_ninja = kwargs.get('use_ninja', True)
    if self.use_ninja:
        msg = 'Attempted to use ninja as the BuildExtension backend but %s. Falling back to using the slow distutils backend.'
        if <MASK>:
            logger.warning(msg, 'we could not find ninja.')
            self.use_ninja = False

@doc_controls.do_not_generate_docs
def get_value(x):
    """Returns the value of a variable.

  `backend.get_value` is the complement of `backend.set_value`, and provides
  a generic interface for reading from variables while abstracting away the
  differences between TensorFlow 1.x and 2.x semantics.

  {snippet}

  Args:
      x: input variable.

  Returns:
      A Numpy array.
  """
    if not tensor_util.is_tf_type(x):
        return x
    if <MASK>:
        return x.numpy()
    if not getattr(x, '_in_graph_mode', True):
        with context.eager_mode():
            return x.numpy()
    if ops.executing_eagerly_outside_functions():
        with ops.init_scope():
            return x.numpy()
    with x.graph.as_default():
        return x.eval(session=get_session((x,)))

def expand_hostlist(hostlist):
    """Create a list of hosts out of a SLURM hostlist.

  The order of nodes is preserved and no deduplication is done
  Input: 'n[1-2],m5,o[3-4,6,7-9]')
  Output: ['n1', 'n2', 'm5', 'o3', 'o4', 'o6', 'o7', 'o8', 'o9']
  """

    def split_hostlist(hostlist):
        """Split hostlist at commas outside of range expressions ('[3-5]')."""
        in_brackets = False
        cur_host = ''
        for c in hostlist:
            if in_brackets:
                assert c != '['
                if c == ']':
                    in_brackets = False
            elif <MASK>:
                in_brackets = True
            elif c == ',':
                assert cur_host != ''
                yield cur_host
                cur_host = ''
                continue
            cur_host += c
        if cur_host:
            yield cur_host

    def expand_range_expression(range_exp):
        """Expand a range expression like '3-5' to values 3,4,5."""
        for part in range_exp.split(','):
            sub_range = part.split('-')
            if len(sub_range) == 1:
                sub_range = sub_range * 2
            else:
                assert len(sub_range) == 2
            num_digits = len(sub_range[0])
            for i in range(int(sub_range[0]), int(sub_range[1]) + 1):
                yield str(i).zfill(num_digits)
    hosts = []
    try:
        for part in split_hostlist(hostlist):
            m = re.match('([^,[\\]]*)(\\[([^\\]]+)\\])?$', part)
            if m is None:
                raise ValueError('Invalid part: %s' % part)
            prefix = m.group(1) or ''
            if m.group(3) is None:
                hosts.append(prefix)
            else:
                hosts.extend((prefix + i for i in expand_range_expression(m.group(3))))
    except Exception as e:
        raise ValueError('Invalid hostlist format "%s": %s' % (hostlist, e))
    return hosts

def make_ellipses(gmm, ax):
    for (n, color) in enumerate(colors):
        if <MASK>:
            covariances = gmm.covariances_[n][:2, :2]
        elif gmm.covariance_type == 'tied':
            covariances = gmm.covariances_[:2, :2]
        elif gmm.covariance_type == 'diag':
            covariances = np.diag(gmm.covariances_[n][:2])
        elif gmm.covariance_type == 'spherical':
            covariances = np.eye(gmm.means_.shape[1]) * gmm.covariances_[n]
        (v, w) = np.linalg.eigh(covariances)
        u = w[0] / np.linalg.norm(w[0])
        angle = np.arctan2(u[1], u[0])
        angle = 180 * angle / np.pi
        v = 2.0 * np.sqrt(2.0) * np.sqrt(v)
        ell = mpl.patches.Ellipse(gmm.means_[n, :2], v[0], v[1], angle=180 + angle, color=color)
        ell.set_clip_box(ax.bbox)
        ell.set_alpha(0.5)
        ax.add_artist(ell)
        ax.set_aspect('equal', 'datalim')

def __call__(self, func):
    if not callable(func):
        raise ValueError(f'Function {func} must be a callable.')
    argspec = tf_inspect.getargspec(func)
    if argspec.keywords or argspec.defaults:
        raise ValueError(f'Functions with argument defaults or keywords arguments are not supported. {func} has defaults {argspec.defaults} and keywords {argspec.keywords}.')
    min_args = len(argspec.args)
    max_args = min_args
    if argspec.varargs:
        max_args = 1000000
    argnames = argspec.args
    if tf_inspect.ismethod(func):
        min_args -= 1
        argnames = argnames[1:]
    if self._input_types:
        num = len(self._input_types)
        if num < min_args or num > max_args:
            raise ValueError(f'The number of tf.function input types is not compatible with the allowed arguments of {func}. The tf.function have {num} input types, while the python function allows minimum {min_args} and maximum {max_args} arguments.')
        return _DefinedFunction(func, argnames, self._input_types, self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)
    if <MASK>:
        return _DefinedFunction(func, [], [], self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)
    return _OverloadedFunction(func, argnames, self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)

def convert_variable_to_constant(self, incoming_edge, tensor_data):
    index = incoming_edge.destination.index
    for edge in self.outgoing_edges:
        dest = edge.destination.convertible
        if <MASK>:
            dest.convert_variable_to_constant(edge, tensor_data)
    node = self.converted_self()
    if index >= self._first_function_input:
        node.update_dtype(self._type_attribute, index - self._first_function_input, tensor_data.dtype)

def mutate_to(changed, val, unsafe_alias=False):
    if <MASK>:
        changed_data = changed.data
    else:
        changed_data = changed
    if isinstance(val, TensorBox):
        val = val.data
    if not isinstance(val, ir.StorageBox):
        node = Pointwise.create(device=changed.get_device(), dtype=changed.get_dtype(), inner_fn=val.make_loader(), ranges=changed.get_size())
        assert isinstance(node, (BaseView, MutableBox))
        val = node.data
        assert isinstance(val, ir.StorageBox)
    if isinstance(changed_data, ir.StorageBox) and (not (changed_data.is_input_buffer() or changed_data.is_module_buffer() or isinstance(changed_data.data, ir.NopKernel))):
        val.realize()
        changed_data.data = val.data
        return changed
    ir.MutationLayoutSHOULDREMOVE.realize_into(val, changed_data, unsafe_alias=unsafe_alias)
    return changed

def arg_parser_unpack_method(t: Type, default: str | None, default_init: str | None, *, symint: bool=True) -> str:
    has_default_init = default_init is not None
    if has_default_init and str(t) not in ('ScalarType?', 'ScalarType', 'Device', 'Device?', 'Layout', 'Layout?', 'bool', 'bool?'):
        raise RuntimeError(f"type '{t}' does not supported unpacking with default")
    if isinstance(t, BaseType):
        if t.name in [BaseTy.Tensor, BaseTy.Stream, BaseTy.Storage, BaseTy.Scalar, BaseTy.Dimname]:
            return t.name.name.lower()
        elif t.name == BaseTy.ScalarType:
            return 'scalartypeWithDefault' if has_default_init else 'scalartype'
        elif t.name == BaseTy.Device:
            return 'deviceWithDefault' if has_default_init else 'device'
        elif t.name == BaseTy.DeviceIndex:
            return 'toInt64'
        elif t.name == BaseTy.int:
            return 'toInt64'
        elif t.name == BaseTy.SymInt:
            return 'toSymInt' if symint else 'toInt64'
        elif t.name == BaseTy.bool:
            return 'toBoolWithDefault' if has_default_init else 'toBool'
        elif t.name == BaseTy.float:
            return 'toDouble'
        elif t.name == BaseTy.str:
            return 'stringView'
        elif t.name == BaseTy.Layout:
            return 'layoutWithDefault' if has_default_init else 'layout'
        elif t.name == BaseTy.MemoryFormat:
            return 'memoryformat'
    elif isinstance(t, OptionalType):
        if str(t.elem) == 'Tensor':
            return 'optionalTensor'
        elif str(t.elem) == 'Generator':
            return 'generator'
        elif str(t.elem) == 'Dimname[]':
            return 'toDimnameListOptional'
        elif not has_default_init and default in (None, 'None', '::std::nullopt', 'std::nullopt'):
            return arg_parser_unpack_method(t.elem, None, None, symint=symint) + 'Optional'
        else:
            return arg_parser_unpack_method(t.elem, default, default_init, symint=symint)
    elif isinstance(t, ListType):
        if str(t.elem) == 'Tensor':
            return f'tensorlist_n<{t.size}>' if t.size is not None else 'tensorlist'
        elif str(t.elem) == 'Tensor?':
            return 'list_of_optional_tensors'
        elif str(t.elem) == 'Dimname':
            return 'dimnamelist'
        elif str(t.elem) == 'int':
            return 'intlist'
        elif str(t.elem) == 'float':
            return 'doublelist'
        elif <MASK>:
            return 'symintlist' if symint else 'intlist'
        elif str(t.elem) == 'Scalar':
            return 'scalarlist'
    raise RuntimeError(f"type '{t}' is not supported by PythonArgParser")

def __dtype_from_pep3118(stream, is_subdtype):
    field_spec = {'names': [], 'formats': [], 'offsets': [], 'itemsize': 0}
    offset = 0
    common_alignment = 1
    is_padding = False
    while stream:
        value = None
        if stream.consume('}'):
            break
        shape = None
        if stream.consume('('):
            shape = stream.consume_until(')')
            shape = tuple(map(int, shape.split(',')))
        if stream.next in ('@', '=', '<', '>', '^', '!'):
            byteorder = stream.advance(1)
            if byteorder == '!':
                byteorder = '>'
            stream.byteorder = byteorder
        if stream.byteorder in ('@', '^'):
            type_map = _pep3118_native_map
            type_map_chars = _pep3118_native_typechars
        else:
            type_map = _pep3118_standard_map
            type_map_chars = _pep3118_standard_typechars
        itemsize_str = stream.consume_until(lambda c: not c.isdigit())
        if itemsize_str:
            itemsize = int(itemsize_str)
        else:
            itemsize = 1
        is_padding = False
        if stream.consume('T{'):
            (value, align) = __dtype_from_pep3118(stream, is_subdtype=True)
        elif stream.next in type_map_chars:
            if stream.next == 'Z':
                typechar = stream.advance(2)
            else:
                typechar = stream.advance(1)
            is_padding = typechar == 'x'
            dtypechar = type_map[typechar]
            if dtypechar in 'USV':
                dtypechar += '%d' % itemsize
                itemsize = 1
            numpy_byteorder = {'@': '=', '^': '='}.get(stream.byteorder, stream.byteorder)
            value = dtype(numpy_byteorder + dtypechar)
            align = value.alignment
        elif stream.next in _pep3118_unsupported_map:
            desc = _pep3118_unsupported_map[stream.next]
            raise NotImplementedError(f'Unrepresentable PEP 3118 data type {stream.next!r} ({desc})')
        else:
            raise ValueError(f'Unknown PEP 3118 data type specifier {stream.s!r}')
        extra_offset = 0
        if stream.byteorder == '@':
            start_padding = -offset % align
            intra_padding = -value.itemsize % align
            offset += start_padding
            if intra_padding != 0:
                if itemsize > 1 or (shape is not None and _prod(shape) > 1):
                    value = _add_trailing_padding(value, intra_padding)
                else:
                    extra_offset += intra_padding
            common_alignment = _lcm(align, common_alignment)
        if itemsize != 1:
            value = dtype((value, (itemsize,)))
        if shape is not None:
            value = dtype((value, shape))
        if stream.consume(':'):
            name = stream.consume_until(':')
        else:
            name = None
        if not (is_padding and name is None):
            if name is not None and name in field_spec['names']:
                raise RuntimeError(f"Duplicate field name '{name}' in PEP3118 format")
            field_spec['names'].append(name)
            field_spec['formats'].append(value)
            field_spec['offsets'].append(offset)
        offset += value.itemsize
        offset += extra_offset
        field_spec['itemsize'] = offset
    if stream.byteorder == '@':
        field_spec['itemsize'] += -offset % common_alignment
    if <MASK>:
        ret = field_spec['formats'][0]
    else:
        _fix_names(field_spec)
        ret = dtype(field_spec)
    return (ret, common_alignment)

def op_priority(op_type):
    """Returns the priority of the op.

  If the priority of the op is k, it will be traced if trace_level>=k.
  Args:
    op_type: String name of the operation type.
  Returns:
    Integer value corresponding the priority of the op.
  """
    if op_type in ('Const', 'Shape', 'BroadcastGradientArgs', 'Range', 'VariableShape', 'Fill', 'OneHot', 'ShapeN'):
        return 7
    if op_type in ('Identity', 'Cast', 'Reshape', 'ExpandDims', 'StopGradient', 'PreventGradient', 'Squeeze', 'Gather', 'GatherNd'):
        return 6
    if op_type in ('ConcatV2', 'Concat', 'StridedSlice', 'Slice', 'Pack', 'Tile', 'CollectivePermute', 'SplitV', 'DynamicPartition'):
        return 5
    if op_type in ('Pad', 'RandomUniformInt', 'GreaterEqual'):
        return 4
    if op_type in ('Sum', 'AddV2', 'Add', 'AddN', 'BiasAdd', 'CrossReplicaSum'):
        return 3
    if op_type in ('Neg', 'Sub'):
        return 2
    if <MASK>:
        return 1
    return 2

def validate_schema(schema: FunctionSchema) -> None:
    if <MASK>:
        raise ValueError(f'custom_op only supports functional operators (ops that do not mutate any inputs, do not return views of the inputs, and has at least one return). Got the following non-functional schema: {schema}')
    if schema.arguments.self_arg is not None:
        raise ValueError(f"custom_op does not support arguments named 'self'. Please rename your argument. Got: {schema}")

def _capture_tensor_as_extra_input(self, tensor, name=None):
    self.extra_inputs.append(tensor)
    with ops.control_dependencies(None):
        ph = array_ops.placeholder(tensor.dtype, shape=tensor.get_shape(), name=name)
    if <MASK>:
        handle_data = tensor._handle_data
        if handle_data:
            handle_data = handle_data.SerializeToString()
    else:
        with tensor.graph._c_graph.get() as c_graph:
            handle_data = c_api.GetHandleShapeAndType(c_graph, tensor._as_tf_output())
    if handle_data:
        with ph.graph._c_graph.get() as c_graph:
            c_api.SetHandleShapeAndType(c_graph, ph._as_tf_output(), compat.as_bytes(handle_data))
    self.inputs.append(ph)
    self._captured[tensor.ref()] = ph
    self.extra_args.append(ph)
    if _is_guaranteed_const(tensor):
        with ops.control_dependencies(None):
            return array_ops.guarantee_const(ph)
    else:
        return ph

