@doc_controls.header(_FEATURE_COLUMN_DEPRECATION_WARNING)
@tf_export('feature_column.weighted_categorical_column')
@deprecation.deprecated(None, _FEATURE_COLUMN_DEPRECATION_RUNTIME_WARNING)
def weighted_categorical_column(categorical_column, weight_feature_key, dtype=dtypes.float32):
    """Applies weight values to a `CategoricalColumn`.

  Use this when each of your sparse inputs has both an ID and a value. For
  example, if you're representing text documents as a collection of word
  frequencies, you can provide 2 parallel sparse input features ('terms' and
  'frequencies' below).

  Example:

  Input `tf.Example` objects:

  ```proto
  [
    features {
      feature {
        key: "terms"
        value {bytes_list {value: "very" value: "model"}}
      }
      feature {
        key: "frequencies"
        value {float_list {value: 0.3 value: 0.1}}
      }
    },
    features {
      feature {
        key: "terms"
        value {bytes_list {value: "when" value: "course" value: "human"}}
      }
      feature {
        key: "frequencies"
        value {float_list {value: 0.4 value: 0.1 value: 0.2}}
      }
    }
  ]
  ```

  ```python
  categorical_column = categorical_column_with_hash_bucket(
      column_name='terms', hash_bucket_size=1000)
  weighted_column = weighted_categorical_column(
      categorical_column=categorical_column, weight_feature_key='frequencies')
  columns = [weighted_column, ...]
  features = tf.io.parse_example(..., features=make_parse_example_spec(columns))
  linear_prediction, _, _ = linear_model(features, columns)
  ```

  This assumes the input dictionary contains a `SparseTensor` for key
  'terms', and a `SparseTensor` for key 'frequencies'. These 2 tensors must have
  the same indices and dense shape.

  Args:
    categorical_column: A `CategoricalColumn` created by
      `categorical_column_with_*` functions.
    weight_feature_key: String key for weight values.
    dtype: Type of weights, such as `tf.float32`. Only float and integer weights
      are supported.

  Returns:
    A `CategoricalColumn` composed of two sparse features: one represents id,
    the other represents weight (value) of the id feature in that example.

  Raises:
    ValueError: if `dtype` is not convertible to float.
  """
    if <MASK>:
        raise ValueError('dtype {} is not convertible to float.'.format(dtype))
    return WeightedCategoricalColumn(categorical_column=categorical_column, weight_feature_key=weight_feature_key, dtype=dtype)

def _snapshot_tracked_fakes(self) -> Optional[list[Any]]:
    if <MASK>:
        return None
    from torch._dynamo.variables.builder import TrackedFake

    def maybe_transform_fake(fake: TrackedFake) -> TrackedFake:
        inner_fake = fake.fake if isinstance(fake.fake, (torch.SymInt, torch.SymFloat)) else FakeTensorMeta.from_fake(fake.fake)
        return TrackedFake(inner_fake, fake.source, fake.symbolic_context)
    return [maybe_transform_fake(fake) for fake in self.tracked_fakes]

def process_request(self, request):
    """
        Check for denied User-Agents and rewrite the URL based on
        settings.APPEND_SLASH and settings.PREPEND_WWW
        """
    user_agent = request.META.get('HTTP_USER_AGENT')
    if user_agent is not None:
        for user_agent_regex in settings.DISALLOWED_USER_AGENTS:
            if <MASK>:
                raise PermissionDenied('Forbidden user agent')
    host = request.get_host()
    if settings.PREPEND_WWW and host and (not host.startswith('www.')):
        if self.should_redirect_with_slash(request):
            path = self.get_full_path_with_slash(request)
        else:
            path = request.get_full_path()
        return self.response_redirect_class(f'{request.scheme}://www.{host}{path}')

def run_test(arr, *args, **kwargs):
    for fn in self.array_transforms:
        arg = fn(arr)
        actual = np_array_ops.prod(arg, *args, **kwargs)
        expected = np.prod(arg, *args, **kwargs)
        dtype = kwargs.get('dtype', None)
        if <MASK>:
            self.match_expected_attrs(actual, expected, _NP_to_TF_result_inferred_types[expected.dtype], WeakTensor)
        else:
            self.match_expected_attrs(actual, expected, flexible_dtypes.result_type(dtype)[0], tensor.Tensor)

def gen_constructor_wrapper(target):

    @functools.wraps(target)
    def wrapper(*args, **kwargs):
        proxy = None

        def check_has_proxy(v):
            if isinstance(v, torch.fx.Proxy):
                nonlocal proxy
                proxy = v
        torch.fx.node.map_aggregate(args, check_has_proxy)
        torch.fx.node.map_aggregate(kwargs, check_has_proxy)
        if <MASK>:
            return proxy.tracer.create_proxy('call_function', target, args, kwargs)
        else:
            return target(*args, **kwargs)
    return (wrapper, target)

def argument_str(self, *, method: bool=False, symint: bool=True) -> str:
    type_str = argument_type_str(self.type, symint=symint).replace('const ', '').replace(' &', '')
    name = self.name
    if <MASK>:
        name = 'input'
    if self.default is not None:
        default = {'nullptr': 'None', '::std::nullopt': 'None', 'std::nullopt': 'None', '{}': 'None'}.get(self.default, self.default)
        return f'{type_str} {name}={default}'
    else:
        return f'{type_str} {name}'

def replace_regex(values: ArrayLike, rx: re.Pattern, value, mask: npt.NDArray[np.bool_] | None) -> None:
    """
    Parameters
    ----------
    values : ArrayLike
        Object dtype.
    rx : re.Pattern
    value : Any
    mask : np.ndarray[bool], optional

    Notes
    -----
    Alters values in-place.
    """
    if isna(value) or not isinstance(value, str):

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return value if rx.search(s) is not None else s
            else:
                return s
    else:

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return rx.sub(value, s)
            else:
                return s
    f = np.vectorize(re_replacer, otypes=[np.object_])
    if <MASK>:
        values[:] = f(values)
    else:
        if values.ndim != mask.ndim:
            mask = np.broadcast_to(mask, values.shape)
        values[mask] = f(values[mask])

def _is_causal_behavior(rank: int, world_size: int, i: int, is_causal: bool) -> _CausalBehavior:
    """
    Calculate is_causal behavior for each KV block. The attention can either be
    calculated in full, not at all or with the causal mask applied.
    """
    if <MASK>:
        return _CausalBehavior.NOT_IS_CAUSAL
    if i == 0:
        return _CausalBehavior.IS_CAUSAL
    source_rank = (rank - i) % world_size
    if source_rank < rank or _cp_options.enable_load_balance:
        return _CausalBehavior.NOT_IS_CAUSAL
    else:
        return _CausalBehavior.SKIP

@register_op_strategy(aten._grouped_mm.default)
def grouped_mm_strategy(op_schema: OpSchema) -> OpStrategy:
    mesh = op_schema.get_mesh_from_args()
    mat1_strategy = op_schema.args_schema[0]
    if not isinstance(mat1_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(mat1_strategy)}')
    mat2_strategy = op_schema.args_schema[1]
    if not isinstance(mat2_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(mat2_strategy)}')
    if len(op_schema.args_schema) > 3:
        bias_strategy = op_schema.args_schema[3]
        if bias_strategy is not None:
            raise AssertionError("grouped_mm doesn't support bias yet")
    single_mesh_dim_strategies = []
    offs_placement = None
    if len(op_schema.args_schema) > 2 and op_schema.args_schema[2] is not None:
        offs_placement = Replicate()
    all_replicate: PlacementList = [Replicate(), Replicate(), Replicate(), offs_placement, None]
    partial_replicate: PlacementList = [Partial(), Partial(), Replicate(), offs_placement, None]
    replicate_partial: PlacementList = [Partial(), Replicate(), Partial(), offs_placement, None]
    single_mesh_dim_strategies = [all_replicate, partial_replicate, replicate_partial]
    if mat1_strategy.ndim == 2 and mat2_strategy.ndim == 3:
        replicate_colwise_2x3: PlacementList = [Shard(1), Replicate(), Shard(2), offs_placement, None]
        colwise_rowwise_2x3: PlacementList = [Partial(), Shard(1), Shard(1), offs_placement, None]
        single_mesh_dim_strategies.extend([replicate_colwise_2x3, colwise_rowwise_2x3])
    if mat1_strategy.ndim == 3 and mat2_strategy.ndim == 2:
        colwise_rowwise_3x2: PlacementList = [Partial(), Shard(2), Shard(0), offs_placement, None]
        rowwise_replicate_3x2: PlacementList = [Shard(0), Shard(1), Replicate(), offs_placement, None]
        single_mesh_dim_strategies.extend([colwise_rowwise_3x2, rowwise_replicate_3x2])
    if mat1_strategy.ndim == 2 and mat2_strategy.ndim == 2:
        replicate_colwise_2x2: PlacementList = [Shard(2), Replicate(), Shard(1), offs_placement, None]
        rowwise_replicate_2x2: PlacementList = [Shard(1), Shard(0), Replicate(), offs_placement, None]
        single_mesh_dim_strategies.extend([replicate_colwise_2x2, rowwise_replicate_2x2])
    if mat1_strategy.ndim == 3 and mat2_strategy.ndim == 3:
        replicate_colwise_3x3: PlacementList = [Shard(2), Replicate(), Shard(2), offs_placement, None]
        rowwise_replicate_3x3: PlacementList = [Shard(1), Shard(1), Replicate(), offs_placement, None]
        colwise_rowwise_3x3: PlacementList = [Partial(), Shard(2), Shard(1), offs_placement, None]
        batch_dim_sharding: PlacementList = [Shard(0), Shard(0), Shard(0), offs_placement, None]
        single_mesh_dim_strategies.extend([replicate_colwise_3x3, rowwise_replicate_3x3, colwise_rowwise_3x3, batch_dim_sharding])

    def valid_grouped_mm_strides(input_specs: list[DTensorSpec], output_specs: tuple[Optional[DTensorSpec], ...]) -> bool:

        def local_meta(spec: OpSpec, placements: tuple[Placement, ...]) -> TensorMeta:
            if not isinstance(spec.output_specs, DTensorSpec):
                raise AssertionError(f'Expected DTensorSpec, got {type(spec.output_specs)}')
            if not isinstance(spec.output_specs.tensor_meta, TensorMeta):
                raise AssertionError(f'Expected TensorMeta, got {type(spec.output_specs.tensor_meta)}')
            meta: TensorMeta = spec.output_specs.tensor_meta
            local_stride = compute_local_stride(meta.stride, mesh, placements)
            (local_shape, _) = compute_local_shape_and_global_offset(meta.shape, mesh, placements)
            return TensorMeta(torch.Size(local_shape), local_stride, meta.dtype)
        mat1_meta = local_meta(mat1_strategy.strategies[0], input_specs[0].placements)
        mat2_meta = local_meta(mat2_strategy.strategies[0], input_specs[1].placements)

        def check_valid_strides(meta: TensorMeta) -> bool:
            end_dim = len(meta.shape) - 1
            alignment = 16 // meta.dtype.itemsize
            if meta.stride[end_dim - 1] == 1 and meta.stride[end_dim] >= max(1, meta.shape[end_dim - 1]):
                if meta.stride[end_dim] % alignment != 0:
                    return False
            elif <MASK>:
                if meta.stride[end_dim - 1] % alignment != 0:
                    return False
            else:
                return False
            return True
        mat1_valid = check_valid_strides(mat1_meta)
        mat2_valid = check_valid_strides(mat2_meta)
        return mat1_valid and mat2_valid
    return expand_to_full_mesh_op_strategy(mesh, op_schema, single_mesh_dim_strategies, input_index=1, is_valid_strategy_cb=valid_grouped_mm_strides)

def get_base_chain(self, model):
    """
        Return a list of parent classes leading to `model` (ordered from
        closest to most distant ancestor). This has to handle the case where
        `model` is a grandparent or even more distant relation.
        """
    if not self.parents:
        return []
    if model in self.parents:
        return [model]
    for parent in self.parents:
        res = parent._meta.get_base_chain(model)
        if <MASK>:
            res.insert(0, parent)
            return res
    return []

def persistent_load(saved_id):
    assert isinstance(saved_id, tuple)
    typename = _maybe_decode_ascii(saved_id[0])
    data = saved_id[1:]
    if typename == 'storage':
        (storage_type, key, location, size) = data
        if storage_type is torch.UntypedStorage:
            dtype = torch.uint8
        else:
            dtype = storage_type.dtype
        if key not in loaded_storages:
            load_tensor(dtype, size, key, _maybe_decode_ascii(location), restore_location)
        storage = loaded_storages[key]
        return torch.storage.TypedStorage(wrap_storage=storage._untyped_storage, dtype=dtype, _internal=True)
    elif typename == 'reduce_package':
        if len(data) == 2:
            (func, args) = data
            return func(self, *args)
        (reduce_id, func, args) = data
        if <MASK>:
            loaded_reduces[reduce_id] = func(self, *args)
        return loaded_reduces[reduce_id]
    else:
        f"Unknown typename for persistent_load, expected 'storage' or 'reduce_package' but got '{typename}'"

