@torch.library.impl(lib, 'fused_all_gather_matmul', 'Meta')
def _fused_all_gather_matmul_fallback(A_shard: torch.Tensor, Bs: list[torch.Tensor], gather_dim: int, group_name: str, *, return_A: bool=True) -> tuple[torch.Tensor | None, list[torch.Tensor]]:
    group_size = c10d._get_group_size_by_name(group_name)
    A = torch.ops._c10d_functional.all_gather_into_tensor(A_shard.contiguous(), group_size, group_name)
    A = torch.ops._c10d_functional.wait_tensor(A)
    if <MASK>:
        A_splits = A.chunk(group_size)
        A_mm = torch.cat(A_splits, dim=-1)
        res = [torch.matmul(A_mm, B) for B in Bs]
        if return_A:
            return (A_mm, res)
        else:
            return (None, res)
    A = A.view(group_size, *A_shard.shape).movedim(gather_dim + 1, 1).flatten(0, 1)
    res = [torch.matmul(A, B).movedim(0, gather_dim) for B in Bs]
    if return_A:
        return (A.movedim(0, gather_dim), res)
    else:
        return (None, res)

def traverse(obj, visit, parents=[], result=None, *args, **kwargs):
    '''Traverse f2py data structure with the following visit function:

    def visit(item, parents, result, *args, **kwargs):
        """

        parents is a list of key-"f2py data structure" pairs from which
        items are taken from.

        result is a f2py data structure that is filled with the
        return value of the visit function.

        item is 2-tuple (index, value) if parents[-1][1] is a list
        item is 2-tuple (key, value) if parents[-1][1] is a dict

        The return value of visit must be None, or of the same kind as
        item, that is, if parents[-1] is a list, the return value must
        be 2-tuple (new_index, new_value), or if parents[-1] is a
        dict, the return value must be 2-tuple (new_key, new_value).

        If new_index or new_value is None, the return value of visit
        is ignored, that is, it will not be added to the result.

        If the return value is None, the content of obj will be
        traversed, otherwise not.
        """
    '''
    if _is_visit_pair(obj):
        if obj[0] == 'parent_block':
            return obj
        new_result = visit(obj, parents, result, *args, **kwargs)
        if new_result is not None:
            assert _is_visit_pair(new_result)
            return new_result
        parent = obj
        (result_key, obj) = obj
    else:
        parent = (None, obj)
        result_key = None
    if isinstance(obj, list):
        new_result = []
        for (index, value) in enumerate(obj):
            (new_index, new_item) = traverse((index, value), visit, parents + [parent], result, *args, **kwargs)
            if new_index is not None:
                new_result.append(new_item)
    elif isinstance(obj, dict):
        new_result = {}
        for (key, value) in obj.items():
            (new_key, new_value) = traverse((key, value), visit, parents + [parent], result, *args, **kwargs)
            if new_key is not None:
                new_result[new_key] = new_value
    else:
        new_result = obj
    if <MASK>:
        return new_result
    return (result_key, new_result)

