def _partition_value(self, tensor: torch.Tensor, mesh: DeviceMesh, mesh_dim: int) -> torch.Tensor:
    """
        For example, consider 4 ranks, a (3,) replicated tensor, and 2-norm:
            Ranks 0 and 1: sqrt(t1^2 + t2^2 + t3^3)
        To convert from replicated to partial, we want f(x) such that
            sqrt(t1^2 + t2^2 + t3^3) = sqrt(4f(t1)^2 + 4f(t2)^2 + 4f(t3)^2)
                                     = sqrt(4) sqrt(f(t1)^2 + f(t2)^2 + f(t3)^2).
        One such f(x) is f(x) = x / sqrt(4). This generalizes to d ranks and
        p-norm as f(x) = x / d^(1/p).
        """
    if self.reduce_op in ('max', 'min'):
        return tensor
    elif self.reduce_op == 'sum':
        if <MASK>:
            raise NotImplementedError(f'Unsupported norm type:: {self.norm_type}')
        elif self.norm_type == 1:
            return tensor / mesh.size(mesh_dim)
        if not isinstance(self.norm_type, (int, float)):
            raise AssertionError(f'Expected int or float, got {type(self.norm_type)}')
        return tensor / math.pow(mesh.size(mesh_dim), 1 / self.norm_type)
    raise NotImplementedError(self.reduce_op)

@register_lowering(aten.mm, type_promotion_kind=None)
def tuned_mm(mat1, mat2, out_dtype=None, *, layout=None):
    """
    Lowering for autotuning aten.mm with different backends (Aten, Triton, CUTLASS, etc.)
    """
    if out_dtype is not None:
        input_dtype = mat1.get_dtype()
        torch._check(mat2.get_dtype() == input_dtype, lambda : 'input dtypes must be the same')
        torch._check(mat1.get_device().type == 'cuda', lambda : 'out_dtype is only supported for CUDA')
        torch._check(out_dtype == input_dtype or (out_dtype == torch.float32 and input_dtype in (torch.float16, torch.bfloat16)), lambda : 'out_dtype must be the same as input dtype or fp32 for fp16/bf16 inputs')
    if <MASK>:
        mat1 = lowerings[aten.unsqueeze](mat1, -1)
        mat2 = lowerings[aten.unsqueeze](mat2, 0)
        (args, kwargs) = transform_args(args=[mat1, mat2], kwargs={}, broadcast=True, type_promotion_kind=None, convert_input_to_bool=False)
        if inductor_config.triton.codegen_upcast_to_fp32 and mat1.dtype in [torch.float16, torch.bfloat16]:

            def _to_dtype(x):
                return ops.to_dtype(x, mat1.dtype, use_compute_types=False)
            args = [make_pointwise(_to_dtype)(x) for x in args]
        mul_pointwise = make_pointwise(ops.dot)(*args)
        dot_reduction = make_reduction('dot')(mul_pointwise, 1)
        return dot_reduction
    (m, n, k, layout, mat1, mat2) = mm_args(mat1, mat2, layout=layout, out_dtype=out_dtype)
    (static_shape, is_nonzero) = _is_static_problem(layout)
    name = 'mm'
    kernel_inputs = MMKernelInputs([mat1, mat2], out_dtype=out_dtype)
    counters['aten_mm_info'][f'aten.mm_{m}_{n}_{k}'] += 1
    log.info('Tuned aten.mm: m=%s, n=%s, k=%s, mat1_dtype=%s, mat2_dtype=%s, output_layout=%s', m, n, k, mat1.get_dtype(), mat2.get_dtype(), layout)
    choices: list[ChoiceCaller] = []
    (static_shape, is_nonzero) = _is_static_problem(layout)
    aten_handler: ExternKernelChoice = aten_mm
    aten_extra_kwargs: dict[str, Any] = {}
    if out_dtype is not None:
        aten_handler = aten_mm_dtype
        aten_extra_kwargs = {'out_dtype': out_dtype}
    templates_to_use: list[Union[ExternKernelChoice, KernelTemplate]] = []
    kwarg_overrides: dict[str, dict[str, Any]] = {}
    if use_aten_gemm_kernels():
        templates_to_use.append(aten_handler)
        if aten_extra_kwargs:
            kwarg_overrides[aten_handler.uid] = aten_extra_kwargs
    if out_dtype is None and is_nonzero and use_triton_template(layout, check_max_autotune=True):
        if use_decompose_k_choice(m, n, k):
            templates_to_use.append(decompose_k_subgraph_template)
        is_exhaustive = inductor_config.max_autotune_gemm_search_space == 'exhaustive'
        if is_exhaustive or not use_decompose_k_choice(m, n, k, threshold_multiple=2):
            templates_to_use.append(mm_template)
            if use_triton_tma_template(mat1, mat2, output_layout=layout):
                templates_to_use.append(persistent_tma_mm_template)
            if use_triton_blackwell_tma_template(mat1, mat2, output_layout=layout):
                templates_to_use.append(blackwell_ws_persistent_device_tma_mm_template)
        templates_to_use.append(mm_contiguous_subgraph_template)
    choices.extend(V.choices.get_template_configs(kernel_inputs, templates_to_use, 'mm', kwarg_overrides=kwarg_overrides))
    if out_dtype is None and is_nonzero and use_cutlass_template(layout, m, n, k) and _use_cutlass_for_op('mm'):
        CUTLASS3xGemmTemplate.add_cutlass_gemm_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and is_nonzero and use_ck_gemm_template(layout, m, n, k):
        CKGemmTemplate.add_ck_gemm_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and is_nonzero and use_ck_tile_gemm_template(layout, m, n, k):
        CKTileGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and use_cpp_gemm_template(layout, mat1, mat2):
        CppGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    input_nodes = [mat1, mat2]
    if out_dtype is None and is_nonzero and use_triton_template(layout) and torch._inductor.config.run_autoheuristic(name) and is_triton(mat1):
        always_included = []
        if use_aten_gemm_kernels():
            always_included.append('extern_mm')
        num_choices_before_extra_configs = len(choices)
        choices.extend(V.choices.get_template_configs(kernel_inputs, [mm_template], 'mm-ah'))
        ah_choices = mm_autoheuristic(mat1, mat2, m, n, k, choices, name, input_nodes, mm_operations(), None, top_k=10, always_included=always_included)
        if not torch._inductor.config.collect_autoheuristic(name):
            if ah_choices is not None and len(ah_choices) > 0:
                choices = [choice for choice in choices if choice in ah_choices]
            else:
                choices = choices[:num_choices_before_extra_configs]
    if out_dtype is None:
        for k in inductor_config.external_matmul:
            choices.append(lazy_register_extern_choice(k).bind(kernel_inputs.nodes(), layout))
    best_config_future = None
    if out_dtype is None and torch._inductor.config.remote_gemm_autotune_cache:
        best_config_future = gen_best_config(mat1, mat2)
    return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout, best_config_future=best_config_future)

def solve_lookup_type(self, lookup, summarize=False):
    """
        Solve the lookup type from the lookup (e.g.: 'foobar__id__icontains').
        """
    lookup_splitted = lookup.split(LOOKUP_SEP)
    if self.annotations:
        (annotation, expression_lookups) = refs_expression(lookup_splitted, self.annotations)
        if annotation:
            expression = self.annotations[annotation]
            if <MASK>:
                expression = Ref(annotation, expression)
            return (expression_lookups, (), expression)
    (_, field, _, lookup_parts) = self.names_to_path(lookup_splitted, self.get_meta())
    field_parts = lookup_splitted[0:len(lookup_splitted) - len(lookup_parts)]
    if len(lookup_parts) > 1 and (not field_parts):
        raise FieldError('Invalid lookup "%s" for model %s".' % (lookup, self.get_meta().model.__name__))
    return (lookup_parts, field_parts, False)

def build_param(ctx, py_arg, self_name, kwarg_only, pdt_arg_type=None):
    name = py_arg.arg
    r = ctx.make_range(py_arg.lineno, py_arg.col_offset, py_arg.col_offset + len(name))
    if getattr(py_arg, 'annotation', None) is not None:
        annotation_expr = build_expr(ctx, py_arg.annotation)
    elif pdt_arg_type:
        annotation_expr = Var(Ident(r, pdt_arg_type))
    elif <MASK>:
        annotation_expr = Var(Ident(r, self_name))
    else:
        annotation_expr = EmptyTypeAnnotation(r)
    return Param(annotation_expr, Ident(r, name), kwarg_only)

def materialize_arg(x):
    if isinstance(x, fx.Node) and isinstance(x.meta['val'], torch.Tensor):
        return _remove_symbols_without_guarding(x.meta['val'], fallback=4096)
    elif isinstance(x, fx.Node) and isinstance(x.meta['val'], torch.SymInt):
        return hint_int(x.meta['val'], fallback=4096)
    elif <MASK>:
        return 1.0
    elif isinstance(x, fx.Node) and isinstance(x.meta['val'], torch.SymBool):
        return True
    else:
        return x

def calc_info(self):
    src_dirs = self.get_src_dirs()
    src_dir = ''
    for d in src_dirs:
        if <MASK>:
            src_dir = d
            break
    if not src_dir:
        return
    if sys.platform == 'win32':
        agg2_srcs = glob(os.path.join(src_dir, 'src', 'platform', 'win32', 'agg_win32_bmp.cpp'))
    else:
        agg2_srcs = glob(os.path.join(src_dir, 'src', '*.cpp'))
        agg2_srcs += [os.path.join(src_dir, 'src', 'platform', 'X11', 'agg_platform_support.cpp')]
    info = {'libraries': [('agg2_src', {'sources': agg2_srcs, 'include_dirs': [os.path.join(src_dir, 'include')]})], 'include_dirs': [os.path.join(src_dir, 'include')]}
    if info:
        self.set_info(**info)
    return

def _exponential_space_einsum_v1(equation, *inputs):
    """Fallback implementation that supports summing an index over > 2 inputs."""
    inputs = list(inputs)
    input_shapes = [x.shape for x in inputs]
    (idx_in, idx_out) = _einsum_v1_parse_and_resolve_equation(equation, input_shapes)
    idx_all = set(''.join(idx_in) + idx_out)
    indices = ''.join(sorted(idx_all))
    missing_idx = set(idx_out).difference(idx_all)
    if missing_idx:
        raise ValueError(f'Unknown output axes: {missing_idx}.')
    axis_order = {}
    for ax in indices:
        if ax not in idx_out:
            axis_order[ax] = len(axis_order)
    for ax in idx_out:
        axis_order[ax] = len(axis_order)
    for (i, (input_, axes_)) in enumerate(zip(inputs, idx_in)):
        if input_.shape.ndims != len(axes_):
            raise ValueError(f'Input {i} with axes {axes_} has incorrect number of dimensions (expected {len(axes_)}, got {input_.shape.ndims}).')
        sorted_idx = sorted(axes_, key=axis_order.get)
        if len(set(axes_)) != len(axes_):
            raise ValueError(f'Subscript not supported: an axis appears more than once: {axes_}.')
        if <MASK>:
            permuted = [axes_.find(ax) for ax in sorted_idx]
            inputs[i] = array_ops.transpose(input_, permuted)
            idx_in[i] = sorted_idx
    reduction_idx = []
    shapes = [[dim if dim else -1 for dim in tensor.shape.as_list()] for tensor in inputs]
    for (j, ax) in enumerate(sorted(idx_all, key=axis_order.get)):
        dims = []
        for (i, idx) in enumerate(idx_in):
            if ax not in idx:
                shapes[i].insert(j, 1)
            else:
                dim = shapes[i][j]
                if isinstance(dim, int) and dim > 1:
                    dims.append(dim)
        if len(set(dims)) > 1:
            raise ValueError(f'Dimension mismatch on axis: {ax}. Found {len(set(dims))}, expected 1.')
        if ax not in idx_out:
            reduction_idx.append(j)
    expanded_inputs = [array_ops.reshape(input_, shape) for (input_, shape) in zip(inputs, shapes)]
    expanded_output = 1
    for input_ in expanded_inputs:
        expanded_output *= input_
    return math_ops.reduce_sum(expanded_output, reduction_idx)

def _resource_apply_sparse_duplicate_indices(self, grad, var, indices, **kwargs):
    if <MASK>:
        return super(SGD, self)._resource_apply_sparse_duplicate_indices(grad, var, indices, **kwargs)
    else:
        (var_device, var_dtype) = (var.device, var.dtype.base_dtype)
        coefficients = kwargs.get('apply_state', {}).get((var_device, var_dtype)) or self._fallback_apply_state(var_device, var_dtype)
        return gen_resource_variable_ops.ResourceScatterAdd(resource=var.handle, indices=indices, updates=-grad * coefficients['lr_t'])

def _get_loc_level(self, key, level: int | list[int]=0):
    """
        get_loc_level but with `level` known to be positional, not name-based.
        """

    def maybe_mi_droplevels(indexer, levels):
        """
            If level does not exist or all levels were dropped, the exception
            has to be handled outside.
            """
        new_index = self[indexer]
        for i in sorted(levels, reverse=True):
            new_index = new_index._drop_level_numbers([i])
        return new_index
    if isinstance(level, (tuple, list)):
        if <MASK>:
            raise AssertionError('Key for location must have same length as number of levels')
        result = None
        for (lev, k) in zip(level, key, strict=True):
            (loc, new_index) = self._get_loc_level(k, level=lev)
            if isinstance(loc, slice):
                mask = np.zeros(len(self), dtype=bool)
                mask[loc] = True
                loc = mask
            result = loc if result is None else result & loc
        try:
            mi = maybe_mi_droplevels(result, level)
        except ValueError:
            mi = self[result]
        return (result, mi)
    if isinstance(key, list):
        key = tuple(key)
    if isinstance(key, tuple) and level == 0:
        try:
            if key in self.levels[0]:
                indexer = self._get_level_indexer(key, level=level)
                new_index = maybe_mi_droplevels(indexer, [0])
                return (indexer, new_index)
        except (TypeError, InvalidIndexError):
            pass
        if not any((isinstance(k, slice) for k in key)):
            if len(key) == self.nlevels and self.is_unique:
                try:
                    return (self._engine.get_loc(key), None)
                except KeyError as err:
                    raise KeyError(key) from err
                except TypeError:
                    pass
            indexer = self.get_loc(key)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            if len(ilevels) == self.nlevels:
                if is_integer(indexer):
                    return (indexer, None)
                ilevels = [i for i in range(len(key)) if (not isinstance(key[i], str) or not self.levels[i]._supports_partial_string_indexing) and key[i] != slice(None, None)]
                if len(ilevels) == self.nlevels:
                    ilevels = []
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
        else:
            indexer = None
            for (i, k) in enumerate(key):
                if not isinstance(k, slice):
                    loc_level = self._get_level_indexer(k, level=i)
                    if isinstance(loc_level, slice):
                        if com.is_null_slice(loc_level) or com.is_full_slice(loc_level, len(self)):
                            continue
                        k_index = np.zeros(len(self), dtype=bool)
                        k_index[loc_level] = True
                    else:
                        k_index = loc_level
                elif com.is_null_slice(k):
                    continue
                else:
                    raise TypeError(f'Expected label or tuple of labels, got {key}')
                if indexer is None:
                    indexer = k_index
                else:
                    indexer &= k_index
            if indexer is None:
                indexer = slice(None, None)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
    else:
        indexer = self._get_level_indexer(key, level=level)
        if isinstance(key, str) and self.levels[level]._supports_partial_string_indexing:
            check = self.levels[level].get_loc(key)
            if not is_integer(check):
                return (indexer, self[indexer])
        try:
            result_index = maybe_mi_droplevels(indexer, [level])
        except ValueError:
            result_index = self[indexer]
        return (indexer, result_index)

def inner(a: ArrayLike, b: ArrayLike, /):
    dtype = _dtypes_impl.result_type_impl(a, b)
    is_half = dtype == torch.float16 and (a.is_cpu or b.is_cpu)
    is_bool = dtype == torch.bool
    if is_half:
        dtype = torch.float32
    elif <MASK>:
        dtype = torch.uint8
    a = _util.cast_if_needed(a, dtype)
    b = _util.cast_if_needed(b, dtype)
    result = torch.inner(a, b)
    if is_half:
        result = result.to(torch.float16)
    elif is_bool:
        result = result.to(torch.bool)
    return result

@register_decomposition_for_jvp(aten.native_layer_norm_backward)
def native_layer_norm_backward(grad_out: Tensor, input: Tensor, normalized_shape: list[int], mean: Tensor, rstd: Tensor, weight: Optional[Tensor], bias: Optional[Tensor], output_mask: list[bool]) -> tuple[Optional[Tensor], Optional[Tensor], Optional[Tensor]]:
    input_shape = input.shape
    input_ndim = input.dim()
    axis = input_ndim - len(normalized_shape)
    inner_dims = input_shape[axis:]
    outer_dims = input_shape[:axis]
    inner_dim_indices = list(range(axis, input_ndim))
    outer_dim_indices = list(range(axis))
    N = 1
    for i in inner_dims:
        N *= i
    M = 1
    for i in outer_dims:
        M *= i
    if M <= 0 or N <= 0:
        return (input.new_zeros(input_shape), input.new_zeros(input_shape[axis:]), input.new_zeros(input_shape[axis:]))
    (mean_, rstd_) = recompute_mean_var(input, rstd, inner_dim_indices, keepdim=True)
    x_hat = (input - mean_) * rstd_
    if <MASK>:
        grad_x_hat = grad_out * weight
    else:
        grad_x_hat = grad_out
    a = grad_x_hat * N
    b = torch.sum(grad_x_hat, inner_dim_indices, True)
    c1 = torch.mul(grad_x_hat, x_hat)
    c2 = torch.sum(c1, inner_dim_indices, True)
    c3 = torch.mul(x_hat, c2)
    inner = a - b - c3
    if output_mask[0]:
        d_input: Optional[Tensor] = rstd_ / N * inner
    else:
        d_input = torch.zeros_like(input)
    if output_mask[1] and weight is not None:
        if len(outer_dim_indices) > 0:
            d_weight: Optional[Tensor] = torch.sum(grad_out * x_hat, outer_dim_indices, False)
        else:
            d_weight = grad_out * x_hat
    elif weight is not None:
        d_weight = torch.zeros_like(weight)
    else:
        d_weight = torch.zeros(())
    if output_mask[2] and bias is not None:
        if len(outer_dim_indices) > 0:
            d_bias: Optional[Tensor] = torch.sum(grad_out, outer_dim_indices, False)
        else:
            d_bias = grad_out.clone()
    elif bias is not None:
        d_bias = torch.zeros_like(bias)
    else:
        d_bias = torch.zeros(())
    return (d_input, d_weight, d_bias)

def _ConcatGradHelper(op: ops.Operation, grad, start_value_index, end_value_index, dim_index):
    """Gradient for concat op.

  Args:
    op: An operation.
    grad: `Tensor` or `IndexedSlices` representing the gradients with respect to
      each output of the op.
    start_value_index: An integer index of the first value in the op.inputs.
    end_value_index: An integer index of the last value in the op.inputs.
    dim_index: An integer index of concat_dim or axis parameter in op.inputs.

  Returns:
    Tensors representing the partial gradients with respect to each input
    of the op.

  Raises:
    ValueError: if concat_dim/axis is not statically known.
  """

    def _CreateDenseMaskAndBegin(sizes, concat_dim):
        """Create variables for iteratively slicing a dense gradients tensor."""
        shape_of_shape = array_ops.shape(sizes[0])
        mask = array_ops.concat([array_ops.zeros(array_ops.expand_dims(concat_dim, 0), dtype=dtypes.int32), [1], array_ops.zeros(shape_of_shape - concat_dim - 1, dtype=dtypes.int32)], 0)
        begin = array_ops.zeros(shape_of_shape, dtype=dtypes.int32)
        return (mask, begin)

    def _ExtractInputShapes(inputs):
        """Extract the shapes of a set of input tensors."""
        if context.executing_eagerly():
            return array_ops.shape_n(inputs)
        sizes = []
        fully_known = True
        for x in inputs:
            input_shape = array_ops.shape(x)
            if not isinstance(input_shape, tensor.Tensor) or input_shape.op.type != 'Const':
                fully_known = False
                break
            sizes.append(input_shape)
        if fully_known:
            return sizes
        else:
            return array_ops.shape_n(inputs)
    if len(op.inputs) == 2:
        return grad + [None] if end_value_index <= dim_index else [None] + grad
    concat_dim = op.inputs[dim_index]
    input_values = op.inputs[start_value_index:end_value_index]
    out_grads = []
    if isinstance(grad, tensor.Tensor):
        if context.executing_eagerly() or isinstance(concat_dim, ops.EagerTensor):
            non_neg_concat_dim = concat_dim._numpy().item(0) % input_values[0]._rank()
            sizes = pywrap_tfe.TFE_Py_TensorShapeSlice(input_values, non_neg_concat_dim)
            out_grads = array_ops.split(grad, sizes, non_neg_concat_dim)
        else:
            if constant_op.is_constant(concat_dim):
                grad_context = control_flow_util.GetOutputContext(grad.op)
                dim_context = control_flow_util.GetOutputContext(concat_dim.op)
                if dim_context != grad_context:
                    value = tensor_util.constant_value(concat_dim)
                    concat_dim = constant_op.constant(value=value, dtype=concat_dim.dtype)
            non_neg_concat_dim = concat_dim % array_ops.rank(input_values[0])
            sizes = _ExtractInputShapes(input_values)
            if len(sizes) > 16:
                sizes = array_ops.squeeze(array_ops.slice(array_ops_stack.stack(sizes, axis=1), [non_neg_concat_dim, 0], [1, -1]))
                out_grads = array_ops.split(grad, sizes, non_neg_concat_dim)
            else:
                offset = gen_array_ops.concat_offset(non_neg_concat_dim, sizes)
                for (begin, size) in zip(offset, sizes):
                    out_grads.append(array_ops.slice(grad, begin, size))
    elif isinstance(grad, indexed_slices_lib.IndexedSlices):
        non_neg_concat_dim = concat_dim % array_ops.rank(input_values[0])
        concat_dim_static = tensor_util.constant_value(concat_dim)
        if <MASK>:
            raise ValueError('Can only compute IndexedSlices gradient with statically-known concat_dim')
        if concat_dim_static < 0:
            rank = tensor_util.constant_value(array_ops.rank(input_values[0]))
            if rank is None:
                raise ValueError('Can only compute IndexedSlices gradient with negative concat_dim when first value rank is statically-known.')
            concat_dim_static %= rank
        sizes = [array_ops.shape(x) for x in input_values]
        if concat_dim_static > 0:
            (mask, begin) = _CreateDenseMaskAndBegin(sizes, non_neg_concat_dim)
            for size in sizes:
                new_values = array_ops.slice(grad.values, begin, array_ops.concat([[-1], array_ops.slice(size, [1], [-1])], 0))
                out_grads.append(indexed_slices_lib.IndexedSlices(new_values, grad.indices, size))
                begin = math_ops.add(begin, size * mask)
        else:
            start = constant_op.constant(0, dtype=grad.indices.dtype)
            for size in sizes:
                size_concat_dim = array_ops.gather(size, non_neg_concat_dim)
                if size_concat_dim.dtype != grad.indices.dtype:
                    size_concat_dim = math_ops.cast(size_concat_dim, dtype=grad.indices.dtype)
                end = start + size_concat_dim
                indices_to_select = array_ops.squeeze(array_ops.where(math_ops.logical_and(grad.indices >= start, grad.indices < end)), axis=[1])
                new_indices = array_ops.gather(grad.indices, indices_to_select) - start
                new_values = array_ops.gather(grad.values, indices_to_select)
                out_grads.append(indexed_slices_lib.IndexedSlices(new_values, new_indices, size))
                start = end
    else:
        raise TypeError('Expected Tensor or IndexedSlices, got %s' % type(grad))
    return out_grads + [None] if end_value_index <= dim_index else [None] + out_grads

def check_all_args(a_nodes, b_nodes):
    for (arg_a, arg_b) in zip(a_nodes, b_nodes):
        if isinstance(arg_a, torch.fx.Node):
            if node_map[arg_a] != arg_b:
                return False
        elif isinstance(arg_a, slice):
            if not isinstance(arg_b, slice):
                return False
            if <MASK>:
                return False
        elif arg_a != arg_b:
            return False
    return True

def format(self, record):
    msg = record.msg
    status_code = getattr(record, 'status_code', None)
    if <MASK>:
        if 200 <= status_code < 300:
            msg = self.style.HTTP_SUCCESS(msg)
        elif 100 <= status_code < 200:
            msg = self.style.HTTP_INFO(msg)
        elif status_code == 304:
            msg = self.style.HTTP_NOT_MODIFIED(msg)
        elif 300 <= status_code < 400:
            msg = self.style.HTTP_REDIRECT(msg)
        elif status_code == 404:
            msg = self.style.HTTP_NOT_FOUND(msg)
        elif 400 <= status_code < 500:
            msg = self.style.HTTP_BAD_REQUEST(msg)
        else:
            msg = self.style.HTTP_SERVER_ERROR(msg)
    if self.uses_server_time() and (not hasattr(record, 'server_time')):
        record.server_time = self.formatTime(record, self.datefmt)
    record.msg = msg
    return super().format(record)

def merge_default_with_oplog(graph, op_log=None, run_meta=None, add_trace=True, add_trainable_var=True):
    """Merge the tfprof default extra info with caller's op_log.

  Args:
    graph: tf.Graph. If None and eager execution is not enabled, use
        default graph.
    op_log: OpLogProto proto.
    run_meta: RunMetadata proto used to complete shape information.
    add_trace: Whether to add op trace information.
    add_trainable_var: Whether to assign tf.compat.v1.trainable_variables() op
      type '_trainable_variables'.
  Returns:
    tmp_op_log: Merged OpLogProto proto.
  """
    if <MASK>:
        graph = ops.get_default_graph()
    tmp_op_log = tfprof_log_pb2.OpLogProto()
    if not graph:
        return tmp_op_log
    (logged_ops, string_to_id) = _get_logged_ops(graph, run_meta, add_trace=add_trace, add_trainable_var=add_trainable_var)
    if not op_log:
        tmp_op_log.log_entries.extend(logged_ops.values())
    else:
        all_ops = {}
        for entry in op_log.log_entries:
            all_ops[entry.name] = entry
        for (op_name, entry) in logged_ops.items():
            if op_name in all_ops:
                all_ops[op_name].types.extend(entry.types)
                if entry.float_ops > 0 and all_ops[op_name].float_ops == 0:
                    all_ops[op_name].float_ops = entry.float_ops
                if entry.code_def.traces and (not all_ops[op_name].code_def.traces):
                    all_ops[op_name].code_def.MergeFrom(entry.code_def)
            else:
                all_ops[op_name] = entry
        tmp_op_log.log_entries.extend(all_ops.values())
    for (s, i) in string_to_id.items():
        tmp_op_log.id_to_string[i] = s
    return tmp_op_log

def _get_results(self) -> None:
    command = ['strobeclient', 'getRunStatus', '--run-id', str(self.current_run_id)]
    logger.debug('running command: %s', _command_to_string(command))
    result = subprocess.run(command, capture_output=True)
    output = result.stderr.decode('utf-8')
    logger.debug('output:\n{%s}', output)
    if result.returncode != 0:
        raise StrobelightCLIProfilerError(f'failed to extract profiling results, return code is not 0 : {output}')
    if (match := re.search('INFO ::1:(.*)', output)):
        current_status = match.group(1)
        if current_status.__contains__('Profile run status: PROCESSING'):
            time.sleep(10)
            self._get_results()
            return
        elif <MASK>:
            raise StrobelightCLIProfilerError(f'failed to extract profiling results, unexpected response {output}')
    for item in re.findall('(Total samples(.*)|GraphProfiler(.*)|Icicle view \\(python stack\\)(.*))', output):
        logger.info(item[0])

@staticmethod
def _string_to_components(spec=None):
    """Stateless portion of device spec string parsing.

    Args:
      spec: An optional string specifying a device specification.

    Returns:
      The parsed components of `spec`. Note that the result of this function
      must go through attribute setters of DeviceSpec, and should therefore NOT
      be used directly.
    """
    cached_result = _STRING_TO_COMPONENTS_CACHE.get(spec)
    if cached_result is not None:
        return cached_result
    raw_spec = spec
    (job, replica, task, device_type, device_index) = (None, None, None, None, None)
    spec = spec or ''
    splits = [x.split(':') for x in spec.split('/')]
    valid_device_types = DeviceSpecV2._get_valid_device_types()
    for y in splits:
        ly = len(y)
        if y:
            if ly == 2 and y[0] == 'job':
                job = y[1]
            elif ly == 2 and y[0] == 'replica':
                replica = y[1]
            elif ly == 2 and y[0] == 'task':
                task = y[1]
            elif (ly == 1 or ly == 2) and y[0].upper() in valid_device_types:
                if device_type is not None:
                    raise ValueError(f'Multiple device types are not allowed while parsing the device spec: {spec}.')
                device_type = y[0].upper()
                if ly == 2 and y[1] != '*':
                    device_index = int(y[1])
            elif <MASK>:
                if device_type is not None:
                    raise ValueError(f'Multiple device types are not allowed while parsing the device spec: {spec}.')
                device_type = y[1]
                if y[2] != '*':
                    device_index = int(y[2])
            elif ly and y[0] != '':
                raise ValueError(f"Unknown attribute '{y[0]}' is encountered while parsing the device spec: '{spec}'.")
    output = (job, replica, task, device_type, device_index)
    _STRING_TO_COMPONENTS_CACHE[raw_spec] = output
    return output

def _make_window_size_func(self, window_size_func):
    """Make wrapping defun for window_size_func."""

    def window_size_func_wrapper(key):
        return ops.convert_to_tensor(window_size_func(key), dtype=dtypes.int64)
    self._window_size_func = structured_function.StructuredFunctionWrapper(window_size_func_wrapper, self._transformation_name(), input_structure=tensor_spec.TensorSpec([], dtypes.int64))
    if <MASK>:
        raise ValueError(f'Invalid `window_size_func`. `window_size_func` must return a single `tf.int64` scalar tensor but its return type is {self._window_size_func.output_structure}.')

def default(self, o):
    if isinstance(o, datetime.datetime):
        r = o.isoformat()
        if o.microsecond:
            r = r[:23] + r[26:]
        if r.endswith('+00:00'):
            r = r.removesuffix('+00:00') + 'Z'
        return r
    elif isinstance(o, datetime.date):
        return o.isoformat()
    elif isinstance(o, datetime.time):
        if is_aware(o):
            raise ValueError("JSON can't represent timezone-aware times.")
        r = o.isoformat()
        if o.microsecond:
            r = r[:12]
        return r
    elif isinstance(o, datetime.timedelta):
        return duration_iso_string(o)
    elif <MASK>:
        return str(o)
    else:
        return super().default(o)

@simple_wraps(fn)
def _functionalized_f_helper(*args: list[FxValue]) -> tuple[tuple[list[FxValue], list[Tensor]], list[Optional[AOTOutput]]]:
    with maybe_enable_thunkify():
        disable_above = torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize))
        with disable_above:
            f_args = pytree.tree_map(to_fun, args)
            if trace_joint and has_input_mutated_in_graph and joint_fn_handle:

                def _post_forward(primals):
                    nonlocal primals_after_forward
                    primals_after_forward = pytree.tree_map(from_fun, primals)
                    nonlocal f_args_after_forward
                    f_args_after_forward = f_args[0]
                    nonlocal f_args_mutation_counters_after_forward
                    f_args_mutation_counters_after_forward = [MutationCounters(-1, -1, -1) if not inputs_mutated_in_graph[i] else _get_mutation_counters(f_arg) for (i, f_arg) in enumerate(f_args_after_forward)]
                joint_fn_handle.post_forward = _post_forward
            (f_outs, f_outs_descs) = call_and_expect_output_descs(fn, f_args)
        if trace_joint:
            assert isinstance(args, tuple) and len(args) == 2 and isinstance(args[0], (list, tuple))
            primals_before = args[0]
            primals_after = pytree.tree_map(from_fun, f_args[0])
            for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args[0], primals_before, primals_after, meta.input_info)):
                joint_mutates_data = has_data_mutation(f_inpt)
                joint_mutates_metadata = has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False)
                if not inpt_info.mutates_metadata:
                    assert not joint_mutates_metadata, 'Found a graph input that had its metadata mutated in the backward. This is not supported'
                if not inpt_info.mutation_inductor_storage_resize:
                    assert not was_inductor_storage_resized(f_inpt), 'Found a graph input that had storage resizing in the backward. This is not supported'
                if joint_mutates_data and (not inpt_info.mutates_data) and (not inpt_info.mutates_storage_metadata):
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
                    meta.indices_of_inputs_that_requires_grad_with_mutations_in_bw.append(idx)
            tangents_before = args[1]
            tangents_after = pytree.tree_map(from_fun, f_args[1])
            for (f_inpt, before, after) in zip(f_args[1], tangents_before, tangents_after):
                assert not has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False), 'Found an input to the backward that had metadata mutated during the backward pass. This is not supported'
                if has_data_mutation(f_inpt):
                    can_be_in_graph = _check_if_mutation_can_be_in_graph(keep_input_mutations=True, mutates_data=True, mutates_metadata=False, mutations_hidden_from_autograd=are_all_mutations_hidden_from_autograd(f_inpt), mutations_under_no_grad_or_inference_mode=are_all_mutations_under_no_grad_or_inference_mode(f_inpt), mutates_storage_metadata=False, mutation_inductor_storage_resize=was_inductor_storage_resized(f_inpt), requires_grad=f_inpt.requires_grad)
                    assert can_be_in_graph, 'a backward input that had data mutated in an autograd-aware way. This is not supported'
                    with torch.fx.traceback.preserve_node_meta():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
        if aot_config.keep_inference_input_mutations:
            mcs_applied: list[MutationCounters] = [MutationCounters(0, 0, 0)] * len(meta.input_info)
            if <MASK>:
                primals_before = args[0]
                for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args_after_forward, primals_before, primals_after_forward, meta.input_info)):
                    if inpt_info.mutation_type != MutationType.MUTATED_IN_GRAPH:
                        continue
                    mcs_after_forward = f_args_mutation_counters_after_forward[idx]
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_forward(), _proxy_tensor_disable_update_tensor_tracker():
                        apply_in_graph_mutations(inpt_info, before, after, f_inpt, idx, mcs_after_forward, mcs_applied[idx])
                        mcs_applied[idx] = mcs_after_forward
            for (idx, (inpt_old, f_inpt)) in enumerate(zip(args, f_args) if not trace_joint else zip(args[0], f_args[0])):
                if not isinstance(f_inpt, torch.Tensor):
                    continue
                assert is_fun(f_inpt)
                inpt_new = from_fun(f_inpt)
                if meta.input_info[idx].mutation_type != MutationType.MUTATED_IN_GRAPH:
                    continue
                mcs: Optional[MutationCounters] = None
                if f_args_mutation_counters_after_forward is not None:
                    mcs = _get_mutation_counters(f_inpt)
                    if mcs == mcs_applied[idx]:
                        continue
                with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                    apply_in_graph_mutations(meta.input_info[idx], inpt_old, inpt_new, f_inpt, idx, mcs, mcs_applied[idx])
            (flat_outs, outs_spec) = pytree.tree_flatten(f_outs)
            flat_outs = [from_fun(o) for o in flat_outs]
            num_outs = len(meta.output_info)
            for i in range(num_outs):
                info = meta.output_info[i]
                if info.output_type != OutputType.is_input:
                    continue
                assert info.base_idx is not None
                if meta.input_info[info.base_idx].mutation_type == MutationType.MUTATED_IN_GRAPH:
                    fw_args = args[0] if trace_joint else args
                    flat_outs[i] = fw_args[info.base_idx]
            return (pytree.tree_unflatten(flat_outs, outs_spec), f_outs_descs)
        return (pytree.tree_map(from_fun, f_outs), f_outs_descs)

def _get_capturable_supported_devices(supports_xla: bool=True) -> list[str]:
    """Return the device type list that supports capturable optimizer."""
    capturable_supported_devices = ['cuda', 'xpu', 'hpu']
    if <MASK>:
        capturable_supported_devices.append(torch._C._get_privateuse1_backend_name())
    if supports_xla:
        capturable_supported_devices.append('xla')
    return capturable_supported_devices

def min_(x, y):
    if <MASK>:
        return math_ops.minimum(x, y)
    else:
        return min(x, y)

def create_joint(fn: Any, primals_descs: Optional[list[AOTInput]]=None, *, aot_config: AOTConfig) -> Any:
    joint_fn_handle = JointFnHandle()

    @simple_wraps(fn)
    def inner_fn(primals: list[FxValue], tangents: list[FxValue]) -> tuple[tuple[list[FxValue], list[Optional[Tensor]]], tuple[list[AOTOutput], list[Optional[AOTOutput]]]]:
        outs_descs = None
        if primals_descs is None:
            (outs, tangent_mask) = fn(*primals)
            assert not pytree.tree_any(lambda x: isinstance(x, AOTOutput), tangent_mask)
        else:
            ((outs, tangent_mask), (outs_descs, _)) = call_and_expect_output_descs(fn, primals)
        if joint_fn_handle and joint_fn_handle.post_forward:
            joint_fn_handle.post_forward(primals)
        assert len(tangent_mask) == len(outs)
        outs_to_grad = [o for (needs_tangent, o) in zip(tangent_mask, outs) if needs_tangent]
        assert len(outs_to_grad) == len(tangents)
        grad_primals: list[torch.Tensor] = []
        inputs_needs_grads = []
        for p in primals:
            if isinstance(p, Tensor) and p.requires_grad:
                inputs_needs_grads.append(True)
                assert isinstance(p, torch.Tensor)
                grad_primals.append(p)
            else:
                inputs_needs_grads.append(False)
        needed_outs = []
        needed_tangents = []
        for (out, tangent) in zip(outs_to_grad, tangents):
            if <MASK>:
                assert isinstance(tangent, torch.Tensor), f'Expected tensor tangent, got {type(tangent)}'
                needed_outs.append(out if guard_or_true(sym_eq(out.shape, tangent.shape)) else out.view(tangent.shape))
                needed_tangents.append(tangent)
        setup_stacktrace_preservation_hooks([out.grad_fn for out in needed_outs])
        if config.functionalize_rng_ops:
            PhiloxStateTracker.mark_beginning_of_backward()
        backward_out: tuple[Tensor, ...] = ()
        if grad_primals:
            functional_tensor_mode = torch.utils._python_dispatch._detect_infra_mode(torch._C._TorchDispatchModeKey.FUNCTIONAL)
            if functional_tensor_mode is not None:
                functional_tensor_mode._tokens_forward_output = functional_tensor_mode._tokens
                functional_tensor_mode._tokens = {}
            with set_partitioner_tag_is_backward(), fx_traceback.preserve_node_meta(), ExitStack() as stack:
                backward_pass_autocast = torch._functorch.config.backward_pass_autocast
                if backward_pass_autocast == 'same_as_forward':
                    pass
                elif backward_pass_autocast == 'off':
                    stack.enter_context(disable_autocast())
                else:
                    stack.enter_context(disable_autocast())
                    assert isinstance(backward_pass_autocast, list)
                    for kwargs in backward_pass_autocast:
                        assert isinstance(kwargs, dict)
                        stack.enter_context(torch.amp.autocast(**kwargs))
                if aot_config.no_tangents:
                    assert len(needed_tangents) == 1 and needed_tangents[0].numel() == 1
                    backward_out = torch.autograd.grad(needed_outs, grad_primals, allow_unused=True)
                else:
                    backward_out = torch.autograd.grad(needed_outs, grad_primals, grad_outputs=needed_tangents, allow_unused=True)
        backward_out_iter = iter(backward_out)
        final_outs = (outs, [next(backward_out_iter) if i else None for i in inputs_needs_grads])
        if primals_descs is None:
            return final_outs
        assert outs_descs is not None
        return (final_outs, (outs_descs, [GradAOTOutput(desc) if i else None for (i, desc) in zip(inputs_needs_grads, primals_descs)]))

    @simple_wraps(inner_fn)
    def inner_fn_with_anomaly(primals: list[FxValue], tangents: list[FxValue]) -> tuple[tuple[list[FxValue], list[Optional[Tensor]]], tuple[list[AOTOutput], list[Optional[AOTOutput]]]]:
        with fx_traceback.preserve_node_meta(), warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'Anomaly Detection has been enabled.')
            with torch.autograd.detect_anomaly(check_nan=False):
                return inner_fn(primals, tangents)

    def joint_helper(primals, tangents):
        return inner_fn_with_anomaly(primals, tangents)
    joint_helper.handle = joint_fn_handle
    return joint_helper

def _is_terminal(value: STATE_DICT_ITEM) -> bool:
    values: Collection[STATE_DICT_ITEM]
    if isinstance(value, Mapping):
        return False
    elif isinstance(value, list):
        values = value
    else:
        return True
    for entry in values:
        if <MASK>:
            return False
        if keep_traversing is not None and keep_traversing(entry):
            return False
    return True

def _wrap_result(self, result, name=None, expand: bool | None=None, fill_value=np.nan, returns_string: bool=True, dtype=None):
    from pandas import Index, MultiIndex
    if not hasattr(result, 'ndim') or not hasattr(result, 'dtype'):
        if isinstance(result, ABCDataFrame):
            result = result.__finalize__(self._orig, name='str')
        return result
    assert result.ndim < 3
    if expand is None:
        expand = result.ndim != 1
    elif expand is True and (not isinstance(self._orig, ABCIndex)):
        if isinstance(result.dtype, ArrowDtype):
            import pyarrow as pa
            from pandas.core.arrays.arrow.array import ArrowExtensionArray
            value_lengths = pa.compute.list_value_length(result._pa_array)
            max_len = pa.compute.max(value_lengths).as_py()
            min_len = pa.compute.min(value_lengths).as_py()
            if result._hasna:
                result = ArrowExtensionArray(result._pa_array.fill_null([None] * max_len))
            if min_len < max_len:
                result = ArrowExtensionArray(pa.compute.list_slice(result._pa_array, start=0, stop=max_len, return_fixed_size_list=True))
            if name is None:
                name = range(max_len)
            result = pa.compute.list_flatten(result._pa_array).to_numpy().reshape(len(result), max_len)
            result = {label: ArrowExtensionArray(pa.array(res)) for (label, res) in zip(name, result.T, strict=True)}
        elif is_object_dtype(result):

            def cons_row(x):
                if is_list_like(x):
                    return x
                else:
                    return [x]
            result = [cons_row(x) for x in result]
            if result and (not self._is_string):
                max_len = max((len(x) for x in result))
                result = [x * max_len if len(x) == 0 or x[0] is np.nan else x for x in result]
    if not isinstance(expand, bool):
        raise ValueError('expand must be True or False')
    if expand is False:
        if name is None:
            name = getattr(result, 'name', None)
        if name is None:
            name = self._orig.name
    if isinstance(self._orig, ABCIndex):
        if is_bool_dtype(result):
            return result
        if expand:
            result = list(result)
            out: Index = MultiIndex.from_tuples(result, names=name)
            if <MASK>:
                out = out.get_level_values(0)
            return out
        else:
            return Index(result, name=name, dtype=dtype)
    else:
        index = self._orig.index
        _dtype: DtypeObj | str | None = dtype
        vdtype = getattr(result, 'dtype', None)
        if _dtype is not None:
            pass
        elif self._is_string:
            if is_bool_dtype(vdtype):
                _dtype = result.dtype
            elif returns_string:
                _dtype = self._orig.dtype
            else:
                _dtype = vdtype
        elif vdtype is not None:
            _dtype = vdtype
        if expand:
            cons = self._orig._constructor_expanddim
            result = cons(result, columns=name, index=index, dtype=_dtype)
        else:
            cons = self._orig._constructor
            result = cons(result, name=name, index=index, dtype=_dtype)
        result = result.__finalize__(self._orig, method='str')
        if name is not None and result.ndim == 1:
            result.name = name
        return result

