def _parse_visible_devices() -> Union[list[int], list[str]]:
    """Parse CUDA_VISIBLE_DEVICES environment variable."""
    var = os.getenv('CUDA_VISIBLE_DEVICES')
    if torch.version.hip:
        hip_devices = os.getenv('HIP_VISIBLE_DEVICES')
        rocr_devices = os.getenv('ROCR_VISIBLE_DEVICES')
        if rocr_devices is not None:
            rocr_count = len(rocr_devices.split(','))
            if hip_devices is not None:
                if len(hip_devices.split(',')) > rocr_count:
                    raise RuntimeError('HIP_VISIBLE_DEVICES contains more devices than ROCR_VISIBLE_DEVICES')
                var = hip_devices
            else:
                return list(range(rocr_count))
        elif hip_devices is not None:
            var = hip_devices
    if var is None:
        return list(range(64))

    def _strtoul(s: str) -> int:
        """Return -1 or positive integer sequence string starts with."""
        if not s:
            return -1
        for (idx, c) in enumerate(s):
            if not (c.isdigit() or (idx == 0 and c in '+-')):
                break
            if idx + 1 == len(s):
                idx += 1
        return int(s[:idx]) if idx > 0 else -1

    def parse_list_with_prefix(lst: str, prefix: str) -> list[str]:
        rcs: list[str] = []
        for elem in lst.split(','):
            if elem in rcs:
                return cast(list[str], [])
            if not elem.startswith(prefix):
                break
            rcs.append(elem)
        return rcs
    if var.startswith('GPU-'):
        return parse_list_with_prefix(var, 'GPU-')
    if <MASK>:
        return parse_list_with_prefix(var, 'MIG-')
    rc: list[int] = []
    for elem in var.split(','):
        x = _strtoul(elem.strip())
        if x in rc:
            return cast(list[int], [])
        if x < 0:
            break
        rc.append(x)
    return rc

def remap_func(x):
    if x.op == 'get_attr':
        if x not in comp.getattr_maps:
            comp.getattr_maps[x] = comp.graph.get_attr(x.target, type_expr=x.type)
            comp.getattr_maps[x].meta = copy.copy(x.meta)
        return comp.getattr_maps[x]
    if <MASK>:
        return node_remapping[x]
    if x not in comp.orig_inputs:
        comp.orig_inputs.append(x)
        placeholder = comp.graph.placeholder(x.name, type_expr=x.type)
        placeholder.meta = copy.copy(x.meta)
        comp.input_placeholders.append(placeholder)
        used_in_main[x] = None
    return comp.input_placeholders[comp.orig_inputs.index(x)]

def _test_DDP_niter(self, model_base, model_DDP, input, target, loss, local_bs, rank, batch_size, test_save, offset=None, world_size=0, zero_grad=False, memory_format=None, n_iter=5):
    for idx in range(n_iter):
        self._test_DDP_helper(model_base, input, target, loss, memory_format=memory_format)
        if offset is None:
            offset = rank * local_bs
        self._test_DDP_helper(model_DDP, input[offset:offset + local_bs], target[offset:offset + local_bs], loss, world_size * local_bs / batch_size if world_size != 0 else 1, memory_format=memory_format)
        if <MASK>:
            self._model_step_with_zero_grad(model_base)
            self._model_step_with_zero_grad(model_DDP)
        else:
            self._model_step(model_base)
            self._model_step(model_DDP)
        self._assert_equal_param(list(model_base.parameters()), list(model_DDP.module.parameters()))
        input = input[torch.randperm(batch_size)]
        if test_save and idx == 2 and INIT_METHOD.startswith('file://'):
            with tempfile.NamedTemporaryFile() as tmp:
                if sys.platform == 'win32':
                    torch.save(model_DDP, tmp)
                    tmp.seek(0)
                    model_DDP = torch.load(tmp, weights_only=False)
                else:
                    torch.save(model_DDP, tmp.name)
                    model_DDP = torch.load(tmp.name, weights_only=False)
    with tempfile.TemporaryFile() as tmp_file:
        torch.save(model_DDP, tmp_file)
        tmp_file.seek(0)
        saved_model = torch.load(tmp_file, weights_only=False)
    for k in model_DDP.state_dict():
        self.assertEqual(model_DDP.state_dict()[k], saved_model.state_dict()[k])

@classmethod
def _from_sequence_of_strings(cls, strings: list[str], *, dtype: ExtensionDtype, copy: bool=False, true_values: list[str] | None=None, false_values: list[str] | None=None, none_values: list[str] | None=None) -> BooleanArray:
    true_values_union = cls._TRUE_VALUES.union(true_values or [])
    false_values_union = cls._FALSE_VALUES.union(false_values or [])
    if none_values is None:
        none_values = []

    def map_string(s) -> bool | None:
        if s in true_values_union:
            return True
        elif s in false_values_union:
            return False
        elif <MASK>:
            return None
        else:
            raise ValueError(f'{s} cannot be cast to bool')
    scalars = np.array(strings, dtype=object)
    mask = isna(scalars)
    scalars[~mask] = list(map(map_string, scalars[~mask]))
    return cls._from_sequence(scalars, dtype=dtype, copy=copy)

@_onnx_symbolic('aten::_convolution_mode')
@symbolic_helper.parse_args('v', 'v', 'v', 'is', 's', 'is', 'i')
def _convolution_mode(g: jit_utils.GraphContext, input, weight, bias, stride, padding, dilation, groups):
    weight_size = symbolic_helper._get_tensor_sizes(weight)
    try:
        kernel_shape = weight_size[2:]
    except Exception:
        kernel_shape = None
    if <MASK>:
        raise errors.SymbolicValueError('Unsupported: ONNX export of convolution for kernel of unknown shape.', input)
    args = [input, weight]
    if not symbolic_helper._is_none(bias) and symbolic_helper._get_tensor_rank(bias) == 1:
        args.append(bias)
    if padding == 'valid':
        padding = 'VALID'
    elif padding == 'same':
        padding = 'SAME_UPPER'
    kwargs = {'kernel_shape_i': weight_size[2:], 'strides_i': stride, 'auto_pad_s': padding, 'dilations_i': dilation, 'group_i': groups}
    n = g.op('Conv', *args, **kwargs)
    if not symbolic_helper._is_none(bias) and symbolic_helper._get_tensor_rank(bias) != 1:
        return g.op('Add', n, bias)
    else:
        return n

def run_node(self, node: torch.fx.Node) -> Any:
    if node.op in ('placeholder', 'output'):
        return super().run_node(node)
    target = node.target
    (args, kwargs) = self.fetch_args_kwargs_from_env(node)
    if node.op == 'call_function':
        assert callable(target)
        result = graph.call_function(target, args, kwargs)
        added_replacement_nodes.append(result)
        _transfer_meta(new_meta=result.meta, old_node=node, pass_name='Interpreter_Replacer')
        if 'eager_input_vals' in node.meta:
            result.meta['eager_input_vals'] = node.meta['eager_input_vals']
        if 'val' in node.meta and 'val' not in result.meta:
            result.meta['val'] = node.meta['val']
            if isinstance(node.meta['val'], torch.Tensor):
                assert 'tensor_meta' in node.meta
                result.meta['tensor_meta'] = node.meta['tensor_meta']
        return result
    if <MASK>:
        from torch._higher_order_ops.utils import unique_graph_name_with_root
        sub_gm = super().get_attr(target, args, kwargs)
        if not isinstance(sub_gm, torch.fx.GraphModule):
            raise NotImplementedError(f'NYI: replacement_graph.{target} is not a graph module. Got {sub_gm}.')
        assert graph.owning_module is not None
        graph_name = None
        for (n, mod) in graph.owning_module.named_modules():
            if sub_gm is mod:
                graph_name = n
                break
        if graph_name is None:
            assert isinstance(target, str)
            (_, graph_name) = unique_graph_name_with_root(graph.owning_module, target)
            graph.owning_module.register_module(graph_name, sub_gm)
        getattr_node = graph.get_attr(graph_name)
        added_replacement_nodes.append(getattr_node)
        return getattr_node
    raise NotImplementedError(f'unhandled {node}')

def get_search_results(self, request, queryset, search_term):
    """
        Return a tuple containing a queryset to implement the search
        and a boolean indicating if the results may contain duplicates.
        """

    def construct_search(field_name):
        if field_name.startswith('^'):
            return ('%s__istartswith' % field_name.removeprefix('^'), None)
        elif field_name.startswith('='):
            return ('%s__iexact' % field_name.removeprefix('='), None)
        elif field_name.startswith('@'):
            return ('%s__search' % field_name.removeprefix('@'), None)
        opts = queryset.model._meta
        lookup_fields = field_name.split(LOOKUP_SEP)
        prev_field = None
        for (i, path_part) in enumerate(lookup_fields):
            if <MASK>:
                path_part = opts.pk.name
            try:
                field = opts.get_field(path_part)
            except FieldDoesNotExist:
                if prev_field and prev_field.get_lookup(path_part):
                    if path_part == 'exact' and (not isinstance(prev_field, (models.CharField, models.TextField))):
                        field_name_without_exact = '__'.join(lookup_fields[:i])
                        alias = Cast(field_name_without_exact, output_field=models.CharField())
                        alias_name = '_'.join(lookup_fields[:i])
                        return (f'{alias_name}_str', alias)
                    else:
                        return (field_name, None)
            else:
                prev_field = field
                if hasattr(field, 'path_infos'):
                    opts = field.path_infos[-1].to_opts
        return ('%s__icontains' % field_name, None)
    may_have_duplicates = False
    search_fields = self.get_search_fields(request)
    if search_fields and search_term:
        str_aliases = {}
        orm_lookups = []
        for field in search_fields:
            (lookup, str_alias) = construct_search(str(field))
            orm_lookups.append(lookup)
            if str_alias:
                str_aliases[lookup] = str_alias
        if str_aliases:
            queryset = queryset.alias(**str_aliases)
        term_queries = []
        for bit in smart_split(search_term):
            if bit.startswith(('"', "'")) and bit[0] == bit[-1]:
                bit = unescape_string_literal(bit)
            or_queries = models.Q.create([(orm_lookup, bit) for orm_lookup in orm_lookups], connector=models.Q.OR)
            term_queries.append(or_queries)
        queryset = queryset.filter(models.Q.create(term_queries))
        may_have_duplicates |= any((lookup_spawns_duplicates(self.opts, search_spec) for search_spec in orm_lookups))
    return (queryset, may_have_duplicates)

def build_err_msg(arrays, err_msg, header='Items are not equal:', verbose=True, names=('ACTUAL', 'DESIRED'), precision=8):
    msg = ['\n' + header]
    err_msg = str(err_msg)
    if err_msg:
        if err_msg.find('\n') == -1 and len(err_msg) < 79 - len(header):
            msg = [msg[0] + ' ' + err_msg]
        else:
            msg.append(err_msg)
    if verbose:
        for (i, a) in enumerate(arrays):
            if isinstance(a, ndarray):
                r_func = partial(array_repr, precision=precision)
            else:
                r_func = repr
            try:
                r = r_func(a)
            except Exception as exc:
                r = f'[repr failed for <{type(a).__name__}>: {exc}]'
            if <MASK>:
                r = '\n'.join(r.splitlines()[:3])
                r += '...'
            msg.append(f' {names[i]}: {r}')
    return '\n'.join(msg)

def isGeneratorType(typ: Type) -> bool:
    if <MASK>:
        return typ.name == BaseTy.Generator
    elif isinstance(typ, OptionalType):
        return isGeneratorType(typ.elem)
    return False

def _changed_params(estimator):
    """Return dict (param_name: value) of parameters that were given to
    estimator with non-default values."""
    params = estimator.get_params(deep=False)
    init_func = getattr(estimator.__init__, 'deprecated_original', estimator.__init__)
    init_params = inspect.signature(init_func).parameters
    init_params = {name: param.default for (name, param) in init_params.items()}

    def has_changed(k, v):
        if k not in init_params:
            return True
        if <MASK>:
            return True
        if isinstance(v, BaseEstimator) and v.__class__ != init_params[k].__class__:
            return True
        if repr(v) != repr(init_params[k]) and (not (is_scalar_nan(init_params[k]) and is_scalar_nan(v))):
            return True
        return False
    return {k: v for (k, v) in params.items() if has_changed(k, v)}

def set_requires_all_reduce(self, requires_all_reduce: bool, *, recurse: bool=True) -> None:
    """
        Sets if the module should all-reduce gradients. This can be used to
        implement gradient accumulation with only reduce-scatter but not
        all-reduce for HSDP.
        """
    self_module = cast(nn.Module, self)
    modules = list(self_module.modules()) if recurse else [self_module]
    for module in modules:
        if isinstance(module, FSDPModule):
            state = module._get_fsdp_state()
            if <MASK>:
                fsdp_param_group.all_reduce_grads = requires_all_reduce

def _maybe_convert_for_string_atom(name: str, bvalues: ArrayLike, existing_col, min_itemsize, nan_rep, encoding, errors, columns: list[str]):
    if isinstance(bvalues.dtype, StringDtype):
        bvalues = bvalues.to_numpy()
    if bvalues.dtype != object:
        return bvalues
    bvalues = cast(np.ndarray, bvalues)
    dtype_name = bvalues.dtype.name
    inferred_type = lib.infer_dtype(bvalues, skipna=False)
    if inferred_type == 'date':
        raise TypeError('[date] is not implemented as a table column')
    if inferred_type == 'datetime':
        raise TypeError('too many timezones in this block, create separate data columns')
    if not (inferred_type == 'string' or dtype_name == 'object'):
        return bvalues
    mask = isna(bvalues)
    data = bvalues.copy()
    data[mask] = nan_rep
    if existing_col and mask.any() and (len(nan_rep) > existing_col.itemsize):
        raise ValueError('NaN representation is too large for existing column size')
    inferred_type = lib.infer_dtype(data, skipna=False)
    if inferred_type != 'string':
        for i in range(data.shape[0]):
            col = data[i]
            inferred_type = lib.infer_dtype(col, skipna=False)
            if inferred_type != 'string':
                error_column_label = columns[i] if len(columns) > i else f'No.{i}'
                raise TypeError(f'Cannot serialize the column [{error_column_label}]\nbecause its data contents are not [string] but [{inferred_type}] object dtype')
    data_converted = _convert_string_array(data, encoding, errors).reshape(data.shape)
    itemsize = data_converted.itemsize
    if isinstance(min_itemsize, dict):
        min_itemsize = int(min_itemsize.get(name) or min_itemsize.get('values') or 0)
    itemsize = max(min_itemsize or 0, itemsize)
    if existing_col is not None:
        eci = existing_col.validate_col(itemsize)
        if <MASK>:
            itemsize = eci
    data_converted = data_converted.astype(f'|S{itemsize}', copy=False)
    return data_converted

def _to_graph(n_x, n_y, n_z, mask=None, img=None, return_as=sparse.coo_matrix, dtype=None):
    """Auxiliary function for img_to_graph and grid_to_graph"""
    edges = _make_edges_3d(n_x, n_y, n_z)
    if dtype is None:
        if img is None:
            dtype = int
        else:
            dtype = img.dtype
    if <MASK>:
        img = np.atleast_3d(img)
        weights = _compute_gradient_3d(edges, img)
        if mask is not None:
            (edges, weights) = _mask_edges_weights(mask, edges, weights)
            diag = img.squeeze()[mask]
        else:
            diag = img.ravel()
        n_voxels = diag.size
    else:
        if mask is not None:
            mask = mask.astype(dtype=bool, copy=False)
            edges = _mask_edges_weights(mask, edges)
            n_voxels = np.sum(mask)
        else:
            n_voxels = n_x * n_y * n_z
        weights = np.ones(edges.shape[1], dtype=dtype)
        diag = np.ones(n_voxels, dtype=dtype)
    diag_idx = np.arange(n_voxels)
    i_idx = np.hstack((edges[0], edges[1]))
    j_idx = np.hstack((edges[1], edges[0]))
    graph = sparse.coo_matrix((np.hstack((weights, weights, diag)), (np.hstack((i_idx, diag_idx)), np.hstack((j_idx, diag_idx)))), (n_voxels, n_voxels), dtype=dtype)
    if return_as is np.ndarray:
        return graph.toarray()
    return return_as(graph)

