def parse_signature(sig_text, name, pos):
    tokens = tokenize.generate_tokens(StringIO(sig_text).readline)
    sig_args = []
    var_arg = None
    var_kw = None
    defaults = {}

    def get_token(pos=False):
        try:
            (tok_type, tok_string, (srow, scol), (erow, ecol), line) = next(tokens)
        except StopIteration:
            return (tokenize.ENDMARKER, '')
        if pos:
            return (tok_type, tok_string, (srow, scol), (erow, ecol))
        else:
            return (tok_type, tok_string)
    while 1:
        var_arg_type = None
        (tok_type, tok_string) = get_token()
        if tok_type == tokenize.ENDMARKER:
            break
        if <MASK>:
            var_arg_type = tok_string
            (tok_type, tok_string) = get_token()
        if tok_type != tokenize.NAME:
            raise TemplateError('Invalid signature: (%s)' % sig_text, position=pos, name=name)
        var_name = tok_string
        (tok_type, tok_string) = get_token()
        if tok_type == tokenize.ENDMARKER or (tok_type == tokenize.OP and tok_string == ','):
            if var_arg_type == '*':
                var_arg = var_name
            elif var_arg_type == '**':
                var_kw = var_name
            else:
                sig_args.append(var_name)
            if tok_type == tokenize.ENDMARKER:
                break
            continue
        if var_arg_type is not None:
            raise TemplateError('Invalid signature: (%s)' % sig_text, position=pos, name=name)
        if tok_type == tokenize.OP and tok_string == '=':
            nest_type = None
            unnest_type = None
            nest_count = 0
            start_pos = end_pos = None
            parts = []
            while 1:
                (tok_type, tok_string, s, e) = get_token(True)
                if start_pos is None:
                    start_pos = s
                end_pos = e
                if tok_type == tokenize.ENDMARKER and nest_count:
                    raise TemplateError('Invalid signature: (%s)' % sig_text, position=pos, name=name)
                if not nest_count and (tok_type == tokenize.ENDMARKER or (tok_type == tokenize.OP and tok_string == ',')):
                    default_expr = isolate_expression(sig_text, start_pos, end_pos)
                    defaults[var_name] = default_expr
                    sig_args.append(var_name)
                    break
                parts.append((tok_type, tok_string))
                if nest_count and tok_type == tokenize.OP and (tok_string == nest_type):
                    nest_count += 1
                elif nest_count and tok_type == tokenize.OP and (tok_string == unnest_type):
                    nest_count -= 1
                    if not nest_count:
                        nest_type = unnest_type = None
                elif not nest_count and tok_type == tokenize.OP and (tok_string in ('(', '[', '{')):
                    nest_type = tok_string
                    nest_count = 1
                    unnest_type = {'(': ')', '[': ']', '{': '}'}[nest_type]
    return (sig_args, var_arg, var_kw, defaults)

def _maybe_wrap_custom_getter(custom_getter, old_getter):
    """Wrap a call to a custom_getter to use the old_getter internally."""
    if <MASK>:
        return custom_getter

    def wrapped_custom_getter(getter, *args, **kwargs):
        return custom_getter(functools.partial(old_getter, getter), *args, **kwargs)
    return wrapped_custom_getter

def _testPad(self, np_inputs, paddings, mode, constant_values):
    np_val = self._npPad(np_inputs, paddings, mode=mode, constant_values=constant_values)
    for use_gpu in [True, False]:
        with test_util.device(use_gpu=use_gpu):
            tf_val = array_ops.pad(np_inputs, paddings, mode=mode, constant_values=constant_values)
            out = self.evaluate(tf_val)
            if <MASK>:
                np_val = np_val.astype(np_inputs.dtype[0])
        self.assertAllEqual(np_val, out)
        self.assertShapeEqual(np_val, tf_val)

def extend(self, other: Match) -> None:
    if <MASK>:
        for key in OrderedSet(self.kwargs.keys()) & OrderedSet(other.kwargs.keys()):
            if self.kwargs[key] != other.kwargs[key]:
                raise FailedMatch('kwarg mismatch: {}', key)
    self.args.extend(other.args)
    self.nodes.extend(other.nodes)
    self.kwargs.update(other.kwargs)
    self.targets.update(other.targets)

def _print_args(arguments, argument_type='Argument', indent=0):
    """Formats and prints the argument of the concrete functions defined in the model.

  Args:
    arguments: Arguments to format print.
    argument_type: Type of arguments.
    indent: How far (in increments of 2 spaces) to indent each line of
     output.
  """
    indent_str = '  ' * indent

    def _maybe_add_quotes(value):
        is_quotes = "'" * isinstance(value, str)
        return is_quotes + str(value) + is_quotes

    def in_print(s, end='\n'):
        print(indent_str + s, end=end)
    for (index, element) in enumerate(arguments, 1):
        if indent == 4:
            in_print('%s #%d' % (argument_type, index))
        if isinstance(element, str):
            in_print('  %s' % element)
        elif isinstance(element, tensor_spec.TensorSpec):
            print((indent + 1) * '  ' + '%s: %s' % (element.name, repr(element)))
        elif isinstance(element, collections_abc.Iterable) and (not isinstance(element, dict)):
            in_print('  DType: %s' % type(element).__name__)
            in_print('  Value: [', end='')
            for value in element:
                print('%s' % _maybe_add_quotes(value), end=', ')
            print('\x08\x08]')
        elif <MASK>:
            in_print('  DType: %s' % type(element).__name__)
            in_print('  Value: {', end='')
            for (key, value) in element.items():
                print("'%s': %s" % (str(key), _maybe_add_quotes(value)), end=', ')
            print('\x08\x08}')
        else:
            in_print('  DType: %s' % type(element).__name__)
            in_print('  Value: %s' % str(element))

@staticmethod
def __nested_list_to_tuple(value):
    """Converts a nested list to a corresponding nested tuple."""
    if <MASK>:
        return tuple((TypeSpec.__nested_list_to_tuple(v) for v in value))
    return value

def _decorator(view_func):
    middleware = middleware_class(view_func, *m_args, **m_kwargs)

    def _pre_process_request(request, *args, **kwargs):
        if hasattr(middleware, 'process_request'):
            result = middleware.process_request(request)
            if result is not None:
                return result
        if hasattr(middleware, 'process_view'):
            result = middleware.process_view(request, view_func, args, kwargs)
            if result is not None:
                return result
        return None

    def _process_exception(request, exception):
        if hasattr(middleware, 'process_exception'):
            result = middleware.process_exception(request, exception)
            if result is not None:
                return result
        raise

    def _post_process_request(request, response):
        if hasattr(response, 'render') and callable(response.render):
            if <MASK>:
                response = middleware.process_template_response(request, response)
            if hasattr(middleware, 'process_response'):

                def callback(response):
                    return middleware.process_response(request, response)
                response.add_post_render_callback(callback)
        elif hasattr(middleware, 'process_response'):
            return middleware.process_response(request, response)
        return response
    if iscoroutinefunction(view_func):

        async def _view_wrapper(request, *args, **kwargs):
            result = _pre_process_request(request, *args, **kwargs)
            if result is not None:
                return result
            try:
                response = await view_func(request, *args, **kwargs)
            except Exception as e:
                result = _process_exception(request, e)
                if result is not None:
                    return result
            return _post_process_request(request, response)
    else:

        def _view_wrapper(request, *args, **kwargs):
            result = _pre_process_request(request, *args, **kwargs)
            if result is not None:
                return result
            try:
                response = view_func(request, *args, **kwargs)
            except Exception as e:
                result = _process_exception(request, e)
                if result is not None:
                    return result
            return _post_process_request(request, response)
    return wraps(view_func)(_view_wrapper)

def test_cond_prune(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')
    x_in = []
    x_out = []

    def f(x, y):
        x_in.append(x)
        xx = cond_v2.cond_v2(math_ops.less(1, 2), lambda : x + 1, lambda : x + 2)
        x_out.append(xx)
        return (xx, 2 * y)
    f_wrapped = wrap_function.wrap_function(f, [tensor_spec.TensorSpec((), dtypes.float32)] * 2)
    f_pruned = f_wrapped.prune(x_in[0], [x_out[0]])

    class Adder(module.Module):

        @def_function.function(input_signature=[tensor_spec.TensorSpec(shape=None, dtype=dtypes.float32)])
        def add(self, x):
            return f_pruned(x)
    root = Adder()
    root.add(constant_op.constant(1.0))
    root = cycle(root, cycles, use_cpp_bindings=use_cpp_bindings)
    root.add(constant_op.constant(1.0))

def convert_to_generator_like(data, batch_size=None, steps_per_epoch=None, epochs=1, shuffle=False):
    """Make a generator out of NumPy or EagerTensor inputs.

  Args:
    data: Either a generator or `keras.utils.data_utils.Sequence` object or
      `Dataset`, `Iterator`, or a {1,2,3}-tuple of NumPy arrays or EagerTensors.
      If a tuple, the elements represent `(x, y, sample_weights)` and may be
      `None` or `[None]`.
    batch_size: Used when creating a generator out of tuples of NumPy arrays or
      EagerTensors.
    steps_per_epoch: Steps of the generator to run each epoch. If `None` the
      number of steps will be read from the data (for
      `keras.utils.data_utils.Sequence` types).
    epochs: Total number of epochs to run.
    shuffle: Whether the data should be shuffled.

  Returns:
    - Generator, `keras.utils.data_utils.Sequence`, or `Iterator`.

  Raises:
    - ValueError: If `batch_size` is not provided for NumPy or EagerTensor
      inputs.
  """
    if <MASK>:
        data = tuple((ele for ele in data if not all((e is None for e in nest.flatten(ele)))))
    if data_utils.is_generator_or_sequence(data) or isinstance(data, iterator_ops.IteratorBase):
        if isinstance(data, data_utils.Sequence):
            if steps_per_epoch is None:
                steps_per_epoch = len(data)
        return (data, steps_per_epoch)
    if isinstance(data, data_types.DatasetV2):
        return (dataset_ops.make_one_shot_iterator(data), steps_per_epoch)
    num_samples = int(nest.flatten(data)[0].shape[0])
    if batch_size is None:
        raise ValueError('When passing input data as arrays, do not specify `steps_per_epoch`/`steps` argument. Please use `batch_size` instead.')
    steps_per_epoch = int(math.ceil(num_samples / batch_size))

    def _gen(data):
        """Makes a generator out of a structure of NumPy/EagerTensors."""
        index_array = np.arange(num_samples)
        for _ in range(epochs):
            if shuffle:
                np.random.shuffle(index_array)
            batches = generic_utils.make_batches(num_samples, batch_size)
            for (batch_start, batch_end) in batches:
                batch_ids = index_array[batch_start:batch_end]
                flat_batch_data = training_utils.slice_arrays(nest.flatten(data), batch_ids, contiguous=not shuffle)
                yield nest.pack_sequence_as(data, flat_batch_data)
    return (_gen(data), steps_per_epoch)

def _call_impl(self, args, kwargs):
    if <MASK>:
        if kwargs:
            raise NotImplementedError(f'Keyword arguments are not supported when calling a wrap_function-decorated function. Got {kwargs}.')
        if self._signature is not None:
            args = list(args)
            for (i, arg) in enumerate(args):
                if isinstance(self._signature[i], tensor_lib.DenseSpec):
                    args[i] = ops.convert_to_tensor(arg, self._signature[i].dtype)
        return self._call_flat(args, self.captured_inputs)
    else:
        return super()._call_impl(args, kwargs)

def reduce(self, operation, app_label):
    if isinstance(operation, DeleteModel) and self.name_lower == operation.name_lower and (not self.options.get('proxy', False)):
        return []
    elif isinstance(operation, RenameModel) and self.name_lower == operation.old_name_lower:
        return [replace(self, name=operation.new_name)]
    elif <MASK>:
        options = {**self.options, **operation.options}
        for key in operation.ALTER_OPTION_KEYS:
            if key not in operation.options:
                options.pop(key, None)
        return [replace(self, options=options)]
    elif isinstance(operation, AlterModelManagers) and self.name_lower == operation.name_lower:
        return [replace(self, managers=operation.managers)]
    elif isinstance(operation, AlterModelTable) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, 'db_table': operation.table})]
    elif isinstance(operation, AlterModelTableComment) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, 'db_table_comment': operation.table_comment})]
    elif isinstance(operation, AlterTogetherOptionOperation) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, **{operation.option_name: operation.option_value}})]
    elif isinstance(operation, AlterOrderWithRespectTo) and self.name_lower == operation.name_lower:
        return [replace(self, options={**self.options, 'order_with_respect_to': operation.order_with_respect_to})]
    elif isinstance(operation, FieldOperation) and self.name_lower == operation.model_name_lower:
        if isinstance(operation, AddField):
            return [replace(self, fields=[*self.fields, (operation.name, operation.field)])]
        elif isinstance(operation, AlterField):
            return [replace(self, fields=[(n, operation.field if n == operation.name else v) for (n, v) in self.fields])]
        elif isinstance(operation, RemoveField):
            options = self.options.copy()
            for option_name in ('unique_together', 'index_together'):
                option = options.pop(option_name, None)
                if option:
                    option = set(filter(bool, (tuple((f for f in fields if f != operation.name_lower)) for fields in option)))
                    if option:
                        options[option_name] = option
            order_with_respect_to = options.get('order_with_respect_to')
            if order_with_respect_to == operation.name_lower:
                del options['order_with_respect_to']
            return [replace(self, fields=[(n, v) for (n, v) in self.fields if n.lower() != operation.name_lower], options=options)]
        elif isinstance(operation, RenameField):
            options = self.options.copy()
            for option_name in ('unique_together', 'index_together'):
                option = options.get(option_name)
                if option:
                    options[option_name] = {tuple((operation.new_name if f == operation.old_name else f for f in fields)) for fields in option}
            order_with_respect_to = options.get('order_with_respect_to')
            if order_with_respect_to == operation.old_name:
                options['order_with_respect_to'] = operation.new_name
            return [replace(self, fields=[(operation.new_name if n == operation.old_name else n, v) for (n, v) in self.fields], options=options)]
    elif isinstance(operation, IndexOperation) and self.name_lower == operation.model_name_lower:
        if isinstance(operation, AddIndex):
            return [replace(self, options={**self.options, 'indexes': [*self.options.get('indexes', []), operation.index]})]
        elif isinstance(operation, RemoveIndex):
            options_indexes = [index for index in self.options.get('indexes', []) if index.name != operation.name]
            return [replace(self, options={**self.options, 'indexes': options_indexes})]
        elif isinstance(operation, AddConstraint):
            return [replace(self, options={**self.options, 'constraints': [*self.options.get('constraints', []), operation.constraint]})]
        elif isinstance(operation, AlterConstraint):
            options_constraints = [constraint for constraint in self.options.get('constraints', []) if constraint.name != operation.name] + [operation.constraint]
            return [replace(self, options={**self.options, 'constraints': options_constraints})]
        elif isinstance(operation, RemoveConstraint):
            options_constraints = [constraint for constraint in self.options.get('constraints', []) if constraint.name != operation.name]
            return [replace(self, options={**self.options, 'constraints': options_constraints})]
    return super().reduce(operation, app_label)

def year_lookup_bounds(self, connection, year):
    from django.db.models.functions import ExtractIsoYear
    iso_year = isinstance(self.lhs, ExtractIsoYear)
    output_field = self.lhs.lhs.output_field
    if <MASK>:
        bounds = connection.ops.year_lookup_bounds_for_datetime_field(year, iso_year=iso_year)
    else:
        bounds = connection.ops.year_lookup_bounds_for_date_field(year, iso_year=iso_year)
