def resolve_input(self, input_name):
    """Resolves an input into its _EndPoint.

    A NodeDef's input name can refer to either global NodeDefs (in the
    GraphDef's node list), a NodeDef in a function's node list, or a Function
    (in the GraphDef's function library). The name can also carry semantic
    information, depending on whether it starts with "^". This method handles
    all that logic in order to find the object to which the input name refers
    to.

    Args:
      input_name: The input name to resolve.

    Returns:
      The object referred to by 'input_name'.
    """
    name_elts = input_name.split(':')
    source_name = name_elts[0]
    if <MASK>:
        source_name = source_name[1:]
    source_index = 0
    if len(name_elts) > 1 and name_elts[-1].isnumeric():
        source_index = int(name_elts[-1])
    if self._function is None:
        return _EndPoint(self._enclosing_graph.nodes[source_name], source_index)
    if source_index != 0 or source_name in self._function.nodes:
        return _EndPoint(self._function.nodes[source_name], source_index)
    inputs = [i.name for i in self._function.function.signature.input_arg]
    return _EndPoint(self._function, inputs.index(source_name))

def _validate_v(v, other, is_other_tuple):
    if len(other) != len(v):
        if is_other_tuple:
            raise RuntimeError(f'v is a tuple of invalid length: should be {len(other)} but got {len(v)}.')
        else:
            raise RuntimeError('The given v should contain a single Tensor.')
    for (idx, (el_v, el_other)) in enumerate(zip(v, other)):
        if <MASK>:
            prepend = ''
            if is_other_tuple:
                prepend = f'Entry {idx} in '
            raise RuntimeError(f'{prepend}v has invalid size: should be {el_other.size()} but got {el_v.size()}.')

def _validate_output_for_cache_entry(self, state: _CacheKeyState, key: _DispatchCacheKey, func: OpOverload, args: Sequence[object], kwargs: Mapping[str, object], output: Optional[FakeTensor]) -> None:
    if isinstance(output, (int, type(None))):
        return
    _validate_symbolic_output_for_caching(state, output)
    if <MASK>:
        raise _BypassDispatchCache('non-FakeTensor output')
    if output.constant is not None:
        raise _BypassDispatchCache('constant attribute')
    if output.is_sparse:
        raise _BypassDispatchCache('sparse output')
    if is_sparse_compressed(output):
        raise _BypassDispatchCache('sparse compressed output')
    for kval in kwargs.values():
        if id(kval) == id(output):
            raise _BypassDispatchCache('kwarg aliases output')

def _atol_for_type(dtype_or_dtype_name):
    """Return the absolute tolerance for a given numpy dtype."""
    if <MASK>:
        dtype_or_dtype_name = numpy.float64
    return numpy.finfo(dtype_or_dtype_name).eps * 1000

def _backward_function_wrapper(*args):
    """Process output gradients and call the backward function."""
    if <MASK>:
        return backward.structured_outputs
    processed_args = []
    input_index = 0
    for (output_index, arg) in enumerate(args):
        if isinstance(arg, indexed_slices.IndexedSlices):
            arg = ops.convert_to_tensor(arg)
        if output_index in skip_positions:
            continue
        if arg is None:
            input_placeholder = backward.inputs[input_index]
            if input_placeholder.dtype == dtypes.variant:
                arg = variant_zeros_like[output_index]
            else:
                arg = array_ops.zeros(*default_gradient.shape_and_dtype(input_placeholder))
        processed_args.append(arg)
        input_index += 1
        if input_index >= backward_function_inputs:
            break
    return backward._call_flat(processed_args, remapped_captures)

def wrap_module(self, value: torch.nn.Module):
    from ..eval_frame import OptimizedModule
    if len(value.__dict__) == 0:
        unimplemented_v2(gb_type='Uninitialized nn.Module', context=typestr(value), explanation=f'Attempted to trace an uninitialized nn.Module of type {typestr(value)}.', hints=[*graph_break_hints.USER_ERROR, 'Ensure your nn.Module instance has called `super().__init__()`.'])
    if istype(value, OptimizedModule):
        if inspect.getattr_static(value.forward, '_torchdynamo_disable', False):
            msg = inspect.getattr_static(value.forward, '_torchdynamo_disable_msg', None)
            return DelayGraphBreakVariable(source=self.source, msg=f'Optimized `nn.Module` is wrapped with `torch.compiler.disable` (reason: {msg})')
        self.install_guards(GuardBuilder.TYPE_MATCH)
        self.source = AttrSource(self.source, '_orig_mod')
        return self.wrap_module(value._orig_mod)
    if isinstance(value, (torch.nn.RNN, torch.nn.GRU, torch.nn.LSTM)) and (not config.allow_rnn):
        unimplemented_v2(gb_type='Attempted to wrap RNN, GRU, or LSTM', context=str(value), explanation='Dynamo does not support RNN, GRU, or LSTM.', hints=[*graph_break_hints.SUPPORTABLE])
    if getattr(value, '_is_fsdp_managed_module', False):
        if not getattr(value, '_fsdp_use_orig_params', False):
            unimplemented_v2(gb_type='FSDP with use_orig_params=False', context='', explanation='Dynamo only supports FSDP with use_orig_params=True', hints=[])
        self.install_guards(GuardBuilder.TYPE_MATCH)
        result = FSDPManagedNNModuleVariable(value, source=self.get_source())
        if not SideEffects.cls_supports_mutation_side_effects(type(value)):
            return result
        return self.tx.output.side_effects.track_object_existing(value, result)
    elif mutation_guard.is_dynamic_nn_module(value, self.tx.export):
        if isinstance(value, torch.fx.experimental.proxy_tensor._AttrProxy):
            value = value.get_base()
            self.source = AttrProxySource(self.source)
        if torch._dynamo.config.inline_inbuilt_nn_modules:
            freezing = is_parameter_freezing()
            if callable(value.named_parameters) and value.named_parameters.__func__ is og_module_named_parameters_fn_ptr:
                try:
                    for (_, p) in value.named_parameters():
                        self.mark_static_input(p, guard=freezing)
                except TypeError as e:
                    raise_observed_exception(type(e), self.tx, args=list(e.args))
            if callable(value.named_buffers) and value.named_buffers.__func__ is og_module_named_buffers_fn_ptr:
                try:
                    for (_, b) in value.named_buffers():
                        self.mark_static_input(b, guard=freezing)
                except TypeError as e:
                    raise_observed_exception(type(e), self.tx, args=list(e.args))
            if <MASK>:
                self.tx.output.nn_modules[self.name] = value
        if value.__module__.startswith(('torch.nn.modules', 'torch.ao.')) and (not value.__module__.startswith('torch.nn.modules.container')) or getattr(value.__class__, '_dynamo_marked_static', False):
            new_source = self.source
            if config.inline_inbuilt_nn_modules and (not self.tx.output.export or config.install_free_tensors):
                new_source = UnspecializedBuiltinNNModuleSource(self.source)
            result = UnspecializedBuiltinNNModuleVariable(value, source=new_source)
            install_guard(new_source.make_guard(GuardBuilder.TYPE_MATCH))
        else:
            new_source = self.source
            if config.inline_inbuilt_nn_modules and (not self.tx.output.export or config.install_free_tensors):
                new_source = UnspecializedNNModuleSource(self.source)
            result = UnspecializedNNModuleVariable(value, source=new_source)
            install_guard(new_source.make_guard(GuardBuilder.TYPE_MATCH))
        self.tx.output.add_fqn_info_for_inlined_modules(value, self.source)
        if not SideEffects.cls_supports_mutation_side_effects(type(value)):
            return result
        return self.tx.output.side_effects.track_object_existing(value, result)
    elif issubclass(value.__class__, torch.nn.parallel.distributed.DistributedDataParallel):
        self.install_guards(GuardBuilder.TYPE_MATCH)
        return UnspecializedNNModuleVariable(value, source=self.get_source())
    else:
        return self.tx.output.register_attr_or_module(value, self.name, source=self.get_source())

