def sig_for_ops(opname: str) -> list[str]:
    """sig_for_ops(opname : str) -> list[str]

    Returns signatures for operator special functions (__add__ etc.)"""
    assert opname.endswith('__') and opname.startswith('__'), f'Unexpected op {opname}'
    name = opname[2:-2]
    if name == 'rpow':
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # type: ignore[has-type]']
    elif name in arithmetic_ops:
        if name.startswith('i'):
            return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # noqa: PYI034']
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...']
    elif name in logic_ops:
        return [f'def {opname}(self, other: Tensor | _int) -> Tensor: ...']
    elif name in shift_ops:
        return [f'def {opname}(self, other: Tensor | _int) -> Tensor: ...']
    elif name in symmetric_comparison_ops:
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # type: ignore[overload-overlap]', f'def {opname}(self, other: object) -> _bool: ...']
    elif name in asymmetric_comparison_ops:
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...']
    elif name in unary_ops:
        return [f'def {opname}(self) -> Tensor: ...']
    if name in to_py_type_ops:
        if name in {'bool', 'float', 'complex'}:
            tname = name
        elif <MASK>:
            tname = 'bool'
        else:
            tname = 'int'
        if tname in {'float', 'int', 'bool', 'complex'}:
            tname = '_' + tname
        return [f'def {opname}(self) -> {tname}: ...']
    raise ValueError(f'unknown op {opname!r}')

@staticmethod
def parallelize(module: 'Transformer', device_mesh: DeviceMesh, use_seq_parallel: bool, local_output_for_attn: bool=False) -> nn.Module:
    assert isinstance(module, Transformer), f'Requires Transformer but got {module}'
    if use_seq_parallel:
        root_plan = {'tok_embeddings': RowwiseParallel(input_layouts=Replicate(), output_layouts=Shard(1)), 'pos_embeddings': RowwiseParallel(input_layouts=Replicate(), output_layouts=Shard(0)), 'norm': SequenceParallel()}
    else:
        root_plan = {'tok_embeddings': RowwiseParallel(input_layouts=Replicate(), output_layouts=Replicate()), 'pos_embeddings': RowwiseParallel(input_layouts=Replicate(), output_layouts=Replicate())}
    module_tp = parallelize_module(module, device_mesh, root_plan)
    for layer in module_tp.layers:
        layer_parallelize_plan = {}
        if use_seq_parallel:
            layer_parallelize_plan['attention'] = PrepareModuleInput(input_layouts=Shard(1), desired_input_layouts=Replicate())
            layer_parallelize_plan['attention_norm'] = SequenceParallel()
            layer_parallelize_plan['ffn_norm'] = SequenceParallel()
        layer_parallelize_plan['attention.wq'] = ColwiseParallel(use_local_output=local_output_for_attn)
        layer_parallelize_plan['attention.wk'] = ColwiseParallel(use_local_output=local_output_for_attn)
        layer_parallelize_plan['attention.wv'] = ColwiseParallel(use_local_output=local_output_for_attn)
        layer_parallelize_plan['attention.wo'] = RowwiseParallel(output_layouts=Shard(1)) if use_seq_parallel else RowwiseParallel()
        layer_parallelize_plan['feed_forward.w1'] = ColwiseParallel(input_layouts=Shard(1)) if use_seq_parallel else ColwiseParallel()
        layer_parallelize_plan['feed_forward.w2'] = RowwiseParallel(output_layouts=Shard(1)) if use_seq_parallel else RowwiseParallel()
        parallelize_module(layer, device_mesh, layer_parallelize_plan)
    output_parallelize_plan = ColwiseParallel(input_layouts=Shard(1), output_layouts=Replicate()) if use_seq_parallel else ColwiseParallel(output_layouts=Replicate())
    parallelize_module(module_tp.output, device_mesh, output_parallelize_plan)
    if local_output_for_attn:
        for layer in module_tp.layers:
            layer.attention.n_heads = module_tp.model_args.n_heads // device_mesh.size()
    if <MASK>:
        module_tp.output.weight = module_tp.tok_embeddings.weight
    return module_tp

def find_smallest_i(graph: fx.Graph, prefix: str) -> int:
    i = 0
    for node in graph.nodes:
        if node.op == 'get_attr' and node.target.startswith(prefix):
            if <MASK>:
                post_fix = node.target.split(prefix)[-1]
                if post_fix.isdigit():
                    i = max(i, int(post_fix))
    for key in existing_keys:
        if key.startswith(prefix):
            if len(key) > len(prefix):
                post_fix = key.split(prefix)[-1]
                if post_fix.isdigit():
                    i = max(i, int(post_fix))
    return i + 1

@staticmethod
def load_with_key(key: str, debug_lines: list[str], example_inputs: Sequence[InputType], local: bool, remote_cache: RemoteCache[JsonDataTy] | None, is_backward: bool, constants: CompiledFxGraphConstants, evaluate_guards: Callable[[str, list[int] | list[torch.SymInt]], bool] | None=None) -> tuple[CompiledFxGraph | None, dict[str, Any]]:
    """
        Lookup the graph with the given key, and return results and metadata.
        Doesn't do any logging on its own, because AOTAutograd handles a cache miss
        differently from FXGraphCache.
        """
    (compiled_graph, cache_info) = FxGraphCache._lookup_graph(key, example_inputs, local, remote_cache, constants, evaluate_guards)
    cache_info = {**cache_info, 'key': key, 'components': debug_lines, 'cache_event_time': time_ns()}
    if compiled_graph is not None:
        log.info('fx graph cache hit for key %s', key)
        counters['inductor']['fxgraph_cache_hit'] += 1
        cache_info['cache_state'] = 'hit'
        if remote_cache:
            CompileEventLogger.try_(CompileEventLogger.increment_toplevel, 'inductor_fx_remote_cache_hit_count')
            CompileEventLogger.try_(CompileEventLogger.add_to_set_toplevel, 'inductor_fx_remote_cache_hit_keys', key)
        if (time_saved_ns := compiled_graph._time_taken_ns) is not None:
            cache_info['time_saved_ns'] = time_saved_ns
            CompileEventLogger.try_(CompileEventLogger.increment_toplevel, 'distributed_ephemeral_timeout_us', time_saved_ns // 1000)
            if <MASK>:
                cache_info['ephemeral_timeout_increase'] = ephemeral_increase
    else:
        if remote_cache:
            CompileEventLogger.try_(CompileEventLogger.increment_toplevel, 'inductor_fx_remote_cache_miss_count')
            CompileEventLogger.try_(CompileEventLogger.add_to_set_toplevel, 'inductor_fx_remote_cache_miss_keys', key)
        log.info('fx graph cache miss for key %s', key)
        counters['inductor']['fxgraph_cache_miss'] += 1
        cache_info['cache_state'] = 'miss'
    return (compiled_graph, cache_info)

def user_defined_triton_kernel_transitive_closure_source_code(kernel) -> str:
    """
    Given a triton kernel function pointer collect the transitive closure of
    its dependencies
    """
    compile_wrapper = IndentedBuffer()
    compile_wrapper.splice(kernel.src, strip=True)
    import triton
    from triton import JITFunction
    from triton.language import constexpr
    symbols_included = OrderedSet([kernel.__name__])

    def traverse(cur_kernel):
        unqualified_loads = OrderedSet((inst.argval for inst in dis.Bytecode(cur_kernel.fn) if inst.opname == 'LOAD_GLOBAL'))
        global_annotations = cur_kernel.fn.__globals__.get('__annotations__', {})
        for symbol_name in cur_kernel.fn.__code__.co_names:
            if symbol_name in symbols_included:
                continue
            if symbol_name in cur_kernel.fn.__globals__:
                symbol = cur_kernel.fn.__globals__[symbol_name]
                if isinstance(symbol, JITFunction):
                    compile_wrapper.newline()
                    compile_wrapper.writeline('@triton.jit')
                    compile_wrapper.splice(symbol.src, strip=True)
                    symbols_included.add(symbol_name)
                    traverse(symbol)
                elif hasattr(triton, 'constexpr_function') and isinstance(symbol, triton.runtime.jit.ConstexprFunction):
                    compile_wrapper.newline()
                    compile_wrapper.writeline('@triton.constexpr_function')
                    compile_wrapper.splice(symbol.src, strip=True)
                    symbols_included.add(symbol_name)
                    traverse(symbol)
                elif isinstance(symbol, (int, str, bool, constexpr)):
                    compile_wrapper.newline()
                    if isinstance(symbol, constexpr):
                        symbol_str = f'tl.constexpr({symbol.value!r})'
                    else:
                        symbol_str = f'{symbol!r}'
                    if <MASK>:
                        if isinstance(annotation, type):
                            annotation_code = f': {annotation.__module__}.{annotation.__name__}'
                        else:
                            annotation_code = f': {annotation!r}'
                        compile_wrapper.writeline(f'{symbol_name}{annotation_code} = {symbol_str}')
                    else:
                        compile_wrapper.writeline(f'{symbol_name} = {symbol_str}')
                    symbols_included.add(symbol_name)
                elif symbol_name in unqualified_loads and symbol_name != 'tl' and hasattr(symbol, '__module__') and symbol.__module__.startswith('triton'):
                    compile_wrapper.writeline(f'from {symbol.__module__} import {symbol.__name__} as {symbol_name}')
                    symbols_included.add(symbol_name)
    traverse(kernel)
    return compile_wrapper.getvalue()

def _add_file(filename: str) -> None:
    try:
        with tokenize.open(filename) as f:
            tokens = list(tokenize.generate_tokens(f.readline))
    except (OSError, tokenize.TokenError):
        cache[filename] = {}
        return
    result: dict[int, str] = {}
    cur_name = ''
    cur_indent = 0
    significant_indents: list[int] = []
    for (i, token) in enumerate(tokens):
        if <MASK>:
            cur_indent += 1
        elif token.type == tokenize.DEDENT:
            cur_indent -= 1
            if significant_indents and cur_indent == significant_indents[-1]:
                significant_indents.pop()
                cur_name = cur_name.rpartition('.')[0]
        elif token.type == tokenize.NAME and i + 1 < len(tokens) and (tokens[i + 1].type == tokenize.NAME) and (token.string == 'class' or token.string == 'def'):
            significant_indents.append(cur_indent)
            if cur_name:
                cur_name += '.'
            cur_name += tokens[i + 1].string
        result[token.start[0]] = cur_name
    cache[filename] = result

def finalize_options(self):
    log.info('unifying config_fc, config, build_clib, build_ext, build commands --fcompiler options')
    build_clib = self.get_finalized_command('build_clib')
    build_ext = self.get_finalized_command('build_ext')
    config = self.get_finalized_command('config')
    build = self.get_finalized_command('build')
    cmd_list = [self, config, build_clib, build_ext, build]
    for a in ['fcompiler']:
        l = []
        for c in cmd_list:
            v = getattr(c, a)
            if <MASK>:
                if not isinstance(v, str):
                    v = v.compiler_type
                if v not in l:
                    l.append(v)
        if not l:
            v1 = None
        else:
            v1 = l[0]
        if len(l) > 1:
            log.warn('  commands have different --%s options: %s, using first in list as default' % (a, l))
        if v1:
            for c in cmd_list:
                if getattr(c, a) is None:
                    setattr(c, a, v1)

def as_numpy_array(array: Array, *, xp: ModuleType) -> np.typing.NDArray[Any]:
    """
    Convert array to NumPy, bypassing GPU-CPU transfer guards and densification guards.
    """
    if is_cupy_namespace(xp):
        return xp.asnumpy(array)
    if <MASK>:
        return array.todense()
    if is_torch_namespace(xp):
        array = to_device(array, 'cpu')
    if is_array_api_strict_namespace(xp):
        cpu: Device = xp.Device('CPU_DEVICE')
        array = to_device(array, cpu)
    if is_jax_namespace(xp):
        import jax
        cpu = cast(Device, jax.devices('cpu')[0])
        array = to_device(array, cpu)
    return np.asarray(array)

@register_jagged_func(torch.ops.aten.broadcast_tensors.default, 'tensors: any')
def broadcast_tensors(func, *args, **kwargs):
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    tensors = new_kwargs.pop('tensors')
    if len(tensors) == 0:
        raise ValueError('broadcast_tensors(): expected at least one tensor input')
    if len(tensors) == 1:
        return tensors[0]
    outs = []
    broadcast_shape = torch.broadcast_shapes(*(t.shape for t in tensors))
    njt = next((t for t in tensors if isinstance(t, NestedTensor)))
    for t in tensors:
        if <MASK>:
            outs.append(t.broadcast_to(broadcast_shape))
        elif t.dim() < len(broadcast_shape):
            outs.append(NestedTensor(t.broadcast_to(njt._values.shape), **extract_kwargs(njt)))
        else:
            raise ValueError('broadcast_tensors(): broadcasting nested tensors with dense tensors of equal or higher dim is not currently supported')
    return tuple(outs)

def _sink_params(module: torch.nn.Module, inputs_to_state: dict[str, list[str]], scope: list[str], module_id_to_inputs_removed: Optional[dict[int, set[str]]]=None):
    """Sink params, buffers, and constants from graph inputs into get_attr nodes.

    Exported modules are purely functional, so they pass their parameters and
    buffers in as inputs to the graph.

    To replicate eager's semantics, we need to get them from the module state
    via get_attr instead.

    module: GraphModule, potentially containing nested submodules.
    inputs_to_state: mapping graph input names to the corresponding key in the state_dict.
    scope: tracks where we are in the module hierarchy, so that we can emit the
        right `getattr(self, "foo.bar")` calls, etc.
    module_id_to_inputs_removed: records inputs removed by child modules, mapping
        the module object id to the list of placeholder node names in the child module
        that were removed.
    """
    if module_id_to_inputs_removed is None:
        module_id_to_inputs_removed = defaultdict(set)
    if <MASK>:
        return {id(module): module_id_to_inputs_removed[id(module)]}
    for (name, submodule) in module._modules.items():
        submod_id_to_inputs_removed = _sink_params(cast('torch.nn.Module', submodule), inputs_to_state, scope + [name], module_id_to_inputs_removed)
        for (k, v) in submod_id_to_inputs_removed.items():
            module_id_to_inputs_removed[k].update(v)
    graph = getattr(module, 'graph', None)
    if graph is None or len(graph.nodes) == 0:
        return module_id_to_inputs_removed
    assert isinstance(graph, torch.fx.Graph)
    inputs = list(filter(lambda n: n.op == 'placeholder', graph.nodes))
    the_last_input = None if len(inputs) == 0 else inputs[-1]
    call_module_nodes = filter(lambda n: n.op == 'call_module', graph.nodes)
    for node in call_module_nodes:
        submodule = _get_attr(module, node.target)
        if submodule is not None and id(submodule) in module_id_to_inputs_removed:
            node.args = tuple(filter(lambda n: n.name not in module_id_to_inputs_removed[id(submodule)], node.args))
    inputs_to_state_of_scope: dict[torch.fx.Node, list[str]] = {}
    for node in inputs:
        if node.name not in inputs_to_state:
            continue
        state_name = None
        for sn in inputs_to_state[node.name]:
            sn_split = sn.split('.')
            if sn_split[:len(scope)] == [x.split('@')[0] for x in scope]:
                state_name = sn_split
                break
        if state_name is None:
            continue
        inputs_to_state_of_scope[node] = state_name
    inputs_removed: set[str] = set()
    for (node, state_name) in inputs_to_state_of_scope.items():
        if len(node.users) > 0:
            attr_path = state_name[len(scope):]
            state_attr = _get_attr_via_attr_list(module, attr_path)
            assert isinstance(state_attr, (torch.Tensor, torch.ScriptObject))
            with graph.inserting_after(the_last_input):
                new_node = graph.create_node('get_attr', '.'.join(attr_path))
            node.replace_all_uses_with(new_node, propagate_meta=True)
        graph.erase_node(node)
        inputs_removed.add(node.name)
    if isinstance(module, InterpreterModule):
        module.finalize()
    return {id(module): inputs_removed}

def set_flags(_enabled=None, _deterministic=None, _allow_tf32=None, _fp32_precision='none'):
    orig_flags = (torch._C._get_mkldnn_enabled(), torch._C._get_mkldnn_deterministic(), torch._C._get_onednn_allow_tf32(), torch._C._get_fp32_precision_getter('mkldnn', 'all'))
    if _enabled is not None:
        torch._C._set_mkldnn_enabled(_enabled)
    if <MASK>:
        torch._C._set_mkldnn_deterministic(_deterministic)
    if _allow_tf32 is not None:
        torch._C._set_onednn_allow_tf32(_allow_tf32)
    if _fp32_precision is not None:
        torch._C._set_fp32_precision_setter('mkldnn', 'all', _fp32_precision)
    return orig_flags

def add_loss(self, losses, inputs=None):
    previous_losses_length = len(self._losses)
    previous_callable_losses_length = len(self._callable_losses)
    super(Layer, self).add_loss(losses, inputs=inputs)
    if <MASK>:
        new_losses = self._losses[previous_losses_length:]
        new_callable_losses = self._callable_losses[previous_callable_losses_length:]
        for regularizer in new_callable_losses:
            loss_tensor = regularizer()
            if loss_tensor is not None:
                new_losses.append(loss_tensor)
        _add_elements_to_collection(new_losses, ops.GraphKeys.REGULARIZATION_LOSSES)

def preprocess_weights(obj: NDFrame, weights, axis: AxisInt) -> np.ndarray:
    """
    Process and validate the `weights` argument to `NDFrame.sample` and
    `.GroupBy.sample`.

    Returns `weights` as an ndarray[np.float64], validated except for normalizing
    weights (because that must be done groupwise in groupby sampling).
    """
    if isinstance(weights, ABCSeries):
        weights = weights.reindex(obj.axes[axis])
    if isinstance(weights, str):
        if isinstance(obj, ABCDataFrame):
            if axis == 0:
                try:
                    weights = obj[weights]
                except KeyError as err:
                    raise KeyError('String passed to weights not a valid column') from err
            else:
                raise ValueError('Strings can only be passed to weights when sampling from rows on a DataFrame')
        else:
            raise ValueError('Strings cannot be passed as weights when sampling from a Series.')
    if <MASK>:
        func = obj._constructor
    else:
        func = obj._constructor_sliced
    weights = func(weights, dtype='float64')._values
    if len(weights) != obj.shape[axis]:
        raise ValueError('Weights and axis to be sampled must be of same length')
    if lib.has_infs(weights):
        raise ValueError('weight vector may not include `inf` values')
    if (weights < 0).any():
        raise ValueError('weight vector many not include negative values')
    missing = np.isnan(weights)
    if missing.any():
        weights = weights.copy()
        weights[missing] = 0
    return weights

def _match(modules: dict[str, nn.ModuleDict], node: Node, current: Union[nn.Module, Any]) -> bool:
    """
    checks to see if a single node of a pattern matches
    """
    if isinstance(current, type) and issubclass(current, MatchAllNode):
        return True
    if not isinstance(node, Node):
        return False
    if isinstance(current, type) and issubclass(current, torch.nn.Module):
        return node.op == 'call_module' and parametrize.type_before_parametrizations(modules[node.target]) == current
    elif callable(current):
        return node.op == 'call_function' and node.target is current
    elif <MASK>:
        return node.target == current
    return False

def persistent_id(obj: Any) -> Optional[tuple]:
    if isinstance(obj, type) and issubclass(obj, nn.Module):
        if obj in serialized_container_types:
            return None
        serialized_container_types[obj] = True
        source_file = source = None
        try:
            (source_lines, _, source_file) = get_source_lines_and_file(obj)
            source = ''.join(source_lines)
        except Exception:
            warnings.warn("Couldn't retrieve source code for container of type " + obj.__name__ + ". It won't be checked for correctness upon loading.")
        return ('module', obj, source_file, source)
    if isinstance(obj, torch.storage.TypedStorage) or torch.is_storage(obj):
        storage: torch.UntypedStorage
        if isinstance(obj, torch.storage.TypedStorage):
            storage = obj._untyped_storage
            storage_dtype = obj.dtype
            storage_type_str = obj._pickle_storage_type()
            storage_type = getattr(torch, storage_type_str)
            dtype = obj.dtype
            storage_numel = obj._size()
        elif isinstance(obj, torch.UntypedStorage):
            storage = obj
            storage_dtype = torch.uint8
            storage_type = normalize_storage_type(type(obj))
            dtype = torch.uint8
            storage_numel = storage.nbytes()
        else:
            raise TypeError(f'type not recognized: {type(obj)}')
        if <MASK>:
            if storage.data_ptr() in storage_dtypes:
                if storage_dtype != storage_dtypes[storage.data_ptr()]:
                    raise RuntimeError('Cannot save multiple tensors or storages that view the same data as different types')
            else:
                storage_dtypes[storage.data_ptr()] = storage_dtype
        view_metadata: Optional[tuple[str, int, int]]
        offset = 0
        storage_key = str(storage._cdata)
        location = location_tag(storage)
        if storage_key not in serialized_storages:
            serialized_storages[storage_key] = (storage, dtype)
        is_view = storage._cdata != storage._cdata
        if is_view:
            view_metadata = (str(storage._cdata), offset, storage.nbytes())
        else:
            view_metadata = None
        res = ('storage', storage_type, storage_key, location, storage_numel, view_metadata)
        return res
    return None

def _create_sub_mesh(self, layout: _MeshLayout, submesh_dim_names: tuple[str, ...]) -> 'DeviceMesh':
    root_mesh = self._get_root_mesh()
    slice_dim_group_name = []
    for name in submesh_dim_names:
        if <MASK>:
            slice_dim_group_name.append(self._dim_group_names[not_none(self._mesh_dim_names).index(name)])
        else:
            flatten_mesh = self._flatten_mapping[name]
            slice_dim_group_name.append(flatten_mesh._dim_group_names[not_none(flatten_mesh._mesh_dim_names).index(name)])
    res_submesh = DeviceMesh(self._device_type, _layout=layout, _rank_map=root_mesh._rank_map, mesh_dim_names=submesh_dim_names, _root_mesh=root_mesh, _init_backend=False)
    res_submesh._dim_group_names = slice_dim_group_name
    return res_submesh

@doc_controls.do_not_generate_docs
def placeholder(shape=None, ndim=None, dtype=None, sparse=False, name=None, ragged=False):
    """Instantiates a placeholder tensor and returns it.

  Args:
      shape: Shape of the placeholder
          (integer tuple, may include `None` entries).
      ndim: Number of axes of the tensor.
          At least one of {`shape`, `ndim`} must be specified.
          If both are specified, `shape` is used.
      dtype: Placeholder type.
      sparse: Boolean, whether the placeholder should have a sparse type.
      name: Optional name string for the placeholder.
      ragged: Boolean, whether the placeholder should have a ragged type.
          In this case, values of 'None' in the 'shape' argument represent
          ragged dimensions. For more information about RaggedTensors, see this
          [guide](https://www.tensorflow.org/guide/ragged_tensors).

  Raises:
      ValueError: If called with sparse = True and ragged = True.

  Returns:
      Tensor instance (with Keras metadata included).

  Examples:


  >>> input_ph = tf.keras.backend.placeholder(shape=(2, 4, 5))
  >>> input_ph
  <KerasTensor: shape=(2, 4, 5) dtype=float32 (created by layer ...)>

  """
    if sparse and ragged:
        raise ValueError('Cannot set both sparse and ragged to True when creating a placeholder.')
    if dtype is None:
        dtype = floatx()
    if not shape:
        if ndim:
            shape = (None,) * ndim
    if ops.executing_eagerly_outside_functions():
        if sparse:
            spec = sparse_tensor.SparseTensorSpec(shape=shape, dtype=dtype)
        elif <MASK>:
            ragged_rank = 0
            for i in range(1, len(shape)):
                if shape[i] is None or (hasattr(shape[i], 'value') and shape[i].value is None):
                    ragged_rank = i
            spec = ragged_tensor.RaggedTensorSpec(shape=shape, dtype=dtype, ragged_rank=ragged_rank)
        else:
            spec = tensor_lib.TensorSpec(shape=shape, dtype=dtype, name=name)
        x = keras_tensor.keras_tensor_from_type_spec(spec, name=name)
    else:
        with get_graph().as_default():
            if sparse:
                x = array_ops.sparse_placeholder(dtype, shape=shape, name=name)
            elif ragged:
                ragged_rank = 0
                for i in range(1, len(shape)):
                    if shape[i] is None:
                        ragged_rank = i
                type_spec = ragged_tensor.RaggedTensorSpec(shape=shape, dtype=dtype, ragged_rank=ragged_rank)

                def tensor_spec_to_placeholder(tensorspec):
                    return array_ops.placeholder(tensorspec.dtype, tensorspec.shape)
                x = nest.map_structure(tensor_spec_to_placeholder, type_spec, expand_composites=True)
            else:
                x = array_ops.placeholder(dtype, shape=shape, name=name)
    if context.executing_eagerly():
        from tensorflow.python.keras.engine import input_layer
        x = input_layer.Input(tensor=x)
        x._is_backend_placeholder = True
    return x

def _validate_deprecation_args(date, instructions):
    if <MASK>:
        raise ValueError(f'Date must be in format YYYY-MM-DD. Received: {date}')
    if not instructions:
        raise ValueError("Don't deprecate things without conversion instructions! Specify the `instructions` argument.")

def call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if self.value is itertools.product:
        if any((kw != 'repeat' for kw in kwargs.keys())):
            unimplemented_v2(gb_type='Unsupported kwargs for itertools.product', context=f'call_function {self} {args} {kwargs}', explanation=f"Expected kwargs: 'repeat', but got {','.join(set(kwargs.keys()) - {'repeat'})}", hints=[*graph_break_hints.USER_ERROR])
        if 'repeat' in kwargs.keys():
            r = kwargs['repeat'].as_python_constant()
        else:
            r = 1
        seqs = [arg.force_unpack_var_sequence(tx) for arg in args]
        items = [variables.TupleVariable(list(item)) for item in itertools.product(*seqs, repeat=r)]
        return variables.ListIteratorVariable(items, mutation_type=ValueMutationNew())
    elif self.value is itertools.combinations and (not kwargs) and (len(args) == 2) and args[0].has_unpack_var_sequence(tx) and args[1].is_python_constant():
        iterable = args[0].unpack_var_sequence(tx)
        r = args[1].as_python_constant()
        items = []
        for item in itertools.combinations(iterable, r):
            items.append(variables.TupleVariable(list(item)))
        return variables.ListIteratorVariable(items, mutation_type=ValueMutationNew())
    elif self.value is itertools.groupby:
        if any((kw != 'key' for kw in kwargs.keys())):
            unimplemented_v2(gb_type='Unsupported kwargs for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f"Expected kwargs: 'key', but got {','.join(set(kwargs.keys()) - {'key'})}", hints=[*graph_break_hints.USER_ERROR])

        def retrieve_const_key(key):
            if isinstance(key, variables.SymNodeVariable):
                return key.evaluate_expr()
            elif isinstance(key, variables.ConstantVariable):
                return key.as_python_constant()
            else:
                unimplemented_v2(gb_type='Unsupported key type for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace itertools.groupby with key type: {str(type(key))}. We only support grouping keys that are constants (int, float, str, etc.)', hints=[*graph_break_hints.SUPPORTABLE])
        if len(args) == 1 and args[0].has_unpack_var_sequence(tx):
            seq = args[0].unpack_var_sequence(tx)
        else:
            unimplemented_v2(gb_type='Unsupported arguments for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace itertools.groupby with args: {args} and kwargs: {kwargs}. itertools.groupby expects an iterable to group and an optional key function to determine groupings.', hints=['Make sure the arguments to itertools.groupby are correct.', *graph_break_hints.SUPPORTABLE])
        if 'key' in kwargs:

            def keyfunc(x):
                return retrieve_const_key(kwargs.get('key').call_function(tx, [x], {}))
        else:

            def keyfunc(x):
                return retrieve_const_key(x)
        result = []
        try:
            for (k, v) in itertools.groupby(seq, key=keyfunc):
                result.append(variables.TupleVariable([variables.ConstantVariable.create(k) if variables.ConstantVariable.is_literal(k) else k, variables.ListIteratorVariable(list(v), mutation_type=ValueMutationNew())], mutation_type=ValueMutationNew()))
        except Exception as e:
            unimplemented_v2(gb_type='Unexpected failure during itertools.groupby() iteration', context=f'call_function {self} {args} {kwargs}', explanation='Unexpected failure in invoking function during groupby', hints=[*graph_break_hints.SUPPORTABLE], from_exc=e)
        return variables.ListIteratorVariable(result, mutation_type=ValueMutationNew())
    elif self.value is itertools.repeat:
        if len(args) < 2:
            return variables.RepeatIteratorVariable(*args, mutation_type=ValueMutationNew())
        return tx.inline_user_function_return(VariableTracker.build(tx, polyfills.repeat), args, kwargs)
    elif self.value is itertools.count:
        return variables.CountIteratorVariable(*args, mutation_type=ValueMutationNew())
    elif self.value is itertools.permutations and (len(args) == 1 or (len(args) == 2 and args[1].is_python_constant())) and (not kwargs):
        if <MASK>:
            r = args[1].as_python_constant()
        else:
            r = None
        items = [variables.TupleVariable(list(item)) for item in itertools.permutations(args[0].force_unpack_var_sequence(tx), r)]
        return variables.ListIteratorVariable(items, mutation_type=ValueMutationNew())
    else:
        return super().call_function(tx, args, kwargs)

@skip_but_pass_in_sandcastle_if(BACKEND not in DistTestCases.backend_feature['subgroup'], f'The {BACKEND} backend does not support creating subgroups on CUDA devices')
@require_world_size(4)
@skip_if_lt_x_gpu(4)
def test_new_subgroups_by_enumeration(self):
    (_group, _group_id, rank) = self._init_global_test()
    rank_to_GPU = init_multigpu_helper(dist.get_world_size(), BACKEND)
    device_id = rank_to_GPU[rank][0]
    (cur_subgroup, subgroups) = dist.new_subgroups_by_enumeration(ranks_per_subgroup_list=[[0, 2], [1, 3]])
    if device_id >= 4:
        self.assertIsNone(cur_subgroup)
    else:
        self.assertEqual(cur_subgroup.size(), 2)
        self.assertEqual(len(subgroups), 2)
        if <MASK>:
            self.assertEqual(cur_subgroup, subgroups[0])
        else:
            self.assertEqual(cur_subgroup, subgroups[1])
    for subgroup in subgroups:
        dist.destroy_process_group(subgroup)

def _handle_fromlist(self, module, fromlist, *, recursive=False):
    """Figure out what __import__ should return.

        The import_ parameter is a callable which takes the name of module to
        import. It is required to decouple the function from assuming importlib's
        import implementation is desired.

        """
    module_name = demangle(module.__name__)
    if hasattr(module, '__path__'):
        for x in fromlist:
            if not isinstance(x, str):
                if recursive:
                    where = module_name + '.__all__'
                else:
                    where = "``from list''"
                raise TypeError(f'Item in {where} must be str, not {type(x).__name__}')
            elif <MASK>:
                if not recursive and hasattr(module, '__all__'):
                    self._handle_fromlist(module, module.__all__, recursive=True)
            elif not hasattr(module, x):
                from_name = f'{module_name}.{x}'
                try:
                    self._gcd_import(from_name)
                except ModuleNotFoundError as exc:
                    if exc.name == from_name and self.modules.get(from_name, _NEEDS_LOADING) is not None:
                        continue
                    raise
    return module

def compile(self):
    num_info = {}
    if num_info:
        self.include_dirs.extend(num_info.get('include_dirs', []))
    ext_args = {'name': self.modulename, 'sources': self.sources, 'include_dirs': self.include_dirs, 'library_dirs': self.library_dirs, 'libraries': self.libraries, 'define_macros': self.define_macros, 'undef_macros': self.undef_macros, 'extra_objects': self.extra_objects, 'f2py_options': self.f2py_flags}
    if <MASK>:
        for n in self.sysinfo_flags:
            i = get_info(n)
            if not i:
                print(f'No {n!r} resources foundin system (try `f2py --help-link`)')
            dict_append(ext_args, **i)
    ext = Extension(**ext_args)
    sys.argv = [sys.argv[0]] + self.setup_flags
    sys.argv.extend(['build', '--build-temp', self.build_dir, '--build-base', self.build_dir, '--build-platlib', '.', '--disable-optimization'])
    if self.fc_flags:
        sys.argv.extend(['config_fc'] + self.fc_flags)
    if self.flib_flags:
        sys.argv.extend(['build_ext'] + self.flib_flags)
    setup(ext_modules=[ext])
    if self.remove_build_dir and os.path.exists(self.build_dir):
        print(f'Removing build directory {self.build_dir}')
        shutil.rmtree(self.build_dir)

def find_args_with_derivatives(differentiable_inputs: list[DifferentiableInput]) -> list[DifferentiableInput]:
    """Find arguments that have derivative definitions"""
    if <MASK>:
        return differentiable_inputs
    names = {name for d in info.derivatives for name in d.var_names}
    differentiable = [arg for arg in differentiable_inputs if arg.name in names]
    if len(differentiable) != len(names):
        missing = names - {arg.name for arg in differentiable}
        raise RuntimeError(f'Missing arguments for derivatives: {missing} in {info.name}')
    return differentiable

def get_field_type(self, data_type, description):
    field_type = super().get_field_type(data_type, description)
    if 'auto_increment' in description.extra:
        if field_type == 'IntegerField':
            return 'AutoField'
        elif field_type == 'BigIntegerField':
            return 'BigAutoField'
        elif field_type == 'SmallIntegerField':
            return 'SmallAutoField'
    if description.is_unsigned:
        if field_type == 'BigIntegerField':
            return 'PositiveBigIntegerField'
        elif field_type == 'IntegerField':
            return 'PositiveIntegerField'
        elif field_type == 'SmallIntegerField':
            return 'PositiveSmallIntegerField'
    if description.data_type.upper() == 'UUID':
        return 'UUIDField'
    if <MASK>:
        return 'JSONField'
    return field_type

def transform_to_z3(constraint, counter, dimension_dict):
    if isinstance(constraint, Conj):
        conjuncts = []
        for c in constraint.conjucts:
            (new_c, counter) = transform_to_z3(c, counter, dimension_dict)
            conjuncts.append(new_c)
        return (z3.And(conjuncts), counter)
    elif isinstance(constraint, Disj):
        disjuncts = []
        for c in constraint.disjuncts:
            (new_c, counter) = transform_to_z3(c, counter, dimension_dict)
            disjuncts.append(new_c)
        return (z3.Or(disjuncts), counter)
    elif isinstance(constraint, T):
        return (True, counter)
    elif isinstance(constraint, F):
        return (False, counter)
    elif isinstance(constraint, BinConstraintT):
        if constraint.op == op_eq:
            (lhs, counter) = transform_var(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_var(constraint.rhs, counter, dimension_dict)
            return (lhs == rhs, counter)
        else:
            raise NotImplementedError('Method not yet implemented')
    elif isinstance(constraint, BinConstraintD):
        if constraint.op == op_eq:
            if isinstance(constraint.lhs, BVar) and is_bool_expr(constraint.rhs):
                (transformed_rhs, counter) = transform_to_z3(constraint.rhs, counter, dimension_dict)
                transformed_lhs = z3.Bool(constraint.lhs.c)
                return (transformed_lhs == transformed_rhs, counter)
            elif is_dim(constraint.lhs) and is_dim(constraint.rhs):
                (lhs, counter) = transform_dimension(constraint.lhs, counter, dimension_dict)
                (rhs, counter) = transform_dimension(constraint.rhs, counter, dimension_dict)
                return (lhs == rhs, counter)
            else:
                (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
                (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
                return (lhs == rhs, counter)
        elif constraint.op == op_neq:
            assert is_dim(constraint.lhs)
            assert is_dim(constraint.rhs)
            (lhs, counter) = transform_dimension(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_dimension(constraint.rhs, counter, dimension_dict)
            if <MASK>:
                if constraint.rhs == Dyn:
                    return (lhs.arg(0) == 1, counter)
                elif constraint.lhs == Dyn:
                    return (rhs.arg(0) == 1, counter)
            elif isinstance(constraint.lhs, int) or isinstance(constraint.rhs, int):
                if isinstance(constraint.lhs, int):
                    return (z3.Or([rhs.arg(0) == 0, z3.And([rhs.arg(0) == 1, lhs.arg(1) != rhs.arg(1)])]), counter)
                elif isinstance(constraint.rhs, int):
                    return (z3.Or([lhs.arg(0) == 0, z3.And([lhs.arg(0) == 1, lhs.arg(1) != rhs.arg(1)])]), counter)
            else:
                return (z3.Or([z3.And([lhs.arg(0) == 0, rhs.arg(0) != 0]), z3.And([lhs.arg(0) != 0, rhs.arg(0) == 0]), z3.And([lhs.arg(0) != 0, rhs.arg(0) != 0, lhs.arg(1) != rhs.arg(1)])]), counter)
        elif constraint.op == op_leq:
            assert is_dim(constraint.lhs) and is_dim(constraint.rhs)
            (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
            return (lhs <= rhs, counter)
        elif constraint.op == op_gt:
            assert is_dim(constraint.lhs) and is_dim(constraint.rhs)
            (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
            return (lhs > rhs, counter)
        elif constraint.op == op_lt:
            assert is_dim(constraint.lhs) and is_dim(constraint.rhs)
            (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
            return (lhs < rhs, counter)
        else:
            raise NotImplementedError('operation not yet implemented')
    else:
        raise NotImplementedError('Operation not yet implemented')

@tf_export(v1=['quantize_v2'])
@dispatch.add_dispatch_support
@deprecation.deprecated('2017-10-25', '`tf.quantize_v2` is deprecated, please use `tf.quantization.quantize` instead.')
def quantize_v2(input, min_range, max_range, T, mode='MIN_COMBINED', name=None, round_mode='HALF_AWAY_FROM_ZERO', narrow_range=False, axis=None, ensure_minimum_range=0.01):
    if axis is None:
        axis = -1
    elif <MASK>:
        if input.shape.ndims is None:
            raise ValueError('input should have known rank to use negative axis.')
        axis %= input.shape.ndims
    if ensure_minimum_range != 0.01:
        return gen_array_ops.quantize_v2(input, min_range, max_range, T=T, mode=mode, name=name, round_mode=round_mode, narrow_range=narrow_range, axis=axis, ensure_minimum_range=ensure_minimum_range)
    return gen_array_ops.quantize_v2(input, min_range, max_range, T=T, mode=mode, name=name, round_mode=round_mode, narrow_range=narrow_range, axis=axis)

def extract(self, to_path):
    members = self._archive.getmembers()
    leading = self.has_leading_dir((x.name for x in members))
    for member in members:
        name = member.name
        if leading:
            name = self.split_leading_dir(name)[1]
        filename = self.target_filename(to_path, name)
        if member.isdir():
            if <MASK>:
                os.makedirs(filename, exist_ok=True)
        else:
            try:
                extracted = self._archive.extractfile(member)
            except (KeyError, AttributeError) as exc:
                print('In the tar file %s the member %s is invalid: %s' % (name, member.name, exc))
            else:
                dirname = os.path.dirname(filename)
                if dirname:
                    os.makedirs(dirname, exist_ok=True)
                with open(filename, 'wb') as outfile:
                    shutil.copyfileobj(extracted, outfile)
                    self._copy_permissions(member.mode, filename)
            finally:
                if extracted:
                    extracted.close()

@staticmethod
def build_Name(ctx, expr):
    r = ctx.make_range(expr.lineno, expr.col_offset, expr.col_offset + len(expr.id))
    if expr.id.startswith(_reserved_prefix):
        raise NotSupportedError(r, "names of variables used in JIT-ed functions can't start with " + _reserved_prefix)
    if <MASK>:
        return TrueLiteral(r)
    elif expr.id == 'False':
        return FalseLiteral(r)
    elif expr.id == 'None':
        return NoneLiteral(r)
    elif expr.id == 'Ellipsis':
        return Dots(r)
    return Var(Ident(r, expr.id))

@cache_readonly
@final
def _is_all_dates(self) -> bool:
    """
        Whether or not the index values only consist of dates.
        """
    if needs_i8_conversion(self.dtype):
        return True
    elif self.dtype != _dtype_obj:
        return False
    elif <MASK>:
        return False
    return is_datetime_array(ensure_object(self._values))

def embed_library(whl_path, lib_soname, update_tag=False):
    patcher = AlignedPatchelf()
    out_dir = TemporaryDirectory()
    whl_name = os.path.basename(whl_path)
    tmp_whl_name = os.path.join(out_dir.name, whl_name)
    with InWheelCtx(whl_path) as ctx:
        torchlib_path = os.path.join(ctx._tmpdir.name, 'torch', 'lib')
        ctx.out_wheel = tmp_whl_name
        (new_lib_path, new_lib_soname) = (None, None)
        for (filename, _) in elf_file_filter(ctx.iter_files()):
            if <MASK>:
                continue
            libtree = lddtree(filename)
            if lib_soname not in libtree['needed']:
                continue
            lib_path = libtree['libs'][lib_soname]['path']
            if lib_path is None:
                print(f"Can't embed {lib_soname} as it could not be found")
                break
            if lib_path.startswith(torchlib_path):
                continue
            if new_lib_path is None:
                (new_lib_soname, new_lib_path) = copylib(lib_path, torchlib_path, patcher)
            patcher.replace_needed(filename, lib_soname, new_lib_soname)
            print(f'Replacing {lib_soname} with {new_lib_soname} for {filename}')
        if update_tag:
            for filename in ctx.iter_files():
                if os.path.basename(filename) != 'WHEEL':
                    continue
                replace_tag(filename)
    shutil.move(tmp_whl_name, whl_path)

def _root_pre_forward(self, module: nn.Module, args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[tuple[Any, ...], dict[str, Any]]:
    self._lazy_init()
    if <MASK>:
        return (args, kwargs)
    if not compiled_autograd_enabled():
        logger.debug('FSDP::root_pre_forward')
    self._state_ctx.iter_forward_root = self
    with torch.profiler.record_function('FSDP::root_pre_forward'):
        if (event := self._state_ctx.post_optim_event) is not None:
            self._comm_ctx.all_gather_copy_in_stream.wait_event(event)
            self._comm_ctx.all_gather_stream.wait_event(event)
            self._state_ctx.post_optim_event = None
        else:
            current_stream = self._device_handle.current_stream()
            self._comm_ctx.all_gather_copy_in_stream.wait_stream(current_stream)
            self._comm_ctx.all_gather_stream.wait_stream(current_stream)
        if self._device.type in ['cuda', 'hpu', 'xpu', 'mtia', torch._C._get_privateuse1_backend_name()]:
            with torch.profiler.record_function('FSDP::inputs_to_device'):
                (args_tuple, kwargs_tuple) = _to_kwargs(args, kwargs, self._device, False)
            (args, kwargs) = (args_tuple[0], kwargs_tuple[0])
    return (args, kwargs)

def _multi_tensor_rprop(params: list[Tensor], grads: list[Tensor], prevs: list[Tensor], step_sizes: list[Tensor], state_steps: list[Tensor], *, step_size_min: float, step_size_max: float, etaminus: float, etaplus: float, maximize: bool, capturable: bool, differentiable: bool, has_complex: bool):
    if len(params) == 0:
        return
    if differentiable:
        raise AssertionError("_foreach ops don't support autograd")
    if <MASK>:
        capturable_supported_devices = _get_capturable_supported_devices()
        if not all((p.device.type == step.device.type and p.device.type in capturable_supported_devices for (p, step) in zip(params, state_steps))):
            raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, prevs, step_sizes, state_steps])
    for ((grouped_params_, grouped_grads_, grouped_prevs_, grouped_step_sizes_, grouped_state_steps_), _) in grouped_tensors.values():
        grouped_params = cast(list[Tensor], grouped_params_)
        grouped_grads = cast(list[Tensor], grouped_grads_)
        grouped_prevs = cast(list[Tensor], grouped_prevs_)
        grouped_step_sizes = cast(list[Tensor], grouped_step_sizes_)
        grouped_state_steps = cast(list[Tensor], grouped_state_steps_)
        if not torch.compiler.is_compiling() and grouped_state_steps[0].is_cpu:
            torch._foreach_add_(grouped_state_steps, torch.tensor(1.0, device='cpu'), alpha=1.0)
        else:
            torch._foreach_add_(grouped_state_steps, 1)
        if has_complex:
            _view_as_real(grouped_params, grouped_grads, grouped_prevs, grouped_step_sizes)
        signs = torch._foreach_mul(grouped_grads, grouped_prevs)
        if maximize:
            torch._foreach_neg_(signs)
        torch._foreach_copy_(grouped_prevs, grouped_grads)
        if maximize:
            torch._foreach_neg_(grouped_prevs)
        grouped_grads = grouped_prevs
        torch._foreach_sign_(signs)
        if capturable:
            for sign in signs:
                sign.copy_(torch.where(sign.gt(0), etaplus, sign))
                sign.copy_(torch.where(sign.lt(0), etaminus, sign))
                sign.copy_(torch.where(sign.eq(0), 1, sign))
        else:
            for sign in signs:
                sign[sign.gt(0)] = etaplus
                sign[sign.lt(0)] = etaminus
                sign[sign.eq(0)] = 1
        torch._foreach_mul_(grouped_step_sizes, signs)
        for step_size in grouped_step_sizes:
            step_size.clamp_(step_size_min, step_size_max)
        grouped_grads = list(grouped_grads)
        for i in range(len(grouped_grads)):
            grouped_grads[i].copy_(torch.where(signs[i].eq(etaminus), 0, grouped_grads[i]))
        del signs
        grad_signs = [grad.sign() for grad in grouped_grads]
        torch._foreach_addcmul_(grouped_params, grad_signs, grouped_step_sizes, value=-1)

def __init__(self, subtype=None, closed: IntervalClosedType | None=None) -> None:
    from pandas.core.dtypes.common import is_string_dtype, pandas_dtype
    if closed is not None and closed not in {'right', 'left', 'both', 'neither'}:
        raise ValueError("closed must be one of 'right', 'left', 'both', 'neither'")
    if isinstance(subtype, IntervalDtype):
        if closed is not None and closed != subtype.closed:
            raise ValueError("dtype.closed and 'closed' do not match. Try IntervalDtype(dtype.subtype, closed) instead.")
        self._subtype = subtype._subtype
        self._closed = subtype._closed
    elif subtype is None:
        self._subtype = None
        self._closed = closed
    elif isinstance(subtype, str) and subtype.lower() == 'interval':
        self._subtype = None
        self._closed = closed
    else:
        if isinstance(subtype, str):
            m = IntervalDtype._match.search(subtype)
            if m is not None:
                gd = m.groupdict()
                subtype = gd['subtype']
                if <MASK>:
                    if closed is not None:
                        if closed != gd['closed']:
                            raise ValueError("'closed' keyword does not match value specified in dtype string")
                    closed = gd['closed']
        try:
            subtype = pandas_dtype(subtype)
        except TypeError as err:
            raise TypeError('could not construct IntervalDtype') from err
        if CategoricalDtype.is_dtype(subtype) or is_string_dtype(subtype):
            msg = 'category, object, and string subtypes are not supported for IntervalDtype'
            raise TypeError(msg)
        self._subtype = subtype
        self._closed = closed

@tf_export.tf_export('experimental.numpy.eye', v1=[])
@np_utils.np_doc('eye')
def eye(N, M=None, k=0, dtype=float):
    if dtype:
        dtype = np_utils.result_type(dtype)
    if not M:
        M = N
    N = int(N)
    M = int(M)
    k = int(k)
    if k >= M or -k >= N:
        return zeros([N, M], dtype=dtype)
    if k == 0:
        return linalg_ops.eye(N, M, dtype=dtype)
    diag_len = builtins.min(N, M)
    if k > 0:
        if N >= M:
            diag_len -= k
        elif <MASK>:
            diag_len = M - k
    elif k <= 0:
        if M >= N:
            diag_len += k
        elif M - k > N:
            diag_len = N + k
    diagonal_ = array_ops.ones([diag_len], dtype=dtype)
    return array_ops.matrix_diag(diagonal=diagonal_, num_rows=N, num_cols=M, k=k)

def _slice_input(t, i=i, inp=nt_inp):
    if isinstance(t, torch.Tensor) and _raggedness_matches(t, inp):
        return t[i]
    elif <MASK>:
        bdim = t._batch_dim
        if t.shape[bdim] == 1:
            return t[0]
        else:
            return t.select(bdim, i)
    else:
        return t

def get_format_timedelta64(values: TimedeltaArray, nat_rep: str | float='NaT', box: bool=False) -> Callable:
    """
    Return a formatter function for a range of timedeltas.
    These will all have the same format argument

    If box, then show the return in quotes
    """
    even_days = values._is_dates_only
    if even_days:
        format = None
    else:
        format = 'long'

    def _formatter(x):
        if x is None or (is_scalar(x) and isna(x)):
            return nat_rep
        if <MASK>:
            x = Timedelta(x)
        result = x._repr_base(format=format)
        if box:
            result = f"'{result}'"
        return result
    return _formatter

@staticmethod
def from_str(action):
    if action == 'F':
        return _ComputationType.FORWARD
    elif action == 'I':
        return _ComputationType.BACKWARD_INPUT
    elif action == 'W':
        return _ComputationType.BACKWARD_WEIGHT
    elif action == 'UNSHARD':
        return _ComputationType.UNSHARD
    elif action == 'RESHARD':
        return _ComputationType.RESHARD
    elif action == 'SEND_F':
        return _ComputationType.SEND_F
    elif action == 'RECV_F':
        return _ComputationType.RECV_F
    elif action == 'SEND_B':
        return _ComputationType.SEND_B
    elif action == 'RECV_B':
        return _ComputationType.RECV_B
    elif action == 'B':
        return _ComputationType.FULL_BACKWARD
    elif <MASK>:
        return _ComputationType.OVERLAP_F_B
    else:
        raise RuntimeError(f'Invalid computation type {action}')

def concatenate_managers(mgrs_indexers, axes: list[Index], concat_axis: AxisInt, copy: bool) -> BlockManager:
    """
    Concatenate block managers into one.

    Parameters
    ----------
    mgrs_indexers : list of (BlockManager, {axis: indexer,...}) tuples
    axes : list of Index
    concat_axis : int
    copy : bool

    Returns
    -------
    BlockManager
    """
    needs_copy = copy and concat_axis == 0
    if concat_axis == 0:
        mgrs = _maybe_reindex_columns_na_proxy(axes, mgrs_indexers, needs_copy)
        return mgrs[0].concat_horizontal(mgrs, axes)
    if len(mgrs_indexers) > 0 and mgrs_indexers[0][0].nblocks > 0:
        first_dtype = mgrs_indexers[0][0].blocks[0].dtype
        if first_dtype in [np.float64, np.float32]:
            if all((_is_homogeneous_mgr(mgr, first_dtype) for (mgr, _) in mgrs_indexers)) and len(mgrs_indexers) > 1:
                shape = tuple((len(x) for x in axes))
                nb = _concat_homogeneous_fastpath(mgrs_indexers, shape, first_dtype)
                return BlockManager((nb,), axes)
    mgrs = _maybe_reindex_columns_na_proxy(axes, mgrs_indexers, needs_copy)
    if len(mgrs) == 1:
        mgr = mgrs[0]
        out = mgr.copy(deep=False)
        out.axes = axes
        return out
    blocks = []
    values: ArrayLike
    for (placement, join_units) in _get_combined_plan(mgrs):
        unit = join_units[0]
        blk = unit.block
        if _is_uniform_join_units(join_units):
            vals = [ju.block.values for ju in join_units]
            if not blk.is_extension:
                values = np.concatenate(vals, axis=1)
            elif is_1d_only_ea_dtype(blk.dtype):
                values = concat_compat(vals, axis=0, ea_compat_axis=True)
                values = ensure_block_shape(values, ndim=2)
            else:
                values = concat_compat(vals, axis=1)
            values = ensure_wrapped_if_datetimelike(values)
            fastpath = blk.values.dtype == values.dtype
        else:
            values = _concatenate_join_units(join_units, copy=copy)
            fastpath = False
        if <MASK>:
            b = blk.make_block_same_class(values, placement=placement)
        else:
            b = new_block_2d(values, placement=placement)
        blocks.append(b)
    return BlockManager(tuple(blocks), axes)

def _getattr_qual(obj, name, default=_NOTHING):
    try:
        for path in name.split('.'):
            obj = getattr(obj, path)
        return obj
    except AttributeError:
        if <MASK>:
            return default
        else:
            raise

def _process_dynamic_shapes(combined_args: dict[str, Any], dynamic_shapes: Union[dict[str, Any], tuple[Any], list[Any], None]) -> list[Constraint]:
    """
    Reads the dynamic_shapes specification and produces a list of constraints.
    """
    from torch._dynamo.exc import UserError, UserErrorType
    if dynamic_shapes is None or len(dynamic_shapes) == 0:
        return []
    if isinstance(dynamic_shapes, (tuple, list)):
        combined_args = type(dynamic_shapes)(combined_args.values())
    symbols: dict[str, list[Constraint]] = defaultdict(list)
    phantom_roots: dict[str, _PhantomRoot] = {}
    derived_constraints_with_phantom_root: list[_DerivedConstraint] = []
    constraints: list[Constraint] = []

    def to_constraint(dim, tensor, i):
        import sympy
        from torch.fx.experimental.symbolic_shapes import StrictMinMaxConstraint
        from torch.utils._sympy.solve import try_solve
        from torch.utils._sympy.value_ranges import ValueRanges

        def root_value():
            symbol = sympy.Symbol(dim.root.__name__, integer=True)
            expr = dim.fn(symbol)
            solution = try_solve(sympy.Eq(expr, tensor.shape[i]), symbol)
            if solution is not None:
                return int(solution[1])
            else:
                raise UserError(UserErrorType.CONSTRAINT_VIOLATION, f'Expected shape[{i}] = {tensor.shape[i]} of input Tensor to be of the form {expr}, where {symbol} is an integer')
        if isinstance(dim, _DerivedDim):
            dim_root = dim.root
            if <MASK>:
                root_constraint = symbols[dim_root.__name__][0]
                root = _ConstraintTarget(root_constraint.t_id, root_constraint.dim)
            elif dim_root.__name__ not in phantom_roots:
                root = _PhantomRoot(name=dim_root.__name__, constraint_range=StrictMinMaxConstraint(vr=ValueRanges(lower=dim_root.min, upper=dim_root.max), warn_only=False), val=root_value())
                phantom_roots[dim_root.__name__] = root
            else:
                root = phantom_roots[dim_root.__name__]
            constraint = _DerivedConstraint(id(tensor), i, dim.__name__, StrictMinMaxConstraint(vr=ValueRanges(lower=dim.min, upper=dim.max), warn_only=False), root, dim.fn)
            if isinstance(root, _PhantomRoot):
                derived_constraints_with_phantom_root.append(constraint)
        elif isinstance(dim, _StaticDim):
            constraint = _Constraint(id(tensor), i, dim.__name__, StrictMinMaxConstraint(vr=ValueRanges(lower=dim.value, upper=dim.value), warn_only=False))
        else:
            assert isinstance(dim, Dim)
            constraint = _Constraint(id(tensor), i, dim.__name__, StrictMinMaxConstraint(vr=ValueRanges(lower=dim.min, upper=dim.max), warn_only=False))
        return constraint

    def _parse_tensor_dim(tensor, idx, dim) -> None:

        def _create_static_dim(tensor, i, value):
            return _StaticDim(value)
        if isinstance(dim, (int, Dim)):
            if isinstance(dim, int):
                dim = _create_static_dim(tensor, idx, dim)
            constraint = to_constraint(dim, tensor, idx)
            symbols[dim.__name__].append(constraint)
        elif isinstance(dim, _DimHint):
            if dim.type == _DimHintType.AUTO:
                torch._dynamo.maybe_mark_dynamic(tensor, idx)
            elif dim.type == _DimHintType.STATIC:
                torch._dynamo.mark_static(tensor, idx)
            elif dim.type == _DimHintType.DYNAMIC:
                torch._dynamo.mark_dynamic(tensor, idx)
            constraints.append(_RelaxedConstraint(id(tensor), idx))
        elif dim is None:
            torch._dynamo.mark_static(tensor, idx)

    def update_symbols(path, tensor, shape):
        tensor._dynamo_weak_dynamic_indices = set()
        tensor._dynamo_dynamic_indices = set()
        tensor._dynamo_dynamic_range = set()
        tensor._dynamo_static_indices = set()
        tensor._dynamo_unbacked_indices = set()
        if isinstance(shape, dict):
            for (i, dim) in shape.items():
                _parse_tensor_dim(tensor, i, dim)
        elif isinstance(shape, (tuple, list)):
            for (i, dim) in enumerate(shape):
                _parse_tensor_dim(tensor, i, dim)
        elif shape is None:
            for i in range(tensor.dim()):
                _parse_tensor_dim(tensor, i, None)

    def assoc_shape(path, t, dynamic_shape):
        if isinstance(t, torch.Tensor):
            update_symbols(path, t, dynamic_shape)
        elif isinstance(t, _IntWrapper):
            t.dynamism = dynamic_shape
    _tree_map_with_path(assoc_shape, combined_args, dynamic_shapes, tree_name='inputs')
    for derived_constraint_with_phantom_root in derived_constraints_with_phantom_root:
        phantom_root_name = derived_constraint_with_phantom_root.root.name
        if phantom_root_name in symbols:
            derived_constraint_with_phantom_root.root = symbols[phantom_root_name][0]
    for dynamic_dims in symbols.values():
        constraints.extend(dynamic_dims)
    return constraints

def _check_solver(solver, penalty, dual):
    if <MASK>:
        raise ValueError(f"Solver {solver} supports only 'l2' or None penalties, got {penalty} penalty.")
    if solver != 'liblinear' and dual:
        raise ValueError(f'Solver {solver} supports only dual=False, got dual={dual}')
    if penalty == 'elasticnet' and solver != 'saga':
        raise ValueError(f"Only 'saga' solver supports elasticnet penalty, got solver={solver}.")
    if solver == 'liblinear' and penalty is None:
        raise ValueError('penalty=None is not supported for the liblinear solver')
    return solver

@register_decomposition(aten.fft_ihfftn)
@out_wrapper()
def ihfftn(input: TensorLikeType, s: Optional[ShapeType]=None, dim: Optional[DimsType]=None, norm: NormType=None) -> TensorLikeType:
    torch._check(not input.dtype.is_complex, lambda : f'ihfftn expects a real-valued input tensor, but got {input.dtype}')
    (shape, dim) = _canonicalize_fft_shape_and_dim_args(input, s, dim)
    torch._check(len(shape) > 0, lambda : 'ihfftn must transform at least one axis')
    input = _maybe_promote_tensor_fft(input, require_complex=False)
    input = _resize_fft_input(input, dim, shape)
    tmp = prims.fft_r2c(input, dim=dim[-1:], onesided=True)
    if <MASK>:
        tmp = _apply_norm(tmp, norm=norm, signal_numel=shape[0], forward=False)
        return prims.conj(tmp)
    tmp = prims.conj_physical(tmp)
    tmp = prims.fft_c2c(tmp, dim=dim[:-1], forward=False)
    return _apply_norm(tmp, norm=norm, signal_numel=_prod(shape), forward=False)

def check_memory_pool(device: int, pool_id: tuple[int, int], live_storages_ptrs: list[StorageWeakRefWrapper]) -> None:
    assert all((isinstance(elem, StorageWeakRefWrapper) for elem in live_storages_ptrs))
    unique_storages = {stor.data_ptr() for stor in live_storages_ptrs if stor()}
    if <MASK>:
        return
    gc.collect()
    torch.cuda.synchronize()
    segments = get_cudagraph_segments(pool_id)
    allocated_not_in_live_storages = {}
    for segment in segments:
        addr = segment['address']
        for block in segment['blocks']:
            if block['state'] == 'active_allocated':
                if addr not in unique_storages:
                    allocated_not_in_live_storages[addr] = block
                else:
                    unique_storages.remove(addr)
            addr += block['size']
    torch._check(len(unique_storages) == 0, lambda : f'These storage data ptrs are not allocated in pool {pool_id} but should be {unique_storages}')
    if len(allocated_not_in_live_storages) != 0:
        formatted = []
        for (dp, block) in allocated_not_in_live_storages.items():
            trace = format_tb(block.get('frames', []))
            formatted.append(f'Data Pointer: {dp}, history: \n{trace}')
        formatted_s = '\n'.join(formatted)
        msg = f'These live storage data ptrs are in the cudagraph pool but not accounted for as an output of cudagraph trees: \n\n{formatted_s}'
        raise RuntimeError(msg)

def test_no_copy_new_vs_old(self):

    def old_np_asarray(values, dtype=None, order=None, copy=None):
        if <MASK>:
            if dtype is not None and np.issubdtype(dtype, np.number):
                return np.asarray(values, order=order, copy=copy).astype(dtype)
            else:
                return np.asarray(values, dtype=dtype, order=order, copy=copy)
        else:
            return np.asarray(values, dtype=dtype, order=order)
    x = np.array([1, 2, 3], dtype=np.float32)
    y_old = old_np_asarray(x, dtype=np.float32, copy=None)
    if np.lib.NumpyVersion(np.__version__) >= '2.0.0.dev0':
        self.assertIsNot(y_old, x, msg='Old code did NOT copy, but we expect it to always copy.')
    y_new = numpy_compat.np_asarray(x, dtype=np.float32, copy=None)
    self.assertIs(y_new, x, msg='New code did copy, but we expect it NOT to copy since copy=None.')

def backward_one_chunk(self, bwd_chunk_id: int, loss=None, full_backward: bool=True, last_backward=False):
    """
        Perform backward pass on the module.
        This should only be called once per microbatch.

        If full_backward is True (the default), the full backward pass including weight and input gradients will be run,
        and it is an error to call `backward_weight_one_chunk` for this bwd_chunk_id.

        If full_backward is False, it is optional that `dw_runner` was provided to the PipelineStage at __init__ time,
        and a subsequent call to `backward_weight_one_chunk` is required to invoke dw_runner and complete the backward.

        last_backward is controlled by the schedule and signals synchronization of gradients across DP groups
        after the last backward.
        """
    if not self.has_backward:
        return
    self._check_chunk_id(bwd_chunk_id)
    (stage_output, input_values) = self.fwd_cache.pop(bwd_chunk_id)
    if self.is_last:
        bwd_kwargs = {'stage_output': loss, 'output_grads': None, 'input_values': input_values}
    else:
        grads_output = self._retrieve_recv_grads(bwd_chunk_id)
        bwd_kwargs = {'stage_output': stage_output, 'output_grads': grads_output, 'input_values': input_values}
    grads_input: tuple[Optional[torch.Tensor], ...] = ()
    if self.dw_builder:
        (grads_input, _) = self.backward_maybe_with_nosync('full', bwd_kwargs, last_backward=last_backward)
        if <MASK>:
            self.dw_builder()()
        else:
            self.dw_runner[bwd_chunk_id] = self.dw_builder()
    elif full_backward:
        (grads_input, _) = self.backward_maybe_with_nosync('full', bwd_kwargs, last_backward=last_backward)
    else:
        param_groups: list[dict[str, Any]] | None = None
        if not self.is_first:
            if isinstance(bwd_kwargs['stage_output'], torch.Tensor):
                bwd_kwargs['stage_output'] = (bwd_kwargs['stage_output'],)
            (grads_input, param_groups) = self.backward_maybe_with_nosync('input', bwd_kwargs, last_backward=last_backward)
        self.backward_state[bwd_chunk_id] = (bwd_kwargs['input_values'], param_groups, bwd_kwargs['stage_output'], bwd_kwargs['output_grads'])
        self.dw_runner[bwd_chunk_id] = lambda : None
    self.bwd_cache[bwd_chunk_id] = grads_input
    if self.is_last and (not self.is_first):
        for t in stage_output:
            if not t._is_view():
                t.detach_()
    logger.debug('%s Backwarded chunk %s', self.log_prefix, bwd_chunk_id)

def _difference(self, other, sort=None):
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    (other, result_name) = self._convert_can_do_setop(other)
    if not isinstance(other, RangeIndex):
        return super()._difference(other, sort=sort)
    if sort is not False and self.step < 0:
        return self[::-1]._difference(other)
    res_name = ops.get_op_result_name(self, other)
    first = self._range[::-1] if self.step < 0 else self._range
    overlap = self.intersection(other)
    if overlap.step < 0:
        overlap = overlap[::-1]
    if len(overlap) == 0:
        return self.rename(name=res_name)
    if len(overlap) == len(self):
        return self[:0].rename(res_name)
    if len(overlap) == 1:
        if overlap[0] == self[0]:
            return self[1:]
        elif overlap[0] == self[-1]:
            return self[:-1]
        elif len(self) == 3 and overlap[0] == self[1]:
            return self[::2]
        else:
            return super()._difference(other, sort=sort)
    elif len(overlap) == 2 and overlap[0] == first[0] and (overlap[-1] == first[-1]):
        return self[1:-1]
    if overlap.step == first.step:
        if overlap[0] == first.start:
            new_rng = range(overlap[-1] + first.step, first.stop, first.step)
        elif <MASK>:
            new_rng = range(first.start, overlap[0], first.step)
        elif overlap._range == first[1:-1]:
            step = len(first) - 1
            new_rng = first[::step]
        else:
            return super()._difference(other, sort=sort)
    else:
        assert len(self) > 1
        if overlap.step == first.step * 2:
            if overlap[0] == first[0] and overlap[-1] in (first[-1], first[-2]):
                new_rng = first[1::2]
            elif overlap[0] == first[1] and overlap[-1] in (first[-1], first[-2]):
                new_rng = first[::2]
            else:
                return super()._difference(other, sort=sort)
        else:
            return super()._difference(other, sort=sort)
    if first is not self._range:
        new_rng = new_rng[::-1]
    new_index = type(self)._simple_new(new_rng, name=res_name)
    return new_index

def increment(self, metric: str, value: int, extra: Optional[dict[str, Any]]=None) -> None:
    """
        Increment a metric by a given amount.
        """
    if <MASK>:
        self._start_time_ns = time.time_ns()
    if metric not in self._metrics:
        self._metrics[metric] = 0
    self._metrics[metric] += value
    if extra:
        for (k, v) in extra.items():
            if k not in self._metrics and v is not None:
                self._metrics[k] = v

def on_read_assign_add_cross_replica(var, value, read_value=True):
    with distribute_lib.enter_or_assert_strategy(var.distribute_strategy):
        if distribute_lib.in_cross_replica_context():
            if <MASK>:
                raise ValueError('SyncOnReadVariable does not support `assign_add` in cross-replica context when aggregation is set to `tf.VariableAggregation.SUM`.')
            return assign_on_each_device(var, assign_add_on_device, value, read_value)

@staticmethod
def _select_best_index(refit, refit_metric, results):
    """Select index of the best combination of hyperparemeters."""
    if callable(refit):
        best_index = refit(results)
        if not isinstance(best_index, numbers.Integral):
            raise TypeError('best_index_ returned is not an integer')
        if <MASK>:
            raise IndexError('best_index_ index out of range')
    else:
        best_index = results[f'rank_test_{refit_metric}'].argmin()
    return best_index

def parse_signature(sig_text, name, pos):
    tokens = tokenize.generate_tokens(StringIO(sig_text).readline)
    sig_args = []
    var_arg = None
    var_kw = None
    defaults = {}

    def get_token(pos=False):
        try:
            (tok_type, tok_string, (srow, scol), (erow, ecol), line) = next(tokens)
        except StopIteration:
            return (tokenize.ENDMARKER, '')
        if pos:
            return (tok_type, tok_string, (srow, scol), (erow, ecol))
        else:
            return (tok_type, tok_string)
    while 1:
        var_arg_type = None
        (tok_type, tok_string) = get_token()
        if tok_type == tokenize.ENDMARKER:
            break
        if tok_type == tokenize.OP and tok_string in {'*', '**'}:
            var_arg_type = tok_string
            (tok_type, tok_string) = get_token()
        if tok_type != tokenize.NAME:
            raise TemplateError('Invalid signature: (%s)' % sig_text, position=pos, name=name)
        var_name = tok_string
        (tok_type, tok_string) = get_token()
        if tok_type == tokenize.ENDMARKER or (tok_type == tokenize.OP and tok_string == ','):
            if var_arg_type == '*':
                var_arg = var_name
            elif var_arg_type == '**':
                var_kw = var_name
            else:
                sig_args.append(var_name)
            if tok_type == tokenize.ENDMARKER:
                break
            continue
        if var_arg_type is not None:
            raise TemplateError('Invalid signature: (%s)' % sig_text, position=pos, name=name)
        if tok_type == tokenize.OP and tok_string == '=':
            nest_type = None
            unnest_type = None
            nest_count = 0
            start_pos = end_pos = None
            parts = []
            while 1:
                (tok_type, tok_string, s, e) = get_token(True)
                if start_pos is None:
                    start_pos = s
                end_pos = e
                if <MASK>:
                    raise TemplateError('Invalid signature: (%s)' % sig_text, position=pos, name=name)
                if not nest_count and (tok_type == tokenize.ENDMARKER or (tok_type == tokenize.OP and tok_string == ',')):
                    default_expr = isolate_expression(sig_text, start_pos, end_pos)
                    defaults[var_name] = default_expr
                    sig_args.append(var_name)
                    break
                parts.append((tok_type, tok_string))
                if nest_count and tok_type == tokenize.OP and (tok_string == nest_type):
                    nest_count += 1
                elif nest_count and tok_type == tokenize.OP and (tok_string == unnest_type):
                    nest_count -= 1
                    if not nest_count:
                        nest_type = unnest_type = None
                elif not nest_count and tok_type == tokenize.OP and (tok_string in ('(', '[', '{')):
                    nest_type = tok_string
                    nest_count = 1
                    unnest_type = {'(': ')', '[': ']', '{': '}'}[nest_type]
    return (sig_args, var_arg, var_kw, defaults)

def _get_feature_importances(estimator, getter, transform_func=None, norm_order=1):
    """
    Retrieve and aggregate (ndim > 1)  the feature importances
    from an estimator. Also optionally applies transformation.

    Parameters
    ----------
    estimator : estimator
        A scikit-learn estimator from which we want to get the feature
        importances.

    getter : "auto", str or callable
        An attribute or a callable to get the feature importance. If `"auto"`,
        `estimator` is expected to expose `coef_` or `feature_importances`.

    transform_func : {"norm", "square"}, default=None
        The transform to apply to the feature importances. By default (`None`)
        no transformation is applied.

    norm_order : int, default=1
        The norm order to apply when `transform_func="norm"`. Only applied
        when `importances.ndim > 1`.

    Returns
    -------
    importances : ndarray of shape (n_features,)
        The features importances, optionally transformed.
    """
    if isinstance(getter, str):
        if getter == 'auto':
            if hasattr(estimator, 'coef_'):
                getter = attrgetter('coef_')
            elif hasattr(estimator, 'feature_importances_'):
                getter = attrgetter('feature_importances_')
            else:
                raise ValueError(f"when `importance_getter=='auto'`, the underlying estimator {estimator.__class__.__name__} should have `coef_` or `feature_importances_` attribute. Either pass a fitted estimator to feature selector or call fit before calling transform.")
        else:
            getter = attrgetter(getter)
    elif not callable(getter):
        raise ValueError('`importance_getter` has to be a string or `callable`')
    importances = getter(estimator)
    if transform_func is None:
        return importances
    elif transform_func == 'norm':
        if importances.ndim == 1:
            importances = np.abs(importances)
        else:
            importances = np.linalg.norm(importances, axis=0, ord=norm_order)
    elif <MASK>:
        if importances.ndim == 1:
            importances = safe_sqr(importances)
        else:
            importances = safe_sqr(importances).sum(axis=0)
    else:
        raise ValueError("Valid values for `transform_func` are None, 'norm' and 'square'. Those two transformation are only supported now")
    return importances

def assertDatasetProducesWithShuffle(self, dataset, expected, batch, num_examples, shuffle):
    if <MASK>:
        actual = []
        next_fn = self.getNext(dataset)
        for _ in range(num_examples):
            elem = self.evaluate(next_fn())
            if isinstance(elem, tuple):
                actual.extend(elem)
            else:
                actual.extend(elem.tolist())
        self.assertCountEqual(actual, expected)
        with self.assertRaises(errors.OutOfRangeError):
            self.evaluate(next_fn())
    else:
        self.assertDatasetProduces(dataset, list(chunk(expected, batch)))

def _get_depend_dict(name, vars, deps):
    if name in vars:
        words = vars[name].get('depend', [])
        if <MASK>:
            for word in word_pattern.findall(vars[name]['=']):
                if word not in words and word in vars and (word != name):
                    words.append(word)
        for word in words[:]:
            for w in deps.get(word, []) or _get_depend_dict(word, vars, deps):
                if w not in words:
                    words.append(w)
    else:
        outmess(f'_get_depend_dict: no dependence info for {repr(name)}\n')
        words = []
    deps[name] = words
    return words

def _laplacian_sparse(graph, normed, axis, copy, form, dtype, symmetrized):
    del form
    if <MASK>:
        dtype = graph.dtype
    needs_copy = False
    if graph.format in ('lil', 'dok'):
        m = graph.tocoo()
    else:
        m = graph
        if copy:
            needs_copy = True
    if symmetrized:
        m += m.T.conj()
    w = np.asarray(m.sum(axis=axis)).ravel() - m.diagonal()
    if normed:
        m = m.tocoo(copy=needs_copy)
        isolated_node_mask = w == 0
        w = np.where(isolated_node_mask, 1, np.sqrt(w))
        m.data /= w[m.row]
        m.data /= w[m.col]
        m.data *= -1
        m.setdiag(1 - isolated_node_mask)
    else:
        if m.format == 'dia':
            m = m.copy()
        else:
            m = m.tocoo(copy=needs_copy)
        m.data *= -1
        m.setdiag(w)
    return (m.astype(dtype, copy=False), w.astype(dtype))

def default_convert(data):
    """
    Convert each NumPy array element into a :class:`torch.Tensor`.

    If the input is a `Sequence`, `Collection`, or `Mapping`, it tries to convert each element inside to a :class:`torch.Tensor`.
    If the input is not an NumPy array, it is left unchanged.
    This is used as the default function for collation when both `batch_sampler` and `batch_size`
    are NOT defined in :class:`~torch.utils.data.DataLoader`.

    The general input type to output type mapping is similar to that
    of :func:`~torch.utils.data.default_collate`. See the description there for more details.

    Args:
        data: a single data point to be converted

    Examples:
        >>> # xdoctest: +SKIP
        >>> # Example with `int`
        >>> default_convert(0)
        0
        >>> # Example with NumPy array
        >>> default_convert(np.array([0, 1]))
        tensor([0, 1])
        >>> # Example with NamedTuple
        >>> Point = namedtuple("Point", ["x", "y"])
        >>> default_convert(Point(0, 0))
        Point(x=0, y=0)
        >>> default_convert(Point(np.array(0), np.array(0)))
        Point(x=tensor(0), y=tensor(0))
        >>> # Example with List
        >>> default_convert([np.array([0, 1]), np.array([2, 3])])
        [tensor([0, 1]), tensor([2, 3])]
    """
    elem_type = type(data)
    if isinstance(data, torch.Tensor):
        return data
    elif elem_type.__module__ == 'numpy' and elem_type.__name__ != 'str_' and (elem_type.__name__ != 'string_'):
        if elem_type.__name__ == 'ndarray' and np_str_obj_array_pattern.search(data.dtype.str) is not None:
            return data
        return torch.as_tensor(data)
    elif isinstance(data, collections.abc.Mapping):
        try:
            if <MASK>:
                clone = copy.copy(data)
                clone.update({key: default_convert(data[key]) for key in data})
                return clone
            else:
                return elem_type({key: default_convert(data[key]) for key in data})
        except TypeError:
            return {key: default_convert(data[key]) for key in data}
    elif isinstance(data, tuple) and hasattr(data, '_fields'):
        return elem_type(*(default_convert(d) for d in data))
    elif isinstance(data, tuple):
        return [default_convert(d) for d in data]
    elif isinstance(data, collections.abc.Sequence) and (not isinstance(data, (str, bytes))):
        try:
            if isinstance(data, collections.abc.MutableSequence):
                clone = copy.copy(data)
                for (i, d) in enumerate(data):
                    clone[i] = default_convert(d)
                return clone
            else:
                return elem_type([default_convert(d) for d in data])
        except TypeError:
            return [default_convert(d) for d in data]
    else:
        return data

