def shape_list(tensor):
    shape = tensor.shape.as_list()
    non_static_indexes = []
    for (index, dim) in enumerate(shape):
        if <MASK>:
            non_static_indexes.append(index)
    if not non_static_indexes:
        return shape
    dynamic_shape = array_ops.shape(input=tensor)
    for index in non_static_indexes:
        shape[index] = dynamic_shape[index]
    return shape

def _inherit_from_data(name: str, delegate: type, cache: bool=False, wrap: bool=False):
    """
    Make an alias for a method of the underlying ExtensionArray.

    Parameters
    ----------
    name : str
        Name of an attribute the class should inherit from its EA parent.
    delegate : class
    cache : bool, default False
        Whether to convert wrapped properties into cache_readonly
    wrap : bool, default False
        Whether to wrap the inherited result in an Index.

    Returns
    -------
    attribute, method, property, or cache_readonly
    """
    attr = getattr(delegate, name)
    if isinstance(attr, property) or type(attr).__name__ == 'getset_descriptor':
        if cache:

            def cached(self):
                return getattr(self._data, name)
            cached.__name__ = name
            cached.__doc__ = attr.__doc__
            method = cache_readonly(cached)
        else:

            def fget(self):
                result = getattr(self._data, name)
                if wrap:
                    if <MASK>:
                        return type(self)._simple_new(result, name=self.name)
                    elif isinstance(result, ABCDataFrame):
                        return result.set_index(self)
                    return Index(result, name=self.name, dtype=result.dtype)
                return result

            def fset(self, value) -> None:
                setattr(self._data, name, value)
            fget.__name__ = name
            fget.__doc__ = attr.__doc__
            method = property(fget, fset)
    elif not callable(attr):
        method = attr
    else:

        def method(self, *args, **kwargs):
            if 'inplace' in kwargs:
                raise ValueError(f'cannot use inplace with {type(self).__name__}')
            result = attr(self._data, *args, **kwargs)
            if wrap:
                if isinstance(result, type(self._data)):
                    return type(self)._simple_new(result, name=self.name)
                elif isinstance(result, ABCDataFrame):
                    return result.set_index(self)
                return Index(result, name=self.name, dtype=result.dtype)
            return result
        method.__name__ = name
        method.__doc__ = attr.__doc__
        method.__signature__ = signature(attr)
    return method

def call_apply(self, tx: 'InstructionTranslator', args, kwargs):
    requires_grad = False

    def visit(vt):
        nonlocal requires_grad
        if isinstance(vt, variables.TensorVariable):
            if vt.requires_grad is not False:
                requires_grad = True
        if isinstance(vt, variables.NNModuleVariable):
            if vt.is_training(tx):
                requires_grad = True
    VariableTracker.visit(visit, (args, kwargs))
    if requires_grad and torch.is_grad_enabled():
        if config.capture_autograd_function is False:
            warnings.warn("The config.capture_autograd_function flag is deprecated, it's now always true.")
        from torch._functorch.autograd_function import autograd_function_forward_rewritten
        from torch.autograd.function import _is_setup_context_defined
        forward_fn = self.fn_cls.forward
        is_setup_ctx_defined = _is_setup_context_defined(self.fn_cls.setup_context)
        if is_setup_ctx_defined:
            forward_fn = autograd_function_forward_rewritten(self.fn_cls.forward, self.fn_cls.setup_context)
        vjp_fn = self.fn_cls.vjp
        if vjp_fn is not torch.autograd.Function.vjp:
            unimplemented_v2(gb_type='Unsupported custom vjp', context=f'call_apply {self} {args} {kwargs}', explanation='Dynamo does not support tracing `torch.autograd.Function` subclasses that define a custom `vjp` method.', hints=['Remove the custom `vjp` method if possible.', 'Use standard `backward` instead if applicable.', *graph_break_hints.SUPPORTABLE])
        jvp_fn = self.fn_cls.jvp
        if <MASK>:
            unimplemented_v2(gb_type='Unsupported custom jvp', context=f'call_apply {self} {args} {kwargs}', explanation='Dynamo does not support tracing `torch.autograd.Function` subclasses that define a custom `jvp` method.', hints=['Remove the custom `jvp` method if possible.', *graph_break_hints.SUPPORTABLE])
        from .higher_order_ops import AutogradFunctionApplyVariable
        source = self.source
        if source is None:
            source = AttrSource(tx.import_source(self.fn_cls.__module__), self.fn_cls.__name__)
        val = AutogradFunctionApplyVariable(forward_fn, self.fn_cls.backward, source, source=AttrSource(source, member='apply')).call_function(tx, args, kwargs)
        if self.source:
            fwd_src = AttrSource(self.source, 'forward')
            install_guard(fwd_src.make_guard(GuardBuilder.FUNCTION_MATCH))
            if is_setup_ctx_defined:
                setup_ctx_src = AttrSource(self.source, 'setup_context')
                install_guard(setup_ctx_src.make_guard(GuardBuilder.FUNCTION_MATCH))
        return val
    if self.source:
        source = AttrSource(self.source, 'forward')
    else:
        source = None
    fn = self.fn_cls.forward
    ctx = AutogradFunctionContextVariable.create(tx, args, kwargs)
    args = [ctx, *args]
    if isinstance(fn, types.FunctionType):
        sig = inspect.signature(fn)
        if len(args) - 1 == len(sig._parameters):
            args = args[1:]
        return variables.UserFunctionVariable(fn, source=source).call_function(tx, args, kwargs)
    elif isinstance(fn, types.MethodType):
        return variables.UserMethodVariable(fn.__func__, variables.UserDefinedClassVariable(self.fn_cls), source=source).call_function(tx, args, kwargs)
    else:
        unimplemented_v2(gb_type='Non-function or method in subclass of torch.autograd.Function', context=f'call_apply {self} {args} {kwargs}', explanation=f'Dynamo requires the `forward` attribute of a `torch.autograd.Function` subclass to be a standard Python function or method. Found type `{type(fn).__name__}` instead.', hints=['Ensure the `forward` method is defined as a regular function or instance method.'])

def pin_memory(data, device=None):
    if isinstance(data, torch.Tensor):
        return data.pin_memory(device)
    elif <MASK>:
        return data
    elif isinstance(data, collections.abc.Mapping):
        try:
            if isinstance(data, collections.abc.MutableMapping):
                clone = copy.copy(data)
                clone.update({k: pin_memory(sample, device) for (k, sample) in data.items()})
                return clone
            else:
                return type(data)({k: pin_memory(sample, device) for (k, sample) in data.items()})
        except TypeError:
            return {k: pin_memory(sample, device) for (k, sample) in data.items()}
    elif isinstance(data, tuple) and hasattr(data, '_fields'):
        return type(data)(*(pin_memory(sample, device) for sample in data))
    elif isinstance(data, tuple):
        return [pin_memory(sample, device) for sample in data]
    elif isinstance(data, collections.abc.Sequence):
        try:
            if isinstance(data, collections.abc.MutableSequence):
                clone = copy.copy(data)
                for (i, item) in enumerate(data):
                    clone[i] = pin_memory(item, device)
                return clone
            return type(data)([pin_memory(sample, device) for sample in data])
        except TypeError:
            return [pin_memory(sample, device) for sample in data]
    elif hasattr(data, 'pin_memory'):
        return data.pin_memory()
    else:
        return data

def _add_observer_(module, qconfig_propagation_list=None, non_leaf_module_list=None, device=None, custom_module_class_mapping=None):
    """Add observer for the leaf child of the module.

    This function insert observer module to all leaf child module that
    has a valid qconfig attribute.

    Args:
        module: input module with qconfig attributes for all the leaf modules that we want to quantize
        qconfig_propagation_list: a list of quantizable modules that will have observers added to them
            if they are leaf nodes
        device: parent device, if any
        non_leaf_module_list: list of non-leaf modules we want to add observer

    Return:
        None, module is modified inplace with added observer modules and forward_hooks
    """
    if qconfig_propagation_list is None:
        qconfig_propagation_list = get_default_qconfig_propagation_list()
    if custom_module_class_mapping is None:
        custom_module_class_mapping = {}
    if device is None:
        devices = _get_unique_devices_(module)
        assert len(devices) <= 1, f'_add_observer_ only works with cpu or single-device CUDA modules, but got devices {devices}'
        device = next(iter(devices)) if len(devices) > 0 else None

    def get_activation_post_process(qconfig, device, special_act_post_process=None):
        activation = qconfig.activation() if special_act_post_process is None else special_act_post_process()
        if device is not None:
            activation.to(device)
        return activation

    def needs_observation(m):
        return hasattr(m, 'qconfig') and m.qconfig is not None

    def insert_activation_post_process(m, special_act_post_process=None):
        """Adds an activation post process module and register
        a pre or post hook that calls the module
        """
        if needs_observation(m) and (not isinstance(m, DeQuantStub)):
            m.add_module('activation_post_process', get_activation_post_process(m.qconfig, device, special_act_post_process))
            _register_activation_post_process_hook(m, pre_hook=_activation_is_memoryless(m.qconfig))
    for (name, child) in module.named_children():
        if type_before_parametrizations(child) is nn.Dropout:
            continue
        elif issubclass(type_before_parametrizations(child), (nnq.FloatFunctional, nnq.QFunctional)):
            if <MASK>:
                assert hasattr(child, 'activation_post_process'), f'functional class {type_before_parametrizations(child)} has no pre-defined `activation_post_process`'
                child.activation_post_process = get_activation_post_process(child.qconfig, device)
        elif isinstance(child, _FusedModule):
            if needs_observation(child):
                insert_activation_post_process(child)
        elif non_leaf_module_list is not None and type_before_parametrizations(child) in non_leaf_module_list:
            if needs_observation(child):
                insert_activation_post_process(child)
        elif _has_special_act_post_process(child):
            special_act_post_process = _get_special_act_post_process(child)
            insert_activation_post_process(child, special_act_post_process)
        elif needs_observation(child) and type_before_parametrizations(child) in custom_module_class_mapping:
            observed_class = custom_module_class_mapping[type_before_parametrizations(child)]
            observed_child = observed_class.from_float(child)
            setattr(module, name, observed_child)
            if not issubclass(observed_class, tuple(no_observer_set())):
                insert_activation_post_process(observed_child)
        else:
            _add_observer_(child, qconfig_propagation_list, non_leaf_module_list, device, custom_module_class_mapping)
    if has_no_children_ignoring_parametrizations(module) and (not isinstance(module, torch.nn.Sequential)) and (type_before_parametrizations(module) in qconfig_propagation_list):
        insert_activation_post_process(module)
    if hasattr(module, 'weight_fake_quant') and (not isinstance(module, torch.nn.Sequential)) and (type_before_parametrizations(module) in qconfig_propagation_list):
        insert_activation_post_process(module)

def _is_valid_regression_signature(signature_def):
    """Determine whether the argument is a servable 'regress' SignatureDef."""
    if signature_def.method_name != signature_constants.REGRESS_METHOD_NAME:
        return False
    if set(signature_def.inputs.keys()) != set([signature_constants.REGRESS_INPUTS]):
        return False
    if signature_def.inputs[signature_constants.REGRESS_INPUTS].dtype != types_pb2.DT_STRING:
        return False
    if set(signature_def.outputs.keys()) != set([signature_constants.REGRESS_OUTPUTS]):
        return False
    if <MASK>:
        return False
    return True

def _check_params_vs_input(self, X):
    super()._check_params_vs_input(X, default_n_init=3)
    self._batch_size = min(self.batch_size, X.shape[0])
    self._init_size = self.init_size
    if <MASK>:
        self._init_size = 3 * self._batch_size
        if self._init_size < self.n_clusters:
            self._init_size = 3 * self.n_clusters
    elif self._init_size < self.n_clusters:
        warnings.warn(f'init_size={self._init_size} should be larger than n_clusters={self.n_clusters}. Setting it to min(3*n_clusters, n_samples)', RuntimeWarning, stacklevel=2)
        self._init_size = 3 * self.n_clusters
    self._init_size = min(self._init_size, X.shape[0])
    if self.reassignment_ratio < 0:
        raise ValueError(f'reassignment_ratio should be >= 0, got {self.reassignment_ratio} instead.')

def strip_unused_from_files(input_graph, input_binary, output_graph, output_binary, input_node_names, output_node_names, placeholder_type_enum):
    """Removes unused nodes from a graph file."""
    if not gfile.Exists(input_graph):
        print("Input graph file '" + input_graph + "' does not exist!")
        return -1
    if not output_node_names:
        print('You need to supply the name of a node to --output_node_names.')
        return -1
    input_graph_def = graph_pb2.GraphDef()
    mode = 'rb' if input_binary else 'r'
    with gfile.GFile(input_graph, mode) as f:
        if <MASK>:
            input_graph_def.ParseFromString(f.read())
        else:
            text_format.Merge(f.read(), input_graph_def)
    output_graph_def = strip_unused(input_graph_def, input_node_names.split(','), output_node_names.split(','), placeholder_type_enum)
    if output_binary:
        with gfile.GFile(output_graph, 'wb') as f:
            f.write(output_graph_def.SerializeToString())
    else:
        with gfile.GFile(output_graph, 'w') as f:
            f.write(text_format.MessageToString(output_graph_def))
    print('%d ops in the final graph.' % len(output_graph_def.node))

@register_lowering(aten._int_mm, type_promotion_kind=None)
def tuned_int_mm(mat1, mat2, *, layout=None):
    (m, n, k, layout, mat1, mat2) = mm_args(mat1, mat2, layout=layout, out_dtype=torch.int32)
    name = 'int_mm'
    counters['aten_mm_info'][f'aten._int_mm_{m}_{n}_{k}'] += 1
    log.info('Tuned aten._int_mm: m=%s, n=%s, k=%s, mat1_dtype=%s, mat2_dtype=%s, output_layout=%s', m, n, k, mat1.get_dtype(), mat2.get_dtype(), layout)
    (static_shape, is_nonzero) = _is_static_problem(layout)
    use_cutlass = static_shape and is_nonzero and use_cutlass_template(layout, m, n, k)
    choices: list[ChoiceCaller] = []
    kernel_inputs = MMKernelInputs([mat1, mat2], out_dtype=torch.int32)
    templates_to_use: list[Union[ExternKernelChoice, KernelTemplate]] = []
    if use_aten_gemm_kernels():
        templates_to_use.append(aten__int_mm)
    if is_nonzero and use_triton_template(layout, enable_int32=True, check_max_autotune=False):
        templates_to_use.append(mm_template)
    choices.extend(V.choices.get_template_configs(kernel_inputs, templates_to_use, name))
    if <MASK>:
        CUTLASS3xGemmTemplate.add_cutlass_gemm_choices(choices, layout, kernel_inputs.nodes(), fuseable=True, non_fuseable=True)
    return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout)

@staticmethod
def num_splits(device: torch.device, dst_dtype: torch.dtype, src_dtype: torch.dtype, inner_fn: Callable[_P, OpsValue], ranges: Sequence[_IntLike], reduction_ranges: Sequence[_IntLike], reduction_type: Union[ReductionType, Literal['scan']], reduction_numel: Expr, input_node: Optional[IRNode]=None) -> tuple[ReductionHint, _IntLike]:
    reduction_numel_hint = V.graph.sizevars.symbolic_hint(reduction_numel)
    numel_hint = V.graph.sizevars.symbolic_hint(sympy_product(ranges))
    should_split = reduction_type == 'scan' or (not V.graph.has_feature(device, BackendFeature.REDUCE_TO_SINGLE_ELEMENT) and reduction_type not in ('argmax', 'argmin') and config.split_reductions)
    if not (_is_static(reduction_numel_hint) and _is_static(numel_hint)):
        return (ReductionHint.DEFAULT, 1)
    if reduction_type == 'dot':
        return (ReductionHint.DEFAULT, 1)
    props = DeviceProperties.create(device)
    num_sm = props.multi_processor_count
    min_elements_per_thread = 32
    if should_split:
        inner_reduction_splits: Callable[[int, int], int] = functools.partial(V.choices.reduction_split_factor, device, inner_reduction=True)
        outer_reduction_splits: Callable[[int, int], int] = functools.partial(V.choices.reduction_split_factor, device, inner_reduction=False)
    else:

        def inner_reduction_splits(reduction_numel_hint: int, numel_hint: int) -> int:
            return 1
        outer_reduction_splits = inner_reduction_splits
    if numel_hint == 1:
        split = inner_reduction_splits(reduction_numel_hint, numel_hint)
        if split == 1:
            return (ReductionHint.INNER, split)
        if input_node is not None and isinstance(input_node, TensorBox):
            with patch.object(FlexibleLayout, 'allow_indexing', True):
                (new_ranges, new_reduction_ranges) = extract_input_node_reduction_ranges(input_node)
            if new_ranges is not None and new_reduction_ranges is not None:
                extracted_numel_hint = V.graph.sizevars.symbolic_hint(sympy_product(new_ranges + new_reduction_ranges))
                if <MASK>:
                    log.debug("Use previous IRNode's range and reduction_ranges instead of split. current ranges: %s, current reduction ranges: %s, current split: %d, new ranges: %s, new reduction ranges: %s", ranges, reduction_ranges, split, new_ranges, new_reduction_ranges)
                    return (ReductionHint.INNER, -1)
        return (ReductionHint.INNER, split)
    if reduction_numel_hint <= min_elements_per_thread or numel_hint >= num_sm * 2 * 32:
        return (ReductionHint.DEFAULT, 1)
    r = Reduction(device=device, dtype=dst_dtype, inner_fn=inner_fn, ranges=ranges, reduction_ranges=reduction_ranges, reduction_type=reduction_type if reduction_type != 'scan' else 'sum', src_dtype=src_dtype, reduction_hint=ReductionHint.DEFAULT)

    def get_read_indices(r: Reduction) -> tuple[Sequence[Expr], bool]:
        device = r.get_device()
        assert device is not None
        cb = ComputedBuffer(name=None, layout=FlexibleLayout(device=device, dtype=r.get_dtype(), size=r.get_size()), data=r)
        read_writes = cb.get_read_writes()
        assert read_writes.range_vars is not None
        range_vars = [r for r in read_writes.range_vars if isinstance(r, Expr) and (not isinstance(r, sympy.Number))]
        indices = []
        changed = False
        for md in sorted(read_writes.reads, key=lambda x: x.name):
            if all((r in md.index.free_symbols for r in range_vars)):
                indices.append(md.index)
                if md.name in V.graph.name_to_buffer:
                    buf = V.graph.name_to_buffer[md.name]
                    original_stride = getattr(buf.layout, 'stride', None)
                    buf.decide_layout()
                    if getattr(buf.layout, 'stride', None) != original_stride:
                        changed = True
        return (indices, changed)
    (indices, changed) = get_read_indices(r)
    if changed:
        (indices, _) = get_read_indices(r)
    if len(indices) == 0:
        return (ReductionHint.DEFAULT, 1)
    ((_, reduction_vars), ranges1) = dependencies.index_vars_squeeze(r.get_size(), r.get_reduction_size())
    num_outer = 0
    num_inner = 0
    for i in indices:
        j = V.graph.sizevars.simplify_with_ranges(i, ranges1)
        strides = V.graph.sizevars.stride_hints(j, reduction_vars, list(ranges1.keys()))
        outer = all((s > 1 for s in strides))
        if outer:
            num_outer += 1
        else:
            num_inner += 1
    if num_inner > num_outer:
        return (ReductionHint.INNER, inner_reduction_splits(reduction_numel_hint, numel_hint))
    else:
        return (ReductionHint.OUTER, outer_reduction_splits(reduction_numel_hint, numel_hint))

def database_forwards(self, app_label, schema_editor, from_state, to_state):
    if schema_editor.connection.vendor != 'postgresql' or not router.allow_migrate(schema_editor.connection.alias, app_label, **self.hints):
        return
    if not self.extension_exists(schema_editor, self.name):
        schema_editor.execute('CREATE EXTENSION IF NOT EXISTS %s' % schema_editor.quote_name(self.name))
    get_hstore_oids.cache_clear()
    get_citext_oids.cache_clear()
    register_type_handlers(schema_editor.connection)
    if <MASK>:
        schema_editor.connection.register_geometry_adapters(schema_editor.connection.connection, True)

def convert_inner_node_data(nested, wrap=False):
    """Either wraps or unwraps innermost node data lists in `ListWrapper` objects.

  Args:
    nested: A nested data structure.
    wrap: If `True`, wrap innermost lists in `ListWrapper` objects. If `False`,
      unwraps `ListWrapper` objects into lists.

  Returns:
    Structure of same type as nested, with lists wrapped/unwrapped.
  """

    def _is_serialized_node_data(nested):
        if isinstance(nested, list) and len(nested) in [3, 4] and isinstance(nested[0], str):
            return True
        return False

    def _is_atomic_nested(nested):
        """Returns `True` if `nested` is a list representing node data."""
        if isinstance(nested, ListWrapper):
            return True
        if <MASK>:
            return True
        return not nest.is_nested(nested)

    def _convert_object_or_list(nested):
        """Convert b/t `ListWrapper` object and list representations."""
        if wrap:
            if isinstance(nested, ListWrapper):
                return nested
            if _is_serialized_node_data(nested):
                return ListWrapper(nested)
            return nested
        else:
            if isinstance(nested, ListWrapper):
                return nested.as_list()
            return nested
    return map_structure_with_atomic(_is_atomic_nested, _convert_object_or_list, nested)

def _find_reference_cycle(objects: Sequence[Any], idx: int) -> bool:

    def get_ignore_reason(obj: Any, denylist: Collection[Any]) -> Optional[str]:
        """Tests whether an object should be omitted from the dependency graph."""
        if len(denylist) > 100:
            return '<depth limit>'
        if tf_inspect.isframe(obj):
            if 'test_util.py' in tf_inspect.getframeinfo(obj)[0]:
                return '<test code>'
        for b in denylist:
            if <MASK>:
                return '<test code>'
        if obj is denylist:
            return '<test code>'
        return None

    def describe(obj: Any, denylist: Collection[Any], leaves_only: bool=False) -> str:
        """Returns a custom human-readable summary of obj.

    Args:
      obj: the value to describe.
      denylist: same as denylist in get_ignore_reason.
      leaves_only: boolean flag used when calling describe recursively. Useful
        for summarizing collections.
    """
        if get_ignore_reason(obj, denylist):
            return '{}{}'.format(get_ignore_reason(obj, denylist), type(obj))
        if tf_inspect.isframe(obj):
            return 'frame: {}'.format(tf_inspect.getframeinfo(obj))
        elif tf_inspect.ismodule(obj):
            return 'module: {}'.format(obj.__name__)
        elif leaves_only:
            return '{}, {}'.format(type(obj), id(obj))
        elif isinstance(obj, list):
            return 'list({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
        elif isinstance(obj, tuple):
            return 'tuple({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
        elif isinstance(obj, dict):
            return 'dict({}): {} keys'.format(id(obj), len(obj.keys()))
        elif tf_inspect.isfunction(obj):
            return 'function({}) {}; globals ID: {}'.format(id(obj), obj.__name__, id(obj.__globals__))
        else:
            return '{}, {}'.format(type(obj), id(obj))

    def build_ref_graph(obj: Any, graph: dict[int, list[int]], reprs: dict[int, str], denylist: tuple[Any, ...]) -> None:
        """Builds a reference graph as <referrer> -> <list of referents>.

    Args:
      obj: The object to start from. The graph will be built by recursively
        adding its referrers.
      graph: Dict holding the graph to be built. To avoid creating extra
        references, the graph holds object IDs rather than actual objects.
      reprs: Auxiliary structure that maps object IDs to their human-readable
        description.
      denylist: List of objects to ignore.
    """
        referrers = gc.get_referrers(obj)
        denylist = denylist + (referrers,)
        obj_id = id(obj)
        for r in referrers:
            if get_ignore_reason(r, denylist) is None:
                r_id = id(r)
                if r_id not in graph:
                    graph[r_id] = []
                if obj_id not in graph[r_id]:
                    graph[r_id].append(obj_id)
                    build_ref_graph(r, graph, reprs, denylist)
                    reprs[r_id] = describe(r, denylist)

    def find_cycle(el: int, graph: dict[int, list[int]], reprs: dict[int, str], path: tuple[int, ...]) -> Optional[bool]:
        """Finds and prints a single cycle in the dependency graph."""
        if el not in graph:
            return
        for r in graph[el]:
            if r in path:
                logging.error('Reference cycle sample:')
                for p in path + (r,):
                    logging.error(reprs.get(p, 'unknown object ' + str(p)))
                return True
            elif find_cycle(r, graph, reprs, path + (r,)):
                return True
        return False
    obj = objects[idx]
    graph: dict[int, list[int]] = {}
    reprs: dict[int, str] = {}
    build_ref_graph(obj, graph, reprs, (objects, graph, reprs, get_ignore_reason, describe, build_ref_graph, find_cycle))
    for k in graph:
        if find_cycle(k, graph, reprs, ()):
            return True
    return False

def _order_by_pairs(self):
    if self.query.extra_order_by:
        ordering = self.query.extra_order_by
    elif not self.query.default_ordering:
        ordering = self.query.order_by
    elif self.query.order_by:
        ordering = self.query.order_by
    elif (meta := self.query.get_meta()) and meta.ordering:
        ordering = meta.ordering
        self._meta_ordering = ordering
    else:
        ordering = []
    if <MASK>:
        (default_order, _) = ORDER_DIR['ASC']
    else:
        (default_order, _) = ORDER_DIR['DESC']
    selected_exprs = {}
    if ordering and (select := self.select):
        for (ordinal, (expr, _, alias)) in enumerate(select, start=1):
            pos_expr = PositionRef(ordinal, alias, expr)
            if alias:
                selected_exprs[alias] = pos_expr
            selected_exprs[expr] = pos_expr
    for field in ordering:
        if hasattr(field, 'resolve_expression'):
            if isinstance(field, Value):
                field = Cast(field, field.output_field)
            if not isinstance(field, OrderBy):
                field = field.asc()
            if not self.query.standard_ordering:
                field = field.copy()
                field.reverse_ordering()
            select_ref = selected_exprs.get(field.expression)
            if select_ref or (isinstance(field.expression, F) and (select_ref := selected_exprs.get(field.expression.name))):
                if field.nulls_first is None and field.nulls_last is None or self.connection.features.supports_order_by_nulls_modifier:
                    field = field.copy()
                    field.expression = select_ref
                elif self.query.combinator:
                    field = field.copy()
                    field.expression = Ref(select_ref.refs, select_ref.source)
            yield (field, select_ref is not None)
            continue
        if field == '?':
            yield (OrderBy(Random()), False)
            continue
        (col, order) = get_order_dir(field, default_order)
        descending = order == 'DESC'
        if (select_ref := selected_exprs.get(col)):
            yield (OrderBy(select_ref, descending=descending), True)
            continue
        if (expr := self.query.annotations.get(col)):
            ref = col
            transforms = []
        else:
            (ref, *transforms) = col.split(LOOKUP_SEP)
            expr = self.query.annotations.get(ref)
        if expr:
            if self.query.combinator and self.select:
                if transforms:
                    raise NotImplementedError('Ordering combined queries by transforms is not implemented.')
                expr = F(ref)
            if transforms:
                for name in transforms:
                    expr = self.query.try_transform(expr, name)
            if isinstance(expr, Value):
                expr = Cast(expr, expr.output_field)
            yield (OrderBy(expr, descending=descending), False)
            continue
        if '.' in field:
            (table, col) = col.split('.', 1)
            yield (OrderBy(RawSQL('%s.%s' % (self.quote_name_unless_alias(table), col), []), descending=descending), False)
            continue
        if self.query.extra and col in self.query.extra:
            if col in self.query.extra_select:
                yield (OrderBy(Ref(col, RawSQL(*self.query.extra[col])), descending=descending), True)
            else:
                yield (OrderBy(RawSQL(*self.query.extra[col]), descending=descending), False)
        elif self.query.combinator and self.select:
            yield (OrderBy(F(col), descending=descending), False)
        else:
            yield from self.find_ordering_name(field, self.query.get_meta(), default_order=default_order)

