def parallelize(self, tp_mesh: DeviceMesh, dp_mesh: DeviceMesh, use_activation_checkpointing: bool, **fsdp_kwargs) -> 'MLPStack':
    parallelize_plan = {'0.in_proj': ColwiseParallel(use_local_output=False), '0.out_proj': RowwiseParallel(use_local_output=False), '1.in_proj': ColwiseParallel(use_local_output=False), '1.out_proj': RowwiseParallel(use_local_output=False), '2.in_proj': ColwiseParallel(use_local_output=False), '2.out_proj': RowwiseParallel(output_layouts=Shard(1)) if self.with_seq_parallel else RowwiseParallel()}
    if <MASK>:
        parallelize_plan['3'] = SequenceParallel(sequence_dim=1)
    parallelize_module(self, device_mesh=tp_mesh, parallelize_plan=parallelize_plan)
    for module in self:
        if isinstance(module, nn.LayerNorm):
            continue
        if use_activation_checkpointing:
            checkpoint(module)
        fully_shard(module, mesh=dp_mesh, **fsdp_kwargs)
    fully_shard(self, mesh=dp_mesh, **fsdp_kwargs)
    return self

