def testConv2DTransposeSingleStride(self):
    with self.cached_session():
        for dtype in (dtypes.float32, dtypes.int32):
            strides = [1, 1, 1, 1]
            x_shape = [2, 6, 4, 3]
            y_shape = [2, 6, 4, 2]
            f_shape = [3, 3, 2, 3]
            x = constant_op.constant(1, shape=x_shape, name='x', dtype=dtype)
            f = constant_op.constant(1, shape=f_shape, name='filter', dtype=dtype)
            output = nn_ops.conv2d_transpose(x, f, y_shape, strides=strides, padding='SAME')
            value = self.evaluate(output)
            for n in range(x_shape[0]):
                for k in range(f_shape[2]):
                    for w in range(y_shape[2]):
                        for h in range(y_shape[1]):
                            target = 4 * 3
                            h_in = h > 0 and h < y_shape[1] - 1
                            w_in = w > 0 and w < y_shape[2] - 1
                            if <MASK>:
                                target += 5 * 3
                            elif h_in or w_in:
                                target += 2 * 3
                            if dtype.is_integer:
                                self.assertAllEqual(target, value[n, h, w, k])
                            else:
                                self.assertAllClose(target, value[n, h, w, k])

def _array_repr_implementation(arr, max_line_width=None, precision=None, suppress_small=None, array2string=array2string):
    """Internal version of array_repr() that allows overriding array2string."""
    current_options = format_options.get()
    override_repr = current_options['override_repr']
    if override_repr is not None:
        return override_repr(arr)
    if max_line_width is None:
        max_line_width = current_options['linewidth']
    if type(arr) is not ndarray:
        class_name = type(arr).__name__
    else:
        class_name = 'array'
    prefix = class_name + '('
    if current_options['legacy'] <= 113 and arr.shape == () and (not arr.dtype.names):
        lst = repr(arr.item())
    else:
        lst = array2string(arr, max_line_width, precision, suppress_small, ', ', prefix, suffix=')')
    extras = []
    if arr.size == 0 and arr.shape != (0,) or (current_options['legacy'] > 210 and arr.size > current_options['threshold']):
        extras.append(f'shape={arr.shape}')
    if not dtype_is_implied(arr.dtype) or arr.size == 0:
        extras.append(f'dtype={dtype_short_repr(arr.dtype)}')
    if <MASK>:
        return prefix + lst + ')'
    arr_str = prefix + lst + ','
    extra_str = ', '.join(extras) + ')'
    last_line_len = len(arr_str) - (arr_str.rfind('\n') + 1)
    spacer = ' '
    if current_options['legacy'] <= 113:
        if issubclass(arr.dtype.type, flexible):
            spacer = '\n' + ' ' * len(prefix)
    elif last_line_len + len(extra_str) + 1 > max_line_width:
        spacer = '\n' + ' ' * len(prefix)
    return arr_str + spacer + extra_str

def __eq__(self, other: object) -> bool:
    """
        Rules for CDT equality:
        1) Any CDT is equal to the string 'category'
        2) Any CDT is equal to itself
        3) Any CDT is equal to a CDT with categories=None regardless of ordered
        4) A CDT with ordered=True is only equal to another CDT with
           ordered=True and identical categories in the same order
        5) A CDT with ordered={False, None} is only equal to another CDT with
           ordered={False, None} and identical categories, but same order is
           not required. There is no distinction between False/None.
        6) Any other comparison returns False
        """
    if isinstance(other, str):
        return other == self.name
    elif other is self:
        return True
    elif not (hasattr(other, 'ordered') and hasattr(other, 'categories')):
        return False
    elif self.categories is None or other.categories is None:
        return self.categories is other.categories
    elif self.ordered or other.ordered:
        return self.ordered == other.ordered and self.categories.equals(other.categories)
    else:
        left = self.categories
        right = other.categories
        if <MASK>:
            return False
        if len(left) != len(right):
            return False
        if self.categories.equals(other.categories):
            return True
        if left.dtype != object:
            indexer = left.get_indexer(right)
            return bool((indexer != -1).all())
        return set(left) == set(right)

