def _validate_compile(self, optimizer, metrics, **kwargs):
    """Performs validation checks for the default `compile`."""
    if <MASK>:
        raise ValueError('`tf.compat.v1.keras` Optimizer (', optimizer, ') is not supported when eager execution is enabled. Use a `tf.keras` Optimizer instead, or disable eager execution.')
    kwargs.pop('cloning', None)
    kwargs.pop('experimental_run_tf_function', None)
    if kwargs.pop('distribute', None) is not None:
        raise ValueError('Distribute argument in compile is not available in TF 2.0 please create the model under the distribution strategy scope.')
    if kwargs.pop('target_tensors', None) is not None:
        raise ValueError('target_tensors argument is not supported when executing eagerly.')
    invalid_kwargs = set(kwargs) - {'sample_weight_mode'}
    if invalid_kwargs:
        raise TypeError('Invalid keyword argument(s) in `compile`: %s' % (invalid_kwargs,))
    if self.built and distribute_lib.has_strategy():
        strategy = distribute_lib.get_strategy()
        for v in self.variables:
            if not strategy.extended.variable_created_in_scope(v):
                raise ValueError('Variable (%s) was not created in the distribution strategy scope of (%s). It is most likely due to not all layers or the model or optimizer being created outside the distribution strategy scope. Try to make sure your code looks similar to the following.\nwith strategy.scope():\n  model=_create_model()\n  model.compile(...)' % (v, strategy))
    strategy = self.distribute_strategy
    for metric in nest.flatten(metrics):
        for v in getattr(metric, 'variables', []):
            if not strategy.extended.variable_created_in_scope(v):
                raise ValueError('Metric (%s) passed to model.compile was created inside of a different distribution strategy scope than the model. All metrics must be created in the same distribution strategy scope as the model (in this case %s). If you pass in a string identifier for a metric to compile the metric will automatically be created in the correct distribution strategy scope.' % (metric, strategy))
    for opt in nest.flatten(optimizer):
        for v in getattr(opt, '_weights', []):
            if not strategy.extended.variable_created_in_scope(v):
                raise ValueError('Optimizer (%s) passed to model.compile was created inside of a different distribution strategy scope than the model. All optimizers must be created in the same distribution strategy scope as the model (in this case %s). If you pass in a string identifier for an optimizer to compile the optimizer will automatically be created in the correct distribution strategy scope.' % (opt, strategy))

def _get_source_of_module(self, module: types.ModuleType) -> Optional[str]:
    filename = None
    spec = getattr(module, '__spec__', None)
    if spec is not None:
        loader = getattr(spec, 'loader', None)
        if loader is not None and isinstance(loader, SourceFileLoader):
            try:
                filename = loader.get_filename(module.__name__)
            except ImportError:
                pass
    if filename is None:
        filename = getattr(module, '__file__', None)
    if <MASK>:
        return ''.join(linecache.getlines(filename, module.__dict__))
    return None

def _fit_transformer(self, y):
    """Check transformer and fit transformer.

        Create the default transformer, fit it and make additional inverse
        check on a subset (optional).

        """
    if self.transformer is not None and (self.func is not None or self.inverse_func is not None):
        raise ValueError("'transformer' and functions 'func'/'inverse_func' cannot both be set.")
    elif self.transformer is not None:
        self.transformer_ = clone(self.transformer)
    else:
        if self.func is not None and self.inverse_func is None or (self.func is None and self.inverse_func is not None):
            (lacking_param, existing_param) = ('func', 'inverse_func') if self.func is None else ('inverse_func', 'func')
            raise ValueError(f"When '{existing_param}' is provided, '{lacking_param}' must also be provided. If {lacking_param} is supposed to be the default, you need to explicitly pass it the identity function.")
        self.transformer_ = FunctionTransformer(func=self.func, inverse_func=self.inverse_func, validate=True, check_inverse=self.check_inverse)
        self.transformer_.set_output(transform='default')
    self.transformer_.fit(y)
    if <MASK>:
        idx_selected = slice(None, None, max(1, y.shape[0] // 10))
        y_sel = _safe_indexing(y, idx_selected)
        y_sel_t = self.transformer_.transform(y_sel)
        if not np.allclose(y_sel, self.transformer_.inverse_transform(y_sel_t)):
            warnings.warn("The provided functions or transformer are not strictly inverse of each other. If you are sure you want to proceed regardless, set 'check_inverse=False'", UserWarning)

def remove_no_ops(gm: torch.fx.GraphModule, zeros: OrderedSet[torch.fx.Node], ones: OrderedSet[torch.fx.Node]):
    with torch.utils._python_dispatch._disable_current_modes():
        'Removes no-ops: (+ 0, - 0, * 1, / 1)'
        graph = gm.graph

        def fake_tensors_eq(t1, t2, fields=('shape', 'dtype', 'device')):
            if <MASK>:
                return False
            for field in fields:
                if getattr(t1, field) != getattr(t2, field):
                    return False
            return True

        def replace_no_op(node, replace_input_index):
            replacement = node.args[replace_input_index]
            if not all((isinstance(arg, torch.fx.Node) for arg in node.args)):
                return
            if not fake_tensors_eq(node.meta['val'], replacement.meta['val']):
                if fake_tensors_eq(node.meta['val'], replacement.meta['val'], ('shape', 'device')):
                    with graph.inserting_after(node):
                        replacement = graph.call_function(torch.ops.prims.convert_element_type.default, args=(replacement, node.meta['val'].dtype))
                else:
                    return
            node.replace_all_uses_with(replacement)
            replacement.meta.update(node.meta)
            graph.erase_node(node)
        for node in graph.find_nodes(op='call_function', target=aten.add.Tensor):
            if len(node.args) == 2:
                if not any((e in zeros for e in node.args)) or node.kwargs.get('alpha', 1) != 1:
                    continue
                replace_index = 1 if node.args[0] in zeros else 0
                replace_no_op(node, replace_index)
        for node in graph.find_nodes(op='call_function', target=aten.sub.Tensor):
            if len(node.args) == 2:
                if node.args[1] not in zeros or node.kwargs.get('alpha', 1) != 1:
                    continue
                replace_no_op(node, 0)
        for node in graph.find_nodes(op='call_function', target=aten.mul.Tensor):
            if len(node.args) == 2:
                if not any((e in ones for e in node.args)):
                    continue
                replace_input_index = 1 if node.args[0] in ones else 0
                replace_no_op(node, replace_input_index)
        for node in graph.find_nodes(op='call_function', target=aten.div.Tensor):
            if len(node.args) == 2 and node.args[1] in ones:
                replace_no_op(node, 0)
        for output_node in graph.find_nodes(op='output'):
            had_meta_return = False

            def visit(n):
                nonlocal had_meta_return
                val = n.meta.get('val')
                if isinstance(val, torch.Tensor) and val.device.type == 'meta':
                    with graph.inserting_before(output_node):
                        n.replace_all_uses_with(graph.call_function(torch.ops.aten.empty_strided.default, args=(val.size(), val.stride()), kwargs={'dtype': val.dtype, 'device': val.device}))
                    had_meta_return = True
            torch.fx.map_arg(output_node.args, visit)
            if had_meta_return:
                graph.eliminate_dead_code()

def get_runtime_arg_values(self, **kwargs: Any) -> list[Any]:
    arg_names = OrderedSet([arg.name for arg in self.get_runtime_arg_info()])
    if <MASK>:
        raise ValueError('Missing runtime arguments: ' + ', '.join(arg_names - kwargs.keys()))
    return [kwargs[k] for k in arg_names]

@dispatch.add_dispatch_support
@doc_controls.do_not_generate_docs
def stop_gradient(variables):
    """Returns `variables` but with zero gradient w.r.t. every other variable.

  Args:
      variables: Tensor or list of tensors to consider constant with respect
        to any other variable.


  Returns:
      A single tensor or a list of tensors (depending on the passed argument)
      that has no gradient with respect to any other variable.
  """
    if <MASK>:
        return map(array_ops.stop_gradient, variables)
    return array_ops.stop_gradient(variables)

def redistribute_cost(current_spec: 'dtensor_spec.DTensorSpec', target_spec: 'dtensor_spec.DTensorSpec') -> float:
    """
    This function returns the cost of redistribute from current to target DTensorSpec.

    NOTE:
    1. Only consider communication cost here, since computation costs for redistribute
       are quite trivial (i.e. we only need to narrow or simple division)
    2. Only consider redistribute cost on same mesh, cross mesh communication cost is
       not quite needed for operator strategy estimation/selection.
    """
    if current_spec.mesh != target_spec.mesh:
        return float('inf')
    if current_spec.is_replicated():
        return 0.0
    mesh_topo = MeshTopoInfo.build_from_mesh(current_spec.mesh)
    cost = 0.0
    comm_bytes_gb = spec_to_bytes(current_spec) / current_spec.num_shards / 1024 / 1024 / 1024
    for (i, (current, target)) in enumerate(zip(current_spec.placements, target_spec.placements)):
        if current == target:
            continue
        num_devices_on_mesh_dim = mesh_topo.mesh_dim_devices[i]
        if current.is_shard() and target.is_replicate():
            comm_bytes_gb *= num_devices_on_mesh_dim
            cost += allgather_cost(comm_bytes_gb, mesh_topo, i)
        elif current.is_shard() and target.is_shard():
            cost += allgather_cost(comm_bytes_gb, mesh_topo, i) + 1.0
        elif current.is_partial() and target.is_replicate():
            cost += allreduce_cost(comm_bytes_gb, mesh_topo, i)
        elif current.is_partial() and target.is_shard():
            cost += reduce_scatter_cost(comm_bytes_gb, mesh_topo, i)
            comm_bytes_gb /= num_devices_on_mesh_dim
        elif <MASK>:
            return float('inf')
    return cost

def get_inputs(input_data_path):
    """
    Return a random input for the given inputs meta generated from _save_fx_default.
    """
    inputs = []
    with open(input_data_path, 'rb') as f:
        inputs_meta = pickle.load(f)
        inputs = []
        for meta in inputs_meta:
            if len(meta) == 1:
                type = meta
                input = type(random.rand())
            else:
                (type, shape, _stride, dtype, device) = meta
                if <MASK>:
                    input = torch.randint(0, 1, shape, dtype=dtype, device=device)
                else:
                    input = torch.rand(shape, dtype=dtype, device=device)
            inputs.append(input)
    return inputs

def __call__(self, x, *args, **params):
    func = getattr(np, self.__name__)
    if <MASK>:
        _d = func(x.__array__(), *args, **params)
        _m = func(getmaskarray(x), *args, **params)
        return masked_array(_d, mask=_m)
    else:
        _d = func(np.asarray(x), *args, **params)
        _m = func(getmaskarray(x), *args, **params)
        return masked_array(_d, mask=_m)

def val_to_arg_str_for_prim_type(self, val, type_) -> str:
    if isinstance(val, bool):
        return '1' if val else '0'
    elif isinstance(val, int):
        return f'{val}LL' if sys.platform in ['darwin', 'win32'] else f'{val}L'
    elif isinstance(val, complex):
        return f'c10::complex<double>{{ {self.generate_float_value(val.real)}, {self.generate_float_value(val.imag)} }}'
    elif isinstance(val, str):
        return f'"{val}"'
    elif isinstance(val, (ir.Buffer, ir.ReinterpretView, ir.StorageBox, ir.TensorBox)):
        return val.codegen_reference()
    elif isinstance(val, torch.device):
        return self.codegen_device(val)
    elif isinstance(val, torch.dtype):
        return self.codegen_dtype(val)
    elif isinstance(val, torch.layout):
        return self.codegen_layout(val)
    elif isinstance(val, torch.memory_format):
        return self.codegen_memory_format(val)
    elif isinstance(val, float):
        return self.generate_float_value(val)
    elif isinstance(val, (list, tuple)):
        return f"{{{', '.join((self.val_to_arg_str(x, None) for x in val))}}}"
    elif <MASK>:
        return cexpr(val.node.expr)
    elif isinstance(val, sympy.Expr):
        return cexpr(val)
    else:
        return repr(val)

def find_common_type(types):
    """
    Find a common data type among the given dtypes.

    Parameters
    ----------
    types : list of dtypes

    Returns
    -------
    pandas extension or numpy dtype

    See Also
    --------
    numpy.find_common_type

    """
    if not types:
        raise ValueError('no types given')
    first = types[0]
    if lib.dtypes_all_equal(list(types)):
        return first
    types = list(dict.fromkeys(types).keys())
    if any((isinstance(t, ExtensionDtype) for t in types)):
        for t in types:
            if isinstance(t, ExtensionDtype):
                res = t._get_common_dtype(types)
                if <MASK>:
                    return res
        return np.dtype('object')
    if all((lib.is_np_dtype(t, 'M') for t in types)):
        return np.dtype(max(types))
    if all((lib.is_np_dtype(t, 'm') for t in types)):
        return np.dtype(max(types))
    has_bools = any((t.kind == 'b' for t in types))
    if has_bools:
        for t in types:
            if t.kind in 'iufc':
                return np.dtype('object')
    return np_find_common_type(*types)

@compatibility(is_backward_compatible=True)
def __init__(self, module: torch.nn.Module, garbage_collect_values: bool=True, graph: Optional[Graph]=None):
    self.module = module
    self.submodules = dict(self.module.named_modules())
    if <MASK>:
        self.graph = graph
    else:
        self.graph = self.module.graph
    self.env: dict[Node, Any] = {}
    self.name = 'Interpreter'
    self.garbage_collect_values = garbage_collect_values
    self.extra_traceback = True
    if self.garbage_collect_values:
        node_to_last_use: dict[Node, Node] = {}
        self.user_to_last_uses: dict[Node, list[Node]] = {}

        def register_last_uses(n: Node, user: Node):
            if n not in node_to_last_use:
                node_to_last_use[n] = user
                self.user_to_last_uses.setdefault(user, []).append(n)
        for node in reversed(self.graph.nodes):
            for n in node._input_nodes:
                register_last_uses(n, node)

def select_jinja_autoescape(self, filename: str) -> bool:
    """Returns ``True`` if autoescaping should be active for the given
        template name. If no template name is given, returns `True`.

        .. versionchanged:: 2.2
            Autoescaping is now enabled by default for ``.svg`` files.

        .. versionadded:: 0.5
        """
    if <MASK>:
        return True
    return filename.endswith(('.html', '.htm', '.xml', '.xhtml', '.svg'))

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    (inner_fn, source) = self._resolved_getattr_and_source(self, name)
    if inner_fn is object.__init__:
        return LambdaVariable(identity)
    elif inner_fn is torch.nn.Module.__init__:
        objvar = self.objvar
        from ..side_effects import AttributeMutationNew
        if isinstance(objvar, variables.UserDefinedObjectVariable) and isinstance(objvar.mutation_type, AttributeMutationNew) and (not (args or kwargs)):
            with do_not_convert_to_tracable_parameter():
                return variables.UserFunctionVariable(unpatched_nn_module_init, source=source).call_function(tx, [self.objvar] + args, kwargs)
        else:
            unimplemented_v2(gb_type='Unsupported super().__init__() call', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'Dynamo encountered a super().__init__() call on {objvar} that resolved to a `torch.nn.Module.__init__()` call that we cannot trace.', hints=[*graph_break_hints.DIFFICULT])
    elif self.objvar.source and hasattr(inner_fn, '__name__') and (inner_fn.__name__ == '__new__') and variables.UserDefinedClassVariable.is_supported_new_method(inner_fn):
        user_cls = inner_fn.__self__
        if hasattr(user_cls, '__module__') and user_cls.__module__ == 'builtins':
            user_cls_vt = variables.BuiltinVariable(user_cls)
        else:
            user_cls_source = source.member
            user_cls_vt = variables.UserDefinedClassVariable(user_cls, source=user_cls_source)
        return user_cls_vt.call_method(tx, '__new__', args, kwargs)
    elif isinstance(inner_fn, staticmethod) and isinstance(inner_fn.__func__, types.FunctionType):
        return variables.UserFunctionVariable(inner_fn.__func__, source=source).call_function(tx, args, kwargs)
    elif isinstance(inner_fn, classmethod) and isinstance(inner_fn.__func__, types.FunctionType):
        if isinstance(self.objvar, variables.UserDefinedClassVariable):
            cls_variable = self.objvar
        else:
            cls_source = None
            if self.objvar.source:
                cls_source = TypeSource(self.objvar.source)
            cls_variable = VariableTracker.build(tx, self.objvar.value_type, cls_source)
        return variables.UserFunctionVariable(inner_fn.__func__, source=AttrSource(source, '__func__')).call_function(tx, [cls_variable, *args], kwargs)
    elif isinstance(inner_fn, types.FunctionType):
        return variables.UserFunctionVariable(inner_fn, source=source).call_function(tx, [self.objvar] + args, kwargs)
    elif isinstance(inner_fn, types.MethodType):
        return variables.UserMethodVariable(inner_fn.__func__, self.objvar, source=source).call_function(tx, args, kwargs)
    elif is_standard_setattr(inner_fn) and isinstance(self.objvar, UserDefinedObjectVariable):
        return self.objvar.method_setattr_standard(tx, *args, **kwargs)
    elif inner_fn is object.__delattr__:
        attr = args[0]
        try:
            attr = attr.as_python_constant()
        except NotImplementedError as exc:
            unimplemented_v2(gb_type='Non-constant attribute given to `super().__delattr__()`', context=f'call_method {self} {name}', explanation='Dynamo requires the attribute name passed to `super().__delattr__(...)` to be a constant (string).', hints=['Ensure the attribute name is a string literal or a constant variable.'], from_exc=exc)
        if not tx.output.side_effects.is_attribute_mutation(self.objvar):
            unimplemented_v2(gb_type='Attempted super().__delattr__() on an object without mutation tracking', context=f'call_method {self} {name}', explanation=f"Dynamo needs to track mutations on an object before `super().__delattr__` can be used on it. But the object ({self.objvar}) doesn't have attribute mutation tracking enabled.", hints=["Ensure the object is tracked by Dynamo's side effect system.", *graph_break_hints.DYNAMO_BUG])
        tx.output.side_effects.store_attr(self.objvar, attr, variables.DeletedVariable())
        return variables.ConstantVariable(None)
    elif isinstance(self.objvar, variables.UserDefinedDictVariable) and inner_fn in self.objvar._dict_methods:
        return self.objvar._dict_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedSetVariable) and inner_fn in self.objvar._set_methods:
        return self.objvar._set_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedTupleVariable) and inner_fn in tuple_methods:
        return self.objvar._tuple_vt.call_method(tx, name, args, kwargs)
    elif <MASK>:
        return self.objvar._list_vt.call_method(tx, name, args, kwargs)
    elif inner_fn is object.__getattribute__:
        attr_name = args[0].value
        if tx.output.side_effects.has_pending_mutation_of_attr(self.objvar, attr_name):
            result = tx.output.side_effects.load_attr(self.objvar, attr_name, deleted_ok=True)
            if isinstance(result, variables.DeletedVariable):
                raise_observed_exception(AttributeError, tx)
            return result
        try:
            attr_value = object.__getattribute__(self.objvar.value, attr_name)
        except AttributeError:
            raise_observed_exception(AttributeError, tx)
        attr_source = None
        if self.objvar.source is not None:
            attr_source = GenericAttrSource(self.objvar.source, attr_name)
        return VariableTracker.build(tx, attr_value, attr_source)
    elif inner_fn is torch._C._disabled_torch_function_impl:
        func = args[0]
        tf_kwargs = {}
        tf_args = args[2].items
        for (hash_key_vt, value_vt) in args[3].items.items():
            key_str = hash_key_vt.vt.as_python_constant()
            tf_kwargs[key_str] = value_vt
        tx_old = tx.symbolic_torch_function_state.torch_function_subclass_enabled
        tx.symbolic_torch_function_state.torch_function_subclass_enabled = False
        try:
            return func.call_function(tx, tf_args, tf_kwargs)
        finally:
            tx.symbolic_torch_function_state.torch_function_subclass_enabled = tx_old
    elif isinstance(inner_fn, types.MethodDescriptorType) and inner_fn in trace_rules.get_tensor_method():
        fn_var = VariableTracker.build(tx, inner_fn, source)
        return fn_var.call_function(tx, [self.objvar] + args, kwargs)
    unimplemented_v2(gb_type='Attempted to call a super() attribute that is not a function or method', context=f'call_method {self} {name}', explanation=f'Dynamo does not know how to trace the call `super().{name}()` because `super().{name}` is not a function or method attribute.', hints=['Ensure the attribute accessed via `super()` is a standard method or function.'])

def create_rdzv_handler(params: RendezvousParameters) -> RendezvousHandler:
    if <MASK>:
        raise ValueError('rank is absent in RendezvousParameters.Try add --node-rank to the cmd request')
    endpoint = params.endpoint.strip()
    if not endpoint:
        raise ValueError('endpoint is absent in RendezvousParametersTry add --master-port and --master-addr to the cmd request')
    (master_addr, master_port) = parse_rendezvous_endpoint(endpoint, -1)
    if master_port == -1:
        raise ValueError(f'Port is absent in endpoint: {endpoint}. Try launching with --master-port')
    world_size = params.max_nodes
    rank = cast(int, params.config.get('rank'))
    run_id = params.run_id
    if 'timeout' in params.config:
        timeout = int(params.config['timeout'])
    else:
        timeout = _default_timeout_seconds
    return StaticTCPRendezvous(master_addr, master_port, rank, world_size, run_id, timeout)

@tf_utils.shape_type_conversion
def build(self, input_shape):
    if isinstance(input_shape, list):
        input_shape = input_shape[0]
    for cell in self.cells:
        if isinstance(cell, Layer) and (not cell.built):
            with backend.name_scope(cell.name):
                cell.build(input_shape)
                cell.built = True
        if <MASK>:
            output_dim = cell.output_size
        elif _is_multiple_state(cell.state_size):
            output_dim = cell.state_size[0]
        else:
            output_dim = cell.state_size
        input_shape = tuple([input_shape[0]] + tensor_shape.TensorShape(output_dim).as_list())
    self.built = True

def create_functionalized_fn(fn, args, args_descs, *, meta: ViewAndMutationMeta, aot_config: AOTConfig, trace_joint: bool, joint_fn_handle: Optional[JointFnHandle]=None) -> Any:
    primals_after_forward = None
    f_args_after_forward = None
    f_args_mutation_counters_after_forward: Optional[list[MutationCounters]] = None
    inputs_mutated_in_graph = [info.mutation_type == MutationType.MUTATED_IN_GRAPH for info in meta.input_info]
    has_input_mutated_in_graph = any(inputs_mutated_in_graph)

    @simple_wraps(fn)
    def _functionalized_f_helper(*args: list[FxValue]) -> tuple[tuple[list[FxValue], list[Tensor]], list[Optional[AOTOutput]]]:
        with maybe_enable_thunkify():
            disable_above = torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize))
            with disable_above:
                f_args = pytree.tree_map(to_fun, args)
                if trace_joint and has_input_mutated_in_graph and joint_fn_handle:

                    def _post_forward(primals):
                        nonlocal primals_after_forward
                        primals_after_forward = pytree.tree_map(from_fun, primals)
                        nonlocal f_args_after_forward
                        f_args_after_forward = f_args[0]
                        nonlocal f_args_mutation_counters_after_forward
                        f_args_mutation_counters_after_forward = [MutationCounters(-1, -1, -1) if not inputs_mutated_in_graph[i] else _get_mutation_counters(f_arg) for (i, f_arg) in enumerate(f_args_after_forward)]
                    joint_fn_handle.post_forward = _post_forward
                (f_outs, f_outs_descs) = call_and_expect_output_descs(fn, f_args)
            if trace_joint:
                assert isinstance(args, tuple) and len(args) == 2 and isinstance(args[0], (list, tuple))
                primals_before = args[0]
                primals_after = pytree.tree_map(from_fun, f_args[0])
                for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args[0], primals_before, primals_after, meta.input_info)):
                    joint_mutates_data = has_data_mutation(f_inpt)
                    joint_mutates_metadata = has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False)
                    if not inpt_info.mutates_metadata:
                        assert not joint_mutates_metadata, 'Found a graph input that had its metadata mutated in the backward. This is not supported'
                    if not inpt_info.mutation_inductor_storage_resize:
                        assert not was_inductor_storage_resized(f_inpt), 'Found a graph input that had storage resizing in the backward. This is not supported'
                    if joint_mutates_data and (not inpt_info.mutates_data) and (not inpt_info.mutates_storage_metadata):
                        with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                            assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                            before.copy_(after)
                        meta.indices_of_inputs_that_requires_grad_with_mutations_in_bw.append(idx)
                tangents_before = args[1]
                tangents_after = pytree.tree_map(from_fun, f_args[1])
                for (f_inpt, before, after) in zip(f_args[1], tangents_before, tangents_after):
                    assert not has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False), 'Found an input to the backward that had metadata mutated during the backward pass. This is not supported'
                    if has_data_mutation(f_inpt):
                        can_be_in_graph = _check_if_mutation_can_be_in_graph(keep_input_mutations=True, mutates_data=True, mutates_metadata=False, mutations_hidden_from_autograd=are_all_mutations_hidden_from_autograd(f_inpt), mutations_under_no_grad_or_inference_mode=are_all_mutations_under_no_grad_or_inference_mode(f_inpt), mutates_storage_metadata=False, mutation_inductor_storage_resize=was_inductor_storage_resized(f_inpt), requires_grad=f_inpt.requires_grad)
                        assert can_be_in_graph, 'a backward input that had data mutated in an autograd-aware way. This is not supported'
                        with torch.fx.traceback.preserve_node_meta():
                            assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                            before.copy_(after)
            if aot_config.keep_inference_input_mutations:
                mcs_applied: list[MutationCounters] = [MutationCounters(0, 0, 0)] * len(meta.input_info)
                if f_args_mutation_counters_after_forward is not None:
                    primals_before = args[0]
                    for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args_after_forward, primals_before, primals_after_forward, meta.input_info)):
                        if inpt_info.mutation_type != MutationType.MUTATED_IN_GRAPH:
                            continue
                        mcs_after_forward = f_args_mutation_counters_after_forward[idx]
                        with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_forward(), _proxy_tensor_disable_update_tensor_tracker():
                            apply_in_graph_mutations(inpt_info, before, after, f_inpt, idx, mcs_after_forward, mcs_applied[idx])
                            mcs_applied[idx] = mcs_after_forward
                for (idx, (inpt_old, f_inpt)) in enumerate(zip(args, f_args) if not trace_joint else zip(args[0], f_args[0])):
                    if not isinstance(f_inpt, torch.Tensor):
                        continue
                    assert is_fun(f_inpt)
                    inpt_new = from_fun(f_inpt)
                    if meta.input_info[idx].mutation_type != MutationType.MUTATED_IN_GRAPH:
                        continue
                    mcs: Optional[MutationCounters] = None
                    if f_args_mutation_counters_after_forward is not None:
                        mcs = _get_mutation_counters(f_inpt)
                        if <MASK>:
                            continue
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                        apply_in_graph_mutations(meta.input_info[idx], inpt_old, inpt_new, f_inpt, idx, mcs, mcs_applied[idx])
                (flat_outs, outs_spec) = pytree.tree_flatten(f_outs)
                flat_outs = [from_fun(o) for o in flat_outs]
                num_outs = len(meta.output_info)
                for i in range(num_outs):
                    info = meta.output_info[i]
                    if info.output_type != OutputType.is_input:
                        continue
                    assert info.base_idx is not None
                    if meta.input_info[info.base_idx].mutation_type == MutationType.MUTATED_IN_GRAPH:
                        fw_args = args[0] if trace_joint else args
                        flat_outs[i] = fw_args[info.base_idx]
                return (pytree.tree_unflatten(flat_outs, outs_spec), f_outs_descs)
            return (pytree.tree_map(from_fun, f_outs), f_outs_descs)

    def joint_helper(primals, tangents):
        return _functionalized_f_helper(primals, tangents)
    helper = joint_helper if trace_joint else _functionalized_f_helper
    if config.functionalize_rng_ops:
        (helper, args, args_descs) = create_functionalized_rng_ops_wrapper(helper, args, args_descs, trace_joint)
    return (helper, args, args_descs)

def decorator(f: Callable[..., Any]) -> Callable[..., None]:
    if tf_inspect.isclass(f):
        raise ValueError('`run_in_graph_and_eager_modes` only supports test methods. Did you mean to use `run_all_in_graph_and_eager_modes`?')

    def decorated(self: 'TensorFlowTestCase', *args, **kwargs) -> None:
        logging.info('Running %s in GRAPH mode.', f.__name__)
        try:
            with context.graph_mode(), self.subTest('graph_mode'):
                for class_ in self.__class__.mro():
                    if class_.__name__ == 'XLATestCase':
                        session_func = self.session
                        session_kwargs = {}
                        break
                else:
                    session_func = self.test_session
                    session_kwargs = dict(use_gpu=use_gpu, config=config)
                with session_func(**session_kwargs):
                    f(self, *args, **kwargs)
        except unittest.case.SkipTest:
            pass

        def run_eagerly(self: 'TensorFlowTestCase', **kwargs) -> None:
            logging.info('Running %s in EAGER mode.', f.__name__)
            if not use_gpu:
                with ops.device('/device:CPU:0'):
                    f(self, *args, **kwargs)
            else:
                f(self, *args, **kwargs)
        if <MASK>:
            ops.reset_default_graph()
            run_eagerly = assert_no_new_tensors(assert_no_garbage_created(run_eagerly))
        self.tearDown()
        self._tempdir = None
        graph_for_eager_test = ops.Graph()
        with graph_for_eager_test.as_default(), context.eager_mode(), self.subTest('eager_mode'):
            self.setUp()
            run_eagerly(self, **kwargs)
        ops.dismantle_graph(graph_for_eager_test)
    return tf_decorator.make_decorator(f, decorated)

def convert_dim_to_auto(dim: Any) -> Any:
    if isinstance(dim, Dim):
