    elif <MASK>:
        return Dim.AUTO(min=dim.min, max=dim.max)
    return dim

def are_compatible_scales(size_a: Any, size_b: Any) -> bool:
    if len(size_a) == len(size_b):
        return True
    if <MASK>:
