    return False

def _find_matches(graph: Graph, modules: dict[str, torch.nn.Module], patterns: dict[Pattern, QuantizeHandler], root_node_getter_mapping: dict[Pattern, Callable], standalone_module_names: Optional[list[str]]=None, standalone_module_classes: Optional[list[type]]=None, custom_module_classes: Optional[list[Any]]=None) -> dict[str, _MatchResult]:
    """
    Matches the nodes in the input graph to quantization patterns, and
    outputs the information needed to quantize them in future steps.

    Inputs:
      - graph: an fx.Graph object
      - modules: a mapping of fully qualified module name to instance,
          for example, {'foo': ModuleFoo, ...}
      - patterns: a mapping from a tuple of nodes in reverse order to
          uninitialized QuantizeHandler subclass.

    Outputs a map of
      node_name ->
        (node, matched_values, matched_pattern, QuantizeHandler instance,
         qconfig)

    For example, {
      'relu_1': (relu_1, [relu_1], torch.nn.functional.relu,
                 <CopyNodeQuantizeHandler instance>, QConfig(...)),
      ...
    }
    """
    if custom_module_classes is None:
        custom_module_classes = []
    if standalone_module_classes is None:
        standalone_module_classes = []
    if standalone_module_names is None:
        standalone_module_names = []
    match_map: dict[str, _MatchResult] = {}
    all_matched: set[str] = set()

    def _recursive_record_node_in_match_map(last_node, match_map, node_pattern, matched_node_pattern, pattern, match_value):
        if isinstance(node_pattern, Node):
            match_map[node_pattern.name] = (last_node, matched_node_pattern, pattern, match_value)
        elif not isinstance(node_pattern, Iterable):
            return
        else:
            for n in node_pattern:
                _recursive_record_node_in_match_map(last_node, match_map, n, matched_node_pattern, pattern, match_value)

    def record_match(pattern, node, last_node, matched_node_pattern, match_map):
        if isinstance(pattern, tuple):
            (s, *args) = pattern
            is_single_arg = len(args) == 1
            current_node_pattern: list[Node] = []
            record_match(s, node, last_node, matched_node_pattern, match_map)
            if pattern[0] is not getattr:
                for (subpattern, arg) in zip(args, node.args):
                    record_match(subpattern, arg, node, current_node_pattern, match_map)
            if len(current_node_pattern) > 1:
                if is_single_arg:
                    matched_node_pattern.append(tuple(current_node_pattern))
                else:
                    matched_node_pattern.extend(list(current_node_pattern))
            else:
                matched_node_pattern.append(current_node_pattern[0])
        else:
            matched_node_pattern.append(node)
    for node in reversed(graph.nodes):
        if <MASK>:
            for (pattern, quantize_handler_cls) in patterns.items():
                root_node_getter = root_node_getter_mapping.get(pattern)
                if _is_match(modules, node, pattern) and node.name not in match_map:
                    matched_node_pattern: list[Node] = []
                    record_match(pattern, node, node, matched_node_pattern, match_map)
                    quantize_handler = quantize_handler_cls(matched_node_pattern, modules, root_node_getter)
                    last_node = node
                    _recursive_record_node_in_match_map(last_node, match_map, matched_node_pattern, matched_node_pattern, pattern, quantize_handler)
                    break
    assert modules is not None
    for node in graph.nodes:
        if node.op == 'call_module' and type(modules[node.target]) in custom_module_classes:
            match_map[node.name] = (node, node, None, QuantizeHandler(node, modules, is_custom_module=True))

    def is_standalone_module(node_target: str, modules: dict[str, torch.nn.Module]):
        assert modules is not None
        return node_target in standalone_module_names or type(modules[node_target]) in standalone_module_classes
    for node in graph.nodes:
        if node.op == 'call_module' and (is_standalone_module(node.target, modules) or _is_observed_standalone_module(modules[node.target])):
            match_map[node.name] = (node, node, None, QuantizeHandler(node, modules, is_standalone_module=True))
    return match_map

def resolve_relation(model, app_label=None, model_name=None):
    """
    Turn a model class or model reference string and return a model tuple.

    app_label and model_name are used to resolve the scope of recursive and
    unscoped model relationship.
    """
    if isinstance(model, str):
        if <MASK>:
            if app_label is None or model_name is None:
                raise TypeError('app_label and model_name must be provided to resolve recursive relationships.')
            return (app_label, model_name)
        if '.' in model:
            (app_label, model_name) = model.split('.', 1)
            return (app_label, model_name.lower())
        if app_label is None:
            raise TypeError('app_label must be provided to resolve unscoped model relationships.')
        return (app_label, model.lower())
    return (model._meta.app_label, model._meta.model_name)

def array_like_impl(array_fn, array_like_fn, tensor, dtype, name, optimize=True, layout=None):
    """Internal implementation for ones_like and zeros_like API calls."""
    if not tensor_util.is_tf_type(tensor):
        tensor = ops.convert_to_tensor(tensor, name='tensor')
    tensor_shape = tensor.shape
    tensor_dtype = tensor.dtype
    if <MASK>:
        if dtype is not None and dtype != tensor_dtype:
            return array_fn(shape_internal(tensor, optimize=optimize), dtype=dtype, name=name, layout=layout)
        return d_api.call_with_layout(array_like_fn, layout, tensor, name=name)
    if optimize and tensor_shape.is_fully_defined() and (tensor_dtype != dtypes.variant):
        return array_fn(tensor_shape, dtype=dtype or tensor_dtype, name=name, layout=layout)
    if dtype is not None and dtype != tensor_dtype and (dtype != dtypes.variant):
        return array_fn(shape_internal(tensor, optimize=optimize), dtype=dtype, name=name, layout=layout)
    return d_api.call_with_layout(array_like_fn, layout, tensor, name=name)

def _round_temporally(self, method: Literal['ceil', 'floor', 'round'], freq, ambiguous: TimeAmbiguous='raise', nonexistent: TimeNonexistent='raise') -> Self:
    if <MASK>:
        raise NotImplementedError('ambiguous is not supported.')
    if nonexistent != 'raise':
        raise NotImplementedError('nonexistent is not supported.')
    offset = to_offset(freq)
    if offset is None:
        raise ValueError(f'Must specify a valid frequency: {freq}')
    pa_supported_unit = {'Y': 'year', 'YS': 'year', 'Q': 'quarter', 'QS': 'quarter', 'M': 'month', 'MS': 'month', 'W': 'week', 'D': 'day', 'h': 'hour', 'min': 'minute', 's': 'second', 'ms': 'millisecond', 'us': 'microsecond', 'ns': 'nanosecond'}
    unit = pa_supported_unit.get(offset._prefix, None)
    if unit is None:
        raise ValueError(f'freq={freq!r} is not supported')
    multiple = offset.n
    rounding_method = getattr(pc, f'{method}_temporal')
    result = rounding_method(self._pa_array, multiple=multiple, unit=unit)
    return self._from_pyarrow_array(result)

def _get_block_composite_vars(self, modified, live_in):
    composite_scope_vars = []
    for s in modified:
        if not s.is_composite():
            continue
        support_set_symbols = tuple((sss for sss in s.support_set if sss.is_symbol()))
        if <MASK>:
            continue
        composite_scope_vars.append(s)
    return frozenset(composite_scope_vars)

def prune_dead_object_new(self, tx: 'InstructionTranslatorBase') -> None:
    visited: set[VariableTracker] = set()
    live_new_objects: set[VariableTracker] = set()

    def visit(var: VariableTracker) -> None:
        if var in visited:
            return
        visited.add(var)
        if isinstance(var.mutation_type, AttributeMutationNew):
            live_new_objects.add(var)
        if <MASK>:
            VariableTracker.visit(visit, self.store_attr_mutations[var])

    def is_live(var: VariableTracker) -> bool:
        if isinstance(var.mutation_type, AttributeMutationNew):
            return var in live_new_objects
        return True
    pre_existing_vars = [var for var in self.id_to_variable.values() if not isinstance(var.mutation_type, AttributeMutationNew)]
    init_live_vars = []
    cur_tx: Optional[InstructionTranslatorBase] = tx
    while cur_tx is not None:
        init_live_vars.extend([cur_tx.stack, cur_tx.symbolic_locals])
        cur_tx = cur_tx.parent
    VariableTracker.visit(visit, init_live_vars + [pre_existing_vars, tx.output.backward_state, self.tensor_hooks])
    del visit
    self.id_to_variable = {k: v for (k, v) in self.id_to_variable.items() if is_live(v)}
    self.store_attr_mutations = {k: v for (k, v) in self.store_attr_mutations.items() if is_live(k)}

def tearDown(self):
    if hasattr(self, '_check_invariants'):
        if <MASK>:
            torch.sparse.check_sparse_tensor_invariants.enable()
        else:
            torch.sparse.check_sparse_tensor_invariants.disable()
    if self._default_dtype_check_enabled:
        assert torch.get_default_dtype() == torch.float
    if hasattr(self, '_prev_grad_state'):
        torch.set_grad_enabled(self._prev_grad_state)

def generate_example_arg_value(self, arg, arg_type, raw_arg=None):
    if isinstance(arg_type, torch_dtype):
        if isinstance(raw_arg, ir.TMADescriptor):
            buf_name = raw_arg.get_tensor().get_name()
            buf = self.args_to_buffers[arg]
        elif self.args_to_buffers.get(arg):
            buf_name = arg
            buf = self.args_to_buffers[arg]
        else:
            assert raw_arg is not None, "V.graph.get_buffer(arg) and raw_arg can't be None at the same time"
            buf_name = f'tmp_arg_{self.kernel_autotune_tmp_arg_idx}'
            buf = raw_arg
            self.kernel_autotune_tmp_arg_idx += 1
        assert buf is not None, f'Failed to find a buffer for arg {arg}'
        size = tuple((V.graph.sizevars.atomically_apply_size_hint(e, fallback=config.unbacked_symint_fallback) for e in buf.get_size()))
        allocation_size = tuple((V.graph.sizevars.atomically_apply_size_hint(e, fallback=config.unbacked_symint_fallback) for e in V.graph.get_allocation_size(buf)))
        stride = tuple((V.graph.sizevars.atomically_apply_size_hint(e, fallback=config.unbacked_symint_fallback) for e in buf.get_stride()))
        device = buf.get_device()
        dtype = buf.get_dtype()
        offset = V.graph.sizevars.size_hint(buf.get_layout().offset, fallback=config.unbacked_symint_fallback)
        value = f"generate_example_value({size}, {stride}, '{device}', {dtype}, {offset}, {allocation_size})"
        self.kernel_autotune_calls.writeline(f'{buf_name} = {value}')
        if isinstance(raw_arg, ir.TMADescriptor):
            value = self._generate_tma_descriptor_call(desc=raw_arg, apply_size_hints=True)
            buf_name = arg
            self.kernel_autotune_calls.writeline(f'{buf_name} = {value}')
        return buf_name
    elif issubclass(arg_type, sympy.Basic) or isinstance(arg, SymbolicCallArg):
        if isinstance(arg, str):
            if arg in self._meta_vars:
                return arg
            if raw_arg is None:
                return 'None'
            arg = raw_arg
        if isinstance(arg, SymbolicCallArg):
            arg = arg.inner_expr
        if arg in V.graph.sizevars.inv_precomputed_replacements:
            arg = V.graph.sizevars.inv_precomputed_replacements[arg]
        return str(V.graph.sizevars.atomically_apply_size_hint(arg, fallback=config.unbacked_symint_fallback))
    elif <MASK>:
        return str(arg)
    elif isinstance(arg, list):
        return f"[{', '.join((self.generate_example_arg_value(a, type(a)) for a in arg))}]"
    else:
        raise NotImplementedError(f'Unsupported type {type(arg)}')

@timed('Creating virtual environment')
def create(self, *, remove_if_exists: bool=False, assume_yes: bool=False) -> Path:
    """Create a virtual environment."""
    if <MASK>:
        if remove_if_exists:
            if not self.is_venv():
                raise RuntimeError(f'The path {self.prefix} already exists and is not a virtual environment. Please remove it manually or choose a different prefix.')
            if any((Path(p).absolute().samefile(self.prefix) for p in [sys.prefix, sys.exec_prefix, sys.base_prefix, sys.base_exec_prefix])):
                raise RuntimeError(f'The path {self.prefix} trying to remove is the same as the interpreter to run this script. Please choose a different prefix or deactivate the current virtual environment.')
            if any((Path(self.base_python('-c', f'import os, sys; print(os.path.abspath({p}))', capture_output=True).stdout.strip()).absolute().samefile(self.prefix) for p in ['sys.prefix', 'sys.exec_prefix', 'sys.base_prefix', 'sys.base_exec_prefix'])):
                raise RuntimeError(f'The Python executable {self.base_executable} trying to remove is the same as the interpreter to create the virtual environment. Please choose a different prefix or a different Python interpreter.')
            if not assume_yes:
                answer = input(f'The virtual environment {self.prefix} already exists. Do you want to remove it and recreate it? [y/N] ')
                if answer.lower() not in ('y', 'yes'):
                    if answer.lower() not in ('n', 'no', ''):
                        print(f'Invalid answer: {answer!r}')
                    else:
                        print(f'Aborting due to existing prefix: {self.prefix}')
                    sys.exit(1)
            print(f'Removing existing venv: {self.prefix}')
            _remove_existing(self.prefix)
        else:
            raise RuntimeError(f'Path {self.prefix} already exists.')
    print(f'Creating venv (Python {self.base_python_version()}): {self.prefix}')
    self.base_python('-m', 'venv', str(self.prefix))
    assert self.is_venv(), 'Failed to create virtual environment.'
    (self.prefix / '.gitignore').write_text('*\n', encoding='utf-8')
    if LINUX:
        activate_script = self.activate_script
        st_mode = activate_script.stat().st_mode
        activate_script.chmod(st_mode | 128)
        with activate_script.open(mode='a', encoding='utf-8') as f:
            f.write('\n' + textwrap.dedent(f'\n                        # Add NVIDIA PyPI packages to LD_LIBRARY_PATH\n                        export LD_LIBRARY_PATH="$(\n                            {self.executable.name} - <<EOS\n                        import glob\n                        import itertools\n                        import os\n                        import site\n\n                        nvidia_libs = [\n                            p.rstrip("/")\n                            for p in itertools.chain.from_iterable(\n                                glob.iglob(f"{{site_dir}}/{{pattern}}/", recursive=True)\n                                for site_dir in site.getsitepackages()\n                                for pattern in ("nvidia/**/lib", "cu*/**/lib")\n                            )\n                        ]\n                        ld_library_path = os.getenv("LD_LIBRARY_PATH", "").split(os.pathsep)\n                        print(os.pathsep.join(dict.fromkeys(nvidia_libs + ld_library_path)))\n                        EOS\n                        )"\n                        ').strip() + '\n')
        activate_script.chmod(st_mode)
    return self.ensure()

def _make_engine(self, f: FilePath | ReadCsvBuffer[bytes] | ReadCsvBuffer[str] | list | IO, engine: CSVEngine='c') -> ParserBase:
    mapping: dict[str, type[ParserBase]] = {'c': CParserWrapper, 'python': PythonParser, 'pyarrow': ArrowParserWrapper, 'python-fwf': FixedWidthFieldParser}
    if engine not in mapping:
        raise ValueError(f'Unknown engine: {engine} (valid options are {mapping.keys()})')
    if not isinstance(f, list):
        is_text = True
        mode = 'r'
        if <MASK>:
            is_text = False
            mode = 'rb'
        elif engine == 'c' and self.options.get('encoding', 'utf-8') == 'utf-8' and isinstance(stringify_path(f), str):
            is_text = False
            if 'b' not in mode:
                mode += 'b'
        self.handles = get_handle(f, mode, encoding=self.options.get('encoding', None), compression=self.options.get('compression', None), memory_map=self.options.get('memory_map', False), is_text=is_text, errors=self.options.get('encoding_errors', 'strict'), storage_options=self.options.get('storage_options', None))
        assert self.handles is not None
        f = self.handles.handle
    elif engine != 'python':
        msg = f'Invalid file path or buffer object type: {type(f)}'
        raise ValueError(msg)
    try:
        return mapping[engine](f, **self.options)
    except Exception:
        if self.handles is not None:
            self.handles.close()
        raise

def _maybe_convert_to_int_keys(convert_dates: dict, varlist: list[Hashable]) -> dict:
    new_dict = {}
    for (key, value) in convert_dates.items():
        if not convert_dates[key].startswith('%'):
            convert_dates[key] = '%' + value
        if key in varlist:
            new_dict[varlist.index(key)] = convert_dates[key]
        else:
            if <MASK>:
                raise ValueError('convert_dates key must be a column or an integer')
            new_dict[key] = convert_dates[key]
    return new_dict

def should_lower_cat_input(x) -> bool:
    if ir.is_storage_and_layout(x):
        (storage, _) = ir.as_storage_and_layout(x, freeze=False)
        return not ir.ConcatKernel.can_realize_into_without_copy(storage)
    if isinstance(x, (TensorBox, ir.StorageBox)):
        return should_lower_cat_input(unwrap_tensor(x))
    if <MASK>:
        return True
    return False

def standardize_weights(y, sample_weight=None, class_weight=None, sample_weight_mode=None):
    """Performs sample weight validation and standardization.

  Everything gets normalized to a single sample-wise (or timestep-wise)
  weight array. If both `sample_weight` and `class_weight` are provided,
  the weights are multiplied.

  Args:
      y: Numpy array or Tensor of model targets to be weighted.
      sample_weight: User-provided `sample_weight` argument.
      class_weight: User-provided `class_weight` argument.
      sample_weight_mode: One of `None` or `"temporal"`. `"temporal"` indicated
        that we expect 2D weight data that will be applied to the last 2
        dimensions of the targets (i.e. we are weighting timesteps, not
        samples).

  Returns:
      A numpy array of target weights, one entry per sample to weight.

  Raises:
      ValueError: In case of invalid user-provided arguments.
  """
    if isinstance(sample_weight, tuple):
        sample_weight = sample_weight[0]
    if sample_weight_mode is not None and sample_weight_mode != 'samplewise':
        if sample_weight_mode != 'temporal':
            raise ValueError('"sample_weight_mode should be None or "temporal". Found: ' + str(sample_weight_mode))
        if len(y.shape) < 3:
            raise ValueError('Found a sample_weight array for an input with shape ' + str(y.shape) + '. Timestep-wise sample weighting (use of sample_weight_mode="temporal") is restricted to outputs that are at least 3D, i.e. that have a time dimension.')
        if sample_weight is not None and len(sample_weight.shape) != 2:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + '. In order to use timestep-wise sample weighting, you should pass a 2D sample_weight array.')
    elif sample_weight is not None and len(sample_weight.shape) != 1:
        raise ValueError('Found a sample_weight array with shape {}. In order to use timestep-wise sample weights, you should specify sample_weight_mode="temporal" in compile(); founssd "{}" instead. If you just mean to use sample-wise weights, make sure your sample_weight array is 1D.'.format(sample_weight.shape, sample_weight_mode))
    if sample_weight is not None:
        if len(sample_weight.shape) > len(y.shape):
            raise ValueError('Found a sample_weight with shape' + str(sample_weight.shape) + '.Expected sample_weight with rank less than or equal to ' + str(len(y.shape)))
        if not tensor_util.is_tf_type(sample_weight) and y.shape[:sample_weight.ndim] != sample_weight.shape:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + ' for an input with shape ' + str(y.shape) + '. sample_weight cannot be broadcast.')
    class_sample_weight = None
    if isinstance(class_weight, dict):
        if len(y.shape) > 2:
            raise ValueError('`class_weight` not supported for 3+ dimensional targets.')
        if tensor_util.is_tf_type(y):
            keys = np.array(sorted(class_weight.keys()))
            values = np.array([class_weight[i] for i in keys])
            weight_vector = np.zeros(np.max(keys) + 1)
            weight_vector[:] = np.nan
            weight_vector[keys] = values
            y_classes = smart_cond.smart_cond(len(y.shape.as_list()) == 2 and backend.shape(y)[1] > 1, lambda : backend.argmax(y, axis=1), lambda : math_ops.cast(backend.reshape(y, (-1,)), dtypes.int64))
            class_sample_weight = array_ops.gather(weight_vector, y_classes)
            gen_array_ops.check_numerics(class_sample_weight, 'Invalid classes or class weights detected. NaN values indicate that an appropriate class weight could not be determined.')
            class_sample_weight = math_ops.cast(class_sample_weight, backend.floatx())
            if sample_weight is not None:
                sample_weight = math_ops.cast(tensor_conversion.convert_to_tensor_v2_with_dispatch(sample_weight), backend.floatx())
        else:
            y_classes = y
            if len(y.shape) == 2:
                if <MASK>:
                    y_classes = np.argmax(y, axis=1)
                elif y.shape[1] == 1:
                    y_classes = np.reshape(y, y.shape[0])
            class_sample_weight = numpy_compat.np_asarray([class_weight[cls] for cls in y_classes if cls in class_weight])
            if len(class_sample_weight) != len(y_classes):
                existing_classes = set(y_classes)
                existing_class_weight = set(class_weight.keys())
                raise ValueError('`class_weight` must contain all classes in the data. The classes %s exist in the data but not in `class_weight`.' % (existing_classes - existing_class_weight))
    if class_sample_weight is not None and sample_weight is not None:
        return class_sample_weight * sample_weight
    if sample_weight is not None:
        return sample_weight
    if class_sample_weight is not None:
        return class_sample_weight
    return None

@parameterized.parameters(dtypes_lib.float32, dtypes_lib.float64, dtypes_lib.int64, dtypes_lib.int32, dtypes_lib.complex64, dtypes_lib.complex128, dtypes_lib.bfloat16)
def testValues(self, dtype):
    ops_list = [(np.add, None, math_ops.segment_sum), (self._mean_cum_op, self._mean_reduce_op, math_ops.segment_mean), (np.ndarray.__mul__, None, math_ops.segment_prod), (np.minimum, None, math_ops.segment_min), (np.maximum, None, math_ops.segment_max)]
    complex_ops_list = [(np.add, None, math_ops.segment_sum), (np.ndarray.__mul__, None, math_ops.segment_prod), (self._mean_cum_op, self._mean_reduce_op, math_ops.segment_mean)]
    n = 10
    for shape in [[n, 1], [n, 2], [n, 3], [n, 32]]:
        indices = [i // 3 for i in range(n)]
        if <MASK>:
            curr_ops_list = complex_ops_list
        else:
            curr_ops_list = ops_list
        for use_gpu in [True, False]:
            with self.cached_session(use_gpu=use_gpu):
                (tf_x, np_x) = self._input(shape, dtype=dtype)
                for (np_op1, np_op2, tf_op) in curr_ops_list:
                    initial_value = 1 if tf_op is math_ops.segment_prod else 0
                    np_ans = self._segmentReduce(indices, np_x, np_op1, np_op2, initial_value=initial_value)
                    s = tf_op(data=tf_x, segment_ids=indices)
                    tf_ans = self.evaluate(s)
                    self.assertAllCloseAccordingToType(np_ans, tf_ans)
                    self.assertAllEqual(np_ans.shape[1:], tf_ans.shape[1:])

def repro_run(options: Any, exported_program: ExportedProgram, config_patches: Optional[dict[str, Any]]) -> None:
    from torch._inductor import _aoti_compile_and_package_inner
    (gm, args, kwargs) = repro_common(options, exported_program)
    from torch.cuda import synchronize
    _aoti_compile_and_package_inner(gm, args, kwargs, load_and_run=True, check_accuracy=options.accuracy, inductor_configs=config_patches)
    need_sync = False
    for arg in args:
        if <MASK>:
            need_sync = True
            break
    if need_sync:
        synchronize()

@contextlib.contextmanager
def git_config_guard(repo: GitRepo) -> Generator[None, None, None]:
    """Restores user.name and user.email global properties after context is finished"""
    user_email = repo._run_git('config', 'user.email')
    user_name = repo._run_git('config', 'user.name')
    try:
        yield
    finally:
        if user_email:
            repo._run_git('config', '--global', 'user.email', user_email)
        if <MASK>:
            repo._run_git('config', '--global', 'user.name', user_name)

def _update_qconfig_for_fusion(model: GraphModule, qconfig_mapping: QConfigMapping):
    """
    Update the QConfigMapping to account for fused modules such as LinearReLU.
    This assumes the QConfigMapping's attributes have already been converted to OrderedDicts.
    """
    object_type_dict = qconfig_mapping.object_type_qconfigs
    if len(object_type_dict) == 0:
        return qconfig_mapping
    modules = dict(model.named_modules())
    for node in model.graph.nodes:
        if node.op == 'call_module' and node.target in modules:
            maybe_fused_module = modules[str(node.target)]
            if <MASK>:
                continue
            ops = list(maybe_fused_module._modules.values())
            fused_qconfig = object_type_dict.get(type(ops[0]), None)
            for op in ops[1:]:
                if not qconfig_equals(object_type_dict.get(type(op), None), fused_qconfig):
                    raise LookupError('During fusion, we need to specify the same ' + f'qconfigs for all module types in {type(maybe_fused_module)} ' + f'offending type: {type(op)}')
            if fused_qconfig is not None:
                object_type_dict[type(maybe_fused_module)] = fused_qconfig

def gather_ops_or_named_saveables(self):
    """Looks up or creates SaveableObjects which don't have cached ops.

    Returns:
      A tuple of (
          existing_restore_ops: list,
          named_saveables: dict,
          python_positions: list,
          registered_savers: dict)
    """
    recorded_registered_saver = self.get_registered_saver_name()
    if not (self.object_proto.attributes or recorded_registered_saver):
        return ([], {}, [], {})
    existing_restore_ops = []
    named_saveables = {}
    python_positions = []
    registered_savers = collections.defaultdict(dict)
    saveable_factories = saveable_object_util.saveable_objects_from_trackable(self.trackable)
    saver_name = registration.get_registered_saver_name(self.trackable)
    if recorded_registered_saver:
        if not self.skip_restore:
            name = self.object_proto.registered_saver.object_name
            registered_savers[recorded_registered_saver][name] = self.trackable
    elif <MASK>:
        registered_savers[saver_name] = {self.object_proto.attributes[0].checkpoint_key: self.trackable}
    elif isinstance(self.trackable, python_state.PythonState):
        python_positions.append(self)
    elif saveable_factories.keys() == {trackable_utils.SERIALIZE_TO_TENSORS_NAME}:
        (existing_restore_ops, named_saveables) = self._create_serialize_to_tensor_saveable(saveable_factories)
    elif saveable_factories:
        (existing_restore_ops, named_saveables) = self._create_saveables_by_attribute_name(saveable_factories)
    else:
        for serialized_tensor in self.object_proto.attributes:
            self._checkpoint.unused_attributes.setdefault(self._proto_id, []).append(serialized_tensor.name)
    return (existing_restore_ops, named_saveables, python_positions, registered_savers)

def StructuredTensorSpec(shape, field_specs):
    """A placeholder for the old StructuredTensorSpec."""
    if not isinstance(field_specs, dict):
        raise TypeError('field_specs must be a dictionary.')
    for k in field_specs.keys():
        if not isinstance(k, str):
            raise TypeError('field_specs must be a dictionary with string keys.')
    for v in field_specs.values():
        if <MASK>:
            raise TypeError('field_specs must be a dictionary with TypeSpec values.')
    shape = dynamic_ragged_shape.DynamicRaggedShape.Spec._from_tensor_shape(tensor_shape.as_shape(shape), 0, dtypes.int32)
    rank = shape.rank
    if rank is None:
        raise TypeError("StructuredTensor's shape must have known rank.")
    for (k, v) in field_specs.items():
        field_shape_untruncated = _dynamic_ragged_shape_spec_from_spec(v)
        if field_shape_untruncated is None:
            raise ValueError(f'Cannot convert spec of {k}.')
        untruncated_rank = field_shape_untruncated.rank
        if untruncated_rank is not None and untruncated_rank < rank:
            raise ValueError(f'Rank of field {k} is {untruncated_rank}, but must be at least {rank}.')
        field_shape = field_shape_untruncated._truncate(rank)
        shape = shape._merge_with(field_shape)
    return StructuredTensor.Spec(_ragged_shape=shape, _fields=field_specs)

def _fit(vander_f, x, y, deg, rcond=None, full=False, w=None):
    """
    Helper function used to implement the ``<type>fit`` functions.

    Parameters
    ----------
    vander_f : function(array_like, int) -> ndarray
        The 1d vander function, such as ``polyvander``
    c1, c2
        See the ``<type>fit`` functions for more detail
    """
    x = np.asarray(x) + 0.0
    y = np.asarray(y) + 0.0
    deg = np.asarray(deg)
    if deg.ndim > 1 or deg.dtype.kind not in 'iu' or deg.size == 0:
        raise TypeError('deg must be an int or non-empty 1-D array of int')
    if deg.min() < 0:
        raise ValueError('expected deg >= 0')
    if x.ndim != 1:
        raise TypeError('expected 1D vector for x')
    if x.size == 0:
        raise TypeError('expected non-empty vector for x')
    if y.ndim < 1 or y.ndim > 2:
        raise TypeError('expected 1D or 2D array for y')
    if len(x) != len(y):
        raise TypeError('expected x and y to have same length')
    if deg.ndim == 0:
        lmax = deg
        order = lmax + 1
        van = vander_f(x, lmax)
    else:
        deg = np.sort(deg)
        lmax = deg[-1]
        order = len(deg)
        van = vander_f(x, lmax)[:, deg]
    lhs = van.T
    rhs = y.T
    if w is not None:
        w = np.asarray(w) + 0.0
        if w.ndim != 1:
            raise TypeError('expected 1D vector for w')
        if len(x) != len(w):
            raise TypeError('expected x and w to have same length')
        lhs = lhs * w
        rhs = rhs * w
    if rcond is None:
        rcond = len(x) * np.finfo(x.dtype).eps
    if issubclass(lhs.dtype.type, np.complexfloating):
        scl = np.sqrt((np.square(lhs.real) + np.square(lhs.imag)).sum(1))
    else:
        scl = np.sqrt(np.square(lhs).sum(1))
    scl[scl == 0] = 1
    (c, resids, rank, s) = np.linalg.lstsq(lhs.T / scl, rhs.T, rcond)
    c = (c.T / scl).T
    if deg.ndim > 0:
        if c.ndim == 2:
            cc = np.zeros((lmax + 1, c.shape[1]), dtype=c.dtype)
        else:
            cc = np.zeros(lmax + 1, dtype=c.dtype)
        cc[deg] = c
        c = cc
    if <MASK>:
        msg = 'The fit may be poorly conditioned'
        warnings.warn(msg, RankWarning, stacklevel=2)
    if full:
        return (c, [resids, rank, s, rcond])
    else:
        return c

def extract_pandas_array(values: ArrayLike, dtype: DtypeObj | None, ndim: int) -> tuple[ArrayLike, DtypeObj | None]:
    """
    Ensure that we don't allow NumpyExtensionArray / NumpyEADtype in internals.
    """
    if isinstance(values, ABCNumpyExtensionArray):
        values = values.to_numpy()
        if <MASK>:
            values = np.atleast_2d(values)
    if isinstance(dtype, NumpyEADtype):
        dtype = dtype.numpy_dtype
    return (values, dtype)

def _ExtractDefaultTypesAndAllowedTypes(op_def, default_type_attr_map, allowed_list_attr_map):
    """Extracts the `default_type_attr_map` and `allowed_list_attr_map`."""
    for attr_def in op_def.attr:
        if attr_def.type != 'type':
            continue
        key = attr_def.name
        if attr_def.HasField('default_value'):
            default_type_attr_map[key] = dtypes.as_dtype(attr_def.default_value.type)
        if <MASK>:
            allowed_list_attr_map[key] = attr_def.allowed_values.list.type

def calc_info(self):
    lib_dirs = self.get_lib_dirs()
    flame_libs = self.get_libs('libraries', self._lib_names)
    info = self.check_libs2(lib_dirs, flame_libs, [])
    if info is None:
        return
    extra_info = self.calc_extra_info()
    dict_append(info, **extra_info)
    if self.check_embedded_lapack(info):
        self.set_info(**info)
    else:
        blas_info = get_info('blas_opt')
        if not blas_info:
            return
        for key in blas_info:
            if isinstance(blas_info[key], list):
                info[key] = info.get(key, []) + blas_info[key]
            elif <MASK>:
                info[key] = info.get(key, ()) + blas_info[key]
            else:
                info[key] = info.get(key, '') + blas_info[key]
        if self.check_embedded_lapack(info):
            self.set_info(**info)

@classmethod
def require_stride1(cls, x: IRNode) -> IRNode:
    if is_storage_and_layout(x):
        if <MASK>:
            return x
        for stride in x.get_stride():
            if stride == 1:
                return x
    return cls.copy_input(x)

def formfield_for_manytomany(self, db_field, request, **kwargs):
    """
        Get a form Field for a ManyToManyField.
        """
    if not db_field.remote_field.through._meta.auto_created:
        return None
    db = kwargs.get('using')
    if 'widget' not in kwargs:
        autocomplete_fields = self.get_autocomplete_fields(request)
        if db_field.name in autocomplete_fields:
            kwargs['widget'] = AutocompleteSelectMultiple(db_field, self.admin_site, using=db)
        elif db_field.name in self.raw_id_fields:
            kwargs['widget'] = widgets.ManyToManyRawIdWidget(db_field.remote_field, self.admin_site, using=db)
        elif <MASK>:
            kwargs['widget'] = widgets.FilteredSelectMultiple(db_field.verbose_name, db_field.name in self.filter_vertical)
    if 'queryset' not in kwargs:
        queryset = self.get_field_queryset(db, db_field, request)
        if queryset is not None:
            kwargs['queryset'] = queryset
    form_field = db_field.formfield(**kwargs)
    if isinstance(form_field.widget, SelectMultiple) and form_field.widget.allow_multiple_selected and (not isinstance(form_field.widget, (CheckboxSelectMultiple, AutocompleteSelectMultiple))):
        msg = _('Hold down “Control”, or “Command” on a Mac, to select more than one.')
        help_text = form_field.help_text
        form_field.help_text = format_lazy('{} {}', help_text, msg) if help_text else msg
    return form_field

def _add_children_recreated_from_config(self, obj, proto, node_id):
    """Recursively records objects recreated from config."""
    if node_id in self._traversed_nodes_from_config:
        return
    parent_path = self._node_paths[node_id]
    self._traversed_nodes_from_config.add(node_id)
    obj._maybe_initialize_trackable()
    if isinstance(obj, base_layer.Layer) and (not obj.built):
        metadata = json_utils.decode(self._metadata[node_id].metadata)
        self._try_build_layer(obj, node_id, metadata.get('build_input_shape'))
    children = []
    for reference in proto.children:
        obj_child = obj._lookup_dependency(reference.local_name)
        children.append((obj_child, reference.node_id, reference.local_name))
    metric_list_node_id = self._search_for_child_node(node_id, [constants.KERAS_ATTR, 'layer_metrics'])
    if metric_list_node_id is not None and hasattr(obj, '_metrics'):
        obj_metrics = {m.name: m for m in obj._metrics}
        for reference in self._proto.nodes[metric_list_node_id].children:
            metric = obj_metrics.get(reference.local_name)
            if metric is not None:
                metric_path = '{}.layer_metrics.{}'.format(constants.KERAS_ATTR, reference.local_name)
                children.append((metric, reference.node_id, metric_path))
    for (obj_child, child_id, child_name) in children:
        child_proto = self._proto.nodes[child_id]
        if not isinstance(obj_child, trackable.Trackable):
            continue
        if child_proto.user_object.identifier in revived_types.registered_identifiers():
            setter = revived_types.get_setter(child_proto.user_object)
        elif obj_child._object_identifier in constants.KERAS_OBJECT_IDENTIFIERS:
            setter = _revive_setter
        else:
            setter = setattr
        if child_id in self.loaded_nodes:
            if self.loaded_nodes[child_id][0] is not obj_child:
                logging.warning('Looks like there is an object (perhaps variable or layer) that is shared between different layers/models. This may cause issues when restoring the variable values. Object: {}'.format(obj_child))
            continue
        if child_proto.WhichOneof('kind') == 'variable' and child_proto.variable.name:
            obj_child._handle_name = child_proto.variable.name + ':0'
        if <MASK>:
            setter = lambda *args: None
        child_path = '{}.{}'.format(parent_path, child_name)
        self._node_paths[child_id] = child_path
        self._add_children_recreated_from_config(obj_child, child_proto, child_id)
        self.loaded_nodes[child_id] = (obj_child, setter)

def _shard_dict_of_args(args_dict, args_chunk_spec, num_chunks):
    """
    Given a dictionary of args, and a dictionary of chunking specs, shard the
    args according to the chunking specs.

    Args:
        args_dict: Dictionary of args
        args_chunk_spec: Dictionary of chunking specs
        num_chunks: Number of chunks to shard the args into

    Returns:
        args_split: List of sharded args
    """
    if not args_dict:
        return [{} for _ in range(num_chunks)]
    assert len(args_dict) == len(args_chunk_spec), f'args_dict.keys() = {list(args_dict.keys())} args_chunk_spec.keys() = {list(args_chunk_spec.keys())}'
    assert args_chunk_spec is not None
    (values, tree_spec) = tree_flatten(args_dict)
    (chunk_specs, _) = tree_flatten(args_chunk_spec)
    split_sizes = []
    for (v, spec) in zip(values, chunk_specs, strict=True):
        if spec is _Replicate or isinstance(spec, _Replicate):
            split_sizes.append(num_chunks)
        elif <MASK>:
            assert isinstance(spec, TensorChunkSpec)
            split_sizes.append(v.size(spec.split_dim))
        elif isinstance(v, BlockMask):
            assert isinstance(spec, TensorChunkSpec)
            assert spec.split_dim == 0, 'BlockMask only supports split_dim=0'
            if v.kv_num_blocks.size(0) == 1:
                split_sizes.append(num_chunks)
            else:
                split_sizes.append(v.kv_num_blocks.size(0))
        else:
            raise ValueError(f'Unsupported chunk spec: {spec} and value: {v} combination.')
    result_num_chunks = min(*split_sizes, num_chunks)
    flat_split_results: list[Any] = [[] for _ in range(result_num_chunks)]
    for (v, spec) in zip(values, chunk_specs, strict=True):
        v_splits: Sequence[Any] = []
        if spec is _Replicate or isinstance(spec, _Replicate):
            v_splits = [v] * result_num_chunks
        elif isinstance(v, torch.Tensor):
            v_splits = _split_tensor(v, spec, result_num_chunks)
        elif isinstance(v, BlockMask):
            v_splits = _split_block_mask(v, result_num_chunks)
        else:
            raise ValueError(f'Unsupported chunk spec: {spec} and value: {v} combination.')
        for (_flat_split_result, _v_split) in zip(flat_split_results, v_splits, strict=True):
            _flat_split_result.append(_v_split)
    return [tree_unflatten(_flat_split_result, tree_spec) for _flat_split_result in flat_split_results]

def _package_aoti_files(archive_writer: PT2ArchiveWriter, aoti_files: Optional[AOTI_FILES], pickle_protocol: int=DEFAULT_PICKLE_PROTOCOL) -> None:
    if aoti_files is None:
        return
    if <MASK>:
        aoti_files = {'model': aoti_files}
    assert isinstance(aoti_files, dict)
    all_weights: dict[str, Weights] = {}
    weights_configs: dict[str, dict[str, Any]] = {}
    for (model_name, files) in aoti_files.items():
        num_so_files = 0
        weights_configs[model_name] = {}
        for file in files:
            if file == '':
                continue
            if isinstance(file, Weights):
                all_weights[model_name] = file
                continue
            if file.endswith('.so'):
                num_so_files += 1
                if num_so_files > 1:
                    raise RuntimeError(f'Multiple .so files found in {files}. You might need to clear your cache directory before calling aoti_compile again.')
            filename = os.path.basename(file)
            if filename.startswith(CUSTOM_OBJ_FILENAME_PREFIX):
                new_filepath = os.path.join(CONSTANTS_DIR, filename)
            else:
                new_filepath = os.path.join(AOTINDUCTOR_DIR, model_name, filename)
            logger.debug('Saving AOTI generated file %s to archive in %s', file, new_filepath)
            archive_writer.write_file(str(new_filepath), file)
    if len(all_weights) > 0:
        grouped_tensors: list[OrderedSet[tuple[str, str]]] = group_weights(all_weights)
        for (idx, group) in enumerate(grouped_tensors):
            filename = f'{WEIGHT_FILENAME_PREFIX}{idx}'
            (model_name, weight_name) = get_complete(group, all_weights)
            (complete_tensor, _) = all_weights[model_name].get_weight(weight_name)
            buffer = io.BytesIO()
            torch.save(complete_tensor, buffer, pickle_protocol=pickle_protocol)
            archive_writer.write_bytes(os.path.join(WEIGHTS_DIR, filename), buffer.getvalue())
            for (model_name, weight_name) in group:
                (_, w_property) = all_weights[model_name].get_weight(weight_name)
                weights_configs[model_name][weight_name] = (filename, w_property.shape, w_property.stride, w_property.offset)
        for (model_name, weights_config) in weights_configs.items():
            archive_writer.write_string(os.path.join(AOTINDUCTOR_DIR, model_name, 'weights_config.json'), json.dumps(weights_config))
            logger.debug('packaging weights_config for model %s', model_name)
            logger.debug(weights_config)

def _init_group(self, group, params_with_grad, grads, square_avgs, momentum_buffer_list, grad_avgs, state_steps):
    has_complex = False
    for p in group['params']:
        if p.grad is None:
            continue
        has_complex |= torch.is_complex(p)
        params_with_grad.append(p)
        if p.grad.is_sparse:
            raise RuntimeError('RMSprop does not support sparse gradients')
        grads.append(p.grad)
        state = self.state[p]
        if len(state) == 0:
            state['step'] = torch.zeros((), dtype=_get_scalar_dtype(), device=p.device) if group['capturable'] else torch.zeros((), dtype=_get_scalar_dtype())
            state['square_avg'] = torch.zeros_like(p, memory_format=torch.preserve_format)
            if <MASK>:
                state['momentum_buffer'] = torch.zeros_like(p, memory_format=torch.preserve_format)
            if group['centered']:
                state['grad_avg'] = torch.zeros_like(p, memory_format=torch.preserve_format)
        square_avgs.append(state['square_avg'])
        state_steps.append(state['step'])
        if group['momentum'] > 0:
            momentum_buffer_list.append(state['momentum_buffer'])
        if group['centered']:
            grad_avgs.append(state['grad_avg'])
    return has_complex

def _savez(file, args, kwds, compress, allow_pickle=True, pickle_kwargs=None):
    import zipfile
    if not hasattr(file, 'write'):
        file = os.fspath(file)
        if <MASK>:
            file = file + '.npz'
    namedict = kwds
    for (i, val) in enumerate(args):
        key = 'arr_%d' % i
        if key in namedict.keys():
            raise ValueError(f'Cannot use un-named variables and keyword {key}')
        namedict[key] = val
    if compress:
        compression = zipfile.ZIP_DEFLATED
    else:
        compression = zipfile.ZIP_STORED
    zipf = zipfile_factory(file, mode='w', compression=compression)
    try:
        for (key, val) in namedict.items():
            fname = key + '.npy'
            val = np.asanyarray(val)
            with zipf.open(fname, 'w', force_zip64=True) as fid:
                format.write_array(fid, val, allow_pickle=allow_pickle, pickle_kwargs=pickle_kwargs)
    finally:
        zipf.close()

def visit_Name(self, node):
    name = anno.getanno(node, anno.Basic.QN)
    if isinstance(node.ctx, gast.Load):
        types = self.types_in.types.get(name, None)
        if types is None:
            if name not in self.scope.bound or name in self.scope.nonlocals:
                if name in self.closure_types:
                    types = self.closure_types[name]
                else:
                    (types, value) = self.resolver.res_name(self.namespace, self.types_in.types, name)
                    if value is not None:
                        anno.setanno(node, anno.Static.VALUE, value)
    elif isinstance(node.ctx, gast.Param):
        f_is_local = self.scope.parent.parent is not None
        type_name = anno.getanno(node.annotation, anno.Basic.QN, None)
        types = self.resolver.res_arg(self.namespace, self.types_in.types, self.scope.function_name, name, type_name, f_is_local)
        if types is not None:
            self.new_symbols[name] = types
    elif <MASK>:
        if self.rtype is not None:
            self.new_symbols[name] = self.rtype
        types = self.rtype
    else:
        assert False, 'unknown ctx'
    if __debug__:
        self._check_set(types)
    return types

def add_field(self, field, private=False):
    if <MASK>:
        self.private_fields.append(field)
    elif field.is_relation and field.many_to_many:
        bisect.insort(self.local_many_to_many, field)
    else:
        bisect.insort(self.local_fields, field)
        self.setup_pk(field)
    if field.is_relation and hasattr(field.remote_field, 'model') and field.remote_field.model:
        try:
            field.remote_field.model._meta._expire_cache(forward=False)
        except AttributeError:
            pass
        self._expire_cache()
    else:
        self._expire_cache(reverse=False)

def __init__(self, tensors: Union[torch.Tensor, tuple[torch.Tensor, ...]]) -> None:
    self.tensors = (tensors,) if isinstance(tensors, torch.Tensor) else tensors
    if <MASK>:
        raise AssertionError('Expected tensors to be a tuple')
    self.prev_versions = tuple((t._version for t in self.tensors))

def _yield_outliers_checks(estimator):
    if hasattr(estimator, 'contamination'):
        yield check_outlier_contamination
    if hasattr(estimator, 'fit_predict'):
