        yield partial(check_outliers_train, readonly_memmap=True)
        yield check_classifier_data_not_an_array
    yield check_non_transformer_estimators_n_iter

def _compute_sizes(seq, scalar_type):
    MAX_DIMS = 128
    is_storage = _isStorage(seq)
    sizes = []
    while isinstance(seq, (list, tuple)):
        length = len(seq)
        if is_storage:
            length //= scalar_type.itemsize
        sizes.append(length)
        if <MASK>:
            raise ValueError(f"too many dimensions '{type(seq).__name__}'")
        if length == 0:
            break
        try:
            handle = seq[0]
        except Exception:
            raise ValueError(f"could not determine the shape of object type '{type(seq).__name__}'")
        seq = handle
    return sizes

def _quantile(self, qs: npt.NDArray[np.float64], interpolation: str) -> BaseMaskedArray:
    """
        Dispatch to quantile_with_mask, needed because we do not have
        _from_factorized.

        Notes
        -----
        We assume that all impacted cases are 1D-only.
        """
    res = quantile_with_mask(self._data, mask=self._mask, fill_value=np.nan, qs=qs, interpolation=interpolation)
    if self._hasna:
        if self.ndim == 2:
            raise NotImplementedError
        if self.isna().all():
            out_mask = np.ones(res.shape, dtype=bool)
            if <MASK>:
                res = np.zeros(res.shape, dtype=self.dtype.numpy_dtype)
        else:
            out_mask = np.zeros(res.shape, dtype=bool)
    else:
        out_mask = np.zeros(res.shape, dtype=bool)
    return self._maybe_mask_result(res, mask=out_mask)

def _validate_sdpa_input(query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, attn_mask: Optional[torch.Tensor]=None, dropout_p=0.0, is_causal=False, scale=None):
    if not isinstance(query, NestedTensor) or not isinstance(key, NestedTensor) or (not isinstance(value, NestedTensor)):
        raise ValueError(f'Expected query, key, and value to be nested tensors, but got query.is_nested: {query.is_nested}, key.is_nested: {key.is_nested}, and value.is_nested: {value.is_nested} instead.')
    if query.dtype != key.dtype or query.dtype != value.dtype:
        raise ValueError(f'Expected query, key, and value to have the same dtype, but got query.dtype: {query.dtype}, key.dtype: {key.dtype}, and value.dtype: {value.dtype} instead.')
    if query.device != key.device or query.device != value.device:
        raise ValueError(f'Expected query, key, and value to have the same device type, but got query.device: {query.device}, key.device: {key.device}, and value.device: {value.device} instead.')
    if query.dim() < 3 or key.dim() < 3 or value.dim() < 3:
        raise ValueError(f'Expected query, key, and value to all be  at least 3 dimensional, but got query.dim: {query.dim()}, key.dim: {key.dim()} and value.dim: {value.dim()} instead.')
    if query._ragged_idx != key._ragged_idx or query._ragged_idx != value._ragged_idx:
        raise ValueError(f'Expected query, key, and value to all be ragged on the same dimension, but got ragged dims {query._ragged_idx}, {key._ragged_idx}, and {value._ragged_idx}, respectively.')
    if <MASK>:
        raise ValueError('Masks are not yet supported!')
        if attn_mask.dtype != torch.bool and attn_mask.dtype != query.dtype:
            raise ValueError(f'Expected attn_mask dtype to be bool or to match query dtype, but got attn_mask.dtype: {attn_mask.dtype}, and query.dtype: {query.dtype} instead.')

def _compare_save_plans(plan: SavePlan, other_plan: SavePlan) -> bool:
    """
    Compare the two Save plans and return True if they are equal.

    Args:
        plan (SavePlan): First SavePlan to compare.
        other_plan (SavePlan): Second SavePlan to compare.

    Returns:
       True if the two plans are equal, False otherwise.
    """
    if plan.usable != other_plan.usable:
        return False
    if len(plan.items) != len(other_plan.items):
        return False
    for (plan_item, other_plan_item) in zip(plan.items, other_plan.items):
        if plan_item.type != other_plan_item.type:
            return False
        plan_metadata_index = plan_item.index
        other_plan_metadata_index = other_plan_item.index
        if <MASK>:
            return False
        tensor_data = plan_item.tensor_data
        other_tensor_data = other_plan_item.tensor_data
        if tensor_data and (not other_tensor_data) or (not tensor_data and other_tensor_data):
            return False
        if tensor_data and other_tensor_data:
            if tensor_data.size != other_tensor_data.size:
                return False
            chunk = tensor_data.chunk
            other_chunk = other_tensor_data.chunk
            if chunk and (not other_chunk) or (not chunk and other_chunk):
                return False
            if chunk and other_chunk:
                if chunk.offsets != other_chunk.offsets or chunk.sizes != other_chunk.sizes:
                    return False
    return True

def get_variable(self, var_store, name, shape=None, dtype=None, initializer=None, regularizer=None, reuse=None, trainable=None, collections=None, caching_device=None, partitioner=None, validate_shape=True, use_resource=None, custom_getter=None, constraint=None, synchronization=VariableSynchronization.AUTO, aggregation=VariableAggregation.NONE):
    """Gets an existing variable with this name or create a new one."""
    if regularizer is None:
        regularizer = self._regularizer
    if caching_device is None:
        caching_device = self._caching_device
    if partitioner is None:
        partitioner = self._partitioner
    if custom_getter is None:
        custom_getter = self._custom_getter
    if <MASK>:
        reuse = False
        use_resource = True
    else:
        if reuse is None:
            reuse = self._reuse
        if use_resource is None:
            use_resource = self._use_resource
    full_name = self.name + '/' + name if self.name else name
    with ops.name_scope(None, skip_on_eager=False):
        if dtype is not None and initializer is not None and (not callable(initializer)):
            init_dtype = ops.convert_to_tensor(initializer).dtype.base_dtype
            if init_dtype != dtype:
                raise ValueError("Initializer type '%s' and explicit dtype '%s' don't match." % (init_dtype, dtype))
        if initializer is None:
            initializer = self._initializer
        if constraint is None:
            constraint = self._constraint
        if dtype is None:
            dtype = self._dtype
        return var_store.get_variable(full_name, shape=shape, dtype=dtype, initializer=initializer, regularizer=regularizer, reuse=reuse, trainable=trainable, collections=collections, caching_device=caching_device, partitioner=partitioner, validate_shape=validate_shape, use_resource=use_resource, custom_getter=custom_getter, constraint=constraint, synchronization=synchronization, aggregation=aggregation)

@register_backend
@fake_tensor_unsupported
def tvm(gm: fx.GraphModule, example_inputs: list[torch.Tensor], *, options: Optional[MappingProxyType[str, Any]]=None) -> Callable[..., Any]:
    if options is None:
        options = MappingProxyType({'scheduler': None, 'trials': 20000, 'opt_level': 3})
    assert options is not None
    import tvm
    from tvm import relay
    from tvm.contrib import graph_executor
    jit_mod = torch.jit.trace(gm, example_inputs)
    device = device_from_inputs(example_inputs)
    shape_list = [(f'inp_{idx}', i.shape) for (idx, i) in enumerate(example_inputs)]
    example_outputs = gm(*example_inputs)
    if len(example_outputs) == 0:
        log.warning('Explicitly fall back to eager due to zero output')
        return gm.forward
    (mod, params) = relay.frontend.from_pytorch(jit_mod, shape_list)
    if device.type == 'cuda':
        dev = tvm.cuda(device.index)
        target = tvm.target.cuda()
    else:
        dev = tvm.cpu(0)
        target = tvm.target.Target(llvm_target())
    scheduler = options.get('scheduler', None)
    if scheduler is None:
        scheduler = os.environ.get('TVM_SCHEDULER', None)
    trials = options.get('trials', 20000)
    opt_level = options.get('opt_level', 3)
    if scheduler == 'auto_scheduler':
        from tvm import auto_scheduler
        log_file = tempfile.NamedTemporaryFile()
        if not os.path.exists(log_file):
            (tasks, task_weights) = auto_scheduler.extract_tasks(mod['main'], params, target)
            if len(tasks) != 0:
                tuner = auto_scheduler.TaskScheduler(tasks, task_weights)
                if not os.path.exists(log_file):
                    assert trials > 0
                    tune_option = auto_scheduler.TuningOptions(num_measure_trials=trials, measure_callbacks=[auto_scheduler.RecordToFile(log_file)], early_stopping=2000)
                    try:
                        tuner.tune(tune_option)
                    except Exception:
                        if <MASK>:
                            os.unlink(log_file)
                        raise
        with auto_scheduler.ApplyHistoryBest(log_file):
            with tvm.transform.PassContext(opt_level=opt_level, config={'relay.backend.use_auto_scheduler': True}):
                lib = relay.build(mod, target=target, params=params)
    elif scheduler == 'meta_schedule':
        from tvm import meta_schedule as ms
        with tempfile.TemporaryDirectory() as work_dir:
            if device.type != 'cuda':
                target = tvm.target.Target(f'{llvm_target()} --num-cores {ms.utils.cpu_count(logical=False)}')
            assert trials > 0
            database = ms.relay_integration.tune_relay(mod=mod, target=target, work_dir=work_dir, max_trials_global=trials, num_trials_per_iter=64, params=params, strategy='evolutionary', opt_level=opt_level)
            lib = ms.relay_integration.compile_relay(database=database, mod=mod, target=target, params=params, opt_level=opt_level)
    elif scheduler == 'default' or not scheduler:
        with tvm.transform.PassContext(opt_level=opt_level):
            lib = relay.build(mod, target=target, params=params)
    else:
        raise NotImplementedError("This tuning option is invalid/not implemented for torchdynamo's TVM-related backend. There are three available options: default, auto_scheduler and meta_schedule.")
    m = graph_executor.GraphModule(lib['default'](dev))

    def to_torch_tensor(nd_tensor: tvm.nd.array) -> torch.Tensor:
        """A helper function to transfer a NDArray to torch.tensor."""
        if nd_tensor.dtype == 'bool':
            return torch.from_numpy(nd_tensor.numpy())
        return torch.utils.dlpack.from_dlpack(nd_tensor.to_dlpack())

    def to_tvm_tensor(torch_tensor: torch.Tensor) -> tvm.nd.array:
        """A helper function to transfer a torch.tensor to NDArray."""
        if torch_tensor.dtype == torch.bool:
            return tvm.nd.array(torch_tensor.cpu().numpy())
        return tvm.nd.from_dlpack(torch_tensor)

    def exec_tvm(*i_args: torch.Tensor) -> list[torch.Tensor]:
        args = [a.contiguous() for a in i_args]
        (shape_info, _) = m.get_input_info()
        active_inputs = {name for (name, _) in shape_info.items()}
        for (idx, arg) in enumerate(args, 0):
            if arg.dim() != 0:
                if arg.requires_grad:
                    arg = arg.detach()
                inp_name = f'inp_{idx}'
                if inp_name not in active_inputs:
                    log.warning("input %s skipped as not found in tvm's runtime library", inp_name)
                    continue
                m.set_input(inp_name, to_tvm_tensor(arg))
        m.run()
        return [to_torch_tensor(m.get_output(i)) for i in range(m.get_num_outputs())]
    return exec_tvm

def _get_cell_value(self, cell) -> Scalar | NaTType:
    from odf.namespaces import OFFICENS
    if str(cell) == '#N/A':
        return np.nan
    cell_type = cell.attributes.get((OFFICENS, 'value-type'))
    if cell_type == 'boolean':
        if str(cell) == 'TRUE':
            return True
        return False
    if cell_type is None:
        return self.empty_value
    elif <MASK>:
        cell_value = float(cell.attributes.get((OFFICENS, 'value')))
        val = int(cell_value)
        if val == cell_value:
            return val
        return cell_value
    elif cell_type == 'percentage':
        cell_value = cell.attributes.get((OFFICENS, 'value'))
        return float(cell_value)
    elif cell_type == 'string':
        return self._get_cell_string_value(cell)
    elif cell_type == 'currency':
        cell_value = cell.attributes.get((OFFICENS, 'value'))
        return float(cell_value)
    elif cell_type == 'date':
        cell_value = cell.attributes.get((OFFICENS, 'date-value'))
        return pd.Timestamp(cell_value)
    elif cell_type == 'time':
        stamp = pd.Timestamp(str(cell))
        return cast(Scalar, stamp.time())
    else:
        self.close()
        raise ValueError(f'Unrecognized type {cell_type}')

def main() -> None:
    parser = argparse.ArgumentParser(description=f'Ruff linter. Linter code: {LINTER_CODE}. Use with RUFF-FIX to auto-fix issues.', fromfile_prefix_chars='@')
    parser.add_argument('--config', default=None, help='Path to the `pyproject.toml` or `ruff.toml` file to use for configuration')
    parser.add_argument('--explain', action='store_true', help='Explain a rule')
    parser.add_argument('--show-disable', action='store_true', help='Show how to disable a lint message')
    parser.add_argument('--timeout', default=90, type=int, help='Seconds to wait for ruff')
    parser.add_argument('--severity', action='append', help='map code to severity (e.g. `F401:advice`). This option can be used multiple times.')
    parser.add_argument('--no-fix', action='store_true', help='Do not suggest fixes')
    add_default_options(parser)
    args = parser.parse_args()
    logging.basicConfig(format='<%(threadName)s:%(levelname)s> %(message)s', level=logging.NOTSET if args.verbose else logging.DEBUG if len(args.filenames) < 1000 else logging.INFO, stream=sys.stderr)
    severities: dict[str, LintSeverity] = {}
    if <MASK>:
        for severity in args.severity:
            parts = severity.split(':', 1)
            assert len(parts) == 2, f'invalid severity `{severity}`'
            severities[parts[0]] = LintSeverity(parts[1])
    lint_messages = check_files(args.filenames, severities=severities, config=args.config, retries=args.retries, timeout=args.timeout, explain=args.explain, show_disable=args.show_disable)
    for lint_message in lint_messages:
        lint_message.display()
    if args.no_fix or not lint_messages:
        return
    files_with_lints = {lint.path for lint in lint_messages if lint.path is not None}
    with concurrent.futures.ThreadPoolExecutor(max_workers=os.cpu_count(), thread_name_prefix='Thread') as executor:
        futures = {executor.submit(check_file_for_fixes, path, config=args.config, retries=args.retries, timeout=args.timeout): path for path in files_with_lints}
        for future in concurrent.futures.as_completed(futures):
            try:
                for lint_message in future.result():
                    lint_message.display()
            except Exception:
                logging.critical('Failed at "%s".', futures[future])
                raise

def test_live_out_if_inside_except(self):

    def test_fn(x, a, b, c):
        if <MASK>:
            try:
                pass
            except:
                if b > 0:
                    x = b
        return x
    node = self._parse_and_analyze(test_fn)
