def populate(self, installed_apps=None):
    """
        Load application configurations and models.

        Import each application module and then each model module.

        It is thread-safe and idempotent, but not reentrant.
        """
    if self.ready:
        return
    with self._lock:
        if self.ready:
            return
        if self.loading:
            raise RuntimeError("populate() isn't reentrant")
        self.loading = True
        for entry in installed_apps:
            if isinstance(entry, AppConfig):
                app_config = entry
            else:
                app_config = AppConfig.create(entry)
            if <MASK>:
                raise ImproperlyConfigured("Application labels aren't unique, duplicates: %s" % app_config.label)
            self.app_configs[app_config.label] = app_config
            app_config.apps = self
        counts = Counter((app_config.name for app_config in self.app_configs.values()))
        duplicates = [name for (name, count) in counts.most_common() if count > 1]
        if duplicates:
            raise ImproperlyConfigured("Application names aren't unique, duplicates: %s" % ', '.join(duplicates))
        self.apps_ready = True
        for app_config in self.app_configs.values():
            app_config.import_models()
        self.clear_cache()
        self.models_ready = True
        for app_config in self.get_app_configs():
            app_config.ready()
        self.ready = True
        self.ready_event.set()

def synthesize_comparison(cls, name: str, allow_eq: bool, raise_on_none: bool, inner: list[str]) -> ParsedDef:
    body = []
    for field in dataclasses.fields(cls):
        if <MASK>:
            continue
        body.extend([f'val1 = self.{field.name}', f'val2 = other.{field.name}'])
        body.extend(inner if not is_optional(field.type) else ['if val1 is not None and val2 is not None:', *['  ' + line for line in inner], 'elif (val1 is None) != (val2 is None):', f"  raise TypeError('Cannot compare {cls.__name__} with None')" if raise_on_none else '  return False'])
    body.append(f'return {allow_eq}')
    return compose_fn(cls, name, body, signature=f'(self, other: {cls.__name__}) -> bool')

@doc(ExtensionArray.factorize)
def factorize(self, use_na_sentinel: bool=True) -> tuple[np.ndarray, ExtensionArray]:
    null_encoding = 'mask' if use_na_sentinel else 'encode'
    data = self._pa_array
    if <MASK>:
        if null_encoding == 'encode':
            data = data.cast(data.type.value_type)
            encoded = data.dictionary_encode(null_encoding=null_encoding)
        else:
            encoded = data
    else:
        encoded = data.dictionary_encode(null_encoding=null_encoding)
    if encoded.length() == 0:
        indices = np.array([], dtype=np.intp)
        uniques = self._from_pyarrow_array(pa.chunked_array([], type=encoded.type.value_type))
    else:
        combined = encoded.combine_chunks()
        pa_indices = combined.indices
        if pa_indices.null_count > 0:
            pa_indices = pc.fill_null(pa_indices, -1)
        indices = pa_indices.to_numpy(zero_copy_only=False, writable=True).astype(np.intp, copy=False)
        uniques = self._from_pyarrow_array(combined.dictionary)
    return (indices, uniques)

def swap_module(mod, mapping, custom_module_class_mapping, use_precomputed_fake_quant=False):
    """Swaps the module if it has a quantized counterpart and it has an
    `observer` attached.

    Args:
        mod: input module
        mapping: a dictionary that maps from nn module to nnq module

    Return:
        The corresponding quantized module of `mod`
    """
    new_mod = mod
    if hasattr(mod, 'qconfig') and mod.qconfig is not None:
        swapped = False
        if type_before_parametrizations(mod) in custom_module_class_mapping:
            new_mod = custom_module_class_mapping[type_before_parametrizations(mod)].from_observed(mod)
            swapped = True
        elif type_before_parametrizations(mod) in mapping:
            qmod = mapping[type_before_parametrizations(mod)]
            if hasattr(qmod, '_IS_REFERENCE') and qmod._IS_REFERENCE:
                assert mod.qconfig is not None
                weight_post_process = mod.qconfig.weight()
                weight_post_process(mod.weight)
                weight_qparams = get_qparam_dict(weight_post_process)
                new_mod = qmod.from_float(mod, weight_qparams)
            else:
                sig = inspect.signature(qmod.from_float)
                if 'use_precomputed_fake_quant' in sig.parameters:
                    new_mod = qmod.from_float(mod, use_precomputed_fake_quant=use_precomputed_fake_quant)
                else:
                    new_mod = qmod.from_float(mod)
            swapped = True
        if swapped:
            for pre_hook_fn in mod._forward_pre_hooks.values():
                new_mod.register_forward_pre_hook(pre_hook_fn)
            for hook_fn in mod._forward_hooks.values():
                if hook_fn is not _observer_forward_hook:
                    new_mod.register_forward_hook(hook_fn)
            devices = _get_unique_devices_(mod)
            assert len(devices) <= 1 or (len(devices) == 2 and torch.device('meta') in devices), f'swap_module only works with cpu or single-device CUDA modules, but got devices {devices}'
            device = next(iter(devices)) if len(devices) > 0 else None
            if <MASK>:
                new_mod.to(device)
    return new_mod

def collect(self, objs, source=None, nullable=False, collect_related=True, source_attr=None, reverse_dependency=False, keep_parents=False, fail_on_restricted=True):
    """
        Add 'objs' to the collection of objects to be deleted as well as all
        parent instances. 'objs' must be a homogeneous iterable collection of
        model instances (e.g. a QuerySet). If 'collect_related' is True,
        related objects will be handled by their respective on_delete handler.

        If the call is the result of a cascade, 'source' should be the model
        that caused it and 'nullable' should be set to True, if the relation
        can be null.

        If 'reverse_dependency' is True, 'source' will be deleted before the
        current model, rather than after. (Needed for cascading to parent
        models, the one case in which the cascade follows the forwards
        direction of an FK rather than the reverse direction.)

        If 'keep_parents' is True, data of parent model's will be not deleted.

        If 'fail_on_restricted' is False, error won't be raised even if it's
        prohibited to delete such objects due to RESTRICT, that defers
        restricted object checking in recursive calls where the top-level call
        may need to collect more objects to determine whether restricted ones
        can be deleted.
        """
    if self.can_fast_delete(objs):
        self.fast_deletes.append(objs)
        return
    new_objs = self.add(objs, source, nullable, reverse_dependency=reverse_dependency)
    if not new_objs:
        return
    model = new_objs[0].__class__
    if not keep_parents:
        concrete_model = model._meta.concrete_model
        for ptr in concrete_model._meta.parents.values():
            if ptr:
                parent_objs = [getattr(obj, ptr.name) for obj in new_objs]
                self.collect(parent_objs, source=model, source_attr=ptr.remote_field.related_name, collect_related=False, reverse_dependency=True, fail_on_restricted=False)
    if not collect_related:
        return
    model_fast_deletes = defaultdict(list)
    protected_objects = defaultdict(list)
    for related in get_candidate_relations_to_delete(model._meta):
        if keep_parents and related.model._meta.concrete_model in model._meta.all_parents:
            continue
        field = related.field
        on_delete = field.remote_field.on_delete
        if on_delete in SKIP_COLLECTION:
            if self.force_collection and (forced_on_delete := getattr(on_delete, 'forced_collector', None)):
                on_delete = forced_on_delete
            else:
                continue
        related_model = related.related_model
        if self.can_fast_delete(related_model, from_field=field):
            model_fast_deletes[related_model].append(field)
            continue
        batches = self.get_del_batches(new_objs, [field])
        for batch in batches:
            sub_objs = self.related_objects(related_model, [field], batch)
            if not (sub_objs.query.select_related or self._has_signal_listeners(related_model)):
                referenced_fields = set(chain.from_iterable(((rf.attname for rf in rel.field.foreign_related_fields) for rel in get_candidate_relations_to_delete(related_model._meta))))
                sub_objs = sub_objs.only(*tuple(referenced_fields))
            if getattr(on_delete, 'lazy_sub_objs', False) or sub_objs:
                try:
                    on_delete(self, field, sub_objs, self.using)
                except ProtectedError as error:
                    key = "'%s.%s'" % (field.model.__name__, field.name)
                    protected_objects[key] += error.protected_objects
    if <MASK>:
        raise ProtectedError('Cannot delete some instances of model %r because they are referenced through protected foreign keys: %s.' % (model.__name__, ', '.join(protected_objects)), set(chain.from_iterable(protected_objects.values())))
    for (related_model, related_fields) in model_fast_deletes.items():
        batches = self.get_del_batches(new_objs, related_fields)
        for batch in batches:
            sub_objs = self.related_objects(related_model, related_fields, batch)
            self.fast_deletes.append(sub_objs)
    for field in model._meta.private_fields:
        if hasattr(field, 'bulk_related_objects'):
            sub_objs = field.bulk_related_objects(new_objs, self.using)
            self.collect(sub_objs, source=model, nullable=True, fail_on_restricted=False)
    if fail_on_restricted:
        for (related_model, instances) in self.data.items():
            self.clear_restricted_objects_from_set(related_model, instances)
        for qs in self.fast_deletes:
            self.clear_restricted_objects_from_queryset(qs.model, qs)
        if self.restricted_objects.values():
            restricted_objects = defaultdict(list)
            for (related_model, fields) in self.restricted_objects.items():
                for (field, objs) in fields.items():
                    if objs:
                        key = "'%s.%s'" % (related_model.__name__, field.name)
                        restricted_objects[key] += objs
            if restricted_objects:
                raise RestrictedError('Cannot delete some instances of model %r because they are referenced through restricted foreign keys: %s.' % (model.__name__, ', '.join(restricted_objects)), set(chain.from_iterable(restricted_objects.values())))

@test_util.run_in_graph_and_eager_modes
