def _get_rocm_arch_flags(cflags: Optional[list[str]]=None) -> list[str]:
    has_gpu_rdc_flag = False
    if cflags is not None:
        has_custom_flags = False
        for flag in cflags:
            if 'amdgpu-target' in flag or 'offload-arch' in flag:
                has_custom_flags = True
            elif 'gpu-rdc' in flag:
                has_gpu_rdc_flag = True
        if has_custom_flags:
            return [] if has_gpu_rdc_flag else ['-fno-gpu-rdc']
    _archs = os.environ.get('PYTORCH_ROCM_ARCH', None)
    if not _archs:
        archFlags = torch._C._cuda_getArchFlags()
        if <MASK>:
            archs = archFlags.split()
        else:
            archs = []
    else:
        archs = _archs.replace(' ', ';').split(';')
    flags = [f'--offload-arch={arch}' for arch in archs]
    flags += [] if has_gpu_rdc_flag else ['-fno-gpu-rdc']
    return flags

def size_to_pt(self, in_val: str, em_pt: float | None=None, conversions: dict=UNIT_RATIOS) -> str:

    def _error() -> str:
        warnings.warn(f'Unhandled size: {in_val!r}', CSSWarning, stacklevel=find_stack_level())
        return self.size_to_pt('1!!default', conversions=conversions)
    match = re.match('^(\\S*?)([a-zA-Z%!].*)', in_val)
    if match is None:
        return _error()
    (val, unit) = match.groups()
    if val == '':
        val = 1
    else:
        try:
            val = float(val)
        except ValueError:
            return _error()
    while unit != 'pt':
        if <MASK>:
            if em_pt is None:
                unit = 'rem'
            else:
                val *= em_pt
                unit = 'pt'
            continue
        try:
            (unit, mul) = conversions[unit]
        except KeyError:
            return _error()
        val *= mul
    val = round(val, 5)
    if int(val) == val:
        size_fmt = f'{int(val):d}pt'
    else:
        size_fmt = f'{val:f}pt'
    return size_fmt

def create_arg(self, a: Argument) -> torch.fx.Node:
    if isinstance(a, torch.nn.Module):
        if a not in self.submodules:
            name_submodule = f'submodule_{len(self.submodules)}'
            self.root.add_module(name_submodule, a)
            self.submodules[a] = name_submodule
    elif isinstance(a, FakeTensor):
        if not hasattr(a, 'constant') or a.constant is None:
            raise ExportPassBaseError(f'Cannot add {a} to graph.')
        a = a.constant
    node = super().create_arg(a)
    if <MASK>:
        self.set_metadata(node, a)
        self.callback.on_attr(ProxyValue(a, node))
    return node

@normalizer
@linalg_errors
def eigvals(a: ArrayLike):
    a = _atleast_float_1(a)
    result = torch.linalg.eigvals(a)
    if <MASK>:
        result = result.real
    return result

def _list_connected_datapipes(scan_obj: DataPipe, only_datapipe: bool, cache: set[int]) -> list[DataPipe]:
    f = io.BytesIO()
    p = pickle.Pickler(f)
    if dill_available():
        from dill import Pickler as dill_Pickler
        d = dill_Pickler(f)
    else:
        d = None
    captured_connections = []

    def getstate_hook(ori_state):
        state = None
        if isinstance(ori_state, dict):
            state = {}
            for (k, v) in ori_state.items():
                if isinstance(v, (IterDataPipe, MapDataPipe, Collection)):
                    state[k] = v
        elif isinstance(ori_state, (tuple, list)):
            state = []
            for v in ori_state:
                if isinstance(v, (IterDataPipe, MapDataPipe, Collection)):
                    state.append(v)
        elif isinstance(ori_state, (IterDataPipe, MapDataPipe, Collection)):
            state = ori_state
        return state

    def reduce_hook(obj):
        if obj == scan_obj or id(obj) in cache:
            raise NotImplementedError
        else:
            captured_connections.append(obj)
            cache.add(id(obj))
            return (_stub_unpickler, ())
    datapipe_classes: tuple[type[DataPipe]] = (IterDataPipe, MapDataPipe)
    try:
        for cls in datapipe_classes:
            cls.set_reduce_ex_hook(reduce_hook)
            if <MASK>:
                cls.set_getstate_hook(getstate_hook)
        try:
            p.dump(scan_obj)
        except (pickle.PickleError, AttributeError, TypeError):
            if dill_available():
                d.dump(scan_obj)
            else:
                raise
    finally:
        for cls in datapipe_classes:
            cls.set_reduce_ex_hook(None)
            if only_datapipe:
                cls.set_getstate_hook(None)
        if dill_available():
            from dill import extend as dill_extend
            dill_extend(False)
    return captured_connections

def runtime_wrapper(compiled_fn: Callable[..., Any], inputs: Any, sizes: Any, scalars: Any, hooks: Any, packed_inputs: Any) -> tuple[Any, Any]:
    global in_compiled_autograd_region
    try:
        in_compiled_autograd_region = True
        if self.nan_checker:
            self.nan_checker.prep_with_inputs(inputs)
        filtered_sizes = []
        for (idx, integer) in enumerate(sizes):
            if idx in used_sizes_idx:
                if <MASK>:
                    filtered_sizes.append(torch.empty(0, integer))
                    torch._dynamo.maybe_mark_dynamic(filtered_sizes[-1], 1)
                else:
                    filtered_sizes.append(integer)
        for i in runtime_inputs_to_move:
            inputs[i] = inputs[i].pin_memory().cuda(non_blocking=True)
        with _disable(), make_compile_context(self.id):
            out = compiled_fn(inputs, filtered_sizes, scalars, hooks, packed_inputs)
            if self.nan_checker:
                self.nan_checker.check(out)
            return out
    finally:
        in_compiled_autograd_region = False

def _copy_trackable_to_cpu(self, object_map):
    """Implements checkpointing protocols for `Trackable`."""
    if self not in object_map:
        if <MASK>:
            object_map[self] = OwnedIterator(components=self._components, element_spec=self._element_spec)
        else:
            object_map[self] = OwnedIterator(dataset=self._dataset)
    serialized = self._serialize_to_tensors()
    object_map[self]._restore_from_tensors(serialized)

def _copy_trackable_to_cpu(self, object_map):
    """For implementing `Trackable`."""
    self._v._copy_trackable_to_cpu(object_map)
    if <MASK>:
        object_map[self] = CachingVariable(object_map[self._v])

def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if <MASK>:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if is_dict(ann):
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if value is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if ann is str:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if ann is Any:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if ann is torch.qscheme:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if maybe_script_class is not None:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

@raise_hard_error_if_graph_break(reason="Cond doesn't work unless it is captured completely with torch.compile.")
def _call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    from . import ListVariable, TensorVariable
    (args, kwargs) = LazyVariableTracker.realize_all((args, kwargs))
    for (i, k) in enumerate(['pred', 'true_fn', 'false_fn', 'operands']):
        if (v := kwargs.pop(k, None)):
            assert i == len(args), 'did not provide the right number of non-keyword args'
            args.append(v)
    if <MASK>:
        unimplemented(f'torch.cond: Got unexpected kwargs: {list(kwargs.keys())}')
    if len(args) != 4:
        unimplemented(f'Expected 4 arguments but got {len(args)}.\nUsage: cond(pred, true_fn, false_fn, operands)')
    (pred, true_fn, false_fn, operands) = args
    if type(args[0]) is ConstantVariable:
        warnings.warn('Pred is a Python constant. When used with torch.cond, it specializes on one of the branches. If you want torch.cond to preserve two branches, please make the predicate a boolean tensor or a SymBool.', UserWarning)
        if pred.as_python_constant():
            return true_fn.call_function(tx, operands.unpack_var_sequence(tx), {})
        else:
            return false_fn.call_function(tx, operands.unpack_var_sequence(tx), {})
    if type(pred) not in (ConstantVariable, TensorVariable, SymNodeVariable):
        unimplemented(f'Expected pred to be bool or a boolean tensor with single item but got {str(type(pred))} with original python type {str(pred.python_type())}.')
    if not isinstance(operands, (ListVariable, TupleVariable)):
        unimplemented(f'Expected operands to be a list/tuple but got {operands.python_type()}')
    operands_seq = operands.unpack_var_sequence(tx)
    if not only_consist_of(operands, (TensorVariable, ConstantVariable, SymNodeVariable)):
        unimplemented('Expect operands to be a tuple of pytrees that only consists of tensor leaves.')
    _check_supported_callable_arg(tx, true_fn, 'true_fn')
    _check_supported_callable_arg(tx, false_fn, 'false_fn')

    def speculate_branch(branch):
        ix = 1 if branch else 2
        ((ret_val, ret_spec), ret_graph, ret_lifted_freevars) = speculate_subgraph(tx, args[ix], operands_seq, {}, 'cond', source_target=self.value, should_flatten_outputs=True, remove_consts_from_outputs=False, supports_input_mutation=self.supports_input_mutation, supports_aliasing=self.supports_aliasing)
        if not only_consist_of(ret_val, (TensorVariable, ConstantVariable)):
            unimplemented('Expected branches to return a possibly nested pytree of tensors or constant ints but it consists of others.')
        for ret in ret_val.unpack_var_sequence(tx):
            if isinstance(ret, ConstantVariable) and ret.python_type() is not int:
                unimplemented(f'Expected branches to return a possibly nested pytree of tensors or constant ints but it consists of others {ret.python_type()}.')
        return (ret_val, ret_spec, ret_graph, ret_lifted_freevars)
    (true_r, true_spec, true_graph, true_lifted_freevars) = speculate_branch(True)
    true_nn_modules = dict(tx.output.nn_modules)
    (false_r, false_spec, false_graph, false_lifted_freevars) = speculate_branch(False)
    false_nn_modules = dict(tx.output.nn_modules)
    same_spec = _make_inlined(tx, pytree.TreeSpec.__eq__)(true_spec.treespec, false_spec.treespec)
    if not same_spec.as_python_constant():
        unimplemented('Expected branches to return the same pytree structure.')
    (true_graph, false_graph, true_shared, _false_shared, unique_true, unique_false) = _merge_graph_inputs(true_graph, true_lifted_freevars, 'true_branch', false_graph, false_lifted_freevars, 'false_branch')
    true_name = tx.output.install_subgraph('cond_true', torch.fx.GraphModule(true_nn_modules, true_graph))
    false_name = tx.output.install_subgraph('cond_false', torch.fx.GraphModule(false_nn_modules, false_graph))
    true_node = make_attr(tx, true_name)
    false_node = make_attr(tx, false_name)
    p_args = (pred.as_proxy(), true_node, false_node, tuple(true_shared + unique_true + unique_false))
    return _call_function_and_unflatten_output(tx, torch.ops.higher_order.cond, p_args, {}, None, true_spec)

@classmethod
def create(cls, entry):
    """
        Factory that creates an app config from an entry in INSTALLED_APPS.
        """
    app_config_class = None
    app_name = None
    app_module = None
    try:
        app_module = import_module(entry)
    except Exception:
        pass
    else:
        if module_has_submodule(app_module, APPS_MODULE_NAME):
            mod_path = '%s.%s' % (entry, APPS_MODULE_NAME)
            mod = import_module(mod_path)
            app_configs = [(name, candidate) for (name, candidate) in inspect.getmembers(mod, inspect.isclass) if issubclass(candidate, cls) and candidate is not cls and getattr(candidate, 'default', True)]
            if len(app_configs) == 1:
                app_config_class = app_configs[0][1]
            else:
                app_configs = [(name, candidate) for (name, candidate) in app_configs if getattr(candidate, 'default', False)]
                if len(app_configs) > 1:
                    candidates = [repr(name) for (name, _) in app_configs]
                    raise RuntimeError('%r declares more than one default AppConfig: %s.' % (mod_path, ', '.join(candidates)))
                elif len(app_configs) == 1:
                    app_config_class = app_configs[0][1]
        if app_config_class is None:
            app_config_class = cls
            app_name = entry
    if app_config_class is None:
        try:
            app_config_class = import_string(entry)
        except Exception:
            pass
    if <MASK>:
        (mod_path, _, cls_name) = entry.rpartition('.')
        if mod_path and cls_name[0].isupper():
            mod = import_module(mod_path)
            candidates = [repr(name) for (name, candidate) in inspect.getmembers(mod, inspect.isclass) if issubclass(candidate, cls) and candidate is not cls]
            msg = "Module '%s' does not contain a '%s' class." % (mod_path, cls_name)
            if candidates:
                msg += ' Choices are: %s.' % ', '.join(candidates)
            raise ImportError(msg)
        else:
            import_module(entry)
    if not issubclass(app_config_class, AppConfig):
        raise ImproperlyConfigured("'%s' isn't a subclass of AppConfig." % entry)
    if app_name is None:
        try:
            app_name = app_config_class.name
        except AttributeError:
            raise ImproperlyConfigured("'%s' must supply a name attribute." % entry)
    try:
        app_module = import_module(app_name)
    except ImportError:
        raise ImproperlyConfigured("Cannot import '%s'. Check that '%s.%s.name' is correct." % (app_name, app_config_class.__module__, app_config_class.__qualname__))
    return app_config_class(app_name, app_module)

@MemoizeWithCycleCheck
def analyze_kernel_mutations(functions: dict[str, dict[Intermediate, list[Op]]], fn_name: str, num_args: int) -> list[bool]:
    """
    Analyzes the graph to detect all sinks from a predefined list of sinks
    by using triton's MemWrite trait list. NOTE: What if triton exposed this?
    From each sink, it traverses the CFG backwards to identify all the input
    pointers that are mutated.
    """
    MUTATION_OPS = {'tt.store': [0], 'tt.atomic_cas': [0], 'tt.atomic_rmw': [0], 'tt.experimental_descriptor_store': [0], 'tt.experimental_tensormap_create': [0], 'tt.descriptor_store': [0]}
    UNKNOWN_OPS = {'tt.elementwise_inline_asm'}
    stack: list[Union[Param, Intermediate]] = []
    visited = set()
    ops = functions[fn_name]
    tma_stores = get_tma_stores(functions, fn_name)
    for op_list in ops.values():
        for op in op_list:
            if op.name in UNKNOWN_OPS:
                if op.name == 'tt.elementwise_inline_asm' and op.is_pure:
                    continue
                raise RuntimeError(f'ttir analysis hit an op we do not know how to analyze: {op.name}')
            if op.name == 'tt.experimental_tensormap_create':
                assert len(op.args) >= 2
                if op.args[0] in tma_stores:
                    stack.append(op.args[1])
            if op.name == 'tt.call':
                assert op.fn_call_name in functions
                mutations = analyze_kernel_mutations(functions, op.fn_call_name, len(op.args))
                stack.extend((arg for (arg, mutated) in zip(op.args, mutations) if mutated))
            else:
                stack.extend((op.args[idx] for idx in MUTATION_OPS.get(op.name, [])))
    mutated = [False] * num_args
    while stack:
        arg = stack.pop()
        if arg in visited:
            continue
        visited.add(arg)
        if isinstance(arg, Param):
            if arg.idx >= num_args:
                continue
            mutated[arg.idx] = True
        elif <MASK>:
            for op in ops[arg]:
                if op.name != 'tt.load':
                    stack.extend(op.args)
    return mutated

def build_operator_and_matrix(self, build_info, dtype, use_placeholder, ensure_self_adjoint_and_pd=False, diagonals_format='sequence'):
    shape = list(build_info.shape)
    diag = linear_operator_test_util.random_sign_uniform(shape[:-1], minval=4.0, maxval=6.0, dtype=dtype)
    subdiag = linear_operator_test_util.random_sign_uniform(shape[:-1], minval=1.0, maxval=2.0, dtype=dtype)
    if ensure_self_adjoint_and_pd:
        diag = math_ops.cast(math_ops.abs(diag), dtype=dtype)
        superdiag = math_ops.conj(subdiag)
        superdiag = manip_ops.roll(superdiag, shift=-1, axis=-1)
    else:
        superdiag = linear_operator_test_util.random_sign_uniform(shape[:-1], minval=1.0, maxval=2.0, dtype=dtype)
    matrix_diagonals = array_ops_stack.stack([superdiag, diag, subdiag], axis=-2)
    matrix = gen_array_ops.matrix_diag_v3(matrix_diagonals, k=(-1, 1), num_rows=-1, num_cols=-1, align='LEFT_RIGHT', padding_value=0.0)
    if diagonals_format == 'sequence':
        diagonals = [superdiag, diag, subdiag]
    elif diagonals_format == 'compact':
        diagonals = array_ops_stack.stack([superdiag, diag, subdiag], axis=-2)
    elif <MASK>:
        diagonals = matrix
    lin_op_diagonals = diagonals
    if use_placeholder:
        if diagonals_format == 'sequence':
            lin_op_diagonals = [array_ops.placeholder_with_default(d, shape=None) for d in lin_op_diagonals]
        else:
            lin_op_diagonals = array_ops.placeholder_with_default(lin_op_diagonals, shape=None)
    operator = linalg_lib.LinearOperatorTridiag(diagonals=lin_op_diagonals, diagonals_format=diagonals_format, is_self_adjoint=True if ensure_self_adjoint_and_pd else None, is_positive_definite=True if ensure_self_adjoint_and_pd else None)
    return (operator, matrix)

