def __init__(self) -> None:
    for (op, rule) in torch._inductor.utils.op_dtype_propagation_rules.items():
        fn = functools.partial(self.return_dtype, dtype=rule.override_return_dtype) if rule.override_return_dtype else functools.partial(self.op_dtype_rule, type_promotion_kind=rule.type_promotion_kind)
