    for op in torch._inductor.codegen.common.pointwise_overrides_data.values():
        if <MASK>:
            setattr(self, op.name, functools.partial(self.op_dtype_rule, type_promotion_kind=op.type_promotion_kind))
    for op in torch._inductor.utils.boolean_ops():
        if not hasattr(self, op):
            setattr(self, op, functools.partial(self.return_dtype, dtype=torch.bool))
    unimplemented_ops = OP_NAMES - OrderedSet(dir(self))
    torch._check(len(unimplemented_ops) == 0, lambda : f'Unimplemented dtype rule for ops: {unimplemented_ops}')

def __getattribute__(self, attr):
    if attr in ('setfield', 'getfield', 'dtype'):
        return nt.void.__getattribute__(self, attr)
    try:
        return nt.void.__getattribute__(self, attr)
    except AttributeError:
        pass
    fielddict = nt.void.__getattribute__(self, 'dtype').fields
    res = fielddict.get(attr, None)
    if <MASK>:
        obj = self.getfield(*res[:2])
        try:
            dt = obj.dtype
        except AttributeError:
            return obj
        if dt.names is not None:
            return obj.view((self.__class__, obj.dtype))
        return obj
    else:
        raise AttributeError(f"'record' object has no attribute '{attr}'")

def __mul__(self, other):
    other = as_expr(other)
    if isinstance(other, Expr):
        if self.op is other.op:
            if self.op in (Op.INTEGER, Op.REAL):
                return as_number(self.data[0] * other.data[0], max(self.data[1], other.data[1]))
            elif self.op is Op.COMPLEX:
                (r1, i1) = self.data
                (r2, i2) = other.data
                return as_complex(r1 * r2 - i1 * i2, r1 * i2 + r2 * i1)
            if self.op is Op.FACTORS:
                r = Expr(self.op, dict(self.data))
                for (k, v) in other.data.items():
                    _pairs_add(r.data, k, v)
                return normalize(r)
            elif self.op is Op.TERMS:
                r = Expr(self.op, {})
                for (t1, c1) in self.data.items():
                    for (t2, c2) in other.data.items():
                        _pairs_add(r.data, t1 * t2, c1 * c2)
                return normalize(r)
        if self.op is Op.COMPLEX and other.op in (Op.INTEGER, Op.REAL):
            return self * as_complex(other)
        elif other.op is Op.COMPLEX and self.op in (Op.INTEGER, Op.REAL):
            return as_complex(self) * other
        elif self.op is Op.REAL and other.op is Op.INTEGER:
            return self * as_real(other, kind=self.data[1])
        elif <MASK>:
            return as_real(self, kind=other.data[1]) * other
        if self.op is Op.TERMS:
            return self * as_terms(other)
        elif other.op is Op.TERMS:
            return as_terms(self) * other
        return as_factors(self) * as_factors(other)
    return NotImplemented

@wraps(f)
def wrapper(x: npt.NDArray, *args, **kwargs):
    keys = set(kwargs.keys())
    dim = kwargs.pop('dim', None)
    keepdim = kwargs.pop('keepdim', False)
    if 'dim' in keys:
        dim = tuple(dim) if isinstance(dim, Sequence) else dim
        if x.ndim == 0 and dim in {0, -1, (0,), (-1,)}:
            kwargs['axis'] = None
        else:
            kwargs['axis'] = dim
    if 'keepdim' in keys and supports_keepdims:
        kwargs['keepdims'] = keepdim
    if <MASK>:
        mask = kwargs.pop('mask')
        if mask is not None:
            assert mask.layout == torch.strided
            kwargs['where'] = mask.cpu().numpy()
    if 'identity' in keys:
        identity = kwargs.pop('identity')
        if identity is not None:
            if identity.dtype is torch.bfloat16:
                identity = identity.cpu().to(torch.float32)
            else:
                identity = identity.cpu()
            kwargs['initial'] = identity.numpy()
    result = f(x, *args, **kwargs)
    if keepdim and (not supports_keepdims) and (x.ndim > 0):
        dim = list(range(x.ndim)) if dim is None else dim
        result = np.expand_dims(result, dim)
    return result

def _interpret_code(self, code, ns, out, defs):
    __traceback_hide__ = True
    (name, pos) = (code[0], code[1])
    if name == 'py':
        self._exec(code[2], ns, pos)
    elif <MASK>:
        raise _TemplateContinue()
    elif name == 'break':
        raise _TemplateBreak()
    elif name == 'for':
        (vars, expr, content) = (code[2], code[3], code[4])
        expr = self._eval(expr, ns, pos)
        self._interpret_for(vars, expr, content, ns, out, defs)
    elif name == 'cond':
        parts = code[2:]
        self._interpret_if(parts, ns, out, defs)
    elif name == 'expr':
        parts = code[2].split('|')
        base = self._eval(parts[0], ns, pos)
        for part in parts[1:]:
            func = self._eval(part, ns, pos)
            base = func(base)
        out.append(self._repr(base, pos))
    elif name == 'default':
        (var, expr) = (code[2], code[3])
        if var not in ns:
            result = self._eval(expr, ns, pos)
            ns[var] = result
    elif name == 'inherit':
        expr = code[2]
        value = self._eval(expr, ns, pos)
        defs['__inherit__'] = value
    elif name == 'def':
        name = code[2]
        signature = code[3]
        parts = code[4]
        ns[name] = defs[name] = TemplateDef(self, name, signature, body=parts, ns=ns, pos=pos)
    elif name == 'comment':
        return
    else:
        assert 0, 'Unknown code: %r' % name

