    return not self.running_forwards_with_pending_backwards

def _check_list_filter_item(self, obj, item, label):
    """
        Check one item of `list_filter`, the three valid options are:
        1. 'field' -- a basic field filter, possibly w/ relationships (e.g.
           'field__rel')
        2. ('field', SomeFieldListFilter) - a field-based list filter class
        3. SomeListFilter - a non-field list filter class
        """
    from django.contrib.admin import FieldListFilter, ListFilter
    if callable(item) and (not isinstance(item, models.Field)):
        if <MASK>:
            return must_inherit_from(parent='ListFilter', option=label, obj=obj, id='admin.E113')
        elif issubclass(item, FieldListFilter):
            return [checks.Error("The value of '%s' must not inherit from 'FieldListFilter'." % label, obj=obj.__class__, id='admin.E114')]
        else:
            return []
    elif isinstance(item, (tuple, list)):
        (field, list_filter_class) = item
        if not _issubclass(list_filter_class, FieldListFilter):
            return must_inherit_from(parent='FieldListFilter', option='%s[1]' % label, obj=obj, id='admin.E115')
        else:
            return []
    else:
        field = item
        try:
            get_fields_from_path(obj.model, field)
        except (NotRelationField, FieldDoesNotExist):
            return [checks.Error("The value of '%s' refers to '%s', which does not refer to a Field." % (label, field), obj=obj.__class__, id='admin.E116')]
        else:
            return []

def _split_and_write(path: str, saved_model: saved_model_pb2.SavedModel, max_size: int, export_files: Sequence[str]):
    """Writes the .pb, .pbtxt and .cpb files for a SavedModel."""
    constants.debug_set_max_size(max_size)
    if <MASK>:
        output_path = f'{path}.pbtxt'
        file_io.write_string_to_file(output_path, str(saved_model))
        logging.info('  %s written', output_path)
    if 'pb' in export_files:
        output_path = f'{path}.pb'
        file_io.write_string_to_file(output_path, saved_model.SerializeToString())
        logging.info('  %s written', output_path)
    if 'cpb' in export_files:
        splitter = split_saved_model.SavedModelSplitter(saved_model)
        splitter.write(path)
        (chunks, _) = splitter.split()
        if len(chunks) > 1:
            logging.info('  %s.cpb written', path)
        else:
            raise RuntimeError('For some reason this graph was not chunked, so a .cpb file was not produced. Raising an error since this should not be the case.')

def _get_custom_pass_detail_unsafe(self, custom_pass: Any) -> Any | None:
    if not custom_pass:
        return None
    if isinstance(custom_pass, list):
        return [self._get_custom_pass_detail_unsafe(x) for x in custom_pass]
    if isinstance(custom_pass, str):
        return custom_pass
    if isinstance(custom_pass, CustomGraphPass):
        return custom_pass.uuid()
    if <MASK>:
        return None
    raise AssertionError(f'unknown config type: {str(type(custom_pass))}')

def _write_cells(self, cells: list[ExcelCell], sheet_name: str | None=None, startrow: int=0, startcol: int=0, freeze_panes: tuple[int, int] | None=None) -> None:
    """
        Write the frame cells using odf
        """
    from odf.table import Table, TableCell, TableRow
    from odf.text import P
    sheet_name = self._get_sheet_name(sheet_name)
    assert sheet_name is not None
    if sheet_name in self.sheets:
        wks = self.sheets[sheet_name]
    else:
        wks = Table(name=sheet_name)
        self.book.spreadsheet.addElement(wks)
    if validate_freeze_panes(freeze_panes):
        freeze_panes = cast(tuple[int, int], freeze_panes)
        self._create_freeze_panes(sheet_name, freeze_panes)
    for _ in range(startrow):
        wks.addElement(TableRow())
    rows: DefaultDict = defaultdict(TableRow)
    col_count: DefaultDict = defaultdict(int)
    for cell in sorted(cells, key=lambda cell: (cell.row, cell.col)):
        if not col_count[cell.row]:
            for _ in range(startcol):
                rows[cell.row].addElement(TableCell())
        for _ in range(cell.col - col_count[cell.row]):
            rows[cell.row].addElement(TableCell())
            col_count[cell.row] += 1
        (pvalue, tc) = self._make_table_cell(cell)
        rows[cell.row].addElement(tc)
        col_count[cell.row] += 1
        p = P(text=pvalue)
        tc.addElement(p)
    if <MASK>:
        for row_nr in range(max(rows.keys()) + 1):
            wks.addElement(rows[row_nr])

def _parse_func_attr_value(key, value):
    """Converts a python object to an attr_value_pb2.AttrValue object."""
    if isinstance(value, attr_value_pb2.AttrValue):
        return value
    elif isinstance(value, bool):
        return attr_value_pb2.AttrValue(b=value)
    elif <MASK>:
        return attr_value_pb2.AttrValue(i=value)
    elif isinstance(value, float):
        return attr_value_pb2.AttrValue(f=value)
    elif isinstance(value, (str, bytes)):
        return attr_value_pb2.AttrValue(s=compat.as_bytes(value))
    elif isinstance(value, list):
        list_value = attr_value_pb2.AttrValue.ListValue()
        for v in value:
            if isinstance(v, bool):
                list_value.b.append(v)
            elif isinstance(v, int):
                list_value.i.append(v)
            elif isinstance(v, float):
                list_value.f.append(v)
            elif isinstance(v, (str, bytes)):
                list_value.s.append(compat.as_bytes(v))
            else:
                raise ValueError(f'Attributes for {key} must be bool, int, float, or string. Got {type(v)}.')
        return attr_value_pb2.AttrValue(list=list_value)
    else:
        raise ValueError(f'Attribute {key} must be bool, int, float, string, list, or AttrValue. Got {type(value)}.')

def _generate_added_field(self, app_label, model_name, field_name):
    field = self.to_state.models[app_label, model_name].get_field(field_name)
    dependencies = [OperationDependency(app_label, model_name, field_name, OperationDependency.Type.REMOVE)]
    if <MASK>:
        dependencies.extend(self._get_dependencies_for_foreign_key(app_label, model_name, field, self.to_state))
    if field.generated:
        dependencies.extend(self._get_dependencies_for_generated_field(field))
    time_fields = (models.DateField, models.DateTimeField, models.TimeField)
    auto_fields = (models.AutoField, models.SmallAutoField, models.BigAutoField)
    preserve_default = field.null or field.has_default() or field.has_db_default() or field.many_to_many or (field.blank and field.empty_strings_allowed) or (isinstance(field, time_fields) and field.auto_now) or isinstance(field, auto_fields)
    if not preserve_default:
        field = field.clone()
        if isinstance(field, time_fields) and field.auto_now_add:
            field.default = self.questioner.ask_auto_now_add_addition(field_name, model_name)
        else:
            field.default = self.questioner.ask_not_null_addition(field_name, model_name)
    if field.unique and field.has_default() and callable(field.default):
        self.questioner.ask_unique_callable_default_addition(field_name, model_name)
    self.add_operation(app_label, operations.AddField(model_name=model_name, name=field_name, field=field, preserve_default=preserve_default), dependencies=dependencies)

def handle_merge(self, loader, conflicts):
    """
        Handles merging together conflicted migrations interactively,
        if it's safe; otherwise, advises on how to fix it.
        """
    if <MASK>:
        questioner = InteractiveMigrationQuestioner(prompt_output=self.log_output)
    else:
        questioner = MigrationQuestioner(defaults={'ask_merge': True})
    for (app_label, migration_names) in conflicts.items():
        merge_migrations = []
        for migration_name in migration_names:
            migration = loader.get_migration(app_label, migration_name)
            migration.ancestry = [mig for mig in loader.graph.forwards_plan((app_label, migration_name)) if mig[0] == migration.app_label]
            merge_migrations.append(migration)

        def all_items_equal(seq):
            return all((item == seq[0] for item in seq[1:]))
        merge_migrations_generations = zip(*(m.ancestry for m in merge_migrations))
        common_ancestor_count = sum((1 for common_ancestor_generation in takewhile(all_items_equal, merge_migrations_generations)))
        if not common_ancestor_count:
            raise ValueError('Could not find common ancestor of %s' % migration_names)
        for migration in merge_migrations:
            migration.branch = migration.ancestry[common_ancestor_count:]
            migrations_ops = (loader.get_migration(node_app, node_name).operations for (node_app, node_name) in migration.branch)
            migration.merged_operations = sum(migrations_ops, [])
        if self.verbosity > 0:
            self.log(self.style.MIGRATE_HEADING('Merging %s' % app_label))
            for migration in merge_migrations:
                self.log(self.style.MIGRATE_LABEL('  Branch %s' % migration.name))
                for operation in migration.merged_operations:
                    self.log('    %s' % operation.formatted_description())
        if questioner.ask_merge(app_label):
            numbers = [self.autodetector.parse_number(migration.name) for migration in merge_migrations]
            try:
                biggest_number = max((x for x in numbers if x is not None))
            except ValueError:
                biggest_number = 1
            subclass = type('Migration', (Migration,), {'dependencies': [(app_label, migration.name) for migration in merge_migrations]})
            parts = ['%04i' % (biggest_number + 1)]
            if self.migration_name:
                parts.append(self.migration_name)
            else:
                parts.append('merge')
                leaf_names = '_'.join(sorted((migration.name for migration in merge_migrations)))
                if len(leaf_names) > 47:
                    parts.append(get_migration_name_timestamp())
                else:
                    parts.append(leaf_names)
            migration_name = '_'.join(parts)
            new_migration = subclass(migration_name, app_label)
            writer = MigrationWriter(new_migration, self.include_header)
            if not self.dry_run:
                with open(writer.path, 'w', encoding='utf-8') as fh:
                    fh.write(writer.as_string())
                run_formatters([writer.path], stderr=self.stderr)
                if self.verbosity > 0:
                    self.log('\nCreated new merge migration %s' % writer.path)
                    if self.scriptable:
                        self.stdout.write(writer.path)
            elif self.verbosity == 3:
                self.log(self.style.MIGRATE_HEADING("Full merge migrations file '%s':" % writer.filename))
                self.log(writer.as_string())

def _as_tuple(inp, arg_name=None, fn_name=None):
    if <MASK>:
        return _as_tuple_nocheck(inp)
    is_inp_tuple = True
    if not isinstance(inp, tuple):
        inp = (inp,)
        is_inp_tuple = False
    for (i, el) in enumerate(inp):
        if not isinstance(el, torch.Tensor):
            if is_inp_tuple:
                raise TypeError(f'The {arg_name} given to {fn_name} must be either a Tensor or a tuple of Tensors but the value at index {i} has type {type(el)}.')
            else:
                raise TypeError(f'The {arg_name} given to {fn_name} must be either a Tensor or a tuple of Tensors but the given {arg_name} has type {type(el)}.')
    return (is_inp_tuple, inp)

def assign(fn, v, update_value, cross_replica):
    update_fn = lambda : getattr(v, fn)(update_value)
    if cross_replica:
        return update_fn()
    else:
        if <MASK>:
            update_fn = def_function.function(update_fn)
        return test_util.gather(distribution, distribution.run(update_fn))

def _build_element_shape(shape):
    """Converts shape to a format understood by list_ops for element_shape.

  If `shape` is already a `Tensor` it is returned as-is. We do not perform a
  type check here.

  If shape is None or a TensorShape with unknown rank, -1 is returned.

  If shape is a scalar, an int32 tensor with empty list is returned. Note we
  do directly return an empty list since ops.convert_to_tensor would convert it
  to a float32 which is not a valid type for element_shape.

  If shape is a sequence of dims, None's in the list are replaced with -1. We
  do not check the dtype of the other dims.

  Args:
    shape: Could be None, Tensor, TensorShape or a list of dims (each dim could
      be a None, scalar or Tensor).

  Returns:
    A None-free shape that can be converted to a tensor.
  """
    if isinstance(shape, tensor_lib.Tensor):
        return shape
    if isinstance(shape, tensor_shape.TensorShape):
        shape = shape.as_list() if shape else None
    if <MASK>:
        return -1
    if isinstance(shape, (np.ndarray, np.generic)) or not shape:
        return ops.convert_to_tensor(shape, dtype=dtypes.int32)

    def convert(val):
        if val is None:
            return -1
        if isinstance(val, tensor_lib.Tensor):
            return val
        if isinstance(val, tensor_shape.Dimension):
            return val.value if val.value is not None else -1
        return val
    return [convert(d) for d in shape]

def check(backend):
    if backend == dist.Backend.GLOO:
        return dist.is_gloo_available()
    if backend == dist.Backend.NCCL:
        return dist.is_nccl_available()
    if backend == dist.Backend.MPI:
        return dist.is_mpi_available()
    if backend == dist.Backend.UCC:
        return dist.is_ucc_available()
    if <MASK>:
        return True
    return False

def infer_arg_by_inputs(raw_keys, raw_args, idx, reused_args):
    """We try to infer raw_arg (i.e. raw_args[idx]) from remaining raw_args.
                This is particularly useful for jagged cases, where the dimension is often
                being passed in as an input."""
    target_arg = raw_args[idx]
    if <MASK>:
        return True
    for (i, (raw_key, raw_arg)) in enumerate(zip(raw_keys, raw_args)):
        if i == idx or not isinstance(raw_arg, IRNode):
            continue
        triton_input = ''
        if autotune_args and raw_key in autotune_args:
            triton_input = self.get_autotuning_input_name(autotune_args[raw_key])
        if triton_input == '':
            continue
        try:
            layout = raw_arg.get_layout()
            for (dim, s) in enumerate(layout.size):
                if s == target_arg:
                    reused_args[target_arg] = f'{triton_input}.shape[{dim}]'
                    return True
        except NotImplementedError:
            continue
    return False

def _split_and_write(path: str, saved_model: saved_model_pb2.SavedModel, max_size: int, export_files: Sequence[str]):
    """Writes the .pb, .pbtxt and .cpb files for a SavedModel."""
    constants.debug_set_max_size(max_size)
    if 'pbtxt' in export_files:
        output_path = f'{path}.pbtxt'
        file_io.write_string_to_file(output_path, str(saved_model))
        logging.info('  %s written', output_path)
    if 'pb' in export_files:
        output_path = f'{path}.pb'
        file_io.write_string_to_file(output_path, saved_model.SerializeToString())
        logging.info('  %s written', output_path)
    if <MASK>:
        splitter = split_saved_model.SavedModelSplitter(saved_model)
        splitter.write(path)
        (chunks, _) = splitter.split()
        if len(chunks) > 1:
            logging.info('  %s.cpb written', path)
        else:
            raise RuntimeError('For some reason this graph was not chunked, so a .cpb file was not produced. Raising an error since this should not be the case.')

def _trackable_children(self, save_type=base.SaveType.CHECKPOINT, **kwargs):
    self._check_external_modification()
    if self._non_append_mutation:
        raise ValueError(f"Unable to save the object {self} (a list wrapper constructed to track trackable TensorFlow objects). A list element was replaced (__setitem__, __setslice__), deleted (__delitem__, __delslice__), or moved (sort). In order to support restoration on object creation, tracking is exclusively for append-only data structures.\n\nIf you don't need this list checkpointed, wrap it in a non-trackable object; it will be subsequently ignored.")
    if self._external_modification:
        raise ValueError(f"Unable to save the object {self} (a list wrapper constructed to track trackable TensorFlow objects). The wrapped list was modified outside the wrapper (its final value was {self._storage}, its value when a checkpoint dependency was added was {self._last_wrapped_list_snapshot}), which breaks restoration on object creation.\n\nIf you don't need this list checkpointed, wrap it in a NoDependency object; it will be subsequently ignored.")
    children = super()._trackable_children(save_type, **kwargs)
    if <MASK>:
        children.update({str(key): value for (key, value) in enumerate(self) if _is_function(value)})
    return children

def setup(self, dtype, method, application, ncols, engine):
    if method in method_blocklist.get(dtype, {}):
        raise NotImplementedError
    if ncols != 1 and method in ['value_counts', 'unique']:
        raise NotImplementedError
    if application == 'transformation' and method in ['describe', 'head', 'tail', 'unique', 'value_counts', 'size']:
        raise NotImplementedError
    if engine == 'numba' and method in _numba_unsupported_methods or ncols > 1 or application == 'transformation' or (dtype == 'datetime'):
        raise NotImplementedError
    if method == 'describe':
        ngroups = 20
    elif method == 'skew':
        ngroups = 100
    else:
        ngroups = 1000
    size = ngroups * 2
    rng = np.arange(ngroups).reshape(-1, 1)
    rng = np.broadcast_to(rng, (len(rng), ncols))
    taker = np.random.randint(0, ngroups, size=size)
    values = rng.take(taker, axis=0)
    if dtype == 'int':
        key = np.random.randint(0, size, size=size)
    elif dtype in ('int16', 'uint'):
        key = np.random.randint(0, size, size=size, dtype=dtype)
    elif dtype == 'float':
        key = np.concatenate([np.random.random(ngroups) * 0.1, np.random.random(ngroups) * 10.0])
    elif <MASK>:
        key = ['foo'] * size
    elif dtype == 'datetime':
        key = date_range('1/1/2011', periods=size, freq='s')
    cols = [f'values{n}' for n in range(ncols)]
    df = DataFrame(values, columns=cols)
    df['key'] = key
    if len(cols) == 1:
        cols = cols[0]
    kwargs = {}
    if engine == 'numba':
        kwargs['engine'] = engine
    if application == 'transformation':
        self.as_group_method = lambda : df.groupby('key')[cols].transform(method, **kwargs)
        self.as_field_method = lambda : df.groupby(cols)['key'].transform(method, **kwargs)
    else:
        self.as_group_method = partial(getattr(df.groupby('key')[cols], method), **kwargs)
        self.as_field_method = partial(getattr(df.groupby(cols)['key'], method), **kwargs)

def assemble(instructions: list[Instruction], firstlineno: int) -> tuple[bytes, bytes]:
    """Do the opposite of dis.get_instructions()"""
    code: list[int] = []
    if sys.version_info >= (3, 11):
        (lnotab, update_lineno) = linetable_311_writer(firstlineno)
        num_ext = 0
        for (i, inst) in enumerate(instructions):
            if inst.opname == 'EXTENDED_ARG':
                inst_size = 1
                num_ext += 1
                for j in (1, 2, 3):
                    if instructions[i + j].opname != 'EXTENDED_ARG':
                        inst.positions = instructions[i + j].positions
                        break
            else:
                inst_size = instruction_size(inst) // 2 + num_ext
                num_ext = 0
            update_lineno(inst.positions, inst_size)
            num_ext = 0
            arg = inst.arg or 0
            code.extend((inst.opcode, arg & 255))
            for _ in range(instruction_size(inst) // 2 - 1):
                code.extend((0, 0))
    else:
        (lnotab, update_lineno, end) = linetable_writer(firstlineno)
        for inst in instructions:
            if <MASK>:
                update_lineno(inst.starts_line, len(code))
            arg = inst.arg or 0
            code.extend((inst.opcode, arg & 255))
        end(len(code))
    return (bytes(code), bytes(lnotab))

def __init__(self, *expressions, fields=(), name=None, db_tablespace=None, opclasses=(), condition=None, include=None):
    if opclasses and (not name):
        raise ValueError('An index must be named to use opclasses.')
    if not isinstance(condition, (NoneType, Q)):
        raise ValueError('Index.condition must be a Q instance.')
    if condition and (not name):
        raise ValueError('An index must be named to use condition.')
    if not isinstance(fields, (list, tuple)):
        raise ValueError('Index.fields must be a list or tuple.')
    if not isinstance(opclasses, (list, tuple)):
        raise ValueError('Index.opclasses must be a list or tuple.')
    if not expressions and (not fields):
        raise ValueError('At least one field or expression is required to define an index.')
    if expressions and fields:
        raise ValueError('Index.fields and expressions are mutually exclusive.')
    if expressions and (not name):
        raise ValueError('An index must be named to use expressions.')
    if expressions and opclasses:
        raise ValueError('Index.opclasses cannot be used with expressions. Use django.contrib.postgres.indexes.OpClass() instead.')
    if opclasses and len(fields) != len(opclasses):
        raise ValueError('Index.fields and Index.opclasses must have the same number of elements.')
    if fields and (not all((isinstance(field, str) for field in fields))):
        raise ValueError('Index.fields must contain only strings with field names.')
    if <MASK>:
        raise ValueError('A covering index must be named.')
    if not isinstance(include, (NoneType, list, tuple)):
        raise ValueError('Index.include must be a list or tuple.')
    self.fields = list(fields)
    self.fields_orders = [(field_name.removeprefix('-'), 'DESC' if field_name.startswith('-') else '') for field_name in self.fields]
    self.name = name or ''
    self.db_tablespace = db_tablespace
    self.opclasses = opclasses
    self.condition = condition
    self.include = tuple(include) if include else ()
    self.expressions = tuple((F(expression) if isinstance(expression, str) else expression for expression in expressions))

def _as_index(idx, need_scalar=True):
    """Helper function to parse idx as an index.

  Args:
    idx: index
    need_scalar: If idx needs to be a scalar value.

  Returns:
    A pair, (indx, bool). First one is the parsed index and can be a tensor,
    or scalar integer / Dimension. Second one is True if rank is known to be 0.

  Raises:
    IndexError: For incorrect indices.
  """
    if isinstance(idx, (numbers.Integral, tensor_shape.Dimension)):
        return (idx, True)
    data = asarray(idx)
    if data.dtype == dtypes.bool:
        if data.shape.ndims != 1:
            raise NotImplementedError('Need rank 1 for bool index %s' % idx)
        data = array_ops.where_v2(data)
        data = array_ops.reshape(data, [-1])
    if need_scalar and data.shape.rank not in (None, 0):
        raise IndexError(_SLICE_ERROR + ', got {!r}'.format(idx))
    np_dtype = data.dtype.as_numpy_dtype
    if <MASK>:
        raise IndexError(_SLICE_ERROR + ', got {!r}'.format(idx))
    if data.dtype not in (dtypes.int64, dtypes.int32):
        promoted_dtype = np.promote_types(np.int32, np_dtype)
        if promoted_dtype == np.int32:
            data = math_ops.cast(data, dtypes.int32)
        elif promoted_dtype == np.int64:
            data = math_ops.cast(data, dtypes.int64)
        else:
            raise IndexError(_SLICE_ERROR + ', got {!r}'.format(idx))
    return (data, data.shape.rank == 0)

def _gen_unsupported_methods_properties():
    tensor_attrs = set(filter(lambda x: x[0] != '_', dir(torch.Tensor)))
    tensor = torch.tensor([2])
    funcs_template = dedent('\n    def func(x):\n        return x.{op}()\n    ')
    deprecated_apis = {'volatile', 'resize', 'reinforce', 'new', 'name', 'map2_', 'has_names', 'grad_fn', 'resize_as'}
    tensor_attrs = tensor_attrs - deprecated_apis
    properties = []
    methods = []
    sorted_tensor_attrs = sorted(tensor_attrs, key=lambda x: x.lower())
    for attr in sorted_tensor_attrs:
        funcs_str = funcs_template.format(op=attr)
        scope: dict[str, Any] = {}
        execWrapper(funcs_str, globals(), scope)
        try:
            torch.jit.CompilationUnit(funcs_str)
        except Exception as e:
            if <MASK>:
                continue
            attr_repr = repr(getattr(tensor, attr))
            if 'bound method' in attr_repr or 'built-in method' in attr_repr:
                methods.append(attr)
            else:
                properties.append(attr)
    mapped_methods = ('\t*  :meth:`~torch.Tensor.' + x + '`' for x in methods)
    mapped_properties = ('\t*  :attr:`~torch.Tensor.' + x + '`' for x in properties)
    return ('\n'.join(mapped_methods), '\n'.join(mapped_properties))

def _execute(self, sql, params, *ignored_wrapper_args):
    if not apps.ready and (not apps.stored_app_configs):
        warnings.warn(self.APPS_NOT_READY_WARNING_MSG, category=RuntimeWarning)
    self.db.validate_no_broken_transaction()
    with self.db.wrap_database_errors:
        if <MASK>:
            return self.cursor.execute(sql)
        else:
            return self.cursor.execute(sql, params)

def dump_string(self):
    outputs: list[str] = []
    cells: list[tuple[str, dict[int, str]]] = []
    header_buffer = ''
    for col in self.cols:
        (header, rows) = col.materialize()
        header_buffer += header
        cells.append((header, dict(rows)))
    outputs.append(header_buffer)
    outputs.append(pad('', len(header_buffer), 0, '='))
    for line in self.source_range:
        row_buffer = ''
        for (header, rows) in cells:
            cell = rows.get(line)
            if <MASK>:
                row_buffer += pad('', len(header))
            else:
                row_buffer += cell
        outputs.append(row_buffer)
    return '\n'.join(outputs)

@csrf_protect_m
def changelist_view(self, request, extra_context=None):
    """
        The 'change list' admin view for this model.
        """
    from django.contrib.admin.views.main import ERROR_FLAG
    app_label = self.opts.app_label
    if not self.has_view_or_change_permission(request):
        raise PermissionDenied
    try:
        cl = self.get_changelist_instance(request)
    except IncorrectLookupParameters:
        if ERROR_FLAG in request.GET:
            return SimpleTemplateResponse('admin/invalid_setup.html', {'title': _('Database error')})
        return HttpResponseRedirect(request.path + '?' + ERROR_FLAG + '=1')
    action_failed = False
    selected = request.POST.getlist(helpers.ACTION_CHECKBOX_NAME)
    actions = self.get_actions(request)
    if actions and request.method == 'POST' and ('index' in request.POST) and ('_save' not in request.POST):
        if <MASK>:
            response = self.response_action(request, queryset=cl.get_queryset(request))
            if response:
                return response
            else:
                action_failed = True
        else:
            msg = _('Items must be selected in order to perform actions on them. No items have been changed.')
            self.message_user(request, msg, messages.WARNING)
            action_failed = True
    if actions and request.method == 'POST' and (helpers.ACTION_CHECKBOX_NAME in request.POST) and ('index' not in request.POST) and ('_save' not in request.POST):
        if selected:
            response = self.response_action(request, queryset=cl.get_queryset(request))
            if response:
                return response
            else:
                action_failed = True
    if action_failed:
        return HttpResponseRedirect(request.get_full_path())
    formset = cl.formset = None
    if request.method == 'POST' and cl.list_editable and ('_save' in request.POST):
        if not self.has_change_permission(request):
            raise PermissionDenied
        FormSet = self.get_changelist_formset(request)
        modified_objects = self._get_list_editable_queryset(request, FormSet.get_default_prefix())
        formset = cl.formset = FormSet(request.POST, request.FILES, queryset=modified_objects)
        if formset.is_valid():
            changecount = 0
            with transaction.atomic(using=router.db_for_write(self.model)):
                for form in formset.forms:
                    if form.has_changed():
                        obj = self.save_form(request, form, change=True)
                        self.save_model(request, obj, form, change=True)
                        self.save_related(request, form, formsets=[], change=True)
                        change_msg = self.construct_change_message(request, form, None)
                        self.log_change(request, obj, change_msg)
                        changecount += 1
            if changecount:
                msg = ngettext('%(count)s %(name)s was changed successfully.', '%(count)s %(name)s were changed successfully.', changecount) % {'count': changecount, 'name': model_ngettext(self.opts, changecount)}
                self.message_user(request, msg, messages.SUCCESS)
            return HttpResponseRedirect(request.get_full_path())
    elif cl.list_editable and self.has_change_permission(request):
        FormSet = self.get_changelist_formset(request)
        formset = cl.formset = FormSet(queryset=cl.result_list)
    if formset:
        media = self.media + formset.media
    else:
        media = self.media
    if actions:
        action_form = self.action_form(auto_id=None)
        action_form.fields['action'].choices = self.get_action_choices(request)
        media += action_form.media
    else:
        action_form = None
    selection_note_all = ngettext('%(total_count)s selected', 'All %(total_count)s selected', cl.result_count)
    context = {**self.admin_site.each_context(request), 'module_name': str(self.opts.verbose_name_plural), 'selection_note': _('0 of %(cnt)s selected') % {'cnt': len(cl.result_list)}, 'selection_note_all': selection_note_all % {'total_count': cl.result_count}, 'title': cl.title, 'subtitle': None, 'is_popup': cl.is_popup, 'to_field': cl.to_field, 'cl': cl, 'media': media, 'has_add_permission': self.has_add_permission(request), 'opts': cl.opts, 'action_form': action_form, 'actions_on_top': self.actions_on_top, 'actions_on_bottom': self.actions_on_bottom, 'actions_selection_counter': self.actions_selection_counter, 'preserved_filters': self.get_preserved_filters(request), **(extra_context or {})}
    request.current_app = self.admin_site.name
    return TemplateResponse(request, self.change_list_template or ['admin/%s/%s/change_list.html' % (app_label, self.opts.model_name), 'admin/%s/change_list.html' % app_label, 'admin/change_list.html'], context)

