@parameterized.named_parameters(('NoTensor', 'NO_TENSOR'), ('CurtHealth', 'CURT_HEALTH'), ('ConciseHealth', 'CONCISE_HEALTH'), ('FullHealth', 'FULL_HEALTH'), ('Shape', 'SHAPE'), ('FullTensor', 'FULL_TENSOR'))
def testMultiThreadedExecutionWithSameSetting(self, tensor_debug_mode):
    """Dumping from multiple threads using the same setting."""
    writer = dumping_callback.enable_dump_debug_info(self.dump_root, tensor_debug_mode=tensor_debug_mode)
    x = variables.Variable(10.0, dtype=dtypes.float32)
    y = variables.Variable(3.0, dtype=dtypes.float32)

    @def_function.function
    def increase_x():
        return x.assign_add(y * 2.0)
    increase_x()
    num_threads = 3
    threads = []
    for _ in range(num_threads):
        threads.append(threading.Thread(target=increase_x))
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    self.assertAllClose(x.read_value(), 34.0)
    writer.FlushNonExecutionFiles()
    writer.FlushExecutionFiles()
    with debug_events_reader.DebugDataReader(self.dump_root) as reader:
        reader.update()
        exec_digests = reader.executions(digest=True)
        prev_wall_time = 1
        for exec_digest in exec_digests:
            self.assertGreaterEqual(exec_digest.wall_time, prev_wall_time)
            prev_wall_time = exec_digest.wall_time
        graph_exec_traces = reader.graph_execution_traces()
        executed_op_types = [trace.op_type for trace in graph_exec_traces]
        self.assertEqual(executed_op_types.count('Mul'), 1 + num_threads)
        self.assertEqual(executed_op_types.count('ReadVariableOp'), 2 * (1 + num_threads))
        for trace in graph_exec_traces:
            self.assertEqual(trace.output_slot, 0)
    tensor_values = [reader.graph_execution_trace_to_tensor_value(trace) for trace in graph_exec_traces]
    if tensor_debug_mode == 'NO_TENSOR':
        for tensor_value in tensor_values:
            self.assertAllEqual(tensor_value, [])
    elif tensor_debug_mode == 'CURT_HEALTH':
        for trace in graph_exec_traces:
            tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
            self.assertAllClose(trace.debug_tensor_value, [tensor_id, 0])
    elif <MASK>:
        for trace in graph_exec_traces:
            tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
            self.assertAllClose(trace.debug_tensor_value, [tensor_id, 1, 0, 0, 0])
    elif tensor_debug_mode == 'FULL_HEALTH':
        for trace in graph_exec_traces:
            tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
            self.assertAllClose(trace.debug_tensor_value, [tensor_id, -1, 1, 0, 1, 0, 0, 0, 0, 0, 1])
    elif tensor_debug_mode == 'SHAPE':
        for trace in graph_exec_traces:
            if trace.op_type == 'Mul':
                tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
                mul_value = reader.graph_execution_trace_to_tensor_value(trace)
                self.assertAllClose(mul_value, [tensor_id, 1, 0, 1, 0, 0, 0, 0, 0, 0])
    elif tensor_debug_mode == 'FULL_TENSOR':
        mul_values = [reader.graph_execution_trace_to_tensor_value(trace) for trace in graph_exec_traces if trace.op_type == 'Mul']
        self.assertAllClose(mul_values, [6.0, 6.0, 6.0, 6.0])

def get_flex_attn_fwd_configs(self, head_dim: int, dtype: Any) -> list[FlexConfig]:
    flex_attn_fwd_configs: list[FlexConfig] = []
    if config.max_autotune:
        if config.max_autotune_flex_search_space == 'EXHAUSTIVE':
            return self.exhaustive_flex_attn_fwd_configs
        flex_attn_fwd_configs += self.flex_attn_fwd_autotune_configs
    if <MASK>:
        if dtype == torch.float32:
            default_config = FlexConfig(64, 64, 1, 8)
        else:
            default_config = FlexConfig(128, 64, 1, 16)
        default_config = self.xpu_default_flex_config.get((dtype, head_dim), default_config)
    elif dtype == torch.float32:
        default_config = FlexConfig(32, 16, 1, 4)
    else:
        default_config = FlexConfig(64, 32, 1, 8)
    if default_config not in flex_attn_fwd_configs:
        flex_attn_fwd_configs.append(default_config)
    return flex_attn_fwd_configs

@_onnx_symbolic('aten::split')
@symbolic_helper.parse_args('v', 'v', 'i', 'i')
def split(g: jit_utils.GraphContext, self, split_size_or_sizes, dim, _outputs=None):
    if <MASK>:
        split_out = g.op('SplitToSequence', self, split_size_or_sizes, axis_i=dim)
        if _outputs is None:
            return split_out
        if symbolic_helper._is_packed_list(split_size_or_sizes) and len(symbolic_helper._unpack_list(split_size_or_sizes)) == _outputs:
            split_sizes = [symbolic_helper._unsqueeze_helper(g, v, [0]) for v in symbolic_helper._unpack_list(split_size_or_sizes)]
            start = g.op('Constant', value_t=torch.tensor([0], dtype=torch.long))
            axis = g.op('Constant', value_t=torch.tensor([dim], dtype=torch.long))
            res = []
            for i in range(_outputs):
                end = g.op('Add', start, split_sizes[i])
                res.append(g.op('Slice', self, start, end, axis))
                start = end
            return res
        return [g.op('SequenceAt', split_out, g.op('Constant', value_t=torch.tensor([i], dtype=torch.long))) for i in range(_outputs)]
    split_val = symbolic_helper._node_get(split_size_or_sizes.node(), 'value')
    if split_val.dim() > 0:
        return g.op('Split', self, split_size_or_sizes, axis_i=dim, outputs=_outputs)
    split_size = symbolic_helper._get_const(split_size_or_sizes, 'i', 'split_size')
    size = symbolic_helper._get_tensor_dim_size(self, dim)
    if size is None:
        if _outputs is not None:
            size = split_size * _outputs
        else:
            raise errors.SymbolicValueError('Unknown dimension size not supported', self)
    splits = [split_size] * (size // split_size)
    leftover = size % split_size
    if leftover:
        splits.append(leftover)
    splits = g.op('Constant', value_t=torch.tensor(splits))
    return g.op('Split', self, splits, axis_i=dim, outputs=_outputs)

def get_owning_type(t: CType) -> tuple[CType, Callable[[str], str]]:
    if t == BaseCType(tensorListT):
        return (VectorCType(BaseCType(tensorT)), lambda x: f'{x}.vec()')
    if <MASK>:
        return (VectorCType(BaseCType(tensorT)), lambda x: f'{{{x}.begin(), {x}.end()}}')
    return (t, lambda x: x)

@register_decomposition(aten.logit_backward.default)
@pw_cast_for_opmath
def logit_backward(grad_output: Tensor, self: Tensor, eps: Optional[float]=None) -> Tensor:
    if <MASK>:
        lo = eps
        hi = 1.0 - lo
        return torch.where(torch.logical_and(self >= lo, self <= hi), grad_output / (self * (1.0 - self)), 0.0)
    else:
        return torch.where(torch.logical_and(self >= 0.0, self <= 1.0), grad_output / (self * (1.0 - self)), self.new_full((), float('nan')))

def check_field(self, field, **kwargs):
    errors = []
    if hasattr(self, 'check_field_type') and (not getattr(field, 'remote_field', None)):
        db_supports_all_required_features = all((getattr(self.connection.features, feature, False) for feature in field.model._meta.required_db_features))
        if db_supports_all_required_features:
            field_type = field.db_type(self.connection)
            if <MASK>:
                errors.extend(self.check_field_type(field, field_type))
    return errors

def __init__(self, mode: str, input_size: int, hidden_size: int, num_layers: int=1, bias: bool=True, batch_first: bool=False, dropout: float=0.0, bidirectional: bool=False, proj_size: int=0, device=None, dtype=None) -> None:
    factory_kwargs = {'device': device, 'dtype': dtype}
    super().__init__()
    self.mode = mode
    self.input_size = input_size
    self.hidden_size = hidden_size
    self.num_layers = num_layers
    self.bias = bias
    self.batch_first = batch_first
    self.dropout = float(dropout)
    self.bidirectional = bidirectional
    self.proj_size = proj_size
    self._flat_weight_refs: list[Optional[weakref.ReferenceType[Parameter]]] = []
    num_directions = 2 if bidirectional else 1
    if not isinstance(dropout, numbers.Number) or not 0 <= dropout <= 1 or isinstance(dropout, bool):
        raise ValueError('dropout should be a number in range [0, 1] representing the probability of an element being zeroed')
    if dropout > 0 and num_layers == 1:
        warnings.warn(f'dropout option adds dropout after all but last recurrent layer, so non-zero dropout expects num_layers greater than 1, but got dropout={dropout} and num_layers={num_layers}')
    if not isinstance(hidden_size, int):
        raise TypeError(f'hidden_size should be of type int, got: {type(hidden_size).__name__}')
    if hidden_size <= 0:
        raise ValueError('hidden_size must be greater than zero')
    if num_layers <= 0:
        raise ValueError('num_layers must be greater than zero')
    if proj_size < 0:
        raise ValueError('proj_size should be a positive integer or zero to disable projections')
    if proj_size >= hidden_size:
        raise ValueError('proj_size has to be smaller than hidden_size')
    if <MASK>:
        gate_size = 4 * hidden_size
    elif mode == 'GRU':
        gate_size = 3 * hidden_size
    elif mode == 'RNN_TANH':
        gate_size = hidden_size
    elif mode == 'RNN_RELU':
        gate_size = hidden_size
    else:
        raise ValueError('Unrecognized RNN mode: ' + mode)
    self._flat_weights_names = []
    self._all_weights = []
    for layer in range(num_layers):
        for direction in range(num_directions):
            real_hidden_size = proj_size if proj_size > 0 else hidden_size
            layer_input_size = input_size if layer == 0 else real_hidden_size * num_directions
            w_ih = Parameter(torch.empty((gate_size, layer_input_size), **factory_kwargs))
            w_hh = Parameter(torch.empty((gate_size, real_hidden_size), **factory_kwargs))
            b_ih = Parameter(torch.empty(gate_size, **factory_kwargs))
            b_hh = Parameter(torch.empty(gate_size, **factory_kwargs))
            layer_params: tuple[Tensor, ...] = ()
            if self.proj_size == 0:
                if bias:
                    layer_params = (w_ih, w_hh, b_ih, b_hh)
                else:
                    layer_params = (w_ih, w_hh)
            else:
                w_hr = Parameter(torch.empty((proj_size, hidden_size), **factory_kwargs))
                if bias:
                    layer_params = (w_ih, w_hh, b_ih, b_hh, w_hr)
                else:
                    layer_params = (w_ih, w_hh, w_hr)
            suffix = '_reverse' if direction == 1 else ''
            param_names = ['weight_ih_l{}{}', 'weight_hh_l{}{}']
            if bias:
                param_names += ['bias_ih_l{}{}', 'bias_hh_l{}{}']
            if self.proj_size > 0:
                param_names += ['weight_hr_l{}{}']
            param_names = [x.format(layer, suffix) for x in param_names]
            for (name, param) in zip(param_names, layer_params):
                setattr(self, name, param)
            self._flat_weights_names.extend(param_names)
            self._all_weights.append(param_names)
    self._init_flat_weights()
    self.reset_parameters()

