def _graph_placeholder(self, graph, name=None):
    """Graph-only version of tf.compat.v1.placeholder(), for internal use only."""
    dtype = self.dtype.base_dtype
    shape = self.shape
    dtype_value = attr_value_pb2.AttrValue(type=dtype.as_datatype_enum)
    if <MASK>:
        shape = tensor_shape.TensorShape(shape)
    shape = attr_value_pb2.AttrValue(shape=shape.as_proto())
    attrs = {'dtype': dtype_value, 'shape': shape}
    try:
        op = graph._create_op_internal('Placeholder', [], [dtype], input_types=[], attrs=attrs, name=name)
    except ValueError as e:
        logging.warning(e)
        op = graph._create_op_internal('Placeholder', [], [dtype], input_types=[], attrs=attrs)
    (result,) = op.outputs
    if op_callbacks.should_invoke_op_callbacks():
        callback_outputs = op_callbacks.invoke_op_callbacks('Placeholder', tuple(), attrs, tuple(op.outputs), op_name=name, graph=graph)
        if callback_outputs is not None:
            (result,) = callback_outputs
    return result

def tensor_split(a: TensorLikeType, indices_or_sections: Union[Tensor, DimsType], dim: int=0) -> tuple[TensorLikeType, ...]:
    _dim = utils.canonicalize_dim(a.ndim, dim)
    if a.ndim == 0:
        msg = 'tensor_split: received a rank zero tensor, but expected a tensor of rank one or greater!'
        raise ValueError(msg)
    if isinstance(indices_or_sections, TensorLike):
        if indices_or_sections.device.type != 'cpu':
            msg = f'tensor_split: if indices_or_sections is a tensor it must be on the CPU, but received one on {indices_or_sections.device}'
            raise ValueError(msg)
        if <MASK>:
            msg = f'tensor_split: if indices_or_sections is a tensor it must have long dtype,  but received one with dtype {indices_or_sections.dtype}'
            raise ValueError(msg)
    if isinstance(indices_or_sections, IntLike) or (isinstance(indices_or_sections, TensorLike) and indices_or_sections.ndim == 0):
        sections: int = indices_or_sections if isinstance(indices_or_sections, Number) else indices_or_sections.item()
        if sections <= 0:
            msg = f'tensor_split: number of sections must be greater than 0, but was {sections}'
            raise ValueError(msg)
        dim_size = a.shape[_dim]
        min_split_size = math.floor(dim_size / sections)
        num_splits_one_extra = dim_size % sections
        split_sizes = []
        for split_idx in range(sections):
            split_size = min_split_size + 1 if split_idx < num_splits_one_extra else min_split_size
            split_sizes.append(split_size)
        return tuple(aten.split_with_sizes(a, split_sizes, dim=_dim))
    else:
        indices = indices_or_sections
        if isinstance(indices_or_sections, TensorLike):
            if indices_or_sections.ndim != 1:
                msg = f'tensor_split: non-scalar indices_or_sections tensors must have only one dimension, but received a tensor with {indices_or_sections.ndim} dimensions'
                raise ValueError(msg)
            indices = indices_or_sections.tolist()
        indices = [0] + list(indices) + [a.shape[_dim]]
        split_sizes = [indices[i + 1] - indices[i] for i in range(len(indices) - 1)]
        return tuple(aten.split_with_sizes(a, split_sizes, dim=_dim))

def _fused_adagrad(params: list[Tensor], grads: list[Tensor], state_sums: list[Tensor], state_steps: list[Tensor], grad_scale: Optional[Tensor], found_inf: Optional[Tensor], *, lr: float, weight_decay: float, lr_decay: float, eps: float, has_sparse_grad: bool, maximize: bool, differentiable: bool, has_complex: bool) -> None:
    if not params:
        return
    if has_sparse_grad or has_complex:
        raise RuntimeError('`fused` does not support sparse grad or complex param')
    if differentiable:
        raise RuntimeError('adagrad with fused=True does not support differentiable=True')
    lr = _to_scalar(lr)
    grad_scale_dict = {grad_scale.device: grad_scale} if grad_scale is not None else None
    found_inf_dict = {found_inf.device: found_inf} if found_inf is not None else None
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, state_sums, state_steps])
    for ((device, _), ((device_params_, device_grads_, device_state_sums_, device_state_steps_), _)) in grouped_tensors.items():
        device_params = cast(list[Tensor], device_params_)
        device_grads = cast(list[Tensor], device_grads_)
        device_state_sums = cast(list[Tensor], device_state_sums_)
        device_state_steps = cast(list[Tensor], device_state_steps_)
        (device_grad_scale, device_found_inf) = (None, None)
        if grad_scale is not None and grad_scale_dict is not None:
            if device not in grad_scale_dict:
                grad_scale_dict[device] = grad_scale.to(device, non_blocking=True)
            device_grad_scale = grad_scale_dict[device]
        if found_inf is not None and found_inf_dict is not None:
            if found_inf not in found_inf_dict:
                found_inf_dict[device] = found_inf.to(device, non_blocking=True)
            device_found_inf = found_inf_dict[device]
        torch._foreach_add_(device_state_steps, 1)
        torch._fused_adagrad_(device_params, device_grads, device_state_sums, device_state_steps, lr=lr, lr_decay=lr_decay, weight_decay=weight_decay, eps=eps, maximize=maximize, grad_scale=device_grad_scale, found_inf=device_found_inf)
        if <MASK>:
            torch._foreach_sub_(device_state_steps, [device_found_inf] * len(device_state_steps))

def _get_var(self, name, conf_desc):
    (hook, envvar, confvar, convert, append) = conf_desc
    if convert is None:
        convert = lambda x: x
    var = self._hook_handler(name, hook)
    if envvar is not None:
        envvar_contents = os.environ.get(envvar)
        if envvar_contents is not None:
            envvar_contents = convert(envvar_contents)
            if <MASK>:
                if os.environ.get('NPY_DISTUTILS_APPEND_FLAGS', '1') == '1':
                    var.extend(envvar_contents)
                else:
                    var = envvar_contents
            else:
                var = envvar_contents
    if confvar is not None and self._conf:
        if confvar in self._conf:
            (source, confvar_contents) = self._conf[confvar]
            var = convert(confvar_contents)
    return var

@staticmethod
def unwrap_storage(inputs: Sequence[Union[IRNode, Sequence[IRNode]]]) -> list[Union[IRNode, Sequence[IRNode]]]:
    inputs_new: list[Union[IRNode, Sequence[IRNode]]] = []
