def _get_logical_cpus_to_bind_to(*, gpu_index: int, numa_options: NumaOptions) -> set[int]:
    """
    Args:
        gpu_index: The index of the GPU that will be used by the subprocess.
            Example: 0
        numa_options: See NumaOptions for details.

    Returns:
        Set of logical CPU indices to bind to.
    """
    if numa_options.affinity_mode == AffinityMode.NODE:
        logical_cpus = _node_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    elif numa_options.affinity_mode == AffinityMode.SOCKET:
        logical_cpus = _socket_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    elif numa_options.affinity_mode == AffinityMode.EXCLUSIVE:
        logical_cpus = _exclusive_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    elif <MASK>:
        logical_cpus = _core_complex_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    else:
        raise ValueError(f'Affinity mode {numa_options.affinity_mode} not supported.')
    return logical_cpus

def _maybe_unbox_datetimelike(value: Scalar, dtype: DtypeObj) -> Scalar:
    """
    Convert a Timedelta or Timestamp to timedelta64 or datetime64 for setting
    into a numpy array.  Failing to unbox would risk dropping nanoseconds.

    Notes
    -----
    Caller is responsible for checking dtype.kind in "mM"
    """
    if is_valid_na_for_dtype(value, dtype):
        value = dtype.type('NaT', 'ns')
    elif isinstance(value, Timestamp):
        if value.tz is None:
            value = value.to_datetime64()
        elif not isinstance(dtype, DatetimeTZDtype):
            raise TypeError('Cannot unbox tzaware Timestamp to tznaive dtype')
    elif <MASK>:
        value = value.to_timedelta64()
    _disallow_mismatched_datetimelike(value, dtype)
    return value

def add_external_dependencies(self, key, migration):
    for parent in migration.dependencies:
        if key[0] == parent[0]:
            continue
        parent = self.check_key(parent, key[0])
        if parent is not None:
            self.graph.add_dependency(migration, key, parent, skip_validation=True)
    for child in migration.run_before:
        child = self.check_key(child, key[0])
        if <MASK>:
            self.graph.add_dependency(migration, child, key, skip_validation=True)

def append_stacktrace_summary(node: Node):
    """
            Append a summary of the stacktrace to the generated code. This is
            useful for debugging.
            """
    nonlocal prev_stacktrace
    if node.op not in {'placeholder', 'output'}:
        stack_trace = node.stack_trace
        if stack_trace:
            if stack_trace != prev_stacktrace:
                prev_stacktrace = stack_trace
                if <MASK>:
                    summary_str = parsed_stack_trace.get_summary_str()
                else:
                    summary_str = ''
                body.append(f"\n {dim(f'# {summary_str}')}\n")
        elif prev_stacktrace != '':
            prev_stacktrace = ''
            no_stacktrace_msg = '# No stacktrace found for following nodes'
            body.append(f'\n{dim(no_stacktrace_msg)}\n')

def _filter_special_cases(f) -> Callable[[F], F]:

    @wraps(f)
