def _get_model_bytecode_version(f_input) -> int:
    """Take a file-like object to return an integer.

    Args:
        f_input: a file-like object (has to implement read, readline, tell, and seek),
            or a string containing a file name

    Returns:
        version: An integer. If the integer is -1, the version is invalid. A warning
            will show in the log.

    Example:
    .. testcode::

        from torch.jit.mobile import _get_model_bytecode_version

        # Get bytecode version from a saved file path
        version = _get_model_bytecode_version("path/to/model.ptl")

    """
    if <MASK>:
        if not os.path.exists(f_input):
            raise ValueError(f'The provided filename {f_input} does not exist')
        if os.path.isdir(f_input):
            raise ValueError(f'The provided filename {f_input} is a directory')
    if isinstance(f_input, (str, os.PathLike)):
        return torch._C._get_model_bytecode_version(os.fspath(f_input))
    else:
        return torch._C._get_model_bytecode_version_from_buffer(f_input.read())

def _generate_buffer(self, node: ir.IRNode) -> Optional[torch.fx.Node]:
    """
        Generates FX IR for transformations on a buffer, such as ReinterpretView.
        Does nothing if no such transformations are present.
        """
    if <MASK>:
        return self._sympy_interp(node.expr).node

    def generate_to_buffer(node: ir.IRNode) -> Optional[BufferLike]:
        if isinstance(node, (ir.Buffer, WorkspaceArg)):
            return node
        elif isinstance(node, ir.NoneAsConstantBuffer):
            return None
        elif isinstance(node, ir.MutableBox):
            return generate_to_buffer(node.data)
        elif isinstance(node, ir.ReinterpretView):
            buffer = self._get_buffer(node.data)
            assert isinstance(buffer, (ir.Buffer, WorkspaceArg))
            unique_name = self.gm.graph._graph_namespace.create_name(f'{buffer.get_name()}_view', None)
            device = buffer.get_device()
            assert device
            reused_as = WorkspaceArg(count=buffer.get_size(), zero_mode=WorkspaceZeroMode.UNINITIALIZED, device=device, outer_name=unique_name, dtype=buffer.get_dtype())
            self._generate_reinterpret_helper(buffer, reused_as, node.layout)
            return reused_as
        else:
            raise NotImplementedError(f'Unrecognized buffer/view node: {node}')
    buffer = generate_to_buffer(node)
    return self.buffer_to_node[buffer.get_name()] if buffer is not None else None

@register_op_strategy(aten._scaled_dot_product_efficient_attention.default, schema_info=RuntimeSchemaInfo(4))
def scaled_dot_product_efficient_attention_strategy(op_schema: OpSchema) -> OpStrategy:
    mesh = op_schema.get_mesh_from_args()
    q_input_strategy = op_schema.args_schema[0]
    if not isinstance(q_input_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(q_input_strategy)}')
    has_attn_bias = op_schema.args_schema[3] is not None
    compute_log_sumexp = op_schema.args_schema[4]
    single_mesh_dim_strategies: list[PlacementList] = []
    all_replicate: PlacementList = [Replicate(), Replicate(), None, None, Replicate(), Replicate(), Replicate()]
    if <MASK>:
        all_replicate.append(Replicate())
    single_mesh_dim_strategies.append([Shard(2), Shard(2), None, None, Shard(2), Shard(2), Shard(2)])
    single_mesh_dim_strategies.append(all_replicate)
    qkv_sharding = Shard(1)
    output_sharding = Shard(1)
    if compute_log_sumexp:
        logsumexp_sharding: Placement = Shard(1)
    else:
        logsumexp_sharding = Replicate()
    num_heads_dim_sharding = [output_sharding, logsumexp_sharding, None, None, qkv_sharding, qkv_sharding, qkv_sharding]
    if has_attn_bias:
        num_heads_dim_sharding.append(Shard(1))
    single_mesh_dim_strategies.append(num_heads_dim_sharding)
    if compute_log_sumexp:
        logsumexp_sharding_dp: Placement = Shard(0)
    else:
        logsumexp_sharding_dp = Replicate()
    batch_sharding = [Shard(0), logsumexp_sharding_dp, None, None, Shard(0), Shard(0), Shard(0)]
    if has_attn_bias:
        batch_sharding.append(Shard(0))
    single_mesh_dim_strategies.append(batch_sharding)
    return expand_to_full_mesh_op_strategy(mesh, op_schema, single_mesh_dim_strategies, input_index=4)

def print_new_cast_table(*, can_cast=True, legacy=False, flags=False):
    """Prints new casts, the values given are default "can-cast" values, not
    actual ones.
    """
    from numpy._core._multiarray_tests import get_all_cast_information
    cast_table = {-1: ' ', 0: '#', 1: '#', 2: '=', 3: '~', 4: '.'}
    flags_table = {0: '▗', 7: '█', 1: '▚', 2: '▐', 4: '▄', 3: '▜', 5: '▙', 6: '▟'}
    cast_info = namedtuple('cast_info', ['can_cast', 'legacy', 'flags'])
    no_cast_info = cast_info(' ', ' ', ' ')
    casts = get_all_cast_information()
    table = {}
    dtypes = set()
    for cast in casts:
        dtypes.add(cast['from'])
        dtypes.add(cast['to'])
        if cast['from'] not in table:
            table[cast['from']] = {}
        to_dict = table[cast['from']]
        can_cast = cast_table[cast['casting']]
        legacy = 'L' if cast['legacy'] else '.'
        flags = 0
        if cast['requires_pyapi']:
            flags |= 1
        if cast['supports_unaligned']:
            flags |= 2
        if cast['no_floatingpoint_errors']:
            flags |= 4
        flags = flags_table[flags]
        to_dict[cast['to']] = cast_info(can_cast=can_cast, legacy=legacy, flags=flags)
    types = np.typecodes['All']

    def sorter(x):
        dtype = np.dtype(x.type)
        try:
            indx = types.index(dtype.char)
        except ValueError:
            indx = np.inf
        return (indx, dtype.char)
    dtypes = sorted(dtypes, key=sorter)

    def print_table(field='can_cast'):
        print('X', end=' ')
        for dt in dtypes:
            print(np.dtype(dt.type).char, end=' ')
        print()
        for from_dt in dtypes:
            print(np.dtype(from_dt.type).char, end=' ')
            row = table.get(from_dt, {})
            for to_dt in dtypes:
                print(getattr(row.get(to_dt, no_cast_info), field), end=' ')
            print()
    if can_cast:
        print()
        print('Casting: # is equivalent, = is safe, ~ is same-kind, and . is unsafe')
        print()
        print_table('can_cast')
    if legacy:
        print()
        print('L denotes a legacy cast . a non-legacy one.')
        print()
        print_table('legacy')
    if <MASK>:
        print()
        print(f'{flags_table[0]}: no flags, {flags_table[1]}: PyAPI, {flags_table[2]}: supports unaligned, {flags_table[4]}: no-float-errors')
        print()
        print_table('flags')

def default_expr(d: str, t: Type, *, symint: bool) -> str:
    if d == 'None' and str(t) == 'Tensor?':
        return '{}'
    if isinstance(t, BaseType) and t.name is BaseTy.str:
        if len(d) >= 2 and d[0] == "'" and (d[-1] == "'"):
            s = ''
            i = 1
            while i + 1 < len(d):
                if d[i] != '\\':
                    if <MASK>:
                        s += '\\"'
                    else:
                        s += d[i]
                    i += 1
                else:
                    if d[i + 1] == "'":
                        s += "'"
                    else:
                        s += d[i:i + 2]
                    i += 2
            return f'"{s}"'
    if isinstance(t, OptionalType):
        if d == 'None':
            return '::std::nullopt'
        return default_expr(d, t.elem, symint=symint)
    if isinstance(t, ListType):
        if d.startswith('[') and d.endswith(']'):
            return '{' + d[1:-1] + '}'
        elif symint and d.isdigit() and (str(t.elem) == 'SymInt'):
            return f'c10::SymInt({d})'
        elif t.size is None:
            raise ValueError(f"Expected a list default '[...]' but found: '{d}'")
    return JIT_TO_CPP_DEFAULT.get(d, d)

def _single_tensor_rmsprop(params: list[Tensor], grads: list[Tensor], square_avgs: list[Tensor], grad_avgs: list[Tensor], momentum_buffer_list: list[Tensor], state_steps: list[Tensor], *, lr: float, alpha: float, eps: float, weight_decay: float, momentum: float, centered: bool, maximize: bool, differentiable: bool, capturable: bool, has_complex: bool):
    if not torch.jit.is_scripting():
        lr = _to_scalar(lr)
    for (i, param) in enumerate(params):
        step = state_steps[i]
        if not torch.compiler.is_compiling() and capturable:
            capturable_supported_devices = _get_capturable_supported_devices()
            if not (param.device.type == step.device.type and param.device.type in capturable_supported_devices):
                raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
        grad = grads[i]
        grad = grad if not maximize else -grad
        square_avg = square_avgs[i]
        step += 1
        if weight_decay != 0:
            grad = grad.add(param, alpha=weight_decay)
        is_complex_param = torch.is_complex(param)
        if is_complex_param:
            param = torch.view_as_real(param)
            grad = torch.view_as_real(grad)
            square_avg = torch.view_as_real(square_avg)
        square_avg.mul_(alpha).addcmul_(grad, grad, value=1 - alpha)
        if centered:
            grad_avg = grad_avgs[i]
            if is_complex_param:
                grad_avg = torch.view_as_real(grad_avg)
            grad_avg.lerp_(grad, 1 - alpha)
            avg = square_avg.addcmul(grad_avg, grad_avg, value=-1).sqrt_()
        else:
            avg = square_avg.sqrt()
        if <MASK>:
            avg = avg.add(eps)
        else:
            avg = avg.add_(eps)
        if momentum > 0:
            buf = momentum_buffer_list[i]
            if is_complex_param:
                buf = torch.view_as_real(buf)
            buf.mul_(momentum).addcdiv_(grad, avg)
            param.add_(buf, alpha=-lr)
        else:
            param.addcdiv_(grad, avg, value=-lr)

def names_to_path(self, names, opts, allow_many=True, fail_on_missing=False):
    """
        Walk the list of names and turns them into PathInfo tuples. A single
        name in 'names' can generate multiple PathInfos (m2m, for example).

        'names' is the path of names to travel, 'opts' is the model Options we
        start the name resolving from, 'allow_many' is as for setup_joins().
        If fail_on_missing is set to True, then a name that can't be resolved
        will generate a FieldError.

        Return a list of PathInfo tuples. In addition return the final field
        (the last used join field) and target (which is a field guaranteed to
        contain the same value as the final field). Finally, return those names
        that weren't found (which are likely transforms and the final lookup).
        """
    (path, names_with_path) = ([], [])
    for (pos, name) in enumerate(names):
        cur_names_with_path = (name, [])
        if name == 'pk' and opts is not None:
            name = opts.pk.name
        field = None
        filtered_relation = None
        try:
            if opts is None:
                raise FieldDoesNotExist
            field = opts.get_field(name)
        except FieldDoesNotExist:
            if name in self.annotation_select:
                field = self.annotation_select[name].output_field
            elif name in self._filtered_relations and pos == 0:
                filtered_relation = self._filtered_relations[name]
                if LOOKUP_SEP in filtered_relation.relation_name:
                    parts = filtered_relation.relation_name.split(LOOKUP_SEP)
                    (filtered_relation_path, field, _, _) = self.names_to_path(parts, opts, allow_many, fail_on_missing)
                    path.extend(filtered_relation_path[:-1])
                else:
                    field = opts.get_field(filtered_relation.relation_name)
        if field is not None:
            if <MASK>:
                raise FieldError('Field %r does not generate an automatic reverse relation and therefore cannot be used for reverse querying. If it is a GenericForeignKey, consider adding a GenericRelation.' % name)
            try:
                model = field.model._meta.concrete_model
            except AttributeError:
                model = None
        else:
            pos -= 1
            if pos == -1 or fail_on_missing:
                available = sorted([*get_field_names_from_opts(opts), *self.annotations, *self._filtered_relations])
                raise FieldError("Cannot resolve keyword '%s' into field. Choices are: %s" % (name, ', '.join(available)))
            break
        if opts is not None and model is not opts.model:
            path_to_parent = opts.get_path_to_parent(model)
            if path_to_parent:
                path.extend(path_to_parent)
                cur_names_with_path[1].extend(path_to_parent)
                opts = path_to_parent[-1].to_opts
        if hasattr(field, 'path_infos'):
            if filtered_relation:
                pathinfos = field.get_path_info(filtered_relation)
            else:
                pathinfos = field.path_infos
            if not allow_many:
                for (inner_pos, p) in enumerate(pathinfos):
                    if p.m2m:
                        cur_names_with_path[1].extend(pathinfos[0:inner_pos + 1])
                        names_with_path.append(cur_names_with_path)
                        raise MultiJoin(pos + 1, names_with_path)
            last = pathinfos[-1]
            path.extend(pathinfos)
            final_field = last.join_field
            opts = last.to_opts
            targets = last.target_fields
            cur_names_with_path[1].extend(pathinfos)
            names_with_path.append(cur_names_with_path)
        else:
            final_field = field
            targets = (field,)
            if fail_on_missing and pos + 1 != len(names):
                raise FieldError("Cannot resolve keyword %r into field. Join on '%s' not permitted." % (names[pos + 1], name))
            break
    return (path, final_field, targets, names[pos + 1:])

def get_items_from_dict(obj: dict[K, V]) -> Iterable[tuple[K, Union[V, Any]]]:
    assert isinstance(obj, dict)
    if istype(obj, (dict, OrderedDict)):
        return obj.items()
    elif <MASK>:
        return [(k, OrderedDict.__getitem__(obj, k)) for k in OrderedDict.keys(obj)]
    else:
        return [(k, dict.__getitem__(obj, k)) for k in dict.keys(obj)]

