def summarize_range(self, start: int, end: int) -> T:
    """
        Query a range of values in the segment tree.

        Args:
            start: Start index of the range to query (inclusive)
            end: End index of the range to query (inclusive)

        Returns:
            Summary value for the range according to the summary operation

        Raises:
            ValueError: If start > end or indices are out of bounds
        """
    if <MASK>:
        raise ValueError('Start index must be less than or equal to end index')
    if start < 0 or start >= self.n:
        raise ValueError(f'Start index {start} out of bounds [0, {self.n - 1}]')
    if end < 0 or end >= self.n:
        raise ValueError(f'End index {end} out of bounds [0, {self.n - 1}]')
    return self._query_range_helper(1, 0, self.n - 1, start, end)

@dispatch_for_api(api, {x_name: x_type})
def dispatch_target(*args, **kwargs):
    (args, kwargs, name) = _extract_name_arg(args, kwargs, name_index)
    if args:
        (x, args) = (args[0], args[1:])
    else:
        x = kwargs.pop(x_name)
    if <MASK>:
        tensor_api = lambda v: api(v, *args, **kwargs)
    else:
        tensor_api = api
    if name is None:
        return elementwise_api_handler(tensor_api, x)
    else:
        with ops.name_scope(name, None, [x]):
            return elementwise_api_handler(tensor_api, x)

def _assert_caught_no_extra_warnings(*, caught_warnings: Sequence[warnings.WarningMessage], expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None) -> None:
    """Assert that no extra warnings apart from the expected ones are caught."""
    extra_warnings = []
    for actual_warning in caught_warnings:
        if <MASK>:
            if actual_warning.category == ResourceWarning:
                if 'unclosed <ssl.SSLSocket' in str(actual_warning.message):
                    continue
                if any(('matplotlib' in mod for mod in sys.modules)):
                    continue
            if actual_warning.category == EncodingWarning:
                continue
            extra_warnings.append((actual_warning.category.__name__, actual_warning.message, actual_warning.filename, actual_warning.lineno))
    if extra_warnings:
        raise AssertionError(f'Caused unexpected warning(s): {extra_warnings!r}')

def maybe_get_suppress_shape_guards_ctx() -> contextlib.AbstractContextManager[None]:
    tracing_context = torch._guards.TracingContext.try_get()
    if <MASK>:
        return contextlib.nullcontext()
    if not tracing_context.fake_mode or not tracing_context.fake_mode.shape_env:
        return contextlib.nullcontext()
    shape_env = tracing_context.fake_mode.shape_env
    return shape_env.suppress_guards()

def deserialize_m2m_values(field, field_value, using, handle_forward_references):
    model = field.remote_field.model
    if <MASK>:

        def m2m_convert(value):
            if hasattr(value, '__iter__') and (not isinstance(value, str)):
                return model._default_manager.db_manager(using).get_by_natural_key(*value).pk
            else:
                return model._meta.pk.to_python(value)
    else:

        def m2m_convert(v):
            return model._meta.pk.to_python(v)
    try:
        pks_iter = iter(field_value)
    except TypeError as e:
        raise M2MDeserializationError(e, field_value)
    try:
        values = []
        for pk in pks_iter:
            values.append(m2m_convert(pk))
        return values
    except Exception as e:
        if isinstance(e, ObjectDoesNotExist) and handle_forward_references:
            return DEFER_FIELD
        else:
            raise M2MDeserializationError(e, pk)

def map_structure_with_atomic(is_atomic_fn, map_fn, nested):
    """Maps the atomic elements of a nested structure.

  Args:
    is_atomic_fn: A function that determines if an element of `nested` is
      atomic.
    map_fn: The function to apply to atomic elements of `nested`.
    nested: A nested structure.

  Returns:
    The nested structure, with atomic elements mapped according to `map_fn`.

  Raises:
    ValueError: If an element that is neither atomic nor a sequence is
      encountered.
  """
    if is_atomic_fn(nested):
        return map_fn(nested)
    if not nest.is_nested(nested):
        raise ValueError('Received non-atomic and non-sequence element: {}'.format(nested))
    if <MASK>:
        values = [nested[k] for k in sorted(nested.keys())]
    elif nest.is_attrs(nested):
        values = _astuple(nested)
    else:
        values = nested
    mapped_values = [map_structure_with_atomic(is_atomic_fn, map_fn, ele) for ele in values]
    return nest._sequence_like(nested, mapped_values)

def call(self, inputs):
    if self.data_format == 'channels_first':
        if self.cropping[0][1] == self.cropping[1][1] == 0:
            return inputs[:, :, self.cropping[0][0]:, self.cropping[1][0]:]
        elif self.cropping[0][1] == 0:
            return inputs[:, :, self.cropping[0][0]:, self.cropping[1][0]:-self.cropping[1][1]]
        elif <MASK>:
            return inputs[:, :, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:]
        return inputs[:, :, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1]]
    else:
        if self.cropping[0][1] == self.cropping[1][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:, :]
        elif self.cropping[0][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:-self.cropping[1][1], :]
        elif self.cropping[1][1] == 0:
            return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:, :]
        return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1], :]

def test_bias_add(self):
    for data_format in ('NCHW', 'NHWC'):
        for stacked_value in (True, False):
            x_shape = [3, 4, 5, 6]
            if stacked_value:
                x_shape = [2] + x_shape
            x = random_ops.random_uniform(x_shape)
            for stacked_bias in (True, False):
                if <MASK>:
                    continue
                with backprop.GradientTape(persistent=True) as g:
                    bias_dim = -1
                    if data_format == 'NCHW':
                        bias_dim = 2 if stacked_value else 1
                    bias_shape = [x_shape[bias_dim]]
                    if stacked_bias:
                        bias_shape = [2] + bias_shape
                    bias = random_ops.random_uniform(bias_shape)
                    g.watch(bias)

                def loop_fn(i):
                    with g:
                        a = array_ops.gather(x, i) if stacked_value else x
                        b = array_ops.gather(bias, i) if stacked_bias else bias
                        y = nn.bias_add(a, b, data_format=data_format)
                        loss = math_ops.reduce_sum(y * y)
                    grad = g.gradient(loss, bias)
                    if stacked_bias:
                        return (y, grad.values, grad.indices)
                    else:
                        return (y, grad)
                out_dtypes = [dtypes.float32, dtypes.float32]
                if stacked_bias:
                    out_dtypes = out_dtypes + [dtypes.int32]
                self._test_loop_fn(loop_fn, 2)

def __call__(self, gm: torch.fx.GraphModule, example_inputs: list[torch.Tensor]) -> Callable[..., Any]:
    self.frame_count += 1
    for node in gm.graph.nodes:
        if <MASK>:
            self.op_count += 1
    return gm.forward

def enforce_comm_ordering_for_fsdp(snodes: list[torch._inductor.scheduler.BaseSchedulerNode], name_to_buf: dict[str, torch._inductor.scheduler.SchedulerBuffer], name_to_fused_node: dict[str, BaseSchedulerNode]) -> list[torch._inductor.scheduler.BaseSchedulerNode]:
    from . import scheduler
    new_order: list[BaseSchedulerNode] = []
    scheduled = OrderedSet[Any]()
    ag_exists = False
    rs_exists = False
    ag_grouped_node_to_wait_grouped_node = {}
    rs_grouped_node_to_wait_grouped_node = {}
    snode_name_to_final_snode = {}

    def _create_group_node(snodes_to_group):
        group_node = scheduler.GroupedSchedulerNode.create(snodes_to_group)
        for snode in snodes_to_group:
            snode_name_to_final_snode[snode.get_name()] = group_node
        snode_name_to_final_snode[group_node.get_name()] = group_node
        return group_node
    for snode in snodes:
        if is_collective(snode.node, op=torch.ops._c10d_functional.all_gather_into_tensor_out.default) and any((is_fallback_op(name_to_fused_node[x].node, torch.ops.fsdp.all_gather_copy_in.default) for x in snode.ancestors)):
            ag_exists = True
            ag_snode = snode
            ag_related_snode_set: OrderedSet[scheduler.BaseSchedulerNode] = OrderedSet()
            find_recursive_deps_of_node(ag_snode, ag_related_snode_set, name_to_buf, name_to_fused_node)
            allowed_ops = OrderedSet([torch.ops._c10d_functional.all_gather_into_tensor_out.default, torch.ops._c10d_functional.wait_tensor.default, torch.ops.fsdp.split_with_sizes_copy.default])
            find_recursive_users_of_node(ag_snode, ag_related_snode_set, name_to_buf, name_to_fused_node, criteria_cb=lambda x: not (isinstance(x, scheduler.NopKernelSchedulerNode) or (isinstance(x, scheduler.ExternKernelSchedulerNode) and x.node.op_overload in allowed_ops)))
            ag_related_snodes = sorted(ag_related_snode_set, key=lambda x: get_op_idx(x))
            end_idx_of_current_ag_block = len(ag_related_snodes)
            copy_out_count = 0
            for i in range(len(ag_related_snodes)):
                cur_snode = ag_related_snodes[i]
                if is_fallback_op(cur_snode.node, torch.ops.fsdp.split_with_sizes_copy.default):
                    copy_out_count += 1
                if copy_out_count > 1:
                    end_idx_of_current_ag_block = i
                    break
            ag_related_snodes = ag_related_snodes[:end_idx_of_current_ag_block]
            wait_node_idx = None
            for i in range(len(ag_related_snodes) - 1):
                if isinstance(ag_related_snodes[i + 1].node, ir._WaitKernel):
                    wait_node_idx = i + 1
                    break
            assert wait_node_idx is not None
            ag_group_node = _create_group_node(ag_related_snodes[:wait_node_idx])
            ag_wait_group_node = _create_group_node(ag_related_snodes[wait_node_idx:])
            ag_grouped_node_to_wait_grouped_node[ag_group_node] = ag_wait_group_node
        elif is_fallback_op(snode.node, torch.ops.fsdp.chunk_cat.default):
            rs_exists = True
            rs_snode = snode
            rs_related_snode_set: OrderedSet[scheduler.BaseSchedulerNode] = OrderedSet()
            find_recursive_users_of_node(rs_snode, rs_related_snode_set, name_to_buf, name_to_fused_node)
            rs_related_snodes = sorted(rs_related_snode_set, key=lambda x: get_op_idx(x))
            wait_node_idx = None
            for i in range(len(rs_related_snodes) - 1):
                if isinstance(rs_related_snodes[i + 1].node, ir._WaitKernel):
                    wait_node_idx = i + 1
                    break
            assert wait_node_idx is not None
            rs_group_node = _create_group_node(rs_related_snodes[:wait_node_idx])
            rs_wait_group_node = _create_group_node(rs_related_snodes[wait_node_idx:])
            rs_grouped_node_to_wait_grouped_node[rs_group_node] = rs_wait_group_node
    assert len(snode_name_to_final_snode) > 0
    if ag_exists:
        assert len(ag_grouped_node_to_wait_grouped_node) > 0
    if rs_exists:
        assert len(rs_grouped_node_to_wait_grouped_node) > 0
    for snode in snodes:
        if snode.get_name() in snode_name_to_final_snode:
            snode = snode_name_to_final_snode[snode.get_name()]
        if snode in scheduled:
            continue
        new_order.append(snode)
        scheduled.add(snode)
    prev_ag_wait = None
    for (ag_group_node, wait_group_node) in ag_grouped_node_to_wait_grouped_node.items():
        if <MASK>:
            mutating_buf = next(iter(ag_group_node.get_buffer_names()))
            for o in prev_ag_wait.get_outputs():
                ag_group_node.add_fake_dep(WeakDep(o.get_name(), mutating_buf=mutating_buf, is_fake=True))
        prev_ag_wait = wait_group_node
    prev_rs_wait = None
    for (rs_group_node, wait_group_node) in rs_grouped_node_to_wait_grouped_node.items():
        if prev_rs_wait is not None:
            mutating_buf = next(iter(rs_group_node.get_buffer_names()))
            for o in prev_rs_wait.get_outputs():
                rs_group_node.add_fake_dep(WeakDep(o.get_name(), mutating_buf=mutating_buf, is_fake=True))
        prev_rs_wait = wait_group_node
    return new_order

def placeholder_value(self, placeholder_context):
    """Generates a graph placeholder with the given TensorSpec information."""
    if placeholder_context.unnest_only:
        return self
    name = self.name or placeholder_context.naming_scope
    context_graph = placeholder_context.context_graph
    if placeholder_context.with_none_control_dependencies:
        with context_graph.control_dependencies(None):
            placeholder = self._graph_placeholder(context_graph, name=name)
    else:
        placeholder = self._graph_placeholder(context_graph, name=name)
    if name is not None:
        placeholder.op._set_attr('_user_specified_name', attr_value_pb2.AttrValue(s=compat.as_bytes(name)))
    handle_data = self.dtype._handle_data
    if handle_data is not None and handle_data.shape_inference.is_set and handle_data.shape_inference.shape_and_type:
        handle_data_util.set_handle_data(placeholder, handle_data.shape_inference)
    if <MASK>:
        placeholder.op._set_attr('_composite_device', attr_value_pb2.AttrValue(s=compat.as_bytes(placeholder_context.composite_device_name)))
    return placeholder

def _broadcast_uniform_partitioned_dimension(self, axis, lengths):
    """Broadcasts the partitioned dimension `axis` to match `lengths`."""
    axis_dim_size = self.dimension_size(axis)
    partitioned_sizes = list(self._partitioned_dim_sizes[:axis])
    if lengths.shape.ndims == 0:
        lengths = array_ops.where(math_ops.equal(axis_dim_size, 1), lengths, axis_dim_size)
        repeats = array_ops.where(math_ops.equal(axis_dim_size, 1), lengths, 1)
        splits = array_ops_stack.stack([0, self.num_slices_in_dimension(axis)])
    else:
        splits = math_ops.range(array_ops.size(lengths, out_type=self.dim_size_dtype) + 1)
        repeats = lengths
    partitioned_sizes.append(lengths)
    for dim_size in self._partitioned_dim_sizes[axis + 1:]:
        if <MASK>:
            partitioned_sizes.append(dim_size)
            splits *= dim_size
        else:
            partitioned_sizes.append(ragged_util.repeat_ranges(dim_size, splits, repeats))
            splits = array_ops.gather(ragged_util.lengths_to_splits(dim_size), splits)
    inner_sizes = self._inner_dim_sizes
    return RaggedTensorDynamicShape(partitioned_sizes, inner_sizes, self.dim_size_dtype)

def get_json_type(obj):
    """Serializes any object to a JSON-serializable structure.

  Args:
      obj: the object to serialize

  Returns:
      JSON-serializable structure representing `obj`.

  Raises:
      TypeError: if `obj` cannot be serialized.
  """
    if hasattr(obj, 'get_config'):
        return {'class_name': obj.__class__.__name__, 'config': obj.get_config()}
    if type(obj).__module__ == np.__name__:
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        else:
            return obj.item()
    if callable(obj):
        return obj.__name__
    if type(obj).__name__ == type.__name__:
        return obj.__name__
    if isinstance(obj, tensor_shape.Dimension):
        return obj.value
    if isinstance(obj, tensor_shape.TensorShape):
        return obj.as_list()
    if isinstance(obj, dtypes.DType):
        return obj.name
    if isinstance(obj, collections_abc.Mapping):
        return dict(obj)
    if <MASK>:
        return {'class_name': '__ellipsis__'}
    if isinstance(obj, wrapt.ObjectProxy):
        return obj.__wrapped__
    raise TypeError(f'Object {obj} is not JSON-serializable. You may implement a `get_config()` method on the class (returning a JSON-serializable dictionary) to make it serializable.')

def _split_helper_int(tensor, indices_or_sections, axis, strict=False):
    if not isinstance(indices_or_sections, int):
        raise NotImplementedError('split: indices_or_sections')
    axis = _util.normalize_axis_index(axis, tensor.ndim)
    (l, n) = (tensor.shape[axis], indices_or_sections)
    if n <= 0:
        raise ValueError
    if l % n == 0:
        (num, sz) = (n, l // n)
        lst = [sz] * num
    else:
        if <MASK>:
            raise ValueError('array split does not result in an equal division')
        (num, sz) = (l % n, l // n + 1)
        lst = [sz] * num
    lst += [sz - 1] * (n - num)
    return torch.split(tensor, lst, axis)

def add_module(self, name: str, module: Optional['Module']) -> None:
    """Add a child module to the current module.

        The module can be accessed as an attribute using the given name.

        Args:
            name (str): name of the child module. The child module can be
                accessed from this module using the given name
            module (Module): child module to be added to the module.
        """
    if not isinstance(module, Module) and module is not None:
        raise TypeError(f'{torch.typename(module)} is not a Module subclass')
    elif not isinstance(name, str):
        raise TypeError(f'module name should be a string. Got {torch.typename(name)}')
    elif hasattr(self, name) and name not in self._modules:
        raise KeyError(f"attribute '{name}' already exists")
    elif <MASK>:
        raise KeyError(f"""module name can't contain ".", got: {name}""")
    elif name == '':
        raise KeyError('module name can\'t be empty string ""')
    for hook in _global_module_registration_hooks.values():
        output = hook(self, name, module)
        if output is not None:
            module = output
    self._modules[name] = module

def _run_sympy_handler(analysis, args, expr, index_dtype=torch.int64):
    if <MASK>:
        return analysis.sqrt(args[0])
    if isinstance(expr, ToFloat):
        return analysis.to_dtype(args[0], torch.float64)
    INDEX_DTYPE_HANDLERS = {TruncToInt: 'trunc_to_int', sympy.floor: 'floor_to_int', sympy.ceiling: 'ceil_to_int', FloorToInt: 'floor_to_int', CeilToInt: 'ceil_to_int', RoundToInt: 'round_to_int'}
    if (handler_name := INDEX_DTYPE_HANDLERS.get(expr.func)) is not None:
        return getattr(analysis, handler_name)(*args, index_dtype)
    if expr.func is sympy.Add and expr.is_integer and hasattr(analysis, 'sym_sum'):
        r = analysis.sym_sum(args)
        log.debug('sym_sum(%s) -> %s', args, r)
        return r
    if hasattr(expr.func, '_torch_handler_name'):
        handler_name = expr.func._torch_handler_name
    else:
        handler_name = handlers()[expr.func]
    handler = getattr(analysis, handler_name)
    try:
        if handler_name in ASSOCIATIVE_OPS:
            if len(args) <= 1:
                raise AssertionError('associative op needs >1 args')
            acc = handler(args[0], args[1])
            for i in range(2, len(args)):
                acc = handler(acc, args[i])
            log.debug('%s(%s) -> %s', handler_name, args, acc)
            return acc
        else:
            r = handler(*args)
            log.debug('%s(%s) -> %s', handler_name, args, r)
            return r
    except NotImplementedError:
        raise
    except Exception:
        log.warning('failed while executing %s(%s)', handler_name, args)
        raise

def asarray_tuplesafe(values: Iterable, dtype: NpDtype | None=None) -> ArrayLike:
    if not (isinstance(values, (list, tuple)) or hasattr(values, '__array__')):
        values = list(values)
    elif <MASK>:
        return values._values
    elif isinstance(values, ABCSeries):
        return values._values
    if isinstance(values, list) and dtype in [np.object_, object]:
        return construct_1d_object_array_from_listlike(values)
    try:
        result = np.asarray(values, dtype=dtype)
    except ValueError:
        return construct_1d_object_array_from_listlike(values)
    if issubclass(result.dtype.type, str):
        result = np.asarray(values, dtype=object)
    if result.ndim == 2:
        values = [tuple(x) for x in values]
        result = construct_1d_object_array_from_listlike(values)
    return result

def _work(self):

    @torch.compile(backend=self.backend(), fullgraph=True, dynamic=self.is_dynamic())
    def f(a, b):
        result = a.clone()
        for i in range(1000):
            if <MASK>:
                result = result + b
            elif i % 3 == 1:
                result = result + 8 * b
            else:
                result = result.sin()
        return result
    with fresh_cache():
        f(self.a, self.b)

def get_model_hash(model):
    """Calculate a 64-bit integer hash for a TensorFlow Lite model based on its structure.

  Args:
      model: A TensorFlow Lite model object.

  Returns:
      int: A 64-bit integer hash value representing the model structure.
  """
    hash_value = 0
    for subgraph in model.subgraphs:
        if subgraph.operators is not None:
            hash_value = update_hash_with_primitive_value(hash_value, len(subgraph.operators))
            for operator in subgraph.operators:
                if operator.inputs is not None:
                    hash_value = update_hash_with_array(hash_value, operator.inputs)
                if operator.outputs is not None:
                    hash_value = update_hash_with_array(hash_value, operator.outputs)
        if subgraph.tensors is not None:
            hash_value = update_hash_with_primitive_value(hash_value, len(subgraph.tensors))
            for tensor in subgraph.tensors:
                if tensor.buffer is not None:
                    buffer = model.buffers[tensor.buffer]
                    if buffer.data is not None:
                        hash_value = update_hash_with_primitive_value(hash_value, len(buffer.data))
                if tensor.shape is not None:
                    hash_value = update_hash_with_array(hash_value, tensor.shape)
        if subgraph.inputs is not None:
            hash_value = update_hash_with_primitive_value(hash_value, len(subgraph.inputs))
        if <MASK>:
            hash_value = update_hash_with_primitive_value(hash_value, len(subgraph.outputs))
    return hash_value

def make_state(self, nodes=None, at_end=True, real_apps=None):
    """
        Given a migration node or nodes, return a complete ProjectState for it.
        If at_end is False, return the state before the migration has run.
        If nodes is not provided, return the overall most current project
        state.
        """
    if nodes is None:
        nodes = list(self.leaf_nodes())
    if <MASK>:
        return ProjectState()
    if not isinstance(nodes[0], tuple):
        nodes = [nodes]
    plan = self._generate_plan(nodes, at_end)
    project_state = ProjectState(real_apps=real_apps)
    for node in plan:
        project_state = self.nodes[node].mutate_state(project_state, preserve=False)
    return project_state

def prepare_content_length(self, body):
    """Prepare Content-Length header based on request method and body"""
    if body is not None:
