        if length:
            self.headers['Content-Length'] = builtin_str(length)
    elif <MASK>:
        self.headers['Content-Length'] = '0'

@staticmethod
def create(h: Any, ensure_batched: bool=True, ensure_present: bool=True) -> TensorInfo:
    from . import Dim, DimEntry, Tensor
    if Tensor.check_exact(h):
        return TensorInfo(h._get_tensor(), h._get_levels(), h._get_has_device(), h._get_batchtensor() if ensure_batched else None)
    elif <MASK>:
        tensor = h._get_range() if h.is_bound else None
        batchtensor = h._get_batchtensor() if ensure_batched and h.is_bound else None
        return TensorInfo(tensor, [DimEntry(h)], False, batchtensor)
    elif isinstance(h, torch.Tensor):
        levels = []
        for i in range(-h.dim(), 0):
            levels.append(DimEntry(i))
        return TensorInfo(h, levels, True, h)
    else:
        if ensure_present:
            raise ValueError('expected a tensor object')
        return TensorInfo(None, [], False, None)

def clean_fill_method(method: Literal['ffill', 'pad', 'bfill', 'backfill', 'nearest'], *, allow_nearest: bool=False) -> Literal['pad', 'backfill', 'nearest']:
    if <MASK>:
        method = method.lower()
        if method == 'ffill':
            method = 'pad'
        elif method == 'bfill':
            method = 'backfill'
    valid_methods = ['pad', 'backfill']
    expecting = 'pad (ffill) or backfill (bfill)'
    if allow_nearest:
        valid_methods.append('nearest')
        expecting = 'pad (ffill), backfill (bfill) or nearest'
    if method not in valid_methods:
        raise ValueError(f'Invalid fill method. Expecting {expecting}. Got {method}')
    return method

@staticmethod
def drop_unused_symbols(index: Union[int, sympy.Expr], var_names: list[sympy.Expr], sizes: list[sympy.Expr]) -> None:
    """
        Reduction has last (reduced) dim in its sizes, but
        downstream users won't.  Normalize this away.
        """
    if <MASK>:
        return
    free_symbols = index.free_symbols
    while var_names and var_names[-1] not in free_symbols:
        var_names.pop()
        sizes.pop()

def _check_filter_item(self, obj, field_name, label):
    """Check one item of `filter_vertical` or `filter_horizontal`, i.e.
        check that given field exists and is a ManyToManyField."""
    try:
        field = obj.model._meta.get_field(field_name)
    except FieldDoesNotExist:
        return refer_to_missing_field(field=field_name, option=label, obj=obj, id='admin.E019')
    else:
        if <MASK>:
            return must_be('a many-to-many field', option=label, obj=obj, id='admin.E020')
        elif not field.remote_field.through._meta.auto_created:
            return [checks.Error(f"The value of '{label}' cannot include the ManyToManyField '{field_name}', because that field manually specifies a relationship model.", obj=obj.__class__, id='admin.E013')]
        else:
            return []

def get_constant(x):
    if <MASK>:
