@register_decomposition(aten._log_softmax)
@out_wrapper(exact_dtype=True)
def _log_softmax(x: Tensor, dim: int, half_to_float: bool):
    from torch.fx.experimental.symbolic_shapes import guard_or_false
    x = x.contiguous()
    if half_to_float:
        assert x.dtype == torch.half
    (computation_dtype, result_dtype) = utils.elementwise_dtypes(x, type_promotion_kind=utils.ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
    x = x.to(computation_dtype)
    if guard_or_false(x.numel() == 0):
        shifted = x
    else:
        x_max = torch.amax(x, dim, keepdim=True)
        shifted = x - x_max
    shifted_logsumexp = torch.log(torch.sum(torch.exp(shifted), dim, keepdim=True))
    result = shifted - shifted_logsumexp
    if <MASK>:
        result = result.to(result_dtype)
    return result

def _next_line(self) -> list[Scalar]:
    if isinstance(self.data, list):
        while self.skipfunc(self.pos):
            if self.pos >= len(self.data):
                break
            self.pos += 1
        while True:
            try:
                line = self._check_comments([self.data[self.pos]])[0]
                self.pos += 1
                if not self.skip_blank_lines and (self._is_line_empty(self.data[self.pos - 1]) or line):
                    break
                if self.skip_blank_lines:
                    ret = self._remove_empty_lines([line])
                    if <MASK>:
                        line = ret[0]
                        break
            except IndexError as err:
                raise StopIteration from err
    else:
        while self.skipfunc(self.pos):
            self.pos += 1
            next(self.data)
        while True:
            orig_line = self._next_iter_line(row_num=self.pos + 1)
            self.pos += 1
            if orig_line is not None:
                line = self._check_comments([orig_line])[0]
                if self.skip_blank_lines:
                    ret = self._remove_empty_lines([line])
                    if ret:
                        line = ret[0]
                        break
                elif self._is_line_empty(orig_line) or line:
                    break
    if self.pos == 1:
        line = self._check_for_bom(line)
    self.line_pos += 1
    self.buf.append(line)
    return line

def getuseblocks(pymod):
