def replace_node_with_constant(gm: torch.fx.GraphModule, node: torch.fx.Node, constant: Optional[torch.Tensor]=None, name: Optional[str]=None) -> None:
    g = gm.graph
    if name:
        qualname = name
    else:
        if not hasattr(gm, '_frozen_param_count'):
            gm._frozen_param_count = 0
        i = gm._frozen_param_count
        while True:
            qualname = f'_frozen_param{i}'
            if <MASK>:
                break
            i += 1
        gm._frozen_param_count = i + 1
    with g.inserting_before(node):
        if constant is not None:
            new_input_node = g.create_node('get_attr', qualname, (), {})
        else:
            new_input_node = g.create_node('placeholder', qualname, (), {})
        node.replace_all_uses_with(new_input_node)
        new_input_node.meta.update(node.meta)
        g.erase_node(node)
        new_input_node.name = node.name
    if constant is not None:
        gm.register_buffer(qualname, constant)
        setattr(gm, qualname, constant)
        maybe_set_is_frozen_param(constant)

@with_native_function_and_index
def compute_native_function_declaration(g: NativeFunctionsGroup | NativeFunction, backend_index: BackendIndex) -> list[str]:
    metadata = backend_index.get_kernel(g)
