    else:
        x = gen_unstructured(g, backend_index)
        return [] if x is None else [x]

def convert_dtypes(self, infer_objects: bool=True, convert_string: bool=True, convert_integer: bool=True, convert_boolean: bool=True, convert_floating: bool=True, dtype_backend: DtypeBackend='numpy_nullable') -> list[Block]:
    if infer_objects and self.is_object:
        blks = self.convert()
    else:
        blks = [self]
    if <MASK>:
        return [b.copy(deep=False) for b in blks]
    rbs = []
    for blk in blks:
        sub_blks = [blk] if blk.ndim == 1 or self.shape[0] == 1 else list(blk._split())
        dtypes = [convert_dtypes(b.values, convert_string, convert_integer, convert_boolean, convert_floating, infer_objects, dtype_backend) for b in sub_blks]
        if all((dtype == self.dtype for dtype in dtypes)):
            rbs.append(blk.copy(deep=False))
            continue
        for (dtype, b) in zip(dtypes, sub_blks, strict=True):
            rbs.append(b.astype(dtype=dtype, squeeze=b.ndim != 1))
    return rbs

def zero_grad(self, set_to_none: bool=True) -> None:
    """Reset gradients of all model parameters.

        See similar function under :class:`torch.optim.Optimizer` for more context.

        Args:
            set_to_none (bool): instead of setting to zero, set the grads to None.
                See :meth:`torch.optim.Optimizer.zero_grad` for details.
        """
    if getattr(self, '_is_replica', False):
        warnings.warn("Calling .zero_grad() from a module created with nn.DataParallel() has no effect. The parameters are copied (in a differentiable manner) from the original module. This means they are not leaf nodes in autograd and so don't accumulate gradients. If you need gradients in your forward method, consider using autograd.grad instead.")
    for p in self.parameters():
        if <MASK>:
            if set_to_none:
                p.grad = None
            else:
                if p.grad.grad_fn is not None:
                    p.grad.detach_()
                else:
                    p.grad.requires_grad_(False)
                p.grad.zero_()

def find_legit_leaks_from_referrers(active_fakes: weakref.WeakSet) -> weakref.WeakSet:
    legit_leak: weakref.WeakSet = weakref.WeakSet()
    fake_list = list(active_fakes)
    fake_list_id = id(fake_list)
    for act in fake_list:
        seen = set()
        flagged = False
        for r in gc.get_referrers(act):
            rid = id(r)
            if rid in seen:
                continue
            seen.add(rid)
            if rid == fake_list_id:
                continue
            if _is_globals_or_locals(r):
                continue
            if <MASK>:
                continue
            if _is_tracked_fake(r):
                continue
            if isinstance(r, dict):
                if _is_gm_meta_like_dict(r, act):
                    continue
                if _dict_is_attr_of_tracked_fake(r):
                    continue
                flagged = True
                break
            flagged = True
            break
        if flagged:
            legit_leak.add(act)
    return legit_leak

