def attach(self, filename=None, content=None, mimetype=None):
    """
        Attach a file with the given filename and content. The filename can
        be omitted and the mimetype is guessed, if not provided.

        If the first parameter is a MIMEBase subclass, insert it directly
        into the resulting message attachments.

        For a text/* mimetype (guessed or specified), when a bytes object is
        specified as content, decode it as UTF-8. If that fails, set the
        mimetype to DEFAULT_ATTACHMENT_MIME_TYPE and don't decode the content.
        """
    if <MASK>:
        if content is not None or mimetype is not None:
            raise ValueError('content and mimetype must not be given when a MIMEPart instance is provided.')
        self.attachments.append(filename)
    elif isinstance(filename, MIMEBase):
        warnings.warn('MIMEBase attachments are deprecated. Use an email.message.MIMEPart instead.', RemovedInDjango70Warning)
        if content is not None or mimetype is not None:
            raise ValueError('content and mimetype must not be given when a MIMEBase instance is provided.')
        self.attachments.append(filename)
    elif content is None:
        raise ValueError('content must be provided.')
    else:
        mimetype = mimetype or mimetypes.guess_type(filename)[0] or DEFAULT_ATTACHMENT_MIME_TYPE
        (basetype, subtype) = mimetype.split('/', 1)
        if basetype == 'text':
            if isinstance(content, bytes):
                try:
                    content = content.decode()
                except UnicodeDecodeError:
                    mimetype = DEFAULT_ATTACHMENT_MIME_TYPE
        self.attachments.append(EmailAttachment(filename, content, mimetype))

