    for ((type2, type3), value) in product(types, values):
        if type2 not in supported_dtypes or type3 not in supported_dtypes:
            continue
        if type(value) is complex and type2 is not torch.complex128:
            continue
        arg1 = make_arg([5, 5], dtype=dtype)
