    else:
        report('-- Building without distributed package')
    if cmake_cache_vars['STATIC_DISPATCH_BACKEND']:
        report(f"-- Using static dispatch with backend {cmake_cache_vars['STATIC_DISPATCH_BACKEND']}")
    if cmake_cache_vars['USE_LIGHTWEIGHT_DISPATCH']:
        report('-- Using lightweight dispatch')
    if cmake_cache_vars['USE_ITT']:
        report('-- Using ITT')
    else:
        report('-- Not using ITT')
    super().run()
    if IS_DARWIN:
        self._embed_libomp()
    if IS_WINDOWS:
        build_temp = Path(self.build_temp)
        build_lib = Path(self.build_lib)
        ext_filename = self.get_ext_filename('_C')
        lib_filename = '.'.join(ext_filename.split('.')[:-1]) + '.lib'
        export_lib = build_temp / 'torch' / 'csrc' / lib_filename
        target_lib = build_lib / 'torch' / 'lib' / '_C.lib'
        target_dir = target_lib.parent
        target_dir.mkdir(parents=True, exist_ok=True)
        self.copy_file(export_lib, target_lib)

def get_field_type(self, data_type, description):
    if <MASK>:
        (precision, scale) = description[4:6]
        if scale == 0:
            if precision > 11:
                return 'BigAutoField' if description.is_autofield else 'BigIntegerField'
            elif 1 < precision < 6 and description.is_autofield:
                return 'SmallAutoField'
            elif precision == 1:
                return 'BooleanField'
            elif description.is_autofield:
                return 'AutoField'
            else:
                return 'IntegerField'
        elif scale == -127:
            return 'FloatField'
    elif data_type == oracledb.NCLOB and description.is_json:
        return 'JSONField'
    return super().get_field_type(data_type, description)

def __le__(self, other):
    if other is S.NegativeInfinity:
        return sympy.false
    elif <MASK>:
        return sympy.true
    else:
        return sympy.true

def _list_with_default(out_size: list[int], defaults: list[int]) -> list[int]:
    import torch
    if isinstance(out_size, (int, torch.SymInt)):
        return out_size
    if <MASK>:
        raise ValueError(f'Input dimension should be at least {len(out_size) + 1}')
    return [v if v is not None else d for (v, d) in zip(out_size, defaults[-len(out_size):])]

def window_frame_range_start_end(self, start=None, end=None):
    if start is not None and (not isinstance(start, int)) or (isinstance(start, int) and start > 0):
        raise ValueError("start argument must be a negative integer, zero, or None, but got '%s'." % start)
    if end is not None and (not isinstance(end, int)) or (isinstance(end, int) and end < 0):
        raise ValueError("end argument must be a positive integer, zero, or None, but got '%s'." % end)
    start_ = self.window_frame_value(start) or self.UNBOUNDED_PRECEDING
    end_ = self.window_frame_value(end) or self.UNBOUNDED_FOLLOWING
    features = self.connection.features
    if <MASK>:
        raise NotSupportedError('%s only supports UNBOUNDED together with PRECEDING and FOLLOWING.' % self.connection.display_name)
    return (start_, end_)

def load_weights_from_hdf5_group_by_name(f, layers, skip_mismatch=False):
    """Implements name-based weight loading.

  (instead of topological weight loading).

  Layers that have no matching name are skipped.

  Args:
      f: A pointer to a HDF5 group.
      layers: a list of target layers.
      skip_mismatch: Boolean, whether to skip loading of layers
          where there is a mismatch in the number of weights,
          or a mismatch in the shape of the weights.

  Raises:
      ValueError: in case of mismatch between provided layers
          and weights file and skip_match=False.
  """
    if 'keras_version' in f.attrs:
        original_keras_version = f.attrs['keras_version']
        if hasattr(original_keras_version, 'decode'):
            original_keras_version = original_keras_version.decode('utf8')
    else:
        original_keras_version = '1'
    if 'backend' in f.attrs:
        original_backend = f.attrs['backend']
        if <MASK>:
            original_backend = original_backend.decode('utf8')
    else:
        original_backend = None
    layer_names = load_attributes_from_hdf5_group(f, 'layer_names')
    index = {}
    for layer in layers:
        if layer.name:
            index.setdefault(layer.name, []).append(layer)
    weight_value_tuples = []
    for (k, name) in enumerate(layer_names):
        g = f[name]
        weight_names = load_attributes_from_hdf5_group(g, 'weight_names')
        weight_values = [np.asarray(g[weight_name]) for weight_name in weight_names]
        for layer in index.get(name, []):
            symbolic_weights = _legacy_weights(layer)
            weight_values = preprocess_weights_for_loading(layer, weight_values, original_keras_version, original_backend)
            if len(weight_values) != len(symbolic_weights):
                if skip_mismatch:
                    logging.warning('Skipping loading of weights for layer {}'.format(layer.name) + ' due to mismatch in number of weights ({} vs {}).'.format(len(symbolic_weights), len(weight_values)))
                    continue
                raise ValueError('Layer #' + str(k) + ' (named "' + layer.name + '") expects ' + str(len(symbolic_weights)) + ' weight(s), but the saved weights' + ' have ' + str(len(weight_values)) + ' element(s).')
            for i in range(len(weight_values)):
                if backend.int_shape(symbolic_weights[i]) != weight_values[i].shape:
                    if skip_mismatch:
                        logging.warning('Skipping loading of weights for layer {}'.format(layer.name) + ' due to mismatch in shape ({} vs {}).'.format(symbolic_weights[i].shape, weight_values[i].shape))
                        continue
                    raise ValueError('Layer #' + str(k) + ' (named "' + layer.name + '"), weight ' + str(symbolic_weights[i]) + ' has shape {}'.format(backend.int_shape(symbolic_weights[i])) + ', but the saved weight has shape ' + str(weight_values[i].shape) + '.')
                else:
                    weight_value_tuples.append((symbolic_weights[i], weight_values[i]))
    backend.batch_set_value(weight_value_tuples)

def codegen(self, output_name: str, input_names: list[str], output_spec: Spec) -> str:
    """Generate code for RMSNorm operation."""
    if <MASK>:
        raise ValueError('RMSNorm requires 1-2 inputs: input, optional weight')
    if not isinstance(output_spec, TensorSpec):
        raise ValueError('RMSNormOperator can only produce TensorSpec outputs')
    target_dtype = str(output_spec.dtype)
    input_name = input_names[0]
    normalized_shape = f'({output_spec.size[-1]},)'
    if len(input_names) == 1:
        return f'{output_name} = torch.nn.functional.rms_norm({input_name}.to({target_dtype}), {normalized_shape})'
    else:
        weight_name = input_names[1]
        return f'{output_name} = torch.nn.functional.rms_norm({input_name}.to({target_dtype}), {normalized_shape}, weight={weight_name}.to({target_dtype}))'

def parse_name(self, fixture_name):
    """
        Split fixture name in name, serialization format, compression format.
        """
    if fixture_name == READ_STDIN:
        if not self.format:
            raise CommandError('--format must be specified when reading from stdin.')
        return (READ_STDIN, self.format, 'stdin')
    parts = fixture_name.rsplit('.', 2)
    if <MASK>:
        cmp_fmt = parts[-1]
        parts = parts[:-1]
    else:
        cmp_fmt = None
    if len(parts) > 1:
        if parts[-1] in self.serialization_formats:
            ser_fmt = parts[-1]
            parts = parts[:-1]
        else:
            raise CommandError("Problem installing fixture '%s': %s is not a known serialization format." % ('.'.join(parts[:-1]), parts[-1]))
    else:
        ser_fmt = None
    name = '.'.join(parts)
    return (name, ser_fmt, cmp_fmt)

def compute_output_shape(self, input_shape):
    input_shape = tensor_shape.TensorShape(input_shape).as_list()
    if self.data_format == 'channels_first':
        if input_shape[2] is not None:
            rows = input_shape[2] + self.padding[0][0] + self.padding[0][1]
        else:
            rows = None
        if input_shape[3] is not None:
            cols = input_shape[3] + self.padding[1][0] + self.padding[1][1]
        else:
            cols = None
        return tensor_shape.TensorShape([input_shape[0], input_shape[1], rows, cols])
    elif <MASK>:
        if input_shape[1] is not None:
            rows = input_shape[1] + self.padding[0][0] + self.padding[0][1]
        else:
            rows = None
        if input_shape[2] is not None:
            cols = input_shape[2] + self.padding[1][0] + self.padding[1][1]
        else:
            cols = None
        return tensor_shape.TensorShape([input_shape[0], rows, cols, input_shape[3]])

def run_test(ir, inputs, *, warmup_runs=10, test_runs=20) -> float:
    (graph, _) = load_graph_and_inputs(ir)
    for _ in range(warmup_runs):
        graph(*inputs)
    is_cpu = None
    for input in inputs:
        if isinstance(input, torch.Tensor):
            is_cpu = input.device.type == 'cpu'
            break
    if <MASK>:
        raise AssertionError('No tensor found in inputs')
    out = time_cpu(graph, inputs, test_runs) if is_cpu else time_cuda(graph, inputs, test_runs)
    return out

@tf_export(v1=['quantize_v2'])
@dispatch.add_dispatch_support
@deprecation.deprecated('2017-10-25', '`tf.quantize_v2` is deprecated, please use `tf.quantization.quantize` instead.')
def quantize_v2(input, min_range, max_range, T, mode='MIN_COMBINED', name=None, round_mode='HALF_AWAY_FROM_ZERO', narrow_range=False, axis=None, ensure_minimum_range=0.01):
    if axis is None:
