    return gen_array_ops.quantize_v2(input, min_range, max_range, T=T, mode=mode, name=name, round_mode=round_mode, narrow_range=narrow_range, axis=axis)

def _symbolic_add_metric(self, value, aggregation=None, name=None):
    base_layer_utils.check_graph_consistency(value, method='add_metric')
    match = self._get_existing_metric(name)
    if aggregation is None:
        if <MASK>:
            result_tensor = value
            metric_obj = match
        elif hasattr(value, '_metric_obj'):
            result_tensor = value
            metric_obj = result_tensor._metric_obj
            self._metrics.append(metric_obj)
        else:
            raise ValueError("We do not support adding an aggregated metric result tensor that is not the output of a `tf.keras.metrics.Metric` metric instance. Without having access to the metric instance we cannot reset the state of a metric after every epoch during training. You can create a `tf.keras.metrics.Metric` instance and pass the result here or pass an un-aggregated result with `aggregation` parameter set as `mean`. For example: `self.add_metric(tf.reduce_sum(inputs), name='mean_activation', aggregation='mean')`")
    elif match:
        result_tensor = match(value)
        metric_obj = match
    else:
        (metric_obj, result_tensor) = base_layer_utils.create_mean_metric(value, name)
        self._metrics.append(metric_obj)

def get_topological_order(self) -> list[str]:
    """
        Get nodes in topological order (dependencies before dependents).

        Returns:
            List of node IDs in topological order
        """
    visited = set()
    temp_visited = set()
    result = []

    def visit(node_id: str):
        if node_id in temp_visited:
            raise ValueError(f'Cycle detected involving node {node_id}')
        if node_id in visited:
            return
        temp_visited.add(node_id)
        node = self.nodes[node_id]
        for input_node_id in node.input_nodes:
            if input_node_id in self.nodes:
                visit(input_node_id)
        temp_visited.remove(node_id)
        visited.add(node_id)
        result.append(node_id)
    for node_id in self.nodes:
        if <MASK>:
            visit(node_id)
    return result

@wraps(func)
def wrapper(*args, **kwargs):
    original_fully_shard: Any = torch.distributed.fsdp.fully_shard
    for mode in FullyShardMode:
        if <MASK>:
            warnings.warn('Inductor on GPU needs Triton and recent GPU arch')
            continue
        original_skip_fsdp_hooks = torch._dynamo.config.skip_fsdp_hooks
        original_compile_threads = torch._inductor.config.compile_threads
        torch.distributed.barrier()
        if mode == FullyShardMode.EAGER:
            fully_shard_patch = original_fully_shard
        elif mode == FullyShardMode.COMPILED_COMPUTE:
            torch._dynamo.config.skip_fsdp_hooks = True
            torch._inductor.config.compile_threads = 1
            fully_shard_patch = fully_shard_with_compiled_compute
        else:
            raise NotImplementedError(f'Need to implement FullyShardMode={mode}')
        func.__globals__[original_fully_shard.__name__] = fully_shard_patch
        func(*args, **kwargs)
        torch.distributed.barrier()
        func.__globals__[original_fully_shard.__name__] = original_fully_shard
        torch._dynamo.config.skip_fsdp_hooks = original_skip_fsdp_hooks
        torch._inductor.config.compile_threads = original_compile_threads

def setitem(self: Any, index: Any, rhs: Any) -> None:
    """Set values in tensor using first-class dimensions."""
    from . import DimensionBindError, TensorInfo
    iinfo = getsetitem(self, index, has_dims(self) or has_dims(rhs))
    if <MASK>:
        torch._C.TensorBase.__setitem__(self, index, rhs)
        return
    rhs_info = TensorInfo.create(rhs, False, False)
    if rhs_info:
        for l in rhs_info.levels:
            if not l.is_positional():
                found = False
                for result_level in iinfo.result_levels:
                    if not result_level.is_positional() and result_level.dim() is l.dim():
                        found = True
                        break
                if not found:
                    result_dims: list[Union[int, Dim]] = []
                    for rl in iinfo.result_levels:
                        if rl.is_positional():
                            result_dims.append(rl.position())
                        else:
                            result_dims.append(rl.dim())
                    raise DimensionBindError(f'rhs of setitem contains dimension {l.dim()!r} which is not in the dimension on the left ({tuple(result_dims)!r})')
        assert rhs_info.tensor is not None, 'Cannot match levels on None tensor'
        matched_rhs = _match_levels(rhs_info.tensor, rhs_info.levels, iinfo.result_levels)
    else:
        matched_rhs = rhs
    if iinfo.advanced_indexing:
        tup = slice_to_tuple(iinfo.flat_inputs)
        if iinfo.self_tensor is None:
            raise RuntimeError('Cannot setitem on None tensor')
        torch._C.TensorBase.__setitem__(iinfo.self_tensor, tup, matched_rhs)
    else:
        if iinfo.self_tensor is None:
            raise RuntimeError('Cannot copy to None tensor')
        iinfo.self_tensor.copy_(matched_rhs)

def get_config_heuristics(self, device_type: Optional[str]='cuda') -> BaseConfigHeuristic:
    if device_type == 'cuda':
        if torch.version.hip is None:
            return CUDAConfigHeuristic()
        else:
