    else:
        return BaseConfigHeuristic()

def _to(self, dtype):
    if <MASK>:
        raise TypeError(f"Argument 'dtype' must be torch.dtype, not {type(dtype)}")
    storage = torch.tensor([], dtype=self.dtype, device=self.device).set_(self).to(dtype)._typed_storage()
    if storage.data_ptr() == self.data_ptr():
        storage = storage.clone()
    return storage

def _fit_transform_in_place(self, K):
    """Fit's using kernel K"""
    K = self._centerer.fit(K).transform(K, copy=False)
    if self.n_components is None:
        n_components = K.shape[0]
    else:
        n_components = min(K.shape[0], self.n_components)
    if self.eigen_solver == 'auto':
        if K.shape[0] > 200 and n_components < 10:
            eigen_solver = 'arpack'
        else:
            eigen_solver = 'dense'
    else:
        eigen_solver = self.eigen_solver
    if eigen_solver == 'dense':
        (self.eigenvalues_, self.eigenvectors_) = eigh(K, subset_by_index=(K.shape[0] - n_components, K.shape[0] - 1))
    elif <MASK>:
        v0 = _init_arpack_v0(K.shape[0], self.random_state)
        (self.eigenvalues_, self.eigenvectors_) = eigsh(K, n_components, which='LA', tol=self.tol, maxiter=self.max_iter, v0=v0)
    elif eigen_solver == 'randomized':
        (self.eigenvalues_, self.eigenvectors_) = _randomized_eigsh(K, n_components=n_components, n_iter=self.iterated_power, random_state=self.random_state, selection='module')
    self.eigenvalues_ = _check_psd_eigenvalues(self.eigenvalues_, enable_warnings=False)
    (self.eigenvectors_, _) = svd_flip(u=self.eigenvectors_, v=None)
    indices = self.eigenvalues_.argsort()[::-1]
    self.eigenvalues_ = self.eigenvalues_[indices]
    self.eigenvectors_ = self.eigenvectors_[:, indices]
    if self.remove_zero_eig or self.n_components is None:
        self.eigenvectors_ = self.eigenvectors_[:, self.eigenvalues_ > 0]
        self.eigenvalues_ = self.eigenvalues_[self.eigenvalues_ > 0]
    return K

def crack2fortrangen(block, tab='\n', as_interface=False):
    global skipfuncs, onlyfuncs
    setmesstext(block)
    ret = ''
    if isinstance(block, list):
        for g in block:
            if g and g['block'] in ['function', 'subroutine']:
                if g['name'] in skipfuncs:
                    continue
                if onlyfuncs and g['name'] not in onlyfuncs:
                    continue
            ret = ret + crack2fortrangen(g, tab, as_interface=as_interface)
        return ret
    prefix = ''
    name = ''
    args = ''
    blocktype = block['block']
    if blocktype == 'program':
        return ''
    argsl = []
    if 'name' in block:
        name = block['name']
    if 'args' in block:
        vars = block['vars']
        for a in block['args']:
            a = expr2name(a, block, argsl)
            if not isintent_callback(vars[a]):
                argsl.append(a)
        if block['block'] == 'function' or argsl:
            args = f"({','.join(argsl)})"
    f2pyenhancements = ''
    if 'f2pyenhancements' in block:
        for k in list(block['f2pyenhancements'].keys()):
            f2pyenhancements = '%s%s%s %s' % (f2pyenhancements, tab + tabchar, k, block['f2pyenhancements'][k])
    intent_lst = block.get('intent', [])[:]
    if blocktype == 'function' and 'callback' in intent_lst:
        intent_lst.remove('callback')
    if intent_lst:
        f2pyenhancements = '%s%sintent(%s) %s' % (f2pyenhancements, tab + tabchar, ','.join(intent_lst), name)
    use = ''
    if 'use' in block:
        use = use2fortran(block['use'], tab + tabchar)
    common = ''
    if 'common' in block:
        common = common2fortran(block['common'], tab + tabchar)
    if name == 'unknown_interface':
        name = ''
    result = ''
    if 'result' in block:
        result = f" result ({block['result']})"
        if block['result'] not in argsl:
            argsl.append(block['result'])
    body = crack2fortrangen(block['body'], tab + tabchar, as_interface=as_interface)
    vars = vars2fortran(block, block['vars'], argsl, tab + tabchar, as_interface=as_interface)
    mess = ''
    if 'from' in block and (not as_interface):
        mess = f"! in {block['from']}"
    if 'entry' in block:
        entry_stmts = ''
        for (k, i) in list(block['entry'].items()):
            entry_stmts = f"{entry_stmts}{tab + tabchar}entry {k}({','.join(i)})"
        body = body + entry_stmts
    if <MASK>:
        name = ''
    ret = '%s%s%s %s%s%s %s%s%s%s%s%s%send %s %s' % (tab, prefix, blocktype, name, args, result, mess, f2pyenhancements, use, vars, common, body, tab, blocktype, name)
    return ret

def _test_determinism(self, case, seed_type):
    seeds = [(x, y) for x in range(5) for y in range(5)] * 3
    with self.test_session(), ops.device(get_device().name):
        (_, stateless_op, _) = case
        if context.executing_eagerly():
            values = [(seed, stateless_op(seed=constant_op.constant(seed, seed_type))) for seed in seeds]
        else:
            seed_t = array_ops.placeholder(seed_type, shape=[2])
            pure = stateless_op(seed=seed_t)
            values = [(seed, pure.eval(feed_dict={seed_t: seed})) for seed in seeds]
        for (s0, v0) in values:
            for (s1, v1) in values:
                if <MASK>:
                    self.assertEqual(s0 == s1, np.all(v0 == v1))
                elif s0 == s1:
                    self.assertAllEqual(v0, v1)

def fetch_sym_proxy(tracer: _ProxyTracer) -> Callable[[PySymType], Union[bool, int, float, Proxy]]:

    def inner(e: PySymType) -> Union[int, bool, float, Proxy]:
        n = e.node
        if <MASK>:
            return n.constant
        if e.node.expr.is_number:
            if isinstance(e, SymBool):
                return bool(e.node.expr)
            elif isinstance(e, SymInt):
                return int(e.node.expr)
            return float(e.node.expr)
        else:
            assert isinstance(e, py_sym_types)
            return get_proxy_slot(e, tracer).force()
    return inner

def gen_foreach_derivativeinfo(foreach_function: NativeFunction, functional_info_by_signature: dict[FunctionSchema, dict[str, DifferentiabilityInfo]], non_functional_info_by_signature: dict[FunctionSchema, dict[str, DifferentiabilityInfo]], dispatch_key: str='Default') -> tuple[DifferentiabilityInfo | None, bool]:
    """Generate DifferentiabilityInfo for out-place foreach function, return the existing one for in-place.

    The second return value indicates whether the info is generated in this function.
    """
    ref_diff_info: DifferentiabilityInfo | None = None
    for (function_schema, diff_info) in functional_info_by_signature.items():
        if not is_reference_for_foreach(foreach_function, function_schema):
            continue
        ref_diff_info = diff_info[dispatch_key]
        if ref_diff_info is not None:
            break
    if <MASK>:
        for (function_schema, diff_info) in non_functional_info_by_signature.items():
            if not is_reference_for_foreach(foreach_function, function_schema):
                continue
            ref_diff_info = diff_info[dispatch_key]
            if ref_diff_info is not None:
                break
    if ref_diff_info is None:
        return (None, False)
    if foreach_function.func.kind() == SchemaKind.inplace:
        return (ref_diff_info, False)
    (map_refarg2foreacharg, map_name2arg) = ({}, {})
    for (i, (arg, ref_arg)) in enumerate(zip(foreach_function.func.arguments.flat_non_out, function_schema.arguments.flat_non_out)):
        map_refarg2foreacharg[ref_arg.name] = arg.name
        map_name2arg[arg.name] = arg
    (all_saved_inputs, all_saved_outputs, all_var_names) = ([], [], [])
    modified_derivative_formulas = []
    for (i, derivative) in enumerate(ref_diff_info.derivatives):
        modified_formula = derivative.formula.replace('grad', 'grads[i]').replace('result', 'result[i]')
        (saved_inputs, saved_outputs) = ([], [])
        with local.parametrize(use_const_ref_for_mutable_tensors=foreach_function.use_const_ref_for_mutable_tensors, use_ilistref_for_tensor_lists=foreach_function.part_of_structured_group):
            for ref_input in derivative.saved_inputs:
                ref_input_jit_name = ref_input.expr.split('.')[0]
                mapped_name = map_refarg2foreacharg[ref_input_jit_name]
                if isinstance(map_name2arg[mapped_name].type, ListType):
                    mapped_expr = mapped_name + '[i]'
                else:
                    mapped_expr = mapped_name
                new_expr = ref_input.expr.replace(ref_input_jit_name, mapped_expr)
                modified_formula = modified_formula.replace(cast(str, ref_input.nctype.name), new_expr)
                nctype = cpp.argument_type(map_name2arg[mapped_name], binds=mapped_name)
                canonical_nctype = NamedCType(nctype.name, nctype.type.remove_const_ref())
                saved_inputs.append(SavedAttribute(nctype=canonical_nctype, expr=mapped_name))
            for ref_output in derivative.saved_outputs:
                if ref_output.nctype.name == 'result':
                    saved_outputs.append(SavedAttribute(nctype=NamedCType(name='result', type=BaseCType(tensorListT)), expr='result'))
                else:
                    raise RuntimeError('')
        var_names = [map_refarg2foreacharg[var] for var in derivative.var_names]
        all_var_names.extend(var_names)
        all_saved_inputs.extend(saved_inputs)
        all_saved_outputs.extend(saved_outputs)
        modified_derivative = Derivative(formula=modified_formula, original_formula=derivative.formula, var_names=tuple(var_names), saved_inputs=tuple(saved_inputs), saved_outputs=tuple(saved_outputs), named_gradients=set())
        modified_derivative_formulas.append(modified_derivative)
    with local.parametrize(use_const_ref_for_mutable_tensors=foreach_function.use_const_ref_for_mutable_tensors, use_ilistref_for_tensor_lists=foreach_function.part_of_structured_group):
        args_with_derivatives = [Binding(name=arg.name, nctype=cpp.argument_type(arg, binds=arg.name), argument=arg, default=None) for arg in foreach_function.func.arguments.flat_non_out if arg.name in all_var_names]
    forward_derivatives: list[ForwardDerivative] = []
    fw_derivative: ForwardDerivative
    for fw_derivative in ref_diff_info.forward_derivatives:
        var_names: list[str] = list(fw_derivative.var_names)
        var_types: list[Type] = list(fw_derivative.var_types)
        required_inputs_fw_grad: list[str] = []
        required_inputs_primal: list[str] = []
        if fw_derivative.required_inputs_fw_grad is not None:
            required_inputs_fw_grad = list(fw_derivative.required_inputs_fw_grad)
        if fw_derivative.required_inputs_primal:
            required_inputs_primal = list(fw_derivative.required_inputs_primal)
        modified_formula = fw_derivative.formula
        if 'result' in modified_formula:
            modified_formula = fw_derivative.formula.replace('result', 'result[i]')
        for (foreach_arg, ref_arg) in zip(foreach_function.func.arguments.flat_non_out, ref_diff_info.func.func.arguments.flat_non_out):
            if isinstance(foreach_arg.type, ListType) and (not foreach_arg.type.is_tensor_like()):
                modified_formula = modified_formula.replace(ref_arg.name, foreach_arg.name + '[i]')
            elif foreach_arg.type.is_tensor_like():
                assert isinstance(foreach_arg.type, ListType) or (foreach_arg.type == BaseType(BaseTy.Tensor) and str(foreach_function.func.name) in _foreach_with_tensor_overload), f'{foreach_function.func.name}, {foreach_arg.type}'
                for suffix in ('_p', '_t'):
                    curr_expr = ref_arg.name + suffix
                    if curr_expr in modified_formula:
                        new_expr = foreach_arg.name + suffix
                        modified_formula = modified_formula.replace(curr_expr, new_expr)
            elif foreach_arg.name != ref_arg.name:
                modified_formula = modified_formula.replace(ref_arg.name, foreach_arg.name)
            for (i, name) in enumerate(var_names):
                if name == ref_arg.name:
                    var_names[i] = foreach_arg.name
                    var_types[i] = foreach_arg.type
            for (i, name) in enumerate(required_inputs_fw_grad):
                if name == ref_arg.name:
                    required_inputs_fw_grad[i] = foreach_arg.name
            for (i, name) in enumerate(required_inputs_primal):
                if name == ref_arg.name:
                    required_inputs_primal[i] = foreach_arg.name
        forward_derivatives.append(ForwardDerivative(formula=modified_formula, var_names=tuple(var_names), var_types=tuple(var_types), required_inputs_fw_grad=tuple(required_inputs_fw_grad), required_inputs_primal=tuple(required_inputs_primal), required_original_self_value=fw_derivative.required_original_self_value, is_reusing_outplace_formula=fw_derivative.is_reusing_outplace_formula))
    return (DifferentiabilityInfo(name=foreach_function.func.name.name.base, func=foreach_function, op=f'Foreach{ref_diff_info.op}{foreach_function.func.name.overload_name}', derivatives=modified_derivative_formulas, forward_derivatives=forward_derivatives, all_saved_inputs=tuple(set(all_saved_inputs)), all_saved_outputs=tuple(set(all_saved_outputs)), available_named_gradients=(), used_named_gradients=set(), args_with_derivatives=args_with_derivatives, non_differentiable_arg_names=[], output_differentiability=None, output_differentiability_conditions=None), True)

def get_qualified_name(function):
    if hasattr(function, '__qualname__'):
        return function.__qualname__
    if <MASK>:
        return function.im_class.__name__ + '.' + function.__name__
    return function.__name__

def configure(src_base_path, gen_path, debug=False):
    """Configure `src_base_path` to embed git hashes if available."""
    git_path = os.path.join(src_base_path, '.git')
    if os.path.exists(gen_path):
        if <MASK>:
            try:
                shutil.rmtree(gen_path)
            except OSError:
                raise RuntimeError('Cannot delete directory %s due to permission error, inspect and remove manually' % gen_path)
        else:
            raise RuntimeError('Cannot delete non-directory %s, inspect ', 'and remove manually' % gen_path)
    os.makedirs(gen_path)
    if not os.path.isdir(gen_path):
        raise RuntimeError('gen_git_source.py: Failed to create dir')
    spec = {}
    link_map = {'head': None, 'branch_ref': None}
    if not os.path.isdir(git_path):
        spec['git'] = False
        open(os.path.join(gen_path, 'head'), 'w').write('')
        open(os.path.join(gen_path, 'branch_ref'), 'w').write('')
    else:
        spec['git'] = True
        spec['path'] = src_base_path
        git_head_path = os.path.join(git_path, 'HEAD')
        spec['branch'] = parse_branch_ref(git_head_path)
        link_map['head'] = git_head_path
        if spec['branch'] is not None:
            link_map['branch_ref'] = os.path.join(git_path, *os.path.split(spec['branch']))
    for (target, src) in link_map.items():
        if src is None:
            open(os.path.join(gen_path, target), 'w').write('')
        elif not os.path.exists(src):
            open(os.path.join(gen_path, target), 'w').write('')
            spec['git'] = False
        else:
            try:
                if hasattr(os, 'symlink'):
                    os.symlink(src, os.path.join(gen_path, target))
                else:
                    shutil.copy2(src, os.path.join(gen_path, target))
            except OSError:
                shutil.copy2(src, os.path.join(gen_path, target))
    json.dump(spec, open(os.path.join(gen_path, 'spec.json'), 'w'), indent=2)
    if debug:
        print('gen_git_source.py: list %s' % gen_path)
        print('gen_git_source.py: %s' + repr(os.listdir(gen_path)))
        print('gen_git_source.py: spec is %r' % spec)

def get_schedule_ops(schedule: Union[str, type[_PipelineSchedule]], pp_degree: int, num_microbatches: int, num_stages_per_rank: Optional[int]=None, add_spacing: bool=False, with_comms: bool=False) -> list[list[Optional[_Action]]]:
    """
    Get all actions for a given schedule, pp_degree, and num_microbatches. The actions are returned in a list of lists
    where each inner list represents a rank and each element in the inner list represents an action.

    The schedule can be specified as a string which is passed into get_schedule_class() or a _PipelineSchedule instance.
    """
    if add_spacing and with_comms:
        raise ValueError('Cannot add spacing and view comms at the same time')
    if isinstance(schedule, str):
        schedule_class = get_schedule_class(schedule)
    elif <MASK>:
        schedule_class = schedule
    else:
        raise ValueError(f'Invalid schedule: {schedule}')
    mock_pipeline_stage = mock.create_autospec(PipelineStage, instance=True)
    mock_pipeline_stage.group_rank = 0
    mock_pipeline_stage.group_size = pp_degree
    mock_pipeline_stage.submod = None
    if issubclass(schedule_class, PipelineScheduleSingle):
        if num_stages_per_rank is None:
            num_stages_per_rank = 1
        assert num_stages_per_rank == 1
        stages = mock_pipeline_stage
        stages.num_stages = num_stages_per_rank * pp_degree
    elif issubclass(schedule_class, PipelineScheduleMulti):
        if num_stages_per_rank is None:
            num_stages_per_rank = 2
        assert num_stages_per_rank >= 2
        stages = [mock_pipeline_stage for _ in range(num_stages_per_rank)]
        for stage in stages:
            stage.num_stages = num_stages_per_rank * pp_degree
    else:
        raise ValueError(f'Invalid schedule: {schedule_class}')
    schedule_instance = schedule_class(stages, num_microbatches)
    assert schedule_instance.pipeline_order is not None
    all_actions: list[list[Optional[_Action]]] = []
    if with_comms:
        runtime = _PipelineScheduleRuntime(stages, num_microbatches)
        runtime._prepare_schedule_with_comms(schedule_instance.pipeline_order)
        for rank in range(pp_degree):
            all_actions.append(list(runtime.pipeline_order_with_comms[rank]))
    else:
        for rank in range(pp_degree):
            all_actions.append(schedule_instance.pipeline_order[rank])
    if add_spacing:
        all_actions = [[action for action in rank if action is not None] for rank in all_actions]
        all_actions = add_schedule_op_spacing(all_actions)
    return all_actions

def write(self, df: DataFrame, path, compression: Literal['snappy', 'gzip', 'brotli'] | None='snappy', index=None, partition_cols=None, storage_options: StorageOptions | None=None, filesystem=None, **kwargs) -> None:
    self.validate_dataframe(df)
    if <MASK>:
        raise ValueError('Cannot use both partition_on and partition_cols. Use partition_cols for partitioning data')
    if 'partition_on' in kwargs:
        partition_cols = kwargs.pop('partition_on')
    if partition_cols is not None:
        kwargs['file_scheme'] = 'hive'
    if filesystem is not None:
        raise NotImplementedError('filesystem is not implemented for the fastparquet engine.')
    path = stringify_path(path)
    if is_fsspec_url(path):
        fsspec = import_optional_dependency('fsspec')
        kwargs['open_with'] = lambda path, _: fsspec.open(path, 'wb', **storage_options or {}).open()
    elif storage_options:
        raise ValueError('storage_options passed with file object or non-fsspec file path')
    with catch_warnings(record=True):
        self.api.write(path, df, compression=compression, write_index=index, partition_on=partition_cols, **kwargs)

def _check_table_initializer_element_spec(element_spec):
    """Raises an error if the given table initializer element spec is invalid."""
    base_error = 'Datasets used to initialize lookup tables must produce elements in the form (key, value), where the keys and values are scalar tensors. '
    specific_error = None
    if len(element_spec) != 2:
        raise ValueError(base_error + f'However, the given dataset produces {len(element_spec)} components instead of two (key, value) components. Full dataset element spec: {element_spec}.')
    if <MASK>:
        raise ValueError(base_error + f'However, the given dataset produces non-Tensor keys of type {type(element_spec[0])}.')
    if not isinstance(element_spec[1], tensor.TensorSpec):
        raise ValueError(base_error + f'However, the given dataset produces non-Tensor values of type {type(element_spec[1])}.')
    if element_spec[0].shape.rank not in (None, 0):
        raise ValueError(base_error + f'However, the given dataset produces non-scalar key Tensors of rank {element_spec[0].shape.rank}.')
    if element_spec[1].shape.rank not in (None, 0):
        raise ValueError(base_error + f'However, the given dataset produces non-scalar value Tensors of rank {element_spec[1].shape.rank}.')

@final
@staticmethod
def _validate_sharex(sharex: bool | None, ax, by) -> bool:
    if <MASK>:
        if ax is None and by is None:
            sharex = True
        else:
            sharex = False
    elif not is_bool(sharex):
        raise TypeError('sharex must be a bool or None')
    return bool(sharex)

