def preprocess(self, root_node, after_compat_v1_upgrade=False):
    visitor = ast_edits.PastaAnalyzeVisitor(TFAPIImportAnalysisSpec())
    visitor.visit(root_node)
    detections = set(visitor.results)
    if <MASK>:
        CompatV1ImportReplacer().visit(root_node)
        return self.preprocess(root_node, after_compat_v1_upgrade=True)
    if detections:
        self.function_handle = {}
        self.function_reorders = {}
        self.function_keyword_renames = {}
        self.symbol_renames = {}
        self.function_warnings = {}
        self.change_to_function = {}
        self.module_deprecations = module_deprecations_v2.MODULE_DEPRECATIONS
        self.function_transformers = {}
        self.import_renames = {}
    return (root_node, visitor.log, visitor.warnings_and_errors)

def _get_output_act_obs_or_fq(arg: Node, named_modules: dict[str, torch.nn.Module], obs_or_fq_map: dict[EdgeOrNode, ObserverOrFakeQuantize], is_qat: bool) -> Optional[ObserverOrFakeQuantize]:
    """Get the constructor for observer or fake quant object for
    the argument in the original graph as the output of previous node,
    skipping inserted observers

    We are assuming that the observers are inserted correctly, and the dtype for
    argument in quantized graph will match what is specified by the qconfig
    """
    assert isinstance(arg, Node)
    if 'quantization_annotation' in arg.meta:
        return _create_obs_or_fq_from_qspec(arg.meta['quantization_annotation'].output_qspec, obs_or_fq_map, is_qat)
    custom_module_lstm_node = _maybe_get_custom_module_lstm_from_node_arg(arg, named_modules)
    output_act_obs_or_fq_ctr = None
    if custom_module_lstm_node is not None:
        output_act_obs_or_fq_ctr = custom_module_lstm_node.meta['target_dtype_info']['output_act_obs_or_fq_ctr']
        output_act_obs_or_fq = output_act_obs_or_fq_ctr() if output_act_obs_or_fq_ctr else None
    elif _is_activation_post_process_node(arg, named_modules):
        observed_arg = arg.args[0]
        assert isinstance(observed_arg, Node), 'Currently we only support observing Node'
        if 'quantization_annotation' in observed_arg.meta:
            output_act_obs_or_fq = _create_obs_or_fq_from_qspec(observed_arg.meta['quantization_annotation'].output_qspec, obs_or_fq_map, is_qat)
        else:
            assert 'target_dtype_info' in observed_arg.meta
            output_act_obs_or_fq_ctr = observed_arg.meta['target_dtype_info']['output_act_obs_or_fq_ctr']
            output_act_obs_or_fq = output_act_obs_or_fq_ctr() if output_act_obs_or_fq_ctr else None
    else:
        if <MASK>:
            output_act_obs_or_fq_ctr = arg.meta['target_dtype_info'].get('output_act_obs_or_fq_ctr', _DEFAULT_FP32_OBS_OR_FQ_CTR)
        else:
            output_act_obs_or_fq_ctr = _DEFAULT_FP32_OBS_OR_FQ_CTR
        output_act_obs_or_fq = output_act_obs_or_fq_ctr() if output_act_obs_or_fq_ctr else None
    return output_act_obs_or_fq

def _print_args(arguments, argument_type='Argument', indent=0):
    """Formats and prints the argument of the concrete functions defined in the model.

  Args:
    arguments: Arguments to format print.
    argument_type: Type of arguments.
    indent: How far (in increments of 2 spaces) to indent each line of
     output.
  """
    indent_str = '  ' * indent

    def _maybe_add_quotes(value):
        is_quotes = "'" * isinstance(value, str)
        return is_quotes + str(value) + is_quotes

    def in_print(s, end='\n'):
        print(indent_str + s, end=end)
    for (index, element) in enumerate(arguments, 1):
        if indent == 4:
            in_print('%s #%d' % (argument_type, index))
        if isinstance(element, str):
            in_print('  %s' % element)
        elif <MASK>:
            print((indent + 1) * '  ' + '%s: %s' % (element.name, repr(element)))
        elif isinstance(element, collections_abc.Iterable) and (not isinstance(element, dict)):
            in_print('  DType: %s' % type(element).__name__)
            in_print('  Value: [', end='')
            for value in element:
                print('%s' % _maybe_add_quotes(value), end=', ')
            print('\x08\x08]')
        elif isinstance(element, dict):
            in_print('  DType: %s' % type(element).__name__)
            in_print('  Value: {', end='')
            for (key, value) in element.items():
                print("'%s': %s" % (str(key), _maybe_add_quotes(value)), end=', ')
            print('\x08\x08}')
        else:
            in_print('  DType: %s' % type(element).__name__)
            in_print('  Value: %s' % str(element))

def _extract_graph_with_inputs_outputs(joint_graph: fx.Graph, inputs: list[fx.Node], outputs: list[fx.Node], outputs_descs: list[AOTOutput], subgraph: Optional[str]=None) -> fx.Graph:
    """
    Given a graph, extracts out a subgraph that takes the specified nodes as
    inputs and returns the specified outputs.

    This includes specifying non-placeholder nodes as inputs.

    The general strategy is to initialize all inputs with proxies as we
    encounter them, and trace through the graph, only keeping values which take
    in valid proxies. Then, all dead code is eliminated.
    """
    new_graph = fx.Graph()
    env = {}
    for node in inputs:
        new_node = new_graph.placeholder(node.name)
        new_node.meta = node.meta
        env[node] = new_node
    for node in joint_graph.nodes:
        if _must_be_in_backward(node) and subgraph != 'backward' and (node not in inputs):
            env[node] = InvalidNode
            continue
        if _must_be_in_forward(node) and subgraph != 'forward' and (node not in inputs):
            env[node] = InvalidNode
            continue
        if node in env:
            continue
        elif node.op == 'placeholder':
            env[node] = InvalidNode
        elif node.op == 'call_function':
            all_args = pytree.arg_tree_leaves(*node.args, **node.kwargs)
            all_args = [isinstance(env[x], InvalidNodeBase) for x in all_args if isinstance(x, fx.Node)]
            if any(all_args):
                env[node] = InvalidNode
                continue
            env[node] = new_graph.node_copy(node, lambda x: env[x])
        elif node.op == 'get_attr':
            env[node] = new_graph.node_copy(node, lambda x: env[x])
        elif node.op == 'output':
            pass
    output_values = []
    for x in outputs:
        if isinstance(x, fx.Node):
            if <MASK>:
                raise RuntimeError(f"Node {x} couldn't be found in env")
            assert not isinstance(env[x], InvalidNodeBase), f'Node {x} was invalid, but is output'
            output_values.append(env[x])
        else:
            output_values.append(x)
    out = new_graph.output(tuple(output_values))
    out.meta['desc'] = outputs_descs
    new_graph.eliminate_dead_code()
    new_graph.lint()
    return new_graph

def __init__(self, srs_input='', srs_type='user', axis_order=None):
    """
        Create a GDAL OSR Spatial Reference object from the given input.
        The input may be string of OGC Well Known Text (WKT), an integer
        EPSG code, a PROJ string, and/or a projection "well known" shorthand
        string (one of 'WGS84', 'WGS72', 'NAD27', 'NAD83').
        """
    if not isinstance(axis_order, (NoneType, AxisOrder)):
        raise ValueError('SpatialReference.axis_order must be an AxisOrder instance.')
    self.axis_order = axis_order or AxisOrder.TRADITIONAL
    if srs_type == 'wkt':
        self.ptr = capi.new_srs(c_char_p(b''))
        self.import_wkt(srs_input)
        if self.axis_order == AxisOrder.TRADITIONAL:
            capi.set_axis_strategy(self.ptr, self.axis_order)
        return
    elif isinstance(srs_input, str):
        try:
            srid = int(srs_input)
            srs_input = 'EPSG:%d' % srid
        except ValueError:
            pass
    elif isinstance(srs_input, int):
        srs_type = 'epsg'
    elif isinstance(srs_input, self.ptr_type):
        srs = srs_input
        srs_type = 'ogr'
    else:
        raise TypeError('Invalid SRS type "%s"' % srs_type)
    if srs_type == 'ogr':
        srs = srs_input
    else:
        buf = c_char_p(b'')
        srs = capi.new_srs(buf)
    if <MASK>:
        raise SRSException('Could not create spatial reference from: %s' % srs_input)
    else:
        self.ptr = srs
    if self.axis_order == AxisOrder.TRADITIONAL:
        capi.set_axis_strategy(self.ptr, self.axis_order)
    if srs_type == 'user':
        self.import_user_input(srs_input)
    elif srs_type == 'epsg':
        self.import_epsg(srs_input)

def autodiscover_modules(*args, **kwargs):
    """
    Auto-discover INSTALLED_APPS modules and fail silently when
    not present. This forces an import on them to register any admin bits they
    may want.

    You may provide a register_to keyword parameter as a way to access a
    registry. This register_to object must have a _registry instance variable
    to access it.
    """
    from django.apps import apps
    register_to = kwargs.get('register_to')
    for app_config in apps.get_app_configs():
        for module_to_search in args:
            try:
                if register_to:
                    before_import_registry = copy.copy(register_to._registry)
                import_module('%s.%s' % (app_config.name, module_to_search))
            except Exception:
                if register_to:
                    register_to._registry = before_import_registry
                if <MASK>:
                    raise

def _isna(obj):
    """
    Detect missing values, treating None, NaN or NA as null.

    Parameters
    ----------
    obj: ndarray or object value
        Input array or scalar value.

    Returns
    -------
    boolean ndarray or boolean
    """
    if is_scalar(obj):
        return libmissing.checknull(obj)
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError('isna is not defined for MultiIndex')
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (np.ndarray, ABCExtensionArray)):
        return _isna_array(obj)
    elif isinstance(obj, ABCIndex):
        if <MASK>:
            return obj.isna()
        return _isna_array(obj._values)
    elif isinstance(obj, ABCSeries):
        result = _isna_array(obj._values)
        result = obj._constructor(result, index=obj.index, name=obj.name, copy=False)
        return result
    elif isinstance(obj, ABCDataFrame):
        return obj.isna()
    elif isinstance(obj, list):
        return _isna_array(np.asarray(obj, dtype=object))
    elif hasattr(obj, '__array__'):
        return _isna_array(np.asarray(obj))
    else:
        return False

def _fit(self, X):
    """Dispatch to the right submethod depending on the chosen solver."""
    (xp, is_array_api_compliant) = get_namespace(X)
    if issparse(X) and self.svd_solver not in ['auto', 'arpack', 'covariance_eigh']:
        raise TypeError(f'PCA only support sparse inputs with the "arpack" and "covariance_eigh" solvers, while "{self.svd_solver}" was passed. See TruncatedSVD for a possible alternative.')
    if self.svd_solver == 'arpack' and is_array_api_compliant:
        raise ValueError("PCA with svd_solver='arpack' is not supported for Array API inputs.")
    X = validate_data(self, X, dtype=[xp.float64, xp.float32], force_writeable=True, accept_sparse=('csr', 'csc'), ensure_2d=True, copy=False)
    self._fit_svd_solver = self.svd_solver
    if self._fit_svd_solver == 'auto' and issparse(X):
        self._fit_svd_solver = 'arpack'
    if <MASK>:
        if self._fit_svd_solver != 'arpack':
            n_components = min(X.shape)
        else:
            n_components = min(X.shape) - 1
    else:
        n_components = self.n_components
    if self._fit_svd_solver == 'auto':
        if X.shape[1] <= 1000 and X.shape[0] >= 10 * X.shape[1]:
            self._fit_svd_solver = 'covariance_eigh'
        elif max(X.shape) <= 500 or n_components == 'mle':
            self._fit_svd_solver = 'full'
        elif 1 <= n_components < 0.8 * min(X.shape):
            self._fit_svd_solver = 'randomized'
        else:
            self._fit_svd_solver = 'full'
    if self._fit_svd_solver in ('full', 'covariance_eigh'):
        return self._fit_full(X, n_components, xp, is_array_api_compliant)
    elif self._fit_svd_solver in ['arpack', 'randomized']:
        return self._fit_truncated(X, n_components, xp)

def get_branches_with_magic_label_or_open_pr() -> set[str]:
