def _validate_transformers(self):
    """Validate names of transformers and the transformers themselves.

        This checks whether given transformers have the required methods, i.e.
        `fit` or `fit_transform` and `transform` implemented.
        """
    if not self.transformers:
        return
    (names, transformers, _) = zip(*self.transformers)
    self._validate_names(names)
    for t in transformers:
        if t in ('drop', 'passthrough'):
            continue
        if <MASK>:
            raise TypeError("All estimators should implement fit and transform, or can be 'drop' or 'passthrough' specifiers. '%s' (type %s) doesn't." % (t, type(t)))

def _get_ignored_params(root_module: torch.nn.Module, ignored_modules: set[torch.nn.Module], ignored_parameters: Optional[Iterable[torch.nn.Parameter]]=None) -> set[torch.nn.Parameter]:
    """
    Return the parameters of the modules in ``ignored_modules`` and the parameters in ``ignored_parameters``.

    :class:`FlatParameter` s are excluded from the result.
    """
    all_ignored_params: set[torch.nn.Parameter] = set()
    params_in_ignored_modules = {p for m in ignored_modules for p in m.parameters() if not _is_fsdp_flattened(p)}
    all_ignored_params.update(params_in_ignored_modules)
    if ignored_parameters is not None:
        params_in_ignored_parameters = {p for p in ignored_parameters if not _is_fsdp_flattened(p)}
        all_ignored_params.update(params_in_ignored_parameters)
    for submodule in root_module.modules():
        optional_fsdp_state = _get_module_fsdp_state(submodule)
        if optional_fsdp_state is not None:
            if <MASK>:
                raise AssertionError('Expected optional_fsdp_state to have _ignored_params attribute')
            all_ignored_params.update(optional_fsdp_state._ignored_params)
    return all_ignored_params

def nontensors_match(self, other: 'SplitInputs'):
    if self.arg_types != other.arg_types:
        return False
    if self.kwarg_types != other.kwarg_types:
        return False
    if self.kwarg_order != other.kwarg_order:
        return False
    if <MASK>:
        return False
    if self.nontensor_kwargs != other.nontensor_kwargs:
        return False
    return True

def _maybe_view_as_subclass(original_array, new_array):
    if <MASK>:
        new_array = new_array.view(type=type(original_array))
        if new_array.__array_finalize__:
            new_array.__array_finalize__(original_array)
    return new_array

def reduction_combine_vec(self, reduction_type, var, next_value, helper_val=None, index: Optional[sympy.Symbol]=None, horizontal_reduction: Optional[bool]=None, src_dtype: Optional[torch.dtype]=torch.float32):
    is_bool = src_dtype == torch.bool
    if reduction_type == 'max':
        if self.tail_size:
            return f'max_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} | {next_value}' if is_bool else f'at::vec::maximum({var}, {next_value})'
    elif reduction_type == 'min':
        if self.tail_size:
            return f'min_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} & {next_value}' if is_bool else f'at::vec::minimum({var}, {next_value})'
    elif reduction_type == 'sum':
        if helper_val:
            if self.tail_size:
                return f'cascade_sum_combine({next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'cascade_sum_combine({next_value}, &{helper_val})'
        elif self.tail_size:
            return f'sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            conjunction = '|' if is_bool else '+'
            return f'{var} {conjunction} {next_value}'
    elif reduction_type == 'prod':
        if self.tail_size:
            return f'prod_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} * {next_value}'
    elif <MASK>:
        if self.tail_size:
            return f'xor_sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} ^ {next_value}'
    elif reduction_type == 'welford_reduce':
        if helper_val:
            if self.tail_size:
                return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'welford_combine({var}, {next_value}, &{helper_val})'
        elif self.tail_size:
            return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {next_value})'
    elif reduction_type == 'welford_combine':
        if isinstance(next_value, tuple):
            (mean, m2, weight) = next_value
        else:
            (mean, m2, weight) = reduction_project(reduction_type, next_value)
        if self.tail_size:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}})'
    elif reduction_type in ('argmin', 'argmax'):
        assert src_dtype is not None
        cdtype = DTYPE_TO_CPP[src_dtype]
        if src_dtype == torch.bool:
            cdtype = DTYPE_TO_CPP[torch.float]
        n_src = self._get_num_vectors(src_dtype)
        n_idx = self._get_num_vectors(torch.int64)
        t_extra = ''
        arg_extra = ''
        if index is not None:
            assert horizontal_reduction is not None
            t_extra = f', {str(horizontal_reduction).lower()}'
            arg_extra = f', {index}'
        if self.tail_size:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra}, {cexpr_index(self.tail_size)})'
        else:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra})'
    elif reduction_type == 'any':
        if isinstance(next_value, CppCSEVariable):
            assert next_value.dtype == torch.bool
            (next_value,) = unify_mask_base_type(V.kernel.compute, (next_value,))
        return f'{var} | {next_value}'
    else:
        raise NotImplementedError

def trim_lex(tokens):
    """
    Takes a lexed set of tokens, and removes whitespace when there is
    a directive on a line by itself:

       >>> tokens = lex('{{if x}}\\nx\\n{{endif}}\\ny', trim_whitespace=False)
       >>> tokens
       [('if x', (1, 3)), '\\nx\\n', ('endif', (3, 3)), '\\ny']
       >>> trim_lex(tokens)
       [('if x', (1, 3)), 'x\\n', ('endif', (3, 3)), 'y']
    """
    last_trim = None
    for (i, current) in enumerate(tokens):
        if isinstance(current, basestring_):
            continue
        item = current[0]
        if not statement_re.search(item) and item not in single_statements:
            continue
        if not i:
            prev = ''
        else:
            prev = tokens[i - 1]
        if i + 1 >= len(tokens):
            next_chunk = ''
        else:
            next_chunk = tokens[i + 1]
        if not isinstance(next_chunk, basestring_) or not isinstance(prev, basestring_):
            continue
        prev_ok = not prev or trail_whitespace_re.search(prev)
        if i == 1 and (not prev.strip()):
            prev_ok = True
        if last_trim is not None and last_trim + 2 == i and (not prev.strip()):
            prev_ok = 'last'
        if prev_ok and (not next_chunk or lead_whitespace_re.search(next_chunk) or (i == len(tokens) - 2 and (not next_chunk.strip()))):
            if prev:
                if i == 1 and (not prev.strip()) or prev_ok == 'last':
                    tokens[i - 1] = ''
                else:
                    m = trail_whitespace_re.search(prev)
                    prev = prev[:m.start() + 1]
                    tokens[i - 1] = prev
            if next_chunk:
                last_trim = i
                if <MASK>:
                    tokens[i + 1] = ''
                else:
                    m = lead_whitespace_re.search(next_chunk)
                    next_chunk = next_chunk[m.end():]
                    tokens[i + 1] = next_chunk
    return tokens

@staticmethod
def for_fetch(fetch):
    """Creates fetch mapper that handles the structure of `fetch`.

    The default graph must be the one from which we want to fetch values when
    this function is called.

    Args:
      fetch: An arbitrary fetch structure: singleton, list, tuple, namedtuple,
        or dict.

    Returns:
      An instance of a subclass of `_FetchMapper` that handles the shape.
    """
    if fetch is None:
        raise TypeError(f'Argument `fetch` = {fetch} has invalid type "{type(fetch).__name__}". Cannot be None')
    elif isinstance(fetch, (list, tuple)):
        return _ListFetchMapper(fetch)
    elif <MASK>:
        return _DictFetchMapper(fetch)
    elif _is_attrs_instance(fetch):
        return _AttrsFetchMapper(fetch)
    else:
        for (tensor_type, fetch_fn, _, _) in _REGISTERED_EXPANSIONS:
            if isinstance(fetch, tensor_type):
                (fetches, contraction_fn) = fetch_fn(fetch)
                return _ElementFetchMapper(fetches, contraction_fn)
    raise TypeError(f'Argument `fetch` = {fetch} has invalid type "{type(fetch).__name__}"')

def __init__(self, message, code=None, params=None):
    """
        The `message` argument can be a single error, a list of errors, or a
        dictionary that maps field names to lists of errors. What we define as
        an "error" can be either a simple string or an instance of
        ValidationError with its message attribute set, and what we define as
        list or dictionary can be an actual `list` or `dict` or an instance
        of ValidationError with its `error_list` or `error_dict` attribute set.
        """
    super().__init__(message, code, params)
    if isinstance(message, ValidationError):
        if <MASK>:
            message = message.error_dict
        elif not hasattr(message, 'message'):
            message = message.error_list
        else:
            (message, code, params) = (message.message, message.code, message.params)
    if isinstance(message, dict):
        self.error_dict = {}
        for (field, messages) in message.items():
            if not isinstance(messages, ValidationError):
                messages = ValidationError(messages)
            self.error_dict[field] = messages.error_list
    elif isinstance(message, list):
        self.error_list = []
        for message in message:
            if not isinstance(message, ValidationError):
                message = ValidationError(message)
            if hasattr(message, 'error_dict'):
                self.error_list.extend(sum(message.error_dict.values(), []))
            else:
                self.error_list.extend(message.error_list)
    else:
        self.message = message
        self.code = code
        self.params = params
        self.error_list = [self]

def _process_tensor_fetches(self, tensor_fetches):
    """Check that tensor_fetches is not empty and have valid tensors."""
    if tensor_fetches is None:
        raise RuntimeError('tensor_fetches provided to tensor_tracer cannot be None.')
    if not isinstance(tensor_fetches, (list, tuple)):
        tensor_fetches = [tensor_fetches]
    elif <MASK>:
        raise RuntimeError('tensor_fetches provided to tensor_tracer cannot be empty list.')
    fetches = []
    for fetch in tensor_fetches:
        if isinstance(fetch, tensor_lib.Tensor):
            fetches.append(fetch)
        else:
            raise RuntimeError('Given tensor_fetch:%s is not a tensor.' % fetch)
    return fetches

