def convert_str_to_export_dim(dynamic_shapes: dict[str, Any] | tuple[Any, ...] | list[Any] | None) -> tuple[dict[str, Any] | tuple[Any, ...] | list[Any] | None, bool]:
    if <MASK>:
        return (dynamic_shapes, False)
    dynamic_shapes_with_export_dim: list[list[Dim | _DimHint | None] | dict[int, Dim | _DimHint | None] | None] = []
    (flat_dynamic_shapes, tree_structure) = _flatten_dynamic_shapes_to_axes(dynamic_shapes)
    for axes in flat_dynamic_shapes:
        if axes is None:
            dynamic_shapes_with_export_dim.append(None)
        elif isinstance(axes, dict):
            converted_axes_dict: dict[int, Dim | _DimHint | None] = {}
            for (axis, dim) in axes.items():
                if isinstance(dim, str):
                    converted_axes_dict[axis] = torch.export.Dim.DYNAMIC
                else:
                    converted_axes_dict[axis] = dim
            dynamic_shapes_with_export_dim.append(converted_axes_dict)
        elif isinstance(axes, (list, tuple)):
            converted_axes_list: list[Dim | _DimHint | None] = []
            for dim in axes:
                if isinstance(dim, str):
                    converted_axes_list.append(torch.export.Dim.DYNAMIC)
                else:
                    converted_axes_list.append(dim)
            dynamic_shapes_with_export_dim.append(converted_axes_list)
    dynamic_shapes_with_export_dim = _pytree.tree_unflatten(dynamic_shapes_with_export_dim, tree_structure)
    return (dynamic_shapes_with_export_dim, True)

def doTestBasic(self, use_locking=False, use_resource=False, use_callable_params=False):
    for dtype in [dtypes.half, dtypes.float32, dtypes.float64]:
        if use_resource:
            var0 = resource_variable_ops.ResourceVariable([1.0, 2.0], dtype=dtype)
            var1 = resource_variable_ops.ResourceVariable([3.0, 4.0], dtype=dtype)
        else:
            var0 = variables.Variable([1.0, 2.0], dtype=dtype)
            var1 = variables.Variable([3.0, 4.0], dtype=dtype)
        grads0 = constant_op.constant([0.1, 0.1], dtype=dtype)
        grads1 = constant_op.constant([0.01, 0.01], dtype=dtype)
        learning_rate = lambda : 3.0
        if not use_callable_params:
            learning_rate = learning_rate()
        ada_opt = adagrad.AdagradOptimizer(learning_rate, initial_accumulator_value=0.1, use_locking=use_locking)
        if <MASK>:
            ada_update = ada_opt.apply_gradients(zip([grads0, grads1], [var0, var1]))
            self.evaluate(variables.global_variables_initializer())
        (v0_val, v1_val) = self.evaluate([var0, var1])
        self.assertAllClose([1.0, 2.0], v0_val)
        self.assertAllClose([3.0, 4.0], v1_val)
        for _ in range(3):
            if not context.executing_eagerly():
                self.evaluate(ada_update)
            else:
                ada_opt.apply_gradients(zip([grads0, grads1], [var0, var1]))
        (v0_val, v1_val) = self.evaluate([var0, var1])
        self.assertAllCloseAccordingToType(np.array([-1.6026098728179932, -0.6026098728179932]), v0_val)
        self.assertAllCloseAccordingToType(np.array([2.715679168701172, 3.715679168701172]), v1_val)

def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if ann is None:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if is_dict(ann):
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if <MASK>:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if ann is str:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if ann is Any:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if ann is torch.qscheme:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if maybe_script_class is not None:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

def config_of(args: list[KernelArgType], *, indices: Optional[list[int]]=None) -> Any:
    if <MASK>:
        indices = list(range(len(args)))

    def is_aligned(x: KernelArgType, alignment: int, include_tensor: bool) -> bool:
        """
        Roughly follow triton code here:
        https://github.com/triton-lang/triton/blob/5282ed890d453e10b9ee30076ef89115dd197761/python/triton/runtime/jit.py#L208-L222
        """
        if isinstance(x, TensorArg):
            if include_tensor:
                offset_aligned = V.graph.sizevars.statically_known_multiple_of(x.offset * x.dtype.itemsize, alignment)
                return offset_aligned and (not is_unaligned_buffer(x))
            else:
                return False
        if isinstance(x, SizeArg):
            if x.name.startswith('load_seed_offset'):
                return False
            if x.expr is None:
                return False
            if isinstance(x.expr, float):
                return False
            return V.graph.sizevars.statically_known_multiple_of(x.expr, alignment)
        if isinstance(x, WorkspaceArg):
            return True
        if isinstance(x, (TMADescriptorArg, ConstexprArg)):
            return False
        raise NotImplementedError(f'unhandled {type(x)}: {x}')
    if config.triton.divisible_by_16:
        divisible_by_16 = tuple((i for (i, arg) in zip(indices, args) if is_aligned(arg, alignment=16, include_tensor=True)))
    else:
        divisible_by_16 = ()
    equal_to_1 = equal_1_arg_indices(args, indices=indices)
    return AttrsDescriptorWrapper(divisible_by_16, equal_to_1)

@final
def _validate_how(self, how: JoinHow | Literal['left_anti', 'right_anti', 'asof']) -> tuple[JoinHow | Literal['asof'], bool]:
    """
        Validate the 'how' parameter and return the actual join type and whether
        this is an anti join.
        """
    merge_type = {'left', 'right', 'inner', 'outer', 'left_anti', 'right_anti', 'cross', 'asof'}
    if <MASK>:
        raise ValueError(f"'{how}' is not a valid Merge type: left, right, inner, outer, left_anti, right_anti, cross, asof")
    anti_join = False
    if how in {'left_anti', 'right_anti'}:
        how = how.split('_')[0]
        anti_join = True
    how = cast(JoinHow | Literal['asof'], how)
    return (how, anti_join)

@classmethod
def from_float(cls, mod, use_precomputed_fake_quant=False):
    assert type(mod) in {torch.nn.LSTM, torch.nn.GRU}, 'nn.quantized.dynamic.RNNBase.from_float only works for nn.LSTM and nn.GRU'
    assert hasattr(mod, 'qconfig'), 'Input float module must have qconfig defined'
    if <MASK>:
        weight_observer_method = mod.qconfig.weight
    else:
        from torch.ao.quantization.qconfig import default_dynamic_qconfig
        weight_observer_method = default_dynamic_qconfig.weight
    dtype = weight_observer_method().dtype
    supported_scalar_types = [torch.qint8, torch.float16]
    if dtype not in supported_scalar_types:
        raise RuntimeError(f'Unsupported dtype for dynamic RNN quantization: {dtype}')
    qRNNBase: Union[LSTM, GRU]
    if mod.mode == 'LSTM':
        qRNNBase = LSTM(mod.input_size, mod.hidden_size, mod.num_layers, mod.bias, mod.batch_first, mod.dropout, mod.bidirectional, dtype)
    elif mod.mode == 'GRU':
        qRNNBase = GRU(mod.input_size, mod.hidden_size, mod.num_layers, mod.bias, mod.batch_first, mod.dropout, mod.bidirectional, dtype)
    else:
        raise NotImplementedError('Only LSTM/GRU is supported for QuantizedRNN for now')
    num_directions = 2 if mod.bidirectional else 1
    assert mod.bias
    _all_weight_values = []
    for layer in range(qRNNBase.num_layers):
        for direction in range(num_directions):
            suffix = '_reverse' if direction == 1 else ''

            def retrieve_weight_bias(ihhh):
                weight_name = f'weight_{ihhh}_l{layer}{suffix}'
                bias_name = f'bias_{ihhh}_l{layer}{suffix}'
                weight = getattr(mod, weight_name)
                bias = getattr(mod, bias_name)
                return (weight, bias)
            (weight_ih, bias_ih) = retrieve_weight_bias('ih')
            (weight_hh, bias_hh) = retrieve_weight_bias('hh')
            if dtype == torch.qint8:

                def quantize_and_pack(w, b):
                    weight_observer = weight_observer_method()
                    weight_observer(w)
                    qweight = _quantize_weight(w.float(), weight_observer)
                    packed_weight = torch.ops.quantized.linear_prepack(qweight, b)
                    return packed_weight
                packed_ih = quantize_and_pack(weight_ih, bias_ih)
                packed_hh = quantize_and_pack(weight_hh, bias_hh)
                if qRNNBase.version is None or qRNNBase.version < 2:
                    cell_params = torch.ops.quantized.make_quantized_cell_params_dynamic(packed_ih, packed_hh, bias_ih, bias_hh)
                else:
                    cell_params = torch.ops.quantized.make_quantized_cell_params_dynamic(packed_ih, packed_hh, bias_ih, bias_hh, True)
            elif dtype == torch.float16:
                packed_ih = torch.ops.quantized.linear_prepack_fp16(weight_ih.float(), bias_ih)
                packed_hh = torch.ops.quantized.linear_prepack_fp16(weight_hh.float(), bias_hh)
                cell_params = torch.ops.quantized.make_quantized_cell_params_fp16(packed_ih, packed_hh)
            else:
                raise RuntimeError('Unsupported dtype specified for dynamic quantized LSTM!')
            _all_weight_values.append(PackedParameter(cell_params))
    qRNNBase._all_weight_values = torch.nn.ModuleList(_all_weight_values)
    return qRNNBase

