def create_symlinks() -> None:
    """Creates symlinks from build/lib to torch/lib"""
    if not TORCH_LIB_DIR.exists():
        raise RuntimeError(f"Can't create symlinks as {TORCH_LIB_DIR} does not exist")
    if not BUILD_LIB_DIR.exists():
        raise RuntimeError(f"Can't create symlinks as {BUILD_LIB_DIR} does not exist")
    for torch_lib in TORCH_LIB_DIR.glob(f'*.{get_lib_extension()}'):
        if <MASK>:
            continue
        build_lib = BUILD_LIB_DIR / torch_lib.name
        if not build_lib.exists():
            raise RuntimeError(f"Can't find {build_lib} corresponding to {torch_lib}")
        torch_lib.unlink()
        torch_lib.symlink_to(build_lib)

def validate_function_matches_schema(schema: FunctionSchema, func: typing.Callable) -> None:
    sig = inspect.signature(func)
    if not all((supported_param(p) for (_, p) in sig.parameters.items())):
        raise ValueError(f'custom_op(..., manual_schema)(func): positional-only args, varargs, and kwargs are not supported. Please rewrite `func` to not have them. Got `func` with signature: {sig}')
    if <MASK>:
        raise ValueError(f'custom_op(..., manual_schema)(func): When passing in a manual schema, we expect `func` to have no type annotations to avoid ambiguity. Got `func` with signature: {sig}')
    positional = [(name, param) for (name, param) in sig.parameters.items() if param.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD]
    kwargonly = [(name, param) for (name, param) in sig.parameters.items() if param.kind == inspect.Parameter.KEYWORD_ONLY]

    def error():
        raise ValueError(f"custom_op(..., manual_schema)(func): When passing in a manual schema, we expect `func`'s signature to match `manual_schema` (aside from type annotations). func's signature: {sig}, manual_schema: {schema}")

    def error_default_args():
        raise ValueError(f"custom_op(..., manual_schema)(func): neither func nor manual_schema should have default arguments. Got func's signature: {sig}, manual_schema: {schema}")

    def compare(sig_args, schema_args):
        if len(sig_args) != len(schema_args):
            error()
        for ((name, param), arg) in zip(sig_args, schema_args):
            if name != arg.name:
                error()
            if param.default is not inspect.Parameter.empty or arg.default is not None:
                error_default_args()
    compare(positional, schema.arguments.flat_positional)
    compare(kwargonly, schema.arguments.flat_kwarg_only)

def _match_normalized_structure(a, b):
    if <MASK>:
        return True
    if _normalize_type(a.type) != _normalize_type(b.type):
        return False
    if a.type is dict and b.type is dict:
        if set(a.context) != set(b.context):
            return False
    elif a.context != b.context:
        return False
    if len(a.children_specs) != len(b.children_specs):
        return False
    return all((_match_normalized_structure(a, b) for (a, b) in zip(a.children_specs, b.children_specs)))

def _unique(fake_mode, func, arg, dim, sorted=True, return_inverse=False, return_counts=False, *, unique_consecutive=False):
    if fake_mode.shape_env is None or not fake_mode.shape_env.allow_dynamic_output_shape_ops:
        raise DynamicOutputShapeException(func)
    nnz = arg.unique_consecutive_memo if unique_consecutive else arg.unique_memo
    if dim is not None or nnz is None:
        from torch.fx.experimental.symbolic_shapes import _constrain_range_for_size, has_free_symbols
        if not has_free_symbols(arg.numel()) and arg.numel() == 0:
            nnz = 0
        else:
            nnz = fake_mode.shape_env.create_unbacked_symint()
            maxval = sys.maxsize - 1
            numel = arg.numel() if dim is None else arg.size(dim)
            if <MASK>:
                maxval = int(numel)
            _constrain_range_for_size(nnz, max=maxval)
        if dim is None:
            if unique_consecutive:
                arg.unique_consecutive_memo = nnz
            else:
                arg.unique_memo = nnz
    if dim is None:
        ret = [arg.new_empty((nnz,))]
    else:
        ret = [arg.new_empty(*arg.shape[:dim], nnz, *arg.shape[dim + 1:])]
    return_if_dim_and_cpu = dim is not None and arg.fake_device == torch.device('cpu')
    if return_inverse or return_if_dim_and_cpu:
        inverse = arg.new_empty(arg.shape if dim is None else (arg.shape[dim],))
    else:
        inverse = arg.new_empty(0)
    ret.append(inverse)
    if return_counts or return_if_dim_and_cpu:
        counts = arg.new_empty(ret[0].shape if dim is None else (ret[0].shape[dim],))
    else:
        counts = arg.new_empty(0)
    ret.append(counts)
    return tuple(ret)

def codegen_range_tree(self):
    for tree in self.range_trees:
        if not tree.is_loop:
            self.iteration_ranges_codegen_header(tree, self.body)
        elif <MASK>:
            self.body.writeline(f'{tree.prefix}base = {self.iteration_ranges_ranges_code(tree)}')
    if self.inside_reduction:
        if any((tree.is_loop for tree in self.range_trees)):
            rn_bases = self._get_reduction_symbols('base', integer=True, nonnegative=True)
            rbase = self._flatten_reduction_indices(rn_bases)
            self.body.splice(f'rbase = {self.index_to_str(rbase)}')
        else:
            self.codegen_reduction_indices(self.body)

def _interpret_code(self, code, ns, out, defs):
    __traceback_hide__ = True
    (name, pos) = (code[0], code[1])
    if name == 'py':
        self._exec(code[2], ns, pos)
    elif name == 'continue':
        raise _TemplateContinue()
    elif name == 'break':
        raise _TemplateBreak()
    elif name == 'for':
        (vars, expr, content) = (code[2], code[3], code[4])
        expr = self._eval(expr, ns, pos)
        self._interpret_for(vars, expr, content, ns, out, defs)
    elif name == 'cond':
        parts = code[2:]
        self._interpret_if(parts, ns, out, defs)
    elif name == 'expr':
        parts = code[2].split('|')
        base = self._eval(parts[0], ns, pos)
        for part in parts[1:]:
            func = self._eval(part, ns, pos)
            base = func(base)
        out.append(self._repr(base, pos))
    elif name == 'default':
        (var, expr) = (code[2], code[3])
        if var not in ns:
            result = self._eval(expr, ns, pos)
            ns[var] = result
    elif name == 'inherit':
        expr = code[2]
        value = self._eval(expr, ns, pos)
        defs['__inherit__'] = value
    elif name == 'def':
        name = code[2]
        signature = code[3]
        parts = code[4]
        ns[name] = defs[name] = TemplateDef(self, name, signature, body=parts, ns=ns, pos=pos)
    elif <MASK>:
        return
    else:
        assert 0, 'Unknown code: %r' % name

def _get_sequence(value, n, channel_index, name):
    """Formats a value input for gen_nn_ops."""
    if value is None:
        return [1] * (n + 2)
    if isinstance(value, list):
        pass
    elif isinstance(value, tuple):
        value = list(value)
    elif isinstance(value, int):
        value = [value]
    elif not isinstance(value, collections_abc.Sized):
        value = [value]
    else:
        value = list(value)
    len_value = len(value)
    if len_value == n + 2:
        return value
    if len_value == 1:
        value = value * n
    elif <MASK>:
        raise ValueError(f'{name} should be of length 1, {n} or {n + 2}. Received: {name}={value} of length {len_value}')
    if channel_index == 1:
        return [1, 1] + value
    else:
        return [1] + value + [1]

def val_to_arg_str(self, val, type_=None) -> str:
    if val is None:
        if type_ is None or isinstance(type_, torch.OptionalType):
            if type_ is not None and isinstance(type_.getElementType(), (torch.DeviceObjType, torch.ListType, torch.TupleType)):
                return 'nullptr, 0'
            return 'nullptr'
        if isinstance(type_, torch.TensorType):
            var_name = f'var_{next(self.arg_var_id)}'
            self.writeline(f'AtenTensorHandle {var_name}_handle;')
            self.writeline(f'AOTI_TORCH_ERROR_CODE_CHECK(aoti_torch_new_uninitialized_tensor(&{var_name}_handle));')
            self.writeline(f'RAIIAtenTensorHandle {var_name}({var_name}_handle);')
            return var_name
        raise AssertionError('Can not map None to a known data type')
    if isinstance(type_, torch.OptionalType):
        element_type = type_.getElementType()
        arg_str = self.val_to_arg_str(val, element_type)
        if <MASK>:
            (main_value, aux) = arg_str.rsplit(', ', maxsplit=1)
            return f'&temporary_reference({main_value}), {aux}'
        if isinstance(element_type, torch.TensorType):
            base_handle = self.val_to_arg_str(val, element_type)
            return f'&temporary_reference({base_handle}.get())'
        var_name = f'var_{next(self.arg_var_id)}'
        if isinstance(element_type, torch.DeviceObjType):
            (main_value, aux) = arg_str.rsplit(', ', maxsplit=1)
            self.writeline(f'auto {var_name} = {main_value};')
            return f'&{var_name}, {aux}'
        self.writeline(f'{self.c_type_for_prim_type(val, element_type)} {var_name} = {arg_str};')
        return f'&{var_name}'
    if isinstance(type_, (torch.ListType, torch.TupleType)):
        assert isinstance(val, (list, tuple)), f'{val} does not match with arg type {type_}'
        element_type = type_.getElementType()
        if len(val) == 0:
            return 'nullptr, 0'
        result = [self.val_to_arg_str(x, element_type) for x in val]
        if isinstance(element_type, torch.TensorType):
            result = [f'{t}.get()' for t in result]
        c_type = self.c_type_for_prim_type(val[0], element_type)
        if isinstance(element_type, torch.OptionalType) and (not c_type.startswith('const')):
            c_type = f'const {c_type}'
        return f'{self._generate_temporary_array_pointer(c_type, result)}, {len(val)}'
    val_is_scalar = isinstance(val, (bool, complex, float, int, *SymTypes))
    if isinstance(type_, torch.TensorType) and val_is_scalar:
        val_str = self.val_to_arg_str_for_prim_type(val, None)
        return self.codegen_scalar_to_tensor(val_str)
    return self.val_to_arg_str_for_prim_type(val, type_)

def hook(_, grad_output):
    self.grad_outputs = self._pack_with_none(self.output_tensors_index, grad_output, self.n_outputs)
    if <MASK>:
        expected_len = len(self.grad_outputs)
        for user_pre_hook in self.user_pre_hooks:
            hook_grad_outputs = user_pre_hook(self.module, self.grad_outputs)
            if hook_grad_outputs is None:
                continue
            actual_len = len(hook_grad_outputs)
            if actual_len != expected_len:
                raise RuntimeError(f'Backward pre hook returned an invalid number of grad_output, got {actual_len}, but expected {expected_len}')
            self.grad_outputs = hook_grad_outputs
    local_grad_outputs = self.grad_outputs
    if self.input_tensors_index is None:
        warnings.warn('Full backward hook is firing when gradients are computed with respect to module outputs since no inputs require gradients. See https://docs.pytorch.org/docs/main/generated/torch.nn.Module.html#torch.nn.Module.register_full_backward_hook for more details.', stacklevel=5)
        grad_inputs = self._pack_with_none([], [], self.n_inputs)
        for user_hook in self.user_hooks:
            res = user_hook(self.module, grad_inputs, self.grad_outputs)
            if res is not None and (not (isinstance(res, tuple) and all((el is None for el in res)))):
                raise RuntimeError('Backward hook for Modules where no input requires gradient should always return None or None for all gradients.')
        self.grad_outputs = None
    if local_grad_outputs is not None:
        assert self.output_tensors_index is not None
        return tuple((local_grad_outputs[i] for i in self.output_tensors_index))

