    res = torch.empty_like(x, dtype=result_dtype, memory_format=torch.contiguous_format)
    return res

def get_traceback_data(self):
    """Return a dictionary containing traceback information."""
    if self.exc_type and issubclass(self.exc_type, TemplateDoesNotExist):
        self.template_does_not_exist = True
        self.postmortem = self.exc_value.chain or [self.exc_value]
    frames = self.get_traceback_frames()
    for (i, frame) in enumerate(frames):
        if 'vars' in frame:
            frame_vars = []
            for (k, v) in frame['vars']:
                v = pprint(v)
                if len(v) > 4096:
                    v = '%s… <trimmed %d bytes string>' % (v[0:4096], len(v))
                frame_vars.append((k, v))
            frame['vars'] = frame_vars
        frames[i] = frame
    unicode_hint = ''
    if self.exc_type and issubclass(self.exc_type, UnicodeError):
        start = getattr(self.exc_value, 'start', None)
        end = getattr(self.exc_value, 'end', None)
        if <MASK>:
            unicode_str = self.exc_value.args[1]
            unicode_hint = force_str(unicode_str[max(start - 5, 0):min(end + 5, len(unicode_str))], 'ascii', errors='replace')
    from django import get_version
    if self.request is None:
        user_str = None
    else:
        try:
            user_str = str(self.request.user)
        except Exception:
            user_str = '[unable to retrieve the current user]'
    c = {'is_email': self.is_email, 'unicode_hint': unicode_hint, 'frames': frames, 'request': self.request, 'request_meta': self.filter.get_safe_request_meta(self.request), 'request_COOKIES_items': self.filter.get_safe_cookies(self.request).items(), 'user_str': user_str, 'filtered_POST_items': list(self.filter.get_post_parameters(self.request).items()), 'settings': self.filter.get_safe_settings(), 'sys_executable': sys.executable, 'sys_version_info': '%d.%d.%d' % sys.version_info[0:3], 'server_time': timezone.now(), 'django_version_info': get_version(), 'sys_path': sys.path, 'template_info': self.template_info, 'template_does_not_exist': self.template_does_not_exist, 'postmortem': self.postmortem}
    if self.request is not None:
        c['request_GET_items'] = self.request.GET.items()
        c['request_FILES_items'] = self.request.FILES.items()
        c['request_insecure_uri'] = self._get_raw_insecure_uri()
        c['raising_view_name'] = get_caller(self.request)
    if self.exc_type:
        c['exception_type'] = self.exc_type.__name__
    if self.exc_value:
        c['exception_value'] = getattr(self.exc_value, 'raw_error_message', self.exc_value)
        if (exc_notes := getattr(self.exc_value, '__notes__', None)):
            c['exception_notes'] = '\n' + '\n'.join(exc_notes)
    if frames:
        c['lastframe'] = frames[-1]
    return c

def maybe_propagate_real_tensors(fake_out: T) -> T:
    import sympy
    log.debug('maybe_propagate_real_tensors %s', func)

    def go(t: object, real_t: Tensor) -> None:
        if isinstance(t, FakeTensor):
            log.debug('maybe_propagate_real_tensors %s -> %s', id(t), id(real_t))
            t.real_tensor = real_t
            for (s, real_s) in zip(t.size(), real_t.size()):
                go(s, real_s)
            for (s, real_s) in zip(t.stride(), real_t.stride()):
                go(s, real_s)
            go(t.storage_offset(), real_t.storage_offset())
        elif isinstance(t, py_sym_types) and free_unbacked_symbols(t):
            if isinstance(t.node.expr, sympy.Symbol):
                assert self.shape_env is not None
                self.shape_env.set_unbacked_var_to_val(t.node.expr, real_t)
            elif isinstance((s := t.node.expr), sympy.Eq) and isinstance(s.lhs, sympy.Symbol) and (s.rhs == 1):
                assert self.shape_env is not None
                self.shape_env.set_unbacked_var_to_val(s, int(real_t))
    if <MASK>:
        if not torch._functorch.config.generate_fake_kernels_from_real_mismatches:
            self._maybe_infer_fake_kernel_from_pytree_out(func, (args, kwargs), (real_args, real_kwargs), fake_out, real_out)
        else:
            fake_out = self._maybe_infer_fake_kernel_from_pytree_out(func, (args, kwargs), (real_args, real_kwargs), fake_out, real_out)
        if not isinstance(fake_out, Tensor) and (not isinstance(real_out, Tensor)) and (type(fake_out) is not type(real_out)):
            tree_map_(go, tuple(pytree.tree_flatten(fake_out)), tuple(pytree.tree_flatten(real_out)))
        else:
            tree_map_(go, fake_out, real_out)
        compute_unbacked_bindings(self.shape_env, fake_out, peek=True)
    return fake_out

@lru_cache(None)
def gen_attr_descriptor_import() -> str:
    """
    import AttrsDescriptor if the triton version is new enough to have this
    class defined.
    """
    if not has_triton_package():
        return ''
    import triton.compiler.compiler
    if <MASK>:
        return 'from triton.compiler.compiler import AttrsDescriptor'
    else:
        return ''

def _find_reference_cycle(objects: Sequence[Any], idx: int) -> bool:

    def get_ignore_reason(obj: Any, denylist: Collection[Any]) -> Optional[str]:
        """Tests whether an object should be omitted from the dependency graph."""
        if len(denylist) > 100:
            return '<depth limit>'
        if <MASK>:
            if 'test_util.py' in tf_inspect.getframeinfo(obj)[0]:
                return '<test code>'
        for b in denylist:
            if b is obj:
                return '<test code>'
        if obj is denylist:
            return '<test code>'
        return None

    def describe(obj: Any, denylist: Collection[Any], leaves_only: bool=False) -> str:
        """Returns a custom human-readable summary of obj.

    Args:
      obj: the value to describe.
      denylist: same as denylist in get_ignore_reason.
      leaves_only: boolean flag used when calling describe recursively. Useful
        for summarizing collections.
    """
        if get_ignore_reason(obj, denylist):
            return '{}{}'.format(get_ignore_reason(obj, denylist), type(obj))
        if tf_inspect.isframe(obj):
            return 'frame: {}'.format(tf_inspect.getframeinfo(obj))
        elif tf_inspect.ismodule(obj):
            return 'module: {}'.format(obj.__name__)
        elif leaves_only:
            return '{}, {}'.format(type(obj), id(obj))
        elif isinstance(obj, list):
            return 'list({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
        elif isinstance(obj, tuple):
            return 'tuple({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
        elif isinstance(obj, dict):
            return 'dict({}): {} keys'.format(id(obj), len(obj.keys()))
        elif tf_inspect.isfunction(obj):
            return 'function({}) {}; globals ID: {}'.format(id(obj), obj.__name__, id(obj.__globals__))
        else:
            return '{}, {}'.format(type(obj), id(obj))

    def build_ref_graph(obj: Any, graph: dict[int, list[int]], reprs: dict[int, str], denylist: tuple[Any, ...]) -> None:
        """Builds a reference graph as <referrer> -> <list of referents>.

    Args:
      obj: The object to start from. The graph will be built by recursively
        adding its referrers.
      graph: Dict holding the graph to be built. To avoid creating extra
        references, the graph holds object IDs rather than actual objects.
      reprs: Auxiliary structure that maps object IDs to their human-readable
        description.
      denylist: List of objects to ignore.
    """
        referrers = gc.get_referrers(obj)
        denylist = denylist + (referrers,)
        obj_id = id(obj)
        for r in referrers:
            if get_ignore_reason(r, denylist) is None:
                r_id = id(r)
                if r_id not in graph:
                    graph[r_id] = []
                if obj_id not in graph[r_id]:
                    graph[r_id].append(obj_id)
                    build_ref_graph(r, graph, reprs, denylist)
                    reprs[r_id] = describe(r, denylist)

    def find_cycle(el: int, graph: dict[int, list[int]], reprs: dict[int, str], path: tuple[int, ...]) -> Optional[bool]:
        """Finds and prints a single cycle in the dependency graph."""
        if el not in graph:
            return
        for r in graph[el]:
            if r in path:
                logging.error('Reference cycle sample:')
                for p in path + (r,):
                    logging.error(reprs.get(p, 'unknown object ' + str(p)))
                return True
            elif find_cycle(r, graph, reprs, path + (r,)):
                return True
        return False
    obj = objects[idx]
    graph: dict[int, list[int]] = {}
    reprs: dict[int, str] = {}
    build_ref_graph(obj, graph, reprs, (objects, graph, reprs, get_ignore_reason, describe, build_ref_graph, find_cycle))
    for k in graph:
        if find_cycle(k, graph, reprs, ()):
            return True
    return False

def load_model(self, device, model_name, batch_size=None, part=None, extra_args=None):
    if self.args.enable_activation_checkpointing:
        raise NotImplementedError('Activation checkpointing not implemented for Torchbench models')
    is_training = self.args.training
    use_eval_mode = self.args.use_eval_mode
    candidates = [f'torchbenchmark.models.{model_name}', f'torchbenchmark.canary_models.{model_name}', f'torchbenchmark.models.fb.{model_name}']
    for c in candidates:
        try:
            module = importlib.import_module(c)
            break
        except ModuleNotFoundError as e:
            if e.name != c:
                raise
    else:
        raise ImportError(f'could not import any of {candidates}')
    benchmark_cls = getattr(module, 'Model', None)
    if benchmark_cls is None:
        raise NotImplementedError(f'{model_name}.Model is None')
    if not hasattr(benchmark_cls, 'name'):
        benchmark_cls.name = model_name
    cant_change_batch_size = not getattr(benchmark_cls, 'ALLOW_CUSTOMIZE_BSIZE', True) or model_name in self._config['dont_change_batch_size']
    if cant_change_batch_size:
        batch_size = None
    if batch_size is None and is_training and (model_name in self._batch_size['training']):
        batch_size = self._batch_size['training'][model_name]
    elif batch_size is None and (not is_training) and (model_name in self._batch_size['inference']):
        batch_size = self._batch_size['inference'][model_name]
    if self.args.accuracy and model_name in self._accuracy['max_batch_size']:
        batch_size = min(batch_size, self._accuracy['max_batch_size'][model_name])
    torch.backends.__allow_nonbracketed_mutation_flag = True
    if extra_args is None:
        extra_args = []
    if part:
        extra_args += ['--part', part]
    if <MASK>:
        self.args.amp = True
        self.setup_amp()
    if model_name == 'vision_maskrcnn' and is_training:
        model_kwargs = {'box_detections_per_img': 4}
        benchmark = benchmark_cls(test='train', device=device, batch_size=batch_size, extra_args=extra_args, model_kwargs=model_kwargs)
        use_eval_mode = True
    elif is_training:
        benchmark = benchmark_cls(test='train', device=device, batch_size=batch_size, extra_args=extra_args)
    else:
        benchmark = benchmark_cls(test='eval', device=device, batch_size=batch_size, extra_args=extra_args)
    (model, example_inputs) = benchmark.get_module()
    if model_name in ['basic_gnn_edgecnn', 'basic_gnn_gcn', 'basic_gnn_sage', 'basic_gnn_gin']:
        _reassign_parameters(model)
    if is_training and (not use_eval_mode or model_name in self._config['only_training']):
        model.train()
    else:
        model.eval()
    gc.collect()
    batch_size = benchmark.batch_size
    if model_name == 'torchrec_dlrm':
        batch_namedtuple = namedtuple('Batch', 'dense_features sparse_features labels')
        example_inputs = tuple((batch_namedtuple(dense_features=batch.dense_features, sparse_features=batch.sparse_features, labels=batch.labels) for batch in example_inputs))
    if model_name == 'yolov3':
        example_inputs = (torch.rand(batch_size, 3, 384, 512).to(device),)
    if model_name == 'maml_omniglot':
        batch_size = 5
        assert example_inputs[0].shape[0] == batch_size
    if model_name == 'vision_maskrcnn':
        batch_size = 1
    if self.args.trace_on_xla:
        import torch_xla
    if model_name.startswith('hf') and hasattr(model, 'config') and hasattr(model.config, 'use_cache'):
        model.config.use_cache = False
    self.validate_model(model, example_inputs)
    return (device, benchmark.name, model, example_inputs, batch_size)

