def testPyvalConversion(self, pyval, expected, type_spec=None):
    expected = expected()
    actual = structured_tensor.StructuredTensor.from_pyval(pyval, type_spec)
    self.assertAllEqual(actual, expected)
    if isinstance(actual, structured_tensor.StructuredTensor):
        if <MASK>:
            self.assertEqual(actual.to_pyval(), pyval)

def _get_coef(self):
    if <MASK>:
        coef = safe_sparse_dot(self.dual_coef_, self.support_vectors_)
    else:
        coef = _one_vs_one_coef(self.dual_coef_, self._n_support, self.support_vectors_)
        if sp.issparse(coef[0]):
            coef = sp.vstack(coef).tocsr()
        else:
            coef = np.vstack(coef)
    return coef

def add_multi_kernel_choices(self, kernel: TritonKernel, kernel_args: list[Any], kernel_kwargs: dict[str, Any]) -> list[TritonKernel]:
    kernels: list[TritonKernel] = [kernel]
    if not config.triton.multi_kernel:
        return kernels
    optional_persistent = kernel.persistent_reduction and (not kernel_kwargs.get('override_persistent_reduction'))
    optional_cooperative = kernel.cooperative_reduction and (not kernel_kwargs.get('override_cooperative_reduction'))
    if <MASK>:
        kernels.append(self.kernel_type(*kernel_args, **kernel_kwargs, override_persistent_reduction=False))
    if optional_cooperative:
        rnumel = kernel.features.reduction_numel
        if V.graph.sizevars.statically_known_leq(rnumel, 65536):
            kernels.append((other := self.kernel_type(*kernel_args, **kernel_kwargs, override_cooperative_reduction=False)))
            if optional_persistent and other.persistent_reduction:
                kernels.append(self.kernel_type(*kernel_args, **kernel_kwargs, override_cooperative_reduction=False, override_persistent_reduction=False))
    if len(kernels) > 1:
        for kernel2 in kernels[1:]:
            kernel2.must_keep_buffers = kernel.must_keep_buffers
        kernels.sort(key=lambda k: k.persistent_reduction)
    return kernels

def simple_broadcast(value, destinations, always_mirrored=False, canonicalize_devices=True):
    """Broadcast `value` to `destinations` using simple copies."""
    devices = get_devices_from(destinations, canonicalize_devices)
    if <MASK>:
        return cross_device_utils.copy_tensor_or_indexed_slices_to_device(value, devices[0])
    else:
        value_updates = []
        for d in devices:
            value_updates.append(cross_device_utils.copy_tensor_or_indexed_slices_to_device(value, d))
        return distribute_utils.regroup(value_updates, wrap_class=value_lib.Mirrored)

def fallback_node_due_to_unsupported_type(node: torch.fx.Node, allow_cpu_inputs=True):
    if node.target is aten.view_as_complex.default:
        return False
    if node.op == 'placeholder':
        return False
    if node.target is aten.lift_fresh_copy.default:
        return False

    def check_skip_condition(inp_out_node, is_output):
        if not isinstance(inp_out_node, torch.fx.Node):
            return False
        if 'val' not in inp_out_node.meta:
            return False
        for meta in pytree.tree_leaves(inp_out_node.meta['val']):
            if not isinstance(meta, torch._subclasses.FakeTensor):
                continue
            if is_output:
                if unsupported_output_tensor(meta, node):
                    return True
            elif unsupported_input_tensor(meta, node):
                return True
        return False
    for arg in pytree.arg_tree_leaves(*node.args, **node.kwargs):
        if <MASK>:
            return True
    return check_skip_condition(node, is_output=True)

def log_prob(self, value):
    if <MASK>:
        self._validate_sample(value)
    lb = self.low.le(value).type_as(self.low)
    ub = self.high.gt(value).type_as(self.low)
    return torch.log(lb.mul(ub)) - torch.log(self.high - self.low)

def fallback_node_due_to_unsupported_type(node: torch.fx.Node, allow_cpu_inputs=True):
    if node.target is aten.view_as_complex.default:
        return False
    if node.op == 'placeholder':
        return False
    if node.target is aten.lift_fresh_copy.default:
        return False

    def check_skip_condition(inp_out_node, is_output):
        if not isinstance(inp_out_node, torch.fx.Node):
            return False
        if <MASK>:
            return False
        for meta in pytree.tree_leaves(inp_out_node.meta['val']):
            if not isinstance(meta, torch._subclasses.FakeTensor):
                continue
            if is_output:
                if unsupported_output_tensor(meta, node):
                    return True
            elif unsupported_input_tensor(meta, node):
                return True
        return False
    for arg in pytree.arg_tree_leaves(*node.args, **node.kwargs):
        if check_skip_condition(arg, is_output=False):
            return True
    return check_skip_condition(node, is_output=True)

def pickle_guards_state(state: GuardsState, guard_tree_values: dict[int, Any]) -> bytes:
    buf = io.BytesIO()
    empty_values = {}
    missing_values = {}
    leaves = pytree.tree_leaves(state.output_graph.local_scope)
    for leaf in leaves:
        if inspect.ismethod(leaf) and hasattr(leaf, '__self__'):
            base = leaf.__self__
            if <MASK>:
                try:
                    type(base).__new__(type(base))
                    empty_values[id(base)] = base
                except:
                    pass
        elif id(leaf) not in guard_tree_values:
            missing_values[id(leaf)] = leaf
    pickler = GuardsStatePickler(guard_tree_values, empty_values, missing_values, buf)
    try:
        pickler.dump(state)
    except AttributeError as e:
        raise torch._dynamo.exc.PackageError(str(e)) from e
    return buf.getvalue()

def handle_sizes_for_dynamic_shapes(func, args, kwargs):

    def f(args, kwargs, extra_args, extra_kwargs):
        if <MASK>:
            for (i, t) in extra_args:
                args[i] = t.size()
        if extra_kwargs:
            for (k, t) in extra_kwargs.items():
                kwargs[k] = t.size()
        return func(*args, **kwargs)
    extra_args = []
    extra_kwargs = {}
    for (i, arg) in enumerate(args):
        if isinstance(arg, torch.Size):
            extra_args.append((i, torch.empty(arg, device='cpu')))
    for (key, value) in kwargs.items():
        if isinstance(value, torch.Size):
            extra_kwargs[key] = torch.empty(value, device='cpu')
    return (f, args, kwargs, extra_args, extra_kwargs)

@unpack_zerodim_and_defer('__rtruediv__')
def __rtruediv__(self, other):
    op = roperator.rtruediv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)
    other = self._cast_divlike_op(other)
    if lib.is_np_dtype(other.dtype, 'm'):
        return self._vector_divlike_op(other, op)
    elif <MASK>:
        result_list = [other[n] / self[n] for n in range(len(self))]
        return np.array(result_list)
    else:
        return NotImplemented

def _order_by_pairs(self):
    if self.query.extra_order_by:
        ordering = self.query.extra_order_by
    elif not self.query.default_ordering:
        ordering = self.query.order_by
    elif self.query.order_by:
        ordering = self.query.order_by
    elif (meta := self.query.get_meta()) and meta.ordering:
        ordering = meta.ordering
        self._meta_ordering = ordering
    else:
        ordering = []
    if self.query.standard_ordering:
        (default_order, _) = ORDER_DIR['ASC']
    else:
        (default_order, _) = ORDER_DIR['DESC']
    selected_exprs = {}
    if ordering and (select := self.select):
        for (ordinal, (expr, _, alias)) in enumerate(select, start=1):
            pos_expr = PositionRef(ordinal, alias, expr)
            if alias:
                selected_exprs[alias] = pos_expr
            selected_exprs[expr] = pos_expr
    for field in ordering:
        if hasattr(field, 'resolve_expression'):
            if isinstance(field, Value):
                field = Cast(field, field.output_field)
            if not isinstance(field, OrderBy):
                field = field.asc()
            if not self.query.standard_ordering:
                field = field.copy()
                field.reverse_ordering()
            select_ref = selected_exprs.get(field.expression)
            if select_ref or (isinstance(field.expression, F) and (select_ref := selected_exprs.get(field.expression.name))):
                if field.nulls_first is None and field.nulls_last is None or self.connection.features.supports_order_by_nulls_modifier:
                    field = field.copy()
                    field.expression = select_ref
                elif <MASK>:
                    field = field.copy()
                    field.expression = Ref(select_ref.refs, select_ref.source)
            yield (field, select_ref is not None)
            continue
        if field == '?':
            yield (OrderBy(Random()), False)
            continue
        (col, order) = get_order_dir(field, default_order)
        descending = order == 'DESC'
        if (select_ref := selected_exprs.get(col)):
            yield (OrderBy(select_ref, descending=descending), True)
            continue
        if (expr := self.query.annotations.get(col)):
            ref = col
            transforms = []
        else:
            (ref, *transforms) = col.split(LOOKUP_SEP)
            expr = self.query.annotations.get(ref)
        if expr:
            if self.query.combinator and self.select:
                if transforms:
                    raise NotImplementedError('Ordering combined queries by transforms is not implemented.')
                expr = F(ref)
            if transforms:
                for name in transforms:
                    expr = self.query.try_transform(expr, name)
            if isinstance(expr, Value):
                expr = Cast(expr, expr.output_field)
            yield (OrderBy(expr, descending=descending), False)
            continue
        if '.' in field:
            (table, col) = col.split('.', 1)
            yield (OrderBy(RawSQL('%s.%s' % (self.quote_name_unless_alias(table), col), []), descending=descending), False)
            continue
        if self.query.extra and col in self.query.extra:
            if col in self.query.extra_select:
                yield (OrderBy(Ref(col, RawSQL(*self.query.extra[col])), descending=descending), True)
            else:
                yield (OrderBy(RawSQL(*self.query.extra[col]), descending=descending), False)
        elif self.query.combinator and self.select:
            yield (OrderBy(F(col), descending=descending), False)
        else:
            yield from self.find_ordering_name(field, self.query.get_meta(), default_order=default_order)

def find_functions(filename, tag='API'):
    """
    Scan the file, looking for tagged functions.

    Assuming ``tag=='API'``, a tagged function looks like::

        /*API*/
        static returntype*
        function_name(argtype1 arg1, argtype2 arg2)
        {
        }

    where the return type must be on a separate line, the function
    name must start the line, and the opening ``{`` must start the line.

    An optional documentation comment in ReST format may follow the tag,
    as in::

        /*API
          This function does foo...
         */
    """
    if filename.endswith(('.c.src', '.h.src')):
        fo = io.StringIO(process_c_file(filename))
    else:
        fo = open(filename, 'r')
    functions = []
    return_type = None
    function_name = None
    function_args = []
    doclist = []
    (SCANNING, STATE_DOC, STATE_RETTYPE, STATE_NAME, STATE_ARGS) = list(range(5))
    state = SCANNING
    tagcomment = '/*' + tag
    for (lineno, line) in enumerate(fo):
        try:
            line = line.strip()
            if state == SCANNING:
                if line.startswith(tagcomment):
                    if line.endswith('*/'):
                        state = STATE_RETTYPE
                    else:
                        state = STATE_DOC
            elif <MASK>:
                if line.startswith('*/'):
                    state = STATE_RETTYPE
                else:
                    line = line.lstrip(' *')
                    doclist.append(line)
            elif state == STATE_RETTYPE:
                m = re.match('NPY_NO_EXPORT\\s+(.*)$', line)
                if m:
                    line = m.group(1)
                return_type = line
                state = STATE_NAME
            elif state == STATE_NAME:
                m = re.match('(\\w+)\\s*\\(', line)
                if m:
                    function_name = m.group(1)
                else:
                    raise ParseError(filename, lineno + 1, 'could not find function name')
                function_args.append(line[m.end():])
                state = STATE_ARGS
            elif state == STATE_ARGS:
                if line.startswith('{'):
                    fargs_str = ' '.join(function_args).rstrip()[:-1].rstrip()
                    fargs = split_arguments(fargs_str)
                    f = Function(function_name, return_type, fargs, '\n'.join(doclist))
                    functions.append(f)
                    return_type = None
                    function_name = None
                    function_args = []
                    doclist = []
                    state = SCANNING
                else:
                    function_args.append(line)
        except ParseError:
            raise
        except Exception as e:
            msg = 'see chained exception for details'
            raise ParseError(filename, lineno + 1, msg) from e
    fo.close()
    return functions

def generate_inputs_for_model(model_cls, model, model_name, bs, device, include_loss_args=False):
    num_choices = 3
    num_visual_features = 42
    seq_length = get_sequence_length(model_cls, model_name)
    vocab_size = model.config.vocab_size
    if model_name.startswith('Wav2Vec2'):
        target_length = 100
        return {'input_values': torch.randn((bs, seq_length), device=device), 'attention_mask': rand_int_tensor(device, 0, 2, (bs, seq_length)), 'labels': rand_int_tensor(device, 0, vocab_size, (bs, target_length))}
    if <MASK>:
        input = rand_int_tensor(device, 0, vocab_size, (bs, num_choices, seq_length))
    elif model_name.startswith('Roberta'):
        input = rand_int_tensor(device, 0, 1, (bs, seq_length))
    else:
        input = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
    if 'Bart' in model_name:
        input[:, -1] = model.config.eos_token_id
    input_dict = {'input_ids': input}
    if model_name.startswith(('T5', 'M2M100', 'MT5')) or model_cls in [BlenderbotModel, BlenderbotSmallModel, BlenderbotForConditionalGeneration, PegasusModel, MarianModel, MarianMTModel]:
        input_dict['decoder_input_ids'] = input
    if model_name.startswith('Lxmert'):
        (visual_feat_dim, visual_pos_dim) = (model.config.visual_feat_dim, model.config.visual_pos_dim)
        input_dict['visual_feats'] = torch.randn(bs, num_visual_features, visual_feat_dim)
        input_dict['visual_pos'] = torch.randn(bs, num_visual_features, visual_pos_dim)
    if include_loss_args:
        if model_name.endswith('PreTraining'):
            if model_cls in [ElectraForPreTraining, LxmertForPreTraining]:
                input_dict['labels'] = rand_int_tensor(device, 0, 1, (bs, seq_length))
            else:
                label_name = 'sentence_order_label' if model_cls in [AlbertForPreTraining] else 'next_sentence_label'
                input_dict['labels'] = (rand_int_tensor(device, 0, vocab_size, (bs, seq_length)),)
                input_dict[label_name] = rand_int_tensor(device, 0, 1, (bs,))
        elif model_name.endswith('QuestionAnswering'):
            input_dict['start_positions'] = rand_int_tensor(device, 0, seq_length, (bs,))
            input_dict['end_positions'] = rand_int_tensor(device, 0, seq_length, (bs,))
        elif model_name.endswith(('MaskedLM', 'HeadModel', 'CausalLM', 'DoubleHeadsModel')):
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
        elif model_name.endswith('TokenClassification'):
            input_dict['labels'] = rand_int_tensor(device, 0, model.config.num_labels - 1, (bs, seq_length))
        elif model_name.endswith('MultipleChoice'):
            input_dict['labels'] = rand_int_tensor(device, 0, num_choices, (bs,))
        elif model_name.endswith('SequenceClassification'):
            input_dict['labels'] = rand_int_tensor(device, 0, model.config.num_labels - 1, (bs,))
        elif model_name.endswith('NextSentencePrediction'):
            input_dict['labels'] = rand_int_tensor(device, 0, 1, (bs,))
        elif model_name.endswith('ForConditionalGeneration'):
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size - 1, (bs, seq_length))
        elif model_name in EXTRA_MODELS:
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
        else:
            raise NotImplementedError(f'Class {model_name} unsupported for training test ')
    return input_dict

def new_symbol(self, name_root, reserved_locals):
    """See control_flow.SymbolNamer.new_symbol."""
    all_reserved_locals = set()
    for s in reserved_locals:
        if isinstance(s, qual_names.QN):
            all_reserved_locals.update(s.qn)
        elif isinstance(s, str):
            all_reserved_locals.add(s)
        else:
            raise ValueError('Unexpected symbol type "%s"' % type(s))
    pieces = name_root.split('_')
    if <MASK>:
        name_root = '_'.join(pieces[:-1])
        n = int(pieces[-1])
    else:
        n = 0
    new_name = name_root
    while new_name in self.global_namespace or new_name in all_reserved_locals or new_name in self.generated_names:
        n += 1
        new_name = '%s_%d' % (name_root, n)
    self.generated_names.add(new_name)
    return new_name

def inner_product(a: IntTuple, b: IntTuple) -> int:
    if <MASK>:
        assert len(a) == len(b)
        return sum((inner_product(x, y) for (x, y) in zip(a, b)))
    else:
        assert not is_tuple(a) and (not is_tuple(b))
        return a * b

@classmethod
def _pad_dense_input(cls, dense_input: torch.Tensor) -> torch.Tensor:
    """
        Calculates padding for dense tensor and pads tensor if necessary.
        If padding is not required, this function returns the original tensor.
        """
    assert dense_input.dim() == 2
    (m, n) = dense_input.shape
    min_rows = cls._DTYPE_SHAPE_CONSTRAINTS[dense_input.dtype].dense_min_rows
    min_cols = cls._DTYPE_SHAPE_CONSTRAINTS[dense_input.dtype].dense_min_cols
    to_pad_m = -m % min_rows if m < min_rows or m % min_rows else 0
    to_pad_n = -n % min_cols if n < min_cols or n % min_rows else 0
    if <MASK>:
        return torch.nn.functional.pad(dense_input, (0, to_pad_n, 0, to_pad_m))
    else:
        return dense_input

@classmethod
def _generate_range(cls, start, end, periods, freq, closed=None, *, unit: TimeUnit) -> Self:
    periods = dtl.validate_periods(periods)
    if freq is None and any((x is None for x in [periods, start, end])):
        raise ValueError('Must provide freq argument if no data is supplied')
    if com.count_not_none(start, end, periods, freq) != 3:
        raise ValueError('Of the four parameters: start, end, periods, and freq, exactly three must be specified')
    if start is not None:
        start = Timedelta(start).as_unit('ns')
    if end is not None:
        end = Timedelta(end).as_unit('ns')
    if unit not in ['s', 'ms', 'us', 'ns']:
        raise ValueError("'unit' must be one of 's', 'ms', 'us', 'ns'")
    if start is not None and unit is not None:
        start = start.as_unit(unit, round_ok=False)
    if end is not None and unit is not None:
        end = end.as_unit(unit, round_ok=False)
    (left_closed, right_closed) = validate_endpoints(closed)
    if <MASK>:
        index = generate_regular_range(start, end, periods, freq, unit=unit)
    else:
        index = np.linspace(start._value, end._value, periods).astype('i8')
    if not left_closed:
        index = index[1:]
    if not right_closed:
        index = index[:-1]
    td64values = index.view(f'm8[{unit}]')
    return cls._simple_new(td64values, dtype=td64values.dtype, freq=freq)

def _type(operator):
    """Returns the type name constant (e.g. _TRIL) for operator."""
    if isinstance(operator, linear_operator_diag.LinearOperatorDiag):
        return _DIAG
    if <MASK>:
        return _TRIL
    if isinstance(operator, linear_operator_full_matrix.LinearOperatorFullMatrix):
        return _MATRIX
    if isinstance(operator, linear_operator_identity.LinearOperatorIdentity):
        return _IDENTITY
    if isinstance(operator, linear_operator_identity.LinearOperatorScaledIdentity):
        return _SCALED_IDENTITY
    raise TypeError(f'Expected operator to be one of [LinearOperatorDiag, LinearOperatorLowerTriangular, LinearOperatorFullMatrix, LinearOperatorIdentity, LinearOperatorScaledIdentity]. Received: {operator}')

