def _load_tf_config(port):
    assert all([x in os.environ for x in [_SM_CURRENT_HOST, _SM_HOSTS]]), 'Not a SageMaker Environment'
    hosts = sorted(json.loads(os.environ[_SM_HOSTS])) if os.environ[_SM_HOSTS] != '' else []
    current_host = os.environ[_SM_CURRENT_HOST]
    if <MASK>:
        return {}
    host_index = hosts.index(current_host)
    hosts = ['%s:%s' % (host, port) for host in hosts]
    tf_config = {_CLUSTER_KEY: {_WORKER_KEY: hosts}, _TASK_KEY: {_TYPE_KEY: _WORKER_KEY, _INDEX_KEY: host_index}}
    return tf_config

def stride(self, name, index=None):
    """
        Hook called from template code to get the stride of an arg.
        Will add needed args to pass it in if it is dynamic.
        """
    if name is None:
        val = self.output_node.get_stride()
    else:
        assert isinstance(name, str)
        val = self.named_input_nodes[name].get_stride()
    if <MASK>:
        return texpr(self.rename_indexing(val[index]))
    return ', '.join([texpr(self.rename_indexing(i)) for i in val])

def _ensure_data(values: ArrayLike) -> np.ndarray:
    """
    routine to ensure that our data is of the correct
    input dtype for lower-level routines

    This will coerce:
    - ints -> int64
    - uint -> uint64
    - bool -> uint8
    - datetimelike -> i8
    - datetime64tz -> i8 (in local tz)
    - categorical -> codes

    Parameters
    ----------
    values : np.ndarray or ExtensionArray

    Returns
    -------
    np.ndarray
    """
    if not isinstance(values, ABCMultiIndex):
        values = extract_array(values, extract_numpy=True)
    if is_object_dtype(values.dtype):
        return ensure_object(np.asarray(values))
    elif isinstance(values.dtype, BaseMaskedDtype):
        values = cast('BaseMaskedArray', values)
        if not values._hasna:
            return _ensure_data(values._data)
        return np.asarray(values)
    elif isinstance(values.dtype, CategoricalDtype):
        values = cast('Categorical', values)
        return values.codes
    elif is_bool_dtype(values.dtype):
        if isinstance(values, np.ndarray):
            return np.asarray(values).view('uint8')
        else:
            return np.asarray(values).astype('uint8', copy=False)
    elif is_integer_dtype(values.dtype):
        return np.asarray(values)
    elif is_float_dtype(values.dtype):
        if values.dtype.itemsize in [2, 12, 16]:
            return ensure_float64(values)
        return np.asarray(values)
    elif is_complex_dtype(values.dtype):
        return cast(np.ndarray, values)
    elif <MASK>:
        npvalues = values.view('i8')
        npvalues = cast(np.ndarray, npvalues)
        return npvalues
    values = np.asarray(values, dtype=object)
    return ensure_object(values)

def __init__(self, src: ReadCsvBuffer[str], **kwds) -> None:
    super().__init__(kwds)
    self.kwds = kwds
    kwds = kwds.copy()
    self.low_memory = kwds.pop('low_memory', False)
    kwds['allow_leading_cols'] = self.index_col is not False
    kwds['usecols'] = self.usecols
    kwds['on_bad_lines'] = self.on_bad_lines.value
    for key in ('storage_options', 'encoding', 'memory_map', 'compression'):
        kwds.pop(key, None)
    kwds['dtype'] = ensure_dtype_objs(kwds.get('dtype', None))
    if 'dtype_backend' not in kwds or kwds['dtype_backend'] is lib.no_default:
        kwds['dtype_backend'] = 'numpy'
    if kwds['dtype_backend'] == 'pyarrow':
        import_optional_dependency('pyarrow')
    self._reader = parsers.TextReader(src, **kwds)
    self.unnamed_cols = self._reader.unnamed_cols
    passed_names = self.names is None
    if self._reader.header is None:
        self.names = None
    else:
        (self.names, self.index_names, self.col_names, passed_names) = self._extract_multi_indexer_columns(self._reader.header, self.index_names, passed_names)
    if self.names is None:
        self.names = list(range(self._reader.table_width))
    self.orig_names = self.names[:]
    if self.usecols:
        usecols = evaluate_callable_usecols(self.usecols, self.orig_names)
        assert self.orig_names is not None
        if self.usecols_dtype == 'string' and (not set(usecols).issubset(self.orig_names)):
            self._validate_usecols_names(usecols, self.orig_names)
        if len(self.names) > len(usecols):
            self.names = [n for (i, n) in enumerate(self.names) if i in usecols or n in usecols]
        if <MASK>:
            self._validate_usecols_names(usecols, self.names)
    validate_parse_dates_presence(self.parse_dates, self.names)
    self._set_noconvert_columns()
    self.orig_names = self.names
    if self._reader.leading_cols == 0 and is_index_col(self.index_col):
        (index_names, self.names, self.index_col) = self._clean_index_names(self.names, self.index_col)
        if self.index_names is None:
            self.index_names = index_names
    if self._reader.header is None and (not passed_names):
        assert self.index_names is not None
        self.index_names = [None] * len(self.index_names)
    self._implicit_index = self._reader.leading_cols > 0

def setup(**attr):
    cmdclass = numpy_cmdclass.copy()
    new_attr = attr.copy()
    if 'cmdclass' in new_attr:
        cmdclass.update(new_attr['cmdclass'])
    new_attr['cmdclass'] = cmdclass
    if 'configuration' in new_attr:
        configuration = new_attr.pop('configuration')
        old_dist = distutils.core._setup_distribution
        old_stop = distutils.core._setup_stop_after
        distutils.core._setup_distribution = None
        distutils.core._setup_stop_after = 'commandline'
        try:
            dist = setup(**new_attr)
        finally:
            distutils.core._setup_distribution = old_dist
            distutils.core._setup_stop_after = old_stop
        if dist.help or not _command_line_ok():
            return dist
        config = configuration()
        if hasattr(config, 'todict'):
            config = config.todict()
        _dict_append(new_attr, **config)
    libraries = []
    for ext in new_attr.get('ext_modules', []):
        new_libraries = []
        for item in ext.libraries:
            if is_sequence(item):
                (lib_name, build_info) = item
                _check_append_ext_library(libraries, lib_name, build_info)
                new_libraries.append(lib_name)
            elif is_string(item):
                new_libraries.append(item)
            else:
                raise TypeError('invalid description of extension module library %r' % (item,))
        ext.libraries = new_libraries
    if libraries:
        if <MASK>:
            new_attr['libraries'] = []
        for item in libraries:
            _check_append_library(new_attr['libraries'], item)
    if ('ext_modules' in new_attr or 'libraries' in new_attr) and 'headers' not in new_attr:
        new_attr['headers'] = []
    new_attr['distclass'] = NumpyDistribution
    return old_setup(**new_attr)

def _distribute_state_dict(full_state_dict: dict[str, Any], local_state_dict: dict[str, Any], device: torch.device, pg: Optional[dist.ProcessGroup]=None) -> None:
    for (key, value) in full_state_dict.items():
        if key not in full_state_dict:
            continue
        if not torch.is_tensor(value):
            local_state_dict[key] = value
        elif value.dim() == 0:
            local_state_dict[key] = value.cpu()
        else:
            assert isinstance(value, torch.Tensor)
            local_state = local_state_dict.get(key)
            if <MASK>:
                continue
            elif isinstance(local_state, DTensor):
                local_state_dict[key] = distribute_tensor(value.detach().to(device), local_state.device_mesh, local_state.placements)
            else:
                local_state_dict[key] = value.detach().to(device)

def _if_match_passes(target_etag, etags):
    """
    Test the If-Match comparison as defined in RFC 9110 Section 13.1.1.
    """
    if <MASK>:
        return False
    elif etags == ['*']:
        return True
    elif target_etag.startswith('W/'):
        return False
    else:
        return target_etag in etags

def _maybe_infer_ndim(values, placement: BlockPlacement, ndim: int | None) -> int:
    """
    If `ndim` is not provided, infer it from placement and values.
    """
    if ndim is None:
        if <MASK>:
            if len(placement) != 1:
                ndim = 1
            else:
                ndim = 2
        else:
            ndim = values.ndim
    return ndim

def has_large_inner_fn(self, threshold: Optional[int]=None) -> bool:
    if <MASK>:
        threshold = 0
    threshold = max(threshold, config.realize_opcount_threshold)
    return self.inner_fn_opcount().num_ops > threshold

@classmethod
def _validate_and_recreate_partition(cls, partition, partition_types):
    """Validates and recreates a partition object using the provided types.

    Args:
      partition: The partition object to validate and recreate.
      partition_types: A tuple of valid partition types.

    Returns:
      A new partition object of the correct type, or raises a TypeError.

    Raises:
      TypeError: If `partition` cannot be cast to any of the types in
        `partition_types`. This happens when the input `partition` object
        is not an instance of any of the expected partition types, and
        cannot be recreated using the provided `partition_types`.
    """
    if <MASK>:
        return partition
    for partition_type in partition_types:
        if str(type(partition)) == str(partition_type):
            if partition_type == cls.UniformRowLength:
                return partition_type(partition.length)
            else:
                return partition_type(partition.key)
    raise TypeError(f'Argument `partitions` cannot be cast to any of the partition types in {partition_types}; got: {partition!r} with type {type(partition)}')

