def set(self, property_name, property_val):
    """Set the value of a property.

    Supports limitd property value types: `bool`, `int` and `str`.

    Args:
      property_name: Name of the property.
      property_val: Value of the property. If the property has `bool` type and
        this argument has `str` type, the `str` value will be parsed as a `bool`

    Raises:
      ValueError: if a `str` property_value fails to be parsed as a `bool`.
      KeyError: if `property_name` is an invalid property name.
    """
    if property_name not in self._config:
        raise KeyError('%s is not a valid property name.' % property_name)
    orig_val = self._config[property_name]
    if isinstance(orig_val, bool):
        if isinstance(property_val, str):
            if property_val.lower() in ('1', 'true', 't', 'yes', 'y', 'on'):
                property_val = True
            elif <MASK>:
                property_val = False
            else:
                raise ValueError('Invalid string value for bool type: %s' % property_val)
        else:
            property_val = bool(property_val)
    elif isinstance(orig_val, int):
        property_val = int(property_val)
    elif isinstance(orig_val, str):
        property_val = str(property_val)
    else:
        raise TypeError('Unsupported property type: %s' % type(orig_val))
    self._config[property_name] = property_val
    self._save_to_file()
    if property_name in self._set_callbacks:
        self._set_callbacks[property_name](self._config)

def _compared_saved_loaded(self, m):

    def extract_files(buffer):
        archive = zipfile.ZipFile(buffer)
        self.assertEqual(len(set(archive.namelist())), len(archive.namelist()))
        files = list(filter(lambda x: x.startswith('archive/code/'), archive.namelist()))
        code_files_str = filter(lambda x: x.endswith('.py'), files)
        code_files_stream = (archive.open(f) for f in code_files_str)
        code_files = (''.join([line.decode() for line in file]) for file in code_files_stream)
        debug_files_str = filter(lambda f: f.endswith('.debug_pkl'), files)
        debug_files_stream = (archive.open(f) for f in debug_files_str)
        debug_files = (pickle.load(f) for f in debug_files_stream)
        return (code_files, debug_files)
    with torch._jit_internal._disable_emit_hooks():
        try:
            if <MASK>:
                return
            if isinstance(m, torch._C.ScriptModule):
                if len(m._method_names()) == 0:
                    return
            buffer = io.BytesIO()
            torch.jit.save(m, buffer)
            buffer_copy = buffer.getvalue()
            (code_files, _debug_files) = extract_files(buffer)
        except RuntimeError as e:
            if not self._isHookExceptionOk(e):
                raise
            else:
                return
        buffer2 = io.BytesIO(buffer_copy)
        imported = torch.jit.load(buffer2)
        saved_module_buffer_2 = io.BytesIO()
        torch.jit.save(imported, saved_module_buffer_2)
        saved_module_buffer_2.seek(0)
        (code_files_2, _debug_files_2) = extract_files(saved_module_buffer_2)
        for (a, b) in zip(code_files, code_files_2, strict=True):
            self.assertMultiLineEqual(a, b)
        if isinstance(m, torch._C.ScriptModule):
            self.assertTrue(torch._C._ivalue_tags_match(m, imported._c))

def _reduce(self, op, name: str, *, axis: Axis=0, skipna: bool=True, numeric_only: bool=False, filter_type=None, **kwds):
    assert filter_type is None or filter_type == 'bool', filter_type
    out_dtype = 'bool' if filter_type == 'bool' else None
    if axis is not None:
        axis = self._get_axis_number(axis)

    def func(values: np.ndarray):
        return op(values, axis=axis, skipna=skipna, **kwds)

    def blk_func(values, axis: Axis=1):
        if isinstance(values, ExtensionArray):
            if not is_1d_only_ea_dtype(values.dtype):
                return values._reduce(name, axis=1, skipna=skipna, **kwds)
            return values._reduce(name, skipna=skipna, keepdims=True, **kwds)
        else:
            return op(values, axis=axis, skipna=skipna, **kwds)

    def _get_data() -> DataFrame:
        if filter_type is None:
            data = self._get_numeric_data()
        else:
            assert filter_type == 'bool'
            data = self._get_bool_data()
        return data
    df = self
    if numeric_only:
        df = _get_data()
    if <MASK>:
        dtype = find_common_type([block.values.dtype for block in df._mgr.blocks])
        if isinstance(dtype, ExtensionDtype):
            df = df.astype(dtype)
            arr = concat_compat(list(df._iter_column_arrays()))
            return arr._reduce(name, skipna=skipna, keepdims=False, **kwds)
        return func(df.values)
    elif axis == 1:
        if len(df.index) == 0:
            result = df._reduce(op, name, axis=0, skipna=skipna, numeric_only=False, filter_type=filter_type, **kwds).iloc[:0]
            result.index = df.index
            return result
        if df.shape[1] and name != 'kurt':
            dtype = find_common_type([block.values.dtype for block in df._mgr.blocks])
            if isinstance(dtype, ExtensionDtype):
                name = {'argmax': 'idxmax', 'argmin': 'idxmin'}.get(name, name)
                df = df.astype(dtype)
                arr = concat_compat(list(df._iter_column_arrays()))
                (nrows, ncols) = df.shape
                row_index = np.tile(np.arange(nrows), ncols)
                col_index = np.repeat(np.arange(ncols), nrows)
                ser = Series(arr, index=col_index, copy=False)
                if name == 'all':
                    skipna = True
                result = ser.groupby(row_index).agg(name, **kwds, skipna=skipna)
                result.index = df.index
                return result
        df = df.T
    res = df._mgr.reduce(blk_func)
    out = df._constructor_from_mgr(res, axes=res.axes).iloc[0]
    if out_dtype is not None and out.dtype != 'boolean':
        out = out.astype(out_dtype)
    elif (df._mgr.get_dtypes() == object).any() and name not in ['any', 'all']:
        out = out.astype(object)
    elif len(self) == 0 and out.dtype == object and (name in ('sum', 'prod')):
        out = out.astype(np.float64)
    return out

def initialize_all(self):
    """Initialize all uninitialized lazy variables stored in scope."""

    def assign_function(uninitialized_var_list):
        for var in uninitialized_var_list:
            val = var._initial_value
            packed_var = getattr(var, '_packed_var', None)
            handle = getattr(packed_var, 'packed_handle', var.handle)
            with ops.device(handle.device):
                resource_variable_ops.AssignVariableOp(resource=handle, value=val)
        return constant_op.constant([])
    assign_tf_function = def_function.function(assign_function, autograph=False, jit_compile=False)
    with ops.init_scope():
        if <MASK>:
            assign_tf_function(self._uninitialized_var_list)
        else:
            assign_function(self._uninitialized_var_list)
    self._uninitialized_var_list = []

def get_qparam_dict(observer_or_fake_quant):
    from torch.ao.quantization.observer import PlaceholderObserver
    qscheme = getattr(observer_or_fake_quant, 'qscheme', None)
    dtype = observer_or_fake_quant.dtype
    qparams = {'qscheme': qscheme, 'dtype': dtype}
    if <MASK>:
        return {'qscheme': None, 'dtype': dtype}
    if is_per_tensor(qscheme):
        qscheme = torch.per_tensor_affine
    elif is_per_channel(qscheme):
        if qscheme == torch.per_channel_symmetric:
            qscheme = torch.per_channel_affine
        qparams['axis'] = observer_or_fake_quant.ch_axis
    else:
        raise RuntimeError(f'Unrecognized qscheme: {qscheme}')
    qparams['qscheme'] = qscheme
    (scale, zero_point) = observer_or_fake_quant.calculate_qparams()
    qparams['scale'] = scale
    qparams['zero_point'] = zero_point
    if hasattr(observer_or_fake_quant, 'quant_min'):
        qparams['quant_min'] = observer_or_fake_quant.quant_min
    if hasattr(observer_or_fake_quant, 'quant_max'):
        qparams['quant_max'] = observer_or_fake_quant.quant_max
    return qparams

def _dt_tz_localize(self, tz, ambiguous: TimeAmbiguous='raise', nonexistent: TimeNonexistent='raise') -> Self:
    if <MASK>:
        raise NotImplementedError(f'ambiguous={ambiguous!r} is not supported')
    nonexistent_pa = {'raise': 'raise', 'shift_backward': 'earliest', 'shift_forward': 'latest'}.get(nonexistent, None)
    if nonexistent_pa is None:
        raise NotImplementedError(f'nonexistent={nonexistent!r} is not supported')
    if tz is None:
        result = pc.local_timestamp(self._pa_array)
    else:
        result = pc.assume_timezone(self._pa_array, str(tz), ambiguous=ambiguous, nonexistent=nonexistent_pa)
    return self._from_pyarrow_array(result)

