def _get_group_start_end(start, end, pattern):
    (unmatched_open_brackets, prev_char) = (1, None)
    for (idx, val) in enumerate(pattern[end:]):
        if val == '(' and prev_char != '\\':
            unmatched_open_brackets += 1
        elif val == ')' and prev_char != '\\':
            unmatched_open_brackets -= 1
        prev_char = val
        if <MASK>:
            return (start, end + idx + 1)

def notebook_modification_function(notebook_content, notebook_filename):
    notebook_content_str = str(notebook_content)
    warning_template = '\n'.join(["<div class='alert alert-{message_class}'>", '', '# JupyterLite warning', '', '{message}', '</div>'])
    message_class = 'warning'
    message = 'Running the scikit-learn examples in JupyterLite is experimental and you may encounter some unexpected behavior.\n\nThe main difference is that imports will take a lot longer than usual, for example the first `import sklearn` can take roughly 10-20s.\n\nIf you notice problems, feel free to open an [issue](https://github.com/scikit-learn/scikit-learn/issues/new/choose) about it.'
    markdown = warning_template.format(message_class=message_class, message=message)
    dummy_notebook_content = {'cells': []}
    add_markdown_cell(dummy_notebook_content, markdown)
    code_lines = []
    if <MASK>:
        code_lines.append('%pip install seaborn')
    if 'plotly.express' in notebook_content_str:
        code_lines.append('%pip install plotly nbformat')
    if 'skimage' in notebook_content_str:
        code_lines.append('%pip install scikit-image')
    if 'polars' in notebook_content_str:
        code_lines.append('%pip install polars')
    if 'fetch_' in notebook_content_str:
        code_lines.extend(['%pip install pyodide-http', 'import pyodide_http', 'pyodide_http.patch_all()'])
    code_lines.extend(['import matplotlib', 'import pandas'])
    if 'dev' in release:
        dev_docs_specific_code = ['import piplite', 'import joblib', 'import threadpoolctl', 'import scipy', f"await piplite.install(\n  'scikit-learn=={release}',\n   index_urls='https://pypi.anaconda.org/scientific-python-nightly-wheels/simple',\n)"]
        code_lines.extend(dev_docs_specific_code)
    if code_lines:
        code_lines = ['# JupyterLite-specific code'] + code_lines
        code = '\n'.join(code_lines)
        add_code_cell(dummy_notebook_content, code)
    notebook_content['cells'] = dummy_notebook_content['cells'] + notebook_content['cells']

def get_mappings(self) -> dict[str, float]:
    path = REPO_ROOT / ADDITIONAL_CI_FILES_FOLDER / 'llm_results/mappings/indexer-files-gitdiff-output.json'
    if not os.path.exists(path):
        print(f'could not find path {path}')
        return {}
    with open(path) as f:
        r = defaultdict(list)
        for (key, value) in json.load(f).items():
            re_match = re.match('(.*).py', key)
            if <MASK>:
                file = re_match.group(1)
                r[file].append(value)
        r = {file: sum(scores) / len(scores) for (file, scores) in r.items()}
        return r

def save_variables(saved_variables: Sequence[SavedAttribute], is_output: bool, guard_for: Callable[[SavedAttribute], str | None]=lambda name: None) -> Sequence[str]:
    stmts: list[str] = []
    for arg in sorted(saved_variables, key=lambda sa: str(sa.nctype.name)):
        name = arg.nctype.name.name if isinstance(arg.nctype.name, SpecialArgName) else arg.nctype.name
        foreacharg: Argument | None = None
        is_foreacharg_list_type: bool = False
        type = arg.nctype.type
        expr = arg.expr
        stmts_prepend = None
        if is_inplace_foreach and info is not None:
            name_to_query = name.split('_scalar_type')[0]
            if name_to_query in refargname2inplace_foreacharg:
                foreacharg = refargname2inplace_foreacharg[name_to_query]
                is_foreacharg_list_type = isinstance(foreacharg.type, ListType)
            if foreacharg is not None:
                name_in_expr = f"{foreacharg.name}{('[i]' if is_foreacharg_list_type else '')}"
                src_name = name
                if '_scalar_type' in src_name:
                    split_src_name = src_name.split('_scalar_type')
                    assert len(split_src_name) == 2
                    src_name = split_src_name[0]
                expr = expr.replace(src_name, name_in_expr)
        if type == BaseCType(tensorT) or type == OptionalCType(BaseCType(tensorT)) or type == MutRefCType(OptionalCType(BaseCType(tensorT))) or (is_output and type == BaseCType(scalarT)):
            var = name
            name += '_'
            if var == 'self' and inplace:
                original_self_var = 'original_self' if not is_inplace_foreach else 'original_selfs[i]'
                self_var = var if not is_inplace_foreach else var + '[i]'
                stmts_prepend = f'if (!{original_self_var}.has_value()) {original_self_var} = {self_var}.clone()'
                var = f'{original_self_var}.value()'
                assert not is_output
            if inplace and is_output:
                assert name == 'result_'
                var = 'self[i]' if is_inplace_foreach or is_foreacharg_list_type else 'self'
                is_inplace_view = f'{var}.is_view()'
                expr = f'SavedVariable({var}, {str(is_output).lower()}, {is_inplace_view})'
            else:
                expr = f'SavedVariable({var}, {str(is_output).lower()})'
                if foreacharg is not None and 'original_selfs' not in expr:
                    expr = expr.replace(src_name, name_in_expr)
        elif type == BaseCType(tensorListT) or type == ListCType(OptionalCType(BaseCType(tensorT))) or type == BaseCType(iTensorListRefT) or (type == VectorCType(BaseCType(tensorT))):
            if type == VectorCType(BaseCType(tensorT)):
                assert is_foreach and is_output
            expr = f'make_saved_variable_list({name}, {str(is_foreach and is_output).lower()})'
            name += '_'
        elif type == BaseCType(intArrayRefT):
            expr = expr + '.vec()'
        elif <MASK>:
            expr = expr + '.vec()'
        elif type == BaseCType(stringT):
            expr = f'std::string({expr})'
        elif type == OptionalCType(BaseCType(stringT)):
            expr = f'{expr}.has_value() ? ::std::optional<std::string>(std::string({expr}.value())) : ::std::nullopt'
        elif type == ArrayRefCType(elem=BaseCType(type=BaseCppType(ns='at', name='Scalar'))):
            expr = expr + '.vec()'
        guard = guard_for(arg)
        if guard is None:
            if stmts_prepend:
                stmts.append(f'{stmts_prepend};')
            stmts.append(f'grad_fn->{name} = {expr};')
        else:
            stmts.append(f'if ({guard}) {{')
            if stmts_prepend:
                stmts.append(f'  {stmts_prepend};')
            stmts.append(f'  grad_fn->{name} = {expr};')
            stmts.append('}')
    return stmts

def call_run(self, variable: Union['TritonKernelVariable', 'TraceableTritonKernelWrapper'], args: Sequence[Any], kwargs: dict[str, Any], tx: Optional['InstructionTranslator']) -> Optional['ConstantVariable']:
    if <MASK>:
        self.raise_unsupported('Triton kernel requires to be called with a grid')
    grid = kwargs.pop('grid')
