def _convert_index(name: str, index: Index, encoding: str, errors: str) -> IndexCol:
    assert isinstance(name, str)
    index_name = index.name
    (converted, dtype_name) = _get_data_and_dtype_name(index)
    kind = _dtype_to_kind(dtype_name)
    atom = DataIndexableCol._get_atom(converted)
    if <MASK>:
        return IndexCol(name, values=converted, kind=kind, typ=atom, freq=getattr(index, 'freq', None), tz=getattr(index, 'tz', None), index_name=index_name)
    if isinstance(index, MultiIndex):
        raise TypeError('MultiIndex not supported here!')
    inferred_type = lib.infer_dtype(index, skipna=False)
    values = np.asarray(index)
    if inferred_type == 'date':
        converted = np.asarray([v.toordinal() for v in values], dtype=np.int32)
        return IndexCol(name, converted, 'date', _tables().Time32Col(), index_name=index_name)
    elif inferred_type == 'string':
        converted = _convert_string_array(values, encoding, errors)
        itemsize = converted.dtype.itemsize
        return IndexCol(name, converted, 'string', _tables().StringCol(itemsize), index_name=index_name)
    elif inferred_type in ['integer', 'floating']:
        return IndexCol(name, values=converted, kind=kind, typ=atom, index_name=index_name)
    else:
        assert isinstance(converted, np.ndarray) and converted.dtype == object
        assert kind == 'object', kind
        atom = _tables().ObjectAtom()
        return IndexCol(name, converted, kind, atom, index_name=index_name)

def fuzz_inputs_specs(self, output_spec: Spec) -> list[Spec]:
    """Generate input spec for unsqueeze operation."""
    if not isinstance(output_spec, TensorSpec):
        raise ValueError('UnsqueezeOperator can only produce TensorSpec outputs')
    input_size = list(output_spec.size)
    singleton_idx = None
    for i in range(len(input_size) - 1, -1, -1):
        if input_size[i] == 1:
            singleton_idx = i
            break
    if singleton_idx is not None:
        input_size.pop(singleton_idx)
    else:
        raise ValueError('UnsqueezeOperator requires output to have at least one singleton dimension')
    if <MASK>:
        input_size = tuple()
    else:
        input_size = tuple(input_size)
    from torchfuzz.tensor_fuzzer import fuzz_valid_stride
    if input_size:
        input_stride = fuzz_valid_stride(input_size)
    else:
        input_stride = tuple()
    return [TensorSpec(size=input_size, stride=input_stride, dtype=output_spec.dtype)]

def get_initial_state(self, inputs=None, batch_size=None, dtype=None):
    if inputs is not None:
        inputs = tensor_conversion.convert_to_tensor_v2_with_dispatch(inputs, name='inputs')
        if batch_size is not None:
            if tensor_util.is_tf_type(batch_size):
                static_batch_size = tensor_util.constant_value(batch_size, partial=True)
            else:
                static_batch_size = batch_size
            if <MASK>:
                raise ValueError('batch size from input tensor is different from the input param. Input tensor batch: {}, batch_size: {}'.format(inputs.shape.dims[0].value, batch_size))
        if dtype is not None and inputs.dtype != dtype:
            raise ValueError('dtype from input tensor is different from the input param. Input tensor dtype: {}, dtype: {}'.format(inputs.dtype, dtype))
        batch_size = inputs.shape.dims[0].value or array_ops.shape(inputs)[0]
        dtype = inputs.dtype
    if batch_size is None or dtype is None:
        raise ValueError('batch_size and dtype cannot be None while constructing initial state: batch_size={}, dtype={}'.format(batch_size, dtype))
    return self.zero_state(batch_size, dtype)

def strip_comments(line: str, in_block: bool) -> tuple[str, bool]:
    """
    Return (code_without_comments, updated_in_block).
    Removes // line comments and /* ... */ block comments (non-nesting, C-style).
    """
    i = 0
    out_parts: list[str] = []
    n = len(line)
    while i < n:
        if in_block:
            end = line.find('*/', i)
            if <MASK>:
                return (''.join(out_parts), True)
            i = end + 2
            in_block = False
            continue
        sl = line.find('//', i)
        bl = line.find('/*', i)
        if sl != -1 and (bl == -1 or sl < bl):
            out_parts.append(line[i:sl])
            return (''.join(out_parts), in_block)
        if bl != -1:
            out_parts.append(line[i:bl])
            i = bl + 2
            in_block = True
            continue
        out_parts.append(line[i:])
        break
    return (''.join(out_parts), in_block)

def _do_convert_categoricals(self, data: DataFrame, value_label_dict: dict[str, dict[int, str]], lbllist: Sequence[str], order_categoricals: bool) -> DataFrame:
    """
        Converts categorical columns to Categorical type.
        """
    if not value_label_dict:
        return data
    cat_converted_data = []
    for (col, label) in zip(data, lbllist, strict=True):
        if label in value_label_dict:
            vl = value_label_dict[label]
            keys = np.array(list(vl.keys()))
            column = data[col]
            key_matches = column.isin(keys)
            if self._using_iterator and key_matches.all():
                initial_categories: np.ndarray | None = keys
            else:
                if <MASK>:
                    warnings.warn(categorical_conversion_warning, CategoricalConversionWarning, stacklevel=find_stack_level())
                initial_categories = None
            cat_data = Categorical(column, categories=initial_categories, ordered=order_categoricals)
            if initial_categories is None:
                categories = []
                for category in cat_data.categories:
                    if category in vl:
                        categories.append(vl[category])
                    else:
                        categories.append(category)
            else:
                categories = list(vl.values())
            try:
                cat_data = cat_data.rename_categories(categories)
            except ValueError as err:
                vc = Series(categories, copy=False).value_counts()
                repeated_cats = list(vc.index[vc > 1])
                repeats = '-' * 80 + '\n' + '\n'.join(repeated_cats)
                msg = f'\nValue labels for column {col} are not unique. These cannot be converted to\npandas categoricals.\n\nEither read the file with `convert_categoricals` set to False or use the\nlow level interface in `StataReader` to separately read the values and the\nvalue_labels.\n\nThe repeated labels are:\n{repeats}\n'
                raise ValueError(msg) from err
            cat_series = Series(cat_data, index=data.index, copy=False)
            cat_converted_data.append((col, cat_series))
        else:
            cat_converted_data.append((col, data[col]))
    data = DataFrame(dict(cat_converted_data), copy=False)
    return data

