def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    """
        Compute boolean array of whether each value is found in the
        passed set of values.

        Parameters
        ----------
        values : np.ndarray or ExtensionArray

        Returns
        -------
        ndarray[bool]
        """
    if values.dtype.kind in 'fiuc':
        return np.zeros(self.shape, dtype=bool)
    values = ensure_wrapped_if_datetimelike(values)
    if not isinstance(values, type(self)):
        if values.dtype == object:
            values = lib.maybe_convert_objects(values, convert_non_numeric=True, dtype_if_all_nat=self.dtype)
            if values.dtype != object:
                return self.isin(values)
            else:
                return isin(self.astype(object), values)
        return np.zeros(self.shape, dtype=bool)
    if <MASK>:
        self = cast('DatetimeArray | TimedeltaArray', self)
        values = values.as_unit(self.unit)
    try:
        self._check_compatible_with(values)
    except (TypeError, ValueError):
        return np.zeros(self.shape, dtype=bool)
    return isin(self.asi8, values.asi8)

@override
def __enter__(self) -> Self:
    super().__enter__()
    for set_name in dir(V):
        if not set_name.startswith('set_'):
            continue
        name = set_name[4:]
        name = name.removesuffix('_handler')
        set_handler = getattr(V, set_name)
        if <MASK>:
            value = getattr(self.virtualized, name)
        else:
            value = torch._inductor.virtualized._PoisonedVirtual
        self.enter_context(set_handler(value))
    return self

def _std_var(input: Union[Tensor, MaskedTensor], dim: DimOrDims, unbiased: Optional[bool], *, correction_opt: Optional[Union[int, float]], keepdim: Optional[bool], dtype: Optional[DType], mask: Optional[Tensor], take_sqrt: Optional[bool]) -> Tensor:
    assert unbiased is None or correction_opt is None, 'Only one of unbiased and correction may be given'
    correction = 1.0
    if unbiased is not None:
        correction = 1.0 if unbiased else 0.0
    if correction_opt is not None:
        correction = sym_float(correction_opt)
    if dtype is None:
        dtype = input.dtype
        if not (dtype.is_floating_point or dtype.is_complex):
            dtype = torch.float32
    compute_dtype = dtype
    if not (compute_dtype.is_floating_point or compute_dtype.is_complex):
        compute_dtype = torch.float32
    if <MASK>:
        if mask is None:
            count = sum(torch.ones(input.shape, dtype=torch.int64, device=input.device), dim, keepdim=True)
            sample_total = sum(input, dim, keepdim=True, dtype=dtype)
        else:
            inmask = _input_mask(input, mask=mask)
            count = inmask.sum(dim=dim, keepdim=True)
            sample_total = sum(input, dim, keepdim=True, dtype=dtype, mask=inmask)
        sample_mean = torch.divide(sample_total, count)
        x = torch.subtract(input, sample_mean)
        if mask is None:
            total = sum(x * x.conj(), dim, keepdim=keepdim, dtype=compute_dtype)
        else:
            total = sum(x * x.conj(), dim, keepdim=keepdim, dtype=compute_dtype, mask=inmask)
        if not keepdim:
            count = count.reshape(total.shape)
        if correction != 0:
            real_dtype = corresponding_real_dtype(compute_dtype) if compute_dtype.is_complex else compute_dtype
            count = count.to(real_dtype)
            count = torch.subtract(count, correction)
            count = torch.maximum(count, count.new_zeros([]))
        output = torch.divide(total, count).to(dtype=dtype)
        if take_sqrt:
            output = torch.sqrt(output)
        return output
    else:
        raise ValueError(f'masked std/var expects strided tensor (got {input.layout} tensor)')

@staticmethod
def _effective_default(field):
    if field.has_default():
        default = field.get_default()
    elif field.generated:
        default = None
    elif not field.null and field.blank and field.empty_strings_allowed:
        if field.get_internal_type() == 'BinaryField':
            default = b''
        else:
            default = ''
    elif getattr(field, 'auto_now', False) or getattr(field, 'auto_now_add', False):
        internal_type = field.get_internal_type()
        if <MASK>:
            default = timezone.now()
        else:
            default = datetime.now()
            if internal_type == 'DateField':
                default = default.date()
            elif internal_type == 'TimeField':
                default = default.time()
    else:
        default = None
    return default

def fuse(model: torch.nn.Module, inplace=False, no_trace=False) -> torch.nn.Module:
    """
    Fuses convolution/BN and linear/BN layers for inference purposes.
    Will deepcopy your model by default, but can modify the model inplace as well.
    """
    patterns = [(nn.Conv1d, nn.BatchNorm1d), (nn.Conv2d, nn.BatchNorm2d), (nn.Conv3d, nn.BatchNorm3d), (nn.Linear, nn.BatchNorm1d)]
    if not inplace:
        model = copy.deepcopy(model)
    if not no_trace or not isinstance(model, torch.fx.GraphModule):
        fx_model = fx.symbolic_trace(model)
    else:
        fx_model = model
    modules = dict(fx_model.named_modules())
    new_graph = copy.deepcopy(fx_model.graph)
    for pattern in patterns:
        for node in new_graph.nodes:
            if matches_module_pattern(pattern, node, modules):
                if len(node.args[0].users) > 1:
                    continue
                first_layer = modules[node.args[0].target]
                bn = modules[node.target]
                if not bn.track_running_stats:
                    continue
                if <MASK>:
                    fused_layer = fuse_conv_bn_eval(first_layer, bn)
                else:
                    fused_layer = fuse_linear_bn_eval(first_layer, bn)
                replace_node_module(node.args[0], modules, fused_layer)
                node.replace_all_uses_with(node.args[0])
                new_graph.erase_node(node)
    return fx.GraphModule(fx_model, new_graph)

@_onnx_symbolic('aten::unsafe_chunk')
@symbolic_helper.parse_args('v', 'i', 'i', 'i')
def unsafe_chunk(g: jit_utils.GraphContext, self, chunks, dim, _outputs=None):
    if _outputs is None:
        return symbolic_helper._onnx_opset_unsupported_detailed('unsafe_chunk', 9, 11, 'Dynamic number of outputs not supported', self)
    size = symbolic_helper._get_tensor_dim_size(self, dim)
    if <MASK>:
        return symbolic_helper._unimplemented('unsafe_chunk', 'unknown dimension size', self)
    split_size = (size + chunks - 1) // chunks
    splits = [split_size] * (size // split_size)
    leftover = size % split_size
    if leftover:
        splits.append(leftover)
    return g.op('Split', self, split_i=splits, axis_i=dim, outputs=_outputs)

def _create_cloned_datasets_from_dataset(self, dataset, input_context, input_workers, strategy, num_replicas_in_sync):
    if <MASK>:
        num_workers = input_context.num_input_pipelines if input_context else len(input_workers.worker_devices)
        rebatch_fn = self._make_rebatch_fn(dataset, num_workers, num_replicas_in_sync)
    else:
        rebatch_fn = None
    self._cloned_datasets = []
    if input_context:
        assert input_workers.num_workers == 1
        if rebatch_fn is not None:
            dataset = rebatch_fn(dataset, input_context.input_pipeline_id)
        dataset = input_ops.auto_shard_dataset(dataset, input_context.num_input_pipelines, input_context.input_pipeline_id, num_replicas_in_sync)
        self._cloned_datasets.append(dataset)
    else:
        replicated_ds = distribute.replicate(dataset, input_workers.worker_devices)
        for (i, worker) in enumerate(input_workers.worker_devices):
            with ops.device(worker):
                cloned_dataset = replicated_ds[worker]
                if rebatch_fn is not None:
                    cloned_dataset = rebatch_fn(cloned_dataset, i)
                cloned_dataset = input_ops.auto_shard_dataset(cloned_dataset, len(input_workers.worker_devices), i, num_replicas_in_sync)
                self._cloned_datasets.append(cloned_dataset)

def _serialize_to_tensors(self):
