        with ops.device(v.device):
            if <MASK>:
                return None
            x = v.read_value_no_copy()
            with ops.device('/device:CPU:0'):
                return array_ops.identity(x)
    return {trackable.VARIABLE_VALUE_KEY: tensor_callable.Callable(_read_variable_closure, dtype=self.dtype, device=self.device)}

def _scalar_divlike_op(self, other, op):
    """
        Shared logic for __truediv__, __rtruediv__, __floordiv__, __rfloordiv__
        with scalar 'other'.
        """
    if isinstance(other, self._recognized_scalars):
        other = Timedelta(other)
        if cast('Timedelta | NaTType', other) is NaT:
            res = np.empty(self.shape, dtype=np.float64)
            res.fill(np.nan)
            return res
        return op(self._ndarray, other)
    else:
        if op in [roperator.rtruediv, roperator.rfloordiv]:
            raise TypeError(f'Cannot divide {type(other).__name__} by {type(self).__name__}')
        result = op(self._ndarray, other)
        freq = None
        if self.freq is not None:
            if isinstance(self.freq, Day):
                if self.freq.n % other == 0:
                    freq = Day(self.freq.n // other)
                else:
                    freq = to_offset(Timedelta(days=self.freq.n)) / other
            else:
                freq = self.freq / other
            if <MASK>:
                freq = None
        return type(self)._simple_new(result, dtype=result.dtype, freq=freq)

def _get_obj_state(obj):
    getstate_fn = getattr(obj, '__getstate__', None)
    if <MASK>:
        state = getstate_fn()
    else:
        slots_to_save = copyreg._slotnames(obj.__class__)
        if slots_to_save:
            state = (obj.__dict__, {name: getattr(obj, name) for name in slots_to_save if hasattr(obj, name)})
        else:
            state = obj.__dict__
    return state

def unzip_namedshape(namedshape):
    if isinstance(namedshape, OrderedDict):
        namedshape = namedshape.items()
    if <MASK>:
        raise RuntimeError(f'Expected namedshape to be OrderedDict or iterable of tuples, got: {type(namedshape)}')
    if len(namedshape) == 0:
