    return zip(*namedshape)

def _check_missing_keys_on_rank(r0_optim_state_keys: list[_OptimStateKey], optim_state_key_to_param_key: dict[_OptimStateKey, Union[str, int]], param_key_to_param: dict[Union[str, int], nn.Parameter], group: Optional[dist.ProcessGroup]) -> None:
    missing_keys: list[_OptimStateKey] = []
    for r0_optim_state_key in r0_optim_state_keys:
        if <MASK>:
            missing_keys.append(r0_optim_state_key)
            continue
        param_key = optim_state_key_to_param_key[r0_optim_state_key]
        if isinstance(param_key, int):
            if not (param_key >= 0 and param_key < len(param_key_to_param)):
                raise AssertionError('Check the `param_key_to_param` construction')
    device = _get_pg_default_device(group)
    num_missing = torch.tensor([len(missing_keys)], dtype=torch.int32, device=device)
    dist.all_reduce(num_missing, group=group)
    if num_missing.item() > 0:
        obj_list = [None for _ in range(dist.get_world_size(group))]
        dist.all_gather_object(obj_list, missing_keys, group=group)
        error_msg = "FSDP currently requires each rank to have at least the optimizer states needed by rank 0's optimizer but some ranks are missing some of those states"
        for (rank, keys) in enumerate(obj_list):
            keys = cast(list[_OptimStateKey], keys)
            if len(keys) > 0:
                error_msg += f'\nRank {rank} is missing states for the parameters: {[key.unflat_param_names for key in keys]}'
        raise RuntimeError(error_msg)

def call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if <MASK>:
        result = self.fn(*[x.as_python_constant() for x in args], **{k: v.as_python_constant() for (k, v) in kwargs.items()})
        return VariableTracker.build(tx, result)
    if self.fn is builtins.sum and len(args) == 1 and (not kwargs) and isinstance(args[0], (variables.ListVariable, variables.TupleVariable)) and all((isinstance(x, variables.ConstantVariable) and isinstance(x.value, int) or (isinstance(x, variables.SymNodeVariable) and x.python_type() is int) for x in args[0].items)):
        return variables.SymNodeVariable.create(tx, tx.output.create_proxy('call_function', torch.sym_sum, (tuple((a.as_proxy() for a in args[0].items)),), {}), sym_num=torch.sym_sum([x.value if isinstance(x, variables.ConstantVariable) else x.sym_num for x in args[0].items]))
    traceable_function_variable = VariableTracker.build(tx, self.traceable_fn)
    return traceable_function_variable.call_function(tx, args, kwargs)

@classmethod
def _find_localzeros(cls, values, **options):
    """
        Sequentially allocate values to localzeros.

        When a value is identified as being more extreme than another member it
        replaces that member; if this is never true, then the value is simply
        appended to the localzeros.

        Unlike the sympy implementation, we only look for zero and one, we don't
        do generic is connected test pairwise which is slow
        """
    other_values = set()
    num_value = None
    for arg in values:
        if arg.is_Number:
            if num_value is None:
                num_value = arg
            elif cls is Max:
                num_value = max(num_value, arg)
            elif <MASK>:
                num_value = min(num_value, arg)
            else:
                raise AssertionError(f'impossible {cls}')
        else:
            other_values.add(arg)
    if num_value is None:
        return other_values
    if len(other_values) == 0:
        return {num_value}
    if len(other_values) == 1:
        other_value = next(iter(other_values))
        if num_value in (0.0, 0) and other_value.is_nonnegative:
            return other_values if cls is Max else {num_value}
        if num_value == 1 and other_value.is_positive:
            return other_values if cls is Max else {num_value}
    other_values.add(num_value)
    return other_values

def is_sequence(seq):
    if <MASK>:
        return False
    try:
        len(seq)
    except Exception:
        return False
    return True

def get_expand_dim_for_pointwise_nodes(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode) -> Optional[tuple[int, SchedulerNode, sympy.Expr]]:
    """
        Fusing two small pointwise nodes significantly reduces kernel overhead
        and launch overhead. However, slightly different sizes would prevent fusion.
        Here, we decide if expanding sizes of one node is profitible by allowing
        fusion, and returns the dimension to expand, node with smaller sizes,
        and new size after expand.
        """
    if not isinstance(node1, SchedulerNode) or not isinstance(node2, SchedulerNode):
        return None
    if not (isinstance(node1.node, ir.ComputedBuffer) and isinstance(node2.node, ir.ComputedBuffer)):
        return None
    if node1.has_aliasing_or_mutation() or node2.has_aliasing_or_mutation():
        return None
    if config.cpu_backend == 'halide':
        return None
    (n1_sizes, n2_sizes) = (node1._sizes, node2._sizes)
    (n1_iter_sizes, n1_reduce_sizes) = n1_sizes
    (n2_iter_sizes, n2_reduce_sizes) = n2_sizes
    if node1.is_reduction() or node2.is_reduction() or n1_reduce_sizes != n2_reduce_sizes or (len(n1_iter_sizes) != len(n2_iter_sizes)):
        return None
    if len(node1.read_writes.writes) > 1 or len(node2.read_writes.writes) > 1:
        return None
    node1_write_memory = self.dep_size_hint(next(iter(node1.read_writes.writes)))
    node2_write_memory = self.dep_size_hint(next(iter(node1.read_writes.writes)))
    if max(node1_write_memory, node2_write_memory) > config.small_memory_access_threshold:
        return None

    def has_reusable_buffer(node: BaseSchedulerNode) -> bool:
        for read in node.read_writes.reads:
            input_buf: Optional[Union[SchedulerBuffer, SchedulerDonatedBuffer]]
            if read.name in self.name_to_donated_buffer:
                input_buf = self.name_to_donated_buffer[read.name]
            else:
                input_buf = self.name_to_buf.get(read.name)
            if input_buf and V.graph.wrapper_code.can_reuse(input_buf, node) and (not isinstance(input_buf.defining_op, NopKernelSchedulerNode)):
                return True
        return False
    if <MASK>:
        return None
    mismatch_dimensions = []
    for (idx, (n1_size, n2_size)) in enumerate(zip(n1_iter_sizes, n2_iter_sizes)):
        if n1_size != n2_size:
            mismatch_dimensions.append(idx)
    if len(mismatch_dimensions) != 1:
        return None
    mismatch_dim = mismatch_dimensions[0]
    (mismatch_size1, mismatch_size2) = (n1_iter_sizes[mismatch_dim], n2_iter_sizes[mismatch_dim])
    if V.graph.sizevars.statically_known_lt(mismatch_size1, mismatch_size2):
        return (mismatch_dim, node1, mismatch_size2)
    elif V.graph.sizevars.statically_known_lt(mismatch_size2, mismatch_size1):
        return (mismatch_dim, node2, mismatch_size1)
    else:
        return None

def skip_if_rocm_ver_lessthan_multiprocess(version=None):
    """Skips a test for ROCm based on ROCm ver - multiprocess UTs"""

    def decorator(func):
        reason = None
        if TEST_WITH_ROCM:
            rocm_version = str(torch.version.hip)
            rocm_version = rocm_version.split('-', maxsplit=1)[0]
            rocm_version_tuple = tuple((int(x) for x in rocm_version.split('.')))
            if <MASK>:
                reason = f'skip_if_rocm_ver_lessthan_multiprocess: ROCm {rocm_version_tuple} is available but {version} required'
        return unittest.skipIf(reason is not None, reason)(func)
    return decorator

def _load_post_and_files(self):
    """
        Populate self._post and self._files if the content-type is a form type
        """
    if self.method != 'POST':
        (self._post, self._files) = (QueryDict(encoding=self._encoding), MultiValueDict())
        return
    if self._read_started and (not hasattr(self, '_body')):
        self._mark_post_parse_error()
        return
    if self.content_type == 'multipart/form-data':
        if hasattr(self, '_body'):
            data = BytesIO(self._body)
        else:
            data = self
        try:
            (self._post, self._files) = self.parse_file_upload(self.META, data)
        except (MultiPartParserError, TooManyFilesSent):
            self._mark_post_parse_error()
            raise
    elif self.content_type == 'application/x-www-form-urlencoded':
        if <MASK>:
            raise BadRequest("HTTP requests with the 'application/x-www-form-urlencoded' content type must be UTF-8 encoded.")
        self._post = QueryDict(self.body, encoding='utf-8')
        self._files = MultiValueDict()
    else:
        (self._post, self._files) = (QueryDict(encoding=self._encoding), MultiValueDict())

def _get_serialized_attributes_internal(self, serialization_cache):
    default_signature = None
    if <MASK>:
        default_signature = save_impl.default_save_signature(self.obj)
    (objects, functions) = super(ModelSavedModelSaver, self)._get_serialized_attributes_internal(serialization_cache)
    functions['_default_save_signature'] = default_signature
    return (objects, functions)

def get_group(self, mesh_dim: Optional[Union[int, str]]=None) -> ProcessGroup:
    """
            Returns the single ProcessGroup specified by mesh_dim, or, if mesh_dim is not specified and the
            DeviceMesh is 1-dimensional, returns the only ProcessGroup in the mesh.

            Args:
                mesh_dim (str/int, optional): it can be the name of the mesh dimension or the index
                of the mesh dimension. Default is None.

            Returns:
                A :class:`ProcessGroup` object.
            """
    if <MASK>:
        raise RuntimeError('DeviceMesh process groups not initialized!')
    if len(self._layout) > 1 and mesh_dim is None:
        raise RuntimeError(f'Found the DeviceMesh have {len(self._layout)} dimensions', 'Optional kwarg `mesh_dim` needs to be specified when device_mesh.ndim > 1.', 'If you want to get the list of all the ProcessGroups in the DeviceMesh,please use `get_all_groups()` instead.')
    if len(self._layout) == 1 and mesh_dim is None:
        return not_none(_resolve_process_group(self._dim_group_names[0]))
    root_mesh = self._get_root_mesh()
    root_to_flatten_mapping = root_mesh._flatten_mapping
    if root_to_flatten_mapping and mesh_dim in root_to_flatten_mapping.keys():
        dim_group_name = root_to_flatten_mapping[mesh_dim]._dim_group_names[0]
        return not_none(_resolve_process_group(dim_group_name))
    else:
        mesh_dim = self._get_mesh_dim_by_name(mesh_dim) if isinstance(mesh_dim, str) else mesh_dim
        assert isinstance(mesh_dim, int)
        return not_none(_resolve_process_group(self._dim_group_names[mesh_dim]))

def _get_combinator_part_sql(self, compiler):
    features = self.connection.features
    selected = self.query.selected
    if selected is not None and compiler.query.selected is None:
        compiler.query = compiler.query.clone()
        compiler.query.set_values(selected)
    (part_sql, part_args) = compiler.as_sql(with_col_aliases=True)
    if compiler.query.combinator:
        if <MASK>:
            part_sql = 'SELECT * FROM ({})'.format(part_sql)
        elif self.query.subquery or not features.supports_slicing_ordering_in_compound:
            part_sql = '({})'.format(part_sql)
    elif self.query.subquery and features.supports_slicing_ordering_in_compound:
        part_sql = '({})'.format(part_sql)
    return (part_sql, part_args)

def __init__(self, value):
    """Creates a new Dimension with the given value."""
    if <MASK>:
        if value < 0:
            raise ValueError('Dimension %d must be >= 0' % value)
        self._value = value
    elif value is None:
        self._value = None
    elif isinstance(value, Dimension):
        self._value = value._value
    else:
        try:
            self._value = int(value.__index__())
        except AttributeError:
            raise TypeError("Dimension value must be integer or None or have an __index__ method, got value '{0!r}' with type '{1!r}'".format(value, type(value))) from None
        if self._value < 0:
            raise ValueError('Dimension %d must be >= 0' % self._value)

def _convert_fx_arg_to_onnx_arg(arg, node_name_to_values: dict[str, ir.Value | Sequence[ir.Value]], node_name_to_local_functions: dict[str, ir.Function]) -> Any:
    """Convert an FX argument to an ONNX compatible argument.

    This function
    - Converts a torch dtype to an integer
    - Converts a torch device/memory_format/layout to a string
    - Converts a torch.fx.Node to an ir.Value
    - Converts a sequence of torch.fx.Node to a sequence of ir.Value
    - Converts a get_attr node to an ir.Function
    """
    if arg is None:
        return None
    if <MASK>:
        if isinstance(arg, torch.fx.Node) and arg.target == operator.getitem:
            source = arg.all_input_nodes[0]
            source_outputs = node_name_to_values[source.name]
            if isinstance(source_outputs, Sequence):
                return _handle_getitem_node(arg, node_name_to_values)
            else:
                pass
        if isinstance(arg, torch.fx.Node) and arg.op == 'get_attr':
            return node_name_to_local_functions[arg.name]
        return node_name_to_values[arg.name]
    if isinstance(arg, (list, tuple)):
        return [_convert_fx_arg_to_onnx_arg(elem, node_name_to_values, node_name_to_local_functions) for elem in arg]
    if isinstance(arg, (torch.device, torch.memory_format, torch.layout)):
        return str(arg)
    if isinstance(arg, torch.dtype):
        return torch_dtype_to_onnx_dtype(arg)
    return arg

def _fill_in_zeros(grads, refs, strict, create_graph, stage):
    if stage not in ['back', 'back_trick', 'double_back', 'double_back_trick']:
        raise RuntimeError(f"Invalid stage argument '{stage}' to _fill_in_zeros")
    res: tuple[torch.Tensor, ...] = ()
    for (i, grads_i) in enumerate(grads):
        if grads_i is None:
            if strict:
                if stage == 'back':
                    raise RuntimeError(f'The output of the user-provided function is independent of input {i}. This is not allowed in strict mode.')
                elif stage == 'back_trick':
                    raise RuntimeError(f'The gradient with respect to the input is independent of entry {i} in the grad_outputs when using the double backward trick to compute forward mode gradients. This is not allowed in strict mode.')
                elif stage == 'double_back':
                    raise RuntimeError(f'The jacobian of the user-provided function is independent of input {i}. This is not allowed in strict mode.')
                else:
                    raise RuntimeError(f'The hessian of the user-provided function is independent of entry {i} in the grad_jacobian. This is not allowed in strict mode as it prevents from using the double backward trick to replace forward mode AD.')
            grads_i = torch.zeros_like(refs[i])
        elif strict and create_graph and (not grads_i.requires_grad):
            if <MASK>:
                raise RuntimeError(f'The jacobian of the user-provided function is independent of input {i}. This is not allowed in strict mode when create_graph=True.')
            else:
                raise RuntimeError(f'The hessian of the user-provided function is independent of input {i}. This is not allowed in strict mode when create_graph=True.')
        res += (grads_i,)
    return res

@test_util.run_v1_only('RefVariable is not supported in v2')
def testGatherNdRefVariable(self):
    with self.cached_session():
        v = ref_variable.RefVariable(constant_op.constant([[1, 2], [3, 4], [5, 6]]))
        self.evaluate(variables.global_variables_initializer())
        gather = array_ops.gather_nd(v, [[0, 1], [2, 0]])
        if <MASK>:
            self.assertEqual('GatherNd', gather.op.name)
        self.assertAllEqual([2, 5], gather)

def call_kernel(self, name: str, node: 'ROCmTemplateBuffer') -> None:
    """
        Generates code to call the kernel through V.graph.wrapper_code.
        used from within torch._inductor.wrapper.PythonWrapperCodegen

        name: Name of kernel function.
        node: The ROCmTemplateBuffer node which contains information about the kernel, it's fused epilogue nodes
        as well as all required inputs and outputs.
        """
    wrapper = V.graph.wrapper_code
    arg_types: list[Any]
    if <MASK>:
        assert isinstance(wrapper, CppWrapperCpu)
        wrapper.initialized_kernels[name] = self
        self.signature = self.signature.replace('KERNEL_NAME', name)
        (_, call_args, arg_types) = self.args.cpp_argdefs(DTYPE_TO_ROCM_TYPE)
    else:
        (_, call_args, _, arg_types) = self.args.python_argdefs()
    kernel_args = []
    for arg in call_args:
        if V.graph.is_unspec_arg(arg):
            arg = arg + '.item()'
        elif not V.graph.cpp_wrapper:
            arg = f'c_void_p({arg}.data_ptr())'
        kernel_args.append(arg)
    size_args = [f'{V.graph.sizevars.simplify(sarg)}' for sarg in node.template.size_args()]
    if V.graph.cpp_wrapper:
        kernel_args.extend(size_args)
    else:
        kernel_args.extend((f'c_int({sarg})' for sarg in size_args))
    if V.graph.cpp_wrapper:
        arg_types.extend(['int'] * len(node.template.size_args()))
    kernel_args.extend(self.runtime_arg_values)
    for arg in self.runtime_arg_info:
        arg_types.append(arg.ty)
    kernel_args.append('nullptr' if V.graph.cpp_wrapper else 'None')
    if V.graph.cpp_wrapper:
        arg_types.append('size_t*')
    if node.get_workspace_size() > 0:
        ws = WorkspaceArg(count=node.get_workspace_size(), device=V.graph.get_current_device_or_throw(), zero_mode=WorkspaceZeroMode.UNINITIALIZED, outer_name=WorkspaceArg.unique_name())
        wrapper.generate_workspace_allocation(ws)
        data_ptr = f'{ws.outer_name}.data_ptr()'
        kernel_args.append(data_ptr if V.graph.cpp_wrapper else f'c_void_p({data_ptr})')
    else:
        ws = None
        kernel_args.append('nullptr' if V.graph.cpp_wrapper else 'None')
    if V.graph.cpp_wrapper:
        arg_types.append('uint8_t*')
    wrapper.generate_kernel_call(name, kernel_args, triton=False, arg_types=arg_types)
    if ws:
        wrapper.generate_workspace_deallocation(ws)

def __init__(self, cache_path=None, *factors):
    self.cache_me = {}
    self.cache_private = set()
    self.cache_infile = False
    self._cache_path = None
    if self.conf_nocache:
        self.dist_log('cache is disabled by `Config`')
        return
    self._cache_hash = self.cache_hash(*factors, *self.conf_cache_factors)
    self._cache_path = cache_path
    if cache_path:
        if os.path.exists(cache_path):
            self.dist_log('load cache from file ->', cache_path)
            cache_mod = self.dist_load_module('cache', cache_path)
            if <MASK>:
                self.dist_log('unable to load the cache file as a module', stderr=True)
            elif not hasattr(cache_mod, 'hash') or not hasattr(cache_mod, 'data'):
                self.dist_log('invalid cache file', stderr=True)
            elif self._cache_hash == cache_mod.hash:
                self.dist_log('hit the file cache')
                for (attr, val) in cache_mod.data.items():
                    setattr(self, attr, val)
                self.cache_infile = True
            else:
                self.dist_log('miss the file cache')
    if not self.cache_infile:
        other_cache = _share_cache.get(self._cache_hash)
        if other_cache:
            self.dist_log('hit the memory cache')
            for (attr, val) in other_cache.__dict__.items():
                if attr in other_cache.cache_private or re.match(self._cache_ignore, attr):
                    continue
                setattr(self, attr, val)
    _share_cache[self._cache_hash] = self
    atexit.register(self.cache_flush)

def __init__(self, model_hash: Optional[Text]=None, model_path: Optional[Text]=None) -> None:
    del self
    if <MASK>:
        raise ValueError('Both model metadata(model_hash, model_path) should be given at the same time.')
    if model_hash:
        pass

def _test_input_iteration(self, input_type, api_type, iteration_type, dataset_or_input_fn, worker_device_pairs, expected_values, strategy, sess=None, num_replicas_in_sync=None, input_context=None):
    if iteration_type == 'for_loop' and (not context.executing_eagerly()):
        self.skipTest('unsupported test combination.')
    if api_type == 'wrap_into_iterator' and iteration_type == 'for_loop':
        self.skipTest('unsupported test combination.')
    if api_type == 'wrap_into_iterator' and input_type == 'input_fn':
        self.skipTest('unsupported test combination.')
    devices = nest.flatten([ds for (_, ds) in worker_device_pairs])
    input_workers = input_lib.InputWorkers(worker_device_pairs)
    if <MASK>:
        iterator = self._wrap_iterator(input_type, dataset_or_input_fn, input_workers, devices, num_replicas_in_sync, strategy, input_context=input_context)
    else:
        dataset = self._wrap_dataset(input_type, dataset_or_input_fn, input_workers, num_replicas_in_sync, strategy, input_context=input_context)
        if ops.executing_eagerly_outside_functions():
            iterator = iter(dataset)
        elif isinstance(dataset, input_lib_v1.DistributedDatasetV1):
            iterator = dataset.make_initializable_iterator()
        else:
            self.skipTest('unsupported test combination')
    if isinstance(iterator, composite_tensor.CompositeTensor):
        nest.assert_same_structure(iterator, iterator._type_spec, expand_composites=True)
    if iteration_type == 'get_next':
        evaluate = lambda x: sess.run(x) if sess else self.evaluate(x)
        if not ops.executing_eagerly_outside_functions():
            evaluate(control_flow_ops.group(iterator.initializer))

        def test_get_next(iterator):
            self._assert_iterator_values(iterator, expected_values, evaluate, devices)
            with self.assertRaises(errors.OutOfRangeError):
                self._assert_iterator_values(iterator, expected_values, evaluate, devices)
            if not ops.executing_eagerly_outside_functions():
                evaluate(control_flow_ops.group(iterator.initializer))
            elif api_type == 'wrap_into_iterator':
                self.skipTest('unsupported test combination')
            else:
                iterator = iter(dataset)
            self._assert_iterator_values(iterator, expected_values, evaluate, devices)

        def test_get_next_as_optional(iterator):
            self._assert_iterator_values(iterator, expected_values, evaluate, devices, enable_get_next_as_optional=True)
            next_element = iterator.get_next_as_optional()
            self.assertFalse(self.evaluate(next_element.has_value()))
            with self.assertRaises(errors.InvalidArgumentError):
                self._assert_iterator_values(iterator, [0], evaluate, devices, enable_get_next_as_optional=True)
        test_get_next(iterator)
        if not tf2.enabled():
            return
        elif api_type == 'wrap_into_iterator':
            return
        else:
            iterator = iter(dataset)
        test_get_next_as_optional(iterator)
    if iteration_type == 'for_loop' and context.executing_eagerly():
        self._assert_dataset_values_for_loop(dataset, expected_values, self.evaluate, devices)

def patch_track_step_called(opt: Optimizer):
    if <MASK>:
        return opt.step

    def wrap_step(step_fn):
        opt_ref = ref(self.optimizer)
        func = step_fn.__func__

        @wraps(func)
        def wrapper(*args, **kwargs):
            opt = opt_ref()
            opt._opt_called = True
            return func.__get__(opt, opt.__class__)(*args, **kwargs)
        wrapper._wrapped_by_lr_sched = True
        return wrapper
    opt.step = wrap_step(opt.step)

def _codegen_unbacked_symbol_defs_for_outputs(self, output_name: str, outputs: Any, unbacked_bindings: Optional[dict[sympy.Symbol, pytree.KeyPath]]) -> None:
    if <MASK>:
        return
    for (s, keypath) in unbacked_bindings.items():

        def go(expr: str, keypath: pytree.KeyPath):
            if keypath == ():
                return expr
            if len(keypath) >= 2 and isinstance(keypath[0], CallMethodKey) and isinstance(keypath[1], pytree.SequenceKey):
                return go(f'{expr}.{keypath[0].name}({keypath[1].idx})', keypath[2:])
            elif isinstance(keypath[0], CallMethodKey):
                return go(f'{expr}.{keypath[0].name}()', keypath[1:])
            elif isinstance(keypath[0], pytree.SequenceKey):
                return go(f'std::get<{keypath[0].idx}>({expr})', keypath[1:]) if V.graph.cpp_wrapper else go(f'{expr}[{keypath[0].idx}]', keypath[1:])
            elif isinstance(keypath[0], DivideByKey):
                return go(f'{expr}.__floordiv__({keypath[0].divisor})', keypath[1:])
            else:
                raise AssertionError(f'unrecognized keypath {keypath}')

        def go_outer():
            if V.graph.cpp_wrapper:
                if len(outputs) == 1:
                    out = outputs[0]
                    return go(outputs[0].get_name(), keypath[1:] if isinstance(out, ir.MultiOutput) and len(out.indices) != 0 else keypath)
                else:
                    assert isinstance(keypath[0], pytree.SequenceKey)
                    return go(outputs[keypath[0].idx].get_name(), keypath[1:])
            else:
                return go(output_name, keypath)
        self.writeline(f'{self.codegen_unbacked_symbol_decl(s)} = {go_outer()}{self.ending}')

def __init__(self):
    if hasattr(self, 'cc_is_cached'):
        return
    detect_arch = (('cc_on_x64', '.*(x|x86_|amd)64.*', ''), ('cc_on_x86', '.*(win32|x86|i386|i686).*', ''), ('cc_on_ppc64le', '.*(powerpc|ppc)64(el|le).*|.*powerpc.*', 'defined(__powerpc64__) && defined(__LITTLE_ENDIAN__)'), ('cc_on_ppc64', '.*(powerpc|ppc).*|.*powerpc.*', 'defined(__powerpc64__) && defined(__BIG_ENDIAN__)'), ('cc_on_aarch64', '.*(aarch64|arm64).*', ''), ('cc_on_armhf', '.*arm.*', 'defined(__ARM_ARCH_7__) || defined(__ARM_ARCH_7A__)'), ('cc_on_s390x', '.*s390x.*', ''), ('cc_on_noarch', '', ''))
    detect_compiler = (('cc_is_gcc', '.*(gcc|gnu\\-g).*', ''), ('cc_is_clang', '.*clang.*', ''), ('cc_is_iccw', '.*(intelw|intelemw|iccw).*', ''), ('cc_is_icc', '.*(intel|icc).*', ''), ('cc_is_msvc', '.*msvc.*', ''), ('cc_is_fcc', '.*fcc.*', ''), ('cc_is_nocc', '', ''))
    detect_args = (('cc_has_debug', '.*(O0|Od|ggdb|coverage|debug:full).*', ''), ('cc_has_native', '.*(-march=native|-xHost|/QxHost|-mcpu=a64fx).*', ''), ('cc_noopt', '.*DISABLE_OPT.*', ''))
    dist_info = self.dist_info()
    (platform, compiler_info, extra_args) = dist_info
    for section in (detect_arch, detect_compiler, detect_args):
        for (attr, rgex, cexpr) in section:
            setattr(self, attr, False)
    for (detect, searchin) in ((detect_arch, platform), (detect_compiler, compiler_info)):
        for (attr, rgex, cexpr) in detect:
            if rgex and (not re.match(rgex, searchin, re.IGNORECASE)):
                continue
            if cexpr and (not self.cc_test_cexpr(cexpr)):
                continue
            setattr(self, attr, True)
            break
    for (attr, rgex, cexpr) in detect_args:
        if rgex and (not re.match(rgex, extra_args, re.IGNORECASE)):
            continue
        if cexpr and (not self.cc_test_cexpr(cexpr)):
            continue
        setattr(self, attr, True)
    if self.cc_on_noarch:
        self.dist_log(f'unable to detect CPU architecture which lead to disable the optimization. check dist_info:<<\n{dist_info}\n>>', stderr=True)
        self.cc_noopt = True
    if self.conf_noopt:
        self.dist_log('Optimization is disabled by the Config', stderr=True)
        self.cc_noopt = True
    if self.cc_is_nocc:
        '\n            mingw can be treated as a gcc, and also xlc even if it based on clang,\n            but still has the same gcc optimization flags.\n            '
        self.dist_log(f"unable to detect compiler type which leads to treating it as GCC. this is a normal behavior if you're using gcc-like compiler such as MinGW or IBM/XLC.check dist_info:<<\n{dist_info}\n>>", stderr=True)
        self.cc_is_gcc = True
    self.cc_march = 'unknown'
    for arch in ('x86', 'x64', 'ppc64', 'ppc64le', 'armhf', 'aarch64', 's390x'):
        if <MASK>:
            self.cc_march = arch
            break
    self.cc_name = 'unknown'
    for name in ('gcc', 'clang', 'iccw', 'icc', 'msvc', 'fcc'):
        if getattr(self, 'cc_is_' + name):
            self.cc_name = name
            break
    self.cc_flags = {}
    compiler_flags = self.conf_cc_flags.get(self.cc_name)
    if compiler_flags is None:
        self.dist_fatal("undefined flag for compiler '%s', leave an empty dict instead" % self.cc_name)
    for (name, flags) in compiler_flags.items():
        self.cc_flags[name] = nflags = []
        if flags:
            assert isinstance(flags, str)
            flags = flags.split()
            for f in flags:
                if self.cc_test_flags([f]):
                    nflags.append(f)
    self.cc_is_cached = True

@staticmethod
def _get_version(cmd: str | None) -> Version | None:
    """Returns cmake version."""
    if cmd is None:
        return None
    try:
        cmake_capabilities = json.loads(check_output([cmd, '-E', 'capabilities'], stderr=DEVNULL, text=True))
    except (OSError, CalledProcessError, json.JSONDecodeError):
        cmake_capabilities = {}
    cmake_version = cmake_capabilities.get('version', {}).get('string')
    if <MASK>:
        return Version(cmake_version)
    raise RuntimeError(f'Failed to get CMake version from command: {cmd}')

def replica_fn():
    CollectiveReplicaLauncher._prefer_unique_instance_key = options.prefer_unique_instance_key
    (collective, devices, pid) = self.make_collective(options.num_processes, options.gpus_per_process)

    def batch_reduce_fn():
        batch_size = len(inputs[0])
        value_dst_pairs = []
        for i in range(batch_size):

            def value_fn(device_idx, idx=i):
                return inputs[pid * len(devices) + device_idx][idx]
            per_replica_value = make_per_replica_value(value_fn, devices)
            value_dst_pairs.append((per_replica_value, per_replica_value))
        reduced_values = collective.batch_reduce(options.reduce_op, value_dst_pairs, options.communication_options)
        if <MASK>:
            for v in reduced_values:
                self.assertIsInstance(v, value_lib.Mirrored)
        reduced_values = [self.as_list(v) for v in reduced_values]
        for v in reduced_values:
            self.assertAllEqual(devices, [t.device for t in v])
        return nest.map_structure(ops.convert_to_tensor, reduced_values)
    per_replica_expect = nest.map_structure(lambda x: [ops.convert_to_tensor(x)] * len(devices), expect)
    if 'eager' in options.mode:
        got = batch_reduce_fn()
        self.assertAllClose(got, per_replica_expect)
    if 'func_graph' in options.mode:
        got = def_function.function(batch_reduce_fn)()
        self.assertAllClose(got, per_replica_expect)

def _count_args(arg_defs):
    for arg in arg_defs:
        if <MASK>:
            return -1
    return len(arg_defs)

def read(self, nrows: int | None=None) -> DataFrame:
    if nrows is None and self.chunksize is not None:
        nrows = self.chunksize
    elif nrows is None:
        nrows = self.row_count
    if <MASK>:
        self.close()
        raise EmptyDataError('No columns to parse from file')
    if nrows > 0 and self._current_row_in_file_index >= self.row_count:
        return DataFrame()
    nrows = min(nrows, self.row_count - self._current_row_in_file_index)
    nd = self._column_types.count(b'd')
    ns = self._column_types.count(b's')
    self._string_chunk = np.empty((ns, nrows), dtype=object)
    self._byte_chunk = np.zeros((nd, 8 * nrows), dtype=np.uint8)
    self._current_row_in_chunk_index = 0
    p = Parser(self)
    p.read(nrows)
    rslt = self._chunk_to_dataframe()
    if self.index is not None:
        rslt = rslt.set_index(self.index)
    return rslt

def _node_def(from_node_def, export_scope, unbound_inputs, clear_devices=False):
    """Create a `NodeDef` proto with export_scope stripped.

  Args:
    from_node_def: A `node_def_pb2.NodeDef` protocol buffer.
    export_scope: A `string` representing the name scope to remove.
    unbound_inputs: An array of unbound input names if they exist.
    clear_devices: Boolean which controls whether to clear device information
      from node_def. Default false.

  Returns:
    A `node_def_pb2.NodeDef` protocol buffer.
  """
    node_def = copy.deepcopy(from_node_def)
    for (i, v) in enumerate(node_def.input):
        if export_scope and (not node_def.input[i].lstrip('^').startswith(export_scope)):
            node_def.input[i] = re.sub('([\\^]|^)(.*)', '\\1' + _UNBOUND_INPUT_PREFIX + '\\2', compat.as_str(v))
            unbound_inputs.append(node_def.input[i])
        else:
            node_def.input[i] = ops.strip_name_scope(v, export_scope)
    node_def.name = compat.as_bytes(ops.strip_name_scope(from_node_def.name, export_scope))
    for (k, v) in from_node_def.attr.items():
        if k == '_class':
            new_s = [compat.as_bytes(ops.strip_name_scope(s, export_scope)) for s in v.list.s if not export_scope or compat.as_str(s).split('@')[1].startswith(export_scope)]
            node_def.attr[k].CopyFrom(attr_value_pb2.AttrValue(list=attr_value_pb2.AttrValue.ListValue(s=new_s)))
        elif <MASK>:
            if not export_scope or compat.as_str(v.s).startswith(export_scope):
                new_s = compat.as_bytes(ops.strip_name_scope(v.s, export_scope))
            node_def.attr[k].CopyFrom(attr_value_pb2.AttrValue(s=new_s))
        else:
            node_def.attr[k].CopyFrom(v)
    if clear_devices:
        node_def.device = ''
    return node_def

def lookup(self, keys, name=None):
    """Looks up `keys` in the table, outputs the corresponding values.

    It assigns out-of-vocabulary keys to buckets based in their hashes.

    Args:
      keys: Keys to look up. May be either a `SparseTensor` or dense `Tensor`.
      name: Optional name for the op.

    Returns:
      A `SparseTensor` if keys are sparse, a `RaggedTensor` if keys are ragged,
      otherwise a dense `Tensor`.

    Raises:
      TypeError: when `keys` doesn't match the table key data type.
    """
    if keys.dtype.base_dtype != self._key_dtype:
        raise TypeError(f'Dtype of argument `keys` must be {self._key_dtype}, received: {keys.dtype}')
    values = keys
    if <MASK>:
        values = keys.values
    if self._table and self._table.key_dtype.base_dtype == dtypes.int64:
        values = math_ops.cast(values, dtypes.int64)
    if self._num_oov_buckets == 0:
        ids = self._table.lookup(values, name=name)
    else:
        with ops.name_scope(name, '%s_Lookup' % self.name):
            str_to_hash_bucket = self._get_string_to_hash_bucket_fn(self._hasher_spec)
            buckets = str_to_hash_bucket(_as_string(values), num_buckets=self._num_oov_buckets, name='hash_bucket')
            if self._table:
                ids = self._table.lookup(values)
                buckets = math_ops.add(buckets, self._table.size())
                is_id_non_default = math_ops.not_equal(ids, self._table.default_value)
                ids = array_ops.where_v2(is_id_non_default, ids, buckets)
            else:
                ids = buckets
    if isinstance(keys, sparse_tensor.SparseTensor):
        return sparse_tensor.SparseTensor(keys.indices, ids, keys.dense_shape)
    elif isinstance(keys, internal.RaggedTensor):
        return keys.with_values(ids)
    return ids

def _is_tma_compatible(sizes: Sequence[sympy.Expr], strides: Sequence[_IntLike], dtype: torch.dtype, allow_float32: bool) -> bool:
    rank = len(sizes)
    itemsize = dtype.itemsize
    if rank < 2 or rank > 5:
        return False
    if dtype not in (torch.float16, torch.bfloat16, torch.float8_e4m3fn) and (not allow_float32 or dtype != torch.float32):
        return False
    if <MASK>:
        sizes_i = V.graph.sizevars.guard_int_seq(sizes)
        strides_i = V.graph.sizevars.guard_int_seq(strides)
    else:
        sizes_i = [V.graph.sizevars.symbolic_hint(s) for s in sizes]
        strides_i = [V.graph.sizevars.symbolic_hint(st) for st in strides]
    if any((not V.graph.sizevars.statically_known_geq(s, 2) for s in sizes_i)):
        return False
    inner = [i for (i, st) in enumerate(strides_i) if V.graph.sizevars.statically_known_equals(st, 1)]
    if len(inner) != 1:
        return False
    inner_idx = inner[0]
    for (i, st) in enumerate(strides_i):
        if i == inner_idx:
            continue
        if not _aligned(st * itemsize):
            return False
    inner_dim = sizes_i[inner_idx]
    if not _aligned(inner_dim * itemsize):
        return False
    if dtype == torch.float8_e4m3fn and (not V.graph.sizevars.statically_known_geq(inner_dim, 32)):
        return False
    return True

def _parse_kineto_results(self, result: _ProfilerResult):
    trace_start_ns = result.trace_start_ns()
    mem_records = [[evt, False] for evt in result.events() if evt.name() == MEMORY_EVENT_NAME]
    oom_records = [evt for evt in result.events() if evt.name() == OUT_OF_MEMORY_EVENT_NAME]
    mem_records_acc = MemRecordsAcc(mem_records)

    def _cpu_memory_usage(mem_record):
        return mem_record.nbytes() if mem_record.device_type() in [DeviceType.CPU, DeviceType.MKLDNN, DeviceType.IDEEP] else 0

    def _device_memory_usage(mem_record):
        return mem_record.nbytes() if mem_record.device_type() in [DeviceType.CUDA, DeviceType.PrivateUse1, DeviceType.HIP, DeviceType.XPU] else 0
    all_function_events = []
    frontend_function_events = []
    device_corr_map: dict[int, list[FunctionEvent]] = {}
    max_evt_id = 0
    for kineto_event in result.events():
        if _filter_name(kineto_event.name()) or getattr(kineto_event, 'is_hidden_event', lambda : False)():
            continue
        rel_start_ns = kineto_event.start_ns() - trace_start_ns
        rel_end_ns = kineto_event.end_ns() - trace_start_ns
        abs_end_ns = kineto_event.end_ns()
        cpu_memory_usage = 0
        device_memory_usage = 0
        if kineto_event.device_type() == DeviceType.CPU:
            for mem_record in mem_records_acc.in_interval(kineto_event.start_ns() / 1000, abs_end_ns / 1000):
                cpu_memory_usage += _cpu_memory_usage(mem_record[0])
                device_memory_usage += _device_memory_usage(mem_record[0])
                mem_record[1] = True
        is_async = kineto_event.is_async() or kineto_event.start_thread_id() != kineto_event.end_thread_id()
        fe = FunctionEvent(id=kineto_event.correlation_id(), name=_rewrite_name(name=kineto_event.name(), with_wildcard=True), overload_name=kineto_event.overload_name(), trace_name=_rewrite_name(name=kineto_event.name(), with_wildcard=False), thread=kineto_event.start_thread_id(), start_us=rel_start_ns / 1000, end_us=rel_end_ns / 1000, fwd_thread=kineto_event.fwd_thread_id(), input_shapes=kineto_event.shapes(), concrete_inputs=kineto_event.concrete_inputs(), kwinputs=kineto_event.kwinputs(), stack=[entry for entry in kineto_event.stack() if _filter_stack_entry(entry)], scope=kineto_event.scope(), use_device=self.use_device, cpu_memory_usage=cpu_memory_usage, device_memory_usage=device_memory_usage, is_async=is_async, sequence_nr=kineto_event.sequence_nr(), device_type=kineto_event.device_type(), device_index=kineto_event.device_index(), device_resource_id=kineto_event.device_resource_id(), flops=kineto_event.flops(), is_user_annotation=kineto_event.is_user_annotation(), metadata_json=kineto_event.metadata_json())
        max_evt_id = max(max_evt_id, fe.id)
        if fe.device_type == DeviceType.CPU and (not fe.is_async):
            if self.use_device == _get_privateuse1_backend_name():
                privateuse1_time = kineto_event.privateuse1_elapsed_us()
                if privateuse1_time > 0:
                    fe.append_kernel(fe.name, fe.device_index, privateuse1_time)
                    fe.is_legacy = True
            elif self.use_device == 'cuda':
                cuda_time = kineto_event.cuda_elapsed_us()
                if cuda_time > 0:
                    fe.append_kernel(fe.name, fe.device_index, cuda_time)
                    fe.is_legacy = True
        all_function_events.append(fe)
        corr_id = kineto_event.linked_correlation_id()
        if corr_id > 0:
            if corr_id not in device_corr_map:
                device_corr_map[corr_id] = []
            device_corr_map[corr_id].append(fe)
        elif corr_id == 0:
            frontend_function_events.append(fe)
        else:
            raise RuntimeError(f'Got negative correlation id {corr_id} in profiler post processing')
    for fe in frontend_function_events:
        if <MASK>:
            for f_evt in device_corr_map[fe.id]:
                if f_evt.device_type == DeviceType.CUDA or f_evt.device_type == DeviceType.PrivateUse1:
                    fe.append_kernel(f_evt.name, f_evt.device_index, f_evt.time_range.end - f_evt.time_range.start)
                elif f_evt.device_type == DeviceType.CPU:
                    f_evt.thread = fe.thread

    def createFunctionEventForMemoryEvents(evt):
        rel_start_ns = evt.start_ns() - trace_start_ns
        fe = FunctionEvent(id=max_evt_id, name=evt.name(), overload_name='', trace_name=None, thread=evt.start_thread_id(), start_us=rel_start_ns / 1000, end_us=rel_start_ns / 1000, fwd_thread=evt.start_thread_id(), input_shapes=[], stack=[], scope=0, use_device=self.use_device, cpu_memory_usage=_cpu_memory_usage(evt), device_memory_usage=_device_memory_usage(evt), is_async=False, sequence_nr=-1, device_type=DeviceType.CPU, device_index=0)
        return fe
    for mem_record in mem_records:
        if not mem_record[1]:
            max_evt_id += 1
            fe = createFunctionEventForMemoryEvents(mem_record[0])
            all_function_events.append(fe)
    for oom_record in oom_records:
        max_evt_id += 1
        fe = createFunctionEventForMemoryEvents(oom_record)
        all_function_events.append(fe)
    all_function_events.sort(key=lambda evt: [evt.time_range.start, -evt.time_range.end])
    return all_function_events

def _commastring(astr):
    startindex = 0
    result = []
    islist = False
    while startindex < len(astr):
        mo = format_re.match(astr, pos=startindex)
        try:
            (order1, repeats, order2, dtype) = mo.groups()
        except (TypeError, AttributeError):
            raise ValueError(f'format number {len(result) + 1} of "{astr}" is not recognized') from None
        startindex = mo.end()
        if startindex < len(astr):
            if space_re.match(astr, pos=startindex):
                startindex = len(astr)
            else:
                mo = sep_re.match(astr, pos=startindex)
                if <MASK>:
                    raise ValueError('format number %d of "%s" is not recognized' % (len(result) + 1, astr))
                startindex = mo.end()
                islist = True
        if order2 == '':
            order = order1
        elif order1 == '':
            order = order2
        else:
            order1 = _convorder.get(order1, order1)
            order2 = _convorder.get(order2, order2)
            if order1 != order2:
                raise ValueError(f'inconsistent byte-order specification {order1} and {order2}')
            order = order1
        if order in ('|', '=', _nbo):
            order = ''
        dtype = order + dtype
        if repeats == '':
            newitem = dtype
        else:
            if repeats[0] == '(' and repeats[-1] == ')' and (repeats[1:-1].strip() != '') and (',' not in repeats):
                warnings.warn('Passing in a parenthesized single number for repeats is deprecated; pass either a single number or indicate a tuple with a comma, like "(2,)".', DeprecationWarning, stacklevel=2)
            newitem = (dtype, ast.literal_eval(repeats))
        result.append(newitem)
    return result if islist else result[0]

def _unflatten_optim_state_dict(optim: torch.optim.Optimizer, state_dict: dict[str, ValueType], info: _StateDictInfo) -> OptimizerStateType:
    """
    This API unflattens the state_dict generated by _flatten_optim_state_dict().
    See the docstring of _flatten_optim_state_dict() for more detail.
    """
    state: DictValueType = {}
    pg_state: ListDictValueType = []
    return_osd: OptimizerStateType = {_STATE: state, _PG: pg_state}
    for param_group in optim.param_groups:
        pg_state.append({_PARAMS: []})
        for param in param_group[_PARAMS]:
            for fqn in info.fqn_param_mapping[param]:
                if fqn in info.shared_params_mapping:
                    in_params = False
                    for k in param_group.keys():
                        if k == _PARAMS:
                            continue
                        flatten_key = f'{_PG}.{fqn}.{k}'
                        if flatten_key in state_dict:
                            in_params = True
                        break
                else:
                    in_params = True
                if <MASK>:
                    continue
                params = pg_state[-1][_PARAMS]
                if not isinstance(params, list):
                    raise AssertionError(f'Expected list, got {type(params)}')
                params.append(fqn)
                if not param.requires_grad:
                    continue
                state[fqn] = {}
                for state_name in optim.state[param].keys():
                    cast(DictValueType, state[fqn])[state_name] = state_dict[f'{_STATE}.{fqn}.{state_name}']
        first_param_fqn = cast(list[str], pg_state[-1][_PARAMS])[0]
        for k in param_group.keys():
            if k == _PARAMS:
                continue
            value = state_dict[f'{_PG}.{first_param_fqn}.{k}']
            if k not in pg_state[-1]:
                pg_state[-1][k] = value
            elif pg_state[-1][k] != value:
                raise RuntimeError(f'All the parameters in the same parameter group should have the same saved param_group value. But {first_param_fqn}.{k} is {value} while other(s) is {pg_state[-1][k]}.')
    return return_osd

def match_dtype_and_type(self, actual, expected_dtype, res_type, msg=None):
    if <MASK>:
        msg = 'Dtype and type match failed for: {}. Expected dtype: {} Actual dtype: {}. Expected type: {} Actual type: {}.'.format(msg, expected_dtype, actual.dtype, res_type, type(actual))
    self.assertIsInstance(actual, res_type, msg=msg)
    self.assertEqual(actual.dtype, expected_dtype, msg=msg)

