def equality_inference_rule(n: Node, symbols, constraints, counter):
    """
    We generate the constraint: input = output
    """
    (output, counter) = gen_tvar(counter)
    symbols[n] = output
    if isinstance(n.args[0], Node):
        input = symbols[n.args[0]]
        if <MASK>:
            return ([BinConstraintT(input, output, op_eq)], counter)
        else:
            for arg in n.args:
                assert isinstance(symbols[arg], DVar)
        my_size = [symbols[arg] for arg in n.args]
        return ([BinConstraintT(output, TensorType(my_size), op_eq)], counter)
    elif isinstance(n.args[0], tuple):
        assert len(n.args[0]) <= 4
        my_size = [symbols[arg] for arg in n.args[0]]
        return ([BinConstraintT(output, TensorType(my_size), op_eq)], counter)
    else:
        raise NotImplementedError('Method not yet implemented')

def optimize_inner(self, operations, app_label):
    """Inner optimization loop."""
    new_operations = []
    for (i, operation) in enumerate(operations):
        right = True
        for (j, other) in enumerate(operations[i + 1:]):
            result = operation.reduce(other, app_label)
            if <MASK>:
                in_between = operations[i + 1:i + j + 1]
                if right:
                    new_operations.extend(in_between)
                    new_operations.extend(result)
                elif all((op.reduce(other, app_label) is True for op in in_between)):
                    new_operations.extend(result)
                    new_operations.extend(in_between)
                else:
                    new_operations.append(operation)
                    break
                new_operations.extend(operations[i + j + 2:])
                return new_operations
            elif not result:
                right = False
        else:
            new_operations.append(operation)
    return new_operations

def _make_decorator(*m_args, **m_kwargs):

    def _decorator(view_func):
        middleware = middleware_class(view_func, *m_args, **m_kwargs)

        def _pre_process_request(request, *args, **kwargs):
            if hasattr(middleware, 'process_request'):
                result = middleware.process_request(request)
                if <MASK>:
                    return result
            if hasattr(middleware, 'process_view'):
                result = middleware.process_view(request, view_func, args, kwargs)
                if result is not None:
                    return result
            return None

        def _process_exception(request, exception):
            if hasattr(middleware, 'process_exception'):
                result = middleware.process_exception(request, exception)
                if result is not None:
                    return result
            raise

        def _post_process_request(request, response):
            if hasattr(response, 'render') and callable(response.render):
                if hasattr(middleware, 'process_template_response'):
                    response = middleware.process_template_response(request, response)
                if hasattr(middleware, 'process_response'):

                    def callback(response):
                        return middleware.process_response(request, response)
                    response.add_post_render_callback(callback)
            elif hasattr(middleware, 'process_response'):
                return middleware.process_response(request, response)
            return response
        if iscoroutinefunction(view_func):

            async def _view_wrapper(request, *args, **kwargs):
                result = _pre_process_request(request, *args, **kwargs)
                if result is not None:
                    return result
                try:
                    response = await view_func(request, *args, **kwargs)
                except Exception as e:
                    result = _process_exception(request, e)
                    if result is not None:
                        return result
                return _post_process_request(request, response)
        else:

            def _view_wrapper(request, *args, **kwargs):
                result = _pre_process_request(request, *args, **kwargs)
                if result is not None:
                    return result
                try:
                    response = view_func(request, *args, **kwargs)
                except Exception as e:
                    result = _process_exception(request, e)
                    if result is not None:
                        return result
                return _post_process_request(request, response)
        return wraps(view_func)(_view_wrapper)
    return _decorator

def _local_map_wrapped(func: Callable, out_placements: OutputPlacements, in_placements: InputPlacements, in_grad_placements: InputPlacements, device_mesh: Optional[DeviceMesh], redistribute_inputs: bool, *args, **kwargs):
    (flat_args, args_spec) = pytree.tree_flatten(args)
    if in_placements is not None:
        assert len(in_placements) == len(flat_args), f'in_placements length {len(in_placements)} does not match the number of input args {len(flat_args)}!'
    flat_local_args = []
    seen_dtensor_arg = False
    for (idx, arg) in enumerate(flat_args):
        if <MASK>:
            if device_mesh is None:
                device_mesh = arg.device_mesh
            seen_dtensor_arg = True
            if in_placements is not None:
                spec = in_placements[idx]
                assert spec is not None, f'DTensor input {arg} expects placements but received {spec}!'
                if not isinstance(spec, tuple):
                    spec = tuple(spec)
                if arg.placements != spec:
                    if redistribute_inputs:
                        arg = arg.redistribute(placements=spec)
                    else:
                        raise ValueError(f'arg {arg} in local_map has a mismatched placements: arg placements is {arg.placements} but the input placements is {spec}! If redistribute_inputs is wanted, set redistribute_inputs=True to local_map.')
            if in_grad_placements is not None:
                spec = in_grad_placements[idx]
                assert spec is not None, f'DTensor input {arg} expects in grad placements but received {spec}!'
                if not isinstance(spec, tuple):
                    spec = tuple(spec)
                local_arg = arg.to_local(grad_placements=spec)
            else:
                local_arg = arg.to_local()
            if isinstance(local_arg, AsyncCollectiveTensor):
                local_arg = local_arg.wait()
            flat_local_args.append(local_arg)
        else:
            if in_placements is not None and (not isinstance(arg, torch.Tensor)):
                spec = in_placements[idx]
                assert spec is None, f'Non-Tensor input {arg} expects None placements but received {spec}!'
            flat_local_args.append(arg)
    local_args = pytree.tree_unflatten(flat_local_args, args_spec)
    out = func(*local_args, **kwargs)
    if seen_dtensor_arg:
        (flat_out, out_spec) = pytree.tree_flatten(out)
        flat_dist_out = []
        out_placements_tuple = out_placements if isinstance(out_placements, tuple) else (out_placements,)
        assert len(flat_out) == len(out_placements_tuple), f'local_map requires one PlacementType be provided for each output value, received {len(out_placements_tuple)} out_placements but {len(flat_out)} is expected!'
        for (out, spec) in zip(flat_out, out_placements_tuple):
            if isinstance(out, torch.Tensor):
                assert not isinstance(out, DTensor), f'torch.Tensor output expected but received {type(out)}: {out}'
                flat_dist_out.append(DTensor.from_local(out, device_mesh, spec, run_check=False))
            else:
                assert spec is None, f'Non-tensor output {out} expects None placements but received {spec}!'
                flat_dist_out.append(out)
        return pytree.tree_unflatten(flat_dist_out, out_spec)
    else:
        return out

def assert_array_compare(comparison, x, y, err_msg='', verbose=True, header='', precision=6, equal_nan=True, equal_inf=True, *, strict=False):
    __tracebackhide__ = True
    from torch._numpy import all, array, asarray, bool_, inf, isnan, max
    x = asarray(x)
    y = asarray(y)

    def array2string(a):
        return str(a)
    (ox, oy) = (x, y)

    def func_assert_same_pos(x, y, func=isnan, hasval='nan'):
        """Handling nan/inf.

        Combine results of running func on x and y, checking that they are True
        at the same locations.

        """
        __tracebackhide__ = True
        x_id = func(x)
        y_id = func(y)
        if (x_id == y_id).all().item() is not True:
            msg = build_err_msg([x, y], err_msg + f'\nx and y {hasval} location mismatch:', verbose=verbose, header=header, names=('x', 'y'), precision=precision)
            raise AssertionError(msg)
        if isinstance(x_id, bool) or x_id.ndim == 0:
            return bool_(x_id)
        elif isinstance(y_id, bool) or y_id.ndim == 0:
            return bool_(y_id)
        else:
            return y_id
    try:
        if strict:
            cond = x.shape == y.shape and x.dtype == y.dtype
        else:
            cond = (x.shape == () or y.shape == ()) or x.shape == y.shape
        if not cond:
            if x.shape != y.shape:
                reason = f'\n(shapes {x.shape}, {y.shape} mismatch)'
            else:
                reason = f'\n(dtypes {x.dtype}, {y.dtype} mismatch)'
            msg = build_err_msg([x, y], err_msg + reason, verbose=verbose, header=header, names=('x', 'y'), precision=precision)
            raise AssertionError(msg)
        flagged = bool_(False)
        if <MASK>:
            flagged = func_assert_same_pos(x, y, func=isnan, hasval='nan')
        if equal_inf:
            flagged |= func_assert_same_pos(x, y, func=lambda xy: xy == +inf, hasval='+inf')
            flagged |= func_assert_same_pos(x, y, func=lambda xy: xy == -inf, hasval='-inf')
        if flagged.ndim > 0:
            (x, y) = (x[~flagged], y[~flagged])
            if x.size == 0:
                return
        elif flagged:
            return
        val = comparison(x, y)
        if isinstance(val, bool):
            cond = val
            reduced = array([val])
        else:
            reduced = val.ravel()
            cond = reduced.all()
        if not cond:
            n_mismatch = reduced.size - int(reduced.sum(dtype=intp))
            n_elements = flagged.size if flagged.ndim != 0 else reduced.size
            percent_mismatch = 100 * n_mismatch / n_elements
            remarks = [f'Mismatched elements: {n_mismatch} / {n_elements} ({percent_mismatch:.3g}%)']
            with contextlib.suppress(TypeError, RuntimeError):
                error = abs(x - y)
                if np.issubdtype(x.dtype, np.unsignedinteger):
                    error2 = abs(y - x)
                    np.minimum(error, error2, out=error)
                max_abs_error = max(error)
                remarks.append('Max absolute difference: ' + array2string(max_abs_error.item()))
                nonzero = bool_(y != 0)
                if all(~nonzero):
                    max_rel_error = array(inf)
                else:
                    max_rel_error = max(error[nonzero] / abs(y[nonzero]))
                remarks.append('Max relative difference: ' + array2string(max_rel_error.item()))
            err_msg += '\n' + '\n'.join(remarks)
            msg = build_err_msg([ox, oy], err_msg, verbose=verbose, header=header, names=('x', 'y'), precision=precision)
            raise AssertionError(msg)
    except ValueError:
        import traceback
        efmt = traceback.format_exc()
        header = f'error during assertion:\n\n{efmt}\n\n{header}'
        msg = build_err_msg([x, y], err_msg, verbose=verbose, header=header, names=('x', 'y'), precision=precision)
        raise ValueError(msg)

def _generate_inputs_for_submodules(model: torch.nn.Module, target_submodules: Iterable[str], args: tuple[Any, ...], kwargs: Optional[dict[str, Any]]=None) -> dict[str, tuple[Any, Any]]:
    """
    Generate inputs for targeting submdoules in the given model. Note that if two submodules refer to the same obj, this
    function doesn't work.

    Args:
        model: root model.
        inputs: inputs to the root model.
        target_submodules: submodules that we want to generate inputs for.

    Returns:
        A dict that maps from submodule name to its inputs.
    """
    kwargs = kwargs or {}
    handles = []
    results = {}
    submodule_to_names = {mod: name for (name, mod) in model.named_modules()}

    def pre_forward(module, module_args, module_kwargs):
        results[submodule_to_names[module]] = (module_args, module_kwargs)
    try:
        for (name, mod) in model.named_modules():
            if <MASK>:
                handles.append(mod.register_forward_pre_hook(pre_forward, with_kwargs=True))
        model(*args, **kwargs)
    except Exception as e:
        warnings.warn(f'Failed to generate submodule inputs because of the following error:\n{e}')
    finally:
        for h in handles:
            h.remove()
    return results

def have_compatible_glibc(major, minimum_minor):
    import ctypes
    process_namespace = ctypes.CDLL(None)
    try:
        gnu_get_libc_version = process_namespace.gnu_get_libc_version
    except AttributeError:
        return False
    gnu_get_libc_version.restype = ctypes.c_char_p
    version_str = gnu_get_libc_version()
    if <MASK>:
        version_str = version_str.decode('ascii')
    version = [int(piece) for piece in version_str.split('.')]
    assert len(version) == 2
    if major != version[0]:
        return False
    if minimum_minor > version[1]:
        return False
    return True

@register_lowering_pattern(pattern, extra_check=_is_single_computation_op(computation_op, lowp_dtype))
def fn(match, *args, **kwargs):
    min_value = kwargs.get('min_value')
    max_value = kwargs.get('max_value')
    if isinstance(min_value, ir.TensorBox) or isinstance(max_value, ir.TensorBox):
        matched = False
    else:
        assert max_value is not None
        matched = min_value <= max_value
    if <MASK>:
        dtype1 = kwargs.get('to_float')
        dtype2 = kwargs.get('to_bf16') if lowp_dtype == torch.bfloat16 else kwargs.get('to_fp16')
        matched = matched and dtype1 == torch.float and (dtype2 == lowp_dtype)
    computation_args = list(args)
    counters['inductor']['mkldnn_unary_fusion_matcher_count'] += 1
    counters['inductor']['mkldnn_unary_fusion_matcher_nodes'] += len(match.nodes)
    if matched:
        computation_args = computation_args[:-3] + ['hardtanh', [min_value, max_value], '']
        return L[computation_op](*computation_args)
    else:
        out = L[computation_op](*computation_args)
        if lowp_dtype:
            out = L[prims.convert_element_type.default](out, dtype=torch.float)
        out = L[aten.clamp_max](L[aten.clamp_min](out, min_value), max_value)
        if lowp_dtype:
            out = L[prims.convert_element_type.default](out, dtype=dtype2)
        return out

@register_lowering(torch.ops.mkldnn._linear_pointwise)
def linear_unary(x: TensorBox, w: TensorBox, b: TensorBox, attr, scalars, algorithm, layout=None):
    x_size = x.get_size()
    if <MASK>:
        x = view(x, [-1, x_size[-1]])
    if b is not None:
        b = ir.ExternKernel.realize_input(b)
    choices: list[ChoiceCaller] = []
    if config.max_autotune or config.max_autotune_gemm:
        transposed_w = permute(w, [1, 0])
        (*_, layout, x, transposed_w) = mm_args(x, transposed_w, layout=layout)
        if use_cpp_gemm_template(layout, x, transposed_w):

            def epilogue_creator(buf):
                return create_epilogue_with_attr(buf, attr, scalars=scalars, algorithm=algorithm)
            kwargs = {'has_bias': b is not None, 'trans_w': True, 'epilogue_creator': None if attr == 'none' else epilogue_creator}
            if b is not None:
                kwargs['input_indices'] = [2, 0, 1]
            CppGemmTemplate.add_choices(choices, layout, [x, w] if b is None else [x, w, b], **kwargs)
    if len(choices) == 0 or use_aten_gemm_kernels():
        kwargs = dict(attr=attr, scalars=scalars, algorithm=algorithm)
        if b is None:
            kwargs['B'] = None
        choices.append(aten_mkldnn_linear_unary.bind([x, w] if b is None else [x, w, b], layout, **kwargs))
    assert w.get_name() in V.graph.constants
    input_gen_fns = {1: lambda x: V.graph.constants[x.get_name()]}
    result = autotune_select_algorithm('linear_unary', choices, [x, w] if b is None else [x, w, b], layout, input_gen_fns=input_gen_fns)
    if len(x_size) > 2:
        result = view(result, (*x_size[:-1], result.get_size()[-1]))
    return result

def bsr_dense_addmm_meta(M, K, N, Ms, Ks, beta, alpha, SPLIT_N=None, GROUP_SIZE_ROW=None, num_warps=None, num_stages=None, sparsity=None, dtype=None, out_dtype=None, _version=0, **extra):
    if dtype is None:
        dtype = torch.float16
    if out_dtype is None:
        out_dtype = dtype
    if sparsity is None:
        sparsity = 0.5
    if {SPLIT_N, num_warps, num_stages, GROUP_SIZE_ROW} == {None}:
        device_name = torch.cuda.get_device_name()
        key = (M, K, N, Ms, Ks, beta == 0, beta == 1, alpha == 1)
        if dtype is out_dtype:
            version_dtype = dtype
        else:
            version_dtype = (dtype, out_dtype)
        meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, version_dtype, sparsity))
        if meta is None and sparsity != 0.5:
            meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, version_dtype, 0.5))
        if <MASK>:
            meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, dtype, 0.5))
        if meta is None:
            matching_meta = get_meta('bsr_dense_addmm', (*key[:2], '*', *key[3:]), device_name, version=(_version, version_dtype, 0.5))
            if matching_meta is None and dtype is not out_dtype:
                matching_meta = get_meta('bsr_dense_addmm', (*key[:2], '*', *key[3:]), device_name, version=(_version, dtype, 0.5))
            for mkey in sorted(matching_meta or {}):
                meta_ = matching_meta[mkey]
                n = mkey[2]
                split_n = meta_['SPLIT_N']
                c = n // split_n
                if N % c == 0 and n <= N:
                    meta = dict(meta_)
                    meta['SPLIT_N'] = N // c
        if meta is not None:
            meta.update(**extra)
            return meta
        else:
            warn_once(f'bsr_dense_addmm uses non-optimal triton kernel parameters for M={M!r} K={K!r} N={N!r} Ms={Ms!r}, Ks={Ks!r} beta={beta!r} alpha={alpha!r} dtype={dtype!r} out_dtype={out_dtype!r}')
    SPLIT_N = SPLIT_N or max(N // Ms, 1)
    GROUP_SIZE_ROW = GROUP_SIZE_ROW or 4
    num_stages = num_stages or 1
    num_warps = num_warps or 4
    return dict(SPLIT_N=SPLIT_N, GROUP_SIZE_ROW=GROUP_SIZE_ROW, num_stages=num_stages, num_warps=num_warps, **extra)

def _maybe_opt_step(self, optimizer: torch.optim.Optimizer, optimizer_state: dict[str, Any], *args: Any, **kwargs: Any) -> Optional[float]:
