def call_iand(self, tx: 'InstructionTranslator', a, b):
    if isinstance(a, ConstantVariable) and isinstance(b, ConstantVariable):
        return None
    if <MASK>:
        return SymNodeVariable.create(tx, tx.output.create_proxy('call_function', operator.iand, *proxy_args_kwargs([a, b], {})), sym_num=None)
    if isinstance(a, (DictKeysVariable, SetVariable, UserDefinedObjectVariable)):
        return a.call_method(tx, '__iand__', [b], {})

@functools.cache
def make_looper(func, result_dtype, is_grouped_kernel, nopython, nogil, parallel):
    if TYPE_CHECKING:
        import numba
    else:
        numba = import_optional_dependency('numba')
    if <MASK>:

        @numba.jit(nopython=nopython, nogil=nogil, parallel=parallel)
        def column_looper(values: np.ndarray, labels: np.ndarray, ngroups: int, min_periods: int, *args):
            result = np.empty((values.shape[0], ngroups), dtype=result_dtype)
            na_positions = {}
            for i in numba.prange(values.shape[0]):
                (output, na_pos) = func(values[i], result_dtype, labels, ngroups, min_periods, *args)
                result[i] = output
                if len(na_pos) > 0:
                    na_positions[i] = np.array(na_pos)
            return (result, na_positions)
    else:

        @numba.jit(nopython=nopython, nogil=nogil, parallel=parallel)
        def column_looper(values: np.ndarray, start: np.ndarray, end: np.ndarray, min_periods: int, *args):
            result = np.empty((values.shape[0], len(start)), dtype=result_dtype)
            na_positions = {}
            for i in numba.prange(values.shape[0]):
                (output, na_pos) = func(values[i], result_dtype, start, end, min_periods, *args)
                result[i] = output
                if len(na_pos) > 0:
                    na_positions[i] = np.array(na_pos)
            return (result, na_positions)
    return column_looper

def _apply_to_modules(root_module: torch.nn.Module, module_fn: Callable, return_fn: Callable, filter_fqns: Optional[list[str]]=None, *args, **kwargs):
    """
    Performs a pre-order traversal of the modules in the hierarchy rooted at
    ``root_module``, applying ``module_fn`` at each module and finally
    returning a value using ``return_fn``. The traversal constructs the full
    module prefix name (e.g. "module.submodule." just like in model state dict)
    and makes that available to ``module_fn``.

    ``filter_fqns`` is used because some module may have its own prefix similar
    to ``FullyShardedDataParallel`` and the ``named_parameters()`` is overwritten
    to remove the prefix.
    """

    def f(module: torch.nn.Module, prefix: str, tree_level: int, *args, **kwargs):
        module_fn(module, prefix, tree_level, *args, **kwargs)
        for (submodule_name, submodule) in module.named_children():
            if submodule is None:
                continue
            new_prefix = prefix + submodule_name + '.'
            new_tree_level = tree_level + 1
            if <MASK>:
                for fqn in filter_fqns:
                    if fqn.startswith(new_prefix):
                        break
                else:
                    if submodule_name == '_fsdp_wrapped_module' or submodule_name == '_dmp_wrapped_module':
                        new_prefix = prefix
                    elif submodule_name == 'module':
                        new_prefix = prefix
            f(submodule, new_prefix, new_tree_level, *args, **kwargs)
    f(root_module, '', 0, *args, **kwargs)
    return return_fn(*args, **kwargs)

def huber_loss(input: Tensor, target: Tensor, reduction: str='mean', delta: float=1.0, weight: Optional[Tensor]=None) -> Tensor:
    """Compute the Huber loss, with optional weighting.

    Function uses a squared term if the absolute
    element-wise error falls below delta and a delta-scaled L1 term otherwise.

    When delta equals 1, this loss is equivalent to SmoothL1Loss.
    In general, Huber loss differs from SmoothL1Loss by a factor of delta (AKA beta in Smooth L1).

    See :class:`~torch.nn.HuberLoss` for details.

    Args:
        input (Tensor): Predicted values.
        target (Tensor): Ground truth values.
        reduction (str, optional): Specifies the reduction to apply to the output:
                                   'none' | 'mean' | 'sum'. 'mean': the mean of the output is taken.
                                   'sum': the output will be summed. 'none': no reduction will be applied.
                                   Default: 'mean'.
        delta (float, optional): The threshold at which to change between delta-scaled L1 and L2 loss. Default: 1.0.
        weight (Tensor, optional): Weights for each sample. Default: None.

    Returns:
        Tensor: Huber loss (optionally weighted).
    """
    if has_torch_function_variadic(input, target, weight):
        return handle_torch_function(huber_loss, (input, target, weight), input, target, reduction=reduction, delta=delta, weight=weight)
    if target.size() != input.size():
        warnings.warn(f'Using a target size ({target.size()}) that is different to the input size ({input.size()}). This will likely lead to incorrect results due to broadcasting. Please ensure they have the same size.', stacklevel=2)
    (expanded_input, expanded_target) = torch.broadcast_tensors(input, target)
    if weight is None:
        return torch._C._nn.huber_loss(expanded_input, expanded_target, _Reduction.get_enum(reduction), delta)
    else:
        if <MASK>:
            raise ValueError('Weights and input must have the same size.')
        unweighted_loss = torch._C._nn.huber_loss(expanded_input, expanded_target, _Reduction.get_enum('none'), delta)
        weighted_loss = unweighted_loss * weight
        if reduction == 'none':
            return weighted_loss
        elif reduction == 'sum':
            return torch.sum(weighted_loss)
        elif reduction == 'mean':
            return weighted_loss.mean()
        else:
            raise ValueError(f"Invalid reduction mode: {reduction}. Expected one of 'none', 'mean', 'sum'.")

def __exit__(self, exc_type, exc_value, traceback):
    if exc_type is not None:
        return
    discrepancy_detected = False
    num_devices = torch.cuda.device_count()
    for i in range(num_devices):
        torch._C._cuda_clearCublasWorkspaces()
        caching_allocator_mem_allocated = torch.cuda.memory_allocated(i)
        if caching_allocator_mem_allocated > self.caching_allocator_befores[i]:
            discrepancy_detected = True
            break
    if <MASK>:
        return
    gc.collect()
    torch.cuda.empty_cache()
    for i in range(num_devices):
        discrepancy_detected = True
        for _ in range(3):
            caching_allocator_mem_allocated = torch.cuda.memory_allocated(i)
            (bytes_free, bytes_total) = torch.cuda.mem_get_info(i)
            driver_mem_allocated = bytes_total - bytes_free
            caching_allocator_discrepancy = False
            driver_discrepancy = False
            if caching_allocator_mem_allocated > self.caching_allocator_befores[i]:
                caching_allocator_discrepancy = True
            if driver_mem_allocated > self.driver_befores[i]:
                driver_discrepancy = True
            if not (caching_allocator_discrepancy or driver_discrepancy):
                discrepancy_detected = False
                break
        if not discrepancy_detected:
            continue
        if caching_allocator_discrepancy and (not driver_discrepancy):
            msg = f'CUDA caching allocator reports a memory leak not verified by the driver API in {self.name}! Caching allocator allocated memory was {self.caching_allocator_befores[i]} and is now reported as {caching_allocator_mem_allocated} on device {i}. CUDA driver allocated memory was {self.driver_befores[i]} and is now {driver_mem_allocated}.'
            warnings.warn(msg)
        elif caching_allocator_discrepancy and driver_discrepancy:
            msg = f'CUDA driver API confirmed a leak in {self.name}! Caching allocator allocated memory was {self.caching_allocator_befores[i]} and is now reported as {caching_allocator_mem_allocated} on device {i}. CUDA driver allocated memory was {self.driver_befores[i]} and is now {driver_mem_allocated}.'
            raise RuntimeError(msg)

def assertDatasetProducesWithShuffle(self, dataset, expected, batch, num_examples, shuffle):
    if shuffle:
        actual = []
        next_fn = self.getNext(dataset)
        for _ in range(num_examples):
            elem = self.evaluate(next_fn())
            if <MASK>:
                actual.extend(elem)
            else:
                actual.extend(elem.tolist())
        self.assertCountEqual(actual, expected)
        with self.assertRaises(errors.OutOfRangeError):
            self.evaluate(next_fn())
    else:
        self.assertDatasetProduces(dataset, list(chunk(expected, batch)))

def call_zip(self, tx: 'InstructionTranslator', *args, **kwargs):
    if kwargs:
        if <MASK>:
            raise_args_mismatch(tx, 'zip', '1 kwargs (`strict`)', f'{len(kwargs)} kwargs')
    strict = kwargs.pop('strict', False)
    args = [BuiltinVariable(iter).call_function(tx, [arg], {}) for arg in args]
    return variables.ZipVariable(args, strict=strict, mutation_type=ValueMutationNew())

def _check_conv_and_broadcast_op(conv_node, other):
    if conv_node.args[1].op != 'get_attr':
        return False
    if conv_node.args[1] is not None and conv_node.args[1].op != 'get_attr':
        return False
    if not isinstance(other, int) and (not isinstance(other, float)) and (other.op != 'get_attr'):
        return False
    if len(conv_node.args[1].users) != 1:
        return False
    weight_meta_value = conv_node.args[1].meta.get('val')
    if weight_meta_value is None:
        return False
    if not weight_meta_value.is_floating_point():
        return False
    if isinstance(other, torch.fx.Node) and other.op == 'get_attr':
        other_meta_value = other.meta.get('val')
        if <MASK>:
            return False
        if torch.promote_types(other_meta_value.dtype, weight_meta_value.dtype) != weight_meta_value.dtype:
            if not conv_node.meta.get('_allow_mixed_dtype_folding', False):
                return False
            if other_meta_value.dtype != torch.float and weight_meta_value.dtype not in (torch.float16, torch.bfloat16):
                return False
        if not _op_not_broadcasting_with_conv(weight_meta_value, other_meta_value):
            return False
    elif not isinstance(other, float):
        return False
    return True

def setitem(self, indexer, value) -> Self:
    """
        Set values with indexer.

        For SingleBlockManager, this backs s[indexer] = value
        """
    if isinstance(indexer, np.ndarray) and indexer.ndim > self.ndim:
        raise ValueError(f'Cannot set values with ndim > {self.ndim}')
    if not self._has_no_reference(0):
        if self.ndim == 2 and isinstance(indexer, tuple):
            blk_loc = self.blklocs[indexer[1]]
            if is_list_like(blk_loc) and blk_loc.ndim == 2:
                blk_loc = np.squeeze(blk_loc, axis=0)
            elif not is_list_like(blk_loc):
                blk_loc = [blk_loc]
            if len(blk_loc) == 0:
                return self.copy(deep=False)
            values = self.blocks[0].values
            if values.ndim == 2:
                values = values[blk_loc]
                self._iset_split_block(0, blk_loc, values)
                indexer = list(indexer)
                if lib.is_integer(indexer[1]):
                    col_indexer = 0
                elif len(blk_loc) > 1:
                    col_indexer = slice(None)
                else:
                    col_indexer = np.arange(len(blk_loc))
                indexer[1] = col_indexer
                row_indexer = indexer[0]
                if <MASK>:
                    row_indexer = np.squeeze(row_indexer, axis=1)
                if isinstance(row_indexer, np.ndarray) and len(row_indexer) == 0:
                    return self
                indexer[0] = row_indexer
                self.blocks[0].setitem(tuple(indexer), value)
                return self
        self = self.copy()
    return self.apply('setitem', indexer=indexer, value=value)

def _create_recomputable_node_only_graph(self) -> nx.DiGraph:
    graph = nx.DiGraph()
    for recomputable_node in self.all_recomputable_banned_nodes:
        graph.add_node(recomputable_node)
    for (a, b) in self.graph_edges:
        if <MASK>:
            graph.add_edge(a, b)
    return graph

def are_same_graph_modules(fn_name, a_mod, b_mod, fake_mode):
    from torch._subclasses._fake_tensor_utils import _CacheKeyState
    from torch._subclasses.fake_tensor import extract_tensor_metadata
    node_map = {}

    def check_all_args(a_nodes, b_nodes):
        for (arg_a, arg_b) in zip(a_nodes, b_nodes):
            if isinstance(arg_a, torch.fx.Node):
                if node_map[arg_a] != arg_b:
                    return False
            elif isinstance(arg_a, slice):
                if not isinstance(arg_b, slice):
                    return False
                if <MASK>:
                    return False
            elif arg_a != arg_b:
                return False
        return True
    for (a_node, b_node) in zip(a_mod.graph.nodes, b_mod.graph.nodes):
        if a_node.op != b_node.op:
            return False
        if a_node.op == 'placeholder':
            a_value = a_node.meta['example_value']
            b_value = b_node.meta['example_value']
            if isinstance(a_value, torch.Tensor):
                if not isinstance(b_value, torch.Tensor):
                    return False
                a_result = []
                state = _CacheKeyState(fake_mode.shape_env)
                a_metadata = extract_tensor_metadata(a_value)
                a_metadata._flatten_into(a_result, fake_mode, state)
                b_result = []
                state = _CacheKeyState(fake_mode.shape_env)
                b_metadata = extract_tensor_metadata(b_value)
                b_metadata._flatten_into(b_result, fake_mode, state)
                if a_result != b_result:
                    return False
            elif isinstance(a_value, torch.SymInt):
                if not isinstance(b_value, torch.SymInt):
                    return False
                if a_value is not b_value:
                    return False
        elif a_node.op == 'call_function':
            if a_node.target is not b_node.target:
                return False
            (a_flat, _) = pytree.tree_flatten((a_node.args, a_node.kwargs))
            (b_flat, _) = pytree.tree_flatten((b_node.args, b_node.kwargs))
            if not check_all_args(a_flat, b_flat):
                hc_log.debug('%s: Graph comparison failed at node (call_function): %s', fn_name, a_node)
                return False
        elif a_node.op == 'call_method':
            if a_node.target != b_node.target:
                return False
            (a_flat, _) = pytree.tree_flatten((a_node.args, a_node.kwargs))
            (b_flat, _) = pytree.tree_flatten((b_node.args, b_node.kwargs))
            if not check_all_args(a_flat, b_flat):
                hc_log.debug('%s: Graph comparison failed at node (call_method) : %s', fn_name, a_node)
                return False
        elif a_node.op == 'output':
            (a_flat, _) = pytree.tree_flatten((a_node.args, a_node.kwargs))
            (b_flat, _) = pytree.tree_flatten((b_node.args, b_node.kwargs))
            if not check_all_args(a_flat, b_flat):
                hc_log.debug('%s: Graph comparison failed at the output node', fn_name)
                return False
        elif a_node.op == 'get_attr':
            a_attr = getattr(a_mod, a_node.target)
            b_attr = getattr(b_mod, b_node.target)
            if isinstance(a_attr, torch.fx.GraphModule):
                if not isinstance(b_attr, torch.fx.GraphModule):
                    return False
                if not are_same_graph_modules(fn_name, a_attr, b_attr, fake_mode):
                    return False
            else:
                raise NotImplementedError(f'get_attr with {type(a_attr)}')
        else:
            raise NotImplementedError(f'Graph equivalence check saw a {a_node.op}')
        node_map[a_node] = b_node
    return True

def scale(self, outputs: Union[torch.Tensor, Iterable[torch.Tensor]]) -> Union[torch.Tensor, Iterable[torch.Tensor]]:
    """
        Multiplies ('scales') a tensor or list of tensors by the scale factor.

        Returns scaled outputs.  If this instance of :class:`GradScaler` is not enabled, outputs are returned
        unmodified.

        Args:
            outputs (Tensor or iterable of Tensors):  Outputs to scale.
        """
    if not self._enabled:
        return outputs
    if <MASK>:
        if self._scale is None:
            self._lazy_init_scale_growth_tracker(outputs.device)
        assert self._scale is not None
        return outputs * self._scale.to(device=outputs.device, non_blocking=True)
    stash: list[_MultiDeviceReplicator] = []

    def apply_scale(val: Union[torch.Tensor, Iterable[torch.Tensor]]):
        if isinstance(val, torch.Tensor):
            if len(stash) == 0:
                if self._scale is None:
                    self._lazy_init_scale_growth_tracker(val.device)
                assert self._scale is not None
                stash.append(_MultiDeviceReplicator(self._scale))
            return val * stash[0].get(val.device)
        if isinstance(val, abc.Iterable):
            iterable = map(apply_scale, val)
            if isinstance(val, (list, tuple)):
                return type(val)(iterable)
            return iterable
        raise ValueError('outputs must be a Tensor or an iterable of Tensors')
    return apply_scale(outputs)

def _clone_and_build_model(model, mode, inputs=None, targets=None):
    """Clone and build the given keras_model."""
    from tensorflow.python.keras import models
    cloned_model = models.clone_model(model, input_tensors=inputs)
    if isinstance(model.optimizer, optimizers.TFOptimizer):
        optimizer = model.optimizer
    else:
        optimizer_config = model.optimizer.get_config()
        optimizer = model.optimizer.__class__.from_config(optimizer_config)

    def _upcast_low_precision_outputs(output):
        if output.dtype == dtypes.bfloat16:
            return math_ops.cast(output, dtypes.float32)
        else:
            return output
    cloned_model.outputs = [_upcast_low_precision_outputs(o) for o in cloned_model.outputs]
    if <MASK>:
        targets = nest.flatten(targets)
    if mode == ModeKeys.PREDICT and inputs is not None:
        _custom_compile_for_predict(cloned_model)
    else:
        cloned_model.compile(optimizer, model.loss, metrics=metrics_module.clone_metrics(model._compile_metrics), loss_weights=model.loss_weights, sample_weight_mode=model.sample_weight_mode, weighted_metrics=metrics_module.clone_metrics(model._compile_weighted_metrics), target_tensors=targets)
    return cloned_model

def get_supported_dtypes(op, sample_inputs_fn, device_type):
    assert device_type in ['cpu', 'cuda']
    if <MASK>:
        warnings.warn('WARNING: CUDA is not available, empty_dtypes dispatch will be returned!')
        return _dynamic_dispatch_dtypes(())
    supported_dtypes = set()
    for dtype in all_types_and_complex_and(torch.bool, torch.bfloat16, torch.half):
        try:
            samples = sample_inputs_fn(op, device_type, dtype, False)
        except RuntimeError:
            warnings.warn(f'WARNING: Unable to generate sample for device:{device_type} and dtype:{dtype}')
            continue
        supported = True
        for sample in samples:
            try:
                op(sample.input, *sample.args, **sample.kwargs)
            except RuntimeError:
                supported = False
                break
        if supported:
            supported_dtypes.add(dtype)
    return _dynamic_dispatch_dtypes(supported_dtypes)

def run_node(self, n: Node) -> Any:
    (args, kwargs) = self.fetch_args_kwargs_from_env(n)
    new_args = []
    assert self.fake_mode
    for arg in args:
        if isinstance(arg, torch.Tensor) and (not isinstance(arg, torch._subclasses.FakeTensor)):
            new_args.append(torch._dynamo.utils.to_fake_tensor(arg, self.fake_mode))
        else:
            new_args.append(arg)
    log.debug('run_node %s, %s got args %s', n.op, n.target, args_str(args))
    assert isinstance(args, tuple)
    assert isinstance(kwargs, dict)
    if <MASK>:
        real_mod = self.fetch_attr(str(n.target))
        if self.fake_mode:
            curr_submod = deepcopy_to_fake_tensor(real_mod, self.fake_mode)
        else:
            curr_submod = real_mod
        ddp_graph_log.debug('\n---%s graph---\n%s', n.target, curr_submod.graph)

        class FakeifyFirstAOTInvocationGuard:

            def __init__(self) -> None:
                self.tc = torch._guards.TracingContext.try_get()
                assert self.tc
                self.tc.fakify_first_call = True

            def __del__(self) -> None:
                self.tc.fakify_first_call = False
        has_tracing_context = torch._guards.TracingContext.try_get() is not None
        if has_tracing_context:
            g = FakeifyFirstAOTInvocationGuard()
        from torch._dynamo.utils import counters
        init = counters['aot_autograd']['total']
        compiled_submod_real = self.compile_submod(real_mod, new_args, kwargs)
        invoked_aot_autograd = init != counters['aot_autograd']['total']
        self.module.delete_submodule(n.target)
        n.target = 'compiled_' + n.target
        self.module.add_submodule(n.target, compiled_submod_real)
        with self.fake_mode, mock.patch.object(self.fake_mode, 'allow_non_fake_inputs', True):
            if has_tracing_context and invoked_aot_autograd:
                tracing_ctx = torch._guards.TracingContext.try_get()
                assert tracing_ctx is not None
                ddp_ctx = tracing_ctx.ddp_optimizer_ctx
                assert ddp_ctx is not None
                assert tracing_ctx.fw_metadata is not None
                ddp_ctx.curr_bucket += 1
                ddp_ctx.metadata_per_bucket.append(tracing_ctx.fw_metadata)
                out = compiled_submod_real(*new_args, **kwargs)
                assert all((not isinstance(t, torch.Tensor) or type(t) is not torch.Tensor for t in (out if isinstance(out, (list, tuple)) else [out])))
                return out
            else:
                return curr_submod(*new_args, **kwargs)
    else:
        return getattr(self, n.op)(n.target, new_args, kwargs)

def maybe_skip_test(self, mode):
    if mode == 'cuda':
        if <MASK>:
            self.skipTest("This test doesn't support Windows")
        if not test.is_gpu_available(cuda_only=True):
            self.skipTest('This test requires GPU.')
        cuda_version_str = sysconfig_lib.get_build_info().get('cuda_version', '0.0')
        cuda_version = tuple([int(x) for x in cuda_version_str.split('.')])
        if cuda_version < (11, 4):
            self.skipTest('This test requires CUDA >= 11.4.')
    if mode == 'mkl' and (not test_util.IsMklEnabled()):
        self.skipTest('MKL is not enabled.')

def _exec_command(command, use_shell=None, use_tee=None, **env):
    """
    Internal workhorse for exec_command().
    """
    if use_shell is None:
        use_shell = os.name == 'posix'
    if <MASK>:
        use_tee = os.name == 'posix'
    if os.name == 'posix' and use_shell:
        sh = os.environ.get('SHELL', '/bin/sh')
        if is_sequence(command):
            command = [sh, '-c', ' '.join(command)]
        else:
            command = [sh, '-c', command]
        use_shell = False
    elif os.name == 'nt' and is_sequence(command):
        command = ' '.join((_quote_arg(arg) for arg in command))
    env = env or None
    try:
        proc = subprocess.Popen(command, shell=use_shell, env=env, text=False, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    except OSError:
        return (127, '')
    (text, err) = proc.communicate()
    mylocale = locale.getpreferredencoding(False)
    if mylocale is None:
        mylocale = 'ascii'
    text = text.decode(mylocale, errors='replace')
    text = text.replace('\r\n', '\n')
    if text[-1:] == '\n':
        text = text[:-1]
    if use_tee and text:
        print(text)
    return (proc.returncode, text)

def _validate_float_format(self, fmt: FloatFormatType | None) -> FloatFormatType | None:
    """
        Validates and processes the float_format argument.
        Converts new-style format strings to callables.
        """
    if fmt is None or callable(fmt):
        return fmt
    if isinstance(fmt, str):
        if <MASK>:
            return fmt
        else:
            try:
                _ = fmt.format(1.0)
                return fmt.format
            except (ValueError, KeyError, IndexError) as e:
                raise ValueError(f'Invalid new-style format string {fmt!r}') from e
    raise ValueError('float_format must be a string or callable')

@register_decomposition(aten.clamp)
@out_wrapper()
@elementwise_type_promotion_wrapper(type_promoting_args=('a', 'min', 'max'), type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
def clamp(a: TensorLikeType, min: Optional[TensorOrNumberLikeType]=None, max: Optional[TensorOrNumberLikeType]=None) -> TensorLikeType:
    if min is None and max is None:
        msg = 'clamp called but both min and max are none!'
        raise ValueError(msg)
    if <MASK>:
        a_isnan = torch.isnan(a)
        condition = torch.bitwise_or(torch.ge(a, min), a_isnan)
        a = torch.where(condition, a, min)
    if max is not None:
        a_isnan = torch.isnan(a)
        condition = torch.bitwise_or(torch.le(a, max), a_isnan)
        a = torch.where(condition, a, max)
    return a

def register(name):
    """Decorator used to register a globally unique name for a TypeSpec subclass.

  Args:
    name: The name of the type spec.  Must be globally unique.  Must have the
      form `"{project_name}.{type_name}"`.  E.g. `"my_project.MyTypeSpec"`.

  Returns:
    A class decorator that registers the decorated class with the given name.
  """
    if not isinstance(name, str):
        raise TypeError('Expected `name` to be a string; got %r' % (name,))
    if <MASK>:
        raise ValueError("Registered name must have the form '{project_name}.{type_name}' (e.g. 'my_project.MyTypeSpec'); got %r." % name)

    def decorator_fn(cls):
        if not (isinstance(cls, type) and issubclass(cls, internal.TypeSpec)):
            raise TypeError('Expected `cls` to be a TypeSpec; got %r' % (cls,))
        if cls in _TYPE_SPEC_TO_NAME:
            raise ValueError('Class %s.%s has already been registered with name %s.' % (cls.__module__, cls.__name__, _TYPE_SPEC_TO_NAME[cls]))
        if name in _NAME_TO_TYPE_SPEC:
            raise ValueError('Name %s has already been registered for class %s.%s.' % (name, _NAME_TO_TYPE_SPEC[name].__module__, _NAME_TO_TYPE_SPEC[name].__name__))
        _TYPE_SPEC_TO_NAME[cls] = name
        _NAME_TO_TYPE_SPEC[name] = cls
        return cls
    return decorator_fn

def set_cpp_kernel_name(self, cpp_kernel_name: Optional[str]=None) -> None:
