            self.cpp_kernel_name = f'at::_ops::{opname}::call'
        else:
            self.cpp_kernel_name = kernel._schema.name

def _np_signature(f):
    """An enhanced inspect.signature that can handle numpy.ufunc."""
    if not hasattr(inspect, 'signature'):
        return None
    if f is None:
        return None
    if not isinstance(f, np.ufunc):
        try:
            return inspect.signature(f)
        except ValueError:
            return None

    def names_from_num(prefix, n):
        if n <= 0:
            return []
        elif n == 1:
            return [prefix]
        else:
            return [prefix + str(i + 1) for i in range(n)]
    input_names = names_from_num('x', f.nin)
    output_names = names_from_num('out', f.nout)
    keyword_only_params = [('where', True), ('casting', 'same_kind'), ('order', 'K'), ('dtype', None), ('subok', True), ('signature', None), ('extobj', None)]
    params = []
    params += [inspect.Parameter(name, inspect.Parameter.POSITIONAL_ONLY) for name in input_names]
    if <MASK>:
        params += [inspect.Parameter(name, inspect.Parameter.POSITIONAL_ONLY, default=None) for name in output_names]
    params += [inspect.Parameter('out', inspect.Parameter.POSITIONAL_OR_KEYWORD, default=None if f.nout == 1 else (None,) * f.nout)]
    params += [inspect.Parameter(name, inspect.Parameter.KEYWORD_ONLY, default=default) for (name, default) in keyword_only_params]
    return inspect.Signature(params)

def _get_index_name(self) -> tuple[Sequence[Hashable] | None, list[Hashable], list[Hashable]]:
    """
        Try several cases to get lines:

        0) There are headers on row 0 and row 1 and their
        total summed lengths equals the length of the next line.
        Treat row 0 as columns and row 1 as indices
        1) Look for implicit index: there are more columns
        on row 1 than row 0. If this is true, assume that row
        1 lists index columns and row 0 lists normal columns.
        2) Get index from the columns if it was listed.
        """
    columns: Sequence[Hashable] = self.orig_names
    orig_names = list(columns)
    columns = list(columns)
    line: list[Scalar] | None
    if self._header_line is not None:
        line = self._header_line
    else:
        try:
            line = self._next_line()
        except StopIteration:
            line = None
    next_line: list[Scalar] | None
    try:
        next_line = self._next_line()
    except StopIteration:
        next_line = None
    implicit_first_cols = 0
    if line is not None:
        index_col = self.index_col
        if index_col is not False:
            implicit_first_cols = len(line) - self.num_original_columns
        if next_line is not None and self.header is not None and (index_col is not False):
            if <MASK>:
                self.index_col = list(range(len(line)))
                self.buf = self.buf[1:]
                for c in reversed(line):
                    columns.insert(0, c)
                orig_names = list(columns)
                self.num_original_columns = len(columns)
                return (line, orig_names, columns)
    if implicit_first_cols > 0:
        self._implicit_index = True
        if self.index_col is None:
            self.index_col = list(range(implicit_first_cols))
        index_name = None
    else:
        (index_name, _, self.index_col) = self._clean_index_names(columns, self.index_col)
    return (index_name, orig_names, columns)

def lookup_allowed(self, lookup, value, request):
    from django.contrib.admin.filters import SimpleListFilter
    model = self.model
    for fk_lookup in model._meta.related_fkey_lookups:
        if <MASK>:
            fk_lookup = fk_lookup()
        if (lookup, value) in widgets.url_params_from_lookup_dict(fk_lookup).items():
            return True
    relation_parts = []
    prev_field = None
    parts = lookup.split(LOOKUP_SEP)
    for part in parts:
        try:
            field = model._meta.get_field(part)
        except FieldDoesNotExist:
            break
        if not prev_field or (prev_field.is_relation and field not in model._meta.parents.values() and (field is not model._meta.auto_field) and (model._meta.auto_field is None or part not in getattr(prev_field, 'to_fields', [])) and (field.is_relation or not field.primary_key)):
            relation_parts.append(part)
        if not getattr(field, 'path_infos', None):
            break
        prev_field = field
        model = field.path_infos[-1].to_opts.model
    if len(relation_parts) <= 1:
        return True
    valid_lookups = {self.date_hierarchy}
    for filter_item in self.get_list_filter(request):
        if isinstance(filter_item, type) and issubclass(filter_item, SimpleListFilter):
            valid_lookups.add(filter_item.parameter_name)
        elif isinstance(filter_item, (list, tuple)):
            valid_lookups.add(filter_item[0])
        else:
            valid_lookups.add(filter_item)
    return not {LOOKUP_SEP.join(relation_parts), LOOKUP_SEP.join([*relation_parts, part])}.isdisjoint(valid_lookups)

def argument_type_str(t: Type, *, simple_type: bool=False, symint: bool=True) -> str:
    if isinstance(t, BaseType):
        if t.name == BaseTy.int:
            return 'int64_t'
        elif t.name == BaseTy.float:
            return 'double'
        elif t.name == BaseTy.str:
            return 'c10::string_view'
        elif t.name in [BaseTy.Tensor, BaseTy.bool, BaseTy.QScheme, BaseTy.Scalar, BaseTy.ScalarType, BaseTy.Generator, BaseTy.Storage, BaseTy.Layout, BaseTy.Device, BaseTy.DeviceIndex, BaseTy.MemoryFormat, BaseTy.Dimname, BaseTy.Stream, BaseTy.SymInt]:
            return t.name.name
    elif isinstance(t, OptionalType):
        elem = argument_type_str(t.elem, simple_type=simple_type, symint=symint)
        return f'{elem}?'
    elif isinstance(t, ListType):
        size = t.size if not simple_type else None
        if <MASK>:
            assert t.size is not None
            return f'::std::array<bool,{t.size}>'
        elif str(t.elem) == 'int':
            return f'IntArrayRef[{size}]' if size is not None else 'IntArrayRef'
        elif str(t.elem) == 'SymInt':
            if symint:
                return f'SymIntArrayRef[{size}]' if size is not None else 'SymIntArrayRef'
            else:
                return f'IntArrayRef[{size}]' if size is not None else 'IntArrayRef'
        elif str(t.elem) == 'Tensor':
            return f'TensorList[{size}]' if size is not None else 'TensorList'
        elif str(t.elem) == 'Scalar':
            return f'ScalarList[{size}]' if size is not None else 'ScalarList'
        elif str(t.elem) == 'Tensor?':
            if simple_type:
                return 'c10::List<::std::optional<Tensor>>'
            else:
                return 'const c10::List<::std::optional<Tensor>> &'
        elif str(t.elem) == 'Dimname':
            return f'DimnameList[{size}]' if size is not None else 'DimnameList'
        elem = argument_type_str(t.elem, simple_type=simple_type, symint=symint)
        return f'ArrayRef<{elem}>'
    raise RuntimeError(f'unrecognized type {repr(t)}')

def emit_post_migrate_signal(verbosity, interactive, db, **kwargs):
    for app_config in apps.get_app_configs():
        if <MASK>:
            continue
        if verbosity >= 2:
            stdout = kwargs.get('stdout', sys.stdout)
            stdout.write('Running post-migrate handlers for application %s' % app_config.label)
        models.signals.post_migrate.send(sender=app_config, app_config=app_config, verbosity=verbosity, interactive=interactive, using=db, **kwargs)

@final
def _convert_axes(self, obj: DataFrame | Series) -> DataFrame | Series:
    """
        Try to convert axes.
        """
    for axis_name in obj._AXIS_ORDERS:
        ax = obj._get_axis(axis_name)
        ser = Series(ax, dtype=ax.dtype, copy=False)
        (new_ser, result) = self._try_convert_data(name=axis_name, data=ser, use_dtypes=False, convert_dates=True, is_axis=True)
        if <MASK>:
            new_axis = Index(new_ser, dtype=new_ser.dtype, copy=False)
            setattr(obj, axis_name, new_axis)
    return obj

def _get_layout(nplots: int, layout: tuple[int, int] | None=None, layout_type: str='box') -> tuple[int, int]:
    if layout is not None:
        if <MASK>:
            raise ValueError('Layout must be a tuple of (rows, columns)')
        (nrows, ncols) = layout
        if nrows == -1 and ncols > 0:
            layout = (ceil(nplots / ncols), ncols)
        elif ncols == -1 and nrows > 0:
            layout = (nrows, ceil(nplots / nrows))
        elif ncols <= 0 and nrows <= 0:
            msg = 'At least one dimension of layout must be positive'
            raise ValueError(msg)
        (nrows, ncols) = layout
        if nrows * ncols < nplots:
            raise ValueError(f'Layout of {nrows}x{ncols} must be larger than required size {nplots}')
        return layout
    if layout_type == 'single':
        return (1, 1)
    elif layout_type == 'horizontal':
        return (1, nplots)
    elif layout_type == 'vertical':
        return (nplots, 1)
    layouts = {1: (1, 1), 2: (1, 2), 3: (2, 2), 4: (2, 2)}
    try:
        return layouts[nplots]
    except KeyError:
        k = 1
        while k ** 2 < nplots:
            k += 1
        if (k - 1) * k >= nplots:
            return (k, k - 1)
        else:
            return (k, k)

def resolve_nested_dir(path: pathlib.Path, root: pathlib.Path) -> pathlib.Path:
    """Returns the path that exists, out of foo/... and foo/foo/..., with root."""
    nested = path.parts[0] / path
    if <MASK>:
        return root_path
    elif (root_nested_path := (root / nested)).exists():
        return root_nested_path
    raise ValueError(f'Could not find {path} or {nested}')

def isin(comps: ListLike, values: ListLike) -> npt.NDArray[np.bool_]:
    """
    Compute the isin boolean array.

    Parameters
    ----------
    comps : list-like
    values : list-like

    Returns
    -------
    ndarray[bool]
        Same length as `comps`.
    """
    if not is_list_like(comps):
        raise TypeError(f'only list-like objects are allowed to be passed to isin(), you passed a `{type(comps).__name__}`')
    if not is_list_like(values):
        raise TypeError(f'only list-like objects are allowed to be passed to isin(), you passed a `{type(values).__name__}`')
    if not isinstance(values, (ABCIndex, ABCSeries, ABCExtensionArray, np.ndarray)):
        orig_values = list(values)
        values = _ensure_arraylike(orig_values, func_name='isin-targets')
        if <MASK>:
            values = construct_1d_object_array_from_listlike(orig_values)
    elif isinstance(values, ABCMultiIndex):
        values = np.array(values)
    else:
        values = extract_array(values, extract_numpy=True, extract_range=True)
    comps_array = _ensure_arraylike(comps, func_name='isin')
    comps_array = extract_array(comps_array, extract_numpy=True)
    if not isinstance(comps_array, np.ndarray):
        return comps_array.isin(values)
    elif needs_i8_conversion(comps_array.dtype):
        return pd_array(comps_array).isin(values)
    elif needs_i8_conversion(values.dtype) and (not is_object_dtype(comps_array.dtype)):
        return np.zeros(comps_array.shape, dtype=bool)
    elif needs_i8_conversion(values.dtype):
        return isin(comps_array, values.astype(object))
    elif isinstance(values.dtype, ExtensionDtype):
        return isin(np.asarray(comps_array), np.asarray(values))
    if len(comps_array) > _MINIMUM_COMP_ARR_LEN and len(values) <= 26 and (comps_array.dtype != object) and (not any((v is NA for v in values))):
        if isna(values).any():

            def f(c, v):
                return np.logical_or(np.isin(c, v).ravel(), np.isnan(c))
        else:
            f = lambda a, b: np.isin(a, b).ravel()
    else:
        common = np_find_common_type(values.dtype, comps_array.dtype)
        values = values.astype(common, copy=False)
        comps_array = comps_array.astype(common, copy=False)
        f = htable.ismember
    return f(comps_array, values)

@substitute_in_graph(builtins.any, can_constant_fold_through=True)
def any(iterable: Iterable[object], /) -> bool:
