def broadcast_symbolic_shapes(a, b):
    """
    Broadcasting logic based on symbolic shapes.

    We give the shapes 0 and 1 concrete values, while all other shapes
    are symbolic sympy formulas.
    """
    output = []
    for (x, y) in itertools.zip_longest(reversed(a), reversed(b), fillvalue=sympy.S.One):
        if <MASK>:
            output.append(x)
        elif V.graph.sizevars.is_size_one_or_false(x):
            output.append(y)
        else:
            V.graph.sizevars.check_equals(x, y)
            if len(sympy.expand(y).free_symbols) < len(sympy.expand(x).free_symbols):
                output.append(y)
            else:
                output.append(x)
    return tuple(reversed(output))

@doc(ExtensionArray.fillna)
def fillna(self, value: object | ArrayLike, limit: int | None=None, copy: bool=True) -> Self:
    if <MASK>:
        return self.copy()
    if limit is not None:
        return super().fillna(value=value, limit=limit, copy=copy)
    if isinstance(value, (np.ndarray, ExtensionArray)):
        if len(value) != len(self):
            raise ValueError(f"Length of 'value' does not match. Got ({len(value)})  expected {len(self)}")
    try:
        fill_value = self._box_pa(value, pa_type=self._pa_array.type)
    except pa.ArrowTypeError as err:
        msg = f"Invalid value '{value!s}' for dtype '{self.dtype}'"
        raise TypeError(msg) from err
    try:
        return self._from_pyarrow_array(pc.fill_null(self._pa_array, fill_value=fill_value))
    except pa.ArrowNotImplementedError:
        pass
    return super().fillna(value=value, limit=limit, copy=copy)

@register_make_test_function()
def make_roll_tests(options):
    """Make a set of tests to do roll."""
    ext_test_parameters = test_parameters + [{'input_dtype': [tf.float32, tf.int32], 'input_shape': [[None, 8, 4]], 'shift': [-3, 5], 'axis': [1, 2]}]

    def set_dynamic_shape(shape):
        return [4 if x is None else x for x in shape]

    def get_shape(param):
        if <MASK>:
            return []
        return [len(param)]

    def get_value(param, dtype):
        if np.isscalar(param):
            return np.dtype(dtype).type(param)
        return np.array(param).astype(dtype)

    def build_graph(parameters):
        input_tensor = tf.compat.v1.placeholder(dtype=parameters['input_dtype'], name='input', shape=parameters['input_shape'])
        shift_tensor = tf.compat.v1.placeholder(dtype=tf.int64, name='shift', shape=get_shape(parameters['shift']))
        axis_tensor = tf.compat.v1.placeholder(dtype=tf.int64, name='axis', shape=get_shape(parameters['axis']))
        outs = tf.roll(input_tensor, shift_tensor, axis_tensor)
        return ([input_tensor, shift_tensor, axis_tensor], [outs])

    def build_inputs(parameters, sess, inputs, outputs):
        input_value = create_tensor_data(parameters['input_dtype'], set_dynamic_shape(parameters['input_shape']))
        shift_value = get_value(parameters['shift'], np.int64)
        axis_value = get_value(parameters['axis'], np.int64)
        return ([input_value, shift_value, axis_value], sess.run(outputs, feed_dict=dict(zip(inputs, [input_value, shift_value, axis_value]))))
    extra_convert_options = ExtraConvertOptions()
    extra_convert_options.allow_custom_ops = True
    make_zip_of_tests(options, ext_test_parameters, build_graph, build_inputs, extra_convert_options)

def _check_symint(symint: Union[int, torch.SymInt], arg: int, range_constraints, unification_map, keypath: KeyPath, i: Optional[int]=None) -> None:
    from torch.export.dynamic_shapes import _IntWrapper
    if isinstance(arg, torch.SymInt) and (not arg.node.expr.is_number) or isinstance(arg, _IntWrapper):
        return
    import sympy
    from torch._export.passes.add_runtime_assertions_for_constraints_pass import _convert_range_to_int
    from torch.utils._sympy.solve import try_solve
    if isinstance(symint, torch.SymInt) and len(symint.node.expr.free_symbols) == 1:
        symbol = next(iter(symint.node.expr.free_symbols))
        if symbol in unification_map:
            existing_dim = symint.node.expr.subs(unification_map)
            if arg != existing_dim:
                path = get_keystr(keypath)
                if i is not None:
                    path += f'.shape[{i}]'
                raise RuntimeError(f'Expected input at {path} to be equal to {existing_dim}, but got {arg}')
        elif isinstance(symint.node.expr, sympy.Symbol):
            unification_map[symbol] = int(arg)
        else:
            solution = try_solve(sympy.Eq(symint.node.expr, arg), symbol)
            if solution is None:
                path = get_keystr(keypath)
                if i is not None:
                    path += f'.shape[{i}]'
                raise RuntimeError(f'Expected input {path} = {arg} to be of the form {symint.node.expr}, where {symbol} is an integer')
            else:
                unification_map[symbol] = int(solution[1])
        if symint.node.expr in range_constraints:
            (min_val, max_val) = _convert_range_to_int(range_constraints[symint.node.expr])
            if <MASK>:
                if arg < min_val:
                    path = get_keystr(keypath)
                    if i is not None:
                        path += f'.shape[{i}]'
                    raise RuntimeError(f'Expected input at {path} to be >= {min_val}, but got {arg}')
            if max_val < math.inf:
                if arg > max_val:
                    path = get_keystr(keypath)
                    if i is not None:
                        path += f'.shape[{i}]'
                    raise RuntimeError(f'Expected input at {path} to be <= {max_val}, but got {arg}')
    elif isinstance(symint, torch.SymInt) and (not symint.node.expr.is_number):
        pass
    elif arg != int(symint):
        path = get_keystr(keypath)
        if i is not None:
            path += f'.shape[{i}]'
        raise RuntimeError(f'Expected input at {path} to be equal to {symint}, but got {arg}. If you meant for this dimension to be dynamic, please re-export and specify dynamic_shapes (e.g. with Dim.DYNAMIC)')

def is_iterable_of_tensors(iterable):
    if isinstance(iterable, torch.Tensor):
        return False
    try:
        if len(iterable) == 0:
            return False
        for t in iter(iterable):
            if <MASK>:
                return False
    except TypeError:
        return False
    return True

def _get_pop_fn(self, w_mod, name, is_bw):

    def fn(*args):
        if <MASK>:
            self._user_post_bw_hook(w_mod(), args)
        if name in self.parents:
            self._active_module_cnt[name] -= 1
            if self._active_module_cnt[name] == 0:
                self.parents.remove(name)
        elif not self.is_bw:
            raise RuntimeError('The Module hierarchy tracking is wrong. Report a bug to PyTorch')
    return fn

def fix_vars(instructions: list[Instruction], code_options: dict[str, Any], varname_from_oparg: Optional[Callable[..., Any]]=None) -> None:
    names = {name: idx for (idx, name) in enumerate(code_options['co_names'])}

    def get_name_index(name: str) -> int:
        try:
            idx = names[name]
        except KeyError:
            idx = names[name] = len(names)
            code_options['co_names'] = (*code_options['co_names'], name)
            assert len(code_options['co_names']) == len(names)
        return idx
    if sys.version_info < (3, 11):
        assert varname_from_oparg is None
        varnames = {name: idx for (idx, name) in enumerate(code_options['co_varnames'])}
        freenames = {name: idx for (idx, name) in enumerate(code_options['co_cellvars'] + code_options['co_freevars'])}
    else:
        assert callable(varname_from_oparg)
        allnames = {}
        for idx in itertools.count():
            try:
                name = varname_from_oparg(idx)
                allnames[name] = idx
            except IndexError:
                break
        varnames = {name: allnames[name] for name in code_options['co_varnames']}
        freenames = {name: allnames[name] for name in code_options['co_cellvars'] + code_options['co_freevars']}
    for i in range(len(instructions)):

        def should_compute_arg() -> bool:
            return instructions[i].argval is not _NotProvided
        if instructions[i].opname == 'LOAD_GLOBAL':
            assert instructions[i].argval is not _NotProvided
            if sys.version_info >= (3, 11):
                assert instructions[i].arg is not None
                instructions[i].arg = (get_name_index(instructions[i].argval) << 1) + cast(int, instructions[i].arg) % 2
            else:
                instructions[i].arg = get_name_index(instructions[i].argval)
        elif instructions[i].opname == 'LOAD_ATTR':
            assert instructions[i].argval is not _NotProvided
            if sys.version_info >= (3, 12):
                assert instructions[i].arg is not None
                instructions[i].arg = (get_name_index(instructions[i].argval) << 1) + cast(int, instructions[i].arg) % 2
            else:
                instructions[i].arg = get_name_index(instructions[i].argval)
        elif instructions[i].opname == 'LOAD_SUPER_ATTR':
            assert instructions[i].arg is not None
            assert instructions[i].argval is not _NotProvided
            instructions[i].arg = (get_name_index(instructions[i].argval) << 2) + cast(int, instructions[i].arg) % 2 + 2
        elif instructions[i].opname in FUSED_INSTS:
            assert sys.version_info >= (3, 13)
            assert isinstance(instructions[i].argval, tuple)
            assert len(instructions[i].argval) == 2
            arg_tuple = tuple((varnames[name] if name in varnames else freenames[name] for name in instructions[i].argval))
            instructions[i].arg = (arg_tuple[0] << 4) + (arg_tuple[1] & 15)
        elif instructions[i].opcode in HAS_LOCAL:
            if <MASK>:
                if sys.version_info >= (3, 13) and instructions[i].argval not in varnames:
                    instructions[i].arg = freenames[instructions[i].argval]
                else:
                    instructions[i].arg = varnames[instructions[i].argval]
        elif instructions[i].opcode in HAS_NAME:
            if should_compute_arg():
                instructions[i].arg = get_name_index(instructions[i].argval)
        elif instructions[i].opcode in HAS_FREE:
            if should_compute_arg():
                instructions[i].arg = freenames[instructions[i].argval]
        elif instructions[i].opcode in HAS_CONST:
            if instructions[i].arg is None:
                idx = get_const_index(code_options, instructions[i].argval)
                assert idx >= 0
                instructions[i].arg = idx

def _fix_start_index(index, rank, num_row_partitions):
    """Slice indexes are always silently truncated."""
    if index < 0:
        if rank is None:
            raise ValueError('Rank must be known to use __getitem__ on a negative index.')
        index = rank + index
    if index < 0:
        index = 0
    if num_row_partitions > 0 and index <= num_row_partitions + 1:
        return index
    if index == 0:
        return index
    if rank is None:
        raise ValueError('Rank must be known to use __getitem__ on a large index.')
    if <MASK>:
        index = rank
    return index

def is_device_compatible_with_triton() -> bool:
    for (device, extra_check) in triton_supported_devices.items():
        device_interface = get_interface_for_device(device)
        if <MASK>:
            return True
    return False

def pre_compile(self, flat_fn: TraceFn, flat_args: list[FxValue], flat_args_descs: list[AOTInput], aot_config: AOTConfig, *, fw_metadata: ViewAndMutationMeta) -> tuple[TraceFn, list[FxValue], list[AOTInput], ViewAndMutationMeta]:
    leaf_flat_args: list[FxValue] = []
    leaf_flat_args_descs: list[AOTInput] = []
    args_set = set()
    ok = True
    for (i, (a, a_desc)) in enumerate(zip(flat_args, flat_args_descs)):
        if not isinstance(a, torch.Tensor):
            leaf_flat_args.append(a)
            leaf_flat_args_descs.append(a_desc)
        elif a not in args_set:
            args_set.add(a)
            leaf_flat_args.append(a)
            leaf_flat_args_descs.append(a_desc)
        elif not fw_metadata.input_info[i].mutates_data and (not fw_metadata.input_info[i].mutates_metadata):
            leaf_flat_args.append(a.detach().requires_grad_(a.requires_grad))
            leaf_flat_args_descs.append(a_desc)
        else:
            ok = False
            break
    if ok:
        self.needs_post_compile = False
        return (flat_fn, leaf_flat_args, leaf_flat_args_descs, fw_metadata)
    if requires_subclass_dispatch(leaf_flat_args, fw_metadata):
        raise RuntimeError('        Encountered duplicate inputs that are mutated in the graph, but at least one input/output\n        to the graph is a tensor subclass. This is not supported today. You can try to\n        remove the aliasing yourself as a workaround, or otherwise file an issue on github.')
    if <MASK>:
        raise RuntimeError(f'        Encountered duplicated inputs that are mutated in the graph you are trying to export.\n        This functionality is currently not supported. If needed, please file a github issue.\n\n        fw_metadata={str(fw_metadata)}\n            ')
    seen_args: dict[Tensor, int] = {}
    keep_arg_mask: list[bool] = []
    add_dupe_map: list[int] = []
    duped_arg_len = len(flat_args)
    j = 0
    for t in flat_args:
        if isinstance(t, torch.Tensor):
            if t in seen_args:
                keep_arg_mask.append(False)
                add_dupe_map.append(seen_args[t])
                continue
            seen_args[t] = j
        keep_arg_mask.append(True)
        add_dupe_map.append(j)
        j += 1
    assert len(add_dupe_map) == duped_arg_len, f'Expects add_dupe_map to have length {duped_arg_len} but got {len(add_dupe_map)}'
    self.keep_arg_mask = keep_arg_mask
    self.add_dupe_map = add_dupe_map
    deduped_flat_args = self.remove_dupe_args(flat_args)
    deduped_flat_args_descs = self.remove_dupe_args(flat_args_descs)
    updated_fw_metadata = remove_dupe_metadata(fw_metadata, keep_arg_mask, add_dupe_map)
    if (tracing_context := (TracingContext.try_get() and aot_config.aot_autograd_arg_pos_to_source)):
        for (dupe_arg_pos, (kept_pos, keep_arg)) in enumerate(zip(add_dupe_map, keep_arg_mask)):
            if not keep_arg:
                dupe_arg_source = aot_config.aot_autograd_arg_pos_to_source[dupe_arg_pos]
                kept_arg_source = aot_config.aot_autograd_arg_pos_to_source[kept_pos]
                tracing_context.guards_context.aotautograd_guards.append(DuplicateInputs(kept_arg_source, dupe_arg_source))

    @simple_wraps(flat_fn)
    def wrapped_flat_fn(*args: FxValue) -> tuple[list[FxValue], list[AOTOutput]]:
        (outs, out_descs) = call_and_expect_output_descs(flat_fn, self.add_dupe_args(args))
        return (outs, out_descs)
    if config.debug_assert:
        ref_fw_metadata = run_functionalized_fw_and_collect_metadata(without_output_descs(wrapped_flat_fn), flat_args_descs=deduped_flat_args_descs, static_input_indices=aot_config.static_input_indices, keep_input_mutations=fw_metadata.keep_input_mutations, is_train=fw_metadata.is_train)(*deduped_flat_args)
        assert ref_fw_metadata == updated_fw_metadata, f'ref_metadata={str(ref_fw_metadata)}, actual_metadata={str(updated_fw_metadata)}'
    return (wrapped_flat_fn, deduped_flat_args, deduped_flat_args_descs, updated_fw_metadata)

@staticmethod
def backward(ctx, grad_output):
    scattered_grads = Scatter.apply(ctx.input_gpus, ctx.input_sizes, ctx.dim, grad_output)
    if <MASK>:
        scattered_grads = tuple((g[0] for g in scattered_grads))
    return (None, None) + scattered_grads

def __init__(self, in_channels, out_channels, kernel_size, stride, padding, dilation, transposed, output_padding, groups, bias, padding_mode, eps=1e-05, momentum=0.1, freeze_bn=False, qconfig=None, dim=2):
    nn.modules.conv._ConvNd.__init__(self, in_channels, out_channels, kernel_size, stride, padding, dilation, transposed, output_padding, groups, False, padding_mode)
    assert qconfig, 'qconfig must be provided for QAT module'
    self.qconfig = qconfig
    self.freeze_bn = freeze_bn if self.training else True
    self.bn = _BN_CLASS_MAP[dim](out_channels, eps, momentum, True, True)
    self.weight_fake_quant = self.qconfig.weight()
    if bias:
        self.bias = Parameter(torch.empty(out_channels))
    else:
        self.register_parameter('bias', None)
    self.reset_bn_parameters()
    if <MASK>:
        if freeze_bn:
            self.freeze_bn_stats()
        else:
            self.update_bn_stats()
    else:
        self.freeze_bn_stats()
    self._enable_slow_path_for_better_numerical_stability = False

def __call__(self, shape, dtype=None, partition_info=None):
    if dtype is None:
        dtype = self.dtype
    if <MASK>:
        raise ValueError(f'The tensor to initialize, specified by argument `shape` must be five-dimensional. Received shape={shape}')
    if shape[-2] > shape[-1]:
        raise ValueError(f'In_filters, specified by shape[-2]={shape[-2]} cannot be greater than out_filters, specified by shape[-1]={shape[-1]}.')
    if shape[0] != shape[1] or shape[0] != shape[2]:
        raise ValueError(f'Kernel sizes, specified by shape[0]={shape[0]},  shape[1]={shape[1]} and shape[2]={shape[2]} must be equal.')
    kernel = self._orthogonal_kernel(shape[0], shape[-2], shape[-1])
    kernel *= math_ops.cast(self.gain, dtype=dtype)
    return kernel

@register_op_impl(_is_tensor_constructor)
@register_op_impl([*_like_tensor_constructors])
def constructors(fake_mode, func, *args, **kwargs):
    assert func not in _non_kwarg_device_constructors
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    if 'names' in kwargs:
        raise UnsupportedOperatorException("torch.compile doesn't support named tensors")
    if <MASK>:
        default_device = new_kwargs['input'].device
        args = (new_kwargs.pop('input'),)
    else:
        default_device = torch.device('cpu')
        args = ()
    out_device = new_kwargs.pop('device', None)
    out_device = out_device if out_device is not None else default_device
    new_kwargs['device'] = torch.device('meta')
    with in_kernel_invocation_manager(fake_mode):
        r = func(*args, **new_kwargs)
    return FakeTensor(fake_mode, r, out_device)

def is_valid_ipv6_address(ip_addr):
    """
    Return whether the `ip_addr` object is a valid IPv6 address.
    """
    if <MASK>:
        return True
    try:
        _ipv6_address_from_str(ip_addr)
    except (TypeError, ValueError):
        return False
    return True

def fully_qualified_type(argument_type: str) -> str:

    def maybe_optional_type(type: str, is_opt: bool) -> str:
        return f'std::optional<{type}>' if is_opt else type
    opt_match = OPTIONAL_TYPE_PATTERN.match(argument_type)
    is_opt = opt_match is not None
    if opt_match:
        argument_type = argument_type[opt_match.start(1):opt_match.end(1)]
    match = TYPE_PATTERN.match(argument_type)
    if <MASK>:
        return maybe_optional_type(argument_type, is_opt)
    index = match.start(1)
    qualified_type = f'{argument_type[:index]}at::{argument_type[index:]}'
    return maybe_optional_type(qualified_type, is_opt)

def postcrack2(block, tab='', param_map=None):
    global f90modulevars
    if not f90modulevars:
        return block
    if isinstance(block, list):
        ret = [postcrack2(g, tab=tab + '\t', param_map=param_map) for g in block]
        return ret
    setmesstext(block)
    outmess(f"{tab}Block: {block['name']}\n", 0)
    if <MASK>:
        param_map = get_useparameters(block)
    if param_map is not None and 'vars' in block:
        vars = block['vars']
        for n in list(vars.keys()):
            var = vars[n]
            if 'kindselector' in var:
                kind = var['kindselector']
                if 'kind' in kind:
                    val = kind['kind']
                    if val in param_map:
                        kind['kind'] = param_map[val]
    new_body = [postcrack2(b, tab=tab + '\t', param_map=param_map) for b in block['body']]
    block['body'] = new_body
    return block

def post_backward(self, *unused: Any):
    if not compiled_autograd_enabled():
        logger.debug('%s', self._with_fqn('FSDP::post_backward'))
    self._training_state = TrainingState.POST_BACKWARD
    with record_function(self._with_fqn('FSDP::post_backward_accumulate')):
        for fsdp_param in self.fsdp_params:
            fsdp_param.accumulate_unsharded_grad_if_needed()
    with record_function(self._with_fqn('FSDP::post_backward_reshard')):
        if not self.reduce_grads:
            if self.reshard_after_backward:
                self.reshard()
            for fsdp_param in self.fsdp_params:
                fsdp_param.to_accumulated_grad_if_needed()
            return
        fsdp_params_with_grad: list[FSDPParam] = []
        unsharded_grads: list[torch.Tensor] = []
        for fsdp_param in self.fsdp_params:
            if not hasattr(fsdp_param, '_unsharded_param'):
                continue
            if fsdp_param.unsharded_accumulated_grad is not None:
                fsdp_params_with_grad.append(fsdp_param)
                unsharded_grads.append(fsdp_param.unsharded_accumulated_grad_data)
                fsdp_param.unsharded_accumulated_grad = None
            elif fsdp_param.unsharded_param.grad is not None:
                fsdp_params_with_grad.append(fsdp_param)
                unsharded_grads.append(fsdp_param.unsharded_grad_data)
                fsdp_param.unsharded_param.grad = None
        if self.reshard_after_backward:
            self.reshard()
    if len(fsdp_params_with_grad) == 0:
        return
    with record_function(self._with_fqn('FSDP::post_backward_reduce')):
        if <MASK>:
            self.device_handle.current_stream().wait_event(self.comm_ctx.reduce_scatter_state.event)
        self.comm_ctx.reduce_scatter_state = None
        all_reduce_pg = self._all_reduce_process_group if self._is_hsdp else None
        all_reduce_stream: torch.cuda.Stream
        if all_reduce_pg is None and self._all_reduce_hook_stream is not None:
            if self._all_reduce_hook is None:
                raise AssertionError('all reduce hook stream is specified but hook itself is missing.')
            all_reduce_stream = self._all_reduce_hook_stream
        else:
            all_reduce_stream = self.comm_ctx.all_reduce_stream
        self._wait_for_post_backward()
        (reduce_scatter_input, reduce_scatter_event, self._post_reduce_event, all_reduce_input, all_reduce_event, self._partial_reduce_output) = foreach_reduce(fsdp_params_with_grad, unsharded_grads, self._reduce_scatter_process_group, self.comm_ctx.reduce_scatter_stream, self._reduce_scatter_comm, self._orig_dtype, self._reduce_dtype, self.device, self.gradient_divide_factor, self._all_reduce_process_group if self._is_hsdp else None, all_reduce_stream, self.all_reduce_grads, self._partial_reduce_output, self._all_reduce_hook, self.force_sum_reduction_for_comms)
        self.comm_ctx.reduce_scatter_state = ReduceScatterState(reduce_scatter_input, reduce_scatter_event)
        if all_reduce_input is not None:
            if self.device.type != 'cpu':
                if all_reduce_event is None:
                    raise AssertionError('Expected all_reduce_event to be set for non-CPU device')
            self._all_reduce_state = AllReduceState(all_reduce_input, all_reduce_event)

def _fast_expand(expr: _SympyT) -> _SympyT:
    """
    A faster implementation of sympy's expand function for common cases.

    This function expands expressions like (a+b)^n or (a+b)*(c+d) into sums of products,
    but avoids the expensive checks and features of sympy's full expand implementation.
    It only recreates objects when necessary to avoid expensive operations.

    Args:
        expr: A sympy expression to expand

    Returns:
        The expanded expression
    """
    new_args = [_fast_expand(arg) for arg in expr.args]
    if any((arg is not new_arg for (arg, new_arg) in zip(expr.args, new_args))):
        return _fast_expand(expr.func(*new_args))
    if expr.is_Pow:
        base: sympy.Expr
        exp: sympy.Expr
        (base, exp) = expr.args
        if exp.is_Integer and base.is_Add:
            if exp > 1:
                return sympy.expand_multinomial(expr, deep=False)
            elif exp < 0:
                return S.One / sympy.expand_multinomial(S.One / expr, deep=False)
    elif <MASK>:
        num: list[sympy.Expr] = []
        den: list[sympy.Expr] = []
        for arg in expr.args:
            if arg.is_Pow and arg.args[1] == -1:
                den.append(S.One / arg)
            else:
                num.append(arg)
        (num, num_changed) = _expandsums(num)
        (den, den_changed) = _expandsums(den)
        if num_changed or den_changed:
            return num / den
    return expr

def prepare_body(self, data, files, json=None):
    """Prepares the given HTTP body data."""
    body = None
    content_type = None
    if not data and json is not None:
        content_type = 'application/json'
        try:
            body = complexjson.dumps(json, allow_nan=False)
        except ValueError as ve:
            raise InvalidJSONError(ve, request=self)
        if not isinstance(body, bytes):
            body = body.encode('utf-8')
    is_stream = all([hasattr(data, '__iter__'), not isinstance(data, (basestring, list, tuple, Mapping))])
    if is_stream:
        try:
            length = super_len(data)
        except (TypeError, AttributeError, UnsupportedOperation):
            length = None
        body = data
        if getattr(body, 'tell', None) is not None:
            try:
                self._body_position = body.tell()
            except OSError:
                self._body_position = object()
        if files:
            raise NotImplementedError('Streamed bodies and files are mutually exclusive.')
        if length:
            self.headers['Content-Length'] = builtin_str(length)
        else:
            self.headers['Transfer-Encoding'] = 'chunked'
    else:
        if files:
            (body, content_type) = self._encode_files(files, data)
        elif data:
            body = self._encode_params(data)
            if isinstance(data, basestring) or hasattr(data, 'read'):
                content_type = None
            else:
                content_type = 'application/x-www-form-urlencoded'
        self.prepare_content_length(body)
        if <MASK>:
            self.headers['Content-Type'] = content_type
    self.body = body

def results_iter(self, results=None, tuple_expected=False, chunked_fetch=False, chunk_size=GET_ITERATOR_CHUNK_SIZE):
    """Return an iterator over the results from executing this query."""
    if <MASK>:
        results = self.execute_sql(MULTI, chunked_fetch=chunked_fetch, chunk_size=chunk_size)
    fields = [s[0] for s in self.select[0:self.col_count]]
    converters = self.get_converters(fields)
    rows = chain.from_iterable(results)
    if converters:
        rows = self.apply_converters(rows, converters)
    if self.has_composite_fields(fields):
        rows = self.composite_fields_to_tuples(rows, fields)
    if tuple_expected:
        rows = map(tuple, rows)
    return rows

def handle_call_function(self, node: torch.fx.Node):
    assert node.op == 'call_function'
    meta_val = node.meta.get('val')
    log.debug('[handle_call_function] %s: %s(%s, {%s}) -> %s', node.name, node.target, node.args, node.kwargs, meta_val)
    if node.target is operator.getitem:
        return
    if node.target in _SYM_OPS or (meta_val is not None and isinstance(meta_val, (torch.SymInt, torch.SymBool, torch.SymFloat))):
        assert len(node.kwargs) == 0
        ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_sym_op_inputs(node.target, node.args), outputs=[self.serialize_output(node.name, meta_val)], metadata=self.serialize_metadata(node))
    elif isinstance(node.target, torch._ops.OpOverload):
        ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_inputs(node.target, node.args, node.kwargs), outputs=self.serialize_outputs(node), metadata=self.serialize_metadata(node))
    elif isinstance(node.target, torch._ops.HigherOrderOperator):

        def _is_hop_single_tensor_return(node) -> bool:
            assert isinstance(node.target, torch._ops.HigherOrderOperator)
            meta_val = node.meta.get('val', None)
            return meta_val is not None and isinstance(meta_val, torch.Tensor)
        if <MASK>:
            serializable_args = list(node.args)
            lowered_module_name: str = node.args[0].name
            assert hasattr(node.graph.owning_module, lowered_module_name)
            lowered_module = getattr(node.graph.owning_module, lowered_module_name)
            serializable_args[0] = lowered_module.aoti_path
            serializable_args[1] = None
            serializable_weight_nodes = []
            if serializable_args[2] is not None and isinstance(serializable_args[2], Iterable):
                for weight_node in serializable_args[2]:
                    if isinstance(weight_node, torch.fx.Node) and isinstance(weight_node.meta.get('val', None), ep.CustomObjArgument):
                        continue
                    serializable_weight_nodes.append(weight_node)
                serializable_args[2] = serializable_weight_nodes

            def serialize_tensor_list_output(node):
                meta_val = node.meta.get('val', None)
                tensor_args = []
                for (idx, meta) in enumerate(meta_val):
                    name = self._output_node_name_at_index(node, idx)
                    tensor_args.append(self.serialize_tensor_output(name, meta))
                return [Argument.create(as_tensors=tensor_args)]
            ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_hoo_inputs(serializable_args, node.kwargs), outputs=serialize_tensor_list_output(node), metadata=self.serialize_metadata(node), is_hop_single_tensor_return=False)
        elif node.target is torch._higher_order_ops.triton_kernel_wrap.triton_kernel_wrapper_functional:
            (kernel, kernel_cache_entry) = get_triton_kernel_and_cache_entry(node)
            kernel_cache_metadata = kernel_cache_entry.metadata
            meta_val = node.meta['val']
            assert isinstance(meta_val, dict)
            output_keys = meta_val.keys()
            output_indices = []
            constexpr_keys = set()
            for p in kernel.params:
                if p.is_constexpr:
                    constexpr_keys.add(p.name)
            found_constexpr = False
            args_new = ()
            i = 0
            assert isinstance(node.kwargs['kwargs'], dict)
            for (k, v) in node.kwargs['kwargs'].items():
                if k in constexpr_keys:
                    found_constexpr = True
                    continue
                assert not found_constexpr, 'non-constexpr args found after constexpr arg(s)'
                if k in output_keys:
                    output_indices.append(i)
                args_new += (v,)
                i += 1
            assert isinstance(node.kwargs['grid'], list)
            kwargs_new = {'name': kernel.fn.__name__, 'grid': node.kwargs['grid'][0], 'output_indices': output_indices, 'num_warps': kernel_cache_metadata.num_warps}
            if hasattr(kernel_cache_metadata, 'shared'):
                kwargs_new['shared_memory_bytes'] = kernel_cache_metadata.shared
            ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_hoo_inputs(args_new, kwargs_new), outputs=self.serialize_hoo_outputs(node), metadata=self.serialize_metadata(node), is_hop_single_tensor_return=_is_hop_single_tensor_return(node))
        else:
            ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_hoo_inputs(node.args, node.kwargs), outputs=self.serialize_hoo_outputs(node), metadata=self.serialize_metadata(node), is_hop_single_tensor_return=_is_hop_single_tensor_return(node))
    elif type(node.target) in _serialization_registry:
        assert type(node.target) in _serialization_registry, f'{type(node.target)} is not supported in export serialization.'
        handler = _serialization_registry[type(node.target)]
        namespace = handler.namespace()
        op_name = handler.to_op_name(node.target)
        assert isinstance(namespace, str) and isinstance(op_name, str)
        assert ':' not in namespace and ':' not in op_name
        ex_node = Node(target=f'#{namespace}:{op_name}', inputs=self.serialize_inputs(node.target, node.args, node.kwargs), outputs=self.serialize_outputs(node), metadata=self.serialize_metadata(node))
    else:
        raise SerializeError(f'Serializing {node.target} is not supported')
    self.graph_state.nodes.append(ex_node)

def _reconstruct(self, x, memo, func, args, state=None, listiter=None, dictiter=None, non_blocking=False):
    deep = memo is not None
    if deep and args:
        args = tuple((self.deepcopy_with_tensor_offload(arg, memo, non_blocking=non_blocking) for arg in args))
    y = func(*args)
    if deep:
        memo[id(x)] = y
    if state is not None:
        if deep:
            state = self.deepcopy_with_tensor_offload(state, memo, non_blocking=non_blocking)
        if hasattr(y, '__setstate__'):
            y.__setstate__(state)
        else:
            if isinstance(state, tuple) and len(state) == 2:
                (state, slotstate) = state
            else:
                slotstate = None
            if state is not None:
                y.__dict__.update(state)
            if <MASK>:
                for (key, value) in slotstate.items():
                    setattr(y, key, value)
    if listiter is not None:
        if deep:
            for item in listiter:
                item = self.deepcopy_with_tensor_offload(item, memo, non_blocking=non_blocking)
                y.append(item)
        else:
            for item in listiter:
                y.append(item)
    if dictiter is not None:
        if deep:
            for (key, value) in dictiter:
                key = self.deepcopy_with_tensor_offload(key, memo, non_blocking=non_blocking)
