    self.sparse = sparse

def _unravel_index(indices: Tensor, shape: Union[int, Sequence[int]]) -> Tensor:
    torch._check_type(not indices.is_complex() and (not indices.is_floating_point()) and (indices.dtype != torch.bool), lambda : f"expected 'indices' to be integer dtype, but got {indices.dtype}")
    torch._check_type(isinstance(shape, (int, torch.SymInt, Sequence)), lambda : f"expected 'shape' to be int or sequence of ints, but got {type(shape)}")
    if <MASK>:
        shape = torch.Size([shape])
    else:
        for dim in shape:
            torch._check_type(isinstance(dim, (int, torch.SymInt)), lambda : f"expected 'shape' sequence to only contain ints, but got {type(dim)}")
        shape = torch.Size(shape)
    torch._check_value(all((dim >= 0 for dim in shape)), lambda : f"'shape' cannot have negative values, but got {tuple(shape)}")
    coefs = list(reversed(list(itertools.accumulate(reversed(shape[1:] + torch.Size([1])), func=operator.mul))))
    return indices.unsqueeze(-1).floor_divide(torch.tensor(coefs, device=indices.device, dtype=torch.int64)) % torch.tensor(shape, device=indices.device, dtype=torch.int64)

def init_cooperative_reduction(self):
    """One time setup code for cooperative reductions."""
    assert self.cooperative_reduction
    for tree in self.range_trees:
        if tree.grid_dim is not None:
            tree.grid_dim += 1
    sem_count = self.numels['x']
    if self.fixed_config:
        sem_count = CeilDiv(sem_count, self.fixed_config['XBLOCK'])
    self.semaphores_name = self.args.semaphores(sem_count)
    self.cooperative_reduction_workspace_cache = CooperativeReductionWorkspaceCache(self.args)
    self.body.splice('            RSPLIT_NEXT_POWER_OF_2: tl.constexpr = triton_helpers.constexpr_next_power_of_2(RSPLIT)\n            RSPLIT_IS_POWER_OF_2: tl.constexpr = RSPLIT == RSPLIT_NEXT_POWER_OF_2\n            HAS_RSPLIT: tl.constexpr = RSPLIT > 1\n            rsplit_id = tl.program_id(0)\n            num_rblocks = (rnumel + RBLOCK - 1) // RBLOCK\n            rsplit_chunk = (num_rblocks + RSPLIT - 1) // RSPLIT * RBLOCK\n            rsplit_start = rsplit_chunk * rsplit_id\n            rsplit_end = rsplit_chunk * (rsplit_id + 1)\n            ')
    if <MASK>:
        self.body.writeline('rsplit_end = tl.where(rsplit_end < rnumel, rsplit_end, rnumel)')

