    else:
        _algorithm = algorithm.upper()
    if _algorithm == 'MD5' or _algorithm == 'MD5-SESS':

        def md5_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.md5(x).hexdigest()
        hash_utf8 = md5_utf8
    elif _algorithm == 'SHA':

        def sha_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha1(x).hexdigest()
        hash_utf8 = sha_utf8
    elif _algorithm == 'SHA-256':

        def sha256_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha256(x).hexdigest()
        hash_utf8 = sha256_utf8
    elif _algorithm == 'SHA-512':

        def sha512_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha512(x).hexdigest()
        hash_utf8 = sha512_utf8
    KD = lambda s, d: hash_utf8(f'{s}:{d}')
    if hash_utf8 is None:
        return None
    entdig = None
    p_parsed = urlparse(url)
    path = p_parsed.path or '/'
    if p_parsed.query:
        path += f'?{p_parsed.query}'
    A1 = f'{self.username}:{realm}:{self.password}'
    A2 = f'{method}:{path}'
    HA1 = hash_utf8(A1)
    HA2 = hash_utf8(A2)
    if nonce == self._thread_local.last_nonce:
        self._thread_local.nonce_count += 1
    else:
        self._thread_local.nonce_count = 1
    ncvalue = f'{self._thread_local.nonce_count:08x}'
    s = str(self._thread_local.nonce_count).encode('utf-8')
    s += nonce.encode('utf-8')
    s += time.ctime().encode('utf-8')
    s += os.urandom(8)
    cnonce = hashlib.sha1(s).hexdigest()[:16]
    if _algorithm == 'MD5-SESS':
        HA1 = hash_utf8(f'{HA1}:{nonce}:{cnonce}')
    if not qop:
        respdig = KD(HA1, f'{nonce}:{HA2}')
    elif qop == 'auth' or 'auth' in qop.split(','):
        noncebit = f'{nonce}:{ncvalue}:{cnonce}:auth:{HA2}'
        respdig = KD(HA1, noncebit)
    else:
        return None
    self._thread_local.last_nonce = nonce
    base = f'username="{self.username}", realm="{realm}", nonce="{nonce}", uri="{path}", response="{respdig}"'
    if opaque:
        base += f', opaque="{opaque}"'
    if algorithm:
        base += f', algorithm="{algorithm}"'
    if <MASK>:
        base += f', digest="{entdig}"'
    if qop:
        base += f', qop="auth", nc={ncvalue}, cnonce="{cnonce}"'
    return f'Digest {base}'

def tensor_counts(arr):
    counts = [len(np.shape(arr)), np.size(arr), 0, 0, 0, 0, 0, 0]
    for n in np.ravel(arr):
        if np.isneginf(n):
            counts[2] += 1
        elif np.isposinf(n):
            counts[3] += 1
        elif <MASK>:
            counts[4] += 1
        elif n < 0.0:
            counts[5] += 1
        elif n == 0.0:
            counts[6] += 1
        else:
            counts[7] += 1
    return counts

def get_cudnn_mode(mode):
    if mode == 'RNN_RELU':
        return int(_cudnn.RNNMode.rnn_relu)
    elif <MASK>:
        return int(_cudnn.RNNMode.rnn_tanh)
    elif mode == 'LSTM':
        return int(_cudnn.RNNMode.lstm)
    elif mode == 'GRU':
        return int(_cudnn.RNNMode.gru)
    else:
        raise Exception(f'Unknown mode: {mode}')

def _show_compute(self, show_dataflow: bool) -> None:
    """Visualize the computation activity."""
    for dev_stats in self._step_stats.dev_stats:
        device_name = dev_stats.device
        device_pid = self._device_pids[device_name]
        is_gputrace = self._is_gputrace_device(device_name)
        for node_stats in dev_stats.node_stats:
            tid = node_stats.thread_id
            start_time = node_stats.all_start_micros
            end_time = node_stats.all_start_micros + node_stats.all_end_rel_micros
            self._emit_op(node_stats, device_pid, is_gputrace)
            if is_gputrace or node_stats.node_name == 'RecvTensor':
                continue
            (_, _, inputs) = self._parse_op_label(node_stats.timeline_label)
            for input_name in inputs:
                if input_name not in self._tensors:
                    index = input_name.rfind('/_')
                    if <MASK>:
                        input_name = input_name[:index]
                if input_name in self._tensors:
                    tensor = self._tensors[input_name]
                    tensor.add_ref(start_time)
                    tensor.add_unref(end_time - 1)
                    if show_dataflow:
                        (create_time, create_pid, create_tid) = self._flow_starts[input_name]
                        if create_pid != device_pid or create_tid != tid:
                            flow_id = self._alloc_flow_id()
                            self._chrome_trace.emit_flow_start(input_name, create_time, create_pid, create_tid, flow_id)
                            self._chrome_trace.emit_flow_end(input_name, start_time, device_pid, tid, flow_id)
                else:
                    logging.vlog(1, "Can't find tensor %s - removed by CSE?", input_name)

def delete_model(self, model):
    """Delete a model from the database."""
    for field in model._meta.local_many_to_many:
        if <MASK>:
            self.delete_model(field.remote_field.through)
    self.execute(self.sql_delete_table % {'table': self.quote_name(model._meta.db_table)})
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_table(model._meta.db_table):
            self.deferred_sql.remove(sql)

def _make_callable_signature(obj):
    """Generate signature for function/method."""
    if inspect.isclass(obj) or inspect.isfunction(obj):
        if <MASK>:
            return _make_lambda_name(obj)
        return obj.__name__
    elif inspect.ismethod(obj):
        obj_self = obj.__self__
        if isinstance(obj_self, type):
            cls_name = obj_self.__name__
        else:
            cls_name = obj_self.__class__.__name__
        return f'{cls_name}.{obj.__name__}'
    else:
        raise TypeError(f'Only class/function/methods are valid inputs, got {type(obj)}')

def get_random_dim(self):
    distr_type = self.get_distr_type()
    if distr_type == 'mult_128':
        return self.random_multiple_of_128(min_num=10, max_num=17)
    if <MASK>:
        return self.get_random_pow2(min_power2=10, max_power2=17)
    elif distr_type == 'uniform-between-pow2':
        return get_random_between_pow2(min_power2=10, max_power2=17)
    elif distr_type == 'uniform':
        return random.randint(1024, 131072)
    print(f'random_type {distr_type} not supported')
    sys.exit(1)

def __call__(self, *args, **kwargs):
    if self._is_context_empty():
        for arg in args:
            if isinstance(arg, Capture) and (not arg._is_context_empty()):
                self.ctx = arg.ctx
                break
        if self._is_context_empty():
            for (k, v) in kwargs.items():
                if <MASK>:
                    self.ctx = k.ctx
                    break
                if isinstance(v, Capture) and (not v._is_context_empty()):
                    self.ctx = v.ctx
                    break
    res = CaptureCall(self, ctx=self.ctx, args=args, kwargs=kwargs)
    var = CaptureVariable(None, ctx=self.ctx)
    t = CaptureVariableAssign(ctx=self.ctx, variable=var, value=res)
    self.ctx['operations'].append(t)
    return var

def init_state(self) -> None:
    """
        Run a dummy optimizer step, which allows to initialize optimizer state because we do lazy init for most optimizers.

        This allows doing in-place loading of optimizer state from a checkpoint.
        """
    for param in self.named_parameters.values():
        if <MASK>:
            t = torch.zeros_like(param)
            param.grad = torch.autograd.Variable(t)
    self.step(closure=None)

def _flatten_to_reference_inputs(self, tensors):
    """Maps `tensors` to their respective `keras.Input`."""
    if self._enable_dict_to_input_mapping and isinstance(tensors, dict):
        ref_inputs = self._nested_inputs
        if <MASK>:
            ref_inputs = [self._nested_inputs]
        if isinstance(ref_inputs, dict):
            ref_input_names = sorted(ref_inputs.keys())
        else:
            ref_input_names = [inp._keras_history.layer.name for inp in ref_inputs]
        if len(tensors) > len(ref_input_names):
            warnings.warn('Input dict contained keys {} which did not match any model input. They will be ignored by the model.'.format([n for n in tensors.keys() if n not in ref_input_names]))
        try:
            return [tensors[n] for n in ref_input_names]
        except KeyError:
            return nest.flatten(tensors)
    return nest.flatten(tensors)

def _process_def(self, node: Union[ast.ClassDef, ast.FunctionDef]) -> None:
    """Process top-level [Class|Function]Def for potential symbol export."""
    for decorator in node.decorator_list:
        if self._is_export_call(decorator):
            self._add_exported_symbol(cast(ast.Call, decorator), node.name)
        else:
            self.visit(decorator)
    if isinstance(node, ast.ClassDef):
        for base in node.bases:
            self.visit(base)
        for kw in node.keywords:
            self.visit(kw)
    elif <MASK>:
        self.visit(node.args)
        if node.returns:
            self.visit(node.returns)
    for stmt in node.body:
        self.visit(stmt)

def testFloatSizes(self):
    t = tensor_util.make_tensor_proto([10.0, 20.0, 30.0], shape=[1, 3])
    if <MASK>:
        self.assertProtoEquals('\n        dtype: DT_FLOAT\n        tensor_shape { dim { size: 1 } dim { size: 3 } }\n        tensor_content: "A \\000\\000A\\240\\000\\000A\\360\\000\\000"\n        ', t)
    else:
        self.assertProtoEquals('\n        dtype: DT_FLOAT\n        tensor_shape { dim { size: 1 } dim { size: 3 } }\n        tensor_content: "\\000\\000 A\\000\\000\\240A\\000\\000\\360A"\n        ', t)
    a = tensor_util.MakeNdarray(t)
    self.assertEqual(np.float32, a.dtype)
    self.assertAllClose(np.array([[10.0, 20.0, 30.0]], dtype=np.float32), a)

def callcrackfortran(files, options):
    rules.options = options
    crackfortran.debug = options['debug']
    crackfortran.verbose = options['verbose']
    if 'module' in options:
        crackfortran.f77modulename = options['module']
    if 'skipfuncs' in options:
        crackfortran.skipfuncs = options['skipfuncs']
    if 'onlyfuncs' in options:
        crackfortran.onlyfuncs = options['onlyfuncs']
    crackfortran.include_paths[:] = options['include_paths']
    crackfortran.dolowercase = options['do-lower']
    postlist = crackfortran.crackfortran(files)
    if 'signsfile' in options:
        outmess(f'''Saving signatures to file "{options['signsfile']}"\n''')
        pyf = crackfortran.crack2fortran(postlist)
        if options['signsfile'][-6:] == 'stdout':
            sys.stdout.write(pyf)
        else:
            with open(options['signsfile'], 'w') as f:
                f.write(pyf)
    if options['coutput'] is None:
        for mod in postlist:
            mod['coutput'] = f"{mod['name']}module.c"
    else:
        for mod in postlist:
            mod['coutput'] = options['coutput']
    if options['f2py_wrapper_output'] is None:
        for mod in postlist:
            mod['f2py_wrapper_output'] = f"{mod['name']}-f2pywrappers.f"
    else:
        for mod in postlist:
            mod['f2py_wrapper_output'] = options['f2py_wrapper_output']
    for mod in postlist:
        if <MASK>:
            mod['gil_used'] = 'Py_MOD_GIL_USED'
        else:
            mod['gil_used'] = 'Py_MOD_GIL_NOT_USED'
    crackfortran.f77modulename = ''
    return postlist

def float_to_apot(x, levels, indices, alpha):
    if x < -alpha:
        return -alpha
    elif <MASK>:
        return alpha
    levels_lst = list(levels)
    indices_lst = list(indices)
    min_delta = math.inf
    best_idx = 0
    for (level, idx) in zip(levels_lst, indices_lst):
        cur_delta = abs(level - x)
        if cur_delta < min_delta:
            min_delta = cur_delta
            best_idx = idx
    return best_idx

def body_contains(self, text):
    """
        Checks that ``text`` occurs in the email body and in all attached MIME
        type text/* alternatives.
        """
    if <MASK>:
        return False
    for (content, mimetype) in self.alternatives:
        if mimetype.startswith('text/') and text not in content:
            return False
    return True

def remove_graph_break_if_leaf_instructions(instructions: list[Instruction]) -> None:
    new_insts = []
    for (inst, next_inst) in itertools.pairwise(instructions):
        if <MASK>:
            for i in range(len(instructions)):
                if instructions[i].target is inst:
                    instructions[i].target = next_inst
                if instructions[i].exn_tab_entry:
                    if instructions[i].exn_tab_entry.start is inst:
                        instructions[i].exn_tab_entry.start = next_inst
                    if instructions[i].exn_tab_entry.end is inst:
                        instructions[i].exn_tab_entry.end = next_inst
                    if instructions[i].exn_tab_entry.target is inst:
                        instructions[i].exn_tab_entry.target = next_inst
        else:
            new_insts.append(inst)
    new_insts.append(instructions[-1])
    instructions[:] = new_insts

@symbolic_helper._overload_by_arg_count
def reduce(g, *args, **kwargs):

    @symbolic_helper.parse_args('v', 'none')
    def reduce_nodim(g, self, dtype):
        dtype_onnx = None
        if dtype.node().kind() == 'onnx::Constant':
            dtype = symbolic_helper._get_const(dtype, 'i', 'dtype')
            dtype_onnx = _type_utils.JitScalarType(dtype).onnx_type()
            self = g.op('Cast', self, to_i=dtype_onnx)
        elif dtype.node().kind() != 'prim::Constant':
            return symbolic_helper._unimplemented(name, 'dtype', dtype)
        result = symbolic(g, self)
        if dtype_onnx is not None:
            result_dtype_onnx = _type_utils.JitScalarType.from_value(result).onnx_type()
            if <MASK>:
                result = g.op('Cast', result, to_i=dtype_onnx)
        return result

    @symbolic_helper.parse_args('v', 'v', 'i', 'none')
    def reduce_dim(g, self, dim, keepdim, dtype):
        dtype_onnx = None
        if dtype.node().kind() == 'onnx::Constant':
            dtype = symbolic_helper._get_const(dtype, 'i', 'dtype')
            dtype_onnx = _type_utils.JitScalarType(dtype).onnx_type()
            self = g.op('Cast', self, to_i=dtype_onnx)
        elif dtype.node().kind() != 'prim::Constant':
            return symbolic_helper._unimplemented(name, 'dtype', dtype)
        result = symbolic(g, self, dim, keepdim)
        if dtype_onnx is not None:
            result_dtype_onnx = _type_utils.JitScalarType.from_value(result).onnx_type()
            if result_dtype_onnx != dtype_onnx:
                result = g.op('Cast', result, to_i=dtype_onnx)
        return result
    return (reduce_nodim, reduce_dim)

def visit_Subscript(self, node, **kwargs) -> ops.Term:
    value = self.visit(node.value)
    slobj = self.visit(node.slice)
    try:
        value = value.value
    except AttributeError:
        pass
    if <MASK>:
        slobj = slobj.value
    try:
        return self.const_type(value[slobj], self.env)
    except TypeError as err:
        raise ValueError(f'cannot subscript {value!r} with {slobj!r}') from err

def check_forward_ad_formula(op: Callable, args, kwargs, gradcheck_wrapper=None, assert_equal_fn=None):
    (CCT, cct_mode) = generate_cct_and_mode(autograd_view_consistency=False)

    def maybe_tangent(t):
        assert type(t) is not CCT
        if <MASK>:
            return torch.randn_like(t)
        elif is_tensorlist(t):
            return [torch.randn_like(e) if e.requires_grad else None for e in t]
        return None
    tangent_args = tuple((maybe_tangent(arg) for arg in args))
    (flat_kwargs, spec) = tree_flatten(kwargs)
    flat_tangent_kwargs = tuple((maybe_tangent(arg) for arg in flat_kwargs))
    tangent_kwargs = tree_unflatten(flat_tangent_kwargs, spec)
    with fwAD.dual_level():

        def maybe_make_dual(dual):
            (primal, tangent) = dual
            if isinstance(primal, torch.Tensor) and primal.requires_grad:
                return fwAD.make_dual(primal.detach(), tangent)
            elif is_tensorlist(primal):
                return tuple((fwAD.make_dual(pri.detach(), tang) if tang is not None else pri for (pri, tang) in zip(primal, tangent, strict=True)))
            return primal

        def compute_expected_grad(args, tangent_args, kwargs, tangent_kwargs):
            op_args = tuple(map(maybe_make_dual, zip(args, tangent_args, strict=True)))
            op_kwargs = {k: maybe_make_dual((v, tangent_kwargs[k])) for (k, v) in kwargs.items()}
            if gradcheck_wrapper is None:
                return op(*op_args, **op_kwargs)
            return gradcheck_wrapper(op, *op_args, **op_kwargs)
        expected = compute_expected_grad(args, tangent_args, kwargs, tangent_kwargs)
        expected = tree_map(fwAD.unpack_dual, expected)
        expected_primals = tree_map(lambda x: x.primal, expected, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
        expected_tangents = tree_map(lambda x: x.tangent, expected, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
        for choice in generate_subclass_choices_args_kwargs(args, kwargs, CCT, cct_mode):
            (new_args, new_kwargs, which_args_are_wrapped, which_kwargs_are_wrapped) = choice
            for tang_choice in generate_subclass_choices_args_kwargs(tangent_args, tangent_kwargs, CCT, cct_mode):
                (new_tang_args, new_tang_kwargs, which_tang_args_are_wrapped, which_tang_kwargs_are_wrapped) = tang_choice
                op_args = tuple(map(maybe_make_dual, zip(new_args, new_tang_args, strict=True)))
                op_kwargs = {k: maybe_make_dual((v, new_tang_kwargs[k])) for (k, v) in new_kwargs.items()}
                try:
                    if gradcheck_wrapper is None:
                        actual = op(*op_args, **op_kwargs)
                    else:
                        actual = gradcheck_wrapper(op, *op_args, **op_kwargs)
                except RuntimeError as err:
                    raise_composite_compliance_error(err, f'- wrapped_args: {which_args_are_wrapped}\n- wrapped_kwargs: {which_kwargs_are_wrapped}\n- wrapped_tangent_args: {which_tang_args_are_wrapped}\n- wrapped_tangent_kwargs: {which_tang_kwargs_are_wrapped}\n')

                def unwrap(e):
                    return e.elem if isinstance(e, CCT) else e
                actual = tree_map(fwAD.unpack_dual, actual)
                actual_primals = tree_map(lambda x: unwrap(x.primal), actual, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
                actual_tangents = tree_map(lambda x: unwrap(x.tangent), actual, is_leaf=lambda x: type(x) is fwAD.UnpackedDualTensor)
                assert_equal_fn(actual_primals, expected_primals, equal_nan=True)
                assert_equal_fn(actual_tangents, expected_tangents, equal_nan=True)

def trim_lex(tokens):
    """
    Takes a lexed set of tokens, and removes whitespace when there is
    a directive on a line by itself:

       >>> tokens = lex('{{if x}}\\nx\\n{{endif}}\\ny', trim_whitespace=False)
       >>> tokens
       [('if x', (1, 3)), '\\nx\\n', ('endif', (3, 3)), '\\ny']
       >>> trim_lex(tokens)
       [('if x', (1, 3)), 'x\\n', ('endif', (3, 3)), 'y']
    """
    last_trim = None
    for (i, current) in enumerate(tokens):
        if isinstance(current, basestring_):
            continue
        item = current[0]
        if not statement_re.search(item) and item not in single_statements:
            continue
        if not i:
            prev = ''
        else:
            prev = tokens[i - 1]
        if i + 1 >= len(tokens):
            next_chunk = ''
        else:
            next_chunk = tokens[i + 1]
        if not isinstance(next_chunk, basestring_) or not isinstance(prev, basestring_):
            continue
        prev_ok = not prev or trail_whitespace_re.search(prev)
        if <MASK>:
            prev_ok = True
        if last_trim is not None and last_trim + 2 == i and (not prev.strip()):
            prev_ok = 'last'
        if prev_ok and (not next_chunk or lead_whitespace_re.search(next_chunk) or (i == len(tokens) - 2 and (not next_chunk.strip()))):
            if prev:
                if i == 1 and (not prev.strip()) or prev_ok == 'last':
                    tokens[i - 1] = ''
                else:
                    m = trail_whitespace_re.search(prev)
                    prev = prev[:m.start() + 1]
                    tokens[i - 1] = prev
            if next_chunk:
                last_trim = i
                if i == len(tokens) - 2 and (not next_chunk.strip()):
                    tokens[i + 1] = ''
                else:
                    m = lead_whitespace_re.search(next_chunk)
                    next_chunk = next_chunk[m.end():]
                    tokens[i + 1] = next_chunk
    return tokens

@override
def reducer_override(self, obj: object) -> tuple[Callable[..., Any], tuple[Any, ...]]:
    if isinstance(obj, FakeTensor):
        return _TensorPickleData.reduce_helper(self, obj)
    elif isinstance(obj, torch.fx.GraphModule):
        return _GraphModulePickleData.reduce_helper(self, obj)
    elif <MASK>:
        return _OpPickleData.reduce_helper(self, obj)
    elif isinstance(obj, ShapeEnv):
        return _ShapeEnvPickleData.reduce_helper(self, obj)
    elif isinstance(obj, torch.SymInt):
        return _SymNodePickleData.reduce_helper(self, obj)
    elif isinstance(obj, torch._guards.TracingContext):
        return _TracingContextPickleData.reduce_helper(self, obj)
    else:
        assert not isinstance(obj, torch.fx.Node)
        if (reduce := _TorchNumpyPickleData.reduce_helper(self, obj)):
            return reduce
        return NotImplemented

def _next_data(self):
    while True:
        while self._rcvd_idx < self._send_idx:
            info = self._task_info.get(self._rcvd_idx, None)
            if <MASK>:
                worker_id = info[0]
                if len(info) == 2 or self._workers_status[worker_id]:
                    break
                del self._task_info[self._rcvd_idx]
            self._rcvd_idx += 1
        else:
            if not self._persistent_workers:
                self._shutdown_workers()
            raise StopIteration
        if len(self._task_info[self._rcvd_idx]) == 2:
            (worker_id, data) = self._task_info.pop(self._rcvd_idx)
            self._rcvd_idx += 1
            return self._process_data(data, worker_id)
        if self._shutdown or self._tasks_outstanding <= 0:
            raise AssertionError('Invalid iterator state: shutdown or no outstanding tasks when fetching next data')
        (idx, data) = self._get_data()
        self._tasks_outstanding -= 1
        if self._dataset_kind == _DatasetKind.Iterable:
            if isinstance(data, _utils.worker._IterableDatasetStopIteration):
                if self._persistent_workers:
                    self._workers_status[data.worker_id] = False
                else:
                    self._mark_worker_as_unavailable(data.worker_id)
                self._try_put_index()
                continue
        if idx != self._rcvd_idx:
            if not self._in_order:
                worker_id = self._task_info.pop(idx)[0]
                return self._process_data(data, worker_id)
            self._task_info[idx] += (data,)
        else:
            worker_id = self._task_info.pop(idx)[0]
            self._rcvd_idx += 1
            return self._process_data(data, worker_id)

def create_local_tensor_test_class(orig_cls, skipped_tests=None):
    if <MASK>:
        skipped_tests = []
    dct = orig_cls.__dict__.copy()
    for name in list(dct.keys()):
        fn = dct[name]
        if not callable(fn):
            continue
        elif name in skipped_tests:
            dct[name] = lambda self: self.skipTest('Skipped test')
        elif name.startswith('test_'):
            ctxs = [lambda test: test._get_local_tensor_mode()]
            dct[name] = make_wrapped(fn, ctxs)
    cls = type(orig_cls.__name__ + 'WithLocalTensor', (LocalDTensorTestBase,) + orig_cls.__bases__, dct)
    cls.__file__ = __file__
    return cls

def _is_match(modules, node, pattern, max_uses=sys.maxsize):
    """Matches a node in fx against a pattern"""
    if <MASK>:
        (self_match, *arg_matches) = pattern
        if self_match is getattr:
            assert len(pattern) == 2, 'Expecting getattr pattern to have two elements'
            arg_matches = []
    else:
        self_match = pattern
        arg_matches = []
    if isinstance(self_match, type) and issubclass(self_match, MatchAllNode):
        return True
    if node == pattern:
        return True
    if not isinstance(node, Node) or len(node.users) > max_uses:
        return False
    if isinstance(self_match, type) and issubclass(self_match, torch.nn.Module):
        if node.op != 'call_module':
            return False
        if type_before_parametrizations(modules[node.target]) != self_match:
            return False
    elif callable(self_match):
        if node.op != 'call_function' or node.target is not self_match:
            return False
        elif node.target is getattr:
            if node.args[1] != pattern[1]:
                return False
    elif isinstance(self_match, str):
        if node.op != 'call_method' or node.target != self_match:
            return False
    elif node.target != self_match:
        return False
    if not arg_matches:
        return True
    if len(arg_matches) != len(node.args):
        return False
    return all((_is_match(modules, node, arg_match, max_uses=1) for (node, arg_match) in zip(node.args, arg_matches)))

def get_default_qconfig(backend='x86', version=0):
    """
    Returns the default PTQ qconfig for the specified backend.

    Args:
      * `backend` (str): a string representing the target backend. Currently supports
        `x86` (default), `fbgemm`, `qnnpack` and `onednn`.

    Return:
        qconfig
    """
    supported_backends = ['fbgemm', 'x86', 'qnnpack', 'onednn']
    if backend not in supported_backends:
        raise AssertionError('backend: ' + str(backend) + f' not supported. backend must be one of {supported_backends}')
    if version == 0:
        if backend == 'fbgemm':
            qconfig = QConfig(activation=HistogramObserver.with_args(reduce_range=True), weight=default_per_channel_weight_observer)
        elif <MASK>:
            qconfig = QConfig(activation=HistogramObserver.with_args(reduce_range=False), weight=default_weight_observer)
        elif backend == 'onednn':
            if not torch.cpu._is_vnni_supported():
                warnings.warn('Default qconfig of oneDNN backend with reduce_range of false may have accuracy issues on CPU without Vector Neural Network Instruction support.')
            qconfig = QConfig(activation=HistogramObserver.with_args(reduce_range=False), weight=default_per_channel_weight_observer)
        elif backend == 'x86':
            qconfig = QConfig(activation=HistogramObserver.with_args(reduce_range=True), weight=default_per_channel_weight_observer)
        else:
            qconfig = default_qconfig
    else:
        raise AssertionError('Version number: ' + str(version) + ' in get_default_qconfig is not supported. Version number must be 0')
    return qconfig

def __repr__(self):
    repr_dtype = self.dtype
    if self.dtype.type is record or not issubclass(self.dtype.type, nt.void):
        if repr_dtype.type is record:
            repr_dtype = sb.dtype((nt.void, repr_dtype))
        prefix = 'rec.array('
        fmt = 'rec.array(%s,%sdtype=%s)'
    else:
        prefix = 'array('
        fmt = 'array(%s,%sdtype=%s).view(numpy.recarray)'
    if <MASK>:
        lst = sb.array2string(self, separator=', ', prefix=prefix, suffix=',')
    else:
        lst = f'[], shape={repr(self.shape)}'
    lf = '\n' + ' ' * len(prefix)
    if _get_legacy_print_mode() <= 113:
        lf = ' ' + lf
    return fmt % (lst, lf, repr_dtype)

def _numpy_compatible_indexing(index):
    """Convert scalar indices to lists when advanced indexing is present for NumPy compatibility."""
    if <MASK>:
        index = (index,)
    has_advanced = _has_advanced_indexing(index)
    if not has_advanced:
        return index
    converted = []
    for idx in index:
        if isinstance(idx, int) and (not isinstance(idx, bool)):
            converted.append([idx])
        elif isinstance(idx, torch.Tensor) and idx.ndim == 0 and (not torch.is_floating_point(idx)) and (idx.dtype != torch.bool):
            converted.append([idx])
        else:
            converted.append(idx)
    return tuple(converted)

