def __getitem__(self, item: PositionalIndexer):
    """Select a subset of self.

        Parameters
        ----------
        item : int, slice, or ndarray
            * int: The position in 'self' to get.
            * slice: A slice object, where 'start', 'stop', and 'step' are
              integers or None
            * ndarray: A 1-d boolean NumPy ndarray the same length as 'self'

        Returns
        -------
        item : scalar or ExtensionArray

        Notes
        -----
        For scalar ``item``, return a scalar value suitable for the array's
        type. This should be an instance of ``self.dtype.type``.
        For slice ``key``, return an instance of ``ExtensionArray``, even
        if the slice is length 0 or 1.
        For a boolean mask, return an instance of ``ExtensionArray``, filtered
        to the values where ``item`` is True.
        """
    item = check_array_indexer(self, item)
    if isinstance(item, np.ndarray):
        if not len(item):
            if isinstance(self._dtype, StringDtype) and self._dtype.storage == 'pyarrow':
                pa_dtype = pa.string()
            else:
                pa_dtype = self._dtype.pyarrow_dtype
            result = pa.chunked_array([], type=pa_dtype)
            return self._from_pyarrow_array(result)
        elif item.dtype.kind in 'iu':
            return self.take(item)
        elif item.dtype.kind == 'b':
            return self._from_pyarrow_array(self._pa_array.filter(item))
        else:
            raise IndexError('Only integers, slices and integer or boolean arrays are valid indices.')
    elif isinstance(item, tuple):
        item = unpack_tuple_and_ellipses(item)
    if item is Ellipsis:
        item = slice(None)
    if is_scalar(item) and (not is_integer(item)):
        raise IndexError('only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) and integer or boolean arrays are valid indices')
    if isinstance(item, slice):
        if item.start == item.stop:
            pass
        elif item.stop is not None and item.stop < -len(self) and (item.step is not None) and (item.step < 0):
            item = slice(item.start, None, item.step)
    value = self._pa_array[item]
    if isinstance(value, pa.ChunkedArray):
        return self._from_pyarrow_array(value)
    else:
        pa_type = self._pa_array.type
        scalar = value.as_py()
        if <MASK>:
            return self._dtype.na_value
        elif pa.types.is_timestamp(pa_type) and pa_type.unit != 'ns':
            return Timestamp(scalar).as_unit(pa_type.unit)
        elif pa.types.is_duration(pa_type) and pa_type.unit != 'ns':
            return Timedelta(scalar).as_unit(pa_type.unit)
        else:
            return scalar

def get_summary_op():
    """Returns a single Summary op that would run all summaries.

  Either existing one from `SUMMARY_OP` collection or merges all existing
  summaries.

  Returns:
    If no summaries were collected, returns None. Otherwise returns a scalar
    `Tensor` of type `string` containing the serialized `Summary` protocol
    buffer resulting from the merging.
  """
    summary_op = ops.get_collection(ops.GraphKeys.SUMMARY_OP)
    if <MASK>:
        if summary_op:
            summary_op = summary_op[0]
        else:
            summary_op = None
    if summary_op is None:
        summary_op = merge_all_summaries()
        if summary_op is not None:
            ops.add_to_collection(ops.GraphKeys.SUMMARY_OP, summary_op)
    return summary_op

