    return dict(list(base_config.items()) + list(config.items()))

def var_getattr(self, tx: 'InstructionTranslator', name):

    def check_and_create_method():
        method = inspect.getattr_static(self.tuple_cls, name, None)
        if isinstance(method, classmethod):
            return UserMethodVariable(method.__func__, variables.UserDefinedClassVariable(self.tuple_cls))
        elif isinstance(method, staticmethod):
            return UserFunctionVariable(method.__func__)
        elif inspect.isfunction(method):
            return UserMethodVariable(method, self)
        else:
            return None
    if name == '_replace' and (not self._is_method_overridden('_replace')) and (not self._is_method_overridden('__getattr__')):
        actual_replace_method = getattr(self.tuple_cls, '_replace', None)
        if actual_replace_method:
            from ..source import AttrSource
            source = AttrSource(self.source, name) if self.source else None
            return variables.GetAttrVariable(self, name, source=source)
        return super().var_getattr(tx, name)
    if name == '_fields':
        source = NamedTupleFieldsSource(self.source) if self.source else None
        return VariableTracker.build(tx, self.fields(), source=source)
    if name in self.dynamic_attributes:
        return self.dynamic_attributes[name]
    fields = self.fields()
    if name not in fields:
        method = check_and_create_method()
        if <MASK>:
            return super().var_getattr(tx, name)
        return method
    return self.items[fields.index(name)]

def embedding_lookup_sparse_impl(params, segment_ids, sp_weights, ids, combiner, ignore_weights, max_norm, allow_fast_lookup, partition_strategy, name):
    """Implementation of sparse embedding aggregation."""
    need_sparse_segment_gradient = False
    segment_ids = ops.convert_to_tensor(segment_ids, name='segment_ids')
    if len(params) == 1 and (not isinstance(params[0], (core.Tensor, composite_tensor.CompositeTensor))):
        params = [ops.convert_to_tensor(params[0], name='params')]
    if len(params) == 1 and (not isinstance(params[0], composite_tensor.CompositeTensor)) and (params[0].device == segment_ids.device) and (max_norm is None) and (allow_fast_lookup or (ignore_weights and compat.forward_compatible(2023, 9, 26))):
        idx = ids
        embeddings = params[0]
        if isinstance(embeddings, resource_variable_ops.BaseResourceVariable):
            embeddings = embeddings.read_value_no_copy()
        if not allow_fast_lookup:
            need_sparse_segment_gradient = True
    else:
        (ids, idx) = array_ops.unique(ids)
        embeddings = embedding_lookup(params, ids, partition_strategy=partition_strategy, max_norm=max_norm)
    if not ignore_weights:
        if segment_ids.dtype != dtypes.int32:
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        weights = sp_weights.values
        embeddings = array_ops.gather(embeddings, idx)
        original_dtype = embeddings.dtype
        if embeddings.dtype in (dtypes.float16, dtypes.bfloat16):
            embeddings = math_ops.cast(embeddings, dtypes.float32)
        if weights.dtype != embeddings.dtype:
            weights = math_ops.cast(weights, embeddings.dtype)
        ones_shape = array_ops.expand_dims(array_ops.rank(embeddings) - 1, 0)
        weights_shape = array_ops.shape(weights)
        ones = array_ops.ones(ones_shape, dtype=weights_shape.dtype)
        bcast_weights_shape = array_ops.concat([weights_shape, ones], 0)
        orig_weights_shape = weights.get_shape()
        weights = array_ops.reshape(weights, bcast_weights_shape)
        if embeddings.get_shape().ndims is not None:
            weights.set_shape(orig_weights_shape.concatenate([1 for _ in range(embeddings.get_shape().ndims - 1)]))
        embeddings *= weights
        if combiner == 'sum':
            embeddings = math_ops.segment_sum(embeddings, segment_ids, name=name)
        elif <MASK>:
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weight_sum = math_ops.segment_sum(weights, segment_ids)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum, name=name)
        elif combiner == 'sqrtn':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weights_squared = math_ops.pow(weights, 2)
            weight_sum = math_ops.segment_sum(weights_squared, segment_ids)
            weight_sum_sqrt = math_ops.sqrt(weight_sum)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum_sqrt, name=name)
        else:
            assert False, 'Unrecognized combiner'
        if embeddings.dtype != original_dtype:
            embeddings = math_ops.cast(embeddings, original_dtype)
    else:
        if segment_ids.dtype not in (dtypes.int32, dtypes.int64):
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        assert idx is not None
        if combiner == 'sum':
            embeddings = math_ops.sparse_segment_sum(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'mean':
            embeddings = math_ops.sparse_segment_mean(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'sqrtn':
            embeddings = math_ops.sparse_segment_sqrt_n(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        else:
            assert False, 'Unrecognized combiner'
    return embeddings

def testMinMax(self):
    for datatype_enum in types_pb2.DataType.values():
        if not _is_numeric_dtype_enum(datatype_enum):
            continue
        dtype = dtypes.as_dtype(datatype_enum)
        numpy_dtype = dtype.as_numpy_dtype
        if dtype.is_quantized or dtype.base_dtype == dtypes.bool or dtype.base_dtype == dtypes.string or (dtype.base_dtype == dtypes.complex64) or (dtype.base_dtype == dtypes.complex128):
            continue
        print('%s: %s - %s' % (dtype, dtype.min, dtype.max))
        if numpy_dtype == np.bool_:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 1)
        if numpy_dtype == np.int8:
            self.assertEqual(dtype.min, -128)
            self.assertEqual(dtype.max, 127)
        if numpy_dtype == np.int16:
            self.assertEqual(dtype.min, -32768)
            self.assertEqual(dtype.max, 32767)
        if numpy_dtype == np.int32:
            self.assertEqual(dtype.min, -2147483648)
            self.assertEqual(dtype.max, 2147483647)
        if numpy_dtype == np.int64:
            self.assertEqual(dtype.min, -9223372036854775808)
            self.assertEqual(dtype.max, 9223372036854775807)
        if numpy_dtype == np.uint8:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 255)
        if numpy_dtype == np.uint16:
            if dtype == dtypes.uint16:
                self.assertEqual(dtype.min, 0)
                self.assertEqual(dtype.max, 65535)
            elif dtype == dtypes.bfloat16:
                self.assertEqual(dtype.min, 0)
                self.assertEqual(dtype.max, 4294967295)
        if numpy_dtype == np.uint32:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 4294967295)
        if numpy_dtype == np.uint64:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 18446744073709551615)
        if numpy_dtype in (np.float16, np.float32, np.float64):
            self.assertEqual(dtype.min, np.finfo(numpy_dtype).min)
            self.assertEqual(dtype.max, np.finfo(numpy_dtype).max)
        if numpy_dtype == dtypes.bfloat16.as_numpy_dtype:
            self.assertEqual(dtype.min, float.fromhex('-0x1.FEp127'))
            self.assertEqual(dtype.max, float.fromhex('0x1.FEp127'))
        if <MASK>:
            self.assertEqual(dtype.min, -57344.0)
            self.assertEqual(dtype.max, 57344.0)
        if numpy_dtype == dtypes.float8_e4m3fn.as_numpy_dtype:
            self.assertEqual(dtype.min, -448.0)
            self.assertEqual(dtype.max, 448.0)
        if numpy_dtype == dtypes.float8_e4m3fnuz.as_numpy_dtype:
            self.assertEqual(dtype.min, -240.0)
            self.assertEqual(dtype.max, 240.0)
        if numpy_dtype == dtypes.float8_e4m3b11fnuz.as_numpy_dtype:
            self.assertEqual(dtype.min, -30.0)
            self.assertEqual(dtype.max, 30.0)
        if numpy_dtype == dtypes.float8_e5m2fnuz.as_numpy_dtype:
            self.assertEqual(dtype.min, -57344.0)
            self.assertEqual(dtype.max, 57344.0)
        if numpy_dtype == dtypes.int4.as_numpy_dtype:
            self.assertEqual(dtype.min, -8)
            self.assertEqual(dtype.max, 7)
        if numpy_dtype == dtypes.uint4.as_numpy_dtype:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 15)
        if numpy_dtype == dtypes.int2.as_numpy_dtype:
            self.assertEqual(dtype.min, -2)
            self.assertEqual(dtype.max, 1)
        if numpy_dtype == dtypes.uint2.as_numpy_dtype:
            self.assertEqual(dtype.min, 0)
            self.assertEqual(dtype.max, 3)

def union_indexes(indexes, sort: bool | None=True) -> Index:
    """
    Return the union of indexes.

    The behavior of sort and names is not consistent.

    Parameters
    ----------
    indexes : list of Index or list objects
    sort : bool, default True
        Whether the result index should come out sorted or not.

    Returns
    -------
    Index
    """
    if len(indexes) == 0:
        raise AssertionError('Must have at least 1 Index to union')
    if len(indexes) == 1:
        result = indexes[0]
        if isinstance(result, list):
            if not sort:
                result = Index(result)
            else:
                result = Index(sorted(result))
        return result
    (indexes, kind) = _sanitize_and_check(indexes)
    if kind == 'special':
        result = indexes[0]
        num_dtis = 0
        num_dti_tzs = 0
        for idx in indexes:
            if isinstance(idx, DatetimeIndex):
                num_dtis += 1
                if idx.tz is not None:
                    num_dti_tzs += 1
        if num_dti_tzs not in [0, num_dtis]:
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
        if num_dtis == len(indexes):
            sort = True
            result = indexes[0]
        elif num_dtis > 1:
            sort = False
            indexes = [x.astype(object, copy=False) for x in indexes]
            result = indexes[0]
        for other in indexes[1:]:
            result = result.union(other, sort=None if sort else False)
        return result
    elif kind == 'array':
        if <MASK>:
            dtype = find_common_type([idx.dtype for idx in indexes])
            inds = [ind.astype(dtype, copy=False) for ind in indexes]
            index = inds[0].unique()
            other = inds[1].append(inds[2:])
            diff = other[index.get_indexer_for(other) == -1]
            if len(diff):
                index = index.append(diff.unique())
            if sort:
                index = index.sort_values()
        else:
            index = indexes[0]
        name = get_unanimous_names(*indexes)[0]
        if name != index.name:
            index = index.rename(name)
        return index
    elif kind == 'list':
        dtypes = [idx.dtype for idx in indexes if isinstance(idx, Index)]
        if dtypes:
            dtype = find_common_type(dtypes)
        else:
            dtype = None
        all_lists = (idx.tolist() if isinstance(idx, Index) else idx for idx in indexes)
        return Index(lib.fast_unique_multiple_list_gen(all_lists, sort=bool(sort)), dtype=dtype)
    else:
        raise ValueError(f"kind={kind!r} must be 'special', 'array' or 'list'.")

def _check_single_backend_availability(backend_name: str) -> bool:
    """
    Helper function to check if a single backend is available.
    """
    available_func = getattr(torch.distributed, f'is_{str(backend_name).lower()}_available', None)
    if <MASK>:
        return available_func()
    return str(backend_name).lower() in Backend.backend_list

def load_from_library(library, label, names):
    """
    Return a subset of tags and filters from a library.
    """
    subset = Library()
    for name in names:
        found = False
        if name in library.tags:
            found = True
            subset.tags[name] = library.tags[name]
        if <MASK>:
            found = True
            subset.filters[name] = library.filters[name]
        if found is False:
            raise TemplateSyntaxError("'%s' is not a valid tag or filter in tag library '%s'" % (name, label))
    return subset

def alpha_dropout(input: Tensor, p: float=0.5, training: bool=False, inplace: bool=False) -> Tensor:
    """Apply alpha dropout to the input.

    See :class:`~torch.nn.AlphaDropout` for details.
    """
    if has_torch_function_unary(input):
        return handle_torch_function(alpha_dropout, (input,), input, p=p, training=training, inplace=inplace)
    if <MASK>:
        raise ValueError(f'dropout probability has to be between 0 and 1, but got {p}')
    return _VF.alpha_dropout_(input, p, training) if inplace else _VF.alpha_dropout(input, p, training)

