def nargminmax(values: ExtensionArray, method: str, axis: AxisInt=0):
    """
    Implementation of np.argmin/argmax but for ExtensionArray and which
    handles missing values.

    Parameters
    ----------
    values : ExtensionArray
    method : {"argmax", "argmin"}
    axis : int, default 0

    Returns
    -------
    int
    """
    assert method in {'argmax', 'argmin'}
    func = np.argmax if method == 'argmax' else np.argmin
    mask = np.asarray(isna(values))
    arr_values = values._values_for_argsort()
    if <MASK>:
        if mask.any():
            if axis == 1:
                zipped = zip(arr_values, mask, strict=True)
            else:
                zipped = zip(arr_values.T, mask.T, strict=True)
            return np.array([_nanargminmax(v, m, func) for (v, m) in zipped])
        return func(arr_values, axis=axis)
    return _nanargminmax(arr_values, mask, func)

def _handle_aggregate(ty) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:

    def dump_type(t, level: int) -> tuple[str, str, str]:
        if getattr(t, '__name__', None) in cpp_enum_defs:
            return (t.__name__, 'int64_t', t.__name__)
        elif t in _CPP_TYPE_MAP:
            return (t.__name__, _CPP_TYPE_MAP[t], _THRIFT_TYPE_MAP[t])
        elif isinstance(t, str):
            assert t in defs
            assert t not in cpp_enum_defs
            assert '[' not in t
            return (t, f'ForwardRef<{t}>', t)
        elif isinstance(t, ForwardRef):
            return (t.__forward_arg__, f'ForwardRef<{t.__forward_arg__}>', t.__forward_arg__)
        elif (o := typing.get_origin(t)):
            if o is list:
                (yaml_head, cpp_head, thrift_head, thrift_tail) = ('List', 'std::vector', 'list<', '>')
            elif o is dict:
                (yaml_head, cpp_head, thrift_head, thrift_tail) = ('Dict', 'std::unordered_map', 'map<', '>')
            elif o == Union:
                assert level == 0, 'Optional is only supported at the top level.'
                args = typing.get_args(t)
                assert len(args) == 2 and args[1] is type(None)
                (yaml_type, cpp_type, thrift_type) = dump_type(args[0], level + 1)
                return (f'Optional[{yaml_type}]', f'std::optional<{cpp_type}>', f'optional {thrift_type}')
            elif o == Annotated:
                return dump_type(t.__origin__, level)
            else:
                raise AssertionError(f'Type {t} is not supported in export schema.')
            (yaml_arg_types, cpp_arg_types, thrift_arg_types) = zip(*[dump_type(x, level + 1) for x in typing.get_args(t)])
            return (f"{yaml_head}[{', '.join(yaml_arg_types)}]", f"{cpp_head}<{', '.join(cpp_arg_types)}>", f"{thrift_head}{', '.join(thrift_arg_types)}{thrift_tail}")
        elif isinstance(t, type):
            return (t.__name__, t.__name__, t.__name__)
        else:
            raise AssertionError(f'Type {t} is not supported in export schema.')

    def dump_cpp_value(v) -> str:
        if v is None:
            return 'std::nullopt'
        elif v is True:
            return 'true'
        elif v is False:
            return 'false'
        elif v == {}:
            return '{}'
        elif v == []:
            return '{}'
        elif <MASK>:
            return '{}'
        elif isinstance(v, str):
            return f'"{v}"'
        else:
            raise AssertionError(f'Default value {v} is not supported yet in export schema.')

    def dump_field(f) -> tuple[dict[str, Any], str, Optional[str], str, int]:
        (t, cpp_type, thrift_type) = dump_type(f.type, 0)
        ret = {'type': t}
        cpp_default: Optional[str] = None
        assert typing.get_origin(f.type) == Annotated, f'Field {f.name} must be annotated with an integer id.'
        thrift_id = f.type.__metadata__[0]
        assert type(thrift_id) is int, f'Field {f.name} must be annotated with an integer id.'
        value = dataclasses.MISSING
        if f.default is not dataclasses.MISSING:
            value = f.default
        elif f.default_factory is not dataclasses.MISSING:
            value = f.default_factory()
        if value is not dataclasses.MISSING:
            default = str(value)
            ret['default'] = default
            cpp_default = dump_cpp_value(value)
            if t.startswith('Optional[') and value is not None:
                raise AssertionError(f'Optional field {ty.__name__}.{f.name} must have default value to be None.')
        return (ret, cpp_type, cpp_default, thrift_type, thrift_id)
    yaml_ret = {}
    cpp_ret = {}
    thrift_ret = {}
    thrift_ids = set()
    for f in dataclasses.fields(ty):
        (yaml_res, cpp_type, cpp_default, thrift_type, thrift_id) = dump_field(f)
        yaml_ret[f.name] = yaml_res
        cpp_ret[f.name] = {'cpp_type': cpp_type, 'cpp_default': cpp_default}
        thrift_ret[f.name] = {'thrift_type': thrift_type, 'thrift_id': thrift_id}
        if thrift_id in thrift_ids:
            raise AssertionError(f'Duplicate thrift id {thrift_id} for field {f.name} in {ty.__name__}.')
        thrift_ids.add(thrift_id)
    return (yaml_ret, cpp_ret, thrift_ret)

def _yield_all_checks(estimator, legacy: bool):
    name = estimator.__class__.__name__
    tags = get_tags(estimator)
    if not tags.input_tags.two_d_array:
        warnings.warn("Can't test estimator {} which requires input  of type {}".format(name, tags.input_tags), SkipTestWarning)
        return
    if tags._skip_test:
        warnings.warn('Explicit SKIP via _skip_test tag for estimator {}.'.format(name), SkipTestWarning)
        return
    for check in _yield_api_checks(estimator):
        yield check
    if not legacy:
        return
    for check in _yield_checks(estimator):
        yield check
    if is_classifier(estimator):
        for check in _yield_classifier_checks(estimator):
            yield check
    if is_regressor(estimator):
        for check in _yield_regressor_checks(estimator):
            yield check
    if hasattr(estimator, 'transform'):
        for check in _yield_transformer_checks(estimator):
            yield check
    if <MASK>:
        for check in _yield_clustering_checks(estimator):
            yield check
    if is_outlier_detector(estimator):
        for check in _yield_outliers_checks(estimator):
            yield check
    yield check_parameters_default_constructible
    if not tags.non_deterministic:
        yield check_methods_sample_order_invariance
        yield check_methods_subset_invariance
    yield check_fit2d_1sample
    yield check_fit2d_1feature
    yield check_get_params_invariance
    yield check_set_params
    yield check_dict_unchanged
    yield check_fit_idempotent
    yield check_fit_check_is_fitted
    if not tags.no_validation:
        yield check_n_features_in
        yield check_fit1d
        yield check_fit2d_predict1d
        if tags.target_tags.required:
            yield check_requires_y_none
    if tags.input_tags.positive_only:
        yield check_fit_non_negative

def compute_jacobian_preallocate_and_copy():
    out_vec_size = sum(flat_output_numels)
    if not (chunk_size is None or chunk_size >= out_vec_size):
        stacked_results = [primal.new_zeros(out_vec_size, *primal.shape) for primal in flat_primals]
    for (idx, flat_basis_chunk) in enumerate(_chunked_standard_basis_for_(flat_output, flat_output_numels, chunk_size=chunk_size)):
        if <MASK>:
            for t in flat_basis_chunk:
                assert t.size(0) == 1
            flat_basis_chunk = [torch.squeeze(t, 0) for t in flat_basis_chunk]
        basis = tree_unflatten(flat_basis_chunk, output_spec)
        if chunk_size == 1:
            chunked_result = vjp_fn(basis)
        else:
            chunked_result = vmap(vjp_fn)(basis)
        flat_results = pytree.tree_leaves(chunked_result)
        if chunk_size is None or chunk_size >= out_vec_size:
            if chunk_size == 1:
                flat_results = tree_map(lambda t: torch.unsqueeze(t, 0), flat_results)
            return flat_results
        for (r, sr) in zip(flat_results, stacked_results):
            sr[idx * chunk_size:(idx + 1) * chunk_size].copy_(r)
    return stacked_results

def _get_summary_signatures(self):
    """Verifies and returns the summary signatures.

    Returns:
      A dictionary of the signature identifiers {signature: index} that will be
      computed when trace_mode is summary.
    """
    signatures = self._flag_value_as_list(FLAG_NAME_SUMMARY_SIGNATURES)
    supported_signatures = self._supported_signatures()
    tt_signatures = []
    for signature in signatures:
        signature_with_prefix = '%s_%s' % (_TT_PREFIX, signature)
        if <MASK>:
            tt_signatures.append(signature)
        elif signature_with_prefix in supported_signatures:
            tt_signatures.append(signature_with_prefix)
        else:
            logging.warning('Unknown signature:%s. Supported signatures: %s' % (signature, supported_signatures))
    if not tt_signatures:
        return {TT_SUMMARY_MAX_ABS: 0, TT_SUMMARY_NORM: 1}
    else:
        return {signature: idx for (idx, signature) in enumerate(tt_signatures)}

