def create_micro_gemm(name, m, n, k, input_dtype, input2_dtype, output_dtype=None, compute_dtype=None, alpha=1, num_threads=-1, use_ref=True, q_group_size=None) -> Optional[CppMicroGemm]:
    """
    Based on the provided info, try to find the config of the micro-kernel that would
    deliver the best performance in terms of lower latency for this case.
    """

    def create_from_config(cls, config: CppMicroGemmConfig):
        return cls(name, config.input_dtype, config.input2_dtype, config.output_dtype, config.compute_dtype, config.register_blocking, alpha)

    def skip_amx_kernel_for_woq(dynamic_M):
        if dynamic_M or input_dtype != torch.bfloat16 or input2_dtype not in [torch.int8, torch.uint8]:
            return False
        m_threshold = 5
        return m < m_threshold
    assert isinstance(n, int) or n.is_number, n
    assert isinstance(k, int) or k.is_number, k
    from ..utils import has_free_symbols
    dynamic_M = has_free_symbols((m,))
    m = V.graph.sizevars.size_hint(m, fallback=1) if dynamic_M else m
    assert isinstance(m, int) or m.is_number, m
    if output_dtype is None:
        output_dtype = input_dtype
    if compute_dtype is None:
        compute_dtype = output_dtype
    if num_threads < 0:
        num_threads = parallel_num_threads()
    vec_isa = pick_vec_isa()
    matched_configs = []
    for (cls, configs) in micro_gemm_configs.items():
        for config in configs:
            if not issubclass(vec_isa.__class__, config.vec_isa_cls):
                continue
            if config.input_dtype == input_dtype and config.compute_dtype == compute_dtype and (config.input2_dtype == input2_dtype) and (config.output_dtype == output_dtype):
                if config.extra_check is not None and (not config.extra_check(config, m, n, k, alpha, num_threads, dynamic_M=dynamic_M, q_group_size=q_group_size, vec_isa=vec_isa)):
                    continue
                (block_m, block_n, block_k) = config.register_blocking
                if config.vec_isa_cls == VecAMX and skip_amx_kernel_for_woq(dynamic_M):
                    continue
                isa_score = 0
                if <MASK>:
                    isa_score += 1
                dividable_score = 0
                if m % block_m == 0:
                    dividable_score += 1
                if n % block_n == 0:
                    dividable_score += 1
                if k % block_k == 0:
                    dividable_score += 1
                occupancy_score = 0
                n_blocks = (n + block_n - 1) // block_n
                total_mxn_blocks = n_blocks * ((m + block_m - 1) // block_m)
                if n_blocks >= num_threads:
                    occupancy_score += 1
                if total_mxn_blocks >= num_threads:
                    occupancy_score += 1
                register_bytes = block_m * block_n * config.compute_dtype.itemsize + (block_m * block_k + block_k * block_n) * config.input_dtype.itemsize
                size_score = register_bytes
                if occupancy_score == 0:
                    size_score = 0 - register_bytes
                matched_configs.append(((isa_score, dividable_score, occupancy_score, size_score), cls, config))
    if len(matched_configs) == 0:
        if use_ref:
            return CppMicroGemmRef(name, input_dtype, input2_dtype, output_dtype, compute_dtype, alpha)
        else:
            return None
    return create_from_config(*max(matched_configs, key=operator.itemgetter(0))[1:])

@test_util.run_without_tensor_float_32('Tests matmul')
def Test(self):
    if <MASK>:
        self.skipTest('Skipping infeasible gradient test.')
    if a_np_.dtype == dtypes.bfloat16.as_numpy_dtype and (not test_util.is_gpu_available()):
        self.skipTest('The bfloat16 tests might fail on CPU')
    effective_a_np = _GetTransposedMatrices(a_np_, 'a', kwargs_)
    effective_b_np = _GetTransposedMatrices(b_np_, 'b', kwargs_)
    if a_np_.dtype == dtypes.bfloat16.as_numpy_dtype:
        epsilon = 0.0078125
    else:
        epsilon = np.finfo(a_np_.dtype).eps
    delta = epsilon ** (1.0 / 3.0)
    tol = 20 * delta
    with self.session():
        (theoretical, numerical) = gradient_checker_v2.compute_gradient(lambda x: math_ops.matmul(x, effective_b_np, **kwargs_), [effective_a_np], delta=delta)
        self.assertAllClose(theoretical, numerical, rtol=tol, atol=tol)
        (theoretical, numerical) = gradient_checker_v2.compute_gradient(lambda x: math_ops.matmul(effective_a_np, x, **kwargs_), [effective_b_np], delta=delta)
        self.assertAllClose(theoretical, numerical, rtol=tol, atol=tol)

