    assert self._dict is not None
    return self._dict

def _worker_loop(dataset_kind, dataset, index_queue, data_queue, done_event, auto_collation, collate_fn, drop_last, base_seed, init_fn, worker_id, num_workers, persistent_workers, shared_seed):
    try:
        signal_handling._set_worker_signal_handlers()
        torch.multiprocessing._set_thread_name('pt_data_worker')
        torch.set_num_threads(1)
        seed = base_seed + worker_id
        random.seed(seed)
        torch.manual_seed(seed)
        if HAS_NUMPY:
            np_seed = _generate_state(base_seed, worker_id)
            import numpy as np
            np.random.seed(np_seed)
        from torch.utils.data import IterDataPipe
        from torch.utils.data.graph_settings import apply_random_seed
        shared_rng = torch.Generator()
        if isinstance(dataset, IterDataPipe):
            if shared_seed is None:
                raise AssertionError('shared_seed must be provided for IterDataPipe workers')
            shared_rng.manual_seed(shared_seed)
            dataset = apply_random_seed(dataset, shared_rng)
        global _worker_info
        _worker_info = WorkerInfo(id=worker_id, num_workers=num_workers, seed=seed, dataset=dataset)
        from torch.utils.data import _DatasetKind
        init_exception = None
        try:
            if <MASK>:
                init_fn(worker_id)
            fetcher = _DatasetKind.create_fetcher(dataset_kind, dataset, auto_collation, collate_fn, drop_last)
        except Exception:
            init_exception = ExceptionWrapper(where=f'in DataLoader worker process {worker_id}')
        iteration_end = False
        watchdog = ManagerWatchdog()
        while watchdog.is_alive():
            try:
                r = index_queue.get(timeout=MP_STATUS_CHECK_INTERVAL)
            except queue.Empty:
                continue
            if isinstance(r, _ResumeIteration):
                data_queue.put((r, None))
                iteration_end = False
                if isinstance(dataset, IterDataPipe):
                    if r.seed is None:
                        raise AssertionError('resume iteration seed is None for IterDataPipe')
                    shared_rng.manual_seed(r.seed)
                    dataset = apply_random_seed(dataset, shared_rng)
                fetcher = _DatasetKind.create_fetcher(dataset_kind, dataset, auto_collation, collate_fn, drop_last)
                continue
            elif r is None:
                if not done_event.is_set() and (not iteration_end):
                    raise AssertionError('Received final signal but neither done_event nor iteration_end is set')
                break
            elif done_event.is_set() or iteration_end:
                continue
            (idx, index) = r
            data: Union[_IterableDatasetStopIteration, ExceptionWrapper]
            if init_exception is not None:
                data = init_exception
                init_exception = None
            else:
                try:
                    data = fetcher.fetch(index)
                except Exception as e:
                    if isinstance(e, StopIteration) and dataset_kind == _DatasetKind.Iterable:
                        data = _IterableDatasetStopIteration(worker_id)
                        iteration_end = True
                    else:
                        data = ExceptionWrapper(where=f'in DataLoader worker process {worker_id}')
            data_queue.put((idx, data))
            del data, idx, index, r
    except KeyboardInterrupt:
        pass
    if done_event.is_set():
        data_queue.cancel_join_thread()
        data_queue.close()

def as_factors(obj):
    """Return expression as FACTORS expression.
    """
    if isinstance(obj, Expr):
        obj = normalize(obj)
        if <MASK>:
            return obj
        if obj.op is Op.TERMS:
            if len(obj.data) == 1:
                ((term, coeff),) = obj.data.items()
                if coeff == 1:
                    return Expr(Op.FACTORS, {term: 1})
                return Expr(Op.FACTORS, {term: 1, Expr.number(coeff): 1})
        if obj.op is Op.APPLY and obj.data[0] is ArithOp.DIV and (not obj.data[2]):
            return Expr(Op.FACTORS, {obj.data[1][0]: 1, obj.data[1][1]: -1})
        return Expr(Op.FACTORS, {obj: 1})
    raise OpError(f'cannot convert {type(obj)} to terms Expr')

def _log_signature_report(signature_def_map, excluded_signatures):
    """Log a report of which signatures were produced."""
    sig_names_by_method_name = collections.defaultdict(list)
    for method_name in _FRIENDLY_METHOD_NAMES:
        sig_names_by_method_name[method_name] = []
    for (signature_name, sig) in signature_def_map.items():
        sig_names_by_method_name[sig.method_name].append(signature_name)
    for (method_name, sig_names) in sig_names_by_method_name.items():
        if <MASK>:
            method_name = _FRIENDLY_METHOD_NAMES[method_name]
        logging.info('Signatures INCLUDED in export for {}: {}'.format(method_name, sig_names if sig_names else 'None'))
    if excluded_signatures:
        logging.info('Signatures EXCLUDED from export because they cannot be be served via TensorFlow Serving APIs:')
        for (signature_name, message) in excluded_signatures.items():
            logging.info("'{}' : {}".format(signature_name, message))
    if not signature_def_map:
        logging.warn('Export includes no signatures!')
    elif signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY not in signature_def_map:
        logging.warn('Export includes no default signature!')

def is_compatible_with(self, spec_or_value):
