def _get_ufunc_and_otypes(self, func, args):
    """Return (ufunc, otypes)."""
    if not args:
        raise ValueError('args can not be empty')
    if self.otypes is not None:
        otypes = self.otypes
        nin = len(args)
        nout = len(self.otypes)
        if func is not self.pyfunc or nin not in self._ufunc:
            ufunc = frompyfunc(func, nin, nout)
        else:
            ufunc = None
        if func is self.pyfunc:
            ufunc = self._ufunc.setdefault(nin, ufunc)
    else:
        args = [asarray(a) for a in args]
        if builtins.any((arg.size == 0 for arg in args)):
            raise ValueError('cannot call `vectorize` on size 0 inputs unless `otypes` is set')
        inputs = [arg.flat[0] for arg in args]
        outputs = func(*inputs)
        if self.cache:
            _cache = [outputs]

            def _func(*vargs):
                if _cache:
                    return _cache.pop()
                else:
                    return func(*vargs)
        else:
            _func = func
        if <MASK>:
            nout = len(outputs)
        else:
            nout = 1
            outputs = (outputs,)
        otypes = ''.join([asarray(outputs[_k]).dtype.char for _k in range(nout)])
        ufunc = frompyfunc(_func, len(args), nout)
    return (ufunc, otypes)

def geomspace(start: ArrayLike, stop: ArrayLike, num=50, endpoint=True, dtype: Optional[DTypeLike]=None, axis=0):
    if <MASK>:
        raise NotImplementedError
    base = torch.pow(stop / start, 1.0 / (num - 1))
    logbase = torch.log(base)
    return torch.logspace(torch.log(start) / logbase, torch.log(stop) / logbase, num, base=base)

def scale(self, outputs: Union[torch.Tensor, Iterable[torch.Tensor]]) -> Union[torch.Tensor, Iterable[torch.Tensor]]:
    """
        Multiplies ('scales') a tensor or list of tensors by the scale factor.

        Returns scaled outputs.  If this instance of :class:`GradScaler` is not enabled, outputs are returned
        unmodified.

        Args:
            outputs (Tensor or iterable of Tensors):  Outputs to scale.
        """
    if not self._enabled:
        return outputs
    if isinstance(outputs, torch.Tensor):
        if self._scale is None:
            self._lazy_init_scale_growth_tracker(outputs.device)
        assert self._scale is not None
        return outputs * self._scale.to(device=outputs.device, non_blocking=True)
    stash: list[_MultiDeviceReplicator] = []

    def apply_scale(val: Union[torch.Tensor, Iterable[torch.Tensor]]):
        if <MASK>:
            if len(stash) == 0:
                if self._scale is None:
                    self._lazy_init_scale_growth_tracker(val.device)
                assert self._scale is not None
                stash.append(_MultiDeviceReplicator(self._scale))
            return val * stash[0].get(val.device)
        if isinstance(val, abc.Iterable):
            iterable = map(apply_scale, val)
            if isinstance(val, (list, tuple)):
                return type(val)(iterable)
            return iterable
        raise ValueError('outputs must be a Tensor or an iterable of Tensors')
    return apply_scale(outputs)

def sync(self) -> Optional[bool]:
    """See base class."""
    state_bits: Optional[bytes] = None
    token = None
    has_set: Optional[bool]
    if self._dirty:
        has_set = False
        state_bits = pickle.dumps(self._state)
        set_response = self._backend.set_state(state_bits, self._token)
        if set_response is not None:
            (state_bits, token, has_set) = set_response
    else:
        has_set = None
        if self._cache_duration > 0:
            if <MASK>:
                return None
        get_response = self._backend.get_state()
        if get_response is not None:
            (state_bits, token) = get_response
    if state_bits is not None:
        try:
            self._state = pickle.loads(state_bits)
        except pickle.PickleError as exc:
            raise RendezvousStateError('The rendezvous state is corrupt. See inner exception for details.') from exc
    else:
        self._state = _RendezvousState()
    if has_set and self._dead_nodes and logger.isEnabledFor(logging.DEBUG):
        node_list = ', '.join((f"'{dead_node}'" for dead_node in self._dead_nodes))
        msg = f"As part of the sync operation the node(s) {node_list} have been removed from the rendezvous '{self._settings.run_id}' since they had no heartbeat."
        self._record(message=msg)
        logger.debug(msg)
    self._token = token
    self._dirty = False
    self._last_sync_time = time.monotonic()
    self._sanitize()
    return has_set

@dist_init
def test_profiler_rpc_key_names(self):
    if <MASK>:
        return
    dst_ranks = [rank for rank in range(self.world_size) if rank != self.rank]

    def rpc_with_profiling(dst_worker):
        with _profile() as prof:
            fut = rpc.rpc_async(dst_worker, udf_with_torch_ops, args=())
            fut.wait()
        events = prof.function_events
        remote_event_names = {event.name: event for event in events if event.is_remote}
        rpc_profiling_key = _build_rpc_profiling_key(RPCExecMode.ASYNC, udf_with_torch_ops.__qualname__, worker_name(self.rank), dst_worker)
        remote_event_name_set = set(EXPECTED_REMOTE_EVENTS)
        for (name, event) in remote_event_names.items():
            self.assertTrue(name.startswith(rpc_profiling_key))
            self.assertTrue(event.is_remote)
            self.assertTrue(event.node_id == rpc.get_worker_info(dst_worker).id)
            operator_name_substr = name[len(rpc_profiling_key):]
            matching_event = {remote_event_name for remote_event_name in remote_event_name_set if remote_event_name in operator_name_substr}
            remote_event_name_set -= matching_event
        self.assertTrue(remote_event_name_set == set(), f'Expected {remote_event_name_set} to be included in remote profiler output.')
    for dst in dst_ranks:
        dst_worker = worker_name(dst)
        num_parallel_rpcs = 2
        with concurrent.futures.ThreadPoolExecutor(max_workers=num_parallel_rpcs) as executor:
            futs = [executor.submit(rpc_with_profiling, dst_worker) for _ in range(num_parallel_rpcs)]
            for fut in futs:
                fut.result()

