def __init__(self, layout: OutputSpec, kernel: _OpOverloads, tensor_args: Sequence[IRNode], nontensor_args: Sequence[Any], unflatten_args: Callable[..., Any], kwargs: Optional[dict[str, Any]]=None, *, unbacked_bindings: Optional[dict[sympy.Symbol, pytree.KeyPath]]=None) -> None:
    super().__init__(layout, tuple(tensor_args), tuple(nontensor_args), op_overload=kernel)
    self.use_runtime_dispatch = False
    self.unbacked_bindings = unbacked_bindings or {}
    assert isinstance(kernel, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)), f'Fails to create FallbackKernel for {kernel}: {type(kernel)} not supported'
    self.op_overload = kernel
    self.unflatten_args = unflatten_args
    self.kwargs = {} if kwargs is None else kwargs
    assert self.python_kernel_name is not None
    V.graph.warn_fallback(self.python_kernel_name)
    self.alias_names: list[str] = []
    self.mutation_names: list[str] = []
    if isinstance(self.op_overload, torch._ops.HigherOrderOperator):
        return
    if '_c10d_functional' in self.op_overload.name():
        return
    schema = self.op_overload._schema
    if torch._library.utils.mutates_and_returns_first_arg(self.op_overload):
        self.mutation_names.append(tensor_args[0].get_name())
        return
    if schema.is_mutable and (not can_auto_functionalize(kernel)):
        raise NotImplementedError(f"NYI: Can't generate FallbackKernel for {kernel}")
    (args, kwargs) = self.unflatten_args(self.inputs, self.constant_args)

    def handle_aliasing_and_mutation(info: torch._C.Argument, arg: Any) -> None:
        if isinstance(info.type, torch.ListType):
            assert isinstance(arg, (list, tuple)), type(arg)
        if library_utils.is_tensor_like_type(info.type):
            assert not isinstance(arg, (tuple, list))
        if arg is None:
            return
        if info.alias_info is None:
            return

        def add_alias(t: IRNode) -> None:
            self.alias_names.append(t.get_name())
            assert info.alias_info is not None
            if info.alias_info.is_write:
                self.mutation_outputs.append(MutationOutput(NoneLayout(device=t.get_device()), t, self))
        if <MASK>:
            if arg is not None:
                for optional_tensor_arg in arg:
                    add_alias(optional_tensor_arg)
        else:
            assert library_utils.is_tensor_like_type(info.type)
            add_alias(arg)
    for (info, arg) in torch._library.utils.zip_schema(schema, args, kwargs):
        handle_aliasing_and_mutation(info, arg)

def _train_for_several_steps(self, model: nn.Module, num_steps: int, autocast: bool, lr: float=0.01, fsdp_cpu_offload: Optional[CPUOffload]=None, save_model: bool=False, mixed_precision: Optional[MixedPrecision]=None, enable_sharded_grad_scaler: bool=False, use_pure_fp16: bool=False, sharded_grad_scaler_kwargs: Optional[dict[str, Any]]=None):
    cpu_offload_params = fsdp_cpu_offload and fsdp_cpu_offload.offload_params
    model_device = next(model.parameters()).device
    if sharded_grad_scaler_kwargs is None:
        sharded_grad_scaler_kwargs = {}
    sharded_grad_scaler = ShardedGradScaler(enabled=enable_sharded_grad_scaler, **sharded_grad_scaler_kwargs)
    optim = torch.optim.SGD(model.parameters(), lr=lr, momentum=0.9)
    for _ in range(num_steps):
        optim.zero_grad()
        with torch.amp.autocast(DEVICE_TYPE, enabled=autocast):
            input = model.module.get_input(torch.device(DEVICE_TYPE))
            if use_pure_fp16 or (mixed_precision and (not isinstance(model, FSDP))):
                if isinstance(input, torch.Tensor):
                    input = input.half()
                else:
                    input = tuple((x.half() for x in input))
            output = model(*input)
            if cpu_offload_params and isinstance(model, FSDP) and (model.sharding_strategy not in NO_RESHARD_AFTER_FORWARD_STRATEGIES):
                for p in model.parameters():
                    self.assertEqual(p.device, torch.device('cpu'))
            loss = model.module.get_loss(input, output).to(model_device)
        loss = sharded_grad_scaler.scale(loss)
        if not mixed_precision and (not use_pure_fp16):
            assert loss.dtype == torch.float32, 'loss data type should be float32, as the original                     parameter data type is float32.'
        elif use_pure_fp16:
            self.assertEqual(loss.dtype, torch.float16)
        elif isinstance(model, FSDP):
            assert mixed_precision is not None
            self.assertEqual(loss.dtype, mixed_precision.param_dtype)
        else:
            self.assertEqual(loss.dtype, torch.float32)
        model.module.run_backward(loss)
        if <MASK>:
            for p in model.parameters():
                self.assertEqual(p.device, torch.device('cpu'))
        sharded_grad_scaler.step(optim)
        sharded_grad_scaler.update()
        if save_model:
            state_dict = {k: v.clone() for (k, v) in model.state_dict().items()}
            _zero_model(model)
            model.load_state_dict(state_dict)
    if isinstance(model, FSDP):
        model._assert_state(TrainingState.IDLE)
    return loss.detach()

@staticmethod
