def _remove_redundant_sym_size_ops(self) -> None:
    """
        Deletes torch.ops.sym_size.int operators whose output is a
        corresponding placeholder that holds the same symbol, and replace all usage
        of the sym_size node to be directly using the placeholders.

        This is to make sure all basic symbols come from inputs.
        """
    placeholder_exprs = {}
    for node in self.joint_gm.graph.nodes:
        if <MASK>:
            val = node.meta['val']
            if isinstance(val, torch.SymInt):
                placeholder_exprs[val.node.expr] = node
    nodes_to_remove = []
    for node in self.joint_gm.graph.find_nodes(op='call_function', target=torch.ops.aten.sym_size.int):
        assert hasattr(node, 'meta') and 'val' in node.meta, node
        val = node.meta['val']
        expr = val.node.expr
        if expr in placeholder_exprs:
            placeholder_node = placeholder_exprs[expr]
            node.replace_all_uses_with(placeholder_node)
            nodes_to_remove.append(node)
    for node in nodes_to_remove:
        self.joint_gm.graph.erase_node(node)
    self.joint_gm.graph.lint()
    self.joint_gm.recompile()

def _handle_usecols(self, columns: list[list[Scalar | None]], usecols_key: list[Scalar | None], num_original_columns: int) -> list[list[Scalar | None]]:
    """
        Sets self._col_indices

        usecols_key is used if there are string usecols.
        """
    col_indices: set[int] | list[int]
    if <MASK>:
        if callable(self.usecols):
            col_indices = evaluate_callable_usecols(self.usecols, usecols_key)
        elif any((isinstance(u, str) for u in self.usecols)):
            if len(columns) > 1:
                raise ValueError('If using multiple headers, usecols must be integers.')
            col_indices = []
            for col in self.usecols:
                if isinstance(col, str):
                    try:
                        col_indices.append(usecols_key.index(col))
                    except ValueError:
                        self._validate_usecols_names(self.usecols, usecols_key)
                else:
                    col_indices.append(col)
        else:
            missing_usecols = [col for col in self.usecols if col >= num_original_columns]
            if missing_usecols:
                raise ParserError(f'Defining usecols with out-of-bounds indices is not allowed. {missing_usecols} are out-of-bounds.')
            col_indices = self.usecols
        columns = [[n for (i, n) in enumerate(column) if i in col_indices] for column in columns]
        self._col_indices = sorted(col_indices)
    return columns

def vector_norm(x: Array, /, *, axis: Optional[Union[int, Tuple[int, ...]]]=None, keepdims: bool=False, ord: JustInt | JustFloat=2, **kwargs) -> Array:
    if axis == ():
        out = kwargs.get('out')
        if <MASK>:
            dtype = None
            if x.dtype == torch.complex64:
                dtype = torch.float32
            elif x.dtype == torch.complex128:
                dtype = torch.float64
            out = torch.zeros_like(x, dtype=dtype)
        if ord == 0:
            out[:] = x != 0
        else:
            out[:] = torch.abs(x)
        return out
    return torch.linalg.vector_norm(x, ord=ord, axis=axis, keepdim=keepdims, **kwargs)

def run(self, new_inputs: Any) -> OutputType:
    assert not self.has_run, 'Wrapped function should never be run twice'
    existing_path_data_ptrs = OrderedSet([t.data_ptr() for t in self.path_live_weakrefs() if t()])

    def get_non_cudagraph_inps() -> list[weakref.ReferenceType[UntypedStorage]]:
        non_cudagraph_inps = [weakref.ref(t.untyped_storage()) for t in itertools.chain(new_inputs, self.wrapped_function.constants) if isinstance(t, torch.Tensor) and t.untyped_storage().data_ptr() not in existing_path_data_ptrs]
        return non_cudagraph_inps
    non_cudagraph_inps_storages = get_non_cudagraph_inps()
    if config.triton.slow_path_cudagraph_asserts and (not self.already_warm):
        refs = list(self.path_live_weakrefs())
        check_memory_pool(self.device_index, self.cuda_graphs_pool, refs)
    with torch.cuda.device(self.device_index), disable_conv_cache_emptying(), clear_cublas_manager(), _use_cuda_memory_pool_manager(self.device_index, self.cuda_graphs_pool, self.stream), get_history_recording():
        out = self.wrapped_function.model(new_inputs)
    non_cudagraph_inps_storage_ptrs = OrderedSet[Any]()
    for storage in non_cudagraph_inps_storages:
        s = storage()
        if <MASK>:
            non_cudagraph_inps_storage_ptrs.add(s._cdata)
    assert len(new_inputs) == 0

    def add_ref(o: Any) -> bool:
        return isinstance(o, torch.Tensor) and o.is_cuda and (o.untyped_storage()._cdata not in non_cudagraph_inps_storage_ptrs) and (o.untyped_storage().data_ptr() != 0)
    self.outputs_weakrefs.extend([map_to_ref(o) if add_ref(o) else None for o in out])
    self.tensor_weakrefs.extend([TensorWeakRef(o) if add_ref(o) else None for o in out])
    if config.triton.slow_path_cudagraph_asserts and (not self.already_warm):
        out_refs = list(self.path_live_weakrefs())
        check_memory_pool(self.device_index, self.cuda_graphs_pool, out_refs)
    return out

def _run_signature(session, meta_graph_def, inputs, signature_key, disable_check_for_input_signature_size_match=False):
    signature = meta_graph_def.signature_def[signature_key]
    if <MASK>:
        assert set(inputs.keys()) == set(signature.inputs.keys())
    feed_dict = {}
    for arg_name in inputs.keys():
        input_tensor = session.graph.get_tensor_by_name(signature.inputs[arg_name].name)
        feed_dict[input_tensor] = inputs[arg_name]
    output_dict = {}
    for (output_name, output_tensor_info) in signature.outputs.items():
        output_dict[output_name] = session.graph.get_tensor_by_name(output_tensor_info.name)
    return session.run(output_dict, feed_dict=feed_dict)

def keras_tensor_from_tensor(tensor):
    """Convert a traced (composite)tensor to a representative KerasTensor."""
    keras_tensor_cls = None
    for (tensor_type, cls) in keras_tensor_classes:
        if <MASK>:
            keras_tensor_cls = cls
            break
    out = keras_tensor_cls.from_tensor(tensor)
    if hasattr(tensor, '_keras_mask'):
        out._keras_mask = keras_tensor_from_tensor(tensor._keras_mask)
    return out

def _dimension(self, index):
    """Return a dimension, if the dimension is not ragged (see __getitem__)."""
    rank = self.rank
    if not isinstance(index, int):
        raise TypeError('index should be an int')
    if self.num_row_partitions == 0 or index > self.num_row_partitions + 1:
        if rank is None:
            raise ValueError('Rank must be known to use __getitem__ on a large index.')
        if index >= rank:
            raise IndexError('Index is too big: ' + str(index) + '>=' + str(rank))
    if index < 0:
        raise IndexError('Index must be non-negative: ' + str(index))
    elif not self.is_uniform(index):
        raise ValueError('Index ' + str(index) + ' is not uniform')
    elif index == 0 and self.num_row_partitions > 0:
        static_nrows = self.row_partitions[0].static_nrows
        if <MASK>:
            return constant_op.constant(static_nrows, dtype=self.dtype)
        return self.row_partitions[0].nrows()
    elif self.num_row_partitions == 0:
        static_result = tensor_shape.dimension_value(self._static_inner_shape[index])
        if static_result is not None:
            return constant_op.constant(static_result, dtype=self.dtype)
        return self.inner_shape[index]
    elif index > self.num_row_partitions:
        static_result = tensor_shape.dimension_value(self._static_inner_shape[index - self.num_row_partitions])
        if static_result is not None:
            return constant_op.constant(static_result, dtype=self.dtype)
        return self.inner_shape[index - self.num_row_partitions]
    else:
        return self.row_partitions[index - 1].uniform_row_length()

def _einsum_v1_parse_and_resolve_equation(equation, input_shapes):
    """Helper for einsum() that splits/resolves inputs & outputs.

  Args:
    equation: Equation string given as argument to einsum().
    input_shapes: List of the shapes of all inputs given to einsum()

  Returns:
    input_axis_labels, output_axis_labels where:
      input_axis_labels: List of length len(input_shapes) of strings
      representing the character label for each dimension of each given input,
      resolving any broadcast (...) axes,
    output_axis_labels: A string of character labels for each axes of output
      tensor, filling in missing output subscripts and broadcast axes.

  Raises:
    ValueError: If equation is in the incorrect format, incorrect number of
      inputs given or broadcast axes "..." or output axes could not be resolved.
  """
    equation = equation.replace(' ', '')
    match = re.match('^([a-zA-Z,.]+)(->[a-zA-Z.]*)?$', equation)
    if not match:
        raise ValueError(f'Indices have incorrect format. Received: {equation}.')
    input_axis_labels = match.group(1).split(',')
    output_axis_labels = match.group(2)[2:] if match.group(2) else None
    if len(input_shapes) != len(input_axis_labels):
        raise ValueError(f'Got {len(input_shapes)} arguments for equation "{equation}", expecting {len(input_axis_labels)}.')
    ellipsis_axes = ''
    if '...' in equation:
        unused = ''.join((c for c in string.ascii_letters if c not in ''.join(input_axis_labels)))
        for (i, ax) in enumerate(input_axis_labels):
            if <MASK>:
                parts = ax.split('...')
                if len(parts) != 2:
                    raise ValueError(f'Unable to resolve ellipsis. Excess number found: {len(parts) - 1} vs 1.')
                if input_shapes[i].ndims is None:
                    raise ValueError('Unable to statically infer ellipsis axes. The input shapes has a dynamic dimensionality.')
                n = input_shapes[i].ndims - len(''.join(parts))
                if n < 0:
                    raise ValueError('Ellipses lengths do not match.')
                if len(unused) < n:
                    raise ValueError('Unable to resolve ellipsis, too many distinct labels.')
                replace_axes = unused[-n:] if n > 0 else ''
                input_axis_labels[i] = input_axis_labels[i].replace('...', replace_axes)
                if len(replace_axes) > len(ellipsis_axes):
                    ellipsis_axes = replace_axes
        if any(('.' in ax for ax in input_axis_labels)):
            raise ValueError(f'Period "." found outside of ellipsis in input {input_axis_labels}.')
        if output_axis_labels is not None:
            output_axis_labels = output_axis_labels.replace('...', ellipsis_axes)
            if '.' in output_axis_labels:
                raise ValueError(f'Period "." found outside of ellipsis in output {output_axis_labels}.')
    if output_axis_labels is None:
        axis_labels = set(''.join(input_axis_labels)) - set(ellipsis_axes)
        indices = ''.join(sorted(axis_labels))
        counts = {ax: 0 for ax in indices}
        for axes_ in input_axis_labels:
            for ax in axes_:
                if ax not in ellipsis_axes:
                    counts[ax] += 1
        output_axis_labels = ellipsis_axes + ''.join(sorted((ax for ax in axis_labels if counts[ax] == 1)))
    return (input_axis_labels, output_axis_labels)

def _type_promote_from_values(*args) -> _type_utils.JitScalarType:
    undef = _type_utils.JitScalarType.UNDEFINED
    jit_types = [_try_get_scalar_type(arg) for arg in args]
    if <MASK>:
        return undef
    if len(jit_types) == 1:
        return jit_types[0]
    new_dtype = jit_types[0].dtype()
    for t in jit_types:
        new_dtype = torch.promote_types(new_dtype, t.dtype())
    return _type_utils.JitScalarType.from_dtype(new_dtype)

def error_inputs_func_wrapper(op, device, **kwargs):
    if <MASK>:
