def update_state(self, values, sample_weight=None):
    """Accumulates statistics for computing the metric.

    Args:
      values: Per-example value.
      sample_weight: Optional weighting of each example. Defaults to 1.

    Returns:
      Update op.
    """
    ([values], sample_weight) = metrics_utils.ragged_assert_compatible_and_get_flat_values([values], sample_weight)
    try:
        values = math_ops.cast(values, self._dtype)
    except (ValueError, TypeError):
        msg = 'The output of a metric function can only be a single Tensor. Got: %s' % (values,)
        if isinstance(values, dict):
            msg += '. To return a dict of values, implement a custom Metric subclass.'
        raise RuntimeError(msg)
    if sample_weight is not None:
        sample_weight = math_ops.cast(sample_weight, self._dtype)
        (values, _, sample_weight) = losses_utils.squeeze_or_expand_dimensions(values, sample_weight=sample_weight)
        try:
            sample_weight = weights_broadcast_ops.broadcast_weights(sample_weight, values)
        except ValueError:
            ndim = backend.ndim(values)
            weight_ndim = backend.ndim(sample_weight)
            if self.reduction == metrics_utils.Reduction.SUM:
                values = math_ops.reduce_sum(values, axis=list(range(weight_ndim, ndim)))
            else:
                values = math_ops.reduce_mean(values, axis=list(range(weight_ndim, ndim)))
        values = math_ops.multiply(values, sample_weight)
    value_sum = math_ops.reduce_sum(values)
    with ops.control_dependencies([value_sum]):
        update_total_op = self.total.assign_add(value_sum)
    if self.reduction == metrics_utils.Reduction.SUM:
        return update_total_op
    if self.reduction == metrics_utils.Reduction.SUM_OVER_BATCH_SIZE:
        num_values = math_ops.cast(array_ops.size(values), self._dtype)
    elif self.reduction == metrics_utils.Reduction.WEIGHTED_MEAN:
        if <MASK>:
            num_values = math_ops.cast(array_ops.size(values), self._dtype)
        else:
            num_values = math_ops.reduce_sum(sample_weight)
    else:
        raise NotImplementedError('reduction [%s] not implemented' % self.reduction)
    with ops.control_dependencies([update_total_op]):
        return self.count.assign_add(num_values)

def _merge_tensors(t1, t2, name, validate):
    """Merge two optional Tensors with equal values into a single Tensor.

  Args:
    t1: tf.Tensor or None
    t2: tf.Tensor or None
    name: A name for the tensors (for error messages)
    validate: If true, then check that `t1` is compatible with `t2` (if both are
      non-None).

  Returns:
    A pair `(merged_value, validated)`:
      * `merged_value` is `t1` if it is not None; or `t2` otherwise.
      * `validated` is true if we validated that t1 and t2 are equal (either
        by adding a check, or because t1 is t2).
  """
    if t1 is None:
        return (t2, False)
    elif t2 is None:
        return (t1, False)
    elif <MASK>:
        return (t1, True)
    else:
        err_msg = 'RowPartition._merge_precomputed_encodings: partitions have incompatible %s' % name
        if not t1.shape.is_compatible_with(t2.shape):
            raise ValueError(err_msg)
        if validate:
            checks = [check_ops.assert_equal(t1, t2, message=err_msg)]
            return (control_flow_ops.with_dependencies(checks, t1), True)
        else:
            return (t1, False)

def _generate_marginal_results_without_values(table: DataFrame, data: DataFrame, rows, cols, aggfunc, kwargs, observed: bool, margins_name: Hashable='All', dropna: bool=True):
    margin_keys: list | Index
    if len(cols) > 0:
        margin_keys = []

        def _all_key():
            if <MASK>:
                return margins_name
            return (margins_name,) + ('',) * (len(cols) - 1)
        if len(rows) > 0:
            margin = data.groupby(rows, observed=observed, dropna=dropna)[rows].apply(aggfunc, **kwargs)
            all_key = _all_key()
            table[all_key] = margin
            result = table
            margin_keys.append(all_key)
        else:
            margin = data.groupby(level=0, observed=observed, dropna=dropna).apply(aggfunc, **kwargs)
            all_key = _all_key()
            table[all_key] = margin
            result = table
            margin_keys.append(all_key)
            return result
    else:
        result = table
        margin_keys = table.columns
    if len(cols):
        row_margin = data.groupby(cols, observed=observed, dropna=dropna)[cols].apply(aggfunc, **kwargs)
    else:
        row_margin = Series(np.nan, index=result.columns)
    return (result, margin_keys, row_margin)

def _eval_power(self, expt):
    if <MASK>:
        return S.IntInfinity
    if expt.is_extended_negative:
        return S.Zero
    if expt is S.NaN:
        return S.NaN
    if expt is S.ComplexInfinity:
        return S.NaN
    if expt.is_extended_real is False and expt.is_number:
        from sympy.functions.elementary.complexes import re
        expt_real = re(expt)
        if expt_real.is_positive:
            return S.ComplexInfinity
        if expt_real.is_negative:
            return S.Zero
        if expt_real.is_zero:
            return S.NaN
        return self ** expt.evalf()

def _full_pre_load_state_dict_hook(module: nn.Module, fsdp_state: _FSDPState, state_dict: dict[str, Any], prefix: str) -> None:
    _lazy_init(fsdp_state, module)
    if <MASK>:
        with SimpleProfiler.profile('_enter_unshard_params_ctx'):
            _enter_unshard_params_ctx(module, fsdp_state, writeback=True)
    if not _is_composable(fsdp_state):
        _replace_by_prefix(state_dict, prefix, prefix + f'{FSDP_PREFIX}')

def do_auto_functionalize_v2(mode: 'torch._subclasses.functional_tensor.FunctionalTensorMode', op: Union[OpOverload, HopInstance], args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
    from torch._subclasses.functional_tensor import PythonFunctionalizeAPI
    ctx = PythonFunctionalizeAPI(mode=mode)
    normalized_kwargs = {}
    schema = op._schema
    op = op._op if isinstance(op, HopInstance) else op
    assert isinstance(op, get_args(_MutableOpType))

    def _functionalize_callable(arg: Any):
        if callable(arg):
            return FunctionalCallableWithEpilogue(arg)
        return arg
    (args, kwargs) = pytree.tree_map(_functionalize_callable, (args, kwargs))
    for (idx, arg) in enumerate(schema.arguments):
        if arg.name in kwargs:
            normalized_kwargs[arg.name] = kwargs[arg.name]
        elif idx < len(args):
            normalized_kwargs[arg.name] = args[idx]
        else:
            normalized_kwargs[arg.name] = arg.default_value
    (mutable_args_names, mutable_args_types) = get_mutable_args_from_schema(schema)
    all_bases = []
    all_bases_addresses: list[int] = []
    arg_to_base_index: dict[str, Any] = {}

    def update_dict(tensor, arg_name, index=None):
        base = tensor if get_base(tensor) is None else get_base(tensor)

        def set_result(base_index):
            if index is None:
                arg_to_base_index[arg_name] = base_index
            else:
                arg_to_base_index[arg_name][index] = base_index
        if not all_bases_addresses.__contains__(base._cdata):
            all_bases_addresses.append(base._cdata)
            all_bases.append(base)
            set_result(len(all_bases) - 1)
        else:
            set_result(all_bases_addresses.index(base._cdata))
    for arg_name in mutable_args_names:
        arg = normalized_kwargs[arg_name]
        if arg is None:
            continue
        if isinstance(arg, list):
            arg_to_base_index[arg_name] = {}
            for (i, tensor) in enumerate(arg):
                if tensor is None:
                    arg_to_base_index[arg_name].append(None)
                    continue
                update_dict(tensor, arg_name, i)
        else:
            update_dict(arg, arg_name)
    write_view_information_to_args(mutable_args_names, mutable_args_types, normalized_kwargs, arg_to_base_index)
    for arg_name in mutable_args_names:
        del normalized_kwargs[arg_name]
    unwrapped_kwargs = ctx.unwrap_tensors(normalized_kwargs)
    if 'self' in unwrapped_kwargs or 'self_' in unwrapped_kwargs:
        warnings.warn('Using `self` or `self_` as an argument in the definition of custom ops may lead to ambiguous parsing. Please consider using a different name for this argument to avoid potential issues.')
    all_basis_unwrapped = ctx.unwrap_tensors(all_bases)
    assert '_all_bases' not in unwrapped_kwargs, (op, unwrapped_kwargs)
    auto_func_kwargs = dict(unwrapped_kwargs, _all_bases=all_basis_unwrapped)
    if isinstance(op, HigherOrderOperator):
        assert '_ops_schema' not in unwrapped_kwargs, (op, unwrapped_kwargs)
        auto_func_kwargs.update({'_op_schema': pytree.tree_flatten(SchemaHolder(schema))[1]})
    with ctx.redispatch_to_next():
        unwrapped_outs = auto_functionalized_v2(op, **auto_func_kwargs)
    unwrapped_actual_out: Union[Any, tuple[Any]] = unwrapped_outs if len(all_bases) == 0 else unwrapped_outs[:-len(all_bases)]
    unwrapped_mutable_out = [] if len(all_bases) == 0 else unwrapped_outs[-len(all_bases):]
    if isinstance(op, HigherOrderOperator):
        assert len(schema.returns) > 0, f'hop is expected to return at least one output {schema}.'
        assert len(unwrapped_actual_out) == len(schema.returns)
    elif len(schema.returns) == 0:
        assert unwrapped_actual_out[0] is None
        unwrapped_actual_out = None
    elif len(schema.returns) == 1:
        assert len(unwrapped_actual_out) == 1
        unwrapped_actual_out = unwrapped_actual_out[0]
    else:
        assert len(unwrapped_actual_out) == len(schema.returns)
    for (orig_arg, unwrapped_out) in zip(all_bases, unwrapped_mutable_out):
        if <MASK>:
            continue

        def sync_update(o, orig_arg):
            ctx.replace(orig_arg, o)
            ctx.commit_update(orig_arg)
            ctx.sync(orig_arg)
        if isinstance(unwrapped_out, torch.Tensor):
            sync_update(unwrapped_out, orig_arg)
        elif isinstance(unwrapped_out, list) and all((isinstance(o, torch.Tensor) for o in unwrapped_out)):
            assert len(orig_arg) == len(unwrapped_out)
            for (orig_a, o) in zip(orig_arg, unwrapped_out):
                sync_update(o, orig_a)
        else:
            raise RuntimeError(f'unsupported type for auto-functionalization: {unwrapped_out}')
    return ctx.wrap_tensors(unwrapped_actual_out)

def value_to_literal(value):
    if <MASK>:
        return ascii(value)
    if isinstance(value, torch.Tensor):
        return 'torch.' + str(value)
    else:
        return str(value)

def stack(self, name=None):
    """See TensorArray."""
    if self._tensor_array:
        for ix in range(len(self._tensor_array)):
            self._maybe_zero(ix)
    if <MASK>:
        return ops.convert_to_tensor(np.ndarray([0] + self._element_shape), name=name, dtype=self._dtype)
    else:
        return ops.convert_to_tensor(self._tensor_array, name=name, dtype=self._dtype)

def _torch_reduce_dim(fn):

    def reduce_dim(self, dim, keepdim=False, dtype=None):
        if self.is_sparse:
            msg = f'The sparse version of {fn} is not implemented in reductions.\nIf you would like this operator to be supported, please file an issue for a feature request at https://github.com/pytorch/maskedtensor/issues with a minimal reproducible code snippet.\nIn the case that the semantics for the operator are not trivial, it would be appreciated to also include a proposal for the semantics.'
            warnings.warn(msg)
            return NotImplemented
        if <MASK>:
            raise TypeError('Input to reduce_dim must be a MaskedTensor')
        masked_fn = _get_masked_fn(fn)
        data = self.get_data()
        mask = self.get_mask()
        if fn == 'all':
            result_data = masked_fn(data, dim=dim, keepdim=keepdim, mask=mask)
        else:
            result_data = masked_fn(self, dim=dim, keepdim=keepdim, dtype=dtype, mask=self.get_mask())
        return as_masked_tensor(result_data, _multidim_any(mask, dim, keepdim))
    return reduce_dim

def _add_observer_(module, qconfig_propagation_list=None, non_leaf_module_list=None, device=None, custom_module_class_mapping=None):
    """Add observer for the leaf child of the module.

    This function insert observer module to all leaf child module that
    has a valid qconfig attribute.

    Args:
        module: input module with qconfig attributes for all the leaf modules that we want to quantize
        qconfig_propagation_list: a list of quantizable modules that will have observers added to them
            if they are leaf nodes
        device: parent device, if any
        non_leaf_module_list: list of non-leaf modules we want to add observer

    Return:
        None, module is modified inplace with added observer modules and forward_hooks
    """
    if qconfig_propagation_list is None:
        qconfig_propagation_list = get_default_qconfig_propagation_list()
    if custom_module_class_mapping is None:
        custom_module_class_mapping = {}
    if device is None:
        devices = _get_unique_devices_(module)
        assert len(devices) <= 1, f'_add_observer_ only works with cpu or single-device CUDA modules, but got devices {devices}'
        device = next(iter(devices)) if len(devices) > 0 else None

    def get_activation_post_process(qconfig, device, special_act_post_process=None):
        activation = qconfig.activation() if special_act_post_process is None else special_act_post_process()
        if device is not None:
            activation.to(device)
        return activation

    def needs_observation(m):
        return hasattr(m, 'qconfig') and m.qconfig is not None

    def insert_activation_post_process(m, special_act_post_process=None):
        """Adds an activation post process module and register
        a pre or post hook that calls the module
        """
        if needs_observation(m) and (not isinstance(m, DeQuantStub)):
            m.add_module('activation_post_process', get_activation_post_process(m.qconfig, device, special_act_post_process))
            _register_activation_post_process_hook(m, pre_hook=_activation_is_memoryless(m.qconfig))
    for (name, child) in module.named_children():
        if type_before_parametrizations(child) is nn.Dropout:
            continue
        elif issubclass(type_before_parametrizations(child), (nnq.FloatFunctional, nnq.QFunctional)):
            if needs_observation(child):
                assert hasattr(child, 'activation_post_process'), f'functional class {type_before_parametrizations(child)} has no pre-defined `activation_post_process`'
                child.activation_post_process = get_activation_post_process(child.qconfig, device)
        elif isinstance(child, _FusedModule):
            if needs_observation(child):
                insert_activation_post_process(child)
        elif non_leaf_module_list is not None and type_before_parametrizations(child) in non_leaf_module_list:
            if needs_observation(child):
                insert_activation_post_process(child)
        elif _has_special_act_post_process(child):
            special_act_post_process = _get_special_act_post_process(child)
            insert_activation_post_process(child, special_act_post_process)
        elif needs_observation(child) and type_before_parametrizations(child) in custom_module_class_mapping:
            observed_class = custom_module_class_mapping[type_before_parametrizations(child)]
            observed_child = observed_class.from_float(child)
            setattr(module, name, observed_child)
            if not issubclass(observed_class, tuple(no_observer_set())):
                insert_activation_post_process(observed_child)
        else:
            _add_observer_(child, qconfig_propagation_list, non_leaf_module_list, device, custom_module_class_mapping)
    if <MASK>:
        insert_activation_post_process(module)
    if hasattr(module, 'weight_fake_quant') and (not isinstance(module, torch.nn.Sequential)) and (type_before_parametrizations(module) in qconfig_propagation_list):
        insert_activation_post_process(module)

def _is_match(modules, node, pattern, max_uses=sys.maxsize):
    """Matches a node in fx against a pattern"""
    if isinstance(pattern, tuple):
        (self_match, *arg_matches) = pattern
        if self_match is getattr:
            assert len(pattern) == 2, 'Expecting getattr pattern to have two elements'
            arg_matches = []
    else:
        self_match = pattern
        arg_matches = []
    if isinstance(self_match, type) and issubclass(self_match, MatchAllNode):
        return True
    if node == pattern:
        return True
    if not isinstance(node, Node) or len(node.users) > max_uses:
        return False
    if isinstance(self_match, type) and issubclass(self_match, torch.nn.Module):
        if <MASK>:
            return False
        if type_before_parametrizations(modules[node.target]) != self_match:
            return False
    elif callable(self_match):
        if node.op != 'call_function' or node.target is not self_match:
            return False
        elif node.target is getattr:
            if node.args[1] != pattern[1]:
                return False
    elif isinstance(self_match, str):
        if node.op != 'call_method' or node.target != self_match:
            return False
    elif node.target != self_match:
        return False
    if not arg_matches:
        return True
    if len(arg_matches) != len(node.args):
        return False
    return all((_is_match(modules, node, arg_match, max_uses=1) for (node, arg_match) in zip(node.args, arg_matches)))

def _call_impl(self, *args, **kwargs):
    forward_call = self._slow_forward if torch._C._get_tracing_state() else self.forward
    if not (self._backward_hooks or self._backward_pre_hooks or self._forward_hooks or self._forward_pre_hooks or _global_backward_pre_hooks or _global_backward_hooks or _global_forward_hooks or _global_forward_pre_hooks):
        return forward_call(*args, **kwargs)
    result = None
    called_always_called_hooks = set()

    def inner():
        nonlocal result, args, kwargs
        (full_backward_hooks, non_full_backward_hooks) = ([], [])
        backward_pre_hooks = []
        if self._backward_pre_hooks or _global_backward_pre_hooks:
            backward_pre_hooks = self._get_backward_pre_hooks()
        if self._backward_hooks or _global_backward_hooks:
            (full_backward_hooks, non_full_backward_hooks) = self._get_backward_hooks()
        if _global_forward_pre_hooks or self._forward_pre_hooks:
            for (hook_id, hook) in (*_global_forward_pre_hooks.items(), *self._forward_pre_hooks.items()):
                if hook_id in self._forward_pre_hooks_with_kwargs:
                    args_kwargs_result = hook(self, args, kwargs)
                    if args_kwargs_result is not None:
                        if isinstance(args_kwargs_result, tuple) and len(args_kwargs_result) == 2:
                            (args, kwargs) = args_kwargs_result
                        else:
                            raise RuntimeError(f'forward pre-hook must return None or a tuple of (new_args, new_kwargs), but got {args_kwargs_result}.')
                else:
                    args_result = hook(self, args)
                    if args_result is not None:
                        if not isinstance(args_result, tuple):
                            args_result = (args_result,)
                        args = args_result
        bw_hook = None
        if full_backward_hooks or backward_pre_hooks:
            bw_hook = BackwardHook(self, full_backward_hooks, backward_pre_hooks)
            args = bw_hook.setup_input_hook(args)
        result = forward_call(*args, **kwargs)
        if _global_forward_hooks or self._forward_hooks:
            for (hook_id, hook) in (*_global_forward_hooks.items(), *self._forward_hooks.items()):
                if hook_id in self._forward_hooks_always_called or hook_id in _global_forward_hooks_always_called:
                    called_always_called_hooks.add(hook_id)
                if hook_id in self._forward_hooks_with_kwargs or hook_id in _global_forward_hooks_with_kwargs:
                    hook_result = hook(self, args, kwargs, result)
                else:
                    hook_result = hook(self, args, result)
                if hook_result is not None:
                    result = hook_result
        if bw_hook:
            if not isinstance(result, (torch.Tensor, tuple)):
                warnings.warn(f'For backward hooks to be called, module output should be a Tensor or a tuple of Tensors but received {type(result)}')
            result = bw_hook.setup_output_hook(result)
        if non_full_backward_hooks:
            var = result
            while not isinstance(var, torch.Tensor):
                if isinstance(var, dict):
                    var = next((v for v in var.values() if isinstance(v, torch.Tensor)))
                else:
                    var = var[0]
            grad_fn = var.grad_fn
            if grad_fn is not None:
                for hook in non_full_backward_hooks:
                    grad_fn.register_hook(_WrappedHook(hook, self))
                self._maybe_warn_non_full_backward_hook(args, result, grad_fn)
        return result
    if torch.compiler.is_compiling():
        return inner()
    try:
        return inner()
    except Exception:
        for (hook_id, hook) in _global_forward_hooks.items():
            if hook_id in _global_forward_hooks_always_called and hook_id not in called_always_called_hooks:
                try:
                    hook_result = hook(self, args, result)
                    if hook_result is not None:
                        result = hook_result
                except Exception as e:
                    warnings.warn(f'global module forward hook with ``always_call=True`` raised an exception that was silenced as another error was raised in forward: {str(e)}')
                    continue
        for (hook_id, hook) in self._forward_hooks.items():
            if <MASK>:
                try:
                    if hook_id in self._forward_hooks_with_kwargs:
                        hook_result = hook(self, args, kwargs, result)
                    else:
                        hook_result = hook(self, args, result)
                    if hook_result is not None:
                        result = hook_result
                except Exception as e:
                    warnings.warn(f'module forward hook with ``always_call=True`` raised an exception that was silenced as another error was raised in forward: {str(e)}')
                    continue
        raise

def describe(obj: Any, denylist: Collection[Any], leaves_only: bool=False) -> str:
    """Returns a custom human-readable summary of obj.

    Args:
      obj: the value to describe.
      denylist: same as denylist in get_ignore_reason.
      leaves_only: boolean flag used when calling describe recursively. Useful
        for summarizing collections.
    """
    if get_ignore_reason(obj, denylist):
        return '{}{}'.format(get_ignore_reason(obj, denylist), type(obj))
    if tf_inspect.isframe(obj):
        return 'frame: {}'.format(tf_inspect.getframeinfo(obj))
    elif tf_inspect.ismodule(obj):
        return 'module: {}'.format(obj.__name__)
    elif leaves_only:
        return '{}, {}'.format(type(obj), id(obj))
    elif <MASK>:
        return 'list({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
    elif isinstance(obj, tuple):
        return 'tuple({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
    elif isinstance(obj, dict):
        return 'dict({}): {} keys'.format(id(obj), len(obj.keys()))
    elif tf_inspect.isfunction(obj):
        return 'function({}) {}; globals ID: {}'.format(id(obj), obj.__name__, id(obj.__globals__))
    else:
        return '{}, {}'.format(type(obj), id(obj))

def wrap_unlinkable_objects(self, objects, output_dir, extra_dll_dir):
    """
        Convert a set of object files that are not compatible with the default
        linker, to a file that is compatible.
        """
    if self.c_compiler.compiler_type == 'msvc':
        archives = []
        plain_objects = []
        for obj in objects:
            if obj.lower().endswith('.a'):
                archives.append(obj)
            else:
                plain_objects.append(obj)
        chained_libs = []
        chained_dlls = []
        for archive in archives[::-1]:
            (lib, dll) = self._link_wrapper_lib([archive], output_dir, extra_dll_dir, chained_dlls=chained_dlls, is_archive=True)
            chained_libs.insert(0, lib)
            chained_dlls.insert(0, dll)
        if <MASK>:
            return chained_libs
        (lib, dll) = self._link_wrapper_lib(plain_objects, output_dir, extra_dll_dir, chained_dlls=chained_dlls, is_archive=False)
        return [lib] + chained_libs
    else:
        raise ValueError('Unsupported C compiler')

def _node_sets_self_attribute(self, node):
    if <MASK>:
        qn = anno.getanno(node, anno.Basic.QN)
        if qn.has_attr and qn.parent.qn == ('self',):
            return True
    return False

def cb_routsign2map(rout, um):
    """
    name,begintitle,endtitle,argname
    ctype,rctype,maxnofargs,nofoptargs,returncptr
    """
    ret = {'name': f"cb_{rout['name']}_in_{um}", 'returncptr': ''}
    if isintent_callback(rout):
        if '_' in rout['name']:
            F_FUNC = 'F_FUNC_US'
        else:
            F_FUNC = 'F_FUNC'
        ret['callbackname'] = f"{F_FUNC}({rout['name'].lower()},{rout['name'].upper()})"
        ret['static'] = 'extern'
    else:
        ret['callbackname'] = ret['name']
        ret['static'] = 'static'
    ret['argname'] = rout['name']
    ret['begintitle'] = gentitle(ret['name'])
    ret['endtitle'] = gentitle(f"end of {ret['name']}")
    ret['ctype'] = getctype(rout)
    ret['rctype'] = 'void'
    if ret['ctype'] == 'string':
        ret['rctype'] = 'void'
    else:
        ret['rctype'] = ret['ctype']
    if ret['rctype'] != 'void':
        if iscomplexfunction(rout):
            ret['returncptr'] = '\n#ifdef F2PY_CB_RETURNCOMPLEX\nreturn_value=\n#endif\n'
        else:
            ret['returncptr'] = 'return_value='
    if ret['ctype'] in cformat_map:
        ret['showvalueformat'] = f"{cformat_map[ret['ctype']]}"
    if isstringfunction(rout):
        ret['strlength'] = getstrlength(rout)
    if isfunction(rout):
        if 'result' in rout:
            a = rout['result']
        else:
            a = rout['name']
        if hasnote(rout['vars'][a]):
            ret['note'] = rout['vars'][a]['note']
            rout['vars'][a]['note'] = ['See elsewhere.']
        ret['rname'] = a
        (ret['pydocsign'], ret['pydocsignout']) = getpydocsign(a, rout)
        if iscomplexfunction(rout):
            ret['rctype'] = '\n#ifdef F2PY_CB_RETURNCOMPLEX\n#ctype#\n#else\nvoid\n#endif\n'
    elif hasnote(rout):
        ret['note'] = rout['note']
        rout['note'] = ['See elsewhere.']
    nofargs = 0
    nofoptargs = 0
    if 'args' in rout and 'vars' in rout:
        for a in rout['args']:
            var = rout['vars'][a]
            if l_or(isintent_in, isintent_inout)(var):
                nofargs = nofargs + 1
                if isoptional(var):
                    nofoptargs = nofoptargs + 1
    ret['maxnofargs'] = repr(nofargs)
    ret['nofoptargs'] = repr(nofoptargs)
    if <MASK>:
        ret['routnote'] = rout['note']
        rout['note'] = ['See elsewhere.']
    return ret

def __init__(self, *args, **kwargs):
    if not args or not all((isinstance(field, str) for field in args)) or len(set(args)) != len(args):
        raise ValueError('CompositePrimaryKey args must be unique strings.')
    if len(args) == 1:
        raise ValueError('CompositePrimaryKey must include at least two fields.')
    if kwargs.get('default', NOT_PROVIDED) is not NOT_PROVIDED:
        raise ValueError('CompositePrimaryKey cannot have a default.')
    if kwargs.get('db_default', NOT_PROVIDED) is not NOT_PROVIDED:
        raise ValueError('CompositePrimaryKey cannot have a database default.')
    if kwargs.get('db_column', None) is not None:
        raise ValueError('CompositePrimaryKey cannot have a db_column.')
    if kwargs.setdefault('editable', False):
        raise ValueError('CompositePrimaryKey cannot be editable.')
    if <MASK>:
        raise ValueError('CompositePrimaryKey must be a primary key.')
    if not kwargs.setdefault('blank', True):
        raise ValueError('CompositePrimaryKey must be blank.')
    self.field_names = args
    super().__init__(**kwargs)

def _collect_derived_attrs_from_proto(op_def):
    derived_attrs = set()
    for arg in op_def.input_arg:
        if arg.type_attr:
            derived_attrs.add(arg.type_attr)
        if <MASK>:
            derived_attrs.add(arg.number_attr)
        if arg.type_list_attr:
            derived_attrs.add(arg.type_list_attr)
        if arg.type == types_pb2.DT_FLOAT:
            derived_attrs.add('f32_')
        elif arg.type == types_pb2.DT_INT32:
            derived_attrs.add('i32_')
        elif arg.type == types_pb2.DT_INT64:
            derived_attrs.add('i64_')
        elif arg.type == types_pb2.DT_BOOL:
            derived_attrs.add('i1_')
    return derived_attrs

