def arrow_table_to_pandas(table: pyarrow.Table, dtype_backend: DtypeBackend | Literal['numpy'] | lib.NoDefault=lib.no_default, null_to_int64: bool=False, to_pandas_kwargs: dict | None=None, dtype: DtypeArg | None=None, names: Sequence[Hashable] | None=None) -> pd.DataFrame:
    pa = import_optional_dependency('pyarrow')
    to_pandas_kwargs = {} if to_pandas_kwargs is None else to_pandas_kwargs
    types_mapper: type[pd.ArrowDtype] | None | Callable
    if dtype_backend == 'numpy_nullable':
        mapping = _arrow_dtype_mapping()
        if null_to_int64:
            mapping[pa.null()] = pd.Int64Dtype()
        types_mapper = mapping.get
    elif dtype_backend == 'pyarrow':
        types_mapper = pd.ArrowDtype
    elif using_string_dtype():
        if pa_version_under19p0:
            types_mapper = _arrow_string_types_mapper()
        elif <MASK>:
            types_mapper = {pa.int8(): pd.Int8Dtype(), pa.int16(): pd.Int16Dtype(), pa.int32(): pd.Int32Dtype(), pa.int64(): pd.Int64Dtype()}.get
        else:
            types_mapper = None
    elif dtype_backend is lib.no_default or dtype_backend == 'numpy':
        if dtype is not None:
            types_mapper = {pa.int8(): pd.Int8Dtype(), pa.int16(): pd.Int16Dtype(), pa.int32(): pd.Int32Dtype(), pa.int64(): pd.Int64Dtype()}.get
        else:
            types_mapper = None
    else:
        raise NotImplementedError
    df = table.to_pandas(types_mapper=types_mapper, **to_pandas_kwargs)
    return _post_convert_dtypes(df, dtype_backend, dtype, names)

def _check_to_fields_exist(self):
    if <MASK>:
        return []
    errors = []
    for to_field in self.to_fields:
        if to_field:
            try:
                self.remote_field.model._meta.get_field(to_field)
            except exceptions.FieldDoesNotExist:
                errors.append(checks.Error("The to_field '%s' doesn't exist on the related model '%s'." % (to_field, self.remote_field.model._meta.label), obj=self, id='fields.E312'))
    return errors

def __call__(self, test_case):
    with set_default_dtype(self.default_dtype):
        module = self.constructor(*self.constructor_args)
        input = self._get_input()
        module.__repr__()
        str(module)
        target = self._get_target()
        if self.reference_fn is not None:
            out = test_case._forward_criterion(module, input, target, extra_args=self.extra_args)
            ref_args = (deepcopy(input), deepcopy(target)) + self.extra_args + (module,)
            expected_out = self.reference_fn(*ref_args)
            test_case.assertEqual(out, expected_out)
        if self.check_forward_only:
            return
        params = tuple((x for x in module.parameters()))
        if <MASK>:
            inputs = (input,) + params + (target,)

            def apply_fn(input, target, *params):
                return module(input, target)
        else:
            inputs = input + params + (target,)

            def apply_fn(input1, input2, target, *params):
                return module(input1, input2, target)
        gradcheck(apply_fn, inputs, check_batched_grad=self.check_batched_grad)
        if self.check_gradgrad:
            gradgradcheck(apply_fn, inputs, check_batched_grad=self.check_batched_grad)

@register_decomposition(aten.native_dropout)
@out_wrapper('out0', 'out1')
def native_dropout(input: Tensor, p: float, train: Optional[bool]):
    if train and p != 0:
        if <MASK>:
            return (torch.zeros_like(input), torch.zeros_like(input, dtype=torch.bool))
        if not input.dtype.is_floating_point:
            raise RuntimeError("result type Float can't be cast to the desired output type Long")
        bool_mask = torch.rand_like(input) > p
        res = bool_mask * input * float(1.0 / (1.0 - p))
        return (res, bool_mask)
    else:
        return (input, torch.ones_like(input, dtype=torch.bool))

def _get_builtin_table():
    global _builtin_table
    if _builtin_table is not None:
        return _builtin_table
    _builtin_table = {}

    def register_all(mod):
        for name in dir(mod):
            v = getattr(mod, name)
            if <MASK>:
                if name == '_segment_reduce':
                    name = name[1:]
                _builtin_ops.append((v, 'aten::' + name))
    for mod in _modules_containing_builtins:
        register_all(mod)
    _builtin_ops.append((math.gcd, 'aten::gcd'))
    _builtin_ops.append((math.isfinite, 'aten::isfinite'))
    _builtin_ops.append((math.remainder, 'aten::mathremainder'))
    import torch.distributed.autograd as dist_autograd
    if dist_autograd.is_available():
        _builtin_ops.append((dist_autograd.get_gradients, 'aten::get_gradients'))
        _builtin_ops.append((dist_autograd.backward, 'aten::dist_backward'))
    for (builtin, aten_op) in _builtin_ops:
        _builtin_table[id(builtin)] = aten_op
    return _builtin_table

def mutates_and_returns_first_arg(op: OpOverload):
    """Check if an op is an inplace aten op, i.e. it mutates and returns the first arg.

    TODO: torchgen/model.py's FunctionSchema.parse is the source of truth for this,
    but not all PyTorch builds have torchgen (due to the yaml dependency being weird).
    Figure this out.

    Example: add_(Tensor(a!) x, Tensor y) -> Tensor(a)
    """
    if op.namespace != 'aten':
        return False
    schema = op._schema
    if len(schema.returns) != 1:
        return False
    if <MASK>:
        return False
    alias_set = schema.returns[0].alias_info.after_set
    if len(alias_set) != 1:
        return False
    loc = next(iter(alias_set))
    if len(schema.arguments) < 1:
        return False
    first_arg = schema.arguments[0]
    if first_arg.alias_info is None:
        return False
    if not first_arg.alias_info.is_write:
        return False
    alias_set = first_arg.alias_info.after_set
    if len(alias_set) != 1:
        return False
    if loc != next(iter(alias_set)):
        return False
    for arg in schema.arguments[1:]:
        if arg.alias_info is not None:
            return False
    return True

@_overload_by_arg_count
def reduce(g, *args, **kwargs):

    @quantized_args(True)
    @parse_args('v', 'none')
    def reduce_nodim(g, self, dtype):
        dtype_onnx = None
        if dtype.node().kind() == 'onnx::Constant':
            dtype = _get_const(dtype, 'i', 'dtype')
            dtype_onnx = _type_utils.JitScalarType(dtype).onnx_type()
            self = g.op('Cast', self, to_i=dtype_onnx)
        elif dtype.node().kind() != 'prim::Constant':
            return _unimplemented(name, 'dtype', dtype)
        result = symbolic(g, self)
        if dtype_onnx is not None:
            result_dtype_onnx = _type_utils.JitScalarType.from_value(result).onnx_type()
            if <MASK>:
                result = g.op('Cast', result, to_i=dtype_onnx)
        return result
    dim_desc = 'is' if allow_multi_dim_support else 'i'

    @quantized_args(True)
    @parse_args('v', dim_desc, 'i', 'none')
    def reduce_dim(g, self, dim, keepdim, dtype):
        dtype_onnx = None
        if dtype.node().kind() == 'onnx::Constant':
            dtype = _get_const(dtype, 'i', 'dtype')
            dtype_onnx = _type_utils.JitScalarType(dtype).onnx_type()
            self = g.op('Cast', self, to_i=dtype_onnx)
        elif dtype.node().kind() != 'prim::Constant':
            return _unimplemented(name, 'dtype', dtype)
        result = symbolic(g, self, dim, keepdim)
        if dtype_onnx is not None:
            result_dtype_onnx = _type_utils.JitScalarType.from_value(result).onnx_type()
            if result_dtype_onnx != dtype_onnx:
                result = g.op('Cast', result, to_i=dtype_onnx)
        return result
    return (reduce_nodim, reduce_dim)

def handle_template(self, template, subdir):
    """
        Determine where the app or project templates are.
        Use django.__path__[0] as the default because the Django install
        directory isn't known.
        """
    if template is None:
        return os.path.join(django.__path__[0], 'conf', subdir)
    else:
        template = template.removeprefix('file://')
        expanded_template = os.path.expanduser(template)
        expanded_template = os.path.normpath(expanded_template)
        if os.path.isdir(expanded_template):
            return expanded_template
        if <MASK>:
            absolute_path = self.download(template)
        else:
            absolute_path = os.path.abspath(expanded_template)
        if os.path.exists(absolute_path):
            return self.extract(absolute_path)
    raise CommandError("couldn't handle %s template %s." % (self.app_or_project, template))

def _wrap_result(name: str, data, sparse_index, fill_value, dtype: Dtype | None=None) -> SparseArray:
    """
    wrap op result to have correct dtype
    """
    if name.startswith('__'):
        name = name[2:-2]
    if name in ('eq', 'ne', 'lt', 'gt', 'le', 'ge'):
        dtype = bool
    fill_value = lib.item_from_zerodim(fill_value)
    if <MASK>:
        fill_value = bool(fill_value)
    return SparseArray(data, sparse_index=sparse_index, fill_value=fill_value, dtype=dtype)

@ignore_warnings(category=FutureWarning)
def check_class_weight_classifiers(name, classifier_orig):
    if get_tags(classifier_orig).classifier_tags.multi_class:
        problems = [2, 3]
    else:
        problems = [2]
    for n_centers in problems:
        (X, y) = make_blobs(centers=n_centers, random_state=0, cluster_std=20)
        (X_train, X_test, y_train, y_test) = train_test_split(X, y, test_size=0.5, random_state=0)
        if get_tags(classifier_orig).input_tags.pairwise:
            X_test = rbf_kernel(X_test, X_train)
            X_train = rbf_kernel(X_train, X_train)
        n_centers = len(np.unique(y_train))
        if n_centers == 2:
            class_weight = {0: 1000, 1: 0.0001}
        else:
            class_weight = {0: 1000, 1: 0.0001, 2: 0.0001}
        classifier = clone(classifier_orig).set_params(class_weight=class_weight)
        if hasattr(classifier, 'n_iter'):
            classifier.set_params(n_iter=100)
        if hasattr(classifier, 'max_iter'):
            classifier.set_params(max_iter=1000)
        if <MASK>:
            classifier.set_params(min_weight_fraction_leaf=0.01)
        if hasattr(classifier, 'n_iter_no_change'):
            classifier.set_params(n_iter_no_change=20)
        set_random_state(classifier)
        classifier.fit(X_train, y_train)
        y_pred = classifier.predict(X_test)
        if not get_tags(classifier_orig).classifier_tags.poor_score:
            assert np.mean(y_pred == 0) > 0.87

def ndarrays_to_tensors(*inputs):
    """Convert all ndarrays from `inputs` to tensors. (other things are intact)"""
    from ._ndarray import ndarray
    if len(inputs) == 0:
        return ValueError()
    elif <MASK>:
        input_ = inputs[0]
        if isinstance(input_, ndarray):
            return input_.tensor
        elif isinstance(input_, tuple):
            result = []
            for sub_input in input_:
                sub_result = ndarrays_to_tensors(sub_input)
                result.append(sub_result)
            return tuple(result)
        else:
            return input_
    else:
        assert isinstance(inputs, tuple)
        return ndarrays_to_tensors(inputs)

def len_(s):
    len_override = registry_lookup(len_registry, s)
    if len_override is not None:
        return len_override(s)
    if tensors.is_tensor_array(s):
        return _tf_tensor_array_len(s)
    elif tensors.is_tensor_list(s):
        return _tf_tensor_list_len(s)
    elif <MASK>:
        return _tf_tensor_len(s)
    return _py_len(s)

@timed('Installing packages')
def uv_pip_install(self, *packages: str, prerelease: bool=False, upgrade: bool=False, no_deps: bool=False, **popen_kwargs: Any) -> subprocess.CompletedProcess[str]:
    """Run a pip install command in the virtual environment."""
    uv_pip_args = []
    if VERBOSE:
        uv_pip_args.append('-v')
    if <MASK>:
        uv_pip_args.append('--prerelease')
    if upgrade:
        uv_pip_args.append('--upgrade')
        verb = 'Upgrading'
    else:
        verb = 'Installing'
    if no_deps:
        uv_pip_args.append('--no-deps')
    print(f'{verb} package(s) ({self.pip_source.index_url}):')
    for package in packages:
        print(f'  - {os.path.basename(package)}')
    return self.uv('pip', 'install', *uv_pip_args, *packages, **popen_kwargs)

def __init__(self, frame):

    def pack_hook(x):
        holder = _Holder()
        frame.weak_holders.append(weakref.ref(holder))
        if frame.metadata_fn is not None:
            with torch.no_grad():
                frame.x_metadatas.append(frame.metadata_fn(x))
        return holder

    def unpack_hook(holder):
        gid = torch._C._current_graph_task_id()
        if gid == -1:
            gid = int(uuid.uuid4())
        if not frame.is_recomputed[gid]:
            ctx = frame.input_saver.grad_fn
            args = ctx.get_args(ctx.saved_tensors)
            try:
                with _recomputation_hook(weakref.ref(frame), gid), torch.autograd.enable_grad():
                    _run_fn_with_dynamo_disabled(frame.recompute_fn, *args)
            except _StopRecomputationError:
                pass
            frame.is_recomputed[gid] = True
            frame.check_recomputed_tensors_match(gid)
        _internal_assert(gid in holder.handles)
        if <MASK>:
            raise CheckpointError('torch.utils.checkpoint: Unpack is being triggered for a tensor that was already unpacked once. If you are calling ctx.saved_tensors in backward, make sure to do so only once. Otherwise please open an issue with details on your use case.')
        _internal_assert(holder.handles[gid] in frame.recomputed[gid])
        ret = frame.recomputed[gid][holder.handles[gid]]
        holder.handles[gid] = None
        return ret
    if frame.unpack_error_cb is not None:

        def unpack_hook_with_error_cb(holder):
            try:
                return unpack_hook(holder)
            except CheckpointError as e:
                frame.unpack_error_cb(e)
        super().__init__(pack_hook, unpack_hook_with_error_cb)
    else:
        super().__init__(pack_hook, unpack_hook)

def __str__(self):
    thestr = '0'
    var = self.variable
    coeffs = self.coeffs[NX.logical_or.accumulate(self.coeffs != 0)]
    N = len(coeffs) - 1

    def fmt_float(q):
        s = f'{q:.4g}'
        s = s.removesuffix('.0000')
        return s
    for (k, coeff) in enumerate(coeffs):
        if not iscomplex(coeff):
            coefstr = fmt_float(real(coeff))
        elif real(coeff) == 0:
            coefstr = f'{fmt_float(imag(coeff))}j'
        else:
            coefstr = f'({fmt_float(real(coeff))} + {fmt_float(imag(coeff))}j)'
        power = N - k
        if power == 0:
            if coefstr != '0':
                newstr = f'{coefstr}'
            elif k == 0:
                newstr = '0'
            else:
                newstr = ''
        elif power == 1:
            if coefstr == '0':
                newstr = ''
            elif <MASK>:
                newstr = var
            else:
                newstr = f'{coefstr} {var}'
        elif coefstr == '0':
            newstr = ''
        elif coefstr == 'b':
            newstr = '%s**%d' % (var, power)
        else:
            newstr = '%s %s**%d' % (coefstr, var, power)
        if k > 0:
            if newstr != '':
                if newstr.startswith('-'):
                    thestr = f'{thestr} - {newstr[1:]}'
                else:
                    thestr = f'{thestr} + {newstr}'
        else:
            thestr = newstr
    return _raise_power(thestr)

