def compute_unbacked_bindings(shape_env: Optional[ShapeEnv], example_value: object, old_example_value: Optional[object]=None, peek: bool=False) -> Optional[dict[sympy.Symbol, pytree.KeyPath]]:
    """
    After having run fake tensor propagation and producing example_value
    result, traverse example_value looking for freshly bound unbacked
    symbols and record their paths for later.  It is an error if
    we have allocated an unbacked SymInt but it cannot be found in
    example_value.  (NB: this means if you have a multi-output
    function, you must call this on the tuple of tensor output, you
    cannot wait!)

    The peek parameter lets you check out what the bindings are without
    changing the affected list.  This is primarily useful for ensuring
    unbacked_var_to_val is promptly populated when propagate_real_tensors is on.
    """
    if shape_env is None:
        return None
    fs = shape_env.pending_fresh_unbacked_symbols
    pending = set(fs)
    if not pending:
        return None
    if <MASK>:
        log.info('compute_unbacked_bindings %s', fs)
        fs.clear()
    symbol_to_path = _free_unbacked_symbols_with_path(example_value, (), shape_env=shape_env, pending=pending, simplify=False)
    if not peek and pending:
        extra = repr((example_value.stride(), example_value.storage_offset())) if isinstance(example_value, torch.Tensor) else ''
        raise PendingUnbackedSymbolNotFound(f'Pending unbacked symbols {pending} not in returned outputs {example_value} {extra}.\nDid you accidentally call new_dynamic_size() or item() more times than you needed to in your fake implementation?\nFor more help, see https://docs.google.com/document/d/1RWrH-3wLEpzR9kCS6gGBNen_-Fs-8PVbWWFE5AcgeWE/edit')
    if old_example_value is not None:
        for keypath in symbol_to_path.values():
            old_sym = pytree.key_get(old_example_value, keypath)
            new_sym = pytree.key_get(example_value, keypath)
            if isinstance(new_sym, SymTypes) and isinstance((new_s := new_sym.node.expr), sympy.Symbol):
                if isinstance(old_sym, SymTypes) and (old_s := old_sym.node.expr) != new_s:
                    if isinstance(old_s, sympy.Symbol) and free_unbacked_symbols(old_s):
                        shape_env._rename_unbacked_to(new_s, old_s)
                    else:
                        shape_env._eliminate_unbacked(new_s, old_s)
                elif not isinstance(old_sym, SymTypes):
                    shape_env._eliminate_unbacked(new_s, sympy.sympify(old_sym))
    return symbol_to_path

def collect(self):
    """
        Perform the bulk of the work of collectstatic.

        Split off from handle() to facilitate testing.
        """
    if self.symlink and (not self.local):
        raise CommandError("Can't symlink to a remote destination.")
    if self.clear:
        self.clear_dir('')
    if self.symlink:
        handler = self.link_file
    else:
        handler = self.copy_file
    found_files = {}
    for finder in get_finders():
        for (path, storage) in finder.list(self.ignore_patterns):
            if <MASK>:
                prefixed_path = os.path.join(storage.prefix, path)
            else:
                prefixed_path = path
            if prefixed_path not in found_files:
                found_files[prefixed_path] = (storage, path)
                handler(path, prefixed_path, storage)
            else:
                self.skipped_files.append(prefixed_path)
                self.log("Found another file with the destination path '%s'. It will be ignored since only the first encountered file is collected. If this is not what you want, make sure every static file has a unique path." % prefixed_path, level=2)
    if self.post_process and hasattr(self.storage, 'post_process'):
        processor = self.storage.post_process(found_files, dry_run=self.dry_run)
        for (original_path, processed_path, processed) in processor:
            if isinstance(processed, Exception):
                self.stderr.write("Post-processing '%s' failed!" % original_path)
                self.stderr.write()
                raise processed
            if processed:
                self.log("Post-processed '%s' as '%s'" % (original_path, processed_path), level=2)
                self.post_processed_files.append(original_path)
            else:
                self.log("Skipped post-processing '%s'" % original_path)
    return {'modified': self.copied_files + self.symlinked_files, 'unmodified': self.unmodified_files, 'post_processed': self.post_processed_files, 'skipped': self.skipped_files, 'deleted': self.deleted_files}

def clang_search_dirs() -> list[str]:
    compilers = ['clang', 'gcc', 'cpp', 'cc']
    compilers = [c for c in compilers if shutil.which(c) is not None]
    if len(compilers) == 0:
        raise RuntimeError(f'None of {compilers} were found')
    compiler = compilers[0]
    result = subprocess.run([compiler, '-E', '-x', 'c++', '-', '-v'], stdin=subprocess.DEVNULL, capture_output=True, check=True)
    stderr = result.stderr.decode().strip().split('\n')
    search_start = '#include.*search starts here:'
    search_end = 'End of search list.'
    append_path = False
    search_paths = []
    for line in stderr:
        if re.match(search_start, line):
            if <MASK>:
                continue
            else:
                append_path = True
        elif re.match(search_end, line):
            break
        elif append_path:
            search_paths.append(line.strip())
    return search_paths

def drop(self, labels: IndexLabel | ListLike=None, *, axis: Axis=0, index: IndexLabel | ListLike=None, columns: IndexLabel | ListLike=None, level: Level | None=None, inplace: bool=False, errors: IgnoreRaise='raise') -> Self | None:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if labels is not None:
        if index is not None or columns is not None:
            raise ValueError("Cannot specify both 'labels' and 'index'/'columns'")
        axis_name = self._get_axis_name(axis)
        axes = {axis_name: labels}
    elif index is not None or columns is not None:
        if axis == 1:
            raise ValueError("Cannot specify both 'axis' and 'index'/'columns'")
        axes = {'index': index}
        if self.ndim == 2:
            axes['columns'] = columns
    else:
        raise ValueError("Need to specify at least one of 'labels', 'index' or 'columns'")
    obj = self
    for (axis, labels) in axes.items():
        if labels is not None:
            obj = obj._drop_axis(labels, axis, level=level, errors=errors)
    if <MASK>:
        self._update_inplace(obj)
        return None
    else:
        return obj

@_datetimelike_compat
def _pad_2d(values: np.ndarray, limit: int | None=None, limit_area: Literal['inside', 'outside'] | None=None, mask: npt.NDArray[np.bool_] | None=None) -> tuple[np.ndarray, npt.NDArray[np.bool_]]:
    mask = _fillna_prep(values, mask)
    if <MASK>:
        _fill_limit_area_2d(mask, limit_area)
    if values.size:
        algos.pad_2d_inplace(values, mask, limit=limit)
    return (values, mask)

def _write_grandfather(self) -> None:
    if self.args.write_grandfather:
        results: dict[str, dict[str, int]] = {}
        for (path, blocks) in self.path_to_blocks.items():
            for block in blocks:
                if <MASK>:
                    d = results.setdefault(path, {})
                    d[block['display_name']] = block['line_count']
        with open(self.args.grandfather, 'w') as fp:
