def get_operator_from(dependency: str) -> str | None:
    if '<=' in dependency:
        operator = '<='
    elif <MASK>:
        operator = '>='
    elif '=' in dependency:
        operator = '='
    elif '>' in dependency:
        operator = '>'
    elif '<' in dependency:
        operator = '<'
    else:
        operator = None
    return operator

def sample_inputs_index(op_info, device, dtype, requires_grad, reference=False, **kwargs):
    add = 'index_add' in op_info.name
    copy = 'index_copy' in op_info.name
    fill = 'index_fill' in op_info.name
    if reference:
        make_arg = partial(torch.ones, device=device, dtype=dtype, requires_grad=requires_grad)
        make_idx = partial(torch.zeros, device=device, dtype=torch.int64)
    else:
        make_arg = partial(make_tensor, device=device, dtype=dtype, requires_grad=requires_grad)
        if copy or add:
            make_idx = partial(torch.randperm, device=device, dtype=torch.int64)
        else:

            def make_idx(n):
                return make_tensor((n,), device=device, dtype=torch.int64, low=0, high=n)
    shapes = [(), (1,), (S, S)]
    if <MASK>:
        if dtype == torch.bool:
            alphas = (True, False)
        else:
            alphas = (-1, 0, 2)
    else:
        alphas = (None,)
    if fill:
        values = (make_arg((1,)).item(), make_arg(()))
    else:
        values = (None,)
    for (shape, alpha, value) in product(shapes, alphas, values):
        t = make_arg(shape)
        args = []
        dim = -1 if t.ndim == 2 else 0
        args.append(dim)
        idx = make_idx(t.shape[dim] if t.ndim != 0 else 1)
        args.append(idx)
        if copy or add:
            args.append(make_arg(shape))
        elif fill:
            args.append(value)
        args = tuple(args)
        kwargs = {} if alpha is None else {'alpha': alpha}
        yield SampleInput(t, args=args, kwargs=kwargs)

def helper(treespec: TreeSpec, tree: PyTree, subtrees: list[PyTree]) -> None:
    if treespec.is_leaf():
        subtrees.append(tree)
        return
    node_type = _get_node_type(tree)
    if treespec.type not in BUILTIN_TYPES:
        if node_type != treespec.type:
            raise ValueError(f'Type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
        (children, context) = flatten_fn(tree)
        if len(children) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(children)}.')
        if context != treespec.context:
            raise ValueError(f'Node context mismatch for custom node type {treespec.type!r}.')
    else:
        both_standard_dict = treespec.type in STANDARD_DICT_TYPES and node_type in STANDARD_DICT_TYPES
        if not both_standard_dict and node_type != treespec.type:
            raise ValueError(f'Node type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        if len(tree) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(tree)}.')
        if both_standard_dict:
            dict_context = treespec.context if treespec.type is not defaultdict else treespec.context[1]
            expected_keys = dict_context
            got_key_set = set(tree)
            expected_key_set = set(expected_keys)
            if <MASK>:
                missing_keys = expected_key_set.difference(got_key_set)
                extra_keys = got_key_set.difference(expected_key_set)
                message = ''
                if missing_keys:
                    message += f'; missing key(s): {missing_keys}'
                if extra_keys:
                    message += f'; extra key(s): {extra_keys}'
                raise ValueError(f'Node keys mismatch{message}.')
            children = [tree[key] for key in expected_keys]
        else:
            flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
            (children, context) = flatten_fn(tree)
            if node_type is not deque and context != treespec.context:
                raise ValueError(f'Node context mismatch for node type {treespec.type!r}; expected {treespec.context!r}, but got {context!r}.')
    for (subtree, subspec) in zip(children, treespec.children_specs):
        helper(subspec, subtree, subtrees)

def _has_constant_mask(self, tree: IterationRangesRoot) -> bool:
    if self.is_native_matmul:
        if V.graph.sizevars.statically_known_lt(tree.numel, 16):
            return False
    if not self.optimize_mask:
        return False
    if self.fixed_config and f'{tree.prefix.upper()}BLOCK' in self.fixed_config:
        if self.fixed_config[f'{tree.prefix.upper()}BLOCK'] == 1:
            return True
    elif <MASK>:
        return True
    if tree.is_reduction and self.persistent_reduction:
        max_block = self._get_persistent_RBLOCK(tree.numel)
    elif tree.prefix == 'x' and self.no_x_dim:
        max_block = 1
    else:
        max_block = self.max_block(tree.prefix)
    if tree.is_reduction and self.cooperative_reduction:
        max_block = max_block * self.max_rsplit()
    if V.graph.sizevars.statically_known_multiple_of(tree.numel, max_block):
        return tree.grid_dim != 1 or tree.has_zdim or V.graph.sizevars.statically_known_leq(tree.numel, get_max_y_grid())
    return False

def args_codegen(self, arg_operations):
    """Generate argument creation code for default template."""
    code_lines = []
    code_lines.extend(['# Sentinel tensor to ensure gradient computation', 'sentinel = torch.tensor(1.0, requires_grad=True)', ''])
    if arg_operations:
        for (i, (node_id, spec)) in enumerate(arg_operations):
            arg_name = f'arg_{i}'
            if isinstance(spec, ScalarSpec):
                dtype_str = f'torch.{spec.dtype}'.replace('torch.torch.', 'torch.')
                if spec.dtype in [torch.int8, torch.int16, torch.int32, torch.int64]:
                    code_lines.append(f'{arg_name} = int(torch.randint(5, 30, ()).item())')
                elif <MASK>:
                    code_lines.append(f'{arg_name} = bool(torch.randint(0, 2, ()).item())')
                else:
                    code_lines.append(f'{arg_name} = float(torch.randn((), dtype={dtype_str}).item())')
            elif isinstance(spec, TensorSpec):
                size_str = str(spec.size)
                dtype_str = f'torch.{spec.dtype}'.replace('torch.torch.', 'torch.')
                if spec.size:
                    max_offset = 0
                    for (dim_size, stride) in zip(spec.size, spec.stride):
                        if dim_size > 1:
                            max_offset += (dim_size - 1) * abs(stride)
                    storage_size = max_offset + 1
                else:
                    storage_size = 1
                stride_str = str(spec.stride)
                if spec.dtype in [torch.int8, torch.int16, torch.int32, torch.int64]:
                    min_val = 5
                    max_val = 30
                    code_lines.append(f'{arg_name} = torch.as_strided(torch.randint({min_val}, {max_val}, ({storage_size},)).to({dtype_str}), {size_str}, {stride_str})')
                elif spec.dtype == torch.bool:
                    code_lines.append(f'{arg_name} = torch.as_strided(torch.randint(0, 2, ({storage_size},), dtype=torch.int8).bool(), {size_str}, {stride_str})')
                else:
                    code_lines.append(f'{arg_name} = torch.as_strided(torch.randn({storage_size}).to({dtype_str}), {size_str}, {stride_str})')
    return code_lines

@register_meta([aten._fft_r2c.default, aten._fft_r2c.out])
@out_wrapper()
def meta_fft_r2c(self, dim, normalization, onesided):
    torch._check(self.dtype.is_floating_point)
    input_sizes = list(self.size())
    out_sizes = list(input_sizes)
    last_dim = dim[-1]
    last_dim_halfsize = input_sizes[last_dim] // 2 + 1
    onesided_sizes = list(input_sizes)
    onesided_sizes[last_dim] = last_dim_halfsize
    if onesided:
        out_sizes[last_dim] = last_dim_halfsize
    if device_hint(self) == 'cuda' or device_hint(self) == 'xpu':
        output = self.new_empty(out_sizes, dtype=utils.corresponding_complex_dtype(self.dtype))
        working_tensor = self
        if <MASK>:
            _exec_fft(output, working_tensor, out_sizes, dim, forward=True)
        else:
            target_sizes = out_sizes if len(dim) == 1 else onesided_sizes
            _exec_fft(output, working_tensor, target_sizes, [last_dim], forward=True)
            if len(dim) > 1:
                working_tensor = self.new_empty(out_sizes, dtype=utils.corresponding_complex_dtype(self.dtype))
            sorted_dims = dim[:-1]
            while sorted_dims:
                (output, working_tensor) = (working_tensor, output)
                strides = working_tensor.stride()
                sorted_dims.sort(key=lambda i: strides[i], reverse=True)
                max_dims = min(cufft_max_ndim, len(sorted_dims))
                last_dims = sorted_dims[len(sorted_dims) - max_dims:]
                _exec_fft(output, working_tensor, onesided_sizes, last_dims, forward=True)
                sorted_dims = sorted_dims[:len(sorted_dims) - max_dims]
        if not onesided:
            if output.size(last_dim) != out_sizes[last_dim]:
                working_tensor.resize_(out_sizes, memory_format=torch.contiguous_format)
                output = working_tensor
        return output
    else:
        return self.new_empty(out_sizes, dtype=utils.corresponding_complex_dtype(self.dtype))

def searchsorted(self, value, side: Literal['left', 'right']='left', sorter: NumpySorter | None=None) -> npt.NDArray[np.intp] | np.intp:
    if side not in {'left', 'right'} or sorter is not None:
        return super().searchsorted(value=value, side=side, sorter=sorter)
    was_scalar = False
    if is_scalar(value):
        was_scalar = True
        array_value = np.array([value])
    else:
        array_value = np.asarray(value)
    if array_value.dtype.kind not in 'iu':
        return super().searchsorted(value=value, side=side, sorter=sorter)
    if (flip := (self.step < 0)):
        rng = self._range[::-1]
        start = rng.start
        step = rng.step
        shift = side == 'right'
    else:
        start = self.start
        step = self.step
        shift = side == 'left'
    result = (array_value - start - int(shift)) // step + 1
    if <MASK>:
        result = len(self) - result
    result = np.maximum(np.minimum(result, len(self)), 0)
    if was_scalar:
        return np.intp(result.item())
    return result.astype(np.intp, copy=False)

def invoke_getitem(iinfo: IndexingInfo) -> Any:
    if <MASK>:
        self_tensor = iinfo.self_tensor
        tup = slice_to_tuple(iinfo.flat_inputs)
        if self_tensor is None:
            raise RuntimeError('Cannot getitem on None tensor')
        rtensor = self_tensor[tup]
    else:
        rtensor = iinfo.self_tensor
        if rtensor is None:
            raise RuntimeError('Cannot getitem on None tensor')
    from . import Tensor
    return Tensor.from_positional(rtensor, iinfo.result_levels, iinfo.has_device)

def get_matching_overload(node: torch.fx.Node, overloads: Sequence[_registration.OnnxDecompMeta]) -> tuple[Callable | None, str]:
    """Get the overload that matches the node's arguments.

    Args:
        node: The node to match.
        overloads: The OnnxDecompMeta with overloads and their signatures to match against.

    Returns:
        A tuple containing the matched overload and a string describing the reason for failure or success.
    """
    if not hasattr(node.target, '_schema'):
        return (overloads[0].onnx_function, 'The node target does not have a schema. Return the first one.')
    named_args = _get_named_fx_node_args(node)
    schema_args: dict[str, torch.Argument] = {arg.name: arg for arg in node.target._schema.arguments}
    failure_messages: list[str] = []
    for overload in overloads:
        assigned_types: dict[str, ir.TypeProtocol] = {}
        fail_reason = ''
        if overload.signature is None:
            return (overload.onnx_function, 'The overload does not have a signature. Assuming it is a custom op and matching it.')
        for param in overload.signature:
            if param.name not in schema_args and param.required:
                fail_reason = 'Required parameter not supplied'
                break
            if param.name in named_args:
                arg = named_args[param.name]
            elif param.name in schema_args and schema_args[param.name].has_default_value():
                arg = schema_args[param.name].default_value
            elif param.has_default():
                arg = param.default
            else:
                fail_reason = 'Parameter not provided'
                break
            if isinstance(param, _schemas.Parameter):
                if isinstance(arg, torch.Tensor):
                    arg = _get_type_from_tensor(arg)
                if isinstance(arg, (list, tuple)) and any((isinstance(t, torch.fx.Node) for t in arg)):
                    first_tensor = _get_first_tensor_in_node_list(arg)
                    assert first_tensor is not None
                    arg = ir.SequenceType(_get_type_from_tensor(first_tensor))
                elif isinstance(arg, torch.fx.Node):
                    meta_val = arg.meta['val']
                    arg = _get_type_from_tensor(meta_val)
                if not _param_type_compatible_with_arg(param, arg, assigned_types):
                    fail_reason = f'Parameter type not compatible with argument: param=`{param}`, assigned_types=`{assigned_types}`, arg=`{arg}`'
                    break
            elif isinstance(param, _schemas.AttributeParameter):
                if not _attribute_type_compatible_with_arg(param, arg):
                    fail_reason = f'Attribute type not compatible with argument: param=`{param}`, arg=`{arg}`'
                    break
            else:
                raise TypeError(f'Unknown parameter type: {type(param)}')
        if <MASK>:
            return (overload.onnx_function, 'Successfully matched overload')
        else:
            failure_messages.append(f'- Failed to match overload `{overload}`: {fail_reason}')
    return (None, f'All overloads did not match the node `{node.format_node()}`.\n' + '\n'.join(failure_messages))

def __init__(self, num_thresholds=200, curve='ROC', summation_method='interpolation', name=None, dtype=None, thresholds=None, multi_label=False, num_labels=None, label_weights=None, from_logits=False):
    if <MASK>:
        raise ValueError('Invalid curve: "{}". Valid options are: "{}"'.format(curve, list(metrics_utils.AUCCurve)))
    if isinstance(summation_method, metrics_utils.AUCSummationMethod) and summation_method not in list(metrics_utils.AUCSummationMethod):
        raise ValueError('Invalid summation method: "{}". Valid options are: "{}"'.format(summation_method, list(metrics_utils.AUCSummationMethod)))
    if thresholds is not None:
        self.num_thresholds = len(thresholds) + 2
        thresholds = sorted(thresholds)
        self._thresholds_distributed_evenly = metrics_utils.is_evenly_distributed_thresholds(np.array([0.0] + thresholds + [1.0]))
    else:
        if num_thresholds <= 1:
            raise ValueError('`num_thresholds` must be > 1.')
        self.num_thresholds = num_thresholds
        thresholds = [(i + 1) * 1.0 / (num_thresholds - 1) for i in range(num_thresholds - 2)]
        self._thresholds_distributed_evenly = True
    self._thresholds = np.array([0.0 - backend.epsilon()] + thresholds + [1.0 + backend.epsilon()])
    if isinstance(curve, metrics_utils.AUCCurve):
        self.curve = curve
    else:
        self.curve = metrics_utils.AUCCurve.from_str(curve)
    if isinstance(summation_method, metrics_utils.AUCSummationMethod):
        self.summation_method = summation_method
    else:
        self.summation_method = metrics_utils.AUCSummationMethod.from_str(summation_method)
    super(AUC, self).__init__(name=name, dtype=dtype)
    self.multi_label = multi_label
    if label_weights is not None:
        label_weights = constant_op.constant(label_weights, dtype=self.dtype)
        checks = [check_ops.assert_non_negative(label_weights, message='All values of `label_weights` must be non-negative.')]
        with ops.control_dependencies(checks):
            self.label_weights = label_weights
    else:
        self.label_weights = None
    self._from_logits = from_logits
    self._built = False
    if self.multi_label:
        if num_labels:
            shape = tensor_shape.TensorShape([None, num_labels])
            self._build(shape)
    else:
        if num_labels:
            raise ValueError('`num_labels` is needed only when `multi_label` is True.')
        self._build(None)

def gradcheck_with_sparse_support(func, inputs, **kwargs):
    """
        Create gradcheck with support for sparse tensors.

        Same as :func:`torch.autograd.gradcheck` but with sparse tensors inputs and outputs support.
        """
    masked = kwargs.pop('masked', False)
    sparse_layouts = {torch.sparse_coo, torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}
    sparse_compressed_layouts = {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}
    sparse_block_layouts = {torch.sparse_bsr, torch.sparse_bsc}
    STRIDED_REPRESENTATION = '__STRIDED_REPRESENTATION__'

    def convert_to_strided_representation(args):
        """Convert differentiable non-strided tensors to a representation containing differentiable strided tensors."""
        if not isinstance(args, (list, tuple)):
            args = (args,)
        new_args: list[Any] = []
        for obj in args:
            if <MASK>:
                d = {'layout': obj.layout, 'shape': obj.shape}
                if not masked:
                    batch_dim = obj.ndim - obj.dense_dim() - obj.sparse_dim()
                    blocksize = obj.values().shape[batch_dim + 1:batch_dim + 3] if obj.layout in sparse_block_layouts else None
                    full_mask = torch.ones(obj.shape, device=obj.device, dtype=torch.bool).to_sparse(layout=obj.layout, blocksize=blocksize, dense_dim=obj.dense_dim())
                    obj = obj.to_dense().sparse_mask(full_mask)
                if obj.layout is torch.sparse_coo:
                    d.update(indices=obj._indices(), is_coalesced=obj.is_coalesced())
                    values = obj._values()
                elif obj.layout in {torch.sparse_csr, torch.sparse_bsr}:
                    d.update(compressed_indices=obj.crow_indices(), plain_indices=obj.col_indices())
                    values = obj.values()
                else:
                    d.update(compressed_indices=obj.ccol_indices(), plain_indices=obj.row_indices())
                    values = obj.values()
                new_args.extend((STRIDED_REPRESENTATION, d, values.requires_grad_(True)))
            else:
                new_args.append(obj)
        return tuple(new_args)

    def restore_from_strided_representation(args):
        """Restore non-strided differentiable tensosr from their strided representations."""
        new_args = []
        args = list(args)
        while args:
            a = args.pop(0)
            if a == STRIDED_REPRESENTATION:
                (d, values) = (args.pop(0), args.pop(0))
                if d['layout'] is torch.sparse_coo:
                    a = torch.sparse_coo_tensor(d['indices'], values, size=d['shape'], is_coalesced=d['is_coalesced'])
                elif d['layout'] in sparse_compressed_layouts:
                    a = torch.sparse_compressed_tensor(d['compressed_indices'], d['plain_indices'], values, size=d['shape'], layout=d['layout'])
                else:
                    raise NotImplementedError(f"conversion of {d['layout']} strided representation to tensor")
            new_args.append(a)
        return tuple(new_args)

    def func_wrapper(*args, **kwargs):
        restored_args = restore_from_strided_representation(args)
        outputs = func(*restored_args, **kwargs)
        strided_outputs = tuple(outputs) if isinstance(outputs, (list, tuple)) else (outputs,)
        strided_outputs = tuple((o.to_dense(masked_grad=masked) if isinstance(o, torch.Tensor) and o.requires_grad and (o.layout in sparse_layouts) else o for o in strided_outputs))
        return strided_outputs if isinstance(outputs, (list, tuple)) else strided_outputs[0]
    args = (func_wrapper, convert_to_strided_representation(inputs))
    return gradcheck(*args, **kwargs)

def check_minus_one(result, func, cargs):
    """Error checking on routines that should not return -1."""
    if <MASK>:
        raise GEOSException('Error encountered in GEOS C function "%s".' % func.__name__)
    else:
        return result

def _create_tpu_strategy():
    FLAGS = flags.FLAGS
    global _did_connect_to_cluster
    global _topology
    try:
        resolver = tpu_cluster_resolver.TPUClusterResolver()
        did_automatically_resolve = True
    except ValueError:
        did_automatically_resolve = False
        resolver = tpu_cluster_resolver.TPUClusterResolver(tpu=hasattr(FLAGS, 'tpu') and FLAGS.tpu or '', zone=hasattr(FLAGS, 'zone') and FLAGS.zone or None, project=hasattr(FLAGS, 'project') and FLAGS.project or None)
    if <MASK>:
        if getattr(FLAGS, 'tpu', '') or did_automatically_resolve:
            remote.connect_to_cluster(resolver)
            _did_connect_to_cluster = True
        _topology = tpu_cluster_resolver.initialize_tpu_system(resolver)
    device_assignment = None
    if use_single_core:
        device_assignment = device_assignment_lib.DeviceAssignment(_topology, core_assignment=device_assignment_lib.SINGLE_CORE_ASSIGNMENT)
    if tf2.enabled():
        strategy = tpu_lib.TPUStrategyV2(resolver, device_assignment, experimental_spmd_xla_partitioning=enable_spmd_xla_paritioning, **kwargs)
    else:
        strategy = tpu_lib.TPUStrategyV1(resolver, steps_per_run, device_assignment, **kwargs)
    if enable_packed_variable and enable_spmd_xla_paritioning:
        raise ValueError('Packed Variable is not compatible with SPMD mode')
    strategy._enable_packed_variable_in_eager_mode = enable_packed_variable
    return strategy

def _parse_input_meta_graph_proto(input_graph: str, input_binary: bool) -> meta_graph_pb2.MetaGraphDef:
    """Parses input tensorflow graph into MetaGraphDef proto."""
    if not gfile.Exists(input_graph):
        raise IOError("Input meta graph file '" + input_graph + "' does not exist!")
    input_meta_graph_def = meta_graph_pb2.MetaGraphDef()
    mode = 'rb' if input_binary else 'r'
    with gfile.GFile(input_graph, mode) as f:
        if <MASK>:
            input_meta_graph_def.ParseFromString(f.read())
        else:
            text_format.Merge(f.read(), input_meta_graph_def)
    print("Loaded meta graph file '" + input_graph)
    return input_meta_graph_def

def check_graph_consistency(tensor=None, method='add_loss', force_raise=False):
    """Checks that tensors passed to `add_*` method match the Keras graph.

  When one of the `add_*` method is called inside a V2 conditional branch,
  the underlying tensor gets created in a FuncGraph managed by control_flow_v2.
  We need to raise clear error messages in such cases.

  Args:
    tensor: Tensor to check, or `False` if it is known that an error
      should be raised.
    method: Caller method, one of {'add_metric', 'add_loss', 'add_update'}.
    force_raise: If an error should be raised regardless of `tensor`.

  Raises:
    RuntimeError: In case of an out-of-graph tensor.
  """
    if force_raise or (ops.executing_eagerly_outside_functions() and hasattr(tensor, 'graph') and tensor.graph.is_control_flow_graph):
        if method == 'activity_regularizer':
            bad_example = "
      class TestModel(tf.keras.Model):

        def __init__(self):
          super(TestModel, self).__init__(name='test_model')
          self.dense = tf.keras.layers.Dense(2, activity_regularizer='l2')

        def call(self, x, training=None):
          if training:
            return self.dense(x)
          else:
            return self.dense(x)
      "
            correct_example = "
      class TestModel(tf.keras.Model):

        def __init__(self):
          super(TestModel, self).__init__(name='test_model')
          self.dense = tf.keras.layers.Dense(2, activity_regularizer='l2')

        def call(self, x, training=None):
          return self.dense(x)
      "
            raise RuntimeError('You are using a layer with `activity_regularizer` in a control flow branch, e.g.:
{bad_example}
This is currently not supported. Please move your call to the layer with `activity_regularizer` out of the control flow branch, e.g.:
{correct_example}
You can also resolve this by marking your outer model/layer dynamic (eager-only) by passing `dynamic=True` to the layer constructor. Any kind of control flow is supported with dynamic layers. Note that using `dynamic=True` requires you to implement static shape inference in the `compute_output_shape(input_shape)` method.'.format(bad_example=bad_example, correct_example=correct_example))
        if method == 'add_metric':
            bad_example = "
      def call(self, inputs, training=None):
        if training:
          metric = compute_metric(inputs)
          self.add_metric(metric, name='my_metric', aggregation='mean')
        return inputs
      "
            correct_example = "
      def call(self, inputs, training=None):
        if training:
          metric = compute_metric(inputs)
        else:
          metric = 0.
        self.add_metric(metric, name='my_metric', aggregation='mean')
        return inputs
      "
        elif <MASK>:
            bad_example = '
      def call(self, inputs, training=None):
        if training:
          loss = compute_loss(inputs)
          self.add_loss(loss)
        return inputs
      '
            correct_example = '
      def call(self, inputs, training=None):
        if training:
          loss = compute_loss(inputs)
        else:
          loss = 0.
        self.add_loss(loss)
        return inputs
      '
        else:
            bad_example = '
      def call(self, inputs, training=None):
        if training:
          self.add_update(self.w.assign_add(1))
        return inputs
      '
            correct_example = '
      def call(self, inputs, training=None):
        if training:
          increment = 1
        else:
          increment = 0
        self.add_update(self.w.assign_add(increment))
        return inputs
      '
        raise RuntimeError('You are using the method `{method}` in a control flow branch in your layer, e.g.:
{bad_example}
This is not currently supported. Please move your call to {method} out of the control flow branch, e.g.:
{correct_example}
You can also resolve this by marking your layer as dynamic (eager-only) by passing `dynamic=True` to the layer constructor. Any kind of control flow is supported with dynamic layers. Note that using `dynamic=True` requires you to implement static shape inference in the `compute_output_shape(input_shape)` method.'.format(method=method, bad_example=bad_example, correct_example=correct_example))

def save(self, *, force_insert=False, force_update=False, using=None, update_fields=None):
    """
        Save the current instance. Override this in a subclass if you want to
        control the saving process.

        The 'force_insert' and 'force_update' parameters can be used to insist
        that the "save" must be an SQL insert or update (or equivalent for
        non-SQL backends), respectively. Normally, they should not be set.
        """
    self._prepare_related_fields_for_save(operation_name='save')
    using = using or router.db_for_write(self.__class__, instance=self)
    if force_insert and (force_update or update_fields):
        raise ValueError('Cannot force both insert and updating in model saving.')
    deferred_non_generated_fields = {f.attname for f in self._meta.concrete_fields if f.attname not in self.__dict__ and f.generated is False}
    if <MASK>:
        if not update_fields:
            return
        update_fields = frozenset(update_fields)
        field_names = self._meta._non_pk_concrete_field_names
        not_updatable_fields = update_fields.difference(field_names)
        if not_updatable_fields:
            raise ValueError('The following fields do not exist in this model, are m2m fields, primary keys, or are non-concrete fields: %s' % ', '.join(not_updatable_fields))
    elif not force_insert and deferred_non_generated_fields and (using == self._state.db) and self._is_pk_set():
        field_names = set()
        pk_fields = self._meta.pk_fields
        for field in self._meta.concrete_fields:
            if field not in pk_fields and (not hasattr(field, 'through')):
                field_names.add(field.attname)
        loaded_fields = field_names.difference(deferred_non_generated_fields)
        if loaded_fields:
            update_fields = frozenset(loaded_fields)
    self.save_base(using=using, force_insert=force_insert, force_update=force_update, update_fields=update_fields)

@lru_cache
def enabled_metric_tables_impl(config_str: str) -> OrderedSet[str]:
    enabled: OrderedSet[str] = OrderedSet()
    for name in config_str.split(','):
        name = name.strip()
        if <MASK>:
            continue
        assert name in REGISTERED_METRIC_TABLES, f'Metric table name {name} is not registered'
        enabled.add(name)
    return enabled

def generate_sources(self, sources, extension):
    new_sources = []
    func_sources = []
    for source in sources:
        if is_string(source):
            new_sources.append(source)
        else:
            func_sources.append(source)
    if not func_sources:
        return new_sources
    if self.inplace and (not is_sequence(extension)):
        build_dir = self.ext_target_dir
    else:
        if is_sequence(extension):
            name = extension[0]
        else:
            name = extension.name
        build_dir = os.path.join(*[self.build_src] + name.split('.')[:-1])
    self.mkpath(build_dir)
    if self.verbose_cfg:
        new_level = log.INFO
    else:
        new_level = log.WARN
    old_level = log.set_threshold(new_level)
    for func in func_sources:
        source = func(extension, build_dir)
        if <MASK>:
            continue
        if is_sequence(source):
            [log.info("  adding '%s' to sources." % (s,)) for s in source]
            new_sources.extend(source)
        else:
            log.info("  adding '%s' to sources." % (source,))
            new_sources.append(source)
    log.set_threshold(old_level)
    return new_sources

def resolve_expression_parameter(self, compiler, connection, sql, param):
    params = [param]
    if hasattr(param, 'resolve_expression'):
        param = param.resolve_expression(compiler.query)
    if <MASK>:
        (sql, params) = compiler.compile(param)
    return (sql, params)

def load_app(self) -> Flask:
    """Loads the Flask app (if not yet loaded) and returns it.  Calling
        this multiple times will just result in the already loaded app to
        be returned.
        """
    if self._loaded_app is not None:
        return self._loaded_app
    app: Flask | None = None
    if self.create_app is not None:
        app = self.create_app()
    elif self.app_import_path:
        (path, name) = (re.split(':(?![\\\\/])', self.app_import_path, maxsplit=1) + [None])[:2]
        import_name = prepare_import(path)
        app = locate_app(import_name, name)
    else:
        for path in ('wsgi.py', 'app.py'):
            import_name = prepare_import(path)
            app = locate_app(import_name, None, raise_if_not_found=False)
            if app is not None:
                break
    if <MASK>:
        raise NoAppException("Could not locate a Flask application. Use the 'flask --app' option, 'FLASK_APP' environment variable, or a 'wsgi.py' or 'app.py' file in the current directory.")
    if self.set_debug_flag:
        app.debug = get_debug_flag()
    self._loaded_app = app
    return app

def _from_ctypes_scalar(t):
    """
    Return the dtype type with endianness included if it's the case
    """
    if getattr(t, '__ctype_be__', None) is t:
        return np.dtype('>' + t._type_)
    elif <MASK>:
        return np.dtype('<' + t._type_)
    else:
        return np.dtype(t._type_)

