def _sort_migrations(self):
    """
        Reorder to make things possible. Reordering may be needed so FKs work
        nicely inside the same app.
        """
    for (app_label, ops) in sorted(self.generated_operations.items()):
        ts = TopologicalSorter()
        for op in ops:
            ts.add(op)
            for dep in op._auto_deps:
                dep = self._resolve_dependency(dep)[0]
                if <MASK>:
                    continue
                ts.add(op, *(x for x in ops if self.check_dependency(x, dep)))
        self.generated_operations[app_label] = list(ts.static_order())

def _check_batch_shape_possibly_add_asserts(self):
    """Static check of init arg `batch_shape`, possibly add asserts."""
    if self._batch_shape_arg is None:
        return
    if <MASK>:
        self._batch_shape_arg = control_flow_ops.with_dependencies([check_ops.assert_rank(self._batch_shape_arg, 1, message='Argument batch_shape must be a 1-D Tensor.'), check_ops.assert_non_negative(self._batch_shape_arg, message='Argument batch_shape must be non-negative.')], self._batch_shape_arg)
    if not self._batch_shape_arg.dtype.is_integer:
        raise TypeError('Argument batch_shape must be integer type.  Found: %s' % self._batch_shape_arg)
    if self._batch_shape_static is None:
        return
    if self._batch_shape_static.ndim != 1:
        raise ValueError('Argument batch_shape must be a 1-D Tensor.  Found: %s' % self._batch_shape_static)
    if np.any(self._batch_shape_static < 0):
        raise ValueError('Argument batch_shape must be non-negative.  Found:%s' % self._batch_shape_static)

def visit_Return(self, node):
    values = self.visit(node.value)
    if self.symbol_table.in_scf_scope():
        self.emit('\nscf.yield ')
    else:
        self.emit('\ntfr.return ')
    if not values:
        return
    if <MASK>:
        (vals, tys) = zip(*values)
    else:
        vals = values[0]
        tys = values[1]
    if isinstance(tys, list) or isinstance(tys, tuple):
        tys = [str(t) for t in tys]
        self._emit_with_loc('{} : {}'.format(', '.join(vals), ', '.join(tys)), node)
    elif tys != TFRTypes.NONE:
        self._emit_with_loc('{} : {}'.format(vals, tys), node)

def get_top_k_choices(self, top_k: int, always_included: Optional[list[str]]=None) -> Optional[list[Choice]]:
    if not self.satisfies_precondition():
        return None
    if torch._inductor.config.use_autoheuristic(self.name):
        if <MASK>:
            self.context.apply_operations(self.augment_context)
        controller = LearnedHeuristicController(self.metadata, self.context)
        choices = controller.get_decisions_ranked(top_k)
        if choices is None:
            return None
        if always_included is not None:
            for choice in always_included:
                if choice not in choices:
                    choices.append(choice)
        return choices
    return None

def _set_call_arg_value(self, arg_name, new_value, args, kwargs, inputs_in_args=False, pop_kwarg_if_none=False):
    arg_pos = self._call_fn_arg_positions.get(arg_name, None)
    if arg_pos is not None:
        if not inputs_in_args:
            arg_pos = arg_pos - 1
        if len(args) > arg_pos:
            args = list(args)
            args[arg_pos] = new_value
            return (args, kwargs)
    if <MASK>:
        kwargs.pop(arg_name, None)
    else:
        kwargs[arg_name] = new_value
    return (args, kwargs)

def __iter__(self):
    size = None
    all_buffer = []
    filter_res = []
    for df in self.source_datapipe:
        if size is None:
            size = len(df.index)
        for i in range(len(df.index)):
            all_buffer.append(df[i:i + 1])
            filter_res.append(self.filter_fn(df.iloc[i]))
    buffer = []
    for (df, res) in zip(all_buffer, filter_res):
        if res:
            buffer.append(df)
            if <MASK>:
                yield df_wrapper.concat(buffer)
                buffer = []
    if buffer:
        yield df_wrapper.concat(buffer)

def assert_input_compatibility(input_spec, inputs, layer_name):
    """Checks compatibility between the layer and provided inputs.

  This checks that the tensor(s) `inputs` verify the input assumptions
  of a layer (if any). If not, a clear and actional exception gets raised.

  Args:
      input_spec: An InputSpec instance, list of InputSpec instances, a nested
          structure of InputSpec instances, or None.
      inputs: Input tensor, list of input tensors, or a nested structure of
          input tensors.
      layer_name: String, name of the layer (for error message formatting).

  Raises:
      ValueError: in case of mismatch between
          the provided inputs and the expectations of the layer.
  """
    if not input_spec:
        return
    input_spec = nest.flatten(input_spec)
    if isinstance(inputs, dict):
        names = [spec.name for spec in input_spec]
        if all(names):
            list_inputs = []
            for name in names:
                if name not in inputs:
                    raise ValueError('Missing data for input "%s". You passed a data dictionary with keys %s. Expected the following keys: %s' % (name, list(inputs.keys()), names))
                list_inputs.append(inputs[name])
            inputs = list_inputs
    inputs = nest.flatten(inputs)
    for x in inputs:
        if not hasattr(x, 'shape'):
            raise TypeError('Inputs to a layer should be tensors. Got: %s' % (x,))
    if len(inputs) != len(input_spec):
        raise ValueError('Layer ' + layer_name + ' expects ' + str(len(input_spec)) + ' input(s), but it received ' + str(len(inputs)) + ' input tensors. Inputs received: ' + str(inputs))
    for (input_index, (x, spec)) in enumerate(zip(inputs, input_spec)):
        if spec is None:
            continue
        shape = tensor_shape.TensorShape(x.shape)
        if shape.rank is None:
            return
        if spec.ndim is not None and (not spec.allow_last_axis_squeeze):
            ndim = shape.rank
            if ndim != spec.ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected ndim=' + str(spec.ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.max_ndim is not None:
            ndim = x.shape.rank
            if <MASK>:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected max_ndim=' + str(spec.max_ndim) + ', found ndim=' + str(ndim))
        if spec.min_ndim is not None:
            ndim = x.shape.rank
            if ndim is not None and ndim < spec.min_ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: : expected min_ndim=' + str(spec.min_ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.dtype is not None:
            if x.dtype.name != spec.dtype:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected dtype=' + str(spec.dtype) + ', found dtype=' + str(x.dtype))
        shape_as_list = shape.as_list()
        if spec.axes:
            for (axis, value) in spec.axes.items():
                if hasattr(value, 'value'):
                    value = value.value
                if value is not None and shape_as_list[int(axis)] not in {value, None}:
                    raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected axis ' + str(axis) + ' of input shape to have value ' + str(value) + ' but received input with shape ' + display_shape(x.shape))
        if spec.shape is not None and shape.rank is not None:
            spec_shape = spec.shape
            if spec.allow_last_axis_squeeze:
                if shape_as_list and shape_as_list[-1] == 1:
                    shape_as_list = shape_as_list[:-1]
                if spec_shape and spec_shape[-1] == 1:
                    spec_shape = spec_shape[:-1]
            for (spec_dim, dim) in zip(spec_shape, shape_as_list):
                if spec_dim is not None and dim is not None:
                    if spec_dim != dim:
                        raise ValueError('Input ' + str(input_index) + ' is incompatible with layer ' + layer_name + ': expected shape=' + str(spec.shape) + ', found shape=' + display_shape(x.shape))

def _onnx_unsupported(op_name: str, value: _C.Value | None=None) -> NoReturn:
    message = f'Unsupported: ONNX export of operator {op_name}. Please feel free to request support or submit a pull request on PyTorch GitHub: {_constants.PYTORCH_GITHUB_ISSUES_URL}'
    if <MASK>:
        raise errors.SymbolicValueError(message, value)
    raise errors.OnnxExporterError(message)

def benchmark(self, *args: list[Any], out: torch.Tensor) -> float:
    import torch._inductor.config as inductor_config
    from torch._inductor.graph import GraphLowering
    bm_graph_lowering = GraphLowering(gm=self.gm, example_inputs=self.example_inputs, shape_env=V.graph._shape_env, cpp_wrapper=V.graph.cpp_wrapper, aot_mode=V.graph.aot_mode, extern_node_serializer=V.graph.extern_node_serializer, is_inference=V.graph.is_inference, is_backward=V.graph.is_backward, name=f'benchmark_{self.name}')
    for sym_inp in self.sym_inputs:
        bm_graph_lowering.graph_inputs[sym_inp.name] = sym_inp
        bm_graph_lowering.graph_input_names.append(sym_inp.name)
    sym_inputs = [int(V.graph.sizevars.shape_env.size_hint(sym_var)) for sym_var in self.sym_inputs]
    if <MASK>:
        for (ar, example_inp) in zip(args, self.example_inputs):
            if isinstance(ar, torch.Tensor):
                assert isinstance(example_inp, torch.Tensor)
                assert ar.shape == example_inp.shape
                assert ar.stride() == example_inp.stride()
    with V.set_graph_handler(bm_graph_lowering):
        with inductor_config.patch(max_autotune=False, max_autotune_gemm=False, max_autotune_gemm_backends='ATEN'):
            bm_graph_lowering.run(*self.example_inputs)
            mod = bm_graph_lowering.compile_to_module()
            bm_func = mod.call
            bm_func([*sym_inputs, *args])
    if config.profile_bandwidth_with_do_bench_using_profiling:
        return do_bench_using_profiling(lambda : bm_func([*sym_inputs, *args]))
    return benchmarker.benchmark_gpu(lambda : bm_func([*sym_inputs, *args]))

@property
def function_call_options(self):
    """Returns function call options for current thread.

    Note that the returned object is still referenced by the eager context.

    Returns: the FunctionCallOptions for current thread.
    """
    if self._thread_local_data.function_call_options is None:
        config = self.config
        if <MASK>:
            config.allow_soft_placement = True
        self._thread_local_data.function_call_options = FunctionCallOptions(config_proto=config)
    return self._thread_local_data.function_call_options

def cutedsl(self, kernel_name: str, source_code: str):
    """
        Compile CuteDSL (CUTLASS Python DSL) kernels.

        Args:
            kernel_name: Name of the kernel to be defined
            source_code: Source code of the CuteDSL kernel, as a string

        Note:
            CuteDSL currently requires source files to do its compilation, there we
            use the PyCodeCache to write the source code to a file and load it.
        """
    from torch._inductor.codegen.cutedsl.cutedsl_kernel import CuteDSLKernelWrapper, MAIN_SUFFIX
    kernel_code_log.info('CuteDSL Kernel:\n%s', source_code)

    def task():
        (key, path) = torch._inductor.codecache.PyCodeCache.write(source_code)
        mod = torch._inductor.codecache.PyCodeCache.load_by_key_path(key, path)
        main_func_name = f'{kernel_name}_{MAIN_SUFFIX}'
        if not hasattr(mod, main_func_name):
            available = [name for name in dir(mod) if callable(getattr(mod, name))]
            raise RuntimeError(f"Could not find CuteDSL main kernel function '{main_func_name}'. Available callables: {available}")
        return CuteDSLKernelWrapper(getattr(mod, main_func_name), kernel_path=path)
    if <MASK>:
        return task()
    else:
        future = self.submit(task)
        return LambdaFuture(lambda : future.result())

def _get_mobile_model_contained_types(f_input) -> int:
    """Take a file-like object and return a set of string, like ("int", "Optional").

    Args:
        f_input: a file-like object (has to implement read, readline, tell, and seek),
            or a string containing a file name

    Returns:
        type_list: A set of string, like ("int", "Optional"). These are types used in bytecode.

    Example:

    .. testcode::

        from torch.jit.mobile import _get_mobile_model_contained_types

        # Get type list from a saved file path
        type_list = _get_mobile_model_contained_types("path/to/model.ptl")

    """
    if <MASK>:
        if not os.path.exists(f_input):
            raise ValueError(f'The provided filename {f_input} does not exist')
        if os.path.isdir(f_input):
            raise ValueError(f'The provided filename {f_input} is a directory')
    if isinstance(f_input, (str, os.PathLike)):
        return torch._C._get_mobile_model_contained_types(os.fspath(f_input))
    else:
        return torch._C._get_mobile_model_contained_types_from_buffer(f_input.read())

def main(unused_args):
    if not gfile.Exists(FLAGS.input):
        print("Input graph file '" + FLAGS.input + "' does not exist!")
        return -1
    input_graph_def = graph_pb2.GraphDef()
    with gfile.Open(FLAGS.input, 'rb') as f:
        data = f.read()
        if <MASK>:
            input_graph_def.ParseFromString(data)
        else:
            text_format.Merge(data.decode('utf-8'), input_graph_def)
    output_graph_def = optimize_for_inference_lib.optimize_for_inference(input_graph_def, FLAGS.input_names.split(','), FLAGS.output_names.split(','), _parse_placeholder_types(FLAGS.placeholder_type_enum), FLAGS.toco_compatible, FLAGS.placeholder_to_const_names.split(','))
    if FLAGS.frozen_graph:
        f = gfile.GFile(FLAGS.output, 'w')
        f.write(output_graph_def.SerializeToString())
    else:
        graph_io.write_graph(output_graph_def, os.path.dirname(FLAGS.output), os.path.basename(FLAGS.output))
    return 0

def _ensure_data(values: ArrayLike) -> np.ndarray:
    """
    routine to ensure that our data is of the correct
    input dtype for lower-level routines

    This will coerce:
    - ints -> int64
    - uint -> uint64
    - bool -> uint8
    - datetimelike -> i8
    - datetime64tz -> i8 (in local tz)
    - categorical -> codes

    Parameters
    ----------
    values : np.ndarray or ExtensionArray

    Returns
    -------
    np.ndarray
    """
    if not isinstance(values, ABCMultiIndex):
        values = extract_array(values, extract_numpy=True)
    if is_object_dtype(values.dtype):
        return ensure_object(np.asarray(values))
    elif <MASK>:
        values = cast('BaseMaskedArray', values)
        if not values._hasna:
            return _ensure_data(values._data)
        return np.asarray(values)
    elif isinstance(values.dtype, CategoricalDtype):
        values = cast('Categorical', values)
        return values.codes
    elif is_bool_dtype(values.dtype):
        if isinstance(values, np.ndarray):
            return np.asarray(values).view('uint8')
        else:
            return np.asarray(values).astype('uint8', copy=False)
    elif is_integer_dtype(values.dtype):
        return np.asarray(values)
    elif is_float_dtype(values.dtype):
        if values.dtype.itemsize in [2, 12, 16]:
            return ensure_float64(values)
        return np.asarray(values)
    elif is_complex_dtype(values.dtype):
        return cast(np.ndarray, values)
    elif needs_i8_conversion(values.dtype):
        npvalues = values.view('i8')
        npvalues = cast(np.ndarray, npvalues)
        return npvalues
    values = np.asarray(values, dtype=object)
    return ensure_object(values)

def __call__(self, graph: torch.fx.Graph):
    for node in graph.nodes:
        if node.op != 'call_function':
            continue
        if isinstance(node.target, (OpOverload, OpOverloadPacket)):
            continue
        kwargs = node.kwargs
        if node.target in self.cache:
            replaceable_kwargs = self.cache[node.target]
        else:
            signatures = torch.fx.operator_schemas.get_signature_for_torch_op(node.target)
            signatures = () if signatures is None else signatures
            replaceable_kwargs = OrderedSet()
            for sig in signatures:
                for param_name in sig.parameters.keys():
                    if param_name in self.numpy_compat:
                        replaceable_kwargs.update(self.numpy_compat[param_name])
            self.cache[node.target] = replaceable_kwargs
        if not replaceable_kwargs:
            continue
        new_kwargs = {}
        kwargs_changed = False
        for (k, v) in kwargs.items():
            if k in replaceable_kwargs:
                kwargs_changed = True
                new_kwargs[self.inverse_mapping[k]] = v
            else:
                new_kwargs[k] = v
        if <MASK>:
            node.kwargs = torch.fx.immutable_collections.immutable_dict(new_kwargs)
            counters['inductor']['numpy_compat_normalization'] += 1

@classmethod
def create(cls, qx: 'TensorBox', x_scale: Union['ShapeAsConstantBuffer', 'TensorBox'], x_zero_point: Union['ShapeAsConstantBuffer', 'TensorBox'], qw: 'TensorBox', w_scale: 'TensorBox', w_zero_point: 'TensorBox', bias: 'TensorBox', stride: list[int], padding: list[int], dilation: list[int], groups: int, output_scale: float, output_zero_point: int, output_dtype, attr, scalars, algorithm):
    transposed = False
    output_padding = None
    (inputs, constant_args, kernel_layout, _, _) = _prepare_convolution_fusion_create(cls, qx, qw, bias, padding, stride, dilation, groups, transposed, output_padding, [x_scale, x_zero_point, w_scale, w_zero_point])
    if <MASK>:
        (constant_args[1], constant_args[2]) = (constant_args[2], constant_args[1])
    else:
        (constant_args[0], constant_args[1]) = (constant_args[1], constant_args[0])
    constant_args = constant_args + [output_scale, output_zero_point, output_dtype, attr, may_convert_to_optional(scalars), algorithm]
    assert output_dtype is not None
    if output_dtype in [torch.float32, torch.bfloat16]:
        kernel_layout.dtype = output_dtype
    return QConvPointWisePT2E(layout=kernel_layout, inputs=inputs, constant_args=constant_args)

def operator_and_matrix(self, build_info, dtype, use_placeholder, ensure_self_adjoint_and_pd=False):
    shape = list(build_info.shape)
    if ensure_self_adjoint_and_pd:
        matrix = linear_operator_test_util.random_positive_definite_matrix(shape, dtype, force_well_conditioned=True)
    else:
        matrix = linear_operator_test_util.random_tril_matrix(shape, dtype, force_well_conditioned=True, remove_upper=True)
    lin_op_matrix = matrix
    if <MASK>:
        lin_op_matrix = array_ops.placeholder_with_default(matrix, shape=None)
    if ensure_self_adjoint_and_pd:
        operator = LinearOperatorAdjoint(linalg.LinearOperatorFullMatrix(lin_op_matrix, is_positive_definite=True, is_self_adjoint=True))
    else:
        operator = LinearOperatorAdjoint(linalg.LinearOperatorLowerTriangular(lin_op_matrix))
    return (operator, linalg.adjoint(matrix))

def __init__(self, ds_input, write=False):
    self._write = 1 if write else 0
    Driver.ensure_registered()
    if isinstance(ds_input, str) and json_regex.match(ds_input):
        ds_input = json.loads(ds_input)
    if isinstance(ds_input, (str, Path)):
        ds_input = str(ds_input)
        if not ds_input.startswith(VSI_FILESYSTEM_PREFIX) and (not os.path.exists(ds_input)):
            raise GDALException('Unable to read raster source input "%s".' % ds_input)
        try:
            self._ptr = capi.open_ds(force_bytes(ds_input), self._write)
        except GDALException as err:
            raise GDALException('Could not open the datasource at "{}" ({}).'.format(ds_input, err))
    elif <MASK>:
        self._write = 1
        size = sys.getsizeof(ds_input)
        self._ds_input = c_buffer(ds_input)
        vsi_path = os.path.join(VSI_MEM_FILESYSTEM_BASE_PATH, str(uuid.uuid4()))
        capi.create_vsi_file_from_mem_buffer(force_bytes(vsi_path), byref(self._ds_input), size, VSI_TAKE_BUFFER_OWNERSHIP)
        try:
            self._ptr = capi.open_ds(force_bytes(vsi_path), self._write)
        except GDALException:
            capi.unlink_vsi_file(force_bytes(vsi_path))
            raise GDALException('Failed creating VSI raster from the input buffer.')
    elif isinstance(ds_input, dict):
        self._write = 1
        driver = Driver(ds_input.get('driver', 'MEM'))
        if driver.name != 'MEM' and 'name' not in ds_input:
            raise GDALException('Specify name for creation of raster with driver "{}".'.format(driver.name))
        if 'width' not in ds_input or 'height' not in ds_input:
            raise GDALException('Specify width and height attributes for JSON or dict input.')
        if 'srid' not in ds_input:
            raise GDALException('Specify srid for JSON or dict input.')
        papsz_options = []
        for (key, val) in ds_input.get('papsz_options', {}).items():
            option = '{}={}'.format(key, val)
            papsz_options.append(option.upper().encode())
        papsz_options.append(None)
        papsz_options = (c_char_p * len(papsz_options))(*papsz_options)
        self._ptr = capi.create_ds(driver._ptr, force_bytes(ds_input.get('name', '')), ds_input['width'], ds_input['height'], ds_input.get('nr_of_bands', len(ds_input.get('bands', []))), ds_input.get('datatype', 6), byref(papsz_options))
        for (i, band_input) in enumerate(ds_input.get('bands', [])):
            band = self.bands[i]
            if 'nodata_value' in band_input:
                band.nodata_value = band_input['nodata_value']
                if band.nodata_value is not None and ('data' not in band_input or 'size' in band_input or 'shape' in band_input):
                    band.data(data=(band.nodata_value,), shape=(1, 1))
            band.data(data=band_input.get('data'), size=band_input.get('size'), shape=band_input.get('shape'), offset=band_input.get('offset'))
        self.srs = ds_input.get('srid')
        if 'origin' in ds_input:
            (self.origin.x, self.origin.y) = ds_input['origin']
        if 'scale' in ds_input:
            (self.scale.x, self.scale.y) = ds_input['scale']
        if 'skew' in ds_input:
            (self.skew.x, self.skew.y) = ds_input['skew']
    elif isinstance(ds_input, c_void_p):
        self._ptr = ds_input
    else:
        raise GDALException('Invalid data source input type: "{}".'.format(type(ds_input)))

def skipIfNoFBGEMM(fn):
    reason = 'Quantized operations require FBGEMM. FBGEMM is only optimized for CPUs with instruction set support AVX2 or newer.'
    if <MASK>:
        if 'fbgemm' not in torch.backends.quantized.supported_engines:
            fn.__unittest_skip__ = True
            fn.__unittest_skip_why__ = reason
        return fn

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        if 'fbgemm' not in torch.backends.quantized.supported_engines:
            raise unittest.SkipTest(reason)
        else:
            fn(*args, **kwargs)
    return wrapper

def _replace_dtype_fields_recursive(dtype, primitive_dtype):
    """Private function allowing recursion in _replace_dtype_fields."""
    _recurse = _replace_dtype_fields_recursive
    if dtype.names is not None:
        descr = []
        for name in dtype.names:
            field = dtype.fields[name]
            if <MASK>:
                name = (field[-1], name)
            descr.append((name, _recurse(field[0], primitive_dtype)))
        new_dtype = np.dtype(descr)
    elif dtype.subdtype:
        descr = list(dtype.subdtype)
        descr[0] = _recurse(dtype.subdtype[0], primitive_dtype)
        new_dtype = np.dtype(tuple(descr))
    else:
        new_dtype = primitive_dtype
    if new_dtype == dtype:
        new_dtype = dtype
    return new_dtype

def restore_fn() -> Mapping[str, ops.Operation]:
    restore_fn_inputs = {}
    restore_fn_input_count = {fn: len(keys) for (fn, keys) in self._restore_fn_to_keys.items()}
    restore_ops = {}
    for (task, shard) in self._shardable_tensors_by_task.items():
        with ops.device(task):
            restored_tensor_dict = _single_shard_restore(file_prefix, shard, options)
            for (ckpt_key, slice_and_tensor) in restored_tensor_dict.items():
                for (slice_spec, tensor) in slice_and_tensor.items():
                    restore_fn = self._keys_to_restore_fn[ckpt_key, slice_spec]
                    if <MASK>:
                        restore_fn_inputs.setdefault(restore_fn, {}).setdefault(ckpt_key, {})[slice_spec] = tensor
                    else:
                        restore_fn_inputs.setdefault(restore_fn, {})[ckpt_key] = tensor
                    restore_fn_input_count[restore_fn] -= 1
                    if restore_fn_input_count[restore_fn] == 0:
                        restored_tensors = {}
                        for (ckpt_key, tensor) in restore_fn_inputs[restore_fn].items():
                            restored_tensors[trackable_utils.extract_local_name(ckpt_key)] = tensor
                        ret = restore_fn(restored_tensors)
                        if isinstance(ret, dict):
                            restore_ops.update(ret)
    for (_, (_, restore_fn)) in self._registered_savers.items():
        restore_fn(file_prefix)
    return restore_ops

def as_string(self):
    """Return a string of the file contents."""
    items = {'replaces_str': '', 'initial_str': '', 'run_before_str': '', 'atomic_str': ''}
    imports = set()
    operations = []
    for operation in self.migration.operations:
        (operation_string, operation_imports) = OperationWriter(operation).serialize()
        imports.update(operation_imports)
        operations.append(operation_string)
    items['operations'] = '\n'.join(operations) + '\n' if operations else ''
    dependencies = []
    for dependency in self.migration.dependencies:
        if dependency[0] == '__setting__':
            dependencies.append('        migrations.swappable_dependency(settings.%s),' % dependency[1])
            imports.add('from django.conf import settings')
        else:
            dependencies.append('        %s,' % self.serialize(dependency)[0])
    items['dependencies'] = '\n'.join(sorted(dependencies)) + '\n' if dependencies else ''
    migration_imports = set()
    for line in list(imports):
        if re.match('^import (.*)\\.\\d+[^\\s]*$', line):
            migration_imports.add(line.split('import')[1].strip())
            imports.remove(line)
            self.needs_manual_porting = True
    if 'from django.db import models' in imports:
        imports.discard('from django.db import models')
        imports.add('from django.db import migrations, models')
    else:
        imports.add('from django.db import migrations')
    sorted_imports = sorted(imports, key=lambda i: (i.split()[0] == 'from', i.split()[1]))
    items['imports'] = '\n'.join(sorted_imports) + '\n' if imports else ''
    if migration_imports:
        items['imports'] += '\n\n# Functions from the following migrations need manual copying.\n# Move them and any dependencies into this file, then update the\n# RunPython operations to refer to the local versions:\n# %s' % '\n# '.join(sorted(migration_imports))
    if self.migration.replaces:
        items['replaces_str'] = '\n    replaces = %s\n' % self.serialize(self.migration.replaces)[0]
    if <MASK>:
        items['run_before_str'] = '\n    run_before = %s\n' % self.serialize(self.migration.run_before)[0]
    if self.include_header:
        items['migration_header'] = MIGRATION_HEADER_TEMPLATE % {'version': get_version(), 'timestamp': now().strftime('%Y-%m-%d %H:%M')}
    else:
        items['migration_header'] = ''
    if self.migration.initial:
        items['initial_str'] = '\n    initial = True\n'
    if not self.migration.atomic:
        items['atomic_str'] = '\n    atomic = False\n'
    return MIGRATION_TEMPLATE % items

def decorated(metric_obj, *args):
    """Decorated function with merge_call."""
    has_strategy = distribute_lib.has_strategy()
    replica_context = distribute_lib.get_replica_context()
    if not has_strategy or replica_context is None or (not distribute_lib.get_strategy().extended._use_merge_call()):
        with distribute_lib.variable_sync_on_read_context():
            raw_result = result_fn(*args)
            if <MASK>:
                result_t = array_ops.identity(raw_result)
            elif isinstance(raw_result, dict):
                result_t = {key: array_ops.identity(value) for (key, value) in raw_result.items()}
            else:
                try:
                    result_t = array_ops.identity(raw_result)
                except (ValueError, TypeError):
                    raise RuntimeError('The output of `metric.result()` can only be a single Tensor/Variable, or a dict of Tensors/Variables. For metric %s, got result %s.' % (metric_obj.name, raw_result))
    else:

        def merge_fn_wrapper(distribution, merge_fn, *args):
            result = distribution.experimental_local_results(merge_fn)[0](*args)
            return array_ops.identity(result)
        result_t = replica_context.merge_call(merge_fn_wrapper, args=(result_fn,) + args)
    metric_obj._call_result = result_t
    return result_t

def recurser(index, hanging_indent, curr_width):
    """
        By using this local function, we don't need to recurse with all the
        arguments. Since this function is not created recursively, the cost is
        not significant
        """
    axis = len(index)
    axes_left = a.ndim - axis
    if axes_left == 0:
        return format_function(a[index])
    next_hanging_indent = hanging_indent + ' '
    if legacy <= 113:
        next_width = curr_width
    else:
        next_width = curr_width - len(']')
    a_len = a.shape[axis]
    show_summary = summary_insert and 2 * edge_items < a_len
    if <MASK>:
        leading_items = edge_items
        trailing_items = edge_items
    else:
        leading_items = 0
        trailing_items = a_len
    s = ''
    if axes_left == 1:
        if legacy <= 113:
            elem_width = curr_width - len(separator.rstrip())
        else:
            elem_width = curr_width - max(len(separator.rstrip()), len(']'))
        line = hanging_indent
        for i in range(leading_items):
            word = recurser(index + (i,), next_hanging_indent, next_width)
            (s, line) = _extendLine_pretty(s, line, word, elem_width, hanging_indent, legacy)
            line += separator
        if show_summary:
            (s, line) = _extendLine(s, line, summary_insert, elem_width, hanging_indent, legacy)
            if legacy <= 113:
                line += ', '
            else:
                line += separator
        for i in range(trailing_items, 1, -1):
            word = recurser(index + (-i,), next_hanging_indent, next_width)
            (s, line) = _extendLine_pretty(s, line, word, elem_width, hanging_indent, legacy)
            line += separator
        if legacy <= 113:
            elem_width = curr_width
        word = recurser(index + (-1,), next_hanging_indent, next_width)
        (s, line) = _extendLine_pretty(s, line, word, elem_width, hanging_indent, legacy)
        s += line
    else:
        s = ''
        line_sep = separator.rstrip() + '\n' * (axes_left - 1)
        for i in range(leading_items):
            nested = recurser(index + (i,), next_hanging_indent, next_width)
            s += hanging_indent + nested + line_sep
        if show_summary:
            if legacy <= 113:
                s += hanging_indent + summary_insert + ', \n'
            else:
                s += hanging_indent + summary_insert + line_sep
        for i in range(trailing_items, 1, -1):
            nested = recurser(index + (-i,), next_hanging_indent, next_width)
            s += hanging_indent + nested + line_sep
        nested = recurser(index + (-1,), next_hanging_indent, next_width)
        s += hanging_indent + nested
    s = '[' + s[len(hanging_indent):] + ']'
    return s

def _view_wrapper(f, arr_dtype=None, out_dtype=None, fill_wrap=None):

    def wrapper(arr: np.ndarray, indexer: np.ndarray, out: np.ndarray, fill_value=np.nan) -> None:
        if arr_dtype is not None:
            arr = arr.view(arr_dtype)
        if <MASK>:
            out = out.view(out_dtype)
        if fill_wrap is not None:
            if fill_value.dtype.kind == 'm':
                fill_value = fill_value.astype('m8[ns]')
            else:
                fill_value = fill_value.astype('M8[ns]')
            fill_value = fill_wrap(fill_value)
        f(arr, indexer, out, fill_value=fill_value)
    return wrapper

def __torch_function__(self, orig_func: Callable[_P, _R], types: Sequence[type], args: Sequence[Any]=(), kwargs: dict[str, Any] | None=None) -> Any:
    if <MASK>:
        kwargs = {}
    if orig_func in torch_function_passthrough or orig_func in all_prims():
        with self.prims_mode_cls():
            return orig_func(*args, **kwargs)
    mapping = torch_to_refs_map()
    func = mapping.get(orig_func, None)
    if func is None and isinstance(orig_func, torch._ops.OpOverload):
        func = torch._decomp.decomposition_table.get(orig_func, None)
    elif func is None and isinstance(orig_func, torch._ops.OpOverloadPacket):
        default = getattr(orig_func, 'default', None)
        if default is None and orig_func._dir:
            default = getattr(orig_func, orig_func._dir[0], None)
        if default is not None:
            func = torch._decomp.decomposition_table.get(default, None)
    if func is not None:
        if self.should_fallback_fn(self, orig_func, func, args, kwargs):
            return orig_func(*args, **kwargs)
        with self:
            return func(*args, **kwargs)
    if self.strict:
        raise RuntimeError(f'no _refs support for {torch.overrides.resolve_name(orig_func)}')
    return orig_func(*args, **kwargs)

def store_reduction(self, name, index, value):
    index = self.rename_indexing(index)
    var = self.args.output(name)
    out_dtype = V.graph.get_dtype(name)
    if out_dtype.is_floating_point and out_dtype != torch.double:
        dtype = torch.float
    else:
        dtype = out_dtype
    out_num_vectors = V.kernel._get_num_vectors(out_dtype)
    src_num_vectors = V.kernel._get_num_vectors(dtype)
    code = IndentedBuffer()
    if self.tiling_idx >= self.reduction_depth:
        code.writeline(f'{var}[{cexpr_index(index)}] = static_cast<{DTYPE_TO_CPP[out_dtype]}>({value});')
    else:
        if out_dtype != dtype:
            converted_value = f"{DTYPE_TO_CPP[out_dtype].replace('::', '_')}_{value}"
            if <MASK>:
                convert = f'{value}.template cast<bool,{self._get_num_vectors(torch.bool)}>()'
            elif src_num_vectors == out_num_vectors == 1:
                convert = f'at::vec::convert<{DTYPE_TO_CPP[out_dtype]}>({value})'
            else:
                convert = f'at::vec::convert<{DTYPE_TO_CPP[out_dtype]},{out_num_vectors},{DTYPE_TO_CPP[dtype]},{src_num_vectors}>({value})'
            code.writeline(f'auto {converted_value} = {convert};')
            value = converted_value
        code.splice(self._get_store_line(value, var, index, out_dtype))
    self.reduction_suffix.splice(code.map(lambda x: DeferredLine(name, x)))

def _parametrize_test(self, test, generic_cls, device_cls):
    """Parameterizes the given test function across each op and its associated dtypes."""
    if device_cls is None:
        raise RuntimeError('The @ops decorator is only intended to be used in a device-specific context; use it with instantiate_device_type_tests() instead of instantiate_parametrized_tests()')
    op = check_exhausted_iterator = object()
    for op in self.op_list:
        dtypes: Union[set[torch.dtype], set[None]]
        if isinstance(self.opinfo_dtypes, Sequence):
            dtypes = set(self.opinfo_dtypes)
        elif self.opinfo_dtypes == OpDTypes.unsupported_backward:
            dtypes = set(get_all_dtypes()).difference(op.supported_backward_dtypes(device_cls.device_type))
        elif <MASK>:
            dtypes = op.supported_backward_dtypes(device_cls.device_type)
        elif self.opinfo_dtypes == OpDTypes.unsupported:
            dtypes = set(get_all_dtypes()).difference(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported:
            dtypes = set(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.any_one:
            supported = op.supported_dtypes(device_cls.device_type)
            supported_backward = op.supported_backward_dtypes(device_cls.device_type)
            supported_both = supported.intersection(supported_backward)
            dtype_set = supported_both if len(supported_both) > 0 else supported
            for dtype in ANY_DTYPE_ORDER:
                if dtype in dtype_set:
                    dtypes = {dtype}
                    break
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.any_common_cpu_cuda_one:
            supported = set(op.dtypes).intersection(op.dtypesIfCUDA)
            if supported:
                dtypes = {next((dtype for dtype in ANY_DTYPE_ORDER if dtype in supported))}
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.none:
            dtypes = {None}
        else:
            raise RuntimeError(f'Unknown OpDType: {self.opinfo_dtypes}')
        if self.allowed_dtypes is not None:
            dtypes = dtypes.intersection(self.allowed_dtypes)
        test_name = op.formatted_name
        sample_skips_and_xfails = getattr(test, 'sample_skips_and_xfails', None)
        if sample_skips_and_xfails is not None:
            sample_skips_and_xfails = [rule for rule in sample_skips_and_xfails if rule.op_match_fn(device_cls.device_type, op)]
        for dtype in dtypes:
            param_kwargs = {'op': op}
            _update_param_kwargs(param_kwargs, 'dtype', dtype)
            try:

                @wraps(test)
                def test_wrapper(*args, **kwargs):
                    try:
                        return test(*args, **kwargs)
                    except unittest.SkipTest as e:
                        raise e
                    except Exception as e:
                        tracked_input = get_tracked_input()
                        if PRINT_REPRO_ON_FAILURE and tracked_input is not None:
                            e_tracked = Exception(f'{str(e)}\n\nCaused by {tracked_input.type_desc} at index {tracked_input.index}: {_serialize_sample(tracked_input.val)}')
                            e_tracked._tracked_input = tracked_input
                            raise e_tracked from e
                        raise e
                    finally:
                        clear_tracked_input()
                if self.skip_if_dynamo and (not TEST_WITH_TORCHINDUCTOR):
                    test_wrapper = skipIfTorchDynamo("Policy: we don't run OpInfo tests w/ Dynamo")(test_wrapper)
                test.tracked_input = None
                decorator_fn = partial(op.get_decorators, generic_cls.__name__, test.__name__, device_cls.device_type, dtype)
                if sample_skips_and_xfails is not None:
                    test_wrapper.sample_skips_and_xfails = sample_skips_and_xfails
                yield (test_wrapper, test_name, param_kwargs, decorator_fn)
            except Exception as ex:
                print(f'Failed to instantiate {test_name} for op {op.name}!')
                raise ex
    if op is check_exhausted_iterator:
        raise ValueError('An empty op_list was passed to @ops. Note that this may result from reuse of a generator.')

@_dcp_method_logger(**ckpt_kwargs)
def local_step():
    nonlocal use_collectives
    nonlocal metadata
    try:
        metadata = storage_reader.read_metadata()
    except Exception:
        logger.info('Global metadata is not found. Falling back to rank local metadata.')
    if not metadata and 'kwargs' in inspect.signature(storage_reader.read_metadata).parameters:
        try:
            metadata = storage_reader.read_metadata(rank=distW.rank)
            use_collectives = False
        except Exception:
            logger.info('Rank local metadata is not found.')
    if <MASK>:
        raise AssertionError('planner is None')
    if metadata is None:
        raise AssertionError('metadata is None')
    planner.set_up_planner(state_dict, metadata, distW.is_coordinator)
    if 'kwargs' in inspect.signature(storage_reader.set_up_storage_reader).parameters:
        storage_reader.set_up_storage_reader(metadata, distW.is_coordinator, rank=distW.rank, use_collectives=use_collectives)
    else:
        storage_reader.set_up_storage_reader(metadata, distW.is_coordinator)
    local_plan = planner.create_local_plan()
    local_plan = storage_reader.prepare_local_plan(local_plan)
    return local_plan

def _validate_shuffle_split(n_samples, test_size, train_size, default_test_size=None):
    """
    Validation helper to check if the train/test sizes are meaningful w.r.t. the
    size of the data (n_samples).
    """
    if <MASK>:
        test_size = default_test_size
    test_size_type = np.asarray(test_size).dtype.kind
    train_size_type = np.asarray(train_size).dtype.kind
    if test_size_type == 'i' and (test_size >= n_samples or test_size <= 0) or (test_size_type == 'f' and (test_size <= 0 or test_size >= 1)):
        raise ValueError('test_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(test_size, n_samples))
    if train_size_type == 'i' and (train_size >= n_samples or train_size <= 0) or (train_size_type == 'f' and (train_size <= 0 or train_size >= 1)):
        raise ValueError('train_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(train_size, n_samples))
    if train_size is not None and train_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for train_size: {}'.format(train_size))
    if test_size is not None and test_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for test_size: {}'.format(test_size))
    if train_size_type == 'f' and test_size_type == 'f' and (train_size + test_size > 1):
        raise ValueError('The sum of test_size and train_size = {}, should be in the (0, 1) range. Reduce test_size and/or train_size.'.format(train_size + test_size))
    if test_size_type == 'f':
        n_test = ceil(test_size * n_samples)
    elif test_size_type == 'i':
        n_test = float(test_size)
    if train_size_type == 'f':
        n_train = floor(train_size * n_samples)
    elif train_size_type == 'i':
        n_train = float(train_size)
    if train_size is None:
        n_train = n_samples - n_test
    elif test_size is None:
        n_test = n_samples - n_train
    if n_train + n_test > n_samples:
        raise ValueError('The sum of train_size and test_size = %d, should be smaller than the number of samples %d. Reduce test_size and/or train_size.' % (n_train + n_test, n_samples))
    (n_train, n_test) = (int(n_train), int(n_test))
    if n_train == 0:
        raise ValueError('With n_samples={}, test_size={} and train_size={}, the resulting train set will be empty. Adjust any of the aforementioned parameters.'.format(n_samples, test_size, train_size))
    return (n_train, n_test)

def _log_autotune_exceptions(exceptions: list[tuple[ChoiceCaller, BaseException]]) -> None:
    """Log autotune exceptions to chromium event logger."""
    if not exceptions:
        return
    try:
        pt2_compile_substack = get_chromium_event_logger().get_pt2_compile_substack()
        if not pt2_compile_substack:
            return
        current_event = pt2_compile_substack[-1]
        if not current_event.endswith('_template_precompiling'):
            return
        exception_details = []
        for (choice, exc) in exceptions:
            try:
                choice_type = 'triton' if isinstance(choice, TritonTemplateCaller) else 'other'
                data = {'choice_type': choice_type, 'choice': choice.description, 'exception_message': str(exc)}
                exc_type_match = re.search('(\\w+):', str(exc))
                if exc_type_match:
                    data['exception'] = exc_type_match.group(1)
                if 'OutOfMemoryError' in str(exc):
                    required_match = re.search('Required: (\\d+)', str(exc))
                    if required_match:
                        data['required_memory'] = required_match.group(1)
                    limit_match = re.search('Hardware limit:\\s*(\\d+)', str(exc))
                    if <MASK>:
                        data['hardware_limit'] = limit_match.group(1)
                exception_details.append(data)
            except Exception:
                continue
        if exception_details:
            metadata = json.dumps({'exceptions': exception_details})
            get_chromium_event_logger().try_add_event_data(current_event, metadata=metadata)
    except Exception:
        pass

def finalize_options(self):
    self.set_undefined_options('build', ('build_base', 'build_base'), ('build_lib', 'build_lib'), ('force', 'force'))
    if self.package is None:
        self.package = self.distribution.ext_package
    self.extensions = self.distribution.ext_modules
    self.libraries = self.distribution.libraries or []
    self.py_modules = self.distribution.py_modules or []
    self.data_files = self.distribution.data_files or []
    if self.build_src is None:
        plat_specifier = '.{}-{}.{}'.format(get_platform(), *sys.version_info[:2])
        self.build_src = os.path.join(self.build_base, 'src' + plat_specifier)
    self.py_modules_dict = {}
    if self.f2pyflags:
        if self.f2py_opts:
            log.warn('ignoring --f2pyflags as --f2py-opts already used')
        else:
            self.f2py_opts = self.f2pyflags
        self.f2pyflags = None
    if self.f2py_opts is None:
        self.f2py_opts = []
    else:
        self.f2py_opts = shlex.split(self.f2py_opts)
    if self.swigflags:
        if self.swig_opts:
            log.warn('ignoring --swigflags as --swig-opts already used')
        else:
            self.swig_opts = self.swigflags
        self.swigflags = None
    if self.swig_opts is None:
        self.swig_opts = []
    else:
        self.swig_opts = shlex.split(self.swig_opts)
    build_ext = self.get_finalized_command('build_ext')
    if <MASK>:
        self.inplace = build_ext.inplace
    if self.swig_cpp is None:
        self.swig_cpp = build_ext.swig_cpp
    for c in ['swig', 'swig_opt']:
        o = '--' + c.replace('_', '-')
        v = getattr(build_ext, c, None)
        if v:
            if getattr(self, c):
                log.warn('both build_src and build_ext define %s option' % o)
            else:
                log.info('using "%s=%s" option from build_ext command' % (o, v))
                setattr(self, c, v)

def _initial_gpu_handler(self) -> None:
    """
        Initializes the GPU handlers if gpus are available, and updates the log summary info.
        """
    try:
        if <MASK>:
            self._gpu_lib_detected = 'pynvml'
            self._gpu_handles = [pynvml.nvmlDeviceGetHandleByIndex(i) for i in range(pynvml.nvmlDeviceGetCount())]
        if self._has_amdsmi:
            self._gpu_lib_detected = 'amdsmi'
            self._gpu_handles = amdsmi.amdsmi_get_processor_handles()
        self._num_of_cpus = psutil.cpu_count(logical=True)
        self._metadata.gpu_count = len(self._gpu_handles)
        self._metadata.cpu_count = self._num_of_cpus
        if self._has_pynvml or self._has_amdsmi:
            if len(self._gpu_handles) == 0:
                self._metadata.gpu_type = ''
            else:
                self._metadata.gpu_type = self._gpu_lib_detected
    except Exception as e:
        self._metadata.error = str(e)

def add_item_elements(self, handler, item):
    handler.addQuickElement('title', item['title'])
    handler.addQuickElement('link', item['link'])
    if item['description'] is not None:
        handler.addQuickElement('description', item['description'])
    if item['author_name'] and item['author_email']:
        handler.addQuickElement('author', '%s (%s)' % (item['author_email'], item['author_name']))
    elif item['author_email']:
        handler.addQuickElement('author', item['author_email'])
    elif item['author_name']:
        handler.addQuickElement('dc:creator', item['author_name'], {'xmlns:dc': 'http://purl.org/dc/elements/1.1/'})
    if item['pubdate'] is not None:
        handler.addQuickElement('pubDate', rfc2822_date(item['pubdate']))
    if item['comments'] is not None:
        handler.addQuickElement('comments', item['comments'])
    if item['unique_id'] is not None:
        guid_attrs = {}
        if <MASK>:
            guid_attrs['isPermaLink'] = str(item['unique_id_is_permalink']).lower()
        handler.addQuickElement('guid', item['unique_id'], guid_attrs)
    if item['ttl'] is not None:
        handler.addQuickElement('ttl', item['ttl'])
    if item['enclosures']:
        enclosures = list(item['enclosures'])
        if len(enclosures) > 1:
            raise ValueError('RSS feed items may only have one enclosure, see http://www.rssboard.org/rss-profile#element-channel-item-enclosure')
        enclosure = enclosures[0]
        handler.addQuickElement('enclosure', '', {'url': enclosure.url, 'length': enclosure.length, 'type': enclosure.mime_type})
    for cat in item['categories']:
        handler.addQuickElement('category', cat)

def _get_outfile_suffix(self):
    if <MASK>:
