    else:
        return ''

def __call__(self, token, device, args):
    """Calls the registered function for `token` with args.

    Args:
      token: A key into this `FuncRegistry` identifying which function to call.
      device: Name of the device on which outputs of `token`'s corresponding
        operation should be placed. Used iff the function registered for `token`
        is an EagerPyFunc.
      args: The arguments to pass to the function registered for `token`.

    Returns:
      The output of the function registered for `token`.

    Raises:
      ValueError: if no function is registered for `token`.
    """
    func = self.get(token, None)
    if func is None:
        raise ValueError(f'Could not find callback with key={token} in the registry.')
    if <MASK>:
        return func(device, token, args)
    else:
        ret = func(*args)
        if isinstance(ret, bytes):
            ret = [ret]
        if isinstance(ret, (tuple, list)):
            return [self._convert(x) for x in ret]
        else:
            return self._convert(ret)

@_onnx_symbolic('aten::binary_cross_entropy_with_logits')
@symbolic_helper.parse_args('v', 'v', 'v', 'v', 'i')
def binary_cross_entropy_with_logits(g: jit_utils.GraphContext, input, target, weight, pos_weight, reduction):
    p = g.op('Constant', value_t=torch.tensor([1]))
    sig_x = opset9.sigmoid(g, input)
    log_sig_x = opset9.log(g, sig_x)
    sub_1_x = opset9.sub(g, p, sig_x)
    sub_1_y = opset9.sub(g, p, target)
    log_1_x = opset9.log(g, sub_1_x)
    if pos_weight is None or symbolic_helper._is_none(pos_weight):
        output = opset9.neg(g, opset9.add(g, opset9.mul(g, target, log_sig_x), opset9.mul(g, sub_1_y, log_1_x)))
    else:
        output = opset9.neg(g, opset9.add(g, opset9.mul(g, opset9.mul(g, target, log_sig_x), pos_weight), opset9.mul(g, sub_1_y, log_1_x)))
    if <MASK>:
        output = opset9.mul(g, weight, output)
    reduction = symbolic_helper._maybe_get_const(reduction, 'i')
    if reduction == 0:
        return output
    elif reduction == 1:
        return g.op('ReduceMean', output, keepdims_i=0)
    elif reduction == 2:
        return g.op('ReduceSum', output, keepdims_i=0)
    else:
        return symbolic_helper._onnx_unsupported('binary_cross_entropy_with_logits with reduction other than none, mean, or sum', input)

@property
def initializer(self):
    if <MASK>:
        return self._variables[0].initializer
    return super().initializer

def call(self, inputs):
    if inputs.dtype.base_dtype != self._compute_dtype_object.base_dtype:
        inputs = math_ops.cast(inputs, dtype=self._compute_dtype_object)
    rank = inputs.shape.rank
    if rank == 2 or rank is None:
        if <MASK>:
            (inputs, _) = sparse_ops.sparse_fill_empty_rows(inputs, 0)
            ids = sparse_tensor.SparseTensor(indices=inputs.indices, values=inputs.indices[:, 1], dense_shape=inputs.dense_shape)
            weights = inputs
            outputs = embedding_ops.embedding_lookup_sparse_v2(self.kernel, ids, weights, combiner='sum')
        else:
            outputs = gen_math_ops.MatMul(a=inputs, b=self.kernel)
    else:
        outputs = standard_ops.tensordot(inputs, self.kernel, [[rank - 1], [0]])
        if not context.executing_eagerly():
            shape = inputs.shape.as_list()
            output_shape = shape[:-1] + [self.kernel.shape[-1]]
            outputs.set_shape(output_shape)
    if self.use_bias:
        outputs = nn_ops.bias_add(outputs, self.bias)
    if self.activation is not None:
        outputs = self.activation(outputs)
    return outputs

def __init__(self, encoder_layer: 'TransformerEncoderLayer', num_layers: int, norm: Optional[Module]=None, enable_nested_tensor: bool=True, mask_check: bool=True) -> None:
    super().__init__()
    torch._C._log_api_usage_once(f'torch.nn.modules.{self.__class__.__name__}')
    self.layers = _get_clones(encoder_layer, num_layers)
    self.num_layers = num_layers
    self.norm = norm
    self.enable_nested_tensor = enable_nested_tensor
    self.use_nested_tensor = enable_nested_tensor
    self.mask_check = mask_check
    enc_layer = 'encoder_layer'
    why_not_sparsity_fast_path = ''
    if not isinstance(encoder_layer, torch.nn.TransformerEncoderLayer):
        why_not_sparsity_fast_path = f'{enc_layer} was not TransformerEncoderLayer'
    elif <MASK>:
        why_not_sparsity_fast_path = f'{enc_layer}.norm_first was True'
    elif not encoder_layer.self_attn.batch_first:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn.batch_first was not True' + '(use batch_first for better inference performance)'
    elif not encoder_layer.self_attn._qkv_same_embed_dim:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn._qkv_same_embed_dim was not True'
    elif encoder_layer.self_attn.in_proj_bias is None:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn was passed bias=False'
    elif not encoder_layer.activation_relu_or_gelu:
        why_not_sparsity_fast_path = f'{enc_layer}.activation_relu_or_gelu was not True'
    elif encoder_layer.norm1.eps != encoder_layer.norm2.eps:
        why_not_sparsity_fast_path = f'{enc_layer}.norm1.eps was not equal to {enc_layer}.norm2.eps'
    elif encoder_layer.self_attn.num_heads % 2 == 1:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn.num_heads is odd'
    if enable_nested_tensor and why_not_sparsity_fast_path:
        warnings.warn(f'enable_nested_tensor is True, but self.use_nested_tensor is False because {why_not_sparsity_fast_path}')
        self.use_nested_tensor = False

def compute_elementwise_output_logical_to_physical_perm(*tensors, _skip_checks=False, ambiguity_check=False) -> tuple[list[int], bool]:
    from torch.fx.experimental.symbolic_shapes import guard_or_false
    if not _skip_checks and len(tensors) == 0:
        msg = "Can't compute elementwise output strides for zero tensors!"
        raise ValueError(msg)
    if not _skip_checks:
        check_same_shape(*tensors, allow_cpu_scalar_tensors=True)
    if not _skip_checks:
        tensors = tuple((a for a in tensors if isinstance(a, TensorLike) and (not is_cpu_scalar_tensor(a))))
    if len(tensors) == 0:
        return ([], False)
    ndim = tensors[0].ndim
    if ndim == 0:
        return ([], False)
    if ndim == 1:
        return ([0], False)
    is_contiguous = True
    is_channels_last = True
    for t in tensors:
        is_contiguous = is_contiguous and is_contiguous_for_memory_format_or_false(t, memory_format=torch.contiguous_format)
        is_channels_last = is_channels_last and is_contiguous_for_memory_format_or_false(t, memory_format=torch.channels_last)
    if is_contiguous and (not is_channels_last):
        return (list(range(ndim)), False)
    if is_channels_last and (not is_contiguous):
        return ([0, *list(range(2, ndim)), 1], False)
    shape = tensors[0].shape

    def should_swap(idx_a, idx_b):

        def ge(a, b):
            """
            Returns true if a is symbolically greater than or equal to b, assuming a >= 0, b >= 0.
            """
            if guard_or_false(b == 0):
                return True
            elif guard_or_false(a == 0):
                return False
            return guard_or_false(a >= b) or guard_or_false(a % b == 0)
        for tensor in tensors:
            stride_a = tensor.stride()[idx_a]
            stride_b = tensor.stride()[idx_b]
            if guard_or_false(stride_a == 0) or guard_or_false(stride_b == 0):
                continue
            if guard_or_false(stride_a == stride_b):
                if ge(shape[idx_b], shape[idx_a]):
                    continue
                return 1
            if <MASK>:
                return -1
            if ge(stride_a, stride_b):
                return 1
        return 0
    perm = list(reversed(range(ndim)))
    for i in range(1, ndim):
        dim1 = i
        for dim0 in reversed(range(i)):
            comparison = should_swap(perm[dim0], perm[dim1])
            if comparison > 0:
                (perm[dim0], perm[dim1]) = (perm[dim1], perm[dim0])
                dim1 = dim0
            elif comparison < 0:
                break
    raise_ambiguous = False
    if ambiguity_check:
        for (i, j) in zip(range(ndim - 1), range(1, ndim)):
            order = should_swap(perm[i], perm[j])
            if order != -1:
                raise_ambiguous = True
                break
    return (list(reversed(perm)), raise_ambiguous)

def construct_graph(node: Node, base_mod_env: dict[str, Node], base_mod_attrs: dict[str, torch.fx.graph_module.GraphModule]):
    if node.op == 'placeholder':
        default_value = node.args[0] if len(node.args) > 0 else inspect.Signature.empty
        if keep_original_node_name:
            args = () if default_value is inspect.Signature.empty else (default_value,)
            base_mod_env[node.name] = base_mod_graph.create_node('placeholder', node.name, args=args, type_expr=node.type)
        else:
            base_mod_env[node.name] = base_mod_graph.placeholder(node.target, type_expr=node.type, default_value=default_value)
        base_mod_env[node.name].meta = node.meta.copy()
    elif <MASK>:
        base_mod_env[node.name] = base_mod_graph.get_attr(node.target)
        base_mod_env[node.name].meta = node.meta.copy()
        assert isinstance(node.target, str)
        attr_val = _get_attr_from_qualname(m, node.target)
        base_mod_attrs[node.target] = attr_val
    return (base_mod_env, base_mod_attrs)

def setup_stacktrace_preservation_hooks(roots: list):

    def iter_graph(roots):
        if not roots:
            return
        seen = set()
        q = collections.deque()
        for node in roots:
            if node is not None and node not in seen:
                seen.add(node)
                q.append(node)
        while q:
            node = q.popleft()
            for (fn, _idx) in node.next_functions:
                if fn in seen or fn is None:
                    continue
                seen.add(fn)
                q.append(fn)
            yield node

    def get_callback(saved_stack_):

        def callback():
            global callback_set
            fx_traceback.set_stack_trace(saved_stack_)
            callback_set = False
        return callback

    def get_prehook(stack_, seq_nr):

        def prehook(grad_output):
            global callback_set
            if <MASK>:
                torch.autograd.variable.Variable._execution_engine.queue_callback(get_callback(fx_traceback.format_stack()))
                callback_set = True
            fx_traceback.set_stack_trace(stack_)
            fx_traceback.set_grad_fn_seq_nr(seq_nr)
        return prehook

    def get_posthook(special_stack_, seq_nr):

        def posthook(grad_input, grad_output):
            fx_traceback.set_stack_trace(special_stack_)
            fx_traceback.reset_grad_fn_seq_nr()
        return posthook
    for node in iter_graph(roots):
        forward_node_stack = node.metadata.get('traceback_', [])
        node.register_prehook(get_prehook(forward_node_stack, node._sequence_nr()))
        special_stack = forward_node_stack.copy()
        special_stack.append('Gradient addition node due to multiple use of tensor around:')
        node.register_hook(get_posthook(special_stack, node._sequence_nr()))

def _ready_to_schedule(action: Optional[_Action]) -> bool:
    if action is None:
        return True
    stage_idx = action.stage_index
    prev_ops = _prev_ops_rank[stage_to_rank(stage_idx)]
    if action.computation_type == F:
        if action.stage_index == 0:
            return True
        elif _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_ops:
            return True
        elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_ops:
            return True
        return False
    elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
        if action.stage_index == num_stages - 1:
            return True
        if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_ops:
            return True
        if _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_ops:
            return True
        if _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_ops:
            return True
        return False
    elif action.computation_type == BACKWARD_WEIGHT:
        return True
    elif action.computation_type == SEND_F:
        expected_f = _Action(action.stage_index, F, action.microbatch_index)
        return expected_f in prev_ops
    elif action.computation_type == RECV_F:
        peer_stage_idx = stage_idx - 1
        expected_send = _Action(peer_stage_idx, SEND_F, action.microbatch_index)
        return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
    elif action.computation_type == SEND_B:
        expected_b = _Action(action.stage_index, BACKWARD_INPUT, action.microbatch_index)
        expected_bw = _Action(action.stage_index, FULL_BACKWARD, action.microbatch_index)
        return expected_b in prev_ops or expected_bw in prev_ops
    elif <MASK>:
        peer_stage_idx = stage_idx + 1
        expected_send = _Action(peer_stage_idx, SEND_B, action.microbatch_index)
        return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
    else:
        raise ValueError(f'Unsupported action type {action}')

def _script_impl(obj, optimize=None, _frames_up=0, _rcb=None, example_inputs: Union[list[tuple], dict[Callable, list[tuple]], None]=None):
    global type_trace_db
    if optimize is not None:
        warnings.warn('`optimize` is deprecated and has no effect. Use `with torch.jit.optimized_execution()` instead', FutureWarning, stacklevel=3)
    if isinstance(obj, RecursiveScriptClass):
        return obj
    if isinstance(obj, ScriptModule):
        return obj
    if isinstance(obj, ScriptFunction):
        return obj
    if example_inputs:
        type_trace_db = JitTypeTraceStore()
        if monkeytype_trace:
            monkeytype_config = JitTypeTraceConfig(type_trace_db)
            with monkeytype_trace(monkeytype_config):
                if isinstance(example_inputs, dict):
                    for (module, example_input) in example_inputs.items():
                        for example in example_input:
                            module(*example)
                elif isinstance(example_inputs, list):
                    for examples in example_inputs:
                        obj(*examples)
                else:
                    raise ValueError('Error: Unable to infer types. Please format the inputs to type `List[Tuple]` or `Dict[Callable, List[Tuple]]` to be run with MonkeyType.')
        else:
            warnings.warn('Warning: monkeytype is not installed. Please install https://github.com/Instagram/MonkeyType to enable Profile-Directed Typing in TorchScript. Refer to https://github.com/Instagram/MonkeyType/blob/master/README.rst to install MonkeyType. ')
    if isinstance(obj, torch.nn.Module):
        obj = call_prepare_scriptable_func(obj)
        return torch.jit._recursive.create_script_module(obj, torch.jit._recursive.infer_methods_to_compile)
    else:
        obj = obj.__prepare_scriptable__() if hasattr(obj, '__prepare_scriptable__') else obj
    if isinstance(obj, dict):
        return create_script_dict(obj)
    if isinstance(obj, list):
        return create_script_list(obj)
    if inspect.isclass(obj):
        qualified_name = _qualified_name(obj)
        if <MASK>:
            raise RuntimeError(f"Type '{obj}' cannot be compiled since it inherits from nn.Module, pass an instance instead")
        if issubclass(obj, enum.Enum):
            return obj
        if not _is_new_style_class(obj):
            raise RuntimeError("TorchScript classes must be new-style classes. Please inherit from 'object'.")
        if len(obj.mro()) > 2:
            raise RuntimeError("TorchScript classes does not support inheritance yet. Please directly inherit from 'object'.")
        if _rcb is None:
            _rcb = _jit_internal.createResolutionCallbackFromFrame(_frames_up + 1)
        _compile_and_register_class(obj, _rcb, qualified_name)
        return obj
    elif inspect.isfunction(obj) or inspect.ismethod(obj):
        qualified_name = _qualified_name(obj)
        if hasattr(obj, '__script_if_tracing_wrapper'):
            obj = obj.__original_fn
            _rcb = _jit_internal.createResolutionCallbackFromClosure(obj)
        if hasattr(obj, '__script_unsupported'):
            raise RuntimeError('TorchScript error: ' + obj.__script_unsupported)
        _check_directly_compile_overloaded(obj)
        maybe_already_compiled_fn = _try_get_jit_cached_function(obj)
        if maybe_already_compiled_fn:
            maybe_already_compiled_fn._torchdynamo_inline = obj
            return maybe_already_compiled_fn
        ast = get_jit_def(obj, obj.__name__)
        if _rcb is None:
            _rcb = _jit_internal.createResolutionCallbackFromClosure(obj)
        fn = torch._C._jit_script_compile(qualified_name, ast, _rcb, get_default_args(obj))
        fn.__doc__ = obj.__doc__
        fn.__name__ = 'ScriptFunction'
        fn.__qualname__ = 'torch.jit.ScriptFunction'
        fn._torchdynamo_inline = obj
        _set_jit_function_cache(obj, fn)
        return fn
    else:
        return torch.jit._recursive.create_script_class(obj)

def clean_ipv6_address(ip_str, unpack_ipv4=False, error_message=_('This is not a valid IPv6 address.'), max_length=MAX_IPV6_ADDRESS_LENGTH):
    """
    Clean an IPv6 address string.

    Raise ValidationError if the address is invalid.

    Replace the longest continuous zero-sequence with "::", remove leading
    zeroes, and make sure all hextets are lowercase.

    Args:
        ip_str: A valid IPv6 address.
        unpack_ipv4: if an IPv4-mapped address is found,
        return the plain IPv4 address (default=False).
        error_message: An error message used in the ValidationError.

    Return a compressed IPv6 address or the same value.
    """
    try:
        addr = _ipv6_address_from_str(ip_str, max_length)
    except ValueError:
        raise ValidationError(error_message, code='invalid', params={'protocol': _('IPv6')})
    if <MASK>:
        return str(addr.ipv4_mapped)
    elif addr.ipv4_mapped:
        return '::ffff:%s' % str(addr.ipv4_mapped)
    return str(addr)

@_datetimelike_compat
def _pad_1d(values: np.ndarray, limit: int | None=None, limit_area: Literal['inside', 'outside'] | None=None, mask: npt.NDArray[np.bool_] | None=None) -> tuple[np.ndarray, npt.NDArray[np.bool_]]:
    mask = _fillna_prep(values, mask)
    if <MASK>:
        _fill_limit_area_1d(mask, limit_area)
    algos.pad_inplace(values, mask, limit=limit)
    return (values, mask)

@register.tag
def resetcycle(parser, token):
    """
    Reset a cycle tag.

    If an argument is given, reset the last rendered cycle tag whose name
    matches the argument, else reset the last rendered cycle tag (named or
    unnamed).
    """
    args = token.split_contents()
    if len(args) > 2:
        raise TemplateSyntaxError('%r tag accepts at most one argument.' % args[0])
    if <MASK>:
        name = args[1]
        try:
            return ResetCycleNode(parser._named_cycle_nodes[name])
        except (AttributeError, KeyError):
            raise TemplateSyntaxError("Named cycle '%s' does not exist." % name)
    try:
        return ResetCycleNode(parser._last_cycle_node)
    except AttributeError:
        raise TemplateSyntaxError('No cycles in template.')

