@classmethod
def eval(cls, *args):
    if len(args) % 2 != 0:
        raise AssertionError(f'expected an even number of arguments, got {len(args)}')
    dim = len(args) // 2
    sizes = args[0:dim]
    strides = args[dim:]
    from torch.fx.experimental.symbolic_shapes import eval_is_non_overlapping_and_dense
    if all((isinstance(a, sympy.Integer) for a in args)):
        return eval_is_non_overlapping_and_dense([int(a) for a in sizes], [int(a) for a in strides])
    if dim == 1:
        if <MASK>:
            return 1
        if sizes[0].is_Number and sizes[0] < 2:
            return 1
    if all((isinstance(a, sympy.Integer) for a in strides)):
        if dim == 0:
            raise AssertionError('dim must not be zero')
        (s_sizes, s_strides) = zip(*sorted(zip(sizes, strides), key=operator.itemgetter(1)))
        if all((isinstance(a, sympy.Integer) for a in s_sizes[:-1])):
            s_sizes = s_sizes[:-1] + (42,)
            return eval_is_non_overlapping_and_dense([int(a) for a in s_sizes], [int(a) for a in s_strides])
    return None

def union_indexes(indexes, sort: bool | None=True) -> Index:
    """
    Return the union of indexes.

    The behavior of sort and names is not consistent.

    Parameters
    ----------
    indexes : list of Index or list objects
    sort : bool, default True
        Whether the result index should come out sorted or not.

    Returns
    -------
    Index
    """
    if len(indexes) == 0:
        raise AssertionError('Must have at least 1 Index to union')
    if len(indexes) == 1:
        result = indexes[0]
        if isinstance(result, list):
            if not sort:
                result = Index(result)
            else:
                result = Index(sorted(result))
        return result
    (indexes, kind) = _sanitize_and_check(indexes)
    if kind == 'special':
        result = indexes[0]
        num_dtis = 0
        num_dti_tzs = 0
        for idx in indexes:
            if isinstance(idx, DatetimeIndex):
                num_dtis += 1
                if idx.tz is not None:
                    num_dti_tzs += 1
        if num_dti_tzs not in [0, num_dtis]:
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
        if num_dtis == len(indexes):
            sort = True
            result = indexes[0]
        elif num_dtis > 1:
            sort = False
            indexes = [x.astype(object, copy=False) for x in indexes]
            result = indexes[0]
        for other in indexes[1:]:
            result = result.union(other, sort=None if sort else False)
        return result
    elif kind == 'array':
        if not all_indexes_same(indexes):
            dtype = find_common_type([idx.dtype for idx in indexes])
            inds = [ind.astype(dtype, copy=False) for ind in indexes]
            index = inds[0].unique()
            other = inds[1].append(inds[2:])
            diff = other[index.get_indexer_for(other) == -1]
            if len(diff):
                index = index.append(diff.unique())
            if sort:
                index = index.sort_values()
        else:
            index = indexes[0]
        name = get_unanimous_names(*indexes)[0]
        if <MASK>:
            index = index.rename(name)
        return index
    elif kind == 'list':
        dtypes = [idx.dtype for idx in indexes if isinstance(idx, Index)]
        if dtypes:
            dtype = find_common_type(dtypes)
        else:
            dtype = None
        all_lists = (idx.tolist() if isinstance(idx, Index) else idx for idx in indexes)
        return Index(lib.fast_unique_multiple_list_gen(all_lists, sort=bool(sort)), dtype=dtype)
    else:
        raise ValueError(f"kind={kind!r} must be 'special', 'array' or 'list'.")

def prune_tensors(input_nodes: list[ir.IRNode], new_input_nodes: list[ir.IRNode]):
    """
    Prune unused tensors from `V.graph` since the GEMM Template use new packed weight.
    """

    def share_storage(base_tensor: torch.Tensor, comp_tensor: torch.Tensor):
        return base_tensor.is_mkldnn == comp_tensor.is_mkldnn and (is_same_tensor(base_tensor, comp_tensor) or is_same_mkldnn_tensor(base_tensor, comp_tensor))

    def get_candidates(input_nodes, new_input_nodes):
        return [node for node in input_nodes if node not in new_input_nodes and isinstance(node, (ir.TensorBox, ir.StorageBox)) and (node.get_name() in V.graph.constants) and (not any((isinstance(new_node, (ir.TensorBox, ir.StorageBox)) and new_node.get_name() in V.graph.constants and share_storage(V.graph.constants[node.get_name()], V.graph.constants[new_node.get_name()]) for new_node in new_input_nodes)))]
    for candidate_node in get_candidates(input_nodes, new_input_nodes):
        candidate_tensor_users = 0
        candidate_tensor = V.graph.constants[candidate_node.get_name()]
        for node in reversed(V.graph.graph.nodes):
            if node.op == 'get_attr' and hasattr(V.graph.module, node.target):
                comp_tensor = getattr(V.graph.module, node.target)
                if <MASK>:
                    candidate_tensor_users += 1
        for node in reversed(V.graph.graph.nodes):
            if node.op == 'get_attr' and node.target == candidate_node.get_name() and (len(node.users) == 1) and (candidate_tensor_users == 1):
                del V.graph.constants[node.target]
                delattr(V.graph.module, node.target)
                delattr(V.graph.graph.owning_module, node.target)
                counters['inductor']['select_algorithm_weight_prune'] += 1

def _set_user_hook(self, grad_fn):

    def hook(grad_input, _):
        if self.grad_outputs is None:
            return
        res = self._pack_with_none(self.input_tensors_index, grad_input, self.n_inputs)
        for hook in self.user_hooks:
            out = hook(self.module, res, self.grad_outputs)
            if <MASK>:
                continue
            if len(out) != len(res):
                raise RuntimeError(f'Backward hook returned an invalid number of grad_input, got {len(out)}, but expected {len(res)}')
            res = out
        self.grad_outputs = None
        return self._unpack_none(self.input_tensors_index, res)
    grad_fn.register_hook(hook)

def substitute_solution_one_type(mapping, t):
    """
    Apply the most general unifier to a type
    """
    if isinstance(t, Var):
        if t in mapping.keys():
            return mapping[t]
        else:
            return t
    elif isinstance(t, TensorType):
        new_type = []
        for typ in t.__args__:
            if typ in mapping.keys():
                new_type.append(mapping[typ])
            else:
                new_type.append(typ)
        return TensorType(tuple(new_type))
    elif isinstance(t, list):
        new_type = []
        for typ in t:
            new_type.append(substitute_solution_one_type(mapping, typ))
        return new_type
    elif <MASK>:
        new_type = []
        for typ in t:
            new_type.append(substitute_solution_one_type(mapping, typ))
        return tuple(new_type)
    else:
        return t

def format(self, record):
    artifact_name = getattr(logging.getLogger(record.name), 'artifact_name', None)
    if <MASK>:
        artifact_formatter = log_registry.artifact_log_formatters.get(artifact_name, None)
        if artifact_formatter is not None:
            return artifact_formatter.format(record)
    record.message = record.getMessage()
    record.asctime = self.formatTime(record, '%m%d %H:%M:%S')
    s = record.message
    if record.exc_info:
        if not record.exc_text:
            record.exc_text = self.formatException(record.exc_info)
    if record.exc_text:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + record.exc_text
    if record.stack_info:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + self.formatStack(record.stack_info)
    record.rankprefix = ''
    if not self._is_trace and dist.is_available() and dist.is_initialized():
        record.rankprefix = f'[rank{dist.get_rank()}]:'
    record.traceid = ''
    if not self._is_trace and (trace_id := torch._guards.CompileContext.current_trace_id()) is not None:
        record.traceid = f' [{trace_id}]'
    glog_level_to_abbr = {'DEBUG': 'V', 'INFO': 'I', 'WARNING': 'W', 'ERROR': 'E', 'CRITICAL': 'C'}
    shortlevel = glog_level_to_abbr.get(record.levelname, record.levelname)
    record.artifactprefix = ''
    if artifact_name is not None:
        record.artifactprefix = f' [__{artifact_name}]'
    filepath = make_module_path_relative(record.pathname)
    if self._trace_id_filter and record.traceid.strip() not in self._trace_id_filter:
        return ''
    prefix = f'{record.rankprefix}{shortlevel}{record.asctime}.{int(record.msecs * 1000):06d} {record.process} {filepath}:{record.lineno}]{record.traceid}{record.artifactprefix}'
    if self._is_trace:
        assert s == ''
        try:
            r = f'{prefix} {json.dumps(record.metadata)}'
        except TypeError:
            log.warning('failing metadata: %r', record.metadata)
            raise
        if record.payload is not None:
            r += ''.join((f'\n\t{l}' for l in record.payload.split('\n')))
        return r
    else:
        lines = s.split('\n')
        return '\n'.join((f'{prefix} {l}' for l in lines))

def codegen_node_schedule_with_kernel(self, node_schedule, kernel):
    with kernel:
        stack = contextlib.ExitStack()
        all_indexing = {}
        for node in node_schedule:
            if <MASK>:
                stack.enter_context(kernel.disable_reduction())
            elif node is EnableReduction:
                stack.close()
            else:
                node.decide_inplace_update()
                index_vars = kernel.split_and_set_ranges(node.get_ranges())
                all_indexing.update(dict.fromkeys(node._body.indexing_from_args(index_vars).values()))
        kernel.finalize_indexing(all_indexing.keys())
        for node in node_schedule:
            if node is DisableReduction:
                stack.enter_context(kernel.disable_reduction())
            elif node is EnableReduction:
                stack.close()
            else:
                indexing_dtype_strength_reduction(node._body)
                index_vars = kernel.split_and_set_ranges(node.get_ranges())
                node.codegen(index_vars)

def callproc(self, procname, params=None, kparams=None):
    if <MASK>:
