def try_to_reduce_precision(node: Any, bounds: dict[Any, Any], indirect_vars: list[Any], indices: dict[Any, sympy.Expr], replacement_vals: dict[Any, ValueRanges[sympy.Expr]]) -> None:

    def skip_filter(node: Any) -> bool:
        return node.target == 'to_dtype' and node.args[2] in (torch.int32, torch.float32, torch.float64)
    for dominated in dominated_nodes([node], skip_filter):
        if dominated.target in ['store', 'output']:
            continue
        if <MASK>:
            idx = int(dominated.target[len('set_indirect'):])
            indirect_var = indirect_vars[idx]
            for (index, expr) in indices.items():
                if indirect_var in expr.free_symbols:
                    index_val = replacement_vals[index]
                    if math.isinf(index_val.lower) or math.isinf(index_val.upper):
                        return
                    index_val_int = ValueRanges[sympy.Expr](int(index_val.lower), int(index_val.upper))
                    if not range_expressable_in_32_bits(index_val_int):
                        return
        if not range_expressable_in_32_bits(bounds[dominated]):
            return
    args = list(node.args)
    args[2] = torch.int32
    node.args = tuple(args)

def load_aoti_eager_cache(ns: str, op_func_name_with_overload: str, device_type: str) -> list[Optional[dict[str, Any]]]:
    device_kernel_cache = aoti_eager_cache_dir(ns, device_type)
    op_conf = device_kernel_cache / f'{op_func_name_with_overload}.json'
    if not op_conf.exists():
        return []
    try:
        with aoti_eager_op_conf_lock(op_func_name_with_overload):
            with open(op_conf) as f:
                json_data = json.load(f)
                for item in json_data:
                    kernel_lib_abs_path = device_kernel_cache / item['kernel_path']
                    item['kernel_path'] = kernel_lib_abs_path.as_posix()
                    if not kernel_lib_abs_path.exists():
                        return []
                    for metadata in item['meta_info']:
                        if <MASK>:
                            raise NotImplementedError('Only support static shape for now')
                        if 'device_type' in metadata and metadata['device_type'] == 'cpu':
                            metadata['device_index'] = -1
                        for dtype_key in ['dtype', 'dtype_value']:
                            if dtype_key in metadata:
                                metadata[dtype_key] = getattr(torch, metadata[dtype_key].split('.')[-1])
                        if 'layout_value' in metadata:
                            metadata['layout_value'] = getattr(torch, metadata['layout_value'].split('.')[-1])
                        if 'memory_format_value' in metadata:
                            metadata['memory_format_value'] = getattr(torch, metadata['memory_format_value'].split('.')[-1])
                return json_data
    except Exception as e:
        err_msg = f'Failed to load aoti eager cache: {e}'
        log.exception(err_msg)
        return []

def _get_global_builtins():
    supported_builtins = ['print', 'tuple', 'float', 'complex', 'int', 'bool', 'str', 'getattr', 'hasattr', 'isinstance', 'len', 'hex', 'oct', 'round', 'hash', 'min', 'max', 'abs', 'all', 'divmod', 'list', 'ord', 'chr', 'bin', 'range', 'zip', 'enumerate', 'sorted']
    op_renames = {'bool': 'aten::Bool', 'int': 'aten::Int', 'float': 'aten::Float', 'complex': 'aten::Complex', 'abs': 'prim::abs', 'max': 'prim::max', 'min': 'prim::min', 'range': 'fake::does_not_exist'}
    schemaless_op_explanations = {'print': 'Print any value', 'tuple': 'Lists cannot be converted to tuples with this method since their size is not statically known', 'getattr': 'Attribute name must be a literal string', 'hasattr': 'Attribute name must be a literal string', 'isinstance': 'Result is static', 'zip': 'Arguments must be iterable.', 'enumerate': 'Arguments must be iterable.', 'range': 'Can only be used as an iterator in a for loop'}
    magic_methods = [('complex', '__complex__'), ('float', '__float__'), ('int', '__int__'), ('bool', '__bool__'), ('str', '__str__'), ('len', '__len__'), ('hex', '__hex__'), ('oct', '__oct__')]
    magic_methods_rows = []
    for (fn, magic_method) in magic_methods:
        magic_methods_rows.append(f'"{fn}", "``{magic_method}``"')
    schematized_ops = []
    schemaless_ops = []
    for fn in supported_builtins:
        op_name = f'aten::{fn}'
        if fn in op_renames:
            op_name = op_renames[fn]
        schemas = torch._C._jit_get_schemas_for_operator(op_name)
        for s in schemas:
            schematized_ops.append(_emit_schema(None, fn, s, padding=0))
        if <MASK>:
            schematized_ops.append('')
        else:
            table_row = f'":external+python:py:obj:`{fn}`", "{schemaless_op_explanations[fn]}"'
            schemaless_ops.append(table_row)
    schematized_ops_str = '\n'.join(schematized_ops)
    schemaless_ops_str = '\n'.join(schemaless_ops)
    magic_methods_rows_str = '\n'.join(magic_methods_rows)
    schematized_ops_str = textwrap.indent(schematized_ops_str, '\t')
    schemaless_ops_str = textwrap.indent(schemaless_ops_str, '\t')
    magic_methods_rows_str = textwrap.indent(magic_methods_rows_str, '\t')
    section = f'\nThe functions in the following table are supported but do not have a static schema\n\n.. csv-table::\n    :header: "Function", "Note"\n\n{schemaless_ops_str}\n\nThe following functions will use the corresponding magic method on TorchScript classes\n\n.. csv-table::\n    :header: "Function", "Magic Method"\n\n{magic_methods_rows_str}\n\nThese built-in functions use the schema\n\n.. rst-class:: codeblock-height-limiter\n\n::\n\n{schematized_ops_str}\n    '
    return ('Python Built-in Functions', section)

@classmethod
def mod(cls, x, y):
    x = ValueRanges.wrap(x)
    y = ValueRanges.wrap(y)

    def c_mod(a, b):
        ret = abs(a) % abs(b)
        if <MASK>:
            ret *= -1
        return ret

    def c_div(a, b):
        x = a / b
        return sympy.Integer(x) if x.is_finite and x not in (int_oo, -int_oo) else x
    if 0 in y:
        return ValueRanges.unknown_int()
    elif y.is_singleton():
        y_val = abs(y.lower)
        if c_div(x.lower, y_val) == c_div(x.upper, y_val):
            return ValueRanges.increasing_map(x, lambda u: c_mod(u, y_val))
        if x.upper < 0:
            return ValueRanges(-y_val + 1, 0)
        elif x.lower > 0:
            return ValueRanges(0, y_val - 1)
        else:
            lower = max(-y_val + 1, x.lower)
            upper = min(y_val - 1, x.upper)
            return ValueRanges(lower, upper)
    else:
        upper = cls.abs(y).upper - 1
        return ValueRanges(-upper, upper)

def _deserialize_keras_object(identifier, module_objects=None, custom_objects=None, printable_module_name='object'):
    """Turns the serialized form of a Keras object back into an actual object."""
    if identifier is None:
        return None
    if isinstance(identifier, dict):
        config = identifier
        (cls, cls_config) = _class_and_config_for_serialized_keras_object(config, module_objects, custom_objects, printable_module_name)
        if hasattr(cls, 'from_config'):
            arg_spec = tf_inspect.getfullargspec(cls.from_config)
            custom_objects = custom_objects or {}
            if 'custom_objects' in arg_spec.args:
                return cls.from_config(cls_config, custom_objects=dict(list(custom_objects.items())))
            return cls.from_config(cls_config)
        else:
            custom_objects = custom_objects or {}
            return cls(**cls_config)
    elif isinstance(identifier, six.string_types):
        object_name = identifier
        if custom_objects and object_name in custom_objects:
            obj = custom_objects.get(object_name)
        else:
            obj = module_objects.get(object_name)
            if <MASK>:
                raise ValueError('Unknown ' + printable_module_name + ': ' + object_name)
        if tf_inspect.isclass(obj):
            return obj()
        return obj
    elif tf_inspect.isfunction(identifier):
        return identifier
    else:
        raise ValueError('Could not interpret serialized %s: %s' % (printable_module_name, identifier))

def deconstruct(self):
    kwargs = {'name': self.name, 'locale': self.locale}
    if <MASK>:
        kwargs['provider'] = self.provider
    if self.deterministic is False:
        kwargs['deterministic'] = self.deterministic
    return (self.__class__.__qualname__, [], kwargs)

def _assertAllCloseRecursive(self, a, b, rtol=1e-06, atol=1e-06, path=None, msg=None):
    if ragged_tensor.is_ragged(a) or ragged_tensor.is_ragged(b):
        return self._assertRaggedClose(a, b, rtol, atol, msg)
    path = path or []
    path_str = '[' + ']['.join((str(p) for p in path)) + ']' if path else ''
    msg = msg if msg else ''
    if hasattr(a, '_asdict'):
        a = a._asdict()
    if hasattr(b, '_asdict'):
        b = b._asdict()
    a_is_dict = isinstance(a, collections_abc.Mapping)
    if a_is_dict != isinstance(b, collections_abc.Mapping):
        raise ValueError("Can't compare dict to non-dict, a%s vs b%s. %s" % (path_str, path_str, msg))
    if a_is_dict:
        self.assertItemsEqual(a.keys(), b.keys(), msg='mismatched keys: a%s has keys %s, but b%s has keys %s. %s' % (path_str, a.keys(), path_str, b.keys(), msg))
        for k in a:
            path.append(k)
            self._assertAllCloseRecursive(a[k], b[k], rtol=rtol, atol=atol, path=path, msg=msg)
            del path[-1]
    elif <MASK>:
        try:
            (a, b) = self.evaluate_if_both_tensors(a, b)
            a_as_ndarray = self._GetNdArray(a)
            b_as_ndarray = self._GetNdArray(b)
            self._assertArrayLikeAllClose(a_as_ndarray, b_as_ndarray, rtol=rtol, atol=atol, msg='Mismatched value: a%s is different from b%s. %s' % (path_str, path_str, msg))
        except (ValueError, TypeError, NotImplementedError) as e:
            if len(a) != len(b):
                raise ValueError('Mismatched length: a%s has %d items, but b%s has %d items. %s' % (path_str, len(a), path_str, len(b), msg))
            for (idx, (a_ele, b_ele)) in enumerate(zip(a, b)):
                path.append(str(idx))
                self._assertAllCloseRecursive(a_ele, b_ele, rtol=rtol, atol=atol, path=path, msg=msg)
                del path[-1]
    else:
        try:
            self._assertArrayLikeAllClose(a, b, rtol=rtol, atol=atol, msg='Mismatched value: a%s is different from b%s. %s' % (path_str, path_str, msg))
        except TypeError as e:
            msg = 'Error: a%s has %s, but b%s has %s. %s' % (path_str, type(a), path_str, type(b), msg)
            e.args = (e.args[0] + ' : ' + msg,) + e.args[1:]
            raise

def _save_triton_kernels() -> None:
    try:
        resource_dir = self.get_resources_dir()
    except Exception as e:
        warn(f'Execution trace exception when generating resource directory: {e}')
        return
    if <MASK>:
        return
    from torch._inductor.codecache import PyCodeCache
    kernel_files = [v.__file__ for v in PyCodeCache.modules if getattr(v, '__file__', None) is not None]
    for kernel_file in kernel_files:
        if kernel_file is None:
            continue
        name = os.path.basename(kernel_file)
        dst = os.path.join(resource_dir, name)
        shutil.copyfile(kernel_file, dst)

