def grab_method_and_template(in_kernel):
    pos = {'kernel_launch': {'start': in_kernel['start'], 'end': in_kernel['end']}, 'kernel_name': {'start': -1, 'end': -1}, 'template': {'start': -1, 'end': -1}}
    count = {'<>': 0}
    START = 0
    AT_TEMPLATE = 1
    AFTER_TEMPLATE = 2
    AT_KERNEL_NAME = 3
    status = START
    for i in range(pos['kernel_launch']['start'] - 1, -1, -1):
        char = string[i]
        if status in (START, AT_TEMPLATE):
            if <MASK>:
                if status == START:
                    status = AT_TEMPLATE
                    pos['template']['end'] = i
                count['<>'] += 1
            if char == '<':
                count['<>'] -= 1
                if count['<>'] == 0 and status == AT_TEMPLATE:
                    pos['template']['start'] = i
                    status = AFTER_TEMPLATE
        if status != AT_TEMPLATE:
            if string[i].isalnum() or string[i] in {'(', ')', '_', ':', '#'}:
                if status != AT_KERNEL_NAME:
                    status = AT_KERNEL_NAME
                    pos['kernel_name']['end'] = i
                if i == 0:
                    pos['kernel_name']['start'] = 0
                    return [pos['kernel_name'], pos['template'], pos['kernel_launch']]
            elif status == AT_KERNEL_NAME:
                pos['kernel_name']['start'] = i
                return [pos['kernel_name'], pos['template'], pos['kernel_launch']]

def cmdline_to_win(line):
    if line.startswith('# '):
        return 'REM ' + args_to_win(line[2:])
    if line.startswith('$ # '):
        return 'REM ' + args_to_win(line[4:])
    if line.startswith('$ ./manage.py'):
        return 'manage.py ' + args_to_win(line[13:])
    if line.startswith('$ manage.py'):
        return 'manage.py ' + args_to_win(line[11:])
    if line.startswith('$ ./runtests.py'):
        return 'runtests.py ' + args_to_win(line[15:])
    if line.startswith('$ ./'):
        return args_to_win(line[4:])
    if line.startswith('$ python3'):
        return 'py ' + args_to_win(line[9:])
    if <MASK>:
        return 'py ' + args_to_win(line[8:])
    if line.startswith('$ '):
        return args_to_win(line[2:])
    return None

def get_storage_info(storage):
    if not isinstance(storage, torch.utils.show_pickle.FakeObject):
        raise AssertionError(f'storage is not FakeObject: {type(storage)}')
    if storage.module != 'pers':
        raise AssertionError(f"storage.module is not 'pers': {storage.module!r}")
    if storage.name != 'obj':
        raise AssertionError(f"storage.name is not 'obj': {storage.name!r}")
    if storage.state is not None:
        raise AssertionError(f'storage.state is not None: {storage.state!r}')
    if not isinstance(storage.args, tuple):
        raise AssertionError(f'storage.args is not a tuple: {type(storage.args)}')
    if len(storage.args) != 1:
        raise AssertionError(f'len(storage.args) is not 1: {len(storage.args)}')
    sa = storage.args[0]
    if not isinstance(sa, tuple):
        raise AssertionError(f'sa is not a tuple: {type(sa)}')
    if len(sa) != 5:
        raise AssertionError(f'len(sa) is not 5: {len(sa)}')
    if sa[0] != 'storage':
        raise AssertionError(f"sa[0] is not 'storage': {sa[0]!r}")
    if not isinstance(sa[1], torch.utils.show_pickle.FakeClass):
        raise AssertionError(f'sa[1] is not FakeClass: {type(sa[1])}')
    if sa[1].module != 'torch':
        raise AssertionError(f"sa[1].module is not 'torch': {sa[1].module!r}")
    if <MASK>:
        raise AssertionError(f"sa[1].name does not end with 'Storage': {sa[1].name!r}")
    storage_info = [sa[1].name.replace('Storage', '')] + list(sa[2:])
    return storage_info

def deserialize_output_spec(self, o: OutputSpec) -> ep.OutputSpec:
    log.debug('[deserialize_output_spec] %s', o)
    if o.type == 'user_output':
        return ep.OutputSpec(kind=ep.OutputKind.USER_OUTPUT, arg=self.deserialize_argument_spec(o.user_output.arg), target=None)
    elif o.type == 'loss_output':
        return ep.OutputSpec(kind=ep.OutputKind.LOSS_OUTPUT, arg=ep.TensorArgument(name=o.loss_output.arg.name), target=None)
    elif o.type == 'buffer_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.BUFFER_MUTATION, arg=ep.TensorArgument(name=o.buffer_mutation.arg.name), target=o.buffer_mutation.buffer_name)
    elif o.type == 'parameter_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.PARAMETER_MUTATION, arg=ep.TensorArgument(name=o.parameter_mutation.arg.name), target=o.parameter_mutation.parameter_name)
    elif o.type == 'gradient_to_parameter':
        return ep.OutputSpec(kind=ep.OutputKind.GRADIENT_TO_PARAMETER, arg=ep.TensorArgument(name=o.gradient_to_parameter.arg.name), target=o.gradient_to_parameter.parameter_name)
    elif o.type == 'gradient_to_user_input':
        return ep.OutputSpec(kind=ep.OutputKind.GRADIENT_TO_USER_INPUT, arg=ep.TensorArgument(name=o.gradient_to_user_input.arg.name), target=o.gradient_to_user_input.user_input_name)
    elif <MASK>:
        return ep.OutputSpec(kind=ep.OutputKind.USER_INPUT_MUTATION, arg=ep.TensorArgument(name=o.user_input_mutation.arg.name), target=o.user_input_mutation.user_input_name)
    elif o.type == 'token':
        return ep.OutputSpec(kind=ep.OutputKind.TOKEN, arg=ep.TokenArgument(name=o.token.arg.name), target=None)
    else:
        raise AssertionError(f'Unknown output spec {o}')

def bucket_key(node: torch.fx.Node) -> object | None:
    if <MASK>:
