def log_prob(self, value):
    if <MASK>:
        self._validate_sample(value)
    var = self.scale ** 2
    log_scale = math.log(self.scale) if isinstance(self.scale, _Number) else self.scale.log()
    return -(value - self.loc) ** 2 / (2 * var) - log_scale - math.log(math.sqrt(2 * math.pi))

@_onnx_symbolic('aten::split')
@symbolic_helper.parse_args('v', 'v', 'i', 'i')
def split(g: jit_utils.GraphContext, self, split_size_or_sizes, dim, _outputs=None):
    if not symbolic_helper._is_split_static(split_size_or_sizes, _outputs):
        split_out = g.op('SplitToSequence', self, split_size_or_sizes, axis_i=dim)
        if _outputs is None:
            return split_out
        if symbolic_helper._is_packed_list(split_size_or_sizes) and len(symbolic_helper._unpack_list(split_size_or_sizes)) == _outputs:
            split_sizes = [symbolic_helper._unsqueeze_helper(g, v, [0]) for v in symbolic_helper._unpack_list(split_size_or_sizes)]
            start = g.op('Constant', value_t=torch.tensor([0], dtype=torch.long))
            axis = g.op('Constant', value_t=torch.tensor([dim], dtype=torch.long))
            res = []
            for i in range(_outputs):
                end = g.op('Add', start, split_sizes[i])
                res.append(g.op('Slice', self, start, end, axis))
                start = end
            return res
        return [g.op('SequenceAt', split_out, g.op('Constant', value_t=torch.tensor([i], dtype=torch.long))) for i in range(_outputs)]
    split_val = symbolic_helper._node_get(split_size_or_sizes.node(), 'value')
    if split_val.dim() > 0:
        return g.op('Split', self, split_size_or_sizes, axis_i=dim, outputs=_outputs)
    split_size = symbolic_helper._get_const(split_size_or_sizes, 'i', 'split_size')
    size = symbolic_helper._get_tensor_dim_size(self, dim)
    if size is None:
        if _outputs is not None:
            size = split_size * _outputs
        else:
            raise errors.SymbolicValueError('Unknown dimension size not supported', self)
    splits = [split_size] * (size // split_size)
    leftover = size % split_size
    if <MASK>:
        splits.append(leftover)
    splits = g.op('Constant', value_t=torch.tensor(splits))
    return g.op('Split', self, splits, axis_i=dim, outputs=_outputs)

def _get_elided_page_range(self, number, num_pages, page_range, on_each_side=3, on_ends=2):
    """
        Return a 1-based range of pages with some values elided.

        If the page range is larger than a given size, the whole range is not
        provided and a compact form is returned instead, e.g. for a paginator
        with 50 pages, if page 43 were the current page, the output, with the
        default arguments, would be:

            1, 2, …, 40, 41, 42, 43, 44, 45, 46, …, 49, 50.
        """
    if num_pages <= (on_each_side + on_ends) * 2:
        for page in page_range:
            yield page
        return
    if <MASK>:
        for page in range(1, on_ends + 1):
            yield page
        yield self.ELLIPSIS
        for page in range(number - on_each_side, number + 1):
            yield page
    else:
        for page in range(1, number + 1):
            yield page
    if number < num_pages - on_each_side - on_ends - 1:
        for page in range(number + 1, number + on_each_side + 1):
            yield page
        yield self.ELLIPSIS
        for page in range(num_pages - on_ends + 1, num_pages + 1):
            yield page
    else:
        for page in range(number + 1, num_pages + 1):
            yield page

def _make_converter(tf_dtype):

    def _converter(x):
        if <MASK>:
            return np.asarray(x).astype('|S')
        x = np.asarray(x).astype(tf_dtype.as_numpy_dtype)
        if tf_dtype.is_complex:
            x -= 1j * x
        return x
    return _converter

def _validate_X_predict(self, X):
    """
        Validate X whenever one tries to predict, apply, predict_proba."""
    check_is_fitted(self)
    if self.estimators_[0]._support_missing_values(X):
        ensure_all_finite = 'allow-nan'
    else:
        ensure_all_finite = True
    X = validate_data(self, X, dtype=DTYPE, accept_sparse='csr', reset=False, ensure_all_finite=ensure_all_finite)
    if <MASK>:
        raise ValueError('No support for np.int64 index based sparse matrices')
    return X

def postprocess_forward_derivatives(f: NativeFunction, defn_name: str, all_arg_names: list[str], derivatives: list[Derivative], forward_derivatives: list[ForwardDerivative], args_with_derivatives: Sequence[Binding]) -> list[ForwardDerivative]:

    def find_required_inputs(formula: str, postfix: str) -> tuple[str, ...]:
        is_foreach = f.func.name.name.base.startswith('_foreach_')
        required_inputs = set()
        for arg in args_with_derivatives:
            if arg.type in ('at::TensorList', 'const at::ITensorListRef &') and (not is_foreach):
                continue
            arg_name = arg.name
            found = re.search(IDENT_REGEX.format(arg_name), formula)
            if <MASK>:
                raise RuntimeError(f'The forward formula for {defn_name} is using the base name of the {arg_name} argument which is ambiguous. You should use {arg_name}_p to access the primal value and {arg_name}_t to access the tangent.')
            found = re.search(IDENT_REGEX.format(arg_name + postfix), formula)
            if found:
                required_inputs.add(arg_name)
        return tuple(required_inputs)
    updated_derivatives: list[ForwardDerivative] = []
    for defn in forward_derivatives:
        formula = defn.formula
        required_inputs_tangent = find_required_inputs(formula, '_t')
        if formula == 'auto_element_wise':
            assert f.func.kind() != SchemaKind.inplace, f'Cannot use auto_element_wise with {f.func.name} because it is an in-place variant'
            if not len(args_with_derivatives) == 1 or len(forward_derivatives) > 1 or len(forward_derivatives[0].var_names) > 1:
                raise RuntimeError(f'Derivative definition of {defn_name} in derivatives.yaml defines the forward definition of gradient as element_wise but this only works for functions with a single differentiable input and a single differentiable output.')
            if not len(derivatives) == 1:
                raise RuntimeError(f'Derivative definition of {defn_name} in derivatives.yaml defines the forward definition of gradient as element_wise but it does not defines the gradient formula for its argument which is required.')
            backward_formula = derivatives[0].original_formula
            input_name = args_with_derivatives[0].name

            def repl(m: Any) -> str:
                return f'{m.group(1)}{input_name}_t.conj(){m.group(2)}'
            fw_formula = re.sub(IDENT_REGEX.format('grad'), repl, backward_formula)
            for arg in args_with_derivatives:
                arg_name = arg.name

                def repl(m: Any) -> str:
                    return f'{m.group(1)}{arg_name}_p{m.group(2)}'
                fw_formula = re.sub(IDENT_REGEX.format(arg_name), repl, fw_formula)
            fw_formula = f'({fw_formula}).conj()'
            required_inputs_tangent = tuple(all_arg_names)
            formula = fw_formula
        elif formula == 'auto_linear':
            if len(forward_derivatives) > 1 or len(forward_derivatives[0].var_names) > 1:
                raise RuntimeError(f'Derivative definition of {defn_name} in derivatives.yaml defines the forward definition of gradient as linear but this only works for functions with a single differentiable output.')
            diff_arg_names = [arg.name for arg in args_with_derivatives]
            assert len(diff_arg_names) > 0
            new_args = []
            for arg_name in all_arg_names:
                if arg_name in diff_arg_names:
                    arg_name = arg_name + '_t'
                new_args.append(arg_name)
            if f.func.has_symint():
                defn_name += '_symint'
            if Variant.function in f.variants:
                fw_formula = f"at::{defn_name}({', '.join(new_args)})"
            else:
                assert Variant.method in f.variants
                fw_formula = f"{new_args[0]}.{defn_name}({', '.join(new_args[1:])})"
            required_inputs_tangent = tuple(diff_arg_names)
            formula = fw_formula
        required_inputs_primal = find_required_inputs(formula, '_p')
        updated_derivatives.append(ForwardDerivative(formula=formula, var_names=defn.var_names, var_types=defn.var_types, required_inputs_fw_grad=required_inputs_tangent, required_inputs_primal=required_inputs_primal, required_original_self_value=False, is_reusing_outplace_formula=False))
    return updated_derivatives

@def_function.function
def run_loop(n):
    ticker.assign(0)
    i = constant_op.constant(0)
    t_acc = tensor_array_ops.TensorArray(dtypes.int32, size=0, dynamic_size=True)
    if read_before:
        rb = ticker.read_value()
    else:
        rb = constant_op.constant(0)
    if modify_before:
        ticker.assign_add(1)
    while i < n:
        directives.set_loop_options(parallel_iterations=10)
        if <MASK>:
            ticker.assign_add(1)
        t_acc = t_acc.write(i, ticker.read_value())
        i += 1
    if read_after:
        ra = ticker.read_value()
    else:
        ra = constant_op.constant(0)
    if modify_after:
        ticker.assign_add(1)
    return (t_acc.stack(), rb, ra)

def __new__(cls, data=None, dtype=None, copy: bool=False, name=None, tupleize_cols: bool=True) -> Self:
    from pandas.core.indexes.range import RangeIndex
    name = maybe_extract_name(name, data, cls)
    if dtype is not None:
        dtype = pandas_dtype(dtype)
    data_dtype = getattr(data, 'dtype', None)
    refs = None
    if not copy and isinstance(data, (ABCSeries, Index)):
        refs = data._references
    if isinstance(data, (range, RangeIndex)):
        result = RangeIndex(start=data, copy=copy, name=name)
        if dtype is not None:
            return result.astype(dtype, copy=False)
        return result
    elif is_ea_or_datetimelike_dtype(dtype):
        if isinstance(data, (set, frozenset)):
            data = list(data)
    elif is_ea_or_datetimelike_dtype(data_dtype):
        pass
    elif isinstance(data, (np.ndarray, ABCMultiIndex)):
        if isinstance(data, ABCMultiIndex):
            data = data._values
        if data.dtype.kind not in 'iufcbmM':
            data = com.asarray_tuplesafe(data, dtype=_dtype_obj)
    elif isinstance(data, (ABCSeries, Index)):
        pass
    elif is_scalar(data):
        raise cls._raise_scalar_data_error(data)
    elif <MASK>:
        return cls(np.asarray(data), dtype=dtype, copy=copy, name=name)
    elif not is_list_like(data) and (not isinstance(data, memoryview)):
        raise cls._raise_scalar_data_error(data)
    else:
        if tupleize_cols:
            if is_iterator(data):
                data = list(data)
            if data and all((isinstance(e, tuple) for e in data)):
                from pandas.core.indexes.multi import MultiIndex
                return MultiIndex.from_tuples(data, names=name)
        if not isinstance(data, (list, tuple)):
            data = list(data)
        if len(data) == 0:
            data = np.array(data, dtype=object)
        if len(data) and isinstance(data[0], tuple):
            data = com.asarray_tuplesafe(data, dtype=_dtype_obj)
    try:
        arr = sanitize_array(data, None, dtype=dtype, copy=copy)
    except ValueError as err:
        if 'index must be specified when data is not list-like' in str(err):
            raise cls._raise_scalar_data_error(data) from err
        if 'Data must be 1-dimensional' in str(err):
            raise ValueError('Index data must be 1-dimensional') from err
        raise
    arr = ensure_wrapped_if_datetimelike(arr)
    klass = cls._dtype_to_subclass(arr.dtype)
    arr = klass._ensure_array(arr, arr.dtype, copy=False)
    return klass._simple_new(arr, name, refs=refs)

def train(train_step, weights):
    torch.manual_seed(16)
    train_step(inp, weights)
    begin = time.time()
    for itr in range(1000):
        (loss, weights) = train_step(torch.randn(batch_size, features), weights)
        if <MASK>:
            print(f'Loss at {itr}: {loss}')
    print('Time taken: ', time.time() - begin)
    print()

def set_cookie(self, key, value='', max_age=None, expires=None, path='/', domain=None, secure=False, httponly=False, samesite=None):
    """
        Set a cookie.

        ``expires`` can be:
        - a string in the correct format,
        - a naive ``datetime.datetime`` object in UTC,
        - an aware ``datetime.datetime`` object in any time zone.
        If it is a ``datetime.datetime`` object then calculate ``max_age``.

        ``max_age`` can be:
        - int/float specifying seconds,
        - ``datetime.timedelta`` object.
        """
    self.cookies[key] = value
    if expires is not None:
        if isinstance(expires, datetime.datetime):
            if timezone.is_naive(expires):
                expires = timezone.make_aware(expires, datetime.UTC)
            delta = expires - datetime.datetime.now(tz=datetime.UTC)
            delta += datetime.timedelta(seconds=1)
            expires = None
            if <MASK>:
                raise ValueError("'expires' and 'max_age' can't be used together.")
            max_age = max(0, delta.days * 86400 + delta.seconds)
        else:
            self.cookies[key]['expires'] = expires
    else:
        self.cookies[key]['expires'] = ''
    if max_age is not None:
        if isinstance(max_age, datetime.timedelta):
            max_age = max_age.total_seconds()
        self.cookies[key]['max-age'] = int(max_age)
        if not expires:
            self.cookies[key]['expires'] = http_date(time.time() + max_age)
    if path is not None:
        self.cookies[key]['path'] = path
    if domain is not None:
        self.cookies[key]['domain'] = domain
    if secure:
        self.cookies[key]['secure'] = True
    if httponly:
        self.cookies[key]['httponly'] = True
    if samesite:
        if samesite.lower() not in ('lax', 'none', 'strict'):
            raise ValueError('samesite must be "lax", "none", or "strict".')
        self.cookies[key]['samesite'] = samesite

@parameterized.parameters(['cuda', 'mkl'])
@test_util.run_deprecated_v1
@test_util.disable_xla('This test does not pass with XLA')
@test_util.run_without_tensor_float_32('Avoid TF32 convs on A100+ GPUs')
def test_matmul_biasadd_activation_fusion(self, mode):
    """Test MatMul+BiasAdd+Gelu fusion."""
    self.maybe_skip_test(mode)

    def gelu_approximate(x):
        return nn.gelu(x, approximate=True)

    def gelu_exact(x):
        return nn.gelu(x, approximate=False)

    def gelu_exact_erfc(x):
        return 0.5 * x * math_ops.erfc(-x * math_ops.cast(0.7071067811865476, x.dtype))
    device = '/device:GPU:0' if mode == 'cuda' else '/device:CPU:0'
    config = []
    use_fp16 = True
    if test_util.IsMklEnabled() and (not _pywrap_utils.IsDataTypeSupportedByOneDNNOnThisCPU(dtypes.float16)):
        use_fp16 = False
    if mode == 'mkl':
        config.append((dtypes.float32, gelu_exact, b'GeluExact'))
        config.append((dtypes.float32, gelu_exact_erfc, b'GeluExact'))
        config.append((dtypes.float32, gelu_approximate, b'GeluApproximate'))
        if _pywrap_utils.IsDataTypeSupportedByOneDNNOnThisCPU(dtypes.bfloat16):
            config.append((dtypes.bfloat16, gelu_approximate, b'GeluApproximate'))
            config.append((dtypes.bfloat16, gelu_exact, b'GeluExact'))
    elif mode == 'cuda':
        config.append((dtypes.float32, gelu_approximate, b'GeluApproximate'))
        if use_fp16:
            config.append((dtypes.float16, gelu_approximate, b'GeluApproximate'))
        if test_util.is_gpu_available(cuda_only=True, min_cuda_compute_capability=(8, 0)):
            config.append((dtypes.float16, gelu_exact, b'GeluExact'))
            config.append((dtypes.float16, math_ops.tanh, b'Tanh'))
            config.append((dtypes.float16, math_ops.sigmoid, b'Sigmoid'))
    (m, n, k) = (2, 4, 6)
    fused_op = ['_MklNativeFusedMatMul', '_MklFusedMatMul', '_FusedMatMul']
    for (precision, act_fn, act_name) in config:
        for transpose in (False, True):
            ops.reset_default_graph()
            with ops.device(device):
                x = _input([k, m] if transpose else [m, k])
                w = _weight([n, k] if transpose else [k, n])
                b = _bias([n])
                x = math_ops.cast(x, precision)
                w = math_ops.cast(w, precision)
                b = math_ops.cast(b, precision)
                y = math_ops.matmul(x, w, transpose_a=transpose, transpose_b=transpose)
                z = nn.bias_add(y, b)
                out = act_fn(z)
            if transpose and device == '/device:CPU:0' and (act_name in (b'GeluApproximate', b'GeluExact')):
                if <MASK>:
                    self._VerifyNoFusion(out)
                    continue
                else:
                    epilog_ops = [b'BiasAdd']
            else:
                epilog_ops = [b'BiasAdd', act_name]
            graph = self._VerifyValues(out, precision != dtypes.float32, fused_op, epilog_ops)

def forced_specializations(self) -> dict[str, sympy.Expr]:
    """Returns a dictionary of the names of symbols to their specialized value"""

    def debug_name(src: Source) -> str:
        name = src.name()
        if <MASK>:
            return f'{self._dcp.source_name_to_debug_name[name]} = {name}'
        else:
            return name
    return {debug_name(self._dcp.symbol_to_source[s][0]): val for (s, val) in self._substitutions.items() if s in self._marked_dynamic}

def _get_default_signal() -> signal.Signals:
    """Get the default termination signal. SIGTERM for unix, CTRL_C_EVENT for windows."""
    if <MASK>:
        return signal.CTRL_C_EVENT
    else:
        return signal.SIGTERM

def mk_repl(templ, include_current_dir=True):

    def repl(m):
        f = m.group(1)
        filename = os.path.basename(f)
        if f.startswith(('ATen/cuda', 'ATen/native/cuda', 'ATen/native/nested/cuda', 'ATen/native/quantized/cuda', 'ATen/native/sparse/cuda', 'ATen/native/transformers/cuda', 'THC/')) or (f.startswith('THC') and (not f.startswith('THCP'))):
            return templ.format(get_hip_file_path(m.group(1), is_pytorch_extension))
        if is_pytorch_extension and any((s.endswith(filename) for s in all_files)):
            header_dir = None
            header_filepath = None
            if include_current_dir:
                header_dir_to_check = os.path.dirname(fin_path)
                header_path_to_check = os.path.abspath(os.path.join(header_dir_to_check, f))
                if os.path.exists(header_path_to_check):
                    header_dir = header_dir_to_check
                    header_filepath = header_path_to_check
            if header_filepath is None:
                for header_include_dir in header_include_dirs:
                    header_dir_to_check = os.path.join(output_directory, header_include_dir)
                    header_path_to_check = os.path.abspath(os.path.join(header_dir_to_check, f))
                    if os.path.exists(header_path_to_check):
                        header_dir = header_dir_to_check
                        header_filepath = header_path_to_check
            if header_filepath is None:
                return m.group(0)
            if header_filepath not in HIPIFY_FINAL_RESULT:
                preprocess_file_and_save_result(output_directory, header_filepath, all_files, header_include_dirs, stats, hip_clang_launch, is_pytorch_extension, clean_ctx, show_progress)
            elif <MASK>:
                header_result = HIPIFY_FINAL_RESULT[header_filepath]
                if header_result.current_state == CurrentState.INITIALIZED:
                    header_rel_path = os.path.relpath(header_filepath, output_directory)
                    header_fout_path = os.path.abspath(os.path.join(output_directory, get_hip_file_path(header_rel_path, is_pytorch_extension)))
                    header_result.hipified_path = header_fout_path
                    HIPIFY_FINAL_RESULT[header_filepath] = header_result
                    return templ.format(os.path.relpath(header_fout_path if header_fout_path is not None else header_filepath, header_dir))
            hipified_header_filepath = HIPIFY_FINAL_RESULT[header_filepath].hipified_path
            return templ.format(_to_unix_path(os.path.relpath(hipified_header_filepath if hipified_header_filepath is not None else header_filepath, header_dir)))
        return m.group(0)
    return repl

def can_fast_delete(self, objs, from_field=None):
    """
        Determine if the objects in the given queryset-like or single object
        can be fast-deleted. This can be done if there are no cascades, no
        parents and no signal listeners for the object class.

        The 'from_field' tells where we are coming from - we need this to
        determine if the objects are in fact to be deleted. Allow also
        skipping parent -> child -> parent chain preventing fast delete of
        the child.
        """
    if self.force_collection:
        return False
    if from_field and from_field.remote_field.on_delete is not CASCADE:
        return False
    if hasattr(objs, '_meta'):
        model = objs._meta.model
    elif hasattr(objs, 'model') and hasattr(objs, '_raw_delete'):
        model = objs.model
    else:
        return False
    if <MASK>:
        return False
    opts = model._meta
    return all((link == from_field for link in opts.concrete_model._meta.parents.values())) and all((related.field.remote_field.on_delete in SKIP_COLLECTION for related in get_candidate_relations_to_delete(opts))) and (not any((hasattr(field, 'bulk_related_objects') for field in opts.private_fields)))

@staticmethod
def build_inline_tracer(parent: Any, func: VariableTracker, args: list[VariableTracker], kwargs: Any) -> InliningInstructionTranslator:
    assert isinstance(func, (UserFunctionVariable, NestedUserFunctionVariable, LocalGeneratorFunctionVariable, LocalGeneratorObjectVariable))
    code: types.CodeType = func.get_code()
    result = None
    tracing_ctx = parent.output.tracing_context
    if not config.dont_skip_tracing and tracing_ctx:
        if (previous_result := tracing_ctx.previously_inlined_functions.get(code, None)):
            result = previous_result
    if result is None:
        if isinstance(func, SkipFunctionVariable):
            unimplemented_v2(gb_type='Attempted to inline function marked as skipped (SkipFunctionVariable)', context=f'Attempted to inline a SkipFunctionVariable {func}', explanation='Attempted to inline a function that was previously determined to be marked as intentionally skipped.', hints=[])
        result = InliningInstructionTranslator.check_inlineable(func)
        assert result.skipped is False
        if not config.dont_skip_tracing and tracing_ctx:
            tracing_ctx.previously_inlined_functions[code] = result
    try:
        sub_locals = func.bind_args(parent, args, kwargs)
    except TypeError as e:
        raise ArgsMismatchError('{reason}.\n  func = {func}, args = {args}, kwargs = {kwargs}'.format(reason=str(e), func=f"'{func.get_name()}' {func.get_filename()}:{func.get_code().co_firstlineno}", args=[arg.python_type() for arg in args], kwargs=kwargs))
    for v in itertools.chain(sub_locals.values()):
        if not isinstance(v, VariableTracker):
            unimplemented_v2(gb_type='Encountered unconverted argument when attempting to inline', context=f'func: {func}, arg: {v}', explanation='An argument to an inlined function was not successfully converted to a VariableTracker.', hints=[*graph_break_hints.DYNAMO_BUG])
    if code.co_name in ('__setitem__', '__setattr__') and (not (args and isinstance(args[0], variables.UserDefinedObjectVariable))):
        unimplemented_v2(gb_type='Unsupported __setitem__/__setattr__ inline attempt', context=f'code name: {code.co_name}, args: {args}', explanation=f'Attempted to inline {code.co_name} where first argument (self) is not a user-defined object.', hints=[])
    suffix = ''
    if torch._logging._internal.log_state.is_artifact_enabled('bytecode'):
        suffix = f'\n{dis.Bytecode(code).dis()}'
    if sys.version_info >= (3, 11):
        cur_inst = parent.current_instruction
        parent_code = parent.f_code

        def get_trace_call_log_str() -> str:
            header = parent.get_line_of_code_header(lineno=cur_inst.positions.lineno)
            line = get_instruction_source_311(parent_code, cur_inst).rstrip()
            return f'TRACE inlined call {code.co_name} from {header}\n{line}'
        trace_call_log.debug('%s', LazyString(get_trace_call_log_str))
    log.debug('INLINING %s%s, %s', code, suffix, result.reason)
    if args and isinstance(args[0], NNModuleVariable):
        module = parent.output.get_submodule(args[0].module_key)
        if isinstance(module, torch.fx.GraphModule):
            code_context.get_context(module.forward.__code__)['orig_graphmodule'] = weakref.ref(module)
    if args and isinstance(args[0], UnspecializedNNModuleVariable):
        module = args[0].value
        if isinstance(module, torch.fx.GraphModule):
            code_context.get_context(module.forward.__code__)['orig_graphmodule'] = weakref.ref(module)
    tracer: InliningInstructionTranslator
    if <MASK>:
        tracer = InliningGeneratorInstructionTranslator(parent, code, sub_locals, parent.symbolic_globals, parent.symbolic_torch_function_state, func)
    else:
        assert not isinstance(func, LocalGeneratorObjectVariable)
        tracer = InliningInstructionTranslator(parent, code, sub_locals, parent.symbolic_globals, parent.symbolic_torch_function_state, func)
    return tracer

@staticmethod
def from_example(obj: Any) -> Any:
    import torch
    if <MASK>:
        return torch._C.AnyType.get()
    elif isinstance(obj, torch.SymInt):
        return torch._C.SymIntType.get()
    elif isinstance(obj, torch.SymBool):
        return torch._C.SymBoolType.get()
    return torch._C._jit_try_infer_type(obj).type()

def _get_level_indexer(self, key, level: int=0, indexer: npt.NDArray[np.bool_] | None=None):
    level_index = self.levels[level]
    level_codes = self.codes[level]

    def convert_indexer(start, stop, step, indexer=indexer, codes=level_codes):
        if indexer is not None:
            codes = codes[indexer]
        if step is None or step == 1:
            new_indexer = (codes >= start) & (codes < stop)
        else:
            r = np.arange(start, stop, step, dtype=codes.dtype)
            new_indexer = algos.isin(codes, r)
        if indexer is None:
            return new_indexer
        indexer = indexer.copy()
        indexer[indexer] = new_indexer
        return indexer
    if isinstance(key, slice):
        step = key.step
        is_negative_step = step is not None and step < 0
        try:
            if key.start is not None:
                start = level_index.get_loc(key.start)
            elif is_negative_step:
                start = len(level_index) - 1
            else:
                start = 0
            if <MASK>:
                stop = level_index.get_loc(key.stop)
            elif is_negative_step:
                stop = 0
            elif isinstance(start, slice):
                stop = len(level_index)
            else:
                stop = len(level_index) - 1
        except KeyError:
            start = stop = level_index.slice_indexer(key.start, key.stop, key.step)
            step = start.step
        if isinstance(start, slice) or isinstance(stop, slice):
            start = getattr(start, 'start', start)
            stop = getattr(stop, 'stop', stop)
            return convert_indexer(start, stop, step)
        elif level > 0 or self._lexsort_depth == 0 or step is not None:
            stop = stop - 1 if is_negative_step else stop + 1
            return convert_indexer(start, stop, step)
        else:
            i = algos.searchsorted(level_codes, start, side='left')
            j = algos.searchsorted(level_codes, stop, side='right')
            return slice(i, j, step)
    else:
        idx = self._get_loc_single_level_index(level_index, key)
        if level > 0 or self._lexsort_depth == 0:
            if isinstance(idx, slice):
                locs = (level_codes >= idx.start) & (level_codes < idx.stop)
                return locs
            locs = np.asarray(level_codes == idx, dtype=bool)
            if not locs.any():
                raise KeyError(key)
            return locs
        if isinstance(idx, slice):
            start = algos.searchsorted(level_codes, idx.start, side='left')
            end = algos.searchsorted(level_codes, idx.stop, side='left')
        else:
            start = algos.searchsorted(level_codes, idx, side='left')
            end = algos.searchsorted(level_codes, idx, side='right')
        if start == end:
            raise KeyError(key)
        return slice(start, end)

def _train_batch_sizes(self):
    """Choose batch sizes based on GPU capability."""
    for device in device_lib.list_local_devices():
        if tf.DeviceSpec.from_string(device.name).device_type == 'GPU':
            if <MASK>:
                return (16,)
            if 'P1000' in device.physical_device_desc:
                return (16,)
            if 'P100' in device.physical_device_desc:
                return (16, 32, 64)
        if tf.DeviceSpec.from_string(device.name).device_type == 'TPU':
            return (32,)
    return (16, 32)

def conda_package_to_pip(package: str):
    """
    Convert a conda package to its pip equivalent.

    In most cases they are the same, those are the exceptions:
    - Packages that should be excluded (in `EXCLUDE`)
    - Packages that should be renamed (in `CONDA_TO_PIP`)
    - A package requiring a specific version, in conda is defined with a single
      equal (e.g. ``pandas=1.0``) and in pip with two (e.g. ``pandas==1.0``)
    """
    package = re.sub('(?<=[^<>~])=', '==', package).strip()
    for compare in ('<=', '>=', '=='):
        if compare in package:
            (pkg, version) = package.split(compare)
            if pkg in EXCLUDE:
                return
            if pkg in REMAP_VERSION:
                return ''.join((pkg, compare, REMAP_VERSION[pkg]))
            if <MASK>:
                return ''.join((CONDA_TO_PIP[pkg], compare, version))
    if package in EXCLUDE:
        return
    if package in CONDA_TO_PIP:
        return CONDA_TO_PIP[package]
    return package

def has_file(self, filename: str) -> bool:
    """Checks if a file is present in a :class:`Directory`.

        Args:
            filename (str): Path of file to search for.
        Returns:
            bool: If a :class:`Directory` contains the specified file.
        """
    lineage = filename.split('/', maxsplit=1)
    child = lineage[0]
    grandchildren = lineage[1] if len(lineage) > 1 else None
    if <MASK>:
        if grandchildren is None:
            return True
        else:
            return self.children[child].has_file(grandchildren)
    return False

def as_datetime(self):
    """Retrieve the Field's value as a tuple of date & time components."""
    if <MASK>:
        return None
    (yy, mm, dd, hh, mn, ss, tz) = [c_int() for i in range(7)]
    status = capi.get_field_as_datetime(self._feat.ptr, self._index, byref(yy), byref(mm), byref(dd), byref(hh), byref(mn), byref(ss), byref(tz))
    if status:
        return (yy, mm, dd, hh, mn, ss, tz)
    else:
        raise GDALException('Unable to retrieve date & time information from the field.')

def setup(self, dtype, method, application, ncols, engine):
    if method in method_blocklist.get(dtype, {}):
        raise NotImplementedError
    if ncols != 1 and method in ['value_counts', 'unique']:
        raise NotImplementedError
    if application == 'transformation' and method in ['describe', 'head', 'tail', 'unique', 'value_counts', 'size']:
        raise NotImplementedError
    if engine == 'numba' and method in _numba_unsupported_methods or ncols > 1 or application == 'transformation' or (dtype == 'datetime'):
        raise NotImplementedError
    if method == 'describe':
        ngroups = 20
    elif method == 'skew':
        ngroups = 100
    else:
        ngroups = 1000
    size = ngroups * 2
    rng = np.arange(ngroups).reshape(-1, 1)
    rng = np.broadcast_to(rng, (len(rng), ncols))
    taker = np.random.randint(0, ngroups, size=size)
    values = rng.take(taker, axis=0)
    if dtype == 'int':
        key = np.random.randint(0, size, size=size)
    elif dtype in ('int16', 'uint'):
        key = np.random.randint(0, size, size=size, dtype=dtype)
    elif dtype == 'float':
        key = np.concatenate([np.random.random(ngroups) * 0.1, np.random.random(ngroups) * 10.0])
    elif dtype == 'object':
        key = ['foo'] * size
    elif dtype == 'datetime':
        key = date_range('1/1/2011', periods=size, freq='s')
    cols = [f'values{n}' for n in range(ncols)]
    df = DataFrame(values, columns=cols)
    df['key'] = key
    if <MASK>:
        cols = cols[0]
    kwargs = {}
    if engine == 'numba':
        kwargs['engine'] = engine
    if application == 'transformation':
        self.as_group_method = lambda : df.groupby('key')[cols].transform(method, **kwargs)
        self.as_field_method = lambda : df.groupby(cols)['key'].transform(method, **kwargs)
    else:
        self.as_group_method = partial(getattr(df.groupby('key')[cols], method), **kwargs)
        self.as_field_method = partial(getattr(df.groupby(cols)['key'], method), **kwargs)

def isna_all(arr: ArrayLike) -> bool:
    """
    Optimized equivalent to isna(arr).all()
    """
    total_len = len(arr)
    chunk_len = max(total_len // 40, 1000)
    dtype = arr.dtype
    if lib.is_np_dtype(dtype, 'f'):
        checker = np.isnan
    elif <MASK>:
        checker = lambda x: np.asarray(x.view('i8')) == iNaT
    else:
        checker = _isna_array
    return all((checker(arr[i:i + chunk_len]).all() for i in range(0, total_len, chunk_len)))

def assertSameShape(self, x, y):
    """Checks that x and y have the same shape (including ragged shapes)."""
    if <MASK>:
        self.assertTrue(ragged_tensor.is_ragged(y))
        self.assertEqual(x.ragged_rank, y.ragged_rank)
        for (x_splits, y_splits) in zip(x.nested_row_splits, y.nested_row_splits):
            self.assertAllEqual(x_splits, y_splits)
        self.assertAllEqual(array_ops.shape(x.flat_values), array_ops.shape(y.flat_values))
    else:
        self.assertIsInstance(y, tensor.Tensor)
        self.assertAllEqual(array_ops.shape(x), array_ops.shape(y))

@lru_cache(100)
def _is_lazy_cls(cls: type) -> bool | None:
    if _issubclass_fast(cls, 'numpy', 'ndarray') or _issubclass_fast(cls, 'numpy', 'generic') or _issubclass_fast(cls, 'cupy', 'ndarray') or _issubclass_fast(cls, 'torch', 'Tensor') or _issubclass_fast(cls, 'sparse', 'SparseArray'):
        return False
    if <MASK>:
        return True
    return None

def _process_dynamic_shapes(combined_args: dict[str, Any], dynamic_shapes: Union[dict[str, Any], tuple[Any], list[Any], None]) -> list[Constraint]:
    """
    Reads the dynamic_shapes specification and produces a list of constraints.
    """
    from torch._dynamo.exc import UserError, UserErrorType
    if dynamic_shapes is None or len(dynamic_shapes) == 0:
        return []
    if <MASK>:
        combined_args = type(dynamic_shapes)(combined_args.values())
    symbols: dict[str, list[Constraint]] = defaultdict(list)
    phantom_roots: dict[str, _PhantomRoot] = {}
    derived_constraints_with_phantom_root: list[_DerivedConstraint] = []
    constraints: list[Constraint] = []

    def to_constraint(dim, tensor, i):
        import sympy
        from torch.fx.experimental.symbolic_shapes import StrictMinMaxConstraint
        from torch.utils._sympy.solve import try_solve
        from torch.utils._sympy.value_ranges import ValueRanges

        def root_value():
            symbol = sympy.Symbol(dim.root.__name__, integer=True)
            expr = dim.fn(symbol)
            solution = try_solve(sympy.Eq(expr, tensor.shape[i]), symbol)
            if solution is not None:
                return int(solution[1])
            else:
                raise UserError(UserErrorType.CONSTRAINT_VIOLATION, f'Expected shape[{i}] = {tensor.shape[i]} of input Tensor to be of the form {expr}, where {symbol} is an integer')
        if isinstance(dim, _DerivedDim):
            dim_root = dim.root
            if dim_root.__name__ in symbols:
                root_constraint = symbols[dim_root.__name__][0]
                root = _ConstraintTarget(root_constraint.t_id, root_constraint.dim)
            elif dim_root.__name__ not in phantom_roots:
                root = _PhantomRoot(name=dim_root.__name__, constraint_range=StrictMinMaxConstraint(vr=ValueRanges(lower=dim_root.min, upper=dim_root.max), warn_only=False), val=root_value())
                phantom_roots[dim_root.__name__] = root
            else:
                root = phantom_roots[dim_root.__name__]
            constraint = _DerivedConstraint(id(tensor), i, dim.__name__, StrictMinMaxConstraint(vr=ValueRanges(lower=dim.min, upper=dim.max), warn_only=False), root, dim.fn)
            if isinstance(root, _PhantomRoot):
                derived_constraints_with_phantom_root.append(constraint)
        elif isinstance(dim, _StaticDim):
            constraint = _Constraint(id(tensor), i, dim.__name__, StrictMinMaxConstraint(vr=ValueRanges(lower=dim.value, upper=dim.value), warn_only=False))
        else:
            assert isinstance(dim, Dim)
            constraint = _Constraint(id(tensor), i, dim.__name__, StrictMinMaxConstraint(vr=ValueRanges(lower=dim.min, upper=dim.max), warn_only=False))
        return constraint

    def _parse_tensor_dim(tensor, idx, dim) -> None:

        def _create_static_dim(tensor, i, value):
            return _StaticDim(value)
        if isinstance(dim, (int, Dim)):
            if isinstance(dim, int):
                dim = _create_static_dim(tensor, idx, dim)
            constraint = to_constraint(dim, tensor, idx)
            symbols[dim.__name__].append(constraint)
        elif isinstance(dim, _DimHint):
            if dim.type == _DimHintType.AUTO:
                torch._dynamo.maybe_mark_dynamic(tensor, idx)
            elif dim.type == _DimHintType.STATIC:
                torch._dynamo.mark_static(tensor, idx)
            elif dim.type == _DimHintType.DYNAMIC:
                torch._dynamo.mark_dynamic(tensor, idx)
            constraints.append(_RelaxedConstraint(id(tensor), idx))
        elif dim is None:
            torch._dynamo.mark_static(tensor, idx)

    def update_symbols(path, tensor, shape):
        tensor._dynamo_weak_dynamic_indices = set()
        tensor._dynamo_dynamic_indices = set()
        tensor._dynamo_dynamic_range = set()
        tensor._dynamo_static_indices = set()
        tensor._dynamo_unbacked_indices = set()
        if isinstance(shape, dict):
            for (i, dim) in shape.items():
                _parse_tensor_dim(tensor, i, dim)
        elif isinstance(shape, (tuple, list)):
            for (i, dim) in enumerate(shape):
                _parse_tensor_dim(tensor, i, dim)
        elif shape is None:
            for i in range(tensor.dim()):
                _parse_tensor_dim(tensor, i, None)

    def assoc_shape(path, t, dynamic_shape):
        if isinstance(t, torch.Tensor):
            update_symbols(path, t, dynamic_shape)
        elif isinstance(t, _IntWrapper):
            t.dynamism = dynamic_shape
    _tree_map_with_path(assoc_shape, combined_args, dynamic_shapes, tree_name='inputs')
    for derived_constraint_with_phantom_root in derived_constraints_with_phantom_root:
        phantom_root_name = derived_constraint_with_phantom_root.root.name
        if phantom_root_name in symbols:
            derived_constraint_with_phantom_root.root = symbols[phantom_root_name][0]
    for dynamic_dims in symbols.values():
        constraints.extend(dynamic_dims)
    return constraints

@staticmethod
def _generate_value_for_type(random_sample: bool, field_name: str, type_hint: type[Any], default: Any) -> Any:
    """
        Generates a value of a type based on the setting.
        """
    if field_name in TYPE_OVERRIDES:
        return random.choice(TYPE_OVERRIDES[field_name])
    if type_hint is bool:
        return random.choice([True, False]) if random_sample else not default
    elif type_hint is int:
        return random.randint(0, 1000)
    elif type_hint is float:
        return random.uniform(0, 1000)
    elif type_hint is str:
        characters = string.ascii_letters + string.digits + string.punctuation
        return ''.join((random.choice(characters) for _ in range(random.randint(1, 20))))
    elif is_type(type_hint, list):
        elem_type = getattr(type_hint, '__args__', [type(default[0])] if default and len(default) else [type(None)])[0]
        new_default = default[0] if default and len(default) > 0 else None
        return [SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, new_default) for _ in range(random.randint(1, 3))]
    elif is_type(type_hint, set):
        indexable = list(default)
        elem_type = getattr(type_hint, '__args__', [type(indexable[0])] if default and len(default) else [type(None)])[0]
        new_default = indexable[0] if default and len(default) > 0 else None
        return {SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, new_default) for _ in range(random.randint(1, 3))}
    elif is_type(type_hint, OrderedSet):
        indexable = list(default)
        elem_type = getattr(type_hint, '__args__', [type(indexable[0])] if default and len(default) else [type(None)])[0]
        new_default = indexable[0] if default and len(default) > 0 else None
        return OrderedSet([SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, new_default) for _ in range(random.randint(1, 3))])
    elif is_type(type_hint, dict):
        (key_type, value_type) = getattr(type_hint, '__args__', map(type, next(iter(default.items()))) if default is not None and len(default) else (type(None), type(None)))
        if default is not None and len(default.items()) > 0:
            (default_key, default_val) = next(iter(default.items()))
        else:
            (default_key, default_val) = (None, None)
        return {SamplingMethod._generate_value_for_type(random_sample, field_name, key_type, default_key): SamplingMethod._generate_value_for_type(random_sample, field_name, value_type, default_val) for _ in range(random.randint(0, 3))}
    elif is_type(type_hint, Union):
        try:
            assert len(type_hint.__args__) > 1
        except AttributeError as err:
            raise ValueError('Union type with no args') from err
        if random_sample:
            new_type = random.choice(type_hint.__args__)
        else:
            new_type = random.choice([t for t in type_hint.__args__ if t is not type(default)])
        try:
            new_default = new_type()
        except Exception:
            new_default = None
        return SamplingMethod._generate_value_for_type(random_sample, field_name, new_type, new_default)
    elif is_type(type_hint, tuple):
        args = getattr(type_hint, '__args__', tuple(map(type, default)))
        zipped = zip(args, default)
        return tuple(map(lambda x: SamplingMethod._generate_value_for_type(random_sample, field_name, x[0], x[1]), zipped))
    elif is_type(type_hint, Literal):
        try:
            if random_sample:
                return random.choice(type_hint.__args__)
            else:
                choices = [t for t in type_hint.__args__ if t != default]
                if choices:
                    return random.choice(choices)
                else:
                    return default
        except AttributeError as err:
            raise ValueError('Literal type with no args') from err
    elif <MASK>:
        try:
            elem_type = type_hint.__args__[0]
        except AttributeError as err:
            raise ValueError('Optional type with no args') from err
        if random_sample:
            return random.choice([None, SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, default)])
        elif default is None:
            return SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, None)
        else:
            return None
    elif type_hint is type(None):
        return None
    elif is_callable_type(type_hint):
        try:
            return_type = list(type_hint.__args__)[-1]
        except AttributeError as err:
            raise ValueError('Callable type with no args') from err

        @wraps(lambda *args, **kwargs: None)
        def dummy_function(*args, **kwargs):
            return SamplingMethod._generate_value_for_type(random_sample, field_name, return_type, None)
        return dummy_function
    elif type_hint == torch._ops.OpOverload:
        return torch.ops.aten.add.default
    elif TypeExemplars.contains(type_hint):
        return TypeExemplars.example(type_hint)
    elif type_hint == Any:
        return 1 if default != 1 else 2
    else:
        raise ValueError(f'Unable to process type {type_hint}. PRs welcome :)')

def _parse_args(self, *args, **kwargs):
    """Parses arguments according to the same rules as the `range()` builtin."""
    if len(args) == 1:
        self._start = self._build_tensor(0, 'start')
        self._stop = self._build_tensor(args[0], 'stop')
        self._step = self._build_tensor(1, 'step')
    elif len(args) == 2:
        self._start = self._build_tensor(args[0], 'start')
        self._stop = self._build_tensor(args[1], 'stop')
        self._step = self._build_tensor(1, 'step')
    elif len(args) == 3:
        self._start = self._build_tensor(args[0], 'start')
        self._stop = self._build_tensor(args[1], 'stop')
        self._step = self._build_tensor(args[2], 'step')
    else:
        raise ValueError(f'Invalid `args`. The length of `args` should be between 1 and 3 but was {len(args)}.')
    if <MASK>:
        self._output_type = kwargs['output_type']
    else:
        self._output_type = dtypes.int64
    self._name = kwargs['name'] if 'name' in kwargs else None

def _multi_tensor_adadelta(params: list[Tensor], grads: list[Tensor], square_avgs: list[Tensor], acc_deltas: list[Tensor], state_steps: list[Tensor], *, lr: float, rho: float, eps: float, weight_decay: float, maximize: bool, differentiable: bool, capturable: bool, has_complex: bool):
    if differentiable:
        raise AssertionError("_foreach ops don't support autograd")
    if not torch.compiler.is_compiling() and capturable:
        capturable_supported_devices = _get_capturable_supported_devices(supports_xla=False)
        if not all((p.device.type == step.device.type and p.device.type in capturable_supported_devices for (p, step) in zip(params, state_steps))):
            raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
    if len(params) == 0:
        return
    lr = _to_scalar(lr)
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, square_avgs, acc_deltas, state_steps])
    for ((device_params_, device_grads_, device_square_avgs_, device_acc_deltas_, device_state_steps_), _) in grouped_tensors.values():
        device_params = cast(list[Tensor], device_params_)
        device_grads = cast(list[Tensor], device_grads_)
        device_square_avgs = cast(list[Tensor], device_square_avgs_)
        device_acc_deltas = cast(list[Tensor], device_acc_deltas_)
        device_state_steps = cast(list[Tensor], device_state_steps_)
        if has_complex:
            _view_as_real(device_params, device_grads, device_square_avgs, device_acc_deltas)
        if not torch.compiler.is_compiling() and device_state_steps[0].is_cpu:
            torch._foreach_add_(device_state_steps, torch.tensor(1.0, device='cpu'), alpha=1.0)
        else:
            torch._foreach_add_(device_state_steps, 1)
        if <MASK>:
            device_grads = torch._foreach_neg(device_grads)
        if weight_decay != 0:
            if maximize:
                torch._foreach_add_(device_grads, device_params, alpha=weight_decay)
            else:
                device_grads = torch._foreach_add(device_grads, device_params, alpha=weight_decay)
        torch._foreach_mul_(device_square_avgs, rho)
        torch._foreach_addcmul_(device_square_avgs, device_grads, device_grads, value=1 - rho)
        std = torch._foreach_add(device_square_avgs, eps)
        torch._foreach_sqrt_(std)
        deltas = torch._foreach_add(device_acc_deltas, eps)
        torch._foreach_sqrt_(deltas)
        torch._foreach_div_(deltas, std)
        torch._foreach_mul_(deltas, device_grads)
        torch._foreach_mul_(device_acc_deltas, rho)
        torch._foreach_addcmul_(device_acc_deltas, deltas, deltas, value=1 - rho)
        if capturable and isinstance(lr, torch.Tensor):
            torch._foreach_mul_(deltas, -lr)
            torch._foreach_add_(device_params, deltas)
        else:
            torch._foreach_add_(device_params, deltas, alpha=-lr)

@RegisterPFor('TensorArrayWriteV3')
def _convert_tensor_array_write_v3(pfor_input: _PforInput):
    handle = pfor_input.unstacked_input(0)
    (index, index_stacked, _) = pfor_input.input(1)
    (value, value_stacked, _) = pfor_input.input(2)
    (flow, flow_stacked, _) = pfor_input.input(3)
    if value_stacked and pfor_input.pfor.all_indices_partitioned:
        raise ValueError('Writing non loop invariant values to TensorArray from inside a while_loop/cond not supported.')
    if flow_stacked:
        flow = _unstack_flow(flow)
    is_inside = _handle_inside_pfor(pfor_input, pfor_input.op.inputs[0])
    if is_inside:
        if index_stacked:
            raise ValueError(f'Need indices for {handle} to be loop invariant.')
        if <MASK>:
            flow_out = data_flow_ops.tensor_array_write_v3(handle, index, value, flow)
            return wrap(flow_out, False)
        else:
            if not value_stacked:
                value = _stack(value, pfor_input.pfor.loop_len_vector).t
            flow_out = data_flow_ops.tensor_array_write_v3(handle, index, value, flow)
            return _stack(flow_out, pfor_input.pfor.loop_len_vector)
    else:
        if not index_stacked:
            raise ValueError(f'Need indices for {handle} to be not loop invariant.')
        if not value_stacked:
            value = _stack(value, pfor_input.pfor.loop_len_vector).t
        flow_out = data_flow_ops.tensor_array_scatter_v3(handle, index, value, flow)
        return _stack(flow_out, pfor_input.pfor.loop_len_vector)

def should_unwrap_unspec_arg(name: str):
    if V.graph.is_unspec_arg(name):
        if <MASK>:
            return True
        if name not in V.graph.mutated_buffers:
            return True
    return False

def benchmark(self, *args, out):
    if out.numel() == 0:
        return 0.0
    if self.has_out_variant:
        return super().benchmark(*args, out=out)
    else:
        algo = self.to_callable()
        out_new = algo(*args)
        torch._C._dynamo.guards.assert_size_stride(out_new, tuple(out.size()), tuple(out.stride()))
        out.copy_(out_new)
        if <MASK>:
            return do_bench_using_profiling(lambda : algo(*args))
        return benchmarker.benchmark(algo, args, {})

def _suggest_fixes_for_data_dependent_error_non_strict(e: GuardOnDataDependentSymNode) -> None:
    """
    Given a raised data-dependent error, add the following to the error message:
    1. the closest user code location that raised the error;
    2. suggested fixes for the error in terms of live variables at that location.
    """
    frame = _find_user_code_frame()
    if frame is not None:
        _blame_user_code(e, frame)
        src_map = defaultdict(list)
        for (var, val) in frame.f_locals.items():
            try:
                tree_leaves_with_path = pytree.tree_leaves_with_path(val)
            except ValueError:
                log.warning('pytree.tree_leaves_with_path failed for value of type {%s} in local variable {%s}', type(val), var)
                continue
            for (path, leaf) in tree_leaves_with_path:
                name = var + pytree.keystr(path)
                if isinstance(leaf, torch.SymInt):
                    src_map[str(leaf.node.expr)].append(name)
                elif <MASK>:
                    for (i, dim) in enumerate(leaf.shape):
                        if isinstance(dim, torch.SymInt):
                            src_map[str(dim.node.expr)].append(f'{name}.shape[{i}]')
        if isinstance(e.cond, sympy.logic.boolalg.Boolean):
            _suggest_torch_checks(e, src_map)

def vdot(a: ArrayLike, b: ArrayLike, /):
    (t_a, t_b) = torch.atleast_1d(a, b)
    if t_a.ndim > 1:
        t_a = t_a.flatten()
    if t_b.ndim > 1:
        t_b = t_b.flatten()
    dtype = _dtypes_impl.result_type_impl(t_a, t_b)
    is_half = dtype == torch.float16 and (t_a.is_cpu or t_b.is_cpu)
    is_bool = dtype == torch.bool
    if <MASK>:
        dtype = torch.float32
    elif is_bool:
        dtype = torch.uint8
    t_a = _util.cast_if_needed(t_a, dtype)
    t_b = _util.cast_if_needed(t_b, dtype)
    result = torch.vdot(t_a, t_b)
    if is_half:
        result = result.to(torch.float16)
    elif is_bool:
        result = result.to(torch.bool)
    return result

def parallel_walk(node, other):
    """Walks two ASTs in parallel.

  The two trees must have identical structure.

  Args:
    node: Union[ast.AST, Iterable[ast.AST]]
    other: Union[ast.AST, Iterable[ast.AST]]
  Yields:
    Tuple[ast.AST, ast.AST]
  Raises:
    ValueError: if the two trees don't have identical structure.
  """
    if isinstance(node, (list, tuple)):
        node_stack = list(node)
    else:
        node_stack = [node]
    if isinstance(other, (list, tuple)):
        other_stack = list(other)
    else:
        other_stack = [other]
    while node_stack and other_stack:
        assert len(node_stack) == len(other_stack)
        n = node_stack.pop()
        o = other_stack.pop()
        if not isinstance(n, (ast.AST, gast.AST, str)) and n is not None or (not isinstance(o, (ast.AST, gast.AST, str)) and n is not None) or n.__class__.__name__ != o.__class__.__name__:
            raise ValueError('inconsistent nodes: {} ({}) and {} ({})'.format(n, n.__class__.__name__, o, o.__class__.__name__))
        yield (n, o)
        if isinstance(n, str):
            assert isinstance(o, str), 'The check above should have ensured this'
            continue
        if n is None:
            assert o is None, 'The check above should have ensured this'
            continue
        for f in n._fields:
            n_child = getattr(n, f, None)
            o_child = getattr(o, f, None)
            if f.startswith('__') or n_child is None or o_child is None:
                continue
            if <MASK>:
                if not isinstance(o_child, (list, tuple)) or len(n_child) != len(o_child):
                    raise ValueError('inconsistent values for field {}: {} and {}'.format(f, n_child, o_child))
                node_stack.extend(n_child)
                other_stack.extend(o_child)
            elif isinstance(n_child, (gast.AST, ast.AST)):
                node_stack.append(n_child)
                other_stack.append(o_child)
            elif n_child != o_child:
                raise ValueError('inconsistent values for field {}: {} and {}'.format(f, n_child, o_child))

def count(fn: Callable[_P, _R]) -> Callable[_P, _R]:

    @functools.wraps(fn)
    def wrapper(*args: _P.args, **kwargs: _P.kwargs) -> _R:
        if <MASK>:
            simple_call_counter[fn.__qualname__] = 0
        simple_call_counter[fn.__qualname__] = simple_call_counter[fn.__qualname__] + 1
        return fn(*args, **kwargs)
    return wrapper

def _process_equalities(constraint: Constraint, get_sources: Callable[[int, int], list['Source']], shape_env: 'ShapeEnv', names: dict[str, tuple[int, int]], source_pairs: list[tuple['Source', 'Source']], derived_equalities: list[tuple['Source', Union['Source', 'Symbol'], Callable]], phantom_symbols: dict[str, 'Symbol'], relaxed_sources: set['Source']):
    """
    Updates `source_pairs`, `derived_equalities`, and `phantom_symbols` (which become
    fields of `EqualityConstraint`) based on a given input `constraint`.
    """
    sources = get_sources(constraint.t_id, constraint.dim)
    if not sources:
        return
    (source, *other_sources) = sources
    source_pairs.extend(((source, other_source) for other_source in other_sources))
    if isinstance(constraint, _Constraint):
        if constraint.name in names:
            (shared_t_id, shared_dim) = names[constraint.name]
            other_sources = get_sources(shared_t_id, shared_dim)
            source_pairs.extend(((source, other_source) for other_source in other_sources))
        else:
            names[constraint.name] = (constraint.t_id, constraint.dim)
    elif isinstance(constraint, _DerivedConstraint):
        if <MASK>:
            root = get_sources(constraint.root.t_id, constraint.root.dim)[0]
        elif constraint.root.name in phantom_symbols:
            root = phantom_symbols[constraint.root.name]
        else:
            root = shape_env.create_symbol(val=constraint.root.val, source=torch._dynamo.source.ConstantSource(constraint.root.name), dynamic_dim=torch.fx.experimental.symbolic_shapes.DimDynamic.DYNAMIC, constraint_dim=constraint.root.constraint_range)
            phantom_symbols[constraint.root.name] = root
        fn = constraint.fn
        derived_equalities.append((source, root, fn))
    elif isinstance(constraint, _RelaxedConstraint):
        relaxed_sources.add(source)

def dynamic_getattr(self, tx: 'InstructionTranslator', name):
    fake_val = self.proxy.node.meta['example_value']
    if not self.source and is_traceable_wrapper_subclass(fake_val):
        (attrs, _ctx) = fake_val.__tensor_flatten__()
        proxy = getattr(self.as_proxy(), name)
        example_value = getattr(fake_val, name)
        if name in attrs:
            assert isinstance(example_value, torch.Tensor)
            from .builder import wrap_fx_proxy
            return wrap_fx_proxy(tx=tx, proxy=proxy, example_value=example_value)
        elif not callable(example_value):
            return VariableTracker.build(tx, example_value)
    if not (self.source and self.source.subguards_allowed()):
        raise NotImplementedError
    scope = {'L': tx.output.local_scope, 'G': tx.output.global_scope}
    try:
        _input_associated_real_value = eval(self.source.name(), scope)
    except Exception as exc:
        raise NotImplementedError from exc
    if <MASK>:
        raise NotImplementedError
    if object_has_getattribute(_input_associated_real_value):
        raise NotImplementedError
    if get_custom_getattr(_input_associated_real_value):
        raise NotImplementedError
    real_value = getattr(_input_associated_real_value, name)
    attr_source = AttrSource(self.source, name)
    if is_bound_tensor_method(real_value):
        from .misc import GetAttrVariable
        return GetAttrVariable(self, name, source=attr_source, py_type=type(real_value))
    install_guard(attr_source.make_guard(GuardBuilder.HASATTR))
    return VariableTracker.build(tx, real_value, attr_source)

@dispatch.dispatch_for_types(array_ops.size_v2, StructuredTensor)
def size_v2(input, out_type=None, name=None):
