        if <MASK>:
            out_type = dtypes.int64
        else:
            out_type = dtypes.int32
    return size(input, name=name, out_type=out_type)

def _enter_autocast(*vals):
    if <MASK>:
        return torch.overrides.handle_torch_function(torch.amp._enter_autocast, [], *vals)
    mode = torch.amp.autocast(*vals)
    mode.__enter__()
    return mode

def _get_num_systems(self, operator):
    """Get some number, either 1 or 2, depending on operator."""
    if <MASK>:
        return 1
    else:
        return 2

def incremental_update(self):
    """Update FakeTensors on self.graph. We will try to do the minimum amount of work."""
    existing_storages: defaultdict[Optional[int], int] = defaultdict(int)
    for node in self.graph.nodes:
        existing_storages[get_node_storage(node)] += 1

    def is_intlist_same(new, old):
        return statically_known_true(sym_eq(new, old))

    def is_fake_tensor_same(new, old, *, node):
        if type(new) is not type(old):
            return False
        if isinstance(new, (list, tuple)):
            if len(new) != len(old):
                return False
            return all((is_fake_tensor_same(new_i, old_i, node=node) for (new_i, old_i) in zip(new, old)))
        if new is None:
            return old is None
        if not isinstance(new, torch.Tensor):
            assert isinstance(new, (torch.SymInt, torch.SymBool, torch.SymFloat)), f'Unknown type {type(new)} in {self.graph}'
            return new.node.shape_env._maybe_evaluate_static(sympy.Eq(new.node.expr, old.node.expr)) == sympy.true
        if not is_intlist_same(new.shape, old.shape) or new.layout != old.layout:
            return False
        if new.layout == torch.strided and (not is_intlist_same(new.stride(), old.stride()) or not statically_known_true(new.storage_offset() == old.storage_offset())):
            return False
        if new.device != old.device:
            return False
        if get_storage(new) == get_storage(old):
            return True

        def any_user_may_alias(node):
            if not isinstance(node.meta['val'], torch.Tensor):
                return True
            for user in node.users:
                if not (isinstance(user.target, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)) or user.target == torch._inductor.fx_passes.reinplace._generalized_scatter):
                    return True
                if <MASK>:
                    continue
                (is_valid, args, kwargs) = get_fake_args_kwargs(user)
                if not is_valid:
                    return True
                with V.fake_mode, enable_python_dispatcher(), contextlib.ExitStack() as stack:
                    shape_env = V.fake_mode.shape_env
                    if shape_env is not None:
                        stack.enter_context(shape_env.ignore_fresh_unbacked_symbols())
                    new_fake_tensor = user.target(*args, **kwargs)
                if not isinstance(new_fake_tensor, torch.Tensor):
                    return True
                if get_storage(new_fake_tensor) == get_storage(node.meta['val']):
                    return True
            return False
        if existing_storages[get_storage(old)] == 1 and get_storage(new) not in existing_storages and (not any_user_may_alias(node)):
            return True
        return False

    def should_process_node(node):
        return node.op == 'call_function' and (isinstance(node.target, torch._ops.OpOverload) or node.target == operator.getitem or node.target == torch._inductor.fx_passes.reinplace._generalized_scatter)
    to_process = OrderedSet[int]()
    for node in self.graph.nodes:
        if self.hash_node(node) in self.processed_hashes and id(node) not in to_process:
            continue
        if not should_process_node(node):
            continue
        (is_valid, args, kwargs) = get_fake_args_kwargs(node)
        if not is_valid:
            continue
        with V.fake_mode, enable_python_dispatcher():
            new_fake_tensor = node.target(*args, **kwargs)
        if 'val' in node.meta and is_fake_tensor_same(new_fake_tensor, node.meta['val'], node=node):
            continue
        rebind_unbacked(V.fake_mode.shape_env, node, new_fake_tensor)
        node.meta['val'] = new_fake_tensor
        if (shape_env := V.fake_mode.shape_env) and (symbol_to_path := compute_unbacked_bindings(shape_env, new_fake_tensor)):
            node.meta['unbacked_bindings'] = symbol_to_path
        existing_storages[get_node_storage(node)] += 1
        to_process.update([id(user) for user in node.users])
        self.processed_hashes.add(self.hash_node(node))

def _libs_with_msvc_and_fortran(self, fcompiler, c_libraries, c_library_dirs):
    if fcompiler is None:
        return
    for libname in c_libraries:
        if libname.startswith('msvc'):
            continue
        fileexists = False
        for libdir in c_library_dirs or []:
            libfile = os.path.join(libdir, '%s.lib' % libname)
            if <MASK>:
                fileexists = True
                break
        if fileexists:
            continue
        fileexists = False
        for libdir in c_library_dirs:
            libfile = os.path.join(libdir, 'lib%s.a' % libname)
            if os.path.isfile(libfile):
                libfile2 = os.path.join(self.build_temp, libname + '.lib')
                copy_file(libfile, libfile2)
                if self.build_temp not in c_library_dirs:
                    c_library_dirs.append(self.build_temp)
                fileexists = True
                break
        if fileexists:
            continue
        log.warn('could not find library %r in directories %s' % (libname, c_library_dirs))
    f_lib_dirs = []
    for dir in fcompiler.library_dirs:
        if dir.startswith('/usr/lib'):
            try:
                dir = subprocess.check_output(['cygpath', '-w', dir])
            except (OSError, subprocess.CalledProcessError):
                pass
            else:
                dir = filepath_from_subprocess_output(dir)
        f_lib_dirs.append(dir)
    c_library_dirs.extend(f_lib_dirs)
    for lib in fcompiler.libraries:
        if not lib.startswith('msvc'):
            c_libraries.append(lib)
            p = combine_paths(f_lib_dirs, 'lib' + lib + '.a')
            if p:
                dst_name = os.path.join(self.build_temp, lib + '.lib')
                if not os.path.isfile(dst_name):
                    copy_file(p[0], dst_name)
                if self.build_temp not in c_library_dirs:
                    c_library_dirs.append(self.build_temp)

@_apply_docstring_templates
def cumsum(input: Tensor, dim: int, *, dtype: Optional[DType]=None, mask: Optional[Tensor]=None) -> Tensor:
    if <MASK>:
        dtype = input.dtype
    dim_ = _canonical_dim(dim, input.ndim)[0]
    mask_input = _combine_input_and_mask(sum, input, mask)
    if mask_input.layout == torch.strided:
        return torch.cumsum(mask_input, dim_, dtype=dtype).to(dtype=dtype)
    else:
        raise ValueError(f'masked cumsum expects strided tensor (got {mask_input.layout} tensor)')

def _process_body(self, inputs_stacked, new_indices, cond_stacked, new_inputs, not_all_done):
    """Convert the body function."""
    mismatching_stacked_indices = []

    def true_fn():
        """Converts the body function for all but last iteration."""
        wrapped_inputs = [wrap(inp, stacked) for (inp, stacked) in zip(new_inputs, inputs_stacked)]
        while True:
            if self._pfor.all_indices_partitioned:
                indices = array_ops.gather(self._pfor.all_indices, new_indices)
            else:
                indices = new_indices
            body_pfor = PFor(loop_var=self._pfor.loop_var, loop_len=array_ops.size(new_indices), pfor_ops=self._body_func.graph.get_operations(), fallback_to_while_loop=self._pfor.fallback_to_while_loop, all_indices=indices, all_indices_partitioned=self._pfor.all_indices_partitioned or cond_stacked, pfor_config=self._pfor.pfor_config)
            stacking_mismatch = False
            outputs = _convert_function_call(self._body_func, body_pfor, wrapped_inputs)
            for (i, (out, inp)) in enumerate(zip(outputs, wrapped_inputs)):
                if out.is_stacked != inp.is_stacked:
                    stacking_mismatch = True
                    mismatching_stacked_indices.append(i)
                    stacked = _stack(inp.t, [array_ops.size(new_indices)])
                    if inp.t.dtype == dtypes.variant:
                        stacked = wrap(_tile_variant_with_length(stacked.t, [array_ops.size(new_indices)]))
                    wrapped_inputs[i] = stacked
            if not stacking_mismatch:
                if <MASK>:
                    with ops.control_dependencies([control_flow_assert.Assert(False, ['pfor ERROR: this branch should never execute'])]):
                        return [array_ops.identity(x) for x in new_inputs]
                else:
                    return [out.t for out in outputs]
    return (tf_cond.cond(not_all_done, true_fn, lambda : list(new_inputs)), mismatching_stacked_indices)

def find_reverse_deps(self, tag_id: Optional[int]=None) -> dict[torch.fx.Node, NodeSet]:
    """
        Builds reversed topological node dependencies, if tag_id is specified,
        we ignore nodes that are in later subgraph i.e. nodes have greater tag_id.
        """
    result: dict[torch.fx.Node, NodeSet] = defaultdict(set)
    for node in self.module.graph.nodes:
        if <MASK>:
            continue
        for user in node.users:
            if user.op not in CALLABLE_NODE_OPS:
                continue
            if tag_id is None or int(user.tag.split('_')[-1]) < tag_id:
                result[node].add(user)
    return result

def cracktypespec0(typespec, ll):
    selector = None
    attr = None
    if <MASK>:
        typespec = 'double complex'
    elif re.match('double\\s*precision', typespec, re.I):
        typespec = 'double precision'
    else:
        typespec = typespec.strip().lower()
    m1 = selectpattern.match(markouterparen(ll))
    if not m1:
        outmess('cracktypespec0: no kind/char_selector pattern found for line.\n')
        return
    d = m1.groupdict()
    for k in list(d.keys()):
        d[k] = unmarkouterparen(d[k])
    if typespec in ['complex', 'integer', 'logical', 'real', 'character', 'type']:
        selector = d['this']
        ll = d['after']
    i = ll.find('::')
    if i >= 0:
        attr = ll[:i].strip()
        ll = ll[i + 2:]
    return (typespec, selector, attr, ll)

def _sqlite_time_trunc(lookup_type, dt, tzname, conn_tzname):
    if dt is None:
        return None
    dt_parsed = _sqlite_datetime_parse(dt, tzname, conn_tzname)
    if dt_parsed is None:
        try:
            dt = typecast_time(dt)
        except (ValueError, TypeError):
            return None
    else:
        dt = dt_parsed
    if lookup_type == 'hour':
        return f'{dt.hour:02d}:00:00'
    elif <MASK>:
        return f'{dt.hour:02d}:{dt.minute:02d}:00'
    elif lookup_type == 'second':
        return f'{dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}'
    raise ValueError(f'Unsupported lookup type: {lookup_type!r}')

def _get_getitem_users(node: torch.fx.Node) -> set[torch.fx.Node]:
    node_users = list(node.users.keys())
    getitem_users = set()
    for user in node_users:
        if <MASK>:
            continue
        assert user.op == 'call_function' and user.target == operator.getitem, f'Expected getitem node as user for {node}, instead got {user}'
        getitem_users.update(list(user.users.keys()))
    return getitem_users

def _fit_transform(self, X, y=None, W=None, H=None, update_H=True):
    X = check_array(X, accept_sparse=('csr', 'csc'))
    check_non_negative(X, 'NMF (input X)')
    (n_samples, n_features) = X.shape
    n_components = self.n_components
    if n_components is None:
        n_components = n_features
    if not isinstance(n_components, numbers.Integral) or n_components <= 0:
        raise ValueError('Number of components must be a positive integer; got (n_components=%r)' % n_components)
    if not isinstance(self.max_iter, numbers.Integral) or self.max_iter < 0:
        raise ValueError('Maximum number of iterations must be a positive integer; got (max_iter=%r)' % self.max_iter)
    if <MASK>:
        raise ValueError('Tolerance for stopping criteria must be positive; got (tol=%r)' % self.tol)
    if self.init == 'custom' and update_H:
        _check_init(H, (n_components, n_features), 'NMF (input H)')
        _check_init(W, (n_samples, n_components), 'NMF (input W)')
    elif not update_H:
        _check_init(H, (n_components, n_features), 'NMF (input H)')
        W = np.zeros((n_samples, n_components))
    else:
        (W, H) = _initialize_nmf(X, n_components, init=self.init, random_state=self.random_state)
    if update_H:
        (W, H, n_iter) = _fit_projected_gradient(X, W, H, self.tol, self.max_iter, self.nls_max_iter, self.alpha, self.l1_ratio)
    else:
        (Wt, _, n_iter) = _nls_subproblem(X.T, H.T, W.T, self.tol, self.nls_max_iter, alpha=self.alpha, l1_ratio=self.l1_ratio)
        W = Wt.T
    if n_iter == self.max_iter and self.tol > 0:
        warnings.warn('Maximum number of iteration %d reached. Increase it to improve convergence.' % self.max_iter, ConvergenceWarning)
    return (W, H, n_iter)

def _acc_helper_init(self, reduction_type, helper_val, helper_range, dtype, num_threads=None, use_scalar=False):
    num_range_thread = CeilDiv(helper_range, num_threads) if num_threads else helper_range
    num_range_thread_expr = cexpr_index(num_range_thread)
    assert reduction_type in ['welford_reduce', 'sum']
    chunk_size = 4096 if reduction_type == 'welford_reduce' else 2 ** 20
    num_chunks = CeilDiv(num_range_thread, chunk_size)
    helper_type = 'WelfordHelper' if reduction_type == 'welford_reduce' else 'CascadeSumHelper'
    if <MASK>:
        h_type = DTYPE_TO_CPP[dtype]
    else:
        h_type = self._get_vec_type(dtype) if hasattr(self, '_get_vec_type') else DTYPE_TO_CPP[dtype]
    helper_init_line = f'{helper_type}<{h_type}, {chunk_size}> {helper_val}({num_range_thread_expr});'
    if reduction_type == 'sum':
        return helper_init_line
    if isinstance(num_chunks, sympy.Integer) and num_chunks <= 1:
        return f'static {helper_init_line}'
    else:
        return helper_init_line

@break_graph_if_unsupported(push=1)
def CALL_FUNCTION_EX(self, inst: Instruction) -> None:
    kwargsvars: VariableTracker
    if inst.argval == 0:
        kwargsvars = ConstDictVariable({})
        argsvars = self.pop()
    elif inst.argval == 1 or sys.version_info >= (3, 14):
        kwargsvars = self.pop()
        if isinstance(kwargsvars, NullVariable):
