def generate_return(self, output_refs: list[str]):
    cst_names = V.graph.constants.keys()
    arr_iface = not V.graph.is_const_graph and config.aot_inductor.use_minimal_arrayref_interface

    def use_thread_local_cached_output_tensor(idx, output):
        cached_output_name = f'cached_output_{next(self.cached_output_id)}'
        cache_type = 'Array' if arr_iface else 'Tensor'
        self.wrapper_call.writeline(f'thread_local ThreadLocalCachedOutput{cache_type}<std::decay_t<decltype({output})>> {cached_output_name}({output});')
        if arr_iface:
            self.wrapper_call.writeline(f'{cached_output_name}.copy_data_from({output});')
            output_entry = f'std::get<{idx}>(output_arrayref_tensors)'
            element_type = f'std::decay_t<decltype({output_entry}.data()[0])>'
            self.wrapper_call.writeline(f'{output_entry} = {cached_output_name}.arrayref_tensor<{element_type}>();')
        else:
            self.wrapper_call.writeline(f'{cached_output_name}.copy_data_from({output});')
            self.wrapper_call.writeline(f'AOTI_TORCH_ERROR_CODE_CHECK(aoti_torch_new_uninitialized_tensor(&output_handles[{idx}]));')
            self.wrapper_call.writeline(f'AOTI_TORCH_ERROR_CODE_CHECK(aoti_torch_assign_tensors({cached_output_name}.tensor(), output_handles[{idx}]));')
    if arr_iface:
        self.wrapper_call.writeline('AOTInductorModelOutputs output_arrayref_tensors;')
    output2idx: dict[str, int] = {}
    for (idx, output) in enumerate(output_refs):
        if output == 'nullptr':
            continue
        is_constant_buffer = output in cst_names
        output_buffer = V.graph.graph_outputs[idx]
        if isinstance(output_buffer, ir.BaseView):
            output_storage = output_buffer.unwrap_view()
            assert isinstance(output_storage, (ir.BaseView, ir.MutableBox))
            if isinstance(output_storage.data, ir.ConstantBuffer):
                is_constant_buffer = True
        if isinstance(output_buffer, ir.ShapeAsConstantBuffer):
            output_tensor = self.codegen_scalar_to_tensor(output)
            self.wrapper_call.writeline(f'output_handles[{idx}] = {output_tensor}.release();')
            continue
        output_is_tensor_handle_expr = f'std::is_same_v<std::decay_t<decltype({output})>,RAIIAtenTensorHandle> || std::is_same_v<std::decay_t<decltype({output})>,AtenTensorHandle> || std::is_same_v<std::decay_t<decltype({output})>,ConstantHandle>'
        self.wrapper_call.writeline(f'if constexpr ({output_is_tensor_handle_expr}) {{')
        with self.wrapper_call.indent():
            if arr_iface:
                cached_output_name = f'cached_output_{next(self.cached_output_id)}'
                self.wrapper_call.writeline(f'thread_local RAIIAtenTensorHandle {cached_output_name};')
                if is_constant_buffer:
                    self.wrapper_call.writeline(f'AtenTensorHandle {cached_output_name}_tmp;')
                    self.wrapper_call.writeline(f'aoti_torch_clone({output}, &{cached_output_name}_tmp);')
                    self.wrapper_call.writeline(f'{cached_output_name} = {cached_output_name}_tmp;')
                else:
                    self.wrapper_call.writeline(f'{cached_output_name} = {output}.release();')
                self.wrapper_call.writeline(f'convert_handle_to_arrayref_tensor({cached_output_name}, std::get<{idx}>(output_arrayref_tensors));')
            elif is_constant_buffer:
                self.wrapper_call.writeline(f'aoti_torch_clone({output}, &output_handles[{idx}]);')
            elif output in output2idx:
                src_idx = output2idx[output]
                self.wrapper_call.writeline(f'output_handles[{idx}] = output_handles[{src_idx}];')
            else:
                self.wrapper_call.writeline(f'output_handles[{idx}] = {output}.release();')
        self.wrapper_call.writeline('} else {')
        with self.wrapper_call.indent():
            use_thread_local_cached_output_tensor(idx, output)
        self.wrapper_call.writeline('}')
        if <MASK>:
            output2idx[output] = idx
    if arr_iface:
        self.wrapper_call.writeline('return output_arrayref_tensors;')

def _find_manylinux_interpreters() -> list[str]:
    """Find Python interpreters in manylinux format (/opt/python/)."""
    supported_versions = get_supported_python_versions()
    interpreters = []
    python_root = Path('/opt/python')
    if <MASK>:
        logger.warning('Path /opt/python does not exist, no interpreters found')
        return []
    python_binaries = list(python_root.glob('*/bin/python3'))
    for python_path in python_binaries:
        try:
            version_output = run_cmd([str(python_path), '--version'], capture_output=True)
            version_string = version_output.stdout.decode('utf-8').strip()
            if 'PyPy' in version_string:
                logger.debug('Skipping PyPy interpreter: %s', python_path)
                continue
            match = re.search('Python (\\d+\\.\\d+)', version_string)
            if not match:
                logger.debug('Could not parse version from: %s', version_string)
                continue
            python_version = match.group(1)
            if python_version in supported_versions:
                interpreters.append(str(python_path))
                logger.debug('Found supported Python %s at %s', python_version, python_path)
            else:
                logger.debug('Python %s not in supported versions: %s', python_version, supported_versions)
        except subprocess.CalledProcessError as e:
            logger.debug('Failed to get version for %s: %s', python_path, e)
            continue
    return interpreters

def decorated(*args):

    @def_function.function(autograph=autograph)
    def computation(*computation_args):
        return fn(*computation_args)
    computation = computation.get_concrete_function(*[tensor.TensorSpec(dtype=x.dtype, shape=x.shape, name='batch_' + str(i)) for (i, x) in enumerate(args)])
    with ops.name_scope('batch') as name:
        for a in args:
            if <MASK>:
                raise ValueError(f'All arguments to functions decorated with `batch_function`  are supposed to be Tensors; found {a!r}.')
        outputs = gen_batch_ops.batch_function(num_batch_threads=num_batch_threads, max_batch_size=max_batch_size, batch_timeout_micros=batch_timeout_micros, allowed_batch_sizes=allowed_batch_sizes, max_enqueued_batches=max_enqueued_batches, shared_name=name, enable_large_batch_splitting=enable_large_batch_splitting, f=computation, in_tensors=list(args), captured_tensors=computation.captured_inputs, Tout=[o.dtype for o in computation.outputs])
        return nest.pack_sequence_as(computation.structured_outputs, outputs, expand_composites=True)

@final
def _maybe_right_yaxis(self, ax: Axes, axes_num: int) -> Axes:
    if not self.on_right(axes_num):
        return self._get_ax_layer(ax)
    if hasattr(ax, 'right_ax'):
        return ax.right_ax
    elif hasattr(ax, 'left_ax'):
        return ax
    else:
        (orig_ax, new_ax) = (ax, ax.twinx())
        new_ax._get_lines = orig_ax._get_lines
        new_ax._get_patches_for_fill = orig_ax._get_patches_for_fill
        (orig_ax.right_ax, new_ax.left_ax) = (new_ax, orig_ax)
        if not self._has_plotted_object(orig_ax):
            orig_ax.get_yaxis().set_visible(False)
        if self.logy is True or self.loglog is True:
            new_ax.set_yscale('log')
        elif <MASK>:
            new_ax.set_yscale('symlog')
        return new_ax

def add(self, guard: Guard, *, collect_debug_stack: bool=True, skip: int=0) -> None:
    if guard in self.inner:
        return
    if <MASK>:
        if guard.stack is None:
            guard.stack = CapturedTraceback.extract(skip=1 + skip)
    if guard.user_stack is None:
        guard.user_stack = TracingContext.extract_stack()
    self.inner.add(guard)

@wraps(func)
def compile_func(parser, token):
    tag_params = params.copy()
    if <MASK>:
        if len(tag_params) >= 2 and tag_params[1] == 'content':
            del tag_params[1]
        else:
            raise TemplateSyntaxError(f"{function_name!r} is decorated with takes_context=True so it must have a first argument of 'context' and a second argument of 'content'")
    elif tag_params and tag_params[0] == 'content':
        del tag_params[0]
    else:
        raise TemplateSyntaxError(f"'{function_name}' must have a first argument of 'content'")
    bits = token.split_contents()[1:]
    target_var = None
    if len(bits) >= 2 and bits[-2] == 'as':
        target_var = bits[-1]
        bits = bits[:-2]
    nodelist = parser.parse((end_name,))
    parser.delete_first_token()
    (args, kwargs) = parse_bits(parser, bits, tag_params, varargs, varkw, defaults, kwonly, kwonly_defaults, takes_context, function_name)
    return SimpleBlockNode(nodelist, func, takes_context, args, kwargs, target_var)

def deserialize_outputs(self, serialized_node: Node, fx_node: torch.fx.Node):
    if len(serialized_node.outputs) == 0:
        return
    if len(serialized_node.outputs) == 1 and 'torch.ops.higher_order' in serialized_node.target and (not getattr(serialized_node, 'is_hop_single_tensor_return', True)) and (serialized_node.outputs[0].type != 'as_none'):

        def _deserialize_hop_with_single_return(serialized_node, fx_node):
            meta_val: list[Any] = []
            arg = None
            if serialized_node.outputs[0].type == 'as_tensor':
                arg = serialized_node.outputs[0].as_tensor
            elif isinstance(serialized_node.outputs[0].value, (SymIntArgument, SymBoolArgument, SymFloatArgument)):
                arg = serialized_node.outputs[0].value
            deserialized_metadata = self.deserialize_metadata(serialized_node.metadata)
            assert arg is not None
            self.generate_getitem(meta_val, fx_node, arg, 0, deserialized_metadata)
            fx_node.meta['val'] = tuple(meta_val)
            self.serialized_name_to_node[fx_node.name] = fx_node
            return
        return _deserialize_hop_with_single_return(serialized_node, fx_node)
    if <MASK>:
        self.sync_fx_node(serialized_node.outputs[0].as_tensor.name, fx_node)
        return
    elif len(serialized_node.outputs) == 1 and isinstance(serialized_node.outputs[0].value, (SymIntArgument, SymBoolArgument, SymFloatArgument)):
        self.sync_fx_node(serialized_node.outputs[0].value.as_name, fx_node)
        return
    elif len(serialized_node.outputs) == 1 and serialized_node.outputs[0].type == 'as_none':
        fx_node.meta['val'] = None
        fx_node._rename(f'{self.graph._target_to_str(fx_node.target)}_unused')
        return
    self.deserialize_multiple_outputs(serialized_node, fx_node)

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    from .builder import SourcelessBuilder, VariableBuilder
    from .torch_function import can_dispatch_torch_function, dispatch_torch_function
    if self.is_strict_mode(tx) and name in self._strict_mode_banned_ops():
        unimplemented_v2(gb_type='Illegal method invocation in strict mode', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'Dynamo currently does not support this method ({name}) invocation in strict mode.', hints=[])
    static_attr = all_tensor_attrs.get(name, None)
    is_base_tensor_method = static_attr is not None
    if can_dispatch_torch_function(tx, tuple([self] + list(args)), kwargs) and is_base_tensor_method:
        if self.source:
            func_var = VariableBuilder(tx, AttrSource(AttrSource(self.source, '__class__'), name))(static_attr)
        else:
            func_var = SourcelessBuilder.create(tx, getattr(torch.Tensor, name))
        return dispatch_torch_function(tx, func_var, tuple([self] + list(args)), kwargs)
    "\n        Dispatch to a method-specific handler defined below.  If the\n        handler returns None (or doesn't exist) we put the method call\n        in the graph.\n        "
    if name == '__eq__' and isinstance(args[0], UserDefinedClassVariable):
        return variables.ConstantVariable(False)
    if name == 'random_':
        unimplemented_v2(gb_type='Tensor.random_ op', context=f'Tensor.{name}(args={args!r}, kwargs={kwargs!r})', explanation='This is currently not supported.', hints=['Use the out-of-place version of this op', *graph_break_hints.SUPPORTABLE])
    elif <MASK>:
        unimplemented_v2(gb_type='Tensor.uniform_ op called with `from` keyword', context=f'Tensor.{name}(args={args!r}, kwargs={kwargs!r})', explanation='This is currently not supported.', hints=['Avoid using the `from` keyword.', *graph_break_hints.SUPPORTABLE])
    try:
        handler_method = getattr(self, f'method_{name}')
    except AttributeError:
        pass
    else:
        try:
            result = handler_method(*args, **kwargs)
            if result:
                return result
        except TypeError as e:
            unimplemented_v2(gb_type='Unhandled args for method', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'Dynamo encountered an error while calling the method `{name}`.', hints=[], from_exc=e)
    from .builder import wrap_fx_proxy
    return wrap_fx_proxy(tx, tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self, *args], kwargs)))

