def _unflatten_optim_state_dict(optim: torch.optim.Optimizer, state_dict: dict[str, ValueType], info: _StateDictInfo) -> OptimizerStateType:
    """
    This API unflattens the state_dict generated by _flatten_optim_state_dict().
    See the docstring of _flatten_optim_state_dict() for more detail.
    """
    state: DictValueType = {}
    pg_state: ListDictValueType = []
    return_osd: OptimizerStateType = {_STATE: state, _PG: pg_state}
    for param_group in optim.param_groups:
        pg_state.append({_PARAMS: []})
        for param in param_group[_PARAMS]:
            for fqn in info.fqn_param_mapping[param]:
                if fqn in info.shared_params_mapping:
                    in_params = False
                    for k in param_group.keys():
                        if k == _PARAMS:
                            continue
                        flatten_key = f'{_PG}.{fqn}.{k}'
                        if <MASK>:
                            in_params = True
                        break
                else:
                    in_params = True
                if not in_params:
                    continue
                params = pg_state[-1][_PARAMS]
                if not isinstance(params, list):
                    raise AssertionError(f'Expected list, got {type(params)}')
                params.append(fqn)
                if not param.requires_grad:
                    continue
                state[fqn] = {}
                for state_name in optim.state[param].keys():
                    cast(DictValueType, state[fqn])[state_name] = state_dict[f'{_STATE}.{fqn}.{state_name}']
        first_param_fqn = cast(list[str], pg_state[-1][_PARAMS])[0]
        for k in param_group.keys():
            if k == _PARAMS:
                continue
            value = state_dict[f'{_PG}.{first_param_fqn}.{k}']
            if k not in pg_state[-1]:
                pg_state[-1][k] = value
            elif pg_state[-1][k] != value:
                raise RuntimeError(f'All the parameters in the same parameter group should have the same saved param_group value. But {first_param_fqn}.{k} is {value} while other(s) is {pg_state[-1][k]}.')
    return return_osd

def num_to_str(self, value: Optional[float], estimated_sigfigs: int, spread: Optional[float]):
    if <MASK>:
        return ' ' * len(self.num_to_str(1, estimated_sigfigs, None))
    if self._trim_significant_figures:
        value = common.trim_sigfig(value, estimated_sigfigs)
    return self._template.format(value, f' (! {spread * 100:.0f}%)' if self._highlight_warnings and spread is not None else '')

def format(self, record):
    artifact_name = getattr(logging.getLogger(record.name), 'artifact_name', None)
    if artifact_name is not None:
        artifact_formatter = log_registry.artifact_log_formatters.get(artifact_name, None)
        if artifact_formatter is not None:
            return artifact_formatter.format(record)
    record.message = record.getMessage()
    record.asctime = self.formatTime(record, '%m%d %H:%M:%S')
    s = record.message
    if record.exc_info:
        if not record.exc_text:
            record.exc_text = self.formatException(record.exc_info)
    if <MASK>:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + record.exc_text
    if record.stack_info:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + self.formatStack(record.stack_info)
    record.rankprefix = ''
    if not self._is_trace and dist.is_available() and dist.is_initialized():
        record.rankprefix = f'[rank{dist.get_rank()}]:'
    record.traceid = ''
    if not self._is_trace and (trace_id := torch._guards.CompileContext.current_trace_id()) is not None:
        record.traceid = f' [{trace_id}]'
    glog_level_to_abbr = {'DEBUG': 'V', 'INFO': 'I', 'WARNING': 'W', 'ERROR': 'E', 'CRITICAL': 'C'}
    shortlevel = glog_level_to_abbr.get(record.levelname, record.levelname)
    record.artifactprefix = ''
    if artifact_name is not None:
        record.artifactprefix = f' [__{artifact_name}]'
    filepath = make_module_path_relative(record.pathname)
    if self._trace_id_filter and record.traceid.strip() not in self._trace_id_filter:
        return ''
    prefix = f'{record.rankprefix}{shortlevel}{record.asctime}.{int(record.msecs * 1000):06d} {record.process} {filepath}:{record.lineno}]{record.traceid}{record.artifactprefix}'
    if self._is_trace:
        assert s == ''
        try:
            r = f'{prefix} {json.dumps(record.metadata)}'
        except TypeError:
            log.warning('failing metadata: %r', record.metadata)
            raise
        if record.payload is not None:
            r += ''.join((f'\n\t{l}' for l in record.payload.split('\n')))
        return r
    else:
        lines = s.split('\n')
        return '\n'.join((f'{prefix} {l}' for l in lines))

def evaluate(self, model, x=None, y=None, batch_size=None, verbose=1, sample_weight=None, steps=None, callbacks=None, **kwargs):
    """Evaluate loop for Distribution Strategies."""
    dist_utils.validate_inputs(x, y)
    (batch_size, steps) = dist_utils.process_batch_and_step_size(model._distribution_strategy, x, batch_size, steps, ModeKeys.TEST)
    batch_size = model._validate_or_infer_batch_size(batch_size, steps, x)
    dataset = model._distribution_standardize_user_data(x, y, sample_weight=sample_weight, batch_size=batch_size, allow_partial_batch=True)
    if <MASK>:
        steps = training_utils_v1.infer_steps_for_dataset(model, dataset, steps, steps_name='steps')
        if steps is None:
            raise ValueError('Number of steps could not be inferred from the data, please pass the steps argument.')
        if not context.executing_eagerly():
            return experimental_tpu_test_loop(model, dataset, verbose=verbose, steps=steps, callbacks=callbacks)
    return training_arrays_v1.test_loop(model, inputs=dataset, batch_size=batch_size, verbose=verbose, steps=steps, callbacks=callbacks)

def _recursive_or(a, b):
    """do a|=b on each field of a, recursively"""
    for name in a.dtype.names:
        (af, bf) = (a[name], b[name])
        if <MASK>:
            _recursive_or(af, bf)
        else:
            af |= bf

def get_language_from_request(request, check_path=False):
    """
    Analyze the request to find what language the user wants the system to
    show. Only languages listed in settings.LANGUAGES are taken into account.
    If the user requests a sublanguage where we have a main language, we send
    out the main language.

    If check_path is True, the URL path prefix will be checked for a language
    code, otherwise this is skipped for backwards compatibility.
    """
    if check_path:
        lang_code = get_language_from_path(request.path_info)
        if lang_code is not None:
            return lang_code
    lang_code = request.COOKIES.get(settings.LANGUAGE_COOKIE_NAME)
    if lang_code is not None and lang_code in get_languages() and check_for_language(lang_code):
        return lang_code
    try:
        return get_supported_language_variant(lang_code)
    except LookupError:
        pass
    accept = request.META.get('HTTP_ACCEPT_LANGUAGE', '')
    for (accept_lang, unused) in parse_accept_lang_header(accept):
        if accept_lang == '*':
            break
        if <MASK>:
            continue
        try:
            return get_supported_language_variant(accept_lang)
        except LookupError:
            continue
    try:
        return get_supported_language_variant(settings.LANGUAGE_CODE)
    except LookupError:
        return settings.LANGUAGE_CODE

def _is_supported(input_size, kernel_size, stride, padding, dilation):
    if <MASK>:
        raise RuntimeError('Dilation must be 1 for tensor parallel convolution.')
    if padding[-1] != 0:
        if stride[-1] != 1:
            raise RuntimeError('Stride must be 1 when there is padding for tensor parallel convolution.')
        if kernel_size[-1] // 2 > input_size[-1]:
            raise RuntimeError('kernel_size[-1] // 2 should be less than or equal to input_size[-1] for tensor parallel convolution.')
    elif not (input_size[-1] % stride[-1] == 0 and stride[-1] == kernel_size[-1]):
        raise RuntimeError('It requires that input_size[-1] is divisible by stride[-1] and stride[-1] equals kernel_size[-1] when there is padding for tensor parallel convolution.')
    return True

def __init__(self, input_workers=None, iterators=None, strategy=None, components=None, element_spec=None, cardinality=cardinality_lib.UNKNOWN, enable_get_next_as_optional=False, options=None, replica_order=None):
    if input_workers is None:
        raise ValueError('`input_workers` should be provided.')
    error_message = 'Either `input_workers` or both `components` and `element_spec` need to be provided.'
    self._options = options
    if iterators is None:
        if components is None or element_spec is None:
            raise ValueError(error_message)
        self._element_spec = element_spec
        self._input_workers = input_workers
        self._iterators = components
        self._strategy = strategy
        self._cardinality = cardinality
        self._enable_get_next_as_optional = enable_get_next_as_optional
        self._replica_order = replica_order
    else:
        if <MASK>:
            raise ValueError(error_message)
        super(DistributedIterator, self).__init__(input_workers, iterators, strategy, cardinality, enable_get_next_as_optional, replica_order)

def _get_tensors_for_gradient(x):
    """Returns the Tensors in `x` that should be differentiated.

  Args:
    x: A `Tensor` or `CompositeTensor`.

  Returns:
    A `Tensor` or a nested structure of `Tensor`.
  """
    if not isinstance(x, composite_tensor.CompositeTensor):
        return x
    if <MASK>:
        raise ValueError(f'Type {type(x).__name__} is not supported as a gradient source or gradient target.')
    composite_gradient = x.__composite_gradient__
    gradient_components = composite_gradient.get_gradient_components(x)
    if gradient_components is x:
        return x
    return nest.map_structure(_get_tensors_for_gradient, gradient_components)

def get_chunks(self, n_chunks: int | None=None):
    """
        Return an iterator yielding the chunks.
        See `DataFrame.get_chunks` for details on ``n_chunks``.
        """
    if n_chunks and n_chunks > 1:
        size = len(self._col)
        step = size // n_chunks
        if <MASK>:
            step += 1
        for start in range(0, step * n_chunks, step):
            yield PandasColumn(self._col.iloc[start:start + step], self._allow_copy)
    else:
        yield self

@lru_cache(256)
def _maybe_guard_rel(self, expr: sympy.Expr) -> None:
    """
        The relational guard is guarded to be true.  Use this information to
        simplify shapes (i.e. a == b or a % 5 == 0)
        """
    if isinstance(expr, sympy.And):
        for arg in expr.args:
            self._maybe_guard_rel(arg)
        return
    elif not isinstance(expr, sympy.Rel):
        log.warning('_maybe_guard_rel() was called on non-relation expression %s', expr)
        return
    if isinstance(expr, sympy.Ne):
        return
    free = list(expr.free_symbols)
    assert len(free) > 0, f'The expression should not be static by this point: {expr}'
    if len(free) > 5:
        return

    def _smart_symbol_sort(x: sympy.Symbol) -> tuple[int, int, str]:
        has_only_ephemeral_sources = x in self.var_to_sources and all((s.is_ephemeral() for s in self.var_to_sources[x]))
        hint_size = self.size_hint(x, allow_none=True)
        if hint_size is None:
            size = sys.maxsize
        elif symbol_is_type(x, SymT.SIZE):
            assert isinstance(hint_size, sympy.Expr)
            size = int(hint_size)
        else:
            size = sys.maxsize
        name = x.name
        return (1 if has_only_ephemeral_sources else 0, size, name)
    free = sorted(free, key=_smart_symbol_sort, reverse=True)
    lhs = expr.lhs
    rhs = expr.rhs
    self._refine_ranges(expr)
    if not isinstance(expr, sympy.Eq):
        return
    if not expr.has(Mod):
        try:
            floor_div_atoms = lhs.atoms(FloorDiv).union(rhs.atoms(FloorDiv))
            if len(floor_div_atoms) > 0 and any((a.divisor != 1 for a in floor_div_atoms)):
                raise NotImplementedError

            def trivial_solve(lhs: sympy.Expr, rhs: sympy.Expr) -> bool:
                if isinstance(lhs, sympy.Symbol):
                    if free_unbacked_symbols(lhs) and (not _free_non_source_unbacked_symbols(rhs, self.unbacked_inputs)):
                        return True
                    if symbol_is_type(lhs, SymT.FLOAT):
                        return True
                return False
            if trivial_solve(lhs, rhs):
                self._set_replacement(lhs, self._find(rhs), 'trivial_lhs')
            elif trivial_solve(rhs, lhs):
                self._set_replacement(rhs, self._find(lhs), 'trivial_rhs')
            else:
                r = try_solve(expr, free[0], floordiv_inequality=False)
                if r is not None and all((t.is_integer for t in sympy.preorder_traversal(r[1]))):
                    new_var = self._find(r[1])
                    ok = len(free_unbacked_symbols(new_var)) == 0
                    if ok:
                        self._set_replacement(free[0], new_var, 'solve')
        except NotImplementedError:
            pass
    if expr.has(Mod):
        mod_expr = next(iter(expr.atoms(Mod)))
        try:
            r = try_solve(expr, mod_expr, floordiv_inequality=False)
            if <MASK>:
                self._add_divisible(mod_expr)
                (p, q) = mod_expr.args
                if isinstance(q, sympy.Number) and isinstance(p, sympy.Mul) and (len(p.args) == 2):
                    (c, i0) = p.args
                    if isinstance(c, sympy.Number) and isinstance(i0, sympy.Symbol) and self.is_unbacked_symint(i0):
                        d = q / sympy.gcd(q, c)
                        i1 = self.create_unbacked_symint().node.expr
                        self._update_var_to_range(i1, SymPyValueRangeAnalysis.floordiv(self.var_to_range[i0], ValueRanges.wrap(d)))
                        if i0 in self.unbacked_var_to_val:
                            self.set_unbacked_var_to_val(i1, self.unbacked_var_to_val[i0] // d)
                        if i0 in self.size_like:
                            self.size_like.add(i1)
                        self._set_replacement(i0, d * i1, 'divisibility')
        except NotImplementedError:
            pass
    return

def merge_single_node(node: Node, node_order: Optional[int], id: Optional[int]):

    def _update_partition_map(node: Node, id: int):
        for user_node in node.users:
            target_id = assignment.get(user_node)
            if target_id is not None:
                partition_map[id].add(target_id)
                partition_map[id].update(partition_map[target_id])
    if node in assignment:
        partitions_by_id[assignment[node]].remove_node(node)
    if id is None:
        assignment.pop(node)
    elif <MASK>:
        assignment[node] = id
        assert node_order is not None
        partitions_by_id[id] = Partition(id=id, nodes=[node], node_orders=[node_order])
        partition_users[id] = set(node.users)
        _update_partition_map(node, id)
    else:
        assignment[node] = id
        partitions_by_id[id].add_node(node, node_order)

def __init__(self, node_pattern: NodePattern, modules: dict[str, torch.nn.Module], root_node_getter: Optional[Callable]=None):
    super().__init__(node_pattern, modules, root_node_getter)
    if <MASK>:
        assert self.num_tensor_args in num_tensor_args_to_observation_type, f'Must provide observation_type config for tensor number {self.num_tensor_args} in num_tensor_args_to_observation_type for {node_pattern}'
        self.observation_type = num_tensor_args_to_observation_type[self.num_tensor_args]
    else:
        self.observation_type = observation_type
    self.dtype_configs = dtype_configs

def _fix_nn_module_stacks(graph):
    for node in graph.nodes:
        if <MASK>:
            continue
        nn_module_stack = node.meta['nn_module_stack']
        fqns = [fqn.split('@')[0] if '@' in fqn else fqn for (fqn, _t) in nn_module_stack.values()]
        (prev_fqn, *next_fqns) = fqns
        num_valid_indices = 1
        for curr_fqn in next_fqns:
            if _is_prefix(prev_fqn, curr_fqn):
                num_valid_indices += 1
                prev_fqn = curr_fqn
            else:
                break
        if num_valid_indices < len(nn_module_stack):
            log.warning('nn_module_stack fqns %s at node %s do not form a stack! dropping last %d entries', fqns, node, len(nn_module_stack) - num_valid_indices)
            node.meta['nn_module_stack'] = dict(list(nn_module_stack.items())[:num_valid_indices])

def _merge_pytest_caches(pytest_cache_dir_to_merge_from: Path, pytest_cache_dir_to_merge_into: Path) -> None:
    static_files_to_copy = ['.gitignore', 'CACHEDIR.TAG', 'README.md']
    for static_file in static_files_to_copy:
        source_file = pytest_cache_dir_to_merge_from / static_file
        if not source_file.is_file():
            continue
        dest_file = pytest_cache_dir_to_merge_into / static_file
        if <MASK>:
            copy_file(source_file, dest_file)
    _merge_lastfailed_files(pytest_cache_dir_to_merge_from, pytest_cache_dir_to_merge_into)
    _merge_additional_failures_files(pytest_cache_dir_to_merge_from, pytest_cache_dir_to_merge_into)

def __init__(self, initial_value, *args, dtype=None, **kwargs):
    """Overrides tf.Variable to fix VarHandleOp placements."""
    layout = kwargs.pop('layout', None)
    shape = kwargs.get('shape', None)
    if callable(initial_value):
        unwrapped = initial_value
        if <MASK>:
            unwrapped = initial_value.func
        if issubclass(type(unwrapped), trackable.CheckpointInitialValueCallable):
            if not shape or not layout:
                raise ValueError('Expected shape and layout to be not None.')
            initial_value = api.call_with_layout(initial_value, layout, shard_info=trackable.ShardInfo(shape=shape, offset=[0] * len(shape)))
        else:
            initial_value = initial_value()
    if isinstance(initial_value, trackable.CheckpointInitialValue):
        initial_value = initial_value.wrapped_value
    initial_value = ops.convert_to_tensor(initial_value, dtype=dtype)
    variable_device = initial_value.device
    self._save_as_bf16 = False
    with ops.device(variable_device):
        if context.executing_eagerly():
            if api.is_dtensor(initial_value):
                value_layout = api.fetch_layout(initial_value)
                if layout is not None and layout != value_layout:
                    raise errors_impl.InvalidArgumentError(None, None, f'Conflicting layout are provided for initial value layout ({value_layout}) and variable ({layout}).')
                layout = value_layout
            elif layout is not None:
                initial_value = api.relayout(initial_value, layout)
            else:
                raise errors_impl.InvalidArgumentError(None, None, 'Neither layout nor DTensor initial value are provided.')
            self.layout = layout
            with api.default_mesh(layout.mesh):
                super(DVariable, self).__init__(initial_value, *args, dtype=dtype, **kwargs)
        else:
            if layout is not None:
                initial_value = api.relayout(initial_value, layout)
            super(DVariable, self).__init__(initial_value, *args, dtype=dtype, **kwargs)

def _maybe_convert_setitem_value(self, value):
    """Maybe convert value to be pyarrow compatible."""
    if <MASK>:
        if isna(value):
            value = None
        elif not isinstance(value, str):
            raise TypeError(f"Invalid value '{value}' for dtype 'str'. Value should be a string or missing value, got '{type(value).__name__}' instead.")
    else:
        value = np.array(value, dtype=object, copy=True)
        value[isna(value)] = None
        for v in value:
            if not (v is None or isinstance(v, str)):
                raise TypeError("Invalid value for dtype 'str'. Value should be a string or missing value (or array of those).")
    return super()._maybe_convert_setitem_value(value)

def _dtype_to_na_value(dtype: DtypeObj, has_none_blocks: bool):
    """
    Find the NA value to go with this dtype.
    """
    if isinstance(dtype, ExtensionDtype):
        return dtype.na_value
    elif dtype.kind in 'mM':
        return dtype.type('NaT')
    elif dtype.kind in 'fc':
        return dtype.type('NaN')
    elif dtype.kind == 'b':
        return None
    elif dtype.kind in 'iu':
        if <MASK>:
            return None
        return np.nan
    elif dtype.kind == 'O':
        return np.nan
    raise NotImplementedError

def save_graph_repro(fd: IO[Any], gm: torch.fx.GraphModule, args: Sequence[Any], compiler_name: str, *, stable_output: bool=False, save_dir: Optional[str]=None, command: str='run', accuracy: Optional[Union[str, bool]]=None, tracing_mode: Optional[str]=None, check_str: Optional[str]=None, stable_hash: bool=False) -> None:
    if any((isinstance(arg, torch.fx.experimental._backward_state.BackwardState) for arg in args)):
        fd.write('Repro is not generated due to existence of BackwardState in graph input')
        return
    if save_dir is not None:
        save_dir = normalize_path_separator(save_dir)
    has_distributed_ops = any((node.op == 'call_function' and isinstance(node.target, OpOverload) and (node.target.namespace in {'_c10d_functional', 'c10d_functional'}) for node in gm.graph.nodes))
    fd.write(generate_compiler_repro_string(gm, args, stable_output=stable_output, save_dir=save_dir, stable_hash=stable_hash, has_distributed_ops=has_distributed_ops))
    if <MASK>:
        accuracy = '_accuracy' in compiler_name
    if tracing_mode is None:
        tracing_mode = 'real'
        if any((has_free_symbols(a) for a in args if not isinstance(a, FakeScriptObject))):
            tracing_mode = 'symbolic'
    fd.write("if __name__ == '__main__':\n")
    fd.write('    from torch._dynamo.repro.after_aot import run_repro\n')
    if has_distributed_ops:
        fd.write('    # Initialize FakeProcessGroup for distributed operations\n    store = FakeStore()\n    dist.init_process_group(\n        backend="fake",\n        rank=0,\n        world_size=2,\n        store=store\n    )\n')
    fd.write(f"    with torch.no_grad():\n        run_repro(mod, load_args, accuracy={accuracy!r}, command={command!r}, save_dir={save_dir!r}, tracing_mode={tracing_mode!r}, check_str={check_str!r})\n        # To run it separately, do \n        # mod, args = run_repro(mod, load_args, accuracy={accuracy!r}, command='get_args', save_dir={save_dir!r}, tracing_mode={tracing_mode!r}, check_str={check_str!r})\n        # mod(*args)")
    if has_distributed_ops:
        fd.write('\n    dist.destroy_process_group()\n')

def filter_files(prefix, suffix, files, remove_prefix=None):
    """
    Filter files by prefix and suffix.
    """
    (filtered, rest) = ([], [])
    match = re.compile(prefix + '.*' + suffix + '\\Z').match
    if <MASK>:
        ind = len(prefix)
    else:
        ind = 0
    for file in [x.strip() for x in files]:
        if match(file):
            filtered.append(file[ind:])
        else:
            rest.append(file)
    return (filtered, rest)

def _check_choices(self):
    if not self.choices:
        return []
    if not isinstance(self.choices, Iterable) or isinstance(self.choices, str):
        return [checks.Error("'choices' must be a mapping (e.g. a dictionary) or an iterable (e.g. a list or tuple).", obj=self, id='fields.E004')]
    choice_max_length = 0
    for choices_group in self.choices:
        try:
            (group_name, group_choices) = choices_group
        except (TypeError, ValueError):
            break
        try:
            if not all((self._choices_is_value(value) and self._choices_is_value(human_name) for (value, human_name) in group_choices)):
                break
            if self.max_length is not None and group_choices:
                choice_max_length = max([choice_max_length, *(len(value) for (value, _) in group_choices if isinstance(value, str))])
        except (TypeError, ValueError):
            (value, human_name) = (group_name, group_choices)
            if <MASK>:
                break
            if self.max_length is not None and isinstance(value, str):
                choice_max_length = max(choice_max_length, len(value))
        if isinstance(choices_group, str):
            break
    else:
        if self.max_length is not None and choice_max_length > self.max_length:
            return [checks.Error("'max_length' is too small to fit the longest value in 'choices' (%d characters)." % choice_max_length, obj=self, id='fields.E009')]
        return []
    return [checks.Error("'choices' must be a mapping of actual values to human readable names or an iterable containing (actual value, human readable name) tuples.", obj=self, id='fields.E005')]

def _libs_with_msvc_and_fortran(self, fcompiler, c_libraries, c_library_dirs):
    if fcompiler is None:
        return
    for libname in c_libraries:
        if libname.startswith('msvc'):
            continue
        fileexists = False
        for libdir in c_library_dirs or []:
            libfile = os.path.join(libdir, '%s.lib' % libname)
            if os.path.isfile(libfile):
                fileexists = True
                break
        if fileexists:
            continue
        fileexists = False
        for libdir in c_library_dirs:
            libfile = os.path.join(libdir, 'lib%s.a' % libname)
            if os.path.isfile(libfile):
                libfile2 = os.path.join(self.build_temp, libname + '.lib')
                copy_file(libfile, libfile2)
                if self.build_temp not in c_library_dirs:
                    c_library_dirs.append(self.build_temp)
                fileexists = True
                break
        if fileexists:
            continue
        log.warn('could not find library %r in directories %s' % (libname, c_library_dirs))
    f_lib_dirs = []
    for dir in fcompiler.library_dirs:
        if dir.startswith('/usr/lib'):
            try:
                dir = subprocess.check_output(['cygpath', '-w', dir])
            except (OSError, subprocess.CalledProcessError):
                pass
            else:
                dir = filepath_from_subprocess_output(dir)
        f_lib_dirs.append(dir)
    c_library_dirs.extend(f_lib_dirs)
    for lib in fcompiler.libraries:
        if <MASK>:
            c_libraries.append(lib)
            p = combine_paths(f_lib_dirs, 'lib' + lib + '.a')
            if p:
                dst_name = os.path.join(self.build_temp, lib + '.lib')
                if not os.path.isfile(dst_name):
                    copy_file(p[0], dst_name)
                if self.build_temp not in c_library_dirs:
                    c_library_dirs.append(self.build_temp)

@classmethod
def eval(cls, p: sympy.Expr, q: sympy.Expr) -> Optional[sympy.Expr]:
    if <MASK>:
        raise ZeroDivisionError('Modulo by zero')
    if p is S.Zero or p in (q, -q) or q == 1:
        return S.Zero
    if q.is_Number and p.is_Number:
        return p % q
    if q.is_Number and q == 2:
        if p.is_even:
            return S.Zero
        if p.is_odd:
            return S.One
    r = p / q
    if r.is_integer:
        return S.Zero
    less = p < q
    if less.is_Boolean and bool(less) and r.is_positive:
        return p
    if sympy.Mod(p, q) == 0:
        return S.Zero
    return None

def __call__(self, module, input, output):
    if <MASK>:
        bias = module._bias.data
        if self.prune_bias:
            bias[~self.param.mask] = 0
        idx = [1] * len(output.shape)
        idx[1] = -1
        bias = bias.reshape(idx)
        output += bias
    return output

def urlencode(query, doseq=False):
    """
    A version of Python's urllib.parse.urlencode() function that can operate on
    MultiValueDict and non-string values.
    """
    if isinstance(query, MultiValueDict):
        query = query.lists()
    elif hasattr(query, 'items'):
        query = query.items()
    query_params = []
    for (key, value) in query:
        if value is None:
            raise TypeError("Cannot encode None for key '%s' in a query string. Did you mean to pass an empty string or omit the value?" % key)
        elif not doseq or isinstance(value, (str, bytes)):
            query_val = value
        else:
            try:
                itr = iter(value)
            except TypeError:
                query_val = value
            else:
                query_val = []
                for item in itr:
                    if <MASK>:
                        raise TypeError("Cannot encode None for key '%s' in a query string. Did you mean to pass an empty string or omit the value?" % key)
                    elif not isinstance(item, bytes):
                        item = str(item)
                    query_val.append(item)
        query_params.append((key, query_val))
    return original_urlencode(query_params, doseq)

def generate_created_models(self):
    """
        Find all new models (both managed and unmanaged) and make create
        operations for them as well as separate operations to create any
        foreign key or M2M relationships (these are optimized later, if
        possible).

        Defer any model options that refer to collections of fields that might
        be deferred (e.g. unique_together).
        """
    old_keys = self.old_model_keys | self.old_unmanaged_keys
    added_models = self.new_model_keys - old_keys
    added_unmanaged_models = self.new_unmanaged_keys - old_keys
    all_added_models = chain(sorted(added_models, key=self.swappable_first_key, reverse=True), sorted(added_unmanaged_models, key=self.swappable_first_key, reverse=True))
    for (app_label, model_name) in all_added_models:
        model_state = self.to_state.models[app_label, model_name]
        related_fields = {}
        primary_key_rel = None
        for (field_name, field) in model_state.fields.items():
            if field.remote_field:
                if field.remote_field.model:
                    if field.primary_key:
                        primary_key_rel = field.remote_field.model
                    elif not field.remote_field.parent_link:
                        related_fields[field_name] = field
                if getattr(field.remote_field, 'through', None):
                    related_fields[field_name] = field
        indexes = model_state.options.pop('indexes')
        constraints = model_state.options.pop('constraints')
        unique_together = model_state.options.pop('unique_together', None)
        order_with_respect_to = model_state.options.pop('order_with_respect_to', None)
        dependencies = [OperationDependency(app_label, model_name, None, OperationDependency.Type.REMOVE)]
        for base in model_state.bases:
            if isinstance(base, str) and '.' in base:
                (base_app_label, base_name) = base.split('.', 1)
                dependencies.append(OperationDependency(base_app_label, base_name, None, OperationDependency.Type.CREATE))
                old_base_model_state = self.from_state.models.get((base_app_label, base_name))
                new_base_model_state = self.to_state.models.get((base_app_label, base_name))
                if old_base_model_state and new_base_model_state:
                    removed_base_fields = set(old_base_model_state.fields).difference(new_base_model_state.fields).intersection(model_state.fields)
                    for removed_base_field in removed_base_fields:
                        dependencies.append(OperationDependency(base_app_label, base_name, removed_base_field, OperationDependency.Type.REMOVE))
        if <MASK>:
            dependencies.append(OperationDependency(*resolve_relation(primary_key_rel, app_label, model_name), None, OperationDependency.Type.CREATE))
        self.add_operation(app_label, operations.CreateModel(name=model_state.name, fields=[d for d in model_state.fields.items() if d[0] not in related_fields], options=model_state.options, bases=model_state.bases, managers=model_state.managers), dependencies=dependencies, beginning=True)
        if not model_state.options.get('managed', True):
            continue
        for (name, field) in sorted(related_fields.items()):
            dependencies = self._get_dependencies_for_foreign_key(app_label, model_name, field, self.to_state)
            dependencies.append(OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE))
            self.add_operation(app_label, operations.AddField(model_name=model_name, name=name, field=field), dependencies=list(set(dependencies)))
        if order_with_respect_to:
            self.add_operation(app_label, operations.AlterOrderWithRespectTo(name=model_name, order_with_respect_to=order_with_respect_to), dependencies=[OperationDependency(app_label, model_name, order_with_respect_to, OperationDependency.Type.CREATE), OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE)])
        related_dependencies = [OperationDependency(app_label, model_name, name, OperationDependency.Type.CREATE) for name in sorted(related_fields)]
        related_dependencies.append(OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE))
        for index in indexes:
            self.add_operation(app_label, operations.AddIndex(model_name=model_name, index=index), dependencies=related_dependencies)
        for constraint in constraints:
            self.add_operation(app_label, operations.AddConstraint(model_name=model_name, constraint=constraint), dependencies=related_dependencies)
        if unique_together:
            self.add_operation(app_label, operations.AlterUniqueTogether(name=model_name, unique_together=unique_together), dependencies=related_dependencies)
        relations = self.to_state.relations
        if (app_label, model_name) in self.old_proxy_keys:
            for (related_model_key, related_fields) in relations[app_label, model_name].items():
                related_model_state = self.to_state.models[related_model_key]
                for (related_field_name, related_field) in related_fields.items():
                    self.add_operation(related_model_state.app_label, operations.AlterField(model_name=related_model_state.name, name=related_field_name, field=related_field), dependencies=[OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE)])

def should_convert(var_name: str, blacklist: list[str] | None, whitelist_prefix: list[str] | None):
    """Check the variable name against white/black lists."""
    if <MASK>:
        return False
    if not whitelist_prefix:
        return True
    for prefix in whitelist_prefix:
        if var_name.startswith(prefix):
            return True
    return False

def build_filter(self, filter_expr, branch_negated=False, current_negated=False, can_reuse=None, allow_joins=True, split_subq=True, check_filterable=True, summarize=False, update_join_types=True):
    """
        Build a WhereNode for a single filter clause but don't add it
        to this Query. Query.add_q() will then add this filter to the where
        Node.

        The 'branch_negated' tells us if the current branch contains any
        negations. This will be used to determine if subqueries are needed.

        The 'current_negated' is used to determine if the current filter is
        negated or not and this will be used to determine if IS NULL filtering
        is needed.

        The difference between current_negated and branch_negated is that
        branch_negated is set on first negation, but current_negated is
        flipped for each negation.

        Note that add_filter will not do any negating itself, that is done
        upper in the code by add_q().

        The 'can_reuse' is a set of reusable joins for multijoins.

        The method will create a filter clause that can be added to the current
        query. However, if the filter isn't added to the query then the caller
        is responsible for unreffing the joins used.
        """
    if isinstance(filter_expr, dict):
        raise FieldError('Cannot parse keyword query as dict')
    if isinstance(filter_expr, Q):
        return self._add_q(filter_expr, branch_negated=branch_negated, current_negated=current_negated, used_aliases=can_reuse, allow_joins=allow_joins, split_subq=split_subq, check_filterable=check_filterable, summarize=summarize, update_join_types=update_join_types)
    if hasattr(filter_expr, 'resolve_expression'):
        if not getattr(filter_expr, 'conditional', False):
            raise TypeError('Cannot filter against a non-conditional expression.')
        condition = filter_expr.resolve_expression(self, allow_joins=allow_joins, reuse=can_reuse, summarize=summarize)
        if not isinstance(condition, Lookup):
            condition = self.build_lookup(['exact'], condition, True)
        return (WhereNode([condition], connector=AND), [])
    (arg, value) = filter_expr
    if not arg:
        raise FieldError('Cannot parse keyword query %r' % arg)
    (lookups, parts, reffed_expression) = self.solve_lookup_type(arg, summarize)
    if check_filterable:
        self.check_filterable(reffed_expression)
    if not allow_joins and len(parts) > 1:
        raise FieldError('Joined field references are not permitted in this query')
    pre_joins = self.alias_refcount.copy()
    value = self.resolve_lookup_value(value, can_reuse, allow_joins, summarize)
    used_joins = {k for (k, v) in self.alias_refcount.items() if v > pre_joins.get(k, 0)}
    if check_filterable:
        self.check_filterable(value)
    if reffed_expression:
        condition = self.build_lookup(lookups, reffed_expression, value)
        return (WhereNode([condition], connector=AND), [])
    opts = self.get_meta()
    alias = self.get_initial_alias()
    allow_many = not branch_negated or not split_subq
    try:
        join_info = self.setup_joins(parts, opts, alias, can_reuse=can_reuse, allow_many=allow_many)
        if isinstance(value, Iterator):
            value = list(value)
        self.check_related_objects(join_info.final_field, value, join_info.opts)
        self._lookup_joins = join_info.joins
    except MultiJoin as e:
        return self.split_exclude(filter_expr, can_reuse, e.names_with_path)
    used_joins.update(join_info.joins)
    (targets, alias, join_list) = self.trim_joins(join_info.targets, join_info.joins, join_info.path)
    if can_reuse is not None:
        can_reuse.update(join_list)
    if join_info.final_field.is_relation:
        if len(targets) == 1:
            col = self._get_col(targets[0], join_info.final_field, alias)
        else:
            col = ColPairs(alias, targets, join_info.targets, join_info.final_field)
    else:
        col = self._get_col(targets[0], join_info.final_field, alias)
    condition = self.build_lookup(lookups, col, value)
    lookup_type = condition.lookup_name
    clause = WhereNode([condition], connector=AND)
    require_outer = lookup_type == 'isnull' and condition.rhs is True and (not current_negated)
    if current_negated and (lookup_type != 'isnull' or condition.rhs is False) and (condition.rhs is not None):
        require_outer = True
        if <MASK>:
            if self.is_nullable(targets[0]) or self.alias_map[join_list[-1]].join_type == LOUTER:
                lookup_class = targets[0].get_lookup('isnull')
                col = self._get_col(targets[0], join_info.targets[0], alias)
                clause.add(lookup_class(col, False), AND)
            if isinstance(value, Col) and self.is_nullable(value.target):
                lookup_class = value.target.get_lookup('isnull')
                clause.add(lookup_class(value, False), AND)
    return (clause, used_joins if not require_outer else ())

def _wrap_result(self, result, name=None, expand: bool | None=None, fill_value=np.nan, returns_string: bool=True, dtype=None):
    from pandas import Index, MultiIndex
    if not hasattr(result, 'ndim') or not hasattr(result, 'dtype'):
        if isinstance(result, ABCDataFrame):
            result = result.__finalize__(self._orig, name='str')
        return result
    assert result.ndim < 3
    if expand is None:
        expand = result.ndim != 1
    elif expand is True and (not isinstance(self._orig, ABCIndex)):
        if <MASK>:
            import pyarrow as pa
            from pandas.core.arrays.arrow.array import ArrowExtensionArray
            value_lengths = pa.compute.list_value_length(result._pa_array)
            max_len = pa.compute.max(value_lengths).as_py()
            min_len = pa.compute.min(value_lengths).as_py()
            if result._hasna:
                result = ArrowExtensionArray(result._pa_array.fill_null([None] * max_len))
            if min_len < max_len:
                result = ArrowExtensionArray(pa.compute.list_slice(result._pa_array, start=0, stop=max_len, return_fixed_size_list=True))
            if name is None:
                name = range(max_len)
            result = pa.compute.list_flatten(result._pa_array).to_numpy().reshape(len(result), max_len)
            result = {label: ArrowExtensionArray(pa.array(res)) for (label, res) in zip(name, result.T, strict=True)}
        elif is_object_dtype(result):

            def cons_row(x):
                if is_list_like(x):
                    return x
                else:
                    return [x]
            result = [cons_row(x) for x in result]
            if result and (not self._is_string):
                max_len = max((len(x) for x in result))
                result = [x * max_len if len(x) == 0 or x[0] is np.nan else x for x in result]
    if not isinstance(expand, bool):
        raise ValueError('expand must be True or False')
    if expand is False:
        if name is None:
            name = getattr(result, 'name', None)
        if name is None:
            name = self._orig.name
    if isinstance(self._orig, ABCIndex):
        if is_bool_dtype(result):
            return result
        if expand:
            result = list(result)
            out: Index = MultiIndex.from_tuples(result, names=name)
            if out.nlevels == 1:
                out = out.get_level_values(0)
            return out
        else:
            return Index(result, name=name, dtype=dtype)
    else:
        index = self._orig.index
        _dtype: DtypeObj | str | None = dtype
        vdtype = getattr(result, 'dtype', None)
        if _dtype is not None:
            pass
        elif self._is_string:
            if is_bool_dtype(vdtype):
                _dtype = result.dtype
            elif returns_string:
                _dtype = self._orig.dtype
            else:
                _dtype = vdtype
        elif vdtype is not None:
            _dtype = vdtype
        if expand:
            cons = self._orig._constructor_expanddim
            result = cons(result, columns=name, index=index, dtype=_dtype)
        else:
            cons = self._orig._constructor
            result = cons(result, name=name, index=index, dtype=_dtype)
        result = result.__finalize__(self._orig, method='str')
        if name is not None and result.ndim == 1:
            result.name = name
        return result

def get_prep_lookup(self):
    if <MASK>:
        self.rhs = get_normalized_value(self.rhs, self.lhs)[0]
        if self.prepare_rhs and hasattr(self.lhs.output_field, 'path_infos'):
            target_field = self.lhs.output_field.path_infos[-1].target_fields[-1]
            self.rhs = target_field.get_prep_value(self.rhs)
