@compatibility(is_backward_compatible=True)
def create_arg(self, a: Any) -> Argument:
    """
        A method that lowers the objects seen as arguments during symbolic evaluation
        into Argument types that can be stored in IR.

        Can be override to support more trace-specific types.
        """
    handler = _create_arg_bypass.get(type(a))
    if handler is not None:
        return handler(self, a)
    if isinstance(a, Proxy):
        return a.node
    elif hasattr(a, '__fx_create_arg__'):
        return a.__fx_create_arg__(self)
    elif isinstance(a, tuple):
        if hasattr(a, '_fields'):
            args = [self.create_arg(elem) for elem in a]
            return type(a)(*args)
        return type(a)([self.create_arg(elem) for elem in a])
    elif isinstance(a, list):
        return [self.create_arg(elem) for elem in a]
    elif <MASK>:
        return _create_arg_dict(self, a)
    elif isinstance(a, slice):
        return slice(self.create_arg(a.start), self.create_arg(a.stop), self.create_arg(a.step))
    elif isinstance(a, range):
        return range(self.create_arg(a.start), self.create_arg(a.stop), self.create_arg(a.step))
    elif isinstance(a, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)):
        return a
    elif is_dataclass(a):
        kwargs = {field.name: self.create_arg(getattr(a, field.name)) for field in fields(a)}
        return self.create_node('call_function', a.__class__, (), kwargs)
    elif isinstance(a, (*base_types, enum.Enum)) or a is None or a is ...:
        return a
    raise NotImplementedError(f'argument of type: {type(a)}')

def _sparse_csr_segment_reduction_helper(op, mask_input: Tensor, dims: tuple[int, ...], keepdim: bool, dtype: Optional[DType]=None) -> Tensor:
    assert keepdim, 'reduction operations on CSR tensors with keepdim=False is unsupported'
    reduce = op.__name__
    valid_reductions = ['sum', 'prod', 'mean', 'amax', 'amin']
    if reduce not in valid_reductions:
        raise ValueError(f"op must be one of {' '.join(valid_reductions)}, but got {reduce} instead")
    device = mask_input.device
    output_dtype = dtype
    (values, crow_indices, col_indices) = (mask_input.values(), mask_input.crow_indices(), mask_input.col_indices())
    if values.dtype != output_dtype:
        values = values.to(output_dtype)
    if len(dims) == 0:
        return mask_input
    if <MASK>:
        if dims[0] == 0:
            (new_col_indices, scatter_indices) = torch.unique(col_indices, return_inverse=True)
            new_nnz = new_col_indices.shape[0]
            new_crow_indices = torch.tensor([0, new_nnz])
            new_values = values.new_empty(new_col_indices.shape)
            new_values.scatter_reduce_(0, scatter_indices, values, reduce, include_self=False)
            new_shape = [1, mask_input.size(1)]
        else:
            assert dims[0] == 1, 'Sparse CSR tensors are 2D and only support reduction along dim 0 or 1.'
            new_crow_indices = torch.cat((crow_indices.new_zeros(1), torch.cumsum(torch.diff(crow_indices) != 0, 0)), 0)
            new_nnz = new_crow_indices[-1]
            new_col_indices = col_indices.new_zeros(new_nnz)
            new_values = torch._segment_reduce(values, reduce, offsets=crow_indices)
            new_shape = [mask_input.size(0), 1]
    else:
        assert len(dims) == 2
        nnz = min(1, values.numel())
        if nnz == 1:
            op_kwargs = {'keepdim': True, 'dtype': output_dtype}
            if reduce in ['amax', 'amin']:
                del op_kwargs['dtype']
            new_values = op(values, 0, **op_kwargs)
        else:
            new_values = torch.empty(0, dtype=output_dtype)
        new_col_indices = col_indices.new_zeros(nnz)
        new_crow_indices = torch.tensor([0, nnz])
        new_shape = [1, nnz]
    return torch.sparse_csr_tensor(new_crow_indices, new_col_indices, new_values, new_shape, dtype=output_dtype, device=device)

def _size_of(node: fx.Node) -> int:

    def object_nbytes(x) -> int:
        if not isinstance(x, torch.Tensor):
            return 0
        return _tensor_nbytes(hint_int(x.numel(), fallback=4096), x.dtype)
    if 'val' in node.meta:
        val = node.meta['val']
        if <MASK>:
            return 1
        elif isinstance(val, (list, tuple)):
            return sum((object_nbytes(n) for n in val))
        elif isinstance(val, dict):
            return sum((object_nbytes(n) for (_, n) in val.items()))
        elif isinstance(val, torch.Tensor):
            return object_nbytes(val)
        raise RuntimeError(f'Unknown metadata type {type(val)} on node {node}')
    if node.op == 'get_attr' or node.target is torch.ops.aten._assert_scalar.default:
        return 0
    raise RuntimeError(f"Node {node} didn't have `val` metadata; we should always have `val` metadata on the nodes.")

def add_assertions(val):
    call_backs: list[Callable] = []
    messages: list[str] = []
    if isinstance(val, (torch.SymInt, torch.SymFloat, torch.SymBool)):
        symbol = val.node.expr
        if symbol in self.existing_inline_assertions:
            return (call_backs, messages)
        if isinstance(symbol, sympy.Symbol) and free_unbacked_symbols(symbol):
            if <MASK>:
                return (call_backs, messages)
            constraint = self.range_constraints[symbol]
            (min_val, max_val) = _convert_range_to_int(constraint)
            assert_msg = f' is outside of inline constraint [{min_val}, {max_val}].'
            call_backs.append(partial(self._assert_range_constraint, lower=min_val, upper=max_val))
            messages.append(assert_msg)
            self._asserts_generated_unbacked_symbols.add(symbol)
    elif isinstance(val, torch.Tensor):
        for (i, sym) in enumerate(val.shape):
            (cbs, msgs) = add_assertions(sym)
            for (cb, msg) in zip(cbs, msgs):

                def sym_size_cb(node, assert_msg, dim):
                    with node.graph.inserting_after(node):
                        dim_node = module.graph.call_function(torch.ops.aten.sym_size.int, (node, dim), {})
                    cb(node=dim_node, assert_msg=assert_msg)
                call_backs.append(partial(sym_size_cb, dim=i))
                messages.append(f'.shape[{i}]' + msg)
    return (call_backs, messages)

@cached_property
def lookup_str(self):
    """
        A string that identifies the view (e.g. 'path.to.view_function' or
        'path.to.ClassBasedView').
        """
    callback = self.callback
    if isinstance(callback, functools.partial):
        callback = callback.func
    if <MASK>:
        callback = callback.view_class
    elif not hasattr(callback, '__name__'):
        return callback.__module__ + '.' + callback.__class__.__name__
    return callback.__module__ + '.' + callback.__qualname__

