def install(self, backends: dict[_BackendId, Any]) -> None:
    """
        Sync the package states to the compiled function. This includes the following actions:
          1. Clean up the previously installed states.
          2. Install the compiled functions to global scopes.
          3. Install the precompiled cache entries to ExtraStates on the code object.
        """
    from torch._C._dynamo.eval_frame import _load_precompile_entry
    from .output_graph import get_builtins_dict
    self.uninstall()
    for (code, entry) in self._codes.items():
        context = _compile_frame_context(code) if entry.has_compile_id else contextlib.nullcontext()
        with context:
            module = sys.modules[entry.python_module]
            for (alias, module_name) in entry.import_sources.items():
                self._install_global(module, alias, importlib.import_module(module_name))
            target_code = code
            if entry.install_to_global:
                for function_name in entry.function_names:
                    fn = types.FunctionType(code, module.__dict__, function_name)
                    self._install_global(module, function_name, fn)
            if <MASK>:
                target_code = _lookup_code(entry)
            if entry.bypassed:
                continue
            for backend_id in entry.backend_ids:
                if backend_id not in backends:
                    raise RuntimeError(f'Backend {backend_id} is not found in the given backends')
                with dynamo_timed('after_deserialization', phase_name='backend_compile'):
                    backend = backends[backend_id].after_deserialization()
                    self._install_global(module, backend_id, torch._dynamo.disable(backend))
            if len(entry.guarded_codes) == 0:
                torch._dynamo.eval_frame.skip_code(target_code)
            for guarded_code in entry.guarded_codes:
                with dynamo_timed('precompile_load_guards'):
                    guards_state = load_guards_state(guarded_code.guards_state)
                runtime_global_scope = sys.modules[entry.python_module].__dict__
                if (builtin_dict_name := guards_state.output_graph.name_of_builtins_dict_key_in_fglobals):
                    builtins_dict = get_builtins_dict(runtime_global_scope)
                    if builtin_dict_name in runtime_global_scope:
                        assert runtime_global_scope[builtin_dict_name] is builtins_dict
                    else:
                        runtime_global_scope[builtin_dict_name] = builtins_dict
                assert isinstance(guards_state, torch._dynamo.guards.GuardsState)
                with dynamo_timed('precompile_build_guards'):
                    guard_manager = load_guard_manager(guards_state, target_code, runtime_global_scope)
                _load_precompile_entry(target_code, guard_manager, SerializedCode.to_code_object(guarded_code.dynamo_code))

def skip_if_lt_x_gpu(x):

    def decorator(func):

        @wraps(func)
        def wrapper(*args, **kwargs):
            if <MASK>:
                return func(*args, **kwargs)
            if TEST_HPU and torch.hpu.device_count() >= x:
                return func(*args, **kwargs)
            if TEST_XPU and torch.xpu.device_count() >= x:
                return func(*args, **kwargs)
            test_skip = TEST_SKIPS[f'multi-gpu-{x}']
            if not _maybe_handle_skip_if_lt_x_gpu(args, test_skip.message):
                sys.exit(test_skip.exit_code)
        return wrapper
    return decorator

def from_value(value: Any, context: trace.TracingContext=None) -> trace.TraceType:
    """Returns a TraceType corresponding to the value based on the context.

  Args:
    value: The value to generate a TraceType for.
    context: The TracingContext to be shared during protocol calls.

  Returns:
    A TraceType object representing the given value.
  """
    if context is None:
        context = InternalTracingContext()
    if context.is_legacy_signature and isinstance(value, trace.TraceType):
        return value
    elif isinstance(value, trace.SupportsTracingProtocol):
        generated_type = value.__tf_tracing_type__(context)
        if not isinstance(generated_type, trace.TraceType):
            raise TypeError('Expected an instance of TraceType for Tracing Protocol call to ' + str(value) + ' but got ' + str(generated_type))
        return generated_type
    if isinstance(value, weakref.ref):
        raise TypeError(f'weakref input {value} not supported for tf.function.')
    if hasattr(value, '__wrapped__'):
        return from_value(value.__wrapped__, context)
    if isinstance(value, list):
        return default_types.List(*(from_value(c, context) for c in value))
    if <MASK>:
        if util.is_namedtuple(value):
            named_tuple_type = type(value)
            return default_types.NamedTuple.from_type_and_attributes(named_tuple_type, tuple((from_value(c, context) for c in value)))
        else:
            return default_types.Tuple(*(from_value(c, context) for c in value))
    if isinstance(value, collections.abc.Mapping):
        mapping_type = type(value)
        return default_types.Dict({k: from_value(value[k], context) for k in value}, mapping_type)
    if util.is_attrs(value):
        return default_types.Attrs.from_type_and_attributes(type(value), tuple((from_value(getattr(value, a.name), context) for a in value.__attrs_attrs__)))
    if util.is_np_ndarray(value):
        ndarray = value.__array__()
        return default_types.TENSOR(ndarray.shape, ndarray.dtype)
    if isinstance(value, custom_nest_protocol.CustomNestProtocol):
        (metadata, components) = value.__tf_flatten__()
        return custom_nest_trace_type.CustomNestTraceType(type(value), metadata, tuple((from_value(c, context) for c in components)))
    try:
        ref = weakref.ref(value)
        if ref is None:
            raise TypeError(f'Deleted objects are not valid tf.function arguments, Got {value!r}')
        else:
            return default_types.Weakref(ref)
    except TypeError:
        try:
            return default_types.Literal(value)
        except:
            raise TypeError(f'Could not generate a generic TraceType for {value!r}.Please verify that it is immutable/hashable. Otherwise, consider implementing the Tracing Protocol for it.')

def check_forward_hidden(self, input: Tensor, hx: Tensor, hidden_label: str='') -> None:
    if input.size(0) != hx.size(0):
