def check_scale(scale_name, scale, mat, scaled_dim, scale_multiplier=1):
    if mat.dim() == 2:
        torch._check(scale.is_contiguous(), lambda : f'Expected {scale_name} to be contiguous.')
        if <MASK>:
            torch._check(scale.dim() == mat.dim(), lambda : f'For MXFP8, scale must have same number of dimensions as target tensor, but {scale_name} has mat.ndim={mat.ndim} and scale.ndim={scale.ndim}')
        else:
            torch._check(scale.dim() == 1, lambda : f'Expected {scale_name} to be 1D tensor, but got {scale.dim()}D tensor.')
            torch._check(scale.shape[0] == mat.shape[scaled_dim] * scale_multiplier, lambda : f'Expected {scale_name} to have {mat.shape[scaled_dim] * scale_multiplier} elements, got {scale.shape[0]} elements.')
    else:
        torch._check(scale.stride(-1) == 1, lambda : f'Expected {scale_name} to be contiguous in the last dimension.')
        torch._check(scale.shape[0] == mat.shape[0], lambda : f'Expected {scale_name} batch dimension to be {mat.shape[0]}, got {scale.shape[0]}.')
        if is_mxfp8:
            torch._check(scale.ndim == mat.ndim - 1, lambda : f'For MXFP8, 3d tensor should have 2d scales, but {scale_name} has mat.ndim={mat.ndim} and scale.ndim={scale.ndim}')
            (G, K, N) = mat.shape
            block_size = 32
            blocked_K = round_up(K / block_size, 4)
            blocked_N = round_up(N, 128)
            torch._check(scale.shape[0] == G and scale.shape[1] == blocked_K * blocked_N, lambda : f'For MXFP8, expected mat.shape={mat.shape} to have scale shape of ({G},{blocked_K * blocked_N}), but got {scale.shape}')
        else:
            torch._check(scale.dim() == 2, lambda : f'Expected {scale_name} to be 2D tensor, but got {scale.dim()}D tensor.')
            torch._check(scale.shape[1] == mat.shape[1 + scaled_dim], lambda : f'Expected {scale_name} non-batch dimension to be {mat.shape[1 + scaled_dim]}, got {scale.shape[1]}.')

def wrapper(f):
    params = inspect.signature(f).parameters
    arg_names = tuple(params.keys())

    @functools.wraps(f)
    def wrapped(*args, **kwargs):
        kwargs.update(zip(arg_names, args, strict=False))
        cond = True
        if 'device' in kwargs:
            cond = cond and torch.device(kwargs['device']).type == 'cpu'
        if 'dtype' in kwargs:
            cond = cond and kwargs['dtype'] == torch.float
        bf32_cond = cond and bf32_is_not_fp32()
        tf32_cond = cond and tf32_is_not_fp32()
        if <MASK>:
            with_reduced_f32_disabled(kwargs['self'], lambda : f(**kwargs))
            if bf32_cond:
                with_bf32_enabled(kwargs['self'], lambda : f(**kwargs))
            if tf32_cond:
                with_tf32_enabled(kwargs['self'], lambda : f(**kwargs))
        else:
            f(**kwargs)
    return wrapped

def convert_to_generator_like(data, batch_size=None, steps_per_epoch=None, epochs=1, shuffle=False):
    """Make a generator out of NumPy or EagerTensor inputs.

  Args:
    data: Either a generator or `keras.utils.data_utils.Sequence` object or
      `Dataset`, `Iterator`, or a {1,2,3}-tuple of NumPy arrays or EagerTensors.
      If a tuple, the elements represent `(x, y, sample_weights)` and may be
      `None` or `[None]`.
    batch_size: Used when creating a generator out of tuples of NumPy arrays or
      EagerTensors.
    steps_per_epoch: Steps of the generator to run each epoch. If `None` the
      number of steps will be read from the data (for
      `keras.utils.data_utils.Sequence` types).
    epochs: Total number of epochs to run.
    shuffle: Whether the data should be shuffled.

  Returns:
    - Generator, `keras.utils.data_utils.Sequence`, or `Iterator`.

  Raises:
    - ValueError: If `batch_size` is not provided for NumPy or EagerTensor
      inputs.
  """
    if isinstance(data, tuple):
        data = tuple((ele for ele in data if not all((e is None for e in nest.flatten(ele)))))
    if data_utils.is_generator_or_sequence(data) or isinstance(data, iterator_ops.IteratorBase):
        if isinstance(data, data_utils.Sequence):
            if <MASK>:
                steps_per_epoch = len(data)
        return (data, steps_per_epoch)
    if isinstance(data, data_types.DatasetV2):
        return (dataset_ops.make_one_shot_iterator(data), steps_per_epoch)
    num_samples = int(nest.flatten(data)[0].shape[0])
    if batch_size is None:
        raise ValueError('When passing input data as arrays, do not specify `steps_per_epoch`/`steps` argument. Please use `batch_size` instead.')
    steps_per_epoch = int(math.ceil(num_samples / batch_size))

    def _gen(data):
        """Makes a generator out of a structure of NumPy/EagerTensors."""
        index_array = np.arange(num_samples)
        for _ in range(epochs):
            if shuffle:
                np.random.shuffle(index_array)
            batches = generic_utils.make_batches(num_samples, batch_size)
            for (batch_start, batch_end) in batches:
                batch_ids = index_array[batch_start:batch_end]
                flat_batch_data = training_utils.slice_arrays(nest.flatten(data), batch_ids, contiguous=not shuffle)
                yield nest.pack_sequence_as(data, flat_batch_data)
    return (_gen(data), steps_per_epoch)

