def module_options(self, module_dirs, module_build_dir):
    options = []
    if self.module_dir_switch is not None:
        if <MASK>:
            options.extend([self.module_dir_switch.strip(), module_build_dir])
        else:
            options.append(self.module_dir_switch.strip() + module_build_dir)
    else:
        print('XXX: module_build_dir=%r option ignored' % module_build_dir)
        print('XXX: Fix module_dir_switch for ', self.__class__.__name__)
    if self.module_include_switch is not None:
        for d in [module_build_dir] + module_dirs:
            options.append('%s%s' % (self.module_include_switch, d))
    else:
        print('XXX: module_dirs=%r option ignored' % module_dirs)
        print('XXX: Fix module_include_switch for ', self.__class__.__name__)
    return options

@register_op_strategy(aten.scatter_add.default, schema_info=RuntimeSchemaInfo(1))
def scatter_add_strategy(op_schema: OpSchema) -> StrategyType:
    input_strategy = op_schema.args_schema[0]
    dim = op_schema.args_schema[1]
    index_strategy = op_schema.args_schema[2]
    if not isinstance(input_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(input_strategy)}')
    if not isinstance(index_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(index_strategy)}')
    if <MASK>:
        raise AssertionError(f'Expected int, got {type(dim)}')
    dim = normalize_dim(dim, input_strategy.ndim)
    mesh = input_strategy.mesh
    input_shape = input_strategy.shape
    index_shape = index_strategy.shape
    single_mesh_dim_strategies = []
    all_replicate: PlacementList = [Replicate()] * 4
    single_mesh_dim_strategies.append(all_replicate)
    if len(input_shape) == len(index_shape):
        for d in range(len(input_shape)):
            if d != dim and input_shape[d] == index_shape[d]:
                sharding: PlacementList = [Shard(d), Shard(d), Shard(d), Shard(d)]
                single_mesh_dim_strategies.append(sharding)
    return expand_to_full_mesh_op_strategy(mesh, op_schema, single_mesh_dim_strategies, input_index=1)

def _single_tensor_sgd(params: list[Tensor], grads: list[Tensor], momentum_buffer_list: list[Optional[Tensor]], grad_scale: Optional[Tensor], found_inf: Optional[Tensor], *, weight_decay: float, momentum: float, lr: float, dampening: float, nesterov: bool, maximize: bool, has_sparse_grad: bool):
    if grad_scale is not None or found_inf is not None:
        raise AssertionError('Expected grad_scale and found_inf to be None')
    if <MASK>:
        lr = _to_scalar(lr)
    for (i, param) in enumerate(params):
        grad = grads[i] if not maximize else -grads[i]
        if weight_decay != 0:
            if isinstance(weight_decay, Tensor):
                if weight_decay.requires_grad:
                    grad = grad.addcmul_(param.clone(), weight_decay)
                else:
                    grad = grad.add(param, alpha=weight_decay)
            else:
                grad = grad.add(param, alpha=weight_decay)
        if momentum != 0:
            buf = momentum_buffer_list[i]
            if buf is None:
                buf = grad.detach().clone()
                momentum_buffer_list[i] = buf
            else:
                buf.mul_(momentum).add_(grad, alpha=1 - dampening)
            if nesterov:
                grad = grad.add(buf, alpha=momentum)
            else:
                grad = buf
        if isinstance(lr, Tensor):
            if lr.requires_grad:
                param.addcmul_(grad, lr, value=-1)
            else:
                param.add_(grad, alpha=-lr)
        else:
            param.add_(grad, alpha=-lr)

def skipIfNNModuleInlined(msg="test doesn't currently work with nn module inlining", condition=torch._dynamo.config.inline_inbuilt_nn_modules):

    def decorator(fn):
        if <MASK>:

            @wraps(fn)
            def wrapper(*args, **kwargs):
                if condition:
                    raise unittest.SkipTest(msg)
                else:
                    fn(*args, **kwargs)
            return wrapper
        assert isinstance(fn, type)
        if condition:
            fn.__unittest_skip__ = True
            fn.__unittest_skip_why__ = msg
        return fn
    return decorator

@classmethod
def _from_pylist_of_value(cls, pyval, typespec, path_so_far):
    """Converts python list `pyval` to a Tensor or RaggedTensor with rank>1."""
    if typespec is None:
        try:
            return ragged_factory_ops.constant(pyval)
        except Exception as exc:
            raise ValueError('Error parsing path %r' % (path_so_far,)) from exc
    elif isinstance(typespec, tensor.TensorSpec):
        try:
            result = constant_op.constant(pyval, typespec.dtype)
        except Exception as exc:
            raise ValueError('Error parsing path %r' % (path_so_far,)) from exc
        if not typespec.shape.is_compatible_with(result.shape):
            raise ValueError('Value at %r does not match typespec: %r vs %r' % (path_so_far, typespec, pyval))
        return result
    elif <MASK>:
        try:
            return ragged_factory_ops.constant(pyval, dtype=typespec._dtype, ragged_rank=typespec._ragged_rank, row_splits_dtype=typespec._row_splits_dtype, inner_shape=typespec._shape[typespec._ragged_rank + 1:])
        except Exception as exc:
            raise ValueError('Error parsing path %r' % (path_so_far,)) from exc
    elif isinstance(typespec, StructuredTensor.Spec):
        empty_rank = _pyval_empty_list_depth(pyval)
        if empty_rank is None:
            raise ValueError('Value at %r does not match typespec: %r vs %r' % (path_so_far, typespec, pyval))
        else:
            return cls._from_pylist_of_dict(pyval, set(), empty_rank, typespec, path_so_far)
    else:
        raise ValueError('Value at %r does not match typespec: %r vs %r' % (path_so_far, typespec, pyval))

