def to_numpy_dtype_inference(arr: ExtensionArray, dtype: npt.DTypeLike | None, na_value, hasna: bool) -> tuple[np.dtype | None, Any]:
    result_dtype: np.dtype | None
    inferred_numeric_dtype = False
    if dtype is None and is_numeric_dtype(arr.dtype):
        inferred_numeric_dtype = True
        if hasna:
            if arr.dtype.kind == 'b':
                result_dtype = np.dtype(np.object_)
            else:
                if arr.dtype.kind in 'iu':
                    result_dtype = np.dtype(np.float64)
                else:
                    result_dtype = arr.dtype.numpy_dtype
                if <MASK>:
                    if not is_nan_na():
                        na_value = NA
                        dtype = np.dtype(object)
                    else:
                        na_value = np.nan
        else:
            result_dtype = arr.dtype.numpy_dtype
    elif dtype is not None:
        result_dtype = np.dtype(dtype)
    else:
        result_dtype = None
    if na_value is lib.no_default:
        if result_dtype is None or not hasna:
            na_value = arr.dtype.na_value
        elif result_dtype.kind == 'f':
            na_value = np.nan
        elif result_dtype.kind == 'M':
            na_value = np.datetime64('nat')
        elif result_dtype.kind == 'm':
            na_value = np.timedelta64('nat')
        else:
            na_value = arr.dtype.na_value
    if inferred_numeric_dtype and hasna:
        try:
            np_can_hold_element(result_dtype, na_value)
        except LossySetitemError:
            result_dtype = np.dtype(np.object_)
    return (result_dtype, na_value)

def _get_broadcaster(source_shape, target_shape):
    """Get a _Broadcaster from source_shape to target_shape."""
    if source_shape.dtype != target_shape.dtype:
        raise ValueError('The source and target row_split dtypes should be equal')
    if source_shape.rank is None or target_shape.rank is None:
        raise ValueError('Rank of source and target must be statically known')
    elif source_shape.rank > target_shape.rank:
        raise ValueError('Cannot broadcast to a shape with smaller rank')
    elif source_shape.rank == 0:
        return _Broadcaster(source_shape, target_shape, [])
    elif target_shape.rank == 1:
        assert source_shape.rank == 1
        layer = _LayerBroadcaster.first_layer(source_shape.inner_shape[0], target_shape.inner_shape[0])
        return _Broadcaster(source_shape, target_shape, [layer])
    assert source_shape.rank <= target_shape.rank
    assert target_shape.rank >= 2
    assert source_shape.rank >= 1
    source_rps = source_shape._as_row_partitions()
    target_rps = target_shape._as_row_partitions()
    assert len(target_rps) >= 1
    assert len(source_rps) <= len(target_rps)
    source_nrows = source_shape[0]
    if <MASK>:
        neg_one_source_rp = RowPartition.from_uniform_row_length(uniform_row_length=source_nrows, nrows=1, nvals=source_nrows)
        neg_one_target_rp = target_rps[-(len(source_rps) + 1)]
        neg_one_broadcaster = _LayerBroadcaster.get_singleton_broadcaster(neg_one_target_rp.nrows())
        zeroth_broadcaster = neg_one_broadcaster.next_layer(neg_one_source_rp, neg_one_target_rp)
        target_rps_tail = target_rps[-len(source_rps):] if len(source_rps) >= 1 else []
        layers = _get_layer_broadcasters_from_rps(zeroth_broadcaster, source_rps, target_rps_tail)
        return _Broadcaster(source_shape, target_shape, layers)
    else:
        assert len(target_rps) == len(source_rps)
        zeroth_broadcaster = _LayerBroadcaster.first_layer(source_rps[0].nrows(), target_rps[0].nrows())
        layers = _get_layer_broadcasters_from_rps(zeroth_broadcaster, source_rps, target_rps)
        return _Broadcaster(source_shape, target_shape, layers)

def argument_type_str_pyi(t: Type) -> str:
    add_optional = False
    if isinstance(t, OptionalType):
        t = t.elem
        add_optional = True
    ret = ''
    if isinstance(t, BaseType):
        if t.name in [BaseTy.int, BaseTy.DeviceIndex]:
            ret = '_int'
        if t.name == BaseTy.SymInt:
            ret = '_int | SymInt'
        elif t.name == BaseTy.float:
            ret = '_float'
        elif t.name == BaseTy.str:
            ret = 'str'
        elif <MASK>:
            ret = 'Number | _complex'
        elif t.name == BaseTy.ScalarType:
            ret = '_dtype'
        elif t.name == BaseTy.bool:
            ret = '_bool'
        elif t.name == BaseTy.QScheme:
            ret = '_qscheme'
        elif t.name == BaseTy.Layout:
            ret = '_layout'
        elif t.name == BaseTy.Device:
            ret = 'DeviceLikeType | None'
        elif t.name == BaseTy.MemoryFormat:
            ret = 'memory_format'
        elif t.name == BaseTy.Dimname:
            ret = 'str | EllipsisType | None'
        elif t.name == BaseTy.Storage:
            ret = 'Storage | UntypedStorage'
        elif t.name in [BaseTy.Tensor, BaseTy.Generator, BaseTy.Stream]:
            ret = t.name.name
    elif isinstance(t, ListType):
        if str(t.elem) == 'int':
            ret = '_int | _size' if t.size is not None else '_size'
        elif t.is_tensor_like():
            add_optional = True
            ret = 'Tensor | tuple[Tensor, ...] | list[Tensor]' if t.size is not None else 'tuple[Tensor, ...] | list[Tensor]'
        elif str(t.elem) == 'float':
            ret = 'Sequence[_float]'
        elif str(t.elem) == 'SymInt' and t.size is not None:
            elem = argument_type_str_pyi(t.elem)
            ret = f'{elem} | Sequence[{elem}]'
        else:
            elem = argument_type_str_pyi(t.elem)
            ret = f'Sequence[{elem}]'
    else:
        raise RuntimeError(f'unrecognized type {repr(t)}')
    if add_optional:
        ret = f'{ret} | None'.replace(' | None | None', ' | None')
    return ret

def hierarchical_pickle(data):
    if isinstance(data, (bool, int, float, str, type(None))):
        return data
    if isinstance(data, list):
        return [hierarchical_pickle(d) for d in data]
    if isinstance(data, tuple):
        return {'__tuple_values__': hierarchical_pickle(list(data))}
    if isinstance(data, dict):
        return {'__is_dict__': True, 'keys': hierarchical_pickle(list(data.keys())), 'values': hierarchical_pickle(list(data.values()))}
    if isinstance(data, torch.utils.show_pickle.FakeObject):
        typename = f'{data.module}.{data.name}'
        if typename.startswith(('__torch__.', 'torch.jit.LoweredWrapper.', 'torch.jit.LoweredModule.')):
            if data.args != ():
                raise AssertionError('data.args is not ()')
            return {'__module_type__': typename, 'state': hierarchical_pickle(data.state)}
        if typename == 'torch._utils._rebuild_tensor_v2':
            if <MASK>:
                raise AssertionError('data.state is not None')
            (storage, offset, size, stride, requires_grad, *_) = data.args
            storage_info = get_storage_info(storage)
            return {'__tensor_v2__': [storage_info, offset, size, stride, requires_grad]}
        if typename == 'torch._utils._rebuild_qtensor':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (storage, offset, size, stride, quantizer, requires_grad, *_) = data.args
            storage_info = get_storage_info(storage)
            if not isinstance(quantizer, tuple):
                raise AssertionError('quantizer is not a tuple')
            if not isinstance(quantizer[0], torch.utils.show_pickle.FakeClass):
                raise AssertionError('quantizer[0] is not a FakeClass')
            if quantizer[0].module != 'torch':
                raise AssertionError('quantizer[0].module is not torch')
            if quantizer[0].name == 'per_tensor_affine':
                if len(quantizer) != 3:
                    raise AssertionError('len(quantizer) is not 3')
                if not isinstance(quantizer[1], float):
                    raise AssertionError('quantizer[1] is not a float')
                if not isinstance(quantizer[2], int):
                    raise AssertionError('quantizer[2] is not an int')
                quantizer_extra = list(quantizer[1:3])
            else:
                quantizer_extra = []
            quantizer_json = [quantizer[0].name] + quantizer_extra
            return {'__qtensor__': [storage_info, offset, size, stride, quantizer_json, requires_grad]}
        if typename == 'torch.jit._pickle.restore_type_tag':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (obj, typ) = data.args
            if not isinstance(typ, str):
                raise AssertionError('typ is not a string')
            return hierarchical_pickle(obj)
        if re.fullmatch('torch\\.jit\\._pickle\\.build_[a-z]+list', typename):
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (ls,) = data.args
            if not isinstance(ls, list):
                raise AssertionError('ls is not a list')
            return hierarchical_pickle(ls)
        if typename == 'torch.device':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (name,) = data.args
            if not isinstance(name, str):
                raise AssertionError('name is not a string')
            return name
        if typename == 'builtin.UnicodeDecodeError':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (msg,) = data.args
            if not isinstance(msg, str):
                raise AssertionError('msg is not a string')
            return {'__module_type__': typename, 'state': hierarchical_pickle((msg,))}
        raise Exception(f"Can't prepare fake object of type for JS: {typename}")
    raise Exception(f"Can't prepare data of type for JS: {type(data)}")

def callback(self, op_type, inputs, attrs, outputs, op_name=None, graph=None):
    is_eager = not graph
    if <MASK>:
        self.eager_op_types.append(compat.as_bytes(op_type) if op_type else op_type)
        self.eager_op_names.append(compat.as_bytes(op_name) if op_name else op_name)
        self.eager_attrs.append(attrs)
        self.eager_graphs.append(graph)
        self.eager_inputs.append(inputs)
    else:
        self.graph_op_types.append(compat.as_bytes(op_type) if op_type else op_type)
        self.graph_op_names.append(compat.as_bytes(op_name) if op_name else op_name)
        self.graph_attrs.append(attrs)
        self.graph_graphs.append(graph)
        self.graph_graph_versions.append(graph.version)
        self.graph_inputs.append(inputs)
        if not self.instrument_graph_ops:
            return outputs
        instrumented_outputs = []
        for output in outputs:
            if compat.as_bytes(op_type) in (_ENTER_OP, _EXIT_OP, _IF_OP, _MERGE_OP, _NEXT_ITERATION_OP, _STATELESS_IF_OP, _SWITCH_OP, _WHILE_OP, _IDENTITY_OP, _VAR_HANDLE_OP, _PLACEHOLDER_OP, _CONSTANT_OP):
                instrumented_output = output
            else:

                def record(ndarray_value):
                    if compat.as_bytes(op_name) not in self.graph_internal_ndarrays:
                        self.graph_internal_ndarrays[compat.as_bytes(op_name)] = []
                    self.graph_internal_ndarrays[compat.as_bytes(op_name)].append(ndarray_value)
                    return ndarray_value
                if self._float_only and (not output.dtype.is_floating):
                    instrumented_output = output
                else:
                    instrumented_output = script_ops.numpy_function(record, [output], output.dtype)
                    instrumented_output.set_shape(output.shape)
            instrumented_outputs.append(instrumented_output)
        return instrumented_outputs

