def forward(self, input):
    if len(input.shape) != 3:
        raise ValueError('Input shape must be `(N, C, L)`!')
    if <MASK>:
        _reversed_padding_repeated_twice = _reverse_repeat_padding(self.padding[:1])
        input = F.pad(input, _reversed_padding_repeated_twice, mode=self.padding_mode)
    return torch.ops.quantized.conv1d_relu(input, self._packed_params, self.scale, self.zero_point)

@wraps(func)
def wrapper(*args, **kwargs):
    if <MASK>:
        sys.exit(TEST_SKIPS['odd_worldsize'].exit_code)
    return func(*args, **kwargs)

def fillna(self, value, limit: int | None=None, inplace: bool=False) -> list[Block]:
    """
        fillna on the block with the value. If we fail, then convert to
        block to hold objects instead and try again
        """
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if not self._can_hold_na:
        noop = True
    else:
        mask = isna(self.values)
        (mask, noop) = validate_putmask(self.values, mask)
    if <MASK>:
        return [self.copy(deep=False)]
    if limit is not None:
        mask[mask.cumsum(self.values.ndim - 1) > limit] = False
    if inplace:
        nbs = self.putmask(mask.T, value)
    else:
        nbs = self.where(value, ~mask.T)
    return extend_blocks(nbs)

def __init__(self, ds_input, write=False):
    self._write = 1 if write else 0
    Driver.ensure_registered()
    if <MASK>:
        ds_input = json.loads(ds_input)
    if isinstance(ds_input, (str, Path)):
        ds_input = str(ds_input)
        if not ds_input.startswith(VSI_FILESYSTEM_PREFIX) and (not os.path.exists(ds_input)):
            raise GDALException('Unable to read raster source input "%s".' % ds_input)
        try:
            self._ptr = capi.open_ds(force_bytes(ds_input), self._write)
        except GDALException as err:
            raise GDALException('Could not open the datasource at "{}" ({}).'.format(ds_input, err))
    elif isinstance(ds_input, bytes):
        self._write = 1
        size = sys.getsizeof(ds_input)
        self._ds_input = c_buffer(ds_input)
        vsi_path = os.path.join(VSI_MEM_FILESYSTEM_BASE_PATH, str(uuid.uuid4()))
        capi.create_vsi_file_from_mem_buffer(force_bytes(vsi_path), byref(self._ds_input), size, VSI_TAKE_BUFFER_OWNERSHIP)
        try:
            self._ptr = capi.open_ds(force_bytes(vsi_path), self._write)
        except GDALException:
            capi.unlink_vsi_file(force_bytes(vsi_path))
            raise GDALException('Failed creating VSI raster from the input buffer.')
    elif isinstance(ds_input, dict):
        self._write = 1
        driver = Driver(ds_input.get('driver', 'MEM'))
        if driver.name != 'MEM' and 'name' not in ds_input:
            raise GDALException('Specify name for creation of raster with driver "{}".'.format(driver.name))
        if 'width' not in ds_input or 'height' not in ds_input:
            raise GDALException('Specify width and height attributes for JSON or dict input.')
        if 'srid' not in ds_input:
            raise GDALException('Specify srid for JSON or dict input.')
        papsz_options = []
        for (key, val) in ds_input.get('papsz_options', {}).items():
            option = '{}={}'.format(key, val)
            papsz_options.append(option.upper().encode())
        papsz_options.append(None)
        papsz_options = (c_char_p * len(papsz_options))(*papsz_options)
        self._ptr = capi.create_ds(driver._ptr, force_bytes(ds_input.get('name', '')), ds_input['width'], ds_input['height'], ds_input.get('nr_of_bands', len(ds_input.get('bands', []))), ds_input.get('datatype', 6), byref(papsz_options))
        for (i, band_input) in enumerate(ds_input.get('bands', [])):
            band = self.bands[i]
            if 'nodata_value' in band_input:
                band.nodata_value = band_input['nodata_value']
                if band.nodata_value is not None and ('data' not in band_input or 'size' in band_input or 'shape' in band_input):
                    band.data(data=(band.nodata_value,), shape=(1, 1))
            band.data(data=band_input.get('data'), size=band_input.get('size'), shape=band_input.get('shape'), offset=band_input.get('offset'))
        self.srs = ds_input.get('srid')
        if 'origin' in ds_input:
            (self.origin.x, self.origin.y) = ds_input['origin']
        if 'scale' in ds_input:
            (self.scale.x, self.scale.y) = ds_input['scale']
        if 'skew' in ds_input:
            (self.skew.x, self.skew.y) = ds_input['skew']
    elif isinstance(ds_input, c_void_p):
        self._ptr = ds_input
    else:
        raise GDALException('Invalid data source input type: "{}".'.format(type(ds_input)))

def random_square_matrix_of_rank(l, rank, dtype=torch.double, device='cpu'):
    assert rank <= l
    A = torch.randn(l, l, dtype=dtype, device=device)
    (u, s, vh) = torch.linalg.svd(A, full_matrices=False)
    for i in range(l):
        if i >= rank:
            s[i] = 0
        elif <MASK>:
            s[i] = 1
    return u * s.to(dtype).unsqueeze(-2) @ vh

def observe_garbage(observer):
    enabled = True

    def disable():
        nonlocal enabled
        enabled = False
    atexit.register(disable)

    def gc_callback(phase, info):
        nonlocal enabled
        if not enabled:
            return
        if phase == 'start':
            gc.set_debug(gc.DEBUG_SAVEALL)
        elif phase == 'stop':
            orig_trace = sys.getprofile()
            self_return = [False]

            def do_collect(*args, **kwargs):
                nonlocal enabled
                if not self_return[0]:
                    self_return[0] = True
                else:
                    sys.setprofile(orig_trace)
                    enabled = False
                    try:
                        if info['generation'] != 2:
                            gc.collect()
                        observer(gc.garbage)
                        gc.garbage.clear()
                        gc.set_debug(0)
                        before = torch.cuda.memory_allocated()
                        gc.collect()
                        after = torch.cuda.memory_allocated()
                        if before != after:
                            logger.warning('CUDA Memory changed during GC, %d bytes freed.', before - after)
                    finally:
                        enabled = True
                if <MASK>:
                    return orig_trace(*args, **kwargs)
            sys.setprofile(do_collect)
    gc.callbacks.append(gc_callback)

    def remove():
        gc.callbacks.remove(gc_callback)
    return remove

def restore_variables(self, wrapped, restore_from_saver):
    """Restores variables from the checkpoint."""
    if restore_from_saver is not None:
        (initializer, _) = restore_from_saver(constant_op.constant(self._variables_path))
        if not ops.executing_eagerly_outside_functions():
            ops.add_to_collection('saved_model_initializers', initializer)
            one_unlifted = False
            for variable in wrapped.graph.get_collection_ref(ops.GraphKeys.GLOBAL_VARIABLES):
                if <MASK>:
                    one_unlifted = True
                variable._initializer_op = initializer
            if one_unlifted:
                logging.warning('Some variables could not be lifted out of a loaded function. Please run `sess.run(tf.get_collection("saved_model_initializers"))`to restore these variables.')

def add(self, key: _ConstantAttributeType, value: Any) -> None:
    if isinstance(key, torch.ScriptObject):
        if hash(key) not in self._constant_attrs:
            self._constant_attrs[hash(key)] = []
        self._constant_attrs[hash(key)].append(value)
        self._script_object_map[hash(key)] = key
    elif <MASK>:
        if key not in self._constant_attrs:
            self._constant_attrs[key] = []
        self._constant_attrs[key].append(value)
    else:
        raise TypeError(f'Expected key to be a tensor or ScriptObject, got {type(key)}')

def _replace_child_layer_functions(layer, serialization_cache):
    """Replaces functions in the children layers with wrapped tf.functions.

  This step allows functions from parent layers to reference the wrapped
  functions from their children layers instead of retracing the ops.

  This function also resets all losses stored in the layer. These are stored in
  the returned dictionary. Use `_restore_child_layer_functions` to restore
  the original attributes.

  Args:
    layer: Keras Layer object.
    serialization_cache: Dictionary shared between all objects during
      serialization.

  Returns:
    Dictionary mapping layer objects -> original functions and losses:
      { Child layer 1: {
          'losses': Original losses,
          'call': Original call function
          '_activity_regularizer': Original activity regularizer},
        Child layer 2: ...
      }
  """
    original_fns = {}

    def replace_layer_functions(child_layer, serialized_fns):
        """Replaces layer call and activity regularizer with wrapped functions."""
        original_fns[child_layer] = {'call': child_layer.call, '_activity_regularizer': child_layer._activity_regularizer}
        with utils.no_automatic_dependency_tracking_scope(child_layer):
            try:
                child_layer._activity_regularizer = serialized_fns.get('activity_regularizer_fn')
            except AttributeError:
                pass
            child_layer.call = utils.use_wrapped_call(child_layer, serialized_fns['call_and_return_conditional_losses'], default_training_value=False)

    def replace_metric_functions(child_layer, serialized_fns):
        """Replaces metric functions with wrapped functions."""
        original_fns[child_layer] = {'__call__': child_layer.__call__, 'result': child_layer.result, 'update_state': child_layer.update_state}
        with utils.no_automatic_dependency_tracking_scope(child_layer):
            child_layer.__call__ = serialized_fns['__call__']
            child_layer.result = serialized_fns['result']
            child_layer.update_state = serialized_fns['update_state']
    for child_layer in utils.list_all_layers(layer):
        if isinstance(child_layer, input_layer.InputLayer):
            continue
        if <MASK>:
            serialized_functions = child_layer._trackable_saved_model_saver._get_serialized_attributes(serialization_cache).functions
        else:
            serialized_functions = serialization_cache[constants.KERAS_CACHE_KEY][child_layer].functions
        if not serialized_functions:
            continue
        if isinstance(child_layer, metrics.Metric):
            replace_metric_functions(child_layer, serialized_functions)
        else:
            replace_layer_functions(child_layer, serialized_functions)
    return original_fns

def setitem(self, indexer, value) -> Self:
    """
        Set values with indexer.

        For SingleBlockManager, this backs s[indexer] = value
        """
    if isinstance(indexer, np.ndarray) and indexer.ndim > self.ndim:
        raise ValueError(f'Cannot set values with ndim > {self.ndim}')
    if not self._has_no_reference(0):
        if self.ndim == 2 and isinstance(indexer, tuple):
            blk_loc = self.blklocs[indexer[1]]
            if is_list_like(blk_loc) and blk_loc.ndim == 2:
                blk_loc = np.squeeze(blk_loc, axis=0)
            elif not is_list_like(blk_loc):
                blk_loc = [blk_loc]
            if <MASK>:
                return self.copy(deep=False)
            values = self.blocks[0].values
            if values.ndim == 2:
                values = values[blk_loc]
                self._iset_split_block(0, blk_loc, values)
                indexer = list(indexer)
                if lib.is_integer(indexer[1]):
                    col_indexer = 0
                elif len(blk_loc) > 1:
                    col_indexer = slice(None)
                else:
                    col_indexer = np.arange(len(blk_loc))
                indexer[1] = col_indexer
                row_indexer = indexer[0]
                if isinstance(row_indexer, np.ndarray) and row_indexer.ndim == 2:
                    row_indexer = np.squeeze(row_indexer, axis=1)
                if isinstance(row_indexer, np.ndarray) and len(row_indexer) == 0:
                    return self
                indexer[0] = row_indexer
                self.blocks[0].setitem(tuple(indexer), value)
                return self
        self = self.copy()
    return self.apply('setitem', indexer=indexer, value=value)

def _commastring(astr):
    startindex = 0
    result = []
    islist = False
    while startindex < len(astr):
        mo = format_re.match(astr, pos=startindex)
        try:
            (order1, repeats, order2, dtype) = mo.groups()
        except (TypeError, AttributeError):
            raise ValueError(f'format number {len(result) + 1} of "{astr}" is not recognized') from None
        startindex = mo.end()
        if startindex < len(astr):
            if space_re.match(astr, pos=startindex):
                startindex = len(astr)
            else:
                mo = sep_re.match(astr, pos=startindex)
                if not mo:
                    raise ValueError('format number %d of "%s" is not recognized' % (len(result) + 1, astr))
                startindex = mo.end()
                islist = True
        if <MASK>:
            order = order1
        elif order1 == '':
            order = order2
        else:
            order1 = _convorder.get(order1, order1)
            order2 = _convorder.get(order2, order2)
            if order1 != order2:
                raise ValueError(f'inconsistent byte-order specification {order1} and {order2}')
            order = order1
        if order in ('|', '=', _nbo):
            order = ''
        dtype = order + dtype
        if repeats == '':
            newitem = dtype
        else:
            if repeats[0] == '(' and repeats[-1] == ')' and (repeats[1:-1].strip() != '') and (',' not in repeats):
                warnings.warn('Passing in a parenthesized single number for repeats is deprecated; pass either a single number or indicate a tuple with a comma, like "(2,)".', DeprecationWarning, stacklevel=2)
            newitem = (dtype, ast.literal_eval(repeats))
        result.append(newitem)
    return result if islist else result[0]

def _can_add_to_bucket(self, bucket_info: CollBucket, candidate: fx.Node) -> bool:
    """
        Check if candidate can be added to bucket without interfering
        with comm/compute overlap.
        """
    candidate_info = self.collective_info[candidate]
    candidate_wait = candidate_info.wait_node
    for coll in bucket_info.collectives:
        if self._ancestor_dep(coll, candidate):
            return False
        coll_wait = self.collective_info[coll].wait_node
        if <MASK>:
            return False
        if (hiding_node := self.collective_info[coll].hiding_node):
            if self._ancestor_dep(hiding_node, candidate_wait):
                return False
        if (new_hiding_node := candidate_info.hiding_node):
            if self._ancestor_dep(new_hiding_node, coll_wait):
                return False
    existing_coll = bucket_info.collectives[0]
    if self.aug_graph.has_path(existing_coll, candidate):
        return False
    if self.aug_graph.has_path(candidate, existing_coll):
        return False
    self.aug_graph.merge_to_set(existing_coll, candidate)
    existing_wait = self.collective_info[existing_coll].wait_node
    candidate_wait = candidate_info.wait_node
    if self.aug_graph.has_path(existing_wait, candidate_wait) or self.aug_graph.has_path(candidate_wait, existing_wait):
        self.aug_graph.unmerge_node(candidate)
        return False
    self.aug_graph.merge_to_set(existing_wait, candidate_wait)
    return True

@tf_export.tf_export('experimental.numpy.meshgrid', v1=[])
@np_utils.np_doc('meshgrid')
def meshgrid(*xi, **kwargs):
    """This currently requires copy=True and sparse=False."""
    sparse = kwargs.get('sparse', False)
    if <MASK>:
        raise ValueError(f'Function `meshgrid` does not support returning sparse arrays yet. Received: sparse={sparse}')
    copy = kwargs.get('copy', True)
    if not copy:
        raise ValueError(f'Function `meshgrid` only supports copy=True. Received: copy={copy}')
    indexing = kwargs.get('indexing', 'xy')
    xi = [np_array_ops.asarray(arg) for arg in xi]
    kwargs = {'indexing': indexing}
    outputs = array_ops.meshgrid(*xi, **kwargs)
    return outputs

@classmethod
def instantiate_test(cls, name, test, *, generic_cls=None):

    def instantiate_test_helper(cls, name, *, test, param_kwargs=None, decorator_fn=lambda _: []):
        param_kwargs = {} if param_kwargs is None else param_kwargs
        test_sig_params = inspect.signature(test).parameters
        if 'device' in test_sig_params or 'devices' in test_sig_params:
            device_arg: str = cls._init_and_get_primary_device()
            if hasattr(test, 'num_required_devices'):
                device_arg = cls.get_all_devices()
            _update_param_kwargs(param_kwargs, 'device', device_arg)
        for decorator in decorator_fn(param_kwargs):
            test = decorator(test)

        @wraps(test)
        def instantiated_test(self, param_kwargs=param_kwargs):
            guard_precision = self.precision
            guard_rel_tol = self.rel_tol
            try:
                self._apply_precision_override_for_test(test, param_kwargs)
                result = test(self, **param_kwargs)
            except RuntimeError as rte:
                self._stop_test_suite = self._should_stop_test_suite()
                if <MASK>:
                    import sys
                    print('Suppressing fatal exception to trigger unexpected success', file=sys.stderr)
                    return
                raise rte
            finally:
                self.precision = guard_precision
                self.rel_tol = guard_rel_tol
            return result
        assert not hasattr(cls, name), f'Redefinition of test {name}'
        setattr(cls, name, instantiated_test)

    def default_parametrize_fn(test, generic_cls, device_cls):
        yield (test, '', {}, lambda _: [])
    parametrize_fn = getattr(test, 'parametrize_fn', default_parametrize_fn)
    dtypes = cls._get_dtypes(test)
    if dtypes is not None:

        def dtype_parametrize_fn(test, generic_cls, device_cls, dtypes=dtypes):
            for dtype in dtypes:
                param_kwargs: dict[str, Any] = {}
                _update_param_kwargs(param_kwargs, 'dtype', dtype)
                yield (test, '', param_kwargs, lambda _: [])
        parametrize_fn = compose_parametrize_fns(dtype_parametrize_fn, parametrize_fn)
    for (test, test_suffix, param_kwargs, decorator_fn) in parametrize_fn(test, generic_cls, cls):
        test_suffix = '' if test_suffix == '' else '_' + test_suffix
        cls_device_type = cls.device_type if cls.device_type != 'privateuse1' else torch._C._get_privateuse1_backend_name()
        device_suffix = '_' + cls_device_type
        dtype_kwarg = None
        if 'dtype' in param_kwargs or 'dtypes' in param_kwargs:
            dtype_kwarg = param_kwargs['dtypes'] if 'dtypes' in param_kwargs else param_kwargs['dtype']
        test_name = f'{name}{test_suffix}{device_suffix}{_dtype_test_suffix(dtype_kwarg)}'
        instantiate_test_helper(cls=cls, name=test_name, test=test, param_kwargs=param_kwargs, decorator_fn=decorator_fn)

@method_with_native_function
def gen_one(self, f: NativeFunction) -> str | None:
    assert not f.manual_kernel_registration
    if self.target is Target.REGISTRATION and (not self.selector.is_native_function_selected(f)):
        return None
    if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional and f.func.kind() is SchemaKind.out:
        return None
    cpp_sig_group = CppSignatureGroup.from_native_function(f, method=False, fallback_binding=False)
    kern = self.backend_index.get_kernel(f)
    sig = NativeSignature(f.func, prefix=f'wrapper_{self.backend_index.dispatch_key}_', symint=kern is not None and kern.supports_symint())
    if self.target is Target.NAMESPACED_DECLARATION:
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += f'TORCH_API {cpp_sig.decl()};\n'
        return result
    elif self.target is Target.NAMESPACED_DEFINITION:

        def generate_defn(cpp_sig: CppSignature) -> str:
            return f"\n{cpp_sig.defn()} {{\nreturn {sig.name()}({', '.join((e.expr for e in translate(cpp_sig.arguments(), sig.arguments())))});\n}}\n"
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += generate_defn(cpp_sig)
        return result
    elif self.target is Target.ANONYMOUS_DEFINITION:
        k = f.func.kind()
        sig_body = []
        context: list[Binding | Expr] = list(sig.arguments())
        if self.backend_index.dispatch_key is DispatchKey.Meta:
            class_name = f'structured_{meta.name(self.g)}_meta_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        elif self.backend_index.dispatch_key is DispatchKey.CompositeExplicitAutogradNonFunctional:
            class_name = f'structured_{meta.name(self.g)}_default_backend_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        else:
            metadata = self.backend_index.get_kernel(self.g)
            assert metadata is not None
            class_name = f'structured_{metadata.kernel}_{k.name}'
            parent_class = f'{metadata.cpp_namespace}::structured_{metadata.kernel}'
        if self.backend_index.device_guard:
            device_check_args = itertools.chain(f.func.arguments.out, f.func.arguments.flat_positional)
            sig_body.append(RegisterDispatchKey.gen_device_check(f.device_check, list(device_check_args), sig.name()))
        if k is SchemaKind.functional:
            sig_body.append(f'{class_name} op;')
        elif k is SchemaKind.inplace:
            sig_body.append(f'{class_name} op(self);')
        elif k is SchemaKind.out:
            out_args_str = ', '.join((a.name for a in f.func.arguments.out))
            sig_body.append(f'{class_name} op({out_args_str});')
        meta_exprs = ', '.join((e.expr for e in translate(context, structured.meta_arguments(self.g), method=False)))
        if self.g.out.precomputed:
            sig_body.append(f'auto precompute = op.meta({meta_exprs});')
            precomputed_values = [*self.g.out.precomputed.replace.values(), self.g.out.precomputed.add]
            for precomputed_elems in precomputed_values:
                context.extend((Expr(expr=f'precompute.{arg.name}', type=structured.argument_type(arg, binds=arg.name)) for arg in precomputed_elems))
            sig_body.append('(void)precompute;')
        else:
            sig_body.append(f'op.meta({meta_exprs});')
        out_args = structured.out_arguments(self.g)
        for (i, out_arg) in enumerate(out_args):
            assert ConstRefCType(BaseCType(tensorT)) == out_arg.nctype.type
            if k is SchemaKind.out:
                expr = f'op.maybe_get_output({i})'
            else:
                expr = f'op.outputs_[{i}]'
            context.append(Expr(expr=expr, type=NamedCType(out_arg.nctype.name, MutRefCType(BaseCType(tensorT)))))
        if <MASK>:
            out_sig_group = CppSignatureGroup.from_native_function(self.g.out, method=False, fallback_binding=f.manual_cpp_binding)
            out_sig = out_sig_group.most_faithful_signature()
            api_name = out_sig.name()
            out_exprs = ', '.join((e.expr for e in translate(context, out_sig.arguments(), method=False)))
            sig_body.append(f'at::{api_name}({out_exprs});')
        elif self.backend_index.dispatch_key != DispatchKey.Meta:
            impl_exprs = ', '.join((e.expr for e in translate(context, structured.impl_arguments(self.g), method=False)))
            sig_body.append(f'op.impl({impl_exprs});')
        if k is SchemaKind.out or k is SchemaKind.inplace:
            for i in range(len(f.func.returns)):
                sig_body.append(f'if (op.proxy_outputs_[{i}].has_value()) op.outputs_[{i}].get().copy_(*op.proxy_outputs_[{i}]);')
        if k is SchemaKind.functional:
            if len(f.func.returns) == 1:
                ret_expr = 'std::move(op.outputs_[0])'
            else:
                moved = ', '.join((f'std::move(op.outputs_[{i}])' for i in range(len(f.func.returns))))
                ret_expr = f'std::make_tuple({moved})'
        elif k is SchemaKind.inplace:
            ret_expr = 'self'
        elif k is SchemaKind.out:
            if len(f.func.returns) == 1:
                ret_expr = f.func.arguments.out[0].name
            else:
                refs = ', '.join((a.name for a in f.func.arguments.out))
                ret_expr = f'std::forward_as_tuple({refs})'
        sig_body.append(f'return {ret_expr};')
        sig_body_str = '\n'.join(sig_body)
        return f'{self.gen_class(f, k, class_name=class_name, parent_class=parent_class, generate_super=self.g.out.structured_inherits is not None)}\n\n{sig.defn()} {{\n{sig_body_str}\n}}\n'
    elif self.target is Target.REGISTRATION:
        return f'm.impl("{f.func.name}", TORCH_FN({sig.name()}));'
    else:
        assert_never(self.target)
        return None

def validate_failures_dict_structure(failure_dict: 'FailuresDict', test_utils: list[str], testcase: Any) -> None:
    """Validates the failures dict.

    The failure dict looks something like the following.
    It maps operator name (qualname) to a list of autogenerated tests.
    Each autogenerated test may have a check for the operator (if the operator is
    called by the test); the dictionary specifies if we should skip the check,
    or if we expect some check to fail.

    {
        "fbgemm::split_lengths": {
            "test_schema__test_split_lengths": {
                "comment": "you can put whatever you want into the comment section",
                "status": "xfail",
            }
            "test_schema__test_split_lengths_empty": {
                "comment": "",
                "status": "skip",
            },
        },
        "fbgemm::gather_lengths": {
            "test_schema__test_gather_lengths": {
                "comment": "",
                "status": "skip",
            },
        },
    }

    """
    failure_dict = failure_dict.data
    for test_to_option in failure_dict.values():
        for (test_name, test_dict) in test_to_option.items():
            if set(test_dict.keys()) != set({'comment', 'status'}):
                raise RuntimeError("in failures_dict, expected sub-dict to have keys 'comment' and 'status'")
            test_option = test_dict['status']
            if test_option not in TEST_OPTIONS:
                raise RuntimeError(f'In failures_dict, got status={test_option} but it needs to be in {TEST_OPTIONS}')
            (test_class, actual_test_name) = test_name.split('.')
            if not any((actual_test_name.startswith(test) for test in test_utils)):
                raise RuntimeError(f"In failures_dict, test name '{test_name}' should begin with one of {test_utils}")
            for test in test_utils:
                if <MASK>:
                    continue
                base_test_name = actual_test_name[len(test) + 2:]
                base_test_name = re.sub('\\[.*\\]', '', base_test_name)
                if testcase.__name__ != test_class:
                    continue
                if hasattr(testcase, base_test_name):
                    continue
                raise RuntimeError(f"In failures dict, got test name '{test_name}'. We parsed this as running test '{test}' on '{base_test_name}', but {base_test_name} does not exist on the TestCase '{testcase.__name__}]. Maybe you need to change the test name?")

def saveable_objects_for_op(op, name):
    """Create `SaveableObject`s from an operation.

  Args:
    op: A variable, operation, or SaveableObject to coerce into a
      SaveableObject.
    name: A string name for the SaveableObject.

  Yields:
    `SaveableObject`s which together save/restore `op`.

  Raises:
    TypeError: If `name` is not a string.
    ValueError: For operations with no known conversion to SaveableObject.
  """
    if not isinstance(name, str):
        raise TypeError(f'names_to_saveables must be a dict mapping string names to trackable operations. Name is not a string: {name}')
    if isinstance(op, saveable_object.SaveableObject):
        yield op
    elif isinstance(op, (list, tuple, variables.PartitionedVariable)):
        if isinstance(op, variables.PartitionedVariable):
            op = list(op)
        slice_name = None
        for variable in op:
            if isinstance(variable, saveable_object.SaveableObject):
                yield variable
                continue
            if <MASK>:
                raise ValueError(f'Slices must all be Variables: {variable}')
            if not variable._save_slice_info:
                raise ValueError(f'Slices must all be slices: {variable}')
            if slice_name is None:
                slice_name = variable._save_slice_info.full_name
            elif slice_name != variable._save_slice_info.full_name:
                raise ValueError(f'Slices must all be from the same tensor: {slice_name} != {variable._save_slice_info.full_name}')
            if variable.op.type in _REF_VARIABLE_OPS:
                yield ReferenceVariableSaveable(variable, variable._save_slice_info.spec, name)
            else:
                yield ResourceVariableSaveable(variable, variable._save_slice_info.spec, name)
    elif isinstance(op, trackable.Trackable) and (not isinstance(op, variables.Variable)):
        for (attr, factory) in saveable_objects_from_trackable(op, tf1_saver=True).items():
            if attr == trackable.VARIABLE_VALUE_KEY:
                full_name = name
            elif attr == trackable_utils.SERIALIZE_TO_TENSORS_NAME:
                full_name = name
            else:
                full_name = name + '_' + attr
            op = factory(full_name) if callable(factory) else factory
            for op in saveable_objects_for_op(op, op.name):
                yield op
    elif isinstance(op, resource_variable_ops.BaseResourceVariable):
        if op._in_graph_mode:
            variable = op._graph_element
        else:
            variable = op
        yield ResourceVariableSaveable(variable, '', name)
    else:
        if context.executing_eagerly():
            raise ValueError(f'Can only save/restore ResourceVariables when executing eagerly, got type: {type(op)}.')
        variable = ops.convert_to_tensor(op, as_ref=True)
        if not _tensor_comes_from_variable(variable):
            raise TypeError(f'names_to_saveables must be a dict mapping string names to Tensors/Variables. Not a variable: {variable}')
        if variable.op.type in _REF_VARIABLE_OPS:
            yield ReferenceVariableSaveable(variable, '', name)
        else:
            yield ResourceVariableSaveable(variable, '', name)

@parameterized.parameters(*itertools.product((False, True), (False, True), (False, True), (False, True), (False, True)))
def testResourceHandlingInLoop(self, read_before, read_after, modify_in_loop, modify_before, modify_after):
    if not tf2.enabled():
        self.skipTest('V2-only test.')
    ticker = variables.Variable(0)

    @def_function.function
    def run_loop(n):
        ticker.assign(0)
        i = constant_op.constant(0)
        t_acc = tensor_array_ops.TensorArray(dtypes.int32, size=0, dynamic_size=True)
        if <MASK>:
            rb = ticker.read_value()
        else:
            rb = constant_op.constant(0)
        if modify_before:
            ticker.assign_add(1)
        while i < n:
            directives.set_loop_options(parallel_iterations=10)
            if modify_in_loop:
                ticker.assign_add(1)
            t_acc = t_acc.write(i, ticker.read_value())
            i += 1
        if read_after:
            ra = ticker.read_value()
        else:
            ra = constant_op.constant(0)
        if modify_after:
            ticker.assign_add(1)
        return (t_acc.stack(), rb, ra)
    self.evaluate(run_loop(1))
    self.evaluate(ticker.assign(123))
    (acc, rb, ra) = run_loop(3)
    self.assertEqual(self.evaluate(math_ops.reduce_max(acc)), int(modify_before) + 3 * int(modify_in_loop))
    self.assertEqual(self.evaluate(rb), 0)
    if read_after:
        expected_ra = int(modify_before) + 3 * int(modify_in_loop)
    else:
        expected_ra = 0
    self.assertEqual(self.evaluate(ra), expected_ra)
    self.assertEqual(self.evaluate(ticker.read_value()), int(modify_before) + 3 * int(modify_in_loop) + int(modify_after))

def change_aliases(self, change_map):
    """
        Change the aliases in change_map (which maps old-alias -> new-alias),
        relabelling any references to them in select columns and the where
        clause.
        """
    if not change_map:
        return self
    assert set(change_map).isdisjoint(change_map.values())
    self.where.relabel_aliases(change_map)
    if <MASK>:
        self.group_by = tuple([col.relabeled_clone(change_map) for col in self.group_by])
    self.select = tuple([col.relabeled_clone(change_map) for col in self.select])
    self.annotations = self.annotations and {key: col.relabeled_clone(change_map) for (key, col) in self.annotations.items()}
    for (old_alias, new_alias) in change_map.items():
        if old_alias not in self.alias_map:
            continue
        alias_data = self.alias_map[old_alias].relabeled_clone(change_map)
        self.alias_map[new_alias] = alias_data
        self.alias_refcount[new_alias] = self.alias_refcount[old_alias]
        del self.alias_refcount[old_alias]
        del self.alias_map[old_alias]
        table_aliases = self.table_map[alias_data.table_name]
        for (pos, alias) in enumerate(table_aliases):
            if alias == old_alias:
                table_aliases[pos] = new_alias
                break
    self.external_aliases = {change_map.get(alias, alias): aliased or alias in change_map for (alias, aliased) in self.external_aliases.items()}
    for combined_query in self.combined_queries:
        external_change_map = {alias: aliased for (alias, aliased) in change_map.items() if alias in combined_query.external_aliases}
        combined_query.change_aliases(external_change_map)

def is_functional_schema(schema: Any, *, allow_valid_view: bool=False) -> bool:
    """Check if the schema is functional.

    An operator is functional if:
    - it does not mutate any of its inputs
    - If no view are allowed
        - it does not return a view on any of its inputs
    - If valid views are allowed
        - it is not a view or a view with a single input Tensor and single output Tensor
    - it has at least one return
    """

    def is_functional(schema):
        if schema.is_mutable:
            return False
        rets = schema.returns
        is_non_mutating_view = len(rets) > 0 and any((r.alias_info is not None and (not r.alias_info.is_write) for r in rets))
        num_tensor_inputs = 0
        num_tensor_outputs = 0
        if isinstance(schema, torch.FunctionSchema):
            for arg in schema.arguments:
                if isinstance(arg.type, torch.TensorType):
                    num_tensor_inputs += 1
            for ret in schema.returns:
                if isinstance(ret.type, torch.TensorType):
                    num_tensor_outputs += 1
        elif isinstance(schema, torchgen.model.FunctionSchema):
            for argument in schema.arguments.flat_non_out:
                if <MASK>:
                    num_tensor_inputs += 1
            for ret_arg in schema.returns:
                if ret_arg.type.is_tensor_like():
                    num_tensor_outputs += 1
        if is_non_mutating_view:
            return allow_valid_view and (num_tensor_inputs == 1 and num_tensor_outputs == 1)
        if not schema.returns:
            return False
        return True
    if isinstance(schema, torch._C.FunctionSchema):
        return is_functional(schema)
    from torchgen.model import FunctionSchema
    if isinstance(schema, str):
        schema = FunctionSchema.parse(schema)
    assert isinstance(schema, FunctionSchema)
    return is_functional(schema)

def _setitem(self, idx, value):
    if not isinstance(idx, (int, slice)):
        raise RuntimeError(f"can't index a {type(self)} with {type(idx)}")
    if <MASK>:
        raise RuntimeError(f'cannot set item with value type {type(value)}')
    if self.dtype in [torch.quint8, torch.quint4x2, torch.quint2x4, torch.qint32, torch.qint8]:
        interpret_dtypes = {torch.quint8: torch.uint8, torch.quint4x2: torch.uint8, torch.quint2x4: torch.uint8, torch.qint32: torch.int32, torch.qint8: torch.int8}
        tmp_dtype = interpret_dtypes[self.dtype]
        tmp_tensor = torch.tensor([], dtype=tmp_dtype, device=self._untyped_storage.device)
        tmp_tensor.set_(TypedStorage(wrap_storage=self._untyped_storage, dtype=tmp_dtype, _internal=True))
    else:
        tmp_tensor = torch.tensor([], dtype=self.dtype, device=self._untyped_storage.device).set_(self)
    tmp_tensor[idx] = value

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    from . import ConstantVariable, UserMethodVariable
    method = self._maybe_get_baseclass_method(name)
    if method is not None:
        if method is object.__init__:
            return ConstantVariable.create(None)
        if is_standard_setattr(method) or isinstance(self.value, threading.local):
            return self.method_setattr_standard(tx, *args, **kwargs)
        if is_standard_delattr(method):
            return self.method_setattr_standard(tx, args[0], variables.DeletedVariable())
        if method is object.__eq__ and len(args) == 1 and (not kwargs):
            other = args[0]
            if <MASK>:
                return variables.ConstantVariable.create(NotImplemented)
            return ConstantVariable.create(self.value is other.value)
        if torch._dynamo.config.enable_faithful_generator_behavior and isinstance(self.value, types.GeneratorType):
            unimplemented_v2(gb_type='call_method on generator', context=f'object={self.value}, method={name}, args={args}, kwargs={kwargs}', explanation='Detected a method call to a user-defined generator object. This is not fully supported.', hints=['Set `torch._dynamo.config.enable_faithful_generator_behavior = False`. Note that this may cause silent incorrectness, since we will eagerly unpack generators instead of lazily evaluating them.'])
        if isinstance(method, types.FunctionType):
            source = self.source
            source_fn = None
            if source:
                source_fn = self.get_source_by_walking_mro(name)
            from ..mutation_guard import unpatched_nn_module_init
            if method is torch.nn.Module.__init__:
                method = unpatched_nn_module_init
            return UserMethodVariable(method, self, source_fn=source_fn, source=source).call_function(tx, args, kwargs)
        if method is list.__len__ and self.source and (not (args or kwargs)):
            install_guard(self.source.make_guard(GuardBuilder.SEQUENCE_LENGTH))
            return ConstantVariable(len(self.value))
    return super().call_method(tx, name, args, kwargs)

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    storages = set()
    na_values = set()
    for dtype in dtypes:
        if isinstance(dtype, StringDtype):
            storages.add(dtype.storage)
            na_values.add(dtype.na_value)
        elif <MASK>:
            continue
        else:
            return None
    if len(storages) == 2:
        storage = 'pyarrow'
    else:
        storage = next(iter(storages))
    na_value: libmissing.NAType | float
    if len(na_values) == 2:
        na_value = libmissing.NA
    else:
        na_value = next(iter(na_values))
    return StringDtype(storage=storage, na_value=na_value)

def get_runner_prefix(rollout_state: str, workflow_requestors: Iterable[str], branch: str, eligible_experiments: frozenset[str]=frozenset(), opt_out_experiments: frozenset[str]=frozenset(), is_canary: bool=False) -> str:
    settings = parse_settings(rollout_state)
    user_optins = parse_users(rollout_state)
    fleet_prefix = ''
    prefixes = []
    for (experiment_name, experiment_settings) in settings.experiments.items():
        if not experiment_settings.all_branches and is_exception_branch(branch):
            log.info(f'Branch {branch} is an exception branch. Not enabling experiment {experiment_name}.')
            continue
        if opt_out_experiments:
            if experiment_name in opt_out_experiments:
                opt_out_exp_list = ', '.join(opt_out_experiments)
                log.info(f"Skipping experiment '{experiment_name}', as this workflow has opted-out (opted out experiments are: {opt_out_exp_list})")
                continue
        if <MASK>:
            if experiment_name not in eligible_experiments:
                exp_list = ', '.join(eligible_experiments)
                log.info(f"Skipping experiment '{experiment_name}', as it is not in the eligible_experiments list: {exp_list}")
                continue
        elif not experiment_settings.default:
            log.info(f"Skipping experiment '{experiment_name}', as it is not a default experiment")
            continue
        opted_out_users = [requestor for requestor in workflow_requestors if is_user_opted_out(requestor, user_optins, experiment_name)]
        if opted_out_users:
            log.info(f"{', '.join(opted_out_users)} have opted out of experiment {experiment_name}.")
            continue
        opted_in_users = [requestor for requestor in workflow_requestors if is_user_opted_in(requestor, user_optins, experiment_name)]
        enabled = False
        if opted_in_users:
            log.info(f"{', '.join(opted_in_users)} have opted into experiment {experiment_name}.")
            enabled = True
        elif experiment_settings.rollout_perc:
            if random.uniform(0, 100) <= experiment_settings.rollout_perc:
                log.info(f'Based on rollout percentage of {experiment_settings.rollout_perc}%, enabling experiment {experiment_name}.')
                enabled = True
        if enabled:
            label = experiment_name
            if experiment_name == LF_FLEET_EXPERIMENT:
                if is_canary:
                    label += CANARY_FLEET_SUFFIX
                fleet_prefix = label
            else:
                prefixes.append(label)
    if len(prefixes) > 1:
        log.error(f"Only a fleet and one other experiment can be enabled for a job at any time. Enabling {prefixes[0]} and ignoring the rest, which are {', '.join(prefixes[1:])}")
        prefixes = prefixes[:1]
    if fleet_prefix:
        prefixes.insert(0, fleet_prefix)
    return '.'.join(prefixes) + '.' if prefixes else ''

@_onnx_symbolic('aten::pad')
def pad(g: jit_utils.GraphContext, input: _C.Value, pad: _C.Value, mode: _C.Value, value: _C.Value):
    mode = symbolic_helper._parse_arg(mode, 's')
    if mode == 'replicate':
        return replication_pad(g, input, pad)
    elif mode == 'reflect':
        return reflection_pad(g, input, pad)
    elif <MASK>:
        return constant_pad_nd(g, input, pad, value)
    elif mode == 'circular':
        return _pad_circular(g, input, pad)
    else:
        raise errors.SymbolicValueError(f'Unrecognized padding mode {mode}', input)

def make_type_checker(annotation):
    """Builds a PyTypeChecker for the given type annotation."""
    if type_annotations.is_generic_union(annotation):
        type_args = type_annotations.get_generic_type_args(annotation)
        simple_types = [t for t in type_args if isinstance(t, type)]
        simple_types = tuple(sorted(simple_types, key=id))
        if len(simple_types) > 1:
            if simple_types not in _is_instance_checker_cache:
                checker = _api_dispatcher.MakeInstanceChecker(*simple_types)
                _is_instance_checker_cache[simple_types] = checker
            options = [_is_instance_checker_cache[simple_types]] + [make_type_checker(t) for t in type_args if not isinstance(t, type)]
            return _api_dispatcher.MakeUnionChecker(options)
        options = [make_type_checker(t) for t in type_args]
        return _api_dispatcher.MakeUnionChecker(options)
    elif type_annotations.is_generic_list(annotation):
        type_args = type_annotations.get_generic_type_args(annotation)
        if len(type_args) != 1:
            raise AssertionError('Expected List[...] to have a single type parameter')
        elt_type = make_type_checker(type_args[0])
        return _api_dispatcher.MakeListChecker(elt_type)
    elif isinstance(annotation, type):
        if annotation not in _is_instance_checker_cache:
            checker = _api_dispatcher.MakeInstanceChecker(annotation)
            _is_instance_checker_cache[annotation] = checker
        return _is_instance_checker_cache[annotation]
    elif <MASK>:
        return make_type_checker(type(None))
    else:
        raise ValueError(f'Type annotation {annotation} is not currently supported by dispatch.  Supported annotations: type objects,  List[...], and Union[...]')

@register_decomposition(aten.hardtanh)
@_inplace_wrapper
@out_wrapper()
@elementwise_unary_scalar_wrapper
@elementwise_type_promotion_wrapper(type_promoting_args='a', type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
def hardtanh(a: TensorLikeType, min_val: NumberType=-1, max_val: NumberType=1, inplace: bool=False) -> TensorLikeType:
    """
    Reference implementation of torch.nn.functional.hardtanh
    """
    if inplace:
        raise NotImplementedError
    if utils.is_boolean_dtype(a.dtype):
        raise RuntimeError('Bool inputs not supported for hardtanh')
    if utils.is_integer_dtype(a.dtype):
        min_val = int(min_val)
        max_val = int(max_val)
        if not (a.dtype != torch.uint8 or (min_val >= 0 and max_val >= 0)):
            raise RuntimeError('Cannot do hardtanh on an unsigned type with negative limits')
    if <MASK>:
        raise ValueError('min_val cannot be greater than max_val')
    return torch.clamp(a, min_val, max_val)

def _convert(ret, cls):
    if <MASK>:
        return ret
    if isinstance(ret, Tensor) and (not isinstance(ret, cls)):
        ret = ret.as_subclass(cls)
    if isinstance(ret, (tuple, list)):
        ret = type(ret)((_convert(r, cls) for r in ret))
    return ret

def reorder_columns(ldesc: Sequence[Series]) -> list[Hashable]:
    """Set a convenient order for rows for display."""
    names: list[Hashable] = []
    seen_names: set[Hashable] = set()
    ldesc_indexes = sorted((x.index for x in ldesc), key=len)
    for idxnames in ldesc_indexes:
        for name in idxnames:
            if <MASK>:
                seen_names.add(name)
                names.append(name)
    return names

