@custom_gradient.custom_gradient
def _identity_with_grad_check(x):
    """Function that asserts it's gradient has a certain value."""
    x = array_ops.identity(x)

    def grad(dx):
        """Gradient function that asserts the gradient has a certain value."""
        if <MASK>:
            assert dx.dtype == expected_dtype, 'dx.dtype should be %s but is: %s' % (expected_dtype, dx.dtype)
        expected_tensor = tensor_conversion.convert_to_tensor_v2_with_dispatch(expected_gradient, dtype=dx.dtype, name='expected_gradient')
        with ops.control_dependencies([x]):
            assert_op = check_ops.assert_equal(dx, expected_tensor)
        with ops.control_dependencies([assert_op]):
            dx = array_ops.identity(dx)
        return dx
    return (x, grad)

def get_choice(self) -> Choice:
    """
        Returns the chosen option based on the value of autoheuristic_use.
        If self.name is one of the comma separated strings in autoheuristic_use,
        it queries a learned heuristic to make a decision. Otherwise, it returns the fallback option.
        """
    if not self.satisfies_precondition():
        return self.fallback()
    if torch._inductor.config.use_autoheuristic(self.name):
        if self.augment_context is not None:
            self.context.apply_operations(self.augment_context)
        controller = LearnedHeuristicController(self.metadata, self.context)
        decision = controller.get_decision()
        if decision not in self.choices:
            return self.fallback()
        if <MASK>:
            return decision
    return self.fallback()

def remove_spectral_norm(module: T_module, name: str='weight') -> T_module:
    """Remove the spectral normalization reparameterization from a module.

    Args:
        module (Module): containing module
        name (str, optional): name of weight parameter

    Example:
        >>> m = spectral_norm(nn.Linear(40, 10))
        >>> remove_spectral_norm(m)
    """
    for (k, hook) in module._forward_pre_hooks.items():
        if isinstance(hook, SpectralNorm) and hook.name == name:
            hook.remove(module)
            del module._forward_pre_hooks[k]
            break
    else:
        raise ValueError(f"spectral_norm of '{name}' not found in {module}")
    for (k, hook) in module._state_dict_hooks.items():
        if isinstance(hook, SpectralNormStateDictHook) and hook.fn.name == name:
            del module._state_dict_hooks[k]
            break
    for (k, hook) in module._load_state_dict_pre_hooks.items():
        if <MASK>:
            del module._load_state_dict_pre_hooks[k]
            break
    return module

