def start_trace(self) -> None:
    if self.execution_trace_observer:
        self.execution_trace_observer.start()
    assert self.profiler is not None
    self.profiler._start_trace()
    if self.profile_memory:
        self.add_metadata_json('profile_memory', '1')
    if self.with_stack:
        self.add_metadata_json('with_stack', '1')
    if self.record_shapes:
        self.add_metadata_json('record_shapes', '1')
    if self.with_modules:
        self.add_metadata_json('with_modules', '1')
    if self.with_flops:
        self.add_metadata_json('with_flops', '1')
    if <MASK>:
        dist_info = self._get_distributed_info()
        if dist_info:
            self.add_metadata_json('distributedInfo', json.dumps(dist_info, cls=_NumpyEncoder))
        cuda_version = None
        if hasattr(torch, 'version'):
            from torch.torch_version import TorchVersion
            cuda_version = TorchVersion(getattr(torch.version, 'cuda', '0.0'))
        if self.has_cudagraphs and (cuda_version and cuda_version < '12.6' or not profiler_allow_cudagraph_cupti_lazy_reinit_cuda12()):
            os.environ['DISABLE_CUPTI_LAZY_REINIT'] = '1'
            self.add_metadata_json('DISABLE_CUPTI_LAZY_REINIT', '1')
            os.environ['TEARDOWN_CUPTI'] = '0'
        for (k, v) in self.preset_metadata.items():
            self.add_metadata_json(k, v)

@functools.lru_cache(32)
def get_alignments(torch_dtype: torch.dtype) -> list[int]:
    """
    Returns all possible valid CUTLASS alignments in terms of the number of elements for a given dtype.
    CUTLASS gemm / conv SM80 APIs support 16 bytes max alignment, and 2 bytes min alignment.
    """
    if torch_dtype in (torch.half, torch.bfloat16):
        return [8, 4, 2, 1]
    elif torch_dtype == torch.float:
        return [4, 2, 1]
    elif torch_dtype in (torch.uint8, torch.int8, torch.float8_e4m3fn):
        return [16, 8, 4, 2]
    elif <MASK>:
        return [4, 2, 1]
    else:
        raise NotImplementedError(f'unsupported torch_dtype={torch_dtype!r} for alignments')

def check_dtype(buffer: IndentedBuffer, var: CSEVariableType, dtype: torch.dtype) -> None:
    backend = get_current_backend()
    if config.test_configs.runtime_triton_dtype_assert and backend == 'triton':
        buffer.writeline(f'tl.static_assert({var}.dtype == {triton_type(dtype)})')
    elif config.test_configs.static_cpp_dtype_assert and backend == 'cpp':
        from .cpp_utils import CppCSEVariable, DTYPE_TO_CPP
        assert isinstance(var, CppCSEVariable), type(var)
        if dtype == torch.bool:
            if <MASK>:
                is_same_dt = f'IsVecMaskType<decltype({var})>::value'
            else:
                is_same_dt = f'std::is_same_v<decltype({var}), bool> || std::is_same_v<decltype({var}), int>'
        else:
            c_var_type = f'decltype({var})'
            if var.is_vec:
                c_var_type = f'typename {c_var_type}::value_type'
            is_same_dt = f'std::is_same_v<{c_var_type}, {DTYPE_TO_CPP[dtype]}>'
        buffer.writeline(f'static_assert({is_same_dt});')

