def _sample_inputs_sparse(sample_inputs, maybe_failing_sample_inputs, validate_sample_input, op_info, *args, **kwargs):
    check_validate = os.environ.get('PYTORCH_TEST_CHECK_VALIDATE_SPARSE_SAMPLES', '0') == '1'
    for sample in sample_inputs(op_info, *args, **kwargs):
        sample = validate_sample_input(op_info, sample, check_validate=check_validate)
        if <MASK>:
            yield sample
    for sample in maybe_failing_sample_inputs(op_info, *args, **kwargs):
        sample = validate_sample_input(op_info, sample, check_validate=check_validate)
        if isinstance(sample, SampleInput):
            yield sample

def _dtype_test_suffix(dtypes):
    """Returns the test suffix for a dtype, sequence of dtypes, or None."""
    if isinstance(dtypes, (list, tuple)):
        if <MASK>:
            return ''
        return '_' + '_'.join((dtype_name(d) for d in dtypes))
    elif dtypes:
        return f'_{dtype_name(dtypes)}'
    else:
        return ''

def cracktypespec0(typespec, ll):
    selector = None
    attr = None
    if re.match('double\\s*complex', typespec, re.I):
        typespec = 'double complex'
    elif re.match('double\\s*precision', typespec, re.I):
        typespec = 'double precision'
    else:
        typespec = typespec.strip().lower()
    m1 = selectpattern.match(markouterparen(ll))
    if <MASK>:
        outmess('cracktypespec0: no kind/char_selector pattern found for line.\n')
        return
    d = m1.groupdict()
    for k in list(d.keys()):
        d[k] = unmarkouterparen(d[k])
    if typespec in ['complex', 'integer', 'logical', 'real', 'character', 'type']:
        selector = d['this']
        ll = d['after']
    i = ll.find('::')
    if i >= 0:
        attr = ll[:i].strip()
        ll = ll[i + 2:]
    return (typespec, selector, attr, ll)

def can_fuse(self, node1, node2):
    """
        Hook called by Scheduler to determine if the Triton backend
        can fuse node1 and node2.  These nodes might already be
        FusedSchedulerNodes.
        """
    if isinstance(node1, scheduler.ForeachKernelSchedulerNode) or isinstance(node2, scheduler.ForeachKernelSchedulerNode):
        return scheduler.ForeachKernelSchedulerNode.can_fuse(node1, node2)
    (_, (numel1, rnumel1)) = node1.group
    (_, (numel2, rnumel2)) = node2.group
    why = WhyNoFuse(node1, node2)
    if <MASK>:
        if node2.is_reduction():
            why('Split scan cannot fuse with reductions')
    elif node2.is_split_scan() and (not node1.is_split_scan()):
        if node1.is_reduction():
            why('Split scan cannot fuse with reductions')
    if node1.is_reduction() and node2.is_reduction():
        reduction_can_fuse = numel1 == numel2 and rnumel1 == rnumel2
        if not reduction_can_fuse:
            why('numel/rnumel mismatch (reduce) (%s, %s), (%s, %s)', numel1, numel2, rnumel1, rnumel2)
        if reduction_can_fuse and (node1.is_native_matmul() or node2.is_native_matmul()):
            if not node1.is_native_matmul():
                (node1, node2) = (node2, node1)
            tiling = self.select_tiling(node1.get_nodes(), numel1, rnumel1)
            if not all((SIMDKernel.is_compatible(tiling.values(), n2.get_ranges(), reduction_numel=rnumel1) for n2 in node2.get_nodes())):
                why('invalid loop order and tiling for native matmul')
                return False
        return reduction_can_fuse
    if not node1.is_reduction() and (not node2.is_reduction()):
        if not (numel1 == numel2 and rnumel1 == rnumel2):
            if not node2.is_template():
                why('numel/rnumel mismatch (non-reduce) (%s, %s), (%s, %s)', numel1, numel2, rnumel1, rnumel2)
                return False
            else:
                for node in node2.get_nodes():
                    if node.is_template():
                        break
                    if not node.used_buffer_names() & node1.get_buffer_names():
                        continue
                    (_, (pro_numel, pro_rnumel)) = node.group
                    if not (numel1 == pro_numel and rnumel1 == pro_rnumel):
                        why('numel/rnumel mismatch prologue mismatch (%s, %s), (%s, %s)', numel1, pro_numel, rnumel1, pro_rnumel)
                        return False
        for n in (node1, node2):
            if n.is_template():
                return True
        tiling1 = self.select_tiling(node1.get_nodes(), numel1, rnumel1)
        tiling2 = self.select_tiling(node2.get_nodes(), numel1, rnumel1)
        tiling3 = self.select_tiling(node1.get_nodes() + node2.get_nodes(), numel1, rnumel1)
        if config.triton.tiling_prevents_pointwise_fusion:
            cond = True
            if len(tiling1) > 2:
                if len(tiling2) > 2:
                    cond = tiling1 == tiling2 == tiling3
                else:
                    cond = tiling1 == tiling3
            elif len(tiling2) > 2:
                cond = tiling2 == tiling3
            if not cond:
                why('tiling mismatch (%s, %s, %s)', tiling1, tiling2, tiling3)
                return False
        return True
    if not node1.is_reduction() and node2.is_reduction():
        assert rnumel1 == 1 and rnumel2 != 1
        if numel1 == numel2 * rnumel2:
            if not all((SIMDKernel.is_compatible((numel2, rnumel2), n.get_ranges()) for n in node1.get_nodes())):
                why('nodes numel/rnumel incompatibility')
                return False
            if config.triton.tiling_prevents_reduction_fusion and (not node1.is_template()):
                is_reduction_tiling_valid = tuple(self.select_tiling(node1.get_nodes(), numel1).values()) in ((numel1, 1), (numel2, rnumel2, 1))
                if not is_reduction_tiling_valid:
                    why('invalid tiling for reduction')
                return is_reduction_tiling_valid
            return True
        if numel1 != numel2:
            why('nodes numel incompatibility')
        return numel1 == numel2
    assert node1.is_reduction() and (not node2.is_reduction())
    return self.can_fuse_horizontal(node2, node1)

def _get_app_label_and_model_name(model, app_label=''):
    if <MASK>:
        split = model.split('.', 1)
        return tuple(split) if len(split) == 2 else (app_label, split[0])
    else:
        return (model._meta.app_label, model._meta.model_name)

def convert_data_format(data_format, ndim):
    if data_format == 'channels_last':
        if ndim == 3:
            return 'NWC'
        elif ndim == 4:
            return 'NHWC'
        elif <MASK>:
            return 'NDHWC'
        else:
            raise ValueError('Input rank not supported:', ndim)
    elif data_format == 'channels_first':
        if ndim == 3:
            return 'NCW'
        elif ndim == 4:
            return 'NCHW'
        elif ndim == 5:
            return 'NCDHW'
        else:
            raise ValueError('Input rank not supported:', ndim)
    else:
        raise ValueError('Invalid data_format:', data_format)

def __post_init__(self) -> None:
    for (arg, ret) in zip(self.arguments.out, self.returns):
        assert arg.annotation == ret.annotation, 'Out arguments must have matching return Tensor; furthermore, the ith-argument needs to correspond to the ith return'
    for a in self.arguments.post_self_positional_mutable:
        assert not any((a.annotation == r.annotation for r in self.returns)), f'If you have a schema with mutable positional args, we expect them to not be returned. schema: {str(self)}'
    out_and_self = list(self.arguments.out) + [arg for arg in self.arguments.flat_positional if arg.name == 'self']
    mutable_returns = [ret for ret in self.returns if ret.annotation is not None and ret.annotation.is_write]
    immutable_returns = [ret for ret in self.returns if ret.annotation is None or not ret.annotation.is_write]
    assert len(mutable_returns) == 0 or len(immutable_returns) == 0, f'NativeFunctions must have either only mutable returns, or only immutable returns. Found: {str(self)}'
    for ret in mutable_returns:
        assert any((ret.annotation == arg.annotation for arg in out_and_self)), 'All mutable returns must be aliased either to a keyword argument, or to "self". Did you forget to mark an out argument as keyword-only?'
    if self.arguments.out:
        if any((a.type != BaseType(BaseTy.Tensor) for a in self.arguments.out)):
            assert len(self.returns) == 0, 'out= ops that accept tensor lists as out arguments '
            "are expected to have no return type (since you can't do method chaining on them)"
        else:
            assert len([arg for arg in self.arguments.out if not arg.name.startswith('_scratch_')]) == len(self.returns), 'Must return as many arguments as there are out arguments, or no return at all'
    if self.name.name.inplace:
        self_a = self.arguments.self_arg
        assert self_a and self_a.argument.annotation and self_a.argument.annotation.is_write
        if self_a.argument.type == BaseType(BaseTy.Tensor):
            assert len(self.returns) == 1 and self.returns[0].annotation == self_a.argument.annotation
        else:
            assert len(self.returns) == 0
    if <MASK>:
        assert self.kind() == SchemaKind.functional, f'Found an operator that is not functional or out variant, but has tensor options arguments.This is not allowed- tensor options arguments are only allowed for factory functions.schema: {str(self)}'
    if self.is_functional_fn():
        assert self.kind() == SchemaKind.functional, f"Found an operator that is not functional, but its overload contains the string 'functional'.This is a special keyword in the codegen, please use a different overload name.schema: {str(self)}"

def reduction_combine_vec(self, reduction_type, var, next_value, helper_val=None, index: Optional[sympy.Symbol]=None, horizontal_reduction: Optional[bool]=None, src_dtype: Optional[torch.dtype]=torch.float32):
    is_bool = src_dtype == torch.bool
    if reduction_type == 'max':
        if <MASK>:
            return f'max_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} | {next_value}' if is_bool else f'at::vec::maximum({var}, {next_value})'
    elif reduction_type == 'min':
        if self.tail_size:
            return f'min_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} & {next_value}' if is_bool else f'at::vec::minimum({var}, {next_value})'
    elif reduction_type == 'sum':
        if helper_val:
            if self.tail_size:
                return f'cascade_sum_combine({next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'cascade_sum_combine({next_value}, &{helper_val})'
        elif self.tail_size:
            return f'sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            conjunction = '|' if is_bool else '+'
            return f'{var} {conjunction} {next_value}'
    elif reduction_type == 'prod':
        if self.tail_size:
            return f'prod_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} * {next_value}'
    elif reduction_type == 'xor_sum':
        if self.tail_size:
            return f'xor_sum_masked_reduce({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'{var} ^ {next_value}'
    elif reduction_type == 'welford_reduce':
        if helper_val:
            if self.tail_size:
                return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)}, &{helper_val})'
            else:
                return f'welford_combine({var}, {next_value}, &{helper_val})'
        elif self.tail_size:
            return f'welford_combine({var}, {next_value}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {next_value})'
    elif reduction_type == 'welford_combine':
        if isinstance(next_value, tuple):
            (mean, m2, weight) = next_value
        else:
            (mean, m2, weight) = reduction_project(reduction_type, next_value)
        if self.tail_size:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}}, {cexpr_index(self.tail_size)})'
        else:
            return f'welford_combine({var}, {{{mean}, {m2}, {weight}}})'
    elif reduction_type in ('argmin', 'argmax'):
        assert src_dtype is not None
        cdtype = DTYPE_TO_CPP[src_dtype]
        if src_dtype == torch.bool:
            cdtype = DTYPE_TO_CPP[torch.float]
        n_src = self._get_num_vectors(src_dtype)
        n_idx = self._get_num_vectors(torch.int64)
        t_extra = ''
        arg_extra = ''
        if index is not None:
            assert horizontal_reduction is not None
            t_extra = f', {str(horizontal_reduction).lower()}'
            arg_extra = f', {index}'
        if self.tail_size:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra}, {cexpr_index(self.tail_size)})'
        else:
            return f'{reduction_type}_combine_vec<{cdtype}, {n_src}, {n_idx}{t_extra}>({var}, {next_value}{arg_extra})'
    elif reduction_type == 'any':
        if isinstance(next_value, CppCSEVariable):
            assert next_value.dtype == torch.bool
            (next_value,) = unify_mask_base_type(V.kernel.compute, (next_value,))
        return f'{var} | {next_value}'
    else:
        raise NotImplementedError

def _query_tpu_system_metadata(master_address, cluster_def=None, query_topology=False):
    """Automatically detects the TPU system metadata in the system."""
    tpu_core_count = 0
    devices = []
    device_dict = collections.defaultdict(list)
    if <MASK>:
        logical_devices = config.list_logical_devices()
        devices = [session_lib._DeviceAttributes(device_util.canonicalize(d.name), d.device_type, 0, 0) for d in logical_devices]
    else:
        retry_count = 1
        while True:
            logging.info('Querying Tensorflow master (%s) for TPU system metadata.', master_address)
            try:
                with ops.Graph().as_default():
                    with session_lib.Session(master_address, config=get_session_config_with_timeout(_PINGING_MASTER_TIMEOUT_IN_MS, cluster_def)) as sess:
                        devices = sess.list_devices()
                        break
            except errors.DeadlineExceededError:
                msg = 'Failed to connect to the Tensorflow master. The TPU worker may not be ready (still scheduling) or the Tensorflow master address is incorrect: got (%s).' % master_address
                if retry_count <= _RETRY_TIMES:
                    logging.warning('%s', msg)
                    logging.warning('Retrying (%d/%d).', retry_count, _RETRY_TIMES)
                    retry_count += 1
                else:
                    raise ValueError(msg)
    for device in devices:
        spec = tf_device.DeviceSpec.from_string(device.name)
        if spec.device_type == 'TPU':
            device_dict[spec.task].append(spec.device_index)
            tpu_core_count += 1
    num_of_cores_per_host = 0
    if tpu_core_count:
        num_cores_per_host_set = set([len(core_ids) for core_ids in device_dict.values()])
        if len(num_cores_per_host_set) != 1:
            raise RuntimeError('TPU cores on each host is not same. This should not happen!. devices: {}'.format(devices))
        num_of_cores_per_host = num_cores_per_host_set.pop()
    topology = None
    if query_topology:
        if not tpu_core_count:
            raise RuntimeError('Cannot find any TPU cores in the system (master address {}). This usually means the master address is incorrect or the TPU worker has some problems. Available devices: {}'.format(master_address, devices))
        topology = _obtain_topology(master_address, cluster_def)

    def _sort_key(device):
        spec = tf_device.DeviceSpec.from_string(device.name)
        return (spec.job, spec.replica, spec.task, spec.device_type, spec.device_index)
    devices = tuple(sorted(devices, key=_sort_key))
    metadata = TPUSystemMetadata(num_cores=tpu_core_count, num_hosts=len(device_dict), num_of_cores_per_host=num_of_cores_per_host, topology=topology, devices=devices)
    if tpu_core_count:
        logging.info('Found TPU system:')
        logging.info('*** Num TPU Cores: %d', metadata.num_cores)
        logging.info('*** Num TPU Workers: %d', metadata.num_hosts)
        logging.info('*** Num TPU Cores Per Worker: %d', metadata.num_of_cores_per_host)
        for device in metadata.devices:
            logging.info('*** Available Device: %s', device)
    else:
        logging.info('Failed to find TPU: %s', metadata)
    return metadata

def __call__(self) -> dict[torch.fx.Node, NodeSet]:
    result: dict[torch.fx.Node, NodeSet] = {}
    acc_nodes = list(self.acc_nodes)
    for node in acc_nodes:
        if node in result:
            continue
        if node.op not in CALLABLE_NODE_OPS:
            continue
        if 'tensor_meta' in node.meta:
            continue
        if node not in self.acc_nodes:
            continue
        fusion_group: FxNetAccFusionsFinder.FusionGroup = self.FusionGroup(top_node_idx=self.nodes.index(node), nodes={node}, inputs=set(node.all_input_nodes), nodes_need_process={node})
        while fusion_group.nodes_need_process:
            node = fusion_group.nodes_need_process.pop()
            self.recursive_add_node(fusion_group, fusion_group.inputs, visited=set())
            if 'tensor_meta' not in node.meta:
                for user in node.users:
                    if user.op not in CALLABLE_NODE_OPS:
                        continue
                    if user in fusion_group.nodes:
                        continue
                    fusion_group.add_node(user)
                    self.recursive_add_node(fusion_group, fusion_group.inputs, visited=set())
            for arg in node.all_input_nodes:
                if arg.op not in CALLABLE_NODE_OPS:
                    continue
                if <MASK>:
                    continue
                if arg in fusion_group.nodes:
                    continue
                fusion_group.add_node(arg)
                fusion_group.top_node_idx = min(fusion_group.top_node_idx, self.nodes.index(arg))
                self.recursive_add_node(fusion_group, fusion_group.inputs, visited=set())
        if not set(fusion_group.nodes) <= self.acc_nodes:
            self.acc_nodes -= fusion_group.nodes
        else:
            for n in fusion_group.nodes:
                result[n] = fusion_group.nodes
    return result

def _select_fn(x):
    if <MASK>:
        return x._primary
    else:
        return x

def _deduplicate_modules(partitions):
    redirected_call_indices = {}
    for shared_submodules in partitions:
        for (i, entry) in enumerate(shared_submodules):
            child_fqn = _call_name(entry.fqn, entry.call_idx)
            target = _compute_accessor(entry.parent_fqn, child_fqn)
            deduplicated = False
            for seen in shared_submodules[:i]:
                if _check_graph_equivalence(seen.module, entry.module):
                    parent = entry.parent_module
                    if <MASK>:
                        (*prefix, name) = target.split('.')
                        _get_attr_via_attr_list(parent, prefix)._modules.pop(name)
                        seen_child_fqn = _call_name(seen.fqn, seen.call_idx)
                        seen_target = _compute_accessor(entry.parent_fqn, seen_child_fqn)
                        entry.parent_call_module.target = seen_target
                        redirected_call_indices[child_fqn] = seen_child_fqn
                        break
                    elif not deduplicated:
                        parent.set_submodule(target, seen.module)
                        deduplicated = True
    return redirected_call_indices

def parallel_apply(modules: Sequence[Module], inputs: Sequence[Any], kwargs_tup: Optional[Sequence[dict[str, Any]]]=None, devices: Optional[Sequence[Optional[Union[int, torch.device]]]]=None) -> list[Any]:
    """Apply each `module` in :attr:`modules` in parallel on each of :attr:`devices`.

    Args:
        modules (Module): modules to be parallelized
        inputs (tensor): inputs to the modules
        devices (list of int or torch.device): CUDA devices

    :attr:`modules`, :attr:`inputs`, :attr:`kwargs_tup` (if given), and
    :attr:`devices` (if given) should all have same length. Moreover, each
    element of :attr:`inputs` can either be a single object as the only argument
    to a module, or a collection of positional arguments.
    """
    assert len(modules) == len(inputs), f'The number of modules {len(modules)} is not equal to the number of inputs {len(inputs)}'
    if kwargs_tup is not None:
        assert len(modules) == len(kwargs_tup)
    else:
        kwargs_tup = (cast(dict[str, Any], {}),) * len(modules)
    if devices is not None:
        assert len(modules) == len(devices)
    else:
        devices = [None] * len(modules)
    devices = [_get_device_index(x, True) for x in devices]
    streams = [torch.accelerator.current_stream(x) for x in devices]
    assert torch.accelerator.is_available(), 'No available accelerator found.'
    device_type = torch.accelerator.current_accelerator().type
    lock = threading.Lock()
    results = {}
    (grad_enabled, autocast_enabled) = (torch.is_grad_enabled(), torch.is_autocast_enabled())

    def _worker(i: int, module: Module, input: Any, kwargs: dict[str, Any], device: Optional[Union[int, torch.device]]=None, stream: Optional[torch.Stream]=None) -> None:
        torch.set_grad_enabled(grad_enabled)
        if device is None:
            t = get_a_var(input)
            if <MASK>:
                with lock:
                    results[i] = ExceptionWrapper(where=f'in replica {i}, no device was provided and no tensor input was found; device cannot be resolved')
                return
            device = t.get_device()
        if isinstance(device, torch.device):
            device = device.index
        if stream is None:
            stream = torch.accelerator.current_stream(device)
        try:
            with torch.accelerator.device_index(device), stream, torch.amp.autocast(device_type, enabled=autocast_enabled):
                if not isinstance(input, (list, tuple)):
                    input = (input,)
                output = module(*input, **kwargs)
            with lock:
                results[i] = output
        except Exception:
            with lock:
                results[i] = ExceptionWrapper(where=f'in replica {i} on device {device}')
    if len(modules) > 1:
        threads = [threading.Thread(target=_worker, args=(i, module, input, kwargs, device, stream)) for (i, (module, input, kwargs, device, stream)) in enumerate(zip(modules, inputs, kwargs_tup, devices, streams))]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
    else:
        _worker(0, modules[0], inputs[0], kwargs_tup[0], devices[0], streams[0])
    outputs = []
    for i in range(len(inputs)):
        output = results[i]
        if isinstance(output, ExceptionWrapper):
            output.reraise()
        outputs.append(output)
    return outputs

def rename_axis(model: ir.Model, rename_mapping: dict[str, str]) -> None:
    """Rename dynamic axes in a model according to the specified dynamic_axes names."""
    sorted_rename_mapping = dict(sorted(rename_mapping.items(), key=lambda item: len(item[0]), reverse=True))
    for value in _all_values(model):
        if value.shape is None:
            continue
        new_shape = []
        changed = False
        for dim in value.shape:
            if <MASK>:
                new_shape.append(dim)
                continue
            dim_name = dim.value
            if dim_name in sorted_rename_mapping:
                new_shape.append(sorted_rename_mapping[dim_name])
                changed = True
            elif dim_name is not None:
                new_name = _replace_names(dim_name, sorted_rename_mapping)
                new_shape.append(new_name)
                if new_name != dim_name:
                    changed = True
            else:
                new_shape.append(None)
        if changed:
            value.shape = ir.Shape(new_shape)

def _reduce(tf_fn, a, axis=None, dtype=None, keepdims=None, promote_int=_TO_INT_, tf_bool_fn=None, preserve_bool=False):
    """A general reduction function.

  Args:
    tf_fn: the TF reduction function.
    a: the array to be reduced.
    axis: (optional) the axis along which to do the reduction. If None, all
      dimensions are reduced.
    dtype: (optional) the dtype of the result.
    keepdims: (optional) whether to keep the reduced dimension(s).
    promote_int: how to promote integer and bool inputs. There are three
      choices. (1) `_TO_INT_` always promotes them to np.int_ or np.uint; (2)
      `_TO_FLOAT` always promotes them to a float type (determined by
      dtypes.default_float_type); (3) None: don't promote.
    tf_bool_fn: (optional) the TF reduction function for bool inputs. It will
      only be used if `dtype` is explicitly set to `np.bool_` or if `a`'s dtype
      is `np.bool_` and `preserve_bool` is True.
    preserve_bool: a flag to control whether to use `tf_bool_fn` if `a`'s dtype
      is `np.bool_` (some reductions such as np.sum convert bools to integers,
      while others such as np.max preserve bools.

  Returns:
    An ndarray.
  """
    if dtype:
        dtype = np_utils.result_type(dtype)
    if keepdims is None:
        keepdims = False
    a = asarray(a, dtype=dtype)
    if (dtype == np.bool_ or (preserve_bool and a.dtype == np.bool_)) and tf_bool_fn is not None:
        return tf_bool_fn(input_tensor=a, axis=axis, keepdims=keepdims)
    if dtype is None:
        dtype = a.dtype.as_numpy_dtype
        if np.issubdtype(dtype, np.integer) or dtype == np.bool_:
            if promote_int == _TO_INT_:
                if dtype == np.bool_:
                    is_signed = True
                    width = 8
                else:
                    is_signed = np.issubdtype(dtype, np.signedinteger)
                    width = np.iinfo(dtype).bits
                if ops.is_auto_dtype_conversion_enabled():
                    if width < np.iinfo(np.int32).bits:
                        if is_signed:
                            dtype = np.int32
                        else:
                            dtype = np.uint32
                elif width < np.iinfo(np.int_).bits:
                    if is_signed:
                        dtype = np.int_
                    else:
                        dtype = np.uint
                a = math_ops.cast(a, dtype)
            elif <MASK>:
                a = math_ops.cast(a, np_utils.result_type(float))
    if isinstance(axis, tensor_lib.Tensor) and axis.dtype not in (dtypes.int32, dtypes.int64):
        axis = math_ops.cast(axis, dtypes.int64)
    return tf_fn(input_tensor=a, axis=axis, keepdims=keepdims)

def _restore_from_tensors(restored_tensors):
    restore_ops = {}
    for saveable in saveables:
        saveable_restored_tensors = []
        for spec in saveable.specs:
            name = trackable_utils.extract_local_name(_convert_to_string(spec.name))
            slice_spec = _convert_to_string(spec.slice_spec)
            maybe_tensor = restored_tensors[name]
            if <MASK>:
                maybe_tensor = {'': maybe_tensor}
            saveable_restored_tensors.append(maybe_tensor[slice_spec])
        restore_ops[saveable.name] = saveable.restore(saveable_restored_tensors, restored_shapes=None)
    return restore_ops

def testNestedCallUnsupportedOps(self):
    if <MASK>:
        self.skipTest('Outside compilation will extract string_length to CPU')
    with ops.device('device:{}:0'.format(self.device)):

        def fn(x):
            return string_ops.string_length(string_ops.string_format('{}', x))
        xla_func = polymorphic_function.function(fn, jit_compile=True)

        def fn2(x):
            return xla_func(x)
        func = polymorphic_function.function(fn2, jit_compile=False)
        inputs = constant_op.constant([1, 2, 2, 3, 3])
        with self.assertRaisesRegex(errors.InvalidArgumentError, 'unsupported operations'):
            func(inputs)

def rename_constant(name):
    if <MASK>:
        n = 1
        while (dup_name := f'{name}_{n}') in node_names:
            n += 1
