def _trackable_children(self, save_type=base.SaveType.CHECKPOINT, **kwargs):
    children = super()._trackable_children(save_type, **kwargs)
    if <MASK>:

        @def_function.function(input_signature=[], autograph=False)
        def _creator():
            resource = self._create_resource()
            return resource

        @def_function.function(input_signature=[], autograph=False)
        def _initializer():
            self._initialize()
            return 1

        @def_function.function(input_signature=[], autograph=False)
        def _destroyer():
            self._destroy_resource()
            return 1
        children.update({'_create_resource': _creator, '_initialize': _initializer, '_destroy_resource': _destroyer})
    return children

def _infer_steps(self, steps, dataset):
    """Infers steps_per_epoch needed to loop through a dataset."""
    if <MASK>:
        self._log_indefinite_training_warning()
        return None
    if steps is not None:
        return steps
    adapter_steps = self._adapter.get_size()
    if adapter_steps is not None:
        return adapter_steps
    size = cardinality.cardinality(dataset)
    if size == cardinality.INFINITE and steps is None:
        raise ValueError('When passing an infinitely repeating dataset, please specify a `steps_per_epoch` value so that epoch level callbacks continue to work. The value can be arbitrary, or a number that you think correctly defines the size of an epoch. Epoch-level callbacks will then be called at this interval.')
    if size >= 0:
        return size.numpy().item()
    return None

def raise_observed_exception(exc_type: type[Exception], tx: InstructionTranslatorBase, *, args: Optional[list[Any]]=None, kwargs: Optional[dict[str, Any]]=None, msg: Optional[str]=None) -> NoReturn:
    from .variables import BuiltinVariable
    if msg is not None and (args is None or len(args) == 0):
        args = [msg]
    exception_vt = BuiltinVariable(exc_type).call_function(tx, args or [], kwargs or {})
    tx.exn_vt_stack.set_current_exception(exception_vt)
    raised_exc = get_dynamo_observed_exception(exc_type)
    if <MASK>:
        raise raised_exc(*args)
    raise raised_exc

def tolist(tensor, sub_proxy):

    def wrap(i, sub_proxy):
        return wrap_fx_proxy(tx, sub_proxy.item())
    if tensor.dtype not in [torch.int8, torch.int16, torch.int32, torch.int64]:
        unimplemented_v2(gb_type='Tensor.tolist() with non-integer tensor', context=f'call_method {self} to_list', explanation='Dynamo currently does not support tracing `tolist()` on non-integer tensors.', hints=['Ensure the input tensor to `tolist()` is an integer type (e.g., int8, int16, int32, int64).'])
    if <MASK>:
        return wrap(tensor, sub_proxy)
    if tensor.dim() == 1:
        return [wrap(val, sub_proxy[i]) for (i, val) in enumerate(tensor)]
    return [tolist(sub_tensor, sub_proxy=sub_proxy[i]) for (i, sub_tensor) in enumerate(tensor)]

def generate_invalid_param_val(constraint):
    """Return a value that does not satisfy the constraint.

    Raises a NotImplementedError if there exists no invalid value for this constraint.

    This is only useful for testing purpose.

    Parameters
    ----------
    constraint : _Constraint instance
        The constraint to generate a value for.

    Returns
    -------
    val : object
        A value that does not satisfy the constraint.
    """
    if isinstance(constraint, StrOptions):
        return f"not {' or '.join(constraint.options)}"
    if isinstance(constraint, MissingValues):
        return np.array([1, 2, 3])
    if isinstance(constraint, _VerboseHelper):
        return -1
    if isinstance(constraint, HasMethods):
        return type('HasNotMethods', (), {})()
    if isinstance(constraint, _IterablesNotString):
        return 'a string'
    if isinstance(constraint, _CVObjects):
        return 'not a cv object'
    if isinstance(constraint, Interval) and constraint.type is Integral:
        if constraint.left is not None:
            return constraint.left - 1
        if constraint.right is not None:
            return constraint.right + 1
        raise NotImplementedError
    if isinstance(constraint, Interval) and constraint.type in (Real, RealNotInt):
        if constraint.left is not None:
            return constraint.left - 1e-06
        if constraint.right is not None:
            return constraint.right + 1e-06
        if <MASK>:
            return -np.inf
        if constraint.closed in ('left', 'neither'):
            return np.inf
        return np.nan
    raise NotImplementedError

def validate_sample_input_sparse(op_info, sample, check_validate=False):
    """Return the specified sample when it is valid and supported by the
    operation. Otherwise, return the sample as ErrorInput instance.

    When check_validate is True, the result is validated against
    calling the op on the sample.
    """
    if <MASK>:
        return _validate_sample_input_sparse_reduction(op_info, sample, check_validate=check_validate)
    elif isinstance(op_info, BinaryUfuncInfo):
        return _validate_sample_input_sparse_elementwise_binary_operation(op_info, sample, check_validate=check_validate)
    else:
        return _validate_sample_input_sparse_default(op_info, sample, check_validate=check_validate)

def __init__(self, dataset: Dataset[_T_co], batch_size: Optional[int]=1, shuffle: Optional[bool]=None, sampler: Union[Sampler, Iterable, None]=None, batch_sampler: Union[Sampler[list], Iterable[list], None]=None, num_workers: int=0, collate_fn: Optional[_collate_fn_t]=None, pin_memory: bool=False, drop_last: bool=False, timeout: float=0, worker_init_fn: Optional[_worker_init_fn_t]=None, multiprocessing_context=None, generator=None, *, prefetch_factor: Optional[int]=None, persistent_workers: bool=False, pin_memory_device: str='', in_order: bool=True) -> None:
    torch._C._log_api_usage_once('python.data_loader')
    if num_workers < 0:
        raise ValueError('num_workers option should be non-negative; use num_workers=0 to disable multiprocessing.')
    if timeout < 0:
        raise ValueError('timeout option should be non-negative')
    if num_workers == 0 and prefetch_factor is not None:
        raise ValueError('prefetch_factor option could only be specified in multiprocessing.let num_workers > 0 to enable multiprocessing, otherwise set prefetch_factor to None.')
    elif num_workers > 0 and prefetch_factor is None:
        prefetch_factor = 2
    elif prefetch_factor is not None and prefetch_factor < 0:
        raise ValueError('prefetch_factor option should be non-negative')
    if persistent_workers and num_workers == 0:
        raise ValueError('persistent_workers option needs num_workers > 0')
    self.dataset = dataset
    self.num_workers = num_workers
    self.prefetch_factor = prefetch_factor
    self.pin_memory = pin_memory
    self.pin_memory_device = pin_memory_device
    self.timeout = timeout
    self.worker_init_fn = worker_init_fn
    self.multiprocessing_context = multiprocessing_context
    self.in_order = in_order
    if isinstance(self.dataset, IterDataPipe):
        self.dataset = _IterDataPipeSerializationWrapper(self.dataset)
    elif isinstance(self.dataset, MapDataPipe):
        self.dataset = _MapDataPipeSerializationWrapper(self.dataset)
    if isinstance(dataset, IterableDataset):
        self._dataset_kind = _DatasetKind.Iterable
        if isinstance(dataset, IterDataPipe):
            if shuffle is not None:
                dataset = torch.utils.data.graph_settings.apply_shuffle_settings(dataset, shuffle=shuffle)
        elif <MASK>:
            raise ValueError(f'DataLoader with IterableDataset: expected unspecified shuffle option, but got shuffle={shuffle}')
        if sampler is not None:
            raise ValueError(f'DataLoader with IterableDataset: expected unspecified sampler option, but got sampler={sampler}')
        elif batch_sampler is not None:
            raise ValueError(f'DataLoader with IterableDataset: expected unspecified batch_sampler option, but got batch_sampler={batch_sampler}')
    else:
        shuffle = bool(shuffle)
        self._dataset_kind = _DatasetKind.Map
    if sampler is not None and shuffle:
        raise ValueError('sampler option is mutually exclusive with shuffle')
    if batch_sampler is not None:
        if batch_size != 1 or shuffle or sampler is not None or drop_last:
            raise ValueError('batch_sampler option is mutually exclusive with batch_size, shuffle, sampler, and drop_last')
        batch_size = None
        drop_last = False
    elif batch_size is None:
        if drop_last:
            raise ValueError('batch_size=None option disables auto-batching and is mutually exclusive with drop_last')
    if sampler is None:
        if self._dataset_kind == _DatasetKind.Iterable:
            sampler = _InfiniteConstantSampler()
        elif shuffle:
            sampler = RandomSampler(dataset, generator=generator)
        else:
            sampler = SequentialSampler(dataset)
    if batch_size is not None and batch_sampler is None:
        batch_sampler = BatchSampler(sampler, batch_size, drop_last)
    self.batch_size = batch_size
    self.drop_last = drop_last
    self.sampler = sampler
    self.batch_sampler = batch_sampler
    self.generator = generator
    if collate_fn is None:
        if self._auto_collation:
            collate_fn = _utils.collate.default_collate
        else:
            collate_fn = _utils.collate.default_convert
    self.collate_fn = collate_fn
    self.persistent_workers = persistent_workers
    self.__initialized = True
    self._IterableDataset_len_called = None
    self._iterator = None
    self.check_worker_number_rationality()
    torch.set_vital('Dataloader', 'enabled', 'True')

def build_graph(device, input_shape, axes, num_layers, mode, scale, train):
    """Build a graph containing a sequence of batch normalizations.

  Args:
    device: string, the device to run on.
    input_shape: shape of the input tensor.
    axes: axes that are to be normalized across.
    num_layers: number of batch normalization layers in the graph.
    mode: "op", "py" or "slow" depending on the implementation.
    scale: scale after normalization.
    train: if true, also run backprop.

  Returns:
    An array of tensors to run()
  """
    moment_shape = []
    keep_dims = mode == 'py' or mode == 'slow'
    if keep_dims:
        for axis in range(len(input_shape)):
            if <MASK>:
                moment_shape.append(1)
            else:
                moment_shape.append(input_shape[axis])
    else:
        for axis in range(len(input_shape)):
            if axis not in axes:
                moment_shape.append(input_shape[axis])
    with ops.device('/%s:0' % device):
        tensor = variables.Variable(random_ops.truncated_normal(input_shape))
        for _ in range(num_layers):
            if train:
                (mean, variance) = nn_impl.moments(tensor, axes, keep_dims=keep_dims)
            else:
                mean = array_ops.zeros(moment_shape)
                variance = array_ops.ones(moment_shape)
            beta = variables.Variable(array_ops.zeros(moment_shape))
            gamma = variables.Variable(constant_op.constant(1.0, shape=moment_shape))
            if mode == 'py':
                tensor = batch_norm_py(tensor, mean, variance, beta, gamma, scale)
            elif mode == 'op':
                tensor = batch_norm_op(tensor, mean, variance, beta, gamma, scale)
            elif mode == 'slow':
                tensor = batch_norm_slow(tensor, mean, variance, beta, gamma, scale)
        if train:
            return gradients_impl.gradients([tensor], variables.trainable_variables())
        else:
            return [tensor]

def cuda_compile_command(src_files: list[str], dst_file: str, dst_file_ext: str, extra_args: list[str] | None=None) -> str:
    if <MASK>:
        extra_args = []
    if use_re_build():
        build_path = os.path.dirname(dst_file)
        include_paths = _clone_cutlass_paths(build_path)
        src_files = [os.path.basename(src_file) for src_file in src_files]
        dst_file = os.path.basename(dst_file)
    else:
        include_paths = _cutlass_include_paths()
    cuda_lib_options = _cuda_lib_options()
    nvcc_host_compiler_options = _nvcc_host_compiler_options()
    nvcc_compiler_options = _nvcc_compiler_options()
    options = nvcc_compiler_options + extra_args + [f'-Xcompiler {opt}' if '=' in opt else f'-Xcompiler={opt}' for opt in nvcc_host_compiler_options] + ['-I' + path for path in include_paths] + cuda_lib_options
    src_file = ' '.join(src_files)
    res = ''
    if dst_file_ext == 'o':
        res = f"{_cuda_compiler()} {' '.join(options)} -c -o {dst_file} {src_file}"
    elif dst_file_ext == 'so':
        options.append('-shared')
        res = f"{_cuda_compiler()} {' '.join(options)} -o {dst_file} {src_file}"
    elif dst_file_ext == 'exe':
        res = f"{_cuda_compiler()} {' '.join(options)} -o {dst_file} {src_file}"
    else:
        raise NotImplementedError(f'Unsupported output file suffix {dst_file_ext}!')
    if log.isEnabledFor(logging.DEBUG):
        log.debug('CUDA command: %s', res)
    else:
        autotuning_log.debug('CUDA command: %s', res)
    return res

@exposed_in('torch')
def cond(pred: Union[bool, int, float, torch.Tensor], true_fn: Callable, false_fn: Callable, operands: Union[tuple, list]=()) -> Any:
    """
    Conditionally applies `true_fn` or `false_fn`.

    .. warning::
        `torch.cond` is a prototype feature in PyTorch. It has limited support for input and output types and
        doesn't support training currently. Please look forward to a more stable implementation in a future version of PyTorch.
        Read more about feature classification at: https://pytorch.org/blog/pytorch-feature-classification-changes/#prototype

    `cond` is structured control flow operator. That is, it is like a Python if-statement,
    but has restrictions on `true_fn`, `false_fn`, and `operands` that enable it to be
    capturable using torch.compile and torch.export.

    Assuming the constraints on `cond`'s arguments are met, `cond` is equivalent to the following::

        def cond(pred, true_branch, false_branch, operands):
            if pred:
                return true_branch(*operands)
            else:
                return false_branch(*operands)

    Args:
        pred (Union[bool, torch.Tensor]): A boolean expression or a tensor with one element,
          indicating which branch function to apply.

        true_fn (Callable): A callable function (a -> b) that is within the
          scope that is being traced.

        false_fn (Callable): A callable function (a -> b) that is within the
          scope that is being traced. The true branch and false branch must
          have consistent input and outputs, meaning the inputs have to be
          the same, and the outputs have to be the same type and shape. Int
          output is also allowed. We'll make the output dynamic by turning it
          into a symint.

        operands (Tuple of possibly nested dict/list/tuple of torch.Tensor): A tuple of inputs to the
          true/false functions. It can be empty if true_fn/false_fn doesn't require input. Defaults to ().

    Example::

        def true_fn(x: torch.Tensor):
            return x.cos()


        def false_fn(x: torch.Tensor):
            return x.sin()


        return cond(x.shape[0] > 4, true_fn, false_fn, (x,))

    Restrictions:
        - The conditional statement (aka `pred`) must meet one of the following constraints:

          - It's a `torch.Tensor` with only one element, and torch.bool dtype

          - It's a boolean expression, e.g. `x.shape[0] > 10` or `x.dim() > 1 and x.shape[1] > 10`

        - The branch function (aka `true_fn`/`false_fn`) must meet all of the following constraints:

          - The function signature must match with operands.

          - The function must return a tensor with the same metadata, e.g. shape,
            dtype, etc.

          - The function cannot have in-place mutations on inputs or global variables.
            (Note: in-place tensor operations such as `add_` for intermediate results
            are allowed in a branch)

    """
    if torch.compiler.is_dynamo_compiling():
        return cond_op(pred, true_fn, false_fn, operands)
    if isinstance(pred, (bool, int, float)):
        if torch.compiler.is_compiling():
            warnings.warn('Pred is a Python constant. When used with torch.cond, it specializes on one of the branches. If you want torch.cond to preserve two branches, please make the predicate a boolean tensor or a SymBool.', UserWarning)
        if pred:
            return true_fn(*operands)
        else:
            return false_fn(*operands)

    def _validate_input(pred, true_fn, false_fn, operands):
        if not isinstance(pred, (bool, torch.Tensor, torch.SymBool)):
            raise RuntimeError(f'Expected pred to be bool or tensor, but got {pred}.')
        if isinstance(pred, torch.Tensor) and pred.numel() != 1:
            raise RuntimeError(f'Expected pred to be bool or single-element tensor, but got {pred}.')
        if not callable(true_fn) or not callable(false_fn):
            raise RuntimeError('Expect both branches to be callable.')
        if <MASK>:
            raise RuntimeError(f'Expect operands to be a tuple of possibly nested dict/list/tuple that only consists of tensor leaves, but got {operands}.')
    _validate_input(pred, true_fn, false_fn, operands)
    if not torch._dynamo.is_dynamo_supported():
        raise RuntimeError('torch.cond requires dynamo support.')

    def _cond_op_wrapper(*args, **kwargs):
        return cond_op(*args, **kwargs)
    from torch._higher_order_ops.utils import setup_compilation_env
    with setup_compilation_env() as backend:
        return torch.compile(_cond_op_wrapper, backend=backend, fullgraph=True)(pred, true_fn, false_fn, operands)

@register_decomposition(aten.softplus)
@_inplace_wrapper
@out_wrapper()
@elementwise_type_promotion_wrapper(type_promoting_args=('a',), type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
def softplus(a: TensorLikeType, beta: Optional[NumberType]=None, threshold: NumberType=20, inplace: bool=False) -> TensorLikeType:
    """
    Reference implementation of torch.nn.functional.softplus
    """
    if inplace:
        raise NotImplementedError
    rhs: TensorLikeType
    if beta is not None:
        python_type = utils.dtype_to_type(a.dtype)
        if <MASK>:
            msg = f'beta argument of type {type(beta)} cannot be safely cast to type {python_type}!'
            raise ValueError(msg)
        scaled_input = a * beta
        rhs = torch.true_divide(torch.log1p(torch.exp(scaled_input)), beta)
    else:
        scaled_input = a
        rhs = torch.log1p(torch.exp(scaled_input))
    return torch.where(scaled_input > threshold, a, rhs)

def __init__(self, level: int, global_dict=None, local_dict=None, resolvers=(), target=None) -> None:
    self.level = level + 1
    self.scope = DeepChainMap(DEFAULT_GLOBALS.copy())
    self.target = target
    if isinstance(local_dict, Scope):
        self.scope.update(local_dict.scope)
        if local_dict.target is not None:
            self.target = local_dict.target
        self._update(local_dict.level)
    frame = sys._getframe(self.level)
    try:
        scope_global = self.scope.new_child((global_dict if global_dict is not None else frame.f_globals).copy())
        self.scope = DeepChainMap(scope_global)
        if <MASK>:
            scope_local = self.scope.new_child((local_dict if local_dict is not None else frame.f_locals).copy())
            self.scope = DeepChainMap(scope_local)
    finally:
        del frame
    if isinstance(local_dict, Scope):
        resolvers += tuple(local_dict.resolvers.maps)
    self.resolvers = DeepChainMap(*resolvers)
    self.temps = {}

def analyze_test_numerics(test_results: model_handler.TestResultCollection, use_cpu_baseline: bool) -> (DataFrame, str):
    """Analyzes test numerics."""
    preprocess_funcs = {'abs_diff': lambda x, y: np.fabs(x - y)}
    postprocess_funcs = {'mean': np.mean}
    column_names = []
    columns = []
    base_result = test_results.cpu_base_result if use_cpu_baseline else test_results.gpu_base_result
    if <MASK>:
        raise ValueError(f"No {('CPU' if use_cpu_baseline else 'GPU')} baseline found!")
    for (fn0, fn1) in itertools.product(preprocess_funcs, postprocess_funcs):
        (func0, func1) = (preprocess_funcs[fn0], postprocess_funcs[fn1])
        column_names.append('{}_{}'.format(fn0, fn1))
        columns.append([])
        for result in test_results.results:
            columns[-1].append(dict())
            for (idx, tensor) in enumerate(result.output_tensors):
                name = base_result.output_names[idx]
                cpu_tensor = base_result.output_tensors[idx]
                absdiff = func0(tensor, cpu_tensor)
                metric_value = func1(absdiff).item()
                cpu_tensor_hist = str_histogram(cpu_tensor, 'cpu_tensor')
                gpu_tensor_hist = str_histogram(tensor, 'gpu_tensor')
                abs_diff_hist = str_histogram(absdiff, 'abs_diff')
                hist_data = (cpu_tensor_hist, gpu_tensor_hist, abs_diff_hist)
                columns[-1][-1][name] = metric_value
    return (DataFrame(column_names=column_names, columns=columns), hist_data)

def _convert_tolerance(self, tolerance, target: np.ndarray | Index) -> np.ndarray:
    tolerance = np.asarray(tolerance)
    if target.size != tolerance.size and tolerance.size > 1:
        raise ValueError('list-like tolerance size must match target index size')
    elif <MASK>:
        if tolerance.ndim > 0:
            raise ValueError(f'tolerance argument for {type(self).__name__} with dtype {self.dtype} must contain numeric elements if it is list type')
        raise ValueError(f'tolerance argument for {type(self).__name__} with dtype {self.dtype} must be numeric if it is a scalar: {tolerance!r}')
    return tolerance

def var_creator(**kwargs):
    """Create an AggregatingVariable and fix up collections."""
    collections = kwargs.pop('collections', None)
    if <MASK>:
        collections = [ops.GraphKeys.GLOBAL_VARIABLES]
    kwargs['collections'] = []
    v = next_creator(**kwargs)
    wrapped = ps_values.AggregatingVariable(self._container_strategy(), v, aggregation)
    if not context.executing_eagerly():
        g = ops.get_default_graph()
        if kwargs.get('trainable', True):
            collections.append(ops.GraphKeys.TRAINABLE_VARIABLES)
            l = g.get_collection_ref(ops.GraphKeys.TRAINABLE_VARIABLES)
            if v in l:
                l.remove(v)
        g.add_to_collections(collections, wrapped)
    elif ops.GraphKeys.GLOBAL_STEP in collections:
        ops.add_to_collections(ops.GraphKeys.GLOBAL_STEP, wrapped)
    return wrapped

def call_function(self, fn: VariableTracker, args: list[VariableTracker], kwargs: dict[str, VariableTracker]) -> None:
    assert isinstance(fn, VariableTracker)
    assert isinstance(args, list)
    assert isinstance(kwargs, dict)
    assert all((isinstance(x, VariableTracker) for x in itertools.chain(args, kwargs.values())))
    inner_fn = None
    if <MASK>:
        inner_fn = fn.value
    if hasattr(fn, 'fn'):
        inner_fn = fn.fn
    if inner_fn and callable(inner_fn) and is_forbidden(inner_fn):
        raise AssertionError(f'Attempt to trace forbidden callable {inner_fn}')
    self.push(fn.call_function(self, args, kwargs))

@classmethod
def get_all(cls) -> list['BwdKernel']:
    kernels: list[BwdKernel] = []
    for (aligned, dtype, (sm, sm_max), apply_dropout, max_k) in itertools.product([True, False], DTYPES.keys(), itertools.pairwise(SM), [True, False], [32, 64, 128, 2 ** 16]):
        if dtype == 'bf16' and sm < 80:
            continue
        if not aligned and sm >= 80:
            continue
        is_half = dtype in ['bf16', 'f16']
        bi_values = [64]
        if sm >= 80 or (sm >= 70 and is_half):
            if <MASK>:
                bi_values.append(128)
        for bi in bi_values:
            output_in_rf = is_half and max_k <= bi
            preload_mmas = is_half and sm >= 80 and output_in_rf
            bj = 128 if preload_mmas and max_k > 64 else 64
            kernels.append(cls(aligned=aligned, dtype=dtype, sm_range=(sm, sm_max), apply_dropout=apply_dropout, preload_mmas=preload_mmas, block_i=bi, block_j=bj, max_k=max_k))
            if apply_dropout or max_k > 128 or (not is_half) or (not aligned):
                continue
            if sm not in [70, 80]:
                continue
            kernels.append(cls(aligned=aligned, dtype=dtype, sm_range=(sm, sm_max), apply_dropout=apply_dropout, preload_mmas=preload_mmas, block_i=bi, block_j=bj, max_k=max_k, keys_queries_aligned_to_blocksizes=True))
    for dtype in ['f16', 'bf16']:
        kernels.append(cls(aligned=True, dtype=dtype, sm_range=(80, SM[SM.index(80) + 1]), apply_dropout=False, preload_mmas=True, block_i=128, block_j=64, max_k=96, dispatch_cond='cc == 86 || cc == 89'))
    return kernels

def __init__(self, app_names=None, *args, **kwargs):
    self.apps = []
    self.storages = {}
    app_configs = apps.get_app_configs()
    if app_names:
        app_names = set(app_names)
        app_configs = [ac for ac in app_configs if ac.name in app_names]
    for app_config in app_configs:
        app_storage = self.storage_class(os.path.join(app_config.path, self.source_dir))
        if os.path.isdir(app_storage.location):
            self.storages[app_config.name] = app_storage
            if <MASK>:
                self.apps.append(app_config.name)
    super().__init__(*args, **kwargs)

def _MakeFunc(v, arg_name):
    """Ensure v is a func."""
    if isinstance(v, attr_value_pb2.NameAttrList):
        return v
    if <MASK>:
        fn_attr = attr_value_pb2.NameAttrList(name=v)
    elif hasattr(v, 'add_to_graph'):
        v.add_to_graph(ops.get_default_graph())
        if hasattr(v, '_as_name_attr_list'):
            fn_attr = v._as_name_attr_list
        else:
            fn_attr = attr_value_pb2.NameAttrList(name=v.name)
    else:
        raise TypeError(f"Don't know how to convert {repr(v)} to a func for argument {arg_name}")
    return fn_attr

def create_graph_input(self, name: str, type_expr: Any, example_value: Any, before: bool=False, source: Optional[Source]=None) -> fx.Proxy:
    if <MASK>:
        self._input_versions_at_beginning.append(example_value._version)
    log.debug('create_graph_input %s %s %s at debug_level %s before=%s', name, source.name() if source is not None else '(none)', example_value, self.debug_level, before)
    if source is None:
        assert self.parent is not None, f'you are required to provide a source for inputs {name} example_val {example_value} on the root tracer'
    if self.is_export and self.parent is None:
        assert source is not None
        if not is_from_local_source(source, only_allow_input=True):
            self.output_graph.source_to_user_stacks.setdefault(source, []).append(TracingContext.extract_stack())
    name = get_unique_name_wrt(name, self._used_names)
    if self.input_name_to_proxy:
        prev_name = next(reversed(self.input_name_to_proxy))
        node = self.input_name_to_proxy[prev_name].node
        if before:
            ctx = self.graph.inserting_before(node)
        else:
            ctx = self.graph.inserting_after(node)
    else:
        ctx = self.graph.inserting_before(None)
    with ctx:
        proxy = self.create_proxy('placeholder', name, (), {}, type_expr=type_expr)
        set_example_value(proxy.node, example_value)
        if self.input_name_to_proxy and before:
            (k, v) = self.input_name_to_proxy.popitem()
            self.input_name_to_proxy[name] = proxy
            self.input_name_to_proxy[k] = v
        else:
            self.input_name_to_proxy[name] = proxy
        self._used_names.add(name)
        is_strict_export = self.is_export
        is_non_strict_export = torch.compiler.is_compiling()
        if not is_strict_export and (not is_non_strict_export):
            if isinstance(example_value, torch.Tensor):
                self._lift_basic_symbols(example_value, source)
            elif isinstance(example_value, (list, tuple)):
                for (i, e) in enumerate(example_value):
                    if not isinstance(e, torch.Tensor):
                        continue
                    e_source = None
                    if source:
                        e_source = GetItemSource(base=source, index=i, index_is_slice=False)
                    self._lift_basic_symbols(e, e_source)
        if isinstance(example_value, torch.SymInt) and isinstance(example_value.node.expr, sympy.Symbol):
            self.bound_symbols[example_value.node.expr] = proxy
        return proxy

def _AddOpInternal(self, op):
    if <MASK>:
        raise NotImplementedError(f'Operation of type {op.type} ({op.name}) is not supported on the TPU for inference. Execution will fail if this op is used in the graph. Make sure your variables are using variable_scope.')
    if self._outer_context:
        self._outer_context.AddInnerOp(op)

def _get_sample_count(self, n_samples):
    """Compute the number of samples as an integer."""
    if <MASK>:
        if self.subsample < n_samples:
            return self.subsample
        return n_samples
    elif isinstance(self.subsample, numbers.Real):
        return ceil(n_samples * self.subsample)
    return n_samples

def _array_equivalent_object(left: np.ndarray, right: np.ndarray, strict_nan: bool) -> bool:
    left = ensure_object(left)
    right = ensure_object(right)
    mask: npt.NDArray[np.bool_] | None = None
    if <MASK>:
        mask = isna(left) & isna(right)
        if not mask.any():
            mask = None
    try:
        if mask is None:
            return lib.array_equivalent_object(left, right)
        if not lib.array_equivalent_object(left[~mask], right[~mask]):
            return False
        left_remaining = left[mask]
        right_remaining = right[mask]
    except ValueError:
        left_remaining = left
        right_remaining = right
    for (left_value, right_value) in zip(left_remaining, right_remaining, strict=True):
        if left_value is NaT and right_value is not NaT:
            return False
        elif left_value is libmissing.NA and right_value is not libmissing.NA:
            return False
        elif isinstance(left_value, float) and np.isnan(left_value):
            if not isinstance(right_value, float) or not np.isnan(right_value):
                return False
        else:
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', DeprecationWarning)
                try:
                    if np.any(np.asarray(left_value != right_value)):
                        return False
                except TypeError as err:
                    if 'boolean value of NA is ambiguous' in str(err):
                        return False
                    raise
                except ValueError:
                    return False
    return True

def equals(self, other) -> bool:
    if <MASK>:
        return False
    if self.dtype != other.dtype:
        return False
    return bool(array_equivalent(self._ndarray, other._ndarray, dtype_equal=True))

def _initialize_index_label(self, index_label: IndexLabel | None) -> IndexLabel:
    if index_label is not False:
        if <MASK>:
            return self._get_index_label_from_obj()
        elif not isinstance(index_label, (list, tuple, np.ndarray, ABCIndex)):
            return [index_label]
    return index_label

def call_function(self, target: Callable, args: Any, kwargs: dict[str, Any]) -> Any:
    if target is operator.getitem and isinstance(args[0], (list, tuple, dict)):
        return super().call_function(target, args, kwargs)
    if not isinstance(target, torch._ops.OpOverloadPacket) and hasattr(target, '_inductor_lowering_function'):
        return target(*args, **kwargs)
    if target not in lowerings:
        assert isinstance(target, torch._ops.OpOverload), f'{target} is not an OpOverload'
        base_name = target.name().split('.')[0]
        if base_name in FALLBACK_ALLOW_LIST:
            make_fallback(target, warn=False, override_decomp=True)
        elif config.implicit_fallbacks:
            error = MissingOperatorWithDecomp if get_decompositions([target]) else MissingOperatorWithoutDecomp
            log.info('Creating implicit fallback for:\n%s', error.operator_str(target, args, kwargs))
            tag: Optional[torch._C.Tag] = get_layout_constraint_tag(target, with_default=False)
            if tag is None and torch._library.utils.is_builtin(target) and self.is_backward:
                decided_constraint = require_contiguous
            else:
                default_tag: torch._C.Tag = get_layout_constraint_tag(target, with_default=True)
                decided_constraint = tag_to_layout_constraint(default_tag)
            make_fallback(target, layout_constraint=decided_constraint)
        elif get_decompositions([target]):
            raise MissingOperatorWithDecomp(target, args, kwargs)
        else:
            raise MissingOperatorWithoutDecomp(target, args, kwargs)
    try:
        log.debug('  via %s', lowerings[target])
        n = self.current_node
        layout_constraints = maybe_layout_constraints(target)
        if <MASK>:
            (old_args, old_kwargs) = (args, kwargs)
            if layout_constraints is constrain_to_fake_tensors:
                if 'eager_input_vals' in n.meta:
                    (fake_args, fake_kwargs) = n.meta['eager_input_vals']
                    assert isinstance(target, torch._ops.OpOverload)

                    def normalize(args: Any, kwargs: Any) -> tuple[Any, Any]:
                        result = torch.fx.operator_schemas.normalize_function(target, args, kwargs)
                        assert result is not None
                        return (result[0], result[1])
                    (fake_args, fake_kwargs) = normalize(fake_args, fake_kwargs)
                    (args, kwargs) = normalize(args, kwargs)
                    (old_args, old_kwargs) = normalize(old_args, old_kwargs)
                    (args, kwargs) = constrain_to_fake_tensors(args, kwargs, fake_args, fake_kwargs)
            else:
                (args, kwargs) = layout_constraints(n, *args, **kwargs)
        out = lowerings[target](*args, **kwargs)
        if layout_constraints:
            self.propagate_mutation(n, old_args, old_kwargs, args, kwargs)
        return out
    except Exception as e:
        raise LoweringException(e, target, args, kwargs).with_traceback(e.__traceback__) from None

def _untie_named_tensors_map(module: 'torch.nn.Module', parameters_and_buffers: dict[str, Tensor]) -> dict[str, Tensor]:
    """
    Unties all tied tensors in the module to parameters_and_buffers.

    This function returns a new untied_parameters_and_buffers dictionary and leave the original
    untied_parameters_and_buffers dictionary unchanged. It adds new (missing) keys for tied tensors
    in the module to untied_parameters_and_buffers. The value of the new key is the user-given value
    in the original parameters_and_buffers dictionary.

    If there are more than one user-given values for the same tied tensor, it will raise an error.

    For example, if the module has two tied weights self.foo and self.tied_foo and the user passes
    {'foo': foo_value, ...}, this will return {'foo': foo_value, 'tied_foo': foo_value, ...}. If the
    user passes {'foo': foo_value, 'tied_foo': tied_foo_value, ...}, it will raise an error. If the
    user passes {'foo': foo_value, 'tied_foo': foo_value, ...}, it will not raise an error.

    Args:
        module (torch.nn.Module): the module to determine which tensors are tied.
        parameters_and_buffers (Dict[str, Tensor]): a map of {name: tensor} for reparamaterizing the module.

    Returns:
        A new untied version of the parameters_and_buffers dictionary.

    Raises:
        ValueError: if there are more than one user-given values for the same tied tensor.
    """
    all_named_tensors: dict[str, Tensor] = {}
    all_named_tensors.update(module.named_parameters(remove_duplicate=False))
    all_named_tensors.update(module.named_buffers(remove_duplicate=False))
    tensor_to_tied_names_map: dict[Tensor, set[str]] = {}
    for (name, tensor) in all_named_tensors.items():
        if tensor not in tensor_to_tied_names_map:
            tensor_to_tied_names_map[tensor] = set()
        tensor_to_tied_names_map[tensor].add(name)
    tied_names_map: dict[str, set[str]] = {}
    for tied_names in tensor_to_tied_names_map.values():
        if <MASK>:
            for tied_name in tied_names:
                tied_names_map[tied_name] = tied_names
    given_names = set(parameters_and_buffers.keys())
    given_names_for_tied_tensors: set[str] = set()
    for name in given_names:
        if name in tied_names_map:
            given_names_for_tied_tensors.add(name)
    for given_name in given_names_for_tied_tensors:
        tied_names = tied_names_map[given_name]
        if len(tied_names.intersection(given_names_for_tied_tensors)) > 1 and len({parameters_and_buffers[tied_name] for tied_name in tied_names}) != 1:
            raise ValueError(f'functional_call got multiple values for keys {sorted(tied_names)}, which are tied. Consider using tie_weights=False')
    untied_parameters_and_buffers = parameters_and_buffers.copy()
    for given_name in given_names_for_tied_tensors:
        for tied_name in tied_names_map[given_name]:
            untied_parameters_and_buffers[tied_name] = parameters_and_buffers[given_name]
    return untied_parameters_and_buffers

