def benchmark_when_ready() -> bool:
    from torch._inductor.runtime.triton_heuristics import NoTritonConfigsError
    try:
        for fut in (future_and_mod_l1[0], future_and_mod_l2[0], future_and_mod_l1_fused[0]):
            if fut is not None:
                fut.result()
        (ms1, path1) = self.benchmark_codegened_module(future_and_mod_l1[1], device)
        if <MASK>:
            why('register spilling of the first kernel')
            return False
        (ms2, path2) = self.benchmark_codegened_module(future_and_mod_l2[1], device)
        if math.isinf(ms2):
            why('register spilling of the second kernel')
            return False
        (ms_fused, path_fused) = self.benchmark_codegened_module(future_and_mod_l1_fused[1], device)
        if math.isinf(ms_fused):
            why('register spilling of the fused kernel')
            return False
        log_fusion(ms_fused, ms1, ms2)
        if is_metric_table_enabled('slow_fusion') and ms_fused >= ms1 + ms2 and ((path1, path2) not in self.logged_slow_fusion):
            self.logged_slow_fusion.add((path1, path2))
            get_metric_table('slow_fusion').add_row(lambda : {'kernel1_path': path1, 'kernel1_latency': ms1, 'kernel2_path': path2, 'kernel2_latency': ms2, 'fused_kernel_path': path_fused, 'fused_kernel_latency': ms_fused, 'slow_down_ratio': ms_fused / (ms1 + ms2)})
        return ms_fused < ms1 + ms2
    except NoTritonConfigsError:
        return False
    except CompilationError as e:
        if 'Loop-carried variable' in str(e):
            return True
        raise

def _is_packable_linear(match):
    """
        Check if the node is supported for MKLDNN linear.
        """

    def is_const_or_cat_by_const(weight):
        if weight.op == 'get_attr':
            return True
        if weight.target != aten.cat.default:
            return False
        return all((arg.op == 'get_attr' for arg in weight.args[0]))
    linear_node = match.output_node()
    if linear_node.target == aten.addmm.default:
        alpha = linear_node.kwargs.get('alpha', 1.0)
        beta = linear_node.kwargs.get('beta', 1.0)
        if beta != 0.0 and beta != 1.0 or alpha != 1.0:
            return False
    weight_idx = 2 if linear_node.target == aten.addmm.default else 1
    if not is_const_or_cat_by_const(linear_node.args[weight_idx]):
        return False
    input_meta_value = linear_node.args[weight_idx - 1].meta.get('val')
    weight_meta_value = linear_node.args[weight_idx].meta.get('val')
    if input_meta_value is None or weight_meta_value is None:
        return False
    if input_meta_value.dtype == torch.float64 or weight_meta_value.dtype == torch.float64:
        return False
    is_lp_weight = weight_meta_value.dtype in (torch.bfloat16, torch.float16)
    reduced_f32_matmul_enabled = torch.backends.mkldnn.matmul.fp32_precision in ['bf16', 'tf32']
    use_reduced_f32_for_fp32_weight = reduced_f32_matmul_enabled and weight_meta_value.dtype == torch.float32
    compute_with_lp = is_lp_weight or use_reduced_f32_for_fp32_weight
    if not compute_with_lp and (not mkldnn._is_mkldnn_acl_supported()) and (not torch._C.has_mkl):
        return False
    for meta_value in [input_meta_value, weight_meta_value]:
        if meta_value is None or meta_value.device.type != 'cpu' or meta_value.dim() != 2:
            return False
    if <MASK>:
        bias_meta_value = linear_node.args[0].meta.get('val')
        if bias_meta_value is None or meta_value.device.type != 'cpu' or bias_meta_value.dim() != 1 or (bias_meta_value.size(0) != weight_meta_value.size(1)):
            return False
    device_type = input_meta_value.device.type
    if input_meta_value.dtype == torch.bfloat16 or weight_meta_value.dtype == torch.bfloat16:
        if not is_mkldnn_bf16_supported(device_type):
            return False
    if input_meta_value.dtype == torch.float16 or weight_meta_value.dtype == torch.float16:
        if not is_mkldnn_fp16_supported(device_type):
            return False
    return True

def sdpa_constraint(fx_node, *args, **kwargs):

    def apply_constraint(idx, arg, fx_arg):
        if not isinstance(arg, ir.IRNode):
            return arg
        meta_val = fx_arg.meta['val']
        meta_stride_expr = [s.node.expr if isinstance(s, torch.SymInt) else s for s in meta_val.stride()]
        shape_env = V.graph.sizevars.shape_env
        stride_order = ir.get_stride_order(meta_val.stride(), shape_env)
        if stride_order and stride_order[-1] != 0:
            stride_order = list(reversed(range(len(arg.get_size()))))
        if fx_node.target == aten._scaled_dot_product_efficient_attention_backward.default and idx in (0, 5):
            assert len(stride_order) == 4
            stride_order = (3, 1, 2, 0)
        if not meta_val.is_cuda:
            return ir.ExternKernel.require_stride_order(arg, stride_order)
        ALIGNMENT = 8
        effn_attn_fwd_bias = fx_node.target == torch.ops.aten._scaled_dot_product_efficient_attention.default and idx == 3
        assert isinstance(arg, TensorBox)
        if len(arg.get_size()) not in (3, 4):
            return arg
        is_aligned_tensor = ir.is_aligned_realized_tensor(arg, ALIGNMENT)
        if is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if <MASK>:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if effn_attn_fwd_bias:
            out_size = list(arg.get_size())
            expanded_dims = []
            maybe_stride = arg.maybe_get_stride()
            for i in range(len(arg.get_size()) - 1):
                if V.graph.sizevars.statically_known_equals(meta_stride_expr[i], 0) or (maybe_stride is not None and V.graph.sizevars.statically_known_equals(maybe_stride[i], 0)):
                    expanded_dims.append(i)
            out_strides = [-1] * len(out_size)
            out_strides[-1] = 1
            stride = 1
            for i in range(len(out_size) - 2, -1, -1):
                if out_strides[i + 1] != 0:
                    stride = stride * out_size[i + 1]
                if i in expanded_dims:
                    if V.graph.sizevars.statically_known_equals(out_strides[i + 1] % ALIGNMENT, 0):
                        out_strides[i] = 0
                        continue
                if not V.graph.sizevars.statically_known_equals(stride % ALIGNMENT, 0):
                    stride = ceildiv(stride, ALIGNMENT) * ALIGNMENT
                out_strides[i] = stride
            return ir.ExternKernel.require_exact_strides(arg, out_strides)
        if is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if isinstance(arg, IRNode) and arg.maybe_get_stride() is not None and is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)

        def is_aligned(x):
            return V.graph.sizevars.guard_or_false(sympy.Eq(Mod(x.get_size()[-1], ALIGNMENT), 0))
        if isinstance(arg.data, ir.BaseView):
            if not is_aligned(arg):
                if is_aligned(arg.unwrap_view()):
                    return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        return ir.ExternKernel.require_stride_order(arg, stride_order)
    args = tuple((apply_constraint(idx, arg, fx_arg) for (idx, (arg, fx_arg)) in enumerate(zip(args, fx_node.args))))
    kwargs = {k: apply_constraint(-1, v, fx_node.kwargs[k]) for (k, v) in kwargs.items()}
    return (args, kwargs)

def _copy_some_through(current, candidate):
    """Copy some tensors through via array_ops.where."""

    def copy_fn(cur_i, cand_i):
        if <MASK>:
            return cand_i
        if cur_i.shape.rank == 0:
            return cand_i
        with ops.colocate_with(cand_i):
            return array_ops.where(elements_finished, cur_i, cand_i)
    return nest.map_structure(copy_fn, current, candidate)

def get_info(self, notfound_action=0):
    """ Return a dictionary with items that are compatible
            with numpy.distutils.setup keyword arguments.
        """
    flag = 0
    if not self.has_info():
        flag = 1
        log.info(self.__class__.__name__ + ':')
        if <MASK>:
            self.calc_info()
        if notfound_action:
            if not self.has_info():
                if notfound_action == 1:
                    warnings.warn(self.notfounderror.__doc__, stacklevel=2)
                elif notfound_action == 2:
                    raise self.notfounderror(self.notfounderror.__doc__)
                else:
                    raise ValueError(repr(notfound_action))
        if not self.has_info():
            log.info('  NOT AVAILABLE')
            self.set_info()
        else:
            log.info('  FOUND:')
    res = self.saved_results.get(self.__class__.__name__)
    if log.get_threshold() <= log.INFO and flag:
        for (k, v) in res.items():
            v = str(v)
            if k in ['sources', 'libraries'] and len(v) > 270:
                v = v[:120] + '...\n...\n...' + v[-120:]
            log.info('    %s = %s', k, v)
        log.info('')
    return copy.deepcopy(res)

def post_backward(self, *unused: Any):
    if not compiled_autograd_enabled():
        logger.debug('%s', self._with_fqn('FSDP::post_backward'))
    self._training_state = TrainingState.POST_BACKWARD
    with record_function(self._with_fqn('FSDP::post_backward_accumulate')):
        for fsdp_param in self.fsdp_params:
            fsdp_param.accumulate_unsharded_grad_if_needed()
    with record_function(self._with_fqn('FSDP::post_backward_reshard')):
        if not self.reduce_grads:
            if self.reshard_after_backward:
                self.reshard()
            for fsdp_param in self.fsdp_params:
                fsdp_param.to_accumulated_grad_if_needed()
            return
        fsdp_params_with_grad: list[FSDPParam] = []
        unsharded_grads: list[torch.Tensor] = []
        for fsdp_param in self.fsdp_params:
            if not hasattr(fsdp_param, '_unsharded_param'):
                continue
            if fsdp_param.unsharded_accumulated_grad is not None:
                fsdp_params_with_grad.append(fsdp_param)
                unsharded_grads.append(fsdp_param.unsharded_accumulated_grad_data)
                fsdp_param.unsharded_accumulated_grad = None
            elif fsdp_param.unsharded_param.grad is not None:
                fsdp_params_with_grad.append(fsdp_param)
                unsharded_grads.append(fsdp_param.unsharded_grad_data)
                fsdp_param.unsharded_param.grad = None
        if self.reshard_after_backward:
            self.reshard()
    if len(fsdp_params_with_grad) == 0:
        return
    with record_function(self._with_fqn('FSDP::post_backward_reduce')):
        if self.comm_ctx.reduce_scatter_state is not None and self.comm_ctx.reduce_scatter_state.event is not None:
            self.device_handle.current_stream().wait_event(self.comm_ctx.reduce_scatter_state.event)
        self.comm_ctx.reduce_scatter_state = None
        all_reduce_pg = self._all_reduce_process_group if self._is_hsdp else None
        all_reduce_stream: torch.cuda.Stream
        if all_reduce_pg is None and self._all_reduce_hook_stream is not None:
            if self._all_reduce_hook is None:
                raise AssertionError('all reduce hook stream is specified but hook itself is missing.')
            all_reduce_stream = self._all_reduce_hook_stream
        else:
            all_reduce_stream = self.comm_ctx.all_reduce_stream
        self._wait_for_post_backward()
        (reduce_scatter_input, reduce_scatter_event, self._post_reduce_event, all_reduce_input, all_reduce_event, self._partial_reduce_output) = foreach_reduce(fsdp_params_with_grad, unsharded_grads, self._reduce_scatter_process_group, self.comm_ctx.reduce_scatter_stream, self._reduce_scatter_comm, self._orig_dtype, self._reduce_dtype, self.device, self.gradient_divide_factor, self._all_reduce_process_group if self._is_hsdp else None, all_reduce_stream, self.all_reduce_grads, self._partial_reduce_output, self._all_reduce_hook, self.force_sum_reduction_for_comms)
        self.comm_ctx.reduce_scatter_state = ReduceScatterState(reduce_scatter_input, reduce_scatter_event)
        if <MASK>:
            if self.device.type != 'cpu':
                if all_reduce_event is None:
                    raise AssertionError('Expected all_reduce_event to be set for non-CPU device')
            self._all_reduce_state = AllReduceState(all_reduce_input, all_reduce_event)

def prepare_database(self):
    super().prepare_database()
    with self.cursor() as cursor:
        cursor.execute('SELECT 1 FROM pg_extension WHERE extname = %s', ['postgis'])
        if <MASK>:
            return
        cursor.execute('CREATE EXTENSION IF NOT EXISTS postgis')
        if is_psycopg3:
            self.register_geometry_adapters(self.connection, True)

def _make_indexed_slices_indices_types_match(op_type, branch_graphs):
    """Match dtype of IndexedSlices.indices in outputs of branch_graphs."""
    assert branch_graphs
    indexed_slice_indices = []
    current_index = 0
    branch_outputs_flat_with_composites = [nest.flatten(branch_graph.structured_outputs, expand_composites=False) for branch_graph in branch_graphs]
    outs_per_branch = [len(outs) for outs in branch_outputs_flat_with_composites]
    assert len(set(outs_per_branch)) == 1, outs_per_branch
    for (output_idx, branch_outs) in enumerate(zip(*branch_outputs_flat_with_composites)):
        if len(set((isinstance(out, indexed_slices.IndexedSlices) for out in branch_outs))) != 1:
            raise TypeError('Cannot reconcile tf.{op_name} {output_idx}-th outputs:\n  branches returned: {outputs}'.format(op_name='cond' if op_type == _COND else 'switch_case', output_idx=output_idx, outputs=branch_outs))
        if isinstance(branch_outs[0], indexed_slices.IndexedSlices):
            indexed_slice_indices.append(current_index + 1)
        if nest.is_nested_or_composite(branch_outs[0]):
            current_index += len(nest.flatten(branch_outs[0], expand_composites=True))
        elif branch_outs[0] is not None:
            current_index += 1
    if not indexed_slice_indices:
        return
    if current_index != len(branch_graphs[0].outputs):
        raise ValueError('Insufficient elements in branch_graphs[0].outputs.\nExpected: %i\nActual: %i' % (current_index, len(branch_graphs[0].outputs)))
    for index in indexed_slice_indices:
        if any((bg.outputs[index].dtype not in (dtypes.int32, dtypes.int64) for bg in branch_graphs)):
            raise TypeError('Type of IndexedSlices.indices must be int32 or int64. Found: %s' % str([bg.outputs[index].dtype for bg in branch_graphs]))
        if <MASK>:
            for branch_graph in branch_graphs:
                if branch_graph.outputs[index].dtype == dtypes.int32:
                    with branch_graph.as_default():
                        branch_graph.outputs[index] = math_ops.cast(branch_graph.outputs[index], dtypes.int64)
    for branch_graph in branch_graphs:
        branch_graph.structured_outputs = _pack_sequence_as(branch_graph.structured_outputs, branch_graph.outputs)

def IsCPUTargetAvailable(target):
    if target.startswith('arm'):
        return _pywrap_util_port.IsAArch32Available()
    elif target.startswith('aarch64'):
        return _pywrap_util_port.IsAArch64Available()
    elif target.startswith('ppc') or target.startswith('powerpc'):
        return _pywrap_util_port.IsPowerPCAvailable()
    elif target.startswith('x86'):
        return _pywrap_util_port.IsX86Available()
    elif <MASK>:
        return _pywrap_util_port.IsSystemZAvailable()
    assert False, 'Unknown CPU target: ' + target

def rfftfreq(n: int, /, xp: Namespace, *, d: float=1.0, dtype: DType | None=None, device: Device | None=None) -> Array:
    if device not in ['cpu', None]:
        raise ValueError(f'Unsupported device {device!r}')
    res = xp.fft.rfftfreq(n, d=d)
    if <MASK>:
        return res.astype(dtype)
    return res

@impl(quantized_decomposed_lib, 'quantize_per_tensor', 'Meta')
def quantize_per_tensor_meta(input: torch.Tensor, scale: float, zero_point: int, quant_min: int, quant_max: int, dtype: torch.dtype) -> torch.Tensor:
    if <MASK>:
        input = input.to(torch.float32)
    assert input.dtype == torch.float32, f'Expecting input to have dtype torch.float32, but got dtype: {input.dtype}'
    return torch.empty_like(input, dtype=dtype)

def __init__(self, cls, doc=None, modulename='', func_doc=FunctionDoc, config=None):
    if not inspect.isclass(cls) and cls is not None:
        raise ValueError(f'Expected a class or None, but got {cls!r}')
    self._cls = cls
    if 'sphinx' in sys.modules:
        from sphinx.ext.autodoc import ALL
    else:
        ALL = object()
    if config is None:
        config = {}
    self.show_inherited_members = config.get('show_inherited_class_members', True)
    if modulename and (not modulename.endswith('.')):
        modulename += '.'
    self._mod = modulename
    if doc is None:
        if <MASK>:
            raise ValueError('No class or documentation string given')
        doc = pydoc.getdoc(cls)
    NumpyDocString.__init__(self, doc)
    _members = config.get('members', [])
    if _members is ALL:
        _members = None
    _exclude = config.get('exclude-members', [])
    if config.get('show_class_members', True) and _exclude is not ALL:

        def splitlines_x(s):
            if not s:
                return []
            else:
                return s.splitlines()
        for (field, items) in [('Methods', self.methods), ('Attributes', self.properties)]:
            if not self[field]:
                doc_list = []
                for name in sorted(items):
                    if name in _exclude or (_members and name not in _members):
                        continue
                    try:
                        doc_item = pydoc.getdoc(getattr(self._cls, name))
                        doc_list.append(Parameter(name, '', splitlines_x(doc_item)))
                    except AttributeError:
                        pass
                self[field] = doc_list

def move_to_device_pass(ep: ExportedProgram, location: Union[torch.device, str, dict[str, str]]) -> ExportedProgram:
    """
    Move the exported program to the given device.

    Args:
        ep (ExportedProgram): The exported program to move.
        location (Union[torch.device, str, Dict[str, str]]): The device to move the exported program to.
            If a string, it is interpreted as a device name.
            If a dict, it is interpreted as a mapping from
            the existing device to the intended one

    Returns:
        ExportedProgram: The moved exported program.
    """

    def _get_new_device(curr_device: torch.device, location: Union[torch.device, str, dict[str, str]]) -> str:
        if isinstance(location, dict):
            if str(curr_device) in location.keys():
                return location[str(curr_device)]
            else:
                return str(curr_device)
        else:
            return str(location)
    for (k, v) in ep.state_dict.items():
        if isinstance(v, torch.nn.Parameter):
            ep._state_dict[k] = torch.nn.Parameter(v.to(_get_new_device(v.device, location)), v.requires_grad)
        else:
            ep._state_dict[k] = v.to(_get_new_device(v.device, location))
    for (k, v) in ep.constants.items():
        if isinstance(v, torch.Tensor):
            ep._constants[k] = v.to(_get_new_device(v.device, location))
    if ep.example_inputs is not None:
        (args, kwargs) = ep.example_inputs
        moved_args = pytree.tree_map_only(torch.Tensor, lambda tensor: tensor.to(_get_new_device(tensor.device, location)), args)
        moved_kwargs = pytree.tree_map_only(torch.Tensor, lambda tensor: tensor.to(_get_new_device(tensor.device, location)), kwargs)
        ep._example_inputs = (moved_args, moved_kwargs)
    for m in ep.graph_module.modules():
        if isinstance(m, torch.fx.GraphModule):
            for node in m.graph.nodes:
                if <MASK>:
                    kwargs = node.kwargs.copy()
                    kwargs['device'] = _get_new_device(kwargs['device'], location)
                    node.kwargs = kwargs
                if node.op == 'call_function' and node.target == torch.ops.aten.to.device:
                    args = list(node.args)
                    args[1] = _get_new_device(args[1], location)
                    node.args = tuple(args)
                node.meta['val'] = pytree.tree_map(lambda v: v.to(_get_new_device(v.device, location)) if isinstance(v, torch.Tensor) else v, node.meta.get('val'))
    ep.validate()
    return ep

def compute_elementwise_output_logical_to_physical_perm(*tensors, _skip_checks=False, ambiguity_check=False) -> tuple[list[int], bool]:
    from torch.fx.experimental.symbolic_shapes import guard_or_false
    if not _skip_checks and len(tensors) == 0:
        msg = "Can't compute elementwise output strides for zero tensors!"
        raise ValueError(msg)
    if <MASK>:
        check_same_shape(*tensors, allow_cpu_scalar_tensors=True)
    if not _skip_checks:
        tensors = tuple((a for a in tensors if isinstance(a, TensorLike) and (not is_cpu_scalar_tensor(a))))
    if len(tensors) == 0:
        return ([], False)
    ndim = tensors[0].ndim
    if ndim == 0:
        return ([], False)
    if ndim == 1:
        return ([0], False)
    is_contiguous = True
    is_channels_last = True
    for t in tensors:
        is_contiguous = is_contiguous and is_contiguous_for_memory_format_or_false(t, memory_format=torch.contiguous_format)
        is_channels_last = is_channels_last and is_contiguous_for_memory_format_or_false(t, memory_format=torch.channels_last)
    if is_contiguous and (not is_channels_last):
        return (list(range(ndim)), False)
    if is_channels_last and (not is_contiguous):
        return ([0, *list(range(2, ndim)), 1], False)
    shape = tensors[0].shape

    def should_swap(idx_a, idx_b):

        def ge(a, b):
            """
            Returns true if a is symbolically greater than or equal to b, assuming a >= 0, b >= 0.
            """
            if guard_or_false(b == 0):
                return True
            elif guard_or_false(a == 0):
                return False
            return guard_or_false(a >= b) or guard_or_false(a % b == 0)
        for tensor in tensors:
            stride_a = tensor.stride()[idx_a]
            stride_b = tensor.stride()[idx_b]
            if guard_or_false(stride_a == 0) or guard_or_false(stride_b == 0):
                continue
            if guard_or_false(stride_a == stride_b):
                if ge(shape[idx_b], shape[idx_a]):
                    continue
                return 1
            if ge(stride_b, stride_a):
                return -1
            if ge(stride_a, stride_b):
                return 1
        return 0
    perm = list(reversed(range(ndim)))
    for i in range(1, ndim):
        dim1 = i
        for dim0 in reversed(range(i)):
            comparison = should_swap(perm[dim0], perm[dim1])
            if comparison > 0:
                (perm[dim0], perm[dim1]) = (perm[dim1], perm[dim0])
                dim1 = dim0
            elif comparison < 0:
                break
    raise_ambiguous = False
    if ambiguity_check:
        for (i, j) in zip(range(ndim - 1), range(1, ndim)):
            order = should_swap(perm[i], perm[j])
            if order != -1:
                raise_ambiguous = True
                break
    return (list(reversed(perm)), raise_ambiguous)

@functools.cache
def non_compute_operator(op):
    schema = op._schema
    if not any((contains_tensor_types(arg.type) for arg in schema.arguments)):
        return True
    if '_like' in op.name():
        return True
    if schema.is_mutable:
        return False
    tensor_inps = [arg for arg in schema.arguments if arg.type is tensor_type]
    tensor_outputs = [ret for ret in schema.returns if ret.type is tensor_type]
    if <MASK>:
        return False
    for inp in tensor_inps:
        if inp.alias_info and tensor_outputs[0].alias_info:
            if inp.alias_info.before_set.intersection(tensor_outputs[0].alias_info.after_set):
                return True
    return False

def _remove_redundant_sym_size_ops(self) -> None:
    """
        Deletes torch.ops.sym_size.int operators whose output is a
        corresponding placeholder that holds the same symbol, and replace all usage
        of the sym_size node to be directly using the placeholders.

        This is to make sure all basic symbols come from inputs.
        """
    placeholder_exprs = {}
    for node in self.joint_gm.graph.nodes:
        if isinstance(node, torch.fx.Node) and node.op == 'placeholder' and hasattr(node, 'meta') and ('val' in node.meta):
            val = node.meta['val']
            if <MASK>:
                placeholder_exprs[val.node.expr] = node
    nodes_to_remove = []
    for node in self.joint_gm.graph.find_nodes(op='call_function', target=torch.ops.aten.sym_size.int):
        assert hasattr(node, 'meta') and 'val' in node.meta, node
        val = node.meta['val']
        expr = val.node.expr
        if expr in placeholder_exprs:
            placeholder_node = placeholder_exprs[expr]
            node.replace_all_uses_with(placeholder_node)
            nodes_to_remove.append(node)
    for node in nodes_to_remove:
        self.joint_gm.graph.erase_node(node)
    self.joint_gm.graph.lint()
    self.joint_gm.recompile()

def draft_export(mod: torch.nn.Module, args: tuple[Any, ...], kwargs: Optional[Mapping[str, Any]]=None, *, dynamic_shapes: Optional[Union[dict[str, Any], tuple[Any], list[Any]]]=None, preserve_module_call_signature: tuple[str, ...]=(), strict: bool=False, pre_dispatch: bool=True, prefer_deferred_runtime_asserts_over_guards: bool=False) -> ExportedProgram:
    start_time = time.time()
    kwargs = kwargs or {}
    dynamic_shapes = dynamic_shapes or {}
    constraint_violation_msg = None
    capture_structured_log = CaptureStructuredTrace()
    with torch._functorch.config.patch(fake_tensor_propagate_real_tensors=True, generate_fake_kernels_from_real_mismatches=True), capture_structured_log:
        try:
            new_shapes = None
            ep = _export(mod, args, kwargs, dynamic_shapes=dynamic_shapes, strict=strict, pre_dispatch=pre_dispatch, preserve_module_call_signature=preserve_module_call_signature, prefer_deferred_runtime_asserts_over_guards=prefer_deferred_runtime_asserts_over_guards)
        except Exception as exc:
            if isinstance(exc, UserError) and exc.error_type == UserErrorType.CONSTRAINT_VIOLATION:
                constraint_violation_msg = exc.msg

                def convert_dim_to_auto(dim: Any) -> Any:
                    if isinstance(dim, Dim):
                        return Dim.AUTO(min=dim.min, max=dim.max)
                    elif isinstance(dim, _DimHint) and dim.type == _DimHintType.DYNAMIC:
                        return Dim.AUTO(min=dim.min, max=dim.max)
                    return dim
                new_shapes = pytree.tree_map(convert_dim_to_auto, dynamic_shapes)
                ep = _export(mod, args, kwargs, dynamic_shapes=new_shapes, strict=strict, pre_dispatch=pre_dispatch, preserve_module_call_signature=preserve_module_call_signature, prefer_deferred_runtime_asserts_over_guards=prefer_deferred_runtime_asserts_over_guards)
            else:
                log_draft_export_usage(error=True, export_time=time.time() - start_time, strict=strict, message=str(exc), type=f'{type(exc).__name__}.{type(exc).__qualname__}')
                raise exc
        torch._logging.dtrace_structured('exported_program', payload_fn=lambda : str(ep))
        str_to_filename: dict[int, str] = {}
        failures: list[FailureReport] = []
        incorrect_custom_ops: set[str] = set()
        expressions_created: dict[int, dict[str, Any]] = {}
        for (log_name, log_contents) in capture_structured_log.log_record.logs:
            failure_type = None
            if log_name == 'str':
                str_to_filename[log_contents[1]] = log_contents[0]
                continue
            elif <MASK>:
                log_contents['occurrences'] = capture_structured_log.log_record.get_log_count((log_name, log_contents))
                failure_type = FailureType.DATA_DEPENDENT_ERROR
            elif log_name == 'guard_added':
                if new_shapes is None:
                    continue
                failure_type = FailureType.GUARD_ADDED
                log_contents['new_dynamic_shapes'] = new_shapes
            elif log_name == 'missing_fake_kernel':
                failure_type = FailureType.MISSING_FAKE_KERNEL
                incorrect_custom_ops.add(log_contents['op'])
            elif log_name == 'mismatched_fake_kernel':
                failure_type = FailureType.MISMATCHED_FAKE_KERNEL
                incorrect_custom_ops.add(log_contents['op'])
            else:
                continue
            assert failure_type is not None
            failures.append(FailureReport(failure_type, log_contents))
        for (k, v) in capture_structured_log.expression_created_logs.items():
            if v.visited:
                expressions_created[k] = v.record
        op_profiles = get_op_profiles(ep.graph_module, incorrect_custom_ops)
        report = DraftExportReport(failures, str_to_filename, expressions_created, op_profiles)
        insert_custom_op_guards(ep.graph_module, incorrect_custom_ops)
    ep._report = report
    if not report.successful():
        log_filename = capture_structured_log.stream.name
        warning_msg = f'\n###################################################################################################\nWARNING: {len(report.failures)} issue(s) found during export, and it was not able to soundly produce a graph.\nTo view the report of failures in an html page, please run the command:\n    `tlparse {log_filename} --export`\nOr, you can view the errors in python by inspecting `print(ep._report)`.\n'
        if len(report.op_profiles) > 0:
            warning_msg += f'\nWhile tracing we found {len(report.op_profiles)} operator(s) which do not have a fake kernel registered.\nIf you intend to retrace the exported graph or run it with fake tensors, please run it under the\nfollowing context manager, which will register a fake kernel for those operators.\n```\nwith torch._library.fake_profile.unsafe_generate_fake_kernels(ep._report.op_profiles):\n    # run with fake tensors\n```\n'
        warning_msg += '#################################################################################################'
        log.warning(warning_msg)
    else:
        log.info('\n##############################################################################################\nCongratuations: No issues are found during export, and it was able to soundly produce a graph.\nYou can now change back to torch.export.export()\n##############################################################################################\n    ')
    log_draft_export_usage(error=False, export_time=time.time() - start_time, strict=strict, constraint_violations=constraint_violation_msg, report=ep._report, **get_ep_stats(ep))
    return ep

def _add_default_callbacks(self, add_history, add_progbar):
    """Adds `Callback`s that are always present."""
    self._progbar = None
    self._history = None
    for cb in self.callbacks:
        if <MASK>:
            self._progbar = cb
        elif isinstance(cb, History):
            self._history = cb
    if self._progbar is None and add_progbar:
        self._progbar = ProgbarLogger(count_mode='steps')
        self.callbacks.insert(0, self._progbar)
    if self._history is None and add_history:
        self._history = History()
        self.callbacks.append(self._history)

def check_raster(self, lookup, template_params):
    spheroid = lookup.rhs_params and lookup.rhs_params[-1] == 'spheroid'
    lhs_is_raster = lookup.lhs.field.geom_type == 'RASTER'
    rhs_is_raster = isinstance(lookup.rhs, GDALRaster)
    if lookup.band_lhs is not None and lhs_is_raster:
        if <MASK>:
            raise ValueError('Band indices are not allowed for this operator, it works on bbox only.')
        template_params['lhs'] = '%s, %s' % (template_params['lhs'], lookup.band_lhs)
    if lookup.band_rhs is not None and rhs_is_raster:
        if not self.func:
            raise ValueError('Band indices are not allowed for this operator, it works on bbox only.')
        template_params['rhs'] = '%s, %s' % (template_params['rhs'], lookup.band_rhs)
    if not self.raster or spheroid:
        if lhs_is_raster:
            template_params['lhs'] = 'ST_Polygon(%s)' % template_params['lhs']
        if rhs_is_raster:
            template_params['rhs'] = 'ST_Polygon(%s)' % template_params['rhs']
    elif self.raster == BILATERAL:
        if lhs_is_raster and (not rhs_is_raster):
            template_params['lhs'] = 'ST_Polygon(%s)' % template_params['lhs']
        elif rhs_is_raster and (not lhs_is_raster):
            template_params['rhs'] = 'ST_Polygon(%s)' % template_params['rhs']
    return template_params

def _convert_grouper(axis: Index, grouper):
    if isinstance(grouper, dict):
        return grouper.get
    elif isinstance(grouper, Series):
        if grouper.index.equals(axis):
            return grouper._values
        else:
            return grouper.reindex(axis)._values
    elif isinstance(grouper, MultiIndex):
        return grouper._values
    elif isinstance(grouper, (list, tuple, Index, Categorical, np.ndarray)):
        if <MASK>:
            raise ValueError('Grouper and axis must be same length')
        if isinstance(grouper, (list, tuple)):
            grouper = com.asarray_tuplesafe(grouper)
        return grouper
    else:
        return grouper

def visit(expr, found=found):
    if expr.op is Op.FACTORS:
        for b in expr.data:
            b.traverse(visit)
        return expr
    if <MASK>:
        return
    if expr.op is Op.APPLY and isinstance(expr.data[0], ArithOp):
        if expr.data[0] is ArithOp.POW:
            expr.data[1][0].traverse(visit)
            return expr
        return
    if expr.op in (Op.INTEGER, Op.REAL):
        return expr
    found.add(expr)
    if expr.op in (Op.INDEXING, Op.APPLY):
        return expr

def build_all_signature_defs(receiver_tensors, export_outputs, receiver_tensors_alternatives=None, serving_only=True):
    """Build `SignatureDef`s for all export outputs.

  Args:
    receiver_tensors: a `Tensor`, or a dict of string to `Tensor`, specifying
      input nodes where this receiver expects to be fed by default.  Typically,
      this is a single placeholder expecting serialized `tf.Example` protos.
    export_outputs: a dict of ExportOutput instances, each of which has
      an as_signature_def instance method that will be called to retrieve
      the signature_def for all export output tensors.
    receiver_tensors_alternatives: a dict of string to additional
      groups of receiver tensors, each of which may be a `Tensor` or a dict of
      string to `Tensor`.  These named receiver tensor alternatives generate
      additional serving signatures, which may be used to feed inputs at
      different points within the input receiver subgraph.  A typical usage is
      to allow feeding raw feature `Tensor`s *downstream* of the
      tf.io.parse_example() op.  Defaults to None.
    serving_only: boolean; if true, resulting signature defs will only include
      valid serving signatures. If false, all requested signatures will be
      returned.

  Returns:
    signature_def representing all passed args.

  Raises:
    ValueError: if export_outputs is not a dict
  """
    if <MASK>:
        receiver_tensors = {SINGLE_RECEIVER_DEFAULT_NAME: receiver_tensors}
    if export_outputs is None or not isinstance(export_outputs, dict):
        raise ValueError('export_outputs must be a dict and not{}'.format(type(export_outputs)))
    signature_def_map = {}
    excluded_signatures = {}
    for (output_key, export_output) in export_outputs.items():
        signature_name = '{}'.format(output_key or 'None')
        try:
            signature = export_output.as_signature_def(receiver_tensors)
            signature_def_map[signature_name] = signature
        except ValueError as e:
            excluded_signatures[signature_name] = str(e)
    if receiver_tensors_alternatives:
        for (receiver_name, receiver_tensors_alt) in receiver_tensors_alternatives.items():
            if not isinstance(receiver_tensors_alt, dict):
                receiver_tensors_alt = {SINGLE_RECEIVER_DEFAULT_NAME: receiver_tensors_alt}
            for (output_key, export_output) in export_outputs.items():
                signature_name = '{}:{}'.format(receiver_name or 'None', output_key or 'None')
                try:
                    signature = export_output.as_signature_def(receiver_tensors_alt)
                    signature_def_map[signature_name] = signature
                except ValueError as e:
                    excluded_signatures[signature_name] = str(e)
    _log_signature_report(signature_def_map, excluded_signatures)
    if serving_only:
        signature_def_map = {k: v for (k, v) in signature_def_map.items() if signature_def_utils.is_valid_signature(v)}
    return signature_def_map

def _has_infs(result) -> bool:
    if isinstance(result, np.ndarray):
