def _make_collective_ops_with_fallbacks(self):
    self._collective_keys = cross_device_utils.CollectiveKeys(group_key_start=1 + self._collective_key_base)
    if <MASK>:
        return cross_device_ops_lib.ReductionToOneDevice()
    if any(('cpu' in d.lower() for d in self._devices)) and any(('gpu' in d.lower() for d in self._devices)):
        return cross_device_ops_lib.ReductionToOneDevice()
    if all(('cpu' in d.lower() for d in self._devices)):
        self._communication_options = collective_util.Options(implementation=collective_util.CommunicationImplementation.RING)
    else:
        physical_gpus = context.context().list_physical_devices(device_type='GPU')
        logical_gpus = context.context().list_logical_devices(device_type='GPU')
        if len(physical_gpus) < len(logical_gpus):
            self._communication_options = collective_util.Options(implementation=collective_util.CommunicationImplementation.RING)
    return cross_device_ops_lib.CollectiveAllReduce(devices=self._devices, group_size=len(self._devices), options=self._communication_options, collective_keys=self._collective_keys)

def _get_multi_worker_mirrored_creator(required_gpus, use_merge_call=True):

    def _create_multi_worker_mirrored():
        tf_config = cluster_resolver.TFConfigClusterResolver()
        master = tf_config.master()
        if tf_config.rpc_layer:
            master = master[len('%s://' % tf_config.rpc_layer):]
        resolver = cluster_resolver.SimpleClusterResolver(cluster_spec=tf_config.cluster_spec(), task_type=tf_config.task_type, task_id=tf_config.task_id, master=master, environment=tf_config.environment, num_accelerators={'GPU': required_gpus}, rpc_layer=tf_config.rpc_layer or 'grpc')
        CollectiveAllReduceExtended._enable_check_health = False
        context.context().configure_coordination_service(service_type='')
        with context.eager_mode():
            strategy = CollectiveAllReduceStrategy(cluster_resolver=resolver)
        if <MASK>:
            strategy.extended._use_merge_call = lambda : False
        try:
            multi_process_runner.get_barrier().wait()
        except ValueError:
            pass
        return strategy

    def skip_if_cannot_start_grpc_server():
        try:
            return _create_multi_worker_mirrored()
        except errors.UnknownError as e:
            if 'Could not start gRPC server' in e.message and (len(sys.argv) >= 1 and 'bazel' in sys.argv[0]):
                raise unittest.SkipTest('Cannot start std servers.')
            else:
                raise
    return skip_if_cannot_start_grpc_server

def hingeembeddingloss_reference(input, target, margin=1.0, reduction='mean'):
    margin_clamp = (margin - input).clamp(min=0).type_as(input)
    output = torch.where(target == 1, input, margin_clamp)
    if <MASK>:
        return output.mean()
    elif reduction == 'sum':
        return output.sum()
    return output

def _setup_trace_module_map(model: torch.nn.Module | torch.jit.ScriptModule, export_modules_as_functions: bool | Collection[type[torch.nn.Module]]) -> set[str]:

    def __register_attribute_hook():
        attr_name = '_onnx_attrs'

        def _track_module_attributes_forward_pre_hook(module, input):
            setattr(module, attr_name, _get_module_attributes(module))

        def _track_module_attributes_forward_hook(module, input, output):
            tracing_state = _C._get_tracing_state()
            if not tracing_state:
                return
            graph = tracing_state.graph()
            onnx_attrs = {}
            if hasattr(module, attr_name):
                onnx_attrs = getattr(module, attr_name)
                delattr(module, attr_name)
            _C._jit_pass_onnx_track_scope_attributes(graph, onnx_attrs)
        for m in model.modules():
            m.register_forward_hook(_track_module_attributes_forward_hook)
            m.register_forward_pre_hook(_track_module_attributes_forward_pre_hook)

    def _unqualified_variable_name(qualified_name: str) -> str:
        """
        Parse qualified variable name and return the unqualified version.

        Pure numeric atoms are considered inadequate, so this function will look past them,
        and start from the first non-numeric atom.

        Example:
            >>> _unqualified_variable_name("__main__.Foo.bar")
            'bar'
            >>> _unqualified_variable_name("__main__.Foo.bar.0")
            'bar.0'
        """
        name_atoms = qualified_name.split('.')
        for (i, atom) in reversed(list(enumerate(name_atoms))):
            if not atom.isnumeric():
                return '.'.join(name_atoms[i:])
        return qualified_name
    trace_module_map = {_m: torch._C._jit_onnx_create_full_scope_name(torch.typename(type(_m)), _unqualified_variable_name(_n)) for (_n, _m) in model.named_modules()}
    torch.jit._trace._trace_module_map = trace_module_map
    if isinstance(export_modules_as_functions, bool) and export_modules_as_functions:
        module_typenames = {torch.typename(type(module)) for module in trace_module_map}
    elif isinstance(export_modules_as_functions, set) and export_modules_as_functions:

        def _find_typename(v):
            if isinstance(v, type):
                return torch.typename(v)
            else:
                raise RuntimeError(f'Only type of the `nn.Module` should be passed in the set for argument `export_modules_as_functions`. Got `{type(v).__name__}`.')
        module_typenames = {_find_typename(v) for v in export_modules_as_functions}
    else:
        module_typenames = set()
    if <MASK>:
        __register_attribute_hook()
    return module_typenames

def disable(fn=None, recursive=True, *, reason=None, wrapping=True):
    """
    Decorator to disable TorchDynamo

    If recursive=True, Dynamo is completely skipped on the decorated function
    frame as well as the recursively invoked functions.

    If recursive=False, Dynamo skips frames associated with the function code,
    but still process recursively invoked frames.

    If reason is provided, it will be printed when Dynamo attempts to trace the disabled function.
    """
    if recursive:
        if fn is not None:
            fn = innermost_fn(fn)
            assert callable(fn)
            return DisableContext(msg=reason, wrapping=wrapping)(fn)
        return DisableContext(msg=reason, wrapping=wrapping)
    else:

        def wrap(fn: Callable[_P, _R]) -> Callable[_P, _R]:
            fn = innermost_fn(fn)
            assert callable(fn)
            nonrecursive_disable_wrapper = get_nonrecursive_disable_wrapper(fn)
            nonrecursive_disable_wrapper._torchdynamo_disable = True
            nonrecursive_disable_wrapper._torchdynamo_disable_msg = reason
            nonrecursive_disable_wrapper._torchdynamo_orig_callable = fn
            return nonrecursive_disable_wrapper
        if <MASK>:
            return wrap
        return wrap(fn)

def UNPACK_SEQUENCE(self, inst: Instruction) -> None:
    seq = self.pop()
    if isinstance(seq, TensorVariable):
        val = seq.unpack_var_sequence(self, idxes=range(inst.argval))
    elif isinstance(seq, GetAttrVariable) and isinstance(seq.obj, TensorVariable):
        proxy = getattr(seq.obj.as_proxy(), seq.name)
        val = [wrap_fx_proxy(self, proxy[i]) for i in range(inst.argval)]
    elif <MASK>:
        val = seq.force_unpack_var_sequence(self)
    else:
        unimplemented_v2(gb_type='Failed to unpack object for UNPACK_SEQUENCE', context=str(seq), explanation=f'{seq} cannot be unpacked into a list for the UNPACK_SEQUENCE bytecode (i.e. `a, b, c = d`).', hints=[*graph_break_hints.USER_ERROR])
    if len(val) != inst.argval:
        unimplemented_v2(gb_type='Length mismatch when unpacking object for UNPACK_SEQUENCE', context=f'expected length: {inst.argval}, actual: {len(val)}', explanation=f'{seq} unpacked to a list for the UNPACK_SEQUENCE bytecode (i.e. `a, b, c = d`) with unexpected length.', hints=[*graph_break_hints.DYNAMO_BUG])
    for i in reversed(val):
        self.push(i)

def _log_device_compatibility_check(policy_name, gpu_details_list):
    """Logs a compatibility check if the devices support the policy.

  Currently only logs for the policy mixed_float16.

  Args:
    policy_name: The name of the dtype policy.
    gpu_details_list: A list of dicts, one dict per GPU. Each dict
      is the device details for a GPU, as returned by
      `tf.config.experimental.get_device_details()`.
  """
    if policy_name != 'mixed_float16':
        return
    supported_device_strs = []
    unsupported_device_strs = []
    for details in gpu_details_list:
        name = details.get('device_name', 'Unknown GPU')
        cc = details.get('compute_capability')
        if cc:
            device_str = '%s, compute capability %s.%s' % (name, cc[0], cc[1])
            if cc >= (7, 0):
                supported_device_strs.append(device_str)
            else:
                unsupported_device_strs.append(device_str)
        else:
            unsupported_device_strs.append(name + ', no compute capability (probably not an Nvidia GPU)')
    if unsupported_device_strs:
        warning_str = _COMPAT_CHECK_WARNING_PREFIX + '\n'
        if <MASK>:
            warning_str += 'Some of your GPUs may run slowly with dtype policy mixed_float16 because they do not all have compute capability of at least 7.0. Your GPUs:\n'
        elif len(unsupported_device_strs) == 1:
            warning_str += 'Your GPU may run slowly with dtype policy mixed_float16 because it does not have compute capability of at least 7.0. Your GPU:\n'
        else:
            warning_str += 'Your GPUs may run slowly with dtype policy mixed_float16 because they do not have compute capability of at least 7.0. Your GPUs:\n'
        for device_str in _dedup_strings(supported_device_strs + unsupported_device_strs):
            warning_str += '  ' + device_str + '\n'
        warning_str += 'See https://developer.nvidia.com/cuda-gpus for a list of GPUs and their compute capabilities.\n'
        warning_str += _COMPAT_CHECK_WARNING_SUFFIX
        tf_logging.warning(warning_str)
    elif not supported_device_strs:
        tf_logging.warning('%s\nThe dtype policy mixed_float16 may run slowly because this machine does not have a GPU. Only Nvidia GPUs with compute capability of at least 7.0 run quickly with mixed_float16.\n%s' % (_COMPAT_CHECK_WARNING_PREFIX, _COMPAT_CHECK_WARNING_SUFFIX))
    elif len(supported_device_strs) == 1:
        tf_logging.info('%s\nYour GPU will likely run quickly with dtype policy mixed_float16 as it has compute capability of at least 7.0. Your GPU: %s' % (_COMPAT_CHECK_OK_PREFIX, supported_device_strs[0]))
    else:
        tf_logging.info('%s\nYour GPUs will likely run quickly with dtype policy mixed_float16 as they all have compute capability of at least 7.0' % _COMPAT_CHECK_OK_PREFIX)

def _get_weights_of_type(weights_list, weights_type):
    if <MASK>:
        return weights_list
    if weights_type == 'tensor':
        return ops.convert_to_tensor(weights_list, name='weights')
    return dataset_ops.Dataset.from_tensors(weights_list).repeat()

def get_freq(self) -> str | None:
    """
        Find the appropriate frequency string to describe the inferred
        frequency of self.i8values

        Returns
        -------
        str or None
        """
    if not self.is_monotonic or not self.index._is_unique:
        return None
    delta = self.deltas[0]
    ppd = periods_per_day(self._creso)
    if delta and _is_multiple(delta, ppd):
        return self._infer_daily_rule()
    if self.hour_deltas in ([1, 17], [1, 65], [1, 17, 65]):
        return 'bh'
    if <MASK>:
        return None
    delta = self.deltas_asi8[0]
    pph = ppd // 24
    ppm = pph // 60
    pps = ppm // 60
    if _is_multiple(delta, pph):
        return _maybe_add_count('h', delta / pph)
    elif _is_multiple(delta, ppm):
        return _maybe_add_count('min', delta / ppm)
    elif _is_multiple(delta, pps):
        return _maybe_add_count('s', delta / pps)
    elif _is_multiple(delta, pps // 1000):
        return _maybe_add_count('ms', delta / (pps // 1000))
    elif _is_multiple(delta, pps // 1000000):
        return _maybe_add_count('us', delta / (pps // 1000000))
    else:
        return _maybe_add_count('ns', delta)

def get_nvidia_smi():
    smi = 'nvidia-smi'
    if get_platform() == 'win32':
        system_root = os.environ.get('SYSTEMROOT', 'C:\\Windows')
        program_files_root = os.environ.get('PROGRAMFILES', 'C:\\Program Files')
        legacy_path = os.path.join(program_files_root, 'NVIDIA Corporation', 'NVSMI', smi)
        new_path = os.path.join(system_root, 'System32', smi)
        smis = [new_path, legacy_path]
        for candidate_smi in smis:
            if <MASK>:
                smi = '"{}"'.format(candidate_smi)
                break
    return smi

@final
def size(self) -> Series:
    """
        Compute group sizes.
        """
    ids = self.ids
    ngroups = self.ngroups
    out: np.ndarray | list
    if <MASK>:
        out = np.bincount(ids[ids != -1], minlength=ngroups)
    else:
        out = []
    return Series(out, index=self.result_index, dtype='int64', copy=False)

def _infer_frame_shape(signal, frame_length, frame_step, pad_end, axis):
    """Infers the shape of the return value of `frame`."""
    frame_length = tensor_util.constant_value(frame_length)
    frame_step = tensor_util.constant_value(frame_step)
    axis = tensor_util.constant_value(axis)
    if signal.shape.ndims is None:
        return None
    if axis is None:
        return [None] * (signal.shape.ndims + 1)
    signal_shape = signal.shape.as_list()
    num_frames = None
    frame_axis = signal_shape[axis]
    outer_dimensions = signal_shape[:axis]
    inner_dimensions = signal_shape[axis:][1:]
    if signal_shape and frame_axis is not None:
        if <MASK>:
            num_frames = max(0, -(-frame_axis // frame_step))
        elif frame_step is not None and frame_length is not None:
            assert not pad_end
            num_frames = max(0, (frame_axis - frame_length + frame_step) // frame_step)
    return outer_dimensions + [num_frames, frame_length] + inner_dimensions

def simulate_codegen(self) -> None:
    from .simd import SIMDKernel
    kernel_size_outside_loop = (*self.groups[:-1], sympy.S.One)
    kernel_size_inside_loop = tuple(self.groups)
    self.kernel_sizes = kernel_size_inside_loop
    for node in self.features.node_schedule:
        if node is DisableReduction:
            self.inside_reduction = False
            self.kernel_sizes = kernel_size_outside_loop
            continue
        elif node is EnableReduction:
            self.inside_reduction = True
            self.kernel_sizes = kernel_size_inside_loop
            self.loops.append(MemoryEstimate())
            continue
        assert isinstance(node, SchedulerNode)
        rw = extract_loop_body_with_args(node._body, SIMDKernel.map_kernel_groups_to_node_sizes(self.kernel_sizes, node.get_ranges(), self.set_ranges), dict(zip(self.symbols, self.kernel_sizes)))
        for dep in rw._reads:
            if <MASK>:
                continue
            dep = dep.simplify_with_ranges()
            if not self.persistent.writes.get(dep.name):
                self.persistent.reads[dep.name].add(dep)
            if not (self.outside_loop.writes.get(dep.name) or self.loops[-1].writes.get(dep.name)):
                self.scope(dep).reads[dep.name].add(dep)
                if dep.name in self.store_buffer_names and self.loops[-1].reads.get(dep.name):
                    self.must_keep_buffers.add(dep.name)
        for dep in rw._writes:
            if not isinstance(dep, MemoryDep):
                continue
            dep = dep.simplify_with_ranges()
            self.store_buffer_names.add(dep.name)
            self.persistent.writes[dep.name].add(dep)
            self.scope(dep).writes[dep.name].add(dep)

@contextlib.contextmanager
def _maybe_revert_all_patches():
    current_patcher = CURRENT_PATCHER
    patches_made = None
    patches_removed = None
    try:
        if <MASK>:
            patches_removed = current_patcher.revert_all_patches()
        yield
    finally:
        if current_patcher is not None:
            patches_made = current_patcher.reapply_all_patches()
        assert patches_made == patches_removed, 'CURRENT_PATCHER was changed during a revert_all_patches'

def get_nvidia_driver_version(run_lambda):
    if <MASK>:
        cmd = 'kextstat | grep -i cuda'
        return run_and_parse_first_match(run_lambda, cmd, 'com[.]nvidia[.]CUDA [(](.*?)[)]')
    smi = get_nvidia_smi()
    return run_and_parse_first_match(run_lambda, smi, 'Driver Version: (.*?) ')

@final
@doc(_shared_docs['replace'], klass=_shared_doc_kwargs['klass'], inplace=_shared_doc_kwargs['inplace'])
def replace(self, to_replace=None, value=lib.no_default, *, inplace: bool=False, regex: bool=False) -> Self | None:
    if not is_bool(regex) and to_replace is not None:
        raise ValueError("'to_replace' must be 'None' if 'regex' is not a bool")
    if not (is_scalar(to_replace) or is_re_compilable(to_replace) or is_list_like(to_replace)):
        raise TypeError(f"Expecting 'to_replace' to be either a scalar, array-like, dict or None, got invalid type {type(to_replace).__name__!r}")
    if value is lib.no_default and (not (is_dict_like(to_replace) or is_dict_like(regex))):
        raise ValueError(f"{type(self).__name__}.replace must specify either 'value', a dict-like 'to_replace', or dict-like 'regex'.")
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if inplace:
        if not PYPY and (not WARNING_CHECK_DISABLED):
            if sys.getrefcount(self) <= REF_COUNT:
                warnings.warn(_chained_assignment_method_msg, ChainedAssignmentError, stacklevel=2)
    if value is lib.no_default:
        if not is_dict_like(to_replace):
            to_replace = regex
            regex = True
        items = list(to_replace.items())
        if items:
            (keys, values) = zip(*items, strict=True)
        else:
            (keys, values) = ([], [])
        are_mappings = [is_dict_like(v) for v in values]
        if any(are_mappings):
            if not all(are_mappings):
                raise TypeError('If a nested mapping is passed, all values of the top level mapping must be mappings')
            to_rep_dict = {}
            value_dict = {}
            for (k, v) in items:
                (keys, values) = list(zip(*v.items(), strict=True)) or ([], [])
                to_rep_dict[k] = list(keys)
                value_dict[k] = list(values)
            (to_replace, value) = (to_rep_dict, value_dict)
        else:
            (to_replace, value) = (keys, values)
        return self.replace(to_replace, value, inplace=inplace, regex=regex)
    else:
        if not self.size:
            if inplace:
                return None
            return self.copy(deep=False)
        if is_dict_like(to_replace):
            if is_dict_like(value):
                if isinstance(self, ABCSeries):
                    raise ValueError('to_replace and value cannot be dict-like for Series.replace')
                mapping = {col: (to_replace[col], value[col]) for col in to_replace.keys() if col in value.keys() and col in self}
                return self._replace_columnwise(mapping, inplace, regex)
            elif not is_list_like(value):
                if <MASK>:
                    raise ValueError("Series.replace cannot specify both a dict-like 'to_replace' and a 'value'")
                mapping = {col: (to_rep, value) for (col, to_rep) in to_replace.items()}
                return self._replace_columnwise(mapping, inplace, regex)
            else:
                raise TypeError('value argument must be scalar, dict, or Series')
        elif is_list_like(to_replace):
            if not is_list_like(value):
                value = [value] * len(to_replace)
            if len(to_replace) != len(value):
                raise ValueError(f'Replacement lists must match in length. Expecting {len(to_replace)} got {len(value)} ')
            new_data = self._mgr.replace_list(src_list=to_replace, dest_list=value, inplace=inplace, regex=regex)
        elif to_replace is None:
            if not (is_re_compilable(regex) or is_list_like(regex) or is_dict_like(regex)):
                raise TypeError(f"'regex' must be a string or a compiled regular expression or a list or dict of strings or regular expressions, you passed a {type(regex).__name__!r}")
            return self.replace(regex, value, inplace=inplace, regex=True)
        elif is_dict_like(value):
            if self.ndim == 1:
                raise ValueError('Series.replace cannot use dict-value and non-None to_replace')
            mapping = {col: (to_replace, val) for (col, val) in value.items()}
            return self._replace_columnwise(mapping, inplace, regex)
        elif not is_list_like(value):
            regex = should_use_regex(regex, to_replace)
            if regex:
                new_data = self._mgr.replace_regex(to_replace=to_replace, value=value, inplace=inplace)
            else:
                new_data = self._mgr.replace(to_replace=to_replace, value=value, inplace=inplace)
        else:
            raise TypeError(f'Invalid "to_replace" type: {type(to_replace).__name__!r}')
    result = self._constructor_from_mgr(new_data, axes=new_data.axes)
    if inplace:
        return self._update_inplace(result)
    else:
        return result.__finalize__(self, method='replace')

def shape_env_check_state_equal(env1, env2, non_state_variable_names, map_value):
    env1_vars = vars(env1).copy()
    env2_vars = vars(env2).copy()
    for v in non_state_variable_names:
        if v in env1_vars:
            env1_vars.pop(v)
        if <MASK>:
            env2_vars.pop(v)

    def value_to_str(value: Any) -> str:
        if isinstance(value, dict):
            return '{' + ', '.join((f'{k}: {value[k]}' for k in sorted(value.keys(), key=str))) + '}'
        if isinstance(value, set):
            return '{' + ', '.join((f'{v}' for v in sorted(value))) + '}'
        return str(value)

    def compare_vars(map_value: Callable[[str, Any], Any]) -> list[tuple[str, str, str]]:
        (env1_set, env2_set) = (set(env1_vars), set(env2_vars))
        if env1_set != env2_set:
            raise NotEqualError('field set mismatch:', [('found unique fields:', str(sorted(env1_set - env2_set)), str(sorted(env2_set - env1_set)))])
        sorted_keys = list(env1_set)
        sorted_keys.sort()
        mapped_dict = [(k, map_value(k, env1_vars[k]), map_value(k, env2_vars[k])) for k in sorted_keys]
        return [(f"{k}: values don't match.", value_to_str(val1), value_to_str(val2)) for (k, val1, val2) in mapped_dict if val1 != val2]
    errors = compare_vars(map_value)
    if len(errors) > 0:
        raise NotEqualError("field values don't match:", errors)

def get_bazel_gcc_flags(self):
