    return names

def _write_hierarchical_rows(self, fmt_values: Mapping[int, list[str]], indent: int) -> None:
    template = 'rowspan="{span}" valign="top"'
    is_truncated_horizontally = self.fmt.is_truncated_horizontally
    is_truncated_vertically = self.fmt.is_truncated_vertically
    frame = self.fmt.tr_frame
    nrows = len(frame)
    assert isinstance(frame.index, MultiIndex)
    idx_values = frame.index._format_multi(sparsify=False, include_names=False)
    idx_values = list(zip(*idx_values, strict=True))
    if self.fmt.sparsify:
        sentinel = lib.no_default
        levels = frame.index._format_multi(sparsify=sentinel, include_names=False)
        level_lengths = get_level_lengths(levels, sentinel)
        inner_lvl = len(level_lengths) - 1
        if is_truncated_vertically:
            ins_row = self.fmt.tr_row_num
            inserted = False
            for (lnum, records) in enumerate(level_lengths):
                rec_new = {}
                for (tag, span) in list(records.items()):
                    if tag >= ins_row:
                        rec_new[tag + 1] = span
                    elif tag + span > ins_row:
                        rec_new[tag] = span + 1
                        if not inserted:
                            dot_row = list(idx_values[ins_row - 1])
                            dot_row[-1] = '...'
                            idx_values.insert(ins_row, tuple(dot_row))
                            inserted = True
                        else:
                            dot_row = list(idx_values[ins_row])
                            dot_row[inner_lvl - lnum] = '...'
                            idx_values[ins_row] = tuple(dot_row)
                    else:
                        rec_new[tag] = span
                    if tag + span == ins_row:
                        rec_new[ins_row] = 1
                        if lnum == 0:
                            idx_values.insert(ins_row, tuple(['...'] * len(level_lengths)))
                        elif <MASK>:
                            dot_row = list(idx_values[ins_row])
                            dot_row[inner_lvl - lnum] = '...'
                            idx_values[ins_row] = tuple(dot_row)
                level_lengths[lnum] = rec_new
            level_lengths[inner_lvl][ins_row] = 1
            for ix_col in fmt_values:
                fmt_values[ix_col].insert(ins_row, '...')
            nrows += 1
        for i in range(nrows):
            row = []
            tags = {}
            sparse_offset = 0
            j = 0
            for (records, v) in zip(level_lengths, idx_values[i], strict=True):
                if i in records:
                    if records[i] > 1:
                        tags[j] = template.format(span=records[i])
                else:
                    sparse_offset += 1
                    continue
                j += 1
                row.append(v)
            row.extend((fmt_values[j][i] for j in range(self.ncols)))
            if is_truncated_horizontally:
                row.insert(self.row_levels - sparse_offset + self.fmt.tr_col_num, '...')
            self.write_tr(row, indent, self.indent_delta, tags=tags, nindex_levels=len(levels) - sparse_offset)
    else:
        row = []
        for i in range(len(frame)):
            if is_truncated_vertically and i == self.fmt.tr_row_num:
                str_sep_row = ['...'] * len(row)
                self.write_tr(str_sep_row, indent, self.indent_delta, tags=None, nindex_levels=self.row_levels)
            idx_values = list(zip(*frame.index._format_multi(sparsify=False, include_names=False), strict=True))
            row = []
            row.extend(idx_values[i])
            row.extend((fmt_values[j][i] for j in range(self.ncols)))
            if is_truncated_horizontally:
                row.insert(self.row_levels + self.fmt.tr_col_num, '...')
            self.write_tr(row, indent, self.indent_delta, tags=None, nindex_levels=frame.index.nlevels)

def reduction_combine(reduction_type, var, next_value, helper_val=None, index: Optional[sympy.Symbol]=None, src_dtype=None):
    is_bool = src_dtype == torch.bool
    if reduction_type == 'sum':
        if helper_val:
            return f'cascade_sum_combine({next_value}, &{helper_val})'
        else:
            conjunction = '|' if is_bool else '+'
            return f'{var} {conjunction} {next_value}'
    if reduction_type == 'prod':
        return f'{var} * {next_value}'
    if reduction_type == 'xor_sum':
        return f'{var} ^ {next_value}'
    if reduction_type == 'any':
        return f'{var} || {next_value}'
    if reduction_type in ('min', 'max'):
        return f'{reduction_type}_propagate_nan({var}, {next_value})'
    if reduction_type == 'welford_reduce':
        return f'welford_combine({var}, {next_value})'
    if reduction_type == 'welford_combine':
        if isinstance(next_value, tuple):
            (mean, m2, weight) = next_value
        else:
            (mean, m2, weight) = reduction_project(reduction_type, next_value)
        return f'welford_combine({var}, {{{mean}, {m2}, {weight}}})'
    if reduction_type in ('argmin', 'argmax'):
        if hasattr(next_value, 'dtype') and next_value.dtype == torch.bool and (not next_value.is_vec):
            if <MASK>:
                return f'{reduction_type}_combine({var}, static_cast<float>({next_value}), {index})'
            else:
                return f'{reduction_type}_combine({var}, static_cast<float>({next_value}))'
        if index is not None:
            return f'{reduction_type}_combine({var}, {next_value}, {index})'
        else:
            return f'{reduction_type}_combine({var}, {next_value})'
    raise AssertionError(reduction_type)

def __call__(self, *args, **kwargs):
    if self._variable_scope:
        if <MASK>:
            self._variable_scope_context_manager = variable_scope.variable_scope(self._variable_scope, reuse=variable_scope.AUTO_REUSE)
        with self._variable_scope_context_manager:
            with self._template_store.as_default():
                return self._call_func(args, kwargs)
    else:
        with variable_scope.variable_scope(self._unique_name, self._name, custom_getter=self._custom_getter) as vs:
            self._variable_scope = vs
            self._template_store.set_variable_scope_name(vs.name)
            with self._template_store.as_default():
                return self._call_func(args, kwargs)

def _format_header_regular(self) -> Iterable[ExcelCell]:
    if self._has_aliases or self.header:
        coloffset = 0
        if self.index:
            coloffset = 1
            if isinstance(self.df.index, MultiIndex):
                coloffset = len(self.df.index.names)
        colnames = self.columns
        if self._has_aliases:
            self.header = cast(Sequence, self.header)
            if <MASK>:
                raise ValueError(f'Writing {len(self.columns)} cols but got {len(self.header)} aliases')
            colnames = self.header
        for (colindex, colname) in enumerate(colnames):
            yield CssExcelCell(row=self.rowcounter, col=colindex + coloffset, val=colname, style=None, css_styles=getattr(self.styler, 'ctx_columns', None), css_row=0, css_col=colindex, css_converter=self.style_converter)

def _get_reconciled_name_object(self, other):
    """
        If the result of a set operation will be self,
        return self, unless the name changes, in which
        case make a shallow copy of self.
        """
    name = get_op_result_name(self, other)
    if <MASK>:
        return self.rename(name)
    return self

def gather_params(params, has_biases, has_projections):
    if <MASK>:
        group_size = 5
    elif has_biases:
        group_size = 4
    elif has_projections:
        group_size = 3
    else:
        group_size = 2
    assert len(params) % group_size == 0, len(params)
    return [tuple(params[i:i + group_size]) for i in range(0, len(params), group_size)]

@deprecated("`get_numerical_jacobian` was part of PyTorch's private API and not meant to be exposed. We are deprecating it and it will be removed in a future version of PyTorch. If you have a specific use for this or feature request for this to be a stable API, please file us an issue at https://github.com/pytorch/pytorch/issues/new", category=FutureWarning)
def get_numerical_jacobian(fn, inputs, target=None, eps=0.001, grad_out=1.0):
    """Compute the numerical Jacobian for a given fn and its inputs.

    This is a Deprecated API.

    Args:
        fn: the function to compute the Jacobian for (must take inputs as a tuple)
        inputs: input to `fn`
        target: the Tensors wrt whom Jacobians are calculated (default=`input`)
        eps: the magnitude of the perturbation during finite differencing
             (default=`1e-3`)
        grad_out: defaults to 1.0.

    Returns:
        A list of Jacobians of `fn` (restricted to its first output) with respect to
        each input or target, if provided.

    Note that `target` may not even be part of `input` to `fn`, so please be
    **very careful** in this to not clone `target`.
    """
    if <MASK>:
        raise ValueError('Expected grad_out to be 1.0. get_numerical_jacobian no longer supports values of grad_out != 1.0.')

    def fn_pack_inps(*inps):
        return fn(inps)
    jacobians = _get_numerical_jacobian(fn_pack_inps, inputs, None, target, eps)
    return tuple((jacobian_for_each_output[0] for jacobian_for_each_output in jacobians))

@final
def _handle_indexes(self) -> None:
    """
        Handle indexes.

        This method will add indexes into attr_cols or elem_cols.
        """
    if <MASK>:
