    else:
        return t

def _set_shape_type(value: ir.Value, meta_val: torch.Tensor | torch.SymBool | torch.SymInt | torch.SymFloat | tuple[torch.Tensor], complex_to_float: bool) -> None:
    if isinstance(meta_val, tuple):
        logger.warning('Setting shape and type of tensors is not supported yet')
    if isinstance(meta_val, torch.Tensor):
        dims = []
        shape: tuple[int, ...]
        if meta_val.dtype == torch.float4_e2m1fn_x2:
            shape = _type_casting.get_float4_shape(meta_val)
        else:
            shape = meta_val.shape
        for dim in shape:
            if isinstance(dim, int):
                dims.append(dim)
            else:
                dims.append(str(dim.node))
        if value.dtype is None:
            value.dtype = torch_dtype_to_onnx_dtype(meta_val.dtype)
            if <MASK>:
                if meta_val.dtype == torch.complex64:
                    value.dtype = ir.DataType.FLOAT
                    dims.append(2)
                elif meta_val.dtype == torch.complex128:
                    value.dtype = ir.DataType.DOUBLE
                    dims.append(2)
        value.shape = ir.Shape(dims)
    elif isinstance(meta_val, (int, torch.SymInt)):
        value.dtype = ir.DataType.INT64
        value.shape = ir.Shape([])
    elif isinstance(meta_val, (bool, torch.SymBool)):
        value.dtype = ir.DataType.BOOL
        value.shape = ir.Shape([])
    elif isinstance(meta_val, (float, torch.SymFloat)):
        value.dtype = ir.DataType.FLOAT
        value.shape = ir.Shape([])

def _maybe_arg_null_out(result: np.ndarray, axis: AxisInt | None, mask: npt.NDArray[np.bool_] | None, skipna: bool) -> np.ndarray | int:
    if <MASK>:
        return result
    if axis is None or not getattr(result, 'ndim', False):
        if skipna and mask.all():
            raise ValueError('Encountered all NA values')
        elif not skipna and mask.any():
            raise ValueError('Encountered an NA value with skipna=False')
    elif skipna and mask.all(axis).any():
        raise ValueError('Encountered all NA values')
    elif not skipna and mask.any(axis).any():
        raise ValueError('Encountered an NA value with skipna=False')
    return result

@substitute_in_graph(itertools.filterfalse, is_embedded_type=True)
def filterfalse(function: _Predicate[_T], iterable: Iterable[_T], /) -> Iterator[_T]:
    it = iter(iterable)
    if <MASK>:
        return filter(operator.not_, it)
    else:
        return filter(lambda x: not function(x), it)

@staticmethod
def process_runtime_tangent(x, meta: Union[PlainTensorMeta, SubclassCreationMeta]):
    if not isinstance(x, torch.Tensor):
        return (x, [x])
    if isinstance(x, FakeTensor):
        assert meta.memory_format
        x = coerce_to_expected_memory_format(x, meta.memory_format)
        return (x, [x])
    expected_type: Optional[type] = torch.Tensor
    expected_meta = None
    if isinstance(meta, SubclassCreationMeta):
        expected_type = meta.original_subclass_type
        expected_meta = meta.meta
    runtime_type = type(x)
    if isinstance(x, torch._subclasses.functional_tensor.FunctionalTensor):
        runtime_type = torch.Tensor
    runtime_meta = None
    runtime_subclass_keys: Sequence[str] = []
    if is_traceable_wrapper_subclass(x):
        (runtime_subclass_keys, runtime_meta) = x.__tensor_flatten__()

    def maybe_coerce(x):
        same_type: bool = expected_type == runtime_type
        same_meta: bool = expected_meta == runtime_meta
        if <MASK>:
            return x
        if not hasattr(x, '__coerce_same_metadata_as_tangent__'):
            return None
        if same_type:
            return x.__coerce_same_metadata_as_tangent__(expected_meta)
        return x.__coerce_same_metadata_as_tangent__(expected_meta, expected_type)
    orig_x = x
    x = maybe_coerce(x)
    if x is None:
        raise RuntimeError(f'\nDuring the backward, we encountered a tensor subclass where we guessed its\nmetadata incorrectly.\n\nExpected metadata: {str(expected_meta)}, expected type: {str(expected_type)}\n\nRuntime metadata: {str(runtime_meta)}, runtime type: {str(runtime_type)}\n\nshape: {str(orig_x.shape)}\nTo fix this, your tensor subclass must implement the dunder method __force_to_same_metadata__.\n')
    assert meta.memory_format
    x = coerce_to_expected_memory_format(x, meta.memory_format)
    if not is_traceable_wrapper_subclass(x):
        return (x, [x])
    assert isinstance(meta, SubclassCreationMeta)
    if orig_x is not x:
        runtime_subclass_keys = x.__tensor_flatten__()[0]
    assert len(meta.attrs) == len(runtime_subclass_keys)
    leaves = []
    for (i, (attr, attr_meta)) in enumerate(meta.attrs.items()):
        elem = getattr(x, attr)
        (new_elem, elem_leaves) = AOTDispatchAutograd.process_runtime_tangent(elem, attr_meta)
        if new_elem is not elem:
            setattr(x, attr, new_elem)
        leaves.extend(elem_leaves)
    return (x, leaves)

def _package_aoti_files(archive_writer: PT2ArchiveWriter, aoti_files: Optional[AOTI_FILES], pickle_protocol: int=DEFAULT_PICKLE_PROTOCOL) -> None:
    if aoti_files is None:
        return
    if isinstance(aoti_files, list):
        aoti_files = {'model': aoti_files}
    assert isinstance(aoti_files, dict)
    all_weights: dict[str, Weights] = {}
    weights_configs: dict[str, dict[str, Any]] = {}
    for (model_name, files) in aoti_files.items():
        num_so_files = 0
        weights_configs[model_name] = {}
        for file in files:
            if <MASK>:
                continue
            if isinstance(file, Weights):
                all_weights[model_name] = file
                continue
            if file.endswith('.so'):
                num_so_files += 1
                if num_so_files > 1:
                    raise RuntimeError(f'Multiple .so files found in {files}. You might need to clear your cache directory before calling aoti_compile again.')
            filename = os.path.basename(file)
            if filename.startswith(CUSTOM_OBJ_FILENAME_PREFIX):
                new_filepath = os.path.join(CONSTANTS_DIR, filename)
            else:
                new_filepath = os.path.join(AOTINDUCTOR_DIR, model_name, filename)
            logger.debug('Saving AOTI generated file %s to archive in %s', file, new_filepath)
            archive_writer.write_file(str(new_filepath), file)
    if len(all_weights) > 0:
        grouped_tensors: list[OrderedSet[tuple[str, str]]] = group_weights(all_weights)
        for (idx, group) in enumerate(grouped_tensors):
            filename = f'{WEIGHT_FILENAME_PREFIX}{idx}'
            (model_name, weight_name) = get_complete(group, all_weights)
            (complete_tensor, _) = all_weights[model_name].get_weight(weight_name)
            buffer = io.BytesIO()
            torch.save(complete_tensor, buffer, pickle_protocol=pickle_protocol)
            archive_writer.write_bytes(os.path.join(WEIGHTS_DIR, filename), buffer.getvalue())
            for (model_name, weight_name) in group:
                (_, w_property) = all_weights[model_name].get_weight(weight_name)
                weights_configs[model_name][weight_name] = (filename, w_property.shape, w_property.stride, w_property.offset)
        for (model_name, weights_config) in weights_configs.items():
            archive_writer.write_string(os.path.join(AOTINDUCTOR_DIR, model_name, 'weights_config.json'), json.dumps(weights_config))
            logger.debug('packaging weights_config for model %s', model_name)
            logger.debug(weights_config)

def _set_handle_data(list_handle, element_shape, element_dtype):
