def _raw_fft(a, n, axis, is_real, is_forward, norm, out=None):
    if n < 1:
        raise ValueError(f'Invalid number of FFT data points ({n}) specified.')
    if not is_forward:
        norm = _swap_direction(norm)
    real_dtype = result_type(a.real.dtype, 1.0)
    if norm is None or norm == 'backward':
        fct = 1
    elif norm == 'ortho':
        fct = reciprocal(sqrt(n, dtype=real_dtype))
    elif norm == 'forward':
        fct = reciprocal(n, dtype=real_dtype)
    else:
        raise ValueError(f'Invalid norm value {norm}; should be "backward","ortho" or "forward".')
    n_out = n
    if is_real:
        if <MASK>:
            ufunc = pfu.rfft_n_even if n % 2 == 0 else pfu.rfft_n_odd
            n_out = n // 2 + 1
        else:
            ufunc = pfu.irfft
    else:
        ufunc = pfu.fft if is_forward else pfu.ifft
    axis = normalize_axis_index(axis, a.ndim)
    if out is None:
        if is_real and (not is_forward):
            out_dtype = real_dtype
        else:
            out_dtype = result_type(a.dtype, 1j)
        out = empty_like(a, shape=a.shape[:axis] + (n_out,) + a.shape[axis + 1:], dtype=out_dtype)
    elif (shape := getattr(out, 'shape', None)) is not None and (len(shape) != a.ndim or shape[axis] != n_out):
        raise ValueError('output array has wrong shape.')
    return ufunc(a, fct, axes=[(axis,), (), (axis,)], out=out)

def load_deprecated_signatures(pairs: Sequence[PythonSignatureNativeFunctionPair], deprecated_yaml_path: str, *, method: bool, pyi: bool) -> list[PythonSignatureNativeFunctionPair]:
    grouped: dict[str, list[PythonSignatureNativeFunctionPair]] = defaultdict(list)
    for pair in pairs:
        grouped[pair.signature.name].append(pair)
    results: list[PythonSignatureNativeFunctionPair] = []
    with open(deprecated_yaml_path) as f:
        deprecated_defs = yaml.load(f, Loader=YamlLoader)
    for deprecated in deprecated_defs:
        schema = FunctionSchema.parse(deprecated['name'])
        (aten_name, call_args) = split_name_params(deprecated['aten'])
        is_out = aten_name.endswith('_out')
        if is_out:
            aten_name = aten_name.replace('_out', '')
        known_constants = {'1': Type.parse('Scalar')}
        schema_args_by_name = {a.name: a for a in schema.arguments.flat_all}
        for name in call_args:
            assert name in schema_args_by_name or name in known_constants, f'deprecation definition: Unrecognized value {name}'

        def is_schema_compatible(aten_schema: FunctionSchema) -> bool:
            arguments: Iterable[Argument]
            if is_out:
                arguments = itertools.chain(aten_schema.arguments.out, aten_schema.arguments.flat_non_out)
            else:
                arguments = aten_schema.arguments.flat_all
            for (i, arg) in enumerate(arguments):
                if i < len(call_args):
                    arg_name = call_args[i]
                    if arg_name in known_constants:
                        schema_type = known_constants[arg_name]
                        schema_annotation = None
                    else:
                        schema_arg = schema_args_by_name[arg_name]
                        schema_type = schema_arg.type
                        schema_annotation = schema_arg.annotation
                    if schema_type != arg.type or schema_annotation != arg.annotation:
                        return False
                elif <MASK>:
                    return False
            return len(schema.returns) == len(aten_schema.returns) and all((a == b for (a, b) in zip(schema.returns, aten_schema.returns)))
        any_schema_found = False
        for pair in grouped[aten_name]:
            if not is_schema_compatible(pair.function.func):
                continue
            any_schema_found = True
            python_sig = signature_from_schema(schema, category_override=pair.function.category_override, method=method, pyi=pyi)
            results.append(PythonSignatureNativeFunctionPair(signature=PythonSignatureDeprecated(name=python_sig.name, input_args=python_sig.input_args, input_kwargs=python_sig.input_kwargs, output_args=python_sig.output_args, tensor_options_args=python_sig.tensor_options_args, method=python_sig.method, deprecated_schema=schema, deprecated_args_exprs=tuple(call_args), returns=python_sig.returns), function=pair.function))
        assert any_schema_found, f'No native function with name {aten_name} matched signature:\n  {str(schema)}'
    return results

@compatibility(is_backward_compatible=True)
def lint(self):
    """
        Runs various checks on this Graph to make sure it is well-formed. In
        particular:
        - Checks Nodes have correct ownership (owned by this graph)
        - Checks Nodes appear in topological order
        - If this Graph has an owning GraphModule, checks that targets
        exist in that GraphModule
        """

    def check_arg(arg: Node, n: Optional[Node]=None) -> None:
        context_str = f" of Node '{n}' " if n else ' '
        if arg.graph is not self:
            raise RuntimeError(f"Argument '{arg}'{context_str}does not belong to this Graph, but was used as an argument! If you are copying nodes from another graph, make sure to use ``arg_transform`` on node_copy() to remap values\n{self}")
        if arg not in seen_values:
            raise RuntimeError(f"Argument '{arg}'{context_str}was used before it has been defined! Please check that Nodes in the graph are topologically ordered\n{self}")
    seen_names: set[str] = set()
    seen_values: set[Node] = set()
    for node in self.nodes:
        if node.op not in _legal_ops:
            raise RuntimeError(f'Node {node} had unknown opcode {node.op}!')
        if <MASK>:
            raise RuntimeError(f"Node '{node}' does not belong to this Graph!")
        if node not in self._find_nodes_lookup_table:
            raise RuntimeError(f"Node '{node}' is not added to the side table")
        for arg in node._input_nodes:
            check_arg(arg, node)
        seen_values.add(node)
        if node.name in seen_names:
            raise RuntimeError(f'Node redefined name {node.name}!')
        seen_names.add(node.name)
    if self.owning_module:
        for node in self.nodes:
            if node.op == 'call_function':
                if not callable(node.target):
                    raise ValueError(f'Node {node} target {node.target} has type {torch.typename(node.target)} but a Callable is expected')
            elif not isinstance(node.target, str):
                raise ValueError(f'Node {node} target {node.target} has type {torch.typename(node.target)} but a str is expected')
            if node.op in ['get_attr', 'call_module']:
                target_atoms = node.target.split('.')
                m_itr = self.owning_module
                for (i, atom) in enumerate(target_atoms):
                    new_m_itr = getattr(m_itr, atom, None)
                    seen_qualname = '.'.join(target_atoms[:i])
                    if new_m_itr is None:
                        raise RuntimeError(f'Node {node} target {node.target} references nonexistent attribute {atom} of {seen_qualname}')
                    if node.op == 'call_module' and (not isinstance(new_m_itr, torch.nn.Module)):
                        raise RuntimeError(f'Node {node} target {node.target} {atom} of {seen_qualname} does not reference an nn.Module')
                    m_itr = new_m_itr

def get_with_params(self):
