def __torch_function__(self, orig_func: Callable[_P, _R], types: Sequence[type], args: Sequence[Any]=(), kwargs: dict[str, Any] | None=None) -> Any:
    if kwargs is None:
        kwargs = {}
    if <MASK>:
        with self.prims_mode_cls():
            return orig_func(*args, **kwargs)
    mapping = torch_to_refs_map()
    func = mapping.get(orig_func, None)
    if func is None and isinstance(orig_func, torch._ops.OpOverload):
        func = torch._decomp.decomposition_table.get(orig_func, None)
    elif func is None and isinstance(orig_func, torch._ops.OpOverloadPacket):
        default = getattr(orig_func, 'default', None)
        if default is None and orig_func._dir:
            default = getattr(orig_func, orig_func._dir[0], None)
        if default is not None:
            func = torch._decomp.decomposition_table.get(default, None)
    if func is not None:
        if self.should_fallback_fn(self, orig_func, func, args, kwargs):
            return orig_func(*args, **kwargs)
        with self:
            return func(*args, **kwargs)
    if self.strict:
        raise RuntimeError(f'no _refs support for {torch.overrides.resolve_name(orig_func)}')
    return orig_func(*args, **kwargs)

def pre_compile(self, flat_fn: TraceFn, flat_args: list[FxValue], flat_args_descs: list[AOTInput], aot_config: AOTConfig, *, fw_metadata: ViewAndMutationMeta) -> tuple[TraceFn, list[FxValue], list[AOTInput], ViewAndMutationMeta]:
    leaf_flat_args: list[FxValue] = []
    leaf_flat_args_descs: list[AOTInput] = []
    args_set = set()
    ok = True
    for (i, (a, a_desc)) in enumerate(zip(flat_args, flat_args_descs)):
        if not isinstance(a, torch.Tensor):
            leaf_flat_args.append(a)
            leaf_flat_args_descs.append(a_desc)
        elif a not in args_set:
            args_set.add(a)
            leaf_flat_args.append(a)
            leaf_flat_args_descs.append(a_desc)
        elif not fw_metadata.input_info[i].mutates_data and (not fw_metadata.input_info[i].mutates_metadata):
            leaf_flat_args.append(a.detach().requires_grad_(a.requires_grad))
            leaf_flat_args_descs.append(a_desc)
        else:
            ok = False
            break
    if ok:
        self.needs_post_compile = False
        return (flat_fn, leaf_flat_args, leaf_flat_args_descs, fw_metadata)
    if requires_subclass_dispatch(leaf_flat_args, fw_metadata):
        raise RuntimeError('        Encountered duplicate inputs that are mutated in the graph, but at least one input/output\n        to the graph is a tensor subclass. This is not supported today. You can try to\n        remove the aliasing yourself as a workaround, or otherwise file an issue on github.')
    if aot_config.is_export:
        raise RuntimeError(f'        Encountered duplicated inputs that are mutated in the graph you are trying to export.\n        This functionality is currently not supported. If needed, please file a github issue.\n\n        fw_metadata={str(fw_metadata)}\n            ')
    seen_args: dict[Tensor, int] = {}
    keep_arg_mask: list[bool] = []
    add_dupe_map: list[int] = []
    duped_arg_len = len(flat_args)
    j = 0
    for t in flat_args:
        if isinstance(t, torch.Tensor):
            if <MASK>:
                keep_arg_mask.append(False)
                add_dupe_map.append(seen_args[t])
                continue
            seen_args[t] = j
        keep_arg_mask.append(True)
        add_dupe_map.append(j)
        j += 1
    assert len(add_dupe_map) == duped_arg_len, f'Expects add_dupe_map to have length {duped_arg_len} but got {len(add_dupe_map)}'
    self.keep_arg_mask = keep_arg_mask
    self.add_dupe_map = add_dupe_map
    deduped_flat_args = self.remove_dupe_args(flat_args)
    deduped_flat_args_descs = self.remove_dupe_args(flat_args_descs)
    updated_fw_metadata = remove_dupe_metadata(fw_metadata, keep_arg_mask, add_dupe_map)
    if (tracing_context := (TracingContext.try_get() and aot_config.aot_autograd_arg_pos_to_source)):
        for (dupe_arg_pos, (kept_pos, keep_arg)) in enumerate(zip(add_dupe_map, keep_arg_mask)):
            if not keep_arg:
                dupe_arg_source = aot_config.aot_autograd_arg_pos_to_source[dupe_arg_pos]
                kept_arg_source = aot_config.aot_autograd_arg_pos_to_source[kept_pos]
                tracing_context.guards_context.aotautograd_guards.append(DuplicateInputs(kept_arg_source, dupe_arg_source))

    @simple_wraps(flat_fn)
    def wrapped_flat_fn(*args: FxValue) -> tuple[list[FxValue], list[AOTOutput]]:
        (outs, out_descs) = call_and_expect_output_descs(flat_fn, self.add_dupe_args(args))
        return (outs, out_descs)
    if config.debug_assert:
        ref_fw_metadata = run_functionalized_fw_and_collect_metadata(without_output_descs(wrapped_flat_fn), flat_args_descs=deduped_flat_args_descs, static_input_indices=aot_config.static_input_indices, keep_input_mutations=fw_metadata.keep_input_mutations, is_train=fw_metadata.is_train)(*deduped_flat_args)
        assert ref_fw_metadata == updated_fw_metadata, f'ref_metadata={str(ref_fw_metadata)}, actual_metadata={str(updated_fw_metadata)}'
    return (wrapped_flat_fn, deduped_flat_args, deduped_flat_args_descs, updated_fw_metadata)

@no_type_check
def _assert_in_training_states(state: _FSDPState, training_states: list[TrainingState]) -> None:
    """Asserts that FSDP is in the states ``_training_states``."""
    if state.training_state not in training_states:
        msg = f'expected to be in states {training_states} but current state is {state.training_state}'
        if <MASK>:
            if isinstance(state, nn.Module):
                print(f'Asserting FSDP instance is: {state}')
            print(f'ERROR: {msg}')
            traceback.print_stack()
        raise ValueError(msg)

@contextlib.contextmanager
def _unshard_params_for_summon(module: nn.Module, state: _FSDPState, writeback: bool, rank0_only: bool, offload_to_cpu: bool, with_grads: bool):
    _validate_unshard_params_args(state, writeback, rank0_only, offload_to_cpu, with_grads)
    _lazy_init(state, module)
    if state.training_state == TrainingState.FORWARD_BACKWARD:
        raise AssertionError('Cannot manually unshard parameters during forward/backward')
    elif <MASK>:
        raise AssertionError('Cannot manually unshard parameters when already unsharding parameters')
    with _unshard_fsdp_state_params(module=module, state=state, writeback=writeback, rank0_only=rank0_only, offload_to_cpu=offload_to_cpu, with_grads=with_grads):
        try:
            state.training_state = TrainingState.SUMMON_FULL_PARAMS
            yield
        finally:
            state.training_state = TrainingState.IDLE

def _lazy_init(self) -> None:
    """
        Lazy initialization represents when all modules' parallelisms have
        finalized (e.g. Replicate has been applied to all desired modules). This
        means that we can determine which state is the root, and we do so by
        the 1st state to run forward.
        """
    if <MASK>:
        return
    self._is_root = True
    if len(self._modules) > 1:
        raise RuntimeError(f'Replicate requires a single root module but got {self._modules}')
    detect_compiled_autograd()
    root_module = self._modules[0]
    visited_states: set[_ReplicateState] = set()
    for (module_name, module) in root_module.named_modules():
        if (state := _get_module_replicate_state(module)) is None:
            continue
        if module is not root_module:
            if state not in visited_states and state._is_root is not None:
                raise RuntimeError(f'Replicate state has already been lazily initialized for {module_name}\nReplicate requires running forward through the root module first')
            state._is_root = False
        self._state_ctx.all_states.append(state)
        visited_states.add(state)
    if self._fsdp_param_group and self._auto_reshard_after_forward:
        self._fsdp_param_group.post_forward_mesh_info = None
    self._init_fqns()
    self._init_shared_state()
    for state in self._state_ctx.all_states:
        if state._fsdp_param_group:
            state._fsdp_param_group.lazy_init()

def contents(self):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon
    (field, obj, model_admin) = (self.field['field'], self.form.instance, self.model_admin)
    try:
        (f, attr, value) = lookup_field(field, obj, model_admin)
    except (AttributeError, ValueError, ObjectDoesNotExist):
        result_repr = self.empty_value_display
    else:
        if f is None:
            if getattr(attr, 'boolean', False):
                result_repr = _boolean_icon(value)
            elif hasattr(value, '__html__'):
                result_repr = value
            else:
                result_repr = linebreaksbr(value)
        else:
            if isinstance(f.remote_field, ManyToManyRel) and value is not None:
                result_repr = ', '.join(map(str, value.all()))
            elif <MASK>:
                result_repr = self.get_admin_url(f.remote_field, value)
            else:
                result_repr = display_for_field(value, f, self.empty_value_display)
            result_repr = linebreaksbr(result_repr)
    return conditional_escape(result_repr)

@final
def _rename(self, mapper: Renamer | None=None, *, index: Renamer | None=None, columns: Renamer | None=None, axis: Axis | None=None, inplace: bool=False, level: Level | None=None, errors: str='ignore') -> Self | None:
    if mapper is None and index is None and (columns is None):
        raise TypeError('must pass an index to rename')
    if <MASK>:
        if axis is not None:
            raise TypeError("Cannot specify both 'axis' and any of 'index' or 'columns'")
        if mapper is not None:
            raise TypeError("Cannot specify both 'mapper' and any of 'index' or 'columns'")
    elif axis and self._get_axis_number(axis) == 1:
        columns = mapper
    else:
        index = mapper
    self._check_inplace_and_allows_duplicate_labels(inplace)
    result = self if inplace else self.copy(deep=False)
    for (axis_no, replacements) in enumerate((index, columns)):
        if replacements is None:
            continue
        ax = self._get_axis(axis_no)
        f = common.get_rename_function(replacements)
        if level is not None:
            level = ax._get_level_number(level)
        if not callable(replacements):
            if ax._is_multi and level is not None:
                indexer = ax.get_level_values(level).get_indexer_for(replacements)
            else:
                indexer = ax.get_indexer_for(replacements)
            if errors == 'raise' and len(indexer[indexer == -1]):
                missing_labels = [label for (index, label) in enumerate(replacements) if indexer[index] == -1]
                raise KeyError(f'{missing_labels} not found in axis')
        new_index = ax._transform_index(f, level=level)
        result._set_axis_nocheck(new_index, axis=axis_no, inplace=True)
    if inplace:
        self._update_inplace(result)
        return None
    else:
        return result.__finalize__(self, method='rename')

def sparse_read(self, indices, name=None):
    """Implements tf.Variable.sparse_read."""
    (per_var_indices, _) = self._decompose_indices(indices)
    result = []
    for (i, v) in enumerate(self._variables):
        new_name = None
        if <MASK>:
            new_name = '{}/part_{}'.format(name, i)
        result.append(v.sparse_read(per_var_indices[i], name=new_name))
    return array_ops.concat(result, axis=0)

def _nvcc_compiler_options() -> list[str]:
    arch = _nvcc_arch_as_compile_option()
    code = [f'sm_{arch}', f'compute_{arch}']
    if config.cuda.enable_cuda_lto:
        code += [f'lto_{arch}']
    options = ['-t=0', '-DCUTLASS_ENABLE_TENSOR_CORE_MMA=1', '-DCUTLASS_ENABLE_SM90_EXTENDED_MMA_SHAPES=1', '-DCUTE_SM90_EXTENDED_MMA_SHAPES_ENABLED', '-w', f"-gencode=arch=compute_{arch},code=[{','.join(code)}]", config.cuda.compile_opt_level, '-std=c++17', '--expt-relaxed-constexpr', '-DNDEBUG']
    if config.is_fbcode():
        options.extend(['-ccbin', os.path.dirname(build_paths.gcc)])
    if config.cuda.enable_debug_info:
        options.extend(['-lineinfo', '-g', '-DCUTLASS_DEBUG_TRACE_LEVEL=1'])
    if config.cuda.enable_ptxas_info:
        options.extend(['--keep', '--ptxas-options=--warn-on-local-memory-usage', '--ptxas-options=--warn-on-spills', '--resource-usage', '--source-in-ptx'])
    if <MASK>:
        options.extend(['--use_fast_math', '-DCUTLASS_USE_TANH_FOR_SIGMOID=1'])
    return options

def is_pytorch_file(rel_filepath):
    if <MASK>:
        raise AssertionError('rel_filepath must be a relative path')
    if rel_filepath.startswith('aten/'):
        if rel_filepath.startswith('aten/src/ATen/core/'):
            return False
        return True
    if rel_filepath.startswith('torch/'):
        return True
    if rel_filepath.startswith('third_party/nvfuser/'):
        return True
    if rel_filepath.startswith('third_party/fbgemm/'):
        return True
    if rel_filepath.startswith('tools/autograd/templates/'):
        return True
    return False

@_onnx_symbolic('aten::native_layer_norm')
@symbolic_helper.quantized_args(True, False, False, False)
@symbolic_helper.parse_args('v', 'is', 'v', 'v', 'f')
def native_layer_norm(g: jit_utils.GraphContext, input: _C.Value, normalized_shape: Sequence[int], weight: _C.Value, bias: _C.Value, eps: float) -> tuple[_C.Value, _C.Value, _C.Value]:
    axes = [-i for i in range(len(normalized_shape), 0, -1)]
    two_cst = symbolic_helper._generate_wrapped_number(g, 2.0)
    eps_cst = symbolic_helper._generate_wrapped_number(g, eps)
    if <MASK>:
        mean = g.op('ReduceMean', input, axes_i=axes)
    else:
        mean = g.op('ReduceMean', input, g.op('Constant', value_t=torch.tensor(axes, dtype=torch.long)))
    numerator = sub(g, input, mean)
    is_type_half = _type_utils.JitScalarType.from_value(numerator) == _type_utils.JitScalarType.HALF
    if is_type_half:
        eps_dtype = _type_utils.JitScalarType.from_value(eps_cst)
        numerator = g.op('Cast', numerator, to_i=_type_utils.JitScalarType(eps_dtype).onnx_type())
    if g.opset < 18:
        variance = g.op('ReduceMean', pow(g, numerator, two_cst), axes_i=axes)
    else:
        variance = g.op('ReduceMean', pow(g, numerator, two_cst), g.op('Constant', value_t=torch.tensor(axes, dtype=torch.long)))
    denominator = sqrt(g, g.op('Add', variance, eps_cst))
    normalized = g.op('Div', numerator, denominator)
    if is_type_half:
        input_dtype = _type_utils.JitScalarType.from_value(input)
        normalized = g.op('Cast', normalized, to_i=_type_utils.JitScalarType(input_dtype).onnx_type())
    if not (weight is None or symbolic_helper._is_none(weight)):
        normalized = mul(g, normalized, weight)
    if not (bias is None or symbolic_helper._is_none(bias)):
        normalized = add(g, normalized, bias)
    if is_type_half:
        denominator = g.op('Cast', denominator, to_i=_type_utils.JitScalarType(input_dtype).onnx_type())
        rdenominator = g.op('Reciprocal', denominator)
    else:
        rdenominator = reciprocal(g, denominator)
    return (normalized, mean, rdenominator)

def __new__(mcs, clsname, base, attrs):
