    return cls._simple_new(data, name=name, refs=refs)

@numba.jit(nopython=True, nogil=True, parallel=False)
def sliding_min_max(values: np.ndarray, result_dtype: np.dtype, start: np.ndarray, end: np.ndarray, min_periods: int, is_max: bool) -> tuple[np.ndarray, list[int]]:
    N = len(start)
    na_pos = []
    output = np.empty(N, dtype=result_dtype)

    def cmp(a: Any, b: Any, is_max: bool) -> bool:
        if is_max:
            return a >= b
        else:
            return a <= b
    candidates: list[int] = []
    dominators: list[int] = []
    if min_periods < 1:
        min_periods = 1
    if N > 2:
        i_next = N - 1
        for i in range(N - 2, -1, -1):
            next_dominates = start[i_next] < start[i]
            if <MASK>:
                dominators.append(i_next)
            i_next = i
    valid_start = -min_periods
    last_end = 0
    last_start = -1
    for i in range(N):
        this_start = start[i].item()
        this_end = end[i].item()
        if dominators and dominators[-1] == i:
            dominators.pop()
        if not (this_end > last_end or (this_end == last_end and this_start >= last_start)):
            raise ValueError('Start/End ordering requirement is violated at index ' + str(i))
        stash_start = this_start if not dominators else min(this_start, start[dominators[-1]])
        while candidates and candidates[0] < stash_start:
            candidates.pop(0)
        for k in range(last_end, this_end):
            if not np.isnan(values[k]):
                valid_start += 1
                while valid_start >= 0 and np.isnan(values[valid_start]):
                    valid_start += 1
                while candidates and cmp(values[k], values[candidates[-1]], is_max):
                    candidates.pop()
                candidates.append(k)
        if not candidates or this_start > valid_start:
            if values.dtype.kind != 'i':
                output[i] = np.nan
            else:
                na_pos.append(i)
        elif candidates[0] >= this_start:
            output[i] = values[candidates[0]]
        else:
            q_idx = bisect_left(candidates, this_start, lo=1)
            output[i] = values[candidates[q_idx]]
        last_end = this_end
        last_start = this_start
    return (output, na_pos)

@functools.wraps(fun)
def wrapper(*args, **kwargs):
    __tracebackhide__ = True
    for (old_name, new_name) in zip(old_names, new_names):
        if <MASK>:
            if dep_version:
                end_version = dep_version.split('.')
                end_version[1] = str(int(end_version[1]) + 2)
                end_version = '.'.join(end_version)
                msg = f'Use of keyword argument `{old_name}` is deprecated and replaced by `{new_name}`. Support for `{old_name}` will be removed in NumPy {end_version}.'
                warnings.warn(msg, DeprecationWarning, stacklevel=2)
            if new_name in kwargs:
                msg = f'{fun.__name__}() got multiple values for argument now known as `{new_name}`'
                raise TypeError(msg)
            kwargs[new_name] = kwargs.pop(old_name)
    return fun(*args, **kwargs)

