    def kernel(_, *args, **kwargs):
        assert len(kwargs) == 0, 'Custom ops do not support kwargs yet.'
        return _autocast_py_impl(*args, **kwargs)
    if device_type == 'cuda':
        return lib.impl(opname, kernel, 'AutocastCUDA', with_keyset=True)
    else:
        return lib.impl(opname, kernel, 'AutocastCPU', with_keyset=True)

def _check_list_filter_item(self, obj, item, label):
    """
        Check one item of `list_filter`, the three valid options are:
        1. 'field' -- a basic field filter, possibly w/ relationships (e.g.
           'field__rel')
        2. ('field', SomeFieldListFilter) - a field-based list filter class
        3. SomeListFilter - a non-field list filter class
        """
    from django.contrib.admin import FieldListFilter, ListFilter
    if callable(item) and (not isinstance(item, models.Field)):
        if not _issubclass(item, ListFilter):
            return must_inherit_from(parent='ListFilter', option=label, obj=obj, id='admin.E113')
        elif issubclass(item, FieldListFilter):
            return [checks.Error("The value of '%s' must not inherit from 'FieldListFilter'." % label, obj=obj.__class__, id='admin.E114')]
        else:
            return []
    elif <MASK>:
        (field, list_filter_class) = item
        if not _issubclass(list_filter_class, FieldListFilter):
            return must_inherit_from(parent='FieldListFilter', option='%s[1]' % label, obj=obj, id='admin.E115')
        else:
            return []
    else:
        field = item
        try:
            get_fields_from_path(obj.model, field)
        except (NotRelationField, FieldDoesNotExist):
            return [checks.Error("The value of '%s' refers to '%s', which does not refer to a Field." % (label, field), obj=obj.__class__, id='admin.E116')]
        else:
            return []

def containscommon(rout):
    if <MASK>:
        return 1
    if hasbody(rout):
        for b in rout['body']:
            if containscommon(b):
                return 1
    return 0

def _make_one_shot_iterator(self) -> Union[iterator_ops.Iterator, iterator_ops.OwnedIterator]:
    if context.executing_eagerly():
        with ops.colocate_with(self._variant_tensor):
            return iterator_ops.OwnedIterator(self)
    _ensure_same_dataset_graph(self)
    allowlisted_stateful_ops = traverse.obtain_capture_by_value_ops(self)
    (graph_level_seed, op_level_seed) = core_random_seed.get_seed(None)

    @function.Defun(capture_by_value=True, allowlisted_stateful_ops=allowlisted_stateful_ops)
    def _make_dataset():
        """Factory function for a dataset."""
        if graph_level_seed is not None:
            assert op_level_seed is not None
            core_random_seed.set_random_seed((graph_level_seed + 87654321 * op_level_seed) % (2 ** 63 - 1))
        dataset = self._apply_debug_options()
        return dataset._variant_tensor
    try:
        _make_dataset.add_to_graph(ops.get_default_graph())
    except ValueError as err:
        if <MASK>:
            raise ValueError('{}: A likely cause of this error is that the dataset for which you are calling `make_one_shot_iterator()` captures a stateful object, such as a `tf.Variable` or `tf.lookup.StaticHashTable`, which is not supported. Use `make_initializable_iterator()` instead.'.format(err)) from None
        else:
            raise
    with ops.colocate_with(self._variant_tensor):
        return iterator_ops.Iterator(gen_dataset_ops.one_shot_iterator(dataset_factory=_make_dataset, **self._flat_structure), None, get_legacy_output_types(self), get_legacy_output_shapes(self), get_legacy_output_classes(self))

def _search_callable_free_vars(fn):
    """Search free vars from a callable object."""
    fn = _handle_wrap_partial_func(fn)
    try:
        node = _parse_and_analyze(fn)
    except ValueError:
        return []
    except NotImplementedError:
        return []
    scope = anno.getanno(node, anno.Static.SCOPE)
    free_vars_all = list(scope.free_vars)
    namespace = inspect_utils.getnamespace(fn)
    filtered = []
    for var in free_vars_all:
        base = str(var.qn[0])
        if var.is_simple():
            if base in builtins.__dict__.keys():
                continue
            obj = namespace.get(base, None)
        else:
            assert var.is_composite()
            if <MASK>:
                continue
            else:
                assert var.has_attr()
                if not var.qn[0].is_composite() and base == 'self':
                    attr = str(var.qn[1])
                    if hasattr(fn, '__self__'):
                        obj = getattr(fn.__self__, attr, None)
                    elif hasattr(fn, '__closure__'):
                        self_obj = _get_self_obj_from_closure(fn)
                        if self_obj:
                            obj = getattr(self_obj, attr, None)
                        else:
                            continue
                    else:
                        continue
                else:
                    continue
        if inspect.ismodule(obj) or inspect.isclass(obj):
            continue
        elif inspect.isfunction(obj) or inspect.ismethod(obj):
            obj = _handle_wrap_partial_func(obj)
            if obj.__module__ != fn.__module__:
                continue
            filtered.append(FreeVar(str(var), True, obj))
        else:
            filtered.append(FreeVar(str(var), False, None))
    filtered = sorted(filtered, key=lambda x: x.name)
    return filtered

def build_graph(parameters):
    """Build a space_to_batch graph given `parameters`."""
    input_tensor = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input', shape=parameters['input_shape'])
    input_tensors = [input_tensor]
    if parameters['constant_block_shape']:
        block_shape = parameters['block_shape']
    else:
        shape = [len(parameters['block_shape'])]
        block_shape = tf.compat.v1.placeholder(dtype=tf.int32, name='shape', shape=shape)
        input_tensors.append(block_shape)
    if <MASK>:
        paddings = parameters['paddings']
    else:
        shape = [len(parameters['paddings']), 2]
        paddings = tf.compat.v1.placeholder(dtype=tf.int32, name='paddings', shape=shape)
        input_tensors.append(paddings)
    out = tf.space_to_batch(input_tensor, block_shape, paddings)
    return (input_tensors, [out])

def install(*, venv: Venv, packages: Iterable[str], subcommand: str='checkout', branch: str | None=None, fresh_venv: bool=False, assume_yes: bool=False) -> None:
    """Development install of PyTorch"""
    if <MASK>:
        print(f'Using existing venv: {venv.prefix}')
        venv.ensure()
    else:
        venv.create(remove_if_exists=True, assume_yes=assume_yes)
    packages = [p for p in packages if p != 'torch']
    downloaded_files = venv.pip_download('torch', prerelease=True, no_deps=True)
    if len(downloaded_files) != 1:
        raise RuntimeError(f'Expected exactly one torch wheel, got {downloaded_files}')
    torch_wheel = downloaded_files[0]
    if not (torch_wheel.name.startswith('torch-') and torch_wheel.name.endswith('.whl')):
        raise RuntimeError(f'Expected exactly one torch wheel, got {torch_wheel}')
    with venv.extracted_wheel(torch_wheel) as wheel_site_dir:
        dependencies = parse_dependencies(venv, wheel_site_dir)
        install_packages(venv, [*dependencies, *packages])
        if subcommand == 'checkout':
            checkout_nightly_version(branch, wheel_site_dir)
        elif subcommand == 'pull':
            pull_nightly_version(wheel_site_dir)
        else:
            raise ValueError(f'Subcommand {subcommand} must be one of: checkout, pull.')
        move_nightly_files(wheel_site_dir)
    write_pth(venv)
    cast(logging.Logger, LOGGER).info('-------\nPyTorch Development Environment set up!\nPlease activate to enable this environment:\n\n  $ %s\n', venv.activate_command)

def restore_captures(concrete_function, inputs):
    """Restore captures for the concrete function.

  Used at deserialization time.  For functions that are being deserialized,
  saved model restores objects that tensors were captured from, but functions
  only know about their tensors -- object information is destroyed by tracing.
  This additional logic extracts the tensors which the function originally
  captured.

  Args:
    concrete_function: the concrete function for which to restore captures
    inputs: a list tensors or other Python objects (such as variables) which
      contain tensors that were originally captured by the function
  """
    bound_inputs = [get_tensor_from_node(obj) for obj in inputs]
    bound_variables = [obj for obj in inputs if isinstance(obj, (variables_lib.Variable, resource_variable_ops.BaseResourceVariable))]
    captured_inputs_list = []
    concrete_function.set_variables(bound_variables)
    if bound_inputs:
        for (bound_input, internal_capture) in zip(bound_inputs, concrete_function.inputs[-len(bound_inputs):]):
            if hasattr(bound_input, '__tf_experimental_restore_capture__'):
                captured_inputs_list.append(bound_input.__tf_experimental_restore_capture__(concrete_function, internal_capture))
            else:
                captured_inputs_list.append(bound_input)
                concrete_function.graph.replace_capture(bound_input, internal_capture)
                if internal_capture.dtype == dtypes.resource:
                    if <MASK>:
                        try:
                            handle = bound_input.handle
                        except ValueError:
                            pass
                        else:
                            handle_data_util.copy_handle_data(handle, internal_capture)
                    else:
                        handle_data_util.copy_handle_data(bound_input, internal_capture)
                concrete_function.graph.capture(bound_input)
    if any([inp is None for inp in captured_inputs_list]):
        warnings.warn("Trying to load ShardedVariables using tf.saved_model.load. This won't work if using a tf.distribute.Strategy, and may use excess memory if not using a Strategy. Ignore this warning if using tf.keras.models.load_model.")
    concrete_function.set_external_captures(captured_inputs_list)
    if concrete_function.function_type:
        concrete_function._function_type = function_type_lib.FunctionType(concrete_function.function_type.parameters.values(), concrete_function.graph.function_captures.capture_types, return_annotation=concrete_function.function_type.output)

def clean(self, data, initial=None):
    if data is FILE_INPUT_CONTRADICTION:
        raise ValidationError(self.error_messages['contradiction'], code='contradiction')
    if data is False:
        if <MASK>:
            return False
        data = None
    if not data and initial:
        return initial
    return super().clean(data)

