        return return_string.replace('-', '')

def _move_single(src: Path, source_dir: Path, target_dir: Path, mover: Callable[[Path, Path], None], verb: str) -> None:
    relpath = src.relative_to(source_dir)
    trg = target_dir / relpath
    _remove_existing(trg)
    if src.is_dir():
        trg.mkdir(parents=True, exist_ok=True)
        for (root, dirs, files) in os.walk(src):
            relroot = Path(root).relative_to(src)
            for name in files:
                relname = relroot / name
                s = src / relname
                t = trg / relname
                if <MASK>:
                    print(f'{verb} {s} -> {t}')
                mover(s, t)
            for name in dirs:
                (trg / relroot / name).mkdir(parents=True, exist_ok=True)
    else:
        if VERBOSE:
            print(f'{verb} {src} -> {trg}')
        mover(src, trg)

def remove_temp_dirpath(dirpath, strategy):
    """Removes the temp path after writing is finished.

  Args:
    dirpath: Original dirpath that would be used without distribution.
    strategy: The tf.distribute strategy object currently used.
  """
    if <MASK>:
        strategy = distribute_lib.get_strategy()
    if strategy is None:
        return
    if strategy.extended._in_multi_worker_mode() and (not strategy.extended.should_checkpoint):
        file_io.delete_recursively(_get_temp_dir(dirpath, strategy))

def get_field_type(self, data_type, description):
    if data_type == oracledb.NUMBER:
        (precision, scale) = description[4:6]
        if scale == 0:
            if precision > 11:
                return 'BigAutoField' if description.is_autofield else 'BigIntegerField'
            elif 1 < precision < 6 and description.is_autofield:
                return 'SmallAutoField'
            elif precision == 1:
                return 'BooleanField'
            elif description.is_autofield:
                return 'AutoField'
            else:
                return 'IntegerField'
        elif <MASK>:
            return 'FloatField'
    elif data_type == oracledb.NCLOB and description.is_json:
        return 'JSONField'
    return super().get_field_type(data_type, description)

@classmethod
def _generate_range(cls, start, end, periods: int | None, freq, tz=None, normalize: bool=False, ambiguous: TimeAmbiguous='raise', nonexistent: TimeNonexistent='raise', inclusive: IntervalClosedType='both', *, unit: TimeUnit='ns') -> Self:
    periods = dtl.validate_periods(periods)
    if freq is None and any((x is None for x in [periods, start, end])):
        raise ValueError('Must provide freq argument if no data is supplied')
    if com.count_not_none(start, end, periods, freq) != 3:
        raise ValueError('Of the four parameters: start, end, periods, and freq, exactly three must be specified')
    freq = to_offset(freq)
    if start is not None:
        start = Timestamp(start)
    if end is not None:
        end = Timestamp(end)
    if start is NaT or end is NaT:
        raise ValueError('Neither `start` nor `end` can be NaT')
    if unit is not None:
        if <MASK>:
            raise ValueError("'unit' must be one of 's', 'ms', 'us', 'ns'")
    else:
        unit = 'ns'
    if start is not None:
        start = start.as_unit(unit, round_ok=False)
    if end is not None:
        end = end.as_unit(unit, round_ok=False)
    (left_inclusive, right_inclusive) = validate_inclusive(inclusive)
    (start, end) = _maybe_normalize_endpoints(start, end, normalize)
    tz = _infer_tz_from_endpoints(start, end, tz)
    if tz is not None:
        start = _maybe_localize_point(start, freq, tz, ambiguous, nonexistent)
        end = _maybe_localize_point(end, freq, tz, ambiguous, nonexistent)
    if freq is not None:
        if not isinstance(freq, Tick):
            if start is not None and start.tz is not None:
                start = start.tz_localize(None)
            if end is not None and end.tz is not None:
                end = end.tz_localize(None)
        if isinstance(freq, (Tick, Day)):
            i8values = generate_regular_range(start, end, periods, freq, unit=unit)
        else:
            xdr = _generate_range(start=start, end=end, periods=periods, offset=freq, unit=unit)
            i8values = np.array([x._value for x in xdr], dtype=np.int64)
        endpoint_tz = start.tz if start is not None else end.tz
        if tz is not None and endpoint_tz is None:
            if not timezones.is_utc(tz):
                creso = abbrev_to_npy_unit(unit)
                i8values = tzconversion.tz_localize_to_utc(i8values, tz, ambiguous=ambiguous, nonexistent=nonexistent, creso=creso)
            if start is not None:
                start = start.tz_localize(tz, ambiguous, nonexistent)
            if end is not None:
                end = end.tz_localize(tz, ambiguous, nonexistent)
    else:
        periods = cast(int, periods)
        i8values = np.linspace(0, end._value - start._value, periods, dtype='int64') + start._value
        if i8values.dtype != 'i8':
            i8values = i8values.astype('i8')
    if start == end:
        if not left_inclusive and (not right_inclusive):
            i8values = i8values[1:-1]
    else:
        start_i8 = Timestamp(start)._value
        end_i8 = Timestamp(end)._value
        if not left_inclusive or not right_inclusive:
            if not left_inclusive and len(i8values) and (i8values[0] == start_i8):
                i8values = i8values[1:]
            if not right_inclusive and len(i8values) and (i8values[-1] == end_i8):
                i8values = i8values[:-1]
    dt64_values = i8values.view(f'datetime64[{unit}]')
    dtype = tz_to_dtype(tz, unit=unit)
    return cls._simple_new(dt64_values, freq=freq, dtype=dtype)

def __init__(self, *expressions, fields=(), name=None, condition=None, deferrable=None, include=None, opclasses=(), nulls_distinct=None, violation_error_code=None, violation_error_message=None):
    if not name:
        raise ValueError('A unique constraint must be named.')
    if <MASK>:
        raise ValueError('At least one field or expression is required to define a unique constraint.')
    if expressions and fields:
        raise ValueError('UniqueConstraint.fields and expressions are mutually exclusive.')
    if not isinstance(condition, (NoneType, Q)):
        raise ValueError('UniqueConstraint.condition must be a Q instance.')
    if condition and deferrable:
        raise ValueError('UniqueConstraint with conditions cannot be deferred.')
    if include and deferrable:
        raise ValueError('UniqueConstraint with include fields cannot be deferred.')
    if opclasses and deferrable:
        raise ValueError('UniqueConstraint with opclasses cannot be deferred.')
    if expressions and deferrable:
        raise ValueError('UniqueConstraint with expressions cannot be deferred.')
    if expressions and opclasses:
        raise ValueError('UniqueConstraint.opclasses cannot be used with expressions. Use django.contrib.postgres.indexes.OpClass() instead.')
    if not isinstance(deferrable, (NoneType, Deferrable)):
        raise TypeError('UniqueConstraint.deferrable must be a Deferrable instance.')
    if not isinstance(include, (NoneType, list, tuple)):
        raise TypeError('UniqueConstraint.include must be a list or tuple.')
    if not isinstance(opclasses, (list, tuple)):
        raise TypeError('UniqueConstraint.opclasses must be a list or tuple.')
    if not isinstance(nulls_distinct, (NoneType, bool)):
        raise TypeError('UniqueConstraint.nulls_distinct must be a bool.')
    if opclasses and len(fields) != len(opclasses):
        raise ValueError('UniqueConstraint.fields and UniqueConstraint.opclasses must have the same number of elements.')
    self.fields = tuple(fields)
    self.condition = condition
    self.deferrable = deferrable
    self.include = tuple(include) if include else ()
    self.opclasses = opclasses
    self.nulls_distinct = nulls_distinct
    self.expressions = tuple((F(expression) if isinstance(expression, str) else expression for expression in expressions))
    super().__init__(name=name, violation_error_code=violation_error_code, violation_error_message=violation_error_message)

