    if not allow_fully_quantize:
        test_parameters = [test_parameter for test_parameter in test_parameters if True not in test_parameter['fully_quantize']]

    def populate_dynamic_shape(parameters, input_shape):
        return [parameters['dynamic_size_value'] if x is None else x for x in input_shape]

    def build_graph(parameters):
        """Builds the graph given the current parameters."""
        input1 = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input1', shape=parameters['input_shape_1'])
        input2 = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input2', shape=parameters['input_shape_2'])
        out = binary_operator(input1, input2)
        if parameters['activation'] and (parameters['dtype'] != tf.int32 and parameters['dtype'] != tf.int64):
            out = tf.nn.relu(out)
        return ([input1, input2], [out])

    def build_inputs(parameters, sess, inputs, outputs):
        """Builds operand inputs for op."""
        input_shape_1 = populate_dynamic_shape(parameters, parameters['input_shape_1'])
        input_shape_2 = populate_dynamic_shape(parameters, parameters['input_shape_2'])
        if allow_fully_quantize:
            input1 = create_tensor_data(parameters['dtype'], input_shape_1, min_value=-1, max_value=1)
            input2 = create_tensor_data(parameters['dtype'], input_shape_2, min_value=-1, max_value=1)
        else:
            input1 = create_tensor_data(parameters['dtype'], input_shape_1)
            input2 = create_tensor_data(parameters['dtype'], input_shape_2)
        return ([input1, input2], sess.run(outputs, feed_dict={inputs[0]: input1, inputs[1]: input2}))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs, expected_tf_failures=expected_tf_failures)

def _validate_output_tensor_for_gather(my_rank: int, dst_rank: int, size: torch.Size, dst_tensor: Optional[torch.Tensor]) -> None:
    if dst_rank == my_rank:
        if dst_tensor is None:
            raise ValueError(f'Argument ``dst_tensor`` must be specified on destination rank {dst_rank}')
        if <MASK>:
            raise ValueError(f'Argument ``dst_tensor`` have size {tuple(dst_tensor.size())},but should be {tuple(size)}')
    elif dst_tensor:
        raise ValueError('Argument ``dst_tensor`` must NOT be specified on non-destination ranks.')

def _check_tf1_flags(flags, unparsed):
    """Checks the parsed and unparsed flags to ensure they are valid in 1.X.

  Raises an error if previously support unparsed flags are found. Raises an
  error for parsed flags that don't meet the required conditions.

  Args:
    flags: argparse.Namespace object containing TFLite flags.
    unparsed: List of unparsed flags.

  Raises:
    ValueError: Invalid flags.
  """

    def _get_message_unparsed(flag, orig_flag, new_flag):
        if flag.startswith(orig_flag):
            return '\n  Use {0} instead of {1}'.format(new_flag, orig_flag)
        return ''
    if unparsed:
        output = ''
        for flag in unparsed:
            output += _get_message_unparsed(flag, '--input_file', '--graph_def_file')
            output += _get_message_unparsed(flag, '--savedmodel_directory', '--saved_model_dir')
            output += _get_message_unparsed(flag, '--std_value', '--std_dev_values')
            output += _get_message_unparsed(flag, '--batch_size', '--input_shapes')
            output += _get_message_unparsed(flag, '--dump_graphviz', '--dump_graphviz_dir')
        if output:
            raise ValueError(output)
    if flags.graph_def_file and (not flags.input_arrays or not flags.output_arrays):
        raise ValueError('--input_arrays and --output_arrays are required with --graph_def_file')
    if <MASK>:
        if not flags.input_arrays:
            raise ValueError('--input_shapes must be used with --input_arrays')
        if flags.input_shapes.count(':') != flags.input_arrays.count(','):
            raise ValueError('--input_shapes and --input_arrays must have the same number of items')
    if flags.std_dev_values or flags.mean_values:
        if bool(flags.std_dev_values) != bool(flags.mean_values):
            raise ValueError('--std_dev_values and --mean_values must be used together')
        if flags.std_dev_values.count(',') != flags.mean_values.count(','):
            raise ValueError('--std_dev_values, --mean_values must have the same number of items')
    if (flags.default_ranges_min is None) != (flags.default_ranges_max is None):
        raise ValueError('--default_ranges_min and --default_ranges_max must be used together')
    if flags.dump_graphviz_video and (not flags.dump_graphviz_dir):
        raise ValueError('--dump_graphviz_video must be used with --dump_graphviz_dir')
    if flags.custom_opdefs and (not flags.experimental_new_converter):
        raise ValueError('--custom_opdefs must be used with --experimental_new_converter')
    if flags.custom_opdefs and (not flags.allow_custom_ops):
        raise ValueError('--custom_opdefs must be used with --allow_custom_ops')
    if flags.experimental_select_user_tf_ops and (not flags.experimental_new_converter):
        raise ValueError('--experimental_select_user_tf_ops must be used with --experimental_new_converter')

def __call__(self, shape, dtype=dtypes.float32, **kwargs):
    """Returns a tensor object initialized as specified by the initializer.

    Args:
      shape: Shape of the tensor.
      dtype: Optional dtype of the tensor. Only floating point types are
        supported.
      **kwargs: Additional keyword arguments.

    Raises:
      ValueError: If the dtype is not floating point
    """
    self._validate_kwargs(kwargs)
    dtype = _assert_float_dtype(dtype)
    scale = self.scale
    (fan_in, fan_out) = _compute_fans(shape)
    if _PARTITION_SHAPE in kwargs:
        shape = kwargs[_PARTITION_SHAPE]
    if self.mode == 'fan_in':
        scale /= max(1.0, fan_in)
    elif <MASK>:
        scale /= max(1.0, fan_out)
    else:
        scale /= max(1.0, (fan_in + fan_out) / 2.0)
    if self.distribution == 'truncated_normal':
        stddev = math.sqrt(scale) / 0.8796256610342398
        return self._random_generator.truncated_normal(shape, 0.0, stddev, dtype)
    elif self.distribution == 'untruncated_normal':
        stddev = math.sqrt(scale)
        return self._random_generator.random_normal(shape, 0.0, stddev, dtype)
    else:
        limit = math.sqrt(3.0 * scale)
        return self._random_generator.random_uniform(shape, -limit, limit, dtype)

@classmethod
def convert(cls, style_dict, num_format_str=None) -> dict[str, Any]:
    """
        converts a style_dict to an xlsxwriter format dict

        Parameters
        ----------
        style_dict : style dictionary to convert
        num_format_str : optional number format string
        """
    props = {}
    if num_format_str is not None:
        props['num_format'] = num_format_str
    if style_dict is None:
        return props
    if 'borders' in style_dict:
        style_dict = style_dict.copy()
        style_dict['border'] = style_dict.pop('borders')
    for (style_group_key, style_group) in style_dict.items():
        for (src, dst) in cls.STYLE_MAPPING.get(style_group_key, []):
            if dst in props:
                continue
            v = style_group
            for k in src:
                try:
                    v = v[k]
                except (KeyError, TypeError):
                    break
            else:
                props[dst] = v
    if <MASK>:
        props['pattern'] = 0 if props['pattern'] == 'none' else 1
    for k in ['border', 'top', 'right', 'bottom', 'left']:
        if isinstance(props.get(k), str):
            try:
                props[k] = ['none', 'thin', 'medium', 'dashed', 'dotted', 'thick', 'double', 'hair', 'mediumDashed', 'dashDot', 'mediumDashDot', 'dashDotDot', 'mediumDashDotDot', 'slantDashDot'].index(props[k])
            except ValueError:
                props[k] = 2
    if isinstance(props.get('font_script'), str):
        props['font_script'] = ['baseline', 'superscript', 'subscript'].index(props['font_script'])
    if isinstance(props.get('underline'), str):
        props['underline'] = {'none': 0, 'single': 1, 'double': 2, 'singleAccounting': 33, 'doubleAccounting': 34}[props['underline']]
    if props.get('valign') == 'center':
        props['valign'] = 'vcenter'
    return props

