def __exit__(self, exc_type, exc_value, traceback):
    if exc_type is not None:
        return
    discrepancy_detected = False
    num_devices = torch.cuda.device_count()
    for i in range(num_devices):
        torch._C._cuda_clearCublasWorkspaces()
        caching_allocator_mem_allocated = torch.cuda.memory_allocated(i)
        if caching_allocator_mem_allocated > self.caching_allocator_befores[i]:
            discrepancy_detected = True
            break
    if not discrepancy_detected:
        return
    gc.collect()
    torch.cuda.empty_cache()
    for i in range(num_devices):
        discrepancy_detected = True
        for _ in range(3):
            caching_allocator_mem_allocated = torch.cuda.memory_allocated(i)
            (bytes_free, bytes_total) = torch.cuda.mem_get_info(i)
            driver_mem_allocated = bytes_total - bytes_free
            caching_allocator_discrepancy = False
            driver_discrepancy = False
            if caching_allocator_mem_allocated > self.caching_allocator_befores[i]:
                caching_allocator_discrepancy = True
            if driver_mem_allocated > self.driver_befores[i]:
                driver_discrepancy = True
            if not (caching_allocator_discrepancy or driver_discrepancy):
                discrepancy_detected = False
                break
        if not discrepancy_detected:
            continue
        if caching_allocator_discrepancy and (not driver_discrepancy):
            msg = f'CUDA caching allocator reports a memory leak not verified by the driver API in {self.name}! Caching allocator allocated memory was {self.caching_allocator_befores[i]} and is now reported as {caching_allocator_mem_allocated} on device {i}. CUDA driver allocated memory was {self.driver_befores[i]} and is now {driver_mem_allocated}.'
            warnings.warn(msg)
        elif <MASK>:
            msg = f'CUDA driver API confirmed a leak in {self.name}! Caching allocator allocated memory was {self.caching_allocator_befores[i]} and is now reported as {caching_allocator_mem_allocated} on device {i}. CUDA driver allocated memory was {self.driver_befores[i]} and is now {driver_mem_allocated}.'
            raise RuntimeError(msg)

@_onnx_symbolic('aten::clamp')
def clamp(g: jit_utils.GraphContext, self, min, max):
    if symbolic_helper._is_none(min):
        return clamp_max(g, self, max)
    elif <MASK>:
        return clamp_min(g, self, min)
    elif symbolic_helper._is_constant(min) and symbolic_helper._is_constant(max):
        return symbolic_helper._op_with_optional_float_cast(g, 'Clip', self, min_f=symbolic_helper._parse_arg(min, 'f'), max_f=symbolic_helper._parse_arg(max, 'f'), opset_before=12)
    else:
        return clamp_max(g, clamp_min(g, self, min), max)

def _get_indices_and_dtypes(self, indices=None):
    if indices is None:
        indices = list(range(len(self._dtypes)))
    if <MASK>:
        raise TypeError(f'Invalid indices type {type(indices)}')
    if len(indices) == 0:
        raise ValueError('Empty indices')
    if all((isinstance(i, str) for i in indices)):
        if self._names is None:
            raise ValueError(f'String indices provided {indices}, but this Staging Area was not created with names.')
        try:
            indices = [self._names.index(n) for n in indices]
        except ValueError:
            raise ValueError(f'Named index not in Staging Area names {self._names}')
    elif all((isinstance(i, int) for i in indices)):
        pass
    else:
        raise TypeError(f'Mixed types in indices {indices}. May only be str or int')
    dtypes = [self._dtypes[i] for i in indices]
    return (indices, dtypes)

def _summarize_ranks(ranks: Iterable[int]) -> str:
    ranks = sorted(ranks)
    assert min(ranks) >= 0, 'ranks should all be positive'
    assert len(set(ranks)) == len(ranks), 'ranks should not contain duplicates'
    curr: Optional[Union[int, range]] = None
    ranges = []
    while ranks:
        x = ranks.pop(0)
        if curr is None:
            curr = x
        elif isinstance(curr, int):
            if x == curr + 1:
                curr = range(curr, x + 1, 1)
            else:
                step = x - curr
                curr = range(curr, x + step, step)
        else:
            assert isinstance(curr, range)
            if x == curr.stop:
                curr = range(curr.start, curr.stop + curr.step, curr.step)
            else:
                ranges.append(curr)
                curr = x
    if isinstance(curr, int):
        ranges.append(range(curr, curr + 1, 1))
    elif isinstance(curr, range):
        ranges.append(curr)
    result = []
    for r in ranges:
        if <MASK>:
            result.append(f'{r.start}')
        elif r.step == 1:
            result.append(f'{r.start}:{r.stop}')
        else:
            result.append(f'{r.start}:{r.stop}:{r.step}')
    return ','.join(result)

