def __init__(self, data=None, index=None, dtype: Dtype | None=None, name=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if isinstance(data, SingleBlockManager) and index is None and (dtype is None) and (copy is False or copy is None):
        if <MASK>:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        NDFrame.__init__(self, data)
        self.name = name
        return
    if isinstance(data, (ExtensionArray, np.ndarray)):
        if copy is not False:
            if dtype is None or astype_is_view(data.dtype, pandas_dtype(dtype)):
                data = data.copy()
    if copy is None:
        copy = False
    if isinstance(data, SingleBlockManager) and (not copy):
        data = data.copy(deep=False)
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
    name = ibase.maybe_extract_name(name, data, type(self))
    if index is not None:
        index = ensure_index(index)
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if data is None:
        index = index if index is not None else default_index(0)
        if len(index) or dtype is not None:
            data = na_value_for_dtype(pandas_dtype(dtype), compat=False)
        else:
            data = []
    if isinstance(data, MultiIndex):
        raise NotImplementedError('initializing a Series from a MultiIndex is not supported')
    refs = None
    if isinstance(data, Index):
        if dtype is not None:
            data = data.astype(dtype)
        refs = data._references
        copy = False
    elif isinstance(data, np.ndarray):
        if len(data.dtype):
            raise ValueError('Cannot construct a Series from an ndarray with compound dtype.  Use DataFrame instead.')
    elif isinstance(data, Series):
        if index is None:
            index = data.index
            data = data._mgr.copy(deep=False)
        else:
            data = data.reindex(index)
            copy = False
            data = data._mgr
    elif isinstance(data, Mapping):
        (data, index) = self._init_dict(data, index, dtype)
        dtype = None
        copy = False
    elif isinstance(data, SingleBlockManager):
        if index is None:
            index = data.index
        elif not data.index.equals(index) or copy:
            raise AssertionError('Cannot pass both SingleBlockManager `data` argument and a different `index` argument. `copy` must be False.')
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
            allow_mgr = True
    elif isinstance(data, ExtensionArray):
        pass
    else:
        data = com.maybe_iterable_to_list(data)
        if is_list_like(data) and (not len(data)) and (dtype is None):
            dtype = np.dtype(object)
    if index is None:
        if not is_list_like(data):
            data = [data]
        index = default_index(len(data))
    elif is_list_like(data):
        com.require_length_match(data, index)
    if isinstance(data, SingleBlockManager):
        if dtype is not None:
            data = data.astype(dtype=dtype)
        elif copy:
            data = data.copy()
    else:
        data = sanitize_array(data, index, dtype, copy)
        data = SingleBlockManager.from_array(data, index, refs=refs)
    NDFrame.__init__(self, data)
    self.name = name
    self._set_axis(0, index)

def _slice_argnums(args, argnums, as_tuple=True):
    if <MASK>:
        raise RuntimeError(f'argnums must be int or Tuple[int, ...], got: {type(argnums)}')
    argnums = _validate_and_wrap_argnums(argnums, len(args))
    _check_unique_non_empty(argnums)
    if isinstance(argnums, int):
        if as_tuple:
            return (args[argnums],)
        else:
            return args[argnums]
    return tuple((args[i] for i in argnums))

def change_aliases(self, change_map):
    """
        Change the aliases in change_map (which maps old-alias -> new-alias),
        relabelling any references to them in select columns and the where
        clause.
        """
    if <MASK>:
        return self
    assert set(change_map).isdisjoint(change_map.values())
    self.where.relabel_aliases(change_map)
    if isinstance(self.group_by, tuple):
        self.group_by = tuple([col.relabeled_clone(change_map) for col in self.group_by])
    self.select = tuple([col.relabeled_clone(change_map) for col in self.select])
    self.annotations = self.annotations and {key: col.relabeled_clone(change_map) for (key, col) in self.annotations.items()}
    for (old_alias, new_alias) in change_map.items():
        if old_alias not in self.alias_map:
            continue
        alias_data = self.alias_map[old_alias].relabeled_clone(change_map)
        self.alias_map[new_alias] = alias_data
        self.alias_refcount[new_alias] = self.alias_refcount[old_alias]
        del self.alias_refcount[old_alias]
        del self.alias_map[old_alias]
        table_aliases = self.table_map[alias_data.table_name]
        for (pos, alias) in enumerate(table_aliases):
            if alias == old_alias:
                table_aliases[pos] = new_alias
                break
    self.external_aliases = {change_map.get(alias, alias): aliased or alias in change_map for (alias, aliased) in self.external_aliases.items()}
    for combined_query in self.combined_queries:
        external_change_map = {alias: aliased for (alias, aliased) in change_map.items() if alias in combined_query.external_aliases}
        combined_query.change_aliases(external_change_map)

def _group(self, value, name=None):
