def _add_unshard_reshard(compute_actions: list[Optional[_Action]], max_active_stages: int=3) -> list[_Action]:
    """Given a basic schedule involving only compute actions (F,B,W,OVERLAP_F_B), add UNSHARD/RESHARD actions for FSDP.

    UNSHARD refers to fetching the full contents of an FSDP-sharded layer, requiring an all-gather operation.
    RESHARD does the opposite, releasing memory (but doing no communication)

    We abandon the "timestep lock"  during lowering

    max_active_stages controls how many prefetches we allow. It should be measured in mb and tuneable but in practice
    3 stages is probably the thing we want?
    (to account for having one f and one b active, and something else prefetching?)
    """

    def next_stage_indices(count: int, next_actions: list[Optional[_Action]]) -> list[int]:
        """Remove duplicates (same stage, different microbatch), find next 'count' stages that will do compute."""
        seen: set[int] = set()
        ret: list[int] = []
        for a in next_actions:
            if a is not None:
                if a.computation_type == OVERLAP_F_B and a.sub_actions is not None:
                    for sub_action in a.sub_actions:
                        if sub_action.stage_index not in seen:
                            seen.add(sub_action.stage_index)
                            ret.append(sub_action.stage_index)
                    if len(ret) >= count:
                        break
                elif a.stage_index not in seen:
                    seen.add(a.stage_index)
                    ret.append(a.stage_index)
                    if len(ret) == count:
                        break
        return ret
    active_stages: set[int] = set()
    fsdp_aware_actions: list[_Action] = []

    def _unshard(stage_index: int):
        active_stages.add(stage_index)
        fsdp_aware_actions.append(_Action(stage_index, UNSHARD, None))

    def _reshard(stage_index: int):
        active_stages.remove(stage_index)
        fsdp_aware_actions.append(_Action(stage_index, RESHARD, None))
    for (i, action) in enumerate(compute_actions):
        if <MASK>:
            continue
        next_n = next_stage_indices(max_active_stages, compute_actions[i:])
        fetch = list(filter(lambda s: s not in active_stages, next_n))
        evict = list(filter(lambda s: s not in next_n, active_stages))
        for stage in evict:
            _reshard(stage)
        for stage in fetch:
            _unshard(stage)
        fsdp_aware_actions.append(action)
    for stage in list(active_stages):
        _reshard(stage)
    return fsdp_aware_actions

@tf_export('summary.create_file_writer', v1=[])
def create_file_writer_v2(logdir, max_queue=None, flush_millis=None, filename_suffix=None, name=None, experimental_trackable=False, experimental_mesh=None):
    """Creates a summary file writer for the given log directory.

  Args:
    logdir: a string specifying the directory in which to write an event file.
    max_queue: the largest number of summaries to keep in a queue; will flush
      once the queue gets bigger than this. Defaults to 10.
    flush_millis: the largest interval between flushes. Defaults to 120,000.
    filename_suffix: optional suffix for the event file name. Defaults to `.v2`.
    name: a name for the op that creates the writer.
    experimental_trackable: a boolean that controls whether the returned writer
      will be a `TrackableResource`, which makes it compatible with SavedModel
      when used as a `tf.Module` property.
    experimental_mesh: a `tf.experimental.dtensor.Mesh` instance. When running
      with DTensor, the mesh (experimental_mesh.host_mesh()) will be used for
      bringing all the DTensor logging from accelerator to CPU mesh.

  Returns:
    A SummaryWriter object.
  """
    if logdir is None:
        raise ValueError('Argument `logdir` cannot be None')
    inside_function = ops.inside_function()
    with ops.name_scope(name, 'create_file_writer') as scope, ops.device('cpu:0'):
        with ops.init_scope():
            if <MASK>:
                _check_create_file_writer_args(inside_function, logdir=logdir, max_queue=max_queue, flush_millis=flush_millis, filename_suffix=filename_suffix)
            logdir = ops.convert_to_tensor(logdir, dtype=dtypes.string)
            if max_queue is None:
                max_queue = constant_op.constant(10)
            if flush_millis is None:
                flush_millis = constant_op.constant(2 * 60 * 1000)
            if filename_suffix is None:
                filename_suffix = constant_op.constant('.v2')

            def create_fn():
                if context.executing_eagerly():
                    shared_name = context.anonymous_name()
                else:
                    shared_name = ops.name_from_scope_name(scope)
                return gen_summary_ops.summary_writer(shared_name=shared_name, name=name)
            init_op_fn = functools.partial(gen_summary_ops.create_summary_file_writer, logdir=logdir, max_queue=max_queue, flush_millis=flush_millis, filename_suffix=filename_suffix)
            if experimental_trackable:
                return _TrackableResourceSummaryWriter(create_fn=create_fn, init_op_fn=init_op_fn, mesh=experimental_mesh)
            else:
                return _ResourceSummaryWriter(create_fn=create_fn, init_op_fn=init_op_fn, mesh=experimental_mesh)

def sort_values(self, *, return_indexer: bool=False, ascending: bool=True, na_position: NaPosition='last', key: Callable | None=None) -> Self | tuple[Self, np.ndarray | RangeIndex]:
    if key is not None:
        return super().sort_values(return_indexer=return_indexer, ascending=ascending, na_position=na_position, key=key)
    else:
        sorted_index = self
        inverse_indexer = False
        if ascending:
            if self.step < 0:
                sorted_index = self[::-1]
                inverse_indexer = True
        elif self.step > 0:
            sorted_index = self[::-1]
            inverse_indexer = True
    if <MASK>:
        if inverse_indexer:
            rng = range(len(self) - 1, -1, -1)
        else:
            rng = range(len(self))
        return (sorted_index, RangeIndex(rng))
    else:
        return sorted_index

def __exit__(self, unused_type, unused_value, unused_traceback):
    if context.executing_eagerly():
        return
    if self._graph is not ops.get_default_graph():
        raise RuntimeError(f'Within the automatic control dependency context, the default graph cannot change. Upon entry it was {self._graph}, but on exit it changed to {ops.get_default_graph()}')
    outer_graph = getattr(self._graph, 'outer_graph', None)
    if outer_graph is not None:
        self._graph._add_control_dependencies = outer_graph._add_control_dependencies
    else:
        self._graph._add_control_dependencies = False
    self._graph.experimental_acd_manager = None
    last_write_to_resource = {}
    reads_since_last_write_to_resource = collections.defaultdict(list)
    collective_manager_scopes_opened = {}
    collective_manager_scopes_used = {}
    ops_which_must_run = set()
    merge_for_resource = {}
    new_operations = self._graph.get_operations()[self._n_operations:]
    for op in new_operations:
        if control_flow_util.IsInWhileLoop(op):
            continue
        control_inputs = set()
        if op.type in MUST_RUN_ORDER_INSENSITIVE_STATEFUL_OPS:
            self.run_independently(op)
        if op in self._independent_ops:
            ops_which_must_run.add(op)
            continue
        if op_def_registry.get(op.type) is None or (op_is_stateful(op) and (op.type not in utils.RESOURCE_READ_OPS or any((output.consumers() for output in op.outputs)))):
            ops_which_must_run.add(op)
        if op.type == 'NoOp':
            try:
                collective_manager_scopes_opened[op.get_attr('_collective_manager_id')] = op
            except ValueError:
                pass
        if <MASK>:
            continue
        if op.type == 'Merge':
            for o in ops_which_must_run:
                op._add_control_input(o)
                for inp in o.inputs:
                    input_id = ops.tensor_id(inp)
                    if input_id in last_write_to_resource:
                        last_write_to_resource[input_id] = op
            ops_which_must_run = set([op])
            continue
        resource_inputs = set()
        for (inp, resource_type) in _get_resource_inputs(op):
            is_read = resource_type == ResourceType.READ_ONLY
            input_id = ops.tensor_id(inp)
            if input_id in resource_inputs:
                continue
            resource_inputs.add(input_id)
            if inp.op.type == 'Switch':
                self._process_switch(inp.op, ops_which_must_run, last_write_to_resource, merge_for_resource)
            is_building_function = op.graph.building_function
            if input_id in last_write_to_resource:
                if is_building_function or last_write_to_resource[input_id]._control_flow_context is op._control_flow_context:
                    control_inputs.add(last_write_to_resource[input_id])
            if input_id in merge_for_resource:
                merge_for_resource[input_id]._add_control_input(op)
            if is_read:
                reads_since_last_write_to_resource[input_id].append(op)
            else:
                control_inputs.update(reads_since_last_write_to_resource[input_id])
                reads_since_last_write_to_resource[input_id] = []
                last_write_to_resource[input_id] = op
        if op_is_stateful(op) and (not resource_inputs) and (op._control_flow_context is None):
            if None in last_write_to_resource:
                op._add_control_input(last_write_to_resource[None])
            last_write_to_resource[None] = op
        manager_ids = collective_manager_ids_from_op(op)
        for manager_id in manager_ids:
            if manager_id in collective_manager_scopes_opened:
                op._add_control_input(collective_manager_scopes_opened[manager_id])
                collective_manager_scopes_opened[manager_id] = op
            else:
                if manager_id in collective_manager_scopes_used:
                    op._add_control_input(collective_manager_scopes_used[manager_id])
                collective_manager_scopes_used[manager_id] = op
        if control_inputs and (not is_building_function):
            control_inputs = [c for c in control_inputs if c._control_flow_context is op._control_flow_context]
        op._add_control_inputs(control_inputs)
    self.ops_which_must_run.update(ops_which_must_run)
    control_output_op = None
    for (idx, r) in enumerate(nest.flatten(list(self._returned_tensors), expand_composites=True)):
        if self.ops_which_must_run:
            updated_ops_which_must_run = []
            if r.graph.building_function:
                if idx == 0:
                    control_output_op = control_flow_ops.no_op()
                    control_output_op._add_control_inputs(self.ops_which_must_run)
                updated_ops_which_must_run = [control_output_op]
            else:
                updated_ops_which_must_run = [o for o in self.ops_which_must_run if o._control_flow_context is r.op._control_flow_context]
            r.op._add_control_inputs(updated_ops_which_must_run)
    self.collective_manager_ids_used = collective_manager_scopes_used

def as_sql(self, compiler, connection):
    try:
        (sql, params) = super().as_sql(compiler, connection)
    except EmptyResultSet:
        features = compiler.connection.features
        if not features.supports_boolean_expr_in_select_clause:
            return ('1=1', ())
        return compiler.compile(Value(True))
    ops = compiler.connection.ops
    if <MASK>:
        return (f'CASE WHEN {sql} = 0 THEN 1 ELSE 0 END', params)
    return (f'NOT {sql}', params)

def sample_inputs_logspace(op, device, dtype, requires_grad, **kwargs):
    ends = (-3, 0, 1.2, 2, 4)
    starts = (-2.0, 0, 1, 2, 4.3)
    nsteps = (0, 1, 2, 4)
    bases = (2.0, 1.1) if dtype in (torch.int8, torch.uint8) else (None, 2.0, 3.0, 1.1, 5.0)
    for (start, end, nstep, base) in product(starts, ends, nsteps, bases):
        if dtype == torch.uint8 and end < 0 or start < 0:
            continue
        if <MASK>:
            continue
        if base is None:
            yield SampleInput(start, args=(end, nstep), kwargs={'dtype': dtype, 'device': device})
        else:
            yield SampleInput(start, args=(end, nstep, base), kwargs={'dtype': dtype, 'device': device})
    yield SampleInput(1, args=(3, 1, 2.0))

def is_subperiod(source, target) -> bool:
    """
    Returns True if downsampling is possible between source and target
    frequencies

    Parameters
    ----------
    source : str or DateOffset
        Frequency converting from
    target : str or DateOffset
        Frequency converting to

    Returns
    -------
    bool
    """
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)
    if _is_annual(target):
        if _is_quarterly(source):
            return _quarter_months_conform(get_rule_month(source), get_rule_month(target))
        return source in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_quarterly(target):
        return source in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_monthly(target):
        return source in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_weekly(target):
        return source in {target, 'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif target == 'B':
        return source in {'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif target == 'C':
        return source in {'C', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif target == 'D':
        return source in {'D', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif target == 'h':
        return source in {'h', 'min', 's', 'ms', 'us', 'ns'}
    elif target == 'min':
        return source in {'min', 's', 'ms', 'us', 'ns'}
    elif target == 's':
        return source in {'s', 'ms', 'us', 'ns'}
    elif target == 'ms':
        return source in {'ms', 'us', 'ns'}
    elif target == 'us':
        return source in {'us', 'ns'}
    elif <MASK>:
        return source in {'ns'}
    else:
        return False

def _shape_offsets(shape):
    """Returns moving offset for each dimension given shape."""
    offsets = []
    for dim in reversed(shape):
        if <MASK>:
            offsets.append(dim * offsets[-1])
        else:
            offsets.append(dim)
    offsets.reverse()
    return offsets

@parameterized.parameters(itertools.product(range(1, 4), (np.complex64, np.complex128)))
@test_util.run_gpu_only
def testAxes_fftn(self, dims, np_type):
    tol = 0.0001 if np_type == np.complex64 else 1e-08
    if dims == 1:
        fft_length = (4,)
        axes = (-1,)
    elif <MASK>:
        fft_length = (4, 4)
        axes = (0, 1)
    else:
        fft_length = None
        axes = None
    self._Compare_fftn(np.mod(np.arange(np.power(4, dims)), 10).reshape((4,) * dims).astype(np_type), fft_length=fft_length, axes=axes, rtol=tol)

def get_ignore_reason(obj: Any, denylist: Collection[Any]) -> Optional[str]:
    """Tests whether an object should be omitted from the dependency graph."""
    if len(denylist) > 100:
        return '<depth limit>'
    if tf_inspect.isframe(obj):
        if 'test_util.py' in tf_inspect.getframeinfo(obj)[0]:
            return '<test code>'
    for b in denylist:
        if <MASK>:
            return '<test code>'
    if obj is denylist:
        return '<test code>'
    return None

def do_auto_functionalize_v2(mode: 'torch._subclasses.functional_tensor.FunctionalTensorMode', op: Union[OpOverload, HopInstance], args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
    from torch._subclasses.functional_tensor import PythonFunctionalizeAPI
    ctx = PythonFunctionalizeAPI(mode=mode)
    normalized_kwargs = {}
    schema = op._schema
    op = op._op if isinstance(op, HopInstance) else op
    assert isinstance(op, get_args(_MutableOpType))

    def _functionalize_callable(arg: Any):
        if callable(arg):
            return FunctionalCallableWithEpilogue(arg)
        return arg
    (args, kwargs) = pytree.tree_map(_functionalize_callable, (args, kwargs))
    for (idx, arg) in enumerate(schema.arguments):
        if <MASK>:
            normalized_kwargs[arg.name] = kwargs[arg.name]
        elif idx < len(args):
            normalized_kwargs[arg.name] = args[idx]
        else:
            normalized_kwargs[arg.name] = arg.default_value
    (mutable_args_names, mutable_args_types) = get_mutable_args_from_schema(schema)
    all_bases = []
    all_bases_addresses: list[int] = []
    arg_to_base_index: dict[str, Any] = {}

    def update_dict(tensor, arg_name, index=None):
        base = tensor if get_base(tensor) is None else get_base(tensor)

        def set_result(base_index):
            if index is None:
                arg_to_base_index[arg_name] = base_index
            else:
                arg_to_base_index[arg_name][index] = base_index
        if not all_bases_addresses.__contains__(base._cdata):
            all_bases_addresses.append(base._cdata)
            all_bases.append(base)
            set_result(len(all_bases) - 1)
        else:
            set_result(all_bases_addresses.index(base._cdata))
    for arg_name in mutable_args_names:
        arg = normalized_kwargs[arg_name]
        if arg is None:
            continue
        if isinstance(arg, list):
            arg_to_base_index[arg_name] = {}
            for (i, tensor) in enumerate(arg):
                if tensor is None:
                    arg_to_base_index[arg_name].append(None)
                    continue
                update_dict(tensor, arg_name, i)
        else:
            update_dict(arg, arg_name)
    write_view_information_to_args(mutable_args_names, mutable_args_types, normalized_kwargs, arg_to_base_index)
    for arg_name in mutable_args_names:
        del normalized_kwargs[arg_name]
    unwrapped_kwargs = ctx.unwrap_tensors(normalized_kwargs)
    if 'self' in unwrapped_kwargs or 'self_' in unwrapped_kwargs:
        warnings.warn('Using `self` or `self_` as an argument in the definition of custom ops may lead to ambiguous parsing. Please consider using a different name for this argument to avoid potential issues.')
    all_basis_unwrapped = ctx.unwrap_tensors(all_bases)
    assert '_all_bases' not in unwrapped_kwargs, (op, unwrapped_kwargs)
    auto_func_kwargs = dict(unwrapped_kwargs, _all_bases=all_basis_unwrapped)
    if isinstance(op, HigherOrderOperator):
        assert '_ops_schema' not in unwrapped_kwargs, (op, unwrapped_kwargs)
        auto_func_kwargs.update({'_op_schema': pytree.tree_flatten(SchemaHolder(schema))[1]})
    with ctx.redispatch_to_next():
        unwrapped_outs = auto_functionalized_v2(op, **auto_func_kwargs)
    unwrapped_actual_out: Union[Any, tuple[Any]] = unwrapped_outs if len(all_bases) == 0 else unwrapped_outs[:-len(all_bases)]
    unwrapped_mutable_out = [] if len(all_bases) == 0 else unwrapped_outs[-len(all_bases):]
    if isinstance(op, HigherOrderOperator):
        assert len(schema.returns) > 0, f'hop is expected to return at least one output {schema}.'
        assert len(unwrapped_actual_out) == len(schema.returns)
    elif len(schema.returns) == 0:
        assert unwrapped_actual_out[0] is None
        unwrapped_actual_out = None
    elif len(schema.returns) == 1:
        assert len(unwrapped_actual_out) == 1
        unwrapped_actual_out = unwrapped_actual_out[0]
    else:
        assert len(unwrapped_actual_out) == len(schema.returns)
    for (orig_arg, unwrapped_out) in zip(all_bases, unwrapped_mutable_out):
        if unwrapped_out is None:
            continue

        def sync_update(o, orig_arg):
            ctx.replace(orig_arg, o)
            ctx.commit_update(orig_arg)
            ctx.sync(orig_arg)
        if isinstance(unwrapped_out, torch.Tensor):
            sync_update(unwrapped_out, orig_arg)
        elif isinstance(unwrapped_out, list) and all((isinstance(o, torch.Tensor) for o in unwrapped_out)):
            assert len(orig_arg) == len(unwrapped_out)
            for (orig_a, o) in zip(orig_arg, unwrapped_out):
                sync_update(o, orig_a)
        else:
            raise RuntimeError(f'unsupported type for auto-functionalization: {unwrapped_out}')
    return ctx.wrap_tensors(unwrapped_actual_out)

def __init__(self, log_dir: Optional[str]=None, redirects: Union[Std, dict[int, Std]]=Std.NONE, tee: Union[Std, dict[int, Std]]=Std.NONE, local_ranks_filter: Optional[set[int]]=None) -> None:
    if log_dir != os.devnull:
        if not log_dir:
            log_dir = tempfile.mkdtemp(prefix='torchelastic_')
        elif not os.path.exists(log_dir):
            os.makedirs(log_dir, exist_ok=True)
        elif <MASK>:
            raise NotADirectoryError(f'log_dir: {log_dir} is a file')
    super().__init__(log_dir, redirects, tee, local_ranks_filter)
    self._run_log_dir = None

@final
def _get_arithmetic_result_freq(self, other) -> BaseOffset | None:
    """
        Check if we can preserve self.freq in addition or subtraction.
        """
    if isinstance(self.dtype, PeriodDtype):
        return self.freq
    elif not lib.is_scalar(other):
        return None
    elif isinstance(self.freq, Tick):
        return self.freq
    elif self.dtype.kind == 'm' and isinstance(other, Timedelta):
        return self.freq
    elif self.dtype.kind == 'm' and isinstance(other, Timestamp) and (other.tz is None or timezones.is_utc(other.tz)):
        return self.freq
    elif <MASK>:
        return self.freq
    elif lib.is_np_dtype(self.dtype, 'M') and isinstance(other, Timestamp) and isinstance(self.freq, Day):
        return self.freq
    return None

@_onnx_symbolic('aten::_convolution')
@symbolic_helper.parse_args('v', 'v', 'v', 'is', 'is', 'is', 'i', 'is', 'i', 'i', 'i', 'i', 'i')
def _convolution(g: jit_utils.GraphContext, input, weight, bias, stride, padding, dilation, transposed, output_padding, groups, benchmark, deterministic, cudnn_enabled, allow_tf32=None):
    weight_size = symbolic_helper._get_tensor_sizes(weight)
    try:
        kernel_shape = weight_size[2:]
    except Exception:
        kernel_shape = None
    if kernel_shape is None or any((i is None for i in kernel_shape)):
        raise errors.SymbolicValueError('Unsupported: ONNX export of convolution for kernel of unknown shape.', input)
    args = [input, weight]
    if not symbolic_helper._is_none(bias) and symbolic_helper._get_tensor_rank(bias) == 1:
        args.append(bias)
    kwargs = {'kernel_shape_i': weight_size[2:], 'strides_i': stride, 'pads_i': padding + padding, 'dilations_i': dilation, 'group_i': groups}
    if <MASK>:
        assert transposed
        assert len(stride) == len(output_padding)
        kwargs['output_padding_i'] = output_padding
    n = g.op('ConvTranspose' if transposed else 'Conv', *args, **kwargs)
    if not symbolic_helper._is_none(bias) and symbolic_helper._get_tensor_rank(bias) != 1:
        return g.op('Add', n, bias)
    else:
        return n

def __init__(self, type_input):
    """Figure out the correct OGR Type based upon the input."""
    if isinstance(type_input, OGRGeomType):
        num = type_input.num
    elif <MASK>:
        type_input = type_input.lower()
        if type_input == 'geometry':
            type_input = 'unknown'
        num = self._str_types.get(type_input)
        if num is None:
            raise GDALException('Invalid OGR String Type "%s"' % type_input)
    elif isinstance(type_input, int):
        if type_input not in self._types:
            raise GDALException('Invalid OGR Integer Type: %d' % type_input)
        num = type_input
    else:
        raise TypeError('Invalid OGR input type given.')
    self.num = num

def _create_obs_or_fq_from_qspec(quantization_spec: Optional[QuantizationSpecBase], obs_or_fq_map: dict[EdgeOrNode, ObserverOrFakeQuantize], is_qat: bool):
    """Create observer or fake quantize objects based on quantization spec

    Args:
       quantization_spec: used to store parameters to create the observer or fake quantizer
       obs_or_fq_map: this is a map from edge/output to the corresponding observer/fake_quant
       instance, it may be reused for different edge/output depending on configuration
    """
    if quantization_spec is None:
        return None
    if isinstance(quantization_spec, SharedQuantizationSpec):
        edge_or_node = quantization_spec.edge_or_node
        assert edge_or_node in obs_or_fq_map, f"please make sure only refer to edge or node that has observer/fake_quant inserted: '{edge_or_node}' not in\n{obs_or_fq_map.keys()}"
        return obs_or_fq_map[edge_or_node]
    elif isinstance(quantization_spec, DerivedQuantizationSpec):
        kwargs = {'dtype': quantization_spec.dtype, 'derive_qparams_fn': quantization_spec.derive_qparams_fn, 'quant_min': quantization_spec.quant_min, 'quant_max': quantization_spec.quant_max, 'qscheme': quantization_spec.qscheme, 'ch_axis': quantization_spec.ch_axis}
        edge_or_nodes = quantization_spec.derived_from
        obs_or_fqs = [obs_or_fq_map[k] for k in edge_or_nodes]
        kwargs['obs_or_fqs'] = obs_or_fqs
        return _DerivedObserverOrFakeQuantize.with_args(**kwargs)()
    elif <MASK>:
        kwargs = _get_observer_kwargs(quantization_spec)
        observer_ctr = FixedQParamsObserver.with_args(**kwargs)
        if is_qat:
            return FixedQParamsFakeQuantize.with_args(observer=observer_ctr)()
        else:
            return observer_ctr()
    assert isinstance(quantization_spec, QuantizationSpec)
    observer_or_fake_quant_ctr = quantization_spec.observer_or_fake_quant_ctr
    kwargs = _get_observer_kwargs(quantization_spec)
    kwargs.pop('observer_or_fake_quant_ctr')
    obs_or_fq_class = observer_or_fake_quant_ctr
    if isinstance(observer_or_fake_quant_ctr, _PartialWrapper):
        obs_or_fq_class = observer_or_fake_quant_ctr.p.func
    if 'PerChannel' not in obs_or_fq_class.__name__:
        kwargs.pop('ch_axis')
    return observer_or_fake_quant_ctr.with_args(**kwargs)()

def win_wrap_ninja_compile(sources, output_dir=None, macros=None, include_dirs=None, debug=0, extra_preargs=None, extra_postargs=None, depends=None, is_standalone=False):
    if not self.compiler.initialized:
        self.compiler.initialize()
    output_dir = os.path.abspath(output_dir)
    convert_to_absolute_paths_inplace(self.compiler.include_dirs)
    (_, objects, extra_postargs, pp_opts, _) = self.compiler._setup_compile(output_dir, macros, include_dirs, sources, depends, extra_postargs)
    if <MASK>:
        pp_opts = ['-I{}'.format(s[2:].replace(' ', '\\')) if s.startswith('-I') else s for s in pp_opts]
    common_cflags = extra_preargs or []
    cflags = []
    if debug:
        cflags.extend(self.compiler.compile_options_debug)
    else:
        cflags.extend(self.compiler.compile_options)
    cflags = cflags + common_cflags + pp_opts + COMMON_MSVC_FLAGS
    if IS_HIP_EXTENSION:
        _set_hipcc_runtime_lib(is_standalone, debug)
        common_cflags.extend(COMMON_HIP_FLAGS)
    else:
        common_cflags.extend(COMMON_MSVC_FLAGS)
    with_cuda = any(map(_is_cuda_file, sources))
    if isinstance(extra_postargs, dict):
        post_cflags = extra_postargs['cxx']
    else:
        post_cflags = list(extra_postargs)
    if IS_HIP_EXTENSION:
        post_cflags = COMMON_HIP_FLAGS + post_cflags
    append_std17_if_no_std_present(post_cflags)
    cuda_post_cflags = None
    cuda_cflags = None
    if with_cuda:
        cuda_cflags = ['-std=c++17']
        for common_cflag in common_cflags:
            cuda_cflags.append('-Xcompiler')
            cuda_cflags.append(common_cflag)
        if not IS_HIP_EXTENSION:
            cuda_cflags.append('--use-local-env')
            for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                cuda_cflags.append('-Xcudafe')
                cuda_cflags.append('--diag_suppress=' + ignore_warning)
        cuda_cflags.extend(pp_opts)
        if isinstance(extra_postargs, dict):
            cuda_post_cflags = extra_postargs['nvcc']
        else:
            cuda_post_cflags = list(extra_postargs)
        if IS_HIP_EXTENSION:
            cuda_post_cflags = win_hip_flags(cuda_post_cflags)
        else:
            cuda_post_cflags = win_cuda_flags(cuda_post_cflags)
    cflags = _nt_quote_args(cflags)
    post_cflags = _nt_quote_args(post_cflags)
    if with_cuda:
        cuda_cflags = _nt_quote_args(cuda_cflags)
        cuda_post_cflags = _nt_quote_args(cuda_post_cflags)
    if isinstance(extra_postargs, dict) and 'nvcc_dlink' in extra_postargs:
        cuda_dlink_post_cflags = win_cuda_flags(extra_postargs['nvcc_dlink'])
    else:
        cuda_dlink_post_cflags = None
    _write_ninja_file_and_compile_objects(sources=sources, objects=objects, cflags=cflags, post_cflags=post_cflags, cuda_cflags=cuda_cflags, cuda_post_cflags=cuda_post_cflags, cuda_dlink_post_cflags=cuda_dlink_post_cflags, sycl_cflags=None, sycl_post_cflags=None, sycl_dlink_post_cflags=None, build_directory=output_dir, verbose=True, with_cuda=with_cuda, with_sycl=False)
    return objects

def na_logical_op(x: np.ndarray, y, op):
    try:
        result = op(x, y)
    except TypeError:
        if <MASK>:
            assert not (x.dtype.kind == 'b' and y.dtype.kind == 'b')
            x = ensure_object(x)
            y = ensure_object(y)
            result = libops.vec_binop(x.ravel(), y.ravel(), op)
        else:
            assert lib.is_scalar(y)
            if not isna(y):
                y = bool(y)
            try:
                result = libops.scalar_binop(x, y, op)
            except (TypeError, ValueError, AttributeError, OverflowError, NotImplementedError) as err:
                typ = type(y).__name__
                raise TypeError(f"Cannot perform '{op.__name__}' with a dtyped [{x.dtype}] array and scalar of type [{typ}]") from err
    return result.reshape(x.shape)

def get_as_bool(self, key: str, default: Optional[bool]=None) -> Optional[bool]:
    """Return the value for ``key`` as a ``bool``."""
    value = self.get(key, default)
    if value is None or isinstance(value, bool):
        return value
    if <MASK>:
        if value == 1:
            return True
        if value == 0:
            return False
    elif isinstance(value, str):
        if value.lower() in ['1', 'true', 't', 'yes', 'y']:
            return True
        if value.lower() in ['0', 'false', 'f', 'no', 'n']:
            return False
    raise ValueError(f"The rendezvous configuration option '{key}' does not represent a valid boolean value.")

def _scaled_mm_like_strategy(mm_equation: str, mesh: DeviceMesh, op_schema: OpSchema) -> OpStrategy:
    (self_strategy, mat2_strategy, scale_self_strategy, scale_mat2_strategy, bias_strategy, scale_result_strategy, *_) = op_schema.args_schema
    if not isinstance(self_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(self_strategy)}')
    if not isinstance(mat2_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(mat2_strategy)}')
    if not isinstance(scale_self_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(scale_self_strategy)}')
    if <MASK>:
        raise AssertionError(f'Expected OpStrategy, got {type(scale_mat2_strategy)}')
    if bias_strategy is not None:
        raise AssertionError("_scaled_mm on DTensors doesn't support bias")
    if scale_result_strategy is not None:
        raise AssertionError("_scaled_mm on DTensors doesn't support scale_result")
    mm_strategy = gen_einsum_strategies(mm_equation, mesh)
    strategies = mm_strategy.strategies
    filtered_strategies = []
    for strtg in strategies:
        if strtg.input_specs is None:
            raise AssertionError(f'Expected input_specs to be not None, got {strtg.input_specs}')
        self_spec = strtg.input_specs[0]
        mat2_spec = strtg.input_specs[1]
        scale_self_spec = DTensorSpec(self_spec.mesh, (Replicate(),)) if prod(scale_self_strategy.shape) == 1 else self_spec
        scale_mat2_spec = DTensorSpec(mat2_spec.mesh, (Replicate(),)) if prod(scale_mat2_strategy.shape) == 1 else mat2_spec
        strtg.input_specs = list(strtg.input_specs) + [scale_self_spec, scale_mat2_spec]
        if is_tensor_shardable(self_strategy.shape, self_spec) and is_tensor_shardable(mat2_strategy.shape, mat2_spec) and is_tensor_shardable(scale_self_strategy.shape, scale_self_spec) and is_tensor_shardable(scale_mat2_strategy.shape, scale_mat2_spec):
            redistribute_cost = [generate_redistribute_costs(self_strategy, self_spec), generate_redistribute_costs(mat2_strategy, mat2_spec), generate_redistribute_costs(scale_self_strategy, scale_self_spec), generate_redistribute_costs(scale_mat2_strategy, scale_mat2_spec)]
            strtg.redistribute_cost = redistribute_cost
            filtered_strategies.append(strtg)
    mm_strategy.strategies = filtered_strategies
    return mm_strategy

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if self.fn is object and name == '__setattr__':
        assert len(args) == 3
        assert len(kwargs) == 0
        (obj, name_var, val) = args
        obj = obj.realize()
        if isinstance(obj, UserDefinedObjectVariable) and tx.output.side_effects.is_attribute_mutation(obj) and name_var.is_python_constant():
            return obj.method_setattr_standard(tx, name_var, val)
    if name == '__new__':
        if self.fn is object and len(args) == 1:
            assert len(kwargs) == 0
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is dict and len(args) == 1 and (not kwargs):
            dict_vt = ConstDictVariable({}, dict, mutation_type=ValueMutationNew())
            if isinstance(args[0], BuiltinVariable) and args[0].fn is dict:
                return dict_vt
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is tuple and len(args) == 2 and args[1].has_force_unpack_var_sequence(tx) and (not kwargs):
            if isinstance(args[0], BuiltinVariable) and args[0].fn is tuple:
                init_args = args[1].force_unpack_var_sequence(tx)
                return variables.TupleVariable(init_args, mutation_type=ValueMutationNew())
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is list:
            list_vt = ListVariable([], mutation_type=ValueMutationNew())
            if isinstance(args[0], BuiltinVariable) and args[0].fn is list:
                return list_vt
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
    if self.fn is float and len(args) == 1 and (name in ('fromhex', 'hex')):
        if <MASK>:
            try:
                fn = getattr(float, name)
                res = fn(args[0].as_python_constant())
                return variables.ConstantVariable.create(res)
            except (OverflowError, ValueError) as e:
                raise_observed_exception(type(e), tx, args=list(map(ConstantVariable.create, e.args)))
    if self.fn is object and name == '__init__':
        return variables.ConstantVariable(None)
    if self.fn is dict and name == 'fromkeys':
        return BuiltinVariable.call_custom_dict_fromkeys(tx, dict, *args, **kwargs)
    if self.fn is dict:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in dict_methods:
            if isinstance(args[0], variables.UserDefinedDictVariable):
                return args[0]._dict_vt.call_method(tx, name, args[1:], kwargs)
            elif isinstance(args[0], variables.ConstDictVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is set:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in set_methods:
            if isinstance(args[0], variables.UserDefinedSetVariable):
                return args[0]._set_vt.call_method(tx, name, args[1:], kwargs)
            elif isinstance(args[0], variables.SetVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is frozenset:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in frozenset_methods:
            if isinstance(args[0], variables.FrozensetVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is str and len(args) >= 1:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in str_methods:
            if isinstance(args[0], ConstantVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is float and len(args) >= 1:
        if isinstance(args[0], ConstantVariable):
            return ConstantVariable.create(getattr(float, name)(args[0].as_python_constant()))
    return super().call_method(tx, name, args, kwargs)

def exception_handler(self, raised_exception: ObservedException) -> None:
    observed_exn_gb_explanation = 'Dynamo found no exception handler at the top-level compiled function when encountering an exception. Exception will propagate outside the compiled region.'

    def bubble_exception_to_interpreter() -> None:
        curr_exc = self.exn_vt_stack.get_current_exception()
        dynamo_exc = exc.get_dynamo_observed_exception(curr_exc.python_type())
        assert isinstance(raised_exception, dynamo_exc)
        unimplemented_v2(gb_type='Observed exception', context=f'raised exception {curr_exc.python_type_name()}({curr_exc.args})', explanation=observed_exn_gb_explanation, hints=[*graph_break_hints.USER_ERROR, *graph_break_hints.SUPPORTABLE], from_exc=raised_exception)
    if sys.version_info >= (3, 11):
        exn_tab_entry = self.current_instruction.exn_tab_entry
        if exn_tab_entry:
            while len(self.stack) > exn_tab_entry.depth:
                self.pop()
            if exn_tab_entry.lasti:
                self.push(variables.ConstantVariable(self.current_instruction.offset))
            self.push(self.exn_vt_stack.get_current_exception())
            self.jump(exn_tab_entry)
        else:
            self.stack.clear()
            if type(self) is InstructionTranslator:
                bubble_exception_to_interpreter()
            raise raised_exception
    elif len(self.block_stack):
        block_stack_entry = self.block_stack.pop()
        while block_stack_entry.inst.opname == 'EXCEPT_HANDLER':
            self.popn(3)
            self.exn_vt_stack.pop()
            if <MASK>:
                self.stack.clear()
                if type(self) is InstructionTranslator:
                    unimplemented_v2(gb_type='Observed exception (EXCEPT_HANDLER)', context=str(raised_exception), explanation=observed_exn_gb_explanation + ' This graph break is unexpected.', hints=[*graph_break_hints.DYNAMO_BUG])
                raise raised_exception
            block_stack_entry = self.block_stack.pop()
        exception_var = self.exn_vt_stack.get_current_exception()
        self.exn_vt_stack.move_current_exception_to_stack()
        while len(self.stack) > block_stack_entry.stack_index:
            self.pop()
        except_handler_inst = Instruction(1000000.0, 'EXCEPT_HANDLER', None, 0)
        self.block_stack.append(BlockStackEntry(except_handler_inst, None, len(self.stack)))
        if len(self.exn_vt_stack) >= 2:
            old_exception = self.exn_vt_stack[-2]
            self.push(variables.UnknownVariable())
            self.push(old_exception)
            self.push(variables.BuiltinVariable(old_exception.exc_type))
        else:
            self.push(variables.ConstantVariable(None))
            self.push(variables.ConstantVariable(None))
            self.push(variables.ConstantVariable(None))
        self.push(variables.UnknownVariable())
        self.push(exception_var)
        self.push(variables.BuiltinVariable(exception_var.exc_type))
        self.jump(block_stack_entry)
    else:
        self.stack.clear()
        if type(self) is InstructionTranslator:
            bubble_exception_to_interpreter()
        raise raised_exception

def format_array(self, a):
    if np.ndim(a) == 0:
        return self.format_function(a)
    if <MASK>:
        formatted = [self.format_array(a_) for a_ in a[:self.edge_items]] + [self.summary_insert] + [self.format_array(a_) for a_ in a[-self.edge_items:]]
    else:
        formatted = [self.format_array(a_) for a_ in a]
    return '[' + ', '.join(formatted) + ']'

def normalize_outarray(arg, parm=None):
    if arg is None:
        return arg
    from ._ndarray import ndarray
    if <MASK>:
        arg = ndarray(arg)
    if not isinstance(arg, ndarray):
        raise TypeError(f"'{parm.name}' must be an array")
    return arg

def _einsum_v2(equation, *inputs, **kwargs):
    """Implementation of einsum utilizing opt_einsum and EinsumOp."""
    name = kwargs.pop('name', None)
    optimize = kwargs.pop('optimize', 'greedy')
    if kwargs:
        raise TypeError(f"Invalid keyword arguments for einsum: {', '.join(kwargs)}. Valid arguments: name, optimize, greedy.")
    with ops.name_scope(name, 'einsum', [equation, inputs]) as name:
        inputs = list(inputs)
        input_shapes = []
        for operand in inputs:
            if isinstance(operand.shape, tensor_shape.TensorShape):
                input_shapes.append(operand.shape.as_list() if operand.shape else None)
            else:
                input_shapes.append(list(operand.shape))
        (resolved_equation, resolved_input_shapes, ellipsis_label) = _einsum_v2_parse_and_resolve_equation(equation, input_shapes)
        if len(inputs) <= 2:
            if <MASK>:
                resolved_equation = resolved_equation.replace(ellipsis_label, '...')
            return gen_linalg_ops.einsum(inputs, resolved_equation)
        shaped = collections.namedtuple('shaped', ['shape'])
        shaped_inputs = tuple([shaped(tuple(shape)) for shape in resolved_input_shapes])
        indices_and_equations = _get_opt_einsum_contract_path(resolved_equation, shaped_inputs, optimize)
        for (operand_indices, binary_equation) in indices_and_equations:
            if ellipsis_label:
                binary_equation = binary_equation.replace(ellipsis_label, '...')
            operands = list(map(inputs.pop, operand_indices))
            inputs.append(gen_linalg_ops.einsum(operands, binary_equation))
        return inputs[0]

def observe_garbage(observer):
    enabled = True

    def disable():
        nonlocal enabled
        enabled = False
    atexit.register(disable)

    def gc_callback(phase, info):
        nonlocal enabled
        if <MASK>:
            return
        if phase == 'start':
            gc.set_debug(gc.DEBUG_SAVEALL)
        elif phase == 'stop':
            orig_trace = sys.getprofile()
            self_return = [False]

            def do_collect(*args, **kwargs):
                nonlocal enabled
                if not self_return[0]:
                    self_return[0] = True
                else:
                    sys.setprofile(orig_trace)
                    enabled = False
                    try:
                        if info['generation'] != 2:
                            gc.collect()
                        observer(gc.garbage)
                        gc.garbage.clear()
                        gc.set_debug(0)
                        before = torch.cuda.memory_allocated()
                        gc.collect()
                        after = torch.cuda.memory_allocated()
                        if before != after:
                            logger.warning('CUDA Memory changed during GC, %d bytes freed.', before - after)
                    finally:
                        enabled = True
                if orig_trace is not None:
                    return orig_trace(*args, **kwargs)
            sys.setprofile(do_collect)
    gc.callbacks.append(gc_callback)

    def remove():
        gc.callbacks.remove(gc_callback)
    return remove

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    if name == '__getitem__':
        from .tensor import TensorVariable
        if <MASK>:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if isinstance(args[0], TensorVariable):
            value = get_fake_value(args[0].as_proxy().node, tx)
            if value.constant is not None and value.constant.numel() == 1:
                value = variables.ConstantVariable.create(value.constant.item())
            else:
                unimplemented_v2(gb_type='Indexing list with non-scalar tensor', context=f'call_method {self} {name} {args} {kwargs}', explanation='Attempted to index list-like object with tensor with > 1 element.', hints=[*graph_break_hints.USER_ERROR])
        else:
            value = args[0]
        if value.python_type() not in (int, slice):
            msg = f'indices must be integers or slices, not {value.python_type()}'
            raise_observed_exception(TypeError, tx, args=[ConstantVariable(msg)])
        return self.getitem_const(tx, value)
    elif name == '__contains__':
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return iter_contains(self.unpack_var_sequence(tx), args[0], tx)
    elif name == 'index':
        if not len(args):
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return tx.inline_user_function_return(VariableTracker.build(tx, polyfills.index), [self] + list(args), kwargs)
    elif name == 'count':
        if len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return VariableTracker.build(tx, operator.countOf).call_function(tx, [self, args[0]], kwargs)
    elif name in ('__add__', '__iadd__'):
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if type(self) is not type(args[0]):
            tp_name = self.python_type_name()
            other = args[0].python_type_name()
            msg = ConstantVariable.create(f'can only concatenate {tp_name} (not "{other}") to {tp_name}')
            raise_observed_exception(TypeError, tx, args=[msg])
        if name == '__add__':
            return type(self)(self.items + args[0].items, source=self.source)
        else:
            self.items += args[0].items
            return self
    elif name in ('__mul__', '__imul__'):
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not (args[0].is_python_constant() and args[0].python_type() is int):
            msg = ConstantVariable.create(f"can't multiply sequence by non-int type of '{args[0].python_type_name()}'")
            raise_observed_exception(TypeError, tx, args=[msg])
        val = args[0].as_python_constant()
        if name == '__mul__':
            return type(self)(self.items * val, source=self.source)
        else:
            self.items *= val
            return self
    elif name in cmp_name_to_op_mapping:
        if len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        left = self
        right = args[0]
        if not isinstance(left, BaseListVariable) or not isinstance(right, BaseListVariable):
            if name == '__eq__':
                return variables.BuiltinVariable(operator.is_).call_function(tx, (left, right), {})
            elif name == '__ne__':
                return variables.BuiltinVariable(operator.is_not).call_function(tx, (left, right), {})
            else:
                op_str = cmp_name_to_op_str_mapping[name]
                left_ty = left.python_type_name()
                right_ty = right.python_type_name()
                msg = f"{op_str} not supported between instances of '{left_ty}' and '{right_ty}'"
                raise_observed_exception(TypeError, tx, args=[msg])
        return variables.UserFunctionVariable(polyfills.list_cmp).call_function(tx, [variables.BuiltinVariable(cmp_name_to_op_mapping[name]), left, right], {})
    return super().call_method(tx, name, args, kwargs)

def _deserialize_nested_config(deserialize_fn, config):
    """Deserializes arbitrary Keras `config` using `deserialize_fn`."""

    def _is_single_object(obj):
        if isinstance(obj, dict) and 'class_name' in obj:
            return True
        if isinstance(obj, str):
            return True
        return False
    if config is None:
        return None
    if _is_single_object(config):
        return deserialize_fn(config)
    elif isinstance(config, dict):
        return {k: _deserialize_nested_config(deserialize_fn, v) for (k, v) in config.items()}
    elif <MASK>:
        return [_deserialize_nested_config(deserialize_fn, obj) for obj in config]
    raise ValueError('Saved configuration not understood.')

def find_command(cmd, path=None, pathext=None):
    if path is None:
        path = os.environ.get('PATH', '').split(os.pathsep)
    if <MASK>:
        path = [path]
    if pathext is None:
        pathext = os.environ.get('PATHEXT', '.COM;.EXE;.BAT;.CMD').split(os.pathsep)
    for ext in pathext:
        if cmd.endswith(ext):
            pathext = ['']
            break
    for p in path:
        f = os.path.join(p, cmd)
        if os.path.isfile(f):
            return f
        for ext in pathext:
            fext = f + ext
            if os.path.isfile(fext):
                return fext
    return None

def min_max_axis(X, axis, ignore_nan=False):
    """Compute minimum and maximum along an axis on a CSR or CSC matrix.

     Optionally ignore NaN values.

    Parameters
    ----------
    X : sparse matrix of shape (n_samples, n_features)
        Input data. It should be of CSR or CSC format.

    axis : {0, 1}
        Axis along which the axis should be computed.

    ignore_nan : bool, default=False
        Ignore or passing through NaN values.

        .. versionadded:: 0.20

    Returns
    -------

    mins : ndarray of shape (n_features,), dtype={np.float32, np.float64}
        Feature-wise minima.

    maxs : ndarray of shape (n_features,), dtype={np.float32, np.float64}
        Feature-wise maxima.
    """
    if <MASK>:
        if ignore_nan:
            return _sparse_nan_min_max(X, axis=axis)
        else:
            return _sparse_min_max(X, axis=axis)
    else:
        _raise_typeerror(X)

def wrapper(*args, **kwargs):
    scalars = [arg for arg in args if isinstance(arg, (int, sympy.Expr)) or (isinstance(arg, CppCSEVariable) and (not arg.is_vec))]
    vectors = [arg for arg in args if isinstance(arg, CppCSEVariable) and arg.is_vec]
    new_args = list(args)
    if scalars and vectors:
        new_args = []
        for arg in args:
            if isinstance(arg, (int, sympy.Expr)):
                if <MASK>:
                    arg = ops.index_expr(arg, torch.int64)
                else:
                    arg = ops.constant(arg, torch.int64)
                arg = arg.value if isinstance(arg, OpsValue) else arg
            new_args.append(arg)
    if vectors:
        if len(new_args) == 2:
            new_args = promote_args(new_args)
        elif func == CppVecOverrides.where:
            new_args[1:] = promote_args(new_args[1:])
    if scalars and vectors:
        assert isinstance(V.kernel, CppVecKernel)
        new_args = [V.kernel.broadcast(new_arg) if isinstance(new_arg, CppCSEVariable) and (not new_arg.is_vec) and (func not in [CppVecOverrides.rand, CppVecOverrides.randn, CppVecOverrides.randint64]) else new_arg for new_arg in new_args]
    if vectors:
        return func(*new_args, **kwargs)
    else:
        scalar_ops = super(CppVecOverrides, self)
        scalar_func = getattr(scalar_ops, func.__name__)
        assert scalar_func is not None
        return scalar_func(*args, **kwargs)

@property
def target_class(self):
    true_self = self.weakrefself_target__()
    if <MASK>:
        return true_self
    else:
        return true_self.__class__

def read_view_information_from_args(mutable_arg_names: list[str], mutable_arg_types: list[torch.Type], kwargs: dict[str, Any], all_bases: list[Tensor]):
    """
    This reads the view information added by `write_view_information_to_args` from kwargs, pop them,
    and returns a dict arg_name -> ViewInfo | [ViewInfo](if the input is list). that maps each mutable arg
    to its view information.
    mutable_arg_names: mutable custom operator arg names.
    mutable_arg_types: mutable custom operator arg types.
    kwargs : args of auto_functionalize(custom_op, kwargs)
    """

    def get_arg(name):
        return kwargs.pop(name)

    def read_single_view(prefix):
        base_index = get_arg(f'{prefix}_base_index')
        if base_index is None:
            return None
        elif f'{prefix}_alias' in kwargs:
            get_arg(f'{prefix}_alias')
            return AliasViewInfo(base_index)
        elif f'{prefix}_storage_offset' in kwargs:
            size = get_arg(f'{prefix}_size')
            stride = get_arg(f'{prefix}_stride')
            storage_offset = get_arg(f'{prefix}_storage_offset')
            return AsStridedViewInfo(base_index, size, stride, storage_offset)
        elif f'{prefix}_slice_dim' in kwargs:
            dim = get_arg(f'{prefix}_slice_dim')
            start = get_arg(f'{prefix}_slice_start')
            end = get_arg(f'{prefix}_slice_end')
            return SliceViewInfo(base_index, dim, start, end)
        else:
            return NotView(base_index)
    args_view_info: dict[str, Any] = {}
    for (arg_name, arg_type) in zip(mutable_arg_names, mutable_arg_types):
        if <MASK>:
            length = get_arg(f'_{arg_name}_length')
            if length is None:
                args_view_info[arg_name] = None
            else:
                args_view_info[arg_name] = [read_single_view(f'_{arg_name}_{i}') for i in range(length)]
        elif library_utils.is_tensor_like_type(arg_type):
            args_view_info[arg_name] = read_single_view(f'_{arg_name}')
        else:
            raise RuntimeError(f'Unsupported type {arg_type}')
    return args_view_info

def track_symint(source: Source, val: IntLikeType, constraint: DimConstraint=None) -> None:
    log.debug('track_symint %s %s %s', LazyString(source.name), val, constraint)
    assert not isinstance(val, SymInt) or is_symbolic(val)
    if isinstance(val, SymInt) and val.node.maybe_as_int() is not None:
        val = val.node.maybe_as_int()
    if <MASK>:
        s = val.node.expr
        if isinstance(s, sympy.Symbol):
            symbol_to_source[s].append(source)
            if constraint is not None and (not isinstance(constraint, RelaxedUnspecConstraint)):
                symbol_to_constraints[s].add(constraint)
        else:
            constraint_violated = False
            if isinstance(constraint, StrictMinMaxConstraint):
                sym_vrs = {x: self.var_to_range.get(x, None) for x in s.free_symbols}
                if any((vr is None for vr in sym_vrs.values())):
                    constraint_violated = True
            elif isinstance(constraint, RelaxedUnspecConstraint):
                if s.is_number:
                    i = int(s)
                    if i not in (0, 1):
                        constraint_violated = True
            if constraint_violated:
                assert constraint is not None

                def hint(s: sympy.Expr) -> str:
                    sexpr = py_printer.doprint(s)
                    return f'{sexpr}.'
                var_with_range = self._render_range_for_constraint_violation(source, constraint)
                msg = f'Not all values of {var_with_range} are valid because {self._debug_name(source)} was inferred to be equal to '
                record_constraint_violation(constraint.warn_only, self._debug_name(source), msg, hint=functools.partial(hint, s))
        input_guards.append((source, s))
    else:
        s = sympy.Integer(val)
        input_guards.append((source, s))
        constraint_violated = False
        if isinstance(constraint, StrictMinMaxConstraint):
            if not s == constraint.vr.lower == constraint.vr.upper:
                constraint_violated = True
        elif isinstance(constraint, RelaxedUnspecConstraint):
            if val not in (0, 1):
                constraint_violated = True
        if constraint_violated:
            assert constraint is not None
            var_with_range = self._render_range_for_constraint_violation(source, constraint)
            user_stack = self.specialization_stacks.get(source, None)
            msg = f"You marked {self._debug_name(source)} as dynamic but your code specialized it to be a constant ({val}). If you're using mark_dynamic, either remove it or use maybe_mark_dynamic. If you're using Dim.DYNAMIC, replace it with either Dim.STATIC or Dim.AUTO." + ('\n\nUser stack:\n' + ''.join(user_stack.format()) if user_stack else '')
            record_constraint_violation(constraint.warn_only, self._debug_name(source), msg)

def _validate_left_right_on(self, left_on, right_on):
    (left_on, right_on) = super()._validate_left_right_on(left_on, right_on)
    if len(left_on) != 1 and (not self.left_index):
        raise MergeError('can only asof on a key for left')
    if <MASK>:
        raise MergeError('can only asof on a key for right')
    if self.left_index and isinstance(self.left.index, MultiIndex):
        raise MergeError('left can only have one index')
    if self.right_index and isinstance(self.right.index, MultiIndex):
        raise MergeError('right can only have one index')
    if self.by is not None:
        if self.left_by is not None or self.right_by is not None:
            raise MergeError('Can only pass by OR left_by and right_by')
        self.left_by = self.right_by = self.by
    if self.left_by is None and self.right_by is not None:
        raise MergeError('missing left_by')
    if self.left_by is not None and self.right_by is None:
        raise MergeError('missing right_by')
    if not self.left_index:
        left_on_0 = left_on[0]
        if isinstance(left_on_0, _known):
            lo_dtype = left_on_0.dtype
        else:
            lo_dtype = self.left._get_label_or_level_values(left_on_0).dtype if left_on_0 in self.left.columns else self.left.index.get_level_values(left_on_0)
    else:
        lo_dtype = self.left.index.dtype
    if not self.right_index:
        right_on_0 = right_on[0]
        if isinstance(right_on_0, _known):
            ro_dtype = right_on_0.dtype
        else:
            ro_dtype = self.right._get_label_or_level_values(right_on_0).dtype if right_on_0 in self.right.columns else self.right.index.get_level_values(right_on_0)
    else:
        ro_dtype = self.right.index.dtype
    if is_object_dtype(lo_dtype) or is_object_dtype(ro_dtype) or is_string_dtype(lo_dtype) or is_string_dtype(ro_dtype):
        raise MergeError(f'Incompatible merge dtype, {lo_dtype!r} and {ro_dtype!r}, both sides must have numeric dtype')
    if self.left_by is not None:
        if not is_list_like(self.left_by):
            self.left_by = [self.left_by]
        if not is_list_like(self.right_by):
            self.right_by = [self.right_by]
        if len(self.left_by) != len(self.right_by):
            raise MergeError('left_by and right_by must be the same length')
        left_on = self.left_by + list(left_on)
        right_on = self.right_by + list(right_on)
    return (left_on, right_on)

def rocm_version_numbers(path):
    possible_version_files = ['include/rocm-core/rocm_version.h', 'include/rocm_version.h']
    version_file = None
    for f in possible_version_files:
        version_file_path = os.path.join(path, f)
        if <MASK>:
            version_file = version_file_path
            break
    if not version_file:
        raise ConfigError('ROCm version file not found in {}'.format(possible_version_files))
    major = _get_header_version(version_file, 'ROCM_VERSION_MAJOR')
    minor = _get_header_version(version_file, 'ROCM_VERSION_MINOR')
    patch = _get_header_version(version_file, 'ROCM_VERSION_PATCH')
    return (major, minor, patch)

def compute_queue_depth(self):
    """
        Computes queue_depth at each event. This will calculate the queue depth data for
        All the events in the tree.
        This will return a list of Interval of queue depth data of cuda launch and kernels.
        """
    assert self.profile.kineto_results is not None
    cuda_event_list = self.profile.kineto_results.events()

    def is_cuda_launch_kernel(e):
        """Check if the event is a CUDA launch kernel."""
        launch_patterns = {'cudaLaunchKernel', 'cudaLaunchKernelExC', '__cudaLaunchKernel', 'cudaLaunchCooperativeKernel', 'cudaLaunchCooperativeKernelMultiDevice'}
        name = str(getattr(e, 'name', e))
        return any((name.startswith(pattern) for pattern in launch_patterns))

    def is_cuda_kernel(e):
        """Check if the event is a CUDA runtime kernel."""
        if e.device_type() != DeviceType.CUDA:
            return False
        name = str(getattr(e, 'name', e)).lower()
        exclude_patterns = {'mem', 'cpy', 'alloc', 'free'}
        return not any((pattern in name for pattern in exclude_patterns))
    cuda_launch_events = sorted((e for e in cuda_event_list if is_cuda_launch_kernel(e)), key=lambda x: x.start_ns())
    cuda_kernel_events = sorted((e for e in cuda_event_list if is_cuda_kernel(e)), key=lambda x: x.start_ns())
    self.cuda_events = sorted(cuda_launch_events + cuda_kernel_events, key=lambda x: x.start_ns())
    kernel_mapping: dict[_KinetoEvent, int] = {}
    last_mapped_kernel = 0
    for cuda_launch_event in cuda_launch_events:
        index = index_of_first_match(cuda_kernel_events, lambda x: x.linked_correlation_id() == cuda_launch_event.linked_correlation_id(), start=last_mapped_kernel)
        kernel_mapping[cuda_launch_event] = index
        last_mapped_kernel = index if index is not None else last_mapped_kernel
    current_kernel_index = 0
    spawned_kernel_index = -1
    all_events = cuda_launch_events + cuda_kernel_events + self.events

    def new_old_event_comparator(event):
        if hasattr(event, 'start_us'):
            return event.start_us() * 1000
        if hasattr(event, 'start_ns'):
            return event.start_ns()
        if hasattr(event, 'start_time_ns'):
            return event.start_time_ns
        raise Exception('Unknown Event Type')
    queue_depth_list: list[Interval] = []
    all_events.sort(key=new_old_event_comparator)
    for event in all_events:
        if hasattr(event, 'start_us'):
            start_time = event.start_us() * 1000
            end_time = (event.start_us() + event.duration_us()) * 1000
            if <MASK>:
                spawned_kernel_index = kernel_mapping[event]
        if hasattr(event, 'start_ns'):
            start_time = event.start_ns()
            end_time = event.start_ns() + event.duration_ns()
            if event in kernel_mapping and kernel_mapping[event] is not None:
                spawned_kernel_index = kernel_mapping[event]
        elif hasattr(event, 'start_time_ns'):
            start_time = event.start_time_ns
            end_time = event.end_time_ns
        while current_kernel_index < len(cuda_kernel_events) and cuda_kernel_events[current_kernel_index].start_ns() <= start_time:
            current_kernel_index += 1
        current_queue_depth = spawned_kernel_index - current_kernel_index + 1
        current_queue_depth = max(current_queue_depth, 0)
        if hasattr(event, 'start_us') or hasattr(event, 'start_ns'):
            queue_depth_list.append(Interval(start_time, end_time, current_queue_depth))
        elif hasattr(event, 'start_time_ns'):
            self.metrics[EventKey(event)].queue_depth = current_queue_depth
    return queue_depth_list

def _generate_marginal_results(table, data: DataFrame, values, rows, cols, aggfunc, kwargs, observed: bool, margins_name: Hashable='All', dropna: bool=True):
    margin_keys: list | Index
    if len(cols) > 0:
        table_pieces = []
        margin_keys = []

        def _all_key(key):
            return (key, margins_name) + ('',) * (len(cols) - 1)
        if len(rows) > 0:
            margin = data[rows + values].groupby(rows, observed=observed, dropna=dropna).agg(aggfunc, **kwargs)
            cat_axis = 1
            for (key, piece) in table.T.groupby(level=0, observed=observed):
                piece = piece.T
                all_key = _all_key(key)
                piece[all_key] = margin[key]
                table_pieces.append(piece)
                margin_keys.append(all_key)
        else:
            margin = data[cols[:1] + values].groupby(cols[:1], observed=observed, dropna=dropna).agg(aggfunc, **kwargs).T
            cat_axis = 0
            for (key, piece) in table.groupby(level=0, observed=observed):
                if len(cols) > 1:
                    all_key = _all_key(key)
                else:
                    all_key = margins_name
                table_pieces.append(piece)
                transformed_piece = margin[key].to_frame().T
                if <MASK>:
                    transformed_piece.index = MultiIndex.from_tuples([all_key], names=piece.index.names + [None])
                else:
                    transformed_piece.index = Index([all_key], name=piece.index.name)
                table_pieces.append(transformed_piece)
                margin_keys.append(all_key)
        if not table_pieces:
            return table
        else:
            result = concat(table_pieces, axis=cat_axis)
        if len(rows) == 0:
            return result
    else:
        result = table
        margin_keys = table.columns
    if len(cols) > 0:
        row_margin = data[cols + values].groupby(cols, observed=observed, dropna=dropna).agg(aggfunc, **kwargs)
        row_margin = row_margin.stack()
        new_order_indices = itertools.chain([len(cols)], range(len(cols)))
        new_order_names = [row_margin.index.names[i] for i in new_order_indices]
        row_margin.index = row_margin.index.reorder_levels(new_order_names)
    else:
        row_margin = data._constructor_sliced(np.nan, index=result.columns)
    return (result, margin_keys, row_margin)

def _reduce_to_lowest_terms(expr: sympy.Expr) -> sympy.Expr:
    """
    Eliminates any integer factor from a given expression.
    E.g., 6x + 4y reduces to 3x + 2y.

    Useful when an expression is == or != to 0.
    """

    def integer_coefficient(x: sympy.Expr) -> int:
        if x.is_Integer:
            return abs(int(x))
        elif x.is_Mul:
            return abs(int(x.args[0])) if x.args[0].is_Integer else 1
        else:
            return 1

    def div_by_factor(x: sympy.Expr, factor: int) -> sympy.Expr:
        if x.is_Integer:
            return x / factor
        elif x.is_Mul:
            if x.args[0] != factor:
                args = [x.args[0] / sympy.Integer(factor), *x.args[1:]]
            else:
                args = list(x.args[1:])
            return _sympy_from_args(sympy.Mul, args, is_commutative=x.is_commutative)
        else:
            raise AssertionError(f'illegal arg to div_by_factor: {x}')
    if expr.is_Add:
        atoms = cast(Sequence[sympy.Expr], expr.args)
        factor = functools.reduce(math.gcd, map(integer_coefficient, atoms))
        if factor == 1:
            return expr
        atoms = [div_by_factor(x, factor) for x in atoms]
        return _sympy_from_args(sympy.Add, atoms, sort=True, is_commutative=expr.is_commutative)
    elif expr.is_Integer:
        return S.One
    elif <MASK>:
        return div_by_factor(expr, integer_coefficient(expr))
    return expr

def sympy_str(expr: sympy.Expr) -> str:
    """
    Normal sympy str is very slow, this is a lot faster.  The result are
    somewhat worse, as it doesn't do as much simplification.  So don't
    use this for final codegen.
    """

    def is_neg_lead(expr: sympy.Expr) -> bool:
        return isinstance(expr, sympy.Mul) and len(expr.args) == 2 and (expr.args[0] == -1)

    def sympy_str_add(expr: sympy.Expr) -> str:
        if isinstance(expr, sympy.Add):
            if len(expr.args) == 2 and is_neg_lead(expr.args[1]):
                return f'{sympy_str_mul(expr.args[0])} - {sympy_str_mul(expr.args[1].args[1])}'
            else:
                return ' + '.join(map(sympy_str_mul, expr.args))
        else:
            return sympy_str_mul(expr)

    def sympy_str_mul(expr: sympy.Expr) -> str:
        if isinstance(expr, sympy.Mul):
            if is_neg_lead(expr):
                return f'-{sympy_str_atom(expr.args[1])}'
            else:
                return ' * '.join(map(sympy_str_atom, expr.args))
        else:
            return sympy_str_atom(expr)

    def sympy_str_atom(expr: sympy.Expr) -> str:
        if isinstance(expr, sympy.Symbol):
            return expr.name
        elif <MASK>:
            return f'({sympy_str_add(expr)})'
        elif isinstance(expr, (ModularIndexing, CleanDiv, FloorDiv, Identity)):
            return f"{expr.func.__name__}({', '.join(map(sympy_str, expr.args))})"
        else:
            return str(expr)
    return sympy_str_add(expr)

