def __enter__(self):
    if _shared_object_disabled():
        return None
    global SHARED_OBJECT_SAVING
    if <MASK>:
        self._passthrough = True
        return _shared_object_saving_scope()
    else:
        self._passthrough = False
    SHARED_OBJECT_SAVING.scope = self
    self._shared_objects_config = weakref.WeakKeyDictionary()
    self._next_id = 0
    return self

def _compute_stride(old_shape, old_stride, new_shape, size_oblivious=False):
    from torch.fx.experimental.symbolic_shapes import guard_or_false, guard_or_true, sym_eq

    def maybe_guard_or_false(x):
        if size_oblivious:
            return guard_or_false(x)
        return x

    def maybe_guard_or_true(x):
        if size_oblivious:
            return guard_or_true(x)
        return x
    if len(old_shape) == 0:
        return [1] * len(new_shape)
    numel = reduce(operator.mul, old_shape, 1)
    zero_numel = maybe_guard_or_false(numel == 0)
    if zero_numel and maybe_guard_or_false(sym_eq(old_shape, new_shape)):
        return old_stride
    new_stride = [0] * len(new_shape)
    if zero_numel:
        for view_d in range(len(new_shape) - 1, -1, -1):
            if view_d == len(new_shape) - 1:
                new_stride[view_d] = 1
            else:
                new_stride[view_d] = max(new_shape[view_d + 1], 1) * new_stride[view_d + 1]
        return new_stride
    view_d = len(new_shape) - 1
    chunk_base_stride = old_stride[-1]
    tensor_numel = 1
    view_numel = 1
    for tensor_d in range(len(old_shape) - 1, -1, -1):
        tensor_numel *= old_shape[tensor_d]
        if tensor_d == 0 or (maybe_guard_or_true(old_shape[tensor_d - 1] != 1) and maybe_guard_or_true(old_stride[tensor_d - 1] != tensor_numel * chunk_base_stride)):
            while view_d >= 0 and (maybe_guard_or_true(view_numel < tensor_numel) or maybe_guard_or_false(new_shape[view_d] == 1)):
                new_stride[view_d] = view_numel * chunk_base_stride
                view_numel *= new_shape[view_d]
                view_d -= 1
            if maybe_guard_or_true(view_numel != tensor_numel):
                return None
            if <MASK>:
                chunk_base_stride = old_stride[tensor_d - 1]
                tensor_numel = 1
                view_numel = 1
    if view_d != -1:
        return None
    return new_stride

def to_numpy(x):
    if <MASK>:
        numpy = x._numpy()
    elif x is not None:
        numpy = x.numpy()
    else:
        return None
    if isinstance(numpy, np.ndarray):
        numpy.setflags(write=False)
    return numpy

def get_input(self) -> torch.fx.Node:
    if <MASK>:
        return self.node.args[0]
    else:
        return self.node.kwargs['input']

def _get_module_path_and_prefix(obs_node: Node, node_name_to_scope: dict[str, tuple[str, type]], node_name_to_qconfig: dict[str, QConfigAny]) -> tuple[str, str]:
    """Given and observer node, get the `Scope` or the fully qualified name for
    the submodule containing the observed node, also return a prefix of "_input"
    when the observed node is an input of a F.linear op, and not the output of another
    quantized op.
    TODO: this logic is hacky, we should think about how to remove it or make it more
    general
    """
    observed_node = obs_node.args[0]
    assert isinstance(observed_node, Node), f'Expecting observed node to be a Node, but got {observed_node}'
    is_input_observer_only = node_name_to_qconfig[observed_node.name] is None if observed_node.name in node_name_to_qconfig else None
    if is_input_observer_only:
        users = list(obs_node.users)
        first_linear_use_or_first_use = users[0] if users else None
        linear_node = None
        for n in users:
            if n.op == 'call_function' and n.target == torch.nn.functional.linear:
                linear_node = n
                break
        if linear_node:
            first_linear_use_or_first_use = linear_node
        prefix = '_input'
    else:
        first_linear_use_or_first_use = observed_node
        prefix = ''
    if <MASK>:
        (module_path, _) = node_name_to_scope[first_linear_use_or_first_use.name]
    else:
        module_path = ''
    return (module_path, prefix)

def standard_mock_service_client(self, mock_instance_groups=None, mock_instances=None):
