    if mock_instances is None:
        mock_instances = self.standard_mock_instances()
    mock_client = mock.MagicMock()
    mock_client.instanceGroups.return_value = mock_instance_groups
    mock_client.instances.return_value = mock_instances
    return mock_client

@st.composite
def per_channel_tensor(draw, shapes=None, elements=None, qparams=None):
    if isinstance(shapes, SearchStrategy):
        _shape = draw(shapes)
    else:
        _shape = draw(st.sampled_from(shapes))
    if qparams is None:
        if <MASK>:
            elements = floats(-1000000.0, 1000000.0, allow_nan=False, width=32)
        X = draw(stnp.arrays(dtype=np.float32, elements=elements, shape=_shape))
        assume(not (np.isnan(X).any() or np.isinf(X).any()))
        return (X, None)
    qparams = draw(qparams)
    if elements is None:
        (min_value, max_value) = _get_valid_min_max(qparams)
        elements = floats(min_value, max_value, allow_infinity=False, allow_nan=False, width=32)
    X = draw(stnp.arrays(dtype=np.float32, elements=elements, shape=_shape))
    (scale, zp) = _calculate_dynamic_per_channel_qparams(X, qparams[2])
    enforced_zp = _ENFORCED_ZERO_POINT.get(qparams[2], None)
    if enforced_zp is not None:
        zp = enforced_zp
    axis = int(np.random.randint(0, X.ndim, 1))
    permute_axes = np.arange(X.ndim)
    permute_axes[0] = axis
    permute_axes[axis] = 0
    X = np.transpose(X, permute_axes)
    return (X, (scale, zp, axis, qparams[2]))

def update(self, modules: Mapping[str, Module]) -> None:
    """Update the :class:`~torch.nn.ModuleDict` with key-value pairs from a mapping, overwriting existing keys.

        .. note::
            If :attr:`modules` is an ``OrderedDict``, a :class:`~torch.nn.ModuleDict`, or
            an iterable of key-value pairs, the order of new elements in it is preserved.

        Args:
            modules (iterable): a mapping (dictionary) from string to :class:`~torch.nn.Module`,
                or an iterable of key-value pairs of type (string, :class:`~torch.nn.Module`)
        """
    if not isinstance(modules, container_abcs.Iterable):
        raise TypeError('ModuleDict.update should be called with an iterable of key/value pairs, but got ' + type(modules).__name__)
    if isinstance(modules, (OrderedDict, ModuleDict, container_abcs.Mapping)):
        for (key, module) in modules.items():
            self[key] = module
    else:
        for (j, m) in enumerate(modules):
            if <MASK>:
                raise TypeError('ModuleDict update sequence element #' + str(j) + ' should be Iterable; is' + type(m).__name__)
            if not len(m) == 2:
                raise ValueError('ModuleDict update sequence element #' + str(j) + ' has length ' + str(len(m)) + '; 2 is required')
            self[m[0]] = m[1]

def _check_related_name_is_valid(self):
    import keyword
    related_name = self.remote_field.related_name
    if <MASK>:
        return []
    is_valid_id = not keyword.iskeyword(related_name) and related_name.isidentifier()
    if not (is_valid_id or related_name.endswith('+')):
        return [checks.Error("The name '%s' is invalid related_name for field %s.%s" % (self.remote_field.related_name, self.model._meta.object_name, self.name), hint="Related name must be a valid Python identifier or end with a '+'", obj=self, id='fields.E306')]
    return []

def transform_dict_like(self, func) -> DataFrame:
    """
        Compute transform in the case of a dict-like func
        """
    from pandas.core.reshape.concat import concat
    obj = self.obj
    args = self.args
    kwargs = self.kwargs
    assert isinstance(obj, ABCNDFrame)
    if <MASK>:
        raise ValueError('No transform functions were provided')
    func = self.normalize_dictlike_arg('transform', obj, func)
    results: dict[Hashable, DataFrame | Series] = {}
    for (name, how) in func.items():
        colg = obj._gotitem(name, ndim=1)
        results[name] = colg.transform(how, 0, *args, **kwargs)
    return concat(results, axis=1)

def _precompute_metric_params(X, Y, metric=None, **kwds):
    """Precompute data-derived metric parameters if not provided."""
    if metric == 'seuclidean' and 'V' not in kwds:
        if <MASK>:
            V = np.var(X, axis=0, ddof=1)
        else:
            raise ValueError("The 'V' parameter is required for the seuclidean metric when Y is passed.")
        return {'V': V}
    if metric == 'mahalanobis' and 'VI' not in kwds:
        if X is Y:
            VI = np.linalg.inv(np.cov(X.T)).T
        else:
            raise ValueError("The 'VI' parameter is required for the mahalanobis metric when Y is passed.")
        return {'VI': VI}
    return {}

def _case_verify_and_canonicalize_args(pred_fn_pairs, exclusive, name, allow_python_preds):
    """Verifies input arguments for the case function.

  Args:
    pred_fn_pairs: Dict or list of pairs of a boolean scalar tensor, and a
      callable which returns a list of tensors.
    exclusive: True iff at most one predicate is allowed to evaluate to `True`.
    name: A name for the case operation.
    allow_python_preds: if true, pred_fn_pairs may contain Python bools in
      addition to boolean Tensors

  Raises:
    TypeError: If `pred_fn_pairs` is not a list/dictionary.
    TypeError: If `pred_fn_pairs` is a list but does not contain 2-tuples.
    TypeError: If `fns[i]` is not callable for any i, or `default` is not
               callable.

  Returns:
    a tuple <list of scalar bool tensors, list of callables>.
  """
    if not isinstance(pred_fn_pairs, (list, tuple, dict)):
        raise TypeError(f"'pred_fn_pairs' must be a list, tuple, or dict. Received: {type(pred_fn_pairs)}")
    if isinstance(pred_fn_pairs, collections.OrderedDict):
        pred_fn_pairs = pred_fn_pairs.items()
    elif <MASK>:
        if context.executing_eagerly():
            if not exclusive:
                raise ValueError("Unordered dictionaries are not supported for the 'pred_fn_pairs' argument when `exclusive=False` and eager mode is enabled.")
            pred_fn_pairs = list(pred_fn_pairs.items())
        else:
            pred_fn_pairs = sorted(pred_fn_pairs.items(), key=lambda item: item[0].name)
            if not exclusive:
                logging.warn('%s: An unordered dictionary of predicate/fn pairs was provided, but exclusive=False. The order of conditional tests is deterministic but not guaranteed.', name)
    for pred_fn_pair in pred_fn_pairs:
        if not isinstance(pred_fn_pair, tuple) or len(pred_fn_pair) != 2:
            raise TypeError(f"Each entry in 'pred_fn_pairs' must be a 2-tuple. Received {pred_fn_pair}.")
        (pred, fn) = pred_fn_pair
        if isinstance(pred, tensor.Tensor):
            if pred.dtype != dtypes.bool:
                raise TypeError('pred must be Tensor of type bool: %s' % pred.name)
        elif not allow_python_preds:
            raise TypeError('pred must be a Tensor, got: %s' % pred)
        elif not isinstance(pred, bool):
            raise TypeError('pred must be a Tensor or bool, got: %s' % pred)
        if not callable(fn):
            raise TypeError('fn for pred %s must be callable.' % pred.name)
    (predicates, actions) = zip(*pred_fn_pairs)
    return (predicates, actions)

def _generate_iterdatapipe_msg(datapipe, simplify_dp_name: bool=False):
    output_string = f'{datapipe.__class__.__name__}({_generate_input_args_string(datapipe)})'
    if <MASK>:
