def __init__(self, data=None, index: Axes | None=None, columns: Axes | None=None, dtype: Dtype | None=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if isinstance(data, DataFrame):
        data = data._mgr
        allow_mgr = True
        if not copy:
            data = data.copy(deep=False)
    if isinstance(data, BlockManager):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        if index is None and columns is None and (dtype is None) and (not copy):
            NDFrame.__init__(self, data)
            return
    if isinstance(index, set):
        raise ValueError('index cannot be a set')
    if isinstance(columns, set):
        raise ValueError('columns cannot be a set')
    if copy is None:
        if isinstance(data, dict):
            copy = True
        elif not isinstance(data, (Index, DataFrame, Series)):
            copy = True
        else:
            copy = False
    if data is None:
        index = index if index is not None else default_index(0)
        columns = columns if columns is not None else default_index(0)
        dtype = dtype if dtype is not None else pandas_dtype(object)
        data = []
    if isinstance(data, BlockManager):
        mgr = self._init_mgr(data, axes={'index': index, 'columns': columns}, dtype=dtype, copy=copy)
    elif isinstance(data, dict):
        mgr = dict_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, ma.MaskedArray):
        from numpy.ma import mrecords
        if isinstance(data, mrecords.MaskedRecords):
            raise TypeError('MaskedRecords are not supported. Pass {name: data[name] for name in data.dtype.names} instead')
        data = sanitize_masked_array(data)
        mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, (np.ndarray, Series, Index, ExtensionArray)):
        if <MASK>:
            data = cast(np.ndarray, data)
            mgr = rec_array_to_mgr(data, index, columns, dtype, copy)
        elif isinstance(data, (ABCSeries, ABCIndex)) and data.name is not None:
            mgr = dict_to_mgr({data.name: data}, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif is_list_like(data):
        if not isinstance(data, abc.Sequence):
            if hasattr(data, '__array__'):
                data = np.asarray(data)
            else:
                data = list(data)
        if len(data) > 0:
            if is_dataclass(data[0]):
                data = dataclasses_to_dicts(data)
            if not isinstance(data, np.ndarray) and treat_as_nested(data):
                if columns is not None:
                    columns = ensure_index(columns)
                (arrays, columns, index) = nested_data_to_arrays(data, columns, index, dtype)
                mgr = arrays_to_mgr(arrays, columns, index, dtype=dtype)
            else:
                mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = dict_to_mgr({}, index, columns if columns is not None else default_index(0), dtype=dtype)
    else:
        if index is None or columns is None:
            raise ValueError('DataFrame constructor not properly called!')
        index = ensure_index(index)
        columns = ensure_index(columns)
        if not dtype:
            (dtype, _) = infer_dtype_from_scalar(data)
        if isinstance(dtype, ExtensionDtype):
            values = [construct_1d_arraylike_from_scalar(data, len(index), dtype) for _ in range(len(columns))]
            mgr = arrays_to_mgr(values, columns, index, dtype=None)
        else:
            arr2d = construct_2d_arraylike_from_scalar(data, len(index), len(columns), dtype, copy)
            mgr = ndarray_to_mgr(arr2d, index, columns, dtype=arr2d.dtype, copy=False)
    NDFrame.__init__(self, mgr)

def substitute_solution_one_type(mapping, t):
    """
    Apply the most general unifier to a type
    """
    if isinstance(t, Var):
        if <MASK>:
            return mapping[t]
        else:
            return t
    elif isinstance(t, TensorType):
        new_type = []
        for typ in t.__args__:
            if typ in mapping.keys():
                new_type.append(mapping[typ])
            else:
                new_type.append(typ)
        return TensorType(tuple(new_type))
    elif isinstance(t, list):
        new_type = []
        for typ in t:
            new_type.append(substitute_solution_one_type(mapping, typ))
        return new_type
    elif isinstance(t, tuple):
        new_type = []
        for typ in t:
            new_type.append(substitute_solution_one_type(mapping, typ))
        return tuple(new_type)
    else:
        return t

def _prefetch_stages(self, op, a_dtype_size, b_dtype_size, warp_size: int=64):
    version_str = op.block_gemm_pipeline_version.split('::')[-1]
    try:
        version = int(version_str[1:])
    except ValueError as e:
        raise ValueError(f'Invalid version string: {version_str}') from e
    if version not in [1, 2, 3, 4, 5]:
        raise ValueError(f'unknown prefetch stages for {op.block_gemm_pipeline_version}')
    version_to_stages = {1: 1, 3: 2, 4: 4, 5: 3}
    stages = version_to_stages.get(version)
    if <MASK>:
        wgp_per_cu = max(4 * warp_size // op.block_size, 1)
        full_mem_band_prefetch_stages = math.ceil(32768 / wgp_per_cu / ((op.m_per_block * a_dtype_size + op.n_per_block * b_dtype_size) * op.k_per_block))
        stages = min(max(full_mem_band_prefetch_stages, 2), 8)
    return stages

def _tf_data_map_structure(func, *structure, **check_types_dict):
    if not callable(func):
        raise TypeError(f'Argument `func` must be callable, got: {func}')
    if <MASK>:
        raise ValueError('Must provide at least one structure')
    if check_types_dict:
        if 'check_types' not in check_types_dict or len(check_types_dict) > 1:
            raise ValueError(f"Only valid keyword argument for `check_types_dict` is 'check_types'. Got {check_types_dict}.")
        check_types = check_types_dict['check_types']
    else:
        check_types = True
    for other in structure[1:]:
        _tf_data_assert_same_structure(structure[0], other, check_types=check_types)
    flat_structure = (_tf_data_flatten(s) for s in structure)
    entries = zip(*flat_structure)
    return _tf_data_pack_sequence_as(structure[0], [func(*x) for x in entries])

def __getitem__(self, k):
    """Retrieve an item or slice from the set of results."""
    if <MASK>:
        raise TypeError('QuerySet indices must be integers or slices, not %s.' % type(k).__name__)
    if isinstance(k, int) and k < 0 or (isinstance(k, slice) and (k.start is not None and k.start < 0 or (k.stop is not None and k.stop < 0))):
        raise ValueError('Negative indexing is not supported.')
    if self._result_cache is not None:
        return self._result_cache[k]
    if isinstance(k, slice):
        qs = self._chain()
        if k.start is not None:
            start = int(k.start)
        else:
            start = None
        if k.stop is not None:
            stop = int(k.stop)
        else:
            stop = None
        qs.query.set_limits(start, stop)
        return list(qs)[::k.step] if k.step else qs
    qs = self._chain()
    qs.query.set_limits(k, k + 1)
    qs._fetch_all()
    return qs._result_cache[0]

@staticmethod
def where(a, b, c):
    assert isinstance(V.kernel, CppVecKernel)
    if <MASK>:
        assert c.dtype == torch.bool
        (blendv_a, blendv_b, blendv_c) = unify_mask_base_type(V.kernel.compute, (a, b, c))
        return f'decltype({blendv_b})::blendv({blendv_c}, {blendv_b}, {blendv_a})'
    else:
        return f'decltype({b})::blendv({c}, {b}, {V.kernel._get_mask_cast(a, b.dtype)})'

@_onnx_symbolic('aten::log_softmax')
@symbolic_helper.parse_args('v', 'i', 'none')
def log_softmax(g: jit_utils.GraphContext, input, dim, dtype=None):
    input_dim = symbolic_helper._get_tensor_rank(input)
    if input_dim is None:
        return symbolic_helper._unimplemented('dim', 'ONNX and PyTorch use different strategies to split the input. Input rank must be known at export time.')
    if dim < 0:
        dim = input_dim + dim
    is_transpose_required = input_dim != dim + 1
    if is_transpose_required:
        axes = list(range(input_dim))
        (axes[dim], axes[-1]) = (axes[-1], axes[dim])
        input = g.op('Transpose', input, perm_i=axes)
        dim = input_dim - 1
    return_op = g.op('LogSoftmax', input, axis_i=dim)
    if <MASK>:
        parsed_dtype = symbolic_helper._get_const(dtype, 'i', 'dtype')
        return_op = g.op('Cast', return_op, to_i=_type_utils.JitScalarType(parsed_dtype).onnx_type())
    if is_transpose_required:
        return_op = g.op('Transpose', return_op, perm_i=axes)
    return return_op

def __torch_dispatch__(self, func: Any, types: tuple[Any, ...], args: tuple[Any, ...]=(), kwargs: dict[str, Any] | None=None) -> Any:
    if kwargs is None:
        kwargs = {}
    (flat_args, args_spec) = pytree.tree_flatten((args, kwargs))
    local_tensors = [a for a in flat_args if isinstance(a, LocalTensor)]
    has_unrecognized_types = _check_for_subclass(flat_args)
    if has_unrecognized_types:
        unrecognized_types = [type(x) for x in flat_args if _check_for_subclass_arg(x)]
        not_implemented_log.debug('LocalTensorMode unrecognized subclass(es): %s', unrecognized_types)
        return NotImplemented
    if not local_tensors:
        if self._disable or any((isinstance(a, Tensor) for a in flat_args)):
            return func(*args, **kwargs)
    for a in flat_args:
        if isinstance(a, LocalTensor):
            assert a._ranks <= self.ranks, f'Input LocalTensor {a} and LocalTensorMode must be configured for the same ranks'
    if func.namespace == 'c10d':
        if func is torch.ops.c10d.allreduce_.default:
            return _c10d._local_all_reduce_(*args, **kwargs)
        elif func is torch.ops.c10d.allreduce_coalesced_.default:
            return _c10d._local_allreduce_coalesced_(*args, **kwargs)
        elif func is torch.ops.c10d.reduce_scatter_tensor_coalesced_.default:
