            return _c10d._local_recv_(*args, **kwargs)
        elif func is torch.ops.c10d.recv_any_source_.default:
            return _c10d._local_recv_any_source_(*args, **kwargs)
        raise NotImplementedError(f'{func} not implemented')
    if func.namespace == '_c10d_functional' or func.namespace == '_dtensor':
        with LocalTensorMode(self.ranks):
            return func._op_dk(DispatchKey.CompositeExplicitAutograd, *args, **kwargs)
    if func.namespace == 'profiler':
        return func(*args, **kwargs)
    if func.namespace == '_c10d_functional_autograd':
        raise NotImplementedError(f'{func} not implemented')
    if func.namespace == 'symm_mem':
        raise NotImplementedError(f'{func} not implemented')
    return _for_each_rank_run_func(func, self.ranks, args, kwargs, alias=True)

def _init_group(self, group, params_with_grad, grads, square_avgs, momentum_buffer_list, grad_avgs, state_steps):
    has_complex = False
    for p in group['params']:
        if p.grad is None:
            continue
        has_complex |= torch.is_complex(p)
        params_with_grad.append(p)
        if p.grad.is_sparse:
            raise RuntimeError('RMSprop does not support sparse gradients')
        grads.append(p.grad)
        state = self.state[p]
        if len(state) == 0:
            state['step'] = torch.zeros((), dtype=_get_scalar_dtype(), device=p.device) if group['capturable'] else torch.zeros((), dtype=_get_scalar_dtype())
            state['square_avg'] = torch.zeros_like(p, memory_format=torch.preserve_format)
            if group['momentum'] > 0:
                state['momentum_buffer'] = torch.zeros_like(p, memory_format=torch.preserve_format)
            if <MASK>:
                state['grad_avg'] = torch.zeros_like(p, memory_format=torch.preserve_format)
        square_avgs.append(state['square_avg'])
        state_steps.append(state['step'])
        if group['momentum'] > 0:
            momentum_buffer_list.append(state['momentum_buffer'])
        if group['centered']:
            grad_avgs.append(state['grad_avg'])
    return has_complex

def get_training_arg_index(call_fn):
    """Returns the index of 'training' in the layer call function arguments.

  Args:
    call_fn: Call function.

  Returns:
    - n: index of 'training' in the call function arguments.
    - -1: if 'training' is not found in the arguments, but layer.call accepts
          variable keyword arguments
    - None: if layer doesn't expect a training argument.
  """
    argspec = tf_inspect.getfullargspec(call_fn)
    if argspec.varargs:
        if <MASK>:
            return -1
        return None
    else:
        arg_list = argspec.args
        if tf_inspect.ismethod(call_fn):
            arg_list = arg_list[1:]
        if 'training' in arg_list:
            return arg_list.index('training')
        elif 'training' in argspec.kwonlyargs or argspec.varkw:
            return -1
        return None

@torch._disable_dynamo
def add_param_group(self, param_group: dict[str, Any]) -> None:
    """Add a param group to the :class:`Optimizer` s `param_groups`.

        This can be useful when fine tuning a pre-trained network as frozen layers can be made
        trainable and added to the :class:`Optimizer` as training progresses.

        Args:
            param_group (dict): Specifies what Tensors should be optimized along with group
                specific optimization options.
        """
    if not isinstance(param_group, dict):
        raise TypeError(f'param_group must be a dict, but got {type(param_group)}')
    params = param_group['params']
    if isinstance(params, torch.Tensor):
        param_group['params'] = [params]
    elif isinstance(params, set):
        raise TypeError('optimizer parameters need to be organized in ordered collections, but the ordering of tensors in sets will change between runs. Please use a list instead.')
    else:
        param_group['params'] = list(params)
    extracted_param_tensors = []
    extracted_param_names = []
    for param in param_group['params']:
        if isinstance(param, tuple):
            param_name = param[0]
            extracted_param_names.append(param_name)
            extracted_param_tensors.append(param[1])
        else:
            extracted_param_tensors.append(param)
    param_group['params'] = extracted_param_tensors
    if len(extracted_param_names) != 0:
        if len(extracted_param_names) == len(extracted_param_tensors):
            param_group['param_names'] = extracted_param_names
        else:
            raise ValueError('all optimizer params should be with/without names. Some param names are missing')
    for param in param_group['params']:
        if not isinstance(param, torch.Tensor):
            raise TypeError('optimizer can only optimize Tensors, but one of the params is ' + torch.typename(param))
        if not self.defaults.get('differentiable', None) and (not (param.is_leaf or param.retains_grad)):
            raise ValueError("can't optimize a non-leaf Tensor")
    for (name, default) in self.defaults.items():
        if default is required and name not in param_group:
            raise ValueError(f"parameter group didn't specify a value of required optimization parameter {name}")
        else:
            param_group.setdefault(name, default)
    params = param_group['params']
    if len(params) != len(set(params)):
        warnings.warn('optimizer contains a parameter group with duplicate parameters; in future, this will cause an error; see github.com/pytorch/pytorch/issues/40967 for more information', stacklevel=3)
    param_set: set[torch.Tensor] = set()
    for group in self.param_groups:
        param_set.update(set(group['params']))
        if <MASK>:
            current_group_txt = 'with names' if 'param_names' in param_group else 'without names'
            raise ValueError(f'all optimizer param groups should be with/without names. cannot add param group {current_group_txt} to the optimizer')
    if not param_set.isdisjoint(set(param_group['params'])):
        raise ValueError('some parameters appear in more than one parameter group')
    self.param_groups.append(param_group)

def _annotate_qat_conv2d_bn_binary_unary(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = find_sequential_partitions(gm, [torch.nn.Conv2d, torch.nn.BatchNorm2d, operator.add, torch.nn.ReLU])
    for fused_partition in fused_partitions:
        (conv_partition, bn_partition, binary_partition, unary_partition) = fused_partition
        (conv_node, bn_output_node, binary_node, unary_node) = self._get_output_nodes_of_partitions([conv_partition, bn_partition, binary_partition, unary_partition])
        if len(bn_output_node.users) != 1:
            continue
        (bn_output_node_idx, extra_input_node_idx) = self._get_input_idx_for_binary_node(bn_output_node, binary_node)
        if bn_output_node_idx is None or extra_input_node_idx is None:
            continue
        if bn_output_node != binary_node.args[bn_output_node_idx]:
            raise ValueError(f"{bn_output_node} doesn't match input of binary node")
        extra_input_node = binary_node.args[extra_input_node_idx]
        if conv_node.op != 'call_function' or conv_node.target != torch.ops.aten.conv2d.default:
            continue
        if _skip_annotate([unary_node, binary_node, bn_output_node, conv_node], filter_fn):
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        if <MASK>:
            binary_node_input_qspec_map = {}
            binary_node_input_qspec_map[extra_input_node] = get_input_act_qspec(quantization_config)
            binary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(input_qspec_map=binary_node_input_qspec_map, _annotated=True)
            unary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(output_qspec=get_output_act_qspec(quantization_config), _annotated=True, _is_output_of_quantized_pattern=True)
        else:
            _annotate_nodes_not_quantize([binary_node, unary_node])
        nodes_to_mark_annotated = list(conv_partition.nodes)
        nodes_to_mark_annotated.extend(list(bn_partition.nodes))
        nodes_to_mark_annotated.extend(list(binary_partition.nodes))
        nodes_to_mark_annotated.extend(list(unary_partition.nodes))
        _mark_nodes_as_annotated(nodes_to_mark_annotated)

def _find_tensorrt_config(base_paths, required_version):

    def get_header_version(path):
        version = (_get_header_version(path, name) for name in ('NV_TENSORRT_MAJOR', 'NV_TENSORRT_MINOR', 'NV_TENSORRT_PATCH'))
        version = list(version)
        if <MASK>:
            return None
        return '.'.join(version)
    (header_path, header_version) = _find_header(base_paths, 'NvInferVersion.h', required_version, get_header_version)
    tensorrt_version = header_version.split('.')[0]
    library_path = _find_library(base_paths, 'nvinfer', tensorrt_version)
    return {'tensorrt_version': header_version, 'tensorrt_include_dir': os.path.dirname(header_path), 'tensorrt_library_dir': os.path.dirname(library_path)}

def decorator(f):

    @wraps(f)
    def wrapper(*args, **kw):
        if data_home is None:
            return f(*args, **kw)
        try:
            return f(*args, **kw)
        except URLError:
            raise
        except Exception as exc:
            if <MASK>:
                raise
            warn('Invalid cache, redownloading file', RuntimeWarning)
            local_path = _get_local_path(openml_path, data_home)
            if os.path.exists(local_path):
                os.unlink(local_path)
            return f(*args, **kw)
    return wrapper

def _get_output_info_for_cache_entry(self, state: _CacheKeyState, key: _DispatchCacheKey, func: OpOverload, args: Sequence[object], kwargs: Mapping[str, object], output: FakeTensor) -> _DispatchCacheEntryOutputInfo:
    if isinstance(output, (int, torch.SymInt, type(None))):
        return _DispatchCacheEntryOutputInfo(inplace_idx=None, metadata=None, view_idx=None, constant_value=output)
    for idx in range(len(args)):
        if id(args[idx]) == id(output):
            return _DispatchCacheEntryOutputInfo(inplace_idx=idx, metadata=None, view_idx=None)
    view_idx = None
    if isinstance(func, torch._ops.OpOverload) and func.is_view:
        idxs = [i for (i, t) in enumerate(args) if isinstance(t, Tensor)]
        assert len(idxs) == 1
        view_idx = idxs[0]
    metadata = extract_tensor_metadata(output)
    metadata.shape = tuple((state.convert_output(v) for v in metadata.shape))
    metadata.stride = tuple((state.convert_output(v) for v in metadata.stride))
    metadata.storage_offset = state.convert_output(metadata.storage_offset)
    metadata.storage_bytes = None if metadata.storage_bytes is None else state.convert_output(metadata.storage_bytes)
    entry = _DispatchCacheEntryOutputInfo(inplace_idx=None, metadata=metadata, view_idx=view_idx)
    entry_for_synth_output = _DispatchCacheValidEntry(output_infos=(entry,), is_output_tuple=False)
    from torch.fx.experimental.symbolic_shapes import GuardOnDataDependentSymNode
    try:
        synth_output = self._output_from_cache_entry(state, entry_for_synth_output, key, func, args)
    except GuardOnDataDependentSymNode:
        raise _BypassDispatchCache('data dependent symnode') from None
    synth_key_set = torch._C._dispatch_key_set(synth_output)
    key_set = torch._C._dispatch_key_set(output)
    if <MASK>:
        raise _BypassDispatchCache('dispatch_key_set mismatch')
    return entry

def update_state(self, y_true, y_pred, sample_weight=None):
    """Updates the state of per-output metrics."""
    y_true = self._conform_to_outputs(y_pred, y_true)
    sample_weight = self._conform_to_outputs(y_pred, sample_weight)
    if not self._built:
        self.build(y_pred, y_true)
    y_pred = nest.flatten(y_pred)
    y_true = nest.flatten(y_true) if y_true is not None else []
    sample_weight = nest.flatten(sample_weight)
    zip_args = (y_true, y_pred, sample_weight, self._metrics, self._weighted_metrics)
    for (y_t, y_p, sw, metric_objs, weighted_metric_objs) in zip(*zip_args):
        if y_t is None or (all((m is None for m in metric_objs)) and all((wm is None for wm in weighted_metric_objs))):
            continue
        (y_t, y_p, sw) = match_dtype_and_rank(y_t, y_p, sw)
        mask = get_mask(y_p)
        sw = apply_mask(y_p, sw, mask)
        for metric_obj in metric_objs:
            if <MASK>:
                continue
            metric_obj.update_state(y_t, y_p, sample_weight=mask)
        for weighted_metric_obj in weighted_metric_objs:
            if weighted_metric_obj is None:
                continue
            weighted_metric_obj.update_state(y_t, y_p, sample_weight=sw)

def get_order_dir(field, default='ASC'):
    """
    Return the field name and direction for an order specification. For
    example, '-foo' is returned as ('foo', 'DESC').

    The 'default' param is used to indicate which way no prefix (or a '+'
    prefix) should sort. The '-' prefix always sorts the opposite way.
    """
    dirn = ORDER_DIR[default]
    if <MASK>:
        return (field[1:], dirn[1])
    return (field, dirn[0])

def call(self, inputs):
    input_shape = inputs.shape
    if self._is_causal:
        inputs = array_ops.pad(inputs, self._compute_causal_padding(inputs))
    outputs = self._convolution_op(inputs, self.kernel)
    if self.use_bias:
        output_rank = outputs.shape.rank
        if <MASK>:
            bias = array_ops.reshape(self.bias, (1, self.filters, 1))
            outputs += bias
        elif output_rank is not None and output_rank > 2 + self.rank:

            def _apply_fn(o):
                return nn.bias_add(o, self.bias, data_format=self._tf_data_format)
            outputs = conv_utils.squeeze_batch_dims(outputs, _apply_fn, inner_rank=self.rank + 1)
        else:
            outputs = nn.bias_add(outputs, self.bias, data_format=self._tf_data_format)
    if not context.executing_eagerly():
        out_shape = self.compute_output_shape(input_shape)
        outputs.set_shape(out_shape)
    if self.activation is not None:
        return self.activation(outputs)
    return outputs

def fn(*args):
    if is_bw:
        self._maybe_set_engine_callback()
    if name in self.parents and (not self.is_bw):

        def custom_formatwarning(msg, category, filename, lineno, line=None):
            return f'{filename}:{lineno}: {category.__name__}: {msg} \n'
        warnings.formatwarning = custom_formatwarning
        warnings.warn('The module hierarchy tracking maybe be messed up. Please file a bug to PyTorch, if it is the case.')
    if <MASK>:
        self._active_module_cnt[name] = 1
        self.parents.add(name)
    else:
        self._active_module_cnt[name] += 1
    if self._user_pre_bw_hook is not None and is_bw:
        self._user_pre_bw_hook(w_mod(), args)

def __getattribute__(self, name):
    if name == 'experimental_threading':
        logging.warning('options.experimental_threading is deprecated. Use options.threading instead.')
        return getattr(self, 'threading')
    if <MASK>:
        return getattr(self, 'deterministic')
    return super(Options, self).__getattribute__(name)

def _zeros(shape, dtype):
    """Helper to return (possibly cached) zero tensors in eager mode."""
    if dtype == dtypes.string or dtype == dtypes.resource:
        return None
    ctx = context.context()
    if not ctx.executing_eagerly():
        return array_ops.zeros(shape, dtype)
    device = ctx.device_name
    if tensor_util.is_tf_type(shape):
        shape_key = shape.ref()
    else:
        shape_key = shape
    cache_key = (shape_key, dtype, device)
    cached = ctx.zeros_cache().get(cache_key)
    if cached is None:
        if <MASK>:
            value = False
        else:
            value = 0
        cached = _fast_fill(value, shape, dtype)
        ctx.zeros_cache().put(cache_key, cached)
    return cached

def as_string(self):
    """Return a string of the file contents."""
    items = {'replaces_str': '', 'initial_str': '', 'run_before_str': '', 'atomic_str': ''}
    imports = set()
    operations = []
    for operation in self.migration.operations:
        (operation_string, operation_imports) = OperationWriter(operation).serialize()
        imports.update(operation_imports)
        operations.append(operation_string)
    items['operations'] = '\n'.join(operations) + '\n' if operations else ''
    dependencies = []
    for dependency in self.migration.dependencies:
        if dependency[0] == '__setting__':
            dependencies.append('        migrations.swappable_dependency(settings.%s),' % dependency[1])
            imports.add('from django.conf import settings')
        else:
            dependencies.append('        %s,' % self.serialize(dependency)[0])
    items['dependencies'] = '\n'.join(sorted(dependencies)) + '\n' if dependencies else ''
    migration_imports = set()
    for line in list(imports):
        if re.match('^import (.*)\\.\\d+[^\\s]*$', line):
            migration_imports.add(line.split('import')[1].strip())
            imports.remove(line)
            self.needs_manual_porting = True
    if <MASK>:
        imports.discard('from django.db import models')
        imports.add('from django.db import migrations, models')
    else:
        imports.add('from django.db import migrations')
    sorted_imports = sorted(imports, key=lambda i: (i.split()[0] == 'from', i.split()[1]))
    items['imports'] = '\n'.join(sorted_imports) + '\n' if imports else ''
    if migration_imports:
        items['imports'] += '\n\n# Functions from the following migrations need manual copying.\n# Move them and any dependencies into this file, then update the\n# RunPython operations to refer to the local versions:\n# %s' % '\n# '.join(sorted(migration_imports))
    if self.migration.replaces:
        items['replaces_str'] = '\n    replaces = %s\n' % self.serialize(self.migration.replaces)[0]
    if self.migration.run_before:
        items['run_before_str'] = '\n    run_before = %s\n' % self.serialize(self.migration.run_before)[0]
    if self.include_header:
        items['migration_header'] = MIGRATION_HEADER_TEMPLATE % {'version': get_version(), 'timestamp': now().strftime('%Y-%m-%d %H:%M')}
    else:
        items['migration_header'] = ''
    if self.migration.initial:
        items['initial_str'] = '\n    initial = True\n'
    if not self.migration.atomic:
        items['atomic_str'] = '\n    atomic = False\n'
    return MIGRATION_TEMPLATE % items

def __get__(self, instance: Union[T, None], obj_type: Any=None) -> 'R | _lazy_property_and_property[T, R]':
    if <MASK>:
        return _lazy_property_and_property(self.wrapped)
    with torch.enable_grad():
        value = self.wrapped(instance)
    setattr(instance, self.wrapped.__name__, value)
    return value

def build_err_msg(arrays, err_msg, header='Items are not equal:', verbose=True, names=('ACTUAL', 'DESIRED'), precision=8):
    msg = ['\n' + header]
    if err_msg:
        if err_msg.find('\n') == -1 and len(err_msg) < 79 - len(header):
            msg = [msg[0] + ' ' + err_msg]
        else:
            msg.append(err_msg)
    if <MASK>:
        for (i, a) in enumerate(arrays):
            if isinstance(a, ndarray):
                r_func = ndarray.__repr__
            else:
                r_func = repr
            try:
                r = r_func(a)
            except Exception as exc:
                r = f'[repr failed for <{type(a).__name__}>: {exc}]'
            if r.count('\n') > 3:
                r = '\n'.join(r.splitlines()[:3])
                r += '...'
            msg.append(f' {names[i]}: {r}')
    return '\n'.join(msg)

def main(unused_argv=None):
    logging.set_verbosity(logging.INFO)
    tf_version = versions.__version__
    print('TensorFlow version %s detected' % tf_version)
    print('Welcome to the Cloud TPU Profiler v%s' % profiler_version.__version__)
    if Version(tf_version) < Version('2.2.0'):
        sys.exit('You must install tensorflow >= 2.2.0 to use this plugin.')
    if not FLAGS.service_addr and (not FLAGS.tpu):
        sys.exit('You must specify either --service_addr or --tpu.')
    tpu_cluster_resolver = None
    if FLAGS.service_addr:
        if FLAGS.tpu:
            logging.warn('Both --service_addr and --tpu are set. Ignoring --tpu and using --service_addr.')
        service_addr = FLAGS.service_addr
    else:
        try:
            tpu_cluster_resolver = resolver.TPUClusterResolver([FLAGS.tpu], zone=FLAGS.tpu_zone, project=FLAGS.gcp_project)
            service_addr = tpu_cluster_resolver.get_master()
        except (ValueError, TypeError):
            sys.exit('Failed to find TPU %s in zone %s project %s. You may use --tpu_zone and --gcp_project to specify the zone and project of your TPU.' % (FLAGS.tpu, FLAGS.tpu_zone, FLAGS.gcp_project))
    service_addr = service_addr.replace('grpc://', '').replace(':8470', ':8466')
    workers_list = ''
    if FLAGS.workers_list is not None:
        workers_list = FLAGS.workers_list
    elif tpu_cluster_resolver is not None:
        workers_list = get_workers_list(tpu_cluster_resolver)
    duration_ms = FLAGS.duration_ms if FLAGS.duration_ms > 0 else 1000
    if FLAGS.monitoring_level > 0:
        print('Since monitoring level is provided, profile', service_addr, ' for ', FLAGS.duration_ms, ' ms and show metrics for ', FLAGS.num_queries, ' time(s).')
        monitoring_helper(service_addr, duration_ms, FLAGS.monitoring_level, FLAGS.num_queries)
    else:
        if not FLAGS.logdir:
            sys.exit('You must specify either --logdir or --monitoring_level.')
        if not gfile.Exists(FLAGS.logdir):
            gfile.MakeDirs(FLAGS.logdir)
        try:
            if <MASK>:
                profiler_client.trace(service_addr, os.path.expanduser(FLAGS.logdir), duration_ms, workers_list, FLAGS.num_tracing_attempts)
            else:
                options = profiler.ProfilerOptions(host_tracer_level=FLAGS.host_tracer_level)
                profiler_client.trace(service_addr, os.path.expanduser(FLAGS.logdir), duration_ms, workers_list, FLAGS.num_tracing_attempts, options)
        except errors.UnavailableError:
            sys.exit(0)

def get_real_obj(self) -> torch.ScriptObject:
    if <MASK>:
