def is_valid_aoti_model_name() -> bool:
    """
    Validates if a model name is suitable for use in code generation.

    """
    from torch._inductor import config
    model_name = config.aot_inductor.model_name_for_generated_files
    if model_name is None:
        return True
    if <MASK>:
        raise ValueError('Invalid AOTI model name: Model name must be a string')
    if model_name == '':
        return True
    if not re.match('^[a-zA-Z_][a-zA-Z0-9_]*$', model_name):
        raise ValueError('Invalid AOTI model name: Model name can only contain letters, numbers, and underscores')
    return True

def _add_test(test, test_name, fn):
    test_name = '_'.join(['test', test_name])
    if <MASK>:
        raise RuntimeError('Test %s defined more than once' % test_name)
    setattr(test, test_name, fn)

def __getitem__(self, idx):
    if idx < 0:
        if <MASK>:
            raise ValueError('absolute value of index should not exceed dataset length')
        idx = len(self) + idx
    dataset_idx = bisect.bisect_right(self.cumulative_sizes, idx)
    if dataset_idx == 0:
        sample_idx = idx
    else:
        sample_idx = idx - self.cumulative_sizes[dataset_idx - 1]
    return self.datasets[dataset_idx][sample_idx]

def _check_perm(self, perm):
    """Static check of perm."""
    if perm.shape.ndims is not None and perm.shape.ndims < 1:
        raise ValueError(f'Argument `perm` must have at least 1 dimension. Received: {perm}.')
    if <MASK>:
        raise TypeError(f'Argument `perm` must be integer dtype. Received: {perm}.')
    static_perm = tensor_util.constant_value(perm)
    if static_perm is not None:
        sorted_perm = np.sort(static_perm, axis=-1)
        if np.any(sorted_perm != np.arange(0, static_perm.shape[-1])):
            raise ValueError(f'Argument `perm` must be a vector of unique integers from 0 to {static_perm.shape[-1] - 1}.')

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument('--version', action='version', version=__version__, help='Print the version and exit.')
    parser.add_argument('--cflags', action='store_true', help='Compile flag needed when using the NumPy headers.')
    parser.add_argument('--pkgconfigdir', action='store_true', help='Print the pkgconfig directory in which `numpy.pc` is stored (useful for setting $PKG_CONFIG_PATH).')
    args = parser.parse_args()
    if not sys.argv[1:]:
        parser.print_help()
    if <MASK>:
        print('-I' + get_include())
    if args.pkgconfigdir:
        _path = Path(get_include()) / '..' / 'lib' / 'pkgconfig'
        print(_path.resolve())

