def _get_missing_features_info(self, X):
    """Compute the imputer mask and the indices of the features
        containing missing values.

        Parameters
        ----------
        X : {ndarray, sparse matrix} of shape (n_samples, n_features)
            The input data with missing values. Note that `X` has been
            checked in :meth:`fit` and :meth:`transform` before to call this
            function.

        Returns
        -------
        imputer_mask : {ndarray, sparse matrix} of shape         (n_samples, n_features)
            The imputer mask of the original data.

        features_with_missing : ndarray of shape (n_features_with_missing)
            The features containing missing values.
        """
    if not self._precomputed:
        imputer_mask = _get_mask(X, self.missing_values)
    else:
        imputer_mask = X
    if sp.issparse(X):
        imputer_mask.eliminate_zeros()
        if self.features == 'missing-only':
            n_missing = imputer_mask.sum(axis=0)
        if <MASK>:
            imputer_mask = imputer_mask.toarray()
        elif imputer_mask.format == 'csr':
            imputer_mask = imputer_mask.tocsc()
    else:
        if not self._precomputed:
            imputer_mask = _get_mask(X, self.missing_values)
        else:
            imputer_mask = X
        if self.features == 'missing-only':
            n_missing = imputer_mask.sum(axis=0)
        if self.sparse is True:
            imputer_mask = sp.csc_matrix(imputer_mask)
    if self.features == 'all':
        features_indices = np.arange(X.shape[1])
    else:
        features_indices = np.flatnonzero(n_missing)
    return (imputer_mask, features_indices)

@staticmethod
def increment(event_name: str, log_level: CompileEventLogLevel, key: str, value: int) -> None:
    """
        Increments an existing field, or adds it
        """
    chromium_log = get_chromium_event_logger()
    if log_level == CompileEventLogLevel.CHROMIUM or log_level == CompileEventLogLevel.PT2_COMPILE:
        chromium_log.increment(event_name, key, value)
    else:
        assert log_level == CompileEventLogLevel.COMPILATION_METRIC
        top_event = chromium_log.get_outermost_event()
        if <MASK>:
            raise RuntimeError("Log level is COMPILATION_METRIC, but event_name isn't the toplevel event. CompilationMetrics must be logged to the toplevel event. Consider using `increment_toplevel` directly.")
        metrics_context = get_metrics_context()
        if not metrics_context.in_progress():
            raise RuntimeError('No metrics context is in progress. Please only call this function within a metrics context/dynamo_timed.')
        metrics_context.increment(key, value)
        chromium_log.increment(event_name, key, value)

def __setattr__(self, attr, val):
    """
        Sets the attribute attr to the value val.

        """
    if attr in ['mask', 'fieldmask']:
        self.__setmask__(val)
        return
    _localdict = object.__getattribute__(self, '__dict__')
    newattr = attr not in _localdict
    try:
        ret = object.__setattr__(self, attr, val)
    except Exception:
        fielddict = np.ndarray.__getattribute__(self, 'dtype').fields or {}
        optinfo = np.ndarray.__getattribute__(self, '_optinfo') or {}
        if not (attr in fielddict or attr in optinfo):
            raise
    else:
        fielddict = np.ndarray.__getattribute__(self, 'dtype').fields or {}
        if attr not in fielddict:
            return ret
        if newattr:
            try:
                object.__delattr__(self, attr)
            except Exception:
                return ret
    try:
        res = fielddict[attr][:2]
    except (TypeError, KeyError) as e:
        raise AttributeError(f'record array has no attribute {attr}') from e
    if val is ma.masked:
        _fill_value = _localdict['_fill_value']
        if <MASK>:
            dval = _localdict['_fill_value'][attr]
        else:
            dval = val
        mval = True
    else:
        dval = ma.filled(val)
        mval = ma.getmaskarray(val)
    obj = np.ndarray.__getattribute__(self, '_data').setfield(dval, *res)
    _localdict['_mask'].__setitem__(attr, mval)
    return obj

def __init__(self, loc: Tensor, cov_factor: Tensor, cov_diag: Tensor, validate_args: Optional[bool]=None) -> None:
    if <MASK>:
        raise ValueError('loc must be at least one-dimensional.')
    event_shape = loc.shape[-1:]
    if cov_factor.dim() < 2:
        raise ValueError('cov_factor must be at least two-dimensional, with optional leading batch dimensions')
    if cov_factor.shape[-2:-1] != event_shape:
        raise ValueError(f'cov_factor must be a batch of matrices with shape {event_shape[0]} x m')
    if cov_diag.shape[-1:] != event_shape:
        raise ValueError(f'cov_diag must be a batch of vectors with shape {event_shape}')
    loc_ = loc.unsqueeze(-1)
    cov_diag_ = cov_diag.unsqueeze(-1)
    try:
        (loc_, self.cov_factor, cov_diag_) = torch.broadcast_tensors(loc_, cov_factor, cov_diag_)
    except RuntimeError as e:
        raise ValueError(f'Incompatible batch shapes: loc {loc.shape}, cov_factor {cov_factor.shape}, cov_diag {cov_diag.shape}') from e
    self.loc = loc_[..., 0]
    self.cov_diag = cov_diag_[..., 0]
    batch_shape = self.loc.shape[:-1]
    self._unbroadcasted_cov_factor = cov_factor
    self._unbroadcasted_cov_diag = cov_diag
    self._capacitance_tril = _batch_capacitance_tril(cov_factor, cov_diag)
    super().__init__(batch_shape, event_shape, validate_args=validate_args)

def _load_graph_execution_traces(self):
    """Incrementally load the .graph_execution_traces file."""
    for (i, traces_iter) in enumerate(self._reader.graph_execution_traces_iterators()):
        for (debug_event, offset) in traces_iter:
            self._graph_execution_trace_digests.append(self._graph_execution_trace_digest_from_debug_event_proto(debug_event, (i, offset)))
            if <MASK>:
                graph_execution_trace = self._graph_execution_trace_from_debug_event_proto(debug_event, (i, offset))
                for monitor in self._monitors:
                    monitor.on_graph_execution_trace(len(self._graph_execution_trace_digests) - 1, graph_execution_trace)

