    strategy = tpu_strategy.TPUStrategy(resolver)
    sparse_features = sparse_ops.sparse_reorder(sparse_tensor.SparseTensor(indices=[[i % 16, i] for i in range(1024)], values=np.arange(1024), dense_shape=[16, 1024]))
    dataset = dataset_ops.DatasetV2.from_tensors(sparse_features)
    dataset = dataset.unbatch().repeat().batch(16 * strategy.num_replicas_in_sync, drop_remainder=True)
    dist = strategy.experimental_distribute_dataset(dataset, options=distribute_lib.InputOptions(experimental_fetch_to_device=False))
    tpu_iter = iter(dist)
    with strategy.scope():
        mid_level_api = tpu_embedding_v3.TPUEmbeddingV2(feature_config=feature_config, optimizer=tpu_embedding_v2_utils.SGD(learning_rate=1.0), pipeline_execution_with_tensor_core=True)
        weight = tf_variables.Variable(initial_value=10)
    if <MASK>:

        @def_function.function
        def tpu_test_fn(tpu_iter):

            def step(data):
                (activations, preserved_results) = mid_level_api.dequeue(data)
                activations = activations * weight
                mid_level_api.apply_gradients(activations, preserved_results)
                return activations

            @def_function.function
            def enqueue(data):
                return mid_level_api.enqueue(data, device=strategy.extended.worker_devices[0])
            inner_result = array_ops.zeros([16, self.embedding_dim], dtype=dtypes.float32)
            for _ in math_ops.range(num_steps):
                host_partition_result = enqueue(next(tpu_iter))
                inner_result = strategy.run(step, args=(host_partition_result,))
            return inner_result
    else:

        @def_function.function
        def tpu_test_fn(tpu_iter):

            def step(data):
                (activations, preserved_results) = mid_level_api(data)
                activations = activations * weight
                mid_level_api.apply_gradients(activations, preserved_results)
                return activations
            inner_result = array_ops.zeros([16, self.embedding_dim], dtype=dtypes.float32)
            for _ in math_ops.range(num_steps):
                inner_result = strategy.run(step, args=(next(tpu_iter),))
            return inner_result

    class MockSummaryWriter(summary_ops_v2.SummaryWriter):

        def init(self):
            pass

        def flush(self):
            pass

        def close(self):
            pass
    if use_predicate_function:
        should_record_summaries = lambda : record_summaries
        should_be_pipelined = True
    else:
        should_record_summaries = record_summaries
        should_be_pipelined = not record_summaries
    sequential_embedding_context = contextlib.nullcontext()
    if use_sequential_embedding_context:
        should_be_pipelined = False
        sequential_embedding_context = ecu.SequentialEmbeddingContext()
    with MockSummaryWriter().as_default():
        with sequential_embedding_context:
            with summary_ops_v2.record_if(should_record_summaries):
                is_pipelined = self.is_function_pipelined(tpu_test_fn, tpu_iter)
                self.assertEqual(is_pipelined, should_be_pipelined)

def __call__(self, X, Y=None, eval_gradient=False):
    """Return the kernel k(X, Y) and optionally its gradient.

        Parameters
        ----------
        X : ndarray of shape (n_samples_X, n_features)
            Left argument of the returned kernel k(X, Y)

        Y : ndarray of shape (n_samples_Y, n_features), default=None
            Right argument of the returned kernel k(X, Y). If None, k(X, X)
            if evaluated instead.

        eval_gradient : bool, default=False
            Determines whether the gradient with respect to the log of
            the kernel hyperparameter is computed.
            Only supported when Y is None.

        Returns
        -------
        K : ndarray of shape (n_samples_X, n_samples_Y)
            Kernel k(X, Y)

        K_gradient : ndarray of shape (n_samples_X, n_samples_X, n_dims),                 optional
            The gradient of the kernel k(X, X) with respect to the log of the
            hyperparameter of the kernel. Only returned when `eval_gradient`
            is True.
        """
    X = np.atleast_2d(X)
    length_scale = _check_length_scale(X, self.length_scale)
    if Y is None:
        dists = pdist(X / length_scale, metric='euclidean')
    else:
        if eval_gradient:
            raise ValueError('Gradient can only be evaluated when Y is None.')
        dists = cdist(X / length_scale, Y / length_scale, metric='euclidean')
    if self.nu == 0.5:
        K = np.exp(-dists)
    elif self.nu == 1.5:
        K = dists * math.sqrt(3)
        K = (1.0 + K) * np.exp(-K)
    elif self.nu == 2.5:
        K = dists * math.sqrt(5)
        K = (1.0 + K + K ** 2 / 3.0) * np.exp(-K)
    elif self.nu == np.inf:
        K = np.exp(-dists ** 2 / 2.0)
    else:
        K = dists
        K[K == 0.0] += np.finfo(float).eps
        tmp = math.sqrt(2 * self.nu) * K
        K.fill(2 ** (1.0 - self.nu) / gamma(self.nu))
        K *= tmp ** self.nu
        K *= kv(self.nu, tmp)
    if Y is None:
        K = squareform(K)
        np.fill_diagonal(K, 1)
    if eval_gradient:
        if self.hyperparameter_length_scale.fixed:
            K_gradient = np.empty((X.shape[0], X.shape[0], 0))
            return (K, K_gradient)
        if self.anisotropic:
            D = (X[:, np.newaxis, :] - X[np.newaxis, :, :]) ** 2 / length_scale ** 2
        else:
            D = squareform(dists ** 2)[:, :, np.newaxis]
        if self.nu == 0.5:
            denominator = np.sqrt(D.sum(axis=2))[:, :, np.newaxis]
            divide_result = np.zeros_like(D)
            np.divide(D, denominator, out=divide_result, where=denominator != 0)
            K_gradient = K[..., np.newaxis] * divide_result
        elif self.nu == 1.5:
            K_gradient = 3 * D * np.exp(-np.sqrt(3 * D.sum(-1)))[..., np.newaxis]
        elif self.nu == 2.5:
            tmp = np.sqrt(5 * D.sum(-1))[..., np.newaxis]
            K_gradient = 5.0 / 3.0 * D * (tmp + 1) * np.exp(-tmp)
        elif self.nu == np.inf:
            K_gradient = D * K[..., np.newaxis]
        else:

            def f(theta):
                return self.clone_with_theta(theta)(X, Y)
            return (K, _approx_fprime(self.theta, f, 1e-10))
        if <MASK>:
            return (K, K_gradient[:, :].sum(-1)[:, :, np.newaxis])
        else:
            return (K, K_gradient)
    else:
        return K

def _map(obj):
    if condition(obj):
        return fn(obj)
    elif <MASK>:
        return None
    elif isinstance(obj, (list, tuple)):
        mapped = (_map(x) for x in obj)
        if hasattr(obj, '_fields'):
            return type(obj)(*mapped)
        return type(obj)(mapped)
    elif isinstance(obj, dict):
        return {x: _map(obj[x]) for x in obj}
    else:
        raise ValueError("Auto nesting doesn't know how to process an input object of type " + torch.typename(obj) + ('. Accepted types: ' + condition_msg + ', or lists/tuples of them' if condition_msg else ''))

