def pprint_thing(thing: object, _nest_lvl: int=0, escape_chars: EscapeChars | None=None, default_escapes: bool=False, quote_strings: bool=False, max_seq_items: int | None=None) -> str:
    """
    This function is the sanctioned way of converting objects
    to a string representation and properly handles nested sequences.

    Parameters
    ----------
    thing : anything to be formatted
    _nest_lvl : internal use only. pprint_thing() is mutually-recursive
        with pprint_sequence, this argument is used to keep track of the
        current nesting level, and limit it.
    escape_chars : list[str] or Mapping[str, str], optional
        Characters to escape. If a Mapping is passed the values are the
        replacements
    default_escapes : bool, default False
        Whether the input escape characters replaces or adds to the defaults
    max_seq_items : int or None, default None
        Pass through to other pretty printers to limit sequence printing

    Returns
    -------
    str
    """

    def as_escaped_string(thing: Any, escape_chars: EscapeChars | None=escape_chars) -> str:
        translate = {'\t': '\\t', '\n': '\\n', '\r': '\\r', "'": "\\'"}
        if isinstance(escape_chars, Mapping):
            if default_escapes:
                translate.update(escape_chars)
            else:
                translate = escape_chars
            escape_chars = list(escape_chars.keys())
        else:
            escape_chars = escape_chars or ()
        result = str(thing)
        for c in escape_chars:
            result = result.replace(c, translate[c])
        return result
    if hasattr(thing, '__next__'):
        return str(thing)
    elif isinstance(thing, Mapping) and _nest_lvl < get_option('display.pprint_nest_depth'):
        result = _pprint_dict(thing, _nest_lvl, quote_strings=True, max_seq_items=max_seq_items)
    elif <MASK>:
        result = _pprint_seq(thing, _nest_lvl, escape_chars=escape_chars, quote_strings=quote_strings, max_seq_items=max_seq_items)
    elif isinstance(thing, str) and quote_strings:
        result = f"'{as_escaped_string(thing)}'"
    else:
        result = as_escaped_string(thing)
    return result

def forward(self, inp, output_type):
    if <MASK>:
        return (self.lin(inp), (self.lin(inp), self.lin(inp)))
    elif output_type == 'list':
        return [self.lin(inp), [self.lin(inp), self.lin(inp)]]
    elif output_type == 'dict':
        return {'a': self.lin(inp), 'b': {'c': self.lin(inp)}}

def remove_replaced_nodes(self, replacement, replaced):
    """
        Remove each of the `replaced` nodes (when they exist). Any
        dependencies that were referencing them are changed to reference the
        `replacement` node instead.
        """
    replaced = set(replaced)
    try:
        replacement_node = self.node_map[replacement]
    except KeyError as err:
        raise NodeNotFoundError('Unable to find replacement node %r. It was either never added to the migration graph, or has been removed.' % (replacement,), replacement) from err
    for replaced_key in replaced:
        self.nodes.pop(replaced_key, None)
        replaced_node = self.node_map.pop(replaced_key, None)
        if replaced_node:
            for child in replaced_node.children:
                child.parents.remove(replaced_node)
                if <MASK>:
                    replacement_node.add_child(child)
                    child.add_parent(replacement_node)
            for parent in replaced_node.parents:
                parent.children.remove(replaced_node)
                if parent.key not in replaced:
                    replacement_node.add_parent(parent)
                    parent.add_child(replacement_node)

def map_array(arr: ArrayLike, mapper, na_action: Literal['ignore'] | None=None) -> np.ndarray | ExtensionArray | Index:
    """
    Map values using an input mapping or function.

    Parameters
    ----------
    mapper : function, dict, or Series
        Mapping correspondence.
    na_action : {None, 'ignore'}, default None
        If 'ignore', propagate NA values, without passing them to the
        mapping correspondence.

    Returns
    -------
    Union[ndarray, Index, ExtensionArray]
        The output of the mapping function applied to the array.
        If the function returns a tuple with more than one element
        a MultiIndex will be returned.
    """
    from pandas import Index
    if <MASK>:
        msg = f"na_action must either be 'ignore' or None, {na_action} was passed"
        raise ValueError(msg)
    if is_dict_like(mapper):
        if isinstance(mapper, dict) and hasattr(mapper, '__missing__'):
            dict_with_default = mapper
            mapper = lambda x: dict_with_default[np.nan if isinstance(x, float) and np.isnan(x) else x]
        else:
            from pandas import Series
            if len(mapper) == 0:
                mapper = Series(mapper, dtype=np.float64)
            elif isinstance(mapper, dict):
                mapper = Series(mapper.values(), index=Index(mapper.keys(), tupleize_cols=False))
            else:
                mapper = Series(mapper)
    if isinstance(mapper, ABCSeries):
        if na_action == 'ignore':
            mapper = mapper[mapper.index.notna()]
        indexer = mapper.index.get_indexer(arr)
        new_values = take_nd(mapper._values, indexer)
        return new_values
    if not len(arr):
        return arr.copy()
    values = arr.astype(object, copy=False)
    if na_action is None:
        return lib.map_infer(values, mapper)
    else:
        return lib.map_infer_mask(values, mapper, mask=isna(values).view(np.uint8))

@compatibility(is_backward_compatible=False)
def extract_attrs_for_lowering(mod: nn.Module) -> dict[str, Any]:
    """If `mod` is in `module_fetch_book`, fetch the mod's attributes that in the `module_fetch_book`
    after checking module's version is compatible with the `module_fetch_book`.
    """
    attrs_for_lowering: dict[str, Any] = {}
    attrs_for_lowering['name'] = torch.typename(mod)
    if <MASK>:
        (version, param_to_fetch, matching_method) = module_fetch_book[type(mod)]
        if version < mod._version:
            raise RuntimeError(f'Fetcher version {version} try to fetch {torch.typename(mod)} version {mod._version}, please upgrade the module_fetch_book, open an issue and @842974287 or report a bug to AIACC team directly.')
        for attr in param_to_fetch:
            attrs_for_lowering[attr] = getattr(mod, matching_method(attr, mod._version))
    else:
        raise RuntimeError(f'{torch.typename(mod)} is not in the module_fetch_book yet, please add it to the module_fetch_book, open an issue and @842974287 or report a bug to AIACC team directly.')
    return attrs_for_lowering

def assert_trace_line_count(self, fn, count, filtering_enabled=True):
    trace_line_count = -1
    if <MASK>:
        traceback_utils.enable_traceback_filtering()
    else:
        traceback_utils.disable_traceback_filtering()
    self.assertEqual(traceback_utils.is_traceback_filtering_enabled(), filtering_enabled)
    try:
        fn()
    except Exception as e:
        trace = '\n'.join(traceback.format_tb(e.__traceback__))
        trace_line_count = len(trace.split('\n'))
    self.assertGreater(trace_line_count, 0)
    if filtering_enabled:
        if sys.version_info >= (3, 13):
            self.assertLessEqual(trace_line_count, count)
        else:
            self.assertLess(trace_line_count, count)
    else:
        self.assertGreater(trace_line_count, count)

def helper(gm: GraphModule):
    custom_metadata = []
    for node in gm.graph.nodes:
        if hasattr(node, 'meta') and node.meta.get('custom', None):
            custom_metadata.append((node.op, node.name, node.meta['custom']))
        if <MASK>:
            custom_metadata.append(helper(getattr(gm, node.target)))
    return custom_metadata

def _cumulative_and_max_seq_len_nnz(qkv: torch.Tensor) -> tuple[torch.Tensor, int, int]:
    if <MASK>:
        raise ValueError('QKV must be nested for flash cumulative_seq_len calculation.')
    if qkv.lengths() is None:
        cumulative_seqlen = qkv.offsets().to(dtype=torch.int32, device=qkv.device)
        max_seqlen = qkv._get_max_seqlen()
        n_elem = qkv.values().shape[0]
    else:
        cumulative_seqlen = qkv.lengths().cumsum(0).to(dtype=torch.int32, device=qkv.device)
        max_seqlen = qkv._get_max_seqlen()
        n_elem = int(cumulative_seqlen[-1].item())
    return (cumulative_seqlen, max_seqlen, n_elem)

def master_job(master, cluster_def):
    """Returns the canonical job name to use to place TPU computations on.

  Args:
    master: A `string` representing the TensorFlow master to use.
    cluster_def: A ClusterDef object describing the TPU cluster.

  Returns:
    A string containing the job name, or None if no job should be specified.

  Raises:
    ValueError: If the user needs to specify a tpu_job_name, because we are
      unable to infer the job name automatically, or if the user-specified job
      names are inappropriate.
  """
    if master in _LOCAL_MASTERS:
        return None
    if not cluster_def or not cluster_def.job:
        return _DEFAULT_JOB_NAME
    job_names = set((job.name for job in cluster_def.job))
    if _DEFAULT_JOB_NAME in job_names:
        raise ValueError('Currently, tpu_worker is not an allowed job name.')
    if len(job_names) == 1:
        return cluster_def.job[0].name
    if <MASK>:
        if _DEFAULT_COORDINATOR_JOB_NAME in job_names:
            job_names.remove(_DEFAULT_COORDINATOR_JOB_NAME)
            return job_names.pop()
    raise ValueError('Could not infer TPU job name.')

def testCaseWithOptionals(self):
    if <MASK>:
        return
    grads = self._makeGradient(use_case=True)
    assert all(('Optional' in str(g.graph.as_graph_def()) for g in grads))

def build_as_function_and_v1_graph(func: Callable[..., Any]) -> Callable[..., None]:
    """Run a test case in v1 graph mode and inside tf.function in eager mode.

  WARNING: This decorator can only be used in test cases that statically checks
  generated graph. Attempting to evaluate graph or function results via.
  session.run() or self.evaluate() will fail.

  WARNING: This decorator can only be used for test cases that inherit from
  absl.testing.parameterized.TestCase.

  Args:
    func: Test case function to be decorated.

  Returns:
    Decorated test case function.
  """
    if tf_inspect.isclass(func):
        raise ValueError('`run_in_graph_mode_and_function` only supports test methods.')

    @parameterized.named_parameters(('_v1_graph', 'v1_graph'), ('_function', 'function'))
    @functools.wraps(func)
    def decorated(self: 'TensorFlowTestCase', run_mode: str, *args, **kwargs) -> None:
        if <MASK>:
            with ops.Graph().as_default():
                func(self, *args, **kwargs)
        elif run_mode == 'function':

            @def_function.function
            def function_in_eager():
                func(self, *args, **kwargs)
            graph_for_eager_test = ops.Graph()
            with graph_for_eager_test.as_default(), context.eager_mode():
                function_in_eager()
            ops.dismantle_graph(graph_for_eager_test)
        else:
            raise ValueError('Unknown run mode %s' % run_mode)
    return decorated

def _get_min_depth(node):
    """Gets the minimum depth at which node can be computed."""
    min_depth = 0
    for (layer, node_id, _, _) in node.iterate_inbound():
        inbound_node = layer._inbound_nodes[node_id]
        if <MASK>:
            min_depth = min(min_depth, node_to_depth[inbound_node])
        elif inbound_node not in network_nodes:
            continue
        else:
            return None
    return min_depth - 1

def __init__(self, geo_input, srid=None):
    """
        The base constructor for GEOS geometry objects. It may take the
        following inputs:

         * strings:
            - WKT
            - HEXEWKB (a PostGIS-specific canonical form)
            - GeoJSON (requires GDAL)
         * memoryview:
            - WKB

        The `srid` keyword specifies the Source Reference Identifier (SRID)
        number for this Geometry. If not provided, it defaults to None.
        """
    input_srid = None
    if isinstance(geo_input, bytes):
        geo_input = force_str(geo_input)
    if isinstance(geo_input, str):
        wkt_m = wkt_regex.match(geo_input)
        if wkt_m:
            if wkt_m['srid']:
                input_srid = int(wkt_m['srid'])
            g = self._from_wkt(force_bytes(wkt_m['wkt']))
        elif hex_regex.match(geo_input):
            g = wkb_r().read(force_bytes(geo_input))
        elif json_regex.match(geo_input):
            ogr = gdal.OGRGeometry.from_json(geo_input)
            g = ogr._geos_ptr()
            input_srid = ogr.srid
        else:
            raise ValueError('String input unrecognized as WKT EWKT, and HEXEWKB.')
    elif isinstance(geo_input, GEOM_PTR):
        g = geo_input
    elif isinstance(geo_input, memoryview):
        g = wkb_r().read(geo_input)
    elif <MASK>:
        g = capi.geom_clone(geo_input.ptr)
    else:
        raise TypeError('Improper geometry input type: %s' % type(geo_input))
    if not g:
        raise GEOSException('Could not initialize GEOS Geometry with given input.')
    input_srid = input_srid or capi.geos_get_srid(g) or None
    if input_srid and srid and (input_srid != srid):
        raise ValueError('Input geometry already has SRID: %d.' % input_srid)
    super().__init__(g, None)
    srid = input_srid or srid
    if srid and isinstance(srid, int):
        self.srid = srid

def _allocate_parameter_mem(self, n_classes, n_features, input_dtype, coef_init=None, intercept_init=None, one_class=0):
    """Allocate mem for parameters; initialize if provided."""
    if n_classes > 2:
        if coef_init is not None:
            coef_init = np.asarray(coef_init, dtype=input_dtype, order='C')
            if coef_init.shape != (n_classes, n_features):
                raise ValueError('Provided ``coef_`` does not match dataset. ')
            self.coef_ = coef_init
        else:
            self.coef_ = np.zeros((n_classes, n_features), dtype=input_dtype, order='C')
        if intercept_init is not None:
            intercept_init = np.asarray(intercept_init, order='C', dtype=input_dtype)
            if intercept_init.shape != (n_classes,):
                raise ValueError('Provided intercept_init does not match dataset.')
            self.intercept_ = intercept_init
        else:
            self.intercept_ = np.zeros(n_classes, dtype=input_dtype, order='C')
    else:
        if coef_init is not None:
            coef_init = np.asarray(coef_init, dtype=input_dtype, order='C')
            coef_init = coef_init.ravel()
            if <MASK>:
                raise ValueError('Provided coef_init does not match dataset.')
            self.coef_ = coef_init
        else:
            self.coef_ = np.zeros(n_features, dtype=input_dtype, order='C')
        if intercept_init is not None:
            intercept_init = np.asarray(intercept_init, dtype=input_dtype)
            if intercept_init.shape != (1,) and intercept_init.shape != ():
                raise ValueError('Provided intercept_init does not match dataset.')
            if one_class:
                self.offset_ = intercept_init.reshape(1)
            else:
                self.intercept_ = intercept_init.reshape(1)
        elif one_class:
            self.offset_ = np.zeros(1, dtype=input_dtype, order='C')
        else:
            self.intercept_ = np.zeros(1, dtype=input_dtype, order='C')
    if self.average > 0:
        self._standard_coef = self.coef_
        self._average_coef = np.zeros(self.coef_.shape, dtype=input_dtype, order='C')
        if one_class:
            self._standard_intercept = 1 - self.offset_
        else:
            self._standard_intercept = self.intercept_
        self._average_intercept = np.zeros(self._standard_intercept.shape, dtype=input_dtype, order='C')

def log_prob(self, value):
    if <MASK>:
        self._validate_sample(value)
    diff = value - self.loc
    M = _batch_lowrank_mahalanobis(self._unbroadcasted_cov_factor, self._unbroadcasted_cov_diag, diff, self._capacitance_tril)
    log_det = _batch_lowrank_logdet(self._unbroadcasted_cov_factor, self._unbroadcasted_cov_diag, self._capacitance_tril)
    return -0.5 * (self._event_shape[0] * math.log(2 * math.pi) + log_det + M)

@cached_property
def lookup_str(self):
    """
        A string that identifies the view (e.g. 'path.to.view_function' or
        'path.to.ClassBasedView').
        """
    callback = self.callback
    if <MASK>:
        callback = callback.func
    if hasattr(callback, 'view_class'):
        callback = callback.view_class
    elif not hasattr(callback, '__name__'):
        return callback.__module__ + '.' + callback.__class__.__name__
    return callback.__module__ + '.' + callback.__qualname__

def _maximum_aten(a: Union[TensorLikeType, NumberType], b: Union[TensorLikeType, NumberType]) -> TensorLikeType:
    if <MASK>:
        b = scalar_tensor(b, dtype=a.dtype, device=a.device)
    elif isinstance(b, TensorLike) and isinstance(a, Number):
        a = scalar_tensor(a, dtype=b.dtype, device=b.device)
    return torch.maximum(a, b)

def _write_col_header(self, indent: int) -> None:
    row: list[Hashable]
    is_truncated_horizontally = self.fmt.is_truncated_horizontally
    if isinstance(self.columns, MultiIndex):
        template = 'colspan="{span:d}" halign="left"'
        sentinel: lib.NoDefault | bool
        if self.fmt.sparsify:
            sentinel = lib.no_default
        else:
            sentinel = False
        levels = self.columns._format_multi(sparsify=sentinel, include_names=False)
        level_lengths = get_level_lengths(levels, sentinel)
        inner_lvl = len(level_lengths) - 1
        for (lnum, (records, values)) in enumerate(zip(level_lengths, levels, strict=True)):
            if is_truncated_horizontally:
                ins_col = self.fmt.tr_col_num
                if self.fmt.sparsify:
                    recs_new = {}
                    for (tag, span) in list(records.items()):
                        if tag >= ins_col:
                            recs_new[tag + 1] = span
                        elif tag + span > ins_col:
                            recs_new[tag] = span + 1
                            if lnum == inner_lvl:
                                values = values[:ins_col] + ('...',) + values[ins_col:]
                            else:
                                values = values[:ins_col] + (values[ins_col - 1],) + values[ins_col:]
                        else:
                            recs_new[tag] = span
                        if tag + span == ins_col:
                            recs_new[ins_col] = 1
                            values = values[:ins_col] + ('...',) + values[ins_col:]
                    records = recs_new
                    inner_lvl = len(level_lengths) - 1
                    if lnum == inner_lvl:
                        records[ins_col] = 1
                else:
                    recs_new = {}
                    for (tag, span) in list(records.items()):
                        if tag >= ins_col:
                            recs_new[tag + 1] = span
                        else:
                            recs_new[tag] = span
                    recs_new[ins_col] = 1
                    records = recs_new
                    values = values[:ins_col] + ['...'] + values[ins_col:]
            row = [''] * (self.row_levels - 1)
            if self.fmt.index or self.show_col_idx_names:
                if <MASK>:
                    name = self.columns.names[lnum]
                    row.append(pprint_thing(name or ''))
                else:
                    row.append('')
            tags = {}
            j = len(row)
            for (i, v) in enumerate(values):
                if i in records:
                    if records[i] > 1:
                        tags[j] = template.format(span=records[i])
                else:
                    continue
                j += 1
                row.append(v)
            self.write_tr(row, indent, self.indent_delta, tags=tags, header=True)
    else:
        row = [''] * (self.row_levels - 1)
        if self.fmt.index or self.show_col_idx_names:
            if self.fmt.show_index_names:
                row.append(self.columns.name or '')
            else:
                row.append('')
        row.extend(self._get_columns_formatted_values())
        align = self.fmt.justify
        if is_truncated_horizontally:
            ins_col = self.row_levels + self.fmt.tr_col_num
            row.insert(ins_col, '...')
        self.write_tr(row, indent, self.indent_delta, header=True, align=align)

def index_str(self, replacements=None, zero_vars=False):
    assert self.expr is not None
    expr = self.expr
    if zero_vars and expr == 0:
        return 'hl.Var()'
    if replacements:
        replacements = {**replacements}
        for sym in expr.free_symbols:
            if <MASK>:
                assert isinstance(sym, sympy.Symbol)
                var = V.kernel.lookup_cse_var(sym.name)
                assert isinstance(var, HalideCSEVariable)
                replacements[sym] = sympy_index_symbol(var.subs_str(replacements))
        expr = sympy_subs(expr, replacements)
    return V.kernel.index_to_str(expr)

def _changeform_view(self, request, object_id, form_url, extra_context):
    to_field = request.POST.get(TO_FIELD_VAR, request.GET.get(TO_FIELD_VAR))
    if to_field and (not self.to_field_allowed(request, to_field)):
        raise DisallowedModelAdminToField('The field %s cannot be referenced.' % to_field)
    if request.method == 'POST' and '_saveasnew' in request.POST:
        object_id = None
    add = object_id is None
    if add:
        if not self.has_add_permission(request):
            raise PermissionDenied
        obj = None
    else:
        obj = self.get_object(request, unquote(object_id), to_field)
        if <MASK>:
            if not self.has_change_permission(request, obj):
                raise PermissionDenied
        elif not self.has_view_or_change_permission(request, obj):
            raise PermissionDenied
        if obj is None:
            return self._get_obj_does_not_exist_redirect(request, self.opts, object_id)
    fieldsets = self.get_fieldsets(request, obj)
    ModelForm = self.get_form(request, obj, change=not add, fields=flatten_fieldsets(fieldsets))
    if request.method == 'POST':
        form = ModelForm(request.POST, request.FILES, instance=obj)
        (formsets, inline_instances) = self._create_formsets(request, form.instance, change=not add)
        form_validated = form.is_valid()
        if form_validated:
            new_object = self.save_form(request, form, change=not add)
        else:
            new_object = form.instance
        if all_valid(formsets) and form_validated:
            self.save_model(request, new_object, form, not add)
            self.save_related(request, form, formsets, not add)
            change_message = self.construct_change_message(request, form, formsets, add)
            if add:
                self.log_addition(request, new_object, change_message)
                return self.response_add(request, new_object)
            else:
                self.log_change(request, new_object, change_message)
                return self.response_change(request, new_object)
        else:
            form_validated = False
    elif add:
        initial = self.get_changeform_initial_data(request)
        form = ModelForm(initial=initial)
        (formsets, inline_instances) = self._create_formsets(request, form.instance, change=False)
    else:
        form = ModelForm(instance=obj)
        (formsets, inline_instances) = self._create_formsets(request, obj, change=True)
    if not add and (not self.has_change_permission(request, obj)):
        readonly_fields = flatten_fieldsets(fieldsets)
    else:
        readonly_fields = self.get_readonly_fields(request, obj)
    admin_form = helpers.AdminForm(form, list(fieldsets), self.get_prepopulated_fields(request, obj) if add or self.has_change_permission(request, obj) else {}, readonly_fields, model_admin=self)
    media = self.media + admin_form.media
    inline_formsets = self.get_inline_formsets(request, formsets, inline_instances, obj)
    for inline_formset in inline_formsets:
        media += inline_formset.media
    if add:
        title = _('Add %s')
    elif self.has_change_permission(request, obj):
        title = _('Change %s')
    else:
        title = _('View %s')
    context = {**self.admin_site.each_context(request), 'title': title % self.opts.verbose_name, 'subtitle': str(obj) if obj else None, 'adminform': admin_form, 'object_id': object_id, 'original': obj, 'is_popup': IS_POPUP_VAR in request.POST or IS_POPUP_VAR in request.GET, 'to_field': to_field, 'media': media, 'inline_admin_formsets': inline_formsets, 'errors': helpers.AdminErrorList(form, formsets), 'preserved_filters': self.get_preserved_filters(request)}
    if request.method == 'POST' and (not form_validated) and ('_saveasnew' in request.POST):
        context['show_save'] = False
        context['show_save_and_continue'] = False
        add = False
    context.update(extra_context or {})
    return self.render_change_form(request, context, add=add, change=not add, obj=obj, form_url=form_url)

def _lower_dynamic_weighted_ref_functional(model: GraphModule, qconfig_map: dict[str, QConfigAny]):
    """
    Traverse the graph and replace functional reference patterns with their dynamically
    quantized versions.
    Examples:
    quantize_per_tensor_dynamic - dequantize - functional linear --> linear_dynamic
    to(torch.float16) - dequantize - functional linear --> linear_dynamic_fp16
    """
    modules = dict(model.named_modules(remove_duplicate=False))
    for n in reversed(model.graph.nodes):
        func_node = n
        if func_node.op == 'call_function' and func_node.target == F.relu or (func_node.op == 'call_module' and type(modules[str(func_node.target)]) is torch.nn.ReLU):
            relu_node = func_node
            func_node = relu_node.args[0]
        else:
            relu_node = None
        if should_skip_lowering(func_node, qconfig_map):
            continue
        if func_node.op != 'call_function' or func_node.target not in DYNAMIC_LOWER_FUNCTIONAL_MAP:
            continue
        (input_dq_node, weight_dq_node, *remaining_func_args) = func_node.args
        if <MASK>:
            continue
        input_dynamic_q_node = input_dq_node.args[0]
        if input_dynamic_q_node.op != 'call_function' or input_dynamic_q_node.target != torch.quantize_per_tensor_dynamic:
            continue
        reduce_range_node = None
        (pattern_input, activation_dtype, reduce_range_node) = input_dynamic_q_node.args
        is_fp16 = activation_dtype == torch.float16
        is_int8 = activation_dtype in [torch.quint8, torch.qint8]
        if not is_int8 and (not is_fp16):
            continue
        quantized_weight = weight_dq_node.args[0]
        weight_dtype = quantized_weight.args[-1]
        dynamic_quant_dtype_key = (activation_dtype, weight_dtype)
        if dynamic_quant_dtype_key not in DYNAMIC_LOWER_FUNCTIONAL_MAP[func_node.target]:
            print(f"Didn't find dtype combination {dynamic_quant_dtype_key} during dynamic quantized op lowering for {func_node.target}")
            continue
        (q_func, q_relu_func) = DYNAMIC_LOWER_FUNCTIONAL_MAP[func_node.target][dynamic_quant_dtype_key]
        if q_func is None or q_relu_func is None:
            print(f"Didn't find corresponding quantized function or quantized relu function for {func_node.target}, {dynamic_quant_dtype_key}")
            continue
        prepack_args = [quantized_weight] + remaining_func_args
        prepack_kwargs = {}
        if func_node.target == F.linear:
            prepack_op = get_linear_prepack_op_for_dtype(weight_dtype)
            kwargs = func_node.kwargs.copy()
            if 'bias' in kwargs:
                prepack_kwargs['B'] = kwargs['bias']
                del kwargs['bias']
                func_node.kwargs = kwargs
        elif func_node.target in CONV_FUNCTIONAL_OPS:
            prepack_op = get_qconv_prepack_op(func_node.target)
            if func_node.target == F.conv1d:
                for i in [2, 3, 4]:
                    if len(prepack_args) > i and isinstance(prepack_args[i], int):
                        prepack_args[i] = (prepack_args[i],)
        else:
            raise ValueError(f"Lowering is not supported for op '{func_node.target}'")
        with model.graph.inserting_before(func_node):
            packed_weight = model.graph.create_node('call_function', prepack_op, tuple(prepack_args), prepack_kwargs)
        func_node.target = q_relu_func if relu_node is not None else q_func
        if is_int8:
            func_node.args = (pattern_input, packed_weight, reduce_range_node)
        else:
            func_node.args = (pattern_input, packed_weight)
        if relu_node is not None:
            relu_node.replace_all_uses_with(func_node)
        if relu_node is not None:
            model.graph.erase_node(relu_node)

def sha_from_force_push_after(ev: dict[str, Any]) -> Optional[str]:
    """Extract SHA from force push event in timeline"""
    commit_id = ev.get('commit_id')
    if <MASK>:
        return str(commit_id)
    after = ev.get('after') or ev.get('after_commit') or {}
    if isinstance(after, dict):
        return after.get('sha') or after.get('oid')
    return ev.get('after_sha') or ev.get('head_sha')

def __getattribute__(self, name):
    if <MASK>:
        return super().__getattribute__(name)
    value = super().__getattribute__(name)
    if not getattr(value, '_mask_wrapped', True):
        raise AttributeError
    return value

def build_digest_header(self, method, url):
    """
        :rtype: str
        """
    realm = self._thread_local.chal['realm']
    nonce = self._thread_local.chal['nonce']
    qop = self._thread_local.chal.get('qop')
    algorithm = self._thread_local.chal.get('algorithm')
    opaque = self._thread_local.chal.get('opaque')
    hash_utf8 = None
    if algorithm is None:
        _algorithm = 'MD5'
    else:
        _algorithm = algorithm.upper()
    if _algorithm == 'MD5' or _algorithm == 'MD5-SESS':

        def md5_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.md5(x).hexdigest()
        hash_utf8 = md5_utf8
    elif _algorithm == 'SHA':

        def sha_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha1(x).hexdigest()
        hash_utf8 = sha_utf8
    elif _algorithm == 'SHA-256':

        def sha256_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha256(x).hexdigest()
        hash_utf8 = sha256_utf8
    elif _algorithm == 'SHA-512':

        def sha512_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha512(x).hexdigest()
        hash_utf8 = sha512_utf8
    KD = lambda s, d: hash_utf8(f'{s}:{d}')
    if hash_utf8 is None:
        return None
    entdig = None
    p_parsed = urlparse(url)
    path = p_parsed.path or '/'
    if p_parsed.query:
        path += f'?{p_parsed.query}'
    A1 = f'{self.username}:{realm}:{self.password}'
    A2 = f'{method}:{path}'
    HA1 = hash_utf8(A1)
    HA2 = hash_utf8(A2)
    if nonce == self._thread_local.last_nonce:
        self._thread_local.nonce_count += 1
    else:
        self._thread_local.nonce_count = 1
    ncvalue = f'{self._thread_local.nonce_count:08x}'
    s = str(self._thread_local.nonce_count).encode('utf-8')
    s += nonce.encode('utf-8')
    s += time.ctime().encode('utf-8')
    s += os.urandom(8)
    cnonce = hashlib.sha1(s).hexdigest()[:16]
    if _algorithm == 'MD5-SESS':
        HA1 = hash_utf8(f'{HA1}:{nonce}:{cnonce}')
    if not qop:
        respdig = KD(HA1, f'{nonce}:{HA2}')
    elif qop == 'auth' or 'auth' in qop.split(','):
        noncebit = f'{nonce}:{ncvalue}:{cnonce}:auth:{HA2}'
        respdig = KD(HA1, noncebit)
    else:
        return None
    self._thread_local.last_nonce = nonce
    base = f'username="{self.username}", realm="{realm}", nonce="{nonce}", uri="{path}", response="{respdig}"'
    if opaque:
        base += f', opaque="{opaque}"'
    if algorithm:
        base += f', algorithm="{algorithm}"'
    if entdig:
        base += f', digest="{entdig}"'
    if <MASK>:
        base += f', qop="auth", nc={ncvalue}, cnonce="{cnonce}"'
    return f'Digest {base}'

def update(instructions: list[Instruction], code_options: dict[str, Any]) -> None:
    meta.instructions = copy.deepcopy(instructions)
    args = ['__nested_resume_fns', '__nested_frame_values']
    args += [f'___stack{i}' for i in range(nstack)]
    args.extend((v for v in argnames if v not in args))
    freevars = tuple(code_options['co_cellvars'] or []) + tuple(code_options['co_freevars'] or [])
    freevars = tuple(sorted(freevars))
    code_options['co_name'] = f"{TORCH_DYNAMO_RESUME_IN_PREFIX}_{code_options['co_name']}_at_{lineno}"
    if is_py311_plus:
        qualified_path = code_options['co_qualname'].rsplit('.', maxsplit=1)
        if len(qualified_path) == 1:
            code_options['co_qualname'] = code_options['co_name']
        else:
            assert len(qualified_path) == 2
            (module_name, co_name) = qualified_path
            code_options['co_qualname'] = f'{module_name}.{TORCH_DYNAMO_RESUME_IN_PREFIX}_{co_name}_at_{lineno}'
    code_options['co_firstlineno'] = lineno
    code_options['co_cellvars'] = ()
    code_options['co_freevars'] = freevars
    code_options['co_argcount'] = len(args)
    code_options['co_posonlyargcount'] = 0
    code_options['co_kwonlyargcount'] = 0
    code_options['co_varnames'] = tuple(args + [v for v in argnames_null if v not in args] + [v for v in code_options['co_varnames'] if v not in args] + [IS_TRACING_RESUME_PROLOGUE_VARNAME])
    code_options['co_flags'] = code_options['co_flags'] & ~(CO_VARARGS | CO_VARKEYWORDS)
    target = next((i for i in instructions if i.offset == offset))
    prefix = []
    if is_py311_plus:
        if freevars:
            prefix.append(create_instruction('COPY_FREE_VARS', arg=len(freevars)))
        prefix.append(create_instruction('RESUME', arg=0))
    prefix.extend([create_instruction('LOAD_CONST', argval=True), create_instruction('STORE_FAST', argval=IS_TRACING_RESUME_PROLOGUE_VARNAME)])
    cleanup: list[Instruction] = []
    hooks = {fn.stack_index: fn for fn in setup_fns}
    hook_target_offsets = {fn.stack_index: setup_fn_target_offsets[i] for (i, fn) in enumerate(setup_fns)}
    offset_to_inst = {inst.offset: inst for inst in instructions}
    old_hook_target_remap = {}
    stack_i = 0
    null_i = 0
    stack_ctx_vars_d = dict(stack_ctx_vars)
    for i in range(nstack + len(null_idxes)):
        if <MASK>:
            prefix.append(create_instruction('PUSH_NULL'))
            null_i += 1
        else:
            prefix.append(create_instruction('LOAD_FAST', argval=f'___stack{stack_i}'))
            if handle_inactive_ctx and stack_i in stack_ctx_vars_d:
                prefix.extend(_load_tuple_and_call(stack_ctx_vars_d[stack_i]))
            stack_i += 1
        if i in hooks:
            hook = hooks.pop(i)
            (hook_insts, exn_target) = hook(code_options, cleanup)
            prefix.extend(hook_insts)
            if is_py311_plus:
                hook_target_offset = hook_target_offsets.pop(i)
                old_hook_target = offset_to_inst[hook_target_offset]
                meta.prefix_block_target_offset_remap.append(hook_target_offset)
                old_hook_target_remap[old_hook_target] = exn_target
    if is_py311_plus:
        meta.prefix_block_target_offset_remap = list(reversed(meta.prefix_block_target_offset_remap))
    assert not hooks
    if handle_inactive_ctx:
        for (name, vals) in argnames_ctx_vars:
            prefix.append(create_instruction('LOAD_FAST', argval=name))
            prefix.extend(_load_tuple_and_call(vals))
            prefix.append(create_instruction('STORE_FAST', argval=name))
    if argnames_null:
        assert sys.version_info >= (3, 12)
        for v in argnames_null:
            assert v not in args
            prefix.extend([create_instruction('PUSH_NULL'), create_instruction('STORE_FAST', argval=v)])
    if nested_code_objs:
        prefix.extend([*add_push_null([create_instruction('LOAD_FAST', argval='__nested_resume_fns'), create_instruction('LOAD_CONST', argval=-1), create_binary_subscr()]), create_instruction('LOAD_FAST', argval='__nested_resume_fns'), create_instruction('LOAD_CONST', argval=-1), create_instruction('DELETE_SUBSCR'), create_instruction('LOAD_FAST', argval='__nested_resume_fns'), create_instruction('LOAD_FAST', argval='__nested_frame_values'), create_instruction('BUILD_LIST', arg=2), create_instruction('LOAD_FAST', argval='__nested_frame_values'), create_instruction('LOAD_CONST', argval=-1), create_binary_subscr(), create_instruction('LIST_EXTEND', arg=1), create_instruction('LOAD_FAST', argval='__nested_frame_values'), create_instruction('LOAD_CONST', argval=-1), create_instruction('DELETE_SUBSCR'), create_instruction('DELETE_FAST', argval='__nested_resume_fns'), create_instruction('DELETE_FAST', argval='__nested_frame_values'), create_instruction('LOAD_CONST', argval=False), create_instruction('STORE_FAST', argval=IS_TRACING_RESUME_PROLOGUE_VARNAME), *create_call_function_ex(False, False)])
    else:
        prefix.extend([create_instruction('LOAD_CONST', argval=False), create_instruction('STORE_FAST', argval=IS_TRACING_RESUME_PROLOGUE_VARNAME)])
    prefix.append(create_jump_absolute(target))
    for inst in instructions:
        if inst.offset == target.offset:
            break
        inst.starts_line = None
        if sys.version_info >= (3, 11):
            inst.positions = None
    if cleanup:
        prefix.extend(cleanup)
        prefix.extend(cls.unreachable_codes(code_options))
    if old_hook_target_remap:
        assert is_py311_plus
        for inst in instructions:
            if inst.exn_tab_entry and inst.exn_tab_entry.target in old_hook_target_remap:
                inst.exn_tab_entry.target = old_hook_target_remap[inst.exn_tab_entry.target]
    instructions[:] = prefix + instructions

def get_and_pop(key, default):
    v = kwargs.get(key, default)
    if <MASK>:
        kwargs.pop(key)
    return v

@wraps(fn)
def disable_mkldnn(self, *args, **kwargs):
    if <MASK>:
        with torch.backends.mkldnn.flags(enabled=False):
            return fn(self, *args, **kwargs)
    return fn(self, *args, **kwargs)

def _shard_tensor(self, tensor: torch.Tensor, mesh: DeviceMesh, mesh_dim: int, src_data_rank: Optional[int]=0) -> torch.Tensor:
    """
        shard and scatter a tensor on a mesh dimension (use coordinate
        0 on the mesh dimension as source of truth)
        """
    my_coordinate = mesh.get_coordinate()
    num_chunks = mesh.size(mesh_dim=mesh_dim)
    if my_coordinate is None:
        return tensor.new_empty(0, requires_grad=tensor.requires_grad)
    mesh_dim_local_rank = my_coordinate[mesh_dim]
    if <MASK>:
        (scatter_list, _) = self._split_tensor(tensor, num_chunks, with_padding=False, contiguous=True)
        return self._select_shard(scatter_list, mesh_dim_local_rank)
    (scatter_list, pad_sizes) = self._split_tensor(tensor, num_chunks, with_padding=True, contiguous=True)
    it = iter(scatter_list)
    first = next(it)
    assert all((first.shape == v.shape for v in it))
    output = torch.empty_like(first)
    mesh_scatter(output, scatter_list, mesh, mesh_dim=mesh_dim, group_src=src_data_rank)
    return Shard._maybe_unpad_tensor_with_sizes(self.dim, output, pad_sizes, mesh_dim_local_rank, True)

def _set_oob_score(self, X, y):
    n_samples = y.shape[0]
    n_classes_ = self.n_classes_
    predictions = np.zeros((n_samples, n_classes_))
    for (estimator, samples, features) in zip(self.estimators_, self.estimators_samples_, self.estimators_features_):
        mask = ~indices_to_mask(samples, n_samples)
        if hasattr(estimator, 'predict_proba'):
            predictions[mask, :] += estimator.predict_proba(X[mask, :][:, features])
        else:
            p = estimator.predict(X[mask, :][:, features])
            j = 0
            for i in range(n_samples):
                if <MASK>:
                    predictions[i, p[j]] += 1
                    j += 1
    if (predictions.sum(axis=1) == 0).any():
        warn('Some inputs do not have OOB scores. This probably means too few estimators were used to compute any reliable oob estimates.')
    oob_decision_function = predictions / predictions.sum(axis=1)[:, np.newaxis]
    oob_score = accuracy_score(y, np.argmax(predictions, axis=1))
    self.oob_decision_function_ = oob_decision_function
    self.oob_score_ = oob_score

def deserialize_input(self, inp: Argument) -> Any:
    value = inp.value
    typ_ = inp.type
    if typ_ == 'as_none':
        return None
    elif typ_ == 'as_tensor':
        return self.serialized_name_to_node[inp.as_tensor.name]
    elif typ_ == 'as_scalar_type':
        return _SERIALIZE_TO_TORCH_DTYPE[inp.as_scalar_type]
    elif typ_ == 'as_memory_format':
        return _SERIALIZE_TO_TORCH_MEMORY_FORMAT[inp.as_memory_format]
    elif typ_ == 'as_layout':
        return _SERIALIZE_TO_TORCH_LAYOUT[inp.as_layout]
    elif typ_ == 'as_graph':
        assert isinstance(value, GraphArgument)
        with self.save_graph_module():
            self.deserialize_graph(value.graph)
            submodule = ep._create_graph_module_for_export(self.module, self.graph)
        self.module.register_module(value.name, submodule)
        return self.graph.create_node('get_attr', value.name, name=value.name)
    elif typ_ == 'as_device':
        return deserialize_device(inp.as_device)
    elif typ_ == 'as_int':
        return inp.as_int
    elif typ_ == 'as_float':
        return inp.as_float
    elif typ_ == 'as_bool':
        return inp.as_bool
    elif typ_ == 'as_string':
        return inp.as_string
    elif typ_ == 'as_complex':
        return complex(inp.as_complex.real, inp.as_complex.imag)
    elif typ_ == 'as_sym_int':
        return self.deserialize_sym_argument(inp.as_sym_int)
    elif typ_ == 'as_sym_float':
        return self.deserialize_sym_argument(inp.as_sym_float)
    elif typ_ == 'as_sym_bool':
        return self.deserialize_sym_argument(inp.as_sym_bool)
    elif <MASK>:
        if len(value) == 0:
            return []
        elif typ_ == 'as_tensors':
            result = [self.serialized_name_to_node[arg.name] for arg in value]
            return result
        elif typ_ in ('as_ints', 'as_floats', 'as_bools', 'as_strings'):
            return list(value)
        elif typ_ in ('as_sym_ints', 'as_sym_bools', 'as_sym_floats'):
            return [self.deserialize_sym_argument(arg) for arg in value]
        elif typ_ == 'as_optional_tensors':

            def deserialize_optional_tensor_args(a):
                if a.type == 'as_none':
                    return None
                elif a.type == 'as_tensor':
                    return self.serialized_name_to_node[a.value.name]
                else:
                    raise SerializeError(f'Unhandled argument {inp}')
            return list(map(deserialize_optional_tensor_args, value))
        else:
            raise SerializeError(f'Unhandled argument {inp}')
    elif typ_ == 'as_custom_obj':
        if inp.as_custom_obj.name in self.serialized_name_to_node:
            return self.serialized_name_to_node[inp.as_custom_obj.name]
        return self.constants[inp.as_custom_obj.name]
    elif typ_ == 'as_operator':
        return self.deserialize_operator(inp.as_operator)
    else:
        raise SerializeError(f'Unhandled argument {inp}')

def handle_partial_sample_weights(outputs, sample_weights, sample_weight_modes, check_all_flat=False):
    """Adds 1.0 as sample weights for the outputs for which there is no weight.

  Args:
    outputs: List of model outputs.
    sample_weights: List of sample weight inputs.
    sample_weight_modes: List of sample weight modes or None.
    check_all_flat: Ensure that inputs are not nested structures. This is not
      a free check, so we may not want to run it eagerly every iteration.

  Returns:
    Tuple of sample weights, one sample weight for every output, and booleans
    describing the raw sample weights.
  """
    any_sample_weight = sample_weights is not None and any((w is not None for w in sample_weights))
    partial_sample_weight = any_sample_weight and any((w is None for w in sample_weights))
    if not any_sample_weight:
        return (None, any_sample_weight, partial_sample_weight)
    if not partial_sample_weight:
        return (sample_weights, any_sample_weight, partial_sample_weight)
    if check_all_flat:
        nest.assert_same_structure(list_to_tuple(sample_weights), list_to_tuple(nest.flatten(sample_weights)))
        nest.assert_same_structure(list_to_tuple(outputs), list_to_tuple(nest.flatten(outputs)))
        if <MASK>:
            nest.assert_same_structure(sample_weight_modes, nest.flatten(sample_weight_modes))
    new_sample_weights = []
    for (i, sw) in enumerate(sample_weights):
        if sw is None:
            as_numpy = isinstance(outputs[i], np.ndarray)
            output = outputs[i]
            output_shape = output.shape if as_numpy else array_ops.shape(output)
            is_temporal = sample_weight_modes is not None and sample_weight_modes[i] == 'temporal'
            sw_shape = (output_shape[0], output_shape[1]) if is_temporal else (output_shape[0],)
            new_sample_weights.append(np.ones(sw_shape) if as_numpy else array_ops.ones(sw_shape))
        else:
            new_sample_weights.append(sw)
    return (list_to_tuple(new_sample_weights), any_sample_weight, partial_sample_weight)

def _simulate_comms_compute(pipeline_order, stage_to_rank: Callable[[int], int], num_stages: int):
    """This function dry-run simulates the actions in the schedule from the perspective of all ranks, and flags
    any deadlocks caused by missing or misordered communications.  It also simulates any bubbles in time where a rank
    can not execute any action due to waiting for unmet dependencies.  The total number of simulator steps can be used
    as a metric for unit tests involving IR optimization passes as reordering and merging of IR can reduce the number
    of simulated steps.

    The simulation is not high-fidelity and does not model overlapping of compute and communication, or cuda streams.
    Future work may be to enhance this and model the compute time, comms overlap, and even memory.
    """
    pipeline_order = {rank: [a for a in pipeline_order[rank] if a is not None] for rank in sorted(pipeline_order)}
    _schedule: dict[int, list[_Action | None]] = {rank: [] for rank in sorted(pipeline_order)}
    _prev_ops_rank: dict[int, set[_Action]] = {rank: set() for rank in _schedule}

    def add_to_schedule(rank: int, action: Optional[_Action]):
        _schedule[rank].append(action)
        if action is not None:
            _prev_ops_rank[rank].add(action)

    def _ready_to_schedule(action: Optional[_Action]) -> bool:
        if action is None:
            return True
        stage_idx = action.stage_index
        prev_ops = _prev_ops_rank[stage_to_rank(stage_idx)]
        if action.computation_type == F:
            if action.stage_index == 0:
                return True
            elif _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_ops:
                return True
            elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_ops:
                return True
            return False
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
            if action.stage_index == num_stages - 1:
                return True
            if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_ops:
                return True
            if _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_ops:
                return True
            if _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_ops:
                return True
            return False
        elif action.computation_type == BACKWARD_WEIGHT:
            return True
        elif action.computation_type == SEND_F:
            expected_f = _Action(action.stage_index, F, action.microbatch_index)
            return expected_f in prev_ops
        elif action.computation_type == RECV_F:
            peer_stage_idx = stage_idx - 1
            expected_send = _Action(peer_stage_idx, SEND_F, action.microbatch_index)
            return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
        elif action.computation_type == SEND_B:
            expected_b = _Action(action.stage_index, BACKWARD_INPUT, action.microbatch_index)
            expected_bw = _Action(action.stage_index, FULL_BACKWARD, action.microbatch_index)
            return expected_b in prev_ops or expected_bw in prev_ops
        elif action.computation_type == RECV_B:
            peer_stage_idx = stage_idx + 1
            expected_send = _Action(peer_stage_idx, SEND_B, action.microbatch_index)
            return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
        else:
            raise ValueError(f'Unsupported action type {action}')
    while pipeline_order:
        progress = False
        for rank in sorted(pipeline_order):
            if len(pipeline_order[rank]) == 0:
                continue
            action = pipeline_order[rank][0]
            if <MASK>:
                if action is not None:
                    add_to_schedule(rank, action)
                pipeline_order[rank].pop(0)
                progress = True
            else:
                add_to_schedule(rank, None)
        for i in sorted(pipeline_order, reverse=True):
            if len(pipeline_order[i]) == 0:
                del pipeline_order[i]
        for rank in sorted(pipeline_order):
            if len(pipeline_order[rank]) == 0:
                continue
            if _schedule[rank][-1] is not None:
                continue
            action = pipeline_order[rank][0]
            if _ready_to_schedule(action):
                if action is not None:
                    _schedule[rank][-1] = action
                    _prev_ops_rank[rank].add(action)
                pipeline_order[rank].pop(0)
        for i in sorted(pipeline_order, reverse=True):
            if len(pipeline_order[i]) == 0:
                del pipeline_order[i]
        if not progress:
            print('WIP comms schedule:\n', _format_pipeline_order(_schedule))
            for rank in pipeline_order:
                print(f'rank={rank!r} next action= {pipeline_order[rank][0]}')
            raise ValueError('Schedule is not progressing')
    return _schedule

def fit(self, X, y, sample_weight=None):
    (xp, is_array_api_compliant) = get_namespace(X, y, sample_weight)
    if self.solver == 'lbfgs' and (not self.positive):
        raise ValueError("'lbfgs' solver can be used only when positive=True. Please use another solver.")
    if self.positive:
        if self.solver not in ['auto', 'lbfgs']:
            raise ValueError(f"solver='{self.solver}' does not support positive fitting. Please set the solver to 'auto' or 'lbfgs', or set `positive=False`")
        else:
            solver = self.solver
    elif <MASK>:
        if self.solver not in ['auto', 'lbfgs', 'lsqr', 'sag', 'sparse_cg']:
            raise ValueError("solver='{}' does not support fitting the intercept on sparse data. Please set the solver to 'auto' or 'lsqr', 'sparse_cg', 'sag', 'lbfgs' or set `fit_intercept=False`".format(self.solver))
        if self.solver in ['lsqr', 'lbfgs']:
            solver = self.solver
        elif self.solver == 'sag' and self.max_iter is None and (self.tol > 0.0001):
            warnings.warn('"sag" solver requires many iterations to fit an intercept with sparse inputs. Either set the solver to "auto" or "sparse_cg", or set a low "tol" and a high "max_iter" (especially if inputs are not standardized).')
            solver = 'sag'
        else:
            solver = 'sparse_cg'
    else:
        solver = self.solver
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    (X, y, X_offset, y_offset, X_scale, _) = _preprocess_data(X, y, fit_intercept=self.fit_intercept, copy=self.copy_X, sample_weight=sample_weight, rescale_with_sw=False)
    if solver == 'sag' and sparse.issparse(X) and self.fit_intercept:
        (self.coef_, self.n_iter_, self.intercept_, self.solver_) = _ridge_regression(X, y, alpha=self.alpha, sample_weight=sample_weight, max_iter=self.max_iter, tol=self.tol, solver='sag', positive=self.positive, random_state=self.random_state, return_n_iter=True, return_intercept=True, return_solver=True, check_input=False)
        self.intercept_ += y_offset
    else:
        if sparse.issparse(X) and self.fit_intercept:
            params = {'X_offset': X_offset, 'X_scale': X_scale}
        else:
            params = {}
        (self.coef_, self.n_iter_, self.solver_) = _ridge_regression(X, y, alpha=self.alpha, sample_weight=sample_weight, max_iter=self.max_iter, tol=self.tol, solver=solver, positive=self.positive, random_state=self.random_state, return_n_iter=True, return_intercept=False, return_solver=True, check_input=False, fit_intercept=self.fit_intercept, **params)
        self._set_intercept(X_offset, y_offset, X_scale)
    return self

@functools.wraps(fn)
def wrapper(self, other=None):
    if other is None:
        result = fn(self)
    else:
        result = fn(self, other)
    if torch._logging._internal.GET_DTRACE_STRUCTURED:
        if other is not None:
            arguments = [self, other]
        else:
            arguments = [self]

        def get_id(sym_node) -> Optional[int]:
            import sympy
            if <MASK>:
                return None
            elif id(sym_node) == id(result):
                return None
            elif isinstance(sym_node.expr, (sympy.Integer, sympy.Float)):
                return None
            elif sym_node.expr in (sympy.true, sympy.false):
                return None
            return id(sym_node)
        dtrace_structured('expression_created', metadata_fn=lambda : {'method': method, 'result': str(result), 'result_id': id(result), 'arguments': [str(a) for a in arguments], 'argument_ids': [get_id(i) for i in arguments if get_id(i) is not None], 'user_stack': structured.get_user_stack(3), 'stack': structured.get_framework_stack(3)})
    return result

def _convert_container(container, constructor_name, columns_name=None, dtype=None, minversion=None, categorical_feature_names=None):
    """Convert a given container to a specific array-like with a dtype.

    Parameters
    ----------
    container : array-like
        The container to convert.
    constructor_name : {"list", "tuple", "array", "sparse", "dataframe",             "pandas", "series", "index", "slice", "sparse_csr", "sparse_csc",             "sparse_csr_array", "sparse_csc_array", "pyarrow", "polars",             "polars_series"}
        The type of the returned container.
    columns_name : index or array-like, default=None
        For pandas/polars container supporting `columns_names`, it will affect
        specific names.
    dtype : dtype, default=None
        Force the dtype of the container. Does not apply to `"slice"`
        container.
    minversion : str, default=None
        Minimum version for package to install.
    categorical_feature_names : list of str, default=None
        List of column names to cast to categorical dtype.

    Returns
    -------
    converted_container
    """
    if constructor_name == 'list':
        if dtype is None:
            return list(container)
        else:
            return np.asarray(container, dtype=dtype).tolist()
    elif constructor_name == 'tuple':
        if dtype is None:
            return tuple(container)
        else:
            return tuple(np.asarray(container, dtype=dtype).tolist())
    elif constructor_name == 'array':
        return np.asarray(container, dtype=dtype)
    elif constructor_name in ('pandas', 'dataframe'):
        pd = pytest.importorskip('pandas', minversion=minversion)
        result = pd.DataFrame(container, columns=columns_name, dtype=dtype, copy=False)
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result[col_name] = result[col_name].astype('category')
        return result
    elif constructor_name == 'pyarrow':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        array = np.asarray(container)
        array = array[:, None] if array.ndim == 1 else array
        if columns_name is None:
            columns_name = [f'col{i}' for i in range(array.shape[1])]
        data = {name: array[:, i] for (i, name) in enumerate(columns_name)}
        result = pa.Table.from_pydict(data)
        if categorical_feature_names is not None:
            for (col_idx, col_name) in enumerate(result.column_names):
                if col_name in categorical_feature_names:
                    result = result.set_column(col_idx, col_name, result.column(col_name).dictionary_encode())
        return result
    elif constructor_name == 'polars':
        pl = pytest.importorskip('polars', minversion=minversion)
        result = pl.DataFrame(container, schema=columns_name, orient='row')
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result = result.with_columns(pl.col(col_name).cast(pl.Categorical))
        return result
    elif constructor_name == 'series':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Series(container, dtype=dtype)
    elif constructor_name == 'pyarrow_array':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        return pa.array(container)
    elif constructor_name == 'polars_series':
        pl = pytest.importorskip('polars', minversion=minversion)
        return pl.Series(values=container)
    elif constructor_name == 'index':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Index(container, dtype=dtype)
    elif constructor_name == 'slice':
        return slice(container[0], container[1])
    elif 'sparse' in constructor_name:
        if not sp.sparse.issparse(container):
            container = np.atleast_2d(container)
        if <MASK>:
            return sp.sparse.csr_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csr_array':
            return sp.sparse.csr_array(container, dtype=dtype)
        elif constructor_name == 'sparse_csc':
            return sp.sparse.csc_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csc_array':
            return sp.sparse.csc_array(container, dtype=dtype)

def set_missing_meta_vals(gm, flat_args, num_params_buffers):
    index = 0
    for node in gm.graph.nodes:
        if <MASK>:
            if index >= num_params_buffers:
                user_arg = flat_args[index - num_params_buffers]
                if not isinstance(user_arg, torch.Tensor):
                    node.meta['val'] = user_arg
            index += 1

def observe_garbage(observer):
    enabled = True

    def disable():
        nonlocal enabled
        enabled = False
    atexit.register(disable)

    def gc_callback(phase, info):
        nonlocal enabled
        if not enabled:
            return
        if phase == 'start':
            gc.set_debug(gc.DEBUG_SAVEALL)
        elif phase == 'stop':
            orig_trace = sys.getprofile()
            self_return = [False]

            def do_collect(*args, **kwargs):
                nonlocal enabled
                if not self_return[0]:
                    self_return[0] = True
                else:
                    sys.setprofile(orig_trace)
                    enabled = False
                    try:
                        if info['generation'] != 2:
                            gc.collect()
                        observer(gc.garbage)
                        gc.garbage.clear()
                        gc.set_debug(0)
                        before = torch.cuda.memory_allocated()
                        gc.collect()
                        after = torch.cuda.memory_allocated()
                        if <MASK>:
                            logger.warning('CUDA Memory changed during GC, %d bytes freed.', before - after)
                    finally:
                        enabled = True
                if orig_trace is not None:
                    return orig_trace(*args, **kwargs)
            sys.setprofile(do_collect)
    gc.callbacks.append(gc_callback)

    def remove():
        gc.callbacks.remove(gc_callback)
    return remove

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif name == 'extend' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
        if isinstance(idx, SymNodeVariable):
            const_idx = idx.evaluate_expr()
        else:
            const_idx = idx.as_python_constant()
        tx.output.side_effects.mutation(self)
        self.items.insert(const_idx, value)
        return ConstantVariable.create(None)
    elif name == 'pop' and self.is_mutable():
        if kwargs or len(args) > 1:
            raise_args_mismatch(tx, name, 'at most 1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if len(self.items) == 0:
            msg = ConstantVariable.create('pop from empty list')
            raise_observed_exception(IndexError, tx, args=[msg])
        if len(args):
            idx = args[0].as_python_constant()
            if idx > len(self.items):
                msg = ConstantVariable.create('pop index out of range')
                raise_observed_exception(IndexError, tx, args=[msg])
        tx.output.side_effects.mutation(self)
        return self.items.pop(*[a.as_python_constant() for a in args])
    elif name == 'clear' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        self.items.clear()
        return ConstantVariable.create(None)
    elif name == '__setitem__' and self.is_mutable() and args and (args[0].is_python_constant() or isinstance(args[0], SymNodeVariable) or (isinstance(args[0], SliceVariable) and all((s.is_python_constant() or isinstance(s, SymNodeVariable) for s in args[0].items)))):
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        (key, value) = args
        tx.output.side_effects.mutation(self)
        if isinstance(key, SymNodeVariable):
            self.items[key.evaluate_expr()] = value
        elif isinstance(key, SliceVariable):
            if key.is_python_constant():
                self.items[key.as_python_constant()] = list(value.items)
            else:
                items = slice(*[s.evaluate_expr() if isinstance(s, SymNodeVariable) else s.as_python_constant() for s in key.items])
                self.items[items] = list(value.items)
        else:
            self.items[key.as_python_constant()] = value
        return ConstantVariable.create(None)
    elif name == '__delitem__' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        if args[0].is_python_constant() and isinstance(args[0].as_python_constant(), (int, slice)):
            if isinstance(args[0], SymNodeVariable):
                idx = args[0].evaluate_expr()
            else:
                idx = args[0].as_python_constant()
            try:
                self.items.__delitem__(idx)
            except (IndexError, ValueError) as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            msg = ConstantVariable.create(f'list indices must be integers or slices, not {args[0].python_type_name()}')
            raise_observed_exception(TypeError, tx, args=[msg])
        return ConstantVariable.create(None)
    elif name == 'copy':
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        items = list(self.items)
        return self.modified(items, mutation_type=ValueMutationNew())
    elif <MASK>:
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        self.items.reverse()
        tx.output.side_effects.mutation(self)
        return ConstantVariable.create(None)
    elif name == 'remove' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        idx = self.call_method(tx, 'index', args, kwargs)
        self.call_method(tx, 'pop', [idx], {})
        return ConstantVariable.create(None)
    else:
        return super().call_method(tx, name, args, kwargs)

def res_arg(self, ns, types_ns, f_name, name, type_anno, f_is_local):
    if f_name == 'test_fn':
        test_self.assertFalse(f_is_local)
        test_self.assertEqual(name, qual_names.QN('a'))
        test_self.assertEqual(type_anno, qual_names.QN('int'))
    elif f_name == 'foo':
        test_self.assertTrue(f_is_local)
        if name == qual_names.QN('x'):
            test_self.assertEqual(type_anno, qual_names.QN('float'))
        elif <MASK>:
            test_self.assertIsNone(type_anno)
        else:
            test_self.fail('unexpected argument {} for {}'.format(name, f_name))
    else:
        test_self.fail('unexpected function name {}'.format(f_name))
    return {str(name) + '_type'}

def error(level, msg, *args, **kwargs):
    if <MASK>:
        logging.error(msg, *args, **kwargs)
        if echo_log_to_stdout:
            _output_to_stdout('ERROR: ' + msg, *args, **kwargs)

def __getitems__(self, indices: list):
    if isinstance(self.datasets, dict):
        dict_batch: list[_T_dict] = [{} for _ in indices]
        for (k, dataset) in self.datasets.items():
            if <MASK>:
                items = dataset.__getitems__(indices)
                if len(items) != len(indices):
                    raise ValueError(f"Nested dataset's output size mismatch. Expected {len(indices)}, got {len(items)}")
                for (data, d_sample) in zip(items, dict_batch):
                    d_sample[k] = data
            else:
                for (idx, d_sample) in zip(indices, dict_batch):
                    d_sample[k] = dataset[idx]
        return dict_batch
    list_batch: list[list] = [[] for _ in indices]
    for dataset in self.datasets:
        if callable(getattr(dataset, '__getitems__', None)):
            items = dataset.__getitems__(indices)
            if len(items) != len(indices):
                raise ValueError(f"Nested dataset's output size mismatch. Expected {len(indices)}, got {len(items)}")
            for (data, t_sample) in zip(items, list_batch):
                t_sample.append(data)
        else:
            for (idx, t_sample) in zip(indices, list_batch):
                t_sample.append(dataset[idx])
    tuple_batch: list[_T_tuple] = [tuple(sample) for sample in list_batch]
    return tuple_batch

def deserialize_inputs(self, target, serialized_node: Node):
    schema_args = _get_schema_from_target(target).arguments
    argument_kinds = {input.name: input.kind for input in serialized_node.inputs}
    actual_args = {input.name: self.deserialize_input(input.arg) for input in serialized_node.inputs}
    args = []
    kwargs: OrderedDict[str, Any] = OrderedDict()
    for schema_arg in schema_args:
        if schema_arg.name in actual_args:
            arg = actual_args[schema_arg.name]
            kind = argument_kinds[schema_arg.name]
            if kind == ArgumentKind.POSITIONAL:
                args.append(arg)
                continue
            elif kind == ArgumentKind.KEYWORD and (not keyword.iskeyword(schema_arg.name)):
                kwargs[schema_arg.name] = arg
                continue
        is_positional = not schema_arg.has_default_value() and (not schema_arg.kwarg_only)
        if <MASK>:
            args.append(actual_args[schema_arg.name])
        elif keyword.iskeyword(schema_arg.name):
            assert not schema_arg.kwarg_only
            if len(kwargs) > 0:
                kwargs = OrderedDict()
                args.extend(list(kwargs.values()))
            args.append(actual_args[schema_arg.name])
        elif schema_arg.name in actual_args:
            kwargs[schema_arg.name] = actual_args[schema_arg.name]
    return (tuple(args), kwargs)

def hingeembeddingloss_reference(input, target, margin=1.0, reduction='mean'):
    margin_clamp = (margin - input).clamp(min=0).type_as(input)
    output = torch.where(target == 1, input, margin_clamp)
    if reduction == 'mean':
        return output.mean()
    elif <MASK>:
        return output.sum()
    return output

def _maybe_insert_input_and_output_observers_for_node(node: Node, model: torch.fx.GraphModule, obs_or_fq_map: dict[EdgeOrNode, ObserverOrFakeQuantize], is_qat: bool, model_device: Optional[torch.device]=None):
    this_node_quantization_annotation = node.meta.get('quantization_annotation', None)
    if this_node_quantization_annotation is None:
        return
    named_modules = dict(model.named_modules(remove_duplicate=False))
    _maybe_insert_input_observers_for_node(node, None, model, named_modules, obs_or_fq_map, is_qat, model_device)
    output_is_a_tensor = 'val' in node.meta and isinstance(node.meta['val'], FakeTensor)
    if not output_is_a_tensor:
        return
    maybe_output_obs_node = _maybe_insert_output_observer_for_node(node, model, named_modules, model.graph, obs_or_fq_map, is_qat, model_device)
    if <MASK>:
        return
    orig_users = list(node.users.keys())
    for user_node in orig_users:
        if user_node is maybe_output_obs_node:
            continue
        user_node.replace_input_with(node, maybe_output_obs_node)

def assertDatasetsRaiseSameError(self, dataset1, dataset2, exception_class, replacements=None):
    """Checks that datasets raise the same error on the first get_next call."""
    if <MASK>:
        replacements = []
    next1 = self.getNext(dataset1)
    next2 = self.getNext(dataset2)
    try:
        self.evaluate(next1())
        raise ValueError('Expected dataset to raise an error of type %s, but it did not.' % repr(exception_class))
    except exception_class as e:
        expected_message = e.message
        for (old, new, count) in replacements:
            expected_message = expected_message.replace(old, new, count)
        with self.assertRaisesRegex(exception_class, re.escape(expected_message)):
            self.evaluate(next2())

@final
def _clip_with_one_bound(self, threshold, method, axis, inplace):
    if axis is not None:
        axis = self._get_axis_number(axis)
    if is_scalar(threshold) and is_number(threshold):
        if method.__name__ == 'le':
            return self._clip_with_scalar(None, threshold, inplace=inplace)
        return self._clip_with_scalar(threshold, None, inplace=inplace)
    if <MASK>:
        if isinstance(self, ABCSeries):
            threshold = self._constructor(threshold, index=self.index)
        else:
            threshold = self._align_for_op(threshold, axis, flex=None)[1]
    if is_list_like(threshold):
        fill_value = np.inf if method.__name__ == 'le' else -np.inf
        threshold_inf = threshold.fillna(fill_value)
    else:
        threshold_inf = threshold
    subset = method(threshold_inf, axis=axis) | isna(self)
    return self.where(subset, threshold, axis=axis, inplace=inplace)

def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if ann is None:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if is_dict(ann):
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if value is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if ann is str:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if <MASK>:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if ann is torch.qscheme:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if maybe_script_class is not None:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

def nn_module_proxy(mod: Any) -> Any:
    if <MASK>:
        return mod
    if isinstance(mod, torch.fx.GraphModule):
        return mod
    proxy = mod.__class__.__new__(mod.__class__)
    proxy.__dict__ = mod.__dict__
    return proxy

def deserialize_output_spec(self, o: OutputSpec) -> ep.OutputSpec:
    log.debug('[deserialize_output_spec] %s', o)
    if o.type == 'user_output':
        return ep.OutputSpec(kind=ep.OutputKind.USER_OUTPUT, arg=self.deserialize_argument_spec(o.user_output.arg), target=None)
    elif o.type == 'loss_output':
        return ep.OutputSpec(kind=ep.OutputKind.LOSS_OUTPUT, arg=ep.TensorArgument(name=o.loss_output.arg.name), target=None)
    elif o.type == 'buffer_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.BUFFER_MUTATION, arg=ep.TensorArgument(name=o.buffer_mutation.arg.name), target=o.buffer_mutation.buffer_name)
    elif <MASK>:
        return ep.OutputSpec(kind=ep.OutputKind.PARAMETER_MUTATION, arg=ep.TensorArgument(name=o.parameter_mutation.arg.name), target=o.parameter_mutation.parameter_name)
    elif o.type == 'gradient_to_parameter':
        return ep.OutputSpec(kind=ep.OutputKind.GRADIENT_TO_PARAMETER, arg=ep.TensorArgument(name=o.gradient_to_parameter.arg.name), target=o.gradient_to_parameter.parameter_name)
    elif o.type == 'gradient_to_user_input':
        return ep.OutputSpec(kind=ep.OutputKind.GRADIENT_TO_USER_INPUT, arg=ep.TensorArgument(name=o.gradient_to_user_input.arg.name), target=o.gradient_to_user_input.user_input_name)
    elif o.type == 'user_input_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.USER_INPUT_MUTATION, arg=ep.TensorArgument(name=o.user_input_mutation.arg.name), target=o.user_input_mutation.user_input_name)
    elif o.type == 'token':
        return ep.OutputSpec(kind=ep.OutputKind.TOKEN, arg=ep.TokenArgument(name=o.token.arg.name), target=None)
    else:
        raise AssertionError(f'Unknown output spec {o}')

def as_array(self, dtype: np.dtype | None=None, copy: bool=False, na_value: object=lib.no_default) -> np.ndarray:
    """
        Convert the blockmanager data into an numpy array.

        Parameters
        ----------
        dtype : np.dtype or None, default None
            Data type of the return array.
        copy : bool, default False
            If True then guarantee that a copy is returned. A value of
            False does not guarantee that the underlying data is not
            copied.
        na_value : object, default lib.no_default
            Value to be used as the missing value sentinel.

        Returns
        -------
        arr : ndarray
        """
    passed_nan = lib.is_float(na_value) and isna(na_value)
    if len(self.blocks) == 0:
        arr = np.empty(self.shape, dtype=float)
        return arr.transpose()
    if self.is_single_block:
        blk = self.blocks[0]
        if na_value is not lib.no_default:
            if <MASK>:
                pass
            else:
                copy = True
        if blk.is_extension:
            arr = blk.values.to_numpy(dtype=dtype, na_value=na_value, copy=copy).reshape(blk.shape)
        elif not copy:
            arr = np.asarray(blk.values, dtype=dtype)
        else:
            arr = np.array(blk.values, dtype=dtype, copy=copy)
        if passed_nan and blk.dtype.kind in 'mM':
            arr[isna(blk.values)] = na_value
        if not copy:
            arr = arr.view()
            arr.flags.writeable = False
    else:
        arr = self._interleave(dtype=dtype, na_value=na_value)
    if na_value is lib.no_default:
        pass
    elif arr.dtype.kind == 'f' and passed_nan:
        pass
    else:
        arr[isna(arr)] = na_value
    return arr.transpose()

def infix_matmul(x, y):
    try:
        r = type(x).__matmul__(x, y)
    except AttributeError:
        r = NotImplemented
    if r is NotImplemented and type(x) is not type(y):
        try:
            r = type(y).__rmatmul__(y, x)
        except AttributeError:
            r = NotImplemented
    if <MASK>:
        raise TypeError("unsupported operand type(s) for @: '{}' and '{}'".format(type(x).__name__, type(y).__name__))
    return r

def _maybe_convert_setitem_value(self, value):
    """Maybe convert value to be pyarrow compatible."""
    if lib.is_scalar(value):
        if <MASK>:
            value = self.dtype.na_value
        elif not isinstance(value, str):
            raise TypeError(f"Invalid value '{value}' for dtype '{self.dtype}'. Value should be a string or missing value, got '{type(value).__name__}' instead.")
    else:
        value = extract_array(value, extract_numpy=True)
        if not is_array_like(value):
            value = np.asarray(value, dtype=object)
        elif isinstance(value.dtype, type(self.dtype)):
            return value
        else:
            value = np.asarray(value)
        if len(value) and (not lib.is_string_array(value, skipna=True)):
            raise TypeError("Invalid value for dtype 'str'. Value should be a string or missing value (or array of those).")
    return value

def dynamic_getattr(self, tx: 'InstructionTranslator', name):
    fake_val = self.proxy.node.meta['example_value']
    if not self.source and is_traceable_wrapper_subclass(fake_val):
        (attrs, _ctx) = fake_val.__tensor_flatten__()
        proxy = getattr(self.as_proxy(), name)
        example_value = getattr(fake_val, name)
        if name in attrs:
            assert isinstance(example_value, torch.Tensor)
            from .builder import wrap_fx_proxy
            return wrap_fx_proxy(tx=tx, proxy=proxy, example_value=example_value)
        elif not callable(example_value):
            return VariableTracker.build(tx, example_value)
    if not (self.source and self.source.subguards_allowed()):
        raise NotImplementedError
    scope = {'L': tx.output.local_scope, 'G': tx.output.global_scope}
    try:
        _input_associated_real_value = eval(self.source.name(), scope)
    except Exception as exc:
        raise NotImplementedError from exc
    if _input_associated_real_value is None:
        raise NotImplementedError
    if object_has_getattribute(_input_associated_real_value):
        raise NotImplementedError
    if get_custom_getattr(_input_associated_real_value):
        raise NotImplementedError
    real_value = getattr(_input_associated_real_value, name)
    attr_source = AttrSource(self.source, name)
    if <MASK>:
        from .misc import GetAttrVariable
        return GetAttrVariable(self, name, source=attr_source, py_type=type(real_value))
    install_guard(attr_source.make_guard(GuardBuilder.HASATTR))
    return VariableTracker.build(tx, real_value, attr_source)

def _validate_full_integer_quantization_bias_type(self):
    """Validates bias type for full interger quantization."""
    bias_type = self._full_integer_quantization_bias_type
    if <MASK>:
        return
    if self.activations_type() == _dtypes.float32:
        raise ValueError('`full_integer_quantization_bias_type` is only supported for full integer quantization.')
    if self.activations_type() == _dtypes.int8 and bias_type != _dtypes.int32:
        raise ValueError(f'Expected bias type to be `dtypes.int32` for Int8Quant. Current setting bias type: {bias_type}')
    if self.activations_type() == _dtypes.int16 and bias_type != _dtypes.int32 and (bias_type != _dtypes.int64):
        raise ValueError(f'Expected bias type to be `dtypes.int32` or `dtypes.int64` for Int16Quant. Current setting bias type: {bias_type}')

@skip_if_no_gpu
@skip_but_pass_in_sandcastle_if(BACKEND != 'nccl', 'NCCL Send Recv Only')
@requires_nccl_version((2, 7, 0), 'Need NCCL 2.7+ for send/recv')
def _test_send_recv_nccl(self, profiler_ctx=None):
    rank = dist.get_rank()
    world_size = dist.get_world_size()
    rank_to_GPU = init_multigpu_helper(world_size, BACKEND)
    device_id = rank_to_GPU[rank][0]
    torch.cuda.set_device(device_id)
    tensor = _build_tensor(rank + 1, device_id=device_id)
    profiler_cls = profiler_ctx if profiler_ctx is not None else nullcontext()
    with profiler_cls as prof:
        for src in range(world_size):
            if <MASK>:
                for dst in range(world_size):
                    if dst == rank:
                        continue
                    dist.send(tensor, dst)
            else:
                expected_tensor = _build_tensor(src + 1)
                output_tensor = _build_tensor(src + 1, value=-1, device_id=device_id)
                dist.recv(output_tensor, src)
                self.assertEqual(output_tensor, expected_tensor)
        self._barrier()
    if profiler_ctx is not None:
        backend = dist.get_backend()
        if backend in SEND_RECV_PROFILING_SUPPORTED_BACKENDS:
            for event_name in [f'{backend}:send', f'{backend}:recv']:
                events = get_profiling_event(event_name, prof, dedup_gpu_user_annotation=True)
                self.assertTrue(events)
                expected_shapes = [[[rank + 1] * 3] for rank in range(dist.get_world_size())]
                for event in events:
                    self.assertTrue(event.input_shapes in expected_shapes)

@def_function.function
def matmul(self, input_tensor: core.Tensor) -> Mapping[str, core.Tensor]:
    """Performs a matrix multiplication.

        Depending on self.has_bias and self.activation_fn, it may add a bias
        term or
        go through the activaction function.

        Args:
          input_tensor: Input tensor to matmul with the filter.

        Returns:
          A map of: output key -> output result.
        """
    out = math_ops.matmul(input_tensor, self.filters, name='sample/matmul')
    if self.has_reshape():
        input_shape = input_tensor.shape
        if <MASK>:
            reshape_shape = (input_shape[0], -1, self.bias_size)
        else:
            reshape_shape = (-1, self.bias_size)
        out = array_ops.reshape(out, reshape_shape)
    if self.has_bias():
        if self.use_biasadd:
            out = nn_ops.bias_add(out, self.bias)
        else:
            out = math_ops.add_v2(out, self.bias)
    if self.activation_fn is not None:
        out = self.activation_fn(out)
    return {'output': out}

def _get_managed_modules(root_modules: tuple[nn.Module, ...], ignored_params: Optional[set[nn.Parameter]]=None) -> list[nn.Module]:
    modules: list[nn.Module] = []
    root_modules_set = set(root_modules)
    visited_modules: set[nn.Module] = set()

    def dfs(module: nn.Module) -> None:
        """
        Runs a DFS to collect managed modules, not recursing into modules with
        a non-composable API or ``fully_shard`` already applied.
        """
        if not _is_composable_with_fsdp(module):
            return
        elif <MASK>:
            return
        visited_modules.add(module)
        for submodule in module.children():
            if submodule not in visited_modules:
                dfs(submodule)
        modules.append(module)
    for root_module in root_modules:
        dfs(root_module)
    if ignored_params is None:
        return modules
    adjusted_modules = _adjust_managed_modules(modules, ignored_params)
    return adjusted_modules

def call_torch_function(wrapper: WrappedOperator, func: Callable, types: tuple, args: tuple=(), kwargs: Optional[dict]=None) -> Any:
    """
    Handle __torch_function__ calls for wrapped operators.
    """
    if <MASK>:
        kwargs = {}
    from . import _Tensor
    return _Tensor.__torch_function__(func, types, args, kwargs)

@classmethod
def from_tensor(cls, tensor):
    """Convert a traced (composite)tensor to a representative KerasTensor."""
    if isinstance(tensor, tensor_lib.Tensor):
        name = getattr(tensor, 'name', None)
        type_spec = type_spec_module.type_spec_from_value(tensor)
        inferred_value = None
        if <MASK>:
            inferred_value = array_ops.ones(shape=tensor).shape
            if inferred_value.dims:
                inferred_value = inferred_value.as_list()
                if len(inferred_value) > _MAX_TENSOR_RANK:
                    inferred_value = None
            else:
                inferred_value = None
        return KerasTensor(type_spec, inferred_value=inferred_value, name=name)
    else:
        name = getattr(tensor, 'name', None)
        type_spec = type_spec_module.type_spec_from_value(tensor)
        return cls(type_spec, name=name)

def sign2map(a, var):
    """
    varname,ctype,atype
    init,init.r,init.i,pytype
    vardebuginfo,vardebugshowvalue,varshowvalue
    varrformat

    intent
    """
    out_a = a
    if isintent_out(var):
        for k in var['intent']:
            if k[:4] == 'out=':
                out_a = k[4:]
                break
    ret = {'varname': a, 'outvarname': out_a, 'ctype': getctype(var)}
    intent_flags = []
    for (f, s) in isintent_dict.items():
        if f(var):
            intent_flags.append(f'F2PY_{s}')
    if intent_flags:
        ret['intent'] = '|'.join(intent_flags)
    else:
        ret['intent'] = 'F2PY_INTENT_IN'
    if isarray(var):
        ret['varrformat'] = 'N'
    elif ret['ctype'] in c2buildvalue_map:
        ret['varrformat'] = c2buildvalue_map[ret['ctype']]
    else:
        ret['varrformat'] = 'O'
    (ret['init'], ret['showinit']) = getinit(a, var)
    if hasinitvalue(var) and iscomplex(var) and (not isarray(var)):
        (ret['init.r'], ret['init.i']) = markoutercomma(ret['init'][1:-1]).split('@,@')
    if isexternal(var):
        ret['cbnamekey'] = a
        if a in lcb_map:
            ret['cbname'] = lcb_map[a]
            ret['maxnofargs'] = lcb2_map[lcb_map[a]]['maxnofargs']
            ret['nofoptargs'] = lcb2_map[lcb_map[a]]['nofoptargs']
            ret['cbdocstr'] = lcb2_map[lcb_map[a]]['docstr']
            ret['cblatexdocstr'] = lcb2_map[lcb_map[a]]['latexdocstr']
        else:
            ret['cbname'] = a
            errmess('sign2map: Confused: external %s is not in lcb_map%s.\n' % (a, list(lcb_map.keys())))
    if isstring(var):
        ret['length'] = getstrlength(var)
    if isarray(var):
        ret = dictappend(ret, getarrdims(a, var))
        dim = copy.copy(var['dimension'])
    if <MASK>:
        ret['atype'] = c2capi_map[ret['ctype']]
        ret['elsize'] = get_elsize(var)
    if debugcapi(var):
        il = [isintent_in, 'input', isintent_out, 'output', isintent_inout, 'inoutput', isrequired, 'required', isoptional, 'optional', isintent_hide, 'hidden', iscomplex, 'complex scalar', l_and(isscalar, l_not(iscomplex)), 'scalar', isstring, 'string', isarray, 'array', iscomplexarray, 'complex array', isstringarray, 'string array', iscomplexfunction, 'complex function', l_and(isfunction, l_not(iscomplexfunction)), 'function', isexternal, 'callback', isintent_callback, 'callback', isintent_aux, 'auxiliary']
        rl = []
        for i in range(0, len(il), 2):
            if il[i](var):
                rl.append(il[i + 1])
        if isstring(var):
            rl.append(f"slen({a})={ret['length']}")
        if isarray(var):
            ddim = ','.join(map(lambda x, y: f'{x}|{y}', var['dimension'], dim))
            rl.append(f'dims({ddim})')
        if isexternal(var):
            ret['vardebuginfo'] = f"debug-capi:{a}=>{ret['cbname']}:{','.join(rl)}"
        else:
            ret['vardebuginfo'] = 'debug-capi:%s %s=%s:%s' % (ret['ctype'], a, ret['showinit'], ','.join(rl))
        if isscalar(var):
            if ret['ctype'] in cformat_map:
                ret['vardebugshowvalue'] = f"debug-capi:{a}={cformat_map[ret['ctype']]}"
        if isstring(var):
            ret['vardebugshowvalue'] = 'debug-capi:slen(%s)=%%d %s=\\"%%s\\"' % (a, a)
        if isexternal(var):
            ret['vardebugshowvalue'] = f'debug-capi:{a}=%p'
    if ret['ctype'] in cformat_map:
        ret['varshowvalue'] = f"#name#:{a}={cformat_map[ret['ctype']]}"
        ret['showvalueformat'] = f"{cformat_map[ret['ctype']]}"
    if isstring(var):
        ret['varshowvalue'] = '#name#:slen(%s)=%%d %s=\\"%%s\\"' % (a, a)
    (ret['pydocsign'], ret['pydocsignout']) = getpydocsign(a, var)
    if hasnote(var):
        ret['note'] = var['note']
    return ret

def get_devices_from(destinations, canonicalize_devices=True):
    if <MASK>:
        return destinations._devices
    if canonicalize_devices:
        if isinstance(destinations, six.string_types):
            return (device_util.resolve(destinations),)
        return (device_util.resolve(destinations.device),)
    if isinstance(destinations, six.string_types):
        return (device_util.canonicalize_without_job_and_task(destinations),)
    return (device_util.canonicalize_without_job_and_task(destinations.device),)

@register_backend
@fake_tensor_unsupported
def tvm(gm: fx.GraphModule, example_inputs: list[torch.Tensor], *, options: Optional[MappingProxyType[str, Any]]=None) -> Callable[..., Any]:
    if options is None:
        options = MappingProxyType({'scheduler': None, 'trials': 20000, 'opt_level': 3})
    assert options is not None
    import tvm
    from tvm import relay
    from tvm.contrib import graph_executor
    jit_mod = torch.jit.trace(gm, example_inputs)
    device = device_from_inputs(example_inputs)
    shape_list = [(f'inp_{idx}', i.shape) for (idx, i) in enumerate(example_inputs)]
    example_outputs = gm(*example_inputs)
    if len(example_outputs) == 0:
        log.warning('Explicitly fall back to eager due to zero output')
        return gm.forward
    (mod, params) = relay.frontend.from_pytorch(jit_mod, shape_list)
    if device.type == 'cuda':
        dev = tvm.cuda(device.index)
        target = tvm.target.cuda()
    else:
        dev = tvm.cpu(0)
        target = tvm.target.Target(llvm_target())
    scheduler = options.get('scheduler', None)
    if scheduler is None:
        scheduler = os.environ.get('TVM_SCHEDULER', None)
    trials = options.get('trials', 20000)
    opt_level = options.get('opt_level', 3)
    if scheduler == 'auto_scheduler':
        from tvm import auto_scheduler
        log_file = tempfile.NamedTemporaryFile()
        if not os.path.exists(log_file):
            (tasks, task_weights) = auto_scheduler.extract_tasks(mod['main'], params, target)
            if len(tasks) != 0:
                tuner = auto_scheduler.TaskScheduler(tasks, task_weights)
                if not os.path.exists(log_file):
                    assert trials > 0
                    tune_option = auto_scheduler.TuningOptions(num_measure_trials=trials, measure_callbacks=[auto_scheduler.RecordToFile(log_file)], early_stopping=2000)
                    try:
                        tuner.tune(tune_option)
                    except Exception:
                        if os.path.exists(log_file):
                            os.unlink(log_file)
                        raise
        with auto_scheduler.ApplyHistoryBest(log_file):
            with tvm.transform.PassContext(opt_level=opt_level, config={'relay.backend.use_auto_scheduler': True}):
                lib = relay.build(mod, target=target, params=params)
    elif scheduler == 'meta_schedule':
        from tvm import meta_schedule as ms
        with tempfile.TemporaryDirectory() as work_dir:
            if device.type != 'cuda':
                target = tvm.target.Target(f'{llvm_target()} --num-cores {ms.utils.cpu_count(logical=False)}')
            assert trials > 0
            database = ms.relay_integration.tune_relay(mod=mod, target=target, work_dir=work_dir, max_trials_global=trials, num_trials_per_iter=64, params=params, strategy='evolutionary', opt_level=opt_level)
            lib = ms.relay_integration.compile_relay(database=database, mod=mod, target=target, params=params, opt_level=opt_level)
    elif scheduler == 'default' or not scheduler:
        with tvm.transform.PassContext(opt_level=opt_level):
            lib = relay.build(mod, target=target, params=params)
    else:
        raise NotImplementedError("This tuning option is invalid/not implemented for torchdynamo's TVM-related backend. There are three available options: default, auto_scheduler and meta_schedule.")
    m = graph_executor.GraphModule(lib['default'](dev))

    def to_torch_tensor(nd_tensor: tvm.nd.array) -> torch.Tensor:
        """A helper function to transfer a NDArray to torch.tensor."""
        if <MASK>:
            return torch.from_numpy(nd_tensor.numpy())
        return torch.utils.dlpack.from_dlpack(nd_tensor.to_dlpack())

    def to_tvm_tensor(torch_tensor: torch.Tensor) -> tvm.nd.array:
        """A helper function to transfer a torch.tensor to NDArray."""
        if torch_tensor.dtype == torch.bool:
            return tvm.nd.array(torch_tensor.cpu().numpy())
        return tvm.nd.from_dlpack(torch_tensor)

    def exec_tvm(*i_args: torch.Tensor) -> list[torch.Tensor]:
        args = [a.contiguous() for a in i_args]
        (shape_info, _) = m.get_input_info()
        active_inputs = {name for (name, _) in shape_info.items()}
        for (idx, arg) in enumerate(args, 0):
            if arg.dim() != 0:
                if arg.requires_grad:
                    arg = arg.detach()
                inp_name = f'inp_{idx}'
                if inp_name not in active_inputs:
                    log.warning("input %s skipped as not found in tvm's runtime library", inp_name)
                    continue
                m.set_input(inp_name, to_tvm_tensor(arg))
        m.run()
        return [to_torch_tensor(m.get_output(i)) for i in range(m.get_num_outputs())]
    return exec_tvm

def partition_graph(self, fx_module: GraphModule, torch_module: torch.nn.Module, partitioner_config: PartitionerConfig) -> PartitionResult:
    """Given the fx module, torch module and partitioner_config,
        find the partitions, do the partitions,
        and then return a DAG and a new fx module with submodule nodes (partitions)
        """
    self.graph_module = fx_module
    self.torch_module = torch_module
    self.devices = partitioner_config.devices
    if len(self.devices) == 0:
        raise RuntimeError('No devices')
    get_size_of_all_nodes(self.graph_module)
    nodes = self.graph_module.graph.nodes
    if all((node.op in {'placeholder', 'get_attr', 'output'} for node in nodes)):
        raise RuntimeError('No Partition since no operations in the module')
    total_size_of_graph = 0
    for node in nodes:
        if node.op == 'output':
            break
        total_size_of_graph += node.size_bytes.total_size
    device_with_max_mem = max(self.devices, key=lambda d: d.available_mem_bytes)
    if <MASK>:
        self.aot_based_partition(partitioner_config.node_to_partition_mapping, partitioner_config.partition_to_logical_device_mapping)
    elif total_size_of_graph <= device_with_max_mem.available_mem_bytes:
        self.find_single_partition(total_size_of_graph, logical_device_id=device_with_max_mem.logical_id)
    elif total_size_of_graph > sum((d.available_mem_bytes for d in self.devices)):
        raise RuntimeError('Devices have no enough memory for the module')
    elif partitioner_config.mode == PartitionMode.sparse_nn:
        available_mem_bytes = self.devices[0].available_mem_bytes
        if not all((device.available_mem_bytes == available_mem_bytes for device in self.devices)):
            raise RuntimeError('All devices must have same memory size!')
        self.sparse_nn_partition(available_mem_bytes)
    elif partitioner_config.mode == PartitionMode.cost_aware:
        self.cost_aware_partition(partitioner_config.transfer_rate_bytes_per_sec, partitioner_config.node_to_latency_mapping)
    elif partitioner_config.mode == PartitionMode.kl_based:
        self.kl_based_partition(partitioner_config.transfer_rate_bytes_per_sec, partitioner_config.node_to_latency_mapping)
    else:
        self.size_based_partition()
    if partitioner_config.saturate_host:
        self.saturate_host()
    module_with_submodules = self.do_partition()
    dag = self.dump_dag(module_with_submodules)
    ret = PartitionResult(dag, module_with_submodules)
    return ret

def get_next_as_optional(self):
    if self._cardinality == cardinality_lib.INFINITE:
        return optional_ops.Optional.from_value(self._get_next_no_partial_batch_handling())
    if <MASK>:
        return optional_ops.Optional.empty(self._element_spec)
    optional_list = []
    for (i, worker) in enumerate(self._input_workers.worker_devices):
        with ops.device(worker):
            optional_list.append(self._iterators[i].get_next_as_optional_list())

    def _create_optional_with_dummy():
        value_list = _get_value_or_dummy(self._input_workers, optional_list, produce_dummy=True)
        if self._replica_order is not None:
            value_list = self._reorder_replicas(value_list)
        per_replica = _create_per_replica(value_list, self._strategy)
        return optional_ops.Optional.from_value(per_replica)

    def _create_empty_optional():
        return optional_ops.Optional.empty(self._element_spec)
    num_replicas_with_values = _calculate_replicas_with_values(self._strategy, self._input_workers, optional_list)
    return tf_cond.cond(num_replicas_with_values > 0, _create_optional_with_dummy, _create_empty_optional, strict=True)

@tf_contextlib.contextmanager
def _MaybeColocateWith(inputs):
    """A context manager for (maybe) colocating with a list of input tensors.

  Args:
    inputs: A list of `Tensor` or `Operation` objects.

  Returns:
    A context manager.
  """
    if <MASK>:
        yield
    else:
        with ops.colocate_with(inputs[0]), _MaybeColocateWith(inputs[1:]):
            yield

def on_node_creation(node):
    self.created_nodes.add(node.name)
    self.name_to_node[node.name] = node
    source = NodeSource(None, self.passname, NodeSourceAction.CREATE)
    if <MASK>:
        node.meta['from_node'] = [source]
    else:
        node.meta['from_node'].append(source)

def _repr_mimebundle_(self, **kwargs):
    """Mime bundle used by jupyter kernels to display estimator"""
    output = {'text/plain': repr(self)}
    if <MASK>:
        output['text/html'] = self._html_repr()
    return output

def fuse(self, node1, node2):
    if node1.is_foreach() or node2.is_foreach():
        return ForeachKernelSchedulerNode.fuse(node1, node2)
    elif node1.is_template():
        assert not node2.is_template()
        return FusedSchedulerNode.fuse(node1, node2)
    elif self._why_fuse_nodes(node1, node2) == ReasonFusedNodes.COMPATIBLE_RANGES_NO_REDUCTION:
        assert isinstance(node1, (SchedulerNode, FusedSchedulerNode))
        assert isinstance(node2, (SchedulerNode, FusedSchedulerNode))
        (_, (vars1, reduce1)) = node1.group
        (_, (vars2, reduce2)) = node2.group
        assert reduce1 == () and reduce2 == (), (reduce1, reduce2)

        def get_indexing_ranges_exprs(node):
            if isinstance(node, FusedSchedulerNode):
                assert len(node.snodes) > 0, node.snodes
                var_ranges = None
                indexing_exprs = OrderedSet[Any]()
                for snode in node.snodes:
                    (v, exprs) = get_indexing_ranges_exprs(snode)
                    if var_ranges is None:
                        var_ranges = v
                    assert var_ranges == v, (var_ranges, v, node.snodes)
                    indexing_exprs.update(exprs)
                return (var_ranges, list(indexing_exprs))
            else:
                assert isinstance(node, SchedulerNode)
                comp_buffer = node.node
                assert isinstance(comp_buffer, ir.ComputedBuffer)
                (_, body, _) = comp_buffer.get_default_sizes_body()
                return (body.var_ranges, list(body.indexing_exprs.values()))
        node_to_recomp = node1 if len(vars1) < len(vars2) else node2
        assert isinstance(node_to_recomp, SchedulerNode)
        ref_node = node2 if len(vars1) < len(vars2) else node1
        ref_indexing_constraints = get_indexing_ranges_exprs(ref_node)
        node_to_recomp.recompute_size_and_body(extra_indexing_constraints=ref_indexing_constraints)
        (_, (vars1, _)) = node1.group
        (_, (vars2, _)) = node2.group
        if <MASK>:
            return FusedSchedulerNode.fuse(node1, node2)
        node_to_recomp_indexing_constraints = get_indexing_ranges_exprs(node_to_recomp)
        if isinstance(ref_node, SchedulerNode):
            ref_node.recompute_size_and_body(extra_indexing_constraints=node_to_recomp_indexing_constraints)
        else:
            assert isinstance(ref_node, FusedSchedulerNode)
            for snode in ref_node.snodes:
                assert isinstance(snode, SchedulerNode)
                snode.recompute_size_and_body(extra_indexing_constraints=node_to_recomp_indexing_constraints)
            ref_node = FusedSchedulerNode(ref_node.scheduler, ref_node.snodes)
        (_, (vars1, _)) = node1.group
        (_, (vars2, _)) = node2.group
        assert vars1 == vars2, (vars1, vars2)
        return FusedSchedulerNode.fuse(node1, node2)
    elif self.can_fuse_vertical_outer_loop(node1, node2):
        return OuterLoopFusedSchedulerNode.fuse(node1, node2, self._get_outer_loop_fusion_depth(node1, node2))
    else:
        return FusedSchedulerNode.fuse(node1, node2)

def _validate_datetimelike_monotonic(self) -> None:
    """
        Validate self._on is monotonic (increasing or decreasing) and has
        no NaT values for frequency windows.
        """
    if <MASK>:
        self._raise_monotonic_error('values must not have NaT')
    if not (self._on.is_monotonic_increasing or self._on.is_monotonic_decreasing):
        self._raise_monotonic_error('values must be monotonic')

def _mha_shape_check(query: Tensor, key: Tensor, value: Tensor, key_padding_mask: Optional[Tensor], attn_mask: Optional[Tensor], num_heads: int):
    if query.dim() == 3:
        is_batched = True
        assert key.dim() == 3 and value.dim() == 3, f'For batched (3-D) `query`, expected `key` and `value` to be 3-D but found {key.dim()}-D and {value.dim()}-D tensors respectively'
        if <MASK>:
            assert key_padding_mask.dim() == 2, f'For batched (3-D) `query`, expected `key_padding_mask` to be `None` or 2-D but found {key_padding_mask.dim()}-D tensor instead'
        if attn_mask is not None:
            assert attn_mask.dim() in (2, 3), f'For batched (3-D) `query`, expected `attn_mask` to be `None`, 2-D or 3-D but found {attn_mask.dim()}-D tensor instead'
    elif query.dim() == 2:
        is_batched = False
        assert key.dim() == 2 and value.dim() == 2, f'For unbatched (2-D) `query`, expected `key` and `value` to be 2-D but found {key.dim()}-D and {value.dim()}-D tensors respectively'
        if key_padding_mask is not None:
            assert key_padding_mask.dim() == 1, f'For unbatched (2-D) `query`, expected `key_padding_mask` to be `None` or 1-D but found {key_padding_mask.dim()}-D tensor instead'
        if attn_mask is not None:
            assert attn_mask.dim() in (2, 3), f'For unbatched (2-D) `query`, expected `attn_mask` to be `None`, 2-D or 3-D but found {attn_mask.dim()}-D tensor instead'
            if attn_mask.dim() == 3:
                expected_shape = (num_heads, query.shape[0], key.shape[0])
                assert attn_mask.shape == expected_shape, f'Expected `attn_mask` shape to be {expected_shape} but got {attn_mask.shape}'
    else:
        raise AssertionError(f'query should be unbatched 2D or batched 3D tensor but received {query.dim()}-D query tensor')
    return is_batched

def _combine_masks(self, *variables: Optional[CSEVariable]):
    masks = None
    for elem in variables:
        if elem is None:
            continue
        if hasattr(elem, 'mask_vars'):
            if <MASK>:
                masks = elem.mask_vars
            else:
                masks = masks | elem.mask_vars
    return masks

def get_doc_object(obj, what=None, doc=None, config=None, class_doc=ClassDoc, func_doc=FunctionDoc, obj_doc=ObjDoc):
    if what is None:
        if inspect.isclass(obj):
            what = 'class'
        elif inspect.ismodule(obj):
            what = 'module'
        elif isinstance(obj, Callable):
            what = 'function'
        else:
            what = 'object'
    if <MASK>:
        config = {}
    if what == 'class':
        return class_doc(obj, func_doc=func_doc, doc=doc, config=config)
    elif what in ('function', 'method'):
        return func_doc(obj, doc=doc, config=config)
    else:
        if doc is None:
            doc = pydoc.getdoc(obj)
        return obj_doc(obj, doc, config=config)

def is_square(operator_a, operator_b):
    """Return a hint to whether the composition is square."""
    if <MASK>:
        return True
    if operator_a.is_square is False and operator_b.is_square is False:
        m = operator_a.range_dimension
        l = operator_b.domain_dimension
        if m is not None and l is not None:
            return m == l
    if operator_a.is_square != operator_b.is_square and (operator_a.is_square is not None and operator_b.is_square is not None):
        return False
    return None

def coerce_text(v):
    if not isinstance(v, basestring_):
        if <MASK>:
            return str(v)
        else:
            return bytes(v)
    return v

def do_cse(v: Union[str, CSEVariable]) -> CSEVariable:
    nonlocal output_idx
    var_dtype: Optional[torch.dtype] = output_dtype[output_idx] if isinstance(output_dtype, (list, tuple)) else output_dtype
    var_shape: BlockShapeType = output_shape[output_idx] if isinstance(output_shape, (list, tuple)) and len(output_shape) > 0 and isinstance(output_shape[0], (list, tuple)) else output_shape
    output_idx += 1
    if isinstance(v, CSEVariable):
        if <MASK>:
            v.dtype = var_dtype
        if v.shape is None:
            v.shape = var_shape
    csevar = V.kernel.cse.generate(V.kernel.compute, v, bounds=bounds, dtype=output_dtype, shape=output_shape)
    csevar.update_on_args(name, args, kwargs)
    if config.test_configs.runtime_triton_dtype_assert or config.test_configs.static_cpp_dtype_assert:
        assert var_dtype is not None
        check_dtype(V.kernel.compute, csevar, var_dtype)
    if config.test_configs.runtime_triton_shape_assert:
        assert output_shape is not None
        check_shape(V.kernel.compute, csevar, output_shape)
    return csevar

@classmethod
def create_from_checkpoint(cls, save_path: str):
    reader = py_checkpoint_reader.NewCheckpointReader(save_path)
    sparsecore_layouts_str = None
    for name in reader.get_variable_to_dtype_map():
        if <MASK>:
            sparsecore_layouts_str = reader.get_tensor(name)
            break
    if sparsecore_layouts_str is None:
        return cls(None)
    layouts = sparse_core_layout_pb2.SparseCoreTableLayouts()
    layouts.ParseFromString(sparsecore_layouts_str)
    logging.info('Loaded layouts from checkpoint: %s', layouts)
    return cls(layouts)

@_onnx_symbolic('aten::addmm')
@symbolic_helper.parse_args('v', 'v', 'v', 't', 't')
def addmm(g: jit_utils.GraphContext, self, mat1, mat2, beta, alpha):
    scalar_type = None
    self_scalar_type = symbolic_helper._try_get_scalar_type(self)
    mat1_scalar_type = symbolic_helper._try_get_scalar_type(mat1)
    mat2_scalar_type = symbolic_helper._try_get_scalar_type(mat2)
    if self_scalar_type is not None:
        scalar_type = self_scalar_type
    elif mat1_scalar_type is not None:
        scalar_type = mat1_scalar_type
    elif mat2_scalar_type is not None:
        scalar_type = mat2_scalar_type
    mat1_rank = symbolic_helper._get_tensor_rank(mat1)
    mat2_rank = symbolic_helper._get_tensor_rank(mat2)

    def is_not_none_nor(v, u):
        return v is not None and v != u
    if <MASK>:
        res1 = g.op('MatMul', mat1, mat2)
        res2 = self
        alpha = symbolic_helper._scalar(alpha)
        beta = symbolic_helper._scalar(beta)
        if alpha != 1:
            alpha = g.op('Constant', value_t=torch.tensor(alpha, dtype=scalar_type.dtype()))
            res1 = g.op('Mul', res1, alpha)
        if beta != 1:
            beta = g.op('Constant', value_t=torch.tensor(symbolic_helper._scalar(beta), dtype=scalar_type.dtype()))
            res2 = g.op('Mul', res2, beta)
        return g.op('Add', res1, res2)
    return g.op('Gemm', mat1, mat2, self, beta_f=symbolic_helper._scalar(beta), alpha_f=symbolic_helper._scalar(alpha))

def handle_fk_field(self, obj, field):
    """
        Handle a ForeignKey (they need to be treated slightly
        differently from regular fields).
        """
    self._start_relational_field(field)
    related_att = getattr(obj, field.attname)
    if <MASK>:
        if self.use_natural_foreign_keys and hasattr(field.remote_field.model, 'natural_key'):
            related = getattr(obj, field.name)
            related = related.natural_key()
            for key_value in related:
                self.xml.startElement('natural', {})
                self.xml.characters(str(key_value))
                self.xml.endElement('natural')
        else:
            self.xml.characters(str(related_att))
    else:
        self.xml.addQuickElement('None')
    self.xml.endElement('field')

