def _get_default_pk_class(self):
    pk_class_path = getattr(self.app_config, 'default_auto_field', settings.DEFAULT_AUTO_FIELD)
    if self.app_config and self.app_config._is_default_auto_field_overridden:
        app_config_class = type(self.app_config)
        source = f'{app_config_class.__module__}.{app_config_class.__qualname__}.default_auto_field'
    else:
        source = 'DEFAULT_AUTO_FIELD'
    if not pk_class_path:
        raise ImproperlyConfigured(f'{source} must not be empty.')
    try:
        pk_class = import_string(pk_class_path)
    except ImportError as e:
        msg = f"{source} refers to the module '{pk_class_path}' that could not be imported."
        raise ImproperlyConfigured(msg) from e
    if <MASK>:
        raise ValueError(f"Primary key '{pk_class_path}' referred by {source} must subclass AutoField.")
    return pk_class

def dump_max_mean_values(tol, ref, res):
    if isinstance(ref, (list, tuple, torch.nn.ParameterList, torch.Size)):
        for (refi, resi) in zip(ref, res):
            dump_max_mean_values(tol, refi, resi)
    elif <MASK>:
        for k in ref.keys():
            dump_max_mean_values(tol, ref[k], res[k])
    elif isinstance(ref, torch.Tensor):
        res = res.to(base_device)
        t = torch.abs(ref - res) / (1 + torch.abs(ref))
        tol.append(t.flatten().to(torch.float32))
    return tol

def __call__(self, func):
    if not callable(func):
        raise ValueError(f'Function {func} must be a callable.')
    argspec = tf_inspect.getargspec(func)
    if argspec.keywords or argspec.defaults:
        raise ValueError(f'Functions with argument defaults or keywords arguments are not supported. {func} has defaults {argspec.defaults} and keywords {argspec.keywords}.')
    min_args = len(argspec.args)
    max_args = min_args
    if argspec.varargs:
        max_args = 1000000
    argnames = argspec.args
    if tf_inspect.ismethod(func):
        min_args -= 1
        argnames = argnames[1:]
    if self._input_types:
        num = len(self._input_types)
        if <MASK>:
            raise ValueError(f'The number of tf.function input types is not compatible with the allowed arguments of {func}. The tf.function have {num} input types, while the python function allows minimum {min_args} and maximum {max_args} arguments.')
        return _DefinedFunction(func, argnames, self._input_types, self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)
    if min_args == 0 and max_args == 0:
        return _DefinedFunction(func, [], [], self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)
    return _OverloadedFunction(func, argnames, self._func_name, self._grad_func, self._python_grad_func, out_names=self._out_names, **self._extra_kwargs)

def _sqlite_datetime_trunc(lookup_type, dt, tzname, conn_tzname):
    dt = _sqlite_datetime_parse(dt, tzname, conn_tzname)
    if dt is None:
        return None
    if lookup_type == 'year':
        return f'{dt.year:04d}-01-01 00:00:00'
    elif lookup_type == 'quarter':
        month_in_quarter = dt.month - (dt.month - 1) % 3
        return f'{dt.year:04d}-{month_in_quarter:02d}-01 00:00:00'
    elif lookup_type == 'month':
        return f'{dt.year:04d}-{dt.month:02d}-01 00:00:00'
    elif lookup_type == 'week':
        dt -= timedelta(days=dt.weekday())
        return f'{dt.year:04d}-{dt.month:02d}-{dt.day:02d} 00:00:00'
    elif <MASK>:
        return f'{dt.year:04d}-{dt.month:02d}-{dt.day:02d} 00:00:00'
    elif lookup_type == 'hour':
        return f'{dt.year:04d}-{dt.month:02d}-{dt.day:02d} {dt.hour:02d}:00:00'
    elif lookup_type == 'minute':
        return f'{dt.year:04d}-{dt.month:02d}-{dt.day:02d} {dt.hour:02d}:{dt.minute:02d}:00'
    elif lookup_type == 'second':
        return f'{dt.year:04d}-{dt.month:02d}-{dt.day:02d} {dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}'
    raise ValueError(f'Unsupported lookup type: {lookup_type!r}')

def rt_with_partition_type(self, rt, partition_type):
    if isinstance(rt, tensor_lib.Tensor):
        return rt
    if partition_type == 'row_splits':
        return rt
    if <MASK>:
        return ragged_tensor.RaggedTensor.from_value_rowids(self.rt_with_partition_type(rt.values, partition_type), rt.value_rowids(), rt.nrows())
    raise AssertionError('Unexpected partition_type %r' % partition_type)

def _get_saver(self):
    if self._saver is not None:
        return self._saver
    elif self._scaffold is not None:
        return self._scaffold.saver
    collection_key = ops.GraphKeys.SAVERS
    savers = ops.get_collection(collection_key)
    if not savers:
        raise RuntimeError('No items in collection {}. Please add a saver to the collection or provide a saver or scaffold.'.format(collection_key))
    elif <MASK>:
        raise RuntimeError('More than one item in collection {}. Please indicate which one to use by passing it to the constructor.'.format(collection_key))
    self._saver = savers[0]
    return savers[0]

def decorator(f: Callable[..., Any]) -> Callable[..., None]:
    if <MASK>:
        raise ValueError('`run_in_graph_and_eager_modes` only supports test methods. Did you mean to use `run_all_in_graph_and_eager_modes`?')

    def decorated(self: 'TensorFlowTestCase', *args, **kwargs) -> None:
        logging.info('Running %s in GRAPH mode.', f.__name__)
        try:
            with context.graph_mode(), self.subTest('graph_mode'):
                for class_ in self.__class__.mro():
                    if class_.__name__ == 'XLATestCase':
                        session_func = self.session
                        session_kwargs = {}
                        break
                else:
                    session_func = self.test_session
                    session_kwargs = dict(use_gpu=use_gpu, config=config)
                with session_func(**session_kwargs):
                    f(self, *args, **kwargs)
        except unittest.case.SkipTest:
            pass

        def run_eagerly(self: 'TensorFlowTestCase', **kwargs) -> None:
            logging.info('Running %s in EAGER mode.', f.__name__)
            if not use_gpu:
                with ops.device('/device:CPU:0'):
                    f(self, *args, **kwargs)
            else:
                f(self, *args, **kwargs)
        if assert_no_eager_garbage:
            ops.reset_default_graph()
            run_eagerly = assert_no_new_tensors(assert_no_garbage_created(run_eagerly))
        self.tearDown()
        self._tempdir = None
        graph_for_eager_test = ops.Graph()
        with graph_for_eager_test.as_default(), context.eager_mode(), self.subTest('eager_mode'):
            self.setUp()
            run_eagerly(self, **kwargs)
        ops.dismantle_graph(graph_for_eager_test)
    return tf_decorator.make_decorator(f, decorated)

def compile_fn(self, gm: fx.GraphModule, example_inputs: list[torch.Tensor]) -> CompiledFn:
    """
        Implements graph splitting, first determining a set of of buckets by counting
        parameter sizes in reverse graph order, then invoking the user/backend compiler
        to compile each subgraph. Finally, stiches compiled graphs into one graphmodule
        and returns its callable.
        """
    buckets = [Bucket()]
    processed_modules: set[torch.nn.Module] = set()
    for node in reversed(gm.graph.nodes):
        if node.op in ('output', 'placeholder'):
            continue
        if buckets[0].size >= self.bucket_bytes_cap or (len(buckets) == 1 and buckets[0].size >= self.first_bucket_cap):
            if <MASK>:
                buckets.insert(0, Bucket())
            else:
                if buckets[0].opcount_increased_to_capture_external_output == 0:
                    buckets[0].paramsize_before_opcount_increase = buckets[0].size
                buckets[0].opcount_increased_to_capture_external_output += 1
        if node.op == 'call_function':
            self.add_param_args(buckets[0], node)
        elif node.op == 'call_module':
            target_mod = gm.get_submodule(node.target)
            if target_mod not in processed_modules:
                self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
        elif node.op == 'call_method':
            if isinstance(node.args[0].target, str):
                target_mod = None
                try:
                    target_mod = gm.get_submodule(node.args[0].target)
                except AttributeError:
                    pass
                if target_mod is not None and target_mod not in processed_modules:
                    self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
                self.add_param_args(buckets[0], node)
        elif node.op == 'get_attr':
            maybe_param = getattr(gm, node.target)
            if isinstance(maybe_param, torch.nn.Parameter) and maybe_param.requires_grad and (not self._ignore_parameter(maybe_param)):
                self.add_param(buckets[0], maybe_param, node.target)
        buckets[0].nodes.append(node)
    if len(buckets) > 1 and buckets[0].size == 0:
        buckets[1].nodes.extend(buckets[0].nodes)
        assert len(buckets[0].params) == 0, 'Params should be empty if size is 0'
        del buckets[0]
    self.buckets = buckets
    pretty_print_buckets(buckets, self.bucket_bytes_cap)
    if len(buckets) == 1:
        return self.backend_compile_fn(gm, example_inputs)
    partition_map = {}
    for (idx, b) in enumerate(buckets):
        for node in b.nodes:
            partition_map[node] = idx
    split_gm = fx.passes.split_module.split_module(gm, None, lambda node: partition_map[node])
    propagate_dynamo_source(gm, split_gm)
    propagate_metadata(gm, split_gm)
    debug_str = f'\n---orig graph---\n{gm.graph}\n' + f'\n---split graph---\n{split_gm.graph}\n'
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            debug_str += f'\n---{name} graph---\n{module.graph}\n'
    debug_str += '\n---------------\n'
    ddp_graph_log.debug(debug_str)
    trace_structured('optimize_ddp_split_graph', payload_fn=lambda : split_gm.print_readable(print_output=False))
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            trace_structured('optimize_ddp_split_child', lambda : {'name': name}, payload_fn=lambda : module.print_readable(print_output=False))
    fake_mode = detect_fake_mode(example_inputs)
    if fake_mode is None:
        fake_mode = torch._subclasses.fake_tensor.FakeTensorMode()
    submod_compiler = SubmodCompiler(split_gm, self.backend_compile_fn, fake_mode)
    with torch._dynamo.utils._disable_saved_tensors_hooks_during_tracing():
        submod_compiler.run(*example_inputs)
    split_gm.recompile()
    ddp_graph_log.debug('\n---final graph---\n%s\n---------------\n', split_gm.graph)
    return split_gm

def __eq__(self, other: object) -> bool:
    if <MASK>:
        return self.lhs == other.lhs and self.rhs == other.rhs
    else:
        return False

def __get_tensor_shard__(self, index: MetadataIndex) -> torch.Tensor:
    """
        For compatibility with DCP, we support finding shard based on index
        Return a 'torch.Tensor' shard based on 'MetadataIndex'.
        """
    if <MASK>:
        if len(self._local_shards) > index.index and self._storage_meta.chunks[index.index].offsets == index.offset:
            return self._local_shards[index.index]
    if index.offset is not None:
        for (shard, chunk) in zip(self._local_shards, self._storage_meta.chunks):
            if chunk.offsets == index.offset:
                return shard
    if len(self._local_shards) == 0 and self._storage_meta.chunks[0].sizes == torch.Size([0, 0]):
        return torch.empty(0)
    raise ValueError(f"Could not find shard at '{index.offset}' for FQN: '{index.fqn}'")

def _create_test_db(self, verbosity=1, autoclobber=False, keepdb=False):
    parameters = self._get_test_db_params()
    with self._maindb_connection.cursor() as cursor:
        if self._test_database_create():
            try:
                self._execute_test_db_creation(cursor, parameters, verbosity, keepdb)
            except Exception as e:
                if 'ORA-01543' not in str(e):
                    self.log('Got an error creating the test database: %s' % e)
                    sys.exit(2)
                if <MASK>:
                    confirm = input("It appears the test database, %s, already exists. Type 'yes' to delete it, or 'no' to cancel: " % parameters['user'])
                if autoclobber or confirm == 'yes':
                    if verbosity >= 1:
                        self.log("Destroying old test database for alias '%s'..." % self.connection.alias)
                    try:
                        self._execute_test_db_destruction(cursor, parameters, verbosity)
                    except DatabaseError as e:
                        if 'ORA-29857' in str(e):
                            self._handle_objects_preventing_db_destruction(cursor, parameters, verbosity, autoclobber)
                        else:
                            self.log('Got an error destroying the old test database: %s' % e)
                            sys.exit(2)
                    except Exception as e:
                        self.log('Got an error destroying the old test database: %s' % e)
                        sys.exit(2)
                    try:
                        self._execute_test_db_creation(cursor, parameters, verbosity, keepdb)
                    except Exception as e:
                        self.log('Got an error recreating the test database: %s' % e)
                        sys.exit(2)
                else:
                    self.log('Tests cancelled.')
                    sys.exit(1)
        if self._test_user_create():
            if verbosity >= 1:
                self.log('Creating test user...')
            try:
                self._create_test_user(cursor, parameters, verbosity, keepdb)
            except Exception as e:
                if 'ORA-01920' not in str(e):
                    self.log('Got an error creating the test user: %s' % e)
                    sys.exit(2)
                if not autoclobber:
                    confirm = input("It appears the test user, %s, already exists. Type 'yes' to delete it, or 'no' to cancel: " % parameters['user'])
                if autoclobber or confirm == 'yes':
                    try:
                        if verbosity >= 1:
                            self.log('Destroying old test user...')
                        self._destroy_test_user(cursor, parameters, verbosity)
                        if verbosity >= 1:
                            self.log('Creating test user...')
                        self._create_test_user(cursor, parameters, verbosity, keepdb)
                    except Exception as e:
                        self.log('Got an error recreating the test user: %s' % e)
                        sys.exit(2)
                else:
                    self.log('Tests cancelled.')
                    sys.exit(1)
    self._maindb_connection.close()
    self._switch_to_test_user(parameters)
    return self.connection.settings_dict['NAME']

def getsetitem(self: Any, index: Any, tensors_have_dims: bool) -> IndexingInfo:
    from . import DimList
    can_call_original_getitem = not tensors_have_dims
    input_list = []
    if has_dims(index):
        input_list.append(index)
    else:
        is_sequence = extractIndices(index, input_list)
        if can_call_original_getitem and (not is_sequence):
            return IndexingInfo(can_call_original=True)
    dims_indexed = 0
    expanding_object = -1
    unbound_dim_list = None
    dimlists = []

    def check_expanding(i: int) -> None:
        nonlocal expanding_object
        if expanding_object != -1:
            from . import DimensionBindError
            raise DimensionBindError(f'at most one ... or unbound dimension list can exist in indexing list but found 2 at offsets {expanding_object} and {i}')
        expanding_object = i

    def is_dimpack(s: Any) -> bool:
        from . import Dim
        return isinstance(s, (tuple, list)) and len(s) > 0 and all((Dim.check_exact(item) for item in s))
    has_dimpacks_or_none = False
    for (i, s) in enumerate(input_list):
        if has_dims(s):
            can_call_original_getitem = False
            dims_indexed += 1
        elif s is ...:
            check_expanding(i)
        elif isinstance(s, DimList):
            can_call_original_getitem = False
            if <MASK>:
                check_expanding(i)
                unbound_dim_list = s
            else:
                dims_indexed += len(s._dims)
            dimlists.append(i)
        elif s is None:
            has_dimpacks_or_none = True
        elif is_dimpack(s):
            can_call_original_getitem = False
            has_dimpacks_or_none = True
            dims_indexed += 1
        else:
            dims_indexed += 1
    if can_call_original_getitem:
        return IndexingInfo(can_call_original=True)
    self_info = TensorInfo.create(self, False, True)
    total_dims = len(self_info.levels)
    if dims_indexed > total_dims:
        raise ValueError(f'at least {dims_indexed} indices were supplied but the tensor only has {total_dims} dimensions')
    expanding_dims = total_dims - dims_indexed
    if expanding_object != -1:
        if unbound_dim_list is not None:
            unbound_dim_list.bind_len(expanding_dims)
        else:
            no_slices = [slice(None)] * expanding_dims
            input_list = input_list[:expanding_object] + no_slices + input_list[expanding_object + 1:]
    for i in range(len(dimlists) - 1, -1, -1):
        idx = dimlists[i]
        if unbound_dim_list is None and expanding_object != -1 and (idx > expanding_object):
            idx += expanding_dims
        dl = input_list[idx]
        input_list = input_list[:idx] + dl._dims + input_list[idx + 1:]
    return getsetitem_flat(self_info, input_list, [], [], has_dimpacks_or_none)

def Test(self):
    np.random.seed(1)
    n = shape_[-1]
    batch_shape = shape_[:-2]
    np_dtype = dtype_.as_numpy_dtype

    def RandomInput():
        a = np.random.uniform(low=-1.0, high=1.0, size=n * n).reshape([n, n]).astype(np_dtype)
        if <MASK>:
            a += 1j * np.random.uniform(low=-1.0, high=1.0, size=n * n).reshape([n, n]).astype(np_dtype)
        a += np.conj(a.T)
        a = np.tile(a, batch_shape + (1, 1))
        return a
    epsilon = np.finfo(np_dtype).eps
    delta = 0.1 * epsilon ** (1.0 / 3.0)
    _ = RandomInput()
    if dtype_ in (dtypes_lib.float32, dtypes_lib.complex64):
        tol = 0.02
    else:
        tol = 1e-07
    with self.session():

        def Compute(x):
            (e, v) = linalg_ops.self_adjoint_eig(x)
            top_rows = v[..., 0:1, :]
            if dtype_.is_complex:
                angle = -math_ops.angle(top_rows)
                phase = math_ops.complex(math_ops.cos(angle), math_ops.sin(angle))
            else:
                phase = math_ops.sign(top_rows)
            v *= phase
            return (e, v)
        if compute_v_:
            funcs = [lambda x: Compute(x)[0], lambda x: Compute(x)[1]]
        else:
            funcs = [linalg_ops.self_adjoint_eigvals]
        for f in funcs:
            (theoretical, numerical) = gradient_checker_v2.compute_gradient(f, [RandomInput()], delta=delta)
            self.assertAllClose(theoretical, numerical, atol=tol, rtol=tol)

def can_inplace(self, read_dep: dependencies.Dep) -> bool:
    if self.is_template():
        return False
    if <MASK>:
        return False
    if len(self.read_writes.writes) == 1 and isinstance(read_dep, dependencies.MemoryDep):
        write_dep = next(iter(self.read_writes.writes))
        assert isinstance(write_dep, dependencies.MemoryDep), f'type(write_dep)={type(write_dep)!r}'
        return read_dep.index == write_dep.index and read_dep.size == write_dep.size
    return False

def get_tcsds_rootdir(self):
    tcsdsroot = os.environ.get('TCSDS_PATH', None)
    if <MASK>:
        return tcsdsroot
    return None

def call_function(self, target: Callable, args: Any, kwargs: dict[str, Any]) -> Any:
    if target is operator.getitem and isinstance(args[0], (list, tuple, dict)):
        return super().call_function(target, args, kwargs)
    if not isinstance(target, torch._ops.OpOverloadPacket) and hasattr(target, '_inductor_lowering_function'):
        return target(*args, **kwargs)
    if <MASK>:
        assert isinstance(target, torch._ops.OpOverload), f'{target} is not an OpOverload'
        base_name = target.name().split('.')[0]
        if base_name in FALLBACK_ALLOW_LIST:
            make_fallback(target, warn=False, override_decomp=True)
        elif config.implicit_fallbacks:
            error = MissingOperatorWithDecomp if get_decompositions([target]) else MissingOperatorWithoutDecomp
            log.info('Creating implicit fallback for:\n%s', error.operator_str(target, args, kwargs))
            tag: Optional[torch._C.Tag] = get_layout_constraint_tag(target, with_default=False)
            if tag is None and torch._library.utils.is_builtin(target) and self.is_backward:
                decided_constraint = require_contiguous
            else:
                default_tag: torch._C.Tag = get_layout_constraint_tag(target, with_default=True)
                decided_constraint = tag_to_layout_constraint(default_tag)
            make_fallback(target, layout_constraint=decided_constraint)
        elif get_decompositions([target]):
            raise MissingOperatorWithDecomp(target, args, kwargs)
        else:
            raise MissingOperatorWithoutDecomp(target, args, kwargs)
    try:
        log.debug('  via %s', lowerings[target])
        n = self.current_node
        layout_constraints = maybe_layout_constraints(target)
        if layout_constraints:
            (old_args, old_kwargs) = (args, kwargs)
            if layout_constraints is constrain_to_fake_tensors:
                if 'eager_input_vals' in n.meta:
                    (fake_args, fake_kwargs) = n.meta['eager_input_vals']
                    assert isinstance(target, torch._ops.OpOverload)

                    def normalize(args: Any, kwargs: Any) -> tuple[Any, Any]:
                        result = torch.fx.operator_schemas.normalize_function(target, args, kwargs)
                        assert result is not None
                        return (result[0], result[1])
                    (fake_args, fake_kwargs) = normalize(fake_args, fake_kwargs)
                    (args, kwargs) = normalize(args, kwargs)
                    (old_args, old_kwargs) = normalize(old_args, old_kwargs)
                    (args, kwargs) = constrain_to_fake_tensors(args, kwargs, fake_args, fake_kwargs)
            else:
                (args, kwargs) = layout_constraints(n, *args, **kwargs)
        out = lowerings[target](*args, **kwargs)
        if layout_constraints:
            self.propagate_mutation(n, old_args, old_kwargs, args, kwargs)
        return out
    except Exception as e:
        raise LoweringException(e, target, args, kwargs).with_traceback(e.__traceback__) from None

