def xframe_options_exempt(view_func):
    """
    Modify a view function by setting a response variable that instructs
    XFrameOptionsMiddleware to NOT set the X-Frame-Options HTTP header. Usage:

    @xframe_options_exempt
    def some_view(request):
        ...
    """
    if <MASK>:

        async def _view_wrapper(*args, **kwargs):
            response = await view_func(*args, **kwargs)
            response.xframe_options_exempt = True
            return response
    else:

        def _view_wrapper(*args, **kwargs):
            response = view_func(*args, **kwargs)
            response.xframe_options_exempt = True
            return response
    return wraps(view_func)(_view_wrapper)

def call_command(command_name, *args, **options):
    """
    Call the given command, with the given options and args/kwargs.

    This is the primary API you should use for calling specific commands.

    `command_name` may be a string or a command object. Using a string is
    preferred unless the command object is required for further processing or
    testing.

    Some examples:
        call_command('migrate')
        call_command('shell', plain=True)
        call_command('sqlmigrate', 'myapp')

        from django.core.management.commands import flush
        cmd = flush.Command()
        call_command(cmd, verbosity=0, interactive=False)
        # Do something with cmd ...
    """
    if isinstance(command_name, BaseCommand):
        command = command_name
        command_name = command.__class__.__module__.split('.')[-1]
    else:
        try:
            app_name = get_commands()[command_name]
        except KeyError:
            raise CommandError('Unknown command: %r' % command_name)
        if isinstance(app_name, BaseCommand):
            command = app_name
        else:
            command = load_command_class(app_name, command_name)
    parser = command.create_parser('', command_name)
    opt_mapping = {min(s_opt.option_strings).lstrip('-').replace('-', '_'): s_opt.dest for s_opt in parser._actions if s_opt.option_strings}
    arg_options = {opt_mapping.get(key, key): value for (key, value) in options.items()}
    parse_args = []
    for arg in args:
        if isinstance(arg, (list, tuple)):
            parse_args += map(str, arg)
        else:
            parse_args.append(str(arg))

    def get_actions(parser):
        for opt in parser._actions:
            if <MASK>:
                for sub_opt in opt.choices.values():
                    yield from get_actions(sub_opt)
            else:
                yield opt
    parser_actions = list(get_actions(parser))
    mutually_exclusive_required_options = {opt for group in parser._mutually_exclusive_groups for opt in group._group_actions if group.required}
    for opt in parser_actions:
        if opt.dest in options and (opt.required or opt in mutually_exclusive_required_options):
            opt_dest_count = sum((v == opt.dest for v in opt_mapping.values()))
            if opt_dest_count > 1:
                raise TypeError(f'Cannot pass the dest {opt.dest!r} that matches multiple arguments via **options.')
            parse_args.append(min(opt.option_strings))
            if isinstance(opt, (_AppendConstAction, _CountAction, _StoreConstAction)):
                continue
            value = arg_options[opt.dest]
            if isinstance(value, (list, tuple)):
                parse_args += map(str, value)
            else:
                parse_args.append(str(value))
    defaults = parser.parse_args(args=parse_args)
    defaults = dict(defaults._get_kwargs(), **arg_options)
    stealth_options = set(command.base_stealth_options + command.stealth_options)
    dest_parameters = {action.dest for action in parser_actions}
    valid_options = (dest_parameters | stealth_options).union(opt_mapping)
    unknown_options = set(options) - valid_options
    if unknown_options:
        raise TypeError('Unknown option(s) for %s command: %s. Valid options are: %s.' % (command_name, ', '.join(sorted(unknown_options)), ', '.join(sorted(valid_options))))
    args = defaults.pop('args', ())
    if 'skip_checks' not in options:
        defaults['skip_checks'] = True
    return command.execute(*args, **defaults)

def check_same_shape(*args, allow_cpu_scalar_tensors: bool):
    """
    Checks that all Tensors in args have the same shape.

    Raises a RuntimeError when:
      - args contains an object whose type is not Tensor or Number
      - two Tensor objects in args have different devices
    """
    shape = None
    for arg in args:
        if isinstance(arg, Number):
            continue
        elif isinstance(arg, TensorLike):
            if <MASK>:
                continue
            if shape is None:
                shape = arg.shape
            if not is_same_shape(shape, arg.shape):
                msg = f'Shape {arg.shape} is not the expected shape {shape}!'
                raise RuntimeError(msg)
        else:
            msg = 'Unexpected type when checking for same shape, ' + str(type(arg)) + '!'
            raise RuntimeError(msg)

def _pairwise_callable(X, Y, metric, ensure_all_finite=True, **kwds):
    """Handle the callable case for pairwise_{distances,kernels}."""
    (xp, _, device) = get_namespace_and_device(X)
    (X, Y) = check_pairwise_arrays(X, Y, dtype=None, ensure_all_finite=ensure_all_finite, ensure_2d=False)
    (_, _, dtype_float) = _find_floating_dtype_allow_sparse(X, Y, xp=xp)

    def _get_slice(array, index):
        if <MASK>:
            return array[[index], :]
        if array.ndim == 1:
            return array[index]
        else:
            return array[index, ...]
    if X is Y:
        out = xp.zeros((X.shape[0], Y.shape[0]), dtype=dtype_float, device=device)
        iterator = itertools.combinations(range(X.shape[0]), 2)
        for (i, j) in iterator:
            x = _get_slice(X, i)
            y = _get_slice(Y, j)
            out[i, j] = metric(x, y, **kwds)
        out = out + out.T
        for i in range(X.shape[0]):
            x = _get_slice(X, i)
            out[i, i] = metric(x, x, **kwds)
    else:
        out = xp.empty((X.shape[0], Y.shape[0]), dtype=dtype_float)
        iterator = itertools.product(range(X.shape[0]), range(Y.shape[0]))
        for (i, j) in iterator:
            x = _get_slice(X, i)
            y = _get_slice(Y, j)
            out[i, j] = metric(x, y, **kwds)
    return out

def _check_db_default(self, databases=None, **kwargs):
    from django.db.models.expressions import Value
    if not self.has_db_default() or (isinstance(self.db_default, Value) or not hasattr(self.db_default, 'resolve_expression')) or databases is None:
        return []
    errors = []
    for db in databases:
        if not router.allow_migrate_model(db, self.model):
            continue
        connection = connections[db]
        if not getattr(self._db_default_expression, 'allowed_default', False) and connection.features.supports_expression_defaults:
            msg = f'{self.db_default} cannot be used in db_default.'
            errors.append(checks.Error(msg, obj=self, id='fields.E012'))
        if <MASK>:
            msg = f'{connection.display_name} does not support default database values with expressions (db_default).'
            errors.append(checks.Error(msg, obj=self, id='fields.E011'))
    return errors

def forward(self, input, extra_input):
    if len(input.shape) != 4:
        raise ValueError('Input shape must be `(N, C, H, W)`!')
    if <MASK>:
        _reversed_padding_repeated_twice = _reverse_repeat_padding(self.padding)
        input = F.pad(input, _reversed_padding_repeated_twice, mode=self.padding_mode)
    return torch.ops.quantized.conv2d_add_relu(input, extra_input, self._packed_params, self.scale, self.zero_point)

def _add_batched_ragged_partition(rt, partition, tensor_dict, feature_key, validate, outer_splits=None):
    """Adds a batched ragged partition tensor to a batched ragged tensor.

  Args:
    rt: A RaggedTensor with shape [batch_size, ...].
    partition: The partition configuration object.  Specifies the key that
      should be used to look up the partition tensor (unless partition is a
      RaggedFeature.UniformRowLength, in which case there is no partition
      tensor).  The specified tensor must have shape [batch_size, ...].
    tensor_dict: The dictionary mapping keys to tensors.
    feature_key: The name of the feature being parsed (for error messages).
    validate: Whether to validate that the values form a valid RaggedTensor.
    outer_splits: If not None, then we have two batch dimensions, and this
      is the row-splits for the collapsed batch dimension.  Every partition
      tensor must have an outer row_splits that matches this value.

  Returns:
    A new RaggedTensor where each batch item `rt[i]` has been partitioned
    using the `partition_t[i]`.
  """
    if isinstance(partition, RaggedFeature.UniformRowLength):
        if rt.ragged_rank > 1:
            length = ops.convert_to_tensor(partition.length, rt.row_splits.dtype)
            return ragged_tensor.RaggedTensor.from_row_splits(ragged_tensor.RaggedTensor.from_uniform_row_length(rt.values, length, validate=validate), rt.row_splits // length, validate=validate)
        else:
            reshaped_vals = array_ops.reshape(rt.values, array_ops.concat([[-1, partition.length], array_ops.shape(rt.values)[1:]], axis=0))
            return ragged_tensor.RaggedTensor.from_row_splits(reshaped_vals, rt.row_splits // partition.length, validate=validate)
    partition_t = tensor_dict[partition.key]
    if partition_t.values.dtype != rt.row_splits.dtype:
        partition_t = math_ops.cast(partition_t, rt.row_splits.dtype)
    checks = []
    if outer_splits is not None:
        if validate:
            checks.append(check_ops.assert_equal(outer_splits, partition_t.row_splits, message='Feature %s: values and partitions are not aligned' % feature_key))
        partition_t = partition_t.values
    with ops.control_dependencies(checks):
        if isinstance(partition, (RaggedFeature.RowSplits, RaggedFeature.RowLimits)):
            if isinstance(partition, RaggedFeature.RowSplits):
                partition_t = partition_t[:, 1:]
            adjusted_limits = partition_t.values + array_ops.repeat(rt.row_starts(), partition_t.row_lengths())
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_limits(rt.values, adjusted_limits, validate=validate))
        elif <MASK>:
            adjusted_starts = partition_t.values + array_ops.repeat(rt.row_starts(), partition_t.row_lengths())
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_starts(rt.values, adjusted_starts, validate=validate))
        elif isinstance(partition, RaggedFeature.RowLengths):
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_lengths(rt.values, partition_t.values, validate=validate))
        elif isinstance(partition, RaggedFeature.ValueRowIds):
            nrows = math_ops.maximum(ragged_math_ops.reduce_max(partition_t + 1, axis=1), 0)
            adjusted_rowids = partition_t.values + array_ops.repeat(math_ops.cumsum(nrows, exclusive=True), partition_t.row_lengths())
            return ragged_tensor.RaggedTensor.from_row_lengths(ragged_tensor.RaggedTensor.from_value_rowids(rt.values, adjusted_rowids, validate=validate), nrows, validate=validate)
        raise ValueError(f'Unhandled partition type {partition!r}')

def _select_tiling_indices(self, fn_list, var_sizes_list, tiling_factor):
    all_index = []
    for (fn, var_sizes) in zip(fn_list, var_sizes_list):
        rw = dependencies.extract_read_writes(fn, *var_sizes)
        all_index += [dep.index for dep in itertools.chain(rw.reads, rw.writes)]
    contig_vars = OrderedSet[int]()
    contig_vars_list = []
    non_contig_stride_const = OrderedSet[int]()
    non_contig_stride_other = OrderedSet[int]()
    for index in all_index:
        for var in index.free_symbols:
            if not re.search('^d\\d+$', var.name):
                continue
            stride = stride_at_vec_range(index, var, tiling_factor)
            if stride == 0:
                continue
            elif stride == 1:
                contig_vars.add(int(var.name[1:]))
                contig_vars_list.append(int(var.name[1:]))
            elif all((symbol_is_type(s, SymT.SIZE) for s in stride.free_symbols)):
                non_contig_stride_const.add(int(var.name[1:]))
            else:
                non_contig_stride_other.add(int(var.name[1:]))
    contig_only = contig_vars - non_contig_stride_const - non_contig_stride_other
    (group, reduction_group) = max(var_sizes_list, key=lambda sizes: len(sizes[1]))
    num_itervars = len(group) + len(reduction_group)
    if <MASK>:
        return [num_itervars - 1]
    if contig_only:
        return sorted(contig_only)[-1:]
    contig_and_const_stride = (contig_vars & non_contig_stride_const) - non_contig_stride_other
    contig_vars_sorted = sorted(contig_vars)
    if len(contig_vars_sorted) == 2 and contig_vars_sorted[-1] in contig_and_const_stride and (contig_vars_sorted[-1] == num_itervars - 1):
        return contig_vars_sorted
    return sorted(contig_vars_sorted, key=contig_vars_list.count)[-1:]

def _nvcc_compiler_options() -> list[str]:
    arch = _nvcc_arch_as_compile_option()
    code = [f'sm_{arch}', f'compute_{arch}']
    if config.cuda.enable_cuda_lto:
        code += [f'lto_{arch}']
    options = ['-t=0', '-DCUTLASS_ENABLE_TENSOR_CORE_MMA=1', '-DCUTLASS_ENABLE_SM90_EXTENDED_MMA_SHAPES=1', '-DCUTE_SM90_EXTENDED_MMA_SHAPES_ENABLED', '-w', f"-gencode=arch=compute_{arch},code=[{','.join(code)}]", config.cuda.compile_opt_level, '-std=c++17', '--expt-relaxed-constexpr', '-DNDEBUG']
    if <MASK>:
        options.extend(['-ccbin', os.path.dirname(build_paths.gcc)])
    if config.cuda.enable_debug_info:
        options.extend(['-lineinfo', '-g', '-DCUTLASS_DEBUG_TRACE_LEVEL=1'])
    if config.cuda.enable_ptxas_info:
        options.extend(['--keep', '--ptxas-options=--warn-on-local-memory-usage', '--ptxas-options=--warn-on-spills', '--resource-usage', '--source-in-ptx'])
    if config.cuda.use_fast_math:
        options.extend(['--use_fast_math', '-DCUTLASS_USE_TANH_FOR_SIGMOID=1'])
    return options

def testV2KeywordArgNames(self):
    if not hasattr(tf.compat, 'v2'):
        return
    v2_arg_exceptions = {'verify_shape_is_now_always_true', 'keyword_required', '_sentinel'}
    v1_name_exceptions = {'tf.print'}
    function_warnings = tf_upgrade_v2.TFAPIChangeSpec().function_warnings
    function_transformers = tf_upgrade_v2.TFAPIChangeSpec().function_transformers
    keyword_renames = tf_upgrade_v2.TFAPIChangeSpec().function_keyword_renames

    def conversion_visitor(unused_path, unused_parent, children):
        for child in children:
            (_, attr) = tf_decorator.unwrap(child[1])
            if not tf_inspect.isfunction(attr):
                continue
            names_v1 = tf_export.get_v1_names(attr)
            arg_names_v1 = get_args(attr)
            for name in names_v1:
                tf_name = 'tf.%s' % name
                if tf_name in function_warnings or tf_name in function_transformers:
                    continue
                if tf_name in v1_name_exceptions:
                    continue
                args = ','.join(['%s=%d' % (from_name, from_index) for (from_index, from_name) in enumerate(arg_names_v1)])
                text_input = '%s(%s)' % (tf_name, args)
                (_, _, _, text) = self._upgrade(text_input)
                (new_function_name, new_args) = get_func_and_args_from_str(text)
                if <MASK>:
                    continue
                if new_function_name == 'tf.compat.v1.%s' % name:
                    if tf_name in keyword_renames:
                        self.fail("Function '%s' is not in 2.0 when converting\n%s\nto\n%s" % (new_function_name, text_input, text))
                    continue
                if new_function_name.startswith('tf.compat.v2'):
                    self.assertIn(new_function_name.replace('tf.compat.v2.', 'tf.'), self.v2_symbols)
                    continue
                args_v2 = get_args(self.v2_symbols[new_function_name])
                args_v2.extend(v2_arg_exceptions)
                for new_arg in new_args:
                    self.assertIn(new_arg, args_v2, "Invalid argument '%s' in 2.0 when converting\n%s\nto\n%s.\nSupported arguments: %s" % (new_arg, text_input, text, str(args_v2)))
                if new_function_name in set(['tf.nn.ctc_loss', 'tf.saved_model.save']):
                    continue
                args_v1 = get_args(self.v1_symbols[new_function_name])
                args_v1.extend(v2_arg_exceptions)
                for new_arg in new_args:
                    self.assertIn(new_arg, args_v1, "Invalid argument '%s' in 1.0 when converting\n%s\nto\n%s.\nSupported arguments: %s" % (new_arg, text_input, text, str(args_v1)))
    visitor = public_api.PublicAPIVisitor(conversion_visitor)
    visitor.do_not_descend_map['tf'].append('contrib')
    visitor.private_map['tf.compat'] = ['v1', 'v2']
    traverse.traverse(tf.compat.v1, visitor)

def consume_prefix_in_state_dict_if_present(state_dict: dict[str, Any], prefix: str) -> None:
    """Strip the prefix in state_dict in place, if any.

    .. note::
        Given a `state_dict` from a DP/DDP model, a local model can load it by applying
        `consume_prefix_in_state_dict_if_present(state_dict, "module.")` before calling
        :meth:`torch.nn.Module.load_state_dict`.

    Args:
        state_dict (OrderedDict): a state-dict to be loaded to the model.
        prefix (str): prefix.
    """
    keys = list(state_dict.keys())
    for key in keys:
        if <MASK>:
            newkey = key[len(prefix):]
            state_dict[newkey] = state_dict.pop(key)
    if hasattr(state_dict, '_metadata'):
        keys = list(state_dict._metadata.keys())
        for key in keys:
            if len(key) == 0:
                continue
            if key == prefix.replace('.', '') or key.startswith(prefix):
                newkey = key[len(prefix):]
                state_dict._metadata[newkey] = state_dict._metadata.pop(key)

def __str__(self) -> str:
    namespace_prefix = f'{self.namespace}::' if self.namespace else ''
    if <MASK>:
        i = 'i' if self.inplace else ''
        return f'{namespace_prefix}__{i}{self.base}__'
    else:
        i = '_' if self.inplace else '_functional' if self.functional_overload else ''
        return f'{namespace_prefix}{self.base}{i}'

def record_cross_partition_use(def_node: Node, use_node: Optional[Node]):
    from torch.fx.experimental.symbolic_shapes import free_symbols
    defined = getattr(def_node, '_fx_partition', None)
    used = getattr(use_node, '_fx_partition', None)
    log.debug('record_cross_partition_use %s (%s) %s (%s)', def_node.name, defined, use_node.name if use_node is not None else '-', used)
    if defined != used:
        if defined is not None:
            def_partition = partitions[defined]
            def_partition.outputs.setdefault(def_node.name)
            if <MASK>:
                def_partition.dependents.setdefault(used)
        if used is not None:
            use_partition = partitions[used]
            use_partition.inputs.setdefault(def_node.name)
            if (def_val := def_node.meta.get('example_value')) is not None:
                for s in sorted(free_symbols(def_val), key=str):
                    s_node = symbol_to_node[s]
                    use_partition.inputs.setdefault(s_node.name)
                    if symbol_to_node[s].op != 'placeholder':
                        s_defined = getattr(s_node, '_fx_partition', None)
                        if s_defined is not None:
                            s_def_partition = partitions[s_defined]
                            s_def_partition.outputs.setdefault(s_node.name)
                            s_def_partition.dependents.setdefault(used)
                            use_partition.dependencies.setdefault(s_defined)
            if defined is not None:
                use_partition.dependencies.setdefault(defined)

@keep_lazy_text
def strip_tags(value):
    """Return the given HTML with all tags stripped."""
    value = str(value)
    for long_open_tag in long_open_tag_without_closing_re.finditer(value):
        if long_open_tag.group().count('<') >= MAX_STRIP_TAGS_DEPTH:
            raise SuspiciousOperation
    strip_tags_depth = 0
    while '<' in value and '>' in value:
        if <MASK>:
            raise SuspiciousOperation
        new_value = _strip_once(value)
        if value.count('<') == new_value.count('<'):
            break
        value = new_value
        strip_tags_depth += 1
    return value

def infer_dtype_from_scalar(val) -> tuple[DtypeObj, Any]:
    """
    Interpret the dtype from a scalar.

    Parameters
    ----------
    val : object
    """
    dtype: DtypeObj = _dtype_obj
    if isinstance(val, np.ndarray):
        if val.ndim != 0:
            msg = 'invalid ndarray passed to infer_dtype_from_scalar'
            raise ValueError(msg)
        dtype = val.dtype
        val = lib.item_from_zerodim(val)
    elif isinstance(val, str):
        dtype = _dtype_obj
        if using_string_dtype():
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
    elif isinstance(val, (np.datetime64, dt.datetime)):
        try:
            val = Timestamp(val)
        except OutOfBoundsDatetime:
            return (_dtype_obj, val)
        if val is NaT or val.tz is None:
            val = val.to_datetime64()
            dtype = val.dtype
        else:
            dtype = DatetimeTZDtype(unit=val.unit, tz=val.tz)
    elif isinstance(val, (np.timedelta64, dt.timedelta)):
        try:
            val = Timedelta(val)
        except (OutOfBoundsTimedelta, OverflowError):
            dtype = _dtype_obj
        else:
            if val is NaT:
                val = np.timedelta64('NaT', 'ns')
            else:
                val = val.asm8
            dtype = val.dtype
    elif is_bool(val):
        dtype = np.dtype(np.bool_)
    elif is_integer(val):
        if isinstance(val, np.integer):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.int64)
        try:
            np.array(val, dtype=dtype)
        except OverflowError:
            dtype = np.array(val).dtype
    elif <MASK>:
        if isinstance(val, np.floating):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.float64)
    elif is_complex(val):
        dtype = np.dtype(np.complex128)
    if isinstance(val, Period):
        dtype = PeriodDtype(freq=val.freq)
    elif isinstance(val, Interval):
        subtype = infer_dtype_from_scalar(val.left)[0]
        dtype = IntervalDtype(subtype=subtype, closed=val.closed)
    return (dtype, val)

@classmethod
def _multilayer_wrap_loader(cls, loader: Callable[..., OpsValue], reduction_ranges: Sequence[_IntLike], reduction_numel: _IntLike, split: _IntLike, block_size: _IntLike, default: Union[_NumLike, Sequence[_NumLike]], input_node: Optional[IRNode]=None) -> Callable[..., object]:
    dense_index = cls.check_for_split_dense_dim_reindexing(reduction_numel, input_node)
    reindex = View.dynamic_reshape_indexer(reduction_ranges, [reduction_numel], dense_index)
    need_mask = not V.graph.sizevars.statically_known_true(sympy.Eq(reduction_numel % split, 0))

    def wrapper_fn(index: Sequence[Symbol], reduction_index: Sequence[Symbol]) -> OpsValue:
        (reduction_index,) = reduction_index
        (*new_index, reduction_block) = index
        indices = block_size * reduction_block + reduction_index

        def body() -> OpsValue:
            return loader(new_index, reindex([indices]))
        if <MASK>:
            index_dtype = dtype_from_size(reduction_numel)
            mask = ops.lt(ops.index_expr(indices, index_dtype), ops.index_expr(reduction_numel, index_dtype))
            return ops.masked(mask, body, default)
        else:
            return body()
    return wrapper_fn

def as_term_coeff(obj):
    """Return expression as term-coefficient pair.
    """
    if isinstance(obj, Expr):
        obj = normalize(obj)
        if obj.op is Op.INTEGER:
            return (as_integer(1, obj.data[1]), obj.data[0])
        if obj.op is Op.REAL:
            return (as_real(1, obj.data[1]), obj.data[0])
        if obj.op is Op.TERMS:
            if <MASK>:
                ((term, coeff),) = obj.data.items()
                return (term, coeff)
        if obj.op is Op.APPLY and obj.data[0] is ArithOp.DIV:
            (t, c) = as_term_coeff(obj.data[1][0])
            return (as_apply(ArithOp.DIV, t, obj.data[1][1]), c)
        return (obj, 1)
    raise OpError(f'cannot convert {type(obj)} to term and coeff')

@final
def _validate_index_level(self, level) -> None:
    """
        Validate index level.

        For single-level Index getting level number is a no-op, but some
        verification must be done like in MultiIndex.

        """
    if isinstance(level, int):
        if <MASK>:
            raise IndexError(f'Too many levels: Index has only 1 level, {level} is not a valid level number')
        if level > 0:
            raise IndexError(f'Too many levels: Index has only 1 level, not {level + 1}')
    elif level != self.name:
        raise KeyError(f'Requested level ({level}) does not match index name ({self.name})')

def get_format(format_type, lang=None, use_l10n=None):
    """
    For a specific format type, return the format for the current
    language (locale). Default to the format in the settings.
    format_type is the name of the format, e.g. 'DATE_FORMAT'.

    If use_l10n is provided and is not None, it forces the value to
    be localized (or not), otherwise it's always localized.
    """
    if use_l10n is None:
        use_l10n = True
    if use_l10n and lang is None:
        lang = get_language()
    format_type = str(format_type)
    cache_key = (format_type, lang)
    try:
        return _format_cache[cache_key]
    except KeyError:
        pass
    val = None
    if use_l10n:
        for module in get_format_modules(lang):
            val = getattr(module, format_type, None)
            if val is not None:
                break
    if <MASK>:
        if format_type not in FORMAT_SETTINGS:
            return format_type
        val = getattr(settings, format_type)
    elif format_type in ISO_INPUT_FORMATS:
        val = list(val)
        for iso_input in ISO_INPUT_FORMATS.get(format_type, ()):
            if iso_input not in val:
                val.append(iso_input)
    _format_cache[cache_key] = val
    return val

def deprecated_wrapper(func):
    """Deprecation decorator."""
    decorator_utils.validate_callable(func, 'deprecated_arg_values')

    @functools.wraps(func)
    def new_func(*args, **kwargs):
        """Deprecation wrapper."""
        if _PRINT_DEPRECATION_WARNINGS:
            named_args = tf_inspect.getcallargs(func, *args, **kwargs)
            for (arg_name, arg_value) in deprecated_kwargs.items():
                if arg_name in named_args and _safe_eq(named_args[arg_name], arg_value):
                    if (func, arg_name) not in _PRINTED_WARNING:
                        if <MASK>:
                            _PRINTED_WARNING[func, arg_name] = True
                        _log_deprecation('From %s: calling %s (from %s) with %s=%s is deprecated and will be removed %s.\nInstructions for updating:\n%s', _call_location(), decorator_utils.get_qualified_name(func), func.__module__, arg_name, arg_value, 'in a future version' if date is None else 'after %s' % date, instructions)
        return func(*args, **kwargs)
    doc = _add_deprecated_arg_value_notice_to_docstring(func.__doc__, date, instructions, deprecated_kwargs)
    return tf_decorator.make_decorator(func, new_func, 'deprecated', doc)

def validate(self, model, instance, exclude=None, using=DEFAULT_DB_ALIAS):
    queryset = model._default_manager.using(using)
    if self.fields:
        lookup_kwargs = {}
        generated_field_names = []
        for field_name in self.fields:
            if exclude and field_name in exclude:
                return
            field = model._meta.get_field(field_name)
            if field.generated:
                if exclude and self._expression_refs_exclude(model, field.expression, exclude):
                    return
                generated_field_names.append(field.name)
            else:
                lookup_value = getattr(instance, field.attname)
                if self.nulls_distinct is not False and lookup_value is None or (lookup_value == '' and connections[using].features.interprets_empty_strings_as_nulls):
                    return
                lookup_kwargs[field.name] = lookup_value
        lookup_args = []
        if generated_field_names:
            field_expression_map = instance._get_field_expression_map(meta=model._meta, exclude=exclude)
            for field_name in generated_field_names:
                expression = field_expression_map[field_name]
                if self.nulls_distinct is False:
                    lhs = F(field_name)
                    condition = Q(Exact(lhs, expression)) | Q(IsNull(lhs, True), IsNull(expression, True))
                    lookup_args.append(condition)
                else:
                    lookup_kwargs[field_name] = expression
        queryset = queryset.filter(*lookup_args, **lookup_kwargs)
    else:
        if exclude and any((self._expression_refs_exclude(model, expression, exclude) for expression in self.expressions)):
            return
        replacements = {F(field): value for (field, value) in instance._get_field_expression_map(meta=model._meta, exclude=exclude).items()}
        filters = []
        for expr in self.expressions:
            if hasattr(expr, 'get_expression_for_validation'):
                expr = expr.get_expression_for_validation()
            rhs = expr.replace_expressions(replacements)
            condition = Exact(expr, rhs)
            if self.nulls_distinct is False:
                condition = Q(condition) | Q(IsNull(expr, True), IsNull(rhs, True))
            filters.append(condition)
        queryset = queryset.filter(*filters)
    model_class_pk = instance._get_pk_val(model._meta)
    if not instance._state.adding and instance._is_pk_set(model._meta):
        queryset = queryset.exclude(pk=model_class_pk)
    if <MASK>:
        if queryset.exists():
            if self.fields and self.violation_error_message == self.default_violation_error_message:
                validation_error_message = instance.unique_error_message(model, self.fields)
                raise ValidationError(validation_error_message, code=validation_error_message.code)
            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)
    else:
        if exclude and self._expression_refs_exclude(model, self.condition, exclude):
            return
        against = instance._get_field_expression_map(meta=model._meta, exclude=exclude)
        if (self.condition & Exists(queryset.filter(self.condition))).check(against, using=using):
            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)

def using(self, *, priority=None, queue_name=None, run_after=None, backend=None):
    """Create a new Task with modified defaults."""
    changes = {}
    if <MASK>:
        changes['priority'] = priority
    if queue_name is not None:
        changes['queue_name'] = queue_name
    if run_after is not None:
        changes['run_after'] = run_after
    if backend is not None:
        changes['backend'] = backend
    return replace(self, **changes)

def val_to_arg_str(self, s, type_=None):
    from torch.utils._triton import has_triton_package
    if has_triton_package():
        import triton
    if isinstance(s, SymTypes):
        return pexpr(s.node.expr)
    elif isinstance(s, sympy.Expr):
        return pexpr(s)
    elif isinstance(s, (tuple, list)):

        @dataclasses.dataclass
        class Shim:
            ref: Any

            def __repr__(self):
                return self.ref
        return repr(type(s)((Shim(PythonWrapperCodegen.val_to_arg_str(self, a)) for a in s)))
    elif isinstance(s, torch._ops.OpOverload):
        return _get_qualified_name(s)
    elif <MASK>:
        return s.codegen_reference()
    elif has_triton_package() and isinstance(s, triton.language.dtype):
        return repr(s)
    elif isinstance(s, ir.GeneratorState):
        return s.codegen_reference()
    else:
        return repr(s)

def expr2name(a, block, args=[]):
    orig_a = a
    a_is_expr = not analyzeargs_re_1.match(a)
    if a_is_expr:
        (implicitrules, attrrules) = buildimplicitrules(block)
        at = determineexprtype(a, block['vars'], implicitrules)
        na = 'e_'
        for c in a:
            c = c.lower()
            if <MASK>:
                c = '_'
            na = na + c
        if na[-1] == '_':
            na = na + 'e'
        else:
            na = na + '_e'
        a = na
        while a in block['vars'] or a in block['args']:
            a = a + 'r'
    if a in args:
        k = 1
        while a + str(k) in args:
            k = k + 1
        a = a + str(k)
    if a_is_expr:
        block['vars'][a] = at
    else:
        if a not in block['vars']:
            block['vars'][a] = block['vars'].get(orig_a, {})
        if 'externals' in block and orig_a in block['externals'] + block['interfaced']:
            block['vars'][a] = setattrspec(block['vars'][a], 'external')
    return a

def _tensor_debug_string(tensor, attributes) -> str:
    """Convert tensor to debug string representation."""
    if isinstance(tensor, torch.Tensor):
        tensor_debug_str = f'{dtype_abbrs[tensor.dtype]}{_stringify_shape(tensor.shape)}{_stringify_attributes(tensor, attributes)}'
        if <MASK>:
            return f'dt: {tensor_debug_str}| {_stringify_dtensor_spec(tensor._spec)}'
        elif isinstance(tensor, FakeTensor):
            return f'ft: {tensor_debug_str}'
        else:
            return f't: {tensor_debug_str}'
    else:
        raise RuntimeError(f'Unsupported tensor type: {type(tensor)}')

@staticmethod
def check_axis_name_return_reason(name: str, allow_underscore: bool=False) -> tuple[bool, str]:
    """Check if the given axis name is valid, and a message explaining why if not.

        Valid axes names are python identifiers except keywords, and should not start or end with an underscore.

        Args:
            name (str): the axis name to check
            allow_underscore (bool): whether axis names are allowed to start with an underscore

        Returns:
            tuple[bool, str]: whether the axis name is valid, a message explaining why if not
        """
    if not str.isidentifier(name):
        return (False, 'not a valid python identifier')
    elif name[0] == '_' or name[-1] == '_':
        if name == '_' and allow_underscore:
            return (True, '')
        return (False, 'axis name should should not start or end with underscore')
    else:
        if <MASK>:
            warnings.warn(f'It is discouraged to use axes names that are keywords: {name}', RuntimeWarning)
        if name in ['axis']:
            warnings.warn("It is discouraged to use 'axis' as an axis name and will raise an error in future", FutureWarning)
        return (True, '')

def _get_code_source(code: types.CodeType) -> tuple[str, str]:
    """
    Given a code object, return a fully qualified name which will be used as
    a serialized handle to access the code object from the new process.
    This is normally a straightforward process, but there are some corner cases:
    1. When a function is defined with decorator, then this function will be captured
       inside a closure with the wrapper object.
    2. When a function is defined as a nested function, then the code object will be
       stored on the co_consts field of the parent code object by Python compiler.
    This function handles all of the corner cases above.
    """
    module = inspect.getmodule(code)
    if module is None:
        raise PackageError(f'Cannot find module for code {code}')
    toplevel: Any = module
    if sys.version_info >= (3, 11):
        parts = code.co_qualname.split('.')
        for part in parts:
            if not hasattr(toplevel, part):
                _raise_resolution_error(code, toplevel)
            toplevel = getattr(toplevel, part)
            if inspect.isfunction(toplevel):
                break
    seen = set()

    def _find_code_source(obj: Any) -> Optional[str]:
        nonlocal toplevel
        nonlocal seen
        if obj in seen:
            return None
        seen.add(obj)
        if inspect.iscode(obj):
            if obj is code:
                return ''
            for (i, const) in enumerate(obj.co_consts):
                if (res := _find_code_source(const)) is not None:
                    return f'.co_consts[{i}]{res}'
        if inspect.isfunction(obj):
            if (res := _find_code_source(obj.__code__)) is not None:
                toplevel = obj
                return f'.__code__{res}'
            if obj.__closure__ is not None:
                for (i, cell) in enumerate(obj.__closure__):
                    try:
                        cell_contents = cell.cell_contents
                    except ValueError:
                        continue
                    if not (inspect.isfunction(cell_contents) or inspect.iscode(cell_contents)):
                        continue
                    if (res := _find_code_source(cell_contents)) is not None:
                        toplevel = obj
                        return f'.__closure__[{i}].cell_contents{res}'
        if sys.version_info < (3, 11):
            if inspect.ismodule(obj):
                for value in obj.__dict__.values():
                    if <MASK>:
                        continue
                    if (res := _find_code_source(value)) is not None:
                        return res
            if inspect.isclass(obj):
                for (name, value) in obj.__dict__.items():
                    value = getattr(obj, name)
                    if not (inspect.isfunction(value) or inspect.isclass(value)):
                        continue
                    if (res := _find_code_source(value)) is not None:
                        if value.__name__ != name:
                            _raise_resolution_error(code, toplevel)
                        return res
        return None
    code_source = _find_code_source(toplevel)
    if code_source is None:
        _raise_resolution_error(code, toplevel)
    return (toplevel.__qualname__, code_source.strip('.'))

def can_reuse_whl(args: argparse.Namespace) -> tuple[bool, str]:
    if args.github_ref and any((args.github_ref.startswith(x) for x in ['refs/heads/release', 'refs/tags/v', 'refs/heads/nightly'])):
        print('Release branch, rebuild whl')
        return (False, 'Release branch')
    if not check_changed_files(get_merge_base()):
        print('Cannot use old whl due to the changed files, rebuild whl')
        return (False, 'Changed files not allowed')
    if check_labels_for_pr():
        print(f'Found {FORCE_REBUILD_LABEL} label on PR, rebuild whl')
        return (False, 'Found FORCE_REBUILD_LABEL on PR')
    if check_issue_open():
        print('Issue #153759 is open, rebuild whl')
        return (False, 'Issue #153759 is open')
    workflow_id = get_workflow_id(args.run_id)
    if workflow_id is None:
        print('No workflow ID found, rebuild whl')
        return (False, 'No workflow ID found')
    if <MASK>:
        print('No old whl found, rebuild whl')
        return (False, 'No old whl found')
    return (True, 'Found old whl')

def register_fake_class(qualname, fake_class: Optional[HasStaticMethodFromReal]=None):
    """Register a fake implementation for this class.

    It's in the same spirit of registering a fake implementation for
    an operator but with the difference that it
    associates a fake class with the original torch bind class (registered
    with torch::class_). In this way, torch.compile can handle them properly
    in components such as Dynamo and AOTAutograd.

    This API may be used as a decorator (see example). For the fake class, users
    are required to provide a from_real classmethod that takes a real object and
    returns an instance of the fake class. All tensors in the fake object should also
    be properly fakified with to_fake_tensor() in from_real.


    Examples:
        # For a custom class Foo defined in test_custom_class_registration.cpp:

        TORCH_LIBRARY(_TorchScriptTesting, m) {
          m.class_<TensorQueue>("_TensorQueue")
            .def(torch::init<at::Tensor>())
            .def("push", &TensorQueue::push)
            .def("pop", &TensorQueue::pop)
            .def("top", &TensorQueue::top)
            .def("size", &TensorQueue::size)
            .def("clone_queue", &TensorQueue::clone_queue)
            .def("__obj_flatten__", &TensorQueue::__obj_flatten__)
            .def_pickle(
                // __getstate__
                [](const c10::intrusive_ptr<TensorQueue>& self)
                    -> c10::Dict<std::string, at::Tensor> {
                  return self->serialize();
                },
                // __setstate__
                [](c10::Dict<std::string, at::Tensor> data)
                    -> c10::intrusive_ptr<TensorQueue> {
                  return c10::make_intrusive<TensorQueue>(std::move(data));
                });
            };
        # We could register a fake class FakeTensorQueue in Python as follows:
        import torch

        @torch._library.register_fake_class("_TorchScriptTesting::_TensorQueue")
        class FakeTensorQueue:
            def __init__(self, queue):
                self.queue = queue

            @classmethod
            def __obj_unflatten__(cls, flattened_ctx):
                return cls(**dict(ctx))

            def push(self, x):
                self.queue.append(x)

            def pop(self):
                return self.queue.pop(0)

            def size(self):
                return len(self.queue)

    In this example, the original TensorQeue need to add a __obj_flatten__ method
    to the class TensorQueue and the flattened result is passed into FakeTensorQueue's
    __obj_unflatten__ as inputs to create a fake class. This protocol allows pytorch to look
    at the contents of the script object and properly handle them in the subsystems
    like dynamo, aot_aotugrad or more.
    """

    def inner(fake_class: HasStaticMethodFromReal):
        (ns, name) = parse_namespace(qualname)
        torch._C._get_custom_class_python_wrapper(ns, name)
        from_method = getattr(fake_class, _CONVERT_FROM_REAL_NAME, None)
        if not from_method:
            raise RuntimeError(f"{fake_class} doesn't define a classmethod {_CONVERT_FROM_REAL_NAME}.")
        if not isinstance(fake_class.__dict__[_CONVERT_FROM_REAL_NAME], classmethod):
            raise RuntimeError(f'{_CONVERT_FROM_REAL_NAME} method is not a classmethod.')
        global_fake_class_registry.register(_full_qual_class_name(qualname), fake_class)
        return fake_class
    if <MASK>:
        return inner
    return inner(fake_class)

def _ensure_data(values: ArrayLike) -> np.ndarray:
    """
    routine to ensure that our data is of the correct
    input dtype for lower-level routines

    This will coerce:
    - ints -> int64
    - uint -> uint64
    - bool -> uint8
    - datetimelike -> i8
    - datetime64tz -> i8 (in local tz)
    - categorical -> codes

    Parameters
    ----------
    values : np.ndarray or ExtensionArray

    Returns
    -------
    np.ndarray
    """
    if not isinstance(values, ABCMultiIndex):
        values = extract_array(values, extract_numpy=True)
    if is_object_dtype(values.dtype):
        return ensure_object(np.asarray(values))
    elif isinstance(values.dtype, BaseMaskedDtype):
        values = cast('BaseMaskedArray', values)
        if not values._hasna:
            return _ensure_data(values._data)
        return np.asarray(values)
    elif isinstance(values.dtype, CategoricalDtype):
        values = cast('Categorical', values)
        return values.codes
    elif is_bool_dtype(values.dtype):
        if isinstance(values, np.ndarray):
            return np.asarray(values).view('uint8')
        else:
            return np.asarray(values).astype('uint8', copy=False)
    elif is_integer_dtype(values.dtype):
        return np.asarray(values)
    elif is_float_dtype(values.dtype):
        if <MASK>:
            return ensure_float64(values)
        return np.asarray(values)
    elif is_complex_dtype(values.dtype):
        return cast(np.ndarray, values)
    elif needs_i8_conversion(values.dtype):
        npvalues = values.view('i8')
        npvalues = cast(np.ndarray, npvalues)
        return npvalues
    values = np.asarray(values, dtype=object)
    return ensure_object(values)

def rank_output(out) -> tuple[int, Optional[str], int]:
    (idx, (_arg, spec)) = out
    assert isinstance(spec, OutputSpec)
    if spec.type == 'user_output':
        return (4, None, idx)
    elif spec.type == 'loss_output':
        return (4, None, idx)
    elif spec.type == 'parameter_mutation':
        return (1, spec.parameter_mutation.parameter_name, idx)
    elif spec.type == 'buffer_mutation':
        return (2, spec.buffer_mutation.buffer_name, idx)
    elif spec.type == 'gradient_to_parameter':
        return (5, spec.gradient_to_parameter.parameter_name, idx)
    elif spec.type == 'gradient_to_user_input':
        return (6, None, idx)
    elif <MASK>:
        return (3, None, idx)
    elif spec.type == 'token':
        return (0, None, idx)
    else:
        raise AssertionError(f'Unknown output type: {spec}')

def get_input_shape_and_dtype(layer):
    """Retrieves input shape and input dtype of layer if applicable.

  Args:
    layer: Layer (or model) instance.

  Returns:
    Tuple (input_shape, input_dtype). Both could be None if the layer
      does not have a defined input shape.

  Raises:
    ValueError: in case an empty Sequential or Functional model is passed.
  """

    def _is_graph_model(layer):
        return hasattr(layer, '_is_graph_network') and layer._is_graph_network or layer.__class__.__name__ == 'Sequential'
    while _is_graph_model(layer):
        if <MASK>:
            raise ValueError('An empty Model cannot be used as a Layer.')
        layer = layer.layers[0]
    if getattr(layer, '_batch_input_shape', None):
        return (layer._batch_input_shape, layer.dtype)
    return (None, None)

@override
def __call__(self, args: Sequence[Any]) -> Any:
    self._check_and_switch_progression()
    if self._optimized_output_code is not None:
        _ProgressiveFxCompile._stat_optimized_runs += 1
        output_code = self._optimized_output_code
    else:
        _ProgressiveFxCompile._stat_fast_runs += 1
        assert self._fast_output_code is not None
        output_code = self._fast_output_code
    boxed_call = getattr(output_code, '_boxed_call', False)
    if <MASK>:
        res = output_code.__call__(args)
    else:
        res = output_code.__call__(*args)
    return res

def describe_numeric_1d(series: Series, percentiles: Sequence[float]) -> Series:
    """Describe series containing numerical data.

    Parameters
    ----------
    series : Series
        Series to be described.
    percentiles : list-like of numbers
        The percentiles to include in the output.
    """
    from pandas import Series
    formatted_percentiles = format_percentiles(percentiles)
    if len(percentiles) == 0:
        quantiles = []
    else:
        quantiles = series.quantile(percentiles).tolist()
    stat_index = ['count', 'mean', 'std', 'min'] + formatted_percentiles + ['max']
    d = [series.count(), series.mean(), series.std(), series.min()] + quantiles + [series.max()]
    dtype: DtypeObj | None
    if <MASK>:
        if isinstance(series.dtype, ArrowDtype):
            if series.dtype.kind == 'm':
                dtype = None
            else:
                import pyarrow as pa
                dtype = ArrowDtype(pa.float64())
        else:
            dtype = Float64Dtype()
    elif series.dtype.kind in 'iufb':
        dtype = np.dtype('float')
    else:
        dtype = None
    return Series(d, index=stat_index, name=series.name, dtype=dtype)

@contextlib.contextmanager
def _reparametrize_module(module: 'torch.nn.Module', parameters_and_buffers: dict[str, Tensor], tie_weights: bool=False, strict: bool=False, stack_weights: bool=False):
    if tie_weights:
        untied_parameters_and_buffers = _untie_named_tensors_map(module, parameters_and_buffers)
    else:
        untied_parameters_and_buffers = parameters_and_buffers
    accessor = NamedMemberAccessor(module)
    if <MASK>:
        (missing_keys, unexpected_keys) = accessor.check_keys(untied_parameters_and_buffers)
        error_msgs = []
        if len(unexpected_keys) > 0:
            error_msgs.append(f"Unexpected key(s): {', '.join(map(repr, unexpected_keys))}.")
        if len(missing_keys) > 0:
            error_msgs.append(f"Missing key(s): {', '.join(map(repr, missing_keys))}.")
        if len(error_msgs) > 0:
            raise RuntimeError('Error(s) in reparametrizing for {}:\n\t{}'.format(module._get_name(), '\n\t'.join(error_msgs)))
    orig_parameters_and_buffers: dict[str, Tensor] = {}
    try:
        (orig_parameters_and_buffers, _) = accessor.swap_tensors_dict(untied_parameters_and_buffers, allow_missing=True)
        yield
    finally:
        if stack_weights:
            orig_parameters_and_buffers = dict(reversed(orig_parameters_and_buffers.items()))
        (new_parameters_and_buffers, _) = accessor.swap_tensors_dict(orig_parameters_and_buffers, allow_missing=True)
        parameters_and_buffers.update({k: new_parameters_and_buffers[k] for k in parameters_and_buffers if k in new_parameters_and_buffers})

def filter_op(self, op: 'CKGroupedConvFwdOp'):
    metas = [T.get_layout() for T in [*self.input_nodes, self.output_node] if T is not None]
    X_meta = metas[0]
    W_meta = metas[1]
    Y_meta = metas[-1]
    if op.a_element_dtype != self._TORCH_DTYPE_TO_CK[X_meta.dtype]:
        return None
    if <MASK>:
        return None
    if op.e_element_dtype != self._TORCH_DTYPE_TO_CK[Y_meta.dtype]:
        return None
    if op.a_layout != torch_layout_to_ck_input_layout(X_meta):
        return None
    if op.b_layout != torch_layout_to_ck_weight_layout(W_meta):
        return None
    if op.e_layout != torch_layout_to_ck_output_layout(Y_meta):
        return None
    if op.n_dim_spatial != self.n_spatial_dimensions:
        return None
    if 'Default' not in op.conv_forward_specialization:
        return None
    return op

def _as_index(idx, need_scalar=True):
    """Helper function to parse idx as an index.

  Args:
    idx: index
    need_scalar: If idx needs to be a scalar value.

  Returns:
    A pair, (indx, bool). First one is the parsed index and can be a tensor,
    or scalar integer / Dimension. Second one is True if rank is known to be 0.

  Raises:
    IndexError: For incorrect indices.
  """
    if isinstance(idx, (numbers.Integral, tensor_shape.Dimension)):
        return (idx, True)
    data = asarray(idx)
    if data.dtype == dtypes.bool:
        if data.shape.ndims != 1:
            raise NotImplementedError('Need rank 1 for bool index %s' % idx)
        data = array_ops.where_v2(data)
        data = array_ops.reshape(data, [-1])
    if <MASK>:
        raise IndexError(_SLICE_ERROR + ', got {!r}'.format(idx))
    np_dtype = data.dtype.as_numpy_dtype
    if not np.issubdtype(np_dtype, np.integer):
        raise IndexError(_SLICE_ERROR + ', got {!r}'.format(idx))
    if data.dtype not in (dtypes.int64, dtypes.int32):
        promoted_dtype = np.promote_types(np.int32, np_dtype)
        if promoted_dtype == np.int32:
            data = math_ops.cast(data, dtypes.int32)
        elif promoted_dtype == np.int64:
            data = math_ops.cast(data, dtypes.int64)
        else:
            raise IndexError(_SLICE_ERROR + ', got {!r}'.format(idx))
    return (data, data.shape.rank == 0)

def spawn(cmd):
    src_regex = re.compile('/T(p|c)(.*)')
    src_list = [m.group(2) for m in (src_regex.match(elem) for elem in cmd) if m]
    obj_regex = re.compile('/Fo(.*)')
    obj_list = [m.group(1) for m in (obj_regex.match(elem) for elem in cmd) if m]
    include_regex = re.compile('((\\-|\\/)I.*)')
    include_list = [m.group(1) for m in (include_regex.match(elem) for elem in cmd) if m]
    if len(src_list) >= 1 and len(obj_list) >= 1:
        src = src_list[0]
        obj = obj_list[0]
        if _is_cuda_file(src):
            if IS_HIP_EXTENSION:
                nvcc = _get_hipcc_path()
            else:
                nvcc = _join_cuda_home('bin', 'nvcc')
            if isinstance(self.cflags, dict):
                cflags = self.cflags['nvcc']
            elif <MASK>:
                cflags = self.cflags
            else:
                cflags = []
            if IS_HIP_EXTENSION:
                cflags = win_hip_flags(cflags)
            else:
                cflags = win_cuda_flags(cflags) + ['-std=c++17', '--use-local-env']
                for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                    cflags = ['-Xcudafe', '--diag_suppress=' + ignore_warning] + cflags
            for flag in COMMON_MSVC_FLAGS:
                cflags = ['-Xcompiler', flag] + cflags
            cmd = [nvcc, '-c', src, '-o', obj] + include_list + cflags
        elif isinstance(self.cflags, dict):
            cflags = COMMON_MSVC_FLAGS + self.cflags['cxx']
            append_std17_if_no_std_present(cflags)
            cmd += cflags
        elif isinstance(self.cflags, list):
            cflags = COMMON_MSVC_FLAGS + self.cflags
            append_std17_if_no_std_present(cflags)
            cmd += cflags
    return original_spawn(cmd)

def constant_to_optimal_zero(self, y_true, sample_weight=None):
    if <MASK>:
        return HalfSquaredError().constant_to_optimal_zero(y_true=y_true, sample_weight=sample_weight)
    elif self.closs.power == 1:
        return HalfPoissonLoss().constant_to_optimal_zero(y_true=y_true, sample_weight=sample_weight)
    elif self.closs.power == 2:
        return HalfGammaLoss().constant_to_optimal_zero(y_true=y_true, sample_weight=sample_weight)
    else:
        p = self.closs.power
        term = np.power(np.maximum(y_true, 0), 2 - p) / (1 - p) / (2 - p)
        if sample_weight is not None:
            term *= sample_weight
        return term

def should_ban_recomputation(node):
    if node.op != 'call_function':
        return False
    if node.target == operator.getitem:
        return False
    if node.meta.get('recompute', None) == CheckpointPolicy.MUST_SAVE:
        return True
    if config.recompute_views and op_types.is_view(node):
        return False
    if node.target in [aten.lift_fresh_copy.default, aten.lift_fresh.default]:
        return False
    if min_cut_options.ban_if_not_in_allowlist:
        if <MASK>:
            return True
    elif op_types.is_random(node) or op_types.is_compute_intensive(node):
        return True
    if min_cut_options.ban_if_materialized_backward and is_materialized_backwards(node):
        log.debug('materialized backwards: %s %s', node, tuple(node.users))
        return True
    if node.dist_from_bw < 1000 and node.dist_from_bw > config.max_dist_from_bw:
        return True
    if min_cut_options.ban_if_reduction:
        input_tensors_size = sum((_size_of(i) for i in node.args if isinstance(i, fx.Node)))
        output_size = _size_of(node)
        return output_size * 4 < input_tensors_size
    return False

def _handle_multiprocessing(self, x, workers, use_multiprocessing, max_queue_size):
    if workers > 1 or (workers > 0 and use_multiprocessing):

        def generator_fn():
            self._enqueuer = data_utils.OrderedEnqueuer(x, use_multiprocessing=use_multiprocessing, shuffle=self._shuffle_sequence)
            self._enqueuer.start(workers=workers, max_queue_size=max_queue_size)
            return self._enqueuer.get()
    else:

        def generator_fn():
            order = range(len(x))
            if <MASK>:
                order = list(order)
                random.shuffle(order)
            for i in order:
                yield x[i]
    return generator_fn

def _infer_reduce_dims_map(reduction_dims: list[int], input_ndim: int, keep_dim=False) -> list[int]:
    reduction_dims_map = []
    new_dim_count = 0
    for input_dim in range(input_ndim):
        if <MASK>:
            reduction_dims_map.append(-1)
        else:
            reduction_dims_map.append(new_dim_count)
            new_dim_count += 1
    return reduction_dims_map

def is_mutated_later_in_fw(node):
    if _has_tag_is_backward(node):
        return False
    tensor_arg_aliases = [x for x in node.args if isinstance(x, fx.Node) and 'val' in x.meta and isinstance(x.meta['val'], torch.Tensor)]
    while len(tensor_arg_aliases) > 0:
        a = tensor_arg_aliases.pop()
        for u in a.users:
            if not isinstance(u.target, torch._ops.OpOverload):
                continue
            if u.target._schema.is_mutable and order[u] > order[node] and (not (_has_tag_is_backward(u) or _has_tag_must_be_in_backward(u))):
                for (idx, alias_info) in enumerate(u.target._schema.arguments):
                    if <MASK>:
                        return True
            elif u.target.is_view:
                tensor_arg_aliases.append(u)
    return False

def _check_exclude(self, obj):
    """Check that exclude is a sequence without duplicates."""
    if <MASK>:
        return []
    elif not isinstance(obj.exclude, (list, tuple)):
        return must_be('a list or tuple', option='exclude', obj=obj, id='admin.E014')
    field_counts = collections.Counter(obj.exclude)
    if (duplicate_fields := [field for (field, count) in field_counts.items() if count > 1]):
        return [checks.Error("The value of 'exclude' contains duplicate field(s).", hint='Remove duplicates of %s.' % ', '.join(map(repr, duplicate_fields)), obj=obj.__class__, id='admin.E015')]
    else:
        return []

