def __init__(self, params: list[Tensor], lr: float=0.001, betas: tuple[float, float]=(0.9, 0.999), eps: float=1e-08, weight_decay: float=0.0, amsgrad: bool=False, maximize: bool=False, foreach: bool=False, fused: bool=False, _allow_empty_param_list: bool=False):
    _scripted_functional_optimizer_deprecation_warning(stacklevel=2)
