def load_tensor(dtype, numel, key, location):
    name = f'data/{key}'
    if torch._guards.detect_fake_mode(None) is not None:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes, device='meta')
        if can_calculate_storage_offsets:
            storage._checkpoint_offset = _get_offset(key, name, numel)
        else:
            storage._checkpoint_offset = zip_file.get_record_offset(name)
    elif _serialization_tls.skip_data:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes)
    elif overall_storage is not None:
        if can_calculate_storage_offsets and calculate_storage_offsets:
            storage_offset = _get_offset(key, name, numel)
            if run_debug_asserts:
                if storage_offset != zip_file.get_record_offset(name):
                    raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        else:
            storage_offset = zip_file.get_record_offset(name)
        storage = overall_storage[storage_offset:storage_offset + numel]
    else:
        if can_calculate_storage_offsets and run_debug_asserts:
            storage_offset = _get_offset(key, name, numel)
            if storage_offset != zip_file.get_record_offset(name):
                raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        storage = zip_file.get_storage_from_record(name, numel, torch.UntypedStorage)._typed_storage()._untyped_storage
    if byteorderdata is not None:
        if byteorderdata.decode() != sys.byteorder:
            storage.byteswap(dtype)
    if <MASK>:
        wrap_storage = restore_location(storage, location)
    else:
        storage._fake_device = location
        wrap_storage = storage
    typed_storage = torch.storage.TypedStorage(wrap_storage=wrap_storage, dtype=dtype, _internal=True)
    if typed_storage._data_ptr() != 0:
        loaded_storages[key] = typed_storage
    return typed_storage

@wraps(fn)
def wrapper(*args, **kwargs):
    assert GRAPH_EXECUTOR
    if <MASK>:
        raise unittest.SkipTest(msg)
    else:
        fn(*args, **kwargs)

def dispatch_reduction_ufunc(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    """
    Dispatch ufunc reductions to self's reduction methods.
    """
    assert method == 'reduce'
    if len(inputs) != 1 or inputs[0] is not self:
        return NotImplemented
    if ufunc.__name__ not in REDUCTION_ALIASES:
        return NotImplemented
    method_name = REDUCTION_ALIASES[ufunc.__name__]
    if <MASK>:
        return NotImplemented
    if self.ndim > 1:
        if isinstance(self, ABCNDFrame):
            kwargs['numeric_only'] = False
        if 'axis' not in kwargs:
            kwargs['axis'] = 0
    return getattr(self, method_name)(skipna=False, **kwargs)

def are_block_parameters_compatible(self, block_params: BlockParameters) -> bool:
    """
        Check if the block parameters are valid for TMA.
        If force, we allow relying on symbolic hints equivalent
        to what we check for Triton templates.
        """
    if self.force:
        strides = [V.graph.sizevars.symbolic_hint(st) for st in block_params.strides]
    else:
        strides = block_params.strides
    if not V.graph.sizevars.statically_known_equals(strides[-1], sympy.Integer(1)):
        log.debug('%s TMA API requires innermost stride to be 1.', self.failed_debug_prefix)
        return False
    element_size = self.dtype.itemsize
    for stride in strides[:-1]:
        if <MASK>:
            log.debug('%s TMA API requires outer strides to be 16 byte aligned.', self.failed_debug_prefix)
            return False
    innermost_block_shape = block_params.block_shape[-1]
    innermost_block_type = None
    innermost_block_symt = None
    for block_type_str in innermost_block_shape.free_symbols:
        for block_symt in TritonSymbols.block_types:
            if symbol_is_type(block_type_str, block_symt):
                innermost_block_type = block_type_str
                innermost_block_symt = block_symt
                break
    assert innermost_block_type and innermost_block_symt, f'{innermost_block_shape} expr must contain a single block type from {TritonSymbols.block_types}'
    if self.kernel.persistent_reduction and (not self.for_store):
        innermost_tree_prefix = prefix_str[innermost_block_symt]
        tree_numel = None
        for t in self.kernel.range_trees:
            if t.is_reduction:
                if t.prefix == innermost_tree_prefix:
                    tree_numel = t.numel
                    break
        assert tree_numel is not None
        persistent_rblock = self.kernel._get_persistent_RBLOCK(tree_numel)
        innermost_block_bytes = innermost_block_shape.subs({innermost_block_type: persistent_rblock}) * element_size
        if not V.graph.sizevars.statically_known_geq(innermost_block_bytes, sympy.Integer(16)):
            log.debug('%s persistent reduction innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    else:
        try:
            min_block_size = next_power_of_2(int(sympy.nsolve(innermost_block_shape * element_size - 16, innermost_block_type, 1)))
            block_type_str = V.kernel.index_to_str(innermost_block_type)
            if self.kernel.fixed_config:
                if min_block_size > self.kernel.fixed_config[block_type_str]:
                    log.debug('%s For block %s, fixed config block size %d is smaller than the minimum required: %d', self.failed_debug_prefix, block_type_str, self.kernel.fixed_config[block_type_str], min_block_size)
                    return False
            else:
                self.kernel.tma_min_block_sizes[block_type_str] = max(min_block_size, self.kernel.tma_min_block_sizes.get(block_type_str, 1))
        except ValueError:
            log.debug('%s innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    return True

def writable(self):
    if self.closed:
        return False
    if <MASK>:
        return self.file.writable()
    return 'w' in getattr(self.file, 'mode', '')

def _setitem_with_indexer_frame_value(self, indexer, value: DataFrame, name: str) -> None:
    ilocs = self._ensure_iterable_column_indexer(indexer[1])
    sub_indexer = list(indexer)
    pi = indexer[0]
    multiindex_indexer = isinstance(self.obj.columns, MultiIndex)
    unique_cols = value.columns.is_unique
    if name == 'iloc':
        for (i, loc) in enumerate(ilocs):
            val = value.iloc[:, i]
            self._setitem_single_column(loc, val, pi)
    elif not unique_cols and value.columns.equals(self.obj.columns):
        for loc in ilocs:
            item = self.obj.columns[loc]
            if <MASK>:
                sub_indexer[1] = item
                val = self._align_series(tuple(sub_indexer), value.iloc[:, loc], multiindex_indexer)
            else:
                val = np.nan
            self._setitem_single_column(loc, val, pi)
    elif not unique_cols:
        raise ValueError('Setting with non-unique columns is not allowed.')
    else:
        for loc in ilocs:
            item = self.obj.columns[loc]
            if item in value:
                sub_indexer[1] = item
                val = self._align_series(tuple(sub_indexer), value[item], multiindex_indexer, using_cow=True)
            else:
                val = np.nan
            self._setitem_single_column(loc, val, pi)

def emit_node(node: Node):
    maybe_type_annotation = '' if node.type is None else f' : {type_repr(node.type)}'
    maybe_comment = ''
    if verbose:
        from torch.fx.experimental.proxy_tensor import py_sym_types
        from torch.fx.passes.shape_prop import TensorMetadata
        meta_val = node.meta.get('val', node.meta.get('tensor_meta', node.meta.get('example_value', None)))

        def _tensor_annotation(t: torch.Tensor) -> str:
            stride = stringify_shape(t.stride()) if include_stride else ''
            device = f'{t.device}' if include_device else ''
            return f'{red(dtype_abbrs[t.dtype])}{blue(stringify_shape(t.shape))}{dim_blue(stride)}{dim_green(device)}'
        if isinstance(meta_val, torch.Tensor) and meta_val.layout not in (torch.sparse_csc, torch.sparse_csr):
            is_plain = type(meta_val) is torch.Tensor or isinstance(meta_val, torch._subclasses.FakeTensor)
            core = _tensor_annotation(meta_val)
            if is_plain:
                maybe_type_annotation = f': "{core}"'
            else:
                cls = meta_val.__class__.__name__
                maybe_type_annotation = f': "{cls}({core})"'
        elif isinstance(meta_val, py_sym_types):
            val_str = CodeGen._sym_repr(meta_val)
            maybe_type_annotation = f': "Sym({val_str})"'
        elif <MASK>:
            maybe_type_annotation = f': "{dtype_abbrs[meta_val.dtype]}{stringify_shape(meta_val.shape)}"'
    desc = None
    if expanded_def:
        desc = node.meta.get('desc', None)
        if desc is not None and node.op == 'placeholder':
            maybe_comment += f'  # {desc}'
    if node.op == 'placeholder':
        assert isinstance(node.target, str)
        maybe_default_arg = '' if not node.args else f' = {_get_repr(node.args[0])}'
        free_vars.append(f'{node.target}{maybe_type_annotation}{maybe_default_arg}{maybe_comment}')
        raw_name = node.target.replace('*', '')
        if raw_name != repr(node):
            body.append(f'{repr(node)} = {raw_name}\n')
        return
    elif node.op == 'call_method':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.target)}({_format_args(node.args[1:], node.kwargs)})')
        return
    elif node.op == 'call_function':
        assert callable(node.target)
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in magic_methods:
            assert isinstance(node.args, tuple)
            body.append(f'{repr(node)}{maybe_type_annotation} = {magic_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))}')
            return
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in inplace_methods:
            body.append(f'{inplace_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))};  {repr(node)}{maybe_type_annotation} = {_get_repr(node.args[0])}')
            return
        qualified_name = _get_qualified_name(node.target)
        global_name = add_global(qualified_name, node.target)
        if global_name == 'getattr' and isinstance(node.args, tuple) and isinstance(node.args[1], str) and node.args[1].isidentifier() and (len(node.args) == 2):
            body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.args[1])}')
            return
        body.append(f'{repr(node)}{maybe_type_annotation} = {global_name}({_format_args(node.args, node.kwargs)})')
        if node.meta.get('is_wrapped', False):
            wrapped_fns.setdefault(global_name)
        return
    elif node.op == 'call_module':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}({_format_args(node.args, node.kwargs)})')
        return
    elif node.op == 'get_attr':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}')
        return
    elif node.op == 'output':
        if node.type is not None:
            maybe_return_annotation[0] = f' -> {type_repr(node.type)}'
        body.append(self._call_method_with_signature_check(self.generate_output, node.args[0], descs=desc if expanded_def else None))
        return
    raise NotImplementedError(f'node: {node.op} {node.target}')

def _quantize_affine_no_dtype_cast(input: torch.Tensor, block_size: list[int], scale: torch.Tensor, zero_point: Optional[torch.Tensor], quant_min: Union[int, float], quant_max: Union[int, float], zero_point_domain: Optional[str]=ZeroPointDomain.INT.name) -> torch.Tensor:
    """
    The op does the following:
    1. figure out the dimension for reduction based on block_size, also reshape the input to align with
       the shape after reduction
    2. quantize the input based on the quantization parameters scale and zero_point and args like zero_point_domain
    3. reshape the quantized result to original shape
    """
    if <MASK>:
        raise AssertionError(f'Unsupported input dtype: {input.dtype}')
    if len(block_size) != input.dim():
        raise AssertionError(f'Got input dim:{input.dim()}, block_size: {block_size}')
    (shape_for_reduction, reduction_dims) = _get_reduction_params(block_size, input.size())
    original_shape = input.shape
    input = input.view(shape_for_reduction)
    shape_after_reduction = shape_for_reduction
    for i in reduction_dims:
        shape_after_reduction[i] = 1
    scale = scale.view(shape_after_reduction)
    if zero_point is not None:
        zero_point = zero_point.view(shape_after_reduction)
    if zero_point_domain == ZeroPointDomain.INT.name:
        quant = torch.clamp(torch.round(input * (1.0 / scale)) + zero_point, quant_min, quant_max)
    elif zero_point_domain == ZeroPointDomain.NONE.name:
        if zero_point is not None:
            raise AssertionError('zero_point should be None when zero_point_domain is NONE')
        quant = torch.clamp(torch.round(input * (1.0 / scale)), quant_min, quant_max)
    elif zero_point_domain is None:
        if zero_point is not None:
            raise AssertionError('zero_point should be None when zero_point_domain is None')
        quant = torch.clamp(input * scale.reciprocal(), quant_min, quant_max)
    else:
        if zero_point_domain != ZeroPointDomain.FLOAT.name:
            raise AssertionError(f'Unexpected zero_point_domain: {zero_point_domain}')
        mid_point = (quant_max + quant_min + 1) / 2
        min_val = zero_point - scale * mid_point
        quant = torch.clamp(torch.round((input - min_val) / scale), quant_min, quant_max)
    quant = quant.view(original_shape)
    return quant

def get_priority_info_for_test(self, test_run: TestRun) -> dict[str, Any]:
    """Given a failing test, returns information about it's prioritization that we want to emit in our metrics."""
    for (idx, (score, test)) in enumerate(self._traverse_scores()):
        if <MASK>:
            return {'position': idx, 'score': score}
    raise AssertionError(f'Test run {test_run} not found')

@functools.cmp_to_key
def index_cmp(a: int, b: int) -> int:
    if sizes[a] == 1 or sizes[b] == 1:
        return cmp(sizes[a] == 1, sizes[b] == 1)
    stride_len_a = [abs(sl[a]) for sl in stride_lengths]
    stride_len_b = [abs(sl[b]) for sl in stride_lengths]
    a_first = sum((sl_b == 0 or sl_a < sl_b for (sl_a, sl_b) in zip(stride_len_a, stride_len_b)))
    b_first = sum((sl_a == 0 or sl_b < sl_a for (sl_a, sl_b) in zip(stride_len_a, stride_len_b)))
    if <MASK>:
        return -1
    if b_first > a_first:
        return 1
    return cmp(b, a)

def _compute_device_options(self, device_type='GPU'):
    """Build the GPUOptions proto for GPU or PluggableDevice."""
    if device_type not in ['GPU', 'PluggableDevice']:
        raise ValueError('device types other than GPU and PluggableDevice are not supported.')
    visible_device_list = []
    virtual_devices = []
    device_to_indices = collections.defaultdict(int)
    memory_growths = set()
    compatible_devices = self.list_physical_devices('GPU') if device_type == 'GPU' else self._pluggable_devices
    support_virtual_devices = device_type == 'GPU'
    for dev in compatible_devices:
        device_index = device_to_indices[dev.device_type]
        device_to_indices[dev.device_type] += 1
        if dev not in self._visible_device_list:
            continue
        growth = self._memory_growth_map[dev]
        memory_growths.add(growth)
        if device_type == 'PluggableDevice':
            visible_device_list.append(dev.device_type + ':' + str(device_index))
        else:
            visible_device_list.append(str(device_index))
        if support_virtual_devices and self._virtual_device_map:
            vdevs = self._virtual_device_map.get(dev, [])
            device_ordinals = []
            device_limits = []
            priority = []
            for virt_dev in vdevs:
                if virt_dev.experimental_device_ordinal is not None:
                    device_ordinals.append(virt_dev.experimental_device_ordinal)
                device_limits.append(virt_dev.memory_limit)
                if virt_dev.experimental_priority is not None:
                    priority.append(virt_dev.experimental_priority)
            if <MASK>:
                raise ValueError('priority must be specified for all virtual devices')
            if device_ordinals and len(device_limits) != len(device_ordinals):
                raise ValueError('device_ordinals must be specified for all virtual devices')
            virtual_devices.append(config_pb2.GPUOptions.Experimental.VirtualDevices(memory_limit_mb=device_limits, priority=priority, device_ordinal=device_ordinals))
    if not virtual_devices and memory_growths:
        if len(memory_growths) > 1:
            raise ValueError('Memory growth cannot differ between GPU devices')
        allow_growth = memory_growths.pop()
    else:
        allow_growth = None
    return config_pb2.GPUOptions(allow_growth=allow_growth, visible_device_list=','.join(visible_device_list), experimental=config_pb2.GPUOptions.Experimental(virtual_devices=virtual_devices))

def object_annotation(obj):
    """
    Return a string to be used for Graphviz nodes.

    The string should be short but as informative as possible.
    """

    def format_sequence(obj):
        body = ','.join((repr(x) if isinstance(x, BASE_TYPES) else type(x).__name__ for (i, x) in zip(range(8), obj)))
        if len(obj) > 8:
            body = f'{body}, ...{len(obj) - 8}'
        return body
    if isinstance(obj, BASE_TYPES):
        return repr(obj)
    if type(obj).__name__ == 'function':
        return f'function\n{obj.__name__}'
    elif isinstance(obj, types.MethodType):
        try:
            func_name = obj.__func__.__qualname__
        except AttributeError:
            func_name = '<anonymous>'
        return f'instancemethod\n{func_name}'
    elif isinstance(obj, list):
        return f'[{format_sequence(obj)}]'
    elif isinstance(obj, tuple):
        return f'({format_sequence(obj)})'
    elif isinstance(obj, dict):
        return f'dict[{len(obj)}]'
    elif isinstance(obj, types.ModuleType):
        return f'module\n{obj.__name__}'
    elif <MASK>:
        return f'type\n{obj.__name__}'
    elif isinstance(obj, weakref.ref):
        referent = obj()
        if referent is None:
            return 'weakref (dead referent)'
        else:
            return f'weakref to id 0x{id(referent):x}'
    elif isinstance(obj, types.FrameType):
        filename = obj.f_code.co_filename
        if len(filename) > FRAME_FILENAME_LIMIT:
            filename = '...' + filename[-(FRAME_FILENAME_LIMIT - 3):]
        return f'frame\n{filename}:{obj.f_lineno}'
    else:
        return f'object\n{type(obj).__module__}.{type(obj).__name__}'

def create_c10d_store(is_server: bool, server_addr: str, server_port: int=-1, world_size: int=1, timeout: float=60 * 10, wait_for_workers: bool=True, retries=3, use_libuv: Optional[bool]=None):
    if use_libuv is not None:
        logger.warning('argument use_libuv is deprecated and ignored. Set USE_LIBUV environment variable to "0" to disable libuv, or "1" to enable it. If the env var is not set, libuv will be used by default.')
    use_libuv = os.environ.get('USE_LIBUV', '1') == '1'
    if <MASK>:
        raise ValueError(f'server_port must be specified when world_size > 1, got server_port={server_port}, world_size={world_size}')
    if server_port != -1:
        logger.info('sever_port: %s, specified, ignoring retries', server_port)
    attempt = retries if server_port == -1 else 1
    while True:
        if server_port != -1:
            port = server_port
        else:
            port = get_free_port()
        logger.info('Creating c10d store on %s:%s\n  world_size  : %s\n  is_server   : %s\n  timeout(sec): %s\n  use_libuv   : %s\n', server_addr, port, world_size, is_server, timeout, use_libuv)
        try:
            store = dist.TCPStore(host_name=server_addr, port=port, world_size=world_size, is_master=is_server, timeout=datetime.timedelta(seconds=timeout), wait_for_workers=wait_for_workers, use_libuv=use_libuv)
            if wait_for_workers:
                _check_full_rank(store, world_size, timeout=timeout)
            logger.info('Successfully created c10d store')
            return store
        except RuntimeError as e:
            if str(e) == _ADDRESS_IN_USE:
                if attempt < retries:
                    logger.warning('port: %s already in use, attempt: [%s/%s]', port, attempt, retries)
                    attempt += 1
                else:
                    raise RuntimeError(f'on {server_addr}, port: {port} already in use') from e
            else:
                raise

@final
def _check_graph_module(self, gm: torch.fx.GraphModule) -> None:

    def _allowed_getattr_types(is_toplevel_gm) -> tuple[type[Any], ...]:
        if is_toplevel_gm:
            ret = self.allowed_getattr_types()
        else:
            ret = self.allowed_getattr_types_for_subgm()
        assert not any((t is object for t in ret))
        return ret

    def _check_valid_op(op) -> None:

        def _allowed_builtin_ops() -> list:
            ret = self.allowed_builtin_ops()
            assert all((inspect.isbuiltin(op) for op in ret))
            return ret

        def _allowed_op_types() -> tuple[type[Any], ...]:
            ret = self.allowed_op_types()
