        elif box_native_indices:
            object_dtype_indices_as_set = set(box_native_indices)
            return into_c(((t[0], {column: maybe_box_native(v) if i in object_dtype_indices_as_set else v for (i, (column, v)) in enumerate(zip(columns, t[1:], strict=True))}) for t in df.itertuples(name=None)))
