@staticmethod
def default_accumulator(reduction_type: str, dtype: torch.dtype) -> Union[_NumLike, Sequence[_NumLike]]:
    if reduction_type in ('max', 'argmax'):
        if <MASK>:
            return float('-inf')
        elif is_boolean_dtype(dtype):
            return False
        else:
            return torch.iinfo(dtype).min
    if reduction_type in ('min', 'argmin'):
        if is_float_dtype(dtype):
            return float('inf')
        elif is_boolean_dtype(dtype):
            return True
        else:
            return torch.iinfo(dtype).max
    zero = False if is_boolean_dtype(dtype) else 0
    one = True if is_boolean_dtype(dtype) else 1
    return {'sum': zero, 'prod': one, 'dot': zero, 'xor_sum': zero, 'any': zero, 'welford_reduce': (zero, zero, zero), 'welford_combine': (zero, zero, zero), 'online_softmax_reduce': (float('-inf'), zero)}[reduction_type]

def ask_initial(self, app_label):
    """Should we create an initial migration for the app?"""
    if app_label in self.specified_apps:
        return True
    try:
        app_config = apps.get_app_config(app_label)
    except LookupError:
        return self.defaults.get('ask_initial', False)
    (migrations_import_path, _) = MigrationLoader.migrations_module(app_config.label)
    if <MASK>:
        return self.defaults.get('ask_initial', False)
    try:
        migrations_module = importlib.import_module(migrations_import_path)
    except ImportError:
        return self.defaults.get('ask_initial', False)
    else:
        if getattr(migrations_module, '__file__', None):
            filenames = os.listdir(os.path.dirname(migrations_module.__file__))
        elif hasattr(migrations_module, '__path__'):
            if len(migrations_module.__path__) > 1:
                return False
            filenames = os.listdir(list(migrations_module.__path__)[0])
        return not any((x.endswith('.py') for x in filenames if x != '__init__.py'))

def export(self, decision_tree):
    if <MASK>:
        if len(self.feature_names) != decision_tree.n_features_in_:
            raise ValueError('Length of feature_names, %d does not match number of features, %d' % (len(self.feature_names), decision_tree.n_features_in_))
    self.head()
    if isinstance(decision_tree, _tree.Tree):
        self.recurse(decision_tree, 0, criterion='impurity')
    else:
        self.recurse(decision_tree.tree_, 0, criterion=decision_tree.criterion)
    self.tail()

