    with context.device(GPU):
        m = self._m_2_by_2.gpu()
        self._benchmark_gen_math_ops_matmul(m, transpose_b=False, num_iters=self._num_iters_2_by_2)

def _infer_scalar_type(obj):
    if isinstance(obj, FloatLike):
        return torch.get_default_dtype()
    if isinstance(obj, IntLike) and (not isinstance(obj, bool)):
        return torch.int64
    if isinstance(obj, BoolLike):
        return torch.bool
    if isinstance(obj, complex):
        default_dtype = torch.get_default_dtype()
        if default_dtype is torch.float:
            return torch.cfloat
        elif <MASK>:
            return torch.cdouble
        elif default_dtype is torch.half:
            return torch.chalf
        else:
            raise RuntimeError('invalid default scalar type for complex')
    if isinstance(obj, torch.Tensor):
        return obj.dtype
    if isinstance(obj, str):
        raise TypeError(f"new(): invalid data type '{type(obj).__name__}'")
    if isinstance(obj, (list, tuple)):
        scalarType = None
        length = len(obj)
        if length == 0:
            return torch.get_default_dtype()
        for i in range(length):
            cur_item = obj[i]
            '\n            if cur_item is obj:\n                raise TypeError("new(): self-referential lists are incompatible")\n            '
            item_scalarType = _infer_scalar_type(cur_item)
            if scalarType is not None:
                scalarType = torch.promote_types(scalarType, item_scalarType)
            else:
                scalarType = item_scalarType
            if scalarType is torch.cdouble:
                return scalarType
        return scalarType
    raise RuntimeError(f'Could not infer dtype of {type(obj).__name__}')

def _setup_local_watchdog(self, envs: dict[int, dict[str, str]]) -> None:
    enable_watchdog_env_name = TORCHELASTIC_ENABLE_FILE_TIMER
    watchdog_enabled = os.getenv(enable_watchdog_env_name)
    watchdog_file_env_name = TORCHELASTIC_TIMER_FILE
    watchdog_file_path = os.getenv(watchdog_file_env_name)
    if <MASK>:
        if watchdog_file_path is None:
            watchdog_file_path = '/tmp/watchdog_timer_' + str(uuid.uuid4())
        logger.info('Starting a FileTimerServer with %s ...', watchdog_file_path)
        if not envs:
            logger.warning('Empty envs variables, using empty run_id for FileTimerServer')
            run_id = ''
        else:
            run_id = envs[0]['TORCHELASTIC_RUN_ID']
        self._worker_watchdog = timer.FileTimerServer(file_path=watchdog_file_path, run_id=run_id, max_interval=0.1, daemon=True, log_event=self._log_watchdog_event)
        self._worker_watchdog.start()
        logger.info('FileTimerServer started')
    else:
        logger.info("Environment variable '%s' not found. Do not start FileTimerServer.", enable_watchdog_env_name)
    if watchdog_file_path is not None:
        for worker_env in envs.values():
            worker_env[watchdog_file_env_name] = watchdog_file_path

def get_df(self, log_path, cat_feature2cats=None, nrows=None, apply_filters=False, add_near_best=False):
    """
        Parses the log file and processes the data into a dataframe that can be used for training.
        """
    (df, metadata, features, categorical_features, choices) = self.parse_log(log_path, nrows)

    def calculate_stats(group):
        count = len(group)
        has_inf = np.isinf(group['feedback']).any()
        if has_inf:
            relative_std = np.inf
            median = np.inf
        else:
            mean = group['feedback'].mean()
            std = group['feedback'].std()
            relative_std = std / mean * 100 if mean != 0 else np.inf
            median = group['feedback'].median()
        if relative_std > 5:
            times = group['feedback'].tolist()
            times_str = ', '.join([f'{t:.3f}' for t in sorted(times)])
            log.debug('High relative std: %f. times=%s', relative_std, times_str)
        return pd.Series({'count': count, 'relative_std': relative_std, 'median_execution_time': median})
    feature_columns = features
    stats = df.groupby(feature_columns + ['choice'], as_index=False).apply(calculate_stats, include_groups=False).reset_index()
    if apply_filters:
        valid_stats = stats[(stats['count'] >= 3) & (stats['relative_std'] <= 5)]
        valid_inputs = valid_stats.groupby(feature_columns).filter(lambda x: len(x) >= 2)
    else:
        valid_inputs = stats

    def get_winner_and_speedup(group):
        assert len(group) >= 2, 'Need at least 2 choices'
        sorted_group = group.sort_values('median_execution_time')
        winner = sorted_group.iloc[0]['choice']
        winning_time = sorted_group.iloc[0]['median_execution_time']
        second_best_time = sorted_group.iloc[1]['median_execution_time']
        speedup = second_best_time / winning_time
        unique_choices = group['choice'].unique()
        choice2time = {}
        for row in group.itertuples():
            choice2time[row.choice] = row.median_execution_time
        assert len(unique_choices) == len(group), f'len(unique_choices) != len(group): {len(unique_choices)} != {len(group)}'
        return pd.Series({'winner': winner, 'speedup': speedup, 'avail_choices': unique_choices, 'choice2time': json.dumps(choice2time)})
    results = valid_inputs.groupby(feature_columns, as_index=False).filter(lambda x: len(x) >= 2).groupby(feature_columns, as_index=False).apply(get_winner_and_speedup, include_groups=False).reset_index()

    def add_near_best_configs(df):
        new_rows = []
        for (index, row) in df.iterrows():
            dictionary = json.loads(row['choice2time'])
            min_value = min(dictionary.values())
            for (key, value) in dictionary.items():
                new_row = row.copy()
                relative_performance = min_value / value
                new_row['relative_performance'] = relative_performance
                if <MASK>:
                    breakpoint()
                new_row['actual_winner'] = row['winner']
                new_row['winner'] = key
                if relative_performance >= 0.98:
                    new_rows.append(new_row)
        return pd.DataFrame(new_rows).reset_index(drop=True)
    if add_near_best:
        results = add_near_best_configs(results)
    (results, added_categorical_features) = self.add_new_features(results)
    categorical_features += added_categorical_features
    (results, cat_feature2cats, dummy_col_2_col_val) = self.handle_categorical_features(cat_feature2cats, categorical_features, results)
    return (results, choices, cat_feature2cats, dummy_col_2_col_val, metadata)

def validate_callbacks(input_callbacks, optimizer):
    """Validate whether given callbacks are supported by DistributionStrategy.

  Args:
    input_callbacks: List of callbacks passed by the user to fit.
    optimizer: Optimizer instance used to train the model.

  Raises:
    ValueError: If `LearningRateScheduler` or `ReduceLROnPlateau` is one of the
        callbacks passed.
    ValueError: If `write_grads` is one of the parameters passed as part of the
        TensorBoard callback.
  """
    if input_callbacks:
        for callback in input_callbacks:
            if isinstance(callback, (callbacks.LearningRateScheduler, callbacks.ReduceLROnPlateau)):
                if not isinstance(optimizer, optimizer_v2.OptimizerV2):
                    raise ValueError('You must specify a Keras Optimizer V2 when using %s callback with DistributionStrategy.' % callback)
            if <MASK>:
                if getattr(callback, 'write_grads', False):
                    logging.warning(UserWarning('`write_grads` in the TensorBoard callback is not supported when using DistributionStrategy. Setting `write_grads` to `False`.'))
                    callback.write_grads = False

def reset_partition_in_sparse_nn(partition, new_partition=True):
    """If crossing the boundary between non-embedding nodes and
            embedding nodes, create a new partition
            """
    if in_embedding_region:
        embedding_partitions.append(partition)
    else:
        non_embedding_partitions.append(partition)
    if <MASK>:
        partition = self.create_partition()
        partition.left_mem_bytes = available_mem_bytes
        return partition
    return None

@override
def codegen(self, wrapper: PythonWrapperCodegen) -> None:
    """Overrides the parent member.
        See https://github.com/pytorch/pytorch/issues/151692"""
    kernel = self.op_overload
    assert kernel is not None
    if kernel.namespace == 'aten':
        assert isinstance(kernel, torch._ops.OpOverload), type(kernel)
        if V.graph.cpp_wrapper:
            from torchgen.aoti.fallback_ops import inductor_fallback_ops
            if str(kernel) not in inductor_fallback_ops:
                log.warning('%s is missing a c-shim implementation, using proxy executor as fallback', kernel)
                self.use_runtime_dispatch = True
    elif kernel.namespace == '_quantized':
        assert isinstance(kernel, torch._ops.OpOverload), type(kernel)
    elif V.graph.cpp_wrapper:
        self.use_runtime_dispatch = kernel not in config.aot_inductor.custom_ops_to_c_shims
    if V.graph.cpp_wrapper and isinstance(kernel, torch._ops.OpOverload) and (not self.use_runtime_dispatch):

        def is_number(t: torch.JitType) -> bool:
            if isinstance(t, torch.OptionalType):
                return is_number(t.getElementType())
            return isinstance(t, torch.NumberType)
        (args, kwargs) = self.unflatten_args(self.inputs, self.constant_args)
        args_iter = itertools.chain(args, (self.get_kwargs_value(k, **kwargs) for k in self.ordered_kwargs_for_cpp_kernel))
        self.use_runtime_dispatch = any((isinstance(v, complex) and is_number(a.real_type) for (v, a) in zip(args_iter, kernel._schema.arguments)))
    self.codegen_comment(wrapper)
    if <MASK>:
        exported_args = self.export_extern_kernel_node()
        assert self.python_kernel_name is not None
        assert self.op_overload is not None
        wrapper.generate_fallback_kernel_with_runtime_lookup(self.get_name(), self.python_kernel_name, lambda : [*self.codegen_args(), *self.codegen_kwargs()], self.op_overload, exported_args, self.outputs if self.outputs else self.mutation_outputs)
    else:
        wrapper.generate_fallback_kernel(self)
        if isinstance(self.layout, Layout):
            self.codegen_size_asserts(wrapper)
            self.codegen_alignment_asserts(wrapper)
            self.codegen_memory_tracking(wrapper)
    self.codegen_unbacked_symbol_defs(wrapper)

def createsubrwrapper(rout, signature=0):
    assert issubroutine(rout)
    extra_args = []
    vars = rout['vars']
    for a in rout['args']:
        v = rout['vars'][a]
        for (i, d) in enumerate(v.get('dimension', [])):
            if d == ':':
                dn = f'f2py_{a}_d{i}'
                dv = {'typespec': 'integer', 'intent': ['hide']}
                dv['='] = f'shape({a}, {i})'
                extra_args.append(dn)
                vars[dn] = dv
                v['dimension'][i] = dn
    rout['args'].extend(extra_args)
    need_interface = bool(extra_args)
    ret = ['']

    def add(line, ret=ret):
        ret[0] = f'{ret[0]}\n      {line}'
    name = rout['name']
    fortranname = getfortranname(rout)
    f90mode = ismoduleroutine(rout)
    args = rout['args']
    useisoc = useiso_c_binding(rout)
    sargs = ', '.join(args)
    if f90mode:
        add(f"subroutine f2pywrap_{rout['modulename']}_{name} ({sargs})")
        if <MASK>:
            add('use iso_c_binding')
        if not signature:
            add(f"use {rout['modulename']}, only : {fortranname}")
    else:
        add(f'subroutine f2pywrap{name} ({sargs})')
        if useisoc:
            add('use iso_c_binding')
        if not need_interface:
            add(f'external {fortranname}')
    if need_interface:
        for line in rout['saved_interface'].split('\n'):
            if line.lstrip().startswith('use ') and '__user__' not in line:
                add(line)
    dumped_args = []
    for a in args:
        if isexternal(vars[a]):
            add(f'external {a}')
            dumped_args.append(a)
    for a in args:
        if a in dumped_args:
            continue
        if isscalar(vars[a]):
            add(var2fixfortran(vars, a, f90mode=f90mode))
            dumped_args.append(a)
    for a in args:
        if a in dumped_args:
            continue
        add(var2fixfortran(vars, a, f90mode=f90mode))
    if need_interface:
        if f90mode:
            pass
        else:
            add('interface')
            for line in rout['saved_interface'].split('\n'):
                if line.lstrip().startswith('use ') and '__user__' in line:
                    continue
                add(line)
            add('end interface')
    sargs = ', '.join([a for a in args if a not in extra_args])
    if not signature:
        add(f'call {fortranname}({sargs})')
    if f90mode:
        add(f"end subroutine f2pywrap_{rout['modulename']}_{name}")
    else:
        add('end')
    return ret[0]

