def _find_matches(graph: Graph, modules: dict[str, torch.nn.Module], patterns: dict[Pattern, QuantizeHandler], root_node_getter_mapping: dict[Pattern, Callable], standalone_module_names: Optional[list[str]]=None, standalone_module_classes: Optional[list[type]]=None, custom_module_classes: Optional[list[Any]]=None) -> dict[str, _MatchResult]:
    """
    Matches the nodes in the input graph to quantization patterns, and
    outputs the information needed to quantize them in future steps.

    Inputs:
      - graph: an fx.Graph object
      - modules: a mapping of fully qualified module name to instance,
          for example, {'foo': ModuleFoo, ...}
      - patterns: a mapping from a tuple of nodes in reverse order to
          uninitialized QuantizeHandler subclass.

    Outputs a map of
      node_name ->
        (node, matched_values, matched_pattern, QuantizeHandler instance,
         qconfig)

    For example, {
      'relu_1': (relu_1, [relu_1], torch.nn.functional.relu,
                 <CopyNodeQuantizeHandler instance>, QConfig(...)),
      ...
    }
    """
    if custom_module_classes is None:
        custom_module_classes = []
    if <MASK>:
        standalone_module_classes = []
    if standalone_module_names is None:
        standalone_module_names = []
    match_map: dict[str, _MatchResult] = {}
    all_matched: set[str] = set()

    def _recursive_record_node_in_match_map(last_node, match_map, node_pattern, matched_node_pattern, pattern, match_value):
        if isinstance(node_pattern, Node):
            match_map[node_pattern.name] = (last_node, matched_node_pattern, pattern, match_value)
        elif not isinstance(node_pattern, Iterable):
            return
        else:
            for n in node_pattern:
                _recursive_record_node_in_match_map(last_node, match_map, n, matched_node_pattern, pattern, match_value)

    def record_match(pattern, node, last_node, matched_node_pattern, match_map):
        if isinstance(pattern, tuple):
            (s, *args) = pattern
            is_single_arg = len(args) == 1
            current_node_pattern: list[Node] = []
            record_match(s, node, last_node, matched_node_pattern, match_map)
            if pattern[0] is not getattr:
                for (subpattern, arg) in zip(args, node.args):
                    record_match(subpattern, arg, node, current_node_pattern, match_map)
            if len(current_node_pattern) > 1:
                if is_single_arg:
                    matched_node_pattern.append(tuple(current_node_pattern))
                else:
                    matched_node_pattern.extend(list(current_node_pattern))
            else:
                matched_node_pattern.append(current_node_pattern[0])
        else:
            matched_node_pattern.append(node)
    for node in reversed(graph.nodes):
        if node.name not in match_map and node.name not in all_matched:
            for (pattern, quantize_handler_cls) in patterns.items():
                root_node_getter = root_node_getter_mapping.get(pattern)
                if _is_match(modules, node, pattern) and node.name not in match_map:
                    matched_node_pattern: list[Node] = []
                    record_match(pattern, node, node, matched_node_pattern, match_map)
                    quantize_handler = quantize_handler_cls(matched_node_pattern, modules, root_node_getter)
                    last_node = node
                    _recursive_record_node_in_match_map(last_node, match_map, matched_node_pattern, matched_node_pattern, pattern, quantize_handler)
                    break
    assert modules is not None
    for node in graph.nodes:
        if node.op == 'call_module' and type(modules[node.target]) in custom_module_classes:
            match_map[node.name] = (node, node, None, QuantizeHandler(node, modules, is_custom_module=True))

    def is_standalone_module(node_target: str, modules: dict[str, torch.nn.Module]):
        assert modules is not None
        return node_target in standalone_module_names or type(modules[node_target]) in standalone_module_classes
    for node in graph.nodes:
        if node.op == 'call_module' and (is_standalone_module(node.target, modules) or _is_observed_standalone_module(modules[node.target])):
            match_map[node.name] = (node, node, None, QuantizeHandler(node, modules, is_standalone_module=True))
    return match_map

def register_pointwise(aten_fn, name=None, broadcast=True, type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT, convert_input_to_bool=False, override_return_dtype=None, override_fn_when_input_bool=None, allow_alpha=False, triton_fallback=None):
    """A pointwise function that maps ops.{name} to inputs"""
    name = name or aten_fn.__name__
    fn = ops_wrapper(name)
    register_op_dtype_propagation_rules(name, type_promotion_kind, override_return_dtype)
    if <MASK>:
        override_fn_when_input_bool = ops_wrapper(override_fn_when_input_bool)
    fn = make_pointwise(fn, override_return_dtype=override_return_dtype, override_fn_when_input_bool=override_fn_when_input_bool, allow_alpha=allow_alpha, triton_fallback=triton_fallback)
    fn = register_lowering(aten_fn, broadcast=broadcast, type_promotion_kind=type_promotion_kind, convert_input_to_bool=convert_input_to_bool)(fn)
    if hasattr(prims, name):
        register_lowering(getattr(prims, name), type_promotion_kind=None, convert_input_to_bool=convert_input_to_bool)(fn)
    return fn

def _compute_numerical_jvps_wrt_specific_input(jvp_fn, delta, input_is_complex, is_forward_ad=False) -> list[torch.Tensor]:
    jvps: list[torch.Tensor] = []
    ds_dx_tup = jvp_fn(delta[0] if isinstance(delta, tuple) else delta)
    if input_is_complex:
        ds_dy_tup = jvp_fn(delta[1] * 1j) if isinstance(delta, tuple) else jvp_fn(delta * 1j)
        for (ds_dx, ds_dy) in zip(ds_dx_tup, ds_dy_tup):
            if ds_dx.is_complex():
                raise AssertionError('Expected ds_dx to be real-valued, not complex')
            conj_w_d = ds_dx + ds_dy * 1j
            jvps.append(conj_w_d)
    else:
        for ds_dx in ds_dx_tup:
            if <MASK>:
                raise AssertionError('Expected ds_dx to be real-valued, not complex.')
            jvps.append(ds_dx)
    return jvps

def values_list(self, *fields, flat=False, named=False):
    if flat and named:
        raise TypeError("'flat' and 'named' can't be used together.")
    if flat:
        if len(fields) > 1:
            raise TypeError("'flat' is not valid when values_list is called with more than one field.")
        elif not fields:
            warnings.warn("Calling values_list() with no field name and flat=True is deprecated. Pass an explicit field name instead, like 'pk'.", RemovedInDjango70Warning)
            fields = [self.model._meta.concrete_fields[0].attname]
    field_names = {f: False for f in fields if not hasattr(f, 'resolve_expression')}
    _fields = []
    expressions = {}
    counter = 1
    for field in fields:
        field_name = field
        expression = None
        if <MASK>:
            field_name = getattr(field, 'default_alias', field.__class__.__name__.lower())
            expression = field
            seen = True
        elif (seen := field_names[field_name]):
            expression = F(field_name)
        if seen:
            field_name_prefix = field_name
            while (field_name := f'{field_name_prefix}{counter}') in field_names:
                counter += 1
        if expression is not None:
            expressions[field_name] = expression
        field_names[field_name] = True
        _fields.append(field_name)
    clone = self._values(*_fields, **expressions)
    clone._iterable_class = NamedValuesListIterable if named else FlatValuesListIterable if flat else ValuesListIterable
    return clone

def label_tag(self, contents=None, attrs=None, label_suffix=None, tag=None):
    """
        Wrap the given contents in a <label>, if the field has an ID attribute.
        contents should be mark_safe'd to avoid HTML escaping. If contents
        aren't given, use the field's HTML-escaped label.

        If attrs are given, use them as HTML attributes on the <label> tag.

        label_suffix overrides the form's label_suffix.
        """
    contents = contents or self.label
    if label_suffix is None:
        label_suffix = self.field.label_suffix if self.field.label_suffix is not None else self.form.label_suffix
    if <MASK>:
        contents = format_html('{}{}', contents, label_suffix)
    widget = self.field.widget
    id_ = widget.attrs.get('id') or self.auto_id
    if id_:
        id_for_label = widget.id_for_label(id_)
        if id_for_label:
            attrs = {**(attrs or {}), 'for': id_for_label}
        if self.field.required and hasattr(self.form, 'required_css_class'):
            attrs = attrs or {}
            if 'class' in attrs:
                attrs['class'] += ' ' + self.form.required_css_class
            else:
                attrs['class'] = self.form.required_css_class
    context = {'field': self, 'label': contents, 'attrs': attrs, 'use_tag': bool(id_), 'tag': tag or 'label'}
    return self.form.render(self.form.template_name_label, context)

def _randomized_range_finder(A, *, size, n_iter, power_iteration_normalizer='auto', random_state=None):
    """Body of randomized_range_finder without input validation."""
    (xp, is_array_api_compliant) = get_namespace(A)
    random_state = check_random_state(random_state)
    Q = xp.asarray(random_state.normal(size=(A.shape[1], size)))
    if hasattr(A, 'dtype') and xp.isdtype(A.dtype, kind='real floating'):
        Q = xp.astype(Q, A.dtype, copy=False)
    if is_array_api_compliant:
        Q = xp.asarray(Q, device=device(A))
    if <MASK>:
        if n_iter <= 2:
            power_iteration_normalizer = 'none'
        elif is_array_api_compliant:
            warnings.warn("Array API does not support LU factorization, falling back to QR instead. Set `power_iteration_normalizer='QR'` explicitly to silence this warning.")
            power_iteration_normalizer = 'QR'
        else:
            power_iteration_normalizer = 'LU'
    elif power_iteration_normalizer == 'LU' and is_array_api_compliant:
        raise ValueError("Array API does not support LU factorization. Set `power_iteration_normalizer='QR'` instead.")
    if is_array_api_compliant:
        qr_normalizer = partial(xp.linalg.qr, mode='reduced')
    else:
        qr_normalizer = partial(linalg.qr, mode='economic', check_finite=False)
    if power_iteration_normalizer == 'QR':
        normalizer = qr_normalizer
    elif power_iteration_normalizer == 'LU':
        normalizer = partial(linalg.lu, permute_l=True, check_finite=False)
    else:
        normalizer = lambda x: (x, None)
    for _ in range(n_iter):
        (Q, _) = normalizer(A @ Q)
        (Q, _) = normalizer(A.T @ Q)
    (Q, _) = qr_normalizer(A @ Q)
    return Q

def _split_cluster_for_evaluator(cluster_spec, task_type):
    """Split the cluster for evaluator since it needn't talk to other tasks."""
    new_cluster_spec = normalize_cluster_spec(cluster_spec).as_dict()
    if <MASK>:
        assert _TaskType.EVALUATOR in new_cluster_spec
        new_cluster_spec = {_TaskType.EVALUATOR: new_cluster_spec[_TaskType.EVALUATOR]}
    else:
        new_cluster_spec.pop(_TaskType.EVALUATOR, None)
    return normalize_cluster_spec(new_cluster_spec)

def _ready(op: ops.Operation, sess: session.Session, msg) -> Tuple[bool, Optional[str]]:
    """Checks if the model is ready or not, as determined by op.

  Args:
    op: An op, either _ready_op or _ready_for_local_init_op, which defines the
      readiness of the model.
    sess: A `Session`.
    msg: A message to log to warning if not ready

  Returns:
    A tuple (is_ready, msg), where is_ready is True if ready and False
    otherwise, and msg is `None` if the model is ready, a `String` with the
    reason why it is not ready otherwise.
  """
    if op is None:
        return (True, None)
    else:
        try:
            ready_value = sess.run(op)
            if ready_value is None or ready_value.dtype == np.int32 or ready_value.size == 0:
                return (True, None)
            else:
                non_initialized_varnames = ', '.join([i.decode('utf-8') for i in ready_value])
                return (False, 'Variables not initialized: ' + non_initialized_varnames)
        except errors.FailedPreconditionError as e:
            if <MASK>:
                logging.warning('%s : error [%s]', msg, str(e))
                raise e
            return (False, str(e))

