def __init__(self, dataset: Dataset, num_replicas: Optional[int]=None, rank: Optional[int]=None, shuffle: bool=True, seed: int=0, drop_last: bool=False) -> None:
    if <MASK>:
        if not dist.is_available():
            raise RuntimeError('Requires distributed package to be available')
        num_replicas = dist.get_world_size()
    if rank is None:
        if not dist.is_available():
            raise RuntimeError('Requires distributed package to be available')
        rank = dist.get_rank()
    if rank >= num_replicas or rank < 0:
        raise ValueError(f'Invalid rank {rank}, rank should be in the interval [0, {num_replicas - 1}]')
    self.dataset = dataset
    self.num_replicas = num_replicas
    self.rank = rank
    self.epoch = 0
    self.drop_last = drop_last
    if self.drop_last and len(self.dataset) % self.num_replicas != 0:
        self.num_samples = math.ceil((len(self.dataset) - self.num_replicas) / self.num_replicas)
    else:
        self.num_samples = math.ceil(len(self.dataset) / self.num_replicas)
    self.total_size = self.num_samples * self.num_replicas
    self.shuffle = shuffle
    self.seed = seed

def _prep_args_for_hash(self, result: list[object], args: Union[Mapping[str, object], Sequence[object], Iterable[object]], state: _CacheKeyState, id_hashed_objects: list[object]) -> None:
    """
        Translate the provided args into a form suitable for caching at FakeTensor
        dispatch, i.e., convert unhashable types like lists & dicts into tuples and
        convert FakeTensors into metadata. Raises _BypassDispatchCache to signal
        unsupported cases that should bypass caching.
        """
    from torch._higher_order_ops.auto_functionalize import FunctionalCallableWithEpilogue
    from torch._higher_order_ops.utils import FunctionalizeCtxWrapper
    if isinstance(args, (list, tuple, dict)):
        result.append(type(args))
        result.append(f'length_{len(args)}')
    if isinstance(args, dict):
        self._prep_args_for_hash(result, args.keys(), state, id_hashed_objects)
        self._prep_args_for_hash(result, args.values(), state, id_hashed_objects)
        return
    for arg in args:
        if isinstance(arg, FakeTensor):
            if not self.is_our_fake(arg):
                raise _BypassDispatchCache('not our fake')
            if <MASK>:
                raise _BypassDispatchCache('constant attribute')
            if is_sparse_any(arg):
                raise _BypassDispatchCache(f'{arg.layout} tensor')
            metadata = extract_tensor_metadata(arg)
            metadata._flatten_into(result, self, state)
        elif isinstance(arg, Tensor):
            raise _BypassDispatchCache('non-fake tensor')
        elif isinstance(arg, SymInt):
            state.convert_sym_int(result, arg)
        elif isinstance(arg, (SymBool, SymFloat)):
            raise _BypassDispatchCache('symbolic shape')
        elif isinstance(arg, (list, tuple, dict)):
            self._prep_args_for_hash(result, arg, state, id_hashed_objects)
        elif isinstance(arg, types.FunctionType):
            raise _BypassDispatchCache('function argument')
        elif isinstance(arg, torch.fx.GraphModule):
            result.append(type(arg))
            result.append(id(arg))
            id_hashed_objects.append(arg)
        elif isinstance(arg, FunctionalizeCtxWrapper):
            result.append(hash(arg))
            id_hashed_objects.append(arg.subgraph)
        elif isinstance(arg, FunctionalCallableWithEpilogue):
            result.append(type(arg))
            result.append(hash(arg))
            id_hashed_objects.append(arg.orig_callable)
        else:
            result.append(type(arg))
            result.append(arg)

def _single_tensor_adamax(params: list[Tensor], grads: list[Tensor], exp_avgs: list[Tensor], exp_infs: list[Tensor], state_steps: list[Tensor], *, eps: float, beta1: float, beta2: float, lr: float, weight_decay: float, maximize: bool, differentiable: bool, capturable: bool, has_complex: bool):
    if not torch.jit.is_scripting():
        lr = _to_scalar(lr)
    for (i, param) in enumerate(params):
        grad = grads[i]
        grad = grad if not maximize else -grad
        exp_avg = exp_avgs[i]
        exp_inf = exp_infs[i]
        step_t = state_steps[i]
        if not torch.compiler.is_compiling() and capturable:
            capturable_supported_devices = _get_capturable_supported_devices()
            if not (param.device.type == step_t.device.type and param.device.type in capturable_supported_devices):
                raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
        step_t += 1
        if weight_decay != 0:
            grad = grad.add(param, alpha=weight_decay)
        if <MASK>:
            param = torch.view_as_real(param)
            grad = torch.view_as_real(grad)
            exp_avg = torch.view_as_real(exp_avg)
            exp_inf = torch.view_as_real(exp_inf)
        exp_avg.lerp_(grad, 1 - beta1)
        if not differentiable:
            torch.maximum(exp_inf.mul_(beta2), grad.abs().add_(eps), out=exp_inf)
        else:
            norm_buf = torch.cat([exp_inf.mul_(beta2).unsqueeze(0), grad.abs().add_(eps).unsqueeze_(0)], 0)
            exp_inf.copy_(torch.amax(norm_buf, 0, keepdim=False))
        if capturable:
            neg_bias_correction = beta1 ** step_t - 1
            neg_bias_correction.div_(lr)
            denom = exp_inf * neg_bias_correction
            param.addcdiv_(exp_avg, denom)
        else:
            bias_correction = 1 - beta1 ** _get_value(step_t)
            clr = lr / bias_correction
            param.addcdiv_(exp_avg, exp_inf, value=-clr)

@staticmethod
def wrap(res: object, spec: OutputSpecType) -> object:
    if isinstance(res, torch.Tensor):
        if spec is not None:
            assert isinstance(spec, DTensorSpec), f'output spec does not match with output! Expected DTensorSpec, got {spec}.'
            return dtensor.DTensor(res, spec, requires_grad=res.requires_grad)
        else:
            assert res.ndim == 0, 'output tensor should be scalar!'
            return res
    elif <MASK>:
        assert spec is not None and isinstance(spec, (list, tuple)), f'output spec does not match with output! Expected list/tuple, got {spec}.'
        res_list = []
        for (e, s) in zip(res, spec):
            res_list.append(OpDispatcher.wrap(e, s))
        return tuple(res_list) if isinstance(res, tuple) else res_list
    else:
        return res

def _inherit_from_data(name: str, delegate: type, cache: bool=False, wrap: bool=False):
    """
    Make an alias for a method of the underlying ExtensionArray.

    Parameters
    ----------
    name : str
        Name of an attribute the class should inherit from its EA parent.
    delegate : class
    cache : bool, default False
        Whether to convert wrapped properties into cache_readonly
    wrap : bool, default False
        Whether to wrap the inherited result in an Index.

    Returns
    -------
    attribute, method, property, or cache_readonly
    """
    attr = getattr(delegate, name)
    if <MASK>:
        if cache:

            def cached(self):
                return getattr(self._data, name)
            cached.__name__ = name
            cached.__doc__ = attr.__doc__
            method = cache_readonly(cached)
        else:

            def fget(self):
                result = getattr(self._data, name)
                if wrap:
                    if isinstance(result, type(self._data)):
                        return type(self)._simple_new(result, name=self.name)
                    elif isinstance(result, ABCDataFrame):
                        return result.set_index(self)
                    return Index(result, name=self.name, dtype=result.dtype)
                return result

            def fset(self, value) -> None:
                setattr(self._data, name, value)
            fget.__name__ = name
            fget.__doc__ = attr.__doc__
            method = property(fget, fset)
    elif not callable(attr):
        method = attr
    else:

        def method(self, *args, **kwargs):
            if 'inplace' in kwargs:
                raise ValueError(f'cannot use inplace with {type(self).__name__}')
            result = attr(self._data, *args, **kwargs)
            if wrap:
                if isinstance(result, type(self._data)):
                    return type(self)._simple_new(result, name=self.name)
                elif isinstance(result, ABCDataFrame):
                    return result.set_index(self)
                return Index(result, name=self.name, dtype=result.dtype)
            return result
        method.__name__ = name
        method.__doc__ = attr.__doc__
        method.__signature__ = signature(attr)
    return method

def patched_dim_method(wrapper: WrappedOperator, *args: Any, **kwargs: Any) -> Any:
    """
    This is the core method that handles dimension-aware operations.
    """
    if not args:
        raise ValueError('Expected at least one argument (self)')
    dim_arg = kwargs.get(wrapper.dim_name)
    if dim_arg is None and wrapper.dim_offset < len(args):
        dim_idx = wrapper.dim_offset + 1
        if dim_idx < len(args):
            dim_arg = args[dim_idx]
    if dim_arg is None:
        info = TensorInfo.create(args[0], ensure_batched=True, ensure_present=False)
        if not info:
            return wrapper.orig(*args, **kwargs)
        with EnableAllLayers(info.levels) as guard:
            assert info.batchedtensor is not None
            guard.inplace_update_layers(info.batchedtensor, info.levels)
            new_args = list(args)
            new_args[0] = handle_from_tensor(info.batchedtensor)
            result = wrapper.orig(*new_args, **kwargs)
            return guard.from_batched(result, info.has_device)
    info = TensorInfo.create(args[0])
    if not info:
        return wrapper.orig(*args, **kwargs)
    keepdim = False
    if wrapper.reduce:
        keepdim_arg = kwargs.get('keepdim')
        if keepdim_arg is None and wrapper.keepdim_offset < len(args):
            keepdim_idx = wrapper.keepdim_offset + 1
            if keepdim_idx < len(args):
                keepdim_arg = args[keepdim_idx]
        if keepdim_arg is not None:
            keepdim = bool(keepdim_arg)
    ndim = info.ndim()
    dims = _wrap_dims(dim_arg, ndim, keepdim)
    dim_indices: list[int] = []
    seen = [False] * len(info.levels)
    for d in dims:
        midx = None
        for (i, level) in enumerate(info.levels):
            if level == d:
                midx = i
                break
        if midx is None:
            for (i, level) in enumerate(info.levels):
                if <MASK>:
                    midx = i
                    break
            if midx is None:
                level_strs = [str(level) for level in info.levels]
                raise ValueError(f'Tensor with dimensions {level_strs} does not contain {d}')
        seen[midx] = True
        dim_indices.append(midx)
    new_levels = []
    if wrapper.reduce and (not keepdim):
        for (i, level) in enumerate(info.levels):
            if not seen[i]:
                new_levels.append(level)
    else:
        new_levels = info.levels[:]
    if len(dim_indices) == 1:
        py_indices: Any = dim_indices[0]
    else:
        py_indices = tuple(dim_indices)
    new_args = list(args)
    new_kwargs = kwargs.copy()
    assert info.tensor is not None
    new_args[0] = handle_from_tensor(info.tensor)
    if wrapper.dim_name in new_kwargs:
        new_kwargs[wrapper.dim_name] = py_indices
    else:
        dim_idx = wrapper.dim_offset + 1
        if dim_idx < len(new_args):
            new_args = list(new_args)
            new_args[dim_idx] = py_indices
    result = wrapper.orig(*new_args, **new_kwargs)

    def wrap_result(obj: Any) -> Any:
        if isinstance(obj, torch.Tensor):
            from . import Tensor
            return Tensor.from_positional(obj, new_levels, info.has_device)
        return obj
    return tree_map(wrap_result, result)

def getrawvalue(self) -> str:
    buf = StringIO()
    for li in self._lines:
        if <MASK>:
            line = li()
            if line is None:
                continue
        elif isinstance(li, LineContext):
            continue
        else:
            line = li
        assert isinstance(line, str)
        if line.endswith('\\'):
            buf.write(line[:-1])
        else:
            buf.write(line)
            buf.write('\n')
    return buf.getvalue()

def get_json_type(obj):
    """Serializes any object to a JSON-serializable structure.

  Args:
      obj: the object to serialize

  Returns:
      JSON-serializable structure representing `obj`.

  Raises:
      TypeError: if `obj` cannot be serialized.
  """
    if hasattr(obj, 'get_config'):
        return {'class_name': obj.__class__.__name__, 'config': obj.get_config()}
    if type(obj).__module__ == np.__name__:
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        else:
            return obj.item()
    if callable(obj):
        return obj.__name__
    if <MASK>:
        return obj.__name__
    if isinstance(obj, tensor_shape.Dimension):
        return obj.value
    if isinstance(obj, tensor_shape.TensorShape):
        return obj.as_list()
    if isinstance(obj, dtypes.DType):
        return obj.name
    if isinstance(obj, collections_abc.Mapping):
        return dict(obj)
    if obj is Ellipsis:
        return {'class_name': '__ellipsis__'}
    if isinstance(obj, wrapt.ObjectProxy):
        return obj.__wrapped__
    raise TypeError(f'Object {obj} is not JSON-serializable. You may implement a `get_config()` method on the class (returning a JSON-serializable dictionary) to make it serializable.')

@final
def _ensure_frame(self, data) -> DataFrame:
    if isinstance(data, ABCSeries):
        label = self.label
        if label is None and data.name is None:
            label = ''
        if <MASK>:
            data = data.to_frame()
        else:
            data = data.to_frame(name=label)
    elif self._kind in ('hist', 'box'):
        cols = self.columns if self.by is None else self.columns + self.by
        data = data.loc[:, cols]
    return data

def generate_node_schedule(self, nodes, numel, rnumel):
    node_schedule: list[Any] = []
    done = OrderedSet[scheduler.BaseSchedulerNode]()
    not_ready_yet_nodes: OrderedSet[str] = OrderedSet()
    current_loop_buffer_usage: OrderedSet[str] = OrderedSet()
    maybe_split_index: Optional[int] = None

    def fits_in_main_body(n):
        (_, (node_numel, node_rnumel)) = n.group
        return node_numel == numel and node_rnumel == rnumel or (node_numel == numel * rnumel and node_rnumel == 1)

    def fits_outside_reduction(n):
        (_, (node_numel, node_rnumel)) = n.group
        return node_numel == numel and node_rnumel == 1 and (rnumel != 1)

    def expect_improved_memory_usage(n):
        for read in n.read_writes.reads:
            if read.name in current_loop_buffer_usage:
                return True
        return False

    def schedule_node_in_loop(n):
        done.add(n)
        node_schedule.append(n)
        current_loop_buffer_usage.update([x.name for x in n.read_writes.reads])
        if n.is_reduction() and isinstance(n, scheduler.SchedulerNode) and isinstance(n.node, ir.ComputedBuffer) and (not isinstance(n.node.data, ir.Scan)):
            not_ready_yet_nodes.add(n.get_name())
        else:
            current_loop_buffer_usage.update([x.name for x in n.read_writes.writes])

    @contextlib.contextmanager
    def end_current_reduction_loop():
        nonlocal maybe_split_index
        if node_schedule and node_schedule[-1] is EnableReduction:
            node_schedule.pop()
        else:
            node_schedule.append(DisableReduction)
        if maybe_split_index:
            node_schedule.insert(maybe_split_index, DisableReduction)
            node_schedule.insert(maybe_split_index + 1, EnableReduction)
            maybe_split_index = None
        yield
        node_schedule.append(EnableReduction)
        not_ready_yet_nodes.clear()
        current_loop_buffer_usage.clear()

    def requires_closing_previous_reduction(node, node_schedule):
        if rnumel == 1:
            return False
        if not not_ready_yet_nodes & node.ancestors:
            return False
        assert node_schedule and (not isinstance(node_schedule[-1], (EnableReduction, DisableReduction)))
        return bool(not_ready_yet_nodes)
    for node in nodes:
        if node in done:
            continue
        done.add(node)
        if fits_in_main_body(node):
            if requires_closing_previous_reduction(node, node_schedule):
                with end_current_reduction_loop():
                    pass
            if <MASK>:
                maybe_split_index = maybe_split_index or len(node_schedule)
            else:
                maybe_split_index = None
            schedule_node_in_loop(node)
        elif fits_outside_reduction(node):
            with end_current_reduction_loop():
                node_schedule.append(node)
        else:
            raise NotImplementedError(f'unexpected group: ({numel}, {rnumel}) != {node.group[1]}')
    return node_schedule

def _parse_sym_expr(self, expr_str: str, hint: Optional[Union[int, bool, float]]=None) -> sympy.Expr:
    """
        Parses and does bottom-up processing of sympy.Expr nodes,
        populating ShapeEnv & caching symbols as needed.
        """

    def _process_sym_expr(sym: sympy.Expr, hint: Optional[Union[int, bool, float]]=None) -> sympy.Expr:
        if sym.is_Integer or sym.is_Float or sym.is_Boolean:
            return sym
        else:
            expr_str = str(sym)
            for arg in sym.args:
                self._parse_sym_expr(arg)
            if expr_str in self.symbol_name_to_symbol:
                sym = self.symbol_name_to_symbol[expr_str]
            else:
                self.symbol_name_to_symbol[expr_str] = sym
                if isinstance(sym, sympy.Symbol) and symbolic_shapes.symbol_is_type(sym, (SymT.UNBACKED_INT, SymT.UNBACKED_FLOAT)):
                    self.unbacked_symbols.add(sym)
            if hint is not None and sym not in self.shape_env.var_to_val:
                self.shape_env.add_var_to_val(sym, hint)
            if <MASK>:
                self.shape_env.constrain_symbol_range(sym, compiler_min=vr.lower, compiler_max=vr.upper)
            if isinstance(sym, sympy.Symbol):
                self.shape_env.var_to_stack[sym] = CapturedTraceback.extract(skip=1)
        return sym
    expr = sympy.sympify(expr_str, locals={**self.sympy_functions, **self.symbol_name_to_symbol})
    return _process_sym_expr(expr, hint)

def modified_arguments(self, kwargs, requested_parameters):
    strategy = None
    for (_, v) in kwargs.items():
        if isinstance(v, NamedDistribution):
            if strategy is not None and _num_total_workers(v.has_chief, v.num_workers) > 1:
                raise ValueError('Only support one NamedDistribution for multi workertests.')
            strategy = v
    if strategy:
        has_chief = strategy.has_chief
        num_workers = strategy.num_workers
        runner = strategy.runner
        share_gpu = strategy.share_gpu
        num_ps = strategy.num_ps
        if 'has_chief' in kwargs and kwargs['has_chief'] != has_chief:
            raise ValueError('both has_chief and strategy specified but are not compatible')
        if 'num_workers' in kwargs and kwargs['num_workers'] != num_workers:
            raise ValueError('both num_workers and strategy specified but are not compatible')
    else:
        has_chief = kwargs.get('has_chief', False)
        num_workers = kwargs.get('num_workers', 1)
        runner = kwargs.get('runner', None)
        share_gpu = kwargs.get('share_gpu', True)
        num_ps = kwargs.get('num_ps', 0)
    update = {}
    if 'has_chief' in requested_parameters:
        update['has_chief'] = has_chief
    if 'num_workers' in requested_parameters:
        update['num_workers'] = num_workers
    if <MASK>:
        update['runner'] = runner
    if 'share_gpu' in requested_parameters:
        update['share_gpu'] = share_gpu
    if 'num_ps' in requested_parameters:
        update['num_ps'] = num_ps
    return update

def _is_stateful_pfor_op(op):
    if isinstance(op, WhileOp):
        return op.is_stateful
    if <MASK>:
        return False
    if op.type in passthrough_stateful_ops:
        return False
    if op.type in force_stateful_ops:
        return True
    assert hasattr(op, 'op_def') and op.op_def is not None, op
    return op.op_def.is_stateful

@_apply_docstring_templates
def mean(input: Union[Tensor, MaskedTensor], dim: DimOrDims=None, *, keepdim: Optional[bool]=False, dtype: Optional[DType]=None, mask: Optional[Tensor]=None) -> Tensor:
    """{reduction_signature}

{reduction_descr}

By definition, the identity value of a mean operation is the mean
value of the tensor. If all elements of the input tensor along given
dimension(s) :attr:`dim` are masked-out, the identity value of the
mean is undefined.  Due to this ambiguity, the elements of output
tensor with strided layout, that correspond to fully masked-out
elements, have ``nan`` values.

{reduction_args}

{reduction_example}"""
    dtype_source = 'Optional'
    if dtype is None:
        dtype = input.dtype
        dtype_source = 'Input'
    if not (dtype.is_floating_point or dtype.is_complex):
        raise ValueError(f'mean(): Could not infer output dtype. {dtype_source} dtype must be either a floating point or complex dtype. Got: {dtype}')
    if input.layout == torch.strided:
        if mask is None:
            count = sum(torch.ones(input.shape, dtype=torch.int64, device=input.device), dim, keepdim=keepdim)
            total = sum(input, dim, keepdim=keepdim, dtype=dtype)
        else:
            inmask = _input_mask(input, mask=mask)
            count = inmask.sum(dim=dim, keepdim=bool(keepdim))
            total = sum(input, dim, keepdim=keepdim, dtype=dtype, mask=inmask)
        return total / count
    elif <MASK>:
        mask_input = _combine_input_and_mask(mean, input, mask)
        dim_ = _canonical_dim(dim, mask_input.ndim)
        if mask is None:
            raise ValueError('masked mean expects explicit mask for sparse_csr tensor input')
        return _sparse_csr_segment_reduction_helper(torch.mean, mask_input, dim_, bool(keepdim), dtype)
    else:
        raise ValueError(f'masked mean expects strided or sparse_csr tensor (got {input.layout} tensor)')

@final
@doc(where, klass=_shared_doc_kwargs['klass'], cond='False', cond_rev='True', name='mask', name_other='where')
def mask(self, cond, other=lib.no_default, *, inplace: bool=False, axis: Axis | None=None, level: Level | None=None) -> Self | None:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if inplace:
        if <MASK>:
            if sys.getrefcount(self) <= REF_COUNT:
                warnings.warn(_chained_assignment_method_msg, ChainedAssignmentError, stacklevel=2)
    cond = common.apply_if_callable(cond, self)
    other = common.apply_if_callable(other, self)
    if not hasattr(cond, '__invert__'):
        cond = np.array(cond)
    return self._where(~cond, other=other, inplace=inplace, axis=axis, level=level)

def __init__(self) -> None:
    self._bindings_module: Optional[CallgrindModuleType] = None
    valgrind_symbols = ('_valgrind_supported_platform', '_valgrind_toggle', '_valgrind_toggle_and_dump_stats')
    if all((hasattr(torch._C, symbol) for symbol in valgrind_symbols)):
        self._supported_platform: bool = torch._C._valgrind_supported_platform()
    else:
        print('Callgrind bindings are not present in `torch._C`. JIT-ing bindings.')
        self._bindings_module = cpp_jit.get_compat_bindings()
        if <MASK>:
            raise AssertionError('JIT-compiled callgrind bindings are missing required symbols')
        self._supported_platform = self._bindings_module._valgrind_supported_platform()
    self._commands_available: dict[str, bool] = {}
    if self._supported_platform:
        for cmd in ('valgrind', 'callgrind_control', 'callgrind_annotate'):
            self._commands_available[cmd] = not subprocess.run(['which', cmd], capture_output=True, check=False).returncode
    self._build_type: Optional[str] = None
    build_search = re.search('BUILD_TYPE=(.+),', torch.__config__.show())
    if build_search is not None:
        self._build_type = build_search.groups()[0].split(',')[0]

def get_matching_overload(node: torch.fx.Node, overloads: Sequence[_registration.OnnxDecompMeta]) -> tuple[Callable | None, str]:
    """Get the overload that matches the node's arguments.

    Args:
        node: The node to match.
        overloads: The OnnxDecompMeta with overloads and their signatures to match against.

    Returns:
        A tuple containing the matched overload and a string describing the reason for failure or success.
    """
    if not hasattr(node.target, '_schema'):
        return (overloads[0].onnx_function, 'The node target does not have a schema. Return the first one.')
    named_args = _get_named_fx_node_args(node)
    schema_args: dict[str, torch.Argument] = {arg.name: arg for arg in node.target._schema.arguments}
    failure_messages: list[str] = []
    for overload in overloads:
        assigned_types: dict[str, ir.TypeProtocol] = {}
        fail_reason = ''
        if overload.signature is None:
            return (overload.onnx_function, 'The overload does not have a signature. Assuming it is a custom op and matching it.')
        for param in overload.signature:
            if param.name not in schema_args and param.required:
                fail_reason = 'Required parameter not supplied'
                break
            if param.name in named_args:
                arg = named_args[param.name]
            elif param.name in schema_args and schema_args[param.name].has_default_value():
                arg = schema_args[param.name].default_value
            elif param.has_default():
                arg = param.default
            else:
                fail_reason = 'Parameter not provided'
                break
            if isinstance(param, _schemas.Parameter):
                if isinstance(arg, torch.Tensor):
                    arg = _get_type_from_tensor(arg)
                if <MASK>:
                    first_tensor = _get_first_tensor_in_node_list(arg)
                    assert first_tensor is not None
                    arg = ir.SequenceType(_get_type_from_tensor(first_tensor))
                elif isinstance(arg, torch.fx.Node):
                    meta_val = arg.meta['val']
                    arg = _get_type_from_tensor(meta_val)
                if not _param_type_compatible_with_arg(param, arg, assigned_types):
                    fail_reason = f'Parameter type not compatible with argument: param=`{param}`, assigned_types=`{assigned_types}`, arg=`{arg}`'
                    break
            elif isinstance(param, _schemas.AttributeParameter):
                if not _attribute_type_compatible_with_arg(param, arg):
                    fail_reason = f'Attribute type not compatible with argument: param=`{param}`, arg=`{arg}`'
                    break
            else:
                raise TypeError(f'Unknown parameter type: {type(param)}')
        if not fail_reason:
            return (overload.onnx_function, 'Successfully matched overload')
        else:
            failure_messages.append(f'- Failed to match overload `{overload}`: {fail_reason}')
    return (None, f'All overloads did not match the node `{node.format_node()}`.\n' + '\n'.join(failure_messages))

def testAdjustRandomHue(self):
    x_shapes = [[2, 2, 3], [4, 2, 3], [2, 4, 3], [2, 5, 3], [1000, 1, 3]]
    test_styles = ['all_random', 'rg_same', 'rb_same', 'gb_same', 'rgb_same']
    for x_shape in x_shapes:
        for test_style in test_styles:
            x_np = np.random.rand(*x_shape) * 255.0
            delta_h = np.random.rand() * 2.0 - 1.0
            if test_style == 'all_random':
                pass
            elif test_style == 'rg_same':
                x_np[..., 1] = x_np[..., 0]
            elif test_style == 'rb_same':
                x_np[..., 2] = x_np[..., 0]
            elif test_style == 'gb_same':
                x_np[..., 2] = x_np[..., 1]
            elif <MASK>:
                x_np[..., 1] = x_np[..., 0]
                x_np[..., 2] = x_np[..., 0]
            else:
                raise AssertionError('Invalid test style: %s' % test_style)
            y_np = self._adjustHueNp(x_np, delta_h)
            y_tf = self._adjustHueTf(x_np, delta_h)
            self.assertAllClose(y_tf, y_np, rtol=2e-05, atol=1e-05)

def forward(self, input, hx=None):
    """
        Runs the forward pass.
        """
    self._update_flat_weights()
    num_directions = 2 if self.bidirectional else 1
    orig_input = input
    if isinstance(orig_input, PackedSequence):
        (input, batch_sizes, sorted_indices, unsorted_indices) = input
        max_batch_size = batch_sizes[0]
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    else:
        batch_sizes = None
        if input.dim() not in (2, 3):
            raise ValueError(f'RNN: Expected input to be 2D or 3D, got {input.dim()}D tensor instead')
        is_batched = input.dim() == 3
        batch_dim = 0 if self.batch_first else 1
        if not is_batched:
            input = input.unsqueeze(batch_dim)
            if hx is not None:
                if hx.dim() != 2:
                    raise RuntimeError(f'For unbatched 2-D input, hx should also be 2-D but got {hx.dim()}-D tensor')
                hx = hx.unsqueeze(1)
        elif hx is not None and hx.dim() != 3:
            raise RuntimeError(f'For batched 3-D input, hx should also be 3-D but got {hx.dim()}-D tensor')
        max_batch_size = input.size(0) if self.batch_first else input.size(1)
        sorted_indices = None
        unsorted_indices = None
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    assert hx is not None
    self.check_forward_args(input, hx, batch_sizes)
    assert self.mode == 'RNN_TANH' or self.mode == 'RNN_RELU'
    if <MASK>:
        if self.mode == 'RNN_TANH':
            result = _VF.rnn_tanh(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
        else:
            result = _VF.rnn_relu(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
    elif self.mode == 'RNN_TANH':
        result = _VF.rnn_tanh(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    else:
        result = _VF.rnn_relu(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    output = result[0]
    hidden = result[1]
    if isinstance(orig_input, PackedSequence):
        output_packed = PackedSequence(output, batch_sizes, sorted_indices, unsorted_indices)
        return (output_packed, self.permute_hidden(hidden, unsorted_indices))
    if not is_batched:
        output = output.squeeze(batch_dim)
        hidden = hidden.squeeze(1)
    return (output, self.permute_hidden(hidden, unsorted_indices))

@register_decomposition([aten.cat.default])
def cat(tensors: list[torch.Tensor], dim: int=0) -> torch.Tensor:

    def non_empty_tensor(x: torch.Tensor) -> bool:
        if len(x.shape) == 1 and guard_or_false(x.shape[0] == 0):
            return False
        if dim < len(x.shape) and guard_or_false(x.shape[dim] == 0):
            return False
        return True
    filtered_tensors = list(filter(non_empty_tensor, tensors))
    if <MASK>:
        promoted_dtype = elementwise_dtypes(*tensors, type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)[1]
        filtered_t = filtered_tensors[0]
        return filtered_t.clone() if promoted_dtype == filtered_t.dtype else filtered_t.to(dtype=promoted_dtype)
    elif 1 < len(filtered_tensors) < len(tensors):
        return aten.cat.default(filtered_tensors, dim)
    if len(filtered_tensors) > 1 and all((t is filtered_tensors[0] for t in filtered_tensors)):
        inp = filtered_tensors[0]
        shape = list(inp.shape)
        dim = dim + len(inp.shape) if dim < 0 else dim
        shape.insert(dim, len(filtered_tensors))
        return inp.unsqueeze(dim).expand(*shape).flatten(dim, dim + 1).clone()
    return NotImplemented

def html(self):
    """
        Build HTML documentation.
        """
    ret_code = self._sphinx_build('html')
    zip_fname = os.path.join(BUILD_PATH, 'html', 'pandas.zip')
    if os.path.exists(zip_fname):
        os.remove(zip_fname)
    if <MASK>:
        if self.single_doc_html is not None:
            if not self.no_browser:
                self._open_browser(self.single_doc_html)
        else:
            self._add_redirects()
            if self.whatsnew and (not self.no_browser):
                self._open_browser(os.path.join('whatsnew', 'index.html'))
    return ret_code

@classmethod
def from_saved_model(cls, saved_model_dir, signature_keys=None, tags=None):
    """Creates a TFLiteConverter object from a SavedModel directory.

    Args:
      saved_model_dir: SavedModel directory to convert.
      signature_keys: List of keys identifying SignatureDef containing inputs
        and outputs. Elements should not be duplicated. By default the
        `signatures` attribute of the MetaGraphdef is used. (default
        saved_model.signatures)
      tags: Set of tags identifying the MetaGraphDef within the SavedModel to
        analyze. All tags in the tag set must be present. (default
        {tf.saved_model.SERVING} or {'serve'})

    Returns:
      TFLiteConverter object.

    Raises:
      Invalid signature keys.
    """
    TFLiteConverterBase._set_original_model_type(conversion_metadata_fb.ModelType.TF_SAVED_MODEL)
    if not context.executing_eagerly():
        signature_key = None
        if signature_keys:
            if len(signature_keys) != 1:
                raise ValueError('Only support a single signature key.')
            else:
                signature_key = signature_keys[0]
        logging.warning('Invoking the TF1 implementation of TFLiteConverter because eager is disabled. Consider enabling eager.')
        return TFLiteConverter.from_saved_model(saved_model_dir, signature_key=signature_key, tag_set=tags)
    if tags is None:
        tags = set([_tag_constants.SERVING])
    with context.eager_mode():
        saved_model = _load(saved_model_dir, tags)
    if not signature_keys:
        signature_keys = list(saved_model.signatures.keys())
    if not signature_keys:
        raise ValueError('Only support at least one signature key.')
    if len(signature_keys) > 1 and hasattr(saved_model, 'serve') and (not hasattr(saved_model, '_default_save_signature')):
        saved_model.serving_default = saved_model.serve
        delattr(saved_model, 'serve')
        signature_keys = ['serving_default']
    funcs = []
    for key in signature_keys:
        if key not in saved_model.signatures:
            raise ValueError("Invalid signature key '{}' found. Valid keys are '{}'.".format(key, ','.join(saved_model.signatures)))
        funcs.append(saved_model.signatures[key])
    saved_model_converter = TFLiteSavedModelConverterV2(saved_model_dir, tags, signature_keys)
    if <MASK>:
        return saved_model_converter
    return cls(funcs, saved_model)

def _codegen_single_template(self, kernel, render, template_node, epilogue_nodes, prologue_nodes, *, only_gen_src_code=False):
    """
        Helper method to codegen a single template kernel variant
        """
    buf_name_to_prologue_group = {}
    template_reads = template_node.used_buffer_names()
    prologue_group = []
    for prologue in prologue_nodes:
        names = prologue.get_buffer_names()
        prologue_group.append(prologue)
        if names & template_reads:
            assert len(names) == 1
            buf_name_to_prologue_group[next(iter(names))] = prologue_group
            kernel.prologue_fused_inputs.add(next(iter(names)))
            prologue_group = []
    assert len(prologue_group) == 0
    with kernel:
        if not only_gen_src_code:
            for node in [template_node, *epilogue_nodes]:
                node.mark_run()
        partial_code = render()
        num_store_subgraphs = kernel.get_store_output_count()
        for i in range(num_store_subgraphs):
            subgraph_name = kernel._get_store_output_subgraph_name(i)
            with kernel.set_subgraph_body(subgraph_name):
                for node in epilogue_nodes:
                    node.codegen(kernel.split_and_set_ranges(node.get_ranges()))
                kernel.cse.invalidate(OrderedSet())
        for (input_name, buffer) in kernel.named_input_nodes.items():
            subgraph_name = f'<LOAD_INPUT_{input_name}>'
            if (prologue_group := buf_name_to_prologue_group.get(buffer.get_name(), [])):
                can_codegen_without_upcast = all((p_n.can_codegen_without_upcasts() for p_n in prologue_group))
                with config.patch('triton.codegen_upcast_to_fp32', not can_codegen_without_upcast):
                    with kernel.set_subgraph_body(subgraph_name):
                        for prologue_node in prologue_group:
                            if len(prologue_node.get_buffer_names()) == 1 and len(prologue_group) == 1:
                                if prologue_preserves_zero_mask(prologue_node):
                                    kernel.prologue_fused_inputs_preserve_zero |= prologue_node.get_buffer_names()
                            prologue_node.codegen(kernel.split_and_set_ranges(prologue_node.get_ranges()))
                        kernel.cse.invalidate(OrderedSet())
    with V.set_kernel_handler(kernel):
        if not isinstance(partial_code, str):
            with ir.IRNode.current_origins(template_node.node.origins):
                partial_code.finalize_hook('<DEF_KERNEL>')
            partial_code.finalize_hook('<ARGDEFS>', strict=False)
        for input_name in kernel.named_input_nodes.keys():
            subgraph_name = f'<LOAD_INPUT_{input_name}>'
            partial_code.finalize_hook(subgraph_name, strict=False)
        num_store_subgraphs = kernel.get_store_output_count()
        for i in range(num_store_subgraphs):
            subgraph_name = kernel._get_store_output_subgraph_name(i)
            partial_code.finalize_hook(subgraph_name)
        if <MASK>:
            src_code = partial_code
        else:
            src_code = partial_code.finalize_remaining()
        node_schedule = [*prologue_nodes, template_node, *epilogue_nodes]
        if config.benchmark_kernel:
            num_gb = kernel.estimate_kernel_num_bytes() / 1000000000.0
            src_code = f'{kernel.imports_for_benchmark_kernel()}\n{src_code}\n{kernel.codegen_kernel_benchmark(num_gb).getvalue()}'
        if only_gen_src_code:
            return src_code
        kernel.kernel_name = self.define_kernel(src_code, node_schedule, kernel)
        return kernel

def _get_metric_object(self, metric, y_t, y_p):
    """Converts user-supplied metric to a `Metric` object.

    Args:
      metric: A string, function, or `Metric` object.
      y_t: Sample of label.
      y_p: Sample of output.

    Returns:
      A `Metric` object.
    """
    if metric is None:
        return None
    if str(metric).lower() not in ['accuracy', 'acc', 'crossentropy', 'ce']:
        metric_obj = metrics_mod.get(metric)
    else:
        y_t_rank = len(y_t.shape.as_list())
        y_p_rank = len(y_p.shape.as_list())
        y_t_last_dim = y_t.shape.as_list()[-1]
        y_p_last_dim = y_p.shape.as_list()[-1]
        is_binary = y_p_last_dim == 1
        is_sparse_categorical = y_t_rank < y_p_rank or (y_t_last_dim == 1 and y_p_last_dim > 1)
        if str(metric).lower() in ['accuracy', 'acc']:
            if is_binary:
                metric_obj = metrics_mod.binary_accuracy
            elif is_sparse_categorical:
                metric_obj = metrics_mod.sparse_categorical_accuracy
            else:
                metric_obj = metrics_mod.categorical_accuracy
        elif is_binary:
            metric_obj = metrics_mod.binary_crossentropy
        elif is_sparse_categorical:
            metric_obj = metrics_mod.sparse_categorical_crossentropy
        else:
            metric_obj = metrics_mod.categorical_crossentropy
    if isinstance(metric_obj, losses_mod.Loss):
        metric_obj._allow_sum_over_batch_size = True
    if <MASK>:
        if isinstance(metric, str):
            metric_name = metric
        else:
            metric_name = get_custom_object_name(metric)
            if metric_name is None:
                raise ValueError('Metric should be a callable, found: {}'.format(metric))
        metric_obj = metrics_mod.MeanMetricWrapper(metric_obj, name=metric_name)
    return metric_obj

def testNestedCall(self):
    if <MASK>:
        self.skipTest('b/162800687: Inner function runs on host')
    with ops.device('device:{}:0'.format(self.device)):

        @polymorphic_function.function(jit_compile=True)
        def fn(x, a):
            return x + a

        @polymorphic_function.function(jit_compile=False)
        def fn2(x, a):
            return fn(x, a)
        inputs = constant_op.constant([1, 2, 2, 3, 3])
        self.assertAllClose([2, 3, 3, 4, 4], fn2(inputs, 1))

def _do_test(self, ddp_mode, simulate_uneven_inputs=False):
    if self.rank == MASTER_RANK:
        self._master_process(ddp_mode, simulate_uneven_inputs)
    elif self.rank == REMOTE_WORKER_RANK:
        self._remote_worker_process(ddp_mode)
    elif <MASK>:
        self._trainer_process(self.rank)
    else:
        raise RuntimeError(f'Unknown process rank: {self.rank}')

def _make_decorator(*m_args, **m_kwargs):

    def _decorator(view_func):
        middleware = middleware_class(view_func, *m_args, **m_kwargs)

        def _pre_process_request(request, *args, **kwargs):
            if hasattr(middleware, 'process_request'):
                result = middleware.process_request(request)
                if result is not None:
                    return result
            if hasattr(middleware, 'process_view'):
                result = middleware.process_view(request, view_func, args, kwargs)
                if result is not None:
                    return result
            return None

        def _process_exception(request, exception):
            if hasattr(middleware, 'process_exception'):
                result = middleware.process_exception(request, exception)
                if result is not None:
                    return result
            raise

        def _post_process_request(request, response):
            if hasattr(response, 'render') and callable(response.render):
                if hasattr(middleware, 'process_template_response'):
                    response = middleware.process_template_response(request, response)
                if <MASK>:

                    def callback(response):
                        return middleware.process_response(request, response)
                    response.add_post_render_callback(callback)
            elif hasattr(middleware, 'process_response'):
                return middleware.process_response(request, response)
            return response
        if iscoroutinefunction(view_func):

            async def _view_wrapper(request, *args, **kwargs):
                result = _pre_process_request(request, *args, **kwargs)
                if result is not None:
                    return result
                try:
                    response = await view_func(request, *args, **kwargs)
                except Exception as e:
                    result = _process_exception(request, e)
                    if result is not None:
                        return result
                return _post_process_request(request, response)
        else:

            def _view_wrapper(request, *args, **kwargs):
                result = _pre_process_request(request, *args, **kwargs)
                if result is not None:
                    return result
                try:
                    response = view_func(request, *args, **kwargs)
                except Exception as e:
                    result = _process_exception(request, e)
                    if result is not None:
                        return result
                return _post_process_request(request, response)
        return wraps(view_func)(_view_wrapper)
    return _decorator

def _multilabelmarginloss_reference(input, target):
    targets = []
    for target_index in target:
        if <MASK>:
            break
        targets.append(target_index)
    sum = 0
    for target_index in targets:
        for i in range(len(input)):
            if i not in targets:
                sum += max(0, 1 - input[target_index] + input[i])
    return sum

@property
def input_spec(self):
    if hasattr(self, '_manual_input_spec'):
        return self._manual_input_spec
    if <MASK>:
        return None
    if isinstance(self._nested_inputs, dict):
        names = sorted(self._nested_inputs.keys())
        return [input_spec.InputSpec(shape=shape_with_no_batch_size(self._nested_inputs[name]), allow_last_axis_squeeze=True, name=name) for name in names]
    else:
        return [input_spec.InputSpec(shape=shape_with_no_batch_size(x), allow_last_axis_squeeze=True, name=x._keras_history.layer.name) for x in self.inputs]

def l1_loss(input: Tensor, target: Tensor, size_average: Optional[bool]=None, reduce: Optional[bool]=None, reduction: str='mean', weight: Optional[Tensor]=None) -> Tensor:
    """Compute the L1 loss, with optional weighting.

    Function that takes the mean element-wise absolute value difference.

    See :class:`~torch.nn.L1Loss` for details.

    Args:
        input (Tensor): Predicted values.
        target (Tensor): Ground truth values.
        size_average (bool, optional): Deprecated (see :attr:`reduction`).
        reduce (bool, optional): Deprecated (see :attr:`reduction`).
        reduction (str, optional): Specifies the reduction to apply to the output:
                                   'none' | 'mean' | 'sum'. 'mean': the mean of the output is taken.
                                   'sum': the output will be summed. 'none': no reduction will be applied.
                                   Default: 'mean'.
        weight (Tensor, optional): Weights for each sample. Default: None.

    Returns:
        Tensor: L1 loss (optionally weighted).
    """
    if has_torch_function_variadic(input, target):
        return handle_torch_function(l1_loss, (input, target, weight), input, target, size_average=size_average, reduce=reduce, reduction=reduction)
    if target.size() != input.size():
        warnings.warn(f'Using a target size ({target.size()}) that is different to the input size ({input.size()}). This will likely lead to incorrect results due to broadcasting. Please ensure they have the same size.', stacklevel=2)
    if size_average is not None or reduce is not None:
        reduction = _Reduction.legacy_get_string(size_average, reduce)
    (expanded_input, expanded_target) = torch.broadcast_tensors(input, target)
    if weight is not None:
        if weight.size() != input.size():
            raise ValueError('Weights and input must have the same size.')
        absolute_errors = torch.abs(expanded_input - expanded_target)
        weighted_absolute_errors = absolute_errors * weight
        if reduction == 'none':
            return weighted_absolute_errors
        elif reduction == 'sum':
            return torch.sum(weighted_absolute_errors)
        elif <MASK>:
            return torch.sum(weighted_absolute_errors) / torch.sum(weight)
        else:
            raise ValueError(f"Invalid reduction mode: {reduction}. Expected one of 'none', 'mean', 'sum'.")
    else:
        return torch._C._nn.l1_loss(expanded_input, expanded_target, _Reduction.get_enum(reduction))

def _flatten_modules(self, recursive=True, include_self=True):
    """Flattens `tf.Module` instances (excluding `Metrics`).

    Args:
      recursive: Whether to recursively flatten through submodules.
      include_self: Whether to include this `Layer` instance.

    Yields:
      `tf.Module` instance tracked by this `Layer`.
    """
    if include_self:
        yield self
    trackables = getattr(self, '_self_tracked_trackables', None)
    if trackables:
        seen_object_ids = set()
        deque = collections.deque(trackables)
        while deque:
            trackable_obj = deque.popleft()
            trackable_id = id(trackable_obj)
            if trackable_id in seen_object_ids:
                continue
            seen_object_ids.add(trackable_id)
            if isinstance(trackable_obj, module.Module) and (not isinstance(trackable_obj, metrics_mod.Metric)):
                yield trackable_obj
                if recursive:
                    subtrackables = getattr(trackable_obj, '_self_tracked_trackables', None)
                    if <MASK>:
                        deque.extendleft(reversed(subtrackables))
            elif isinstance(trackable_obj, data_structures.TrackableDataStructure):
                tracked_values = trackable_obj._values
                if tracked_values:
                    deque.extendleft(reversed(tracked_values))

def _get_nseries(self, data: Series | DataFrame) -> int:
    if <MASK>:
        return 1
    elif self.by is not None and self._kind == 'hist':
        return len(self._grouped)
    elif self.by is not None and self._kind == 'box':
        return len(self.columns)
    else:
        return data.shape[1]

@classonlymethod
def as_view(cls, **initkwargs):
    """Main entry point for a request-response process."""
    for key in initkwargs:
        if <MASK>:
            raise TypeError('The method name %s is not accepted as a keyword argument to %s().' % (key, cls.__name__))
        if not hasattr(cls, key):
            raise TypeError('%s() received an invalid keyword %r. as_view only accepts arguments that are already attributes of the class.' % (cls.__name__, key))

    def view(request, *args, **kwargs):
        self = cls(**initkwargs)
        self.setup(request, *args, **kwargs)
        if not hasattr(self, 'request'):
            raise AttributeError("%s instance has no 'request' attribute. Did you override setup() and forget to call super()?" % cls.__name__)
        return self.dispatch(request, *args, **kwargs)
    view.view_class = cls
    view.view_initkwargs = initkwargs
    view.__doc__ = cls.__doc__
    view.__module__ = cls.__module__
    view.__annotations__ = cls.dispatch.__annotations__
    view.__dict__.update(cls.dispatch.__dict__)
    if cls.view_is_async:
        markcoroutinefunction(view)
    return view

def _track_symbol(self, node, composite_writes_alter_parent=False):
    if self._track_annotations_only and (not self._in_annotation):
        return
    if not anno.hasanno(node, anno.Basic.QN):
        return
    qn = anno.getanno(node, anno.Basic.QN)
    for l in self.state[_Comprehension]:
        if qn in l.targets:
            return
        if qn.owner_set & set(l.targets):
            return
    if isinstance(node.ctx, gast.Store):
        if <MASK>:
            self.state[_Comprehension].targets.add(qn)
            return
        self.scope.modified.add(qn)
        self.scope.bound.add(qn)
        if qn.is_composite and composite_writes_alter_parent:
            self.scope.modified.add(qn.parent)
        if self._in_aug_assign:
            self.scope.read.add(qn)
    elif isinstance(node.ctx, gast.Load):
        self.scope.read.add(qn)
        if self._in_annotation:
            self.scope.annotations.add(qn)
    elif isinstance(node.ctx, gast.Param):
        self.scope.bound.add(qn)
        self.scope.mark_param(qn, self.state[_FunctionOrClass].node)
    elif isinstance(node.ctx, gast.Del):
        self.scope.read.add(qn)
        self.scope.bound.add(qn)
        self.scope.deleted.add(qn)
    else:
        raise ValueError('Unknown context {} for node "{}".'.format(type(node.ctx), qn))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    """Fit Gaussian process regression model.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features) or list of object
            Feature vectors or other representations of training data.

        y : array-like of shape (n_samples,) or (n_samples, n_targets)
            Target values.

        Returns
        -------
        self : object
            GaussianProcessRegressor class instance.
        """
    if self.kernel is None:
        self.kernel_ = C(1.0, constant_value_bounds='fixed') * RBF(1.0, length_scale_bounds='fixed')
    else:
        self.kernel_ = clone(self.kernel)
    self._rng = check_random_state(self.random_state)
    if self.kernel_.requires_vector_input:
        (dtype, ensure_2d) = ('numeric', True)
    else:
        (dtype, ensure_2d) = (None, False)
    (X, y) = validate_data(self, X, y, multi_output=True, y_numeric=True, ensure_2d=ensure_2d, dtype=dtype)
    n_targets_seen = y.shape[1] if y.ndim > 1 else 1
    if self.n_targets is not None and n_targets_seen != self.n_targets:
        raise ValueError(f'The number of targets seen in `y` is different from the parameter `n_targets`. Got {n_targets_seen} != {self.n_targets}.')
    if self.normalize_y:
        self._y_train_mean = np.mean(y, axis=0)
        self._y_train_std = _handle_zeros_in_scale(np.std(y, axis=0), copy=False)
        y = (y - self._y_train_mean) / self._y_train_std
    else:
        shape_y_stats = (y.shape[1],) if y.ndim == 2 else 1
        self._y_train_mean = np.zeros(shape=shape_y_stats)
        self._y_train_std = np.ones(shape=shape_y_stats)
    if np.iterable(self.alpha) and self.alpha.shape[0] != y.shape[0]:
        if self.alpha.shape[0] == 1:
            self.alpha = self.alpha[0]
        else:
            raise ValueError(f'alpha must be a scalar or an array with same number of entries as y. ({self.alpha.shape[0]} != {y.shape[0]})')
    self.X_train_ = np.copy(X) if self.copy_X_train else X
    self.y_train_ = np.copy(y) if self.copy_X_train else y
    if self.optimizer is not None and self.kernel_.n_dims > 0:

        def obj_func(theta, eval_gradient=True):
            if eval_gradient:
                (lml, grad) = self.log_marginal_likelihood(theta, eval_gradient=True, clone_kernel=False)
                return (-lml, -grad)
            else:
                return -self.log_marginal_likelihood(theta, clone_kernel=False)
        optima = [self._constrained_optimization(obj_func, self.kernel_.theta, self.kernel_.bounds)]
        if self.n_restarts_optimizer > 0:
            if <MASK>:
                raise ValueError('Multiple optimizer restarts (n_restarts_optimizer>0) requires that all bounds are finite.')
            bounds = self.kernel_.bounds
            for iteration in range(self.n_restarts_optimizer):
                theta_initial = self._rng.uniform(bounds[:, 0], bounds[:, 1])
                optima.append(self._constrained_optimization(obj_func, theta_initial, bounds))
        lml_values = list(map(itemgetter(1), optima))
        self.kernel_.theta = optima[np.argmin(lml_values)][0]
        self.kernel_._check_bounds_params()
        self.log_marginal_likelihood_value_ = -np.min(lml_values)
    else:
        self.log_marginal_likelihood_value_ = self.log_marginal_likelihood(self.kernel_.theta, clone_kernel=False)
    K = self.kernel_(self.X_train_)
    K[np.diag_indices_from(K)] += self.alpha
    try:
        self.L_ = cholesky(K, lower=GPR_CHOLESKY_LOWER, check_finite=False)
    except np.linalg.LinAlgError as exc:
        exc.args = (f"The kernel, {self.kernel_}, is not returning a positive definite matrix. Try gradually increasing the 'alpha' parameter of your GaussianProcessRegressor estimator.",) + exc.args
        raise
    self.alpha_ = cho_solve((self.L_, GPR_CHOLESKY_LOWER), self.y_train_, check_finite=False)
    return self

def _astype_nansafe(arr: np.ndarray, dtype: DtypeObj, copy: bool=True, skipna: bool=False) -> ArrayLike:
    """
    Cast the elements of an array to a given dtype a nan-safe manner.

    Parameters
    ----------
    arr : ndarray
    dtype : np.dtype or ExtensionDtype
    copy : bool, default True
        If False, a view will be attempted but may fail, if
        e.g. the item sizes don't align.
    skipna: bool, default False
        Whether or not we should skip NaN when casting as a string-type.

    Raises
    ------
    ValueError
        The dtype was a datetime64/timedelta64 dtype, but it had no unit.
    """
    if isinstance(dtype, ExtensionDtype):
        return dtype.construct_array_type()._from_sequence(arr, dtype=dtype, copy=copy)
    elif not isinstance(dtype, np.dtype):
        raise ValueError('dtype must be np.dtype or ExtensionDtype')
    if arr.dtype.kind in 'mM':
        from pandas.core.construction import ensure_wrapped_if_datetimelike
        arr = ensure_wrapped_if_datetimelike(arr)
        res = arr.astype(dtype, copy=copy)
        return np.asarray(res)
    if issubclass(dtype.type, str):
        shape = arr.shape
        if arr.ndim > 1:
            arr = arr.ravel()
        return lib.ensure_string_array(arr, skipna=skipna, convert_na_value=False).reshape(shape)
    elif np.issubdtype(arr.dtype, np.floating) and dtype.kind in 'iu':
        return _astype_float_to_int_nansafe(arr, dtype, copy)
    elif <MASK>:
        if lib.is_np_dtype(dtype, 'M'):
            from pandas.core.arrays import DatetimeArray
            dta = DatetimeArray._from_sequence(arr, dtype=dtype)
            return dta._ndarray
        elif lib.is_np_dtype(dtype, 'm'):
            from pandas.core.construction import ensure_wrapped_if_datetimelike
            tdvals = array_to_timedelta64(arr).view('m8[ns]')
            tda = ensure_wrapped_if_datetimelike(tdvals)
            return tda.astype(dtype, copy=False)._ndarray
    if dtype.name in ('datetime64', 'timedelta64'):
        msg = f"The '{dtype.name}' dtype has no unit. Please pass in '{dtype.name}[ns]' instead."
        raise ValueError(msg)
    if copy or arr.dtype == object or dtype == object:
        return arr.astype(dtype, copy=True)
    return arr.astype(dtype, copy=copy)

def _codegen(self, nodes: list[BaseSchedulerNode]) -> None:
    if config.check_stack_no_cycles_TESTING_ONLY:
        import torch._dynamo.convert_frame
        stack = traceback.extract_stack()
        seen: OrderedSet[tuple[str, int | None]] = OrderedSet()
        for frame in reversed(stack):
            if frame.name == '_compile_inner' and frame.filename == torch._dynamo.convert_frame.__file__:
                break
            key = (frame.filename, frame.lineno)
            assert key not in seen, f'Duplicate stack frame {frame.filename}:{frame.lineno}; did you add a decorator to one of the functions in this stack trace?  If so, try using a context manager instead.'
            seen.add(key)
    self.current_device = self.default_device_context
    if self.default_device_context and config.triton.autotune_at_compile_time:
        V.graph.wrapper_code.write_get_raw_stream_header()
    for node in nodes:
        if <MASK>:
            try:
                log.debug('Generating code for node %s with estimated runtime %f', node.get_name(), node.get_estimated_runtime())
            except Exception:
                log.debug('Generating code for node %s with estimated runtime 0.0', node.get_name())
        self.enter_context(node)
        if (device := node.get_device()):
            if device != self.current_device or node.is_extern() or node.is_template():
                self.flush()
            if device != self.current_device:
                if self.current_device and device_need_guard(self.current_device.type):
                    V.graph.wrapper_code.codegen_device_guard_exit()
                self.current_device = device
                if device_need_guard(device.type):
                    assert device.index is not None, 'device should have an index'
                    V.graph.wrapper_code.codegen_device_guard_enter(device.index)
        self.current_node = node
        self.buffer_names_to_free.update(node.last_usage)
        if node.is_template():
            (prologue, template_node, epilogue) = node.get_prologue_template_epilogue(list(node.get_nodes()))
            self.get_backend(device).codegen_template(template_node, epilogue, prologue)
        elif node.is_extern():
            node = typing.cast(ExternKernelSchedulerNode, node)
            self.codegen_extern_call(node)
        elif node.is_foreach():
            node = typing.cast(ForeachKernelSchedulerNode, node)
            backend_ = self.get_backend(device)
            from .codegen.cuda_combined_scheduling import CUDACombinedScheduling
            from .codegen.simd import SIMDScheduling
            if isinstance(backend_, (SIMDScheduling, CUDACombinedScheduling)):
                backend = backend_
            else:
                raise AssertionError(f'type(self)={type(self)!r}')
            backend.codegen_combo_kernel(node)
        elif isinstance(node, (FusedSchedulerNode, SchedulerNode)):
            self.get_backend(device).codegen_node(node)
        else:
            assert isinstance(node, NopKernelSchedulerNode)
            node.mark_run()
        if config.triton.debug_sync_kernel:
            self.get_backend(device).codegen_sync()
        self.available_buffer_names.update(node.get_buffer_names())
        self.completed_operations.update(node.get_operation_names())
        if not isinstance(node, NopKernelSchedulerNode):
            device = node.get_device()
            if device is not None and device.type != 'meta' and self.get_backend(device).ready_to_flush():
                self.flush()
    if self.current_device != self.default_device_context:
        assert self.current_device is not None
        if device_need_guard(self.current_device.type):
            V.graph.wrapper_code.codegen_device_guard_exit()
    self.flush()

def test_partial_with_passed_fn_as_default(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')

    def f(x, y):
        return x(3) + y

    def my_func(a):
        return 2 * a
    func = def_function.function(functools.partial(f, my_func))
    root = autotrackable.AutoTrackable()
    root.f = func
    self.assertEqual(root.f(constant_op.constant(3)).numpy(), 9)
    root = cycle(root, cycles, use_cpp_bindings=use_cpp_bindings)
    self.assertEqual(root.f(constant_op.constant(3)).numpy(), 9)

