def get_samples(self):
    """Returns number of samples in the data, or `None`."""
    if <MASK>:
        return None
    total_sample = self.get_size() * self.batch_size()
    if self.has_partial_batch():
        total_sample -= self.batch_size() - self.partial_batch_size()
    return total_sample

