def callproc(self, procname, params=None, kparams=None):
    if kparams is not None and (not self.db.features.supports_callproc_kwargs):
        raise NotSupportedError('Keyword parameters for callproc are not supported on this database backend.')
    if not apps.ready and (not apps.stored_app_configs):
        warnings.warn(self.APPS_NOT_READY_WARNING_MSG, category=RuntimeWarning)
    self.db.validate_no_broken_transaction()
    with self.db.wrap_database_errors:
        if params is None and kparams is None:
            return self.cursor.callproc(procname)
        elif <MASK>:
            return self.cursor.callproc(procname, params)
        else:
            params = params or ()
            return self.cursor.callproc(procname, params, kparams)

def __repr__(self) -> str:
    info = ''
    if self.year is not None:
        info += f'year={self.year}, '
    info += f'month={self.month}, day={self.day}, '
    if <MASK>:
        info += f'offset={self.offset}'
    if self.observance is not None:
        info += f'observance={self.observance}'
    repr = f'Holiday: {self.name} ({info})'
    return repr

def batch_reduce_and_verify(self, inputs, expect, options):
    """Batch reduce the given `inputs` and verify the output matches `expect`.

    Args:
      inputs: a 2-level nested list of `Tensor` or `IndexedSlices`, where i-th
        value will be fed to i-th replica.
      expect: a list of `Tensor` or `IndexedSlices`. This should be the expected
        value for one replica.
      options: a `RunOpotions` instance.
    """

    def replica_fn():
        CollectiveReplicaLauncher._prefer_unique_instance_key = options.prefer_unique_instance_key
        (collective, devices, pid) = self.make_collective(options.num_processes, options.gpus_per_process)

        def batch_reduce_fn():
            batch_size = len(inputs[0])
            value_dst_pairs = []
            for i in range(batch_size):

                def value_fn(device_idx, idx=i):
                    return inputs[pid * len(devices) + device_idx][idx]
                per_replica_value = make_per_replica_value(value_fn, devices)
                value_dst_pairs.append((per_replica_value, per_replica_value))
            reduced_values = collective.batch_reduce(options.reduce_op, value_dst_pairs, options.communication_options)
            if options.gpus_per_process > 1:
                for v in reduced_values:
                    self.assertIsInstance(v, value_lib.Mirrored)
            reduced_values = [self.as_list(v) for v in reduced_values]
            for v in reduced_values:
                self.assertAllEqual(devices, [t.device for t in v])
            return nest.map_structure(ops.convert_to_tensor, reduced_values)
        per_replica_expect = nest.map_structure(lambda x: [ops.convert_to_tensor(x)] * len(devices), expect)
        if <MASK>:
            got = batch_reduce_fn()
            self.assertAllClose(got, per_replica_expect)
        if 'func_graph' in options.mode:
            got = def_function.function(batch_reduce_fn)()
            self.assertAllClose(got, per_replica_expect)
    get_global_mpr(options.num_processes).run(replica_fn)

def get_atlas_version(**config):
    libraries = config.get('libraries', [])
    library_dirs = config.get('library_dirs', [])
    key = (tuple(libraries), tuple(library_dirs))
    if key in _cached_atlas_version:
        return _cached_atlas_version[key]
    c = cmd_config(Distribution())
    atlas_version = None
    info = {}
    try:
        (s, o) = c.get_output(atlas_version_c_text, libraries=libraries, library_dirs=library_dirs)
        if s and re.search('undefined reference to `_gfortran', o, re.M):
            (s, o) = c.get_output(atlas_version_c_text, libraries=libraries + ['gfortran'], library_dirs=library_dirs)
            if not s:
                warnings.warn(textwrap.dedent('\n                    *****************************************************\n                    Linkage with ATLAS requires gfortran. Use\n\n                      python setup.py config_fc --fcompiler=gnu95 ...\n\n                    when building extension libraries that use ATLAS.\n                    Make sure that -lgfortran is used for C++ extensions.\n                    *****************************************************\n                    '), stacklevel=2)
                dict_append(info, language='f90', define_macros=[('ATLAS_REQUIRES_GFORTRAN', None)])
    except Exception:
        for o in library_dirs:
            m = re.search('ATLAS_(?P<version>\\d+[.]\\d+[.]\\d+)_', o)
            if m:
                atlas_version = m.group('version')
            if atlas_version is not None:
                break
        if <MASK>:
            atlas_version = os.environ.get('ATLAS_VERSION', None)
        if atlas_version:
            dict_append(info, define_macros=[('ATLAS_INFO', _c_string_literal(atlas_version))])
        else:
            dict_append(info, define_macros=[('NO_ATLAS_INFO', -1)])
        return (atlas_version or '?.?.?', info)
    if not s:
        m = re.search('ATLAS version (?P<version>\\d+[.]\\d+[.]\\d+)', o)
        if m:
            atlas_version = m.group('version')
    if atlas_version is None:
        if re.search('undefined symbol: ATL_buildinfo', o, re.M):
            atlas_version = '3.2.1_pre3.3.6'
        else:
            log.info('Status: %d', s)
            log.info('Output: %s', o)
    elif atlas_version == '3.2.1_pre3.3.6':
        dict_append(info, define_macros=[('NO_ATLAS_INFO', -2)])
    else:
        dict_append(info, define_macros=[('ATLAS_INFO', _c_string_literal(atlas_version))])
    result = _cached_atlas_version[key] = (atlas_version, info)
    return result

@staticmethod
def constant(value, dtype):
    if isinstance(value, ValueRanges):
        if not value.is_singleton():
            raise AssertionError('ValueRanges must be a singleton for constant()')
        value = value.lower
    is_python = isinstance(value, (int, float, bool))
    if not is_python and (not isinstance(value, (BooleanAtom, sympy.Integer, sympy.Number))):
        raise AssertionError(f'not a supported constant type: {type(value)}')
    if isinstance(value, SupportsFloat) and math.isnan(value):
        if dtype == torch.bool:
            return ValueRanges.unknown_bool()
        elif dtype.is_floating_point:
            return ValueRanges.unknown()
        else:
            return ValueRanges.unknown_int()
    if is_python:
        type_ = dtype_to_type(dtype)
        value = type_(value)
    elif dtype == torch.bool:
        if <MASK>:
            raise AssertionError('expected BooleanAtom for bool dtype')
    elif dtype.is_floating_point:
        if value.is_finite and (not value.is_real):
            raise AssertionError('expected float-like sympy value for float dtype')
    elif not getattr(value, 'is_integer', False):
        raise AssertionError('expected integer sympy value for int dtype')
    r = ValueRanges.wrap(value)
    return r

def _testParallelPartialInsertManyTakeManyCloseHalfwayThrough(self, cancel):
    with self.cached_session() as sess:
        b = data_flow_ops.Barrier((dtypes.float32, dtypes.int64), shapes=((), (2,)))
        num_iterations = 100
        keys = [str(x) for x in range(10)]
        values_0 = np.asarray(range(10), dtype=np.float32)
        values_1 = np.asarray([[x + 1, x + 2] for x in range(10)], dtype=np.int64)
        keys_i = lambda i: [('%d:%s' % (i, k)).encode('ascii') for k in keys]
        insert_0_ops = [b.insert_many(0, keys_i(i), values_0 + i, name='insert_0_%d' % i) for i in range(num_iterations)]
        close_op = b.close(cancel_pending_enqueues=cancel)
        take_ops = [b.take_many(10, name='take_%d' % i) for i in range(num_iterations)]
        insert_1_ops = [b.insert_many(1, keys_i(i), values_1 + i, name='insert_1_%d' % i) for i in range(num_iterations)]

        def take(sess, i, taken):
            if <MASK>:
                try:
                    (indices_val, unused_keys_val, unused_val_0, unused_val_1) = sess.run([take_ops[i][0], take_ops[i][1], take_ops[i][2][0], take_ops[i][2][1]])
                    taken.append(len(indices_val))
                except errors_impl.OutOfRangeError:
                    taken.append(0)
            else:
                (indices_val, unused_keys_val, unused_val_0, unused_val_1) = sess.run([take_ops[i][0], take_ops[i][1], take_ops[i][2][0], take_ops[i][2][1]])
                taken.append(len(indices_val))

        def insert_0(sess, i):
            insert_0_ops[i].run(session=sess)

        def insert_1(sess, i):
            if cancel:
                try:
                    insert_1_ops[i].run(session=sess)
                except errors_impl.CancelledError:
                    pass
            else:
                insert_1_ops[i].run(session=sess)
        taken = []
        take_threads = [self.checkedThread(target=take, args=(sess, i, taken)) for i in range(num_iterations)]
        insert_0_threads = [self.checkedThread(target=insert_0, args=(sess, i)) for i in range(num_iterations)]
        insert_1_threads = [self.checkedThread(target=insert_1, args=(sess, i)) for i in range(num_iterations)]
        for t in insert_0_threads:
            t.start()
        for t in insert_0_threads:
            t.join()
        for t in take_threads:
            t.start()
        close_op.run()
        for t in insert_1_threads:
            t.start()
        for t in take_threads:
            t.join()
        for t in insert_1_threads:
            t.join()
        if cancel:
            self.assertEqual(taken, [0] * num_iterations)
        else:
            self.assertEqual(taken, [10] * num_iterations)

def _convert_to_tensors_or_sparse_tensors(a, b):
    """Convert to tensor types, and flip order if necessary.

  Args:
    a: `Tensor` or `SparseTensor` of the same type as `b`.
    b: `Tensor` or `SparseTensor` of the same type as `a`.

  Returns:
    Tuple of `(a, b, flipped)`, where `a` and `b` have been converted to
    `Tensor` or `SparseTensor`, and `flipped` indicates whether the order has
    been flipped to make it dense,sparse instead of sparse,dense (since the set
    ops do not support the latter).
  """
    a = sparse_tensor.convert_to_tensor_or_sparse_tensor(a, name='a')
    if a.dtype.base_dtype not in _VALID_DTYPES:
        raise TypeError(f"'a' has invalid dtype `{a.dtype}` not in supported dtypes: `{_VALID_DTYPES}`.")
    b = sparse_tensor.convert_to_tensor_or_sparse_tensor(b, name='b')
    if b.dtype.base_dtype != a.dtype.base_dtype:
        raise TypeError("Types don't match, %s vs %s." % (a.dtype, b.dtype))
    if <MASK>:
        return (b, a, True)
    return (a, b, False)

def __torch_function__(self, func, types, args=(), kwargs=None):
    kwargs = kwargs if kwargs else {}
    if not isinstance(func, (torch._ops.OpOverloadPacket, torch._ops.OpOverload)):
        return func(*args, **kwargs)
    if torch.jit.is_tracing() or torch.jit.is_scripting() or torch._dynamo.is_compiling():
        return func(*args, **kwargs)
    if isinstance(func, torch._ops.OpOverloadPacket):
        func = resolve_unique_overload_or_throw(func)
    qualname = func.name()
    ns = qualname.split('::')[0]
    if <MASK>:
        return func(*args, **kwargs)
    (args_c, kwargs_c) = deepcopy_tensors((args, kwargs))
    result = func(*args, **kwargs)
    option = self.failures_dict.get_status(qualname, self.test_name)
    if option == 'xsuccess' or option == 'xfail':
        try:
            if qualname not in self.seen_ops_to_errors:
                self.seen_ops_to_errors[qualname] = []
            self.run_test_util(func, args_c, kwargs_c)
        except Exception as ex:
            if should_print_better_repro():
                self.seen_ops_to_errors[qualname].append((ex, func, args, kwargs))
            else:
                self.seen_ops_to_errors[qualname].append((ex, func, None, None))
    elif option == 'skip':
        pass
    return result

def finish(self, metadata: Metadata, results: list[list[WriteResult]]) -> None:
    if <MASK>:
        logger.info('Not consolidating sharded checkpoint in finish step.')
        return
    if self.save_distributed:
        fqn_to_index_mapping: dict[str, int] = self.fqn_to_index_mapping if self.fqn_to_index_mapping is not None else dict.fromkeys(metadata.state_dict_metadata.keys(), 1)
        return consolidate_safetensors_files(input_dir=str(self.path), output_dir=self.consolidated_output_path, num_threads=self.thread_count_consolidation, fqn_to_index_mapping=fqn_to_index_mapping)
    metadata_to_write = {}
    storage_md = {}
    total_size = 0
    for wr_list in results:
        storage_md.update({wr.index.fqn: wr.storage_data.relative_path for wr in wr_list})
        total_size += sum([wr.storage_data.length for wr in wr_list])
    metadata_to_write['metadata'] = {'total_size': total_size}
    metadata_to_write['weight_map'] = storage_md
    metadata_path = self.fs.concat_path(self.path, f'{_metadata_fn}')
    with self.fs.create_stream(metadata_path, 'w') as metadata_file:
        json.dump(metadata_to_write, metadata_file, indent=2)

