def bind_args_cached(func, tx, fn_source, args, kwargs):
    spec = _get_spec(func)
    spec.update_defaults(func)
    ba = {}
    rem_kw = dict(kwargs)
    for (i, name) in enumerate(spec.all_pos_names):
        if i < len(args):
            ba[name] = wrap_bound_arg(tx, args[i])
        elif name in rem_kw:
            if name in spec.posonly_names:
                raise_observed_exception(TypeError, tx, args=[ConstantVariable.create(f'{name} is positional-only')])
            ba[name] = wrap_bound_arg(tx, rem_kw.pop(name))
        elif name in spec.pos_default_map:
            idx = spec.pos_default_map[name]
            default_source = None
            if fn_source and (not (ConstantVariable.is_literal(spec.defaults[idx]) and config.skip_guards_on_constant_func_defaults)):
                default_source = DefaultsSource(fn_source, idx)
            ba[name] = wrap_bound_arg(tx, spec.defaults[idx], default_source)
        else:
            raise_observed_exception(TypeError, tx, args=[ConstantVariable.create(f'Missing required positional argument: {name}')])
    extra = args[len(spec.all_pos_names):]
    if spec.varargs_name:
        ba[spec.varargs_name] = wrap_bound_arg(tx, tuple(extra))
    elif extra:
        raise_observed_exception(TypeError, tx, args=[ConstantVariable.create(f'Too many positional arguments: got {len(args)}, expected {len(spec.all_pos_names)}')])
    for name in spec.kwonly_names:
        if name in rem_kw:
            ba[name] = wrap_bound_arg(tx, rem_kw.pop(name))
        elif <MASK>:
            kwdefault_source = None
            if fn_source:
                kwdefault_source = DefaultsSource(fn_source, name, is_kw=True)
            ba[name] = wrap_bound_arg(tx, spec.kwdefaults[name], kwdefault_source)
        else:
            raise_observed_exception(TypeError, tx, args=[ConstantVariable.create(f'Missing required keyword-only argument: {name}')])
    if spec.varkw_name:
        ba[spec.varkw_name] = wrap_bound_arg(tx, rem_kw)
    elif rem_kw:
        raise_observed_exception(TypeError, tx, args=[ConstantVariable.create(f'Unexpected keyword arguments: {list(rem_kw)}')])
    return ba

def _get_python_include_dirs() -> list[str]:
    include_dir = Path(sysconfig.get_path('include'))
    if not include_dir.exists() and platform.system() == 'Darwin':
        std_lib = Path(sysconfig.get_path('stdlib'))
        include_dir = (std_lib.parent.parent / 'Headers').absolute()
    if <MASK>:
        warnings.warn(f"Can't find Python.h in {str(include_dir)}")
    return [str(include_dir)]

def _post_process(self, paths, adjustable_paths, hashed_files):

    def path_level(name):
        return len(name.split(os.sep))
    for name in sorted(paths, key=path_level, reverse=True):
        substitutions = True
        (storage, path) = paths[name]
        with storage.open(path) as original_file:
            cleaned_name = self.clean_name(name)
            hash_key = self.hash_key(cleaned_name)
            if <MASK>:
                hashed_name = self.hashed_name(name, original_file)
            else:
                hashed_name = hashed_files[hash_key]
            if hasattr(original_file, 'seek'):
                original_file.seek(0)
            hashed_file_exists = self.exists(hashed_name)
            processed = False
            if name in adjustable_paths:
                old_hashed_name = hashed_name
                try:
                    content = original_file.read().decode('utf-8')
                except UnicodeDecodeError as exc:
                    yield (name, None, exc, False)
                for (extension, patterns) in self._patterns.items():
                    if matches_patterns(path, (extension,)):
                        for (pattern, template) in patterns:
                            converter = self.url_converter(name, hashed_files, template)
                            try:
                                content = pattern.sub(converter, content)
                            except ValueError as exc:
                                yield (name, None, exc, False)
                if hashed_file_exists:
                    self.delete(hashed_name)
                content_file = ContentFile(content.encode())
                if self.keep_intermediate_files:
                    self._save(hashed_name, content_file)
                hashed_name = self.hashed_name(name, content_file)
                if self.exists(hashed_name):
                    self.delete(hashed_name)
                saved_name = self._save(hashed_name, content_file)
                hashed_name = self.clean_name(saved_name)
                if old_hashed_name == hashed_name:
                    substitutions = False
                processed = True
            if not processed:
                if not hashed_file_exists:
                    processed = True
                    saved_name = self._save(hashed_name, original_file)
                    hashed_name = self.clean_name(saved_name)
            hashed_files[hash_key] = hashed_name
            yield (name, hashed_name, processed, substitutions)

def dtypes(self, *, device: Device | None=None, kind: str | tuple[str, ...] | None=None) -> dict[str, DType]:
    """
        The array API data types supported by NumPy.

        Note that this function only returns data types that are defined by
        the array API.

        Parameters
        ----------
        device : str, optional
            The device to get the data types for. For NumPy, only ``'cpu'`` is
            allowed.
        kind : str or tuple of str, optional
            The kind of data types to return. If ``None``, all data types are
            returned. If a string, only data types of that kind are returned.
            If a tuple, a dictionary containing the union of the given kinds
            is returned. The following kinds are supported:

            - ``'bool'``: boolean data types (i.e., ``bool``).
            - ``'signed integer'``: signed integer data types (i.e., ``int8``,
              ``int16``, ``int32``, ``int64``).
            - ``'unsigned integer'``: unsigned integer data types (i.e.,
              ``uint8``, ``uint16``, ``uint32``, ``uint64``).
            - ``'integral'``: integer data types. Shorthand for ``('signed
              integer', 'unsigned integer')``.
            - ``'real floating'``: real-valued floating-point data types
              (i.e., ``float32``, ``float64``).
            - ``'complex floating'``: complex floating-point data types (i.e.,
              ``complex64``, ``complex128``).
            - ``'numeric'``: numeric data types. Shorthand for ``('integral',
              'real floating', 'complex floating')``.

        Returns
        -------
        dtypes : dict
            A dictionary mapping the names of data types to the corresponding
            NumPy data types.

        See Also
        --------
        __array_namespace_info__.capabilities,
        __array_namespace_info__.default_device,
        __array_namespace_info__.default_dtypes,
        __array_namespace_info__.devices

        Examples
        --------
        >>> info = np.__array_namespace_info__()
        >>> info.dtypes(kind='signed integer')
        {'int8': numpy.int8,
         'int16': numpy.int16,
         'int32': numpy.int32,
         'int64': numpy.int64}

        """
    if device not in ['cpu', None]:
        raise ValueError(f'Device not understood. Only "cpu" is allowed, but received: {device}')
    if kind is None:
        return {'bool': dtype(bool), 'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'bool':
        return {'bool': dtype(bool)}
    if kind == 'signed integer':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if <MASK>:
