def _generate_unbacked_symbol_defs(self, line: WrapperLine) -> None:
    assert isinstance(line, UnbackedSymbolDefsLine)
    graph = self.gm.graph

    def convert_key(node: torch.fx.Node, path: pytree.KeyPath) -> torch.fx.Node:
        """
            Generate FX IR for each key entry.
            """
        if len(path) == 0:
            return node
        entry = path[0]
        if isinstance(entry, CallMethodKey):
            target = {'size': aten.sym_size.int, 'stride': aten.sym_stride.int, 'storage_offset': aten.sym_storage_offset}[entry.name]
            assert callable(target)
            node = graph.call_function(target, args=(node, path[1].idx) if len(path) > 1 and isinstance(path[1], pytree.SequenceKey) else (node,))
            return convert_key(node, path[1 + len(node.args):])
        elif <MASK>:
            node = graph.call_function(operator.getitem, args=(node, entry.idx))
            return convert_key(node, path[1:])
        elif isinstance(entry, DivideByKey):
            node = graph.call_function(operator.floordiv, args=(node, entry.divisor))
            return convert_key(node, path[1:])
        else:
            raise NotImplementedError(f'Unrecognized entry type: {type(entry)}')
    root_node = self.buffer_to_node[line.output_name]
    unbacked_bindings = line.unbacked_bindings
    assert unbacked_bindings is not None
    for (s, keypath) in unbacked_bindings.items():
        if s.name in self.buffer_to_node:
            continue
        node = convert_key(root_node, keypath)
        out_buffer = SymbolBuffer(s)
        self._record_allocation(out_buffer, node)
        self._generate_size_proxy(node, s)

def __init__(self, config, start=True):
    """Creates a new worker server.

    Args:
      config: A `tf.data.experimental.service.WorkerConfig` configuration.
      start: (Optional.) Boolean, indicating whether to start the server after
        creating it. Defaults to True.
    """
    if config.dispatcher_address is None:
        raise ValueError('Must specify a `dispatcher_address` in the `config` passed to `WorkerServer`.')
    if <MASK>:
        config_proto = config
    else:
        config_proto = service_config_pb2.WorkerConfig(dispatcher_address=config.dispatcher_address, worker_address=config.worker_address, port=config.port, protocol=config.protocol, heartbeat_interval_ms=config.heartbeat_interval_ms, dispatcher_timeout_ms=config.dispatcher_timeout_ms, data_transfer_protocol=config.data_transfer_protocol, data_transfer_address=config.data_transfer_address)
    self._server = _pywrap_server_lib.TF_DATA_NewWorkerServer(config_proto.SerializeToString())
    if start:
        self._server.start()

def _wrap_results(result, dtype: np.dtype, fill_value=None):
    """wrap our results if needed"""
    if result is NaT:
        pass
    elif dtype.kind == 'M':
        if fill_value is None:
            fill_value = iNaT
        if not isinstance(result, np.ndarray):
            assert not isna(fill_value), 'Expected non-null fill_value'
            if result == fill_value:
                result = np.nan
            if isna(result):
                result = np.datetime64('NaT', 'ns').astype(dtype)
            else:
                result = np.int64(result).view(dtype)
            result = result.astype(dtype, copy=False)
        else:
            result = result.astype(dtype)
    elif dtype.kind == 'm':
        if not isinstance(result, np.ndarray):
            if <MASK>:
                result = np.timedelta64('NaT').astype(dtype)
            elif np.fabs(result) > lib.i8max:
                raise ValueError('overflow in timedelta operation')
            else:
                result = np.int64(result).astype(dtype, copy=False)
        else:
            result = result.astype('m8[ns]').view(dtype)
    return result

def result_headers(cl):
    """
    Generate the list column headers.
    """
    ordering_field_columns = cl.get_ordering_field_columns()
    for (i, field_name) in enumerate(cl.list_display):
        (text, attr) = label_for_field(field_name, cl.model, model_admin=cl.model_admin, return_attr=True)
        is_field_sortable = cl.sortable_by is None or field_name in cl.sortable_by
        if attr:
            field_name = _coerce_field_name(field_name, i)
            if field_name == 'action_checkbox':
                aria_label = _('Select all objects on this page for an action')
                yield {'text': mark_safe(f'<input type="checkbox" id="action-toggle" aria-label="{aria_label}">'), 'class_attrib': mark_safe(' class="action-checkbox-column"'), 'sortable': False}
                continue
            admin_order_field = getattr(attr, 'admin_order_field', None)
            if isinstance(attr, property) and hasattr(attr, 'fget'):
                admin_order_field = getattr(attr.fget, 'admin_order_field', None)
            if not admin_order_field and LOOKUP_SEP not in field_name:
                is_field_sortable = False
        if not is_field_sortable:
            yield {'text': text, 'class_attrib': format_html(' class="column-{}"', field_name), 'sortable': False}
            continue
        th_classes = ['sortable', 'column-{}'.format(field_name)]
        order_type = ''
        new_order_type = 'asc'
        sort_priority = 0
        is_sorted = i in ordering_field_columns
        if <MASK>:
            order_type = ordering_field_columns.get(i).lower()
            sort_priority = list(ordering_field_columns).index(i) + 1
            th_classes.append('sorted %sending' % order_type)
            new_order_type = {'asc': 'desc', 'desc': 'asc'}[order_type]
        o_list_primary = []
        o_list_remove = []
        o_list_toggle = []

        def make_qs_param(t, n):
            return ('-' if t == 'desc' else '') + str(n)
        for (j, ot) in ordering_field_columns.items():
            if j == i:
                param = make_qs_param(new_order_type, j)
                o_list_primary.insert(0, param)
                o_list_toggle.append(param)
            else:
                param = make_qs_param(ot, j)
                o_list_primary.append(param)
                o_list_toggle.append(param)
                o_list_remove.append(param)
        if i not in ordering_field_columns:
            o_list_primary.insert(0, make_qs_param(new_order_type, i))
        yield {'text': text, 'sortable': True, 'sorted': is_sorted, 'ascending': order_type == 'asc', 'sort_priority': sort_priority, 'url_primary': cl.get_query_string({ORDER_VAR: '.'.join(o_list_primary)}), 'url_remove': cl.get_query_string({ORDER_VAR: '.'.join(o_list_remove)}), 'url_toggle': cl.get_query_string({ORDER_VAR: '.'.join(o_list_toggle)}), 'class_attrib': format_html(' class="{}"', ' '.join(th_classes)) if th_classes else ''}

def win_wrap_single_compile(sources, output_dir=None, macros=None, include_dirs=None, debug=0, extra_preargs=None, extra_postargs=None, depends=None):
    self.cflags = copy.deepcopy(extra_postargs)
    extra_postargs = None

    def spawn(cmd):
        src_regex = re.compile('/T(p|c)(.*)')
        src_list = [m.group(2) for m in (src_regex.match(elem) for elem in cmd) if m]
        obj_regex = re.compile('/Fo(.*)')
        obj_list = [m.group(1) for m in (obj_regex.match(elem) for elem in cmd) if m]
        include_regex = re.compile('((\\-|\\/)I.*)')
        include_list = [m.group(1) for m in (include_regex.match(elem) for elem in cmd) if m]
        if len(src_list) >= 1 and len(obj_list) >= 1:
            src = src_list[0]
            obj = obj_list[0]
            if _is_cuda_file(src):
                if <MASK>:
                    nvcc = _get_hipcc_path()
                else:
                    nvcc = _join_cuda_home('bin', 'nvcc')
                if isinstance(self.cflags, dict):
                    cflags = self.cflags['nvcc']
                elif isinstance(self.cflags, list):
                    cflags = self.cflags
                else:
                    cflags = []
                if IS_HIP_EXTENSION:
                    cflags = win_hip_flags(cflags)
                else:
                    cflags = win_cuda_flags(cflags) + ['-std=c++17', '--use-local-env']
                    for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                        cflags = ['-Xcudafe', '--diag_suppress=' + ignore_warning] + cflags
                for flag in COMMON_MSVC_FLAGS:
                    cflags = ['-Xcompiler', flag] + cflags
                cmd = [nvcc, '-c', src, '-o', obj] + include_list + cflags
            elif isinstance(self.cflags, dict):
                cflags = COMMON_MSVC_FLAGS + self.cflags['cxx']
                append_std17_if_no_std_present(cflags)
                cmd += cflags
            elif isinstance(self.cflags, list):
                cflags = COMMON_MSVC_FLAGS + self.cflags
                append_std17_if_no_std_present(cflags)
                cmd += cflags
        return original_spawn(cmd)
    try:
        self.compiler.spawn = spawn
        return original_compile(sources, output_dir, macros, include_dirs, debug, extra_preargs, extra_postargs, depends)
    finally:
        self.compiler.spawn = original_spawn

def flex_binary_moment(arg1, arg2, f, pairwise: bool=False):
    if isinstance(arg1, ABCSeries) and isinstance(arg2, ABCSeries):
        (X, Y) = prep_binary(arg1, arg2)
        return f(X, Y)
    elif isinstance(arg1, ABCDataFrame):
        from pandas import DataFrame

        def dataframe_from_int_dict(data, frame_template) -> DataFrame:
            result = DataFrame(data, index=frame_template.index)
            if len(result.columns) > 0:
                result.columns = frame_template.columns[result.columns]
            else:
                result.columns = frame_template.columns.copy()
            return result
        results = {}
        if isinstance(arg2, ABCDataFrame):
            if pairwise is False:
                if arg1 is arg2:
                    for i in range(len(arg1.columns)):
                        results[i] = f(arg1.iloc[:, i], arg2.iloc[:, i])
                    return dataframe_from_int_dict(results, arg1)
                else:
                    if not arg1.columns.is_unique:
                        raise ValueError("'arg1' columns are not unique")
                    if <MASK>:
                        raise ValueError("'arg2' columns are not unique")
                    (X, Y) = arg1.align(arg2, join='outer')
                    (X, Y) = prep_binary(X, Y)
                    res_columns = arg1.columns.union(arg2.columns)
                    for col in res_columns:
                        if col in X and col in Y:
                            results[col] = f(X[col], Y[col])
                    return DataFrame(results, index=X.index, columns=res_columns)
            elif pairwise is True:
                results = defaultdict(dict)
                for i in range(len(arg1.columns)):
                    for j in range(len(arg2.columns)):
                        if j < i and arg2 is arg1:
                            results[i][j] = results[j][i]
                        else:
                            results[i][j] = f(*prep_binary(arg1.iloc[:, i], arg2.iloc[:, j]))
                from pandas import concat
                result_index = arg1.index.union(arg2.index)
                if len(result_index):
                    result = concat([concat([results[i][j] for j in range(len(arg2.columns))], ignore_index=True) for i in range(len(arg1.columns))], ignore_index=True, axis=1)
                    result.columns = arg1.columns
                    if arg2.columns.nlevels > 1:
                        arg2.columns = cast(MultiIndex, arg2.columns)
                        result_level = np.tile(result_index, len(result) // len(result_index))
                        arg2_levels = (np.repeat(arg2.columns.get_level_values(i), len(result) // len(arg2.columns)) for i in range(arg2.columns.nlevels))
                        result_names = list(arg2.columns.names) + [result_index.name]
                        result.index = MultiIndex.from_arrays([*arg2_levels, result_level], names=result_names)
                        num_levels = len(result.index.levels)
                        new_order = [num_levels - 1] + list(range(num_levels - 1))
                        result = result.reorder_levels(new_order).sort_index()
                    else:
                        result.index = MultiIndex.from_product([range(len(arg2.columns)), range(len(result_index))])
                        result = result.swaplevel(1, 0).sort_index()
                        result.index = MultiIndex.from_product([result_index] + [arg2.columns])
                else:
                    result = DataFrame(index=MultiIndex(levels=[arg1.index, arg2.columns], codes=[[], []]), columns=arg2.columns, dtype='float64')
                result.columns = result.columns.set_names(arg1.columns.names)
                result.index = result.index.set_names(result_index.names + arg2.columns.names)
                return result
        else:
            results = {i: f(*prep_binary(arg1.iloc[:, i], arg2)) for i in range(len(arg1.columns))}
            return dataframe_from_int_dict(results, arg1)
    else:
        return flex_binary_moment(arg2, arg1, f)

def _compile_to_module(self) -> CompiledModule:
    (wrapper_code, _) = self.codegen_with_cpp_wrapper() if self.cpp_wrapper else self.codegen()
    if isinstance(wrapper_code, ValueWithLineMap):
        mod = self._compile_to_module_lines(wrapper_code)
    elif <MASK>:
        mod = wrapper_code
    else:
        raise NotImplementedError(f'Unrecognized wrapper code type: {type(wrapper_code)}')
    assert mod.__file__ is not None
    log_module_code(mod.__file__)
    log.debug('Output code written to: %s', mod.__file__)
    output_code_log.info('Output code written to: %s', mod.__file__)
    if config.benchmark_kernel:
        print(f'Compiled module path: {mod.__file__}', file=sys.stderr)
    if isinstance(wrapper_code, FileBackedGraphModule):
        V.debug.output_code(mod.__file__)
        V.debug.copy(os.path.splitext(mod.__file__)[0] + '.debug')
    return mod

