@staticmethod
def init(group: dist.ProcessGroup, fsdp_init_mode: FSDPInitMode, device_init_mode: DEVICEInitMode, fsdp_kwargs: Optional[dict[str, Any]]=None, deterministic: bool=False, add_bn: bool=True) -> Union[nn.Module, FSDP]:
    """
        Initializes a :class:`TransformerWithSharedParams` instance.

        Args:
            fsdp_init_mode (FSDPInitMode): If ``NO_FSDP``, then does not wrap
                any modules with FSDP. If ``RECURSIVE``, then wraps with
                top-level FSDP. By default, the top-level FSDP uses the
                ``ModuleWrapPolicy`` for encoder and decoder layers, but a
                different auto wrap policy may be specified via
                ``fsdp_kwargs``.
            device_init_mode (DEVICEInitMode): Determines model movement to DEVICE.
            fsdp_kwargs (Optional[Dict[str, Any]]): Optional keyword arguments
                forwarded to the FSDP constructor.
            deterministic (bool): Whether to make the model deterministic
                across constructions.
            add_bn (bool): Whether to include batch norm in the model.
        """
    if fsdp_kwargs is None:
        fsdp_kwargs = {}
    if fsdp_init_mode == FSDPInitMode.NO_FSDP:
        if isinstance(group, tuple):
            pg = group[0]
        else:
            pg = group
        return TransformerWithSharedParams(pg, device_init_mode, add_bn, deterministic)
    elif <MASK>:
        if 'auto_wrap_policy' not in fsdp_kwargs:
            auto_wrap_policy = ModuleWrapPolicy({TransformerEncoderLayer, TransformerDecoderLayer})
        else:
            auto_wrap_policy = fsdp_kwargs.pop('auto_wrap_policy')
        if 'sharding_strategy' in fsdp_kwargs and fsdp_kwargs['sharding_strategy'] in {ShardingStrategy.HYBRID_SHARD, ShardingStrategy._HYBRID_SHARD_ZERO2} and (not isinstance(group, tuple)):
            fsdp_pg = None
        else:
            fsdp_pg = group
        if isinstance(group, tuple):
            tformer_pg = group[0]
        else:
            tformer_pg = group
        m = TransformerWithSharedParams(tformer_pg, device_init_mode, add_bn, deterministic)
        fsdp_model = FSDP(m, fsdp_pg, auto_wrap_policy=auto_wrap_policy, **fsdp_kwargs)
        if device_init_mode == DEVICEInitMode.DEVICE_AFTER:
            fsdp_model = fsdp_model.to(DEVICE_TYPE)
        return fsdp_model
    raise ValueError(f'Unsupported FSDP init mode: {fsdp_init_mode}')

def has_effects(op, args, kwargs) -> bool:
    _skip_ops = {torch.ops.profiler._record_function_exit._RecordFunction}
    if <MASK>:
        return False
    return isinstance(op, (torch._ops.HigherOrderOperator, torch._ops.OpOverload)) and (not has_aliasing(op)) and (get_effect_key(op, args, kwargs) is not None)

def _store_sparse_tensors(tensor_list, enqueue_many, keep_input, shared_map_ops=None):
    """Store SparseTensors for feeding into batch, etc.

  If `shared_map_ops` is provided, the underlying `SparseTensorsMap` objects
  are reused (shared).  This argument is useful for, e.g., `batch_join`
  where multiple enqueue operations write to the same Queue component,
  and another (dequeue) thread reads from that same location and must then
  restore the associated `SparseTensor` objects.  In this case, the sparse
  restore must have a single `SparseTensorMap` from which to read out the
  handles; so a single `SparseTensorMap` must be shared for storing
  across the multiple enqueue operations.  This sharing is performed by
  calling `_store_sparse_tensors` the first time with `shared_map_ops=None`,
  and then in subsequent times with this value set to the list of `Operation`
  objects created in the first call.

  Args:
    tensor_list: List of `Tensor` and `SparseTensor` objects.
    enqueue_many: Python `Boolean`.
    keep_input: Must be a scalar bool Tensor (not a Python bool). If False,
      don't store.
    shared_map_ops: (optional) List of `Operation` objects from a previous
      call to `_store_sparse_tensors`.  If not `None`, the op types should be
      one of `AddSparseToTensorsMap` or `AddManySparseToTensorsMap` in the
      locations corresponding to `SparseTensors` in `tensor_list`.

  Returns:
    A tuple `(stored_list, sparse_info_list)` where `stored_list` is a list
    of `Tensor` objects (same length as `tensor_list`) and `sparse_info_list`
    is a list of the same length of `_SparseMetaData` objects.
  """
    maybe_shared_map_ops = shared_map_ops or [None] * len(tensor_list)

    def _sparse_meta_data(t, storing_op, map_op):
        if not isinstance(t, sparse_tensor.SparseTensor):
            return _SparseMetaData(False, None, None)
        rank = t.dense_shape.shape.with_rank(1).dims[0]
        if enqueue_many:
            rank -= 1
        return _SparseMetaData(sparse=True, map_op=map_op or storing_op, rank=rank)

    def _maybe_store(t, shared_map_op):
        """Store Sparse tensor, if necessary."""
        if not isinstance(t, sparse_tensor.SparseTensor):
            return t
        map_op_name = shared_map_op.name if shared_map_op else None

        def _maybe_store_sparse(t, map_op_name, keep_input):
            """Conditionally store a single sparse Tensor."""
            return utils.smart_cond(keep_input, lambda : _store_sparse(t, shared_name=map_op_name), lambda : constant_op.constant(-1, dtypes.int64))

        def _maybe_store_many_sparse(t, map_op_name, keep_input):
            """Conditionally store multiple sparse Tensors."""
            out_tensor = utils.smart_cond(keep_input, lambda : _store_many_sparse(t, shared_name=map_op_name), lambda : -1 * array_ops.ones(array_ops.shape(t)[0:1], dtypes.int64))
            out_tensor.set_shape([None])
            return out_tensor

        def _sparse_values_to_keep(t, keep_input):
            """Convert a per-row `keep_input` vector to a per-value one."""
            row_values = t.indices[:, 0]
            return array_ops.gather(keep_input, row_values)
        if <MASK>:
            t = sparse_ops.sparse_retain(t, _sparse_values_to_keep(t, keep_input))
            store_f = lambda t, name, _: _store_many_sparse(t, shared_name=name)
        elif enqueue_many:
            store_f = _maybe_store_many_sparse
        else:
            store_f = _maybe_store_sparse
        return store_f(t, map_op_name, keep_input)
    stored_list = [_maybe_store(t, shared_map_op) for (t, shared_map_op) in zip(tensor_list, maybe_shared_map_ops)]

    def _sparse_op(stored):
        for input_tensor in stored.op.inputs:
            if input_tensor.op.type in ('AddSparseToTensorsMap', 'AddManySparseToTensorsMap'):
                return input_tensor.op
        return stored.op
    sparse_info_list = [_sparse_meta_data(t, _sparse_op(stored), shared_map_op) for (t, stored, shared_map_op) in zip(tensor_list, stored_list, maybe_shared_map_ops)]
    stored_list = [array_ops.expand_dims(s, [-1]) if s_info.sparse else s for (s, s_info) in zip(stored_list, sparse_info_list)]
    return (stored_list, sparse_info_list)

def broadcast_shapes(shape1, shape2):
    assert len(shape1) > 0
    assert len(shape2) > 0
    s1 = list(shape1)
    s2 = list(shape2)
    if len(s1) > len(s2):
        raise Exception('Non-equal-rank broadcast is not supported yet.')
    if len(s2) > len(s1):
        raise Exception('Non-equal-rank broadcast is not supported yet.')
    ret = []
    for (d1, d2) in zip(s1, s2):
        if d1 == 1:
            ret.append(d2)
        elif <MASK>:
            ret.append(d1)
        elif d1 == d2:
            ret.append(d1)
        else:
            raise Exception(f'Cannot broadcast shapes: {shape1} and {shape2}')
    return tuple(ret)

def get_parameters(vars, global_params={}):
    params = copy.copy(global_params)
    g_params = copy.copy(global_params)
    for (name, func) in [('kind', _kind_func), ('selected_int_kind', _selected_int_kind_func), ('selected_real_kind', _selected_real_kind_func)]:
        if name not in g_params:
            g_params[name] = func
    param_names = []
    for n in get_sorted_names(vars):
        if 'attrspec' in vars[n] and 'parameter' in vars[n]['attrspec']:
            param_names.append(n)
    kind_re = re.compile('\\bkind\\s*\\(\\s*(?P<value>.*)\\s*\\)', re.I)
    selected_int_kind_re = re.compile('\\bselected_int_kind\\s*\\(\\s*(?P<value>.*)\\s*\\)', re.I)
    selected_kind_re = re.compile('\\bselected_(int|real)_kind\\s*\\(\\s*(?P<value>.*)\\s*\\)', re.I)
    for n in param_names:
        if '=' in vars[n]:
            v = vars[n]['=']
            if islogical(vars[n]):
                v = v.lower()
                for repl in [('.false.', 'False'), ('.true.', 'True')]:
                    v = v.replace(*repl)
            v = kind_re.sub('kind("\\1")', v)
            v = selected_int_kind_re.sub('selected_int_kind(\\1)', v)
            is_replaced = False
            if 'kindselector' in vars[n]:
                if 'kind' in vars[n]['kindselector']:
                    orig_v_len = len(v)
                    v = v.replace('_' + vars[n]['kindselector']['kind'], '')
                    is_replaced = len(v) < orig_v_len
            if not is_replaced:
                if not selected_kind_re.match(v):
                    v_ = v.split('_')
                    if len(v_) > 1:
                        v = ''.join(v_[:-1]).lower().replace(v_[-1].lower(), '')
            if isdouble(vars[n]):
                tt = list(v)
                for m in real16pattern.finditer(v):
                    tt[m.start():m.end()] = list(v[m.start():m.end()].lower().replace('d', 'e'))
                v = ''.join(tt)
            elif <MASK>:
                outmess(f'get_parameters[TODO]: implement evaluation of complex expression {v}\n')
            dimspec = ([s.removeprefix('dimension').strip() for s in vars[n]['attrspec'] if s.startswith('dimension')] or [None])[0]
            if real16pattern.search(v):
                v = 8
            elif real8pattern.search(v):
                v = 4
            try:
                params[n] = param_eval(v, g_params, params, dimspec=dimspec)
            except Exception as msg:
                params[n] = v
                outmess(f'get_parameters: got "{msg}" on {n!r}\n')
            if isstring(vars[n]) and isinstance(params[n], int):
                params[n] = chr(params[n])
            nl = n.lower()
            if nl != n:
                params[nl] = params[n]
        else:
            print(vars[n])
            outmess(f'get_parameters:parameter {n!r} does not have value?!\n')
    return params

def get_globals_in_pkl(file) -> set[str]:
    globals_in_checkpoint = set()
    read = file.read
    readline = file.readline
    op_to_bytes_to_read = {NEWOBJ[0]: 0, REDUCE[0]: 0, BUILD[0]: 0, APPEND[0]: 0, APPENDS[0]: 0, SETITEM[0]: 0, SETITEMS[0]: 0, MARK[0]: 0, TUPLE[0]: 0, TUPLE1[0]: 0, TUPLE2[0]: 0, TUPLE3[0]: 0, NONE[0]: 0, NEWFALSE[0]: 0, NEWTRUE[0]: 0, EMPTY_TUPLE[0]: 0, EMPTY_LIST[0]: 0, EMPTY_DICT[0]: 0, EMPTY_SET[0]: 0, BINPERSID[0]: 0, BININT[0]: 4, BININT1[0]: 1, BININT2[0]: 2, BINFLOAT[0]: 8, BINGET[0]: 1, LONG_BINGET[0]: 4, BINPUT[0]: 1, LONG_BINPUT[0]: 4}
    while True:
        key = read(1)
        if not key:
            raise EOFError
        assert isinstance(key, bytes_types)
        if <MASK>:
            (module, name) = _read_global_instruction(readline)
            globals_in_checkpoint.add(f'{module}.{name}')
        elif key[0] in op_to_bytes_to_read:
            bytes_to_read = op_to_bytes_to_read[key[0]]
            if bytes_to_read:
                read(bytes_to_read)
        elif key[0] == BINUNICODE[0]:
            strlen = unpack('<I', read(4))[0]
            if strlen > maxsize:
                raise UnpicklingError('String is too long')
            read(strlen)
        elif key[0] in {SHORT_BINSTRING[0], LONG1[0]}:
            strlen = read(1)[0]
            read(strlen)
        elif key[0] == PROTO[0]:
            read(1)[0]
        elif key[0] == STOP[0]:
            return globals_in_checkpoint
        else:
            raise UnpicklingError(f'Unsupported operand {key[0]}')

@register(Tags.caches, deploy=True)
def check_cache_location_not_exposed(app_configs, **kwargs):
    errors = []
    for name in ('MEDIA_ROOT', 'STATIC_ROOT', 'STATICFILES_DIRS'):
        setting = getattr(settings, name, None)
        if not setting:
            continue
        if name == 'STATICFILES_DIRS':
            paths = set()
            for staticfiles_dir in setting:
                if isinstance(staticfiles_dir, (list, tuple)):
                    (_, staticfiles_dir) = staticfiles_dir
                paths.add(pathlib.Path(staticfiles_dir).resolve())
        else:
            paths = {pathlib.Path(setting).resolve()}
        for alias in settings.CACHES:
            cache = caches[alias]
            if <MASK>:
                continue
            cache_path = pathlib.Path(cache._dir).resolve()
            if any((path == cache_path for path in paths)):
                relation = 'matches'
            elif any((path in cache_path.parents for path in paths)):
                relation = 'is inside'
            elif any((cache_path in path.parents for path in paths)):
                relation = 'contains'
            else:
                continue
            errors.append(Warning(f"Your '{alias}' cache configuration might expose your cache or lead to corruption of your data because its LOCATION {relation} {name}.", id='caches.W002'))
    return errors

@numba.jit(nopython=nopython, nogil=nogil, parallel=parallel)
def ewm(values: np.ndarray, begin: np.ndarray, end: np.ndarray, minimum_periods: int) -> np.ndarray:
    result = np.empty(len(values))
    alpha = 1.0 / (1.0 + com)
    old_wt_factor = 1.0 - alpha
    new_wt = 1.0 if adjust else alpha
    for i in numba.prange(len(begin)):
        start = begin[i]
        stop = end[i]
        window = values[start:stop]
        sub_result = np.empty(len(window))
        weighted = window[0]
        nobs = int(not np.isnan(weighted))
        sub_result[0] = weighted if nobs >= minimum_periods else np.nan
        old_wt = 1.0
        for j in range(1, len(window)):
            cur = window[j]
            is_observation = not np.isnan(cur)
            nobs += is_observation
            if not np.isnan(weighted):
                if is_observation or not ignore_na:
                    if normalize:
                        old_wt *= old_wt_factor ** deltas[start + j - 1]
                        if not adjust and com == 1:
                            new_wt = 1.0 - old_wt
                    else:
                        weighted = old_wt_factor * weighted
                    if <MASK>:
                        if normalize:
                            if weighted != cur:
                                weighted = old_wt * weighted + new_wt * cur
                                if normalize:
                                    weighted = weighted / (old_wt + new_wt)
                            if adjust:
                                old_wt += new_wt
                            else:
                                old_wt = 1.0
                        else:
                            weighted += cur
            elif is_observation:
                weighted = cur
            sub_result[j] = weighted if nobs >= minimum_periods else np.nan
        result[start:stop] = sub_result
    return result

@functools.wraps(inner_fn)
def wrapper(self: InstructionTranslatorBase, inst: Instruction) -> None:
    speculation = self.speculate()
    if <MASK>:
        assert speculation.reason is not None
        return handle_graph_break(self, inst, speculation.reason)
    try:
        return inner_fn(self, inst)
    except Unsupported as excp:
        if self.active_generic_context_managers:
            excp.remove_from_stats()
            unimplemented_v2(gb_type='Graph break under GenericContextWrappingVariable', context=f'Active generic context managers: {self.active_generic_context_managers}', explanation="Attempted to graph break in an active context manager(s) that doesn't support graph breaking.", hints=['Move the offending context manager(s) to outside the compiled region.', *graph_break_hints.CAUSED_BY_EARLIER_GRAPH_BREAK], from_exc=excp)
        if isinstance(excp, exc.UncapturedHigherOrderOpError):
            raise
        if not self.should_compile_partial_graph():
            raise
        log_graph_break(self.code_options, exc_info=True, reason=str(excp), user_stack=excp.real_stack, latest_bytecode_log='\n'.join(self.latest_bytecode_queue))
        if self.maybe_has_backedge():
            msg = f'Skipping frame because there is a graph break in a for/while loop\n{self.frame_summary()}'
            log.info(msg)
            raise exc.SkipFrame(msg) from excp
        excp.remove_from_stats()
        excp.add_to_stats('graph_break')
        speculation.reason = GraphCompileReason(excp.msg, excp.real_stack)
    speculation.fail_and_restart_analysis(self.error_on_graph_break)

def check_version(package: str) -> None:
    release_version = os.getenv('RELEASE_VERSION')
    if release_version:
        release_matrix = read_release_matrix()
        stable_version = release_matrix['torch']
    else:
        stable_version = os.getenv('MATRIX_STABLE_VERSION')
    if <MASK>:
        check_nightly_binaries_date(package)
    elif stable_version is not None:
        if not torch.__version__.startswith(stable_version):
            raise RuntimeError(f'Torch version mismatch, expected {stable_version} for channel {channel}. But its {torch.__version__}')
        if release_version and package == 'all':
            for module in MODULES:
                imported_module = importlib.import_module(module['name'])
                module_version = imported_module.__version__
                if not module_version.startswith(release_matrix[module['name']]):
                    raise RuntimeError(f"{module['name']} version mismatch, expected:                             {release_matrix[module['name']]} for channel {channel}. But its {module_version}")
                else:
                    print(f"{module['name']} version actual: {module_version} expected:                         {release_matrix[module['name']]} for channel {channel}.")
    else:
        print(f'Skip version check for channel {channel} as stable version is None')

