    jobs: dict[int, str] = {}
    page = 1
    while True:
        response = requests.get(f'{PYTORCH_REPO}/actions/runs/{workflow_id}/attempts/{workflow_run_attempt}/jobs', headers=_get_request_headers(), params={'page': page, 'per_page': 100})
        if <MASK>:
