def on_epoch_end(self, epoch, logs=None):
    """Checks if summary ops should run next epoch, logs scalar summaries."""
    logs = {'epoch_' + k: v for (k, v) in logs.items() if k not in ['batch', 'size', 'num_steps']}
    if self.update_freq == 'epoch':
        step = epoch
    else:
        step = self._samples_seen
    self._write_custom_summaries(step, logs)
    if self.histogram_freq:
        if self.merged in self.model.test_function.fetches:
            self.model.test_function.fetches.remove(self.merged)
        if self.merged in self.model.test_function.fetch_callbacks:
            self.model.test_function.fetch_callbacks.pop(self.merged)
    if self.embeddings_data is None and self.embeddings_freq:
        raise ValueError('To visualize embeddings, embeddings_data must be provided.')
    if self.embeddings_freq and self.embeddings_data is not None:
        if <MASK>:
            embeddings_data = self.embeddings_data
            n_samples = embeddings_data[0].shape[0]
            i = 0
            sess = K.get_session()
            while i < n_samples:
                step = min(self.batch_size, n_samples - i)
                batch = slice(i, i + step)
                if isinstance(self.model.input, list):
                    feed_dict = {model_input: embeddings_data[idx][batch] for (idx, model_input) in enumerate(self.model.input)}
                else:
                    feed_dict = {self.model.input: embeddings_data[0][batch]}
                feed_dict.update({self.batch_id: i, self.step: step})
                if not isinstance(K.learning_phase(), int):
                    feed_dict[K.learning_phase()] = False
                sess.run(self.assign_embeddings, feed_dict=feed_dict)
                self.saver.save(sess, os.path.join(self.log_dir, 'keras_embedding.ckpt'), epoch)
                i += self.batch_size

def _pyarrow_indexing(X, key, key_dtype, axis):
    """Index a pyarrow data."""
    scalar_key = np.isscalar(key)
    if isinstance(key, slice):
        if <MASK>:
            start = X.column_names.index(key.start)
            stop = X.column_names.index(key.stop) + 1
        else:
            start = 0 if not key.start else key.start
            stop = key.stop
        step = 1 if not key.step else key.step
        key = list(range(start, stop, step))
    if axis == 1:
        if key_dtype == 'int' and (not isinstance(key, list)):
            key = np.asarray(key).tolist()
        if key_dtype == 'bool':
            key = np.asarray(key).nonzero()[0].tolist()
        if scalar_key:
            return X.column(key)
        return X.select(key)
    if scalar_key:
        if hasattr(X, 'shape'):
            key = [key]
        else:
            return X[key].as_py()
    elif not isinstance(key, list):
        key = np.asarray(key)
    if key_dtype == 'bool':
        if PYARROW_VERSION_BELOW_17:
            import pyarrow
            if not isinstance(key, pyarrow.BooleanArray):
                key = pyarrow.array(key, type=pyarrow.bool_())
        X_indexed = X.filter(key)
    else:
        X_indexed = X.take(key)
    if scalar_key and len(getattr(X, 'shape', [0])) == 2:
        pa = sys.modules['pyarrow']
        return pa.array(X_indexed.to_pylist()[0].values())
    return X_indexed

@simple_wraps(flat_fn)
def wrapped_flat_fn(*args):
    unpacked_args = _unpack_synthetic_bases(args)
    aliased_args_with_metadata_mutations = [x for (i, x) in enumerate(unpacked_args) if i in self.aliased_arg_idx_with_metadata_mutations]
    (out, out_descs) = call_and_expect_output_descs(flat_fn, unpacked_args)
    if <MASK>:
        return ((*out, *aliased_args_with_metadata_mutations), (*out_descs, *[MetadataMutationAOTOutput(i) for i in range(len(self.aliased_arg_idx_with_metadata_mutations))]))
    else:
        return (out, out_descs)

def var_getattr(self, tx: 'InstructionTranslator', name: str) -> 'VariableTracker':
    from . import ConstantVariable, EnumVariable
    source = AttrSource(self.source, name) if self.source is not None else None
    if name == '__name__':
        return ConstantVariable.create(self.value.__name__)
    elif name == '__qualname__':
        return ConstantVariable.create(self.value.__qualname__)
    elif name == '__dict__':
        options = {'source': source}
        return variables.GetAttrVariable(self, name, **options)
    elif name == '__mro__':
        attr_source = self.source and TypeMROSource(self.source)
        return VariableTracker.build(tx, self.value.__mro__, attr_source)
    if self.value in {collections.OrderedDict, collections.defaultdict} and name == 'fromkeys':
        return super().var_getattr(tx, name)
    try:
        obj = inspect.getattr_static(self.value, name)
    except AttributeError:
        if type(self.value) is type:
            raise_observed_exception(AttributeError, tx, msg=f"type object '{self.value.__name__}' has no attribute '{name}'")
        else:
            obj = None
    if name == '__new__' and UserDefinedClassVariable.is_supported_new_method(obj):
        return super().var_getattr(tx, name)
    if name in cmp_name_to_op_mapping and (not isinstance(obj, types.FunctionType)):
        return variables.GetAttrVariable(self, name, source=source)
    if isinstance(obj, staticmethod):
        return VariableTracker.build(tx, obj.__get__(self.value), source)
    elif isinstance(obj, classmethod):
        if isinstance(obj.__func__, property):
            fget_vt = VariableTracker.build(tx, obj.__func__.fget)
            return fget_vt.call_function(tx, [self], {})
        return variables.UserMethodVariable(obj.__func__, self, source=source)
    elif isinstance(obj, types.ClassMethodDescriptorType):
        func = obj.__get__(None, self.value)
        return VariableTracker.build(tx, func, source)
    elif source:
        if inspect.ismemberdescriptor(obj):
            return VariableTracker.build(tx, obj.__get__(self.value), source)
    if ConstantVariable.is_literal(obj):
        return ConstantVariable.create(obj)
    elif isinstance(obj, enum.Enum):
        return EnumVariable(obj)
    elif <MASK>:
        return variables.GetAttrVariable(self, name)
    elif name in getattr(self.value, '__dict__', {}) or (self.value.__module__.startswith('torch.') or self.value.__module__ == 'torch'):
        if source:
            return VariableTracker.build(tx, obj, source)
    if source and (not inspect.ismethoddescriptor(obj)) and (not is_wrapper_or_member_descriptor(obj)):
        return VariableTracker.build(tx, obj, source)
    return super().var_getattr(tx, name)

def check_graph_breaks(actual_csv, expected_csv, expected_filename):
    failed = []
    improved = []
    if 'rocm' in expected_filename:
        flaky_models.update({'alexnet', 'demucs', 'densenet121', 'detectron2_fcos_r_50_fpn', 'doctr_det_predictor', 'doctr_reco_predictor', 'levit_128', 'llava', 'microbench_unbacked_tolist_sum', 'resnet50', 'resnet152', 'sam', 'sam_fast', 'stable_diffusion_text_encoder', 'stable_diffusion_unet', 'timm_efficientdet', 'torchrec_dlrm', 'vgg16', 'meta-llama/Llama-3.2-1B', 'google/gemma-2-2b', 'google/gemma-3-4b-it', 'openai/whisper-tiny', 'Qwen/Qwen3-0.6B', 'mistralai/Mistral-7B-Instruct-v0.3', 'openai/gpt-oss-20b'})
    for model in actual_csv['name']:
        graph_breaks = get_field(actual_csv, model, 'graph_breaks')
        expected_graph_breaks = get_field(expected_csv, model, 'graph_breaks')
        flaky = model in flaky_models
        if expected_graph_breaks is None:
            status = 'MISSING:'
            improved.append(model)
        elif graph_breaks == expected_graph_breaks:
            status = 'PASS_BUT_FLAKY' if flaky else 'PASS'
            print(f'{model:34}  {status}')
            continue
        elif graph_breaks > expected_graph_breaks:
            if flaky:
                status = 'FAIL_BUT_FLAKY:'
            else:
                status = 'FAIL:'
                failed.append(model)
        elif graph_breaks < expected_graph_breaks:
            if flaky:
                status = 'IMPROVED_BUT_FLAKY:'
            else:
                status = 'IMPROVED:'
                improved.append(model)
        print(f'{model:34}  {status:19} graph_breaks={graph_breaks}, expected={expected_graph_breaks}')
    msg = ''
    if failed or improved:
        if <MASK>:
            msg += textwrap.dedent(f"\n            Error: {len(failed)} models have new dynamo graph breaks:\n                {' '.join(failed)}\n\n            ")
        if improved:
            msg += textwrap.dedent(f"\n            Improvement: {len(improved)} models have fixed dynamo graph breaks:\n                {' '.join(improved)}\n\n            ")
        sha = os.getenv('SHA1', '{your CI commit sha}')
        msg += textwrap.dedent(f'\n        If this change is expected, you can update `{expected_filename}` to reflect the new baseline.\n        from pytorch/pytorch root, run\n        `python benchmarks/dynamo/ci_expected_accuracy/update_expected.py {sha}`\n        and then `git add` the resulting local changes to expected CSVs to your commit.\n        ')
    return (failed or improved, msg)

def gen_class(self, f: NativeFunction, k: SchemaKind, *, class_name: str, parent_class: str, generate_super: bool) -> str:
    if k is SchemaKind.functional:
        output_type = 'Tensor'
        output_value = 'outputs_[output_idx]'
        proxy_field = ''
    elif k is SchemaKind.inplace:
        output_type = 'std::reference_wrapper<Tensor>'
        output_value = 'proxy_outputs_[output_idx].has_value() ? *proxy_outputs_[output_idx] : outputs_[output_idx].get()'
        proxy_field = f'std::array<::std::optional<Tensor>, {len(f.func.returns)}> proxy_outputs_;'
    elif k is SchemaKind.out:
        output_type = 'std::reference_wrapper<Tensor>'
        output_value = 'proxy_outputs_[output_idx].has_value() ? *proxy_outputs_[output_idx] : outputs_[output_idx].get()'
        proxy_field = f'std::array<::std::optional<Tensor>, {len(f.func.returns)}> proxy_outputs_;'
    else:
        raise RuntimeError(f'Unsupported SchemaKind {k}')
    if self.backend_index.dispatch_key == DispatchKey.CUDA:
        if self.rocm:
            guard_field = 'c10::hip::OptionalHIPGuardMasqueradingAsCUDA guard_;'
        else:
            guard_field = 'c10::cuda::OptionalCUDAGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.MPS:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.XPU:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif <MASK>:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    else:
        guard_field = ''
    indent = ' ' * 4
    class_ctor_str = self.gen_class_ctor(k, class_name, len(f.func.returns))
    lines = (f'struct {class_name} final : public {parent_class} {{', f'{textwrap.indent(class_ctor_str, indent)}', f'{textwrap.indent(self.gen_class_set_output_functions(k, parent_class, generate_super), indent)}', '    const Tensor& maybe_get_output(int64_t output_idx) override {', f'      return {output_value};\n', '    }', f'    std::array<{output_type}, {len(f.func.returns)}> outputs_;', f'{textwrap.indent(proxy_field, indent)}', f'{textwrap.indent(guard_field, indent)}', '};')
    return '\n'.join((line for line in lines if line))

