def _post_forward(self, output):
    if self._use_python_reducer:
        return output
    if self._delay_all_reduce_all_params:
        self._clear_grad_buffer()
        return output
    if <MASK>:
        self._sync_buffers()
    if torch.is_grad_enabled() and self.require_backward_grad_sync:
        self.require_forward_param_sync = True
        if self.find_unused_parameters and (not self.static_graph):
            self.reducer.prepare_for_backward(list(_find_tensors(output)))
        else:
            self.reducer.prepare_for_backward([])
    else:
        self.require_forward_param_sync = False
    if self.find_unused_parameters and (not self.static_graph) or (self.static_graph and (not self._static_graph_delay_allreduce_enqueued)):
        (output_tensor_list, treespec, output_is_rref) = _tree_flatten_with_rref(output)
        output_placeholders: list[Optional[torch.Tensor]] = [None for _ in range(len(output_tensor_list))]
        for (i, output) in enumerate(output_tensor_list):
            if torch.is_tensor(output) and output.grad_fn is None:
                output_placeholders[i] = output
        passthrough_tensor_list = _DDPSink.apply(weakref.ref(self), *output_tensor_list)
        for i in range(len(output_placeholders)):
            if output_placeholders[i] is None:
                output_placeholders[i] = passthrough_tensor_list[i]
        output = _tree_unflatten_with_rref(output_placeholders, treespec, output_is_rref)
    self._clear_grad_buffer()
    return output

@register_decomposition(aten.addr)
@out_wrapper()
@elementwise_type_promotion_wrapper(type_promoting_args=('self', 'vec1', 'vec2'), type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
def addr(self: TensorLikeType, vec1: TensorLikeType, vec2: TensorLikeType, *, beta: NumberType=1, alpha: NumberType=1) -> TensorLikeType:
    torch._check(vec1.ndim == 1, lambda : f'addr: Expected 1-D argument vec1, but got {vec1.ndim}-D')
    torch._check(vec2.ndim == 1, lambda : f'addr: Expected 1-D argument vec2, but got {vec2.ndim}-D')
    for (arg, arg_name) in ((alpha, 'alpha'), (beta, 'beta')):
        if isinstance(arg, bool):
            torch._check(utils.is_boolean_dtype(self.dtype) and utils.is_boolean_dtype(vec1.dtype) and utils.is_boolean_dtype(vec2.dtype), lambda : f'Boolean {arg_name} only supported for Boolean results.')
    self = self.expand(vec1.shape[0], vec2.shape[0])
    if utils.is_boolean_dtype(self.dtype):
        torch._check(is_weakly_lesser_type(type(beta), int), lambda : f'expected bool/int beta but got {type(beta)}')
        torch._check(is_weakly_lesser_type(type(alpha), int), lambda : f'expected bool/int alpha but got {type(beta)}')
        if not beta:
            return torch.outer(vec1, vec2) if alpha else torch.full_like(self, False)
        else:
            return torch.logical_or(self, torch.outer(vec1, vec2) if alpha else torch.full_like(self, False))
    else:
        torch._check(is_weakly_lesser_type(type(beta), dtype_to_type(self.dtype)), lambda : f'cannot safely convert {type(beta)} to {self.dtype}')
        torch._check(is_weakly_lesser_type(type(alpha), dtype_to_type(self.dtype)), lambda : f'cannot safely convert {type(alpha)} to {self.dtype}')
        if <MASK>:
            return alpha * torch.outer(vec1, vec2)
        else:
            return beta * self + alpha * torch.outer(vec1, vec2)

def prettify_results(self, original_signature: inspect.Signature, dynamic_shapes: Union[dict[str, Any], tuple[Any], list[Any]], constraint_violation_error: object, forced_specializations: dict[str, str]) -> str:
    """Format a message for constraint violation errors"""
    from torch.export.dynamic_shapes import _get_dim_name_mapping
    if not self._dcp.source_name_to_debug_name:
        return ''

    def transform(s: str, inverse: bool=False) -> str:
        for (k, v) in self._dcp.source_name_to_debug_name.items():
            s = s.replace(k, v) if not inverse else s.replace(v, k)
        return s
    results: defaultdict[str, dict[str, Any]] = defaultdict(dict)
    if dynamic_shapes is None:
        dynamic_shapes = {}

    def flip(op: str) -> str:
        if op == '<=':
            return '>='
        if op == '>=':
            return '<='
        if op == '<':
            return '>'
        if op == '>':
            return '<'
        assert op == '=='
        return op

    def relation_with_digit(expr: str, op: str, digit: int) -> None:
        if op == '<=':
            results[expr]['max'] = digit
        elif op == '<':
            results[expr]['max'] = digit - 1
        elif op == '>=':
            results[expr]['min'] = digit
        elif op == '>':
            results[expr]['min'] = digit + 1
        else:
            assert op == '=='
            results[expr]['eq'] = digit
    name_to_dim = _get_dim_name_mapping(dynamic_shapes)
    for s in self._static_results.union(self._dynamic_results):
        t = transform(s)
        if t == s:
            continue
        (left, op, right) = re.split('( == | <= | >= | < | > )', t)
        op = op.strip()
        if op == '==' and left == right:
            continue
        if right.isdigit():
            relation_with_digit(left, op, int(right))
        elif left.isdigit():
            relation_with_digit(right, flip(op), int(left))
        else:
            assert op == '==', t
            try:
                results[left]['eq'] = sympy.sympify(right)
            except TypeError:
                pass
    forced_specializations = {k: forced_specializations[k] for k in sorted(forced_specializations.keys(), key=lambda x: x.split(' = ')[1])}
    buf = ''
    if forced_specializations:
        debug_names = set()
        for k in forced_specializations:
            dim = name_to_dim[k.split(' = ')[0]]
            if self._is_derived_dim(dim):
                debug_names.add(dim.root.__name__)
            else:
                debug_names.add(dim.__name__)
        buf += f"""Specializations unexpectedly required ({', '.join(sorted(debug_names))})! For more information, run with TORCH_LOGS="+dynamic".\n"""
        for (s, val) in forced_specializations.items():
            buf += f'  - solving the guards generated for {s} resulted in a specialized value of {val}.\n'
    self._process_derived_dim_roots(results, name_to_dim)
    dims = []
    others = []
    results2 = {k: results[k] for k in sorted(results.keys(), key=lambda x: transform(x, inverse=True))}
    for (k, c) in results2.items():
        if <MASK>:
            other = c['eq']
            if isinstance(other, int):
                others.append(f'{k} = {other}')
            elif _is_supported_equivalence(other):
                others.append(f'{k} = {other}')
        else:
            min_ = c.get('min', None)
            if min_ == 2:
                min_ = None
            max_ = c.get('max', None)
            if min_ is not None and max_ is not None:
                dims.append(f"{k} = Dim('{k}', min={min_}, max={max_})")
            elif min_ is not None:
                dims.append(f"{k} = Dim('{k}', min={min_})")
            elif max_ is not None:
                dims.append(f"{k} = Dim('{k}', max={max_})")
            else:
                dims.append(f"{k} = Dim('{k}')")
    if dims or others:
        buf += '\nSuggested fixes:\n  '
        buf += '\n  '.join(dims + others)
    return buf

def diff(self, other: 'SideEffects') -> Optional[str]:
    if self.id_to_variable != other.id_to_variable:
        sk_itv = self.id_to_variable.keys()
        ok_itv = other.id_to_variable.keys()
        if <MASK>:
            return f'id_to_variable keys: {sk_itv} != {ok_itv}'
        return 'id_to_variable: unknown diff'
    elif self.store_attr_mutations != other.store_attr_mutations:
        sk_sam = self.store_attr_mutations.keys()
        ok_sam = other.store_attr_mutations.keys()
        if sk_sam != ok_sam:
            return f'store_attr_mutations keys: {sk_sam} != {ok_sam}'
        return 'store_attr_mutations: unknown diff'
    elif self.save_for_backward != other.save_for_backward:
        return 'save_for_backward'
    elif self.tensor_hooks != other.tensor_hooks:
        return 'tensor_hooks'
    else:
        return None

def _check_inputs(self, arg_mbs: Optional[list]=None, kwarg_mbs: Optional[list]=None, target_mbs: Optional[list]=None, losses: Optional[list]=None) -> tuple[list, list]:
    """
        Pre-process/check inputs
        """

    def check_type_and_len(mbs, name: str):
        if not isinstance(mbs, list):
            raise TypeError(f'{name} must be a list but got a {type(mbs)}')
        if len(mbs) != self._n_microbatches:
            raise ValueError(f'Expecting {self._n_microbatches} {name} but got {len(mbs)}')
    if arg_mbs is not None:
        check_type_and_len(arg_mbs, 'arg_mbs')
    else:
        arg_mbs = [()] * self._n_microbatches
    if kwarg_mbs is not None:
        check_type_and_len(kwarg_mbs, 'kwarg_mbs')
    else:
        kwarg_mbs = [{}] * self._n_microbatches
    if target_mbs is not None:
        check_type_and_len(target_mbs, 'target_mbs')
    if losses is not None:
        if <MASK>:
            raise TypeError(f'losses must be a list but got a {type(losses)}')
    return (arg_mbs, kwarg_mbs)

def _diff_schema(dst, src):
    additions = {key: src[key] for key in src.keys() - dst.keys()}
    subtractions = {key: dst[key] for key in dst.keys() - src.keys()}
    common_keys = src.keys() & dst.keys()
    versions = {'SCHEMA_VERSION', 'TREESPEC_VERSION'}
    common_keys -= versions
    for key in common_keys:
        src_kind = src[key]['kind']
        src_fields = src[key]['fields']
        dst_kind = dst[key]['kind']
        dst_fields = dst[key]['fields']
        _check(src_kind == dst_kind, f'Type {key} changed kind from {dst_kind} to {src_kind}')
        assert isinstance(src_fields, dict) and isinstance(dst_fields, dict)
        added_fields = {key: src_fields[key] for key in src_fields.keys() - dst_fields.keys()}
        subtracted_fields = {key: dst_fields[key] for key in dst_fields.keys() - src_fields.keys()}
        common_fields = src_fields.keys() & dst_fields.keys()
        for field in common_fields:
            src_field = src_fields[field]
            dst_field = dst_fields[field]
            if src_kind == 'struct':
                _check(src_field['type'] == dst_field['type'], f"Type of the field {key}.{field} changed from {dst_field['type']} to {src_field['type']}")
                if 'default' in src_field and 'default' not in dst_field:
                    added_fields[field] = {}
                    added_fields[field]['default'] = src_field['default']
                if 'default' not in src_field and 'default' in dst_field:
                    subtracted_fields[field] = {}
                    subtracted_fields[field]['default'] = dst_field['default']
            elif src_kind == 'enum':
                _check(src_field == dst_field, f'Value of the enum field {key}.{field} changed from {dst_field} to {src_field}')
            elif src_kind == 'union':
                _check(src_field['type'] == dst_field['type'], f"Type of the field {key}.{field} changed from {dst_field['type']} to {src_field['type']}")
            else:
                raise AssertionError(f'Unknown kind {src_kind}: {key}')
        if <MASK>:
            assert key not in additions
            additions[key] = {}
            additions[key]['fields'] = added_fields
        if len(subtracted_fields) > 0:
            assert key not in subtractions
            subtractions[key] = {}
            subtractions[key]['fields'] = subtracted_fields
    return (additions, subtractions)

@staticmethod
def merge(*lists):
    """
        Merge lists while trying to keep the relative order of the elements.
        Warn if the lists have the same elements in a different relative order.

        For static assets it can be important to have them included in the DOM
        in a certain order. In JavaScript you may not be able to reference a
        global or in CSS you might want to override a style.
        """
    ts = TopologicalSorter()
    for (head, *tail) in filter(None, lists):
        ts.add(head)
        for item in tail:
            if <MASK>:
                ts.add(item, head)
            head = item
    try:
        return list(ts.static_order())
    except CycleError:
        warnings.warn('Detected duplicate Media files in an opposite order: {}'.format(', '.join((repr(list_) for list_ in lists))), MediaOrderConflictWarning)
        return list(dict.fromkeys(chain.from_iterable(filter(None, lists))))

def prod(x: Array, /, *, axis: Optional[Union[int, Tuple[int, ...]]]=None, dtype: Optional[DType]=None, keepdims: bool=False, **kwargs) -> Array:
    if <MASK>:
        return _sum_prod_no_axis(x, dtype)
    if isinstance(axis, tuple):
        return _reduce_multiple_axes(torch.prod, x, axis, keepdims=keepdims, dtype=dtype, **kwargs)
    if axis is None:
        res = torch.prod(x, dtype=dtype, **kwargs)
        res = _axis_none_keepdims(res, x.ndim, keepdims)
        return res
    return torch.prod(x, axis, dtype=dtype, keepdims=keepdims, **kwargs)

def find_patterns(node: Node, index_stack: list[int], current_pattern: list[Node], matched_patterns: list[list[Node]], seen: set[tuple[Node, tuple[int, ...]]]):
    """
        Traverse the graph recursively to match for the N-tuple - N-getitem patterns,
        starting at the given node.

        We use a stack to keep track of the expected `getitem` indices, since these are
        reversed from the `tuple` indices. In the above example, the stack after
        (b -> tuple -> tuple) will be [0, 1], which will be popped by getitem(1) first
        and then by getitem(0).

        TODO: traverse upwards from the output and handle the case when tuple is not a
        separate node, e.g. graph.call_function(operator.getitem, args=(a, (b, c)))
        """
    if len(index_stack) == 0 and len(current_pattern) > 0:
        matched_patterns.append(copy.copy(current_pattern))
        current_pattern.clear()
    state = (node, tuple(index_stack))
    if <MASK>:
        return
    seen.add(state)
    for user in node.users:
        if user.op == 'call_function' and user.target is tuple:
            for (i, user_arg) in enumerate(user.args[0]):
                if user_arg == node:
                    index_stack.append(i)
                    current_pattern.append(user)
                    find_patterns(user, index_stack, current_pattern, matched_patterns, seen)
        elif user.op == 'call_function' and user.target == operator.getitem:
            if len(index_stack) > 0:
                if user.args[1] == index_stack[-1]:
                    index_stack.pop()
                    current_pattern.append(user)
                    find_patterns(user, index_stack, current_pattern, matched_patterns, seen)
    return matched_patterns

@staticmethod
@contextlib.contextmanager
def current_frame(frame_summary: Optional[traceback.FrameSummary]) -> Generator[None, None, None]:
    tc = TracingContext.get()
    if frame_summary is not None:
        tc.frame_summary_stack.append(frame_summary)
    old = tc.loc_in_frame
    tc.loc_in_frame = None
    try:
        yield
    except Exception as e:
        if <MASK>:
            e.real_stack = tc.extract_stack()
        raise
    finally:
        if frame_summary is not None:
            tc.frame_summary_stack.pop()
        tc.loc_in_frame = old

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif name == 'extend' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if <MASK>:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
        if isinstance(idx, SymNodeVariable):
            const_idx = idx.evaluate_expr()
        else:
            const_idx = idx.as_python_constant()
        tx.output.side_effects.mutation(self)
        self.items.insert(const_idx, value)
        return ConstantVariable.create(None)
    elif name == 'pop' and self.is_mutable():
        if kwargs or len(args) > 1:
            raise_args_mismatch(tx, name, 'at most 1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if len(self.items) == 0:
            msg = ConstantVariable.create('pop from empty list')
            raise_observed_exception(IndexError, tx, args=[msg])
        if len(args):
            idx = args[0].as_python_constant()
            if idx > len(self.items):
                msg = ConstantVariable.create('pop index out of range')
                raise_observed_exception(IndexError, tx, args=[msg])
        tx.output.side_effects.mutation(self)
        return self.items.pop(*[a.as_python_constant() for a in args])
    elif name == 'clear' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        self.items.clear()
        return ConstantVariable.create(None)
    elif name == '__setitem__' and self.is_mutable() and args and (args[0].is_python_constant() or isinstance(args[0], SymNodeVariable) or (isinstance(args[0], SliceVariable) and all((s.is_python_constant() or isinstance(s, SymNodeVariable) for s in args[0].items)))):
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        (key, value) = args
        tx.output.side_effects.mutation(self)
        if isinstance(key, SymNodeVariable):
            self.items[key.evaluate_expr()] = value
        elif isinstance(key, SliceVariable):
            if key.is_python_constant():
                self.items[key.as_python_constant()] = list(value.items)
            else:
                items = slice(*[s.evaluate_expr() if isinstance(s, SymNodeVariable) else s.as_python_constant() for s in key.items])
                self.items[items] = list(value.items)
        else:
            self.items[key.as_python_constant()] = value
        return ConstantVariable.create(None)
    elif name == '__delitem__' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        if args[0].is_python_constant() and isinstance(args[0].as_python_constant(), (int, slice)):
            if isinstance(args[0], SymNodeVariable):
                idx = args[0].evaluate_expr()
            else:
                idx = args[0].as_python_constant()
            try:
                self.items.__delitem__(idx)
            except (IndexError, ValueError) as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            msg = ConstantVariable.create(f'list indices must be integers or slices, not {args[0].python_type_name()}')
            raise_observed_exception(TypeError, tx, args=[msg])
        return ConstantVariable.create(None)
    elif name == 'copy':
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        items = list(self.items)
        return self.modified(items, mutation_type=ValueMutationNew())
    elif name == 'reverse' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        self.items.reverse()
        tx.output.side_effects.mutation(self)
        return ConstantVariable.create(None)
    elif name == 'remove' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        idx = self.call_method(tx, 'index', args, kwargs)
        self.call_method(tx, 'pop', [idx], {})
        return ConstantVariable.create(None)
    else:
        return super().call_method(tx, name, args, kwargs)

def _model_loss(model, inputs, targets, output_loss_metrics=None, sample_weights=None, training=False):
    """Calculates the loss for a given model.

  Args:
      model: The model on which metrics are being calculated.
      inputs: Either a dictionary of inputs to the model or a list of input
        arrays.
      targets: List of target arrays.
      output_loss_metrics: List of metrics that are used to aggregated output
        loss values.
      sample_weights: Optional list of sample weight arrays.
      training: Whether the model should be run in inference or training mode.

  Returns:
     Returns the model output, total loss, loss value calculated using the
     specified loss function and masks for each output. The total loss includes
     regularization losses and applies masking and sample weighting
     to the loss value.
  """
    total_loss = 0
    kwargs = {}
    if model._expects_training_arg:
        kwargs['training'] = training
    if len(inputs) == 1 and (not isinstance(inputs, dict)):
        inputs = inputs[0]
    if any((isinstance(input_t, (np.ndarray, float, int)) for input_t in nest.flatten(inputs))):
        inputs = nest.map_structure(tensor_conversion.convert_to_tensor_v2_with_dispatch, inputs)
    outs = model(inputs, **kwargs)
    outs = nest.flatten(outs)
    if targets:
        targets = training_utils_v1.cast_if_floating_dtype_and_mismatch(targets, outs)
    if sample_weights:
        new_sample_weights = []
        for val in sample_weights:
            if val is not None:
                new_sample_weights.append(training_utils_v1.cast_if_floating_dtype(tensor_conversion.convert_to_tensor_v2_with_dispatch(val)))
            else:
                new_sample_weights.append(None)
        sample_weights = new_sample_weights
    masks = [getattr(t, '_keras_mask', None) for t in outs]
    targets = nest.flatten(targets)
    output_losses = []
    with backend.name_scope('loss'):
        loss_fns = [loss_fn for loss_fn in model.loss_functions if loss_fn is not None]
        custom_losses = model.losses
        if not loss_fns and (not custom_losses):
            if training:
                raise ValueError('The model cannot be trained because it has no loss to optimize.')
            else:
                raise ValueError('The model cannot be evaluated because it has no loss to compute.')
        for (i, loss_fn) in enumerate(loss_fns):
            weights = sample_weights[i] if sample_weights else None
            mask = masks[i]
            with backend.name_scope(model.output_names[i] + '_loss'):
                if mask is not None:
                    mask = math_ops.cast(mask, outs[i].dtype)
                    if weights is None:
                        weights = mask
                    else:
                        weights = math_ops.cast(weights, outs[i].dtype)
                        (mask, _, weights) = losses_utils.squeeze_or_expand_dimensions(mask, sample_weight=weights)
                        weights *= mask
                if hasattr(loss_fn, 'reduction'):
                    per_sample_losses = loss_fn.call(targets[i], outs[i])
                    weighted_losses = losses_utils.compute_weighted_loss(per_sample_losses, sample_weight=weights, reduction=losses_utils.ReductionV2.NONE)
                    loss_reduction = loss_fn.reduction
                    if loss_reduction == losses_utils.ReductionV2.AUTO:
                        loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
                    output_loss = losses_utils.reduce_weighted_loss(weighted_losses, reduction=loss_reduction)
                else:
                    output_loss = loss_fn(targets[i], outs[i], sample_weight=weights)
                    loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
            if <MASK>:
                output_losses.append(output_loss_metrics[i](output_loss))
            if loss_reduction == losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE:
                output_loss = losses_utils.scale_loss_for_distribution(output_loss)
            total_loss += model._loss_weights_list[i] * output_loss
        if custom_losses:
            total_loss += losses_utils.scale_loss_for_distribution(math_ops.add_n(custom_losses))
    return (outs, total_loss, output_losses, masks)

def initial_form_count(self):
    """Return the number of forms that are required in this FormSet."""
    if <MASK>:
        return self.management_form.cleaned_data[INITIAL_FORM_COUNT]
    else:
        initial_forms = len(self.initial) if self.initial else 0
    return initial_forms

def trace_structured(name: str, metadata_fn: Callable[[], Union[dict[str, Any], tuple[str, int]]]=dict, *, payload_fn: Callable[[], Optional[Union[str, object]]]=lambda : None, suppress_context: bool=False, expect_trace_id: bool=True, record_logging_overhead: bool=True, compile_id: Optional[CompileId]=None) -> None:
    """
    metadata is an arbitrary JSON compatible struct, but it's expected to not be
    too long (e.g., less than 1MB)

    payload is an arbitrary string, which can be arbitrarily long (but expected to have
    newlines so no lines are too long)
    """
    assert name not in ['rank', 'compiled_autograd_id', 'frame_id', 'frame_compile_id', 'attempt', 'severity', 'timestamp', 'pathname', 'thread']
    assert callable(metadata_fn), f'metadata_fn should be callable, but got {type(metadata_fn)}'
    assert callable(payload_fn), f'payload_fn should be callable, but got {type(payload_fn)}'
    if trace_log.handlers:
        start_time = time.time_ns()
        record: dict[str, object] = {}
        record[name] = metadata_fn()
        if not suppress_context:
            if dist.is_available() and dist.is_initialized():
                record['rank'] = dist.get_rank()
            trace_id = torch._guards.CompileContext.current_trace_id()
            if expect_trace_id and trace_id is None and (compile_id is None):
                record['stack'] = torch._logging.structured.from_traceback(CapturedTraceback.extract(skip=1).summary())
            else:
                cid = trace_id.compile_id if trace_id else compile_id
                if cid is not None:
                    if cid.compiled_autograd_id is not None:
                        record['compiled_autograd_id'] = cid.compiled_autograd_id
                    if cid.frame_id is not None:
                        record['frame_id'] = cid.frame_id
                    if cid.frame_compile_id is not None:
                        record['frame_compile_id'] = cid.frame_compile_id
                if <MASK>:
                    record['attempt'] = trace_id.attempt
        payload = payload_fn()
        if payload is not None:
            if not isinstance(payload, str):
                if isinstance(payload, list):
                    payload = '[\n' + ',\n'.join((json.dumps(i) for i in payload)) + '\n]'
                else:

                    def json_default(obj):
                        if isinstance(obj, set):
                            return list(obj)
                        raise TypeError(f'Object of type {type(obj)} is not JSON serializable')
                    payload = json.dumps(payload, default=json_default, indent=0)
            h = hashlib.md5(usedforsecurity=False)
            h.update(payload.encode('utf-8'))
            record['has_payload'] = h.hexdigest()
        trace_log.debug('', extra={'metadata': record, 'payload': payload}, stacklevel=2)
        log_trace_structured_event(name, record)
        if record_logging_overhead:
            structured_logging_overhead_s = (time.time_ns() - start_time) / 1000000000.0
            add_structured_logging_overhead(structured_logging_overhead_s)

