        data = None
    if not data and initial:
        return initial
    return super().clean(data)

def set_printer_args(self, args_to_print_or_save: list[str], kernel_name: str, arg_signatures: Optional[list[type]], kernel, kernel_type=None):
    if isinstance(kernel, MultiKernel):
        log.info('MultiKernel type is not supported in AOTI debug printer tool yet.')
        self.debug_printer_level = IntermediateValueDebuggingLevel.OFF
    self.kernel_type = kernel_type
    if kernel_type == 'extern':
        args_to_print_or_save_extern = [arg for arg in args_to_print_or_save if arg.startswith(('buf', 'arg'))]
        self.args_to_print_or_save = args_to_print_or_save_extern
    elif <MASK>:
        self.args_to_print_or_save = [f'copy_arrayref_tensor_to_tensor({arg})' if self.use_array_ref else arg for arg in args_to_print_or_save if arg.startswith(('buf', 'arg'))]
    else:
        self.args_to_print_or_save = args_to_print_or_save
    self.kernel_name = kernel_name
