def batchable_to_tensor_list(spec, value, minimum_rank=0):
    """Returns a list of tensors encoding `value`, whose type is `spec`."""
    if <MASK>:
        return [value]
    elif hasattr(spec, '__batch_encoder__'):
        encoded_value = spec.__batch_encoder__.encode(spec, value, minimum_rank)
        encoded_specs = spec.__batch_encoder__.encoding_specs(spec)
        encoded_flats = nest.map_structure(functools.partial(batchable_to_tensor_list, minimum_rank=minimum_rank), encoded_specs, encoded_value)
        return nest.flatten(encoded_flats)
    else:
        return spec._to_tensor_list(value)

def build_digest_header(self, method, url):
    """
        :rtype: str
        """
    realm = self._thread_local.chal['realm']
    nonce = self._thread_local.chal['nonce']
    qop = self._thread_local.chal.get('qop')
    algorithm = self._thread_local.chal.get('algorithm')
    opaque = self._thread_local.chal.get('opaque')
    hash_utf8 = None
    if algorithm is None:
        _algorithm = 'MD5'
    else:
        _algorithm = algorithm.upper()
    if _algorithm == 'MD5' or _algorithm == 'MD5-SESS':

        def md5_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.md5(x).hexdigest()
        hash_utf8 = md5_utf8
    elif _algorithm == 'SHA':

        def sha_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha1(x).hexdigest()
        hash_utf8 = sha_utf8
    elif <MASK>:

        def sha256_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha256(x).hexdigest()
        hash_utf8 = sha256_utf8
    elif _algorithm == 'SHA-512':

        def sha512_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha512(x).hexdigest()
        hash_utf8 = sha512_utf8
    KD = lambda s, d: hash_utf8(f'{s}:{d}')
    if hash_utf8 is None:
        return None
    entdig = None
    p_parsed = urlparse(url)
    path = p_parsed.path or '/'
    if p_parsed.query:
        path += f'?{p_parsed.query}'
    A1 = f'{self.username}:{realm}:{self.password}'
    A2 = f'{method}:{path}'
    HA1 = hash_utf8(A1)
    HA2 = hash_utf8(A2)
    if nonce == self._thread_local.last_nonce:
        self._thread_local.nonce_count += 1
    else:
        self._thread_local.nonce_count = 1
    ncvalue = f'{self._thread_local.nonce_count:08x}'
    s = str(self._thread_local.nonce_count).encode('utf-8')
    s += nonce.encode('utf-8')
    s += time.ctime().encode('utf-8')
    s += os.urandom(8)
    cnonce = hashlib.sha1(s).hexdigest()[:16]
    if _algorithm == 'MD5-SESS':
        HA1 = hash_utf8(f'{HA1}:{nonce}:{cnonce}')
    if not qop:
        respdig = KD(HA1, f'{nonce}:{HA2}')
    elif qop == 'auth' or 'auth' in qop.split(','):
        noncebit = f'{nonce}:{ncvalue}:{cnonce}:auth:{HA2}'
        respdig = KD(HA1, noncebit)
    else:
        return None
    self._thread_local.last_nonce = nonce
    base = f'username="{self.username}", realm="{realm}", nonce="{nonce}", uri="{path}", response="{respdig}"'
    if opaque:
        base += f', opaque="{opaque}"'
    if algorithm:
        base += f', algorithm="{algorithm}"'
    if entdig:
        base += f', digest="{entdig}"'
    if qop:
        base += f', qop="auth", nc={ncvalue}, cnonce="{cnonce}"'
    return f'Digest {base}'

def parse_cookie(cookie):
    """
    Return a dictionary parsed from a `Cookie:` header string.
    """
    cookiedict = {}
    for chunk in cookie.split(';'):
        if '=' in chunk:
            (key, val) = chunk.split('=', 1)
        else:
            (key, val) = ('', chunk)
        (key, val) = (key.strip(), val.strip())
        if <MASK>:
            cookiedict[key] = cookies._unquote(val)
    return cookiedict

def set_names(node_list, name_list, descriptor):
    if name_list is None:
        return
    if len(name_list) > len(node_list):
        raise RuntimeError(f'number of {descriptor} names provided ({len(name_list)}) exceeded number of {descriptor}s ({len(node_list)})')
    output_node_set = set()
    for (i, (name, node)) in enumerate(zip(name_list, node_list)):
        if <MASK>:
            if node in output_node_set:
                identity_node = graph.create('onnx::Identity')
                identity_node.insertAfter(node.node())
                identity_node.addInput(node)
                identity_node.output().setType(node.type())
                graph.return_node().replaceInput(i, identity_node.output())
                node = identity_node.output()
            output_node_set.add(node)
        if node.debugName() != name:
            node.setDebugName(name)

def _get_time_delta_bins(self, ax: TimedeltaIndex):
    if not isinstance(ax, TimedeltaIndex):
        raise TypeError(f'axis must be a TimedeltaIndex, but got an instance of {type(ax).__name__}')
    if <MASK>:
        raise ValueError(f"Resampling on a TimedeltaIndex requires fixed-duration `freq`, e.g. '24h' or '3D', not {self.freq}")
    if not len(ax):
        binner = labels = TimedeltaIndex(data=[], freq=self.freq, name=ax.name)
        return (binner, [], labels)
    (start, end) = (ax.min(), ax.max())
    if self.closed == 'right':
        end += self.freq
    labels = binner = timedelta_range(start=start, end=end, freq=self.freq, name=ax.name)
    end_stamps = labels
    if self.closed == 'left':
        end_stamps += self.freq
    bins = ax.searchsorted(end_stamps, side=self.closed)
    if self.offset:
        labels += self.offset
    return (binner, bins, labels)

