@classmethod
def __torch_function__(cls, func: Callable, types: tuple, args: tuple=(), kwargs: Optional[dict]=None) -> Any:
    if kwargs is None:
        kwargs = {}
    if <MASK>:
        if len(args) == 2 and (not kwargs) and isinstance(args[0], (_Tensor, torch.Tensor)) and isinstance(args[1], (_Tensor, torch.Tensor)):
            lhs_info = TensorInfo.create(args[0], ensure_batched=False, ensure_present=False)
            rhs_info = TensorInfo.create(args[1], ensure_batched=False, ensure_present=False)
            if lhs_info and rhs_info and (lhs_info.tensor is not None) and (rhs_info.tensor is not None) and (lhs_info.tensor.dim() == 0) and (rhs_info.tensor.dim() == 0):
                if lhs_info.tensor.is_floating_point() and rhs_info.tensor.is_floating_point():
                    has_device = lhs_info.has_device or rhs_info.has_device
                    levels = []
                    for level in lhs_info.levels:
                        if level not in levels:
                            levels.append(level)
                    for level in rhs_info.levels:
                        if level not in levels:
                            levels.append(level)
