def assert_variables_initialized(var_list=None):
    """Returns an Op to check if variables are initialized.

  NOTE: This function is obsolete and will be removed in 6 months.  Please
  change your implementation to use `report_uninitialized_variables()`.

  When run, the returned Op will raise the exception `FailedPreconditionError`
  if any of the variables has not yet been initialized.

  Note: This function is implemented by trying to fetch the values of the
  variables. If one of the variables is not initialized a message may be
  logged by the C++ runtime. This is expected.

  Args:
    var_list: List of `Variable` objects to check. Defaults to the value of
      `global_variables().`

  Returns:
    An Op, or None if there are no variables.
  """
    if var_list is None:
        var_list = global_variables() + local_variables()
    if not var_list:
        var_list = []
        for op in ops.get_default_graph().get_operations():
            if <MASK>:
                var_list.append(op.outputs[0])
    if not var_list:
        return None
    else:
        ranks = []
        for var in var_list:
            with ops.colocate_with(var.op):
                ranks.append(array_ops.rank_internal(var, optimize=False))
        if len(ranks) == 1:
            return ranks[0]
        else:
            return array_ops_stack.stack(ranks)

def _write_col_header(self, indent: int) -> None:
    row: list[Hashable]
    is_truncated_horizontally = self.fmt.is_truncated_horizontally
    if isinstance(self.columns, MultiIndex):
        template = 'colspan="{span:d}" halign="left"'
        sentinel: lib.NoDefault | bool
        if self.fmt.sparsify:
            sentinel = lib.no_default
        else:
            sentinel = False
        levels = self.columns._format_multi(sparsify=sentinel, include_names=False)
        level_lengths = get_level_lengths(levels, sentinel)
        inner_lvl = len(level_lengths) - 1
        for (lnum, (records, values)) in enumerate(zip(level_lengths, levels, strict=True)):
            if is_truncated_horizontally:
                ins_col = self.fmt.tr_col_num
                if self.fmt.sparsify:
                    recs_new = {}
                    for (tag, span) in list(records.items()):
                        if tag >= ins_col:
                            recs_new[tag + 1] = span
                        elif tag + span > ins_col:
                            recs_new[tag] = span + 1
                            if lnum == inner_lvl:
                                values = values[:ins_col] + ('...',) + values[ins_col:]
                            else:
                                values = values[:ins_col] + (values[ins_col - 1],) + values[ins_col:]
                        else:
                            recs_new[tag] = span
                        if tag + span == ins_col:
                            recs_new[ins_col] = 1
                            values = values[:ins_col] + ('...',) + values[ins_col:]
                    records = recs_new
                    inner_lvl = len(level_lengths) - 1
                    if lnum == inner_lvl:
                        records[ins_col] = 1
                else:
                    recs_new = {}
                    for (tag, span) in list(records.items()):
                        if tag >= ins_col:
                            recs_new[tag + 1] = span
                        else:
                            recs_new[tag] = span
                    recs_new[ins_col] = 1
                    records = recs_new
                    values = values[:ins_col] + ['...'] + values[ins_col:]
            row = [''] * (self.row_levels - 1)
            if self.fmt.index or self.show_col_idx_names:
                if <MASK>:
                    name = self.columns.names[lnum]
                    row.append(pprint_thing(name or ''))
                else:
                    row.append('')
            tags = {}
            j = len(row)
            for (i, v) in enumerate(values):
                if i in records:
                    if records[i] > 1:
                        tags[j] = template.format(span=records[i])
                else:
                    continue
                j += 1
                row.append(v)
            self.write_tr(row, indent, self.indent_delta, tags=tags, header=True)
    else:
        row = [''] * (self.row_levels - 1)
        if self.fmt.index or self.show_col_idx_names:
            if self.fmt.show_index_names:
                row.append(self.columns.name or '')
            else:
                row.append('')
        row.extend(self._get_columns_formatted_values())
        align = self.fmt.justify
        if is_truncated_horizontally:
            ins_col = self.row_levels + self.fmt.tr_col_num
            row.insert(ins_col, '...')
        self.write_tr(row, indent, self.indent_delta, header=True, align=align)

def deserialize_shape(val: Union[None, int, str]) -> Union[None, int, Dim, _DimHint]:
    if val is None or isinstance(val, int):
        return val
    elif val == '_DimHint.AUTO':
        return _DimHint.AUTO()
    elif val == '_DimHint.DYNAMIC':
        return _DimHint.DYNAMIC()
    elif <MASK>:
        return _DimHint.STATIC()
    if not isinstance(val, str):
        raise UserError(UserErrorType.INVALID_INPUT, f"Expected leaves in `spec['dynamic_shapes']` to be ints, None, Dim.AUTO/STATIC, symbols,  or derived expressions, got {val}")
    if val not in dim_cache:
        raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dynamic_shapes']` to be tracked in `spec['dims']`, got {val} which is not in {dims.keys()}")
    return dim_cache[val]

def check_files(code: str, config: str) -> list[LintMessage]:
    try:
        pyrefly_commands = ['pyrefly', 'check', '--config', config, '--output-format=json']
        proc = run_command([*pyrefly_commands], extra_env={}, retries=0)
    except OSError as err:
        return [LintMessage(path=None, line=None, char=None, code=code, severity=LintSeverity.ERROR, name='command-failed', original=None, replacement=None, description=f'Failed due to {err.__class__.__name__}:\n{err}')]
    stdout = str(proc.stdout, 'utf-8').strip()
    stderr = str(proc.stderr, 'utf-8').strip()
    if proc.returncode not in (0, 1):
        return [LintMessage(path=None, line=None, char=None, code=code, severity=LintSeverity.ERROR, name='command-failed', original=None, replacement=None, description=stderr)]
    try:
        if <MASK>:
            result = json.loads(stdout)
            errors = result.get('errors', [])
        else:
            errors = []
        errors = [error for error in errors if error['name'] != 'deprecated']
        rc = [LintMessage(path=error['path'], name=error['name'], description=error.get('description', error.get('concise_description', '')), line=error['line'], char=error['column'], code=code, severity=LintSeverity.ADVICE, original=None, replacement=None) for error in errors]
    except (json.JSONDecodeError, KeyError, TypeError) as e:
        return [LintMessage(path=None, line=None, char=None, code=code, severity=LintSeverity.ERROR, name='json-parse-error', original=None, replacement=None, description=f'Failed to parse pyrefly JSON output: {e}')]
    rc += [LintMessage(path=match['file'], name='INTERNAL ERROR', description=match['message'], line=int(match['line']), char=None, code=code, severity=severities.get(match['severity'], LintSeverity.ERROR), original=None, replacement=None) for match in INTERNAL_ERROR_RE.finditer(stderr)]
    return rc

def print_tensors_in_checkpoint_file(file_name, tensor_name, all_tensors, all_tensor_names=False, count_exclude_pattern=''):
    """Prints tensors in a checkpoint file.

  If no `tensor_name` is provided, prints the tensor names and shapes
  in the checkpoint file.

  If `tensor_name` is provided, prints the content of the tensor.

  Args:
    file_name: Name of the checkpoint file.
    tensor_name: Name of the tensor in the checkpoint file to print.
    all_tensors: Boolean indicating whether to print all tensors.
    all_tensor_names: Boolean indicating whether to print all tensor names.
    count_exclude_pattern: Regex string, pattern to exclude tensors from count.
  """
    try:
        reader = py_checkpoint_reader.NewCheckpointReader(file_name)
        if all_tensors or all_tensor_names:
            var_to_shape_map = reader.get_variable_to_shape_map()
            var_to_dtype_map = reader.get_variable_to_dtype_map()
            for (key, value) in sorted(var_to_shape_map.items()):
                print('tensor: %s (%s) %s' % (key, var_to_dtype_map[key].name, value))
                if all_tensors:
                    try:
                        print(reader.get_tensor(key))
                    except errors_impl.InternalError:
                        print('<not convertible to a numpy dtype>')
        elif not tensor_name:
            print(reader.debug_string().decode('utf-8', errors='ignore'))
        else:
            if not reader.has_tensor(tensor_name):
                print('Tensor %s not found in checkpoint' % tensor_name)
                return
            var_to_shape_map = reader.get_variable_to_shape_map()
            var_to_dtype_map = reader.get_variable_to_dtype_map()
            print('tensor: %s (%s) %s' % (tensor_name, var_to_dtype_map[tensor_name].name, var_to_shape_map[tensor_name]))
            print(reader.get_tensor(tensor_name))
        print('# Total number of params: %d' % _count_total_params(reader, count_exclude_pattern=count_exclude_pattern))
    except Exception as e:
        print(str(e))
        if <MASK>:
            print("It's likely that your checkpoint file has been compressed with SNAPPY.")
        if 'Data loss' in str(e) and any((e in file_name for e in ['.index', '.meta', '.data'])):
            proposed_file = '.'.join(file_name.split('.')[0:-1])
            v2_file_error_template = "\nIt's likely that this is a V2 checkpoint and you need to provide the filename\n*prefix*.  Try removing the '.' and extension.  Try:\ninspect checkpoint --file_name = {}"
            print(v2_file_error_template.format(proposed_file))

@staticmethod
def reduction_split_factor(device: torch.device, reduction_numel_hint: int, numel_hint: int, inner_reduction: bool) -> int:
    """Heuristic to decide the RSPLIT used for split reductions.
        When a reduction has a small number of outputs there is not enough parallelism,
        so we will do the reduction in two phases."""
    props = DeviceProperties.create(device)
    num_sm = props.multi_processor_count
    min_elements_per_thread = 32
    max_elements_per_thread = 512
    threads_per_sm = 2048
    min_elements_per_device = min_elements_per_thread * num_sm * threads_per_sm
    max_elements_per_device = max_elements_per_thread * num_sm * threads_per_sm
    num_warps = 8
    num_threads = 32 * num_warps
    if inner_reduction:
        if numel_hint >= 2 * num_sm:
            return 1
        if reduction_numel_hint <= 8192:
            return 1
        if reduction_numel_hint * numel_hint <= min_elements_per_device:
            split_size = min_elements_per_thread
        elif reduction_numel_hint * numel_hint < max_elements_per_device:
            target_blocks = num_sm * threads_per_sm // (2 * num_threads)
            blocks_per_output = (target_blocks + numel_hint - 1) // numel_hint
            tmp_split_size = (reduction_numel_hint + num_threads * blocks_per_output - 1) // (num_threads * blocks_per_output)
            divisors = sympy.divisors(reduction_numel_hint)
            closest = min(divisors, key=lambda x: abs(x - tmp_split_size))
            if abs(closest - tmp_split_size) < 30:
                split_size = max(closest, min_elements_per_thread)
            else:
                split_size = tmp_split_size
        else:
            divisors = sympy.divisors(reduction_numel_hint)
            closest = min(divisors, key=lambda x: abs(x - max_elements_per_thread))
            if <MASK>:
                split_size = closest
            else:
                split_size = max_elements_per_thread
        return (reduction_numel_hint + split_size * num_threads - 1) // (split_size * num_threads)
    else:
        rvals_per_thread = 4
        xvals_per_block = 128
        xblocks = (numel_hint + xvals_per_block - 1) // xvals_per_block
        if reduction_numel_hint * numel_hint < min_elements_per_device:
            split_size = min_elements_per_thread
        elif reduction_numel_hint * numel_hint < max_elements_per_device:
            target_blocks = num_sm * threads_per_sm // num_threads
            target_blocks = (target_blocks + xblocks - 1) // xblocks
            tmp_split_size = (reduction_numel_hint + rvals_per_thread * target_blocks - 1) // (rvals_per_thread * target_blocks)
            divisors = sympy.divisors(reduction_numel_hint)
            closest = min(divisors, key=lambda x: abs(x - tmp_split_size))
            if abs(tmp_split_size - closest) < 20:
                split_size = max(closest, min_elements_per_thread)
            else:
                split_size = tmp_split_size
        else:
            divisors = sympy.divisors(reduction_numel_hint)
            closest = min(divisors, key=lambda x: abs(x - max_elements_per_thread))
            if abs(closest - max_elements_per_thread) < 50:
                split_size = closest
            else:
                split_size = max_elements_per_thread
        return (reduction_numel_hint + rvals_per_thread * split_size - 1) // (rvals_per_thread * split_size)

def unsupported_input_tensor(t: torch.Tensor, node=None):
    """Do not support reading or writing to this tensor"""
    if t.is_complex():
        _warn_complex_not_supported()
        return True
    if <MASK>:
        return True
    if t.is_sparse:
        return True
    if t.dtype == torch.float8_e8m0fnu:
        if not node:
            return True
        return not (isinstance(node.target, torch._ops.OpOverload) and node.target in (aten.view.dtype, aten.cat.default, aten.clone.default, aten._scaled_mm.default) or (isinstance(node.target, torch._ops.OpOverload) and is_view(node.target)))
    return False

def __next__(self) -> Any:
    with torch.autograd.profiler.record_function(self._profile_name):
        if self._sampler_iter is None:
            self._reset()
        data = self._next_data()
        self._num_yielded += 1
        if self._dataset_kind == _DatasetKind.Iterable and self._IterableDataset_len_called is not None and (self._num_yielded > self._IterableDataset_len_called):
            warn_msg = f'Length of IterableDataset {self._dataset} was reported to be {self._IterableDataset_len_called}(when accessing len(dataloader)), but {self._num_yielded} samples have been fetched. '
            if <MASK>:
                warn_msg += 'For multiprocessing data-loading, this could be caused by not properly configuring the IterableDataset replica at each worker. Please see https://pytorch.org/docs/stable/data.html#torch.utils.data.IterableDataset for examples.'
            warnings.warn(warn_msg)
        return data

@contextlib.contextmanager
def _use_training_state(self, training_state: TrainingState, handle_training_state: HandleTrainingState):
    prev_training_state = self.training_state
    self.training_state = training_state
    if <MASK>:
        prev_handle_training_state = self._handle._training_state
        self._handle._training_state = handle_training_state
    try:
        yield
    finally:
        self.training_state = prev_training_state
        if self._handle:
            self._handle._training_state = prev_handle_training_state

def make_binary_op_tests(options, binary_operator, allow_fully_quantize=False, expected_tf_failures=0, test_parameters=None):
    """Make a set of tests to do binary ops with and without broadcast."""
    if test_parameters is None:
        test_parameters = []
    test_parameters = test_parameters + [{'dtype': [tf.float32, tf.int32], 'input_shape_1': [[1, 3, 4, 3]], 'input_shape_2': [[1, 3, 4, 3]], 'activation': [True], 'fully_quantize': [False], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[5]], 'input_shape_2': [[5]], 'activation': [False, True], 'fully_quantize': [False], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32, tf.int32, tf.int64], 'input_shape_1': [[1, 3, 4, 3]], 'input_shape_2': [[3]], 'activation': [True, False], 'fully_quantize': [False], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32, tf.int32], 'input_shape_1': [[3]], 'input_shape_2': [[1, 3, 4, 3]], 'activation': [True, False], 'fully_quantize': [False], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[]], 'input_shape_2': [[]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[1, 3, 4, 3]], 'input_shape_2': [[1, 3, 4, 3]], 'activation': [False], 'fully_quantize': [True], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[5]], 'input_shape_2': [[5]], 'activation': [False], 'fully_quantize': [True], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[1, 3, 4, 3]], 'input_shape_2': [[3]], 'activation': [False], 'fully_quantize': [True], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[3]], 'input_shape_2': [[1, 3, 4, 3]], 'activation': [False], 'fully_quantize': [True], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[]], 'input_shape_2': [[]], 'activation': [False], 'fully_quantize': [True], 'dynamic_range_quantize': [False]}, {'dtype': [tf.float32], 'input_shape_1': [[1, 3, 4, 3]], 'input_shape_2': [[1, 3, 4, 3]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [True]}, {'dtype': [tf.float32], 'input_shape_1': [[5]], 'input_shape_2': [[5]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [True]}, {'dtype': [tf.float32], 'input_shape_1': [[1, 3, 4, 3]], 'input_shape_2': [[3]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [True]}, {'dtype': [tf.float32], 'input_shape_1': [[3]], 'input_shape_2': [[1, 3, 4, 3]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [True]}, {'dtype': [tf.float32], 'input_shape_1': [[]], 'input_shape_2': [[]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [True]}]
    if options.run_with_flex:
        test_parameters = test_parameters + [{'dtype': [tf.float64], 'input_shape_1': [[7]], 'input_shape_2': [[7]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [False]}]
    if not options.skip_high_dimension_inputs:
        test_parameters = test_parameters + [{'dtype': [tf.float32], 'input_shape_1': [[8, 7, 6, 5, 4, 3, 2, 1], [8, 7, 6, 5, None, 3, 2, 1], [2, None]], 'input_shape_2': [[4, 3, 2, 1], [None, 3, 2, 1]], 'activation': [False], 'fully_quantize': [False], 'dynamic_range_quantize': [False], 'dynamic_size_value': [4, 1]}]
    if not allow_fully_quantize:
        test_parameters = [test_parameter for test_parameter in test_parameters if True not in test_parameter['fully_quantize']]

    def populate_dynamic_shape(parameters, input_shape):
        return [parameters['dynamic_size_value'] if x is None else x for x in input_shape]

    def build_graph(parameters):
        """Builds the graph given the current parameters."""
        input1 = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input1', shape=parameters['input_shape_1'])
        input2 = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input2', shape=parameters['input_shape_2'])
        out = binary_operator(input1, input2)
        if parameters['activation'] and (parameters['dtype'] != tf.int32 and parameters['dtype'] != tf.int64):
            out = tf.nn.relu(out)
        return ([input1, input2], [out])

    def build_inputs(parameters, sess, inputs, outputs):
        """Builds operand inputs for op."""
        input_shape_1 = populate_dynamic_shape(parameters, parameters['input_shape_1'])
        input_shape_2 = populate_dynamic_shape(parameters, parameters['input_shape_2'])
        if <MASK>:
            input1 = create_tensor_data(parameters['dtype'], input_shape_1, min_value=-1, max_value=1)
            input2 = create_tensor_data(parameters['dtype'], input_shape_2, min_value=-1, max_value=1)
        else:
            input1 = create_tensor_data(parameters['dtype'], input_shape_1)
            input2 = create_tensor_data(parameters['dtype'], input_shape_2)
        return ([input1, input2], sess.run(outputs, feed_dict={inputs[0]: input1, inputs[1]: input2}))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs, expected_tf_failures=expected_tf_failures)

def make_naive(value, timezone=None):
    """Make an aware datetime.datetime naive in a given time zone."""
    if <MASK>:
        timezone = get_current_timezone()
