def forward(self, src: Tensor, src_mask: Optional[Tensor]=None, src_key_padding_mask: Optional[Tensor]=None, is_causal: bool=False) -> Tensor:
    """Pass the input through the encoder layer.

        Args:
            src: the sequence to the encoder layer (required).
            src_mask: the mask for the src sequence (optional).
            src_key_padding_mask: the mask for the src keys per batch (optional).
            is_causal: If specified, applies a causal mask as ``src mask``.
                Default: ``False``.
                Warning:
                ``is_causal`` provides a hint that ``src_mask`` is the
                causal mask. Providing incorrect hints can result in
                incorrect execution, including forward and backward
                compatibility.

        Shape:
            see the docs in :class:`~torch.nn.Transformer`.
        """
    src_key_padding_mask = F._canonical_mask(mask=src_key_padding_mask, mask_name='src_key_padding_mask', other_type=F._none_or_dtype(src_mask), other_name='src_mask', target_type=src.dtype)
    src_mask = F._canonical_mask(mask=src_mask, mask_name='src_mask', other_type=None, other_name='', target_type=src.dtype, check_other=False)
    is_fastpath_enabled = torch.backends.mha.get_fastpath_enabled()
    why_not_sparsity_fast_path = ''
    if not is_fastpath_enabled:
        why_not_sparsity_fast_path = 'torch.backends.mha.get_fastpath_enabled() was not True'
    elif src.dim() != 3:
        why_not_sparsity_fast_path = f'input not batched; expected src.dim() of 3 but got {src.dim()}'
    elif self.training:
        why_not_sparsity_fast_path = 'training is enabled'
    elif not self.self_attn.batch_first:
        why_not_sparsity_fast_path = 'self_attn.batch_first was not True'
    elif self.self_attn.in_proj_bias is None:
        why_not_sparsity_fast_path = 'self_attn was passed bias=False'
    elif not self.self_attn._qkv_same_embed_dim:
        why_not_sparsity_fast_path = 'self_attn._qkv_same_embed_dim was not True'
    elif <MASK>:
        why_not_sparsity_fast_path = 'activation_relu_or_gelu was not True'
    elif self.norm1.eps != self.norm2.eps:
        why_not_sparsity_fast_path = 'norm1.eps is not equal to norm2.eps'
    elif src.is_nested and (src_key_padding_mask is not None or src_mask is not None):
        why_not_sparsity_fast_path = 'neither src_key_padding_mask nor src_mask are not supported with NestedTensor input'
    elif self.self_attn.num_heads % 2 == 1:
        why_not_sparsity_fast_path = 'num_head is odd'
    elif torch.is_autocast_enabled():
        why_not_sparsity_fast_path = 'autocast is enabled'
    elif any((len(getattr(m, '_forward_hooks', {})) + len(getattr(m, '_forward_pre_hooks', {})) for m in self.modules())):
        why_not_sparsity_fast_path = 'forward pre-/hooks are attached to the module'
    if not why_not_sparsity_fast_path:
        tensor_args = (src, self.self_attn.in_proj_weight, self.self_attn.in_proj_bias, self.self_attn.out_proj.weight, self.self_attn.out_proj.bias, self.norm1.weight, self.norm1.bias, self.norm2.weight, self.norm2.bias, self.linear1.weight, self.linear1.bias, self.linear2.weight, self.linear2.bias)
        _supported_device_type = ['cpu', 'cuda', torch.utils.backend_registration._privateuse1_backend_name]
        if torch.overrides.has_torch_function(tensor_args):
            why_not_sparsity_fast_path = 'some Tensor argument has_torch_function'
        elif not all((x.device.type in _supported_device_type for x in tensor_args)):
            why_not_sparsity_fast_path = f"some Tensor argument's device is neither one of {_supported_device_type}"
        elif torch.is_grad_enabled() and any((x.requires_grad for x in tensor_args)):
            why_not_sparsity_fast_path = 'grad is enabled and at least one of query or the input/output projection weights or biases requires_grad'
        if not why_not_sparsity_fast_path:
            (merged_mask, mask_type) = self.self_attn.merge_masks(src_mask, src_key_padding_mask, src)
            return torch._transformer_encoder_layer_fwd(src, self.self_attn.embed_dim, self.self_attn.num_heads, self.self_attn.in_proj_weight, self.self_attn.in_proj_bias, self.self_attn.out_proj.weight, self.self_attn.out_proj.bias, self.activation_relu_or_gelu == 2, self.norm_first, self.norm1.eps, self.norm1.weight, self.norm1.bias, self.norm2.weight, self.norm2.bias, self.linear1.weight, self.linear1.bias, self.linear2.weight, self.linear2.bias, merged_mask, mask_type)
    x = src
    if self.norm_first:
        x = x + self._sa_block(self.norm1(x), src_mask, src_key_padding_mask, is_causal=is_causal)
        x = x + self._ff_block(self.norm2(x))
    else:
        x = self.norm1(x + self._sa_block(x, src_mask, src_key_padding_mask, is_causal=is_causal))
        x = self.norm2(x + self._ff_block(x))
    return x

def _get_wheel_type(version):
    if <MASK>:
        return 'nightly'
