def _command_line_ok(_cache=None):
    """ Return True if command line does not contain any
    help or display requests.
    """
    if _cache:
        return _cache[0]
    elif <MASK>:
        _cache = []
    ok = True
    display_opts = ['--' + n for n in Distribution.display_option_names]
    for o in Distribution.display_options:
        if o[1]:
            display_opts.append('-' + o[1])
    for arg in sys.argv:
        if arg.startswith('--help') or arg == '-h' or arg in display_opts:
            ok = False
            break
    _cache.append(ok)
    return ok

@invoke_subgraph.py_impl(ProxyTorchDispatchMode)
def _(proxy_mode: ProxyTorchDispatchMode, subgraph, identifier, *operands):
    graph = None
    invoke_subgraph_cache = get_invoke_subgraph_cache()
    if invoke_subgraph_cache:
        graph = invoke_subgraph_cache.get_proxy_dispatch_entry(identifier)
    if graph is None:
        from torch._dynamo.utils import dynamo_timed
        with dynamo_timed('invoke_subgraph_proxy_tensor', log_pt2_compile_event=True):
            graph = reenter_make_fx(subgraph)(*operands)
        from torch._guards import detect_fake_mode
        fake_mode = detect_fake_mode(operands)
        assert fake_mode is not None and fake_mode.shape_env is not None
        insert_deferred_runtime_asserts(graph, fake_mode.shape_env, 'invoke_subgraph_proxy_torch_dispatch_mode', export=True)
        graph.recompile()
        assert isinstance(proxy_mode.tracer, torch.fx.Tracer)
        if invoke_subgraph_cache:
            invoke_subgraph_cache.add_proxy_dispatch_entry(identifier, graph)
    node_args = (graph, identifier, *operands)

    def _unwrap_proxy(arg):
        if isinstance(arg, torch.fx.GraphModule):
            registered_before = False
            for (_, submod) in proxy_mode.tracer.root.named_modules():
                if <MASK>:
                    registered_before = True
            if not registered_before:
                qualname = proxy_mode.tracer.get_fresh_qualname('repeated_subgraph')
                proxy_mode.tracer.root.register_module(qualname, arg)
        return proxy_mode.tracer.unwrap_proxy(arg)
    proxy_args = pytree.tree_map(_unwrap_proxy, node_args)
    out_proxy = proxy_mode.tracer.create_proxy('call_function', invoke_subgraph, proxy_args, {})
    example_out = invoke_subgraph(graph, identifier, *operands)
    return track_tensor_tree(example_out, out_proxy, constant=None, tracer=proxy_mode.tracer)

def calculate_flops(op_name: str, shape: tuple[int, int, int], batch_size: int) -> int:
    """
    Calculate the number of floating point operations based on operation type and shape.
    """
    (M, N, K) = shape
    if op_name == 'bmm':
        return 2 * batch_size * M * N * K
    elif <MASK>:
        return 2 * M * N * K + M * N
    elif op_name == '_scaled_mm':
        return 2 * M * N * K
    else:
        return 2 * M * N * K

def get(identifier):
    """Get a loss scale object."""
    if isinstance(identifier, dict):
