    if <MASK>:
        return loss_scale_module.FixedLossScale(identifier)
    if identifier == 'dynamic':
        return loss_scale_module.DynamicLossScale()
    if isinstance(identifier, loss_scale_module.LossScale):
        return identifier
    elif identifier is None:
        return None
    else:
        raise ValueError('Could not interpret loss scale identifier: %s' % identifier)

def check_outer_fusion_loop_level_attr(self, cpp_kernel_proxy_list, outer_loop_fusion_depth):

    def _inner(left_loop_nest: LoopNest, right_loop_nest: LoopNest, loop_fusion_depth: int, current_checking_depth: int) -> bool:
        assert left_loop_nest.loops
        assert right_loop_nest.loops
        left_loop_level = left_loop_nest.loops[current_checking_depth]
        right_loop_level = right_loop_nest.loops[current_checking_depth]
        outer_loops_attr_compare_list = ['var', 'size', 'offset', 'steps']
        if not all((getattr(left_loop_level, attr_compare) == getattr(right_loop_level, attr_compare) for attr_compare in outer_loops_attr_compare_list)):
            return False
        assert loop_fusion_depth >= 1
        if (loop_fusion_depth := (loop_fusion_depth - 1)) > 0:
            current_checking_depth = current_checking_depth + 1
            assert current_checking_depth < len(left_loop_nest.loops)
            assert current_checking_depth < len(right_loop_nest.loops)
            if not _inner(left_loop_nest, right_loop_nest, loop_fusion_depth, current_checking_depth):
                return False
        return True
    for idx in range(len(cpp_kernel_proxy_list) - 1):
        left_loop_nest = cpp_kernel_proxy_list[idx].loop_nest
        right_loop_nest = cpp_kernel_proxy_list[idx + 1].loop_nest
        if <MASK>:
            return False
    for cpp_kernel_proxy in cpp_kernel_proxy_list:
        outer_ranges = functools.reduce(operator.mul, cpp_kernel_proxy.ranges[:outer_loop_fusion_depth])
        if len(cpp_kernel_proxy.ranges) > outer_loop_fusion_depth and isinstance(outer_ranges, sympy.Integer) and isinstance(cpp_kernel_proxy.ranges[outer_loop_fusion_depth], sympy.Integer) and (outer_ranges * 300 < cpp_kernel_proxy.ranges[outer_loop_fusion_depth]):
            return False
    return True

def _get_metric_object(self, metric, y_t, y_p):
    """Converts user-supplied metric to a `Metric` object.

    Args:
      metric: A string, function, or `Metric` object.
      y_t: Sample of label.
      y_p: Sample of output.

    Returns:
      A `Metric` object.
    """
    if <MASK>:
        return None
    if str(metric).lower() not in ['accuracy', 'acc', 'crossentropy', 'ce']:
        metric_obj = metrics_mod.get(metric)
    else:
        y_t_rank = len(y_t.shape.as_list())
        y_p_rank = len(y_p.shape.as_list())
        y_t_last_dim = y_t.shape.as_list()[-1]
        y_p_last_dim = y_p.shape.as_list()[-1]
        is_binary = y_p_last_dim == 1
        is_sparse_categorical = y_t_rank < y_p_rank or (y_t_last_dim == 1 and y_p_last_dim > 1)
        if str(metric).lower() in ['accuracy', 'acc']:
            if is_binary:
                metric_obj = metrics_mod.binary_accuracy
            elif is_sparse_categorical:
                metric_obj = metrics_mod.sparse_categorical_accuracy
            else:
                metric_obj = metrics_mod.categorical_accuracy
        elif is_binary:
            metric_obj = metrics_mod.binary_crossentropy
        elif is_sparse_categorical:
            metric_obj = metrics_mod.sparse_categorical_crossentropy
        else:
            metric_obj = metrics_mod.categorical_crossentropy
    if isinstance(metric_obj, losses_mod.Loss):
        metric_obj._allow_sum_over_batch_size = True
    if not isinstance(metric_obj, metrics_mod.Metric):
        if isinstance(metric, str):
            metric_name = metric
        else:
            metric_name = get_custom_object_name(metric)
            if metric_name is None:
                raise ValueError('Metric should be a callable, found: {}'.format(metric))
        metric_obj = metrics_mod.MeanMetricWrapper(metric_obj, name=metric_name)
    return metric_obj

def get_geom_placeholder(self, f, value, compiler):
    """
        Provide a proper substitution value for Geometries or rasters that are
        not in the SRID of the field. Specifically, this routine will
        substitute in the ST_Transform() function call.
        """
    transform_func = self.spatial_function_name('Transform')
    if <MASK>:
        if value.field.srid == f.srid:
            placeholder = '%s'
        else:
            placeholder = '%s(%%s, %s)' % (transform_func, f.srid)
        return placeholder
    if value is None:
        value_srid = None
    else:
        value_srid = value.srid
    if value_srid is None or value_srid == f.srid:
        placeholder = '%s'
    else:
        placeholder = '%s(%%s, %s)' % (transform_func, f.srid)
    return placeholder

