def outer(a, b):
    """maskedarray version of the numpy function."""
    fa = filled(a, 0).ravel()
    fb = filled(b, 0).ravel()
    d = np.outer(fa, fb)
    ma = getmask(a)
    mb = getmask(b)
    if <MASK>:
        return masked_array(d)
    ma = getmaskarray(a)
    mb = getmaskarray(b)
    m = make_mask(1 - np.outer(1 - ma, 1 - mb), copy=False)
    return masked_array(d, mask=m)

def _vectorize_call_with_signature(self, func, args):
    """Vectorized call over positional arguments with a signature."""
    (input_core_dims, output_core_dims) = self._in_and_out_core_dims
    if len(args) != len(input_core_dims):
        raise TypeError('wrong number of positional arguments: expected %r, got %r' % (len(input_core_dims), len(args)))
    args = tuple((asanyarray(arg) for arg in args))
    (broadcast_shape, dim_sizes) = _parse_input_dimensions(args, input_core_dims)
    input_shapes = _calculate_shapes(broadcast_shape, dim_sizes, input_core_dims)
    args = [np.broadcast_to(arg, shape, subok=True) for (arg, shape) in zip(args, input_shapes)]
    outputs = None
    otypes = self.otypes
    nout = len(output_core_dims)
    for index in np.ndindex(*broadcast_shape):
        results = func(*(arg[index] for arg in args))
        n_results = len(results) if isinstance(results, tuple) else 1
        if nout != n_results:
            raise ValueError('wrong number of outputs from pyfunc: expected %r, got %r' % (nout, n_results))
        if nout == 1:
            results = (results,)
        if outputs is None:
            for (result, core_dims) in zip(results, output_core_dims):
                _update_dim_sizes(dim_sizes, result, core_dims)
            outputs = _create_arrays(broadcast_shape, dim_sizes, output_core_dims, otypes, results)
        for (output, result) in zip(outputs, results):
            output[index] = result
    if outputs is None:
        if <MASK>:
            raise ValueError('cannot call `vectorize` on size 0 inputs unless `otypes` is set')
        if builtins.any((dim not in dim_sizes for dims in output_core_dims for dim in dims)):
            raise ValueError('cannot call `vectorize` with a signature including new output dimensions on size 0 inputs')
        outputs = _create_arrays(broadcast_shape, dim_sizes, output_core_dims, otypes)
    return outputs[0] if nout == 1 else outputs

@classmethod
def lookup(cls, code: types.CodeType, lineno: int, *key: Any) -> types.CodeType:
    if <MASK>:
        cls.cache[code] = {}
    key = tuple(key)
    if key not in cls.cache[code]:
        cls.cache[code][key] = cls.generate(code, lineno, *key)
    return cls.cache[code][key]

def astype(self, dtype, copy: bool=True):
    dtype = pandas_dtype(dtype)
    if dtype == self.dtype:
        if <MASK>:
            return self.copy()
        return self
    elif isinstance(dtype, IntegerDtype):
        arr = self._ndarray.copy()
        mask = self.isna()
        arr[mask] = 0
        values = arr.astype(dtype.numpy_dtype)
        return IntegerArray(values, mask, copy=False)
    elif isinstance(dtype, FloatingDtype):
        arr_ea = self.copy()
        mask = self.isna()
        arr_ea[mask] = '0'
        values = arr_ea.astype(dtype.numpy_dtype)
        return FloatingArray(values, mask, copy=False)
    elif isinstance(dtype, ExtensionDtype):
        return ExtensionArray.astype(self, dtype, copy)
    elif np.issubdtype(dtype, np.floating):
        arr = self._ndarray.copy()
        mask = self.isna()
        arr[mask] = 0
        values = arr.astype(dtype)
        values[mask] = np.nan
        return values
    return super().astype(dtype, copy)

@abstractmethod
def fit(self, X, Y, **fit_params):
    """Fit the model to data matrix X and targets Y.

        Parameters
        ----------
        X : {array-like, sparse matrix} of shape (n_samples, n_features)
            The input data.

        Y : array-like of shape (n_samples, n_classes)
            The target values.

        **fit_params : dict of string -> object
            Parameters passed to the `fit` method of each step.

            .. versionadded:: 0.23

        Returns
        -------
        self : object
            Returns a fitted instance.
        """
    (X, Y) = validate_data(self, X, Y, multi_output=True, accept_sparse=True)
    random_state = check_random_state(self.random_state)
    self.order_ = self.order
    if isinstance(self.order_, tuple):
        self.order_ = np.array(self.order_)
    if <MASK>:
        self.order_ = np.array(range(Y.shape[1]))
    elif isinstance(self.order_, str):
        if self.order_ == 'random':
            self.order_ = random_state.permutation(Y.shape[1])
    elif sorted(self.order_) != list(range(Y.shape[1])):
        raise ValueError('invalid order')
    self.estimators_ = [clone(self._get_estimator()) for _ in range(Y.shape[1])]
    if self.cv is None:
        Y_pred_chain = Y[:, self.order_]
        if sp.issparse(X):
            X_aug = sp.hstack((X, Y_pred_chain), format='lil')
            X_aug = X_aug.tocsr()
        else:
            X_aug = np.hstack((X, Y_pred_chain))
    elif sp.issparse(X):
        if not sp.isspmatrix(X):
            if X.format == 'dok':
                X = sp.coo_array(X)
            Y_pred_chain = sp.coo_array((X.shape[0], Y.shape[1]))
        else:
            Y_pred_chain = sp.coo_matrix((X.shape[0], Y.shape[1]))
        X_aug = sp.hstack((X, Y_pred_chain), format='lil')
    else:
        Y_pred_chain = np.zeros((X.shape[0], Y.shape[1]))
        X_aug = np.hstack((X, Y_pred_chain))
    del Y_pred_chain
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = Bunch(estimator=Bunch(fit=fit_params))
    if hasattr(self, 'chain_method'):
        chain_method = _check_response_method(self._get_estimator(), self.chain_method).__name__
        self.chain_method_ = chain_method
    else:
        chain_method = 'predict'
    for (chain_idx, estimator) in enumerate(self.estimators_):
        message = self._log_message(estimator_idx=chain_idx + 1, n_estimators=len(self.estimators_), processing_msg=f'Processing order {self.order_[chain_idx]}')
        y = Y[:, self.order_[chain_idx]]
        with _print_elapsed_time('Chain', message):
            estimator.fit(X_aug[:, :X.shape[1] + chain_idx], y, **routed_params.estimator.fit)
        if self.cv is not None and chain_idx < len(self.estimators_) - 1:
            col_idx = X.shape[1] + chain_idx
            cv_result = cross_val_predict(self._get_estimator(), X_aug[:, :col_idx], y=y, cv=self.cv, method=chain_method)
            if cv_result.ndim > 1:
                cv_result = cv_result[:, 1]
            if sp.issparse(X_aug):
                X_aug[:, col_idx] = np.expand_dims(cv_result, 1)
            else:
                X_aug[:, col_idx] = cv_result
    return self

def _process_traceback_frames(tb):
    new_tb = None
    tb_list = list(traceback.walk_tb(tb))
    for (f, line_no) in reversed(tb_list):
        if <MASK>:
            new_tb = types.TracebackType(new_tb, f, f.f_lasti, line_no)
    if new_tb is None and tb_list:
        (f, line_no) = tb_list[-1]
        new_tb = types.TracebackType(new_tb, f, f.f_lasti, line_no)
    return new_tb

def _create_owned_multi_device_iterator(self):
    if <MASK>:
        device_scope = device_util.canonicalize(self._worker, device_util.current())
        host_device = device_util.get_host_for_device(device_scope)
    else:
        (device_scope, host_device) = (self._worker, self._worker)
    with ops.device(device_scope):
        if self._options is not None:
            self._iterator = multi_device_iterator_ops.OwnedMultiDeviceIterator(self._dataset, self._devices, source_device=host_device, max_buffer_size=self._options.experimental_per_replica_buffer_size, prefetch_buffer_size=self._options.experimental_per_replica_buffer_size)
        else:
            self._iterator = multi_device_iterator_ops.OwnedMultiDeviceIterator(self._dataset, self._devices, source_device=host_device)

def _body(i, _):
    """Body that adds a single new center based on a subset."""

    def _sample_random():
        """Returns a random point as a cluster center."""
        new_center = array_ops.reshape(first_shard[0], [1, -1])
        if <MASK>:
            new_center = nn_impl.l2_normalize(new_center, dim=1)
        return new_center

    def _sample_kmc2_chain():
        """Returns previous centers as well as a new center sampled using k-MC2."""
        start = i * self._kmc2_chain_length
        end = start + self._kmc2_chain_length
        subset = first_shard[start:end]
        (_, distances) = gen_clustering_ops.nearest_neighbors(subset, self._cluster_centers, 1)
        new_center_index = gen_clustering_ops.kmc2_chain_initialization(array_ops.squeeze(distances), self._seed)
        newly_sampled_center = array_ops.reshape(subset[new_center_index], [1, -1])
        if self._distance_metric == COSINE_DISTANCE:
            newly_sampled_center = nn_impl.l2_normalize(newly_sampled_center, dim=1)
        return array_ops.concat([self._cluster_centers, newly_sampled_center], 0)
    new_centers = cond.cond(math_ops.equal(self._num_selected, 0), _sample_random, _sample_kmc2_chain)
    assigned_centers = state_ops.assign(self._cluster_centers, new_centers, validate_shape=False)
    if self._cluster_centers_updated is not self._cluster_centers:
        assigned_centers = state_ops.assign(self._cluster_centers_updated, assigned_centers, validate_shape=False)
    return (i + 1, self._num_clusters - array_ops.shape(assigned_centers)[0])

def initial_value_fn():
    group_key = self._collective_keys.get_group_key([device])
    group_size = self._num_workers
    collective_instance_key = self._collective_keys.get_instance_key(group_key, device)
    with ops.device(device):
        initial_value = kwargs['initial_value']
        if <MASK>:
            initial_value = initial_value()
        if isinstance(initial_value, base.CheckpointInitialValue):
            initial_value = initial_value.wrapped_value
        assert not callable(initial_value)
        initial_value = ops.convert_to_tensor(initial_value, dtype=kwargs.get('dtype', None))
        if self._num_workers > 1:
            if self._is_chief:
                bcast_send = collective_ops.broadcast_send(initial_value, initial_value.shape, initial_value.dtype, group_size, group_key, collective_instance_key)
                with ops.control_dependencies([bcast_send]):
                    return array_ops.identity(initial_value)
            else:
                return collective_ops.broadcast_recv(initial_value.shape, initial_value.dtype, group_size, group_key, collective_instance_key)
        return initial_value

