def _mean_shift_single_seed(my_mean, X, nbrs, max_iter):
    bandwidth = nbrs.get_params()['radius']
    stop_thresh = 0.001 * bandwidth
    completed_iterations = 0
    while True:
        i_nbrs = nbrs.radius_neighbors([my_mean], bandwidth, return_distance=False)[0]
        points_within = X[i_nbrs]
        if len(points_within) == 0:
            break
        my_old_mean = my_mean
        my_mean = np.mean(points_within, axis=0)
        if <MASK>:
            break
        completed_iterations += 1
    return (tuple(my_mean), len(points_within), completed_iterations)

def test_bias_add(self):
    for data_format in ('NCHW', 'NHWC'):
        for stacked_value in (True, False):
            x_shape = [3, 4, 5, 6]
            if stacked_value:
                x_shape = [2] + x_shape
            x = random_ops.random_uniform(x_shape)
            for stacked_bias in (True, False):
                if not (stacked_value or stacked_bias):
                    continue
                with backprop.GradientTape(persistent=True) as g:
                    bias_dim = -1
                    if <MASK>:
                        bias_dim = 2 if stacked_value else 1
                    bias_shape = [x_shape[bias_dim]]
                    if stacked_bias:
                        bias_shape = [2] + bias_shape
                    bias = random_ops.random_uniform(bias_shape)
                    g.watch(bias)

                def loop_fn(i):
                    with g:
                        a = array_ops.gather(x, i) if stacked_value else x
                        b = array_ops.gather(bias, i) if stacked_bias else bias
                        y = nn.bias_add(a, b, data_format=data_format)
                        loss = math_ops.reduce_sum(y * y)
                    grad = g.gradient(loss, bias)
                    if stacked_bias:
                        return (y, grad.values, grad.indices)
                    else:
                        return (y, grad)
                out_dtypes = [dtypes.float32, dtypes.float32]
                if stacked_bias:
                    out_dtypes = out_dtypes + [dtypes.int32]
                self._test_loop_fn(loop_fn, 2)

def __init__(self, model, data, mapping, layer=0, source_srs=None, encoding='utf-8', transaction_mode='commit_on_success', transform=True, unique=None, using=None):
    """
        A LayerMapping object is initialized using the given Model (not an
        instance), a DataSource (or string path to an OGR-supported data file),
        and a mapping dictionary. See the module level docstring for more
        details and keyword argument usage.
        """
    if isinstance(data, (str, Path)):
        self.ds = DataSource(data, encoding=encoding)
    else:
        self.ds = data
    self.layer = self.ds[layer]
    self.using = using if using is not None else router.db_for_write(model)
    connection = connections[self.using]
    self.spatial_backend = connection.ops
    self.mapping = mapping
    self.model = model
    self.check_layer()
    if connection.features.supports_transform:
        self.geo_field = self.geometry_field()
    else:
        transform = False
    if <MASK>:
        self.source_srs = self.check_srs(source_srs)
        self.transform = self.coord_transform()
    else:
        self.transform = transform
    if encoding:
        from codecs import lookup
        lookup(encoding)
        self.encoding = encoding
    else:
        self.encoding = None
    if unique:
        self.check_unique(unique)
        transaction_mode = 'autocommit'
        self.unique = unique
    else:
        self.unique = None
    self.transaction_mode = transaction_mode
    if transaction_mode == 'autocommit':
        self.transaction_decorator = None
    elif transaction_mode == 'commit_on_success':
        self.transaction_decorator = transaction.atomic
    else:
        raise LayerMapError('Unrecognized transaction mode: %s' % transaction_mode)

@final
def _call_cython_op(self, values: np.ndarray, *, min_count: int, ngroups: int, comp_ids: np.ndarray, mask: npt.NDArray[np.bool_] | None, result_mask: npt.NDArray[np.bool_] | None, initial: Any=0, **kwargs) -> np.ndarray:
    orig_values = values
    dtype = values.dtype
    is_numeric = dtype.kind in 'iufcb'
    is_datetimelike = dtype.kind in 'mM'
    if self.how in ['any', 'all']:
        if mask is None:
            mask = isna(values)
    if <MASK>:
        values = values.view('int64')
        is_numeric = True
    elif dtype.kind == 'b':
        values = values.view('uint8')
    if values.dtype == 'float16':
        values = values.astype(np.float32)
    if self.how in ['any', 'all']:
        if dtype == object:
            if kwargs['skipna']:
                if mask is not None and mask.any():
                    values = values.copy()
                    values[mask] = True
        values = values.astype(bool, copy=False).view(np.int8)
        is_numeric = True
    values = values.T
    if mask is not None:
        mask = mask.T
        if result_mask is not None:
            result_mask = result_mask.T
    out_shape = self._get_output_shape(ngroups, values)
    func = self._get_cython_function(self.kind, self.how, values.dtype, is_numeric)
    values = self._get_cython_vals(values)
    out_dtype = self._get_out_dtype(values.dtype)
    result = maybe_fill(np.empty(out_shape, dtype=out_dtype))
    if self.kind == 'aggregate':
        counts = np.zeros(ngroups, dtype=np.int64)
        if self.how in ['idxmin', 'idxmax', 'min', 'max', 'mean', 'last', 'first', 'sum', 'median']:
            if self.how == 'sum':
                kwargs['initial'] = initial
            func(out=result, counts=counts, values=values, labels=comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, is_datetimelike=is_datetimelike, **kwargs)
        elif self.how in ['sem', 'std', 'var', 'ohlc', 'prod']:
            if self.how in ['std', 'sem']:
                kwargs['is_datetimelike'] = is_datetimelike
            func(result, counts, values, comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, **kwargs)
        elif self.how in ['any', 'all']:
            func(out=result, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            result = result.astype(bool, copy=False)
        elif self.how in ['skew', 'kurt']:
            func(out=result, counts=counts, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            if dtype == object:
                result = result.astype(object)
        else:
            raise NotImplementedError(f'{self.how} is not implemented')
    else:
        if self.how != 'rank':
            kwargs['result_mask'] = result_mask
        func(out=result, values=values, labels=comp_ids, ngroups=ngroups, is_datetimelike=is_datetimelike, mask=mask, **kwargs)
    if self.kind == 'aggregate' and self.how not in ['idxmin', 'idxmax']:
        if result.dtype.kind in 'iu' and (not is_datetimelike):
            cutoff = max(0 if self.how in ['sum', 'prod'] else 1, min_count)
            empty_groups = counts < cutoff
            if empty_groups.any():
                if result_mask is not None:
                    assert result_mask[empty_groups].all()
                else:
                    result = result.astype('float64')
                    result[empty_groups] = np.nan
    result = result.T
    if self.how not in self.cast_blocklist:
        res_dtype = self._get_result_dtype(orig_values.dtype)
        op_result = maybe_downcast_to_dtype(result, res_dtype)
    else:
        op_result = result
    return op_result

def _unbox_scalar(self, value) -> np.timedelta64:
    if not isinstance(value, self._scalar_type) and value is not NaT:
        raise ValueError("'value' should be a Timedelta.")
    self._check_compatible_with(value)
    if <MASK>:
        return np.timedelta64(value._value, self.unit)
    else:
        return value.as_unit(self.unit, round_ok=False).asm8

def map_function(x):
    if <MASK>:
        return script_ops.py_func(sleep, [x], x.dtype, stateful=False)
    else:
        return x

def __init__(self, method_name='runTest', methodName='runTest'):
    if methodName != 'runTest':
        method_name = methodName
    super().__init__(method_name)
    test_method = getattr(self, method_name, None)
    if <MASK>:
        if TEST_CUDA_MEM_LEAK_CHECK:
            self._do_cuda_memory_leak_check &= getattr(test_method, '_do_cuda_memory_leak_check', True)
            if self._do_cuda_memory_leak_check and (not IS_WINDOWS):
                self.wrap_with_cuda_policy(method_name, self.assertLeaksNoCudaTensors)
        self._do_cuda_non_default_stream &= getattr(test_method, '_do_cuda_non_default_stream', True)
        if self._do_cuda_non_default_stream and (not IS_WINDOWS):
            self.wrap_with_cuda_policy(method_name, self.enforceNonDefaultStream)
        if self._ignore_not_implemented_error:
            self.wrap_with_policy(method_name, lambda : skip_exception_type(NotImplementedError))
        if PRINT_REPRO_ON_FAILURE:
            try:

                def _get_rel_test_path(abs_test_path):
                    parts = Path(abs_test_path).parts
                    for (i, part) in enumerate(parts):
                        if part == 'test':
                            base_dir = os.path.join(*parts[:i]) if i > 0 else ''
                            return os.path.relpath(abs_test_path, start=base_dir)
                    return os.path.split(abs_test_path)[1]
                abs_test_path = inspect.getfile(type(self))
                test_filename = _get_rel_test_path(abs_test_path)
                class_name = type(self).__name__
                test_run_cmd = f'python {test_filename} {class_name}.{method_name}'
                env_var_prefix = TestEnvironment.repro_env_var_prefix()
                repro_parts = [env_var_prefix, test_run_cmd]
                self.wrap_with_policy(method_name, lambda repro_parts=repro_parts: print_repro_on_failure(repro_parts))
            except Exception as e:
                log.info('could not print repro string', extra=str(e))

