def _get_subgraph_relationship_type(subgraph_a: NSSubgraph, subgraph_b: NSSubgraph, gm_a: GraphModule, gm_b: GraphModule, type_a_related_to_b: set[tuple[NSNodeTargetType, NSNodeTargetType]]) -> SubgraphTypeRelationship:
    node_a = subgraph_a.base_op_node
    node_b = subgraph_b.base_op_node
    if node_a.op != node_b.op:
        if not (node_a.op in ('call_function', 'call_method') and node_b.op in ('call_function', 'call_method')):
            return SubgraphTypeRelationship.NOT_RELATED
    if node_a.op in ('call_function', 'call_method'):
        key = (node_a.target, node_b.target)
        if <MASK>:
            if node_a.target == node_b.target:
                return SubgraphTypeRelationship.EQUAL_BUT_UKNOWN
            else:
                return SubgraphTypeRelationship.NOT_RELATED
        if node_a.target == node_b.target:
            node_a_has_prev = subgraph_a.base_op_node == subgraph_a.start_node
            node_b_has_prev = subgraph_b.base_op_node == subgraph_b.start_node
            if node_a_has_prev and (not node_b_has_prev):
                return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
            elif not node_a_has_prev and node_b_has_prev:
                return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
            elif not node_a_has_prev and (not node_b_has_prev):
                return SubgraphTypeRelationship.EQUAL
            else:
                return SubgraphTypeRelationship.EQUAL
        if key in type_a_related_to_b:
            return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
        else:
            return SubgraphTypeRelationship.NOT_RELATED
    elif node_a.op == 'call_module':
        if subgraph_a.base_op_node != subgraph_a.start_node or subgraph_b.base_op_node != subgraph_b.start_node:
            raise AssertionError('Matching call_module patterns where base_op_node != start_node is not supported yet')
        if not isinstance(node_a.target, str):
            raise AssertionError(f'Expected str, got {type(node_a.target)}')
        mod_a = getattr_from_fqn(gm_a, node_a.target)
        if not isinstance(node_b.target, str):
            raise AssertionError(f'Expected str, got {type(node_b.target)}')
        mod_b = getattr_from_fqn(gm_b, node_b.target)
        key = (type(mod_a), type(mod_b))
        if key not in type_a_related_to_b:
            if type(mod_a) is type(mod_b):
                return SubgraphTypeRelationship.EQUAL_BUT_UKNOWN
            else:
                return SubgraphTypeRelationship.NOT_RELATED
        elif type(mod_a) is type(mod_b):
            return SubgraphTypeRelationship.EQUAL
        else:
            return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
    return SubgraphTypeRelationship.NOT_RELATED

def _show_compute(self, show_dataflow: bool) -> None:
    """Visualize the computation activity."""
    for dev_stats in self._step_stats.dev_stats:
        device_name = dev_stats.device
        device_pid = self._device_pids[device_name]
        is_gputrace = self._is_gputrace_device(device_name)
        for node_stats in dev_stats.node_stats:
            tid = node_stats.thread_id
            start_time = node_stats.all_start_micros
            end_time = node_stats.all_start_micros + node_stats.all_end_rel_micros
            self._emit_op(node_stats, device_pid, is_gputrace)
            if is_gputrace or node_stats.node_name == 'RecvTensor':
                continue
            (_, _, inputs) = self._parse_op_label(node_stats.timeline_label)
            for input_name in inputs:
                if input_name not in self._tensors:
                    index = input_name.rfind('/_')
                    if index > 0:
                        input_name = input_name[:index]
                if input_name in self._tensors:
                    tensor = self._tensors[input_name]
                    tensor.add_ref(start_time)
                    tensor.add_unref(end_time - 1)
                    if <MASK>:
                        (create_time, create_pid, create_tid) = self._flow_starts[input_name]
                        if create_pid != device_pid or create_tid != tid:
                            flow_id = self._alloc_flow_id()
                            self._chrome_trace.emit_flow_start(input_name, create_time, create_pid, create_tid, flow_id)
                            self._chrome_trace.emit_flow_end(input_name, start_time, device_pid, tid, flow_id)
                else:
                    logging.vlog(1, "Can't find tensor %s - removed by CSE?", input_name)

@register_op_strategy(aten.cat.default, RuntimeSchemaInfo(1, needs_pytree=True))
def cat_strategy(op_schema: OpSchema) -> StrategyType:
    args_schema = op_schema.args_schema
    input_tuple_strategy = args_schema[0]
    if not isinstance(input_tuple_strategy, TupleStrategy):
        raise AssertionError(f'Expected TupleStrategy, got {input_tuple_strategy}')
    num_input_tensor = len(input_tuple_strategy.children)
    first_input_strategy = input_tuple_strategy.children[0]
    if not isinstance(first_input_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {first_input_strategy}')
    common_input_ndim = first_input_strategy.ndim
    dim = cast(int, args_schema[1]) if len(args_schema) > 1 else 0
    dim = normalize_dim(dim, common_input_ndim)
    mesh = first_input_strategy.mesh
    op_strategy = OpStrategy([])
    strategies_placement_pool = set()
    for this_strategy in input_tuple_strategy.children:
        if not isinstance(this_strategy, OpStrategy):
            raise AssertionError(f'Expected OpStrategy, got {type(this_strategy)}')
        if <MASK>:
            raise AssertionError("cat op doesn't support cross mesh concatenation")
        for op_spec in this_strategy.strategies:
            if not isinstance(op_spec, OpSpec):
                raise AssertionError(f'Expected OpSpec, got {type(op_spec)}')
            exemplar_spec = op_spec.output_spec
            if is_tensor_dim_sharded(exemplar_spec, dim):
                exemplar_placement = unshard_tensor_dim(exemplar_spec.placements, dim)
            else:
                exemplar_placement = exemplar_spec.placements
            if exemplar_placement not in strategies_placement_pool:
                strategies_placement_pool.add(exemplar_placement)
                redistribute_costs = []
                input_specs = []
                for idx in range(num_input_tensor):
                    that_tensor_strategy = input_tuple_strategy.children[idx]
                    if not isinstance(that_tensor_strategy, OpStrategy):
                        raise AssertionError(f'Expected OpStrategy, got {type(that_tensor_strategy)}')
                    input_spec = DTensorSpec(mesh, exemplar_placement, tensor_meta=that_tensor_strategy.strategies[0].output_spec.tensor_meta)
                    input_specs.append(input_spec)
                    redistribute_costs.append(generate_redistribute_costs(that_tensor_strategy, input_spec))
                op_strategy.strategies.append(OpSpec(output_specs=DTensorSpec(mesh, exemplar_placement), input_specs=tuple(input_specs), redistribute_cost=redistribute_costs))
    return op_strategy

def compute_output_shape(self, input_shape):
    input_shape = tensor_shape.TensorShape(input_shape).as_list()
    if self.data_format == 'channels_first':
        if <MASK>:
            dim1 = input_shape[2] - self.cropping[0][0] - self.cropping[0][1]
        else:
            dim1 = None
        if input_shape[3] is not None:
            dim2 = input_shape[3] - self.cropping[1][0] - self.cropping[1][1]
        else:
            dim2 = None
        if input_shape[4] is not None:
            dim3 = input_shape[4] - self.cropping[2][0] - self.cropping[2][1]
        else:
            dim3 = None
        return tensor_shape.TensorShape([input_shape[0], input_shape[1], dim1, dim2, dim3])
    elif self.data_format == 'channels_last':
        if input_shape[1] is not None:
            dim1 = input_shape[1] - self.cropping[0][0] - self.cropping[0][1]
        else:
            dim1 = None
        if input_shape[2] is not None:
            dim2 = input_shape[2] - self.cropping[1][0] - self.cropping[1][1]
        else:
            dim2 = None
        if input_shape[3] is not None:
            dim3 = input_shape[3] - self.cropping[2][0] - self.cropping[2][1]
        else:
            dim3 = None
        return tensor_shape.TensorShape([input_shape[0], dim1, dim2, dim3, input_shape[4]])

def _remove_existing(path: Path) -> None:
    if <MASK>:
        if path.is_dir():
            shutil.rmtree(path)
        else:
            path.unlink()

def index_of_first_match(seq, predicate, start=0, end=None):
    if <MASK>:
        end = len(seq)
    for i in range(start, end):
        if predicate(seq[i]):
            return i
    return None

def get_df(self, log_path, cat_feature2cats=None, nrows=None, apply_filters=False, add_near_best=False):
    """
        Parses the log file and processes the data into a dataframe that can be used for training.
        """
    (df, metadata, features, categorical_features, choices) = self.parse_log(log_path, nrows)

    def calculate_stats(group):
        count = len(group)
        has_inf = np.isinf(group['feedback']).any()
        if has_inf:
            relative_std = np.inf
            median = np.inf
        else:
            mean = group['feedback'].mean()
            std = group['feedback'].std()
            relative_std = std / mean * 100 if mean != 0 else np.inf
            median = group['feedback'].median()
        if relative_std > 5:
            times = group['feedback'].tolist()
            times_str = ', '.join([f'{t:.3f}' for t in sorted(times)])
            log.debug('High relative std: %f. times=%s', relative_std, times_str)
        return pd.Series({'count': count, 'relative_std': relative_std, 'median_execution_time': median})
    feature_columns = features
    stats = df.groupby(feature_columns + ['choice'], as_index=False).apply(calculate_stats, include_groups=False).reset_index()
    if <MASK>:
        valid_stats = stats[(stats['count'] >= 3) & (stats['relative_std'] <= 5)]
        valid_inputs = valid_stats.groupby(feature_columns).filter(lambda x: len(x) >= 2)
    else:
        valid_inputs = stats

    def get_winner_and_speedup(group):
        assert len(group) >= 2, 'Need at least 2 choices'
        sorted_group = group.sort_values('median_execution_time')
        winner = sorted_group.iloc[0]['choice']
        winning_time = sorted_group.iloc[0]['median_execution_time']
        second_best_time = sorted_group.iloc[1]['median_execution_time']
        speedup = second_best_time / winning_time
        unique_choices = group['choice'].unique()
        choice2time = {}
        for row in group.itertuples():
            choice2time[row.choice] = row.median_execution_time
        assert len(unique_choices) == len(group), f'len(unique_choices) != len(group): {len(unique_choices)} != {len(group)}'
        return pd.Series({'winner': winner, 'speedup': speedup, 'avail_choices': unique_choices, 'choice2time': json.dumps(choice2time)})
    results = valid_inputs.groupby(feature_columns, as_index=False).filter(lambda x: len(x) >= 2).groupby(feature_columns, as_index=False).apply(get_winner_and_speedup, include_groups=False).reset_index()

    def add_near_best_configs(df):
        new_rows = []
        for (index, row) in df.iterrows():
            dictionary = json.loads(row['choice2time'])
            min_value = min(dictionary.values())
            for (key, value) in dictionary.items():
                new_row = row.copy()
                relative_performance = min_value / value
                new_row['relative_performance'] = relative_performance
                if relative_performance is None or relative_performance is np.inf:
                    breakpoint()
                new_row['actual_winner'] = row['winner']
                new_row['winner'] = key
                if relative_performance >= 0.98:
                    new_rows.append(new_row)
        return pd.DataFrame(new_rows).reset_index(drop=True)
    if add_near_best:
        results = add_near_best_configs(results)
    (results, added_categorical_features) = self.add_new_features(results)
    categorical_features += added_categorical_features
    (results, cat_feature2cats, dummy_col_2_col_val) = self.handle_categorical_features(cat_feature2cats, categorical_features, results)
    return (results, choices, cat_feature2cats, dummy_col_2_col_val, metadata)

def compare_tensor_meta(a: TensorLikeType, b: TensorLikeType, check_sizes=True, check_strides=False, *, allow_rhs_unbacked=False, check_conj=True):
    """
    Checks that two tensor likes have the same shape,
    dtype and device.

    In the future this will validate additional metadata, like
    strides.
    """
    from torch._subclasses.fake_tensor import MetadataMismatchError
    assert isinstance(a, TensorLike)
    assert isinstance(b, TensorLike)
    if check_sizes and (not same_shape(a.shape, b.shape, allow_rhs_unbacked=allow_rhs_unbacked)):
        msg = f'Shapes {a.shape} and {b.shape} are not equal!'
        raise MetadataMismatchError(msg)
    if a.dtype != b.dtype:
        msg = f'Dtypes {a.dtype} and {b.dtype} are not equal!'
        raise MetadataMismatchError(msg)
    if <MASK>:
        if (str(a.device) == 'cuda:0' or str(a.device) == 'cuda') and (str(b.device) == 'cuda:0' or str(b.device) == 'cuda'):
            pass
        else:
            msg = f'Devices {a.device} and {b.device} are not equal!'
            raise MetadataMismatchError(msg)
    if check_strides:
        (same_strides, idx) = check_significant_strides(a, b, allow_rhs_unbacked=allow_rhs_unbacked)
        if not same_strides:
            msg = f'Stride mismatch! Strides are {a.stride()} and {b.stride()} (mismatched at {idx})!'
            raise MetadataMismatchError(msg)
        if a.storage_offset() != b.storage_offset():
            msg = f'Storage offset mismatch! Storage offsets are {a.storage_offset()} and {b.storage_offset()}!'
            raise MetadataMismatchError(msg)
    if check_conj:
        if a.is_conj() != b.is_conj():
            raise MetadataMismatchError(f'Conj mismatch! is_conj is set to {a.is_conj()} and {b.is_conj()}')
    if a.is_neg() != b.is_neg():
        raise MetadataMismatchError(f'Neg mismatch! is_neg is set to {a.is_neg()} and {b.is_neg()}')

def get_setup_py_content_with_nvidia_wheel_versions(setup_py_content: str, cuda_version: str, nvidia_wheel_versions_data: str) -> str:
    nvidia_wheel_versions = {'12': {}, '13': {}}
    for line in nvidia_wheel_versions_data.splitlines():
        match = NVIDIA_WHEEL_VERSIONS_PATTERN.match(line)
        if match:
            wheel_name = match.group(1).replace('-', '_')
            for (suffix, version) in {'_cu12': '12', '_cu13': '13', '': '13'}.items():
                if <MASK>:
                    continue
                wheel_name = wheel_name.replace(suffix, '') + '_version'
                nvidia_wheel_versions[version][wheel_name] = match.group(2).strip()
                break
    setup_py_content = setup_py_content.replace('cuda_version = 0  # placeholder', f'cuda_version = {cuda_version}')
    setup_py_content = setup_py_content.replace("cuda_wheel_suffix = ''  # placeholder", "cuda_wheel_suffix = '-cu12'" if cuda_version == '12' else "cuda_wheel_suffix = ''")
    for (version_name, version_value) in nvidia_wheel_versions[str(cuda_version)].items():
        setup_py_content = setup_py_content.replace(f"{version_name} = ''  # placeholder", f"{version_name} = '{version_value}'")
    return setup_py_content

def optimize_for_mobile(script_module: torch.jit.ScriptModule, optimization_blocklist: Optional[set[MobileOptimizerType]]=None, preserved_methods: Optional[list[AnyStr]]=None, backend: str='CPU') -> torch.jit.RecursiveScriptModule:
    """
    Optimize a torch script module for mobile deployment.

    Args:
        script_module: An instance of torch script module with type of ScriptModule.
        optimization_blocklist: A set with type of MobileOptimizerType. When set is not passed,
            optimization method will run all the optimizer pass; otherwise, optimizer
            method will run the optimization pass that is not included inside optimization_blocklist.
        preserved_methods: A list of methods that needed to be preserved when freeze_module pass is invoked
        backend: Device type to use for running the result model ('CPU'(default), 'Vulkan' or 'Metal').
    Returns:
        A new optimized torch script module
    """
    if not isinstance(script_module, torch.jit.ScriptModule):
        raise TypeError(f'Got {type(script_module)}, but ScriptModule is expected.')
    if optimization_blocklist is None:
        optimization_blocklist = set()
    if preserved_methods is None:
        preserved_methods = []
    preserved_methods_str: list[str] = [str(method) for method in preserved_methods]
    bundled_inputs_attributes = _get_bundled_inputs_preserved_attributes(script_module, preserved_methods_str)
    if all((hasattr(script_module, method) for method in bundled_inputs_attributes)):
        preserved_methods_str = list(set(preserved_methods_str + bundled_inputs_attributes))
    non_exist_methods = [method for method in preserved_methods_str if not hasattr(script_module, method)]
    if non_exist_methods:
        raise AttributeError(f"The following methods to preserve do not exist in script_module: {', '.join(non_exist_methods)}")
    backend = backend.lower()
    if backend == 'cpu':
        optimized_cpp_module = torch._C._jit_pass_optimize_for_mobile(script_module._c, optimization_blocklist, preserved_methods_str)
    elif backend == 'vulkan':
        optimized_cpp_module = torch._C._jit_pass_vulkan_optimize_for_mobile(script_module._c, optimization_blocklist, preserved_methods_str)
    elif <MASK>:
        optimized_cpp_module = torch._C._jit_pass_metal_optimize_for_mobile(script_module._c, preserved_methods_str)
    else:
        raise TypeError("Unknown backend, must be one of 'CPU', 'Vulkan' or 'Metal'")
    return torch.jit._recursive.wrap_cpp_module(optimized_cpp_module)

def _get_support_mask(self):
    estimator = getattr(self, 'estimator_', self.estimator)
    max_features = getattr(self, 'max_features_', self.max_features)
    if <MASK>:
        try:
            check_is_fitted(self.estimator)
        except NotFittedError as exc:
            raise NotFittedError('When `prefit=True`, `estimator` is expected to be a fitted estimator.') from exc
    if callable(max_features):
        raise NotFittedError('When `prefit=True` and `max_features` is a callable, call `fit` before calling `transform`.')
    elif max_features is not None and (not isinstance(max_features, Integral)):
        raise ValueError(f'`max_features` must be an integer. Got `max_features={max_features}` instead.')
    scores = _get_feature_importances(estimator=estimator, getter=self.importance_getter, transform_func='norm', norm_order=self.norm_order)
    threshold = _calculate_threshold(estimator, scores, self.threshold)
    if self.max_features is not None:
        mask = np.zeros_like(scores, dtype=bool)
        candidate_indices = np.argsort(-scores, kind='mergesort')[:max_features]
        mask[candidate_indices] = True
    else:
        mask = np.ones_like(scores, dtype=bool)
    mask[scores < threshold] = False
    return mask

def _create_flatten_mesh(self, mesh_dim_name: Optional[str]=None, backend_override: BackendConfig=(None, None)) -> 'DeviceMesh':
    root_mesh = self._get_root_mesh()
    if not mesh_dim_name:
        mesh_dim_name = '_'.join(not_none(self._mesh_dim_names))
    if self.ndim == 1 and mesh_dim_name in not_none(self._mesh_dim_names):
        return self
    invalid_dim_names = not_none(root_mesh._mesh_dim_names)
    if mesh_dim_name in invalid_dim_names:
        raise ValueError(f'{mesh_dim_name} already exists for submesh of the {root_mesh}. ', f'The mesh_dim_names of submesh and flattened mesh are {invalid_dim_names}. Please specify another valid mesh_dim_name.')
    flattened_mesh_layout = self._layout.coalesce()
    if len(flattened_mesh_layout) > 1:
        flattened_mesh_layout = flattened_mesh_layout.nest()
    if mesh_dim_name in root_mesh._flatten_mapping:
        if <MASK>:
            return root_mesh._flatten_mapping[mesh_dim_name]
        else:
            raise ValueError(f'Flatten mesh with mesh_dim_name {mesh_dim_name} has been created before, Please specify another valid mesh_dim_name.')
    res_flattened_mesh = DeviceMesh(root_mesh._device_type, _layout=flattened_mesh_layout, _rank_map=root_mesh._rank_map, mesh_dim_names=(mesh_dim_name,), _root_mesh=root_mesh, backend_override=(backend_override,))
    root_mesh._flatten_mapping[mesh_dim_name] = res_flattened_mesh
    return res_flattened_mesh

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    out = kwargs.get('out', ())
    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(self, ufunc, method, *inputs, **kwargs)
    if <MASK>:
        return result
    if 'out' in kwargs:
        return arraylike.dispatch_ufunc_with_out(self, ufunc, method, *inputs, **kwargs)
    if method == 'reduce':
        result = arraylike.dispatch_reduction_ufunc(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    inputs = tuple((x._ndarray if isinstance(x, NumpyExtensionArray) else x for x in inputs))
    if out:
        kwargs['out'] = tuple((x._ndarray if isinstance(x, NumpyExtensionArray) else x for x in out))
    result = getattr(ufunc, method)(*inputs, **kwargs)
    if ufunc.nout > 1:
        return tuple((type(self)(x) for x in result))
    elif method == 'at':
        return None
    elif method == 'reduce':
        if isinstance(result, np.ndarray):
            return type(self)(result)
        return result
    else:
        if self.dtype.type is str:
            self = cast('StringArray', self)
            try:
                return type(self)(result, dtype=self.dtype)
            except ValueError:
                return result
        return type(self)(result)

def _parse_policy_autovec(self, has_baseline, final_targets, extra_flags):
    """skip features that has no auto-vectorized support by compiler"""
    skipped = []
    for tar in final_targets[:]:
        if isinstance(tar, str):
            can = self.feature_can_autovec(tar)
        else:
            can = all([self.feature_can_autovec(t) for t in tar])
        if not can:
            final_targets.remove(tar)
            skipped.append(tar)
    if <MASK>:
        self.dist_log('skip non auto-vectorized features', skipped)
    return (has_baseline, final_targets, extra_flags)

def is_url(self, template):
    """Return True if the name looks like a URL."""
    if <MASK>:
        return False
    scheme = template.split(':', 1)[0].lower()
    return scheme in self.url_schemes

@_trace_wrapped_op.py_impl(ProxyTorchDispatchMode)
def inner_trace(mode: ProxyTorchDispatchMode, *args: Any, bw_state: Optional[BackwardState]=None, **kwargs: Any) -> Any:

    def self_invoke(*args: Any, **dyn_kwargs: Any) -> Any:
        with torch.no_grad():
            return _trace_wrapped_op(*args, **dyn_kwargs, **kwargs)

    def unwrap_proxies(x: Any) -> Any:
        if isinstance(x, torch.Tensor):
            return mode.tracer.unwrap_proxy(x)
        if isinstance(x, (list, tuple)):
            return type(x)(map(unwrap_proxies, x))
        if x is None:
            return None
        raise AssertionError(f'unhandled type: {type(x)}')
    proxy_kwargs = {}
    if bw_state is not None:
        assert isinstance(bw_state, BackwardState) and bw_state.proxy is not None
        proxy_kwargs['bw_state'] = bw_state.proxy
    out_proxy = mode.tracer.create_proxy('call_function', self_invoke, unwrap_proxies(args), proxy_kwargs, name='trace_wrapped')
    if <MASK>:
        grad = args[1]
    else:
        grad = args[0]
    grad = tree_map_only(torch.Tensor, torch.empty_like, grad)
    track_tensor_tree(grad, out_proxy, constant=None, tracer=mode.tracer)
    return grad

@compatibility(is_backward_compatible=False)
def lift_lowering_attrs_to_nodes(fx_module: GraphModule) -> None:
    """Recursively traverse all `fx_module` nodes and fetch the module's attributes if the node is a leaf module."""
    submodules = dict(fx_module.named_modules())
    for node in fx_module.graph.nodes:
        if node.op == 'call_module':
            if <MASK>:
                lift_lowering_attrs_to_nodes(submodules[node.target])
            else:
                node.attrs_for_lowering = extract_attrs_for_lowering(submodules[node.target])

def __init__(self, optimizer: Optimizer, T_0: int, T_mult: int=1, eta_min: float=0.0, last_epoch: int=-1):
    if T_0 <= 0 or not isinstance(T_0, int):
        raise ValueError(f'Expected positive integer T_0, but got {T_0}')
    if <MASK>:
        raise ValueError(f'Expected integer T_mult >= 1, but got {T_mult}')
    if not isinstance(eta_min, (float, int)):
        raise ValueError(f'Expected float or int eta_min, but got {eta_min} of type {type(eta_min)}')
    self.T_0 = T_0
    self.T_i = T_0
    self.T_mult = T_mult
    self.eta_min = eta_min
    self.T_cur = last_epoch
    super().__init__(optimizer, last_epoch)

@register(torch.tensor)
def handle_torch_tensor(self, tx: 'InstructionTranslator', *args, **kwargs):

    def check_any_unspec(x):
        if isinstance(x, (TensorVariable, SymNodeVariable)):
            return True
        elif <MASK>:
            return any((check_any_unspec(y) for y in x.items))
        else:
            return False
    data_arg = None
    if args:
        data_arg = args[0]
    elif 'data' in kwargs:
        data_arg = kwargs['data']
    if not isinstance(data_arg, TensorVariable) and check_any_unspec(data_arg):
        return TorchInGraphFunctionVariable(torch._refs.tensor).call_function(tx, [*args], kwargs)

def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if ann is None:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if <MASK>:
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if value is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if ann is str:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if ann is Any:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if ann is torch.qscheme:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if maybe_script_class is not None:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

@unpack_zerodim_and_defer('__truediv__')
def __truediv__(self, other):
    op = operator.truediv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)
    other = self._cast_divlike_op(other)
    if lib.is_np_dtype(other.dtype, 'm') or is_integer_dtype(other.dtype) or is_float_dtype(other.dtype):
        return self._vector_divlike_op(other, op)
    if is_object_dtype(other.dtype):
        other = np.asarray(other)
        if <MASK>:
            res_cols = [left / right for (left, right) in zip(self, other, strict=True)]
            res_cols2 = [x.reshape(1, -1) for x in res_cols]
            result = np.concatenate(res_cols2, axis=0)
        else:
            result = truediv_object_array(self._ndarray, other)
        return result
    else:
        return NotImplemented

@final
def _clean_index_names(self, columns, index_col) -> tuple[list | None, list, list]:
    if not is_index_col(index_col):
        return (None, columns, index_col)
    columns = list(columns)
    if <MASK>:
        return ([None] * len(index_col), columns, index_col)
    cp_cols = list(columns)
    index_names: list[str | int | None] = []
    index_col = list(index_col)
    for (i, c) in enumerate(index_col):
        if isinstance(c, str):
            index_names.append(c)
            for (j, name) in enumerate(cp_cols):
                if name == c:
                    index_col[i] = j
                    columns.remove(name)
                    break
        else:
            name = cp_cols[c]
            columns.remove(name)
            index_names.append(name)
    for (i, name) in enumerate(index_names):
        if isinstance(name, str) and name in self.unnamed_cols:
            index_names[i] = None
    return (index_names, columns, index_col)

def opcheck(op: Union[torch._ops.OpOverload, torch._ops.OpOverloadPacket, CustomOpDef], args: tuple[Any, ...], kwargs: Optional[dict[str, Any]]=None, *, test_utils: Union[str, Sequence[str]]=DEFAULT_TEST_UTILS, raise_exception: bool=True, rtol: Optional[float]=None, atol: Optional[float]=None) -> dict[str, str]:
    """See torch.library.opcheck for docstring"""
    if (rtol is None) ^ (atol is None):
        raise ValueError('opcheck(op, ...): if you specify one of rtol/atol, you must specify both')
    if kwargs is None:
        kwargs = {}
    if <MASK>:
        op = op._opoverload
    if isinstance(op, torch._ops.OpOverloadPacket):
        op = resolve_unique_overload_or_throw(op)
    if not isinstance(op, torch._ops.OpOverload):
        raise ValueError(f'opcheck(op, ...): op must be instance of torch._ops.OpOverload, e.g. torch.ops.aten.sin.default, got {type(op)}')
    if test_utils == 'ALL':
        test_utils = tuple(ALL_TEST_UTILS.keys())
    if isinstance(test_utils, str):
        test_utils = (test_utils,)
    if not isinstance(test_utils, (tuple, list)) or not set(test_utils).issubset(ALL_TEST_UTILS.keys()):
        raise ValueError(f'opcheck(op, ..., test_utils={test_utils}), expected test_utils to be subset of {tuple(ALL_TEST_UTILS.keys())} but it was not')
    results_dict = {}
    for test_util in test_utils:
        tester = ALL_TEST_UTILS[test_util]
        try:
            tester(op, args, kwargs, rtol=rtol, atol=atol)
            results_dict[test_util] = 'SUCCESS'
        except Exception as ex:
            if raise_exception:
                raise OpCheckError(f'opcheck(op, ...): {test_util} failed with {ex} (scroll up for stack trace)') from ex
            results_dict[test_util] = ex
    return results_dict

def make_autograd_impl(op: _ops.OpOverload, info: InfoProtocol) -> Callable:
    name: str = f'GeneratedBackwardFor_{op._namespace}_{op._opname}_{op._overloadname}'
    has_kwarg_only_args = utils.has_kwarg_only_args(op._schema)

    @dataclass
    class Metadata:
        keyset: _C.DispatchKeySet
        keyword_only_args: dict[str, Any]

    def forward_no_grad(*args):
        metadata = args[-1]
        args = args[:-1]
        with _C._AutoDispatchBelowAutograd():
            keyset = metadata.keyset
            kwargs = metadata.keyword_only_args
            result = op.redispatch(keyset & _C._after_autograd_keyset, *args, **kwargs)
            return result

    def forward(ctx, *args):
        metadata = args[-1]
        args = args[:-1]
        with _C._AutoDispatchBelowAutograd():
            keyset = metadata.keyset
            kwargs = metadata.keyword_only_args
            result = op.redispatch(keyset & _C._after_autograd_keyset, *args, **kwargs)
            if info._setup_context_fn:
                (args, kwargs) = utils.fill_defaults(op._schema, args, kwargs)
                if has_kwarg_only_args:
                    info._setup_context_fn(ctx=ctx, inputs=args, keyword_only_inputs=kwargs, output=result)
                else:
                    info._setup_context_fn(ctx=ctx, inputs=args, output=result)
            return result

    def backward(ctx, *grads):
        if info._backward_fn:
            try:
                prev_needs_input_grad = ctx.needs_input_grad
                ctx.needs_input_grad = ctx.needs_input_grad[:-1]
                result = info._backward_fn(ctx, *grads)
            finally:
                ctx.needs_input_grad = prev_needs_input_grad
            if isinstance(result, tuple):
                return (*result, None)
            return (result, None)
        raise RuntimeError(f'Trying to backward through {op} but no autograd formula was registered. Please use register_autograd to add one.')
    Generated = type(name, (autograd.Function,), {'forward': staticmethod(forward), 'backward': staticmethod(backward)})
    schema = op._schema
    if <MASK>:
        Generated = supports_tensorlist(Generated)

    def autograd_impl(keyset, *args, **keyword_only_args):
        if _C.is_grad_enabled() and _C._any_requires_grad(*args):
            result = Generated.apply(*args, Metadata(keyset, keyword_only_args))
        else:
            result = forward_no_grad(*args, Metadata(keyset, keyword_only_args))
        return result
    return autograd_impl

@wraps(orig_fsdp_state_post_fw)
def inner(*args: _P.args, **kwargs: _P.kwargs) -> _R:
    mod_stat = self.memory_tracking[fsdp_mod]
    if self._mod_tracker.is_bw:
        state = _FSDPModState.POST_FW_AC
        if self._ac_mod is not None and self._ac_mod() is fsdp_mod:
            self._ac_mod = None
            self._in_ac = False
    else:
        state = _FSDPModState.BEF_POST_FW
    mod_stat.snapshots.setdefault(state, []).append(self.get_tracker_snapshot())
    self._fsdp_state = _FSDPState.POST_FW
    output = orig_fsdp_state_post_fw(*args, **kwargs)
    if <MASK>:
        mod_stat.snapshots.setdefault(_FSDPModState.AFT_POST_FW, []).append(self.get_tracker_snapshot())
    return output

def checkTrace(self, func, reference_tensors, input_tensors=None, drop=None, allow_unused=False, verbose=False, inputs_require_grads=True, check_tolerance=1e-05, export_import=True, _force_outplace=False, grad_atol=None, grad_rtol=None):

    def allSum(vs):
        if drop is not None:
            vs = vs[:-drop]
        return sum((math.log(i + 2) * v.sum() for (i, v) in enumerate(vs) if v is not None))
    if input_tensors is None:
        input_tensors = reference_tensors

    def flatten_inputs(inputs):

        def input_reduce(input, fn, acc):
            if isinstance(input, torch.Tensor):
                fn(input, acc)
            elif isinstance(input, dict):
                reduce(lambda acc, key: input_reduce(input[key], fn, acc), input, acc)
            else:
                reduce(lambda acc, val: input_reduce(val, fn, acc), input, acc)
            return acc
        return tuple(input_reduce(recording_inputs, lambda t, acc: acc.append(t), []))
    nograd_inputs = reference_tensors
    if <MASK>:
        recording_inputs = do_input_map(lambda t: t.clone().requires_grad_(), reference_tensors)
        flattened_recording_inputs = flatten_inputs(recording_inputs)
    else:
        recording_inputs = reference_tensors
    ge = torch.jit.trace(func, input_tensors, check_tolerance=check_tolerance, _force_outplace=_force_outplace, check_trace=False)
    if export_import:
        ge = self.getExportImportCopy(ge)
    if verbose:
        print(ge.graph)
    outputs = func(*nograd_inputs)
    outputs_ge = ge(*nograd_inputs)
    self.assertEqual(outputs, outputs_ge)
    outputs = func(*recording_inputs)
    if inputs_require_grads:
        grads = torch.autograd.grad(allSum(outputs), flattened_recording_inputs, allow_unused=allow_unused)
    outputs_ge = ge(*recording_inputs)
    if inputs_require_grads:
        grads_ge = torch.autograd.grad(allSum(outputs_ge), flattened_recording_inputs, allow_unused=allow_unused)
    self.assertEqual(outputs, outputs_ge)
    if inputs_require_grads:
        self.assertEqual(grads, grads_ge, atol=grad_atol, rtol=grad_rtol)
    outputs = func(*recording_inputs)
    l1 = allSum(outputs)
    if inputs_require_grads:
        grads = torch.autograd.grad(l1, flattened_recording_inputs, create_graph=True, allow_unused=allow_unused)
    if inputs_require_grads:
        l2 = allSum(grads) * l1
        grads2 = torch.autograd.grad(l2, flattened_recording_inputs, allow_unused=allow_unused)
    if inputs_require_grads:
        recording_inputs = do_input_map(lambda t: Variable(t, requires_grad=True), reference_tensors)
        flattened_recording_inputs = flatten_inputs(recording_inputs)
    outputs_ge = ge(*recording_inputs)
    l1_ge = allSum(outputs_ge)
    if inputs_require_grads:
        grads_ge = torch.autograd.grad(l1_ge, flattened_recording_inputs, create_graph=True, allow_unused=allow_unused)
    if inputs_require_grads:
        l2_ge = allSum(grads_ge) * l1_ge
        grads2_ge = torch.autograd.grad(l2_ge, flattened_recording_inputs, allow_unused=allow_unused)
    self.assertEqual(outputs, outputs_ge)
    if inputs_require_grads:
        self.assertEqual(grads, grads_ge, atol=grad_atol, rtol=grad_rtol)
        for (g2, g2_ge) in zip(grads2, grads2_ge, strict=True):
            if g2 is None and g2_ge is None:
                continue
            self.assertEqual(g2, g2_ge, atol=0.0008, rtol=0.0008)
    return ge

def _export_to_saved_model_graph(self, object_map, tensor_map, **unused_kwargs):
    if <MASK>:
        raise ValueError(f'Unable to save function {self.name} for the following reason(s):\n' + '\n'.join(self.graph.saving_errors))
    self.add_to_graph()
    object_map[self] = saved_model_exported_concrete.ExportedConcreteFunction(self, tensor_map)
