@trackable.no_automatic_dependency_tracking
def _set_input_attrs(self, inputs):
    """Sets attributes related to the inputs of the Model."""
    if <MASK>:
        raise ValueError('Model inputs are already set.')
    if self.__class__.__name__ == 'Sequential' and (not self.built):
        if tensor_util.is_tf_type(inputs):
            input_shape = (None,) + tuple(inputs.shape.as_list()[1:])
        elif isinstance(inputs, tensor_shape.TensorShape):
            input_shape = (None,) + tuple(inputs.as_list()[1:])
        elif isinstance(inputs, dict):
            if not training_utils_v1.is_feature_layer(self.layers[0]):
                raise ValueError("Passing a dictionary input to a Sequential Model which doesn't have FeatureLayer as the first layer is an error.")
            input_shape = (None,)
        else:
            input_shape = (None,) + tuple(inputs.shape[1:])
        self._build_input_shape = input_shape
    inputs = self._maybe_cast_inputs(inputs)
    model_inputs = training_utils_v1.ModelInputs(inputs)
    inputs = model_inputs.get_symbolic_inputs()
    self.inputs = model_inputs.get_symbolic_inputs(return_single_as_list=True)
    self.input_names = model_inputs.get_input_names()
    self._feed_inputs = []
    self._feed_input_names = []
    self._feed_input_shapes = []
    for (k, v) in model_inputs.as_dict():
        if backend.is_placeholder(v):
            self._feed_input_names.append(k)
            self._feed_inputs.append(v)
            self._feed_input_shapes.append(backend.int_shape(v))
    return inputs

def __init__(self, layout: OutputSpec, kernel: _OpOverloads, tensor_args: Sequence[IRNode], nontensor_args: Sequence[Any], unflatten_args: Callable[..., Any], kwargs: Optional[dict[str, Any]]=None, *, unbacked_bindings: Optional[dict[sympy.Symbol, pytree.KeyPath]]=None) -> None:
    super().__init__(layout, tuple(tensor_args), tuple(nontensor_args), op_overload=kernel)
    self.use_runtime_dispatch = False
    self.unbacked_bindings = unbacked_bindings or {}
    assert isinstance(kernel, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)), f'Fails to create FallbackKernel for {kernel}: {type(kernel)} not supported'
    self.op_overload = kernel
    self.unflatten_args = unflatten_args
    self.kwargs = {} if kwargs is None else kwargs
    assert self.python_kernel_name is not None
    V.graph.warn_fallback(self.python_kernel_name)
    self.alias_names: list[str] = []
    self.mutation_names: list[str] = []
    if isinstance(self.op_overload, torch._ops.HigherOrderOperator):
        return
    if '_c10d_functional' in self.op_overload.name():
        return
    schema = self.op_overload._schema
    if torch._library.utils.mutates_and_returns_first_arg(self.op_overload):
        self.mutation_names.append(tensor_args[0].get_name())
        return
    if schema.is_mutable and (not can_auto_functionalize(kernel)):
        raise NotImplementedError(f"NYI: Can't generate FallbackKernel for {kernel}")
    (args, kwargs) = self.unflatten_args(self.inputs, self.constant_args)

    def handle_aliasing_and_mutation(info: torch._C.Argument, arg: Any) -> None:
        if isinstance(info.type, torch.ListType):
            assert isinstance(arg, (list, tuple)), type(arg)
        if library_utils.is_tensor_like_type(info.type):
            assert not isinstance(arg, (tuple, list))
        if arg is None:
            return
        if <MASK>:
            return

        def add_alias(t: IRNode) -> None:
            self.alias_names.append(t.get_name())
            assert info.alias_info is not None
            if info.alias_info.is_write:
                self.mutation_outputs.append(MutationOutput(NoneLayout(device=t.get_device()), t, self))
        if library_utils.is_tensorlist_like_type(info.type):
            if arg is not None:
                for optional_tensor_arg in arg:
                    add_alias(optional_tensor_arg)
        else:
            assert library_utils.is_tensor_like_type(info.type)
            add_alias(arg)
    for (info, arg) in torch._library.utils.zip_schema(schema, args, kwargs):
        handle_aliasing_and_mutation(info, arg)

def schedule_comm_wait(graph: fx.Graph) -> None:
    """
    Delay the execution of wait tensors of allreduce until its first user.

    This algorithm considers the intermediate users, like split, getitem,
    of the wait node and schedule those intermediate users as well.
    This will result in a better overlapping result.
    """
    ops = (torch.ops._c10d_functional.all_reduce_.default, torch.ops._c10d_functional.all_reduce.default, torch.ops._c10d_functional.all_reduce_coalesced.default, torch.ops._c10d_functional.all_reduce_coalesced_.default)
    comm_blocks = get_all_comm_blocks(graph, ops)
    if not comm_blocks:
        return
    allreduce_users = OrderedSet[fx.Node]()
    for allreduce in comm_blocks:
        for output in allreduce.outputs:
            allreduce_users.update(output.users)
    node_indices = {node: i for (i, node) in enumerate(graph.nodes)}
    for allreduce in comm_blocks:
        assert len(allreduce.outputs) >= 1, f'Found a allreduce that has zero outputs/users -- {allreduce}.'
        target_node = next(iter(next(iter(allreduce.outputs)).users))
        target_node_index = 2 ** 31
        for user in (user for output in allreduce.outputs for user in output.users):
            index = node_indices[user]
            if index < target_node_index:
                target_node = user
                target_node_index = index
        wait_idx = -1
        for (wait_idx, node) in enumerate(allreduce.node_list):
            if <MASK>:
                break
        assert wait_idx >= 0
        move_block_before(allreduce.node_list[wait_idx:], target_node)

@def_function.function
def matmul_and_same_scale(self, input_tensor: core.Tensor) -> Mapping[str, core.Tensor]:
    """Performs a matrix multiplication.

        Args:
          input_tensor: Input tensor to matmul with the filter.

        Returns:
          A map of: output key -> output result.
        """
    out = math_ops.matmul(input_tensor, self.filters, name='sample/matmul')
    if <MASK>:
        ones = array_ops.ones_like(out)
        out = array_ops.concat([out, ones], 0)
    elif self.same_scale_op == 'gather':
        out = array_ops.gather(out, indices=[0], axis=0)
    elif self.same_scale_op == 'max_pool':
        out = nn_ops.max_pool(out, ksize=3, strides=1, padding='SAME')
    elif self.same_scale_op == 'pad':
        paddings = array_ops.ones((array_ops.rank(out), 2), dtype=dtypes.int32)
        out = array_ops.pad(out, paddings, 'CONSTANT')
    elif self.same_scale_op == 'reshape':
        out = array_ops.reshape(out, [-1])
    elif self.same_scale_op == 'select':
        rng = np.random.default_rng(seed=1234)
        condition = ops.convert_to_tensor(rng.uniform(low=0.0, high=1.0, size=out.shape) < 0.5)
        ones = array_ops.ones_like(out)
        out = math_ops.select(condition, out, ones)
    elif self.same_scale_op == 'slice':
        begin = array_ops.zeros(array_ops.rank(out), dtype=dtypes.int32)
        size = array_ops.ones(array_ops.rank(out), dtype=dtypes.int32)
        out = array_ops.slice(out, begin, size)
    elif self.same_scale_op == 'transpose':
        out = array_ops.transpose(out)
    else:
        raise NotImplementedError('{} is not implemented for integration test.'.format(self.same_scale_op))
    return {'output': out}

def check_worker_number_rationality(self):

    def _create_warning_msg(num_worker_suggest, num_worker_created, cpuset_checked):
        suggested_max_worker_msg = 'Our suggested max number of worker in current system is {}{}, which is smaller than what this DataLoader is going to create.'.format(num_worker_suggest, '' if cpuset_checked else ' (`cpuset` is not taken into account)') if num_worker_suggest is not None else 'DataLoader is not able to compute a suggested max number of worker in current system.'
        warn_msg = f'This DataLoader will create {num_worker_created} worker processes in total. {suggested_max_worker_msg} Please be aware that excessive worker creation might get DataLoader running slow or even freeze, lower the worker number to avoid potential slowness/freeze if necessary.'
        return warn_msg
    if <MASK>:
        return
    max_num_worker_suggest = None
    cpuset_checked = False
    if hasattr(os, 'sched_getaffinity'):
        try:
            max_num_worker_suggest = len(os.sched_getaffinity(0))
            cpuset_checked = True
        except Exception:
            pass
    if max_num_worker_suggest is None:
        cpu_count = os.cpu_count()
        if cpu_count is not None:
            max_num_worker_suggest = cpu_count
    if max_num_worker_suggest is None:
        warnings.warn(_create_warning_msg(max_num_worker_suggest, self.num_workers, cpuset_checked))
        return
    if self.num_workers > max_num_worker_suggest:
        warnings.warn(_create_warning_msg(max_num_worker_suggest, self.num_workers, cpuset_checked))

def _reset_is_grad_none(self) -> None:
    """
        Reset ``_is_grad_none_mask`` as needed.

        This method should only be
        called in the post-backward after gradient computation, in which case
        if a parameter requires gradient, then it will surely receive a
        gradient and we may reset its mask entry to ``False``.
        """
    if <MASK>:
        return
    _p_assert(self._training_state == HandleTrainingState.BACKWARD_POST, 'Expects to only be called in the post-backward after gradient computation')
    flat_param = self.flat_param
    if flat_param._params is None:
        raise AssertionError('Expected _params to be not None')
    for (i, param) in enumerate(flat_param._params):
        if param.requires_grad:
            if flat_param._is_grad_none_mask is None:
                raise AssertionError('Expected _is_grad_none_mask to be not None')
            flat_param._is_grad_none_mask[i] = False

