def dispatch_lambda_exprs(ps: PythonSignature, f: NativeFunction, *, symint: bool=True) -> DispatchLambdaArgumentExprs:
    arg_parser_outputs = arg_parser_output_exprs(ps, f, symint=symint)
    lambda_args = dispatch_lambda_args(ps, f, symint=symint)
    inits: list[str] = []
    lambda_args_exprs: dict[str, str] = {}
    has_toptions = has_tensor_options(f)
    for a in ps.arguments(skip_tensor_options=True):
        name = a.name
        arg_parser_expr = arg_parser_outputs[a.name].expr
        if has_toptions and name == 'self':
            inits.extend([f'auto self = {arg_parser_expr};'])
            lambda_args_exprs[name] = name
        elif isinstance(a, PythonOutArgument) and len(a.outputs) > 1 and f.func.is_out_fn():
            inits.extend([f'auto out = {arg_parser_expr};'])
            for (i, out_arg) in enumerate(a.outputs):
                lambda_args_exprs[out_arg.name] = f'out[{i}]'
        elif str(a.type) == 'Dimname[]?':
            inits.extend([f'auto __{name} = {arg_parser_expr};', f'::std::optional<DimnameList> {name} = __{name} ? ::std::make_optional(DimnameList(__{name}.value())) : ::std::nullopt;'])
            lambda_args_exprs[name] = name
        else:
            lambda_args_exprs[name] = arg_parser_expr
    if ps.method:
        lambda_args_exprs['self'] = 'self'
    tensor_options_args_names = [a.name for a in ps.tensor_options_args]
    if has_toptions:
        if f.func.is_out_fn():
            raise RuntimeError(f'{f.func}: tensor options with output arg')
        for a in ps.tensor_options_args:
            if a.name not in TENSOR_OPTIONS_FIELDS:
                raise RuntimeError(f"{f.func}: unrecognized tensor options field '{a.name}' in python binding arguments")
            if str(a.type) != TENSOR_OPTIONS_FIELDS.get(a.name):
                raise RuntimeError(f"{f.func}: unrecognized type '{str(a.type)}' for tensor options field '{a.name}'")
        if not all((a in tensor_options_args_names for a in TENSOR_OPTIONS_FIELDS)):
            raise RuntimeError(f'{f.func}: incomplete tensor options args: {tensor_options_args_names}')
        inits.append(f"const auto options = TensorOptions()\n    .dtype({arg_parser_outputs['dtype'].expr})\n    .device({arg_parser_outputs['device'].expr})\n    .layout({arg_parser_outputs['layout'].expr})\n    .requires_grad({arg_parser_outputs['requires_grad'].expr})\n    .pinned_memory({arg_parser_outputs['pin_memory'].expr});\ntorch::utils::maybe_initialize_device(options);\n")
        lambda_args_exprs['options'] = 'options'
    if not has_toptions and tensor_options_args_names:
        if <MASK>:
            if not f.func.is_out_fn():
                raise RuntimeError(f'{f.func}: dtype in tensor_options_args without output arg, {ps} {ps.arguments}')
            if not all((a in tensor_options_args_names for a in ('layout', 'device'))):
                raise RuntimeError(f'{f.func}: incomplete tensor options for output check')
            inits.append(f"check_out_type_matches({arg_parser_outputs['out'].expr}, {arg_parser_outputs['dtype'].expr},\n                       {arg_parser_outputs['dtype'].is_none_expr}, {arg_parser_outputs['layout'].expr},\n                       {arg_parser_outputs['device'].expr}, {arg_parser_outputs['device'].is_none_expr});\n")
        if 'requires_grad' not in tensor_options_args_names:
            raise RuntimeError(f'{f.func}: expected "requires_grad" in tensor_options_args absent, but found [{tensor_options_args_names}]')
    return DispatchLambdaArgumentExprs(exprs=tuple((lambda_args_exprs[a.name] for a in lambda_args)), inits=inits)

def condition(children):
    for child in children:
        if <MASK>:
            if "Policy: we don't run" in child.attrib['message']:
                return True
    return False

def is_allowlisted(o, check_call_override=True, allow_namedtuple_subclass=False):
    """Checks whether an entity is allowed for use in graph mode.

  Examples of allowed entities include all members of the tensorflow
  package.

  Args:
    o: A Python entity.
    check_call_override: Reserved for internal use. When set to `False`, it
      disables the rule according to which classes are allowed if their
      __call__ method is allowed.
    allow_namedtuple_subclass: Reserved for internal use. When `True`,
      namedtuple subclasses are not allowed.

  Returns:
    Boolean
  """
    if isinstance(o, functools.partial):
        m = functools
    else:
        m = tf_inspect.getmodule(o)
    if hasattr(m, '__name__'):
        for rule in config.CONVERSION_RULES:
            action = rule.get_action(m)
            if action == config.Action.CONVERT:
                logging.log(2, 'Not allowed: %s: %s', o, rule)
                return False
            elif action == config.Action.DO_NOT_CONVERT:
                logging.log(2, 'Allowlisted: %s: %s', o, rule)
                return True
    if hasattr(o, '__code__') and tf_inspect.isgeneratorfunction(o):
        logging.log(2, 'Allowlisted: %s: generator functions are not converted', o)
        return True
    if check_call_override and (not tf_inspect.isclass(o)) and hasattr(o, '__call__'):
        if <MASK>:
            logging.log(2, 'Allowlisted: %s: object __call__ allowed', o)
            return True
    owner_class = None
    if tf_inspect.ismethod(o):
        owner_class = inspect_utils.getmethodclass(o)
        if owner_class is tf_method_target.TfMethodTarget:
            owner_class = o.__self__.target_class
        if owner_class is not None:
            if issubclass(owner_class, unittest.TestCase):
                logging.log(2, 'Allowlisted: %s: method of TestCase subclass', o)
                return True
            owner_class = inspect_utils.getdefiningclass(o, owner_class)
            if is_allowlisted(owner_class, check_call_override=False, allow_namedtuple_subclass=True):
                logging.log(2, 'Allowlisted: %s: owner is allowed %s', o, owner_class)
                return True
    if inspect_utils.isnamedtuple(o):
        if allow_namedtuple_subclass:
            if not any((inspect_utils.isnamedtuple(base) for base in o.__bases__)):
                logging.log(2, 'Allowlisted: %s: named tuple', o)
                return True
        else:
            logging.log(2, 'Allowlisted: %s: named tuple or subclass', o)
            return True
    logging.log(2, 'Not allowed: %s: default rule', o)
    return False

def get_meta(op, key, device_name=None, version=(0, torch.float16, 0.5), exact=False):
    """Return triton kernel meta parameters of the specified op and its inputs key.

    Parameters
    ----------
    op (str): The name of an operation that implementation uses meta parameters.
    key (tuple): A tuple of op input parameters, e.g. shapes, etc.
    device_name (optional, str): The name of a device for which op
      parameters are provided.
    version (optional, hashable): Specifies the version of parameters.
    exact (optional, bool): When True, the returned data (if
      available) corresponds exactly to the specified device_name and
      version information. Otherwise, if the corresponding data is not
      available but there exists a data set that is computed for a
      similar GPU device, then this data set will be returned.

    Returns
    -------
    result (dict): The requested mapping of parameter names and
      values, or None when no data is available. If the input `key`
      contains `"*"`, the result will be a dictionary of keys and
      mappings that match with the given `key`.
    """
    if device_name is None:
        device_name = torch.cuda.get_device_name()
    op_data = _operation_device_version_data.get((op, device_name, version))
    if op_data is None and (not exact):
        if re.match('NVIDIA A100[^\\d]', device_name) is not None:
            device_name = 'NVIDIA A100-SXM4-80GB'
        else:
            return
        op_data = _operation_device_version_data.get((op, device_name, version))
    if op_data is None:
        return
    matching_data = {}
    if '*' in key:
        for op_key in op_data:
            if [None for (k1, k2) in zip(op_key, key) if k2 != '*' and k1 != k2]:
                continue
            matching_data[op_key] = op_data[op_key]
    else:
        values = op_data.get(key)
        if values is not None:
            matching_data[key] = values
    matching_meta = {}
    for (op_key, values) in matching_data.items():
        if op == 'scatter_mm':
            names = ('GROUP_SIZE', 'SPLIT_N', 'TILE_M', 'TILE_N', 'num_stages', 'num_warps')
            meta = dict(zip(names, values))
        elif op in {'bsr_dense_addmm', '_int_bsr_dense_addmm'}:
            meta = dict(zip(('GROUP_SIZE_ROW', 'SPLIT_N', 'num_stages', 'num_warps'), values))
        else:
            raise NotImplementedError(f'names for op={op!r}')
        if <MASK>:
            return meta
        matching_meta[op_key] = meta
    if '*' in key:
        return matching_meta

