def _assert_caught_no_extra_warnings(*, caught_warnings: Sequence[warnings.WarningMessage], expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None) -> None:
    """Assert that no extra warnings apart from the expected ones are caught."""
    extra_warnings = []
    for actual_warning in caught_warnings:
        if _is_unexpected_warning(actual_warning, expected_warning):
            if actual_warning.category == ResourceWarning:
                if 'unclosed <ssl.SSLSocket' in str(actual_warning.message):
                    continue
                if any(('matplotlib' in mod for mod in sys.modules)):
                    continue
            if <MASK>:
                continue
            extra_warnings.append((actual_warning.category.__name__, actual_warning.message, actual_warning.filename, actual_warning.lineno))
    if extra_warnings:
        raise AssertionError(f'Caused unexpected warning(s): {extra_warnings!r}')

def diff(self, other: 'SideEffects') -> Optional[str]:
    if self.id_to_variable != other.id_to_variable:
        sk_itv = self.id_to_variable.keys()
        ok_itv = other.id_to_variable.keys()
        if sk_itv != ok_itv:
            return f'id_to_variable keys: {sk_itv} != {ok_itv}'
        return 'id_to_variable: unknown diff'
    elif self.store_attr_mutations != other.store_attr_mutations:
        sk_sam = self.store_attr_mutations.keys()
        ok_sam = other.store_attr_mutations.keys()
        if sk_sam != ok_sam:
            return f'store_attr_mutations keys: {sk_sam} != {ok_sam}'
        return 'store_attr_mutations: unknown diff'
    elif <MASK>:
        return 'save_for_backward'
    elif self.tensor_hooks != other.tensor_hooks:
        return 'tensor_hooks'
    else:
        return None

def get_filters(self, request):
    lookup_params = self.get_filters_params()
    may_have_duplicates = False
    has_active_filters = False
    for (key, value_list) in lookup_params.items():
        for value in value_list:
            if not self.model_admin.lookup_allowed(key, value, request):
                raise DisallowedModelAdminLookup(f'Filtering by {key} not allowed')
    filter_specs = []
    for list_filter in self.list_filter:
        lookup_params_count = len(lookup_params)
        if <MASK>:
            spec = list_filter(request, lookup_params, self.model, self.model_admin)
        else:
            field_path = None
            if isinstance(list_filter, (tuple, list)):
                (field, field_list_filter_class) = list_filter
            else:
                (field, field_list_filter_class) = (list_filter, FieldListFilter.create)
            if not isinstance(field, Field):
                field_path = field
                field = get_fields_from_path(self.model, field_path)[-1]
            spec = field_list_filter_class(field, request, lookup_params, self.model, self.model_admin, field_path=field_path)
            if lookup_params_count > len(lookup_params):
                may_have_duplicates |= lookup_spawns_duplicates(self.lookup_opts, field_path)
        if spec and spec.has_output():
            filter_specs.append(spec)
            if lookup_params_count > len(lookup_params):
                has_active_filters = True
    if self.date_hierarchy:
        year = lookup_params.pop('%s__year' % self.date_hierarchy, None)
        if year is not None:
            month = lookup_params.pop('%s__month' % self.date_hierarchy, None)
            day = lookup_params.pop('%s__day' % self.date_hierarchy, None)
            try:
                from_date = datetime(int(year[-1]), int(month[-1] if month is not None else 1), int(day[-1] if day is not None else 1))
            except ValueError as e:
                raise IncorrectLookupParameters(e) from e
            if day:
                to_date = from_date + timedelta(days=1)
            elif month:
                to_date = (from_date + timedelta(days=32)).replace(day=1)
            else:
                to_date = from_date.replace(year=from_date.year + 1)
            if settings.USE_TZ:
                from_date = make_aware(from_date)
                to_date = make_aware(to_date)
            lookup_params.update({'%s__gte' % self.date_hierarchy: [from_date], '%s__lt' % self.date_hierarchy: [to_date]})
    try:
        for (key, value) in lookup_params.items():
            lookup_params[key] = prepare_lookup_value(key, value)
            may_have_duplicates |= lookup_spawns_duplicates(self.lookup_opts, key)
        return (filter_specs, bool(filter_specs), lookup_params, may_have_duplicates, has_active_filters)
    except FieldDoesNotExist as e:
        raise IncorrectLookupParameters(e) from e

def _apply_to_tensors(fn, container):
    """Recursively apply to all tensor in different kinds of container types."""

    def apply(x):
        from torch.nn.parallel.scatter_gather import _is_namedtuple
        if isinstance(x, torch.Tensor):
            return fn(x)
        elif <MASK>:
            dc = dataclasses.replace(x)
            changes = {f.name: apply(getattr(dc, f.name)) for f in dataclasses.fields(dc)}
            return dataclasses.replace(dc, **changes)
        elif isinstance(x, OrderedDict):
            od = x.__class__()
            for (key, value) in x.items():
                od[key] = apply(value)
            return od
        elif isinstance(x, PackedSequence):
            apply(x.data)
            return x
        elif isinstance(x, dict):
            return {key: apply(value) for (key, value) in x.items()}
        elif _is_namedtuple(x):
            res = (apply(el) for el in x)
            return type(x)(*res)
        elif isinstance(x, (list, tuple, set)):
            return type(x)((apply(el) for el in x))
        else:
            return x
    return apply(container)

