def _reduce_congruences(self) -> dict[sympy.Symbol, set[sympy.Expr]]:
    reduced_congruences: dict[sympy.Symbol, set[sympy.Expr]] = {}
    for (s, congruences) in self._congruences.items():
        remainder_modulus_pairs = []
        congruences_to_check = set()
        for congruence in congruences:
            (base, divisor) = congruence.args
            tmp = sympy.Symbol('reduce_congruences_tmp', integer=True)
            (symbol, solution) = sympy.solve_linear(base - divisor * tmp, symbols=[s])
            if s == symbol:
                (modulus, remainder) = sympy.polys.polytools.div(solution, tmp)
                if isinstance(modulus, sympy.Integer) and isinstance(remainder, sympy.Integer):
                    remainder = remainder % modulus
                    remainder_modulus_pairs.append((remainder, modulus))
                    continue
            congruences_to_check.add(congruence)
        if <MASK>:
            (remainder, modulus) = sympy.ntheory.modular.solve_congruence(*remainder_modulus_pairs)
            reduced_congruences[s] = {(s - remainder) % modulus}
            substitution = {s: modulus * sympy.Symbol('tmp', integer=True) + remainder}
            reduced_congruences[s].update((congruence for congruence in congruences_to_check if not sympy.checksol(congruence, substitution)))
        else:
            reduced_congruences[s] = congruences_to_check
    return reduced_congruences

def train_batch(modeldef):
    if device == 'cuda':
        timer_class = torch.cuda.Event
    else:
        timer_class = Event
    fwd_start_event = timer_class(enable_timing=True)
    fwd_end_event = timer_class(enable_timing=True)
    bwd_start_event = timer_class(enable_timing=True)
    bwd_end_event = timer_class(enable_timing=True)
    gc.collect()
    fwd_start_event.record()
    with record_function('## forward ##'):
        forward_output = modeldef.forward(*modeldef.inputs)
    fwd_end_event.record()
    if modeldef.backward_setup is not None:
        backward_input = modeldef.backward_setup(forward_output)
    else:
        backward_input = forward_output
    gc.collect()
    bwd_start_event.record()
    if <MASK>:
        modeldef.backward(*backward_input)
    bwd_end_event.record()
    if modeldef.backward is not None:
        with torch.no_grad():
            for param in modeldef.params:
                assert param.grad is not None
                param.grad.zero_()
    if device == 'cuda':
        torch.cuda.synchronize()
    fwd_time = fwd_start_event.elapsed_time(fwd_end_event)
    bwd_time = bwd_start_event.elapsed_time(bwd_end_event)
    return (fwd_time, bwd_time)

