def tf_tensor_list_new(elements, element_dtype=None, element_shape=None):
    """Overload of new_list that stages a Tensor list creation."""
    if tensor_util.is_tf_type(elements):
        if element_shape is not None:
            raise ValueError('element shape may not be specified when creating list from tensor')
        element_shape = array_ops.shape(elements)[1:]
        l = list_ops.tensor_list_from_tensor(elements, element_shape=element_shape)
        return l
    elements = tuple((ops.convert_to_tensor(el) for el in elements))
    all_dtypes = set((el.dtype for el in elements))
    if len(all_dtypes) == 1:
        inferred_dtype = tuple(all_dtypes)[0]
        if element_dtype is not None and element_dtype != inferred_dtype:
            raise ValueError('incompatible dtype; specified: {}, inferred from {}: {}'.format(element_dtype, elements, inferred_dtype))
    elif all_dtypes:
        if element_dtype is not None:
            raise ValueError('specified dtype {} is inconsistent with that of elements {}'.format(element_dtype, elements))
        inferred_dtype = dtypes.variant
    else:
        inferred_dtype = dtypes.variant
    all_shapes = set((tuple(el.shape.as_list()) for el in elements))
    if len(all_shapes) == 1:
        inferred_shape = array_ops.shape(elements[0])
        if <MASK>:
            raise ValueError('incompatible shape; specified: {}, inferred from {}: {}'.format(element_shape, elements, inferred_shape))
    elif all_shapes:
        if element_shape is not None:
            raise ValueError('specified shape {} is inconsistent with that of elements {}'.format(element_shape, elements))
        inferred_shape = constant_op.constant(-1)
    else:
        inferred_shape = constant_op.constant(-1)
    if element_dtype is None:
        element_dtype = inferred_dtype
    if element_shape is None:
        element_shape = inferred_shape
    element_shape = ops.convert_to_tensor(element_shape, dtype=dtypes.int32)
    l = list_ops.empty_tensor_list(element_shape=element_shape, element_dtype=element_dtype)
    for el in elements:
        l = list_ops.tensor_list_push_back(l, el)
    return l

@classmethod
def __torch_function__(cls, func, types, args=(), kwargs=None):
    kwargs = kwargs or {}
    from ._ops_refs import _MASKEDTENSOR_FUNCTION_TABLE
    if <MASK>:
        return _MASKEDTENSOR_FUNCTION_TABLE[func](*args, **kwargs)
    if not all((issubclass(cls, t) for t in types)):
        return NotImplemented
    with torch._C.DisableTorchFunctionSubclass():
        ret = func(*args, **kwargs)
        if func in get_default_nowrap_functions():
            return ret
        else:
            return torch._tensor._convert(ret, cls)

def sdpa_constraint(fx_node, *args, **kwargs):

    def apply_constraint(idx, arg, fx_arg):
        if not isinstance(arg, ir.IRNode):
            return arg
        meta_val = fx_arg.meta['val']
        meta_stride_expr = [s.node.expr if isinstance(s, torch.SymInt) else s for s in meta_val.stride()]
        shape_env = V.graph.sizevars.shape_env
        stride_order = ir.get_stride_order(meta_val.stride(), shape_env)
        if stride_order and stride_order[-1] != 0:
            stride_order = list(reversed(range(len(arg.get_size()))))
        if fx_node.target == aten._scaled_dot_product_efficient_attention_backward.default and idx in (0, 5):
            assert len(stride_order) == 4
            stride_order = (3, 1, 2, 0)
        if not meta_val.is_cuda:
            return ir.ExternKernel.require_stride_order(arg, stride_order)
        ALIGNMENT = 8
        effn_attn_fwd_bias = fx_node.target == torch.ops.aten._scaled_dot_product_efficient_attention.default and idx == 3
        assert isinstance(arg, TensorBox)
        if len(arg.get_size()) not in (3, 4):
            return arg
        is_aligned_tensor = ir.is_aligned_realized_tensor(arg, ALIGNMENT)
        if <MASK>:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if isinstance(arg, IRNode) and arg.maybe_get_stride() is not None and is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if effn_attn_fwd_bias:
            out_size = list(arg.get_size())
            expanded_dims = []
            maybe_stride = arg.maybe_get_stride()
            for i in range(len(arg.get_size()) - 1):
                if V.graph.sizevars.statically_known_equals(meta_stride_expr[i], 0) or (maybe_stride is not None and V.graph.sizevars.statically_known_equals(maybe_stride[i], 0)):
                    expanded_dims.append(i)
            out_strides = [-1] * len(out_size)
            out_strides[-1] = 1
            stride = 1
            for i in range(len(out_size) - 2, -1, -1):
                if out_strides[i + 1] != 0:
                    stride = stride * out_size[i + 1]
                if i in expanded_dims:
                    if V.graph.sizevars.statically_known_equals(out_strides[i + 1] % ALIGNMENT, 0):
                        out_strides[i] = 0
                        continue
                if not V.graph.sizevars.statically_known_equals(stride % ALIGNMENT, 0):
                    stride = ceildiv(stride, ALIGNMENT) * ALIGNMENT
                out_strides[i] = stride
            return ir.ExternKernel.require_exact_strides(arg, out_strides)
        if is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if isinstance(arg, IRNode) and arg.maybe_get_stride() is not None and is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)

        def is_aligned(x):
            return V.graph.sizevars.guard_or_false(sympy.Eq(Mod(x.get_size()[-1], ALIGNMENT), 0))
        if isinstance(arg.data, ir.BaseView):
            if not is_aligned(arg):
                if is_aligned(arg.unwrap_view()):
                    return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        return ir.ExternKernel.require_stride_order(arg, stride_order)
    args = tuple((apply_constraint(idx, arg, fx_arg) for (idx, (arg, fx_arg)) in enumerate(zip(args, fx_node.args))))
    kwargs = {k: apply_constraint(-1, v, fx_node.kwargs[k]) for (k, v) in kwargs.items()}
    return (args, kwargs)

