@property
def __doc__(self):
    docs = [f'Multiply dispatched method: {self.name}']
    if self.doc:
        docs.append(self.doc)
    other = []
    for sig in self.ordering[::-1]:
        func = self.funcs[sig]
        if <MASK>:
            s = f'Inputs: <{str_signature(sig)}>\n'
            s += '-' * len(s) + '\n'
            s += func.__doc__.strip()
            docs.append(s)
        else:
            other.append(str_signature(sig))
    if other:
        docs.append('Other signatures:\n    ' + '\n    '.join(other))
    return '\n\n'.join(docs)

@lru_cache(256)
def _maybe_guard_rel(self, expr: sympy.Expr) -> None:
    """
        The relational guard is guarded to be true.  Use this information to
        simplify shapes (i.e. a == b or a % 5 == 0)
        """
    if isinstance(expr, sympy.And):
        for arg in expr.args:
            self._maybe_guard_rel(arg)
        return
    elif not isinstance(expr, sympy.Rel):
        log.warning('_maybe_guard_rel() was called on non-relation expression %s', expr)
        return
    if isinstance(expr, sympy.Ne):
        return
    free = list(expr.free_symbols)
    assert len(free) > 0, f'The expression should not be static by this point: {expr}'
    if len(free) > 5:
        return

    def _smart_symbol_sort(x: sympy.Symbol) -> tuple[int, int, str]:
        has_only_ephemeral_sources = x in self.var_to_sources and all((s.is_ephemeral() for s in self.var_to_sources[x]))
        hint_size = self.size_hint(x, allow_none=True)
        if hint_size is None:
            size = sys.maxsize
        elif symbol_is_type(x, SymT.SIZE):
            assert isinstance(hint_size, sympy.Expr)
            size = int(hint_size)
        else:
            size = sys.maxsize
        name = x.name
        return (1 if has_only_ephemeral_sources else 0, size, name)
    free = sorted(free, key=_smart_symbol_sort, reverse=True)
    lhs = expr.lhs
    rhs = expr.rhs
    self._refine_ranges(expr)
    if not isinstance(expr, sympy.Eq):
        return
    if not expr.has(Mod):
        try:
            floor_div_atoms = lhs.atoms(FloorDiv).union(rhs.atoms(FloorDiv))
            if len(floor_div_atoms) > 0 and any((a.divisor != 1 for a in floor_div_atoms)):
                raise NotImplementedError

            def trivial_solve(lhs: sympy.Expr, rhs: sympy.Expr) -> bool:
                if isinstance(lhs, sympy.Symbol):
                    if free_unbacked_symbols(lhs) and (not _free_non_source_unbacked_symbols(rhs, self.unbacked_inputs)):
                        return True
                    if symbol_is_type(lhs, SymT.FLOAT):
                        return True
                return False
            if <MASK>:
                self._set_replacement(lhs, self._find(rhs), 'trivial_lhs')
            elif trivial_solve(rhs, lhs):
                self._set_replacement(rhs, self._find(lhs), 'trivial_rhs')
            else:
                r = try_solve(expr, free[0], floordiv_inequality=False)
                if r is not None and all((t.is_integer for t in sympy.preorder_traversal(r[1]))):
                    new_var = self._find(r[1])
                    ok = len(free_unbacked_symbols(new_var)) == 0
                    if ok:
                        self._set_replacement(free[0], new_var, 'solve')
        except NotImplementedError:
            pass
    if expr.has(Mod):
        mod_expr = next(iter(expr.atoms(Mod)))
        try:
            r = try_solve(expr, mod_expr, floordiv_inequality=False)
            if r is not None and r[1] == 0:
                self._add_divisible(mod_expr)
                (p, q) = mod_expr.args
                if isinstance(q, sympy.Number) and isinstance(p, sympy.Mul) and (len(p.args) == 2):
                    (c, i0) = p.args
                    if isinstance(c, sympy.Number) and isinstance(i0, sympy.Symbol) and self.is_unbacked_symint(i0):
                        d = q / sympy.gcd(q, c)
                        i1 = self.create_unbacked_symint().node.expr
                        self._update_var_to_range(i1, SymPyValueRangeAnalysis.floordiv(self.var_to_range[i0], ValueRanges.wrap(d)))
                        if i0 in self.unbacked_var_to_val:
                            self.set_unbacked_var_to_val(i1, self.unbacked_var_to_val[i0] // d)
                        if i0 in self.size_like:
                            self.size_like.add(i1)
                        self._set_replacement(i0, d * i1, 'divisibility')
        except NotImplementedError:
            pass
    return

def __eq__(self, other):
    if <MASK>:
        return False
    if isinstance(self.loc, _Number) and isinstance(other.loc, _Number):
        if self.loc != other.loc:
            return False
    elif not (self.loc == other.loc).all().item():
        return False
    if isinstance(self.scale, _Number) and isinstance(other.scale, _Number):
        if self.scale != other.scale:
            return False
    elif not (self.scale == other.scale).all().item():
        return False
    return True

@classmethod
def realize_into(cls, src: IRNode, dst: IRNode) -> IRNode:
    if not isinstance(dst, ReinterpretView):
        if <MASK>:
            (storage, layout) = as_storage_and_layout(dst)
            dst = ReinterpretView(data=storage, layout=layout)
    assert isinstance(dst, ReinterpretView), type(dst)
    if isinstance(src, TensorBox):
        return cls.realize_into(src.data, dst)
    if isinstance(src, StorageBox):
        src.realize()
        assert hasattr(src.data, 'layout')
        if cls.can_realize_into_without_copy(src, dst):
            src.data.layout = NonOwningLayout(dst)
            return src.data
    pw = Pointwise.create(device=src.get_device(), dtype=src.get_dtype(), inner_fn=src.make_loader(), ranges=[V.graph.sizevars.check_equals_and_simplify(a, b) for (a, b) in zip(src.get_size(), dst.get_size())])
    return cls.realize_into(pw, dst)

def get_reachable_from_inputs(inputs, targets=None):
    """Returns the set of tensors/ops reachable from `inputs`.

  Stops if all targets have been found (target is optional).

  Only valid in Symbolic mode, not Eager mode.

  Args:
    inputs: List of tensors.
    targets: List of tensors.

  Returns:
    A set of tensors reachable from the inputs (includes the inputs themselves).
  """
    inputs = nest.flatten(inputs, expand_composites=True)
    reachable = object_identity.ObjectIdentitySet(inputs)
    if targets:
        remaining_targets = object_identity.ObjectIdentitySet(nest.flatten(targets))
    queue = collections.deque(inputs)
    while queue:
        x = queue.pop()
        if isinstance(x, tuple(_user_convertible_tensor_types)):
            continue
        if isinstance(x, ops.Operation):
            outputs = x.outputs[:] or []
            outputs += x._control_outputs
        elif isinstance(x, variables.Variable):
            try:
                outputs = [x.op]
            except AttributeError:
                outputs = []
        elif <MASK>:
            outputs = x.consumers()
        else:
            raise TypeError('Expected Operation, Variable, or Tensor, got ' + str(x))
        for y in outputs:
            if y not in reachable:
                reachable.add(y)
                if targets:
                    remaining_targets.discard(y)
                queue.appendleft(y)
        if targets and (not remaining_targets):
            return reachable
    return reachable

def visit_With(self, node):
    node.items = self.visit_block(node.items)
    (node.body, definitely_returns) = self._visit_statement_block(node, node.body)
    if <MASK>:
        anno.setanno(node, STMT_DEFINITELY_RETURNS, True)
    return node

@tf_export.tf_export('experimental.numpy.take', v1=[])
@np_utils.np_doc('take')
def take(a, indices, axis=None, out=None, mode='clip'):
    """out argument is not supported, and default mode is clip."""
    if <MASK>:
        raise ValueError('out argument is not supported in take.')
    if mode not in {'raise', 'clip', 'wrap'}:
        raise ValueError("Invalid mode '{}' for take".format(mode))
    a = asarray(a)
    indices = asarray(indices)
    if axis is None:
        a = array_ops.reshape(a, [-1])
        axis = 0
    axis_size = array_ops.shape(a, out_type=indices.dtype)[axis]
    if mode == 'clip':
        indices = clip_ops.clip_by_value(indices, 0, axis_size - 1)
    elif mode == 'wrap':
        indices = math_ops.floormod(indices, axis_size)
    else:
        raise ValueError("The 'raise' mode to take is not supported.")
    return array_ops.gather(a, indices, axis=axis)

