def __init__(self, optimizer: Optimizer, last_epoch: int=-1) -> None:
    if not isinstance(optimizer, Optimizer):
        raise TypeError(f'{type(optimizer).__name__} is not an Optimizer')
    self.optimizer = optimizer
    if last_epoch == -1:
        for group in optimizer.param_groups:
            initial_lr = group['lr']
            if isinstance(initial_lr, Tensor):
                initial_lr = initial_lr.clone()
            group.setdefault('initial_lr', initial_lr)
    else:
        for (i, group) in enumerate(optimizer.param_groups):
            if <MASK>:
                raise KeyError(f"param 'initial_lr' is not specified in param_groups[{i}] when resuming scheduler with last_epoch >= 0.\nThis typically happens when:\n1. You're trying to resume training from a checkpoint but haven't properly loaded the optimizer state\n2. You're using last_epoch >= 0 for a fresh training run (not recommended)")
    self.base_lrs: list[float | Tensor] = _param_groups_val_list(optimizer, 'initial_lr')
    self.last_epoch = last_epoch

    def patch_track_step_called(opt: Optimizer):
        if hasattr(opt.step, '_wrapped_by_lr_sched'):
            return opt.step

        def wrap_step(step_fn):
            opt_ref = ref(self.optimizer)
            func = step_fn.__func__

            @wraps(func)
            def wrapper(*args, **kwargs):
                opt = opt_ref()
                opt._opt_called = True
                return func.__get__(opt, opt.__class__)(*args, **kwargs)
            wrapper._wrapped_by_lr_sched = True
            return wrapper
        opt.step = wrap_step(opt.step)
    patch_track_step_called(self.optimizer)
    self._initial_step()

def _parse(self) -> DataFrame:
    json = self.json
    orient = self.orient
    if orient == 'split':
        decoded = {str(k): v for (k, v) in ujson_loads(json, precise_float=self.precise_float).items()}
        self.check_keys_split(decoded)
        orig_names = [tuple(col) if isinstance(col, list) else col for col in decoded['columns']]
        decoded['columns'] = dedup_names(orig_names, is_potential_multi_index(orig_names, None))
        return DataFrame(dtype=None, **decoded)
    elif orient == 'index':
        return DataFrame.from_dict(ujson_loads(json, precise_float=self.precise_float), dtype=None, orient='index')
    elif <MASK>:
        return parse_table_schema(json, precise_float=self.precise_float)
    else:
        return DataFrame(ujson_loads(json, precise_float=self.precise_float), dtype=None)

def get_flex_attn_bwd_configs(self, head_dim: int, dtype: Any) -> list[FlexBwDConfig]:
    flex_attn_bwd_configs: list[FlexBwDConfig] = []
    if config.max_autotune:
        if config.max_autotune_flex_search_space == 'EXHAUSTIVE':
            return self.exhaustive_flex_attn_bwd_configs
        flex_attn_bwd_configs += self.flex_attn_bwd_autotune_configs
    if <MASK>:
        default_config = ROCmFlexBwDConfig(16, 16, 16, 16, 1, 4)
    elif head_dim <= 256:
        if head_dim == 64:
            default_config = ROCmFlexBwDConfig(64, 64, 64, 64, 1, 4)
        elif head_dim == 128:
            default_config = ROCmFlexBwDConfig(64, 128, 128, 64, 1, 8)
        else:
            default_config = ROCmFlexBwDConfig(64, 64, 64, 64, 1, 4)
    else:
        default_config = ROCmFlexBwDConfig(16, 16, 16, 16, 1, 4)
    if default_config not in flex_attn_bwd_configs:
        flex_attn_bwd_configs.append(default_config)
    return flex_attn_bwd_configs

