def _rand_like(rand_fn: Callable[..., torch.Tensor], self: torch.Tensor, *, dtype: Optional[torch.dtype]=None, device: Optional[torch.device]=None, memory_format: torch.memory_format=torch.preserve_format, **kwargs: Any) -> torch.Tensor:
