    if isinstance(data, BlockManager):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        if index is None and columns is None and (dtype is None) and (not copy):
            NDFrame.__init__(self, data)
            return
    if isinstance(index, set):
        raise ValueError('index cannot be a set')
    if isinstance(columns, set):
        raise ValueError('columns cannot be a set')
    if copy is None:
        if <MASK>:
            copy = True
        elif not isinstance(data, (Index, DataFrame, Series)):
            copy = True
        else:
            copy = False
    if data is None:
        index = index if index is not None else default_index(0)
        columns = columns if columns is not None else default_index(0)
        dtype = dtype if dtype is not None else pandas_dtype(object)
        data = []
    if isinstance(data, BlockManager):
        mgr = self._init_mgr(data, axes={'index': index, 'columns': columns}, dtype=dtype, copy=copy)
    elif isinstance(data, dict):
        mgr = dict_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, ma.MaskedArray):
        from numpy.ma import mrecords
        if isinstance(data, mrecords.MaskedRecords):
            raise TypeError('MaskedRecords are not supported. Pass {name: data[name] for name in data.dtype.names} instead')
        data = sanitize_masked_array(data)
        mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, (np.ndarray, Series, Index, ExtensionArray)):
        if data.dtype.names:
            data = cast(np.ndarray, data)
            mgr = rec_array_to_mgr(data, index, columns, dtype, copy)
        elif isinstance(data, (ABCSeries, ABCIndex)) and data.name is not None:
            mgr = dict_to_mgr({data.name: data}, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif is_list_like(data):
        if not isinstance(data, abc.Sequence):
            if hasattr(data, '__array__'):
                data = np.asarray(data)
            else:
                data = list(data)
        if len(data) > 0:
            if is_dataclass(data[0]):
                data = dataclasses_to_dicts(data)
            if not isinstance(data, np.ndarray) and treat_as_nested(data):
                if columns is not None:
                    columns = ensure_index(columns)
                (arrays, columns, index) = nested_data_to_arrays(data, columns, index, dtype)
                mgr = arrays_to_mgr(arrays, columns, index, dtype=dtype)
            else:
                mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = dict_to_mgr({}, index, columns if columns is not None else default_index(0), dtype=dtype)
    else:
        if index is None or columns is None:
            raise ValueError('DataFrame constructor not properly called!')
        index = ensure_index(index)
        columns = ensure_index(columns)
        if not dtype:
            (dtype, _) = infer_dtype_from_scalar(data)
        if isinstance(dtype, ExtensionDtype):
            values = [construct_1d_arraylike_from_scalar(data, len(index), dtype) for _ in range(len(columns))]
            mgr = arrays_to_mgr(values, columns, index, dtype=None)
        else:
            arr2d = construct_2d_arraylike_from_scalar(data, len(index), len(columns), dtype, copy)
            mgr = ndarray_to_mgr(arr2d, index, columns, dtype=arr2d.dtype, copy=False)
    NDFrame.__init__(self, mgr)

def _get_cross_device_ops(self, value):
    if not self._use_merge_call():
        if not isinstance(self._cross_device_ops, cross_device_ops_lib.CollectiveAllReduce):
            logging.warning('Under XLA context, MirroredStrategy uses CollectiveAllReduce op. Although %r is provided to initialize MirroredStrategy, it is ignored in XLA. Please use CollectiveAllReduce(or default option) in the future, since other cross device ops are not well supported on XLA.', self._cross_device_ops)
        return self._collective_ops
    if isinstance(value, values.DistributedValues):
        value_int32 = True in {dtypes.as_dtype(v.dtype) == dtypes.int32 for v in value.values}
    else:
        value_int32 = dtypes.as_dtype(value.dtype) == dtypes.int32
    if <MASK>:
        return cross_device_ops_lib.ReductionToOneDevice()
    else:
        return self._cross_device_ops

def _GetNormalizeOpTest(dtype_, shape_, ord_, axis_):

    @test_util.run_in_graph_and_eager_modes
    def Test(self):
        is_matrix_norm = (isinstance(axis_, tuple) or isinstance(axis_, list)) and len(axis_) == 2
        is_fancy_p_norm = np.isreal(ord_) and np.floor(ord_) != ord_
        if <MASK>:
            self.skipTest('Not supported by neither numpy.linalg.norm nor tf.norm')
        if ord_ == 'euclidean' or (axis_ is None and len(shape) > 2):
            self.skipTest('Not supported by numpy.linalg.norm')
        matrix = np.random.randn(*shape_).astype(dtype_)
        if dtype_ in (np.complex64, np.complex128):
            matrix += 1j * np.random.randn(*shape_).astype(dtype_)
        (tf_np_n, _) = self.evaluate(nn_impl.normalize(matrix, ord_, axis_))
        np_n = _Normalize(matrix, ord_, axis_)
        self.assertAllClose(tf_np_n, np_n, rtol=1e-05, atol=1e-05)
    return Test

def is_superperiod(source, target) -> bool:
    """
    Returns True if upsampling is possible between source and target
    frequencies

    Parameters
    ----------
    source : str or DateOffset
        Frequency converting from
    target : str or DateOffset
        Frequency converting to

    Returns
    -------
    bool
    """
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)
    if _is_annual(source):
        if _is_annual(target):
            return get_rule_month(source) == get_rule_month(target)
        if <MASK>:
            smonth = get_rule_month(source)
            tmonth = get_rule_month(target)
            return _quarter_months_conform(smonth, tmonth)
        return target in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_quarterly(source):
        return target in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_monthly(source):
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_weekly(source):
        return target in {source, 'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'B':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'C':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'D':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'h':
        return target in {'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'min':
        return target in {'min', 's', 'ms', 'us', 'ns'}
    elif source == 's':
        return target in {'s', 'ms', 'us', 'ns'}
    elif source == 'ms':
        return target in {'ms', 'us', 'ns'}
    elif source == 'us':
        return target in {'us', 'ns'}
    elif source == 'ns':
        return target in {'ns'}
    else:
        return False

def get_result(self) -> DataFrame:
    (join_index, left_indexer, right_indexer) = self._get_join_info()
    left_join_indexer: npt.NDArray[np.intp] | None
    right_join_indexer: npt.NDArray[np.intp] | None
    if self.fill_method == 'ffill':
        if left_indexer is None:
            left_join_indexer = None
        else:
            left_join_indexer = libjoin.ffill_indexer(left_indexer)
        if <MASK>:
            right_join_indexer = None
        else:
            right_join_indexer = libjoin.ffill_indexer(right_indexer)
    elif self.fill_method is None:
        left_join_indexer = left_indexer
        right_join_indexer = right_indexer
    else:
        raise ValueError("fill_method must be 'ffill' or None")
    result = self._reindex_and_concat(join_index, left_join_indexer, right_join_indexer)
    self._maybe_add_join_keys(result, left_indexer, right_indexer)
    return result

def __torch_dispatch__(self, func, types, args=(), kwargs=None):
    if func == torch.ops._c10d_functional.wait_tensor.default and active_fake_mode():
        res = args[0]
    else:
        res = func(*args, **kwargs or {})
    if <MASK>:
        reftype = _MemRefType.OPT
    elif self._mod_tracker.is_bw and (not self._in_ac):
        reftype = _MemRefType.TEMP
    else:
        reftype = _MemRefType.ACT
    tree_map_only(torch.Tensor, partial(self._track, reftype), res)
    peak_state = _ModState.PEAK_BW if self._mod_tracker.is_bw else _ModState.PEAK_FW
    self._update_peak_stats(peak_state)
    return res

@register_op_impl(torch.ops.aten.slice.Tensor)
def slice_forward(fake_mode, func, self, dim: int=0, start: Optional[int]=None, end: Optional[int]=None, step: int=1):
    from torch.fx.experimental.symbolic_shapes import guard_or_false, statically_known_true
    shape_env = fake_mode.shape_env
    ndim = self.dim()
    if ndim == 0:
        raise RuntimeError('slice() cannot be applied to a 0-dim tensor.')
    dim = canonicalize_dim(self.dim(), dim)
    sizes = list(self.size())
    strides = list(self.stride())
    if step <= 0:
        raise RuntimeError('slice step must be positive')
    start_index = 0 if start is None else _compute_slice_index(sizes[dim], start)
    end_index = sizes[dim] if statically_known_true(end == sys.maxsize) or end is None else _compute_slice_index(sizes[dim], end)
    new_size = None
    if start_index is not None and end_index is not None:
        if guard_or_false(end_index >= start_index):
            new_size = (end_index - start_index + step - 1) // step
        elif <MASK>:
            new_size = 0
    if new_size is None:
        new_size = shape_env.create_unbacked_symint()
        torch._check(new_size >= 0)
        torch._check(new_size <= sizes[dim])
    new_stride = strides[dim] * step
    if start_index is not None:
        storage_offset = self.storage_offset() + start_index * strides[dim]
    else:
        storage_offset = shape_env.create_unbacked_symint()
        torch._check(storage_offset >= 0)
    sizes[dim] = new_size
    strides[dim] = new_stride
    if self.is_quantized:
        raise NotImplementedError("Slice decomposition for quantized tensors aren't implemented")
    else:
        return self.as_strided(sizes, strides, storage_offset)

def _type_repr(obj: object) -> str:
    """Return the repr() of an object, special-casing types (internal helper).
    If obj is a type, we return a shorter version than the default
    type.__repr__, based on the module and qualified name, which is
    typically enough to uniquely identify a type.  For everything
    else, we fall back on repr(obj).
    """
    if isinstance(obj, type) and (not isinstance(obj, types.GenericAlias)):
        if obj.__module__ == 'builtins':
            return obj.__qualname__
        return f'{obj.__module__}.{obj.__qualname__}'
    if obj is ...:
        return '...'
    if <MASK>:
        return obj.__name__
    return repr(obj)

@tf_export.tf_export('experimental.numpy.roll', v1=[])
@np_utils.np_doc('roll')
def roll(a, shift, axis=None):
    a = asarray(a)
    if <MASK>:
        return manip_ops.roll(a, shift, axis)
    original_shape = array_ops.shape(a)
    a = manip_ops.roll(array_ops.reshape(a, [-1]), shift, 0)
    return array_ops.reshape(a, original_shape)

@deco_stream
@normalizer
def choice(a: ArrayLike, size=None, replace=True, p: Optional[ArrayLike]=None):
    if a.numel() == 1:
        a = torch.arange(a)
    if size is None:
        num_el = 1
    elif _util.is_sequence(size):
        num_el = 1
        for el in size:
            num_el *= el
    else:
        num_el = size
    if <MASK>:
        p = torch.ones_like(a) / a.shape[0]
    atol = sqrt(torch.finfo(p.dtype).eps)
    if abs(p.sum() - 1.0) > atol:
        raise ValueError('probabilities do not sum to 1.')
    indices = torch.multinomial(p, num_el, replacement=replace)
    if _util.is_sequence(size):
        indices = indices.reshape(size)
    samples = a[indices]
    return samples

def update_info(self, info) -> None:
    """
        set/update the info for this indexable with the key/value
        if there is a conflict raise/warn as needed
        """
    for key in self._info_fields:
        value = getattr(self, key, None)
        idx = info.setdefault(self.name, {})
        existing_value = idx.get(key)
        if key in idx and value is not None and (existing_value != value):
            if <MASK>:
                ws = attribute_conflict_doc % (key, existing_value, value)
                warnings.warn(ws, AttributeConflictWarning, stacklevel=find_stack_level())
                idx[key] = None
                setattr(self, key, None)
            else:
                raise ValueError(f'invalid info for [{self.name}] for [{key}], existing_value [{existing_value}] conflicts with new value [{value}]')
        elif value is not None or existing_value is not None:
            idx[key] = value

def find_parent_nodes_of_subgraph(self, tag: str) -> NodeSet:
    """
        Finds parent nodes of the `tag` subgraph.

        Traverse the inputs of nodes in the subgraph, if input doesn't belong to the subgraph
        and is not a placeholder, we consider it as the parent node of the subgraph.
        """
    parent_nodes = set()
    for node in self.module.graph.nodes:
        if <MASK>:
            for arg in node.all_input_nodes:
                if arg.op in CALLABLE_NODE_OPS and arg.tag != tag:
                    parent_nodes.add(arg)
    return parent_nodes

def assertExpected(self, s, subname=None):
    """
        Test that a string matches the recorded contents of a file
        derived from the name of this test and subname.  This file
        is placed in the 'expect' directory in the same directory
        as the test script. You can automatically update the recorded test
        output using --accept.

        If you call this multiple times in a single function, you must
        give a unique subname each time.
        """
    if not isinstance(s, str):
        raise TypeError('assertExpected is strings only')

    def remove_prefix(text, prefix):
        if text.startswith(prefix):
            return text[len(prefix):]
        return text
    module_id = self.__class__.__module__
    munged_id = remove_prefix(self.id(), module_id + '.')
    test_file = os.path.realpath(sys.modules[module_id].__file__)
    expected_file = os.path.join(os.path.dirname(test_file), 'expect', munged_id)
    subname_output = ''
    if subname:
        expected_file += '-' + subname
        subname_output = f' ({subname})'
    expected_file += '.expect'
    expected = None

    def accept_output(update_type):
        print(f'Accepting {update_type} for {munged_id}{subname_output}:\n\n{s}')
        with open(expected_file, 'w') as f:
            s_tag = re.sub('(producer_version): "[0-9.]*"', '\\1: "CURRENT_VERSION"', s)
            f.write(s_tag)
    try:
        with open(expected_file) as f:
            expected = f.read()
    except OSError as e:
        if e.errno != errno.ENOENT:
            raise
        elif <MASK>:
            return accept_output('output')
        else:
            raise RuntimeError(f'I got this output for {munged_id}{subname_output}:\n\n{s}\n\nNo expect file exists; to accept the current output, run:\npython {__main__.__file__} {munged_id} --accept') from None
    if IS_WINDOWS:
        expected = re.sub('CppOp\\[(.+?)\\]', 'CppOp[]', expected)
        s = re.sub('CppOp\\[(.+?)\\]', 'CppOp[]', s)
    expected = expected.replace('producer_version: "CURRENT_VERSION"', f'producer_version: "{torch.onnx.producer_version}"')
    if expecttest.ACCEPT:
        if expected != s:
            return accept_output('updated output')
    elif hasattr(self, 'assertMultiLineEqual'):
        self.assertMultiLineEqual(expected, s)
    else:
        self.assertEqual(s, expected)

def update_coverage(coverage_records: list[CoverageRecord], interested_folders: list[str], platform: TestPlatform) -> None:
    for item in coverage_records:
        record = item.to_dict()
        file_path = record['filepath']
        if <MASK>:
            continue
        covered_range = record['covered_lines']
        uncovered_range = record['uncovered_lines']
        file_path = transform_file_name(file_path, interested_folders, platform)
        if file_path not in covered_lines:
            covered_lines[file_path] = set()
        if file_path not in uncovered_lines:
            uncovered_lines[file_path] = set()
        if covered_range is not None:
            covered_lines[file_path].update(covered_range)
        if uncovered_range is not None:
            uncovered_lines[file_path].update(uncovered_range)

def check_unspec_python_args(args: Iterable[Any], kwargs: Mapping[Any, Any]) -> bool:
    from .variables.constant import ConstantVariable
    from .variables.tensor import UnspecializedPythonVariable
    unspec_count = 0
