def _env_rendezvous_handler(url: str, timeout: timedelta=default_pg_timeout, **kwargs):

    def _error(msg):
        return _rendezvous_error('env:// rendezvous: ' + msg)

    def _env_error(var):
        return _error(f'environment variable {var} expected, but not set')

    def _get_env_or_raise(env_var: str) -> str:
        env_val = os.environ.get(env_var, None)
        if not env_val:
            raise _env_error(env_var)
        else:
            return env_val
    result = urlparse(url)
    query_dict = _query_to_dict(result.query)
    rank: int
    world_size: int
    master_port: int
    master_addr: str
    if 'rank' in query_dict:
        rank = int(query_dict['rank'])
    else:
        rank = int(_get_env_or_raise('RANK'))
    if <MASK>:
        world_size = int(query_dict['world_size'])
    else:
        world_size = int(_get_env_or_raise('WORLD_SIZE'))
    master_addr = _get_env_or_raise('MASTER_ADDR')
    master_port = int(_get_env_or_raise('MASTER_PORT'))
    use_libuv = _get_use_libuv_from_query_dict(query_dict)
    store = _create_c10d_store(master_addr, master_port, rank, world_size, timeout, use_libuv)
    yield (store, rank, world_size)
    raise RuntimeError('Unable to perform re-rendezvous using env:// method')

def lookup_op(qualname: str) -> OpOverload:
    (namespace, name) = parse_namespace(qualname)
    if <MASK>:
        (name, overload) = name.split('.')
    else:
        overload = 'default'
    ns = getattr(torch.ops, namespace)
    packet = getattr(ns, name)
    return getattr(packet, overload)

def download_file(self, remote_file: str, local_file: Optional[str]=None) -> None:
    if <MASK>:
        return self.scp_download_file(remote_file, local_file)
    tmp_file = os.path.join('/tmp', os.path.basename(remote_file))
    self.run_ssh_cmd(['docker', 'cp', f'{self.container_id}:/root/{remote_file}', tmp_file])
    self.scp_download_file(tmp_file, local_file)
    self.run_ssh_cmd(['rm', tmp_file])

def _check_scorers_accept_sample_weight(self):
    (scorers, _) = self._get_scorers()
    if <MASK>:
        for (name, scorer) in scorers._scorers.items():
            if not scorer._accept_sample_weight():
                warnings.warn(f'The scoring {name}={scorer} does not support sample_weight, which may lead to statistically incorrect results when fitting {self} with sample_weight. ')
        return scorers._accept_sample_weight()
    if hasattr(scorers, '_accept_sample_weight'):
        accept = scorers._accept_sample_weight()
    else:
        accept = 'sample_weight' in signature(scorers).parameters
    if not accept:
        warnings.warn(f'The scoring {scorers} does not support sample_weight, which may lead to statistically incorrect results when fitting {self} with sample_weight. ')
    return accept

def check_accuracy(actual_csv, expected_csv, expected_filename):
    failed = []
    improved = []
    if <MASK>:
        flaky_models.update({'Background_Matting', 'alexnet', 'demucs', 'densenet121', 'detectron2_fcos_r_50_fpn', 'doctr_det_predictor', 'doctr_reco_predictor', 'dpn107', 'fbnetv3_b', 'levit_128', 'llava', 'microbench_unbacked_tolist_sum', 'mnasnet1_0', 'mobilenet_v2', 'pytorch_CycleGAN_and_pix2pix', 'pytorch_stargan', 'resnet152', 'resnet18', 'resnet50', 'resnext50_32x4d', 'sam', 'sam_fast', 'shufflenet_v2_x1_0', 'squeezenet1_1', 'stable_diffusion_text_encoder', 'stable_diffusion_unet', 'swsl_resnext101_32x16d', 'torchrec_dlrm', 'vgg16', 'BERT_pytorch', 'coat_lite_mini', 'mobilenet_v3_large', 'vision_maskrcnn', 'meta-llama/Llama-3.2-1B', 'google/gemma-2-2b', 'google/gemma-3-4b-it', 'openai/whisper-tiny', 'Qwen/Qwen3-0.6B', 'mistralai/Mistral-7B-Instruct-v0.3', 'openai/gpt-oss-20b'})
    for model in actual_csv['name']:
        accuracy = get_field(actual_csv, model, 'accuracy')
        expected_accuracy = get_field(expected_csv, model, 'accuracy')
        if accuracy == expected_accuracy:
            status = 'PASS' if expected_accuracy == 'pass' else 'XFAIL'
            print(f'{model:34}  {status}')
            continue
        elif model in flaky_models:
            if accuracy == 'pass':
                status = 'PASS_BUT_FLAKY:'
            else:
                status = 'FAIL_BUT_FLAKY:'
        elif accuracy != 'pass':
            status = 'FAIL:'
            failed.append(model)
        else:
            status = 'IMPROVED:'
            improved.append(model)
        print(f'{model:34}  {status:9} accuracy={accuracy}, expected={expected_accuracy}')
    msg = ''
    if failed or improved:
        if failed:
            msg += textwrap.dedent(f"\n            Error: {len(failed)} models have accuracy status regressed:\n                {' '.join(failed)}\n\n            ")
        if improved:
            msg += textwrap.dedent(f"\n            Improvement: {len(improved)} models have accuracy status improved:\n                {' '.join(improved)}\n\n            ")
        sha = os.getenv('SHA1', '{your CI commit sha}')
        msg += textwrap.dedent(f'\n        If this change is expected, you can update `{expected_filename}` to reflect the new baseline.\n        from pytorch/pytorch root, run\n        `python benchmarks/dynamo/ci_expected_accuracy/update_expected.py {sha}`\n        and then `git add` the resulting local changes to expected CSVs to your commit.\n        ')
    return (failed or improved, msg)

def _get_iterator_ops_from_collection(self, ds_fn, sparse_tensors=False):
    all_ops = ops.get_collection('iterator_ops')
    if <MASK>:
        (init_op, indices, values, dense_shape) = all_ops
        return (init_op, sparse_tensor.SparseTensor(indices, values, dense_shape))
    get_next_list = []
    i = 1
    for output_class in nest.flatten(self._get_output_classes(ds_fn)):
        if output_class is sparse_tensor.SparseTensor:
            (indices, values, dense_shape) = all_ops[i:i + 3]
            i += 3
            get_next_list.append(sparse_tensor.SparseTensor(indices, values, dense_shape))
        else:
            get_next_list.append(all_ops[i])
            i += 1
    return (all_ops[0], nest.pack_sequence_as(self._get_output_types(ds_fn), get_next_list))

def _gen_transform_infos_non_cached(src_spec: DTensorSpec, dst_spec: DTensorSpec, use_graph_based_transform: Optional[bool]=None) -> list[_TransformInfo]:
    transform_infos: list[_TransformInfo] = []
    device_mesh = src_spec.device_mesh
    src_shard_order = src_spec.shard_order
    dst_shard_order = dst_spec.shard_order
    assert src_shard_order is not None and dst_shard_order is not None
    if use_graph_based_transform is None:
        if all((DTensorSpec.is_default_device_order(order) for order in (src_shard_order, dst_shard_order))):
            use_graph_based_transform = False
        else:
            use_graph_based_transform = True
    drp = get_redistribute_planner(device_mesh, len(src_spec.shape))
    if <MASK>:
        transform_infos = drp.generate_graph_based_transform_infos(src_spec, dst_spec, src_spec.shape)
    else:
        transform_infos = drp.generate_greedy_transform_infos(src_spec, dst_spec)
    return transform_infos

def _next_data(self):
    while True:
        while self._rcvd_idx < self._send_idx:
            info = self._task_info.get(self._rcvd_idx, None)
            if info:
                worker_id = info[0]
                if len(info) == 2 or self._workers_status[worker_id]:
                    break
                del self._task_info[self._rcvd_idx]
            self._rcvd_idx += 1
        else:
            if not self._persistent_workers:
                self._shutdown_workers()
            raise StopIteration
        if len(self._task_info[self._rcvd_idx]) == 2:
            (worker_id, data) = self._task_info.pop(self._rcvd_idx)
            self._rcvd_idx += 1
            return self._process_data(data, worker_id)
        if self._shutdown or self._tasks_outstanding <= 0:
            raise AssertionError('Invalid iterator state: shutdown or no outstanding tasks when fetching next data')
        (idx, data) = self._get_data()
        self._tasks_outstanding -= 1
        if self._dataset_kind == _DatasetKind.Iterable:
            if isinstance(data, _utils.worker._IterableDatasetStopIteration):
                if self._persistent_workers:
                    self._workers_status[data.worker_id] = False
                else:
                    self._mark_worker_as_unavailable(data.worker_id)
                self._try_put_index()
                continue
        if <MASK>:
            if not self._in_order:
                worker_id = self._task_info.pop(idx)[0]
                return self._process_data(data, worker_id)
            self._task_info[idx] += (data,)
        else:
            worker_id = self._task_info.pop(idx)[0]
            self._rcvd_idx += 1
            return self._process_data(data, worker_id)

def __iter__(self):
    if [dim for dim in self.shape if dim <= 0]:
        return
    start = self.start[:]
    stop = self.stop[:]
    step = self.step[:]
    ndims = self.var.ndim
    while True:
        count = self.buf_size or reduce(mul, self.shape)
        rundim = 0
        for i in range(ndims - 1, -1, -1):
            if <MASK>:
                stop[i] = start[i] + 1
            elif count <= self.shape[i]:
                stop[i] = start[i] + count * step[i]
                rundim = i
            else:
                stop[i] = self.stop[i]
            stop[i] = min(self.stop[i], stop[i])
            count = count // self.shape[i]
        slice_ = tuple((slice(*t) for t in zip(start, stop, step)))
        yield self.var[slice_]
        start[rundim] = stop[rundim]
        for i in range(ndims - 1, 0, -1):
            if start[i] >= self.stop[i]:
                start[i] = self.start[i]
                start[i - 1] += self.step[i - 1]
        if start[0] >= self.stop[0]:
            return

@classmethod
def _get_param_names(cls):
    """Get parameter names for the estimator"""
    init = getattr(cls.__init__, 'deprecated_original', cls.__init__)
    if init is object.__init__:
        return []
    init_signature = inspect.signature(init)
    parameters = [p for p in init_signature.parameters.values() if p.name != 'self' and p.kind != p.VAR_KEYWORD]
    for p in parameters:
        if <MASK>:
            raise RuntimeError("scikit-learn estimators should always specify their parameters in the signature of their __init__ (no varargs). %s with constructor %s doesn't  follow this convention." % (cls, init_signature))
    return sorted([p.name for p in parameters])

def get_traceback_frame_variables(self, request, tb_frame):
    """
        Replace the values of variables marked as sensitive with
        stars (*********).
        """
    sensitive_variables = None
    if tb_frame.f_code.co_flags & inspect.CO_COROUTINE != 0 and tb_frame.f_code.co_name != 'sensitive_variables_wrapper':
        key = hash(f'{tb_frame.f_code.co_filename}:{tb_frame.f_code.co_firstlineno}')
        sensitive_variables = coroutine_functions_to_sensitive_variables.get(key, None)
    if sensitive_variables is None:
        current_frame = tb_frame
        while current_frame is not None:
            if current_frame.f_code.co_name == 'sensitive_variables_wrapper' and 'sensitive_variables_wrapper' in current_frame.f_locals:
                wrapper = current_frame.f_locals['sensitive_variables_wrapper']
                sensitive_variables = getattr(wrapper, 'sensitive_variables', None)
                break
            current_frame = current_frame.f_back
    cleansed = {}
    if self.is_active(request) and sensitive_variables:
        if sensitive_variables == '__ALL__':
            for name in tb_frame.f_locals:
                cleansed[name] = self.cleansed_substitute
        else:
            for (name, value) in tb_frame.f_locals.items():
                if name in sensitive_variables:
                    value = self.cleansed_substitute
                else:
                    value = self.cleanse_special_types(request, value)
                cleansed[name] = value
    else:
        for (name, value) in tb_frame.f_locals.items():
            cleansed[name] = self.cleanse_special_types(request, value)
    if <MASK>:
        cleansed['func_args'] = self.cleansed_substitute
        cleansed['func_kwargs'] = self.cleansed_substitute
    return cleansed.items()

def sparse_merge_impl(sp_ids, sp_values, vocab_size, name=None, already_sorted=False):
    """Internal implementation for sparse_merge to avoid deprecation warnings."""
    if isinstance(sp_ids, sparse_tensor.SparseTensorValue) or isinstance(sp_ids, sparse_tensor.SparseTensor):
        sp_ids = [sp_ids]
        if not (isinstance(vocab_size, tensor_lib.Tensor) or isinstance(vocab_size, numbers.Integral)):
            raise TypeError('vocab_size has to be a Tensor or Python int. Found %s' % type(vocab_size))
        vocab_size = [vocab_size]
    else:
        if not isinstance(sp_ids, collections_abc.Iterable):
            raise TypeError('sp_ids has to be a SparseTensor or list thereof. Found %s' % type(sp_ids))
        if not isinstance(vocab_size, collections_abc.Iterable):
            raise TypeError('vocab_size has to be a list of Tensors or Python ints. Found %s' % type(vocab_size))
        for dim in vocab_size:
            if not (isinstance(dim, tensor_lib.Tensor) or isinstance(dim, numbers.Integral)):
                raise TypeError('vocab_size has to be a list of Tensors or Python ints. Found %s' % type(dim))
    if len(sp_ids) != len(vocab_size):
        raise ValueError('sp_ids and vocab_size have to have equal lengths.')
    with ops.name_scope(name, 'SparseMerge', [sp_ids, sp_values]):
        sp_ids = [_convert_to_sparse_tensor(sp_ids_dim) for sp_ids_dim in sp_ids]
        sp_values = _convert_to_sparse_tensor(sp_values)
        ids = []
        for sp_ids_dim in sp_ids:
            ids_dim = sp_ids_dim.values
            if <MASK>:
                ids_dim = math_ops.cast(ids_dim, dtypes.int64)
            ids += [array_ops.expand_dims(ids_dim, axis=1)]
        vocab_size = [math_ops.cast(x, dtypes.int64) for x in vocab_size]
        indices_columns_to_preserve = sp_ids[0].indices[:, :-1]
        new_indices = array_ops.concat([indices_columns_to_preserve] + ids, 1)
        new_values = sp_values.values
        new_shape = array_ops.concat([sp_ids[0].dense_shape[:-1], vocab_size], 0)
        result = sparse_tensor.SparseTensor(new_indices, new_values, new_shape)
        if already_sorted:
            return result
        sorted_result = sparse_reorder(result)
        return sparse_tensor.SparseTensor(sorted_result.indices, sorted_result.values, new_shape)

def fn(grad_fn):

    def hook(_, grad_output):
        self.grad_outputs = self._pack_with_none(self.output_tensors_index, grad_output, self.n_outputs)
        if self.user_pre_hooks:
            expected_len = len(self.grad_outputs)
            for user_pre_hook in self.user_pre_hooks:
                hook_grad_outputs = user_pre_hook(self.module, self.grad_outputs)
                if hook_grad_outputs is None:
                    continue
                actual_len = len(hook_grad_outputs)
                if <MASK>:
                    raise RuntimeError(f'Backward pre hook returned an invalid number of grad_output, got {actual_len}, but expected {expected_len}')
                self.grad_outputs = hook_grad_outputs
        local_grad_outputs = self.grad_outputs
        if self.input_tensors_index is None:
            warnings.warn('Full backward hook is firing when gradients are computed with respect to module outputs since no inputs require gradients. See https://docs.pytorch.org/docs/main/generated/torch.nn.Module.html#torch.nn.Module.register_full_backward_hook for more details.', stacklevel=5)
            grad_inputs = self._pack_with_none([], [], self.n_inputs)
            for user_hook in self.user_hooks:
                res = user_hook(self.module, grad_inputs, self.grad_outputs)
                if res is not None and (not (isinstance(res, tuple) and all((el is None for el in res)))):
                    raise RuntimeError('Backward hook for Modules where no input requires gradient should always return None or None for all gradients.')
            self.grad_outputs = None
        if local_grad_outputs is not None:
            assert self.output_tensors_index is not None
            return tuple((local_grad_outputs[i] for i in self.output_tensors_index))
    grad_fn.register_hook(hook)

def codegen_kernel(self, name=None):
    """Called at the end to generate a final kernel string"""
    if self.args.inplace_buffers:
        raise Unsupported('inplace_buffers')
    meta = self.halide_kernel_meta()
    code = IndentedBuffer()
    code.splice('\n            import halide as hl\n            from torch._inductor.runtime import halide_helpers\n            from math import inf, nan\n\n            @hl.generator(name="kernel")\n            class Kernel:\n        ', strip=True)
    code.do_indent()
    for (_, arg) in self.halide_argdefs():
        if isinstance(arg, SizeArg):
            code.writeline(f'{arg.name} = hl.InputScalar({self.index_dtype})')
        else:
            assert arg.buffer, arg
            argcls = 'hl.OutputBuffer' if 'out' in arg.name else 'hl.InputBuffer'
            argtype = halide_type(arg.dtype)
            ndim = len(self.buffer_dimensions[arg.name])
            code.writeline(f'{arg.name} = {argcls}({argtype}, {ndim})')
    code.splice('\n            def generate(g):\n        ')
    code.do_indent()
    for (_, arg) in self.halide_argdefs():
        code.writeline(f'{arg.name} = g.{arg.name}')
    for (old, new) in self.args.aliases():
        code.writeline(f'{old} = {new}')
    code.splice(self.indexing_code)

    def update_index(m):
        var = cast(HalideCSEVariable, self.cse.varname_map[m.group(1)])
        assert var.used_dims is not None, var
        return str(var)
    for line in self.body._lines:
        if <MASK>:
            line = HalideCSEVariable.undefined_re.sub(update_index, line)
        code.writeline(line)
    code.writeline('')
    code.writeline('assert g.using_autoscheduler()')
    for (_, arg) in self.halide_argdefs():
        if isinstance(arg, SizeArg):
            hint = V.graph.sizevars.size_hint(arg.expr, fallback=1)
            code.writeline(f'{arg.name}.set_estimate({hint})')
        else:
            dims = self.buffer_dimensions[arg.name]
            range_hints = []
            for (i, dim) in enumerate(dims):
                hint = self._autoscheduler_workarounds(V.graph.sizevars.size_hint(dim.size, fallback=1), dims)
                range_hints.append(f'hl.Range(0, {hint})')
                if 'out' not in arg.name:
                    code.writeline(f'{arg.name}.dim({i}).set_min(0)')
                    try:
                        code.writeline(f'{arg.name}.dim({i}).set_stride({int(dim.stride)})')
                    except TypeError:
                        pass
                    try:
                        code.writeline(f'{arg.name}.dim({i}).set_extent({int(dim.size)})')
                    except TypeError:
                        pass
            code.writeline(f"{arg.name}.set_estimates([{', '.join(range_hints)}])")
    code.do_unindent(2)
    code.splice('\n            if __name__ == "__main__":\n                hl.main()\n            '.rstrip())
    if meta.scheduler:
        code.splice(f'\n                else:\n                    hl.load_plugin({HalideCodeCache.find_libautoschedule(meta.scheduler)!r})\n                    target = hl.Target({meta.target!r})\n                    autoscheduler = hl.AutoschedulerParams({meta.scheduler!r}, {meta.scheduler_flags!r})\n                    with hl.GeneratorContext(target, autoscheduler):\n                        gen = Kernel()\n                        pipeline = gen._build_pipeline()\n                        # gen.compile_to_callable() does not run the autoscheduler\n                        pipeline.apply_autoscheduler(target, autoscheduler)\n                        kernel = pipeline.compile_to_callable([\n                                gen._get_input_parameter(a.name)._to_argument()\n                                for a in gen._get_arginfos()\n                                if a.dir == hl.ArgInfoDirection.Input\n                            ], target)\n                ', strip=True)
    else:
        code.splice(f'\n                  else:\n                      with hl.GeneratorContext(hl.Target({meta.target!r})):\n                          kernel = Kernel().compile_to_callable()\n                  ', strip=True)
    return code.getvalue()

@ops.RegisterGradient('ResourceGatherNd')
def _ResourceGatherNdGrad(op: ops.Operation, grad):
    ref = op.inputs[0]
    indices = op.inputs[1]
    ref_shape = gen_resource_variable_ops.variable_shape(ref, indices.dtype)
    if <MASK>:
        ref_grad = indexed_slices_lib.IndexedSlices(grad, array_ops.squeeze(indices, axis=-1), ref_shape)
    else:
        ref_grad = array_ops.scatter_nd(indices, grad, ref_shape)
    return [ref_grad, None]

def _validate_args(self, y, sample_weights, steps):
    """Validates `__init__` arguments."""
    if not is_none_or_empty(y):
        raise ValueError('`y` argument is not supported when using dataset as input.')
    if <MASK>:
        raise ValueError('`sample_weight` argument is not supported when using dataset as input.')
    if steps is None:
        if _is_distributed_dataset(self._dataset):
            raise ValueError('When providing a distributed dataset, you must specify the number of steps to run.')
        size = cardinality.cardinality(self._dataset).numpy()
        if size == cardinality.INFINITE and steps is None:
            raise ValueError('When providing an infinite dataset, you must specify the number of steps to run (if you did not intend to create an infinite dataset, make sure to not call `repeat()` on the dataset).')

def _validate_sdpa_input(query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, attn_mask: Optional[torch.Tensor]=None, dropout_p=0.0, is_causal=False, scale=None):
    if query.dtype != key.dtype or query.dtype != value.dtype:
        raise ValueError(f'Expected query, key, and value to have the same dtype, but got query.dtype: {query.dtype}, key.dtype: {key.dtype}, and value.dtype: {value.dtype} instead.')
    if query.device != key.device or query.device != value.device:
        raise ValueError(f'Expected query, key, and value to have the same device type, but got query.device: {query.device}, key.device: {key.device}, and value.device: {value.device} instead.')
    if <MASK>:
        raise ValueError(f'Expected query, key, and value to all be  at least 2 dimensional, but got query.dim: {query.dim()}, key.dim: {key.dim()} and value.dim: {value.dim()} instead.')

def _remote_module_reducer(remote_module):
    """Serialize a RemoteModule."""
    pickled_attrs = {}
    for (k, v) in remote_module.__dict__.items():
        if k == 'module_rref':
            pickled_attrs[k] = v._serialize()
        elif <MASK>:
            pickled_attrs[k] = v
        elif k not in _REMOTE_MODULE_ATTRIBUTES_IGNORE_FOR_PICKLING:
            print(f'The new attribute ``{k}`` of RemoteModule is ignored during RPC pickling. To pickle this attribute, please add it to ``_REMOTE_MODULE_PICKLED_ATTRIBUTES``. Otherwise, please explicitly add it to ``_REMOTE_MODULE_ATTRIBUTES_IGNORE_FOR_PICKLING``.', file=sys.stderr)
    return (_remote_module_receiver, tuple(pickled_attrs.values()))

def _check_node_kwarg_arg_value(check_node, kwarg_name, args_index, expected_value):
    if <MASK>:
        actual_value = check_node.kwargs[kwarg_name]
        return actual_value == expected_value
    else:
        assert len(check_node.args) >= args_index + 1
        actual_value = check_node.args[args_index]
        return actual_value == expected_value

def _url_has_allowed_host_and_scheme(url, allowed_hosts, require_https=False):
    if url.startswith('///') or len(url) > MAX_URL_LENGTH:
        return False
    try:
        url_info = urlsplit(url)
    except ValueError:
        return False
    if not url_info.netloc and url_info.scheme:
        return False
    if unicodedata.category(url[0])[0] == 'C':
        return False
    scheme = url_info.scheme
    if <MASK>:
        scheme = 'http'
    valid_schemes = ['https'] if require_https else ['http', 'https']
    return (not url_info.netloc or url_info.netloc in allowed_hosts) and (not scheme or scheme in valid_schemes)

@register_decomposition(aten.addmv)
@out_wrapper(exact_dtype=True)
@pw_cast_for_opmath
def addmv(self: Tensor, mat1: Tensor, vec: Tensor, beta: int=1, alpha: int=1):
    if not self.is_floating_point() and (not self.is_complex()):
        beta = int(beta)
        alpha = int(alpha)
    out = alpha * torch.mv(mat1, vec)
    if beta == 0:
        return out
    if <MASK>:
        return beta * self
    return out + beta * self

@register_lowering(aten.mean)
def mean(x, axis=None, keepdim=False, *, dtype=None):
    if <MASK>:
        x = to_dtype(x, dtype)
    size = x.get_size()
    axis = _validate_reduction_axis(x, axis)
    output_dtype = x.get_dtype()
    if output_dtype in (torch.float16, torch.bfloat16):
        x = to_dtype(x, torch.float)
    sum_result = sum_(x, axis, keepdim)
    denom = sympy_product((size[i] for i in axis))
    denom = ir.IndexingConstant(index=denom, dtype=x.get_dtype(), device=x.get_device())
    denom = ExpandView.create(denom, list(sum_result.get_size()))
    return to_dtype(div(sum_result, denom), output_dtype)

def builtin_dispatch(tx: 'InstructionTranslator', args, kwargs):
    rv = handler(tx, args, kwargs)
    if <MASK>:
        return rv
    call_unimplemented_v2(args)

def _RandomPDMatrix(n, rng, dtype=np.float64):
    """Random positive definite matrix."""
    temp = rng.randn(n, n).astype(dtype)
    if <MASK>:
        temp.imag = rng.randn(n, n)
    return np.conj(temp).dot(temp.T)

def select_tiling(self, fn_list, var_sizes_list) -> tuple[list[int], list[int]]:
    loop_bodies = _get_loop_body(fn_list)
    all_dtypes = _get_dtype_from_loopbodies(loop_bodies)
    assert all_dtypes
    if any((dtype not in VECTORIZABLE_DTYPES for dtype in all_dtypes)):
        return ([], [])
    dtype = torch.float
    _lowp_fp_dtype = get_loop_body_lowp_fp(loop_bodies[0])[0]
    if _lowp_fp_dtype and all((get_loop_body_lowp_fp(loop_body)[0] == _lowp_fp_dtype for loop_body in loop_bodies[1:])):
        dtype = _lowp_fp_dtype
    tiling_factor = cpu_vec_isa.pick_vec_isa().nelements(dtype=dtype)
    tiling_indices = self._select_tiling_indices(fn_list, var_sizes_list, tiling_factor)
    if tiling_indices:
        (group, reduction_group) = max(var_sizes_list, key=lambda sizes: len(sizes[1]))
        call_ranges = tuple(group) + tuple(reduction_group)
        if config.cpp.enable_tiling_heuristics:

            def _try_get_stride(index, itervars, tiling_factor, tiling_indices):
                itervar = itervars[tiling_indices[0]]
                stride = stride_at_vec_range(index, itervar, tiling_factor)
                return stride if stride.is_number else None

            def _update_negative_op_count(node_name, non_contig_indexing_op_counter):
                if node_name not in non_contig_indexing_op_counter:
                    non_contig_indexing_op_counter[node_name] = 1
                else:
                    non_contig_indexing_op_counter[node_name] += 1

            def _is_valid_indices(itervars, tiling_indices):
                return len(tiling_indices) == 1 and len(itervars) > 0 and ((tiling_indices[0] if tiling_indices[0] >= 0 else tiling_indices[0] + len(itervars)) < len(itervars))
            itervars = [sympy_index_symbol_with_prefix(SymT.XBLOCK, n) for n in range(len(call_ranges))]
            reduction_depth = len(group)
            (vars, reduction_vars) = (itervars[:reduction_depth], itervars[reduction_depth:])
            op_counter: dict[str, int] = {}
            non_contig_indexing_op_counter: dict[str, int] = {}
            for _body in loop_bodies:
                sub_blocks = [_body.root_block] + list(_body.subblocks.values())
                for sub_block in sub_blocks:
                    for _node in sub_block.graph.nodes:
                        if _node.target in ['index_expr', 'load', 'store']:
                            arg_idx = 1 if _node.target == 'index_expr' else 2
                            index = sub_block.body.indexing_from_args((vars, reduction_vars))[_node.args[arg_idx].args[0]]
                            if _is_valid_indices(itervars, tiling_indices):
                                stride = _try_get_stride(index, itervars, tiling_factor, tiling_indices)
                                if stride is None if _node.target == 'index_expr' else stride not in [0, 1]:
                                    _update_negative_op_count(_node.target, non_contig_indexing_op_counter)
                        if isinstance(_node.target, str) and (not (_node.target.startswith('masked_subblock') or _node.target in ['ops', 'output', 'constant', 'get_index'])):
                            if _node.target not in op_counter:
                                op_counter[_node.target] = 1
                            else:
                                op_counter[_node.target] += 1
            op_num = sum(op_counter.values())
            non_contig_indexing_op_num = sum(non_contig_indexing_op_counter.values())
            ratio_threshold = 0.12
            quantity_threshold = 35
            if non_contig_indexing_op_num >= quantity_threshold or (op_num > 0 and non_contig_indexing_op_num / op_num >= ratio_threshold):
                return ([], [])
            if not reduction_group and group and (len(tiling_indices) == 1) and (not has_free_symbols([group[tiling_indices[0]]])) and (group[tiling_indices[0]] < tiling_factor / 4) and (op_num < 10):
                return ([], [])
        if dtype in DTYPE_LOWP_FP:
            factor_lowp = cpu_vec_isa.pick_vec_isa().nelements(dtype=dtype)
            for tiling_indice in tiling_indices:
                if tiling_indice < 0:
                    tiling_indice = tiling_indice + len(call_ranges)
                if <MASK>:
                    continue
                if has_free_symbols(call_ranges):
                    call_range = V.graph.sizevars.size_hint(call_ranges[tiling_indice], fallback=0)
                    if call_range < factor_lowp:
                        V.graph.sizevars.check_lt(call_range, factor_lowp)
                        tiling_factor = factor_lowp // 2
                        break
                elif call_ranges[tiling_indice] < factor_lowp:
                    tiling_factor = factor_lowp // 2
                    break
        if len(tiling_indices) == 1:
            return ([tiling_factor], tiling_indices)
        if len(tiling_indices) == 2:
            return ([tiling_factor, tiling_factor], tiling_indices)
    return ([], [])

def pandasSQL_builder(con, schema: str | None=None, need_transaction: bool=False) -> PandasSQL:
    """
    Convenience function to return the correct PandasSQL subclass based on the
    provided parameters.  Also creates a sqlalchemy connection and transaction
    if necessary.
    """
    import sqlite3
    if isinstance(con, sqlite3.Connection) or con is None:
        return SQLiteDatabase(con)
    sqlalchemy = import_optional_dependency('sqlalchemy', errors='ignore')
    if isinstance(con, str) and sqlalchemy is None:
        raise ImportError(f"Using URI string without version '{VERSIONS['sqlalchemy']}' or newer of 'sqlalchemy' installed.")
    if sqlalchemy is not None and isinstance(con, (str, sqlalchemy.engine.Connectable)):
        return SQLDatabase(con, schema, need_transaction)
    adbc = import_optional_dependency('adbc_driver_manager.dbapi', errors='ignore')
    if <MASK>:
        return ADBCDatabase(con)
    warnings.warn('pandas only supports SQLAlchemy connectable (engine/connection) or database string URI or sqlite3 DBAPI2 connection. Other DBAPI2 objects are not tested. Please consider using SQLAlchemy.', UserWarning, stacklevel=find_stack_level())
    return SQLiteDatabase(con)

@contextlib.contextmanager
def _assert_warns_context(warning_class, name=None):
    __tracebackhide__ = True
    with suppress_warnings() as sup:
        l = sup.record(warning_class)
        yield
        if <MASK>:
            name_str = f' when calling {name}' if name is not None else ''
            raise AssertionError('No warning raised' + name_str)

def regroup(values, wrap_class=values_lib.PerReplica, always_wrap=False):
    """Makes a nest per-replica into a nest of PerReplica/Mirrored values.

  Args:
    values: Values to regroup
    wrap_class: Class that `values` be wrapped in.
    always_wrap: Always wrap the `values` in `wrap_class` even if the values
        are the same except for DistributeVariable.
  Returns:
    Wrapped `values`.
  """
    v0 = values[0]
    if isinstance(v0, list):
        for v in values[1:]:
            assert isinstance(v, list)
            assert len(v) == len(v0), 'len(v) == %d, len(v0) == %d, v: %s, v0: %s' % (len(v), len(v0), v, v0)
        return [regroup(tuple((v[i] for v in values)), wrap_class, always_wrap) for i in range(len(v0))]
    if isinstance(v0, tuple):
        for v in values[1:]:
            assert isinstance(v, tuple)
            assert len(v) == len(v0), f'Values to regroup had different lengths: len(v) == {len(v)}, len(v0) == {len(v0)}, v: {v}, v0: {v0}'
        regrouped_tuple = tuple((regroup(tuple((v[i] for v in values)), wrap_class, always_wrap) for i in range(len(v0))))
        if <MASK>:
            assert hasattr(v0, '_make')
            return v0._make(regrouped_tuple)
        else:
            return regrouped_tuple
    if isinstance(v0, abc.Mapping):
        v0keys = v0.keys()
        for v in values[1:]:
            assert isinstance(v, abc.Mapping), 'v[0]: %r  v[i]: %r' % (v0, v)
            assert set(v.keys()) == set(v0keys), 'v[0].keys: %s  v[i].keys: %s' % (set(v0keys), set(v.keys()))
        return type(v0)({key: regroup(tuple((v[key] for v in values)), wrap_class, always_wrap) for key in v0keys})
    same_id = True
    for v in values[1:]:
        if v is not v0:
            same_id = False
            break
    if same_id and isinstance(v0, values_lib.DistributedVariable):
        return v0
    if same_id and (not always_wrap) and (value_container(v0) is v0):
        return v0
    if not isinstance(v0, resource_variable_ops._UnreadVariable) and value_container(v0) is not v0:
        assert not isinstance(v0, values_lib.MirroredVariable), 'ids = %s, values = %s' % ([id(v) for v in values], values)
        distributed_container = value_container(v0)
        assert distributed_container is not None
        for v in values[1:]:
            assert distributed_container is value_container(v)
        return distributed_container
    return wrap_class(values)

def get_guard_manager_type(self, source: Source, example_value: Optional[Union[KeysView[Any], set[Any], frozenset[Any], dict[Any, Any]]]) -> GuardManagerType:
    guard_manager_enum = GuardManagerType.GUARD_MANAGER
    if <MASK>:
        if isinstance(example_value, dict_keys):
            guard_manager_enum = GuardManagerType.DICT_GUARD_MANAGER
        elif isinstance(example_value, (set, frozenset)):
            guard_manager_enum = GuardManagerType.GUARD_MANAGER
        else:
            assert isinstance(example_value, dict)
            guard_manager_enum = GuardManagerType.DICT_GUARD_MANAGER
    return guard_manager_enum

@may_distort_benchmarking_result
@time_and_count
def benchmark_gpu(self: Self, _callable: Callable[[], Any], is_vetted_benchmarking: bool=False, **kwargs: Any) -> float:
    """Benchmark the GPU callable, `_callable`, and return the runtime, in milliseconds.

        Arguments:
        - _callable: The GPU callable to benchmark.

        Keyword Arguments:
        - quantiles: Optionally, a tuple of floats denoting the requested quantiles.
        - return_mode: Optionally, the requested return mode. Currently, Triton's
        `do_bench` supports min, max, mean, and median return modes.
        - **kwargs: Additional kwargs passed to Triton's `do_bench`.

        Returns:
        - The runtime of `callable`, in milliseconds. If `kwargs["quantiles"]` is specified,
        this is the first requested quantile. Else, if `kwargs["return_mode"]` is specified,
        this is the requested return mode. Otherwise, this is the median.
        """
    if not is_vetted_benchmarking:
        may_ban_benchmarking()
    do_bench_params = inspect.signature(self.triton_do_bench).parameters
    for kwarg in list(kwargs.keys()):
        if kwarg not in do_bench_params:
            del kwargs[kwarg]
    if <MASK>:
        return self.triton_do_bench(_callable, **kwargs)[0]
    elif 'return_mode' in kwargs:
        return self.triton_do_bench(_callable, **kwargs)
    return self.triton_do_bench(_callable, **kwargs, return_mode='median')

