def mark_nodes_dislike_padding(g: Graph, user_visible_output_strides: dict[Node, tuple[int, ...]]) -> None:
    """
    Nodes like convolution/convolution_backward want its input to be dense.
    If we pad their inputs, we result in extra calls to copy kernels!  On the other hand, padding usually helps reduction.

    The pass finds nodes that dislike padding. These are nodes that can be reached
    from a convolution/convolution_backward in the backward direction without
    going thru a reduction.
    """
    if not config.comprehensive_padding:
        return
    extended_user_visible_nodes = extend_user_visible_output_strides(user_visible_output_strides)
    ops_dislike_padding = OrderedSet([aten.convolution, aten.convolution_backward, aten._scaled_mm])
    ops_like_padding = OrderedSet([aten.var_mean, aten.sum, aten.mean, aten.prod, aten.any, aten.amin, aten.amax, aten.min, aten.max, aten.argmin, aten.argmax, aten.scatter_reduce])

    def _get_overload_packet(node: torch.fx.Node) -> Optional[torch._ops.OpOverloadPacket]:
        return node.target._overloadpacket if node.op == 'call_function' and isinstance(node.target, torch._ops.OpOverload) and hasattr(node.target, '_overloadpacket') else None
    for cur in reversed(g.nodes):
        if isinstance(cur.target, torch._higher_order_ops.triton_kernel_wrap.TritonKernelWrapperMutation):
            cur.meta['dislike_padding'] = True
            continue
        if isinstance(cur.target, torch._ops.OpOverload) and get_layout_constraint_tag(cur.target) == torch._C.Tag.needs_exact_strides:
            cur.meta['dislike_padding'] = True
            continue
        op = _get_overload_packet(cur)
        if not op:
            continue
        if <MASK>:
            cur.meta['dislike_padding'] = True
        if cur.meta.get('dislike_padding', False):
            for prior in cur.all_input_nodes:
                prior_op = _get_overload_packet(prior)
                if not prior_op:
                    continue
                if prior_op not in ops_like_padding:
                    prior.meta['dislike_padding'] = True
        if not config.pad_outputs and cur in extended_user_visible_nodes:
            cur.meta['dislike_padding'] = True

def __lt__(self, other: object) -> bool:
    if not isinstance(other, ShardedTest):
        raise NotImplementedError
    if self.name != other.name:
        return self.name < other.name
    if self.shard != other.shard:
        return self.shard < other.shard
    if self.num_shards != other.num_shards:
        return self.num_shards < other.num_shards
    if <MASK>:
        return True
    if other.time is None:
        return False
    return self.time < other.time

def array(obj, dtype=None, *, copy=True, order='K', subok=False, ndmin=0, like=None):
    if subok is not False:
        raise NotImplementedError("'subok' parameter is not supported.")
    if like is not None:
        raise NotImplementedError("'like' parameter is not supported.")
    if order != 'K':
        raise NotImplementedError
    if isinstance(obj, ndarray) and copy is False and (dtype is None) and (ndmin <= obj.ndim):
        return obj
    if isinstance(obj, (list, tuple)):
        if obj and all((isinstance(x, torch.Tensor) for x in obj)):
            obj = torch.stack(obj)
        else:
            obj = _tolist(obj)
    if <MASK>:
        obj = obj.tensor
    torch_dtype = None
    if dtype is not None:
        torch_dtype = _dtypes.dtype(dtype).torch_dtype
    tensor = _util._coerce_to_tensor(obj, torch_dtype, copy, ndmin)
    return ndarray(tensor)

def run_and_get_constant_graph(gm: torch.fx.GraphModule, skip_constructors: bool=True, lifted_constant_names: Optional[list[str]]=None, skip_folding_node_fn: Optional[Callable[[torch.fx.Node], bool]]=None) -> torch.fx.GraphModule:
    """
    Construct a GraphModule which corresponds to the part which could be
    constant folded in provided gm.
    """
    constant_graph_tag(gm, skip_constructors, lifted_constant_names, skip_folding_node_fn)

    def untag(node: torch.fx.Node) -> bool:
        used_to_fold = False
        for u in node.users:
            if u.meta[META_TAG] == CONST_MODULE_TAG:
                used_to_fold = True
                break
        if not used_to_fold:
            node.meta[META_TAG] = MODULE_TAG
        return used_to_fold
    for node in gm.graph.nodes:
        if node.op == 'get_attr' or node.name in (lifted_constant_names or ()):
            untag(node)
    new_graph = torch.fx.Graph()
    node_remapping: dict[torch.fx.Node, torch.fx.Node] = {}
    output_nodes = []
    for node in gm.graph.nodes:
        if <MASK>:
            continue
        new_node = new_graph.node_copy(node, lambda x: node_remapping[x])
        node_remapping[node] = new_node
        for user in node.users:
            if user.meta[META_TAG] == MODULE_TAG:
                output_nodes.append(new_node)
                break
    new_graph.output(tuple(output_nodes))
    new_graph.lint()
    new_gm = torch.fx.GraphModule(gm, new_graph)
    return new_gm

def check_use_count(t, name='t1'):
    use_count = t._use_count()
    error_str = f'Expected use_count of {name} to be 1 or 2 with an AccumulateGrad node but got {use_count} make sure you are not holding references to the tensor in other places.'
    if use_count > 1:
        if use_count == 2 and t.is_leaf:
            accum_grad_node = torch.autograd.graph.get_gradient_edge(t).node
            if <MASK>:
                accum_grad_node.register_prehook(error_pre_hook)
            else:
                raise RuntimeError(error_str)
        else:
            raise RuntimeError(error_str)

@doesnt_support_saved_tensors_hooks
def _vjp_with_argnums(func: Callable, *primals, argnums: Optional[argnums_t]=None, has_aux: bool=False):
    with grad_increment_nesting() as level:
        with torch.enable_grad():
            primals = _wrap_all_tensors(primals, level)
            if argnums is None:
                diff_primals = _create_differentiable(primals, level)
            else:
                diff_primals = _slice_argnums(primals, argnums, as_tuple=False)
                tree_map_(partial(_create_differentiable, level=level), diff_primals)
            primals_out = func(*primals)
            if <MASK>:
                if not (isinstance(primals_out, tuple) and len(primals_out) == 2):
                    raise RuntimeError('vjp(f, *primals): output of function f should be a tuple: (output, aux) if has_aux is True')
                (primals_out, aux) = primals_out
                aux = _undo_create_differentiable(aux, level)
            (flat_primals_out, primals_out_spec) = tree_flatten(primals_out)
            assert_non_empty_tensor_output(flat_primals_out, 'vjp(f, *primals)')
            (flat_diff_primals, primals_spec) = tree_flatten(diff_primals)
            results = _undo_create_differentiable(primals_out, level)
            for primal_out in flat_primals_out:
                assert isinstance(primal_out, torch.Tensor)
                if primal_out.is_floating_point() or primal_out.is_complex():
                    continue
                raise RuntimeError(f'vjp(f, ...): All outputs of f must be floating-point or complex Tensors, got Tensor with dtype {primal_out.dtype}')

        def wrapper(cotangents, retain_graph=True, create_graph=None):
            if create_graph is None:
                create_graph = torch.is_grad_enabled()
            (flat_cotangents, cotangents_spec) = tree_flatten(cotangents)
            if primals_out_spec != cotangents_spec:
                raise RuntimeError(f'Expected pytree structure of cotangents to be the same as pytree structure of outputs to the function. cotangents: {treespec_pprint(cotangents_spec)}, primal output: {treespec_pprint(primals_out_spec)}')
            result = _autograd_grad(flat_primals_out, flat_diff_primals, flat_cotangents, retain_graph=retain_graph, create_graph=create_graph)
            return tree_unflatten(result, primals_spec)
    if has_aux:
        return (results, wrapper, aux)
    else:
        return (results, wrapper)

def find_state_dict_object(state_dict: STATE_DICT_TYPE, index: MetadataIndex) -> Any:
    if <MASK>:
        raise ValueError(f"Could not find FQN: '{index.fqn}'")
    obj = state_dict[index.fqn]
    if isinstance(obj, torch.Tensor):
        return find_tensor_shard(obj, index)
    elif index.offset is not None:
        raise ValueError(f"FQN: '{index.fqn}' is not a ShardedTensor, can't find by offset: '{index.offset}'")
    return obj

