def test_config(self, results: ResultType, config: ConfigType) -> Status:
    """
        Tests a config by calling the function produced by the factory function.
        """
    original_handler = signal.signal(signal.SIGALRM, self.timeout_handler)
    signal.alarm(self.test_timeout)
    print(f'Testing config {config}')
    config_tuple = tuple(config.keys())
    if (ret := results.lookup(config_tuple)):
        signal.signal(signal.SIGALRM, original_handler)
        return ret

    def print_config() -> None:
        for (field, value) in config.items():
            print(f'{field} = {value}')

    def get_error_info(exc: Exception) -> dict[str, Any]:
        return {'exception': str(exc), 'traceback': traceback.format_exc(), 'config': config.copy()}

    def handle_return(message: str, return_status: Status, print_traceback: bool, exc: Optional[Exception]) -> Status:
        signal.signal(signal.SIGALRM, original_handler)
        print(f'{message} with config combination:')
        print_config()
        if exc:
            self.detailed_results[config_tuple] = get_error_info(exc)
        if <MASK>:
            traceback.print_exc()
        results.set(config_tuple, return_status)
        return return_status
    torch._dynamo.reset()
    self._reset_configs()
    for (name, value) in config.items():
        self._set_config(name, value)
    test_model_fn = self.test_model_fn_factory()
    try:
        test_model_fn()
    except Exception as exc:
        return handle_return('Eager exception', Status.FAILED_RUN_EAGER_EXCEPTION, True, exc)
    try:
        test_model_fn2 = self.test_model_fn_factory()
        comp = torch.compile(test_model_fn2, backend='inductor')
    except Exception as exc:
        return handle_return('Exception compiling', Status.FAILED_COMPILE, True, exc)
    try:
        compile_result = comp()
    except Exception as exc:
        return handle_return('Exception running compiled', Status.FAILED_RUN_COMPILE_EXCEPTION, True, exc)
    if not compile_result:
        return handle_return('Function returned False', Status.FAILED_RUN_RETURN, False, None)
    else:
        return handle_return('Function succeeded', Status.PASSED, False, None)

def build_graph(parameters):
    multi_node = parameters['multi_node']
    if <MASK>:
        return build_graph_multi_node(parameters)
    return build_graph_one_node(parameters)

def res_arg(self, ns, types_ns, f_name, name, type_anno, f_is_local):
    if <MASK>:
        f_name_str = str(f_name)
        if f_name_str in self._for_loop_target_types:
            assert self._for_loop_target_types[f_name_str] & {TFRTypes.ATTR}
            return {TFRTypes.INDEX}
        else:
            return None
    func = ns[f_name]
    (op_def, derived_attrs) = self._op_defs.lookup(f_name, func)
    if op_def is None:
        return None
    pos = tf_inspect.getfullargspec(func).args.index(str(name))
    if pos < len(op_def.input_arg):
        arg_def = op_def.input_arg[pos]
        return {_get_type_from_proto(arg_def)}
    elif pos < len(op_def.input_arg) + len(op_def.attr) - len(derived_attrs):
        non_derived_attr_pos = pos - len(op_def.input_arg)
        for attr_def in op_def.attr:
            if attr_def.name in derived_attrs:
                continue
            if non_derived_attr_pos == 0:
                return {_get_type_from_proto(None, attr_def)}
            non_derived_attr_pos -= 1
    raise ValueError('Argument is not defined in OpDef: ' + str(name))

def feature_get_til(self, names, keyisfalse):
    """
        same as `feature_implies_c()` but stop collecting implied
        features when feature's option that provided through
        parameter 'keyisfalse' is False, also sorting the returned
        features.
        """

    def til(tnames):
        tnames = self.feature_implies_c(tnames)
        tnames = self.feature_sorted(tnames, reverse=True)
        for (i, n) in enumerate(tnames):
            if <MASK>:
                tnames = tnames[:i + 1]
                break
        return tnames
    if isinstance(names, str) or len(names) <= 1:
        names = til(names)
        names.reverse()
        return names
    names = self.feature_ahead(names)
    names = {t for n in names for t in til(n)}
    return self.feature_sorted(names)

@register_vcs_handler('git', 'keywords')
def git_versions_from_keywords(keywords, tag_prefix, verbose):
    """Get version information from git keywords."""
    if 'refnames' not in keywords:
        raise NotThisMethod('Short version file found')
    date = keywords.get('date')
    if date is not None:
        date = date.splitlines()[-1]
        date = date.strip().replace(' ', 'T', 1).replace(' ', '', 1)
    refnames = keywords['refnames'].strip()
    if refnames.startswith('$Format'):
        if <MASK>:
            print('keywords are unexpanded, not using')
        raise NotThisMethod('unexpanded keywords, not a git-archive tarball')
    refs = {r.strip() for r in refnames.strip('()').split(',')}
    TAG = 'tag: '
    tags = {r[len(TAG):] for r in refs if r.startswith(TAG)}
    if not tags:
        tags = {r for r in refs if re.search('\\d', r)}
        if verbose:
            print(f"discarding '{','.join(refs - tags)}', no digits")
    if verbose:
        print(f"likely tags: {','.join(sorted(tags))}")
    for ref in sorted(tags):
        if ref.startswith(tag_prefix):
            r = ref[len(tag_prefix):]
            if not re.match('\\d', r):
                continue
            if verbose:
                print(f'picking {r}')
            return {'version': r, 'full-revisionid': keywords['full'].strip(), 'dirty': False, 'error': None, 'date': date}
    if verbose:
        print('no suitable tags, using unknown + full revision id')
    return {'version': '0+unknown', 'full-revisionid': keywords['full'].strip(), 'dirty': False, 'error': 'no suitable tags', 'date': None}

def contains(self, other):
    """Check if self contains other.
        """
    found = []

    def visit(expr, found=found):
        if found:
            return expr
        elif <MASK>:
            found.append(1)
            return expr
    self.traverse(visit)
    return len(found) != 0

def _from_proto(self, pb):
    if pb.WhichOneof('optional_deterministic') is not None:
        self.deterministic = pb.deterministic
    self.autotune._from_proto(pb.autotune_options)
    self.experimental_distribute._from_proto(pb.distribute_options)
    if pb.WhichOneof('optional_external_state_policy') is not None:
        self.experimental_external_state_policy = ExternalStatePolicy._from_proto(pb.external_state_policy)
    self.experimental_optimization._from_proto(pb.optimization_options)
    if pb.WhichOneof('optional_slack') is not None:
        self.experimental_slack = pb.slack
    if pb.WhichOneof('optional_symbolic_checkpoint') is not None:
        self.experimental_symbolic_checkpoint = pb.symbolic_checkpoint
    if <MASK>:
        self.experimental_warm_start = pb.warm_start
    if pb.WhichOneof('optional_dataset_name') is not None:
        self.dataset_name = pb.dataset_name
    if pb.framework_type:
        self.framework_type = []
        for framework_type in pb.framework_type:
            self.framework_type.append(framework_type)
    self.experimental_service._from_proto(pb.service_options)
    self.threading._from_proto(pb.threading_options)

def _adjust_dates_anchored(first: Timestamp, last: Timestamp, freq: Tick, closed: Literal['right', 'left']='right', origin: TimeGrouperOrigin='start_day', offset: Timedelta | None=None, unit: TimeUnit='ns') -> tuple[Timestamp, Timestamp]:
    first = first.as_unit(unit)
    last = last.as_unit(unit)
    if offset is not None:
        offset = offset.as_unit(unit)
    freq_value = Timedelta(freq).as_unit(unit)._value
    origin_timestamp = 0
    if origin == 'start_day':
        origin_timestamp = first.normalize()._value
    elif origin == 'start':
        origin_timestamp = first._value
    elif isinstance(origin, Timestamp):
        origin_timestamp = origin.as_unit(unit)._value
    elif origin in ['end', 'end_day']:
        origin_last = last if origin == 'end' else last.ceil('D')
        sub_freq_times = (origin_last._value - first._value) // freq_value
        if closed == 'left':
            sub_freq_times += 1
        first = origin_last - sub_freq_times * freq
        origin_timestamp = first._value
    origin_timestamp += offset._value if offset else 0
    first_tzinfo = first.tzinfo
    last_tzinfo = last.tzinfo
    if first_tzinfo is not None:
        first = first.tz_convert('UTC')
    if <MASK>:
        last = last.tz_convert('UTC')
    foffset = (first._value - origin_timestamp) % freq_value
    loffset = (last._value - origin_timestamp) % freq_value
    if closed == 'right':
        if foffset > 0:
            fresult_int = first._value - foffset
        else:
            fresult_int = first._value - freq_value
        if loffset > 0:
            lresult_int = last._value + (freq_value - loffset)
        else:
            lresult_int = last._value
    else:
        if foffset > 0:
            fresult_int = first._value - foffset
        else:
            fresult_int = first._value
        if loffset > 0:
            lresult_int = last._value + (freq_value - loffset)
        else:
            lresult_int = last._value + freq_value
    fresult = Timestamp(fresult_int, unit=unit)
    lresult = Timestamp(lresult_int, unit=unit)
    if first_tzinfo is not None:
        fresult = fresult.tz_localize('UTC').tz_convert(first_tzinfo)
    if last_tzinfo is not None:
        lresult = lresult.tz_localize('UTC').tz_convert(last_tzinfo)
    return (fresult, lresult)

def _validate_frozen_params(root_module: nn.Module, modules_to_wrap: set[nn.Module], ignored_params: set[nn.Parameter], use_orig_params: bool):
    """
    This checks that, given ``modules_to_wrap``, each module would manage
    parameters that are uniformly frozen or non-frozen. This uniformity
    requirement is strict for ``use_orig_params=False`` (hard error) and highly
    recommended for ``use_orig_params=True`` (user warning).
    """
    post_order_named_modules = _get_post_order_named_modules(root_module)
    visited_modules: set[nn.Module] = set()
    for (module_name, module) in post_order_named_modules:
        if module in modules_to_wrap:
            param_to_fqn = _get_managed_param_to_fqn(module, ignored_params, visited_modules, module_name)
            frozen_param_fqns: list[str] = []
            frozen_param_numel = 0
            nonfrozen_param_fqns: list[str] = []
            nonfrozen_param_numel = 0
            for (param, fqn) in param_to_fqn.items():
                if param.requires_grad:
                    nonfrozen_param_fqns.append(fqn)
                    nonfrozen_param_numel += param.numel()
                else:
                    frozen_param_fqns.append(fqn)
                    frozen_param_numel += param.numel()
            if len(frozen_param_fqns) > 0 and len(nonfrozen_param_fqns) > 0:
                msg = f'{module_name} has both parameters with requires_grad=True and False.'
                if <MASK>:
                    total_param_numel = frozen_param_numel + nonfrozen_param_numel
                    msg += f' We do not recommend wrapping such modules since the gradient memory usage will be higher than expected ({total_param_numel} numel instead of {nonfrozen_param_numel} numel before sharding via reduce-scatter). '
                else:
                    msg += ' FSDP does not support wrapping such modules when use_orig_params=False. '
                msg += 'If possible, wrap the frozen parameters with FSDP separately.\n'
                msg += f'The following parameters have requires_grad=True:\n{nonfrozen_param_fqns}\nThe following parameters have requires_grad=False:\n{frozen_param_fqns}'
                if use_orig_params:
                    warnings.warn(msg)
                else:
                    raise ValueError(msg)

def _stack_pytree(pytrees):
    flat_out = []
    out_spec = None
    for pt in pytrees:
        (flat_pt, out_spec) = pytree.tree_flatten(pt)
        flat_out.append(flat_pt)
    assert out_spec is not None
    b = zip(*flat_out)
    stacked_out = []
    for leaves in b:
        if <MASK>:
            stacked_out.append(torch.stack(leaves))
        elif all((leaf is None for leaf in leaves)):
            stacked_out.append(None)
        else:
            raise RuntimeError(f'Cannot stack {leaves}.')
    return pytree.tree_unflatten(stacked_out, out_spec)

@final
def _check_indexing_method(self, method: str_t | None, limit: int | None=None, tolerance=None) -> None:
    """
        Raise if we have a get_indexer `method` that is not supported or valid.
        """
    if method not in [None, 'bfill', 'backfill', 'pad', 'ffill', 'nearest']:
        raise ValueError('Invalid fill method')
    if self._is_multi:
        if method == 'nearest':
            raise NotImplementedError("method='nearest' not implemented yet for MultiIndex; see GitHub issue 9365")
        if <MASK>:
            if tolerance is not None:
                raise NotImplementedError('tolerance not implemented yet for MultiIndex')
    if isinstance(self.dtype, (IntervalDtype, CategoricalDtype)):
        if method is not None:
            raise NotImplementedError(f'method {method} not yet implemented for {type(self).__name__}')
    if method is None:
        if tolerance is not None:
            raise ValueError('tolerance argument only valid if doing pad, backfill or nearest reindexing')
        if limit is not None:
            raise ValueError('limit argument only valid if doing pad, backfill or nearest reindexing')

def set_item(target, i, x):
    """The slice write operator (i.e. __setitem__).

  Note: it is unspecified whether target will be mutated or not. In general,
  if target is mutable (like Python lists), it will be mutated.

  Args:
    target: An entity that supports setitem semantics.
    i: Index to modify.
    x: The new element value.

  Returns:
    Same as target, after the update was performed.

  Raises:
    ValueError: if target is not of a supported type.
  """
    if isinstance(target, tensor_array_ops.TensorArray):
        return _tf_tensorarray_set_item(target, i, x)
    elif tensor_util.is_tf_type(target):
        if <MASK>:
            return _tf_tensor_list_set_item(target, i, x)
        else:
            return _tf_tensor_set_item(target, i, x)
    else:
        return _py_set_item(target, i, x)

def baselines(models, model_iter_fn, example_inputs, args):
    """
    Common measurement code across all baseline experiments.
    """
    models = list(models)
    for (idx, (name, model)) in enumerate(models):
        if idx == 0:
            result0 = model_iter_fn(model, example_inputs)
        elif model is not None:
            try:
                result = model_iter_fn(model, example_inputs)
                if same(result0, result):
                    continue
                print(name, 'is INCORRECT')
            except Exception:
                log.exception('error checking %s', name)
            models[idx] = (name, None)
    timings = np.zeros((args.repeat, len(models)), np.float64)
    timings.fill(10000000000.0)
    for rep in range(args.repeat):
        for (idx, (name, model)) in enumerate(models):
            if model is not None:
                try:
                    timings[rep, idx] = timed(model, model_iter_fn, example_inputs)
                except Exception:
                    pass
    pvalue = [ttest_ind(timings[:, 0], timings[:, i]).pvalue for i in range(1, timings.shape[1])]
    median = np.median(timings, axis=0)
    speedup = median[0] / median[1:]
    for (idx, (name, model)) in enumerate(models[1:]):
        if <MASK>:
            speedup[idx] = 0.0
    result = ' '.join([format_speedup(s, p, m is not None) for (s, p, m) in zip(speedup, pvalue, [m for (n, m) in models[1:]])])
    write_outputs(output_filename, ('dev', 'name', 'batch_size') + tuple((n for (n, m) in models[1:])), [current_device, current_name, current_batch_size] + [f'{x:.4f}' for x in speedup])
    return result

