                print(f"Path does not exist: {cwd}/{module['repo_name']}")
                try:
                    subprocess.check_output(f"git clone --depth 1 {module['repo']}", stderr=subprocess.STDOUT, shell=True)
                except subprocess.CalledProcessError as exc:
                    raise RuntimeError(f"Cloning {module['repo']} FAIL: {exc.returncode} Output: {exc.output}") from exc
            try:
                smoke_test_command = f"python3 {module['smoke_test']}"
                if target_os == 'windows':
                    smoke_test_command = f"python {module['smoke_test']}"
                output = subprocess.check_output(smoke_test_command, stderr=subprocess.STDOUT, shell=True, universal_newlines=True)
            except subprocess.CalledProcessError as exc:
                raise RuntimeError(f"Module {module['name']} FAIL: {exc.returncode} Output: {exc.output}") from exc
            else:
                print(f'Output: \n{output}\n')

def __init__(self, arg):
    if isinstance(arg, torch.dtype):
        sctype = _torch_dtypes[arg]
    elif isinstance(arg, torch.Tensor):
        sctype = _torch_dtypes[arg.dtype]
    elif issubclass_(arg, generic):
        sctype = arg
    elif <MASK>:
        sctype = arg._scalar_type
    elif hasattr(arg, 'dtype'):
        sctype = arg.dtype._scalar_type
    else:
        sctype = sctype_from_string(arg)
    self._scalar_type = sctype

def _warn_for_unused_params(self):
    if self.tokenizer is not None and self.token_pattern is not None:
        warnings.warn("The parameter 'token_pattern' will not be used since 'tokenizer' is not None'")
    if self.preprocessor is not None and callable(self.analyzer):
        warnings.warn("The parameter 'preprocessor' will not be used since 'analyzer' is callable'")
    if self.ngram_range != (1, 1) and self.ngram_range is not None and callable(self.analyzer):
        warnings.warn("The parameter 'ngram_range' will not be used since 'analyzer' is callable'")
    if self.analyzer != 'word' or callable(self.analyzer):
        if self.stop_words is not None:
            warnings.warn("The parameter 'stop_words' will not be used since 'analyzer' != 'word'")
        if <MASK>:
            warnings.warn("The parameter 'token_pattern' will not be used since 'analyzer' != 'word'")
        if self.tokenizer is not None:
            warnings.warn("The parameter 'tokenizer' will not be used since 'analyzer' != 'word'")

def module_fn(module, prefix, tree_level, fqn_to_param_info):
    fsdp_state = _get_module_fsdp_state_if_fully_sharded_module(module)
    if fsdp_state is None:
        return
    _lazy_init(fsdp_state, module)
    handle = _module_handle(fsdp_state, module)
    if <MASK>:
        return
    flat_param = handle.flat_param
    fsdp_param_info = FSDPParamInfo(fsdp_state, handle, {}, [])
    for (idx, local_fqn) in enumerate(flat_param._fqns):
        fqn = clean_tensor_name(prefix + local_fqn)
        if fqn in fqn_to_param_info:
            if fqn_to_param_info[fqn].handle.flat_param is not flat_param:
                raise AssertionError(f'Expected fqn_to_param_info[fqn].handle.flat_param is flat_param for {fqn}')
        fqn_to_param_info[fqn] = fsdp_param_info
        fsdp_param_info.param_indices[fqn] = idx
        if flat_param._params is not None:
            fsdp_param_info.param_requires_grad.append(flat_param._params[idx].requires_grad)

def _process_python_sequences(signature: _schemas.OpSignature, named_inputs: dict[str, AllowedArgType], type_binding: Mapping[_schemas.TypeConstraintParam, ir.TypeProtocol], constant_farm: dict[tuple[bool | int | float | str | ir.TensorProtocol | tuple[int] | tuple[float], ir.DataType], ir.Value], opset: onnxscript.values.Opset):
    """Handle three types of sequences.

    1. Variadic inputs
    2. Sequence input of ir.Value,
    3. Sequence of Python constants that contains ir.Value
    """
    for (name, arg) in named_inputs.items():
        param = signature.params_map[name]
        assert isinstance(param, _schemas.Parameter), f'Expected Parameter, got {type(param)}'
        if not isinstance(arg, (tuple, list)):
            continue
        if len(arg) == 0:
            continue
        if _allowed_types_are_sequence_types(param.type_constraint.allowed_types):
            named_inputs[name] = opset.SequenceConstruct(*arg)
            continue
        if param.variadic:
            if <MASK>:
                continue
            dtype = _determine_input_dtype(param, arg, type_binding)
            new_args = []
            for val in arg:
                if isinstance(val, ir.Value):
                    new_args.append(val)
                else:
                    constant_tensor = ir.tensor(value=val, dtype=dtype)
                    constant_value = opset.Constant(value=constant_tensor)
                    new_args.append(constant_value)
            named_inputs[name] = new_args
            continue
        else:
            if all((isinstance(val, ir.Value) for val in arg)):
                expanded_args = [_reshape_to_1d_tensor(opset, val) for val in arg]
                named_inputs[name] = opset.Concat(*expanded_args, axis=0)
                continue
            dtype = _determine_input_dtype(param, arg, type_binding)
            new_args = []
            for val in arg:
                if isinstance(val, ir.Value):
                    new_args.append(_reshape_to_1d_tensor(opset, val))
                elif val is None:
                    continue
                elif isinstance(val, (ir.Tensor, ir.TensorProtocol)):
                    new_args.append(_reshape_to_1d_tensor(opset, opset.Constant(value=val)))
                else:
                    assert isinstance(val, (bool, int, float)), f'Expected int or float, got {type(val)}'
                    new_args.append(_get_or_create_constant(constant_farm, [val], dtype, opset))
            named_inputs[name] = opset.Concat(*new_args, axis=0)
            continue
    return named_inputs

def sdpa_constraint(fx_node, *args, **kwargs):

    def apply_constraint(idx, arg, fx_arg):
        if not isinstance(arg, ir.IRNode):
            return arg
        meta_val = fx_arg.meta['val']
        meta_stride_expr = [s.node.expr if isinstance(s, torch.SymInt) else s for s in meta_val.stride()]
        shape_env = V.graph.sizevars.shape_env
        stride_order = ir.get_stride_order(meta_val.stride(), shape_env)
        if stride_order and stride_order[-1] != 0:
            stride_order = list(reversed(range(len(arg.get_size()))))
        if fx_node.target == aten._scaled_dot_product_efficient_attention_backward.default and idx in (0, 5):
            assert len(stride_order) == 4
            stride_order = (3, 1, 2, 0)
        if not meta_val.is_cuda:
            return ir.ExternKernel.require_stride_order(arg, stride_order)
        ALIGNMENT = 8
        effn_attn_fwd_bias = fx_node.target == torch.ops.aten._scaled_dot_product_efficient_attention.default and idx == 3
        assert isinstance(arg, TensorBox)
        if len(arg.get_size()) not in (3, 4):
            return arg
        is_aligned_tensor = ir.is_aligned_realized_tensor(arg, ALIGNMENT)
        if is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if isinstance(arg, IRNode) and arg.maybe_get_stride() is not None and is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if effn_attn_fwd_bias:
            out_size = list(arg.get_size())
            expanded_dims = []
            maybe_stride = arg.maybe_get_stride()
            for i in range(len(arg.get_size()) - 1):
                if <MASK>:
                    expanded_dims.append(i)
            out_strides = [-1] * len(out_size)
            out_strides[-1] = 1
            stride = 1
            for i in range(len(out_size) - 2, -1, -1):
                if out_strides[i + 1] != 0:
                    stride = stride * out_size[i + 1]
                if i in expanded_dims:
                    if V.graph.sizevars.statically_known_equals(out_strides[i + 1] % ALIGNMENT, 0):
                        out_strides[i] = 0
                        continue
                if not V.graph.sizevars.statically_known_equals(stride % ALIGNMENT, 0):
                    stride = ceildiv(stride, ALIGNMENT) * ALIGNMENT
                out_strides[i] = stride
            return ir.ExternKernel.require_exact_strides(arg, out_strides)
        if is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        if isinstance(arg, IRNode) and arg.maybe_get_stride() is not None and is_aligned_tensor:
            return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)

        def is_aligned(x):
            return V.graph.sizevars.guard_or_false(sympy.Eq(Mod(x.get_size()[-1], ALIGNMENT), 0))
        if isinstance(arg.data, ir.BaseView):
            if not is_aligned(arg):
                if is_aligned(arg.unwrap_view()):
                    return ir.try_match_insignificant_strides(ir.ExternKernel.realize_input(arg), meta_stride_expr)
        return ir.ExternKernel.require_stride_order(arg, stride_order)
    args = tuple((apply_constraint(idx, arg, fx_arg) for (idx, (arg, fx_arg)) in enumerate(zip(args, fx_node.args))))
    kwargs = {k: apply_constraint(-1, v, fx_node.kwargs[k]) for (k, v) in kwargs.items()}
    return (args, kwargs)

@final
def copy(self, deep: bool=True) -> Self:
    """copy constructor"""
    values = self.values
    refs: BlockValuesRefs | None
    if <MASK>:
        values = values.copy()
        refs = None
    else:
        refs = self.refs
    return type(self)(values, placement=self._mgr_locs, ndim=self.ndim, refs=refs)

def emit_node(node: Node):
    maybe_type_annotation = '' if node.type is None else f' : {type_repr(node.type)}'
    maybe_comment = ''
    if verbose:
        from torch.fx.experimental.proxy_tensor import py_sym_types
        from torch.fx.passes.shape_prop import TensorMetadata
        meta_val = node.meta.get('val', node.meta.get('tensor_meta', node.meta.get('example_value', None)))

        def _tensor_annotation(t: torch.Tensor) -> str:
            stride = stringify_shape(t.stride()) if include_stride else ''
            device = f'{t.device}' if include_device else ''
            return f'{red(dtype_abbrs[t.dtype])}{blue(stringify_shape(t.shape))}{dim_blue(stride)}{dim_green(device)}'
        if isinstance(meta_val, torch.Tensor) and meta_val.layout not in (torch.sparse_csc, torch.sparse_csr):
            is_plain = type(meta_val) is torch.Tensor or isinstance(meta_val, torch._subclasses.FakeTensor)
            core = _tensor_annotation(meta_val)
            if is_plain:
                maybe_type_annotation = f': "{core}"'
            else:
                cls = meta_val.__class__.__name__
                maybe_type_annotation = f': "{cls}({core})"'
        elif isinstance(meta_val, py_sym_types):
            val_str = CodeGen._sym_repr(meta_val)
            maybe_type_annotation = f': "Sym({val_str})"'
        elif isinstance(meta_val, TensorMetadata):
            maybe_type_annotation = f': "{dtype_abbrs[meta_val.dtype]}{stringify_shape(meta_val.shape)}"'
    desc = None
    if expanded_def:
        desc = node.meta.get('desc', None)
        if desc is not None and node.op == 'placeholder':
            maybe_comment += f'  # {desc}'
    if node.op == 'placeholder':
        assert isinstance(node.target, str)
        maybe_default_arg = '' if not node.args else f' = {_get_repr(node.args[0])}'
        free_vars.append(f'{node.target}{maybe_type_annotation}{maybe_default_arg}{maybe_comment}')
        raw_name = node.target.replace('*', '')
        if <MASK>:
            body.append(f'{repr(node)} = {raw_name}\n')
        return
    elif node.op == 'call_method':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.target)}({_format_args(node.args[1:], node.kwargs)})')
        return
    elif node.op == 'call_function':
        assert callable(node.target)
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in magic_methods:
            assert isinstance(node.args, tuple)
            body.append(f'{repr(node)}{maybe_type_annotation} = {magic_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))}')
            return
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in inplace_methods:
            body.append(f'{inplace_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))};  {repr(node)}{maybe_type_annotation} = {_get_repr(node.args[0])}')
            return
        qualified_name = _get_qualified_name(node.target)
        global_name = add_global(qualified_name, node.target)
        if global_name == 'getattr' and isinstance(node.args, tuple) and isinstance(node.args[1], str) and node.args[1].isidentifier() and (len(node.args) == 2):
            body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.args[1])}')
            return
        body.append(f'{repr(node)}{maybe_type_annotation} = {global_name}({_format_args(node.args, node.kwargs)})')
        if node.meta.get('is_wrapped', False):
            wrapped_fns.setdefault(global_name)
        return
    elif node.op == 'call_module':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}({_format_args(node.args, node.kwargs)})')
        return
    elif node.op == 'get_attr':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}')
        return
    elif node.op == 'output':
        if node.type is not None:
            maybe_return_annotation[0] = f' -> {type_repr(node.type)}'
        body.append(self._call_method_with_signature_check(self.generate_output, node.args[0], descs=desc if expanded_def else None))
        return
    raise NotImplementedError(f'node: {node.op} {node.target}')

def linkcode_resolve(domain, info):
    """
    Determine the URL corresponding to Python object
    """
    if domain != 'py':
        return None
    modname = info['module']
    fullname = info['fullname']
    submod = sys.modules.get(modname)
    if submod is None:
        return None
    obj = submod
    for part in fullname.split('.'):
        try:
            obj = getattr(obj, part)
        except Exception:
            return None
    try:
        unwrap = inspect.unwrap
    except AttributeError:
        pass
    else:
        obj = unwrap(obj)
    fn = None
    lineno = None
    if isinstance(obj, type):
        if obj.__module__ == 'numpy':
            fn = _get_c_source_file(obj)
        if hasattr(obj, '_module_source'):
            (obj.__module__, obj._module_source) = (obj._module_source, obj.__module__)
    if <MASK>:
        try:
            fn = inspect.getsourcefile(obj)
        except Exception:
            fn = None
        if not fn:
            return None
        module = inspect.getmodule(obj)
        if module is not None and (not module.__name__.startswith('numpy')):
            return None
        try:
            (source, lineno) = inspect.getsourcelines(obj)
        except Exception:
            lineno = None
        fn = relpath(fn, start=dirname(numpy.__file__))
    if lineno:
        linespec = '#L%d-L%d' % (lineno, lineno + len(source) - 1)
    else:
        linespec = ''
    if isinstance(obj, type) and hasattr(obj, '_module_source'):
        (obj.__module__, obj._module_source) = (obj._module_source, obj.__module__)
    if 'dev' in numpy.__version__:
        return f'https://github.com/numpy/numpy/blob/main/numpy/{fn}{linespec}'
    else:
        return 'https://github.com/numpy/numpy/blob/v%s/numpy/%s%s' % (numpy.__version__, fn, linespec)

def assert_equal_graph_def(actual: graph_pb2.GraphDef, expected: graph_pb2.GraphDef, checkpoint_v2: bool=False, hash_table_shared_name: bool=False) -> None:
    if not isinstance(actual, graph_pb2.GraphDef):
        raise TypeError('Expected tf.GraphDef for actual, got %s' % type(actual).__name__)
    if not isinstance(expected, graph_pb2.GraphDef):
        raise TypeError('Expected tf.GraphDef for expected, got %s' % type(expected).__name__)
    if checkpoint_v2:
        _strip_checkpoint_v2_randomized(actual)
        _strip_checkpoint_v2_randomized(expected)
    if <MASK>:
        _strip_hash_table_shared_name(actual)
        _strip_hash_table_shared_name(expected)
    diff = pywrap_tf_session.EqualGraphDefWrapper(actual.SerializeToString(), expected.SerializeToString())
    if diff:
        raise AssertionError(compat.as_str(diff))

def testAllGatherRaiseDiffShapeAtNonAxis(self, strategy, pure_eager):
    """Different at non-`axis`-th dimension : [2, 1], [1, 1], all_gather(...axis=1...) -> raise error."""
    if _is_tpu_strategy(strategy):
        self.skipTest('TODO(b/169108777): raise a clear error message in xla.')
    if isinstance(strategy, CollectiveAllReduceStrategy) and _get_num_replicas_per_client(strategy) > 1:
        self.skipTest('b/167331966')
    if strategy.num_replicas_in_sync <= 1:
        self.skipTest('Test for more than 1 replica only.')

    def value_fn(ctx):
        return constant_op.constant(1, shape=(1, ctx.replica_id_in_sync_group + 1))
    per_replica_value = strategy.experimental_distribute_values_from_function(value_fn)

    def run(value):
        value_identity = array_ops.identity(value)
        ctx = distribute_lib.get_replica_context()
        return ctx.all_gather(value_identity, axis=0)
    if not pure_eager:
        run = def_function.function(run)
    if <MASK>:
        with self.assertRaisesRegex(errors.InvalidArgumentError, 'Shape mismatch'):
            strategy.run(run, args=(per_replica_value,))
    elif isinstance(strategy, (mirrored_strategy.MirroredStrategy, central_storage_strategy.CentralStorageStrategy)):
        with self.assertRaisesRegex((errors.InvalidArgumentError, ValueError), 'Dimension \\d in both shapes must be equal'):
            strategy.run(run, args=(per_replica_value,))

def _is_qat_saved_model(saved_model_path: str):
    """Checks if the SavedModel is QAT-enabled by looking for 'FakeQuant' ops."""
    saved_model_proto = saved_model_loader.parse_saved_model(saved_model_path)
    for meta_graph in saved_model_proto.meta_graphs:
        if <MASK>:
            return True
        for function in meta_graph.graph_def.library.function:
            if any((node.op.startswith('FakeQuant') for node in function.node_def)):
                return True
    return False

def serialize_guards(self, builder: GuardBuilder, sorted_guards: list[Guard], output_graph: OutputGraphCommon) -> bytes:
    for guard in sorted_guards:
        guard_type = guard.create_fn_name()
        derived_guard_types = tuple(guard.guard_types) if guard.guard_types else ()
        if guard_type in ('TYPE_MATCH', 'BUILTIN_MATCH'):
            if guard._unserializable:
                obj = builder.get(guard.name)
                raise_local_type_error(obj)
        elif guard_type in CheckFunctionManager.UNSUPPORTED_SERIALIZATION_GUARD_TYPES:
            raise torch._dynamo.exc.PackageError(f'{guard_type} guard cannot be serialized.')
        elif (failed := next((i for i in derived_guard_types if i in CheckFunctionManager.UNSUPPORTED_SERIALIZATION_GUARD_TYPES), None)):
            raise torch._dynamo.exc.PackageError(f'{failed} guard cannot be serialized.')
    builtins_dict_name = output_graph.name_of_builtins_dict_key_in_fglobals or ''
    used_global_vars = set()
    used_local_vars = set()

    def prune_variable(source: Source) -> None:
        if (name := get_global_source_name(source)):
            assert isinstance(name, str)
            if name != builtins_dict_name:
                used_global_vars.add(name)
        elif (name := get_local_source_name(source)):
            assert isinstance(name, str)
            used_local_vars.add(name)
    output_graph_guards_state = output_graph.dump_guards_state()
    for guard in sorted_guards:
        if isinstance(guard.originating_source, ShapeEnvSource):
            assert self.shape_code_parts
            for source in self.shape_code_parts.shape_env_sources:
                prune_variable(source)
        else:
            prune_variable(guard.originating_source)
    for source in output_graph.guard_on_key_order:
        prune_variable(source)

    def normalize_create_fn(x: Callable[..., None]) -> Callable[..., None]:
        if <MASK>:

            def _ref(x: Any) -> Any:
                if isinstance(x, (TensorWeakRef, weakref.ref)):
                    return x()
                return x
            new_args = tuple((_ref(a) for a in x.args))
            new_keywords = {k: _ref(v) for (k, v) in x.keywords.items()}
            return functools.partial(x.func, *new_args, **new_keywords)
        return x
    global_scope_state = {k: v for (k, v) in output_graph_guards_state.global_scope.items() if k in used_global_vars or k in self.additional_used_global_vars}
    global_scope_state[builtins_dict_name] = {k: v for (k, v) in output_graph_guards_state.global_scope[builtins_dict_name].items() if k in self.used_builtin_vars}
    output_graph_guards_state = dataclasses.replace(output_graph_guards_state, local_scope={k: v for (k, v) in output_graph_guards_state.local_scope.items() if k in used_local_vars or k in self.additional_used_local_vars}, global_scope=global_scope_state, _guards=torch._guards.GuardsSet({dataclasses.replace(guard, obj_weakref=None, guarded_class_weakref=None, create_fn=normalize_create_fn(guard.create_fn)) for guard in sorted_guards}), input_source_to_sizes_strides=pytree.tree_map(convert_int_to_concrete_values, output_graph_guards_state.input_source_to_sizes_strides), skip_guards_check=True)
    guards_state = GuardsState(output_graph=output_graph_guards_state, shape_code_parts=self.shape_code_parts, source_get_cache=builder.source_get_cache)
    return pickle_guards_state(guards_state, builder.guard_tree_values)

def __new__(cls, data=None, mask=nomask, dtype=None, copy=False, subok=True, ndmin=0, fill_value=None, keep_mask=True, hard_mask=None, shrink=True, order=None):
    """
        Create a new masked array from scratch.

        Notes
        -----
        A masked array can also be created by taking a .view(MaskedArray).

        """
    copy = None if not copy else True
    _data = np.array(data, dtype=dtype, copy=copy, order=order, subok=True, ndmin=ndmin)
    _baseclass = getattr(data, '_baseclass', type(_data))
    if isinstance(data, MaskedArray) and data.shape != _data.shape:
        copy = True
    if isinstance(data, cls) and subok and (not isinstance(data, MaskedConstant)):
        _data = ndarray.view(_data, type(data))
    else:
        _data = ndarray.view(_data, cls)
    if hasattr(data, '_mask') and (not isinstance(data, ndarray)):
        _data._mask = data._mask
    mdtype = make_mask_descr(_data.dtype)
    if mask is nomask:
        if not keep_mask:
            if shrink:
                _data._mask = nomask
            else:
                _data._mask = np.zeros(_data.shape, dtype=mdtype)
        elif isinstance(data, (tuple, list)):
            try:
                mask = np.array([getmaskarray(np.asanyarray(m, dtype=_data.dtype)) for m in data], dtype=mdtype)
            except (ValueError, TypeError):
                mask = nomask
            if mdtype == MaskType and mask.any():
                _data._mask = mask
                _data._sharedmask = False
        else:
            _data._sharedmask = not copy
            if <MASK>:
                _data._mask = _data._mask.copy()
                if getmask(data) is not nomask:
                    if data._mask.shape != data.shape:
                        data._mask.shape = data.shape
    else:
        if mask is None:
            mask = False
        if mask is True and mdtype == MaskType:
            mask = np.ones(_data.shape, dtype=mdtype)
        elif mask is False and mdtype == MaskType:
            mask = np.zeros(_data.shape, dtype=mdtype)
        else:
            try:
                mask = np.array(mask, copy=copy, dtype=mdtype)
            except TypeError:
                mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
        if mask.shape != _data.shape:
            (nd, nm) = (_data.size, mask.size)
            if nm == 1:
                mask = np.resize(mask, _data.shape)
            elif nm == nd:
                mask = np.reshape(mask, _data.shape)
            else:
                msg = f'Mask and data not compatible: data size is {nd}, mask size is {nm}.'
                raise MaskError(msg)
            copy = True
        if _data._mask is nomask:
            _data._mask = mask
            _data._sharedmask = not copy
        elif not keep_mask:
            _data._mask = mask
            _data._sharedmask = not copy
        else:
            if _data.dtype.names is not None:

                def _recursive_or(a, b):
                    """do a|=b on each field of a, recursively"""
                    for name in a.dtype.names:
                        (af, bf) = (a[name], b[name])
                        if af.dtype.names is not None:
                            _recursive_or(af, bf)
                        else:
                            af |= bf
                _recursive_or(_data._mask, mask)
            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

@register_meta(aten.avg_pool2d.default)
def meta_avg_pool2d(input, kernel_size, stride=(), padding=(0,), ceil_mode=False, count_include_pad=True, divisor_override=None):

    def unpack(name, val):
        torch._check(len(val) in [1, 2], lambda : f'avg_pool2d: {name} must either be a single int, or a tuple of two ints')
        H = val[0]
        W = H if len(val) == 1 else val[1]
        return (H, W)
    (kH, kW) = unpack('kernel_size', kernel_size)
    torch._check(len(stride) in [0, 1, 2], lambda : 'avg_pool2d: stride must either be omitted, a single int, or a tuple of two ints')
    torch._check(input.dtype not in [torch.uint8, torch.uint16, torch.uint32, torch.uint64], lambda : f""""avg_pool2d" not implemented for '{input.dtype.__str__()}'""")
    if <MASK>:
        (dH, dW) = (kH, kW)
    elif len(stride) == 1:
        (dH, dW) = (stride[0], stride[0])
    else:
        (dH, dW) = unpack('stride', stride)
    (padH, padW) = unpack('padding', padding)
    torch._check(divisor_override is None or divisor_override != 0, lambda : 'divisor must be not zero')
    nbatch = input.size(-4) if input.dim() == 4 else 1
    nInputPlane = input.size(-3)
    inputHeight = input.size(-2)
    inputWidth = input.size(-1)
    outputHeight = pooling_output_shape(inputHeight, kH, padH, dH, 1, ceil_mode)
    outputWidth = pooling_output_shape(inputWidth, kW, padW, dW, 1, ceil_mode)
    memory_format = utils.suggest_memory_format(input)
    pool2d_shape_check(input, kH, kW, dH, dW, padH, padW, 1, 1, nInputPlane, inputHeight, inputWidth, outputHeight, outputWidth, memory_format)
    if input.dim() == 3:
        size = [nInputPlane, outputHeight, outputWidth]
    else:
        size = [nbatch, nInputPlane, outputHeight, outputWidth]
    return torch.empty(size, dtype=input.dtype, device=input.device, memory_format=memory_format)

def _unique_np(values, return_inverse=False, return_counts=False):
    """Helper function to find unique values for numpy arrays that correctly
    accounts for nans. See `_unique` documentation for details."""
    (xp, _) = get_namespace(values)
    (inverse, counts) = (None, None)
    if return_inverse and return_counts:
        (uniques, _, inverse, counts) = xp.unique_all(values)
    elif <MASK>:
        (uniques, inverse) = xp.unique_inverse(values)
    elif return_counts:
        (uniques, counts) = xp.unique_counts(values)
    else:
        uniques = xp.unique_values(values)
    if uniques.size and is_scalar_nan(uniques[-1]):
        nan_idx = xp.searchsorted(uniques, xp.nan)
        uniques = uniques[:nan_idx + 1]
        if return_inverse:
            inverse[inverse > nan_idx] = nan_idx
        if return_counts:
            counts[nan_idx] = xp.sum(counts[nan_idx:])
            counts = counts[:nan_idx + 1]
    ret = (uniques,)
    if return_inverse:
        ret += (inverse,)
    if return_counts:
        ret += (counts,)
    return ret[0] if len(ret) == 1 else ret

def __new__(cls, dtype, value_key=None, partitions=(), row_splits_dtype=dtypes.int32, validate=False):
    if value_key is not None:
        if not isinstance(value_key, str):
            raise ValueError(f'Argument `value_key` must be a string; got {value_key}')
        if not value_key:
            raise ValueError('Argument `value_key` must not be empty')
    dtype = dtypes.as_dtype(dtype)
    if <MASK>:
        raise ValueError(f'Argument `dtype` must be int64, float32, or bytes; got {dtype!r}')
    row_splits_dtype = dtypes.as_dtype(row_splits_dtype)
    if row_splits_dtype not in (dtypes.int32, dtypes.int64):
        raise ValueError(f'Argument `row_splits_dtype` must be int32 or int64; got{row_splits_dtype!r}')
    if not isinstance(partitions, (list, tuple)):
        raise TypeError(f'Argument `partitions` must be a list or tuple. Receivedpartitions={partitions} of type {type(partitions).__name__}.')
    new_partitions = []
    for partition in partitions:
        new_partition = RaggedFeature._validate_and_recreate_partition(partition, cls._PARTITION_TYPES)
        new_partitions.append(new_partition)
    partitions = tuple(new_partitions)
    for partition in partitions:
        if not isinstance(partition, cls._PARTITION_TYPES):
            raise TypeError(f'Argument `partitions` must be a list of partition objects {cls._PARTITION_TYPES}; got: {partition!r}')
    if not isinstance(validate, bool):
        raise TypeError(f'Argument `validate` must be a bool; got {validate!r}')
    return super().__new__(cls, dtype, value_key, partitions, row_splits_dtype, validate)

def __init__(self, data=None, files=None, auto_id='id_%s', prefix=None, initial=None, error_class=ErrorList, label_suffix=None, empty_permitted=False, instance=None, use_required_attribute=None, renderer=None):
    opts = self._meta
    if opts.model is None:
        raise ValueError('ModelForm has no model class specified.')
    if <MASK>:
        self.instance = opts.model()
        object_data = {}
    else:
        self.instance = instance
        object_data = model_to_dict(instance, opts.fields, opts.exclude)
    if initial is not None:
        object_data.update(initial)
    self._validate_unique = False
    self._validate_constraints = False
    super().__init__(data, files, auto_id, prefix, object_data, error_class, label_suffix, empty_permitted, use_required_attribute=use_required_attribute, renderer=renderer)
    for formfield in self.fields.values():
        apply_limit_choices_to_to_formfield(formfield)

def codegen_kernel(self, name: Optional[str]=None) -> str:
    """Called at the end to generate a final kernel string"""
    self.codegen_body()
    code = IndentedBuffer()
    if V.graph.cpp_wrapper:
        code.writeline('(R"MTL(')
    else:
        code.writeline("compile_mps_shader('''")
    idx_vars = self.active_range_trees()
    with code.indent():
        if not V.graph.cpp_wrapper:
            for header in self.headers:
                code.writeline(f'#include <c10/metal/{header}.h>')
        else:
            headers = [f'#include <c10/metal/{header}.h>' for header in self.headers]
            header_contents = _embed_headers(headers, [Path(__file__).parent.parent.parent / 'include'], OrderedSet())
            code.writeline(header_contents)
        if <MASK>:
            total_reduction_size = math.prod((t.numel for t in self.range_trees if t.is_reduction))
            threadgroup_size = min(total_reduction_size, self.max_threadgroup_size) if isinstance(total_reduction_size, sympy.Integer) else self.max_threadgroup_size
            code.writeline(f'[[max_total_threads_per_threadgroup({threadgroup_size})]]')
        code.writeline('kernel void generated_kernel(')
        with code.indent():
            for (outer, inner) in self.args.output_buffers.items():
                if outer in self.removed_buffers:
                    continue
                dtype_str = self.dtype_to_str(V.graph.get_dtype(outer))
                code.writeline(f'device {dtype_str}* {inner},')
            for (outer, inner) in self.args.input_buffers.items():
                dtype = V.graph.get_dtype(outer)
                if dtype == torch.float64:
                    outer_buf = V.graph.try_get_buffer(outer)
                    if outer_buf is None or outer_buf.get_size() != []:
                        raise RuntimeError('float64 is not supported by MPS')
                    dtype_str = 'float'
                else:
                    dtype_str = self.dtype_to_str(dtype)
                code.writeline(f'constant {dtype_str}* {inner},')
            for (outer, inner) in self.args.sizevars.items():
                code.writeline(f'constant long& {inner},')
            for idx_var in idx_vars:
                if isinstance(idx_var.numel, sympy.Integer):
                    pass
                else:
                    code.writeline(f'constant long& {idx_var.prefix}numel,')
            assert len(idx_vars) < 4, 'Up to 3 index variables are supported'
            thread_pos_dtype = f'uint{len(idx_vars)}' if len(idx_vars) > 1 else 'uint'
            thread_pos_var_name = idx_vars[0].name if len(idx_vars) == 1 else 'thread_pos'
            thread_pos_suffix = ',' if self.inside_reduction else ''
            code.writeline(f'{thread_pos_dtype} {thread_pos_var_name} [[thread_position_in_grid]]{thread_pos_suffix}')
            if self.inside_reduction:
                code.writeline(f'{thread_pos_dtype} group_pos [[thread_position_in_threadgroup]]')
        code.writeline(') {')
        with code.indent():
            if len(idx_vars) > 1:
                for (idx, var) in enumerate(idx_vars):
                    code.writeline(f'auto {var.name} = thread_pos.{chr(120 + idx)};')
            code.splice(self.indexing_code)
            code.splice(self.body)
        code.writeline('}')
    if V.graph.cpp_wrapper:
        code.writeline(')MTL");')
    else:
        code.writeline("''')")
    return code.getvalue()

def _unflatten_orig_param_states(fsdp_param_info: FSDPParamInfo, output_states: dict[str, dict[str, Any]], state_name: str, shard_state: bool, to_save: bool, cpu_offload: bool) -> None:
    """
    Given a output state dict, ``output_states``, which the keys are FQNs to the
    original parameters (not FlatParameters nor parameter ID), and the values
    are gathered states, unflatten the states to the original dimensions.

    This function performs the unflattening process in-place.
    """
    if <MASK>:
        return
    flat_param = fsdp_param_info.handle.flat_param
    fsdp_state = fsdp_param_info.state
    for (fqn, gathered_state) in output_states.items():
        value = gathered_state[state_name]
        param_idx = fsdp_param_info.param_indices[fqn]
        if isinstance(value, DTensor):
            placement = value.placements[0]
            if placement != Replicate():
                placement_dim = placement.dim
                value.redistribute(placements=(Replicate(),))
                reshape_size = list(flat_param._shapes[param_idx])
                reshape_size[placement_dim] *= value.device_mesh.size(0)
                reshape_size = torch.Size(reshape_size)
                value = value.reshape(reshape_size)
            else:
                value = value.reshape(flat_param._shapes[param_idx])
        else:
            value = value.reshape(flat_param._shapes[param_idx])
        if shard_state:
            osd_config = fsdp_state._optim_state_dict_config
            if getattr(osd_config, '_use_dtensor', False):
                if fsdp_state._device_mesh is None:
                    raise AssertionError(f'Expected _device_mesh to be not None, got {fsdp_state._device_mesh}')
                value = _ext_chunk_dtensor(value, fsdp_state.rank, fsdp_state._device_mesh, fsdp_state._fsdp_extension)
            else:
                if fsdp_state.process_group is None:
                    raise AssertionError(f'Expected process_group to be not None, got {fsdp_state.process_group}')
                value = _ext_chunk_tensor(value, fsdp_state.rank, fsdp_state.world_size, fsdp_state._device_handle.device_count(), fsdp_state.process_group, fsdp_state._fsdp_extension)
        elif not cpu_offload:
            with SimpleProfiler.profile('clone'):
                value = value.detach().clone()
        if cpu_offload:
            with SimpleProfiler.profile(SimpleProfiler.Type.D2H):
                value = value.cpu()
        gathered_state[state_name] = value

def hash_storage(storage: torch.UntypedStorage, *, stable_hash: bool=False) -> str:
    import torch._dynamo
    from torch._dynamo.utils import is_compile_supported
    device_type = storage.device.type
    if <MASK>:
        cpu_storage = storage.cpu()
        buf = (ctypes.c_byte * cpu_storage.nbytes()).from_address(cpu_storage.data_ptr())
        sha1 = hashlib.sha1(usedforsecurity=False)
        sha1.update(buf)
        return sha1.hexdigest()
    if device_type == 'cpu':
        generator = torch._C.default_generator
    elif device_type == 'cuda':
        generator = torch.cuda.default_generators[storage.device.index]
    elif device_type == 'mps':
        generator = torch.mps._get_default_mps_generator()
    elif device_type == 'xpu':
        generator = torch.xpu.default_generators[storage.device.index]
    else:
        raise AssertionError(f'unhandled device type {device_type}')
    state = generator.get_state()
    try:
        generator.manual_seed(0)
        x = torch.empty(0, dtype=torch.uint8, device=storage.device).set_(storage)
        pad = -x.numel() % 4
        if pad > 0:
            x = F.pad(x, (0, pad), 'constant', 0)
        x = x.view(torch.int32)
        ITER = 5
        cs = [hash_storage_kernel(x).item() for _ in range(ITER)]
        return struct.pack('>' + 'i' * ITER, *cs).hex()
    finally:
        generator.set_state(state)

def _GetQrOpTest(dtype_, shape_, full_matrices_, use_static_shape_):
    is_complex = dtype_ in (np.complex64, np.complex128)
    is_single = dtype_ in (np.float32, np.complex64)

    def CompareOrthogonal(self, x, y, rank):
        if is_single:
            atol = 0.0005
        else:
            atol = 5e-14
        x = x[..., 0:rank]
        y = y[..., 0:rank]
        sum_of_ratios = np.sum(np.divide(y, x), -2, keepdims=True)
        phases = np.divide(sum_of_ratios, np.abs(sum_of_ratios))
        x *= phases
        self.assertAllClose(x, y, atol=atol)

    def CheckApproximation(self, a, q, r):
        if is_single:
            tol = 1e-05
        else:
            tol = 1e-14
        a_recon = test_util.matmul_without_tf32(q, r)
        self.assertAllClose(a_recon, a, rtol=tol, atol=tol)

    def CheckUnitary(self, x):
        xx = test_util.matmul_without_tf32(x, x, adjoint_a=True)
        identity = array_ops.matrix_band_part(array_ops.ones_like(xx), 0, 0)
        if is_single:
            tol = 1e-05
        else:
            tol = 1e-14
        self.assertAllClose(identity, xx, atol=tol)

    @test_util.run_in_graph_and_eager_modes(use_gpu=True)
    def Test(self):
        if not use_static_shape_ and context.executing_eagerly():
            return
        np.random.seed(1)
        x_np = np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape_)).reshape(shape_).astype(dtype_)
        if is_complex:
            x_np += 1j * np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape_)).reshape(shape_).astype(dtype_)
            if <MASK>:
                x_tf = constant_op.constant(x_np)
            else:
                x_tf = array_ops.placeholder(dtype_)
            (q_tf, r_tf) = linalg_ops.qr(x_tf, full_matrices=full_matrices_)
            if use_static_shape_:
                (q_tf_val, r_tf_val) = self.evaluate([q_tf, r_tf])
            else:
                with self.session() as sess:
                    (q_tf_val, r_tf_val) = sess.run([q_tf, r_tf], feed_dict={x_tf: x_np})
            q_dims = q_tf_val.shape
            np_q = np.ndarray(q_dims, dtype_)
            np_q_reshape = np.reshape(np_q, (-1, q_dims[-2], q_dims[-1]))
            new_first_dim = np_q_reshape.shape[0]
            x_reshape = np.reshape(x_np, (-1, x_np.shape[-2], x_np.shape[-1]))
            for i in range(new_first_dim):
                if full_matrices_:
                    (np_q_reshape[i, :, :], _) = np.linalg.qr(x_reshape[i, :, :], mode='complete')
                else:
                    (np_q_reshape[i, :, :], _) = np.linalg.qr(x_reshape[i, :, :], mode='reduced')
            np_q = np.reshape(np_q_reshape, q_dims)
            CompareOrthogonal(self, np_q, q_tf_val, min(shape_[-2:]))
            CheckApproximation(self, x_np, q_tf_val, r_tf_val)
            CheckUnitary(self, q_tf_val)
    return Test

def visit_FunctionDef(self, node):
    compose_dec = []
    for dec in node.decorator_list:
        if isinstance(dec, ast.Call):
            if isinstance(dec.func, ast.Attribute) and dec.func.attr == 'Composite':
                compose_dec.append(dec)
            if isinstance(dec.func, ast.Name) and dec.func.id == 'Composite':
                compose_dec.append(dec)
    if not compose_dec:
        return
    elif len(compose_dec) > 1:
        raise KeyError('More than one TF ops decomposes for.')
    all_dec_args = {}
    for (arg_name, arg_value) in zip(_COMPOSITE_ARG_LIST, compose_dec[0].args):
        all_dec_args[arg_name] = self.visit(arg_value)
    kw_dec_args = dict([self.visit(kw) for kw in compose_dec[0].keywords])
    if <MASK>:
        raise KeyError('More arguments than expected.')
    all_dec_args.update(kw_dec_args)
    op_name = all_dec_args['op_name']
    op_def = op_def_registry.get(op_name)
    if op_def:
        if len(all_dec_args) > 1:
            raise ValueError('Op has been registered: ' + op_name)
        else:
            return
    inputs = all_dec_args.get('inputs', [])
    attrs = all_dec_args.get('attrs', [])
    expected_args = [arg.split(':')[0] for arg in inputs + attrs]
    all_func_args = self.visit(node.args)
    if len(expected_args) != len(all_func_args):
        raise KeyError('Composition arguments for {} do not match the registration. {} vs {}'.format(op_name, expected_args, all_func_args))
    cxx_reg_code = ['\nREGISTER_OP("{}")'.format(op_name)]
    for input_ in inputs:
        cxx_reg_code.append('.Input("{}")'.format(input_))
    for attr in attrs:
        py_str = attr.replace('"', "'")
        cxx_reg_code.append('.Attr("{}")'.format(py_str))
    for attr in all_dec_args.get('derived_attrs', []):
        py_str = attr.replace('"', "'")
        cxx_reg_code.append('.Attr("{}")'.format(py_str))
    for output_ in all_dec_args.get('outputs', []):
        cxx_reg_code.append('.Output("{}")'.format(output_))
    cxx_reg_code[-1] += ';\n'
    self.emit('\n    '.join(cxx_reg_code))

