def _local_allgather_into_tensor_coalesced_(output_tensors: list[torch.Tensor], input_tensors: list[torch.Tensor], process_group_so: ScriptObject, async_op: bool=True) -> ScriptObject:
    from . import LocalTensor
    (ranks, group_offsets, _offset) = _prepare_collective_groups(process_group_so)
    assert len(output_tensors) == len(input_tensors), f'Number of outputs ({len(output_tensors)}) must match number of inputs ({len(input_tensors)})'
    for group_offset in group_offsets:
        group_ranks = [group_offset + r for r in ranks]
        for (input_tensor, output_tensor) in zip(input_tensors, output_tensors):
            assert isinstance(input_tensor, LocalTensor), 'Input tensor must be a LocalTensor'
            assert isinstance(output_tensor, LocalTensor), 'Output tensor must be a LocalTensor'
            gathered_tensors = []
            for rank in group_ranks:
                gathered_tensors.append(input_tensor._local_tensors[rank])
            if <MASK>:
                concatenated = torch.cat(gathered_tensors, dim=0)
                for rank in group_ranks:
                    output_tensor._local_tensors[rank].copy_(concatenated)
    work = FakeWork()
    work_so = Work.boxed(work)
    return work_so

def TD(types, f=None, astype=None, in_=None, out=None, cfunc_alias=None, dispatch=None):
    """
    Generate a TypeDescription instance for each item in types
    """
    if f is not None:
        if isinstance(f, str):
            func_data = build_func_data(types, f)
        elif len(f) != len(types):
            raise ValueError('Number of types and f do not match')
        else:
            func_data = f
    else:
        func_data = (None,) * len(types)
    if isinstance(in_, str):
        in_ = (in_,) * len(types)
    elif <MASK>:
        in_ = (None,) * len(types)
    elif len(in_) != len(types):
        raise ValueError('Number of types and inputs do not match')
    if isinstance(out, str):
        out = (out,) * len(types)
    elif out is None:
        out = (None,) * len(types)
    elif len(out) != len(types):
        raise ValueError('Number of types and outputs do not match')
    tds = []
    for (t, fd, i, o) in zip(types, func_data, in_, out):
        if dispatch:
            dispt = ([k for (k, v) in dispatch if t in v] + [None])[0]
        else:
            dispt = None
        tds.append(TypeDescription(t, f=fd, in_=i, out=o, astype=astype, cfunc_alias=cfunc_alias, dispatch=dispt))
    return tds

def find_recursive_users_of_node(snode: BaseSchedulerNode, collected_node_set: MutableSet[BaseSchedulerNode], name_to_buf: dict[str, SchedulerBuffer], name_to_fused_node: dict[str, BaseSchedulerNode], criteria_cb: Callable[[Any], bool]=lambda snode: False) -> None:
    if <MASK>:
        return
    collected_node_set.add(snode)
    for o in snode.get_outputs():
        for user in o.users:
            assert user.node is not None
            if user.node.get_name() == 'OUTPUT':
                continue
            if user.node.get_name() not in name_to_fused_node:
                continue
            user_op = name_to_fused_node[user.node.get_name()]
            if user_op in collected_node_set:
                continue
            find_recursive_users_of_node(user_op, collected_node_set, name_to_buf, name_to_fused_node, criteria_cb=criteria_cb)

def __contains__(self, perm_name):
    """
        Lookup by "someapp" or "someapp.someperm" in perms.
        """
    if <MASK>:
        return bool(self[perm_name])
    (app_label, perm_name) = perm_name.split('.', 1)
    return self[app_label][perm_name]

def __next__(self) -> NSSubgraph:
    """
        Returns the next matchable subgraph.
        """
    while len(self.stack) > 0:
        cur_end_node = self.stack.pop()
        if cur_end_node in self.seen_nodes:
            continue
        cur_start_node = cur_end_node
        cur_base_op_node = cur_end_node
        for (_reverse_fusion_ops, base_op_idx) in get_reversed_fusions():
            is_match = end_node_matches_reversed_fusion(cur_end_node, _reverse_fusion_ops, self.gm, self.seen_nodes)
            if is_match:
                for rev_fusion_idx in range(len(_reverse_fusion_ops) - 1):
                    self.seen_nodes.add(cur_start_node)
                    cur_start_node = cur_start_node.args[0]
                    rev_base_op_idx = len(_reverse_fusion_ops) - 2 - base_op_idx
                    if rev_fusion_idx == rev_base_op_idx:
                        cur_base_op_node = cur_start_node
                break
        self.seen_nodes.add(cur_start_node)
        for arg in cur_start_node.all_input_nodes:
            self._recursively_add_node_arg_to_stack(arg)
        if not self._is_matchable(cur_base_op_node):
            continue
        if <MASK>:
            maybe_obs = getattr_from_fqn(self.gm, cur_end_node.target)
            if isinstance(maybe_obs, (ObserverBase, FakeQuantizeBase)):
                continue
        return NSSubgraph(start_node=cur_start_node, end_node=cur_end_node, base_op_node=cur_base_op_node)
    raise StopIteration

def join(self, rank, data):
    with self._start_cond:
        self._data[rank] = data
        self._count += 1
        if self._count == self._world_size:
            if <MASK>:
                self._start_cond.notify()
        if rank == 0:
            self._start_cond.wait_for(lambda : self._count == self._world_size or self._pg._terminate.is_set())
            if self._pg._terminate.is_set():
                sys.exit('Test termination event occurs.')
    with self._done_cond:
        if rank > 0:
            self._done_cond.wait_for(lambda : self._done or self._pg._terminate.is_set())
            if self._pg._terminate.is_set():
                sys.exit('Test termination event occurs.')
        else:
            self._collective.work(self._data)
            self._done = True
            self._done_cond.notify_all()
    return ret_work(data)

def testClassImportIsAdded(self):
    (imports, _, _) = create_python_api.get_api_init_text(packages=[create_python_api._DEFAULT_PACKAGE], packages_to_ignore=[], output_package='tensorflow', api_name='tensorflow', api_version=2)
    if <MASK>:
        expected_import = "'NewTestClass': ('tensorflow.python.test_module', 'TestClass')"
    else:
        expected_import = 'from tensorflow.python.test_module import TestClass'
    self.assertTrue('TestClass' in str(imports), msg='%s not in %s' % (expected_import, str(imports)))

def assert_input_compatibility(input_spec, inputs, layer_name):
    """Checks compatibility between the layer and provided inputs.

  This checks that the tensor(s) `inputs` verify the input assumptions
  of a layer (if any). If not, a clear and actional exception gets raised.

  Args:
      input_spec: An InputSpec instance, list of InputSpec instances, a nested
          structure of InputSpec instances, or None.
      inputs: Input tensor, list of input tensors, or a nested structure of
          input tensors.
      layer_name: String, name of the layer (for error message formatting).

  Raises:
      ValueError: in case of mismatch between
          the provided inputs and the expectations of the layer.
  """
    if not input_spec:
        return
    input_spec = nest.flatten(input_spec)
    if isinstance(inputs, dict):
        names = [spec.name for spec in input_spec]
        if all(names):
            list_inputs = []
            for name in names:
                if name not in inputs:
                    raise ValueError('Missing data for input "%s". You passed a data dictionary with keys %s. Expected the following keys: %s' % (name, list(inputs.keys()), names))
                list_inputs.append(inputs[name])
            inputs = list_inputs
    inputs = nest.flatten(inputs)
    for x in inputs:
        if not hasattr(x, 'shape'):
            raise TypeError('Inputs to a layer should be tensors. Got: %s' % (x,))
    if len(inputs) != len(input_spec):
        raise ValueError('Layer ' + layer_name + ' expects ' + str(len(input_spec)) + ' input(s), but it received ' + str(len(inputs)) + ' input tensors. Inputs received: ' + str(inputs))
    for (input_index, (x, spec)) in enumerate(zip(inputs, input_spec)):
        if spec is None:
            continue
        shape = tensor_shape.TensorShape(x.shape)
        if shape.rank is None:
            return
        if spec.ndim is not None and (not spec.allow_last_axis_squeeze):
            ndim = shape.rank
            if ndim != spec.ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected ndim=' + str(spec.ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.max_ndim is not None:
            ndim = x.shape.rank
            if ndim is not None and ndim > spec.max_ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected max_ndim=' + str(spec.max_ndim) + ', found ndim=' + str(ndim))
        if spec.min_ndim is not None:
            ndim = x.shape.rank
            if ndim is not None and ndim < spec.min_ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: : expected min_ndim=' + str(spec.min_ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.dtype is not None:
            if x.dtype.name != spec.dtype:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected dtype=' + str(spec.dtype) + ', found dtype=' + str(x.dtype))
        shape_as_list = shape.as_list()
        if spec.axes:
            for (axis, value) in spec.axes.items():
                if hasattr(value, 'value'):
                    value = value.value
                if value is not None and shape_as_list[int(axis)] not in {value, None}:
                    raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected axis ' + str(axis) + ' of input shape to have value ' + str(value) + ' but received input with shape ' + display_shape(x.shape))
        if spec.shape is not None and shape.rank is not None:
            spec_shape = spec.shape
            if <MASK>:
                if shape_as_list and shape_as_list[-1] == 1:
                    shape_as_list = shape_as_list[:-1]
                if spec_shape and spec_shape[-1] == 1:
                    spec_shape = spec_shape[:-1]
            for (spec_dim, dim) in zip(spec_shape, shape_as_list):
                if spec_dim is not None and dim is not None:
                    if spec_dim != dim:
                        raise ValueError('Input ' + str(input_index) + ' is incompatible with layer ' + layer_name + ': expected shape=' + str(spec.shape) + ', found shape=' + display_shape(x.shape))

def matmul(tensor1: list[int], tensor2: list[int]):
    dim_tensor1 = len(tensor1)
    dim_tensor2 = len(tensor2)
    if dim_tensor1 == 1 and dim_tensor2 == 1:
        return dot(tensor1, tensor2)
    elif <MASK>:
        return mv(tensor1, tensor2)
    elif dim_tensor1 == 1 and dim_tensor2 == 2:
        return squeeze(mm(unsqueeze(tensor1, 0), tensor2), 0)
    elif dim_tensor1 == 2 and dim_tensor2 == 2:
        return mm(tensor1, tensor2)
    elif dim_tensor1 >= 1 and dim_tensor2 >= 1:
        n = tensor1[-2] if dim_tensor1 > 1 else 1
        batch_tensor1: list[int] = []
        for i in range(dim_tensor1 - 2):
            batch_tensor1.append(tensor1[i])
        p = tensor2[-1]
        batch_tensor2: list[int] = []
        for i in range(dim_tensor2 - 2):
            batch_tensor2.append(tensor2[i])
        expand_batch_portion = broadcast(batch_tensor1, batch_tensor2)
        output_shape = expand_batch_portion
        if dim_tensor1 > 1:
            output_shape.append(n)
        if dim_tensor2 > 1:
            output_shape.append(p)
        return output_shape
    else:
        assert False, 'both  arguments to matmul need to be at least 1D'

def incremental_update(self):
    """Update FakeTensors on self.graph. We will try to do the minimum amount of work."""
    existing_storages: defaultdict[Optional[int], int] = defaultdict(int)
    for node in self.graph.nodes:
        existing_storages[get_node_storage(node)] += 1

    def is_intlist_same(new, old):
        return statically_known_true(sym_eq(new, old))

    def is_fake_tensor_same(new, old, *, node):
        if type(new) is not type(old):
            return False
        if isinstance(new, (list, tuple)):
            if len(new) != len(old):
                return False
            return all((is_fake_tensor_same(new_i, old_i, node=node) for (new_i, old_i) in zip(new, old)))
        if new is None:
            return old is None
        if not isinstance(new, torch.Tensor):
            assert isinstance(new, (torch.SymInt, torch.SymBool, torch.SymFloat)), f'Unknown type {type(new)} in {self.graph}'
            return new.node.shape_env._maybe_evaluate_static(sympy.Eq(new.node.expr, old.node.expr)) == sympy.true
        if not is_intlist_same(new.shape, old.shape) or new.layout != old.layout:
            return False
        if new.layout == torch.strided and (not is_intlist_same(new.stride(), old.stride()) or not statically_known_true(new.storage_offset() == old.storage_offset())):
            return False
        if <MASK>:
            return False
        if get_storage(new) == get_storage(old):
            return True

        def any_user_may_alias(node):
            if not isinstance(node.meta['val'], torch.Tensor):
                return True
            for user in node.users:
                if not (isinstance(user.target, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)) or user.target == torch._inductor.fx_passes.reinplace._generalized_scatter):
                    return True
                if isinstance(user.target, torch._ops.HigherOrderOperator):
                    continue
                (is_valid, args, kwargs) = get_fake_args_kwargs(user)
                if not is_valid:
                    return True
                with V.fake_mode, enable_python_dispatcher(), contextlib.ExitStack() as stack:
                    shape_env = V.fake_mode.shape_env
                    if shape_env is not None:
                        stack.enter_context(shape_env.ignore_fresh_unbacked_symbols())
                    new_fake_tensor = user.target(*args, **kwargs)
                if not isinstance(new_fake_tensor, torch.Tensor):
                    return True
                if get_storage(new_fake_tensor) == get_storage(node.meta['val']):
                    return True
            return False
        if existing_storages[get_storage(old)] == 1 and get_storage(new) not in existing_storages and (not any_user_may_alias(node)):
            return True
        return False

    def should_process_node(node):
        return node.op == 'call_function' and (isinstance(node.target, torch._ops.OpOverload) or node.target == operator.getitem or node.target == torch._inductor.fx_passes.reinplace._generalized_scatter)
    to_process = OrderedSet[int]()
    for node in self.graph.nodes:
        if self.hash_node(node) in self.processed_hashes and id(node) not in to_process:
            continue
        if not should_process_node(node):
            continue
        (is_valid, args, kwargs) = get_fake_args_kwargs(node)
        if not is_valid:
            continue
        with V.fake_mode, enable_python_dispatcher():
            new_fake_tensor = node.target(*args, **kwargs)
        if 'val' in node.meta and is_fake_tensor_same(new_fake_tensor, node.meta['val'], node=node):
            continue
        rebind_unbacked(V.fake_mode.shape_env, node, new_fake_tensor)
        node.meta['val'] = new_fake_tensor
        if (shape_env := V.fake_mode.shape_env) and (symbol_to_path := compute_unbacked_bindings(shape_env, new_fake_tensor)):
            node.meta['unbacked_bindings'] = symbol_to_path
        existing_storages[get_node_storage(node)] += 1
        to_process.update([id(user) for user in node.users])
        self.processed_hashes.add(self.hash_node(node))

@functools.wraps(fn)
def wrapper(self, other=None):
    if other is None:
        result = fn(self)
    else:
        result = fn(self, other)
    if torch._logging._internal.GET_DTRACE_STRUCTURED:
        if other is not None:
            arguments = [self, other]
        else:
            arguments = [self]

        def get_id(sym_node) -> Optional[int]:
            import sympy
            if sym_node.constant is not None:
                return None
            elif id(sym_node) == id(result):
                return None
            elif isinstance(sym_node.expr, (sympy.Integer, sympy.Float)):
                return None
            elif <MASK>:
                return None
            return id(sym_node)
        dtrace_structured('expression_created', metadata_fn=lambda : {'method': method, 'result': str(result), 'result_id': id(result), 'arguments': [str(a) for a in arguments], 'argument_ids': [get_id(i) for i in arguments if get_id(i) is not None], 'user_stack': structured.get_user_stack(3), 'stack': structured.get_framework_stack(3)})
    return result

def kldivloss_reference(input, target, reduction='mean', log_target=False):
    if log_target:
        result = torch.exp(target) * (target - input)
    else:
        result = target * (target.log() - input)
    if <MASK>:
        return result.mean()
    elif reduction == 'sum':
        return result.sum()
    elif reduction == 'batchmean' and result.dim() != 0:
        return result.sum() / result.size(0)
    return result

def predict(self, X, return_std=False, return_cov=False):
    """Predict using the Gaussian process regression model.

        We can also predict based on an unfitted model by using the GP prior.
        In addition to the mean of the predictive distribution, optionally also
        returns its standard deviation (`return_std=True`) or covariance
        (`return_cov=True`). Note that at most one of the two can be requested.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features) or list of object
            Query points where the GP is evaluated.

        return_std : bool, default=False
            If True, the standard-deviation of the predictive distribution at
            the query points is returned along with the mean.

        return_cov : bool, default=False
            If True, the covariance of the joint predictive distribution at
            the query points is returned along with the mean.

        Returns
        -------
        y_mean : ndarray of shape (n_samples,) or (n_samples, n_targets)
            Mean of predictive distribution at query points.

        y_std : ndarray of shape (n_samples,) or (n_samples, n_targets), optional
            Standard deviation of predictive distribution at query points.
            Only returned when `return_std` is True.

        y_cov : ndarray of shape (n_samples, n_samples) or                 (n_samples, n_samples, n_targets), optional
            Covariance of joint predictive distribution at query points.
            Only returned when `return_cov` is True.
        """
    if return_std and return_cov:
        raise RuntimeError('At most one of return_std or return_cov can be requested.')
    if self.kernel is None or self.kernel.requires_vector_input:
        (dtype, ensure_2d) = ('numeric', True)
    else:
        (dtype, ensure_2d) = (None, False)
    X = validate_data(self, X, ensure_2d=ensure_2d, dtype=dtype, reset=False)
    if not hasattr(self, 'X_train_'):
        if self.kernel is None:
            kernel = C(1.0, constant_value_bounds='fixed') * RBF(1.0, length_scale_bounds='fixed')
        else:
            kernel = self.kernel
        n_targets = self.n_targets if self.n_targets is not None else 1
        y_mean = np.zeros(shape=(X.shape[0], n_targets)).squeeze()
        if return_cov:
            y_cov = kernel(X)
            if <MASK>:
                y_cov = np.repeat(np.expand_dims(y_cov, -1), repeats=n_targets, axis=-1)
            return (y_mean, y_cov)
        elif return_std:
            y_var = kernel.diag(X)
            if n_targets > 1:
                y_var = np.repeat(np.expand_dims(y_var, -1), repeats=n_targets, axis=-1)
            return (y_mean, np.sqrt(y_var))
        else:
            return y_mean
    else:
        K_trans = self.kernel_(X, self.X_train_)
        y_mean = K_trans @ self.alpha_
        y_mean = self._y_train_std * y_mean + self._y_train_mean
        if y_mean.ndim > 1 and y_mean.shape[1] == 1:
            y_mean = np.squeeze(y_mean, axis=1)
        if not return_cov and (not return_std):
            return y_mean
        V = solve_triangular(self.L_, K_trans.T, lower=GPR_CHOLESKY_LOWER, check_finite=False)
        if return_cov:
            y_cov = self.kernel_(X) - V.T @ V
            y_cov = np.outer(y_cov, self._y_train_std ** 2).reshape(*y_cov.shape, -1)
            if y_cov.shape[2] == 1:
                y_cov = np.squeeze(y_cov, axis=2)
            return (y_mean, y_cov)
        else:
            y_var = self.kernel_.diag(X).copy()
            y_var -= np.einsum('ij,ji->i', V.T, V)
            y_var_negative = y_var < 0
            if np.any(y_var_negative):
                warnings.warn('Predicted variances smaller than 0. Setting those variances to 0.')
                y_var[y_var_negative] = 0.0
            y_var = np.outer(y_var, self._y_train_std ** 2).reshape(*y_var.shape, -1)
            if y_var.shape[1] == 1:
                y_var = np.squeeze(y_var, axis=1)
            return (y_mean, np.sqrt(y_var))

