def run(self, fetches, feed_dict=None, options=None, run_metadata=None, callable_runner=None, callable_runner_args=None, callable_options=None):
    """Wrapper around Session.run() that inserts tensor watch options.

    Args:
      fetches: Same as the `fetches` arg to regular `Session.run()`.
      feed_dict: Same as the `feed_dict` arg to regular `Session.run()`.
      options: Same as the `options` arg to regular `Session.run()`.
      run_metadata: Same as the `run_metadata` arg to regular `Session.run()`.
      callable_runner: A `callable` returned by `Session.make_callable()`.
        If not `None`, `fetches` and `feed_dict` must both be `None`.
        Mutually exclusive with `callable_options`.
      callable_runner_args: An optional list of arguments to `callable_runner`
        or for `callable_options`.
      callable_options: An instance of `config_pb2.CallableOptions`, to be
        used with `Session._make_callable_from_options()`. Mutually exclusive
        with `callable_runner`.

    Returns:
      Simply forwards the output of the wrapped `Session.run()` call.

    Raises:
      ValueError: On invalid `OnRunStartAction` value. Or if `callable_runner`
        is not `None` and either or both of `fetches` and `feed_dict` is `None`.
    """
    if callable_runner and callable_options:
        raise ValueError('callable_runner and callable_options are mutually exclusive, but are both specified in this call to BaseDebugWrapperSession.run().')
    if callable_runner and (fetches or feed_dict):
        raise ValueError('callable_runner and fetches/feed_dict are mutually exclusive, but are used simultaneously.')
    elif callable_options and (fetches or feed_dict):
        raise ValueError('callable_options and fetches/feed_dict are mutually exclusive, but are used simultaneously.')
    self.increment_run_call_count()

    def is_empty(x):
        """Check whether a possibly nested structure is empty."""
        if not nest.is_nested(x):
            return False
        if isinstance(x, collections_abc.Mapping):
            return is_empty(list(x.values()))
        for item in x:
            if not is_empty(item):
                return False
        return True
    empty_fetches = is_empty(fetches)
    if empty_fetches:
        tf_logging.info('Due to empty fetches, tfdbg Session wrapper is letting a Session.run pass through without any debugging actions.')
    if self._is_disabled_thread() or empty_fetches:
        if callable_runner:
            return callable_runner(*callable_runner_args)
        elif callable_options:
            return self._sess._make_callable_from_options(callable_options)(*callable_runner_args)
        else:
            return self._sess.run(fetches, feed_dict=feed_dict, options=options, run_metadata=run_metadata)
    run_start_resp = self.on_run_start(OnRunStartRequest(fetches, feed_dict, options, run_metadata, self._run_call_count, is_callable_runner=bool(callable_runner)))
    _check_type(run_start_resp, OnRunStartResponse)
    if <MASK>:
        (retvals, run_end_req) = self._run_with_debugging(run_start_resp, fetches, feed_dict, options, run_metadata, callable_runner, callable_runner_args, callable_options)
    elif run_start_resp.action == OnRunStartAction.PROFILE_RUN:
        (retvals, run_end_req) = self._run_with_profiling(run_start_resp, fetches, feed_dict, options, run_metadata, callable_runner, callable_runner_args, callable_options)
    elif run_start_resp.action == OnRunStartAction.NON_DEBUG_RUN:
        if callable_runner:
            retvals = callable_runner(*callable_runner_args)
        elif callable_options:
            callable_object = self._sess._make_callable_from_options(callable_options)
            retvals = callable_object(*callable_runner_args)
        else:
            retvals = self._sess.run(fetches, feed_dict=feed_dict, options=options, run_metadata=run_metadata)
        run_end_req = OnRunEndRequest(run_start_resp.action)
    else:
        raise ValueError('Invalid OnRunStartAction value: %s' % run_start_resp.action)
    run_end_resp = self.on_run_end(run_end_req)
    _check_type(run_end_resp, OnRunEndResponse)
    return retvals

def can_fuse_vertical(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode) -> bool:
    if <MASK>:
        assert node1.node, 'node1.node should not be None'
        return self._can_fuse_epilogue_impl(cast(CUDATemplateBuffer, node1.node), [], node2)
    elif self.is_cuda_cpp_fused_template(node1) and isinstance(node2, BaseSchedulerNode):
        assert node1.node, 'node1.node should not be None'
        assert node2.node, 'node2.node should not be None'
        fnode1 = cast(FusedSchedulerNode, node1)
        return self._can_fuse_epilogue_impl(fnode1.get_template_node(), self._unwrap_epilogue_nodes(fnode1), node2)
    return False

def outer_config_opt():
    (max_x_block, x_block) = (256, 64)
    load_factor = inductor_meta.get('num_load', 0)
    x = size_hints['x']
    num_warps = None
    if x <= 1024:
        x_block = max(min(x // 128, 8), 2)
        outer_r_block = min(rnumel, 64)
    elif x // 4096 <= 8:
        x_block = 16
        outer_r_block = 512 // x_block
    elif num_dynamic > 1:
        outer_r_block = max(min(rnumel // 64, 64), 8)
    elif num_dynamic == 1:
        outer_r_block = 1 if load_factor >= 3 else min(next_power_of_2(max(rnumel, 128) // 128), 8)
    else:
        x_block = max(min(max_x_block, next_power_of_2(x // 4096)), x_block)
        if <MASK>:
            outer_r_block = 512 // x_block
        else:
            if rnumel >= 2048:
                outer_r_block = 64
            else:
                outer_r_block = 32
            x_block = min(x_block, 32)
            num_warps = 4
    return make_config(x_block, outer_r_block, num_warps=num_warps, register_intensive=register_intensive)

@parameterized.parameters(itertools.product(range(1, 4), (5, 6), (np.float32, np.float64)))
@test_util.run_gpu_only
def testAxes_rfftn(self, dims, size, np_rtype):
    inner_dim = size // 2 + 1
    np_ctype = np.complex64 if np_rtype == np.float32 else np.complex128
    tol = 0.0001 if np_ctype == np.complex64 else 1e-08
    r2c = np.mod(np.arange(np.power(size, dims)), 10).reshape((size,) * dims)
    if dims == 1:
        fft_length = (size,)
        axes = (-1,)
    elif <MASK>:
        fft_length = (size, size)
        axes = (0, 1)
    else:
        fft_length = None
        axes = None
    self._CompareForward_fftn(r2c.astype(np_rtype), fft_length=fft_length, axes=axes, rtol=tol)
    c2r = np.mod(np.arange(np.power(size, dims - 1) * inner_dim), 10).reshape((size,) * (dims - 1) + (inner_dim,))
    c2r = self._generate_valid_irfft_input(c2r, np_ctype, r2c, np_rtype, 2, fft_length)
    self._CompareBackward_fftn(c2r, fft_length, axes, rtol=tol)

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument('-o', '--outfile', type=str, help='Path to write version info to', required=False)
    parser.add_argument('--print', default=False, action='store_true', help='Whether to print out the version', required=False)
    args = parser.parse_args()
    if args.outfile:
        if not args.outfile.endswith('.py'):
            raise ValueError(f'Output file must be a Python file. Got: {args.outfile} as filename instead')
        write_version_info(args.outfile)
    if <MASK>:
        try:
            import _version_meson
            version = _version_meson.__version__
        except ImportError:
            version = versioneer.get_version()
        print(version)

def consolidate_types(self, qualified_name: str) -> dict:
    all_args = self.analyze(qualified_name)
    for (arg, types) in all_args.items():
        types = list(types)
        type_length = len(types)
        if type_length == 2 and type(None) in types:
            all_args[arg] = get_optional_of_element_type(types)
        elif type_length > 1:
            all_args[arg] = 'Any'
        elif <MASK>:
            all_args[arg] = get_type(types[0])
    return all_args

def __init__(self, *args, device=None, dtype=None, wrap_storage=None, _internal=False):
    if <MASK>:
        _warn_typed_storage_removal()
    arg_error_msg = 'TypedStorage.__init__ received an invalid combination of arguments. Expected one of:\n * (*, torch.device device, torch.dtype dtype)\n * (int size, *, torch.device device, torch.dtype dtype)\n * (Sequence data, *, torch.device device, torch.dtype dtype)\n * (*, UntypedStorage wrap_storage, torch.dtype dtype)'
    if wrap_storage is not None:
        if len(args) != 0:
            raise RuntimeError(arg_error_msg + "\nNo positional arguments should be given when using 'wrap_storage'")
        if dtype is None:
            raise RuntimeError(arg_error_msg + "\nArgument 'dtype' must be specified")
        if not isinstance(dtype, torch.dtype):
            raise TypeError(arg_error_msg + f"\nArgument 'dtype' must be torch.dtype, not {type(dtype)}")
        if device is not None:
            raise RuntimeError(arg_error_msg + "\nArgument 'device' should not be specified when 'wrap_storage' is given")
        self.dtype = dtype
        if not isinstance(wrap_storage, torch.UntypedStorage):
            raise TypeError(arg_error_msg + f"\nArgument 'wrap_storage' must be UntypedStorage, but got {type(wrap_storage)}")
        self._untyped_storage = wrap_storage
    else:
        self.dtype = torch.get_default_dtype() if dtype is None else dtype
        device = torch.device('cpu' if device is None else device)
        if self.dtype in [torch.quint8, torch.quint4x2, torch.quint2x4, torch.qint32, torch.qint8]:
            if device.type == 'cuda':
                raise RuntimeError('Cannot create CUDA storage with quantized dtype')
        if len(args) == 0:
            self._untyped_storage = torch.UntypedStorage(device=device)
        elif len(args) == 1:
            if _isint(args[0]):
                self._untyped_storage = torch.UntypedStorage(int(args[0]) * self._element_size(), device=device)
            elif isinstance(args[0], collections.abc.Sequence):
                self._untyped_storage = _get_storage_from_sequence(args[0], self.dtype, device)
            else:
                raise TypeError(arg_error_msg + f'\nArgument type not recognized: {type(args[0])}')
        else:
            raise RuntimeError(arg_error_msg + '\nToo many positional arguments')

def get_meta(self, table_name, constraints, column_to_field_name, is_view, is_partition, comment):
    """
        Return a sequence comprising the lines of code necessary
        to construct the inner Meta class for the model corresponding
        to the given database table name.
        """
    unique_together = []
    has_unsupported_constraint = False
    for params in constraints.values():
        if params['unique']:
            columns = params['columns']
            if None in columns:
                has_unsupported_constraint = True
            columns = [x for x in columns if x is not None and x in column_to_field_name]
            if len(columns) > 1 and (not params['primary_key']):
                unique_together.append(str(tuple((column_to_field_name[c] for c in columns))))
    if is_view:
        managed_comment = "  # Created from a view. Don't remove."
    elif <MASK>:
        managed_comment = "  # Created from a partition. Don't remove."
    else:
        managed_comment = ''
    meta = ['']
    if has_unsupported_constraint:
        meta.append('    # A unique constraint could not be introspected.')
    meta += ['    class Meta:', '        managed = False%s' % managed_comment, '        db_table = %r' % table_name]
    if unique_together:
        tup = '(' + ', '.join(unique_together) + ',)'
        meta += ['        unique_together = %s' % tup]
    if comment:
        meta += [f'        db_table_comment = {comment!r}']
    return meta

def get_extra_size_of(node: Node, nodes: set[Node]) -> int:
    """Given a node and a set of nodes,
    this function return the extra size that needed
    if this node is included in this set.
    """
    input_nodes: dict[Node, None] = {}
    map_arg(node.args, input_nodes.setdefault)
    map_arg(node.kwargs, input_nodes.setdefault)
    total_size_of_input_nodes = 0
    for n in input_nodes:
        if <MASK>:
            size_bytes = getattr(n, 'size_bytes', None)
            if size_bytes:
                total_size_of_input_nodes += size_bytes.output_size
            else:
                raise RuntimeError('node has no size_bytes attr')
    size_bytes = getattr(node, 'size_bytes', None)
    if size_bytes:
        total_size_of_input_nodes += size_bytes.total_size
    else:
        raise RuntimeError('node has no size_bytes attr')
    return total_size_of_input_nodes

def substitute(self, symbols_map):
    """Recursively substitute symbols with values in symbols map.

        Symbols map is a dictionary of symbol-expression pairs.
        """
    if self.op is Op.SYMBOL:
        value = symbols_map.get(self)
        if <MASK>:
            return self
        m = re.match('\\A(@__f2py_PARENTHESIS_(\\w+)_\\d+@)\\Z', self.data)
        if m:
            (items, paren) = m.groups()
            if paren in ['ROUNDDIV', 'SQUARE']:
                return as_array(value)
            assert paren == 'ROUND', (paren, value)
        return value
    if self.op in (Op.INTEGER, Op.REAL, Op.STRING):
        return self
    if self.op in (Op.ARRAY, Op.COMPLEX):
        return Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data)))
    if self.op is Op.CONCAT:
        return normalize(Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data))))
    if self.op is Op.TERMS:
        r = None
        for (term, coeff) in self.data.items():
            if r is None:
                r = term.substitute(symbols_map) * coeff
            else:
                r += term.substitute(symbols_map) * coeff
        if r is None:
            ewarn('substitute: empty TERMS expression interpreted as int-literal 0')
            return as_number(0)
        return r
    if self.op is Op.FACTORS:
        r = None
        for (base, exponent) in self.data.items():
            if r is None:
                r = base.substitute(symbols_map) ** exponent
            else:
                r *= base.substitute(symbols_map) ** exponent
        if r is None:
            ewarn('substitute: empty FACTORS expression interpreted as int-literal 1')
            return as_number(1)
        return r
    if self.op is Op.APPLY:
        (target, args, kwargs) = self.data
        if isinstance(target, Expr):
            target = target.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in args))
        kwargs = {k: v.substitute(symbols_map) for (k, v) in kwargs.items()}
        return normalize(Expr(self.op, (target, args, kwargs)))
    if self.op is Op.INDEXING:
        func = self.data[0]
        if isinstance(func, Expr):
            func = func.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in self.data[1:]))
        return normalize(Expr(self.op, (func,) + args))
    if self.op is Op.TERNARY:
        operands = tuple((a.substitute(symbols_map) for a in self.data))
        return normalize(Expr(self.op, operands))
    if self.op in (Op.REF, Op.DEREF):
        return normalize(Expr(self.op, self.data.substitute(symbols_map)))
    if self.op is Op.RELATIONAL:
        (rop, left, right) = self.data
        left = left.substitute(symbols_map)
        right = right.substitute(symbols_map)
        return normalize(Expr(self.op, (rop, left, right)))
    raise NotImplementedError(f'substitute method for {self.op}: {self!r}')

@register_graph_pattern(CallFunction(torch.ops.aten.cat, ListOf(CallFunctionVarArgs(torch.ops.aten.unsqueeze)), _users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('unbind_stack_aten_pass'))
def merge_unbind_stack_aten(match: Match, *args, **kwargs):
    node = match.nodes[-1]
    graph = match.graph
    unsqueeze_nodes = list(node.args[0])
    cat_dim = get_arg_value(node, 1, 'dim')
    if not all((get_arg_value(unsqueeze_node, 0, 'input').target == torch.ops.aten.select for unsqueeze_node in unsqueeze_nodes)):
        return
    select_nodes = [get_arg_value(unsqueeze_node, 0, 'input') for unsqueeze_node in unsqueeze_nodes]
    parent_of_select_node = get_arg_value(select_nodes[0], 0, 'input')
    if not all((select_node.target == torch.ops.aten.select for select_node in select_nodes)):
        return
    if not all((get_arg_value(select_node, 0, 'input') == parent_of_select_node for select_node in select_nodes)):
        return
    if len(unsqueeze_nodes) != len(select_nodes):
        return
    if not all((get_arg_value(select_node, 1, 'dim') == cat_dim for select_node in select_nodes)):
        return
    if <MASK>:
        return
    if len(parent_of_select_node.users.keys()) != len(node.args[0]):
        return
    node.replace_all_uses_with(parent_of_select_node)
    graph.erase_node(node)
    for unsqueeze_node in unsqueeze_nodes:
        graph.erase_node(unsqueeze_node)
    for select_node in select_nodes:
        if len(select_node.users) == 0:
            graph.erase_node(select_node)
    counters[backend]['unbind_stack_aten_pass'] += 1

def dynamo_normalization_capturing_compiler(gm: torch.fx.GraphModule, inner_example_inputs: list[Any]) -> Callable[..., Any]:
    nonlocal graph
    assert graph is None, "Tried to emit a second graph during export. Tracing through 'f' must produce a single graph."
    graph = gm
    nonlocal fake_mode, example_inputs
    fake_mode = _guards.detect_fake_mode()
    example_inputs = inner_example_inputs

    def result_capturing_wrapper(*graph_inputs: Any) -> Any:
        nonlocal graph_captured_result
        nonlocal graph_captured_input
        graph_captured_input = graph_inputs
        assert graph is not None
        named_parameters = dict(graph.named_parameters(remove_duplicate=False))
        named_buffers = dict(graph.named_buffers(remove_duplicate=False))
        ambient_fake_mode = _guards.detect_fake_mode(graph_inputs) if _guards.detect_fake_mode(graph_inputs) is not None else fake_mode
        ignore_fresh_unbacked = null_context()
        assert ambient_fake_mode is not None
        if (shape_env := ambient_fake_mode.shape_env):
            ignore_fresh_unbacked = shape_env.ignore_fresh_unbacked_symbols()
        with ambient_fake_mode, enable_python_dispatcher(), ignore_fresh_unbacked:
            params_and_buffers = {**named_parameters, **named_buffers}
            fake_params_buffers = {}
            for (name, value) in params_and_buffers.items():
                fake_params_buffers[name] = ambient_fake_mode.from_tensor(value, static_shapes=True)
            from torch._export.non_strict_utils import key_path_to_source, KeyPath

            def fakify_with_ambient(path: KeyPath, t: Union[torch.Tensor, _IntWrapper, Any]) -> Any:
                if <MASK>:
                    return ambient_fake_mode.from_tensor(t, static_shapes=True)
                elif isinstance(t, _IntWrapper):
                    if t.dynamism is not None and isinstance(t.dynamism, _DimHint) and (t.dynamism.type in (_DimHintType.DYNAMIC, _DimHintType.AUTO)):
                        source = key_path_to_source(path)
                        symint = ambient_fake_mode.shape_env.create_unspecified_symint_and_symbol(t.val, source, DimDynamic.DYNAMIC)
                        return symint
                    else:
                        return t.val
                else:
                    return t
            fake_graph_inputs = pytree.tree_map_with_path(fakify_with_ambient, graph_inputs)
            graph_captured_result = torch.func.functional_call(graph, fake_params_buffers, fake_graph_inputs)
        return graph_captured_result
    return result_capturing_wrapper

def wrapper(arr: np.ndarray, indexer: np.ndarray, out: np.ndarray, fill_value=np.nan) -> None:
    if <MASK>:
