            fill_value = fill_value.astype('m8[ns]')
        else:
            fill_value = fill_value.astype('M8[ns]')
        fill_value = fill_wrap(fill_value)
    f(arr, indexer, out, fill_value=fill_value)

@setupmethod
def template_filter(self, name: T_template_filter | str | None=None) -> T_template_filter | t.Callable[[T_template_filter], T_template_filter]:
    """Decorate a function to register it as a custom Jinja filter. The name
        is optional. The decorator may be used without parentheses.

        .. code-block:: python

            @app.template_filter("reverse")
            def reverse_filter(s):
                return reversed(s)

        The :meth:`add_template_filter` method may be used to register a
        function later rather than decorating.

        :param name: The name to register the filter as. If not given, uses the
            function's name.
        """
    if <MASK>:
        self.add_template_filter(name)
        return name

    def decorator(f: T_template_filter) -> T_template_filter:
        self.add_template_filter(f, name=name)
        return f
    return decorator

def where(condition: ArrayLike, x: Optional[ArrayLikeOrScalar]=None, y: Optional[ArrayLikeOrScalar]=None, /):
    if (x is None) != (y is None):
        raise ValueError('either both or neither of x and y should be given')
    if <MASK>:
        condition = condition.to(torch.bool)
    if x is None and y is None:
        result = torch.where(condition)
    else:
        result = torch.where(condition, x, y)
    return result

def format_speedup(speedup: float, pvalue: float, is_correct: bool=True, pvalue_threshold: float=0.1) -> str:
    if <MASK>:
        return 'ERROR'
