def delete_file(self, path, prefixed_path, source_storage):
    """
        Check if the target file should be deleted if it already exists.
        """
    if <MASK>:
        try:
            target_last_modified = self.storage.get_modified_time(prefixed_path)
        except (OSError, NotImplementedError):
            pass
        else:
            try:
                source_last_modified = source_storage.get_modified_time(path)
            except (OSError, NotImplementedError):
                pass
            else:
                if self.local:
                    full_path = self.storage.path(prefixed_path)
                    can_skip_unmodified_files = not self.symlink ^ os.path.islink(full_path)
                else:
                    can_skip_unmodified_files = True
                file_is_unmodified = target_last_modified.replace(microsecond=0) >= source_last_modified.replace(microsecond=0)
                if file_is_unmodified and can_skip_unmodified_files:
                    if prefixed_path not in self.unmodified_files:
                        self.unmodified_files.append(prefixed_path)
                    self.log("Skipping '%s' (not modified)" % path)
                    return False
        if self.dry_run:
            self.log("Pretending to delete '%s'" % path)
        else:
            self.log("Deleting '%s'" % path)
            self.storage.delete(prefixed_path)
    return True

def __getitem__(self, key):
    """
        Conserve RangeIndex type for scalar and slice keys.
        """
    key = lib.item_from_zerodim(key)
    if key is Ellipsis:
        key = slice(None)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    elif is_integer(key):
        new_key = int(key)
        try:
            return self._range[new_key]
        except IndexError as err:
            raise IndexError(f'index {key} is out of bounds for axis 0 with size {len(self)}') from err
    elif is_scalar(key):
        raise IndexError('only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) and integer or boolean arrays are valid indices')
    elif <MASK>:
        if isinstance(getattr(key, 'dtype', None), ExtensionDtype):
            key = key.to_numpy(dtype=bool, na_value=False)
        else:
            key = np.asarray(key, dtype=bool)
        check_array_indexer(self._range, key)
        key = np.flatnonzero(key)
    try:
        return self.take(key)
    except (TypeError, ValueError):
        return super().__getitem__(key)

def get_node_first_input_and_output_type(node: Node, gm: GraphModule, logger_cls: Callable, node_type_to_io_type_map: dict[str, set[NSNodeTargetType]]) -> tuple[NodeInputOrOutputType, NodeInputOrOutputType]:
    FUNS_IO_TYPE_FP32 = node_type_to_io_type_map['funs_io_type_fp32']
    FUNS_IO_TYPE_FP16 = node_type_to_io_type_map['funs_io_type_fp16']
    FUNS_IO_TYPE_INT8 = node_type_to_io_type_map['funs_io_type_int8']
    FUNS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['funs_io_type_fp32_or_int8']
    MODS_IO_TYPE_FP32 = node_type_to_io_type_map['mods_io_type_fp32']
    MODS_IO_TYPE_INT8 = node_type_to_io_type_map['mods_io_type_int8']
    MODS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['mods_io_type_fp32_or_int8']
    METHS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['meths_io_type_fp32_or_int8']
    if node.op == 'call_function':
        if node.target in FUNS_IO_TYPE_FP32:
            return (NodeInputOrOutputType.FP32, NodeInputOrOutputType.FP32)
        if node.target in FUNS_IO_TYPE_FP16:
            return (NodeInputOrOutputType.FP16, NodeInputOrOutputType.FP16)
        elif node.target in FUNS_IO_TYPE_INT8:
            return (NodeInputOrOutputType.INT8, NodeInputOrOutputType.INT8)
        elif node.target in FUNS_IO_TYPE_FP32_OR_INT8:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        else:
            return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    elif node.op == 'call_module':
        if node.op != 'call_module':
            raise AssertionError(f"Expected call_module, got '{node.op}'")
        if not isinstance(node.target, str):
            raise AssertionError(f'Expected str, but got {type(node.target)}')
        mod = getattr_from_fqn(gm, node.target)
        is_known_fp32_or_int8_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_FP32_OR_INT8))
        if isinstance(mod, (logger_cls, ObserverBase, FakeQuantizeBase)) or is_known_fp32_or_int8_input_module:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        is_known_fp32_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_FP32))
        is_known_int8_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_INT8))
        if is_known_fp32_input_module:
            return (NodeInputOrOutputType.FP32, NodeInputOrOutputType.FP32)
        elif is_known_int8_input_module:
            return (NodeInputOrOutputType.INT8, NodeInputOrOutputType.INT8)
        else:
            return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    elif node.op == 'call_method':
        if <MASK>:
            prev_node = get_normalized_nth_input(node, gm, 0)
            if not isinstance(prev_node, Node):
                raise AssertionError(f'Expected Node, got {type(prev_node)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(prev_node, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, NodeInputOrOutputType.FP32)
        elif node.target == 'to':
            prev_node = get_normalized_nth_input(node, gm, 0)
            if not isinstance(prev_node, Node):
                raise AssertionError(f'Expected Node, got {type(prev_node)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(prev_node, gm, logger_cls, node_type_to_io_type_map)
            cur_node_dtype_target = get_normalized_nth_input(node, gm, 1)
            if cur_node_dtype_target is not torch.float16:
                raise AssertionError(f'{cur_node_dtype_target} handling needs to be added')
            return (prev_node_output_type, NodeInputOrOutputType.FP16)
        elif node.target in METHS_IO_TYPE_FP32_OR_INT8:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    else:
        return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)

def _verify_single_loop_var(name, check_shape, init, entry, exit_, shape_invariant):
    """Verifies whether the initial, entry and exit values are consistent."""
    assert entry is not None, "no TF op should set '{}' to None?".format(name)
    if exit_ is None:
        raise ValueError("'{}' is None at the end of the iteration.".format(name))
    if isinstance(init, (bool, int, float, str, np.ndarray)):
        init = tensor_conversion.convert_to_tensor_v2(init)
    if <MASK>:
        entry = tensor_conversion.convert_to_tensor_v2(entry)
    if isinstance(exit_, (bool, int, float, str, np.ndarray)):
        exit_ = tensor_conversion.convert_to_tensor_v2(exit_)
    if not tensor_util.is_tf_type(entry) or not tensor_util.is_tf_type(exit_):
        return
    if not hasattr(entry, 'dtype') or not hasattr(exit_, 'dtype'):
        return
    if not hasattr(entry, 'shape') or not hasattr(exit_, 'shape'):
        return
    if entry.dtype != exit_.dtype:
        raise TypeError("'{}' has dtype {} before the loop, but dtype {} after one iteration".format(name, entry.dtype.name, exit_.dtype.name))
    if check_shape:
        exit_shape = exit_.shape
        if shape_invariant is None:
            entry_shape = entry.shape
            if not _is_subshape(exit_shape, entry_shape):
                raise ValueError("'{}' has shape {} before the loop, but shape {} after one iteration. Use tf.autograph.experimental.set_loop_options to set shape invariants.".format(name, entry_shape, exit_shape))
        else:
            init_shape = init.shape
            if not _is_subshape(init_shape, shape_invariant):
                raise ValueError("'{}' has shape {} before the loop, which does not conform with the shape invariant {}.".format(name, init_shape, shape_invariant))
            if not _is_subshape(exit_shape, shape_invariant):
                raise ValueError("'{}' has shape {} after one iteration, which does not conform with the shape invariant {}.".format(name, exit_shape, shape_invariant))

def _replicatable_module(module: Module, memo: Optional[set[Module]]=None) -> bool:

    def descendant_modules(module: Module) -> Iterator[Module]:
        gen = module.modules()
        next(gen)
        return gen
    if not _is_jit_enabled():
        return True
    if memo is None:
        memo = set()
    memo.add(module)
    if <MASK>:
        memo.update(descendant_modules(module))
        return all((_is_script_module(descendant) for descendant in descendant_modules(module)))
    for child in module.children():
        if child in memo:
            continue
        if not _replicatable_module(child, memo):
            return False
    return True

def _get_quant_params(tensor_detail: Mapping[str, Any]) -> Optional[Tuple[float, int]]:
    """Returns first scale and zero point from tensor detail, if present."""
    quant_params = tensor_detail['quantization_parameters']
    if <MASK>:
        return None
    if quant_params['scales'] and quant_params['zero_points']:
        return (quant_params['scales'][0], quant_params['zero_points'][0])
    return None

def _unflatten_orig_param_states(fsdp_param_info: FSDPParamInfo, output_states: dict[str, dict[str, Any]], state_name: str, shard_state: bool, to_save: bool, cpu_offload: bool) -> None:
    """
    Given a output state dict, ``output_states``, which the keys are FQNs to the
    original parameters (not FlatParameters nor parameter ID), and the values
    are gathered states, unflatten the states to the original dimensions.

    This function performs the unflattening process in-place.
    """
    if not to_save:
        return
    flat_param = fsdp_param_info.handle.flat_param
    fsdp_state = fsdp_param_info.state
    for (fqn, gathered_state) in output_states.items():
        value = gathered_state[state_name]
        param_idx = fsdp_param_info.param_indices[fqn]
        if isinstance(value, DTensor):
            placement = value.placements[0]
            if placement != Replicate():
                placement_dim = placement.dim
                value.redistribute(placements=(Replicate(),))
                reshape_size = list(flat_param._shapes[param_idx])
                reshape_size[placement_dim] *= value.device_mesh.size(0)
                reshape_size = torch.Size(reshape_size)
                value = value.reshape(reshape_size)
            else:
                value = value.reshape(flat_param._shapes[param_idx])
        else:
            value = value.reshape(flat_param._shapes[param_idx])
        if shard_state:
            osd_config = fsdp_state._optim_state_dict_config
            if <MASK>:
                if fsdp_state._device_mesh is None:
                    raise AssertionError(f'Expected _device_mesh to be not None, got {fsdp_state._device_mesh}')
                value = _ext_chunk_dtensor(value, fsdp_state.rank, fsdp_state._device_mesh, fsdp_state._fsdp_extension)
            else:
                if fsdp_state.process_group is None:
                    raise AssertionError(f'Expected process_group to be not None, got {fsdp_state.process_group}')
                value = _ext_chunk_tensor(value, fsdp_state.rank, fsdp_state.world_size, fsdp_state._device_handle.device_count(), fsdp_state.process_group, fsdp_state._fsdp_extension)
        elif not cpu_offload:
            with SimpleProfiler.profile('clone'):
                value = value.detach().clone()
        if cpu_offload:
            with SimpleProfiler.profile(SimpleProfiler.Type.D2H):
                value = value.cpu()
        gathered_state[state_name] = value

def reconstruct(self, codegen: 'PyCodegen') -> None:
    codegen.add_push_null(lambda : codegen.load_import_from(utils.__name__, f'call_{self.prop.method_name()}'))
    codegen(self.base)
    if <MASK>:
        codegen.append_output(codegen.create_load_const(self.idx))
    codegen.extend_output(create_call_function(2 if self.idx is not None else 1, False))

def compute_mask(self, inputs, mask=None):
    if mask is None:
        return None
    if not isinstance(mask, (tuple, list)):
        raise ValueError('`mask` should be a list.')
    if not isinstance(inputs, (tuple, list)):
        raise ValueError('`inputs` should be a list.')
    if <MASK>:
        raise ValueError('The lists `inputs` and `mask` should have the same length.')
    if all((m is None for m in mask)):
        return None
    masks = []
    for (input_i, mask_i) in zip(inputs, mask):
        if mask_i is None:
            masks.append(array_ops.ones_like(input_i, dtype='bool'))
        elif backend.ndim(mask_i) < backend.ndim(input_i):
            masks.append(array_ops.expand_dims(mask_i, axis=-1))
        else:
            masks.append(mask_i)
    concatenated = backend.concatenate(masks, axis=self.axis)
    return backend.all(concatenated, axis=-1, keepdims=False)

def fuzz_valid_stride(size: tuple[int, ...]) -> tuple[int, ...]:
    """
    Fuzzes PyTorch tensor strides by generating valid stride patterns for a given size.

    Args:
        size: Tensor shape/size as a tuple of integers

    Returns:
        Tuple[int, ...]: A tuple representing valid tensor strides
    """
    if len(size) == 0:
        return ()
    stride_types = ['contiguous', 'transposed', 'custom_gaps', 'minimal', 'nonoverlapping_and_dense', 'nonoverlapping_and_dense_non_contig', 'overlapping', 'sparse_gaps']
    stride_type: str = random.choice(stride_types)
    if stride_type in ['contiguous', 'nonoverlapping_and_dense']:
        return tuple(_compute_contiguous_strides(size))
    elif stride_type == 'transposed':
        base_strides = list(_compute_contiguous_strides(size))
        if len(base_strides) >= 2:
            (i, j) = random.sample(range(len(base_strides)), 2)
            (base_strides[i], base_strides[j]) = (base_strides[j], base_strides[i])
        return tuple(base_strides)
    elif stride_type == 'custom_gaps':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] != 0 and random.random() < 0.3:
                gap_multiplier: int = random.randint(2, 5)
                base_strides[i] *= gap_multiplier
        return tuple(base_strides)
    elif <MASK>:
        return tuple([1] * len(size))
    elif stride_type == 'nonoverlapping_and_dense_non_contig':
        return tuple(_compute_non_contiguous_dense_strides(size))
    elif stride_type == 'overlapping':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] > 1 and random.random() < 0.4:
                base_strides[i] = 0
        return tuple(base_strides)
    elif stride_type == 'sparse_gaps':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] > 1:
                gap_multiplier: int = random.randint(10, 100)
                base_strides[i] *= gap_multiplier
        return tuple(base_strides)
    return tuple(_compute_contiguous_strides(size))

def build_sources(self):
    if self.inplace:
        self.get_package_dir = self.get_finalized_command('build_py').get_package_dir
    self.build_py_modules_sources()
    for libname_info in self.libraries:
        self.build_library_sources(*libname_info)
    if <MASK>:
        self.check_extensions_list(self.extensions)
        for ext in self.extensions:
            self.build_extension_sources(ext)
    self.build_data_files_sources()
    self.build_npy_pkg_config()

@final
def __delitem__(self, key) -> None:
    """
        Delete item
        """
    deleted = False
    maybe_shortcut = False
    if self.ndim == 2 and isinstance(self.columns, MultiIndex):
        try:
            maybe_shortcut = key not in self.columns._engine
        except TypeError:
            pass
    if maybe_shortcut:
        if not isinstance(key, tuple):
            key = (key,)
        for col in self.columns:
            if isinstance(col, tuple) and col[:len(key)] == key:
                del self[col]
                deleted = True
    if <MASK>:
        loc = self.axes[-1].get_loc(key)
        self._mgr = self._mgr.idelete(loc)

def _safe_repr(object, context, maxlevels, level, changed_only=False):
    """Same as the builtin _safe_repr, with added support for Estimator
    objects."""
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if issubclass(typ, dict) and r is dict.__repr__:
        if <MASK>:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if issubclass(typ, list) and r is list.__repr__ or (issubclass(typ, tuple) and r is tuple.__repr__):
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            (orepr, oreadable, orecur) = _safe_repr(o, context, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if not oreadable:
                readable = False
            if orecur:
                recursive = True
        del context[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

def __enter__(self):
    connection = get_connection(self.using)
    if self.durable and connection.atomic_blocks and (not connection.atomic_blocks[-1]._from_testcase):
        raise RuntimeError('A durable atomic block cannot be nested within another atomic block.')
    if not connection.in_atomic_block:
        connection.commit_on_exit = True
        connection.needs_rollback = False
        if not connection.get_autocommit():
            connection.in_atomic_block = True
            connection.commit_on_exit = False
    if <MASK>:
        if self.savepoint and (not connection.needs_rollback):
            sid = connection.savepoint()
            connection.savepoint_ids.append(sid)
        else:
            connection.savepoint_ids.append(None)
    else:
        connection.set_autocommit(False, force_begin_transaction_with_broken_autocommit=True)
        connection.in_atomic_block = True
    if connection.in_atomic_block:
        connection.atomic_blocks.append(self)

def _populate_quantization_options_default_values(quantization_options: _QuantizationOptions) -> None:
    """Populates default values for QuantizationOptions.

  Populates unspecified or unset fields of QuantizationOptions with the default
  values.

  * If `op_set` is unspecified, it defaults to `OpSet.XLA`.
  * If `freeze_all_variables` is not set, it defaults to `True`.
  * Check if configurations are set correctly:
    - Per-channel quantization is supported for Uniform Quantized opset only.

  Args:
    quantization_options: An instance of QuantizationOptions.
  """
    if quantization_options.op_set == quant_opts_pb2.OpSet.OP_SET_UNSPECIFIED:
        quantization_options.op_set = quant_opts_pb2.OpSet.XLA
    if not quantization_options.tags:
        quantization_options.tags.append(tag_constants.SERVING)
    if not quantization_options.signature_keys:
        quantization_options.signature_keys.append(signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY)
    if not quantization_options.HasField('freeze_all_variables'):
        quantization_options.freeze_all_variables = True
    if quantization_options.enable_legacy_weight_only:
        raise ValueError('Legacy weight-only is deprecated. Use weight-only quantization method.')
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_UNSPECIFIED:
        logging.debug('"preset_method" for QuantizationMethod is not specified.Static range quantization is used by default.')
        quantization_options.quantization_method.preset_method = _PresetMethod.METHOD_STATIC_RANGE_INT8
    if quantization_options.min_num_elements_for_weights == 0:
        quantization_options.min_num_elements_for_weights = _DYNAMIC_RANGE_DEFAULT_MIN_NUM_ELEMENTS_FOR_WEIGHTS
        logging.warning('QuantizationOptions.min_num_elements_for_weights is not set (0). Setting to the default value: %d.', _DYNAMIC_RANGE_DEFAULT_MIN_NUM_ELEMENTS_FOR_WEIGHTS)
    if not quantization_options.HasField('enable_per_channel_quantization'):
        quantization_options.enable_per_channel_quantization = False
    if quantization_options.enable_per_channel_quantization and (not ((quantization_options.op_set == quant_opts_pb2.OpSet.UNIFORM_QUANTIZED or quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8) or (quantization_options.op_set in (quant_opts_pb2.OpSet.XLA, quant_opts_pb2.OpSet.STABLEHLO) and quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8))):
        raise ValueError('Currently, per-channel quantization is supported for Uniform Quantized opset, weight only quantization, or XLA/StableHLO opset with static range quantization.')
    if <MASK>:
        raise ValueError('TF/Uniform quantized opset does not support weight-only.')
    if quantization_options.op_set == quant_opts_pb2.OpSet.STABLEHLO and (quantization_options.quantization_method.preset_method != _PresetMethod.METHOD_STATIC_RANGE_INT8 and quantization_options.quantization_method.preset_method != _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8):
        raise ValueError('StableHLO quantized opset currently only supports static range quantization and weight-only quantizationvia TF Quantizer.')
    logging.debug('Setting `force_graph_mode_calibration = True` to ensure the calibration mode is executed properly.')
    quantization_options.force_graph_mode_calibration = True
    if quantization_options.HasField('debugger_config'):
        if not quantization_options.debugger_config.log_dir_path:
            quantization_options.debugger_config.log_dir_path = '/tmp/dumps'
        if quantization_options.debugger_config.debugger_type == stablehlo_quant_config_pb2.DebuggerConfig.DebuggerType.DEBUGGER_TYPE_UNSPECIFIED:
            raise ValueError('Debugger is enabled but debugger type was not specified.')
        if quantization_options.debugger_config.debugger_type == stablehlo_quant_config_pb2.DebuggerConfig.DebuggerType.DEBUGGER_TYPE_WHOLE_MODEL and (not quantization_options.debugger_config.unquantized_dump_model_path):
            raise ValueError('Debugger type whole model verify was used but unquantized_dump_model_path was not specified.')
    _populate_quantization_component_spec(quantization_options.quantization_method)
    _populate_unitwise_quantization_specs(quantization_options)
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8:
        _populate_calibration_options(quantization_options)

@unpack_zerodim_and_defer('__add__')
def __add__(self, other):
    other_dtype = getattr(other, 'dtype', None)
    other = ensure_wrapped_if_datetimelike(other)
    if other is NaT:
        result: np.ndarray | DatetimeLikeArrayMixin = self._add_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_timedeltalike_scalar(other)
    elif isinstance(other, Day) and lib.is_np_dtype(self.dtype, 'Mm'):
        td = Timedelta(days=other.n).as_unit('s')
        result = self._add_timedeltalike_scalar(td)
    elif isinstance(other, BaseOffset):
        result = self._add_offset(other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._add_datetimelike_scalar(other)
    elif isinstance(other, Period) and lib.is_np_dtype(self.dtype, 'm'):
        result = self._add_period(other)
    elif lib.is_integer(other):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast('PeriodArray', self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.add)
    elif lib.is_np_dtype(other_dtype, 'm'):
        result = self._add_timedelta_arraylike(other)
    elif is_object_dtype(other_dtype):
        result = self._addsub_object_array(other, operator.add)
    elif lib.is_np_dtype(other_dtype, 'M') or isinstance(other_dtype, DatetimeTZDtype):
        return self._add_datetime_arraylike(other)
    elif <MASK>:
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast('PeriodArray', self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.add)
    else:
        return NotImplemented
    if isinstance(result, np.ndarray) and lib.is_np_dtype(result.dtype, 'm'):
        from pandas.core.arrays import TimedeltaArray
        return TimedeltaArray._from_sequence(result, dtype=result.dtype)
    return result

def _validate_input(cfn, lxs, d, r, cm):
    if not callable(cfn):
        raise ValueError(f'Combine_fn must be a callable, but got {cfn}')
    if not isinstance(d, int):
        raise ValueError('Dim must be an int, but got ' + str(type(d)))
    if not isinstance(r, bool):
        raise RuntimeError('Reverse must be a bool, but got ' + str(type(r)))
    if cm not in ['pointwise', 'generic']:
        raise ValueError(f"Combine_mode must either 'pointwise' or 'generic', but got {cm}")
    if cm == 'pointwise' and (not all((l.device.type == 'cuda' for l in lxs))):
        raise ValueError("For combine_mode='pointwise', all input tensors need to be on CUDA")
    if len(lxs) == 0:
        raise ValueError('Expected at least 1 xs leaf')
    if <MASK>:
        raise ValueError('xs leaves must be a Tensor')
    if any((x.is_sparse for x in lxs)):
        raise ValueError('xs leaves must dense Tensors, consider using `to_dense()`')
    if any((x.ndim <= d for x in lxs)):
        raise ValueError("All xs leaves must at least have 'dim' number of dimensions and scan dimension > 0")
    if any((x.shape[d] == 0 for x in lxs)):
        raise ValueError("All xs leaves must at least have 'dim' number of dimensions and scan dimension > 0")

def vecdot(x1: Array, x2: Array, /, *, axis: int=-1, **kwargs) -> Array:
    from ._aliases import isdtype
    (x1, x2) = _fix_promotion(x1, x2, only_scalar=False)
    if x1.shape[axis] != x2.shape[axis]:
        raise ValueError('x1 and x2 must have the same size along the given axis')
    if isdtype(x1.dtype, 'integral') or isdtype(x2.dtype, 'integral'):
        if <MASK>:
            raise RuntimeError('vecdot kwargs not supported for integral dtypes')
        x1_ = torch.moveaxis(x1, axis, -1)
        x2_ = torch.moveaxis(x2, axis, -1)
        (x1_, x2_) = torch.broadcast_tensors(x1_, x2_)
        res = x1_[..., None, :] @ x2_[..., None]
        return res[..., 0, 0]
    return torch.linalg.vecdot(x1, x2, dim=axis, **kwargs)

@parameterized.parameters(True, False)
def testCustomGradientVariablesKwonlyArgs(self, anonymous_varargs):
    with context.eager_mode():
        x_captured = variables.Variable(3.0)

        @custom_gradient.custom_gradient
        def FuncMult(x):

            def ActualGrad(dy, variables):
                self.assertLen(variables, 1)
                self.assertIs(variables[0], x_captured)
                x_captured_grad = 5.0 * x * dy
                return (4.0 * x_captured * dy, [x_captured_grad])
            if <MASK>:

                def GradMult(dy, *, variables=None):
                    return ActualGrad(dy, variables)
            else:

                def GradMult(*dys, variables=None):
                    return ActualGrad(dys[0], variables)
            return (x * x_captured, GradMult)
        x = variables.Variable(6.0)
        with backprop.GradientTape(persistent=True) as g:
            y = FuncMult(x)
        self.assertAllEqual(g.gradient(y, x), 4.0 * 3.0)

def _parse_kernel_name(name: str) -> Optional[str]:
    """
    parse the name of the kernel from the event name.
    """
    if name.startswith(ATEN_PREFIX):
        return name[len(ATEN_PREFIX):]
    elif 'conv' in name:
        return 'convolution'
    elif <MASK>:
        return 'addmm'
    elif 'bmm' in name:
        return 'bmm'
    elif 'baddbmm' in name:
        return 'baddbmm'
    elif '_mm' in name:
        return 'mm'
    else:
        return None

@tf_utils.shape_type_conversion
def build(self, inputs_shape):
    if inputs_shape[-1] is None:
        raise ValueError('Expected inputs.shape[-1] to be known, saw shape: %s' % str(inputs_shape))
    _check_supported_dtypes(self.dtype)
    input_depth = inputs_shape[-1]
    h_depth = self._num_units if self._num_proj is None else self._num_proj
    maybe_partitioner = partitioned_variables.fixed_size_partitioner(self._num_unit_shards) if self._num_unit_shards is not None else None
    self._kernel = self.add_variable(_WEIGHTS_VARIABLE_NAME, shape=[input_depth + h_depth, 4 * self._num_units], initializer=self._initializer, partitioner=maybe_partitioner)
    if self.dtype is None:
        initializer = init_ops.zeros_initializer
    else:
        initializer = init_ops.zeros_initializer(dtype=self.dtype)
    self._bias = self.add_variable(_BIAS_VARIABLE_NAME, shape=[4 * self._num_units], initializer=initializer)
    if <MASK>:
        self._w_f_diag = self.add_variable('w_f_diag', shape=[self._num_units], initializer=self._initializer)
        self._w_i_diag = self.add_variable('w_i_diag', shape=[self._num_units], initializer=self._initializer)
        self._w_o_diag = self.add_variable('w_o_diag', shape=[self._num_units], initializer=self._initializer)
    if self._num_proj is not None:
        maybe_proj_partitioner = partitioned_variables.fixed_size_partitioner(self._num_proj_shards) if self._num_proj_shards is not None else None
        self._proj_kernel = self.add_variable('projection/%s' % _WEIGHTS_VARIABLE_NAME, shape=[self._num_units, self._num_proj], initializer=self._initializer, partitioner=maybe_proj_partitioner)
    self.built = True

def _decorator(view_func):
    middleware = middleware_class(view_func, *m_args, **m_kwargs)

    def _pre_process_request(request, *args, **kwargs):
        if hasattr(middleware, 'process_request'):
            result = middleware.process_request(request)
            if result is not None:
                return result
        if hasattr(middleware, 'process_view'):
            result = middleware.process_view(request, view_func, args, kwargs)
            if result is not None:
                return result
        return None

    def _process_exception(request, exception):
        if hasattr(middleware, 'process_exception'):
            result = middleware.process_exception(request, exception)
            if result is not None:
                return result
        raise

    def _post_process_request(request, response):
        if <MASK>:
            if hasattr(middleware, 'process_template_response'):
                response = middleware.process_template_response(request, response)
            if hasattr(middleware, 'process_response'):

                def callback(response):
                    return middleware.process_response(request, response)
                response.add_post_render_callback(callback)
        elif hasattr(middleware, 'process_response'):
            return middleware.process_response(request, response)
        return response
    if iscoroutinefunction(view_func):

        async def _view_wrapper(request, *args, **kwargs):
            result = _pre_process_request(request, *args, **kwargs)
            if result is not None:
                return result
            try:
                response = await view_func(request, *args, **kwargs)
            except Exception as e:
                result = _process_exception(request, e)
                if result is not None:
                    return result
            return _post_process_request(request, response)
    else:

        def _view_wrapper(request, *args, **kwargs):
            result = _pre_process_request(request, *args, **kwargs)
            if result is not None:
                return result
            try:
                response = view_func(request, *args, **kwargs)
            except Exception as e:
                result = _process_exception(request, e)
                if result is not None:
                    return result
            return _post_process_request(request, response)
    return wraps(view_func)(_view_wrapper)

@cache_readonly
def numpy_dtype(self) -> np.dtype:
    """Return an instance of the related numpy dtype"""
    if pa.types.is_timestamp(self.pyarrow_dtype):
        return np.dtype(f'datetime64[{self.pyarrow_dtype.unit}]')
    if <MASK>:
        return np.dtype(f'timedelta64[{self.pyarrow_dtype.unit}]')
    if pa.types.is_string(self.pyarrow_dtype) or pa.types.is_large_string(self.pyarrow_dtype):
        return np.dtype(str)
    try:
        return np.dtype(self.pyarrow_dtype.to_pandas_dtype())
    except (NotImplementedError, TypeError):
        return np.dtype(object)

@cache
def get_pr_info(github_repo: str, github_token: str, pr_number: int) -> dict[str, Any]:
    """
