@out_wrapper(exact_dtype=True)
def matrix_norm(A: TensorLikeType, ord: Union[float, str]='fro', dim: DimsType=(-2, -1), keepdim: bool=False, *, dtype: Optional[torch.dtype]=None) -> TensorLikeType:
    check_is_matrix(A, 'linalg.matrix_norm')
    dim = utils.canonicalize_dims(A.ndim, dim)
    if isinstance(dim, Dim):
        dim = (dim,)
    torch._check(len(dim) == 2, lambda : f'linalg.matrix_norm: dim must be a 2-tuple. Got {dim}')
    torch._check(dim[0] != dim[1], lambda : f'linalg.matrix_norm: dims must be different. Got ({dim[0]}, {dim[1]})')
    _check_norm_dtype(dtype, A.dtype, 'linalg.matrix_norm')
    if isinstance(ord, str):
        torch._check(ord in ('fro', 'nuc'), lambda : f'linalg.matrix_norm: Order {ord} not supported.')
        check_fp_or_complex(A.dtype, 'linalg.matrix_norm', allow_low_precision_dtypes=ord != 'nuc')
        if <MASK>:
            return vector_norm(A, 2, dim, keepdim, dtype=dtype)
        else:
            if dtype is not None:
                A = _maybe_convert_to_dtype(A, dtype)
            perm = _backshift_permutation(dim[0], dim[1], A.ndim)
            result = torch.sum(svdvals(prims.transpose(A, perm)), -1, keepdim)
            if keepdim:
                inv_perm = _inverse_permutation(perm)
                result = prims.transpose(torch.unsqueeze(result, -1), inv_perm)
            return result
    else:
        abs_ord = abs(ord)
        torch._check(abs_ord in (2, 1, float('inf')), lambda : f'linalg.matrix_norm: Order {ord} not supported.')
        check_fp_or_complex(A.dtype, 'linalg.matrix_norm', allow_low_precision_dtypes=ord != 2)
        max_min = partial(torch.amax if ord > 0.0 else torch.amin, keepdim=keepdim)
        if abs_ord == 2.0:
            if dtype is not None:
                A = _maybe_convert_to_dtype(A, dtype)
            perm = _backshift_permutation(dim[0], dim[1], A.ndim)
            result = max_min(svdvals(prims.transpose(A, perm)), dim=-1)
            if keepdim:
                inv_perm = _inverse_permutation(perm)
                result = prims.transpose(torch.unsqueeze(result, -1), inv_perm)
            return result
        else:
            (dim0, dim1) = dim
            if abs_ord == float('inf'):
                (dim0, dim1) = (dim1, dim0)
            if not keepdim and dim0 < dim1:
                dim1 -= 1
            return max_min(vector_norm(A, 1.0, dim=dim0, keepdim=keepdim, dtype=dtype), dim1)

def compute_memory_timeline(nodes: list[BaseSchedulerNode], name_to_freeable_input_buf: dict[str, FreeableInputBuffer], graph_outputs: OrderedSet[str]) -> tuple[list[BufferInfo], dict[BaseSchedulerNode, int], dict[Union[FreeableInputBuffer, SchedulerBuffer], BaseSchedulerNode]]:
    """
    Compute buffer allocation and deallocation sizes and map their
    lifetime to the node schedule
    """
    node_to_step: dict[BaseSchedulerNode, int] = {node: step for (step, node) in enumerate(nodes)}
    buf_info_list: list[BufferInfo] = []
    buf_to_snode_last_use: dict[Union[FreeableInputBuffer, SchedulerBuffer], BaseSchedulerNode] = {}

    def _get_end_step_and_snode(buf: Union[FreeableInputBuffer, SchedulerBuffer]) -> tuple[int, Optional[BaseSchedulerNode]]:
        max_step: int = -1
        max_step_snode: Optional[BaseSchedulerNode] = None
        succ_nodes = buf.mpi_buffer.succ_nodes
        if succ_nodes:
            for succ_node in succ_nodes:
                step = node_to_step[succ_node]
                if <MASK>:
                    max_step = step
                    max_step_snode = succ_node
            assert max_step_snode is not None
        return (max_step, max_step_snode)
    for (buf_name, input_buf) in name_to_freeable_input_buf.items():
        end_step = -1
        if buf_name not in graph_outputs:
            (end_step, end_step_snode) = _get_end_step_and_snode(input_buf)
            assert end_step_snode is not None
            buf_to_snode_last_use[input_buf] = end_step_snode
        buf_info_list.append(BufferInfo(input_buf, input_buf.mpi_buffer.size_free, input_buf.mpi_buffer.size_free, 0, end_step))
    for (step, node) in enumerate(nodes):
        for sched_buf in node.get_outputs():
            buf_name = sched_buf.get_name()
            end_step = -1
            if buf_name not in graph_outputs:
                (end_step, end_step_snode) = _get_end_step_and_snode(sched_buf)
                if end_step == -1:
                    end_step = step
                    buf_to_snode_last_use[sched_buf] = node
                else:
                    assert end_step_snode is not None
                    buf_to_snode_last_use[sched_buf] = end_step_snode
            buf_info_list.append(BufferInfo(sched_buf, sched_buf.mpi_buffer.size_alloc, sched_buf.mpi_buffer.size_free, step, end_step))
    return (buf_info_list, node_to_step, buf_to_snode_last_use)

def replace_regex(values: ArrayLike, rx: re.Pattern, value, mask: npt.NDArray[np.bool_] | None) -> None:
    """
    Parameters
    ----------
    values : ArrayLike
        Object dtype.
    rx : re.Pattern
    value : Any
    mask : np.ndarray[bool], optional

    Notes
    -----
    Alters values in-place.
    """
    if isna(value) or not isinstance(value, str):

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return value if rx.search(s) is not None else s
            else:
                return s
    else:

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return rx.sub(value, s)
            else:
                return s
    f = np.vectorize(re_replacer, otypes=[np.object_])
    if mask is None:
        values[:] = f(values)
    else:
        if <MASK>:
            mask = np.broadcast_to(mask, values.shape)
        values[mask] = f(values[mask])

def _colocate_with_for_gradient(op, gradient_uid, ignore_existing=False) -> ContextManager[None]:
    """Returns a context manager for colocating op gradients with an op.

  Internal API. In eager mode, returns a context manager that sets the default
  device for new ops to the same device as the given op. Does the same if a
  function is currently being built (i.e. the current mode is graph, but the
  overall mode is eager).

  In all other cases, returns a `Graph.colocate_with()` context manager,
  optionally accounting for gradients (if a gradient UID is specified).

  Args:
    op: Operation or Tensor with which to colocate.
    gradient_uid: Optional gradient UID to enable colocation of gradients during
      compilation.
    ignore_existing: See `Graph.colocate_with()`.

  Returns:
    A context manager used to colocate ops and gradients with the specified
    operation.
  """
    if <MASK>:
        if op is not None:
            if not hasattr(op, 'device'):
                op = convert_to_tensor(op)
            return device(op.device)
        else:
            return NullContextmanager()
    else:
        default_graph = get_default_graph()
        if isinstance(op, EagerTensor):
            if default_graph.building_function:
                return default_graph.device(op.device)
            else:
                raise ValueError('Encountered an Eager-defined Tensor during graph construction, but a function was not being built.')
        return default_graph._colocate_with_for_gradient(op, gradient_uid=gradient_uid, ignore_existing=ignore_existing)

def _select_training_loop(self, inputs):
    """Select training loop for fit/eval/predict based on the inputs."""
    if isinstance(inputs, (iterator_ops.Iterator, iterator_ops.IteratorBase)):
        raise ValueError('For performance reasons Keras `fit`, `evaluate` and`predict` accept tf.data `Datasets` as input but not iterators that have been manually generated from Datasets by users. Please directly pass in the original `Dataset` object instead of passing in `iter(dataset)`.')
    if <MASK>:
        if self._in_multi_worker_mode():
            return training_distributed_v1.DistributionMultiWorkerTrainingLoop(training_distributed_v1.DistributionSingleWorkerTrainingLoop())
        else:
            return training_distributed_v1.DistributionSingleWorkerTrainingLoop()
    if data_utils.is_generator_or_sequence(inputs):
        return training_generator_v1.GeneratorOrSequenceTrainingLoop()
    if training_utils_v1.is_eager_dataset_or_iterator(inputs):
        return training_generator_v1.EagerDatasetOrIteratorTrainingLoop()
    if self.run_eagerly:
        return training_generator_v1.GeneratorLikeTrainingLoop()
    else:
        return training_arrays_v1.ArrayLikeTrainingLoop()

@staticmethod
def can_use_32bit_indexing(numel: sympy.Expr, buffers: Iterable[Union[ir.Buffer, ir.TensorBox, ir.TorchBindObject, ir.IRNode]]) -> bool:
    int_max = torch.iinfo(torch.int32).max
    if not expr_fits_within_32bit(numel):
        return False
    buf_sizes = [buf.get_layout().storage_size() for buf in buffers if buf.has_tensor_output()]
    for buf in buffers:
        if not buf.has_tensor_output() and isinstance(buf, ir.MutationOutput):
            mutated_bufs = buf.get_mutation_buffers()
            buf_sizes += [buf.get_layout().storage_size() for buf in mutated_bufs if buf.has_tensor_output()]
    if <MASK>:
        return False
    V.graph.sizevars.check_leq(numel, int_max)
    for size in buf_sizes:
        V.graph.sizevars.check_leq(size, int_max)
    return True

def extract_system_builds(filepath):
    """Extract the 'name' argument of all rules with a system_build_file argument."""
    lib_names = []
    system_build_files = []
    current_name = None
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if <MASK>:
                current_name = line[7:-1].strip('"')
            elif line.startswith('system_build_file = '):
                lib_names.append(current_name)
                system_build_spec = line.split('=')[-1].split('"')[1]
                assert system_build_spec.startswith('//')
                system_build_files.append(system_build_spec[2:].replace(':', os.sep))
    return (lib_names, system_build_files)

def find_triton_kernels(fn: Callable[..., Any]) -> list[object]:
    try:
        source = inspect.getsource(fn)
    except (OSError, TypeError):
        return []
    from torch._inductor.utils import IndentedBuffer
    buffer = IndentedBuffer()
    buffer.splice(source, strip=True)
    tree = ast.parse(buffer.getrawvalue())

    class Visitor(ast.NodeVisitor):

        def __init__(self) -> None:
            self.triton_kernels: list[Any] = []

        def visit_Call(self, node: ast.Call) -> None:
            triton_func_names = ('capture_triton', 'wrap_triton')
            if isinstance(node.func, ast.Attribute):
                attr = node.func
                if isinstance(attr.value, ast.Attribute) and isinstance(attr.value.value, ast.Name) and (attr.value.value.id == 'torch') and (attr.value.attr == '_library') and (attr.attr in triton_func_names):
                    if <MASK>:
                        self.triton_kernels.append(node.args[0].id)
            elif isinstance(node.func, ast.Name):
                if node.func.id in triton_func_names:
                    if node.args and isinstance(node.args[0], ast.Name):
                        self.triton_kernels.append(node.args[0].id)
            self.generic_visit(node)
    collector = Visitor()
    collector.visit(tree)
    closure_vars = inspect.getclosurevars(fn)
    resolved = []
    for name in collector.triton_kernels:
        if name in closure_vars.nonlocals:
            resolved.append(closure_vars.nonlocals[name])
        elif name in closure_vars.globals:
            resolved.append(closure_vars.globals[name])
        elif name in closure_vars.builtins:
            resolved.append(closure_vars.builtins[name])
    return resolved

def iter_contains(items: Iterable[Any], search: Any, tx: InstructionTranslator, check_tensor_identity: bool=False) -> Any:
    from .variables import BuiltinVariable, ConstantVariable, TensorVariable
    if <MASK>:
        found_const = any((x.is_python_constant() and x.as_python_constant() == search.as_python_constant() for x in items))
        return ConstantVariable.create(found_const)
    must_check_tensor_id = False
    if check_tensor_identity and isinstance(search, TensorVariable):
        must_check_tensor_id = True
        search = _get_fake_tensor(search)
    found: Optional[VariableTracker] = None
    for x in items:
        if must_check_tensor_id:
            if isinstance(x, TensorVariable):
                if search is _get_fake_tensor(x):
                    return ConstantVariable.create(True)
        else:
            check = BuiltinVariable(operator.eq).call_function(tx, [x, search], {})
            if found is None:
                found = check
            else:
                found = BuiltinVariable(operator.or_).call_function(tx, [check, found], {})
    if found is None:
        found = ConstantVariable.create(False)
    return found

