def calc_info(self):
    lib_dirs = self.get_lib_dirs()
    info = {}
    opt = self.get_option_single('atlas_libs', 'libraries')
    atlas_libs = self.get_libs(opt, self._lib_names + self._lib_atlas)
    lapack_libs = self.get_libs('lapack_libs', self._lib_lapack)
    atlas = None
    lapack = None
    atlas_1 = None
    for d in lib_dirs:
        atlas = self.check_libs2(d, atlas_libs, [])
        if atlas is not None:
            lib_dirs2 = [d] + self.combine_paths(d, ['atlas*', 'ATLAS*'])
            lapack = self.check_libs2(lib_dirs2, lapack_libs, [])
            if lapack is not None:
                break
        if atlas:
            atlas_1 = atlas
    log.info(self.__class__)
    if <MASK>:
        atlas = atlas_1
    if atlas is None:
        return
    include_dirs = self.get_include_dirs()
    h = self.combine_paths(lib_dirs + include_dirs, 'cblas.h') or [None]
    h = h[0]
    if h:
        h = os.path.dirname(h)
        dict_append(info, include_dirs=[h])
    info['language'] = 'c'
    if lapack is not None:
        dict_append(info, **lapack)
        dict_append(info, **atlas)
    elif 'lapack_atlas' in atlas['libraries']:
        dict_append(info, **atlas)
        dict_append(info, define_macros=[('ATLAS_WITH_LAPACK_ATLAS', None)])
        self.set_info(**info)
        return
    else:
        dict_append(info, **atlas)
        dict_append(info, define_macros=[('ATLAS_WITHOUT_LAPACK', None)])
        message = textwrap.dedent('\n                *********************************************************************\n                    Could not find lapack library within the ATLAS installation.\n                *********************************************************************\n                ')
        warnings.warn(message, stacklevel=2)
        self.set_info(**info)
        return
    lapack_dir = lapack['library_dirs'][0]
    lapack_name = lapack['libraries'][0]
    lapack_lib = None
    lib_prefixes = ['lib']
    if sys.platform == 'win32':
        lib_prefixes.append('')
    for e in self.library_extensions():
        for prefix in lib_prefixes:
            fn = os.path.join(lapack_dir, prefix + lapack_name + e)
            if os.path.exists(fn):
                lapack_lib = fn
                break
        if lapack_lib:
            break
    if lapack_lib is not None:
        sz = os.stat(lapack_lib)[6]
        if sz <= 4000 * 1024:
            message = textwrap.dedent('\n                    *********************************************************************\n                        Lapack library (from ATLAS) is probably incomplete:\n                          size of %s is %sk (expected >4000k)\n\n                        Follow the instructions in the KNOWN PROBLEMS section of the file\n                        numpy/INSTALL.txt.\n                    *********************************************************************\n                    ') % (lapack_lib, sz / 1024)
            warnings.warn(message, stacklevel=2)
        else:
            info['language'] = 'f77'
    (atlas_version, atlas_extra_info) = get_atlas_version(**atlas)
    dict_append(info, **atlas_extra_info)
    self.set_info(**info)

def profile_model(args, model, inputs, rank):
    with profile(activities=[ProfilerActivity.CPU, ProfilerActivity.CUDA]) as prof:
        for i in range(args.repeat):
            with record_function('Forward'):
                outputs = model(*inputs)
                loss = reduce_to_scalar_loss(outputs)
            with record_function('Backward'):
                loss.backward()
    if <MASK>:
        prof.export_chrome_trace(args.trace_file)

def formatargvalues(args, varargs, varkw, locals, formatarg=str, formatvarargs=lambda name: '*' + name, formatvarkw=lambda name: '**' + name, formatvalue=lambda value: '=' + repr(value), join=joinseq):
    """Format an argument spec from the 4 values returned by getargvalues.

    The first four arguments are (args, varargs, varkw, locals).  The
    next four arguments are the corresponding optional formatting functions
    that are called to turn names and values into strings.  The ninth
    argument is an optional function to format the sequence of arguments.

    """

    def convert(name, locals=locals, formatarg=formatarg, formatvalue=formatvalue):
        return formatarg(name) + formatvalue(locals[name])
    specs = [strseq(arg, convert, join) for arg in args]
    if <MASK>:
        specs.append(formatvarargs(varargs) + formatvalue(locals[varargs]))
    if varkw:
        specs.append(formatvarkw(varkw) + formatvalue(locals[varkw]))
    return '(' + ', '.join(specs) + ')'

