def integer_repr(x):
    """Return the signed-magnitude interpretation of the binary representation
    of x."""
    import numpy as np
    if x.dtype == np.float16:
        return _integer_repr(x, np.int16, np.int16(-2 ** 15))
    elif x.dtype == np.float32:
        return _integer_repr(x, np.int32, np.int32(-2 ** 31))
    elif <MASK>:
        return _integer_repr(x, np.int64, np.int64(-2 ** 63))
    else:
        raise ValueError(f'Unsupported dtype {x.dtype}')

@bp.route('/register', methods=('GET', 'POST'))
def register():
    """Register a new user.

    Validates that the username is not already taken. Hashes the
    password for security.
    """
    if <MASK>:
        username = request.form['username']
        password = request.form['password']
        db = get_db()
        error = None
        if not username:
            error = 'Username is required.'
        elif not password:
            error = 'Password is required.'
        if error is None:
            try:
                db.execute('INSERT INTO user (username, password) VALUES (?, ?)', (username, generate_password_hash(password)))
                db.commit()
            except db.IntegrityError:
                error = f'User {username} is already registered.'
            else:
                return redirect(url_for('auth.login'))
        flash(error)
    return render_template('auth/register.html')

def _cmpkey(epoch: int, release: Tuple[int, ...], pre: Optional[Tuple[str, int]], post: Optional[Tuple[str, int]], dev: Optional[Tuple[str, int]], local: Optional[LocalType]) -> CmpKey:
    _release = tuple(reversed(list(itertools.dropwhile(lambda x: x == 0, reversed(release)))))
    if pre is None and post is None and (dev is not None):
        _pre: CmpPrePostDevType = NegativeInfinity
    elif <MASK>:
        _pre = Infinity
    else:
        _pre = pre
    if post is None:
        _post: CmpPrePostDevType = NegativeInfinity
    else:
        _post = post
    if dev is None:
        _dev: CmpPrePostDevType = Infinity
    else:
        _dev = dev
    if local is None:
        _local: CmpLocalType = NegativeInfinity
    else:
        _local = tuple(((i, '') if isinstance(i, int) else (NegativeInfinity, i) for i in local))
    return (epoch, _release, _pre, _post, _dev, _local)

def forward(self, input, hx=None):
    """
        Runs the forward pass.
        """
    self._update_flat_weights()
    num_directions = 2 if self.bidirectional else 1
    orig_input = input
    if isinstance(orig_input, PackedSequence):
        (input, batch_sizes, sorted_indices, unsorted_indices) = input
        max_batch_size = batch_sizes[0]
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    else:
        batch_sizes = None
        if input.dim() not in (2, 3):
            raise ValueError(f'RNN: Expected input to be 2D or 3D, got {input.dim()}D tensor instead')
        is_batched = input.dim() == 3
        batch_dim = 0 if self.batch_first else 1
        if not is_batched:
            input = input.unsqueeze(batch_dim)
            if hx is not None:
                if <MASK>:
                    raise RuntimeError(f'For unbatched 2-D input, hx should also be 2-D but got {hx.dim()}-D tensor')
                hx = hx.unsqueeze(1)
        elif hx is not None and hx.dim() != 3:
            raise RuntimeError(f'For batched 3-D input, hx should also be 3-D but got {hx.dim()}-D tensor')
        max_batch_size = input.size(0) if self.batch_first else input.size(1)
        sorted_indices = None
        unsorted_indices = None
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    assert hx is not None
    self.check_forward_args(input, hx, batch_sizes)
    assert self.mode == 'RNN_TANH' or self.mode == 'RNN_RELU'
    if batch_sizes is None:
        if self.mode == 'RNN_TANH':
            result = _VF.rnn_tanh(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
        else:
            result = _VF.rnn_relu(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
    elif self.mode == 'RNN_TANH':
        result = _VF.rnn_tanh(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    else:
        result = _VF.rnn_relu(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    output = result[0]
    hidden = result[1]
    if isinstance(orig_input, PackedSequence):
        output_packed = PackedSequence(output, batch_sizes, sorted_indices, unsorted_indices)
        return (output_packed, self.permute_hidden(hidden, unsorted_indices))
    if not is_batched:
        output = output.squeeze(batch_dim)
        hidden = hidden.squeeze(1)
    return (output, self.permute_hidden(hidden, unsorted_indices))

def _align_frame(self, indexer, df: DataFrame) -> DataFrame:
    is_frame = self.ndim == 2
    if isinstance(indexer, tuple):
        (idx, cols) = (None, None)
        sindexers = []
        for (i, ix) in enumerate(indexer):
            ax = self.obj.axes[i]
            if is_sequence(ix) or isinstance(ix, slice):
                if <MASK>:
                    ix = ix.reshape(-1)
                if idx is None:
                    idx = ax[ix]
                elif cols is None:
                    cols = ax[ix]
                else:
                    break
            else:
                sindexers.append(i)
        if idx is not None and cols is not None:
            if df.index.equals(idx) and df.columns.equals(cols):
                val = df.copy()
            else:
                val = df.reindex(idx, columns=cols)
            return val
    elif (isinstance(indexer, slice) or is_list_like_indexer(indexer)) and is_frame:
        ax = self.obj.index[indexer]
        if df.index.equals(ax):
            val = df.copy()
        else:
            if isinstance(ax, MultiIndex) and isinstance(df.index, MultiIndex) and (ax.nlevels != df.index.nlevels):
                raise TypeError('cannot align on a multi-index with out specifying the join levels')
            val = df.reindex(index=ax)
        return val
    raise ValueError('Incompatible indexer with DataFrame')

