def deserialize_metadata(self, metadata: dict[str, str]) -> dict[str, Any]:
    ret: dict[str, Any] = {}
    if (stack_trace := metadata.get('stack_trace')):
        ret['stack_trace'] = stack_trace

    def deserialize_meta_func(serialized_target: str):
        module = None
        if <MASK>:
            module = torch.nn
            serialized_target_names = serialized_target.split('.')[2:]
        elif serialized_target.startswith('torch'):
            module = torch
            serialized_target_names = serialized_target.split('.')[1:]
        else:
            return self.deserialize_operator(serialized_target)
        target = module
        for name in serialized_target_names:
            if not hasattr(target, name):
                return serialized_target
            else:
                target = getattr(target, name)
        return target
    if (nn_module_stack_str := metadata.get('nn_module_stack')):

        def import_nn_module_stack(key, path, ty):
            return (key, (path, ty))

        def metadata_split(metadata):
            out = []
            (start, n) = (0, 0)
            (a, b) = ('[(', ')]')
            for (end, c) in enumerate(metadata):
                if c in a:
                    n += 1
                elif c in b:
                    n -= 1
                elif c == ',' and n == 0:
                    out.append(metadata[start:end])
                    start = end + 1
            out.append(metadata[start:])
            assert len(out) == 3
            return out
        nn_module_stack = dict((import_nn_module_stack(*metadata_split(item)) for item in nn_module_stack_str.split(ST_DELIMITER)))
        ret['nn_module_stack'] = nn_module_stack
    if (source_fn_st_str := metadata.get('source_fn_stack')):
        source_fn_st = []
        for source_fn_str in source_fn_st_str.split(ST_DELIMITER):
            (name, target_str) = source_fn_str.split(',')
            source_fn_st.append((name, deserialize_meta_func(target_str)))
        ret['source_fn_stack'] = source_fn_st
    if (torch_fn_str := metadata.get('torch_fn')):
        ret['torch_fn'] = tuple(torch_fn_str.split(ST_DELIMITER))
    if (custom_str := metadata.get('custom')):
        ret['custom'] = json.loads(custom_str)
    return ret

def compare_outputs(original, reference, match_what):
    all_ok = True
    for (i, (orig, ref)) in enumerate(zip(original, reference)):
        try:
            if orig.is_quantized:
                orig = orig.dequantize()
            if ref.is_quantized:
                ref = ref.dequantize()
            if orig.is_mkldnn:
                orig = orig.to_dense()
            if ref.is_mkldnn:
                ref = ref.to_dense()
            if ref.is_complex() or orig.is_complex():
                torch.testing.assert_close(orig.to(torch.cdouble), ref.to(torch.cdouble), rtol=check_tolerance, atol=default_tolerances(orig, ref)[1], equal_nan=True)
            elif orig.is_mps or ref.is_mps:
                torch.testing.assert_close(orig.float(), ref.float(), rtol=check_tolerance, atol=default_tolerances(orig, ref)[1], equal_nan=True)
            elif <MASK>:
                assert getattr(orig, 'is_nested', None) == getattr(ref, 'is_nested', None)
                for (t_orig, t_ref) in zip(orig.unbind(), ref.unbind()):
                    torch.testing.assert_close(t_orig.double(), t_ref.double(), rtol=check_tolerance, atol=default_tolerances(t_orig, t_ref)[1], equal_nan=True)
            else:
                torch.testing.assert_close(orig.double(), ref.double(), rtol=check_tolerance, atol=default_tolerances(orig, ref)[1], equal_nan=True)
        except AssertionError as e:
            maybe_warn_nondeterministic()
            warnings.warn('Output nr ' + str(i + 1) + '. of the traced function does not match the corresponding output of the ' + match_what + '. Detailed error:\n' + str(e), category=TracerWarning, stacklevel=4)
            all_ok = False
    return all_ok

def _extract_archive(file_path, path='.', archive_format='auto'):
    """Extracts an archive if it matches tar, tar.gz, tar.bz, or zip formats.

  Args:
      file_path: path to the archive file
      path: path to extract the archive file
      archive_format: Archive format to try for extracting the file.
          Options are 'auto', 'tar', 'zip', and None.
          'tar' includes tar, tar.gz, and tar.bz files.
          The default 'auto' is ['tar', 'zip'].
          None or an empty list will return no matches found.

  Returns:
      True if a match was found and an archive extraction was completed,
      False otherwise.
  """
    if archive_format is None:
        return False
    if archive_format == 'auto':
        archive_format = ['tar', 'zip']
    if isinstance(archive_format, str):
        archive_format = [archive_format]
    file_path = path_to_string(file_path)
    path = path_to_string(path)
    for archive_type in archive_format:
        if archive_type == 'tar':
            open_fn = tarfile.open
            is_match_fn = tarfile.is_tarfile
        if archive_type == 'zip':
            open_fn = zipfile.ZipFile
            is_match_fn = zipfile.is_zipfile
        if is_match_fn(file_path):
            with open_fn(file_path) as archive:
                try:
                    archive.extractall(path)
                except (tarfile.TarError, RuntimeError, KeyboardInterrupt):
                    if <MASK>:
                        if os.path.isfile(path):
                            os.remove(path)
                        else:
                            shutil.rmtree(path)
                    raise
            return True
    return False

