    return True

@classmethod
def _from_sequence_of_strings(cls, strings: list[str], *, dtype: ExtensionDtype, copy: bool=False, true_values: list[str] | None=None, false_values: list[str] | None=None, none_values: list[str] | None=None) -> BooleanArray:
    true_values_union = cls._TRUE_VALUES.union(true_values or [])
    false_values_union = cls._FALSE_VALUES.union(false_values or [])
    if none_values is None:
        none_values = []

    def map_string(s) -> bool | None:
        if s in true_values_union:
            return True
        elif <MASK>:
            return False
        elif s in none_values:
            return None
        else:
            raise ValueError(f'{s} cannot be cast to bool')
    scalars = np.array(strings, dtype=object)
    mask = isna(scalars)
    scalars[~mask] = list(map(map_string, scalars[~mask]))
    return cls._from_sequence(scalars, dtype=dtype, copy=copy)

def _write(self, index, value):
    """Writes `value` into index named by `index`.

    Args:
      index: 0-D.  int32 scalar with the index to write to.
      value: N-D.  Tensor of type `dtype`.  The `Tensor` to write to `index`.

    Raises:
      errors_impl.InvalidArgumentError: `value` dtype does not match dtype.
      errors_impl.OutOfRangeError: `index` is out of bounds.
      ValueError: shape of `value` is not consistent with inferred shape.
    """
    if isinstance(index, ops.EagerTensor):
        index = index.numpy()
    if index < 0:
        raise errors_impl.OutOfRangeError(None, None, 'Writing to negative indices (index %d) is not allowed.' % index)
    size = len(self._tensor_array)
    if index >= size:
        if <MASK>:
            raise errors_impl.OutOfRangeError(None, None, 'Tried to write to index %d but array is not resizeable and size is: %d ' % (index, size))
        self._tensor_array.extend((None for _ in range(index - size + 1)))
    if not isinstance(value, ops.EagerTensor):
        value = ops.convert_to_tensor(value, preferred_dtype=self._dtype, name='value')
    if self._dtype != value.dtype:
        raise errors_impl.InvalidArgumentError(None, None, 'TensorArray dtype is %s but Op is trying to write dtype %s ' % (self._dtype.name, value.dtype.name))
    if not self._element_shape.is_compatible_with(value.shape):
        raise ValueError('Incompatible shape for value (%s), expected (%s)' % (value.shape, self._element_shape))
    if self._infer_shape:
        self._element_shape = self._element_shape.merge_with(value.shape)
    self._tensor_array[index] = value

def _validate_args_if_ragged(self, is_ragged_input, mask):
    if not is_ragged_input:
        return
    if <MASK>:
        raise ValueError('The mask that was passed in was ' + str(mask) + ' and cannot be applied to RaggedTensor inputs. Please make sure that there is no mask passed in by upstream layers.')
    if self.unroll:
        raise ValueError('The input received contains RaggedTensors and does not support unrolling. Disable unrolling by passing `unroll=False` in the RNN Layer constructor.')

def assertAllFused(self, graph, except_for=()):

    def get_nodes_and_parents_recursively(block, kind, acc):
        for node in block.nodes():
            if <MASK>:
                acc[block].append(node)
            elif node.kind() == 'prim::DifferentiableGraph':
                get_nodes_and_parents_recursively(node.g('Subgraph'), kind, acc)
            elif node.kind() == 'prim::If' and (node.inputs().__next__().node().kind() == 'aten::all' or node.inputs().__next__().node().kind() == 'prim::TypeCheck' or node.inputs().__next__().node().kind() == 'prim::RequiresGradCheck'):
                get_nodes_and_parents_recursively(node.blocks().__next__(), kind, acc)
            else:
                for inner_block in node.blocks():
                    get_nodes_and_parents_recursively(inner_block, kind, acc)
    allowed_nodes = {'prim::Constant', FUSION_GROUP, 'prim::BailoutTemplate', 'prim::TupleConstruct', 'prim::If', 'prim::TypeCheck', 'prim::RequiresGradCheck'} | set(except_for)
    fusion_groups: dict[torch._C.Block, list[torch._C.Node]] = defaultdict(list)
    get_nodes_and_parents_recursively(graph, FUSION_GROUP, fusion_groups)
    self.assertTrue(len(fusion_groups) == 1, f'got {graph}')
    (graph, fusion_nodes) = next(iter(fusion_groups.items()))
    self.assertTrue(len(fusion_nodes) == 1, f'got {graph}')
    self.assertTrue(all((node.kind() in allowed_nodes for node in graph.nodes())), f'got {graph}')

def _maybe_partial_apply_variables(fn, args, kwargs):
    """Inspects arguments to partially apply any DistributedVariable.

  This avoids an automatic cast of the current variable value to tensor.

  Note that a variable may be captured implicitly with Python scope instead of
  passing it to run(), but supporting run() keeps behavior consistent
  with MirroredStrategy.

  Since positional arguments must be applied from left to right, this function
  does some tricky function inspection to move variable positional arguments
  into kwargs. As a result of this, we can't support passing Variables as *args,
  nor as args to functions which combine both explicit positional arguments and
  *args.

  Args:
    fn: The function to run, as passed to run().
    args: Positional arguments to fn, as passed to run().
    kwargs: Keyword arguments to fn, as passed to run().

  Returns:
    A tuple of the function (possibly wrapped), args, kwargs (both
    possibly filtered, with members of args possibly moved to kwargs).
    If no variables are found, this function is a noop.

  Raises:
    ValueError: If the function signature makes unsupported use of *args, or if
      too many arguments are passed.
  """

    def is_distributed_var(x):
        flat = nest.flatten(x)
        return flat and isinstance(flat[0], values.DistributedVariable)
    var_kwargs = {}
    nonvar_kwargs = {}
    if kwargs:
        var_kwargs = {k: v for (k, v) in kwargs.items() if is_distributed_var(v)}
    if <MASK>:
        nonvar_kwargs = {k: v for (k, v) in kwargs.items() if not is_distributed_var(v)}
    positional_args = []
    index_of_star_args = None
    for (i, p) in enumerate(tf_inspect.signature(fn).parameters.values()):
        if i == 0 and p.name == 'self':
            continue
        if p.kind == tf_inspect.Parameter.POSITIONAL_OR_KEYWORD:
            positional_args.append(p.name)
        elif p.kind == tf_inspect.Parameter.VAR_POSITIONAL:
            index_of_star_args = i
        elif p.kind == tf_inspect.Parameter.POSITIONAL_ONLY:
            if var_kwargs or any((is_distributed_var(a) for a in args)):
                raise ValueError(f'Mixing Variables and positional-only parameters not supported by TPUStrategy. Received {len(var_kwargs)} DistributedVariables in **kwargs and {sum((is_distributed_var(a) for a in args))} in *args, expected zero for both.')
            return (fn, args, kwargs)
    star_args = []
    have_seen_var_arg = False
    for (i, a) in enumerate(args):
        if is_distributed_var(a):
            if index_of_star_args is not None and i >= index_of_star_args:
                raise ValueError('TPUStrategy.run() cannot handle Variables passed to *args. Either name the function argument, or capture the Variable implicitly.')
            if len(positional_args) <= i:
                raise ValueError('Too many positional arguments passed to call to TPUStrategy.run().')
            var_kwargs[positional_args[i]] = a
            have_seen_var_arg = True
        else:
            if index_of_star_args is not None and i >= index_of_star_args:
                if have_seen_var_arg:
                    raise ValueError('TPUStrategy.run() cannot handle both Variables and a mix of positional args and *args. Either remove the *args, or capture the Variable implicitly.')
                else:
                    star_args.append(a)
                    continue
            if len(positional_args) <= i:
                raise ValueError('Too many positional arguments passed to call to TPUStrategy.run().')
            nonvar_kwargs[positional_args[i]] = a
    if var_kwargs:
        return (functools.partial(fn, **var_kwargs), star_args, nonvar_kwargs)
    return (fn, args, kwargs)

def wrapper(func):

    @wraps(func)
    def inner(*args, **kwargs):
        if <MASK>:
            update_kwargs = lambda i: dict(kwargs, **kwargs_list[i])
        else:
            update_kwargs = lambda i: kwargs
        threads = []
        for i in range(num_threads):
            updated_kwargs = update_kwargs(i)
            thread = threading.Thread(target=func, args=args, kwargs=updated_kwargs)
            threads.append(thread)
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
    return inner

def _format_header_mi(self) -> Iterable[ExcelCell]:
    if self.columns.nlevels > 1:
        if not self.index:
            raise NotImplementedError("Writing to Excel with MultiIndex columns and no index ('index'=False) is not yet implemented.")
    if not (self._has_aliases or self.header):
        return
    columns = self.columns
    merge_columns = self.merge_cells in {True, 'columns'}
    level_strs = columns._format_multi(sparsify=merge_columns, include_names=False)
    level_lengths = get_level_lengths(level_strs)
    coloffset = 0
    lnum = 0
    if <MASK>:
        coloffset = self.df.index.nlevels - 1
    for (lnum, name) in enumerate(columns.names):
        yield ExcelCell(row=lnum, col=coloffset, val=name, style=None)
    for (lnum, (spans, levels, level_codes)) in enumerate(zip(level_lengths, columns.levels, columns.codes, strict=True)):
        values = levels.take(level_codes)
        for (i, span_val) in spans.items():
            (mergestart, mergeend) = (None, None)
            if merge_columns and span_val > 1:
                (mergestart, mergeend) = (lnum, coloffset + i + span_val)
            yield CssExcelCell(row=lnum, col=coloffset + i + 1, val=values[i], style=None, css_styles=getattr(self.styler, 'ctx_columns', None), css_row=lnum, css_col=i, css_converter=self.style_converter, mergestart=mergestart, mergeend=mergeend)
    self.rowcounter = lnum

def assertAllEqual(self, a, b, msg=None):
    if not (isinstance(a, structured_tensor.StructuredTensor) or isinstance(b, structured_tensor.StructuredTensor)):
        return super(StructuredTensorTest, self).assertAllEqual(a, b, msg)
    if <MASK>:
        a = structured_tensor.StructuredTensor.from_pyval(a)
        self._assertStructuredEqual(a, b, msg, False)
    elif not isinstance(b, structured_tensor.StructuredTensor):
        b = structured_tensor.StructuredTensor.from_pyval(b)
        self._assertStructuredEqual(a, b, msg, False)
    else:
        self._assertStructuredEqual(a, b, msg, True)

def _set_metric_attributes(self):
    """Sets the metric attributes on the model for all the model outputs."""
    updated_per_output_metrics = []
    updated_per_output_weighted_metrics = []
    for (i, endpoint) in enumerate(self._training_endpoints):
        if <MASK>:
            updated_per_output_metrics.append(self._per_output_metrics[i])
            updated_per_output_weighted_metrics.append(self._per_output_weighted_metrics[i])
            continue
        updated_per_output_metrics.append(self._set_per_output_metric_attributes(self._per_output_metrics[i], i))
        updated_per_output_weighted_metrics.append(self._set_per_output_metric_attributes(self._per_output_weighted_metrics[i], i))
    if len(self._training_endpoints) > 1:
        for endpoint in self._training_endpoints:
            if not endpoint.should_skip_target():
                endpoint.output_loss_metric = metrics_module.Mean(name=endpoint.loss_name())
    self._per_output_metrics = updated_per_output_metrics
    self._per_output_weighted_metrics = updated_per_output_weighted_metrics

def __init__(self, remote_device: Union[str, torch.device]):
    PARSE_ERROR = f"Could not parse remote_device: {remote_device}. The valid format is '<workername>/<device>' or 'rank:<rank>/<device>' or '<device>'"
    self._worker_name = None
    self._rank = None
    self._device: Optional[Union[str, int, torch.device]] = None
    if isinstance(remote_device, torch.device):
        self._device = remote_device
    elif isinstance(remote_device, str):
        fields = remote_device.split('/')
        if len(fields) == 2:
            (self._worker_name, self._device) = fields
        elif len(fields) == 1:
            if _remote_device._is_valid_local_device(fields[0]):
                self._device = fields[0]
            else:
                self._worker_name = fields[0]
                self._device = 'cpu'
        else:
            raise ValueError(PARSE_ERROR)
    else:
        raise TypeError(f'Invalid type for remote_device: {type(remote_device)}')
    if self._worker_name is not None and (not self._worker_name):
        raise ValueError(PARSE_ERROR)
    self._device = torch.device(self._device)
    if <MASK>:
        fields = self._worker_name.split(':')
        if len(fields) == 2:
            if fields[0] == 'rank' and fields[1].isdigit():
                self._rank = int(fields[1])
                self._worker_name = None
            else:
                raise ValueError(PARSE_ERROR)
        elif len(fields) > 2:
            raise ValueError(PARSE_ERROR)

def restore_from_strided_representation(args):
    """Restore non-strided differentiable tensosr from their strided representations."""
    new_args = []
    args = list(args)
    while args:
        a = args.pop(0)
        if <MASK>:
            (d, values) = (args.pop(0), args.pop(0))
            if d['layout'] is torch.sparse_coo:
                a = torch.sparse_coo_tensor(d['indices'], values, size=d['shape'], is_coalesced=d['is_coalesced'])
            elif d['layout'] in sparse_compressed_layouts:
                a = torch.sparse_compressed_tensor(d['compressed_indices'], d['plain_indices'], values, size=d['shape'], layout=d['layout'])
            else:
                raise NotImplementedError(f"conversion of {d['layout']} strided representation to tensor")
        new_args.append(a)
    return tuple(new_args)

@_onnx_symbolic('prim::ListUnpack')
def prim_list_unpack(g: jit_utils.GraphContext, *inputs, **kwargs) -> list[_C.Value] | None:
    if <MASK>:
        return symbolic_helper._unpack_list(inputs[0])
    return None

def is_fake_tensor_same(new, old, *, node):
    if type(new) is not type(old):
        return False
    if isinstance(new, (list, tuple)):
        if <MASK>:
            return False
        return all((is_fake_tensor_same(new_i, old_i, node=node) for (new_i, old_i) in zip(new, old)))
    if new is None:
        return old is None
    if not isinstance(new, torch.Tensor):
        assert isinstance(new, (torch.SymInt, torch.SymBool, torch.SymFloat)), f'Unknown type {type(new)} in {self.graph}'
        return new.node.shape_env._maybe_evaluate_static(sympy.Eq(new.node.expr, old.node.expr)) == sympy.true
    if not is_intlist_same(new.shape, old.shape) or new.layout != old.layout:
        return False
    if new.layout == torch.strided and (not is_intlist_same(new.stride(), old.stride()) or not statically_known_true(new.storage_offset() == old.storage_offset())):
        return False
    if new.device != old.device:
        return False
    if get_storage(new) == get_storage(old):
        return True

    def any_user_may_alias(node):
        if not isinstance(node.meta['val'], torch.Tensor):
            return True
        for user in node.users:
            if not (isinstance(user.target, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)) or user.target == torch._inductor.fx_passes.reinplace._generalized_scatter):
                return True
            if isinstance(user.target, torch._ops.HigherOrderOperator):
                continue
            (is_valid, args, kwargs) = get_fake_args_kwargs(user)
            if not is_valid:
                return True
            with V.fake_mode, enable_python_dispatcher(), contextlib.ExitStack() as stack:
                shape_env = V.fake_mode.shape_env
                if shape_env is not None:
                    stack.enter_context(shape_env.ignore_fresh_unbacked_symbols())
                new_fake_tensor = user.target(*args, **kwargs)
            if not isinstance(new_fake_tensor, torch.Tensor):
                return True
            if get_storage(new_fake_tensor) == get_storage(node.meta['val']):
                return True
        return False
    if existing_storages[get_storage(old)] == 1 and get_storage(new) not in existing_storages and (not any_user_may_alias(node)):
        return True
    return False

def _save_state_dict(state_dict: STATE_DICT_TYPE, storage_writer: StorageWriter, process_group: Optional[dist.ProcessGroup]=None, coordinator_rank: int=0, no_dist: bool=False, planner: Optional[SavePlanner]=None, use_collectives: bool=True) -> Metadata:
    torch._C._log_api_usage_once('torch.distributed.checkpoint.save_state_dict')
    distW = _DistWrapper(process_group, not no_dist, coordinator_rank)
    if <MASK>:
        planner = DefaultSavePlanner()
    if planner is None:
        raise AssertionError('planner is None')
    global_metadata = None
    ckpt_kwargs = {}
    if (ckpt_id := getattr(storage_writer, 'checkpoint_id', None)) is not None:
        ckpt_kwargs['checkpoint_id'] = ckpt_id
        ckpt_kwargs['process_group'] = distW.group

    @_dcp_method_logger(**ckpt_kwargs)
    def local_step():
        if planner is None:
            raise AssertionError('planner is None')
        storage_meta = storage_writer.storage_meta()
        if 'storage_meta' not in inspect.signature(planner.set_up_planner).parameters:
            warnings.warn('The function definition for SavePlanner.set_up_planner has been updated to include the storage_meta argument. Please update your implementation to include this parameter.')
            planner.set_up_planner(state_dict, distW.is_coordinator)
        else:
            planner.set_up_planner(state_dict=state_dict, storage_meta=storage_meta, is_coordinator=distW.is_coordinator)
        if 'kwargs' in inspect.signature(storage_writer.set_up_storage_writer).parameters:
            storage_writer.set_up_storage_writer(distW.is_coordinator, rank=distW.rank, use_collectives=use_collectives)
        else:
            storage_writer.set_up_storage_writer(distW.is_coordinator)
        local_plan = planner.create_local_plan()
        local_plan = storage_writer.prepare_local_plan(local_plan)
        return local_plan

    @_dcp_method_logger(**ckpt_kwargs)
    def global_step(all_local_plans):
        nonlocal global_metadata
        if planner is None:
            raise AssertionError('planner is None')
        (all_local_plans, global_metadata) = planner.create_global_plan(all_local_plans)
        all_local_plans = storage_writer.prepare_global_plan(all_local_plans)
        return all_local_plans
    central_plan: Optional[SavePlan] = None
    if use_collectives:
        central_plan = distW.reduce_scatter('plan', local_step, global_step)
    else:
        local_plan: SavePlan = local_step()
        global_plan: list[SavePlan] = global_step([local_plan])
        central_plan = global_plan[0]

    @_dcp_method_logger(**ckpt_kwargs)
    def write_data():
        if planner is None:
            raise AssertionError('planner is None')
        if central_plan is None:
            raise AssertionError('central_plan is None')
        final_local_plan = planner.finish_plan(central_plan)
        all_writes = storage_writer.write_data(final_local_plan, planner)
        all_writes.wait()
        return all_writes.value()

    @_dcp_method_logger(**ckpt_kwargs)
    def finish_checkpoint(all_results):
        if global_metadata is None:
            raise AssertionError('global_metadata is None')
        storage_writer.finish(metadata=global_metadata, results=all_results)
        return global_metadata
    if use_collectives:
        metadata = distW.all_reduce('write', write_data, finish_checkpoint)
    else:
        write_results: list[WriteResult] = write_data()
        metadata = finish_checkpoint([write_results])
        distW.barrier()
    return metadata

def patch_config(config_patches: dict[str, Any], config_name: str, config_value: Any) -> None:
    value = config_patches.get(config_name, getattr(config, config_name))
    if value is None:
        config_patches[config_name] = config_value
    elif <MASK>:
        raise RuntimeError(f'Invalid config: {config_name}={config_value} when aot_inductor_mode.compile_standalone is True.')

@compatibility(is_backward_compatible=True)
def create_arg(self, a: Any) -> Argument:
    """
        A method that lowers the objects seen as arguments during symbolic evaluation
        into Argument types that can be stored in IR.

        Can be override to support more trace-specific types.
        """
    handler = _create_arg_bypass.get(type(a))
    if handler is not None:
        return handler(self, a)
    if isinstance(a, Proxy):
        return a.node
    elif hasattr(a, '__fx_create_arg__'):
        return a.__fx_create_arg__(self)
    elif isinstance(a, tuple):
        if hasattr(a, '_fields'):
            args = [self.create_arg(elem) for elem in a]
            return type(a)(*args)
        return type(a)([self.create_arg(elem) for elem in a])
    elif isinstance(a, list):
        return [self.create_arg(elem) for elem in a]
    elif isinstance(a, dict):
        return _create_arg_dict(self, a)
    elif <MASK>:
        return slice(self.create_arg(a.start), self.create_arg(a.stop), self.create_arg(a.step))
    elif isinstance(a, range):
        return range(self.create_arg(a.start), self.create_arg(a.stop), self.create_arg(a.step))
    elif isinstance(a, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)):
        return a
    elif is_dataclass(a):
        kwargs = {field.name: self.create_arg(getattr(a, field.name)) for field in fields(a)}
        return self.create_node('call_function', a.__class__, (), kwargs)
    elif isinstance(a, (*base_types, enum.Enum)) or a is None or a is ...:
        return a
    raise NotImplementedError(f'argument of type: {type(a)}')

def lookup_jagged(func, *args, **kwargs) -> Optional[Callable]:
    dispatch_func = JAGGED_OPS_TABLE.get(func, None)
    if dispatch_func is not None:
        return dispatch_func
    if torch.Tag.pointwise in func.tags:
        from torch.fx.experimental.symbolic_shapes import is_nested_int
        for arg in args:
            if is_nested_int(arg):
                raise RuntimeError(f'NestedTensor {func.__name__}: invalid argument {arg}')
        num_tensor_args = sum((isinstance(x, torch.Tensor) for x in args))
        if num_tensor_args == 1:
            schema_parts = []
            for arg in func._schema.arguments:
                if <MASK>:
                    schema_parts.append(f'{arg.name}: jt_all')
                    break
                else:
                    schema_parts.append(f'{arg.name}: any')
            schema_parts.append('...')
            check_schema_str = ', '.join(schema_parts)
            check_schema(check_schema_str, func, *args, **kwargs)
            return functools.partial(jagged_unary_pointwise, func)
        elif num_tensor_args == 2:
            check_schema('lhs: any, rhs: any, ...', func, *args, **kwargs)
            return functools.partial(jagged_binary_pointwise, func)
    return None

def LOAD_FAST(self, inst: Instruction) -> None:
    name = inst.argval
    if self.exec_recorder and name in self.f_locals:
        self.exec_recorder.add_local_var(name, self.f_locals[name])
    try:
        self.push(self.symbolic_locals[name].unwrap())
    except KeyError:
        if <MASK>:
            try:
                new_name = name.replace('.', 'implicit')
                self.push(self.symbolic_locals[new_name])
            except KeyError:
                unimplemented_v2(gb_type='Attempted to read undefined local variable (implicit)', context=f'LOAD_FAST {name}', explanation=f'Could not find an implicit local variable with name `{name}`', hints=['This happens in dict/list comprehensions', *graph_break_hints.USER_ERROR])
        else:
            unimplemented_v2(gb_type='Attempted to read undefined local variable', context=f'LOAD_FAST {name}', explanation=f'Could not find a local variable with name `{name}`', hints=[*graph_break_hints.USER_ERROR])
    if name.startswith('__stack'):
        self.symbolic_locals.pop(name)

def _from_join_target(self, result: np.ndarray) -> ArrayLike:
    """
        Cast the ndarray returned from one of the libjoin.foo_indexer functions
        back to type(self._data).
        """
    if <MASK>:
        return type(self.values)(result, np.zeros(result.shape, dtype=np.bool_))
    elif isinstance(self.values, (ArrowExtensionArray, StringArray)):
        return type(self.values)._from_sequence(result, dtype=self.dtype)
    return result

def visit_manager(node: GuardManager) -> list[GuardManager]:
    assert not isinstance(node, DictGuardManager)
    tag_safe_roots = []
    for child_mgr in node.get_child_managers():
        tag_safe_roots.extend(visit(child_mgr))
    if node.is_guarded_value_immutable():
        if issubclass(node.get_type_of_guarded_value(), torch.Tensor):
            if node.has_no_accessors() and (not node.has_object_aliasing_guard()):
                node.mark_tag_safe()
        else:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), dict):
        accessors = node.get_accessors()
        child_mgrs = node.get_child_managers()
        is_subtree_tag_safe = all((isinstance(accessor, DictGetItemGuardAccessor) and mgr.is_tag_safe() for (accessor, mgr) in zip(accessors, child_mgrs)))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif <MASK>:
        is_subtree_tag_safe = check_tag_safety(node, (GetGenericDictGuardAccessor, TypeGuardAccessor))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
            return [node]
    elif node.get_type_of_guarded_value() in (types.FunctionType, types.MethodType, staticmethod, classmethod) and config.assume_dunder_attributes_remain_unchanged:
        is_subtree_tag_safe = check_tag_safety(node, (CodeGuardAccessor, ClosureGuardAccessor, FuncDefaultsGuardAccessor, FuncKwDefaultsGuardAccessor, GetAttrGuardAccessor))
        for accessor in node.get_accessors():
            if isinstance(accessor, GetAttrGuardAccessor):
                is_subtree_tag_safe &= accessor.get_attr_name() in dunder_attrs_assumed_constants
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), types.CellType):
        is_subtree_tag_safe = check_tag_safety(node, (GetAttrGuardAccessor,))
        is_subtree_tag_safe &= all((isinstance(accessor, GetAttrGuardAccessor) and accessor.get_attr_name() == 'cell_contents' for accessor in node.get_accessors()))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), tuple) and node.get_source().endswith(dunder_attrs_assumed_constants) and config.assume_dunder_attributes_remain_unchanged:
        is_subtree_tag_safe = check_tag_safety(node, (TupleGetItemGuardAccessor,))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), type):
        is_subtree_tag_safe = check_tag_safety(node, (TypeDictGuardAccessor, TypeMROGuardAccessor))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    return tag_safe_roots

def _parse_supported_ops_with_weights(spec: str) -> tuple[list[str], dict[str, float]]:
    """Parse --supported-ops string.

    Format: comma-separated fully-qualified torch ops, each optionally with =weight.
    Example: "torch.matmul=5,torch.nn.functional.rms_norm=5,torch.add"
    Returns (ops_list, weights_dict)
    """
    ops: list[str] = []
    weights: dict[str, float] = {}
    if not spec:
        return (ops, weights)
    for entry in spec.split(','):
        entry = entry.strip()
        if <MASK>:
            continue
        if '=' in entry:
            (name, w) = entry.split('=', 1)
            name = name.strip()
            try:
                weight = float(w.strip())
            except ValueError:
                continue
            ops.append(name)
            weights[name] = weight
        else:
            ops.append(entry)
    return (ops, weights)

def emit(self, record: Any) -> None:

    def _log_expression_created(emit_func: Callable[[Any], None], sym_node_id: int) -> None:
        if sym_node_id is None:
            return
        if (res := self.expression_created_logs.get(sym_node_id, None)):
            if not res.visited:
                res.visited = True
                for arg in res.argument_ids:
                    _log_expression_created(emit_func, arg)
            emit_func(res.record)
    metadata = record.metadata
    for key in self.specific_log_keys:
        if key in metadata:
            if <MASK>:
                if key == 'expression_created':
                    self.expression_created_logs[metadata[key]['result_id']] = ExpressionCreatedNode(metadata[key]['result_id'], metadata[key].get('argument_ids', []), record)
                    return
                elif key == 'propagate_real_tensors_provenance':
                    _log_expression_created(super().emit, metadata[key].get('expr_node_id'))
                elif key == 'guard_added':
                    if len(metadata[key]['symbol_to_sources']) == 0:
                        return
                    elif metadata[key]['prefix'] == 'runtime_assert':
                        return
                    _log_expression_created(super().emit, metadata[key].get('expr_node_id'))
                super().emit(record)

def local_meta(spec: OpSpec, placements: tuple[Placement, ...]) -> TensorMeta:
    if not isinstance(spec.output_specs, DTensorSpec):
        raise AssertionError(f'Expected DTensorSpec, got {type(spec.output_specs)}')
    if <MASK>:
        raise AssertionError(f'Expected TensorMeta, got {type(spec.output_specs.tensor_meta)}')
    meta: TensorMeta = spec.output_specs.tensor_meta
    local_stride = compute_local_stride(meta.stride, mesh, placements)
    (local_shape, _) = compute_local_shape_and_global_offset(meta.shape, mesh, placements)
    return TensorMeta(torch.Size(local_shape), local_stride, meta.dtype)

def run(self, shape_env=None) -> Any:
    from torch.fx.experimental.symbolic_shapes import is_symbolic, ShapeEnv, SymTypes
    if self.f is ShapeEnv:
        assert shape_env is None and self.args is None and (self.kwargs is not None)
        return ShapeEnv(**self.kwargs)
    assert shape_env is not None
    args = list(self.args or [])
    kwargs = dict(self.kwargs or {})
    (args, kwargs) = pytree.tree_map_only(ShapeEnv, lambda _: shape_env, (args, kwargs))
    (args, kwargs) = pytree.tree_map_only(lambda x: isinstance(x, SymTypes) and is_symbolic(x), lambda a: type(a)(a.node.with_shape_env(shape_env)), (args, kwargs))

    def maybe_convert_node(x: Any) -> Any:
        if <MASK>:
            return x
        assert hasattr(shape_env, 'name_to_node')
        name_to_node = shape_env.name_to_node
        assert x.name in name_to_node
        return name_to_node[x.name]

    def replacearg(index: int, key: str, fn: Callable):
        if index < len(args):
            args[index] = fn(args[index])
        if key in kwargs:
            kwargs[key] = fn(kwargs[key])
    if self.is_create_fx_call_function():
        replacearg(index=2, key='args', fn=lambda args: tuple((maybe_convert_node(a) for a in args)))
    if self.is_evaluate_expr() or self.is_defer_runtime_assert():
        replacearg(index=3, key='fx_node', fn=maybe_convert_node)
    return self.f(*args, **kwargs)

def call_bool(self, tx: 'InstructionTranslator', arg):
    if <MASK>:
        if isinstance(arg.sym_num, torch.SymBool):
            return arg
        assert istype(arg.sym_num, (torch.SymInt, torch.SymFloat))
        return SymNodeVariable.create(tx, arg.as_proxy() != 0)

def _set_skip_input_transform(self, input_str):
    if <MASK>:
        self.skip_input_transform = False
    elif input_str == 's1':
        self.skip_input_transform = True
    else:
        raise ValueError(f'invalid skip_input_transform: {input_str}')

def _gather_tunableop_results() -> None:
    """Gather results from multiple tunableop results file and create a single file."""
    gemm_lines = set()
    validator_lines = []
    results_filename = get_filename()
    if results_filename is not None and results_filename != '':
        dot_pos = results_filename.find('.')
        if dot_pos != -1 and dot_pos > 0:
            filename_pattern = results_filename[:dot_pos - 1] + '?' + results_filename[dot_pos:]
        else:
            filename_pattern = ''
    else:
        results_filename_env = os.getenv('PYTORCH_TUNABLEOP_FILENAME')
        if <MASK>:
            filename_pattern = 'tunableop_results?.csv'
        elif '%d' in results_filename_env:
            filename_pattern = results_filename_env.replace('%d', '?')
        else:
            filename_pattern = results_filename_env.replace('.', '?.')
    assert '?' in filename_pattern
    FirstFile = False
    matching_files = glob.glob(filename_pattern)
    num_matching_files = len(matching_files)
    for file_path in matching_files:
        with open(file_path) as file:
            for line in file:
                if line.startswith('Validator'):
                    if not FirstFile:
                        validator_lines.append(line)
                else:
                    gemm_lines.add(line)
        FirstFile = True
    output_file = filename_pattern.replace('?', '_full0')
    with open(output_file, 'w') as out_file:
        for line in validator_lines:
            out_file.write(line)
        for line in gemm_lines:
            out_file.write(line)
    for i in range(1, num_matching_files):
        duplicate_file = output_file.replace('0', str(i))
        shutil.copy(output_file, duplicate_file)

def aggregate(metric_values: list[float], metric_name: str):
    """Aggregates metric values using a function based on the metric name.

  If metric name does not match any of the known patterns, the first value from
  the input list is returned.

  Args:
    metric_values: list of metric values, floats
    metric_name: metric name

  Returns:
    aggregated metric value
  """
    if str.endswith(metric_name, '.max'):
        return max(metric_values)
    if <MASK>:
        return min(metric_values)
    if str.endswith(metric_name, '.sum'):
        return sum(metric_values)
    return metric_values[0]

def speculate_subgraph(tx, f, sub_args, sub_kwargs, description, *, source_target=None, always_restore=False, enable_grad=None, set_subgraph_inputs='automatic', restore_side_effects=True, should_flatten_outputs=False, remove_consts_from_outputs=True, under_activation_checkpoint=False, supports_input_mutation=True, supports_aliasing=True, tracer=None):
    if sub_kwargs is None:
        sub_kwargs = {}
    assert set_subgraph_inputs in {'automatic', 'semi_automatic', 'flatten_manual', 'manual'}, 'Please use one of the supported set_subgraph_inputs options.'
    if sub_kwargs and set_subgraph_inputs != 'automatic':
        unimplemented('Use `set_subgraph_inputs=automatic` when passing `sub_kwargs`.')
    try:
        (f, sub_args, sub_kwargs) = LazyVariableTracker.realize_all((f, sub_args, sub_kwargs))
        with tx.output.subtracer(source_target, tracer) as subtracer:
            sub_args_names = maybe_positional_arg_names(f)
            if sub_args_names is not None and len(sub_args_names) < len(sub_args):
                sub_args_names = None
            args = validate_args_and_maybe_create_graph_inputs(sub_args, subtracer, tx, set_subgraph_inputs, description, sub_args_names)
            validate_args_and_maybe_create_graph_inputs(sub_kwargs.values(), subtracer, tx, set_subgraph_inputs='automatic', description=description)
            autograd_ctx = dynamo_enable_grad(tx, enable_grad) if enable_grad is not None else contextlib.nullcontext()
            checkpoint_ctx = dynamo_under_activation_checkpoint(tx) if under_activation_checkpoint else contextlib.nullcontext()
            if restore_side_effects:
                prev_side_effects = tx.output.side_effects.clone()
            with autograd_ctx, checkpoint_ctx:
                output = f.call_function(tx, args, sub_kwargs)
            if restore_side_effects:
                new_side_effects = tx.output.side_effects.clone()
                prev_side_effects.track_runahead_tensor_and_symvar_side_effects(new_side_effects)
                tx.output.side_effects = prev_side_effects
            treespec = None
            masks_to_filter_const_values = None
            const_values = None
            if should_flatten_outputs:
                from torch._dynamo.external_utils import filter_out_const_values
                (output, treespec) = _make_inlined(tx, pytree.tree_flatten)(output).unpack_var_sequence(tx)
                output = BuiltinVariable(tuple).call_function(tx, [output], {})
                if <MASK>:
                    output_proxies = output.as_proxy()
                    masks_to_filter_const_values = pytree.tree_map(lambda x: not isinstance(x, torch.fx.Proxy), output_proxies)
                    const_values = pytree.tree_map(lambda x: None if isinstance(x, torch.fx.Proxy) else x, output_proxies)
                    output = _make_inlined(tx, filter_out_const_values)(output, masks_to_filter_const_values)
            if always_restore:
                return ((output, OutputSpec(treespec, masks_to_filter_const_values, const_values)), tx.output.graph, subtracer.lifted_freevars)
            else:
                validate_subgraph_output_types(output)
                output_proxies = output.as_proxy()
                output_proxies = pytree.tree_map(subtracer.maybe_lift_tracked_freevar_to_input, output_proxies)
                tx.output.create_node('output', 'output', subtracer.create_arg((output_proxies,)), {})
                graph = tx.output.graph
                graph.lint()
                lifted_freevars = subtracer.lifted_freevars

                def move_lifted_freevars_phs_to_end(graph: torch.fx.Graph, lifted_freevars: tuple[torch.fx.Node]):
                    lifted_ph_set = {child_p.node for child_p in lifted_freevars.values()}
                    prev_phs = [n for n in graph.nodes if n.op == 'placeholder']
                    if len(prev_phs) == 0 or len(lifted_ph_set) == 0 or len(prev_phs) == len(lifted_ph_set):
                        return
                    for x1 in prev_phs:
                        if x1 in lifted_ph_set:
                            break
                    assert x1 is not None and x1.op == 'placeholder'
                    cand_x = x1.next
                    while cand_x is not None and cand_x.op == 'placeholder':
                        if cand_x in lifted_ph_set:
                            cand_x = cand_x.next
                        else:
                            nxt = cand_x.next
                            cand_x._remove_from_list()
                            x1.prepend(cand_x)
                            cand_x = nxt
                    after_phs = [node for node in graph.nodes if node.op == 'placeholder'][-len(lifted_freevars):]
                    assert len(after_phs) == len(lifted_freevars)
                    for (child_proxy, ph) in zip(lifted_freevars.values(), after_phs):
                        assert child_proxy.node is ph, 'The order of placeholders is different from the order of lifted_freevars'
                    graph.lint()
                if len(lifted_freevars) > 0:
                    move_lifted_freevars_phs_to_end(graph, lifted_freevars)
                if not supports_input_mutation:
                    mutation_info = subtracer.has_input_mutation()
                    if mutation_info.has_mutation:
                        context = f'{mutation_info.msg} in\n {graph}'
                        unimplemented_v2(gb_type='Encountered input mutation during higher order op tracing', context=context, explanation=f'Higher order ops do not support input mutation. Found in {source_target.name()}', hints=['Consider using the debug context to change user code to avoid mutation.', 'Please open an issue.'])
                if not supports_aliasing:
                    aliasing_info = subtracer.has_aliasing()
                    if aliasing_info.has_aliasing:
                        context = f'{aliasing_info.msg} in\n {graph}'
                        unimplemented_v2(gb_type='Encountered aliasing during higher order op tracing', context=context, explanation=f'Higher order ops do not support aliasing. Found in {source_target.name()}', hints=['Replace `return input` with `return input.clone()` to avoid aliasing.', 'Consider using the debug context to change user code to avoid aliasing.', 'Please open an issue.'])
                return ((output, OutputSpec(treespec, masks_to_filter_const_values, const_values)), graph, lifted_freevars)
    except Unsupported as ex:
        f_name = f'{type(f).__name__}'
        if isinstance(f, UserFunctionVariable):
            f_name = f.get_name()
        msg = f'speculate_subgraph: while introspecting {description}, we were unable to trace function `{f_name}` into a single graph. This means that Dynamo was unable to prove safety for this API and will fall back to eager-mode PyTorch, which could lead to a slowdown.'
        log.info(msg)
        log.info(ex)
        raise ex

def array_ufunc(self, ufunc: np.ufunc, method: str, *inputs: Any, **kwargs: Any):
    """
    Compatibility with numpy ufuncs.

    See also
    --------
    numpy.org/doc/stable/reference/arrays.classes.html#numpy.class.__array_ufunc__
    """
    from pandas.core.frame import DataFrame, Series
    from pandas.core.generic import NDFrame
    from pandas.core.internals import BlockManager
    cls = type(self)
    kwargs = _standardize_out_kwarg(**kwargs)
    result = maybe_dispatch_ufunc_to_dunder_op(self, ufunc, method, *inputs, **kwargs)
    if <MASK>:
        return result
    no_defer = (np.ndarray.__array_ufunc__, cls.__array_ufunc__)
    for item in inputs:
        higher_priority = hasattr(item, '__array_priority__') and item.__array_priority__ > self.__array_priority__
        has_array_ufunc = hasattr(item, '__array_ufunc__') and type(item).__array_ufunc__ not in no_defer and (not isinstance(item, self._HANDLED_TYPES))
        if higher_priority or has_array_ufunc:
            return NotImplemented
    types = tuple((type(x) for x in inputs))
    alignable = [x for (x, t) in zip(inputs, types, strict=True) if issubclass(t, NDFrame)]
    if len(alignable) > 1:
        set_types = set(types)
        if len(set_types) > 1 and {DataFrame, Series}.issubset(set_types):
            raise NotImplementedError(f'Cannot apply ufunc {ufunc} to mixed DataFrame and Series inputs.')
        axes = self.axes
        for obj in alignable[1:]:
            for (i, (ax1, ax2)) in enumerate(zip(axes, obj.axes, strict=True)):
                axes[i] = ax1.union(ax2)
        reconstruct_axes = dict(zip(self._AXIS_ORDERS, axes, strict=True))
        inputs = tuple((x.reindex(**reconstruct_axes) if issubclass(t, NDFrame) else x for (x, t) in zip(inputs, types, strict=True)))
    else:
        reconstruct_axes = dict(zip(self._AXIS_ORDERS, self.axes, strict=True))
    if self.ndim == 1:
        names = {x.name for x in inputs if hasattr(x, 'name')}
        name = names.pop() if len(names) == 1 else None
        reconstruct_kwargs = {'name': name}
    else:
        reconstruct_kwargs = {}

    def reconstruct(result):
        if ufunc.nout > 1:
            return tuple((_reconstruct(x) for x in result))
        return _reconstruct(result)

    def _reconstruct(result):
        if lib.is_scalar(result):
            return result
        if result.ndim != self.ndim:
            if method == 'outer':
                raise NotImplementedError
            return result
        if isinstance(result, BlockManager):
            result = self._constructor_from_mgr(result, axes=result.axes)
        else:
            result = self._constructor(result, **reconstruct_axes, **reconstruct_kwargs, copy=False)
        if len(alignable) == 1:
            result = result.__finalize__(self)
        return result
    if 'out' in kwargs:
        result = dispatch_ufunc_with_out(self, ufunc, method, *inputs, **kwargs)
        return reconstruct(result)
    if method == 'reduce':
        result = dispatch_reduction_ufunc(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    if self.ndim > 1 and (len(inputs) > 1 or ufunc.nout > 1):
        inputs = tuple((np.asarray(x) for x in inputs))
        result = getattr(ufunc, method)(*inputs, **kwargs)
    elif self.ndim == 1:
        inputs = tuple((extract_array(x, extract_numpy=True) for x in inputs))
        result = getattr(ufunc, method)(*inputs, **kwargs)
    elif method == '__call__' and (not kwargs):
        mgr = inputs[0]._mgr
        result = mgr.apply(getattr(ufunc, method))
    else:
        result = default_array_ufunc(inputs[0], ufunc, method, *inputs, **kwargs)
    result = reconstruct(result)
    return result

def add_json_information(json_dict, fqn):
    json_dict['fqn'] = fqn
    json_dict['module_type'] = ''
    json_dict['parameters'] = []
    json_dict['children'] = []
    json_dict['collectives_forward'] = []
    json_dict['collectives_backward'] = []
    json_dict['operations_forward'] = []
    json_dict['operations_backward'] = []
    if 'module_type' in self.advanced_module_tracker.module_helper_dict[fqn] and include_module_data:
        json_dict['module_type'] = self.advanced_module_tracker.module_helper_dict[fqn]['module_type']
        if 'parameters' in self.advanced_module_tracker.module_helper_dict[fqn]:
            for (param_name, placement) in self.advanced_module_tracker.module_helper_dict[fqn]['parameters'].items():
                json_dict['parameters'].append((param_name, placement))
    if fqn in self.comm_module_counts:
        for (collective, count) in self.comm_module_counts[fqn]['forward'].items():
            json_dict['collectives_forward'].append((str(collective), count))
        for (collective, count) in self.comm_module_counts[fqn]['backward'].items():
            json_dict['collectives_backward'].append((str(collective), count))
    forward_operations = []
    backward_operations = []
    checkpointing_operations = []
    if include_DTensor_ops:
        if <MASK>:
            (forward_operations, backward_operations, checkpointing_operations) = self._get_operations_list(self.comm_module_operation_counts[fqn])
    if not include_ops:
        forward_operations = [op for op in forward_operations if len(op['input_sharding'])]
        backward_operations = [op for op in backward_operations if len(op['input_sharding'])]
        checkpointing_operations = [op for op in checkpointing_operations if len(op['input_sharding'])]
    if not include_trivial_ops:
        forward_operations = [op for op in forward_operations if str(op['name']) not in trivial_ops]
        backward_operations = [op for op in backward_operations if str(op['name']) not in trivial_ops]
        checkpointing_operations = [op for op in checkpointing_operations if str(op['name']) not in trivial_ops]
    forward_operations = copy.deepcopy(forward_operations)
    for op in forward_operations:
        op['name'] = str(op['name'])
        for i in range(len(op['input_sharding'])):
            op['input_sharding'][i] = str(op['input_sharding'][i])
            op['input_shape'][i] = str(op['input_shape'][i])
    backward_operations = copy.deepcopy(backward_operations)
    for op in backward_operations:
        op['name'] = str(op['name'])
        for i in range(len(op['input_sharding'])):
            op['input_sharding'][i] = str(op['input_sharding'][i])
            op['input_shape'][i] = str(op['input_shape'][i])
    checkpointing_operations = copy.deepcopy(checkpointing_operations)
    for op in checkpointing_operations:
        op['name'] = str(op['name'])
        for i in range(len(op['input_sharding'])):
            op['input_sharding'][i] = str(op['input_sharding'][i])
            op['input_shape'][i] = str(op['input_shape'][i])
    json_dict['operations_forward'] = forward_operations
    json_dict['operations_backward'] = backward_operations
    json_dict['operations_checkpointing'] = checkpointing_operations
    if fqn not in self.advanced_module_tracker.parent_dict:
        return json_dict
    for ele in self.advanced_module_tracker.parent_dict[fqn]:
        json_dict['children'].append(add_json_information({}, ele))
    return json_dict

def _simulate_comms_compute(pipeline_order, stage_to_rank: Callable[[int], int], num_stages: int):
    """This function dry-run simulates the actions in the schedule from the perspective of all ranks, and flags
    any deadlocks caused by missing or misordered communications.  It also simulates any bubbles in time where a rank
    can not execute any action due to waiting for unmet dependencies.  The total number of simulator steps can be used
    as a metric for unit tests involving IR optimization passes as reordering and merging of IR can reduce the number
    of simulated steps.

    The simulation is not high-fidelity and does not model overlapping of compute and communication, or cuda streams.
    Future work may be to enhance this and model the compute time, comms overlap, and even memory.
    """
    pipeline_order = {rank: [a for a in pipeline_order[rank] if a is not None] for rank in sorted(pipeline_order)}
    _schedule: dict[int, list[_Action | None]] = {rank: [] for rank in sorted(pipeline_order)}
    _prev_ops_rank: dict[int, set[_Action]] = {rank: set() for rank in _schedule}

    def add_to_schedule(rank: int, action: Optional[_Action]):
        _schedule[rank].append(action)
        if action is not None:
            _prev_ops_rank[rank].add(action)

    def _ready_to_schedule(action: Optional[_Action]) -> bool:
        if action is None:
            return True
        stage_idx = action.stage_index
        prev_ops = _prev_ops_rank[stage_to_rank(stage_idx)]
        if action.computation_type == F:
            if action.stage_index == 0:
                return True
            elif _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_ops:
                return True
            elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_ops:
                return True
            return False
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
            if action.stage_index == num_stages - 1:
                return True
            if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_ops:
                return True
            if _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_ops:
                return True
            if _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_ops:
                return True
            return False
        elif action.computation_type == BACKWARD_WEIGHT:
            return True
        elif <MASK>:
            expected_f = _Action(action.stage_index, F, action.microbatch_index)
            return expected_f in prev_ops
        elif action.computation_type == RECV_F:
            peer_stage_idx = stage_idx - 1
            expected_send = _Action(peer_stage_idx, SEND_F, action.microbatch_index)
            return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
        elif action.computation_type == SEND_B:
            expected_b = _Action(action.stage_index, BACKWARD_INPUT, action.microbatch_index)
            expected_bw = _Action(action.stage_index, FULL_BACKWARD, action.microbatch_index)
            return expected_b in prev_ops or expected_bw in prev_ops
        elif action.computation_type == RECV_B:
            peer_stage_idx = stage_idx + 1
            expected_send = _Action(peer_stage_idx, SEND_B, action.microbatch_index)
            return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
        else:
            raise ValueError(f'Unsupported action type {action}')
    while pipeline_order:
        progress = False
        for rank in sorted(pipeline_order):
            if len(pipeline_order[rank]) == 0:
                continue
            action = pipeline_order[rank][0]
            if _ready_to_schedule(action):
                if action is not None:
                    add_to_schedule(rank, action)
                pipeline_order[rank].pop(0)
                progress = True
            else:
                add_to_schedule(rank, None)
        for i in sorted(pipeline_order, reverse=True):
            if len(pipeline_order[i]) == 0:
                del pipeline_order[i]
        for rank in sorted(pipeline_order):
            if len(pipeline_order[rank]) == 0:
                continue
            if _schedule[rank][-1] is not None:
                continue
            action = pipeline_order[rank][0]
            if _ready_to_schedule(action):
                if action is not None:
                    _schedule[rank][-1] = action
                    _prev_ops_rank[rank].add(action)
                pipeline_order[rank].pop(0)
        for i in sorted(pipeline_order, reverse=True):
            if len(pipeline_order[i]) == 0:
                del pipeline_order[i]
        if not progress:
            print('WIP comms schedule:\n', _format_pipeline_order(_schedule))
            for rank in pipeline_order:
                print(f'rank={rank!r} next action= {pipeline_order[rank][0]}')
            raise ValueError('Schedule is not progressing')
    return _schedule

def node_name_from_input(node_name: str) -> str:
    """Strips off ports and other decorations to get the underlying node name."""
    if <MASK>:
        node_name = node_name[1:]
    m = re.search('(.*):\\d+$', node_name)
    if m:
        node_name = m.group(1)
    return node_name

def signature_of(arg: KernelArgType, *, size_dtype: Optional[str]) -> str:
    if isinstance(arg, TensorArg):
        if arg.dtype == torch.float8_e4m3fn:
            typ = '*fp8e4nv'
        elif arg.dtype == torch.float8_e5m2:
            typ = '*fp8e5'
        elif arg.dtype == torch.float8_e4m3fnuz:
            typ = '*fp8e4b8'
        elif arg.dtype == torch.float8_e5m2fnuz:
            typ = '*fp8e5b16'
        else:
            typ = _type_of(arg.dtype)
        if should_unwrap_unspec_arg(arg.buffer):
            new_typ = typ.lstrip('*')
            if <MASK>:
                return 'fp32'
            else:
                return new_typ
        else:
            return typ
    if isinstance(arg, SizeArg):
        if arg.expr is None:
            if triton_version_uses_attrs_dict():
                return 'constexpr'
            else:
                return '*i8'
        elif _arg_equals_1(arg) and triton_version_uses_attrs_dict():
            return 'constexpr'
        elif isinstance(arg.expr, (float, sympy.Float)):
            return 'fp32'
        elif isinstance(arg.expr, bool):
            return 'i1'
        if size_dtype == 'tl.int32':
            return 'i32'
        elif size_dtype == 'tl.int64':
            return 'i64'
        elif size_dtype is None:
            int_max = torch.iinfo(torch.int32).max
            if expr_fits_within_32bit(arg.expr):
                V.graph.sizevars.check_leq(arg.expr, int_max)
                return 'i32'
            else:
                return 'i64'
        else:
            raise NotImplementedError(f'unhandled size_dtype {size_dtype}')
    if isinstance(arg, WorkspaceArg):
        return _type_of(arg.dtype)
    if isinstance(arg, TMADescriptorArg):
        if arg.api_type == 'experimental':
            return 'nvTmaDesc'
        else:
            assert arg.api_type == 'stable'
            assert arg.block_shape is not None
            assert arg.dtype is not None
            inner = _type_of(arg.dtype)[1:]
            return f'tensordesc<{inner}{list(arg.block_shape)}>'
    if isinstance(arg, ConstexprArg):
        return 'constexpr'
    raise NotImplementedError(f'unhandled {type(arg)}: {arg}')

def get_versions_from_ci(content: list[str]) -> tuple[dict[str, str], dict[str, str]]:
    """Min versions in CI job for testing all optional dependencies."""
    seen_required = False
    seen_optional = False
    seen_test = False
    required_deps = {}
    optional_deps = {}
    for line in content:
        if '# test dependencies' in line:
            seen_test = True
        elif seen_test and '- pytest>=' in line:
            (package, version) = line.strip().split('>=')
            package = package[2:]
            optional_deps[package.casefold()] = version
        elif '# required dependencies' in line:
            seen_required = True
        elif '# optional dependencies' in line:
            seen_optional = True
        elif '- pip:' in line:
            continue
        elif seen_required and line.strip():
            if '==' in line:
                (package, version) = line.strip().split('==', maxsplit=1)
            else:
                (package, version) = line.strip().split('=', maxsplit=1)
            package = package.split()[-1]
            if package in EXCLUDE_DEPS:
                continue
            if <MASK>:
                required_deps[package.casefold()] = version
            else:
                optional_deps[package.casefold()] = version
    return (required_deps, optional_deps)

def memory_plan_reuse(self):
    outputs = self.get_graph_outputs()
    out_names = V.graph._get_output_names(outputs)
    while self.lines and isinstance(self.lines[-1], MemoryPlanningLine) and (self.lines[-1].node.name not in out_names):
        self.lines.pop()
    planning_states = [MemoryPlanningState()]
    past_planning_states = []
    for i in range(len(self.lines)):
        line = self.lines[i]
        if isinstance(line, MemoryPlanningLine):
            self.lines[i] = line.plan(planning_states[-1])
        elif <MASK>:
            planning_states.append(MemoryPlanningState())
        elif isinstance(line, ExitSubgraphLine):
            past_planning_states.append(planning_states.pop())
    past_planning_states.append(planning_states.pop())
    assert len(planning_states) == 0
    _total_allocated_buffer_size = sum((s.total_allocated_buffer_size for s in past_planning_states))

def __init__(self, obj):

    def get_tensor_key(obj):
        assert not (obj.dtype.is_floating_point or obj.dtype.is_complex), obj.dtype
        return (obj.data_ptr(), obj.storage_offset(), obj.shape, obj.stride(), obj.dtype)
    self._obj_ref = weakref.ref(obj)
    if obj.layout is torch.strided:
        self.key = get_tensor_key(obj)
    elif <MASK>:
        self.key = (get_tensor_key(obj.crow_indices()), get_tensor_key(obj.col_indices()))
    elif obj.layout in {torch.sparse_csc, torch.sparse_bsc}:
        self.key = (get_tensor_key(obj.ccol_indices()), get_tensor_key(obj.row_indices()))
    else:
        raise NotImplementedError(obj.layout)
    self._hash = hash(self.key)

def _live_receivers(self, sender):
    """
        Filter sequence of receivers to get resolved, live receivers.

        This checks for weak references and resolves them, then returning only
        live receivers.
        """
    receivers = None
    if self.use_caching and (not self._dead_receivers):
        receivers = self.sender_receivers_cache.get(sender)
        if receivers is NO_RECEIVERS:
            return ([], [])
    if receivers is None:
        with self.lock:
            self._clear_dead_receivers()
            senderkey = _make_id(sender)
            receivers = []
            for ((_receiverkey, r_senderkey), receiver, sender_ref, is_async) in self.receivers:
                if r_senderkey == NONE_ID or r_senderkey == senderkey:
                    receivers.append((receiver, sender_ref, is_async))
            if <MASK>:
                if not receivers:
                    self.sender_receivers_cache[sender] = NO_RECEIVERS
                else:
                    self.sender_receivers_cache[sender] = receivers
    non_weak_sync_receivers = []
    non_weak_async_receivers = []
    for (receiver, sender_ref, is_async) in receivers:
        if isinstance(receiver, weakref.ReferenceType):
            receiver = receiver()
            if receiver is None:
                continue
        if sender_ref is not None and sender_ref() is None:
            continue
        if is_async:
            non_weak_async_receivers.append(receiver)
        else:
            non_weak_sync_receivers.append(receiver)
    return (non_weak_sync_receivers, non_weak_async_receivers)

def test_prefetch_to_host_dataset(self, distribution):
    input_options = distribute_lib.InputOptions(experimental_fetch_to_device=False)
    dataset = dataset_ops.Dataset.range(100)
    dataset = dataset.batch(distribution.num_replicas_in_sync)
    dataset = distribution.experimental_distribute_dataset(dataset, options=input_options)
    if context.executing_eagerly():
        item = next(iter(dataset))
    elif <MASK>:
        item = dataset.make_initializable_iterator().get_next()
    else:
        self.skipTest('unsupported test combination')
    self.assertAllEqual(tf_device.DeviceSpec.from_string(item.device).device_type, 'CPU')

def _elementwise_where_v2(condition, x, y):
    """Ragged version of tf.where_v2(condition, x, y)."""
    if not (condition.shape.is_fully_defined() and x.shape.is_fully_defined() and y.shape.is_fully_defined() and (x.shape == y.shape) and (condition.shape == x.shape)):
        shape_c = ragged_tensor_shape.RaggedTensorDynamicShape.from_tensor(condition)
        shape_x = ragged_tensor_shape.RaggedTensorDynamicShape.from_tensor(x)
        shape_y = ragged_tensor_shape.RaggedTensorDynamicShape.from_tensor(y)
        shape = ragged_tensor_shape.broadcast_dynamic_shape(shape_c, ragged_tensor_shape.broadcast_dynamic_shape(shape_x, shape_y))
        condition = ragged_tensor_shape.broadcast_to(condition, shape)
        x = ragged_tensor_shape.broadcast_to(x, shape)
        y = ragged_tensor_shape.broadcast_to(y, shape)
    condition_is_ragged = isinstance(condition, ragged_tensor.RaggedTensor)
    x_is_ragged = isinstance(x, ragged_tensor.RaggedTensor)
    y_is_ragged = isinstance(y, ragged_tensor.RaggedTensor)
    if <MASK>:
        return array_ops.where_v2(condition, x, y)
    return ragged_functional_ops.map_flat_values(array_ops.where_v2, condition, x, y)

def list_resources_with_updates(date_since, resources=None, languages=None, verbosity=0):
    api_token = get_api_token()
    project = 'o:django:p:django'
    date_since_iso = date_since.isoformat().strip('Z') + 'Z'
    if <MASK>:
        print(f'\n== Starting list_resources_with_updates at date_since_iso={date_since_iso!r}')
    if not languages:
        languages = [d['attributes']['code'] for d in get_api_response(f'projects/{project}/languages', api_token, verbosity=verbosity)]
    if verbosity > 1:
        print(f'\n=== Languages to process: languages={languages!r}')
    if not resources:
        resources = [d['attributes']['slug'] for d in get_api_response('resources', api_token, params={'filter[project]': project}, verbosity=verbosity)]
    else:
        resources = [_tx_resource_slug_for_name(r) for r in resources]
    if verbosity > 1:
        print(f'\n=== Resources to process: resources={resources!r}')
    resource_lang_changed = defaultdict(list)
    for (lang, resource) in product(languages, resources):
        if verbosity:
            print(f'\n=== Getting data for: lang={lang!r} resource={resource!r} date_since_iso={date_since_iso!r}')
        data = get_api_response('resource_translations', api_token, params={'filter[resource]': f'{project}:r:{resource}', 'filter[language]': f'l:{lang}', 'filter[date_translated][gt]': date_since_iso}, verbosity=verbosity)
        local_resource = resource.replace('contrib-', '', 1)
        local_lang = lang
        if data:
            resource_lang_changed[local_resource].append(local_lang)
            if verbosity > 2:
                fname = f'{local_resource}-{local_lang}.json'
                with open(fname, 'w') as f:
                    f.write(json.dumps(data, sort_keys=True, indent=2))
                print(f'==== Stored full data JSON in: {fname}')
        if verbosity > 1:
            print(f'==== Result for local_resource={local_resource!r} local_lang={local_lang!r}: len(data)={len(data)!r}')
    return resource_lang_changed

def aggregate(self, func=None, *args, **kwargs):
    (relabeling, func, columns, order) = reconstruct_func(func, **kwargs)
    result = ResamplerWindowApply(self, func, args=args, kwargs=kwargs).agg()
    if isinstance(result, ABCDataFrame) and relabeling:
        result = result.iloc[:, order]
        result.columns = columns
    if <MASK>:
        return self.apply(func, raw=False, args=args, kwargs=kwargs)
    return result

def maybe_lift_tracked_freevar_to_input(self, arg: Any) -> Any:
    """
        If arg is a free variable, then lift it to be an input.
        Returns the new lifted arg (if arg was a freevar), else the
        original arg.
        """
    if <MASK>:
        if isinstance(arg, slice):
            return slice(*(self.maybe_lift_tracked_freevar_to_input(sub_arg) for sub_arg in (arg.start, arg.stop, arg.step)))
        else:
            return arg
    elif arg.tracer == self:
        return arg
    return self.lift_tracked_freevar_to_input(arg)

def _verify_exported_program_signature(exported_program) -> None:
    gs = exported_program.graph_signature
    input_node_names = [node.name for node in exported_program.graph.nodes if node.op == 'placeholder']
    if len(input_node_names) != len(gs.input_specs):
        raise SpecViolationError(f'Number of graph inputs ({len(input_node_names)}) does not match number of inputs in the graph signature ({len(gs.input_specs)})')
    for (input_spec, node) in zip(gs.input_specs, input_node_names):
        if isinstance(input_spec.arg, (TensorArgument, SymIntArgument, SymFloatArgument, SymBoolArgument)):
            if input_spec.arg.name != node:
                raise SpecViolationError(f'Input spec name {input_spec.arg.name} does not match node name {node}')
        if input_spec.kind == InputKind.USER_INPUT:
            continue
        elif <MASK>:
            if not isinstance(input_spec.arg, TensorArgument):
                raise SpecViolationError(f'Parameter {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            param = input_spec.target
            if param not in exported_program.state_dict:
                raise SpecViolationError(f'Parameter {param} is not in the state dict.')
            if not isinstance(exported_program.state_dict[param], torch.nn.Parameter):
                raise SpecViolationError(f'State dict entry for parameter {param} is not an instance of torch.nn.Parameter.')
        elif input_spec.kind == InputKind.BUFFER:
            if not isinstance(input_spec.arg, TensorArgument):
                raise SpecViolationError(f'Buffer {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            buffer = input_spec.target
            if input_spec.persistent is None:
                raise SpecViolationError(f'Buffer {buffer} is missing a persistence flag')
            if input_spec.persistent is True and buffer not in exported_program.state_dict:
                raise SpecViolationError(f'Buffer {buffer} is not in the state dict.')
            if input_spec.persistent is False and buffer in exported_program.state_dict:
                raise SpecViolationError(f'Non-persistent buffer {buffer} is in the state dict, it should not be.')
        elif input_spec.kind == InputKind.CONSTANT_TENSOR:
            if not isinstance(input_spec.arg, TensorArgument):
                raise SpecViolationError(f'Constant tensor {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            tensor_const = input_spec.target
            if tensor_const not in exported_program.constants:
                raise SpecViolationError(f'Constant tensor {tensor_const} is not in the constants dictionary.')
        elif input_spec.kind == InputKind.CUSTOM_OBJ:
            if not isinstance(input_spec.arg, CustomObjArgument):
                raise SpecViolationError(f'Custom object {input_spec.name} is not a custom object argument. Found {input_spec.arg} instead.')
            if input_spec.target is None:
                raise SpecViolationError(f'InputSpec for {input_spec.name} has no target.')
            custom_obj = input_spec.target
            if custom_obj not in exported_program.constants:
                raise SpecViolationError(f'Custom object {custom_obj} is not in the constants dictionary.')
        elif input_spec.kind == InputKind.TOKEN:
            if not isinstance(input_spec.arg, TokenArgument):
                raise SpecViolationError(f'Constant tensor {input_spec.name} is not a tensor argument. Found {input_spec.arg} instead.')
        else:
            raise SpecViolationError(f'Unknown InputKind {input_spec.kind}.')
    output_node = list(exported_program.graph.nodes)[-1]
    assert output_node.op == 'output'
    output_nodes = [arg.name if isinstance(arg, torch.fx.Node) else arg for arg in output_node.args[0]]
    if len(output_nodes) != len(gs.output_specs):
        raise SpecViolationError(f'Number of output nodes {len(output_nodes)} is different Than the number of outputs specified by the graph signature: \nNumber of mutated buffers: {len(gs.buffers_to_mutate)}. \nNumber of user outputs: {len(gs.user_outputs)}. \n')
    num_tokens = len(gs.output_tokens)
    end = len(gs.buffers_to_mutate) + len(gs.parameters_to_mutate) + len(gs.user_inputs_to_mutate) + num_tokens
    mutate_nodes: list[str] = output_nodes[num_tokens:end]
    user_output_nodes = output_nodes[end:end + len(gs.user_outputs)]
    for mutation_node in mutate_nodes:
        if mutation_node in gs.buffers_to_mutate:
            if gs.buffers_to_mutate[mutation_node] not in gs.buffers:
                raise SpecViolationError(f'Buffer output {mutation_node} does not point to a buffer that exists. \nDict of buffers that are mutated, in order: {gs.buffers_to_mutate} \nBuffer nodes available: {gs.buffers} \n')
        elif mutation_node in gs.parameters_to_mutate:
            if gs.parameters_to_mutate[mutation_node] not in gs.parameters:
                raise SpecViolationError(f'Parameter output {mutation_node} does not point to a parameter that exists. \nDict of parameters that are mutated, in order: {gs.parameters_to_mutate} \nParameter nodes available: {gs.parameters} \n')
        elif mutation_node in gs.user_inputs_to_mutate:
            if gs.user_inputs_to_mutate[mutation_node] not in gs.user_inputs:
                raise SpecViolationError(f'User input output {mutation_node} does not point to a user input that exists. \nDict of user inputs that are mutated, in order: {gs.user_inputs_to_mutate} \nUser input nodes available: {gs.user_inputs} \n')
        else:
            raise SpecViolationError(f'Mutation node {mutation_node} is neither a buffer nor a user input. Buffers to mutate: {gs.buffers_to_mutate}, User inputs to mutate: {gs.user_inputs_to_mutate}')
    for (user_output_node, user_output_name) in zip(user_output_nodes, gs.user_outputs):
        if user_output_node != user_output_name:
            raise SpecViolationError(f"User output {user_output_node} is not in the correct order or is not found in the exported program's user_output list: {gs.user_outputs}. ")

def _partitions_sequential(partitions: Sequence[SourcePartition]):
    prev_partition = None
    for partition in partitions:
        if <MASK>:
            return False
        prev_partition = partition
    return True

def generate_def(dll, dfile):
    """Given a dll file location,  get all its exported symbols and dump them
    into the given def file.

    The .def file will be overwritten"""
    dump = dump_table(dll)
    for i in range(len(dump)):
        if <MASK>:
            break
    else:
        raise ValueError('Symbol table not found')
    syms = []
    for j in range(i + 1, len(dump)):
        m = _TABLE.match(dump[j].decode())
        if m:
            syms.append((int(m.group(1).strip()), m.group(2)))
        else:
            break
    if len(syms) == 0:
        log.warn('No symbols found in %s' % dll)
    with open(dfile, 'w') as d:
        d.write('LIBRARY        %s\n' % os.path.basename(dll))
        d.write(';CODE          PRELOAD MOVEABLE DISCARDABLE\n')
        d.write(';DATA          PRELOAD SINGLE\n')
        d.write('\nEXPORTS\n')
        for s in syms:
            d.write('%s\n' % s[1])

def _model_loss(model, inputs, targets, output_loss_metrics=None, sample_weights=None, training=False):
    """Calculates the loss for a given model.

  Args:
      model: The model on which metrics are being calculated.
      inputs: Either a dictionary of inputs to the model or a list of input
        arrays.
      targets: List of target arrays.
      output_loss_metrics: List of metrics that are used to aggregated output
        loss values.
      sample_weights: Optional list of sample weight arrays.
      training: Whether the model should be run in inference or training mode.

  Returns:
     Returns the model output, total loss, loss value calculated using the
     specified loss function and masks for each output. The total loss includes
     regularization losses and applies masking and sample weighting
     to the loss value.
  """
    total_loss = 0
    kwargs = {}
    if model._expects_training_arg:
        kwargs['training'] = training
    if len(inputs) == 1 and (not isinstance(inputs, dict)):
        inputs = inputs[0]
    if any((isinstance(input_t, (np.ndarray, float, int)) for input_t in nest.flatten(inputs))):
        inputs = nest.map_structure(tensor_conversion.convert_to_tensor_v2_with_dispatch, inputs)
    outs = model(inputs, **kwargs)
    outs = nest.flatten(outs)
    if targets:
        targets = training_utils_v1.cast_if_floating_dtype_and_mismatch(targets, outs)
    if sample_weights:
        new_sample_weights = []
        for val in sample_weights:
            if val is not None:
                new_sample_weights.append(training_utils_v1.cast_if_floating_dtype(tensor_conversion.convert_to_tensor_v2_with_dispatch(val)))
            else:
                new_sample_weights.append(None)
        sample_weights = new_sample_weights
    masks = [getattr(t, '_keras_mask', None) for t in outs]
    targets = nest.flatten(targets)
    output_losses = []
    with backend.name_scope('loss'):
        loss_fns = [loss_fn for loss_fn in model.loss_functions if loss_fn is not None]
        custom_losses = model.losses
        if not loss_fns and (not custom_losses):
            if training:
                raise ValueError('The model cannot be trained because it has no loss to optimize.')
            else:
                raise ValueError('The model cannot be evaluated because it has no loss to compute.')
        for (i, loss_fn) in enumerate(loss_fns):
            weights = sample_weights[i] if sample_weights else None
            mask = masks[i]
            with backend.name_scope(model.output_names[i] + '_loss'):
                if mask is not None:
                    mask = math_ops.cast(mask, outs[i].dtype)
                    if weights is None:
                        weights = mask
                    else:
                        weights = math_ops.cast(weights, outs[i].dtype)
                        (mask, _, weights) = losses_utils.squeeze_or_expand_dimensions(mask, sample_weight=weights)
                        weights *= mask
                if <MASK>:
                    per_sample_losses = loss_fn.call(targets[i], outs[i])
                    weighted_losses = losses_utils.compute_weighted_loss(per_sample_losses, sample_weight=weights, reduction=losses_utils.ReductionV2.NONE)
                    loss_reduction = loss_fn.reduction
                    if loss_reduction == losses_utils.ReductionV2.AUTO:
                        loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
                    output_loss = losses_utils.reduce_weighted_loss(weighted_losses, reduction=loss_reduction)
                else:
                    output_loss = loss_fn(targets[i], outs[i], sample_weight=weights)
                    loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
            if len(model.outputs) > 1:
                output_losses.append(output_loss_metrics[i](output_loss))
            if loss_reduction == losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE:
                output_loss = losses_utils.scale_loss_for_distribution(output_loss)
            total_loss += model._loss_weights_list[i] * output_loss
        if custom_losses:
            total_loss += losses_utils.scale_loss_for_distribution(math_ops.add_n(custom_losses))
    return (outs, total_loss, output_losses, masks)

def index_output_size_and_inner_fn(x_size, indices, tensor_indices, tensor_size, indices_loaders, indexed_size, x_loader, check, wrap_neg=True):
    non_consecutive_tensors = False
    for (previous, current) in itertools.pairwise(tensor_indices):
        if <MASK>:
            non_consecutive_tensors = True
    output_size = [x_size[i] for (i, val) in enumerate(indices) if val is None]
    output_size = [*output_size, *x_size[len(output_size) + len(tensor_indices):]]
    first_tensor_index = tensor_indices[0]
    if non_consecutive_tensors:
        output_size = tensor_size + output_size
    else:
        output_size = output_size[:first_tensor_index] + tensor_size + output_size[first_tensor_index:]

    def fn(idx):
        assert len(idx) == len(output_size)
        assert len(indices_loaders) == len(indexed_size)
        rank = len(tensor_size)
        new_index = []
        first_tensor_index = tensor_indices[0]
        start_offset = 0 if non_consecutive_tensors else first_tensor_index
        next_idx = 0
        for i in range(tensor_indices[-1] + 1):
            if i == start_offset:
                next_idx += rank
            if indices[i] is None:
                assert next_idx < len(idx)
                new_index.append(idx[next_idx])
                next_idx += 1
            else:
                loader = indices_loaders[i]
                assert loader is not None
                size = indexed_size[i]
                new_index.append(ops.indirect_indexing(loader(idx[start_offset:start_offset + rank]), size, check=check, wrap_neg=wrap_neg))
        new_index = [*new_index, *idx[next_idx:]]
        return new_index if x_loader is None else x_loader(new_index)
    return (output_size, fn)

def _validate_y_class_weight(self, y):
    check_classification_targets(y)
    y = np.copy(y)
    expanded_class_weight = None
    if self.class_weight is not None:
        y_original = np.copy(y)
    self.classes_ = []
    self.n_classes_ = []
    y_store_unique_indices = np.zeros(y.shape, dtype=int)
    for k in range(self.n_outputs_):
        (classes_k, y_store_unique_indices[:, k]) = np.unique(y[:, k], return_inverse=True)
        self.classes_.append(classes_k)
        self.n_classes_.append(classes_k.shape[0])
    y = y_store_unique_indices
    if self.class_weight is not None:
        valid_presets = ('balanced', 'balanced_subsample')
        if isinstance(self.class_weight, str):
            if self.class_weight not in valid_presets:
                raise ValueError('Valid presets for class_weight include "balanced" and "balanced_subsample".Given "%s".' % self.class_weight)
            if self.warm_start:
                warn('class_weight presets "balanced" or "balanced_subsample" are not recommended for warm_start if the fitted data differs from the full dataset. In order to use "balanced" weights, use compute_class_weight ("balanced", classes, y). In place of y you can use a large enough sample of the full training set target to properly estimate the class frequency distributions. Pass the resulting weights as the class_weight parameter.')
        if self.class_weight != 'balanced_subsample' or not self.bootstrap:
            if <MASK>:
                class_weight = 'balanced'
            else:
                class_weight = self.class_weight
            expanded_class_weight = compute_sample_weight(class_weight, y_original)
    return (y, expanded_class_weight)

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    tf_args = [self] + args
    if can_dispatch_torch_function(tx, tf_args, kwargs):
        import torch
        if _is_attr_overridden(tx, self, name):
            unimplemented_v2(gb_type='Tensor subclass overridden method call', context=f'{name}', explanation="`torch.compile` currently can't trace this", hints=[f'Avoid calling {name} of tensor subclass in torch.compile region', f'Renaming method `{name}` of type {self.class_type}', *graph_break_hints.SUPPORTABLE])
        if <MASK>:
            source = AttrSource(AttrSource(self.source, '__class__'), name)
            value = inspect.getattr_static(self.python_type(), name)
        else:
            source = None
            value = getattr(torch.Tensor, name)
        func_var = VariableTracker.build(tx, value, source)
        return dispatch_torch_function(tx, func_var, tf_args, kwargs)
    else:
        return super().call_method(tx, name, args, kwargs)

def normalizer(_func=None, *, promote_scalar_result=False):

    def normalizer_inner(func):

        @functools.wraps(func)
        def wrapped(*args, **kwds):
            sig = inspect.signature(func)
            params = sig.parameters
            first_param = next(iter(params.values()))
            if first_param.kind == inspect.Parameter.VAR_POSITIONAL:
                args = [maybe_normalize(arg, first_param) for arg in args]
            else:
                args = tuple((maybe_normalize(arg, parm) for (arg, parm) in zip(args, params.values()))) + args[len(params.values()):]
            kwds = {name: maybe_normalize(arg, params[name]) if name in params else arg for (name, arg) in kwds.items()}
            result = func(*args, **kwds)
            bound_args = None
            if 'keepdims' in params and params['keepdims'].annotation == 'KeepDims':
                bound_args = sig.bind(*args, **kwds).arguments
                if bound_args.get('keepdims', False):
                    tensor = args[0]
                    axis = bound_args.get('axis')
                    result = _util.apply_keepdims(result, axis, tensor.ndim)
            if 'out' in params:
                if <MASK>:
                    bound_args = sig.bind(*args, **kwds).arguments
                out = bound_args.get('out')
                result = maybe_copy_to(out, result, promote_scalar_result)
            result = wrap_tensors(result)
            return result
        return wrapped
    if _func is None:
        return normalizer_inner
    else:
        return normalizer_inner(_func)

def _preprocess_conv3d_input(x, data_format):
