def _lazy_apply_wrapper(func: Callable[..., Array | ArrayLike | Sequence[Array | ArrayLike]], as_numpy: bool, multi_output: bool, xp: ModuleType) -> Callable[..., tuple[Array, ...]]:
    """
    Helper of `lazy_apply`.

    Given a function that accepts one or more arrays as positional arguments and returns
    a single array-like or a sequence of array-likes, return a function that accepts the
    same number of Array API arrays and always returns a tuple of Array API array.

    Any keyword arguments are passed through verbatim to the wrapped function.
    """

    @wraps(func)
    def wrapper(*args: Array | complex | None, **kwargs: Any) -> tuple[Array, ...]:
        args_list = []
        device = None
        for arg in args:
            if arg is not None and (not is_python_scalar(arg)):
                if device is None:
                    device = _compat.device(arg)
                if <MASK>:
                    import numpy as np
                    arg = cast(Array, np.asarray(arg))
            args_list.append(arg)
        assert device is not None
        out = func(*args_list, **kwargs)
        if multi_output:
            assert isinstance(out, Sequence)
            return tuple((xp.asarray(o, device=device) for o in out))
        return (xp.asarray(out, device=device),)
    return wrapper

@staticmethod
def create(tx: 'InstructionTranslator', value) -> VariableTracker:
    value_type = type(value)
    fast_handler = SourcelessBuilder._type_handlers.get(value_type)
    if fast_handler:
        return fast_handler(tx, value)
    if isinstance(value, VariableTracker):
        return value
    elif isinstance(value, dataclasses._HAS_DEFAULT_FACTORY_CLASS):
        return UserDefinedObjectVariable(value)
    elif ConstantVariable.is_literal(value):
        return ConstantVariable.create(value)
    elif callable(value) and trace_rules.lookup_callable(value) is not None:
        if trace_rules.is_callable_allowed(value):
            tx.output.has_user_defined_allowed_in_graph = True
        return trace_rules.lookup_callable(value)(value)
    elif <MASK>:
        obj = trace_rules.lookup_callable(value.__self__)(value.__self__)
        return GetAttrVariable(obj, '__new__')
    elif is_function_or_wrapper(value):
        return trace_rules.lookup(value)(value)
    elif isinstance(value, (enum.Enum, torch.DispatchKey, torch._C._functorch.TransformType)):
        return EnumVariable(value)
    elif isinstance(value, (type, abc.ABCMeta)):
        return UserDefinedClassVariable(value)
    elif isinstance(value, types.MethodWrapperType):
        return MethodWrapperVariable(value)
    elif isinstance(value, types.MethodType) and isinstance(value.__self__, (type, abc.ABCMeta)):
        assert getattr(value.__self__, value.__func__.__name__) == value
        cls_obj_vt = SourcelessBuilder.create(tx, value.__self__)
        try:
            return cls_obj_vt.var_getattr(tx, value.__func__.__name__)
        except NotImplementedError:
            pass
    elif isinstance(value, torch.fx.graph_module.GraphModule):
        return SourcelessGraphModuleVariable(value)
    elif isinstance(value, (torch.utils._pytree.TreeSpec, torch.utils._pytree.LeafSpec)):
        return UserDefinedObjectVariable(value)
    elif PlacementVariable.is_placement(value):
        return PlacementVariable(value)
    elif DeviceMeshVariable.is_device_mesh(value):
        return DeviceMeshVariable(value)
    elif value is functools.wraps:
        return FunctoolsWrapsVariable(value)
    elif isinstance(value, re.Pattern):
        return RegexPatternVariable(value)
    elif isinstance(value, torch._dynamo.variables.lazy.LazySymNodeFormatString):
        return ConstantVariable.create(str(value))
    elif isinstance(value, type(torch._higher_order_ops.flex_attention_backward)):
        return torch._dynamo.variables.higher_order_ops.FlexAttentionBackwardHighOrderVariable(value)
    elif isinstance(value, types.GenericAlias):
        return TypingVariable(value)
    elif is_namedtuple(value):
        output = [SourcelessBuilder.create(tx, getattr(value, name)) for name in namedtuple_fields(type(value))]
        return NamedTupleVariable(output, tuple_cls=type(value))
    elif isinstance(value, torch.SymInt) and value.node.expr in tx.output.bound_symbols:
        proxy = tx.output.bound_symbols[value.node.expr]
        return SymNodeVariable.create(tx, proxy)
    unimplemented_v2(gb_type='Unexpected type in sourceless builder', context=f'{value_type.__module__}.{value_type.__qualname__}', explanation=f'SourcelessBuilder.create does not know how to wrap {value_type}', hints=[*graph_break_hints.DYNAMO_BUG])

def generate_py_arg_inner(lines, raw_arg, arg_type):

    def handle_scalar(scalar):
        if isinstance(scalar, int):
            return f'PyLong_FromLongLong({scalar})'
        if isinstance(scalar, float):
            return f'PyFloat_FromDouble({self.generate_float_value(scalar)})'
        if isinstance(scalar, bool):
            return f'PyBool_FromLong({(1 if scalar else 0)})'
        if isinstance(scalar, complex):
            real = self.generate_float_value(scalar.real)
            imag = self.generate_float_value(scalar.imag)
            return f'PyComplex_FromDoubles({real}, {imag})'
        if isinstance(scalar, SymTypes):
            scalar_var = cexpr(scalar.node.expr)
            if isinstance(scalar, torch.SymBool):
                return f'PyBool_FromLong({scalar_var})'
            if isinstance(scalar, torch.SymFloat):
                return f'PyFloat_FromDouble({scalar_var})'
            return f'PyLong_FromLongLong({scalar_var})'
        raise NotImplementedError(f'scalar {scalar}, {type(scalar)} cannot be handled by handle_scalar')
    if raw_arg is None:
        lines.append('Py_INCREF(Py_None);\n')
        return 'Py_None'
    elif isinstance(arg_type, torch.TensorType):
        if not hasattr(raw_arg, 'codegen_reference'):
            return handle_scalar(raw_arg)
        base_handle = self.create_tmp_raii_handle_var_if_needed(raw_arg.codegen_reference(), lines)
        return f'PyCapsule_New(reinterpret_cast<void*>({base_handle}.get()), NULL, NULL)'
    elif isinstance(arg_type, torch.OptionalType):
        return generate_py_arg_inner(lines, raw_arg, arg_type.getElementType())
    elif isinstance(arg_type, torch.IntType):
        return f'PyLong_FromLongLong({raw_arg})'
    elif isinstance(arg_type, torch.SymIntType):
        expr = raw_arg.node.expr if isinstance(raw_arg, torch.SymInt) else raw_arg
        return f'PyLong_FromLongLong({cexpr(expr)})'
    elif isinstance(arg_type, torch.FloatType):
        return f'PyFloat_FromDouble({self.generate_float_value(raw_arg)})'
    elif isinstance(arg_type, torch.BoolType):
        return f'PyBool_FromLong({(1 if raw_arg else 0)})'
    elif isinstance(arg_type, torch.StringType):
        return f'PyUnicode_FromString("{raw_arg}")'
    elif isinstance(arg_type, torch.NumberType):
        return handle_scalar(raw_arg)
    elif <MASK>:
        (device_str, device_index) = self.codegen_device(raw_arg).split(', ')
        return f'THPDevice_New(c10::Device(static_cast<c10::DeviceType>({device_str}), {device_index}))'
    elif isinstance(raw_arg, torch.dtype):
        return f'Py_NewRef(torch::getTHPDtype(static_cast<c10::ScalarType>({self.codegen_dtype(raw_arg)})))'
    elif isinstance(raw_arg, torch.layout):
        return f'Py_NewRef(torch::getTHPLayout(static_cast<c10::Layout>({self.codegen_layout(raw_arg)})))'
    elif isinstance(raw_arg, torch.memory_format):
        return f'Py_NewRef(torch::utils::getTHPMemoryFormat(static_cast<c10::MemoryFormat>({self.codegen_memory_format(raw_arg)})))'
    else:
        raise NotImplementedError(f'arg type {arg_type} is not yet supported by custom_op_wrapper')

@tf_export(v1=['report_uninitialized_variables'])
@tf_should_use.should_use_result
def report_uninitialized_variables(var_list=None, name='report_uninitialized_variables'):
    """Adds ops to list the names of uninitialized variables.

  When run, it returns a 1-D tensor containing the names of uninitialized
  variables if there are any, or an empty array if there are none.

  Args:
    var_list: List of `Variable` objects to check. Defaults to the value of
      `global_variables() + local_variables()`
    name: Optional name of the `Operation`.

  Returns:
    A 1-D tensor containing names of the uninitialized variables, or an empty
    1-D tensor if there are no variables or no uninitialized variables.
  """
    if <MASK>:
        var_list = global_variables() + local_variables()
        if not var_list:
            var_list = []
            for op in ops.get_default_graph().get_operations():
                if op.type in ['Variable', 'VariableV2', 'AutoReloadVariable']:
                    var_list.append(op.outputs[0])
    with ops.name_scope(name):
        if var_list:
            init_vars = [state_ops.is_variable_initialized(v) for v in var_list]
        local_device = os.environ.get('TF_DEVICE_FOR_UNINITIALIZED_VARIABLE_REPORTING', '/cpu:0')
        with ops.device(local_device):
            if not var_list:
                return array_ops.constant([], dtype=dtypes.string)
            else:
                variables_mask = math_ops.logical_not(array_ops_stack.stack(init_vars))
                variable_names_tensor = array_ops.constant([s.op.name for s in var_list])
                return array_ops.boolean_mask(variable_names_tensor, variables_mask)

def check(self, model, connection):
    errors = []
    if not (connection.features.supports_table_check_constraints or 'supports_table_check_constraints' in model._meta.required_db_features):
        errors.append(checks.Warning(f'{connection.display_name} does not support check constraints.', hint="A constraint won't be created. Silence this warning if you don't care about it.", obj=model, id='models.W027'))
    elif <MASK>:
        references = set()
        condition = self.condition
        if isinstance(condition, Q):
            references.update(model._get_expr_references(condition))
        if any((isinstance(expr, RawSQL) for expr in condition.flatten())):
            errors.append(checks.Warning(f"Check constraint {self.name!r} contains RawSQL() expression and won't be validated during the model full_clean().", hint="Silence this warning if you don't care about it.", obj=model, id='models.W045'))
        errors.extend(self._check_references(model, references))
    return errors

def traverse_state_dict(state_dict: STATE_DICT_TYPE, visitor: Callable[[OBJ_PATH, STATE_DICT_ITEM], None], keep_traversing: Callable[[STATE_DICT_ITEM], bool]=_keep_visiting_tensors) -> None:
    """
    Invoke ``visitor`` for each value recursively in ``state_dict``.
    Mapping will be traversed and ``visitor`` will be applied to the leaf elements.
    ``visitor`` will only be applied to elements in a list or a tuple, if the
    container contains tensors or mappings.
    """

    def _is_terminal(value: STATE_DICT_ITEM) -> bool:
        values: Collection[STATE_DICT_ITEM]
        if <MASK>:
            return False
        elif isinstance(value, list):
            values = value
        else:
            return True
        for entry in values:
            if isinstance(entry, (Mapping, list)) and (not _is_terminal(entry)):
                return False
            if keep_traversing is not None and keep_traversing(entry):
                return False
        return True

    def _traverse_obj(path: OBJ_PATH, value: STATE_DICT_ITEM) -> None:
        if isinstance(value, Mapping):
            for (k, v) in value.items():
                _traverse_obj(path + (str(k),), v)
        elif _is_terminal(value):
            visitor(path, value)
        elif isinstance(value, (list, tuple)):
            for (i, v) in enumerate(value):
                _traverse_obj(path + (i,), v)
    for (key, value) in state_dict.items():
        _traverse_obj((str(key),), value)

