def codegen_list_tuple_access(basename, indices):
    if len(indices) > 0:
        (itype, i) = indices[0]
        if <MASK>:
            return codegen_list_tuple_access(f'{basename}[{i}]', indices[1:])
        elif issubclass(itype, tuple):
            tuple_access = self.wrapper.codegen_tuple_access(basename, self.result_name, str(i))
            return codegen_list_tuple_access(tuple_access, indices[1:])
        elif issubclass(itype, dict):
            return codegen_list_tuple_access(f"{basename}['{i}']", indices[1:])
        else:
            raise AssertionError('non supported index type: ', itype)
    else:
        return basename

def _check_alias_info(context, real_out, real_in, fake_out, fake_in):
    r_aliasing = outputs_alias_inputs(real_out, real_in)
    f_aliasing = outputs_alias_inputs(fake_out, fake_in)
