    r_identity_eq = outputs_are_inputs(real_out, real_in)
    f_identity_eq = outputs_are_inputs(fake_out, fake_in)
    if r_identity_eq != f_identity_eq:
        raise MetadataMismatchError(f'{context} mismatch in outputs_are_inputs check {f_identity_eq} != {r_identity_eq}')
    r_output_alias_each_other = output_alias_each_other(real_out)
    f_output_alias_each_other = output_alias_each_other(fake_out)
    if r_output_alias_each_other != f_output_alias_each_other:
        raise MetadataMismatchError(f'{context} mismatch in outputs_alias_each_other check {f_output_alias_each_other} != {r_output_alias_each_other}')

@staticmethod
def from_native_function(f: NativeFunction, *, method: bool, fallback_binding: bool=False) -> CppSignatureGroup:
    func = f.func

    def make_sig(*, faithful: bool, symint: bool) -> CppSignature:
        return CppSignature(func=func, faithful=faithful, symint=symint, method=method, fallback_binding=fallback_binding, cpp_no_default_args=f.cpp_no_default_args)

    def make_sigs(*, symint: bool) -> tuple[CppSignature, CppSignature | None]:
        faithful_signature: CppSignature | None = None
        if <MASK>:
            faithful_signature = make_sig(faithful=True, symint=symint)
        signature = make_sig(faithful=False, symint=symint)
        return (signature, faithful_signature)
    (signature, faithful_signature) = make_sigs(symint=False)
    symint_signature: CppSignature | None = None
    symint_faithful_signature: CppSignature | None = None
    if func.has_symint():
        (symint_signature, symint_faithful_signature) = make_sigs(symint=True)
    return CppSignatureGroup(func=func, signature=signature, faithful_signature=faithful_signature, symint_signature=symint_signature, symint_faithful_signature=symint_faithful_signature)

def _Identity(tensor, name=None):
    """Return a tensor with the same shape and contents as the input tensor.

  Args:
    tensor: A Tensor.
    name: A name for this operation (optional).

  Returns:
    A Tensor with the same type and value as the input Tensor.
  """
    tensor = ops.internal_convert_to_tensor_or_composite(tensor, as_ref=True)
    tensor = variable_utils.convert_variables_to_tensors(tensor)
    if isinstance(tensor, tensor_lib.Tensor):
        if tensor.dtype._is_ref_dtype:
            return gen_array_ops.ref_identity(tensor, name=name)
        else:
            return array_ops.identity(tensor, name=name)
    elif <MASK>:
        return nest.map_structure(_Identity, tensor, expand_composites=True)
    else:
        raise TypeError(f"'tensor' must be a Tensor or CompositeTensor. Received: {type(tensor)}.")

@property
def feed_output_shape(self):
    """The output shape for the feedable target."""
    if not self.has_feedable_training_target():
        return None
    if <MASK>:
        if backend.image_data_format() == 'channels_first':
            return (self.shape[0], 1) + self.shape[2:]
        else:
            return self.shape[:-1] + (1,)
    elif not isinstance(self.loss_fn, losses.Loss) or (isinstance(self.loss_fn, losses.LossFunctionWrapper) and getattr(losses, self.loss_fn.fn.__name__, None) is None):
        return None
    else:
        return self.shape

def update(self, other):
    """Updates this jar with cookies from another CookieJar or dict-like"""
    if <MASK>:
        for cookie in other:
            self.set_cookie(copy.copy(cookie))
    else:
        super().update(other)

def _convert_composite_tensor(value, expected_type, path, context):
    """Converts `value` to a value of type `expected_type`."""
    if context == _ConversionContext.SPEC:
        if <MASK>:
            raise TypeError(f"{''.join(path)}: expected a TypeSpec for {expected_type.__name__!r}, got {type(value).__name__!r}")
        return value
    if not isinstance(value, expected_type):
        raise TypeError(f"{''.join(path)}: expected {expected_type.__name__!r}, got {type(value).__name__!r}")
    return value

def prune_conv2d_padded(conv2d_1: nn.Conv2d) -> None:
    parametrization_dict = cast(nn.ModuleDict, conv2d_1.parametrizations)
    weight_parameterizations = cast(ParametrizationList, parametrization_dict.weight)
    for p in weight_parameterizations:
        if isinstance(p, FakeStructuredSparsity):
            mask = cast(Tensor, p.mask)
    with torch.no_grad():
        parametrize.remove_parametrizations(conv2d_1, 'weight', leave_parametrized=True)
    if getattr(conv2d_1, '_bias', None) is not None:
        if conv2d_1.bias is not None:
            new_bias = torch.zeros(conv2d_1.bias.shape)
            new_bias[mask] = conv2d_1.bias[mask]
            new_bias[~mask] = cast(Tensor, conv2d_1._bias)[~mask]
            conv2d_1.bias = nn.Parameter(new_bias)
        else:
            conv2d_1.bias = nn.Parameter(cast(Tensor, conv2d_1._bias))
    elif conv2d_1.bias is not None:
        conv2d_1.bias.data[~mask] = 0
    if <MASK>:
        delattr(conv2d_1, '_bias')

def cast(self, value: Any, casting_context: Any) -> Any:
    if <MASK>:
        raise TypeError(f'[{value!r}] is not of type {self.value_type}.')
    (value_metadata, value_components) = value.__tf_flatten__()
    if self.metadata != value_metadata:
        raise ValueError(f'Metadata mismatch: [{self.metadata!r}] != [{value_metadata!r}].')
    if len(self.components) != len(value_components):
        raise ValueError(f'Lengths of components mismatch: {len(self.components)} != {len(value_components)}.')
    (casted_value_components, was_casted) = util.cast_and_return_whether_casted(self.components, value_components, casting_context)
    if was_casted:
        return self.value_type.__tf_unflatten__(self.metadata, casted_value_components)
    else:
        return value

def map_expr(e: Any) -> Union[float, int, SymInt, SymFloat, SymBool]:
    if <MASK>:
        return int(e)
    if fakify_first_call:
        return shape_env.deserialize_symexpr(e)
    return shape_env.evaluate_symexpr(e)

def __array_finalize__(self, obj):
    """
        Finalizes the masked array.

        """
    self._update_from(obj)
    if isinstance(obj, ndarray):
        if obj.dtype.names is not None:
            _mask = getmaskarray(obj)
        else:
            _mask = getmask(obj)
        if _mask is not nomask and obj.__array_interface__['data'][0] != self.__array_interface__['data'][0]:
            if self.dtype == obj.dtype:
                _mask_dtype = _mask.dtype
            else:
                _mask_dtype = make_mask_descr(self.dtype)
            if self.flags.c_contiguous:
                order = 'C'
            elif <MASK>:
                order = 'F'
            else:
                order = 'K'
            _mask = _mask.astype(_mask_dtype, order)
        else:
            _mask = _mask.view()
    else:
        _mask = nomask
    self._mask = _mask
    if self._mask is not nomask:
        try:
            self._mask.shape = self.shape
        except ValueError:
            self._mask = nomask
        except (TypeError, AttributeError):
            pass
    if self._fill_value is not None:
        self._fill_value = _check_fill_value(self._fill_value, self.dtype)
    elif self.dtype.names is not None:
        self._fill_value = _check_fill_value(None, self.dtype)

def doesnt_use_pandas_warnings(file_obj: IO[str]) -> Iterable[tuple[int, str]]:
    """
    Checking that pandas-specific warnings are used for deprecations.

    Parameters
    ----------
    file_obj : IO
        File-like object containing the Python code to validate.

    Yields
    ------
    line_number : int
        Line number of the warning.
    msg : str
        Explanation of the error.
    """
    contents = file_obj.read()
    lines = contents.split('\n')
    tree = ast.parse(contents)
    for node in ast.walk(tree):
        if <MASK>:
            continue
        if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            if node.func.value.id != 'warnings' or node.func.attr != 'warn':
                continue
        elif isinstance(node.func, ast.Name):
            if node.func.id != 'warn':
                continue
        if any(('# pdlint: ignore[warning_class]' in lines[k] for k in range(node.lineno - 1, node.end_lineno + 1))):
            continue
        values = [arg.id for arg in node.args if isinstance(arg, ast.Name)] + [kw.value.id for kw in node.keywords if kw.arg == 'category']
        for value in values:
            matches = re.match(DEPRECATION_WARNINGS_PATTERN, value)
            if matches is not None:
                yield (node.lineno, f"Don't use {matches[0]}, use a pandas-specific warning in pd.errors instead. You can add `# pdlint: ignore[warning_class]` to override.")

def codegen_block_ptr(self, name: str, var: str, indexing: Union[BlockPtrOptions, TensorDescriptorOptions], other='') -> tuple[str, str]:
    """Generate a block pointer or tensor descriptor for Triton kernel operations.

        This method creates either a block pointer (for regular Triton operations) or
        a tensor descriptor (for TMA operations) based on the indexing type. It handles
        caching and reuse of descriptors for performance optimization.

        Args:
            name: The name of the buffer/tensor being accessed
            var: The variable name for the pointer
            indexing: Block pointer options or tensor descriptor options containing
                     indexing information and boundary check settings
            other: Additional parameters string (e.g., padding options)

        Returns:
            A tuple containing:
            - block_descriptor: The generated block pointer or tensor descriptor variable name
            - other: Modified additional parameters string with boundary check options
        """
    check = indexing.boundary_check()
    if isinstance(indexing, TensorDescriptorOptions):
        if check and other:
            assert other == ', other=0.0'
            other = ''
    elif not check:
        other = ''
    elif other:
        assert other == ', other=0.0'
        other = f", boundary_check={check!r}, padding_option='zero'"
    else:
        other = f', boundary_check={check!r}'
    if self.inside_reduction and self.range_trees[-1].is_loop and indexing.has_rindex() or indexing.can_lift:
        if <MASK>:
            block_descriptor = self.prologue_cache[var]
        else:
            block_ptr_line = indexing.format(var, roffset=False)
            block_var = self.cse.try_get(block_ptr_line)
            if block_var:
                return (str(block_var), other)
            block_descriptor_id = next(self.block_ptr_id)
            if isinstance(indexing, BlockPtrOptions):
                block_descriptor = f'block_ptr{block_descriptor_id}'
            else:
                block_descriptor = f'tma_descriptor{block_descriptor_id}'
            named_var = self.cse.namedvar(block_descriptor, dtype=torch.uint64, shape=[])
            self.cse.put(block_ptr_line, named_var)
            line_body = DeferredLine(name, f'{block_descriptor} = {block_ptr_line}')
            if indexing.can_lift:
                self.prologue.writeline(line_body)
                self.prologue_cache[var] = block_descriptor
            else:
                self.body.writeline(line_body)
            if isinstance(indexing, BlockPtrOptions):
                self.block_ptr_to_buffer[block_descriptor] = name
                for symt in TritonSymbols.reduction_types:
                    advance_offsets = indexing.advance_roffset(symt)
                    if all((V.graph.sizevars.statically_known_equals(offset, sympy.Integer(0)) for offset in advance_offsets)):
                        continue
                    advancements = self.pointer_advancements[symt]
                    assert block_descriptor not in advancements, f"duplicate advancement for pointer '{block_descriptor}' at type '{symt}'"
                    advancements[block_descriptor] = advance_offsets
    else:
        block_descriptor = indexing.format(var)
    return (block_descriptor, other)

@classmethod
def from_model(cls, model, exclude_rels=False):
    """Given a model, return a ModelState representing it."""
    fields = []
    for field in model._meta.local_fields:
        if getattr(field, 'remote_field', None) and exclude_rels:
            continue
        if isinstance(field, models.OrderWrt):
            continue
        name = field.name
        try:
            fields.append((name, field.clone()))
        except TypeError as e:
            raise TypeError("Couldn't reconstruct field %s on %s: %s" % (name, model._meta.label, e))
    if not exclude_rels:
        for field in model._meta.local_many_to_many:
            name = field.name
            try:
                fields.append((name, field.clone()))
            except TypeError as e:
                raise TypeError("Couldn't reconstruct m2m field %s on %s: %s" % (name, model._meta.object_name, e))
    options = {}
    for name in DEFAULT_NAMES:
        if name in ['apps', 'app_label']:
            continue
        elif name in model._meta.original_attrs:
            if <MASK>:
                ut = model._meta.original_attrs['unique_together']
                options[name] = set(normalize_together(ut))
            elif name == 'indexes':
                indexes = [idx.clone() for idx in model._meta.indexes]
                for index in indexes:
                    if not index.name:
                        index.set_name_with_model(model)
                options['indexes'] = indexes
            elif name == 'constraints':
                options['constraints'] = [con.clone() for con in model._meta.constraints]
            else:
                options[name] = model._meta.original_attrs[name]
    if exclude_rels:
        for key in ['unique_together', 'order_with_respect_to']:
            if key in options:
                del options[key]
    elif options.get('order_with_respect_to') in {field.name for field in model._meta.private_fields}:
        del options['order_with_respect_to']

    def flatten_bases(model):
        bases = []
        for base in model.__bases__:
            if hasattr(base, '_meta') and base._meta.abstract:
                bases.extend(flatten_bases(base))
            else:
                bases.append(base)
        return bases
    flattened_bases = sorted(set(flatten_bases(model)), key=lambda x: model.__mro__.index(x))
    bases = tuple((base._meta.label_lower if hasattr(base, '_meta') else base for base in flattened_bases))
    if not any((isinstance(base, str) or issubclass(base, models.Model) for base in bases)):
        bases = (models.Model,)
    managers = []
    manager_names = set()
    default_manager_shim = None
    for manager in model._meta.managers:
        if manager.name in manager_names:
            continue
        elif manager.use_in_migrations:
            new_manager = copy.copy(manager)
            new_manager._set_creation_counter()
        elif manager is model._base_manager or manager is model._default_manager:
            new_manager = models.Manager()
            new_manager.model = manager.model
            new_manager.name = manager.name
            if manager is model._default_manager:
                default_manager_shim = new_manager
        else:
            continue
        manager_names.add(manager.name)
        managers.append((manager.name, new_manager))
    if managers == [('objects', default_manager_shim)]:
        managers = []
    return cls(model._meta.app_label, model._meta.object_name, fields, options, bases, managers)

def _maybe_insert_input_observer_for_arg_or_kwarg(node: Union[Node, Any], arg: Argument, qconfig: QConfigAny, model: torch.nn.Module, named_modules: dict[str, torch.nn.Module], obs_or_fq_map: dict[EdgeOrNode, ObserverOrFakeQuantize], is_qat: bool, model_device: Optional[torch.device]=None) -> Argument:
    """
    Given a `node` and an `arg`, inserts an input observer between
    `node` and `arg` if necessary.
    """
    if isinstance(arg, (list, tuple)):
        new_arg_to_return = []
        for inner_arg in arg:
            new_inner_arg = _maybe_insert_input_observer_for_arg_or_kwarg(node, inner_arg, qconfig, model, named_modules, obs_or_fq_map, is_qat, model_device)
            new_arg_to_return.append(new_inner_arg)
        return type(arg)(new_arg_to_return)
    if <MASK>:
        return arg
    if not isinstance(arg, Node):
        raise AssertionError(f'expect original argument to be a Node, but got: {type(arg)}')
    new_arg = arg
    original_arg = arg
    while _is_activation_post_process_node(original_arg, named_modules):
        original_arg = original_arg.args[0]
    if not isinstance(original_arg, Node):
        raise AssertionError(f'expect original argument to be a Node, but got: {type(original_arg)}')
    input_edge = (original_arg, node)
    if input_edge not in obs_or_fq_map:
        return new_arg
    input_edge_obs_or_fq = obs_or_fq_map[input_edge]
    if input_edge_obs_or_fq is None:
        return new_arg
    arg_as_output_obs_or_fq = obs_or_fq_map.get(original_arg)
    if arg_as_output_obs_or_fq is not None and id(arg_as_output_obs_or_fq) == id(input_edge_obs_or_fq):
        return new_arg
    for maybe_obs_node in arg.users.keys():
        if not _is_activation_post_process_node(maybe_obs_node, named_modules):
            continue
        maybe_obs_mod = named_modules[maybe_obs_node.target]
        if id(maybe_obs_mod) == id(input_edge_obs_or_fq):
            return maybe_obs_node
    if not isinstance(model.graph, Graph):
        raise AssertionError(f'Expected model.graph to be a torch.fx.Graph, got {type(model.graph)}')
    new_arg = _insert_obs_or_fq(arg, input_edge_obs_or_fq, model, named_modules, model.graph, model_device)
    return new_arg

def __call__(self, body_fn, args, kwargs, hints):
    """
        Call implementation of hints_wrapper

        Args:
            body_fn (Callable): A callable function that is within the scope
             that is being traced.

            args (Tuple of torch.Tensor/int/float/bool): A tuple of inputs to
             body_fn.

            kwargs (dict): Keyword argument to the body_fn.

            hints (dict): A dict of context hints which could be passed to
             backend compiler.
        """
    if not isinstance(args, tuple):
        raise RuntimeError(f'args must be a tuple, got {type(args)}')
    if not all((isinstance(t, (torch.Tensor, int, float, bool)) for t in args)):
        raise RuntimeError(f'args must be a tuple of tensors, ints, floats, or bools, got {args}')
    if <MASK>:
        raise RuntimeError(f'kwargs must be a dict, got {type(kwargs)}')
    if len(kwargs) > 0:
        raise RuntimeError(f'kwargs except for hints are not supported, got {kwargs}')
    if not isinstance(hints, dict):
        raise RuntimeError(f'hints must be a dict, got {type(hints)}')
    for (k, v) in hints.items():
        if not isinstance(k, str):
            raise RuntimeError(f'hints key must be a str, got {k}.')
        if not isinstance(v, (int, float, bool, str)):
            raise RuntimeError(f'hints must be a dict containing int, float, bool or str value, got value {v} for key {k}.')
    return super().__call__(body_fn, args, kwargs, hints)

@register_lowering(aten.cat)
def cat(inputs, dim=0):
    cpu_device = inputs[0].get_device().type == 'cpu'
    if cpu_device and all((input.get_dtype() in [torch.int8, torch.uint8] for input in inputs)):
        for input in inputs:
            input.realize()
        if all((len(input.get_size()) == 4 for input in inputs)):
            (inputs, _) = require_channels_last(aten.cat, *inputs)
        return fallback_handler(aten.cat.default)(inputs, dim)
    if len(inputs) == 1:
        return clone(inputs[0])
    dim = _validate_dim(inputs[0], dim, 0)
    dtype = get_promoted_dtype(*inputs, type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
    inputs = [to_dtype(inp, dtype) for inp in inputs]

    def unwrap_tensor(x: Union[TensorBox, ir.StorageBox]) -> ir.IRNode:
        if <MASK>:
            if isinstance(x.data, ir.BaseView):
                return x.data.unwrap_view()
            else:
                return x.data
        if isinstance(x, ir.StorageBox):
            return x.data
        return x

    def is_reduction(t):
        return isinstance(t, ir.ComputedBuffer) and isinstance(t.data, ir.Reduction)

    def can_fuse_reduction(t):
        if isinstance(t, (TensorBox, ir.StorageBox)):
            return can_fuse_reduction(unwrap_tensor(t))
        return is_reduction(t) or (isinstance(t, ir.Pointwise) and any((can_fuse_reduction(V.graph.get_buffer(read)) for read in t.get_read_names())))
    fusable_reduction = any((can_fuse_reduction(t) for t in inputs))

    def should_lower_cat_input(x) -> bool:
        if ir.is_storage_and_layout(x):
            (storage, _) = ir.as_storage_and_layout(x, freeze=False)
            return not ir.ConcatKernel.can_realize_into_without_copy(storage)
        if isinstance(x, (TensorBox, ir.StorageBox)):
            return should_lower_cat_input(unwrap_tensor(x))
        if isinstance(x, ir.Pointwise):
            return True
        return False
    if config.force_pointwise_cat:
        return pointwise_cat(inputs, dim)
    if cpu_device:
        return TensorBox(ir.ConcatKernel.create(inputs, dim))

    def op_count(x):
        if isinstance(x, (TensorBox, ir.StorageBox)):
            return op_count(unwrap_tensor(x))
        if not isinstance(x, ir.Pointwise):
            return 0
        count = x.inner_fn_opcount().num_ops
        for read in x.get_read_names():
            count += op_count(V.graph.get_buffer(read))
        return count
    MAX_COMPLEX_POINTWISE_CAT = 8
    MAX_SIMPLE_OP_COUNT = 2

    def additional_pointwise_ops(op: torch._ops.OpOverload):
        return op in (aten.cat.default, aten.constant_pad_nd.default)
    if len(inputs) <= MAX_COMPLEX_POINTWISE_CAT or (len(inputs) <= config.max_pointwise_cat_inputs and all((op_count(t) <= MAX_SIMPLE_OP_COUNT for t in inputs))):
        pointwise_uses = all((is_pointwise_use(use, additional_pointwise_ops) for use in V.current_node.users))
        fuse_pointwise_use = any((should_lower_cat_input(inp) for inp in inputs)) and pointwise_uses
        horizontal_fuse_cat = all((should_lower_cat_input(inp) for inp in inputs)) and (not any((can_fuse_reduction(t) for t in inputs)))
        if fuse_pointwise_use or (horizontal_fuse_cat and (not fusable_reduction)):
            return pointwise_cat(inputs, dim)
    return TensorBox(ir.ConcatKernel.create(inputs, dim))

def _match(self, pattern, parent, field, child):
    if <MASK>:
        return True
    else:
        return pattern.matches(parent, field, child)

def polyfit(x, y, deg, rcond=None, full=False, w=None, cov=False):
    """
    Any masked values in x is propagated in y, and vice-versa.

    """
    x = asarray(x)
    y = asarray(y)
    m = getmask(x)
    if y.ndim == 1:
        m = mask_or(m, getmask(y))
    elif y.ndim == 2:
        my = getmask(mask_rows(y))
        if my is not nomask:
            m = mask_or(m, my[:, 0])
    else:
        raise TypeError('Expected a 1D or 2D array for y!')
    if <MASK>:
        w = asarray(w)
        if w.ndim != 1:
            raise TypeError('expected a 1-d array for weights')
        if w.shape[0] != y.shape[0]:
            raise TypeError('expected w and y to have the same length')
        m = mask_or(m, getmask(w))
    if m is not nomask:
        not_m = ~m
        if w is not None:
            w = w[not_m]
        return np.polyfit(x[not_m], y[not_m], deg, rcond, full, w, cov)
    else:
        return np.polyfit(x, y, deg, rcond, full, w, cov)

def is_channels_last_contiguous_2d(a: Tensor, false_if_dde=False) -> bool:
    if a.ndim != 4:
        return False
    from torch.fx.experimental.symbolic_shapes import guard_or_false, guard_or_true

    def eval_eager(x):
        return bool(x)
    maybe_guard_or_false = guard_or_false if false_if_dde else eval_eager
    maybe_guard_or_true = guard_or_true if false_if_dde else eval_eager
    expected_stride = 1
    for idx in (1, 3, 2, 0):
        length = a.shape[idx]
        if maybe_guard_or_false(length == 1):
            continue
        stride = a.stride()[idx]
        if <MASK>:
            return False
        expected_stride *= length
    return True

def __init__(self, data=None, index: Axes | None=None, columns: Axes | None=None, dtype: Dtype | None=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if isinstance(data, DataFrame):
        data = data._mgr
        allow_mgr = True
        if not copy:
            data = data.copy(deep=False)
    if isinstance(data, BlockManager):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        if index is None and columns is None and (dtype is None) and (not copy):
            NDFrame.__init__(self, data)
            return
    if isinstance(index, set):
        raise ValueError('index cannot be a set')
    if isinstance(columns, set):
        raise ValueError('columns cannot be a set')
    if copy is None:
        if isinstance(data, dict):
            copy = True
        elif not isinstance(data, (Index, DataFrame, Series)):
            copy = True
        else:
            copy = False
    if data is None:
        index = index if index is not None else default_index(0)
        columns = columns if columns is not None else default_index(0)
        dtype = dtype if dtype is not None else pandas_dtype(object)
        data = []
    if isinstance(data, BlockManager):
        mgr = self._init_mgr(data, axes={'index': index, 'columns': columns}, dtype=dtype, copy=copy)
    elif isinstance(data, dict):
        mgr = dict_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, ma.MaskedArray):
        from numpy.ma import mrecords
        if <MASK>:
            raise TypeError('MaskedRecords are not supported. Pass {name: data[name] for name in data.dtype.names} instead')
        data = sanitize_masked_array(data)
        mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, (np.ndarray, Series, Index, ExtensionArray)):
        if data.dtype.names:
            data = cast(np.ndarray, data)
            mgr = rec_array_to_mgr(data, index, columns, dtype, copy)
        elif isinstance(data, (ABCSeries, ABCIndex)) and data.name is not None:
            mgr = dict_to_mgr({data.name: data}, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif is_list_like(data):
        if not isinstance(data, abc.Sequence):
            if hasattr(data, '__array__'):
                data = np.asarray(data)
            else:
                data = list(data)
        if len(data) > 0:
            if is_dataclass(data[0]):
                data = dataclasses_to_dicts(data)
            if not isinstance(data, np.ndarray) and treat_as_nested(data):
                if columns is not None:
                    columns = ensure_index(columns)
                (arrays, columns, index) = nested_data_to_arrays(data, columns, index, dtype)
                mgr = arrays_to_mgr(arrays, columns, index, dtype=dtype)
            else:
                mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = dict_to_mgr({}, index, columns if columns is not None else default_index(0), dtype=dtype)
    else:
        if index is None or columns is None:
            raise ValueError('DataFrame constructor not properly called!')
        index = ensure_index(index)
        columns = ensure_index(columns)
        if not dtype:
            (dtype, _) = infer_dtype_from_scalar(data)
        if isinstance(dtype, ExtensionDtype):
            values = [construct_1d_arraylike_from_scalar(data, len(index), dtype) for _ in range(len(columns))]
            mgr = arrays_to_mgr(values, columns, index, dtype=None)
        else:
            arr2d = construct_2d_arraylike_from_scalar(data, len(index), len(columns), dtype, copy)
            mgr = ndarray_to_mgr(arr2d, index, columns, dtype=arr2d.dtype, copy=False)
    NDFrame.__init__(self, mgr)

def __next__(self):
    if <MASK>:
        raise StopIteration
    result = WeakTensor.from_tensor(self._weak_tensor.tensor[self._index])
    self._index += 1
    return result

@property
def underlying_value(self):
    if <MASK>:
        return self.vt.original_value()
    if isinstance(self.vt, variables.TensorVariable):
        x = self.vt.as_proxy().node.meta['example_value']
    elif isinstance(self.vt, variables.TupleVariable):
        Hashable = ConstDictVariable._HashableTracker
        x = tuple((Hashable(e).underlying_value for e in self.vt.items))
    elif isinstance(self.vt, variables.NNModuleVariable):
        return self.vt.value
    elif isinstance(self.vt, variables.UnspecializedNNModuleVariable):
        return self.vt.value
    elif isinstance(self.vt, variables.UserFunctionVariable):
        return self.vt.get_function()
    elif isinstance(self.vt, variables.WeakRefVariable):
        Hashable = ConstDictVariable._HashableTracker
        return Hashable(self.vt.referent_vt).underlying_value
    elif isinstance(self.vt, variables.FrozenDataClassVariable):
        Hashable = ConstDictVariable._HashableTracker
        fields_values = {k: Hashable(v).underlying_value for (k, v) in self.vt.fields.items()}
        return variables.FrozenDataClassVariable.HashWrapper(self.vt.python_type(), fields_values)
    elif isinstance(self.vt, variables.UserDefinedObjectVariable):
        return self.vt.value
    else:
        x = self.vt.as_python_constant()
    return x

def compute_potential_hidden_nodes(self, nodes_to_check: Iterable[fx.Node], limit_coll_per_compute: bool=False) -> dict[fx.Node, fx.Node]:
    """
        Returns a dict containing a mapping of nodes which could potentially be hidden to their hiding node
        """
    used_compute_nodes: OrderedSet[fx.Node] = OrderedSet()

    def could_be_hidden(start: fx.Node) -> fx.Node | None:
        for compute_node in self.compute_nodes:
            if limit_coll_per_compute and compute_node in used_compute_nodes:
                continue
            if <MASK>:
                if limit_coll_per_compute:
                    used_compute_nodes.add(compute_node)
                return compute_node
        return None
    potentially_hidden = {}
    for node in nodes_to_check:
        if (mm := could_be_hidden(node)):
            potentially_hidden[node] = mm
    return potentially_hidden

def codegen_reinterpret_view(self, data, size, stride, offset, writeline: Callable[..., None], dtype=None) -> str:
    if size == data.layout.size and stride == data.layout.stride and (offset == data.layout.offset):
        if <MASK>:
            return f'aten.view.dtype({data.get_name()}, {dtype})'
        else:
            return f'{data.get_name()}'
    else:
        size = self.codegen_python_shape_tuple(size)
        stride = self.codegen_python_shape_tuple(stride)
        offset = self.codegen_sizevar(offset)
        if dtype is not None and dtype != data.dtype:
            return f'aten.view.dtype(reinterpret_tensor({data.get_name()}, {size}, {stride}, {offset}), {dtype})'
        else:
            return f'reinterpret_tensor({data.get_name()}, {size}, {stride}, {offset})'

def history_view(self, request, object_id, extra_context=None):
    """The 'history' admin view for this model."""
    from django.contrib.admin.models import LogEntry
    from django.contrib.admin.views.main import PAGE_VAR
    model = self.model
    obj = self.get_object(request, unquote(object_id))
    if obj is None:
        return self._get_obj_does_not_exist_redirect(request, model._meta, object_id)
    if <MASK>:
        raise PermissionDenied
    app_label = self.opts.app_label
    action_list = LogEntry.objects.filter(object_id=unquote(object_id), content_type=get_content_type_for_model(model)).select_related().order_by('action_time')
    paginator = self.get_paginator(request, action_list, 100)
    page_number = request.GET.get(PAGE_VAR, 1)
    page_obj = paginator.get_page(page_number)
    page_range = paginator.get_elided_page_range(page_obj.number)
    context = {**self.admin_site.each_context(request), 'title': _('Change history: %s') % obj, 'subtitle': None, 'action_list': page_obj, 'page_range': page_range, 'page_var': PAGE_VAR, 'pagination_required': paginator.count > 100, 'module_name': str(capfirst(self.opts.verbose_name_plural)), 'object': obj, 'opts': self.opts, 'preserved_filters': self.get_preserved_filters(request), **(extra_context or {})}
    request.current_app = self.admin_site.name
    return TemplateResponse(request, self.object_history_template or ['admin/%s/%s/object_history.html' % (app_label, self.opts.model_name), 'admin/%s/object_history.html' % app_label, 'admin/object_history.html'], context)

def append_needs(need, flag=1):
    if isinstance(need, list):
        for n in need:
            append_needs(n, flag)
    elif isinstance(need, str):
        if not need:
            return
        if need in includes0:
            n = 'includes0'
        elif need in includes:
            n = 'includes'
        elif need in typedefs:
            n = 'typedefs'
        elif need in typedefs_generated:
            n = 'typedefs_generated'
        elif need in cppmacros:
            n = 'cppmacros'
        elif need in cfuncs:
            n = 'cfuncs'
        elif need in callbacks:
            n = 'callbacks'
        elif need in f90modhooks:
            n = 'f90modhooks'
        elif <MASK>:
            n = 'commonhooks'
        else:
            errmess(f'append_needs: unknown need {repr(need)}\n')
            return
        if need in outneeds[n]:
            return
        if flag:
            tmp = {}
            if need in needs:
                for nn in needs[need]:
                    t = append_needs(nn, 0)
                    if isinstance(t, dict):
                        for nnn in t.keys():
                            if nnn in tmp:
                                tmp[nnn] = tmp[nnn] + t[nnn]
                            else:
                                tmp[nnn] = t[nnn]
            for nn in tmp.keys():
                for nnn in tmp[nn]:
                    if nnn not in outneeds[nn]:
                        outneeds[nn] = [nnn] + outneeds[nn]
            outneeds[n].append(need)
        else:
            tmp = {}
            if need in needs:
                for nn in needs[need]:
                    t = append_needs(nn, flag)
                    if isinstance(t, dict):
                        for nnn in t.keys():
                            if nnn in tmp:
                                tmp[nnn] = t[nnn] + tmp[nnn]
                            else:
                                tmp[nnn] = t[nnn]
            if n not in tmp:
                tmp[n] = []
            tmp[n].append(need)
            return tmp
    else:
        errmess(f'append_needs: expected list or string but got :{repr(need)}\n')

def _validate_embedding_bag_param(args, kwargs):
    """
    Validate input params of sharded embeddingBag op.

    Args:
        input: list of ID used for lookup and aggregation.
        weight: sharded weight tensor.
        kwargs: same as normal EmbeddingBag.

    Return: None.
    """
    input = args[0]
    weight = args[1]
    offsets = kwargs.get('offsets')
    per_sample_weights = kwargs.get('per_sample_weights')
    mode = kwargs.get('mode')
    max_norm = kwargs.get('max_norm')
    scale_grad_by_freq = kwargs.get('scale_grad_by_freq')
    sparse = kwargs.get('sparse')
    include_last_offset = kwargs.get('include_last_offset')
    if not isinstance(input, torch.Tensor):
        raise TypeError('input need to be torch.Tensor')
    if offsets is not None and (not isinstance(offsets, torch.Tensor)):
        raise TypeError('offsets need to be torch.Tensor')
    if per_sample_weights is not None and (not isinstance(per_sample_weights, torch.Tensor)):
        raise TypeError('per_sample_weights need to be torch.Tensor')
    if not isinstance(weight, ShardedTensor):
        raise TypeError('weight needs to be ShardedTensor')
    if len(input.size()) > 2:
        raise ValueError('Input more than 2 dims not supported')
    weight_size = weight.size()
    if len(weight_size) != 2:
        raise ValueError('Weight needs to have exactly 2 dims')
    if int(torch.min(input).item()) < 0:
        raise ValueError('Index out of range in Input %d %d', int(torch.min(input).item()), weight_size[1])
    if int(torch.max(input).item()) >= weight_size[0]:
        raise ValueError('Index out of range in Input %d %d', int(torch.max(input).item()), weight_size[1])
    if offsets is not None and len(input.size()) != 1:
        raise ValueError('Input dimension needs to be exactly 1 dim')
    if len(input.size()) == 1 and offsets is None:
        raise ValueError('offsets is required for 1D input')
    if per_sample_weights is not None and per_sample_weights.size() != input.size():
        raise ValueError(f'per_sample_weights size {per_sample_weights.size()} not equal to input size {input.size()}')
    if mode is None:
        mode = 'mean'
    if <MASK>:
        raise ValueError(f"mode '{mode}' is not supported")
    if scale_grad_by_freq:
        raise RuntimeError('nn.Embedding weight sharded with flag on "scale_grad_by_freq" not supported!')
    if sparse:
        raise RuntimeError('nn.Embedding weight sharded with flag on "sparse" not supported!')
    if include_last_offset and offsets is None:
        raise ValueError('offsets is required for flag "include_last_offset"!')
    if include_last_offset and cast(list[int], offsets)[-1] != input.size(0):
        raise ValueError('offsets need to have the input size in the end when the flag "include_last_offset" is on!')
    if max_norm and max_norm <= 0.0:
        raise ValueError('"max_norm" must be larger than zero!')
    if not isinstance(weight._sharding_spec, ChunkShardingSpec):
        raise ValueError('Only ChunkShardingSpec supported for ShardedTensor ops!')
    if len(weight.local_shards()) != 1:
        raise ValueError('Only one local shard supported!')

def validate_file_name(name, allow_relative_path=False):
    if os.path.basename(name) in {'', '.', '..'}:
        raise SuspiciousFileOperation("Could not derive file name from '%s'" % name)
    if allow_relative_path:
        path = pathlib.PurePosixPath(str(name).replace('\\', '/'))
        if path.is_absolute() or '..' in path.parts:
            raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % name)
    elif <MASK>:
        raise SuspiciousFileOperation("File name '%s' includes path elements" % name)
    return name

def forward(self, x: Tensor, hidden: Optional[tuple[Tensor, Tensor]]=None):
    if self.batch_first:
        x = x.transpose(0, 1)
    if hidden is None:
        (hx_fw, cx_fw) = (None, None)
    else:
        (hx_fw, cx_fw) = hidden
    hidden_bw: Optional[tuple[Tensor, Tensor]] = None
    if self.bidirectional:
        if hx_fw is None:
            hx_bw = None
        else:
            hx_bw = hx_fw[1]
            hx_fw = hx_fw[0]
        if cx_fw is None:
            cx_bw = None
        else:
            cx_bw = cx_fw[1]
            cx_fw = cx_fw[0]
        if hx_bw is not None and cx_bw is not None:
            hidden_bw = (hx_bw, cx_bw)
    if hx_fw is None and cx_fw is None:
        hidden_fw = None
    else:
        hidden_fw = (torch.jit._unwrap_optional(hx_fw), torch.jit._unwrap_optional(cx_fw))
    (result_fw, hidden_fw) = self.layer_fw(x, hidden_fw)
    if <MASK>:
        x_reversed = x.flip(0)
        (result_bw, hidden_bw) = self.layer_bw(x_reversed, hidden_bw)
        result_bw = result_bw.flip(0)
        result = torch.cat([result_fw, result_bw], result_fw.dim() - 1)
        if hidden_fw is None and hidden_bw is None:
            h = None
            c = None
        elif hidden_fw is None:
            (h, c) = torch.jit._unwrap_optional(hidden_bw)
        elif hidden_bw is None:
            (h, c) = torch.jit._unwrap_optional(hidden_fw)
        else:
            h = torch.stack([hidden_fw[0], hidden_bw[0]], 0)
            c = torch.stack([hidden_fw[1], hidden_bw[1]], 0)
    else:
        result = result_fw
        (h, c) = torch.jit._unwrap_optional(hidden_fw)
    if self.batch_first:
        result.transpose_(0, 1)
    return (result, (h, c))

def args_maybe_kwargs(self, op_with_args):
    if <MASK>:
        return (op_with_args[0], op_with_args[1], {})
    else:
        return (op_with_args[0], op_with_args[1], op_with_args[2])

def _sample_from_datasets(datasets, weights=None, seed=None, stop_on_empty_dataset=False, rerandomize_each_iteration=None):
    """See `Dataset.sample_from_datasets()` for details."""

    def _skip_datasets_with_zero_weight(datasets, weights):
        datasets_and_weights = [(dataset, weight) for (dataset, weight) in zip(datasets, weights) if weight > 0]
        return zip(*datasets_and_weights) if datasets_and_weights else ([datasets[0].take(0)], [1.0])
    if not datasets:
        raise ValueError('Invalid `datasets`. `datasets` should not be empty.')
    if not isinstance(weights, data_types.DatasetV2):
        if weights is None:
            logits = [[1.0] * len(datasets)]
        else:
            if isinstance(weights, tensor.Tensor):
                if not weights.shape.is_compatible_with([len(datasets)]):
                    raise ValueError(f'Invalid `weights`. The shape of `weights` should be compatible with `[len(datasets)]` but is {weights.shape}.')
            elif <MASK>:
                raise ValueError(f'Invalid `weights`. `weights` should have the same length as `datasets` but got `len(weights)={len(weights)}` vs. `len(datasets)={len(datasets)}`.')
            if not isinstance(weights, tensor.Tensor):
                (datasets, weights) = _skip_datasets_with_zero_weight(datasets, weights)
            weights = ops.convert_to_tensor(weights, name='weights')
            if weights.dtype not in (dtypes.float32, dtypes.float64):
                raise TypeError(f'Invalid `weights`. `weights` type must be either `tf.float32` or `tf.float64` but is {weights.dtype}.')
            logits = array_ops.expand_dims(math_ops.log(weights, name='logits'), 0)
        if len(datasets) == 1:
            return datasets[0]

        def select_dataset_constant_logits(seed):
            return array_ops.squeeze(gen_stateless_random_ops.stateless_multinomial(logits, 1, seed=seed), axis=[0, 1])
        selector_input = map_op._MapDataset(dataset_ops.Dataset.random(seed=seed, rerandomize_each_iteration=rerandomize_each_iteration).batch(2), select_dataset_constant_logits, use_inter_op_parallelism=False)
    else:
        logits_ds = weights.map(lambda *p: math_ops.log(p, name='logits'))

        def select_dataset_varying_logits(logits, seed):
            return array_ops.squeeze(gen_stateless_random_ops.stateless_multinomial(logits, 1, seed=seed), axis=[0, 1])
        logits_and_seeds = dataset_ops.Dataset.zip((logits_ds, dataset_ops.Dataset.random(seed=seed, rerandomize_each_iteration=rerandomize_each_iteration).batch(2)))
        selector_input = map_op._MapDataset(logits_and_seeds, select_dataset_varying_logits, use_inter_op_parallelism=False)
    return directed_interleave_op._directed_interleave(selector_input, datasets, stop_on_empty_dataset)

