@functools.cache
def get_k_splits(m: _IntLike, n: _IntLike, k: _IntLike) -> list[int]:
    k_splits_limit = config.triton.num_decompose_k_splits
    default_k_splits = [16, 32, 64, 128, 256]
    if isinstance(k, sympy.Expr) and (not k.is_number):
        return default_k_splits
    elif k_splits_limit == 0:
        return []
    if isinstance(m, sympy.Expr) and (not m.is_number) or (isinstance(n, sympy.Expr) and (not n.is_number)):
        max_k_split = 256
    else:
        max_k_split = min(k // m, k // n)
    min_k_split = 2
    divisors = sympy.divisors(k)
    divisors = [divisor for divisor in divisors if divisor <= max_k_split and divisor >= min_k_split]
    (pow_of_2_divisors, mul_of_32_divisors, rest_of_splits) = ([], [], [])
    for d in divisors:
        kPart = k // d
        if kPart < 128:
            continue
        if kPart & kPart - 1 == 0 and kPart >= 128:
            pow_of_2_divisors.append(d)
        elif <MASK>:
            mul_of_32_divisors.append(d)
        else:
            rest_of_splits.append(d)
    if config.max_autotune_gemm_search_space == 'EXHAUSTIVE':
        return pow_of_2_divisors + mul_of_32_divisors + rest_of_splits
    best_splits = pow_of_2_divisors + mul_of_32_divisors + rest_of_splits
    return best_splits[:k_splits_limit]

def simplify_with_ranges(expr: Expr, var_ranges: VarRanges) -> Expr:
    nonlocal replacement_count
    if replacement_count != len(self.replacements):
        cache.clear()
        replacement_count = len(self.replacements)
    key = (expr, *var_ranges.items())
    result = cache.get(key)
    if result is None:
        result = self._simplify_with_ranges(expr, var_ranges)
        cache[key] = result
        if <MASK>:
            cache[(result, *var_ranges.items())] = result
    return result

def reduction_dims(shape: ShapeType, dims: Optional[Sequence]) -> tuple[int, ...]:
    if <MASK>:
        return tuple(range(len(shape)))
    dims = tuple((canonicalize_dim(len(shape), idx) for idx in dims))
    validate_no_repeating_dims(dims)
    return dims

def skipIfTorchDynamo(msg="test doesn't currently work with dynamo"):
    """
    Usage:
    @skipIfTorchDynamo(msg)
    def test_blah(self):
        ...
    """
    assert isinstance(msg, str), 'Are you using skipIfTorchDynamo correctly?'

    def decorator(fn):
        if not isinstance(fn, type):

            @wraps(fn)
            def wrapper(*args, **kwargs):
                if <MASK>:
                    raise unittest.SkipTest(msg)
                else:
                    fn(*args, **kwargs)
            return wrapper
        assert isinstance(fn, type)
        if TEST_WITH_TORCHDYNAMO:
            fn.__unittest_skip__ = True
            fn.__unittest_skip_why__ = msg
        return fn
    return decorator

def get_flags_linker_so(self):
    opt = self.linker_so[1:]
    if sys.platform == 'darwin':
        target = os.environ.get('MACOSX_DEPLOYMENT_TARGET', None)
        if <MASK>:
            import sysconfig
            target = sysconfig.get_config_var('MACOSX_DEPLOYMENT_TARGET')
            if not target:
                target = '10.9'
                s = f'Env. variable MACOSX_DEPLOYMENT_TARGET set to {target}'
                warnings.warn(s, stacklevel=2)
            os.environ['MACOSX_DEPLOYMENT_TARGET'] = str(target)
        opt.extend(['-undefined', 'dynamic_lookup', '-bundle'])
    else:
        opt.append('-shared')
    if sys.platform.startswith('sunos'):
        opt.append('-mimpure-text')
    return opt

def main(args: list[str]) -> None:
