def run(self) -> None:
    cmake_cache_vars = get_cmake_cache_vars()
    if cmake_cache_vars['USE_NUMPY']:
        report('-- Building with NumPy bindings')
    else:
        report('-- NumPy not found')
    if cmake_cache_vars['USE_CUDNN']:
        report(f"-- Detected cuDNN at {cmake_cache_vars['CUDNN_LIBRARY']}, {cmake_cache_vars['CUDNN_INCLUDE_DIR']}")
    else:
        report('-- Not using cuDNN')
    if cmake_cache_vars['USE_CUDA']:
        report(f"-- Detected CUDA at {cmake_cache_vars['CUDA_TOOLKIT_ROOT_DIR']}")
    else:
        report('-- Not using CUDA')
    if <MASK>:
        report(f"-- Detected XPU runtime at {cmake_cache_vars['SYCL_LIBRARY_DIR']}")
    else:
        report('-- Not using XPU')
    if cmake_cache_vars['USE_MKLDNN']:
        report('-- Using MKLDNN')
        if cmake_cache_vars['USE_MKLDNN_ACL']:
            report('-- Using Compute Library for the Arm architecture with MKLDNN')
        else:
            report('-- Not using Compute Library for the Arm architecture with MKLDNN')
        if cmake_cache_vars['USE_MKLDNN_CBLAS']:
            report('-- Using CBLAS in MKLDNN')
        else:
            report('-- Not using CBLAS in MKLDNN')
    else:
        report('-- Not using MKLDNN')
    if cmake_cache_vars['USE_NCCL'] and cmake_cache_vars['USE_SYSTEM_NCCL']:
        report(f"-- Using system provided NCCL library at {cmake_cache_vars['NCCL_LIBRARIES']}, {cmake_cache_vars['NCCL_INCLUDE_DIRS']}")
    elif cmake_cache_vars['USE_NCCL']:
        report('-- Building NCCL library')
    else:
        report('-- Not using NCCL')
    if cmake_cache_vars['USE_DISTRIBUTED']:
        if IS_WINDOWS:
            report('-- Building without distributed package')
        else:
            report('-- Building with distributed package: ')
            report(f"  -- USE_TENSORPIPE={cmake_cache_vars['USE_TENSORPIPE']}")
            report(f"  -- USE_GLOO={cmake_cache_vars['USE_GLOO']}")
            report(f"  -- USE_MPI={cmake_cache_vars['USE_OPENMPI']}")
    else:
        report('-- Building without distributed package')
