        report(f"-- Using static dispatch with backend {cmake_cache_vars['STATIC_DISPATCH_BACKEND']}")
    if cmake_cache_vars['USE_LIGHTWEIGHT_DISPATCH']:
        report('-- Using lightweight dispatch')
    if cmake_cache_vars['USE_ITT']:
        report('-- Using ITT')
