    verify_fn(self, _build_dataset, num_outputs=len(filenames) * repetitions, assert_items_equal=reshuffle_each_iteration)

def merge_single_node(node: Node, node_order: Optional[int], id: Optional[int]):

    def _update_partition_map(node: Node, id: int):
        for user_node in node.users:
            target_id = assignment.get(user_node)
            if target_id is not None:
                partition_map[id].add(target_id)
                partition_map[id].update(partition_map[target_id])
    if <MASK>:
        partitions_by_id[assignment[node]].remove_node(node)
    if id is None:
        assignment.pop(node)
    elif id not in partitions_by_id:
        assignment[node] = id
        assert node_order is not None
        partitions_by_id[id] = Partition(id=id, nodes=[node], node_orders=[node_order])
        partition_users[id] = set(node.users)
        _update_partition_map(node, id)
    else:
        assignment[node] = id
        partitions_by_id[id].add_node(node, node_order)

def load_disk(self):
    """Load the migrations from all INSTALLED_APPS from disk."""
    self.disk_migrations = {}
    self.unmigrated_apps = set()
    self.migrated_apps = set()
    for app_config in apps.get_app_configs():
        (module_name, explicit) = self.migrations_module(app_config.label)
        if <MASK>:
            self.unmigrated_apps.add(app_config.label)
            continue
        was_loaded = module_name in sys.modules
        try:
            module = import_module(module_name)
        except ModuleNotFoundError as e:
            if explicit and self.ignore_no_migrations or (not explicit and MIGRATIONS_MODULE_NAME in e.name.split('.')):
                self.unmigrated_apps.add(app_config.label)
                continue
            raise
        else:
            if not hasattr(module, '__path__'):
                self.unmigrated_apps.add(app_config.label)
                continue
            if getattr(module, '__file__', None) is None and (not isinstance(module.__path__, list)):
                self.unmigrated_apps.add(app_config.label)
                continue
            if was_loaded:
                reload(module)
        self.migrated_apps.add(app_config.label)
        migration_names = {name for (_, name, is_pkg) in pkgutil.iter_modules(module.__path__) if not is_pkg and name[0] not in '_~'}
        for migration_name in migration_names:
            migration_path = '%s.%s' % (module_name, migration_name)
            try:
                migration_module = import_module(migration_path)
            except ImportError as e:
                if 'bad magic number' in str(e):
                    raise ImportError("Couldn't import %r as it appears to be a stale .pyc file." % migration_path) from e
                else:
                    raise
            if not hasattr(migration_module, 'Migration'):
                raise BadMigrationError('Migration %s in app %s has no Migration class' % (migration_name, app_config.label))
            self.disk_migrations[app_config.label, migration_name] = migration_module.Migration(migration_name, app_config.label)

def _find_names(obj):
    import gc
    import inspect
    frame = inspect.currentframe()
    while frame is not None:
        frame.f_locals
        frame = frame.f_back
    obj_names = []
    for referrer in gc.get_referrers(obj):
        if <MASK>:
            for (k, v) in referrer.items():
                if v is obj:
                    obj_names.append(k)
    return obj_names

def _apply_reduction(fn, *args, **kwargs):
    if fn in NATIVE_REDUCE_MAP:
        return NATIVE_REDUCE_MAP[fn](*args, **kwargs)
    if fn in TORCH_REDUCE_MAP:
        return TORCH_REDUCE_MAP[fn](*args, **kwargs)
    if <MASK>:
        return TENSOR_REDUCE_MAP[fn](*args, **kwargs)
    return NotImplemented

def _str_startswith(self, pat: str | tuple[str, ...], na: Scalar | lib.NoDefault=lib.no_default):
    if <MASK>:
        result = pc.starts_with(self._pa_array, pattern=pat)
    elif len(pat) == 0:
        result = pc.if_else(pc.is_null(self._pa_array), None, False)
    else:
        result = pc.starts_with(self._pa_array, pattern=pat[0])
        for p in pat[1:]:
            result = pc.or_(result, pc.starts_with(self._pa_array, pattern=p))
    return self._convert_bool_result(result, na=na, method_name='startswith')

def quantile(a: ArrayLike, q: ArrayLike, axis: AxisLike=None, out: Optional[OutArray]=None, overwrite_input=False, method='linear', keepdims: KeepDims=False, *, interpolation: NotImplementedType=None):
    if overwrite_input:
        pass
    if <MASK>:
        dtype = _dtypes_impl.default_dtypes().float_dtype
        a = a.to(dtype)
    if a.dtype == torch.float16:
        a = a.to(torch.float32)
    if axis is None:
        a = a.flatten()
        q = q.flatten()
        axis = (0,)
    else:
        axis = _util.normalize_axis_tuple(axis, a.ndim)
    axis = _util.allow_only_single_axis(axis)
    q = _util.cast_if_needed(q, a.dtype)
    return torch.quantile(a, q, axis=axis, interpolation=method)

def _parse_thead_tr(self, table):
    rows = []
    for thead in table.xpath('.//thead'):
        rows.extend(thead.xpath('./tr'))
        elements_at_root = thead.xpath('./td|./th')
        if <MASK>:
            rows.append(thead)
    return rows

def __get__(self, instance, cls=None):
    """
        Retrieve and caches the value from the datastore on the first lookup.
        Return the cached value.
        """
    if instance is None:
        return self
    data = instance.__dict__
    field_name = self.field.attname
    if field_name not in data:
        val = self._check_parent_chain(instance)
        if <MASK>:
            if not instance._is_pk_set():
                raise AttributeError(f'Cannot retrieve deferred field {field_name!r} from an unsaved model.')
            instance._state.fetch_mode.fetch(self, instance)
        else:
            data[field_name] = val
    return data[field_name]

def _yield_all_checks(estimator, legacy: bool):
    name = estimator.__class__.__name__
    tags = get_tags(estimator)
    if not tags.input_tags.two_d_array:
        warnings.warn("Can't test estimator {} which requires input  of type {}".format(name, tags.input_tags), SkipTestWarning)
        return
    if tags._skip_test:
        warnings.warn('Explicit SKIP via _skip_test tag for estimator {}.'.format(name), SkipTestWarning)
        return
    for check in _yield_api_checks(estimator):
        yield check
    if not legacy:
        return
    for check in _yield_checks(estimator):
        yield check
    if <MASK>:
        for check in _yield_classifier_checks(estimator):
            yield check
    if is_regressor(estimator):
        for check in _yield_regressor_checks(estimator):
            yield check
    if hasattr(estimator, 'transform'):
        for check in _yield_transformer_checks(estimator):
            yield check
    if isinstance(estimator, ClusterMixin):
        for check in _yield_clustering_checks(estimator):
            yield check
    if is_outlier_detector(estimator):
        for check in _yield_outliers_checks(estimator):
            yield check
    yield check_parameters_default_constructible
    if not tags.non_deterministic:
        yield check_methods_sample_order_invariance
        yield check_methods_subset_invariance
    yield check_fit2d_1sample
    yield check_fit2d_1feature
    yield check_get_params_invariance
    yield check_set_params
    yield check_dict_unchanged
    yield check_fit_idempotent
    yield check_fit_check_is_fitted
    if not tags.no_validation:
        yield check_n_features_in
        yield check_fit1d
        yield check_fit2d_predict1d
        if tags.target_tags.required:
            yield check_requires_y_none
    if tags.input_tags.positive_only:
        yield check_fit_non_negative

