            init_geoms = args
    else:
        init_geoms = args
    self._check_allowed(init_geoms)
    collection = self._create_collection(len(init_geoms), init_geoms)
    super().__init__(collection, **kwargs)

def clean_nn_module_stack_and_source_fn(graph_module: torch.fx.GraphModule, is_inline_builtin=False) -> torch.fx.GraphModule:
    """
    Clean up nn_module_stack metadata by removing export_root references.

    Removes the _export_root module references from nn_module_stack metadata
    in graph nodes, which are artifacts from the export process. Fixes two patterns:

    1. Keys: Removes "__export_root_" and "__modules['_export_root']_" prefixes
       - Normal case: "L__self____export_root_child" -> "L__self__child"
       - inline_builtin case: Uses numeric ID strings like "140468831433840"

    2. Values: Removes "._export_root" and "._modules['_export_root']" from child names
       e.g., "L['self']._export_root.child" -> "L['self'].child"
       e.g., "L['self']._modules['_export_root'].child" -> "L['self'].child"

    Also removes the root export entry "L__self____export_root" entirely.

    Args:
        graph_module: The GraphModule to clean up
        is_inline_builtin: If True, keys are numeric ID strings and self references
                          (L['self']) are filtered out

    Returns:
        The cleaned GraphModule (modified in-place)
    """

    def _process_nn_module_stack(nn_module_stack):
        if 'L__self____export_root' in nn_module_stack:
            del nn_module_stack['L__self____export_root']
        cleaned_stack = {}
        for (key, (child_name, child_class)) in nn_module_stack.items():
            clean_key = clean_export_root_string(key)
            clean_name = clean_export_root_string(child_name)
            if is_inline_builtin and clean_name == "L['self']":
                continue
            cleaned_stack[clean_key] = (clean_name, child_class)
        return cleaned_stack

    def _process_source_fn(source_fn_stack):
        cleaned_stack = []
        for item in source_fn_stack:
            if isinstance(item, tuple) and len(item) == 2:
                (name, cls) = item
                if isinstance(name, str):
                    clean_name = clean_export_root_string(name)
                    cleaned_stack.append((clean_name, cls))
                else:
                    cleaned_stack.append(item)
            else:
                cleaned_stack.append(item)
        return cleaned_stack
    for node in graph_module.graph.nodes:
        if 'nn_module_stack' in node.meta:
            node.meta['nn_module_stack'] = _process_nn_module_stack(node.meta['nn_module_stack'].copy())
        if 'source_fn_stack' in node.meta:
            node.meta['source_fn_stack'] = _process_source_fn(node.meta['source_fn_stack'].copy())
    if <MASK>:
        clean_name_to_original_fqn = {}
        for (flat_name, original_fqn) in graph_module.meta['dynamo_flat_name_to_original_fqn'].items():
            clean_name_to_original_fqn[clean_export_root_string(flat_name)] = clean_export_root_string(original_fqn)
        graph_module.meta['dynamo_flat_name_to_original_fqn'] = clean_name_to_original_fqn
    return graph_module

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName) -> NamedCType:
    r = cpp.valuetype_type(t, symint=False, binds=binds, mutable=mutable)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, BaseCType(optionalTensorRefT))
        elif <MASK>:
            return NamedCType(binds, BaseCType(optionalScalarRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
        elif t.elem == OptionalType(BaseType(BaseTy.Tensor)):
            return NamedCType(binds, BaseCType(iOptTensorListRefT))
        elif str(t.elem) == 'int':
            return NamedCType(binds, BaseCType(intArrayRefT))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

def __init__(self, values, *, dtype: StringDtype | None=None) -> None:
    _check_pyarrow_available()
    if isinstance(values, (pa.Array, pa.ChunkedArray)) and (pa.types.is_string(values.type) or _is_string_view(values.type) or (pa.types.is_dictionary(values.type) and (pa.types.is_string(values.type.value_type) or pa.types.is_large_string(values.type.value_type) or _is_string_view(values.type.value_type)))):
        values = pc.cast(values, pa.large_string())
    super().__init__(values)
    if <MASK>:
        dtype = StringDtype(storage='pyarrow', na_value=libmissing.NA)
    self._dtype = dtype
    if not pa.types.is_large_string(self._pa_array.type):
        raise ValueError('ArrowStringArray requires a PyArrow (chunked) array of large_string type')

def _clone_parametrized(estimator, *, safe=True):
    """Default implementation of clone. See :func:`sklearn.base.clone` for details."""
    estimator_type = type(estimator)
    if estimator_type is dict:
        return {k: clone(v, safe=safe) for (k, v) in estimator.items()}
    elif estimator_type in (list, tuple, set, frozenset):
        return estimator_type([clone(e, safe=safe) for e in estimator])
    elif <MASK>:
        if not safe:
            return copy.deepcopy(estimator)
        elif isinstance(estimator, type):
            raise TypeError('Cannot clone object. You should provide an instance of scikit-learn estimator instead of a class.')
        else:
            raise TypeError("Cannot clone object '%s' (type %s): it does not seem to be a scikit-learn estimator as it does not implement a 'get_params' method." % (repr(estimator), type(estimator)))
    klass = estimator.__class__
    new_object_params = estimator.get_params(deep=False)
    for (name, param) in new_object_params.items():
        new_object_params[name] = clone(param, safe=False)
    new_object = klass(**new_object_params)
    try:
        new_object._metadata_request = copy.deepcopy(estimator._metadata_request)
    except AttributeError:
        pass
    params_set = new_object.get_params(deep=False)
    for name in new_object_params:
        param1 = new_object_params[name]
        param2 = params_set[name]
        if param1 is not param2:
            raise RuntimeError('Cannot clone object %s, as the constructor either does not set or modifies parameter %s' % (estimator, name))
    if hasattr(estimator, '_sklearn_output_config'):
        new_object._sklearn_output_config = copy.deepcopy(estimator._sklearn_output_config)
    return new_object

@register_lowering(torch.ops.aten.resize)
def resize(x, size, *, memory_format=None):
    assert isinstance(x, TensorBox)
    assert isinstance(size, (list, tuple))
    if <MASK>:
        memory_format = torch.contiguous_format
    if memory_format == torch.preserve_format:
        raise RuntimeError(f'unsupported memory format: {memory_format}')
    if memory_format == torch.channels_last:
        assert len(size) == 4
    if memory_format == torch.channels_last_3d:
        assert len(size) == 5
    old_numel = x.get_numel()
    dtype = x.get_dtype()
    device = x.get_device_or_error()
    if isinstance(x.data, ir.BaseView):
        x.data = x.data.unwrap_view()
    if torch.are_deterministic_algorithms_enabled() and torch.utils.deterministic.fill_uninitialized_memory:
        if is_float_dtype(dtype):
            uninitialized_val = float('nan')
        elif is_integer_dtype(dtype):
            uninitialized_val = torch.iinfo(dtype).max
        else:
            uninitialized_val = True
    else:
        uninitialized_val = 0.0
    if V.graph.sizevars.statically_known_equals(old_numel, 0):
        return full(size, uninitialized_val, dtype=dtype, device=device)
    x_flat = as_strided(x, [old_numel], [1])
    flat_loader = x_flat.make_loader()
    out_stride = ir.FlexibleLayout.stride_ordered_for_memory_format(size, memory_format)
    out_indexer = ir.FixedLayout(device, dtype, size, out_stride).make_indexer()

    def inner_fn(idx):
        flat_index = out_indexer(idx)
        flat_index_expr = ops.index_expr(flat_index, torch.int64)
        limit = ops.index_expr(old_numel, torch.int64)
        mask = ops.lt(flat_index_expr, limit)
        return ops.masked(mask, lambda : flat_loader([flat_index]), uninitialized_val)
    out = Pointwise.create(device=device, dtype=dtype, inner_fn=inner_fn, ranges=list(size))
    return out

def main(_):
    if <MASK>:
        assert FLAGS.output.endswith('.cc')
        generated_code = gen_register_op(sys.modules[__name__], '_composite_')
    else:
        assert FLAGS.output.endswith('.mlir')
        generated_code = tfr_gen_from_module(sys.modules[__name__], '_composite_')
    dirname = os.path.dirname(FLAGS.output)
    if not os.path.exists(dirname):
        os.makedirs(dirname)
    with open(FLAGS.output, 'w') as f:
        f.write(generated_code)

def _is_tma_compatible(sizes: Sequence[sympy.Expr], strides: Sequence[_IntLike], dtype: torch.dtype, allow_float32: bool) -> bool:
    rank = len(sizes)
    itemsize = dtype.itemsize
    if <MASK>:
        return False
    if dtype not in (torch.float16, torch.bfloat16, torch.float8_e4m3fn) and (not allow_float32 or dtype != torch.float32):
        return False
    if add_guards:
        sizes_i = V.graph.sizevars.guard_int_seq(sizes)
        strides_i = V.graph.sizevars.guard_int_seq(strides)
    else:
        sizes_i = [V.graph.sizevars.symbolic_hint(s) for s in sizes]
        strides_i = [V.graph.sizevars.symbolic_hint(st) for st in strides]
    if any((not V.graph.sizevars.statically_known_geq(s, 2) for s in sizes_i)):
        return False
    inner = [i for (i, st) in enumerate(strides_i) if V.graph.sizevars.statically_known_equals(st, 1)]
    if len(inner) != 1:
        return False
    inner_idx = inner[0]
    for (i, st) in enumerate(strides_i):
        if i == inner_idx:
            continue
        if not _aligned(st * itemsize):
            return False
    inner_dim = sizes_i[inner_idx]
    if not _aligned(inner_dim * itemsize):
        return False
    if dtype == torch.float8_e4m3fn and (not V.graph.sizevars.statically_known_geq(inner_dim, 32)):
        return False
    return True

