@staticmethod
def constant(value, dtype):
    if isinstance(value, ValueRanges):
        if not value.is_singleton():
            raise AssertionError('ValueRanges must be a singleton for constant()')
        value = value.lower
    is_python = isinstance(value, (int, float, bool))
    if not is_python and (not isinstance(value, (BooleanAtom, sympy.Integer, sympy.Number))):
        raise AssertionError(f'not a supported constant type: {type(value)}')
    if isinstance(value, SupportsFloat) and math.isnan(value):
        if dtype == torch.bool:
            return ValueRanges.unknown_bool()
        elif <MASK>:
            return ValueRanges.unknown()
        else:
            return ValueRanges.unknown_int()
    if is_python:
        type_ = dtype_to_type(dtype)
        value = type_(value)
    elif dtype == torch.bool:
        if not isinstance(value, BooleanAtom):
            raise AssertionError('expected BooleanAtom for bool dtype')
    elif dtype.is_floating_point:
        if value.is_finite and (not value.is_real):
            raise AssertionError('expected float-like sympy value for float dtype')
    elif not getattr(value, 'is_integer', False):
        raise AssertionError('expected integer sympy value for int dtype')
    r = ValueRanges.wrap(value)
    return r

def parse_cluster_spec(cluster_spec, cluster, verbose=False):
    """Parse content of cluster_spec string and inject info into cluster protobuf.

  Args:
    cluster_spec: cluster specification string, e.g.,
          "local|localhost:2222;localhost:2223"
    cluster: cluster protobuf.
    verbose: If verbose logging is requested.

  Raises:
    ValueError: if the cluster_spec string is invalid.
  """
    job_strings = cluster_spec.split(',')
    if not cluster_spec:
        raise ValueError('Empty cluster_spec string')
    for job_string in job_strings:
        job_def = cluster.job.add()
        if job_string.count('|') != 1:
            raise ValueError("Not exactly one instance of '|' in cluster_spec")
        job_name = job_string.split('|')[0]
        if not job_name:
            raise ValueError('Empty job_name in cluster_spec')
        job_def.name = job_name
        if <MASK>:
            logging.info('Added job named "%s"', job_name)
        job_tasks = job_string.split('|')[1].split(';')
        for i in range(len(job_tasks)):
            if not job_tasks[i]:
                raise ValueError('Empty task string at position %d' % i)
            job_def.tasks[i] = job_tasks[i]
            if verbose:
                logging.info('  Added task "%s" to job "%s"', job_tasks[i], job_name)

@staticmethod
def build_inline_tracer(parent: Any, func: VariableTracker, args: list[VariableTracker], kwargs: Any) -> InliningInstructionTranslator:
    assert isinstance(func, (UserFunctionVariable, NestedUserFunctionVariable, LocalGeneratorFunctionVariable, LocalGeneratorObjectVariable))
    code: types.CodeType = func.get_code()
    result = None
    tracing_ctx = parent.output.tracing_context
    if not config.dont_skip_tracing and tracing_ctx:
        if (previous_result := tracing_ctx.previously_inlined_functions.get(code, None)):
            result = previous_result
    if result is None:
        if isinstance(func, SkipFunctionVariable):
            unimplemented_v2(gb_type='Attempted to inline function marked as skipped (SkipFunctionVariable)', context=f'Attempted to inline a SkipFunctionVariable {func}', explanation='Attempted to inline a function that was previously determined to be marked as intentionally skipped.', hints=[])
        result = InliningInstructionTranslator.check_inlineable(func)
        assert result.skipped is False
        if not config.dont_skip_tracing and tracing_ctx:
            tracing_ctx.previously_inlined_functions[code] = result
    try:
        sub_locals = func.bind_args(parent, args, kwargs)
    except TypeError as e:
        raise ArgsMismatchError('{reason}.\n  func = {func}, args = {args}, kwargs = {kwargs}'.format(reason=str(e), func=f"'{func.get_name()}' {func.get_filename()}:{func.get_code().co_firstlineno}", args=[arg.python_type() for arg in args], kwargs=kwargs))
    for v in itertools.chain(sub_locals.values()):
        if not isinstance(v, VariableTracker):
            unimplemented_v2(gb_type='Encountered unconverted argument when attempting to inline', context=f'func: {func}, arg: {v}', explanation='An argument to an inlined function was not successfully converted to a VariableTracker.', hints=[*graph_break_hints.DYNAMO_BUG])
    if code.co_name in ('__setitem__', '__setattr__') and (not (args and isinstance(args[0], variables.UserDefinedObjectVariable))):
        unimplemented_v2(gb_type='Unsupported __setitem__/__setattr__ inline attempt', context=f'code name: {code.co_name}, args: {args}', explanation=f'Attempted to inline {code.co_name} where first argument (self) is not a user-defined object.', hints=[])
    suffix = ''
    if torch._logging._internal.log_state.is_artifact_enabled('bytecode'):
        suffix = f'\n{dis.Bytecode(code).dis()}'
    if sys.version_info >= (3, 11):
        cur_inst = parent.current_instruction
        parent_code = parent.f_code

        def get_trace_call_log_str() -> str:
            header = parent.get_line_of_code_header(lineno=cur_inst.positions.lineno)
            line = get_instruction_source_311(parent_code, cur_inst).rstrip()
            return f'TRACE inlined call {code.co_name} from {header}\n{line}'
        trace_call_log.debug('%s', LazyString(get_trace_call_log_str))
    log.debug('INLINING %s%s, %s', code, suffix, result.reason)
    if args and isinstance(args[0], NNModuleVariable):
        module = parent.output.get_submodule(args[0].module_key)
        if isinstance(module, torch.fx.GraphModule):
            code_context.get_context(module.forward.__code__)['orig_graphmodule'] = weakref.ref(module)
    if <MASK>:
        module = args[0].value
        if isinstance(module, torch.fx.GraphModule):
            code_context.get_context(module.forward.__code__)['orig_graphmodule'] = weakref.ref(module)
    tracer: InliningInstructionTranslator
    if is_generator(code):
        tracer = InliningGeneratorInstructionTranslator(parent, code, sub_locals, parent.symbolic_globals, parent.symbolic_torch_function_state, func)
    else:
        assert not isinstance(func, LocalGeneratorObjectVariable)
        tracer = InliningInstructionTranslator(parent, code, sub_locals, parent.symbolic_globals, parent.symbolic_torch_function_state, func)
    return tracer

def _cmpkey(epoch: int, release: Tuple[int, ...], pre: Optional[Tuple[str, int]], post: Optional[Tuple[str, int]], dev: Optional[Tuple[str, int]], local: Optional[Tuple[SubLocalType]]) -> CmpKey:
    _release = tuple(reversed(list(itertools.dropwhile(lambda x: x == 0, reversed(release)))))
    if pre is None and post is None and (dev is not None):
        _pre: PrePostDevType = NegativeInfinity
    elif pre is None:
        _pre = Infinity
    else:
        _pre = pre
    if <MASK>:
        _post: PrePostDevType = NegativeInfinity
    else:
        _post = post
    if dev is None:
        _dev: PrePostDevType = Infinity
    else:
        _dev = dev
    if local is None:
        _local: LocalType = NegativeInfinity
    else:
        _local = tuple(((i, '') if isinstance(i, int) else (NegativeInfinity, i) for i in local))
    return (epoch, _release, _pre, _post, _dev, _local)

def to_structured_signature(function_type: FunctionType) -> Tuple[Any, Any]:
    """Returns structured input and output signatures from a FunctionType."""

    def to_signature(x_type):
        if <MASK>:
            raise TypeError(f'Can not generate structured signature if FunctionType is not fully specified. Received {function_type}')
        return x_type.placeholder_value(trace_type.InternalPlaceholderContext(unnest_only=True))
    args_signature = []
    kwargs_signature = {}
    for p in function_type.parameters.values():
        if p.kind == Parameter.POSITIONAL_ONLY:
            args_signature.append(to_signature(p.type_constraint))
        else:
            kwargs_signature[p.name] = to_signature(p.type_constraint)
    input_signature = (tuple(args_signature), kwargs_signature)
    output_signature = to_signature(function_type.output)
    return (input_signature, output_signature)

def setup(self, dtype, hasna):
    N = 100000
    if dtype == 'boolean[pyarrow]':
        data = np.random.choice([True, False], N, replace=True)
    elif dtype == 'float64[pyarrow]':
        data = np.random.randn(N)
    elif <MASK>:
        data = np.arange(N)
    elif dtype == 'string[pyarrow]':
        data = np.array([str(i) for i in range(N)], dtype=object)
    elif dtype == 'timestamp[ns][pyarrow]':
        data = pd.date_range('2000-01-01', freq='s', periods=N)
    else:
        raise NotImplementedError
    arr = pd.array(data, dtype=dtype)
    if hasna:
        arr[::2] = pd.NA
    self.arr = arr

def _bfs_for_reachable_nodes(target_nodes, name_to_input_name):
    """Breadth first search for reachable nodes from target nodes."""
    nodes_to_keep = set()
    next_to_visit = list(target_nodes)
    while next_to_visit:
        node = next_to_visit[0]
        del next_to_visit[0]
        if <MASK>:
            continue
        nodes_to_keep.add(node)
        if node in name_to_input_name:
            next_to_visit += name_to_input_name[node]
    return nodes_to_keep

def _cdf(self, k):
    k = ops.convert_to_tensor(k, name='k')
    if <MASK>:
        k = distribution_util.embed_check_integer_casting_closed(k, target_dtype=dtypes.int32)
    (k, probs) = _broadcast_cat_event_and_params(k, self.probs, base_dtype=self.dtype.base_dtype)
    batch_flattened_probs = array_ops.reshape(probs, (-1, self._event_size))
    batch_flattened_k = array_ops.reshape(k, [-1])
    to_sum_over = array_ops.where(array_ops.sequence_mask(batch_flattened_k, self._event_size), batch_flattened_probs, array_ops.zeros_like(batch_flattened_probs))
    batch_flattened_cdf = math_ops.reduce_sum(to_sum_over, axis=-1)
    return array_ops.reshape(batch_flattened_cdf, array_ops.shape(k))

def _convert_listlike_datetimes(arg, format: str | None, name: Hashable | None=None, utc: bool=False, unit: str | None=None, errors: DateTimeErrorChoices='raise', dayfirst: bool | None=None, yearfirst: bool | None=None, exact: bool=True):
    """
    Helper function for to_datetime. Performs the conversions of 1D listlike
    of dates

    Parameters
    ----------
    arg : list, tuple, ndarray, Series, Index
        date to be parsed
    name : object
        None or string for the Index name
    utc : bool
        Whether to convert/localize timestamps to UTC.
    unit : str
        None or string of the frequency of the passed data
    errors : str
        error handing behaviors from to_datetime, 'raise', 'coerce'
    dayfirst : bool
        dayfirst parsing behavior from to_datetime
    yearfirst : bool
        yearfirst parsing behavior from to_datetime
    exact : bool, default True
        exact format matching behavior from to_datetime

    Returns
    -------
    Index-like of parsed dates
    """
    if isinstance(arg, (list, tuple)):
        arg = np.array(arg, dtype='O')
    elif isinstance(arg, NumpyExtensionArray):
        arg = np.array(arg)
    arg_dtype = getattr(arg, 'dtype', None)
    tz = 'utc' if utc else None
    if isinstance(arg_dtype, DatetimeTZDtype):
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        if utc:
            arg = arg.tz_convert(None).tz_localize('utc')
        return arg
    elif isinstance(arg_dtype, ArrowDtype) and arg_dtype.type is Timestamp:
        if utc:
            if <MASK>:
                arg_array = cast(ArrowExtensionArray, arg.array)
                if arg_dtype.pyarrow_dtype.tz is not None:
                    arg_array = arg_array._dt_tz_convert('UTC')
                else:
                    arg_array = arg_array._dt_tz_localize('UTC')
                arg = Index(arg_array)
            elif arg_dtype.pyarrow_dtype.tz is not None:
                arg = arg._dt_tz_convert('UTC')
            else:
                arg = arg._dt_tz_localize('UTC')
        return arg
    elif lib.is_np_dtype(arg_dtype, 'M'):
        if not is_supported_dtype(arg_dtype):
            arg = astype_overflowsafe(np.asarray(arg), np.dtype('M8[s]'), is_coerce=errors == 'coerce')
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        elif utc:
            return arg.tz_localize('utc')
        return arg
    elif unit is not None:
        if format is not None:
            raise ValueError('cannot specify both format and unit')
        return _to_datetime_with_unit(arg, unit, name, utc, errors)
    elif getattr(arg, 'ndim', 1) > 1:
        raise TypeError('arg must be a string, datetime, list, tuple, 1-d array, or Series')
    try:
        (arg, _) = maybe_convert_dtype(arg, copy=False, tz=libtimezones.maybe_get_tz(tz))
    except TypeError:
        if errors == 'coerce':
            npvalues = np.full(len(arg), np.datetime64('NaT', 'ns'))
            return DatetimeIndex(npvalues, name=name)
        raise
    arg = ensure_object(arg)
    if format is None:
        format = _guess_datetime_format_for_array(arg, dayfirst=dayfirst)
    if format is not None and format != 'mixed':
        return _array_strptime_with_fallback(arg, name, utc, format, exact, errors)
    (result, tz_parsed) = objects_to_datetime64(arg, dayfirst=dayfirst, yearfirst=yearfirst, utc=utc, errors=errors, allow_object=True)
    if tz_parsed is not None:
        out_unit = np.datetime_data(result.dtype)[0]
        dtype = tz_to_dtype(tz_parsed, out_unit)
        dt64_values = result.view(f'M8[{dtype.unit}]')
        dta = DatetimeArray._simple_new(dt64_values, dtype=dtype)
        return DatetimeIndex._simple_new(dta, name=name)
    return _box_as_indexlike(result, utc=utc, name=name)

def _set_item_frame_value(self, key, value: DataFrame) -> None:
    self._ensure_valid_index(value)
    if key in self.columns:
        loc = self.columns.get_loc(key)
        cols = self.columns[loc]
        len_cols = 1 if is_scalar(cols) or isinstance(cols, tuple) else len(cols)
        if len_cols != len(value.columns):
            raise ValueError('Columns must be same length as key')
        if isinstance(self.columns, MultiIndex) and isinstance(loc, (slice, Series, np.ndarray, Index)):
            cols_droplevel = maybe_droplevels(cols, key)
            if not isinstance(cols_droplevel, MultiIndex) and is_string_dtype(cols_droplevel.dtype) and (not cols_droplevel.any()):
                return
            if <MASK>:
                value = value.reindex(cols_droplevel, axis=1)
            for (col, col_droplevel) in zip(cols, cols_droplevel, strict=True):
                self[col] = value[col_droplevel]
            return
        if is_scalar(cols):
            self[cols] = value[value.columns[0]]
            return
        locs: np.ndarray | list
        if isinstance(loc, slice):
            locs = np.arange(loc.start, loc.stop, loc.step)
        elif is_scalar(loc):
            locs = [loc]
        else:
            locs = loc.nonzero()[0]
        return self.isetitem(locs, value)
    if len(value.columns) > 1:
        raise ValueError(f'Cannot set a DataFrame with multiple columns to the single column {key}')
    elif len(value.columns) == 0:
        raise ValueError(f'Cannot set a DataFrame without columns to the column {key}')
    self[key] = value[value.columns[0]]

def emit_check_if_in_complex_autograd_allowlist() -> list[str]:
    body: list[str] = []
    if <MASK>:
        return body
    for arg in differentiable_outputs:
        name = arg.name
        if arg.cpp_type == 'at::Tensor' or arg.cpp_type in TENSOR_LIST_LIKE_CTYPES:
            body.append(f'throw_error_for_complex_autograd({name}, "{base_name}");')
    return body

