@click.command()
@click.option('--tests', '-t', default=None, metavar='TESTS', multiple=True, help='Which tests to run')
@click.option('--compare', '-c', is_flag=True, default=False, help='Compare benchmarks between the current branch and main (unless other branches specified). The benchmarks are each executed in a new isolated environment.')
@click.option('--verbose', '-v', is_flag=True, default=False)
@click.option('--quick', '-q', is_flag=True, default=False, help="Run each benchmark only once (timings won't be accurate)")
@click.argument('commits', metavar='', required=False, nargs=-1)
@meson.build_dir_option
@click.pass_context
def bench(ctx, tests, compare, verbose, quick, commits, build_dir):
    """🏋 Run benchmarks.

    \x08
    Examples:

    \x08
    $ spin bench -t bench_lib
    $ spin bench -t bench_random.Random
    $ spin bench -t Random -t Shuffle

    Two benchmark runs can be compared.
    By default, `HEAD` is compared to `main`.
    You can also specify the branches/commits to compare:

    \x08
    $ spin bench --compare
    $ spin bench --compare main
    $ spin bench --compare main HEAD

    You can also choose which benchmarks to run in comparison mode:

    $ spin bench -t Random --compare
    """
    if not commits:
        commits = ('main', 'HEAD')
    elif len(commits) == 1:
        commits = commits + ('HEAD',)
    elif len(commits) > 2:
        raise click.ClickException('Need a maximum of two revisions to compare')
    bench_args = []
    for t in tests:
        bench_args += ['--bench', t]
    if verbose:
        bench_args = ['-v'] + bench_args
    if quick:
        bench_args = ['--quick'] + bench_args
    if not compare:
        click.secho('Invoking `build` prior to running benchmarks:', bold=True, fg='bright_green')
        ctx.invoke(build)
        meson._set_pythonpath(build_dir)
        p = spin.util.run(['python', '-c', 'import numpy as np; print(np.__version__)'], cwd='benchmarks', echo=False, output=False)
        os.chdir('..')
        np_ver = p.stdout.strip().decode('ascii')
        click.secho(f'Running benchmarks on NumPy {np_ver}', bold=True, fg='bright_green')
        cmd = ['asv', 'run', '--dry-run', '--show-stderr', '--python=same'] + bench_args
        _run_asv(cmd)
    else:
        (commit_a, commit_b) = [_commit_to_sha(c) for c in commits]
        if <MASK>:
            click.secho('WARNING: you have uncommitted changes --- these will NOT be benchmarked!', fg='red')
        cmd_compare = ['asv', 'continuous', '--factor', '1.05'] + bench_args + [commit_a, commit_b]
        _run_asv(cmd_compare)

def _laplacian_sparse_flo(graph, normed, axis, copy, form, dtype, symmetrized):
    del copy
    if <MASK>:
        dtype = graph.dtype
    graph_sum = np.asarray(graph.sum(axis=axis)).ravel()
    graph_diagonal = graph.diagonal()
    diag = graph_sum - graph_diagonal
    if symmetrized:
        graph_sum += np.asarray(graph.sum(axis=1 - axis)).ravel()
        diag = graph_sum - graph_diagonal - graph_diagonal
    if normed:
        isolated_node_mask = diag == 0
        w = np.where(isolated_node_mask, 1, np.sqrt(diag))
        if symmetrized:
            md = _laplace_normed_sym(graph, graph_sum, 1.0 / w)
        else:
            md = _laplace_normed(graph, graph_sum, 1.0 / w)
        if form == 'function':
            return (md, w.astype(dtype, copy=False))
        elif form == 'lo':
            m = _linearoperator(md, shape=graph.shape, dtype=dtype)
            return (m, w.astype(dtype, copy=False))
        else:
            raise ValueError(f'Invalid form: {form!r}')
    else:
        if symmetrized:
            md = _laplace_sym(graph, graph_sum)
        else:
            md = _laplace(graph, graph_sum)
        if form == 'function':
            return (md, diag.astype(dtype, copy=False))
        elif form == 'lo':
            m = _linearoperator(md, shape=graph.shape, dtype=dtype)
            return (m, diag.astype(dtype, copy=False))
        else:
            raise ValueError(f'Invalid form: {form!r}')

