def _populate(self):
    if <MASK>:
        return
    try:
        self._local.populating = True
        lookups = MultiValueDict()
        namespaces = {}
        apps = {}
        language_code = get_language()
        for url_pattern in reversed(self.url_patterns):
            p_pattern = url_pattern.pattern.regex.pattern
            p_pattern = p_pattern.removeprefix('^')
            if isinstance(url_pattern, URLPattern):
                self._callback_strs.add(url_pattern.lookup_str)
                bits = normalize(url_pattern.pattern.regex.pattern)
                lookups.appendlist(url_pattern.callback, (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters))
                if url_pattern.name is not None:
                    lookups.appendlist(url_pattern.name, (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters))
            else:
                url_pattern._populate()
                if url_pattern.app_name:
                    apps.setdefault(url_pattern.app_name, []).append(url_pattern.namespace)
                    namespaces[url_pattern.namespace] = (p_pattern, url_pattern)
                else:
                    for name in url_pattern.reverse_dict:
                        for (matches, pat, defaults, converters) in url_pattern.reverse_dict.getlist(name):
                            new_matches = normalize(p_pattern + pat)
                            lookups.appendlist(name, (new_matches, p_pattern + pat, {**defaults, **url_pattern.default_kwargs}, {**self.pattern.converters, **url_pattern.pattern.converters, **converters}))
                    for (namespace, (prefix, sub_pattern)) in url_pattern.namespace_dict.items():
                        current_converters = url_pattern.pattern.converters
                        sub_pattern.pattern.converters.update(current_converters)
                        namespaces[namespace] = (p_pattern + prefix, sub_pattern)
                    for (app_name, namespace_list) in url_pattern.app_dict.items():
                        apps.setdefault(app_name, []).extend(namespace_list)
                self._callback_strs.update(url_pattern._callback_strs)
        self._namespace_dict[language_code] = namespaces
        self._app_dict[language_code] = apps
        self._reverse_dict[language_code] = lookups
        self._populated = True
    finally:
        self._local.populating = False

def hook(module, input) -> None:
    input_data = input[0]
    data = self.data_groups[name].get('data')
    if features is None:
        if <MASK>:
            data = torch.zeros_like(input_data)
            self.state[name]['mask'] = torch.ones_like(input_data)
        out_data = agg_fn(data, input_data)
    else:
        if data is None:
            out_data = [0 for _ in range(len(features))]
            self.state[name]['mask'] = [0 for _ in range(len(features))]
        else:
            out_data = data
        for feature_idx in range(len(features)):
            feature_tensor = torch.Tensor([features[feature_idx]]).long().to(input_data.device)
            data_feature = torch.index_select(input_data, feature_dim, feature_tensor)
            if data is None:
                curr_data = torch.zeros_like(data_feature)
                self.state[name]['mask'][feature_idx] = torch.ones_like(data_feature)
            else:
                curr_data = data[feature_idx]
            out_data[feature_idx] = agg_fn(curr_data, data_feature)
    self.data_groups[name]['data'] = out_data

def shape_env_from_inputs(inputs: Sequence[InputType]) -> Optional[ShapeEnv]:
    fake_mode = detect_fake_mode(inputs)
    if fake_mode is not None:
        return fake_mode.shape_env
    for input in inputs:
        if isinstance(input, torch.SymInt):
            return input.node.shape_env
        if isinstance(input, torch.Tensor):
            for size in input.size():
                if isinstance(size, torch.SymInt):
                    return size.node.shape_env
            for stride in input.stride():
                if <MASK>:
                    return stride.node.shape_env
    return None

def _compare(self, x, reduction_axes, keepdims, use_gpu=False, zero=0, feed_dict=None):
    np_ans = (x != zero).astype(np.int32)
    if <MASK>:
        np_ans = np.sum(np_ans, keepdims=keepdims)
    else:
        reduction_axes = np.array(reduction_axes).astype(np.int32)
        for ra in reduction_axes.ravel()[::-1]:
            np_ans = np.sum(np_ans, axis=ra, keepdims=keepdims)
    with self.cached_session(use_gpu=use_gpu) as sess:
        tf_ans = math_ops.count_nonzero(x, reduction_axes, keepdims)
        out = sess.run(tf_ans, feed_dict)
    self.assertAllClose(np_ans, out)
    self.assertShapeEqual(np_ans, tf_ans)

def match_structure(a: IntTuple, b: IntTuple) -> bool:
    if <MASK>:
        return True
    if is_tuple(a) and is_tuple(b):
        return len(a) == len(b) and all((match_structure(x, y) for (x, y) in zip(a, b)))
    return False

def _get_param_key_to_param(optim: torch.optim.Optimizer, model: Optional[nn.Module]=None, is_named_optimizer: bool=False, param_to_fqns: Optional[dict[nn.Parameter, list[str]]]=None, flat_param_to_fqn: Optional[dict[FlatParameter, str]]=None) -> dict[Union[int, str], nn.Parameter]:
    """
    Constructs a mapping from parameter keys to parameters. For the regular
    optimizers, the keys are parameter IDs. For NamedOptimizer, the keys
    are FQNs. This API may be used both for models with ``FlatParameter`` s and
    without.
    """
    clean_fqn_to_curr_fqn: dict[str, str] = {}
    if is_named_optimizer:
        if param_to_fqns is None or flat_param_to_fqn is None:
            raise AssertionError('The optimizer is a NamedOptimizer, `param_to_fqns` must not be None.')
        if model is None:
            raise AssertionError(f'Expected model to be not None, got {model}')
        for (key, _) in _named_parameters_with_duplicates(model):
            clean_fqn_to_curr_fqn[clean_tensor_name(key)] = key
    param_key_to_param: dict[Union[str, int], nn.Parameter] = {}
    pid = 0
    for param_group in optim.param_groups:
        if is_named_optimizer:
            for param in param_group['params']:
                if flat_param_to_fqn is None:
                    raise AssertionError(f'Expected flat_param_to_fqn to be not None, got {flat_param_to_fqn}')
                if param in flat_param_to_fqn:
                    key = flat_param_to_fqn[param]
                else:
                    if <MASK>:
                        raise AssertionError(f'Expected param_to_fqns to be not None, got {param_to_fqns}')
                    if len(param_to_fqns[param]) != 1:
                        raise AssertionError(f'Expected len(param_to_fqns[param]) == 1, got {len(param_to_fqns[param])}')
                    key = param_to_fqns[param][0]
                try:
                    key = clean_fqn_to_curr_fqn[key]
                except KeyError as e:
                    raise KeyError(f"Can't find {key} from {list(clean_fqn_to_curr_fqn.keys())}.") from e
                param_key_to_param[key] = param
        else:
            for param in param_group['params']:
                param_key_to_param[pid] = param
                pid += 1
    return param_key_to_param

def explicit_super(code: types.CodeType, instructions: list[Instruction]) -> None:
    """convert super() with no args into explicit arg form"""
    cell_and_free = (code.co_cellvars or ()) + (code.co_freevars or ())
    if <MASK>:
        return
    output = []
    for (idx, inst) in enumerate(instructions):
        output.append(inst)
        if inst.opname == 'LOAD_GLOBAL' and inst.argval == 'super':
            nexti = instructions[idx + 1]
            if nexti.arg == 0 and (sys.version_info >= (3, 12) and nexti.opname == 'CALL' or (sys.version_info >= (3, 11) and sys.version_info < (3, 12) and (nexti.opname == 'PRECALL')) or (sys.version_info < (3, 11) and nexti.opname == 'CALL_FUNCTION')):
                assert '__class__' in cell_and_free
                output.append(create_instruction('LOAD_DEREF', argval='__class__'))
                first_var = code.co_varnames[0]
                if first_var in cell_and_free:
                    output.append(create_instruction('LOAD_DEREF', argval=first_var))
                else:
                    output.append(create_instruction('LOAD_FAST', argval=first_var))
                nexti.arg = 2
                nexti.argval = 2
                if nexti.opname == 'PRECALL':
                    call_inst = instructions[idx + 2]
                    call_inst.arg = 2
                    call_inst.argval = 2
    instructions[:] = output

