def _scaled_mm_like_strategy(mm_equation: str, mesh: DeviceMesh, op_schema: OpSchema) -> OpStrategy:
    (self_strategy, mat2_strategy, scale_self_strategy, scale_mat2_strategy, bias_strategy, scale_result_strategy, *_) = op_schema.args_schema
    if not isinstance(self_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(self_strategy)}')
    if not isinstance(mat2_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(mat2_strategy)}')
    if not isinstance(scale_self_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(scale_self_strategy)}')
    if not isinstance(scale_mat2_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(scale_mat2_strategy)}')
    if bias_strategy is not None:
        raise AssertionError("_scaled_mm on DTensors doesn't support bias")
    if scale_result_strategy is not None:
        raise AssertionError("_scaled_mm on DTensors doesn't support scale_result")
    mm_strategy = gen_einsum_strategies(mm_equation, mesh)
    strategies = mm_strategy.strategies
    filtered_strategies = []
    for strtg in strategies:
        if strtg.input_specs is None:
            raise AssertionError(f'Expected input_specs to be not None, got {strtg.input_specs}')
        self_spec = strtg.input_specs[0]
        mat2_spec = strtg.input_specs[1]
        scale_self_spec = DTensorSpec(self_spec.mesh, (Replicate(),)) if prod(scale_self_strategy.shape) == 1 else self_spec
        scale_mat2_spec = DTensorSpec(mat2_spec.mesh, (Replicate(),)) if prod(scale_mat2_strategy.shape) == 1 else mat2_spec
        strtg.input_specs = list(strtg.input_specs) + [scale_self_spec, scale_mat2_spec]
        if <MASK>:
            redistribute_cost = [generate_redistribute_costs(self_strategy, self_spec), generate_redistribute_costs(mat2_strategy, mat2_spec), generate_redistribute_costs(scale_self_strategy, scale_self_spec), generate_redistribute_costs(scale_mat2_strategy, scale_mat2_spec)]
            strtg.redistribute_cost = redistribute_cost
            filtered_strategies.append(strtg)
    mm_strategy.strategies = filtered_strategies
    return mm_strategy

def prune_unconnected_ops_from_xla(prune_graph: ops.Graph):
    """Prunes unconnected ops as listed in _UNCONNECTED_OPS_TO_PRUNE.

  Args:
    prune_graph: A tensorflow graph from which we wish to prune unconnected ops
      as listed in _UNCONNECTED_OPS_TO_PRUNE.  In general, these ops should have
      no inputs and no consumers. These can often be left behind due to graph
      construction rewiring (for instance TF-Hub). While they never execute,
      they will cause XLA compile to fail so we strip them from XLA compile by
      removing the tpu_replicate attribute.
  """
    for graph in [prune_graph] + [f for f in prune_graph._functions.values()]:
        if <MASK>:
            continue
        for op in graph.get_operations():
            if op.type not in _UNCONNECTED_OPS_TO_PRUNE:
                continue
            outputs_consumed = False
            for output in op.outputs:
                if output.consumers():
                    outputs_consumed = True
                    break
            if not outputs_consumed:
                logging.info('Pruning OP %s of type %s from XLA Compile due to it being disconnected.', op.name, op.type)
                op._clear_attr(tpu_replication._TPU_REPLICATE_ATTR)

def _reduce_pyarrow(self, name: str, *, skipna: bool=True, **kwargs) -> pa.Scalar:
    """
        Return a pyarrow scalar result of performing the reduction operation.

        Parameters
        ----------
        name : str
            Name of the function, supported values are:
            { any, all, min, max, sum, mean, median, prod,
            std, var, sem, kurt, skew }.
        skipna : bool, default True
            If True, skip NaN values.
        **kwargs
            Additional keyword arguments passed to the reduction function.
            Currently, `ddof` is the only supported kwarg.

        Returns
        -------
        pyarrow scalar

        Raises
        ------
        TypeError : subclass does not define reductions
        """
    pa_type = self._pa_array.type
    data_to_reduce = self._pa_array
    if name in ['any', 'all'] and (pa.types.is_integer(pa_type) or pa.types.is_floating(pa_type) or pa.types.is_duration(pa_type) or pa.types.is_decimal(pa_type)):
        if pa.types.is_duration(pa_type):
            data_to_cmp = self._pa_array.cast(pa.int64())
        else:
            data_to_cmp = self._pa_array
        not_eq = pc.not_equal(data_to_cmp, 0)
        data_to_reduce = not_eq
    elif name in ['min', 'max', 'sum'] and pa.types.is_duration(pa_type):
        data_to_reduce = self._pa_array.cast(pa.int64())
    elif name in ['median', 'mean', 'std', 'sem'] and pa.types.is_temporal(pa_type):
        nbits = pa_type.bit_width
        if nbits == 32:
            data_to_reduce = self._pa_array.cast(pa.int32())
        else:
            data_to_reduce = self._pa_array.cast(pa.int64())
    if <MASK>:

        def pyarrow_meth(data, skip_nulls, **kwargs):
            numerator = pc.stddev(data, skip_nulls=skip_nulls, **kwargs)
            denominator = pc.sqrt_checked(pc.count(self._pa_array))
            return pc.divide_checked(numerator, denominator)
    elif name == 'sum' and (pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type)):

        def pyarrow_meth(data, skip_nulls, min_count=0):
            mask = pc.is_null(data) if data.null_count > 0 else None
            if skip_nulls:
                if min_count > 0 and check_below_min_count((len(data),), None if mask is None else mask.to_numpy(), min_count):
                    return pa.scalar(None, type=data.type)
                if data.null_count > 0:
                    data = data.filter(pc.invert(mask))
            elif mask is not None or check_below_min_count((len(data),), None, min_count):
                return pa.scalar(None, type=data.type)
            if pa.types.is_large_string(data.type):
                data = data.cast(pa.string())
            data_list = pa.ListArray.from_arrays([0, len(data)], data.combine_chunks())[0]
            return pc.binary_join(data_list, '')
    else:
        pyarrow_name = {'median': 'quantile', 'prod': 'product', 'std': 'stddev', 'var': 'variance'}.get(name, name)
        pyarrow_meth = getattr(pc, pyarrow_name, None)
        if pyarrow_meth is None:
            return super()._reduce(name, skipna=skipna, **kwargs)
    if name in ['any', 'all'] and 'min_count' not in kwargs:
        kwargs['min_count'] = 0
    elif name == 'median':
        kwargs['q'] = 0.5
    try:
        result = pyarrow_meth(data_to_reduce, skip_nulls=skipna, **kwargs)
    except (AttributeError, NotImplementedError, TypeError) as err:
        msg = f"'{type(self).__name__}' with dtype {self.dtype} does not support operation '{name}' with pyarrow version {pa.__version__}. '{name}' may be supported by upgrading pyarrow."
        raise TypeError(msg) from err
    if name == 'median':
        result = result[0]
    if name in ['min', 'max', 'sum'] and pa.types.is_duration(pa_type):
        result = result.cast(pa_type)
    if name in ['median', 'mean'] and pa.types.is_temporal(pa_type):
        nbits = pa_type.bit_width
        if nbits == 32:
            result = result.cast(pa.int32(), safe=False)
        else:
            result = result.cast(pa.int64(), safe=False)
        result = result.cast(pa_type)
    if name in ['std', 'sem'] and pa.types.is_temporal(pa_type):
        result = result.cast(pa.int64(), safe=False)
        if pa.types.is_duration(pa_type):
            result = result.cast(pa_type)
        elif pa.types.is_time(pa_type):
            result = result.cast(pa.duration(pa_type.unit))
        elif pa.types.is_date(pa_type):
            result = result.cast(pa.duration('s'))
        else:
            result = result.cast(pa.duration(pa_type.unit))
    return result

def _node_metadata_hook(node: torch.fx.Node, stack_trace: Optional[str]=None, nn_module_stack: Optional[dict[str, Any]]=None) -> None:
    fake_args = pytree.tree_map(lambda arg: _get_example_value(arg) if isinstance(arg, torch.fx.Node) else arg, node.args)
    try:
        target = node.target
        if <MASK>:
            assert isinstance(node.target, str)
            target = getattr(fake_args[0], node.target)
            fake_args = fake_args[1:]
        node.meta[val_key] = target(*fake_args)
    except NotImplementedError:
        pass
    if stack_trace is not None:
        node.meta['stack_trace'] = stack_trace
    if nn_module_stack is not None:
        node.meta['nn_module_stack'] = nn_module_stack

