def create_backend(self, device: torch.device) -> BaseScheduling:
    assert not is_gpu(device.type) or device.index is not None, f'{device} should have been normalized in lowering'
    V.graph.add_device_info(device)
    device_scheduling = get_scheduling_for_device(device.type)
    if <MASK>:
        raise RuntimeError(f'Unsupported device type: {device.type}')
    if not has_triton():
        if device.type == 'cuda' and (device_props := torch.cuda.get_device_properties(device)).major < 7:
            raise GPUTooOldForTriton(device_props, inspect.currentframe())
        elif is_gpu(device.type) and (not device.type == 'mps'):
            raise TritonMissing(inspect.currentframe())
    return device_scheduling(self)

def expr_to_dimension(expr, syms):
    expr = sympy.factor(expr)
    if len(syms) == 1:
        stride_wild = sympy.Wild('wild', exclude=symbols)
        m = expr.match(stride_wild * syms[0])
        if m:
            return DimensionInfo(syms[0], self.sym_size(syms[0]), m[stride_wild])
    assert not is_store, expr
    length = sympy.simplify(sympy_subs(expr, {sym: self.sym_size(sym) - 1 for sym in syms}) + 1)
    stride = sympy.S.One
    if isinstance(expr, sympy.Mul):
        for term in expr.args:
            if <MASK>:
                stride *= term
                expr = sympy.simplify(expr / term)
                length = sympy.simplify(sympy.ceiling(length / term))
    return DimensionInfo(expr, length, stride)

def __init__(self, *expressions, fields=(), name=None, db_tablespace=None, opclasses=(), condition=None, include=None):
    if opclasses and (not name):
        raise ValueError('An index must be named to use opclasses.')
    if not isinstance(condition, (NoneType, Q)):
        raise ValueError('Index.condition must be a Q instance.')
    if condition and (not name):
        raise ValueError('An index must be named to use condition.')
    if not isinstance(fields, (list, tuple)):
        raise ValueError('Index.fields must be a list or tuple.')
    if not isinstance(opclasses, (list, tuple)):
        raise ValueError('Index.opclasses must be a list or tuple.')
    if not expressions and (not fields):
        raise ValueError('At least one field or expression is required to define an index.')
    if expressions and fields:
        raise ValueError('Index.fields and expressions are mutually exclusive.')
    if expressions and (not name):
        raise ValueError('An index must be named to use expressions.')
    if expressions and opclasses:
        raise ValueError('Index.opclasses cannot be used with expressions. Use django.contrib.postgres.indexes.OpClass() instead.')
    if opclasses and len(fields) != len(opclasses):
        raise ValueError('Index.fields and Index.opclasses must have the same number of elements.')
    if <MASK>:
        raise ValueError('Index.fields must contain only strings with field names.')
    if include and (not name):
        raise ValueError('A covering index must be named.')
    if not isinstance(include, (NoneType, list, tuple)):
        raise ValueError('Index.include must be a list or tuple.')
    self.fields = list(fields)
    self.fields_orders = [(field_name.removeprefix('-'), 'DESC' if field_name.startswith('-') else '') for field_name in self.fields]
    self.name = name or ''
    self.db_tablespace = db_tablespace
    self.opclasses = opclasses
    self.condition = condition
    self.include = tuple(include) if include else ()
    self.expressions = tuple((F(expression) if isinstance(expression, str) else expression for expression in expressions))

def _fit(self, X):
    """Fit without validation

        Parameters
        ----------
        X : ndarray of shape (n_samples, n_features) or (n_samples, n_samples)
            Training instances to cluster, or distances between instances if
            ``metric='precomputed'``.

        Returns
        -------
        self : object
            Returns the fitted instance.
        """
    memory = check_memory(self.memory)
    if not (self.n_clusters is None) ^ (self.distance_threshold is None):
        raise ValueError('Exactly one of n_clusters and distance_threshold has to be set, and the other needs to be None.')
    if self.distance_threshold is not None and (not self.compute_full_tree):
        raise ValueError('compute_full_tree must be True if distance_threshold is set.')
    if self.linkage == 'ward' and self.metric != 'euclidean':
        raise ValueError(f'{self.metric} was provided as metric. Ward can only work with euclidean distances.')
    tree_builder = _TREE_BUILDERS[self.linkage]
    connectivity = self.connectivity
    if self.connectivity is not None:
        if callable(self.connectivity):
            connectivity = self.connectivity(X)
        connectivity = check_array(connectivity, accept_sparse=['csr', 'coo', 'lil'])
    n_samples = len(X)
    compute_full_tree = self.compute_full_tree
    if self.connectivity is None:
        compute_full_tree = True
    if compute_full_tree == 'auto':
        if self.distance_threshold is not None:
            compute_full_tree = True
        else:
            compute_full_tree = self.n_clusters < max(100, 0.02 * n_samples)
    n_clusters = self.n_clusters
    if <MASK>:
        n_clusters = None
    kwargs = {}
    if self.linkage != 'ward':
        kwargs['linkage'] = self.linkage
        kwargs['affinity'] = self.metric
    distance_threshold = self.distance_threshold
    return_distance = distance_threshold is not None or self.compute_distances
    out = memory.cache(tree_builder)(X, connectivity=connectivity, n_clusters=n_clusters, return_distance=return_distance, **kwargs)
    (self.children_, self.n_connected_components_, self.n_leaves_, parents) = out[:4]
    if return_distance:
        self.distances_ = out[-1]
    if self.distance_threshold is not None:
        self.n_clusters_ = np.count_nonzero(self.distances_ >= distance_threshold) + 1
    else:
        self.n_clusters_ = self.n_clusters
    if compute_full_tree:
        self.labels_ = _hc_cut(self.n_clusters_, self.children_, self.n_leaves_)
    else:
        labels = _hierarchical.hc_get_heads(parents, copy=False)
        labels = np.copy(labels[:n_samples])
        self.labels_ = np.searchsorted(np.unique(labels), labels)
    return self

def create_local_plan(self) -> LoadPlan:
    requests = []
    self.translation = {}
    for (fqn, obj) in self.state_dict.items():
        md = self.metadata.state_dict_metadata[fqn]
        if <MASK>:
            requests += _create_read_items(fqn, md, obj)
            continue
        if fqn not in self.fqn_to_offset:
            requests += _create_read_items(fqn, md, obj)
            continue
        offset = self.fqn_to_offset[fqn]
        if not len(obj.local_shards()) == 1:
            raise AssertionError('Expected exactly one local shard')
        original_shard = obj.local_shards()[0]
        local_chunks = [ChunkStorageMetadata(offsets=torch.Size(_element_wise_add(original_shard.metadata.shard_offsets, offset)), sizes=torch.Size(original_shard.metadata.shard_sizes))]
        reqs = create_read_items_for_chunk_list(fqn, cast(TensorStorageMetadata, md), local_chunks)
        for ri in reqs:
            if ri.dest_index.offset is None:
                raise AssertionError('dest_index.offset must not be None')
            original_offset = _element_wise_sub(ri.dest_index.offset, offset)
            original_index = dataclasses.replace(ri.dest_index, offset=torch.Size(original_offset))
            self.translation[ri.dest_index] = original_index
        requests += reqs
    return LoadPlan(requests)

def generate_inputs_for_model(model_cls, model, model_name, bs, device, include_loss_args=False):
    num_choices = 3
    num_visual_features = 42
    seq_length = get_sequence_length(model_cls, model_name)
    vocab_size = model.config.vocab_size
    if model_name.startswith('Wav2Vec2'):
        target_length = 100
        return {'input_values': torch.randn((bs, seq_length), device=device), 'attention_mask': rand_int_tensor(device, 0, 2, (bs, seq_length)), 'labels': rand_int_tensor(device, 0, vocab_size, (bs, target_length))}
    if model_name.endswith('MultipleChoice'):
        input = rand_int_tensor(device, 0, vocab_size, (bs, num_choices, seq_length))
    elif model_name.startswith('Roberta'):
        input = rand_int_tensor(device, 0, 1, (bs, seq_length))
    else:
        input = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
    if 'Bart' in model_name:
        input[:, -1] = model.config.eos_token_id
    input_dict = {'input_ids': input}
    if model_name.startswith(('T5', 'M2M100', 'MT5')) or model_cls in [BlenderbotModel, BlenderbotSmallModel, BlenderbotForConditionalGeneration, PegasusModel, MarianModel, MarianMTModel]:
        input_dict['decoder_input_ids'] = input
    if model_name.startswith('Lxmert'):
        (visual_feat_dim, visual_pos_dim) = (model.config.visual_feat_dim, model.config.visual_pos_dim)
        input_dict['visual_feats'] = torch.randn(bs, num_visual_features, visual_feat_dim)
        input_dict['visual_pos'] = torch.randn(bs, num_visual_features, visual_pos_dim)
    if include_loss_args:
        if <MASK>:
            if model_cls in [ElectraForPreTraining, LxmertForPreTraining]:
                input_dict['labels'] = rand_int_tensor(device, 0, 1, (bs, seq_length))
            else:
                label_name = 'sentence_order_label' if model_cls in [AlbertForPreTraining] else 'next_sentence_label'
                input_dict['labels'] = (rand_int_tensor(device, 0, vocab_size, (bs, seq_length)),)
                input_dict[label_name] = rand_int_tensor(device, 0, 1, (bs,))
        elif model_name.endswith('QuestionAnswering'):
            input_dict['start_positions'] = rand_int_tensor(device, 0, seq_length, (bs,))
            input_dict['end_positions'] = rand_int_tensor(device, 0, seq_length, (bs,))
        elif model_name.endswith(('MaskedLM', 'HeadModel', 'CausalLM', 'DoubleHeadsModel')):
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
        elif model_name.endswith('TokenClassification'):
            input_dict['labels'] = rand_int_tensor(device, 0, model.config.num_labels - 1, (bs, seq_length))
        elif model_name.endswith('MultipleChoice'):
            input_dict['labels'] = rand_int_tensor(device, 0, num_choices, (bs,))
        elif model_name.endswith('SequenceClassification'):
            input_dict['labels'] = rand_int_tensor(device, 0, model.config.num_labels - 1, (bs,))
        elif model_name.endswith('NextSentencePrediction'):
            input_dict['labels'] = rand_int_tensor(device, 0, 1, (bs,))
        elif model_name.endswith('ForConditionalGeneration'):
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size - 1, (bs, seq_length))
        elif model_name in EXTRA_MODELS:
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
        else:
            raise NotImplementedError(f'Class {model_name} unsupported for training test ')
    return input_dict

def dtypes(self, *, device=None, kind=None):
    """
        The array API data types supported by CuPy.

        Note that this function only returns data types that are defined by
        the array API.

        Parameters
        ----------
        device : str, optional
            The device to get the data types for.
        kind : str or tuple of str, optional
            The kind of data types to return. If ``None``, all data types are
            returned. If a string, only data types of that kind are returned.
            If a tuple, a dictionary containing the union of the given kinds
            is returned. The following kinds are supported:

            - ``'bool'``: boolean data types (i.e., ``bool``).
            - ``'signed integer'``: signed integer data types (i.e., ``int8``,
              ``int16``, ``int32``, ``int64``).
            - ``'unsigned integer'``: unsigned integer data types (i.e.,
              ``uint8``, ``uint16``, ``uint32``, ``uint64``).
            - ``'integral'``: integer data types. Shorthand for ``('signed
              integer', 'unsigned integer')``.
            - ``'real floating'``: real-valued floating-point data types
              (i.e., ``float32``, ``float64``).
            - ``'complex floating'``: complex floating-point data types (i.e.,
