@staticmethod
def find_device(tensor_args: Optional[Sequence[torch.Tensor]], example_output: Sequence[Any]) -> Any:
    non_torch_bind_tensor_args = [t for t in tensor_args if not isinstance(t, TorchBindObject)] if tensor_args else None
    if non_torch_bind_tensor_args:
        assert tensor_args
        devices = [arg.get_device() for arg in tensor_args if arg.get_device()]
        return devices[0]
    if isinstance(example_output, torch.Tensor):
        return example_output.device
    if isinstance(example_output, (list, tuple)):
        device_set = OrderedSet((FallbackKernel.find_device(None, x) for x in example_output))
        devices = [device for device in device_set if device]
        if len(devices) == 1:
            return devices[0]
        for device in devices:
            assert isinstance(device, torch.device)
            if <MASK>:
                return device
        return devices[0]
    return None

def database_forwards(self, app_label, schema_editor, from_state, to_state):
    model = to_state.apps.get_model(app_label, self.model_name)
    if not self.allow_migrate_model(schema_editor.connection.alias, model):
        return
    if self.old_fields:
        from_model = from_state.apps.get_model(app_label, self.model_name)
        columns = [from_model._meta.get_field(field).column for field in self.old_fields]
        matching_index_name = schema_editor._constraint_names(from_model, column_names=columns, index=True, unique=False)
        if <MASK>:
            raise ValueError('Found wrong number (%s) of indexes for %s(%s).' % (len(matching_index_name), from_model._meta.db_table, ', '.join(columns)))
        old_index = models.Index(fields=self.old_fields, name=matching_index_name[0])
    else:
        from_model_state = from_state.models[app_label, self.model_name_lower]
        old_index = from_model_state.get_index_by_name(self.old_name)
    if old_index.name == self.new_name:
        return
    to_model_state = to_state.models[app_label, self.model_name_lower]
    new_index = to_model_state.get_index_by_name(self.new_name)
    schema_editor.rename_index(model, old_index, new_index)

