def _rewrite_forward_and_call_backward(self, op: ops.Operation, *doutputs):
    """Add outputs to the forward call and feed them to the grad function."""
    (forward_function, backwards_function) = self.forward_backward(len(doutputs))
    if <MASK>:
        return backwards_function.structured_outputs
    op.graph._add_function_recursive(forward_function)
    op._set_func_attr('f', forward_function.name)
    op._set_type_list_attr('Tout', [o.dtype.as_datatype_enum for o in forward_function.function_type.flat_outputs])
    truncated_outputs = forward_function.function_type.flat_outputs[len(op.outputs):]
    op._add_outputs([o.dtype.as_datatype_enum for o in truncated_outputs], [o.shape for o in truncated_outputs])
    for i in range(len(op.outputs)):
        output_type = forward_function.function_type.flat_outputs[i]
        handle_data = output_type.dtype._handle_data
        if handle_data:
            handle_data_util.set_handle_data(op.outputs[i], handle_data.shape_inference)
    capture_mapping = dict(zip((ops.tensor_id(t) for t in self._func_graph.outputs), op.outputs))
    remapped_captures = [capture_mapping.get(ops.tensor_id(capture), capture) for capture in backwards_function.captured_inputs]
    cleaned_doutputs = []
    for (doutput, placeholder) in zip(doutputs, self._func_graph.outputs):
        if backprop_util.IsTrainable(placeholder):
            if isinstance(doutput, indexed_slices.IndexedSlices):
                cleaned_doutputs.append(ops.convert_to_tensor(doutput))
            elif doutput is not None:
                cleaned_doutputs.append(doutput)
            else:
                cleaned_doutputs.append(default_gradient.zeros_like(placeholder))
    return backwards_function._call_flat(cleaned_doutputs, remapped_captures)

def _apply_rule(self, dates: DatetimeIndex) -> DatetimeIndex:
    """
        Apply the given offset/observance to a DatetimeIndex of dates.

        Parameters
        ----------
        dates : DatetimeIndex
            Dates to apply the given offset/observance rule

        Returns
        -------
        Dates with rules applied
        """
    if dates.empty:
        return dates.copy()
    if self.observance is not None:
        return dates.map(lambda d: self.observance(d))
    if self.offset is not None:
        if <MASK>:
            offsets = [self.offset]
        else:
            offsets = self.offset
        for offset in offsets:
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', PerformanceWarning)
                dates += offset
    return dates

def cast(self, value: Any, casting_context: Any) -> Any:
    if not isinstance(value, self.value_type):
        raise TypeError(f'[{value!r}] is not of type {self.value_type}.')
    (value_metadata, value_components) = value.__tf_flatten__()
    if self.metadata != value_metadata:
        raise ValueError(f'Metadata mismatch: [{self.metadata!r}] != [{value_metadata!r}].')
    if len(self.components) != len(value_components):
        raise ValueError(f'Lengths of components mismatch: {len(self.components)} != {len(value_components)}.')
    (casted_value_components, was_casted) = util.cast_and_return_whether_casted(self.components, value_components, casting_context)
    if <MASK>:
        return self.value_type.__tf_unflatten__(self.metadata, casted_value_components)
    else:
        return value

def extract_val(val: _ExtractValType, include_real: bool=False) -> _ExtractValType:
    if is_fake(val):
        return snapshot_fake(val, include_real=include_real)
    elif isinstance(val, py_sym_types):
        return val
    elif isinstance(val, _AnyScriptObject):
        return val
    elif isinstance(val, BackwardState):
        return val
    elif isinstance(val, (list, tuple)):
        return val.__class__([extract_val(x) for x in val])
    elif isinstance(val, dict):
        return {k: extract_val(v) for (k, v) in val.items()}
    elif <MASK>:
        if not val.is_sparse:
            from torch._guards import detect_fake_mode
            fake_tensor_mode = detect_fake_mode(val)
            if not fake_tensor_mode:
                fake_tensor_mode = FakeTensorMode(allow_fallback_kernels=True)
            with fake_tensor_mode:
                return torch.empty_strided(val.shape, val.stride(), device=val.device, dtype=val.dtype)
        else:
            return None
    elif isinstance(val, (int, float, bool)):
        return val
    elif val is None:
        return None
    typing_extensions.assert_never(val)

def create_node(self, kind: str, target: Target, args: tuple[Argument, ...], kwargs: dict[str, Argument], name: Optional[str]=None, type_expr: Optional[Any]=None) -> torch.fx.Node:
    node = super().create_node(kind, target, args, kwargs, name, type_expr)
