@final
def _maybe_mask_setitem_value(self, indexer, value):
    """
        If we have obj.iloc[mask] = series_or_frame and series_or_frame has the
        same length as obj, we treat this as obj.iloc[mask] = series_or_frame[mask],
        similar to Series.__setitem__.

        Note this is only for loc, not iloc.
        """
    if isinstance(indexer, tuple) and len(indexer) == 2 and isinstance(value, (ABCSeries, ABCDataFrame)):
        (pi, icols) = indexer
        ndim = value.ndim
        if com.is_bool_indexer(pi) and len(value) == len(pi):
            newkey = pi.nonzero()[0]
            if is_scalar_indexer(icols, self.ndim - 1) and ndim == 1:
                if len(newkey) == 0:
                    value = value.iloc[:0]
                else:
                    value = self.obj.iloc._align_series(indexer, value)
                indexer = (newkey, icols)
            elif isinstance(icols, np.ndarray) and icols.dtype.kind == 'i' and (len(icols) == 1):
                if <MASK>:
                    value = self.obj.iloc._align_series(indexer, value)
                    indexer = (newkey, icols)
                elif ndim == 2 and value.shape[1] == 1:
                    if len(newkey) == 0:
                        value = value.iloc[:0]
                    else:
                        value = self.obj.iloc._align_frame(indexer, value)
                    indexer = (newkey, icols)
    elif com.is_bool_indexer(indexer):
        indexer = indexer.nonzero()[0]
    return (indexer, value)

def reduced_f32_on_and_off(bf32_precision=0.01, tf32_precision=1e-05):

    def with_reduced_f32_disabled(self, function_call):
        with reduced_f32_off():
            function_call()

    def with_bf32_enabled(self, function_call):
        with bf32_on(self, bf32_precision):
            function_call()

    def with_tf32_enabled(self, function_call):
        with tf32_on(self, tf32_precision):
            function_call()

    def wrapper(f):
        params = inspect.signature(f).parameters
        arg_names = tuple(params.keys())

        @functools.wraps(f)
        def wrapped(*args, **kwargs):
            kwargs.update(zip(arg_names, args, strict=False))
            cond = True
            if 'device' in kwargs:
                cond = cond and torch.device(kwargs['device']).type == 'cpu'
            if 'dtype' in kwargs:
                cond = cond and kwargs['dtype'] == torch.float
            bf32_cond = cond and bf32_is_not_fp32()
            tf32_cond = cond and tf32_is_not_fp32()
            if bf32_cond or tf32_cond:
                with_reduced_f32_disabled(kwargs['self'], lambda : f(**kwargs))
                if <MASK>:
                    with_bf32_enabled(kwargs['self'], lambda : f(**kwargs))
                if tf32_cond:
                    with_tf32_enabled(kwargs['self'], lambda : f(**kwargs))
            else:
                f(**kwargs)
        return wrapped
    return wrapper

def _parse_sheet(self, data: list, output: dict, asheetname: str | int | None=None, header: int | Sequence[int] | None=0, names: SequenceNotStr[Hashable] | range | None=None, index_col: int | Sequence[int] | None=None, usecols=None, dtype: DtypeArg | None=None, skiprows: Sequence[int] | int | Callable[[int], object] | None=None, nrows: int | None=None, true_values: Iterable[Hashable] | None=None, false_values: Iterable[Hashable] | None=None, na_values=None, parse_dates: list | dict | bool=False, date_format: dict[Hashable, str] | str | None=None, thousands: str | None=None, decimal: str='.', comment: str | None=None, skipfooter: int=0, dtype_backend: DtypeBackend | lib.NoDefault=lib.no_default, **kwds):
    is_list_header = False
    is_len_one_list_header = False
    if is_list_like(header):
        assert isinstance(header, Sequence)
        is_list_header = True
        if len(header) == 1:
            is_len_one_list_header = True
    if is_len_one_list_header:
        header = cast(Sequence[int], header)[0]
    header_names = None
    if header is not None and is_list_like(header):
        assert isinstance(header, Sequence)
        header_names = []
        control_row = [True] * len(data[0])
        for row in header:
            if is_integer(skiprows):
                assert isinstance(skiprows, int)
                row += skiprows
            if row > len(data) - 1:
                raise ValueError(f'header index {row} exceeds maximum index {len(data) - 1} of data.')
            (data[row], control_row) = fill_mi_header(data[row], control_row)
            if <MASK>:
                (header_name, _) = pop_header_name(data[row], index_col)
                header_names.append(header_name)
    has_index_names = False
    if is_list_header and (not is_len_one_list_header) and (index_col is not None):
        index_col_set: set[int]
        if isinstance(index_col, int):
            index_col_set = {index_col}
        else:
            assert isinstance(index_col, Sequence)
            index_col_set = set(index_col)
        assert isinstance(header, Sequence)
        if len(header) < len(data):
            potential_index_names = data[len(header)]
            has_index_names = all((x == '' or x is None for (i, x) in enumerate(potential_index_names) if not control_row[i] and i not in index_col_set))
    if is_list_like(index_col):
        if header is None:
            offset = 0
        elif isinstance(header, int):
            offset = 1 + header
        else:
            offset = 1 + max(header)
        if has_index_names:
            offset += 1
        if offset < len(data):
            assert isinstance(index_col, Sequence)
            for col in index_col:
                last = data[offset][col]
                for row in range(offset + 1, len(data)):
                    if data[row][col] == '' or data[row][col] is None:
                        data[row][col] = last
                    else:
                        last = data[row][col]
    try:
        parser = TextParser(data, names=names, header=header, index_col=index_col, has_index_names=has_index_names, dtype=dtype, true_values=true_values, false_values=false_values, skiprows=skiprows, nrows=nrows, na_values=na_values, skip_blank_lines=False, parse_dates=parse_dates, date_format=date_format, thousands=thousands, decimal=decimal, comment=comment, skipfooter=skipfooter, usecols=usecols, dtype_backend=dtype_backend, **kwds)
        output[asheetname] = parser.read(nrows=nrows)
        if header_names:
            output[asheetname].columns = output[asheetname].columns.set_names(header_names)
    except EmptyDataError:
        output[asheetname] = DataFrame()
    except Exception as err:
        err.args = (f'{err.args[0]} (sheet: {asheetname})', *err.args[1:])
        raise err
    return output

def get_neighbour_values(self, name, orig_val, radius=1, include_self=False):
    """
        Get neighbour values in 'radius' steps. The original value is not
        returned as it's own neighbour.
        """
    assert radius >= 1

    def update(cur_val, inc=True):
        if <MASK>:
            if inc:
                return cur_val + 1
            else:
                return cur_val - 1
        elif inc:
            return cur_val * 2
        else:
            return cur_val // 2
    out = []
    cur_val = orig_val
    for _ in range(radius):
        cur_val = update(cur_val, True)
        if self.value_too_large(name, cur_val):
            break
        out.append(cur_val)
    cur_val = orig_val
    for _ in range(radius):
        cur_val = update(cur_val, False)
        if self.value_too_small(name, cur_val):
            break
        out.append(cur_val)
    if include_self:
        out.append(orig_val)
    return out

