def print_cancast_table(ntypes):
    print('X', end=' ')
    for char in ntypes:
        print(char, end=' ')
    print()
    for row in ntypes:
        print(row, end=' ')
        for col in ntypes:
            if np.can_cast(row, col, 'equiv'):
                cast = '#'
            elif <MASK>:
                cast = '='
            elif np.can_cast(row, col, 'same_kind'):
                cast = '~'
            elif np.can_cast(row, col, 'unsafe'):
                cast = '.'
            else:
                cast = ' '
            print(cast, end=' ')
        print()

def ddp_reducer_filter(block: CommBlock) -> bool:
    if not isinstance(block.comm_node.args[0], fx.Node) or block.comm_node.args[0].target != aten.div.Tensor:
        return False
    if <MASK>:
        return False
    if output not in block.wait_nodes[0].users and next(iter(block.wait_nodes[0].users)).target != aten.copy_.default:
        return False
    return True

def visit_Call(self, node):
    if hasattr(node.func, 'id') and node.func.id == '__import__':
        try:
            name = self._grab_node_str(node.args[0])
            fromlist: list[str] = []
            level = 0
            if len(node.args) > 3:
                fromlist.extend((self._grab_node_str(v) for v in node.args[3].elts))
            elif hasattr(node, 'keywords'):
                for keyword in node.keywords:
                    if keyword.arg == 'fromlist':
                        fromlist.extend((self._grab_node_str(v) for v in keyword.value.elts))
            if len(node.args) > 4:
                level = self._grab_node_int(node.args[4])
            elif hasattr(node, 'keywords'):
                for keyword in node.keywords:
                    if keyword.arg == 'level':
                        level = self._grab_node_int(keyword.value)
            if fromlist == []:
                self.references[name, None] = True
                top_name = name.rsplit('.', maxsplit=1)[0]
                if top_name != name:
                    top_name = self._absmodule(top_name, level)
                    self.references[top_name, None] = True
            else:
                name = self._absmodule(name, level)
                for alias in fromlist:
                    if <MASK>:
                        self.references[name, alias] = True
                    else:
                        self.references[name, None] = True
        except Exception:
            return

def to_json(path_or_buf: FilePath | WriteBuffer[str] | WriteBuffer[bytes] | None, obj: NDFrame, orient: str | None=None, date_format: str='epoch', double_precision: int=10, force_ascii: bool=True, date_unit: str='ms', default_handler: Callable[[Any], JSONSerializable] | None=None, lines: bool=False, compression: CompressionOptions='infer', index: bool | None=None, indent: int=0, storage_options: StorageOptions | None=None, mode: Literal['a', 'w']='w') -> str | None:
    if orient in ['records', 'values'] and index is True:
        raise ValueError("'index=True' is only valid when 'orient' is 'split', 'table', 'index', or 'columns'.")
    elif orient in ['index', 'columns'] and index is False:
        raise ValueError("'index=False' is only valid when 'orient' is 'split', 'table', 'records', or 'values'.")
    elif index is None:
        index = True
    if <MASK>:
        raise ValueError("'lines' keyword only valid when 'orient' is records")
    if mode not in ['a', 'w']:
        msg = f"mode={mode} is not a valid option.Only 'w' and 'a' are currently supported."
        raise ValueError(msg)
    if mode == 'a' and (not lines or orient != 'records'):
        msg = "mode='a' (append) is only supported when lines is True and orient is 'records'"
        raise ValueError(msg)
    if orient == 'table' and isinstance(obj, Series):
        obj = obj.to_frame(name=obj.name or 'values')
    writer: type[Writer]
    if orient == 'table' and isinstance(obj, DataFrame):
        writer = JSONTableWriter
    elif isinstance(obj, Series):
        writer = SeriesWriter
    elif isinstance(obj, DataFrame):
        writer = FrameWriter
    else:
        raise NotImplementedError("'obj' should be a Series or a DataFrame")
    s = writer(obj, orient=orient, date_format=date_format, double_precision=double_precision, ensure_ascii=force_ascii, date_unit=date_unit, default_handler=default_handler, index=index, indent=indent).write()
    if lines:
        s = convert_to_line_delimits(s)
    if path_or_buf is not None:
        with get_handle(path_or_buf, mode, compression=compression, storage_options=storage_options) as handles:
            handles.handle.write(s)
    else:
        return s
    return None

def __dlpack__(self, *, stream: Optional[Any]=-1, max_version: Optional[tuple[int, int]]=None, dl_device: Optional[tuple[enum.IntEnum, int]]=None, copy: Optional[bool]=None):
    """
        Creates a DLpack `capsule https://data-apis.org/array-api/latest/design_topics/data_interchange.html#data-interchange`_
        of the current tensor to be exported to other libraries.

        This function will be called from the `from_dlpack` method
        of the library that will consume the capsule. `from_dlpack` passes the current
        stream to this method as part of the specification.

        Args:
            stream (integer or None): An optional Python integer representing a
                pointer to a CUDA stream. The current stream is synchronized with
                this stream before the capsule is created, and since the capsule
                shares its storage with the tensor this make it safe to access from
                both streams.  If -1 is passed then no synchronization is performed.
                If 1 (on CUDA) or 0 (on ROCM) then the default stream is used for
                synchronization. This API intentionally slightly deviates from the DLPack
                guidance: the default stream is -1 (stream-preserving; no cross-stream sync),
                because many from_dlpack implementations intend stream preservation.
                For non-CUDA devices, -1 is treated the same as None.

            max_version (tuple[int, int] or None): An optional Python tuple with
                2 integers, representing the maximum version the caller supports. If
                None (default), PyTorch will fallback to DLPack 0.8.

            dl_device (tuple[DLDeviceType, int] or None): An optional tuple specifying
                in which device the exported DLPack capsule should be on. If None (default),
                the exported DLPack capsule will be on the same device as ``self``.

            copy (bool or None): An optional boolean indicating whether or not to copy
                ``self``. If None, PyTorch will copy only if necessary.
        """
    if <MASK>:
        args = (self,)
        kwargs = {'stream': stream, 'max_version': max_version, 'dl_device': dl_device, 'copy': copy}
        return handle_torch_function(Tensor.__dlpack__, (self,), *args, **kwargs)
    if self.requires_grad:
        raise BufferError("Can't export tensors that require gradient, use tensor.detach()")
    if self.is_conj():
        raise BufferError("Can't export tensors with the conjugate bit set")
    if self.layout != torch.strided:
        raise BufferError("Can't export tensors with layout other than torch.strided")
    if self.device.type == 'cuda' and self.device.index != torch.cuda.current_device():
        raise BufferError(f"Can't export tensors on a different CUDA device index. Expected: {self.device.index}. Current device: {torch.cuda.current_device()}.")
    if stream is not None and type(stream) is not int:
        raise TypeError('stream must be ``int`` or ``none``')
    elif self.device.type == 'cuda' and stream != -1:
        is_rocm = torch.version.hip is not None
        is_cuda = not is_rocm
        if stream is None or (is_rocm and stream == 0) or (is_cuda and stream == 1):
            stream = torch.cuda.default_stream()
        else:
            if is_cuda and stream == 2:
                raise BufferError('per-thread default stream is not supported.')
            device_str = 'CUDA' if is_cuda else 'ROCm'
            assert is_cuda and stream != 0 or (is_rocm and stream not in (1, 2)), f'unsupported stream on {device_str}: {stream}.'
            stream = torch.cuda.ExternalStream(stream)
        current_stream = torch.cuda.current_stream()
        if stream != current_stream:
            event = torch.cuda.Event()
            event.record(current_stream)
            stream.wait_event(event)
    elif self.device.type == 'cpu':
        assert stream is None or stream == -1, 'stream should be None on cpu.'
    if self.device.type == 'xla':
        import torch_xla
        import torch_xla.utils.dlpack as xla_dlpack
        if len(torch_xla.real_devices()) <= 0 or 'cuda' not in torch_xla.real_devices()[0].lower():
            raise RuntimeError("Can't export to dlpack an XLA tensor that is not on CUDA.")
        return xla_dlpack.to_dlpack(self)
    if max_version is None or max_version[0] < 1:
        return _C._to_dlpack(self, dl_device=dl_device, copy=copy)
    return _C._to_dlpack_versioned(self, dl_device=dl_device, copy=copy)

