def match(self, expected, actual, assert_items_equal=False):
    """Matches nested structures.

    Recursively matches shape and values of `expected` and `actual`.
    Handles scalars, numpy arrays and other python sequence containers
    e.g. list, dict, as well as SparseTensorValue and RaggedTensorValue.

    Args:
      expected: Nested structure 1.
      actual: Nested structure 2.
      assert_items_equal: Tests the output has the expected elements regardless
        of order.

    Raises:
      AssertionError if matching fails.
    """
    if isinstance(expected, np.ndarray):
        expected = expected.tolist()
    if isinstance(actual, np.ndarray):
        actual = actual.tolist()
    self.assertEqual(type(expected), type(actual))
    if nest.is_nested(expected):
        self.assertEqual(len(expected), len(actual))
        if isinstance(expected, dict):
            for (key1, key2) in zip(sorted(expected), sorted(actual)):
                self.assertEqual(key1, key2)
                self.match(expected[key1], actual[key2])
        elif assert_items_equal:
            for (item1, item2) in zip(sorted(expected), sorted(actual)):
                self.match(item1, item2)
        else:
            for (item1, item2) in zip(expected, actual):
                self.match(item1, item2)
    elif isinstance(expected, sparse_tensor.SparseTensorValue):
        self.match((expected.indices, expected.values, expected.dense_shape), (actual.indices, actual.values, actual.dense_shape))
    elif <MASK>:
        self.match((expected.values, expected.row_splits), (actual.values, actual.row_splits))
    else:
        self.assertEqual(expected, actual)

@trackable.no_automatic_dependency_tracking
def _build_graph_network_for_inferred_shape(self, input_shape, input_dtype=None):
    if input_shape is None or not self.layers:
        return
    if not tf2.enabled() or not ops.executing_eagerly_outside_functions():
        return
    if not self._has_explicit_input_shape and (not self._use_legacy_deferred_behavior):
        input_shape = tuple(input_shape)
        if self._inferred_input_shape is None:
            new_shape = input_shape
        else:
            new_shape = relax_input_shape(self._inferred_input_shape, input_shape)
        if new_shape is not None and new_shape != self._inferred_input_shape:
            with ops.init_scope():
                inputs = input_layer.Input(batch_shape=new_shape, dtype=input_dtype, name=self.layers[0].name + '_input')
                layer_input = inputs
                created_nodes = set()
                for layer in self.layers:
                    clear_previously_created_nodes(layer, self._created_nodes)
                    try:
                        layer_output = layer(layer_input)
                    except:
                        self._use_legacy_deferred_behavior = True
                        return
                    if <MASK>:
                        raise ValueError(SINGLE_LAYER_OUTPUT_ERROR_MSG)
                    track_nodes_created_by_last_call(layer, created_nodes)
                    layer_input = layer_output
                    outputs = layer_output
                self._created_nodes = created_nodes
                try:
                    self._init_graph_network(inputs, outputs)
                    self._graph_initialized = True
                except:
                    self._use_legacy_deferred_behavior = True
            self._inferred_input_shape = new_shape

def build_chunks(self) -> Sequence[Union[message.Message, bytes]]:
    if <MASK>:
        raise TypeError('Can only split TreeString type protos')
    if not self._proto.child_nodes:
        return
    for (i, node) in enumerate(self._proto.child_nodes):
        self.add_chunk(node, [_CHILD_NODES_FIELD_TAG, i])
        DFStringNodeSplitter(proto=node, parent_splitter=self, fields_in_parent=[_CHILD_NODES_FIELD_TAG], chunked_message=self._chunked_message.chunked_fields[i].message).build_chunks()
    self._proto.ClearField('child_nodes')
    if self._parent_splitter is None:
        self._chunks.append(self._chunked_message)
        file_io.write_string_to_file(os.path.join(SPLITTER_TESTDATA_PATH.value, 'df-split-tree.pbtxt'), str(self._chunked_message))
    return self._chunks

def _check_args(x, div, mod, is_first):
    if not isinstance(div, sympy.Integer) or not isinstance(mod, sympy.Integer):
        return False
    if div != 1:
        return False
    if mod <= 0:
        return False
    if is_first:
        if <MASK>:
            return False
    elif not isinstance(x, sympy.Symbol) or not self.statically_known_geq(x, 0):
        return False
    return True

def render_dispatch(pipeline_type, op_name):
    switch_tailnum_template = '
            switch (tail_num) {
                {% for tail_num in valid_tailnums %}
                case ck_tile::TailNumber::{{tail_num}}:
                    dispatch({{has_hot_loop}},
                             ck_tile::integral_constant<ck_tile::TailNumber, ck_tile::TailNumber::{{tail_num}}>{});
                    break;
                {% endfor %}
                default:
                    std::ostringstream err;
                    err << "Unsupported dispatch: "
                        << "Pipeline: " << "{{pipeline}}"
                        << "Prefetch stages: " << kPrefetchStages
                        << "Tail num: " << tail_num;
                    throw std::runtime_error(err.str());
            } // switch tail_num
            '
    dispatch_template = '
        if (has_hot_loop) {
            {{rendered_with_hot_loop}}
        }
        else { // has_hot_loop == false
            {{rendered_without_hot_loop}}
        } // if has_hot_loop
        '
    if pipeline_type == 'CompV3':
        return self._template_from_string(dispatch_template).render(rendered_with_hot_loop=self._template_from_string(switch_tailnum_template).render(has_hot_loop='ck_tile::integral_constant<bool, true>{}', valid_tailnums=('Full', 'Odd', 'Even'), pipeline=pipeline_type), rendered_without_hot_loop=self._template_from_string(switch_tailnum_template).render(has_hot_loop='ck_tile::integral_constant<bool, false>{}', valid_tailnums=('Full', 'Odd', 'Even'), pipeline=pipeline_type))
    elif <MASK>:
        return self._template_from_string(dispatch_template).render(rendered_with_hot_loop='dispatch_memory_pipeline_hot_loop<kPrefetchStages>(tail_num, dispatch);', rendered_without_hot_loop=self._template_from_string(switch_tailnum_template).render(has_hot_loop='ck_tile::integral_constant<bool, false>{}', valid_tailnums=('Full', 'Odd', 'Even'), pipeline=pipeline_type))
    elif pipeline_type == 'CompV4':
        return self._template_from_string(dispatch_template).render(rendered_with_hot_loop=self._template_from_string(switch_tailnum_template).render(has_hot_loop='ck_tile::integral_constant<bool, true>{}', valid_tailnums=('Two', 'Three'), pipeline=pipeline_type), rendered_without_hot_loop=self._template_from_string(switch_tailnum_template).render(has_hot_loop='ck_tile::integral_constant<bool, false>{}', valid_tailnums=('Full', 'Odd', 'Even'), pipeline=pipeline_type))
    else:
        raise AssertionError(f'Pipeline {pipeline_type} is not supported')

