def replace_output(out):
    assert isinstance(spec, OutputSpec)
    if <MASK>:
        arg = spec.user_output.arg
        if arg.type == 'as_tensor':
            t = arg.as_tensor
            t.name = replace_table[t.name]
        elif arg.type == 'as_sym_int':
            s = arg.as_sym_int
            if s.type == 'as_name':
                s.as_name = replace_table[s.as_name]
            elif s.type == 'as_int':
                pass
            else:
                raise AssertionError(f'Unknown sym_int type: {s}')
        elif arg.type == 'as_sym_float':
            f = arg.as_sym_float
            if f.type == 'as_name':
                f.as_name = replace_table[f.as_name]
            elif f.type == 'as_float':
                pass
            else:
                raise AssertionError(f'Unknown sym_float type: {f}')
        elif arg.type in ('as_none', 'as_bool', 'as_int', 'as_float', 'as_string'):
            return
        else:
            raise AssertionError(f'Unknown input type: {arg}')
    elif spec.type == 'loss_output':
        t = spec.loss_output.arg
        t.name = replace_table[t.name]
    elif spec.type == 'buffer_mutation':
        t = spec.buffer_mutation.arg
        t.name = replace_table[t.name]
    elif spec.type == 'parameter_mutation':
        t = spec.parameter_mutation.arg
        t.name = replace_table[t.name]
    elif spec.type == 'gradient_to_parameter':
        t = spec.gradient_to_parameter.arg
        t.name = replace_table[t.name]
    elif spec.type == 'gradient_to_user_input':
        g = spec.gradient_to_user_input
        g.arg.name = replace_table[g.arg.name]
        g.user_input_name = replace_table[g.user_input_name]
    elif spec.type == 'user_input_mutation':
        u = spec.user_input_mutation
        u.arg.name = replace_table[u.arg.name]
        u.user_input_name = replace_table[u.user_input_name]
    elif spec.type == 'token':
        tok = spec.token.arg
        tok.name = replace_table[tok.name]
    else:
        raise AssertionError(f'Unknown output type: {spec}')

def generate_renamed_models(self):
    """
        Find any renamed models, generate the operations for them, and remove
        the old entry from the model lists. Must be run before other
        model-level generation.
        """
    self.renamed_models = {}
    self.renamed_models_rel = {}
    added_models = self.new_model_keys - self.old_model_keys
    for (app_label, model_name) in sorted(added_models):
        model_state = self.to_state.models[app_label, model_name]
        model_fields_def = self.only_relation_agnostic_fields(model_state.fields)
        removed_models = self.old_model_keys - self.new_model_keys
        for (rem_app_label, rem_model_name) in removed_models:
            if rem_app_label == app_label:
                rem_model_state = self.from_state.models[rem_app_label, rem_model_name]
                rem_model_fields_def = self.only_relation_agnostic_fields(rem_model_state.fields)
                if model_fields_def == rem_model_fields_def:
                    if <MASK>:
                        dependencies = []
                        fields = list(model_state.fields.values()) + [field.remote_field for relations in self.to_state.relations[app_label, model_name].values() for field in relations.values()]
                        for field in fields:
                            if field.is_relation:
                                dependencies.extend(self._get_dependencies_for_foreign_key(app_label, model_name, field, self.to_state))
                        self.add_operation(app_label, operations.RenameModel(old_name=rem_model_state.name, new_name=model_state.name), dependencies=dependencies)
                        self.renamed_models[app_label, model_name] = rem_model_name
                        renamed_models_rel_key = '%s.%s' % (rem_model_state.app_label, rem_model_state.name_lower)
                        self.renamed_models_rel[renamed_models_rel_key] = '%s.%s' % (model_state.app_label, model_state.name_lower)
                        self.old_model_keys.remove((rem_app_label, rem_model_name))
                        self.old_model_keys.add((app_label, model_name))
                        break

def _hide_packed_params_repr(self, params):
    extra_lines = []
    extra_repr = self.extra_repr()
    if extra_repr:
        extra_lines = extra_repr.split('\n')
    child_lines = []
    for (key, module) in self._modules.items():
        if <MASK>:
            continue
        mod_str = repr(module)
        mod_str = _addindent(mod_str, 2)
        child_lines.append('(' + key + '): ' + mod_str)
    lines = extra_lines + child_lines
    main_str = self._get_name() + '('
    if lines:
        if len(extra_lines) == 1 and (not child_lines):
            main_str += extra_lines[0]
        else:
            main_str += '\n  ' + '\n  '.join(lines) + '\n'
    main_str += ')'
    return main_str

def create_instruction(name: str, *, arg: Optional[int]=None, argval: Optional[Any]=_NotProvided, target: Optional[Instruction]=None) -> Instruction:
    """
    At most one of `arg`, `argval`, and `target` can be not None/_NotProvided.
    This is to prevent ambiguity, e.g. does
        create_instruction("LOAD_CONST", 5)
    mean load the constant at co_consts[5], or load the constant 5?

    If `arg` is not provided, it will be computed during assembly from
    `argval` or `target`.

    Bits in the args of instructions LOAD_GLOBAL, LOAD_ATTR (3.12+), and LOAD_SUPER_ATTR
    modify the behavior of the instruction. In this case, we allow both `arg`
    and `argval` to be set. The value of `arg` here is expected to be the value of
    the op bits and the true value of `arg` will be computed during assembly.
    If `arg` is not set, the bits are assumed to be 0.
    """
    if <MASK>:
        if target is not None:
            raise RuntimeError('target cannot be specified for instruction')
        if arg is None:
            arg = 0
    else:
        cnt = (arg is not None) + (argval is not _NotProvided) + (target is not None)
        if cnt > 1:
            raise RuntimeError('only one of arg, argval, and target can be not None/_NotProvided')
    if arg is not None and (not isinstance(arg, int)):
        raise RuntimeError('instruction arg must be int or None')
    return Instruction(opcode=dis.opmap[name], opname=name, arg=arg, argval=argval, target=target)

def _make_grads(outputs: Union[Sequence[torch.Tensor], Sequence[graph.GradientEdge]], grads: Sequence[_OptionalTensor], is_grads_batched: bool) -> tuple[_OptionalTensor, ...]:
    new_grads: list[_OptionalTensor] = []
    for (out, grad) in zip(outputs, grads):
        out = cast(Union[torch.Tensor, graph.GradientEdge], out)
        out_size = None
        out_device = None
        if isinstance(out, graph.GradientEdge):
            out_metadata = out.node._input_metadata[out.output_nr]
            out_size = torch.Size(out_metadata.shape)
            out_dtype = out_metadata.dtype
            out_device = out_metadata.device
            out_is_nested = out_metadata.is_nested_tensor
            if out_metadata.is_cpp_nested_tensor:
                raise RuntimeError('C++ NestedTensor are not supported with GradientEdge')
            out_is_cpp_nested = False
        else:
            from torch.nested._internal.nested_tensor import NestedTensor
            if <MASK>:
                raise AssertionError('Expected output to be a torch.Tensor')
            out_dtype = out.dtype
            out_is_nested = out.is_nested
            out_is_cpp_nested = out_is_nested and (not isinstance(out, NestedTensor))
            if not out_is_cpp_nested:
                out_size = out.shape
        if isinstance(grad, torch.Tensor):
            from torch.fx.experimental.symbolic_shapes import expect_true, sym_eq
            first_grad = grad if not is_grads_batched else grad[0]
            if out_is_cpp_nested:
                if not isinstance(out, torch.Tensor):
                    raise AssertionError('Expected output to be a torch.Tensor.')
                shape_matches = torch.is_same_size(out, first_grad)
            else:
                if out_size is None:
                    raise AssertionError('Expected out_size to be set.')
                shape_matches = expect_true(sym_eq(out_size, first_grad.size()))
            if not shape_matches:
                out = cast(Union[torch.Tensor, graph.GradientEdge], out)
                (out_shape, grad_shape) = _calculate_shape(out, first_grad, is_grads_batched)
                if is_grads_batched:
                    raise RuntimeError('If `is_grads_batched=True`, we interpret the first dimension of each grad_output as the batch dimension. The sizes of the remaining dimensions are expected to match the shape of corresponding output, but a mismatch was detected: grad_output[' + str(grads.index(grad)) + '] has a shape of ' + str(grad_shape) + ' and output[' + str(outputs.index(out)) + '] has a shape of ' + str(out_shape) + '. If you only want some tensors in `grad_output` to be considered batched, consider using vmap.')
                else:
                    raise RuntimeError('Mismatch in shape: grad_output[' + str(grads.index(grad)) + '] has a shape of ' + str(grad_shape) + ' and output[' + str(outputs.index(out)) + '] has a shape of ' + str(out_shape) + '.')
            if out_dtype.is_complex != grad.dtype.is_complex:
                raise RuntimeError('For complex Tensors, both grad_output and output are required to have the same dtype. Mismatch in dtype: grad_output[' + str(grads.index(grad)) + '] has a dtype of ' + str(grad.dtype) + ' and output[' + str(outputs.index(out)) + '] has a dtype of ' + str(out_dtype) + '.')
            new_grads.append(grad)
        elif grad is None:
            if isinstance(out, graph.GradientEdge) or out.requires_grad:
                if isinstance(out, graph.GradientEdge):
                    if out_size is None:
                        raise AssertionError('Expected out_size to be set.')
                    out_numel_is_1 = all((o == 1 for o in out_size))
                else:
                    if not isinstance(out, torch.Tensor):
                        raise AssertionError('Expected output to be a torch.Tensor')
                    out_numel_is_1 = out.numel() == 1
                if not out_numel_is_1:
                    raise RuntimeError('grad can be implicitly created only for scalar outputs')
                if not out_dtype.is_floating_point:
                    msg = f'grad can be implicitly created only for real scalar outputs but got {out_dtype}'
                    raise RuntimeError(msg)
                if isinstance(out, graph.GradientEdge):
                    if out_size is None:
                        raise AssertionError('Expected out_size to be set.')
                    if out_device is None:
                        raise AssertionError('Expected out_device to be set.')
                    new_grads.append(torch.ones(out_size, dtype=out_dtype, device=out_device))
                else:
                    if not isinstance(out, torch.Tensor):
                        raise AssertionError('Expected output to be a torch.Tensor')
                    new_grads.append(torch.ones_like(out, memory_format=torch.preserve_format))
            else:
                new_grads.append(None)
        else:
            raise TypeError('gradients can be either Tensors or None, but got ' + type(grad).__name__)
    return tuple(new_grads)

def _fast_gradcheck(func, func_out, inputs, outputs, eps, rtol, atol, check_grad_dtypes, nondet_tol, *, use_forward_ad=False, complex_indices=None, test_imag=False, masked=False):
    (inp_tensors_idx, inp_tensors) = _get_inp_tensors(inputs)
    (all_v, all_u, all_u_dense) = _make_vectors(inp_tensors, outputs, use_forward_ad=use_forward_ad)
    (inputs_numerical, all_u_numerical, all_v_numerical) = (inputs, all_u, all_v) if masked else _densify((inputs, all_u, all_v))
    numerical_vJu = _get_numerical_vJu(func, inputs_numerical, inp_tensors_idx, func_out, all_u_numerical, all_v_numerical, eps, is_forward_ad=use_forward_ad)
    if use_forward_ad:
        if all_v is not None:
            raise AssertionError('Expected all_v to be None.')
        analytical_vJu = _get_analytical_jacobian_forward_ad(func, inputs, _as_tuple(func_out), all_u=all_u, check_grad_dtypes=check_grad_dtypes)
    else:
        if <MASK>:
            _check_no_differentiable_outputs_fast(func, func_out, inputs, inp_tensors_idx, all_u, eps, nondet_tol)
        analytical_vJu = _get_analytical_vJu_backward_mode(inputs, outputs, nondet_tol, check_grad_dtypes, all_v, all_u_dense)
    _check_analytical_numerical_equal(analytical_vJu, numerical_vJu, complex_indices, inputs, outputs, func, all_v, all_u, rtol, atol, eps, test_imag, is_forward_ad=use_forward_ad)
    return True

def iter_format_modules(lang, format_module_path=None):
    """Find format modules."""
    if <MASK>:
        return
    if format_module_path is None:
        format_module_path = settings.FORMAT_MODULE_PATH
    format_locations = []
    if format_module_path:
        if isinstance(format_module_path, str):
            format_module_path = [format_module_path]
        for path in format_module_path:
            format_locations.append(path + '.%s')
    format_locations.append('django.conf.locale.%s')
    locale = to_locale(lang)
    locales = [locale]
    if '_' in locale:
        locales.append(locale.split('_')[0])
    for location in format_locations:
        for loc in locales:
            try:
                yield import_module('%s.formats' % (location % loc))
            except ImportError:
                pass

def _init_group(self, group: MutableMapping, params_with_grad: list[Tensor], grads: list[Tensor], muon_momentum_bufs: list[Tensor]):
    for p in group['params']:
        if p.grad is None:
            continue
        if torch.is_complex(p):
            raise RuntimeError('Muon does not support complex parameters')
        if p.grad.is_sparse:
            raise RuntimeError('Muon does not support sparse gradients')
        params_with_grad.append(p)
        grads.append(p.grad)
        state = self.state[p]
        if <MASK>:
            state['momentum_buffer'] = torch.zeros_like(p.grad, memory_format=torch.preserve_format)
        muon_momentum_bufs.append(state['momentum_buffer'])
    return False

def fuse_all_gather_matmul(all_gather: _AllGatherMatch) -> None:
    """
    Fused the pattern

        A = all_gather_tensor(A_shard, gather_dim, group_name)
        C_0 = torch.matmul(A, B_0)
        C_1 = torch.matmul(A, B_1)
        C_2 = torch.matmul(A, B_2)
        ...

    into

        A, Cs = torch.ops.symm_mem.fused_all_gather_matmul(
            A_shard, [B_0, B_1, B_2, ...], gather_dim, group_name,
        )
    """
    if not torch.distributed.is_available() or not torch.distributed.is_nccl_available():
        return
    from torch.distributed._symmetric_memory import is_symm_mem_enabled_for_group, restride_A_shard_for_fused_all_gather_matmul
    (shard_node, ag_node, ag_res_node, gather_dim, group_name) = (all_gather.shard_node, all_gather.ag_node, all_gather.res_node, all_gather.gather_dim, all_gather.group_name)
    if not is_symm_mem_enabled_for_group(group_name):
        return
    filter_matmul = None
    if _is_last_dim(_get_tensor(shard_node), gather_dim):
        if _get_tensor(shard_node).shape[-1] < 1024:
            return

        def _filter_out_scaled_matmul(matmul: _Matmul):
            return not isinstance(matmul, _ScaledMatmul)
        filter_matmul = _filter_out_scaled_matmul
    matmuls = _find_consumer_matmuls(ag_res_node)
    matmuls = [matmul for matmul in matmuls if all_gather.res_node not in matmul.arg_ancestor_nodes]
    if len(matmuls) == 0 or len(OrderedSet(map(type, matmuls))) != 1:
        return
    if <MASK>:
        return
    if filter_matmul and (not filter_matmul(matmuls[0])):
        return
    graph = ag_node.graph
    with graph.inserting_before(ag_node):
        if not _is_last_dim(_get_tensor(shard_node), gather_dim):
            if 'val' in shard_node.meta:
                restrided = restride_A_shard_for_fused_all_gather_matmul(_get_tensor(shard_node), gather_dim)
                shard_node = graph.call_function(inductor_prims.force_stride_order, args=(shard_node, restrided.stride()))
        fused_node = _insert_fused_all_gather_matmul(graph, matmuls, shard_node, gather_dim, group_name)
        new_ag_node = graph.call_function(operator.getitem, args=(fused_node, 0))
        new_out_nodes = graph.call_function(operator.getitem, args=(fused_node, 1))
        for (idx, matmul) in enumerate(matmuls):
            new_out_node = graph.call_function(operator.getitem, args=(new_out_nodes, idx))
            matmul.replace_with(new_out_node)
            matmul.erase()
        all_gather.replace_with(new_ag_node)
        all_gather.erase()
        if len(new_ag_node.users) == 0:
            graph.erase_node(new_ag_node)
            kwargs = dict(fused_node.kwargs)
            if 'return_A' in kwargs:
                kwargs['return_A'] = False
                fused_node.kwargs = kwargs
    order = {node: idx for (idx, node) in enumerate(graph.nodes)}
    nodes_to_raise = sorted(OrderedSet((x for matmul in matmuls for x in matmul.arg_ancestor_nodes)), key=lambda x: order[x])
    for node in nodes_to_raise:
        if order[node] > order[fused_node]:
            fused_node.prepend(node)

def _check_fields(self, obj):
    """Check that `fields` only refer to existing fields, doesn't contain
        duplicates. Check if at most one of `fields` and `fieldsets` is
        defined.
        """
    if obj.fields is None:
        return []
    elif not isinstance(obj.fields, (list, tuple)):
        return must_be('a list or tuple', option='fields', obj=obj, id='admin.E004')
    elif obj.fieldsets:
        return [checks.Error("Both 'fieldsets' and 'fields' are specified.", obj=obj.__class__, id='admin.E005')]
    field_counts = collections.Counter(flatten(obj.fields))
    if <MASK>:
        return [checks.Error("The value of 'fields' contains duplicate field(s).", hint='Remove duplicates of %s.' % ', '.join(map(repr, duplicate_fields)), obj=obj.__class__, id='admin.E006')]
    return list(chain.from_iterable((self._check_field_spec(obj, field_name, 'fields') for field_name in obj.fields)))

