@ops.RegisterGradient('SparseMatrixMatMul')
def _SparseMatrixMatMulGrad(op: ops.Operation, grad):
    """Gradient for sparse_matrix_mat_mul op."""
    t_a = op.get_attr('transpose_a')
    t_b = op.get_attr('transpose_b')
    adj_a = op.get_attr('adjoint_a')
    adj_b = op.get_attr('adjoint_b')
    transpose_output = op.get_attr('transpose_output')
    conjugate_output = op.get_attr('conjugate_output')
    a = op.inputs[0]
    b = op.inputs[1]
    conj = math_ops.conj
    sparse_matmul = sparse_csr_matrix_ops.sparse_matrix_mat_mul

    def matmul(x, y, **kwargs):
        return _PrunedDenseMatrixMultiplication(x, y, indices=sparse_csr_matrix_ops.csr_sparse_matrix_to_sparse_tensor(a, type=x.dtype).indices, **kwargs)
    if conjugate_output:
        grad = conj(grad)
    if not transpose_output:
        if not adj_a and (not adj_b):
            a = conj(a)
            b = conj(b)
            if not t_a:
                grad_a = matmul(grad, b, transpose_b=not t_b)
            else:
                grad_a = matmul(b, grad, transpose_a=t_b, transpose_b=True)
            grad_b = sparse_matmul(a, grad, transpose_a=not t_a, transpose_output=t_b)
        elif not t_a and (not t_b):
            if not adj_a:
                grad_a = matmul(grad, b, adjoint_b=not adj_b)
            else:
                grad_a = matmul(b, grad, adjoint_a=adj_b, adjoint_b=True)
            grad_b = sparse_matmul(a, grad, adjoint_a=not adj_a, transpose_output=adj_b, conjugate_output=adj_b)
        elif adj_a and t_b:
            grad_a = matmul(b, grad, transpose_a=True, adjoint_b=True)
            grad_b = sparse_matmul(a, grad, transpose_output=True)
        elif <MASK>:
            grad_a = matmul(b, grad, transpose_a=True, transpose_b=True)
            grad_b = sparse_matmul(conj(a), grad, transpose_output=True, conjugate_output=True)
    elif not adj_a and (not adj_b):
        a = conj(a)
        b = conj(b)
        if not t_a:
            grad_a = matmul(grad, b, transpose_a=True, transpose_b=not t_b)
        else:
            grad_a = matmul(b, grad, transpose_a=t_b)
        grad_b = sparse_matmul(a, grad, transpose_a=not t_a, transpose_b=True, transpose_output=t_b)
    elif not t_a and (not t_b):
        if not adj_a:
            grad_a = matmul(grad, b, transpose_a=True, adjoint_b=not adj_b)
        else:
            grad_a = matmul(b, conj(grad), adjoint_a=adj_b)
        grad_b = sparse_matmul(a, grad, adjoint_a=not adj_a, transpose_b=True, transpose_output=adj_b, conjugate_output=adj_b)
    elif adj_a and t_b:
        grad_a = matmul(b, conj(grad), transpose_a=True)
        grad_b = sparse_matmul(a, grad, transpose_b=True, transpose_output=True)
    elif t_a and adj_b:
        grad_a = matmul(b, grad, transpose_a=True)
        grad_b = sparse_matmul(a, grad, adjoint_b=True, transpose_output=True)
    return (grad_a, grad_b)

def validate_rst_syntax(text, name, dots=True):
    """
    Validates the doc string in a snippet of documentation
    `text` from file `name`
    Parameters
    ----------
    text : str
        Docstring text
    name : str
        File name for which the doc string is to be validated
    dots : bool
        Whether to print a dot symbol for each check
    Returns
    -------
    (bool, str)
    """
    if <MASK>:
        if dots:
            output_dot('E')
        return (False, f'ERROR: {name}: no documentation')
    ok_unknown_items = {'mod', 'doc', 'currentmodule', 'autosummary', 'data', 'attr', 'obj', 'versionadded', 'versionchanged', 'module', 'class', 'ref', 'func', 'toctree', 'moduleauthor', 'term', 'c:member', 'sectionauthor', 'codeauthor', 'eq', 'doi', 'DOI', 'arXiv', 'arxiv'}
    error_stream = io.StringIO()

    def resolve(name, is_label=False):
        return ('http://foo', name)
    token = '<RST-VALIDATE-SYNTAX-CHECK>'
    docutils.core.publish_doctree(text, token, settings_overrides={'halt_level': 5, 'traceback': True, 'default_reference_context': 'title-reference', 'default_role': 'emphasis', 'link_base': '', 'resolve_name': resolve, 'stylesheet_path': '', 'raw_enabled': 0, 'file_insertion_enabled': 0, 'warning_stream': error_stream})
    error_msg = error_stream.getvalue()
    errors = error_msg.split(token)
    success = True
    output = ''
    for error in errors:
        lines = error.splitlines()
        if not lines:
            continue
        m = re.match('.*Unknown (?:interpreted text role|directive type) "(.*)".*$', lines[0])
        if m:
            if m.group(1) in ok_unknown_items:
                continue
        m = re.match('.*Error in "math" directive:.*unknown option: "label"', ' '.join(lines), re.S)
        if m:
            continue
        output += name + lines[0] + '::\n    ' + '\n    '.join(lines[1:]).rstrip() + '\n'
        success = False
    if not success:
        output += '    ' + '-' * 72 + '\n'
        for (lineno, line) in enumerate(text.splitlines()):
            output += '    %-4d    %s\n' % (lineno + 1, line)
        output += '    ' + '-' * 72 + '\n\n'
    if dots:
        output_dot('.' if success else 'F')
    return (success, output)

def _filter_returned_ops(fn):
    """Filtering out any ops returned by function.

  Args:
    fn: a function

  Returns:
    A tuple of (
      Wrapped function that returns `None` in place of any ops,
      dict that maps the index in the flat output structure to the returned op
    )
  """
    returned_ops = {}

    def wrap_and_filter_returned_ops(*args, **kwargs):
        outputs = fn(*args, **kwargs)
        flat_outputs = nest.flatten(outputs)
        for n in range(len(flat_outputs)):
            output = flat_outputs[n]
            if <MASK>:
                returned_ops[n] = output
                flat_outputs[n] = None
        return nest.pack_sequence_as(outputs, flat_outputs)
    return (wrap_and_filter_returned_ops, returned_ops)

def refresh_model_names():
    import glob
    from timm.models import list_models

    def read_models_from_docs():
        models = set()
        for fn in glob.glob('../pytorch-image-models/docs/models/*.md'):
            with open(fn) as f:
                while True:
                    line = f.readline()
                    if <MASK>:
                        break
                    if not line.startswith('model = timm.create_model('):
                        continue
                    model = line.split("'")[1]
                    models.add(model)
        return models

    def get_family_name(name):
        known_families = ['darknet', 'densenet', 'dla', 'dpn', 'ecaresnet', 'halo', 'regnet', 'efficientnet', 'deit', 'mobilevit', 'mnasnet', 'convnext', 'resnet', 'resnest', 'resnext', 'selecsls', 'vgg', 'xception']
        for known_family in known_families:
            if known_family in name:
                return known_family
        if name.startswith('gluon_'):
            return 'gluon_' + name.split('_')[1]
        return name.split('_')[0]

    def populate_family(models):
        family = {}
        for model_name in models:
            family_name = get_family_name(model_name)
            if family_name not in family:
                family[family_name] = []
            family[family_name].append(model_name)
        return family
    docs_models = read_models_from_docs()
    all_models = list_models(pretrained=True, exclude_filters=['*in21k'])
    all_models_family = populate_family(all_models)
    docs_models_family = populate_family(docs_models)
    for key in docs_models_family:
        del all_models_family[key]
    chosen_models = set()
    chosen_models.update((value[0] for value in docs_models_family.values()))
    chosen_models.update((value[0] for (key, value) in all_models_family.items()))
    filename = 'timm_models_list.txt'
    if os.path.exists('benchmarks'):
        filename = 'benchmarks/' + filename
    with open(filename, 'w') as fw:
        for model_name in sorted(chosen_models):
            fw.write(model_name + '\n')

def _get_join_indexers(self) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    """return the join indexers"""
    left_values = self.left.index._values if self.left_index else self.left_join_keys[-1]
    right_values = self.right.index._values if self.right_index else self.right_join_keys[-1]
    assert left_values.dtype == right_values.dtype
    tolerance = self.tolerance
    if tolerance is not None:
        if needs_i8_conversion(left_values.dtype) or (isinstance(left_values, ArrowExtensionArray) and left_values.dtype.kind in 'mM'):
            tolerance = Timedelta(tolerance)
            if left_values.dtype.kind in 'mM':
                if isinstance(left_values, ArrowExtensionArray):
                    unit = left_values.dtype.pyarrow_dtype.unit
                else:
                    unit = ensure_wrapped_if_datetimelike(left_values).unit
                tolerance = tolerance.as_unit(unit)
            tolerance = tolerance._value
    left_values = self._convert_values_for_libjoin(left_values, 'left')
    right_values = self._convert_values_for_libjoin(right_values, 'right')
    if <MASK>:
        if self.left_index and self.right_index:
            left_join_keys = self.left_join_keys
            right_join_keys = self.right_join_keys
        else:
            left_join_keys = self.left_join_keys[0:-1]
            right_join_keys = self.right_join_keys[0:-1]
        mapped = [_factorize_keys(left_join_keys[n], right_join_keys[n], sort=False) for n in range(len(left_join_keys))]
        if len(left_join_keys) == 1:
            left_by_values = mapped[0][0]
            right_by_values = mapped[0][1]
        else:
            arrs = [np.concatenate(m[:2]) for m in mapped]
            shape = tuple((m[2] for m in mapped))
            group_index = get_group_index(arrs, shape=shape, sort=False, xnull=False)
            left_len = len(left_join_keys[0])
            left_by_values = group_index[:left_len]
            right_by_values = group_index[left_len:]
        left_by_values = ensure_int64(left_by_values)
        right_by_values = ensure_int64(right_by_values)
        func = _asof_by_function(self.direction)
        return func(left_values, right_values, left_by_values, right_by_values, self.allow_exact_matches, tolerance)
    else:
        func = _asof_by_function(self.direction)
        return func(left_values, right_values, None, None, self.allow_exact_matches, tolerance, False)

def emit(self, operation):
    """Given a gem operation, emits a template definition of the operation"""
    opcode_class_main = operation.tile_description.math_instruction.opcode_class
    opcode_class_epi = opcode_class_main
    tile_shape = operation.tile_description.tile_shape
    instruction_shape = operation.tile_description.math_instruction.instruction_shape
    cluster_m = operation.tile_description.cluster_shape[0]
    cluster_n = operation.tile_description.cluster_shape[1]
    (tile_shape_m, tile_shape_n, tile_shape_k) = tile_shape
    cta_m = tile_shape[0] // cluster_m if cluster_m > 0 else tile_shape[0]
    cta_n = tile_shape[1] // cluster_n if cluster_n > 0 else tile_shape[1]
    is_sm100_kernel = operation.arch == 100
