        B_dtype_bits = DataTypeSize[B_dtype]
        is_A_dtype_narrow = A_dtype_bits < B_dtype_bits
        if is_A_dtype_narrow:
            (narrow_dtype, wide_dtype) = (A_dtype, B_dtype)
            (narrow_dtype_bits, wide_dtype_bits) = (A_dtype_bits, B_dtype_bits)
        else:
            (narrow_dtype, wide_dtype) = (B_dtype, A_dtype)
            (narrow_dtype_bits, wide_dtype_bits) = (B_dtype_bits, A_dtype_bits)
        narrow_tag = DataTypeTag[narrow_dtype]
        wide_tag = DataTypeTag[wide_dtype]
        scale_tag = DataTypeTag[wide_dtype]
        zero_tag = DataTypeTag[wide_dtype]
        do_shuffle = False
        value_shuffle_str = ''
        if narrow_dtype_bits == 4 and wide_dtype_bits == 16:
            value_shuffle_str = 'cute::Layout<cute::Shape<cute::_2,cute::_4>, cute::Stride<cute::_4,cute::_1>>'
            do_shuffle = True
        if narrow_dtype_bits == 8 and wide_dtype_bits == 16:
            value_shuffle_str = 'cute::Layout<cute::Shape<cute::_2,cute::_2>, cute::Stride<cute::_2,cute::_1>>'
            do_shuffle = True
        do_shuffle = operation.mixed_input_shuffle and do_shuffle
        if do_shuffle:
            if is_A_dtype_narrow:
                stride_narrow_str = f'cutlass::detail::TagToStrideA_t<{layout_a_str}>'
                layout_a_str = f'{operation_name_str}_LayoutNarrowReordered'
            else:
                stride_narrow_str = f'cutlass::detail::TagToStrideB_t<{layout_b_str}>'
                layout_b_str = f'{operation_name_str}_LayoutNarrowReordered'
            mixed_dtype_prepare_code = f'\n            using {operation_name_str}_StrideNarrow = {stride_narrow_str};\n            using {operation_name_str}_ValueShuffle = {value_shuffle_str};\n            static constexpr int {operation_name_str}_NumShuffleAtoms = 1;\n            using {operation_name_str}_MmaAtomShape = cute::Layout<cute::Shape<cute::_1, cute::Int<{operation_name_str}_NumShuffleAtoms>>>;\n            using {operation_name_str}_LayoutAtomQuant = decltype(cutlass::compute_memory_reordering_atom<{wide_tag}, {operation_name_str}_MmaAtomShape, {operation_name_str}_ValueShuffle>());\n            using {operation_name_str}_LayoutNarrowReordered = decltype(cute::tile_to_shape({operation_name_str}_LayoutAtomQuant{{}}, cute::Layout<cute::Shape<int,int,int>, {operation_name_str}_StrideNarrow>{{}}));\n                    '
        mixed_input_modes_to_element = {MixedInputMode.ConvertOnly: narrow_tag, MixedInputMode.ScaleOnly: f'cute::tuple<{narrow_tag}, {scale_tag}>', MixedInputMode.ScaleWithZeroPoint: f'cute::tuple<{narrow_tag}, {scale_tag}, {zero_tag}>'}
        narrow_element = mixed_input_modes_to_element.get(operation.mixed_input_mode, narrow_tag)
        if narrow_dtype == DataType.s4 and (wide_dtype == DataType.e4m3 or wide_dtype == DataType.e5m2):
            narrow_element = f'cute::tuple<{narrow_tag}, cutlass::Array<{scale_tag}, 8>>'
        if is_A_dtype_narrow:
            element_a = narrow_element
        else:
            element_b = narrow_element
    if self.evt_name:
        epilogue_functor = self.evt_name
    values = {'operation_name': operation_name_str, 'operation_suffix': self.operation_suffix, 'problem_shape': self.problem_shape(operation), 'element_a': element_a, 'layout_a': self.pointerize_if_grouped(operation, layout_a_str), 'element_b': element_b, 'layout_b': self.pointerize_if_grouped(operation, layout_b_str), 'element_c': DataTypeTag[operation.C.element], 'layout_c': self.pointerize_if_grouped(operation, LayoutTag[instance_layout_C]), 'element_d': DataTypeTag[operation.D.element], 'layout_d': self.pointerize_if_grouped(operation, LayoutTag[instance_layout_D]), 'element_accumulator': DataTypeTag[operation.accumulator_type()], 'opcode_class_main': OpcodeClassTag[opcode_class_main], 'opcode_class_epi': OpcodeClassTag[opcode_class_epi], 'arch': f'cutlass::arch::Sm{operation.arch}', 'tile_shape_m': str(tile_shape_m), 'tile_shape_n': str(tile_shape_n), 'tile_shape_k': str(tile_shape_k), 'cluster_shape_m': 'cute::_' + str(operation.tile_description.cluster_shape[0]) if operation.tile_description.cluster_shape[0] > 0 else 'int', 'cluster_shape_n': 'cute::_' + str(operation.tile_description.cluster_shape[1]) if operation.tile_description.cluster_shape[1] > 0 else 'int', 'cluster_shape_k': 'cute::_' + str(operation.tile_description.cluster_shape[2]) if operation.tile_description.cluster_shape[2] > 0 else 'int', 'instruction_shape_m': str(instruction_shape[0]), 'instruction_shape_n': str(instruction_shape[1]), 'instruction_shape_k': str(instruction_shape[2]), 'kernel_schedule': str(KernelScheduleTag[operation.kernel_schedule]), 'epilogue_schedule': str(epilogue_schedule_type), 'epi_tile_mn': epi_tile_mn, 'epilogue_functor': epilogue_functor, 'stages': stage_count_string, 'align_a': str(operation.A.alignment), 'align_b': str(operation.B.alignment), 'align_c': str(operation.C.alignment), 'align_d': str(operation.D.alignment), 'transform_a': ComplexTransformTag[operation.A.complex_transform], 'transform_b': ComplexTransformTag[operation.B.complex_transform], 'math_operation': MathOperationTag[operation.tile_description.math_instruction.math_operation], 'epilogue_vector_length': str(epilogue_vector_length), 'element_epilogue': str(DataTypeTag[operation.element_epilogue]), 'tile_scheduler': str(TileSchedulerTag[operation.tile_scheduler]), 'mixed_dtype_prepare_code': mixed_dtype_prepare_code}
    return SubstituteTemplate(self.gemm_template, values)

def determine_clipboard():
    """
    Determine the OS/platform and set the copy() and paste() functions
    accordingly.
    """
    global Foundation, AppKit, qtpy, PyQt4, PyQt5
    if 'cygwin' in platform.system().lower():
        if os.path.exists('/dev/clipboard'):
            warnings.warn("Pyperclip's support for Cygwin is not perfect, see https://github.com/asweigart/pyperclip/issues/55", stacklevel=find_stack_level())
            return init_dev_clipboard_clipboard()
    elif os.name == 'nt' or platform.system() == 'Windows':
        return init_windows_clipboard()
    if platform.system() == 'Linux':
        if <MASK>:
            return init_wsl_clipboard()
    if os.name == 'mac' or platform.system() == 'Darwin':
        try:
            import AppKit
            import Foundation
        except ImportError:
            return init_osx_pbcopy_clipboard()
        else:
            return init_osx_pyobjc_clipboard()
    if HAS_DISPLAY:
        if os.environ.get('WAYLAND_DISPLAY') and _executable_exists('wl-copy'):
            return init_wl_clipboard()
        if _executable_exists('xsel'):
            return init_xsel_clipboard()
        if _executable_exists('xclip'):
            return init_xclip_clipboard()
        if _executable_exists('klipper') and _executable_exists('qdbus'):
            return init_klipper_clipboard()
        try:
            import qtpy
        except ImportError:
            try:
                import PyQt5
            except ImportError:
                try:
                    import PyQt4
                except ImportError:
                    pass
                else:
                    return init_qt_clipboard()
            else:
                return init_qt_clipboard()
        else:
            return init_qt_clipboard()
    return init_no_clipboard()

@test_util.run_in_graph_and_eager_modes
def testSparseTensorFuncGraph(self):
    instrument = _NumpyFunctionCallback()
    op_callbacks.add_op_callback(instrument.callback)

    @def_function.function
    def dense_matmul(sp, w):
        return sparse_ops.sparse_tensor_dense_matmul(sp, w)
    indices = [[1, 2], [2, 0], [3, 4]]
    values = [0.0, 8.0, -2.0]
    shape = [4, 5]
    sp = sparse_tensor.SparseTensorValue(indices, values, shape)
    w = ops.convert_to_tensor(np.ones([5, 1], np.float32))
    y = dense_matmul(sp, w)
    self.assertAllClose(y, [[0.0], [0.0], [8.0], [-2.0]])
    self.assertIn(_SPARSE_TENSOR_DENSE_MATMUL_OP, instrument.graph_op_types)
    if <MASK>:
        self.assertIn(dense_matmul.get_concrete_function(sp, w).name, instrument.eager_op_types)
    sparse_matmul_outputs = instrument.graph_internal_ndarrays[_SPARSE_TENSOR_DENSE_MATMUL_OP + b'/' + _SPARSE_TENSOR_DENSE_MATMUL_OP]
    if context.executing_eagerly():
        self.assertEqual(len(sparse_matmul_outputs), 1)
    self.assertAllClose(sparse_matmul_outputs[0], [[0.0], [0.0], [8.0], [-2.0]])

def find_args_with_derivatives(differentiable_inputs: list[DifferentiableInput]) -> list[DifferentiableInput]:
    """Find arguments that have derivative definitions"""
    if info is None or not info.has_derivatives:
        return differentiable_inputs
    names = {name for d in info.derivatives for name in d.var_names}
    differentiable = [arg for arg in differentiable_inputs if arg.name in names]
    if <MASK>:
        missing = names - {arg.name for arg in differentiable}
        raise RuntimeError(f'Missing arguments for derivatives: {missing} in {info.name}')
    return differentiable

def msvc_runtime_library():
    """Return name of MSVC runtime library if Python was built with MSVC >= 7"""
    ver = msvc_runtime_major()
    if ver:
        if <MASK>:
            return 'msvcr%i' % ver
        else:
            return 'vcruntime%i' % ver
    else:
        return None

def are_strides_like_channels_last_or_false(shape: Sequence[int], strides: Sequence[int]) -> bool:
    from torch.fx.experimental.symbolic_shapes import guard_or_true, statically_known_true
    ndim = len(shape)
    if ndim == 4:
        dim_order = [1, 3, 2, 0]
    elif ndim == 5:
        dim_order = [1, 4, 3, 2, 0]
    else:
        return False
    if guard_or_true(strides[1] == 0):
        return False
    min = 0
    for d in dim_order:
        if guard_or_true(shape[d] == 0):
            return False
        if guard_or_true(strides[d] < min):
            return False
        if <MASK>:
            return False
        min = strides[d]
        if guard_or_true(strides[d] > 1):
            min *= shape[d]
    return True

def gen_registration_headers(backend_index: BackendIndex, per_operator_headers: bool, rocm: bool) -> list[str]:
    if per_operator_headers:
        headers = ['#include <ATen/ops/as_strided_native.h>']
    else:
        headers = ['#include <ATen/NativeFunctions.h>']
    if backend_index.dispatch_key in (DispatchKey.CPU, DispatchKey.Meta):
        headers.append('#include <ATen/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.CUDA:
        if rocm:
            headers.append('#include <ATen/hip/EmptyTensor.h>')
        else:
            headers.append('#include <ATen/cuda/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.MPS:
        headers.append('#include <ATen/mps/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.XPU:
        headers.append('#include <ATen/xpu/EmptyTensor.h>')
    elif <MASK>:
        headers.append('#include <ATen/native/mtia/EmptyTensor.h>')
    elif per_operator_headers:
        headers += ['#include <ATen/ops/empty.h>', '#include <ATen/ops/empty_strided.h>', '#include <ATen/ops/_copy_from_and_resize.h>', '#include <ATen/ops/_copy_from.h>']
    else:
        headers.append('#include <ATen/Functions.h>')
    headers.append('#include <c10/macros/Macros.h>')
    return headers

def prune(self, klass):

    def pr(left, right):
        """create and return a new specialized BinOp from myself"""
        if left is None:
            return right
        elif <MASK>:
            return left
        k = klass
        if isinstance(left, ConditionBinOp):
            if isinstance(right, ConditionBinOp):
                k = JointConditionBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right
        elif isinstance(left, FilterBinOp):
            if isinstance(right, FilterBinOp):
                k = JointFilterBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right
        return k(self.op, left, right, queryables=self.queryables, encoding=self.encoding).evaluate()
    (left, right) = (self.lhs, self.rhs)
    if is_term(left) and is_term(right):
        res = pr(left.value, right.value)
    elif not is_term(left) and is_term(right):
        res = pr(left.prune(klass), right.value)
    elif is_term(left) and (not is_term(right)):
        res = pr(left.value, right.prune(klass))
    elif not (is_term(left) or is_term(right)):
        res = pr(left.prune(klass), right.prune(klass))
    return res

def replace_output(out):
    assert isinstance(spec, OutputSpec)
    if spec.type == 'user_output':
        arg = spec.user_output.arg
        if arg.type == 'as_tensor':
            t = arg.as_tensor
            t.name = replace_table[t.name]
        elif arg.type == 'as_sym_int':
            s = arg.as_sym_int
            if s.type == 'as_name':
                s.as_name = replace_table[s.as_name]
            elif s.type == 'as_int':
                pass
            else:
                raise AssertionError(f'Unknown sym_int type: {s}')
        elif arg.type == 'as_sym_float':
            f = arg.as_sym_float
            if f.type == 'as_name':
                f.as_name = replace_table[f.as_name]
            elif f.type == 'as_float':
                pass
            else:
                raise AssertionError(f'Unknown sym_float type: {f}')
        elif arg.type in ('as_none', 'as_bool', 'as_int', 'as_float', 'as_string'):
            return
        else:
            raise AssertionError(f'Unknown input type: {arg}')
    elif spec.type == 'loss_output':
        t = spec.loss_output.arg
        t.name = replace_table[t.name]
    elif <MASK>:
        t = spec.buffer_mutation.arg
        t.name = replace_table[t.name]
    elif spec.type == 'parameter_mutation':
        t = spec.parameter_mutation.arg
        t.name = replace_table[t.name]
    elif spec.type == 'gradient_to_parameter':
        t = spec.gradient_to_parameter.arg
        t.name = replace_table[t.name]
    elif spec.type == 'gradient_to_user_input':
        g = spec.gradient_to_user_input
        g.arg.name = replace_table[g.arg.name]
        g.user_input_name = replace_table[g.user_input_name]
    elif spec.type == 'user_input_mutation':
        u = spec.user_input_mutation
        u.arg.name = replace_table[u.arg.name]
        u.user_input_name = replace_table[u.user_input_name]
    elif spec.type == 'token':
        tok = spec.token.arg
        tok.name = replace_table[tok.name]
    else:
        raise AssertionError(f'Unknown output type: {spec}')

@classmethod
def require_stride1(cls, x: IRNode) -> IRNode:
    if is_storage_and_layout(x):
        if len(x.get_stride()) == 0:
            return x
        for stride in x.get_stride():
            if <MASK>:
                return x
    return cls.copy_input(x)

@_onnx_symbolic('aten::to')
def to(g: jit_utils.GraphContext, self, *args):

    def is_aten_to_device_only(args):
        if len(args) == 4:
            return args[0].node().kind() == 'prim::device' or args[0].type().isSubtypeOf(_C.ListType.ofInts()) or isinstance(args[0].type(), _C.DeviceObjType)
        elif len(args) == 5:
            dtype = symbolic_helper._get_const(args[1], 'i', 'dtype')
            return dtype is None
        elif <MASK>:
            dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
            return dtype is None
        return False
    if is_aten_to_device_only(args):
        return self
    if len(args) == 4:
        dtype = args[0]
        if symbolic_helper._is_value(args[0]) and args[0].node().kind() == 'onnx::Constant':
            tval = symbolic_helper._node_get(args[0].node(), 'value')
            if isinstance(tval, torch.Tensor):
                if len(tval.shape) == 0:
                    tval = tval.item()
                    dtype = int(tval)
                else:
                    dtype = tval
        if symbolic_helper._is_value(dtype) or isinstance(dtype, torch.Tensor):
            dtype = _type_utils.JitScalarType.from_value(args[0])
            return g.op('Cast', self, to_i=dtype.onnx_type())
        else:
            return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    elif len(args) == 5:
        dtype = symbolic_helper._get_const(args[1], 'i', 'dtype')
        return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    elif len(args) == 6:
        dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
        return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    elif len(args) == 7:
        dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
        return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    return symbolic_helper._onnx_unsupported('Unknown aten::to signature', self)

@trackable.no_automatic_dependency_tracking
def _set_input_attrs(self, inputs):
    """Sets attributes related to the inputs of the Model."""
    if self.inputs:
        raise ValueError('Model inputs are already set.')
    if self.__class__.__name__ == 'Sequential' and (not self.built):
        if tensor_util.is_tf_type(inputs):
            input_shape = (None,) + tuple(inputs.shape.as_list()[1:])
        elif <MASK>:
            input_shape = (None,) + tuple(inputs.as_list()[1:])
        elif isinstance(inputs, dict):
            if not training_utils_v1.is_feature_layer(self.layers[0]):
                raise ValueError("Passing a dictionary input to a Sequential Model which doesn't have FeatureLayer as the first layer is an error.")
            input_shape = (None,)
        else:
            input_shape = (None,) + tuple(inputs.shape[1:])
        self._build_input_shape = input_shape
    inputs = self._maybe_cast_inputs(inputs)
    model_inputs = training_utils_v1.ModelInputs(inputs)
    inputs = model_inputs.get_symbolic_inputs()
    self.inputs = model_inputs.get_symbolic_inputs(return_single_as_list=True)
    self.input_names = model_inputs.get_input_names()
    self._feed_inputs = []
    self._feed_input_names = []
    self._feed_input_shapes = []
    for (k, v) in model_inputs.as_dict():
        if backend.is_placeholder(v):
            self._feed_input_names.append(k)
            self._feed_inputs.append(v)
            self._feed_input_shapes.append(backend.int_shape(v))
    return inputs

@disable_if_config_true
def _pre_forward(self, module: nn.Module, args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[tuple[Any, ...], dict[str, Any]]:
    if self._training_state == TrainingState.PRE_BACKWARD:
        return (args, kwargs)
    self._training_state = TrainingState.FORWARD
    (args, kwargs) = self._root_pre_forward(module, args, kwargs)
    if <MASK>:
        with torch.profiler.record_function('FSDP::cast_forward_inputs'):
            cast_fn = functools.partial(_cast_fp_tensor, self._mp_policy.param_dtype)
            (args, kwargs) = (_apply_to_tensors(cast_fn, args), _apply_to_tensors(cast_fn, kwargs))
    if self._fsdp_param_group:
        (args, kwargs) = self._fsdp_param_group.pre_forward(module, args, kwargs)
    for fsdp_state in self._states_to_forward_prefetch:
        if (target_param_group := fsdp_state._fsdp_param_group) is not None:
            FSDPParamGroup._prefetch_unshard(target_param_group, 'forward')
    return (args, kwargs)

@classmethod
def __torch_dispatch__(cls, func, types, args=(), kwargs=None):
    if not all((issubclass(cls, t) for t in types)):
        return NotImplemented
    if <MASK>:
        kwargs = {}

    def unwrap(e):
        return e.t if isinstance(e, WrapperTensorWithCustomSizes) else e

    def wrap(e):
        return WrapperTensorWithCustomSizes(e) if isinstance(e, torch.Tensor) else e
    rs = tree_map(wrap, func(*tree_map(unwrap, args), **tree_map(unwrap, kwargs or {})))
    return rs

def __next__(self) -> tuple[tuple[object, ...], dict[str, object]]:
    try:
        next_sharding_choices = next(self.sharding_combs)
        idx = 0
        new_args: list[object] = []
        for arg in self.flatten_args:
            if <MASK>:
                new_args.append(self.to_dist_tensor(arg, self.mesh, [next_sharding_choices[idx]]))
                idx += 1
            else:
                new_args.append(arg)
        new_kwargs: list[object] = []
        for arg in self.flatten_kwargs:
            if isinstance(arg, torch.Tensor):
                new_kwargs.append(self.to_dist_tensor(arg, self.mesh, [next_sharding_choices[idx]]))
                idx += 1
            else:
                new_kwargs.append(arg)
        return (tree_unflatten(new_args, self.flatten_args_spec), tree_unflatten(new_kwargs, self.flatten_kwargs_spec))
    except StopIteration as e:
        raise StopIteration from e

def check_fn(match: Match) -> bool:
    """
        Often shapes get burned into the pattern, so our initial match ran with
        `ignore_types=(int, ...)`.

        Recheck the match with the correct shapes.
        """
    argnames = list(argnames_static)
    for name in argnames:
        if name not in match.kwargs:
            raise RuntimeError(f'Not all inputs to pattern found in match.kwargs. Perhaps one of the inputs is unused? argnames={argnames}, match.kwargs={match.kwargs}')
    args = list(torch.fx.map_arg([match.kwargs[name] for name in argnames], lambda n: n.meta['val']))
    sym_args: list[torch.SymInt] = []
    fake_mode = torch._dynamo.utils.detect_fake_mode(args)
    assert fake_mode is not None
    with fake_mode:
        for (i, grad) in enumerate(requires_grad):
            if isinstance(args[i], torch.Tensor):
                if <MASK>:
                    return False
                args[i] = torch.empty_strided(args[i].size(), args[i].stride(), dtype=args[i].dtype, device=args[i].device, requires_grad=grad)
                for v in itertools.chain(args[i].shape, args[i].stride()):
                    if isinstance(v, torch.SymInt) and all((statically_known_true(v != a) for a in sym_args)):
                        sym_args.append(v)
        specific_pattern = search_fn_pattern
        if not specific_pattern:
            if sym_args:

                def search_fn_new(*args_new: Any) -> Any:
                    return search_fn(*args_new[len(args_new) - len(args):])
                try:
                    specific_graph = trace_fn(search_fn_new, sym_args + args)
                except RuntimeError as e:
                    log_trace_failure(search_fn, e)
                    return False
                sym_arg_names = []
                for (i, placeholder) in zip(range(len(sym_args) + len(args)), specific_graph.graph.nodes):
                    if i < len(sym_args):
                        sym_arg_names.append(placeholder.target)
                        continue
                    with specific_graph.graph.inserting_after(placeholder):
                        new_node = specific_graph.graph.placeholder(argnames[i - len(sym_args)])
                        new_node.target = new_node.name
                        placeholder.replace_all_uses_with(new_node)
                        specific_graph.graph.erase_node(placeholder)
                argnames = sym_arg_names + argnames
            else:
                try:
                    specific_graph = trace_fn(search_fn, args)
                except RuntimeError as e:
                    log_trace_failure(search_fn, e)
                    return False
            specific_pattern = fx_to_pattern(specific_graph, argnames=argnames, exclusive_arg_names=exclusive_arg_names, scalar_workaround=scalar_workaround)
        node = match.output_nodes()[0]
        assert node is not None
        specific_pattern_match = specific_pattern.match(node)
        if is_match(specific_pattern_match) and extra_check(specific_pattern_match):
            match.replacement_graph = trace_fn(replace_fn, args)
            if len(match.nodes) == 1:
                for n in match.replacement_graph.graph.nodes:
                    _transfer_meta(new_meta=n.meta, old_node=match.nodes[0], pass_name='replacement')
            return True
        return False

def safe_pow(base, exp):
    sign = 1
    if <MASK>:
        base = -base
        sign = 1 if exp % 2 == 0 else -1
    return sign * _safe_pow(base, exp)

def _create_context():
    with _context_lock:
        if <MASK>:
            ctx = Context()
            _set_context_locked(ctx)

@final
def _try_convert_data(self, name: Hashable, data: Series, use_dtypes: bool=True, convert_dates: bool | list[str]=True, is_axis: bool=False) -> tuple[Series, bool]:
    """
        Try to parse a Series into a column by inferring dtype.
        """
    org_data = data
    if use_dtypes:
        if not self.dtype:
            if <MASK>:
                return (data, False)
            filled = data.fillna(np.nan)
            return (filled, True)
        elif self.dtype is True:
            pass
        elif not _should_convert_dates(convert_dates, self.keep_default_dates, name):
            dtype = self.dtype.get(name) if isinstance(self.dtype, dict) else self.dtype
            if dtype is not None:
                try:
                    return (data.astype(dtype), True)
                except (TypeError, ValueError):
                    return (data, False)
    if convert_dates:
        new_data = self._try_convert_to_date(data)
        if new_data is not data:
            return (new_data, True)
    converted = False
    if self.dtype_backend is not lib.no_default and (not is_axis):
        return (data, True)
    elif is_string_dtype(data.dtype):
        try:
            data = data.astype('float64')
            converted = True
        except (TypeError, ValueError):
            pass
    if data.dtype.kind == 'f' and data.dtype != 'float64':
        try:
            data = data.astype('float64')
            converted = True
        except (TypeError, ValueError):
            pass
    if len(data) and data.dtype in ('float', 'object'):
        try:
            new_data = org_data.astype('int64')
            if (new_data == data).all():
                data = new_data
                converted = True
        except (TypeError, ValueError, OverflowError):
            pass
    if data.dtype == 'int' and data.dtype != 'int64':
        try:
            data = data.astype('int64')
            converted = True
        except (TypeError, ValueError):
            pass
    if name == 'index' and len(data):
        if self.orient == 'split':
            return (data, False)
    return (data, converted)

def _get_param_module_infos(params: list[nn.Parameter], modules: tuple[nn.Module, ...]) -> list[ParamModuleInfo]:
    """
    Shared parameter: lin1.weight = lin2.weight
    Shared module: mlp.lin1 = mlp.lin2
    We do not remove duplicates when traversing both modules and parameters to
    find shared modules' parameters and shared parameters within a module.
    """
    params_set = set(params)
    param_to_module_info: dict[nn.Parameter, ParamModuleInfo] = {}
    for module in modules:
        for (_, submodule) in module.named_modules(remove_duplicate=False):
            for (param_name, param) in _named_parameters_with_duplicates(submodule, recurse=False):
                if param in params_set:
                    if <MASK>:
                        param_to_module_info[param] = ParamModuleInfo(submodule, param_name)
                    else:
                        param_to_module_info[param].shared_modules.append(submodule)
                        param_to_module_info[param].shared_param_names.append(param_name)
    if len(param_to_module_info) != len(params):
        raise AssertionError(f'Some parameters are not in the module tree of {modules}')
    return [param_to_module_info[param] for param in params]

def args_codegen(self, arg_operations):
    """Generate DTensor argument creation code with proper mesh setup."""
    code_lines = []
    code_lines.extend(['world_size = 1024', 'fake_store = FakeStore()', 'torch.distributed.init_process_group(', '    "fake", store=fake_store, rank=0, world_size=world_size', ')', '', 'mesh = torch.distributed.device_mesh.init_device_mesh(', '    "cuda",', '    (2, 8),', '    mesh_dim_names=(', '        "dim1", "dim2",', '    ),', ')', '', 'placements = (Replicate(), Replicate())', '', '# Sentinel tensor to ensure gradient computation', "sentinel_local = torch.tensor(1.0, device='cuda', requires_grad=True)", 'sentinel = DTensor.from_local(sentinel_local, mesh, placements)', ''])
    if arg_operations:
        for (i, (node_id, spec)) in enumerate(arg_operations):
            arg_name = f'arg_{i}'
            if isinstance(spec, ScalarSpec):
                dtype_str = f'torch.{spec.dtype}'.replace('torch.torch.', 'torch.')
                code_lines.extend([f"{arg_name}_local = torch.randn((), dtype={dtype_str}, device='cuda', requires_grad=True)", f'{arg_name} = DTensor.from_local({arg_name}_local, mesh, placements)'])
            elif <MASK>:
                size_str = str(spec.size)
                dtype_str = f'torch.{spec.dtype}'.replace('torch.torch.', 'torch.')
                if spec.dtype in [torch.int32, torch.int64, torch.int8, torch.int16]:
                    code_lines.extend([f"{arg_name}_local = torch.randint(1, 10, {size_str}, dtype={dtype_str}, device='cuda')", f'{arg_name} = DTensor.from_local({arg_name}_local, mesh, placements)'])
                elif spec.dtype == torch.bool:
                    code_lines.extend([f"{arg_name}_local = torch.randint(0, 2, {size_str}, device='cuda').bool()", f'{arg_name} = DTensor.from_local({arg_name}_local, mesh, placements)'])
                else:
                    code_lines.extend([f"{arg_name}_local = torch.randn({size_str}, dtype={dtype_str}, device='cuda', requires_grad=True)", f'{arg_name} = DTensor.from_local({arg_name}_local, mesh, placements)'])
    return code_lines

def _make_elementwise_unary_reference(type_promotion_kind, *, aten_op=infer_aten_op, extra_meta=None, exact_dtype=False) -> Callable:

    def inner(prim: Callable):
        nonlocal aten_op

        @wraps(prim)
        @out_wrapper(exact_dtype=exact_dtype)
        @elementwise_unary_scalar_wrapper
        @elementwise_type_promotion_wrapper(type_promoting_args=('a',), type_promotion_kind=type_promotion_kind)
        def _ref(a: TensorLikeType) -> TensorLikeType:
            if extra_meta is not None:
                extra_meta(a)
            output = prim(a)
            return handle_noncontiguous_outputs([a], output)
        if aten_op is infer_aten_op:
            aten_op = utils.get_aten_op(prim, prim.__name__)
        if <MASK>:
            register_decomposition(aten_op)(_ref)
        return _ref
    return inner

def add_axis_name(x: str) -> None:
    if x in self.identifiers:
        if not (allow_underscore and x == '_') and (not allow_duplicates):
            raise ValueError(f"Indexing expression contains duplicate dimension '{x}'")
    if x == _ellipsis:
        self.identifiers.add(_ellipsis)
        if <MASK>:
            self.composition.append(_ellipsis)
            self.has_ellipsis_parenthesized = False
        else:
            bracket_group.append(_ellipsis)
            self.has_ellipsis_parenthesized = True
    else:
        is_number = str.isdecimal(x)
        if is_number and int(x) == 1:
            if bracket_group is None:
                self.composition.append([])
            else:
                pass
            return
        (is_axis_name, reason) = self.check_axis_name_return_reason(x, allow_underscore=allow_underscore)
        if not (is_number or is_axis_name):
            raise ValueError(f'Invalid axis identifier: {x}\n{reason}')
        axis_name: Union[str, AnonymousAxis] = AnonymousAxis(x) if is_number else x
        self.identifiers.add(axis_name)
        if is_number:
            self.has_non_unitary_anonymous_axes = True
        if bracket_group is None:
            self.composition.append([axis_name])
        else:
            bracket_group.append(axis_name)

def apply_aggregation_replica_context(value, aggregation, destinations):
    """Aggregate `value` to `destinations` as specified by `aggregation`."""
    if isinstance(value, DistributedValues):
        raise TypeError('Cannot use DistributedValues to update variables in replica context.')
    if <MASK>:
        return value
    if aggregation == vs.VariableAggregation.ONLY_FIRST_REPLICA:

        def merge_fn(strategy, value):
            return strategy.extended.broadcast_to(strategy.experimental_local_results(value)[0], destinations=destinations)
        return distribute_lib.get_replica_context().merge_call(merge_fn, args=(value,))
    else:
        reduce_op = reduce_util.ReduceOp.from_variable_aggregation(aggregation)
        aggregated_value = distribute_lib.get_strategy().extended._replica_ctx_all_reduce(reduce_op, value)
        return aggregated_value

def _check_multimetric_scoring(estimator, scoring):
    """Check the scoring parameter in cases when multiple metrics are allowed.

    In addition, multimetric scoring leverages a caching mechanism to not call the same
    estimator response method multiple times. Hence, the scorer is modified to only use
    a single response method given a list of response methods and the estimator.

    Parameters
    ----------
    estimator : sklearn estimator instance
        The estimator for which the scoring will be applied.

    scoring : list, tuple or dict
        Strategy to evaluate the performance of the cross-validated model on
        the test set.

        The possibilities are:

        - a list or tuple of unique strings;
        - a callable returning a dictionary where they keys are the metric
          names and the values are the metric scores;
        - a dictionary with metric names as keys and callables a values.

        See :ref:`multimetric_grid_search` for an example.

    Returns
    -------
    scorers_dict : dict
        A dict mapping each scorer name to its validated scorer.
    """
    err_msg_generic = f'scoring is invalid (got {scoring!r}). Refer to the scoring glossary for details: https://scikit-learn.org/stable/glossary.html#term-scoring'
    if isinstance(scoring, (list, tuple, set)):
        err_msg = 'The list/tuple elements must be unique strings of predefined scorers. '
        try:
            keys = set(scoring)
        except TypeError as e:
            raise ValueError(err_msg) from e
        if len(keys) != len(scoring):
            raise ValueError(f'{err_msg} Duplicate elements were found in the given list. {scoring!r}')
        elif len(keys) > 0:
            if not all((isinstance(k, str) for k in keys)):
                if any((callable(k) for k in keys)):
                    raise ValueError(f'{err_msg} One or more of the elements were callables. Use a dict of score name mapped to the scorer callable. Got {scoring!r}')
                else:
                    raise ValueError(f'{err_msg} Non-string types were found in the given list. Got {scoring!r}')
            scorers = {scorer: check_scoring(estimator, scoring=scorer) for scorer in scoring}
        else:
            raise ValueError(f'{err_msg} Empty list was given. {scoring!r}')
    elif isinstance(scoring, dict):
        keys = set(scoring)
        if not all((isinstance(k, str) for k in keys)):
            raise ValueError(f'Non-string types were found in the keys of the given dict. scoring={scoring!r}')
        if <MASK>:
            raise ValueError(f'An empty dict was passed. {scoring!r}')
        scorers = {key: check_scoring(estimator, scoring=scorer) for (key, scorer) in scoring.items()}
    else:
        raise ValueError(err_msg_generic)
    return scorers

def dataset_is_infinite(dataset):
    """True if the passed dataset is infinite."""
    if <MASK>:
        return math_ops.equal(cardinality.cardinality(dataset), cardinality.INFINITE)
    else:
        dataset_size = K.get_session().run(cardinality.cardinality(dataset))
        return dataset_size == cardinality.INFINITE

def _convert_to_list_leaving_none(param):
    """Convert parameters to a list, leaving `None` as is."""
    if <MASK>:
        return None
    if isinstance(param, list):
        return param
    return [param]

def from_dynamic_shapes_to_dynamic_axes(dynamic_shapes: dict[str, Any] | tuple[Any, ...] | list[Any], input_names: Sequence[str], exception: Exception) -> dict[str, Any] | None:
    """
    Converts dynamic_shapes into dynamic_axes by removing torch.export.Dim wrapping
    and converting to list or dict form based on whether dimension names are present.

    dynamic_shapes examples:
    (1) dynamic_shapes = {"x": {0: Dim("my_custom_axis_name_1")}, "y": {1: Dim("my_custom_axis_name_2")}}
    (2) dynamic_shapes = ({0: Dim("my_custom_axis_name_1"}, {1: Dim("my_custom_axis_name_2")})

    these will be converted to dynamic_axes respectively:
    (1) dynamic_axes = {"x": [0], "y": [1]}
    (2) dynamic_axes = {"x": [0], "y": [1]}

    NOTE: If the model input is nested, so is the dynamic_shapes, we need to flatten the dynamic_shapes,
    and then assign the axes to the input names in the order they are provided.

    NOTE: input_names are used to assign the axes to the correct input names. If the input names are not
    provided, or less than the dynamic inputs/axes, it raises an error.
    """
    (flat_dynamic_shapes, _) = _flatten_dynamic_shapes_to_axes(dynamic_shapes)
    if len(input_names) < len(flat_dynamic_shapes):
        raise ValueError(f'To construct dynamic_axes from dynamic_shapes, number of input names ({len(input_names)}) should be greater than or equal to the number of graph inputs(flat) ({len(flat_dynamic_shapes)})') from exception
    dynamic_axes: dict[str, list[int]] = {}
    for (input_name, axes) in zip(input_names, flat_dynamic_shapes):
        if axes is None:
            continue
        converted_axes: list[int] = []
        if isinstance(axes, dict):
            for (axis, dim) in axes.items():
                if dim is None:
                    continue
                converted_axes.append(axis)
            dynamic_axes[input_name] = converted_axes
        elif <MASK>:
            for (idx, dim) in enumerate(axes):
                if dim is None:
                    continue
                converted_axes.append(idx)
            dynamic_axes[input_name] = converted_axes
    return dynamic_axes

def wrap_tensor(self, value: torch.Tensor):
    source = self.get_source()
    assert value not in self.tx.output.side_effects
    is_static_input = get_static_address_type(value) is not None
    if config.inline_inbuilt_nn_modules and (not is_static_input) and (isinstance(value, torch.nn.Parameter) or (source and source.guard_source().is_unspecialized_nn_module())):
        self.mark_static_input(value, guard=is_parameter_freezing())
        is_static_input = True
    should_install_free_tensor = config.install_free_tensors and (is_from_global_source(source) or is_from_nonlocal_source(source) or is_from_unspecialized_nn_module_source(source))
    make_graph_attribute = is_static_input and (not config.inline_inbuilt_nn_modules or is_parameter_freezing() or torch._dynamo.config.prepare_freezing)
    if should_install_free_tensor or ((source.guard_source().is_specialized_nn_module() or make_graph_attribute) and (not source.guard_source().is_fsdp_module())):
        self.assert_not_wrapped_by_this_graph(value)
        return self.tx.output.register_attr_or_module(value, self.name, source=source)
    if get_static_address_type(value) == 'guarded':
        self.install_guards(GuardBuilder.ID_MATCH)
        self.assert_not_wrapped_by_this_graph(value)
        return self.tx.output.register_attr_or_module(value, self.name, source=source)
    if is_constant_source(source):
        self.assert_not_wrapped_by_this_graph(value)
        return self.tx.output.register_attr_or_module(value, re.sub('[^a-zA-Z0-9]+', '_', self.name), source=source)
    is_duplicate_tensor = source in self.tx.output.input_source_to_var
    if is_duplicate_tensor:
        return self.tx.output.input_source_to_var[source]
    options = {}
    subclass_type = infer_subclass_type(value)
    if subclass_type is not None:
        self.install_guards(GuardBuilder.TYPE_MATCH)
    if get_static_address_type(value) == 'guarded':
        self.install_guards(GuardBuilder.ID_MATCH)
    self.assert_not_wrapped_by_this_graph(value)
    if isinstance(value, torch.Tensor) and value.is_nested and (not isinstance(value, torch.nested._internal.nested_tensor.NestedTensor)):
        unimplemented_v2(gb_type='Attempted to wrap strided NestedTensor', context='', explanation='torch.compile does not support strided NestedTensor', hints=[])
    if isinstance(value, torch.Tensor) and is_sparse_any(value) and (not self.tx.export or not config.capture_sparse_compute):
        unimplemented_v2(gb_type='Attempted to wrap sparse Tensor', context='', explanation='torch.compile does not support sparse Tensors', hints=[*graph_break_hints.SUPPORTABLE])
    if safe_has_grad(value) and safe_grad(value) is not None and (value.dtype != safe_grad(value).dtype):
        unimplemented_v2(gb_type='dtype mismatch between tensor and its gradient', context=f'tensor dtype: {value.dtype}; grad dtype: {safe_grad(value).dtype}', explanation='Inconsistent dtype between tensor and its gradient. This can happen in FSDP and crashes meta tensor creation.', hints=[*graph_break_hints.SUPPORTABLE])
    example_value = wrap_to_fake_tensor_and_record(value, tx=self.tx, is_tensor=True, source=source)
    tensor_proxy = self.tx.output.root_tracer.create_graph_input(re.sub('[^a-zA-Z0-9]+', '_', self.name), type(value), example_value, source=source)
    cache_real_value_when_export(self.tx, tensor_proxy, value)
    tensor_variable = wrap_fx_proxy(tx=self.tx, proxy=tensor_proxy, example_value=example_value, subclass_type=subclass_type, source=source, **options)
    if value._is_view():
        wrap_to_fake_tensor_and_record(value._base, tx=self.tx, source=AttrSource(source, '_base'), is_tensor=True)
    guard_type = GuardBuilder.TENSOR_MATCH
    if isinstance(source, GradSource) and is_from_optimizer_source(source):
        guard_type = GuardBuilder.NOT_NONE_MATCH
    self.install_guards(functools.partial(guard_type, value=value if isinstance(source, NumpyTensorSource) else TensorWeakRef(value)))
    if <MASK>:
        self.install_guards(GuardBuilder.TENSOR_SUBCLASS_METADATA_MATCH)
        self.install_guards(GuardBuilder.TYPE_MATCH)
        install_guard(SubclassAttrListSource(source).make_guard(GuardBuilder.EQUALS_MATCH))
        (attrs, _) = value.__tensor_flatten__()
        for attr in attrs:
            inner_value = getattr(value, attr)
            inner_source = AttrSource(self.source, attr)
            LazyVariableTracker.realize_all(VariableBuilder(self.tx, inner_source)(inner_value))
    self.tx.output.input_source_to_var[source] = tensor_variable
    assert 'tensor_dict' not in tensor_proxy.node.meta
    tensor_proxy.node.meta['tensor_dict'] = _extract_tensor_dict(value)
    fake_tensor_value = tensor_variable.proxy.node.meta['example_value']
    if maybe_get_fake_mode(fake_tensor_value) is not self.tx.fake_mode:
        raise InternalTorchDynamoError("Wrapped Tensor must be this graph's fake")
    grapharg = GraphArg(source, value, False, fake_tensor_value)
    tensor_proxy.node.meta['grapharg'] = grapharg
    return tensor_variable

def _common_norm_backward_strategy(op_schema: OpSchema, rms_norm: bool=False) -> OpStrategy:
    """Common backward strategy logic for layer_norm and rms_norm."""
    mesh = op_schema.get_mesh_from_args(validate=False)
    if <MASK>:
        if not len(op_schema.args_schema) == 8:
            raise AssertionError(f'Expected 8 args, got {len(op_schema.args_schema)}')
        (grad_out_strategy, input_strategy, normalized_shape, mean_strategy, rstd_strategy, weight_strategy, bias_strategy, output_mask) = op_schema.args_schema
    else:
        if not len(op_schema.args_schema) == 6:
            raise AssertionError(f'Expected 6 args, got {len(op_schema.args_schema)}')
        (grad_out_strategy, input_strategy, normalized_shape, rstd_strategy, weight_strategy, output_mask) = op_schema.args_schema
        mean_strategy = None
        bias_strategy = None
    if not isinstance(grad_out_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(grad_out_strategy)}')
    if not isinstance(input_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(input_strategy)}')
    if not isinstance(rstd_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(rstd_strategy)}')
    if mean_strategy is not None:
        if not isinstance(mean_strategy, OpStrategy):
            raise AssertionError(f'Expected OpStrategy, got {type(mean_strategy)}')
    if not isinstance(normalized_shape, (int, Sequence, torch.Size)):
        raise AssertionError(f'Expected int, Sequence, or torch.Size, got {type(normalized_shape)}')
    normalized_size = normalize_to_torch_size(normalized_shape)
    input_ndim = input_strategy.ndim
    axis = input_ndim - len(normalized_size)
    outer_dims = list(range(axis))
    if not rms_norm:
        if not (isinstance(output_mask, list) and len(output_mask) == 3):
            raise AssertionError(f"Expected output_mask to be list of length 3, got {type(output_mask)} of length {(len(output_mask) if isinstance(output_mask, list) else 'N/A')}")
    elif not (isinstance(output_mask, list) and len(output_mask) == 2):
        raise AssertionError(f"Expected output_mask to be list of length 2, got {type(output_mask)} of length {(len(output_mask) if isinstance(output_mask, list) else 'N/A')}")
    out_tuple_strategy = OpStrategy([])
    for (idx, input_placement_strategy) in enumerate(input_strategy.strategies):
        output_specs_list: list[Optional[DTensorSpec]] = []
        input_specs_list: list[DTensorSpec] = []
        redistribute_costs = []
        input_src_spec = input_placement_strategy.output_spec
        grad_out_target_spec = DTensorSpec(mesh=mesh, placements=_replicate_dims_start_at(input_src_spec.placements, axis), tensor_meta=input_src_spec.tensor_meta)
        input_specs_list.append(grad_out_target_spec)
        redistribute_costs.append(generate_redistribute_costs(grad_out_strategy, grad_out_target_spec))
        output_specs_list.append(grad_out_target_spec if output_mask[0] else None)
        input_target_spec = DTensorSpec(mesh=mesh, placements=_replicate_dims_start_at(input_src_spec.placements, axis), tensor_meta=input_src_spec.tensor_meta)
        input_specs_list.append(input_target_spec)
        redistribute_costs.append(generate_redistribute_costs(input_strategy, input_target_spec))
        if not rms_norm:
            if mean_strategy is None:
                raise AssertionError('Expected mean_strategy to not be None')
            mean_src_spec = mean_strategy.strategies[idx].output_spec
            input_specs_list.append(mean_src_spec)
            redistribute_costs.append([0.0 for _ in mean_strategy.strategies])
        rstd_src_spec = rstd_strategy.strategies[idx].output_spec
        input_specs_list.append(rstd_src_spec)
        redistribute_costs.append([0.0 for _ in rstd_strategy.strategies])

        def _add_target_input_spec(strategy) -> DTensorSpec:
            if not isinstance(strategy, OpStrategy):
                raise AssertionError(f'Expected OpStrategy, got {type(strategy)}')
            src_spec = strategy.strategies[idx].output_spec
            input_specs_list.append(src_spec)
            redistribute_costs.append([0.0 for _ in strategy.strategies])
            return src_spec
        if weight_strategy is not None:
            weight_src_spec = _add_target_input_spec(weight_strategy)
            inp_placements = _replicate_dims_start_at(input_src_spec.placements, axis)
            reduce_dims_map = _infer_reduce_dims_map(outer_dims, input_src_spec.ndim, False)
            out_placements = map_placements_after_reduction(inp_placements, outer_dims, reduce_dims_map, 'sum')
            weight_out_spec = DTensorSpec(mesh=mesh, placements=out_placements, tensor_meta=weight_src_spec.tensor_meta)
            output_specs_list.append(weight_out_spec if output_mask[1] else None)
        else:
            if not rms_norm:
                error_msg = 'output_mask[1] should not be `True` while weight argument is `None` in native_layer_norm_backward.'
            else:
                error_msg = 'output_mask[1] should not be `True` while weight argument is `None` in _fused_rms_norm_backward.'
            if output_mask[1] is not False:
                raise AssertionError(error_msg)
            output_specs_list.append(None)
        if not rms_norm:
            if bias_strategy is not None:
                bias_src_spec = _add_target_input_spec(bias_strategy)
                inp_placements = _replicate_dims_start_at(grad_out_target_spec.placements, axis)
                reduce_dims_map = _infer_reduce_dims_map(outer_dims, grad_out_target_spec.ndim, False)
                out_placements = map_placements_after_reduction(inp_placements, outer_dims, reduce_dims_map, 'sum')
                bias_out_spec = DTensorSpec(mesh=mesh, placements=out_placements, tensor_meta=bias_src_spec.tensor_meta)
                output_specs_list.append(bias_out_spec if output_mask[2] else None)
            else:
                if output_mask[2] is not False:
                    raise AssertionError('output_mask[2] should not be `True` while bias argument is `None` in native_layer_norm_backward.')
                output_specs_list.append(None)
        out_tuple_strategy.strategies.append(OpSpec(output_specs=tuple(output_specs_list), input_specs=input_specs_list, redistribute_cost=redistribute_costs))
    return out_tuple_strategy

def split_const_subgraphs(module: Union[torch.nn.Module, torch.fx.GraphModule], skip_folding_node_fn: Optional[Callable[[torch.fx.Node], bool]]=None, device_for_folded_attrs: str='cpu') -> FoldedGraphModule:
    """
    Looks through `module` for any nodes that have all constant attribute inputs
    and separates them out into their own constant subgraph, and returns a
    FoldedGraphModule which runs that constant subgraph on the first run to set
    attributes on the module prior to running the non-constant portion of the
    graph.
    """
    import sympy
    if not isinstance(module, torch.fx.GraphModule):
        mod_traced = torch.fx.symbolic_trace(module)
    else:
        mod_traced = module
    const_nodes: set[torch.fx.Node] = set()
    found_const_folding = False
    for node in mod_traced.graph.nodes:
        if node.op in {'placeholder', 'output'}:
            continue
        if node.op != 'get_attr' and (not set(node.all_input_nodes).issubset(const_nodes)):
            continue
        if skip_folding_node_fn and skip_folding_node_fn(node):
            continue
        if node.is_impure():
            continue
        if isinstance(node.kwargs.get('fill_value', None), sympy.Expr):
            continue
        const_nodes.add(node)
        if node.op != 'get_attr':
            found_const_folding = True
    if not found_const_folding:
        return FoldedGraphModule(mod_traced, mod_traced.graph)

    def mod_partition(node: torch.fx.Node):
        return 0 if node in const_nodes else 1
    split = split_module(mod_traced, module, mod_partition)
    (const_mod_name, non_const_mod_name) = ('submod_0', 'submod_1')
    (const_gm, non_const_gm) = (split.submod_0, getattr(split, non_const_mod_name, None))
    for node in non_const_gm.graph.nodes if non_const_gm else []:
        if node.op == 'call_module':
            setattr(split, node.target, getattr(non_const_gm, node.target))
    for node in const_gm.graph.nodes:
        if node.op == 'call_module':
            setattr(split, node.target, getattr(const_gm, node.target))
    call_const_gm_args = None
    for node in split.graph.nodes:
        if node.op == 'call_module':
            if node.target == const_mod_name:
                call_const_gm_args = node.args
                break
    assert call_const_gm_args is not None
    root_const_gm = torch.fx.GraphModule(split, const_gm.graph)
    ph_idx = 0
    for node in root_const_gm.graph.nodes:
        if node.op == 'output':
            multiple_outputs = isinstance(node.args[0], tuple)
            continue
        if node.op != 'placeholder':
            continue
        assert ph_idx < len(call_const_gm_args)
        in_node = call_const_gm_args[ph_idx]
        ph_idx += 1
        assert in_node.op == 'get_attr'
        with root_const_gm.graph.inserting_before(node):
            new_node = root_const_gm.graph.get_attr(in_node.target)
        new_node.meta = node.meta.copy()
        node.replace_all_uses_with(new_node)
        root_const_gm.graph.erase_node(node)
    assert 'multiple_outputs' in locals()
    fx_const_folded_attrs_name = get_unique_attr_name_in_module(mod_traced, '_FX_CONST_FOLDED_ATTRS')
    setattr(split, fx_const_folded_attrs_name, torch.nn.ParameterList() if multiple_outputs else torch.nn.Parameter())
    for node in split.graph.nodes:
        if node.op == 'call_module' and node.target == const_mod_name:
            with node.graph.inserting_before(node):
                folded_attrs = node.graph.get_attr(fx_const_folded_attrs_name)
            folded_attrs.meta = node.meta.copy()
            node.replace_all_uses_with(folded_attrs)
            break
    if <MASK>:
        _inline_module(split, non_const_mod_name)
    split.graph.eliminate_dead_code()
    return FoldedGraphModule(split, split.graph, root_const_gm.graph, fx_const_folded_attrs_name, device_for_folded_attrs)

@bottleneck_switch()
def nanmedian(values: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, mask=None) -> float | np.ndarray:
    """
    Parameters
    ----------
    values : ndarray
    axis : int, optional
    skipna : bool, default True
    mask : ndarray[bool], optional
        nan-mask if known

    Returns
    -------
    result : float | ndarray
        Unless input is a float array, in which case use the same
        precision as the input array.

    Examples
    --------
    >>> from pandas.core import nanops
    >>> s = pd.Series([1, np.nan, 2, 2])
    >>> nanops.nanmedian(s.values)
    2.0

    >>> s = pd.Series([np.nan, np.nan, np.nan])
    >>> nanops.nanmedian(s.values)
    nan
    """
    using_nan_sentinel = values.dtype.kind == 'f' and mask is None

    def get_median(x: np.ndarray, _mask=None):
        if _mask is None:
            _mask = notna(x)
        else:
            _mask = ~_mask
        if <MASK>:
            return np.nan
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
            warnings.filterwarnings('ignore', 'Mean of empty slice', RuntimeWarning)
            res = np.nanmedian(x[_mask])
        return res
    dtype = values.dtype
    (values, mask) = _get_values(values, skipna, mask=mask, fill_value=None)
    if values.dtype.kind != 'f':
        if values.dtype == object:
            inferred = lib.infer_dtype(values)
            if inferred in ['string', 'mixed']:
                raise TypeError(f'Cannot convert {values} to numeric')
        try:
            values = values.astype('f8')
        except ValueError as err:
            raise TypeError(str(err)) from err
    if not using_nan_sentinel and mask is not None:
        if not values.flags.writeable:
            values = values.copy()
        values[mask] = np.nan
    notempty = values.size
    res: float | np.ndarray
    if values.ndim > 1 and axis is not None:
        if notempty:
            if not skipna:
                res = np.apply_along_axis(get_median, axis, values)
            else:
                with warnings.catch_warnings():
                    warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
                    if values.shape[1] == 1 and axis == 0 or (values.shape[0] == 1 and axis == 1):
                        res = np.nanmedian(np.squeeze(values), keepdims=True)
                    else:
                        res = np.nanmedian(values, axis=axis)
        else:
            res = _get_empty_reduction_result(values.shape, axis)
    else:
        res = get_median(values, mask) if notempty else np.nan
    return _wrap_results(res, dtype)

def pin_memory(data_ptr: int, size: int) -> None:
    cudart = torch.cuda.cudart()
    succ = int(cudart.cudaHostRegister(data_ptr, size, 1))
    if <MASK>:
        raise RuntimeError(f"Registering memory failed with cudaError: {succ}. It's possible that this is an asynchronous error raised from a previous cuda operation. Consider launching with CUDA_LAUNCH_BLOCKING=1 to debug.")

def size(self, name=None):
    """Compute the number of elements in this queue.

    >>> q = tf.queue.FIFOQueue(capacity=10, dtypes=tf.int32)
    >>> q.enqueue_many(tf.constant([1, 2, 3, 4], dtype=tf.int32))
    >>> q.size()
    <tf.Tensor: shape=(), dtype=int32, numpy=4>

    Args:
      name: A name for the operation (optional).

    Returns:
      A scalar tensor containing the number of elements in this queue.
    """
    if name is None:
        name = '%s_Size' % self._name
    if <MASK>:
        return gen_data_flow_ops.queue_size_v2(self._queue_ref, name=name)
    else:
        return gen_data_flow_ops.queue_size(self._queue_ref, name=name)

@_onnx_symbolic('aten::pixel_unshuffle')
@symbolic_helper.parse_args('v', 'i')
def pixel_unshuffle(g: jit_utils.GraphContext, self, downscale_factor):
    dims = symbolic_helper._get_tensor_sizes(self)
    if len(dims) != 4:
        return symbolic_helper._unimplemented('pixel_shuffle', 'only support 4d input', self)
    if <MASK>:
        reshape_h = symbolic_helper._reshape_helper(g, symbolic_helper._unsqueeze_helper(g, self, [3]), g.op('Constant', value_t=torch.tensor([0, 0, -1, downscale_factor, 0])), allowzero=0)
        reshape_w = symbolic_helper._reshape_helper(g, reshape_h, g.op('Constant', value_t=torch.tensor([0, 0, 0, 0, -1, downscale_factor])), allowzero=0)
        after_transpose = g.op('Transpose', reshape_w, perm_i=[0, 1, 3, 5, 2, 4])
        final_reshape = symbolic_helper._reshape_helper(g, after_transpose, g.op('Constant', value_t=torch.tensor([0, -1, 1, 1, 0, 0])), allowzero=0)
        return symbolic_helper._squeeze_helper(g, final_reshape, [2, 3])
    else:
        output_channel = dims[1] * downscale_factor * downscale_factor
        after_view = symbolic_helper._reshape_helper(g, self, g.op('Constant', value_t=torch.tensor([-1, dims[1], dims[2] // downscale_factor, downscale_factor, dims[3] // downscale_factor, downscale_factor])), allowzero=0)
        after_transpose = g.op('Transpose', after_view, perm_i=[0, 1, 3, 5, 2, 4])
        return symbolic_helper._reshape_helper(g, after_transpose, g.op('Constant', value_t=torch.tensor([-1, output_channel, dims[2] // downscale_factor, dims[3] // downscale_factor])), allowzero=0)

def from_value(value: Any, context: trace.TracingContext=None) -> trace.TraceType:
    """Returns a TraceType corresponding to the value based on the context.

  Args:
    value: The value to generate a TraceType for.
    context: The TracingContext to be shared during protocol calls.

  Returns:
    A TraceType object representing the given value.
  """
    if <MASK>:
        context = InternalTracingContext()
    if context.is_legacy_signature and isinstance(value, trace.TraceType):
        return value
    elif isinstance(value, trace.SupportsTracingProtocol):
        generated_type = value.__tf_tracing_type__(context)
        if not isinstance(generated_type, trace.TraceType):
            raise TypeError('Expected an instance of TraceType for Tracing Protocol call to ' + str(value) + ' but got ' + str(generated_type))
        return generated_type
    if isinstance(value, weakref.ref):
        raise TypeError(f'weakref input {value} not supported for tf.function.')
    if hasattr(value, '__wrapped__'):
        return from_value(value.__wrapped__, context)
    if isinstance(value, list):
        return default_types.List(*(from_value(c, context) for c in value))
    if isinstance(value, tuple):
        if util.is_namedtuple(value):
            named_tuple_type = type(value)
            return default_types.NamedTuple.from_type_and_attributes(named_tuple_type, tuple((from_value(c, context) for c in value)))
        else:
            return default_types.Tuple(*(from_value(c, context) for c in value))
    if isinstance(value, collections.abc.Mapping):
        mapping_type = type(value)
        return default_types.Dict({k: from_value(value[k], context) for k in value}, mapping_type)
    if util.is_attrs(value):
        return default_types.Attrs.from_type_and_attributes(type(value), tuple((from_value(getattr(value, a.name), context) for a in value.__attrs_attrs__)))
    if util.is_np_ndarray(value):
        ndarray = value.__array__()
        return default_types.TENSOR(ndarray.shape, ndarray.dtype)
    if isinstance(value, custom_nest_protocol.CustomNestProtocol):
        (metadata, components) = value.__tf_flatten__()
        return custom_nest_trace_type.CustomNestTraceType(type(value), metadata, tuple((from_value(c, context) for c in components)))
    try:
        ref = weakref.ref(value)
        if ref is None:
            raise TypeError(f'Deleted objects are not valid tf.function arguments, Got {value!r}')
        else:
            return default_types.Weakref(ref)
    except TypeError:
        try:
            return default_types.Literal(value)
        except:
            raise TypeError(f'Could not generate a generic TraceType for {value!r}.Please verify that it is immutable/hashable. Otherwise, consider implementing the Tracing Protocol for it.')

def update_dict(tensor, arg_name, index=None):
    base = tensor if get_base(tensor) is None else get_base(tensor)

    def set_result(base_index):
        if index is None:
            arg_to_base_index[arg_name] = base_index
        else:
            arg_to_base_index[arg_name][index] = base_index
    if <MASK>:
        all_bases_addresses.append(base._cdata)
        all_bases.append(base)
        set_result(len(all_bases) - 1)
    else:
        set_result(all_bases_addresses.index(base._cdata))

def basichandlers(extension: str, data):
    """Transforms raw data (byte stream) into python objects.

    Looks at the extension and loads the data into a python object supporting
    the corresponding extension.

    Args:
        extension (str): The file extension
        data (byte stream): Data to load into a python object.

    Returns:
        object: The data loaded into a corresponding python object
            supporting the extension.

    Example:
        >>> import pickle
        >>> data = pickle.dumps("some data")
        >>> new_data = basichandlers("pickle", data)
        >>> new_data
        some data

    The transformation of data for extensions are:
        - txt, text, transcript: utf-8 decoded data of str format
        - cls, cls2, class, count, index, inx, id: int
        - json, jsn: json loaded data
        - pickle, pyd: pickle loaded data
        - pt: torch loaded data
    """
    if extension in 'txt text transcript':
        return data.decode('utf-8')
    if extension in ['cls', 'cls2', 'class', 'count', 'index', 'inx', 'id']:
        try:
            return int(data)
        except ValueError:
            return None
    if <MASK>:
        return json.loads(data)
    if extension in ['pyd', 'pickle']:
        return pickle.loads(data)
    if extension in ['pt']:
        stream = io.BytesIO(data)
        return torch.load(stream)
    return None

def assertRaisesRegex(self, expected_exception, expected_regex, *args, **kwargs):
    if hasattr(self, 'device_type') and self.device_type not in NATIVE_DEVICES and (self.device_type != 'mps'):
        expected_regex = ''
    if <MASK>:
        context = AssertRaisesContextIgnoreNotImplementedError(expected_exception, self, expected_regex)
        return context.handle('assertRaisesRegex', args, kwargs)
    else:
        return super().assertRaisesRegex(expected_exception, expected_regex, *args, **kwargs)

def clamp_wrap(val: Union[int, None], lower: int, upper: int, default: Union[Expr, int]) -> Union[Expr, int]:
    if <MASK>:
        return default
    val = cls.handle_negative_index(val, dim_size)
    return clamp(val, lower, upper)

def get_platform():
    if <MASK>:
        return 'linux'
    elif sys.platform.startswith('win32'):
        return 'win32'
    elif sys.platform.startswith('cygwin'):
        return 'cygwin'
    elif sys.platform.startswith('darwin'):
        return 'darwin'
    else:
        return sys.platform

def _ensure_node_in_anf(self, parent, field, node):
    """Puts `node` in A-normal form, by replacing it with a variable if needed.

    The exact definition of A-normal form is given by the configuration.  The
    parent and the incoming field name are only needed because the configuration
    may be context-dependent.

    Args:
      parent: An AST node, the parent of `node`.
      field: The field name under which `node` is the child of `parent`.
      node: An AST node, potentially to be replaced with a variable reference.

    Returns:
      node: An AST node; the argument if transformation was not necessary,
        or the new variable reference if it was.
    """
    if node is None:
        return node
    if <MASK>:
        return node
    if isinstance(node, list):
        return [self._ensure_node_in_anf(parent, field, n) for n in node]
    if isinstance(node, gast.keyword):
        node.value = self._ensure_node_in_anf(parent, field, node.value)
        return node
    if isinstance(node, (gast.Starred, gast.withitem, gast.slice)):
        return self._ensure_fields_in_anf(node, parent, field)
    if self._should_transform(parent, field, node):
        return self._do_transform_node(node)
    else:
        return node

def send_messages(self, email_messages):
    """
        Send one or more EmailMessage objects and return the number of email
        messages sent.
        """
    if not email_messages:
        return 0
    with self._lock:
        new_conn_created = self.open()
        if <MASK>:
            return 0
        num_sent = 0
        try:
            for message in email_messages:
                sent = self._send(message)
                if sent:
                    num_sent += 1
        finally:
            if new_conn_created:
                self.close()
    return num_sent

def _npSoftmax(self, features, dim=-1, log=False):
    if dim == -1:
        dim = len(features.shape) - 1
    one_only_on_dim = list(features.shape)
    one_only_on_dim[dim] = 1
    is_fp16 = features.dtype == np.float16
    if is_fp16:
        features = features.astype(np.float32)
    e = np.exp(features - np.reshape(np.amax(features, axis=dim), one_only_on_dim))
    softmax = e / np.reshape(np.sum(e, axis=dim), one_only_on_dim)
    if <MASK>:
        res = np.log(softmax)
    else:
        res = softmax
    if is_fp16:
        res = res.astype(np.float16)
    return res

def _register_mesh(self, mesh: layout_lib.Mesh):
    """Idempotently register `mesh` with the dtensor device."""
    with self._mesh_lock:
        if <MASK>:
            _pywrap_dtensor_device.AddMesh(self._device_info, mesh.to_string(), False)
            self._meshes.add(mesh)
            if mesh.device_type().upper() == 'TPU':
                logging.info('Registering virtual 1:1 mapped host mesh %s for mesh %s', mesh.host_mesh().to_string(), mesh.to_string())
                _pywrap_dtensor_device.AddMesh(self._device_info, mesh.host_mesh().to_string(), True)
                self._meshes.add(mesh.host_mesh())

def _recursive_wrap(module: nn.Module, auto_wrap_policy: Callable, wrapper_cls: Callable, ignored_modules: set[nn.Module], ignored_params: set[nn.Parameter], only_wrap_children: bool=False, **kwargs: Any) -> tuple[nn.Module, int]:
    """
    Wraps submodules of ``module`` for which ``auto_wrap_policy`` returns
    ``True`` with ``wrapper_cls``.

    Args:
        module (nn.Module): Module to recursively wrap.
        auto_wrap_policy (Callable): A callable representing a policy that
            determines which modules to recursively wrap with ``wrapper_cls``.
        ignored_modules (set[torch.nn.Module]): Modules to ignore when
            wrapping.
        ignored_params (set[torch.nn.Parameter]): Parameters to ignore when
            wrapping; these should be the parameters contained in the modules
            in ``ignored_modules``.
    Returns:
        (nn.Module, int):
            ``module`` after wrapping and the numel recursively wrapped.
    """
    if <MASK>:
        raise AssertionError('Must specify auto_wrap_policy.')
    if wrapper_cls is None:
        raise AssertionError('Must specify wrapper_cls')
    for (_, child) in module.named_modules():
        if child in ignored_modules:
            continue
        try:
            if isinstance(child, cast(type, wrapper_cls)):
                raise AssertionError(f'Child module {child} is already wrapped by {wrapper_cls}')
        except TypeError:
            pass
    nonwrapped_numel = sum((p.numel() for p in module.parameters() if p not in ignored_params))
    if auto_wrap_policy is None:
        raise AssertionError('Expected auto_wrap_policy to be set')
    if auto_wrap_policy(module=module, recurse=True, nonwrapped_numel=nonwrapped_numel):
        total_wrapped_numel = 0
        for (name, child) in module.named_children():
            if child in ignored_modules:
                continue
            (wrapped_child, num_wrapped_params) = _recursive_wrap(module=child, auto_wrap_policy=auto_wrap_policy, wrapper_cls=wrapper_cls, ignored_modules=ignored_modules, ignored_params=ignored_params, **kwargs)
            setattr(module, name, wrapped_child)
            total_wrapped_numel += num_wrapped_params
        remainder = nonwrapped_numel - total_wrapped_numel
        if not only_wrap_children and auto_wrap_policy(module=module, recurse=False, nonwrapped_numel=remainder):
            return (_wrap(module, wrapper_cls, **kwargs), nonwrapped_numel)
        else:
            return (module, total_wrapped_numel)
    return (module, 0)

@dispatch(SingletonInt, SingletonInt)
def _eval_is_ge(a, b):
    if <MASK>:
        if a._coeff >= b._coeff:
