def handle_call_function(self, node: torch.fx.Node):
    assert node.op == 'call_function'
    meta_val = node.meta.get('val')
    log.debug('[handle_call_function] %s: %s(%s, {%s}) -> %s', node.name, node.target, node.args, node.kwargs, meta_val)
    if <MASK>:
        return
    if node.target in _SYM_OPS or (meta_val is not None and isinstance(meta_val, (torch.SymInt, torch.SymBool, torch.SymFloat))):
        assert len(node.kwargs) == 0
        ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_sym_op_inputs(node.target, node.args), outputs=[self.serialize_output(node.name, meta_val)], metadata=self.serialize_metadata(node))
    elif isinstance(node.target, torch._ops.OpOverload):
        ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_inputs(node.target, node.args, node.kwargs), outputs=self.serialize_outputs(node), metadata=self.serialize_metadata(node))
    elif isinstance(node.target, torch._ops.HigherOrderOperator):

        def _is_hop_single_tensor_return(node) -> bool:
            assert isinstance(node.target, torch._ops.HigherOrderOperator)
            meta_val = node.meta.get('val', None)
            return meta_val is not None and isinstance(meta_val, torch.Tensor)
        if node.target is torch._higher_order_ops.aoti_call_delegate:
            serializable_args = list(node.args)
            lowered_module_name: str = node.args[0].name
            assert hasattr(node.graph.owning_module, lowered_module_name)
            lowered_module = getattr(node.graph.owning_module, lowered_module_name)
            serializable_args[0] = lowered_module.aoti_path
            serializable_args[1] = None
            serializable_weight_nodes = []
            if serializable_args[2] is not None and isinstance(serializable_args[2], Iterable):
                for weight_node in serializable_args[2]:
                    if isinstance(weight_node, torch.fx.Node) and isinstance(weight_node.meta.get('val', None), ep.CustomObjArgument):
                        continue
                    serializable_weight_nodes.append(weight_node)
                serializable_args[2] = serializable_weight_nodes

            def serialize_tensor_list_output(node):
                meta_val = node.meta.get('val', None)
                tensor_args = []
                for (idx, meta) in enumerate(meta_val):
                    name = self._output_node_name_at_index(node, idx)
                    tensor_args.append(self.serialize_tensor_output(name, meta))
                return [Argument.create(as_tensors=tensor_args)]
            ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_hoo_inputs(serializable_args, node.kwargs), outputs=serialize_tensor_list_output(node), metadata=self.serialize_metadata(node), is_hop_single_tensor_return=False)
        elif node.target is torch._higher_order_ops.triton_kernel_wrap.triton_kernel_wrapper_functional:
            (kernel, kernel_cache_entry) = get_triton_kernel_and_cache_entry(node)
            kernel_cache_metadata = kernel_cache_entry.metadata
            meta_val = node.meta['val']
            assert isinstance(meta_val, dict)
            output_keys = meta_val.keys()
            output_indices = []
            constexpr_keys = set()
            for p in kernel.params:
                if p.is_constexpr:
                    constexpr_keys.add(p.name)
            found_constexpr = False
            args_new = ()
            i = 0
            assert isinstance(node.kwargs['kwargs'], dict)
            for (k, v) in node.kwargs['kwargs'].items():
                if k in constexpr_keys:
                    found_constexpr = True
                    continue
                assert not found_constexpr, 'non-constexpr args found after constexpr arg(s)'
                if k in output_keys:
                    output_indices.append(i)
                args_new += (v,)
                i += 1
            assert isinstance(node.kwargs['grid'], list)
            kwargs_new = {'name': kernel.fn.__name__, 'grid': node.kwargs['grid'][0], 'output_indices': output_indices, 'num_warps': kernel_cache_metadata.num_warps}
            if hasattr(kernel_cache_metadata, 'shared'):
                kwargs_new['shared_memory_bytes'] = kernel_cache_metadata.shared
            ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_hoo_inputs(args_new, kwargs_new), outputs=self.serialize_hoo_outputs(node), metadata=self.serialize_metadata(node), is_hop_single_tensor_return=_is_hop_single_tensor_return(node))
        else:
            ex_node = Node(target=self.serialize_operator(node.target), inputs=self.serialize_hoo_inputs(node.args, node.kwargs), outputs=self.serialize_hoo_outputs(node), metadata=self.serialize_metadata(node), is_hop_single_tensor_return=_is_hop_single_tensor_return(node))
    elif type(node.target) in _serialization_registry:
        assert type(node.target) in _serialization_registry, f'{type(node.target)} is not supported in export serialization.'
        handler = _serialization_registry[type(node.target)]
        namespace = handler.namespace()
        op_name = handler.to_op_name(node.target)
        assert isinstance(namespace, str) and isinstance(op_name, str)
        assert ':' not in namespace and ':' not in op_name
        ex_node = Node(target=f'#{namespace}:{op_name}', inputs=self.serialize_inputs(node.target, node.args, node.kwargs), outputs=self.serialize_outputs(node), metadata=self.serialize_metadata(node))
    else:
        raise SerializeError(f'Serializing {node.target} is not supported')
    self.graph_state.nodes.append(ex_node)

def supercedes(a, b):
    """``a`` is a more specific match than ``b``"""
    if isvar(b) and (not isvar(a)):
        return True
    s = unify(a, b)
    if s is False:
        return False
    s = {k: v for (k, v) in s.items() if not isvar(k) or not isvar(v)}
    if reify(a, s) == a:
        return True
    if <MASK>:
        return False

def _runOneTest(self, shape, dtype, batch, scalar_test):
    if dtype == dtypes_lib.float64:
        tol = 1e-05
    elif dtype == dtypes_lib.complex128:
        tol = 5e-05
    else:
        tol = 0.005
    epsilon = np.finfo(dtype.as_numpy_dtype).eps
    delta = epsilon ** (1.0 / 3.0)

    def RandomInput():
        a = np.random.randn(shape[0], shape[1]).astype(dtype.as_numpy_dtype)
        if dtype.is_complex:
            a += 1j * np.random.randn(shape[0], shape[1]).astype(dtype.as_numpy_dtype)
        return a

    def Compute(x):
        a = test_util.matmul_without_tf32(x, math_ops.conj(array_ops.matrix_transpose(x))) / shape[0]
        if batch:
            a = array_ops.tile(array_ops.expand_dims(a, 0), [2, 1, 1])
        c = linalg_ops.cholesky(a)
        if <MASK>:
            c = math_ops.reduce_mean(c)
        return c
    (theoretical, numerical) = gradient_checker_v2.compute_gradient(Compute, [RandomInput()], delta=delta)
    self.assertAllClose(theoretical, numerical, atol=tol, rtol=tol)

def reorder_arrays(arrays: list[ArrayLike], arr_columns: Index, columns: Index | None, length: int) -> tuple[list[ArrayLike], Index]:
    """
    Preemptively (cheaply) reindex arrays with new columns.
    """
    if columns is not None:
        if <MASK>:
            new_arrays: list[ArrayLike] = []
            indexer = arr_columns.get_indexer(columns)
            for (i, k) in enumerate(indexer):
                if k == -1:
                    arr = np.empty(length, dtype=object)
                    arr.fill(np.nan)
                else:
                    arr = arrays[k]
                new_arrays.append(arr)
            arrays = new_arrays
            arr_columns = columns
    return (arrays, arr_columns)

@classmethod
def construct_from_string(cls, string: str) -> NumpyEADtype:
    try:
        dtype = np.dtype(string)
    except TypeError as err:
        if <MASK>:
            msg = f"'construct_from_string' expects a string, got {type(string)}"
        else:
            msg = f"Cannot construct a 'NumpyEADtype' from '{string}'"
        raise TypeError(msg) from err
    return cls(dtype)

def _check_partition_boundary(self) -> None:
    """check partitioned graph is in valid state."""
    invalid_reasons = []
    fw_outputs = _find_hop_subgraph_outputs(self.fw_gm)
    for (i, out) in enumerate(fw_outputs):
        if 'val' not in out.meta:
            invalid_reasons.append(f"fw_gm output[{i}] doesn't have a 'val' meta.")
        elif not isinstance(out.meta['val'], (torch.SymInt, torch.Tensor)):
            invalid_reasons.append(f"fw_gm output[{i}] is of type {type(out.meta['val'])} but only SymInt or Tensor are allowed.")
        elif isinstance(out.meta['val'], torch.SymInt) and is_complex_expr(out.meta['val'].node.expr) and self.no_complex_exprs_at_boundary:
            invalid_reasons.append(f"fw_gm output[{i}] must be of type SymInt with basic symbols or Tensor but got {type(out.meta['val'])} {out.meta['val']}")
    if len(fw_outputs) != self.n_fw_outputs + self.n_intermediates:
        invalid_reasons.append(f'len(fw_outputs) ({len(fw_outputs)}) != n_fw_outputs ({self.n_fw_outputs}) + n_intermediates ({self.n_intermediates})')
    bw_phs = list(self.bw_gm.graph.find_nodes(op='placeholder'))
    if len(fw_outputs) != len(bw_phs):
        invalid_reasons.append(f"Expect number of fw_gm's output to be the same as bw_gm's input but fw_gm has {len(fw_outputs)} outputs, bw_gm takes {len(bw_phs)} inputs.")
    original_forward_outputs = fw_outputs[:self.n_fw_outputs]
    fw_intermediates = fw_outputs[self.n_fw_outputs:]
    bw_intermediates = bw_phs[:-self.n_fw_outputs]
    bw_grads = bw_phs[-self.n_fw_outputs:]

    def _match_size_or_expr(val1: Union[torch.SymInt, torch.Tensor], val2: Union[torch.SymInt, torch.Tensor]) -> bool:
        if type(val1) is not type(val2):
            return False
        if isinstance(val1, torch.SymInt) and isinstance(val2, torch.SymInt):
            return val1.node.expr == val2.node.expr
        elif isinstance(val1, torch.Tensor) and isinstance(val2, torch.Tensor):
            return val1.size() == val2.size()
        return False
    for (fw, bw) in zip(fw_intermediates, bw_intermediates):
        if fw.name != bw.name or not _match_size_or_expr(fw.meta['val'], bw.meta['val']):
            invalid_reasons.append("fw intermediates don't match bw intermediates")
    for (fw_out, bw_grad) in zip(original_forward_outputs, bw_grads):
        if <MASK>:
            invalid_reasons.append("fw outputs don't match bw gradients")
    if len(invalid_reasons) > 0:
        newline = '\n'
        raise RuntimeError('Invalid HopPartitionedGraph. Reasons:\n', f'{newline.join(invalid_reasons)}')

def _precompute_metric_params(X, Y, metric=None, **kwds):
    """Precompute data-derived metric parameters if not provided."""
    if <MASK>:
        if X is Y:
            V = np.var(X, axis=0, ddof=1)
        else:
            raise ValueError("The 'V' parameter is required for the seuclidean metric when Y is passed.")
        return {'V': V}
    if metric == 'mahalanobis' and 'VI' not in kwds:
        if X is Y:
            VI = np.linalg.inv(np.cov(X.T)).T
        else:
            raise ValueError("The 'VI' parameter is required for the mahalanobis metric when Y is passed.")
        return {'VI': VI}
    return {}

@final
def _call_cython_op(self, values: np.ndarray, *, min_count: int, ngroups: int, comp_ids: np.ndarray, mask: npt.NDArray[np.bool_] | None, result_mask: npt.NDArray[np.bool_] | None, initial: Any=0, **kwargs) -> np.ndarray:
    orig_values = values
    dtype = values.dtype
    is_numeric = dtype.kind in 'iufcb'
    is_datetimelike = dtype.kind in 'mM'
    if <MASK>:
        if mask is None:
            mask = isna(values)
    if is_datetimelike:
        values = values.view('int64')
        is_numeric = True
    elif dtype.kind == 'b':
        values = values.view('uint8')
    if values.dtype == 'float16':
        values = values.astype(np.float32)
    if self.how in ['any', 'all']:
        if dtype == object:
            if kwargs['skipna']:
                if mask is not None and mask.any():
                    values = values.copy()
                    values[mask] = True
        values = values.astype(bool, copy=False).view(np.int8)
        is_numeric = True
    values = values.T
    if mask is not None:
        mask = mask.T
        if result_mask is not None:
            result_mask = result_mask.T
    out_shape = self._get_output_shape(ngroups, values)
    func = self._get_cython_function(self.kind, self.how, values.dtype, is_numeric)
    values = self._get_cython_vals(values)
    out_dtype = self._get_out_dtype(values.dtype)
    result = maybe_fill(np.empty(out_shape, dtype=out_dtype))
    if self.kind == 'aggregate':
        counts = np.zeros(ngroups, dtype=np.int64)
        if self.how in ['idxmin', 'idxmax', 'min', 'max', 'mean', 'last', 'first', 'sum', 'median']:
            if self.how == 'sum':
                kwargs['initial'] = initial
            func(out=result, counts=counts, values=values, labels=comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, is_datetimelike=is_datetimelike, **kwargs)
        elif self.how in ['sem', 'std', 'var', 'ohlc', 'prod']:
            if self.how in ['std', 'sem']:
                kwargs['is_datetimelike'] = is_datetimelike
            func(result, counts, values, comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, **kwargs)
        elif self.how in ['any', 'all']:
            func(out=result, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            result = result.astype(bool, copy=False)
        elif self.how in ['skew', 'kurt']:
            func(out=result, counts=counts, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            if dtype == object:
                result = result.astype(object)
        else:
            raise NotImplementedError(f'{self.how} is not implemented')
    else:
        if self.how != 'rank':
            kwargs['result_mask'] = result_mask
        func(out=result, values=values, labels=comp_ids, ngroups=ngroups, is_datetimelike=is_datetimelike, mask=mask, **kwargs)
    if self.kind == 'aggregate' and self.how not in ['idxmin', 'idxmax']:
        if result.dtype.kind in 'iu' and (not is_datetimelike):
            cutoff = max(0 if self.how in ['sum', 'prod'] else 1, min_count)
            empty_groups = counts < cutoff
            if empty_groups.any():
                if result_mask is not None:
                    assert result_mask[empty_groups].all()
                else:
                    result = result.astype('float64')
                    result[empty_groups] = np.nan
    result = result.T
    if self.how not in self.cast_blocklist:
        res_dtype = self._get_result_dtype(orig_values.dtype)
        op_result = maybe_downcast_to_dtype(result, res_dtype)
    else:
        op_result = result
    return op_result

def convert_missing_indexer(indexer):
    """
    Reverse convert a missing indexer, which is a dict
    return the scalar indexer and a boolean indicating if we converted
    """
    if <MASK>:
        indexer = indexer['key']
        if isinstance(indexer, bool):
            raise KeyError('cannot use a single bool to index into setitem')
        return (indexer, True)
    return (indexer, False)

def _get_pyarrow_options(self) -> None:
    """
        Rename some arguments to pass to pyarrow
        """
    mapping = {'usecols': 'include_columns', 'na_values': 'null_values', 'escapechar': 'escape_char', 'skip_blank_lines': 'ignore_empty_lines', 'decimal': 'decimal_point', 'quotechar': 'quote_char'}
    for (pandas_name, pyarrow_name) in mapping.items():
        if pandas_name in self.kwds and self.kwds.get(pandas_name) is not None:
            self.kwds[pyarrow_name] = self.kwds.pop(pandas_name)
    date_format = self.date_format
    if isinstance(date_format, str):
        date_format = [date_format]
    else:
        date_format = None
    self.kwds['timestamp_parsers'] = date_format
    self.parse_options = {option_name: option_value for (option_name, option_value) in self.kwds.items() if option_value is not None and option_name in ('delimiter', 'quote_char', 'escape_char', 'ignore_empty_lines')}
    on_bad_lines = self.kwds.get('on_bad_lines')
    if on_bad_lines is not None:
        if callable(on_bad_lines):
            self.parse_options['invalid_row_handler'] = on_bad_lines
        elif on_bad_lines == ParserBase.BadLineHandleMethod.ERROR:
            self.parse_options['invalid_row_handler'] = None
        elif on_bad_lines == ParserBase.BadLineHandleMethod.WARN:

            def handle_warning(invalid_row) -> str:
                warnings.warn(f'Expected {invalid_row.expected_columns} columns, but found {invalid_row.actual_columns}: {invalid_row.text}', ParserWarning, stacklevel=find_stack_level())
                return 'skip'
            self.parse_options['invalid_row_handler'] = handle_warning
        elif on_bad_lines == ParserBase.BadLineHandleMethod.SKIP:
            self.parse_options['invalid_row_handler'] = lambda _: 'skip'
    self.convert_options = {option_name: option_value for (option_name, option_value) in self.kwds.items() if option_value is not None and option_name in ('include_columns', 'null_values', 'true_values', 'false_values', 'decimal_point', 'timestamp_parsers')}
    self.convert_options['strings_can_be_null'] = '' in self.kwds['null_values']
    if <MASK>:
        self.convert_options['include_columns'] = [f'f{n}' for n in self.convert_options['include_columns']]
    self.read_options = {'autogenerate_column_names': self.header is None, 'skip_rows': self.header if self.header is not None else self.kwds['skiprows'], 'encoding': self.encoding}

def check_can_launch() -> StaticallyLaunchedCudaKernel:
    if triton_meta.get('device_type') != 'cuda':
        raise CannotStaticallyLaunchKernel('Non-cuda device')
    if torch._inductor.config.cpp_wrapper:
        raise CannotStaticallyLaunchKernel('Cpp wrapper enabled')
    if heuristic_type == HeuristicType.USER_AUTOTUNE and (not torch._inductor.config.static_launch_user_defined_triton_kernels):
        raise CannotStaticallyLaunchKernel('User defined triton kernel')
    if inductor_meta.get('store_cubin'):
        raise CannotStaticallyLaunchKernel('store_cubin is enabled')
    if getattr(kernel.metadata, 'launch_pdl', False) or getattr(kernel.metadata, 'launch_cooperative_grid', False):
        raise CannotStaticallyLaunchKernel('static launch does not support launch attributes')
    cubin_location = os.path.join(triton_cache_dir(triton_meta.get('device', 0)), triton_hash_to_path_key(kernel.hash), f'{kernel.src.fn.__name__}.cubin')
    if <MASK>:
        raise CannotStaticallyLaunchKernel(f'Cubin path not found: {cubin_location}')
    else:
        kernel._cubin_path = cubin_location
    try:
        static_kernel = StaticallyLaunchedCudaKernel(kernel)
    except NotImplementedError as e:
        raise CannotStaticallyLaunchKernel(f'NotImplemented: {str(e)}') from e
    return static_kernel

def gen_class(self, f: NativeFunction, k: SchemaKind, *, class_name: str, parent_class: str, generate_super: bool) -> str:
    if <MASK>:
        output_type = 'Tensor'
        output_value = 'outputs_[output_idx]'
        proxy_field = ''
    elif k is SchemaKind.inplace:
        output_type = 'std::reference_wrapper<Tensor>'
        output_value = 'proxy_outputs_[output_idx].has_value() ? *proxy_outputs_[output_idx] : outputs_[output_idx].get()'
        proxy_field = f'std::array<::std::optional<Tensor>, {len(f.func.returns)}> proxy_outputs_;'
    elif k is SchemaKind.out:
        output_type = 'std::reference_wrapper<Tensor>'
        output_value = 'proxy_outputs_[output_idx].has_value() ? *proxy_outputs_[output_idx] : outputs_[output_idx].get()'
        proxy_field = f'std::array<::std::optional<Tensor>, {len(f.func.returns)}> proxy_outputs_;'
    else:
        raise RuntimeError(f'Unsupported SchemaKind {k}')
    if self.backend_index.dispatch_key == DispatchKey.CUDA:
        if self.rocm:
            guard_field = 'c10::hip::OptionalHIPGuardMasqueradingAsCUDA guard_;'
        else:
            guard_field = 'c10::cuda::OptionalCUDAGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.MPS:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.XPU:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.MTIA:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    else:
        guard_field = ''
    indent = ' ' * 4
    class_ctor_str = self.gen_class_ctor(k, class_name, len(f.func.returns))
    lines = (f'struct {class_name} final : public {parent_class} {{', f'{textwrap.indent(class_ctor_str, indent)}', f'{textwrap.indent(self.gen_class_set_output_functions(k, parent_class, generate_super), indent)}', '    const Tensor& maybe_get_output(int64_t output_idx) override {', f'      return {output_value};\n', '    }', f'    std::array<{output_type}, {len(f.func.returns)}> outputs_;', f'{textwrap.indent(proxy_field, indent)}', f'{textwrap.indent(guard_field, indent)}', '};')
    return '\n'.join((line for line in lines if line))

def _normalize_backend_override(backend_override: dict[Union[int, str], Union[str, C10dBackend.Options, tuple[str, C10dBackend.Options]]], ndim: int, mesh_dim_names: Optional[tuple[str, ...]]=None) -> Iterator[BackendConfig]:
    if mesh_dim_names is None:
        mesh_dim_names = ()
    for (dim_idx, dim_name) in zip_longest(range(ndim), mesh_dim_names):
        if dim_name is not None and dim_name in backend_override:
            if <MASK>:
                raise RuntimeError(f'Found redundant dim index {dim_idx} and name {dim_name} in backend_override')
            val = backend_override.pop(dim_name)
        elif dim_idx in backend_override:
            val = backend_override.pop(dim_idx)
        else:
            yield (None, None)
            continue
        if isinstance(val, str):
            yield (val, None)
        elif isinstance(val, C10dBackend.Options):
            yield (None, val)
        else:
            yield val
    if backend_override:
        raise RuntimeError(f'Found invalid keys in backend_override: got {list(backend_override.keys())}, expected integers in range [0, {ndim}) or one of {mesh_dim_names}')

def _static_check_for_broadcastable_batch_shape(operators):
    """ValueError if operators determined to have non-broadcastable shapes."""
    if <MASK>:
        return
    batch_shape = operators[0].batch_shape
    for op in operators[1:]:
        batch_shape = array_ops.broadcast_static_shape(batch_shape, op.batch_shape)

def call_for_each_replica(strategy, fn, args=None, kwargs=None):
    """Call `fn` on each worker devices(replica).

  It's highly recommended to wrap the call to this function inside a
  `tf.function`, otherwise the performance is poor.

  Args:
    strategy: `tf.distribute.Strategy`.
    fn: function to call on each worker devices.
    args: positional arguments to `fn`.
    kwargs: keyword arguments to `fn`.

  Returns:
    Wrapped returned value of `fn` from all replicas.
  """
    if <MASK>:
        args = ()
    if kwargs is None:
        kwargs = {}
    if isinstance(fn, def_function.Function):
        if fn._jit_compile and all([_is_gpu_device(d) for d in strategy.extended.worker_devices]):
            return _call_for_each_replica(strategy, fn, args, kwargs)
        if strategy not in _cfer_fn_cache:
            _cfer_fn_cache[strategy] = weakref.WeakKeyDictionary()
        wrapped = _cfer_fn_cache[strategy].get(fn)
        if wrapped is None:

            def wrapped_fn(*args, **kwargs):
                return call_for_each_replica(strategy, fn.python_function, args, kwargs)
            wrapped = fn._clone(python_function=wrapped_fn)
            _cfer_fn_cache[strategy][fn] = wrapped
        return wrapped(*args, **kwargs)
    if context.executing_eagerly():
        logging.log_first_n(logging.WARN, 'Using %s eagerly has significant overhead currently. We will be working on improving this in the future, but for now please wrap `call_for_each_replica` or `experimental_run` or `run` inside a tf.function to get the best performance.' % strategy.__class__.__name__, 5)
    else:
        fn = autograph.tf_convert(fn, autograph_ctx.control_status_ctx())
    return _call_for_each_replica(strategy, fn, args, kwargs)

def _broadcast_to(self, tensor, destinations):
    del destinations
    if isinstance(tensor, (float, int)):
        return tensor
    if <MASK>:
        broadcast_tensor = [tensor for _ in range(self._num_replicas_in_sync)]
        result = tpu_ops.all_to_all(broadcast_tensor, concat_dimension=0, split_dimension=0, split_count=self._num_replicas_in_sync)
        return result[0]
    return tensor

@_onnx_symbolic('aten::__or_')
def __or_(g: jit_utils.GraphContext, input, other):
    if not symbolic_helper._is_bool(input):
        raise errors.SymbolicValueError('ONNX export does NOT support exporting bitwise OR for non-boolean input values', input)
    if <MASK>:
        raise errors.SymbolicValueError('ONNX export does NOT support exporting bitwise OR for non-boolean input values', other)
    return g.op('Or', input, other)

