def get_linear_prepack_op_for_dtype(dtype):
    if dtype == torch.float16:
        return torch.ops.quantized.linear_prepack_fp16
    elif <MASK>:
        return torch.ops.quantized.linear_prepack
    else:
        raise Exception("can't get linear prepack op for dtype:", dtype)

def _match_nodes(self, pn: Node, gn: Node, match: InternalMatch, node_name_match: str='') -> bool:
    logger.info('  matching %s to %s', pn, gn)
    assert isinstance(pn, Node) and isinstance(gn, Node), str(f'pn and gn must be Node, pn: {pn}, gn: {gn}')
    if pn in match.nodes_map:
        return match.nodes_map[pn] == gn
    if gn in match.nodes_map.values():
        return False
    if not self._nodes_are_equal(pn, gn, node_name_match):
        return False
    saved_match = copy.copy(match)
    match.nodes_map[pn] = gn
    if pn.op == 'placeholder':
        return True
    match_found = True

    def _match_args(args1: Union[list, tuple], args2: Union[list, tuple]) -> bool:
        if len(args1) != len(args2):
            return False
        for (a1, a2) in zip(args1, args2):
            if <MASK>:
                matched = self._match_nodes(a1, a2, match)
            elif isinstance(a1, (list, tuple)) and isinstance(a2, (list, tuple)):
                matched = _match_args(a1, a2)
            else:
                matched = self._match_literals(a1, a2, match) or self.ignore_literals
            if not matched:
                return False
        return True
    (pn_args, gn_args) = (None, None)
    if (len(pn.args) != len(gn.args) or list(pn.kwargs.keys()) != list(gn.kwargs.keys())) and pn.op == 'call_function' and isinstance(pn.target, torch._ops.OpOverload):
        args_schema = pn.target._schema.arguments

        def get_all_arguments(orig_args, orig_kwargs):
            all_args = []
            for (i, schema) in enumerate(args_schema):
                if schema.name in orig_kwargs:
                    all_args.append(orig_kwargs[schema.name])
                elif not schema.kwarg_only and i < len(orig_args):
                    all_args.append(orig_args[i])
                else:
                    all_args.append(schema.default_value)
            return all_args
        pn_args = get_all_arguments(pn.args, pn.kwargs)
        gn_args = get_all_arguments(gn.args, gn.kwargs)
    elif len(pn.args) == len(gn.args) and list(pn.kwargs.keys()) == list(gn.kwargs.keys()):
        pn_args = list(pn.args)
        gn_args = list(gn.args)
        pn_args.extend(list(pn.kwargs.values()))
        gn_args.extend(list(gn.kwargs.values()))
    else:
        match_found = False
    match_found = match_found and pn_args is not None and (gn_args is not None) and _match_args(pn_args, gn_args)
    if not match_found:
        match = copy.copy(saved_match)
        return False
    return True

@staticmethod
def _get_exc_class_and_code(exc_class_or_code: type[Exception] | int) -> tuple[type[Exception], int | None]:
    """Get the exception class being handled. For HTTP status codes
        or ``HTTPException`` subclasses, return both the exception and
        status code.

        :param exc_class_or_code: Any exception class, or an HTTP status
            code as an integer.
        """
    exc_class: type[Exception]
    if isinstance(exc_class_or_code, int):
        try:
            exc_class = default_exceptions[exc_class_or_code]
        except KeyError:
            raise ValueError(f"'{exc_class_or_code}' is not a recognized HTTP error code. Use a subclass of HTTPException with that code instead.") from None
    else:
        exc_class = exc_class_or_code
    if <MASK>:
        raise TypeError(f'{exc_class!r} is an instance, not a class. Handlers can only be registered for Exception classes or HTTP error codes.')
    if not issubclass(exc_class, Exception):
        raise ValueError(f"'{exc_class.__name__}' is not a subclass of Exception. Handlers can only be registered for Exception classes or HTTP error codes.")
    if issubclass(exc_class, HTTPException):
        return (exc_class, exc_class.code)
    else:
        return (exc_class, None)

def in_bulk(self, id_list=None, *, field_name='pk'):
    """
        Return a dictionary mapping each of the given IDs to the object with
        that ID. If `id_list` isn't provided, evaluate the entire QuerySet.
        """
    if self.query.is_sliced:
        raise TypeError("Cannot use 'limit' or 'offset' with in_bulk().")
    if id_list is not None and (not id_list):
        return {}
    opts = self.model._meta
    unique_fields = [constraint.fields[0] for constraint in opts.total_unique_constraints if len(constraint.fields) == 1]
    if field_name != 'pk' and (not opts.get_field(field_name).unique) and (field_name not in unique_fields) and (self.query.distinct_fields != (field_name,)):
        raise ValueError("in_bulk()'s field_name must be a unique field but %r isn't." % field_name)
    qs = self

    def get_obj(obj):
        return obj
    if issubclass(self._iterable_class, ModelIterable):
        get_key = operator.attrgetter(field_name)
    elif <MASK>:
        if field_name not in self.query.values_select:
            qs = qs.values(field_name, *self.query.values_select)

            def get_obj(obj):
                del obj[field_name]
                return obj
        get_key = operator.itemgetter(field_name)
    elif issubclass(self._iterable_class, ValuesListIterable):
        try:
            field_index = self.query.values_select.index(field_name)
        except ValueError:
            field_index = 0
            if issubclass(self._iterable_class, NamedValuesListIterable):
                kwargs = {'named': True}
            else:
                kwargs = {}
                get_obj = operator.itemgetter(slice(1, None))
            qs = qs.values_list(field_name, *self.query.values_select, **kwargs)
        get_key = operator.itemgetter(field_index)
    elif issubclass(self._iterable_class, FlatValuesListIterable):
        if self.query.values_select == (field_name,):
            get_key = get_obj
        else:
            qs = qs.values_list(field_name, *self.query.values_select)
            get_key = operator.itemgetter(0)
            get_obj = operator.itemgetter(1)
    else:
        raise TypeError(f'in_bulk() cannot be used with {self._iterable_class.__name__}.')
    if id_list is not None:
        filter_key = '{}__in'.format(field_name)
        id_list = tuple(id_list)
        batch_size = connections[self.db].ops.bulk_batch_size([opts.pk], id_list)
        if batch_size and batch_size < len(id_list):
            results = ()
            for offset in range(0, len(id_list), batch_size):
                batch = id_list[offset:offset + batch_size]
                results += tuple(qs.filter(**{filter_key: batch}))
            qs = results
        else:
            qs = qs.filter(**{filter_key: id_list})
    else:
        qs = qs._chain()
    return {get_key(obj): get_obj(obj) for obj in qs}

def _post_plot_logic(self, ax: Axes, data) -> None:
    LinePlot._post_plot_logic(self, ax, data)
    is_shared_y = len(list(ax.get_shared_y_axes())) > 0
    if self.ylim is None and (not is_shared_y):
        if (data >= 0).all().all():
            ax.set_ylim(0, None)
        elif <MASK>:
            ax.set_ylim(None, 0)

@classmethod
def convert(cls, style_dict, num_format_str=None) -> dict[str, Any]:
    """
        converts a style_dict to an xlsxwriter format dict

        Parameters
        ----------
        style_dict : style dictionary to convert
        num_format_str : optional number format string
        """
    props = {}
    if num_format_str is not None:
        props['num_format'] = num_format_str
    if style_dict is None:
        return props
    if 'borders' in style_dict:
        style_dict = style_dict.copy()
        style_dict['border'] = style_dict.pop('borders')
    for (style_group_key, style_group) in style_dict.items():
        for (src, dst) in cls.STYLE_MAPPING.get(style_group_key, []):
            if dst in props:
                continue
            v = style_group
            for k in src:
                try:
                    v = v[k]
                except (KeyError, TypeError):
                    break
            else:
                props[dst] = v
    if isinstance(props.get('pattern'), str):
        props['pattern'] = 0 if props['pattern'] == 'none' else 1
    for k in ['border', 'top', 'right', 'bottom', 'left']:
        if isinstance(props.get(k), str):
            try:
                props[k] = ['none', 'thin', 'medium', 'dashed', 'dotted', 'thick', 'double', 'hair', 'mediumDashed', 'dashDot', 'mediumDashDot', 'dashDotDot', 'mediumDashDotDot', 'slantDashDot'].index(props[k])
            except ValueError:
                props[k] = 2
    if isinstance(props.get('font_script'), str):
        props['font_script'] = ['baseline', 'superscript', 'subscript'].index(props['font_script'])
    if isinstance(props.get('underline'), str):
        props['underline'] = {'none': 0, 'single': 1, 'double': 2, 'singleAccounting': 33, 'doubleAccounting': 34}[props['underline']]
    if <MASK>:
        props['valign'] = 'vcenter'
    return props

@override
def reducer_override(self, obj: object) -> tuple[Callable[..., Any], tuple[Any, ...]]:
    if <MASK>:
        return _TensorPickleData.reduce_helper(self, obj)
    elif isinstance(obj, torch.fx.GraphModule):
        return _GraphModulePickleData.reduce_helper(self, obj)
    elif isinstance(obj, (torch._ops.OperatorBase, torch._ops.OpOverloadPacket)):
        return _OpPickleData.reduce_helper(self, obj)
    elif isinstance(obj, ShapeEnv):
        return _ShapeEnvPickleData.reduce_helper(self, obj)
    elif isinstance(obj, torch.SymInt):
        return _SymNodePickleData.reduce_helper(self, obj)
    elif isinstance(obj, torch._guards.TracingContext):
        return _TracingContextPickleData.reduce_helper(self, obj)
    else:
        assert not isinstance(obj, torch.fx.Node)
        if (reduce := _TorchNumpyPickleData.reduce_helper(self, obj)):
            return reduce
        return NotImplemented

def _check_for_seq_len_0_nested(params: SDPAParams, debug=False) -> bool:
    q_is_safe = _check_for_seq_len_0_and_consistent_head_dim_nested_helper(params.query, 'query', debug) if params.query.is_nested else True
    if not q_is_safe:
        return False
    k_is_safe = _check_for_seq_len_0_and_consistent_head_dim_nested_helper(params.key, 'key', debug) if params.key.is_nested else True
    if not k_is_safe:
        return False
    v_is_safe = _check_for_seq_len_0_and_consistent_head_dim_nested_helper(params.value, 'value', debug) if params.value.is_nested else True
    if not v_is_safe:
        return False
    q_num_heads = params.query.size(1)
    k_num_heads = params.key.size(1)
    v_num_heads = params.value.size(1)
    same_num_heads = q_num_heads == k_num_heads and q_num_heads == v_num_heads
    if <MASK>:
        if params.query.requires_grad or params.key.requires_grad or params.value.requires_grad:
            if debug:
                log.warning('Both fused kernels do not support training with broadcasted NT inputs.')
            return False
        return _try_broadcast_param_size(q_num_heads, k_num_heads, v_num_heads, 'num heads', debug)
    return True

def __init__(self, data):
    """
        Populate the initial data using __setitem__ to ensure values are
        correctly encoded.
        """
    self._store = {}
    if <MASK>:
        for (header, value) in self._unpack_items(data):
            self[header] = value

def annotate_split_points(mod: torch.nn.Module, spec: dict[str, SplitPoint]):
    for (qualname, split_type) in spec.items():
        atoms = qualname.split('.')
        predecessor_module = mod
        for (i, atom) in enumerate(atoms[:-1]):
            try:
                predecessor_module = getattr(predecessor_module, atom)
            except AttributeError as e:
                raise AttributeError(f"Specified target {qualname} referenced nonexistent module {'.'.join(atoms[:i + 1])}") from e
        mod_to_wrap = getattr(predecessor_module, atoms[-1])
        mod_to_wrap._orig_forward = mod_to_wrap.forward
        if split_type == SplitPoint.BEGINNING:
            mod_to_wrap.forward = MethodType(_split_before_forward, mod_to_wrap)
        elif <MASK>:
            mod_to_wrap.forward = MethodType(_split_after_forward, mod_to_wrap)
        else:
            raise ValueError('Unknown split point type.')

def gen_foreach_derivativeinfo(foreach_function: NativeFunction, functional_info_by_signature: dict[FunctionSchema, dict[str, DifferentiabilityInfo]], non_functional_info_by_signature: dict[FunctionSchema, dict[str, DifferentiabilityInfo]], dispatch_key: str='Default') -> tuple[DifferentiabilityInfo | None, bool]:
    """Generate DifferentiabilityInfo for out-place foreach function, return the existing one for in-place.

    The second return value indicates whether the info is generated in this function.
    """
    ref_diff_info: DifferentiabilityInfo | None = None
    for (function_schema, diff_info) in functional_info_by_signature.items():
        if not is_reference_for_foreach(foreach_function, function_schema):
            continue
        ref_diff_info = diff_info[dispatch_key]
        if ref_diff_info is not None:
            break
