def _overload_method(func):
    _check_overload_body(func)
    qual_name = _qualified_name(func)
    global _overloaded_methods
    class_name_map = _overloaded_methods.get(qual_name)
    if class_name_map is None:
        class_name_map = {}
        _overloaded_methods[qual_name] = class_name_map
    (class_name, line_no) = get_class_name_lineno(func)
    method_overloads = class_name_map.get(class_name)
    if <MASK>:
        method_overloads = []
        class_name_map[class_name] = method_overloads
        _overloaded_method_class_fileno[qual_name, class_name] = line_no
    else:
        existing_lineno = _overloaded_method_class_fileno[qual_name, class_name]
        if existing_lineno != line_no:
            raise RuntimeError('Cannot currently overload the same method name in two different classes with the same name in the same module')
    method_overloads.append(func)
    return func

def _rows_to_cols(self, content: list[list[Scalar]]) -> list[np.ndarray]:
    col_len = self.num_original_columns
    if self._implicit_index:
        col_len += len(self.index_col)
    max_len = max((len(row) for row in content))
    if max_len > col_len and self.index_col is not False and (self.usecols is None):
        footers = self.skipfooter if self.skipfooter else 0
        bad_lines = []
        iter_content = enumerate(content)
        content_len = len(content)
        content = []
        for (i, _content) in iter_content:
            actual_len = len(_content)
            if actual_len > col_len:
                if callable(self.on_bad_lines):
                    new_l = self.on_bad_lines(_content)
                    if new_l is not None:
                        new_l = cast(list[Scalar], new_l)
                        if len(new_l) > col_len:
                            row_num = self.pos - (content_len - i + footers)
                            bad_lines.append((row_num, len(new_l), 'callable'))
                            new_l = new_l[:col_len]
                        content.append(new_l)
                elif self.on_bad_lines in (self.BadLineHandleMethod.ERROR, self.BadLineHandleMethod.WARN):
                    row_num = self.pos - (content_len - i + footers)
                    bad_lines.append((row_num, actual_len, 'normal'))
                    if self.on_bad_lines == self.BadLineHandleMethod.ERROR:
                        break
            else:
                content.append(_content)
        for (row_num, actual_len, source) in bad_lines:
            msg = f'Expected {col_len} fields in line {row_num + 1}, saw {actual_len}'
            if <MASK>:
                msg += ' from bad_lines callable'
            elif self.delimiter and len(self.delimiter) > 1 and (self.quoting != csv.QUOTE_NONE):
                reason = 'Error could possibly be due to quotes being ignored when a multi-char delimiter is used.'
                msg += '. ' + reason
            self._alert_malformed(msg, row_num + 1)
    zipped_content = list(lib.to_object_array(content, min_width=col_len).T)
    if self.usecols:
        assert self._col_indices is not None
        col_indices = self._col_indices
        if self._implicit_index:
            zipped_content = [a for (i, a) in enumerate(zipped_content) if i < len(self.index_col) or i - len(self.index_col) in col_indices]
        else:
            zipped_content = [a for (i, a) in enumerate(zipped_content) if i in col_indices]
    return zipped_content

def sgd(params: list[Tensor], d_p_list: list[Tensor], momentum_buffer_list: list[Optional[Tensor]], has_sparse_grad: bool=False, foreach: Optional[bool]=None, fused: Optional[bool]=None, grad_scale: Optional[Tensor]=None, found_inf: Optional[Tensor]=None, *, weight_decay: float, momentum: float, lr: float, dampening: float, nesterov: bool, maximize: bool):
    """Functional API that performs SGD algorithm computation.

    See :class:`~torch.optim.SGD` for details.
    """
    if foreach is None and fused is None:
        if not torch.jit.is_scripting():
            (fused, foreach) = _default_to_fused_or_foreach(params, differentiable=False, use_fused=False)
        else:
            foreach = False
            fused = False
    if foreach is None:
        foreach = False
    if fused is None:
        fused = False
    if foreach and torch.jit.is_scripting():
        raise RuntimeError('torch.jit.script not supported with foreach optimizers')
    if <MASK>:
        raise RuntimeError('torch.jit.script not supported with fused optimizers')
    if foreach and (not torch.jit.is_scripting()):
        func = _multi_tensor_sgd
    elif fused and (not torch.jit.is_scripting()):
        func = _fused_sgd
    else:
        func = _single_tensor_sgd
    func(params, d_p_list, momentum_buffer_list, weight_decay=weight_decay, momentum=momentum, lr=lr, dampening=dampening, nesterov=nesterov, has_sparse_grad=has_sparse_grad, maximize=maximize, grad_scale=grad_scale, found_inf=found_inf)

