    return container(name_or_buffer)

def _detect_fake_mode_from_gm(gm: torch.fx.GraphModule) -> Optional[torch._subclasses.fake_tensor.FakeTensorMode]:
    """
    For a given graph module, we look at the "val" of placeholder nodes to find the fake inputs.
    Additionally, if gm doesn't have placeholders, we further look at the "example_value" or "val" of other nodes.
    If no fake mode is found, we return None for fake_mode.
    """
    fake_inps: list[torch.Tensor] = []
    fake_vals: list[torch.Tensor] = []
    for node in gm.graph.nodes:
        if node.op == 'placeholder' and 'val' in node.meta:
            fake_val = node.meta['val']
            if <MASK>:
                fake_inps.append(fake_val)
        elif len(fake_inps) == 0 and ('example_value' in node.meta or 'val' in node.meta):
            fake_val = None
            if 'example_value' in node.meta:
                fake_val = node.meta['example_value']
            elif 'val' in node.meta:
                fake_val = node.meta['val']
            if fake_val is not None and isinstance(fake_val, torch.Tensor):
                fake_vals.append(fake_val)
    return detect_fake_mode(fake_inps + fake_vals)

def _compare(self, sp_t, reduction_axes, ndims, keep_dims, do_sum):
    densified = self.evaluate(sparse_ops.sparse_tensor_to_dense(sp_t))
    np_ans = densified
    if reduction_axes is None:
        if <MASK>:
            np_ans = np.sum(np_ans, keepdims=keep_dims)
        else:
            np_ans = np.max(np_ans, keepdims=keep_dims)
    else:
        if not isinstance(reduction_axes, list):
            reduction_axes = [reduction_axes]
        reduction_axes = np.array(reduction_axes).astype(np.int32)
        reduction_axes = (reduction_axes + ndims) % ndims
        reduction_axes.sort()
        for ra in reduction_axes.ravel()[::-1]:
            if do_sum:
                np_ans = np.sum(np_ans, axis=ra, keepdims=keep_dims)
            else:
                np_ans = np.max(np_ans, axis=ra, keepdims=keep_dims)
    with self.cached_session():
        if do_sum:
            tf_dense_ans = sparse_ops.sparse_reduce_sum(sp_t, reduction_axes, keep_dims)
        else:
            tf_dense_ans = sparse_ops.sparse_reduce_max(sp_t, reduction_axes, keep_dims)
        out_dense = self.evaluate(tf_dense_ans)
        if do_sum:
            tf_sparse_ans = sparse_ops.sparse_reduce_sum_sparse(sp_t, reduction_axes, keep_dims)
        else:
            tf_sparse_ans = sparse_ops.sparse_reduce_max_sparse(sp_t, reduction_axes, keep_dims)
        out_sparse = sparse_ops.sparse_tensor_to_dense(tf_sparse_ans)
    self.assertAllClose(np_ans, out_dense)
    self.assertAllClose(np_ans, out_sparse)

def __init__(self, normalized_shape: _shape_t, eps: float=1e-05, elementwise_affine: bool=True, bias: bool=True, device=None, dtype=None) -> None:
    factory_kwargs = {'device': device, 'dtype': dtype}
    super().__init__()
    if isinstance(normalized_shape, numbers.Integral):
        normalized_shape = (normalized_shape,)
    self.normalized_shape = tuple(normalized_shape)
    self.eps = eps
    self.elementwise_affine = elementwise_affine
    if <MASK>:
        self.weight = Parameter(torch.empty(self.normalized_shape, **factory_kwargs))
        if bias:
            self.bias = Parameter(torch.empty(self.normalized_shape, **factory_kwargs))
        else:
            self.register_parameter('bias', None)
    else:
        self.register_parameter('weight', None)
        self.register_parameter('bias', None)
    self.reset_parameters()

