def _reshape_view_helper_core_alg(a: TensorLikeType, shape, allow_copy: bool) -> TensorLikeType:
    idx = 0
    a_ = a
    for length in shape:
        if idx >= a_.ndim:
            assert length == 1
            last_dim = a_.ndim - 1
            a_ = prims.split_dim(a_, last_dim, a_.shape[last_dim])
            idx = idx + 1
            continue
        if length == a_.shape[idx]:
            idx = idx + 1
            continue
        accum = a_.shape[idx]
        end = idx
        while accum % length != 0:
            end += 1
            accum *= a_.shape[end]
        if end != idx:
            (new_shape, _new_strides) = prims._collapse_view_helper(a_, idx, end, must_be_valid=None)
            if new_shape is None:
                if allow_copy:
                    return prims.reshape(a, shape)
                msg = f'Cannot view a tensor with shape {a.shape} and strides {a.stride()} as a tensor with shape {shape}!'
                raise ValueError(msg)
            a_ = flatten(a_, idx, end)
        if accum != length:
            a_ = prims.split_dim(a_, idx, length)
        idx = idx + 1
    while idx < a_.ndim:
        torch._check(a_.shape[idx] == 1, lambda : f'a.size({idx}) expected to be 1 but got {a_.shape[idx]}')
        a_ = squeeze(a_, idx)
    if <MASK>:
        return prims.view_of(a)
    else:
        return a_

def _parse_name(self, name):
    """Parses a Policy name into a compute and variable dtype.

    Args:
      name: The name of the policy:

    Returns:
      The (compute_dtype, variable_dtype) pair.
    """
    if name.endswith('_float32_vars'):
        error_msg = "Policies ending in '_float32_vars' have been removed from TensorFlow."
        if name in ('infer_float32_vars', 'infer_with_float32_vars'):
            error_msg += " Please use the 'mixed_float16' or 'mixed_bfloat16' policy instead."
        elif name == 'float16_with_float32_vars':
            error_msg += " Please use the 'mixed_float16' policy instead."
        elif name == 'bfloat16_with_float32_vars':
            error_msg += " Please use the 'mixed_bfloat16' policy instead."
        error_msg += " Got policy name: '%s'" % name
        raise ValueError(error_msg)
    if <MASK>:
        return ('float16', 'float32')
    elif name == 'mixed_bfloat16':
        return ('bfloat16', 'float32')
    elif name == '_infer':
        return (None, None)
    try:
        dtype = dtypes.as_dtype(name).name
    except TypeError:
        error = "Cannot convert value %s to a mixed precision Policy. Valid policies include 'mixed_float16', 'mixed_bfloat16', and the name of any dtype such as 'float32'." % (name,)
        raise ValueError(error)
    return (dtype, dtype)

def finalize_options(self):
    log.info('unifying config_fc, config, build_clib, build_ext, build commands --fcompiler options')
    build_clib = self.get_finalized_command('build_clib')
    build_ext = self.get_finalized_command('build_ext')
    config = self.get_finalized_command('config')
    build = self.get_finalized_command('build')
    cmd_list = [self, config, build_clib, build_ext, build]
    for a in ['fcompiler']:
        l = []
        for c in cmd_list:
            v = getattr(c, a)
            if v is not None:
                if not isinstance(v, str):
                    v = v.compiler_type
                if v not in l:
                    l.append(v)
        if not l:
            v1 = None
        else:
            v1 = l[0]
        if <MASK>:
            log.warn('  commands have different --%s options: %s, using first in list as default' % (a, l))
        if v1:
            for c in cmd_list:
                if getattr(c, a) is None:
                    setattr(c, a, v1)

def set_correction(unbiased: Optional[bool]=None, correction: Optional[NumberType]=None) -> float:
    if correction is not None and unbiased is not None:
        raise RuntimeError('cannot specify both correction and unbiased arguments')
    elif correction is None and unbiased is None:
        correction = 1.0
    elif correction is None and unbiased is not None:
        correction = 0.0 if unbiased is False else 1.0
    if not isinstance(correction, (IntLike, FloatLike)):
        raise ValueError('correction argument should be integer or float')
    if <MASK>:
        raise ValueError('correction argument should be non-negative')
    return sym_float(correction)

@biject_to.register(constraints.interval)
@biject_to.register(constraints.half_open_interval)
@transform_to.register(constraints.interval)
@transform_to.register(constraints.half_open_interval)
def _transform_to_interval(constraint):
    lower_is_0 = isinstance(constraint.lower_bound, _Number) and constraint.lower_bound == 0
    upper_is_1 = isinstance(constraint.upper_bound, _Number) and constraint.upper_bound == 1
    if <MASK>:
        return transforms.SigmoidTransform()
    loc = constraint.lower_bound
    scale = constraint.upper_bound - constraint.lower_bound
    return transforms.ComposeTransform([transforms.SigmoidTransform(), transforms.AffineTransform(loc, scale)])

def _DefaultGradYs(grad_ys, ys, colocate_gradients_with_ops, gradient_uid='__unsupported__'):
    """Fill in default values for grad_ys.

  Args:
    grad_ys: List of gradients, can contain None.
    ys: List of tensors.
    colocate_gradients_with_ops: If True, try colocating gradients with
      the corresponding op.
    gradient_uid: A unique identifier within the graph indicating
      which invocation of gradients is being executed. Used to cluster
      ops for compilation.

  Returns:
    A list of gradients to use, without None.

  Raises:
    ValueError: If sizes of gradients and inputs don't match
    TypeError: If type of any gradient is not valid for its input.
  """
    if len(grad_ys) != len(ys):
        raise ValueError(f'Length mismatch. Passed {len(grad_ys)} grad_ys for {len(ys)} ys')
    grad_ys = indexed_slices.convert_n_to_tensor_or_indexed_slices(grad_ys, name='grad_y')
    new_grad_ys = []
    for (i, (y, grad_y)) in enumerate(zip(ys, grad_ys)):
        with _maybe_colocate_with(y.op, gradient_uid, colocate_gradients_with_ops):
            if grad_y is None:
                if y.dtype.is_complex:
                    raise TypeError(f'Gradients of complex tensors ({y}) must set grad_ys (y.dtype = {dtypes.as_dtype(y.dtype).name})')
                new_grad_ys.append(array_ops.ones(array_ops.shape(y), dtype=y.dtype, name='grad_ys_%d' % i))
                continue
            if y.dtype.is_floating or y.dtype.is_integer:
                if <MASK>:
                    raise TypeError(f'Gradient type {dtypes.as_dtype(grad_y.dtype).name} generated for real or integer-valued tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be real or integer')
            elif y.dtype.is_complex:
                if not grad_y.dtype.is_complex:
                    raise TypeError(f'Gradient type {dtypes.as_dtype(grad_y.dtype).name} generated for complex-valued tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be real')
            elif y.dtype == dtypes.variant:
                if grad_y.dtype != dtypes.variant:
                    raise TypeError(f'Gradient type {dtypes.as_dtype(grad_y.dtype).name} generated for variant tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be variant')
            elif y.dtype == dtypes.resource:
                if grad_y.dtype == dtypes.resource:
                    raise TypeError(f'Input gradient {grad_y} for resource tensor {y} should not be a resource')
            else:
                raise TypeError(f'Tensor {y} with type {dtypes.as_dtype(y.dtype).name} must be numeric to obtain a default gradient')
            if isinstance(grad_y, indexed_slices.IndexedSlices):
                new_grad_ys.append(indexed_slices.IndexedSlices(indices=array_ops.identity(grad_y.indices, name='grad_ys_%d_indices' % i) if isinstance(grad_y.indices, tensor_lib.Tensor) else grad_y.indices, values=array_ops.identity(grad_y.values, name='grad_ys_%d_values' % i) if isinstance(grad_y.values, tensor_lib.Tensor) else grad_y.values, dense_shape=array_ops.identity(grad_y.dense_shape, name='grad_ys_%d_shape' % i) if isinstance(grad_y.dense_shape, tensor_lib.Tensor) else grad_y.dense_shape))
            else:
                new_grad_ys.append(array_ops.identity(grad_y, name='grad_ys_%d' % i))
    return new_grad_ys

def convert_data_format(data_format, ndim):
    if data_format == 'channels_last':
        if ndim == 3:
            return 'NWC'
        elif ndim == 4:
            return 'NHWC'
        elif <MASK>:
            return 'NDHWC'
        else:
            raise ValueError('Input rank not supported:', ndim)
    elif data_format == 'channels_first':
        if ndim == 3:
            return 'NCW'
        elif ndim == 4:
            return 'NCHW'
        elif ndim == 5:
            return 'NCDHW'
        else:
            raise ValueError('Input rank not supported:', ndim)
    else:
        raise ValueError('Invalid data_format:', data_format)

def __init__(self, op, data):
    assert isinstance(op, Op)
    if op is Op.INTEGER:
        assert isinstance(data, tuple) and len(data) == 2
        assert isinstance(data[0], int)
        assert isinstance(data[1], (int, str)), data
    elif op is Op.REAL:
        assert isinstance(data, tuple) and len(data) == 2
        assert isinstance(data[0], float)
        assert isinstance(data[1], (int, str)), data
    elif op is Op.COMPLEX:
        assert isinstance(data, tuple) and len(data) == 2
    elif op is Op.STRING:
        assert isinstance(data, tuple) and len(data) == 2
        assert isinstance(data[0], str) and data[0][::len(data[0]) - 1] in ('""', "''", '@@')
        assert isinstance(data[1], (int, str)), data
    elif op is Op.SYMBOL:
        assert hash(data) is not None
    elif op in (Op.ARRAY, Op.CONCAT):
        assert isinstance(data, tuple)
        assert all((isinstance(item, Expr) for item in data)), data
    elif op in (Op.TERMS, Op.FACTORS):
        assert isinstance(data, dict)
    elif op is Op.APPLY:
        assert isinstance(data, tuple) and len(data) == 3
        assert hash(data[0]) is not None
        assert isinstance(data[1], tuple)
        assert isinstance(data[2], dict)
    elif op is Op.INDEXING:
        assert isinstance(data, tuple) and len(data) == 2
        assert hash(data[0]) is not None
    elif op is Op.TERNARY:
        assert isinstance(data, tuple) and len(data) == 3
    elif op in (Op.REF, Op.DEREF):
        assert isinstance(data, Expr)
    elif <MASK>:
        assert isinstance(data, tuple) and len(data) == 3
    else:
        raise NotImplementedError(f'unknown op or missing sanity check: {op}')
    self.op = op
    self.data = data

def _inner(match):
    assert dtype in [torch.float32, torch.bfloat16]
    dequant_pattern_end_node = match.output_node()
    if dequant_pattern_end_node.target not in [quantized_decomposed.dequantize_per_tensor.default, quantized_decomposed.dequantize_per_tensor.tensor, prims.convert_element_type.default, aten.reshape.default]:
        return False
    if <MASK>:
        dequant_node = dequant_pattern_end_node.args[0] if dtype == torch.float32 else dequant_pattern_end_node.args[0].args[0]
    else:
        dequant_node = dequant_pattern_end_node if dtype == torch.float32 else dequant_pattern_end_node.args[0]
    if dequant_node.target in [quantized_decomposed.dequantize_per_tensor.default, quantized_decomposed.dequantize_per_tensor.tensor] and len(list(dequant_pattern_end_node.users)) > 1:
        return True
    return False

@property
def shard_mesh(self):
    mesh = self.mesh_info.mesh
    if mesh.ndim == 1:
        return mesh
    elif mesh.ndim == 2:
        if <MASK>:
            raise AssertionError('Expected mesh_dim_names to not be None')
        return mesh[mesh.mesh_dim_names[-1]]
    raise ValueError(f'Invalid mesh: {mesh}')

def handle(self, **options):
    self.verbosity = options['verbosity']
    self.interactive = options['interactive']
    app_label = options['app_label']
    start_migration_name = options['start_migration_name']
    migration_name = options['migration_name']
    no_optimize = options['no_optimize']
    squashed_name = options['squashed_name']
    include_header = options['include_header']
    try:
        apps.get_app_config(app_label)
    except LookupError as err:
        raise CommandError(str(err))
    loader = MigrationLoader(None)
    if <MASK>:
        raise CommandError("App '%s' does not have migrations (so squashmigrations on it makes no sense)" % app_label)
    migration = self.find_migration(loader, app_label, migration_name)
    migrations_to_squash = [loader.get_migration(al, mn) for (al, mn) in loader.graph.forwards_plan((migration.app_label, migration.name)) if al == migration.app_label]
    if start_migration_name:
        start_migration = self.find_migration(loader, app_label, start_migration_name)
        start = loader.get_migration(start_migration.app_label, start_migration.name)
        try:
            start_index = migrations_to_squash.index(start)
            migrations_to_squash = migrations_to_squash[start_index:]
        except ValueError:
            raise CommandError("The migration '%s' cannot be found. Maybe it comes after the migration '%s'?\nHave a look at:\n  python manage.py showmigrations %s\nto debug this issue." % (start_migration, migration, app_label))
    if self.verbosity > 0 or self.interactive:
        self.stdout.write(self.style.MIGRATE_HEADING('Will squash the following migrations:'))
        for migration in migrations_to_squash:
            self.stdout.write(' - %s' % migration.name)
        if self.interactive:
            answer = None
            while not answer or answer not in 'yn':
                answer = input('Do you wish to proceed? [y/N] ')
                if not answer:
                    answer = 'n'
                    break
                else:
                    answer = answer[0].lower()
            if answer != 'y':
                return
    operations = []
    dependencies = set()
    first_migration = True
    for smigration in migrations_to_squash:
        operations.extend(smigration.operations)
        for dependency in smigration.dependencies:
            if isinstance(dependency, SwappableTuple):
                if settings.AUTH_USER_MODEL == dependency.setting:
                    dependencies.add(('__setting__', 'AUTH_USER_MODEL'))
                else:
                    dependencies.add(dependency)
            elif dependency[0] != smigration.app_label or first_migration:
                dependencies.add(dependency)
        first_migration = False
    if no_optimize:
        if self.verbosity > 0:
            self.stdout.write(self.style.MIGRATE_HEADING('(Skipping optimization.)'))
        new_operations = operations
    else:
        if self.verbosity > 0:
            self.stdout.write(self.style.MIGRATE_HEADING('Optimizing...'))
        optimizer = MigrationOptimizer()
        new_operations = optimizer.optimize(operations, migration.app_label)
        if self.verbosity > 0:
            if len(new_operations) == len(operations):
                self.stdout.write('  No optimizations possible.')
            else:
                self.stdout.write('  Optimized from %s operations to %s operations.' % (len(operations), len(new_operations)))
    replaces = [(m.app_label, m.name) for m in migrations_to_squash]
    subclass = type('Migration', (migrations.Migration,), {'dependencies': dependencies, 'operations': new_operations, 'replaces': replaces})
    if start_migration_name:
        if squashed_name:
            (prefix, _) = start_migration.name.split('_', 1)
            name = '%s_%s' % (prefix, squashed_name)
        else:
            name = '%s_squashed_%s' % (start_migration.name, migration.name)
        new_migration = subclass(name, app_label)
    else:
        name = '0001_%s' % (squashed_name or 'squashed_%s' % migration.name)
        new_migration = subclass(name, app_label)
        new_migration.initial = True
    writer = MigrationWriter(new_migration, include_header)
    if os.path.exists(writer.path):
        raise CommandError(f'Migration {new_migration.name} already exists. Use a different name.')
    with open(writer.path, 'w', encoding='utf-8') as fh:
        fh.write(writer.as_string())
    run_formatters([writer.path], stderr=self.stderr)
    if self.verbosity > 0:
        self.stdout.write(self.style.MIGRATE_HEADING('Created new squashed migration %s' % writer.path) + '\n  You should commit this migration but leave the old ones in place;\n  the new migration will be used for new installs. Once you are sure\n  all instances of the codebase have applied the migrations you squashed,\n  you can delete them.')
        if writer.needs_manual_porting:
            self.stdout.write(self.style.MIGRATE_HEADING('Manual porting required') + '\n  Your migrations contained functions that must be manually copied over,\n  as we could not safely copy their implementation.\n  See the comment at the top of the squashed migration for details.')
            if shutil.which('black'):
                self.stdout.write(self.style.WARNING('Squashed migration couldn\'t be formatted using the "black" command. You can call it manually.'))

def _as_record_writer_options(self):
    """Convert to RecordWriterOptions for use with PyRecordWriter."""
    options = _pywrap_record_io.RecordWriterOptions(compat.as_bytes(self.get_compression_type_string(self.compression_type)))
    if self.flush_mode is not None:
        options.zlib_options.flush_mode = self.flush_mode
    if self.input_buffer_size is not None:
        options.zlib_options.input_buffer_size = self.input_buffer_size
    if self.output_buffer_size is not None:
        options.zlib_options.output_buffer_size = self.output_buffer_size
    if self.window_bits is not None:
        options.zlib_options.window_bits = self.window_bits
    if self.compression_level is not None:
        options.zlib_options.compression_level = self.compression_level
    if <MASK>:
        options.zlib_options.compression_method = self.compression_method
    if self.mem_level is not None:
        options.zlib_options.mem_level = self.mem_level
    if self.compression_strategy is not None:
        options.zlib_options.compression_strategy = self.compression_strategy
    return options

