def diff_meta(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
    if isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor):
        return ', '.join(diff_tensor_meta(_extract_tensor_metadata(lhs, include_contiguity=include_contiguity), _extract_tensor_metadata(rhs, include_contiguity=include_contiguity), check_grad=False))
    else:

        def _both_int_types(lhs, rhs):
            return isinstance(lhs, (int, torch.SymInt)) and isinstance(rhs, (int, torch.SymInt))

        def _both_tensor(lhs, rhs):
            return isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor)
        if <MASK>:
            return f'type: {lhs} vs {rhs}'
    return ''

def run(self):

    def args_to_win(cmdline):
        changed = False
        out = []
        for token in cmdline.split():
            if <MASK>:
                token = token[2:]
                changed = True
            elif token[:2] == '~/':
                token = '%HOMEPATH%\\' + token[2:]
                changed = True
            elif token == 'make':
                token = 'make.bat'
                changed = True
            if '://' not in token and 'git' not in cmdline:
                out.append(token.replace('/', '\\'))
                changed = True
            else:
                out.append(token)
        if changed:
            return ' '.join(out)
        return cmdline

    def cmdline_to_win(line):
        if line.startswith('# '):
            return 'REM ' + args_to_win(line[2:])
        if line.startswith('$ # '):
            return 'REM ' + args_to_win(line[4:])
        if line.startswith('$ ./manage.py'):
            return 'manage.py ' + args_to_win(line[13:])
        if line.startswith('$ manage.py'):
            return 'manage.py ' + args_to_win(line[11:])
        if line.startswith('$ ./runtests.py'):
            return 'runtests.py ' + args_to_win(line[15:])
        if line.startswith('$ ./'):
            return args_to_win(line[4:])
        if line.startswith('$ python3'):
            return 'py ' + args_to_win(line[9:])
        if line.startswith('$ python'):
            return 'py ' + args_to_win(line[8:])
        if line.startswith('$ '):
            return args_to_win(line[2:])
        return None

    def code_block_to_win(content):
        bchanged = False
        lines = []
        for line in content:
            modline = cmdline_to_win(line)
            if modline is None:
                lines.append(line)
            else:
                lines.append(self.WIN_PROMPT + modline)
                bchanged = True
        if bchanged:
            return ViewList(lines)
        return None
    env = self.state.document.settings.env
    self.arguments = ['console']
    lit_blk_obj = super().run()[0]
    if env.app.builder.name not in ('djangohtml', 'json'):
        return [lit_blk_obj]
    lit_blk_obj['uid'] = str(env.new_serialno('console'))
    win_content = code_block_to_win(self.content)
    if win_content is None:
        lit_blk_obj['win_console_text'] = None
    else:
        self.content = win_content
        lit_blk_obj['win_console_text'] = super().run()[0].rawsource
    return [ConsoleNode(lit_blk_obj)]

def _generate_scatter_fallback(self, line: WrapperLine) -> None:
    assert isinstance(line, ScatterFallbackLine)
    ir_node = line.node
    assert ir.is_node_sequence(ir_node.inputs)
    (x, index, src) = [self._generate_buffer(t) for t in ir_node.inputs] + ([] if ir_node.src_is_tensor else [ir_node.constant_args[1]])
    args = (x, ir_node.constant_args[0], index, src)
    kwargs = {}
    if <MASK>:
        kwargs['reduce'] = reduce
    self._generate_fallback_call(ir_node, args, kwargs)

def setup(self, multiple_chunks):
    try:
        import pyarrow as pa
    except ImportError as err:
