def process_locale_dir(self, locale_dir, files):
    """
        Extract translatable literals from the specified files, creating or
        updating the POT file for a given locale directory.

        Use the xgettext GNU gettext utility.
        """
    build_files = []
    for translatable in files:
        if self.verbosity > 1:
            self.stdout.write('processing file %s in %s' % (translatable.file, translatable.dirpath))
        if <MASK>:
            continue
        build_file = self.build_file_class(self, self.domain, translatable)
        try:
            build_file.preprocess()
        except UnicodeDecodeError as e:
            self.stdout.write('UnicodeDecodeError: skipped file %s in %s (reason: %s)' % (translatable.file, translatable.dirpath, e))
            continue
        except BaseException:
            for build_file in build_files:
                build_file.cleanup()
            raise
        build_files.append(build_file)
    if self.domain == 'djangojs':
        args = ['xgettext', '-d', self.domain, '--language=JavaScript', '--keyword=gettext_noop', '--keyword=gettext_lazy', '--keyword=ngettext_lazy:1,2', '--keyword=pgettext:1c,2', '--keyword=npgettext:1c,2,3', '--output=-']
    elif self.domain == 'django':
        args = ['xgettext', '-d', self.domain, '--language=Python', '--keyword=gettext_noop', '--keyword=gettext_lazy', '--keyword=ngettext_lazy:1,2', '--keyword=pgettext:1c,2', '--keyword=npgettext:1c,2,3', '--keyword=pgettext_lazy:1c,2', '--keyword=npgettext_lazy:1c,2,3', '--output=-']
    else:
        return
    input_files = [bf.work_path for bf in build_files]
    with NamedTemporaryFile(mode='w+') as input_files_list:
        input_files_list.write('\n'.join(input_files))
        input_files_list.flush()
        args.extend(['--files-from', input_files_list.name])
        args.extend(self.xgettext_options)
        (msgs, errors, status) = popen_wrapper(args)
    if errors:
        if status != STATUS_OK:
            for build_file in build_files:
                build_file.cleanup()
            raise CommandError('errors happened while running xgettext on %s\n%s' % ('\n'.join(input_files), errors))
        elif self.verbosity > 0:
            self.stdout.write(errors)
    if msgs:
        if locale_dir is NO_LOCALE_DIR:
            for build_file in build_files:
                build_file.cleanup()
            file_path = os.path.normpath(build_files[0].path)
            raise CommandError("Unable to find a locale path to store translations for file %s. Make sure the 'locale' directory exists in an app or LOCALE_PATHS setting is set." % file_path)
        for build_file in build_files:
            msgs = build_file.postprocess_messages(msgs)
        potfile = os.path.join(locale_dir, '%s.pot' % self.domain)
        write_pot_file(potfile, msgs)
    for build_file in build_files:
        build_file.cleanup()

def check_func(self, func, headers=None, include_dirs=None, libraries=None, library_dirs=None, decl=False, call=False, call_args=None):
    self._check_compiler()
    body = []
    if decl:
        if type(decl) == str:
            body.append(decl)
        else:
            body.append('int %s (void);' % func)
    body.append('#ifdef _MSC_VER')
    body.append('#pragma function(%s)' % func)
    body.append('#endif')
    body.append('int main (void) {')
    if call:
        if <MASK>:
            call_args = ''
        body.append('  %s(%s);' % (func, call_args))
    else:
        body.append('  %s;' % func)
    body.append('  return 0;')
    body.append('}')
    body = '\n'.join(body) + '\n'
    return self.try_link(body, headers, include_dirs, libraries, library_dirs)

def optimize_inner(self, operations, app_label):
    """Inner optimization loop."""
    new_operations = []
    for (i, operation) in enumerate(operations):
        right = True
        for (j, other) in enumerate(operations[i + 1:]):
            result = operation.reduce(other, app_label)
            if isinstance(result, list):
                in_between = operations[i + 1:i + j + 1]
                if right:
                    new_operations.extend(in_between)
                    new_operations.extend(result)
                elif <MASK>:
                    new_operations.extend(result)
                    new_operations.extend(in_between)
                else:
                    new_operations.append(operation)
                    break
                new_operations.extend(operations[i + j + 2:])
                return new_operations
            elif not result:
                right = False
        else:
            new_operations.append(operation)
    return new_operations

@classmethod
def eval(cls, *args):
    if len(args) % 2 != 0:
        raise AssertionError(f'expected an even number of arguments, got {len(args)}')
    dim = len(args) // 2
    sizes = args[0:dim]
    strides = args[dim:]
    from torch.fx.experimental.symbolic_shapes import eval_is_non_overlapping_and_dense
    if all((isinstance(a, sympy.Integer) for a in args)):
        return eval_is_non_overlapping_and_dense([int(a) for a in sizes], [int(a) for a in strides])
    if <MASK>:
        if strides[0].is_Number and strides[0] == 1:
            return 1
        if sizes[0].is_Number and sizes[0] < 2:
            return 1
    if all((isinstance(a, sympy.Integer) for a in strides)):
        if dim == 0:
            raise AssertionError('dim must not be zero')
        (s_sizes, s_strides) = zip(*sorted(zip(sizes, strides), key=operator.itemgetter(1)))
        if all((isinstance(a, sympy.Integer) for a in s_sizes[:-1])):
            s_sizes = s_sizes[:-1] + (42,)
            return eval_is_non_overlapping_and_dense([int(a) for a in s_sizes], [int(a) for a in s_strides])
    return None

@property
def name(self):
    """Return the name of this Spatial Reference."""
    if self.projected:
        return self.attr_value('PROJCS')
    elif <MASK>:
        return self.attr_value('GEOGCS')
    elif self.local:
        return self.attr_value('LOCAL_CS')
    else:
        return None

def wrap_results_for_axis(self, results: ResType, res_index: Index) -> DataFrame | Series:
    """return the results for the rows"""
    if self.result_type == 'reduce':
        res = self.obj._constructor_sliced(results)
        res.index = res_index
        return res
    elif self.result_type is None and all((isinstance(x, dict) for x in results.values())):
        res = self.obj._constructor_sliced(results)
        res.index = res_index
        return res
    try:
        result = self.obj._constructor(data=results)
    except ValueError as err:
        if 'All arrays must be of the same length' in str(err):
            res = self.obj._constructor_sliced(results)
            res.index = res_index
            return res
        else:
            raise
    if not isinstance(results[0], ABCSeries):
        if len(result.index) == len(self.res_columns):
            result.index = self.res_columns
    if <MASK>:
        result.columns = res_index
    return result

def handle(self, *args, **options):
    if not settings.DEBUG and (not settings.ALLOWED_HOSTS):
        raise CommandError('You must set settings.ALLOWED_HOSTS if DEBUG is False.')
    self.use_ipv6 = options['use_ipv6']
    if <MASK>:
        raise CommandError('Your Python does not support IPv6.')
    self._raw_ipv6 = False
    if not options['addrport']:
        self.addr = ''
        self.port = self.default_port
    else:
        m = re.match(naiveip_re, options['addrport'])
        if m is None:
            raise CommandError('"%s" is not a valid port number or address:port pair.' % options['addrport'])
        (self.addr, _ipv4, _ipv6, _fqdn, self.port) = m.groups()
        if not self.port.isdigit():
            raise CommandError('%r is not a valid port number.' % self.port)
        if self.addr:
            if _ipv6:
                self.addr = self.addr[1:-1]
                self.use_ipv6 = True
                self._raw_ipv6 = True
            elif self.use_ipv6 and (not _fqdn):
                raise CommandError('"%s" is not a valid IPv6 address.' % self.addr)
    if not self.addr:
        self.addr = self.default_addr_ipv6 if self.use_ipv6 else self.default_addr
        self._raw_ipv6 = self.use_ipv6
    self.run(**options)

def _constant_eager_impl(ctx, value, dtype, shape, verify_shape) -> ops._EagerTensorBase:
    """Creates a constant on the current device."""
    t = convert_to_eager_tensor(value, ctx, dtype)
    if shape is None:
        return t
    shape = tensor_shape.as_shape(shape)
    if shape == t.shape:
        return t
    if verify_shape:
        raise TypeError(f'Expected Tensor {t} (converted from {value}) with shape {tuple(shape)}, but got shape {tuple(t.shape)}.')
    num_t = t.shape.num_elements()
    if num_t == shape.num_elements():
        return _eager_reshape(t, shape.as_list(), ctx)
    if <MASK>:
        if t.dtype == dtypes.bool:
            with ops.device('/device:CPU:0'):
                x = _eager_fill(shape.as_list(), _eager_identity(t, ctx), ctx)
            return _eager_identity(x, ctx)
        else:
            return _eager_fill(shape.as_list(), t, ctx)
    raise TypeError(f'Eager execution of tf.constant with unsupported shape. Tensor {t} (converted from {value}) has {num_t:d} elements, but got `shape` {shape} with {shape.num_elements()} elements).')

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName, symint: bool) -> NamedCType:
    if str(t) == 'Tensor?':
        tensor_type: OptionalCType = OptionalCType(BaseCType(tensorT))
        if mutable and (not local.use_const_ref_for_mutable_tensors()):
            return NamedCType(binds, MutRefCType(tensor_type))
        else:
            return NamedCType(binds, ConstRefCType(tensor_type))
    elif str(t) == 'Tensor?[]':
        return NamedCType(binds, ConstRefCType(ListCType(OptionalCType(BaseCType(tensorT)))))
    elif <MASK>:
        return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
    elif str(t) == 'Scalar?':
        return NamedCType(binds, ConstRefCType(OptionalCType(BaseCType(scalarT))))
    return cpp.argumenttype_type(t, mutable=mutable, binds=binds, symint=symint)

def __torch_dispatch__(self, func, types, args=(), kwargs=None):

    def bitwise_equal(lhs, rhs):
        if lhs.is_quantized:
            return torch.equal(lhs, rhs)
        else:
            return torch.allclose(lhs, rhs, equal_nan=True)

    def has_mutated(before, after, md):
        are_tensors = type(before) is torch.Tensor and type(after) is torch.Tensor
        if are_tensors and before.layout != torch.sparse_csr and (after.layout != torch.sparse_csr):
            return not (before.size() == after.size() and bitwise_equal(before, after) and (md[0] == after.stride()) and (md[1] == after._typed_storage()._cdata))
        return False

    def has_aliased(lhs, rhs):
        try:
            return torch._C._overlaps(lhs, rhs)
        except Exception as exception:
            if str(exception).startswith('Cannot inspect value of type '):
                return False
            else:
                raise exception

    def standardize_name(name):
        return name if name != 'self' else 'input'

    def unwrap(e):
        if <MASK>:
            try:
                return e.elem
            except AttributeError:
                return e
        return e

    def parse_metadata(e):
        if isinstance(e, torch.Tensor):
            if type(e) is not torch.Tensor:
                try:
                    current = e.elem
                    return (deepcopy(current.stride()), current._typed_storage()._cdata)
                except AttributeError:
                    return None
            elif e.layout != torch.sparse_csr:
                return (deepcopy(e.stride()), e._typed_storage()._cdata)
        return None
    self.ops.append(func._schema.name)
    pre_arguments = normalize_function(func, args, kwargs, normalize_to_only_use_kwargs=True).kwargs
    c_p_args = dict(zip(pre_arguments.keys(), clone_inputs(pre_arguments.values())))
    cloned_arguments = {name: tree_map(unwrap, c_p_args.get(name)) for name in c_p_args}
    cloned_metadata = {name: [parse_metadata(a) for a in pytree.tree_leaves(pre_arguments.get(name))] for name in pre_arguments}
    out = func(*args, **kwargs)
    arguments = {name: tree_map(unwrap, pre_arguments.get(name)) for name in pre_arguments}
    tuple_out = out if isinstance(out, tuple) else (out,)
    tuple_out = tree_map(unwrap, tuple_out)
    schema_info = SchemaInfo(func._schema)
    schema_info.add_argument_values(pre_arguments)
    for i in range(len(func._schema.arguments)):
        arg = func._schema.arguments[i]
        name = standardize_name(arg.name)
        if arguments.get(name) is not None:
            before = cloned_arguments.get(name)
            md = cloned_metadata.get(name)
            after = arguments.get(name)
            for j in range(len(tuple_out)):
                unsafe_ops = ('aten::_unsafe_view', 'aten::unsafe_split')
                if has_aliased(tuple_out[j], after) and func._schema.name not in unsafe_ops:
                    if not schema_info.may_contain_alias(SchemaArgument(SchemaArgType.output, j), SchemaArgument(SchemaArgType.input, i)):
                        raise RuntimeError(f'Argument {name} is not defined to alias output but was aliasing')
                    else:
                        self.aliasing.append(Aliasing(func._schema.name, name, f'output_{j}'))
                if after is tuple_out[j] and isinstance(after, torch.Tensor):
                    if not schema_info.is_mutable(SchemaArgument(SchemaArgType.input, i)) and func not in [torch.ops.aten.lift.default, torch.ops.aten.lift_fresh.default]:
                        raise RuntimeError(f'Dispatcher operators below autograd are not allowed to directly return inputs.\nHowever, we found that `outputs[{str(j)}] is {name}')
            if any((has_mutated(a, b, c) for (a, b, c) in zip(pytree.tree_leaves(before), pytree.tree_leaves(after), md))):
                if not schema_info.is_mutable(SchemaArgument(SchemaArgType.input, i)):
                    raise RuntimeError(f'Argument {name} is not defined as mutable but was mutated')
                else:
                    self.mutated.append(Mutation(func._schema.name, name))
    for (i, j) in combinations(range(len(func._schema.returns)), 2):
        if has_aliased(tuple_out[i], tuple_out[j]):
            if not schema_info.may_contain_alias(SchemaArgument(SchemaArgType.output, i), SchemaArgument(SchemaArgType.output, j)):
                raise RuntimeError(f'Outputs {i} and {j} alias unexpectedly')
    return out

@generic_utils.default
def build(self, input_shape=None):
