@combinations.generate(strategy_with_var_policy())
def testInitializedToSameValueInsideEagerRun(self, distribution):
    if not context.executing_eagerly():
        self.skipTest('eager only')
    if <MASK>:
        self.skipTest('Test for more than 1 device per worker only.')
    v = [None]

    @def_function.function
    def step():

        def f():
            if v[0] is None:
                v[0] = variables_lib.Variable(random_ops.random_normal([]), synchronization=variables_lib.VariableSynchronization.ON_READ)
        distribution.run(f)
    context.set_global_seed(None)
    step()
    vals = self.evaluate(v[0].values)
    self.assertAllEqual(vals[0], vals[1])

def is_unsupported(o):
    """Checks whether an entity is supported by AutoGraph at all."""
    if <MASK>:
        logging.warning('{} appears to be decorated by wrapt, which is not yet supported by AutoGraph. The function will run as-is. You may still apply AutoGraph before the wrapt decorator.'.format(o))
        logging.log(2, 'Permanently allowed: %s: wrapt decorated', o)
        return True
    if _is_known_loaded_type(o, 'functools', '_lru_cache_wrapper'):
        logging.log(2, 'Permanently allowed: %s: lru_cache', o)
        return True
    if inspect_utils.isconstructor(o):
        logging.log(2, 'Permanently allowed: %s: constructor', o)
        return True
    if any((_is_of_known_loaded_module(o, m) for m in ('collections', 'pdb', 'copy', 'inspect', 're'))):
        logging.log(2, 'Permanently allowed: %s: part of builtin module', o)
        return True
    if hasattr(o, '__module__') and hasattr(o.__module__, '_IS_TENSORFLOW_PLUGIN'):
        logging.log(2, 'Permanently allowed: %s: TensorFlow plugin', o)
        return True
    return False

@functools.lru_cache(32)
def dtype_match(torch_dtype: Optional[torch.dtype], cutlass_dtype: 'cutlass_library.library.DataType') -> bool:
    assert try_import_cutlass()
    import cutlass_library
    if torch_dtype == torch.float:
        return cutlass_dtype == cutlass_library.library.DataType.f32 or cutlass_dtype == cutlass_library.library.DataType.tf32
    elif <MASK>:
        return cutlass_dtype == cutlass_library.library.DataType.f16
    elif torch_dtype == torch.bfloat16:
        return cutlass_dtype == cutlass_library.library.DataType.bf16
    elif torch_dtype == torch.int8:
        return cutlass_dtype == cutlass_library.library.DataType.s8
    elif torch_dtype == torch.uint8:
        return cutlass_dtype == cutlass_library.library.DataType.u8
    elif torch_dtype == torch.int32:
        return cutlass_dtype == cutlass_library.library.DataType.s32
    elif torch_dtype == torch.float8_e4m3fn:
        return cutlass_dtype == cutlass_library.library.DataType.e4m3
    else:
        return False

def _tensor_isinstance(tensor_var, tensor_type):

    def check_type(ty):
        if <MASK>:
            example_val = arg.as_proxy().node.meta['example_value']
            if is_traceable_wrapper_subclass(example_val) and ty is torch.nn.parameter.Parameter:
                return isinstance(example_val, ty)
            else:
                return issubclass(arg.python_type(), ty)
        dtypes = tensortype_to_dtype[ty]
        return arg.dtype in dtypes
    if type(tensor_type) is tuple:
        return any((check_type(ty) for ty in tensor_type))
    else:
        return check_type(tensor_type)

@property
def run_eagerly(self):
    """Settable attribute indicating whether the model should run eagerly.

    Running eagerly means that your model will be run step by step,
    like Python code. Your model might run slower, but it should become easier
    for you to debug it by stepping into individual layer calls.

    By default, we will attempt to compile your model to a static graph to
    deliver the best execution performance.

    Returns:
      Boolean, whether the model should run eagerly.
    """
    if self._run_eagerly is True and (not context.executing_eagerly()):
        raise ValueError('You can only set `run_eagerly=True` if eager execution is enabled.')
    if not self.dynamic:
        if <MASK>:
            return def_function.functions_run_eagerly()
        else:
            return self._run_eagerly
    else:
        if not context.executing_eagerly():
            raise ValueError('Your model contains layers that can only be successfully run in eager execution (layers constructed with `dynamic=True`). You must enable eager execution with `tf.enable_eager_execution()`.')
        if self._run_eagerly is False:
            raise ValueError('Your model contains layers that can only be successfully run in eager execution (layers constructed with `dynamic=True`). You cannot set `run_eagerly=False`.')
        return context.executing_eagerly()

def _torch_grad_reduce(fn):

    def grad_reduce(*args, **kwargs):
        if <MASK>:
            return _torch_reduce_all(fn)(args[0])
        (input, dim, keepdim, dtype) = _reduce_dim_args(*args, **kwargs)
        return _torch_reduce_dim(fn)(input, dim, keepdim, dtype)
    return grad_reduce

def render(self):
    """Render (thereby finalizing) the content of the response.

        If the content has already been rendered, this is a no-op.

        Return the baked response instance.
        """
    retval = self
    if not self._is_rendered:
        self.content = self.rendered_content
        for post_callback in self._post_render_callbacks:
            newretval = post_callback(retval)
            if <MASK>:
                retval = newretval
    return retval

@simple_wraps(fn)
def inner_fn(primals: list[FxValue], tangents: list[FxValue]) -> tuple[tuple[list[FxValue], list[Optional[Tensor]]], tuple[list[AOTOutput], list[Optional[AOTOutput]]]]:
    outs_descs = None
    if primals_descs is None:
        (outs, tangent_mask) = fn(*primals)
        assert not pytree.tree_any(lambda x: isinstance(x, AOTOutput), tangent_mask)
    else:
        ((outs, tangent_mask), (outs_descs, _)) = call_and_expect_output_descs(fn, primals)
    if joint_fn_handle and joint_fn_handle.post_forward:
        joint_fn_handle.post_forward(primals)
    assert len(tangent_mask) == len(outs)
    outs_to_grad = [o for (needs_tangent, o) in zip(tangent_mask, outs) if needs_tangent]
    assert len(outs_to_grad) == len(tangents)
    grad_primals: list[torch.Tensor] = []
    inputs_needs_grads = []
    for p in primals:
        if isinstance(p, Tensor) and p.requires_grad:
            inputs_needs_grads.append(True)
            assert isinstance(p, torch.Tensor)
            grad_primals.append(p)
        else:
            inputs_needs_grads.append(False)
    needed_outs = []
    needed_tangents = []
    for (out, tangent) in zip(outs_to_grad, tangents):
        if isinstance(out, Tensor) and out.requires_grad:
            assert isinstance(tangent, torch.Tensor), f'Expected tensor tangent, got {type(tangent)}'
            needed_outs.append(out if guard_or_true(sym_eq(out.shape, tangent.shape)) else out.view(tangent.shape))
            needed_tangents.append(tangent)
    setup_stacktrace_preservation_hooks([out.grad_fn for out in needed_outs])
    if config.functionalize_rng_ops:
        PhiloxStateTracker.mark_beginning_of_backward()
    backward_out: tuple[Tensor, ...] = ()
    if grad_primals:
        functional_tensor_mode = torch.utils._python_dispatch._detect_infra_mode(torch._C._TorchDispatchModeKey.FUNCTIONAL)
        if functional_tensor_mode is not None:
            functional_tensor_mode._tokens_forward_output = functional_tensor_mode._tokens
            functional_tensor_mode._tokens = {}
        with set_partitioner_tag_is_backward(), fx_traceback.preserve_node_meta(), ExitStack() as stack:
            backward_pass_autocast = torch._functorch.config.backward_pass_autocast
            if backward_pass_autocast == 'same_as_forward':
                pass
            elif <MASK>:
                stack.enter_context(disable_autocast())
            else:
                stack.enter_context(disable_autocast())
                assert isinstance(backward_pass_autocast, list)
                for kwargs in backward_pass_autocast:
                    assert isinstance(kwargs, dict)
                    stack.enter_context(torch.amp.autocast(**kwargs))
            if aot_config.no_tangents:
                assert len(needed_tangents) == 1 and needed_tangents[0].numel() == 1
                backward_out = torch.autograd.grad(needed_outs, grad_primals, allow_unused=True)
            else:
                backward_out = torch.autograd.grad(needed_outs, grad_primals, grad_outputs=needed_tangents, allow_unused=True)
    backward_out_iter = iter(backward_out)
    final_outs = (outs, [next(backward_out_iter) if i else None for i in inputs_needs_grads])
    if primals_descs is None:
        return final_outs
    assert outs_descs is not None
    return (final_outs, (outs_descs, [GradAOTOutput(desc) if i else None for (i, desc) in zip(inputs_needs_grads, primals_descs)]))

def __init__(self, attrs=None):
    if <MASK>:
        raise ValueError("%s doesn't support uploading multiple files." % self.__class__.__qualname__)
    if self.allow_multiple_selected:
        if attrs is None:
            attrs = {'multiple': True}
        else:
            attrs.setdefault('multiple', True)
    super().__init__(attrs)

def def_kernel(self, inputs: dict[str, ir.Buffer], outputs: dict[str, ir.Buffer], aliases: Optional[dict[str, str]]=None, function_name: str='', extra_sizevars: Optional[list[sympy.Expr]]=None, placeholder: str='<DEF_KERNEL>') -> str:
    if <MASK>:
        function_name = str(self.kernel_name)
    for (name, inp) in inputs.items():
        if inp is not None:
            self.args.input_buffers[inp.get_name()] = name
    for (name, out) in outputs.items():
        self.args.output_buffers[out.get_name()] = name
    if aliases is not None:
        for (alias, orig) in aliases.items():
            if orig in self.args.input_buffers:
                self.args.input_buffers[alias] = self.args.input_buffers[orig]
            if orig in self.args.output_buffers:
                self.args.output_buffers[alias] = self.args.output_buffers[orig]
    unique_sizevars = OrderedSet((s for input in inputs.values() if input is not None for sym in itertools.chain(input.get_size(), input.get_stride()) if isinstance(sym, sympy.Expr) for s in sym.free_symbols))
    unique_sizevars.update((s for sym in extra_sizevars or [] if isinstance(sym, sympy.Expr) for s in sym.free_symbols))
    unique_sizevars.update((s for output in outputs.values() for sym in itertools.chain(output.get_size(), output.get_stride()) if isinstance(sym, sympy.Expr) for s in sym.free_symbols))
    sizevars = sorted(unique_sizevars, key=str)
    for sizevar in sizevars:
        self.args.sizevars[sizevar] = f'k{sizevar}'

    def hook():
        if aliases is not None:
            for alias in aliases:
                if alias in self.args.input_buffers:
                    raise AssertionError(f'input_buffers cannot be removed: {alias}')
                if alias in self.args.output_buffers:
                    self.args.output_buffers[alias] = REMOVED
        (cpp_argdefs, _, _) = self.args.cpp_argdefs()
        return f"void {function_name}({', '.join(cpp_argdefs)})"
    assert placeholder not in self.render_hooks
    self.render_hooks[placeholder] = hook
    return placeholder

def __init__(self, input_shape=None, batch_size=None, dtype=None, input_tensor=None, sparse=None, name=None, ragged=None, type_spec=None, **kwargs):
    self._init_input_shape = input_shape
    self._init_batch_size = batch_size
    self._init_dtype = dtype
    self._init_sparse = sparse
    self._init_ragged = ragged
    self._init_type_spec = type_spec
    strategy = distribute_lib.get_strategy()
    if strategy and batch_size is not None and distributed_training_utils.global_batch_size_supported(strategy):
        if <MASK>:
            raise ValueError('The `batch_size` argument ({}) must be divisible by the number of replicas ({})'.format(batch_size, strategy.num_replicas_in_sync))
        batch_size = batch_size // strategy.num_replicas_in_sync
    if 'batch_input_shape' in kwargs:
        batch_input_shape = kwargs.pop('batch_input_shape')
        if input_shape and batch_input_shape:
            raise ValueError('Only provide the input_shape OR batch_input_shape argument to InputLayer, not both at the same time.')
        if batch_input_shape:
            batch_size = batch_input_shape[0]
            input_shape = batch_input_shape[1:]
    if kwargs:
        raise ValueError('Unrecognized keyword arguments:', kwargs.keys())
    if sparse and ragged:
        raise ValueError('Cannot set both sparse and ragged to True in a Keras input.')
    if not name:
        prefix = 'input'
        name = prefix + '_' + str(backend.get_uid(prefix))
    if not dtype:
        if input_tensor is None:
            dtype = backend.floatx()
        else:
            dtype = backend.dtype(input_tensor)
    elif input_tensor is not None and input_tensor.dtype != dtype:
        raise ValueError('`input_tensor.dtype` differs from `dtype`: %s vs. %s' % (input_tensor.dtype, dtype))
    super(InputLayer, self).__init__(dtype=dtype, name=name)
    self.built = True
    self.sparse = True if sparse else False
    self.ragged = True if ragged else False
    self.batch_size = batch_size
    self.supports_masking = True
    if isinstance(input_shape, tensor_shape.TensorShape):
        input_shape = tuple(input_shape.as_list())
    elif isinstance(input_shape, int):
        input_shape = (input_shape,)
    if type_spec is not None:
        args_that_must_be_none = [('(input_)shape', self._init_input_shape), ('batch_size', self._init_batch_size), ('dtype', self._init_dtype), ('input_tensor', input_tensor), ('sparse', self._init_sparse), ('ragged', self._init_ragged)]
        for (arg_name, arg) in args_that_must_be_none:
            _assert_other_arg_none(arg_name, arg)
        if not ops.executing_eagerly_outside_functions():
            raise ValueError('Creating Keras inputs from a type_spec is only supported when eager execution is enabled.')
        input_tensor = keras_tensor.keras_tensor_from_type_spec(type_spec)
        if isinstance(input_tensor, keras_tensor.SparseKerasTensor):
            self.sparse = True
        if isinstance(input_tensor, keras_tensor.RaggedKerasTensor):
            self.ragged = True
        self.is_placeholder = True
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    elif input_tensor is None:
        if input_shape is not None:
            batch_input_shape = (batch_size,) + tuple(input_shape)
        else:
            batch_input_shape = None
        graph = backend.get_graph()
        with graph.as_default():
            input_tensor = backend.placeholder(shape=batch_input_shape, dtype=dtype, name=self.name, sparse=sparse, ragged=ragged)
        self.is_placeholder = True
        self._batch_input_shape = batch_input_shape
    else:
        if ops.executing_eagerly_outside_functions():
            if not isinstance(input_tensor, keras_tensor.KerasTensor):
                input_tensor = keras_tensor.keras_tensor_from_tensor(input_tensor)
        elif not tf_utils.is_symbolic_tensor(input_tensor):
            raise ValueError('You should not pass an EagerTensor to `Input`. For example, instead of creating an InputLayer, you should instantiate your model and directly call it on your input.')
        self.is_placeholder = False
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    input_tensor._keras_mask = None
    node_module.Node(layer=self, outputs=input_tensor)
    if isinstance(input_tensor, keras_tensor.KerasTensor) or tf_utils.is_extension_type(input_tensor):
        self._type_spec = input_tensor._type_spec
    else:
        self._type_spec = tensor_spec.TensorSpec(shape=input_tensor.shape, dtype=input_tensor.dtype, name=self.name)

@unpack_zerodim_and_defer('__mul__')
def __mul__(self, other) -> Self:
    if is_scalar(other):
        if <MASK>:
            raise TypeError(f"Cannot multiply '{self.dtype}' by bool, explicitly cast to integers instead")
        result = self._ndarray * other
        if result.dtype.kind != 'm':
            raise TypeError(f'Cannot multiply with {type(other).__name__}')
        freq = None
        if self.freq is not None and (not isna(other)):
            freq = self.freq * other
            if freq.n == 0:
                freq = None
        return type(self)._simple_new(result, dtype=result.dtype, freq=freq)
    if not hasattr(other, 'dtype'):
        other = np.array(other)
    if other.dtype.kind == 'b':
        raise TypeError(f"Cannot multiply '{self.dtype}' by bool, explicitly cast to integers instead")
    if len(other) != len(self) and (not lib.is_np_dtype(other.dtype, 'm')):
        raise ValueError('Cannot multiply with unequal lengths')
    if is_object_dtype(other.dtype):
        arr = self._ndarray
        result = [arr[n] * other[n] for n in range(len(self))]
        result = np.array(result)
        return type(self)._simple_new(result, dtype=result.dtype)
    result = self._ndarray * other
    if result.dtype.kind != 'm':
        raise TypeError(f'Cannot multiply with {type(other).__name__}')
    return type(self)._simple_new(result, dtype=result.dtype)

def get_subpackage(self, subpackage_name, subpackage_path=None, parent_name=None, caller_level=1):
    """Return list of subpackage configurations.

        Parameters
        ----------
        subpackage_name : str or None
            Name of the subpackage to get the configuration. '*' in
            subpackage_name is handled as a wildcard.
        subpackage_path : str
            If None, then the path is assumed to be the local path plus the
            subpackage_name. If a setup.py file is not found in the
            subpackage_path, then a default configuration is used.
        parent_name : str
            Parent name.
        """
    if <MASK>:
        if subpackage_path is None:
            raise ValueError('either subpackage_name or subpackage_path must be specified')
        subpackage_name = os.path.basename(subpackage_path)
    l = subpackage_name.split('.')
    if subpackage_path is None and '*' in subpackage_name:
        return self._wildcard_get_subpackage(subpackage_name, parent_name, caller_level=caller_level + 1)
    assert '*' not in subpackage_name, repr((subpackage_name, subpackage_path, parent_name))
    if subpackage_path is None:
        subpackage_path = njoin([self.local_path] + l)
    else:
        subpackage_path = njoin([subpackage_path] + l[:-1])
        subpackage_path = self.paths([subpackage_path])[0]
    setup_py = njoin(subpackage_path, self.setup_name)
    if not self.options['ignore_setup_xxx_py']:
        if not os.path.isfile(setup_py):
            setup_py = njoin(subpackage_path, 'setup_%s.py' % subpackage_name)
    if not os.path.isfile(setup_py):
        if not self.options['assume_default_configuration']:
            self.warn('Assuming default configuration (%s/{setup_%s,setup}.py was not found)' % (os.path.dirname(setup_py), subpackage_name))
        config = Configuration(subpackage_name, parent_name, self.top_path, subpackage_path, caller_level=caller_level + 1)
    else:
        config = self._get_configuration_from_setup_py(setup_py, subpackage_name, subpackage_path, parent_name, caller_level=caller_level + 1)
    if config:
        return [config]
    else:
        return []

def get_compiler_abi_compatibility_and_version(compiler) -> tuple[bool, TorchVersion]:
    """
    Determine if the given compiler is ABI-compatible with PyTorch alongside its version.

    Args:
        compiler (str): The compiler executable name to check (e.g. ``g++``).
            Must be executable in a shell process.

    Returns:
        A tuple that contains a boolean that defines if the compiler is (likely) ABI-incompatible with PyTorch,
        followed by a `TorchVersion` string that contains the compiler version separated by dots.
    """
    if not _is_binary_build():
        return (True, TorchVersion('0.0.0'))
    if os.environ.get('TORCH_DONT_CHECK_COMPILER_ABI') in ['ON', '1', 'YES', 'TRUE', 'Y']:
        return (True, TorchVersion('0.0.0'))
    if not check_compiler_ok_for_platform(compiler):
        logger.warning(WRONG_COMPILER_WARNING, compiler, _accepted_compilers_for_platform()[0], sys.platform, _accepted_compilers_for_platform()[0])
        return (False, TorchVersion('0.0.0'))
    if <MASK>:
        return (True, TorchVersion('0.0.0'))
    try:
        if IS_LINUX:
            minimum_required_version = MINIMUM_GCC_VERSION
            compiler_info = subprocess.check_output([compiler, '-dumpfullversion', '-dumpversion'])
        else:
            minimum_required_version = MINIMUM_MSVC_VERSION
            compiler_info = subprocess.check_output(compiler, stderr=subprocess.STDOUT)
        match = re.search('(\\d+)\\.(\\d+)\\.(\\d+)', compiler_info.decode(*SUBPROCESS_DECODE_ARGS).strip())
        version = ['0', '0', '0'] if match is None else list(match.groups())
    except Exception:
        (_, error, _) = sys.exc_info()
        logger.warning('Error checking compiler version for %s: %s', compiler, error)
        return (False, TorchVersion('0.0.0'))
    numeric_version = [re.sub('\\D', '', v) for v in version]
    if tuple(map(int, numeric_version)) >= minimum_required_version:
        return (True, TorchVersion('.'.join(numeric_version)))
    compiler = f"{compiler} {'.'.join(numeric_version)}"
    logger.warning(ABI_INCOMPATIBILITY_WARNING, compiler)
    return (False, TorchVersion('.'.join(numeric_version)))

def _get_result_dtype(to_concat: Sequence[ArrayLike], non_empties: Sequence[ArrayLike]) -> tuple[bool, set[str], DtypeObj | None]:
    target_dtype = None
    dtypes = {obj.dtype for obj in to_concat}
    kinds = {obj.dtype.kind for obj in to_concat}
    any_ea = any((not isinstance(x, np.ndarray) for x in to_concat))
    if any_ea:
        if len(dtypes) != 1:
            target_dtype = find_common_type([x.dtype for x in to_concat])
            target_dtype = common_dtype_categorical_compat(to_concat, target_dtype)
    elif not len(non_empties):
        if len(kinds) != 1:
            if <MASK>:
                pass
            else:
                target_dtype = np.dtype(object)
                kinds = {'o'}
    else:
        target_dtype = np_find_common_type(*dtypes)
    return (any_ea, kinds, target_dtype)

def create_input(value_range: tuple[float, float], shape: Sequence[int], dtype: np.dtype, shuffle: bool=False) -> np.ndarray:
    size = np.prod(shape) if shape else 1
    result = np.linspace(value_range[0], value_range[1], size, dtype=dtype).reshape(shape)
    if <MASK>:
        np.random.shuffle(result)
    return result

def _check_repo_is_trusted(repo_owner, repo_name, owner_name_branch, trust_repo, calling_fn='load'):
    hub_dir = get_dir()
    filepath = os.path.join(hub_dir, 'trusted_list')
    if not os.path.exists(filepath):
        Path(filepath).touch()
    with open(filepath) as file:
        trusted_repos = tuple((line.strip() for line in file))
    trusted_repos_legacy = next(os.walk(hub_dir))[1]
    owner_name = '_'.join([repo_owner, repo_name])
    is_trusted = owner_name in trusted_repos or owner_name_branch in trusted_repos_legacy or repo_owner in _TRUSTED_REPO_OWNERS
    if trust_repo is None:
        if not is_trusted:
            warnings.warn(f"You are about to download and run code from an untrusted repository. In a future release, this won't be allowed. To add the repository to your trusted list, change the command to {calling_fn}(..., trust_repo=False) and a command prompt will appear asking for an explicit confirmation of trust, or {calling_fn}(..., trust_repo=True), which will assume that the prompt is to be answered with 'yes'. You can also use {calling_fn}(..., trust_repo='check') which will only prompt for confirmation if the repo is not already trusted. This will eventually be the default behaviour")
        return
    if trust_repo is False or (trust_repo == 'check' and (not is_trusted)):
        response = input(f'The repository {owner_name} does not belong to the list of trusted repositories and as such cannot be downloaded. Do you trust this repository and wish to add it to the trusted list of repositories (y/N)?')
        if response.lower() in ('y', 'yes'):
            if is_trusted:
                print('The repository is already trusted.')
        elif <MASK>:
            raise Exception('Untrusted repository.')
        else:
            raise ValueError(f'Unrecognized response {response}.')
    if not is_trusted:
        with open(filepath, 'a') as file:
            file.write(owner_name + '\n')

