@classmethod
def process_kernel(cls, kernel: _OpOverloads, *args: Any, **kwargs: Any) -> tuple[Any, list[Any], list[Any], Callable[[Any, Any], Any], Optional[dict[sympy.Symbol, pytree.KeyPath]]]:
    binded_args = {'args': args, 'kwargs': kwargs}
    (args_flat, args_spec) = pytree.tree_flatten(binded_args)
    is_arg_tensor = []
    tensor_args = []
    non_tensor_args: list[Any] = []
    for arg in args_flat:
        is_arg_tensor.append(isinstance(arg, IRNode) and (not isinstance(arg, GeneratorState)))
        if is_arg_tensor[-1]:
            tensor_args.append(arg)
        else:
            if isinstance(arg, Expr):
                arg = V.graph.sizevars.shape_env.create_symintnode(arg, hint=None)
            non_tensor_args.append(arg)

    def unflatten_args(new_tensor_args: Sequence[_T], new_non_tensor_args: Sequence[_T]) -> tuple[list[_T], dict[str, _T]]:
        result = []
        it_tensors = iter(new_tensor_args)
        it_non_tensors = iter(new_non_tensor_args)
        for is_tensor in is_arg_tensor:
            if is_tensor:
                result.append(next(it_tensors))
            else:
                result.append(next(it_non_tensors))
        r = pytree.tree_unflatten(result, args_spec)
        return (r.get('args', []), r.get('kwargs', {}))
    tensor_args = [cls.realize_input(x) for x in tensor_args]
    for x in tensor_args:
        if is_storage_and_layout(x):
            as_storage_and_layout(x, freeze=True)
    example_args: list[Union[torch.Tensor, torch._C.ScriptObject, FakeScriptObject, torch.Generator]] = []
    for x in tensor_args:
        if not isinstance(x, BaseView) and x.get_name() in V.graph.constants:
            example_args.append(V.graph.constants[x.get_name()])
        elif not isinstance(x, BaseView) and x.get_name() in V.graph.torchbind_constants:
            example_args.append(V.graph.torchbind_constants[x.get_name()])
        elif <MASK>:
            example_args.append(x.get_value())
        elif isinstance(x, torch._inductor.ir.GeneratorState):
            device_index = x.device.index
            assert x.device.type == 'cuda' and device_index is not None
            example_args.append(torch.cuda.default_generators[device_index].clone_state())
        else:
            example_args.append(ir_node_to_tensor(x, guard_shape=True))
    (new_args, new_kwargs) = unflatten_args(example_args, non_tensor_args)
    example_output = kernel(*new_args, **new_kwargs)
    unbacked_bindings: Optional[dict[sympy.Symbol, pytree.KeyPath]] = None
    if (shape_env := V.fake_mode.shape_env):
        node_meta_val = V.current_node.meta.get('val')
        ctx: AbstractContextManager[None] = nullcontext()
        if V.current_node.target == torch._higher_order_ops.effects.with_effects:
            node_meta_val = node_meta_val[1]
            ctx = _remove_effect_token_unbacked_bindings(V.current_node)
        with ctx:
            rebind_unbacked(shape_env, V.current_node, example_output)
        unbacked_bindings = compute_unbacked_bindings(shape_env, example_output, node_meta_val)
    example_out_li = [example_output] if not isinstance(example_output, (list, tuple)) else example_output
    for t in example_out_li:
        if isinstance(t, torch.Tensor) and t.is_sparse:
            msg = 'sparsity not handled. Please file issue for sparse inference weights.'
            if (stack_trace := V.graph.current_node.meta.get('stack_trace', None)):
                msg = f'{msg} Found from : \n {stack_trace}'
            V.graph.disable_cudagraphs_reason = msg
    return (example_output, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings)

@st.composite
def tensor(draw, shapes=None, elements=None, qparams=None, dtype=np.float32):
    if <MASK>:
        _shape = draw(shapes)
    else:
        _shape = draw(st.sampled_from(shapes))
    if qparams is None:
        if elements is None:
            elements = floats(-1000000.0, 1000000.0, allow_nan=False, width=32)
        X = draw(stnp.arrays(dtype=dtype, elements=elements, shape=_shape))
        assume(not (np.isnan(X).any() or np.isinf(X).any()))
        return (X, None)
    qparams = draw(qparams)
    if elements is None:
        (min_value, max_value) = _get_valid_min_max(qparams)
        elements = floats(min_value, max_value, allow_infinity=False, allow_nan=False, width=32)
    X = draw(stnp.arrays(dtype=dtype, elements=elements, shape=_shape))
    (scale, zp) = _calculate_dynamic_qparams(X, qparams[2])
    enforced_zp = _ENFORCED_ZERO_POINT.get(qparams[2], None)
    if enforced_zp is not None:
        zp = enforced_zp
    return (X, (scale, zp, qparams[2]))

def remove_noop_ops(graph: torch.fx.Graph):
    """
    Removes both operations that are essentially aten.clone and operations that are essentially aten.alias from the graph.
    """
    inputs = OrderedSet[torch.fx.Node]()
    input_storages = OrderedSet[int | None]()
    output_storages = OrderedSet[int | None]()
    for node in graph.find_nodes(op='placeholder'):
        inputs.add(node)
        input_storages.add(get_node_storage(node))
    output_node = next(iter(reversed(graph.nodes)))
    assert output_node.op == 'output'
    outputs = output_node.args[0]
    if not isinstance(outputs, (list, tuple)):
        outputs = (outputs,)
    for out in outputs:
        if isinstance(out, torch.fx.Node):
            output_storages.add(get_node_storage(out))
    for node in graph.nodes:
        if <MASK>:
            (cond, src_index) = noop_registry[node.target]
            if isinstance(src_index, int):
                src = node.args[src_index]
            else:
                src = src_index(node.args)
            if not isinstance(src, torch.fx.Node):
                continue
            node_storage = get_node_storage(node)
            src_storage = get_node_storage(src)
            node_is_view = node_storage == src_storage
            if not node_is_view and node_storage in output_storages and (src_storage in input_storages or src_storage in output_storages):
                continue
            if node_is_view and node in output_node.args and (src in inputs or src in output_node.args):
                continue
            (is_valid, args, kwargs) = get_fake_args_kwargs(node)
            if not is_valid:
                continue
            if same_meta(node, src) and cond(*args, **kwargs):
                node.replace_all_uses_with(src)
                graph.erase_node(node)

def _load_edges(self):
    """Adds edges from objects to other objects and functions."""
    for (node_id, object_proto) in self._iter_all_nodes():
        self._add_object_graph_edges(object_proto, node_id)
    if self._filtered_nodes is not None and 0 not in self._filtered_nodes:
        root = self.get(0)
        for node_path in self._node_filters:
            loaded_node = self._nodes[self._node_path_to_id[node_path]]
            path = node_path.split('.')
            current_node = root
            for name in path[1:-1]:
                if not hasattr(current_node, name):
                    setattr(current_node, name, self._recreate_base_user_object()[0])
                current_node = getattr(current_node, name)
            if <MASK>:
                setattr(current_node, path[-1], loaded_node)

def __init__(self, kernel: CompiledKernel) -> None:
    self.name = kernel.src.fn.__name__
    self.cubin_raw = kernel.asm.get('cubin', None)
    self.cubin_path = kernel._cubin_path
    self.arg_names = kernel.src.fn.arg_names
    self.declared_constexprs = kernel.src.fn.constexprs
    self.hash = kernel.hash
    if triton_knobs is None:
        launch_enter = kernel.__class__.launch_enter_hook
        launch_exit = kernel.__class__.launch_exit_hook
    else:
        launch_enter = triton_knobs.runtime.launch_enter_hook
        launch_exit = triton_knobs.runtime.launch_exit_hook

    def hook_is_empty(hook: Any) -> bool:
        if hook is None:
            return True
        if triton_knobs and (HookChain := getattr(triton_knobs, 'HookChain', None)) is not None and isinstance(hook, HookChain):
            return len(hook.calls) == 0
        return False
    if not hook_is_empty(launch_enter) or not hook_is_empty(launch_exit):
        raise NotImplementedError("We don't support launch enter or launch exit hooks")
    self.num_warps = kernel.metadata.num_warps
    self.shared = kernel.shared if hasattr(kernel, 'shared') else kernel.metadata.shared

    def needs_scratch_arg(scratch_name: str, param_name: str) -> bool:
        if hasattr(kernel.metadata, param_name):
            if getattr(kernel.metadata, param_name) > 0:
                raise NotImplementedError(f'{scratch_name} scratch not yet supported')
            return True
        return False
    self.has_global_scratch = needs_scratch_arg('Global', 'global_scratch_size')
    self.has_profile_scratch = needs_scratch_arg('Profile', 'profile_scratch_size')
    self.arg_tys = self.arg_ty_from_signature(kernel.src)
    self.function: int | None = None
    num_ctas = 1
    if <MASK>:
        num_ctas = kernel.num_ctas
    elif hasattr(kernel, 'metadata'):
        num_ctas = kernel.metadata.num_ctas
    if num_ctas != 1:
        raise NotImplementedError('Static cuda launcher only supports num_ctas == 1')

def _simulate_comms_compute(pipeline_order, stage_to_rank: Callable[[int], int], num_stages: int):
    """This function dry-run simulates the actions in the schedule from the perspective of all ranks, and flags
    any deadlocks caused by missing or misordered communications.  It also simulates any bubbles in time where a rank
    can not execute any action due to waiting for unmet dependencies.  The total number of simulator steps can be used
    as a metric for unit tests involving IR optimization passes as reordering and merging of IR can reduce the number
    of simulated steps.

    The simulation is not high-fidelity and does not model overlapping of compute and communication, or cuda streams.
    Future work may be to enhance this and model the compute time, comms overlap, and even memory.
    """
    pipeline_order = {rank: [a for a in pipeline_order[rank] if a is not None] for rank in sorted(pipeline_order)}
    _schedule: dict[int, list[_Action | None]] = {rank: [] for rank in sorted(pipeline_order)}
    _prev_ops_rank: dict[int, set[_Action]] = {rank: set() for rank in _schedule}

    def add_to_schedule(rank: int, action: Optional[_Action]):
        _schedule[rank].append(action)
        if action is not None:
            _prev_ops_rank[rank].add(action)

    def _ready_to_schedule(action: Optional[_Action]) -> bool:
        if action is None:
            return True
        stage_idx = action.stage_index
        prev_ops = _prev_ops_rank[stage_to_rank(stage_idx)]
        if action.computation_type == F:
            if <MASK>:
                return True
            elif _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_ops:
                return True
            elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_ops:
                return True
            return False
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
            if action.stage_index == num_stages - 1:
                return True
            if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_ops:
                return True
            if _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_ops:
                return True
            if _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_ops:
                return True
            return False
        elif action.computation_type == BACKWARD_WEIGHT:
            return True
        elif action.computation_type == SEND_F:
            expected_f = _Action(action.stage_index, F, action.microbatch_index)
            return expected_f in prev_ops
        elif action.computation_type == RECV_F:
            peer_stage_idx = stage_idx - 1
            expected_send = _Action(peer_stage_idx, SEND_F, action.microbatch_index)
            return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
        elif action.computation_type == SEND_B:
            expected_b = _Action(action.stage_index, BACKWARD_INPUT, action.microbatch_index)
            expected_bw = _Action(action.stage_index, FULL_BACKWARD, action.microbatch_index)
            return expected_b in prev_ops or expected_bw in prev_ops
        elif action.computation_type == RECV_B:
            peer_stage_idx = stage_idx + 1
            expected_send = _Action(peer_stage_idx, SEND_B, action.microbatch_index)
            return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
        else:
            raise ValueError(f'Unsupported action type {action}')
    while pipeline_order:
        progress = False
        for rank in sorted(pipeline_order):
            if len(pipeline_order[rank]) == 0:
                continue
            action = pipeline_order[rank][0]
            if _ready_to_schedule(action):
                if action is not None:
                    add_to_schedule(rank, action)
                pipeline_order[rank].pop(0)
                progress = True
            else:
                add_to_schedule(rank, None)
        for i in sorted(pipeline_order, reverse=True):
            if len(pipeline_order[i]) == 0:
                del pipeline_order[i]
        for rank in sorted(pipeline_order):
            if len(pipeline_order[rank]) == 0:
                continue
            if _schedule[rank][-1] is not None:
                continue
            action = pipeline_order[rank][0]
            if _ready_to_schedule(action):
                if action is not None:
                    _schedule[rank][-1] = action
                    _prev_ops_rank[rank].add(action)
                pipeline_order[rank].pop(0)
        for i in sorted(pipeline_order, reverse=True):
            if len(pipeline_order[i]) == 0:
                del pipeline_order[i]
        if not progress:
            print('WIP comms schedule:\n', _format_pipeline_order(_schedule))
            for rank in pipeline_order:
                print(f'rank={rank!r} next action= {pipeline_order[rank][0]}')
            raise ValueError('Schedule is not progressing')
    return _schedule

def _reduce(v):
    """Reduce a single `PerReplica` object."""
    if reduction == 'concat' and _collective_all_reduce_multi_worker(strategy):
        return _multi_worker_concat(v, strategy)
    if <MASK>:
        return v
    elif reduction == 'first':
        return strategy.unwrap(v)[0]
    elif reduction == 'concat':
        if _is_tpu_multi_host(strategy):
            return _tpu_multi_host_concat(v, strategy)
        else:
            return concat(strategy.unwrap(v))
    else:
        raise ValueError('`reduction` must be "first" or "concat".')

