def _test_saved_model(use_placeholder, shapes_info, dtype):

    @test_util.run_without_tensor_float_32('Use FP32 in matmul')
    def test_saved_model(self: 'LinearOperatorDerivedClassTest'):
        with self.session(graph=ops.Graph()) as sess:
            sess.graph.seed = random_seed.DEFAULT_GRAPH_SEED
            if <MASK>:
                self.skipTest('Saving XLA model fails for empty model.')
            (operator, mat) = self.operator_and_matrix(shapes_info, dtype, use_placeholder=use_placeholder)
            x = self.make_x(operator, adjoint=False)

            class Model(module.Module):

                def __init__(self, init_x):
                    self.x = nest.map_structure(lambda x_: variables.Variable(x_, shape=None), init_x)

                @def_function.function(input_signature=(operator._type_spec,))
                def do_matmul(self, op):
                    return op.matmul(self.x)
            saved_model_dir = self.get_temp_dir()
            m1 = Model(x)
            sess.run([v.initializer for v in m1.variables])
            sess.run(m1.x.assign(m1.x + 1.0))
            save_model.save(m1, saved_model_dir)
            m2 = load_model.load(saved_model_dir)
            sess.run(m2.x.initializer)
            sess.run(m2.x.assign(m2.x + 1.0))
            y_op = m2.do_matmul(operator)
            y_mat = math_ops.matmul(mat, m2.x)
            (y_op_, y_mat_) = sess.run([y_op, y_mat])
            self.assertAC(y_op_, y_mat_)
    return test_saved_model

@functools.wraps(f)
def inner(*args, **kwargs):
    allowed_types = (Tensor, torch.types._Number) if include_non_tensor_args else (Tensor,)
    flat_args = [x for x in pytree.arg_tree_leaves(*args, **kwargs) if isinstance(x, allowed_types)]
    (computation_dtype, result_dtype) = utils.elementwise_dtypes(*flat_args, type_promotion_kind=type_promotion)

    def increase_prec(x):
        if isinstance(x, Tensor):
            return x.to(computation_dtype)
        else:
            return x

    def decrease_prec(x):
        if isinstance(x, Tensor):
            return x.to(result_dtype)
        else:
            return x
    r = f(*tree_map(increase_prec, args), **tree_map(increase_prec, kwargs))
    if <MASK>:
        return r
    else:
        return tree_map(decrease_prec, r)

def legacy_get_string(size_average: Optional[bool], reduce: Optional[bool], emit_warning: bool=True) -> str:
    warning = "size_average and reduce args will be deprecated, please use reduction='{}' instead."
    if size_average is None:
        size_average = True
    if <MASK>:
        reduce = True
    if size_average and reduce:
        ret = 'mean'
    elif reduce:
        ret = 'sum'
    else:
        ret = 'none'
    if emit_warning:
        warnings.warn(warning.format(ret))
    return ret

def to_real_tensor(e):
    if cls.fake_mode.is_our_fake(e):
        if e.dtype in cls._float_types:
            out = torch.rand_like(e, device=e.fake_device)
        else:
            out = torch.ones_like(e, device=e.fake_device)
        if <MASK>:
            out._coalesced_(e.is_coalesced())
        inp_impls[id(out)] = e
        return out
    return e

