    else:
        base_func_name = function_utils.get_func_name(self._func)
        if self._grad_func:
            base_func_name += '_%s' % self._grad_func.name
    kwargs_attr = _parse_kwargs_as_attrs(base_func_name, **self._extra_kwargs)
    if not temp_graph._c_graph:
        self._definition = graph_to_function_def.graph_to_function_def(temp_graph, temp_graph.get_operations(), temp_graph.inputs, temp_graph.outputs, out_names=self._out_names)
        for k in kwargs_attr:
            self._definition.attr[k].CopyFrom(kwargs_attr[k])
        self._hash_str = self._create_hash_str(self._definition.signature.input_arg, self._definition.signature.output_arg, self._definition.node_def)
        if not self._func_name:
            self._func_name = '_'.join([base_func_name, self._hash_str])
        self._definition.signature.name = self._func_name
        if self._func.__doc__:
            self._definition.signature.description = self._func.__doc__
        self._op_def = self._definition.signature
    else:
        output_names = [compat.as_bytes(x) for x in self._out_names] if self._out_names else []
        description = self._func.__doc__ or None
        with temp_graph._c_graph.get() as c_graph:
            c_func = c_api.TF_GraphToFunction_wrapper(c_graph, base_func_name, self._func_name is None, None, [t._as_tf_output() for t in temp_graph.inputs], [t._as_tf_output() for t in temp_graph.outputs], output_names, [], [], None, description)
        self._c_func = c_api_util.ScopedTFFunction(c_func, base_func_name)
        self._set_c_attrs(kwargs_attr)
        self._op_def = self.definition.signature
        if self._func_name:
            assert self._func_name == self._op_def.name
        else:
            self._func_name = compat.as_str(self._op_def.name)
    self._stateful_ops = [(op.name, op.type) for op in temp_graph.get_operations() if op._is_stateful]

def issue_guard(guard: ShapeGuard) -> None:
    expr = self.simplify(guard.expr)
    if expr in issued:
        return
    issued.add(expr)
    try:
        is_trivial = False
        if any((is_dim(source) for s in expr.free_symbols for source in symbol_to_source[s])):
            assert self.dim_constraints is not None
            is_trivial = self.dim_constraints.add(expr)
        for (exprs, printer, lang) in zip(all_exprs, printers, langs):
            guard_expr = printer.doprint(expr)
            if lang == 'verbose_python':
                guard_expr = f'{guard_expr}  # {guard.sloc}'
            exprs.append(guard_expr)
        self._add_target_expr(expr)
        if not is_trivial and len(expr.free_symbols) == 1:
            symbol = next(iter(expr.free_symbols))
            source = symbol_to_source[symbol][0]
            constraints = symbol_to_constraints[symbol]
            for c in constraints:
                if isinstance(c, StrictMinMaxConstraint):
                    var_with_range = self._render_range_for_constraint_violation(source, c)
                    msg = f'Not all values of {var_with_range} satisfy the generated guard {py_printer.doprint(expr)}.'
                    record_constraint_violation(c.warn_only, self._debug_name(source), msg)
                elif <MASK>:
                    pass
                else:
                    raise AssertionError(f'unrecognized constraint {c}')
    except Exception:
        self.log.warning('Failing guard allocated at %s', guard.sloc)
        raise

@functools.wraps(decomp_fn)
def wrapped(*args, **kwargs):
    args: list[Any] = list(args)
    kwargs: dict[str, Any] = dict(kwargs)
    unpacked = False
    if len(args) == 1 and isinstance(args[0], (list, tuple)):
        unpacked = True
        args = list(args[0])
    if <MASK>:
        assert not any((x == 'out' for x in kwargs.keys())), "out= ops aren't yet supported"
    (args, kwargs) = transform_args(args, kwargs, broadcast, type_promotion_kind, convert_input_to_bool)
    if unpacked:
        args = [args]
    out = decomp_fn(*args, **kwargs)
    validate_ir(out)
    return out

def check_meta_consistency(lhs_list: list[Union[torch.Tensor, torch.SymInt, int]], rhs_list: list[Union[torch.Tensor, torch.SymInt, int]], lhs_name: str, rhs_name: str, include_contiguity: bool=True) -> None:

    def diff_meta_pairs(lhs_list: list[Union[torch.Tensor, torch.SymInt, int]], rhs_list: list[Union[torch.Tensor, torch.SymInt, int]]) -> list[str]:

        def diff_meta(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
            if isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor):
                return ', '.join(diff_tensor_meta(_extract_tensor_metadata(lhs, include_contiguity=include_contiguity), _extract_tensor_metadata(rhs, include_contiguity=include_contiguity), check_grad=False))
            else:

                def _both_int_types(lhs, rhs):
                    return isinstance(lhs, (int, torch.SymInt)) and isinstance(rhs, (int, torch.SymInt))

                def _both_tensor(lhs, rhs):
                    return isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor)
                if not _both_int_types(lhs, rhs) and (not _both_tensor(lhs, rhs)):
                    return f'type: {lhs} vs {rhs}'
            return ''

        def diff_device(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
            if isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor):
                if rhs.device.type == lhs.device.type and rhs.device.index == lhs.device.index:
                    return ''
                else:
                    return 'device'
            return ''
        if len(lhs_list) != len(rhs_list):
            raise torch._dynamo.exc.UncapturedHigherOrderOpError(f'Expected {lhs_name} and {rhs_name} to have same number of outputs but got lhs:{lhs_list} and rhs:{rhs_list}')
        all_diffs = []
        for (i, (lhs, rhs)) in enumerate(zip(lhs_list, rhs_list)):
            if (diff := diff_meta(lhs, rhs)):
                all_diffs.append(f'pair[{i}] differ in {diff}, where lhs is {lhs} and rhs is {rhs}')
            if (diff := diff_device(lhs, rhs)):
                all_diffs.append(f'pair[{i}] differ in {diff}, where lhs is {lhs} and rhs is {rhs}')
        return all_diffs
    if <MASK>:
        diff_str = '\n'.join(all_diffs)
        raise torch._dynamo.exc.UncapturedHigherOrderOpError(f'Expected {lhs_name} and {rhs_name} to have same metadata but found:\n{diff_str}')

def worker_fn(self, checkpoint_dir, cluster_spec, strategy_option, input_arg='checkpoint', training_started_event=None, raise_app_error_on_worker=None, training_restarted=None, training_finished=None, termination_config=failure_handling.TerminationConfig(), api_wrapping_train=True):
    if strategy_option == 'MS':
        strategy = mirrored_strategy.MirroredStrategy()
    elif strategy_option == 'OneDevice':
        if config.list_physical_devices('GPU'):
            strategy = one_device_lib.OneDeviceStrategy(device='/gpu:0')
        else:
            strategy = one_device_lib.OneDeviceStrategy(device='/cpu:0')
    else:
        strategy = collective_all_reduce_strategy.CollectiveAllReduceStrategy()

    class Model(module.Module):

        def __init__(self):
            self.v = variables_lib.Variable(0.0, synchronization=variables_lib.VariableSynchronization.ON_WRITE, aggregation=variables_lib.VariableAggregation.SUM)

        @def_function.function(input_signature=[])
        def __call__(self):
            return self.v.read_value()
    with mock.patch.object(failure_handling_util, 'on_gcp', lambda : False):
        with strategy.scope():
            model = Model()
            fh_ckpt = tracking_util.Checkpoint(model=model)
            if input_arg == 'checkpoint':
                checkpoint_or_manager = fh_ckpt
            else:
                checkpoint_or_manager = _make_checkpoint_manager(fh_ckpt, checkpoint_dir, strategy.cluster_resolver)
            preemption_handler = failure_handling.PreemptionCheckpointHandler(strategy.cluster_resolver, checkpoint_or_manager, checkpoint_dir, termination_config)

        def distributed_train_step(current_epoch, current_step):

            @def_function.function
            def train_step():
                if cluster_spec and distribute_lib.get_distribution_strategy().cluster_resolver.task_id == raise_app_error_on_worker:
                    raise errors_impl.ResourceExhaustedError(node_def=None, op=None, message='Running out of resources')
                model.v.assign_add(constant_op.constant(1.0))
            strategy.run(train_step)
            if current_step == STEPS_PER_EPOCH - 1:
                logging.info('epoch %d finished', current_epoch)
        logging.info('Start training at %d', preemption_handler.total_run_calls)
        if training_restarted and training_restarted.is_set() and (not training_finished.is_set()):
            logging.info('training restarted')
            match_group = [re.search('.*ckpt-(\\d+).index', a_file) for a_file in gfile.ListDirectory(checkpoint_dir)]
            checkpoint_index = [a_match.group(1) for a_match in match_group if a_match]
            if getattr(termination_config, 'grace_period', 0):
                self.assertEqual(int(checkpoint_index[0]), 2)
            else:
                self.assertEqual(int(checkpoint_index[0]), 1)
        for epoch in range(preemption_handler.total_run_calls // STEPS_PER_EPOCH, EPOCHS_TO_RUN):
            for step in range(preemption_handler.total_run_calls % STEPS_PER_EPOCH, STEPS_PER_EPOCH):
                if api_wrapping_train:
                    preemption_handler.run(distributed_train_step, epoch, step)
                else:
                    preemption_handler.save_checkpoint_if_preempted()
                    distributed_train_step(epoch, step)
            if <MASK>:
                trigger_it = True
            else:
                trigger_it = False
            self._maybe_trigger_a_preemption(training_started_event, trigger_it)
        training_finished.set()
        logging.info('Training finished.')
        self.assertEqual(model.v.numpy(), strategy.num_replicas_in_sync * EPOCHS_TO_RUN * STEPS_PER_EPOCH)

def _validate_vocabulary(self):
    vocabulary = self.vocabulary
    if vocabulary is not None:
        if <MASK>:
            vocabulary = sorted(vocabulary)
        if not isinstance(vocabulary, Mapping):
            vocab = {}
            for (i, t) in enumerate(vocabulary):
                if vocab.setdefault(t, i) != i:
                    msg = 'Duplicate term in vocabulary: %r' % t
                    raise ValueError(msg)
            vocabulary = vocab
        else:
            indices = set(vocabulary.values())
            if len(indices) != len(vocabulary):
                raise ValueError('Vocabulary contains repeated indices.')
            for i in range(len(vocabulary)):
                if i not in indices:
                    msg = "Vocabulary of size %d doesn't contain index %d." % (len(vocabulary), i)
                    raise ValueError(msg)
        if not vocabulary:
            raise ValueError('empty vocabulary passed to fit')
        self.fixed_vocabulary_ = True
        self.vocabulary_ = dict(vocabulary)
    else:
        self.fixed_vocabulary_ = False

def get_default_device() -> 'torch.device':
    """Gets the default ``torch.Tensor`` to be allocated on ``device``"""
    global _GLOBAL_DEVICE_CONTEXT
    from torch.overrides import _get_current_function_mode_stack
    from torch.utils._device import DeviceContext

    def _get_device_with_index(device):
        if device.index is not None:
            return device
        else:
            return torch.tensor([]).device
    device_mode = next(filter(lambda mode: isinstance(mode, DeviceContext), reversed(_get_current_function_mode_stack())), None)
    if <MASK>:
        device = device_mode.device
        return _get_device_with_index(device)
    if hasattr(_GLOBAL_DEVICE_CONTEXT, 'device_context'):
        device = _GLOBAL_DEVICE_CONTEXT.device_context.device
        return _get_device_with_index(device)
    else:
        return torch.device('cpu')

@classmethod
def eval(cls, base: sympy.Integer, divisor: sympy.Integer, modulus: sympy.Integer) -> Optional[sympy.Basic]:
    if base == 0 or modulus == 1:
        return sympy.S.Zero
    if isinstance(base, sympy.Integer) and isinstance(divisor, sympy.Integer) and isinstance(modulus, sympy.Integer):
        return base // divisor % modulus
    try:
        if divisor != 1:
            gcd = sympy.gcd(base, divisor)
            if gcd != 1:
                return ModularIndexing(sympy.simplify(base / gcd), sympy.simplify(divisor / gcd), modulus)
    except sympy.PolynomialError:
        pass
    if isinstance(base, sympy.Add):
        new_terms: list[sympy.Integer] = []
        all_positive: bool = True
        for term in base.args:
            if <MASK>:
                if isinstance(term, sympy.Integer) and term < 0 or (isinstance(term, sympy.Mul) and isinstance(term.args[0], sympy.Integer) and (term.args[0] < 0)):
                    all_positive = False
                    break
                else:
                    new_terms.append(term)
        if len(new_terms) != len(base.args) and all_positive:
            return ModularIndexing(sum(new_terms), divisor, modulus)
    if isinstance(base, FloorDiv):
        return ModularIndexing(base.args[0], base.args[1] * divisor, modulus)
    return None

@classmethod
def eval(cls, a):
    if isinstance(a, (sympy.Integer, sympy.Float)):
        try:
            return sympy.Float(getattr(math, name)(float(a)))
        except OverflowError:
            return getattr(sympy, name)(a)
    elif <MASK>:
        if a is int_oo:
            a = sympy.oo
        if a is -int_oo:
            a = -sympy.oo
        if name == 'log2':
            return sympy.log(a, 2)
        return getattr(sympy, name)(a)
    return None

@register_make_test_function()
def make_conv2d_transpose_tests(options):
    """Make a set of tests to do transpose_conv."""
    test_parameters = [{'input_shape': [[1, 50, 54, 3]], 'filter_shape': [[1, 1, 8, 3], [1, 2, 8, 3], [1, 3, 8, 3], [1, 4, 8, 3]], 'output_shape': [[1, 100, 108, 8]], 'dynamic_output_shape': [True, False]}, {'input_shape': [[1, 16, 1, 512]], 'filter_shape': [[4, 1, 512, 512]], 'output_shape': [[1, 32, 1, 512]], 'dynamic_output_shape': [True, False]}, {'input_shape': [[1, 128, 128, 1]], 'filter_shape': [[4, 4, 1, 1]], 'output_shape': [[1, 256, 256, 1]], 'dynamic_output_shape': [True, False]}]

    def build_graph(parameters):
        """Build a transpose_conv graph given `parameters`."""
        input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=parameters['input_shape'])
        filter_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='filter', shape=parameters['filter_shape'])
        input_tensors = [input_tensor, filter_tensor]
        if <MASK>:
            output_shape = tf.compat.v1.placeholder(dtype=tf.int32, shape=[4])
            input_tensors.append(output_shape)
        else:
            output_shape = parameters['output_shape']
        out = tf.nn.conv2d_transpose(input_tensor, filter_tensor, output_shape=output_shape, padding='SAME', strides=(1, 2, 2, 1))
        return (input_tensors, [out])

    def build_inputs(parameters, sess, inputs, outputs):
        values = [create_tensor_data(np.float32, parameters['input_shape']), create_tensor_data(np.float32, parameters['filter_shape'])]
        if parameters['dynamic_output_shape']:
            values.append(np.array(parameters['output_shape']))
        return (values, sess.run(outputs, feed_dict=dict(zip(inputs, values))))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs)

def _check_set_wise_labels(y_true, y_pred, average, labels, pos_label):
    """Validation associated with set-wise metrics.

    Returns identified labels.
    """
    average_options = (None, 'micro', 'macro', 'weighted', 'samples')
    if average not in average_options and average != 'binary':
        raise ValueError('average has to be one of ' + str(average_options))
    (y_true, y_pred) = attach_unique(y_true, y_pred)
    (y_type, y_true, y_pred, _) = _check_targets(y_true, y_pred)
    present_labels = _tolist(unique_labels(y_true, y_pred))
    if average == 'binary':
        if y_type == 'binary':
            if pos_label not in present_labels:
                if <MASK>:
                    raise ValueError(f'pos_label={pos_label} is not a valid label. It should be one of {present_labels}')
            labels = [pos_label]
        else:
            average_options = list(average_options)
            if y_type == 'multiclass':
                average_options.remove('samples')
            raise ValueError("Target is %s but average='binary'. Please choose another average setting, one of %r." % (y_type, average_options))
    elif pos_label not in (None, 1):
        warnings.warn("Note that pos_label (set to %r) is ignored when average != 'binary' (got %r). You may use labels=[pos_label] to specify a single positive class." % (pos_label, average), UserWarning)
    return labels

def run_once(self) -> None:
    self._run_once = True
    if <MASK>:
        logger.info('Stopping watchdog thread...')
        self._watchdog_thread.join()
        self._watchdog_thread = None
    else:
        logger.info('No watchdog thread running, doing nothing')
    if os.path.exists(self._file_path):
