@register_graph_pattern(CallFunctionVarArgs(torch.unbind, users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('normalization_pass'))
@register_graph_pattern(CallMethodVarArgs('unbind', users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('normalization_pass'))
def normalize_unbind_default(match: Match, *args, **kwargs):
    node = match.nodes[0]
    graph = match.graph
    input = get_arg_value(node, 0, 'input')
    dim = get_arg_value(node, 1, 'dim')
    if dim is None:
        axis = node.kwargs.get('axis')
        if axis is not None:
            dim = axis
        else:
            dim = 0
    if <MASK>:
        log.debug("couldn't find unbind args")
        return
    if not is_node_meta_valid(input):
        log.debug('example value absent for node: %s', input)
        return
    ndim = input.meta['example_value'].ndim
    if dim < 0:
        dim += ndim
    with graph.inserting_after(node):
        new_node = graph.call_function(torch.unbind, args=(input,), kwargs={'dim': dim})
    node.replace_all_uses_with(new_node)
    new_node.meta.update(node.meta)
    graph.erase_node(node)
    counters[backend]['normalization_pass'] += 1

def get(self):
    """Creates a generator to extract data from the queue.

    Skip the data if it is `None`.

    Yields:
        The next element in the queue, i.e. a tuple
        `(inputs, targets)` or
        `(inputs, targets, sample_weights)`.
    """
    try:
        while self.is_running():
            inputs = self.queue.get(block=True).get()
            self.queue.task_done()
            if <MASK>:
                yield inputs
    except StopIteration:
        last_ones = []
        while self.queue.qsize() > 0:
            last_ones.append(self.queue.get(block=True))
        for f in last_ones:
            f.wait()
        last_ones = [future.get() for future in last_ones if future.successful()]
        for inputs in last_ones:
            if inputs is not None:
                yield inputs
    except Exception as e:
        self.stop()
        if 'generator already executing' in str(e):
            raise RuntimeError('Your generator is NOT thread-safe. Keras requires a thread-safe generator when `use_multiprocessing=False, workers > 1`. ')
        raise e

@final
def _call_cython_op(self, values: np.ndarray, *, min_count: int, ngroups: int, comp_ids: np.ndarray, mask: npt.NDArray[np.bool_] | None, result_mask: npt.NDArray[np.bool_] | None, initial: Any=0, **kwargs) -> np.ndarray:
    orig_values = values
    dtype = values.dtype
    is_numeric = dtype.kind in 'iufcb'
    is_datetimelike = dtype.kind in 'mM'
    if <MASK>:
        if mask is None:
            mask = isna(values)
    if is_datetimelike:
        values = values.view('int64')
        is_numeric = True
    elif dtype.kind == 'b':
        values = values.view('uint8')
    if values.dtype == 'float16':
        values = values.astype(np.float32)
    if self.how in ['any', 'all']:
        if dtype == object:
            if kwargs['skipna']:
                if mask is not None and mask.any():
                    values = values.copy()
                    values[mask] = True
        values = values.astype(bool, copy=False).view(np.int8)
        is_numeric = True
    values = values.T
    if mask is not None:
        mask = mask.T
        if result_mask is not None:
            result_mask = result_mask.T
    out_shape = self._get_output_shape(ngroups, values)
    func = self._get_cython_function(self.kind, self.how, values.dtype, is_numeric)
    values = self._get_cython_vals(values)
    out_dtype = self._get_out_dtype(values.dtype)
    result = maybe_fill(np.empty(out_shape, dtype=out_dtype))
    if self.kind == 'aggregate':
        counts = np.zeros(ngroups, dtype=np.int64)
        if self.how in ['idxmin', 'idxmax', 'min', 'max', 'mean', 'last', 'first', 'sum', 'median']:
            if self.how == 'sum':
                kwargs['initial'] = initial
            func(out=result, counts=counts, values=values, labels=comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, is_datetimelike=is_datetimelike, **kwargs)
        elif self.how in ['sem', 'std', 'var', 'ohlc', 'prod']:
            if self.how in ['std', 'sem']:
                kwargs['is_datetimelike'] = is_datetimelike
            func(result, counts, values, comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, **kwargs)
        elif self.how in ['any', 'all']:
            func(out=result, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            result = result.astype(bool, copy=False)
        elif self.how in ['skew', 'kurt']:
            func(out=result, counts=counts, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            if dtype == object:
                result = result.astype(object)
        else:
            raise NotImplementedError(f'{self.how} is not implemented')
    else:
        if self.how != 'rank':
            kwargs['result_mask'] = result_mask
        func(out=result, values=values, labels=comp_ids, ngroups=ngroups, is_datetimelike=is_datetimelike, mask=mask, **kwargs)
    if self.kind == 'aggregate' and self.how not in ['idxmin', 'idxmax']:
        if result.dtype.kind in 'iu' and (not is_datetimelike):
            cutoff = max(0 if self.how in ['sum', 'prod'] else 1, min_count)
            empty_groups = counts < cutoff
            if empty_groups.any():
                if result_mask is not None:
                    assert result_mask[empty_groups].all()
                else:
                    result = result.astype('float64')
                    result[empty_groups] = np.nan
    result = result.T
    if self.how not in self.cast_blocklist:
        res_dtype = self._get_result_dtype(orig_values.dtype)
        op_result = maybe_downcast_to_dtype(result, res_dtype)
    else:
        op_result = result
    return op_result

def indirect_assert(self, var, lower, upper, mask=None):
    assert isinstance(var, CppCSEVariable)
    assert var.dtype is not None
    if not var.is_vec:
        if isinstance(mask, CppCSEVariable) and mask.is_vec:
            mask = f'({mask}).all_masked()'
        return super().indirect_assert(var, lower, upper, mask)
    lower_scalar = lower
    upper_scalar = upper
    if <MASK>:
        lower = f'{self._get_vec_type(var.dtype)}({lower})'
    if upper:
        upper = f'{self._get_vec_type(var.dtype)}({upper})'
    if lower and upper:
        cond = f'({lower} <= {var}) & ({var} < {upper})'
        cond_print = f'{lower_scalar} <= {var} < {upper_scalar}'
    elif lower:
        cond = f'{lower} <= {var}'
        cond_print = f'{lower_scalar} <= {var}'
    else:
        assert upper
        cond = f'{var} < {upper}'
        cond_print = f'{var} < {upper_scalar}'
    cond = f'{self._get_mask_type(var.dtype)}({cond})'
    if mask:
        if not mask.is_vec:
            mask = f'{self._get_mask_type(var.dtype)}({mask})'
        cond = f'({cond}) | ~({mask})'
    if self.tail_size:
        cond = f'{self._get_mask_type(var.dtype)}::set({self._get_mask_type(var.dtype)}::from(1), ({cond}), {cexpr_index(self.tail_size)})'
    cond = f'({cond}).all_masked()'
    return f'{self.assert_function}({cond}, "index out of bounds: {cond_print}")'

def get_libc_version():
    import platform
    if <MASK>:
