def deserialize_input(self, inp: Argument) -> Any:
    value = inp.value
    typ_ = inp.type
    if typ_ == 'as_none':
        return None
    elif typ_ == 'as_tensor':
        return self.serialized_name_to_node[inp.as_tensor.name]
    elif typ_ == 'as_scalar_type':
        return _SERIALIZE_TO_TORCH_DTYPE[inp.as_scalar_type]
    elif typ_ == 'as_memory_format':
        return _SERIALIZE_TO_TORCH_MEMORY_FORMAT[inp.as_memory_format]
    elif typ_ == 'as_layout':
        return _SERIALIZE_TO_TORCH_LAYOUT[inp.as_layout]
    elif <MASK>:
        assert isinstance(value, GraphArgument)
        with self.save_graph_module():
            self.deserialize_graph(value.graph)
            submodule = ep._create_graph_module_for_export(self.module, self.graph)
        self.module.register_module(value.name, submodule)
        return self.graph.create_node('get_attr', value.name, name=value.name)
    elif typ_ == 'as_device':
        return deserialize_device(inp.as_device)
    elif typ_ == 'as_int':
        return inp.as_int
    elif typ_ == 'as_float':
        return inp.as_float
    elif typ_ == 'as_bool':
        return inp.as_bool
    elif typ_ == 'as_string':
        return inp.as_string
    elif typ_ == 'as_complex':
        return complex(inp.as_complex.real, inp.as_complex.imag)
    elif typ_ == 'as_sym_int':
        return self.deserialize_sym_argument(inp.as_sym_int)
    elif typ_ == 'as_sym_float':
        return self.deserialize_sym_argument(inp.as_sym_float)
    elif typ_ == 'as_sym_bool':
        return self.deserialize_sym_argument(inp.as_sym_bool)
    elif isinstance(value, list):
        if len(value) == 0:
            return []
        elif typ_ == 'as_tensors':
            result = [self.serialized_name_to_node[arg.name] for arg in value]
            return result
        elif typ_ in ('as_ints', 'as_floats', 'as_bools', 'as_strings'):
            return list(value)
        elif typ_ in ('as_sym_ints', 'as_sym_bools', 'as_sym_floats'):
            return [self.deserialize_sym_argument(arg) for arg in value]
        elif typ_ == 'as_optional_tensors':

            def deserialize_optional_tensor_args(a):
                if a.type == 'as_none':
                    return None
                elif a.type == 'as_tensor':
                    return self.serialized_name_to_node[a.value.name]
                else:
                    raise SerializeError(f'Unhandled argument {inp}')
            return list(map(deserialize_optional_tensor_args, value))
        else:
            raise SerializeError(f'Unhandled argument {inp}')
    elif typ_ == 'as_custom_obj':
        if inp.as_custom_obj.name in self.serialized_name_to_node:
            return self.serialized_name_to_node[inp.as_custom_obj.name]
        return self.constants[inp.as_custom_obj.name]
    elif typ_ == 'as_operator':
        return self.deserialize_operator(inp.as_operator)
    else:
        raise SerializeError(f'Unhandled argument {inp}')

def _match_literals(self, pn: Any, gn: Any, match: InternalMatch) -> bool:
    assert not (isinstance(pn, Node) and isinstance(gn, Node)), 'pn and gn cannot both be Node'
    if isinstance(pn, Node) and (not isinstance(gn, Node)):
        if pn.op == 'placeholder':
            if pn in match.nodes_map:
                return match.nodes_map[pn] == gn
            match.nodes_map[pn] = gn
            return True
        else:
            return False
    elif <MASK>:
        return False
    else:
        return type(gn) is type(pn) and gn == pn

def remove_fsdp2_unsharded_param_graph_input_usage(graph: torch.fx.Graph):
    """
    This FX graph pass replaces uses of FSDP2 unsharded params with their corresponding
    graph intermediates that were fsdp.copy_ into the unsharded params in the original graph.

    NOTE: Can only apply this pass to any of the FSDP2 unsharded params that have this pattern
    (or repetition of): `resize_(full) -> copy_ -> resize_(0)`. Because of this, for partial-graph case
    where `resize_(full) -> copy_` is in one graph and `resize_(0)` is in another graph, we can't
    remove these resize and copy ops and thus we will have worse performance there.

    In other words, "do we try to remove all the resize_(full) -> copy_ -> resize_(0) nodes for this unsharded param"
    is actually a per-unsharded-param decision, since for each unsharded param, we look at its resize sequence pattern
    (in `check_resize_pattern()`) to determine if its set of resize and copy nodes can be removed.
    """
    node_list = list(graph.nodes)
    graph_input_to_resized_to_full_node_idxes = defaultdict(list)
    graph_input_to_resized_to_0_node_idxes = defaultdict(list)
    for (idx, node) in enumerate(node_list):
        if node.op == 'call_function' and node.target == torch.ops.inductor.resize_storage_bytes_.default:
            assert node.args[0].op == 'placeholder', f'Resize can only operate on graph inputs, but got {node} which is resizing non-graph-input {node.args[0]}\n'
            graph_input = node.args[0]
            new_size = node.args[1]
            if new_size > 0:
                graph_input_to_resized_to_full_node_idxes[graph_input].append(idx)
            else:
                graph_input_to_resized_to_0_node_idxes[graph_input].append(idx)

    def check_resize_pattern(graph_input):
        resized_to_full_idxes = graph_input_to_resized_to_full_node_idxes.get(graph_input, [])
        resized_to_0_idxes = graph_input_to_resized_to_0_node_idxes.get(graph_input, [])
        if len(resized_to_full_idxes) != len(resized_to_0_idxes):
            log.warning(f'\nUnequal number of resize-to-full and resize-to-0 nodes for graph input {graph_input}:\n{len(resized_to_full_idxes)} vs. {len(resized_to_0_idxes)}.\nSkipping `remove_fsdp2_unsharded_param_graph_input_usage` FX graph pass.\n')
            return False
        for (resize_to_full_idx, resize_to_0_idx) in zip(resized_to_full_idxes, resized_to_0_idxes):
            if resize_to_full_idx >= resize_to_0_idx:
                log.warning(f'\nFor graph input {graph_input}: resize-to-full node {node_list[resize_to_full_idx]} at index {resize_to_full_idx}\nhappens after resize-to-0 node {node_list[resize_to_0_idx]} at index {resize_to_0_idx}.\nSkipping `remove_fsdp2_unsharded_param_graph_input_usage` FX graph pass for that unsharded param.\n')
                return False
        return True
    unsharded_param_to_fsdp_copy_node_idxes = defaultdict(list)
    for (idx, node) in enumerate(node_list):
        if node.op == 'call_function' and node.target == torch.ops.fsdp.copy_.default:
            fsdp_copy_node = node
            unsharded_param = node.args[0]
            assert unsharded_param.op == 'placeholder', f"\nAssumed all FSDP2 `unsharded_param`s to be graph input, but it's not true!\nOffending node: {unsharded_param}. Graph: {graph}\n"
            if check_resize_pattern(unsharded_param):
                unsharded_param_to_fsdp_copy_node_idxes[unsharded_param].append(idx)

    def is_allowed_mutation(node):
        return node.target == torch.ops.fsdp.copy_.default or node.target == torch.ops.inductor.resize_storage_bytes_.default

    def is_node_mutating_unsharded_param_or_its_alias(node, unsharded_params):
        mutated_arg_idxes = [i for (i, x) in enumerate(node.target._schema.arguments) if x.alias_info is not None and x.alias_info.is_write] if isinstance(node.target, torch._ops.OpOverload) else []
        mutated_node_arg_storages = OrderedSet([StorageWeakRef(node.args[i].meta['val'].untyped_storage()) for i in mutated_arg_idxes])
        storages_of_unsharded_params = OrderedSet([StorageWeakRef(unsharded_param.meta['val'].untyped_storage()) for unsharded_param in unsharded_params])
        return len(mutated_node_arg_storages & storages_of_unsharded_params) > 0
    for node in node_list:
        if <MASK>:
            assert not is_node_mutating_unsharded_param_or_its_alias(node, unsharded_param_to_fsdp_copy_node_idxes.keys()), f'User mutation on FSDP2 unsharded param is not allowed when Traceable FSDP2 is used. Violating node: {node}\n'
    for (unsharded_param, fsdp_copy_node_idxes) in unsharded_param_to_fsdp_copy_node_idxes.items():
        for (i, fsdp_copy_node_idx) in enumerate(fsdp_copy_node_idxes):
            fsdp_copy_node = node_list[fsdp_copy_node_idx]
            assert fsdp_copy_node.args[0] is unsharded_param
            (_, replacement) = fsdp_copy_node.args
            subgraph_start_idx = fsdp_copy_node_idx + 1
            subgraph_end_idx = fsdp_copy_node_idxes[i + 1] if i < len(fsdp_copy_node_idxes) - 1 else len(node_list) - 1
            subgraph_nodes = node_list[subgraph_start_idx:subgraph_end_idx]
            assert not any((is_node_mutating_unsharded_param_or_its_alias(node, [unsharded_param]) for node in subgraph_nodes)), f"Assumed no ops mutating unsharded param {unsharded_param} in subgraph {subgraph_nodes}, but it's not true!\nGraph: {graph}\n"
            for node in subgraph_nodes:
                if node.op == 'call_function' and unsharded_param in node.args and (node.target != torch.ops.inductor.resize_storage_bytes_.default):
                    new_args = tuple((replacement if arg is unsharded_param else arg for arg in node.args))
                    node.args = new_args
    for (unsharded_param, fsdp_copy_node_idxes) in unsharded_param_to_fsdp_copy_node_idxes.items():
        for (i, fsdp_copy_node_idx) in enumerate(fsdp_copy_node_idxes):
            fsdp_copy_node = node_list[fsdp_copy_node_idx]
            graph.erase_node(fsdp_copy_node)
    for node in node_list:
        if node.op == 'call_function' and node.target == torch.ops.inductor.resize_storage_bytes_.default and (node.args[0] in unsharded_param_to_fsdp_copy_node_idxes):
            graph.erase_node(node)

@register_make_test_function()
def make_transpose_conv_tests(options):
    """Make a set of tests to do transpose_conv."""
    test_parameters = [{'input_shape': [[1, 3, 4, 1], [1, 10, 10, 3], [3, 20, 20, 1]], 'filter_size': [[1, 1], [1, 2], [3, 3]], 'has_bias': [False], 'strides': [[1, 1, 1, 1], [1, 3, 3, 1]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'channel_multiplier': [1, 2], 'output_shape': [[]], 'fully_quantize': [False], 'const_weight_bias': [False]}, {'input_shape': [[1, 3, 3, 1]], 'filter_size': [[3, 3, 2, 1]], 'has_bias': [False], 'strides': [[1, 1, 1, 1]], 'padding': ['SAME'], 'data_format': ['NHWC'], 'channel_multiplier': [1], 'output_shape': [[1, 3, 3, 2]], 'fully_quantize': [True], 'const_weight_bias': [True]}, {'input_shape': [[1, 3, 3, 1]], 'filter_size': [[3, 3, 2, 1]], 'has_bias': [False], 'strides': [[1, 1, 1, 1]], 'padding': ['SAME'], 'data_format': ['NHWC'], 'channel_multiplier': [1], 'output_shape': [[1, 3, 3, 2]], 'fully_quantize': [False], 'const_weight_bias': [True]}, {'input_shape': [[1, 3, 3, 1]], 'filter_size': [[3, 3, 2, 1]], 'has_bias': [False], 'strides': [[1, 2, 2, 1]], 'padding': ['SAME'], 'data_format': ['NHWC'], 'channel_multiplier': [1], 'output_shape': [[1, 6, 6, 2]], 'fully_quantize': [True], 'const_weight_bias': [True]}, {'input_shape': [[1, 4, 3, 1]], 'filter_size': [[3, 3, 2, 1]], 'has_bias': [False], 'strides': [[1, 2, 2, 1]], 'padding': ['SAME'], 'data_format': ['NHWC'], 'channel_multiplier': [1], 'output_shape': [[1, 8, 6, 2]], 'fully_quantize': [True], 'const_weight_bias': [True]}, {'input_shape': [[1, 3, 3, 1]], 'filter_size': [[3, 3, 2, 1]], 'has_bias': [True], 'strides': [[1, 1, 1, 1]], 'padding': ['SAME'], 'data_format': ['NHWC'], 'channel_multiplier': [1], 'output_shape': [[1, 3, 3, 2]], 'fully_quantize': [True], 'const_weight_bias': [True]}]

    def get_tensor_shapes(parameters):
        input_shape = parameters['input_shape']
        filter_size = parameters['filter_size']
        if not parameters['const_weight_bias']:
            filter_shape = filter_size + [input_shape[3], parameters['channel_multiplier']]
            return [input_shape, filter_shape]
        return [input_shape, filter_size]

    def build_graph(parameters):
        """Build a transpose_conv graph given `parameters`."""
        (input_shape, filter_shape) = get_tensor_shapes(parameters)
        input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=input_shape)
        filter_input = tf.compat.v1.placeholder(dtype=tf.float32, name='filter', shape=filter_shape)
        if not parameters['const_weight_bias']:
            input_tensors = [input_tensor, filter_input]
            conv_outputs = tf.nn.conv2d(input=input_tensor, filters=filter_input, strides=parameters['strides'], padding=parameters['padding'], data_format=parameters['data_format'])
            out = tf.compat.v1.nn.conv2d_backprop_input(input_shape, filter_input, conv_outputs, strides=parameters['strides'], padding=parameters['padding'], data_format=parameters['data_format'])
        else:
            input_tensors = [input_tensor]
            if <MASK>:
                filter_input = create_tensor_data(np.float32, filter_shape, min_value=-1, max_value=1)
            else:
                filter_input = create_tensor_data(np.float32, filter_shape)
            out = tf.nn.conv2d_transpose(input_tensor, filter_input, parameters['output_shape'], strides=parameters['strides'], padding=parameters['padding'], data_format=parameters['data_format'])
            if parameters['has_bias']:
                if parameters['fully_quantize']:
                    bias_input = create_tensor_data(np.float32, (parameters['output_shape'][-1],), min_value=-1, max_value=1)
                else:
                    bias_input = create_tensor_data(np.float32, (parameters['output_shape'][-1],))
                out = tf.nn.bias_add(out, bias_input, data_format=parameters['data_format'])
                mul_data = create_tensor_data(np.float32, (parameters['output_shape'][-1],))
                out = tf.math.multiply(out, mul_data)
        return (input_tensors, [out])

    def build_inputs(parameters, sess, inputs, outputs):
        (input_shape, filter_shape) = get_tensor_shapes(parameters)
        if not parameters['const_weight_bias']:
            values = [create_tensor_data(np.float32, input_shape), create_tensor_data(np.float32, filter_shape)]
        elif parameters['fully_quantize']:
            values = [create_tensor_data(np.float32, input_shape, min_value=-1, max_value=1)]
        else:
            values = [create_tensor_data(np.float32, input_shape)]
        return (values, sess.run(outputs, feed_dict=dict(zip(inputs, values))))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs)

@MemoizeWithCycleCheck
def analyze_kernel_mutations(functions: dict[str, dict[Intermediate, list[Op]]], fn_name: str, num_args: int) -> list[bool]:
    """
    Analyzes the graph to detect all sinks from a predefined list of sinks
    by using triton's MemWrite trait list. NOTE: What if triton exposed this?
    From each sink, it traverses the CFG backwards to identify all the input
    pointers that are mutated.
    """
    MUTATION_OPS = {'tt.store': [0], 'tt.atomic_cas': [0], 'tt.atomic_rmw': [0], 'tt.experimental_descriptor_store': [0], 'tt.experimental_tensormap_create': [0], 'tt.descriptor_store': [0]}
    UNKNOWN_OPS = {'tt.elementwise_inline_asm'}
    stack: list[Union[Param, Intermediate]] = []
    visited = set()
    ops = functions[fn_name]
    tma_stores = get_tma_stores(functions, fn_name)
    for op_list in ops.values():
        for op in op_list:
            if op.name in UNKNOWN_OPS:
                if op.name == 'tt.elementwise_inline_asm' and op.is_pure:
                    continue
                raise RuntimeError(f'ttir analysis hit an op we do not know how to analyze: {op.name}')
            if op.name == 'tt.experimental_tensormap_create':
                assert len(op.args) >= 2
                if op.args[0] in tma_stores:
                    stack.append(op.args[1])
            if op.name == 'tt.call':
                assert op.fn_call_name in functions
                mutations = analyze_kernel_mutations(functions, op.fn_call_name, len(op.args))
                stack.extend((arg for (arg, mutated) in zip(op.args, mutations) if mutated))
            else:
                stack.extend((op.args[idx] for idx in MUTATION_OPS.get(op.name, [])))
    mutated = [False] * num_args
    while stack:
        arg = stack.pop()
        if arg in visited:
            continue
        visited.add(arg)
        if <MASK>:
            if arg.idx >= num_args:
                continue
            mutated[arg.idx] = True
        elif isinstance(arg, Intermediate) and (not arg.fake()):
            for op in ops[arg]:
                if op.name != 'tt.load':
                    stack.extend(op.args)
    return mutated

def _are_differentiable_views(view1, view2):
    if view1 is view2:
        return True
    if view1._base is None and view2._base is None:
        return False
    if <MASK>:
        return True
    return False

def resolve_related_fields(self):
    if not self.from_fields or len(self.from_fields) != len(self.to_fields):
        raise ValueError('Foreign Object from and to fields must be the same non-zero length')
    if <MASK>:
        raise ValueError('Related model %r cannot be resolved' % self.remote_field.model)
    related_fields = []
    for (from_field_name, to_field_name) in zip(self.from_fields, self.to_fields):
        from_field = self if from_field_name == RECURSIVE_RELATIONSHIP_CONSTANT else self.opts.get_field(from_field_name)
        to_field = self.remote_field.model._meta.pk if to_field_name is None else self.remote_field.model._meta.get_field(to_field_name)
        related_fields.append((from_field, to_field))
    return related_fields

def apply_str(self) -> DataFrame | Series:
    if <MASK>:
        obj = self.obj
        value = obj.shape[self.axis]
        return obj._constructor_sliced(value, index=self.agg_axis)
    return super().apply_str()

def deconstruct(self):
    kwargs = {'code': self.code}
    if self.reverse_code is not None:
        kwargs['reverse_code'] = self.reverse_code
    if <MASK>:
        kwargs['atomic'] = self.atomic
    if self.hints:
        kwargs['hints'] = self.hints
    return (self.__class__.__qualname__, [], kwargs)

def array_ufunc(self, ufunc: np.ufunc, method: str, *inputs: Any, **kwargs: Any):
    """
    Compatibility with numpy ufuncs.

    See also
    --------
    numpy.org/doc/stable/reference/arrays.classes.html#numpy.class.__array_ufunc__
    """
    from pandas.core.frame import DataFrame, Series
    from pandas.core.generic import NDFrame
    from pandas.core.internals import BlockManager
    cls = type(self)
    kwargs = _standardize_out_kwarg(**kwargs)
    result = maybe_dispatch_ufunc_to_dunder_op(self, ufunc, method, *inputs, **kwargs)
    if result is not NotImplemented:
        return result
    no_defer = (np.ndarray.__array_ufunc__, cls.__array_ufunc__)
    for item in inputs:
        higher_priority = hasattr(item, '__array_priority__') and item.__array_priority__ > self.__array_priority__
        has_array_ufunc = hasattr(item, '__array_ufunc__') and type(item).__array_ufunc__ not in no_defer and (not isinstance(item, self._HANDLED_TYPES))
        if higher_priority or has_array_ufunc:
            return NotImplemented
    types = tuple((type(x) for x in inputs))
    alignable = [x for (x, t) in zip(inputs, types, strict=True) if issubclass(t, NDFrame)]
    if len(alignable) > 1:
        set_types = set(types)
        if <MASK>:
            raise NotImplementedError(f'Cannot apply ufunc {ufunc} to mixed DataFrame and Series inputs.')
        axes = self.axes
        for obj in alignable[1:]:
            for (i, (ax1, ax2)) in enumerate(zip(axes, obj.axes, strict=True)):
                axes[i] = ax1.union(ax2)
        reconstruct_axes = dict(zip(self._AXIS_ORDERS, axes, strict=True))
        inputs = tuple((x.reindex(**reconstruct_axes) if issubclass(t, NDFrame) else x for (x, t) in zip(inputs, types, strict=True)))
    else:
        reconstruct_axes = dict(zip(self._AXIS_ORDERS, self.axes, strict=True))
    if self.ndim == 1:
        names = {x.name for x in inputs if hasattr(x, 'name')}
        name = names.pop() if len(names) == 1 else None
        reconstruct_kwargs = {'name': name}
    else:
        reconstruct_kwargs = {}

    def reconstruct(result):
        if ufunc.nout > 1:
            return tuple((_reconstruct(x) for x in result))
        return _reconstruct(result)

    def _reconstruct(result):
        if lib.is_scalar(result):
            return result
        if result.ndim != self.ndim:
            if method == 'outer':
                raise NotImplementedError
            return result
        if isinstance(result, BlockManager):
            result = self._constructor_from_mgr(result, axes=result.axes)
        else:
            result = self._constructor(result, **reconstruct_axes, **reconstruct_kwargs, copy=False)
        if len(alignable) == 1:
            result = result.__finalize__(self)
        return result
    if 'out' in kwargs:
        result = dispatch_ufunc_with_out(self, ufunc, method, *inputs, **kwargs)
        return reconstruct(result)
    if method == 'reduce':
        result = dispatch_reduction_ufunc(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    if self.ndim > 1 and (len(inputs) > 1 or ufunc.nout > 1):
        inputs = tuple((np.asarray(x) for x in inputs))
        result = getattr(ufunc, method)(*inputs, **kwargs)
    elif self.ndim == 1:
        inputs = tuple((extract_array(x, extract_numpy=True) for x in inputs))
        result = getattr(ufunc, method)(*inputs, **kwargs)
    elif method == '__call__' and (not kwargs):
        mgr = inputs[0]._mgr
        result = mgr.apply(getattr(ufunc, method))
    else:
        result = default_array_ufunc(inputs[0], ufunc, method, *inputs, **kwargs)
    result = reconstruct(result)
    return result

@dispatch.dispatch_for_api(nn_ops.dropout)
def dropout_v1(x: ragged_tensor.Ragged, keep_prob=None, noise_shape=None, seed=None, name=None, rate=None):
    """Ragged dispatch target for tf.nn.dropout."""
    if <MASK>:
        raise ValueError('noise_shape is not supported yet for RaggedTensor x')
    with ops.name_scope(name, 'RaggedNNDropout', [x, rate]):
        x = ragged_tensor.convert_to_tensor_or_ragged_tensor(x, name='x')
        return x.with_flat_values(nn_ops.dropout(x.flat_values, keep_prob=keep_prob, seed=seed, rate=rate))

def broadcast_shapes_for_args(args: Sequence[ShapeArg]) -> BlockShapeType:
    result_shape: BlockShapeType = None
    for arg in args:
        if hasattr(arg, 'shape'):
            shape = arg.shape
            if shape is None:
                return None
            elif result_shape is None:
                result_shape = tuple(shape)
            else:
                result_shape = get_broadcasted_shape(result_shape, tuple(shape))
        elif <MASK>:
            if result_shape is None:
                result_shape = ()
        elif isinstance(arg, torch.dtype):
            continue
        else:
            from torch._inductor.loop_body import LoopBody, LoopBodyBlock
            if isinstance(arg, (LoopBodyBlock, LoopBody, OpsValue)):
                return None
            raise TypeError(f'Unknown type: {type(arg)}')
    return result_shape

def c_mod(a, b):
    ret = abs(a) % abs(b)
    if <MASK>:
        ret *= -1
    return ret

def fetch(resources=None, languages=None, date_since=None, verbosity=0):
    """
    Fetch translations from Transifex, wrap long lines, generate mo files.
    """
    if date_since is None:
        resource_lang_mapping = {}
    else:
        resource_lang_mapping = list_resources_with_updates(date_since=date_since, resources=resources, languages=languages, verbosity=verbosity)
        resources = resource_lang_mapping.keys()
    locale_dirs = _get_locale_dirs(resources)
    errors = []
    for (name, dir_) in locale_dirs:
        cmd = ['tx', 'pull', '-r', _tx_resource_for_name(name), '-f', '--minimum-perc=5']
        per_resource_langs = resource_lang_mapping.get(name, languages)
        if per_resource_langs is None:
            run([*cmd, '--all'], verbosity=verbosity)
            target_langs = sorted((d for d in os.listdir(dir_) if not d.startswith('_') and d != 'en'))
        else:
            run([*cmd, '-l', ','.join(per_resource_langs)], verbosity=verbosity)
            target_langs = per_resource_langs
        target_langs = [LANG_OVERRIDES.get(d, d) for d in target_langs]
        for lang in target_langs:
            po_path = '%(path)s/%(lang)s/LC_MESSAGES/django%(ext)s.po' % {'path': dir_, 'lang': lang, 'ext': 'js' if name.endswith('-js') else ''}
            if not os.path.exists(po_path):
                print('No %(lang)s translation for resource %(name)s' % {'lang': lang, 'name': name})
                continue
            run(['msgcat', '--no-location', '-o', po_path, po_path], verbosity=verbosity)
            msgfmt = run(['msgfmt', '-c', '-o', '%s.mo' % po_path[:-3], po_path], verbosity=verbosity)
            if msgfmt.returncode != 0:
                errors.append((name, lang))
    if errors:
        print('\nWARNING: Errors have occurred in following cases:')
        for (resource, lang) in errors:
            print('\tResource %s for language %s' % (resource, lang))
        exit(1)
    if <MASK>:
        print('\nCOMPLETED.')

