def arrow_table_to_pandas(table: pyarrow.Table, dtype_backend: DtypeBackend | Literal['numpy'] | lib.NoDefault=lib.no_default, null_to_int64: bool=False, to_pandas_kwargs: dict | None=None, dtype: DtypeArg | None=None, names: Sequence[Hashable] | None=None) -> pd.DataFrame:
    pa = import_optional_dependency('pyarrow')
    to_pandas_kwargs = {} if to_pandas_kwargs is None else to_pandas_kwargs
    types_mapper: type[pd.ArrowDtype] | None | Callable
    if dtype_backend == 'numpy_nullable':
        mapping = _arrow_dtype_mapping()
        if null_to_int64:
            mapping[pa.null()] = pd.Int64Dtype()
        types_mapper = mapping.get
    elif dtype_backend == 'pyarrow':
        types_mapper = pd.ArrowDtype
    elif using_string_dtype():
        if pa_version_under19p0:
            types_mapper = _arrow_string_types_mapper()
        elif dtype is not None:
            types_mapper = {pa.int8(): pd.Int8Dtype(), pa.int16(): pd.Int16Dtype(), pa.int32(): pd.Int32Dtype(), pa.int64(): pd.Int64Dtype()}.get
        else:
            types_mapper = None
    elif <MASK>:
        if dtype is not None:
            types_mapper = {pa.int8(): pd.Int8Dtype(), pa.int16(): pd.Int16Dtype(), pa.int32(): pd.Int32Dtype(), pa.int64(): pd.Int64Dtype()}.get
        else:
            types_mapper = None
    else:
        raise NotImplementedError
    df = table.to_pandas(types_mapper=types_mapper, **to_pandas_kwargs)
    return _post_convert_dtypes(df, dtype_backend, dtype, names)

def get_sequence_length(model_cls, model_name):
    if model_name.startswith(('Blenderbot',)):
        seq_length = 128
    elif <MASK>:
        seq_length = 1024
    elif model_name in ('AllenaiLongformerBase', 'BigBird'):
        seq_length = 1024
    elif model_name.startswith('OPT'):
        seq_length = 2048
    elif 'Reformer' in model_name:
        seq_length = 4096
    elif model_name.startswith(('Albert', 'Deberta', 'Layout', 'Electra', 'XLNet', 'MegatronBert', 'Bert', 'Roberta')) or model_name in ('DistillGPT2', 'GoogleFnet', 'YituTechConvBert'):
        seq_length = 512
    elif model_name in 'TrOCRForCausalLM':
        seq_length = 256
    elif model_name.startswith('MobileBert'):
        seq_length = 128
    elif model_name.startswith('Wav2Vec2'):
        seq_length = 10000
    else:
        log.info(f'Sequence Length not defined for {model_name}. Choosing 128 arbitrarily')
        seq_length = 128
    return seq_length

@compatibility(is_backward_compatible=True)
def __init__(self, root: Union[torch.nn.Module, dict[str, Any]], graph: Graph, class_name: str='GraphModule'):
    """
        Construct a GraphModule.

        Args:

            root (Union[torch.nn.Module, Dict[str, Any]):
                ``root`` can either be an nn.Module instance or a Dict mapping strings to any attribute type.
                In the case that ``root`` is a Module, any references to Module-based objects (via qualified
                name) in the Graph's Nodes' ``target`` field will be copied over from the respective place
                within ``root``'s Module hierarchy into the GraphModule's module hierarchy.
                In the case that ``root`` is a dict, the qualified name found in a Node's ``target`` will be
                looked up directly in the dict's keys. The object mapped to by the Dict will be copied
                over into the appropriate place within the GraphModule's module hierarchy.

            graph (Graph): ``graph`` contains the nodes this GraphModule should use for code generation

            class_name (str): ``name`` denotes the name of this GraphModule for debugging purposes. If it's unset, all
                error messages will report as originating from ``GraphModule``. It may be helpful to set this
                to ``root``'s original name or a name that makes sense within the context of your transform.
        """
    super().__init__()
    self.__class__.__name__ = class_name
    if isinstance(root, torch.nn.Module):
        if hasattr(root, 'training'):
            self.training = root.training
        if isinstance(root, _CodeOnlyModule):
            for (k, _) in root.named_children():
                _copy_attr(root, self, k)
            for (k, _) in root.named_buffers():
                _copy_attr(root, self, k)
            for (k, _) in root.named_parameters():
                _copy_attr(root, self, k)
        for node in graph.nodes:
            if node.op in ['get_attr', 'call_module']:
                assert isinstance(node.target, str)
                _copy_attr(root, self, node.target)
    elif isinstance(root, dict):
        targets_to_copy = []
        for node in graph.nodes:
            if node.op in ['get_attr', 'call_module']:
                assert isinstance(node.target, str)
                if <MASK>:
                    raise RuntimeError('Node ' + str(node) + ' referenced target ' + node.target + ' but that target was not provided in ``root``!')
                targets_to_copy.append(node.target)
        targets_to_copy.sort(key=lambda t: t.count('.'))
        for target_to_copy in targets_to_copy:
            _assign_attr(root[target_to_copy], self, target_to_copy)
    else:
        raise RuntimeError('Unsupported type ' + str(root) + ' passed for root!')
    self.graph = graph
    self._tracer_cls = None
    if self.graph._tracer_cls and '<locals>' not in self.graph._tracer_cls.__qualname__:
        self._tracer_cls = self.graph._tracer_cls
    self._tracer_extras = {}
    if self.graph._tracer_extras:
        self._tracer_extras = self.graph._tracer_extras
    self.meta: dict[str, Any] = {}
    self._replace_hooks: list[Callable] = []
    self._create_node_hooks: list[Callable] = []
    self._erase_node_hooks: list[Callable] = []
    self._deepcopy_hooks: list[Callable] = []
    self.shape_env = None

def sig_for_ops(opname: str) -> list[str]:
    """sig_for_ops(opname : str) -> list[str]

    Returns signatures for operator special functions (__add__ etc.)"""
    assert opname.endswith('__') and opname.startswith('__'), f'Unexpected op {opname}'
    name = opname[2:-2]
    if name == 'rpow':
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # type: ignore[has-type]']
    elif name in arithmetic_ops:
        if <MASK>:
            return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # noqa: PYI034']
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...']
    elif name in logic_ops:
        return [f'def {opname}(self, other: Tensor | _int) -> Tensor: ...']
    elif name in shift_ops:
        return [f'def {opname}(self, other: Tensor | _int) -> Tensor: ...']
    elif name in symmetric_comparison_ops:
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # type: ignore[overload-overlap]', f'def {opname}(self, other: object) -> _bool: ...']
    elif name in asymmetric_comparison_ops:
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...']
    elif name in unary_ops:
        return [f'def {opname}(self) -> Tensor: ...']
    if name in to_py_type_ops:
        if name in {'bool', 'float', 'complex'}:
            tname = name
        elif name == 'nonzero':
            tname = 'bool'
        else:
            tname = 'int'
        if tname in {'float', 'int', 'bool', 'complex'}:
            tname = '_' + tname
        return [f'def {opname}(self) -> {tname}: ...']
    raise ValueError(f'unknown op {opname!r}')

def _clone_input(value, fake_mode):
    if isinstance(value, torch.Tensor):
        if <MASK>:
            value = clone_input(value)
    return value

def _get_default_pk_class(self):
    pk_class_path = getattr(self.app_config, 'default_auto_field', settings.DEFAULT_AUTO_FIELD)
    if <MASK>:
        app_config_class = type(self.app_config)
        source = f'{app_config_class.__module__}.{app_config_class.__qualname__}.default_auto_field'
    else:
        source = 'DEFAULT_AUTO_FIELD'
    if not pk_class_path:
        raise ImproperlyConfigured(f'{source} must not be empty.')
    try:
        pk_class = import_string(pk_class_path)
    except ImportError as e:
        msg = f"{source} refers to the module '{pk_class_path}' that could not be imported."
        raise ImproperlyConfigured(msg) from e
    if not issubclass(pk_class, AutoField):
        raise ValueError(f"Primary key '{pk_class_path}' referred by {source} must subclass AutoField.")
    return pk_class

def setup(self, dtype, exponent, title):
    M = 3 * 2 ** (exponent - 2)
    self.series = Series(np.random.randint(0, M, M)).astype(dtype)
    values = np.random.randint(0, M, M).astype(dtype)
    if title == 'inside':
        self.values = values
    elif <MASK>:
        self.values = values + M
    else:
        raise ValueError(title)

@triton.jit
def maximum_with_index(a_value, a_index, b_value, b_index):
    mask = a_value > b_value
    equal = a_value == b_value
    if <MASK>:
        a_isnan = a_value != a_value
        b_isnan = b_value != b_value
        mask |= a_isnan & (not b_isnan)
        equal |= a_isnan & b_isnan
    mask |= equal & (a_index < b_index)
    return (tl.where(mask, a_value, b_value), tl.where(mask, a_index, b_index))

def to_fullargspec(function_type: function_type_lib.FunctionType, default_values: Dict[str, Any]) -> inspect.FullArgSpec:
    """Generates backwards compatible FullArgSpec from FunctionType."""
    args = []
    varargs = None
    varkw = None
    defaults = []
    kwonlyargs = []
    kwonlydefaults = {}
    for parameter in function_type.parameters.values():
        if parameter.kind in [inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD]:
            args.append(parameter.name)
            if <MASK>:
                defaults.append(default_values[parameter.name])
        elif parameter.kind is inspect.Parameter.KEYWORD_ONLY:
            kwonlyargs.append(parameter.name)
            if parameter.default is not inspect.Parameter.empty:
                kwonlydefaults[parameter.name] = default_values[parameter.name]
        elif parameter.kind is inspect.Parameter.VAR_POSITIONAL:
            varargs = parameter.name
        elif parameter.kind is inspect.Parameter.VAR_KEYWORD:
            varkw = parameter.name
    return inspect.FullArgSpec(args, varargs, varkw, tuple(defaults) if defaults else None, kwonlyargs, kwonlydefaults if kwonlydefaults else None, annotations={})

def _str_accumulate(self, name: str, *, skipna: bool=True, **kwargs) -> ArrowExtensionArray | ExtensionArray:
    """
        Accumulate implementation for strings, see `_accumulate` docstring for details.

        pyarrow.compute does not implement these methods for strings.
        """
    if name == 'cumprod':
        msg = f"operation '{name}' not supported for dtype '{self.dtype}'"
        raise TypeError(msg)
    tail: pa.array | None = None
    na_mask: pa.array | None = None
    pa_array = self._pa_array
    np_func = {'cumsum': np.cumsum, 'cummin': np.minimum.accumulate, 'cummax': np.maximum.accumulate}[name]
    if self._hasna:
        na_mask = pc.is_null(pa_array)
        if pc.all(na_mask) == pa.scalar(True):
            return self._from_pyarrow_array(pa_array)
        if skipna:
            if name == 'cumsum':
                pa_array = pc.fill_null(pa_array, '')
            else:
                pa_array = pc.fill_null_forward(pa_array)
                pa_array = pc.fill_null_backward(pa_array)
        else:
            idx = pc.index(na_mask, True).as_py()
            tail = pa.nulls(len(pa_array) - idx, type=pa_array.type)
            pa_array = pa_array[:idx]
    pa_result = pa.array(np_func(pa_array), type=pa_array.type)
    if <MASK>:
        pa_result = pa.concat_arrays([pa_result, tail])
    elif na_mask is not None:
        pa_result = pc.if_else(na_mask, None, pa_result)
    result = self._from_pyarrow_array(pa_result)
    return result

def _convert_listlike_datetimes(arg, format: str | None, name: Hashable | None=None, utc: bool=False, unit: str | None=None, errors: DateTimeErrorChoices='raise', dayfirst: bool | None=None, yearfirst: bool | None=None, exact: bool=True):
    """
    Helper function for to_datetime. Performs the conversions of 1D listlike
    of dates

    Parameters
    ----------
    arg : list, tuple, ndarray, Series, Index
        date to be parsed
    name : object
        None or string for the Index name
    utc : bool
        Whether to convert/localize timestamps to UTC.
    unit : str
        None or string of the frequency of the passed data
    errors : str
        error handing behaviors from to_datetime, 'raise', 'coerce'
    dayfirst : bool
        dayfirst parsing behavior from to_datetime
    yearfirst : bool
        yearfirst parsing behavior from to_datetime
    exact : bool, default True
        exact format matching behavior from to_datetime

    Returns
    -------
    Index-like of parsed dates
    """
    if isinstance(arg, (list, tuple)):
        arg = np.array(arg, dtype='O')
    elif isinstance(arg, NumpyExtensionArray):
        arg = np.array(arg)
    arg_dtype = getattr(arg, 'dtype', None)
    tz = 'utc' if utc else None
    if isinstance(arg_dtype, DatetimeTZDtype):
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        if utc:
            arg = arg.tz_convert(None).tz_localize('utc')
        return arg
    elif isinstance(arg_dtype, ArrowDtype) and arg_dtype.type is Timestamp:
        if utc:
            if isinstance(arg, Index):
                arg_array = cast(ArrowExtensionArray, arg.array)
                if arg_dtype.pyarrow_dtype.tz is not None:
                    arg_array = arg_array._dt_tz_convert('UTC')
                else:
                    arg_array = arg_array._dt_tz_localize('UTC')
                arg = Index(arg_array)
            elif arg_dtype.pyarrow_dtype.tz is not None:
                arg = arg._dt_tz_convert('UTC')
            else:
                arg = arg._dt_tz_localize('UTC')
        return arg
    elif lib.is_np_dtype(arg_dtype, 'M'):
        if not is_supported_dtype(arg_dtype):
            arg = astype_overflowsafe(np.asarray(arg), np.dtype('M8[s]'), is_coerce=errors == 'coerce')
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        elif utc:
            return arg.tz_localize('utc')
        return arg
    elif unit is not None:
        if format is not None:
            raise ValueError('cannot specify both format and unit')
        return _to_datetime_with_unit(arg, unit, name, utc, errors)
    elif <MASK>:
        raise TypeError('arg must be a string, datetime, list, tuple, 1-d array, or Series')
    try:
        (arg, _) = maybe_convert_dtype(arg, copy=False, tz=libtimezones.maybe_get_tz(tz))
    except TypeError:
        if errors == 'coerce':
            npvalues = np.full(len(arg), np.datetime64('NaT', 'ns'))
            return DatetimeIndex(npvalues, name=name)
        raise
    arg = ensure_object(arg)
    if format is None:
        format = _guess_datetime_format_for_array(arg, dayfirst=dayfirst)
    if format is not None and format != 'mixed':
        return _array_strptime_with_fallback(arg, name, utc, format, exact, errors)
    (result, tz_parsed) = objects_to_datetime64(arg, dayfirst=dayfirst, yearfirst=yearfirst, utc=utc, errors=errors, allow_object=True)
    if tz_parsed is not None:
        out_unit = np.datetime_data(result.dtype)[0]
        dtype = tz_to_dtype(tz_parsed, out_unit)
        dt64_values = result.view(f'M8[{dtype.unit}]')
        dta = DatetimeArray._simple_new(dt64_values, dtype=dtype)
        return DatetimeIndex._simple_new(dta, name=name)
    return _box_as_indexlike(result, utc=utc, name=name)

def _get_response(self, request):
    """
        Resolve and call the view, then apply view, exception, and
        template_response middleware. This method is everything that happens
        inside the request/response middleware.
        """
    response = None
    (callback, callback_args, callback_kwargs) = self.resolve_request(request)
    for middleware_method in self._view_middleware:
        response = middleware_method(request, callback, callback_args, callback_kwargs)
        if response:
            break
    if <MASK>:
        wrapped_callback = self.make_view_atomic(callback)
        if iscoroutinefunction(wrapped_callback):
            wrapped_callback = async_to_sync(wrapped_callback)
        try:
            response = wrapped_callback(request, *callback_args, **callback_kwargs)
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise
    self.check_response(response, callback)
    if hasattr(response, 'render') and callable(response.render):
        for middleware_method in self._template_response_middleware:
            response = middleware_method(request, response)
            self.check_response(response, middleware_method, name='%s.process_template_response' % (middleware_method.__self__.__class__.__name__,))
        try:
            response = response.render()
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise
    return response

def _get_data_buffer(self) -> tuple[Buffer, tuple[DtypeKind, int, str, str]]:
    """
        Return the buffer containing the data and the buffer's associated dtype.
        """
    buffer: Buffer
    if <MASK>:
        if len(self.dtype[2]) > 4:
            np_arr = self._col.dt.tz_convert(None).to_numpy()
        else:
            np_arr = self._col.to_numpy()
        buffer = PandasBuffer(np_arr, allow_copy=self._allow_copy)
        dtype = (DtypeKind.INT, 64, ArrowCTypes.INT64, Endianness.NATIVE)
    elif self.dtype[0] in (DtypeKind.INT, DtypeKind.UINT, DtypeKind.FLOAT, DtypeKind.BOOL):
        dtype = self.dtype
        arr = self._col.array
        if isinstance(self._col.dtype, ArrowDtype):
            arr = arr._pa_array.chunks[0]
            buffer = PandasBufferPyarrow(arr.buffers()[1], length=len(arr))
            return (buffer, dtype)
        if isinstance(self._col.dtype, BaseMaskedDtype):
            np_arr = arr._data
        else:
            np_arr = arr._ndarray
        buffer = PandasBuffer(np_arr, allow_copy=self._allow_copy)
    elif self.dtype[0] == DtypeKind.CATEGORICAL:
        codes = self._col.values._codes
        buffer = PandasBuffer(codes, allow_copy=self._allow_copy)
        dtype = self._dtype_from_pandasdtype(codes.dtype)
    elif self.dtype[0] == DtypeKind.STRING:
        buf = self._col.to_numpy()
        b = bytearray()
        for obj in buf:
            if isinstance(obj, str):
                b.extend(obj.encode(encoding='utf-8'))
        buffer = PandasBuffer(np.frombuffer(b, dtype='uint8'))
        dtype = (DtypeKind.UINT, 8, ArrowCTypes.UINT8, Endianness.NATIVE)
    else:
        raise NotImplementedError(f'Data type {self._col.dtype} not handled yet')
    return (buffer, dtype)

def instantiate_parametrized_tests(generic_cls):
    """
    Instantiates tests that have been decorated with a parametrize_fn. This is generally performed by a
    decorator subclass of _TestParametrizer. The generic test will be replaced on the test class by
    parametrized tests with specialized names. This should be used instead of
    instantiate_device_type_tests() if the test class contains device-agnostic tests.

    You can also use it as a class decorator. E.g.

    ```
    @instantiate_parametrized_tests
    class TestFoo(TestCase):
        ...
    ```

    Args:
        generic_cls (class): Generic test class object containing tests (e.g. TestFoo)
    """
    for attr_name in tuple(dir(generic_cls)):
        class_attr = getattr(generic_cls, attr_name)
        if <MASK>:
            continue
        delattr(generic_cls, attr_name)

        def instantiate_test_helper(cls, name, test, param_kwargs):

            @wraps(test)
            def instantiated_test(self, param_kwargs=param_kwargs):
                test(self, **param_kwargs)
            assert not hasattr(generic_cls, name), f'Redefinition of test {name}'
            setattr(generic_cls, name, instantiated_test)
        for (test, test_suffix, param_kwargs, decorator_fn) in class_attr.parametrize_fn(class_attr, generic_cls=generic_cls, device_cls=None):
            full_name = f'{test.__name__}_{test_suffix}'
            for decorator in decorator_fn(param_kwargs):
                test = decorator(test)
            instantiate_test_helper(cls=generic_cls, name=full_name, test=test, param_kwargs=param_kwargs)
    return generic_cls

def __new__(cls, *args, wrap_storage=None, dtype=None, device=None, _internal=False):
    if not _internal:
        _warn_typed_storage_removal()
    if <MASK>:
        raise RuntimeError('Only child classes of _LegacyStorage can be instantiated')
    if cls == TypedStorage:
        return super().__new__(cls)
    else:
        arg_error_msg = f'{cls}.__new__ received an invalid combination of arguments. Expected one of:\n * no arguments\n * (int size)\n * (Sequence data)\n * (*, UntypedStorage wrap_storage)'
        if device is not None:
            raise RuntimeError(arg_error_msg + "\nKeyword argument 'device' cannot be specified")
        if dtype is not None:
            raise RuntimeError(arg_error_msg + "\nKeyword argument 'dtype' cannot be specified")
        if wrap_storage is None:
            if len(args) > 1:
                raise RuntimeError(arg_error_msg + '\nToo many positional arguments')
            if len(args) == 1 and (not _isint(args[0])) and (not isinstance(args[0], collections.abc.Sequence)):
                raise TypeError(arg_error_msg + f'\nArgument type not recognized: {type(args[0])}')
            return TypedStorage(*args, dtype=cls._dtype, device=_get_device_from_module(cls.__module__), _internal=True)
        else:
            if len(args) != 0:
                raise RuntimeError(arg_error_msg + "\nNo positional arguments should be given when using 'wrap_storage'")
            if not isinstance(wrap_storage, torch.UntypedStorage):
                raise TypeError(arg_error_msg + f"\nArgument 'wrap_storage' must be UntypedStorage, but got {type(wrap_storage)}")
            cls_device = _get_device_from_module(cls.__module__)
            if wrap_storage.device.type != cls_device:
                raise RuntimeError(arg_error_msg + f"\nDevice of 'wrap_storage' must be {cls_device}, but got {wrap_storage.device.type}")
            return TypedStorage(*args, wrap_storage=wrap_storage, dtype=cls.dtype, _internal=True)

def is_valid_na_for_dtype(obj, dtype: DtypeObj) -> bool:
    """
    isna check that excludes incompatible dtypes

    Parameters
    ----------
    obj : object
    dtype : np.datetime64, np.timedelta64, DatetimeTZDtype, or PeriodDtype

    Returns
    -------
    bool
    """
    if not lib.is_scalar(obj) or not isna(obj):
        return False
    elif dtype.kind == 'M':
        if isinstance(dtype, np.dtype):
            return not isinstance(obj, (np.timedelta64, Decimal))
        return not isinstance(obj, (np.timedelta64, np.datetime64, Decimal))
    elif dtype.kind == 'm':
        return not isinstance(obj, (np.datetime64, Decimal))
    elif dtype.kind in 'iufc':
        return obj is not NaT and (not isinstance(obj, (np.datetime64, np.timedelta64)))
    elif <MASK>:
        return lib.is_float(obj) or obj is None or obj is libmissing.NA
    elif dtype == _dtype_str:
        return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal, float))
    elif dtype == _dtype_object:
        return True
    elif isinstance(dtype, PeriodDtype):
        return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal))
    elif isinstance(dtype, IntervalDtype):
        return lib.is_float(obj) or obj is None or obj is libmissing.NA
    elif isinstance(dtype, CategoricalDtype):
        return is_valid_na_for_dtype(obj, dtype.categories.dtype)
    return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal))

def _get_multiindex_indexer(join_keys: list[ArrayLike], index: MultiIndex, sort: bool) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    mapped = (_factorize_keys(index.levels[n]._values, join_keys[n], sort=sort) for n in range(index.nlevels))
    zipped = zip(*mapped)
    (rcodes, lcodes, shape) = (list(x) for x in zipped)
    if sort:
        rcodes = list(map(np.take, rcodes, index.codes))
    else:
        i8copy = lambda a: a.astype('i8', subok=False)
        rcodes = list(map(i8copy, index.codes))
    for (i, join_key) in enumerate(join_keys):
        mask = index.codes[i] == -1
        if mask.any():
            a = join_key[lcodes[i] == shape[i] - 1]
            if <MASK>:
                shape[i] += 1
            rcodes[i][mask] = shape[i] - 1
    (lkey, rkey) = _get_join_keys(lcodes, rcodes, tuple(shape), sort)
    return (lkey, rkey)

def _propagate_module_bias(module: nn.Module, mask: Tensor) -> Optional[Tensor]:
    """
    In the case that we need to propagate biases, this function will return the biases we need
    """
    if module.bias is not None:
        module.bias = nn.Parameter(cast(Tensor, module.bias)[mask])
    elif getattr(module, '_bias', None) is not None:
        module.bias = nn.Parameter(cast(Tensor, module._bias)[mask])
    if getattr(module, '_bias', None) is not None:
        pruned_biases = cast(Tensor, module._bias)[~mask]
    else:
        pruned_biases = None
    if <MASK>:
        delattr(module, '_bias')
    return pruned_biases

def _create_variable(self, next_creator, **kwargs):
    """Create a mirrored variable. See `DistributionStrategy.scope`."""
    colocate_with = kwargs.pop('colocate_with', None)
    if colocate_with is None:
        devices = self._devices
    elif <MASK>:
        with ops.device(colocate_with.device):
            return next_creator(**kwargs)
    else:
        devices = colocate_with._devices

    def _real_mirrored_creator(**kwargs):
        value_list = []
        for (i, d) in enumerate(devices):
            with ops.device(d):
                kwargs['initial_value'] = self._get_variable_creator_initial_value(replica_id=i, device=d, primary_var=value_list[0] if value_list else None, **kwargs)
                if i > 0:
                    var0name = value_list[0].name.split(':')[0]
                    kwargs['name'] = '%s/replica_%d/' % (var0name, i)
                with context.device_policy(context.DEVICE_PLACEMENT_SILENT):
                    with record.stop_recording():
                        v = next_creator(**kwargs)
                assert not isinstance(v, values.DistributedVariable)
                value_list.append(v)
        return value_list
    return distribute_utils.create_mirrored_variable(self._container_strategy(), _real_mirrored_creator, distribute_utils.VARIABLE_CLASS_MAPPING, distribute_utils.VARIABLE_POLICY_MAPPING, **kwargs)

def call(self, gm: torch.fx.GraphModule) -> Optional[PassResult]:

    def get_arg_spec(arg) -> Union[TensorArgument, ConstantArgument]:
        if isinstance(arg, torch.fx.Node):
            if isinstance(arg.meta.get('val'), torch.Tensor):
                return TensorArgument(name=arg.name)
            else:
                raise AssertionError('Symint input is not implemented yet for submodule call signature.')
        else:
            return ConstantArgument(name='', value=arg)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        nn_module_stack = None
        for node in module.graph.nodes:
            if <MASK>:
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_outputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_inputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None
        nn_module_stack = None
        for node in reversed(module.graph.nodes):
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_inputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_outputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None

    def copy_sig(sig) -> ModuleCallSignature:
        from torch.export.exported_program import ModuleCallSignature
        return ModuleCallSignature(inputs=[], outputs=[], in_spec=sig.in_spec, out_spec=sig.out_spec, forward_arg_names=None)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                path = node.kwargs['path']
                (fqn, _) = next(reversed(node.meta['nn_module_stack'].values()))
                module_key = next(reversed(node.meta['nn_module_stack']))
                if '@' in module_key:
                    suffix = module_key.split('@')[-1]
                    path = f'{path}@{suffix}'
                    call_fqn = f'{fqn}@{suffix}'
                    if call_fqn not in self.specs:
                        self.specs[call_fqn] = copy_sig(self.specs[fqn])
                    fqn = call_fqn
                kind = node.kwargs['kind']
                for (i, arg) in enumerate(node.args):
                    if fqn == path:
                        if kind == 'module_call_inputs':
                            self.specs[path].inputs.append(get_arg_spec(arg))
                        elif kind == 'module_call_outputs':
                            self.specs[path].outputs.append(get_arg_spec(arg))
                        else:
                            raise AssertionError(f'Unknown tracepoint kind: {kind}')
                    if isinstance(arg, torch.fx.Node):
                        for user in node.users:
                            assert user.op == 'call_function'
                            assert user.target == operator.getitem
                            assert isinstance(user.args[1], int)
                            if user.args[1] == i:
                                user.replace_all_uses_with(arg)
                                self.sig.replace_all_uses(user.name, arg.name)
                                break
                users = list(node.users)
                for user in users:
                    assert len(user.users) == 0
                    gm.graph.erase_node(user)
                gm.graph.erase_node(node)
        return PassResult(gm, True)
    return None

def hardtanh(input: Tensor, min_val: float=-1.0, max_val: float=1.0, inplace: bool=False) -> Tensor:
    """This is the quantized version of :func:`~torch.nn.functional.hardtanh`."""
    if <MASK>:
        raise ValueError("Input to 'quantized.hardtanh' must be quantized!")
    if inplace:
        return torch._C._nn.hardtanh_(input, min_val, max_val)
    return torch._C._nn.hardtanh(input, min_val, max_val)

def set_up_planner(self, state_dict: STATE_DICT_TYPE, metadata: Optional[Metadata]=None, is_coordinator: bool=False) -> None:
    if state_dict:
        raise AssertionError('not state_dict')
    if <MASK>:
        raise AssertionError('metadata is not None')
    for (k, v) in metadata.state_dict_metadata.items():
        if not self._should_include_key(k, metadata):
            continue
        if isinstance(v, TensorStorageMetadata):
            v = torch.empty(v.size, dtype=v.properties.dtype)
        if metadata.planner_data is not None and k in metadata.planner_data:
            set_element(state_dict, metadata.planner_data[k], v)
        else:
            state_dict[k] = v
    super().set_up_planner(state_dict, metadata, is_coordinator)

def saveable_objects_for_op(op, name):
    """Create `SaveableObject`s from an operation.

  Args:
    op: A variable, operation, or SaveableObject to coerce into a
      SaveableObject.
    name: A string name for the SaveableObject.

  Yields:
    `SaveableObject`s which together save/restore `op`.

  Raises:
    TypeError: If `name` is not a string.
    ValueError: For operations with no known conversion to SaveableObject.
  """
    if not isinstance(name, str):
        raise TypeError(f'names_to_saveables must be a dict mapping string names to trackable operations. Name is not a string: {name}')
    if isinstance(op, saveable_object.SaveableObject):
        yield op
    elif isinstance(op, (list, tuple, variables.PartitionedVariable)):
        if isinstance(op, variables.PartitionedVariable):
            op = list(op)
        slice_name = None
        for variable in op:
            if isinstance(variable, saveable_object.SaveableObject):
                yield variable
                continue
            if not isinstance(variable, variables.Variable):
                raise ValueError(f'Slices must all be Variables: {variable}')
            if not variable._save_slice_info:
                raise ValueError(f'Slices must all be slices: {variable}')
            if slice_name is None:
                slice_name = variable._save_slice_info.full_name
            elif slice_name != variable._save_slice_info.full_name:
                raise ValueError(f'Slices must all be from the same tensor: {slice_name} != {variable._save_slice_info.full_name}')
            if <MASK>:
                yield ReferenceVariableSaveable(variable, variable._save_slice_info.spec, name)
            else:
                yield ResourceVariableSaveable(variable, variable._save_slice_info.spec, name)
    elif isinstance(op, trackable.Trackable) and (not isinstance(op, variables.Variable)):
        for (attr, factory) in saveable_objects_from_trackable(op, tf1_saver=True).items():
            if attr == trackable.VARIABLE_VALUE_KEY:
                full_name = name
            elif attr == trackable_utils.SERIALIZE_TO_TENSORS_NAME:
                full_name = name
            else:
                full_name = name + '_' + attr
            op = factory(full_name) if callable(factory) else factory
            for op in saveable_objects_for_op(op, op.name):
                yield op
    elif isinstance(op, resource_variable_ops.BaseResourceVariable):
        if op._in_graph_mode:
            variable = op._graph_element
        else:
            variable = op
        yield ResourceVariableSaveable(variable, '', name)
    else:
        if context.executing_eagerly():
            raise ValueError(f'Can only save/restore ResourceVariables when executing eagerly, got type: {type(op)}.')
        variable = ops.convert_to_tensor(op, as_ref=True)
        if not _tensor_comes_from_variable(variable):
            raise TypeError(f'names_to_saveables must be a dict mapping string names to Tensors/Variables. Not a variable: {variable}')
        if variable.op.type in _REF_VARIABLE_OPS:
            yield ReferenceVariableSaveable(variable, '', name)
        else:
            yield ResourceVariableSaveable(variable, '', name)

@dispatch.dispatch_for_api(math_ops.matmul)
def matmul(a: ragged_tensor.RaggedOrDense, b: ragged_tensor.RaggedOrDense, transpose_a=False, transpose_b=False, adjoint_a=False, adjoint_b=False, a_is_sparse=False, b_is_sparse=False, output_type=None, grad_a=False, grad_b=False, name=None):
    """Multiplies matrix `a` by matrix `b`.

  If all transpose or adjoint attributes are `False` then:

  ```
  output[..., i, j] = sum_k (a[..., i, k] * b[..., k, j]), for all indices i, j.
  ```

  The inputs `a` and `b` must have `rank >= 2`, where the outermost `rank - 2`
  dimensions are batch dimensions.  The inputs must have the same dtype.  See
  `tf.matmul` for more information.

  Args:
    a: `tf.Tensor` or `RaggedTensor` with `rank > 1`.
    b: `tf.Tensor` or `RaggedTensor` with same type and rank as `a`.
    transpose_a: If `True`, `a` is transposed before multiplication.
    transpose_b: If `True`, `b` is transposed before multiplication.
    adjoint_a: If `True`, `a` is conjugated & transposed before multiplication.
    adjoint_b: If `True`, `b` is conjugated & transposed before multiplication.
    a_is_sparse: If `True`, optimize assuming `a` is mostly zero.
    b_is_sparse: If `True`, optimize assuming `b` is mostly zero.
    output_type: The output datatype (optional).
    grad_a: Unused.
    grad_b: Unused.
    name: Name for the operation (optional).

  Returns:
    A `Tensor` or `RaggedTensor` with the same rank and shape as `a`, where
    each inner-most matrix is the product of the corresponding matrices in `a`
    and `b`.
  """
    del grad_a
    del grad_b
    if transpose_a and adjoint_a:
        raise ValueError('Only one of transpose_a and adjoint_a can be True.')
    if transpose_b and adjoint_b:
        raise ValueError('Only one of transpose_b and adjoint_b can be True.')
    kwargs = dict(transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b, a_is_sparse=a_is_sparse, b_is_sparse=b_is_sparse, output_type=output_type)
    with ops.name_scope(name, 'RaggedMatMul', [a, b]) as name:
        a = ragged_tensor.convert_to_tensor_or_ragged_tensor(a, name='a')
        b = ragged_tensor.convert_to_tensor_or_ragged_tensor(b, name='b')
        a_is_ragged = isinstance(a, ragged_tensor.RaggedTensor)
        b_is_ragged = isinstance(b, ragged_tensor.RaggedTensor)
        if not (a_is_ragged or b_is_ragged):
            return math_ops.matmul(a, b, **kwargs)
        if a.dtype != b.dtype:
            raise ValueError('`a` and `b` must have the same dtype.')
        if <MASK>:
            if b.shape.rank is None:
                raise ValueError('matmul requires at least one input to have known rank if either input is ragged.')
            rank = b.shape.rank
        else:
            if b.shape.rank is not None and a.shape.rank != b.shape.rank:
                raise ValueError('`a` and `b` must have the same rank.')
            rank = a.shape.rank
        if rank < 2:
            raise ValueError('`a` and `b` must have the same rank.')
        if rank > 3:
            shape_err = 'Batch dimensions of `a` and `b` do not have the same size.'
            if not a_is_ragged:
                a = ragged_tensor.RaggedTensor.from_tensor(a, ragged_rank=1)
            if not b_is_ragged:
                b = ragged_tensor.RaggedTensor.from_tensor(b, ragged_rank=1)
            with ops.control_dependencies([check_ops.assert_equal(a.row_splits, b.row_splits, message=shape_err)]):
                flat_result = matmul(a.values, b.values, **kwargs)
                return a.with_values(flat_result)
        if rank == 2:
            return _matmul_2d(a, b, **kwargs)
        assert rank == 3
        a_ragged_rank = a.ragged_rank if a_is_ragged else 0
        if a_ragged_rank == 1 and (not (b_is_ragged or transpose_a or adjoint_a)):
            return _matmul_3d_with_batch_dim_folding(a, b, **kwargs)
        else:
            return _matmul_3d_with_map_fn(a, b, **kwargs)

@torch._disable_dynamo
def zero_grad(self, set_to_none: bool=True) -> None:
    """Reset the gradients of all optimized :class:`torch.Tensor` s.

        Args:
            set_to_none (bool, optional): Instead of setting to zero, set the grads to None. Default: ``True``

                This will in general have lower memory footprint, and can modestly improve performance.
                However, it changes certain behaviors. For example:

                1. When the user tries to access a gradient and perform manual ops on it,
                   a None attribute or a Tensor full of 0s will behave differently.
                2. If the user requests ``zero_grad(set_to_none=True)`` followed by a backward pass, ``.grad``\\ s
                   are guaranteed to be None for params that did not receive a gradient.
                3. ``torch.optim`` optimizers have a different behavior if the gradient is 0 or None
                   (in one case it does the step with a gradient of 0 and in the other it skips
                   the step altogether).
        """
    foreach = self.defaults.get('foreach', False) or self.defaults.get('fused', False)
    if not hasattr(self, '_zero_grad_profile_name'):
        self._patch_step_function()
    per_device_and_dtype_grads: Optional[defaultdict[torch.device, defaultdict[torch.dtype, list[torch.Tensor]]]]
    if foreach:
        per_device_and_dtype_grads = defaultdict(lambda : defaultdict(list))
    else:
        per_device_and_dtype_grads = None
    with torch.autograd.profiler.record_function(self._zero_grad_profile_name):
        for group in self.param_groups:
            for p in group['params']:
                if p.grad is not None:
                    if set_to_none:
                        p.grad = None
                    else:
                        if p.grad.grad_fn is not None:
                            p.grad.detach_()
                        else:
                            p.grad.requires_grad_(False)
                        if not foreach or p.grad.is_sparse:
                            p.grad.zero_()
                        else:
                            if <MASK>:
                                raise AssertionError('Expected per_device_and_dtype_grads to be set')
                            per_device_and_dtype_grads[p.grad.device][p.grad.dtype].append(p.grad)
        if foreach:
            if per_device_and_dtype_grads is None:
                raise AssertionError('Expected per_device_and_dtype_grads to be set')
            for per_dtype_grads in per_device_and_dtype_grads.values():
                for grads in per_dtype_grads.values():
                    torch._foreach_zero_(grads)

def f(n):
    a = 0
    b = 0
    if <MASK>:
        a = -n
    else:
        b = 2 * n
    return (a, b)

def multimarginloss_reference(input, target, p=1, margin=1, weight=None, reduction='mean'):
    if input.dim() < 2:
        input = input.unsqueeze(0) if input.dim() == 1 else input.unsqueeze(0).unsqueeze(0)
    target_dim = target.dim()
    if target.dim() == 0:
        target = target.unsqueeze(0)
    n = input.size(0)
    dim = input.size(1)
    output = input.new(n)
    for x in range(n):
        output[x] = _multimarginloss_reference(input[x], target[x], p, margin, weight)
    if <MASK>:
        return output.mean() / dim
    elif reduction == 'sum':
        return output.sum() / dim
    elif target_dim == 0:
        return output.squeeze(0) / dim
    return output / dim

def call(self, inputs):
    if self.data_format == 'channels_first':
        if self.cropping[0][1] == self.cropping[1][1] == 0:
            return inputs[:, :, self.cropping[0][0]:, self.cropping[1][0]:]
        elif <MASK>:
            return inputs[:, :, self.cropping[0][0]:, self.cropping[1][0]:-self.cropping[1][1]]
        elif self.cropping[1][1] == 0:
            return inputs[:, :, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:]
        return inputs[:, :, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1]]
    else:
        if self.cropping[0][1] == self.cropping[1][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:, :]
        elif self.cropping[0][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:-self.cropping[1][1], :]
        elif self.cropping[1][1] == 0:
            return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:, :]
        return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1], :]

def classify_nodes(joint_module, static_lifetime_input_indices):
    name_to_node = get_name_to_node(joint_module.graph)
    required_bw_nodes: OrderedSet[fx.Node] = OrderedSet()
    for node in joint_module.graph.nodes:
        if node.op == 'placeholder' and 'tangents' in node.target:
            required_bw_nodes.add(node)
        elif _must_be_in_backward(node):
            required_bw_nodes.add(node)
        if node in required_bw_nodes:
            required_bw_nodes.update(node.users)
    primal_inputs = list(filter(_is_primal, joint_module.graph.nodes))
    fwd_seed_offset_inputs = list(filter(_is_fwd_seed_offset, joint_module.graph.nodes))
    inputs = primal_inputs + fwd_seed_offset_inputs
    (fwd_outputs, bwd_outputs, fwd_outputs_descs, bwd_outputs_descs) = _extract_fwd_bwd_outputs(joint_module, num_fwd_outputs=num_fwd_outputs)
    required_bw_nodes.update((o for o in bwd_outputs if o is not None and o.op != 'output'))
    forward_only_graph = _extract_graph_with_inputs_outputs(joint_module.graph, inputs, fwd_outputs, fwd_outputs_descs, 'forward')
    required_fw_nodes: OrderedSet[fx.Node] = OrderedSet((name_to_node[node.name] for node in forward_only_graph.nodes if node.op != 'output'))
    unclaimed_nodes: OrderedSet[fx.Node] = OrderedSet((node for node in joint_module.graph.nodes if node not in required_fw_nodes and node not in required_bw_nodes))
    static_lifetime_input_nodes = OrderedSet((p for (i, p) in enumerate(primal_inputs) if i in static_lifetime_input_indices))
    fw_cnt = 0
    fw_order = {}
    for node in joint_module.graph.nodes:
        if <MASK>:
            fw_order[node] = fw_cnt
            fw_cnt += 1
    return NodeInfo(inputs, required_fw_nodes, required_bw_nodes, unclaimed_nodes, fw_order, static_lifetime_input_nodes)

def _update_no_improvement_count(self, early_stopping, X, y, sample_weight):
    if early_stopping:
        val_score = self._score(X, y, sample_weight=sample_weight)
        self.validation_scores_.append(val_score)
        if self.verbose:
            print('Validation score: %f' % self.validation_scores_[-1])
        last_valid_score = self.validation_scores_[-1]
        if last_valid_score < self.best_validation_score_ + self.tol:
            self._no_improvement_count += 1
        else:
            self._no_improvement_count = 0
        if last_valid_score > self.best_validation_score_:
            self.best_validation_score_ = last_valid_score
            self._best_coefs = [c.copy() for c in self.coefs_]
            self._best_intercepts = [i.copy() for i in self.intercepts_]
    else:
        if <MASK>:
            self._no_improvement_count += 1
        else:
            self._no_improvement_count = 0
        if self.loss_curve_[-1] < self.best_loss_:
            self.best_loss_ = self.loss_curve_[-1]

def sensitive_post_parameters(*parameters):
    """
    Indicate which POST parameters used in the decorated view are sensitive,
    so that those parameters can later be treated in a special way, for example
    by hiding them when logging unhandled exceptions.

    Accept two forms:

    * with specified parameters:

        @sensitive_post_parameters('password', 'credit_card')
        def my_view(request):
            pw = request.POST['password']
            cc = request.POST['credit_card']
            ...

    * without any specified parameters, in which case consider all
      variables are sensitive:

        @sensitive_post_parameters()
        def my_view(request)
            ...
    """
    if len(parameters) == 1 and callable(parameters[0]):
        raise TypeError('sensitive_post_parameters() must be called to use it as a decorator, e.g., use @sensitive_post_parameters(), not @sensitive_post_parameters.')

    def decorator(view):
        if iscoroutinefunction(view):

            @wraps(view)
            async def sensitive_post_parameters_wrapper(request, *args, **kwargs):
                if not isinstance(request, HttpRequest):
                    raise TypeError("sensitive_post_parameters didn't receive an HttpRequest object. If you are decorating a classmethod, make sure to use @method_decorator.")
                if <MASK>:
                    request.sensitive_post_parameters = parameters
                else:
                    request.sensitive_post_parameters = '__ALL__'
                return await view(request, *args, **kwargs)
        else:

            @wraps(view)
            def sensitive_post_parameters_wrapper(request, *args, **kwargs):
                if not isinstance(request, HttpRequest):
                    raise TypeError("sensitive_post_parameters didn't receive an HttpRequest object. If you are decorating a classmethod, make sure to use @method_decorator.")
                if parameters:
                    request.sensitive_post_parameters = parameters
                else:
                    request.sensitive_post_parameters = '__ALL__'
                return view(request, *args, **kwargs)
        return sensitive_post_parameters_wrapper
    return decorator

def replace_expressions(self, replacements):
    if not replacements:
        return self
    if <MASK>:
        return replacement
    clone = self.create(connector=self.connector, negated=self.negated)
    for child in self.children:
        clone.children.append(child.replace_expressions(replacements))
    return clone

def jagged_binary_pointwise(func, *args, **kwargs):
    (a, b) = (args[0], args[1])
    assert isinstance(a, NestedTensor) or isinstance(b, NestedTensor)
    mismatch_error_msg = 'cannot call binary pointwise function {} with inputs of shapes {} and {}'
    if isinstance(a, NestedTensor) and isinstance(b, NestedTensor):
        if <MASK>:
            return NestedTensor(func(a._values, b._values, *args[2:], **kwargs), **extract_kwargs(a))
        raise RuntimeError(mismatch_error_msg.format(func.__name__, a._size, b._size))
    a_is_nt = isinstance(a, NestedTensor)
    extracted_kwargs = extract_kwargs(a) if a_is_nt else extract_kwargs(b)
    (nt, t) = (a, b) if a_is_nt else (b, a)
    if t.dim() > nt.dim():
        raise NotImplementedError('NYI: broadcasting NT with T with larger dim')
    t_squeezed = squeeze_leading_ones(t)
    if nt.dim() >= t_squeezed.dim() + 2:
        (lhs, rhs) = (nt._values, t_squeezed) if a_is_nt else (t_squeezed, nt._values)
        return NestedTensor(func(lhs, rhs, *args[2:], **kwargs), **extracted_kwargs)
    if a.dim() == b.dim():
        if a.shape[0] != b.shape[0]:
            raise RuntimeError(mismatch_error_msg.format(func.__name__, a.shape, b.shape))
        from .nested_tensor import nested_from_padded
        min_seqlen = nt._maybe_min_seqlen
        max_seqlen = nt._maybe_max_seqlen
        padded_max_S = max_seqlen
        total_L = nt._values.shape[nt._ragged_idx - 1]
        if padded_max_S is None:
            padded_max_S = total_L
        t = t.expand([x if i != nt._ragged_idx else padded_max_S for (i, x) in enumerate(t.shape)])
        t_as_nt = nested_from_padded(t, offsets=nt._offsets, ragged_idx=nt._ragged_idx, sum_S=total_L, min_seqlen=min_seqlen, max_seqlen=max_seqlen)
        (lhs, rhs) = (nt, t_as_nt) if a_is_nt else (t_as_nt, nt)
        return func(lhs, rhs, *args[2:], **kwargs)
    raise RuntimeError(mismatch_error_msg.format(func.__name__, a.shape, b.shape))

def __exit__(self, *exc):
    _summary_state.writer.flush()
    _summary_state.writer = self._old_writer
    if <MASK>:
        _summary_state.step = self._old_step
    return False

def __getattribute__(self, name):
    """Overridden to support hyperparameter access."""
    try:
        return super(OptimizerV2, self).__getattribute__(name)
    except AttributeError as e:
        if name == '_hyper':
            raise e
        if <MASK>:
            name = 'learning_rate'
        if name in self._hyper:
            return self._get_hyper(name)
        raise e

def assert_trace_line_count(self, fn, count, filtering_enabled=True):
    trace_line_count = -1
    if <MASK>:
        traceback_utils.enable_traceback_filtering()
    else:
        traceback_utils.disable_traceback_filtering()
    self.assertEqual(traceback_utils.is_traceback_filtering_enabled(), filtering_enabled)
    try:
        fn()
    except Exception as e:
        trace = '\n'.join(traceback.format_tb(e.__traceback__))
        trace_line_count = len(trace.split('\n'))
    self.assertGreater(trace_line_count, 0)
    if filtering_enabled:
        if sys.version_info >= (3, 13):
            self.assertLessEqual(trace_line_count, count)
        else:
            self.assertLess(trace_line_count, count)
    else:
        self.assertGreater(trace_line_count, count)

def _functional_call(module: 'torch.nn.Module', parameters_and_buffers: dict[str, Tensor], args: Optional[Union[Any, tuple]]=None, kwargs: Optional[dict[str, Any]]=None, *, tie_weights: bool=True, strict: bool=False):
    if torch.jit.is_tracing() or torch.jit.is_scripting() or isinstance(module, (torch.jit.RecursiveScriptModule, torch.jit.ScriptModule, torch.jit.ScriptFunction)):
        raise RuntimeError("The stateless API can't be used with Jitted modules")
    if isinstance(module, torch.nn.DataParallel):
        raise RuntimeError("The stateless API can't be used with nn.DataParallel module")
    if kwargs is None:
        kwargs = {}
    if <MASK>:
        args = ()
    elif not isinstance(args, tuple):
        args = (args,)
    with _reparametrize_module(module, parameters_and_buffers, tie_weights=tie_weights, strict=strict):
        return module(*args, **kwargs)

def _get_pop_fn(self, w_mod, name, is_bw):

    def fn(*args):
        if self._user_post_bw_hook is not None and is_bw:
            self._user_post_bw_hook(w_mod(), args)
        if name in self.parents:
            self._active_module_cnt[name] -= 1
            if <MASK>:
                self.parents.remove(name)
        elif not self.is_bw:
            raise RuntimeError('The Module hierarchy tracking is wrong. Report a bug to PyTorch')
    return fn

@classmethod
def _check_composite_pk(cls):
    errors = []
    meta = cls._meta
    pk = meta.pk
    if not isinstance(pk, CompositePrimaryKey):
        return errors
    seen_columns = defaultdict(list)
    for field_name in pk.field_names:
        hint = None
        try:
            field = meta.get_field(field_name)
        except FieldDoesNotExist:
            field = None
        if not field:
            hint = f'{field_name!r} is not a valid field.'
        elif <MASK>:
            hint = f'{field_name!r} field has no column.'
        elif field.null:
            hint = f"{field_name!r} field may not set 'null=True'."
        elif field.generated:
            hint = f'{field_name!r} field is a generated field.'
        elif field not in meta.local_fields:
            hint = f'{field_name!r} field is not a local field.'
        else:
            seen_columns[field.column].append(field_name)
        if hint:
            errors.append(checks.Error(f'{field_name!r} cannot be included in the composite primary key.', hint=hint, obj=cls, id='models.E042'))
    for (column, field_names) in seen_columns.items():
        if len(field_names) > 1:
            (field_name, *rest) = field_names
            duplicates = ', '.join((repr(field) for field in rest))
            errors.append(checks.Error(f'{duplicates} cannot be included in the composite primary key.', hint=f'{duplicates} and {field_name!r} are the same fields.', obj=cls, id='models.E042'))
    return errors

def _remove_redundant_quantize_ops_per_subgraph(model, subgraph_index, signature_index):
    """Remove redundant quantize ops per subgraph."""
    subgraph = model.subgraphs[subgraph_index]
    tensors = subgraph.tensors
    operators = subgraph.operators
    quant_opcode_idxs = get_quantize_opcode_idx(model)
    dequant_opcode_idxs = get_dequantize_opcode_idx(model)
    all_quant_ops = []
    redundant_quant_tensors = {}
    output_dequant_tensors = {}
    for op in operators:
        if op.opcodeIndex in quant_opcode_idxs:
            all_quant_ops.append(op)
            input_tensor = tensors[op.inputs[0]]
            output_tensor = tensors[op.outputs[0]]
            input_type = _convert_tflite_enum_type_to_tf_type(input_tensor.type)
            output_type = _convert_tflite_enum_type_to_tf_type(output_tensor.type)
            if input_type != dtypes.float32 and output_type != dtypes.float32:
                redundant_quant_tensors[op.inputs[0]] = op
        if op.opcodeIndex in dequant_opcode_idxs and op.outputs[0] in subgraph.outputs:
            output_dequant_tensors[op.inputs[0]] = op
    for op in all_quant_ops:
        output_tensor_idx = op.outputs[0]
        if output_tensor_idx in redundant_quant_tensors:
            requantize_op = redundant_quant_tensors[output_tensor_idx]
            if model.signatureDefs:
                signature_def = model.signatureDefs[0]
                for output in signature_def.outputs:
                    if output.tensorIndex == op.outputs[0]:
                        output.tensorIndex = op.inputs[0]
            deleted_tensor = requantize_op.inputs[0]
            requantize_op.inputs[0] = op.inputs[0]
            for op_user in operators:
                if deleted_tensor in op_user.inputs and op_user != requantize_op:
                    for (idx, input_tensor) in enumerate(op_user.inputs):
                        if input_tensor == deleted_tensor:
                            op_user.inputs[idx] = requantize_op.outputs[0]
            operators.remove(op)
    for op in all_quant_ops:
        output_tensor_idx = op.outputs[0]
        if <MASK>:
