def track_symint(source: Source, val: IntLikeType, constraint: DimConstraint=None) -> None:
    log.debug('track_symint %s %s %s', LazyString(source.name), val, constraint)
    assert not isinstance(val, SymInt) or is_symbolic(val)
    if isinstance(val, SymInt) and val.node.maybe_as_int() is not None:
        val = val.node.maybe_as_int()
    if isinstance(val, SymInt):
        s = val.node.expr
        if isinstance(s, sympy.Symbol):
            symbol_to_source[s].append(source)
            if constraint is not None and (not isinstance(constraint, RelaxedUnspecConstraint)):
                symbol_to_constraints[s].add(constraint)
        else:
            constraint_violated = False
            if isinstance(constraint, StrictMinMaxConstraint):
                sym_vrs = {x: self.var_to_range.get(x, None) for x in s.free_symbols}
                if any((vr is None for vr in sym_vrs.values())):
                    constraint_violated = True
            elif isinstance(constraint, RelaxedUnspecConstraint):
                if s.is_number:
                    i = int(s)
                    if i not in (0, 1):
                        constraint_violated = True
            if <MASK>:
                assert constraint is not None

                def hint(s: sympy.Expr) -> str:
                    sexpr = py_printer.doprint(s)
                    return f'{sexpr}.'
                var_with_range = self._render_range_for_constraint_violation(source, constraint)
                msg = f'Not all values of {var_with_range} are valid because {self._debug_name(source)} was inferred to be equal to '
                record_constraint_violation(constraint.warn_only, self._debug_name(source), msg, hint=functools.partial(hint, s))
        input_guards.append((source, s))
    else:
        s = sympy.Integer(val)
        input_guards.append((source, s))
        constraint_violated = False
        if isinstance(constraint, StrictMinMaxConstraint):
            if not s == constraint.vr.lower == constraint.vr.upper:
                constraint_violated = True
        elif isinstance(constraint, RelaxedUnspecConstraint):
            if val not in (0, 1):
                constraint_violated = True
        if constraint_violated:
            assert constraint is not None
            var_with_range = self._render_range_for_constraint_violation(source, constraint)
            user_stack = self.specialization_stacks.get(source, None)
            msg = f"You marked {self._debug_name(source)} as dynamic but your code specialized it to be a constant ({val}). If you're using mark_dynamic, either remove it or use maybe_mark_dynamic. If you're using Dim.DYNAMIC, replace it with either Dim.STATIC or Dim.AUTO." + ('\n\nUser stack:\n' + ''.join(user_stack.format()) if user_stack else '')
            record_constraint_violation(constraint.warn_only, self._debug_name(source), msg)

def default_expr(d: str, t: Type, *, symint: bool) -> str:
    if d == 'None' and str(t) == 'Tensor?':
        return '{}'
    if isinstance(t, BaseType) and t.name is BaseTy.str:
        if len(d) >= 2 and d[0] == "'" and (d[-1] == "'"):
            s = ''
            i = 1
            while i + 1 < len(d):
                if d[i] != '\\':
                    if d[i] == '"':
                        s += '\\"'
                    else:
                        s += d[i]
                    i += 1
                else:
                    if d[i + 1] == "'":
                        s += "'"
                    else:
                        s += d[i:i + 2]
                    i += 2
            return f'"{s}"'
    if isinstance(t, OptionalType):
        if d == 'None':
            return '::std::nullopt'
        return default_expr(d, t.elem, symint=symint)
    if isinstance(t, ListType):
        if d.startswith('[') and d.endswith(']'):
            return '{' + d[1:-1] + '}'
        elif <MASK>:
            return f'c10::SymInt({d})'
        elif t.size is None:
            raise ValueError(f"Expected a list default '[...]' but found: '{d}'")
    return JIT_TO_CPP_DEFAULT.get(d, d)

def _create_variable(self, next_creator, **kwargs):
    var_creator = self._create_var_creator(next_creator, **kwargs)
    if 'colocate_with' in kwargs:
        colocate_with = kwargs['colocate_with']
        if <MASK>:
            with ops.device(colocate_with.device):
                return var_creator(**kwargs)
        with ops.device(None):
            with ops.colocate_with(colocate_with):
                return var_creator(**kwargs)
    with ops.colocate_with(None, ignore_existing=True):
        with ops.device(self._variable_device):
            return var_creator(**kwargs)

def _update_var_to_range(self, symbol: sympy.Symbol, vr: ValueRanges, vr_sloc: Optional[ValueRangesSLoc]=None, *, is_constraint: bool=False) -> None:
    (lower, upper) = (vr.lower, vr.upper)
    if upper < 2 and symbol in self.size_like:
        vr = ValueRanges(lower, 2)
    if symbol not in self.var_to_range:
        self.log.debug('_update_var_to_range %s = %s (new)', symbol, vr)
        self.var_to_range[symbol] = vr
        if vr_sloc is None:
            sloc = self._get_sloc()
            vr_sloc = ValueRangesSLoc(sloc, sloc)
        self.var_to_range_sloc[symbol] = vr_sloc
    else:
        old = self.var_to_range[symbol]
        new = old & vr
        if new != old:
            if vr_sloc is None:
                sloc = self._get_sloc()
                vr_sloc = ValueRangesSLoc(sloc, sloc)
            if new.lower != old.lower:
                self.var_to_range_sloc[symbol].lower = vr_sloc.lower
            if <MASK>:
                self.var_to_range_sloc[symbol].upper = vr_sloc.upper
            self.var_to_range[symbol] = new
            self.log.debug('_update_var_to_range %s = %s (update)', symbol, new)
    if (v := self.var_to_val.get(symbol)) is not None:
        r = self.var_to_range[symbol]
        if v not in r:
            if not is_constraint:
                assert v in r, f'{v} not in {r}'

def _collect_derived_attrs_from_proto(op_def):
    derived_attrs = set()
    for arg in op_def.input_arg:
        if arg.type_attr:
            derived_attrs.add(arg.type_attr)
        if arg.number_attr:
            derived_attrs.add(arg.number_attr)
        if arg.type_list_attr:
            derived_attrs.add(arg.type_list_attr)
        if arg.type == types_pb2.DT_FLOAT:
            derived_attrs.add('f32_')
        elif arg.type == types_pb2.DT_INT32:
            derived_attrs.add('i32_')
        elif <MASK>:
            derived_attrs.add('i64_')
        elif arg.type == types_pb2.DT_BOOL:
            derived_attrs.add('i1_')
    return derived_attrs

def can_auto_functionalize(op: Union[OperatorBase, HopInstance]) -> bool:
    if isinstance(op, HopInstance):
        if not _has_gen_schema(op._op):
            return False
    else:
        if not isinstance(op, OpOverload):
            return False
        if torch._library.utils.is_builtin(op):
            return False
    schema = op._schema
    if not schema.is_mutable:
        return False
    schema = op._schema
    for arg in schema.arguments:
        if arg.alias_info is None:
            continue
        if not arg.alias_info.is_write:
            continue
        if <MASK>:
            continue
        if torch._library.utils.is_tensorlist_like_type(arg.type):
            continue
        return False
    if len(schema.returns) == 1 and isinstance(schema.returns[0].type, torch.NoneType):
        return True
    if isinstance(op, OpOverload):
        for ret in schema.returns:
            if ret.alias_info is None and type(ret.type) is torch.TensorType:
                continue
            return False
        if torch._C._dispatch_has_kernel_for_dispatch_key(op.name(), 'Functionalize'):
            return False
    return True

def __setitem__(self, key, val):
