        if version < versions:
            reason = f'test skipped for CUDA versions < {version}'
            raise unittest.SkipTest(reason)
        return fn(self, *args, **kwargs)
    return wrap_fn

def _assert_broadcast_with_unknown_dims(self, expected, shape1, shape2):
    actual_dims = common_shapes.broadcast_shape(shape1, shape2).dims
    reflexive_actual_dims = common_shapes.broadcast_shape(shape2, shape1).dims
    if <MASK>:
        self.assertIsNone(reflexive_actual_dims)
    elif reflexive_actual_dims is None:
        self.assertIsNone(actual_dims)
    else:
        self.assertEqual(len(actual_dims), len(reflexive_actual_dims))
        for (actual_dim, reflexive_actual_dim) in zip(actual_dims, reflexive_actual_dims):
            self.assertEqual(actual_dim.value, reflexive_actual_dim.value)
    expected_dims = expected.dims
    if expected_dims is None:
        self.assertIsNone(actual_dims)
    elif actual_dims is None:
        self.assertIsNone(expected_dims)
    else:
        self.assertEqual(len(expected_dims), len(actual_dims))
        for (expected_dim, actual_dim) in zip(expected_dims, actual_dims):
            self.assertEqual(expected_dim.value, actual_dim.value)

def _init_fqns(self) -> None:
    """Sets module and parameter FQN attributes for debugging."""
    if <MASK>:
        raise AssertionError('Expected _is_root to be True')
    root_module = self._modules[0]
    param_to_fsdp_param: dict[nn.Parameter, FSDPParam] = {}
    module_to_fsdp_param_group: dict[nn.Module, FSDPParamGroup] = {}
    for state in self._state_ctx.all_states:
        if (fsdp_param_group := state._fsdp_param_group):
            for fsdp_param in fsdp_param_group.fsdp_params:
                param_to_fsdp_param[fsdp_param.sharded_param] = fsdp_param
            for module in fsdp_param_group.modules:
                module_to_fsdp_param_group[module] = fsdp_param_group
    for (param_name, param) in root_module.named_parameters():
        if param in param_to_fsdp_param:
            param_to_fsdp_param[param]._param_fqn = param_name
    for (module_name, module) in root_module.named_modules():
        if module in module_to_fsdp_param_group:
            module_fqn = module_to_fsdp_param_group[module]._module_fqn
            if module_fqn is None:
                module_to_fsdp_param_group[module]._module_fqn = module_name
            else:
                if not isinstance(module_fqn, str):
                    raise AssertionError(f'Expected module_fqn to be str, got {type(module_fqn)}: {module_fqn}')
                module_fqn += f', {module_name}'
                module_to_fsdp_param_group[module]._module_fqn = module_fqn

def S(self):
    """
        English ordinal suffix for the day of the month, 2 characters; i.e.
        'st', 'nd', 'rd' or 'th'.
        """
    if self.data.day in (11, 12, 13):
        return 'th'
    last = self.data.day % 10
    if <MASK>:
        return 'st'
    if last == 2:
        return 'nd'
    if last == 3:
        return 'rd'
    return 'th'

@register_decomposition(aten._adaptive_avg_pool2d)
@out_wrapper()
@pw_cast_for_opmath
def adaptive_avg_pool2d(input: Tensor, output_size: tuple[int, int]):
    device = input.device
    shape = input.shape
    ndim = len(shape)
    torch._check(ndim in (3, 4), lambda : f'adaptive_avg_pool2d(): Expected 3D or 4D tensor, but got {ndim}')
    for d in input.shape[-2:]:
        torch._check(d != 0, lambda : f'adaptive_avg_pool2d(): Expected input to have non-zero size for non-batch dimensions, but input has shape {tuple(shape)}.')
    if <MASK>:
        stride = tuple((i // o for (i, o) in zip(shape[-2:], output_size)))
        kernel = tuple((i - (o - 1) * s for (i, o, s) in zip(shape[-2:], output_size, stride)))
        return torch.nn.functional.avg_pool2d(input, kernel, stride)

    def start_index(a, b, c):
        return torch.div(a * c, b, rounding_mode='trunc')

    def end_index(a, b, c):
        return torch.div((a + 1) * c + b - 1, b, rounding_mode='trunc')

    def compute_idx(in_size, out_size):
        orange = torch.arange(out_size, device=device, dtype=torch.int64)
        i0 = start_index(orange, out_size, in_size)
        maxlength = in_size // out_size + 1
        in_size_mod = in_size % out_size
        adaptive = not (in_size_mod == 0 or out_size % in_size_mod == 0)
        if adaptive:
            maxlength += 1
        elif in_size_mod == 0:
            maxlength -= 1
        range_max = torch.arange(maxlength, device=device, dtype=torch.int64)
        idx = i0.unsqueeze(-1) + range_max
        if adaptive:
            maxval = torch.scalar_tensor(in_size - 1, dtype=idx.dtype, device=idx.device)
            idx = torch.minimum(idx, maxval)
            i1 = end_index(orange, out_size, in_size)
            length = i1 - i0
        else:
            length = maxlength
        return (idx, length, range_max, adaptive)
    (idxh, length_h, range_max_h, adaptive_h) = compute_idx(shape[-2], output_size[-2])
    (idxw, length_w, range_max_w, adaptive_w) = compute_idx(shape[-1], output_size[-1])
    vals = input[..., _unsqueeze_to_dim(idxh, 4), idxw]
    if not adaptive_h and (not adaptive_w):
        return torch.mean(vals, dim=(-3, -1))

    def maybe_mask(vals, length, range_max, adaptive, dim):
        if isinstance(length, IntLike):
            return (vals, length)
        else:
            assert dim < 0
            mask = range_max >= length.unsqueeze(-1)
            if dim == -2:
                mask = _unsqueeze_to_dim(mask, 4)
            vals = torch.masked_fill(vals, mask, 0.0)
            length = _unsqueeze_to_dim(length, -dim)
            return (vals, length)
    (vals, length_h) = maybe_mask(vals, length_h, range_max_h, adaptive=adaptive_h, dim=-2)
    (vals, length_w) = maybe_mask(vals, length_w, range_max_w, adaptive=adaptive_w, dim=-1)
    ret = None
    for (i, j) in product(range(vals.shape[-3]), range(vals.shape[-1])):
        if ret is None:
            ret = vals[..., i, :, j]
        else:
            ret = ret + vals[..., i, :, j]
    return ret / (length_h * length_w)

def _build(self, checkpoint_path, build_save, build_restore):
    """Builds saver_def."""
    if not context.executing_eagerly():
        if self._is_built:
            return
        self._is_built = True
    if not self.saver_def or context.executing_eagerly():
        if <MASK>:
            self._builder = BulkSaverBuilder(self._write_version)
        if self._var_list is None:
            self._var_list = variables._all_saveable_objects()
        if not self._var_list:
            if self._allow_empty:
                self._is_empty = True
                return
            else:
                raise ValueError('No variables to save')
        self._is_empty = False
        self.saver_def = self._builder._build_internal(self._var_list, reshape=self._reshape, sharded=self._sharded, max_to_keep=self._max_to_keep, keep_checkpoint_every_n_hours=self._keep_checkpoint_every_n_hours, name=self._name, restore_sequentially=self._restore_sequentially, filename=checkpoint_path, build_save=build_save, build_restore=build_restore)
    elif self.saver_def and self._name:
        self.saver_def.filename_tensor_name = ops.prepend_name_scope(self.saver_def.filename_tensor_name, self._name)
        self.saver_def.save_tensor_name = ops.prepend_name_scope(self.saver_def.save_tensor_name, self._name)
        self.saver_def.restore_op_name = ops.prepend_name_scope(self.saver_def.restore_op_name, self._name)
    self._check_saver_def()
    if not context.executing_eagerly():
        self._next_checkpoint_time = time.time() + self.saver_def.keep_checkpoint_every_n_hours * 3600

def _parse_config_to_function(config, custom_objects, func_attr_name, func_type_attr_name, module_attr_name):
    """Reconstruct the function from the config."""
    globs = globals()
    module = config.pop(module_attr_name, None)
    if module in sys.modules:
        globs.update(sys.modules[module].__dict__)
    elif module is not None:
        warnings.warn('{} is not loaded, but a layer uses it. It may cause errors.'.format(module), UserWarning)
    if <MASK>:
        globs.update(custom_objects)
    function_type = config.pop(func_type_attr_name)
    if function_type == 'function':
        function = generic_utils.deserialize_keras_object(config[func_attr_name], custom_objects=custom_objects, printable_module_name='function in wrapper')
    elif function_type == 'lambda':
        function = generic_utils.func_load(config[func_attr_name], globs=globs)
    else:
        raise TypeError('Unknown function type:', function_type)
    return function

def _create_unique_sql(self, model, fields, name=None, condition=None, deferrable=None, include=None, opclasses=None, expressions=None, nulls_distinct=None):
    if not self._unique_supported(condition=condition, deferrable=deferrable, include=include, expressions=expressions, nulls_distinct=nulls_distinct):
        return None
    compiler = Query(model, alias_cols=False).get_compiler(connection=self.connection)
    table = model._meta.db_table
    columns = [field.column for field in fields]
    if <MASK>:
        name = self._unique_constraint_name(table, columns, quote=True)
    else:
        name = self.quote_name(name)
    if condition or include or opclasses or expressions:
        sql = self.sql_create_unique_index
    else:
        sql = self.sql_create_unique
    if columns:
        columns = self._index_columns(table, columns, col_suffixes=(), opclasses=opclasses)
    else:
        columns = Expressions(table, expressions, compiler, self.quote_value)
    return Statement(sql, table=Table(table, self.quote_name), name=name, columns=columns, condition=self._index_condition_sql(condition), deferrable=self._deferrable_constraint_sql(deferrable), include=self._index_include_sql(model, include), nulls_distinct=self._unique_index_nulls_distinct_sql(nulls_distinct))

def _deprecate_kwarg(func: F) -> F:

    @wraps(func)
    def wrapper(*args, **kwargs) -> Callable[..., Any]:
        __tracebackhide__ = True
        old_arg_value = kwargs.pop(old_arg_name, None)
        if old_arg_value is not None:
            if new_arg_name is None:
                msg = f'the {old_arg_name!r} keyword is deprecated and will be removed in a future version. Please take steps to stop the use of {old_arg_name!r}'
                warnings.warn(msg, klass, stacklevel=stacklevel)
                kwargs[old_arg_name] = old_arg_value
                return func(*args, **kwargs)
            elif <MASK>:
                if callable(mapping):
                    new_arg_value = mapping(old_arg_value)
                else:
                    new_arg_value = mapping.get(old_arg_value, old_arg_value)
                msg = f'the {old_arg_name}={old_arg_value!r} keyword is deprecated, use {new_arg_name}={new_arg_value!r} instead.'
            else:
                new_arg_value = old_arg_value
                msg = f'the {old_arg_name!r} keyword is deprecated, use {new_arg_name!r} instead.'
            warnings.warn(msg, klass, stacklevel=stacklevel)
            if kwargs.get(new_arg_name) is not None:
                msg = f'Can only specify {old_arg_name!r} or {new_arg_name!r}, not both.'
                raise TypeError(msg)
            kwargs[new_arg_name] = new_arg_value
        return func(*args, **kwargs)
    return cast(F, wrapper)

def node_to_str(self, tree, node_id, criterion):
    if tree.n_outputs == 1:
        value = tree.value[node_id][0, :]
    else:
        value = tree.value[node_id]
    labels = self.label == 'root' and node_id == 0 or self.label == 'all'
    characters = self.characters
    node_string = characters[-1]
    if self.node_ids:
        if labels:
            node_string += 'node '
        node_string += characters[0] + str(node_id) + characters[4]
    if tree.children_left[node_id] != _tree.TREE_LEAF:
        if self.feature_names is not None:
            feature = self.feature_names[tree.feature[node_id]]
            feature = self.str_escape(feature)
        else:
            feature = 'x%s%s%s' % (characters[1], tree.feature[node_id], characters[2])
        node_string += '%s %s %s%s' % (feature, characters[3], round(tree.threshold[node_id], self.precision), characters[4])
    if <MASK>:
        if isinstance(criterion, _criterion.FriedmanMSE):
            criterion = 'friedman_mse'
        elif isinstance(criterion, _criterion.MSE) or criterion == 'squared_error':
            criterion = 'squared_error'
        elif not isinstance(criterion, str):
            criterion = 'impurity'
        if labels:
            node_string += '%s = ' % criterion
        node_string += str(round(tree.impurity[node_id], self.precision)) + characters[4]
    if labels:
        node_string += 'samples = '
    if self.proportion:
        percent = 100.0 * tree.n_node_samples[node_id] / float(tree.n_node_samples[0])
        node_string += str(round(percent, 1)) + '%' + characters[4]
    else:
        node_string += str(tree.n_node_samples[node_id]) + characters[4]
    if not self.proportion and tree.n_classes[0] != 1:
        value = value * tree.weighted_n_node_samples[node_id]
    if labels:
        node_string += 'value = '
    if tree.n_classes[0] == 1:
        value_text = np.around(value, self.precision)
    elif self.proportion:
        value_text = np.around(value, self.precision)
    elif np.all(np.equal(np.mod(value, 1), 0)):
        value_text = value.astype(int)
    else:
        value_text = np.around(value, self.precision)
    value_text = str(value_text.astype('S32')).replace("b'", "'")
    value_text = value_text.replace("' '", ', ').replace("'", '')
    if tree.n_classes[0] == 1 and tree.n_outputs == 1:
        value_text = value_text.replace('[', '').replace(']', '')
    value_text = value_text.replace('\n ', characters[4])
    node_string += value_text + characters[4]
    if self.class_names is not None and tree.n_classes[0] != 1 and (tree.n_outputs == 1):
        if labels:
            node_string += 'class = '
        if self.class_names is not True:
            class_name = self.class_names[np.argmax(value)]
            class_name = self.str_escape(class_name)
        else:
            class_name = 'y%s%s%s' % (characters[1], np.argmax(value), characters[2])
        node_string += class_name
    if node_string.endswith(characters[4]):
        node_string = node_string[:-len(characters[4])]
    return node_string + characters[5]

def convolution_internal(input, filters, strides=None, padding='VALID', data_format=None, dilations=None, name=None, call_from_convolution=True, num_spatial_dims=None):
    """Internal function which performs rank agnostic convolution.

  Args:
    input: See `convolution`.
    filters: See `convolution`.
    strides: See `convolution`.
    padding: See `convolution`.
    data_format: See `convolution`.
    dilations: See `convolution`.
    name: See `convolution`.
    call_from_convolution: See `convolution`.
    num_spatial_dims: (Optional.).  It is a integer describing the
      rank of the spatial dimensions.  For `1-D`, `2-D` and `3-D` convolutions,
      the value of `num_spatial_dims` is `1`, `2`, and `3`, respectively.
      This argument is only required to disambiguate the rank of `batch_shape`
      when `filter_shape.ndims is None` and `len(batch_shape) > 1`.  For
      backwards compatibility, if `num_spatial_dims is None` and
     `filter_shape.ndims is None`, then `len(batch_shape)` is assumed to be
     `1` (i.e., the input is expected to be
     `[batch_size, num_channels] + input_spatial_shape`
     or `[batch_size] + input_spatial_shape + [num_channels]`.

  Returns:
    A tensor of shape and dtype matching that of `input`.

  Raises:
    ValueError: If input and filter both have unknown shapes, or if
      `num_spatial_dims` is provided and incompatible with the value
      estimated from `filters.shape`.
  """
    if not isinstance(filters, variables_lib.Variable) and (not tensor_util.is_tf_type(filters)):
        with ops.name_scope('convolution_internal', None, [filters, input]):
            filters = ops.convert_to_tensor(filters, name='filters')
    if not isinstance(input, tensor_lib.Tensor) and (not tensor_util.is_tf_type(input)):
        with ops.name_scope('convolution_internal', None, [filters, input]):
            input = ops.convert_to_tensor(input, name='input')
    filters_rank = filters.shape.rank
    inputs_rank = input.shape.rank
    if num_spatial_dims is None:
        if filters_rank:
            num_spatial_dims = filters_rank - 2
        elif inputs_rank:
            num_spatial_dims = inputs_rank - 2
        else:
            raise ValueError(f'When `num_spatial_dims` is not set, one of `input.shape.rank` or `filters.shape.rank` must be known. Received: input.shape={input.shape} of rank {inputs_rank} and filters.shape={filters.shape} of rank {filters_rank}')
    elif filters_rank and filters_rank - 2 != num_spatial_dims:
        raise ValueError(f'`filters.shape.rank - 2` should equal `num_spatial_dims`. Received: filters.shape={filters.shape} of rank {filters_rank} and num_spatial_dims={num_spatial_dims}')
    if inputs_rank:
        num_batch_dims = inputs_rank - num_spatial_dims - 1
    else:
        num_batch_dims = 1
    if num_spatial_dims not in {1, 2, 3}:
        raise ValueError(f'`num_spatial_dims` must be 1, 2, or 3. Received: num_spatial_dims={num_spatial_dims}.')
    if data_format is None or data_format in _CHANNELS_LAST_FORMATS:
        channel_index = num_batch_dims + num_spatial_dims
    else:
        channel_index = num_batch_dims
    if dilations is None:
        dilations = _get_sequence(dilations, num_spatial_dims, channel_index, 'dilations')
        is_dilated_conv = False
    else:
        dilations = _get_sequence(dilations, num_spatial_dims, channel_index, 'dilations')
        is_dilated_conv = any((i != 1 for i in dilations))
    strides = _get_sequence(strides, num_spatial_dims, channel_index, 'strides')
    has_tpu_context = device_context.enclosing_tpu_context() is not None
    if name:
        default_name = None
    elif not has_tpu_context or call_from_convolution:
        default_name = 'convolution'
    elif num_spatial_dims == 2:
        default_name = 'Conv2D'
    elif num_spatial_dims == 3:
        default_name = 'Conv3D'
    else:
        default_name = 'conv1d'
    with ops.name_scope(name, default_name, [input, filters]) as name:
        if not is_dilated_conv or has_tpu_context:
            if num_spatial_dims == 2:
                op = _conv2d_expanded_batch
            elif num_spatial_dims == 3:
                op = _conv3d_expanded_batch
            else:
                op = conv1d
            return op(input, filters, strides, padding=padding, data_format=data_format, dilations=dilations, name=name)
        else:
            if <MASK>:
                strides = strides[2:]
                dilations = dilations[2:]
            else:
                strides = strides[1:-1]
                dilations = dilations[1:-1]
            op = Convolution(tensor_shape.as_shape(input.shape), tensor_shape.as_shape(filters.shape), padding, strides=strides, dilation_rate=dilations, name=name, data_format=data_format, num_spatial_dims=num_spatial_dims)
            return op(input, filters)

@register_meta([aten._fft_c2r.default, aten._fft_c2r.out])
@out_wrapper()
def meta_fft_c2r(self: Tensor, dim: list[int], normalization: int, lastdim: int):
    torch._check(self.dtype.is_complex)
    if device_hint(self) == 'cuda':
        out_sizes = list(self.size())
        out_sizes[dim[-1]] = lastdim
        output = self.new_empty(out_sizes, dtype=toRealValueType(self.dtype))
        if use_optimized_cufft_path(dim):
            return _exec_fft(output, self.clone(memory_format=torch.contiguous_format), out_sizes, dim, forward=False)
        else:
            if <MASK>:
                temp = meta_fft_c2c(self, dim[:-1], 0, lastdim)
            else:
                temp = self.clone(memory_format=torch.contiguous_format)
            return _exec_fft(output, temp, out_sizes, [dim[-1]], forward=False)
    else:
        input = self
        if len(dim) > 1:
            c2c_dims = dim[:-1]
            input = meta_fft_c2c(self, c2c_dims, normalization, forward=False)
            dim = dim[-1:]
        out_sizes = list(input.size())
        out_sizes[dim[-1]] = lastdim
        out = self.new_empty(out_sizes, dtype=toRealValueType(self.dtype))
        return _exec_fft(out, input, out_sizes, dim, forward=False)

def _convert_object_or_list(nested):
    """Convert b/t `ListWrapper` object and list representations."""
    if wrap:
        if <MASK>:
            return nested
        if _is_serialized_node_data(nested):
            return ListWrapper(nested)
        return nested
    else:
        if isinstance(nested, ListWrapper):
            return nested.as_list()
        return nested

def regroup(values, wrap_class=values_lib.PerReplica, always_wrap=False):
    """Makes a nest per-replica into a nest of PerReplica/Mirrored values.

  Args:
    values: Values to regroup
    wrap_class: Class that `values` be wrapped in.
    always_wrap: Always wrap the `values` in `wrap_class` even if the values
        are the same except for DistributeVariable.
  Returns:
    Wrapped `values`.
  """
    v0 = values[0]
    if isinstance(v0, list):
        for v in values[1:]:
            assert isinstance(v, list)
            assert len(v) == len(v0), 'len(v) == %d, len(v0) == %d, v: %s, v0: %s' % (len(v), len(v0), v, v0)
        return [regroup(tuple((v[i] for v in values)), wrap_class, always_wrap) for i in range(len(v0))]
    if isinstance(v0, tuple):
        for v in values[1:]:
            assert isinstance(v, tuple)
            assert len(v) == len(v0), f'Values to regroup had different lengths: len(v) == {len(v)}, len(v0) == {len(v0)}, v: {v}, v0: {v0}'
        regrouped_tuple = tuple((regroup(tuple((v[i] for v in values)), wrap_class, always_wrap) for i in range(len(v0))))
        if hasattr(v0, '_fields'):
            assert hasattr(v0, '_make')
            return v0._make(regrouped_tuple)
        else:
            return regrouped_tuple
    if isinstance(v0, abc.Mapping):
        v0keys = v0.keys()
        for v in values[1:]:
            assert isinstance(v, abc.Mapping), 'v[0]: %r  v[i]: %r' % (v0, v)
            assert set(v.keys()) == set(v0keys), 'v[0].keys: %s  v[i].keys: %s' % (set(v0keys), set(v.keys()))
        return type(v0)({key: regroup(tuple((v[key] for v in values)), wrap_class, always_wrap) for key in v0keys})
    same_id = True
    for v in values[1:]:
        if <MASK>:
            same_id = False
            break
    if same_id and isinstance(v0, values_lib.DistributedVariable):
        return v0
    if same_id and (not always_wrap) and (value_container(v0) is v0):
        return v0
    if not isinstance(v0, resource_variable_ops._UnreadVariable) and value_container(v0) is not v0:
        assert not isinstance(v0, values_lib.MirroredVariable), 'ids = %s, values = %s' % ([id(v) for v in values], values)
        distributed_container = value_container(v0)
        assert distributed_container is not None
        for v in values[1:]:
            assert distributed_container is value_container(v)
        return distributed_container
    return wrap_class(values)

def _difference(self, other, sort=None):
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    (other, result_name) = self._convert_can_do_setop(other)
    if not isinstance(other, RangeIndex):
        return super()._difference(other, sort=sort)
    if sort is not False and self.step < 0:
        return self[::-1]._difference(other)
    res_name = ops.get_op_result_name(self, other)
    first = self._range[::-1] if self.step < 0 else self._range
    overlap = self.intersection(other)
    if overlap.step < 0:
        overlap = overlap[::-1]
    if len(overlap) == 0:
        return self.rename(name=res_name)
    if len(overlap) == len(self):
        return self[:0].rename(res_name)
    if <MASK>:
        if overlap[0] == self[0]:
            return self[1:]
        elif overlap[0] == self[-1]:
            return self[:-1]
        elif len(self) == 3 and overlap[0] == self[1]:
            return self[::2]
        else:
            return super()._difference(other, sort=sort)
    elif len(overlap) == 2 and overlap[0] == first[0] and (overlap[-1] == first[-1]):
        return self[1:-1]
    if overlap.step == first.step:
        if overlap[0] == first.start:
            new_rng = range(overlap[-1] + first.step, first.stop, first.step)
        elif overlap[-1] == first[-1]:
            new_rng = range(first.start, overlap[0], first.step)
        elif overlap._range == first[1:-1]:
            step = len(first) - 1
            new_rng = first[::step]
        else:
            return super()._difference(other, sort=sort)
    else:
        assert len(self) > 1
        if overlap.step == first.step * 2:
            if overlap[0] == first[0] and overlap[-1] in (first[-1], first[-2]):
                new_rng = first[1::2]
            elif overlap[0] == first[1] and overlap[-1] in (first[-1], first[-2]):
                new_rng = first[::2]
            else:
                return super()._difference(other, sort=sort)
        else:
            return super()._difference(other, sort=sort)
    if first is not self._range:
        new_rng = new_rng[::-1]
    new_index = type(self)._simple_new(new_rng, name=res_name)
    return new_index

def sql_table_creation_suffix(self):
    test_settings = self.connection.settings_dict['TEST']
    if <MASK>:
        raise ImproperlyConfigured('PostgreSQL does not support collation setting at database creation time.')
    return self._get_database_create_suffix(encoding=test_settings['CHARSET'], template=test_settings.get('TEMPLATE'))

def create_model(fingerprint_input, model_settings, model_architecture, is_training, runtime_settings=None):
    """Builds a model of the requested architecture compatible with the settings.

  There are many possible ways of deriving predictions from a spectrogram
  input, so this function provides an abstract interface for creating different
  kinds of models in a black-box way. You need to pass in a TensorFlow node as
  the 'fingerprint' input, and this should output a batch of 1D features that
  describe the audio. Typically this will be derived from a spectrogram that's
  been run through an MFCC, but in theory it can be any feature vector of the
  size specified in model_settings['fingerprint_size'].

  The function will build the graph it needs in the current TensorFlow graph,
  and return the tensorflow output that will contain the 'logits' input to the
  softmax prediction process. If training flag is on, it will also return a
  placeholder node that can be used to control the dropout amount.

  See the implementations below for the possible model architectures that can be
  requested.

  Args:
    fingerprint_input: TensorFlow node that will output audio feature vectors.
    model_settings: Dictionary of information about the model.
    model_architecture: String specifying which kind of model to create.
    is_training: Whether the model is going to be used for training.
    runtime_settings: Dictionary of information about the runtime.

  Returns:
    TensorFlow node outputting logits results, and optionally a dropout
    placeholder.

  Raises:
    Exception: If the architecture type isn't recognized.
  """
    if model_architecture == 'single_fc':
        return create_single_fc_model(fingerprint_input, model_settings, is_training)
    elif model_architecture == 'conv':
        return create_conv_model(fingerprint_input, model_settings, is_training)
    elif model_architecture == 'low_latency_conv':
        return create_low_latency_conv_model(fingerprint_input, model_settings, is_training)
    elif model_architecture == 'low_latency_svdf':
        return create_low_latency_svdf_model(fingerprint_input, model_settings, is_training, runtime_settings)
    elif model_architecture == 'tiny_conv':
        return create_tiny_conv_model(fingerprint_input, model_settings, is_training)
    elif <MASK>:
        return create_tiny_embedding_conv_model(fingerprint_input, model_settings, is_training)
    else:
        raise Exception('model_architecture argument "' + model_architecture + '" not recognized, should be one of "single_fc", "conv",' + ' "low_latency_conv, "low_latency_svdf",' + ' "tiny_conv", or "tiny_embedding_conv"')

def get_select_for_update_of_arguments(self):
    """
        Return a quoted list of arguments for the SELECT FOR UPDATE OF part of
        the query.
        """

    def _get_parent_klass_info(klass_info):
        concrete_model = klass_info['model']._meta.concrete_model
        for (parent_model, parent_link) in concrete_model._meta.parents.items():
            all_parents = parent_model._meta.all_parents
            yield {'model': parent_model, 'field': parent_link, 'reverse': False, 'select_fields': [select_index for select_index in klass_info['select_fields'] if self.select[select_index][0].target.model == parent_model or self.select[select_index][0].target.model in all_parents]}

    def _get_first_selected_col_from_model(klass_info):
        """
            Find the first selected column from a model. If it doesn't exist,
            don't lock a model.

            select_fields is filled recursively, so it also contains fields
            from the parent models.
            """
        concrete_model = klass_info['model']._meta.concrete_model
        for select_index in klass_info['select_fields']:
            if self.select[select_index][0].target.model == concrete_model:
                return self.select[select_index][0]

    def _get_field_choices():
        """Yield all allowed field paths in breadth-first search order."""
        queue = collections.deque([(None, self.klass_info)])
        while queue:
            (parent_path, klass_info) = queue.popleft()
            if parent_path is None:
                path = []
                yield 'self'
            else:
                field = klass_info['field']
                if klass_info['reverse']:
                    field = field.remote_field
                path = [*parent_path, field.name]
                yield LOOKUP_SEP.join(path)
            queue.extend(((path, klass_info) for klass_info in _get_parent_klass_info(klass_info)))
            queue.extend(((path, klass_info) for klass_info in klass_info.get('related_klass_infos', [])))
    if not self.klass_info:
        return []
    result = []
    invalid_names = []
    for name in self.query.select_for_update_of:
        klass_info = self.klass_info
        if name == 'self':
            col = _get_first_selected_col_from_model(klass_info)
        else:
            for part in name.split(LOOKUP_SEP):
                klass_infos = (*klass_info.get('related_klass_infos', []), *_get_parent_klass_info(klass_info))
                for related_klass_info in klass_infos:
                    field = related_klass_info['field']
                    if related_klass_info['reverse']:
                        field = field.remote_field
                    if field.name == part:
                        klass_info = related_klass_info
                        break
                else:
                    klass_info = None
                    break
            if klass_info is None:
                invalid_names.append(name)
                continue
            col = _get_first_selected_col_from_model(klass_info)
        if col is not None:
            if <MASK>:
                result.append(self.compile(col)[0])
            else:
                result.append(self.quote_name_unless_alias(col.alias))
    if invalid_names:
        raise FieldError('Invalid field name(s) given in select_for_update(of=(...)): %s. Only relational fields followed in the query are allowed. Choices are: %s.' % (', '.join(invalid_names), ', '.join(_get_field_choices())))
    return result

def __call__(self, args, kwargs, fname=None, max_fname_arg_count=None, method: str | None=None) -> None:
    if not args and (not kwargs):
        return None
    fname = self.fname if fname is None else fname
    max_fname_arg_count = self.max_fname_arg_count if max_fname_arg_count is None else max_fname_arg_count
    method = self.method if method is None else method
    if method == 'args':
        validate_args(fname, args, max_fname_arg_count, self.defaults)
    elif method == 'kwargs':
        validate_kwargs(fname, kwargs, self.defaults)
    elif <MASK>:
        validate_args_and_kwargs(fname, args, kwargs, max_fname_arg_count, self.defaults)
    else:
        raise ValueError(f"invalid validation method '{method}'")

def get_geom_placeholder(self, f, value, compiler):
    """
        Return the placeholder for the given geometry field with the given
        value. Depending on the spatial backend, the placeholder may contain a
        stored procedure call to the transformation function of the spatial
        backend.
        """

    def transform_value(value, field):
        return value is not None and value.srid != field.srid
    if hasattr(value, 'as_sql'):
        return '%s(%%s, %s)' % (self.spatial_function_name('Transform'), f.srid) if transform_value(value.output_field, f) else '%s'
    if <MASK>:
        return '%s(%s(%%s,%s), %s)' % (self.spatial_function_name('Transform'), self.from_text, value.srid, f.srid)
    elif self.connection.features.has_spatialrefsys_table:
        return '%s(%%s,%s)' % (self.from_text, f.srid)
    else:
        return '%s(%%s)' % self.from_text

def substitute(self, symbols_map):
    """Recursively substitute symbols with values in symbols map.

        Symbols map is a dictionary of symbol-expression pairs.
        """
    if self.op is Op.SYMBOL:
        value = symbols_map.get(self)
        if value is None:
            return self
        m = re.match('\\A(@__f2py_PARENTHESIS_(\\w+)_\\d+@)\\Z', self.data)
        if <MASK>:
            (items, paren) = m.groups()
            if paren in ['ROUNDDIV', 'SQUARE']:
                return as_array(value)
            assert paren == 'ROUND', (paren, value)
        return value
    if self.op in (Op.INTEGER, Op.REAL, Op.STRING):
        return self
    if self.op in (Op.ARRAY, Op.COMPLEX):
        return Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data)))
    if self.op is Op.CONCAT:
        return normalize(Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data))))
    if self.op is Op.TERMS:
        r = None
        for (term, coeff) in self.data.items():
            if r is None:
                r = term.substitute(symbols_map) * coeff
            else:
                r += term.substitute(symbols_map) * coeff
        if r is None:
            ewarn('substitute: empty TERMS expression interpreted as int-literal 0')
            return as_number(0)
        return r
    if self.op is Op.FACTORS:
        r = None
        for (base, exponent) in self.data.items():
            if r is None:
                r = base.substitute(symbols_map) ** exponent
            else:
                r *= base.substitute(symbols_map) ** exponent
        if r is None:
            ewarn('substitute: empty FACTORS expression interpreted as int-literal 1')
            return as_number(1)
        return r
    if self.op is Op.APPLY:
        (target, args, kwargs) = self.data
        if isinstance(target, Expr):
            target = target.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in args))
        kwargs = {k: v.substitute(symbols_map) for (k, v) in kwargs.items()}
        return normalize(Expr(self.op, (target, args, kwargs)))
    if self.op is Op.INDEXING:
        func = self.data[0]
        if isinstance(func, Expr):
            func = func.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in self.data[1:]))
        return normalize(Expr(self.op, (func,) + args))
    if self.op is Op.TERNARY:
        operands = tuple((a.substitute(symbols_map) for a in self.data))
        return normalize(Expr(self.op, operands))
    if self.op in (Op.REF, Op.DEREF):
        return normalize(Expr(self.op, self.data.substitute(symbols_map)))
    if self.op is Op.RELATIONAL:
        (rop, left, right) = self.data
        left = left.substitute(symbols_map)
        right = right.substitute(symbols_map)
        return normalize(Expr(self.op, (rop, left, right)))
    raise NotImplementedError(f'substitute method for {self.op}: {self!r}')

def get_queryset(self):
    """
        Return the list of items for this view.

        The return value must be an iterable and may be an instance of
        `QuerySet` in which case `QuerySet` specific behavior will be enabled.
        """
    if self.queryset is not None:
        queryset = self.queryset
        if isinstance(queryset, QuerySet):
            queryset = queryset.all()
    elif self.model is not None:
        queryset = self.model._default_manager.all()
    else:
        raise ImproperlyConfigured('%(cls)s is missing a QuerySet. Define %(cls)s.model, %(cls)s.queryset, or override %(cls)s.get_queryset().' % {'cls': self.__class__.__name__})
    ordering = self.get_ordering()
    if ordering:
        if <MASK>:
            ordering = (ordering,)
        queryset = queryset.order_by(*ordering)
    return queryset

def as_python_constant(self):
    import torch.utils._pytree as pytree
    if <MASK>:
        if self.source is not None:
            install_guard(self.source.make_guard(GuardBuilder.EQUALS_MATCH))
            return self.value
    return super().as_python_constant()

def get_runner_prefix(rollout_state: str, workflow_requestors: Iterable[str], branch: str, eligible_experiments: frozenset[str]=frozenset(), opt_out_experiments: frozenset[str]=frozenset(), is_canary: bool=False) -> str:
    settings = parse_settings(rollout_state)
    user_optins = parse_users(rollout_state)
    fleet_prefix = ''
    prefixes = []
    for (experiment_name, experiment_settings) in settings.experiments.items():
        if not experiment_settings.all_branches and is_exception_branch(branch):
            log.info(f'Branch {branch} is an exception branch. Not enabling experiment {experiment_name}.')
            continue
        if opt_out_experiments:
            if experiment_name in opt_out_experiments:
                opt_out_exp_list = ', '.join(opt_out_experiments)
                log.info(f"Skipping experiment '{experiment_name}', as this workflow has opted-out (opted out experiments are: {opt_out_exp_list})")
                continue
        if eligible_experiments:
            if experiment_name not in eligible_experiments:
                exp_list = ', '.join(eligible_experiments)
                log.info(f"Skipping experiment '{experiment_name}', as it is not in the eligible_experiments list: {exp_list}")
                continue
        elif <MASK>:
            log.info(f"Skipping experiment '{experiment_name}', as it is not a default experiment")
            continue
        opted_out_users = [requestor for requestor in workflow_requestors if is_user_opted_out(requestor, user_optins, experiment_name)]
        if opted_out_users:
            log.info(f"{', '.join(opted_out_users)} have opted out of experiment {experiment_name}.")
            continue
        opted_in_users = [requestor for requestor in workflow_requestors if is_user_opted_in(requestor, user_optins, experiment_name)]
        enabled = False
        if opted_in_users:
            log.info(f"{', '.join(opted_in_users)} have opted into experiment {experiment_name}.")
            enabled = True
        elif experiment_settings.rollout_perc:
            if random.uniform(0, 100) <= experiment_settings.rollout_perc:
                log.info(f'Based on rollout percentage of {experiment_settings.rollout_perc}%, enabling experiment {experiment_name}.')
                enabled = True
        if enabled:
            label = experiment_name
            if experiment_name == LF_FLEET_EXPERIMENT:
                if is_canary:
                    label += CANARY_FLEET_SUFFIX
                fleet_prefix = label
            else:
                prefixes.append(label)
    if len(prefixes) > 1:
        log.error(f"Only a fleet and one other experiment can be enabled for a job at any time. Enabling {prefixes[0]} and ignoring the rest, which are {', '.join(prefixes[1:])}")
        prefixes = prefixes[:1]
    if fleet_prefix:
        prefixes.insert(0, fleet_prefix)
    return '.'.join(prefixes) + '.' if prefixes else ''

def flatten_up_to(self, tree: PyTree) -> list[PyTree]:

    def helper(treespec: PyTreeSpec, node: PyTree, subtrees: list[PyTree]) -> None:
        if treespec.is_leaf():
            subtrees.append(node)
            return
        node_type = type(node)
        if <MASK>:
            if node_type != treespec.type:
                raise ValueError(f'Type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
            (children, metadata, *_) = optree.tree_flatten_one_level(node, none_is_leaf=self.none_is_leaf, namespace=self.namespace)
            if len(children) != treespec.num_children:
                raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(children)}.')
            if metadata != treespec._metadata:
                raise ValueError(f'Node context mismatch for custom node type {treespec.type!r}.')
        else:
            both_standard_dict = treespec.type in STANDARD_DICT_TYPES and node_type in STANDARD_DICT_TYPES
            if not both_standard_dict and node_type != treespec.type:
                raise ValueError(f'Node type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
            if len(node) != treespec.num_children:
                raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(node)}.')
            if both_standard_dict:
                expected_keys = treespec.entries()
                got_key_set = set(node)
                expected_key_set = set(expected_keys)
                if got_key_set != expected_key_set:
                    missing_keys = expected_key_set.difference(got_key_set)
                    extra_keys = got_key_set.difference(expected_key_set)
                    message = ''
                    if missing_keys:
                        message += f'; missing key(s): {missing_keys}'
                    if extra_keys:
                        message += f'; extra key(s): {extra_keys}'
                    raise ValueError(f'Node keys mismatch{message}.')
                children = [node[key] for key in expected_keys]
            else:
                (children, metadata, *_) = optree.tree_flatten_one_level(node, none_is_leaf=self.none_is_leaf, namespace=self.namespace)
                if node_type is not deque and metadata != treespec._metadata:
                    raise ValueError(f'Node metadata mismatch for node type {treespec.type!r}; expected {treespec._metadata!r}, but got {metadata!r}.')
        for (subtree, subspec) in zip(children, treespec._children):
            helper(subspec, subtree, subtrees)
    subtrees: list[PyTree] = []
    helper(self, tree, subtrees)
    return subtrees

def _slice_shape(self, start, stop):
    """Returns a shape self[start:stop].

    If start == 0, then this truncates dimensions after stop.
    If start != 0, then this will return a shape with num_row_partitions == 0.

    See __getitem__.

    Args:
      start: the first dimension. 0 <= start <= rank
      stop: the last dimension (exclusive). 0 <= stop <= rank
    """
    if stop <= start:
        return DynamicRaggedShape._from_inner_shape([])
    elif start == 0:
        if stop <= self.num_row_partitions:
            if stop == 1:
                return DynamicRaggedShape._from_inner_shape([self.row_partitions[0].nrows()])
            new_row_partitions = self.row_partitions[:stop - 1]
            new_inner_shape = [new_row_partitions[-1].nvals()]
            return DynamicRaggedShape(new_row_partitions, new_inner_shape)
        else:
            if <MASK>:
                new_inner_rank = stop - self.num_row_partitions
                new_inner_shape = self.inner_shape[:new_inner_rank]
                return DynamicRaggedShape(row_partitions=self.row_partitions, inner_shape=new_inner_shape, static_inner_shape=None, validate=False)
            elif self.rank <= stop:
                return self
            new_inner_rank = stop - self.num_row_partitions
            new_inner_shape = self.inner_shape[:new_inner_rank]
            return DynamicRaggedShape(row_partitions=self.row_partitions, inner_shape=new_inner_shape, static_inner_shape=tensor_shape.TensorShape([None] * new_inner_rank), validate=False)
    else:
        if self.rank is None or stop < self.rank:
            partial = self._slice_shape(0, stop)
        else:
            partial = self
        for x in partial.row_partitions:
            if not x.is_uniform():
                raise ValueError('All relevant dimensions must be uniform')
        if partial.rank is None:
            raise NotImplementedError('__getitem__[start:stop] where start > 0 not implemented')
        return DynamicRaggedShape._from_inner_shape(partial._with_num_row_partitions(0).inner_shape[start:])

def deduplicate_readonly_buffers(tflite_model):
    """Generates a new model byte array after deduplicating readonly buffers.

  This function should be invoked after the model optimization toolkit. The
  model optimization toolkit assumes that each tensor object owns its each
  buffer separately.

  Args:
    tflite_model: TFLite flatbuffer in a byte array to be deduplicated.

  Returns:
    TFLite flatbuffer in a bytes array, processed with the deduplication method.
  """
    model = flatbuffer_utils.convert_bytearray_to_object(tflite_model)
    read_only_buffer_indices = set()
    for subgraph in model.subgraphs:
        read_only_input_tensor_indices = set()
        for op in subgraph.operators:
            if op.inputs is None:
                continue
            for (i, input_tensor_idx) in enumerate(op.inputs):
                if op.mutatingVariableInputs is not None:
                    if i < len(op.mutatingVariableInputs) and op.mutatingVariableInputs[i]:
                        continue
                if subgraph.tensors[input_tensor_idx].isVariable:
                    continue
                read_only_input_tensor_indices.add(input_tensor_idx)
        for op in subgraph.operators:
            if op.outputs is not None:
                for output_tensor_idx in op.outputs:
                    read_only_input_tensor_indices.discard(output_tensor_idx)
            if op.intermediates is not None:
                for intermediate_tensor_idx in op.intermediates:
                    read_only_input_tensor_indices.discard(intermediate_tensor_idx)
        if subgraph.inputs is not None:
            for input_tensor_idx in subgraph.inputs:
                read_only_input_tensor_indices.discard(input_tensor_idx)
        if subgraph.outputs is not None:
            for output_tensor_idx in subgraph.outputs:
                read_only_input_tensor_indices.discard(output_tensor_idx)
        for tensor_idx in read_only_input_tensor_indices:
            read_only_buffer_indices.add(subgraph.tensors[tensor_idx].buffer)
    for buffer_idx in read_only_buffer_indices.copy():
        if buffer_idx < 0 or (model.buffers[buffer_idx].data is None or isinstance(model.buffers[buffer_idx].data, list) or model.buffers[buffer_idx].data.size == 0):
            read_only_buffer_indices.discard(buffer_idx)

    class BufferIndex:
        """A class to store index, size, hash of the buffers in TFLite model."""

        def __init__(self, idx, size, hash_value):
            self.idx = idx
            self.size = size
            self.hash_value = hash_value
    read_only_buffers = list(map(lambda index: BufferIndex(index, model.buffers[index].data.size, hashlib.md5(model.buffers[index].data.data.tobytes()).hexdigest()), read_only_buffer_indices))
    read_only_buffers = sorted(read_only_buffers, key=lambda buffer: (buffer.size, buffer.hash_value), reverse=True)
    duplicate_buffer_map = {}
    for (i, buffer_i) in enumerate(read_only_buffers):
        if buffer_i.idx in duplicate_buffer_map:
            continue
        for buffer_j in read_only_buffers[i + 1:]:
            if buffer_j.idx in duplicate_buffer_map:
                continue
            if buffer_i.size != buffer_j.size:
                break
            if <MASK>:
                continue
            duplicate_buffer_map[buffer_j.idx] = buffer_i.idx
    for subgraph in model.subgraphs:
        for op in subgraph.operators:
            if op.inputs is None:
                continue
            for input_tensor in op.inputs:
                buffer_idx = subgraph.tensors[input_tensor].buffer
                if buffer_idx in duplicate_buffer_map:
                    subgraph.tensors[input_tensor].buffer = duplicate_buffer_map[buffer_idx]
    for idx in duplicate_buffer_map:
        model.buffers[idx].data = None
    return flatbuffer_utils.convert_object_to_bytearray(model)

def _block_traverse_impl(self, nodes: NodeList, start_idx: int, end_idx: int, find_last_node: bool) -> Optional[int]:
    """
        Recursive block search implementation.
        find_last_node: If True, search for the last node which result in numerics difference
        if False: find first node in sorted node list
        """
    report: list[str] = []
    mid = (start_idx + end_idx) // 2
    cur_nodes_list: NodeList = nodes[:mid + 1] if find_last_node else nodes[mid:]
    if self.exclusion_fn:
        self.exclusion_fn(cur_nodes_list, -1, -1)
    cur_nodes = set(cur_nodes_list)
    first_node_name = cur_nodes_list[0].name
    last_node_name = cur_nodes_list[-1].name
    target_node_name = last_node_name if find_last_node else first_node_name
    self.iteration += 1
    self.reports.append(report)
    report.extend(['=' * 30, f'Block search iteration {self.iteration}'])
    report.extend([f"Search for {('last' if find_last_node else 'first')} node in culprits", f'From node index {start_idx}:{nodes[start_idx].name} to {end_idx}:{nodes[end_idx].name}. ', f'Subgraph constructed by {first_node_name} to {last_node_name}', f'Targeting node: {target_node_name}', f'Size of the interested node list is {end_idx - start_idx + 1}'])
    report_idx = len(self.reports) - 1
    try:
        (split_module, submod_name) = self._build_submodule(cur_nodes)
        self._run_and_compare(split_module, submod_name, [last_node_name], report_idx)
    except (FxNetMinimizerResultMismatchError, FxNetMinimizerRunFuncError):
        report.append(f'Culprits found from node {first_node_name} to {last_node_name}.')
        if <MASK>:
            report.extend(['This is the last node in the sub-module. ', 'Search in the current branch is successful with node :', f'{start_idx}, node name: {nodes[start_idx].name}.'])
            self.print_report(report)
            return start_idx
        report.append('Proceed to split and lower the halves of the current sub-module individually.')
        self.print_report(report)
        if find_last_node:
            return self._block_traverse_impl(nodes, start_idx, mid, find_last_node)
        else:
            return self._block_traverse_impl(nodes, mid + 1, end_idx, find_last_node)
    else:
        report.append(f'Culprits not found from node start to {mid}:{nodes[mid].name}.')
        if start_idx == mid == end_idx:
            if start_idx == 0 and (not find_last_node) or (start_idx == len(nodes) - 1 and find_last_node):
                report.append(f"At {('last' if find_last_node else 'first')} node, no culprits found.")
                self.print_report(report)
                return None
            return start_idx + (1 if find_last_node else -1)
        report.append('Proceed to split and lower the halves of the current sub-module individually.')
        self.print_report(report)
        if find_last_node:
            return self._block_traverse_impl(nodes, mid + 1, end_idx, find_last_node)
        else:
            return self._block_traverse_impl(nodes, start_idx, mid, find_last_node)

def override_time_unit(time_us, default_str, time_unit):
    US_IN_SECOND = 1000.0 * 1000.0
    US_IN_MS = 1000.0
    if <MASK>:
        return f'{time_us / US_IN_SECOND:.3f}s'
    elif time_unit == 'ms':
        return f'{time_us / US_IN_MS:.3f}ms'
    elif time_unit == 'us':
        return f'{time_us:.3f}us'
    else:
        return default_str

def call_function(self, target: str, args: Sequence[Any], kwargs: Mapping[str, Any]) -> PatternExpr:
    process_arg_fn = process_arg
    if <MASK>:

        def process_arg_fn_impl(x: T, ignore_types_override: Optional[Sequence[type[Any]]]=tuple((t for t in ignore_types if t is not int))) -> Union[T, KeywordArg, Ignored]:
            return process_arg(x, ignore_types_override)
        process_arg_fn = process_arg_fn_impl
    (args, kwargs) = pytree.tree_map(process_arg_fn, (args, kwargs))
    if list in ignore_types:
        args = [process_arg_fn(a) for a in args]
        kwargs = {k: process_arg_fn(a) for (k, a) in kwargs.items()}
    return CallFunction(target, *args, **kwargs)

def _get_stack_summary(self, is_debug: bool=False, framework_loc: Optional[str]=None) -> tuple[SLoc, str]:
    floc: Optional[Union[str, traceback.FrameSummary]] = framework_loc
    if floc is None:
        frame = self._get_user_frame()
        try:
            if frame is not None:
                floc = traceback.FrameSummary(frame.f_code.co_filename, frame.f_lineno, frame.f_code.co_name)
        finally:
            del frame
    maybe_user_loc = None
    user_tb = TracingContext.extract_stack()
    if <MASK>:
        idx = len(user_tb) - 1
        while idx > 0 and user_tb[idx].filename in uninteresting_files():
            idx -= 1
        maybe_user_loc = format_frame(user_tb[idx], line=True)
    maybe_extra_debug = ''
    if is_debug and user_tb:
        maybe_extra_debug = '\nUser Stack (most recent call last):\n' + '  (snipped, see stack below for prefix)\n' + ''.join(traceback.format_list(user_tb))
    if is_debug and config.extended_debug_cpp:
        cpp_stack = CapturedTraceback.extract(cpp=True)
        maybe_extra_debug += '\nC++ stack trace:\n' + ''.join(cpp_stack.format())
    elif is_debug:
        maybe_extra_debug += '\nFor C++ stack trace, run with TORCHDYNAMO_EXTENDED_DEBUG_CPP=1'
    return (SLoc(floc, maybe_user_loc), maybe_extra_debug)

def update(self, new_scale: Optional[Union[float, torch.Tensor]]=None) -> None:
    """
        Updates the scale factor.
        If any optimizer steps were skipped the scale is multiplied by ``backoff_factor``
        to reduce it. If ``growth_interval`` unskipped iterations occurred consecutively,
        the scale is multiplied by ``growth_factor`` to increase it.
        Passing ``new_scale`` sets the new scale value manually. (``new_scale`` is not
        used directly, it's used to fill GradScaler's internal scale tensor. So if
        ``new_scale`` was a tensor, later in-place changes to that tensor will not further
        affect the scale GradScaler uses internally.)
        Args:
            new_scale (float or :class:`torch.Tensor`, optional, default=None):  New scale factor.
        .. warning::
            :meth:`update` should only be called at the end of the iteration, after ``scaler.step(optimizer)`` has
            been invoked for all optimizers used this iteration.
        """
    if not self._enabled:
        return
    (_scale, _growth_tracker) = self._check_scale_growth_tracker('update')
    if <MASK>:
        if isinstance(new_scale, float):
            self._scale.fill_(new_scale)
        else:
            reason = 'new_scale should be a float or a 1-element torch.cuda.FloatTensor or torch.FloatTensor with requires_grad=False.'
            if new_scale.device.type != self._device:
                raise AssertionError(reason)
            if new_scale.numel() != 1:
                raise AssertionError(reason)
            if new_scale.requires_grad is not False:
                raise AssertionError(reason)
            self._scale.copy_(new_scale)
    else:
        found_infs = [found_inf.to(device=_scale.device, non_blocking=True) for state in self._per_optimizer_states.values() for found_inf in state['found_inf_per_device'].values()]
        if len(found_infs) == 0:
            raise AssertionError('No inf checks were recorded prior to update.')
        found_inf_combined = found_infs[0]
        if len(found_infs) > 1:
            for i in range(1, len(found_infs)):
                found_inf_combined += found_infs[i]
        if _scale.device.type == 'cpu':
            self._amp_update_scale_cpu_(found_inf_combined)
        else:
            torch._amp_update_scale_(self._scale, self._growth_tracker, found_inf_combined, self._growth_factor, self._backoff_factor, self._growth_interval)
    self._per_optimizer_states = defaultdict(_refresh_per_optimizer_state)

def is_uniform(self, axis):
    """Returns true if the indicated dimension is uniform."""
    if not isinstance(axis, int):
        raise TypeError('axis must be an integer')
    rank = self.rank
    if axis < 0:
        raise IndexError('Negative axis values are not supported')
    elif <MASK>:
        raise IndexError('Expected axis=%s < rank=%s' % (axis, rank))
    else:
        return (axis == 0 or axis > len(self._row_partitions)) or self._row_partitions[axis - 1].is_uniform()

def broadcast_shapes(shape1, shape2):
    assert len(shape1) > 0
    assert len(shape2) > 0
    s1 = list(shape1)
    s2 = list(shape2)
    if len(s1) > len(s2):
        raise Exception('Non-equal-rank broadcast is not supported yet.')
    if <MASK>:
        raise Exception('Non-equal-rank broadcast is not supported yet.')
    ret = []
    for (d1, d2) in zip(s1, s2):
        if d1 == 1:
            ret.append(d2)
        elif d2 == 1:
            ret.append(d1)
        elif d1 == d2:
            ret.append(d1)
        else:
            raise Exception(f'Cannot broadcast shapes: {shape1} and {shape2}')
    return tuple(ret)

@register_decomposition_for_jvp(aten.native_layer_norm_backward)
def native_layer_norm_backward(grad_out: Tensor, input: Tensor, normalized_shape: list[int], mean: Tensor, rstd: Tensor, weight: Optional[Tensor], bias: Optional[Tensor], output_mask: list[bool]) -> tuple[Optional[Tensor], Optional[Tensor], Optional[Tensor]]:
    input_shape = input.shape
    input_ndim = input.dim()
    axis = input_ndim - len(normalized_shape)
    inner_dims = input_shape[axis:]
    outer_dims = input_shape[:axis]
    inner_dim_indices = list(range(axis, input_ndim))
    outer_dim_indices = list(range(axis))
    N = 1
    for i in inner_dims:
        N *= i
    M = 1
    for i in outer_dims:
        M *= i
    if M <= 0 or N <= 0:
        return (input.new_zeros(input_shape), input.new_zeros(input_shape[axis:]), input.new_zeros(input_shape[axis:]))
    (mean_, rstd_) = recompute_mean_var(input, rstd, inner_dim_indices, keepdim=True)
    x_hat = (input - mean_) * rstd_
    if weight is not None:
        grad_x_hat = grad_out * weight
    else:
        grad_x_hat = grad_out
    a = grad_x_hat * N
    b = torch.sum(grad_x_hat, inner_dim_indices, True)
    c1 = torch.mul(grad_x_hat, x_hat)
    c2 = torch.sum(c1, inner_dim_indices, True)
    c3 = torch.mul(x_hat, c2)
    inner = a - b - c3
    if output_mask[0]:
        d_input: Optional[Tensor] = rstd_ / N * inner
    else:
        d_input = torch.zeros_like(input)
    if output_mask[1] and weight is not None:
        if len(outer_dim_indices) > 0:
            d_weight: Optional[Tensor] = torch.sum(grad_out * x_hat, outer_dim_indices, False)
        else:
            d_weight = grad_out * x_hat
    elif weight is not None:
        d_weight = torch.zeros_like(weight)
    else:
        d_weight = torch.zeros(())
    if output_mask[2] and bias is not None:
        if len(outer_dim_indices) > 0:
            d_bias: Optional[Tensor] = torch.sum(grad_out, outer_dim_indices, False)
        else:
            d_bias = grad_out.clone()
    elif <MASK>:
        d_bias = torch.zeros_like(bias)
    else:
        d_bias = torch.zeros(())
    return (d_input, d_weight, d_bias)

def _alt_inner_shape(self, new_inner_rank):
    """Get an alternative inner shape with higher or lower rank.

    For the rank of the inner shape to be be higher, the last few ragged
    dimensions must have uniform_row_length.

    Args:
      new_inner_rank: the new rank of the inner_shape

    Returns:
       A new inner_shape of rank new_inner_rank.
    """
    if new_inner_rank == 0:
        raise ValueError('new_inner_rank cannot be zero')
    elif self.inner_rank == 0:
        raise ValueError('old inner_rank cannot be zero')
    elif new_inner_rank == self.inner_rank:
        return self.inner_shape
    elif new_inner_rank < self.inner_rank:
        if <MASK>:
            return _alt_inner_shape_from_tensor_shape(self._static_inner_shape, self.dtype, new_inner_rank)
        first_dimension = self._num_slices_in_dimension(-new_inner_rank)
        if new_inner_rank == 1:
            return array_ops.expand_dims(first_dimension, 0)
        remaining_dimensions = self.inner_shape[1 - new_inner_rank:]
        return array_ops.concat([array_ops.expand_dims(first_dimension, 0), remaining_dimensions], axis=0)
    else:
        assert new_inner_rank > self.inner_rank
        new_dimensions = new_inner_rank - self.inner_rank
        if any([not x.is_uniform() for x in self.row_partitions[-new_dimensions:]]):
            raise ValueError('Cannot get an inner shape over a ragged dimension')
        first_dimension = self._num_slices_in_dimension(-new_inner_rank)
        new_dimensions = new_inner_rank - self.inner_rank
        new_dims = [first_dimension] + [x.uniform_row_length() for x in self.row_partitions[-new_dimensions:]]
        return array_ops.concat([array_ops_stack.stack(new_dims), self.inner_shape[1:]], axis=0)

def _maybe_convert_for_string_atom(name: str, bvalues: ArrayLike, existing_col, min_itemsize, nan_rep, encoding, errors, columns: list[str]):
    if isinstance(bvalues.dtype, StringDtype):
        bvalues = bvalues.to_numpy()
    if bvalues.dtype != object:
        return bvalues
    bvalues = cast(np.ndarray, bvalues)
    dtype_name = bvalues.dtype.name
    inferred_type = lib.infer_dtype(bvalues, skipna=False)
    if inferred_type == 'date':
        raise TypeError('[date] is not implemented as a table column')
    if inferred_type == 'datetime':
        raise TypeError('too many timezones in this block, create separate data columns')
    if not (inferred_type == 'string' or dtype_name == 'object'):
        return bvalues
    mask = isna(bvalues)
    data = bvalues.copy()
    data[mask] = nan_rep
    if <MASK>:
        raise ValueError('NaN representation is too large for existing column size')
    inferred_type = lib.infer_dtype(data, skipna=False)
    if inferred_type != 'string':
        for i in range(data.shape[0]):
            col = data[i]
            inferred_type = lib.infer_dtype(col, skipna=False)
            if inferred_type != 'string':
                error_column_label = columns[i] if len(columns) > i else f'No.{i}'
                raise TypeError(f'Cannot serialize the column [{error_column_label}]\nbecause its data contents are not [string] but [{inferred_type}] object dtype')
    data_converted = _convert_string_array(data, encoding, errors).reshape(data.shape)
    itemsize = data_converted.itemsize
    if isinstance(min_itemsize, dict):
        min_itemsize = int(min_itemsize.get(name) or min_itemsize.get('values') or 0)
    itemsize = max(min_itemsize or 0, itemsize)
    if existing_col is not None:
        eci = existing_col.validate_col(itemsize)
        if eci is not None and eci > itemsize:
            itemsize = eci
    data_converted = data_converted.astype(f'|S{itemsize}', copy=False)
    return data_converted

def __init__(self, _shape: IntTuple, _stride: Optional[IntTuple]=None) -> None:
