def _union(self, other, sort):
    assert isinstance(other, type(self))
    assert self.dtype == other.dtype
    if <MASK>:
        return self._range_union(other, sort=sort)
    if self._can_fast_union(other):
        result = self._fast_union(other, sort=sort)
        return result
    else:
        return super()._union(other, sort)._with_freq('infer')

def adagrad(params: list[Tensor], grads: list[Tensor], state_sums: list[Tensor], state_steps: list[Tensor], fused: Optional[bool]=None, grad_scale: Optional[Tensor]=None, found_inf: Optional[Tensor]=None, has_sparse_grad: bool=False, foreach: Optional[bool]=None, differentiable: bool=False, has_complex: bool=False, *, lr: float, weight_decay: float, lr_decay: float, eps: float, maximize: bool):
    """Functional API that performs Adagrad algorithm computation.

    See :class:`~torch.optim.Adagrad` for details.
    """
    if not all((isinstance(t, torch.Tensor) for t in state_steps)):
        raise RuntimeError('API has changed, `state_steps` argument must contain a list of singleton tensors')
    if fused is None and foreach is None:
        (_, foreach) = _default_to_fused_or_foreach(params, differentiable, use_fused=False)
    if fused is None:
        fused = False
    if foreach is None:
        foreach = False
    if foreach and torch.jit.is_scripting():
        raise RuntimeError('torch.jit.script not supported with foreach optimizers')
    if <MASK>:
        raise RuntimeError('torch.jit.script not supported with fused optimizers')
    if fused and (not torch.jit.is_scripting()):
        func = _fused_adagrad
    elif foreach and (not torch.jit.is_scripting()):
        func = _multi_tensor_adagrad
    else:
        func = _single_tensor_adagrad
    func(params, grads, state_sums, state_steps, lr=lr, weight_decay=weight_decay, lr_decay=lr_decay, eps=eps, has_sparse_grad=has_sparse_grad, maximize=maximize, differentiable=differentiable, has_complex=has_complex, grad_scale=grad_scale, found_inf=found_inf)

def _can_use_math_sdpa_jagged(params: SDPAParams, debug=False) -> bool:
    if not params.query.transpose(1, 2).is_contiguous() or not params.key.transpose(1, 2).is_contiguous() or (not params.value.transpose(1, 2).is_contiguous()):
        if <MASK>:
            log.warning('If inputs are nested tensors they must be contiguous after transposing.')
        return False
    if params.is_causal:
        if debug:
            log.warning('Nested tensors for query / key are not supported when is_causal=True.')
        return False
    return True

def testFunctionStackInErrorMessage(self):
    if <MASK>:
        self.skipTest('Error interpolation is not working when function is invoked without PartitionedCallOp.')

    @polymorphic_function.function()
    def fn3(x):
        return x + 2

    @polymorphic_function.function()
    def fn2(x):
        check_ops.assert_equal(fn3(x), 3)
        return 2

    @polymorphic_function.function()
    def fn(x):
        return fn2(x)
    with self.assertRaises(errors.InvalidArgumentError) as cm:
        fn(2)
    e = cm.exception
    self.assertIn('fn -> fn2', e.message)
    self.assertIn('node assert_equal/Assert/Assert (defined at', e.message)
    self.assertNotIn('fn3', e.message)

def _list_with_ellipsis_to_str(arr):
    """Print a list that might have ellipsis."""
