def _process_python_sequences(signature: _schemas.OpSignature, named_inputs: dict[str, AllowedArgType], type_binding: Mapping[_schemas.TypeConstraintParam, ir.TypeProtocol], constant_farm: dict[tuple[bool | int | float | str | ir.TensorProtocol | tuple[int] | tuple[float], ir.DataType], ir.Value], opset: onnxscript.values.Opset):
    """Handle three types of sequences.

    1. Variadic inputs
    2. Sequence input of ir.Value,
    3. Sequence of Python constants that contains ir.Value
    """
    for (name, arg) in named_inputs.items():
        param = signature.params_map[name]
        assert isinstance(param, _schemas.Parameter), f'Expected Parameter, got {type(param)}'
        if not isinstance(arg, (tuple, list)):
            continue
        if len(arg) == 0:
            continue
        if _allowed_types_are_sequence_types(param.type_constraint.allowed_types):
            named_inputs[name] = opset.SequenceConstruct(*arg)
            continue
        if param.variadic:
            if all((isinstance(val, ir.Value) for val in arg)):
                continue
            dtype = _determine_input_dtype(param, arg, type_binding)
            new_args = []
            for val in arg:
                if isinstance(val, ir.Value):
                    new_args.append(val)
                else:
                    constant_tensor = ir.tensor(value=val, dtype=dtype)
                    constant_value = opset.Constant(value=constant_tensor)
                    new_args.append(constant_value)
            named_inputs[name] = new_args
            continue
        else:
            if all((isinstance(val, ir.Value) for val in arg)):
                expanded_args = [_reshape_to_1d_tensor(opset, val) for val in arg]
                named_inputs[name] = opset.Concat(*expanded_args, axis=0)
                continue
            dtype = _determine_input_dtype(param, arg, type_binding)
            new_args = []
            for val in arg:
                if isinstance(val, ir.Value):
                    new_args.append(_reshape_to_1d_tensor(opset, val))
                elif val is None:
                    continue
                elif <MASK>:
                    new_args.append(_reshape_to_1d_tensor(opset, opset.Constant(value=val)))
                else:
                    assert isinstance(val, (bool, int, float)), f'Expected int or float, got {type(val)}'
                    new_args.append(_get_or_create_constant(constant_farm, [val], dtype, opset))
            named_inputs[name] = opset.Concat(*new_args, axis=0)
            continue
    return named_inputs

def _sequential_split_and_maybe_inline_subgraphs(gm: torch.fx.GraphModule, graph_signature: Optional[ExportGraphSignature]) -> tuple[torch.fx.GraphModule, Optional[ExportGraphSignature]]:
    """
    Helper function for replace_set_grad_with_hop_pass().
    Split the graph module into multiple subgraphs based on the set_grad_enabled nodes.
    For each subgraph, decides whether to construct a HOO subgraph, or inline the calls
    back into the parent graph module.
    """
    need_replacing = any((_is_set_grad_enabled_node(node) for node in gm.graph.nodes))
    if not need_replacing:
        return (gm, graph_signature)
    new_gm = sequential_split(gm, _is_set_grad_enabled_node)

    def _maybe_inline_or_replace_with_hop(node: torch.fx.Node):
        if <MASK>:
            _replace_with_hop(node)
        else:
            _remove_set_grad_and_inline(node)
    return _sequential_split_and_maybe_inline_subgraphs_helper(new_gm, graph_signature, _maybe_inline_or_replace_with_hop)

def AddOp(self, op: ops.Operation) -> None:
    if op.type in _DENYLISTED_OPS:
        logging.error('Operation of type %s (%s) is not supported on the TPU. Execution will fail if this op is used in the graph. ', op.type, op.name)
    if op.type in _UNSUPPORTED_OPS:
        self._unsupported_ops.append(op)
    if any((x.dtype._is_ref_dtype for x in op.inputs)):
        raise NotImplementedError(f'Non-resource Variables are not supported inside TPU computations (operator name: {op.name})')
    if _TPU_REPLICATE_ATTR in op.node_def.attr and '_cloned' not in op.node_def.attr:
        raise ValueError(f'TPU computations cannot be nested on op ({op})')
    op._set_attr(_TPU_REPLICATE_ATTR, self._tpu_replicate_attr)
    if self._outside_compilation_cluster:
        op._set_attr(_OUTSIDE_COMPILATION_ATTR, attr_value_pb2.AttrValue(s=compat.as_bytes(self._outside_compilation_cluster)))
    if self._is_map_outside_compilation:
        op._set_attr(_MAP_OUTSIDE_COMPILATION_ATTR, attr_value_pb2.AttrValue(b=True))
    if self._num_replicas > 1 or not self._outside_compilation_cluster:
        op.graph.prevent_feeding(op)
        op.graph.prevent_fetching(op)
    (internal_control_inputs, external_control_inputs) = self._RemoveExternalControlEdges(op)
    if not op.inputs:
        if not internal_control_inputs:
            op._add_control_input(self.GetControlPivot())
    else:
        for index in range(len(op.inputs)):
            x = op.inputs[index]
            real_x = self.AddValue(x)
            if <MASK>:
                op._update_input(index, real_x)
    if external_control_inputs:
        with ops.control_dependencies(None):
            self.Enter()
            external_control_inputs = [array_ops.identity(x.outputs[0]).op for x in external_control_inputs if x.outputs]
            self.Exit()
        op._add_control_inputs(external_control_inputs)
    output_names = [x.name for x in op.outputs]
    context = self
    while context is not None:
        context._values.update(output_names)
        context = context._outer_context
    if self._outer_context:
        self._outer_context.AddInnerOp(op)

def _get_set_of_int_from_ranges_str(ranges_str: str) -> set[int]:
    """
    Util for parsing a string of int ranges, as in a sysfs file.

    Args:
        ranges_str: E.g., "0-2,4,6-7"

    Returns:
        E.g., {0, 1, 2, 4, 6, 7}
    """
    ints: set[int] = set()
    for range_str in ranges_str.split(','):
        range_str = range_str.strip()
        if not range_str:
            continue
        if <MASK>:
            (start_str, end_str) = range_str.split('-')
            (start, end) = (int(start_str), int(end_str))
            ints.update(range(start, end + 1))
        else:
            ints.add(int(range_str))
    return ints

def run(self, *args, stream, benchmark_run=False, **kwargs):
    if hasattr(triton, 'set_allocator'):

        def alloc_fn(size: int, align: int, stream: int | None):
            return torch.empty(size, dtype=torch.int8, device=self.device_props.type)
        triton.set_allocator(alloc_fn)
    if <MASK>:
        (args, grid) = self._interpret_args_grid(args, self.configs[0])
        return self.fn[grid](*args, **kwargs, **self.configs[0].kwargs)
    if len(self.launchers) != 1:
        if len(self.launchers) == 0:
            start_time = time.time_ns()
            self.precompile()
            self.precompile_time_taken_ns = time.time_ns() - start_time
        if len(self.launchers) > 1:
            self.autotune_to_one_config(*args, **kwargs)
    if not getattr(self.launchers[0].config, 'found_by_coordesc', False) and self.inductor_meta.get('coordinate_descent_tuning', False):
        self.launchers = [self.coordinate_descent_tuning(self.launchers[0], *args, **kwargs)]
    (launcher,) = self.launchers
    if launcher.store_cubin and (not benchmark_run or not self.cuda_kernel_saved):
        self.save_gpu_kernel(stream, launcher)
    args_without_constexprs = tuple(args)
    if self.dump_launch_params:
        (new_args, grid) = self._interpret_args_grid(args, launcher.config)
        _dump_launch_params(new_args, kwargs, launcher, self.fn.__name__, grid)
    if autograd_profiler._is_profiler_enabled:
        profiler_kwargs = self.get_profiler_kwargs(stream, launcher)
        with torch._C._profiler._RecordFunctionFast(self.inductor_meta.get('kernel_name', 'triton kernel'), args_without_constexprs, profiler_kwargs):
            return launcher(*args, **kwargs, stream=stream)
    else:
        return launcher(*args, **kwargs, stream=stream)

def tpu_function(args, kwargs):
    """TF Function used to replicate the user computation."""
    logging.vlog(1, '`TPUStrategy.run` is called with [args: %s] [kwargs: %s]', args, kwargs)
    if kwargs is None:
        kwargs = {}
    result = [[]]

    def replicated_fn(replica_id, replica_args, replica_kwargs):
        """Wraps user function to provide replica ID and `Tensor` inputs."""
        with _TPUReplicaContext(strategy, replica_id_in_sync_group=replica_id):
            result[0] = fn(*replica_args, **replica_kwargs)
        return result[0]
    replicate_inputs = []
    for i in range(strategy.num_replicas_in_sync):
        replicate_inputs.append([constant_op.constant(i, dtype=dtypes.int32), distribute_utils.select_replica(i, args), distribute_utils.select_replica(i, kwargs)])
    if options.experimental_enable_dynamic_batch_size and replicate_inputs:
        maximum_shapes = []
        flattened_list = nest.flatten(replicate_inputs[0])
        for input_tensor in flattened_list:
            if <MASK>:
                rank = input_tensor.shape.rank
            else:
                rank = np.ndim(input_tensor)
            if rank is None:
                raise ValueError('input tensor {} to TPUStrategy.run() has unknown rank, which is not allowed'.format(input_tensor))
            maximum_shape = tensor_shape.TensorShape([None] * rank)
            maximum_shapes.append(maximum_shape)
        maximum_shapes = nest.pack_sequence_as(replicate_inputs[0], maximum_shapes)
    else:
        maximum_shapes = None
    if options.experimental_bucketizing_dynamic_shape:
        padding_spec = tpu.PaddingSpec.POWER_OF_TWO
    else:
        padding_spec = None
    with strategy.scope():
        xla_options = options.experimental_xla_options or tpu.XLAOptions(use_spmd_for_xla_partitioning=self._use_spmd_for_xla_partitioning)
        replicate_outputs = tpu.replicate(replicated_fn, replicate_inputs, device_assignment=self._device_assignment, maximum_shapes=maximum_shapes, padding_spec=padding_spec, xla_options=xla_options)
    filter_ops = lambda x: [o for o in x if not isinstance(o, ops.Operation)]
    if isinstance(result[0], list):
        result[0] = filter_ops(result[0])
    if result[0] is None or isinstance(result[0], ops.Operation):
        replicate_outputs = [None] * len(replicate_outputs)
    else:
        replicate_outputs = [nest.pack_sequence_as(result[0], filter_ops(nest.flatten(output))) for output in replicate_outputs]
    return distribute_utils.regroup(replicate_outputs)

def _pretty_print(data_item, summarize):
    """Format a data item for use in an error message in eager mode.

  Args:
    data_item: One of the items in the "data" argument to an assert_* function.
      Can be a Tensor or a scalar value.
    summarize: How many elements to retain of each tensor-valued entry in data.

  Returns:
    An appropriate string representation of data_item
  """
    if <MASK>:
        arr = data_item.numpy()
        if np.isscalar(arr):
            return str(arr)
        else:
            flat = arr.reshape((-1,))
            lst = [str(x) for x in flat[:summarize]]
            if len(lst) < flat.size:
                lst.append('...')
            return str(lst)
    else:
        return str(data_item)

def _annotate_conv2d_unary(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = []
    unary_patterns = [[torch.nn.Conv2d, torch.nn.ReLU], [torch.nn.Conv2d, torch.nn.Hardtanh], [torch.nn.Conv2d, torch.nn.Hardswish], [torch.nn.Conv2d, torch.nn.ReLU6], [torch.nn.Conv2d, torch.nn.SiLU], [torch.nn.Conv1d, torch.nn.ReLU]]
    for unary_pattern in unary_patterns:
        partitions = find_sequential_partitions(gm, unary_pattern)
        if <MASK>:
            fused_partitions.extend(partitions)
    for fused_partition in fused_partitions:
        (conv_partition, unary_partition) = fused_partition
        (conv_node, unary_node) = self._get_output_nodes_of_partitions([conv_partition, unary_partition])
        if conv_node.op != 'call_function' or conv_node.target not in (torch.ops.aten.conv2d.default, torch.ops.aten.conv1d.default):
            continue
        if _skip_annotate([unary_node, conv_node], filter_fn):
            continue
        if quantization_config is None:
            _annotate_nodes_not_quantize([conv_node, unary_node])
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        unary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(_annotated=True, _is_output_of_quantized_pattern=True)

def _format_regular_rows(self) -> Iterable[ExcelCell]:
    if self._has_aliases or self.header:
        self.rowcounter += 1
    if self.index:
        if self.index_label and isinstance(self.index_label, (list, tuple, np.ndarray, Index)):
            index_label = self.index_label[0]
        elif self.index_label and isinstance(self.index_label, str):
            index_label = self.index_label
        else:
            index_label = self.df.index.names[0]
        if <MASK>:
            self.rowcounter += 1
        if index_label and self.header is not False:
            yield ExcelCell(self.rowcounter - 1, 0, index_label, None)
        index_values = self.df.index
        if isinstance(self.df.index, PeriodIndex):
            index_values = self.df.index.to_timestamp()
        for (idx, idxval) in enumerate(index_values):
            yield CssExcelCell(row=self.rowcounter + idx, col=0, val=idxval, style=None, css_styles=getattr(self.styler, 'ctx_index', None), css_row=idx, css_col=0, css_converter=self.style_converter)
        coloffset = 1
    else:
        coloffset = 0
    yield from self._generate_body(coloffset)

def _validate_path(self) -> list[Any]:
    """
        Notes
        -----
        ``etree`` supports limited ``XPath``. If user attempts a more complex
        expression syntax error will raise.
        """
    msg = 'xpath does not return any nodes or attributes. Be sure to specify in `xpath` the parent nodes of children and attributes to parse. If document uses namespaces denoted with xmlns, be sure to define namespaces and use them in xpath.'
    try:
        elems = self.xml_doc.findall(self.xpath, namespaces=self.namespaces)
        children = [ch for el in elems for ch in el.findall('*')]
        attrs = {k: v for el in elems for (k, v) in el.attrib.items()}
        if elems is None:
            raise ValueError(msg)
        if elems is not None:
            if self.elems_only and children == []:
                raise ValueError(msg)
            if <MASK>:
                raise ValueError(msg)
            if children == [] and attrs == {}:
                raise ValueError(msg)
    except (KeyError, SyntaxError) as err:
        raise SyntaxError('You have used an incorrect or unsupported XPath expression for etree library or you used an undeclared namespace prefix.') from err
    return elems

def ListDevices(self):
    """Returns a list of available hardware devices."""
