def __new__(cls, *args, wrap_storage=None, dtype=None, device=None, _internal=False):
    if <MASK>:
        _warn_typed_storage_removal()
    if cls == torch.storage._LegacyStorage:
        raise RuntimeError('Only child classes of _LegacyStorage can be instantiated')
    if cls == TypedStorage:
        return super().__new__(cls)
    else:
        arg_error_msg = f'{cls}.__new__ received an invalid combination of arguments. Expected one of:\n * no arguments\n * (int size)\n * (Sequence data)\n * (*, UntypedStorage wrap_storage)'
        if device is not None:
            raise RuntimeError(arg_error_msg + "\nKeyword argument 'device' cannot be specified")
        if dtype is not None:
            raise RuntimeError(arg_error_msg + "\nKeyword argument 'dtype' cannot be specified")
        if wrap_storage is None:
            if len(args) > 1:
                raise RuntimeError(arg_error_msg + '\nToo many positional arguments')
            if len(args) == 1 and (not _isint(args[0])) and (not isinstance(args[0], collections.abc.Sequence)):
                raise TypeError(arg_error_msg + f'\nArgument type not recognized: {type(args[0])}')
            return TypedStorage(*args, dtype=cls._dtype, device=_get_device_from_module(cls.__module__), _internal=True)
        else:
            if len(args) != 0:
                raise RuntimeError(arg_error_msg + "\nNo positional arguments should be given when using 'wrap_storage'")
            if not isinstance(wrap_storage, torch.UntypedStorage):
                raise TypeError(arg_error_msg + f"\nArgument 'wrap_storage' must be UntypedStorage, but got {type(wrap_storage)}")
            cls_device = _get_device_from_module(cls.__module__)
            if wrap_storage.device.type != cls_device:
                raise RuntimeError(arg_error_msg + f"\nDevice of 'wrap_storage' must be {cls_device}, but got {wrap_storage.device.type}")
            return TypedStorage(*args, wrap_storage=wrap_storage, dtype=cls.dtype, _internal=True)

def _traverse_state_dict(state_dict: STATE_DICT_TYPE, visitor: Callable[[OBJ_PATH, Any], None]) -> None:
    """
    Invoke ``visitor`` for each value recursively in ``state_dict``.
    Mapping, list, and tuple will be flattened and other value types are treated
    as the terminal values and will invoke ``visitor``.
    """

    def _traverse_obj(path: OBJ_PATH, value: Any) -> None:
        if <MASK>:
            for (k, v) in value.items():
                _traverse_obj(path + (str(k),), v)
        elif isinstance(value, (list, tuple)):
            for (i, v) in enumerate(value):
                _traverse_obj(path + (i,), v)
        else:
            visitor(path, value)
    for (key, value) in state_dict.items():
        _traverse_obj((str(key),), value)

def requires_key_order_guarding(self, source: Source) -> bool:
    source_name = source.name()
    if <MASK>:
        return False
    obj_id = id(self.get(source_name))
    return obj_id in self.key_order_guarded_dict_ids

def scm_root() -> str:
    path = os.path.abspath(os.getcwd())
    while True:
        if os.path.exists(os.path.join(path, '.git')):
            return path
        if <MASK>:
            return path
        n = len(path)
        path = os.path.dirname(path)
        if len(path) == n:
            raise RuntimeError('Unable to find SCM root')

def _unique_np(values, return_inverse=False, return_counts=False):
    """Helper function to find unique values for numpy arrays that correctly
    accounts for nans. See `_unique` documentation for details."""
    (xp, _) = get_namespace(values)
    (inverse, counts) = (None, None)
    if return_inverse and return_counts:
        (uniques, _, inverse, counts) = xp.unique_all(values)
    elif <MASK>:
        (uniques, inverse) = xp.unique_inverse(values)
    elif return_counts:
        (uniques, counts) = xp.unique_counts(values)
    else:
        uniques = xp.unique_values(values)
    if uniques.size and is_scalar_nan(uniques[-1]):
        nan_idx = xp.searchsorted(uniques, xp.nan)
        uniques = uniques[:nan_idx + 1]
        if return_inverse:
            inverse[inverse > nan_idx] = nan_idx
        if return_counts:
            counts[nan_idx] = xp.sum(counts[nan_idx:])
            counts = counts[:nan_idx + 1]
    ret = (uniques,)
    if return_inverse:
        ret += (inverse,)
    if return_counts:
        ret += (counts,)
    return ret[0] if len(ret) == 1 else ret

def should_stop(self):
    """Return true if this session should not be used anymore.

    Always return True if the session was closed.

    Returns:
      True if the session should stop, False otherwise.
    """
    if self._check_stop():
        return True
    if <MASK>:
        return self._wrapped_is_stoppable and self._sess.should_stop()
    return True

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    (inner_fn, source) = self._resolved_getattr_and_source(self, name)
    if inner_fn is object.__init__:
        return LambdaVariable(identity)
    elif <MASK>:
        objvar = self.objvar
        from ..side_effects import AttributeMutationNew
        if isinstance(objvar, variables.UserDefinedObjectVariable) and isinstance(objvar.mutation_type, AttributeMutationNew) and (not (args or kwargs)):
            with do_not_convert_to_tracable_parameter():
                return variables.UserFunctionVariable(unpatched_nn_module_init, source=source).call_function(tx, [self.objvar] + args, kwargs)
        else:
            unimplemented_v2(gb_type='Unsupported super().__init__() call', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'Dynamo encountered a super().__init__() call on {objvar} that resolved to a `torch.nn.Module.__init__()` call that we cannot trace.', hints=[*graph_break_hints.DIFFICULT])
