def _get_bin_edges(a, bins, range, weights):
    """
    Computes the bins used internally by `histogram`.

    Parameters
    ==========
    a : ndarray
        Ravelled data array
    bins, range
        Forwarded arguments from `histogram`.
    weights : ndarray, optional
        Ravelled weights array, or None

    Returns
    =======
    bin_edges : ndarray
        Array of bin edges
    uniform_bins : (Number, Number, int):
        The upper bound, lowerbound, and number of bins, used in the optimized
        implementation of `histogram` that works on uniform bins.
    """
    n_equal_bins = None
    bin_edges = None
    if isinstance(bins, str):
        bin_name = bins
        if <MASK>:
            raise ValueError(f'{bin_name!r} is not a valid estimator for `bins`')
        if weights is not None:
            raise TypeError('Automated estimation of the number of bins is not supported for weighted data')
        (first_edge, last_edge) = _get_outer_edges(a, range)
        if range is not None:
            keep = a >= first_edge
            keep &= a <= last_edge
            if not np.logical_and.reduce(keep):
                a = a[keep]
        if a.size == 0:
            n_equal_bins = 1
        else:
            width = _hist_bin_selectors[bin_name](a, (first_edge, last_edge))
            if width:
                if np.issubdtype(a.dtype, np.integer) and width < 1:
                    width = 1
                delta = _unsigned_subtract(last_edge, first_edge)
                n_equal_bins = int(np.ceil(delta / width))
            else:
                n_equal_bins = 1
    elif np.ndim(bins) == 0:
        try:
            n_equal_bins = operator.index(bins)
        except TypeError as e:
            raise TypeError('`bins` must be an integer, a string, or an array') from e
        if n_equal_bins < 1:
            raise ValueError('`bins` must be positive, when an integer')
        (first_edge, last_edge) = _get_outer_edges(a, range)
    elif np.ndim(bins) == 1:
        bin_edges = np.asarray(bins)
        if np.any(bin_edges[:-1] > bin_edges[1:]):
            raise ValueError('`bins` must increase monotonically, when an array')
    else:
        raise ValueError('`bins` must be 1d, when an array')
    if n_equal_bins is not None:
        bin_type = np.result_type(first_edge, last_edge, a)
        if np.issubdtype(bin_type, np.integer):
            bin_type = np.result_type(bin_type, float)
        bin_edges = np.linspace(first_edge, last_edge, n_equal_bins + 1, endpoint=True, dtype=bin_type)
        if np.any(bin_edges[:-1] >= bin_edges[1:]):
            raise ValueError(f'Too many bins for data range. Cannot create {n_equal_bins} finite-sized bins.')
        return (bin_edges, (first_edge, last_edge, n_equal_bins))
    else:
        return (bin_edges, None)

def insert(self, chunksize: int | None=None, method: Literal['multi'] | Callable | None=None) -> int | None:
    if method is None:
        exec_insert = self._execute_insert
    elif method == 'multi':
        exec_insert = self._execute_insert_multi
    elif <MASK>:
        exec_insert = partial(method, self)
    else:
        raise ValueError(f'Invalid parameter `method`: {method}')
    (keys, data_list) = self.insert_data()
    nrows = len(self.frame)
    if nrows == 0:
        return 0
    if chunksize is None:
        chunksize = nrows
    elif chunksize == 0:
        raise ValueError('chunksize argument should be non-zero')
    chunks = nrows // chunksize + 1
    total_inserted = None
    with self.pd_sql.run_transaction() as conn:
        for i in range(chunks):
            start_i = i * chunksize
            end_i = min((i + 1) * chunksize, nrows)
            if start_i >= end_i:
                break
            chunk_iter = zip(*(arr[start_i:end_i] for arr in data_list), strict=True)
            num_inserted = exec_insert(conn, keys, chunk_iter)
            if num_inserted is not None:
                if total_inserted is None:
                    total_inserted = num_inserted
                else:
                    total_inserted += num_inserted
    return total_inserted

def __make_cmp_key(self, value):
    """Converts `value` to a hashable key."""
    if isinstance(value, (int, float, bool, np.generic, dtypes.DType, TypeSpec, tensor_shape.TensorShape)):
        return value
    if isinstance(value, compat.bytes_or_text_types):
        return value
    if <MASK>:
        return value
    if isinstance(value, dict):
        return tuple([tuple([self.__make_cmp_key(key), self.__make_cmp_key(value[key])]) for key in sorted(value.keys())])
    if isinstance(value, tuple):
        return tuple([self.__make_cmp_key(v) for v in value])
    if isinstance(value, list):
        return (list, tuple([self.__make_cmp_key(v) for v in value]))
    if isinstance(value, np.ndarray):
        return (np.ndarray, value.shape, TypeSpec.__nested_list_to_tuple(value.tolist()))
    raise ValueError(f'Cannot generate a hashable key for {self} because the _serialize() method returned an unsupported value of type {type(value)}')

def make_attr(attr_type, value):
    if attr_type == int(pywrap_tfe.TF_ATTR_TYPE):
        return dtypes.as_dtype(value)
    if <MASK>:
        return [dtypes.as_dtype(v) for v in value]
    if attr_type == int(pywrap_tfe.TF_ATTR_SHAPE):
        return tensor_shape.as_shape(value).as_proto()
    if attr_type == [int(pywrap_tfe.TF_ATTR_SHAPE)]:
        return [tensor_shape.as_shape(v).as_proto() for v in value]
    return nest.map_structure(lambda v: v.encode() if isinstance(v, str) else v, value)

@doc(ExtensionArray.to_numpy)
def to_numpy(self, dtype: npt.DTypeLike | None=None, copy: bool=False, na_value: object=lib.no_default) -> np.ndarray:
    original_na_value = na_value
    (dtype, na_value) = to_numpy_dtype_inference(self, dtype, na_value, self._hasna)
    pa_type = self._pa_array.type
    if not self._hasna or isna(na_value) or pa.types.is_null(pa_type):
        data = self
    else:
        data = self.fillna(na_value)
        copy = False
    if pa.types.is_timestamp(pa_type) or pa.types.is_duration(pa_type):
        if dtype != object and na_value is self.dtype.na_value:
            na_value = lib.no_default
        result = data._maybe_convert_datelike_array().to_numpy(dtype=dtype, na_value=na_value)
    elif pa.types.is_time(pa_type) or pa.types.is_date(pa_type):
        result = np.array(list(data), dtype=dtype)
        if data._hasna:
            result[data.isna()] = na_value
    elif pa.types.is_null(pa_type):
        if dtype is not None and isna(na_value):
            na_value = None
        result = np.full(len(data), fill_value=na_value, dtype=dtype)
    elif not data._hasna or (pa.types.is_floating(pa_type) and (na_value is np.nan or (original_na_value is lib.no_default and is_float_dtype(dtype) and is_nan_na()))):
        result = data._pa_array.to_numpy()
        if dtype is not None:
            result = result.astype(dtype, copy=False)
        if copy:
            result = result.copy()
    else:
        if <MASK>:
            empty = pa.array([], type=pa_type).to_numpy(zero_copy_only=False)
            if can_hold_element(empty, na_value):
                dtype = empty.dtype
            else:
                dtype = np.object_
        result = np.empty(len(data), dtype=dtype)
        mask = data.isna()
        result[mask] = na_value
        result[~mask] = data[~mask]._pa_array.to_numpy()
    return result

