        elif <MASK>:
            return inputs[:, :, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1], self.cropping[2][0]:]
        return inputs[:, :, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1], self.cropping[2][0]:-self.cropping[2][1]]
    else:
        if self.cropping[0][1] == self.cropping[1][1] == self.cropping[2][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:, self.cropping[2][0]:, :]
        elif self.cropping[0][1] == self.cropping[1][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:, self.cropping[2][0]:-self.cropping[2][1], :]
        elif self.cropping[1][1] == self.cropping[2][1] == 0:
            return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:, self.cropping[2][0]:, :]
        elif self.cropping[0][1] == self.cropping[2][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:-self.cropping[1][1], self.cropping[2][0]:, :]
        elif self.cropping[0][1] == 0:
            return inputs[:, self.cropping[0][0]:, self.cropping[1][0]:-self.cropping[1][1], self.cropping[2][0]:-self.cropping[2][1], :]
        elif self.cropping[1][1] == 0:
            return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:, self.cropping[2][0]:-self.cropping[2][1], :]
        elif self.cropping[2][1] == 0:
            return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1], self.cropping[2][0]:, :]
        return inputs[:, self.cropping[0][0]:-self.cropping[0][1], self.cropping[1][0]:-self.cropping[1][1], self.cropping[2][0]:-self.cropping[2][1], :]

