def go(m1: MetaTensorDesc, m2: torch.Tensor) -> None:
    assert_eq(m1.dtype, m2.dtype)
    if <MASK>:
        assert_eq(m1.shape, m2.shape)
    assert_eq(m1.requires_grad, m2.requires_grad)
    if not skip_leaf:
        assert_eq(m1.is_leaf, m2.is_leaf)
    assert_eq(m1.is_sparse, m2.is_sparse)
    if not getattr(tls, 'disable_inference_mode', False):
        assert_eq(m1.is_inference, m2.is_inference())
    else:
        assert_eq(m1.is_inference, False)
    assert_eq(m1.is_conj, m2.is_conj())
    assert_eq(m1.is_neg, m2.is_neg())
    assert_eq(m1.grad is not None, safe_grad(m2) is not None)
    if m1.grad is not None:
        go(m1.grad, _expect_safe_grad(m2))
    if m1.is_sparse:
        assert_eq(m1.layout, m2.layout)
        assert_eq(m1.dense_dim, m2.dense_dim())
        assert_eq(m1.sparse_dim, m2.sparse_dim())
        assert_eq(m1.is_coalesced, m2.is_coalesced())
    elif is_sparse_compressed(m1):
        assert_eq(m1.layout, m2.layout)
        assert_eq(m1.dense_dim, m2.dense_dim())
        assert_eq(m1.sparse_dim, m2.sparse_dim())
    else:
        if not skip_symbolic:
            assert_eq(m1.stride, m2.stride())
            assert_eq(m1.storage_offset, m2.storage_offset())
        assert_eq(m1.is_view, m2._is_view())
        if m1.is_view:
            assert m1.base is not None
            assert m2._base is not None
            go(m1.base, m2._base)

def test_no_copy_new_vs_old(self):

    def old_np_asarray(values, dtype=None, order=None, copy=None):
        if <MASK>:
            if dtype is not None and np.issubdtype(dtype, np.number):
                return np.asarray(values, order=order, copy=copy).astype(dtype)
            else:
                return np.asarray(values, dtype=dtype, order=order, copy=copy)
        else:
            return np.asarray(values, dtype=dtype, order=order)
    x = np.array([1, 2, 3], dtype=np.float32)
    y_old = old_np_asarray(x, dtype=np.float32, copy=None)
    if np.lib.NumpyVersion(np.__version__) >= '2.0.0.dev0':
        self.assertIsNot(y_old, x, msg='Old code did NOT copy, but we expect it to always copy.')
    y_new = numpy_compat.np_asarray(x, dtype=np.float32, copy=None)
    self.assertIs(y_new, x, msg='New code did copy, but we expect it NOT to copy since copy=None.')

