def _backward_function_wrapper(*args):
    """Process output gradients and call the backward function."""
    if not backward.outputs:
        return backward.structured_outputs
    processed_args = []
    input_index = 0
    for (output_index, arg) in enumerate(args):
        if isinstance(arg, indexed_slices.IndexedSlices):
            arg = ops.convert_to_tensor(arg)
        if output_index in skip_positions:
            continue
        if arg is None:
            input_placeholder = backward.inputs[input_index]
            if input_placeholder.dtype == dtypes.variant:
                arg = variant_zeros_like[output_index]
            else:
                arg = array_ops.zeros(*default_gradient.shape_and_dtype(input_placeholder))
        processed_args.append(arg)
        input_index += 1
        if <MASK>:
            break
    return backward._call_flat(processed_args, remapped_captures)

@classmethod
def match_mod_div_block_expr(cls, index: Expr, index_var: Symbol, numel: Expr, num_dims: int) -> Optional[tuple[list[Expr], list[Expr], list[Expr]]]:
    """
        Matches modular indexing expressions, converting them to implied block dimensions and strides.
        See triton.py for more information.
        """
    index = cls._preprocess(index)
    wild_unsigned_int = functools.partial(cls._indexing_wild_unsigned_int, exclude=[index_var])
    wild_signed_int = functools.partial(cls._indexing_wild_signed_int, exclude=[index_var])
    dims: list[Expr] = [wild_unsigned_int(f'dim_mod{idx}') for idx in range(num_dims)]
    strides: list[Expr] = [wild_signed_int(f'stride_mod{idx}') for idx in range(num_dims)]
    slice_numels = cls.get_slice_numels(dims[:num_dims])
    block_index_exprs = [FloorDiv(index_var, slice_numels[0])] + [ModularIndexing(index_var, numel, dim) for (dim, numel) in zip(dims[1:], slice_numels[1:])]
    match_expr = sympy_dot(strides, block_index_exprs)
    if num_dims >= 5:
        stride = sympy.symbols('stride', cls=wild_signed_int)
        (denom, other) = sympy.symbols('denominator other', cls=wild_unsigned_int)
        mod_div_pattern = stride * ModularIndexing(index_var, denom, other)
        floor_div_pattern = stride * FloorDiv(index_var, denom)
        first_dim_floor_div_matched = False
        match_failed = False
        for arg in sympy.Add.make_args(index):
            if <MASK>:
                if first_dim_floor_div_matched:
                    match_failed = True
                    break
                first_dim_floor_div_matched = True
            elif arg.match(mod_div_pattern):
                continue
            else:
                match_failed = True
                break
        if match_failed:
            return None
    match = index.match(match_expr)
    if match is None:
        return None
    for dim in dims[1:]:
        if dim not in match:
            match[dim] = sympy.S.One
    for stride in strides[1:]:
        if stride not in match:
            match[stride] = sympy.S.Zero
    sizevars = V.graph.sizevars

    def get_match(expr: Expr) -> Expr:
        return sizevars.lookup_precomputed_size(match[expr])
    dims = [dims[0]] + [get_match(dim) for dim in dims[1:]]
    strides = [get_match(stride) for stride in strides]
    slice_numels = cls.get_slice_numels(dims)
    block_index_exprs = [sympy_subs(expr, match) for expr in block_index_exprs]
    assert dims[0] not in match, 'Expected not to match the leading dimension!'
    if not sizevars.statically_known_multiple_of(numel, slice_numels[0]):
        return None
    dims[0] = numel / slice_numels[0]
    matched_index = sympy_dot(strides, block_index_exprs)
    assert sizevars.statically_known_equals(sizevars.remove_precomputed_replacements(matched_index), sizevars.remove_precomputed_replacements(index)), textwrap.dedent(f'\n            Invalid match!\n            Index: {index}\n            Matched expression: {matched_index}\n            ')
    return (dims, strides, block_index_exprs)

def _validate_key(ctx: click.Context, param: click.Parameter, value: t.Any) -> t.Any:
    """The ``--key`` option must be specified when ``--cert`` is a file.
    Modifies the ``cert`` param to be a ``(cert, key)`` pair if needed.
    """
    cert = ctx.params.get('cert')
    is_adhoc = cert == 'adhoc'
    try:
        import ssl
    except ImportError:
        is_context = False
    else:
        is_context = isinstance(cert, ssl.SSLContext)
    if value is not None:
        if is_adhoc:
            raise click.BadParameter('When "--cert" is "adhoc", "--key" is not used.', ctx, param)
        if is_context:
            raise click.BadParameter('When "--cert" is an SSLContext object, "--key" is not used.', ctx, param)
        if <MASK>:
            raise click.BadParameter('"--cert" must also be specified.', ctx, param)
        ctx.params['cert'] = (cert, value)
    elif cert and (not (is_adhoc or is_context)):
        raise click.BadParameter('Required when using "--cert".', ctx, param)
    return value

