def _pull_records(js: dict[str, Any], spec: list | str) -> list:
    """
        Internal function to pull field for records, and similar to
        _pull_field, but require to return list. And will raise error
        if has non iterable value.
        """
    result = _pull_field(js, spec, extract_record=True)
    if not isinstance(result, list):
        if <MASK>:
            result = []
        else:
            raise TypeError(f'Path must contain list or null, but got {type(result).__name__} at {spec!r}')
    return result

def _handle_compute(self, node: fx.Node) -> None:
    """Handle scheduling compute and finding overlaps."""
    compute_time = benchmark_node(node)
    available_compute = compute_time * self.compute_overlap_multipler
    for info in self.in_flight.values():
        if info.exposed_time_ms == 0:
            continue
        overlap_amount = min(info.exposed_time_ms, available_compute)
        info.exposed_time_ms -= overlap_amount
        available_compute -= overlap_amount
        if info.exposed_time_ms == 0:
            info.hiding_node = node
        elif available_compute == 0:
            break
    if <MASK>:
        self._schedule_collectives_for_overlap(node, available_compute)
    self._schedule(node)
    self.current_compute_index += 1

def forward(self, input, hx=None):
    orig_input = input
    if isinstance(orig_input, PackedSequence):
        (input, batch_sizes, sorted_indices, unsorted_indices) = input
        max_batch_size = int(batch_sizes[0])
    else:
        batch_sizes = None
        assert input.dim() in (2, 3), f'GRU: Expected input to be 2-D or 3-D but received {input.dim()}-D tensor'
        is_batched = input.dim() == 3
        batch_dim = 0 if self.batch_first else 1
        if <MASK>:
            input = input.unsqueeze(batch_dim)
            if hx is not None:
                if hx.dim() != 2:
                    raise RuntimeError(f'For unbatched 2-D input, hx should also be 2-D but got {hx.dim()}-D tensor')
                hx = hx.unsqueeze(1)
        elif hx is not None and hx.dim() != 3:
            raise RuntimeError(f'For batched 3-D input, hx should also be 3-D but got {hx.dim()}-D tensor')
        max_batch_size = input.size(0) if self.batch_first else input.size(1)
        sorted_indices = None
        unsorted_indices = None
    if hx is None:
        num_directions = 2 if self.bidirectional else 1
        hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
    else:
        hx = self.permute_hidden(hx, sorted_indices)
    self.check_forward_args(input, hx, batch_sizes)
    if batch_sizes is None:
        result = _VF.gru(input, hx, self.get_flat_weights(), self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
    else:
        result = _VF.gru(input, batch_sizes, hx, self.get_flat_weights(), self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    output = result[0]
    hidden = result[1]
    if isinstance(orig_input, PackedSequence):
        output_packed = PackedSequence(output, batch_sizes, sorted_indices, unsorted_indices)
        return (output_packed, self.permute_hidden(hidden, unsorted_indices))
    else:
        if not is_batched:
            output = output.squeeze(batch_dim)
            hidden = hidden.squeeze(1)
        return (output, self.permute_hidden(hidden, unsorted_indices))

