def _get_global_builtins():
    supported_builtins = ['print', 'tuple', 'float', 'complex', 'int', 'bool', 'str', 'getattr', 'hasattr', 'isinstance', 'len', 'hex', 'oct', 'round', 'hash', 'min', 'max', 'abs', 'all', 'divmod', 'list', 'ord', 'chr', 'bin', 'range', 'zip', 'enumerate', 'sorted']
    op_renames = {'bool': 'aten::Bool', 'int': 'aten::Int', 'float': 'aten::Float', 'complex': 'aten::Complex', 'abs': 'prim::abs', 'max': 'prim::max', 'min': 'prim::min', 'range': 'fake::does_not_exist'}
    schemaless_op_explanations = {'print': 'Print any value', 'tuple': 'Lists cannot be converted to tuples with this method since their size is not statically known', 'getattr': 'Attribute name must be a literal string', 'hasattr': 'Attribute name must be a literal string', 'isinstance': 'Result is static', 'zip': 'Arguments must be iterable.', 'enumerate': 'Arguments must be iterable.', 'range': 'Can only be used as an iterator in a for loop'}
    magic_methods = [('complex', '__complex__'), ('float', '__float__'), ('int', '__int__'), ('bool', '__bool__'), ('str', '__str__'), ('len', '__len__'), ('hex', '__hex__'), ('oct', '__oct__')]
    magic_methods_rows = []
    for (fn, magic_method) in magic_methods:
        magic_methods_rows.append(f'"{fn}", "``{magic_method}``"')
    schematized_ops = []
    schemaless_ops = []
    for fn in supported_builtins:
        op_name = f'aten::{fn}'
        if <MASK>:
            op_name = op_renames[fn]
        schemas = torch._C._jit_get_schemas_for_operator(op_name)
        for s in schemas:
            schematized_ops.append(_emit_schema(None, fn, s, padding=0))
        if len(schemas) > 0:
            schematized_ops.append('')
        else:
            table_row = f'":external+python:py:obj:`{fn}`", "{schemaless_op_explanations[fn]}"'
            schemaless_ops.append(table_row)
    schematized_ops_str = '\n'.join(schematized_ops)
    schemaless_ops_str = '\n'.join(schemaless_ops)
    magic_methods_rows_str = '\n'.join(magic_methods_rows)
    schematized_ops_str = textwrap.indent(schematized_ops_str, '\t')
    schemaless_ops_str = textwrap.indent(schemaless_ops_str, '\t')
    magic_methods_rows_str = textwrap.indent(magic_methods_rows_str, '\t')
    section = f'\nThe functions in the following table are supported but do not have a static schema\n\n.. csv-table::\n    :header: "Function", "Note"\n\n{schemaless_ops_str}\n\nThe following functions will use the corresponding magic method on TorchScript classes\n\n.. csv-table::\n    :header: "Function", "Magic Method"\n\n{magic_methods_rows_str}\n\nThese built-in functions use the schema\n\n.. rst-class:: codeblock-height-limiter\n\n::\n\n{schematized_ops_str}\n    '
    return ('Python Built-in Functions', section)

def _to_proto(self):
    pb = dataset_options_pb2.OptimizationOptions()
    if self.apply_default_optimizations is not None:
        pb.apply_default_optimizations = self.apply_default_optimizations
    if self.filter_fusion is not None:
        pb.filter_fusion = self.filter_fusion
    if <MASK>:
        pb.filter_parallelization = self.filter_parallelization
    if self.inject_prefetch is not None:
        pb.inject_prefetch = self.inject_prefetch
    if self.seq_interleave_prefetch is not None:
        pb.seq_interleave_prefetch = self.seq_interleave_prefetch
    if self.map_and_batch_fusion is not None:
        pb.map_and_batch_fusion = self.map_and_batch_fusion
    if self.map_and_filter_fusion is not None:
        pb.map_and_filter_fusion = self.map_and_filter_fusion
    if self.map_fusion is not None:
        pb.map_fusion = self.map_fusion
    if self.map_parallelization is not None:
        pb.map_parallelization = self.map_parallelization
    if self.noop_elimination is not None:
        pb.noop_elimination = self.noop_elimination
    if self.parallel_batch is not None:
        pb.parallel_batch = self.parallel_batch
    if self.shuffle_and_repeat_fusion is not None:
        pb.shuffle_and_repeat_fusion = self.shuffle_and_repeat_fusion
    return pb

def reset_states(self, states=None):
    if not self.stateful:
        raise AttributeError('Layer must be stateful.')
    input_shape = self.input_spec[0].shape
    state_shape = self.compute_output_shape(input_shape)
    if self.return_state:
        state_shape = state_shape[0]
    if self.return_sequences:
        state_shape = state_shape[:1].concatenate(state_shape[2:])
    if None in state_shape:
        raise ValueError('If a RNN is stateful, it needs to know its batch size. Specify the batch size of your input tensors: \n- If using a Sequential model, specify the batch size by passing a `batch_input_shape` argument to your first layer.\n- If using the functional API, specify the time dimension by passing a `batch_shape` argument to your Input layer.\nThe same thing goes for the number of rows and columns.')

    def get_tuple_shape(nb_channels):
        result = list(state_shape)
        if self.cell.data_format == 'channels_first':
            result[1] = nb_channels
        elif <MASK>:
            result[3] = nb_channels
        else:
            raise KeyError
        return tuple(result)
    if self.states[0] is None:
        if hasattr(self.cell.state_size, '__len__'):
            self.states = [backend.zeros(get_tuple_shape(dim)) for dim in self.cell.state_size]
        else:
            self.states = [backend.zeros(get_tuple_shape(self.cell.state_size))]
    elif states is None:
        if hasattr(self.cell.state_size, '__len__'):
            for (state, dim) in zip(self.states, self.cell.state_size):
                backend.set_value(state, np.zeros(get_tuple_shape(dim)))
        else:
            backend.set_value(self.states[0], np.zeros(get_tuple_shape(self.cell.state_size)))
    else:
        if not isinstance(states, (list, tuple)):
            states = [states]
        if len(states) != len(self.states):
            raise ValueError('Layer ' + self.name + ' expects ' + str(len(self.states)) + ' states, ' + 'but it received ' + str(len(states)) + ' state values. Input received: ' + str(states))
        for (index, (value, state)) in enumerate(zip(states, self.states)):
            if hasattr(self.cell.state_size, '__len__'):
                dim = self.cell.state_size[index]
            else:
                dim = self.cell.state_size
            if value.shape != get_tuple_shape(dim):
                raise ValueError('State ' + str(index) + ' is incompatible with layer ' + self.name + ': expected shape=' + str(get_tuple_shape(dim)) + ', found shape=' + str(value.shape))
            backend.set_value(state, value)

def batch(self, spec, batch_size):
    """Returns the TypeSpec representing a batch of values described by `spec`.

    The default definition returns a `TypeSpec` that is equal to `spec`, except
    that an outer axis with size `batch_size` is added to every nested
    `TypeSpec` and `TensorShape` field.  Subclasses may override this default
    definition, when necessary.

    Args:
      spec: The `TypeSpec` for an individual value.
      batch_size: An `int` indicating the number of values that are batched
        together, or `None` if the batch size is not known.

    Returns:
      A `TypeSpec` for a batch of values.
    """

    def batch_field(f):
        if <MASK>:
            return f.__batch_encoder__.batch(f, batch_size)
        elif isinstance(f, tensor_shape.TensorShape):
            return [batch_size] + f
        else:
            return f
    fields = tuple(spec.__dict__.items())
    batched_fields = nest.map_structure(batch_field, fields)
    return _create_object_from_type_and_dict(type(spec), batched_fields)

def _validate_sample_input_sparse_reduction(op_info, sample, check_validate=False):
    """Return the specified sample when it is valid and supported by the
    operation. Otherwise, return the sample as ErrorInput instance.

    When check_validate is True, the result is validated against
    calling the op on the sample.
    """
    UNSPECIFIED = object()
    if op_info.name == 'sum':
        sample = _validate_sample_input_sparse_reduction_sum(sample)
    if op_info.name == 'masked.sum':
        mask = sample.kwargs.get('mask', UNSPECIFIED)
        if mask not in {None, UNSPECIFIED} and mask.ndim > 2 and (mask.layout is torch.strided) and (mask == 0).any():
            sample = ErrorInput(sample, error_regex='Expect the same number of specified elements per batch.')
        elif not sample.kwargs.get('keepdim'):
            sample = ErrorInput(sample, error_type=(AssertionError, RuntimeError), error_regex='reduction operations on (CSR|CSC) tensors with keepdim=False is unsupported')
        elif mask is UNSPECIFIED:
            sample = ErrorInput(sample, error_type=ValueError, error_regex='masked (.*) expects explicit mask for sparse_csr tensor input')
        elif <MASK>:
            sample = ErrorInput(sample, error_regex='crow_indices is supposed to be a vector, but got 3 dimensional tensor.')
    if op_info.name in {'masked.amax', 'masked.amin', 'masked.mean', 'masked.prod'}:
        t_inp = sample.input
        mask = sample.kwargs.get('mask')
        if mask is not None and mask.ndim > 2 and (mask.layout is torch.strided) and (mask == 0).any():
            sample = ErrorInput(sample, error_regex='Expect the same number of specified elements per batch.')
        elif mask is None:
            sample = ErrorInput(sample, error_type=ValueError, error_regex='masked (.*) expects explicit mask for sparse_csr tensor input')
        elif mask.layout is sample.input.layout and mask.ndim > 2 and (op_info.name == 'masked.mean'):
            sample = ErrorInput(sample, error_type=TypeError, error_regex='where[(][)] received an invalid combination of arguments - got [(]Tensor, Tensor, NoneType[)]')
        elif not sample.kwargs.get('keepdim'):
            sample = ErrorInput(sample, error_type=(AssertionError, RuntimeError), error_regex='reduction operations on (CSR|CSC) tensors with keepdim=False is unsupported')
        elif sample.input.ndim > 2 and sample.kwargs.get('dim') not in {0, 1} and (mask.ndim > 2) and (mask.layout is not torch.strided):
            if sample.kwargs.get('dim') == (0, -1):
                sample = ErrorInput(sample, error_regex='tensor dimensionality must be sum of batch, base, and dense dimensionalities')
            elif op_info.name == 'masked.prod':
                sample = ErrorInput(sample, error_regex='input_dim == 2 INTERNAL ASSERT FAILED at')
            else:
                sample = ErrorInput(sample, error_type=AssertionError, error_regex='Sparse CSR tensors are 2D and only support reduction along dim 0 or 1.')
        elif sample.input.ndim > 2:
            sample = ErrorInput(sample, error_regex='crow_indices is supposed to be a vector, but got 3 dimensional tensor.')
        elif mask.layout is t_inp.layout and mask._nnz() != t_inp._nnz() and (t_inp.dense_dim() > 0):
            sample = ErrorInput(sample, error_regex='Index tensor must have the same number of dimensions as src tensor')
    if check_validate:
        _check_validate(op_info, sample)
    return sample

def __init__(self, values: Optional[Iterable[Any]]=None) -> None:
    super().__init__()
    self._size = 0
    if <MASK>:
        self += values

def _raise(left, right, err_msg) -> NoReturn:
    if <MASK>:
        if left.shape != right.shape:
            raise_assert_detail(obj, f'{obj} shapes are different', left.shape, right.shape)
        diff = 0
        for (left_arr, right_arr) in zip(left, right, strict=True):
            if not array_equivalent(left_arr, right_arr, strict_nan=strict_nan):
                diff += 1
        diff = diff * 100.0 / left.size
        msg = f'{obj} values are different ({np.round(diff, 5)} %)'
        raise_assert_detail(obj, msg, left, right, index_values=index_values)
    raise AssertionError(err_msg)

def get_join_indexers(left_keys: list[ArrayLike], right_keys: list[ArrayLike], sort: bool=False, how: JoinHow='inner') -> tuple[npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    """

    Parameters
    ----------
    left_keys : list[ndarray, ExtensionArray, Index, Series]
    right_keys : list[ndarray, ExtensionArray, Index, Series]
    sort : bool, default False
    how : {'inner', 'outer', 'left', 'right'}, default 'inner'

    Returns
    -------
    np.ndarray[np.intp] or None
        Indexer into the left_keys.
    np.ndarray[np.intp] or None
        Indexer into the right_keys.
    """
    assert len(left_keys) == len(right_keys), 'left_keys and right_keys must be the same length'
    left_n = len(left_keys[0])
    right_n = len(right_keys[0])
    if left_n == 0:
        if how in ['left', 'inner']:
            return _get_empty_indexer()
        elif <MASK>:
            return _get_no_sort_one_missing_indexer(right_n, True)
    elif right_n == 0:
        if how in ['right', 'inner']:
            return _get_empty_indexer()
        elif not sort and how in ['left', 'outer']:
            return _get_no_sort_one_missing_indexer(left_n, False)
    lkey: ArrayLike
    rkey: ArrayLike
    if len(left_keys) > 1:
        mapped = (_factorize_keys(left_keys[n], right_keys[n], sort=sort) for n in range(len(left_keys)))
        zipped = zip(*mapped)
        (llab, rlab, shape) = (list(x) for x in zipped)
        (lkey, rkey) = _get_join_keys(llab, rlab, tuple(shape), sort)
    else:
        lkey = left_keys[0]
        rkey = right_keys[0]
    left = Index(lkey)
    right = Index(rkey)
    if left.is_monotonic_increasing and right.is_monotonic_increasing and (left.is_unique or right.is_unique):
        (_, lidx, ridx) = left.join(right, how=how, return_indexers=True, sort=sort)
    else:
        (lidx, ridx) = get_join_indexers_non_unique(left._values, right._values, sort, how)
    if lidx is not None and is_range_indexer(lidx, len(left)):
        lidx = None
    if ridx is not None and is_range_indexer(ridx, len(right)):
        ridx = None
    return (lidx, ridx)

def _assign_attr(from_obj: Union[torch.Tensor, torch.ScriptObject, torch.nn.Module], to_module: torch.nn.Module, target: str, attr_kind: _AttrKind, persistent: bool=True):
    (*prefix, field) = target.split('.')
    to_modules = {to_module}
    for item in prefix:
        ts: set[torch.nn.Module] = set()
        for to_module in to_modules:
            if not hasattr(to_module, item):
                setattr(to_module, item, torch.nn.Module())
            ts.update((t_call for (k, t_call) in to_module._modules.items() if _is_call_name(k, item)))
        to_modules = ts
    for to_module in to_modules:
        if <MASK>:
            assert isinstance(from_obj, torch.nn.Parameter)
            to_module.register_parameter(field, from_obj)
        elif attr_kind == _AttrKind.BUFFER:
            assert isinstance(from_obj, torch.Tensor)
            to_module.register_buffer(field, from_obj, persistent=persistent)
        elif attr_kind == _AttrKind.CONSTANT:
            assert not isinstance(from_obj, FakeScriptObject), 'FakeScriptObject should only exist during tracing.'
            assert isinstance(from_obj, (torch.Tensor, torch.ScriptObject))
            setattr(to_module, field, from_obj)
        elif attr_kind == _AttrKind.MODULE:
            assert isinstance(from_obj, torch.nn.Module)
            setattr(to_module, field, from_obj)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    """
        Build a forest of trees from the training set (X, y).

        Parameters
        ----------
        X : {array-like, sparse matrix} of shape (n_samples, n_features)
            The training input samples. Internally, its dtype will be converted
            to ``dtype=np.float32``. If a sparse matrix is provided, it will be
            converted into a sparse ``csc_matrix``.

        y : array-like of shape (n_samples,) or (n_samples, n_outputs)
            The target values (class labels in classification, real numbers in
            regression).

        sample_weight : array-like of shape (n_samples,), default=None
            Sample weights. If None, then samples are equally weighted. Splits
            that would create child nodes with net zero or negative weight are
            ignored while searching for a split in each node. In the case of
            classification, splits are also ignored if they would result in any
            single class carrying a negative weight in either child node.

        Returns
        -------
        self : object
            Fitted estimator.
        """
    if issparse(y):
        raise ValueError('sparse multilabel-indicator for y is not supported.')
    (X, y) = validate_data(self, X, y, multi_output=True, accept_sparse='csc', dtype=DTYPE, ensure_all_finite=False)
    estimator = type(self.estimator)(criterion=self.criterion)
    missing_values_in_feature_mask = estimator._compute_missing_values_in_feature_mask(X, estimator_name=self.__class__.__name__)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if issparse(X):
        X.sort_indices()
    y = np.atleast_1d(y)
    if y.ndim == 2 and y.shape[1] == 1:
        warn('A column-vector y was passed when a 1d array was expected. Please change the shape of y to (n_samples,), for example using ravel().', DataConversionWarning, stacklevel=2)
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    if self.criterion == 'poisson':
        if np.any(y < 0):
            raise ValueError('Some value(s) of y are negative which is not allowed for Poisson regression.')
        if np.sum(y) <= 0:
            raise ValueError('Sum of y is not strictly positive which is necessary for Poisson regression.')
    (self._n_samples, self.n_outputs_) = y.shape
    (y, expanded_class_weight) = self._validate_y_class_weight(y)
    if getattr(y, 'dtype', None) != DOUBLE or not y.flags.contiguous:
        y = np.ascontiguousarray(y, dtype=DOUBLE)
    if <MASK>:
        if sample_weight is not None:
            sample_weight = sample_weight * expanded_class_weight
        else:
            sample_weight = expanded_class_weight
    if not self.bootstrap and self.max_samples is not None:
        raise ValueError('`max_sample` cannot be set if `bootstrap=False`. Either switch to `bootstrap=True` or set `max_sample=None`.')
    elif self.bootstrap:
        n_samples_bootstrap = _get_n_samples_bootstrap(n_samples=X.shape[0], max_samples=self.max_samples)
    else:
        n_samples_bootstrap = None
    self._n_samples_bootstrap = n_samples_bootstrap
    self._validate_estimator()
    if not self.bootstrap and self.oob_score:
        raise ValueError('Out of bag estimation only available if bootstrap=True')
    random_state = check_random_state(self.random_state)
    if not self.warm_start or not hasattr(self, 'estimators_'):
        self.estimators_ = []
    n_more_estimators = self.n_estimators - len(self.estimators_)
    if n_more_estimators < 0:
        raise ValueError('n_estimators=%d must be larger or equal to len(estimators_)=%d when warm_start==True' % (self.n_estimators, len(self.estimators_)))
    elif n_more_estimators == 0:
        warn('Warm-start fitting without increasing n_estimators does not fit new trees.')
    else:
        if self.warm_start and len(self.estimators_) > 0:
            random_state.randint(MAX_INT, size=len(self.estimators_))
        trees = [self._make_estimator(append=False, random_state=random_state) for i in range(n_more_estimators)]
        trees = Parallel(n_jobs=self.n_jobs, verbose=self.verbose, prefer='threads')((delayed(_parallel_build_trees)(t, self.bootstrap, X, y, sample_weight, i, len(trees), verbose=self.verbose, class_weight=self.class_weight, n_samples_bootstrap=n_samples_bootstrap, missing_values_in_feature_mask=missing_values_in_feature_mask) for (i, t) in enumerate(trees)))
        self.estimators_.extend(trees)
    if self.oob_score and (n_more_estimators > 0 or not hasattr(self, 'oob_score_')):
        y_type = type_of_target(y)
        if y_type == 'unknown' or (is_classifier(self) and y_type == 'multiclass-multioutput'):
            raise ValueError(f'The type of target cannot be used to compute OOB estimates. Got {y_type} while only the following are supported: continuous, continuous-multioutput, binary, multiclass, multilabel-indicator.')
        if callable(self.oob_score):
            self._set_oob_score_and_attributes(X, y, scoring_function=self.oob_score)
        else:
            self._set_oob_score_and_attributes(X, y)
    if hasattr(self, 'classes_') and self.n_outputs_ == 1:
        self.n_classes_ = self.n_classes_[0]
        self.classes_ = self.classes_[0]
    return self

def as_terms(obj):
    """Return expression as TERMS expression.
    """
    if isinstance(obj, Expr):
        obj = normalize(obj)
        if obj.op is Op.TERMS:
            return obj
        if <MASK>:
            return Expr(Op.TERMS, {as_integer(1, obj.data[1]): obj.data[0]})
        if obj.op is Op.REAL:
            return Expr(Op.TERMS, {as_real(1, obj.data[1]): obj.data[0]})
        return Expr(Op.TERMS, {obj: 1})
    raise OpError(f'cannot convert {type(obj)} to terms Expr')

def check_file(filename: Optional[str], is_inlined_call: bool=False) -> SkipResult:
    """Should skip this file?"""
    if filename is None:
        return SkipResult(True, 'filename is None')
    filename = _as_posix_path(filename)
    if filename in FORCE_SKIP_FILES:
        return SkipResult(True, 'FORCE_SKIP_FILES')
    if any((filename.startswith(d) for d in get_legacy_mod_inlinelist())):
        return SkipResult(False, 'LEGACY_MOD_INLINELIST')
    if is_inlined_call and is_torch_inline_allowed(filename):
        return SkipResult(False, 'MOD_INLINELIST')
    if is_fbcode() and FBCODE_SKIP_DIRS and bool(FBCODE_SKIP_DIRS_RE.match(filename)) and (not bool(FBCODE_INLINE_FILES_IN_SKIPPED_DIRS_RE.match(filename))):
        return SkipResult(True, 'FBCODE_SKIP_DIRS')
    if is_fbcode() and config.skip_torchrec and FBCODE_SKIP_TORCHREC_DIRS and bool(FBCODE_SKIP_TORCHREC_DIRS_RE.match(filename)) and (not bool(FBCODE_INLINE_FILES_IN_SKIPPED_DIRS_RE.match(filename))):
        return SkipResult(True, 'FBCODE_SKIP_TORCHREC_DIRS')
    unittest_dir = _module_dir(unittest)
    if unittest_dir is not None and filename.startswith(unittest_dir) and (not torch._dynamo.config.enable_trace_unittest):
        return SkipResult(True, 'unittest')
    if <MASK>:
        return SkipResult(True, 'SKIP_DIRS')
    if any((filename.startswith(d) for d in get_mod_skiplist())):
        return SkipResult(True, 'MOD_SKIPLIST')
    return SkipResult(False, 'inlined by default')

def np_doc(np_fun_name, np_fun=None, unsupported_params=None, link=None):
    """Attachs numpy docstring to a function.

  Args:
    np_fun_name: name for the np_fun symbol. At least one of np_fun or
      np_fun_name shoud be set.
    np_fun: (optional) the numpy function whose docstring will be used.
    unsupported_params: (optional) the list of parameters not supported by
      tf.numpy.
    link: (optional) which link to use. If `None`, a default link generated from
      `np_fun_name` will be used. If an instance of `AliasOf`, `link.value` will
      be used in place of `np_fun_name` for the link generation. If an instance
      of `Link`, `link.value` will be used as the whole link. If an instance of
      `NoLink`, no link will be added.

  Returns:
    A function decorator that attaches the docstring from `np_fun` to the
    decorated function.
  """
    (np_fun_name_orig, np_fun_orig) = (np_fun_name, np_fun)
    (np_fun_name, np_fun) = _prepare_np_fun_name_and_fun(np_fun_name, np_fun)
    np_sig = _np_signature(np_fun)
    if unsupported_params is None:
        unsupported_params = []

    def decorator(f):
        """The decorator."""
        if hasattr(inspect, 'signature') and np_sig is not None:
            try:
                sig = inspect.signature(f)
            except ValueError:
                sig = None
            if sig is not None:
                for (name, param) in sig.parameters.items():
                    np_param = np_sig.parameters.get(name)
                    if np_param is None:
                        if is_sig_mismatch_an_error():
                            raise TypeError(f"Cannot find parameter {name} in the numpy function's signature (which has these parameters: {list(np_sig.parameters.keys())}). Argument `np_fun_name` is {np_fun_name_orig}. Argument `np_fun` is {np_fun_orig}.")
                        else:
                            continue
                    if is_sig_mismatch_an_error() and (not _is_compatible_param_kind(param.kind, np_param.kind)):
                        raise TypeError(f'Parameter {name} is of kind {param.kind} while in numpy it is of kind {np_param.kind}. Argument `np_fun_name` is {np_fun_name_orig}. Argument `np_fun` is {np_fun_orig}.')
                    has_default = param.default != inspect.Parameter.empty
                    np_has_default = np_param.default != inspect.Parameter.empty
                    if <MASK>:
                        raise TypeError('Parameter {} should{} have a default value. Argument `np_fun_name` is {}. Argument `np_fun` is {}.'.format(name, '' if np_has_default else ' not', np_fun_name_orig, np_fun_orig))
                for name in np_sig.parameters:
                    if name not in sig.parameters:
                        unsupported_params.append(name)
        f.__doc__ = _np_doc_helper(f, np_fun, np_fun_name=np_fun_name, unsupported_params=unsupported_params, link=link)
        return f
    return decorator

def value_container(self, val):
    if hasattr(val, '_aggregating_container') and (not isinstance(val, ps_values.AggregatingVariable)):
        wrapper = val._aggregating_container()
        if <MASK>:
            return wrapper
    return val

def wrapper(*args, **kwargs):
    if <MASK>:
        return fn(*args, **kwargs)
    flags.config().enable_quantized_dtypes_training.reset(True)
    try:
        return fn(*args, **kwargs)
    finally:
        flags.config().enable_quantized_dtypes_training.reset(False)

def _parse_sheet(self, data: list, output: dict, asheetname: str | int | None=None, header: int | Sequence[int] | None=0, names: SequenceNotStr[Hashable] | range | None=None, index_col: int | Sequence[int] | None=None, usecols=None, dtype: DtypeArg | None=None, skiprows: Sequence[int] | int | Callable[[int], object] | None=None, nrows: int | None=None, true_values: Iterable[Hashable] | None=None, false_values: Iterable[Hashable] | None=None, na_values=None, parse_dates: list | dict | bool=False, date_format: dict[Hashable, str] | str | None=None, thousands: str | None=None, decimal: str='.', comment: str | None=None, skipfooter: int=0, dtype_backend: DtypeBackend | lib.NoDefault=lib.no_default, **kwds):
    is_list_header = False
    is_len_one_list_header = False
    if is_list_like(header):
        assert isinstance(header, Sequence)
        is_list_header = True
        if len(header) == 1:
            is_len_one_list_header = True
    if is_len_one_list_header:
        header = cast(Sequence[int], header)[0]
    header_names = None
    if header is not None and is_list_like(header):
        assert isinstance(header, Sequence)
        header_names = []
        control_row = [True] * len(data[0])
        for row in header:
            if is_integer(skiprows):
                assert isinstance(skiprows, int)
                row += skiprows
            if row > len(data) - 1:
                raise ValueError(f'header index {row} exceeds maximum index {len(data) - 1} of data.')
            (data[row], control_row) = fill_mi_header(data[row], control_row)
            if index_col is not None:
                (header_name, _) = pop_header_name(data[row], index_col)
                header_names.append(header_name)
    has_index_names = False
    if is_list_header and (not is_len_one_list_header) and (index_col is not None):
        index_col_set: set[int]
        if isinstance(index_col, int):
            index_col_set = {index_col}
        else:
            assert isinstance(index_col, Sequence)
            index_col_set = set(index_col)
        assert isinstance(header, Sequence)
        if len(header) < len(data):
            potential_index_names = data[len(header)]
            has_index_names = all((x == '' or x is None for (i, x) in enumerate(potential_index_names) if not control_row[i] and i not in index_col_set))
    if is_list_like(index_col):
        if header is None:
            offset = 0
        elif isinstance(header, int):
            offset = 1 + header
        else:
            offset = 1 + max(header)
        if has_index_names:
            offset += 1
        if offset < len(data):
            assert isinstance(index_col, Sequence)
            for col in index_col:
                last = data[offset][col]
                for row in range(offset + 1, len(data)):
                    if data[row][col] == '' or data[row][col] is None:
                        data[row][col] = last
                    else:
                        last = data[row][col]
    try:
        parser = TextParser(data, names=names, header=header, index_col=index_col, has_index_names=has_index_names, dtype=dtype, true_values=true_values, false_values=false_values, skiprows=skiprows, nrows=nrows, na_values=na_values, skip_blank_lines=False, parse_dates=parse_dates, date_format=date_format, thousands=thousands, decimal=decimal, comment=comment, skipfooter=skipfooter, usecols=usecols, dtype_backend=dtype_backend, **kwds)
        output[asheetname] = parser.read(nrows=nrows)
        if <MASK>:
            output[asheetname].columns = output[asheetname].columns.set_names(header_names)
    except EmptyDataError:
        output[asheetname] = DataFrame()
    except Exception as err:
        err.args = (f'{err.args[0]} (sheet: {asheetname})', *err.args[1:])
        raise err
    return output

@staticmethod
def _generate_value_for_type(random_sample: bool, field_name: str, type_hint: type[Any], default: Any) -> Any:
    """
        Generates a value of a type based on the setting.
        """
    if field_name in TYPE_OVERRIDES:
        return random.choice(TYPE_OVERRIDES[field_name])
    if type_hint is bool:
        return random.choice([True, False]) if random_sample else not default
    elif type_hint is int:
        return random.randint(0, 1000)
    elif type_hint is float:
        return random.uniform(0, 1000)
    elif type_hint is str:
        characters = string.ascii_letters + string.digits + string.punctuation
        return ''.join((random.choice(characters) for _ in range(random.randint(1, 20))))
    elif <MASK>:
        elem_type = getattr(type_hint, '__args__', [type(default[0])] if default and len(default) else [type(None)])[0]
        new_default = default[0] if default and len(default) > 0 else None
        return [SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, new_default) for _ in range(random.randint(1, 3))]
    elif is_type(type_hint, set):
        indexable = list(default)
        elem_type = getattr(type_hint, '__args__', [type(indexable[0])] if default and len(default) else [type(None)])[0]
        new_default = indexable[0] if default and len(default) > 0 else None
        return {SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, new_default) for _ in range(random.randint(1, 3))}
    elif is_type(type_hint, OrderedSet):
        indexable = list(default)
        elem_type = getattr(type_hint, '__args__', [type(indexable[0])] if default and len(default) else [type(None)])[0]
        new_default = indexable[0] if default and len(default) > 0 else None
        return OrderedSet([SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, new_default) for _ in range(random.randint(1, 3))])
    elif is_type(type_hint, dict):
        (key_type, value_type) = getattr(type_hint, '__args__', map(type, next(iter(default.items()))) if default is not None and len(default) else (type(None), type(None)))
        if default is not None and len(default.items()) > 0:
            (default_key, default_val) = next(iter(default.items()))
        else:
            (default_key, default_val) = (None, None)
        return {SamplingMethod._generate_value_for_type(random_sample, field_name, key_type, default_key): SamplingMethod._generate_value_for_type(random_sample, field_name, value_type, default_val) for _ in range(random.randint(0, 3))}
    elif is_type(type_hint, Union):
        try:
            assert len(type_hint.__args__) > 1
        except AttributeError as err:
            raise ValueError('Union type with no args') from err
        if random_sample:
            new_type = random.choice(type_hint.__args__)
        else:
            new_type = random.choice([t for t in type_hint.__args__ if t is not type(default)])
        try:
            new_default = new_type()
        except Exception:
            new_default = None
        return SamplingMethod._generate_value_for_type(random_sample, field_name, new_type, new_default)
    elif is_type(type_hint, tuple):
        args = getattr(type_hint, '__args__', tuple(map(type, default)))
        zipped = zip(args, default)
        return tuple(map(lambda x: SamplingMethod._generate_value_for_type(random_sample, field_name, x[0], x[1]), zipped))
    elif is_type(type_hint, Literal):
        try:
            if random_sample:
                return random.choice(type_hint.__args__)
            else:
                choices = [t for t in type_hint.__args__ if t != default]
                if choices:
                    return random.choice(choices)
                else:
                    return default
        except AttributeError as err:
            raise ValueError('Literal type with no args') from err
    elif is_optional_type(type_hint):
        try:
            elem_type = type_hint.__args__[0]
        except AttributeError as err:
            raise ValueError('Optional type with no args') from err
        if random_sample:
            return random.choice([None, SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, default)])
        elif default is None:
            return SamplingMethod._generate_value_for_type(random_sample, field_name, elem_type, None)
        else:
            return None
    elif type_hint is type(None):
        return None
    elif is_callable_type(type_hint):
        try:
            return_type = list(type_hint.__args__)[-1]
        except AttributeError as err:
            raise ValueError('Callable type with no args') from err

        @wraps(lambda *args, **kwargs: None)
        def dummy_function(*args, **kwargs):
            return SamplingMethod._generate_value_for_type(random_sample, field_name, return_type, None)
        return dummy_function
    elif type_hint == torch._ops.OpOverload:
        return torch.ops.aten.add.default
    elif TypeExemplars.contains(type_hint):
        return TypeExemplars.example(type_hint)
    elif type_hint == Any:
        return 1 if default != 1 else 2
    else:
        raise ValueError(f'Unable to process type {type_hint}. PRs welcome :)')

def _pad_or_backfill(self, *, method: FillnaOptions, limit: int | None=None, limit_area: Literal['inside', 'outside'] | None=None, copy: bool=True) -> Self:
    mask = self._mask
    if mask.any():
        func = missing.get_fill_func(method, ndim=self.ndim)
        npvalues = self._data.T
        new_mask = mask.T
        if <MASK>:
            npvalues = npvalues.copy()
            new_mask = new_mask.copy()
        elif limit_area is not None:
            mask = mask.copy()
        func(npvalues, limit=limit, mask=new_mask)
        if limit_area is not None and (not mask.all()):
            mask = mask.T
            neg_mask = ~mask
            first = neg_mask.argmax()
            last = len(neg_mask) - neg_mask[::-1].argmax() - 1
            if limit_area == 'inside':
                new_mask[:first] |= mask[:first]
                new_mask[last + 1:] |= mask[last + 1:]
            elif limit_area == 'outside':
                new_mask[first + 1:last] |= mask[first + 1:last]
        if copy:
            return self._simple_new(npvalues.T, new_mask.T)
        else:
            return self
    elif copy:
        new_values = self.copy()
    else:
        new_values = self
    return new_values

def _prepare(cls):
    """Create some methods once self._meta has been populated."""
    opts = cls._meta
    opts._prepare(cls)
    if opts.order_with_respect_to:
        cls.get_next_in_order = partialmethod(cls._get_next_or_previous_in_order, is_next=True)
        cls.get_previous_in_order = partialmethod(cls._get_next_or_previous_in_order, is_next=False)
        if opts.order_with_respect_to.remote_field:
            wrt = opts.order_with_respect_to
            remote = wrt.remote_field.model
            lazy_related_operation(make_foreign_order_accessors, cls, remote)
    if cls.__doc__ is None:
        cls.__doc__ = '%s(%s)' % (cls.__name__, ', '.join((f.name for f in opts.fields)))
    get_absolute_url_override = settings.ABSOLUTE_URL_OVERRIDES.get(opts.label_lower)
    if get_absolute_url_override:
        setattr(cls, 'get_absolute_url', get_absolute_url_override)
    if not opts.managers:
        if any((f.name == 'objects' for f in opts.fields)):
            raise ValueError("Model %s must specify a custom Manager, because it has a field named 'objects'." % cls.__name__)
        manager = Manager()
        manager.auto_created = True
        cls.add_to_class('objects', manager)
    for index in cls._meta.indexes:
        if <MASK>:
            index.set_name_with_model(cls)
    class_prepared.send(sender=cls)

def __mul__(self, other):
    other = as_expr(other)
    if isinstance(other, Expr):
        if self.op is other.op:
            if self.op in (Op.INTEGER, Op.REAL):
                return as_number(self.data[0] * other.data[0], max(self.data[1], other.data[1]))
            elif self.op is Op.COMPLEX:
                (r1, i1) = self.data
                (r2, i2) = other.data
                return as_complex(r1 * r2 - i1 * i2, r1 * i2 + r2 * i1)
            if self.op is Op.FACTORS:
                r = Expr(self.op, dict(self.data))
                for (k, v) in other.data.items():
                    _pairs_add(r.data, k, v)
                return normalize(r)
            elif self.op is Op.TERMS:
                r = Expr(self.op, {})
                for (t1, c1) in self.data.items():
                    for (t2, c2) in other.data.items():
                        _pairs_add(r.data, t1 * t2, c1 * c2)
                return normalize(r)
        if self.op is Op.COMPLEX and other.op in (Op.INTEGER, Op.REAL):
            return self * as_complex(other)
        elif <MASK>:
            return as_complex(self) * other
        elif self.op is Op.REAL and other.op is Op.INTEGER:
            return self * as_real(other, kind=self.data[1])
        elif self.op is Op.INTEGER and other.op is Op.REAL:
            return as_real(self, kind=other.data[1]) * other
        if self.op is Op.TERMS:
            return self * as_terms(other)
        elif other.op is Op.TERMS:
            return as_terms(self) * other
        return as_factors(self) * as_factors(other)
    return NotImplemented

def __call__(self, shape, dtype=None, partition_info=None):
    if dtype is None:
        dtype = self.dtype
    if <MASK>:
        raise ValueError(f'The tensor to initialize, specified by argument `shape` must be four-dimensional. Received: {shape}')
    if shape[-2] > shape[-1]:
        raise ValueError(f'In_filters, specified by shape[-2]={shape[-2]} cannot be greater than out_filters, specified by shape[-1]={shape[-1]}.')
    if shape[0] != shape[1]:
        raise ValueError(f'Kernel sizes, specified by shape[0]={shape[0]} and shape[1]={shape[1]} must be equal.')
    kernel = self._orthogonal_kernel(shape[0], shape[2], shape[3])
    kernel *= math_ops.cast(self.gain, dtype=dtype)
    return kernel

def _add_send_recv(compute_actions: dict[int, list[_Action]], stage_to_rank: Callable[[int], int], num_stages: int) -> dict[int, list[_Action]]:
    """
    Transforms a compute-only schedule into a complete schedule with communication actions.

    For actions with sub-actions (OVERLAP_F_B) we ensure that all the subactions have been
    computed and the communication is ready
    """
    comm_actions: dict[int, list[_Action]] = {rank: [] for rank in compute_actions}
    prev_actions: dict[int, set[_Action]] = {rank: set() for rank in compute_actions}

    def _has_comms(action: _Action) -> bool:
        if <MASK>:
            return action.stage_index != num_stages - 1 and stage_to_rank(action.stage_index + 1) != stage_to_rank(action.stage_index)
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
            return action.stage_index != 0 and stage_to_rank(action.stage_index - 1) != stage_to_rank(action.stage_index)
        return False

    def _get_comms(action: _Action) -> tuple[_Action, _Action]:
        assert _has_comms(action), f'{action} is not a valid comm action'
        stage_idx = action.stage_index
        ctype = action.computation_type
        mb_idx = action.microbatch_index
        send = _Action(stage_idx, SEND_F if ctype == F else SEND_B, mb_idx)
        recv_stage_idx = stage_idx + 1 if ctype == F else stage_idx - 1
        recv = _Action(recv_stage_idx, RECV_F if ctype == F else RECV_B, mb_idx)
        return (send, recv)

    def _ready_to_schedule(action: Optional[_Action], prev_actions: set[_Action]) -> bool:
        """We don't put our own recv ops in the schedule, we let a sender on another rank put our recv ops in place.
        This helps ensure a sane (non-hanging) ordering of sends and recvs.
        But it also means we might not be able to schedule our next compute action yet.
        """
        if action is None:
            return True
        elif action.computation_type == F and action.stage_index != 0:
            if _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_actions:
                return True
            return False
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD) and action.stage_index != num_stages - 1:
            if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_actions:
                return True
            return False
        else:
            return True
    while compute_actions:
        progress = False
        for rank in sorted(compute_actions):
            assert len(compute_actions[rank]) > 0, f'rank={rank!r}, len(compute_actions[rank])={len(compute_actions[rank])!r}'
            action = compute_actions[rank][0]
            if action is not None and action.sub_actions is not None:
                all_actions = action.sub_actions
            else:
                all_actions = (action,)
            if not all((_ready_to_schedule(a, prev_actions[rank]) for a in all_actions)):
                continue
            if action is not None:
                comm_actions[rank].append(action)
                for a in all_actions:
                    prev_actions[rank].add(a)
                    if _has_comms(a):
                        (send, recv) = _get_comms(a)
                        comm_actions[rank].append(send)
                        prev_actions[rank].add(send)
                        comm_actions[stage_to_rank(recv.stage_index)].append(recv)
                        prev_actions[stage_to_rank(recv.stage_index)].add(recv)
            compute_actions[rank].pop(0)
            if len(compute_actions[rank]) == 0:
                del compute_actions[rank]
            progress = True
        assert progress, "Malformed compute schedule, can't schedule sends/recvs"
    return comm_actions

def plan(self, state: MemoryPlanningState) -> MemoryPlanningLine:
    if <MASK>:
        assert self.reused_as.get_name() in V.graph.removed_buffers
        return NullLine(self.wrapper)
    assert self.reused_as.get_name() not in V.graph.removed_buffers
    return self

def _verifyExponential(self, x, np_type):
    inp = x.astype(np_type)
    with test_util.use_gpu():
        tf_ans = linalg_impl.matrix_exponential(inp)
        if x.size == 0:
            np_ans = np.empty(x.shape, dtype=np_type)
        elif <MASK>:
            np_ans = np.zeros(inp.shape, dtype=np_type)
            for i in itertools.product(*[range(x) for x in inp.shape[:-2]]):
                np_ans[i] = np_expm(inp[i])
        else:
            np_ans = np_expm(inp)
        out = self.evaluate(tf_ans)
        self.assertAllClose(np_ans, out, rtol=0.001, atol=0.001)

def _same_storage(a, b):
    from torch.distributed.tensor import DTensor
    if <MASK>:
        a = a._local_tensor
    if isinstance(b, DTensor):
        b = b._local_tensor
    return a.untyped_storage().data_ptr() == b.untyped_storage().data_ptr()

def should_bypass_proxies(url, no_proxy):
    """
    Returns whether we should bypass proxies or not.

    :rtype: bool
    """

    def get_proxy(key):
        return os.environ.get(key) or os.environ.get(key.upper())
    no_proxy_arg = no_proxy
    if <MASK>:
        no_proxy = get_proxy('no_proxy')
    parsed = urlparse(url)
    if parsed.hostname is None:
        return True
    if no_proxy:
        no_proxy = (host for host in no_proxy.replace(' ', '').split(',') if host)
        if is_ipv4_address(parsed.hostname):
            for proxy_ip in no_proxy:
                if is_valid_cidr(proxy_ip):
                    if address_in_network(parsed.hostname, proxy_ip):
                        return True
                elif parsed.hostname == proxy_ip:
                    return True
        else:
            host_with_port = parsed.hostname
            if parsed.port:
                host_with_port += f':{parsed.port}'
            for host in no_proxy:
                if parsed.hostname.endswith(host) or host_with_port.endswith(host):
                    return True
    with set_environ('no_proxy', no_proxy_arg):
        try:
            bypass = proxy_bypass(parsed.hostname)
        except (TypeError, socket.gaierror):
            bypass = False
    if bypass:
        return True
    return False

def get_config(self):
    config = {}
    if hasattr(self, 'clipnorm'):
        config['clipnorm'] = self.clipnorm
    if <MASK>:
        config['clipvalue'] = self.clipvalue
    return config

def _repr(self, value, pos):
    __traceback_hide__ = True
    try:
        if value is None:
            return ''
        if self._unicode:
            try:
                value = str(value)
            except UnicodeDecodeError:
                value = bytes(value)
        else:
            if not isinstance(value, basestring_):
                value = coerce_text(value)
            if <MASK>:
                value = value.encode(self.default_encoding)
    except Exception as e:
        e.args = (self._add_line_info(e.args[0], pos),)
        raise
    else:
        if self._unicode and isinstance(value, bytes):
            if not self.default_encoding:
                raise UnicodeDecodeError('Cannot decode bytes value %r into unicode (no default_encoding provided)' % value)
            try:
                value = value.decode(self.default_encoding)
            except UnicodeDecodeError as e:
                raise UnicodeDecodeError(e.encoding, e.object, e.start, e.end, e.reason + ' in string %r' % value)
        elif not self._unicode and isinstance(value, str):
            if not self.default_encoding:
                raise UnicodeEncodeError('Cannot encode unicode value %r into bytes (no default_encoding provided)' % value)
            value = value.encode(self.default_encoding)
        return value

def _transform_feature(self, inputs):
    feature_tensors = []
    for key in _collect_leaf_level_keys(self):
        if <MASK>:
            feature_tensors.append(inputs.get(key))
        elif isinstance(key, _CategoricalColumn):
            ids_and_weights = key._get_sparse_tensors(inputs)
            if ids_and_weights.weight_tensor is not None:
                raise ValueError('crossed_column does not support weight_tensor, but the given column populates weight_tensor. Given column: {}'.format(key.name))
            feature_tensors.append(ids_and_weights.id_tensor)
        else:
            raise ValueError('Unsupported column type. Given: {}'.format(key))
    return sparse_ops.sparse_cross_hashed(inputs=feature_tensors, num_buckets=self.hash_bucket_size, hash_key=self.hash_key)

def skipCUDAVersionIn(versions: Optional[list[tuple[int, int]]]=None):

    def dec_fn(fn):

        @wraps(fn)
        def wrap_fn(self, *args, **kwargs):
            version = _get_torch_cuda_version()
            if <MASK>:
                return fn(self, *args, **kwargs)
            if version in (versions or []):
                reason = f'test skipped for CUDA version {version}'
                raise unittest.SkipTest(reason)
            return fn(self, *args, **kwargs)
        return wrap_fn
    return dec_fn

def _unicode_decode(input, input_encoding, errors, replacement_char, replace_control_characters, with_offsets):
    """Decodes each string into a sequence of codepoints."""
    input = ragged_tensor.convert_to_tensor_or_ragged_tensor(input, name='input')
    input_ndims = input.shape.ndims
    if input_ndims is None:
        raise ValueError('Rank of `input` must be statically known.')
    if <MASK>:
        if not ragged_tensor.is_ragged(input):
            input = ragged_tensor.RaggedTensor.from_tensor(input, ragged_rank=input_ndims - 1)
        elif input.ragged_rank < input_ndims - 1:
            input = input.with_flat_values(ragged_tensor.RaggedTensor.from_tensor(input.flat_values, ragged_rank=input_ndims - input.ragged_rank - 1))
    if ragged_tensor.is_ragged(input):
        flat_input = array_ops.reshape(input.flat_values, [-1])
    else:
        flat_input = array_ops.reshape(input, [-1])
    if with_offsets:
        decode_op = gen_string_ops.unicode_decode_with_offsets
    else:
        decode_op = gen_string_ops.unicode_decode
    flat_result = decode_op(input=flat_input, input_encoding=input_encoding, errors=errors, replacement_char=replacement_char, replace_control_characters=replace_control_characters)
    if input_ndims == 0:
        codepoints = flat_result.char_values
        if with_offsets:
            offsets = flat_result.char_to_byte_starts
    else:
        codepoints = ragged_tensor.RaggedTensor.from_row_splits(flat_result.char_values, flat_result.row_splits, validate=False)
        if input_ndims > 1:
            codepoints = input.with_flat_values(codepoints)
        if with_offsets:
            offsets = ragged_tensor.RaggedTensor.from_row_splits(flat_result.char_to_byte_starts, flat_result.row_splits, validate=False)
            if input_ndims > 1:
                offsets = input.with_flat_values(offsets)
    if with_offsets:
        return (codepoints, offsets)
    else:
        return codepoints

@register_prop_rule(aten.index.Tensor, schema_info=RuntimeSchemaInfo(needs_pytree=True))
def prop_index(op_schema: OpSchema) -> OutputSharding:
    """
    Expect replicated on the first input; _mostly_ pointwise on the second input.

    TODO: exception: when the dtype of second input is "bool", then a torch.nonzero needs to be triggered first.
    """
    (values_spec, multi_indices_spec) = op_schema.args_schema
    if <MASK>:
        raise AssertionError(f'Expected DTensorSpec, got {type(values_spec)}')
    if not isinstance(multi_indices_spec, list):
        raise AssertionError(f'Expected list, got {type(multi_indices_spec)}')
    multi_indices_spec = cast(list[Optional[DTensorSpec]], multi_indices_spec)
    valid_indices_spec: list[tuple[int, DTensorSpec]] = [(i, a) for (i, a) in enumerate(multi_indices_spec) if a is not None]
    indices_out = pointwise_rule(OpSchema(op=op_schema.op, args_schema=tuple((v[1] for v in valid_indices_spec)), kwargs_schema={}))
    need_reshard_on_indices = indices_out.output_spec is None
    if not need_reshard_on_indices:
        if not isinstance(indices_out.output_spec, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(indices_out.output_spec)}')
        indices_spec: DTensorSpec = indices_out.output_spec
    else:
        if indices_out.redistribute_schema is None:
            raise AssertionError('redistribute_schema should not be None')
        valid_indices_suggestion = indices_out.redistribute_schema
        for (i, v) in enumerate(valid_indices_suggestion.args_spec):
            multi_indices_spec[valid_indices_spec[i][0]] = v
        indices_output_spec = pointwise_rule(valid_indices_suggestion).output_spec
        if not isinstance(indices_output_spec, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(indices_output_spec)}')
        indices_spec = indices_output_spec
    lookup_dims = {v[0] for v in valid_indices_spec}
    need_reshard_on_values = tuple((isinstance(vp, Shard) and (vp.dim in lookup_dims or isinstance(ip, Shard)) for (vp, ip) in zip(values_spec.placements, indices_spec.placements)))
    if not need_reshard_on_indices and (not any(need_reshard_on_values)):
        value_placements = values_spec.placements
        all_dims_consecutive = all((b[0] - a[0] == 1 for (b, a) in zip(valid_indices_spec[1:], valid_indices_spec[:-1])))
        if all_dims_consecutive:
            insert_dim: int = valid_indices_spec[0][0]
        else:
            insert_dim = 0

        def place(vp: Placement, ip: Placement) -> Placement:
            if isinstance(vp, Shard):
                return Shard(vp.dim if vp.dim < insert_dim else vp.dim + indices_spec.ndim - sum((1 if vp.dim > v[0] else 0 for v in valid_indices_spec)))
            if isinstance(ip, Shard):
                return Shard(ip.dim + insert_dim)
            return vp
        value_placements = tuple((place(vp, ip) for (vp, ip) in zip(values_spec.placements, indices_spec.placements)))
        result = OutputSharding(output_spec=DTensorSpec(mesh=values_spec.mesh, placements=value_placements))
        return result
    else:
        result = OutputSharding(output_spec=None, redistribute_schema=OpSchema(op=op_schema.op, args_schema=(DTensorSpec(mesh=values_spec.mesh, placements=tuple((Replicate() if need_reshard_on_values[i] else v for (i, v) in enumerate(values_spec.placements))), tensor_meta=values_spec.tensor_meta), multi_indices_spec), kwargs_schema=op_schema.kwargs_schema))
        return result

def get_logits_and_probs(logits=None, probs=None, multidimensional=False, validate_args=False, name='get_logits_and_probs', dtype=None):
    """Converts logit to probabilities (or vice-versa), and returns both.

  Args:
    logits: Floating-point `Tensor` representing log-odds.
    probs: Floating-point `Tensor` representing probabilities.
    multidimensional: Python `bool`, default `False`. If `True`, represents
      whether the last dimension of `logits` or `probs`, a `[N1, N2, ...  k]`
      dimensional tensor, representing the logit or probability of `shape[-1]`
      classes.
    validate_args: Python `bool`, default `False`. When `True`, either assert `0
      <= probs <= 1` (if not `multidimensional`) or that the last dimension of
      `probs` sums to one.
    name: A name for this operation (optional).
    dtype: `tf.DType` to prefer when converting args to `Tensor`s.

  Returns:
    logits, probs: Tuple of `Tensor`s. If `probs` has an entry that is `0` or
      `1`, then the corresponding entry in the returned logit will be `-Inf` and
      `Inf` respectively.

  Raises:
    ValueError: if neither `probs` nor `logits` were passed in, or both were.
  """
    with ops.name_scope(name, values=[probs, logits]):
        if (probs is None) == (logits is None):
            raise ValueError('Must pass probs or logits, but not both.')
        if probs is None:
            logits = ops.convert_to_tensor(logits, name='logits', dtype=dtype)
            if not logits.dtype.is_floating:
                raise TypeError('logits must having floating type.')
            if multidimensional:
                if validate_args:
                    logits = embed_check_categorical_event_shape(logits)
                return (logits, nn.softmax(logits, name='probs'))
            return (logits, math_ops.sigmoid(logits, name='probs'))
        probs = ops.convert_to_tensor(probs, name='probs', dtype=dtype)
        if <MASK>:
            raise TypeError('probs must having floating type.')
        if validate_args:
            with ops.name_scope('validate_probs'):
                one = constant_op.constant(1.0, probs.dtype)
                dependencies = [check_ops.assert_non_negative(probs)]
                if multidimensional:
                    probs = embed_check_categorical_event_shape(probs)
                    dependencies += [check_ops.assert_near(math_ops.reduce_sum(probs, -1), one, message='probs does not sum to 1.')]
                else:
                    dependencies += [check_ops.assert_less_equal(probs, one, message='probs has components greater than 1.')]
                probs = control_flow_ops.with_dependencies(dependencies, probs)
        with ops.name_scope('logits'):
            if multidimensional:
                return (math_ops.log(probs), probs)
            return (math_ops.log(probs) - math_ops.log1p(-1.0 * probs), probs)

@register_decomposition(aten.repeat_interleave.Tensor)
def repeat_interleave_Tensor(repeat: torch.Tensor, output_size: Optional[int]=None) -> torch.Tensor:
    if <MASK>:
        return NotImplemented
    if output_size is None or type(output_size) is not int:
        return NotImplemented
    if repeat.device.type == 'mps':
        return NotImplemented
    assert repeat.dtype in [torch.int32, torch.int64]
    assert repeat.ndim == 1
    cumsum = repeat.cumsum(0)
    pos = torch.arange(output_size, device=repeat.device)
    indices = torch.searchsorted(cumsum, pos, out_int32=repeat.dtype == torch.int32, right=True)
    return torch.clamp(indices, max=repeat.size(0) - 1)

def _size_of(node: fx.Node) -> int:

    def object_nbytes(x) -> int:
        if not isinstance(x, torch.Tensor):
            return 0
        return _tensor_nbytes(hint_int(x.numel(), fallback=4096), x.dtype)
    if <MASK>:
        val = node.meta['val']
        if isinstance(val, py_sym_types):
            return 1
        elif isinstance(val, (list, tuple)):
            return sum((object_nbytes(n) for n in val))
        elif isinstance(val, dict):
            return sum((object_nbytes(n) for (_, n) in val.items()))
        elif isinstance(val, torch.Tensor):
            return object_nbytes(val)
        raise RuntimeError(f'Unknown metadata type {type(val)} on node {node}')
    if node.op == 'get_attr' or node.target is torch.ops.aten._assert_scalar.default:
        return 0
    raise RuntimeError(f"Node {node} didn't have `val` metadata; we should always have `val` metadata on the nodes.")

def _tag_callable(loss):
    """Tags callable loss tensor as `_unconditional_loss`."""
    if callable(loss):
        with autocast_variable.enable_auto_cast_variables(None):
            loss = loss()
    if loss is None:
        return None
    if <MASK>:
        loss = tensor_conversion.convert_to_tensor_v2_with_dispatch(loss, dtype=backend.floatx())
    loss._unconditional_loss = True
    return loss

def _lru_cache(fn: Callable[..., _T], maxsize: Optional[int]=None) -> functools._lru_cache_wrapper[_T]:
    """
    Wrapper around lru_cache that clears when new info about shapes has been
    updated.

    Use lru_cache if the output is always the same, regardless of the
    constraints we know now (i.e. evaluate_expr)

    Use _lru_cache otherwise.

    Also note that this depends on _update_version_counter being called on the
    shape environment whenever the constraints are updated, otherwise the cache
    will not be cleared.
    """
    fn_cache = lru_cache(maxsize)(fn)
    prior_version = 0
    if config.validate_shape_env_version_key:
        prior_key = None

        @functools.wraps(fn)
        def wrapper(self: ShapeEnv, *args: Any, **kwargs: Any) -> _T:
            nonlocal prior_version, prior_key
            if <MASK>:
                prior_key = self._get_key()
            if prior_version != self._version_counter:
                fn_cache.cache_clear()
                prior_version = self._version_counter
                prior_key = self._get_key()
            else:
                assert prior_key == self._get_key(), 'ShapeEnv cache key changed without version being updated!'
            return fn_cache(self, *args, **kwargs)
    else:

        @functools.wraps(fn)
        def wrapper(self: ShapeEnv, *args: Any, **kwargs: Any) -> _T:
            nonlocal prior_version
            if prior_version != self._version_counter:
                fn_cache.cache_clear()
                prior_version = self._version_counter
            return fn_cache(self, *args, **kwargs)
    wrapper.cache_clear = fn_cache.cache_clear
    wrapper.cache_info = fn_cache.cache_info
    return wrapper

@classmethod
def eval(cls, a, b):
    if a.is_Boolean and b.is_Boolean:
        return getattr(operator, real_op_name)(a, b)
    if a.is_Boolean:
        a = sympy.Integer(1 if a else 0)
    if <MASK>:
        b = sympy.Integer(1 if b else 0)
    if isinstance(a, (sympy.Integer, int)) and isinstance(b, (sympy.Integer, int)):
        return sympy.Integer(getattr(operator, real_op_name)(int(a), int(b)))
    return None

@classmethod
def _check_return_codes(cls, failed_ranks, timeout, fn):
    error_msg = ''
    skip_code = -1
    for (rank, exc_info) in failed_ranks:
        exc = exc_info[1]
        if isinstance(exc, unittest.SkipTest):
            logger.info('Thread %s skipping test %s for following reason: %s', rank, fn, str(exc))
            if skip_code < 0:
                skip_code = TEST_SKIPS['generic'].exit_code
        elif isinstance(exc, TimeoutError):
            msg = f'Thread {rank} terminated or timed out after {timeout} seconds\n'
            logger.error(msg)
            raise RuntimeError(msg)
        elif isinstance(exc, Exception):
            msg = ''.join(traceback.format_exception(*exc_info))
            logger.error('Caught exception: \n%s exiting thread %s', msg, rank)
            error_msg += f'Thread {rank} exited with exception:\n{msg}\n'
        elif isinstance(exc, SystemExit):
            if <MASK>:
                skip_code = exc.code
    if len(error_msg) > 0:
        raise RuntimeError(error_msg)
    if skip_code > 0:
        for skip in TEST_SKIPS.values():
            if skip_code == skip.exit_code:
                if IS_SANDCASTLE:
                    logger.info('Skipping %s on sandcastle for the following reason: %s', fn, skip.message)
                    return
                else:
                    raise unittest.SkipTest(skip.message)

def _check_precision_parameters(self, X):
    """Check the prior parameters of the precision distribution.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
        """
    (_, n_features) = X.shape
    if self.degrees_of_freedom_prior is None:
        self.degrees_of_freedom_prior_ = n_features
    elif <MASK>:
        self.degrees_of_freedom_prior_ = self.degrees_of_freedom_prior
    else:
        raise ValueError("The parameter 'degrees_of_freedom_prior' should be greater than %d, but got %.3f." % (n_features - 1, self.degrees_of_freedom_prior))

def validate_shards(shards: Sequence[Shard], shardable_tensors: Sequence[ShardableTensor], callback_description: str) -> None:
    """Validates shards generated by the sharding_callback."""
    unseen_tensor_dict = {}
    for shardable_tensor in shardable_tensors:
        unseen_tensor_dict.setdefault(shardable_tensor.checkpoint_key, {})[shardable_tensor.slice_spec] = shardable_tensor.tensor
    seen_tensor_set = set()
    for shard_tensors in shards:
        task_tensor = None
        for (checkpoint_key, tensor_slice_dict) in shard_tensors.items():
            for (slice_spec, shard_tensor) in tensor_slice_dict.items():
                slice_spec = slice_spec.strip()
                if (checkpoint_key, slice_spec) in seen_tensor_set:
                    raise RuntimeError(f'After executing the checkpoint sharding callback, multiple tensors with the same checkpoint key and slice spec were found:\n  callback_description: {callback_description}\n  checkpoint_key: {checkpoint_key}\n  slice_spec: {slice_spec}\n')
                if checkpoint_key not in unseen_tensor_dict:
                    raise RuntimeError(f'After executing the checkpoint sharding callback, a tensor not originally in the object graph was found in the checkpoint shards:\n  callback_description: {callback_description}\n  checkpoint_key: {checkpoint_key}\n  slice_spec: {slice_spec}\n')
                target_shape = unseen_tensor_dict[checkpoint_key][slice_spec].shape
                if shard_tensor.shape != target_shape:
                    raise RuntimeError(f'After executing the checkpoint sharding callback, a tensor was found with an altered shape:\n  callback_description: {callback_description}\n  checkpoint_key: {checkpoint_key}\n  slice_spec: {slice_spec}\n  original tensor_shape: {target_shape}\n  new tensor_shape: {shard_tensor.shape}\n')
                target_dtype = unseen_tensor_dict[checkpoint_key][slice_spec].dtype
                if shard_tensor.dtype != target_dtype:
                    raise RuntimeError(f'After executing the checkpoint sharding callback, a tensor was found with an altered dtype:\n  callback_description: {callback_description}\n  checkpoint_key: {checkpoint_key}\n  slice_spec: {slice_spec}\n  original tensor_dtype: {target_dtype}\n  new tensor_dtype: {shard_tensor.dtype}\n')
                target_task = device_lib.DeviceSpec.from_string(unseen_tensor_dict[checkpoint_key][slice_spec].device).task
                shard_tensor_task = device_lib.DeviceSpec.from_string(shard_tensor.device).task
                if shard_tensor_task != target_task:
                    raise RuntimeError(f'After executing the checkpoint sharding callback, a tensor was found with an altered task:\n  callback_description: {callback_description}\n  checkpoint_key: {checkpoint_key}\n  slice_spec: {slice_spec}\n  original tensor_task: {target_task}\n  new tensor_task: {shard_tensor_task}\n')
                if task_tensor is None:
                    task_tensor = ShardableTensor(_tensor_save_spec=None, tensor=None, dtype=None, device=shard_tensor.device, name=None, shape=None, slice_spec=slice_spec, checkpoint_key=checkpoint_key, trackable=None)
                else:
                    task1 = device_lib.DeviceSpec.from_string(task_tensor.device).task
                    task2 = device_lib.DeviceSpec.from_string(shard_tensor.device).task
                    if task1 is not None and task2 is not None and (task1 != task2):
                        raise RuntimeError(f'After executing the checkpoint sharding callback, tensors with different tasks were found in the same shard:\n  callback_description: {callback_description}\n  tensor #1:    checkpoint_key: {task_tensor.checkpoint_key}\n    slice_spec: {task_tensor.slice_spec}\n    task: {task1}\n  tensor #2:    checkpoint_key: {checkpoint_key}\n    slice_spec: {slice_spec}\n    task: {task2}\n')
                del unseen_tensor_dict[checkpoint_key][slice_spec]
                if not unseen_tensor_dict[checkpoint_key]:
                    del unseen_tensor_dict[checkpoint_key]
                seen_tensor_set.add((checkpoint_key, slice_spec))
    if <MASK>:
        tensors_info = ''
        for (ckpt_key, slice_spec) in unseen_tensor_dict.items():
            tensors_info += '  tensor:\n'
            tensors_info += f'    checkpoint_key: {ckpt_key}\n'
            tensors_info += f'    slice_spec: {slice_spec}\n'
        raise RuntimeError(f'After executing the checkpoint sharding callback, tensors in the object graph were not found in the checkpoint shards:\n  callback_description: {callback_description}\n{tensors_info}')

def exists(self, limit=True):
    q = self.clone()
    if not (q.distinct and q.is_sliced):
        if <MASK>:
            q.add_fields((f.attname for f in self.model._meta.concrete_fields), False)
            q.set_group_by(allow_aliases=False)
        q.clear_select_clause()
    if q.combined_queries and q.combinator == 'union':
        q.combined_queries = tuple((combined_query.exists(limit=False) for combined_query in q.combined_queries))
    q.clear_ordering(force=True)
    if limit is True:
        q.set_limits(high=1)
    q.add_annotation(Value(1), 'a')
    return q

@register_prop_rule(aten.index.Tensor, schema_info=RuntimeSchemaInfo(needs_pytree=True))
def prop_index(op_schema: OpSchema) -> OutputSharding:
    """
    Expect replicated on the first input; _mostly_ pointwise on the second input.

    TODO: exception: when the dtype of second input is "bool", then a torch.nonzero needs to be triggered first.
    """
    (values_spec, multi_indices_spec) = op_schema.args_schema
    if not isinstance(values_spec, DTensorSpec):
        raise AssertionError(f'Expected DTensorSpec, got {type(values_spec)}')
    if not isinstance(multi_indices_spec, list):
        raise AssertionError(f'Expected list, got {type(multi_indices_spec)}')
    multi_indices_spec = cast(list[Optional[DTensorSpec]], multi_indices_spec)
    valid_indices_spec: list[tuple[int, DTensorSpec]] = [(i, a) for (i, a) in enumerate(multi_indices_spec) if a is not None]
    indices_out = pointwise_rule(OpSchema(op=op_schema.op, args_schema=tuple((v[1] for v in valid_indices_spec)), kwargs_schema={}))
    need_reshard_on_indices = indices_out.output_spec is None
    if not need_reshard_on_indices:
        if not isinstance(indices_out.output_spec, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(indices_out.output_spec)}')
        indices_spec: DTensorSpec = indices_out.output_spec
    else:
        if indices_out.redistribute_schema is None:
            raise AssertionError('redistribute_schema should not be None')
        valid_indices_suggestion = indices_out.redistribute_schema
        for (i, v) in enumerate(valid_indices_suggestion.args_spec):
            multi_indices_spec[valid_indices_spec[i][0]] = v
        indices_output_spec = pointwise_rule(valid_indices_suggestion).output_spec
        if not isinstance(indices_output_spec, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(indices_output_spec)}')
        indices_spec = indices_output_spec
    lookup_dims = {v[0] for v in valid_indices_spec}
    need_reshard_on_values = tuple((isinstance(vp, Shard) and (vp.dim in lookup_dims or isinstance(ip, Shard)) for (vp, ip) in zip(values_spec.placements, indices_spec.placements)))
    if not need_reshard_on_indices and (not any(need_reshard_on_values)):
        value_placements = values_spec.placements
        all_dims_consecutive = all((b[0] - a[0] == 1 for (b, a) in zip(valid_indices_spec[1:], valid_indices_spec[:-1])))
        if <MASK>:
            insert_dim: int = valid_indices_spec[0][0]
        else:
            insert_dim = 0

        def place(vp: Placement, ip: Placement) -> Placement:
            if isinstance(vp, Shard):
                return Shard(vp.dim if vp.dim < insert_dim else vp.dim + indices_spec.ndim - sum((1 if vp.dim > v[0] else 0 for v in valid_indices_spec)))
            if isinstance(ip, Shard):
                return Shard(ip.dim + insert_dim)
            return vp
        value_placements = tuple((place(vp, ip) for (vp, ip) in zip(values_spec.placements, indices_spec.placements)))
        result = OutputSharding(output_spec=DTensorSpec(mesh=values_spec.mesh, placements=value_placements))
        return result
    else:
        result = OutputSharding(output_spec=None, redistribute_schema=OpSchema(op=op_schema.op, args_schema=(DTensorSpec(mesh=values_spec.mesh, placements=tuple((Replicate() if need_reshard_on_values[i] else v for (i, v) in enumerate(values_spec.placements))), tensor_meta=values_spec.tensor_meta), multi_indices_spec), kwargs_schema=op_schema.kwargs_schema))
        return result

@wraps(f)
def wrapper(x: npt.NDArray, *args, **kwargs):
    keys = set(kwargs.keys())
    dim = kwargs.pop('dim', None)
    keepdim = kwargs.pop('keepdim', False)
    if 'dim' in keys:
        dim = tuple(dim) if isinstance(dim, Sequence) else dim
        if x.ndim == 0 and dim in {0, -1, (0,), (-1,)}:
            kwargs['axis'] = None
        else:
            kwargs['axis'] = dim
    if 'keepdim' in keys and supports_keepdims:
        kwargs['keepdims'] = keepdim
    if 'mask' in keys:
        mask = kwargs.pop('mask')
        if mask is not None:
            assert mask.layout == torch.strided
            kwargs['where'] = mask.cpu().numpy()
    if 'identity' in keys:
        identity = kwargs.pop('identity')
        if <MASK>:
            if identity.dtype is torch.bfloat16:
                identity = identity.cpu().to(torch.float32)
            else:
                identity = identity.cpu()
            kwargs['initial'] = identity.numpy()
    result = f(x, *args, **kwargs)
    if keepdim and (not supports_keepdims) and (x.ndim > 0):
        dim = list(range(x.ndim)) if dim is None else dim
        result = np.expand_dims(result, dim)
    return result

@tf_export('experimental.dtensor.num_clients', v1=[])
def num_clients() -> int:
    """Returns the number of clients in this DTensor cluster."""
    if <MASK>:
        return 1
    return len(jobs())

def _find_frame_locals(self) -> _FrameLocalResult:
    """
        Given the current user code frame, finds the relevant lines of code,
        values of symbolic locals, and free symbols involved.
        """
    frame_locals: dict[str, Any] = {}
    frame_symbols: dict[str, str] = {}
    if (frame := _find_user_code_frame()) is None or frame.f_code.co_filename == '<string>':
        return _FrameLocalResult()
    instructions = list(dis.Bytecode(frame.f_code))
    (co_lines, offset) = inspect.getsourcelines(frame.f_code)
    (start, end, cur) = (None, None, None)
    for (i, instr) in enumerate(instructions):
        if instr.starts_line is not None:
            cur = instr.starts_line
        if cur != frame.f_lineno:
            continue
        if <MASK>:
            start = end = i
        else:
            end = i
    if start is None or end is None:
        return _FrameLocalResult()

    def go(x: Any) -> Optional[str]:
        if isinstance(x, torch.Tensor):
            for y in x.size():
                go(y)
            for y in x.stride():
                go(y)
            go(x.storage_offset())
            return f'Tensor(shape: {x.size()}, stride: {x.stride()}, storage_offset: {x.storage_offset()})'
        elif isinstance(x, (SymBool, SymInt, SymFloat)):
            for s in x.node.expr.free_symbols:
                if str(s) in frame_symbols:
                    continue
                if s in self.var_to_sources:
                    frame_symbols[str(s)] = self.var_to_sources[s][0].name()
            return str(x)
        return None
    last_lineno = frame.f_lineno
    for instr in instructions[start:end + 1]:
        if (lineno := instr.starts_line) is not None:
            last_lineno = max(last_lineno, lineno)
        if isinstance(instr.argval, str) and instr.argval in frame.f_locals:
            flat_locals = pytree.tree_flatten(frame.f_locals[instr.argval])[0]
            frame_locals[instr.argval] = [go(flat_local) for flat_local in flat_locals]
    locs = co_lines[frame.f_lineno - offset:last_lineno + 1 - offset]
    if not locs:
        return _FrameLocalResult()
    indent = len(locs[0]) - len(locs[0].lstrip())
    frame_loc = ''.join([loc[indent:] for loc in locs]).strip()
    return _FrameLocalResult(loc=frame_loc, locals=frame_locals, symbols=frame_symbols)

def check_concat_weights(match):
    is_cpu = match.kwargs['inp'].meta['val'].is_cpu
    if is_cpu and (not config.cpp.enable_concat_linear):
        return False
    weight_inputs = ['w1', 'w2']
    if <MASK>:
        weight_inputs.append('w3')
    equal_shape_inputs = [weight_inputs]
    if 'b1' in match.kwargs:
        bias_inputs = ['b1', 'b2']
        if 'b3' in match.kwargs:
            bias_inputs.append('b3')
        equal_shape_inputs.append(bias_inputs)
    for equal_shape_group in equal_shape_inputs:
        inps = [match.kwargs[name] for name in equal_shape_group]
        if not all((inp.op == 'get_attr' and inp.meta['val'].shape == inps[0].meta['val'].shape for inp in inps)):
            return False
    return True

@_onnx_symbolic('aten::bitwise_not')
def bitwise_not(g: jit_utils.GraphContext, input):
    if <MASK>:
        raise errors.SymbolicValueError('ONNX export does NOT support exporting bitwise Not for non-boolean input values', input)
    return g.op('Not', input)

def strip_overloads(gm):
    """
    Modifies the target of graph nodes in :attr:`gm` to strip overloads.

    Args:
        gm(fx.GraphModule): The input Fx graph module to be modified
    """
    for node in gm.graph.nodes:
        if <MASK>:
            node.target = node.target.overloadpacket
    gm.recompile()

def hook(module, input) -> None:
    input_data = input[0]
    data = self.data_groups[name].get('data')
    if features is None:
        if <MASK>:
            data = torch.zeros_like(input_data)
            self.state[name]['mask'] = torch.ones_like(input_data)
        out_data = agg_fn(data, input_data)
    else:
        if data is None:
            out_data = [0 for _ in range(len(features))]
            self.state[name]['mask'] = [0 for _ in range(len(features))]
        else:
            out_data = data
        for feature_idx in range(len(features)):
            feature_tensor = torch.Tensor([features[feature_idx]]).long().to(input_data.device)
            data_feature = torch.index_select(input_data, feature_dim, feature_tensor)
            if data is None:
                curr_data = torch.zeros_like(data_feature)
                self.state[name]['mask'][feature_idx] = torch.ones_like(data_feature)
            else:
                curr_data = data[feature_idx]
            out_data[feature_idx] = agg_fn(curr_data, data_feature)
    self.data_groups[name]['data'] = out_data

def _testDtype(self, dtype):
    if <MASK>:
        fi = np.finfo(dtype)
        data = np.array([0, -1, 1, fi.resolution, -fi.resolution, fi.min, fi.max, -np.inf, np.inf, np.nan]).astype(dtype)
    else:
        data = np.array([0, -1, 1, 0.01, -0.01, -3.3895e+38, 3.3895e+38, -np.inf, np.inf, np.nan]).astype(dtype)
    self._compare(data, use_gpu=False)
    self._compare(data, use_gpu=True)

@staticmethod
def _components_to_string(job, replica, task, device_type, device_index):
    """Stateless portion of `to_string` (separated to allow caching)."""
    key = (job, replica, task, device_type, device_index)
    cached_result = _COMPONENTS_TO_STRING_CACHE.get(key)
    if cached_result is not None:
        return cached_result
    output = []
    if <MASK>:
        output.append('/job:' + job)
    if replica is not None:
        output.append('/replica:' + str(replica))
    if task is not None:
        output.append('/task:' + str(task))
    if device_type is not None:
        device_index_string = '*'
        if device_index is not None:
            device_index_string = str(device_index)
        output.append('/device:%s:%s' % (device_type, device_index_string))
    output = ''.join(output)
    _COMPONENTS_TO_STRING_CACHE[key] = output
    return output

def build_digest_header(self, method, url):
    """
        :rtype: str
        """
    realm = self._thread_local.chal['realm']
    nonce = self._thread_local.chal['nonce']
    qop = self._thread_local.chal.get('qop')
    algorithm = self._thread_local.chal.get('algorithm')
    opaque = self._thread_local.chal.get('opaque')
    hash_utf8 = None
    if algorithm is None:
        _algorithm = 'MD5'
    else:
        _algorithm = algorithm.upper()
    if _algorithm == 'MD5' or _algorithm == 'MD5-SESS':

        def md5_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.md5(x).hexdigest()
        hash_utf8 = md5_utf8
    elif _algorithm == 'SHA':

        def sha_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha1(x).hexdigest()
        hash_utf8 = sha_utf8
    elif _algorithm == 'SHA-256':

        def sha256_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha256(x).hexdigest()
        hash_utf8 = sha256_utf8
    elif _algorithm == 'SHA-512':

        def sha512_utf8(x):
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha512(x).hexdigest()
        hash_utf8 = sha512_utf8
    KD = lambda s, d: hash_utf8(f'{s}:{d}')
    if hash_utf8 is None:
        return None
    entdig = None
    p_parsed = urlparse(url)
    path = p_parsed.path or '/'
    if p_parsed.query:
        path += f'?{p_parsed.query}'
    A1 = f'{self.username}:{realm}:{self.password}'
    A2 = f'{method}:{path}'
    HA1 = hash_utf8(A1)
    HA2 = hash_utf8(A2)
    if nonce == self._thread_local.last_nonce:
        self._thread_local.nonce_count += 1
    else:
        self._thread_local.nonce_count = 1
    ncvalue = f'{self._thread_local.nonce_count:08x}'
    s = str(self._thread_local.nonce_count).encode('utf-8')
    s += nonce.encode('utf-8')
    s += time.ctime().encode('utf-8')
    s += os.urandom(8)
    cnonce = hashlib.sha1(s).hexdigest()[:16]
    if _algorithm == 'MD5-SESS':
        HA1 = hash_utf8(f'{HA1}:{nonce}:{cnonce}')
    if not qop:
        respdig = KD(HA1, f'{nonce}:{HA2}')
    elif qop == 'auth' or 'auth' in qop.split(','):
        noncebit = f'{nonce}:{ncvalue}:{cnonce}:auth:{HA2}'
        respdig = KD(HA1, noncebit)
    else:
        return None
    self._thread_local.last_nonce = nonce
    base = f'username="{self.username}", realm="{realm}", nonce="{nonce}", uri="{path}", response="{respdig}"'
    if <MASK>:
        base += f', opaque="{opaque}"'
    if algorithm:
        base += f', algorithm="{algorithm}"'
    if entdig:
        base += f', digest="{entdig}"'
    if qop:
        base += f', qop="auth", nc={ncvalue}, cnonce="{cnonce}"'
    return f'Digest {base}'

def serialize_input_spec(self, spec: ep.InputSpec) -> InputSpec:
    log.debug('[serialize_input_spec] %s', spec)
    if spec.kind == ep.InputKind.USER_INPUT:
        if isinstance(spec.arg, ep.ConstantArgument):
            if type(spec.arg.value) is int:
                constant_spec = ConstantValue.create(as_int=spec.arg.value)
            elif <MASK>:
                constant_spec = ConstantValue.create(as_bool=spec.arg.value)
            elif type(spec.arg.value) is str:
                constant_spec = ConstantValue.create(as_string=spec.arg.value)
            elif type(spec.arg.value) is float:
                constant_spec = ConstantValue.create(as_float=spec.arg.value)
            elif spec.arg.value is None:
                constant_spec = ConstantValue.create(as_none=True)
            else:
                raise SerializeError(f'Unhandled constant input {spec.arg.value} to serialize')
            return InputSpec.create(constant_input=InputToConstantInputSpec(name=spec.arg.name, value=constant_spec))
        else:
            return InputSpec.create(user_input=UserInputSpec(arg=self.serialize_argument_spec(spec.arg)))
    elif spec.kind == ep.InputKind.PARAMETER:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return InputSpec.create(parameter=InputToParameterSpec(arg=TensorArgument(name=spec.arg.name), parameter_name=spec.target))
    elif spec.kind == ep.InputKind.BUFFER:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        assert spec.persistent is not None
        return InputSpec.create(buffer=InputToBufferSpec(arg=TensorArgument(name=spec.arg.name), buffer_name=spec.target, persistent=spec.persistent))
    elif spec.kind == ep.InputKind.CONSTANT_TENSOR:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return InputSpec.create(tensor_constant=InputToTensorConstantSpec(arg=TensorArgument(name=spec.arg.name), tensor_constant_name=spec.target))
    elif spec.kind == ep.InputKind.CUSTOM_OBJ:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.CustomObjArgument)
        return InputSpec.create(custom_obj=InputToCustomObjSpec(arg=CustomObjArgument(name=spec.arg.name, class_fqn=spec.arg.class_fqn), custom_obj_name=spec.target))
    elif spec.kind == ep.InputKind.TOKEN:
        assert isinstance(spec.arg, ep.TokenArgument)
        return InputSpec.create(token=InputTokenSpec(arg=TokenArgument(name=spec.arg.name)))
    else:
        raise AssertionError(f'Unknown argument kind: {spec}')

@compatibility(is_backward_compatible=False)
def create_args_for_root(self, root_fn, is_module, concrete_args=None):
    """
        Create ``placeholder`` nodes corresponding to the signature of the ``root``
        Module. This method introspects root's signature and emits those
        nodes accordingly, also supporting ``*args`` and ``**kwargs``.
        """
    fn_for_analysis = inspect.unwrap(root_fn)
    co = fn_for_analysis.__code__
    total_args = co.co_argcount + co.co_kwonlyargcount
    orig_args = list(co.co_varnames)
    names_iter = iter(co.co_varnames)
    args: list[Any] = []
    skip_arg_idx = 0
    if is_module:
        if total_args == 0:
            raise RuntimeError('``self`` argument cannot be part of *args expansion!')
        skip_arg_idx = 1
        next(names_iter)
        args.append(self.root)
    sig = inspect.signature(fn_for_analysis)
    name_idx = 0
    if isinstance(concrete_args, tuple) and len(concrete_args) > 0 and co.co_flags & HAS_VARSTUFF and (total_args == 1):
        for concrete_arg in concrete_args:
            out = self.create_proxy('placeholder', f'input_{name_idx}', (), {})
            if isinstance(concrete_arg, PHBase):
                if concrete_arg != PH:
                    _transfer_attrs(fr=concrete_arg, to=out.node)
            args.append(out)
            name_idx += 1
        return (root_fn, args)
    arg_names = [next(names_iter) for idx in range(skip_arg_idx, total_args)]
    if isinstance(concrete_args, tuple):
        if len(arg_names) != len(concrete_args):
            raise RuntimeError(f'Tracing expected {len(arg_names)} arguments but got {len(concrete_args)} concrete arguments')
        concrete_args = dict(zip(arg_names, concrete_args))

    def proxy_placeholder(name):
        return self._proxy_placeholder(name, concrete_args, sig, fn_for_analysis)
    args.extend((proxy_placeholder(names) for names in arg_names))
    if co.co_kwonlyargcount > 0 or co.co_flags & HAS_VARSTUFF:
        if co.co_flags & inspect.CO_VARARGS:
            args.append(proxy_placeholder('*' + next(names_iter)))
        if co.co_flags & inspect.CO_VARKEYWORDS:
            args.append(proxy_placeholder('**' + next(names_iter)))
        root_fn = _patch_function(root_fn, len(args))
    (flat_args, in_spec) = pytree.tree_flatten(tuple(args))
    if <MASK>:
        self.graph._codegen = _PyTreeCodeGen(_PyTreeInfo(orig_args[:total_args], in_spec, None))

        def flatten_fn(*args):
            tree_args = pytree.tree_unflatten(list(args), in_spec)
            tree_out = root_fn(*tree_args)
            (out_args, out_spec) = pytree.tree_flatten(tree_out)
            assert isinstance(self.graph._codegen, _PyTreeCodeGen)
            self.graph._codegen.pytree_info = self.graph._codegen.pytree_info._replace(out_spec=out_spec)
            return out_args
        return (flatten_fn, flat_args)
    return (root_fn, args)

def get_language_from_request(request, check_path=False):
    """
    Analyze the request to find what language the user wants the system to
    show. Only languages listed in settings.LANGUAGES are taken into account.
    If the user requests a sublanguage where we have a main language, we send
    out the main language.

    If check_path is True, the URL path prefix will be checked for a language
    code, otherwise this is skipped for backwards compatibility.
    """
    if check_path:
        lang_code = get_language_from_path(request.path_info)
        if lang_code is not None:
            return lang_code
    lang_code = request.COOKIES.get(settings.LANGUAGE_COOKIE_NAME)
    if lang_code is not None and lang_code in get_languages() and check_for_language(lang_code):
        return lang_code
    try:
        return get_supported_language_variant(lang_code)
    except LookupError:
        pass
    accept = request.META.get('HTTP_ACCEPT_LANGUAGE', '')
    for (accept_lang, unused) in parse_accept_lang_header(accept):
        if <MASK>:
            break
        if not language_code_re.search(accept_lang):
            continue
        try:
            return get_supported_language_variant(accept_lang)
        except LookupError:
            continue
    try:
        return get_supported_language_variant(settings.LANGUAGE_CODE)
    except LookupError:
        return settings.LANGUAGE_CODE

def make_call_generated_code(self, fn_name: str) -> None:
    """Call the generated code function stored in fn_name"""
    self.extend_output(self.load_function_name(fn_name, True))
    graphargs = self.tx.output.graphargs
    seen_sources: OrderedSet[Source] = OrderedSet()

    def collect_temp_source(source: Source) -> None:
        if source in seen_sources:
            self.mark_source_temp(source)
            return
        seen_sources.add(source)
        if <MASK>:
            collect_temp_source(source.base)
        if isinstance(source, DictGetItemSource) and isinstance(source.index, Source):
            collect_temp_source(source.index)
    for arg in graphargs:
        if arg.source is not None:
            collect_temp_source(arg.source)
    cm_var = None
    if config.record_runtime_overhead:
        self.add_push_null(lambda : self.load_import_from(utils.__name__, 'record_pregraph_bytecode_enter'))
        self.extend_output(create_call_function(0, False))
        cm_var = self.new_var()
        self.store(cm_var)
    for arg in graphargs:
        if arg.pass_arg_as_tensor:
            self.add_push_null(lambda : self.extend_output([self.create_load_python_module(torch), self.create_load_attr('_as_tensor_fullprec')]))
            self.call_reconstruct(arg)
            self.extend_output(create_call_function(1, False))
        else:
            self.call_reconstruct(arg)
    if config.record_runtime_overhead:
        self.add_push_null(lambda : self.load_import_from(utils.__name__, 'record_pregraph_bytecode_exit'))
        assert cm_var is not None
        self.extend_output([self.create_load(cm_var)])
        self.extend_output(create_call_function(1, False))
        self.pop_top()
    self.extend_output(create_call_function(len(graphargs), False))

def __call__(self, frame: DynamoFrameType, cache_entry: Optional[CacheEntry], hooks: Hooks, frame_state: dict[str, Union[int, FrameStateSizeEntry]], *, skip: int=0) -> ConvertFrameReturn:
    increment_frame()
    code = frame.f_code
    cache_size = compute_cache_size(frame, cache_entry)
    input_codes.add(code)
    if code in output_codes:
        return ConvertFrameReturn()
    if os.environ.get('TORCHDYNAMO_DEBUG_FUNCTION') and os.environ.get('TORCHDYNAMO_DEBUG_FUNCTION') != code.co_name:
        return ConvertFrameReturn()
    if code.co_name == '<genexpr>' and code.co_filename.endswith(('transformers/file_utils.py', 'transformers/utils/generic.py', 'diffusers/utils/outputs.py')):
        return ConvertFrameReturn()
    if code.co_name == '__setattr__':
        return ConvertFrameReturn()
    if code.co_name == '__init__' and code.co_filename.startswith(os.path.dirname(torch.optim.__file__)):
        return ConvertFrameReturn()
    if <MASK>:
        return ConvertFrameReturn()
    if code.co_name == '<lambda>' and code.co_filename == '<string>' and (not bool(frame.f_builtins)):
        return ConvertFrameReturn()
    if is_generator(code):
        unimplemented_v2(gb_type='Attempt to trace generator', context='', explanation='Generators cannot be compiled directly with `torch.compile`.', hints=['Call a generator from inside of a non-generator Python function and compile that function instead.', *graph_break_hints.FUNDAMENTAL])
    if not has_tensor_in_frame(frame):
        return ConvertFrameReturn()
    prev_frame = sys._getframe()
    while prev_frame and 'torch/_dynamo/convert_frame.py' in prev_frame.f_code.co_filename:
        prev_frame = prev_frame.f_back
    if prev_frame and prev_frame.f_code is decorators._nonrecursive_disable_wrapper_code:
        return ConvertFrameReturn(apply_to_code=False)
    global initial_global_state
    initial_global_state = GlobalStateGuard()
    compile_id = get_compile_id(frame_state)
    frame_id = compile_id.frame_id
    signpost_event('dynamo', '_convert_frame_assert._compile', {'co_name': code.co_name, 'frame_id': frame_id, 'compile_id': str(compile_id), 'co_filename': code.co_filename, 'co_firstlineno': code.co_firstlineno, 'cache_size': cache_size.num_cache_entries_with_same_id_matched_objs, 'accumulated_cache_size': cache_size.num_cache_entries})
    if not code.co_name.startswith(TORCH_DYNAMO_RESUME_IN_PREFIX):
        info = f'{code.co_name} {code.co_filename}:{code.co_firstlineno}'
        dynamo_tls.traced_frame_infos.append(info)
    with compile_context(CompileContext(compile_id)):
        result = _compile(frame.f_code, frame.f_globals, frame.f_locals, frame.f_builtins, frame.closure, self._torchdynamo_orig_backend, self._one_graph, self._export, self._export_constraints, hooks, cache_entry, cache_size, frame, frame_state=frame_state, compile_id=compile_id, skip=skip + 1, package=self._package, convert_frame_box=self._box)
    if config.caching_precompile and self._package is not None:
        from .package import DynamoCache
        DynamoCache.record_package(self._package)
    return result

def prepare_lookup_value(key, value, separator=','):
    """
    Return a lookup value prepared to be used in queryset filtering.
    """
    if <MASK>:
        return [prepare_lookup_value(key, v, separator=separator) for v in value]
    if key.endswith('__in'):
        value = value.split(separator)
    elif key.endswith('__isnull'):
        value = value.lower() not in ('', 'false', '0')
    return value

def setup(self, unique, keep, dtype):
    N = 10 ** 5
    if dtype in ['int64', 'uint64']:
        data = pd.Index(np.arange(N), dtype=dtype)
    elif <MASK>:
        data = pd.Index(np.random.randn(N), dtype='float64')
    elif dtype == 'string':
        data = pd.Index([f'i-{i}' for i in range(N)], dtype=object)
    elif dtype == 'datetime64[ns]':
        data = pd.date_range('2011-01-01', freq='h', periods=N)
    elif dtype == 'datetime64[ns, tz]':
        data = pd.date_range('2011-01-01', freq='h', periods=N, tz='Asia/Tokyo')
    elif dtype in ['timestamp[ms][pyarrow]', 'duration[s][pyarrow]']:
        data = pd.Index(np.arange(N), dtype=dtype)
    else:
        raise NotImplementedError
    if not unique:
        data = data.repeat(5)
    self.idx = data
    self.idx.is_unique

def __torch_dispatch__(self, func, types, args=(), kwargs=None):
    kwargs = kwargs if kwargs else {}
    if func in {torch.ops.aten.sym_is_contiguous.default, torch.ops.aten.is_contiguous.default, torch.ops.aten.is_contiguous.memory_format, torch.ops.aten.is_strides_like_format.default, torch.ops.aten.is_non_overlapping_and_dense.default, torch.ops.aten.size.default, torch.ops.aten.sym_size.default, torch.ops.aten.stride.default, torch.ops.aten.sym_stride.default, torch.ops.aten.storage_offset.default, torch.ops.aten.sym_storage_offset.default, torch.ops.aten.numel.default, torch.ops.aten.sym_numel.default, torch.ops.aten.dim.default, torch.ops.prim.layout.default}:
        return NotImplemented
    if <MASK>:
        return self._handle_higher_order_ops(func, types, args, kwargs)
    if func not in self.counter.flop_registry and func is not torch.ops.prim.device.default:
        with self:
            r = func.decompose(*args, **kwargs)
            if r is not NotImplemented:
                return r
    out = func(*args, **kwargs)
    return self.counter._count_flops(func._overloadpacket, out, args, kwargs)

def get_traced_sample_variant_pairs(device, dtype, op):
    outputs: list[tuple[Any, Any]] = []
    samples = op.sample_inputs(device, dtype)
    func = op.get_op()
    method = op.get_method()
    variants = {'function': func, 'method': method}
    has_fake_function = op.name in ['resize_', 'resize_as_']
    if has_fake_function:
        variants = {'method': getattr(torch.Tensor, op.name)}
    ops_with_unsupported_bool_args = [{'name': 'div_floor_rounding', 'arg_idx': [0]}, {'name': 'div_no_rounding_mode', 'arg_idx': [0]}, {'name': 'div_trunc_rounding', 'arg_idx': [0]}, {'name': 'index_fill', 'arg_idx': [2]}, {'name': 'full_like', 'arg_idx': [0]}, {'name': 'mul', 'arg_idx': [0]}, {'name': 'new_full', 'arg_idx': [1]}]
    if has_fake_function:
        return outputs
    for sample in samples:
        for variant in variants.values():
            if <MASK>:
                continue
            if is_lambda(variant):
                continue
            matching_ops = filter(lambda x: op.formatted_name == x['name'], ops_with_unsupported_bool_args)
            for op_data in matching_ops:
                for idx in op_data['arg_idx']:
                    args = list(sample.args)
                    if len(sample.args) > idx and isinstance(sample.args[idx], bool):
                        args[idx] = int(args[idx])
                    sample.args = tuple(args)
            outputs.append((variant, sample))
    return outputs

def decorator(fun):

    @functools.wraps(fun)
    def wrapper(*args, **kwargs):
        __tracebackhide__ = True
        for (old_name, new_name) in zip(old_names, new_names):
            if old_name in kwargs:
                if dep_version:
                    end_version = dep_version.split('.')
                    end_version[1] = str(int(end_version[1]) + 2)
                    end_version = '.'.join(end_version)
                    msg = f'Use of keyword argument `{old_name}` is deprecated and replaced by `{new_name}`. Support for `{old_name}` will be removed in NumPy {end_version}.'
                    warnings.warn(msg, DeprecationWarning, stacklevel=2)
                if <MASK>:
                    msg = f'{fun.__name__}() got multiple values for argument now known as `{new_name}`'
                    raise TypeError(msg)
                kwargs[new_name] = kwargs.pop(old_name)
        return fun(*args, **kwargs)
    return wrapper

def _create_scaling_models_optimizers(device='cuda', optimizer_ctor=torch.optim.SGD, optimizer_kwargs=None):
    mod_control = torch.nn.Sequential(torch.nn.Linear(8, 8), torch.nn.Linear(8, 8)).to(device=device)
    mod_scaling = torch.nn.Sequential(torch.nn.Linear(8, 8), torch.nn.Linear(8, 8)).to(device=device)
    with torch.no_grad():
        for (c, s) in zip(mod_control.parameters(), mod_scaling.parameters(), strict=True):
            s.copy_(c)
    kwargs = {'lr': 1.0}
    if <MASK>:
        kwargs.update(optimizer_kwargs)
    opt_control = optimizer_ctor(mod_control.parameters(), **kwargs)
    opt_scaling = optimizer_ctor(mod_scaling.parameters(), **kwargs)
    return (mod_control, mod_scaling, opt_control, opt_scaling)

@compatibility(is_backward_compatible=False)
def topo_sort(nodes: NodeList) -> NodeList:
    indegree_map = dict.fromkeys(nodes, 0)
    candidates: SimpleQueue[Node] = SimpleQueue()
    for node in nodes:
        for n in node.all_input_nodes:
            if n in indegree_map:
                indegree_map[node] += 1
        if indegree_map[node] == 0:
            candidates.put(node)
    sorted_nodes: NodeList = []
    while not candidates.empty():
        node = candidates.get()
        sorted_nodes.append(node)
        for n in node.users:
            if n in indegree_map:
                indegree_map[n] -= 1
                if <MASK>:
                    candidates.put(n)
    assert len(nodes) == len(sorted_nodes), "topological sorted nodes doesn't have same length as input nodes"
    return sorted_nodes

@doc_controls.header(_FEATURE_COLUMN_DEPRECATION_WARNING)
