    else:
        raise ValueError('Instance: {} is not a FeatureColumn'.format(fc))

def checkGraphModuleNodes(self, graph_module, expected_node=None, expected_node_occurrence=None, expected_node_list=None):
    """Check if GraphModule contains the target node
        Args:
            graph_module: the GraphModule instance we want to check
            expected_node, expected_node_occurrence, expected_node_list:
               see docs for checkGraphModeFxOp
        """
    nodes_in_graph = {}
    node_list = []
    modules = dict(graph_module.named_modules(remove_duplicate=False))
    for node in graph_module.graph.nodes:
        n = None
        if node.op == 'call_function' or node.op == 'call_method':
            n = NodeSpec(node.op, node.target)
        elif node.op == 'call_module':
            n = NodeSpec(node.op, type(modules[node.target]))
        if <MASK>:
            node_list.append(n)
            if n in nodes_in_graph:
                nodes_in_graph[n] += 1
            else:
                nodes_in_graph[n] = 1
    if expected_node is not None:
        self.assertTrue(expected_node in nodes_in_graph, 'node:' + str(expected_node) + ' not found in the graph module')
    if expected_node_occurrence is not None:
        for (expected_node, occurrence) in expected_node_occurrence.items():
            if occurrence != 0:
                self.assertTrue(expected_node in nodes_in_graph, 'Check failed for node:' + str(expected_node) + ' not found')
                self.assertTrue(nodes_in_graph[expected_node] == occurrence, 'Check failed for node:' + str(expected_node) + ' Expected occurrence:' + str(occurrence) + ' Found occurrence:' + str(nodes_in_graph[expected_node]))
            else:
                self.assertTrue(expected_node not in nodes_in_graph, 'Check failed for node:' + str(expected_node) + ' expected no occurrence but found')
    if expected_node_list is not None:
        cur_index = 0
        for n in node_list:
            if cur_index == len(expected_node_list):
                return
            if n == expected_node_list[cur_index]:
                cur_index += 1
        self.assertTrue(cur_index == len(expected_node_list), 'Check failed for graph:' + self.printGraphModule(graph_module, print_str=False) + 'Expected ordered list:' + str(expected_node_list))

def _test_gather_helper(self, group, group_id, rank, cuda=False, rank_to_GPU=None):
    for dest in group:
        tensor = _build_tensor(dest + 1, rank)
        tensors = [_build_tensor(dest + 1, -1) for i in group] if rank == dest else []
        if <MASK>:
            tensor = tensor.cuda(rank_to_GPU[rank][0])
            tensors = [t.cuda(rank_to_GPU[rank][0]) for t in tensors]
        self.call_dist_op(':gather', False, dist.gather, tensor, dst=dest, gather_list=tensors, group=group_id, expect_event=False, tensor_shapes=[tensors[0].shape] if len(tensors) > 0 else None)
        if rank == dest:
            expected_tensors = [_build_tensor(dest + 1, i) for i in group]
            for (t1, t2) in zip(tensors, expected_tensors, strict=True):
                self.assertEqual(t1, t2)
    self._barrier()

def _parse_target_tokens(self, tokens):
    assert isinstance(tokens, str)
    final_targets = []
    extra_flags = []
    has_baseline = False
    skipped = set()
    policies = set()
    multi_target = None
    tokens = list(filter(None, re.split(self._parse_regex_target, tokens)))
    if not tokens:
        self.dist_fatal('expected one token at least')
    for tok in tokens:
        TOK = tok.upper()
        ch = tok[0]
        if ch in ('+', '-'):
            self.dist_fatal("+/- are 'not' allowed from target's groups or @targets, only from cpu_baseline and cpu_dispatch parms")
        elif ch == '$':
            if <MASK>:
                self.dist_fatal("policies aren't allowed inside multi-target '()', only CPU features")
            policies.add(self._parse_token_policy(TOK))
        elif ch == '#':
            if multi_target is not None:
                self.dist_fatal("target groups aren't allowed inside multi-target '()', only CPU features")
            (has_baseline, final_targets, extra_flags) = self._parse_token_group(TOK, has_baseline, final_targets, extra_flags)
        elif ch == '(':
            if multi_target is not None:
                self.dist_fatal("unclosed multi-target, missing ')'")
            multi_target = set()
        elif ch == ')':
            if multi_target is None:
                self.dist_fatal("multi-target opener '(' wasn't found")
            targets = self._parse_multi_target(multi_target)
            if targets is None:
                skipped.add(tuple(multi_target))
            else:
                if len(targets) == 1:
                    targets = targets[0]
                if targets and targets not in final_targets:
                    final_targets.append(targets)
            multi_target = None
        else:
            if TOK == 'BASELINE':
                if multi_target is not None:
                    self.dist_fatal("baseline isn't allowed inside multi-target '()'")
                has_baseline = True
                continue
            if multi_target is not None:
                multi_target.add(TOK)
                continue
            if not self.feature_is_exist(TOK):
                self.dist_fatal("invalid target name '%s'" % TOK)
            is_enabled = TOK in self.parse_baseline_names or TOK in self.parse_dispatch_names
            if is_enabled:
                if TOK not in final_targets:
                    final_targets.append(TOK)
                continue
            skipped.add(TOK)
    if multi_target is not None:
        self.dist_fatal("unclosed multi-target, missing ')'")
    if skipped:
        self.dist_log('skip targets', skipped, 'not part of baseline or dispatch-able features')
    final_targets = self.feature_untied(final_targets)
    for p in list(policies):
        (_, _, deps) = self._parse_policies[p]
        for d in deps:
            if d in policies:
                continue
            self.dist_log("policy '%s' force enables '%s'" % (p, d))
            policies.add(d)
    for (p, (have, nhave, _)) in self._parse_policies.items():
        func = None
        if p in policies:
            func = have
            self.dist_log("policy '%s' is ON" % p)
        else:
            func = nhave
        if not func:
            continue
        (has_baseline, final_targets, extra_flags) = func(has_baseline, final_targets, extra_flags)
    return (has_baseline, final_targets, extra_flags)

def _check_external_modification(self):
    """Checks for any changes to the wrapped list not through the wrapper."""
    if <MASK>:
        return
    if self._storage != self._last_wrapped_list_snapshot:
        self._external_modification = True
        self._last_wrapped_list_snapshot = None

@TorchPatcher.suppress_torch_distributed_warnings
def has_tensor_in_frame(frame: DynamoFrameType) -> bool:
    """Check if the frame has torch.* related bits"""
    if frame.f_code in always_optimize_code_objects:
        return True
    for co_name in frame.f_code.co_names:
        if co_name in frame.f_globals:
            obj = frame.f_globals[co_name]
            if isinstance(obj, ModuleType) and (obj.__name__.startswith('torch.') or obj is torch):
                return True
            if np and config.trace_numpy and (obj is np or is_numpy(obj)):
                return True
    seen_ids: dict[int, bool] = {}

    def has_tensor(obj: object) -> bool:
        """Recursively check if the obj has a tensor"""
        obj_id = id(obj)
        if obj_id in seen_ids:
            return seen_ids[obj_id]
        seen_ids[obj_id] = False
        if isinstance(obj, (torch.Tensor, torch.nn.Module)) or (istype(obj, type) and issubclass(obj, torch.nn.Module)):
            seen_ids[obj_id] = True
            return seen_ids[obj_id]
        elif config.trace_numpy and np and (istype(obj, np.ndarray) or isinstance(obj, np.generic)):
            seen_ids[obj_id] = True
            return seen_ids[obj_id]
        elif istype(obj, (list, tuple)):
            seen_ids[obj_id] = any((has_tensor(v) for v in obj))
            return seen_ids[obj_id]
        elif <MASK>:
            values = list(obj.values())
            seen_ids[obj_id] = any((has_tensor(v) for v in values))
            return seen_ids[obj_id]
        elif istype(obj, (str, int, float, type(None), bool)):
            seen_ids[obj_id] = False
            return seen_ids[obj_id]
        elif is_namedtuple(obj) and hasattr(obj, '_fields'):
            seen_ids[obj_id] = any((has_tensor(getattr(obj, v)) for v in obj._fields))
            return seen_ids[obj_id]
        else:
            return False
    for value in frame.f_locals.values():
        if has_tensor(value):
            return True
    log.debug('skipping because no torch.* %s             %s %s', frame.f_code.co_name, frame.f_code.co_filename, frame.f_code.co_firstlineno)
    return False

def _n_parameters(self):
    """Return the number of free parameters in the model."""
    (_, n_features) = self.means_.shape
    if self.covariance_type == 'full':
        cov_params = self.n_components * n_features * (n_features + 1) / 2.0
    elif <MASK>:
        cov_params = self.n_components * n_features
    elif self.covariance_type == 'tied':
        cov_params = n_features * (n_features + 1) / 2.0
    elif self.covariance_type == 'spherical':
        cov_params = self.n_components
    mean_params = n_features * self.n_components
    return int(cov_params + mean_params + self.n_components - 1)

def _is_backward(graph: torch.fx.Graph) -> bool:
    placeholders = []
    for node in graph.nodes:
        if <MASK>:
            break
        placeholders.append(node)
    return not all((node.name.startswith('primal') for node in placeholders))

