@classmethod
def eval(cls, base: sympy.Integer, divisor: sympy.Integer) -> Union[sympy.Basic, None]:
    if divisor.is_zero:
        raise ZeroDivisionError('division by zero')
    if <MASK>:
        return sympy.nan
    if base is sympy.nan or divisor is sympy.nan:
        return sympy.nan
    if base.is_zero:
        return sympy.S.Zero
    if base.is_integer and equal_valued(divisor, 1):
        return base
    if base.is_integer and equal_valued(divisor, -1):
        return sympy.Mul(base, -1)
    if isinstance(base, sympy.Number) and isinstance(divisor, sympy.Number) and (base in (int_oo, -int_oo, sympy.oo, -sympy.oo) or divisor in (int_oo, -int_oo, sympy.oo, -sympy.oo)):
        r = float(base) / float(divisor)
        if r == math.inf:
            return int_oo
        elif r == -math.inf:
            return -int_oo
        elif math.isnan(r):
            return sympy.nan
        else:
            return sympy.Integer(math.floor(r))
    if isinstance(base, sympy.Integer) and isinstance(divisor, sympy.Integer):
        return sympy.Integer(int(base) // int(divisor))
    if isinstance(base, FloorDiv):
        return FloorDiv(base.args[0], base.args[1] * divisor)
    if isinstance(divisor, sympy.Integer):
        quotients = 0
        terms = []
        for term in sympy.Add.make_args(base):
            quotient = term / divisor
            quotient_is_integer = None
            if isinstance(quotient, sympy.Mul) and TorchVersion(sympy.__version__) < TorchVersion('1.15.0'):
                rationals = quotient.atoms(sympy.Rational)
                all_rationals_ints = all((r.q == 1 for r in rationals))
                quotient_is_integer = quotient.is_integer and all_rationals_ints
            else:
                quotient_is_integer = quotient.is_integer
            if quotient_is_integer:
                terms.append(term)
                quotients += quotient
        if len(terms) != 0:
            return FloorDiv(base - sympy.Add(*terms, evaluate=False), divisor) + quotients
    try:
        gcd = simple_floordiv_gcd(base, divisor)
        if equal_valued(gcd, 1) and isinstance(divisor, sympy.Add):
            gcd = sympy.gcd(base, divisor)
        if not equal_valued(gcd, 1):
            return FloorDiv(sympy.simplify(base / gcd), sympy.simplify(divisor / gcd))
    except sympy.PolynomialError:
        pass
    return None

def _deprecate_positional_args(func=None, *, version='1.3'):
    """Decorator for methods that issues warnings for positional arguments.

    Using the keyword-only argument syntax in pep 3102, arguments after the
    * will issue a warning when passed as a positional argument.

    Parameters
    ----------
    func : callable, default=None
        Function to check arguments on.
    version : callable, default="1.3"
        The version when positional arguments will result in error.
    """

    def _inner_deprecate_positional_args(f):
        sig = signature(f)
        kwonly_args = []
        all_args = []
        for (name, param) in sig.parameters.items():
            if param.kind == Parameter.POSITIONAL_OR_KEYWORD:
                all_args.append(name)
            elif <MASK>:
                kwonly_args.append(name)

        @wraps(f)
        def inner_f(*args, **kwargs):
            extra_args = len(args) - len(all_args)
            if extra_args <= 0:
                return f(*args, **kwargs)
            args_msg = ['{}={}'.format(name, arg) for (name, arg) in zip(kwonly_args[:extra_args], args[-extra_args:])]
            args_msg = ', '.join(args_msg)
            warnings.warn(f'Pass {args_msg} as keyword args. From version {version} passing these as positional arguments will result in an error', FutureWarning)
            kwargs.update(zip(sig.parameters, args))
            return f(**kwargs)
        return inner_f
    if func is not None:
        return _inner_deprecate_positional_args(func)
    return _inner_deprecate_positional_args

def win_wrap_single_compile(sources, output_dir=None, macros=None, include_dirs=None, debug=0, extra_preargs=None, extra_postargs=None, depends=None):
    self.cflags = copy.deepcopy(extra_postargs)
    extra_postargs = None

    def spawn(cmd):
        src_regex = re.compile('/T(p|c)(.*)')
        src_list = [m.group(2) for m in (src_regex.match(elem) for elem in cmd) if m]
        obj_regex = re.compile('/Fo(.*)')
        obj_list = [m.group(1) for m in (obj_regex.match(elem) for elem in cmd) if m]
        include_regex = re.compile('((\\-|\\/)I.*)')
        include_list = [m.group(1) for m in (include_regex.match(elem) for elem in cmd) if m]
        if len(src_list) >= 1 and len(obj_list) >= 1:
            src = src_list[0]
            obj = obj_list[0]
            if _is_cuda_file(src):
                if IS_HIP_EXTENSION:
                    nvcc = _get_hipcc_path()
                else:
                    nvcc = _join_cuda_home('bin', 'nvcc')
                if isinstance(self.cflags, dict):
                    cflags = self.cflags['nvcc']
                elif <MASK>:
                    cflags = self.cflags
                else:
                    cflags = []
                if IS_HIP_EXTENSION:
                    cflags = win_hip_flags(cflags)
                else:
                    cflags = win_cuda_flags(cflags) + ['-std=c++17', '--use-local-env']
                    for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                        cflags = ['-Xcudafe', '--diag_suppress=' + ignore_warning] + cflags
                for flag in COMMON_MSVC_FLAGS:
                    cflags = ['-Xcompiler', flag] + cflags
                cmd = [nvcc, '-c', src, '-o', obj] + include_list + cflags
            elif isinstance(self.cflags, dict):
                cflags = COMMON_MSVC_FLAGS + self.cflags['cxx']
                append_std17_if_no_std_present(cflags)
                cmd += cflags
            elif isinstance(self.cflags, list):
                cflags = COMMON_MSVC_FLAGS + self.cflags
                append_std17_if_no_std_present(cflags)
                cmd += cflags
        return original_spawn(cmd)
    try:
        self.compiler.spawn = spawn
        return original_compile(sources, output_dir, macros, include_dirs, debug, extra_preargs, extra_postargs, depends)
    finally:
        self.compiler.spawn = original_spawn

def maybe_propagate(schema_arg: torch._C.Argument, old_arg: ir.IRNode, new_arg: ir.IRNode) -> None:
    if old_arg is new_arg:
        return
    if schema_arg.alias_info is not None and schema_arg.alias_info.is_write:
        if isinstance(old_arg, ir.IRNode):
            old_arg = (old_arg,)
            new_arg = (new_arg,)
        for (old_arg_item, new_arg_item) in zip(old_arg, new_arg):
            if <MASK>:
                continue
            self.call_function(torch.ops.aten.copy_.default, (old_arg_item, new_arg_item), {})

