def __init__(self, values, categories=None, ordered=None, dtype: Dtype | None=None, copy: bool=True) -> None:
    dtype = CategoricalDtype._from_values_or_dtype(values, categories, ordered, dtype)
    if not is_list_like(values):
        raise TypeError('Categorical input must be list-like')
    null_mask = np.array(False)
    vdtype = getattr(values, 'dtype', None)
    if isinstance(vdtype, CategoricalDtype):
        if dtype.categories is None:
            dtype = CategoricalDtype(values.categories, dtype.ordered)
    elif isinstance(values, range):
        from pandas.core.indexes.range import RangeIndex
        values = RangeIndex(values)
    elif not isinstance(values, (ABCIndex, ABCSeries, ExtensionArray)):
        values = com.convert_to_list_like(values)
        if <MASK>:
            values = np.array([], dtype=object)
        elif isinstance(values, np.ndarray):
            if values.ndim > 1:
                raise NotImplementedError('> 1 ndim Categorical are not supported at this time')
            values = sanitize_array(values, None)
        else:
            arr = sanitize_array(values, None)
            null_mask = isna(arr)
            if null_mask.any():
                arr_list = [values[idx] for idx in np.where(~null_mask)[0]]
                if arr_list or arr.dtype == 'object':
                    sanitize_dtype = None
                else:
                    sanitize_dtype = arr.dtype
                arr = sanitize_array(arr_list, None, dtype=sanitize_dtype)
            values = arr
    if dtype.categories is None:
        if isinstance(values.dtype, ArrowDtype) and issubclass(values.dtype.type, CategoricalDtypeType):
            from pandas import Index
            if isinstance(values, Index):
                arr = values._data._pa_array.combine_chunks()
            else:
                arr = extract_array(values)._pa_array.combine_chunks()
            categories = arr.dictionary.to_pandas(types_mapper=ArrowDtype)
            codes = arr.indices.to_numpy()
            dtype = CategoricalDtype(categories, values.dtype.pyarrow_dtype.ordered)
        else:
            if not isinstance(values, ABCIndex):
                values = sanitize_array(values, None)
            try:
                (codes, categories) = factorize(values, sort=True)
            except TypeError as err:
                (codes, categories) = factorize(values, sort=False)
                if dtype.ordered:
                    raise TypeError("'values' is not ordered, please explicitly specify the categories order by passing in a categories argument.") from err
            dtype = CategoricalDtype(categories, dtype.ordered)
    elif isinstance(values.dtype, CategoricalDtype):
        old_codes = extract_array(values)._codes
        codes = recode_for_categories(old_codes, values.dtype.categories, dtype.categories, copy=copy, warn=True)
    else:
        codes = _get_codes_for_values(values, dtype.categories)
    if null_mask.any():
        full_codes = -np.ones(null_mask.shape, dtype=codes.dtype)
        full_codes[~null_mask] = codes
        codes = full_codes
    dtype = CategoricalDtype(ordered=False).update_dtype(dtype)
    arr = coerce_indexer_dtype(codes, dtype.categories)
    super().__init__(arr, dtype)

def jit_lines(self):
    if self.use_jit:
        return '@triton.jit'
    (argdefs, _, signature, _) = self.args.python_argdefs()
    triton_meta: dict[str, Any] = {'signature': signature_to_meta(signature, size_dtype=self.index_dtype, argdefs=argdefs, is_template=True), 'device': DeviceProperties.create(self.output_node.get_device()), 'constants': {}}
    triton_meta['configs'] = [config_of(signature)]
    for arg_num in equal_1_arg_indices(signature):
        triton_meta['constants'][signature[arg_num].name] = 1
    matrix_instr_nonkdim = self.meta.get('matrix_instr_nonkdim', None)
    waves_per_eu = self.meta.get('waves_per_eu', None)
    kpack = self.meta.get('kpack', None)
    if matrix_instr_nonkdim:
        triton_meta['matrix_instr_nonkdim'] = matrix_instr_nonkdim
    if waves_per_eu:
        triton_meta['waves_per_eu'] = waves_per_eu
    if <MASK>:
        triton_meta['kpack'] = kpack
    self.triton_meta = triton_meta
    inductor_meta = {'kernel_name': str(Placeholder.DESCRIPTIVE_NAME), **self.inductor_meta_common(), **FixedGrid.setup_grid_as_args()}
    if config.profile_bandwidth or config.benchmark_kernel:
        num_gb = self.estimate_kernel_num_bytes() / 1000000000.0
        inductor_meta['kernel_num_gb'] = num_gb
    if config.benchmark_kernel:
        flops = self.estimate_flops()
        inductor_meta['kernel_flop'] = flops
    inductor_meta['config_args'] = self.meta
    template_args = f'\n            num_stages={self.num_stages},\n            num_warps={self.num_warps},\n            triton_meta={triton_meta!r},\n            inductor_meta={inductor_meta!r},\n        '
    if HAS_WARP_SPEC:
        template_args += f'\n            num_consumer_groups={self.num_consumer_groups},\n            num_buffers_warp_spec={self.num_buffers_warp_spec},\n        '
    return f'\n            @triton_heuristics.template(\n                {template_args}\n            )\n            @triton.jit\n        '

def can_fuse(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode, can_reorder: bool=False) -> bool:
    """
        Determine if it is possible to combine node1 and node2 into a
        single fused node.
        """
    if <MASK>:
        return False
    why = WhyNoFuse(node1, node2)
    if node1.is_template() and self.get_backend(node1.get_device()).can_fuse_multi_outputs_template(node1, node2):
        return True
    if isinstance(node1, GroupedSchedulerNode) or isinstance(node2, GroupedSchedulerNode):
        why('grouped node must not be fused with other nodes')
        return False
    if isinstance(node1, (ExternKernelSchedulerNode, NopKernelSchedulerNode)) and (not node1.is_template()):
        why('node1 is extern or nop')
        return False
    if isinstance(node2, (ExternKernelSchedulerNode, NopKernelSchedulerNode)) and (not node2.is_template()):
        why('node2 is extern or nop')
        return False
    if node2.get_operation_names() & node1.ancestors:
        why('node1 must go before node2')
        return False
    if node2.is_template():
        if not config.prologue_fusion:
            why('prologue fusion turned off')
            return False
        if node1.is_reduction() or node1.is_template():
            why('prologue fusion only supported for pointwise nodes')
            return False
        template = node2.get_template_node_or_throw()
        if not isinstance(template, ir.TritonTemplateBuffer):
            why('prologue fusion only supported for TritonTemplates')
            return False
        allowed_prologue_inps = template.get_allowed_prologue_inps()
        unsupported_prologue_args = OrderedSet((inp.get_name() for inp in template.inputs)) - allowed_prologue_inps
        if node1.get_buffer_names() & unsupported_prologue_args:
            why('prologue fusion not implemented for kernel for these inputs')
            return False
        if node1.has_aliasing_or_mutation() or node1.has_aliasing_or_mutation():
            why('template prologue can only fuse functional pointwise nodes')
            return False
        prologue_nodes = node1.get_nodes()
        for node in prologue_nodes[:-1]:
            node_outs = node.get_outputs()
            for out in node_outs:
                if not all((user.node in prologue_nodes for user in out.users)):
                    why('template prologue can only fuse nodes with a single use')
                    return False
        template_snodes = [node2] if not isinstance(node2, FusedSchedulerNode) else [n for n in node2.snodes if n.is_template()]
        assert len(template_snodes) == 1
        template_snode = template_snodes[0]
        if not (len(prologue_nodes[-1].outputs) == 1 and len(prologue_nodes[-1].outputs[0].users) == 1 and (prologue_nodes[-1].outputs[0].users[0].node is template_snode)):
            why('template prologue can only fuse nodes with a single use into template')
            return False
        if not self.check_prologue_fusion_heuristics_fusable(node1, node2, why):
            return False
    if node1.is_template() and (node2.has_aliasing_or_mutation() or node2.is_reduction() or (not config.epilogue_fusion)):
        why('template epilogue not satisfied')
        return False
    if node1.get_buffer_names() & V.graph.no_fuse_buffer_names or node2.get_buffer_names() & V.graph.no_fuse_buffer_names:
        why('fusion for buffer explicit disabled')
        return False
    device = node1.get_device()
    device2 = node2.get_device()
    if device != device2:
        why('device mismatch (%s vs %s)', device, device2)
        return False
    del device2
    shared_data_score = self.score_fusion_memory(node1, node2)
    if can_reorder and shared_data_score < config.score_fusion_memory_threshold and config.loop_ordering_after_fusion:
        new_shared_data_score = self.shared_data_after_reordering_loop(node1, node2)
        if new_shared_data_score >= 0:
            shared_data_score = new_shared_data_score
    if config.expand_dimension_for_pointwise_nodes and (expand_analysis := self.get_expand_dim_for_pointwise_nodes(node1, node2)):
        (expand_dim, smaller_node, expand_size) = expand_analysis
        smaller_node.expand_dimension_for_pointwise_node(expand_dim, expand_size)
        shared_data_score = self.score_fusion_memory(node1, node2)
    if loop_ordering_log.isEnabledFor(logging.DEBUG):
        loop_ordering_log.debug('%s and %s has %s shared data', node1.get_name(), node2.get_name(), shared_data_score)
    if not V.choices.can_fuse(self, node1, node2, shared_data_score):
        return False
    if node1.get_operation_names() & node2.ancestors:
        return self.can_fuse_vertical(node1, node2) and V.choices.can_fuse_vertical(self, node1, node2, shared_data_score) and self.get_backend(device).can_fuse_vertical(node1, node2)
    else:
        return V.choices.can_fuse_horizontal(self, node1, node2, shared_data_score) and self.get_backend(device).can_fuse_horizontal(node1, node2)

@final
