def _skip_tensor(self, op_id, out_tensor, report_handler):
    """Returns True if we should not trace out_tensor.

    Args:
      op_id: Topological index of the op producing tensor.
      out_tensor: tf.Tensor
      report_handler: An instance of tensor_tracer_report.TTReportHandle.
    Returns:
      True if the tensor should not be traced, false otherwise.
    """
    non_numeric_tensor_types = set([dtypes.variant, dtypes.resource, dtypes.string])
    if out_tensor.dtype in non_numeric_tensor_types:
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_NON_NUMERIC_TENSOR))
        return True
    if [consumer for consumer in out_tensor.consumers() if TensorTracer.while_loop_op(consumer)]:
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_FEEDS_WHILELOOP_OP))
        return True
    if self._is_user_included_op(out_tensor.op):
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_USER_INCLUDED))
        if tensor_tracer_flags.TT_CHECK_FILTER.value:
            logging.info('USER_INCLUDED tensor %s', out_tensor.name)
        return False
    if self._is_user_excluded_op(out_tensor.op):
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_USER_EXCLUDED))
        if tensor_tracer_flags.TT_CHECK_FILTER.value:
            logging.info('USER_EXCLUDED tensor %s', out_tensor.name)
        return True
    if not out_tensor.get_shape().is_fully_defined():
        if self._parameters.trace_mode in (tensor_tracer_flags.TRACE_MODE_NAN_INF, tensor_tracer_flags.TRACE_MODE_NORM, tensor_tracer_flags.TRACE_MODE_HISTORY, tensor_tracer_flags.TRACE_MODE_MAX_ABS, tensor_tracer_flags.TRACE_MODE_SUMMARY):
            report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_TENSOR_GET_TRACED))
            return False
        else:
            report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_DYNAMIC_SHAPE))
            return True
    rank = len(out_tensor.shape)
    if rank < 1:
        if self._parameters.trace_scalar_ops:
            if <MASK>:
                report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_UNSAFE_SCALAR))
                return True
            else:
                report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_SCALAR_GET_TRACED))
                return False
        else:
            report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_SKIP_SCALAR))
            return True
    else:
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_TENSOR_GET_TRACED))
        return False

def tuple_to_list(tuple_type: type[tuple]) -> type[list]:
    """
    Convert `tuple_type` into a list type with the same type arguments. Assumes that `tuple_type` is typing.Tuple type.
    """
    type_args = getattr(tuple_type, '__args__', None)
    if <MASK>:
        return list
    elif len(type_args) == 1:
        return list[type_args[0]]
    elif len(type_args) == 2 and type_args[1] is Ellipsis:
        return list[type_args[0]]
    else:
        return list[typing.Union[tuple(type_args)]]

def reset_partition_in_sparse_nn(partition, new_partition=True):
    """If crossing the boundary between non-embedding nodes and
            embedding nodes, create a new partition
            """
    if <MASK>:
        embedding_partitions.append(partition)
    else:
        non_embedding_partitions.append(partition)
    if new_partition:
        partition = self.create_partition()
        partition.left_mem_bytes = available_mem_bytes
        return partition
    return None

@def_function.function
def my_function_with_cond(x):
    if <MASK>:
        return x ** 2.0
    else:
        return x ** 3.0

def _align_for_op(self, right, align_asobject: bool=False):
    """align lhs and rhs Series"""
    left = self
    if isinstance(right, Series):
        if not left.index.equals(right.index):
            if align_asobject:
                if <MASK>:
                    pass
                else:
                    left = left.astype(object)
                    right = right.astype(object)
            (left, right) = left.align(right)
    return (left, right)

def visit_Call(self, node):
    (func_name, func_type) = self.visit(node.func)
    func_type = self._get_inferred_type(node.func, func_type)
    if func_type == TFRTypes.AG_BUILTIN_FUNC:
        if func_name == 'if_stmt':
            (cond, _) = self.visit(node.args[0])
            (body, _) = self.visit(node.args[1])
            (orelse, _) = self.visit(node.args[2])
            (get_state, _) = self.visit(node.args[3])
            nouts = int(node.args[6].value)
            out_symbols = []
            for out in node.args[5].elts[:nouts]:
                (val, ty) = self.symbol_table.lookup(out.value)
                out_symbols.append(out.value)
            return self._visit_if_stmt(cond, body, orelse, get_state, out_symbols, node)
        elif func_name == 'for_stmt':
            range_ = self._visit_iter(node.args[0])
            (body, _) = self.visit(node.args[2])
            (get_state, _) = self.visit(node.args[3])
            loop_carried = [out.value for out in node.args[5].elts]
            return self._visit_for_stmt(range_, body, get_state, loop_carried, node)
        elif func_name == 'Undefined':
            val = self._ssa_name(node.args[0].value)
            return (val, TFRTypes.AG_UNDEFINED_VAL)
        elif func_name == 'UndefinedReturnValue':
            val = self._ssa_name('return_val')
            return (val, TFRTypes.AG_UNDEFINED_VAL)
    if <MASK>:
        return self._visit_tf_op(func_name, node.args, node.keywords, node)
    if func_type == TFRTypes.TFR_BUILTIN_FUNC:
        return self._visit_tfr_builtins(func_name, node.args, node)
    if func_type == types.FunctionType:
        return self._visit_tf_op(func_name, node.args, node.keywords, node)
    if func_type == TFRTypes.TF_TENSOR_SHAPE_FUNC:
        return (func_name, TFRTypes.TF_TENSOR_SHAPE_LIST)
    if func_type == TFRTypes.PY_BUILTIN_FUNC:
        if func_name == 'len':
            (arg, ty) = self.visit(node.args[0])
            ty = self._get_inferred_type(node.args[0], ty)
            if ty == TFRTypes.TF_TENSOR_SHAPE_LIST:
                len_value = self._ssa_name('len')
                self._emit_with_loc('\n{} = shape.rank {} : !shape.shape -> !shape.size'.format(len_value, arg), node)
                size_value = self._ssa_name('len_size')
                self._emit_with_loc('\n{} = shape.size_to_index {} : !shape.size'.format(size_value, len_value), node)
            elif ty == TFRTypes.TENSOR_LIST:
                size_value = self._ssa_name('len')
                self._emit_with_loc('\n{} = tfr.get_length {} -> index'.format(size_value, arg), node)
            return (size_value, TFRTypes.INDEX)
    raise NotImplementedError('call operator not recognized: {} {}'.format(func_name, func_type))

def __init__(self, period_group_size_dict=None, warmup_steps=0, process_group=None):
    super().__init__(process_group)
    if not period_group_size_dict:
        raise ValueError('Arg ``period_group_size_dict`` must not be empty.')
    self._periods = list(period_group_size_dict.keys())
    if self._periods[0] <= 0:
        raise ValueError('The minimum period in arg ``period_group_size_dict`` must be a positive value.')
    elif self._periods[-1] == 1:
        warnings.warn('When the maximum period in arg ``period_group_size_dict`` is 1, no need to use model averaging because the communication cost of all-reducing parameters will be no less than the cost of all-reducing gradients by DistributedDataParallel in the backward pass. Therefore, only DistributedDataParallel should be used for this case.')
    overall_group_size = dist.get_world_size(group=self.process_group)
    if list(period_group_size_dict.values())[-1] != overall_group_size:
        raise ValueError(f'The last value in arg ``period_process_group_dict`` {list(period_group_size_dict.values())[-1]} must be equal to the size of arg ``process_group`` {overall_group_size}.')
    self.period_process_group_dict = OrderedDict()
    logger.info('Model averaging hierarchy:')
    for (period, group_size) in period_group_size_dict.items():
        logger.info('\tEach group that has %s processes average parameters every %s iterations, if no higher-level averaging.', group_size, period)
        if <MASK>:
            (self.period_process_group_dict[period], _) = dist.new_subgroups(group_size=group_size, group=self.process_group)
        else:
            self.period_process_group_dict[period] = self.process_group
    if warmup_steps < 0:
        raise ValueError('Arg ``warmup_steps`` must be a non-negative number.')
    self.warmup_steps = warmup_steps

def contains_collective(snode: BaseSchedulerNode) -> bool:
    from torch._inductor.scheduler import GroupedSchedulerNode
    if <MASK>:
        return any((contains_collective(x) for x in snode.snodes))
    return is_collective(snode.node)

def _sparse_min_or_max(X, axis, min_or_max):
    if axis is None:
        if 0 in X.shape:
            raise ValueError('zero-size array to reduction operation')
        zero = X.dtype.type(0)
        if X.nnz == 0:
            return zero
        m = min_or_max.reduce(X.data.ravel())
        if X.nnz != np.prod(X.shape):
            m = min_or_max(zero, m)
        return m
    if <MASK>:
        axis += 2
    if axis == 0 or axis == 1:
        return _min_or_max_axis(X, axis, min_or_max)
    else:
        raise ValueError('invalid axis, use 0 for rows, or 1 for columns')

def build_graph(parameters):
    """Build a transpose graph given `parameters`."""
    input_tensor = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input', shape=parameters['input_shape'])
    if <MASK>:
        perm = parameters['perm']
        input_tensors = [input_tensor]
    else:
        shape = len(parameters['perm'])
        perm = tf.compat.v1.placeholder(dtype=tf.int32, name='perm', shape=shape)
        input_tensors = [input_tensor, perm]
    out = tf.transpose(a=input_tensor, perm=perm)
    return (input_tensors, [out])

def check_meta_consistency(lhs_list: list[Union[torch.Tensor, torch.SymInt, int]], rhs_list: list[Union[torch.Tensor, torch.SymInt, int]], lhs_name: str, rhs_name: str, include_contiguity: bool=True) -> None:

    def diff_meta_pairs(lhs_list: list[Union[torch.Tensor, torch.SymInt, int]], rhs_list: list[Union[torch.Tensor, torch.SymInt, int]]) -> list[str]:

        def diff_meta(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
            if isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor):
                return ', '.join(diff_tensor_meta(_extract_tensor_metadata(lhs, include_contiguity=include_contiguity), _extract_tensor_metadata(rhs, include_contiguity=include_contiguity), check_grad=False))
            else:

                def _both_int_types(lhs, rhs):
                    return isinstance(lhs, (int, torch.SymInt)) and isinstance(rhs, (int, torch.SymInt))

                def _both_tensor(lhs, rhs):
                    return isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor)
                if <MASK>:
                    return f'type: {lhs} vs {rhs}'
            return ''

        def diff_device(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
            if isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor):
                if rhs.device.type == lhs.device.type and rhs.device.index == lhs.device.index:
                    return ''
                else:
                    return 'device'
            return ''
        if len(lhs_list) != len(rhs_list):
            raise torch._dynamo.exc.UncapturedHigherOrderOpError(f'Expected {lhs_name} and {rhs_name} to have same number of outputs but got lhs:{lhs_list} and rhs:{rhs_list}')
        all_diffs = []
        for (i, (lhs, rhs)) in enumerate(zip(lhs_list, rhs_list)):
            if (diff := diff_meta(lhs, rhs)):
                all_diffs.append(f'pair[{i}] differ in {diff}, where lhs is {lhs} and rhs is {rhs}')
            if (diff := diff_device(lhs, rhs)):
                all_diffs.append(f'pair[{i}] differ in {diff}, where lhs is {lhs} and rhs is {rhs}')
        return all_diffs
    if (all_diffs := diff_meta_pairs(lhs_list, rhs_list)):
        diff_str = '\n'.join(all_diffs)
        raise torch._dynamo.exc.UncapturedHigherOrderOpError(f'Expected {lhs_name} and {rhs_name} to have same metadata but found:\n{diff_str}')

def _summarize_eager(tensor, summarize=None):
    """Returns a summarized string representation of eager `tensor`.

  Args:
    tensor: EagerTensor to summarize
    summarize: Include these many first elements of `array`
  """
    if summarize is None:
        summarize = 3
    elif summarize < 0:
        summarize = array_ops.size(tensor)
    if <MASK>:
        flat = tensor.numpy().reshape((-1,))
        lst = [str(x) for x in flat[:summarize]]
        if len(lst) < flat.size:
            lst.append('...')
    elif gen_math_ops.not_equal(summarize, 0):
        lst = [str(tensor.numpy())]
    else:
        lst = []
    return ', '.join(lst)

def _grid_dim_str(self, grid_per_dim):
    if <MASK>:
        return '[' + ', '.join((self._grid_dim_str(item) for item in grid_per_dim)) + ']'
    else:
        return pexpr(grid_per_dim)

def generate(self, buffer: IndentedBuffer, expr: Union[str, CSEVariable, OpsValue, IndentedBuffer, DeferredLineBase], *, bounds: ValueRanges[Any]=ValueRanges.unknown(), write: bool=True, assignment: bool=True, dtype: Optional[torch.dtype]=None, shape: BlockShapeType=None) -> CSEVariableType:
    if <MASK>:
        expr = expr.value
    assert write or assignment
    if isinstance(expr, CSEVariable):
        expr.bounds = expr.bounds.tighten(bounds)
        expr.use_count += 1
        return cast(CSEVariableType, expr)
    elif isinstance(expr, IndentedBuffer):
        cache_key = expr.getvalue()
    elif isinstance(expr, DeferredLineBase):
        cache_key = expr.line
    else:
        assert isinstance(expr, str)
        cache_key = expr
    var = self.try_get(cache_key)
    if shape is None and (not assignment):
        shape = ()
    if not var:
        var = self.newvar(bounds, dtype, shape)
        self.put(cache_key, var)
        if write:
            if V.kernel.current_node:
                V.kernel.current_node.codegen_originating_info(buffer, only_once=True)
            if isinstance(expr, IndentedBuffer):
                if assignment:
                    buffer.writeline(f'{self.prefix}{var} =')
                buffer.splice(expr)
                buffer.writeline(self.suffix)
            elif isinstance(expr, DeferredLineBase):
                assert assignment
                buffer.writeline(expr._new_line(f'{self.prefix}{var} = {expr.line}{self.suffix}'))
            else:
                if assignment:
                    line = f'{self.prefix}{var} = {expr}{self.suffix}'
                else:
                    line = f'{expr}{self.suffix}'
                buffer.writeline(line)
                if assignment and (config.test_configs.runtime_triton_dtype_assert or config.test_configs.static_cpp_dtype_assert) and (dtype is not None) and (get_current_backend() != 'cpp'):
                    check_dtype(buffer, var, dtype)
    else:
        var.bounds = var.bounds.tighten(bounds)
        var.use_count += 1
    return var

def graph_diagnostic_info():
    mod_canonicalized = torch._C._jit_pass_canonicalize(traced_func.graph)
    torch._C._jit_pass_inline(mod_canonicalized)
    torch._C._jit_pass_erase_shape_information(mod_canonicalized)
    mod_str = str(mod_canonicalized)
    mod_str = re.sub('___torch_mangle_[0-9]+\\.', '', mod_str)
    check_canonicalized = torch._C._jit_pass_canonicalize(check_mod_func.graph)
    torch._C._jit_pass_inline(check_canonicalized)
    torch._C._jit_pass_erase_shape_information(check_canonicalized)
    check_str = str(check_canonicalized)
    check_str = re.sub('___torch_mangle_[0-9]+\\.', '', check_str)
    graph_diff_errors = None
    if mod_str != check_str:
        import difflib
        graph_diff = difflib.ndiff(mod_str.splitlines(True), check_str.splitlines(True))
        graph_diff_errors = 'Graph diff:\n' + indent(''.join(graph_diff)) + '\n'
        for (n_mod, n_check) in zip(mod_canonicalized.nodes(), check_canonicalized.nodes()):
            if <MASK>:
                graph_diff_errors += 'First diverging operator:\n'
                node_diff = difflib.ndiff(str(n_mod).splitlines(True), str(n_check).splitlines(True))
                source_printout = 'Node diff:\n' + indent(''.join(node_diff)) + '\n'
                mod_stack = n_mod.sourceRange()
                if mod_stack:
                    source_printout += 'Trace source location:\n' + indent(mod_stack) + '\n'
                check_stack = n_check.sourceRange()
                if check_stack:
                    source_printout += 'Check source location:\n' + indent(check_stack) + '\n'
                graph_diff_errors += source_printout
                break
    tensor_compare_errors = None
    for (n_mod, n_check) in zip(mod_canonicalized.nodes(), check_canonicalized.nodes()):
        if n_mod.kind() != n_check.kind():
            break
        if n_mod.kind() == 'prim::Constant' and (not (n_mod.mustBeNone() or n_check.mustBeNone())):
            if not n_mod.hasAttribute('value'):
                continue
            if n_mod.kindOf('value') != 't' or n_check.kindOf('value') != 't':
                continue
            mod_tensor_val = n_mod.t('value')
            check_tensor_val = n_check.t('value')
            try:
                torch.testing.assert_close(mod_tensor_val, check_tensor_val, equal_nan=True)
            except (RuntimeError, AssertionError) as e:
                if tensor_compare_errors is None:
                    tensor_compare_errors = ''
                tensor_compare_errors += 'Node:\n' + indent(str(n_mod)) + '\n'
                compare_stack = n_mod.sourceRange()
                if compare_stack:
                    tensor_compare_errors += 'Source Location:\n' + indent(compare_stack) + '\n'
                tensor_compare_errors += 'Comparison exception: ' + indent(str(e))
                break
    return (graph_diff_errors, tensor_compare_errors)

def _get_numeric_verify_tensor_details(self) -> List[str]:
    """Returns all names of all tensors from NumericVerify op."""
    if not self._numeric_verify_tensor_details:
        self._numeric_verify_tensor_details = []
        self._numeric_verify_op_details = {}
        for op_info in self._quant_interpreter._get_ops_details():
            if <MASK>:
                self._numeric_verify_tensor_details.append(self._quant_interpreter._get_tensor_details(op_info['outputs'][0], subgraph_index=0))
                tensor_name = self._numeric_verify_tensor_details[-1]['name']
                self._numeric_verify_op_details[tensor_name] = op_info
    return self._numeric_verify_tensor_details

def _set_drop_idx(self):
    """Compute the drop indices associated with `self.categories_`.

        If `self.drop` is:
        - `None`, No categories have been dropped.
        - `'first'`, All zeros to drop the first category.
        - `'if_binary'`, All zeros if the category is binary and `None`
          otherwise.
        - array-like, The indices of the categories that match the
          categories in `self.drop`. If the dropped category is an infrequent
          category, then the index for the infrequent category is used. This
          means that the entire infrequent category is dropped.

        This methods defines a public `drop_idx_` and a private
        `_drop_idx_after_grouping`.

        - `drop_idx_`: Public facing API that references the drop category in
          `self.categories_`.
        - `_drop_idx_after_grouping`: Used internally to drop categories *after* the
          infrequent categories are grouped together.

        If there are no infrequent categories or drop is `None`, then
        `drop_idx_=_drop_idx_after_grouping`.
        """
    if self.drop is None:
        drop_idx_after_grouping = None
    elif isinstance(self.drop, str):
        if self.drop == 'first':
            drop_idx_after_grouping = np.zeros(len(self.categories_), dtype=object)
        elif self.drop == 'if_binary':
            n_features_out_no_drop = [len(cat) for cat in self.categories_]
            if self._infrequent_enabled:
                for (i, infreq_idx) in enumerate(self._infrequent_indices):
                    if infreq_idx is None:
                        continue
                    n_features_out_no_drop[i] -= infreq_idx.size - 1
            drop_idx_after_grouping = np.array([0 if n_features_out == 2 else None for n_features_out in n_features_out_no_drop], dtype=object)
    else:
        drop_array = np.asarray(self.drop, dtype=object)
        droplen = len(drop_array)
        if droplen != len(self.categories_):
            msg = '`drop` should have length equal to the number of features ({}), got {}'
            raise ValueError(msg.format(len(self.categories_), droplen))
        missing_drops = []
        drop_indices = []
        for (feature_idx, (drop_val, cat_list)) in enumerate(zip(drop_array, self.categories_)):
            if not is_scalar_nan(drop_val):
                drop_idx = np.where(cat_list == drop_val)[0]
                if drop_idx.size:
                    drop_indices.append(self._map_drop_idx_to_infrequent(feature_idx, drop_idx[0]))
                else:
                    missing_drops.append((feature_idx, drop_val))
                continue
            if is_scalar_nan(cat_list[-1]):
                drop_indices.append(self._map_drop_idx_to_infrequent(feature_idx, cat_list.size - 1))
            else:
                missing_drops.append((feature_idx, drop_val))
        if any(missing_drops):
            msg = 'The following categories were supposed to be dropped, but were not found in the training data.\n{}'.format('\n'.join(['Category: {}, Feature: {}'.format(c, v) for (c, v) in missing_drops]))
            raise ValueError(msg)
        drop_idx_after_grouping = np.array(drop_indices, dtype=object)
    self._drop_idx_after_grouping = drop_idx_after_grouping
    if <MASK>:
        self.drop_idx_ = self._drop_idx_after_grouping
    else:
        drop_idx_ = []
        for (feature_idx, drop_idx) in enumerate(drop_idx_after_grouping):
            default_to_infrequent = self._default_to_infrequent_mappings[feature_idx]
            if drop_idx is None or default_to_infrequent is None:
                orig_drop_idx = drop_idx
            else:
                orig_drop_idx = np.flatnonzero(default_to_infrequent == drop_idx)[0]
            drop_idx_.append(orig_drop_idx)
        self.drop_idx_ = np.asarray(drop_idx_, dtype=object)

def z3str(e: z3.ExprRef) -> str:
    assert z3.is_expr(e), f'unsupported expression type: {e}'

    def get_args_str(e: z3.ExprRef) -> list[str]:
        return [z3str(e.arg(i)) for i in range(e.num_args())]
    e = z3.simplify(e)
    if not z3.is_app(e):
        raise ValueError(f"can't print Z3 expression: {e}")
    if z3.is_int_value(e) or z3.is_rational_value(e):
        return e.as_string()
    decl = e.decl()
    kind = decl.kind()
    op = str(decl)
    args = get_args_str(e)
    if kind == z3.Z3_OP_POWER:
        op = 'pow'
    elif kind in (z3.Z3_OP_ADD, z3.Z3_OP_MUL):

        def collect_str_args(e):
            if not (z3.is_app(e) and e.decl().kind() == kind):
                return [z3str(e)]
            else:
                return [x for i in range(e.num_args()) for x in collect_str_args(e.arg(i))]
        args = collect_str_args(e)
    elif <MASK>:
        assert e.num_args() == 1
        arg = e.arg(0)
        assert z3.is_app(arg)
        argkind = arg.decl().kind()
        logic_inverse = {z3.Z3_OP_EQ: '!=', z3.Z3_OP_LE: '>', z3.Z3_OP_GE: '<'}
        if argkind in logic_inverse:
            op = logic_inverse[argkind]
            args = get_args_str(arg)
    elif kind in (z3.Z3_OP_TO_INT, z3.Z3_OP_TO_REAL):
        assert e.num_args() == 1
        argstr = z3str(e.arg(0))
        if argstr.startswith('(/'):
            return '(idiv' + argstr[2:]
        return argstr
    elif kind == z3.Z3_OP_UNINTERPRETED:
        assert e.num_args() == 0
        return str(decl)
    string = op + ' ' + ' '.join(args)
    return f'({string.rstrip()})'

def EnterGradientColocation(self, op: ops.Operation, gradient_uid: Text):
    if op is not None:
        if <MASK>:
            try:
                outside_attr = op.get_attr(_OUTSIDE_COMPILATION_ATTR).decode('ascii')
            except ValueError:
                return
            parts = outside_attr.split('.')
            cluster = parts[0] + '.' + gradient_uid
            self._outside_compilation_v2_context = OutsideCompilationV2Context(cluster)
            self._outside_compilation_v2_context.Enter()
            return
        self._gradient_colocation_stack.append(op)
        if not self._outside_compilation_cluster:
            try:
                outside_attr = op.get_attr(_OUTSIDE_COMPILATION_ATTR).decode('ascii')
                if self._in_gradient_colocation:
                    raise NotImplementedError('Cannot nest gradient colocation operations outside compilation')
                if gradient_uid == '__unsupported__':
                    raise NotImplementedError('No gradient_uid calling gradient within outside_compilation')
                self._in_gradient_colocation = op
                parts = outside_attr.split('.')
                cluster = parts[0] + '.' + gradient_uid
                self._EnterOutsideCompilationScope(cluster=cluster)
            except ValueError:
                pass

def decide_parallel_depth(self, max_parallel_depth, threads):
    assert self.call_ranges is not None
    ranges = self.call_ranges[max_parallel_depth.start_depth:max_parallel_depth.start_depth + max_parallel_depth.parallel_depth]
    seq = self.size_hint()
    par = 1
    depth = 0
    for expr in ranges:
        hint = V.graph.sizevars.size_hint(expr, fallback=8192)
        if <MASK>:
            break
        if seq // threads < config.cpp.min_chunk_size:
            break
        depth += 1
        par *= hint
        seq /= hint
    if config.cpp.dynamic_threads and depth == 0 and (len(ranges) > 0):
        depth = 1
    return ParallelDepth(parallel_depth=depth, start_depth=max_parallel_depth.start_depth)

@combinations.generate(test_base.default_test_combinations())
def testMapAndBatchControlFlow(self):

    def map_fn(x):
        previous_control_flow_v2_value = control_flow_util.ENABLE_CONTROL_FLOW_V2
        control_flow_util.ENABLE_CONTROL_FLOW_V2 = True
        return_value = cond.cond(x < 50, lambda : x + 1, lambda : x * x)
        control_flow_util.ENABLE_CONTROL_FLOW_V2 = previous_control_flow_v2_value
        return return_value
    dataset = dataset_ops.Dataset.range(100).apply(batching.map_and_batch(map_fn, batch_size=10))
    get_next = self.getNext(dataset)
    for i in range(10):
        if <MASK>:
            self.assertAllEqual([i * 10 + j + 1 for j in range(10)], self.evaluate(get_next()))
        else:
            self.assertAllEqual([(i * 10 + j) * (i * 10 + j) for j in range(10)], self.evaluate(get_next()))
    with self.assertRaises(errors.OutOfRangeError):
        self.evaluate(get_next())

def _get_attr_type(type_: type) -> ir.AttributeType:
    """Obtain the type of the attribute from a Python class."""
    try:
        if type_ in _PY_TYPE_TO_ATTR_TYPE:
            return _PY_TYPE_TO_ATTR_TYPE[type_]
        origin_type = typing.get_origin(type_)
        if origin_type is None:
            return ir.AttributeType.UNDEFINED
        if <MASK>:
            inner_type = typing.get_args(type_)[0]
            if inner_type in _LIST_TYPE_TO_ATTR_TYPE:
                return _LIST_TYPE_TO_ATTR_TYPE[inner_type]
    except TypeError:
        logger.warning('TypeError when checking %s.', type_, exc_info=True)
    return ir.AttributeType.UNDEFINED

def _buildParams(self, data, dtype):
    data = data.astype(dtype.as_numpy_dtype)
    if <MASK>:
        return data + 10j * data
    return data

@staticmethod
def _parse_variants(block: str, language: Language) -> tuple[dict[str, list[str]], str, str]:
    block = textwrap.dedent(block).strip()
    comment = '#' if language == Language.PYTHON else '//'
    label_pattern = f'{comment} @(.+)$'
    label = ''
    lines_by_label: dict[str, list[str]] = {'SETUP': [], 'GLOBAL_SETUP': []}
    for line in block.splitlines(keepends=False):
        match = re.search(label_pattern, line.strip())
        if <MASK>:
            label = match.groups()[0]
            if label.replace(' ', '_').upper() in ('SETUP', 'GLOBAL_SETUP'):
                label = label.replace(' ', '_').upper()
            continue
        lines_by_label.setdefault(label, [])
        if line.startswith(comment):
            line = ''
        lines_by_label[label].append(line)
    setup = '\n'.join(lines_by_label.pop('SETUP'))
    global_setup = '\n'.join(lines_by_label.pop('GLOBAL_SETUP'))
    return (lines_by_label, setup, global_setup)

def __getstate__(self):
    """Hook to allow choosing the attributes to pickle."""
    state = self.__dict__.copy()
    state['_state'] = copy.copy(state['_state'])
    state['_state'].fields_cache = state['_state'].fields_cache.copy()
    _memoryview_attrs = []
    for (attr, value) in state.items():
        if <MASK>:
            _memoryview_attrs.append((attr, bytes(value)))
    if _memoryview_attrs:
        state['_memoryview_attrs'] = _memoryview_attrs
        for (attr, value) in _memoryview_attrs:
            state.pop(attr)
    return state

def sample_inputs_full_like(self, device, dtype, requires_grad, **kwargs):

    def get_val(dtype):
        return make_tensor([], dtype=dtype, device='cpu').item()
    double_dtype = torch.double if device != 'mps:0' else torch.float
    inputs = [((), get_val(dtype), {}), ((S, S), get_val(dtype), {}), ((0, S, 0), get_val(dtype), {}), ((S,), get_val(dtype), {'dtype': dtype, 'device': device}), ((S,), get_val(double_dtype), {'dtype': double_dtype}), ((S,), get_val(dtype), {'device': 'cpu'}), ((S,), get_val(double_dtype), {'dtype': double_dtype, 'device': 'cpu'})]
    if <MASK>:
        inputs.append(((S,), get_val(dtype), {'device': 'cuda'}))
    if torch.mps.is_available() and dtype not in [torch.float64, torch.complex128, torch.uint32, torch.uint16]:
        inputs.append(((S,), get_val(dtype), {'device': 'mps'}))
    if not dtype.is_signed:
        inputs.append(((S,), -get_val(dtype), {}))
    for (shape, fill_value, kwargs) in inputs:
        t = make_tensor(shape, dtype=dtype, device=device, low=None, high=None, requires_grad=requires_grad)
        yield SampleInput(t, fill_value, **kwargs)

@classmethod
def collect(cls) -> tuple[TritonBundle, Optional[TritonBundlerMetadata]]:
    """
        This is the main function called when a cache write happens. This function
        converts all the previously remembered kernels into bundled format so that
        it can be written into a cache entry.
        This function also finalizes the current bundle.
        """
    from torch._inductor import config
    if not TritonBundler.is_enabled():
        cls.end_compile()
        set_feature_use('triton_bundling', False)
        return (TritonBundle([], []), None)
    set_feature_use('triton_bundling', True)
    with dynamo_timed(key='TritonBundler.collect', log_pt2_compile_event=True):
        entries = cls._entries
        if <MASK>:
            result: list[TritonKernelArtifacts] = []
            kernel_names: list[str] = []
            for entry in entries:
                artifacts: list[TritonKernelArtifact] = []
                path = os.path.join(entry.directory, entry.kernel_hash)
                if not os.path.exists(path):
                    continue
                for filename in os.listdir(path):
                    filepath = os.path.join(path, filename)
                    try:
                        assert os.path.isfile(filepath)
                        with open(filepath, 'rb') as file:
                            payload = file.read()
                            if filepath.endswith('.json'):
                                if TritonBundler._REPLACE_BYTES in payload:
                                    log.warning('Bundle contains illegal %s, payload: %s', TritonBundler._REPLACE_BYTES, payload)
                                    raise AssertionError('Bundle contains illegal bytes')
                                payload = payload.replace(str.encode(path), TritonBundler._REPLACE_BYTES)
                            artifacts.append(TritonKernelArtifact(filename, payload))
                        counters['inductor']['triton_bundler_save_kernel'] += 1
                    except Exception:
                        log.debug('failed to collect triton kernel', exc_info=True)
                    extension = os.path.splitext(filename)[1]
                    if extension in GPU_KERNEL_BIN_EXTS.values():
                        kernel_names.append(Path(filename).stem)
                if artifacts:
                    result.append(TritonKernelArtifacts(entry.kernel_hash, entry.device, artifacts))
            if config.use_static_cuda_launcher:
                (static_autotuners, static_kernel_names) = cls.collect_static_autotuners()
            else:
                static_autotuners = []
                static_kernel_names = []
            cls.end_compile()
            return (TritonBundle(result, static_autotuners), TritonBundlerMetadata(kernel_names, static_kernel_names))
        return (TritonBundle([], []), None)

def matmul(a, b, transpose_a=False, transpose_b=False, adjoint_a=False, adjoint_b=False, name=None):
    """Perform a sparse matrix matmul between `a` and `b`.

  Performs a contraction between `a` and `b` along the two innermost dimensions.
  If both `a` and `b` are instances of `SparseMatrix`, returns a new instance
  of `SparseMatrix` (same type as `a`).  If one is not an instance of
  `SparseMatrix`, returns a dense `Tensor`:

  ```
  c = opA(a) . opB(b)
  ```
  where `opA` (resp. `opB`) is the transpose or hermitian transpose depending
  on the values of `transpose_a` (resp. `transpose_b`) and `adjoint_a`
  (resp. `adjoint_b`).

  Args:
    a: `Tensor` or `SparseMatrix`, having rank `2` or `3`.
    b: `Tensor` or `SparseMatrix`, having rank `2` or `3`.
    transpose_a: Python `bool`.
    transpose_b: Python `bool`.
    adjoint_a: Python `bool`.
    adjoint_b: Python `bool`.
    name: Optional name to use when creating ops.

  Returns:
    A `SparseMatrix` if both `a` and `b` are instances of `SparseMatrix`,
    otherwise a dense `Tensor`.
  """
    if not isinstance(a, SparseMatrix) and (not isinstance(b, SparseMatrix)):
        return math_ops.matmul(a, b, transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b, name=name)
    a_matrix = a._matrix if isinstance(a, SparseMatrix) else a
    b_matrix = b._matrix if isinstance(b, SparseMatrix) else b
    with ops.name_scope(name, 'SparseMatrixMatMul', [a_matrix, b_matrix]):
        if <MASK>:
            if not (isinstance(a, type(b)) or isinstance(b, type(a))):
                raise TypeError("SparseMatrix types don't inherit from each other: %s and %s" % (type(a), type(b)))
            c = sm_ops.sparse_matrix_sparse_mat_mul(a_matrix, b_matrix, transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b, type=a.dtype)
            c_handle = matmul_shape_inference(a_matrix, b_matrix, c, transpose_a, transpose_b, adjoint_a, adjoint_b)
            return a._from_matrix(c, handle_data=c_handle)
        elif isinstance(a, SparseMatrix):
            return sm_ops.sparse_matrix_mat_mul(a_matrix, b, transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b)
        elif not adjoint_a and (not adjoint_b):
            return sm_ops.sparse_matrix_mat_mul(b_matrix, a, transpose_a=not transpose_b, transpose_b=not transpose_a, transpose_output=True)
        elif not transpose_a and (not transpose_b):
            return sm_ops.sparse_matrix_mat_mul(b_matrix, a, adjoint_a=not adjoint_b, adjoint_b=not adjoint_a, transpose_output=True, conjugate_output=True)
        else:
            return sm_ops.sparse_matrix_mat_mul(b_matrix, math_ops.conj(a), transpose_output=True, conjugate_output=adjoint_b)

