def _einsum_v1_parse_and_resolve_equation(equation, input_shapes):
    """Helper for einsum() that splits/resolves inputs & outputs.

  Args:
    equation: Equation string given as argument to einsum().
    input_shapes: List of the shapes of all inputs given to einsum()

  Returns:
    input_axis_labels, output_axis_labels where:
      input_axis_labels: List of length len(input_shapes) of strings
      representing the character label for each dimension of each given input,
      resolving any broadcast (...) axes,
    output_axis_labels: A string of character labels for each axes of output
      tensor, filling in missing output subscripts and broadcast axes.

  Raises:
    ValueError: If equation is in the incorrect format, incorrect number of
      inputs given or broadcast axes "..." or output axes could not be resolved.
  """
    equation = equation.replace(' ', '')
    match = re.match('^([a-zA-Z,.]+)(->[a-zA-Z.]*)?$', equation)
    if not match:
        raise ValueError(f'Indices have incorrect format. Received: {equation}.')
    input_axis_labels = match.group(1).split(',')
    output_axis_labels = match.group(2)[2:] if match.group(2) else None
    if len(input_shapes) != len(input_axis_labels):
        raise ValueError(f'Got {len(input_shapes)} arguments for equation "{equation}", expecting {len(input_axis_labels)}.')
    ellipsis_axes = ''
    if <MASK>:
        unused = ''.join((c for c in string.ascii_letters if c not in ''.join(input_axis_labels)))
        for (i, ax) in enumerate(input_axis_labels):
            if '...' in ax:
                parts = ax.split('...')
                if len(parts) != 2:
                    raise ValueError(f'Unable to resolve ellipsis. Excess number found: {len(parts) - 1} vs 1.')
                if input_shapes[i].ndims is None:
                    raise ValueError('Unable to statically infer ellipsis axes. The input shapes has a dynamic dimensionality.')
                n = input_shapes[i].ndims - len(''.join(parts))
                if n < 0:
                    raise ValueError('Ellipses lengths do not match.')
                if len(unused) < n:
                    raise ValueError('Unable to resolve ellipsis, too many distinct labels.')
                replace_axes = unused[-n:] if n > 0 else ''
                input_axis_labels[i] = input_axis_labels[i].replace('...', replace_axes)
                if len(replace_axes) > len(ellipsis_axes):
                    ellipsis_axes = replace_axes
        if any(('.' in ax for ax in input_axis_labels)):
            raise ValueError(f'Period "." found outside of ellipsis in input {input_axis_labels}.')
        if output_axis_labels is not None:
            output_axis_labels = output_axis_labels.replace('...', ellipsis_axes)
            if '.' in output_axis_labels:
                raise ValueError(f'Period "." found outside of ellipsis in output {output_axis_labels}.')
    if output_axis_labels is None:
        axis_labels = set(''.join(input_axis_labels)) - set(ellipsis_axes)
        indices = ''.join(sorted(axis_labels))
        counts = {ax: 0 for ax in indices}
        for axes_ in input_axis_labels:
            for ax in axes_:
                if ax not in ellipsis_axes:
                    counts[ax] += 1
        output_axis_labels = ellipsis_axes + ''.join(sorted((ax for ax in axis_labels if counts[ax] == 1)))
    return (input_axis_labels, output_axis_labels)

def as_sql(self, compiler, connection, function=None, template=None):
    clone = self.copy()
    clone.set_source_expressions([Coalesce(expression if isinstance(expression.output_field, (CharField, TextField)) else Cast(expression, TextField()), Value('')) for expression in clone.get_source_expressions()])
    config_sql = None
    config_params = []
    if template is None:
        if <MASK>:
            (config_sql, config_params) = compiler.compile(clone.config)
            template = '%(function)s(%(config)s, %(expressions)s)'
        else:
            template = clone.template
    (sql, params) = super(SearchVector, clone).as_sql(compiler, connection, function=function, template=template, config=config_sql)
    extra_params = []
    if clone.weight:
        (weight_sql, extra_params) = compiler.compile(clone.weight)
        sql = 'setweight({}, {})'.format(sql, weight_sql)
    return (sql, (*config_params, *params, *extra_params))

def finalize_outputs(self):
    self.created_modules.pop(self.fqn, None)
    orig_outputs = []
    signature = self.module_call_graph.get(self.child_fqn)
    if signature is not None and self.parent is not None:
        for output in signature.outputs:
            if isinstance(output, (TensorArgument, SymIntArgument, SymBoolArgument, SymFloatArgument, ConstantArgument)):
                if output.name in self.seen_nodes:
                    orig_outputs.append(self.seen_nodes[output.name])
                else:
                    orig_outputs.append(None)
            else:
                raise RuntimeError(f'Unsupported data type for output node: {output}')

        def get_actual_output_node(output):
            if output is None:
                return None
            seen_node = self.seen_nodes[output.name]
            if seen_node in self.node_map:
                return self.node_map[seen_node]
            elif seen_node in self.node_to_placeholder:
                return self.node_to_placeholder[seen_node]
            else:
                raise RuntimeError(f'Could not find output node {output}. Graph: {self.graph}')
        tree_out_node = _generate_unflatten(self.module, tuple((get_actual_output_node(output) for output in orig_outputs)), signature.out_spec)
        parent_out: Optional[torch.fx.Node] = _generate_flatten_spec(self.parent.module, self.parent_call_module, signature.out_spec)
        graph_outputs: Union[torch.fx.Node, list[torch.fx.Node]] = tree_out_node
    else:
        graph_outputs = []
        for orig_node in self.node_map.keys():
            for user_node in orig_node.users:
                if user_node.name not in self.seen_nodes:
                    orig_outputs.append(orig_node)
                    graph_outputs.append(self.node_map[orig_node])
                    break
        parent_out = self.parent_call_module
        if <MASK>:
            graph_outputs = graph_outputs[0]
    assert isinstance(graph_outputs, (list, torch.fx.Node))
    self.graph.output(graph_outputs)
    if parent_out is None:
        return
    parent_out.meta['val'] = graph_outputs.meta.get('val') if isinstance(graph_outputs, torch.fx.Node) else [o.meta.get('val') for o in graph_outputs]
    if len(orig_outputs) == 1 and signature is None:
        self.parent.node_map[orig_outputs[0]] = parent_out
    else:
        for (i, orig_output) in enumerate(orig_outputs):
            if orig_output is None:
                continue
            proxy_out = torch.fx.Proxy(parent_out)[i].node
            proxy_out.meta['val'] = orig_output.meta.get('val')
            self.parent.node_map[orig_output] = proxy_out

def _root_pre_forward(self, module: nn.Module, args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[tuple[Any, ...], dict[str, Any]]:
    self._lazy_init()
    if self._state_ctx.iter_forward_root is not None:
        return (args, kwargs)
    if <MASK>:
        logger.debug('FSDP::root_pre_forward')
    self._state_ctx.iter_forward_root = self
    with torch.profiler.record_function('FSDP::root_pre_forward'):
        if (event := self._state_ctx.post_optim_event) is not None:
            self._comm_ctx.all_gather_copy_in_stream.wait_event(event)
            self._comm_ctx.all_gather_stream.wait_event(event)
            self._state_ctx.post_optim_event = None
        else:
            current_stream = self._device_handle.current_stream()
            self._comm_ctx.all_gather_copy_in_stream.wait_stream(current_stream)
            self._comm_ctx.all_gather_stream.wait_stream(current_stream)
        if self._device.type in ['cuda', 'hpu', 'xpu', 'mtia', torch._C._get_privateuse1_backend_name()]:
            with torch.profiler.record_function('FSDP::inputs_to_device'):
                (args_tuple, kwargs_tuple) = _to_kwargs(args, kwargs, self._device, False)
            (args, kwargs) = (args_tuple[0], kwargs_tuple[0])
    return (args, kwargs)

def _log_signature_report(signature_def_map, excluded_signatures):
    """Log a report of which signatures were produced."""
    sig_names_by_method_name = collections.defaultdict(list)
    for method_name in _FRIENDLY_METHOD_NAMES:
        sig_names_by_method_name[method_name] = []
    for (signature_name, sig) in signature_def_map.items():
        sig_names_by_method_name[sig.method_name].append(signature_name)
    for (method_name, sig_names) in sig_names_by_method_name.items():
        if method_name in _FRIENDLY_METHOD_NAMES:
            method_name = _FRIENDLY_METHOD_NAMES[method_name]
        logging.info('Signatures INCLUDED in export for {}: {}'.format(method_name, sig_names if sig_names else 'None'))
    if excluded_signatures:
        logging.info('Signatures EXCLUDED from export because they cannot be be served via TensorFlow Serving APIs:')
        for (signature_name, message) in excluded_signatures.items():
            logging.info("'{}' : {}".format(signature_name, message))
    if <MASK>:
        logging.warning('Export includes no signatures!')
    elif signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY not in signature_def_map:
        logging.warning('Export includes no default signature!')

def finalize_outputs(self):
    self.created_modules.pop(self.fqn, None)
    orig_outputs = []
    signature = self.module_call_graph.get(self.child_fqn)
    if signature is not None and self.parent is not None:
        for output in signature.outputs:
            if isinstance(output, (TensorArgument, SymIntArgument, SymBoolArgument, SymFloatArgument, ConstantArgument)):
                if output.name in self.seen_nodes:
                    orig_outputs.append(self.seen_nodes[output.name])
                else:
                    orig_outputs.append(None)
            else:
                raise RuntimeError(f'Unsupported data type for output node: {output}')

        def get_actual_output_node(output):
            if <MASK>:
                return None
            seen_node = self.seen_nodes[output.name]
            if seen_node in self.node_map:
                return self.node_map[seen_node]
            elif seen_node in self.node_to_placeholder:
                return self.node_to_placeholder[seen_node]
            else:
                raise RuntimeError(f'Could not find output node {output}. Graph: {self.graph}')
        tree_out_node = _generate_unflatten(self.module, tuple((get_actual_output_node(output) for output in orig_outputs)), signature.out_spec)
        parent_out: Optional[torch.fx.Node] = _generate_flatten_spec(self.parent.module, self.parent_call_module, signature.out_spec)
        graph_outputs: Union[torch.fx.Node, list[torch.fx.Node]] = tree_out_node
    else:
        graph_outputs = []
        for orig_node in self.node_map.keys():
            for user_node in orig_node.users:
                if user_node.name not in self.seen_nodes:
                    orig_outputs.append(orig_node)
                    graph_outputs.append(self.node_map[orig_node])
                    break
        parent_out = self.parent_call_module
        if len(graph_outputs) == 1:
            graph_outputs = graph_outputs[0]
    assert isinstance(graph_outputs, (list, torch.fx.Node))
    self.graph.output(graph_outputs)
    if parent_out is None:
        return
    parent_out.meta['val'] = graph_outputs.meta.get('val') if isinstance(graph_outputs, torch.fx.Node) else [o.meta.get('val') for o in graph_outputs]
    if len(orig_outputs) == 1 and signature is None:
        self.parent.node_map[orig_outputs[0]] = parent_out
    else:
        for (i, orig_output) in enumerate(orig_outputs):
            if orig_output is None:
                continue
            proxy_out = torch.fx.Proxy(parent_out)[i].node
            proxy_out.meta['val'] = orig_output.meta.get('val')
            self.parent.node_map[orig_output] = proxy_out

def _extract_index(data) -> Index:
    """
    Try to infer an Index from the passed data, raise ValueError on failure.
    """
    index: Index
    if len(data) == 0:
        return default_index(0)
    raw_lengths = set()
    indexes: list[list[Hashable] | Index] = []
    have_raw_arrays = False
    have_series = False
    have_dicts = False
    for val in data:
        if isinstance(val, ABCSeries):
            have_series = True
            indexes.append(val.index)
        elif <MASK>:
            have_dicts = True
            indexes.append(list(val.keys()))
        elif is_list_like(val) and getattr(val, 'ndim', 1) == 1:
            have_raw_arrays = True
            raw_lengths.add(len(val))
        elif isinstance(val, np.ndarray) and val.ndim > 1:
            raise ValueError('Per-column arrays must each be 1-dimensional')
    if not indexes and (not raw_lengths):
        raise ValueError('If using all scalar values, you must pass an index')
    if have_series:
        index = union_indexes(indexes)
    elif have_dicts:
        index = union_indexes(indexes, sort=False)
    if have_raw_arrays:
        if len(raw_lengths) > 1:
            raise ValueError('All arrays must be of the same length')
        if have_dicts:
            raise ValueError('Mixing dicts with non-Series may lead to ambiguous ordering.')
        raw_length = raw_lengths.pop()
        if have_series:
            if raw_length != len(index):
                msg = f'array length {raw_length} does not match index length {len(index)}'
                raise ValueError(msg)
        else:
            index = default_index(raw_length)
    return ensure_index(index)

