def compile_fn(self, gm: fx.GraphModule, example_inputs: list[torch.Tensor]) -> CompiledFn:
    """
        Implements graph splitting, first determining a set of of buckets by counting
        parameter sizes in reverse graph order, then invoking the user/backend compiler
        to compile each subgraph. Finally, stiches compiled graphs into one graphmodule
        and returns its callable.
        """
    buckets = [Bucket()]
    processed_modules: set[torch.nn.Module] = set()
    for node in reversed(gm.graph.nodes):
        if node.op in ('output', 'placeholder'):
            continue
        if buckets[0].size >= self.bucket_bytes_cap or (len(buckets) == 1 and buckets[0].size >= self.first_bucket_cap):
            if bucket_has_external_output(buckets[0]):
                buckets.insert(0, Bucket())
            else:
                if buckets[0].opcount_increased_to_capture_external_output == 0:
                    buckets[0].paramsize_before_opcount_increase = buckets[0].size
                buckets[0].opcount_increased_to_capture_external_output += 1
        if node.op == 'call_function':
            self.add_param_args(buckets[0], node)
        elif node.op == 'call_module':
            target_mod = gm.get_submodule(node.target)
            if target_mod not in processed_modules:
                self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
        elif node.op == 'call_method':
            if isinstance(node.args[0].target, str):
                target_mod = None
                try:
                    target_mod = gm.get_submodule(node.args[0].target)
                except AttributeError:
                    pass
                if target_mod is not None and target_mod not in processed_modules:
                    self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
                self.add_param_args(buckets[0], node)
        elif node.op == 'get_attr':
            maybe_param = getattr(gm, node.target)
            if isinstance(maybe_param, torch.nn.Parameter) and maybe_param.requires_grad and (not self._ignore_parameter(maybe_param)):
                self.add_param(buckets[0], maybe_param, node.target)
        buckets[0].nodes.append(node)
    if <MASK>:
        buckets[1].nodes.extend(buckets[0].nodes)
        assert len(buckets[0].params) == 0, 'Params should be empty if size is 0'
        del buckets[0]
    self.buckets = buckets
    pretty_print_buckets(buckets, self.bucket_bytes_cap)
    if len(buckets) == 1:
        return self.backend_compile_fn(gm, example_inputs)
    partition_map = {}
    for (idx, b) in enumerate(buckets):
        for node in b.nodes:
            partition_map[node] = idx
    split_gm = fx.passes.split_module.split_module(gm, None, lambda node: partition_map[node])
    propagate_dynamo_source(gm, split_gm)
    propagate_metadata(gm, split_gm)
    debug_str = f'\n---orig graph---\n{gm.graph}\n' + f'\n---split graph---\n{split_gm.graph}\n'
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            debug_str += f'\n---{name} graph---\n{module.graph}\n'
    debug_str += '\n---------------\n'
    ddp_graph_log.debug(debug_str)
    trace_structured('optimize_ddp_split_graph', payload_fn=lambda : split_gm.print_readable(print_output=False))
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            trace_structured('optimize_ddp_split_child', lambda : {'name': name}, payload_fn=lambda : module.print_readable(print_output=False))
    fake_mode = detect_fake_mode(example_inputs)
    if fake_mode is None:
        fake_mode = torch._subclasses.fake_tensor.FakeTensorMode()
    submod_compiler = SubmodCompiler(split_gm, self.backend_compile_fn, fake_mode)
    with torch._dynamo.utils._disable_saved_tensors_hooks_during_tracing():
        submod_compiler.run(*example_inputs)
    split_gm.recompile()
    ddp_graph_log.debug('\n---final graph---\n%s\n---------------\n', split_gm.graph)
    return split_gm

@final
def _getitem_lowerdim(self, tup: tuple):
    if self.axis is not None:
        axis = self.obj._get_axis_number(self.axis)
        return self._getitem_axis(tup, axis=axis)
    if self._is_nested_tuple_indexer(tup):
        return self._getitem_nested_tuple(tup)
    ax0 = self.obj._get_axis(0)
    if <MASK>:
        with suppress(IndexingError):
            return cast(_LocIndexer, self)._handle_lowerdim_multi_index_axis0(tup)
    tup = self._validate_key_length(tup)
    for (i, key) in zip(range(len(tup) - 1, -1, -1), reversed(tup), strict=True):
        if is_label_like(key) or is_list_like(key):
            section = self._getitem_axis(key, axis=i)
            if section.ndim == self.ndim:
                new_key = tup[:i] + (_NS,) + tup[i + 1:]
            else:
                new_key = tup[:i] + tup[i + 1:]
                if len(new_key) == 1:
                    new_key = new_key[0]
            if com.is_null_slice(new_key):
                return section
            return getattr(section, self.name)[new_key]
    raise IndexingError('not applicable')

def get_decimalfield_converter(self, expression):
    create_decimal = decimal.Context(prec=15).create_decimal_from_float
    if isinstance(expression, Col):
        quantize_value = decimal.Decimal(1).scaleb(-expression.output_field.decimal_places)

        def converter(value, expression, connection):
            if <MASK>:
                return create_decimal(value).quantize(quantize_value, context=expression.output_field.context)
    else:

        def converter(value, expression, connection):
            if value is not None:
                return create_decimal(value)
    return converter

@classmethod
def from_operator(cls, operator):
    """Builds a `_LinearOperatorSpec` from a `LinearOperator` instance.

    Args:
      operator: An instance of `LinearOperator`.

    Returns:
      linear_operator_spec: An instance of `_LinearOperatorSpec` to be used as
        the `TypeSpec` of `operator`.
    """
    validation_fields = ('is_non_singular', 'is_self_adjoint', 'is_positive_definite', 'is_square')
    kwargs = _extract_attrs(operator, keys=set(operator._composite_tensor_fields + validation_fields))
    non_tensor_params = {}
    param_specs = {}
    for (k, v) in list(kwargs.items()):
        type_spec_or_v = _extract_type_spec_recursively(v)
        is_tensor = [isinstance(x, type_spec.TypeSpec) for x in nest.flatten(type_spec_or_v)]
        if <MASK>:
            param_specs[k] = type_spec_or_v
        elif not any(is_tensor):
            non_tensor_params[k] = v
        else:
            raise NotImplementedError(f'Field {k} contains a mix of `Tensor` and  non-`Tensor` values.')
    return cls(param_specs=param_specs, non_tensor_params=non_tensor_params, prefer_static_fields=operator._composite_tensor_prefer_static_fields)

def test_signature_loading(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')

    class Exported(autotrackable.AutoTrackable):

        def __init__(self):
            self.v = variables.Variable(3.0)

        @def_function.function
        def do(self, x):
            return self.v * x
    exported = Exported()
    imported = cycle(exported, cycles, signatures=exported.do.get_concrete_function(tensor_spec.TensorSpec(None, dtypes.float32)), use_cpp_bindings=use_cpp_bindings)
    self.assertEqual(['serving_default'], list(imported.signatures.keys()))
    imported_function = imported.signatures['serving_default']
    two = constant_op.constant(2.0)
    self.assertEqual(6.0, imported_function(x=two)['output_0'].numpy())
    imported.v.assign(4.0)
    self.assertEqual(8.0, imported_function(x=two)['output_0'].numpy())
    self.assertEqual(8.0, imported_function(two)['output_0'].numpy())
    with self.assertRaises(TypeError):
        imported.signatures['random_key'] = 3

def _reindex_axis(obj: DataFrame, axis: AxisInt, labels: Index, other=None) -> DataFrame:
    ax = obj._get_axis(axis)
    labels = ensure_index(labels)
    if <MASK>:
        other = ensure_index(other)
    if (other is None or labels.equals(other)) and labels.equals(ax):
        return obj
    labels = ensure_index(labels.unique())
    if other is not None:
        labels = ensure_index(other.unique()).intersection(labels, sort=False)
    if not labels.equals(ax):
        slicer: list[slice | Index] = [slice(None, None)] * obj.ndim
        slicer[axis] = labels
        obj = obj.loc[tuple(slicer)]
    return obj

def _makenames_list(adict, align):
    allfields = []
    for (fname, obj) in adict.items():
        n = len(obj)
        if not isinstance(obj, tuple) or n not in (2, 3):
            raise ValueError('entry not a 2- or 3- tuple')
        if n > 2 and obj[2] == fname:
            continue
        num = int(obj[1])
        if num < 0:
            raise ValueError('invalid offset.')
        format = dtype(obj[0], align=align)
        if <MASK>:
            title = obj[2]
        else:
            title = None
        allfields.append((fname, format, num, title))
    allfields.sort(key=lambda x: x[2])
    names = [x[0] for x in allfields]
    formats = [x[1] for x in allfields]
    offsets = [x[2] for x in allfields]
    titles = [x[3] for x in allfields]
    return (names, formats, offsets, titles)

@classmethod
def _from_sequence(cls, scalars, *, dtype: Dtype | None=None, copy: bool=False) -> Self:
    if dtype and (not (isinstance(dtype, str) and dtype == 'string')):
        dtype = pandas_dtype(dtype)
        assert isinstance(dtype, StringDtype) and dtype.storage == 'python'
    elif using_string_dtype():
        dtype = StringDtype(storage='python', na_value=np.nan)
    else:
        dtype = StringDtype(storage='python')
    from pandas.core.arrays.masked import BaseMaskedArray
    na_value = dtype.na_value
    if isinstance(scalars, BaseMaskedArray):
        na_values = scalars._mask
        result = scalars._data
        result = lib.ensure_string_array(result, copy=copy, convert_na_value=False)
        result[na_values] = na_value
    else:
        if <MASK>:
            scalars = np.array(scalars)
        result = lib.ensure_string_array(scalars, na_value=na_value, copy=copy)
    new_string_array = cls.__new__(cls)
    NDArrayBacked.__init__(new_string_array, result, dtype)
    return new_string_array

def cpp_dispatch_exprs(f: NativeFunction, *, python_signature: PythonSignature | None=None) -> tuple[str, ...]:
    cpp_args: Sequence[Binding] = _cpp_signature(f, method=False).arguments()
    exprs: tuple[str, ...] = ()
    if not isinstance(python_signature, PythonSignatureDeprecated):
        exprs = tuple((a.name for a in cpp_args))
    else:
        exprs = tuple(filter(lambda n: n != 'out' or f.func.is_out_fn(), python_signature.deprecated_args_exprs))
    if <MASK>:
        exprs = tuple(filter('self'.__ne__, exprs))
    return exprs

