def np_expm(x):
    """Slow but accurate Taylor series matrix exponential."""
    y = np.zeros(x.shape, dtype=x.dtype)
    xn = np.eye(x.shape[0], dtype=x.dtype)
    for n in range(40):
        if <MASK>:
            xn /= float(n)
        y += xn
        xn = np.dot(xn, x)
    return y

def _validate_reduction_axis(x, axis):
    size = x.get_size()
    if isinstance(axis, int):
        axis = [axis]
    elif not axis:
        axis = range(len(size))
    if <MASK>:
        assert tuple(axis) in [(), (0,), (-1,)], f'invalid axis: {axis}'
        return []
    axis = list(axis)
    for i in range(len(axis)):
        if axis[i] < 0:
            axis[i] += len(size) if len(size) else 1
        assert 0 <= axis[i] < len(size) or (len(size) == 0 and axis[i] == 0)
    assert len(OrderedSet(axis)) == len(axis), 'reduction axis not unique'
    return axis

@test_util.run_gpu_only
@test_util.disable_xla('Wants RunMetadata')
def testParallelExecution(self):
    """Verify disjoint branches across while iterations are run in parallel."""
    self.skipTest('b/210666081: Flaky')
    if control_flow_v2_toggles.control_flow_v2_enabled():
        self.skipTest('b/138870290')
    with ops.Graph().as_default() as g:
        nbranches = 7
        matrices = array_ops_stack.unstack(array_ops.matrix_diag(random_ops.random_uniform([nbranches, 8, 512]) + 0.001))

        def make_branch(i, mat, name):

            def branch_fn():
                next_i = i + 1
                with ops.device('gpu:0'):
                    return (next_i, math_ops.reduce_sum(linalg_ops.cholesky(mat, name=name + '_Cholesky')))
            return branch_fn

        def make_branches(i):
            return [make_branch(i, matrices[bi], 'br{}'.format(bi)) for bi in range(nbranches)]

        def cond(i, _):
            return i < nbranches

        def body(i, result):
            with ops.device('cpu:0'):
                (next_i, branch_out) = control_flow_switch_case.switch_case(i, make_branches(i))
            return (next_i, result + branch_out)
        (_, result) = while_loop.while_loop(cond, body, [0, 0.0])
        run_metadata = config_pb2.RunMetadata()
        run_options = config_pb2.RunOptions(trace_level=config_pb2.RunOptions.FULL_TRACE)
        config = config_pb2.ConfigProto(allow_soft_placement=False, log_device_placement=True)
        with session.Session(config=config, graph=g) as sess:
            _ = sess.run(result, options=run_options, run_metadata=run_metadata)
    chol_node_stats = []
    for dev_stats in run_metadata.step_stats.dev_stats:
        for node_stats in dev_stats.node_stats:
            if node_stats.node_name.endswith('Cholesky') and node_stats.all_start_nanos > 0:
                chol_node_stats.append(node_stats)
    self.assertLen(chol_node_stats, nbranches)
    chol_node_stats = sorted(chol_node_stats, key=lambda stats: stats.node_name)
    op_start_nanos = [stats.all_start_nanos for stats in chol_node_stats]
    op_end_nanos = [stats.all_start_nanos + stats.op_end_rel_nanos for stats in chol_node_stats]

    def overlap(range1, range2):
        (s1, e1) = range1
        (s2, e2) = range2
        if <MASK>:
            return 0 if s2 > e1 else e1 - s2
        return 0 if s1 > e2 else e2 - s1
    timespans = list(zip(op_start_nanos, op_end_nanos))
    overlaps_chol0 = [overlap(timespans[0], r2) for r2 in timespans[1:]]
    self.assertGreater(np.count_nonzero(overlaps_chol0), 0)

def parallel_walk(node, other):
    """Walks two ASTs in parallel.

  The two trees must have identical structure.

  Args:
    node: Union[ast.AST, Iterable[ast.AST]]
    other: Union[ast.AST, Iterable[ast.AST]]
  Yields:
    Tuple[ast.AST, ast.AST]
  Raises:
    ValueError: if the two trees don't have identical structure.
  """
    if isinstance(node, (list, tuple)):
        node_stack = list(node)
    else:
        node_stack = [node]
    if isinstance(other, (list, tuple)):
        other_stack = list(other)
    else:
        other_stack = [other]
    while node_stack and other_stack:
        assert len(node_stack) == len(other_stack)
        n = node_stack.pop()
        o = other_stack.pop()
        if not isinstance(n, (ast.AST, gast.AST, str)) and n is not None or (not isinstance(o, (ast.AST, gast.AST, str)) and n is not None) or n.__class__.__name__ != o.__class__.__name__:
            raise ValueError('inconsistent nodes: {} ({}) and {} ({})'.format(n, n.__class__.__name__, o, o.__class__.__name__))
        yield (n, o)
        if isinstance(n, str):
            assert isinstance(o, str), 'The check above should have ensured this'
            continue
        if <MASK>:
            assert o is None, 'The check above should have ensured this'
            continue
        for f in n._fields:
            n_child = getattr(n, f, None)
            o_child = getattr(o, f, None)
            if f.startswith('__') or n_child is None or o_child is None:
                continue
            if isinstance(n_child, (list, tuple)):
                if not isinstance(o_child, (list, tuple)) or len(n_child) != len(o_child):
                    raise ValueError('inconsistent values for field {}: {} and {}'.format(f, n_child, o_child))
                node_stack.extend(n_child)
                other_stack.extend(o_child)
            elif isinstance(n_child, (gast.AST, ast.AST)):
                node_stack.append(n_child)
                other_stack.append(o_child)
            elif n_child != o_child:
                raise ValueError('inconsistent values for field {}: {} and {}'.format(f, n_child, o_child))

@lru_cache
def get_job_name(id: int | None, workflow_id: int | None, workflow_run_attempt: int | None) -> str | None:
    if id is None:
        return None
    try:
        if <MASK>:
            response = requests.get(f'{PYTORCH_REPO}/actions/jobs/{id}', headers=_get_request_headers())
            if response.status_code != 200:
                return None
            return cast(str, response.json()['name'])
        else:

            @lru_cache
            def _get_jobs(workflow_id: int) -> dict[int, str]:
                jobs: dict[int, str] = {}
                page = 1
                while True:
                    response = requests.get(f'{PYTORCH_REPO}/actions/runs/{workflow_id}/attempts/{workflow_run_attempt}/jobs', headers=_get_request_headers(), params={'page': page, 'per_page': 100})
                    if response.status_code != 200:
                        return jobs
                    for job in response.json()['jobs']:
                        jobs[job['id']] = job['name']
                    if 'next' not in response.links:
                        break
                    page += 1
                return jobs
            jobs = _get_jobs(workflow_id)
            return jobs[id]
    except Exception:
        return None

