def get_unique_name_wrt(prefix: str, *containers: Any, requires_suffix: bool=False) -> str:
    """
    Return a name that starts with `prefix` and is not in any of the
    `containers` (e.g., map, set).
    """
    if not requires_suffix and (not is_in(prefix, *containers)):
        return prefix
    for i in itertools.count():
        candidate = f'{prefix}_{i}'
        if <MASK>:
            return candidate
    raise AssertionError('unreachable')

def _distribute_tensors(local_state_dict: dict[str, Any], keys: list[str], device: torch.device, pg: Optional[dist.ProcessGroup]=None) -> None:
    if pg is None:
        pg = dist.distributed_c10d._get_default_group()
    for key in keys:
        _local_state = local_state_dict.get(key)
        if _local_state is None or torch.is_tensor(_local_state):
            continue
        local_state = _local_state[0]
        full_tensor = _local_state[1]
        (shape, offset) = compute_local_shape_and_global_offset(full_tensor.shape, local_state.device_mesh, local_state.placements)
        slices = [slice(cur_offset, cur_offset + cur_shape) for (cur_shape, cur_offset) in zip(shape, offset)]
        if <MASK>:
            local_tensor = full_tensor[tuple(slices)].detach().clone()
            ret = DTensor.from_local(local_tensor, local_state.device_mesh, local_state.placements, shape=local_state.shape, stride=local_state.stride())
        else:
            ret = local_state
            ret.to_local().copy_(full_tensor[tuple(slices)])
        local_state_dict[key] = ret

