def _partial_read(self, file_path: Path, state_dict: STATE_DICT, *, map_location: Any=None, **kwargs: dict[str, Any]) -> tuple[STATE_DICT, list[str]]:
    """
        Reads only the keys present in state_dict from the checkpoint file.

        This method optimizes checkpoint loading by only loading the tensors that
        are actually needed, based on the keys present in the input state_dict.
        This can significantly reduce memory usage and loading time for large checkpoints
        when only a subset of the model needs to be loaded.

        Args:
            file_path (str): The path to the checkpoint file.
            state_dict (STATE_DICT): The state dictionary containing keys to load.
            map_location (Any): Device mapping function or device name for relocating tensors.
            **kwargs: Additional keyword arguments passed to torch.load.

        Returns:
            tuple[STATE_DICT, list[str]]: The updated state dictionary with loaded values and a list of missing keys.
        """
    with FakeTensorMode():
        metadata_dict = torch.load(file_path, map_location=map_location)
    missing_keys = []
    with open(file_path, 'rb') as file:

        def load_tensor(target: Optional[torch.Tensor], source: torch.Tensor, full_key: str) -> torch.Tensor:
            if target is not None and (target.size() != source.size() or target.dtype != source.dtype):
                raise RuntimeError(f'Target tensor size={target.size()} dtype={target.dtype} does not match source tensor size={source.size()} dtype={source.dtype} for key {full_key}')
            tensor_offset = source.untyped_storage()._checkpoint_offset
            if tensor_offset is None:
                raise AssertionError('checkpoint_offset for tensor in torch serialized file is not set. This could happen if the checkpoint was saved with a older version of Pytorch. Please make sure that the checkpoint was saved with Pytorch 2.7 or later.')
            tensor_len = source.nelement() * source.element_size()
            file.seek(tensor_offset + source.element_size() * int(source.storage_offset()))
            if target is None:
                target = torch.empty(source.size(), dtype=source.dtype, device=source.device)
            buffer = file.read(tensor_len)
            cpu_tensor = torch.frombuffer(buffer, dtype=source.dtype)
            tensor = cpu_tensor.view(source.size())
            target.copy_(tensor)
            return target

        def process_value(target_value: Any, source_value: Any, key_path: str) -> Any:
            source_type = type(source_value)
            if source_type is torch._subclasses.fake_tensor.FakeTensor:
                source_type = torch.Tensor
            if target_value is not None and (not isinstance(target_value, source_type)):
                raise RuntimeError(f'Target value {key_path} is set to {type(target_value)}, but source value is {type(source_value)}')
            if isinstance(source_value, torch.Tensor):
                return load_tensor(target_value, source_value, key_path)
            elif isinstance(source_value, dict):
                if target_value is None:
                    target_value = dict.fromkeys(source_value.keys())
                for key in list(target_value.keys()):
                    current_path = f'{key_path}.{key}' if key_path else key
                    if key in source_value:
                        target_value[key] = process_value(target_value[key], source_value[key], current_path)
                    else:
                        missing_keys.append(current_path)
                return target_value
            elif isinstance(source_value, list):
                if target_value is None:
                    target_value = [None] * len(source_value)
                result = []
                for (i, (target_item, source_item)) in enumerate(zip_longest(target_value, source_value, fillvalue=None)):
                    current_path = f'{key_path}[{i}]' if key_path else f'[{i}]'
                    result.append(process_value(target_item, source_item, current_path))
                return result
            else:
                return source_value
        updated_state_dict = process_value(state_dict, metadata_dict, '')
    if missing_keys:
        if <MASK>:
            logger.warning('Missing %s keys from checkpoint: %s... (and %s more)', len(missing_keys), missing_keys[:10], len(missing_keys) - 10)
        else:
            logger.warning('Missing %s keys from checkpoint: %s', len(missing_keys), missing_keys)
    return (updated_state_dict, missing_keys)

def __new__(cls, data=None, mask=nomask, dtype=None, copy=False, subok=True, ndmin=0, fill_value=None, keep_mask=True, hard_mask=None, shrink=True, order=None):
    """
        Create a new masked array from scratch.

        Notes
        -----
        A masked array can also be created by taking a .view(MaskedArray).

        """
    copy = None if not copy else True
    _data = np.array(data, dtype=dtype, copy=copy, order=order, subok=True, ndmin=ndmin)
    _baseclass = getattr(data, '_baseclass', type(_data))
    if isinstance(data, MaskedArray) and data.shape != _data.shape:
        copy = True
    if <MASK>:
        _data = ndarray.view(_data, type(data))
    else:
        _data = ndarray.view(_data, cls)
    if hasattr(data, '_mask') and (not isinstance(data, ndarray)):
        _data._mask = data._mask
    mdtype = make_mask_descr(_data.dtype)
    if mask is nomask:
        if not keep_mask:
            if shrink:
                _data._mask = nomask
            else:
                _data._mask = np.zeros(_data.shape, dtype=mdtype)
        elif isinstance(data, (tuple, list)):
            try:
                mask = np.array([getmaskarray(np.asanyarray(m, dtype=_data.dtype)) for m in data], dtype=mdtype)
            except (ValueError, TypeError):
                mask = nomask
            if mdtype == MaskType and mask.any():
                _data._mask = mask
                _data._sharedmask = False
        else:
            _data._sharedmask = not copy
            if copy:
                _data._mask = _data._mask.copy()
                if getmask(data) is not nomask:
                    if data._mask.shape != data.shape:
                        data._mask.shape = data.shape
    else:
        if mask is None:
            mask = False
        if mask is True and mdtype == MaskType:
            mask = np.ones(_data.shape, dtype=mdtype)
        elif mask is False and mdtype == MaskType:
            mask = np.zeros(_data.shape, dtype=mdtype)
        else:
            try:
                mask = np.array(mask, copy=copy, dtype=mdtype)
            except TypeError:
                mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
        if mask.shape != _data.shape:
            (nd, nm) = (_data.size, mask.size)
            if nm == 1:
                mask = np.resize(mask, _data.shape)
            elif nm == nd:
                mask = np.reshape(mask, _data.shape)
            else:
                msg = f'Mask and data not compatible: data size is {nd}, mask size is {nm}.'
                raise MaskError(msg)
            copy = True
        if _data._mask is nomask:
            _data._mask = mask
            _data._sharedmask = not copy
        elif not keep_mask:
            _data._mask = mask
            _data._sharedmask = not copy
        else:
            if _data.dtype.names is not None:

                def _recursive_or(a, b):
                    """do a|=b on each field of a, recursively"""
                    for name in a.dtype.names:
                        (af, bf) = (a[name], b[name])
                        if af.dtype.names is not None:
                            _recursive_or(af, bf)
                        else:
                            af |= bf
                _recursive_or(_data._mask, mask)
            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

def testCancelRemoteFunctionDuringExecution(self):
    remote_async_env_var = 'TF_ENABLE_EAGER_CLIENT_STREAMING_ENQUEUE'
    default_streaming = os.environ.get(remote_async_env_var)
    os.environ[remote_async_env_var] = str(False)
    q = data_flow_ops.FIFOQueue(1, dtypes.int32)

    @def_function.function
    def f():
        return q.dequeue()
    c_mgr = cancellation.CancellationManager()
    cancelable_func = c_mgr.get_cancelable_function(f.get_concrete_function())

    def cancel_thread():
        time.sleep(0.5)
        c_mgr.start_cancel()
    t = self.checkedThread(cancel_thread)
    t.start()
    with self.assertRaises(errors.CancelledError):
        with ops.device('/job:worker/replica:0/task:1'):
            cancelable_func()
    t.join()
    if <MASK>:
        del os.environ[remote_async_env_var]
    else:
        os.environ[remote_async_env_var] = default_streaming

