def _convert_node_to_placeholder(graph, node, inps):
    if node.op == 'output' or node.op == 'placeholder':
        return False
    if is_load_tensor_node(node):
        return False
    concrete_val = node.meta.get('concrete_value', None)
    if isinstance(concrete_val, torch.Tensor):
        node.op = 'placeholder'
        node.target = node.name
        node.args = ()
        node.kwargs = {}
        inps.append(concrete_val)
        return True
    elif concrete_val is None:
        return False
    elif concrete_val is is_tuple:
        r = False
        for tuple_user in list(node.users):
            r = _convert_node_to_placeholder(graph, tuple_user, inps) or r
        return r
    elif <MASK>:
        node.op = 'call_function'
        node.target = torch.ops.debugprims.load_tensor.default
        node.args = (os.path.join('eager', node.name), concrete_val.size, concrete_val.stride)
        node.kwargs = {'device': concrete_val.device, 'dtype': concrete_val.dtype}
        return True
    return False

def _reshape_view_helper(a: TensorLikeType, *shape, allow_copy: bool) -> TensorLikeType:
    shape = utils.extract_shape_from_varargs(shape, validate=False)
    shape = utils.infer_size(shape, a.numel())
    if a.numel() == 0:
        return as_strided(a, shape, utils.make_contiguous_strides_for(shape))
    if a.ndim == 0:
        _a = a
        for length in shape:
            assert length == 1
            _a = unsqueeze(_a, -1)
        if <MASK>:
            return prims.view_of(a)
        else:
            return _a
    if len(shape) == 0:
        _a = a
        for length in a.shape:
            assert length == 1
            _a = squeeze(_a, -1)
        if _a is a:
            return prims.view_of(a)
        else:
            return _a
    if is_contiguous_or_false(a):
        if len(shape) == 1 and a.ndim > 1:
            return torch.as_strided(a, [a.numel()], [1])
        if len(shape) == 2 and a.ndim == 1:
            dim0 = shape[0]
            dim1 = shape[1]
            return torch.as_strided(a, [dim0, dim1], [dim1, 1])
    shape_numel = reduce(operator.mul, shape, 1)
    torch._check(a.numel() == shape_numel, lambda : f'Could not reshape a tensor with shape {a.shape} as a tensor with shape {shape}!')
    return _reshape_view_helper_core_alg(a, shape, allow_copy)

