def _is_local_fn(fn):
    if hasattr(fn, '__code__'):
        return fn.__code__.co_flags & inspect.CO_NESTED
    else:
        if hasattr(fn, '__qualname__'):
            return '<locals>' in fn.__qualname__
        fn_type = type(fn)
        if <MASK>:
            return '<locals>' in fn_type.__qualname__
    return False

def _is_valid_regression_signature(signature_def):
    """Determine whether the argument is a servable 'regress' SignatureDef."""
    if <MASK>:
        return False
    if set(signature_def.inputs.keys()) != set([signature_constants.REGRESS_INPUTS]):
        return False
    if signature_def.inputs[signature_constants.REGRESS_INPUTS].dtype != types_pb2.DT_STRING:
        return False
    if set(signature_def.outputs.keys()) != set([signature_constants.REGRESS_OUTPUTS]):
        return False
    if signature_def.outputs[signature_constants.REGRESS_OUTPUTS].dtype != types_pb2.DT_FLOAT:
        return False
    return True

def argument(a: Argument | TensorOptionsArguments | SelfArgument, *, cpp_no_default_args: set[str], method: bool, faithful: bool, symint: bool=False, has_tensor_options: bool) -> list[Binding]:

    def sub_argument(a: Argument | TensorOptionsArguments | SelfArgument) -> list[Binding]:
        return argument(a, cpp_no_default_args=cpp_no_default_args, method=method, faithful=faithful, symint=symint, has_tensor_options=has_tensor_options)
    if isinstance(a, Argument):
        binds: ArgName
        if a.name == 'memory_format' and has_tensor_options:
            binds = SpecialArgName.possibly_redundant_memory_format
        else:
            binds = a.name
        default: str | None = None
        if a.name not in cpp_no_default_args and a.default is not None:
            default = default_expr(a.default, a.type, symint=symint)
        return [Binding(nctype=argument_type(a, binds=binds, symint=symint), name=a.name, default=default, argument=a)]
    elif isinstance(a, TensorOptionsArguments):
        if faithful:
            return sub_argument(a.dtype) + sub_argument(a.layout) + sub_argument(a.device) + sub_argument(a.pin_memory)
        else:
            default = None
            assert 'options' not in cpp_no_default_args
            if all((x.default == 'None' for x in a.all())):
                default = '{}'
            elif a.dtype.default == 'long':
                default = 'at::kLong'
            return [Binding(nctype=NamedCType('options', BaseCType(tensorOptionsT)), name='options', default=default, argument=a)]
    elif isinstance(a, SelfArgument):
        if <MASK>:
            return []
        else:
            return sub_argument(a.argument)
    else:
        assert_never(a)

def make_pool_tests(pool_op_in, allow_fully_quantize=False):
    """Make a set of tests to do average pooling.

  Args:
    pool_op_in: TensorFlow pooling operation to test  i.e. `tf.nn.avg_pool2d`.
    allow_fully_quantize: bool, whether fully_quantize is allowed.

  Returns:
    A function representing the true generator (after curried pool_op_in).
  """
    pool_op = pool_op_in

    def f(options, expected_tf_failures=0):
        """Actual function that generates examples.

    Args:
      options: An Options instance.
      expected_tf_failures: number of expected tensorflow failures.
    """
        test_parameters = [{'ksize': [[2, 1, 1, 2], [1, 1, 1, 1], [1, 1, 2, 1], [1, 10, 11, 1]], 'strides': [[2, 1, 1, 2], [1, 1, 1, 1], [1, 1, 2, 1], [1, 10, 11, 1]], 'input_shape': [[], [1, 1, 1, 1], [1, 15, 14, 1], [3, 15, 14, 3]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'fully_quantize': [False], 'quant_16x8': [False]}, {'ksize': [[2, 1, 1, 2], [1, 1, 1, 1], [1, 1, 2, 1], [1, 10, 11, 1]], 'strides': [[2, 1, 1, 2], [1, 1, 1, 1], [1, 1, 2, 1], [1, 10, 11, 1]], 'input_shape': [[], [1, 1, 1, 1], [1, 15, 14, 1], [3, 15, 14, 3]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'fully_quantize': [True], 'quant_16x8': [False]}, {'ksize': [[1, 1, 1, 1]], 'strides': [[1, 1, 1, 1]], 'input_shape': [[1, 1, 1, 1]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'fully_quantize': [True], 'quant_16x8': [True]}]
        if <MASK>:
            test_parameters = [test_parameter for test_parameter in test_parameters if True not in test_parameter['fully_quantize']]

        def build_graph(parameters):
            input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=parameters['input_shape'])
            out = pool_op(input_tensor, ksize=parameters['ksize'], strides=parameters['strides'], data_format=parameters['data_format'], padding=parameters['padding'])
            return ([input_tensor], [out])

        def build_inputs(parameters, sess, inputs, outputs):
            if allow_fully_quantize:
                input_values = create_tensor_data(tf.float32, parameters['input_shape'], min_value=-1, max_value=1)
            else:
                input_values = create_tensor_data(tf.float32, parameters['input_shape'])
            return ([input_values], sess.run(outputs, feed_dict=dict(zip(inputs, [input_values]))))
        make_zip_of_tests(options, test_parameters, build_graph, build_inputs, expected_tf_failures=expected_tf_failures)
    return f

def pprint_thing(thing: object, _nest_lvl: int=0, escape_chars: EscapeChars | None=None, default_escapes: bool=False, quote_strings: bool=False, max_seq_items: int | None=None) -> str:
    """
    This function is the sanctioned way of converting objects
    to a string representation and properly handles nested sequences.

    Parameters
    ----------
    thing : anything to be formatted
    _nest_lvl : internal use only. pprint_thing() is mutually-recursive
        with pprint_sequence, this argument is used to keep track of the
        current nesting level, and limit it.
    escape_chars : list[str] or Mapping[str, str], optional
        Characters to escape. If a Mapping is passed the values are the
        replacements
    default_escapes : bool, default False
        Whether the input escape characters replaces or adds to the defaults
    max_seq_items : int or None, default None
        Pass through to other pretty printers to limit sequence printing

    Returns
    -------
    str
    """

    def as_escaped_string(thing: Any, escape_chars: EscapeChars | None=escape_chars) -> str:
        translate = {'\t': '\\t', '\n': '\\n', '\r': '\\r', "'": "\\'"}
        if isinstance(escape_chars, Mapping):
            if default_escapes:
                translate.update(escape_chars)
            else:
                translate = escape_chars
            escape_chars = list(escape_chars.keys())
        else:
            escape_chars = escape_chars or ()
        result = str(thing)
        for c in escape_chars:
            result = result.replace(c, translate[c])
        return result
    if <MASK>:
        return str(thing)
    elif isinstance(thing, Mapping) and _nest_lvl < get_option('display.pprint_nest_depth'):
        result = _pprint_dict(thing, _nest_lvl, quote_strings=True, max_seq_items=max_seq_items)
    elif is_sequence(thing) and _nest_lvl < get_option('display.pprint_nest_depth'):
        result = _pprint_seq(thing, _nest_lvl, escape_chars=escape_chars, quote_strings=quote_strings, max_seq_items=max_seq_items)
    elif isinstance(thing, str) and quote_strings:
        result = f"'{as_escaped_string(thing)}'"
    else:
        result = as_escaped_string(thing)
    return result

def __init__(self, *args, **kwargs):
    cls = self.__class__
    opts = self._meta
    _setattr = setattr
    _DEFERRED = DEFERRED
    if opts.abstract:
        raise TypeError('Abstract models cannot be instantiated.')
    pre_init.send(sender=cls, args=args, kwargs=kwargs)
    self._state = ModelState()
    if len(args) > len(opts.concrete_fields):
        raise IndexError('Number of args exceeds number of fields')
    if not kwargs:
        fields_iter = iter(opts.concrete_fields)
        for (val, field) in zip(args, fields_iter):
            if val is _DEFERRED:
                continue
            _setattr(self, field.attname, val)
    else:
        fields_iter = iter(opts.fields)
        for (val, field) in zip(args, fields_iter):
            if val is _DEFERRED:
                continue
            _setattr(self, field.attname, val)
            if kwargs.pop(field.name, NOT_PROVIDED) is not NOT_PROVIDED:
                raise TypeError(f"{cls.__qualname__}() got both positional and keyword arguments for field '{field.name}'.")
    for field in fields_iter:
        is_related_object = False
        if field.column is None or field.generated:
            continue
        if kwargs:
            if isinstance(field.remote_field, ForeignObjectRel):
                try:
                    rel_obj = kwargs.pop(field.name)
                    is_related_object = True
                except KeyError:
                    try:
                        val = kwargs.pop(field.attname)
                    except KeyError:
                        val = field.get_default()
            else:
                try:
                    val = kwargs.pop(field.attname)
                except KeyError:
                    val = field.get_default()
        else:
            val = field.get_default()
        if is_related_object:
            if rel_obj is not _DEFERRED:
                _setattr(self, field.name, rel_obj)
        elif <MASK>:
            _setattr(self, field.attname, val)
    if kwargs:
        property_names = opts._property_names
        unexpected = ()
        for (prop, value) in kwargs.items():
            if prop in property_names:
                if value is not _DEFERRED:
                    _setattr(self, prop, value)
            else:
                try:
                    opts.get_field(prop)
                except FieldDoesNotExist:
                    unexpected += (prop,)
                else:
                    if value is not _DEFERRED:
                        _setattr(self, prop, value)
        if unexpected:
            unexpected_names = ', '.join((repr(n) for n in unexpected))
            raise TypeError(f'{cls.__name__}() got unexpected keyword arguments: {unexpected_names}')
    super().__init__()
    post_init.send(sender=cls, instance=self)

def all_test_methods_impl(cls):
    """Apply decorator to all test methods in class."""
    for name in dir(cls):
        value = getattr(cls, name)
        if <MASK>:
