                _data._mask = np.array(mask, dtype=mdtype)[()]
    if fill_value is not None:
        _data.fill_value = fill_value
    return _data

def skip_brackets(s, lbrac, rbrac):
    count = 0
    for (i, c) in enumerate(s):
        if c == lbrac:
            count += 1
        elif <MASK>:
            count -= 1
        if count == 0:
            return i
    raise ValueError(f"no match '{lbrac}' for '{rbrac}' ({s!r})")

def _get_cross_device_ops(self, value):
    if not self._use_merge_call():
        if not isinstance(self._cross_device_ops, cross_device_ops_lib.CollectiveAllReduce):
            logging.warning('Under XLA context, MirroredStrategy uses CollectiveAllReduce op. Although %r is provided to initialize MirroredStrategy, it is ignored in XLA. Please use CollectiveAllReduce(or default option) in the future, since other cross device ops are not well supported on XLA.', self._cross_device_ops)
        return self._collective_ops
    if <MASK>:
        value_int32 = True in {dtypes.as_dtype(v.dtype) == dtypes.int32 for v in value.values}
    else:
        value_int32 = dtypes.as_dtype(value.dtype) == dtypes.int32
    if value_int32:
        return cross_device_ops_lib.ReductionToOneDevice()
    else:
        return self._cross_device_ops

def dedup_and_sort_lifted_freevars(l_lifted_freevars, r_lifted_freevars):

    def shared_getattrs(l_lifted_proxies, r_lifted_proxies):
        true_targets = {proxy.node.target: proxy for proxy in l_lifted_proxies if proxy.node.op == 'get_attr'}
        l_shared_getattrs = {}
        r_shared_getattrs = {}
        for false_proxy in r_lifted_proxies:
            if <MASK>:
                true_proxy = true_targets[false_proxy.node.target]
                l_shared_getattrs[true_proxy] = true_proxy
                r_shared_getattrs[false_proxy] = true_proxy
        return (l_shared_getattrs, r_shared_getattrs)
    (l_shared_getattrs, r_shared_getattrs) = shared_getattrs(l_lifted_freevars.keys(), r_lifted_freevars.keys())
    l_shared_freevars = (l_lifted_freevars.keys() & r_lifted_freevars.keys()).union(l_shared_getattrs.keys())
    r_shared_freevars = (l_lifted_freevars.keys() & r_lifted_freevars.keys()).union(r_shared_getattrs.keys())
    unique_l_freevars = l_lifted_freevars.keys() - l_shared_freevars
    unique_r_freevars = r_lifted_freevars.keys() - r_shared_freevars

    def _sort_by_name(vars):
        return sorted(vars, key=lambda var: var.node.name)
    return (list(_sort_by_name(list(l_shared_freevars))), list(_sort_by_name(list(r_shared_freevars))), list(_sort_by_name(list(unique_l_freevars))), list(_sort_by_name(list(unique_r_freevars))))

def _get_inputs_and_attributes(node: torch.fx.Node) -> tuple[list[torch.fx.Node | None], dict[str, Any], list[str], list[str]]:
    """Find and Fill in the not provided kwargs with default values.

    Returns:
        (inputs, attributes, input_names, output_names)
    """
    if <MASK>:
        inputs = list(node.args)
        return (inputs, {}, [], [node.name])
    assert hasattr(node.target, '_schema'), f'The target should be an ATen operator now, but node target {node.target} has no schema'
    node_schema: torch.FunctionSchema = node.target._schema
    inputs: list[Any] = []
    input_names: list[str] = []
    attributes: dict[str, Any] = {}
    if inspect.isbuiltin(node.target):
        inputs = list(node.args)
    else:
        for (arg, schema_arg) in zip(node.args, node_schema.arguments):
            if arg is None or isinstance(arg, torch.fx.Node):
                inputs.append(arg)
                input_names.append(schema_arg.name)
            elif isinstance(arg, Sequence) and all((elem is None or isinstance(elem, torch.fx.Node) for elem in arg)):
                inputs.extend(arg)
                input_names.extend([schema_arg.name] * len(arg))
            elif isinstance(arg, torch.device):
                attributes[schema_arg.name] = str(arg)
            elif isinstance(arg, torch.dtype):
                attributes[schema_arg.name] = torch_dtype_to_onnx_dtype(arg)
            else:
                attributes[schema_arg.name] = arg
        for schema_arg in node_schema.arguments:
            if schema_arg.name not in node.kwargs:
                continue
            kwarg = node.kwargs[schema_arg.name]
            if schema_arg.name in {'layout', 'device', 'requires_grad', 'memory_format', 'implicit'} or isinstance(kwarg, torch.device):
                attr = str(kwarg)
            elif isinstance(kwarg, torch.dtype):
                attr = torch_dtype_to_onnx_dtype(kwarg)
            else:
                attr = kwarg
            attributes[schema_arg.name] = attr
    output_names = [f'{node.name}_{output.name}' for output in node_schema.returns]
    return (inputs, attributes, input_names, output_names)

def _is_supported(input_size, kernel_size, stride, padding, dilation):
    if dilation[-1] != 1:
        raise RuntimeError('Dilation must be 1 for tensor parallel convolution.')
    if padding[-1] != 0:
        if stride[-1] != 1:
            raise RuntimeError('Stride must be 1 when there is padding for tensor parallel convolution.')
        if kernel_size[-1] // 2 > input_size[-1]:
            raise RuntimeError('kernel_size[-1] // 2 should be less than or equal to input_size[-1] for tensor parallel convolution.')
    elif <MASK>:
        raise RuntimeError('It requires that input_size[-1] is divisible by stride[-1] and stride[-1] equals kernel_size[-1] when there is padding for tensor parallel convolution.')
    return True

def __reversed__(self):
    """Reverses the tensor along dimension 0."""
    if has_torch_function_unary(self):
        return handle_torch_function(Tensor.__reversed__, (self,), self)
    if <MASK>:
        return self
    else:
        return self.flip(0)

def check_consistent_history(self, connection):
    """
        Raise InconsistentMigrationHistory if any applied migrations have
        unapplied dependencies.
        """
    recorder = MigrationRecorder(connection)
    applied = recorder.applied_migrations()
    for migration in applied:
        if migration not in self.graph.nodes:
            continue
        for parent in self.graph.node_map[migration].parents:
            if parent not in applied:
                if parent in self.replacements:
                    if <MASK>:
                        continue
                raise InconsistentMigrationHistory("Migration {}.{} is applied before its dependency {}.{} on database '{}'.".format(migration[0], migration[1], parent[0], parent[1], connection.alias))

