    else:
        deltas = (0,)
    for (batch, driver, delta) in product(((), (3,), (3, 3)), drivers, deltas):
        shape = batch + (3 + delta, 3)
        a = random_well_conditioned_matrix(*shape, dtype=dtype, device=device)
        a.requires_grad_(requires_grad)
        b = make_tensor(shape, dtype=dtype, device=device, low=None, high=None, requires_grad=requires_grad)
        yield SampleInput(a, b, driver=driver)

def _normalize_axes(axis, ndim):
    axes = []
    if ndim == 0 and axis:
        raise IndexError(f'Dimension out of range: {axis[0]}')
    (lower, upper) = (-ndim, ndim - 1)
    for a in axis:
        if <MASK>:
            raise IndexError(f'Dimension out of range (expected to be in range of [{lower}, {upper}], but got {a}')
        if a < 0:
            a = a + ndim
        if a in axes:
            raise IndexError(f'Axis {a} appears multiple times in the list of axes')
        axes.append(a)
    return sorted(axes)

def write_cpp(cpp_path: str, upgrader_dict: list[dict[str, Any]]) -> None:
    upgrader_bytecode_function_to_index_map = get_upgrader_bytecode_function_to_index_map(upgrader_dict)
    version_map_src = construct_version_maps(upgrader_bytecode_function_to_index_map)
    all_upgrader_src_string = []
    for upgrader_bytecode in upgrader_dict:
        for (upgrader_name, bytecode) in upgrader_bytecode.items():
            if upgrader_name in EXCLUE_UPGRADER_SET:
                continue
            instruction_list_str = ''
            constant_list_str = ''
            type_list_str = ''
            register_size_str = ''
            operator_list_str = ''
            for (table_name, contents) in bytecode.items():
                element = ByteCode[table_name]
                if <MASK>:
                    instruction_list_str = construct_instruction(contents)
                elif element is ByteCode.constants:
                    constant_list_str = construct_constants(contents)
                elif element is ByteCode.operators:
                    operator_list_str = construct_operators(contents)
                elif element is ByteCode.types:
                    type_list_str = construct_types(contents)
                elif element is ByteCode.register_size:
                    register_size_str = construct_register_size(contents)
            one_upgrader_function_string = ONE_UPGRADER_FUNCTION.substitute(upgrader_name=upgrader_name, instruction_list=instruction_list_str, constant_list=constant_list_str, type_list=type_list_str, register_size=register_size_str)
            one_upgrader_src_string = ONE_UPGRADER_SRC.substitute(bytecode_function=one_upgrader_function_string.lstrip('\n'), operator_string_list=operator_list_str.lstrip('\n'))
            all_upgrader_src_string.append(one_upgrader_src_string)
    upgrader_file_content = UPGRADER_CPP_SRC.substitute(operator_version_map=version_map_src, upgrader_bytecode=''.join(all_upgrader_src_string).lstrip('\n'))
    print('writing file to : ', cpp_path + '/' + UPGRADER_MOBILE_FILE_NAME)
    with open(os.path.join(cpp_path, UPGRADER_MOBILE_FILE_NAME), 'wb') as out_file:
        out_file.write(upgrader_file_content.encode('utf-8'))

def __init__(self, dtype_or_func=None, default=None, missing_values=None, locked=False):
    self._locked = bool(locked)
    if <MASK>:
        self.func = str2bool
        self._status = 0
        self.default = default or False
        dtype = np.dtype('bool')
    else:
        try:
            self.func = None
            dtype = np.dtype(dtype_or_func)
        except TypeError:
            if not callable(dtype_or_func):
                errmsg = "The input argument `dtype` is neither a function nor a dtype (got '%s' instead)"
                raise TypeError(errmsg % type(dtype_or_func))
            self.func = dtype_or_func
            if default is None:
                try:
                    default = self.func('0')
                except ValueError:
                    default = None
            dtype = self._getdtype(default)
        try:
            (self._status, (_, func, default_def)) = self._find_map_entry(dtype)
        except LookupError:
            self.default = default
            (_, func, _) = self._mapper[-1]
            self._status = 0
        else:
            if default is None:
                self.default = default_def
            else:
                self.default = default
        if self.func is None:
            self.func = func
        if self.func == self._mapper[1][1]:
            if issubclass(dtype.type, np.uint64):
                self.func = np.uint64
            elif issubclass(dtype.type, np.int64):
                self.func = np.int64
            else:
                self.func = lambda x: int(float(x))
    if missing_values is None:
        self.missing_values = {''}
    else:
        if isinstance(missing_values, str):
            missing_values = missing_values.split(',')
        self.missing_values = set(list(missing_values) + [''])
    self._callingfunction = self._strict_call
    self.type = self._dtypeortype(dtype)
    self._checked = False
    self._initial_default = default

def _check_perm(self, perm):
    """Static check of perm."""
    if <MASK>:
        raise ValueError(f'Argument `perm` must have at least 1 dimension. Received: {perm}.')
    if not perm.dtype.is_integer:
        raise TypeError(f'Argument `perm` must be integer dtype. Received: {perm}.')
    static_perm = tensor_util.constant_value(perm)
    if static_perm is not None:
        sorted_perm = np.sort(static_perm, axis=-1)
        if np.any(sorted_perm != np.arange(0, static_perm.shape[-1])):
            raise ValueError(f'Argument `perm` must be a vector of unique integers from 0 to {static_perm.shape[-1] - 1}.')

@tf_export(v1=['resource_loader.get_root_dir_with_all_resources'])
def get_root_dir_with_all_resources():
    """Get a root directory containing all the data attributes in the build rule.

  Returns:
    The path to the specified file present in the data attribute of py_test
    or py_binary. Falls back to returning the same as get_data_files_path if it
    fails to detect a bazel runfiles directory.
  """
    script_dir = get_data_files_path()
    directories = [script_dir]
    data_files_dir = ''
    while True:
        candidate_dir = directories[-1]
        current_directory = _os.path.basename(candidate_dir)
        if '.runfiles' in current_directory:
            if <MASK>:
                data_files_dir = directories[-2]
            break
        else:
            new_candidate_dir = _os.path.dirname(candidate_dir)
            if new_candidate_dir == candidate_dir:
                break
            else:
                directories.append(new_candidate_dir)
    return data_files_dir or script_dir

