            return import_string(key_func)
    return default_key_func

def check_autotune_cache(configs: list[Config], filename: str | None, inductor_meta: dict[str, Any]) -> tuple[list[Config], AutotuneCache | None, dict[str, Any]]:
    """
    Given a list of configs, checks autotune cache and return metadata
    """
    autotune_cache = None
    autotune_cache_info = {}
    disabled = inductor_meta.get('force_disable_caches', False)
    if not disabled and filename is not None and (len(configs) > 1 or inductor_meta.get('coordinate_descent_tuning')) and (os.environ.get('TRITON_INTERPRET', '0') != '1'):
        configs_hash = hash_configs(configs)
        autotune_cache = AutotuneCache.create(inductor_meta, filename, configs_hash)
        if autotune_cache:
            if <MASK>:
                configs = [best_config]
                autotune_cache_info['best_config'] = triton_config_to_hashable(best_config)
                autotune_cache_info['autotune_cache_state'] = 'hit'
            else:
                autotune_cache_info['autotune_cache_state'] = 'miss'
                autotune_cache_info['num_configs'] = len(configs)
                if inductor_meta.get('coordinate_descent_tuning'):
                    autotune_cache_info['coordesc_tuning'] = True
                    if len(configs) == 1:
                        autotune_cache_info['coordesc_tuning_start_config'] = triton_config_to_hashable(configs[0])
    else:
        if len(configs) == 1:
            autotune_cache_info['autotune_cache_state'] = 'only 1 config'
            autotune_cache_info['only_config'] = triton_config_to_hashable(configs[0])
        if disabled:
            autotune_cache_info['autotune_cache_state'] = 'force_disabled'
            log.debug('autotune caching is disabled by config.force_disable_caches')
    return (configs, autotune_cache, autotune_cache_info)

@tf_utils.shape_type_conversion
def compute_output_shape(self, input_shape):
    if <MASK>:
        output_shape = None
    else:
        output_shape = input_shape[0][1:]
    for i in range(1, len(input_shape)):
        if input_shape[i] is None:
            shape = None
        else:
            shape = input_shape[i][1:]
        output_shape = self._compute_elemwise_op_output_shape(output_shape, shape)
    batch_sizes = {s[0] for s in input_shape if s is not None} - {None}
    if len(batch_sizes) == 1:
        output_shape = (list(batch_sizes)[0],) + output_shape
    else:
        output_shape = (None,) + output_shape
    return output_shape

def _interpolate_1d(indices: np.ndarray, yvalues: np.ndarray, method: str='linear', limit: int | None=None, limit_direction: str='forward', limit_area: Literal['inside', 'outside'] | None=None, fill_value: Any | None=None, bounds_error: bool=False, order: int | None=None, mask=None, **kwargs) -> None:
    """
    Logic for the 1-d interpolation.  The input
    indices and yvalues will each be 1-d arrays of the same length.

    Bounds_error is currently hardcoded to False since non-scipy ones don't
    take it as an argument.

    Notes
    -----
    Fills 'yvalues' in-place.
    """
    if mask is not None:
        invalid = mask
    else:
        invalid = isna(yvalues)
    valid = ~invalid
    if not valid.any():
        return
    if valid.all():
        return
    all_nans = np.flatnonzero(invalid)
    first_valid_index = find_valid_index(how='first', is_valid=valid)
    if first_valid_index is None:
        first_valid_index = 0
    start_nans = np.arange(first_valid_index)
    last_valid_index = find_valid_index(how='last', is_valid=valid)
    if last_valid_index is None:
        last_valid_index = len(yvalues)
    end_nans = np.arange(1 + last_valid_index, len(valid))
    if limit_direction == 'forward':
        preserve_nans = np.union1d(start_nans, _interp_limit(invalid, limit, 0))
    elif <MASK>:
        preserve_nans = np.union1d(end_nans, _interp_limit(invalid, 0, limit))
    else:
        preserve_nans = np.unique(_interp_limit(invalid, limit, limit))
    if limit_area == 'inside':
        preserve_nans = np.union1d(preserve_nans, start_nans)
        preserve_nans = np.union1d(preserve_nans, end_nans)
    elif limit_area == 'outside':
        mid_nans = np.setdiff1d(all_nans, start_nans, assume_unique=True)
        mid_nans = np.setdiff1d(mid_nans, end_nans, assume_unique=True)
        preserve_nans = np.union1d(preserve_nans, mid_nans)
    is_datetimelike = yvalues.dtype.kind in 'mM'
    if is_datetimelike:
        yvalues = yvalues.view('i8')
    if method in NP_METHODS:
        indexer = np.argsort(indices[valid])
        yvalues[invalid] = np.interp(indices[invalid], indices[valid][indexer], yvalues[valid][indexer])
    else:
        yvalues[invalid] = _interpolate_scipy_wrapper(indices[valid], yvalues[valid], indices[invalid], method=method, fill_value=fill_value, bounds_error=bounds_error, order=order, **kwargs)
    if mask is not None:
        mask[:] = False
        mask[preserve_nans] = True
    elif is_datetimelike:
        yvalues[preserve_nans] = NaT.value
    else:
        yvalues[preserve_nans] = np.nan
    return

def __init__(self, name: str, sources: Union[str, list[str]], BuildOption: BuildOptionsBase, output_dir: str='') -> None:
    self._compiler = ''
    self._cflags_args = ''
    self._definitions_args = ''
    self._include_dirs_args = ''
    self._ldflags_args = ''
    self._libraries_dirs_args = ''
    self._libraries_args = ''
    self._passthrough_parameters_args = ''
    self._orig_source_paths = []
    self._output_dir = ''
    self._target_file = ''
    self._use_relative_path: bool = False
    self._aot_mode: bool = False
    self._name = name
    self._target_name = config.aot_inductor.model_name_for_generated_files or 'aoti_model'
    self._build_option = BuildOption
    self._compiler = BuildOption.get_compiler()
    self._use_relative_path = BuildOption.get_use_relative_path()
    self._aot_mode = BuildOption.get_aot_mode()
    self._output_dir = output_dir
    self._compile_only = BuildOption.get_compile_only()
    self._precompiling = BuildOption.get_precompiling()
    self._preprocessing = BuildOption.get_preprocessing()
    assert sum((self._compile_only, self._precompiling, self._preprocessing)) <= 1
    self._do_link = not (self._compile_only or self._precompiling or self._preprocessing)
    assert not _IS_WINDOWS or not self._precompiling, 'Cannot currently precompile headers on Windows!'
    if self._compile_only:
        (file_ext, output_flags) = self.__get_object_flags()
    elif self._precompiling:
        (file_ext, output_flags) = self.__get_precompiled_header_flags()
    elif self._preprocessing:
        (file_ext, output_flags) = self.__get_preprocessor_output_flags()
    else:
        (file_ext, output_flags) = self.__get_python_module_flags()
    self._target_file = os.path.join(self._output_dir, f'{self._name}{file_ext}')
    relative_target_file = os.path.basename(self._target_file) if self._use_relative_path else self._target_file
    if <MASK>:
        if self._preprocessing:
            self._output = output_flags
        else:
            self._output = f'{output_flags}{relative_target_file}'
    else:
        self._output = f'{output_flags} {relative_target_file}'
    if isinstance(sources, str):
        sources = [sources]
    if config.is_fbcode() and self._use_relative_path:
        self._orig_source_paths = list(sources)
        sources = [os.path.basename(i) for i in sources]
    if self._precompiling:
        assert len(sources) == 1
        self._sources_args = f'-x c++-header {sources[0]}'
    else:
        self._sources_args = ' '.join(sources)
    for cflag in BuildOption.get_cflags():
        if _IS_WINDOWS:
            self._cflags_args += f'/{cflag} '
        else:
            self._cflags_args += f'-{cflag} '
    for definition in BuildOption.get_definitions():
        if _IS_WINDOWS:
            self._definitions_args += f'/D {definition} '
        else:
            self._definitions_args += f'-D {definition} '
    if (precompiled_header := BuildOption.precompiled_header):
        if _IS_WINDOWS:
            log.warning('Precompiled header support for MSVC is currently unavailable; ignoring %s', precompiled_header)
        else:
            self._include_dirs_args = f'-include {precompiled_header} '
    for inc_dir in BuildOption.get_include_dirs():
        if _IS_WINDOWS:
            self._include_dirs_args += f'/I "{inc_dir}" '
        else:
            self._include_dirs_args += f'-I{shlex.quote(inc_dir)} '
    for ldflag in BuildOption.get_ldflags():
        if _IS_WINDOWS:
            self._ldflags_args += f'/{ldflag} '
        else:
            self._ldflags_args += f'-{ldflag} '
    for lib_dir in BuildOption.get_libraries_dirs():
        if _IS_WINDOWS:
            self._libraries_dirs_args += f'/LIBPATH:"{lib_dir}" '
        else:
            self._libraries_dirs_args += f'-L{lib_dir} '
    for lib in BuildOption.get_libraries():
        if _IS_WINDOWS:
            self._libraries_args += f'"{lib}.lib" '
        else:
            self._libraries_args += f'-l{lib} '
    for passthrough_arg in BuildOption.get_passthrough_args():
        self._passthrough_parameters_args += f'{passthrough_arg} '

def read_model_from_bytearray(model_bytearray):
    """Reads a tflite model as a python object.

  Args:
    model_bytearray: TFLite model in bytearray format.

  Returns:
    A python object corresponding to the input tflite file.
  """
    model = convert_bytearray_to_object(model_bytearray)
    if sys.byteorder == 'big':
        byte_swap_tflite_model_obj(model, 'little', 'big')
    for buffer in model.buffers:
        if buffer.offset:
            buffer.data = model_bytearray[buffer.offset:buffer.offset + buffer.size]
            buffer.offset = 0
            buffer.size = 0
    for subgraph in model.subgraphs:
        for op in subgraph.operators:
            if <MASK>:
                op.customOptions = model_bytearray[op.largeCustomOptionsOffset:op.largeCustomOptionsOffset + op.largeCustomOptionsSize]
                op.largeCustomOptionsOffset = 0
                op.largeCustomOptionsSize = 0
    return model

def __setattr__(self, attr, value):
    if <MASK>:
        self[attr.upper()] = value
    else:
        super().__setattr__(attr, value)

def _without_context(node, lines, minl, maxl):
    """Returns a clean node and source code without indenting and context."""
    for n in gast.walk(node):
        lineno = getattr(n, 'lineno', None)
        if lineno is not None:
            n.lineno = lineno - minl
        end_lineno = getattr(n, 'end_lineno', None)
        if end_lineno is not None:
            n.end_lineno = end_lineno - minl
    code_lines = lines[minl - 1:maxl]
    end_col_offset = getattr(node, 'end_col_offset', None)
    if end_col_offset is not None:
        code_lines[-1] = code_lines[-1][:end_col_offset]
    col_offset = getattr(node, 'col_offset', None)
    if <MASK>:
        match = re.search('(?<!\\w)lambda(?!\\w)', code_lines[0])
        if match is not None:
            col_offset = match.start(0)
    if col_offset is not None:
        code_lines[0] = code_lines[0][col_offset:]
    code_block = '\n'.join([c.rstrip() for c in code_lines])
    return (node, code_block)

def _div(mul_f, c1, c2):
    """
    Helper function used to implement the ``<type>div`` functions.

    Implementation uses repeated subtraction of c2 multiplied by the nth basis.
    For some polynomial types, a more efficient approach may be possible.

    Parameters
    ----------
    mul_f : function(array_like, array_like) -> array_like
        The ``<type>mul`` function, such as ``polymul``
    c1, c2
        See the ``<type>div`` functions for more detail
    """
    [c1, c2] = as_series([c1, c2])
    if c2[-1] == 0:
        raise ZeroDivisionError
    lc1 = len(c1)
    lc2 = len(c2)
    if <MASK>:
        return (c1[:1] * 0, c1)
    elif lc2 == 1:
        return (c1 / c2[-1], c1[:1] * 0)
    else:
        quo = np.empty(lc1 - lc2 + 1, dtype=c1.dtype)
        rem = c1
        for i in range(lc1 - lc2, -1, -1):
            p = mul_f([0] * i + [1], c2)
            q = rem[-1] / p[-1]
            rem = rem[:-1] - q * p[:-1]
            quo[i] = q
        return (quo, trimseq(rem))

def __iter__(self):
    datasets: List[Tuple[int, data_types.DatasetV2]] = []
    local_dataset = self._batched_dataset
    if self._batch_dim is not None:
        if self._num_clients_per_replica > 1:
            local_dataset = self._repeat_batch(local_dataset, self._num_clients_per_replica)
            sharding_policy = data_service_ops.ShardingPolicy.DATA
        else:
            sharding_policy = data_service_ops.ShardingPolicy.FILE
    else:
        sharding_policy = data_service_ops.ShardingPolicy.OFF
    if <MASK>:
        local_dataset = local_dataset.apply(data_service_ops.distribute(processing_mode=sharding_policy, service=self._tf_data_service_config.dispatcher_address, job_name=f'{self._tf_data_service_config.job_name}_{config.client_id()}', target_workers='LOCAL'))
    for (local_replica_idx, replica_id) in enumerate(self._local_replica_ids):
        dataset = distribute._AutoShardDataset(local_dataset, num_workers=self._num_local_replicas, index=local_replica_idx, num_replicas=self.num_global_replicas)
        dataset = self._repeat_batch(dataset, self._num_local_devices_per_replica)
        dataset = self._partition(dataset)
        if self._prefetch is not None:
            dataset = dataset.prefetch(self._prefetch * self._num_local_devices_per_replica)
        datasets.append((replica_id, dataset))
    d_iterator_resource = _pack_iterator_resource_dtensor(datasets=datasets, layouts=self._layouts, mesh=self._mesh, num_local_devices_per_replica=self._num_local_devices_per_replica)
    return _DTensorIterator(dtensor_components=(d_iterator_resource,), global_element_spec=self._global_element_spec, layouts=self._layouts)

def get_queryset(self):
    """
        Return the list of items for this view.

        The return value must be an iterable and may be an instance of
        `QuerySet` in which case `QuerySet` specific behavior will be enabled.
        """
    if self.queryset is not None:
        queryset = self.queryset
        if isinstance(queryset, QuerySet):
            queryset = queryset.all()
    elif <MASK>:
        queryset = self.model._default_manager.all()
    else:
        raise ImproperlyConfigured('%(cls)s is missing a QuerySet. Define %(cls)s.model, %(cls)s.queryset, or override %(cls)s.get_queryset().' % {'cls': self.__class__.__name__})
    ordering = self.get_ordering()
    if ordering:
        if isinstance(ordering, str):
            ordering = (ordering,)
        queryset = queryset.order_by(*ordering)
    return queryset

@staticmethod
def reciprocal(x):
    """Needed as it's used in pow, but it won't appear on a SymPy expression"""
    x = ValueRanges.wrap(x)
    if <MASK>:
        return ValueRanges.unknown()
    else:
        return ValueRanges.decreasing_map(x, lambda y: FloatTrueDiv(1.0, y))

def get_fused_kernel_name(node_schedule: Sequence[BaseSchedulerNode], descriptive_names: Literal[True, 'torch', 'original_aten', 'inductor_node']) -> str:
    all_origins = aggregate_origins(node_schedule)
    if descriptive_names == 'original_aten':
        sources = [origin.meta['original_aten']._overloadpacket.__name__ for origin in all_origins if origin.op == 'call_function' and 'original_aten' in origin.meta and (origin.meta['original_aten'] is not None)]
        sources = sorted(OrderedSet(sources))
    elif <MASK>:
        sources = []
        for origin in all_origins:
            if origin.op == 'call_function' and 'source_fn_stack' in origin.meta:
                source_fn = origin.meta['source_fn_stack'][-1]
                if isinstance(source_fn[1], str):
                    sources.append(source_fn[1])
                else:
                    sources.append(source_fn[1].__name__)
        sources = sorted(OrderedSet(sources))
    elif descriptive_names == 'inductor_node':
        sources = [origin.name for origin in all_origins if origin.op == 'call_function']
    else:
        raise NotImplementedError
    return '_'.join(['fused'] + sources)

def equals(self, other: object) -> bool:
    """
        Determines if two MultiIndex objects have the same labeling information
        (the levels themselves do not necessarily have to be the same)

        See Also
        --------
        equal_levels
        """
    if self.is_(other):
        return True
    if <MASK>:
        return False
    if len(self) != len(other):
        return False
    if not isinstance(other, MultiIndex):
        if not self._should_compare(other):
            return False
        return array_equivalent(self._values, other._values)
    if self.nlevels != other.nlevels:
        return False
    for i in range(self.nlevels):
        self_codes = self.codes[i]
        other_codes = other.codes[i]
        self_mask = self_codes == -1
        other_mask = other_codes == -1
        if not np.array_equal(self_mask, other_mask):
            return False
        self_level = self.levels[i]
        other_level = other.levels[i]
        new_codes = recode_for_categories(other_codes, other_level, self_level, copy=False)
        if not np.array_equal(self_codes, new_codes):
            return False
        if not self_level[:0].equals(other_level[:0]):
            return False
    return True

def dump_field(f) -> tuple[dict[str, Any], str, Optional[str], str, int]:
    (t, cpp_type, thrift_type) = dump_type(f.type, 0)
    ret = {'type': t}
    cpp_default: Optional[str] = None
    assert typing.get_origin(f.type) == Annotated, f'Field {f.name} must be annotated with an integer id.'
    thrift_id = f.type.__metadata__[0]
    assert type(thrift_id) is int, f'Field {f.name} must be annotated with an integer id.'
    value = dataclasses.MISSING
    if f.default is not dataclasses.MISSING:
        value = f.default
    elif <MASK>:
        value = f.default_factory()
    if value is not dataclasses.MISSING:
        default = str(value)
        ret['default'] = default
        cpp_default = dump_cpp_value(value)
        if t.startswith('Optional[') and value is not None:
            raise AssertionError(f'Optional field {ty.__name__}.{f.name} must have default value to be None.')
    return (ret, cpp_type, cpp_default, thrift_type, thrift_id)

def build_graph(self):
    """
        Build a migration dependency graph using both the disk and database.
        You'll need to rebuild the graph if you apply migrations. This isn't
        usually a problem as generally migration stuff runs in a one-shot
        process.
        """
    self.load_disk()
    if self.connection is None:
        self.applied_migrations = {}
    else:
        recorder = MigrationRecorder(self.connection)
        self.applied_migrations = recorder.applied_migrations()
    self.graph = MigrationGraph()
    self.replacements = {}
    for (key, migration) in self.disk_migrations.items():
        self.graph.add_node(key, migration)
        if migration.replaces:
            self.replacements[key] = migration
    for (key, migration) in self.disk_migrations.items():
        self.add_internal_dependencies(key, migration)
    for (key, migration) in self.disk_migrations.items():
        self.add_external_dependencies(key, migration)
    if <MASK>:
        self.replacements_progress = {}
        for migration_key in self.replacements.keys():
            self.replace_migration(migration_key)
    try:
        self.graph.validate_consistency()
    except NodeNotFoundError as exc:
        reverse_replacements = {}
        for (key, migration) in self.replacements.items():
            for replaced in migration.replaces:
                reverse_replacements.setdefault(replaced, set()).add(key)
        if exc.node in reverse_replacements:
            candidates = reverse_replacements.get(exc.node, set())
            is_replaced = any((candidate in self.graph.nodes for candidate in candidates))
            if not is_replaced:
                tries = ', '.join(('%s.%s' % c for c in candidates))
                raise NodeNotFoundError("Migration {0} depends on nonexistent node ('{1}', '{2}'). Django tried to replace migration {1}.{2} with any of [{3}] but wasn't able to because some of the replaced migrations are already applied.".format(exc.origin, exc.node[0], exc.node[1], tries), exc.node) from exc
        raise
    self.graph.ensure_not_cyclic()

def _get_layout(name):
    """Get layout extension object from its string representation."""
    cache = _get_layout.cache
    if <MASK>:
        for v in torch.__dict__.values():
            if isinstance(v, torch.layout):
                cache[str(v)] = v
    return cache[name]

def _get_code_source(code: types.CodeType) -> tuple[str, str]:
    """
    Given a code object, return a fully qualified name which will be used as
    a serialized handle to access the code object from the new process.
    This is normally a straightforward process, but there are some corner cases:
    1. When a function is defined with decorator, then this function will be captured
       inside a closure with the wrapper object.
    2. When a function is defined as a nested function, then the code object will be
       stored on the co_consts field of the parent code object by Python compiler.
    This function handles all of the corner cases above.
    """
    module = inspect.getmodule(code)
    if module is None:
        raise PackageError(f'Cannot find module for code {code}')
    toplevel: Any = module
    if sys.version_info >= (3, 11):
        parts = code.co_qualname.split('.')
        for part in parts:
            if not hasattr(toplevel, part):
                _raise_resolution_error(code, toplevel)
            toplevel = getattr(toplevel, part)
            if inspect.isfunction(toplevel):
                break
    seen = set()

    def _find_code_source(obj: Any) -> Optional[str]:
        nonlocal toplevel
        nonlocal seen
        if obj in seen:
            return None
        seen.add(obj)
        if inspect.iscode(obj):
            if obj is code:
                return ''
            for (i, const) in enumerate(obj.co_consts):
                if (res := _find_code_source(const)) is not None:
                    return f'.co_consts[{i}]{res}'
        if inspect.isfunction(obj):
            if <MASK>:
                toplevel = obj
                return f'.__code__{res}'
            if obj.__closure__ is not None:
                for (i, cell) in enumerate(obj.__closure__):
                    try:
                        cell_contents = cell.cell_contents
                    except ValueError:
                        continue
                    if not (inspect.isfunction(cell_contents) or inspect.iscode(cell_contents)):
                        continue
                    if (res := _find_code_source(cell_contents)) is not None:
                        toplevel = obj
                        return f'.__closure__[{i}].cell_contents{res}'
        if sys.version_info < (3, 11):
            if inspect.ismodule(obj):
                for value in obj.__dict__.values():
                    if not (inspect.isfunction(value) or inspect.isclass(value)):
                        continue
                    if (res := _find_code_source(value)) is not None:
                        return res
            if inspect.isclass(obj):
                for (name, value) in obj.__dict__.items():
                    value = getattr(obj, name)
                    if not (inspect.isfunction(value) or inspect.isclass(value)):
                        continue
                    if (res := _find_code_source(value)) is not None:
                        if value.__name__ != name:
                            _raise_resolution_error(code, toplevel)
                        return res
        return None
    code_source = _find_code_source(toplevel)
    if code_source is None:
        _raise_resolution_error(code, toplevel)
    return (toplevel.__qualname__, code_source.strip('.'))

def _ignore_module(module: nn.Module, ignored_params: set[nn.Parameter], ignore_decision: dict[nn.Module, bool]) -> bool:
    """
    Decide if it is safe to ignore a module for applying fully_shard.
    """
    if <MASK>:
        return ignore_decision[module]
    if len(list(module.buffers(recurse=False))) > 0:
        ignore_decision[module] = False
        return False
    for (_, param) in module.named_parameters(recurse=False):
        if param not in ignored_params:
            ignore_decision[module] = False
            return False
    for child in list(module.children()):
        ignore_child = _ignore_module(child, ignored_params, ignore_decision)
        if not ignore_child:
            ignore_decision[module] = False
            return False
    ignore_decision[module] = True
    return True

@final
def _maybe_disallow_fill(self, allow_fill: bool, fill_value, indices) -> bool:
    """
        We only use pandas-style take when allow_fill is True _and_
        fill_value is not None.
        """
    if <MASK>:
        if self._can_hold_na:
            if (indices < -1).any():
                raise ValueError('When allow_fill=True and fill_value is not None, all indices must be >= -1')
        else:
            cls_name = type(self).__name__
            raise ValueError(f'Unable to fill values because {cls_name} cannot contain NA')
    else:
        allow_fill = False
    return allow_fill

def infer_arg_by_inputs(raw_keys, raw_args, idx, reused_args):
    """We try to infer raw_arg (i.e. raw_args[idx]) from remaining raw_args.
                This is particularly useful for jagged cases, where the dimension is often
                being passed in as an input."""
    target_arg = raw_args[idx]
    if target_arg in reused_args:
        return True
    for (i, (raw_key, raw_arg)) in enumerate(zip(raw_keys, raw_args)):
        if i == idx or not isinstance(raw_arg, IRNode):
            continue
        triton_input = ''
        if autotune_args and raw_key in autotune_args:
            triton_input = self.get_autotuning_input_name(autotune_args[raw_key])
        if <MASK>:
            continue
        try:
            layout = raw_arg.get_layout()
            for (dim, s) in enumerate(layout.size):
                if s == target_arg:
                    reused_args[target_arg] = f'{triton_input}.shape[{dim}]'
                    return True
        except NotImplementedError:
            continue
    return False

def print_(*objects, **kwargs):
    """Overload of the print builtin."""
    unknown_kwargs = tuple(set(kwargs.keys()) - set(('sep', 'end', 'file', 'flush')))
    if unknown_kwargs:
        raise ValueError('invalid keyword arguments: {}'.format(unknown_kwargs))
    print_fn = _py_print
    for x in objects:
        print_override = registry_lookup(print_registry, x)
        if <MASK>:
            print_fn = print_override
            break
    if print_fn is _py_print:
        assert not any((tensor_util.is_tf_type(s) for s in objects))
    return print_fn(*objects, **kwargs)

def _reconstruct_model(self, model_id, model, layers):
    """Reconstructs the network structure."""
    config = json_utils.decode(self._metadata[model_id].metadata)['config']
    if model.inputs:
        pass
    elif isinstance(model, models_lib.Sequential):
        if not layers or not isinstance(layers[0], input_layer.InputLayer):
            if <MASK>:
                layers.insert(0, input_layer.InputLayer.from_config(config['layers'][0]['config']))
            elif 'batch_input_shape' in config['layers'][0]['config']:
                batch_input_shape = config['layers'][0]['config']['batch_input_shape']
                layers.insert(0, input_layer.InputLayer(input_shape=batch_input_shape[1:], batch_size=batch_input_shape[0], dtype=layers[0].dtype, name=layers[0].name + '_input'))
        model.__init__(layers, name=config['name'])
        if not model.inputs:
            first_layer = self._get_child_layer_node_ids(model_id)[0]
            input_specs = self._infer_inputs(first_layer)
            input_shapes = self._infer_inputs(first_layer, convert_to_shapes=True)
            model._set_inputs(input_specs)
            if not model.built and (not isinstance(input_specs, dict)):
                model.build(input_shapes)
    else:
        (inputs, outputs, created_layers) = functional_lib.reconstruct_from_config(config, created_layers={layer.name: layer for layer in layers})
        model.__init__(inputs, outputs, name=config['name'])
        functional_lib.connect_ancillary_layers(model, created_layers)
    _set_network_attributes_from_metadata(model)
    self._unblock_model_reconstruction(model_id, model)

def _range_in_self(self, other: range) -> bool:
    """Check if other range is contained in self"""
    if not other:
        return True
    if not self._range:
        return False
    if <MASK>:
        return False
    return other.start in self._range and other[-1] in self._range

def _compare(tree, dynamic_shapes, path):
    rendered_path = keystr(path)
    if isinstance(tree, LeafSpec):
        return
    if isinstance(dynamic_shapes, LeafSpec):
        raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is not')
    if tree.type != dynamic_shapes.type:
        raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is a {dynamic_shapes.type}')
    if len(tree.children_specs) != len(dynamic_shapes.children_specs):
        raise_mismatch_error(f'`{tree_name}{rendered_path}` has {len(tree.children_specs)} elements, but `dynamic_shapes{rendered_path}` has {len(dynamic_shapes.children_specs)} elements')
    if tree.type is dict:
        if <MASK>:
            raise_mismatch_error(f'`{tree_name}{rendered_path}` has keys {tree.context}, but `dynamic_shapes{rendered_path}` has keys {dynamic_shapes.context}')
        _remap = dict(zip(dynamic_shapes.context, dynamic_shapes.children_specs))
        dynamic_shapes_children_specs = [_remap[k] for k in tree.context]
    else:
        dynamic_shapes_children_specs = dynamic_shapes.children_specs
    for (i, (tree_, dynamic_shapes_)) in enumerate(zip(tree.children_specs, dynamic_shapes_children_specs)):
        _compare(tree_, dynamic_shapes_, path + [_key(tree.type, tree.context, i)])

def _get_dummies_1d(data, prefix, prefix_sep: str | Iterable[str] | dict[str, str]='_', dummy_na: bool=False, sparse: bool=False, drop_first: bool=False, dtype: NpDtype | None=None) -> DataFrame:
    from pandas.core.reshape.concat import concat
    (codes, levels) = factorize_from_iterable(Series(data, copy=False))
    if dtype is None and hasattr(data, 'dtype'):
        input_dtype = data.dtype
        if isinstance(input_dtype, CategoricalDtype):
            input_dtype = input_dtype.categories.dtype
        if isinstance(input_dtype, ArrowDtype):
            import pyarrow as pa
            dtype = ArrowDtype(pa.bool_())
        elif isinstance(input_dtype, StringDtype) and input_dtype.na_value is libmissing.NA:
            dtype = pandas_dtype('boolean')
        else:
            dtype = np.dtype(bool)
    elif dtype is None:
        dtype = np.dtype(bool)
    _dtype = pandas_dtype(dtype)
    if is_object_dtype(_dtype):
        raise ValueError('dtype=object is not a valid dtype for get_dummies')

    def get_empty_frame(data) -> DataFrame:
        index: Index | np.ndarray
        if isinstance(data, Series):
            index = data.index
        else:
            index = default_index(len(data))
        return DataFrame(index=index)
    if not dummy_na and len(levels) == 0:
        return get_empty_frame(data)
    codes = codes.copy()
    if dummy_na:
        codes[codes == -1] = len(levels)
        levels = levels.insert(len(levels), np.nan)
    if drop_first and len(levels) == 1:
        return get_empty_frame(data)
    number_of_cols = len(levels)
    if <MASK>:
        dummy_cols = levels
    else:
        dummy_cols = Index([f'{prefix}{prefix_sep}{level}' for level in levels])
    index: Index | None
    if isinstance(data, Series):
        index = data.index
    else:
        index = None
    if sparse:
        fill_value: bool | float
        if is_integer_dtype(dtype):
            fill_value = 0
        elif dtype == np.dtype(bool):
            fill_value = False
        else:
            fill_value = 0.0
        sparse_series = []
        N = len(data)
        sp_indices: list[list] = [[] for _ in range(len(dummy_cols))]
        mask = codes != -1
        codes = codes[mask]
        n_idx = np.arange(N)[mask]
        for (ndx, code) in zip(n_idx, codes):
            sp_indices[code].append(ndx)
        if drop_first:
            sp_indices = sp_indices[1:]
            dummy_cols = dummy_cols[1:]
        for (col, ixs) in zip(dummy_cols, sp_indices):
            sarr = SparseArray(np.ones(len(ixs), dtype=dtype), sparse_index=IntIndex(N, ixs), fill_value=fill_value, dtype=dtype)
            sparse_series.append(Series(data=sarr, index=index, name=col, copy=False))
        return concat(sparse_series, axis=1)
    else:
        shape = (len(codes), number_of_cols)
        dummy_dtype: NpDtype
        if isinstance(_dtype, np.dtype):
            dummy_dtype = _dtype
        else:
            dummy_dtype = np.bool_
        dummy_mat = np.zeros(shape=shape, dtype=dummy_dtype, order='F')
        dummy_mat[np.arange(len(codes)), codes] = 1
        if not dummy_na:
            dummy_mat[codes == -1] = 0
        if drop_first:
            dummy_mat = dummy_mat[:, 1:]
            dummy_cols = dummy_cols[1:]
        return DataFrame(dummy_mat, index=index, columns=dummy_cols, dtype=_dtype)

def extract_loop_body_with_args(fn: Any, args: list[list[sympy.Expr]], var_ranges: VarRanges, normalize: bool=False) -> _RecordLoadStoreInner:
    from .loop_body import MemoryUsageType
    inner = _RecordLoadStoreInner(var_ranges=var_ranges, normalize=normalize)
    name_to_index = fn.indexing_from_args(args)
    if <MASK>:
        repl = {v: make_symbol(SymT.TMP, i) for (i, v) in enumerate(fn.indirect_vars)}
        name_to_index = {k: sympy_subs(v, repl) for (k, v) in name_to_index.items()}
    for entry in fn.memory_usage[MemoryUsageType.LOAD]:
        inner.load(entry.buffer_name, name_to_index[entry.index_name])
    for entry in fn.memory_usage[MemoryUsageType.LOAD_SEED]:
        inner.load_seed(entry.buffer_name, int(name_to_index[entry.index_name]))
    for entry in fn.memory_usage[MemoryUsageType.STORE]:
        inner.store(entry.buffer_name, name_to_index[entry.index_name], None, entry.mode)
    for entry in fn.memory_usage[MemoryUsageType.STORE_REDUCTION]:
        inner.store_reduction(entry.buffer_name, name_to_index[entry.index_name], None)
    for entry in fn.memory_usage[MemoryUsageType.INDEX_EXPR]:
        inner.index_expr(name_to_index[entry.index_name], None)
    for entry in fn.memory_usage[MemoryUsageType.BUCKETIZE]:
        inner.bucketize(None, (entry.buffer_name, None, None, None), None, None, None)
    return inner

def __mul__(self, other):
    other = as_expr(other)
    if <MASK>:
        if self.op is other.op:
            if self.op in (Op.INTEGER, Op.REAL):
                return as_number(self.data[0] * other.data[0], max(self.data[1], other.data[1]))
            elif self.op is Op.COMPLEX:
                (r1, i1) = self.data
                (r2, i2) = other.data
                return as_complex(r1 * r2 - i1 * i2, r1 * i2 + r2 * i1)
            if self.op is Op.FACTORS:
                r = Expr(self.op, dict(self.data))
                for (k, v) in other.data.items():
                    _pairs_add(r.data, k, v)
                return normalize(r)
            elif self.op is Op.TERMS:
                r = Expr(self.op, {})
                for (t1, c1) in self.data.items():
                    for (t2, c2) in other.data.items():
                        _pairs_add(r.data, t1 * t2, c1 * c2)
                return normalize(r)
        if self.op is Op.COMPLEX and other.op in (Op.INTEGER, Op.REAL):
            return self * as_complex(other)
        elif other.op is Op.COMPLEX and self.op in (Op.INTEGER, Op.REAL):
            return as_complex(self) * other
        elif self.op is Op.REAL and other.op is Op.INTEGER:
            return self * as_real(other, kind=self.data[1])
        elif self.op is Op.INTEGER and other.op is Op.REAL:
            return as_real(self, kind=other.data[1]) * other
        if self.op is Op.TERMS:
            return self * as_terms(other)
        elif other.op is Op.TERMS:
            return as_terms(self) * other
        return as_factors(self) * as_factors(other)
    return NotImplemented

def _get_argspec_for_partial(obj):
    """Implements `getargspec` for `functools.partial` objects.

  Args:
    obj: The `functools.partial` object
  Returns:
    An `inspect.ArgSpec`
  Raises:
    ValueError: When callable's signature can not be expressed with
      ArgSpec.
  """
    n_prune_args = len(obj.args)
    partial_keywords = obj.keywords or {}
    (args, varargs, keywords, defaults) = getargspec(obj.func)
    args = args[n_prune_args:]
    no_default = object()
    all_defaults = [no_default] * len(args)
    if defaults:
        all_defaults[-len(defaults):] = defaults
    for (kw, default) in partial_keywords.items():
        if kw in args:
            idx = args.index(kw)
            all_defaults[idx] = default
        elif not keywords:
            raise ValueError('Function does not have **kwargs parameter, but contains an unknown partial keyword.')
    first_default = next((idx for (idx, x) in enumerate(all_defaults) if x is not no_default), None)
    if first_default is None:
        return ArgSpec(args, varargs, keywords, None)
    invalid_default_values = [args[i] for (i, j) in enumerate(all_defaults) if j is no_default and i > first_default]
    if <MASK>:
        raise ValueError('Some arguments %s do not have default value, but they are positioned after those with default values. This can not be expressed with ArgSpec.' % invalid_default_values)
    return ArgSpec(args, varargs, keywords, tuple(all_defaults[first_default:]))

def gen_transitive_closure(dep_graph: DepGraph, root_ops: list[str], train: bool=False) -> list[str]:
    result = set(root_ops)
    queue = root_ops.copy()
    queue.append('__BASE__')
    if train:
        queue.append('__ROOT__')
    while queue:
        cur = queue.pop()
        for dep in dep_graph.get(cur, []):
            if <MASK>:
                result.add(dep)
                queue.append(dep)
    return sorted(result)

def pin_min_versions_to_yaml_file(yaml_map: dict[str, list[str] | None], toml_map: dict[str, str], yaml_file_data: str) -> str:
    data = yaml_file_data
    for (yaml_package, yaml_versions) in yaml_map.items():
        old_dep = yaml_package
        if <MASK>:
            old_dep = old_dep + ', '.join(yaml_versions)
        if CONDA_TO_PIP.get(yaml_package, yaml_package) in toml_map:
            min_dep = toml_map[CONDA_TO_PIP.get(yaml_package, yaml_package)]
        elif yaml_package in toml_map:
            min_dep = toml_map[yaml_package]
        else:
            continue
        if yaml_versions is None:
            new_dep = old_dep + '>=' + min_dep
            data = data.replace(old_dep, new_dep, 1)
            continue
        toml_version = version.parse(min_dep)
        yaml_versions_list = clean_version_list(yaml_versions, toml_version)
        cleaned_yaml_versions = [x for x in yaml_versions_list if '-' not in x]
        new_dep = yaml_package
        for clean_yaml_version in cleaned_yaml_versions:
            new_dep += clean_yaml_version + ', '
        operator = get_operator_from(new_dep)
        if operator != '=':
            new_dep += '>=' + min_dep
        else:
            new_dep = new_dep[:-2]
        data = data.replace(old_dep, new_dep)
    return data

def tag_activation_checkpoint_impl(gmod, *args, **kwargs):
    import torch.fx.traceback as fx_traceback
    from torch.fx import Interpreter
    if <MASK>:
        warning_once(log, '\nDetected that context_fn is passed to torch.utils.checkpoint under torch.compile.\nPlease make sure the checkpointed region does not contain in-place ops (e.g. torch.relu_).\n')
        kwargs['use_reentrant'] = False
        kwargs['preserve_rng_state'] = False
        kwargs['context_fn'] = gmod.meta['_checkpoint_context_fn']
        gmod = TagActivationCheckpoint.tag_nodes(gmod, is_sac=True)
        with fx_traceback.preserve_node_meta():
            from torch.utils.checkpoint import checkpoint
            return checkpoint(Interpreter(gmod).run, *args, **kwargs)
    else:
        gmod = TagActivationCheckpoint.tag_nodes(gmod, is_sac=False)
        with fx_traceback.preserve_node_meta():
            return Interpreter(gmod).run(*args)

def _rfft_wrapper(fft_fn, fft_rank, default_name):
    """Wrapper around gen_spectral_ops.rfft* that infers fft_length argument."""

    def _rfft(input_tensor, fft_length=None, name=None):
        """Wrapper around gen_spectral_ops.rfft* that infers fft_length argument."""
        with _ops.name_scope(name, default_name, [input_tensor, fft_length]) as name:
            input_tensor = _ops.convert_to_tensor(input_tensor, preferred_dtype=_dtypes.float32)
            if input_tensor.dtype not in (_dtypes.float32, _dtypes.float64):
                raise ValueError('RFFT requires tf.float32 or tf.float64 inputs, got: %s' % input_tensor)
            real_dtype = input_tensor.dtype
            if real_dtype == _dtypes.float32:
                complex_dtype = _dtypes.complex64
            else:
                assert real_dtype == _dtypes.float64
                complex_dtype = _dtypes.complex128
            input_tensor.shape.with_rank_at_least(fft_rank)
            if fft_length is None:
                fft_length = _infer_fft_length_for_rfft(input_tensor, fft_rank)
            else:
                fft_length = _ops.convert_to_tensor(fft_length, _dtypes.int32)
            input_tensor = _maybe_pad_for_rfft(input_tensor, fft_rank, fft_length)
            fft_length_static = _tensor_util.constant_value(fft_length)
            if <MASK>:
                fft_length = fft_length_static
            return fft_fn(input_tensor, fft_length, Tcomplex=complex_dtype, name=name)
    if fft_fn.__doc__ is not None:
        _rfft.__doc__ = re.sub('    Tcomplex.*?\n', '', fft_fn.__doc__)
    return _rfft

@classmethod
@functools.cache
def create(cls, device) -> DeviceProperties:
    import torch
    from torch._dynamo.device_interface import get_interface_for_device
    device_type = device.type
    if torch.version.hip and device_type == 'cuda':
        device_type = 'hip'
    device_interface = get_interface_for_device(device)
    props = device_interface.get_device_properties(device)
    try:
        multi_processor_count = props.multi_processor_count
    except AttributeError:
        if device_type == 'xpu':
            multi_processor_count = props.gpu_subslice_count
        elif <MASK>:
            multi_processor_count = 64
        else:
            raise
    return cls(type=device_type, index=device.index, multi_processor_count=multi_processor_count, cc=device_interface.get_compute_capability(device), major=getattr(props, 'major', None), regs_per_multiprocessor=getattr(props, 'regs_per_multiprocessor', None), max_threads_per_multi_processor=getattr(props, 'max_threads_per_multi_processor', None), warp_size=getattr(props, 'warp_size', 32 if device_type != 'cpu' else None))

def load_f2cmap_file(f2cmap_file):
    global f2cmap_all, f2cmap_mapped
    f2cmap_all = copy.deepcopy(f2cmap_default)
    if <MASK>:
        f2cmap_file = '.f2py_f2cmap'
        if not os.path.isfile(f2cmap_file):
            return
    try:
        outmess(f'Reading f2cmap from {f2cmap_file!r} ...\n')
        with open(f2cmap_file) as f:
            d = eval(f.read().lower(), {}, {})
        (f2cmap_all, f2cmap_mapped) = process_f2cmap_dict(f2cmap_all, d, c2py_map, True)
        outmess('Successfully applied user defined f2cmap changes\n')
    except Exception as msg:
        errmess(f'Failed to apply user defined f2cmap changes: {msg}. Skipping.\n')

