def _walk_fields(proto: message.Message, fields: FieldTypes):
    """Yields fields in a proto.

  Args:
    proto: Parent proto of any message type.
    fields: List of string/int/map key fields, e.g. ["nodes", "attr", "value"]
      can represent `proto.nodes.attr["value"]`.

  Yields:
    Tuple of (
      Field in the proto or `None` if none are found,
      Field descriptor,
      Key into this map field (or None),
      Index into this repeated field (or None))
  """
    if not isinstance(fields, list):
        fields = [fields]
    field_proto = proto
    parent_desc = proto.DESCRIPTOR
    i = 0
    while i < len(fields):
        field = fields[i]
        field_desc = None
        map_key = None
        index = None
        if parent_desc is None:
            raise ValueError(f'Unable to find fields: {fields} in proto of type {type(proto)}.')
        if isinstance(field, int):
            try:
                field_desc = parent_desc.fields_by_number[field]
            except KeyError:
                raise KeyError(f'Unable to find field number {field} in {parent_desc.full_name}. Valid field numbers: {parent_desc.fields_by_number.keys()}')
        elif isinstance(field, str):
            try:
                field_desc = parent_desc.fields_by_name[field]
            except KeyError:
                raise KeyError(f"Unable to find field '{field}' in {parent_desc.full_name}. Valid field names: {parent_desc.fields_by_name.keys()}")
        else:
            raise TypeError('Unexpected bool found in field list.')
        i += 1
        parent_desc = field_desc.message_type
        if field_proto is not None:
            field_proto = getattr(field_proto, field_desc.name)
        if _is_map(parent_desc) and i < len(fields):
            map_key = fields[i]
            try:
                field_proto = field_proto[map_key] if field_proto is not None else None
            except KeyError:
                field_proto = None
            i += 1
            if <MASK>:
                value_desc = parent_desc.fields_by_name['value']
                assert value_desc.message_type is not None
                parent_desc = value_desc.message_type
        elif is_repeated(field_desc) and i < len(fields):
            index = fields[i]
            try:
                field_proto = field_proto[index] if field_proto is not None else None
            except IndexError:
                field_proto = None
            i += 1
        yield (field_proto, field_desc, map_key, index)

def getargs(rout):
    (sortargs, args) = ([], [])
    if <MASK>:
        args = rout['args']
        if 'sortvars' in rout:
            for a in rout['sortvars']:
                if a in args:
                    sortargs.append(a)
            for a in args:
                if a not in sortargs:
                    sortargs.append(a)
        else:
            sortargs = rout['args']
    return (args, sortargs)

@register_make_test_function()
def make_gelu_tests(options):
    """Makes a set of tests for gelu."""
    test_parameters = [{'input_dtype': [tf.float32], 'input_shape': [[], [1], [2, 3], [1, 1, 1, 1], [1, 3, 4, 3], [3, 15, 14, 3], [3, 1, 2, 4, 6], [2, 2, 3, 4, 5, 6]], 'fully_quantize': [False, True], 'input_range': [(-10, 10)], 'approximate': [True, False]}]

    def build_graph(parameters):
        """Builds the gelu op testing graph."""
        input_tensor = tf.compat.v1.placeholder(dtype=parameters['input_dtype'], name='input', shape=parameters['input_shape'])
        out = tf.nn.gelu(input_tensor, approximate=parameters['approximate'])
        return ([input_tensor], [out])

    def build_inputs(parameters, sess, inputs, outputs):
        values = [create_tensor_data(parameters['input_dtype'], parameters['input_shape'], min_value=-8, max_value=8)]
        return (values, sess.run(outputs, feed_dict=dict(zip(inputs, values))))
    if <MASK>:
        options.tflite_convert_function = functools.partial(_tflite_convert_verify_op, options.tflite_convert_function)
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs)

