def greedy_knapsack(memory: list[float], runtimes: list[float], max_memory: float) -> tuple[float, list[int], list[int]]:
    n = len(runtimes)
    items = list(range(n))
    items = sorted(items, key=lambda i: runtimes[i] / memory[i], reverse=True)
    total_memory = 0.0
    total_runtime = 0.0
    items_to_save = []
    items_to_allow_recomputing = []
    for i in items:
        if <MASK>:
            total_memory += memory[i]
            total_runtime += runtimes[i]
            items_to_save.append(i)
        else:
            items_to_allow_recomputing.append(i)
    return (total_runtime, items_to_save, items_to_allow_recomputing)

def _generate_sym_node(self, s: Union[int, sympy.Expr]) -> Union[int, torch.fx.Node]:
    if isinstance(s, (int, sympy.Integer)):
        return int(s)
    elif <MASK>:
        assert s in self.expr_to_proxy, f'Could not find a node corresponding to the symbol {s}'
        return self.expr_to_proxy[s].node
    elif isinstance(s, sympy.Expr):
        return self._sympy_interp(s).node
    elif isinstance(s, torch.fx.Node):
        return s
    else:
        raise ValueError(f'{s} of type {type(s)} is not a valid input')

