def wrap_type(to_patch: Any, pattern: type, __torch_function__: Callable) -> None:
    wrap_method = _py_wrap_method
    all: dict[str, Any] = {}
    for t in reversed(pattern.mro()[:-1]):
        all.update(t.__dict__)

    def wrap_attr(orig: Any) -> property:
        return property(wrap_method(orig.__get__, __torch_function__))
    for (name, obj) in all.items():
        if name in ('__dict__', '__new__', '__init__', '__repr__', '__weakref__', '__doc__', '__module__', '__dir__'):
            continue
        if hasattr(to_patch, name) and getattr(to_patch, name) is not getattr(object, name, None):
            continue
        if isinstance(obj, FUNC_TYPES):
            setattr(to_patch, name, wrap_method(obj, __torch_function__))
        elif <MASK>:
            setattr(to_patch, name, wrap_attr(obj))

def _ready_to_schedule(action: Optional[_Action]) -> bool:
    if action is None:
        return True
    stage_idx = action.stage_index
    prev_ops = _prev_ops_rank[stage_to_rank(stage_idx)]
    if action.computation_type == F:
        if action.stage_index == 0:
            return True
        elif _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_ops:
            return True
        elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_ops:
            return True
        return False
    elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
        if action.stage_index == num_stages - 1:
            return True
        if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_ops:
            return True
        if <MASK>:
            return True
        if _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_ops:
            return True
        return False
    elif action.computation_type == BACKWARD_WEIGHT:
        return True
    elif action.computation_type == SEND_F:
        expected_f = _Action(action.stage_index, F, action.microbatch_index)
        return expected_f in prev_ops
    elif action.computation_type == RECV_F:
        peer_stage_idx = stage_idx - 1
        expected_send = _Action(peer_stage_idx, SEND_F, action.microbatch_index)
        return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
    elif action.computation_type == SEND_B:
        expected_b = _Action(action.stage_index, BACKWARD_INPUT, action.microbatch_index)
        expected_bw = _Action(action.stage_index, FULL_BACKWARD, action.microbatch_index)
        return expected_b in prev_ops or expected_bw in prev_ops
    elif action.computation_type == RECV_B:
        peer_stage_idx = stage_idx + 1
        expected_send = _Action(peer_stage_idx, SEND_B, action.microbatch_index)
        return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
    else:
        raise ValueError(f'Unsupported action type {action}')

def as_string(self):
    """Return a string of the file contents."""
    items = {'replaces_str': '', 'initial_str': '', 'run_before_str': '', 'atomic_str': ''}
    imports = set()
    operations = []
    for operation in self.migration.operations:
        (operation_string, operation_imports) = OperationWriter(operation).serialize()
        imports.update(operation_imports)
        operations.append(operation_string)
    items['operations'] = '\n'.join(operations) + '\n' if operations else ''
    dependencies = []
    for dependency in self.migration.dependencies:
        if dependency[0] == '__setting__':
            dependencies.append('        migrations.swappable_dependency(settings.%s),' % dependency[1])
            imports.add('from django.conf import settings')
        else:
            dependencies.append('        %s,' % self.serialize(dependency)[0])
    items['dependencies'] = '\n'.join(sorted(dependencies)) + '\n' if dependencies else ''
    migration_imports = set()
    for line in list(imports):
        if <MASK>:
            migration_imports.add(line.split('import')[1].strip())
            imports.remove(line)
            self.needs_manual_porting = True
    if 'from django.db import models' in imports:
        imports.discard('from django.db import models')
        imports.add('from django.db import migrations, models')
    else:
        imports.add('from django.db import migrations')
    sorted_imports = sorted(imports, key=lambda i: (i.split()[0] == 'from', i.split()[1]))
    items['imports'] = '\n'.join(sorted_imports) + '\n' if imports else ''
    if migration_imports:
        items['imports'] += '\n\n# Functions from the following migrations need manual copying.\n# Move them and any dependencies into this file, then update the\n# RunPython operations to refer to the local versions:\n# %s' % '\n# '.join(sorted(migration_imports))
    if self.migration.replaces:
        items['replaces_str'] = '\n    replaces = %s\n' % self.serialize(self.migration.replaces)[0]
    if self.migration.run_before:
        items['run_before_str'] = '\n    run_before = %s\n' % self.serialize(self.migration.run_before)[0]
    if self.include_header:
        items['migration_header'] = MIGRATION_HEADER_TEMPLATE % {'version': get_version(), 'timestamp': now().strftime('%Y-%m-%d %H:%M')}
    else:
        items['migration_header'] = ''
    if self.migration.initial:
        items['initial_str'] = '\n    initial = True\n'
    if not self.migration.atomic:
        items['atomic_str'] = '\n    atomic = False\n'
    return MIGRATION_TEMPLATE % items

def test_nested_fn_backprop(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')
    weight = variables.Variable(2.0, trainable=True)

    @def_function.function(input_signature=[tensor_spec.TensorSpec(dtype=dtypes.float32, shape=(None, None))])
    def g(x):
        weight.read_value()
        handle = array_ops.identity(weight.handle)

        @def_function.function
        def launder_var_handle():
            return array_ops.identity(handle)
        return x + resource_variable_ops.read_variable_op(launder_var_handle(), dtypes.float32)
    root = autotrackable.AutoTrackable()
    root.weight = weight
    root.g = g
    imported = cycle(root, cycles, use_cpp_bindings=use_cpp_bindings)

    def get_gradient(obj, persistent):
        with backprop.GradientTape(persistent=persistent) as t:
            x = constant_op.constant([[1.0, 2.0, 3.0], [1.0, -2, 3.0]])
            y = obj.g(x)
            self.assertAllClose(y, obj.weight + x)
            loss = math_ops.reduce_sum(y)
            return t.gradient(loss, obj.weight)
    imported_gradient = get_gradient(imported, persistent=False)
    original_gradient = get_gradient(root, persistent=False)
    self.assertIsNotNone(original_gradient)
    self.assertAllClose(original_gradient, 6.0)
    self.assertIsNotNone(imported_gradient)
    self.assertAllClose(imported_gradient, 6.0)

def broadcast_dynamic_shape_extended(a: DynamicRaggedShape, b: DynamicRaggedShape):
    """Gets the smallest shape to which a and b can broadcast.

  In order to create the smallest shape, one must also do most of the
  work to figure out how to transform from the shapes given. Thus, in addition
  to returning the shape, it also creates transformations from the
  original shapes to the result.

  This is the equivalent of:

  c = broadcast_dynamic_shape(a, b)
  ac = get_broadcaster(a, c)
  bc = get_broadcaster(b, c)
  return (c, ac, bc)

  Args:
    a: a DynamicRaggedShape
    b: a DynamicRaggedShape

  Returns:
    A triple of a shape and two broadcasters.
  """
    if a.row_partitions and b.row_partitions:
        if a.dtype != b.dtype:
            raise ValueError("Dtypes don't match")
    elif a.dtype != b.dtype:
        if a.row_partitions:
            b = b.with_dtype(a.dtype)
        elif b.row_partitions:
            a = a.with_dtype(b.dtype)
        else:
            a = a.with_dtype(dtypes.int64)
            b = b.with_dtype(dtypes.int64)
    if a.rank is None or b.rank is None:
        raise ValueError('Unable to broadcast: unknown rank')
    elif a.rank == 0:
        return (b, _Broadcaster(a, b, []), _get_identity_broadcaster(b))
    elif <MASK>:
        return (a, _get_identity_broadcaster(a), _Broadcaster(b, a, []))
    elif a.rank == 1 and b.rank == 1:
        [a_layer, b_layer, target] = _broadcast_dynamic_shape_one_layer(a.inner_shape, b.inner_shape)
        target_shape = DynamicRaggedShape._from_inner_shape(target)
        return (target_shape, _Broadcaster(a, target_shape, [a_layer]), _Broadcaster(b, target_shape, [b_layer]))
    if a.rank > b.rank:
        (c, bc, ac) = _broadcast_dynamic_shape_extended_helper(b, a)
        return (c, ac, bc)
    return _broadcast_dynamic_shape_extended_helper(a, b)

