def _queue_slot_variables(checkpoint_position, visit_queue):
    """Queues slot variables for restoration."""
    trackable = checkpoint_position.trackable
    checkpoint = checkpoint_position.checkpoint
    for deferred_slot_restoration in checkpoint.deferred_slot_restorations.pop(checkpoint_position.proto_id, ()):
        (slot_variable_position, slot_variable) = checkpoint_position.create_slot_variable_position(trackable, deferred_slot_restoration.original_variable, deferred_slot_restoration.slot_variable_id, deferred_slot_restoration.slot_name, checkpoint_position.callback if checkpoint_position.has_non_trivial_reshard_callback() else None)
        if <MASK>:
            visit_queue.append((slot_variable_position, slot_variable))
    for slot_restoration in checkpoint.slot_restorations.pop(checkpoint_position.proto_id, ()):
        optimizer_object = checkpoint.object_by_proto_id.get(slot_restoration.optimizer_id, None)
        if optimizer_object is None:
            checkpoint.deferred_slot_restorations.setdefault(slot_restoration.optimizer_id, []).append(_DeferredSlotVariableRestoration(original_variable=trackable, slot_variable_id=slot_restoration.slot_variable_id, slot_name=slot_restoration.slot_name))
        elif hasattr(optimizer_object, '_create_or_restore_slot_variable'):
            (slot_variable_position, slot_variable) = checkpoint_position.create_slot_variable_position(optimizer_object, trackable, slot_restoration.slot_variable_id, slot_restoration.slot_name, checkpoint_position.callback if checkpoint_position.has_non_trivial_reshard_callback() else None)
            if slot_variable_position is not None:
                visit_queue.append((slot_variable_position, slot_variable))

def callback(self, op_type, inputs, attrs, outputs, op_name=None, graph=None):
    """Eager-function unified callback for checking numerics."""
    del attrs, op_name
    op_type_bytes = compat.as_bytes(op_type)
    is_v1_graph_mode = not ops.executing_eagerly_outside_functions()
    if op_type_bytes in op_callbacks_common.OP_CALLBACK_SKIP_OPS or op_type_bytes in SAFE_OPS:
        return None
    if graph:
        instrumented_outputs = []
        if <MASK>:
            for input_tensor in inputs:
                if input_tensor in self._placeholder_to_debug_tensor and outputs:
                    outputs[0].op._add_control_input(self._placeholder_to_debug_tensor[input_tensor].op)
        for (slot, output) in enumerate(outputs):
            if output.dtype.is_floating and (op_type_bytes, slot) not in IGNORE_OP_OUTPUTS:
                checked_output = array_ops.check_numerics_v2(output if is_v1_graph_mode else _debug_summary(output), get_check_numerics_error_message(slot, len(outputs), op_type, output, inputs, graph=graph, traceback=output.op.traceback, stack_height_limit=self._stack_height_limit, path_length_limit=self._path_length_limit))
                _CHECK_NUMERICS_INPUT_LOOKUP[graph][checked_output.name] = output
                instrumented_outputs.append(self._get_output_tensor(op_type_bytes, output, checked_output, is_v1_graph_mode))
            else:
                instrumented_outputs.append(output)
        return instrumented_outputs
    else:
        if op_type_bytes == b'CheckNumericsV2':
            return None
        for (slot, output) in enumerate(outputs):
            if output.dtype.is_floating and (op_type_bytes, slot) not in IGNORE_OP_OUTPUTS:
                array_ops.check_numerics_v2(output, get_check_numerics_error_message(slot, len(outputs), op_type, output, inputs, stack_height_limit=self._stack_height_limit, path_length_limit=self._path_length_limit))

def _rank(self, *, axis: AxisInt=0, method: str='average', na_option: str='keep', ascending: bool=True, pct: bool=False):
    if axis != 0 or self.ndim != 1:
        raise NotImplementedError
    from pandas.core.arrays import FloatingArray
    data = self._data
    if <MASK>:
        data = data.view('uint8')
    result = libalgos.rank_1d(data, is_datetimelike=False, ties_method=method, ascending=ascending, na_option=na_option, pct=pct, mask=self.isna())
    if na_option in ['top', 'bottom']:
        mask = np.zeros(self.shape, dtype=bool)
    else:
        mask = self._mask.copy()
    if method != 'average' and (not pct):
        if na_option not in ['top', 'bottom']:
            result[self._mask] = 0
        result = result.astype('uint64', copy=False)
        from pandas.core.arrays import IntegerArray
        return IntegerArray(result, mask=mask)
    return FloatingArray(result, mask=mask)

def __init__(self, obj: NDFrame, com: float | None=None, span: float | None=None, halflife: float | TimedeltaConvertibleTypes | None=None, alpha: float | None=None, min_periods: int | None=0, adjust: bool=True, ignore_na: bool=False, times: np.ndarray | NDFrame | None=None, method: str='single', *, selection=None) -> None:
    super().__init__(obj=obj, min_periods=1 if min_periods is None else max(int(min_periods), 1), on=None, center=False, closed=None, method=method, selection=selection)
    self.com = com
    self.span = span
    self.halflife = halflife
    self.alpha = alpha
    self.adjust = adjust
    self.ignore_na = ignore_na
    self.times = times
    if self.times is not None:
        times_dtype = getattr(self.times, 'dtype', None)
        if not (is_datetime64_dtype(times_dtype) or isinstance(times_dtype, DatetimeTZDtype)):
            raise ValueError('times must be datetime64 dtype.')
        if <MASK>:
            raise ValueError('times must be the same length as the object.')
        if not isinstance(self.halflife, (str, datetime.timedelta, np.timedelta64)):
            raise ValueError('halflife must be a timedelta convertible object')
        if isna(self.times).any():
            raise ValueError('Cannot convert NaT values to integer')
        self._deltas = _calculate_deltas(self.times, self.halflife)
        if common.count_not_none(self.com, self.span, self.alpha) > 0:
            if not self.adjust:
                raise NotImplementedError('None of com, span, or alpha can be specified if times is provided and adjust=False')
            self._com = get_center_of_mass(self.com, self.span, None, self.alpha)
        else:
            self._com = 1.0
    else:
        if self.halflife is not None and isinstance(self.halflife, (str, datetime.timedelta, np.timedelta64)):
            raise ValueError('halflife can only be a timedelta convertible argument if times is not None.')
        self._deltas = np.ones(max(self.obj.shape[0] - 1, 0), dtype=np.float64)
        self._com = get_center_of_mass(self.com, self.span, self.halflife, self.alpha)

