def post_backward(self, *unused: Any):
    if not compiled_autograd_enabled():
        logger.debug('%s', self._with_fqn('FSDP::post_backward'))
    self._training_state = TrainingState.POST_BACKWARD
    with record_function(self._with_fqn('FSDP::post_backward_accumulate')):
        for fsdp_param in self.fsdp_params:
            fsdp_param.accumulate_unsharded_grad_if_needed()
    with record_function(self._with_fqn('FSDP::post_backward_reshard')):
        if not self.reduce_grads:
            if self.reshard_after_backward:
                self.reshard()
            for fsdp_param in self.fsdp_params:
                fsdp_param.to_accumulated_grad_if_needed()
            return
        fsdp_params_with_grad: list[FSDPParam] = []
        unsharded_grads: list[torch.Tensor] = []
        for fsdp_param in self.fsdp_params:
            if not hasattr(fsdp_param, '_unsharded_param'):
                continue
            if fsdp_param.unsharded_accumulated_grad is not None:
                fsdp_params_with_grad.append(fsdp_param)
                unsharded_grads.append(fsdp_param.unsharded_accumulated_grad_data)
                fsdp_param.unsharded_accumulated_grad = None
            elif fsdp_param.unsharded_param.grad is not None:
                fsdp_params_with_grad.append(fsdp_param)
                unsharded_grads.append(fsdp_param.unsharded_grad_data)
                fsdp_param.unsharded_param.grad = None
        if self.reshard_after_backward:
            self.reshard()
    if len(fsdp_params_with_grad) == 0:
        return
    with record_function(self._with_fqn('FSDP::post_backward_reduce')):
        if self.comm_ctx.reduce_scatter_state is not None and self.comm_ctx.reduce_scatter_state.event is not None:
            self.device_handle.current_stream().wait_event(self.comm_ctx.reduce_scatter_state.event)
        self.comm_ctx.reduce_scatter_state = None
        all_reduce_pg = self._all_reduce_process_group if self._is_hsdp else None
        all_reduce_stream: torch.cuda.Stream
        if <MASK>:
            if self._all_reduce_hook is None:
                raise AssertionError('all reduce hook stream is specified but hook itself is missing.')
            all_reduce_stream = self._all_reduce_hook_stream
        else:
            all_reduce_stream = self.comm_ctx.all_reduce_stream
        self._wait_for_post_backward()
        (reduce_scatter_input, reduce_scatter_event, self._post_reduce_event, all_reduce_input, all_reduce_event, self._partial_reduce_output) = foreach_reduce(fsdp_params_with_grad, unsharded_grads, self._reduce_scatter_process_group, self.comm_ctx.reduce_scatter_stream, self._reduce_scatter_comm, self._orig_dtype, self._reduce_dtype, self.device, self.gradient_divide_factor, self._all_reduce_process_group if self._is_hsdp else None, all_reduce_stream, self.all_reduce_grads, self._partial_reduce_output, self._all_reduce_hook, self.force_sum_reduction_for_comms)
        self.comm_ctx.reduce_scatter_state = ReduceScatterState(reduce_scatter_input, reduce_scatter_event)
        if all_reduce_input is not None:
            if self.device.type != 'cpu':
                if all_reduce_event is None:
                    raise AssertionError('Expected all_reduce_event to be set for non-CPU device')
            self._all_reduce_state = AllReduceState(all_reduce_input, all_reduce_event)

def _broadcast_state_dict(full_state_dict: dict[str, Any], local_state_dict: dict[str, Any], device: torch.device, pg: Optional[dist.ProcessGroup]=None, strict: bool=False, cpu_offload: bool=False) -> None:
    ret = {}
    if <MASK>:
        for (key, value) in full_state_dict.items():
            if not torch.is_tensor(value):
                ret[key] = value
            elif value.dim() == 0:
                ret[key] = value.cpu()
            else:
                ret[key] = _TensorInfo(value.size(), value.dtype)
    broadcast_list = [ret]
    dist.broadcast_object_list(broadcast_list, src=0, group=pg)
    ret = broadcast_list[0]
    keys = []
    local_state_dict_keys = set(local_state_dict.keys())
    global_keys = set()
    for (key, value) in ret.items():
        global_keys.add(key)
        if not isinstance(value, _TensorInfo):
            if key in local_state_dict:
                local_state_dict[key] = value
            continue
        if dist.get_rank() == 0:
            ret[key] = full_state_dict[key]
        keys.append(key)
        if len(keys) >= 1:
            _broadcast_tensors(ret, local_state_dict, keys, device, pg)
            if cpu_offload:
                for key in keys:
                    local_state_dict[key] = local_state_dict[key].cpu()
            keys.clear()
    if strict:
        if (missing_keys := (local_state_dict_keys - global_keys)):
            for key in missing_keys:
                local_state_dict.pop(key)
    if keys:
        _broadcast_tensors(ret, local_state_dict, keys, device, pg)
        if cpu_offload:
            for key in keys:
                local_state_dict[key] = local_state_dict[key].cpu()

@classmethod
@count
def __torch_dispatch__(cls, func: OpOverload, types: Sequence[type], args: Sequence[object]=(), kwargs: Mapping[str, object]=immutable_dict()) -> object:
    if func == torch.ops.prim.device.default:
        assert len(args) == 1 and isinstance(args[0], FakeTensor)
        if args[0].fake_mode.in_kernel_invocation:
            return torch.device('meta')
        else:
            return args[0].fake_device
    if (handler := _DISPATCH_META_HANDLERS.get(func)):
        return handler(args)
    unrecognized_types = [t for t in types if not issubclass(t, FakeTensor) and t is not Tensor]
    if <MASK>:
        not_implemented_log.debug('FakeTensor unrecognized subclass(es): %s', unrecognized_types)
        return NotImplemented
    fake_mode = None
    for arg in pytree.arg_tree_leaves(*args, **kwargs):
        if isinstance(arg, FakeTensor):
            fake_mode = arg.fake_mode
            break
    assert fake_mode is not None
    maybe_cur_fake_mode = torch._C._get_dispatch_mode(torch._C._TorchDispatchModeKey.FAKE)
    if maybe_cur_fake_mode:
        not_implemented_log.debug('FakeTensor mode already active: %s in %s', fake_mode, maybe_cur_fake_mode)
        return NotImplemented
    assert not fake_mode.in_kernel_invocation
    with fake_mode:
        return func(*args, **kwargs)

def _get_nn_functional_ops():
    functions = []
    mod = torch.nn.functional
    name = mod.__name__
    for elem in dir(torch.nn.functional):
        attr = getattr(mod, elem)
        if not inspect.isfunction(attr) or _hidden(elem[0]):
            continue
        attr_module = inspect.getmodule(attr)
        if not attr_module:
            raise RuntimeError(f'Module for {attr} not found')
        if <MASK>:
            continue
        try:
            scripted = torch.jit.script(attr)
            scripted_schema = scripted.schema
            functions.append(_emit_schema(name, elem, scripted_schema))
        except:
            pass
    for mod in torch.jit._builtins._modules_containing_builtins:
        name = mod.__name__
        for elem in dir(mod):
            builtin = _find_builtin(getattr(mod, elem))
            if builtin is not None:
                schemas = torch._C._jit_get_schemas_for_operator(builtin)
                for schema in schemas:
                    if not _hidden(elem):
                        functions.append(_emit_schema(name, elem, schema))
    return ('Supported PyTorch Functions', functions)

def __new__(cls, *args, **kargs):
    self = super().__new__(cls)

    def wrap(func):

        def wrapper(*args, **kwargs):
            scalars = [arg for arg in args if isinstance(arg, (int, sympy.Expr)) or (isinstance(arg, CppCSEVariable) and (not arg.is_vec))]
            vectors = [arg for arg in args if isinstance(arg, CppCSEVariable) and arg.is_vec]
            new_args = list(args)
            if scalars and vectors:
                new_args = []
                for arg in args:
                    if isinstance(arg, (int, sympy.Expr)):
                        if <MASK>:
                            arg = ops.index_expr(arg, torch.int64)
                        else:
                            arg = ops.constant(arg, torch.int64)
                        arg = arg.value if isinstance(arg, OpsValue) else arg
                    new_args.append(arg)
            if vectors:
                if len(new_args) == 2:
                    new_args = promote_args(new_args)
                elif func == CppVecOverrides.where:
                    new_args[1:] = promote_args(new_args[1:])
            if scalars and vectors:
                assert isinstance(V.kernel, CppVecKernel)
                new_args = [V.kernel.broadcast(new_arg) if isinstance(new_arg, CppCSEVariable) and (not new_arg.is_vec) and (func not in [CppVecOverrides.rand, CppVecOverrides.randn, CppVecOverrides.randint64]) else new_arg for new_arg in new_args]
            if vectors:
                return func(*new_args, **kwargs)
            else:
                scalar_ops = super(CppVecOverrides, self)
                scalar_func = getattr(scalar_ops, func.__name__)
                assert scalar_func is not None
                return scalar_func(*args, **kwargs)
        return wrapper
    for (name, method) in vars(CppVecOverrides).items():
        if getattr(method, '__class__', None) is staticmethod and name not in ['masked', 'index_expr']:
            setattr(self, name, wrap(method.__func__))
    return self

@impl(quantized_decomposed_lib, 'quantize_per_tensor.tensor', 'Meta')
def quantize_per_tensor_tensor_meta(input: torch.Tensor, scale: torch.Tensor, zero_point: torch.Tensor, quant_min: int, quant_max: int, dtype: torch.dtype) -> torch.Tensor:
    if <MASK>:
        input = input.to(torch.float32)
    assert zero_point.numel() == 1, f'Expecting zero_point tensor to be one element, but received : {zero_point.numel()}'
    assert scale.numel() == 1, f'Expecting scale tensor to be one element, but received : {scale.numel()}'
    assert input.dtype == torch.float32, f'Expecting input to have dtype torch.float32, but got dtype: {input.dtype}'
    return torch.empty_like(input, dtype=dtype)

def dense_size_list(self) -> list[str]:
    sizes = ['1'] * self.triton_tensor_ndim()
    for tree in self.range_trees:
        if <MASK>:
