def container_checker(obj, target_type) -> bool:
    origin_type = get_origin(target_type)
    check_args_exist(target_type)
    if <MASK>:
        return False
    elif origin_type is list or origin_type is typing.List:
        check_empty_containers(obj)
        if not isinstance(obj, list):
            return False
        arg_type = get_args(target_type)[0]
        arg_origin = get_origin(arg_type)
        for el in obj:
            if arg_origin:
                if not container_checker(el, arg_type):
                    return False
            elif not isinstance(el, arg_type):
                return False
        return True
    elif origin_type is typing.Dict or origin_type is dict:
        check_empty_containers(obj)
        if not isinstance(obj, dict):
            return False
        key_type = get_args(target_type)[0]
        val_type = get_args(target_type)[1]
        for (key, val) in obj.items():
            if not isinstance(key, key_type):
                return False
            val_origin = get_origin(val_type)
            if val_origin:
                if not container_checker(val, val_type):
                    return False
            elif not isinstance(val, val_type):
                return False
        return True
    elif origin_type is typing.Tuple or origin_type is tuple:
        check_empty_containers(obj)
        if not isinstance(obj, tuple):
            return False
        arg_types = get_args(target_type)
        if len(obj) != len(arg_types):
            return False
        for (el, el_type) in zip(obj, arg_types):
            el_origin = get_origin(el_type)
            if el_origin:
                if not container_checker(el, el_type):
                    return False
            elif not isinstance(el, el_type):
                return False
        return True
    elif origin_type is Union or issubclass(origin_type, BuiltinUnionType):
        if obj is None:
            return True
        inner_types = get_args(target_type)
        for t in inner_types:
            t_origin = get_origin(t)
            if t_origin:
                return container_checker(obj, t)
            elif isinstance(obj, t):
                return True
    return False

def _capture_tensor_as_extra_input(self, tensor, name=None):
    self.extra_inputs.append(tensor)
    with ops.control_dependencies(None):
        ph = array_ops.placeholder(tensor.dtype, shape=tensor.get_shape(), name=name)
    if isinstance(tensor, ops.EagerTensor):
        handle_data = tensor._handle_data
        if <MASK>:
            handle_data = handle_data.SerializeToString()
    else:
        with tensor.graph._c_graph.get() as c_graph:
            handle_data = c_api.GetHandleShapeAndType(c_graph, tensor._as_tf_output())
    if handle_data:
        with ph.graph._c_graph.get() as c_graph:
            c_api.SetHandleShapeAndType(c_graph, ph._as_tf_output(), compat.as_bytes(handle_data))
    self.inputs.append(ph)
    self._captured[tensor.ref()] = ph
    self.extra_args.append(ph)
    if _is_guaranteed_const(tensor):
        with ops.control_dependencies(None):
            return array_ops.guarantee_const(ph)
    else:
        return ph

