@_onnx_symbolic('aten::index')
def index(g: jit_utils.GraphContext, self, index):
    if symbolic_helper._is_packed_list(index):
        indices = symbolic_helper._unpack_list(index)
    else:
        indices = [index]

    def try_mask_to_index(index):
        if not symbolic_helper._is_none(index) and (_type_utils.JitScalarType.from_value(index, _type_utils.JitScalarType.UNDEFINED) == _type_utils.JitScalarType.UINT8 or symbolic_helper._is_bool(index)):
            if <MASK>:
                raise errors.SymbolicValueError('Exporting masked indices are only supported after ONNX opset 9.', self)
            warnings.warn('Exporting aten::index operator with indices of type Byte. Only 1-D indices are supported. In any other case, this will produce an incorrect ONNX graph.')
            index = symbolic_helper._squeeze_helper(g, nonzero(g, index), [1])
        return index
    indices = [try_mask_to_index(idx) for idx in indices]
    if len(indices) == 1:
        return symbolic_helper._select_helper(g, self, 0, indices[0], apply_reshape=False)
    else:
        adv_idx_indices = [i for (i, idx) in enumerate(indices) if not symbolic_helper._is_none(idx)]
        if len(adv_idx_indices) == 0:
            return self
        elif len(adv_idx_indices) == 1:
            return index_select(g, self, adv_idx_indices[0], indices[adv_idx_indices[0]])
        else:
            rank = symbolic_helper._get_tensor_rank(self)
            if rank is None:
                return symbolic_helper._unimplemented('aten::index', 'operator of advanced indexing on tensor of unknown rank. ', self)
            warnings.warn(f'Exporting aten::index operator of advanced indexing in opset {GLOBALS.export_onnx_opset_version} is achieved by combination of multiple ONNX operators, including Reshape, Transpose, Concat, and Gather. If indices include negative values, the exported graph will produce incorrect results.')
            adv_idx_count = len(adv_idx_indices)
            shape_tensor = _shape_as_tensor(g, self)
            dim_tensor_list = [g.op('Gather', shape_tensor, g.op('Constant', value_t=torch.LongTensor([dim])), axis_i=0) for dim in range(rank)]
            self = g.op('Transpose', self, perm_i=adv_idx_indices + [i for i in range(rank) if i not in adv_idx_indices])
            self = g.op('Flatten', self, axis_i=adv_idx_count)
            cum_adv_index = indices[adv_idx_indices[-1]]
            multiplier = dim_tensor_list[adv_idx_indices[-1]]
            for i in range(adv_idx_count - 2, -1, -1):
                adv_index = g.op('Mul', indices[adv_idx_indices[i]], multiplier)
                cum_adv_index = g.op('Add', cum_adv_index, adv_index)
                multiplier = g.op('Mul', multiplier, dim_tensor_list[adv_idx_indices[i]])
            self = index_select(g, self, 0, cum_adv_index)
            cum_adv_index_shape_tensor = _shape_as_tensor(g, cum_adv_index)
            if adv_idx_indices == list(range(adv_idx_indices[0], adv_idx_indices[-1] + 1)):
                folded_adv_idx_shape_list = [g.op('Constant', value_t=torch.LongTensor([-1]))] + [dim_tensor_list[i] for i in range(rank) if i not in adv_idx_indices]
                folded_adv_idx_shape = g.op('Concat', *folded_adv_idx_shape_list, axis_i=0)
                self = symbolic_helper._reshape_helper(g, self, folded_adv_idx_shape)
                adv_idx_permute = list(range(1, adv_idx_indices[0] + 1)) + [0] + list(range(adv_idx_indices[0] + 1, rank - adv_idx_count + 1))
                self = g.op('Transpose', self, perm_i=adv_idx_permute)
                final_shape_list = [dim_tensor_list[i] for i in range(adv_idx_indices[0])] + [cum_adv_index_shape_tensor] + [dim_tensor_list[i] for i in range(adv_idx_indices[0], rank) if i not in adv_idx_indices]
                final_shape = g.op('Concat', *final_shape_list, axis_i=0)
            else:
                final_shape = g.op('Concat', cum_adv_index_shape_tensor, *[dim_tensor_list[i] for i in range(rank) if i not in adv_idx_indices], axis_i=0)
            return symbolic_helper._reshape_helper(g, self, final_shape)

def __repr__(self):
    extra_lines = []
    extra_repr = self.extra_repr()
    if extra_repr:
        extra_lines = extra_repr.split('\n')
    child_lines = []
    for (key, module) in self._modules.items():
        if isinstance(module, (PackedParameter, nn.ModuleList)):
            continue
        mod_str = repr(module)
        mod_str = nn.modules.module._addindent(mod_str, 2)
        child_lines.append('(' + key + '): ' + mod_str)
    lines = extra_lines + child_lines
    main_str = self._get_name() + '('
    if <MASK>:
        if len(extra_lines) == 1 and (not child_lines):
            main_str += extra_lines[0]
        else:
            main_str += '\n  ' + '\n  '.join(lines) + '\n'
    main_str += ')'
    return main_str

def _max_pool1d(input: Tensor, kernel_size: BroadcastingList1[int], stride: Optional[BroadcastingList1[int]]=None, padding: BroadcastingList1[int]=0, dilation: BroadcastingList1[int]=1, ceil_mode: bool=False, return_indices: bool=False) -> Tensor:
    if <MASK>:
        return handle_torch_function(max_pool1d, (input,), input, kernel_size, stride=stride, padding=padding, dilation=dilation, ceil_mode=ceil_mode, return_indices=return_indices)
    if stride is None:
        stride = torch.jit.annotate(list[int], [])
    return torch.max_pool1d(input, kernel_size, stride, padding, dilation, ceil_mode)

def get_matching_overload(node: torch.fx.Node, overloads: Sequence[_registration.OnnxDecompMeta]) -> tuple[Callable | None, str]:
    """Get the overload that matches the node's arguments.

    Args:
        node: The node to match.
        overloads: The OnnxDecompMeta with overloads and their signatures to match against.

    Returns:
        A tuple containing the matched overload and a string describing the reason for failure or success.
    """
    if not hasattr(node.target, '_schema'):
        return (overloads[0].onnx_function, 'The node target does not have a schema. Return the first one.')
    named_args = _get_named_fx_node_args(node)
    schema_args: dict[str, torch.Argument] = {arg.name: arg for arg in node.target._schema.arguments}
    failure_messages: list[str] = []
    for overload in overloads:
        assigned_types: dict[str, ir.TypeProtocol] = {}
        fail_reason = ''
        if overload.signature is None:
            return (overload.onnx_function, 'The overload does not have a signature. Assuming it is a custom op and matching it.')
        for param in overload.signature:
            if param.name not in schema_args and param.required:
                fail_reason = 'Required parameter not supplied'
                break
            if param.name in named_args:
                arg = named_args[param.name]
            elif param.name in schema_args and schema_args[param.name].has_default_value():
                arg = schema_args[param.name].default_value
            elif param.has_default():
                arg = param.default
            else:
                fail_reason = 'Parameter not provided'
                break
            if <MASK>:
                if isinstance(arg, torch.Tensor):
                    arg = _get_type_from_tensor(arg)
                if isinstance(arg, (list, tuple)) and any((isinstance(t, torch.fx.Node) for t in arg)):
                    first_tensor = _get_first_tensor_in_node_list(arg)
                    assert first_tensor is not None
                    arg = ir.SequenceType(_get_type_from_tensor(first_tensor))
                elif isinstance(arg, torch.fx.Node):
                    meta_val = arg.meta['val']
                    arg = _get_type_from_tensor(meta_val)
                if not _param_type_compatible_with_arg(param, arg, assigned_types):
                    fail_reason = f'Parameter type not compatible with argument: param=`{param}`, assigned_types=`{assigned_types}`, arg=`{arg}`'
                    break
            elif isinstance(param, _schemas.AttributeParameter):
                if not _attribute_type_compatible_with_arg(param, arg):
                    fail_reason = f'Attribute type not compatible with argument: param=`{param}`, arg=`{arg}`'
                    break
            else:
                raise TypeError(f'Unknown parameter type: {type(param)}')
        if not fail_reason:
            return (overload.onnx_function, 'Successfully matched overload')
        else:
            failure_messages.append(f'- Failed to match overload `{overload}`: {fail_reason}')
    return (None, f'All overloads did not match the node `{node.format_node()}`.\n' + '\n'.join(failure_messages))

def __init__(self, remote_device: Union[str, torch.device]):
    PARSE_ERROR = f"Could not parse remote_device: {remote_device}. The valid format is '<workername>/<device>' or 'rank:<rank>/<device>' or '<device>'"
    self._worker_name = None
    self._rank = None
    self._device: Optional[Union[str, int, torch.device]] = None
    if isinstance(remote_device, torch.device):
        self._device = remote_device
    elif isinstance(remote_device, str):
        fields = remote_device.split('/')
        if len(fields) == 2:
            (self._worker_name, self._device) = fields
        elif len(fields) == 1:
            if _remote_device._is_valid_local_device(fields[0]):
                self._device = fields[0]
            else:
                self._worker_name = fields[0]
                self._device = 'cpu'
        else:
            raise ValueError(PARSE_ERROR)
    else:
        raise TypeError(f'Invalid type for remote_device: {type(remote_device)}')
    if <MASK>:
        raise ValueError(PARSE_ERROR)
    self._device = torch.device(self._device)
    if self._worker_name is not None:
        fields = self._worker_name.split(':')
        if len(fields) == 2:
            if fields[0] == 'rank' and fields[1].isdigit():
                self._rank = int(fields[1])
                self._worker_name = None
            else:
                raise ValueError(PARSE_ERROR)
        elif len(fields) > 2:
            raise ValueError(PARSE_ERROR)

def get_cell(self, *labels):
