def with_appcontext(f: F) -> F:
    """Wraps a callback so that it's guaranteed to be executed with the
    script's application context.

    Custom commands (and their options) registered under ``app.cli`` or
    ``blueprint.cli`` will always have an app context available, this
    decorator is not required in that case.

    .. versionchanged:: 2.2
        The app context is active for subcommands as well as the
        decorated callback. The app context is always available to
        ``app.cli`` command and parameter callbacks.
    """

    @click.pass_context
    def decorator(ctx: click.Context, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
        if <MASK>:
            app = ctx.ensure_object(ScriptInfo).load_app()
            ctx.with_resource(app.app_context())
        return ctx.invoke(f, *args, **kwargs)
    return update_wrapper(decorator, f)

def visit_Subscript(self, node):
    (val, ty) = self.visit(node.value)
    type_ = self._get_inferred_type(node.value, ty)
    s = node.slice
    if not isinstance(s, (ast.Tuple, ast.Slice)):
        if <MASK>:
            idx_val = self._ssa_name('cst')
            self._emit_with_loc('\n{} = arith.constant {} : index'.format(idx_val, s.value), node)
        else:
            (idx_val, _) = self.visit(s)
    else:
        raise NotImplementedError('non-index slice not supported.')
    elt = self._ssa_name('elt')
    if type_ == TFRTypes.TENSOR_LIST:
        self.emit('\n{} = tfr.get_element {}[{}] '.format(elt, val, idx_val))
        self._emit_with_loc(': (!tfr.tensor_list, index) -> !tfr.tensor', node)
        return (elt, TFRTypes.TENSOR)
    elif type_ == TFRTypes.TF_TENSOR_SHAPE_LIST:
        size_ = self._ssa_name('size')
        self.emit('\n{} = shape.get_extent {}, {}'.format(size_, val, idx_val))
        self._emit_with_loc(': !shape.shape, index -> !shape.size', node)
        self._emit_with_loc('\n{} = shape.size_to_index {} : !shape.size'.format(elt, size_), node)
        return (elt, TFRTypes.INDEX)

def lookup_field(name, obj, model_admin=None):
    opts = obj._meta
    try:
        f = _get_non_gfk_field(opts, name)
    except (FieldDoesNotExist, FieldIsAForeignKeyColumnName):
        if callable(name):
            attr = name
            value = attr(obj)
        elif hasattr(model_admin, name) and name != '__str__':
            attr = getattr(model_admin, name)
            value = attr(obj)
        else:
            sentinel = object()
            attr = getattr(obj, name, sentinel)
            if callable(attr):
                value = attr()
            else:
                if <MASK>:
                    attr = obj
                    for part in name.split(LOOKUP_SEP):
                        attr = getattr(attr, part, sentinel)
                        if attr is sentinel:
                            return (None, None, None)
                value = attr
            if hasattr(model_admin, 'model') and hasattr(model_admin.model, name):
                attr = getattr(model_admin.model, name)
        f = None
    else:
        attr = None
        value = getattr(obj, name)
    return (f, attr, value)

def fill_bool(x, left=None):
    if x.dtype.kind in 'cfO':
        mask = isna(x)
        if mask.any():
            x = x.astype(object)
            x[mask] = False
    if <MASK>:
        x = x.astype(bool)
    return x

@classmethod
def index_expr(cls, expr, dtype):
    indexing = V.kernel.indexing(expr, block_ptr=False, tma_compatibility_checker=None)
    assert isinstance(indexing, IndexingOptions)
    shape: BlockShapeType
    if indexing.expand_shape:
        shape = indexing.expand_shape
    else:
        shape = TritonSymbols.get_block_shape(indexing.index)
    index_dtype = V.kernel.get_index_dtype_as_torch_dtype()
    dtype = dtype if dtype not in (torch.int32, torch.int64) else index_dtype
    orig = config.test_configs.runtime_triton_dtype_assert
    try:
        config.test_configs.runtime_triton_dtype_assert = False
        var = V.kernel.cse.generate(V.kernel.compute, indexing.index_str, bounds=get_bounds_index_expr(expr), dtype=dtype, shape=shape)
    finally:
        config.test_configs.runtime_triton_dtype_assert = orig
    if dtype not in (torch.int32, torch.int64):
        var = V.kernel.cse.generate(V.kernel.compute, cls.to_dtype(var, dtype), dtype=upcast_compute_type(dtype), shape=var.shape)
    else:
        dtype = index_dtype
        for index_var in expr.free_symbols:
            if symbol_is_type(index_var, SymT.TMP):
                dtype = torch.promote_types(dtype, V.kernel.cse.varname_map[index_var.name].dtype)
        if <MASK>:
            var = V.kernel.cse.generate(V.kernel.compute, cls.to_dtype(var, index_dtype), dtype=index_dtype, shape=var.shape)
    var.mask_vars = indexing.mask_vars
    return var

def can_ignore(self, node):
    """Returns True if the node can safely be assumed not to touch variables."""
    ast_node = node.ast_node
    if <MASK>:
        return True
    return isinstance(ast_node, (gast.Break, gast.Continue, gast.Raise, gast.Pass))

def _ConvertGraphV1(self, output_saved_model_dir=None, need_calibration=False, max_batch_size=1, minimum_segment_size=3, is_dynamic_op=False, maximum_cached_engines=1, device=None):
    """Helper method to convert a GraphDef or SavedModel using TF-TRT."""
    input_saved_model_dir = None
    if output_saved_model_dir:
        input_saved_model_dir = self.mkdtemp()
        self._WriteInputSavedModelForV1(input_saved_model_dir, device)
    if <MASK>:
        is_dynamic_op = True
    if is_dynamic_op:
        max_batch_size = None
    converter = trt_convert.TrtGraphConverter(input_saved_model_dir=input_saved_model_dir, input_saved_model_signature_key=_SAVED_MODEL_SIGNATURE_KEY, input_graph_def=None if input_saved_model_dir else self._GetGraphDefForV1(device), nodes_denylist=None if input_saved_model_dir else ['output'], max_batch_size=max_batch_size, max_workspace_size_bytes=TrtConvertTest._TRT_MAX_WORKSPACE_SIZE_BYTES, precision_mode=trt_convert.TrtPrecisionMode.INT8 if need_calibration else trt_convert.TrtPrecisionMode.FP32, minimum_segment_size=minimum_segment_size, is_dynamic_op=is_dynamic_op, maximum_cached_engines=maximum_cached_engines)
    output_graph_def = converter.convert()
    if need_calibration:

        class CalibrationData(object):

            def __init__(self):
                self._data = 0

            def next(self):
                self._data += 1
                return {'input1:0': [[[self._data]]], 'input2:0': [[[self._data]]]}
        output_graph_def = converter.calibrate(fetch_names=['output:0'], num_runs=10, feed_dict_fn=CalibrationData().next)
    if output_saved_model_dir is not None:
        converter.save(output_saved_model_dir=output_saved_model_dir)
    return output_graph_def

def sample(self, state):
    if <MASK>:
        return self._loguniform(state)
    if self._distribution == 'uniform':
        return self._uniform(state)
    if isinstance(self._distribution, dict):
        return self._custom_distribution(state)

def handle(self, **options):
    db = options['database']
    include_stale_apps = options['include_stale_apps']
    interactive = options['interactive']
    verbosity = options['verbosity']
    if not router.allow_migrate_model(db, ContentType):
        return
    ContentType.objects.clear_cache()
    apps_content_types = itertools.groupby(ContentType.objects.using(db).order_by('app_label', 'model'), lambda obj: obj.app_label)
    for (app_label, content_types) in apps_content_types:
        if not include_stale_apps and app_label not in apps.app_configs:
            continue
        to_remove = [ct for ct in content_types if ct.model_class() is None]
        using = router.db_for_write(ContentType)
        if <MASK>:
            if interactive:
                ct_info = []
                for ct in to_remove:
                    ct_info.append('    - Content type for %s.%s' % (ct.app_label, ct.model))
                    collector = Collector(using=using, origin=ct, force_collection=True)
                    collector.collect([ct])
                    for (obj_type, objs) in collector.data.items():
                        if objs != {ct}:
                            ct_info.append('    - %s %s object(s)' % (len(objs), obj_type._meta.label))
                content_type_display = '\n'.join(ct_info)
                self.stdout.write(f"Some content types in your database are stale and can be deleted.\nAny objects that depend on these content types will also be deleted.\nThe content types and dependent objects that would be deleted are:\n\n{content_type_display}\n\nThis list doesn't include any cascade deletions to data outside of Django\nmodels (uncommon).\n\nAre you sure you want to delete these content types?\nIf you're unsure, answer 'no'.")
                ok_to_delete = input("Type 'yes' to continue, or 'no' to cancel: ")
            else:
                ok_to_delete = 'yes'
            if ok_to_delete == 'yes':
                for ct in to_remove:
                    if verbosity >= 2:
                        self.stdout.write("Deleting stale content type '%s | %s'" % (ct.app_label, ct.model))
                    ct.delete()
            elif verbosity >= 2:
                self.stdout.write('Stale content types remain.')

def drop_removed_buffers(self, lines):
    """
        Replace any memory planning lines in V.graph.removed_buffers with NullLine
        """
    for (i, line) in enumerate(lines):
        if isinstance(line, (AllocateLine, FreeIfNotReusedLine, ReuseLine)):
            if <MASK>:
                lines[i] = NullLine(self.wrapper)

@register_lowering(aten.scatter_reduce_, type_promotion_kind=None)
def scatter_reduce_(self, dim: int, index, src, reduce, *, include_self: bool=True):
    assert reduce in (None, 'sum', 'prod', 'mean', 'amax', 'amin')
    assert len(aten.scatter_reduce_.overloads()) == 1 and 'two' in aten.scatter_reduce_.overloads(), 'aten.scatter_reduce_.two is not the unique overload of aten.scatter_reduce_'
    if <MASK>:
        src = full_like(self, src)
    fallback_result = scatter_fallback(aten.scatter_reduce_.two, self, dim, index, src, reduce=reduce, include_self=include_self)
    if fallback_result:
        return fallback_result
    assert isinstance(self, TensorBox)
    assert 'int' in str(index.get_dtype())
    ndim = len(self.get_size())
    if ndim == 0:
        self = view(self, [1])
    if isinstance(src, TensorBox) and len(src.get_size()) == 0:
        src = view(src, [1])
    if isinstance(index, TensorBox) and len(index.get_size()) == 0:
        index = view(index, [1])
    if index.get_numel() == 0:
        return self
    dim = _validate_dim(self, dim)
    self.realize()
    index_loader = index.make_loader()
    src_loader = src.make_loader() if isinstance(src, TensorBox) else None

    def output_indexer(idx):
        shape = self.get_size()
        ndim = len(shape)
        indirect_idx = list(idx)
        indirect_idx[dim] = ops.indirect_indexing(index_loader(idx), 1 if ndim == 0 else shape[dim], wrap_neg=False)
        return indirect_idx

    def fn(idx):
        if src_loader:
            return src_loader(idx)
        else:
            return ops.constant(src, self.get_dtype())

    def backend_reduce_str(reduce):
        if reduce == 'sum':
            return 'atomic_add'
        else:
            assert reduce is None
            return None
    device = self.get_device()
    assert device is not None
    if not include_self:
        zero_out = ir.Scatter(device=device, dtype=self.get_dtype(), inner_fn=lambda index: ops.constant(0, self.get_dtype()), ranges=index.get_size(), output_indexer=output_indexer, scatter_mode=None)
        buffer = ir.ComputedBuffer(name=None, layout=ir.MutationLayoutSHOULDREMOVE(self), data=zero_out)
        buffer.name = V.graph.register_buffer(buffer)
        V.graph.register_operation(buffer)
    scatter = ir.Scatter(device=device, dtype=self.get_dtype(), inner_fn=fn, ranges=index.get_size(), output_indexer=output_indexer, scatter_mode=backend_reduce_str(reduce))
    buffer = ir.ComputedBuffer(name=None, layout=ir.MutationLayoutSHOULDREMOVE(self), data=scatter)
    buffer.name = V.graph.register_buffer(buffer)
    V.graph.register_operation(buffer)
    if ndim == 0:
        self = view(self, [])
    return self

@staticmethod
def create(tx: 'InstructionTranslator', value) -> VariableTracker:
    value_type = type(value)
    fast_handler = SourcelessBuilder._type_handlers.get(value_type)
    if fast_handler:
        return fast_handler(tx, value)
    if isinstance(value, VariableTracker):
        return value
    elif isinstance(value, dataclasses._HAS_DEFAULT_FACTORY_CLASS):
        return UserDefinedObjectVariable(value)
    elif ConstantVariable.is_literal(value):
        return ConstantVariable.create(value)
    elif callable(value) and trace_rules.lookup_callable(value) is not None:
        if trace_rules.is_callable_allowed(value):
            tx.output.has_user_defined_allowed_in_graph = True
        return trace_rules.lookup_callable(value)(value)
    elif callable(value) and UserDefinedClassVariable.is_supported_new_method(value):
        obj = trace_rules.lookup_callable(value.__self__)(value.__self__)
        return GetAttrVariable(obj, '__new__')
    elif is_function_or_wrapper(value):
        return trace_rules.lookup(value)(value)
    elif isinstance(value, (enum.Enum, torch.DispatchKey, torch._C._functorch.TransformType)):
        return EnumVariable(value)
    elif isinstance(value, (type, abc.ABCMeta)):
        return UserDefinedClassVariable(value)
    elif isinstance(value, types.MethodWrapperType):
        return MethodWrapperVariable(value)
    elif isinstance(value, types.MethodType) and isinstance(value.__self__, (type, abc.ABCMeta)):
        assert getattr(value.__self__, value.__func__.__name__) == value
        cls_obj_vt = SourcelessBuilder.create(tx, value.__self__)
        try:
            return cls_obj_vt.var_getattr(tx, value.__func__.__name__)
        except NotImplementedError:
            pass
    elif isinstance(value, torch.fx.graph_module.GraphModule):
        return SourcelessGraphModuleVariable(value)
    elif isinstance(value, (torch.utils._pytree.TreeSpec, torch.utils._pytree.LeafSpec)):
        return UserDefinedObjectVariable(value)
    elif PlacementVariable.is_placement(value):
        return PlacementVariable(value)
    elif <MASK>:
        return DeviceMeshVariable(value)
    elif value is functools.wraps:
        return FunctoolsWrapsVariable(value)
    elif isinstance(value, re.Pattern):
        return RegexPatternVariable(value)
    elif isinstance(value, torch._dynamo.variables.lazy.LazySymNodeFormatString):
        return ConstantVariable.create(str(value))
    elif isinstance(value, type(torch._higher_order_ops.flex_attention_backward)):
        return torch._dynamo.variables.higher_order_ops.FlexAttentionBackwardHighOrderVariable(value)
    elif isinstance(value, types.GenericAlias):
        return TypingVariable(value)
    elif is_namedtuple(value):
        output = [SourcelessBuilder.create(tx, getattr(value, name)) for name in namedtuple_fields(type(value))]
        return NamedTupleVariable(output, tuple_cls=type(value))
    elif isinstance(value, torch.SymInt) and value.node.expr in tx.output.bound_symbols:
        proxy = tx.output.bound_symbols[value.node.expr]
        return SymNodeVariable.create(tx, proxy)
    unimplemented_v2(gb_type='Unexpected type in sourceless builder', context=f'{value_type.__module__}.{value_type.__qualname__}', explanation=f'SourcelessBuilder.create does not know how to wrap {value_type}', hints=[*graph_break_hints.DYNAMO_BUG])

def get_compile_id(frame_state: dict[str, Union[int, FrameStateSizeEntry]]) -> CompileId:
    global FRAME_COUNTER
    if '_id' not in frame_state:
        frame_state['_id'] = FRAME_COUNTER
        FRAME_COUNTER += 1
    frame_id = frame_state['_id']
    assert isinstance(frame_id, int)
    frame_compile_id = FRAME_COMPILE_COUNTER[frame_id]
    FRAME_COMPILE_COUNTER[frame_id] += 1
    compiled_autograd_id = None
    if <MASK>:
        compiled_autograd_id = prior.compiled_autograd_id
    return CompileId(compiled_autograd_id=compiled_autograd_id, frame_id=frame_id, frame_compile_id=frame_compile_id)

def __setstate__(self, state: dict[str, Any]) -> None:
    self.__dict__.update(state)
    if '_optimizer_step_pre_hooks' not in self.__dict__:
        self._optimizer_step_pre_hooks = OrderedDict()
    if '_optimizer_step_post_hooks' not in self.__dict__:
        self._optimizer_step_post_hooks = OrderedDict()
    if '_optimizer_state_dict_pre_hooks' not in self.__dict__:
        self._optimizer_state_dict_pre_hooks = OrderedDict()
    if '_optimizer_state_dict_post_hooks' not in self.__dict__:
        self._optimizer_state_dict_post_hooks = OrderedDict()
    if '_optimizer_load_state_dict_pre_hooks' not in self.__dict__:
        self._optimizer_load_state_dict_pre_hooks = OrderedDict()
    if <MASK>:
        self._optimizer_load_state_dict_post_hooks = OrderedDict()
    self._patch_step_function()
    self.defaults.setdefault('differentiable', False)

@staticmethod
def _find_common_device(func: OpOverload, flat_args: Sequence[object]) -> tuple[torch.device, bool]:
    common_device = None
    has_scalar_only_inputs = False
    is_cpu_zero_dim = None
    mixed_device_fns = ordered_set(aten._foreach_copy.default)
    bypass_zero_dim_cpu_tensor_check_ops = ordered_set(aten.nextafter.default)

    def check_cpu_device(device: torch.device) -> bool:
        return device.type == 'cpu'

    def cpu_zero_dim(t: Tensor) -> bool:
        return check_cpu_device(t.device) and t.dim() == 0

    def merge_devices(t: object) -> None:
        nonlocal common_device
        nonlocal is_cpu_zero_dim
        if not isinstance(t, FakeTensor):
            return
        if common_device is None:
            common_device = t.device
            is_cpu_zero_dim = cpu_zero_dim(t)
            return
        t_is_cpu_zero_dim = cpu_zero_dim(t)
        if t.device == common_device:
            if <MASK>:
                is_cpu_zero_dim = t_is_cpu_zero_dim
            return
        is_bypass_zero_dim_cpu_tensor_check_op = func in bypass_zero_dim_cpu_tensor_check_ops
        if t_is_cpu_zero_dim and (not is_bypass_zero_dim_cpu_tensor_check_op):
            return
        if is_cpu_zero_dim and (not is_bypass_zero_dim_cpu_tensor_check_op):
            common_device = t.device
            is_cpu_zero_dim = t_is_cpu_zero_dim
            return
        if func in mixed_device_fns:
            if any(map(check_cpu_device, (common_device, t.device))):
                return
        prefer_device_type = torch._functorch.config.fake_tensor_prefer_device_type
        if prefer_device_type is not None:
            common_has_preferred = prefer_device_type in common_device.type
            t_has_preferred = prefer_device_type in t.device.type
            if not common_has_preferred and t_has_preferred:
                common_device = t.device
                is_cpu_zero_dim = t_is_cpu_zero_dim
                return
            elif common_has_preferred and (not t_has_preferred):
                return
        raise RuntimeError(f'Unhandled FakeTensor Device Propagation for {func}, found two different devices {common_device}, {t.device}')
    for arg in flat_args:
        merge_devices(arg)
    if should_allow_numbers_as_tensors(func) and common_device is None:
        has_scalar_only_inputs = True
        common_device = torch.device('cpu')
    assert common_device is not None, f'Could not find common device for {func}'
    return (common_device, has_scalar_only_inputs)

def get_flag_value(self, wanted_flag_name):
    """Returns the value of a TensorTracer flags.

    Args:
      wanted_flag_name: the name of the flag we are looking for.

    Returns:
      A pair where the first element indicates if the flag is
      found and the second element is the value of the flag.

    Raises:
      RuntimeError: If supposedly deadcode is reached.
    """
    tensor_tracer_flags = self._env.get(FLAGS_ENV_VAR)
    if not tensor_tracer_flags:
        return (False, None)
    pos = 0
    while True:
        (match, has_value) = TTParameters.match_next_flag(tensor_tracer_flags, pos)
        if <MASK>:
            return (False, None)
        flag_name = match.group(1)
        if has_value:
            flag_value = match.group(2)
        else:
            flag_value = None
        if flag_name == wanted_flag_name:
            return (True, flag_value)
        pos = match.end()
    raise RuntimeError('Invalid tensor tracer flag. Could not recognize %s.' % flag_name)

@functools.wraps(fun)
def wrapper(*args, **kwargs):
    __tracebackhide__ = True
    for (old_name, new_name) in zip(old_names, new_names):
        if old_name in kwargs:
            if dep_version:
                end_version = dep_version.split('.')
                end_version[1] = str(int(end_version[1]) + 2)
                end_version = '.'.join(end_version)
                msg = f'Use of keyword argument `{old_name}` is deprecated and replaced by `{new_name}`. Support for `{old_name}` will be removed in NumPy {end_version}.'
                warnings.warn(msg, DeprecationWarning, stacklevel=2)
            if <MASK>:
                msg = f'{fun.__name__}() got multiple values for argument now known as `{new_name}`'
                raise TypeError(msg)
            kwargs[new_name] = kwargs.pop(old_name)
    return fun(*args, **kwargs)

@tf_utils.shape_type_conversion
def build(self, input_shape):
    if not isinstance(input_shape[0], tuple) or len(input_shape) != 2:
        raise ValueError('A `Dot` layer should be called on a list of 2 inputs.')
    shape1 = input_shape[0]
    shape2 = input_shape[1]
    if shape1 is None or shape2 is None:
        return
    if <MASK>:
        if self.axes < 0:
            axes = [self.axes % len(shape1), self.axes % len(shape2)]
        else:
            axes = [self.axes] * 2
    else:
        axes = self.axes
    if shape1[axes[0]] != shape2[axes[1]]:
        raise ValueError('Dimension incompatibility %s != %s. ' % (shape1[axes[0]], shape2[axes[1]]) + 'Layer shapes: %s, %s. ' % (shape1, shape2) + 'Chosen axes: %s, %s' % (axes[0], axes[1]))

def _log_epoch_metrics(self, epoch, logs):
    """Writes epoch metrics out as scalar summaries.

    Args:
        epoch: Int. The global step to use for TensorBoard.
        logs: Dict. Keys are scalar summary names, values are scalars.
    """
    if not logs:
        return
    train_logs = {k: v for (k, v) in logs.items() if not k.startswith('val_')}
    val_logs = {k: v for (k, v) in logs.items() if k.startswith('val_')}
    train_logs = self._collect_learning_rate(train_logs)
    if <MASK>:
        train_logs['steps_per_second'] = self._compute_steps_per_second()
    with summary_ops_v2.record_if(True):
        if train_logs:
            with self._train_writer.as_default():
                for (name, value) in train_logs.items():
                    summary_ops_v2.scalar('epoch_' + name, value, step=epoch)
        if val_logs:
            with self._val_writer.as_default():
                for (name, value) in val_logs.items():
                    name = name[4:]
                    summary_ops_v2.scalar('epoch_' + name, value, step=epoch)

def reduce_weighted_loss(weighted_losses, reduction=ReductionV2.SUM_OVER_BATCH_SIZE):
    """Reduces the individual weighted loss measurements."""
    if reduction == ReductionV2.NONE:
        loss = weighted_losses
    else:
        loss = math_ops.reduce_sum(weighted_losses)
        if <MASK>:
            loss = _safe_mean(loss, _num_elements(weighted_losses))
    return loss

@staticmethod
def _search_for_file(suffix: str, errmsg: str) -> str:
    spec = importlib.machinery.PathFinder.find_spec('halide')
    if spec is None or not spec.submodule_search_locations:
        raise RuntimeError('halide python bindings not installed')
    try:
        search = spec.submodule_search_locations[0]
        for file in os.listdir(search):
            if file.endswith('.so'):
                try:
                    out = subprocess.check_output(['ldd', os.path.join(search, file)])
                except subprocess.SubprocessError:
                    continue
                m = re.search('(/.*)/libHalide.so', out.decode('utf-8'))
                if m:
                    path = os.path.join(os.path.abspath(m.group(1)), suffix)
                    if <MASK>:
                        return os.path.abspath(path)
    except Exception as e:
        raise RuntimeError(errmsg) from e
    raise RuntimeError(errmsg)

@final
def _where(self, cond, other=lib.no_default, *, inplace: bool=False, axis: Axis | None=None, level=None) -> Self | None:
    """
        Equivalent to public method `where`, except that `other` is not
        applied as a function even if callable. Used in __setitem__.
        """
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if axis is not None:
        axis = self._get_axis_number(axis)
    cond = common.apply_if_callable(cond, self)
    if isinstance(cond, NDFrame):
        if cond.ndim == 1 and self.ndim == 2:
            cond = cond._constructor_expanddim(dict.fromkeys(range(len(self.columns)), cond), copy=False)
            cond.columns = self.columns
        cond = cond.align(self, join='right')[0]
    else:
        if not hasattr(cond, 'shape'):
            cond = np.asanyarray(cond)
        if cond.shape != self.shape:
            raise ValueError('Array conditional must be same shape as self')
        cond = self._constructor(cond, **self._construct_axes_dict(), copy=False)
    fill_value = bool(inplace)
    cond = cond.fillna(fill_value)
    cond = cond.infer_objects()
    msg = 'Boolean array expected for the condition, not {dtype}'
    if <MASK>:
        if not isinstance(cond, ABCDataFrame):
            if not is_bool_dtype(cond):
                raise TypeError(msg.format(dtype=cond.dtype))
        else:
            for block in cond._mgr.blocks:
                if not is_bool_dtype(block.dtype):
                    raise TypeError(msg.format(dtype=block.dtype))
            if cond._mgr.any_extension_types:
                cond = cond._constructor(cond.to_numpy(dtype=bool, na_value=fill_value), **cond._construct_axes_dict())
    else:
        cond = cond.astype(bool)
    cond = -cond if inplace else cond
    cond = cond.reindex(self._info_axis, axis=self._info_axis_number)
    if isinstance(other, NDFrame):
        if other.ndim <= self.ndim:
            other = self.align(other, join='left', axis=axis, level=level, fill_value=None)[1]
            if axis is None and (not other._indexed_same(self)):
                raise InvalidIndexError
            if other.ndim < self.ndim:
                other = other._values
                if isinstance(other, np.ndarray):
                    if axis == 0:
                        other = np.reshape(other, (-1, 1))
                    elif axis == 1:
                        other = np.reshape(other, (1, -1))
                    other = np.broadcast_to(other, self.shape)
                else:
                    if axis == 0:
                        res_cols = [self.iloc[:, i]._where(cond.iloc[:, i], other) for i in range(self.shape[1])]
                    elif axis == 1:
                        res_cols = [self.iloc[:, i]._where(cond.iloc[:, i], other[i:i + 1].repeat(len(self))) for i in range(self.shape[1])]
                    res = self._constructor(dict(enumerate(res_cols)))
                    res.index = self.index
                    res.columns = self.columns
                    if inplace:
                        return self._update_inplace(res)
                    return res.__finalize__(self)
        else:
            raise NotImplementedError('cannot align with a higher dimensional NDFrame')
    elif not isinstance(other, (MultiIndex, NDFrame)):
        other = extract_array(other, extract_numpy=True)
    if isinstance(other, (np.ndarray, ExtensionArray)):
        if other.shape != self.shape:
            if self.ndim != 1:
                raise ValueError('other must be the same shape as self when an ndarray')
        else:
            other = self._constructor(other, **self._construct_axes_dict(), copy=False)
    if axis is None:
        axis = 0
    if self.ndim == getattr(other, 'ndim', 0):
        align = True
    else:
        align = self._get_axis_number(axis) == 1
    if inplace:
        new_data = self._mgr.putmask(mask=cond, new=other, align=align)
        result = self._constructor_from_mgr(new_data, axes=new_data.axes)
        return self._update_inplace(result)
    else:
        new_data = self._mgr.where(other=other, cond=cond, align=align)
        result = self._constructor_from_mgr(new_data, axes=new_data.axes)
        return result.__finalize__(self)

def on_epoch_begin(self, epoch, logs=None):
    """Add histogram op to Model eval_function callbacks, reset batch count."""
    if self.histogram_freq and epoch % self.histogram_freq == 0:
        self.model._make_test_function()
