            self.model.test_function.fetch_callbacks[self.merged] = self._fetch_callback

def __init__(self, values: np.ndarray, mask: npt.NDArray[np.bool_], copy: bool=False) -> None:
    checker = self._dtype_cls._checker
    if not (isinstance(values, np.ndarray) and checker(values.dtype)):
        descr = 'floating' if self._dtype_cls.kind == 'f' else 'integer'
        raise TypeError(f"values should be {descr} numpy array. Use the 'pd.array' function instead")
    if <MASK>:
        raise TypeError('FloatingArray does not support np.float16 dtype.')
    super().__init__(values, mask, copy=copy)

@property
def metrics_names(self):
    """Returns the model's display labels for all outputs."""
    metrics_names = ['loss']
    if <MASK>:
        if not hasattr(self, '_v1_compile_was_called'):
            return super(Model, self).metrics_names
        if len(self._training_endpoints) > 1:
            metrics_names.extend([e.loss_name() for e in self._training_endpoints if not e.should_skip_target()])
    metrics_names += [m.name for m in self.metrics]
    return metrics_names

@dispatch.add_dispatch_support
@doc_controls.do_not_generate_docs
def switch(condition, then_expression, else_expression):
    """Switches between two operations depending on a scalar value.

  Note that both `then_expression` and `else_expression`
  should be symbolic tensors of the *same shape*.

  Args:
      condition: tensor (`int` or `bool`).
      then_expression: either a tensor, or a callable that returns a tensor.
      else_expression: either a tensor, or a callable that returns a tensor.

  Returns:
      The selected tensor.

  Raises:
      ValueError: If rank of `condition` is greater than rank of expressions.
  """
    if condition.dtype != dtypes_module.bool:
        condition = math_ops.cast(condition, 'bool')
    cond_ndim = ndim(condition)
    if not cond_ndim:
        if <MASK>:

            def then_expression_fn():
                return then_expression
        else:
            then_expression_fn = then_expression
        if not callable(else_expression):

            def else_expression_fn():
                return else_expression
        else:
            else_expression_fn = else_expression
        x = cond.cond(condition, then_expression_fn, else_expression_fn)
    else:
        if callable(then_expression):
            then_expression = then_expression()
        if callable(else_expression):
            else_expression = else_expression()
        expr_ndim = ndim(then_expression)
        if cond_ndim > expr_ndim:
            raise ValueError('Rank of `condition` should be less than or equal to rank of `then_expression` and `else_expression`. ndim(condition)=' + str(cond_ndim) + ', ndim(then_expression)=' + str(expr_ndim))
        if cond_ndim > 1:
            ndim_diff = expr_ndim - cond_ndim
            cond_shape = array_ops.concat([array_ops.shape(condition), [1] * ndim_diff], axis=0)
            condition = array_ops.reshape(condition, cond_shape)
            expr_shape = array_ops.shape(then_expression)
            shape_diff = expr_shape - cond_shape
            tile_shape = array_ops.where_v2(shape_diff > 0, expr_shape, array_ops.ones_like(expr_shape))
            condition = array_ops.tile(condition, tile_shape)
        x = array_ops.where_v2(condition, then_expression, else_expression)
    return x

def _check_device_methods(self, subnode: ast.Call, msg_prefix: str) -> None:
    func = subnode.func
    if not isinstance(func, ast.Attribute):
        return
    method_name = func.attr
    if method_name in DEVICE_BIAS:
        self.record(subnode, f'{msg_prefix} .{method_name}(), suggest to use .to(GPU_TYPE)')
    elif method_name == 'to' and subnode.args:
        arg = subnode.args[0]
        if <MASK>:
            self.record(subnode, f"{msg_prefix} .to('{arg.value}'), suggest to use .to(GPU_TYPE)")

def _has_sufficient_memory(device, size):
    device_ = torch.device(device)
    device_type = device_.type
    if <MASK>:
        acc = torch.accelerator.current_accelerator()
        if not acc:
            return False
        if acc.type != device_type:
            return True
        if not torch.accelerator.is_available():
            return False
        gc.collect()
        torch.accelerator.empty_cache()
        if device_.index is None:
            device_ = torch.device(device_type, 0)
        if device_type == 'cuda':
            return torch.cuda.memory.mem_get_info(device_)[0] * torch.cuda.memory.get_per_process_memory_fraction(device_) >= size
        if device_type == 'xpu':
            return torch.xpu.memory.mem_get_info(device_)[0] >= size
    if device_type == 'xla':
        raise unittest.SkipTest('TODO: Memory availability checks for XLA?')
    if device_type != 'cpu':
        raise unittest.SkipTest('Unknown device type')
    if not HAS_PSUTIL:
        raise unittest.SkipTest('Need psutil to determine if memory is sufficient')
    if TEST_WITH_ASAN or TEST_WITH_TSAN or TEST_WITH_UBSAN:
        effective_size = size * 10
    else:
        effective_size = size
    if IS_S390X:
        effective_size = effective_size * 2
    if psutil.virtual_memory().available < effective_size:
        gc.collect()
    return psutil.virtual_memory().available >= effective_size

def inject_url_defaults(self, endpoint: str, values: dict[str, t.Any]) -> None:
    """Injects the URL defaults for the given endpoint directly into
        the values dictionary passed.  This is used internally and
        automatically called on URL building.

        .. versionadded:: 0.7
        """
    names: t.Iterable[str | None] = (None,)
    if <MASK>:
        names = chain(names, reversed(_split_blueprint_path(endpoint.rpartition('.')[0])))
    for name in names:
        if name in self.url_default_functions:
            for func in self.url_default_functions[name]:
                func(endpoint, values)

def _parse_table_constraints(self, sql, columns):
    statement = sqlparse.parse(sql)[0]
    constraints = {}
    unnamed_constrains_index = 0
    tokens = (token for token in statement.flatten() if not token.is_whitespace)
    for token in tokens:
        if token.match(sqlparse.tokens.Punctuation, '('):
            break
    while True:
        (constraint_name, unique, check, end_token) = self._parse_column_or_constraint_definition(tokens, columns)
        if unique:
            if constraint_name:
                constraints[constraint_name] = unique
            else:
                unnamed_constrains_index += 1
                constraints['__unnamed_constraint_%s__' % unnamed_constrains_index] = unique
        if check:
            if constraint_name:
                constraints[constraint_name] = check
            else:
                unnamed_constrains_index += 1
                constraints['__unnamed_constraint_%s__' % unnamed_constrains_index] = check
        if <MASK>:
            break
    return constraints

def _fused_adam(params: list[Tensor], grads: list[Tensor], exp_avgs: list[Tensor], exp_avg_sqs: list[Tensor], max_exp_avg_sqs: list[Tensor], state_steps: list[Tensor], grad_scale: Optional[Tensor], found_inf: Optional[Tensor], *, amsgrad: bool, has_complex: bool, beta1: Union[float, Tensor], beta2: Union[float, Tensor], lr: Union[float, Tensor], weight_decay: float, eps: float, maximize: bool, capturable: bool, differentiable: bool, decoupled_weight_decay: bool) -> None:
    if not params:
        return
    if differentiable:
        raise RuntimeError('Adam with fused=True does not support differentiable=True')
    beta1 = _to_scalar(beta1)
    beta2 = _to_scalar(beta2)
    grad_scale_dict: DeviceDict = {grad_scale.device: grad_scale} if grad_scale is not None else {}
    found_inf_dict: DeviceDict = {found_inf.device: found_inf} if found_inf is not None else {}
    lr_dict: Optional[DeviceDict] = {lr.device: lr} if isinstance(lr, Tensor) and str(lr.device) != 'cpu' else None
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, exp_avgs, exp_avg_sqs, max_exp_avg_sqs, state_steps])
    for ((device, _), ((device_params_, device_grads_, device_exp_avgs_, device_exp_avg_sqs_, device_max_exp_avg_sqs, device_state_steps_), _)) in grouped_tensors.items():
        device_params = cast(list[Tensor], device_params_)
        device_grads = cast(list[Tensor], device_grads_)
        device_exp_avgs = cast(list[Tensor], device_exp_avgs_)
        device_exp_avg_sqs = cast(list[Tensor], device_exp_avg_sqs_)
        device_state_steps = cast(list[Tensor], device_state_steps_)
        (device_grad_scale, device_found_inf) = (None, None)
        if <MASK>:
            device_grad_scale = grad_scale_dict.setdefault(device, grad_scale.to(device, non_blocking=True))
        if found_inf is not None:
            device_found_inf = found_inf_dict.setdefault(device, found_inf.to(device, non_blocking=True))
        if lr_dict is not None and device not in lr_dict:
            lr_dict[device] = lr.to(device=device, non_blocking=True)
            lr = lr_dict[device]
        torch._foreach_add_(device_state_steps, 1)
        func = torch._fused_adam_ if not decoupled_weight_decay else torch._fused_adamw_
        func(device_params, device_grads, device_exp_avgs, device_exp_avg_sqs, device_max_exp_avg_sqs, device_state_steps, amsgrad=amsgrad, lr=lr, beta1=beta1, beta2=beta2, weight_decay=weight_decay, eps=eps, maximize=maximize, grad_scale=device_grad_scale, found_inf=device_found_inf)
        if device_found_inf is not None:
            torch._foreach_sub_(device_state_steps, [device_found_inf] * len(device_state_steps))

def _maybe_transform_eq_ne(self, node, left=None, right=None):
    if <MASK>:
        left = self.visit(node.left, side='left')
    if right is None:
        right = self.visit(node.right, side='right')
    (op, op_class, left, right) = self._rewrite_membership_op(node, left, right)
    return (op, op_class, left, right)

def step(self, metrics: SupportsFloat, epoch=None) -> None:
    """Perform a step."""
    current = float(metrics)
    if epoch is None:
        epoch = self.last_epoch + 1
    else:
        warnings.warn(EPOCH_DEPRECATION_WARNING, UserWarning)
    self.last_epoch = epoch
    if <MASK>:
        self.best = current
        self.num_bad_epochs = 0
    else:
        self.num_bad_epochs += 1
    if self.in_cooldown:
        self.cooldown_counter -= 1
        self.num_bad_epochs = 0
    if self.num_bad_epochs > self.patience:
        self._reduce_lr(epoch)
        self.cooldown_counter = self.cooldown
        self.num_bad_epochs = 0
    self._last_lr = _param_groups_val_list(self.optimizer, 'lr')

def __lt__(self, other):
    if <MASK>:
        return sympy.false
    elif other is S.NegativeIntInfinity:
        return sympy.false
    else:
        return sympy.true

def get_read_writes(self) -> dependencies.ReadWrites:
    read_writes = super().get_read_writes()
    if <MASK>:
        for arg in self.constant_args:
            if isinstance(arg, GeneratorState):
                read_writes = read_writes.with_read(dependencies.StarDep(arg.get_name()))
    return read_writes

def _clean_na_values(na_values, keep_default_na: bool=True, floatify: bool=True):
    na_fvalues: set | dict
    if na_values is None:
        if keep_default_na:
            na_values = STR_NA_VALUES
        else:
            na_values = set()
        na_fvalues = set()
    elif <MASK>:
        old_na_values = na_values.copy()
        na_values = {}
        for (k, v) in old_na_values.items():
            if not is_list_like(v):
                v = [v]
            if keep_default_na:
                v = set(v) | STR_NA_VALUES
            na_values[k] = _stringify_na_values(v, floatify)
        na_fvalues = {k: _floatify_na_values(v) for (k, v) in na_values.items()}
    else:
        if not is_list_like(na_values):
            na_values = [na_values]
        na_values = _stringify_na_values(na_values, floatify)
        if keep_default_na:
            na_values = na_values | STR_NA_VALUES
        na_fvalues = _floatify_na_values(na_values)
    return (na_values, na_fvalues)

def get_dim_argnames(self) -> tuple[Optional[str], Optional[str]]:
    if <MASK>:
        return (None, None)
    single_dim_argname = None
    dimlist_argname = None
    for overload in self.dim_args:
        if len(overload) != 1:
            continue
        if overload[0].endswith('...'):
            dimlist_argname = overload[0].replace('...', '')
            if single_dim_argname is None:
                single_dim_argname = dimlist_argname
        else:
            single_dim_argname = overload[0]
    return (single_dim_argname, dimlist_argname)

def _to_dot(self, graph_module: torch.fx.GraphModule, name: str, ignore_getattr: bool, ignore_parameters_and_buffers: bool, skip_node_names_in_args: bool, parse_stack_trace: bool) -> pydot.Dot:
    """
            Actual interface to visualize a fx.Graph. Note that it takes in the GraphModule instead of the Graph.
            If ignore_parameters_and_buffers is True, the parameters and buffers
            created with the module will not be added as nodes and edges.
            """
    dot_graph = pydot.Dot(name, rankdir='TB')
    buf_name_to_subgraph = {}
    for node in graph_module.graph.nodes:
        if <MASK>:
            continue
        style = self._get_node_style(node)
        dot_node = pydot.Node(node.name, label=self._get_node_label(graph_module, node, skip_node_names_in_args, parse_stack_trace), **style)
        current_graph = dot_graph
        buf_meta = node.meta.get('buf_meta', None)
        if buf_meta is not None and buf_meta.n_origin > 1:
            buf_name = buf_meta.name
            if buf_name not in buf_name_to_subgraph:
                buf_name_to_subgraph[buf_name] = pydot.Cluster(buf_name, label=buf_name)
            current_graph = buf_name_to_subgraph.get(buf_name)
        current_graph.add_node(dot_node)

        def get_module_params_or_buffers():
            for (pname, ptensor) in chain(leaf_module.named_parameters(), leaf_module.named_buffers()):
                pname1 = node.name + '.' + pname
                label1 = pname1 + '|op_code=get_' + 'parameter' if isinstance(ptensor, torch.nn.Parameter) else 'buffer' + '\\l'
                dot_w_node = pydot.Node(pname1, label='{' + label1 + self._get_tensor_label(ptensor) + '}', **_WEIGHT_TEMPLATE)
                dot_graph.add_node(dot_w_node)
                dot_graph.add_edge(pydot.Edge(pname1, node.name))
        if node.op == 'call_module':
            leaf_module = self._get_leaf_node(graph_module, node)
            if not ignore_parameters_and_buffers and (not isinstance(leaf_module, torch.fx.GraphModule)):
                get_module_params_or_buffers()
    for subgraph in buf_name_to_subgraph.values():
        subgraph.set('color', 'royalblue')
        subgraph.set('penwidth', '2')
        dot_graph.add_subgraph(subgraph)
    for node in graph_module.graph.nodes:
        if ignore_getattr and node.op == 'get_attr':
            continue
        for user in node.users:
            dot_graph.add_edge(pydot.Edge(node.name, user.name))
    return dot_graph

def check_file(filename: Optional[str], is_inlined_call: bool=False) -> SkipResult:
    """Should skip this file?"""
    if filename is None:
        return SkipResult(True, 'filename is None')
    filename = _as_posix_path(filename)
    if filename in FORCE_SKIP_FILES:
        return SkipResult(True, 'FORCE_SKIP_FILES')
    if any((filename.startswith(d) for d in get_legacy_mod_inlinelist())):
        return SkipResult(False, 'LEGACY_MOD_INLINELIST')
    if is_inlined_call and is_torch_inline_allowed(filename):
        return SkipResult(False, 'MOD_INLINELIST')
    if <MASK>:
        return SkipResult(True, 'FBCODE_SKIP_DIRS')
    if is_fbcode() and config.skip_torchrec and FBCODE_SKIP_TORCHREC_DIRS and bool(FBCODE_SKIP_TORCHREC_DIRS_RE.match(filename)) and (not bool(FBCODE_INLINE_FILES_IN_SKIPPED_DIRS_RE.match(filename))):
        return SkipResult(True, 'FBCODE_SKIP_TORCHREC_DIRS')
    unittest_dir = _module_dir(unittest)
    if unittest_dir is not None and filename.startswith(unittest_dir) and (not torch._dynamo.config.enable_trace_unittest):
        return SkipResult(True, 'unittest')
    if bool(SKIP_DIRS_RE.match(filename)):
        return SkipResult(True, 'SKIP_DIRS')
    if any((filename.startswith(d) for d in get_mod_skiplist())):
        return SkipResult(True, 'MOD_SKIPLIST')
    return SkipResult(False, 'inlined by default')

def _broadcast_tensors(full_state_dict: dict[str, Any], local_state_dict: dict[str, Any], keys: list[str], device: torch.device, pg: Optional[dist.ProcessGroup]=None) -> None:
    if pg is None:
        pg = dist.distributed_c10d._get_default_group()
    pg_device = device if device.type in {pg_device.type for pg_device in pg._device_types} else pg._device_types[0]
    tensors: list[torch.Tensor] = []
    for key in keys:
        if <MASK>:
            full_state = full_state_dict[key]
            assert isinstance(full_state, torch.Tensor)
            full_tensor = full_state.detach().to(pg_device)
        else:
            tensor_info = full_state_dict[key]
            full_tensor = torch.empty(size=tensor_info.size, device=pg_device, dtype=tensor_info.dtype)
        tensors.append(full_tensor)
        if (local_state := local_state_dict.get(key)) is None:
            continue
        local_state_dict[key] = (local_state, full_tensor) if isinstance(local_state, DTensor) else full_tensor
    if len(tensors) > 1:
        dist._broadcast_coalesced(pg, tensors, 500, 0)
    else:
        dist.broadcast(tensors[0], src=0, group=pg)
    if pg_device != device:
        for (key, full_tensor) in zip(keys, tensors):
            if (local_state := local_state_dict.get(key)) is not None:
                local_state_dict[key] = (local_state[0], full_tensor.to(device)) if isinstance(local_state, tuple) and isinstance(local_state[0], DTensor) else full_tensor.to(device)
    _distribute_tensors(local_state_dict, keys, device, pg)

def __getitem__(self, key):
    """
        Conserve RangeIndex type for scalar and slice keys.
        """
    key = lib.item_from_zerodim(key)
    if key is Ellipsis:
        key = slice(None)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    elif <MASK>:
        new_key = int(key)
        try:
            return self._range[new_key]
        except IndexError as err:
            raise IndexError(f'index {key} is out of bounds for axis 0 with size {len(self)}') from err
    elif is_scalar(key):
        raise IndexError('only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) and integer or boolean arrays are valid indices')
    elif com.is_bool_indexer(key):
        if isinstance(getattr(key, 'dtype', None), ExtensionDtype):
            key = key.to_numpy(dtype=bool, na_value=False)
        else:
            key = np.asarray(key, dtype=bool)
        check_array_indexer(self._range, key)
        key = np.flatnonzero(key)
    try:
        return self.take(key)
    except (TypeError, ValueError):
        return super().__getitem__(key)

def _align_for_op(self, other, axis: AxisInt, flex: bool | None=False, level: Level | None=None):
    """
        Convert rhs to meet lhs dims if input is list, tuple or np.ndarray.

        Parameters
        ----------
        other : Any
        axis : int
        flex : bool or None, default False
            Whether this is a flex op, in which case we reindex.
            None indicates not to check for alignment.
        level : int or level name, default None

        Returns
        -------
        left : DataFrame
        right : Any
        """
    (left, right) = (self, other)

    def to_series(right):
        msg = 'Unable to coerce to Series, length must be {req_len}: given {given_len}'
        dtype = None
        if getattr(right, 'dtype', None) == object:
            dtype = object
        if axis == 0:
            if len(left.index) != len(right):
                raise ValueError(msg.format(req_len=len(left.index), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.index, dtype=dtype)
        else:
            if len(left.columns) != len(right):
                raise ValueError(msg.format(req_len=len(left.columns), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.columns, dtype=dtype)
        return right
    if isinstance(right, np.ndarray):
        if right.ndim == 1:
            right = to_series(right)
        elif <MASK>:
            dtype = None
            if right.dtype == object:
                dtype = object
            if right.shape == left.shape:
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[0] == left.shape[0] and right.shape[1] == 1:
                right = np.broadcast_to(right, left.shape)
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[1] == left.shape[1] and right.shape[0] == 1:
                right = to_series(right[0, :])
            else:
                raise ValueError(f'Unable to coerce to DataFrame, shape must be {left.shape}: given {right.shape}')
        elif right.ndim > 2:
            raise ValueError(f'Unable to coerce to Series/DataFrame, dimension must be <= 2: {right.shape}')
    elif is_list_like(right) and (not isinstance(right, (Series, DataFrame))):
        if any((is_array_like(el) for el in right)):
            raise ValueError(f'Unable to coerce list of {type(right[0])} to Series/DataFrame')
        right = to_series(right)
    if flex is not None and isinstance(right, DataFrame):
        if not left._indexed_same(right):
            if flex:
                (left, right) = left.align(right, join='outer', level=level)
            else:
                raise ValueError('Can only compare identically-labeled (both index and columns) DataFrame objects')
    elif isinstance(right, Series):
        axis = axis if axis is not None else 1
        if not flex:
            if not left.axes[axis].equals(right.index):
                raise ValueError('Operands are not aligned. Do `left, right = left.align(right, axis=1)` before operating.')
        (left, right) = left.align(right, join='outer', axis=axis, level=level)
        right = left._maybe_align_series_as_frame(right, axis)
    return (left, right)

@property
def output_field(self):
    if len(self.select) == 1:
        select = self.select[0]
        return getattr(select, 'target', None) or select.field
    elif <MASK>:
