def step(self) -> bool:
    """Process exactly one instruction, return False we should exit"""
    self.error_on_graph_break = _get_error_on_graph_break()
    ip = self.instruction_pointer
    if <MASK>:
        return False
    self.current_instruction = inst = self.instructions[ip]
    self.instruction_pointer = ip + 1
    if inst.starts_line:
        self.starts_line(inst.starts_line)
    if not self.stack and self.should_compile_partial_graph() and self.is_non_empty_graph():
        self.current_speculation = self.speculate()
        if self.current_speculation.failed(self):
            self.step_graph_break(inst)
            return False
    if self.is_trace_bytecode_log_enabled:
        trace_bytecode_log.debug('TRACE %s %s %s', inst.opname, inst.argval, repr(self.stack))
    try:
        stack_repr = repr(self.stack)
    except ValueError:
        stack_repr = '<self.stack repr truncated due to large integer>'
    self.latest_bytecode_queue.append(f'TRACE {inst.opname} {repr(inst.argval)} {stack_repr}')
    self.update_block_stack(inst)
    try:
        self.dispatch_table[inst.opcode](self, inst)
        return not self.output.should_exit
    except TensorifyScalarRestartAnalysis:
        raise
    except exc.ObservedException as e:
        self.exception_handler(e)
        return True
    except (ReturnValueOp, YieldValueOp):
        return False
    except (Unsupported, StepUnsupported) as e:
        if self.current_speculation is None:
            log.debug('empty checkpoint')
            if isinstance(e, StepUnsupported):
                unimplemented_v2(gb_type='torch._dynamo.step_unsupported() with empty checkpoint', context='', explanation='traced torch._dynamo.step_unsupported(), but there is no checkpoint to step_graph_break from. This graph break is used for debugging only.', hints=['Remove the torch._dynamo.step_unsupported() call.', 'Include at least one checkpoint: (1) include at least 2 ops and (2) make sure there is some line of code that is not in a try/with block, and has an empty Python stack.', *graph_break_hints.DYNAMO_BUG])
            raise
        log.debug('step triggered compile', exc_info=True)
    self.current_speculation.fail_and_restart_analysis(self.error_on_graph_break)
    return False

def container_checker(obj, target_type) -> bool:
    origin_type = get_origin(target_type)
    check_args_exist(target_type)
    if origin_type is None:
        return False
    elif origin_type is list or origin_type is typing.List:
        check_empty_containers(obj)
        if not isinstance(obj, list):
            return False
        arg_type = get_args(target_type)[0]
        arg_origin = get_origin(arg_type)
        for el in obj:
            if arg_origin:
                if not container_checker(el, arg_type):
                    return False
            elif not isinstance(el, arg_type):
                return False
        return True
    elif origin_type is typing.Dict or origin_type is dict:
        check_empty_containers(obj)
        if not isinstance(obj, dict):
            return False
        key_type = get_args(target_type)[0]
        val_type = get_args(target_type)[1]
        for (key, val) in obj.items():
            if not isinstance(key, key_type):
                return False
            val_origin = get_origin(val_type)
            if val_origin:
                if not container_checker(val, val_type):
                    return False
            elif not isinstance(val, val_type):
                return False
        return True
    elif origin_type is typing.Tuple or origin_type is tuple:
        check_empty_containers(obj)
        if not isinstance(obj, tuple):
            return False
        arg_types = get_args(target_type)
        if len(obj) != len(arg_types):
            return False
        for (el, el_type) in zip(obj, arg_types):
            el_origin = get_origin(el_type)
            if el_origin:
                if not container_checker(el, el_type):
                    return False
            elif not isinstance(el, el_type):
                return False
        return True
    elif origin_type is Union or issubclass(origin_type, BuiltinUnionType):
        if obj is None:
            return True
        inner_types = get_args(target_type)
        for t in inner_types:
            t_origin = get_origin(t)
            if t_origin:
                return container_checker(obj, t)
            elif <MASK>:
                return True
    return False

def generate_py_arg_inner(lines, raw_arg, arg_type):

    def handle_scalar(scalar):
        if isinstance(scalar, int):
            return f'PyLong_FromLongLong({scalar})'
        if isinstance(scalar, float):
            return f'PyFloat_FromDouble({self.generate_float_value(scalar)})'
        if isinstance(scalar, bool):
            return f'PyBool_FromLong({(1 if scalar else 0)})'
        if isinstance(scalar, complex):
            real = self.generate_float_value(scalar.real)
            imag = self.generate_float_value(scalar.imag)
            return f'PyComplex_FromDoubles({real}, {imag})'
        if isinstance(scalar, SymTypes):
            scalar_var = cexpr(scalar.node.expr)
            if isinstance(scalar, torch.SymBool):
                return f'PyBool_FromLong({scalar_var})'
            if isinstance(scalar, torch.SymFloat):
                return f'PyFloat_FromDouble({scalar_var})'
            return f'PyLong_FromLongLong({scalar_var})'
        raise NotImplementedError(f'scalar {scalar}, {type(scalar)} cannot be handled by handle_scalar')
    if raw_arg is None:
        lines.append('Py_INCREF(Py_None);\n')
        return 'Py_None'
    elif isinstance(arg_type, torch.TensorType):
        if not hasattr(raw_arg, 'codegen_reference'):
            return handle_scalar(raw_arg)
        base_handle = self.create_tmp_raii_handle_var_if_needed(raw_arg.codegen_reference(), lines)
        return f'PyCapsule_New(reinterpret_cast<void*>({base_handle}.get()), NULL, NULL)'
    elif isinstance(arg_type, torch.OptionalType):
        return generate_py_arg_inner(lines, raw_arg, arg_type.getElementType())
    elif isinstance(arg_type, torch.IntType):
        return f'PyLong_FromLongLong({raw_arg})'
    elif isinstance(arg_type, torch.SymIntType):
        expr = raw_arg.node.expr if isinstance(raw_arg, torch.SymInt) else raw_arg
        return f'PyLong_FromLongLong({cexpr(expr)})'
    elif isinstance(arg_type, torch.FloatType):
        return f'PyFloat_FromDouble({self.generate_float_value(raw_arg)})'
    elif isinstance(arg_type, torch.BoolType):
        return f'PyBool_FromLong({(1 if raw_arg else 0)})'
    elif isinstance(arg_type, torch.StringType):
        return f'PyUnicode_FromString("{raw_arg}")'
    elif isinstance(arg_type, torch.NumberType):
        return handle_scalar(raw_arg)
    elif isinstance(raw_arg, torch.device):
        (device_str, device_index) = self.codegen_device(raw_arg).split(', ')
        return f'THPDevice_New(c10::Device(static_cast<c10::DeviceType>({device_str}), {device_index}))'
    elif isinstance(raw_arg, torch.dtype):
        return f'Py_NewRef(torch::getTHPDtype(static_cast<c10::ScalarType>({self.codegen_dtype(raw_arg)})))'
    elif <MASK>:
        return f'Py_NewRef(torch::getTHPLayout(static_cast<c10::Layout>({self.codegen_layout(raw_arg)})))'
    elif isinstance(raw_arg, torch.memory_format):
        return f'Py_NewRef(torch::utils::getTHPMemoryFormat(static_cast<c10::MemoryFormat>({self.codegen_memory_format(raw_arg)})))'
    else:
        raise NotImplementedError(f'arg type {arg_type} is not yet supported by custom_op_wrapper')

