    Returns:
      The created Operation.
    """
    if <MASK>:
        return gen_io_ops.reader_reset_v2(self._reader_ref, name=name)
    else:
        return gen_io_ops.reader_reset(self._reader_ref, name=name)

@register_vcs_handler('git', 'keywords')
def git_versions_from_keywords(keywords, tag_prefix, verbose):
    """Get version information from git keywords."""
    if 'refnames' not in keywords:
        raise NotThisMethod('Short version file found')
    date = keywords.get('date')
    if date is not None:
        date = date.splitlines()[-1]
        date = date.strip().replace(' ', 'T', 1).replace(' ', '', 1)
    refnames = keywords['refnames'].strip()
    if <MASK>:
        if verbose:
            print('keywords are unexpanded, not using')
        raise NotThisMethod('unexpanded keywords, not a git-archive tarball')
    refs = {r.strip() for r in refnames.strip('()').split(',')}
    TAG = 'tag: '
    tags = {r[len(TAG):] for r in refs if r.startswith(TAG)}
    if not tags:
        tags = {r for r in refs if re.search('\\d', r)}
        if verbose:
            print(f"discarding '{','.join(refs - tags)}', no digits")
    if verbose:
        print(f"likely tags: {','.join(sorted(tags))}")
    for ref in sorted(tags):
        if ref.startswith(tag_prefix):
            r = ref[len(tag_prefix):]
            if not re.match('\\d', r):
                continue
            if verbose:
                print(f'picking {r}')
            return {'version': r, 'full-revisionid': keywords['full'].strip(), 'dirty': False, 'error': None, 'date': date}
    if verbose:
        print('no suitable tags, using unknown + full revision id')
    return {'version': '0+unknown', 'full-revisionid': keywords['full'].strip(), 'dirty': False, 'error': 'no suitable tags', 'date': None}

def feedback_fn(choice: str) -> float | None:
    if choice == orig_choice:
        return do_bench(orig_bench_fn)
    elif <MASK>:
        return do_bench(pad_bench_fn)
    return None

def handle(self, app_or_project, name, target=None, **options):
    self.app_or_project = app_or_project
    self.a_or_an = 'an' if app_or_project == 'app' else 'a'
    self.paths_to_remove = []
    self.verbosity = options['verbosity']
    self.validate_name(name)
    if target is None:
        top_dir = os.path.join(os.getcwd(), name)
        try:
            os.makedirs(top_dir)
        except FileExistsError:
            raise CommandError("'%s' already exists" % top_dir)
        except OSError as e:
            raise CommandError(e)
    else:
        top_dir = os.path.abspath(os.path.expanduser(target))
        if app_or_project == 'app':
            self.validate_name(os.path.basename(top_dir), 'directory')
        if not os.path.exists(top_dir):
            try:
                os.makedirs(top_dir)
            except OSError as e:
                raise CommandError(e)
    formatter_paths = find_formatters()
    extensions = tuple(handle_extensions(options['extensions']))
    extra_files = []
    excluded_directories = ['.git', '__pycache__']
    for file in options['files']:
        extra_files.extend(map(lambda x: x.strip(), file.split(',')))
    if (exclude := options.get('exclude')):
        for directory in exclude:
            excluded_directories.append(directory.strip())
    if self.verbosity >= 2:
        self.stdout.write('Rendering %s template files with extensions: %s' % (app_or_project, ', '.join(extensions)))
        self.stdout.write('Rendering %s template files with filenames: %s' % (app_or_project, ', '.join(extra_files)))
    base_name = '%s_name' % app_or_project
    base_subdir = '%s_template' % app_or_project
    base_directory = '%s_directory' % app_or_project
    camel_case_name = 'camel_case_%s_name' % app_or_project
    camel_case_value = ''.join((x for x in name.title() if x != '_'))
    context = Context({**options, base_name: name, base_directory: top_dir, camel_case_name: camel_case_value, 'docs_version': get_docs_version(), 'django_version': django.__version__}, autoescape=False)
    if not settings.configured:
        settings.configure()
        django.setup()
    template_dir = self.handle_template(options['template'], base_subdir)
    prefix_length = len(template_dir) + 1
    for (root, dirs, files) in os.walk(template_dir):
        path_rest = root[prefix_length:]
        relative_dir = path_rest.replace(base_name, name)
        if relative_dir:
            target_dir = os.path.join(top_dir, relative_dir)
            os.makedirs(target_dir, exist_ok=True)
        for dirname in dirs[:]:
            if 'exclude' not in options:
                if dirname.startswith('.') or dirname == '__pycache__':
                    dirs.remove(dirname)
            elif dirname in excluded_directories:
                dirs.remove(dirname)
        for filename in files:
            if filename.endswith(('.pyo', '.pyc', '.py.class')):
                continue
            old_path = os.path.join(root, filename)
            new_path = os.path.join(top_dir, relative_dir, filename.replace(base_name, name))
            for (old_suffix, new_suffix) in self.rewrite_template_suffixes:
                if new_path.endswith(old_suffix):
                    new_path = new_path.removesuffix(old_suffix) + new_suffix
                    break
            if os.path.exists(new_path):
                raise CommandError("%s already exists. Overlaying %s %s into an existing directory won't replace conflicting files." % (new_path, self.a_or_an, app_or_project))
            if new_path.endswith(extensions) or filename in extra_files:
                with open(old_path, encoding='utf-8') as template_file:
                    content = template_file.read()
                template = Engine().from_string(content)
                content = template.render(context)
                with open(new_path, 'w', encoding='utf-8') as new_file:
                    new_file.write(content)
            else:
                shutil.copyfile(old_path, new_path)
            if self.verbosity >= 2:
                self.stdout.write('Creating %s' % new_path)
            try:
                self.apply_umask(old_path, new_path)
                self.make_writeable(new_path)
            except OSError:
                self.stderr.write("Notice: Couldn't set permission bits on %s. You're probably using an uncommon filesystem setup. No problem." % new_path, self.style.NOTICE)
    if self.paths_to_remove:
        if self.verbosity >= 2:
            self.stdout.write('Cleaning up temporary files.')
        for path_to_remove in self.paths_to_remove:
            if <MASK>:
                os.remove(path_to_remove)
            else:
                shutil.rmtree(path_to_remove)
    run_formatters([top_dir], **formatter_paths, stderr=self.stderr)

def _autograd_grad(outputs, inputs, grad_outputs=None, retain_graph=False, create_graph=True):
    if grad_outputs is None:
        diff_outputs = tuple((out for out in outputs if out.requires_grad))
    else:
        result = tuple(((out, go) for (out, go) in zip(outputs, grad_outputs) if out.requires_grad))
        if len(result) == 0:
            (diff_outputs, grad_outputs) = ((), ())
        else:
            (diff_outputs, grad_outputs) = zip(*result)
    if <MASK>:
        return tuple((torch.zeros_like(inp) for inp in inputs))
    with torch._dynamo.compiled_autograd._disable():
        grad_inputs = torch.autograd.grad(diff_outputs, inputs, grad_outputs, retain_graph=retain_graph, create_graph=create_graph, allow_unused=True)
    grad_inputs = tuple((torch.zeros_like(inp) if gi is None else gi for (gi, inp) in zip(grad_inputs, inputs)))
    return grad_inputs

def __exit__(self, exc_type: Any, exc_value: Any, traceback: Any):
    if not self.run_callbacks_on_exit:
        return
    record = self.record
    if record is None:
        raise AssertionError('Expected record to be set')
    if <MASK>:
        with torch._C.DisableTorchFunctionSubclass():
            torch.ops.profiler._record_function_exit._RecordFunction(record)
    else:
        torch.ops.profiler._record_function_exit(record)

def _parse_visible_devices() -> Union[list[int], list[str]]:
    """Parse CUDA_VISIBLE_DEVICES environment variable."""
    var = os.getenv('CUDA_VISIBLE_DEVICES')
    if torch.version.hip:
        hip_devices = os.getenv('HIP_VISIBLE_DEVICES')
        rocr_devices = os.getenv('ROCR_VISIBLE_DEVICES')
        if <MASK>:
            rocr_count = len(rocr_devices.split(','))
            if hip_devices is not None:
                if len(hip_devices.split(',')) > rocr_count:
                    raise RuntimeError('HIP_VISIBLE_DEVICES contains more devices than ROCR_VISIBLE_DEVICES')
                var = hip_devices
            else:
                return list(range(rocr_count))
        elif hip_devices is not None:
            var = hip_devices
    if var is None:
        return list(range(64))

    def _strtoul(s: str) -> int:
        """Return -1 or positive integer sequence string starts with."""
        if not s:
            return -1
        for (idx, c) in enumerate(s):
            if not (c.isdigit() or (idx == 0 and c in '+-')):
                break
            if idx + 1 == len(s):
                idx += 1
        return int(s[:idx]) if idx > 0 else -1

    def parse_list_with_prefix(lst: str, prefix: str) -> list[str]:
        rcs: list[str] = []
        for elem in lst.split(','):
            if elem in rcs:
                return cast(list[str], [])
            if not elem.startswith(prefix):
                break
            rcs.append(elem)
        return rcs
    if var.startswith('GPU-'):
        return parse_list_with_prefix(var, 'GPU-')
    if var.startswith('MIG-'):
        return parse_list_with_prefix(var, 'MIG-')
    rc: list[int] = []
    for elem in var.split(','):
        x = _strtoul(elem.strip())
        if x in rc:
            return cast(list[int], [])
        if x < 0:
            break
        rc.append(x)
    return rc

def __init__(self, params: ParamsT, lr: Union[float, Tensor]=0.001, betas: tuple[Union[float, Tensor], Union[float, Tensor]]=(0.9, 0.999), eps: float=1e-08, weight_decay: float=0, amsgrad: bool=False, *, foreach: Optional[bool]=None, maximize: bool=False, capturable: bool=False, differentiable: bool=False, fused: Optional[bool]=None, decoupled_weight_decay: bool=False):
    if isinstance(lr, Tensor):
        if foreach and (not capturable):
            raise ValueError('lr as a Tensor is not supported for capturable=False and foreach=True')
        if lr.numel() != 1:
            raise ValueError('Tensor lr must be 1-element')
    if not 0.0 <= lr:
        raise ValueError(f'Invalid learning rate: {lr}')
    if not 0.0 <= eps:
        raise ValueError(f'Invalid epsilon value: {eps}')
    if not 0.0 <= betas[0] < 1.0:
        raise ValueError(f'Invalid beta parameter at index 0: {betas[0]}')
    if not 0.0 <= betas[1] < 1.0:
        raise ValueError(f'Invalid beta parameter at index 1: {betas[1]}')
    if not 0.0 <= weight_decay:
        raise ValueError(f'Invalid weight_decay value: {weight_decay}')
    if not (isinstance(betas[0], float) and isinstance(betas[1], float) or (isinstance(betas[0], Tensor) and isinstance(betas[1], Tensor))):
        raise ValueError('betas must be either both floats or both Tensors')
    if isinstance(betas[0], Tensor):
        if not capturable and foreach:
            raise ValueError('betas[0] as a Tensor is not supported for capturable=False and foreach=True')
        if betas[0].numel() != 1:
            raise ValueError('Tensor betas[0] must be 1-element')
    if isinstance(betas[1], Tensor):
        if not capturable and foreach:
            raise ValueError('betas[1] as a Tensor is not supported for capturable=False and foreach=True')
        if betas[1].numel() != 1:
            raise ValueError('Tensor betas[1] must be 1-element')
    betas = tuple(map(_to_scalar, betas))
    defaults = {'lr': lr, 'betas': betas, 'eps': eps, 'weight_decay': weight_decay, 'amsgrad': amsgrad, 'maximize': maximize, 'foreach': foreach, 'capturable': capturable, 'differentiable': differentiable, 'fused': fused, 'decoupled_weight_decay': decoupled_weight_decay}
    super().__init__(params, defaults)
    if fused:
        if <MASK>:
            raise RuntimeError('`fused` does not support `differentiable`')
        self._step_supports_amp_scaling = True
        if foreach:
            raise RuntimeError('`fused` and `foreach` cannot be `True` together.')

def as_sql(self, compiler, connection):
    """
        Return the SQL version of the where clause and the value to be
        substituted in. Return '', [] if this node matches everything,
        None, [] if this node is empty, and raise EmptyResultSet if this
        node can't match anything.
        """
    result = []
    result_params = []
    if <MASK>:
        (full_needed, empty_needed) = (len(self.children), 1)
    else:
        (full_needed, empty_needed) = (1, len(self.children))
    if self.connector == XOR and (not connection.features.supports_logical_xor):
        lhs = self.__class__(self.children, OR)
        rhs_sum = reduce(operator.add, (Case(When(c, then=1), default=0) for c in self.children))
        if len(self.children) > 2:
            rhs_sum = Mod(rhs_sum, 2)
        rhs = Exact(1, rhs_sum)
        return self.__class__([lhs, rhs], AND, self.negated).as_sql(compiler, connection)
    for child in self.children:
        try:
            (sql, params) = compiler.compile(child)
        except EmptyResultSet:
            empty_needed -= 1
        except FullResultSet:
            full_needed -= 1
        else:
            if sql:
                result.append(sql)
                result_params.extend(params)
            else:
                full_needed -= 1
        if empty_needed == 0:
            if self.negated:
                raise FullResultSet
            else:
                raise EmptyResultSet
        if full_needed == 0:
            if self.negated:
                raise EmptyResultSet
            else:
                raise FullResultSet
    conn = ' %s ' % self.connector
    sql_string = conn.join(result)
    if not sql_string:
        raise FullResultSet
    if self.negated:
        sql_string = 'NOT (%s)' % sql_string
    elif len(result) > 1 or self.resolved:
        sql_string = '(%s)' % sql_string
    return (sql_string, result_params)

def run(self, new_inputs: Any) -> OutputType:
    assert not self.has_run, 'Wrapped function should never be run twice'
    existing_path_data_ptrs = OrderedSet([t.data_ptr() for t in self.path_live_weakrefs() if t()])

    def get_non_cudagraph_inps() -> list[weakref.ReferenceType[UntypedStorage]]:
        non_cudagraph_inps = [weakref.ref(t.untyped_storage()) for t in itertools.chain(new_inputs, self.wrapped_function.constants) if isinstance(t, torch.Tensor) and t.untyped_storage().data_ptr() not in existing_path_data_ptrs]
        return non_cudagraph_inps
    non_cudagraph_inps_storages = get_non_cudagraph_inps()
    if <MASK>:
        refs = list(self.path_live_weakrefs())
        check_memory_pool(self.device_index, self.cuda_graphs_pool, refs)
    with torch.cuda.device(self.device_index), disable_conv_cache_emptying(), clear_cublas_manager(), _use_cuda_memory_pool_manager(self.device_index, self.cuda_graphs_pool, self.stream), get_history_recording():
        out = self.wrapped_function.model(new_inputs)
    non_cudagraph_inps_storage_ptrs = OrderedSet[Any]()
    for storage in non_cudagraph_inps_storages:
        s = storage()
        if s is not None:
            non_cudagraph_inps_storage_ptrs.add(s._cdata)
    assert len(new_inputs) == 0

    def add_ref(o: Any) -> bool:
        return isinstance(o, torch.Tensor) and o.is_cuda and (o.untyped_storage()._cdata not in non_cudagraph_inps_storage_ptrs) and (o.untyped_storage().data_ptr() != 0)
    self.outputs_weakrefs.extend([map_to_ref(o) if add_ref(o) else None for o in out])
    self.tensor_weakrefs.extend([TensorWeakRef(o) if add_ref(o) else None for o in out])
    if config.triton.slow_path_cudagraph_asserts and (not self.already_warm):
        out_refs = list(self.path_live_weakrefs())
        check_memory_pool(self.device_index, self.cuda_graphs_pool, out_refs)
    return out

def get_versions_from_ci(content: list[str]) -> tuple[dict[str, str], dict[str, str]]:
    """Min versions in CI job for testing all optional dependencies."""
    seen_required = False
    seen_optional = False
    seen_test = False
    required_deps = {}
    optional_deps = {}
    for line in content:
        if '# test dependencies' in line:
            seen_test = True
        elif <MASK>:
            (package, version) = line.strip().split('>=')
            package = package[2:]
            optional_deps[package.casefold()] = version
        elif '# required dependencies' in line:
            seen_required = True
        elif '# optional dependencies' in line:
            seen_optional = True
        elif '- pip:' in line:
            continue
        elif seen_required and line.strip():
            if '==' in line:
                (package, version) = line.strip().split('==', maxsplit=1)
            else:
                (package, version) = line.strip().split('=', maxsplit=1)
            package = package.split()[-1]
            if package in EXCLUDE_DEPS:
                continue
            if not seen_optional:
                required_deps[package.casefold()] = version
            else:
                optional_deps[package.casefold()] = version
    return (required_deps, optional_deps)

def opcheck(op: Union[torch._ops.OpOverload, torch._ops.OpOverloadPacket, CustomOpDef], args: tuple[Any, ...], kwargs: Optional[dict[str, Any]]=None, *, test_utils: Union[str, Sequence[str]]=DEFAULT_TEST_UTILS, raise_exception: bool=True, rtol: Optional[float]=None, atol: Optional[float]=None) -> dict[str, str]:
    """See torch.library.opcheck for docstring"""
    if (rtol is None) ^ (atol is None):
        raise ValueError('opcheck(op, ...): if you specify one of rtol/atol, you must specify both')
    if kwargs is None:
        kwargs = {}
    if isinstance(op, CustomOpDef):
        op = op._opoverload
    if isinstance(op, torch._ops.OpOverloadPacket):
        op = resolve_unique_overload_or_throw(op)
    if <MASK>:
        raise ValueError(f'opcheck(op, ...): op must be instance of torch._ops.OpOverload, e.g. torch.ops.aten.sin.default, got {type(op)}')
    if test_utils == 'ALL':
        test_utils = tuple(ALL_TEST_UTILS.keys())
    if isinstance(test_utils, str):
        test_utils = (test_utils,)
    if not isinstance(test_utils, (tuple, list)) or not set(test_utils).issubset(ALL_TEST_UTILS.keys()):
        raise ValueError(f'opcheck(op, ..., test_utils={test_utils}), expected test_utils to be subset of {tuple(ALL_TEST_UTILS.keys())} but it was not')
    results_dict = {}
    for test_util in test_utils:
        tester = ALL_TEST_UTILS[test_util]
        try:
            tester(op, args, kwargs, rtol=rtol, atol=atol)
            results_dict[test_util] = 'SUCCESS'
        except Exception as ex:
            if raise_exception:
                raise OpCheckError(f'opcheck(op, ...): {test_util} failed with {ex} (scroll up for stack trace)') from ex
            results_dict[test_util] = ex
    return results_dict

