def _eval(self, d1, d2, d3, d4, binary_op, unary_op):
    if <MASK>:

        def binary_op(x, y):
            return x + y
    if not unary_op:

        def unary_op(x):
            return x
    if self.split_input:
        d1 = unary_op(d1)
        d2 = unary_op(d2)
        d3 = unary_op(d3)
        d4 = unary_op(d4)
    else:
        (d1, d2, d3, d4) = (unary_op(d1), unary_op(d2), unary_op(d1 + 0.001), unary_op(d4))
    a = binary_op(d1, d2)
    b = binary_op(d3, d4)
    c = a + b
    return c

def _refill(self) -> None:
    with self.device_module.stream(self.stream):
        while not self._done and self.in_flight_data < self.inflight_threshhold:
            (_, obj) = self.items[self.idx]
            self.idx += 1
            tensor = self.resolve_fun(obj).detach()
            if tensor.device.type == self.device_type:
                tensor = tensor.to(device='cpu', non_blocking=True)
            elif tensor.device == torch.device('cpu'):
                if <MASK>:
                    tensor = tensor.clone()
            self.current_items.append((tensor, obj))
            self.in_flight_data += tensor.numel() * tensor.element_size()

@classmethod
def eval(cls, base, shift):
    if <MASK>:
        raise ValueError('negative shift count')
    return base * 2 ** shift

