def build_def(ctx, py_def, type_line, def_name, self_name=None, pdt_arg_types=None):
    body = py_def.body
    r = ctx.make_range(py_def.lineno, py_def.col_offset, py_def.col_offset + len('def'))
    param_list = build_param_list(ctx, py_def.args, self_name, pdt_arg_types)
    return_type = None
    if <MASK>:
        return_type = build_expr(ctx, py_def.returns)
    decl = Decl(r, param_list, return_type)
    is_method = self_name is not None
    if type_line is not None:
        type_comment_decl = torch._C.parse_type_comment(type_line)
        decl = torch._C.merge_type_from_type_comment(decl, type_comment_decl, is_method)
    return Def(Ident(r, def_name), decl, build_stmts(ctx, body))

def _wrap_applied_output(self, data: Series, values: list[Any], not_indexed_same: bool=False, is_transform: bool=False) -> DataFrame | Series:
    """
        Wrap the output of SeriesGroupBy.apply into the expected result.

        Parameters
        ----------
        data : Series
            Input data for groupby operation.
        values : List[Any]
            Applied output for each group.
        not_indexed_same : bool, default False
            Whether the applied outputs are not indexed the same as the group axes.

        Returns
        -------
        DataFrame or Series
        """
    if len(values) == 0:
        if is_transform:
            res_index = data.index
        elif not self.group_keys:
            res_index = None
        else:
            res_index = self._grouper.result_index
        return self.obj._constructor([], name=self.obj.name, index=res_index, dtype=data.dtype)
    assert values is not None
    if isinstance(values[0], dict):
        index = self._grouper.result_index
        res_df = self.obj._constructor_expanddim(values, index=index)
        res_ser = res_df.stack()
        res_ser.name = self.obj.name
        return res_ser
    elif isinstance(values[0], (Series, DataFrame)):
        result = self._concat_objects(values, not_indexed_same=not_indexed_same, is_transform=is_transform)
        if isinstance(result, Series):
            result.name = self.obj.name
        if <MASK>:
            result = self._insert_inaxis_grouper(result)
            result.index = default_index(len(result))
        return result.__finalize__(self.obj, method='groupby')
    else:
        result = self.obj._constructor(data=values, index=self._grouper.result_index, name=self.obj.name)
        if not self.as_index:
            result = self._insert_inaxis_grouper(result)
            result.index = default_index(len(result))
        return result.__finalize__(self.obj, method='groupby')

def __init__(self, filepath, monitor='val_loss', verbose=0, save_best_only=False, save_weights_only=False, mode='auto', save_freq='epoch', options=None, **kwargs):
    super(ModelCheckpoint, self).__init__()
    self._supports_tf_logs = True
    self.monitor = monitor
    self.verbose = verbose
    self.filepath = path_to_string(filepath)
    self.save_best_only = save_best_only
    self.save_weights_only = save_weights_only
    self.save_freq = save_freq
    self.epochs_since_last_save = 0
    self._batches_seen_since_last_saving = 0
    self._last_batch_seen = 0
    if save_weights_only:
        if options is None or isinstance(options, checkpoint_options_lib.CheckpointOptions):
            self._options = options or checkpoint_options_lib.CheckpointOptions()
        else:
            raise TypeError('If save_weights_only is True, then `options` must be either None or a tf.train.CheckpointOptions')
    elif options is None or isinstance(options, save_options_lib.SaveOptions):
        self._options = options or save_options_lib.SaveOptions()
    else:
        raise TypeError('If save_weights_only is False, then `options` must beeither None or a tf.saved_model.SaveOptions')
    if 'load_weights_on_restart' in kwargs:
        self.load_weights_on_restart = kwargs['load_weights_on_restart']
        logging.warning('`load_weights_on_restart` argument is deprecated. Please use `model.load_weights()` for loading weights before the start of `model.fit()`.')
    else:
        self.load_weights_on_restart = False
    if 'period' in kwargs:
        self.period = kwargs['period']
        logging.warning('`period` argument is deprecated. Please use `save_freq` to specify the frequency in number of batches seen.')
    else:
        self.period = 1
    if mode not in ['auto', 'min', 'max']:
        logging.warning('ModelCheckpoint mode %s is unknown, fallback to auto mode.', mode)
        mode = 'auto'
    if mode == 'min':
        self.monitor_op = np.less
        self.best = np.inf
    elif mode == 'max':
        self.monitor_op = np.greater
        self.best = -np.inf
    elif 'acc' in self.monitor or self.monitor.startswith('fmeasure'):
        self.monitor_op = np.greater
        self.best = -np.inf
    else:
        self.monitor_op = np.less
        self.best = np.inf
    if <MASK>:
        raise ValueError('Unrecognized save_freq: {}'.format(self.save_freq))
    self._chief_worker_only = False

def is_square(operator_a, operator_b):
    """Return a hint to whether the composition is square."""
    if operator_a.is_square and operator_b.is_square:
        return True
    if operator_a.is_square is False and operator_b.is_square is False:
        m = operator_a.range_dimension
        l = operator_b.domain_dimension
        if <MASK>:
            return m == l
    if operator_a.is_square != operator_b.is_square and (operator_a.is_square is not None and operator_b.is_square is not None):
        return False
    return None

def identify_license(f, exception=''):
    """
    Read f and try to identify the license type
    This is __very__ rough and probably not legally binding, it is specific for
    this repo.
    """

    def squeeze(t):
        """Remove 'n and ' ', normalize quotes
        """
        t = t.replace('\n', '').replace(' ', '')
        t = t.replace('``', '"').replace("''", '"')
        return t
    with open(f) as fid:
        txt = fid.read()
        if not exception and 'exception' in txt:
            license = identify_license(f, 'exception')
            return license + ' with exception'
        txt = squeeze(txt)
        if 'ApacheLicense' in txt:
            return 'Apache-2.0'
        elif 'MITLicense' in txt:
            return 'MIT'
        elif <MASK>:
            return 'BSD-3-Clause'
        elif 'BSD3-ClauseLicense' in txt:
            return 'BSD-3-Clause'
        elif 'BoostSoftwareLicense-Version1.0' in txt:
            return 'BSL-1.0'
        elif 'gettimeofday' in txt:
            return 'Apache-2.0'
        elif 'libhungarian' in txt:
            return 'Permissive (free to use)'
        elif 'PDCurses' in txt:
            return 'Public Domain for core'
        elif 'Copyright1999UniversityofNorthCarolina' in txt:
            return 'Apache-2.0'
        elif 'sigslot' in txt:
            return 'Public Domain'
        elif squeeze('Clarified Artistic License') in txt:
            return 'Clarified Artistic License'
        elif all([squeeze(m) in txt.lower() for m in bsd3_txt]):
            return 'BSD-3-Clause'
        elif all([squeeze(m) in txt.lower() for m in bsd3_v1_txt]):
            return 'BSD-3-Clause'
        elif all([squeeze(m) in txt.lower() for m in bsd2_txt]):
            return 'BSD-2-Clause'
        elif all([squeeze(m) in txt.lower() for m in bsd3_src_txt]):
            return 'BSD-Source-Code'
        elif any([squeeze(m) in txt.lower() for m in mit_txt]):
            return 'MIT'
        else:
            raise ValueError('unknown license')

def _test_input_fn_iterator(self, task_type, task_id, num_gpus, input_fn, expected_values, test_reinitialize=True, ignore_order=False):
    (distribution, master_target, config) = self._get_test_objects(task_type, task_id, num_gpus)
    devices = distribution.extended.worker_devices
    with ops.Graph().as_default(), self.cached_session(config=config, target=master_target) as sess:
        iterator = distribution.make_input_fn_iterator(input_fn)
        sess.run(iterator.initializer)
        for expected_value in expected_values:
            next_element = iterator.get_next()
            computed_value = sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
            if ignore_order:
                self.assertCountEqual(expected_value, computed_value)
            else:
                self.assertEqual(expected_value, computed_value)
        with self.assertRaises(errors.OutOfRangeError):
            next_element = iterator.get_next()
            sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
        if <MASK>:
            sess.run(iterator.initializer)
            for expected_value in expected_values:
                next_element = iterator.get_next()
                computed_value = sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
                if ignore_order:
                    self.assertCountEqual(expected_value, computed_value)
                else:
                    self.assertEqual(expected_value, computed_value)

def _validate_flavor(flavor):
    if <MASK>:
        flavor = ('lxml', 'bs4')
    elif isinstance(flavor, str):
        flavor = (flavor,)
    elif isinstance(flavor, abc.Iterable):
        if not all((isinstance(flav, str) for flav in flavor)):
            raise TypeError(f'Object of type {type(flavor).__name__!r} is not an iterable of strings')
    else:
        msg = repr(flavor) if isinstance(flavor, str) else str(flavor)
        msg += ' is not a valid flavor'
        raise ValueError(msg)
    flavor = tuple(flavor)
    valid_flavors = set(_valid_parsers)
    flavor_set = set(flavor)
    if not flavor_set & valid_flavors:
        raise ValueError(f'{_print_as_set(flavor_set)} is not a valid set of flavors, valid flavors are {_print_as_set(valid_flavors)}')
    return flavor

def _add_first_outputs(self, outputs: OutputType, static_input_persistent_storage_ptrs: dict[int, StorageWeakRefWrapper]) -> None:
    """Add the outputs from the first invocation of the node and set up metadata"""
    prev_liveness = self.recorded_liveness_before_graph
    curr_liveness = self._get_liveness(self.path_weakrefs)
    delta = self._get_different_indices(prev_liveness, curr_liveness)
    self.expected_dead_indices_after_graph = delta
    assert len(self.outputs_weakrefs) == 0
    output_new_storages_index: dict[StorageDataPtr, int] = {}
    self.unaliased_in_all_paths = [False for _ in range(len(outputs))]
    self.static_output_tensors = [None for _ in range(len(outputs))]
    for (i, o) in enumerate(outputs):
        if o is None or not isinstance(o, torch.Tensor):
            self.output_storage_alias.append(UnaliasedStorage)
            continue
        torch._check(o.is_cuda or o.untyped_storage().data_ptr() == 0, lambda : f"Expected all cuda outputs in cuda graph recording. Non cuda output from {(self.stack_traces[i] if self.stack_traces else '(unknown)')}")
        ref = static_input_persistent_storage_ptrs.get(o.untyped_storage().data_ptr(), None)
        is_empty_storage = o.untyped_storage().data_ptr() == 0
        if ref and ref() is not None or is_empty_storage:
            self.output_storage_alias.append(None)
            self.static_output_tensors[i] = o
            continue
        path_ref = self._is_alias_of_live_recorded_tensor(o)
        if path_ref is not None:
            self._mark_prior_graph_output_as_aliased(path_ref)
            for (idx, inp_path_ref) in enumerate(self.live_cudagraph_managed_path_refs):
                if path_ref == inp_path_ref:
                    self.preserved_aliased_inputs[idx] = True
            self.output_storage_alias.append(AliasesPriorGraphOutput(path_ref))
            continue
        if o.untyped_storage().data_ptr() in output_new_storages_index:
            index = output_new_storages_index[o.untyped_storage().data_ptr()]
            self.unaliased_in_all_paths[index] = False
            self.output_storage_alias.append(AliasesNewOutput(index))
            continue
        output_new_storages_index[o.untyped_storage().data_ptr()] = i
        self.output_storage_alias.append(UnaliasedStorage)
        self.unaliased_in_all_paths[i] = True
    if <MASK>:
        self.stack_traces = [None for _ in range(len(outputs))]
    else:
        assert len(self.stack_traces) == len(outputs), 'Wrong number of stack traces passed in'
    assert not self.outputs_weakrefs
    for (out, static_output_tensor) in zip(outputs, self.static_output_tensors):
        if not isinstance(out, torch.Tensor) or static_output_tensor is not None:
            self.outputs_weakrefs.append(None)
            self.tensor_weakrefs.append(None)
        else:
            self.outputs_weakrefs.append(StorageWeakRefWrapper(out))
            self.tensor_weakrefs.append(TensorWeakRef(out))
    self.recorded_liveness_after_graph = self._get_liveness(self.path_weakrefs)
    self.checkpointed_caching_state = torch._C._cuda_getCheckpointState(self.device, self.cuda_graphs_pool)
    for depth in range(len(self.path_weakrefs)):
        for output_index in range(len(self.path_weakrefs[depth])):
            if is_live(self.path_weakrefs[depth][output_index]):
                self.live_indices_after_graph.append((depth, output_index))
    self.debug_check_invariants_after_invocation()
    if config.triton.slow_path_cudagraph_asserts:
        check_memory_pool(self.device, self.cuda_graphs_pool, list(self.path_live_weakrefs()))

def nested_data_to_arrays(data: Sequence, columns: Index | None, index: Index | None, dtype: DtypeObj | None) -> tuple[list[ArrayLike], Index, Index]:
    """
    Convert a single sequence of arrays to multiple arrays.
    """
    if is_named_tuple(data[0]) and columns is None:
        columns = ensure_index(data[0]._fields)
    (arrays, columns) = to_arrays(data, columns, dtype=dtype)
    columns = ensure_index(columns)
    if index is None:
        if <MASK>:
            index = _get_names_from_index(data)
        else:
            index = default_index(len(data))
    return (arrays, columns, index)

