def get_task_func(task: str) -> Callable:

    def hessian_fwdrev(model, inp, strict=None):
        return functional.hessian(model, inp, strict=False, vectorize=True, outer_jacobian_strategy='forward-mode')

    def hessian_revrev(model, inp, strict=None):
        return functional.hessian(model, inp, strict=False, vectorize=True)

    def jacfwd(model, inp, strict=None):
        return functional.jacobian(model, inp, strict=False, vectorize=True, strategy='forward-mode')

    def jacrev(model, inp, strict=None):
        return functional.jacobian(model, inp, strict=False, vectorize=True)
    if task == 'hessian_fwdrev':
        return hessian_fwdrev
    elif task == 'hessian_revrev':
        return hessian_revrev
    elif task == 'jacfwd':
        return jacfwd
    elif <MASK>:
        return jacrev
    else:
        return getattr(functional, task)

def load_tensor(dtype, numel, key, location):
    name = f'data/{key}'
    if torch._guards.detect_fake_mode(None) is not None:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes, device='meta')
        if can_calculate_storage_offsets:
            storage._checkpoint_offset = _get_offset(key, name, numel)
        else:
            storage._checkpoint_offset = zip_file.get_record_offset(name)
    elif <MASK>:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes)
    elif overall_storage is not None:
        if can_calculate_storage_offsets and calculate_storage_offsets:
            storage_offset = _get_offset(key, name, numel)
            if run_debug_asserts:
                if storage_offset != zip_file.get_record_offset(name):
                    raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        else:
            storage_offset = zip_file.get_record_offset(name)
        storage = overall_storage[storage_offset:storage_offset + numel]
    else:
        if can_calculate_storage_offsets and run_debug_asserts:
            storage_offset = _get_offset(key, name, numel)
            if storage_offset != zip_file.get_record_offset(name):
                raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        storage = zip_file.get_storage_from_record(name, numel, torch.UntypedStorage)._typed_storage()._untyped_storage
    if byteorderdata is not None:
        if byteorderdata.decode() != sys.byteorder:
            storage.byteswap(dtype)
    if torch._guards.detect_fake_mode(None) is None:
        wrap_storage = restore_location(storage, location)
    else:
        storage._fake_device = location
        wrap_storage = storage
    typed_storage = torch.storage.TypedStorage(wrap_storage=wrap_storage, dtype=dtype, _internal=True)
    if typed_storage._data_ptr() != 0:
        loaded_storages[key] = typed_storage
    return typed_storage

def sequence_like(instance, args):
    """Converts the sequence `args` to the same type as `instance`.

  Args:
    instance: an instance of `tuple`, `list`, `namedtuple`, `dict`,
      `collections.OrderedDict`, or `composite_tensor.Composite_Tensor` or
      `type_spec.TypeSpec`.
    args: items to be converted to the `instance` type.

  Returns:
    `args` with the type of `instance`.
  """
    if _is_mutable_mapping(instance):
        result = dict(zip(_tf_core_sorted(instance), args))
        instance_type = type(instance)
        if instance_type == _collections.defaultdict:
            d = _collections.defaultdict(instance.default_factory)
        else:
            d = instance_type()
        for key in instance:
            d[key] = result[key]
        return d
    elif _is_mapping(instance):
        result = dict(zip(_tf_core_sorted(instance), args))
        instance_type = type(instance)
        if <MASK>:
            tf_logging.log_first_n(tf_logging.WARN, 'Mapping types may not work well with tf.nest. Prefer using MutableMapping for {}'.format(instance_type), 1)
        try:
            return instance_type(((key, result[key]) for key in instance))
        except TypeError as err:
            raise TypeError('Error creating an object of type {} like {}. Note that it must accept a single positional argument representing an iterable of key-value pairs, in addition to self. Cause: {}'.format(type(instance), instance, err))
    elif _is_mapping_view(instance):
        return list(args)
    elif is_namedtuple(instance) or _is_attrs(instance):
        if isinstance(instance, _wrapt.ObjectProxy):
            instance_type = type(instance.__wrapped__)
        else:
            instance_type = type(instance)
        return instance_type(*args)
    elif _is_composite_tensor(instance):
        assert len(args) == 1
        spec = instance._type_spec
        return spec._from_components(args[0])
    elif _is_type_spec(instance):
        assert len(args) == 1
        return instance._from_components(args[0])
    elif isinstance(instance, range):
        return sequence_like(list(instance), args)
    elif isinstance(instance, _wrapt.ObjectProxy):
        return type(instance)(sequence_like(instance.__wrapped__, args))
    elif isinstance(instance, CustomNestProtocol):
        metadata = instance.__tf_flatten__()[0]
        return instance.__tf_unflatten__(metadata, tuple(args))
    else:
        return type(instance)(args)

def get_geometry_converter(self, expression):
    read = wkb_r().read
    srid = expression.output_field.srid
    if <MASK>:
        srid = None
    geom_class = expression.output_field.geom_class

    def converter(value, expression, connection):
        if value is not None:
            geom = GEOSGeometryBase(read(memoryview(value)), geom_class)
            if srid:
                geom.srid = srid
            return geom
    return converter

def install_config_module(module: ModuleType) -> None:
    """
    Converts a module-level config into a `ConfigModule()`.

    See _config_typing.pyi for instructions on how to get the converted module to typecheck.
    """

    class ConfigModuleInstance(ConfigModule):
        _bypass_keys = set({'_is_dirty', '_hash_digest', '__annotations__'})

    def visit(source: Union[ModuleType, type], dest: Union[ModuleType, SubConfigProxy], prefix: str) -> None:
        """Walk the module structure and move everything to module._config"""
        type_hints = inspect.get_annotations(source)
        for (key, value) in list(source.__dict__.items()):
            if key.startswith('__') or isinstance(value, (ModuleType, FunctionType)) or (hasattr(value, '__module__') and value.__module__ == 'typing') or (isinstance(value, type) and issubclass(value, _Config)):
                continue
            name = f'{prefix}{key}'
            annotated_type = type_hints.get(key, None)
            if isinstance(value, CONFIG_TYPES):
                config[name] = _ConfigEntry(_Config(default=value, value_type=annotated_type))
                if dest is module:
                    delattr(module, key)
            elif isinstance(value, _Config):
                if <MASK>:
                    value.value_type = annotated_type
                config[name] = _ConfigEntry(value)
                if dest is module:
                    delattr(module, key)
            elif isinstance(value, type):
                assert value.__module__ == module.__name__
                proxy = SubConfigProxy(module, f'{name}.')
                visit(value, proxy, f'{name}.')
                if dest is module:
                    setattr(dest, key, proxy)
                else:
                    dest.__dict__[key] = proxy
            else:
                raise AssertionError(f'Unhandled config {key}={value} ({type(value)})')
    config: dict[str, _ConfigEntry] = {}
    compile_ignored_keys = get_assignments_with_compile_ignored_comments(module)
    visit(module, module, '')
    module._config = config
    module._compile_ignored_keys = compile_ignored_keys
    module.__class__ = ConfigModuleInstance
    module._is_dirty = True
    module._hash_digest = None

def test_method_w_self_as_arg(self):
    x = 1

    class Foo:

        def f(self):
            return self.g(self)

        def g(self, obj):
            if <MASK>:
                return x
            else:
                return -x
    foo = Foo()
    func_map = free_vars_detect._detect_function_free_vars(foo.f)
    self.assertLen(func_map.keys(), 2)
    self.assertIn('Foo.f', func_map.keys())
    free_vars = get_var_name(func_map['Foo.f'])
    self.assertSequenceEqual(free_vars, ['self.g'])
    self.assertIn('Foo.g', func_map.keys())
    free_vars = get_var_name(func_map['Foo.g'])
    self.assertSequenceEqual(free_vars, ['x'])

