def __getitem__(self, key):
    check_dict_or_set_indexers(key)
    key = lib.item_from_zerodim(key)
    key = com.apply_if_callable(key, self)
    if is_hashable(key) and (not is_iterator(key)) and (not isinstance(key, slice)):
        is_mi = isinstance(self.columns, MultiIndex)
        if not is_mi and (self.columns.is_unique and key in self.columns or key in self.columns.drop_duplicates(keep=False)):
            return self._get_item(key)
        elif is_mi and self.columns.is_unique and (key in self.columns):
            return self._getitem_multilevel(key)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    if isinstance(key, DataFrame):
        return self.where(key)
    if com.is_bool_indexer(key):
        return self._getitem_bool_array(key)
    is_single_key = isinstance(key, tuple) or not is_list_like(key)
    if <MASK>:
        if self.columns.nlevels > 1:
            return self._getitem_multilevel(key)
        indexer = self.columns.get_loc(key)
        if is_integer(indexer):
            indexer = [indexer]
    else:
        if is_iterator(key):
            key = list(key)
        indexer = self.columns._get_indexer_strict(key, 'columns')[1]
    if getattr(indexer, 'dtype', None) == bool:
        indexer = np.where(indexer)[0]
    if isinstance(indexer, slice):
        return self._slice(indexer, axis=1)
    data = self.take(indexer, axis=1)
    if is_single_key:
        if data.shape[1] == 1 and (not isinstance(self.columns, MultiIndex)):
            return data._get_item(key)
    return data

def get_center_of_mass(comass: float | None, span: float | None, halflife: float | None, alpha: float | None) -> float:
    valid_count = common.count_not_none(comass, span, halflife, alpha)
    if valid_count > 1:
        raise ValueError('comass, span, halflife, and alpha are mutually exclusive')
    if comass is not None:
        if comass < 0:
            raise ValueError('comass must satisfy: comass >= 0')
    elif <MASK>:
        if span < 1:
            raise ValueError('span must satisfy: span >= 1')
        comass = (span - 1) / 2
    elif halflife is not None:
        if halflife <= 0:
            raise ValueError('halflife must satisfy: halflife > 0')
        decay = 1 - np.exp(np.log(0.5) / halflife)
        comass = 1 / decay - 1
    elif alpha is not None:
        if alpha <= 0 or alpha > 1:
            raise ValueError('alpha must satisfy: 0 < alpha <= 1')
        comass = (1 - alpha) / alpha
    else:
        raise ValueError('Must pass one of comass, span, halflife, or alpha')
    return float(comass)

def get_summarized_data(self):
    dim = self.dim()
    if dim == 0:
        return self
    if dim == 1:
        if <MASK>:
            return torch.cat((self[:PRINT_OPTS.edgeitems], self[-PRINT_OPTS.edgeitems:]))
        else:
            return self
    if not PRINT_OPTS.edgeitems:
        return self.new_empty([0] * self.dim())
    elif self.size(0) > 2 * PRINT_OPTS.edgeitems:
        start = [self[i] for i in range(PRINT_OPTS.edgeitems)]
        end = [self[i] for i in range(len(self) - PRINT_OPTS.edgeitems, len(self))]
        return torch.stack([get_summarized_data(x) for x in start + end])
    else:
        return torch.stack([get_summarized_data(x) for x in self])

def assertTupleShape(self, shape, expected):
    self.assertEqual(shape.element_type, xla_data_pb2.TUPLE)
    for (sub_shape, sub_expected) in zip(shape.tuple_shapes, expected):
        if <MASK>:
            self.assertTupleShape(sub_shape, sub_expected)
        else:
            (expected_dimensions, expected_element_types) = sub_expected
            self.assertShape(sub_shape, expected_dimensions, expected_element_types)

def broadcast_dynamic_shape_extended(a: DynamicRaggedShape, b: DynamicRaggedShape):
    """Gets the smallest shape to which a and b can broadcast.

  In order to create the smallest shape, one must also do most of the
  work to figure out how to transform from the shapes given. Thus, in addition
  to returning the shape, it also creates transformations from the
  original shapes to the result.

  This is the equivalent of:

  c = broadcast_dynamic_shape(a, b)
  ac = get_broadcaster(a, c)
  bc = get_broadcaster(b, c)
  return (c, ac, bc)

  Args:
    a: a DynamicRaggedShape
    b: a DynamicRaggedShape

  Returns:
    A triple of a shape and two broadcasters.
  """
    if a.row_partitions and b.row_partitions:
        if a.dtype != b.dtype:
            raise ValueError("Dtypes don't match")
    elif a.dtype != b.dtype:
        if a.row_partitions:
            b = b.with_dtype(a.dtype)
        elif b.row_partitions:
            a = a.with_dtype(b.dtype)
        else:
            a = a.with_dtype(dtypes.int64)
            b = b.with_dtype(dtypes.int64)
    if <MASK>:
        raise ValueError('Unable to broadcast: unknown rank')
    elif a.rank == 0:
        return (b, _Broadcaster(a, b, []), _get_identity_broadcaster(b))
    elif b.rank == 0:
        return (a, _get_identity_broadcaster(a), _Broadcaster(b, a, []))
    elif a.rank == 1 and b.rank == 1:
        [a_layer, b_layer, target] = _broadcast_dynamic_shape_one_layer(a.inner_shape, b.inner_shape)
        target_shape = DynamicRaggedShape._from_inner_shape(target)
        return (target_shape, _Broadcaster(a, target_shape, [a_layer]), _Broadcaster(b, target_shape, [b_layer]))
    if a.rank > b.rank:
        (c, bc, ac) = _broadcast_dynamic_shape_extended_helper(b, a)
        return (c, ac, bc)
    return _broadcast_dynamic_shape_extended_helper(a, b)

def run_with_input_iter(bench_cls, input_iter, allow_skip=True):
    tensor_dim_specs = input_iter.split(',')
    tensor_dim_specs = [dim.split(':') for dim in tensor_dim_specs]
    configs = []
    for (start, stop, inc) in tensor_dim_specs:
        dim_list = []
        if inc == 'pow2':
            curr = int(start)
            while curr <= int(stop):
                dim_list.append(curr)
                curr <<= 1
        elif <MASK>:
            curr = int(start)
            while curr <= int(stop):
                dim_list.append(curr)
                curr -= 1
                curr <<= 1
                curr += 1
        else:
            dim_list = list(range(int(start), int(stop) + int(inc), int(inc)))
        configs.append(dim_list)
    configs = itertools.product(*configs)
    for (mode, device, dtype, config) in itertools.product(modes, devices, datatypes, list(configs)):
        bench = bench_cls(mode, device, dtype, *config)
        bench.output_type = args.output
        bench.jit_mode = args.jit_mode
        if not bench.is_supported():
            if allow_skip:
                continue
            else:
                raise ValueError(f'attempted to run an unsupported benchmark: {bench.desc()}')
        bench.run(args)

def fuzz_op(target_spec: Spec, depth, stack_size, template: str='default', supported_ops: Optional[list[str]]=None) -> tuple[str, list[Spec]]:
    """
    Given an output specification, returns an operation that can
    produce a tensor with that layout using the operator class system.

    Args:
        target_spec: Desired output specification (TensorSpec or ScalarSpec)
        depth: Maximum depth for operation generation. At depth 0, only leaf operations
               (constant, arg) are allowed. Higher depths allow more complex operations.
        stack_size: Current stack size. When < 10, reduces probability of leaf operations.

    Returns:
        Tuple of (operation_name, list_of_argument_specs) where each argument spec
        describes the layout requirements for the operation's inputs
    """
    available_operators = _get_template_filtered_operators(template, supported_ops)
    compatible_ops = []
    for op_name in sorted(available_operators.keys()):
        operator = available_operators[op_name]
        if operator.can_produce(target_spec):
            compatible_ops.append((op_name, operator))
    random.shuffle(compatible_ops)
    if not compatible_ops:
        raise ValueError(f'No operators available that can produce {target_spec}')
    leaf_ops = []
    non_leaf_ops = []
    for (op_name, operator) in compatible_ops:
        if op_name in ['constant', 'arg'] or op_name.startswith('arg_'):
            leaf_ops.append((op_name, operator))
        else:
            non_leaf_ops.append((op_name, operator))
    if depth == 0:
        if <MASK>:
            return _get_arg_args_specs(target_spec)
        leaf_weights = [op.get_weight(target_spec=target_spec, depth=depth, stack_size=stack_size, template=template) for (_, op) in leaf_ops]
        idx = random.choices(range(len(leaf_ops)), weights=leaf_weights, k=1)[0]
        (chosen_op_name, chosen_operator) = leaf_ops[idx]
    elif (stack_size < 10 or depth > 7) and non_leaf_ops:
        if random.random() < 0.8:
            nonleaf_weights = [op.get_weight(target_spec=target_spec, depth=depth, stack_size=stack_size, template=template) for (_, op) in non_leaf_ops]
            idx = random.choices(range(len(non_leaf_ops)), weights=nonleaf_weights, k=1)[0]
            (chosen_op_name, chosen_operator) = non_leaf_ops[idx]
        elif leaf_ops:
            leaf_weights = [op.get_weight(target_spec=target_spec, depth=depth, stack_size=stack_size, template=template) for (_, op) in leaf_ops]
            idx = random.choices(range(len(leaf_ops)), weights=leaf_weights, k=1)[0]
            (chosen_op_name, chosen_operator) = leaf_ops[idx]
        else:
            nonleaf_weights = [op.get_weight(target_spec=target_spec, depth=depth, stack_size=stack_size, template=template) for (_, op) in non_leaf_ops]
            idx = random.choices(range(len(non_leaf_ops)), weights=nonleaf_weights, k=1)[0]
            (chosen_op_name, chosen_operator) = non_leaf_ops[idx]
    else:
        all_ops = non_leaf_ops + leaf_ops
        if all_ops:
            all_weights = [op.get_weight(target_spec=target_spec, depth=depth, stack_size=stack_size, template=template) for (_, op) in all_ops]
            idx = random.choices(range(len(all_ops)), weights=all_weights, k=1)[0]
            (chosen_op_name, chosen_operator) = all_ops[idx]
        else:
            (chosen_op_name, chosen_operator) = ('arg', get_operator('arg'))
    if chosen_operator is None:
        return _get_arg_args_specs(target_spec)
    input_specs = chosen_operator.fuzz_inputs_specs(target_spec)
    return (chosen_op_name, input_specs)

def _is_empty_container(self, node: ast.AST, ann_type: str) -> bool:
    if ann_type == 'List':
        if <MASK>:
            return False
        if node.elts:
            return False
    elif ann_type == 'Dict':
        if not isinstance(node, ast.Dict):
            return False
        if node.keys:
            return False
    elif ann_type == 'Optional':
        if not isinstance(node, ast.Constant):
            return False
        if node.value:
            return False
    return True

def render(self, context):
    compiled_parent = self.get_parent(context)
    if <MASK>:
        context.render_context[BLOCK_CONTEXT_KEY] = BlockContext()
    block_context = context.render_context[BLOCK_CONTEXT_KEY]
    block_context.add_blocks(self.blocks)
    for node in compiled_parent.nodelist:
        if not isinstance(node, TextNode):
            if not isinstance(node, ExtendsNode):
                blocks = {n.name: n for n in compiled_parent.nodelist.get_nodes_by_type(BlockNode)}
                block_context.add_blocks(blocks)
            break
    with context.render_context.push_state(compiled_parent, isolated_context=False):
        return compiled_parent._render(context)

def use_cpp_gemm_template(layout: Layout, mat1: IRNode, mat2: IRNode, mat2_transposed: bool=False, require_constant_mat2: bool=True, is_woq_int4: bool=False, q_group_size: Optional[int]=None) -> bool:
    from . import ir
    from .codegen.cpp_micro_gemm import create_micro_gemm
    from .codegen.cpp_utils import get_gemm_template_output_and_compute_dtype
    from .kernel.mm_common import mm_args
    if not _use_template_for_cpu(layout) or not _use_autotune_backend('CPP'):
        return False
    if <MASK>:
        return False
    int8_gemm = mat1.get_dtype() in [torch.uint8, torch.int8]
    layout_dtypes = [torch.float32, torch.bfloat16, torch.half, torch.uint8]
    (m, n, k, layout, mat1, mat2) = mm_args(mat1, mat2, out_dtype=layout.dtype if int8_gemm else None, mat2_transposed=mat2_transposed, use_4x2_dim=is_woq_int4)
    if has_free_symbols((n, k)):
        return False
    if isinstance(mat2, ir.BaseView):
        mat2 = mat2.unwrap_view()
    (output_dtype, _) = get_gemm_template_output_and_compute_dtype(mat1.get_dtype())
    micro_gemm = create_micro_gemm('micro_gemm', m, n, k, input_dtype=mat1.get_dtype(), input2_dtype=mat2.get_dtype(), output_dtype=output_dtype, num_threads=parallel_num_threads(), use_ref=not is_woq_int4, q_group_size=q_group_size)

    def is_last_dim_stride1(x: IRNode) -> bool:
        x.freeze_layout()
        return x.get_stride()[-1] == 1
    return layout.dtype in layout_dtypes and micro_gemm is not None and is_last_dim_stride1(mat1) and isinstance(mat2, ir.StorageBox) and (mat2.is_module_buffer() or not require_constant_mat2)

def getcallprotoargument(rout, cb_map={}):
    r = getmultilineblock(rout, 'callprotoargument', comment=0)
    if r:
        return r
    if hascallstatement(rout):
        outmess('warning: callstatement is defined without callprotoargument\n')
        return
    from .capi_maps import getctype
    (arg_types, arg_types2) = ([], [])
    if l_and(isstringfunction, l_not(isfunction_wrap))(rout):
        arg_types.extend(['char*', 'size_t'])
    for n in rout['args']:
        var = rout['vars'][n]
        if isintent_callback(var):
            continue
        if n in cb_map:
            ctype = cb_map[n] + '_typedef'
        else:
            ctype = getctype(var)
            if l_and(isintent_c, l_or(isscalar, iscomplex))(var):
                pass
            elif isstring(var):
                pass
            elif not isattr_value(var):
                ctype = ctype + '*'
            if isstring(var) or isarrayofstrings(var) or isstringarray(var):
                arg_types2.append('size_t')
        arg_types.append(ctype)
    proto_args = ','.join(arg_types + arg_types2)
    if <MASK>:
        proto_args = 'void'
    return proto_args

def _einsum_v1(equation, *inputs, **kwargs):
    """Legacy implementation of einsum without using EinsumOp."""
    name = kwargs.pop('name', None)
    if kwargs:
        raise TypeError(f"Invalid keyword arguments for this function: {', '.join([format(key) for key in sorted(list(kwargs.keys()))])}. Expected: name.")
    with ops.name_scope(name, 'einsum', [equation, inputs]) as name:
        inputs = list(inputs)
        input_shapes = [x.shape for x in inputs]
        (input_axis_labels, output_axis_labels) = _einsum_v1_parse_and_resolve_equation(equation, input_shapes)
        axis_labels = set(''.join(input_axis_labels) + output_axis_labels)
        for a in axis_labels:
            for input_labels in input_axis_labels:
                if len(input_axis_labels) == 1 and input_labels.count(a) == 2 and (input_labels == input_labels[::-1]) and ('->' not in equation):
                    return math_ops.trace(inputs[0])
                if <MASK>:
                    raise ValueError(f'Subscript not supported: the axis {a} appears more than once in {input_labels}.')
        for a in axis_labels:
            input_count = sum((1 for s in input_axis_labels if a in s))
            if input_count > 2 and a not in output_axis_labels:
                logging.warn(f'Falling back to exponential-space implementation of einsum() because index {a} is summed over more than two inputs.')
                return _exponential_space_einsum_v1(equation, *inputs)
        if _enclosing_tpu_context() is not None and len(inputs) == 2:
            return gen_xla_ops.xla_einsum(inputs[0], inputs[1], input_axis_labels[0] + ',' + input_axis_labels[1] + '->' + output_axis_labels)
        temp = inputs[0]
        temp_axis_labels = input_axis_labels[0]
        for i in range(len(inputs) - 1):
            axes_to_sum = set(temp_axis_labels) & set(input_axis_labels[i + 1]) - set(output_axis_labels)
            (temp, temp_axis_labels) = _einsum_v1_reduction(temp, temp_axis_labels, inputs[i + 1], input_axis_labels[i + 1], axes_to_sum)
        missing_indices = set(temp_axis_labels) - set(output_axis_labels)
        if missing_indices:
            axis = [i for (i, a) in enumerate(temp_axis_labels) if a not in output_axis_labels]
            temp = math_ops.reduce_sum(temp, axis=axis)
            temp_axis_labels = ''.join((a for a in temp_axis_labels if a in output_axis_labels))
        if sorted(temp_axis_labels) != sorted(output_axis_labels):
            raise ValueError(f'Invalid equation: {equation}. The computed and specified output labels do not match: {temp_axis_labels} vs {output_axis_labels}.')
        perm = [temp_axis_labels.index(a) for a in output_axis_labels]
        return _transpose_if_necessary(temp, perm)

def find_missing_items(model_items, key, selected_models_yaml):
    missing_items = []
    if not new_style_rule or not model_items:
        return missing_items
    for item in model_items:
        found = False
        for model in selected_models_yaml:
            if str(model['model'][key]) == item:
                found = True
        if <MASK>:
            missing_items.append(item)
    return missing_items

def find_shape(path, t):
    t_id = id(t)
    if <MASK>:
        t_ids.add(t_id)
        return self._shapes[t_id]
    else:
        return None

def impl_arguments(g: NativeFunctionsGroup) -> list[Binding]:
    args: list[Argument | TensorOptionsArguments | SelfArgument] = []
    if g.out.precomputed:
        non_out_args_replaced: list[Argument | TensorOptionsArguments | SelfArgument] = []
        for a in g.out.func.arguments.non_out:
            if <MASK>:
                non_out_args_replaced.extend(g.out.precomputed.replace[a.name])
            else:
                non_out_args_replaced.append(a)
        args.extend(non_out_args_replaced)
        args.extend(g.out.precomputed.add)
    else:
        args.extend(g.out.func.arguments.non_out)
    args.extend(g.out.func.arguments.out)
    return [r for arg in args for r in argument(arg)]

def bound_sympy(self, expr: sympy.Expr, size_oblivious: bool=False) -> ValueRanges:
    """Given a sympy expression, computes a ValueRanges bound for what values it can be"""
    var_to_range = {x: self.var_to_range.get(x, None) for x in expr.free_symbols}
    if size_oblivious:
        for x in self.size_like & var_to_range.keys():
            if <MASK>:
                var_to_range[x] = ValueRanges(2, int_oo)
    return bound_sympy(expr, var_to_range)

def _initialize_stages(self, args: tuple[Any, ...], kwargs):
    if not self._stages_forward_initialized:
        all_ops: list[dist.P2POp] = []
        for stage in self._stages:
            all_ops.extend(stage._get_init_p2p_neighbors_ops())
        _wait_batch_p2p(_batch_p2p(all_ops))
        next_stage_args: tuple[Any, ...] = tuple()
        for stage in self._stages:
            if <MASK>:
                next_stage_args = stage._prepare_forward_infra(self._n_microbatches, args, kwargs)
            else:
                next_stage_args = stage._prepare_forward_infra(self._n_microbatches, next_stage_args, kwargs)
        self._stages_forward_initialized = True
    if self._has_backward and (not self._stages_backward_initialized):
        for stage in self._stages:
            stage._prepare_backward_infra(self._n_microbatches)
        self._stages_backward_initialized = True

def _gather_and_copy(acceptance_prob, data):
    if <MASK>:
        class_val = class_func(*data)
    else:
        class_val = class_func(data)
    return (class_val, array_ops.gather(acceptance_prob, class_val), data)

def build_graph(parameters):
    """Build a batch_to_space graph given `parameters`."""
    input_tensor = tf.compat.v1.placeholder(dtype=parameters['dtype'], name='input', shape=parameters['input_shape'])
    input_tensors = [input_tensor]
    if <MASK>:
        block_shape = parameters['block_shape']
    else:
        shape = [len(parameters['block_shape'])]
        block_shape = tf.compat.v1.placeholder(dtype=tf.int32, name='shape', shape=shape)
        input_tensors.append(block_shape)
    if parameters['constant_crops']:
        crops = parameters['crops']
    else:
        shape = [len(parameters['crops']), 2]
        crops = tf.compat.v1.placeholder(dtype=tf.int32, name='crops', shape=shape)
        input_tensors.append(crops)
    out = tf.batch_to_space(input_tensor, block_shape, crops)
    return (input_tensors, [out])

def log_or_raise(self, msg: str) -> None:
    if <MASK>:
