def can_fuse(self, node1, node2):
    """
        Hook called by Scheduler to determine if the Triton backend
        can fuse node1 and node2.  These nodes might already be
        FusedSchedulerNodes.
        """
    if <MASK>:
        return scheduler.ForeachKernelSchedulerNode.can_fuse(node1, node2)
    (_, (numel1, rnumel1)) = node1.group
    (_, (numel2, rnumel2)) = node2.group
    why = WhyNoFuse(node1, node2)
    if node1.is_split_scan() and (not node2.is_split_scan()):
        if node2.is_reduction():
            why('Split scan cannot fuse with reductions')
    elif node2.is_split_scan() and (not node1.is_split_scan()):
        if node1.is_reduction():
            why('Split scan cannot fuse with reductions')
    if node1.is_reduction() and node2.is_reduction():
        reduction_can_fuse = numel1 == numel2 and rnumel1 == rnumel2
        if not reduction_can_fuse:
            why('numel/rnumel mismatch (reduce) (%s, %s), (%s, %s)', numel1, numel2, rnumel1, rnumel2)
        if reduction_can_fuse and (node1.is_native_matmul() or node2.is_native_matmul()):
            if not node1.is_native_matmul():
                (node1, node2) = (node2, node1)
            tiling = self.select_tiling(node1.get_nodes(), numel1, rnumel1)
            if not all((SIMDKernel.is_compatible(tiling.values(), n2.get_ranges(), reduction_numel=rnumel1) for n2 in node2.get_nodes())):
                why('invalid loop order and tiling for native matmul')
                return False
        return reduction_can_fuse
    if not node1.is_reduction() and (not node2.is_reduction()):
        if not (numel1 == numel2 and rnumel1 == rnumel2):
            if not node2.is_template():
                why('numel/rnumel mismatch (non-reduce) (%s, %s), (%s, %s)', numel1, numel2, rnumel1, rnumel2)
                return False
            else:
                for node in node2.get_nodes():
                    if node.is_template():
                        break
                    if not node.used_buffer_names() & node1.get_buffer_names():
                        continue
                    (_, (pro_numel, pro_rnumel)) = node.group
                    if not (numel1 == pro_numel and rnumel1 == pro_rnumel):
                        why('numel/rnumel mismatch prologue mismatch (%s, %s), (%s, %s)', numel1, pro_numel, rnumel1, pro_rnumel)
                        return False
        for n in (node1, node2):
            if n.is_template():
                return True
        tiling1 = self.select_tiling(node1.get_nodes(), numel1, rnumel1)
        tiling2 = self.select_tiling(node2.get_nodes(), numel1, rnumel1)
        tiling3 = self.select_tiling(node1.get_nodes() + node2.get_nodes(), numel1, rnumel1)
        if config.triton.tiling_prevents_pointwise_fusion:
            cond = True
            if len(tiling1) > 2:
                if len(tiling2) > 2:
                    cond = tiling1 == tiling2 == tiling3
                else:
                    cond = tiling1 == tiling3
            elif len(tiling2) > 2:
                cond = tiling2 == tiling3
            if not cond:
                why('tiling mismatch (%s, %s, %s)', tiling1, tiling2, tiling3)
                return False
        return True
    if not node1.is_reduction() and node2.is_reduction():
        assert rnumel1 == 1 and rnumel2 != 1
        if numel1 == numel2 * rnumel2:
            if not all((SIMDKernel.is_compatible((numel2, rnumel2), n.get_ranges()) for n in node1.get_nodes())):
                why('nodes numel/rnumel incompatibility')
                return False
            if config.triton.tiling_prevents_reduction_fusion and (not node1.is_template()):
                is_reduction_tiling_valid = tuple(self.select_tiling(node1.get_nodes(), numel1).values()) in ((numel1, 1), (numel2, rnumel2, 1))
                if not is_reduction_tiling_valid:
                    why('invalid tiling for reduction')
                return is_reduction_tiling_valid
            return True
        if numel1 != numel2:
            why('nodes numel incompatibility')
        return numel1 == numel2
    assert node1.is_reduction() and (not node2.is_reduction())
    return self.can_fuse_horizontal(node2, node1)

def _ctc_loss_impl(labels, inputs=None, sequence_length=None, preprocess_collapse_repeated=False, ctc_merge_repeated=True, ignore_longer_outputs_than_inputs=False, time_major=True, logits=None, use_cudnn=False):
    if not isinstance(labels, sparse_tensor.SparseTensor):
        raise TypeError(f'Expected argument `labels` to be a SparseTensor. Received labels={labels} of type: {type(labels).__name__}')
    inputs = deprecation.deprecated_argument_lookup('logits', logits, 'inputs', inputs)
    inputs = ops.convert_to_tensor(inputs, name='logits')
    if not time_major:
        inputs = array_ops.transpose(inputs, [1, 0, 2])
    orig_dtype = inputs.dtype
    if <MASK>:
        inputs = math_ops.cast(inputs, dtypes.float32)
    if use_cudnn:
        ctc_loss_func = gen_ctc_ops.ctc_loss_v2
    else:
        ctc_loss_func = gen_ctc_ops.ctc_loss
    (loss, _) = ctc_loss_func(inputs, labels.indices, labels.values, sequence_length, preprocess_collapse_repeated=preprocess_collapse_repeated, ctc_merge_repeated=ctc_merge_repeated, ignore_longer_outputs_than_inputs=ignore_longer_outputs_than_inputs)
    if orig_dtype in (dtypes.float16, dtypes.bfloat16):
        loss = math_ops.cast(loss, orig_dtype)
    return loss

