    if <MASK>:
        other_type = f"dtype '{other.dtype}'"
    else:
        other_type = f'object of type {type(other)}'
    return f"operation '{op.__name__}' not supported for dtype '{self.dtype}' with {other_type}"

def argumenttype_ivalue_convert(t: Type, arg_name: str, *, mutable: bool=False) -> tuple[str, CType, list[str], list[str]]:
    ctype = cpp.argumenttype_type(t=t, mutable=mutable, binds=arg_name, symint=False).type
    if isinstance(t, BaseType):
        out_name = f'{arg_name}_base'
        (code, decl) = _gen_code_base_type(arg_name=arg_name, out_name=out_name, ctype=ctype)
    elif isinstance(t, OptionalType):
        out_name = f'{arg_name}_opt_out'
        (code, decl) = _gen_code_optional_type(arg_name=arg_name, out_name=out_name, t=t, ctype=ctype)
    elif <MASK>:
        out_name = f'{arg_name}_list_out'
        (code, decl) = _gen_code_list_type(arg_name=arg_name, out_name=out_name, t=t, ctype=ctype)
    else:
        raise Exception(f'Cannot handle type {t}. arg_name: {arg_name}')
    return (out_name, ctype, code, decl)

def graph_returns_tuple(gm: GraphModule) -> bool:
    """True if a FX graph returns a tuple"""
    if not isinstance(gm, GraphModule):
        return True
    (rv,) = output_node(gm).args
    if <MASK>:
        return True
    if isinstance(rv, torch.fx.node.Node) and hasattr(rv.target, '_schema') and (len(rv.target._schema.returns) > 1) and all((str(ret.type) == 'Tensor' for ret in rv.target._schema.returns)):
        return True
    return False

def as_widget(self, widget=None, attrs=None, only_initial=False):
    """
        Render the field by rendering the passed widget, adding any HTML
        attributes passed as attrs. If a widget isn't specified, use the
        field's default widget.
        """
    widget = widget or self.field.widget
    if self.field.localize:
        widget.is_localized = True
    attrs = attrs or {}
    attrs = self.build_widget_attrs(attrs, widget)
    if self.auto_id and 'id' not in widget.attrs:
        attrs.setdefault('id', self.html_initial_id if only_initial else self.auto_id)
    if <MASK>:
        value = self.form._widget_data_value(self.field.hidden_widget(), self.html_initial_name)
    else:
        value = self.value()
    return widget.render(name=self.html_initial_name if only_initial else self.html_name, value=value, attrs=attrs, renderer=self.form.renderer)

def compute_output_shape(self, input_shape):
    input_shape = tensor_shape.TensorShape(input_shape).as_list()
    output_shape = list(input_shape)
    if self.data_format == 'channels_first':
        (c_axis, t_axis) = (1, 2)
    else:
        (c_axis, t_axis) = (2, 1)
    if <MASK>:
        output_padding = None
    else:
        output_padding = self.output_padding[0]
    output_shape[c_axis] = self.filters
    output_shape[t_axis] = conv_utils.deconv_output_length(output_shape[t_axis], self.kernel_size[0], padding=self.padding, output_padding=output_padding, stride=self.strides[0], dilation=self.dilation_rate[0])
    return tensor_shape.TensorShape(output_shape)

def get_ordering(self, request, queryset):
    """
        Return the list of ordering fields for the change list.
        First check the get_ordering() method in model admin, then check
        the object's default ordering. Then, any manually-specified ordering
        from the query string overrides anything. Finally, a deterministic
        order is guaranteed by calling _get_deterministic_ordering() with the
        constructed ordering.
        """
    params = self.params
    ordering = list(self.model_admin.get_ordering(request) or self._get_default_ordering())
    if params.get(ORDER_VAR):
        ordering = []
        order_params = params[ORDER_VAR].split('.')
        for p in order_params:
            try:
                (none, pfx, idx) = p.rpartition('-')
                field_name = self.list_display[int(idx)]
                order_field = self.get_ordering_field(field_name)
                if not order_field:
                    continue
                if isinstance(order_field, OrderBy):
                    if pfx == '-':
                        order_field = order_field.copy()
                        order_field.reverse_ordering()
                    ordering.append(order_field)
                elif hasattr(order_field, 'resolve_expression'):
                    ordering.append(order_field.desc() if pfx == '-' else order_field.asc())
                elif <MASK>:
                    ordering.append(order_field.removeprefix(pfx))
                else:
                    ordering.append(pfx + order_field)
            except (IndexError, ValueError):
                continue
    ordering.extend(queryset.query.order_by)
    return self._get_deterministic_ordering(ordering)

def outer_config_opt():
    (max_x_block, x_block) = (256, 64)
    load_factor = inductor_meta.get('num_load', 0)
    x = size_hints['x']
    num_warps = None
    if x <= 1024:
        x_block = max(min(x // 128, 8), 2)
        outer_r_block = min(rnumel, 64)
    elif x // 4096 <= 8:
        x_block = 16
        outer_r_block = 512 // x_block
    elif num_dynamic > 1:
        outer_r_block = max(min(rnumel // 64, 64), 8)
    elif <MASK>:
        outer_r_block = 1 if load_factor >= 3 else min(next_power_of_2(max(rnumel, 128) // 128), 8)
    else:
        x_block = max(min(max_x_block, next_power_of_2(x // 4096)), x_block)
        if load_factor < 4 or rnumel <= 128:
            outer_r_block = 512 // x_block
        else:
            if rnumel >= 2048:
                outer_r_block = 64
            else:
                outer_r_block = 32
            x_block = min(x_block, 32)
            num_warps = 4
    return make_config(x_block, outer_r_block, num_warps=num_warps, register_intensive=register_intensive)

def _lookup_inner(obj: Any, name: Optional[str]=None, filename: Optional[str]=None, is_direct_call: bool=True, reasons: Optional[set[str]]=None) -> Optional[type[VariableTracker]]:
    try:
        can_hash = hashable(obj)
    except Exception:
        can_hash = False
    if not can_hash:
        if reasons is not None:
            reasons.add('obj is not hashable')
        return None
    if obj is not None:
        if is_aten_op_or_tensor_method(obj):
            return TorchInGraphFunctionVariable
        rule = get_torch_obj_rule_map().get(obj, None)
        if rule is not None:
            if reasons is not None:
                reasons.add('get_torch_obj_rule_map')
            return rule
    elif name is not None and filename is not None and (not is_direct_call):
        if name.startswith(TORCH_DYNAMO_RESUME_IN_PREFIX):
            rule = get_torch_obj_rule_map().get(filename + '#' + TORCH_DYNAMO_RESUME_IN_PREFIX, None)
        else:
            rule = get_torch_obj_rule_map().get(filename + '#' + name, None)
        if rule is not None:
            if reasons is not None:
                reasons.add('get_torch_obj_rule_map')
            return rule
    elif name == '<listcomp>':
        if reasons is not None:
            reasons.add('inlining frame from list comprehension')
        return UserFunctionVariable
    if is_direct_call:
        if name == 'patched_init':
            if reasons is not None:
                reasons.add('func name is patched_init')
            return SkipFunctionVariable
        elif name == '__torch_function__' or (obj and getattr(obj, '__name__', None) == '__torch_function__'):
            if reasons is not None:
                reasons.add('func name is __torch_function__')
            return UserFunctionVariable
    if not is_direct_call:
        if name == '__getattr__':
            if reasons is not None:
                reasons.add('Tracing __getattr__ as the top level frame, unsuitable for tracing.')
            return SkipFunctionVariable
    if <MASK>:
        filename = getfile(obj)
    skip_result = check_file(filename, is_direct_call)
    if reasons is not None and skip_result.reason is not None:
        reasons.add(skip_result.reason)
    if skip_result.skipped:
        return SkipFunctionVariable
    else:
        return UserFunctionVariable

def aggregate(metric_values: list[float], metric_name: str):
    """Aggregates metric values using a function based on the metric name.

  If metric name does not match any of the known patterns, the first value from
  the input list is returned.

  Args:
    metric_values: list of metric values, floats
    metric_name: metric name

  Returns:
    aggregated metric value
  """
    if str.endswith(metric_name, '.max'):
        return max(metric_values)
    if str.endswith(metric_name, '.min'):
        return min(metric_values)
    if <MASK>:
        return sum(metric_values)
    return metric_values[0]

def smoke_test_modules():
    cwd = os.getcwd()
    for module in MODULES:
        if module['repo']:
            if not os.path.exists(f"{cwd}/{module['repo_name']}"):
                print(f"Path does not exist: {cwd}/{module['repo_name']}")
                try:
                    subprocess.check_output(f"git clone --depth 1 {module['repo']}", stderr=subprocess.STDOUT, shell=True)
                except subprocess.CalledProcessError as exc:
                    raise RuntimeError(f"Cloning {module['repo']} FAIL: {exc.returncode} Output: {exc.output}") from exc
            try:
                smoke_test_command = f"python3 {module['smoke_test']}"
                if <MASK>:
                    smoke_test_command = f"python {module['smoke_test']}"
                output = subprocess.check_output(smoke_test_command, stderr=subprocess.STDOUT, shell=True, universal_newlines=True)
            except subprocess.CalledProcessError as exc:
                raise RuntimeError(f"Module {module['name']} FAIL: {exc.returncode} Output: {exc.output}") from exc
            else:
                print(f'Output: \n{output}\n')

def _gen_code_list_type(arg_name: str, out_name: str, t: ListType, ctype: CType) -> tuple[list[str], list[str]]:
    in_name = f'{arg_name}_list_in'
    elem_name = f'{arg_name}_elem'
    code = [f'const c10::List<c10::IValue> {in_name} = {arg_name}.toList();']
    (res_name, res_ctype, res_code, decl) = argumenttype_ivalue_convert(t.elem, elem_name)
    if <MASK>:
        code.extend(f'
{ctype.cpp_type(strip_ref=True)} {out_name} = as_array<{res_ctype.cpp_type(strip_ref=True)}, {t.size}>({in_name});
            '.split('
'))
    elif isinstance(t.elem, OptionalType):
        code.extend(f'
{ctype.cpp_type(strip_ref=True)} {out_name};
for (c10::IValue {elem_name}: {in_name}) {{
    {connector.join(res_code)}
    {out_name}.push_back({res_name});
}}
            '.split('
'))
    else:
        vec_name = arg_name + '_vec'
        decl.append(f'std::vector<{res_ctype.cpp_type(strip_ref=True)}> {vec_name};')
        code.extend(f'
for (c10::IValue {elem_name}: {in_name}) {{
    {connector.join(res_code)}
    {vec_name}.push_back({res_name});
}}
{ctype.cpp_type(strip_ref=True)} {out_name}({vec_name});
            '.split('
'))
    return (code, decl)

def _cached_call(cache, estimator, response_method, *args, **kwargs):
    """Call estimator with method and args and kwargs."""
    if <MASK>:
        return cache[response_method]
    (result, _) = _get_response_values(estimator, *args, response_method=response_method, **kwargs)
    if cache is not None:
        cache[response_method] = result
    return result

@tf_utils.shape_type_conversion
def compute_output_shape(self, input_shape):
    if not isinstance(input_shape, (tuple, list)) or len(input_shape) != 2:
        raise ValueError('A `Dot` layer should be called on a list of 2 inputs.')
    shape1 = list(input_shape[0])
    shape2 = list(input_shape[1])
    if isinstance(self.axes, int):
        if <MASK>:
            axes = [self.axes % len(shape1), self.axes % len(shape2)]
        else:
            axes = [self.axes] * 2
    else:
        axes = self.axes
    shape1.pop(axes[0])
    shape2.pop(axes[1])
    shape2.pop(0)
    output_shape = shape1 + shape2
    if len(output_shape) == 1:
        output_shape += [1]
    return tuple(output_shape)

def merge_single_node(node: Node, node_order: Optional[int], id: Optional[int]):

    def _update_partition_map(node: Node, id: int):
        for user_node in node.users:
            target_id = assignment.get(user_node)
            if <MASK>:
                partition_map[id].add(target_id)
                partition_map[id].update(partition_map[target_id])
    if node in assignment:
        partitions_by_id[assignment[node]].remove_node(node)
    if id is None:
        assignment.pop(node)
    elif id not in partitions_by_id:
        assignment[node] = id
        assert node_order is not None
        partitions_by_id[id] = Partition(id=id, nodes=[node], node_orders=[node_order])
        partition_users[id] = set(node.users)
        _update_partition_map(node, id)
    else:
        assignment[node] = id
        partitions_by_id[id].add_node(node, node_order)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    if <MASK>:
        if self.closed != values.closed:
            return np.zeros(self.shape, dtype=bool)
        if self.dtype == values.dtype:
            left = self._combined.view('complex128')
            right = values._combined.view('complex128')
            return np.isin(left, right).ravel()
        elif needs_i8_conversion(self.left.dtype) ^ needs_i8_conversion(values.left.dtype):
            return np.zeros(self.shape, dtype=bool)
    return isin(self.astype(object), values.astype(object))

