def protocol_df_chunk_to_pandas(df: DataFrameXchg) -> pd.DataFrame:
    """
    Convert interchange protocol chunk to ``pd.DataFrame``.

    Parameters
    ----------
    df : DataFrameXchg

    Returns
    -------
    pd.DataFrame
    """
    columns: dict[str, Any] = {}
    buffers = []
    for name in df.column_names():
        if <MASK>:
            raise ValueError(f'Column {name} is not a string')
        if name in columns:
            raise ValueError(f'Column {name} is not unique')
        col = df.get_column_by_name(name)
        dtype = col.dtype[0]
        if dtype in (DtypeKind.INT, DtypeKind.UINT, DtypeKind.FLOAT, DtypeKind.BOOL):
            (columns[name], buf) = primitive_column_to_ndarray(col)
        elif dtype == DtypeKind.CATEGORICAL:
            (columns[name], buf) = categorical_column_to_series(col)
        elif dtype == DtypeKind.STRING:
            (columns[name], buf) = string_column_to_ndarray(col)
        elif dtype == DtypeKind.DATETIME:
            (columns[name], buf) = datetime_column_to_ndarray(col)
        else:
            raise NotImplementedError(f'Data type {dtype} not handled yet')
        buffers.append(buf)
    pandas_df = pd.DataFrame(columns)
    pandas_df.attrs['_INTERCHANGE_PROTOCOL_BUFFERS'] = buffers
    return pandas_df

def try_get_nn_module_compiled_mod_and_inputs(*args, **kwargs):
    name = get_nn_module_name_from_kwargs(**kwargs)
    if 'desc' in kwargs and 'eval' in kwargs['desc']:
        return
    test_name = name
    if 'desc' in kwargs:
        test_name = f"{test_name}_{kwargs['desc']}"
    test_name = get_nn_mod_test_name(**kwargs)
    if test_name in EXCLUDE_SCRIPT_MODULES:
        return
    if 'constructor' in kwargs:
        nn_module = kwargs['constructor']
    else:
        nn_module = getattr(torch.nn, name)
    if <MASK>:
        return
    if 'constructor_args_fn' in kwargs:
        constructor_args = kwargs['constructor_args_fn']()
    else:
        constructor_args = kwargs.get('constructor_args', ())
    input_dtype = torch.double
    if 'input_fn' in kwargs:
        input = kwargs['input_fn']()
        if isinstance(input, torch.Tensor):
            input = (input,)
        if all((tensor.is_complex() for tensor in input)):
            input_dtype = torch.cdouble
    else:
        input = (kwargs['input_size'],)
    if 'extra_args' in kwargs:
        input = input + kwargs['extra_args']
    if 'target_size' in kwargs:
        input = input + (kwargs['target_size'],)
    elif 'target_fn' in kwargs:
        if torch.is_tensor(input):
            input = (input,)
        input = input + (kwargs['target_fn'](),)
    (args_variable, _kwargs_variable) = create_input(input, dtype=input_dtype)
    f_args_variable = deepcopy(unpack_variables(args_variable))
    out_var = deepcopy(f_args_variable)
    (_args, mod) = (f_args_variable, create_script_module(None, nn_module, constructor_args, *f_args_variable)(*f_args_variable))
    return (mod, out_var)

@torch_key_cache
def torch_key() -> bytes:
    """
    Compute a key that contains relevant information about torch source files
    """
    with dynamo_timed('inductor_codecache_torch_key', log_pt2_compile_event=False):
        if <MASK>:

            def get_code_hash(root: str) -> bytes:
                extra_files = ('codegen/aoti_runtime/interface.cpp', 'script.ld')
                inductor_root = os.path.dirname(__file__)
                extra_files = [os.path.join(inductor_root, x) for x in extra_files]
                hasher = hashlib.sha256()
                hasher.update(torch.__version__.encode('utf-8'))
                build_code_hash([root], '', hasher)
                for path in extra_files:
                    if os.path.exists(path):
                        with open(path, 'rb') as f:
                            hasher.update(f.read())
                return hasher.digest()
            return get_code_hash(_TORCH_PATH)
        from libfb.py import parutil
        return parutil.get_file_contents('torch/src_hash.txt').rstrip().encode('ascii')

