def test_partial_function(self):
    expected_test_arg = 123

    def fn_has_kwargs(test_arg, **x):
        if <MASK>:
            return ValueError('partial fn does not work correctly')
        return x
    wrapped_fn = functools.partial(fn_has_kwargs, test_arg=123)
    self.assertTrue(function_utils.has_kwargs(wrapped_fn))
    some_kwargs = dict(x=1, y=2, z=3)
    self.assertEqual(wrapped_fn(**some_kwargs), some_kwargs)

    def fn_has_no_kwargs(x, test_arg):
        if test_arg != expected_test_arg:
            return ValueError('partial fn does not work correctly')
        return x
    wrapped_fn = functools.partial(fn_has_no_kwargs, test_arg=123)
    self.assertFalse(function_utils.has_kwargs(wrapped_fn))
    some_arg = 1
    self.assertEqual(wrapped_fn(some_arg), some_arg)

def load(self):
    session_data = {}
    try:
        with open(self._key_to_file(), encoding='ascii') as session_file:
            file_data = session_file.read()
        if file_data:
            try:
                session_data = self.decode(file_data)
            except (EOFError, SuspiciousOperation) as e:
                if isinstance(e, SuspiciousOperation):
                    logger = logging.getLogger('django.security.%s' % e.__class__.__name__)
                    logger.warning(str(e))
                self.create()
            expiry_age = self.get_expiry_age(expiry=self._expiry_date(session_data))
            if <MASK>:
                session_data = {}
                self.delete()
                self.create()
    except (OSError, SuspiciousOperation):
        self._session_key = None
    return session_data

@ops.RegisterGradient('MatMul')
def _MatMulGrad(op: ops.Operation, grad):
    """Gradient for MatMul."""
    try:
        skip_input_indices = op.skip_input_indices
        if skip_input_indices is not None:
            if 1 in skip_input_indices:
                return _MatMulGradAgainstFirstOnly(op, grad)
            elif <MASK>:
                return _MatMulGradAgainstSecondOnly(op, grad)
    except AttributeError:
        pass
    t_a = op.get_attr('transpose_a')
    t_b = op.get_attr('transpose_b')
    a = math_ops.conj(op.inputs[0])
    b = math_ops.conj(op.inputs[1])
    if not t_a and (not t_b):
        grad_a = gen_math_ops.mat_mul(grad, b, transpose_b=True, grad_a=True)
        grad_b = gen_math_ops.mat_mul(a, grad, transpose_a=True, grad_b=True)
    elif not t_a and t_b:
        grad_a = gen_math_ops.mat_mul(grad, b, grad_a=True)
        grad_b = gen_math_ops.mat_mul(grad, a, transpose_a=True, grad_b=True)
    elif t_a and (not t_b):
        grad_a = gen_math_ops.mat_mul(b, grad, transpose_b=True, grad_a=True)
        grad_b = gen_math_ops.mat_mul(a, grad, grad_b=True)
    elif t_a and t_b:
        grad_a = gen_math_ops.mat_mul(b, grad, transpose_a=True, transpose_b=True, grad_a=True)
        grad_b = gen_math_ops.mat_mul(grad, a, transpose_a=True, transpose_b=True, grad_b=True)
    return (grad_a, grad_b)

