def export_memory_timeline_raw(self, path, device_str) -> None:
    """Saves the memory timeline as raw memory event tuples in the
        form of (timestamp, action, numbytes, category)
        as a JSON formatted file to the given path for the given
        device."""
    device = torch.device(device_str)
    raw_events: list[tuple[int, int, int, int]] = []

    def get_category_index(key, version):
        category = self.categories.get(key, version) if isinstance(key, TensorKey) else None
        return _CATEGORY_TO_INDEX[category]
    for (t, action, (key, version), numbytes) in self.timeline:
        if key.device != device:
            continue
        if <MASK>:
            raw_events.append((t, _ACTION_TO_INDEX[action], numbytes, get_category_index(key, version)))
        elif action == Action.INCREMENT_VERSION:
            raw_events.append((t, _ACTION_TO_INDEX[action], -numbytes, get_category_index(key, version)))
            raw_events.append((t, _ACTION_TO_INDEX[action], numbytes, get_category_index(key, version + 1)))
        elif action == Action.DESTROY:
            raw_events.append((t, _ACTION_TO_INDEX[action], -numbytes, get_category_index(key, version)))
        else:
            raise ValueError(f'Unknown action: {action}')
    import json
    with open(path, 'w') as f:
        json.dump(raw_events, f)

@register_graph_pattern(CallFunctionVarArgs(torch.unbind, users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('normalization_pass'))
@register_graph_pattern(CallMethodVarArgs('unbind', users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('normalization_pass'))
def normalize_unbind_default(match: Match, *args, **kwargs):
    node = match.nodes[0]
    graph = match.graph
    input = get_arg_value(node, 0, 'input')
    dim = get_arg_value(node, 1, 'dim')
    if <MASK>:
        axis = node.kwargs.get('axis')
        if axis is not None:
            dim = axis
        else:
            dim = 0
    if input is None:
        log.debug("couldn't find unbind args")
        return
    if not is_node_meta_valid(input):
        log.debug('example value absent for node: %s', input)
        return
    ndim = input.meta['example_value'].ndim
    if dim < 0:
        dim += ndim
    with graph.inserting_after(node):
        new_node = graph.call_function(torch.unbind, args=(input,), kwargs={'dim': dim})
    node.replace_all_uses_with(new_node)
    new_node.meta.update(node.meta)
    graph.erase_node(node)
    counters[backend]['normalization_pass'] += 1

def add_dependency(self, module_name: str, dependencies=True):
    """Given a module, add it to the dependency graph according to patterns
        specified by the user.
        """
    if <MASK>:
        return
    if module_name == 'torch_package_importer':
        self.dependency_graph.add_node(module_name, action=_ModuleProviderAction.SKIP, provided=True)
        return
    if module_name == '_mock':
        self.dependency_graph.add_node(module_name, action=_ModuleProviderAction.REPACKAGED_MOCK_MODULE, provided=True)
        return
    if self._can_implicitly_extern(module_name):
        self.dependency_graph.add_node(module_name, action=_ModuleProviderAction.EXTERN, provided=True)
        return
    for (pattern, pattern_info) in self.patterns.items():
        if pattern.matches(module_name):
            pattern_info.was_matched = True
            self.dependency_graph.add_node(module_name, action=pattern_info.action, provided=True)
            if pattern_info.action == _ModuleProviderAction.DENY:
                self.dependency_graph.add_node(module_name, error=PackagingErrorReason.DENIED)
            if pattern_info.action == _ModuleProviderAction.INTERN:
                self._intern_module(module_name, dependencies)
            return
    self.dependency_graph.add_node(module_name, error=PackagingErrorReason.NO_ACTION)

@torch.no_grad()
def _get_model_state_dict(model: nn.Module, info: _StateDictInfo) -> dict[str, ValueType]:
    if not info.handle_model:
        return {}
    with info.fsdp_context():
        state_dict = _state_dict_fn(model, 'state_dict')()
    for key in list(state_dict.keys()):
        fqns = _get_fqns(model, key)
        if len(fqns) != 1:
            raise AssertionError(f"Expected 1 FQN for key '{key}', got {len(fqns)}: {fqns}")
        fqn = next(iter(fqns))
        if fqn != key:

            def verify(key, fqn) -> bool:
                if len(fqn) >= len(key):
                    return False
                fqn_split = fqn.split('.')
                key_split = key.split('.')
                fqn_idx = 0
                for (key_idx, key_name) in enumerate(key_split):
                    if key_name == fqn_split[fqn_idx]:
                        fqn_idx += 1
                        if fqn_idx == len(fqn_split):
                            return key_idx == len(key_split) - 1
                    elif key_name in ('module', '_orig_mod'):
                        continue
                    else:
                        return False
                return True
            if <MASK>:
                raise RuntimeError(f'An unexpected key, {key}, exists. FQN is {fqn}')
            state_dict[fqn] = state_dict.pop(key)
    if info.submodule_prefixes:
        new_state_dict: dict[str, ValueType] = {}
        for fqn in state_dict.keys():
            for prefix in info.submodule_prefixes:
                if not fqn.startswith(prefix):
                    continue
                if info.keep_submodule_prefixes:
                    new_state_dict[fqn] = state_dict[fqn]
                else:
                    new_fqn = fqn[len(prefix):]
                    new_state_dict[new_fqn] = state_dict[fqn]
        state_dict = new_state_dict
    if info.ignore_frozen_params:
        for (key, param) in model.named_parameters():
            if param.requires_grad:
                continue
            fqns = _get_fqns(model, key)
            for fqn in fqns:
                state_dict.pop(fqn)
    return _maybe_full_or_cpu_state_dict(state_dict, info)

def _replace(self, pf: PythonFile) -> tuple[str, list[LintResult]]:
    previous_result_count = float('inf')
    first_results = None
    original = replacement = pf.contents
    while True:
        try:
            results = sorted(self._lint(pf), key=LintResult.sort_key)
        except IndentationError as e:
            (error, (_name, lineno, column, _line)) = e.args
            results = [LintResult(error, lineno, column)]
            self._error(pf, *results)
        except ParseError as e:
            results = [LintResult(str(e), *e.token.start)]
            self._error(pf, *results)
        for (i, ri) in enumerate(results):
            if not ri.is_recursive:
                for rj in results[i + 1:]:
                    if ri.contains(rj):
                        rj.is_recursive = True
                    else:
                        break
        first_results = first_results or results
        if not results or len(results) >= previous_result_count:
            break
        previous_result_count = len(results)
        lines = pf.lines[:]
        for r in reversed(results):
            if <MASK>:
                r.apply(lines)
        replacement = ''.join(lines)
        if not any((r.is_recursive for r in results)):
            break
        pf = pf.with_contents(replacement)
    if first_results and self.args.lintrunner:
        name = f'Suggested fixes for {self.linter_name}'
        msg = LintResult(name=name, original=original, replacement=replacement)
        first_results.append(msg)
    return (replacement, first_results)

def _is_comparable_dtype(self, dtype: DtypeObj) -> bool:
    """
        Can we compare values of the given dtype to our own?
        """
    if <MASK>:
        if dtype.kind != 'M':
            return False
        pa_dtype = dtype.pyarrow_dtype
        if (pa_dtype.tz is None) ^ (self.tz is None):
            return False
        return True
    if self.tz is not None:
        return isinstance(dtype, DatetimeTZDtype)
    return lib.is_np_dtype(dtype, 'M')

def unwrap_to_op_info(self, op_call: torch._ops.OpOverload, args: tuple[object, ...], kwargs: dict[str, object]) -> OpInfo:
    runtime_schema_info = self.sharding_propagator.op_to_schema_info.get(op_call, None)
    if runtime_schema_info is not None and runtime_schema_info.needs_pytree:
        (tree_args, args_spec) = pytree.tree_flatten(args)
        args_list: Sequence[object] = tree_args
    else:
        (args_list, args_spec) = (args, None)
    args_schema: list[object] = []
    kwargs_schema: dict[str, object] = {}
    local_args: list[object] = []
    local_kwargs: dict[str, object] = {}
    compute_mesh: Optional[DeviceMesh] = None
    for arg in args_list:
        if isinstance(arg, dtensor.DTensor):
            local_args.append(arg._local_tensor)
            args_schema.append(arg._spec)
            if <MASK>:
                compute_mesh = arg.device_mesh
        elif isinstance(arg, torch.Tensor):
            compute_mesh = compute_mesh or try_find_mesh_from_args(op_call, args_list)
            args_schema.append(self._try_replicate_spec_for_scalar_tensor(op_call, arg, compute_mesh))
            local_args.append(arg)
        else:
            args_schema.append(arg)
            local_args.append(arg)
    for (k, v) in kwargs.items():
        if isinstance(v, dtensor.DTensor):
            local_kwargs[k] = v._local_tensor
            kwargs_schema[k] = v._spec
        elif isinstance(v, torch.Tensor):
            compute_mesh = compute_mesh or try_find_mesh_from_args(op_call, args_list)
            kwargs_schema[k] = self._try_replicate_spec_for_scalar_tensor(op_call, v, compute_mesh)
            local_kwargs[k] = v
        else:
            kwargs_schema[k] = v
            local_kwargs[k] = v
    assert compute_mesh is not None, f'found no DeviceMesh from dtensor args for {op_call}!'
    op_info = OpInfo(compute_mesh, OpSchema(op_call, pytree.tree_unflatten(args_schema, args_spec) if args_spec else tuple(args_schema), kwargs_schema, schema_info=runtime_schema_info), args_schema, tuple(local_args), local_kwargs, args_spec)
    return op_info

def masked_samples():
    for sample_input in sample_inputs_std_var(op_info, device, dtype, requires_grad, **kwargs):
        if <MASK>:
            continue
        for mask in _generate_masked_op_mask(sample_input.input.shape, device, **kwargs):
            (sample_input_args, sample_input_kwargs) = (sample_input.args, dict(mask=mask, **sample_input.kwargs))
            yield SampleInput(sample_input.input.detach().requires_grad_(requires_grad), args=sample_input_args, kwargs=sample_input_kwargs)
            if not requires_grad and dtype.is_floating_point and (sample_input.input.ndim == 2) and (mask is not None) and (mask.shape == sample_input.input.shape):
                for v in [torch.inf, -torch.inf, torch.nan]:
                    t = sample_input.input.detach()
                    t.diagonal(0, -2, -1).fill_(v)
                    yield SampleInput(t.requires_grad_(requires_grad), args=sample_input_args, kwargs=sample_input_kwargs)

def get_conditional_response(request, etag=None, last_modified=None, response=None):
    if response and (not 200 <= response.status_code < 300):
        return response
    if_match_etags = parse_etags(request.META.get('HTTP_IF_MATCH', ''))
    if_unmodified_since = request.META.get('HTTP_IF_UNMODIFIED_SINCE')
    if_unmodified_since = if_unmodified_since and parse_http_date_safe(if_unmodified_since)
    if_none_match_etags = parse_etags(request.META.get('HTTP_IF_NONE_MATCH', ''))
    if_modified_since = request.META.get('HTTP_IF_MODIFIED_SINCE')
    if_modified_since = if_modified_since and parse_http_date_safe(if_modified_since)
    if if_match_etags and (not _if_match_passes(etag, if_match_etags)):
        return _precondition_failed(request)
    if not if_match_etags and if_unmodified_since and (not _if_unmodified_since_passes(last_modified, if_unmodified_since)):
        return _precondition_failed(request)
    if <MASK>:
        if request.method in ('GET', 'HEAD'):
            return _not_modified(request, response)
        else:
            return _precondition_failed(request)
    if not if_none_match_etags and if_modified_since and (not _if_modified_since_passes(last_modified, if_modified_since)) and (request.method in ('GET', 'HEAD')):
        return _not_modified(request, response)
    return response

@property
def theta(self):
    """Returns the (flattened, log-transformed) non-fixed hyperparameters.

        Note that theta are typically the log-transformed values of the
        kernel's hyperparameters as this representation of the search space
        is more amenable for hyperparameter search, as hyperparameters like
        length-scales naturally live on a log-scale.

        Returns
        -------
        theta : ndarray of shape (n_dims,)
            The non-fixed, log-transformed hyperparameters of the kernel
        """
    theta = []
    params = self.get_params()
    for hyperparameter in self.hyperparameters:
        if not hyperparameter.fixed:
            theta.append(params[hyperparameter.name])
    if <MASK>:
        return np.log(np.hstack(theta))
    else:
        return np.array([])

def get_test_db_clone_settings(self, suffix):
    orig_settings_dict = self.connection.settings_dict
    source_database_name = orig_settings_dict['NAME'] or ':memory:'
    if not self.is_in_memory_db(source_database_name):
        (root, ext) = os.path.splitext(source_database_name)
        return {**orig_settings_dict, 'NAME': f'{root}_{suffix}{ext}'}
    start_method = multiprocessing.get_start_method()
    if <MASK>:
        return orig_settings_dict
    if start_method in {'forkserver', 'spawn'}:
        return {**orig_settings_dict, 'NAME': f'{self.connection.alias}_{suffix}.sqlite3'}
    raise NotSupportedError(f'Cloning with start method {start_method!r} is not supported.')

