        else:
            res = keyarr
    return Index(res, dtype=res.dtype)

def create_session(self):
    """Creates a coordinated session."""
    self.tf_sess = self._session_creator.create_session()
    self.coord = coordinator.Coordinator(clean_stop_exception_types=[])
    if <MASK>:
        queue_runner.start_queue_runners(sess=self.tf_sess, coord=self.coord)
    for hook in self._hooks:
        hook.after_create_session(self.tf_sess, self.coord)
    return _CoordinatedSession(_HookedSession(self.tf_sess, self._hooks), self.coord, self._stop_grace_period_secs)

def transform_to_z3(constraint, counter, dimension_dict):
    if isinstance(constraint, Conj):
        conjuncts = []
        for c in constraint.conjucts:
            (new_c, counter) = transform_to_z3(c, counter, dimension_dict)
            conjuncts.append(new_c)
        return (z3.And(conjuncts), counter)
    elif isinstance(constraint, Disj):
        disjuncts = []
        for c in constraint.disjuncts:
            (new_c, counter) = transform_to_z3(c, counter, dimension_dict)
            disjuncts.append(new_c)
        return (z3.Or(disjuncts), counter)
    elif isinstance(constraint, T):
        return (True, counter)
    elif isinstance(constraint, F):
        return (False, counter)
    elif isinstance(constraint, BinConstraintT):
        if constraint.op == op_eq:
            (lhs, counter) = transform_var(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_var(constraint.rhs, counter, dimension_dict)
            return (lhs == rhs, counter)
        else:
            raise NotImplementedError('Method not yet implemented')
    elif isinstance(constraint, BinConstraintD):
        if constraint.op == op_eq:
            if isinstance(constraint.lhs, BVar) and is_bool_expr(constraint.rhs):
                (transformed_rhs, counter) = transform_to_z3(constraint.rhs, counter, dimension_dict)
                transformed_lhs = z3.Bool(constraint.lhs.c)
                return (transformed_lhs == transformed_rhs, counter)
            elif is_dim(constraint.lhs) and is_dim(constraint.rhs):
                (lhs, counter) = transform_dimension(constraint.lhs, counter, dimension_dict)
                (rhs, counter) = transform_dimension(constraint.rhs, counter, dimension_dict)
                return (lhs == rhs, counter)
            else:
                (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
                (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
                return (lhs == rhs, counter)
        elif constraint.op == op_neq:
            assert is_dim(constraint.lhs)
            assert is_dim(constraint.rhs)
            (lhs, counter) = transform_dimension(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_dimension(constraint.rhs, counter, dimension_dict)
            if constraint.rhs == Dyn or constraint.lhs == Dyn:
                if <MASK>:
                    return (lhs.arg(0) == 1, counter)
                elif constraint.lhs == Dyn:
                    return (rhs.arg(0) == 1, counter)
            elif isinstance(constraint.lhs, int) or isinstance(constraint.rhs, int):
                if isinstance(constraint.lhs, int):
                    return (z3.Or([rhs.arg(0) == 0, z3.And([rhs.arg(0) == 1, lhs.arg(1) != rhs.arg(1)])]), counter)
                elif isinstance(constraint.rhs, int):
                    return (z3.Or([lhs.arg(0) == 0, z3.And([lhs.arg(0) == 1, lhs.arg(1) != rhs.arg(1)])]), counter)
            else:
                return (z3.Or([z3.And([lhs.arg(0) == 0, rhs.arg(0) != 0]), z3.And([lhs.arg(0) != 0, rhs.arg(0) == 0]), z3.And([lhs.arg(0) != 0, rhs.arg(0) != 0, lhs.arg(1) != rhs.arg(1)])]), counter)
        elif constraint.op == op_leq:
            assert is_dim(constraint.lhs) and is_dim(constraint.rhs)
            (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
            return (lhs <= rhs, counter)
        elif constraint.op == op_gt:
            assert is_dim(constraint.lhs) and is_dim(constraint.rhs)
            (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
            return (lhs > rhs, counter)
        elif constraint.op == op_lt:
            assert is_dim(constraint.lhs) and is_dim(constraint.rhs)
            (lhs, counter) = transform_algebraic_expression(constraint.lhs, counter, dimension_dict)
            (rhs, counter) = transform_algebraic_expression(constraint.rhs, counter, dimension_dict)
            return (lhs < rhs, counter)
        else:
            raise NotImplementedError('operation not yet implemented')
    else:
        raise NotImplementedError('Operation not yet implemented')

def wrapper(*args, **kwargs):
    scalars = [arg for arg in args if isinstance(arg, (int, sympy.Expr)) or (isinstance(arg, CppCSEVariable) and (not arg.is_vec))]
    vectors = [arg for arg in args if isinstance(arg, CppCSEVariable) and arg.is_vec]
    new_args = list(args)
    if scalars and vectors:
        new_args = []
        for arg in args:
            if isinstance(arg, (int, sympy.Expr)):
                if isinstance(arg, sympy.Expr) and (not arg.is_number):
                    arg = ops.index_expr(arg, torch.int64)
                else:
                    arg = ops.constant(arg, torch.int64)
                arg = arg.value if isinstance(arg, OpsValue) else arg
            new_args.append(arg)
    if <MASK>:
        if len(new_args) == 2:
            new_args = promote_args(new_args)
        elif func == CppVecOverrides.where:
            new_args[1:] = promote_args(new_args[1:])
    if scalars and vectors:
        assert isinstance(V.kernel, CppVecKernel)
        new_args = [V.kernel.broadcast(new_arg) if isinstance(new_arg, CppCSEVariable) and (not new_arg.is_vec) and (func not in [CppVecOverrides.rand, CppVecOverrides.randn, CppVecOverrides.randint64]) else new_arg for new_arg in new_args]
    if vectors:
        return func(*new_args, **kwargs)
    else:
        scalar_ops = super(CppVecOverrides, self)
        scalar_func = getattr(scalar_ops, func.__name__)
        assert scalar_func is not None
        return scalar_func(*args, **kwargs)

def get_compile_id(frame_state: dict[str, Union[int, FrameStateSizeEntry]]) -> CompileId:
    global FRAME_COUNTER
    if <MASK>:
        frame_state['_id'] = FRAME_COUNTER
        FRAME_COUNTER += 1
    frame_id = frame_state['_id']
    assert isinstance(frame_id, int)
    frame_compile_id = FRAME_COMPILE_COUNTER[frame_id]
    FRAME_COMPILE_COUNTER[frame_id] += 1
    compiled_autograd_id = None
    if (prior := CompileContext.current_compile_id()):
        compiled_autograd_id = prior.compiled_autograd_id
    return CompileId(compiled_autograd_id=compiled_autograd_id, frame_id=frame_id, frame_compile_id=frame_compile_id)

@dispatch.dispatch_for_api(math_ops.matmul)
def matmul(a: ragged_tensor.RaggedOrDense, b: ragged_tensor.RaggedOrDense, transpose_a=False, transpose_b=False, adjoint_a=False, adjoint_b=False, a_is_sparse=False, b_is_sparse=False, output_type=None, grad_a=False, grad_b=False, name=None):
    """Multiplies matrix `a` by matrix `b`.

  If all transpose or adjoint attributes are `False` then:

  ```
  output[..., i, j] = sum_k (a[..., i, k] * b[..., k, j]), for all indices i, j.
  ```

  The inputs `a` and `b` must have `rank >= 2`, where the outermost `rank - 2`
  dimensions are batch dimensions.  The inputs must have the same dtype.  See
  `tf.matmul` for more information.

  Args:
    a: `tf.Tensor` or `RaggedTensor` with `rank > 1`.
    b: `tf.Tensor` or `RaggedTensor` with same type and rank as `a`.
    transpose_a: If `True`, `a` is transposed before multiplication.
    transpose_b: If `True`, `b` is transposed before multiplication.
    adjoint_a: If `True`, `a` is conjugated & transposed before multiplication.
    adjoint_b: If `True`, `b` is conjugated & transposed before multiplication.
    a_is_sparse: If `True`, optimize assuming `a` is mostly zero.
    b_is_sparse: If `True`, optimize assuming `b` is mostly zero.
    output_type: The output datatype (optional).
    grad_a: Unused.
    grad_b: Unused.
    name: Name for the operation (optional).

  Returns:
    A `Tensor` or `RaggedTensor` with the same rank and shape as `a`, where
    each inner-most matrix is the product of the corresponding matrices in `a`
    and `b`.
  """
    del grad_a
    del grad_b
    if transpose_a and adjoint_a:
        raise ValueError('Only one of transpose_a and adjoint_a can be True.')
    if transpose_b and adjoint_b:
        raise ValueError('Only one of transpose_b and adjoint_b can be True.')
    kwargs = dict(transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b, a_is_sparse=a_is_sparse, b_is_sparse=b_is_sparse, output_type=output_type)
    with ops.name_scope(name, 'RaggedMatMul', [a, b]) as name:
        a = ragged_tensor.convert_to_tensor_or_ragged_tensor(a, name='a')
        b = ragged_tensor.convert_to_tensor_or_ragged_tensor(b, name='b')
        a_is_ragged = isinstance(a, ragged_tensor.RaggedTensor)
        b_is_ragged = isinstance(b, ragged_tensor.RaggedTensor)
        if not (a_is_ragged or b_is_ragged):
            return math_ops.matmul(a, b, **kwargs)
        if a.dtype != b.dtype:
            raise ValueError('`a` and `b` must have the same dtype.')
        if a.shape.rank is None:
            if b.shape.rank is None:
                raise ValueError('matmul requires at least one input to have known rank if either input is ragged.')
            rank = b.shape.rank
        else:
            if b.shape.rank is not None and a.shape.rank != b.shape.rank:
                raise ValueError('`a` and `b` must have the same rank.')
            rank = a.shape.rank
        if <MASK>:
            raise ValueError('`a` and `b` must have the same rank.')
        if rank > 3:
            shape_err = 'Batch dimensions of `a` and `b` do not have the same size.'
            if not a_is_ragged:
                a = ragged_tensor.RaggedTensor.from_tensor(a, ragged_rank=1)
            if not b_is_ragged:
                b = ragged_tensor.RaggedTensor.from_tensor(b, ragged_rank=1)
            with ops.control_dependencies([check_ops.assert_equal(a.row_splits, b.row_splits, message=shape_err)]):
                flat_result = matmul(a.values, b.values, **kwargs)
                return a.with_values(flat_result)
        if rank == 2:
            return _matmul_2d(a, b, **kwargs)
        assert rank == 3
        a_ragged_rank = a.ragged_rank if a_is_ragged else 0
        if a_ragged_rank == 1 and (not (b_is_ragged or transpose_a or adjoint_a)):
            return _matmul_3d_with_batch_dim_folding(a, b, **kwargs)
        else:
            return _matmul_3d_with_map_fn(a, b, **kwargs)

def select_template(self, template_name_list):
    """
        Given a list of template names, return the first that can be loaded.
        """
    if not template_name_list:
        raise TemplateDoesNotExist('No template names provided')
    not_found = []
    for template_name in template_name_list:
        try:
            return self.get_template(template_name)
        except TemplateDoesNotExist as exc:
            if <MASK>:
                not_found.append(exc.args[0])
            continue
    raise TemplateDoesNotExist(', '.join(not_found))

def nargsort(items: ArrayLike | Index | Series, kind: SortKind='quicksort', ascending: bool=True, na_position: str='last', key: Callable | None=None, mask: npt.NDArray[np.bool_] | None=None) -> npt.NDArray[np.intp]:
    """
    Intended to be a drop-in replacement for np.argsort which handles NaNs.

    Adds ascending, na_position, and key parameters.

    (GH #6399, #5231, #27237)

    Parameters
    ----------
    items : np.ndarray, ExtensionArray, Index, or Series
    kind : {'quicksort', 'mergesort', 'heapsort', 'stable'}, default 'quicksort'
    ascending : bool, default True
    na_position : {'first', 'last'}, default 'last'
    key : Optional[Callable], default None
    mask : Optional[np.ndarray[bool]], default None
        Passed when called by ExtensionArray.argsort.

    Returns
    -------
    np.ndarray[np.intp]
    """
    if key is not None:
        items = ensure_key_mapped(items, key)
        return nargsort(items, kind=kind, ascending=ascending, na_position=na_position, key=None, mask=mask)
    if isinstance(items, ABCRangeIndex):
        return items.argsort(ascending=ascending)
    elif <MASK>:
        items = extract_array(items)
    else:
        raise TypeError('nargsort does not support MultiIndex. Use index.sort_values instead.')
    if mask is None:
        mask = np.asarray(isna(items))
    if not isinstance(items, np.ndarray):
        return items.argsort(ascending=ascending, kind=kind, na_position=na_position)
    idx = np.arange(len(items))
    non_nans = items[~mask]
    non_nan_idx = idx[~mask]
    nan_idx = np.nonzero(mask)[0]
    if not ascending:
        non_nans = non_nans[::-1]
        non_nan_idx = non_nan_idx[::-1]
    indexer = non_nan_idx[non_nans.argsort(kind=kind)]
    if not ascending:
        indexer = indexer[::-1]
    if na_position == 'last':
        indexer = np.concatenate([indexer, nan_idx])
    elif na_position == 'first':
        indexer = np.concatenate([nan_idx, indexer])
    else:
        raise ValueError(f'invalid na_position: {na_position}')
    return ensure_platform_int(indexer)

def _compareValues(self, fd, vs, evs):
    """Compare lists/arrays of field values."""
    if len(vs) != len(evs):
        self.fail('Field %s decoded %d outputs, expected %d' % (fd.name, len(vs), len(evs)))
    for (i, ev) in enumerate(evs):
        if fd.cpp_type == fd.CPPTYPE_FLOAT:
            self.assertTrue(np.isclose(vs[i], ev), 'expected %r, actual %r' % (ev, vs[i]))
        elif <MASK>:
            self.assertEqual(vs[i], ev.encode('ascii'))
        else:
            self.assertEqual(vs[i], ev)

def grouped_mm_args(mat1: TensorBox, mat2: TensorBox, offs: Optional[TensorBox], layout=None, out_dtype=None):
    (mat1, mat2) = realize_inputs(mat1, mat2)
    if offs is not None:
        realize_inputs(offs)
    mat1_size = mat1.get_size()
    mat2_size = mat2.get_size()
    (m1dim, m2dim) = (len(mat1_size), len(mat2_size))
    assert m1dim == 2 or m1dim == 3
    assert m2dim == 2 or m2dim == 3
    if layout is None:
        from torch._inductor.ir import FixedLayout
        if out_dtype is None:
            out_dtype = mat1.get_dtype()
        alignment = 16 // out_dtype.itemsize
        if m1dim == 2:
            if <MASK>:
                assert offs is not None
                out_size = [offs.get_size()[0], mat1_size[0], mat2_size[1]]
            else:
                out_size = [mat1_size[0], mat2_size[-1]]
        elif m2dim == 2:
            out_size = [mat1_size[1], mat2_size[1]]
        else:
            out_size = [mat1_size[0], mat1_size[1], mat2_size[-1]]
        size_padded = (out_size[-1] + alignment - 1) // alignment * alignment
        if len(out_size) == 2:
            out_stride = [size_padded, 1]
        else:
            out_stride = [out_size[1] * size_padded, size_padded, 1]
        layout = FixedLayout(mat1.get_device(), out_dtype, out_size, out_stride)
    else:
        assert out_dtype is None, 'out_dtype is ignored if layout is specified.'
    return (mat1_size, mat2_size, layout, mat1, mat2, offs)

def __str__(self):

    def col_str(column, idx):
        col = self.quote_name(column)
        try:
            suffix = self.col_suffixes[idx]
            if <MASK>:
                col = '{} {}'.format(col, suffix)
        except IndexError:
            pass
        return col
    return ', '.join((col_str(column, idx) for (idx, column) in enumerate(self.columns)))

def _replace_input_placeholders_with_default_values(graph_def, signature_def):
    """Replace graphdef's `tf.placeholder` input ops with all-zero constants."""
    name_to_node_map = dict(((n.name, n) for n in graph_def.node))
    processed_nodes = set([])
    for (name, input_) in signature_def.inputs.items():
        (tensor_name, _) = _parse_tensor_name(input_.name)
        if tensor_name in processed_nodes:
            continue
        processed_nodes.add(tensor_name)
        if tensor_name not in name_to_node_map:
            raise RuntimeError(f"Unable to find input signature tensor '{tensor_name}' in optimized GraphDef. Graph nodes are: {list(name_to_node_map.keys())}")
        node = name_to_node_map[tensor_name]
        if node.op not in ('Placeholder', 'PlaceholderV2'):
            logging.info("Tried to convert SavedModel input node '{}' from a placeholder, but it doesn't look like a placeholder: {}".format(tensor_name, node))
            continue
        shape = tensor_shape.TensorShape(input_.tensor_shape)
        if not shape.is_fully_defined():
            raise ValueError(f"Expected fully defined input shape for signature_def '{name}', tensor name: '{tensor_name}'; but shape is: {shape}.")
        temp_graph = ops_lib.Graph()
        with temp_graph.as_default():
            const = array_ops.zeros(shape, dtype=input_.dtype, name=tensor_name)
        node.CopyFrom(const.op.node_def)
        for op in temp_graph.get_operations():
            if <MASK>:
                continue
            graph_def.node.append(op.node_def)
            name_to_node_map[op.node_def.name] = op.node_def

def __init__(self, optimizer, iterations=None):
    self.optimizer = optimizer
    self._track_trackable(optimizer, name='optimizer')
    if <MASK>:
        with backend.name_scope(self.__class__.__name__):
            self.iterations = backend.variable(0, dtype='int64', name='iterations')
    else:
        self.iterations = iterations
    self._track_trackable(self.iterations, name='global_step')

def complex_memory_overlap(t: torch.Tensor) -> bool:
    if config.always_complex_memory_overlap_TESTING_ONLY:
        return True
    t = index_expanded_dims(t, get_expanded_dims(t)).squeeze()
    if <MASK>:
        strides = t.stride()
        sizes = t.shape
        indices = list(range(len(strides)))
        indices = [x for (_, x) in sorted(zip(strides, indices))]
        for i in range(len(strides)):
            prev_stride = 1 if i == 0 else strides[indices[i - 1]]
            prev_size = 1 if i == 0 else sizes[indices[i - 1]]
            if strides[indices[i]] < prev_stride * prev_size:
                return True
    return False

@combinations.generate(combinations.combine(mode=['graph'], prefetch_to_device=[None, True]))
