def result_capturing_wrapper(*graph_inputs: Any) -> Any:
    nonlocal graph_captured_result
    nonlocal graph_captured_input
    graph_captured_input = graph_inputs
    assert graph is not None
    named_parameters = dict(graph.named_parameters(remove_duplicate=False))
    named_buffers = dict(graph.named_buffers(remove_duplicate=False))
    ambient_fake_mode = _guards.detect_fake_mode(graph_inputs) if _guards.detect_fake_mode(graph_inputs) is not None else fake_mode
    ignore_fresh_unbacked = null_context()
    assert ambient_fake_mode is not None
    if (shape_env := ambient_fake_mode.shape_env):
        ignore_fresh_unbacked = shape_env.ignore_fresh_unbacked_symbols()
    with ambient_fake_mode, enable_python_dispatcher(), ignore_fresh_unbacked:
        params_and_buffers = {**named_parameters, **named_buffers}
        fake_params_buffers = {}
        for (name, value) in params_and_buffers.items():
            fake_params_buffers[name] = ambient_fake_mode.from_tensor(value, static_shapes=True)
        from torch._export.non_strict_utils import key_path_to_source, KeyPath

        def fakify_with_ambient(path: KeyPath, t: Union[torch.Tensor, _IntWrapper, Any]) -> Any:
            if isinstance(t, torch.Tensor):
                return ambient_fake_mode.from_tensor(t, static_shapes=True)
            elif <MASK>:
                if t.dynamism is not None and isinstance(t.dynamism, _DimHint) and (t.dynamism.type in (_DimHintType.DYNAMIC, _DimHintType.AUTO)):
                    source = key_path_to_source(path)
                    symint = ambient_fake_mode.shape_env.create_unspecified_symint_and_symbol(t.val, source, DimDynamic.DYNAMIC)
                    return symint
                else:
                    return t.val
            else:
                return t
        fake_graph_inputs = pytree.tree_map_with_path(fakify_with_ambient, graph_inputs)
        graph_captured_result = torch.func.functional_call(graph, fake_params_buffers, fake_graph_inputs)
    return graph_captured_result

def gen_registration_headers(backend_index: BackendIndex, per_operator_headers: bool, rocm: bool) -> list[str]:
    if <MASK>:
        headers = ['#include <ATen/ops/as_strided_native.h>']
    else:
        headers = ['#include <ATen/NativeFunctions.h>']
    if backend_index.dispatch_key in (DispatchKey.CPU, DispatchKey.Meta):
        headers.append('#include <ATen/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.CUDA:
        if rocm:
            headers.append('#include <ATen/hip/EmptyTensor.h>')
        else:
            headers.append('#include <ATen/cuda/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.MPS:
        headers.append('#include <ATen/mps/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.XPU:
        headers.append('#include <ATen/xpu/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.MTIA:
        headers.append('#include <ATen/native/mtia/EmptyTensor.h>')
    elif per_operator_headers:
        headers += ['#include <ATen/ops/empty.h>', '#include <ATen/ops/empty_strided.h>', '#include <ATen/ops/_copy_from_and_resize.h>', '#include <ATen/ops/_copy_from.h>']
    else:
        headers.append('#include <ATen/Functions.h>')
    headers.append('#include <c10/macros/Macros.h>')
    return headers

def __call__(self, fn: Callable) -> Callable:
    sig = inspect.signature(fn)

    @torch._disable_dynamo
    @wraps(fn)
    def _fn(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        type_promoting_args = tuple((bound.arguments[x] for x in self.type_promoting_arg_names if x in bound.arguments.keys()))
        flattened_type_promoting_args = pytree.arg_tree_leaves(*type_promoting_args)
        (compute_dtype, result_dtype) = utils.elementwise_dtypes(*flattened_type_promoting_args, type_promotion_kind=self.type_promotion_kind)
        promoted_args = {x: _maybe_convert_to_dtype(bound.arguments[x], compute_dtype) for x in self.type_promoting_arg_names if x in bound.arguments.keys()}
        bound.arguments.update(promoted_args)
        result = fn(**bound.arguments)
        if 'dtype' in bound.arguments:
            maybe_dtype = bound.arguments['dtype']
            if maybe_dtype:
                result_dtype = maybe_dtype
        if <MASK>:
            return _maybe_convert_to_dtype(result, result_dtype)
        if isinstance(result, Sequence):
            return tuple((_maybe_convert_to_dtype(x, result_dtype) for x in result))
        raise AssertionError(f'Unhandled result type: {type(result)}')
    _fn.__signature__ = sig
    return _fn

def inner_debug_fn(real_inputs: Sequence[InputType]) -> Any:
    """
            Aot Autograd fw_compiler and bw_compiler can have fake tensors. So,
            example_inputs can be fake tensors. We can call compiler_fn (which is
            inductor or nvfuser) with fake tensors but the actually compiled_fn
            should be called with real tensors. Therefore, the actual invocation
            is deferred.
            """
    fake_mode = FakeTensorMode()
    copy_tensor_attrs = [fake_mode.from_tensor(x) if isinstance(x, torch.Tensor) else x for x in real_inputs]
    if config.repro_level == 3:
        dump_to_minify(fx.GraphModule(gm, orig_graph), real_inputs, compiler_name)
    if config.repro_level == 4:
        if compiler_name != 'inductor':
            raise NotImplementedError('Accuracy minification is supported for inductor only')
        failed = not same_two_models(gm, inner_compiled_fn, real_inputs, only_fwd=True, ignore_non_fp=config.repro_ignore_non_fp)
        if failed:
            log.warning('Accuracy failed for the AOT Autograd graph %s', graph_name)
            dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), real_inputs, f'{compiler_name}_accuracy')
            dump_to_minify(fx.GraphModule(gm, orig_graph), real_inputs, f'{compiler_name}_accuracy')
            raise AccuracyError('Bad accuracy detected')
        else:
            return inner_compiled_fn(real_inputs)
    else:
        try:
            out = inner_compiled_fn(real_inputs)
            for arg in example_inputs:
                if isinstance(arg, torch.Tensor) and arg.is_cuda:
                    torch.cuda.synchronize()
                    break
            return out
        except Exception:
            if <MASK>:
                dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), copy_tensor_attrs, compiler_name)
            elif config.repro_level == 2:
                dump_to_minify(fx.GraphModule(gm, orig_graph), copy_tensor_attrs, compiler_name)
            raise

@RegisterPFor('OneHot')
def _convert_one_hot(pfor_input: _PforInput):
    indices = pfor_input.stacked_input(0)
    depth = pfor_input.unstacked_input(1)
    on_value = pfor_input.unstacked_input(2)
    off_value = pfor_input.unstacked_input(3)
    axis = pfor_input.get_attr('axis')
    if <MASK>:
        axis += 1
    return wrap(array_ops.one_hot(indices, depth, on_value, off_value, axis), True)

def wait_for_connection(addr, port, timeout=15, attempt_cnt=5):
    import socket
    for i in range(attempt_cnt):
        try:
            with socket.create_connection((addr, port), timeout=timeout):
                return
        except (ConnectionRefusedError, TimeoutError):
            if <MASK>:
                raise
            time.sleep(timeout)

def _hipify_compile_flags(self, extension):
    if isinstance(extension.extra_compile_args, dict) and 'nvcc' in extension.extra_compile_args:
        modified_flags = []
        for flag in extension.extra_compile_args['nvcc']:
            if flag.startswith('-') and 'CUDA' in flag and (not flag.startswith('-I')):
                parts = flag.split('=', 1)
                if <MASK>:
                    (flag_part, value_part) = parts
                    modified_flag_part = flag_part.replace('CUDA', 'HIP', 1)
                    modified_flag = f'{modified_flag_part}={value_part}'
                else:
                    modified_flag = flag.replace('CUDA', 'HIP', 1)
                modified_flags.append(modified_flag)
                logger.info('Modified flag: %s -> %s', flag, modified_flag)
            else:
                modified_flags.append(flag)
        extension.extra_compile_args['nvcc'] = modified_flags

@staticmethod
def _string_to_components(spec=None):
    """Stateless portion of device spec string parsing.

    Args:
      spec: An optional string specifying a device specification.

    Returns:
      The parsed components of `spec`. Note that the result of this function
      must go through attribute setters of DeviceSpec, and should therefore NOT
      be used directly.
    """
    cached_result = _STRING_TO_COMPONENTS_CACHE.get(spec)
    if cached_result is not None:
        return cached_result
    raw_spec = spec
    (job, replica, task, device_type, device_index) = (None, None, None, None, None)
    spec = spec or ''
    splits = [x.split(':') for x in spec.split('/')]
    valid_device_types = DeviceSpecV2._get_valid_device_types()
    for y in splits:
        ly = len(y)
        if y:
            if <MASK>:
                job = y[1]
            elif ly == 2 and y[0] == 'replica':
                replica = y[1]
            elif ly == 2 and y[0] == 'task':
                task = y[1]
            elif (ly == 1 or ly == 2) and y[0].upper() in valid_device_types:
                if device_type is not None:
                    raise ValueError(f'Multiple device types are not allowed while parsing the device spec: {spec}.')
                device_type = y[0].upper()
                if ly == 2 and y[1] != '*':
                    device_index = int(y[1])
            elif ly == 3 and y[0] == 'device':
                if device_type is not None:
                    raise ValueError(f'Multiple device types are not allowed while parsing the device spec: {spec}.')
                device_type = y[1]
                if y[2] != '*':
                    device_index = int(y[2])
            elif ly and y[0] != '':
                raise ValueError(f"Unknown attribute '{y[0]}' is encountered while parsing the device spec: '{spec}'.")
    output = (job, replica, task, device_type, device_index)
    _STRING_TO_COMPONENTS_CACHE[raw_spec] = output
    return output

def _make_server_def(server_or_cluster_def, job_name, task_index, protocol, config):
    """Creates a `tf.train.ServerDef` protocol buffer.

  Args:
    server_or_cluster_def: A `tf.train.ServerDef` or `tf.train.ClusterDef`
      protocol buffer, or a `tf.train.ClusterSpec` object, describing the server
      to be defined and/or the cluster of which it is a member.
    job_name: (Optional.) Specifies the name of the job of which the server is a
      member. Defaults to the value in `server_or_cluster_def`, if specified.
    task_index: (Optional.) Specifies the task index of the server in its job.
      Defaults to the value in `server_or_cluster_def`, if specified. Otherwise
      defaults to 0 if the server's job has only one task.
    protocol: (Optional.) Specifies the protocol to be used by the server.
      Acceptable values include `"grpc", "grpc+verbs"`. Defaults to the value in
      `server_or_cluster_def`, if specified. Otherwise defaults to `"grpc"`.
    config: (Options.) A `tf.compat.v1.ConfigProto` that specifies default
      configuration options for all sessions that run on this server.

  Returns:
    A `tf.train.ServerDef`.

  Raises:
    TypeError: If the arguments do not have the appropriate type.
    ValueError: If an argument is not specified and cannot be inferred.
  """
    server_def = tensorflow_server_pb2.ServerDef()
    if isinstance(server_or_cluster_def, tensorflow_server_pb2.ServerDef):
        server_def.MergeFrom(server_or_cluster_def)
        if job_name is not None:
            server_def.job_name = job_name
        if task_index is not None:
            server_def.task_index = task_index
        if protocol is not None:
            server_def.protocol = protocol
        if <MASK>:
            server_def.default_session_config.MergeFrom(config)
    else:
        try:
            cluster_spec = ClusterSpec(server_or_cluster_def)
        except TypeError:
            raise TypeError('Could not convert `server_or_cluster_def` to a `tf.train.ServerDef` or `tf.train.ClusterSpec`.')
        if job_name is None:
            if len(cluster_spec.jobs) == 1:
                job_name = cluster_spec.jobs[0]
            else:
                raise ValueError('Must specify an explicit `job_name`.')
        if task_index is None:
            task_indices = cluster_spec.task_indices(job_name)
            if len(task_indices) == 1:
                task_index = task_indices[0]
            else:
                raise ValueError('Must specify an explicit `task_index`.')
        if protocol is None:
            protocol = 'grpc'
        server_def = tensorflow_server_pb2.ServerDef(cluster=cluster_spec.as_cluster_def(), job_name=job_name, task_index=task_index, protocol=protocol)
        if config is not None:
            server_def.default_session_config.MergeFrom(config)
    return server_def

def log_prob(self, value):
    if <MASK>:
        self._validate_sample(value)
    (value, probs) = broadcast_all(value, self.probs)
    probs = probs.clone(memory_format=torch.contiguous_format)
    probs[(probs == 1) & (value == 0)] = 0
    return value * (-probs).log1p() + self.probs.log()

@final
def _try_convert_data(self, name: Hashable, data: Series, use_dtypes: bool=True, convert_dates: bool | list[str]=True, is_axis: bool=False) -> tuple[Series, bool]:
    """
        Try to parse a Series into a column by inferring dtype.
        """
    org_data = data
    if use_dtypes:
        if not self.dtype:
            if all(notna(data)):
                return (data, False)
            filled = data.fillna(np.nan)
            return (filled, True)
        elif self.dtype is True:
            pass
        elif not _should_convert_dates(convert_dates, self.keep_default_dates, name):
            dtype = self.dtype.get(name) if isinstance(self.dtype, dict) else self.dtype
            if dtype is not None:
                try:
                    return (data.astype(dtype), True)
                except (TypeError, ValueError):
                    return (data, False)
    if convert_dates:
        new_data = self._try_convert_to_date(data)
        if new_data is not data:
            return (new_data, True)
    converted = False
    if self.dtype_backend is not lib.no_default and (not is_axis):
        return (data, True)
    elif is_string_dtype(data.dtype):
        try:
            data = data.astype('float64')
            converted = True
        except (TypeError, ValueError):
            pass
    if data.dtype.kind == 'f' and data.dtype != 'float64':
        try:
            data = data.astype('float64')
            converted = True
        except (TypeError, ValueError):
            pass
    if len(data) and data.dtype in ('float', 'object'):
        try:
            new_data = org_data.astype('int64')
            if (new_data == data).all():
                data = new_data
                converted = True
        except (TypeError, ValueError, OverflowError):
            pass
    if <MASK>:
        try:
            data = data.astype('int64')
            converted = True
        except (TypeError, ValueError):
            pass
    if name == 'index' and len(data):
        if self.orient == 'split':
            return (data, False)
    return (data, converted)

def _compare_group(self, item, other, getter):
    if getter is None:
        return item != other
    elif <MASK>:
        getter = getter[1:]
        if getter.endswith('()'):
            getter = getter[:-2]
            return getattr(item, getter)() != getattr(other, getter)()
        else:
            return getattr(item, getter) != getattr(other, getter)
    elif callable(getter):
        return getter(item) != getter(other)
    else:
        return item[getter] != other[getter]

def should_load(self, proto):
    """Checks if this object should load the SavedUserObject `proto`."""
    if <MASK>:
        return False
    if self.version < proto.version.min_consumer:
        return False
    if proto.version.producer < self._min_producer_version:
        return False
    for bad_version in proto.version.bad_consumers:
        if self.version == bad_version:
            return False
    return True

def _true_getter(name, shape=None, dtype=dtypes.float32, initializer=None, regularizer=None, reuse=None, trainable=None, collections=None, caching_device=None, partitioner=None, validate_shape=True, use_resource=None, constraint=None, synchronization=VariableSynchronization.AUTO, aggregation=VariableAggregation.NONE):
