    return self._get_single_variable(name=name, shape=shape, dtype=dtype, initializer=initializer, regularizer=regularizer, reuse=reuse, trainable=trainable, collections=collections, caching_device=caching_device, validate_shape=validate_shape, use_resource=use_resource, constraint=constraint, synchronization=synchronization, aggregation=aggregation)

def propagate_mutation(self, fx_node: torch.fx.Node, old_args: tuple[Any], old_kwargs: dict[str, Any], new_args: tuple[Any], new_kwargs: dict[str, Any]) -> None:
    """Propagate mutations on new_args/new_kwargs back to old_args/old_kwargs.

        Assumes we may have cloned old_args/old_kwargs into new_args/new_kwargs
        and then called fx_node(*new_args, **new_kwargs).

        If fx_node mutates any of new_args/new_kwargs, and they are different from
        old_args/old_kwargs, then we need to update the original tensor.
        """
    assert len(old_args) == len(new_args)
    assert len(old_kwargs) == len(new_kwargs)
    if fx_node.target is torch.ops.higher_order.triton_kernel_wrapper_mutation:
        kwargs = fx_node.kwargs['kwargs']
        assert isinstance(kwargs, dict)
        mutated = torch._higher_order_ops.triton_kernel_wrap.get_mutated_tensors(old_kwargs['kernel_idx'], old_kwargs['constant_args_idx'], {k: v.meta['val'] if isinstance(v, torch.fx.Node) else v for (k, v) in kwargs.items()}, old_kwargs['tma_descriptor_metadata'])
        for name in mutated:
            old_arg = old_kwargs['kwargs'][name]
            new_arg = new_kwargs['kwargs'][name]
            if old_arg is new_arg:
                continue
            self.call_function(torch.ops.aten.copy_.default, (old_arg, new_arg), {})
        return
    assert isinstance(fx_node.target, torch._ops.OpOverload)

    def maybe_propagate(schema_arg: torch._C.Argument, old_arg: ir.IRNode, new_arg: ir.IRNode) -> None:
        if old_arg is new_arg:
            return
        if schema_arg.alias_info is not None and schema_arg.alias_info.is_write:
            if isinstance(old_arg, ir.IRNode):
                old_arg = (old_arg,)
                new_arg = (new_arg,)
            for (old_arg_item, new_arg_item) in zip(old_arg, new_arg):
                if <MASK>:
                    continue
                self.call_function(torch.ops.aten.copy_.default, (old_arg_item, new_arg_item), {})
    schema = fx_node.target._schema
    for (idx, (old_arg, new_arg)) in enumerate(zip(old_args, new_args)):
        schema_arg = schema.arguments[idx]
        maybe_propagate(schema_arg, old_arg, new_arg)
    schema_kwargs = {arg.name: arg for arg in schema.arguments}
    for key in old_kwargs.keys():
        old_arg = old_kwargs[key]
        new_arg = new_kwargs[key]
        schema_arg = schema_kwargs[key]
        maybe_propagate(schema_arg, old_arg, new_arg)

def method_def(name: BaseOperatorName, module: str | None, overloads: Sequence[PythonSignatureNativeFunctionPair], *, method: bool) -> str:
    """
    Generate method def entry.
    """
    pycname = get_pycname(name)
    if <MASK>:
        pycname = f'TypeError_to_NotImplemented_<{pycname}>'
    if is_noarg(overloads):
        flags = 'METH_NOARGS' if method else 'METH_VARARGS | METH_KEYWORDS'
    else:
        pycname = f'castPyCFunctionWithKeywords({pycname})'
        flags = 'METH_VARARGS | METH_KEYWORDS'
    if module == 'torch':
        flags += ' | METH_STATIC'
    return f'{{"{name}", {pycname}, {flags}, nullptr}},'

def _index_fill_reshape_helper(g: jit_utils.GraphContext, self, dim, index):
    from torch.onnx._internal.torchscript_exporter.symbolic_opset9 import expand
    if g.opset <= 10:
        from torch.onnx._internal.torchscript_exporter.symbolic_opset9 import scatter
    else:
        from torch.onnx._internal.torchscript_exporter.symbolic_opset11 import scatter
    if self.type().dim() is None:
        return _unimplemented('index_fill', 'input rank not accessible')
    self_dim = self.type().dim()
    dim_value = _parse_arg(dim, 'i')
    if <MASK>:
        dim_value += self_dim
    unsqueezed_index = _unsqueeze_helper(g, index, [i for i in range(self_dim) if i != dim_value])
    expanded_index_shape = scatter(g, g.op('Shape', self), 0, _unsqueeze_helper(g, dim, [0]), g.op('Shape', index))
    expanded_index = expand(g, unsqueezed_index, expanded_index_shape, None)
    return (expanded_index_shape, expanded_index)

def _decide_input_format(model, args):
    try:
        sig = _signature(model)
    except ValueError as e:
        warnings.warn(f'{e}, skipping _decide_input_format')
        return args
    try:
        ordered_list_keys = list(sig.parameters.keys())
        if ordered_list_keys[0] == 'self':
            ordered_list_keys = ordered_list_keys[1:]
        args_dict: dict = {}
        if <MASK>:
            args_list = args
        elif isinstance(args, tuple):
            args_list = list(args)
        else:
            args_list = [args]
        if isinstance(args_list[-1], dict):
            args_dict = args_list[-1]
            args_list = args_list[:-1]
        n_nonkeyword = len(args_list)
        for optional_arg in ordered_list_keys[n_nonkeyword:]:
            if optional_arg in args_dict:
                args_list.append(args_dict[optional_arg])
            else:
                param = sig.parameters[optional_arg]
                if param.default != param.empty:
                    args_list.append(param.default)
        args = args_list if isinstance(args, list) else tuple(args_list)
    except IndexError:
        warnings.warn('No input args, skipping _decide_input_format')
    except Exception as e:
        warnings.warn(f'Skipping _decide_input_format\n {e.args[0]}')
    return args

def handle_options(func, x, axis, exclusive, reverse):
    """Adds tf options to numpy scan ops."""
    length = len(x.shape)
    if axis < 0:
        axis = length + axis
    if reverse:
        x = numpy_reverse(x, axis)
    if exclusive:
        ix_head = [slice(0, 1) if i == axis else slice(None) for i in range(length)]
        ix_init = [slice(0, -1) if i == axis else slice(None) for i in range(length)]
        if <MASK>:
            init = np.zeros_like(x[tuple(ix_head)])
        elif func == np.cumprod:
            init = np.ones_like(x[tuple(ix_head)])
        else:
            raise ValueError('Unknown scan function.')
        x = np.concatenate([init, func(x[tuple(ix_init)], axis)], axis=axis)
    else:
        x = func(x, axis=axis)
    if reverse:
        x = numpy_reverse(x, axis)
    return x

def _get_builtins_helper():
    builtins = []
    for (fn, _builtin_name) in torch.jit._builtins._builtin_ops:
        mod = inspect.getmodule(fn)
        if not hasattr(fn, '__name__'):
            continue
        if <MASK>:
            continue
        if _hidden(fn.__name__) or _hidden(fn.__qualname__) or _hidden(mod.__name__):
            continue
        if 'torch._C' in mod.__name__:
            continue
        builtins.append((fn, _builtin_name))
    return builtins

