def lookup(self, keys, name=None):
    """Looks up `keys` in the table, outputs the corresponding values.

    It assigns out-of-vocabulary keys to buckets based in their hashes.

    Args:
      keys: Keys to look up. May be either a `SparseTensor` or dense `Tensor`.
      name: Optional name for the op.

    Returns:
      A `SparseTensor` if keys are sparse, a `RaggedTensor` if keys are ragged,
      otherwise a dense `Tensor`.

    Raises:
      TypeError: when `keys` doesn't match the table key data type.
    """
    if keys.dtype.base_dtype != self._key_dtype:
        raise TypeError(f'Dtype of argument `keys` must be {self._key_dtype}, received: {keys.dtype}')
    values = keys
    if isinstance(keys, (sparse_tensor.SparseTensor, internal.RaggedTensor)):
        values = keys.values
    if self._table and self._table.key_dtype.base_dtype == dtypes.int64:
        values = math_ops.cast(values, dtypes.int64)
    if self._num_oov_buckets == 0:
        ids = self._table.lookup(values, name=name)
    else:
        with ops.name_scope(name, '%s_Lookup' % self.name):
            str_to_hash_bucket = self._get_string_to_hash_bucket_fn(self._hasher_spec)
            buckets = str_to_hash_bucket(_as_string(values), num_buckets=self._num_oov_buckets, name='hash_bucket')
            if <MASK>:
                ids = self._table.lookup(values)
                buckets = math_ops.add(buckets, self._table.size())
                is_id_non_default = math_ops.not_equal(ids, self._table.default_value)
                ids = array_ops.where_v2(is_id_non_default, ids, buckets)
            else:
                ids = buckets
    if isinstance(keys, sparse_tensor.SparseTensor):
        return sparse_tensor.SparseTensor(keys.indices, ids, keys.dense_shape)
    elif isinstance(keys, internal.RaggedTensor):
        return keys.with_values(ids)
    return ids

@classmethod
def _find_localzeros(cls, values, **options):
    """
        Sequentially allocate values to localzeros.

        When a value is identified as being more extreme than another member it
        replaces that member; if this is never true, then the value is simply
        appended to the localzeros.

        Unlike the sympy implementation, we only look for zero and one, we don't
        do generic is connected test pairwise which is slow
        """
    other_values = set()
    num_value = None
    for arg in values:
        if <MASK>:
            if num_value is None:
                num_value = arg
            elif cls is Max:
                num_value = max(num_value, arg)
            elif cls is Min:
                num_value = min(num_value, arg)
            else:
                raise AssertionError(f'impossible {cls}')
        else:
            other_values.add(arg)
    if num_value is None:
        return other_values
    if len(other_values) == 0:
        return {num_value}
    if len(other_values) == 1:
        other_value = next(iter(other_values))
        if num_value in (0.0, 0) and other_value.is_nonnegative:
            return other_values if cls is Max else {num_value}
        if num_value == 1 and other_value.is_positive:
            return other_values if cls is Max else {num_value}
    other_values.add(num_value)
    return other_values

def schedule_fn(step: int) -> ProfilerAction:
    assert step >= 0
    if step < skip_first:
        return ProfilerAction.NONE
    else:
        step -= skip_first
    if skip_first_wait != 0:
        step += wait
    num_steps = wait + warmup + active
    if repeat > 0 and step / num_steps >= repeat:
        return ProfilerAction.NONE
    mod_step = step % num_steps
    if <MASK>:
        return ProfilerAction.NONE
    elif mod_step < wait + warmup:
        return ProfilerAction.WARMUP
    else:
        return ProfilerAction.RECORD if mod_step < num_steps - 1 else ProfilerAction.RECORD_AND_SAVE

def rename_field(self, app_label, model_name, old_name, new_name):
    model_key = (app_label, model_name)
    model_state = self.models[model_key]
    fields = model_state.fields
    try:
        found = fields.pop(old_name)
    except KeyError:
        raise FieldDoesNotExist(f"{app_label}.{model_name} has no field named '{old_name}'")
    fields[new_name] = found
    for field in fields.values():
        from_fields = getattr(field, 'from_fields', None)
        if from_fields:
            field.from_fields = tuple([new_name if from_field_name == old_name else from_field_name for from_field_name in from_fields])
        if (field_names := getattr(field, 'field_names', None)):
            if old_name in field_names:
                field.field_names = tuple([new_name if field_name == old_name else field_name for field_name in field.field_names])
    options = model_state.options
    for option in ('index_together', 'unique_together'):
        if option in options:
            options[option] = [[new_name if n == old_name else n for n in together] for together in options[option]]
    delay = True
    references = get_references(self, model_key, (old_name, found))
    for (*_, field, reference) in references:
        delay = False
        if reference.to:
            (remote_field, to_fields) = reference.to
            if getattr(remote_field, 'field_name', None) == old_name:
                remote_field.field_name = new_name
            if to_fields:
                field.to_fields = tuple([new_name if to_field_name == old_name else to_field_name for to_field_name in to_fields])
    if <MASK>:
        old_name_lower = old_name.lower()
        new_name_lower = new_name.lower()
        for to_model in self._relations.values():
            if old_name_lower in to_model[model_key]:
                field = to_model[model_key].pop(old_name_lower)
                field.name = new_name_lower
                to_model[model_key][new_name_lower] = field
    self.reload_model(*model_key, delay=delay)

def prep_with_inputs(self, inputs: tuple[torch.Tensor]) -> None:
    if <MASK>:
        return
    for idx in self.params_indices:
        grad = inputs[idx].grad
        if grad is not None:
            assert not torch.isnan(grad).any(), f'Compiled autograd running under anomaly mode with inputs[{idx}] already having NaN gradient. This is not supported. {TURN_OFF_MSG}'
        self.params_to_check[f'inputs[{idx}]'] = inputs[idx]

@ops.RegisterGradient('Sum')
def _SumGrad(op: ops.Operation, grad):
    """Gradient for Sum."""
    input_0_shape = op.inputs[0]._shape_tuple()
    if input_0_shape is not None:
        axes = tensor_util.constant_value(op.inputs[1])
        if axes is not None:
            rank = len(input_0_shape)
            if np.array_equal(axes, np.arange(rank)):
                if context.executing_eagerly():
                    ctx = context.context()
                    new_shape = ctx.ones_rank_cache().get(rank)
                    if new_shape is None:
                        new_shape = constant_op.constant([1] * rank, dtype=dtypes.int32)
                        ctx.ones_rank_cache().put(rank, new_shape)
                else:
                    new_shape = [1] * rank
                grad = array_ops.reshape(grad, new_shape)
                if <MASK>:
                    input_shape = constant_op.constant(input_0_shape, dtype=dtypes.int32)
                else:
                    input_shape = array_ops.shape(op.inputs[0])
                return [array_ops.tile(grad, input_shape), None]
            elif None not in input_0_shape and (not context.executing_eagerly()):
                graph = ops.get_default_graph()
                axes = tuple(axes.reshape(-1))
                try:
                    (output_shape_kept_dims, tile_scaling) = graph._reduced_shape_cache[input_0_shape, axes]
                except KeyError:

                    def EvaluateAsTuple(t):
                        if tensor_util.is_tf_type(t):
                            value = tensor_util.try_evaluate_constant(t)
                            assert value is not None
                        else:
                            value = t
                        return tuple(value)
                    output_shape_kept_dims = EvaluateAsTuple(math_ops.reduced_shape(input_0_shape, axes))
                    tile_scaling = EvaluateAsTuple(_SafeShapeDiv(input_0_shape, output_shape_kept_dims))
                    graph._reduced_shape_cache[input_0_shape, axes] = (output_shape_kept_dims, tile_scaling)
                grad = array_ops.reshape(grad, output_shape_kept_dims)
                return [array_ops.tile(grad, tile_scaling), None]
    input_shape = array_ops.shape(op.inputs[0])
    if not op.get_attr('keep_dims'):
        with ops.colocate_with(input_shape):
            output_shape_kept_dims = math_ops.reduced_shape(input_shape, op.inputs[1])
        grad = array_ops.reshape(grad, output_shape_kept_dims)
    return [array_ops.broadcast_to(grad, input_shape), None]

def check_meta_consistency(lhs_list: list[Union[torch.Tensor, torch.SymInt, int]], rhs_list: list[Union[torch.Tensor, torch.SymInt, int]], lhs_name: str, rhs_name: str, include_contiguity: bool=True) -> None:

    def diff_meta_pairs(lhs_list: list[Union[torch.Tensor, torch.SymInt, int]], rhs_list: list[Union[torch.Tensor, torch.SymInt, int]]) -> list[str]:

        def diff_meta(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
            if <MASK>:
                return ', '.join(diff_tensor_meta(_extract_tensor_metadata(lhs, include_contiguity=include_contiguity), _extract_tensor_metadata(rhs, include_contiguity=include_contiguity), check_grad=False))
            else:

                def _both_int_types(lhs, rhs):
                    return isinstance(lhs, (int, torch.SymInt)) and isinstance(rhs, (int, torch.SymInt))

                def _both_tensor(lhs, rhs):
                    return isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor)
                if not _both_int_types(lhs, rhs) and (not _both_tensor(lhs, rhs)):
                    return f'type: {lhs} vs {rhs}'
            return ''

        def diff_device(lhs: Union[torch.Tensor, torch.SymInt, int], rhs: Union[torch.Tensor, torch.SymInt, int]) -> str:
            if isinstance(lhs, torch.Tensor) and isinstance(rhs, torch.Tensor):
                if rhs.device.type == lhs.device.type and rhs.device.index == lhs.device.index:
                    return ''
                else:
                    return 'device'
            return ''
        if len(lhs_list) != len(rhs_list):
            raise torch._dynamo.exc.UncapturedHigherOrderOpError(f'Expected {lhs_name} and {rhs_name} to have same number of outputs but got lhs:{lhs_list} and rhs:{rhs_list}')
        all_diffs = []
        for (i, (lhs, rhs)) in enumerate(zip(lhs_list, rhs_list)):
            if (diff := diff_meta(lhs, rhs)):
                all_diffs.append(f'pair[{i}] differ in {diff}, where lhs is {lhs} and rhs is {rhs}')
            if (diff := diff_device(lhs, rhs)):
                all_diffs.append(f'pair[{i}] differ in {diff}, where lhs is {lhs} and rhs is {rhs}')
        return all_diffs
    if (all_diffs := diff_meta_pairs(lhs_list, rhs_list)):
        diff_str = '\n'.join(all_diffs)
        raise torch._dynamo.exc.UncapturedHigherOrderOpError(f'Expected {lhs_name} and {rhs_name} to have same metadata but found:\n{diff_str}')

def _next_line(self) -> list[Scalar]:
    if isinstance(self.data, list):
        while self.skipfunc(self.pos):
            if self.pos >= len(self.data):
                break
            self.pos += 1
        while True:
            try:
                line = self._check_comments([self.data[self.pos]])[0]
                self.pos += 1
                if not self.skip_blank_lines and (self._is_line_empty(self.data[self.pos - 1]) or line):
                    break
                if self.skip_blank_lines:
                    ret = self._remove_empty_lines([line])
                    if ret:
                        line = ret[0]
                        break
            except IndexError as err:
                raise StopIteration from err
    else:
        while self.skipfunc(self.pos):
            self.pos += 1
            next(self.data)
        while True:
            orig_line = self._next_iter_line(row_num=self.pos + 1)
            self.pos += 1
            if <MASK>:
                line = self._check_comments([orig_line])[0]
                if self.skip_blank_lines:
                    ret = self._remove_empty_lines([line])
                    if ret:
                        line = ret[0]
                        break
                elif self._is_line_empty(orig_line) or line:
                    break
    if self.pos == 1:
        line = self._check_for_bom(line)
    self.line_pos += 1
    self.buf.append(line)
    return line

@cache
def get_pr_number() -> int | None:
    pr_number = os.environ.get('PR_NUMBER', '')
    if pr_number == '':
        re_match = re.match('^refs/tags/.*/(\\d+)$', os.environ.get('GITHUB_REF', ''))
        if re_match is not None:
            pr_number = re_match.group(1)
    if <MASK>:
        return int(pr_number)
    return None

def __array_ufunc__(self, ufunc: np.ufunc, method: str, *inputs, **kwargs):
    out = kwargs.get('out', ())
    for x in inputs + out:
        if not isinstance(x, self._HANDLED_TYPES + (SparseArray,)):
            return NotImplemented
    result = arraylike.maybe_dispatch_ufunc_to_dunder_op(self, ufunc, method, *inputs, **kwargs)
    if result is not NotImplemented:
        return result
    if 'out' in kwargs:
        res = arraylike.dispatch_ufunc_with_out(self, ufunc, method, *inputs, **kwargs)
        return res
    if method == 'reduce':
        result = arraylike.dispatch_reduction_ufunc(self, ufunc, method, *inputs, **kwargs)
        if result is not NotImplemented:
            return result
    if len(inputs) == 1:
        sp_values = getattr(ufunc, method)(self.sp_values, **kwargs)
        fill_value = getattr(ufunc, method)(self.fill_value, **kwargs)
        if <MASK>:
            arrays = tuple((self._simple_new(sp_value, self.sp_index, SparseDtype(sp_value.dtype, fv)) for (sp_value, fv) in zip(sp_values, fill_value, strict=True)))
            return arrays
        elif method == 'reduce':
            return sp_values
        return self._simple_new(sp_values, self.sp_index, SparseDtype(sp_values.dtype, fill_value))
    new_inputs = tuple((np.asarray(x) for x in inputs))
    result = getattr(ufunc, method)(*new_inputs, **kwargs)
    if out:
        if len(out) == 1:
            out = out[0]
        return out
    if ufunc.nout > 1:
        return tuple((type(self)(x) for x in result))
    elif method == 'at':
        return None
    else:
        return type(self)(result)

def test_function_with_default_none_input(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')

    def func(x, dtype=None):
        if dtype:
            return array_ops.zeros(shape=x.shape, dtype=dtype)
        else:
            return array_ops.zeros(shape=x.shape, dtype=dtypes.float32)
    root = autotrackable.AutoTrackable()
    root.f = def_function.function(func)
    self.assertAllEqual([0.0, 0.0, 0.0], root.f(constant_op.constant([1, 2, 3])).numpy())
    self.assertAllEqual([0.0, 0.0, 0.0], root.f(constant_op.constant([1.0, 2.0, 3.0])).numpy())
    self.assertAllEqual([0.0, 0.0, 0.0, 0.0], root.f(constant_op.constant([1, 2, 3, 4])).numpy())
    self.assertAllEqual([0, 0, 0], root.f(constant_op.constant([1.0, 2.0, 3.0]), dtype=dtypes.int32).numpy())
    concrete_functions = root.f._list_all_concrete_functions_for_serialization()
    self.assertLen(concrete_functions, 4)
    imported = cycle(root, cycles, use_cpp_bindings=use_cpp_bindings)
    restored_concrete_functions = imported.f._list_all_concrete_functions()
    self.assertLen(restored_concrete_functions, 4)
    self.assertAllEqual([0.0, 0.0, 0.0], imported.f(constant_op.constant([1, 2, 3]), None).numpy())
    self.assertAllEqual([0.0, 0.0, 0.0], imported.f(constant_op.constant([1.0, 2.0, 3.0])).numpy())
    self.assertAllEqual([0.0, 0.0, 0.0, 0.0], imported.f(constant_op.constant([1, 2, 3, 4])).numpy())
    self.assertAllEqual([0, 0, 0], imported.f(constant_op.constant([1.0, 2.0, 3.0]), dtype=dtypes.int32).numpy())

@register_decomposition(aten._softmax_backward_data.default)
@pw_cast_for_opmath
def _softmax_backward_data(grad_output: torch.Tensor, output: torch.Tensor, dim: int, input_dtype: torch.dtype) -> torch.Tensor:
    new_grad_output = grad_output * output
    sum_new_grad = torch.sum(new_grad_output, dim=dim, keepdim=True)
    grad_input = inductor_prims.fma(-output, sum_new_grad, new_grad_output)
    if <MASK>:
        grad_input = grad_input.to(input_dtype)
    return grad_input.contiguous()

def _key(type_, context, i):
    if type_ is dict:
        return MappingKey(context[i])
    if <MASK>:
        assert context is None
        return SequenceKey(i)
    raise AssertionError(f'Did not expect type {type_}')

@wraps(fn)
def wrapped_fn(gm):
    res = fn(gm)
    if <MASK>:
        return PassResult(gm, True)
    if isinstance(res, PassResult):
        return res
    elif isinstance(res, nn.Module):
        return PassResult(res, True)

def as_storage_and_layout(x: IRNode, freeze: bool=True, want_contiguous: bool=False, stride_order: Optional[Sequence[Union[int, Integer]]]=None, allow_padding: bool=False, exact_strides: Optional[Sequence[Union[int, Integer]]]=None) -> tuple[StorageBox, Layout]:
    """
    Try to simplify x into a StorageBox and a Layout.

    allow_padding only affect how we apply stride_order. When allow_padding
    is True, we have the freedom to add padding when applying the stride_order.
    """
    if isinstance(x, TensorBox):
        return as_storage_and_layout(x.data, freeze=freeze, want_contiguous=want_contiguous, stride_order=stride_order, allow_padding=allow_padding, exact_strides=exact_strides)
    if isinstance(x, StorageBox):
        (_, layout) = as_storage_and_layout(x.data, freeze=freeze, want_contiguous=want_contiguous, stride_order=stride_order, allow_padding=allow_padding, exact_strides=exact_strides)
        return (x, x.data.get_layout())
    if isinstance(x, Buffer):
        if freeze:
            if want_contiguous:
                x.freeze_layout()
                assert x.get_layout().is_contiguous()
            elif stride_order is not None:
                x.freeze_layout_with_stride_order(stride_order, allow_padding=allow_padding)
            elif <MASK>:
                x.freeze_layout_with_exact_strides(exact_strides, allow_padding=allow_padding)
            else:
                x.decide_layout()
        return (StorageBox(x), x.get_layout())
    if isinstance(x, ReinterpretView):
        (buffer, _) = as_storage_and_layout(x.data, freeze=freeze)
        return (buffer, x.layout)
    raise NotImplementedError

def get_current_semver_version():
    """Returns a Version object of current version.

  Returns:
    version: Version object of current SemVer string based on information from
    .bazelrc and tf_version.bzl files.
  """
    bazel_rc_file = open(BAZEL_RC, 'r')
    wheel_type = ''
    wheel_build_date = ''
    wheel_version_suffix = ''
    for line in bazel_rc_file:
        wheel_type = _get_regex_match(line, '^common --repo_env=ML_WHEEL_TYPE="(.+)"')[0] or wheel_type
        wheel_build_date = _get_regex_match(line, '^common --repo_env=ML_WHEEL_BUILD_DATE="([0-9]*)"')[0] or wheel_build_date
        (wheel_version_suffix, is_matched) = _get_regex_match(line, '^common --repo_env=ML_WHEEL_VERSION_SUFFIX="(.*)"', is_last_match=True)
        if <MASK>:
            break
    tf_version_bzl_file = open(TF_VERSION_BZL, 'r')
    wheel_version = ''
    for line in tf_version_bzl_file:
        (wheel_version, is_matched) = _get_regex_match(line, '^TF_VERSION = "([0-9.]+)"', is_last_match=True)
        if is_matched:
            break
    (old_major, old_minor, old_patch_num) = wheel_version.split('.')
    if wheel_type == 'nightly':
        version_type = NIGHTLY_VERSION
    else:
        version_type = SNAPSHOT_VERSION
    old_extension = ''
    if wheel_type == 'nightly':
        old_extension = '-dev{}'.format(wheel_build_date)
    else:
        if wheel_build_date:
            old_extension += '-dev{}'.format(wheel_build_date)
        if wheel_version_suffix:
            old_extension += wheel_version_suffix
    return Version(old_major, old_minor, old_patch_num, old_extension, version_type)

def inner(model_iter_fn: Callable):

    def _torchao_apply(module: torch.nn.Module, example_inputs: Any):
        if getattr(module, '_quantized', None) is None:
            if <MASK>:
                quantize_(module, int8_dynamic_activation_int8_weight(), set_inductor_config=False)
            elif quantization == 'int8weightonly':
                quantize_(module, int8_weight_only(), set_inductor_config=False)
            elif quantization == 'int4weightonly':
                quantize_(module, int4_weight_only(), set_inductor_config=False)
            if quantization == 'autoquant':
                autoquant(module, error_on_unseen=False, set_inductor_config=False)
                if isinstance(example_inputs, dict):
                    module(**example_inputs)
                else:
                    module(*example_inputs)
                from torchao.quantization.autoquant import AUTOQUANT_CACHE
                if len(AUTOQUANT_CACHE) == 0:
                    raise Exception(f'NotAutoquantizableFound no autoquantizable layers in model {type(module)}, stopping autoquantized run')
            else:
                unwrap_tensor_subclass(module)
            setattr(module, '_quantized', True)
        model_iter_fn(module, example_inputs)
    return _torchao_apply

def clean_nn_module_stack_and_source_fn(graph_module: torch.fx.GraphModule, is_inline_builtin=False) -> torch.fx.GraphModule:
    """
    Clean up nn_module_stack metadata by removing export_root references.

    Removes the _export_root module references from nn_module_stack metadata
    in graph nodes, which are artifacts from the export process. Fixes two patterns:

    1. Keys: Removes "__export_root_" and "__modules['_export_root']_" prefixes
       - Normal case: "L__self____export_root_child" -> "L__self__child"
       - inline_builtin case: Uses numeric ID strings like "140468831433840"

    2. Values: Removes "._export_root" and "._modules['_export_root']" from child names
       e.g., "L['self']._export_root.child" -> "L['self'].child"
       e.g., "L['self']._modules['_export_root'].child" -> "L['self'].child"

    Also removes the root export entry "L__self____export_root" entirely.

    Args:
        graph_module: The GraphModule to clean up
        is_inline_builtin: If True, keys are numeric ID strings and self references
                          (L['self']) are filtered out

    Returns:
        The cleaned GraphModule (modified in-place)
    """

    def _process_nn_module_stack(nn_module_stack):
        if 'L__self____export_root' in nn_module_stack:
            del nn_module_stack['L__self____export_root']
        cleaned_stack = {}
        for (key, (child_name, child_class)) in nn_module_stack.items():
            clean_key = clean_export_root_string(key)
            clean_name = clean_export_root_string(child_name)
            if is_inline_builtin and clean_name == "L['self']":
                continue
            cleaned_stack[clean_key] = (clean_name, child_class)
        return cleaned_stack

    def _process_source_fn(source_fn_stack):
        cleaned_stack = []
        for item in source_fn_stack:
            if isinstance(item, tuple) and len(item) == 2:
                (name, cls) = item
                if isinstance(name, str):
                    clean_name = clean_export_root_string(name)
                    cleaned_stack.append((clean_name, cls))
                else:
                    cleaned_stack.append(item)
            else:
                cleaned_stack.append(item)
        return cleaned_stack
    for node in graph_module.graph.nodes:
        if 'nn_module_stack' in node.meta:
            node.meta['nn_module_stack'] = _process_nn_module_stack(node.meta['nn_module_stack'].copy())
        if <MASK>:
            node.meta['source_fn_stack'] = _process_source_fn(node.meta['source_fn_stack'].copy())
    if 'dynamo_flat_name_to_original_fqn' in graph_module.meta:
        clean_name_to_original_fqn = {}
        for (flat_name, original_fqn) in graph_module.meta['dynamo_flat_name_to_original_fqn'].items():
            clean_name_to_original_fqn[clean_export_root_string(flat_name)] = clean_export_root_string(original_fqn)
        graph_module.meta['dynamo_flat_name_to_original_fqn'] = clean_name_to_original_fqn
    return graph_module

def _normalize_backend_override(backend_override: dict[Union[int, str], Union[str, C10dBackend.Options, tuple[str, C10dBackend.Options]]], ndim: int, mesh_dim_names: Optional[tuple[str, ...]]=None) -> Iterator[BackendConfig]:
    if mesh_dim_names is None:
        mesh_dim_names = ()
    for (dim_idx, dim_name) in zip_longest(range(ndim), mesh_dim_names):
        if dim_name is not None and dim_name in backend_override:
            if dim_idx in backend_override:
                raise RuntimeError(f'Found redundant dim index {dim_idx} and name {dim_name} in backend_override')
            val = backend_override.pop(dim_name)
        elif dim_idx in backend_override:
            val = backend_override.pop(dim_idx)
        else:
            yield (None, None)
            continue
        if <MASK>:
            yield (val, None)
        elif isinstance(val, C10dBackend.Options):
            yield (None, val)
        else:
            yield val
    if backend_override:
        raise RuntimeError(f'Found invalid keys in backend_override: got {list(backend_override.keys())}, expected integers in range [0, {ndim}) or one of {mesh_dim_names}')

def generate_libtorch_matrix(os: str, release_type: str, arches: Optional[list[str]]=None, libtorch_variants: Optional[list[str]]=None) -> list[dict[str, str]]:
    if arches is None:
        arches = ['cpu']
        if <MASK>:
            arches += CUDA_ARCHES
            arches += ROCM_ARCHES
        elif os == 'windows':
            windows_cuda_arches = CUDA_ARCHES.copy()
            windows_cuda_arches.remove('12.9')
            arches += windows_cuda_arches
    if libtorch_variants is None:
        libtorch_variants = ['shared-with-deps', 'shared-without-deps', 'static-with-deps', 'static-without-deps']
    ret: list[dict[str, str]] = []
    for arch_version in arches:
        for libtorch_variant in libtorch_variants:
            gpu_arch_type = arch_type(arch_version)
            gpu_arch_version = '' if arch_version == 'cpu' else arch_version
            if gpu_arch_type == 'rocm' and 'without-deps' in libtorch_variant:
                continue
            ret.append({'gpu_arch_type': gpu_arch_type, 'gpu_arch_version': gpu_arch_version, 'desired_cuda': translate_desired_cuda(gpu_arch_type, gpu_arch_version), 'libtorch_config': release_type, 'libtorch_variant': libtorch_variant, 'container_image': LIBTORCH_CONTAINER_IMAGES[arch_version].split(':')[0] if os not in ('windows', 'windows-arm64') else '', 'container_image_tag_prefix': LIBTORCH_CONTAINER_IMAGES[arch_version].split(':')[1] if os not in ('windows', 'windows-arm64') else '', 'package_type': 'libtorch', 'build_name': f'libtorch-{gpu_arch_type}{gpu_arch_version}-{libtorch_variant}-{release_type}'.replace('.', '_')})
    return ret

