    imported = cycle(root, cycles, signatures={}, use_cpp_bindings=use_cpp_bindings)
    self.assertAllEqual([2, 4, 6], imported.f(x=constant_op.constant([1, 2, 3])).numpy())

def update_state(self, values, sample_weight=None):
    """Accumulates statistics for computing the metric.

    Args:
      values: Per-example value.
      sample_weight: Optional weighting of each example. Defaults to 1.

    Returns:
      Update op.
    """
    ([values], sample_weight) = metrics_utils.ragged_assert_compatible_and_get_flat_values([values], sample_weight)
    try:
        values = math_ops.cast(values, self._dtype)
    except (ValueError, TypeError):
        msg = 'The output of a metric function can only be a single Tensor. Got: %s' % (values,)
        if isinstance(values, dict):
            msg += '. To return a dict of values, implement a custom Metric subclass.'
        raise RuntimeError(msg)
    if sample_weight is not None:
        sample_weight = math_ops.cast(sample_weight, self._dtype)
        (values, _, sample_weight) = losses_utils.squeeze_or_expand_dimensions(values, sample_weight=sample_weight)
        try:
            sample_weight = weights_broadcast_ops.broadcast_weights(sample_weight, values)
        except ValueError:
            ndim = backend.ndim(values)
            weight_ndim = backend.ndim(sample_weight)
            if <MASK>:
                values = math_ops.reduce_sum(values, axis=list(range(weight_ndim, ndim)))
            else:
                values = math_ops.reduce_mean(values, axis=list(range(weight_ndim, ndim)))
        values = math_ops.multiply(values, sample_weight)
    value_sum = math_ops.reduce_sum(values)
    with ops.control_dependencies([value_sum]):
        update_total_op = self.total.assign_add(value_sum)
    if self.reduction == metrics_utils.Reduction.SUM:
        return update_total_op
    if self.reduction == metrics_utils.Reduction.SUM_OVER_BATCH_SIZE:
        num_values = math_ops.cast(array_ops.size(values), self._dtype)
    elif self.reduction == metrics_utils.Reduction.WEIGHTED_MEAN:
        if sample_weight is None:
            num_values = math_ops.cast(array_ops.size(values), self._dtype)
        else:
            num_values = math_ops.reduce_sum(sample_weight)
    else:
        raise NotImplementedError('reduction [%s] not implemented' % self.reduction)
    with ops.control_dependencies([update_total_op]):
        return self.count.assign_add(num_values)

@property
def device_time_total(self):
    if self.is_async or not self.use_device:
        return 0
    if self.device_type == DeviceType.CPU:
        if <MASK>:
            return sum((kinfo.duration for kinfo in self.kernels)) + sum((ch.device_time_total for ch in self.cpu_children))
        else:
            return sum((kinfo.duration for kinfo in self.kernels))
    else:
        if self.device_type not in [DeviceType.CUDA, DeviceType.PrivateUse1, DeviceType.MTIA, DeviceType.HPU]:
            raise AssertionError(f'Expected device_type to be CUDA, PrivateUse1, MTIA, or HPU, but got {self.device_type}')
        return self.time_range.elapsed_us()

def __sym_dispatch__(self, func: OpOverload, types: tuple[torch._C._TensorMeta, ...], args: tuple[object, ...], kwargs: dict[str, object]) -> object:
    if func == operator.mul:
        if <MASK>:
            return args[0]
        elif isinstance(args[0], int) and args[0] == 1:
            return args[1]
    assert not kwargs
    out = func(*args, **kwargs)
    _sym_register(self.tracer, func, args, out)
    return out

def __init__(self, data=None, index: Axes | None=None, columns: Axes | None=None, dtype: Dtype | None=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if isinstance(data, DataFrame):
        data = data._mgr
        allow_mgr = True
        if not copy:
            data = data.copy(deep=False)
    if isinstance(data, BlockManager):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        if index is None and columns is None and (dtype is None) and (not copy):
            NDFrame.__init__(self, data)
            return
    if isinstance(index, set):
        raise ValueError('index cannot be a set')
    if isinstance(columns, set):
        raise ValueError('columns cannot be a set')
    if copy is None:
        if isinstance(data, dict):
            copy = True
        elif not isinstance(data, (Index, DataFrame, Series)):
            copy = True
        else:
            copy = False
    if data is None:
        index = index if index is not None else default_index(0)
        columns = columns if columns is not None else default_index(0)
        dtype = dtype if dtype is not None else pandas_dtype(object)
        data = []
    if isinstance(data, BlockManager):
        mgr = self._init_mgr(data, axes={'index': index, 'columns': columns}, dtype=dtype, copy=copy)
    elif isinstance(data, dict):
        mgr = dict_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, ma.MaskedArray):
        from numpy.ma import mrecords
        if isinstance(data, mrecords.MaskedRecords):
            raise TypeError('MaskedRecords are not supported. Pass {name: data[name] for name in data.dtype.names} instead')
        data = sanitize_masked_array(data)
        mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, (np.ndarray, Series, Index, ExtensionArray)):
        if data.dtype.names:
            data = cast(np.ndarray, data)
            mgr = rec_array_to_mgr(data, index, columns, dtype, copy)
        elif isinstance(data, (ABCSeries, ABCIndex)) and data.name is not None:
            mgr = dict_to_mgr({data.name: data}, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif is_list_like(data):
        if not isinstance(data, abc.Sequence):
            if hasattr(data, '__array__'):
                data = np.asarray(data)
            else:
                data = list(data)
        if len(data) > 0:
            if is_dataclass(data[0]):
                data = dataclasses_to_dicts(data)
            if not isinstance(data, np.ndarray) and treat_as_nested(data):
                if <MASK>:
                    columns = ensure_index(columns)
                (arrays, columns, index) = nested_data_to_arrays(data, columns, index, dtype)
                mgr = arrays_to_mgr(arrays, columns, index, dtype=dtype)
            else:
                mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = dict_to_mgr({}, index, columns if columns is not None else default_index(0), dtype=dtype)
    else:
        if index is None or columns is None:
            raise ValueError('DataFrame constructor not properly called!')
        index = ensure_index(index)
        columns = ensure_index(columns)
        if not dtype:
            (dtype, _) = infer_dtype_from_scalar(data)
        if isinstance(dtype, ExtensionDtype):
            values = [construct_1d_arraylike_from_scalar(data, len(index), dtype) for _ in range(len(columns))]
            mgr = arrays_to_mgr(values, columns, index, dtype=None)
        else:
            arr2d = construct_2d_arraylike_from_scalar(data, len(index), len(columns), dtype, copy)
            mgr = ndarray_to_mgr(arr2d, index, columns, dtype=arr2d.dtype, copy=False)
    NDFrame.__init__(self, mgr)

def generate_saveable_objects(checkpoint_factory_map, object_graph_proto=None, node_ids=None, object_map=None, call_with_mapped_captures=None, saveables_cache=None):
    """Create SaveableObjects and corresponding SerializedTensor protos."""
    named_saveable_objects = []
    if saveables_cache is None:
        feed_additions = None
    else:
        feed_additions = {}
    for (trackable, factory_data_list) in checkpoint_factory_map.items():
        fill_object_proto = object_graph_proto is not None and node_ids is not None
        if fill_object_proto:
            object_proto = object_graph_proto.nodes[node_ids[trackable]]
        object_to_save = util.get_mapped_trackable(trackable, object_map)
        if saveables_cache is not None:
            cached_attributes = saveables_cache.setdefault(object_to_save, {})
        else:
            cached_attributes = None
        for factory_data in factory_data_list:
            name = factory_data.name
            key = factory_data.checkpoint_key
            saveable_factory = factory_data.factory
            saveables = cached_attributes.get(name) if cached_attributes else None
            if saveables is not None:
                for saveable in saveables:
                    if key not in saveable.name:
                        saveables = None
                        del cached_attributes[name]
                        break
            if saveables is None:
                if callable(saveable_factory):
                    maybe_saveable = saveable_object_util.create_saveable_object(name, key, saveable_factory, call_with_mapped_captures)
                else:
                    maybe_saveable = saveable_factory
                if isinstance(maybe_saveable, saveable_object_lib.SaveableObject):
                    saveables = (maybe_saveable,)
                else:
                    saveables = tuple(saveable_object_util.saveable_objects_for_op(op=maybe_saveable, name=key))
                for saveable in saveables:
                    if key not in saveable.name:
                        raise AssertionError(f"The object {trackable} produced a SaveableObject with name '{saveable.name}' for attribute '{name}'. Expected a name containing '{key}'.")
                if cached_attributes is not None:
                    cached_attributes[name] = saveables
            if <MASK>:
                assert len(saveables) == 1
                saveable = saveables[0]
                if feed_additions is None:
                    assert saveables_cache is None
                    saveables = (saveable.freeze(),)
                else:
                    feed_additions.update(saveable.feed_dict_additions())
            named_saveable_objects.extend(saveables)
            if not fill_object_proto:
                continue
            if isinstance(saveables[0], saveable_object_util.TrackableSaveable) and (saveable_compat.force_checkpoint_conversion_enabled() or saveable_compat.get_saveable_name(object_to_save) is None):
                for (local_name, local_key) in saveables[0].get_proto_names_and_checkpoint_keys():
                    object_proto.attributes.add(name=local_name, checkpoint_key=local_key, full_name=util.get_full_name(object_to_save))
            else:
                object_proto.attributes.add(name=name, checkpoint_key=key, full_name=util.get_full_name(object_to_save))
    return (named_saveable_objects, feed_additions)

