        new_api = f'torch.func.{api}'
    warning = f"We've integrated functorch into PyTorch. As the final step of the \nintegration, `functorch.{api}` is deprecated as of PyTorch \n2.0 and will be deleted in a future version of PyTorch >= 2.3. \nPlease use `{new_api}` instead; see the PyTorch 2.0 release notes \nand/or the `torch.func` migration guide for more details \nhttps://pytorch.org/docs/main/func.migrating.html"
    if <MASK>:
