def visit_manager(node: GuardManager) -> bool:
    assert not isinstance(node, DictGuardManager)
    is_diff_guard_node = node.get_source() in self.diff_guard_sources or node.fail_count() > 0
    for child_mgr in node.get_child_managers():
        is_diff_guard_node |= visit(child_mgr)
    if <MASK>:
        self.diff_guard_sources.add(node.get_source())
    return is_diff_guard_node

@compatibility(is_backward_compatible=False)
def is_consistent(t1, t2):
    """
    A binary relation denoted by ~ that determines if t1 is consistent with t2.
    The relation is reflexive, symmetric but not transitive.
    returns True if t1 and t2 are consistent and False otherwise.
    Example:
        Dyn ~ TensorType((1,2,3))
        int ~ Dyn
        int ~ int
        TensorType((1,Dyn,3)) ~ TensorType((1,2,3))
    """
    if <MASK>:
        return True
    if t1 == Dyn or t2 == Dyn or isinstance(t1, Var) or isinstance(t2, Var):
        return True
    if isinstance(t1, TensorType) and isinstance(t2, TensorType):
        return len(t1.__args__) == len(t2.__args__) and all((is_consistent(elem1, elem2) for (elem1, elem2) in zip(t1.__args__, t2.__args__)))
    else:
        return False

def int_padding_for_string_padding(func, padding_style, dilation, kernel_size):

    def get_dilation(i):
        return dilation[i] if isinstance(dilation, tuple) else dilation
    if padding_style == 'same':
        padding: list[int] = []
        for i in range(conv_picker(func, 0, 1, 2), -1, -1):
            padding += conv_padding_for_same(get_dilation(i), kernel_size[i])
        return padding
    elif <MASK>:
        return conv_picker(func, 2, 4, 6) * (0,)
    else:
        raise RuntimeError(f"got padding type of {padding_style}, only accept 'same' or 'valid'")

def process_request(self, request):
    """
        Check for denied User-Agents and rewrite the URL based on
        settings.APPEND_SLASH and settings.PREPEND_WWW
        """
    user_agent = request.META.get('HTTP_USER_AGENT')
    if user_agent is not None:
        for user_agent_regex in settings.DISALLOWED_USER_AGENTS:
            if user_agent_regex.search(user_agent):
                raise PermissionDenied('Forbidden user agent')
    host = request.get_host()
    if <MASK>:
        if self.should_redirect_with_slash(request):
            path = self.get_full_path_with_slash(request)
        else:
            path = request.get_full_path()
        return self.response_redirect_class(f'{request.scheme}://www.{host}{path}')

def _tf_core_assert_shallow_structure(shallow_tree, input_tree, check_types=True, expand_composites=False):
    is_nested_fn = _is_nested_or_composite if expand_composites else _tf_core_is_nested
    if is_nested_fn(shallow_tree):
        if not is_nested_fn(input_tree):
            raise TypeError('If shallow structure is a sequence, input must also be a sequence. Input has type: %s.' % type(input_tree))
        if isinstance(shallow_tree, _wrapt.ObjectProxy):
            shallow_type = type(shallow_tree.__wrapped__)
        else:
            shallow_type = type(shallow_tree)
        if check_types and (not isinstance(input_tree, shallow_type)):
            shallow_is_namedtuple = is_namedtuple(shallow_tree, False)
            input_is_namedtuple = is_namedtuple(input_tree, False)
            if shallow_is_namedtuple and input_is_namedtuple:
                if not same_namedtuples(shallow_tree, input_tree):
                    raise TypeError(STRUCTURES_HAVE_MISMATCHING_TYPES.format(input_type=type(input_tree), shallow_type=type(shallow_tree)))
            elif isinstance(shallow_tree, list) and isinstance(input_tree, list):
                pass
            elif (_is_composite_tensor(shallow_tree) or _is_type_spec(shallow_tree)) and (_is_composite_tensor(input_tree) or _is_type_spec(input_tree)):
                pass
            elif not (isinstance(shallow_tree, _collections_abc.Mapping) and isinstance(input_tree, _collections_abc.Mapping)):
                raise TypeError(STRUCTURES_HAVE_MISMATCHING_TYPES.format(input_type=type(input_tree), shallow_type=type(shallow_tree)))
        if _is_composite_tensor(shallow_tree) or _is_composite_tensor(input_tree):
            if not ((_is_composite_tensor(input_tree) or _is_type_spec(input_tree)) and (_is_composite_tensor(shallow_tree) or _is_type_spec(shallow_tree))):
                raise TypeError(STRUCTURES_HAVE_MISMATCHING_TYPES.format(input_type=type(input_tree), shallow_type=type(shallow_tree)))
            type_spec_1 = (shallow_tree if _is_type_spec(shallow_tree) else shallow_tree._type_spec)._without_tensor_names()
            type_spec_2 = (input_tree if _is_type_spec(input_tree) else input_tree._type_spec)._without_tensor_names()
            if <MASK>:
                result = type_spec_1._get_structure() == type_spec_2._get_structure() or None
            else:
                result = type_spec_1.most_specific_common_supertype([type_spec_2])
            if result is None:
                raise ValueError('Incompatible CompositeTensor TypeSpecs: %s vs. %s' % (type_spec_1, type_spec_2))
        elif _is_type_spec(shallow_tree):
            if not _is_type_spec(input_tree):
                raise TypeError('If shallow structure is a TypeSpec, input must also be a TypeSpec.  Input has type: %s.' % type(input_tree))
        elif len(input_tree) != len(shallow_tree):
            raise ValueError(STRUCTURES_HAVE_MISMATCHING_LENGTHS.format(input_length=len(input_tree), shallow_length=len(shallow_tree)))
        elif len(input_tree) < len(shallow_tree):
            raise ValueError(INPUT_TREE_SMALLER_THAN_SHALLOW_TREE.format(input_size=len(input_tree), shallow_size=len(shallow_tree)))
        if isinstance(shallow_tree, _collections_abc.Mapping):
            absent_keys = set(shallow_tree) - set(input_tree)
            if absent_keys:
                raise ValueError(SHALLOW_TREE_HAS_INVALID_KEYS.format(sorted(absent_keys)))
        for (shallow_branch, input_branch) in zip(_tf_core_yield_value(shallow_tree), _tf_core_yield_value(input_tree)):
            _tf_core_assert_shallow_structure(shallow_branch, input_branch, check_types=check_types, expand_composites=expand_composites)

def __init__(self, config: _Config):
    self.default = config.default
    self.value_type = config.value_type if config.value_type is not None else type(self.default)
    self.justknob = config.justknob
    self.alias = config.alias
    if config.env_name_default is not None:
        for val in config.env_name_default:
            if (env_value := _read_env_variable(val)) is not None:
                self.env_value_default = env_value
                break
    if config.env_name_force is not None:
        for val in config.env_name_force:
            if (env_value := _read_env_variable(val)) is not None:
                self.env_value_force = env_value
                break
    if <MASK>:
        assert isinstance(self.default, bool), f'justknobs only support booleans, {self.default} is not a boolean'
    if self.value_type is not None and (config.env_name_default is not None or config.env_name_force is not None):
        assert self.value_type in (bool, str, Optional[bool], Optional[str]), f'envvar configs only support (optional) booleans or strings, {self.value_type} is neither'

def check_submodules() -> None:

    def check_for_files(folder: Path, files: list[str]) -> None:
        if not any(((folder / f).exists() for f in files)):
            report('Could not find any of {} in {}'.format(', '.join(files), folder))
            report("Did you run 'git submodule update --init --recursive'?")
            sys.exit(1)

    def not_exists_or_empty(folder: Path) -> bool:
        return not folder.exists() or (folder.is_dir() and next(folder.iterdir(), None) is None)
    if <MASK>:
        return
    folders = get_submodule_folders()
    if all((not_exists_or_empty(folder) for folder in folders)):
        try:
            report(' --- Trying to initialize submodules')
            start = time.time()
            subprocess.check_call(['git', 'submodule', 'update', '--init', '--recursive'], cwd=CWD)
            end = time.time()
            report(f' --- Submodule initialization took {end - start:.2f} sec')
        except Exception:
            report(' --- Submodule initialization failed')
            report('Please run:\n\tgit submodule update --init --recursive')
            sys.exit(1)
    for folder in folders:
        check_for_files(folder, ['CMakeLists.txt', 'Makefile', 'setup.py', 'LICENSE', 'LICENSE.md', 'LICENSE.txt'])
    check_for_files(THIRD_PARTY_DIR / 'fbgemm' / 'external' / 'asmjit', ['CMakeLists.txt'])

@simple_wraps(fn)
def _functionalized_f_helper(*args: list[FxValue]) -> tuple[tuple[list[FxValue], list[Tensor]], list[Optional[AOTOutput]]]:
    with maybe_enable_thunkify():
        disable_above = torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize))
        with disable_above:
            f_args = pytree.tree_map(to_fun, args)
            if <MASK>:

                def _post_forward(primals):
                    nonlocal primals_after_forward
                    primals_after_forward = pytree.tree_map(from_fun, primals)
                    nonlocal f_args_after_forward
                    f_args_after_forward = f_args[0]
                    nonlocal f_args_mutation_counters_after_forward
                    f_args_mutation_counters_after_forward = [MutationCounters(-1, -1, -1) if not inputs_mutated_in_graph[i] else _get_mutation_counters(f_arg) for (i, f_arg) in enumerate(f_args_after_forward)]
                joint_fn_handle.post_forward = _post_forward
            (f_outs, f_outs_descs) = call_and_expect_output_descs(fn, f_args)
        if trace_joint:
            assert isinstance(args, tuple) and len(args) == 2 and isinstance(args[0], (list, tuple))
            primals_before = args[0]
            primals_after = pytree.tree_map(from_fun, f_args[0])
            for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args[0], primals_before, primals_after, meta.input_info)):
                joint_mutates_data = has_data_mutation(f_inpt)
                joint_mutates_metadata = has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False)
                if not inpt_info.mutates_metadata:
                    assert not joint_mutates_metadata, 'Found a graph input that had its metadata mutated in the backward. This is not supported'
                if not inpt_info.mutation_inductor_storage_resize:
                    assert not was_inductor_storage_resized(f_inpt), 'Found a graph input that had storage resizing in the backward. This is not supported'
                if joint_mutates_data and (not inpt_info.mutates_data) and (not inpt_info.mutates_storage_metadata):
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
                    meta.indices_of_inputs_that_requires_grad_with_mutations_in_bw.append(idx)
            tangents_before = args[1]
            tangents_after = pytree.tree_map(from_fun, f_args[1])
            for (f_inpt, before, after) in zip(f_args[1], tangents_before, tangents_after):
                assert not has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False), 'Found an input to the backward that had metadata mutated during the backward pass. This is not supported'
                if has_data_mutation(f_inpt):
                    can_be_in_graph = _check_if_mutation_can_be_in_graph(keep_input_mutations=True, mutates_data=True, mutates_metadata=False, mutations_hidden_from_autograd=are_all_mutations_hidden_from_autograd(f_inpt), mutations_under_no_grad_or_inference_mode=are_all_mutations_under_no_grad_or_inference_mode(f_inpt), mutates_storage_metadata=False, mutation_inductor_storage_resize=was_inductor_storage_resized(f_inpt), requires_grad=f_inpt.requires_grad)
                    assert can_be_in_graph, 'a backward input that had data mutated in an autograd-aware way. This is not supported'
                    with torch.fx.traceback.preserve_node_meta():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
        if aot_config.keep_inference_input_mutations:
            mcs_applied: list[MutationCounters] = [MutationCounters(0, 0, 0)] * len(meta.input_info)
            if f_args_mutation_counters_after_forward is not None:
                primals_before = args[0]
                for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args_after_forward, primals_before, primals_after_forward, meta.input_info)):
                    if inpt_info.mutation_type != MutationType.MUTATED_IN_GRAPH:
                        continue
                    mcs_after_forward = f_args_mutation_counters_after_forward[idx]
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_forward(), _proxy_tensor_disable_update_tensor_tracker():
                        apply_in_graph_mutations(inpt_info, before, after, f_inpt, idx, mcs_after_forward, mcs_applied[idx])
                        mcs_applied[idx] = mcs_after_forward
            for (idx, (inpt_old, f_inpt)) in enumerate(zip(args, f_args) if not trace_joint else zip(args[0], f_args[0])):
                if not isinstance(f_inpt, torch.Tensor):
                    continue
                assert is_fun(f_inpt)
                inpt_new = from_fun(f_inpt)
                if meta.input_info[idx].mutation_type != MutationType.MUTATED_IN_GRAPH:
                    continue
                mcs: Optional[MutationCounters] = None
                if f_args_mutation_counters_after_forward is not None:
                    mcs = _get_mutation_counters(f_inpt)
                    if mcs == mcs_applied[idx]:
                        continue
                with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                    apply_in_graph_mutations(meta.input_info[idx], inpt_old, inpt_new, f_inpt, idx, mcs, mcs_applied[idx])
            (flat_outs, outs_spec) = pytree.tree_flatten(f_outs)
            flat_outs = [from_fun(o) for o in flat_outs]
            num_outs = len(meta.output_info)
            for i in range(num_outs):
                info = meta.output_info[i]
                if info.output_type != OutputType.is_input:
                    continue
                assert info.base_idx is not None
                if meta.input_info[info.base_idx].mutation_type == MutationType.MUTATED_IN_GRAPH:
                    fw_args = args[0] if trace_joint else args
                    flat_outs[i] = fw_args[info.base_idx]
            return (pytree.tree_unflatten(flat_outs, outs_spec), f_outs_descs)
        return (pytree.tree_map(from_fun, f_outs), f_outs_descs)

def disable_tfrt(unused_description: str) -> Callable[[Union[_TC, _F]], Union[_TC, _F, None]]:

    def disable_tfrt_impl(cls_or_func: Union[_TC, _F]) -> Union[_TC, _F, None]:
        """Execute the test only if tfrt is not enabled."""
        if tf_inspect.isclass(cls_or_func):
            if <MASK>:
                return None
            else:
                return cast(_TC, cls_or_func)
        else:
            func = cast(Callable[..., Any], cls_or_func)

            def decorated(*args, **kwargs):
                if tfrt_utils.enabled():
                    return
                else:
                    return func(*args, **kwargs)
            return tf_decorator.make_decorator(cls_or_func, decorated)
    return disable_tfrt_impl

@final
def _validate_names(self, name=None, names=None, deep: bool=False) -> list[Hashable]:
    """
        Handles the quirks of having a singular 'name' parameter for general
        Index and plural 'names' parameter for MultiIndex.
        """
    from copy import deepcopy
    if names is not None and name is not None:
        raise TypeError('Can only provide one of `names` and `name`')
    if names is None and name is None:
        new_names = deepcopy(self.names) if deep else self.names
    elif names is not None:
        if not is_list_like(names):
            raise TypeError('Must pass list-like as `names`.')
        new_names = names
    elif <MASK>:
        new_names = [name]
    else:
        new_names = name
    if len(new_names) != len(self.names):
        raise ValueError(f'Length of new names must be {len(self.names)}, got {len(new_names)}')
    validate_all_hashable(*new_names, error_name=f'{type(self).__name__}.name')
    return new_names

def __init__(self, input_shape, dilation_rate, padding, build_op, filter_shape=None, spatial_dims=None, data_format=None, num_batch_dims=1):
    """Helper class for _with_space_to_batch."""
    dilation_rate = ops.convert_to_tensor(dilation_rate, dtypes.int32, name='dilation_rate')
    if dilation_rate.shape.ndims not in (None, 1):
        raise ValueError(f'`dilation_rate.shape.rank` must be 1. Received: dilation_rate={dilation_rate} of rank {dilation_rate.shape.rank}')
    if not dilation_rate.shape.is_fully_defined():
        raise ValueError(f'`dilation_rate.shape` must be fully defined. Received: dilation_rate={dilation_rate} with shape {dilation_rate.shape}')
    num_spatial_dims = dilation_rate.shape.dims[0].value
    if data_format is not None and data_format.startswith('NC'):
        starting_spatial_dim = num_batch_dims + 1
    else:
        starting_spatial_dim = num_batch_dims
    if spatial_dims is None:
        spatial_dims = range(starting_spatial_dim, num_spatial_dims + starting_spatial_dim)
    orig_spatial_dims = list(spatial_dims)
    spatial_dims = sorted(set((int(x) for x in orig_spatial_dims)))
    if spatial_dims != orig_spatial_dims or any((x < 1 for x in spatial_dims)):
        raise ValueError(f'`spatial_dims` must be a monotonically increasing sequence of positive integers. Received: spatial_dims={orig_spatial_dims}')
    if data_format is not None and data_format.startswith('NC'):
        expected_input_rank = spatial_dims[-1]
    else:
        expected_input_rank = spatial_dims[-1] + 1
    try:
        input_shape.with_rank_at_least(expected_input_rank)
    except ValueError:
        raise ValueError(f'`input.shape.rank` must be at least {expected_input_rank}. Received: input.shape={input_shape} with rank {input_shape.rank}')
    const_rate = tensor_util.constant_value(dilation_rate)
    rate_or_const_rate = dilation_rate
    if const_rate is not None:
        rate_or_const_rate = const_rate
        if np.any(const_rate < 1):
            raise ValueError(f'`dilation_rate` must be positive. Received: dilation_rate={const_rate}')
        if np.all(const_rate == 1):
            self.call = build_op(num_spatial_dims, padding)
            return
    (padding, explicit_paddings) = convert_padding(padding)
    if padding == 'SAME':
        if filter_shape is None:
            raise ValueError(f"`filter_shape` must be specified for `padding='SAME'`. Received: filter_shape={filter_shape} and padding={padding}")
        filter_shape = ops.convert_to_tensor(filter_shape, name='filter_shape')
        const_filter_shape = tensor_util.constant_value(filter_shape)
        if <MASK>:
            filter_shape = const_filter_shape
            self.base_paddings = _with_space_to_batch_base_paddings(const_filter_shape, num_spatial_dims, rate_or_const_rate)
        else:
            self.num_spatial_dims = num_spatial_dims
            self.rate_or_const_rate = rate_or_const_rate
            self.base_paddings = None
    elif padding == 'VALID':
        self.base_paddings = np.zeros([num_spatial_dims, 2], np.int32)
    elif padding == 'EXPLICIT':
        base_paddings = np.array(explicit_paddings).reshape([num_spatial_dims + 2, 2])
        if data_format is not None and data_format.startswith('NC'):
            self.base_paddings = base_paddings[2:]
        else:
            self.base_paddings = base_paddings[1:-1]
    else:
        raise ValueError(f"`padding` must be one of 'SAME' or 'VALID'. Received: padding={padding}")
    self.input_shape = input_shape
    self.spatial_dims = spatial_dims
    self.dilation_rate = dilation_rate
    self.data_format = data_format
    self.op = build_op(num_spatial_dims, 'VALID')
    self.call = self._with_space_to_batch_call

def __init__(self):
    if <MASK>:
        return
    self.feature_supported = pfeatures = self.conf_features_partial()
    for feature_name in list(pfeatures.keys()):
        feature = pfeatures[feature_name]
        cfeature = self.conf_features[feature_name]
        feature.update({k: v for (k, v) in cfeature.items() if k not in feature})
        disabled = feature.get('disable')
        if disabled is not None:
            pfeatures.pop(feature_name)
            self.dist_log("feature '%s' is disabled," % feature_name, disabled, stderr=True)
            continue
        for option in ('implies', 'group', 'detect', 'headers', 'flags', 'extra_checks'):
            oval = feature.get(option)
            if isinstance(oval, str):
                feature[option] = oval.split()
    self.feature_min = set()
    min_f = self.conf_min_features.get(self.cc_march, '')
    for F in min_f.upper().split():
        if F in self.feature_supported:
            self.feature_min.add(F)
    self.feature_is_cached = True

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if self.fn is object and name == '__setattr__':
        assert len(args) == 3
        assert len(kwargs) == 0
        (obj, name_var, val) = args
        obj = obj.realize()
        if isinstance(obj, UserDefinedObjectVariable) and tx.output.side_effects.is_attribute_mutation(obj) and name_var.is_python_constant():
            return obj.method_setattr_standard(tx, name_var, val)
    if name == '__new__':
        if self.fn is object and len(args) == 1:
            assert len(kwargs) == 0
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is dict and len(args) == 1 and (not kwargs):
            dict_vt = ConstDictVariable({}, dict, mutation_type=ValueMutationNew())
            if isinstance(args[0], BuiltinVariable) and args[0].fn is dict:
                return dict_vt
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is tuple and len(args) == 2 and args[1].has_force_unpack_var_sequence(tx) and (not kwargs):
            if <MASK>:
                init_args = args[1].force_unpack_var_sequence(tx)
                return variables.TupleVariable(init_args, mutation_type=ValueMutationNew())
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is list:
            list_vt = ListVariable([], mutation_type=ValueMutationNew())
            if isinstance(args[0], BuiltinVariable) and args[0].fn is list:
                return list_vt
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
    if self.fn is float and len(args) == 1 and (name in ('fromhex', 'hex')):
        if isinstance(args[0], ConstantVariable):
            try:
                fn = getattr(float, name)
                res = fn(args[0].as_python_constant())
                return variables.ConstantVariable.create(res)
            except (OverflowError, ValueError) as e:
                raise_observed_exception(type(e), tx, args=list(map(ConstantVariable.create, e.args)))
    if self.fn is object and name == '__init__':
        return variables.ConstantVariable(None)
    if self.fn is dict and name == 'fromkeys':
        return BuiltinVariable.call_custom_dict_fromkeys(tx, dict, *args, **kwargs)
    if self.fn is dict:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in dict_methods:
            if isinstance(args[0], variables.UserDefinedDictVariable):
                return args[0]._dict_vt.call_method(tx, name, args[1:], kwargs)
            elif isinstance(args[0], variables.ConstDictVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is set:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in set_methods:
            if isinstance(args[0], variables.UserDefinedSetVariable):
                return args[0]._set_vt.call_method(tx, name, args[1:], kwargs)
            elif isinstance(args[0], variables.SetVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is frozenset:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in frozenset_methods:
            if isinstance(args[0], variables.FrozensetVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is str and len(args) >= 1:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in str_methods:
            if isinstance(args[0], ConstantVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is float and len(args) >= 1:
        if isinstance(args[0], ConstantVariable):
            return ConstantVariable.create(getattr(float, name)(args[0].as_python_constant()))
    return super().call_method(tx, name, args, kwargs)

def prefetch_one_level(instances, prefetcher, lookup, level):
    """
    Helper function for prefetch_related_objects().

    Run prefetches on all instances using the prefetcher object,
    assigning results to relevant caches in instance.

    Return the prefetched objects along with any additional prefetches that
    must be done due to prefetch_related lookups found from default managers.
    """
    (rel_qs, rel_obj_attr, instance_attr, single, cache_name, is_descriptor) = prefetcher.get_prefetch_querysets(instances, lookup.get_current_querysets(level))
    additional_lookups = [copy.copy(additional_lookup) for additional_lookup in getattr(rel_qs, '_prefetch_related_lookups', ())]
    if additional_lookups:
        rel_qs._prefetch_related_lookups = ()
    all_related_objects = list(rel_qs)
    rel_obj_cache = {}
    for rel_obj in all_related_objects:
        rel_attr_val = rel_obj_attr(rel_obj)
        rel_obj_cache.setdefault(rel_attr_val, []).append(rel_obj)
    (to_attr, as_attr) = lookup.get_current_to_attr(level)
    if as_attr and instances:
        model = instances[0].__class__
        try:
            model._meta.get_field(to_attr)
        except exceptions.FieldDoesNotExist:
            pass
        else:
            msg = 'to_attr={} conflicts with a field on the {} model.'
            raise ValueError(msg.format(to_attr, model.__name__))
    leaf = len(lookup.prefetch_through.split(LOOKUP_SEP)) - 1 == level
    for obj in instances:
        instance_attr_val = instance_attr(obj)
        vals = rel_obj_cache.get(instance_attr_val, [])
        if single:
            val = vals[0] if vals else None
            if as_attr:
                setattr(obj, to_attr, val)
            elif is_descriptor:
                setattr(obj, cache_name, val)
            else:
                obj._state.fields_cache[cache_name] = val
        elif as_attr:
            setattr(obj, to_attr, vals)
        else:
            manager = getattr(obj, to_attr)
            if <MASK>:
                qs = manager._apply_rel_filters(lookup.queryset)
            else:
                qs = manager.get_queryset()
            qs._result_cache = vals
            qs._prefetch_done = True
            obj._prefetched_objects_cache[cache_name] = qs
    return (all_related_objects, additional_lookups)

def _cast_to_stata_types(data: DataFrame) -> DataFrame:
    """
    Checks the dtypes of the columns of a pandas DataFrame for
    compatibility with the data types and ranges supported by Stata, and
    converts if necessary.

    Parameters
    ----------
    data : DataFrame
        The DataFrame to check and convert

    Notes
    -----
    Numeric columns in Stata must be one of int8, int16, int32, float32 or
    float64, with some additional value restrictions.  int8 and int16 columns
    are checked for violations of the value restrictions and upcast if needed.
    int64 data is not usable in Stata, and so it is downcast to int32 whenever
    the value are in the int32 range, and sidecast to float64 when larger than
    this range.  If the int64 values are outside of the range of those
    perfectly representable as float64 values, a warning is raised.

    bool columns are cast to int8.  uint columns are converted to int of the
    same size if there is no loss in precision, otherwise are upcast to a
    larger type.  uint64 is currently not supported since it is concerted to
    object in a DataFrame.
    """
    ws = ''
    conversion_data: tuple[tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type]] = ((np.bool_, np.int8, np.int8), (np.uint8, np.int8, np.int16), (np.uint16, np.int16, np.int32), (np.uint32, np.int32, np.int64), (np.uint64, np.int64, np.float64))
    float32_max = struct.unpack('<f', b'\xff\xff\xff~')[0]
    float64_max = struct.unpack('<d', b'\xff\xff\xff\xff\xff\xff\xdf\x7f')[0]
    for col in data:
        is_nullable_int = isinstance(data[col].dtype, ExtensionDtype) and data[col].dtype.kind in 'iub'
        orig_missing = data[col].isna()
        if is_nullable_int:
            fv = 0 if data[col].dtype.kind in 'iu' else False
            data[col] = data[col].fillna(fv).astype(data[col].dtype.numpy_dtype)
        elif isinstance(data[col].dtype, ExtensionDtype):
            if getattr(data[col].dtype, 'numpy_dtype', None) is not None:
                data[col] = data[col].astype(data[col].dtype.numpy_dtype)
            elif is_string_dtype(data[col].dtype):
                data[col] = data[col].astype('object')
                data.loc[data[col].isna(), col] = None
        dtype = data[col].dtype
        empty_df = data.shape[0] == 0
        for c_data in conversion_data:
            if dtype == c_data[0]:
                if empty_df or data[col].max() <= np.iinfo(c_data[1]).max:
                    dtype = c_data[1]
                else:
                    dtype = c_data[2]
                if c_data[2] == np.int64:
                    if data[col].max() >= 2 ** 53:
                        ws = precision_loss_doc.format('uint64', 'float64')
                data[col] = data[col].astype(dtype)
        if dtype == np.int8 and (not empty_df):
            if data[col].max() > 100 or data[col].min() < -127:
                data[col] = data[col].astype(np.int16)
        elif dtype == np.int16 and (not empty_df):
            if data[col].max() > 32740 or data[col].min() < -32767:
                data[col] = data[col].astype(np.int32)
        elif dtype == np.int64:
            if empty_df or (data[col].max() <= 2147483620 and data[col].min() >= -2147483647):
                data[col] = data[col].astype(np.int32)
            else:
                data[col] = data[col].astype(np.float64)
                if data[col].max() >= 2 ** 53 or data[col].min() <= -2 ** 53:
                    ws = precision_loss_doc.format('int64', 'float64')
        elif dtype in (np.float32, np.float64):
            if <MASK>:
                raise ValueError(f'Column {col} contains infinity or -infinitywhich is outside the range supported by Stata.')
            value = data[col].max()
            if dtype == np.float32 and value > float32_max:
                data[col] = data[col].astype(np.float64)
            elif dtype == np.float64:
                if value > float64_max:
                    raise ValueError(f'Column {col} has a maximum value ({value}) outside the range supported by Stata ({float64_max})')
        if is_nullable_int:
            if orig_missing.any():
                sentinel = StataMissingValue.BASE_MISSING_VALUES[data[col].dtype.name]
                data.loc[orig_missing, col] = sentinel
    if ws:
        warnings.warn(ws, PossiblePrecisionLoss, stacklevel=find_stack_level())
    return data

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    """Fit the baseline regressor.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            Training data.

        y : array-like of shape (n_samples,) or (n_samples, n_outputs)
            Target values.

        sample_weight : array-like of shape (n_samples,), default=None
            Sample weights.

        Returns
        -------
        self : object
            Fitted estimator.
        """
    validate_data(self, X, skip_check_array=True)
    y = check_array(y, ensure_2d=False, input_name='y')
    if len(y) == 0:
        raise ValueError('y must not be empty.')
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    self.n_outputs_ = y.shape[1]
    check_consistent_length(X, y, sample_weight)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if self.strategy == 'mean':
        self.constant_ = np.average(y, axis=0, weights=sample_weight)
    elif self.strategy == 'median':
        if sample_weight is None:
            self.constant_ = np.median(y, axis=0)
        else:
            self.constant_ = [_weighted_percentile(y[:, k], sample_weight, percentile_rank=50.0) for k in range(self.n_outputs_)]
    elif self.strategy == 'quantile':
        if self.quantile is None:
            raise ValueError("When using `strategy='quantile', you have to specify the desired quantile in the range [0, 1].")
        percentile_rank = self.quantile * 100.0
        if sample_weight is None:
            self.constant_ = np.percentile(y, axis=0, q=percentile_rank)
        else:
            self.constant_ = [_weighted_percentile(y[:, k], sample_weight, percentile_rank=percentile_rank) for k in range(self.n_outputs_)]
    elif <MASK>:
        if self.constant is None:
            raise TypeError('Constant target value has to be specified when the constant strategy is used.')
        self.constant_ = check_array(self.constant, accept_sparse=['csr', 'csc', 'coo'], ensure_2d=False, ensure_min_samples=0)
        if self.n_outputs_ != 1 and self.constant_.shape[0] != y.shape[1]:
            raise ValueError('Constant target value should have shape (%d, 1).' % y.shape[1])
    self.constant_ = np.reshape(self.constant_, (1, -1))
    return self

def _field_accessor(name: str, alias: str, docstring: str):

    def f(self) -> np.ndarray:
        values = self.asi8
        if alias == 'days':
            result = get_timedelta_days(values, reso=self._creso)
        else:
            result = get_timedelta_field(values, alias, reso=self._creso)
        if <MASK>:
            result = self._maybe_mask_results(result, fill_value=None, convert='float64')
        return result
    f.__name__ = name
    f.__doc__ = f'\n{docstring}\n'
    return property(f)

@classmethod
def _box_pa_array(cls, value, pa_type: pa.DataType | None=None, copy: bool=False) -> pa.Array | pa.ChunkedArray:
    """
        Box value into a pyarrow Array or ChunkedArray.

        Parameters
        ----------
        value : Sequence
        pa_type : pa.DataType | None

        Returns
        -------
        pa.Array or pa.ChunkedArray
        """
    value = extract_array(value, extract_numpy=True)
    if isinstance(value, cls):
        pa_array = value._pa_array
    elif isinstance(value, (pa.Array, pa.ChunkedArray)):
        pa_array = value
    elif isinstance(value, BaseMaskedArray):
        if copy:
            value = value.copy()
        pa_array = value.__arrow_array__()
    elif hasattr(value, '__arrow_array__'):
        if copy:
            value = value.copy()
        pa_array = value.__arrow_array__()
    else:
        if <MASK>:
            value = value.tolist()
        elif copy and is_array_like(value):
            value = value.copy()
        if pa_type is not None and pa.types.is_duration(pa_type) and (not isinstance(value, np.ndarray) or value.dtype.kind not in 'mi'):
            from pandas.core.tools.timedeltas import to_timedelta
            value = to_timedelta(value, unit=pa_type.unit).as_unit(pa_type.unit)
            value = value.to_numpy()
        if pa_type is not None and pa.types.is_timestamp(pa_type):
            from pandas.core.arrays.datetimes import DatetimeArray, tz_to_dtype
            pass_dtype = tz_to_dtype(tz=pa_type.tz, unit=pa_type.unit)
            value = extract_array(value, extract_numpy=True)
            if isinstance(value, DatetimeArray):
                dta = value
            else:
                dta = DatetimeArray._from_sequence(value, copy=copy, dtype=pass_dtype)
            dta_mask = dta.isna()
            value_i8 = cast('npt.NDArray', dta.view('i8'))
            if not value_i8.flags['WRITEABLE']:
                value_i8 = value_i8.copy()
                dta = DatetimeArray._from_sequence(value_i8, dtype=dta.dtype)
            value_i8[dta_mask] = 0
            pa_array = pa.array(dta._ndarray, type=pa_type, mask=dta_mask)
            return pa_array
        mask = None
        if is_nan_na():
            try:
                arr_value = np.asarray(value)
                if arr_value.ndim > 1:
                    mask = np.zeros(len(value), dtype=np.bool_)
                else:
                    mask = isna(arr_value)
            except ValueError:
                arr_value = construct_1d_object_array_from_listlike(value)
                mask = isna(arr_value)
        elif getattr(value, 'dtype', None) is None or value.dtype.kind not in 'iumMf':
            arr_value = np.asarray(value, dtype=object)
            mask = is_pdna_or_none(arr_value)
        try:
            pa_array = pa.array(value, type=pa_type, mask=mask)
        except (pa.ArrowInvalid, pa.ArrowTypeError):
            pa_array = pa.array(value, mask=mask)
        if pa_type is None and pa.types.is_duration(pa_array.type):
            from pandas.core.tools.timedeltas import to_timedelta
            value = to_timedelta(value)
            value = value.to_numpy()
            pa_array = pa.array(value, type=pa_type)
        if pa.types.is_duration(pa_array.type) and pa_array.null_count > 0:
            arr = cls(pa_array)
            arr = arr.fillna(arr.dtype.na_value)
            pa_array = arr._pa_array
    if pa_type is not None and pa_array.type != pa_type:
        if pa.types.is_dictionary(pa_type):
            pa_array = pa_array.dictionary_encode()
            if pa_array.type != pa_type:
                pa_array = pa_array.cast(pa_type)
        else:
            try:
                pa_array = pa_array.cast(pa_type)
            except (pa.ArrowNotImplementedError, pa.ArrowTypeError):
                if pa.types.is_string(pa_array.type) or pa.types.is_large_string(pa_array.type):
                    dtype = ArrowDtype(pa_type)
                    return cls._from_sequence_of_strings(value, dtype=dtype)._pa_array
                else:
                    raise
    return pa_array

def retry_shell(command, cwd=None, env=None, stdout=None, stderr=None, timeout=None, retries=1, was_rerun=False) -> tuple[int, bool]:
    assert retries >= 0, f'Expecting non negative number for number of retries, got {retries}'
    try:
        exit_code = shell(command, cwd=cwd, env=env, stdout=stdout, stderr=stderr, timeout=timeout)
        if exit_code == 0 or retries == 0:
            return (exit_code, was_rerun)
        print(f'Got exit code {exit_code}, retrying (retries left={retries})', file=stdout, flush=True)
    except subprocess.TimeoutExpired:
        if <MASK>:
            print(f'Command took >{timeout // 60}min, returning 124', file=stdout, flush=True)
            return (124, was_rerun)
        print(f'Command took >{timeout // 60}min, retrying (retries left={retries})', file=stdout, flush=True)
    return retry_shell(command, cwd=cwd, env=env, stdout=stdout, stderr=stderr, timeout=timeout, retries=retries - 1, was_rerun=True)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces['error']:
        return {'version': 'unknown', 'full-revisionid': pieces.get('long'), 'dirty': None, 'error': pieces['error'], 'date': None}
    if not style or style == 'default':
        style = 'pep440'
    if style == 'pep440':
        rendered = render_pep440(pieces)
    elif <MASK>:
        rendered = render_pep440_branch(pieces)
    elif style == 'pep440-pre':
        rendered = render_pep440_pre(pieces)
    elif style == 'pep440-post':
        rendered = render_pep440_post(pieces)
    elif style == 'pep440-post-branch':
        rendered = render_pep440_post_branch(pieces)
    elif style == 'pep440-old':
        rendered = render_pep440_old(pieces)
    elif style == 'git-describe':
        rendered = render_git_describe(pieces)
    elif style == 'git-describe-long':
        rendered = render_git_describe_long(pieces)
    else:
        raise ValueError(f"unknown style '{style}'")
    return {'version': rendered, 'full-revisionid': pieces['long'], 'dirty': pieces['dirty'], 'error': None, 'date': pieces.get('date')}

def _warn_if_deprecated(key: str) -> bool:
    """
    Checks if `key` is a deprecated option and if so, prints a warning.

    Returns
    -------
    bool - True if `key` is deprecated, False otherwise.
    """
    d = _get_deprecated_option(key)
    if d:
        if d.msg:
            warnings.warn(d.msg, d.category, stacklevel=find_stack_level())
        else:
            msg = f"'{key}' is deprecated"
            if <MASK>:
                msg += f' and will be removed in {d.removal_ver}'
            if d.rkey:
                msg += f", please use '{d.rkey}' instead."
            else:
                msg += ', please refrain from using it.'
            warnings.warn(msg, d.category, stacklevel=find_stack_level())
        return True
    return False

def ban_recomputation_if_allowed(node):
    if <MASK>:
        return False
    if node in dont_ban:
        is_collective = isinstance(node.target, torch._ops.OpOverload) and node.target.namespace == '_c10d_functional'
        if config.unsafe_allow_optimization_of_collectives or not is_collective:
            return False
    if must_recompute(node):
        return False
    if 'val' in node.meta and isinstance(node.meta['val'], torch.SymFloat):
        return False
    banned_nodes.add(node)
    nx_graph.add_edge('source', node.name + '_in', capacity=math.inf)
    return True

def starter_nodes(self) -> tuple[NodeSet, NodeSet]:
    """
        Finds nodes that consume module inputs or get_attr nodes.
        """
    starter_cpu_nodes: NodeSet = set()
    starter_acc_nodes: NodeSet = set()
    for node in self.module.graph.nodes:
        if node.op == 'call_function' and len(node.all_input_nodes) == 0:
            if node in self.acc_nodes:
                starter_acc_nodes.add(node)
            else:
                starter_cpu_nodes.add(node)
        if node.op not in {'placeholder', 'get_attr'}:
            continue
        for user in node.users:
            if <MASK>:
                starter_acc_nodes.add(user)
            else:
                starter_cpu_nodes.add(user)
    return (starter_cpu_nodes, starter_acc_nodes)

