def is_linear_add_bias(match):
    add_node = match.output_node()
    linear_node = add_node.args[0]
    device_type = add_node.meta.get('val').device.type
    mkldnn_device_op = _get_mkldnn_device_op(device_type)
    transpose_weight_node = mkldnn_device_op.get_linear_transpose_weight(linear_node.args[1])
    weight_meta = transpose_weight_node.args[0].meta.get('val')
    bias_node = add_node.args[1]
    if <MASK>:
        return False
    bias_meta = add_node.args[1].meta.get('val')
    if weight_meta is None or bias_meta is None:
        return False
    if bias_meta.dtype != weight_meta.dtype:
        return False
    return linear_node.args[2] is None and bias_meta.dim() == 1 and (bias_meta.size(0) == weight_meta.size(1))

def __repr__(self):
    if <MASK>:
        repr_attr = self._setupfunc
    else:
        repr_attr = self._wrapped
    return '<%s: %r>' % (type(self).__name__, repr_attr)

@property
def _component_specs(self):
    if self._ragged_rank <= 0:
        if <MASK>:
            return [self._flat_values_spec]
        else:
            return [tensor_lib.TensorSpec(self._shape, self._dtype)]
    flat_values_spec = self._flat_values_spec
    if flat_values_spec is None:
        flat_values_shape = tensor_shape.TensorShape([None]).concatenate(self._shape[self._ragged_rank + 1:])
        flat_values_spec = tensor_lib.TensorSpec(flat_values_shape, self._dtype)
    outer_dim = tensor_shape.dimension_at_index(self._shape, 0)
    outer_splits_shape = [None if outer_dim is None else outer_dim + 1]
    inner_splits_spec = tensor_lib.TensorSpec([None], self._row_splits_dtype)
    specs = [flat_values_spec, tensor_lib.TensorSpec(outer_splits_shape, self._row_splits_dtype)] + [inner_splits_spec for _ in range(self._ragged_rank - 1)]
    return specs

def _check_global_requires_backward_grad_sync(self, is_joined_rank):
    if not is_joined_rank and self.require_backward_grad_sync:
        requires_sync_tensor = torch.ones(1, device=self.device)
    else:
        requires_sync_tensor = torch.zeros(1, device=self.device)
    work = dist.all_reduce(requires_sync_tensor, group=self.process_group, async_op=True)
    if <MASK>:
        work.wait()
        should_sync_backwards = requires_sync_tensor.item() != 0
        return should_sync_backwards
    else:
        return None

def _parse_target_tokens(self, tokens):
    assert isinstance(tokens, str)
    final_targets = []
    extra_flags = []
    has_baseline = False
    skipped = set()
    policies = set()
    multi_target = None
    tokens = list(filter(None, re.split(self._parse_regex_target, tokens)))
    if not tokens:
        self.dist_fatal('expected one token at least')
    for tok in tokens:
        TOK = tok.upper()
        ch = tok[0]
        if ch in ('+', '-'):
            self.dist_fatal("+/- are 'not' allowed from target's groups or @targets, only from cpu_baseline and cpu_dispatch parms")
        elif ch == '$':
            if multi_target is not None:
                self.dist_fatal("policies aren't allowed inside multi-target '()', only CPU features")
            policies.add(self._parse_token_policy(TOK))
        elif ch == '#':
            if multi_target is not None:
                self.dist_fatal("target groups aren't allowed inside multi-target '()', only CPU features")
            (has_baseline, final_targets, extra_flags) = self._parse_token_group(TOK, has_baseline, final_targets, extra_flags)
        elif ch == '(':
            if multi_target is not None:
                self.dist_fatal("unclosed multi-target, missing ')'")
            multi_target = set()
        elif ch == ')':
            if multi_target is None:
                self.dist_fatal("multi-target opener '(' wasn't found")
            targets = self._parse_multi_target(multi_target)
            if targets is None:
                skipped.add(tuple(multi_target))
            else:
                if len(targets) == 1:
                    targets = targets[0]
                if targets and targets not in final_targets:
                    final_targets.append(targets)
            multi_target = None
        else:
            if TOK == 'BASELINE':
                if multi_target is not None:
                    self.dist_fatal("baseline isn't allowed inside multi-target '()'")
                has_baseline = True
                continue
            if multi_target is not None:
                multi_target.add(TOK)
                continue
            if not self.feature_is_exist(TOK):
                self.dist_fatal("invalid target name '%s'" % TOK)
            is_enabled = TOK in self.parse_baseline_names or TOK in self.parse_dispatch_names
            if is_enabled:
                if TOK not in final_targets:
                    final_targets.append(TOK)
                continue
            skipped.add(TOK)
    if multi_target is not None:
        self.dist_fatal("unclosed multi-target, missing ')'")
    if skipped:
        self.dist_log('skip targets', skipped, 'not part of baseline or dispatch-able features')
    final_targets = self.feature_untied(final_targets)
    for p in list(policies):
        (_, _, deps) = self._parse_policies[p]
        for d in deps:
            if <MASK>:
                continue
            self.dist_log("policy '%s' force enables '%s'" % (p, d))
            policies.add(d)
    for (p, (have, nhave, _)) in self._parse_policies.items():
        func = None
        if p in policies:
            func = have
            self.dist_log("policy '%s' is ON" % p)
        else:
            func = nhave
        if not func:
            continue
        (has_baseline, final_targets, extra_flags) = func(has_baseline, final_targets, extra_flags)
    return (has_baseline, final_targets, extra_flags)

def _get_logical_cpus_to_bind_to(*, gpu_index: int, numa_options: NumaOptions) -> set[int]:
    """
    Args:
        gpu_index: The index of the GPU that will be used by the subprocess.
            Example: 0
        numa_options: See NumaOptions for details.

    Returns:
        Set of logical CPU indices to bind to.
    """
    if numa_options.affinity_mode == AffinityMode.NODE:
        logical_cpus = _node_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    elif <MASK>:
        logical_cpus = _socket_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    elif numa_options.affinity_mode == AffinityMode.EXCLUSIVE:
        logical_cpus = _exclusive_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    elif numa_options.affinity_mode == AffinityMode.CORE_COMPLEX:
        logical_cpus = _core_complex_get_logical_cpus_to_bind_to(gpu_index=gpu_index)
    else:
        raise ValueError(f'Affinity mode {numa_options.affinity_mode} not supported.')
    return logical_cpus

def fallback_node_due_to_unsupported_type(node: torch.fx.Node, allow_cpu_inputs=True):
    if node.target is aten.view_as_complex.default:
        return False
    if node.op == 'placeholder':
        return False
    if node.target is aten.lift_fresh_copy.default:
        return False

    def check_skip_condition(inp_out_node, is_output):
        if not isinstance(inp_out_node, torch.fx.Node):
            return False
        if 'val' not in inp_out_node.meta:
            return False
        for meta in pytree.tree_leaves(inp_out_node.meta['val']):
            if not isinstance(meta, torch._subclasses.FakeTensor):
                continue
            if is_output:
                if unsupported_output_tensor(meta, node):
                    return True
            elif <MASK>:
                return True
        return False
    for arg in pytree.arg_tree_leaves(*node.args, **node.kwargs):
        if check_skip_condition(arg, is_output=False):
            return True
    return check_skip_condition(node, is_output=True)

def _reduction_nocache(self, dtype: torch.dtype, src_dtype: torch.dtype, reduction_type: ReductionType, value: Union[CSEVariable, tuple[CSEVariable, ...]]) -> Union[CSEVariable, tuple[CSEVariable, ...]]:
    """Codegen a reduction operation.
        Only sum and prod operations are somewhat reasonable optimized"""
    assert self.inside_reduction
    assert not self._load_mask

    def _unwrap_helper(res3: CSEVariable) -> tuple[CSEVariable, ...]:
        return OpsWrapper._unwrap([CSEVariable(f'{res3}.{t}', res3.bounds, res3.dtype) for t in 'xyz'])
    reduction_idx = ''
    acc_buf_size = 1
    for rd in self.range_trees:
        if not rd.is_reduction:
            continue
        if reduction_idx:
            reduction_idx += ' + '
        reduction_idx += f'{rd.name} * {acc_buf_size}'
        if <MASK>:
            acc_buf_size *= rd.numel
        else:
            acc_buf_size *= sympy.Symbol(f'{rd.prefix}numel', integer=True, positive=True)
    acc_buf_size = sympy.Min(acc_buf_size, self.max_threadgroup_size)
    acc_buf_size_str = self.sexpr(acc_buf_size)
    shmem_buf_size = ceildiv(acc_buf_size, self.simd_group_size) if isinstance(acc_buf_size, sympy.Integer) else self.simd_group_size
    if reduction_type == 'any':
        acc = self._new_idxvar(dtype)
        self.indexing_code.writeline(f'{acc} = false;')
        self.indexing_code.writeline('threadgroup_barrier(metal::mem_flags::mem_threadgroup);')
        self.compute.splice(f'\n                if ({value}) {{\n                    {acc} = true;\n                }}\n            ')
        self.stores.writeline('threadgroup_barrier(metal::mem_flags::mem_threadgroup);')
        return acc
    self.headers.add('reduction_utils')
    if reduction_type in ['prod', 'sum']:
        acc_dtype = DTYPE_TO_COMPUTATION_DTYPE[src_dtype]
        acc_buf = self._new_idxvar(acc_dtype, shmem_buf_size)
        if not self.multistage_reduction_entry:
            val = value
        else:
            (default_val, reduction_op) = (0, '+') if reduction_type == 'sum' else (1, '*')
            val = self._new_idxvar(acc_dtype, default_value=default_val, is_threadgroup=False)
            self.compute.splice(f'{val} {reduction_op}= {value};')
        return self.cse.generate(self.stores, f'c10::metal::threadgroup_{reduction_type}({acc_buf}, {val}, {reduction_idx}, {acc_buf_size_str})', dtype=DTYPE_TO_COMPUTATION_DTYPE[dtype])
    if reduction_type in ['max', 'min']:
        acc_buf = self._new_idxvar(src_dtype, shmem_buf_size)
        src_metal_type = DTYPE_TO_METAL[src_dtype]
        cast_value = f'static_cast<{src_metal_type}>({value})'
        if not self.multistage_reduction_entry:
            val = cast_value
        else:
            lim_fn = 'lowest' if reduction_type.endswith('max') else 'max'
            limit_val = f'::metal::numeric_limits<{src_metal_type}>::{lim_fn}()'
            val = self._new_idxvar(src_dtype, default_value=limit_val, is_threadgroup=False)
            self.compute.splice(f'{val} = ::c10::metal::{reduction_type}({val}, {cast_value});')
        return self.cse.generate(self.stores, f'c10::metal::threadgroup_{reduction_type}({acc_buf}, {val}, {reduction_idx}, {acc_buf_size_str})', dtype=DTYPE_TO_COMPUTATION_DTYPE[dtype])
    if reduction_type in ['argmin', 'argmax']:
        data_acc_buf = self._new_idxvar(src_dtype, shmem_buf_size)
        idx_acc_buf = self._new_idxvar(dtype, shmem_buf_size)
        src_metal_type = DTYPE_TO_METAL[src_dtype]
        cast_value = f'static_cast<{src_metal_type}>({value})'
        if not self.multistage_reduction_entry:
            val = cast_value
            idx_val = f'static_cast<{DTYPE_TO_METAL[dtype]}>({reduction_idx})'
        else:
            lim_fn = 'lowest' if reduction_type.endswith('max') else 'max'
            limit_val = f'::metal::numeric_limits<{src_metal_type}>::{lim_fn}()'
            val = self._new_idxvar(src_dtype, default_value=limit_val, is_threadgroup=False)
            idx_val = self._new_idxvar(dtype, default_value=0, is_threadgroup=False)
            idx_var = next((t for t in self.range_tree_nodes.values() if t.is_reduction))
            cmp_op = '>' if reduction_type == 'argmax' else '<'
            nan_suffix = f' || ::metal::isnan({value}) ' if src_dtype.is_floating_point else ''
            self.compute.splice(f'\n                if ({value} {cmp_op} {val}{nan_suffix}) {{\n                    {val} = {value};\n                    {idx_val} = {idx_var.name};\n                }}\n                ')
        return self.cse.generate(self.stores, f'c10::metal::threadgroup_{reduction_type}({data_acc_buf}, {idx_acc_buf}, {val}, {idx_val}, {reduction_idx}, {acc_buf_size_str})', dtype=dtype)
    if reduction_type == 'welford_reduce':
        if not self.multistage_reduction_entry:
            acc_buf = self._new_idxvar(src_dtype, acc_buf_size)
            self.compute.splice(f'{acc_buf}[{reduction_idx}] = {value};')
            wf_res = self.cse.generate(self.compute, f'c10::metal::threadgroup_{reduction_type}({acc_buf}, {acc_buf_size_str})', dtype=torch.float32)
            return _unwrap_helper(wf_res)
        acc_buf = self._new_idxvar('float3', acc_buf_size)
        acc_thread_var = f'{acc_buf}[{reduction_idx}]'
        self.indexing_code.splice(f'{acc_thread_var} = 0.0;')
        self.compute.writeline(f'{acc_thread_var} = ::c10::metal::welford_combine({acc_thread_var}, float3({value}, 0.0, 1.0));')
        wf_res = self.cse.generate(self.stores, f'c10::metal::threadgroup_welford_combine({acc_buf}, {acc_buf_size})', dtype=torch.float32)
        return _unwrap_helper(wf_res)
    if reduction_type == 'welford_combine':
        assert isinstance(value, tuple), 'Input to welford combine must be tuple'
        acc_buf = self._new_idxvar('float3', acc_buf_size)
        acc_thread_var = f'{acc_buf}[{reduction_idx}]'
        inp_value = f'float3({value[0]}, {value[1]}, {value[2]})'
        self.indexing_code.splice(f'{acc_thread_var} = 0.0;')
        if self.multistage_reduction_entry:
            self.indexing_code.splice(f'{acc_thread_var} = 0.0;')
            self.compute.writeline(f'{acc_thread_var} = ::c10::metal::welford_combine({acc_thread_var}, {inp_value});')
        else:
            self.compute.writeline(f'{acc_thread_var} = {inp_value};')
        wf_res = self.cse.generate(self.stores if self.multistage_reduction_entry else self.compute, f'c10::metal::threadgroup_{reduction_type}({acc_buf}, {acc_buf_size_str})', dtype=torch.float32)
        return _unwrap_helper(wf_res)
    raise NotImplementedError(reduction_type)

def _resolved_getattr_and_source(self, tx: 'InstructionTranslator', name):
    assert self.objvar, '1-arg super not implemented'
    search_type = self.typevar.as_python_constant()
    type_to_use = self.objvar.python_type()
    type_to_use_source = TypeSource(self.objvar.source) if self.objvar.source else None
    if issubclass(type_to_use, type):
        type_to_use = self.objvar.value
        type_to_use_source = self.objvar.source
    source = None
    search_mro = type_to_use.__mro__
    try:
        start_index = search_mro.index(search_type) + 1
    except ValueError:
        return (getattr(super(search_type, type_to_use), name), None)
    for index in range(start_index, len(search_mro)):
        if (resolved_getattr := search_mro[index].__dict__.get(name, NO_SUCH_SUBOBJ)):
            if <MASK>:
                if type_to_use_source:
                    source = AttrSource(GetItemSource(TypeMROSource(type_to_use_source), index), name)
                return (resolved_getattr, source)
    unimplemented_v2(gb_type='Unable to resolve super getattr', context='', explanation=f'Dynamo failed to trace attribute `{name}` accessed via `super()` (for type `{self.typevar}` and object `{self.objvar}`) because the resolved attribute type is not supported.', hints=['Ensure the attribute exists in the parent class.', 'Check the arguments passed to `super()`.'])

def codegen_input_symbol_assignment(self, name: str, value: ir.TensorBox, bound_vars: OrderedSet[sympy.Symbol]):
    code = self.prefix

    @functools.cache
    def sizeof(name):
        code.writeline(f'{name}_size = {name}.size()')
        return f'{name}_size'

    @functools.cache
    def strideof(name):
        code.writeline(f'{name}_stride = {name}.stride()')
        return f'{name}_stride'
    if isinstance(value, sympy.Expr):
        if <MASK>:
            return
        code.writeline(f'{value} = {name}')
        bound_vars.add(value)
    elif isinstance(value, ir.TensorBox):
        for (dim, size) in enumerate(value.get_size()):
            if isinstance(size, sympy.Symbol) and size not in bound_vars:
                code.writeline(f'{size} = {sizeof(name)}[{dim}]')
                bound_vars.add(size)
        for (dim, stride) in enumerate(value.get_stride()):
            if isinstance(stride, sympy.Symbol) and stride not in bound_vars:
                code.writeline(f'{stride} = {strideof(name)}[{dim}]')
                bound_vars.add(stride)
    elif isinstance(value, ir.TorchBindObject):
        return
    elif isinstance(value, ir.GeneratorState):
        return
    elif torch._inductor.config.graph_partition:
        pass
    else:
        raise AssertionError(f'Unknown value type: {type(value)}')

def swap_tensor_content_in_graph_function(graph_def, from_endiness, to_endiness):
    """Fix endiness of tensor contents.

  Args:
    graph_def: Target graph_def to change endiness.
    from_endiness: The original endianness format. "big" or "little"
    to_endiness: The target endianness format. "big" or "little"
  """
    if isinstance(graph_def, meta_graph_pb2.MetaGraphDef):
        functions = graph_def.graph_def.library.function
    elif <MASK>:
        functions = graph_def.library.function
    else:
        return
    for function in functions:
        node_def = function.node_def
        for node in node_def:
            if node.op == 'Const':
                tensor = node.attr['value'].tensor
                byte_swap_tensor_content(tensor, from_endiness, to_endiness)

def _sample_from_datasets(datasets, weights=None, seed=None, stop_on_empty_dataset=False, rerandomize_each_iteration=None):
    """See `Dataset.sample_from_datasets()` for details."""

    def _skip_datasets_with_zero_weight(datasets, weights):
        datasets_and_weights = [(dataset, weight) for (dataset, weight) in zip(datasets, weights) if weight > 0]
        return zip(*datasets_and_weights) if datasets_and_weights else ([datasets[0].take(0)], [1.0])
    if not datasets:
        raise ValueError('Invalid `datasets`. `datasets` should not be empty.')
    if not isinstance(weights, data_types.DatasetV2):
        if weights is None:
            logits = [[1.0] * len(datasets)]
        else:
            if isinstance(weights, tensor.Tensor):
                if not weights.shape.is_compatible_with([len(datasets)]):
                    raise ValueError(f'Invalid `weights`. The shape of `weights` should be compatible with `[len(datasets)]` but is {weights.shape}.')
            elif len(datasets) != len(weights):
                raise ValueError(f'Invalid `weights`. `weights` should have the same length as `datasets` but got `len(weights)={len(weights)}` vs. `len(datasets)={len(datasets)}`.')
            if <MASK>:
                (datasets, weights) = _skip_datasets_with_zero_weight(datasets, weights)
            weights = ops.convert_to_tensor(weights, name='weights')
            if weights.dtype not in (dtypes.float32, dtypes.float64):
                raise TypeError(f'Invalid `weights`. `weights` type must be either `tf.float32` or `tf.float64` but is {weights.dtype}.')
            logits = array_ops.expand_dims(math_ops.log(weights, name='logits'), 0)
        if len(datasets) == 1:
            return datasets[0]

        def select_dataset_constant_logits(seed):
            return array_ops.squeeze(gen_stateless_random_ops.stateless_multinomial(logits, 1, seed=seed), axis=[0, 1])
        selector_input = map_op._MapDataset(dataset_ops.Dataset.random(seed=seed, rerandomize_each_iteration=rerandomize_each_iteration).batch(2), select_dataset_constant_logits, use_inter_op_parallelism=False)
    else:
        logits_ds = weights.map(lambda *p: math_ops.log(p, name='logits'))

        def select_dataset_varying_logits(logits, seed):
            return array_ops.squeeze(gen_stateless_random_ops.stateless_multinomial(logits, 1, seed=seed), axis=[0, 1])
        logits_and_seeds = dataset_ops.Dataset.zip((logits_ds, dataset_ops.Dataset.random(seed=seed, rerandomize_each_iteration=rerandomize_each_iteration).batch(2)))
        selector_input = map_op._MapDataset(logits_and_seeds, select_dataset_varying_logits, use_inter_op_parallelism=False)
    return directed_interleave_op._directed_interleave(selector_input, datasets, stop_on_empty_dataset)

def _select_sdp_backend(query, key, value, attn_mask, dropout, is_causal, enable_gqa):
    if not flash_sdp_enabled() and (not mem_efficient_sdp_enabled()) and (not math_sdp_enabled()) and (not cudnn_sdp_enabled()):
        return SDPBackend.ERROR
    ordering = (SDPBackend.FLASH_ATTENTION, SDPBackend.EFFICIENT_ATTENTION, SDPBackend.MATH, SDPBackend.CUDNN_ATTENTION)
    params = SDPAParams(query, key, value, attn_mask, dropout, is_causal, enable_gqa)
    for backend in ordering:
        if <MASK>:
            if can_use_cudnn_attention(params):
                return SDPBackend.CUDNN_ATTENTION
        if backend == SDPBackend.FLASH_ATTENTION:
            if can_use_flash_attention(params) and _can_use_flash_sdpa_jagged(params):
                return SDPBackend.FLASH_ATTENTION
        if backend == SDPBackend.EFFICIENT_ATTENTION:
            if can_use_efficient_attention(params) and _can_use_efficient_sdpa_jagged(params):
                return SDPBackend.EFFICIENT_ATTENTION
        if backend == SDPBackend.MATH:
            if math_sdp_enabled() and _can_use_math_sdpa_jagged(params):
                return SDPBackend.MATH
    log.warning('Memory efficient kernel not used because:')
    can_use_efficient_attention(params, debug=True)
    _can_use_efficient_sdpa_jagged(params, debug=True)
    log.warning('Flash attention kernel not used because:')
    can_use_flash_attention(params, debug=True)
    _can_use_flash_sdpa_jagged(params, debug=True)
    log.warning('Math attention kernel not used because:')
    _can_use_math_sdpa_jagged(params, debug=True)
    log.warning('cuDNN attention kernel not used because:')
    can_use_cudnn_attention(params, debug=True)
    return SDPBackend.ERROR

def extra_repr(self):
    s = '{in_channels}, {out_channels}, kernel_size={kernel_size}, stride={stride}, scale={scale}, zero_point={zero_point}'
    if <MASK>:
        s += ', padding={padding}'
    if self.dilation != (1,) * len(self.dilation):
        s += ', dilation={dilation}'
    if self.output_padding != (0,) * len(self.output_padding):
        s += ', output_padding={output_padding}'
    if self.groups != 1:
        s += ', groups={groups}'
    if self.bias() is None:
        s += ', bias=False'
    return s.format(**self.__dict__)

def check_function_argument_count(func, input_arity, infeed_queue):
    """Validate the number of input arguments to an XLA function.

  Args:
    func: the Python function that will be called to generate the body of an XLA
      computation graph.
    input_arity: the number of explicit arguments supplied by the caller.
    infeed_queue: if not None, the infeed queue that will supply
      additional arguments to the function.

  Returns:
    None if function can be called with the supplied number of
      arguments, or an error string if it cannot.
  """

    def format_error(complaint, quantity):
        return '%s %d argument%s' % (complaint, quantity, '' if quantity == 1 else 's')
    num_args_supplied = input_arity
    if <MASK>:
        num_args_supplied += infeed_queue.number_of_tuple_elements
    arg_spec = tf_inspect.getargspec(func)
    num_func_args = len(arg_spec.args)
    if arg_spec.defaults is None:
        num_func_defaults = 0
    else:
        num_func_defaults = len(arg_spec.defaults)
    min_func_args = num_func_args - num_func_defaults
    if num_args_supplied < min_func_args:
        if num_func_defaults == 0 and arg_spec.varargs is None:
            return format_error('exactly', num_func_args)
        else:
            return format_error('at least', min_func_args)
    if arg_spec.varargs is None and num_args_supplied > num_func_args:
        if num_func_defaults == 0:
            return format_error('exactly', num_func_args)
        else:
            return format_error('at most', num_func_args)
    return None

def MAKE_FUNCTION(self, inst: Instruction) -> None:
    flags = inst.arg
    if sys.version_info < (3, 11):
        fn_name = self.pop()
    code = self.pop()
    if sys.version_info >= (3, 11):
        assert hasattr(code.value, 'co_qualname')
        fn_name = ConstantVariable.create(value=code.value.co_qualname)
    defaults = None
    closure = None
    annotations = None
    kwdefaults = None
    if sys.version_info < (3, 13):
        if <MASK>:
            if flags & 8:
                closure = self.pop()
            if flags & 4:
                annotations = self.pop()
            if flags & 2:
                kwdefaults = self.pop()
            if flags & 1:
                defaults = self.pop()
    self.push(NestedUserFunctionVariable(fn_name, code, self.f_globals, defaults, kwdefaults, annotations, closure))

def _rnn_helper(input, hidden, params, has_biases, num_layers, dropout, train, bidirectional, batch_first, layer_fn):
    input = input.transpose(0, 1) if batch_first else input
    final_hiddens = []
    for i in range(num_layers):
        (cur_params, cur_hidden, bidir_params, bidir_hidden) = params_hiddens(params, hidden, i, bidirectional)
        dropout = dropout if train and num_layers < i - 1 else 0.0
        (fwd_inp, fwd_hidden) = layer_fn(input, cur_hidden, cur_params, has_biases)
        final_hiddens.append(fwd_hidden)
        if <MASK>:
            (bwd_inp, bwd_hidden) = layer_fn(input, bidir_hidden, bidir_params, has_biases, reverse=True)
            final_hiddens.append(bwd_hidden)
        if bidirectional:
            input = torch.cat([fwd_inp, bwd_inp], fwd_inp.dim() - 1)
        else:
            input = fwd_inp
        if dropout != 0 and train and (i < num_layers - 1):
            input = torch.dropout(input, dropout, train=True)
    input = input.transpose(0, 1) if batch_first else input
    return (input, final_hiddens)

def _convert_tf1_model(flags):
    """Calls function to convert the TensorFlow 1.X model into a TFLite model.

  Args:
    flags: argparse.Namespace object.

  Raises:
    ValueError: Invalid flags.
  """
    if flags.custom_opdefs:
        register_custom_opdefs(_parse_array(flags.custom_opdefs))
    converter = _get_tflite_converter(flags)
    if flags.inference_type:
        converter.inference_type = _parse_inference_type(flags.inference_type, 'inference_type')
    if flags.inference_input_type:
        converter.inference_input_type = _parse_inference_type(flags.inference_input_type, 'inference_input_type')
    if flags.output_format:
        converter.output_format = _toco_flags_pb2.FileFormat.Value(flags.output_format)
    if flags.mean_values and flags.std_dev_values:
        input_arrays = converter.get_input_arrays()
        std_dev_values = _parse_array(flags.std_dev_values, type_fn=float)
        if converter.inference_type == dtypes.float32:
            mean_values = _parse_array(flags.mean_values, type_fn=float)
        else:
            mean_values = _parse_array(flags.mean_values, type_fn=int)
        quant_stats = list(zip(mean_values, std_dev_values))
        if not flags.input_arrays and len(input_arrays) > 1 or len(input_arrays) != len(quant_stats):
