def testBiasQuantization(self, is_int16_quantize, explicitly_set_bias, bias_type, is_valid_bias_type):
    model = tf.keras.models.Sequential([tf.keras.layers.Dense(1024, input_shape=[1024], activation=None, bias_initializer='ones')])
    saved_model_dir = os.path.join(self.get_temp_dir(), 'dense_saved_model')
    save.save(model, saved_model_dir)
    k_dense_bias_name = 'sequential/dense/BiasAdd'
    quantized_converter = lite.TFLiteConverterV2.from_saved_model(saved_model_dir)
    quantized_converter.optimizations = [lite.Optimize.DEFAULT]
    if explicitly_set_bias:
        quantized_converter._experimental_full_integer_quantization_bias_type = bias_type
    if is_int16_quantize:
        quantized_converter.target_spec.supported_ops = [lite.OpsSet.EXPERIMENTAL_TFLITE_BUILTINS_ACTIVATIONS_INT16_WEIGHTS_INT8]
    else:
        quantized_converter.target_spec.supported_ops = [lite.OpsSet.TFLITE_BUILTINS_INT8]

    def calibration_gen():
        for _ in range(5):
            yield [np.random.randn(1, 1024).astype(np.float32)]
    quantized_converter.representative_dataset = calibration_gen
    if <MASK>:
        with self.assertRaisesRegex(ValueError, 'Expected bias type to be'):
            quantized_converter.convert()
        return
    quantized_tflite_model = quantized_converter.convert()
    self.assertIsNotNone(quantized_tflite_model)
    interp = interpreter.Interpreter(model_content=quantized_tflite_model)
    interp.allocate_tensors()
    dense_bias = next((d for d in interp.get_tensor_details() if d['name'].startswith(k_dense_bias_name)))
    self.assertEqual(bias_type, dense_bias['dtype'])

def _reduce(self, op, name: str, *, axis: Axis=0, skipna: bool=True, numeric_only: bool=False, filter_type=None, **kwds):
    assert filter_type is None or filter_type == 'bool', filter_type
    out_dtype = 'bool' if filter_type == 'bool' else None
    if axis is not None:
        axis = self._get_axis_number(axis)

    def func(values: np.ndarray):
        return op(values, axis=axis, skipna=skipna, **kwds)

    def blk_func(values, axis: Axis=1):
        if isinstance(values, ExtensionArray):
            if not is_1d_only_ea_dtype(values.dtype):
                return values._reduce(name, axis=1, skipna=skipna, **kwds)
            return values._reduce(name, skipna=skipna, keepdims=True, **kwds)
        else:
            return op(values, axis=axis, skipna=skipna, **kwds)

    def _get_data() -> DataFrame:
        if filter_type is None:
            data = self._get_numeric_data()
        else:
            assert filter_type == 'bool'
            data = self._get_bool_data()
        return data
    df = self
    if <MASK>:
        df = _get_data()
    if axis is None:
        dtype = find_common_type([block.values.dtype for block in df._mgr.blocks])
        if isinstance(dtype, ExtensionDtype):
            df = df.astype(dtype)
            arr = concat_compat(list(df._iter_column_arrays()))
            return arr._reduce(name, skipna=skipna, keepdims=False, **kwds)
        return func(df.values)
    elif axis == 1:
        if len(df.index) == 0:
            result = df._reduce(op, name, axis=0, skipna=skipna, numeric_only=False, filter_type=filter_type, **kwds).iloc[:0]
            result.index = df.index
            return result
        if df.shape[1] and name != 'kurt':
            dtype = find_common_type([block.values.dtype for block in df._mgr.blocks])
            if isinstance(dtype, ExtensionDtype):
                name = {'argmax': 'idxmax', 'argmin': 'idxmin'}.get(name, name)
                df = df.astype(dtype)
                arr = concat_compat(list(df._iter_column_arrays()))
                (nrows, ncols) = df.shape
                row_index = np.tile(np.arange(nrows), ncols)
                col_index = np.repeat(np.arange(ncols), nrows)
                ser = Series(arr, index=col_index, copy=False)
                if name == 'all':
                    skipna = True
                result = ser.groupby(row_index).agg(name, **kwds, skipna=skipna)
                result.index = df.index
                return result
        df = df.T
    res = df._mgr.reduce(blk_func)
    out = df._constructor_from_mgr(res, axes=res.axes).iloc[0]
    if out_dtype is not None and out.dtype != 'boolean':
        out = out.astype(out_dtype)
    elif (df._mgr.get_dtypes() == object).any() and name not in ['any', 'all']:
        out = out.astype(object)
    elif len(self) == 0 and out.dtype == object and (name in ('sum', 'prod')):
        out = out.astype(np.float64)
    return out

def remove_field(self, model, field):
    """
        Remove a field from a model. Usually involves deleting a column,
        but for M2Ms may involve deleting a table.
        """
    if <MASK>:
        return self.delete_model(field.remote_field.through)
    if field.db_parameters(connection=self.connection)['type'] is None:
        return
    if field.remote_field:
        fk_names = self._constraint_names(model, [field.column], foreign_key=True)
        for fk_name in fk_names:
            self.execute(self._delete_fk_sql(model, fk_name))
    sql = self.sql_delete_column % {'table': self.quote_name(model._meta.db_table), 'column': self.quote_name(field.column)}
    self.execute(sql)
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()
    for sql in list(self.deferred_sql):
        if isinstance(sql, Statement) and sql.references_column(model._meta.db_table, field.column):
            self.deferred_sql.remove(sql)

def adaptiveavgpool2d_check(tensor_type, module_instance):
    output_size = module_instance.output_size
    if isinstance(output_size, int):
        output_size = [output_size, output_size]
    elif isinstance(output_size, tuple):
        output_size = list(output_size)
        if output_size[0] is None:
            output_size[0] = output_size[1]
        if <MASK>:
            output_size[1] = output_size[0]
    new_type_list = list(tensor_type.__args__)
    if len(tensor_type.__args__) == 4 or len(tensor_type.__args__) == 3:
        new_type_list[-1] = output_size[1]
        new_type_list[-2] = output_size[0]
        return TensorType(tuple(new_type_list))
    else:
        raise TypeError(f'Tensor ranks must be 3 or 4. Got {tensor_type}')

def str2bool(value: Optional[str]) -> bool:
    """Convert environment variables to boolean values."""
    if not value:
        return False
    if not isinstance(value, str):
        raise ValueError(f'Expected a string value for boolean conversion, got {type(value)}')
    value = value.strip().lower()
    true_value_set = {'1', 'true', 't', 'yes', 'y', 'on', 'enable', 'enabled', 'found'}
    false_value_set = {'0', 'false', 'f', 'no', 'n', 'off', 'disable'}
    if value in true_value_set:
        return True
    if <MASK>:
        return False
    raise ValueError(f'Invalid string value for boolean conversion: {value}')

def visit_Attribute(self, node):
    parent_types = self.visit(node.value)
    parent_value = anno.Static.VALUE.of(node.value, None)
    if parent_value is not None:
        static_value = getattr(parent_value, node.attr, NO_VALUE)
        if <MASK>:
            (types, static_value) = self.resolver.res_name(self.namespace, self.types_in, anno.Basic.QN.of(node))
            anno.setanno(node, anno.Static.VALUE, static_value)
            if __debug__:
                self._check_set(types)
            return types
    else:
        if parent_types is None:
            return None
        inferred_values = [getattr(t, node.attr, None) for t in parent_types]
        if not inferred_values:
            return None
        static_value = inferred_values[0]
        if static_value is None:
            return None
        if any((v is not static_value for v in inferred_values[1:])):
            return None
    types = self.resolver.res_value(self.namespace, static_value)
    anno.setanno(node, anno.Static.VALUE, static_value)
    if __debug__:
        self._check_set(types)
    return types

def get_tolerance_and_cosine_flag(self, is_training, current_device, name):
    cosine = self.args.cosine
    tolerance = 0.001
    if self.args.freezing and name in REQUIRE_HIGHER_TOLERANCE_FOR_FREEZING:
        tolerance = 8 * 0.01
    if <MASK>:
        from torch._inductor import config as inductor_config
        if name in REQUIRE_EVEN_HIGHER_TOLERANCE or (inductor_config.max_autotune and name in REQUIRE_EVEN_HIGHER_TOLERANCE_MAX_AUTOTUNE):
            tolerance = 8 * 0.01
        elif name in REQUIRE_HIGHER_TOLERANCE or (self.args.amp and name in REQUIRE_HIGHER_TOLERANCE_AMP):
            tolerance = 4 * 0.01
        else:
            tolerance = 0.01
    return (tolerance, cosine)

