def __init__(self, obj, subscript):
    super().__init__(obj.name)
    self.obj = obj
    if isinstance(subscript, int):
        if subscript < 0:
            raise ValueError('Negative indexing is not supported.')
        self.start = subscript + 1
        self.length = 1
    elif isinstance(subscript, slice):
        if subscript.start is not None and subscript.start < 0 or (subscript.stop is not None and subscript.stop < 0):
            raise ValueError('Negative indexing is not supported.')
        if <MASK>:
            raise ValueError('Step argument is not supported.')
        if subscript.stop and subscript.start and (subscript.stop < subscript.start):
            raise ValueError('Slice stop must be greater than slice start.')
        self.start = 1 if subscript.start is None else subscript.start + 1
        if subscript.stop is None:
            self.length = None
        else:
            self.length = subscript.stop - (subscript.start or 0)
    else:
        raise TypeError('Argument to slice must be either int or slice instance.')

def map_arg(arg):

    def maybe_non_contig(tensor):
        if not non_contiguous or tensor.numel() < 2:
            return tensor.clone()
        return noncontiguous_like(tensor)

    def conjugate(tensor):
        return tensor.conj()
    if <MASK>:
        return arg
    elif isinstance(arg, tuple) and len(arg) == 0:
        var = conjugate(torch.randn((), dtype=dtype, device=device))
        var.requires_grad = requires_grad
        return var
    elif isinstance(arg, tuple) and (not isinstance(arg[0], torch.Tensor)):
        return conjugate(maybe_non_contig(torch.randn(*arg, dtype=dtype, device=device))).requires_grad_(requires_grad)
    elif isinstance(arg, non_differentiable):
        if isinstance(arg.tensor, torch.Tensor):
            return conjugate(maybe_non_contig(arg.tensor.to(device=device)))
        return conjugate(maybe_non_contig(arg.tensor.to(device=device)))
    elif isinstance(arg, torch.Tensor):
        if arg.is_complex() != dtype.is_complex:
            raise RuntimeError('User provided tensor is real for a test that runs with complex dtype, ', 'which is not supported for now')
        v = conjugate(maybe_non_contig(arg)).detach().to(device=device).clone()
        v.requires_grad = requires_grad and (v.is_floating_point() or v.is_complex())
        return v
    elif callable(arg):
        return map_arg(arg(dtype=dtype, device=device))
    else:
        return arg

def to_time(arg, format: str | None=None, infer_time_format: bool=False, errors: DateTimeErrorChoices='raise'):
    """
    Parse time strings to time objects using fixed strptime formats ("%H:%M",
    "%H%M", "%I:%M%p", "%I%M%p", "%H:%M:%S", "%H%M%S", "%I:%M:%S%p",
    "%I%M%S%p")

    Use infer_time_format if all the strings are in the same format to speed
    up conversion.

    Parameters
    ----------
    arg : string in time format, datetime.time, list, tuple, 1-d array,  Series
    format : str, default None
        Format used to convert arg into a time object.  If None, fixed formats
        are used.
    infer_time_format: bool, default False
        Infer the time format based on the first non-NaN element.  If all
        strings are in the same format, this will speed up conversion.
    errors : {'raise', 'coerce'}, default 'raise'
        - If 'raise', then invalid parsing will raise an exception
        - If 'coerce', then invalid parsing will be set as None

    Returns
    -------
    datetime.time
    """
    if errors not in ('raise', 'coerce'):
        raise ValueError("errors must be one of 'raise', or 'coerce'.")

    def _convert_listlike(arg, format):
        if isinstance(arg, (list, tuple)):
            arg = np.array(arg, dtype='O')
        elif getattr(arg, 'ndim', 1) > 1:
            raise TypeError('arg must be a string, datetime, list, tuple, 1-d array, or Series')
        arg = np.asarray(arg, dtype='O')
        if infer_time_format and format is None:
            format = _guess_time_format_for_array(arg)
        times: list[time | None] = []
        if format is not None:
            for element in arg:
                try:
                    times.append(datetime.strptime(element, format).time())
                except (ValueError, TypeError) as err:
                    if <MASK>:
                        msg = f'Cannot convert {element} to a time with given format {format}'
                        raise ValueError(msg) from err
                    times.append(None)
        else:
            formats = _time_formats[:]
            format_found = False
            for element in arg:
                time_object = None
                try:
                    time_object = time.fromisoformat(element)
                except (ValueError, TypeError):
                    for time_format in formats:
                        try:
                            time_object = datetime.strptime(element, time_format).time()
                            if not format_found:
                                fmt = formats.pop(formats.index(time_format))
                                formats.insert(0, fmt)
                                format_found = True
                            break
                        except (ValueError, TypeError):
                            continue
                if time_object is not None:
                    times.append(time_object)
                elif errors == 'raise':
                    raise ValueError(f'Cannot convert arg {arg} to a time')
                else:
                    times.append(None)
        return times
    if arg is None:
        return arg
    elif isinstance(arg, time):
        return arg
    elif isinstance(arg, ABCSeries):
        values = _convert_listlike(arg._values, format)
        return arg._constructor(values, index=arg.index, name=arg.name)
    elif isinstance(arg, ABCIndex):
        return _convert_listlike(arg, format)
    elif is_list_like(arg):
        return _convert_listlike(arg, format)
    return _convert_listlike(np.array([arg]), format)[0]

