def _wrap_result(self, result, name=None, expand: bool | None=None, fill_value=np.nan, returns_string: bool=True, dtype=None):
    from pandas import Index, MultiIndex
    if not hasattr(result, 'ndim') or not hasattr(result, 'dtype'):
        if isinstance(result, ABCDataFrame):
            result = result.__finalize__(self._orig, name='str')
        return result
    assert result.ndim < 3
    if expand is None:
        expand = result.ndim != 1
    elif expand is True and (not isinstance(self._orig, ABCIndex)):
        if isinstance(result.dtype, ArrowDtype):
            import pyarrow as pa
            from pandas.core.arrays.arrow.array import ArrowExtensionArray
            value_lengths = pa.compute.list_value_length(result._pa_array)
            max_len = pa.compute.max(value_lengths).as_py()
            min_len = pa.compute.min(value_lengths).as_py()
            if result._hasna:
                result = ArrowExtensionArray(result._pa_array.fill_null([None] * max_len))
            if min_len < max_len:
                result = ArrowExtensionArray(pa.compute.list_slice(result._pa_array, start=0, stop=max_len, return_fixed_size_list=True))
            if name is None:
                name = range(max_len)
            result = pa.compute.list_flatten(result._pa_array).to_numpy().reshape(len(result), max_len)
            result = {label: ArrowExtensionArray(pa.array(res)) for (label, res) in zip(name, result.T, strict=True)}
        elif is_object_dtype(result):

            def cons_row(x):
                if <MASK>:
                    return x
                else:
                    return [x]
            result = [cons_row(x) for x in result]
            if result and (not self._is_string):
                max_len = max((len(x) for x in result))
                result = [x * max_len if len(x) == 0 or x[0] is np.nan else x for x in result]
    if not isinstance(expand, bool):
        raise ValueError('expand must be True or False')
    if expand is False:
        if name is None:
            name = getattr(result, 'name', None)
        if name is None:
            name = self._orig.name
    if isinstance(self._orig, ABCIndex):
        if is_bool_dtype(result):
            return result
        if expand:
            result = list(result)
            out: Index = MultiIndex.from_tuples(result, names=name)
            if out.nlevels == 1:
                out = out.get_level_values(0)
            return out
        else:
            return Index(result, name=name, dtype=dtype)
    else:
        index = self._orig.index
        _dtype: DtypeObj | str | None = dtype
        vdtype = getattr(result, 'dtype', None)
        if _dtype is not None:
            pass
        elif self._is_string:
            if is_bool_dtype(vdtype):
                _dtype = result.dtype
            elif returns_string:
                _dtype = self._orig.dtype
            else:
                _dtype = vdtype
        elif vdtype is not None:
            _dtype = vdtype
        if expand:
            cons = self._orig._constructor_expanddim
            result = cons(result, columns=name, index=index, dtype=_dtype)
        else:
            cons = self._orig._constructor
            result = cons(result, name=name, index=index, dtype=_dtype)
        result = result.__finalize__(self._orig, method='str')
        if name is not None and result.ndim == 1:
            result.name = name
        return result

@contextlib.contextmanager
def _reparametrize_module(module: 'torch.nn.Module', parameters_and_buffers: dict[str, Tensor], tie_weights: bool=False, strict: bool=False, stack_weights: bool=False):
    if tie_weights:
        untied_parameters_and_buffers = _untie_named_tensors_map(module, parameters_and_buffers)
    else:
        untied_parameters_and_buffers = parameters_and_buffers
    accessor = NamedMemberAccessor(module)
    if strict:
        (missing_keys, unexpected_keys) = accessor.check_keys(untied_parameters_and_buffers)
        error_msgs = []
        if len(unexpected_keys) > 0:
            error_msgs.append(f"Unexpected key(s): {', '.join(map(repr, unexpected_keys))}.")
        if len(missing_keys) > 0:
            error_msgs.append(f"Missing key(s): {', '.join(map(repr, missing_keys))}.")
        if len(error_msgs) > 0:
            raise RuntimeError('Error(s) in reparametrizing for {}:\n\t{}'.format(module._get_name(), '\n\t'.join(error_msgs)))
    orig_parameters_and_buffers: dict[str, Tensor] = {}
    try:
        (orig_parameters_and_buffers, _) = accessor.swap_tensors_dict(untied_parameters_and_buffers, allow_missing=True)
        yield
    finally:
        if <MASK>:
            orig_parameters_and_buffers = dict(reversed(orig_parameters_and_buffers.items()))
        (new_parameters_and_buffers, _) = accessor.swap_tensors_dict(orig_parameters_and_buffers, allow_missing=True)
        parameters_and_buffers.update({k: new_parameters_and_buffers[k] for k in parameters_and_buffers if k in new_parameters_and_buffers})

def get_fx_value_by_ir_value(self, value: torch._C.Value):
    value_name = value.debugName()
    if <MASK>:
        input_node = self.name_to_node[value_name]
        return input_node
    elif value_name in self.name_to_constant:
        if isinstance(self.name_to_constant[value_name], torch.ScriptObject):
            return self.fx_graph.get_attr(value_name)
        return self.name_to_constant[value_name]
    elif value_name in self.name_to_attribute_fqn:
        return self.get_fx_value_by_fqn(self.name_to_attribute_fqn[value_name])
    else:
        raise ValueError(f'Input {value_name} not found')

