def print_summary_table(data, print_dataframe=False):
    if <MASK>:
        pd.options.display.max_rows = 1000
        pd.options.display.max_columns = 1000
        pd.options.display.width = 2000
        print(data)
    width = max(map(len, data.columns))
    for col in data.columns:
        try:
            if col in ('dev', 'name', 'batch_size', 'tag'):
                continue
            elif col in ('pct_ops', 'pct_time'):
                print(col.ljust(width), f'{data[col].mean():.3%}')
            elif col in ('graphs', 'graph_calls', 'captured_ops', 'total_ops'):
                print(col.ljust(width), f'{data[col].mean():.3f}')
            elif col in 'compilation_latency':
                print(col.ljust(width), f'mean={data[col].mean():.3f} seconds')
            elif col in 'compression_ratio':
                print(col.ljust(width), f'mean={data[col].mean():.3f}x')
            elif col in 'accuracy':
                pass_rate = (data[col] == 'pass').mean()
                print(col.ljust(width), f'pass_rate={100 * pass_rate:.2f}%')
            else:
                cdata = data[col]
                print(col.ljust(width), f'gmean={gmean(cdata):.2f}x mean={cdata.mean():.3f}x')
        except Exception:
            pass

def add_type_constraints(function_type: FunctionType, input_signature: Any, default_values: Dict[str, Any]) -> FunctionType:
    """Adds type constraints to a FunctionType based on the input_signature."""
    context = trace_type.InternalTracingContext(is_legacy_signature=True)
    constraints = [trace_type.from_value(c, context) for c in input_signature]
    parameters = []
    has_var_pos = any((p.kind is p.VAR_POSITIONAL for p in function_type.parameters.values()))
    for param in function_type.parameters.values():
        sanitized_kind = param.POSITIONAL_ONLY if has_var_pos and param.kind is param.POSITIONAL_OR_KEYWORD else param.kind
        if <MASK>:
            parameters.append(Parameter('self', sanitized_kind, param.optional, None))
        elif param.kind is param.VAR_KEYWORD:
            continue
        elif param.kind is param.VAR_POSITIONAL:
            for i in range(len(constraints)):
                parameters.append(Parameter(param.name + '_' + str(i), Parameter.POSITIONAL_ONLY, False, constraints.pop(0)))
        elif param.kind in [param.POSITIONAL_ONLY, param.POSITIONAL_OR_KEYWORD, param.KEYWORD_ONLY]:
            if param.kind is param.KEYWORD_ONLY and param.name not in default_values:
                raise TypeError(f'Since input_signature is defined, keyword-only parameter `{param.name}` must have a default value')
            if constraints:
                parameters.append(Parameter(param.name, sanitized_kind, param.optional, constraints.pop(0)))
            elif param.name in default_values:
                type_constraint = trace_type.from_value(default_values[param.name])
                parameters.append(Parameter(param.name, sanitized_kind, param.optional, type_constraint))
            else:
                raise TypeError(f'input_signature missing type constraint for {param.name}')
    if constraints:
        raise TypeError(f'input_signature contains {len(constraints)} extra type constraints.')
    return FunctionType(parameters)

@staticmethod
def _check_for_hop(gm: torch.fx.GraphModule) -> None:
    for module in gm.modules():
        if <MASK>:
            continue
        for node in module.graph.nodes:
            if isinstance(node.target, torch._ops.HigherOrderOperator) and (not node.target.cacheable()):
                raise BypassFxGraphCache(f"Can't cache HigherOrderOperator: {node.target.name()}")
            if node.op == 'getattr' and isinstance(getattr(gm, node.target), torch._C.ScriptObject):
                raise BypassFxGraphCache("Can't cache torchbind objects")

def visit_manager(node: GuardManager) -> list[GuardManager]:
    assert not isinstance(node, DictGuardManager)
    tag_safe_roots = []
    for child_mgr in node.get_child_managers():
        tag_safe_roots.extend(visit(child_mgr))
    if node.is_guarded_value_immutable():
        if issubclass(node.get_type_of_guarded_value(), torch.Tensor):
            if node.has_no_accessors() and (not node.has_object_aliasing_guard()):
                node.mark_tag_safe()
        else:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), dict):
        accessors = node.get_accessors()
        child_mgrs = node.get_child_managers()
        is_subtree_tag_safe = all((isinstance(accessor, DictGetItemGuardAccessor) and mgr.is_tag_safe() for (accessor, mgr) in zip(accessors, child_mgrs)))
        if <MASK>:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), torch.nn.Module):
        is_subtree_tag_safe = check_tag_safety(node, (GetGenericDictGuardAccessor, TypeGuardAccessor))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
            return [node]
    elif node.get_type_of_guarded_value() in (types.FunctionType, types.MethodType, staticmethod, classmethod) and config.assume_dunder_attributes_remain_unchanged:
        is_subtree_tag_safe = check_tag_safety(node, (CodeGuardAccessor, ClosureGuardAccessor, FuncDefaultsGuardAccessor, FuncKwDefaultsGuardAccessor, GetAttrGuardAccessor))
        for accessor in node.get_accessors():
            if isinstance(accessor, GetAttrGuardAccessor):
                is_subtree_tag_safe &= accessor.get_attr_name() in dunder_attrs_assumed_constants
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), types.CellType):
        is_subtree_tag_safe = check_tag_safety(node, (GetAttrGuardAccessor,))
        is_subtree_tag_safe &= all((isinstance(accessor, GetAttrGuardAccessor) and accessor.get_attr_name() == 'cell_contents' for accessor in node.get_accessors()))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), tuple) and node.get_source().endswith(dunder_attrs_assumed_constants) and config.assume_dunder_attributes_remain_unchanged:
        is_subtree_tag_safe = check_tag_safety(node, (TupleGetItemGuardAccessor,))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), type):
        is_subtree_tag_safe = check_tag_safety(node, (TypeDictGuardAccessor, TypeMROGuardAccessor))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    return tag_safe_roots

def constant_value(pred):
    """Return the bool value for `pred`, or None if `pred` had a dynamic value.

  Args:
    pred: A scalar, either a Python bool or a TensorFlow boolean variable
      or tensor, or the Python integer 1 or 0.

  Returns:
    True or False if `pred` has a constant boolean value, None otherwise.

  Raises:
    TypeError: If `pred` is not a Variable, Tensor or bool, or Python
      integer 1 or 0.
  """
    if isinstance(pred, tensor.Tensor):
        return tensor_util.constant_value(pred)
    if pred in {0, 1}:
        return bool(pred)
    if isinstance(pred, bool):
        return pred
    if <MASK>:
        return None
    raise TypeError('`pred` must be a Tensor, or a Python bool, or 1 or 0. Found instead: %s' % type(pred))

def _name_get(dtype):
    if dtype.isbuiltin == 2:
        return dtype.type.__name__
    if <MASK>:
        name = type(dtype).__name__
    elif issubclass(dtype.type, np.void):
        name = dtype.type.__name__
    else:
        name = _kind_name(dtype)
    if _name_includes_bit_suffix(dtype):
        name += f'{dtype.itemsize * 8}'
    if dtype.type in (np.datetime64, np.timedelta64):
        name += _datetime_metadata_str(dtype)
    return name

def _get_subgraph_names(gm: GraphModule, skip_invoke_subgraph: bool=False) -> Generator[str, None, None]:
    all_subgraph_names: OrderedSet[str] = OrderedSet((x.target for x in gm.graph.find_nodes(op='get_attr')))
    fx_subgraph_names: OrderedSet[str] = OrderedSet()
    for (child_name, child_module) in gm.named_children():
        if <MASK>:
            fx_subgraph_names.add(child_name)
    if skip_invoke_subgraph:
        for node in gm.graph.find_nodes(op='call_function', target=torch.ops.higher_order.invoke_subgraph):
            fx_subgraph_names.discard(node.args[0].target)
    yield from fx_subgraph_names

