def sort_values(self, *, return_indexer: bool=False, ascending: bool=True, na_position: NaPosition='last', key: Callable | None=None) -> Self | tuple[Self, np.ndarray | RangeIndex]:
    if key is not None:
        return super().sort_values(return_indexer=return_indexer, ascending=ascending, na_position=na_position, key=key)
    else:
        sorted_index = self
        inverse_indexer = False
        if ascending:
            if <MASK>:
                sorted_index = self[::-1]
                inverse_indexer = True
        elif self.step > 0:
            sorted_index = self[::-1]
            inverse_indexer = True
    if return_indexer:
        if inverse_indexer:
            rng = range(len(self) - 1, -1, -1)
        else:
            rng = range(len(self))
        return (sorted_index, RangeIndex(rng))
    else:
        return sorted_index

def process_arg(x: T, ignore_types_override: Optional[Sequence[type[Any]]]=None) -> Union[T, KeywordArg, Ignored]:
    current_ignore_types = ignore_types_override if ignore_types_override is not None else ignore_types
    if <MASK>:
        return KeywordArg(inv_scalar_workaround[x])
    if type(x) in current_ignore_types:
        return Ignored()
    if isinstance(x, list) and all((isinstance(y, Ignored) for y in x)) and x:
        return Ignored()
    return x

def _compute_output_meta_with_inductor_strides(self):
    out = self.out_metas
    fwd_output_strides = self.fwd_output_strides
    if <MASK>:
        return out
    from torch.fx.experimental.symbolic_shapes import statically_known_true
    for i in range(len(out)):
        if not isinstance(out[i], Tensor):
            continue
        strides = fwd_output_strides[i]
        if strides is None:
            continue
        if all((statically_known_true(s1 == s2) for (s1, s2) in zip(out[i].stride(), strides))):
            continue
        out[i] = out[i].as_strided(out[i].shape, strides)
    return out

@register_make_test_function('make_batchmatmul_tests')
def make_batchmatmul_tests(options):
    """Make a set of tests to do basic batch matrix multiply."""
    test_parameters = [{'dtype': [tf.float32], 'shapes': [((3, 4, 7), (7, 9), (3, 4, 7), (7, 9)), ((None, 4, 5), (None, 5, 6), (3, 4, 5), (3, 5, 6)), ((None, 1, 3, 4), (None, 4, 2), (2, 1, 3, 4), (5, 4, 2)), ((None, None, None, 3, 4), (None, None, None, 4, 3), (2, 2, 2, 3, 4), (2, 2, 2, 4, 3))], 'adjoint_b': [False, True], 'adjoint_a': [False, True], 'rhs_constant': [False], 'fully_quantize': [False, True]}]

    def swap_last_two_dims(*args):
        """Return a tuple with the last two dimensions swapped."""
        return args[:-2] + (args[-1],) + (args[-2],)

    def build_graph(parameters):
        """Build a simple graph with BatchMatMul."""
        placeholder0_shape = parameters['shapes'][0]
        adj_a = parameters['adjoint_a']
        adj_b = parameters['adjoint_b']
        rhs_constant = parameters['rhs_constant']
        if adj_a:
            placeholder0_shape = swap_last_two_dims(*placeholder0_shape)
        input0_tensor = tf.compat.v1.placeholder(dtype=parameters['dtype'], shape=placeholder0_shape)
        if rhs_constant:
            if <MASK>:
                constant1_shape = swap_last_two_dims(*parameters['shapes'][3])
            else:
                constant1_shape = parameters['shapes'][3]
            data = create_tensor_data(parameters['dtype'], constant1_shape, min_value=-1.0, max_value=1.0)
            input1_constant = tf.constant(data, shape=constant1_shape, dtype=parameters['dtype'])
            out = tf.matmul(input0_tensor, input1_constant, adjoint_a=adj_a, adjoint_b=adj_b)
            return ([input0_tensor], [out])
        else:
            if adj_b:
                placeholder1_shape = swap_last_two_dims(*parameters['shapes'][1])
            else:
                placeholder1_shape = parameters['shapes'][1]
            input1_tensor = tf.compat.v1.placeholder(dtype=parameters['dtype'], shape=placeholder1_shape)
            out = tf.matmul(input0_tensor, input1_tensor, adjoint_a=adj_a, adjoint_b=adj_b)
            return ([input0_tensor, input1_tensor], [out])

    def build_inputs(parameters, sess, inputs, outputs):
        """Feed inputs, assign variables, and freeze graph."""
        input0_shape = parameters['shapes'][2]
        adj_a = parameters['adjoint_a']
        adj_b = parameters['adjoint_b']
        rhs_constant = parameters['rhs_constant']
        if adj_a:
            input0_shape = swap_last_two_dims(*input0_shape)
        input0_value = create_tensor_data(parameters['dtype'], input0_shape, min_value=-1.0, max_value=1.0)
        if rhs_constant:
            output_values = sess.run(outputs, feed_dict=dict(zip(inputs, [input0_value])))
            return ([input0_value], output_values)
        else:
            input1_shape = parameters['shapes'][3] if not adj_b else swap_last_two_dims(*parameters['shapes'][3])
            input1_value = create_tensor_data(parameters['dtype'], input1_shape, min_value=-1.0, max_value=1.0)
            output_values = sess.run(outputs, feed_dict=dict(zip(inputs, [input0_value, input1_value])))
            return ([input0_value, input1_value], output_values)
    options.disable_batchmatmul_unfold = True
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs, expected_tf_failures=0)

@classmethod
def _from_buffer(cls, *args, dtype=None, device=None, **kwargs):
    if cls == TypedStorage:
        dtype = torch.get_default_dtype() if dtype is None else dtype
        device = torch.device('cpu' if device is None else device)
        if device.type != 'cpu':
            raise RuntimeError(f'TypedStorage.from_buffer: Not available for device {device.type}')
        untyped_storage: torch.UntypedStorage = torch.UntypedStorage.from_buffer(*args, dtype=dtype, **kwargs)
    else:
        if <MASK>:
            raise RuntimeError("from_buffer: 'dtype' can only be specified in UntypedStorage.from_buffer and TypedStorage.from_buffer")
        if device is not None:
            raise RuntimeError("from_buffer: 'device' can only be specified in UntypedStorage.from_buffer and TypedStorage.from_buffer")
        dtype = cls._dtype
        untyped_storage = torch.UntypedStorage.from_buffer(*args, dtype=dtype, **kwargs)
    return TypedStorage(wrap_storage=untyped_storage, dtype=dtype, _internal=True)

def _process_unlinkable_fobjects(self, objects, libraries, fcompiler, library_dirs, unlinkable_fobjects):
    libraries = list(libraries)
    objects = list(objects)
    unlinkable_fobjects = list(unlinkable_fobjects)
    for lib in libraries[:]:
        for libdir in library_dirs:
            fake_lib = os.path.join(libdir, lib + '.fobjects')
            if <MASK>:
                libraries.remove(lib)
                with open(fake_lib) as f:
                    unlinkable_fobjects.extend(f.read().splitlines())
                c_lib = os.path.join(libdir, lib + '.cobjects')
                with open(c_lib) as f:
                    objects.extend(f.read().splitlines())
    if unlinkable_fobjects:
        fobjects = [os.path.abspath(obj) for obj in unlinkable_fobjects]
        wrapped = fcompiler.wrap_unlinkable_objects(fobjects, output_dir=self.build_temp, extra_dll_dir=self.extra_dll_dir)
        objects.extend(wrapped)
    return (objects, libraries)

def method___setitem__(self, key, value):
    from ..symbolic_convert import InstructionTranslator
    tx = InstructionTranslator.current_tx()
    proxy = tx.output.create_proxy('call_function', operator.setitem, *proxy_args_kwargs([self, key, value], {}))
    if isinstance(value, TensorVariable):
        with torch._dynamo.utils._disable_saved_tensors_hooks_during_tracing(), tx.fake_mode.shape_env.ignore_fresh_unbacked_symbols() if tx.fake_mode and tx.fake_mode.shape_env else nullcontext():
            get_fake_value(proxy.node, tx, allow_non_graph_fake=False)
        vt = value
        if isinstance(vt, variables.lazy.LazyVariableTracker):
            vt = variables.lazy.LazyVariableTracker.realize_all(vt)
        self.synchronize_attributes(tx, type(vt))
    if <MASK>:
        tx.output.region_tracker.add_node_mutation(proxy.node, 0)
    return ConstantVariable.create(None)

def explain_template_loading_attempts(app: App, template: str, attempts: list[tuple[BaseLoader, Scaffold, tuple[str, str | None, t.Callable[[], bool] | None] | None]]) -> None:
    """This should help developers understand what failed"""
    info = [f'Locating template {template!r}:']
    total_found = 0
    blueprint = None
    if (ctx := _cv_app.get(None)) is not None and ctx.has_request:
        blueprint = ctx.request.blueprint
    for (idx, (loader, srcobj, triple)) in enumerate(attempts):
        if isinstance(srcobj, App):
            src_info = f'application {srcobj.import_name!r}'
        elif isinstance(srcobj, Blueprint):
            src_info = f'blueprint {srcobj.name!r} ({srcobj.import_name})'
        else:
            src_info = repr(srcobj)
        info.append(f'{idx + 1:5}: trying loader of {src_info}')
        for line in _dump_loader_info(loader):
            info.append(f'       {line}')
        if triple is None:
            detail = 'no match'
        else:
            detail = f"found ({triple[1] or '<string>'!r})"
            total_found += 1
        info.append(f'       -> {detail}')
    seems_fishy = False
    if total_found == 0:
        info.append('Error: the template could not be found.')
        seems_fishy = True
    elif total_found > 1:
        info.append('Warning: multiple loaders returned a match for the template.')
        seems_fishy = True
    if <MASK>:
        info.append(f'  The template was looked up from an endpoint that belongs to the blueprint {blueprint!r}.')
        info.append('  Maybe you did not place a template in the right folder?')
        info.append('  See https://flask.palletsprojects.com/blueprints/#templates')
    app.logger.info('\n'.join(info))

def apply_empty_result(self):
    """
        we have an empty result; at least 1 axis is 0

        we will try to apply the function to an empty
        series in order to see if this is a reduction function
        """
    assert callable(self.func)
    if self.result_type not in ['reduce', None]:
        return self.obj.copy()
    should_reduce = self.result_type == 'reduce'
    from pandas import Series
    if not should_reduce:
        try:
            if self.axis == 0:
                r = self.func(Series([], dtype=np.float64), *self.args, **self.kwargs)
            else:
                r = self.func(Series(index=self.columns, dtype=np.float64), *self.args, **self.kwargs)
        except Exception:
            pass
        else:
            should_reduce = not isinstance(r, Series)
    if should_reduce:
        if <MASK>:
            r = self.func(Series([], dtype=np.float64), *self.args, **self.kwargs)
        else:
            r = np.nan
        return self.obj._constructor_sliced(r, index=self.agg_axis)
    else:
        return self.obj.copy()

@staticmethod
def decide_layout_opt(gm: GraphModule, *, is_inference: bool) -> bool:
    """
        Decide if we should enable layout optimization for this graph based on
        heuristics.
        """
    if not config.layout_optimization:
        return False
    if config.force_layout_optimization:
        return True
    conv_nodes = [n for n in gm.graph.nodes if n.target == torch.ops.aten.convolution.default]
    nconv = len(conv_nodes)
    if nconv == 0:
        return False
    if torch.backends.mkldnn.enabled and torch.backends.mkldnn.is_available() and all((n.args[idx].meta['val'].device.type in SUPPORTED_MKLDNN_DEVICES for n in conv_nodes for idx in [0, 1])):
        return True
    if len(list(gm.graph.nodes)) >= 300 * nconv:
        log.debug('Skipped layout opt because only a few conv')
        return False
    if <MASK>:
        log.debug('See perf regression with dynamic shape. Follow up in https://github.com/pytorch/pytorch/issues/102670')
        return False

    def is_grouped(n: Any) -> bool:
        meta_val = n.args[1].meta['val']
        assert isinstance(meta_val, torch.Tensor)
        return n.args[-1] > 1 and meta_val.size(1) > 1

    def is_in_out_channel(n: torch.fx.Node) -> bool:
        return n.args[1].meta['val'].size(0) * 2 <= n.args[1].meta['val'].size(1) and n.args[1].meta['val'].size(2) > 1

    def is_small_channel(n: torch.fx.Node) -> bool:
        return n.args[1].meta['val'].size(0) <= 64 and n.args[1].meta['val'].size(1) <= 64
    if is_inference:
        flop_counts: dict[str, float] = defaultdict(float)
        for node in conv_nodes:
            counted_flops = count_flops_fx(node)
            if counted_flops is None:
                continue
            if is_grouped(node):
                node_type = 'grouped'
            elif is_small_channel(node):
                node_type = 'small'
            elif is_in_out_channel(node):
                node_type = 'in_out'
            else:
                node_type = 'default'
            flop_counts[node_type] += counted_flops
        else:
            log.debug('Conv inputs meta not found')
        GROUPED_MULTIPLIER = 1.358
        DEFAULT_MULTIPLIER = 0.823
        IN_OUT_MULTIPLIER = 0.725
        SMALL_MULTIPLIER = 0.783
        total_flops = sum(flop_counts.values())
        weighted_flops = flop_counts['grouped'] * GROUPED_MULTIPLIER + flop_counts['small'] * SMALL_MULTIPLIER + flop_counts['in_out'] * IN_OUT_MULTIPLIER + flop_counts['default'] * DEFAULT_MULTIPLIER
        do_layout_opt = weighted_flops <= total_flops
        if not do_layout_opt:
            log.debug('Skipped layout opt in inference because weighted flops indicate slowdown, default: %d, channels last: %d', total_flops, weighted_flops)
        return do_layout_opt
    if any(map(is_grouped, conv_nodes)):
        log.debug('Skip layout opt because found grouped convolution with >1 in_channels!')
        return False
    if any(map(is_in_out_channel, conv_nodes)):
        log.debug('Skip layout opt because some convolutions have smaller out_channel')
        return False
    if all(map(is_small_channel, conv_nodes)):
        log.debug('Skip layout opt because all convolution channels are too small')
        return False
    return True

