def test_nested_transform_with(self, transform_fn=None, mlir_pipeline=None, nested_fn=False, nested_mlir=False):

    @def_function.function
    def f(x, y, z):

        @def_function.function
        def inner_add():
            return math_ops.add(y, z, name='x_plus_y')
        return math_ops.add(x, inner_add(), name='x_plus_y')
    inputs = [1.0, 2.0, 4.0]
    self.assertEqual(f(*inputs), 7.0)
    nested_fn_transforms = {}
