    cf = f.get_concrete_function(*inputs)
    gdef = cf.graph.as_graph_def()
    for fdef in gdef.library.function:
        fdef_name = fdef.signature.name
        if nested_fn:
            nested_fn_transforms[fdef_name] = add_to_multiply
        if <MASK>:
            nested_mlir_transforms[fdef_name] = 'test-pass'
    updated_f = transform.transform_function(f, inputs=inputs, transform_fn=transform_fn, mlir_pipeline=mlir_pipeline, nested_fn_transforms=nested_fn_transforms, nested_mlir_transforms=nested_mlir_transforms)
    self.assertEqual(updated_f(*inputs), 8.0)

