def f(a, b):
    if axis is None:
        axis_a = axisa
        axis_b = axisb
        axis_c = axisc
    else:
        axis_a = axis
        axis_b = axis
        axis_c = axis
    if <MASK>:
        axis_a = np_utils.add(axis_a, array_ops.rank(a))
    if axis_b < 0:
        axis_b = np_utils.add(axis_b, array_ops.rank(b))

    def maybe_move_axis_to_last(a, axis):

        def move_axis_to_last(a, axis):
            return array_ops.transpose(a, array_ops.concat([math_ops.range(axis), math_ops.range(axis + 1, array_ops.rank(a)), [axis]], axis=0))
        return np_utils.cond(axis == np_utils.subtract(array_ops.rank(a), 1), lambda : a, lambda : move_axis_to_last(a, axis))
    a = maybe_move_axis_to_last(a, axis_a)
    b = maybe_move_axis_to_last(b, axis_b)
    a_dim = np_utils.getitem(array_ops.shape(a), -1)
    b_dim = np_utils.getitem(array_ops.shape(b), -1)

    def maybe_pad_0(a, size_of_last_dim):

        def pad_0(a):
            return array_ops.pad(a, array_ops.concat([array_ops.zeros([array_ops.rank(a) - 1, 2], dtypes.int32), constant_op.constant([[0, 1]], dtypes.int32)], axis=0))
        return np_utils.cond(math_ops.equal(size_of_last_dim, 2), lambda : pad_0(a), lambda : a)
    a = maybe_pad_0(a, a_dim)
    b = maybe_pad_0(b, b_dim)
    c = math_ops.cross(*np_utils.tf_broadcast(a, b))
    if axis_c < 0:
        axis_c = np_utils.add(axis_c, array_ops.rank(c))

    def move_last_to_axis(a, axis):
        r = array_ops.rank(a)
        return array_ops.transpose(a, array_ops.concat([math_ops.range(axis), [r - 1], math_ops.range(axis, r - 1)], axis=0))
    c = np_utils.cond((a_dim == 2) & (b_dim == 2), lambda : c[..., 2], lambda : np_utils.cond(axis_c == np_utils.subtract(array_ops.rank(c), 1), lambda : c, lambda : move_last_to_axis(c, axis_c)))
    return c

def jagged_from_tensor_and_lengths(tensor: torch.Tensor, starts: torch.Tensor, lengths: torch.Tensor) -> tuple[NestedTensor, torch.Tensor, Optional[torch.Tensor]]:
    """Constructs a NestedTensor backed by jagged layout from a tensor, starts of sequences, and sequence lengths"""
    batch_size = tensor.shape[0]
    if is_expandable_to(starts.shape, (batch_size,)) and is_expandable_to(lengths.shape, (batch_size,)):
        start_list = starts.expand(batch_size)
        length_list = lengths.expand(batch_size)
    else:
        raise RuntimeError('When constructing a jagged nested tensor using narrow(), your start and length must be Tensors that broadcast to input.shape[0]')
    assert len(tensor.shape) >= 2, 'tensor must at least be 2D for the nested narrow op to work'
    max_seq_len = tensor.shape[1]
    offset_lengths = max_seq_len * torch.arange(0, batch_size, dtype=torch.int64, device=tensor.device)
    offsets = torch.cat([start_list + offset_lengths, (start_list[-1] + offset_lengths[-1] + length_list[-1]).unsqueeze(0)])
    if len(tensor.shape) > 2:
        values = tensor.view(-1, *tensor.shape[2:])
    else:
        values = tensor.view(-1)
    is_contiguous = True
    orig_dim = tensor.shape[1]
    if torch.any(length_list[1:-1].ne(orig_dim)):
        is_contiguous = False
    if torch.any(offsets[1:-2].diff().ne(orig_dim)):
        is_contiguous = False
    if offsets[0] + length_list[0] != orig_dim:
        is_contiguous = False
    actual_max_seqlen = int(torch.max(lengths).item())
    min_seqlen = int(torch.min(lengths).item())
    if <MASK>:
        ret_nt = nested_view_from_values_offsets(values[offsets[0]:offsets[-1]], offsets - offsets[0], min_seqlen=min_seqlen, max_seqlen=actual_max_seqlen)
    else:
        ret_nt = nested_view_from_values_offsets_lengths(values, offsets, length_list, min_seqlen=min_seqlen, max_seqlen=actual_max_seqlen)
    return (ret_nt, offsets, None if is_contiguous else length_list)

def __init__(self, serialized_tensors: Mapping[base.Trackable, sharding_util.Shard], registered_savers: 'RegisteredSaversDict | None'=None, call_with_mapped_captures: 'MappedCapturesCallable | None'=None):
    """Specify a list of `SaveableObject`s to save and restore.

    Args:
      serialized_tensors: A dictionary mapping `Trackable` to a tensor dict,
        which maps checkpoint_key -> (slice_spec ->) -> Tensor/SaveSpec. The
        `Trackable` key is used to get the `restore_from_tensors` function,
        and may be `None` if the tensor is not meant to be restored.
      registered_savers: A dictionary mapping `registration.RegisteredSaver`
        namedtuples to a dictionary of named Trackables. The keys of the
        Trackable dictionary are string names that uniquely identify the
        Trackable in the checkpoint.
      call_with_mapped_captures: TODO
    """
    self._shardable_tensors_by_task: MutableMapping[device_lib.DeviceSpec, MutableSequence[sharding_util.ShardableTensor]] = {}
    self._keys_to_restore_fn: MutableMapping[TensorKeyAndSliceSpec, RestoreFn] = {}
    self._restore_fn_to_keys: MutableMapping[RestoreFn, MutableSequence[TensorKeyAndSliceSpec]] = {}
    unique_tasks = set()
    for (obj, tensor_dict) in serialized_tensors.items():
        restore_fn = _restore_noop if obj is None else obj._restore_from_tensors
        for (checkpoint_key, tensor_slice_dict) in tensor_dict.items():
            if not isinstance(tensor_slice_dict, dict):
                tensor_slice_dict = {'': tensor_slice_dict}
            for (slice_spec, tensor_save_spec) in tensor_slice_dict.items():
                tensor_value = None
                if not isinstance(tensor_save_spec, saveable_object.SaveSpec):
                    tensor_value = tensor_save_spec
                    tensor_save_spec = saveable_object.SaveSpec(tensor=tensor_value, slice_spec=slice_spec, name=checkpoint_key, dtype=tensor_save_spec.dtype, device=tensor_save_spec.device)
                if <MASK>:
                    raise ValueError('Received multiple tensors with the same checkpoint key and slice spec. This is invalid because one will overwrite the other in the checkpoint. This indicates a bug in the Checkpoint key-generation.')
                self._keys_to_restore_fn[checkpoint_key, slice_spec] = restore_fn
                self._restore_fn_to_keys.setdefault(restore_fn, []).append((checkpoint_key, slice_spec))
                if isinstance(tensor_save_spec.device, str):
                    device = device_lib.DeviceSpec.from_string(tensor_save_spec.device)
                    task = device_lib.DeviceSpec.from_string(saveable_object_util.set_cpu0(tensor_save_spec.device))
                else:
                    device = tensor_save_spec.device
                    task = device_lib.DeviceSpec.from_string(saveable_object_util.set_cpu0(device.to_string()))
                self._shardable_tensors_by_task.setdefault(task, []).append(sharding_util.ShardableTensor(_tensor_save_spec=tensor_save_spec, tensor=tensor_value, dtype=tensor_save_spec.dtype, device=device, name=tensor_save_spec.name, shape=None, slice_spec=slice_spec.strip(), checkpoint_key=checkpoint_key, trackable=obj))
                unique_tasks.add(saveable_object_util.set_cpu0(device.to_string()))
    self._num_unique_tasks = len(unique_tasks)
    self._registered_savers = {}
    if registered_savers:
        for (registered_name, trackables) in registered_savers.items():
            save_fn = _get_mapped_registered_save_fn(registration.get_save_function(registered_name), trackables, call_with_mapped_captures)
            restore_fn = _get_mapped_registered_restore_fn(registration.get_restore_function(registered_name), trackables, call_with_mapped_captures)
            self._registered_savers[registered_name] = (save_fn, restore_fn)

