def _prep_args_for_hash(self, result: list[object], args: Union[Mapping[str, object], Sequence[object], Iterable[object]], state: _CacheKeyState, id_hashed_objects: list[object]) -> None:
    """
        Translate the provided args into a form suitable for caching at FakeTensor
        dispatch, i.e., convert unhashable types like lists & dicts into tuples and
        convert FakeTensors into metadata. Raises _BypassDispatchCache to signal
        unsupported cases that should bypass caching.
        """
    from torch._higher_order_ops.auto_functionalize import FunctionalCallableWithEpilogue
    from torch._higher_order_ops.utils import FunctionalizeCtxWrapper
    if isinstance(args, (list, tuple, dict)):
        result.append(type(args))
        result.append(f'length_{len(args)}')
    if isinstance(args, dict):
        self._prep_args_for_hash(result, args.keys(), state, id_hashed_objects)
        self._prep_args_for_hash(result, args.values(), state, id_hashed_objects)
        return
    for arg in args:
        if isinstance(arg, FakeTensor):
            if not self.is_our_fake(arg):
                raise _BypassDispatchCache('not our fake')
            if arg.constant is not None:
                raise _BypassDispatchCache('constant attribute')
            if is_sparse_any(arg):
                raise _BypassDispatchCache(f'{arg.layout} tensor')
            metadata = extract_tensor_metadata(arg)
            metadata._flatten_into(result, self, state)
        elif isinstance(arg, Tensor):
            raise _BypassDispatchCache('non-fake tensor')
        elif isinstance(arg, SymInt):
            state.convert_sym_int(result, arg)
        elif isinstance(arg, (SymBool, SymFloat)):
            raise _BypassDispatchCache('symbolic shape')
        elif <MASK>:
            self._prep_args_for_hash(result, arg, state, id_hashed_objects)
        elif isinstance(arg, types.FunctionType):
            raise _BypassDispatchCache('function argument')
        elif isinstance(arg, torch.fx.GraphModule):
            result.append(type(arg))
            result.append(id(arg))
            id_hashed_objects.append(arg)
        elif isinstance(arg, FunctionalizeCtxWrapper):
            result.append(hash(arg))
            id_hashed_objects.append(arg.subgraph)
        elif isinstance(arg, FunctionalCallableWithEpilogue):
            result.append(type(arg))
            result.append(hash(arg))
            id_hashed_objects.append(arg.orig_callable)
        else:
            result.append(type(arg))
            result.append(arg)

def _common_getitem_elimination_pass(gm: torch.fx.GraphModule, graph_signature, module_call_graph):
    with gm._set_replace_hook(graph_signature.get_replace_hook()):
        for module in gm.modules():
            if not isinstance(module, torch.fx.GraphModule):
                continue
            node_id: dict[torch.fx.Node, str] = {}
            getitems: dict[str, torch.fx.Node] = {}
            for node in list(module.graph.nodes):
                if node.op == 'call_function' and node.target == operator.getitem:
                    (source, idx) = node.args
                    new_id = f'{node_id[source]}.{idx}'
                    if <MASK>:
                        node.replace_all_uses_with(getitems[new_id])
                        for entry in module_call_graph:
                            if entry.signature is not None:
                                entry.signature.replace_all_uses_with(node, getitems[new_id])
                        module.graph.erase_node(node)
                    else:
                        getitems[new_id] = node
                        node_id[node] = new_id
                else:
                    node_id[node] = node.name

def _quantile(self, qs: npt.NDArray[np.float64], interpolation: str) -> BaseMaskedArray:
    """
        Dispatch to quantile_with_mask, needed because we do not have
        _from_factorized.

        Notes
