    return self._maybe_mask_result(res, mask=out_mask)

def build_chunks(self):
    """Splits a GraphDef proto into smaller chunks."""
    proto = self._proto
    if not isinstance(proto, graph_pb2.GraphDef):
        raise TypeError('Can only split GraphDef type protos.')
    proto_size = proto.ByteSize()
    if proto_size < constants.max_size():
        return
    node_splitter = RepeatedMessageSplitter(proto, 'node', [ConstantNodeDefSplitter, LargeMessageSplitter], parent_splitter=self, fields_in_parent=[])
    function_splitter = RepeatedMessageSplitter(proto.library, ['function'], [FunctionDefSplitter], parent_splitter=self, fields_in_parent=['library'])
    library_size = proto.library.ByteSize()
    approx_node_size = proto_size - library_size
    if library_size > approx_node_size:
        library_size -= function_splitter.build_chunks()
        if library_size + approx_node_size > constants.max_size():
            approx_node_size -= node_splitter.build_chunks()
    else:
        approx_node_size -= node_splitter.build_chunks()
        if library_size + approx_node_size > constants.max_size():
            library_size -= function_splitter.build_chunks()
    if <MASK>:
        self.add_chunk(proto.library, ['library'], 1)
        proto.ClearField('library')

@classmethod
def profile_compile_time(cls, func: Any, phase_name: str, *args: Any, **kwargs: Any) -> Any:

    def skip() -> Any:
        return func(*args, **kwargs)
    if not cls.enabled:
        return skip()
    if cls.profiler is None:
        logger.error('profiler is not set')
        return
    frame_id = cls.get_frame()
    if cls.inside_profile_compile_time:
        cls.ignored_profile_runs += 1
        logger.info('profile_compile_time is requested for phase: %s, frame %s, while already in running phase: %s,frame %s, recursive call ignored', phase_name, frame_id, cls.current_phase, frame_id)
        return skip()
    if cls.frame_id_filter is not None:
        should_run = re.match(cls.frame_id_filter, frame_id) is not None
        if <MASK>:
            logger.info('profiling frame %s is skipped due to frame_id_filter %s', frame_id, cls.frame_id_filter)
            return skip()
    cls.inside_profile_compile_time = True
    cls.current_phase = phase_name
    logger.info('profiling frame %s', frame_id)
    work_result = cls.profiler.profile(func, *args, **kwargs)
    if cls.profiler.profile_result is not None:
        cls.success_profile_count += 1
    else:
        cls.failed_profile_count += 1
    cls._log_stats()
    cls.inside_profile_compile_time = False
    return work_result

