def make_autograd_impl(op: _ops.OpOverload, info: InfoProtocol) -> Callable:
    name: str = f'GeneratedBackwardFor_{op._namespace}_{op._opname}_{op._overloadname}'
    has_kwarg_only_args = utils.has_kwarg_only_args(op._schema)

    @dataclass
    class Metadata:
        keyset: _C.DispatchKeySet
        keyword_only_args: dict[str, Any]

    def forward_no_grad(*args):
        metadata = args[-1]
        args = args[:-1]
        with _C._AutoDispatchBelowAutograd():
            keyset = metadata.keyset
            kwargs = metadata.keyword_only_args
            result = op.redispatch(keyset & _C._after_autograd_keyset, *args, **kwargs)
            return result

    def forward(ctx, *args):
        metadata = args[-1]
        args = args[:-1]
        with _C._AutoDispatchBelowAutograd():
            keyset = metadata.keyset
            kwargs = metadata.keyword_only_args
            result = op.redispatch(keyset & _C._after_autograd_keyset, *args, **kwargs)
            if info._setup_context_fn:
                (args, kwargs) = utils.fill_defaults(op._schema, args, kwargs)
                if <MASK>:
                    info._setup_context_fn(ctx=ctx, inputs=args, keyword_only_inputs=kwargs, output=result)
                else:
                    info._setup_context_fn(ctx=ctx, inputs=args, output=result)
            return result

    def backward(ctx, *grads):
        if info._backward_fn:
            try:
                prev_needs_input_grad = ctx.needs_input_grad
                ctx.needs_input_grad = ctx.needs_input_grad[:-1]
                result = info._backward_fn(ctx, *grads)
            finally:
                ctx.needs_input_grad = prev_needs_input_grad
            if isinstance(result, tuple):
                return (*result, None)
            return (result, None)
        raise RuntimeError(f'Trying to backward through {op} but no autograd formula was registered. Please use register_autograd to add one.')
    Generated = type(name, (autograd.Function,), {'forward': staticmethod(forward), 'backward': staticmethod(backward)})
    schema = op._schema
    if any((utils.is_tensorlist_like_type(a.type) for a in (*schema.arguments, *schema.returns))):
        Generated = supports_tensorlist(Generated)

    def autograd_impl(keyset, *args, **keyword_only_args):
        if _C.is_grad_enabled() and _C._any_requires_grad(*args):
            result = Generated.apply(*args, Metadata(keyset, keyword_only_args))
        else:
            result = forward_no_grad(*args, Metadata(keyset, keyword_only_args))
        return result
    return autograd_impl

def _list_supported_ops():

    def emit_block(decls):
        return '\n.. rst-class:: codeblock-height-limiter\n\n::\n\n{}\n'.format(''.join((f'    {d}\n\n' for d in decls)))
    body = ''
    op_gathering_fns = (_get_tensor_ops, _get_nn_functional_ops, _get_torchscript_builtins, _get_global_builtins, _get_math_builtins)
    for fn in op_gathering_fns:
        (header, items) = fn()
        link_target = header.replace('`', '').replace('-', '').lower().replace(' ', '-')
        if <MASK>:
            section = f"{header}\n{'~' * len(header)}\n{items}\n"
        else:
            section = f"{header}\n{'~' * len(header)}\n{emit_block(items)}"
        section = f'.. _{link_target}:' + '\n\n' + section
        body += section
    return body

