def handle(self, *args, **options):
    verbosity = options['verbosity']
    app_label = options['app_label']
    migration_name = options['migration_name']
    check = options['check']
    try:
        apps.get_app_config(app_label)
    except LookupError as err:
        raise CommandError(str(err))
    loader = MigrationLoader(None)
    if app_label not in loader.migrated_apps:
        raise CommandError(f"App '{app_label}' does not have migrations.")
    try:
        migration = loader.get_migration_by_prefix(app_label, migration_name)
    except AmbiguityError:
        raise CommandError(f"More than one migration matches '{migration_name}' in app '{app_label}'. Please be more specific.")
    except KeyError:
        raise CommandError(f"Cannot find a migration matching '{migration_name}' from app '{app_label}'.")
    optimizer = MigrationOptimizer()
    new_operations = optimizer.optimize(migration.operations, migration.app_label)
    if len(migration.operations) == len(new_operations):
        if verbosity > 0:
            self.stdout.write('No optimizations possible.')
        return
    else:
        if verbosity > 0:
            self.stdout.write('Optimizing from %d operations to %d operations.' % (len(migration.operations), len(new_operations)))
        if check:
            sys.exit(1)
    migration.operations = new_operations
    writer = MigrationWriter(migration)
    migration_file_string = writer.as_string()
    if writer.needs_manual_porting:
        if <MASK>:
            raise CommandError('Migration will require manual porting but is already a squashed migration.\nTransition to a normal migration first: https://docs.djangoproject.com/en/%s/topics/migrations/#squashing-migrations' % get_docs_version())
        subclass = type('Migration', (migrations.Migration,), {'dependencies': migration.dependencies, 'operations': new_operations, 'replaces': [(migration.app_label, migration.name)]})
        optimized_migration_name = '%s_optimized' % migration.name
        optimized_migration = subclass(optimized_migration_name, app_label)
        writer = MigrationWriter(optimized_migration)
        migration_file_string = writer.as_string()
        if verbosity > 0:
            self.stdout.write(self.style.MIGRATE_HEADING('Manual porting required') + '\n  Your migrations contained functions that must be manually copied over,\n  as we could not safely copy their implementation.\n  See the comment at the top of the optimized migration for details.')
            if shutil.which('black'):
                self.stdout.write(self.style.WARNING('Optimized migration couldn\'t be formatted using the "black" command. You can call it manually.'))
    with open(writer.path, 'w', encoding='utf-8') as fh:
        fh.write(migration_file_string)
    run_formatters([writer.path], stderr=self.stderr)
    if verbosity > 0:
        self.stdout.write(self.style.MIGRATE_HEADING(f'Optimized migration {writer.path}'))

def _check_helper(self, device, dtype, op, variant, check, *, check_forward_ad=False, check_backward_ad=True, check_batched_grad=None, check_batched_forward_grad=False):
    assert check in ('gradcheck', 'bwgrad_bwgrad', 'fwgrad_bwgrad')
    if variant is None:
        self.skipTest('Skipped! Variant not implemented.')
    if not op.supports_dtype(dtype, torch.device(device).type):
        self.skipTest(f'Skipped! {op.name} does not support dtype {str(dtype)}')

    def is_inplace(variant):
        if hasattr(variant, '__wrapped__'):
            return variant.__wrapped__ is op.get_inplace()
        return variant is op.get_inplace()
    include_conjugated_inputs = op.test_conjugated_samples and dtype.is_complex
    samples = op.sample_inputs(device, dtype, requires_grad=True, include_conjugated_inputs=include_conjugated_inputs, small_inputs_only=TEST_WITH_SLOW_GRADCHECK)
    for sample in samples:
        if sample.broadcasts_input and is_inplace(variant):
            continue
        all_args = None
        if is_iterable_of_tensors(sample.input):
            all_args = chain(sample.input, sample.args, sample.kwargs.values())
        else:
            all_args = tuple(chain((sample.input,), sample.args, sample.kwargs.values()))
        gradcheck_args = tuple((x for x in all_args if isinstance(x, torch.Tensor) and x.requires_grad))
        for t in gradcheck_args:
            self.assertIsNone(t.grad, 'A sampled input has a gradient before running autograd. This usually means that (at least) one input tensor is reused across different SampleInputs. Please create a new tensor for each SampleInput.')

        def _input_recomposition_helper(inputs, inp, input_idx):
            if is_iterable_of_tensors(inp):
                tensor_list = []
                for x in inp:
                    if isinstance(x, torch.Tensor) and x.requires_grad:
                        tensor_list.append(inputs[input_idx])
                        input_idx = input_idx + 1
                    else:
                        tensor_list.append(x)
                return (tensor_list, input_idx)
            elif isinstance(inp, torch.Tensor) and inp.requires_grad:
                return (inputs[input_idx], input_idx + 1)
            else:
                return (inp, input_idx)

        def fn(*inputs):
            positional_args = []
            input_idx = 0
            (inp, input_idx) = _input_recomposition_helper(inputs, sample.input, input_idx)
            positional_args.append(inp)
            for x in sample.args:
                (inp, input_idx) = _input_recomposition_helper(inputs, x, input_idx)
                positional_args.append(inp)
            kwargs = {}
            for (k, v) in sample.kwargs.items():
                (inp, input_idx) = _input_recomposition_helper(inputs, v, input_idx)
                kwargs[k] = inp
            output = op.gradcheck_wrapper(variant, *positional_args, **kwargs)
            if sample.output_process_fn_grad is not None:
                return sample.output_process_fn_grad(output)
            return output
        if check == 'gradcheck':
            if <MASK>:
                check_batched_grad = op.check_batched_grad
            self.assertTrue(gradcheck(fn, gradcheck_args, check_batched_grad=check_batched_grad, check_grad_dtypes=True, nondet_tol=op.gradcheck_nondet_tol, fast_mode=op.gradcheck_fast_mode, check_forward_ad=check_forward_ad, check_backward_ad=check_backward_ad, check_undefined_grad=True, check_batched_forward_grad=check_batched_forward_grad))
        elif check in ('bwgrad_bwgrad', 'fwgrad_bwgrad'):
            self.assertFalse(check_forward_ad, msg='Cannot run forward AD check for gradgradcheck')
            for gen_non_contig_grad_outputs in (False, True):
                kwargs = {'gen_non_contig_grad_outputs': gen_non_contig_grad_outputs, 'check_batched_grad': op.check_batched_gradgrad, 'check_grad_dtypes': True, 'nondet_tol': op.gradcheck_nondet_tol, 'fast_mode': op.gradcheck_fast_mode}
                if check == 'fwgrad_bwgrad':
                    kwargs['check_fwd_over_rev'] = True
                    kwargs['check_rev_over_rev'] = False
                    kwargs['check_batched_grad'] = False
                    kwargs['check_undefined_grad'] = False
                self.assertTrue(gradgradcheck(fn, gradcheck_args, **kwargs))
        else:
            self.assertTrue(False, msg='Unknown check requested!')

def get_func_graphs(op):
    """Returns `FuncGraph`s for the input op branches.

  Args:
    op: The If or Case Operation.

  Returns:
    A tuple of the `FuncGraph`s of the then_branch and else_branch (all branches
    for Case).
  """

    def _get_func_graph_for_branch(name_attr_list, cached_attr_name=None):
        """Generates and returns a FuncGraph for the given branch."""
        func_graph = None
        if cached_attr_name is not None:
            func_graph = getattr(op, cached_attr_name, None)
        inputs = op.inputs[1:]
        if func_graph is None:
            input_shapes = [t.shape for t in inputs]
            func_graph = util.get_func_graph(op, input_shapes, name_attr_list.name)
        for (external_t, internal_t) in zip(inputs, func_graph.inputs):
            handle_data_util.copy_handle_data(external_t, internal_t)
        func_graph.function_captures.reset_captures(inputs, func_graph.inputs)
        func_graph._forward_cond = op
        return func_graph
    if op.type in ['If', 'StatelessIf']:
        return (_get_func_graph_for_branch(op.get_attr('then_branch'), '_true_graph'), _get_func_graph_for_branch(op.get_attr('else_branch'), '_false_graph'))
    elif <MASK>:
        return [_get_func_graph_for_branch(branch_fn, '_branch_graph_{}'.format(i)) for (i, branch_fn) in enumerate(op.get_attr('branches'))]
    else:
        raise ValueError('Unsupported op type: {}'.format(op.type))

def decorator(f):
    if tf_inspect.isclass(f):
        raise ValueError('`run_v2_only` only supports test methods.')

    def decorated(self, *args, **kwargs):
        if <MASK>:
            self.skipTest('Test is only compatible with v2')
        return f(self, *args, **kwargs)
    return decorated

def get_input_params(distribution_strategy, num_samples, steps, batch_size, mode=None):
    """Calculate the number of batches and steps/steps_per_epoch.

  Args:
    distribution_strategy: The DistributionStrategy used to compile the model.
    num_samples: The number of samples from which we determine the batch size
      and steps.
    steps:  The specified number of steps.
    batch_size: The specified batch_size.
    mode: ModeKey representing whether input will be used for training,
      evaluation, or prediction. This is used to relax the constraints on
      consuming all the training samples to keep compatibility till we support
      partial batches. If none, then partial batches are not allowed.

  Returns:
    steps: The steps or steps_per_epoch argument depending on if a user is
        calling `fit`, `evaluate` or `predict`. If the is_training flag is set
        we don't require the number of samples to be used completely.
    batch_size: The batch size to be used in model iterations.

  Raises:
    ValueError: If the number of batches or steps evaluates to 0.

  """
    use_per_replica_batch = not dist_utils.global_batch_size_supported(distribution_strategy)
    if context.executing_eagerly():
        allow_partial_batch = mode != ModeKeys.TRAIN or not backend.is_tpu_strategy(distribution_strategy)
    else:
        allow_partial_batch = mode == ModeKeys.TRAIN or ((mode == ModeKeys.PREDICT or mode == ModeKeys.TEST) and backend.is_tpu_strategy(distribution_strategy))
    if steps is None:
        if batch_size is None:
            global_batch_size = min(num_samples, 32)
        else:
            global_batch_size = batch_size
            if use_per_replica_batch:
                global_batch_size *= distribution_strategy.num_replicas_in_sync
        if allow_partial_batch:
            steps = np.ceil(num_samples / global_batch_size).astype(int)
        else:
            if num_samples % global_batch_size:
                raise ValueError('The number of samples %s is not divisible by batch size %s.' % (num_samples, global_batch_size))
            steps = num_samples // global_batch_size
    elif batch_size is None:
        if <MASK>:
            raise ValueError('The number of samples %s is not divisible by steps %s. Please change the number of steps to a value that can consume all the samples' % (num_samples, steps))
        global_batch_size = num_samples // steps
    else:
        global_batch_size = batch_size
        if use_per_replica_batch:
            global_batch_size *= distribution_strategy.num_replicas_in_sync
        min_num_samples = global_batch_size * steps
        if allow_partial_batch:
            min_num_samples = global_batch_size * (steps - 1) + 1 if steps > 1 else 0
        if num_samples < min_num_samples:
            raise ValueError('Number of samples %s is less than samples required for specified batch_size %s and steps %s' % (num_samples, global_batch_size, steps))
    if use_per_replica_batch:
        if global_batch_size % distribution_strategy.num_replicas_in_sync:
            raise ValueError('The batch size (%s) could not be sharded evenly across the sync replicas (%s) in the distribution strategy.' % (global_batch_size, distribution_strategy.num_replicas_in_sync))
        batch_size = global_batch_size // distribution_strategy.num_replicas_in_sync
    else:
        batch_size = global_batch_size
    return (steps, batch_size)

def pretty_print(self, pp: PatternPrettyPrinter) -> str:
    args = [self.fns_repr(), *(pp.pretty_print(x) for x in self.args), *[f'{k}={pp.pretty_print(v)}' for (k, v) in self.kwargs.items()]]
    if <MASK>:
        args.append('_users=MULTIPLE')
    elif self.users != 1:
        args.append(f'_users={self.users}')
    joiner_str = ', '
    return f'{self.__class__.__name__}({joiner_str.join(args)})'

def is_allowlisted(o, check_call_override=True, allow_namedtuple_subclass=False):
    """Checks whether an entity is allowed for use in graph mode.

  Examples of allowed entities include all members of the tensorflow
  package.

  Args:
    o: A Python entity.
    check_call_override: Reserved for internal use. When set to `False`, it
      disables the rule according to which classes are allowed if their
      __call__ method is allowed.
    allow_namedtuple_subclass: Reserved for internal use. When `True`,
      namedtuple subclasses are not allowed.

  Returns:
    Boolean
  """
    if isinstance(o, functools.partial):
        m = functools
    else:
        m = tf_inspect.getmodule(o)
    if hasattr(m, '__name__'):
        for rule in config.CONVERSION_RULES:
            action = rule.get_action(m)
            if action == config.Action.CONVERT:
                logging.log(2, 'Not allowed: %s: %s', o, rule)
                return False
            elif <MASK>:
                logging.log(2, 'Allowlisted: %s: %s', o, rule)
                return True
    if hasattr(o, '__code__') and tf_inspect.isgeneratorfunction(o):
        logging.log(2, 'Allowlisted: %s: generator functions are not converted', o)
        return True
    if check_call_override and (not tf_inspect.isclass(o)) and hasattr(o, '__call__'):
        if type(o) != type(o.__call__) and is_allowlisted(o.__call__):
            logging.log(2, 'Allowlisted: %s: object __call__ allowed', o)
            return True
    owner_class = None
    if tf_inspect.ismethod(o):
        owner_class = inspect_utils.getmethodclass(o)
        if owner_class is tf_method_target.TfMethodTarget:
            owner_class = o.__self__.target_class
        if owner_class is not None:
            if issubclass(owner_class, unittest.TestCase):
                logging.log(2, 'Allowlisted: %s: method of TestCase subclass', o)
                return True
            owner_class = inspect_utils.getdefiningclass(o, owner_class)
            if is_allowlisted(owner_class, check_call_override=False, allow_namedtuple_subclass=True):
                logging.log(2, 'Allowlisted: %s: owner is allowed %s', o, owner_class)
                return True
    if inspect_utils.isnamedtuple(o):
        if allow_namedtuple_subclass:
            if not any((inspect_utils.isnamedtuple(base) for base in o.__bases__)):
                logging.log(2, 'Allowlisted: %s: named tuple', o)
                return True
        else:
            logging.log(2, 'Allowlisted: %s: named tuple or subclass', o)
            return True
    logging.log(2, 'Not allowed: %s: default rule', o)
    return False

def get_bwd_send_ops(self, bwd_chunk_id: int) -> list[dist.P2POp]:
    """
        Get the gradient send ops for current stage's backward.
        """
    if <MASK>:
        return []
    self._check_chunk_id(bwd_chunk_id)
    if self.grad_send_info is None:
        self.grad_send_info = self._create_grad_send_info(self.args_recv_info[0])
    ops: list[dist.P2POp] = []
    grads_input = self.bwd_cache.pop(bwd_chunk_id)
    for (grad, grad_recv_stage) in zip(grads_input, self.grad_send_info):
        if isinstance(grad, torch.Tensor) and grad_recv_stage is not None:
            logger.debug('%s Sending gradient to Stage %s: %s', self.log_prefix, grad_recv_stage, grad.size())
            peer_rank = self.stage_index_to_group_rank[grad_recv_stage]
            peer_global_rank = peer_rank if self.group is None else dist.get_global_rank(self.group, peer_rank)
            ops.append(dist.P2POp(dist.isend, grad, peer_global_rank, self.group))
        elif not (grad is None and grad_recv_stage is None):
            raise RuntimeError(f'[{self.stage_index}] for chunk {bwd_chunk_id} has gradients {grad} and is expecting to send gradients to stage {grad_recv_stage}')
    return ops

def call_function(self, target: torch.fx.node.Target, args: tuple[Argument, ...], kwargs: dict[str, Argument]) -> ProxyValue:
    meta = NodeMetadata(self.node.meta)
    if target == operator.getitem:
        (value, key) = args
        return self.callback.call_getitem(value, key, meta)
    elif getattr(target, '__module__', None) in {'_operator', 'builtins', 'math'}:
        assert callable(target)
        return self.callback.call_sym(target, args, meta)
    elif target in _TORCH_SYM_OPS:
        assert callable(target)
        return self.callback.call_sym(target, args, meta)
    elif <MASK>:
        return self.callback.call_operator(target, args, kwargs, meta)
    elif target == torch.ops.higher_order.cond:
        (pred, true_fn, false_fn, inputs) = args
        return self.callback.call_cond(pred, true_fn, false_fn, inputs, meta)
    elif target == torch.ops.higher_order.map_impl:
        (f, mapped_args, operands) = args
        return self.callback.call_map(f, mapped_args, operands, meta)
    elif isinstance(target, torch._ops.HigherOrderOperator):
        return self.callback._fx('call_function', target, args, kwargs, meta)
    else:
        raise ExportPassBaseError(f'Unsupported target type: {target}')

@no_type_check
def _init_ignored_module_states(state: _FSDPState, module: nn.Module, ignored_modules: Optional[Iterable[torch.nn.Module]], ignored_states: Union[Optional[Iterable[torch.nn.Parameter]], Optional[Iterable[torch.nn.Module]]]=None) -> _FSDPState:
    if ignored_modules is not None and ignored_states is not None:
        raise ValueError('Cannot pass both ignored_modules and ignored_states at the same time. Please just pass ignored_states.')
    ignored_parameters = None
    passed_as_ignored_states = ignored_states is not None
    if <MASK>:
        ignored_states_list = list(ignored_states)
        _check_ignored_states(ignored_states_list, True)
    else:
        ignored_states_list = []
        _check_ignored_states(list(ignored_modules) if ignored_modules is not None else [], False)
    if len(ignored_states_list) > 0:
        if isinstance(ignored_states_list[0], nn.Parameter):
            ignored_parameters = ignored_states_list
        else:
            ignored_modules = ignored_states_list
    state._ignored_modules = _get_ignored_modules(module, ignored_modules)
    state._ignored_params = _get_ignored_params(module, state._ignored_modules, ignored_parameters)
    state._ignored_buffer_names = _get_ignored_buffer_names(module, state._ignored_modules)
    return state

def __init__(self, params: list[Tensor], lr: float=0.001, betas: tuple[float, float]=(0.9, 0.999), eps: float=1e-08, weight_decay: float=0.0, foreach: bool=False, maximize: bool=False, _allow_empty_param_list: bool=False):
    _scripted_functional_optimizer_deprecation_warning(stacklevel=2)
    if not 0.0 <= lr:
        raise ValueError(f'Invalid learning rate: {lr}')
    if not 0.0 <= eps:
        raise ValueError(f'Invalid epsilon value: {eps}')
    if <MASK>:
        raise ValueError(f'Invalid beta parameter at index 0: {betas[0]}')
    if not 0.0 <= betas[1] < 1.0:
        raise ValueError(f'Invalid beta parameter at index 1: {betas[1]}')
    if not 0.0 <= weight_decay:
        raise ValueError(f'Invalid weight_decay value: {weight_decay}')
    self.defaults = {'lr': lr, 'eps': eps, 'beta1': betas[0], 'beta2': betas[1], 'weight_decay': weight_decay}
    self.foreach = foreach
    self.maximize = maximize
    self.state = torch.jit.annotate(dict[torch.Tensor, dict[str, torch.Tensor]], {})
    if len(params) == 0 and (not _allow_empty_param_list):
        raise ValueError('optimizer got an empty parameter list')
    self.param_group = {'params': params}

@functools.cache
def check_mingw_win32_flavor(compiler: str) -> str:
    """
    Check if MinGW `compiler` exists and return it's flavor (win32 or posix).
    """
    try:
        out = subprocess.check_output([compiler, '-v'], stderr=subprocess.STDOUT, text=True)
    except FileNotFoundError as e:
        raise RuntimeError(f'Compiler: {compiler} is not found.') from e
    except Exception as e:
        raise RuntimeError(f'Failed to run {compiler} -v') from e
    flavor: str | None = None
    for line in out.splitlines():
        if 'Thread model' in line:
            flavor = line.split(':', 1)[-1].strip().lower()
    if flavor is None:
        raise RuntimeError(f'Cannot determine the flavor of {compiler} (win32 or posix). No Thread model found in {compiler} -v')
    if <MASK>:
        raise RuntimeError(f'Only win32 and pofix flavor of {compiler} is supported. The flavor is {flavor}')
    return flavor

def MAKE_FUNCTION(self, inst: Instruction) -> None:
    flags = inst.arg
    if sys.version_info < (3, 11):
        fn_name = self.pop()
    code = self.pop()
    if sys.version_info >= (3, 11):
        assert hasattr(code.value, 'co_qualname')
        fn_name = ConstantVariable.create(value=code.value.co_qualname)
    defaults = None
    closure = None
    annotations = None
    kwdefaults = None
    if sys.version_info < (3, 13):
        if flags is not None:
            if flags & 8:
                closure = self.pop()
            if flags & 4:
                annotations = self.pop()
            if flags & 2:
                kwdefaults = self.pop()
            if <MASK>:
                defaults = self.pop()
    self.push(NestedUserFunctionVariable(fn_name, code, self.f_globals, defaults, kwdefaults, annotations, closure))

def assign_on_device(self, device, value):
    if <MASK>:
