def call_function(self, tx: 'InstructionTranslator', args, kwargs):
    if <MASK>:
        unimplemented('random.Random() with > 1 arg')
    elif kwargs:
        unimplemented('random.Random() with kwargs')
    seed = variables.ConstantVariable.create(None) if len(args) == 0 else args[0]
    return RandomVariable(seed=seed, mutation_type=variables.base.ValueMutationNew())

def list_logical_devices(self, device_type=None):
    """Return logical devices."""
    self.ensure_initialized()
