    return [d for d in self._logical_devices if d.device_type == device_type]

@register_decomposition([aten.arange.start_step, aten.arange.start_out])
@out_wrapper()
def arange(start: NumberType=0, end: Optional[NumberType]=None, step: NumberType=1, *, dtype: Optional[torch.dtype]=None, layout: torch.layout=torch.strided, device: Optional[DeviceLikeType]=None, pin_memory: bool=False, requires_grad: bool=False) -> TensorLikeType:
    utils.check_layout(layout)
    utils.check_pin_memory(pin_memory)
    device = torch.device(utils.device_or_default(device))
    assert not isinstance(start, complex)
    assert not isinstance(end, complex)
    assert not isinstance(step, complex)
    if end is None:
        end = start
        start = 0
    torch._check(step != 0, lambda : 'step must be nonzero')
    if step > 0:
        torch._check(end >= start, lambda : 'upper bound and lower bound inconsistent with step sign')
    elif step < 0:
        torch._check(end <= start, lambda : 'upper bound and lower bound inconsistent with step sign')

    def is_finite(x):
        return not isinstance(x, FloatWithoutSymFloat) or math.isfinite(x)
    torch._check(is_finite(start) and is_finite(end), lambda : f'unsupported range: {start} -> {end}')
    torch._check(is_finite(step), lambda : f'step must be finite but got {step}')
    args = (start, end, step)
    integer_args = builtins.all((isinstance(arg, IntLike) for arg in args))
    if dtype is None:
        dtype = torch.int64 if integer_args else torch.get_default_dtype()
    is_integer = utils.is_integer_dtype(dtype)
    if is_integer or integer_args:
        xstart = sym_int(start)
        xend = sym_int(end)
        xstep = sym_int(step)
    if dtype == torch.int64 or integer_args:
        sgn = bool(xstep > 0) - bool(xstep < 0)
        length = (xend - xstart + xstep - sgn) // xstep
    else:
        length = math.ceil((end - start) / step)
    if is_integer:
        return prims.iota(length, start=xstart, step=xstep, dtype=dtype, device=device, requires_grad=requires_grad)
    index = prims.iota(length, start=0, step=1, dtype=torch.int64, device=device, requires_grad=False)
    computation_dtype = torch.long if integer_args else utils.get_acc_type(dtype, device)
    index = _maybe_convert_to_dtype(index, computation_dtype)
    result = start + step * index
    result = _maybe_convert_to_dtype(result, dtype)
    if <MASK>:
        result.requires_grad_(True)
    return result

def set_tensor(module: 'torch.nn.Module', name: str, tensor: torch.Tensor) -> None:
    if not isinstance(module, torch.nn.Module):
        raise TypeError(f'{module} is not an instance of torch.nn.Module')
    if not isinstance(tensor, torch.Tensor) and tensor is not None:
        raise TypeError(f'{tensor} is not an instance of torch.Tensor')
    if '.' in name:
        raise KeyError('tensor name can\'t contain "."')
    if name == '':
        raise KeyError('tensor name can\'t be empty string ""')
    if <MASK>:
        module._parameters[name] = tensor
    elif name in module._buffers:
        module._buffers[name] = tensor
    else:
        setattr(module, name, tensor)

def __get__(self, instance, cls=None):
    """
        Get the related instance through the forward relation.

        With the example above, when getting ``child.parent``:

        - ``self`` is the descriptor managing the ``parent`` attribute
        - ``instance`` is the ``child`` instance
        - ``cls`` is the ``Child`` class (we don't need it)
        """
    if instance is None:
        return self
    try:
        rel_obj = self.field.get_cached_value(instance)
    except KeyError:
        rel_obj = None
        has_value = None not in self.field.get_local_related_value(instance)
        if <MASK>:
            model = self.field.model
            for (current_instance, ancestor) in _traverse_ancestors(model, instance):
                if ancestor:
                    rel_obj = self.field.get_cached_value(ancestor, default=None)
                    if rel_obj is not None:
                        break
        if rel_obj is None and has_value:
            instance._state.fetch_mode.fetch(self, instance)
            return self.field.get_cached_value(instance)
        self.field.set_cached_value(instance, rel_obj)
    if rel_obj is None and (not self.field.null):
        raise self.RelatedObjectDoesNotExist('%s has no %s.' % (self.field.model.__name__, self.field.name))
    else:
        return rel_obj

def _copy_cookie_jar(jar):
    if <MASK>:
        return None
    if hasattr(jar, 'copy'):
        return jar.copy()
    new_jar = copy.copy(jar)
    new_jar.clear()
    for cookie in jar:
        new_jar.set_cookie(copy.copy(cookie))
    return new_jar

def _reshape_method_wrapper(a, *newshape, **kwargs):
    order = kwargs.pop('order', 'C')
    if <MASK>:
        raise ValueError('Unsupported arguments: {}'.format(kwargs.keys()))
    if len(newshape) == 1 and (not isinstance(newshape[0], int)):
        newshape = newshape[0]
    return reshape(a, newshape, order=order)

def getcallprotoargument(rout, cb_map={}):
    r = getmultilineblock(rout, 'callprotoargument', comment=0)
    if <MASK>:
        return r
    if hascallstatement(rout):
        outmess('warning: callstatement is defined without callprotoargument\n')
        return
    from .capi_maps import getctype
    (arg_types, arg_types2) = ([], [])
    if l_and(isstringfunction, l_not(isfunction_wrap))(rout):
        arg_types.extend(['char*', 'size_t'])
    for n in rout['args']:
        var = rout['vars'][n]
        if isintent_callback(var):
            continue
        if n in cb_map:
            ctype = cb_map[n] + '_typedef'
        else:
            ctype = getctype(var)
            if l_and(isintent_c, l_or(isscalar, iscomplex))(var):
                pass
            elif isstring(var):
                pass
            elif not isattr_value(var):
                ctype = ctype + '*'
            if isstring(var) or isarrayofstrings(var) or isstringarray(var):
                arg_types2.append('size_t')
        arg_types.append(ctype)
    proto_args = ','.join(arg_types + arg_types2)
    if not proto_args:
        proto_args = 'void'
    return proto_args

def deconv_output_length(input_length, filter_size, padding, output_padding=None, stride=0, dilation=1):
    """Determines output length of a transposed convolution given input length.

  Args:
      input_length: Integer.
      filter_size: Integer.
      padding: one of `"same"`, `"valid"`, `"full"`.
      output_padding: Integer, amount of padding along the output dimension. Can
        be set to `None` in which case the output length is inferred.
      stride: Integer.
      dilation: Integer.

  Returns:
      The output length (integer).
  """
    assert padding in {'same', 'valid', 'full'}
    if input_length is None:
        return None
    filter_size = filter_size + (filter_size - 1) * (dilation - 1)
    if output_padding is None:
        if <MASK>:
            length = input_length * stride + max(filter_size - stride, 0)
        elif padding == 'full':
            length = input_length * stride - (stride + filter_size - 2)
        elif padding == 'same':
            length = input_length * stride
    else:
        if padding == 'same':
            pad = filter_size // 2
        elif padding == 'valid':
            pad = 0
        elif padding == 'full':
            pad = filter_size - 1
        length = (input_length - 1) * stride + filter_size - 2 * pad + output_padding
    return length

@no_type_check
def _root_pre_forward(state: _FSDPState, module: nn.Module, args, kwargs) -> None:
    """
    Runs pre-forward logic specific to the root FSDP instance, which should run
    before any individual module's pre-forward. This starts with an attempt at
    lazy initialization (which only runs non-vacuously once). Otherwise, if
    this is called on a non-root FSDP instance, then it returns directly.

    Args:
        module (nn.Module): Module for which this logic tries to run. It may or
            may not be the root. If not, then this method does not do anything.
    """
    with torch.profiler.record_function('FullyShardedDataParallel._root_pre_forward'):
        _lazy_init(state, module)
        _p_assert(state._is_root is not None, 'Expects a root FSDP to have been set')
        if not state._is_root:
            if _is_composable(state):
                return _root_cast_forward_input(state, module, args, kwargs)
            return (args, kwargs)
        handle = state._handle
        if <MASK>:
            should_cast_buffers_to_full_prec = handle._force_full_precision
        else:
            handles = traversal_utils._get_fsdp_handles(module)
            should_cast_buffers_to_full_prec = any((handle._force_full_precision for handle in handles))
        if should_cast_buffers_to_full_prec:
            _cast_buffers_to_dtype_and_device(buffers=dict(module.named_buffers()).values(), buffer_dtypes=list(state._buffer_name_to_orig_dtype.values()), device=state.compute_device)
            state._needs_buffer_dtype_restore_check = True
        elif getattr(state, '_needs_buffer_dtype_restore_check', False):
            (buffers, buffer_dtypes_for_computation) = _get_buffers_and_dtypes_for_computation(state, module)
            if len(buffers) > 0 and len(buffer_dtypes_for_computation) > 0:
                if any((buffer.dtype != buffer_dtype_for_computation for (buffer, buffer_dtype_for_computation) in zip(buffers, buffer_dtypes_for_computation))):
                    _cast_buffers_to_dtype_and_device(buffers, buffer_dtypes_for_computation, state.compute_device)
            state._needs_buffer_dtype_restore_check = False
        if state.forward_prefetch:
            handles = [fsdp_state._handle for fsdp_state in state._all_fsdp_states if fsdp_state._handle]
            for handle in handles:
                handle._needs_pre_forward_unshard = True
                handle._prefetched = False
        _wait_for_computation_stream(state._device_handle.current_stream(), state._unshard_stream, state._pre_unshard_stream)
        _reset_flat_param_grad_info_if_needed(state._all_handles)
        with torch.profiler.record_function('FullyShardedDataParallel._to_kwargs'):
            (args_tuple, kwargs_tuple) = _to_kwargs(args, kwargs, state.compute_device, False)
        args = args_tuple[0] if args_tuple else tuple()
        kwargs = kwargs_tuple[0] if kwargs_tuple else {}
        return _root_cast_forward_input(state, module, args, kwargs)

def __init__(self, allowed_extensions=None, message=None, code=None):
    if allowed_extensions is not None:
        allowed_extensions = [allowed_extension.lower() for allowed_extension in allowed_extensions]
    self.allowed_extensions = allowed_extensions
    if message is not None:
        self.message = message
    if <MASK>:
        self.code = code

def _as_shape_list(shapes, dtypes, unknown_dim_allowed=False, unknown_rank_allowed=False):
    """Convert shapes to a list of tuples of int (or None)."""
