def run(self, fn, args=None, kwargs=None):
    """Runs `fn` with `args` and `kwargs` on all jobs.

    Args:
      fn: The function to be run.
      args: Optional positional arguments to be supplied in `fn`.
      kwargs: Optional keyword arguments to be supplied in `fn`.

    Returns:
      A list of return values.
    """
    _check_initialization()
    multi_process_lib.Process()
    if <MASK>:
        self._start()
    fn = dill.dumps(fn, dill.HIGHEST_PROTOCOL)
    for conn in self._conn.values():
        conn.send((fn, args or [], kwargs or {}))
    process_statuses = []
    total_timeout = 300
    start_time = time.time()
    for ((task_type, task_id), conn) in self._conn.items():
        remaining_time = total_timeout - (time.time() - start_time)
        if remaining_time <= 0:
            raise RuntimeError(f'Total timeout of {total_timeout} s exceeded while waiting for processes')
        logging.info('Waiting for the result from %s-%d (timeout: %.1fs)', task_type, task_id, remaining_time)
        result_container = []
        error_container = []

        def recv_with_timeout():
            try:
                result = conn.recv()
                result_container.append(result)
            except EOFError as e:
                error_container.append(('eof', e))
            except Exception as e:
                error_container.append(('error', e))
        recv_thread = threading.Thread(target=recv_with_timeout)
        recv_thread.daemon = True
        recv_thread.start()
        recv_thread.join(timeout=min(remaining_time, 120))
        if recv_thread.is_alive():
            logging.info('[%s-%d] Timeout waiting for process result after %d s', task_type, task_id, min(remaining_time, 120))
            with self._runner._process_lock if self._runner else threading.Lock():
                if self._runner and (task_type, task_id) in self._runner._processes:
                    process = self._runner._processes[task_type, task_id]
                    logging.info('[%s-%d] Process state: exitcode=%d, pid=%d', task_type, task_id, process.exitcode, process.pid)
            raise RuntimeError(f'Timeout waiting for {task_type}-{task_id} after {min(remaining_time, 120):.1f}s. This often indicates a subprocess is stuck in initialization or pipe reading. Try increasing Docker container resources or check for deadlocks.')
        if error_container:
            (error_type, error) = error_container[0]
            if error_type == 'eof':
                self.shutdown()
                raise RuntimeError('Unexpected EOF. Worker process may have died. Please report a bug')
            else:
                raise error
        if result_container:
            process_statuses.append(result_container[0])
        else:
            raise RuntimeError(f'No result received from {task_type}-{task_id}')
    return_values = []
    for process_status in process_statuses:
        assert isinstance(process_status, _ProcessStatusInfo)
        if not process_status.is_successful:
            six.reraise(*process_status.exc_info)
        if process_status.return_value is not None:
            return_values.append(process_status.return_value)
    return return_values

@classmethod
def eval(cls, p: sympy.Expr, q: sympy.Expr) -> Optional[sympy.Expr]:
    if q.is_zero:
        raise ZeroDivisionError('Modulo by zero')
    if p is S.Zero or p in (q, -q) or q == 1:
        return S.Zero
    if q.is_Number and p.is_Number:
        return p % q
    if q.is_Number and q == 2:
        if p.is_even:
            return S.Zero
        if p.is_odd:
            return S.One
    r = p / q
    if r.is_integer:
        return S.Zero
    less = p < q
    if <MASK>:
        return p
    if sympy.Mod(p, q) == 0:
        return S.Zero
    return None

