def split_const_subgraphs(module: Union[torch.nn.Module, torch.fx.GraphModule], skip_folding_node_fn: Optional[Callable[[torch.fx.Node], bool]]=None, device_for_folded_attrs: str='cpu') -> FoldedGraphModule:
    """
    Looks through `module` for any nodes that have all constant attribute inputs
    and separates them out into their own constant subgraph, and returns a
    FoldedGraphModule which runs that constant subgraph on the first run to set
    attributes on the module prior to running the non-constant portion of the
    graph.
    """
    import sympy
    if not isinstance(module, torch.fx.GraphModule):
        mod_traced = torch.fx.symbolic_trace(module)
    else:
        mod_traced = module
    const_nodes: set[torch.fx.Node] = set()
    found_const_folding = False
    for node in mod_traced.graph.nodes:
        if node.op in {'placeholder', 'output'}:
            continue
        if node.op != 'get_attr' and (not set(node.all_input_nodes).issubset(const_nodes)):
            continue
        if skip_folding_node_fn and skip_folding_node_fn(node):
            continue
        if node.is_impure():
            continue
        if isinstance(node.kwargs.get('fill_value', None), sympy.Expr):
            continue
        const_nodes.add(node)
        if node.op != 'get_attr':
            found_const_folding = True
    if not found_const_folding:
        return FoldedGraphModule(mod_traced, mod_traced.graph)

    def mod_partition(node: torch.fx.Node):
        return 0 if node in const_nodes else 1
    split = split_module(mod_traced, module, mod_partition)
    (const_mod_name, non_const_mod_name) = ('submod_0', 'submod_1')
    (const_gm, non_const_gm) = (split.submod_0, getattr(split, non_const_mod_name, None))
    for node in non_const_gm.graph.nodes if non_const_gm else []:
        if node.op == 'call_module':
            setattr(split, node.target, getattr(non_const_gm, node.target))
    for node in const_gm.graph.nodes:
        if node.op == 'call_module':
            setattr(split, node.target, getattr(const_gm, node.target))
    call_const_gm_args = None
    for node in split.graph.nodes:
        if node.op == 'call_module':
            if node.target == const_mod_name:
                call_const_gm_args = node.args
                break
    assert call_const_gm_args is not None
    root_const_gm = torch.fx.GraphModule(split, const_gm.graph)
    ph_idx = 0
    for node in root_const_gm.graph.nodes:
        if node.op == 'output':
            multiple_outputs = isinstance(node.args[0], tuple)
            continue
        if node.op != 'placeholder':
            continue
        assert ph_idx < len(call_const_gm_args)
        in_node = call_const_gm_args[ph_idx]
        ph_idx += 1
        assert in_node.op == 'get_attr'
        with root_const_gm.graph.inserting_before(node):
            new_node = root_const_gm.graph.get_attr(in_node.target)
        new_node.meta = node.meta.copy()
        node.replace_all_uses_with(new_node)
        root_const_gm.graph.erase_node(node)
    assert 'multiple_outputs' in locals()
    fx_const_folded_attrs_name = get_unique_attr_name_in_module(mod_traced, '_FX_CONST_FOLDED_ATTRS')
    setattr(split, fx_const_folded_attrs_name, torch.nn.ParameterList() if multiple_outputs else torch.nn.Parameter())
    for node in split.graph.nodes:
        if <MASK>:
            with node.graph.inserting_before(node):
                folded_attrs = node.graph.get_attr(fx_const_folded_attrs_name)
            folded_attrs.meta = node.meta.copy()
            node.replace_all_uses_with(folded_attrs)
            break
    if hasattr(split, non_const_mod_name):
        _inline_module(split, non_const_mod_name)
    split.graph.eliminate_dead_code()
    return FoldedGraphModule(split, split.graph, root_const_gm.graph, fx_const_folded_attrs_name, device_for_folded_attrs)

@staticmethod
def _torch_function_fallback(func: Callable, types: tuple, args: tuple, kwargs: dict) -> Any:
    """Fallback torch function implementation for non-special-cased functions."""
    is_pointwise = POINTWISE_OPTIMIZE and func in op_properties.pointwise
    (flat_args, spec) = tree_flatten((args, kwargs))
    device_holding_tensor = None
    infos: list[TensorInfo] = []
    result_levels: list[DimEntry] = []
    for f in flat_args:
        info = TensorInfo.create(f, not is_pointwise, False)
        infos.append(info)
        if info:
            assert is_pointwise or info.batchedtensor is not None
            if device_holding_tensor is None and info.has_device:
                device_holding_tensor = info.tensor
            for level in info.levels:
                assert isinstance(level, DimEntry)
                if <MASK>:
                    result_levels.append(level)
    if is_pointwise:
        for (i, info) in enumerate(infos):
            if info and info.tensor is not None:
                tensor = info.tensor
                if device_holding_tensor is not None and (not info.has_device):
                    tensor = tensor.to(device_holding_tensor.device)
                ml = _match_levels(tensor, info.levels, result_levels)
                flat_args[i] = handle_from_tensor(ml)
        (unflat_args, unflat_kwargs) = tree_unflatten(flat_args, spec)
        result = func(*unflat_args, **unflat_kwargs)

        def wrap_tensor(obj: Any) -> Any:
            if isinstance(obj, torch.Tensor):
                return Tensor.from_positional(obj, result_levels, device_holding_tensor is not None)
            return obj
        if isinstance(result, torch.Tensor):
            return wrap_tensor(result)
        else:
            return tree_map(wrap_tensor, result)
    with EnableAllLayers(result_levels) as guard:
        for (i, info) in enumerate(infos):
            if info and info.batchedtensor is not None:
                batched = info.batchedtensor
                if device_holding_tensor is not None and (not info.has_device):
                    batched = batched.to(device_holding_tensor.device)
                guard.inplace_update_layers(batched, info.levels)
                flat_args[i] = handle_from_tensor(batched)
        (unflat_args, unflat_kwargs) = tree_unflatten(flat_args, spec)
        result = func(*unflat_args, **unflat_kwargs)

        def unwrap_tensor(obj: Any) -> Any:
            if isinstance(obj, torch.Tensor):
                return guard.from_batched(obj, device_holding_tensor is not None)
            return obj
        if isinstance(result, torch.Tensor):
            return unwrap_tensor(result)
        else:
            return tree_map(unwrap_tensor, result)

def _check_targets(y_true, y_pred, sample_weight=None):
    """Check that y_true and y_pred belong to the same classification task.

    This converts multiclass or binary types to a common shape, and raises a
    ValueError for a mix of multilabel and multiclass targets, a mix of
    multilabel formats, for the presence of continuous-valued or multioutput
    targets, or for targets of different lengths.

    Column vectors are squeezed to 1d, while multilabel formats are returned
    as CSR sparse label indicators.

    Parameters
    ----------
    y_true : array-like

    y_pred : array-like

    sample_weight : array-like, default=None

    Returns
    -------
    type_true : one of {'multilabel-indicator', 'multiclass', 'binary'}
        The type of the true target data, as output by
        ``utils.multiclass.type_of_target``.

    y_true : array or indicator matrix

    y_pred : array or indicator matrix

    sample_weight : array or None
    """
    (xp, _) = get_namespace(y_true, y_pred, sample_weight)
    check_consistent_length(y_true, y_pred, sample_weight)
    type_true = type_of_target(y_true, input_name='y_true')
    type_pred = type_of_target(y_pred, input_name='y_pred')
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, y_true, force_float_dtype=False)
    y_type = {type_true, type_pred}
    if y_type == {'binary', 'multiclass'}:
        y_type = {'multiclass'}
    if len(y_type) > 1:
        raise ValueError("Classification metrics can't handle a mix of {0} and {1} targets".format(type_true, type_pred))
    y_type = y_type.pop()
    if <MASK>:
        raise ValueError('{0} is not supported'.format(y_type))
    if y_type in ['binary', 'multiclass']:
        try:
            y_true = column_or_1d(y_true, input_name='y_true')
            y_pred = column_or_1d(y_pred, input_name='y_pred')
        except TypeError as e:
            if 'Sparse data was passed' in str(e):
                raise TypeError('Sparse input is only supported when targets are of multilabel type') from e
            else:
                raise
        (xp, _) = get_namespace(y_true, y_pred)
        if y_type == 'binary':
            try:
                unique_values = _union1d(y_true, y_pred, xp)
            except TypeError as e:
                raise TypeError(f'Labels in y_true and y_pred should be of the same type. Got y_true={xp.unique(y_true)} and y_pred={xp.unique(y_pred)}. Make sure that the predictions provided by the classifier coincides with the true labels.') from e
            if unique_values.shape[0] > 2:
                y_type = 'multiclass'
    if y_type.startswith('multilabel'):
        if _is_numpy_namespace(xp):
            y_true = csr_matrix(y_true)
            y_pred = csr_matrix(y_pred)
        y_type = 'multilabel-indicator'
    return (y_type, y_true, y_pred, sample_weight)

def finalize_outputs(self):
    self.created_modules.pop(self.fqn, None)
    orig_outputs = []
    signature = self.module_call_graph.get(self.child_fqn)
    if signature is not None and self.parent is not None:
        for output in signature.outputs:
            if isinstance(output, (TensorArgument, SymIntArgument, SymBoolArgument, SymFloatArgument, ConstantArgument)):
                if output.name in self.seen_nodes:
                    orig_outputs.append(self.seen_nodes[output.name])
                else:
                    orig_outputs.append(None)
            else:
                raise RuntimeError(f'Unsupported data type for output node: {output}')

        def get_actual_output_node(output):
            if output is None:
                return None
            seen_node = self.seen_nodes[output.name]
            if seen_node in self.node_map:
                return self.node_map[seen_node]
            elif seen_node in self.node_to_placeholder:
                return self.node_to_placeholder[seen_node]
            else:
                raise RuntimeError(f'Could not find output node {output}. Graph: {self.graph}')
        tree_out_node = _generate_unflatten(self.module, tuple((get_actual_output_node(output) for output in orig_outputs)), signature.out_spec)
        parent_out: Optional[torch.fx.Node] = _generate_flatten_spec(self.parent.module, self.parent_call_module, signature.out_spec)
        graph_outputs: Union[torch.fx.Node, list[torch.fx.Node]] = tree_out_node
    else:
        graph_outputs = []
        for orig_node in self.node_map.keys():
            for user_node in orig_node.users:
                if user_node.name not in self.seen_nodes:
                    orig_outputs.append(orig_node)
                    graph_outputs.append(self.node_map[orig_node])
                    break
        parent_out = self.parent_call_module
        if len(graph_outputs) == 1:
            graph_outputs = graph_outputs[0]
    assert isinstance(graph_outputs, (list, torch.fx.Node))
    self.graph.output(graph_outputs)
    if parent_out is None:
        return
    parent_out.meta['val'] = graph_outputs.meta.get('val') if isinstance(graph_outputs, torch.fx.Node) else [o.meta.get('val') for o in graph_outputs]
    if len(orig_outputs) == 1 and signature is None:
        self.parent.node_map[orig_outputs[0]] = parent_out
    else:
        for (i, orig_output) in enumerate(orig_outputs):
            if <MASK>:
                continue
            proxy_out = torch.fx.Proxy(parent_out)[i].node
            proxy_out.meta['val'] = orig_output.meta.get('val')
            self.parent.node_map[orig_output] = proxy_out

def _annotate_qat_conv2d_bn(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = find_sequential_partitions(gm, [torch.nn.Conv2d, torch.nn.BatchNorm2d])
    for fused_partition in fused_partitions:
        (conv_partition, bn_partition) = fused_partition
        (conv_node, bn_output_node) = self._get_output_nodes_of_partitions([conv_partition, bn_partition])
        if conv_node.op != 'call_function' or conv_node.target != torch.ops.aten.conv2d.default:
            continue
        if <MASK>:
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        if quantization_config is not None:
            bn_output_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(output_qspec=get_output_act_qspec(quantization_config), _annotated=True, _is_output_of_quantized_pattern=True)
        else:
            _annotate_nodes_not_quantize(bn_output_node)
        nodes_to_mark_annotated = list(conv_partition.nodes)
        nodes_to_mark_annotated.extend(list(bn_partition.nodes))
        _mark_nodes_as_annotated(nodes_to_mark_annotated)

@final
def _cython_agg_general(self, how: str, alt: Callable | None=None, numeric_only: bool=False, min_count: int=-1, **kwargs):
    data = self._get_data_to_aggregate(numeric_only=numeric_only, name=how)

    def array_func(values: ArrayLike) -> ArrayLike:
        try:
            result = self._grouper._cython_operation('aggregate', values, how, axis=data.ndim - 1, min_count=min_count, **kwargs)
        except NotImplementedError:
            if how in ['any', 'all'] and isinstance(values, SparseArray):
                pass
            elif alt is None or how in ['any', 'all', 'std', 'sem']:
                raise
        else:
            return result
        assert alt is not None
        result = self._agg_py_fallback(how, values, ndim=data.ndim, alt=alt)
        return result
    new_mgr = data.grouped_reduce(array_func)
    res = self._wrap_agged_manager(new_mgr)
    if <MASK>:
        res = self._wrap_idxmax_idxmin(res, how=how, skipna=kwargs['skipna'])
    out = self._wrap_aggregated_output(res)
    return out

@dispatch_for_api(api, {x_name: x_type})
def dispatch_target(*args, **kwargs):
    (args, kwargs, name) = _extract_name_arg(args, kwargs, name_index)
    if <MASK>:
        (x, args) = (args[0], args[1:])
    else:
        x = kwargs.pop(x_name)
    if need_to_bind_api_args:
        tensor_api = lambda v: api(v, *args, **kwargs)
    else:
        tensor_api = api
    if name is None:
        return elementwise_api_handler(tensor_api, x)
    else:
        with ops.name_scope(name, None, [x]):
            return elementwise_api_handler(tensor_api, x)

def _set_metric_names(self):
    """Sets unique metric names."""
    metric_names = set()
    is_multi_output = len(self._output_names) > 1
    zip_args = (self._output_names, self._metrics, self._weighted_metrics)
    for (output_name, output_metrics, weighted_output_metrics) in zip(*zip_args):
        for m in output_metrics:
            if m is None:
                continue
            if is_multi_output:
                m._name = output_name + '_' + m._name
            if m._name in metric_names:
                raise ValueError('Found two metrics with the same name: {}'.format(m._name))
            metric_names.add(m._name)
        for wm in weighted_output_metrics:
            if <MASK>:
                continue
            if is_multi_output:
                if output_name + '_' + wm._name in metric_names:
                    wm._name = output_name + '_weighted_' + wm._name
                else:
                    wm._name = output_name + '_' + wm._name
            elif wm._name in metric_names:
                wm._name = 'weighted_' + wm._name
            if wm._name in metric_names:
                raise ValueError('Found two metrics with the same name: {}'.format(wm._name))
            metric_names.add(wm._name)

def _get_backward_hooks(self):
    """Return the backward hooks for use in the call function.

        It returns two lists, one with the full backward hooks and one with the non-full
        backward hooks.
        """
    full_backward_hooks: list[Callable] = []
    if _global_is_full_backward_hook is True:
        full_backward_hooks += _global_backward_hooks.values()
    if <MASK>:
        full_backward_hooks += self._backward_hooks.values()
    non_full_backward_hooks: list[Callable] = []
    if _global_is_full_backward_hook is False:
        non_full_backward_hooks += _global_backward_hooks.values()
    if self._is_full_backward_hook is False:
        non_full_backward_hooks += self._backward_hooks.values()
    return (full_backward_hooks, non_full_backward_hooks)

def __call__(self, shape, dtype=None, partition_info=None):
    if <MASK>:
        dtype = self.dtype
    if len(shape) < 2:
        raise ValueError(f'The tensor to initialize, specified by argument `shape` must be at least two-dimensional. Received shape={shape}')
    num_rows = 1
    for dim in shape[:-1]:
        num_rows *= dim
    num_rows = int(num_rows)
    num_cols = int(shape[-1])
    if num_rows < num_cols:
        flat_shape = (num_cols, num_rows)
    else:
        flat_shape = (num_rows, num_cols)
    a = random_ops.random_normal(flat_shape, dtype=dtype, seed=self.seed)
    (q, r) = gen_linalg_ops.qr(a, full_matrices=False)
    d = array_ops.diag_part(r)
    q *= math_ops.sign(d)
    if num_rows < num_cols:
        q = array_ops.matrix_transpose(q)
    return self.gain * array_ops.reshape(q, shape)

def proxy_bypass_registry(host):
    try:
        import winreg
    except ImportError:
        return False
    try:
        internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
        proxyEnable = int(winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0])
        proxyOverride = winreg.QueryValueEx(internetSettings, 'ProxyOverride')[0]
    except (OSError, ValueError):
        return False
    if not proxyEnable or not proxyOverride:
        return False
    proxyOverride = proxyOverride.split(';')
    proxyOverride = filter(None, proxyOverride)
    for test in proxyOverride:
        if test == '<local>':
            if <MASK>:
                return True
        test = test.replace('.', '\\.')
        test = test.replace('*', '.*')
        test = test.replace('?', '.')
        if re.match(test, host, re.I):
            return True
    return False

@RegisterPFor('Gather')
@RegisterPFor('GatherV2')
def _convert_gather(pfor_input: _PforInput):
    (param, param_stacked, _) = pfor_input.input(0)
    (indices, indices_stacked, _) = pfor_input.input(1)
    batch_dims = pfor_input.get_attr('batch_dims')
    op_type = pfor_input.op_type
    if <MASK>:
        validate_indices = pfor_input.get_attr('validate_indices')
        axis = 0
    else:
        validate_indices = None
        axis = math_ops.cast(pfor_input.unstacked_input(2), dtypes.int32)
        axis_value = tensor_util.constant_value(axis)
        if axis_value is not None:
            axis = axis_value
    if indices_stacked and (not param_stacked):
        if indices is pfor_input.pfor.all_indices and axis == 0:
            param_shape0 = tensor_shape.dimension_value(param.shape[0])
            indices_shape0 = tensor_shape.dimension_value(indices.shape[0])
            if param_shape0 is not None and indices_shape0 == param_shape0:
                return wrap(param, True)
        if batch_dims != 0:
            batch_dims_pos = batch_dims
            if batch_dims < 0:
                batch_dims_pos += array_ops.rank(indices)
            order = array_ops.concat([math_ops.range(1, batch_dims_pos + 1), [0], math_ops.range(batch_dims_pos + 1, array_ops.rank(indices))], axis=0)
            indices = array_ops.transpose(indices, order)
        output = array_ops.gather(param, indices, validate_indices=validate_indices, axis=axis, batch_dims=batch_dims)
        if axis != 0:
            axis = smart_cond.smart_cond(axis < 0, lambda : axis + array_ops.rank(param), lambda : ops.convert_to_tensor(axis))
            order = array_ops.concat([[axis], math_ops.range(axis), math_ops.range(axis + 1, array_ops.rank(output))], axis=0)
            output = smart_cond.smart_cond(math_ops.equal(axis, 0), lambda : output, lambda : array_ops.transpose(output, order))
        return wrap(output, True)
    if param_stacked:
        pfor_input.stack_inputs(stack_indices=[1])
        indices = pfor_input.stacked_input(1)
        if isinstance(axis, tensor_lib.Tensor):
            axis = array_ops.where(axis >= 0, axis + 1, axis)
        else:
            axis = axis + 1 if axis >= 0 else axis
        batch_dims = batch_dims + 1 if batch_dims >= 0 else batch_dims
        output = array_ops.gather(param, indices, axis=axis, batch_dims=batch_dims)
        return wrap(output, True)

def parse_datetime_format_str(format_str, data) -> pd.Series | np.ndarray:
    """Parse datetime `format_str` to interpret the `data`."""
    timestamp_meta = re.match('ts([smun]):(.*)', format_str)
    if timestamp_meta:
        (unit, tz) = (timestamp_meta.group(1), timestamp_meta.group(2))
        if <MASK>:
            unit += 's'
        data = data.astype(f'datetime64[{unit}]')
        if tz != '':
            data = pd.Series(data).dt.tz_localize('UTC').dt.tz_convert(tz)
        return data
    date_meta = re.match('td([Dm])', format_str)
    if date_meta:
        unit = date_meta.group(1)
        if unit == 'D':
            data = (data.astype(np.uint64) * (24 * 60 * 60)).astype('datetime64[s]')
        elif unit == 'm':
            data = data.astype('datetime64[ms]')
        else:
            raise NotImplementedError(f'Date unit is not supported: {unit}')
        return data
    raise NotImplementedError(f'DateTime kind is not supported: {format_str}')

