def _interpolate(name, dim, interpolate_mode):

    def symbolic_fn(g, input, output_size, *args):
        (scales, align_corners) = symbolic_helper._get_interpolate_attributes(g, interpolate_mode, args)
        symbolic_helper._interpolate_warning(interpolate_mode)
        align_corners = symbolic_helper._maybe_get_scalar(align_corners)
        if align_corners:
            return symbolic_helper._unimplemented(name, 'align_corners == True', input)
        output_size = symbolic_helper._maybe_get_const(output_size, 'is')
        if symbolic_helper._is_value(output_size):
            return symbolic_helper._unimplemented(name, 'torch._C.Value (output_size) indexing')
        if <MASK>:
            scales = [1.0 if i < 2 else float(output_size[-(dim - i)]) / float(input.type().sizes()[-(dim - i)]) for i in range(dim)]
        return g.op('Upsample', input, mode_s=interpolate_mode, scales_f=scales)
    return symbolic_fn

def _validate_embedding_param(args, kwargs):
    """
    Validate input params of sharded embedding op.

    Args:
        input: list of ID used for lookup.
        weight: sharded weight tensor.
        kwargs: same as normal Embedding.

    Return: None.
    """
    input = args[0]
    weight = args[1]
    max_norm = kwargs.get('max_norm')
    scale_grad_by_freq = kwargs.get('scale_grad_by_freq')
    sparse = kwargs.get('sparse')
    if not isinstance(input, torch.Tensor):
        raise TypeError('input need to be torch.Tensor')
    if <MASK>:
        raise TypeError('weight needs to be ShardedTensor')
    weight_size = weight.size()
    if len(weight_size) != 2:
        raise ValueError('Weight needs to have exactly 2 dims')
    if int(torch.min(input).item()) < 0:
        raise ValueError('Index out of range in Input %d %d', int(torch.min(input).item()), weight_size[1])
    if int(torch.max(input).item()) >= weight_size[0]:
        raise ValueError('Index out of range in Input %d %d', int(torch.max(input).item()), weight_size[1])
    if scale_grad_by_freq:
        raise RuntimeError('nn.Embedding weight sharded with flag on "scale_grad_by_freq" not supported!')
    if sparse:
        raise RuntimeError('nn.Embedding weight sharded with flag on "sparse" not supported!')
    if max_norm and max_norm <= 0.0:
        raise ValueError('"max_norm" must be larger than zero!')
    if not isinstance(weight._sharding_spec, ChunkShardingSpec):
        raise ValueError('Only ChunkShardingSpec supported for ShardedTensor ops!')
    if len(weight.local_shards()) != 1:
        raise ValueError('Only one local shard supported!')

def convert_variable_to_constant(self, incoming_edge, tensor_data):
    node = self.converted_self().node
    node.Clear()
    node.name = self._node.name
    node.op = 'Identity'
    node.input.append(self._node.input[0])
    node.attr['T'].CopyFrom(self._node.attr['dtype'])
    if '_class' in self._node.attr:
        node.attr['_class'].CopyFrom(self._node.attr['_class'])
    if <MASK>:
        for edge in self.outgoing_edges:
            index = edge.destination.index
            dest = edge.destination.convertible.converted_self()
            if isinstance(dest, _Node):
                input_name_parts = dest.node.input[index].split(':')
                if len(input_name_parts) > 1 and input_name_parts[1] == 'value':
                    input_name_parts[1] = 'output'
                    dest.node.input[index] = ':'.join(input_name_parts)

def forward(self, input: Tensor, hx: Optional[Tensor]=None) -> Tensor:
    self.check_forward_input(input)
    if hx is None:
        hx = torch.zeros(input.size(0), self.hidden_size, dtype=input.dtype, device=input.device)
    self.check_forward_hidden(input, hx, '')
    if self.nonlinearity == 'tanh':
        ret = torch.ops.quantized.quantized_rnn_tanh_cell_dynamic(input, hx, self._packed_weight_ih, self._packed_weight_hh, self.bias_ih, self.bias_hh)
    elif <MASK>:
        ret = torch.ops.quantized.quantized_rnn_relu_cell_dynamic(input, hx, self._packed_weight_ih, self._packed_weight_hh, self.bias_ih, self.bias_hh)
    else:
        ret = input
        raise RuntimeError(f'Unknown nonlinearity: {self.nonlinearity}')
    return ret

def _save_conversion_params_metric(self, graph_def=None, inference_type=None, inference_input_type=None):
    """Set conversion parameter metrics."""
    converter_kwargs = self._collected_converter_params
    converter_kwargs.update(self._get_base_converter_args())
    quant_mode = QuantizationMode(self.optimizations, self.target_spec, self.representative_dataset, graph_def, self._experimental_disable_per_channel, self.experimental_new_dynamic_range_quantizer, self._experimental_low_bit_qat, self._experimental_full_integer_quantization_bias_type, self._experimental_variable_quantization, self._experimental_strict_qdq)
    converter_kwargs.update({'tf_version': self._metadata.environment.tensorflowVersion, 'api_version': self._metadata.environment.apiVersion, 'original_model_format': self._metadata.environment.modelType, 'optimization_default': quant_mode.is_any_optimization_enabled(), 'optimization_post_training_dynamic_range': quant_mode.is_post_training_dynamic_range_quantization(), 'optimization_post_training_float16': quant_mode.is_post_training_float16_quantization(), 'optimization_post_training_integer_quantize': quant_mode.is_post_training_integer_quantization(), 'optimization_qat': quant_mode.is_quantization_aware_training(), 'optimization_low_bit_qat': quant_mode.is_low_bit_quantize_aware_training(), 'optimization_sparsify': self._sparsify_model(), 'activations_type': quant_mode.activations_type()})
    converter_kwargs.update(quant_mode.converter_flags(inference_type, inference_input_type))
    if self.target_spec._experimental_supported_accumulation_type:
        converter_kwargs.update({'accumulation_type': self.target_spec._experimental_supported_accumulation_type})

    def format_element(elem):
        if isinstance(elem, enum.Enum):
            return str(elem.value)
        return pprint.pformat(elem)

    def format_param(param):
        if isinstance(param, (list, tuple, set)):
            if not param:
                return 'None'
            string_list = [format_element(x) for x in param]
            return ','.join(sorted(string_list))
        return format_element(param)
    for (key, value) in converter_kwargs.items():
        self._tflite_metrics.set_converter_param(key, format_param(value))
    self._tflite_metrics.set_export_required()
    self._metadata.options.allowCustomOps = self.allow_custom_ops
    self._metadata.options.enableSelectTfOps = OpsSet.SELECT_TF_OPS in self.target_spec.supported_ops
    self._metadata.options.forceSelectTfOps = set([OpsSet.SELECT_TF_OPS]) == set(self.target_spec.supported_ops)
    self._metadata.options.modelOptimizationModes = []
    if quant_mode.is_post_training_float16_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_FLOAT16)
    if quant_mode.is_post_training_dynamic_range_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_DYNAMIC_RANGE)
    if quant_mode.is_post_training_int8_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_FULL_INTEGER)
    if quant_mode.is_post_training_int16x8_quantization():
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.PTQ_INT16)
    if <MASK>:
        self._metadata.options.modelOptimizationModes.append(conversion_metadata_fb.ModelOptimizationMode.QUANTIZATION_AWARE_TRAINING)

