def _set_replacement(self, a: sympy.Symbol, tgt: sympy.Expr, msg: str) -> None:
    """
        Adds or updates a replacement for a symbol.
        Use this instead of `self.replacements[a] = tgt`.
        """
    if tgt == self.replacements.get(a, None):
        return
    if a in tgt.free_symbols:
        return
    assert isinstance(a, sympy.Symbol)
    if self.prefer_deferred_runtime_asserts_over_guards and (not _is_supported_equivalence(tgt)):
        return
    tgt_bound = None
    if a in self.var_to_range:
        src_bound = self.var_to_range[a]
        tgt_bound = self.bound_sympy(tgt)
        self._update_var_to_range(a, tgt_bound)
        if not tgt_bound.issubset(src_bound) and len(tgt.free_symbols) == 1:
            b = next(iter(tgt.free_symbols))
            r = try_solve(sympy.Eq(a, tgt), b, floordiv_inequality=False)
            if r is not None:
                self.log.debug('set_replacement: solve for %s in %s == %s gives %s', b, a, tgt, r)
                rat_b_bound = self.bound_sympy(r[1])
                b_bound = ValueRanges(CeilToInt(rat_b_bound.lower), FloorToInt(rat_b_bound.upper))
                self._update_var_to_range(b, b_bound, self.var_to_range_sloc[a])
                tgt_bound = self.bound_sympy(tgt)
                assert tgt_bound.issubset(src_bound), f'tgt_bound={tgt_bound!r} not a subset of src_bound={src_bound!r}'
        if a in self.size_like and isinstance(tgt, sympy.Symbol):
            self.size_like.add(tgt)
        elif isinstance(tgt, sympy.Symbol) and tgt in self.size_like:
            self.size_like.add(a)
        if <MASK>:
            self.log.debug('skipped set_replacement %s = %s (%s) [%s not subset of %s]', a, tgt, msg, tgt_bound, src_bound)
            return
        elif a in self.size_like:
            tgt_bound_so = self.bound_sympy(tgt, size_oblivious=True)
            src_bound_so = self.bound_sympy(a, size_oblivious=True)
            if not tgt_bound_so.issubset(src_bound_so):
                self.log.debug('skipped set_replacement %s = %s (%s) [%s not subset of %s (size-oblivious conditions)]', a, tgt, msg, tgt_bound_so, src_bound_so)
                return
    if isinstance(tgt, (sympy.Integer, sympy.Float)):
        user_tb = TracingContext.extract_stack()
        trace_structured('symbolic_shape_specialization', metadata_fn=lambda : {'symbol': repr(a), 'sources': [s.name() for s in self.var_to_sources.get(a, [])], 'value': repr(tgt), 'reason': msg, 'stack': structured.from_traceback(CapturedTraceback.extract(skip=1).summary()), 'user_stack': structured.from_traceback(user_tb) if user_tb else None})
        for source in self.var_to_sources.get(a, []):
            if user_tb:
                self.specialization_stacks[source] = user_tb
        if config.print_specializations:
            self.log.warning('Specializing %s to %s', self.var_to_sources[a][0].name(), tgt)
            self.log.debug('SPECIALIZATION', stack_info=True)
    log.info('set_replacement %s = %s (%s) %s', a, tgt, msg, tgt_bound)
    self.replacements[a] = tgt
    if a not in self.replacements_slocs:
        self.replacements_slocs[a] = self._get_sloc()
    self._update_version_counter()
    self._add_target_expr(sympy.Eq(a, tgt, evaluate=False))

def make_piece_scalar(piece):
    if isinstance(piece, int):
        scalar = constant_op.constant(piece)
        if use_constant:
            return scalar
        else:
            return array_ops.placeholder_with_default(scalar, [])
    elif <MASK>:
        return slice(make_piece_scalar(piece.start), make_piece_scalar(piece.stop), make_piece_scalar(piece.step))
    else:
        return piece

def _rank_calc(self, *, axis: AxisInt=0, method: str='average', na_option: str='keep', ascending: bool=True, pct: bool=False):
    if axis != 0:
        ranked = super()._rank(axis=axis, method=method, na_option=na_option, ascending=ascending, pct=pct)
        if method == 'average' or pct:
            pa_type = pa.float64()
        else:
            pa_type = pa.uint64()
        result = pa.array(ranked, type=pa_type, from_pandas=is_nan_na())
        return result
    data = self._pa_array.combine_chunks()
    sort_keys = 'ascending' if ascending else 'descending'
    null_placement = 'at_start' if na_option == 'top' else 'at_end'
    tiebreaker = 'min' if method == 'average' else method
    result = pc.rank(data, sort_keys=sort_keys, null_placement=null_placement, tiebreaker=tiebreaker)
    if na_option == 'keep':
        mask = pc.is_null(self._pa_array)
        null = pa.scalar(None, type=result.type)
        result = pc.if_else(mask, null, result)
    if method == 'average':
        result_max = pc.rank(data, sort_keys=sort_keys, null_placement=null_placement, tiebreaker='max')
        result_max = result_max.cast(pa.float64())
        result_min = result.cast(pa.float64())
        result = pc.divide(pc.add(result_min, result_max), 2)
    if pct:
        if <MASK>:
            result = result.cast(pa.float64())
        if method == 'dense':
            divisor = pc.max(result)
        else:
            divisor = pc.count(result)
        result = pc.divide(result, divisor)
    return result

def defn(self, *, name: str | None=None, prefix: str='', is_redispatching_fn: bool=False) -> str:
    returns_type = cpp.returns_type(self.func.returns, symint=self.symint).cpp_type()
    cpp_args = [a.defn() for a in self.arguments()]
    if <MASK>:
        cpp_args = ['c10::DispatchKeySet dispatchKeySet'] + cpp_args
    cpp_args_str = ', '.join(cpp_args)
    if name is None:
        name = prefix + self.name()
    return f'{returns_type} {name}({cpp_args_str})'

def codegen_kwargs(self, skip_out: bool=False) -> list[str]:
    if V.graph.cpp_wrapper:
        if self.op_overload is not None and len(self.schema_kwargs) == 0:
            return []
        kwargs = []
        for arg_name in self.ordered_kwargs_for_cpp_kernel:
            if <MASK>:
                continue
            v = self.get_kwargs_value(arg_name)
            if isinstance(v, Expr):
                kwargs.append(v)
            else:
                assert self.allarg_properties is not None
                type_ = self.allarg_properties.get(arg_name, {}).get('type')
                kwargs.append(V.graph.wrapper_code.val_to_arg_str(v, type_))
    else:
        kwargs = [f'{k}={V.graph.wrapper_code.val_to_arg_str(v)}' for (k, v) in self.kwargs.items()]
    return kwargs

def genobject(i: int) -> Dim:
    nonlocal found_ndims
    name = None
    if i < found_ndims:
        name = decoder.name()
    if <MASK>:
        name = f'd{i}'
        found_ndims = 0
    else:
        decoder.next()
    size = sizes[i] if sizes is not None else None
    return _create_dim(name, size)

def _compareGpu(self, x, p, conjugate=False):
    if p is None:
        rank = x.ndim
        perm = rank - 1 - np.arange(rank)
    else:
        perm = p
    np_ans = self._np_transpose(x, perm)
    if <MASK>:
        np_ans = np.conj(np_ans)
    with self.cached_session():
        inx = ops.convert_to_tensor(x)
        y = array_ops.transpose(inx, p, conjugate=conjugate)
        tf_ans = self.evaluate(y)
        self.assertAllEqual(np_ans, tf_ans)
        self.assertShapeEqual(np_ans, y)
        jacob_t = None
        if x.dtype == np.float32:
            (jacob_t, jacob_n) = gradient_checker_v2.compute_gradient(lambda x: array_ops.transpose(x, p, conjugate=conjugate), [inx])
            self.assertAllClose(jacob_t, jacob_n, 0.001, 0.001)
        elif x.dtype == np.float64:
            (jacob_t, jacob_n) = gradient_checker_v2.compute_gradient(lambda x: array_ops.transpose(x, p, conjugate=conjugate), [inx])
            self.assertAllClose(jacob_t, jacob_n, 1e-06, 1e-06)
        return (tf_ans, jacob_t)

def _reduction(a: TensorLikeType, prim: Callable, *, has_identity: bool=True, accepts_dim_tuple: bool=True, dims: Optional[DimsType]=None, keepdims: bool=False, dtype: Optional[torch.dtype]=None, out: Optional[Tensor]=None, output_dtype_kind: REDUCTION_OUTPUT_TYPE_KIND) -> TensorLikeType:
    assert isinstance(a, TensorLike)
    if a.ndim > 64:
        raise RuntimeError(f'Received a tensor with {a.ndim} dimensions, but only tensors with up to 64 dims are supported!')
    if out is not None:
        assert isinstance(out, TensorLike)
        if dtype is not None:
            if dtype != out.dtype:
                raise RuntimeError('dtype argument and out dtype must match in reduction')
    if not accepts_dim_tuple:
        assert dims is None or isinstance(dims, Dim)
    if isinstance(dims, Dim):
        dims = (dims,)
    dims = utils.reduction_dims(a.shape, dims)
    if not has_identity:
        from torch.fx.experimental.symbolic_shapes import sym_and
        valid_shape = a.ndim == 0 or sym_and(*(a.shape[i] > 0 for i in dims))
        torch._check(valid_shape, lambda : 'reducing over zero-size dimension for reduction operation without identity')
    (computation_dtype, result_dtype) = utils.reduction_dtypes(a, output_dtype_kind, dtype)
    a = _maybe_convert_to_dtype(a, computation_dtype)
    result = prim(a, dims)
    if <MASK>:
        output_shape = [a.shape[i] if i not in dims else 1 for i in range(a.ndim)]
        broadcast_dims = [i for i in range(a.ndim) if i not in dims]
        result = prims.broadcast_in_dim(result, output_shape, broadcast_dims)
    if out is not None:
        assert result_dtype is not None
        if dtype is not None and result_dtype != out.dtype:
            raise RuntimeError('Expected the dtype of reduction result and out to match')
        out = _maybe_resize_out(out, result.shape)
        return _safe_copy_out(copy_from=result, copy_to=out)
    if result.dtype != result_dtype and result_dtype is not None:
        result = prims.convert_element_type(result, result_dtype)
    return result

def rewriter_bool(option):
    toggle = self._optimizer_experimental_options.get(option, None)
    if <MASK>:
        return
    setattr(config.graph_options.rewrite_options, option, toggle)

def _handles(self, args, kwargs):
    for arg in itertools.chain(args, kwargs.values()):
        if <MASK>:
            return True
    return False

def _make_fixed_width(strings: list[str], justify: str='right', minimum: int | None=None, adj: printing._TextAdjustment | None=None) -> list[str]:
    if len(strings) == 0 or justify == 'all':
        return strings
    if <MASK>:
        adjustment = printing.get_adjustment()
    else:
        adjustment = adj
    max_len = max((adjustment.len(x) for x in strings))
    if minimum is not None:
        max_len = max(minimum, max_len)
    conf_max = get_option('display.max_colwidth')
    if conf_max is not None and max_len > conf_max:
        max_len = conf_max

    def just(x: str) -> str:
        if conf_max is not None:
            if (conf_max > 3) & (adjustment.len(x) > max_len):
                x = x[:max_len - 3] + '...'
        return x
    strings = [just(x) for x in strings]
    result = adjustment.justify(strings, max_len, mode=justify)
    return result

def _extract_signatures(self, wrapped, meta_graph_def):
    """Creates ConcreteFunctions for signatures in `meta_graph_def`."""
    signature_functions = {}
    for (signature_key, signature_def) in meta_graph_def.signature_def.items():
        if signature_def.inputs:
            input_items = sorted(signature_def.inputs.items(), key=lambda item: item[0])
            (original_input_names, input_specs) = zip(*input_items)
        else:
            original_input_names = []
            input_specs = []
        feeds = [wrap_function._get_element_from_tensor_info(input_spec, wrapped.graph) for input_spec in input_specs]
        input_names = []
        input_tensors = []
        for (original_input_name, feed) in zip(original_input_names, feeds):
            if isinstance(feed, sparse_tensor.SparseTensor):
                indices_name = '%s_indices' % original_input_name
                values_name = '%s_values' % original_input_name
                dense_shape_name = '%s_dense_shape' % original_input_name
                input_names.extend([indices_name, values_name, dense_shape_name])
                input_tensors.extend([feed.indices, feed.values, feed.dense_shape])
            elif isinstance(feed, composite_tensor.CompositeTensor):
                component_tensors = nest.flatten(feed, expand_composites=True)
                input_names.extend(('%s_component_%d' % (original_input_name, n) for n in range(len(component_tensors))))
                input_tensors.extend(component_tensors)
            else:
                input_names.append(original_input_name)
                input_tensors.append(feed)
        fetches = {name: out for (name, out) in signature_def.outputs.items()}
        input_signature = ((), func_graph.convert_structure_to_signature(dict(zip(input_names, input_tensors))))
        try:
            signature_fn = wrapped.prune(feeds=feeds, fetches=fetches, input_signature=input_signature, are_keyword_args_also_positional=True)
        except lift_to_graph.UnliftableError as ex:
            args = ex.args
            if <MASK>:
                message = ''
            else:
                message = args[0]
            message = "A SavedModel signature needs an input for each placeholder the signature's outputs use. An output for signature '{}' depends on a placeholder which is not an input (i.e. the placeholder is not fed a value).\n\n".format(signature_key) + message
            ex.args = (message,) + args[1:]
            raise
        signature_fn._arg_keywords = input_names
        if len(input_names) == 1:
            signature_fn._num_positional_args = 1
        else:
            signature_fn._num_positional_args = 0
        signature_functions[signature_key] = signature_fn
    return signature_functions

def validate_map_location(map_location=None):
    if isinstance(map_location, str):
        map_location = torch.device(map_location)
    elif <MASK>:
        raise ValueError('map_location should be either None, string or torch.device, but got type: ' + str(type(map_location)))
    if str(map_location).startswith('cuda'):
        validate_cuda_device(map_location)
    return map_location

def __init__(self, delimiter=None, comments='#', autostrip=True, encoding=None):
    delimiter = _decode_line(delimiter)
    comments = _decode_line(comments)
    self.comments = comments
    if <MASK>:
        delimiter = delimiter or None
        _handyman = self._delimited_splitter
    elif hasattr(delimiter, '__iter__'):
        _handyman = self._variablewidth_splitter
        idx = np.cumsum([0] + list(delimiter))
        delimiter = [slice(i, j) for (i, j) in itertools.pairwise(idx)]
    elif int(delimiter):
        (_handyman, delimiter) = (self._fixedwidth_splitter, int(delimiter))
    else:
        (_handyman, delimiter) = (self._delimited_splitter, None)
    self.delimiter = delimiter
    if autostrip:
        self._handyman = self.autostrip(_handyman)
    else:
        self._handyman = _handyman
    self.encoding = encoding

def get_node_first_input_and_output_type(node: Node, gm: GraphModule, logger_cls: Callable, node_type_to_io_type_map: dict[str, set[NSNodeTargetType]]) -> tuple[NodeInputOrOutputType, NodeInputOrOutputType]:
    FUNS_IO_TYPE_FP32 = node_type_to_io_type_map['funs_io_type_fp32']
    FUNS_IO_TYPE_FP16 = node_type_to_io_type_map['funs_io_type_fp16']
    FUNS_IO_TYPE_INT8 = node_type_to_io_type_map['funs_io_type_int8']
    FUNS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['funs_io_type_fp32_or_int8']
    MODS_IO_TYPE_FP32 = node_type_to_io_type_map['mods_io_type_fp32']
    MODS_IO_TYPE_INT8 = node_type_to_io_type_map['mods_io_type_int8']
    MODS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['mods_io_type_fp32_or_int8']
    METHS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['meths_io_type_fp32_or_int8']
    if node.op == 'call_function':
        if node.target in FUNS_IO_TYPE_FP32:
            return (NodeInputOrOutputType.FP32, NodeInputOrOutputType.FP32)
        if node.target in FUNS_IO_TYPE_FP16:
            return (NodeInputOrOutputType.FP16, NodeInputOrOutputType.FP16)
        elif node.target in FUNS_IO_TYPE_INT8:
            return (NodeInputOrOutputType.INT8, NodeInputOrOutputType.INT8)
        elif node.target in FUNS_IO_TYPE_FP32_OR_INT8:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        else:
            return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    elif <MASK>:
        if node.op != 'call_module':
            raise AssertionError(f"Expected call_module, got '{node.op}'")
        if not isinstance(node.target, str):
            raise AssertionError(f'Expected str, but got {type(node.target)}')
        mod = getattr_from_fqn(gm, node.target)
        is_known_fp32_or_int8_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_FP32_OR_INT8))
        if isinstance(mod, (logger_cls, ObserverBase, FakeQuantizeBase)) or is_known_fp32_or_int8_input_module:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        is_known_fp32_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_FP32))
        is_known_int8_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_INT8))
        if is_known_fp32_input_module:
            return (NodeInputOrOutputType.FP32, NodeInputOrOutputType.FP32)
        elif is_known_int8_input_module:
            return (NodeInputOrOutputType.INT8, NodeInputOrOutputType.INT8)
        else:
            return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    elif node.op == 'call_method':
        if node.target == 'dequantize':
            prev_node = get_normalized_nth_input(node, gm, 0)
            if not isinstance(prev_node, Node):
                raise AssertionError(f'Expected Node, got {type(prev_node)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(prev_node, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, NodeInputOrOutputType.FP32)
        elif node.target == 'to':
            prev_node = get_normalized_nth_input(node, gm, 0)
            if not isinstance(prev_node, Node):
                raise AssertionError(f'Expected Node, got {type(prev_node)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(prev_node, gm, logger_cls, node_type_to_io_type_map)
            cur_node_dtype_target = get_normalized_nth_input(node, gm, 1)
            if cur_node_dtype_target is not torch.float16:
                raise AssertionError(f'{cur_node_dtype_target} handling needs to be added')
            return (prev_node_output_type, NodeInputOrOutputType.FP16)
        elif node.target in METHS_IO_TYPE_FP32_OR_INT8:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    else:
        return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)

def start_trace(self) -> None:
    if self.execution_trace_observer:
        self.execution_trace_observer.start()
    assert self.profiler is not None
    self.profiler._start_trace()
    if self.profile_memory:
        self.add_metadata_json('profile_memory', '1')
    if self.with_stack:
        self.add_metadata_json('with_stack', '1')
    if self.record_shapes:
        self.add_metadata_json('record_shapes', '1')
    if <MASK>:
        self.add_metadata_json('with_modules', '1')
    if self.with_flops:
        self.add_metadata_json('with_flops', '1')
    if kineto_available():
        dist_info = self._get_distributed_info()
        if dist_info:
            self.add_metadata_json('distributedInfo', json.dumps(dist_info, cls=_NumpyEncoder))
        cuda_version = None
        if hasattr(torch, 'version'):
            from torch.torch_version import TorchVersion
            cuda_version = TorchVersion(getattr(torch.version, 'cuda', '0.0'))
        if self.has_cudagraphs and (cuda_version and cuda_version < '12.6' or not profiler_allow_cudagraph_cupti_lazy_reinit_cuda12()):
            os.environ['DISABLE_CUPTI_LAZY_REINIT'] = '1'
            self.add_metadata_json('DISABLE_CUPTI_LAZY_REINIT', '1')
            os.environ['TEARDOWN_CUPTI'] = '0'
        for (k, v) in self.preset_metadata.items():
            self.add_metadata_json(k, v)

def _transform_input_tensor(self, input_tensor):
    """Hashes the values in the feature_column."""
    if not isinstance(input_tensor, sparse_tensor_lib.SparseTensor):
        raise ValueError('SparseColumn input must be a SparseTensor.')
    fc_utils.assert_string_or_int(input_tensor.dtype, prefix='column_name: {} input_tensor'.format(self.key))
    if self.dtype.is_integer != input_tensor.dtype.is_integer:
        raise ValueError('Column dtype and SparseTensors dtype must be compatible. key: {}, column dtype: {}, tensor dtype: {}'.format(self.key, self.dtype, input_tensor.dtype))
    if <MASK>:
        sparse_values = input_tensor.values
    else:
        sparse_values = string_ops.as_string(input_tensor.values)
    sparse_id_values = string_ops.string_to_hash_bucket_fast(sparse_values, self.hash_bucket_size, name='lookup')
    return sparse_tensor_lib.SparseTensor(input_tensor.indices, sparse_id_values, input_tensor.dense_shape)

def _update_losses(self, stages, losses):
    """
        Update the losses to those in the internal state
        """
    if not isinstance(stages, list):
        stages = [stages]
    contains_last_stage = any((stage.is_last for stage in stages))
    if contains_last_stage and losses is not None:
        if <MASK>:
            raise RuntimeError(f'Expecting {self._n_microbatches} losses but got {len(self._internal_losses)}')
        losses.clear()
        losses.extend(self._internal_losses)
    self._internal_losses.clear()

def print_deps(node):
    out = []
    for parent in sorted(node.parents):
        out.append('%s.%s' % parent.key)
    if <MASK>:
        return ' ... (%s)' % ', '.join(out)
    return ''

def traverse(obj, visit, parents=[], result=None, *args, **kwargs):
    '''Traverse f2py data structure with the following visit function:

    def visit(item, parents, result, *args, **kwargs):
        """

        parents is a list of key-"f2py data structure" pairs from which
        items are taken from.

        result is a f2py data structure that is filled with the
        return value of the visit function.

        item is 2-tuple (index, value) if parents[-1][1] is a list
        item is 2-tuple (key, value) if parents[-1][1] is a dict

        The return value of visit must be None, or of the same kind as
        item, that is, if parents[-1] is a list, the return value must
        be 2-tuple (new_index, new_value), or if parents[-1] is a
        dict, the return value must be 2-tuple (new_key, new_value).

        If new_index or new_value is None, the return value of visit
        is ignored, that is, it will not be added to the result.

        If the return value is None, the content of obj will be
        traversed, otherwise not.
        """
    '''
    if _is_visit_pair(obj):
        if <MASK>:
            return obj
        new_result = visit(obj, parents, result, *args, **kwargs)
        if new_result is not None:
            assert _is_visit_pair(new_result)
            return new_result
        parent = obj
        (result_key, obj) = obj
    else:
        parent = (None, obj)
        result_key = None
    if isinstance(obj, list):
        new_result = []
        for (index, value) in enumerate(obj):
            (new_index, new_item) = traverse((index, value), visit, parents + [parent], result, *args, **kwargs)
            if new_index is not None:
                new_result.append(new_item)
    elif isinstance(obj, dict):
        new_result = {}
        for (key, value) in obj.items():
            (new_key, new_value) = traverse((key, value), visit, parents + [parent], result, *args, **kwargs)
            if new_key is not None:
                new_result[new_key] = new_value
    else:
        new_result = obj
    if result_key is None:
        return new_result
    return (result_key, new_result)

def end_node_matches_reversed_fusion(end_node: Node, reversed_fusion: NSFusionType, gm: GraphModule, seen_nodes: set[Node]) -> bool:
    """
    Returns true if a pattern ending with `end_node` matches
    the fusion pattern.
    """
    cur_node = end_node
    for fusion_idx in range(len(reversed_fusion)):
        if cur_node in seen_nodes:
            return False
        cur_fusion_el = reversed_fusion[fusion_idx]
        if cur_node.op == 'call_function':
            fusion_el_is_fun = not isinstance(cur_fusion_el, str) and (not isinstance(cur_fusion_el, type))
            if fusion_el_is_fun:
                if <MASK>:
                    return False
                if len(cur_node.args) > 0 and isinstance(cur_node.args[0], Node):
                    cur_node = cur_node.args[0]
                else:
                    return False
            else:
                return False
        elif cur_node.op == 'call_module':
            fusion_el_is_mod = isinstance(cur_fusion_el, type)
            if fusion_el_is_mod:
                if not isinstance(cur_node.target, str):
                    raise AssertionError(f'Expected str, got {type(cur_node.target)}')
                target_mod = getattr_from_fqn(gm, cur_node.target)
                if not isinstance(cur_fusion_el, type):
                    return False
                if not isinstance(target_mod, cur_fusion_el):
                    return False
                if len(cur_node.args) > 0 and isinstance(cur_node.args[0], Node):
                    cur_node = cur_node.args[0]
                else:
                    return False
            else:
                return False
        elif cur_node.op == 'call_method':
            fusion_el_is_meth_with_second_arg = isinstance(cur_fusion_el, tuple) and len(cur_fusion_el) == 2
            fusion_el_is_meth_without_args = isinstance(cur_fusion_el, str)
            if fusion_el_is_meth_without_args or fusion_el_is_meth_with_second_arg:
                if fusion_el_is_meth_without_args:
                    if cur_node.target != cur_fusion_el:
                        return False
                else:
                    if not isinstance(cur_fusion_el, tuple):
                        raise AssertionError(f'Expected tuple, got {type(cur_fusion_el)}')
                    if cur_node.target != cur_fusion_el[0]:
                        return False
                    elif len(cur_node.args) < 2:
                        return False
                    elif cur_node.args[1] != cur_fusion_el[1]:
                        return False
                if len(cur_node.args) > 0 and isinstance(cur_node.args[0], Node):
                    cur_node = cur_node.args[0]
                else:
                    return False
            else:
                return False
        else:
            return False
    return True

def __init__(self, data=None, index=None, dtype: Dtype | None=None, name=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if isinstance(data, SingleBlockManager) and index is None and (dtype is None) and (copy is False or copy is None):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        NDFrame.__init__(self, data)
        self.name = name
        return
    if isinstance(data, (ExtensionArray, np.ndarray)):
        if copy is not False:
            if dtype is None or astype_is_view(data.dtype, pandas_dtype(dtype)):
                data = data.copy()
    if copy is None:
        copy = False
    if isinstance(data, SingleBlockManager) and (not copy):
        data = data.copy(deep=False)
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
    name = ibase.maybe_extract_name(name, data, type(self))
    if index is not None:
        index = ensure_index(index)
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if data is None:
        index = index if index is not None else default_index(0)
        if <MASK>:
            data = na_value_for_dtype(pandas_dtype(dtype), compat=False)
        else:
            data = []
    if isinstance(data, MultiIndex):
        raise NotImplementedError('initializing a Series from a MultiIndex is not supported')
    refs = None
    if isinstance(data, Index):
        if dtype is not None:
            data = data.astype(dtype)
        refs = data._references
        copy = False
    elif isinstance(data, np.ndarray):
        if len(data.dtype):
            raise ValueError('Cannot construct a Series from an ndarray with compound dtype.  Use DataFrame instead.')
    elif isinstance(data, Series):
        if index is None:
            index = data.index
            data = data._mgr.copy(deep=False)
        else:
            data = data.reindex(index)
            copy = False
            data = data._mgr
    elif isinstance(data, Mapping):
        (data, index) = self._init_dict(data, index, dtype)
        dtype = None
        copy = False
    elif isinstance(data, SingleBlockManager):
        if index is None:
            index = data.index
        elif not data.index.equals(index) or copy:
            raise AssertionError('Cannot pass both SingleBlockManager `data` argument and a different `index` argument. `copy` must be False.')
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
            allow_mgr = True
    elif isinstance(data, ExtensionArray):
        pass
    else:
        data = com.maybe_iterable_to_list(data)
        if is_list_like(data) and (not len(data)) and (dtype is None):
            dtype = np.dtype(object)
    if index is None:
        if not is_list_like(data):
            data = [data]
        index = default_index(len(data))
    elif is_list_like(data):
        com.require_length_match(data, index)
    if isinstance(data, SingleBlockManager):
        if dtype is not None:
            data = data.astype(dtype=dtype)
        elif copy:
            data = data.copy()
    else:
        data = sanitize_array(data, index, dtype, copy)
        data = SingleBlockManager.from_array(data, index, refs=refs)
    NDFrame.__init__(self, data)
    self.name = name
    self._set_axis(0, index)

def _set_list(self, length, items):
    ndim = self._cs.dims
    hasz = self._cs.hasz
    srid = self.srid
    cs = GEOSCoordSeq(capi.create_cs(length, ndim), z=hasz)
    for (i, c) in enumerate(items):
        cs[i] = c
    ptr = self._init_func(cs.ptr)
    if <MASK>:
        capi.destroy_geom(self.ptr)
        self.ptr = ptr
        if srid is not None:
            self.srid = srid
        self._post_init()
    else:
        raise GEOSException('Geometry resulting from slice deletion was invalid.')

@cached_property
def supports_index_column_ordering(self):
    if self._mysql_storage_engine != 'InnoDB':
        return False
    if <MASK>:
        return self.connection.mysql_version >= (10, 8)
    return True

def annotated_references(obj):
    """
    Return known information about references held by the given object.

    Returns a mapping from referents to lists of descriptions.  Note that there
    may be more than one edge leading to any particular referent; hence the
    need for a list.  Descriptions are currently strings.

    """
    references: dict[int, list[str]] = {}

    def add_reference(name, obj):
        references.setdefault(id(obj), []).append(name)

    def add_attrs(*attrs):
        for attr in attrs:
            if hasattr(obj, attr):
                add_reference(attr, getattr(obj, attr))

    def add_cell_references():
        try:
            add_attrs('cell_contents')
        except ValueError:
            pass

    def add_function_references():
        add_attrs('__defaults__', '__closure__', '__globals__', '__code__', '__name__', '__module__', '__doc____qualname__', '__annotations__', '__kwdefaults__')

    def add_sequence_references():
        for (position, item) in enumerate(obj):
            add_reference(f'[{position}]', item)

    def add_dict_references():
        for (key, value) in obj.items():
            add_reference('key', key)
            add_reference(f'[{repr(key)}]', value)

    def add_set_references():
        for elt in obj:
            add_reference('element', elt)

    def add_bound_method_references():
        add_attrs('__self__', '__func__', 'im_class')

    def add_weakref_references():
        if type(obj) is weakref.ref:
            referents = gc.get_referents(obj)
            if len(referents) == 1:
                target = referents[0]
                add_reference('__callback__', target)

    def add_frame_references():
        f_locals = obj.f_locals
        add_attrs('f_back', 'f_code', 'f_builtins', 'f_globals', 'f_trace', 'f_locals')
        if type(f_locals) is dict:
            for (name, local) in obj.f_locals.items():
                add_reference(f'local {name}', local)

    def add_getset_descriptor_references():
        add_attrs('__objclass__', '__name__', '__doc__')
    type_based_references = {tuple: add_sequence_references, list: add_sequence_references, dict: add_dict_references, set: add_set_references, frozenset: add_set_references, types.FunctionType: add_function_references, types.FrameType: add_frame_references, CellType: add_cell_references, types.MethodType: add_bound_method_references, weakref.ref: add_weakref_references, types.GetSetDescriptorType: add_getset_descriptor_references}
    for type_ in type(obj).__mro__:
        if type_ in type_based_references:
            type_based_references[type_]()
    add_attrs('__dict__', '__class__')
    if <MASK>:
        add_attrs('__mro__')
    return references

def _get_data_buffer(self) -> tuple[Buffer, tuple[DtypeKind, int, str, str]]:
    """
        Return the buffer containing the data and the buffer's associated dtype.
        """
    buffer: Buffer
    if self.dtype[0] == DtypeKind.DATETIME:
        if len(self.dtype[2]) > 4:
            np_arr = self._col.dt.tz_convert(None).to_numpy()
        else:
            np_arr = self._col.to_numpy()
        buffer = PandasBuffer(np_arr, allow_copy=self._allow_copy)
        dtype = (DtypeKind.INT, 64, ArrowCTypes.INT64, Endianness.NATIVE)
    elif self.dtype[0] in (DtypeKind.INT, DtypeKind.UINT, DtypeKind.FLOAT, DtypeKind.BOOL):
        dtype = self.dtype
        arr = self._col.array
        if isinstance(self._col.dtype, ArrowDtype):
            arr = arr._pa_array.chunks[0]
            buffer = PandasBufferPyarrow(arr.buffers()[1], length=len(arr))
            return (buffer, dtype)
        if isinstance(self._col.dtype, BaseMaskedDtype):
            np_arr = arr._data
        else:
            np_arr = arr._ndarray
        buffer = PandasBuffer(np_arr, allow_copy=self._allow_copy)
    elif <MASK>:
        codes = self._col.values._codes
        buffer = PandasBuffer(codes, allow_copy=self._allow_copy)
        dtype = self._dtype_from_pandasdtype(codes.dtype)
    elif self.dtype[0] == DtypeKind.STRING:
        buf = self._col.to_numpy()
        b = bytearray()
        for obj in buf:
            if isinstance(obj, str):
                b.extend(obj.encode(encoding='utf-8'))
        buffer = PandasBuffer(np.frombuffer(b, dtype='uint8'))
        dtype = (DtypeKind.UINT, 8, ArrowCTypes.UINT8, Endianness.NATIVE)
    else:
        raise NotImplementedError(f'Data type {self._col.dtype} not handled yet')
    return (buffer, dtype)

def get_shape_tensor(s):
    if <MASK>:
        return make_shape_tensor(s)
    if s.is_fully_defined():
        return make_shape_tensor(s.as_list())
    raise ValueError('Cannot broadcast from partially defined `TensorShape`.')

@cache_readonly
def _engine(self) -> libindex.IndexEngine | libindex.ExtensionEngine | libindex.MaskedIndexEngine:
    target_values = self._get_engine_target()
    if isinstance(self._values, ArrowExtensionArray) and self.dtype.kind in 'Mm':
        import pyarrow as pa
        pa_type = self._values._pa_array.type
        if pa.types.is_timestamp(pa_type):
            target_values = self._values._to_datetimearray()
            return libindex.DatetimeEngine(target_values._ndarray)
        elif pa.types.is_duration(pa_type):
            target_values = self._values._to_timedeltaarray()
            return libindex.TimedeltaEngine(target_values._ndarray)
    if isinstance(target_values, ExtensionArray):
        if isinstance(target_values, (BaseMaskedArray, ArrowExtensionArray)):
            try:
                return _masked_engines[target_values.dtype.name](target_values)
            except KeyError:
                pass
        elif self._engine_type is libindex.ObjectEngine:
            return libindex.ExtensionEngine(target_values)
    target_values = cast(np.ndarray, target_values)
    if target_values.dtype == bool:
        return libindex.BoolEngine(target_values)
    elif target_values.dtype == np.complex64:
        return libindex.Complex64Engine(target_values)
    elif target_values.dtype == np.complex128:
        return libindex.Complex128Engine(target_values)
    elif <MASK>:
        target_values = self._data._ndarray
    elif is_string_dtype(self.dtype) and (not is_object_dtype(self.dtype)):
        return libindex.StringObjectEngine(target_values, self.dtype.na_value)
    return self._engine_type(target_values)

@classmethod
def eval(cls, *args):
    if len(args) % 2 != 0:
        raise AssertionError(f'expected an even number of arguments, got {len(args)}')
    dim = len(args) // 2
    sizes = args[0:dim]
    strides = args[dim:]
    from torch.fx.experimental.symbolic_shapes import eval_is_non_overlapping_and_dense
    if all((isinstance(a, sympy.Integer) for a in args)):
        return eval_is_non_overlapping_and_dense([int(a) for a in sizes], [int(a) for a in strides])
    if dim == 1:
        if strides[0].is_Number and strides[0] == 1:
            return 1
        if sizes[0].is_Number and sizes[0] < 2:
            return 1
    if <MASK>:
        if dim == 0:
            raise AssertionError('dim must not be zero')
        (s_sizes, s_strides) = zip(*sorted(zip(sizes, strides), key=operator.itemgetter(1)))
        if all((isinstance(a, sympy.Integer) for a in s_sizes[:-1])):
            s_sizes = s_sizes[:-1] + (42,)
            return eval_is_non_overlapping_and_dense([int(a) for a in s_sizes], [int(a) for a in s_strides])
    return None

def prepare_url(self, url, params):
    """Prepares the given HTTP URL."""
    if isinstance(url, bytes):
        url = url.decode('utf8')
    else:
        url = str(url)
    url = url.lstrip()
    if <MASK>:
        self.url = url
        return
    try:
        (scheme, auth, host, port, path, query, fragment) = parse_url(url)
    except LocationParseError as e:
        raise InvalidURL(*e.args)
    if not scheme:
        raise MissingSchema(f'Invalid URL {url!r}: No scheme supplied. Perhaps you meant https://{url}?')
    if not host:
        raise InvalidURL(f'Invalid URL {url!r}: No host supplied')
    if not unicode_is_ascii(host):
        try:
            host = self._get_idna_encoded_host(host)
        except UnicodeError:
            raise InvalidURL('URL has an invalid label.')
    elif host.startswith(('*', '.')):
        raise InvalidURL('URL has an invalid label.')
    netloc = auth or ''
    if netloc:
        netloc += '@'
    netloc += host
    if port:
        netloc += f':{port}'
    if not path:
        path = '/'
    if isinstance(params, (str, bytes)):
        params = to_native_string(params)
    enc_params = self._encode_params(params)
    if enc_params:
        if query:
            query = f'{query}&{enc_params}'
        else:
            query = enc_params
    url = requote_uri(urlunparse([scheme, netloc, path, None, query, fragment]))
    self.url = url

def _avg_poolnd(x, kernel_size, stride, padding, ceil_mode, count_include_pad, divisor_override, dim):
    if <MASK>:
        stride = kernel_size
    if not padding:
        padding = [0] * dim
    kernel_size = pad_listlike(kernel_size, dim)
    stride = pad_listlike(stride, dim)
    padding = pad_listlike(padding, dim)
    assert isinstance(x, TensorBox)
    assert len(kernel_size) == dim
    assert len(stride) == dim
    assert len(padding) == dim
    assert len(x.get_size()) in (dim + 1, dim + 2)
    x.realize_hint()
    batch = x.get_size()[:-dim]
    h = x.get_size()[-dim:]
    (h_out, ceil_modes) = zip(*[pooling_size(h[i], i, kernel_size, stride, padding, ceil_mode) for i in range(dim)])
    if any(padding) or any(ceil_modes):
        x_loader = constant_boundary_condition(x, 0.0, dim=dim)
        had_padding = True
    else:
        x_loader = x.make_loader()
        had_padding = False
    new_size = list(batch) + list(h_out)
    dtype = x.get_dtype()
    window_size = functools.reduce(operator.mul, kernel_size)
    if window_size > 25:
        if dim == 2:
            fallback = fallback_avg_pool2d
        elif dim == 3:
            fallback = fallback_avg_pool3d
        else:
            raise ValueError(f'Unknown dim: {dim}')
        return fallback(x, kernel_size, stride, padding, ceil_mode, count_include_pad, divisor_override)

    def fn_sum(idx, loader):
        prefix = idx[:-dim]
        b = idx[-dim:]
        total = None
        for ih in itertools.product(*[range(kernel_size[i]) for i in range(dim)]):
            inp = [b[i] * stride[i] + ih[i] - padding[i] for i in range(dim)]
            val = loader([*prefix, *inp])
            if total is None:
                total = val
            else:
                total = ops.add(val, total)
        return total
    if not had_padding or divisor_override:
        divisor = divisor_override if divisor_override else window_size
        if dtype.is_floating_point:
            scale = 1 / divisor

            def fn(idx):
                return ops.mul(fn_sum(idx, x_loader), ops.constant(scale, dtype))
        else:

            def fn(idx):
                return ops.truncdiv(fn_sum(idx, x_loader), ops.constant(divisor, dtype))
    else:

        def fn(idx):
            bh = idx[-dim:]
            divide_factors = []
            for i in range(dim):
                hstart = bh[i] * stride[i] - padding[i]
                hend = sympy.Min(hstart + kernel_size[i], h[i] + padding[i])
                if not count_include_pad:
                    hstart = sympy.Max(hstart, 0)
                    hend = sympy.Min(hend, h[i])
                factor = ops.index_expr(hend - hstart, torch.int32)
                divide_factors.append(factor)
            divide_factor = functools.reduce(ops.mul, divide_factors)
            if dtype.is_floating_point:
                return ops.truediv(fn_sum(idx, x_loader), divide_factor)
            return ops.truncdiv(fn_sum(idx, x_loader), divide_factor)
    rv = Pointwise.create(device=x.get_device(), dtype=dtype, inner_fn=fn, ranges=new_size)
    return rv

def get_query_string(self, new_params=None, remove=None):
    if new_params is None:
        new_params = {}
    if remove is None:
        remove = []
    p = self.filter_params.copy()
    for r in remove:
        for k in list(p):
            if <MASK>:
                del p[k]
    for (k, v) in new_params.items():
        if v is None:
            if k in p:
                del p[k]
        else:
            p[k] = v
    return '?%s' % urlencode(sorted(p.items()), doseq=True)

@register_annotator('add')
def _annotate_add(gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[Callable[[Node], bool]]=None) -> Optional[list[list[Node]]]:
    annotated_partitions = []
    for node in gm.graph.nodes:
        if node.op != 'call_function' or node.target not in [torch.ops.aten.add.Tensor, torch.ops.aten.add_.Tensor]:
            continue
        add_node = node
        partition = [add_node]
        if _is_annotated(partition):
            continue
        if filter_fn and any((not filter_fn(n) for n in partition)):
            continue
        input_act_qspec = get_input_act_qspec(quantization_config)
        output_act_qspec = get_output_act_qspec(quantization_config)
        input_qspec_map = {}
        input_act0 = add_node.args[0]
        if isinstance(input_act0, Node):
            if _is_input_large_scalar(input_act0, gm):
                continue
            if _is_input_non_float_tensor(input_act0):
                continue
            input_qspec_map[input_act0] = input_act_qspec
            partition.append(input_act0)
        input_act1 = add_node.args[1]
        if isinstance(input_act1, Node):
            if <MASK>:
                continue
            if _is_input_non_float_tensor(input_act1):
                continue
            input_qspec_map[input_act1] = input_act_qspec
            partition.append(input_act1)
        add_node.meta['quantization_annotation'] = QuantizationAnnotation(input_qspec_map=input_qspec_map, output_qspec=output_act_qspec, _annotated=True)
        annotated_partitions.append(partition)
    return annotated_partitions

def node_summary(snode):
    snodes = snode.get_nodes()
    if len(snodes) == 1:
        detail = ''
        if <MASK>:
            outs_str = f'outs:{[o.get_name() for o in snode.get_outputs()]}'
            ins_str = f'ins:{[d.name for d in snode.unmet_dependencies]}'
            detail = f' {snode.get_name()} ({snode.node.python_kernel_name})\n {outs_str}\n ({ins_str})'
        layouts = [child.node.get_output_spec() for child in snode.get_nodes()]
        out_tensor_info = ','.join([f' (size={layout.size}, stride={layout.stride})' if isinstance(layout, ir.Layout) else '' for layout in layouts])
        try:
            node_name = snode.node.maybe_get_name()
        except AttributeError:
            node_name = ''
        return f'{snode.node.__class__.__name__}{detail}{out_tensor_info} ({node_name} ({snode.get_estimated_runtime():.0f} ns)'
    summaries = []
    for child_snode in snodes:
        summaries.append(node_summary(child_snode))
    return f"{snode.__class__.__name__}: {', '.join(summaries)}"

def run_node(self, node: torch.fx.Node) -> Any:
    if node.target == 'output':

        def set_env(arg: torch.fx.Node) -> None:
            self.env[arg] = self.unknown_value
        pytree.tree_map_only_(torch.fx.Node, set_env, node.args)
        return super().run_node(node)
    (args, kwargs) = self.fetch_args_kwargs_from_env(node)
    flattened_inputs = pytree.arg_tree_leaves(*args, **kwargs)
    if any((type(self.unknown_value) is type(input_) and self.unknown_value == input_ for input_ in flattened_inputs)):
        return self.unknown_value
    if node.op == 'call_function' and node.target == aten._efficientzerotensor.default:
        return self.unknown_value
    if node.op == 'call_function' and node.name == 'triton_kernel_wrapper_functional_proxy':
        return self.unknown_value
    if self.skip_constructors and (not is_const_source(node, self.lifted_constant_names)) and (not any((isinstance(e, torch.Tensor) for e in flattened_inputs))):
        return self.unknown_value
    if isinstance(node.target, torch._ops.OpOverload) and torch.Tag.nondeterministic_seeded in node.target.tags:
        return self.unknown_value
    if node.op == 'call_function' and isinstance(node.target, torch._ops.HigherOrderOperator):
        return self.unknown_value
    out = self._deduce_value(node)
    if isinstance(out, torch._C.ScriptObject):
        return out
    if out == self.unknown_value:
        return self.unknown_value
    if not is_const_source(node, self.lifted_constant_names) and (isinstance(out, torch.Tensor) or out == self.deferred_value):
        if <MASK>:
            return out
        if not self.insertable_tensor_check(out):
            return out
        if self.is_impure(node):
            return self.unknown_value
        self.add_node_replacement(node, out)
        flattened_node_inps = pytree.arg_tree_leaves(*node.args, **node.kwargs)
        for n in flattened_node_inps:
            if not isinstance(n, torch.fx.Node):
                continue
            self.replaced_uses[n] += 1
        for to_delete in self.user_to_last_uses.get(node, []):
            if self.replaced_uses[to_delete] == len(to_delete.users):
                self.node_replacements.pop(to_delete, None)
    return out

