def capture_provenance(fn):

    @functools.wraps(fn)
    def wrapper(self, other=None):
        if other is None:
            result = fn(self)
        else:
            result = fn(self, other)
        if torch._logging._internal.GET_DTRACE_STRUCTURED:
            if other is not None:
                arguments = [self, other]
            else:
                arguments = [self]

            def get_id(sym_node) -> Optional[int]:
                import sympy
                if sym_node.constant is not None:
                    return None
                elif id(sym_node) == id(result):
                    return None
                elif <MASK>:
                    return None
                elif sym_node.expr in (sympy.true, sympy.false):
                    return None
                return id(sym_node)
            dtrace_structured('expression_created', metadata_fn=lambda : {'method': method, 'result': str(result), 'result_id': id(result), 'arguments': [str(a) for a in arguments], 'argument_ids': [get_id(i) for i in arguments if get_id(i) is not None], 'user_stack': structured.get_user_stack(3), 'stack': structured.get_framework_stack(3)})
        return result
    return wrapper

def read(self, nrows: int | None=None) -> DataFrame:
    if nrows is None and self.chunksize is not None:
        nrows = self.chunksize
    elif nrows is None:
        nrows = self.row_count
    if len(self._column_types) == 0:
        self.close()
        raise EmptyDataError('No columns to parse from file')
    if nrows > 0 and self._current_row_in_file_index >= self.row_count:
        return DataFrame()
    nrows = min(nrows, self.row_count - self._current_row_in_file_index)
    nd = self._column_types.count(b'd')
    ns = self._column_types.count(b's')
    self._string_chunk = np.empty((ns, nrows), dtype=object)
    self._byte_chunk = np.zeros((nd, 8 * nrows), dtype=np.uint8)
    self._current_row_in_chunk_index = 0
    p = Parser(self)
    p.read(nrows)
    rslt = self._chunk_to_dataframe()
    if <MASK>:
        rslt = rslt.set_index(self.index)
    return rslt

def dynamic_int_impl(*args):
    args = [x.real if isinstance(x, DynamicInt) else x for x in args]
    out = getattr(int, attr)(*args)
    if <MASK>:
        return DynamicInt(out)
    return out

def consistent(a, b):
    """It is possible for an argument list to satisfy both A and B"""
    if not a:
        return not b or isvariadic(b[0])
    if not b:
        return not a or isvariadic(a[0])
    if <MASK>:
        return all((issubclass(aa, bb) or issubclass(bb, aa) for (aa, bb) in zip(a, b)))
    else:
        p1 = 0
        p2 = 0
        while p1 < len(a) and p2 < len(b):
            cur_a = a[p1]
            cur_b = b[p2]
            if not issubclass(cur_b, cur_a) and (not issubclass(cur_a, cur_b)):
                return False
            if not (isvariadic(cur_a) or isvariadic(cur_b)):
                p1 += 1
                p2 += 1
            elif isvariadic(cur_a):
                p2 += 1
            elif isvariadic(cur_b):
                p1 += 1
        return isvariadic(cur_a) and p2 == len(b) or (isvariadic(cur_b) and p1 == len(a))

def has_perms(self, perm_list, obj=None):
    """
        Return True if the user has each of the specified permissions. If
        object is passed, check if the user has all required perms for it.
        """
    if <MASK>:
        raise ValueError('perm_list must be an iterable of permissions.')
    return all((self.has_perm(perm, obj) for perm in perm_list))

def get_block_size(input_shape: tuple[int, ...], granularity: Granularity) -> tuple[int, ...]:
    """Get the block size based on the input shape and granularity type.

    Args:
        input_shape: The input tensor shape possibly more than 2 dimensions
        granularity: The granularity type of the quantization
    """
    assert isinstance(granularity, Granularity), 'Please provide an instance of Granularity, not subclass of it'
    if isinstance(granularity, PerTensor):
        return input_shape
    elif isinstance(granularity, PerAxis):
        block_size = list(input_shape)
        block_size[granularity.axis] = 1
        return tuple(block_size)
    elif isinstance(granularity, PerRow):
        return (1,) * (len(input_shape) - 1) + (input_shape[-1],)
    elif isinstance(granularity, PerGroup):
        assert len(input_shape) == 2, f'Expecting input shape dim to be 2 for per group quantization, gotinput shape: {input_shape}'
        return (1, granularity.group_size)
    elif <MASK>:
        block_size = [1] * len(input_shape)
        block_size[-1] = input_shape[-1]
        return tuple(block_size)
    raise ValueError(f'Unsupported Granularity: {granularity}')

@disable_if_config_true
def _post_forward(self, module: nn.Module, input: Any, output: Any) -> Any:
    if self._training_state == TrainingState.PRE_BACKWARD:
        return output
    if self._fsdp_param_group:
        output = self._fsdp_param_group.post_forward(module, input, output)
    output = self._register_pre_backward_hook(output)
    self._training_state = TrainingState.IDLE
    if self._state_ctx.iter_forward_root is self:
        if <MASK>:
            self._comm_ctx.all_gather_copy_in_stream.wait_event(all_gather_state.event)
            self._comm_ctx.all_gather_stream.wait_event(all_gather_state.event)
            self._comm_ctx.all_gather_state = None
        self._state_ctx.iter_forward_root = None
    if self._mp_policy.output_dtype is not None:
        with torch.profiler.record_function('FSDP::cast_forward_outputs'):
            output = _apply_to_tensors(functools.partial(_cast_fp_tensor, self._mp_policy.output_dtype), output)
    return output

@tf_export(v1=['assert_variables_initialized'])
@tf_should_use.should_use_result
def assert_variables_initialized(var_list=None):
    """Returns an Op to check if variables are initialized.

  NOTE: This function is obsolete and will be removed in 6 months.  Please
  change your implementation to use `report_uninitialized_variables()`.

  When run, the returned Op will raise the exception `FailedPreconditionError`
  if any of the variables has not yet been initialized.

  Note: This function is implemented by trying to fetch the values of the
  variables. If one of the variables is not initialized a message may be
  logged by the C++ runtime. This is expected.

  Args:
    var_list: List of `Variable` objects to check. Defaults to the value of
      `global_variables().`

  Returns:
    An Op, or None if there are no variables.
  """
    if var_list is None:
        var_list = global_variables() + local_variables()
    if <MASK>:
        var_list = []
        for op in ops.get_default_graph().get_operations():
            if op.type in ['Variable', 'VariableV2', 'AutoReloadVariable']:
                var_list.append(op.outputs[0])
    if not var_list:
        return None
    else:
        ranks = []
        for var in var_list:
            with ops.colocate_with(var.op):
                ranks.append(array_ops.rank_internal(var, optimize=False))
        if len(ranks) == 1:
            return ranks[0]
        else:
            return array_ops_stack.stack(ranks)

def _maybe_build_distributed_table(self):
    """Create table objects and resources on each worker if hasn't been created."""
    with self._distributed_table_creation_lock:
        if not self._distributed_table:

            def create_copy():
                new_table = self._wrapped_creator()
                with self._has_resource_functions:
                    while not hasattr(self, '_restored_function') or any((method not in self._restored_function for method in TRACKABLE_RESOURCE_METHODS)):
                        self._has_resource_functions.wait()
                if <MASK>:
                    with with_local_resource_restore_context(new_table):
                        for (name, tf_function) in self._restored_function.items():
                            setattr(new_table, name, tf_function)
                        init_op = new_table._initialize()
                        if not context.executing_eagerly():
                            ops.add_to_collection(ops.GraphKeys.TABLE_INITIALIZERS, init_op)
                ret = new_table.resource_handle
                return ret
            self._distributed_table = self._coordinator._create_per_worker_resources(create_copy)

