def is_subtype_of(self, other):
    """See base class."""
    if type(self) is not type(other):
        return False
    try:
        tf_nest.assert_same_structure(self.element_spec, other.element_spec)
    except (TypeError, ValueError):
        return False
    self_elements = tf_nest.flatten(self.element_spec)
    other_elements = tf_nest.flatten(other.element_spec)

    def is_subtype_or_equal(a, b):
        if isinstance(a, trace.TraceType):
            return a.is_subtype_of(b)
        else:
            return a == b
    for (self_element, other_element) in zip(self_elements, other_elements):
        if <MASK>:
            return False
    return self._dataset_shape.is_subtype_of(other._dataset_shape)

@no_type_check
@torch.no_grad()
def _use_sharded_views(self) -> None:
    """
        Set the original parameter variables' data to be flattened views into the sharded flat parameter.

        The views are kept as flattened to simplify the case where a parameter
        is sharded across ranks. Parameters whose data is not present in the
        sharded flat parameter have their data set to a size-0 empty tensor. We
        do not delete them to ensure to preserve expected behaviors like model
        printability. Parameters whose data is present must preserve their
        variables to be passable to an optimizer.
        """
    self._unsharded_flat_param_for_skipped_views = None
    if not self.uses_sharded_strategy:
        self._use_unsharded_views(as_params=True)
        return
    flat_param = self.flat_param
    self._check_sharded(flat_param)
    size_0_empty_tensor = torch.empty(0, dtype=self.flat_param.dtype, device=self.flat_param.device, requires_grad=False)
    for (param, shard_param_info, (param_name, module, _)) in zip(flat_param._params, flat_param._shard_param_infos, flat_param._param_infos):
        self._setattr_param(module, param_name, param)
        if <MASK>:
            param.data = size_0_empty_tensor
        else:
            offset = shard_param_info.offset_in_shard
            numel_in_shard = shard_param_info.numel_in_shard
            param.data = flat_param[offset:offset + numel_in_shard]
    if self.flat_param._shared_params is None:
        raise AssertionError('Expected _shared_params to be not None')
    for (i, (param, (param_name, module, _, prim_param_name, prim_module, _))) in enumerate(zip(self.flat_param._shared_params, self.flat_param._shared_param_infos)):
        self._setattr_param(module, param_name, param)
        prim_param = getattr(prim_module, prim_param_name)
        param.data = prim_param
    if self._training_state == HandleTrainingState.BACKWARD_POST:
        for i in range(len(self.flat_param._tensors)):
            self.flat_param._tensors[i] = None

def histogramdd(sample, bins=10, range: Optional[ArrayLike]=None, normed=None, weights: Optional[ArrayLike]=None, density=None):
    if normed is not None:
        raise ValueError('normed argument is deprecated, use density= instead')
    from ._normalizations import normalize_array_like, normalize_seq_array_like
    if isinstance(sample, (list, tuple)):
        sample = normalize_array_like(sample).T
    else:
        sample = normalize_array_like(sample)
    sample = torch.atleast_2d(sample)
    if not (sample.dtype.is_floating_point or sample.dtype.is_complex):
        sample = sample.double()
    bins_is_array = not (isinstance(bins, int) or builtins.all((isinstance(b, int) for b in bins)))
    if <MASK>:
        bins = normalize_seq_array_like(bins)
        bins_dtypes = [b.dtype for b in bins]
        bins = [_util.cast_if_needed(b, sample.dtype) for b in bins]
    if range is not None:
        range = range.flatten().tolist()
    if weights is not None:
        mm = sample.aminmax(dim=0)
        range = torch.cat(mm).reshape(2, -1).T.flatten()
        range = tuple(range.tolist())
        weights = _util.cast_if_needed(weights, sample.dtype)
        w_kwd = {'weight': weights}
    else:
        w_kwd = {}
    (h, b) = torch.histogramdd(sample, bins, range, density=bool(density), **w_kwd)
    if bins_is_array:
        b = [_util.cast_if_needed(bb, dtyp) for (bb, dtyp) in zip(b, bins_dtypes)]
    return (h, b)

def _validate_transformers(self):
    """Validate names of transformers and the transformers themselves.

        This checks whether given transformers have the required methods, i.e.
        `fit` or `fit_transform` and `transform` implemented.
        """
    if not self.transformers:
        return
    (names, transformers, _) = zip(*self.transformers)
    self._validate_names(names)
    for t in transformers:
        if <MASK>:
            continue
        if not (hasattr(t, 'fit') or hasattr(t, 'fit_transform')) or not hasattr(t, 'transform'):
            raise TypeError("All estimators should implement fit and transform, or can be 'drop' or 'passthrough' specifiers. '%s' (type %s) doesn't." % (t, type(t)))

def _clone_sequential_model(model, input_tensors=None, layer_fn=_clone_layer):
    """Clone a `Sequential` model instance.

  Model cloning is similar to calling a model on new inputs,
  except that it creates new layers (and thus new weights) instead
  of sharing the weights of the existing layers.

  Args:
      model: Instance of `Sequential`.
      input_tensors: optional list of input tensors
          to build the model upon. If not provided,
          placeholders will be created.
      layer_fn: callable to be applied on non-input layers in the model. By
          default it clones the layer. Another example is to preserve the layer
          to share the weights. This is required when we create a per-replica
          copy of the model with distribution strategy; we want the weights to
          be shared but still feed inputs separately so we create new input
          layers.

  Returns:
      An instance of `Sequential` reproducing the behavior
      of the original model, on top of new inputs tensors,
      using newly instantiated weights.

  Raises:
      ValueError: in case of invalid `model` argument value or `layer_fn`
      argument value.
  """
    if not isinstance(model, Sequential):
        raise ValueError('Expected `model` argument to be a `Sequential` model instance, but got:', model)
    if not callable(layer_fn):
        raise ValueError('Expected `layer_fn` argument to be a callable.')
    layers = []
    layer_map = {}
    for layer in model._flatten_layers(include_self=False, recursive=False):
        if isinstance(layer, InputLayer) and input_tensors is not None:
            continue
        cloned_layer = _clone_layer(layer) if isinstance(layer, InputLayer) else layer_fn(layer)
        layers.append(cloned_layer)
        layer_map[layer] = cloned_layer
    (layers, ancillary_layers) = _remove_ancillary_layers(model, layer_map, layers)
    if input_tensors is None:
        cloned_model = Sequential(layers=layers, name=model.name)
    elif len(generic_utils.to_list(input_tensors)) != 1:
        raise ValueError('To clone a `Sequential` model, we expect  at most one tensor as part of `input_tensors`.')
    else:
        if isinstance(input_tensors, tuple):
            input_tensors = list(input_tensors)
        x = generic_utils.to_list(input_tensors)[0]
        if backend.is_keras_tensor(x):
            origin_layer = x._keras_history.layer
            if isinstance(origin_layer, InputLayer):
                cloned_model = Sequential(layers=[origin_layer] + layers, name=model.name)
            else:
                raise ValueError('Cannot clone a `Sequential` model on top of a tensor that comes from a Keras layer other than an `InputLayer`. Use the functional API instead.')
        else:
            input_tensor = Input(tensor=x, name='input_wrapper_for_' + str(x.name))
            input_layer = input_tensor._keras_history.layer
            cloned_model = Sequential(layers=[input_layer] + layers, name=model.name)
    if not ancillary_layers:
        return cloned_model
    tensor_map = {}
    for (depth, cloned_nodes) in cloned_model._nodes_by_depth.items():
        nodes = model._nodes_by_depth[depth]
        for (cloned_node, node) in zip(cloned_nodes, nodes):
            if <MASK>:
                for (j, output_tensor) in enumerate(cloned_node.output_tensors):
                    tensor_map[node.output_tensors[j]] = output_tensor
            else:
                tensor_map[node.output_tensors] = cloned_node.output_tensors
    new_nodes = _make_new_nodes({depth: nodes for (depth, nodes) in model._nodes_by_depth.items() if depth < 0}, layer_fn, layer_map, tensor_map)
    _insert_ancillary_layers(cloned_model, ancillary_layers, model.metrics_names, new_nodes)
    return cloned_model

def testMethodExtensionType(self):

    class MaskedTensorExtensionType(extension_type.ExtensionType):
        values: tensor_lib.Tensor
        mask: tensor_lib.Tensor

        @polymorphic_function.function
        def with_default(self, default_value):
            return array_ops.where_v2(self.mask, self.values, default_value)

        @polymorphic_function.function
        def sum(self):
            result = 0
            for i in range(array_ops.size(self.values)):
                if <MASK>:
                    result += self.values[i]
            return result
    mt = MaskedTensorExtensionType([1, 2, 3], [True, False, True])
    self.assertAllEqual(mt.with_default(-1), [1, -1, 3])
    self.assertAllEqual(mt.sum(), 4)

def _tensor_to_argdef(t, name=None, used_names=None):
    """Convert tensor t to an argdef, with a specified name or a unique name."""
