def _pool_seed_transformer(parent, node, full_name, name, logs):
    """Removes seed2 and deterministic, and adds non-zero seed if needed."""
    seed_arg = None
    deterministic = False
    modified = False
    new_keywords = []
    for kw in node.keywords:
        if sys.version_info[:2] >= (3, 5) and isinstance(kw, ast.Starred):
            pass
        elif kw.arg == 'seed':
            seed_arg = kw
        elif kw.arg == 'seed2' or kw.arg == 'deterministic':
            lineno = getattr(kw, 'lineno', node.lineno)
            col_offset = getattr(kw, 'col_offset', node.col_offset)
            logs.append((ast_edits.INFO, lineno, col_offset, 'Removed argument %s for function %s' % (kw.arg, full_name or name)))
            if kw.arg == 'deterministic':
                if not _is_ast_false(kw.value):
                    deterministic = True
            modified = True
            continue
        new_keywords.append(kw)
    if deterministic:
        if seed_arg is None:
            new_keywords.append(ast.keyword(arg='seed', value=ast.Num(42)))
            logs.add((ast_edits.INFO, node.lineno, node.col_offset, 'Adding seed=42 to call to %s since determinism was requested' % (full_name or name)))
        else:
            logs.add((ast_edits.WARNING, node.lineno, node.col_offset, 'The deterministic argument is deprecated for %s, pass a non-zero seed for determinism. The deterministic argument is present, possibly not False, and the seed is already set. The converter cannot determine whether it is nonzero, please check.'))
    if <MASK>:
        node.keywords = new_keywords
        return node
    else:
        return

def _in1d(ar1, ar2, xp, assume_unique=False, invert=False):
    """Checks whether each element of an array is also present in a
    second array.

    Returns a boolean array the same length as `ar1` that is True
    where an element of `ar1` is in `ar2` and False otherwise.

    This function has been adapted using the original implementation
    present in numpy:
    https://github.com/numpy/numpy/blob/v1.26.0/numpy/lib/arraysetops.py#L524-L758
    """
    (xp, _) = get_namespace(ar1, ar2, xp=xp)
    if ar2.shape[0] < 10 * ar1.shape[0] ** 0.145:
        if invert:
            mask = xp.ones(ar1.shape[0], dtype=xp.bool, device=device(ar1))
            for a in ar2:
                mask &= ar1 != a
        else:
            mask = xp.zeros(ar1.shape[0], dtype=xp.bool, device=device(ar1))
            for a in ar2:
                mask |= ar1 == a
        return mask
    if <MASK>:
        (ar1, rev_idx) = xp.unique_inverse(ar1)
        ar2 = xp.unique_values(ar2)
    ar = xp.concat((ar1, ar2))
    device_ = device(ar)
    order = xp.argsort(ar, stable=True)
    reverse_order = xp.argsort(order, stable=True)
    sar = xp.take(ar, order, axis=0)
    if size(sar) >= 1:
        bool_ar = sar[1:] != sar[:-1] if invert else sar[1:] == sar[:-1]
    else:
        bool_ar = xp.asarray([False]) if invert else xp.asarray([True])
    flag = xp.concat((bool_ar, xp.asarray([invert], device=device_)))
    ret = xp.take(flag, reverse_order, axis=0)
    if assume_unique:
        return ret[:ar1.shape[0]]
    else:
        return xp.take(ret, rev_idx, axis=0)

def _getitem_axis(self, key, axis: AxisInt):
    key = item_from_zerodim(key)
    if is_iterator(key):
        key = list(key)
    if key is Ellipsis:
        key = slice(None)
    labels = self.obj._get_axis(axis)
    if isinstance(key, tuple) and isinstance(labels, MultiIndex):
        key = tuple(key)
    if <MASK>:
        self._validate_key(key, axis)
        return self._get_slice_axis(key, axis=axis)
    elif com.is_bool_indexer(key):
        return self._getbool_axis(key, axis=axis)
    elif is_list_like_indexer(key):
        if not (isinstance(key, tuple) and isinstance(labels, MultiIndex)):
            if hasattr(key, 'ndim') and key.ndim > 1:
                raise ValueError('Cannot index with multidimensional key')
            return self._getitem_iterable(key, axis=axis)
        if is_nested_tuple(key, labels):
            locs = labels.get_locs(key)
            indexer: list[slice | npt.NDArray[np.intp]] = [slice(None)] * self.ndim
            indexer[axis] = locs
            return self.obj.iloc[tuple(indexer)]
    self._validate_key(key, axis)
    return self._get_label(key, axis=axis)

def set_sync_debug_mode(debug_mode: Union[int, str]) -> None:
    """Set the debug mode for cuda synchronizing operations.

    Args:
        debug_mode(str or int): if "default" or 0, don't error or warn on synchronizing operations,
            if "warn" or 1, warn on synchronizing operations, if "error" or 2, error out synchronizing operations.

    Warning:
        This is an experimental feature, and not all synchronizing operations will trigger warning or error. In
        particular, operations in torch.distributed and torch.sparse namespaces are not covered yet.
    """
    _lazy_init()
    if <MASK>:
        if debug_mode == 'default':
            debug_mode = 0
        elif debug_mode == 'warn':
            debug_mode = 1
        elif debug_mode == 'error':
            debug_mode = 2
        else:
            raise RuntimeError('invalid value of debug_mode, expected one of `default`, `warn`, `error`')
    torch._C._cuda_set_sync_debug_mode(debug_mode)

def generate_fallback_kernel_with_runtime_lookup(self, buf_name: str, python_kernel_name: str, get_args: Callable[[], Sequence[str]], op_overload: Union[torch._ops.OpOverload, torch._ops.HigherOrderOperator], raw_args: Sequence[Any], outputs: Sequence[ir.Buffer]) -> None:
    """Generate a call to a kernel not contained in the C-shim.  This results in
        different code paths for AOT Inductor vs cpp_wrapper Inductor mode."""

    def extract_output_name(out: Optional[Union[ir.Buffer, Sequence[ir.Buffer]]]) -> Union[Optional[str], _OUTPUT_ARGS_TYPE]:
        if out is None:
            return None
        if isinstance(out, (ir.MultiOutput, ir._CollectiveKernel)):
            return out.get_name()
        if isinstance(out, ir.MutationOutput):
            mutated_buf_names = out.get_mutation_names()
            assert isinstance(mutated_buf_names, list) and len(mutated_buf_names) == 1, 'Expect only one mutated buffer in MutationOutput'
            return mutated_buf_names[0]
        if isinstance(out, (list, tuple)):
            return [extract_output_name(o) for o in out]
        if isinstance(out, int):
            return str(out)
        raise AssertionError(f'Unexpected output: {type(out)}')
    if isinstance(op_overload, torch._ops.HigherOrderOperator):
        assert isinstance(op_overload, torch._higher_order_ops.torchbind.CallTorchBind), type(op_overload)
        assert len(raw_args) > 1
        obj = raw_args[0]
        method = raw_args[1]
        return_schema = op_overload.schema(obj, method).returns
    else:
        return_schema = op_overload._schema.returns
    if not return_schema:
        output_args: _OUTPUT_ARGS_TYPE = []
    elif <MASK>:
        output_args = [output_name]
    else:
        assert isinstance(output_name, list), type(output_name)
        output_args = output_name
    if V.graph.aot_mode:
        self.generate_fallback_kernel_with_runtime_lookup_aot(op_overload, raw_args, output_args, outputs)
        return
    assert isinstance(op_overload, torch._ops.OpOverload), type(op_overload)
    for output in output_args:
        assert output is None or isinstance(output, str), 'fallback kernels with runtime lookup currently only support tensor returns, not more complicated types (such as list-of-list-of-tensor)'
    if self._compatible_with_stableivalue(op_overload):
        self.generate_fallback_kernel_with_runtime_lookup_nopython(get_args, op_overload, output_args, outputs)
        return
    self.generate_fallback_kernel_with_runtime_lookup_python(buf_name, python_kernel_name, op_overload, raw_args, output_args, outputs)

