def validate(self, model, instance, exclude=None, using=DEFAULT_DB_ALIAS):
    queryset = model._default_manager.using(using)
    replacement_map = instance._get_field_expression_map(meta=model._meta, exclude=exclude)
    replacements = {F(field): value for (field, value) in replacement_map.items()}
    lookups = []
    for (expression, operator) in self.expressions:
        if isinstance(expression, str):
            expression = F(expression)
        if exclude and self._expression_refs_exclude(model, expression, exclude):
            return
        rhs_expression = expression.replace_expressions(replacements)
        if hasattr(expression, 'get_expression_for_validation'):
            expression = expression.get_expression_for_validation()
        if hasattr(rhs_expression, 'get_expression_for_validation'):
            rhs_expression = rhs_expression.get_expression_for_validation()
        lookup = PostgresOperatorLookup(lhs=expression, rhs=rhs_expression)
        lookup.postgres_operator = operator
        lookups.append(lookup)
    queryset = queryset.filter(*lookups)
    model_class_pk = instance._get_pk_val(model._meta)
    if not instance._state.adding and instance._is_pk_set(model._meta):
        queryset = queryset.exclude(pk=model_class_pk)
    if <MASK>:
        if queryset.exists():
            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)
    else:
        if exclude and self._expression_refs_exclude(model, self.condition, exclude):
            return
        if (self.condition & Exists(queryset.filter(self.condition))).check(replacement_map, using=using):
            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)

def _transform(self, X, fitting):
    assert array('i').itemsize == 4, 'sizeof(int) != 4 on your platform; please report this at https://github.com/scikit-learn/scikit-learn/issues and include the output from platform.platform() in your bug report'
    dtype = self.dtype
    if fitting:
        feature_names = []
        vocab = {}
    else:
        feature_names = self.feature_names_
        vocab = self.vocabulary_
    transforming = True
    X = [X] if isinstance(X, Mapping) else X
    indices = array('i')
    indptr = [0]
    values = []
    for x in X:
        for (f, v) in x.items():
            if isinstance(v, str):
                feature_name = '%s%s%s' % (f, self.separator, v)
                v = 1
            elif isinstance(v, Number) or v is None:
                feature_name = f
            elif not isinstance(v, Mapping) and isinstance(v, Iterable):
                feature_name = None
                self._add_iterable_element(f, v, feature_names, vocab, fitting=fitting, transforming=transforming, indices=indices, values=values)
            else:
                raise TypeError(f'Unsupported value Type {type(v)} for {f}: {v}.\n{type(v)} objects are not supported.')
            if feature_name is not None:
                if fitting and feature_name not in vocab:
                    vocab[feature_name] = len(feature_names)
                    feature_names.append(feature_name)
                if feature_name in vocab:
                    indices.append(vocab[feature_name])
                    values.append(self.dtype(v))
        indptr.append(len(indices))
    if len(indptr) == 1:
        raise ValueError('Sample sequence X is empty.')
    indices = np.frombuffer(indices, dtype=np.intc)
    shape = (len(indptr) - 1, len(vocab))
    result_matrix = sp.csr_matrix((values, indices, indptr), shape=shape, dtype=dtype)
    if fitting and self.sort:
        feature_names.sort()
        map_index = np.empty(len(feature_names), dtype=np.int32)
        for (new_val, f) in enumerate(feature_names):
            map_index[new_val] = vocab[f]
            vocab[f] = new_val
        result_matrix = result_matrix[:, map_index]
    if <MASK>:
        result_matrix.sort_indices()
    else:
        result_matrix = result_matrix.toarray()
    if fitting:
        self.feature_names_ = feature_names
        self.vocabulary_ = vocab
    return result_matrix

