def to_map(obj):
    if isinstance(obj, (torch.Tensor, PackedSequence)):
        device = obj.data.device if isinstance(obj, PackedSequence) else obj.device
        if device == target_device:
            return (obj,)
        if <MASK>:
            return (obj.to(target_device),)
        else:
            if device.type == 'cpu':
                return (obj.to(target_device),)
            from torch.nn.parallel._functions import _get_stream
            stream = _get_stream(target_device)
            with stream:
                output = obj.to(target_device)
            with torch.accelerator.device_index(target_device.index):
                current_stream = torch.accelerator.current_stream()
                current_stream.wait_stream(stream)
                if isinstance(obj, PackedSequence):
                    output.data.record_stream(current_stream)
                else:
                    assert isinstance(output, torch.Tensor)
                    output.record_stream(current_stream)
            return (output,)
    from torch.nn.parallel.scatter_gather import _is_namedtuple
    if _is_namedtuple(obj):
        return [type(obj)(*args) for args in zip(*map(to_map, obj))]
    if isinstance(obj, tuple) and len(obj) > 0:
        return list(zip(*map(to_map, obj)))
    if isinstance(obj, list) and len(obj) > 0:
        return [list(i) for i in zip(*map(to_map, obj))]
    if isinstance(obj, dict) and len(obj) > 0:
        return [type(obj)(i) for i in zip(*map(to_map, obj.items()))]
    return [obj]

def reset_states(self, states=None):
    if not self.stateful:
        raise AttributeError('Layer must be stateful.')
    input_shape = self.input_spec[0].shape
    state_shape = self.compute_output_shape(input_shape)
    if self.return_state:
        state_shape = state_shape[0]
    if self.return_sequences:
        state_shape = state_shape[:1].concatenate(state_shape[2:])
    if None in state_shape:
        raise ValueError('If a RNN is stateful, it needs to know its batch size. Specify the batch size of your input tensors: \n- If using a Sequential model, specify the batch size by passing a `batch_input_shape` argument to your first layer.\n- If using the functional API, specify the time dimension by passing a `batch_shape` argument to your Input layer.\nThe same thing goes for the number of rows and columns.')

    def get_tuple_shape(nb_channels):
        result = list(state_shape)
        if self.cell.data_format == 'channels_first':
            result[1] = nb_channels
        elif self.cell.data_format == 'channels_last':
            result[3] = nb_channels
        else:
            raise KeyError
        return tuple(result)
    if self.states[0] is None:
        if <MASK>:
            self.states = [backend.zeros(get_tuple_shape(dim)) for dim in self.cell.state_size]
        else:
            self.states = [backend.zeros(get_tuple_shape(self.cell.state_size))]
    elif states is None:
        if hasattr(self.cell.state_size, '__len__'):
            for (state, dim) in zip(self.states, self.cell.state_size):
                backend.set_value(state, np.zeros(get_tuple_shape(dim)))
        else:
            backend.set_value(self.states[0], np.zeros(get_tuple_shape(self.cell.state_size)))
    else:
        if not isinstance(states, (list, tuple)):
            states = [states]
        if len(states) != len(self.states):
            raise ValueError('Layer ' + self.name + ' expects ' + str(len(self.states)) + ' states, ' + 'but it received ' + str(len(states)) + ' state values. Input received: ' + str(states))
        for (index, (value, state)) in enumerate(zip(states, self.states)):
            if hasattr(self.cell.state_size, '__len__'):
                dim = self.cell.state_size[index]
            else:
                dim = self.cell.state_size
            if value.shape != get_tuple_shape(dim):
                raise ValueError('State ' + str(index) + ' is incompatible with layer ' + self.name + ': expected shape=' + str(get_tuple_shape(dim)) + ', found shape=' + str(value.shape))
            backend.set_value(state, value)

def __init__(self, ts_model: Union[torch.jit.ScriptModule, torch.jit.ScriptFunction], sample_args: tuple[Any, ...], sample_kwargs: Optional[dict[str, Any]]=None):
    self.ts_model = ts_model
    (self.ts_graph, self.params, _, _) = _create_jit_graph(ts_model, sample_args)
    self.sample_args = sample_args
    self.sample_kwargs = sample_kwargs
    self.name_to_param: dict[str, torch.Tensor] = {}
    self.name_to_buffer: dict[str, torch.Tensor] = {}
    param_list = list(self.ts_model.parameters()) if not isinstance(self.ts_model, torch._C.ScriptFunction) else []
    if <MASK>:
        for (k, tensor) in self.ts_model.state_dict().items():
            if any(((tensor == param).all() for param in param_list if tensor.shape == param.shape)):
                self.name_to_param[k] = tensor
            else:
                self.name_to_buffer[k] = tensor
    self.name_to_non_tensor_attributes: dict[str, Any] = {}
    self.name_to_constant: dict[str, Any] = {}
    self.lift_get_attr()

def _match(self, node: torch.fx.Node, ctx: MatchContext) -> MatchResult:
    m = ctx.match(self.inner_pattern, node)
    if <MASK>:
        return m
    ctx.pattern_to_node.pop(self.inner_pattern)
    for anchor_node in self.inner_pattern.find_anchor_nodes(ctx, OrderedSet()):
        anchor_m = MatchContext([self], graph=node.graph).match(self.inner_pattern, anchor_node)
        if not is_match(anchor_m):
            return anchor_m
        m.extend(anchor_m)
    return m

def reshard(self):
    if self._training_state == TrainingState.FORWARD:
        if not self._reshard_after_forward:
            return
        if self._use_post_forward_mesh:
            self._to_sharded_post_forward()
            self._reshard_after_forward_event = self.device_handle.Event()
            if <MASK>:
                self._reshard_after_forward_event.record()
            return
    self._to_sharded()

def type_based_dispatch_signatures_for(cls):
    """Returns dispatch signatures that have been registered for a given class.

  This function is intended for documentation-generation purposes.

  Args:
    cls: The class to search for.  Type signatures are searched recursively, so
      e.g., if `cls=RaggedTensor`, then information will be returned for all
      dispatch targets that have `RaggedTensor` anywhere in their type
      annotations (including nested in `typing.Union` or `typing.List`.)

  Returns:
    A `dict` mapping `api` -> `signatures`, where `api` is a TensorFlow API
    function; and `signatures` is a list of dispatch signatures for `api`
    that include `cls`.  (Each signature is a dict mapping argument names to
    type annotations; see `dispatch_for_api` for more info.)
  """

    def contains_cls(x):
        """Returns true if `x` contains `cls`."""
        if isinstance(x, dict):
            return any((contains_cls(v) for v in x.values()))
        elif <MASK>:
            return True
        elif type_annotations.is_generic_list(x) or type_annotations.is_generic_union(x):
            type_args = type_annotations.get_generic_type_args(x)
            return any((contains_cls(arg) for arg in type_args))
        else:
            return False
    result = {}
    for (api, api_signatures) in _TYPE_BASED_DISPATCH_SIGNATURES.items():
        for (_, signatures) in api_signatures.items():
            filtered = list(filter(contains_cls, signatures))
            if filtered:
                result.setdefault(api, []).extend(filtered)
    return result

def __torch_dispatch__(self, func: Any, types: tuple[Any, ...], args: tuple[Any, ...]=(), kwargs: dict[str, Any] | None=None) -> Any:
    if kwargs is None:
        kwargs = {}
    (flat_args, args_spec) = pytree.tree_flatten((args, kwargs))
    local_tensors = [a for a in flat_args if isinstance(a, LocalTensor)]
    has_unrecognized_types = _check_for_subclass(flat_args)
    if has_unrecognized_types:
        unrecognized_types = [type(x) for x in flat_args if _check_for_subclass_arg(x)]
        not_implemented_log.debug('LocalTensorMode unrecognized subclass(es): %s', unrecognized_types)
        return NotImplemented
    if not local_tensors:
        if self._disable or any((isinstance(a, Tensor) for a in flat_args)):
            return func(*args, **kwargs)
    for a in flat_args:
        if isinstance(a, LocalTensor):
            assert a._ranks <= self.ranks, f'Input LocalTensor {a} and LocalTensorMode must be configured for the same ranks'
    if func.namespace == 'c10d':
        if func is torch.ops.c10d.allreduce_.default:
            return _c10d._local_all_reduce_(*args, **kwargs)
        elif func is torch.ops.c10d.allreduce_coalesced_.default:
            return _c10d._local_allreduce_coalesced_(*args, **kwargs)
        elif func is torch.ops.c10d.reduce_scatter_tensor_coalesced_.default:
            return _c10d._local_reduce_scatter_tensor_coalesced_(*args, **kwargs)
        elif func is torch.ops.c10d.scatter_.default:
            return _c10d._local_scatter_(*args, **kwargs)
        elif func is torch.ops.c10d.broadcast_.default:
            return _c10d._local_broadcast_(*args, **kwargs)
        elif func is torch.ops.c10d.allgather_.default:
            return _c10d._local_all_gather_(*args, **kwargs)
        elif func is torch.ops.c10d.allgather_into_tensor_coalesced_.default:
            return _c10d._local_allgather_into_tensor_coalesced_(*args, **kwargs)
        elif func is torch.ops.c10d.gather_.default:
            return _c10d._local_gather_(*args, **kwargs)
        elif func is torch.ops.c10d.alltoall_.default:
            return _c10d._local_alltoall_(*args, **kwargs)
        elif func is torch.ops.c10d.alltoall_base_.default:
            return _c10d._local_alltoall_base_(*args, **kwargs)
        elif func is torch.ops.c10d.barrier.default:
            return _c10d._local_barrier(*args, **kwargs)
        elif func is torch.ops.c10d.monitored_barrier_.default:
            return _c10d._local_monitored_barrier_(*args, **kwargs)
        elif func is torch.ops.c10d.send.default:
            return _c10d._local_send(*args, **kwargs)
        elif func is torch.ops.c10d.recv_.default:
            return _c10d._local_recv_(*args, **kwargs)
        elif <MASK>:
            return _c10d._local_recv_any_source_(*args, **kwargs)
        raise NotImplementedError(f'{func} not implemented')
    if func.namespace == '_c10d_functional' or func.namespace == '_dtensor':
        with LocalTensorMode(self.ranks):
            return func._op_dk(DispatchKey.CompositeExplicitAutograd, *args, **kwargs)
    if func.namespace == 'profiler':
        return func(*args, **kwargs)
    if func.namespace == '_c10d_functional_autograd':
        raise NotImplementedError(f'{func} not implemented')
    if func.namespace == 'symm_mem':
        raise NotImplementedError(f'{func} not implemented')
    return _for_each_rank_run_func(func, self.ranks, args, kwargs, alias=True)

def items_for_result(cl, result, form):
    """
    Generate the actual list of data.
    """

    def link_in_col(is_first, field_name, cl):
        if cl.list_display_links is None:
            return False
        if is_first and (not cl.list_display_links):
            return True
        return field_name in cl.list_display_links
    first = True
    pk = cl.lookup_opts.pk.attname
    for (field_index, field_name) in enumerate(cl.list_display):
        empty_value_display = cl.model_admin.get_empty_value_display()
        row_classes = ['field-%s' % _coerce_field_name(field_name, field_index)]
        link_to_changelist = link_in_col(first, field_name, cl)
        try:
            (f, attr, value) = lookup_field(field_name, result, cl.model_admin)
        except ObjectDoesNotExist:
            result_repr = empty_value_display
        else:
            empty_value_display = getattr(attr, 'empty_value_display', empty_value_display)
            if isinstance(value, str) and value.strip() == '':
                value = ''
            if f is None or f.auto_created:
                if field_name == 'action_checkbox':
                    row_classes = ['action-checkbox']
                boolean = getattr(attr, 'boolean', False)
                if isinstance(attr, property) and hasattr(attr, 'fget'):
                    boolean = getattr(attr.fget, 'boolean', False)
                result_repr = display_for_value(value, empty_value_display, boolean)
                if isinstance(value, (datetime.date, datetime.time)):
                    row_classes.append('nowrap')
            else:
                if isinstance(f.remote_field, models.ManyToOneRel):
                    field_val = getattr(result, f.name)
                    if field_val is None:
                        result_repr = empty_value_display
                    else:
                        result_repr = field_val
                else:
                    result_repr = display_for_field(value, f, empty_value_display, avoid_link=link_to_changelist)
                if isinstance(f, (models.DateField, models.TimeField, models.ForeignKey)):
                    row_classes.append('nowrap')
        row_class = mark_safe(' class="%s"' % ' '.join(row_classes))
        if link_to_changelist:
            table_tag = 'th' if first else 'td'
            first = False
            try:
                url = cl.url_for_result(result)
            except NoReverseMatch:
                link_or_text = result_repr
            else:
                url = add_preserved_filters({'preserved_filters': cl.preserved_filters, 'opts': cl.opts}, url)
                if cl.to_field:
                    attr = str(cl.to_field)
                else:
                    attr = pk
                value = result.serializable_value(attr)
                link_or_text = format_html('<a href="{}"{}>{}</a>', url, format_html(' data-popup-opener="{}"', value) if cl.is_popup else '', result_repr)
            yield format_html('<{}{}>{}</{}>', table_tag, row_class, link_or_text, table_tag)
        else:
            if <MASK>:
                bf = form[field_name]
                result_repr = mark_safe(str(bf.errors) + str(bf))
            yield format_html('<td{}>{}</td>', row_class, result_repr)
    if form and (not form[cl.model._meta.pk.name].is_hidden):
        yield format_html('<td>{}</td>', form[cl.model._meta.pk.name])

def _check_valid_op(op) -> None:

    def _allowed_builtin_ops() -> list:
        ret = self.allowed_builtin_ops()
        assert all((inspect.isbuiltin(op) for op in ret))
        return ret

    def _allowed_op_types() -> tuple[type[Any], ...]:
        ret = self.allowed_op_types()
        assert not any((t is object for t in ret))
        return ret
    _allowed_torch_functions = (torch.autograd.grad_mode.set_grad_enabled, torch.sym_int, torch.sym_float, torch.sym_ite, torch.sym_max, torch.sym_min, torch.sym_not, torch.sym_sqrt, torch.sym_sum, torch.export.custom_ops._call_custom_autograd_function_in_pre_dispatch, torch._C._set_grad_enabled, torch.amp.autocast_mode._enter_autocast, torch.amp.autocast_mode._exit_autocast, torch.fx.experimental.symbolic_shapes.cast_symbool_to_symint_guardless, torch._functorch.predispatch._add_batch_dim, torch._functorch.predispatch._remove_batch_dim, torch._functorch.predispatch._vmap_increment_nesting, torch._functorch.predispatch._vmap_decrement_nesting, torch._functorch.predispatch.lazy_load_decompositions)
    if not isinstance(op, _allowed_op_types()):
        if op not in _allowed_builtin_ops() and op not in _allowed_torch_functions:
            raise SpecViolationError(f"Operator '{op}' is not an allowed operator type: {_allowed_op_types()}\nValid builtin ops: {_allowed_builtin_ops()}Valid torch functions: {_allowed_torch_functions}")
    if <MASK>:
        if self.dialect != 'TRAINING' and (not is_functional(op)):
            raise SpecViolationError(f"operator '{op}' is not functional")
    self.check_valid_op(op)

def _ordinalize(self, words, fixed_length=None):
    outputs = []
    if fixed_length is None:
        fixed_length = len(words[0])
    for word in words:
        output = []
        for i in range(fixed_length):
            if <MASK>:
                output.append(ord(word[i]))
            else:
                output.append(0)
        outputs.append(output)
    return np.array(outputs)

def __init__(self, optimizer: Optimizer, lr_lambda: Union[Callable[[int], float], list[Callable[[int], float]]], last_epoch: int=-1) -> None:
    self.optimizer = optimizer
    self.lr_lambdas: list[Callable[[int], float]]
    if not isinstance(lr_lambda, list) and (not isinstance(lr_lambda, tuple)):
        self.lr_lambdas = [lr_lambda] * len(optimizer.param_groups)
    else:
        if <MASK>:
            raise ValueError(f'Expected {len(optimizer.param_groups)} lr_lambdas, but got {len(lr_lambda)}')
        self.lr_lambdas = list(lr_lambda)
    for lr_lambda in self.lr_lambdas:
        if not callable(lr_lambda):
            raise TypeError(f'lr_lambda should be a function, but got {type(lr_lambda).__name__}')
    super().__init__(optimizer, last_epoch)

def obj_func(theta, eval_gradient=True):
    if <MASK>:
        (lml, grad) = self.log_marginal_likelihood(theta, eval_gradient=True, clone_kernel=False)
        return (-lml, -grad)
    else:
        return -self.log_marginal_likelihood(theta, clone_kernel=False)

def _select_tiling_indices(self, fn_list, var_sizes_list, tiling_factor):
    all_index = []
    for (fn, var_sizes) in zip(fn_list, var_sizes_list):
        rw = dependencies.extract_read_writes(fn, *var_sizes)
        all_index += [dep.index for dep in itertools.chain(rw.reads, rw.writes)]
    contig_vars = OrderedSet[int]()
    contig_vars_list = []
    non_contig_stride_const = OrderedSet[int]()
    non_contig_stride_other = OrderedSet[int]()
    for index in all_index:
        for var in index.free_symbols:
            if not re.search('^d\\d+$', var.name):
                continue
            stride = stride_at_vec_range(index, var, tiling_factor)
            if stride == 0:
                continue
            elif stride == 1:
                contig_vars.add(int(var.name[1:]))
                contig_vars_list.append(int(var.name[1:]))
            elif <MASK>:
                non_contig_stride_const.add(int(var.name[1:]))
            else:
                non_contig_stride_other.add(int(var.name[1:]))
    contig_only = contig_vars - non_contig_stride_const - non_contig_stride_other
    (group, reduction_group) = max(var_sizes_list, key=lambda sizes: len(sizes[1]))
    num_itervars = len(group) + len(reduction_group)
    if len(contig_vars) == 0:
        return [num_itervars - 1]
    if contig_only:
        return sorted(contig_only)[-1:]
    contig_and_const_stride = (contig_vars & non_contig_stride_const) - non_contig_stride_other
    contig_vars_sorted = sorted(contig_vars)
    if len(contig_vars_sorted) == 2 and contig_vars_sorted[-1] in contig_and_const_stride and (contig_vars_sorted[-1] == num_itervars - 1):
        return contig_vars_sorted
    return sorted(contig_vars_sorted, key=contig_vars_list.count)[-1:]

def pythonify_default(s: str) -> object:
    if <MASK>:
        return True
    elif s == 'false':
        return False
    try:
        return int(s)
    except ValueError:
        try:
            return float(s)
        except ValueError:
            return s

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name == '__setattr__':
        return super().call_method(tx, name, args, kwargs)
    elif name == 'mark_non_differentiable':
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        self.non_differentiable = proxy_args_kwargs(args, {})[0]
        return variables.ConstantVariable.create(None)
    if <MASK>:
        unimplemented_v2(gb_type='Unsupported autograd.Function context method', context=f'call_method {self} {name}', explanation=f'Dynamo does not support calling the method `{name}` on `autograd.Function` context objects. Supported methods are `__setattr__`, `save_for_backward` and `mark_non_differentiable`.', hints=[*graph_break_hints.SUPPORTABLE])
    if self.saved_tensors is None:
        unimplemented_v2(gb_type='Unsupported autograd.Function context `save_for_backward`', context=f'call_method {self} {name}', explanation='Dynamo requires the `saved_tensors` attribute to be initialized on the `autograd.Function` context object.', hints=['Ensure that the `saved_tensors` attribute is properly initialized before calling `save_for_backward`. `save_for_backward` only supported on a newly constructed `torch.autograd.function.FunctionCtx`.'])
    if not self.inference:
        if kwargs or not self.source:
            raise_type_error_exc(tx, 'save_for_backward() requires a source and no keyword arguments')
        tx.output.side_effects.track_save_for_backward(self, args)
    if len(self.saved_tensors.tensors) > 0:
        self.saved_tensors.tensors = []
    for arg in args:
        self.saved_tensors.tensors.append(arg)
    return variables.ConstantVariable.create(None)

def print_file_summary(covered_summary: int, total_summary: int, summary_file: IO[str]) -> float:
    try:
        coverage_percentage = 100.0 * covered_summary / total_summary
    except ZeroDivisionError:
        coverage_percentage = 0
    print(f'SUMMARY\ncovered: {covered_summary}\nuncovered: {total_summary}\npercentage: {coverage_percentage:.2f}%\n\n', file=summary_file)
    if <MASK>:
        print('Coverage is 0, Please check if json profiles are valid')
    return coverage_percentage

def _libs_with_msvc_and_fortran(self, fcompiler, c_libraries, c_library_dirs):
    if fcompiler is None:
        return
    for libname in c_libraries:
        if libname.startswith('msvc'):
            continue
        fileexists = False
        for libdir in c_library_dirs or []:
            libfile = os.path.join(libdir, '%s.lib' % libname)
            if os.path.isfile(libfile):
                fileexists = True
                break
        if fileexists:
            continue
        fileexists = False
        for libdir in c_library_dirs:
            libfile = os.path.join(libdir, 'lib%s.a' % libname)
            if os.path.isfile(libfile):
                libfile2 = os.path.join(self.build_temp, libname + '.lib')
                copy_file(libfile, libfile2)
                if self.build_temp not in c_library_dirs:
                    c_library_dirs.append(self.build_temp)
                fileexists = True
                break
        if fileexists:
            continue
        log.warn('could not find library %r in directories %s' % (libname, c_library_dirs))
    f_lib_dirs = []
    for dir in fcompiler.library_dirs:
        if dir.startswith('/usr/lib'):
            try:
                dir = subprocess.check_output(['cygpath', '-w', dir])
            except (OSError, subprocess.CalledProcessError):
                pass
            else:
                dir = filepath_from_subprocess_output(dir)
        f_lib_dirs.append(dir)
    c_library_dirs.extend(f_lib_dirs)
    for lib in fcompiler.libraries:
        if not lib.startswith('msvc'):
            c_libraries.append(lib)
            p = combine_paths(f_lib_dirs, 'lib' + lib + '.a')
            if p:
                dst_name = os.path.join(self.build_temp, lib + '.lib')
                if <MASK>:
                    copy_file(p[0], dst_name)
                if self.build_temp not in c_library_dirs:
                    c_library_dirs.append(self.build_temp)

def metadata_split(metadata):
    out = []
    (start, n) = (0, 0)
    (a, b) = ('[(', ')]')
    for (end, c) in enumerate(metadata):
        if c in a:
            n += 1
        elif <MASK>:
            n -= 1
        elif c == ',' and n == 0:
            out.append(metadata[start:end])
            start = end + 1
    out.append(metadata[start:])
    assert len(out) == 3
    return out

def get_example_value(self, base_cls_vt: VariableTracker, cls_vt: VariableTracker, init_args: list[VariableTracker]) -> Any:
    user_cls = cls_vt.value
    if issubclass(user_cls, torch.nn.Module):
        obj = nn_module_new(user_cls)
    else:
        if <MASK>:
            base_cls = base_cls_vt.fn
        elif isinstance(base_cls_vt, variables.UserDefinedClassVariable):
            base_cls = base_cls_vt.value
        else:
            raise RuntimeError(f'Unexpected base_cls_vt {base_cls_vt}')
        assert variables.UserDefinedClassVariable.is_supported_new_method(base_cls.__new__)
        obj = base_cls.__new__(user_cls)
    return obj

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName) -> NamedCType:
    r = cpp.valuetype_type(t, symint=False, binds=binds, mutable=mutable)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if <MASK>:
            return NamedCType(binds, BaseCType(optionalTensorRefT))
        elif t.elem == BaseType(BaseTy.Scalar):
            return NamedCType(binds, BaseCType(optionalScalarRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
        elif t.elem == OptionalType(BaseType(BaseTy.Tensor)):
            return NamedCType(binds, BaseCType(iOptTensorListRefT))
        elif str(t.elem) == 'int':
            return NamedCType(binds, BaseCType(intArrayRefT))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

