def partition(self, partition_fn: Callable, always_recompute_complex_exprs: bool) -> HopPartitionedGraph:
    if <MASK>:
        logger.debug('before min_cut_partition:\n%s', self.joint_gm.print_readable(print_output=False))
    if always_recompute_complex_exprs:
        self._mark_complex_exprs_as_must_recompute()
    (fw_gm, bw_gm) = partition_fn(self.joint_gm, None, num_fwd_outputs=self.n_fw_outputs)
    if logger.isEnabledFor(logging.DEBUG):
        logger.debug('after partition_fn:')
        logger.debug('fw_gm:\n%s', fw_gm.print_readable(print_output=False))
        logger.debug('bw_gm:\n%s', bw_gm.print_readable(print_output=False))
    n_intermediates = len(_find_hop_subgraph_outputs(fw_gm)) - self.n_fw_outputs
    return HopPartitionedGraph(fw_gm, bw_gm, self.n_fw_outputs, n_intermediates, always_recompute_complex_exprs)

def functional_init(model_class: type[nn.Module], ensemble_shape: Union[tuple[()], tuple[int]]=(), device: torch.types.Device='cpu'):

    def wrapped(*args, **kwargs):
        if len(ensemble_shape) >= 2:
            raise ValueError('NYI: ensemble_shape with more than 1 element')
        if <MASK>:
            model = model_class(*args, **kwargs).to(device)
            return make_functional_deprecated_v1(model)
        num_models = ensemble_shape[0]
        if num_models <= 0:
            raise ValueError(f'num_models {num_models} should be > 0')
        models = tuple((model_class(*args, **kwargs).to(device) for _ in range(num_models)))
        (_, fn, names) = make_functional_deprecated_v1(model_class(*args, **kwargs))
        weights = tuple((make_functional_deprecated_v1(model)[0] for model in models))
        weights = tuple(zip(*weights))
        weights = tuple((torch.stack(shards).detach() for shards in weights))
        return (weights, fn, names)
    return wrapped

def new_method_proxy(func):

    def inner(self, *args):
        if <MASK>:
            self._setup()
            _wrapped = self._wrapped
        return func(_wrapped, *args)
    inner._mask_wrapped = False
    return inner

def _align_for_op(self, right, align_asobject: bool=False):
    """align lhs and rhs Series"""
    left = self
    if <MASK>:
        if not left.index.equals(right.index):
            if align_asobject:
                if left.dtype not in (object, np.bool_) or right.dtype not in (object, np.bool_):
                    pass
                else:
                    left = left.astype(object)
                    right = right.astype(object)
            (left, right) = left.align(right)
    return (left, right)

