def _assemble_from_unit_mappings(arg, errors: DateTimeErrorChoices, utc: bool) -> Series:
    """
    assemble the unit specified fields from the arg (DataFrame)
    Return a Series for actual parsing

    Parameters
    ----------
    arg : DataFrame
    errors : {'raise', 'coerce'}, default 'raise'

        - If :const:`'raise'`, then invalid parsing will raise an exception
        - If :const:`'coerce'`, then invalid parsing will be set as :const:`NaT`
    utc : bool
        Whether to convert/localize timestamps to UTC.

    Returns
    -------
    Series
    """
    from pandas import DataFrame, to_numeric, to_timedelta
    arg = DataFrame(arg)
    if not arg.columns.is_unique:
        raise ValueError('cannot assemble with duplicate keys')

    def f(value):
        if <MASK>:
            return _unit_map[value]
        if value.lower() in _unit_map:
            return _unit_map[value.lower()]
        return value
    unit = {k: f(k) for k in arg.keys()}
    unit_rev = {v: k for (k, v) in unit.items()}
    required = ['year', 'month', 'day']
    req = set(required) - set(unit_rev.keys())
    if len(req):
        _required = ','.join(sorted(req))
        raise ValueError(f'to assemble mappings requires at least that [year, month, day] be specified: [{_required}] is missing')
    excess = set(unit_rev.keys()) - set(_unit_map.values())
    if len(excess):
        _excess = ','.join(sorted(excess))
        raise ValueError(f'extra keys have been passed to the datetime assemblage: [{_excess}]')

    def coerce(values):
        values = to_numeric(values, errors=errors)
        if is_float_dtype(values.dtype):
            values = values.astype('float64')
        if is_integer_dtype(values.dtype):
            values = values.astype('int64')
        return values
    values = coerce(arg[unit_rev['year']]) * 10000 + coerce(arg[unit_rev['month']]) * 100 + coerce(arg[unit_rev['day']])
    try:
        values = to_datetime(values, format='%Y%m%d', errors=errors, utc=utc)
    except (TypeError, ValueError) as err:
        raise ValueError(f'cannot assemble the datetimes: {err}') from err
    units: list[UnitChoices] = ['h', 'm', 's', 'ms', 'us', 'ns']
    for u in units:
        value = unit_rev.get(u)
        if value is not None and value in arg:
            try:
                values += to_timedelta(coerce(arg[value]), unit=u, errors=errors)
            except (TypeError, ValueError) as err:
                raise ValueError(f'cannot assemble the datetimes [{value}]: {err}') from err
    return values

def _more_validate_params(self, for_partial_fit=False):
    """Validate input params."""
    if <MASK>:
        raise ValueError('early_stopping should be False with partial_fit')
    if self.learning_rate == 'optimal' and self.alpha == 0:
        raise ValueError("alpha must be > 0 since learning_rate is 'optimal'. alpha is used to compute the optimal learning rate.")
    if self.learning_rate in ('pa1', 'pa2'):
        if is_classifier(self):
            if self.loss != 'hinge':
                msg = f"Learning rate '{self.learning_rate}' only works with loss 'hinge'."
                raise ValueError(msg)
        elif self.loss != 'epsilon_insensitive':
            msg = f"Learning rate '{self.learning_rate}' only works with loss 'epsilon_insensitive'."
            raise ValueError(msg)
    if self.penalty == 'elasticnet' and self.l1_ratio is None:
        raise ValueError("l1_ratio must be set when penalty is 'elasticnet'")
    self._get_penalty_type(self.penalty)
    self._get_learning_rate_type(self.learning_rate)

@classmethod
def _box_pa_scalar(cls, value, pa_type: pa.DataType | None=None) -> pa.Scalar:
    """
        Box value into a pyarrow Scalar.

        Parameters
        ----------
        value : any
        pa_type : pa.DataType | None

        Returns
        -------
        pa.Scalar
        """
    if isinstance(value, pa.Scalar):
        pa_scalar = value
    elif isna(value) and (not (lib.is_float(value) and (not is_nan_na()))):
        pa_scalar = pa.scalar(None, type=pa_type)
    else:
        if isinstance(value, Timedelta):
            if <MASK>:
                pa_type = pa.duration(value.unit)
            elif value.unit != pa_type.unit:
                value = value.as_unit(pa_type.unit)
            value = value._value
        elif isinstance(value, Timestamp):
            if pa_type is None:
                pa_type = pa.timestamp(value.unit, tz=value.tz)
            elif value.unit != pa_type.unit:
                value = value.as_unit(pa_type.unit)
            value = value._value
        pa_scalar = pa.scalar(value, type=pa_type)
    if pa_type is not None and pa_scalar.type != pa_type:
        pa_scalar = pa_scalar.cast(pa_type)
    return pa_scalar

