def _check_num_rows_possibly_add_asserts(self):
    """Static check of init arg `num_rows`, possibly add asserts."""
    if self._assert_proper_shapes:
        self._num_rows = control_flow_ops.with_dependencies([check_ops.assert_rank(self._num_rows, 0, message='Argument num_rows must be a 0-D Tensor.'), check_ops.assert_non_negative(self._num_rows, message='Argument num_rows must be non-negative.')], self._num_rows)
    if not self._num_rows.dtype.is_integer:
        raise TypeError('Argument num_rows must be integer type.  Found: %s' % self._num_rows)
    num_rows_static = self._num_rows_static
    if num_rows_static is None:
        return
    if <MASK>:
        raise ValueError('Argument num_rows must be a 0-D Tensor.  Found: %s' % num_rows_static)
    if num_rows_static < 0:
        raise ValueError('Argument num_rows must be non-negative.  Found: %s' % num_rows_static)

def find_cycle(el: int, graph: dict[int, list[int]], reprs: dict[int, str], path: tuple[int, ...]) -> Optional[bool]:
    """Finds and prints a single cycle in the dependency graph."""
    if <MASK>:
        return
    for r in graph[el]:
        if r in path:
            logging.error('Reference cycle sample:')
            for p in path + (r,):
                logging.error(reprs.get(p, 'unknown object ' + str(p)))
            return True
        elif find_cycle(r, graph, reprs, path + (r,)):
            return True
    return False

def view_from_base(base: _TensorT, t: MetaTensorDesc, shape_env: Optional[torch.fx.experimental.symbolic_shapes.ShapeEnv]=shape_env) -> _TensorT:
    with enable_python_dispatcher():
        (sizes, strides, storage_offset) = sym_sizes_strides_storage_offset(t, source)
        if not t.is_traceable_wrapper_subclass and (not is_traceable_wrapper_subclass(base)):
            with maybe_suppress():
                return self._checked_cast_tensor_t(base.as_strided(sizes, strides, storage_offset))
        from torch._dynamo.source import EphemeralSource
        from torch.fx.experimental.symbolic_shapes import StatelessSymbolicContext, sym_eq

        def symint_visitor_fn(s: int) -> int:
            nonlocal symbolic_context
            from torch.fx.experimental.symbolic_shapes import DimDynamic
            all_static_sizes = symbolic_context is not None and isinstance(symbolic_context, StatelessSymbolicContext) and all((x is DimDynamic.STATIC for x in symbolic_context.dynamic_sizes))
            if all_static_sizes or shape_env is None:
                return s
            sym_source = EphemeralSource('symint_visitor_fn')
            symbol = shape_env.create_symbol(s, sym_source, positive=None)
            return shape_env.create_symintnode(symbol, hint=s, source=sym_source)
        real_to_fake_mapping = {}
        if <MASK>:
            assert t.attrs is not None
            assert t.type is not None
            fake_t: _TensorT = empty_create_subclass(t, outer_size=sizes, outer_stride=strides)
            (attrs, _) = fake_t.__tensor_flatten__()
            for attr in attrs:
                real_to_fake_mapping[t.attrs[attr].id] = getattr(fake_t, attr)

        def tensor_visitor_fn(visited_t: torch.Tensor, shape_env: Optional[torch.fx.experimental.symbolic_shapes.ShapeEnv]=shape_env, callback: _MetaTensorCallbackOptDevice[_TensorT]=callback) -> torch.Tensor:
            if visited_t is None:
                return None
            visited_id = self.describer.get_tensor_id(visited_t)
            fake_visited_t = real_to_fake_mapping.get(visited_id)
            if fake_visited_t is not None:
                return fake_visited_t
            visited_desc = self.describer.describe_tensor(visited_t)
            temp_source = EphemeralSource('tensor_visitor_fn')
            return self.meta_tensor(visited_desc, shape_env, callback, temp_source, all_dynamic_symbolic_context(visited_desc, temp_source, shape_env, callback))
        assert t.view_func is not None
        fake_t = t.view_func.apply(t, base, symint_visitor_fn, tensor_visitor_fn)
        torch._check(sym_eq(fake_t.size(), sizes))
        torch._check(sym_eq(fake_t.stride(), strides))
        torch._check(sym_eq(fake_t.storage_offset(), storage_offset))
        return fake_t

@normalizer
def ldexp(x1: ArrayLikeOrScalar, x2: ArrayLikeOrScalar, /, out: Optional[OutArray]=None, *, where: NotImplementedType=True, casting: Optional[CastingModes]='same_kind', order: NotImplementedType='K', dtype: Optional[DTypeLike]=None, subok: NotImplementedType=False, signature: NotImplementedType=None, extobj: NotImplementedType=None):
    if dtype is not None:
        if isinstance(x1, torch.Tensor):
            x1 = _util.typecast_tensor(x1, dtype, casting)
        else:
            x1 = torch.as_tensor(x1, dtype=dtype)
    elif not isinstance(x1, torch.Tensor):
        x1 = torch.as_tensor(x1)
        x1 = _util.cast_int_to_float(x1)
    x2 = torch.as_tensor(x2)
    if <MASK>:
        raise ValueError('ldexp 2nd arg must be integer')
    result = _binary_ufuncs_impl.ldexp(x1, x2)
    if x1.dtype == torch.float16:
        result = result.to(torch.float16)
    return _ufunc_postprocess(result, out, casting)

