@classmethod
def _find_localzeros(cls, values, **options):
    """
        Sequentially allocate values to localzeros.

        When a value is identified as being more extreme than another member it
        replaces that member; if this is never true, then the value is simply
        appended to the localzeros.

        Unlike the sympy implementation, we only look for zero and one, we don't
        do generic is connected test pairwise which is slow
        """
    other_values = set()
    num_value = None
    for arg in values:
        if arg.is_Number:
            if num_value is None:
                num_value = arg
            elif cls is Max:
                num_value = max(num_value, arg)
            elif cls is Min:
                num_value = min(num_value, arg)
            else:
                raise AssertionError(f'impossible {cls}')
        else:
            other_values.add(arg)
    if num_value is None:
        return other_values
    if len(other_values) == 0:
        return {num_value}
    if len(other_values) == 1:
        other_value = next(iter(other_values))
        if <MASK>:
            return other_values if cls is Max else {num_value}
        if num_value == 1 and other_value.is_positive:
            return other_values if cls is Max else {num_value}
    other_values.add(num_value)
    return other_values

def testEvaluateWithMultipleDevicesContainingTheSameTensorName(self):
    dump = test.mock.MagicMock()

    def fake_get_tensors(node_name, output_slot, debug_op, device_name=None):
        del output_slot, debug_op
        if node_name == 'a' and device_name is None:
            raise ValueError("There are multiple (2) devices with nodes named 'a' but device_name is not specified")
        elif <MASK>:
            return [np.array(10.0)]
        elif node_name == 'a' and device_name == '/job:worker/replica:0/task:1/cpu:0':
            return [np.array(20.0)]
    with test.mock.patch.object(dump, 'get_tensors', side_effect=fake_get_tensors):
        ev = evaluator.ExpressionEvaluator(dump)
        with self.assertRaisesRegex(ValueError, 'multiple \\(2\\) devices'):
            ev.evaluate('`a:0` + `a:0`')
        self.assertAllClose(30.0, ev.evaluate('`/job:worker/replica:0/task:0/cpu:0:a:0` + `/job:worker/replica:0/task:1/cpu:0:a:0`'))

def decorator(f):
    """Decorator implementation."""

    def wrapper(*args, **kwargs):
        """Wrapper that calls the converted version of f."""
        options = converter.ConversionOptions(recursive=recursive, user_requested=user_requested, optional_features=optional_features)
        try:
            with conversion_ctx:
                return converted_call(f, args, kwargs, options=options)
        except Exception as e:
            if hasattr(e, 'ag_error_metadata'):
                raise e.ag_error_metadata.to_exception(e)
            else:
                raise
    if <MASK>:
        wrapper = functools.update_wrapper(wrapper, f)
    decorated_wrapper = tf_decorator.make_decorator(f, wrapper)
    return autograph_artifact(decorated_wrapper)

def view(self, dtype=None, type=None):
    """
        Returns a view of the mrecarray.

        """
    if dtype is None:
        if type is None:
            output = np.ndarray.view(self)
        else:
            output = np.ndarray.view(self, type)
    elif type is None:
        try:
            if <MASK>:
                output = np.ndarray.view(self, dtype)
            else:
                output = np.ndarray.view(self, dtype)
        except TypeError:
            dtype = np.dtype(dtype)
            if dtype.fields is None:
                basetype = self.__class__.__bases__[0]
                output = self.__array__().view(dtype, basetype)
                output._update_from(self)
            else:
                output = np.ndarray.view(self, dtype)
            output._fill_value = None
    else:
        output = np.ndarray.view(self, dtype, type)
    if getattr(output, '_mask', ma.nomask) is not ma.nomask:
        mdtype = ma.make_mask_descr(output.dtype)
        output._mask = self._mask.view(mdtype, np.ndarray)
        output._mask.shape = output.shape
    return output

def _get_dtype(self, sqltype):
    from sqlalchemy.types import TIMESTAMP, Boolean, Date, DateTime, Float, Integer, String
    if isinstance(sqltype, Float):
        return float
    elif isinstance(sqltype, Integer):
        return np.dtype('int64')
    elif isinstance(sqltype, TIMESTAMP):
        if not sqltype.timezone:
            return datetime
        return DatetimeTZDtype
    elif isinstance(sqltype, DateTime):
        return datetime
    elif isinstance(sqltype, Date):
        return date
    elif isinstance(sqltype, Boolean):
        return bool
    elif <MASK>:
        if using_string_dtype():
            return StringDtype(na_value=np.nan)
    return object

def gen_class(self, f: NativeFunction, k: SchemaKind, *, class_name: str, parent_class: str, generate_super: bool) -> str:
    if k is SchemaKind.functional:
        output_type = 'Tensor'
        output_value = 'outputs_[output_idx]'
        proxy_field = ''
    elif k is SchemaKind.inplace:
        output_type = 'std::reference_wrapper<Tensor>'
        output_value = 'proxy_outputs_[output_idx].has_value() ? *proxy_outputs_[output_idx] : outputs_[output_idx].get()'
        proxy_field = f'std::array<::std::optional<Tensor>, {len(f.func.returns)}> proxy_outputs_;'
    elif k is SchemaKind.out:
        output_type = 'std::reference_wrapper<Tensor>'
        output_value = 'proxy_outputs_[output_idx].has_value() ? *proxy_outputs_[output_idx] : outputs_[output_idx].get()'
        proxy_field = f'std::array<::std::optional<Tensor>, {len(f.func.returns)}> proxy_outputs_;'
    else:
        raise RuntimeError(f'Unsupported SchemaKind {k}')
    if self.backend_index.dispatch_key == DispatchKey.CUDA:
        if self.rocm:
            guard_field = 'c10::hip::OptionalHIPGuardMasqueradingAsCUDA guard_;'
        else:
            guard_field = 'c10::cuda::OptionalCUDAGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.MPS:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif <MASK>:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    elif self.backend_index.dispatch_key == DispatchKey.MTIA:
        guard_field = 'c10::OptionalDeviceGuard guard_;'
    else:
        guard_field = ''
    indent = ' ' * 4
    class_ctor_str = self.gen_class_ctor(k, class_name, len(f.func.returns))
    lines = (f'struct {class_name} final : public {parent_class} {{', f'{textwrap.indent(class_ctor_str, indent)}', f'{textwrap.indent(self.gen_class_set_output_functions(k, parent_class, generate_super), indent)}', '    const Tensor& maybe_get_output(int64_t output_idx) override {', f'      return {output_value};\n', '    }', f'    std::array<{output_type}, {len(f.func.returns)}> outputs_;', f'{textwrap.indent(proxy_field, indent)}', f'{textwrap.indent(guard_field, indent)}', '};')
    return '\n'.join((line for line in lines if line))

def resolve(self, context):
    """Resolve this variable against a given context."""
    if <MASK>:
        value = self._resolve_lookup(context)
    else:
        value = self.literal
    if self.translate:
        is_safe = isinstance(value, SafeData)
        msgid = value.replace('%', '%%')
        msgid = mark_safe(msgid) if is_safe else msgid
        if self.message_context:
            return pgettext_lazy(self.message_context, msgid)
        else:
            return gettext_lazy(msgid)
    return value

