def on_run_start(self, request):
    """Overrides on-run-start callback.

    Args:
      request: An instance of `OnRunStartRequest`.

    Returns:
      An instance of `OnRunStartResponse`.
    """
    self._is_run_start = True
    self._update_run_calls_state(request.run_call_count, request.fetches, request.feed_dict, is_callable_runner=request.is_callable_runner)
    if self._active_tensor_filter:
        return self._active_tensor_filter_run_start_response
    self._exit_if_requested_by_user()
    if self._run_call_count > 1 and (not self._skip_debug):
        if self._run_through_times > 0:
            return framework.OnRunStartResponse(framework.OnRunStartAction.NON_DEBUG_RUN, [])
        elif <MASK>:
            return self._run_start_response or framework.OnRunStartResponse(framework.OnRunStartAction.DEBUG_RUN, self._get_run_debug_urls())
    if self._run_start_response is None:
        self._prep_cli_for_run_start()
        self._run_start_response = self._launch_cli()
        if self._active_tensor_filter:
            self._active_tensor_filter_run_start_response = self._run_start_response
        if self._run_through_times > 1:
            self._run_through_times -= 1
    self._exit_if_requested_by_user()
    return self._run_start_response

def get_node_first_input_and_output_type(node: Node, gm: GraphModule, logger_cls: Callable, node_type_to_io_type_map: dict[str, set[NSNodeTargetType]]) -> tuple[NodeInputOrOutputType, NodeInputOrOutputType]:
    FUNS_IO_TYPE_FP32 = node_type_to_io_type_map['funs_io_type_fp32']
    FUNS_IO_TYPE_FP16 = node_type_to_io_type_map['funs_io_type_fp16']
    FUNS_IO_TYPE_INT8 = node_type_to_io_type_map['funs_io_type_int8']
    FUNS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['funs_io_type_fp32_or_int8']
    MODS_IO_TYPE_FP32 = node_type_to_io_type_map['mods_io_type_fp32']
    MODS_IO_TYPE_INT8 = node_type_to_io_type_map['mods_io_type_int8']
    MODS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['mods_io_type_fp32_or_int8']
    METHS_IO_TYPE_FP32_OR_INT8 = node_type_to_io_type_map['meths_io_type_fp32_or_int8']
    if node.op == 'call_function':
        if node.target in FUNS_IO_TYPE_FP32:
            return (NodeInputOrOutputType.FP32, NodeInputOrOutputType.FP32)
        if node.target in FUNS_IO_TYPE_FP16:
            return (NodeInputOrOutputType.FP16, NodeInputOrOutputType.FP16)
        elif node.target in FUNS_IO_TYPE_INT8:
            return (NodeInputOrOutputType.INT8, NodeInputOrOutputType.INT8)
        elif node.target in FUNS_IO_TYPE_FP32_OR_INT8:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        else:
            return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    elif node.op == 'call_module':
        if node.op != 'call_module':
            raise AssertionError(f"Expected call_module, got '{node.op}'")
        if not isinstance(node.target, str):
            raise AssertionError(f'Expected str, but got {type(node.target)}')
        mod = getattr_from_fqn(gm, node.target)
        is_known_fp32_or_int8_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_FP32_OR_INT8))
        if isinstance(mod, (logger_cls, ObserverBase, FakeQuantizeBase)) or is_known_fp32_or_int8_input_module:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        is_known_fp32_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_FP32))
        is_known_int8_input_module = any((isinstance(mod, target_type) for target_type in MODS_IO_TYPE_INT8))
        if is_known_fp32_input_module:
            return (NodeInputOrOutputType.FP32, NodeInputOrOutputType.FP32)
        elif is_known_int8_input_module:
            return (NodeInputOrOutputType.INT8, NodeInputOrOutputType.INT8)
        else:
            return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    elif node.op == 'call_method':
        if node.target == 'dequantize':
            prev_node = get_normalized_nth_input(node, gm, 0)
            if not isinstance(prev_node, Node):
                raise AssertionError(f'Expected Node, got {type(prev_node)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(prev_node, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, NodeInputOrOutputType.FP32)
        elif node.target == 'to':
            prev_node = get_normalized_nth_input(node, gm, 0)
            if not isinstance(prev_node, Node):
                raise AssertionError(f'Expected Node, got {type(prev_node)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(prev_node, gm, logger_cls, node_type_to_io_type_map)
            cur_node_dtype_target = get_normalized_nth_input(node, gm, 1)
            if cur_node_dtype_target is not torch.float16:
                raise AssertionError(f'{cur_node_dtype_target} handling needs to be added')
            return (prev_node_output_type, NodeInputOrOutputType.FP16)
        elif <MASK>:
            first_arg = get_normalized_nth_input(node, gm, 0)
            if not isinstance(first_arg, Node):
                raise AssertionError(f'Expected Node, got {type(first_arg)}')
            (_prev_node_input_type, prev_node_output_type) = get_node_first_input_and_output_type(first_arg, gm, logger_cls, node_type_to_io_type_map)
            return (prev_node_output_type, prev_node_output_type)
        return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)
    else:
        return (NodeInputOrOutputType.UNKNOWN, NodeInputOrOutputType.UNKNOWN)

def add_near_best_configs(df):
    new_rows = []
    for (index, row) in df.iterrows():
        dictionary = json.loads(row['choice2time'])
        min_value = min(dictionary.values())
        for (key, value) in dictionary.items():
            new_row = row.copy()
            relative_performance = min_value / value
            new_row['relative_performance'] = relative_performance
            if <MASK>:
                breakpoint()
            new_row['actual_winner'] = row['winner']
            new_row['winner'] = key
            if relative_performance >= 0.98:
                new_rows.append(new_row)
    return pd.DataFrame(new_rows).reset_index(drop=True)

@register_dispatch_func([torch.ops.aten._to_dense])
def _to_dense(func, *args, **kwargs):
    _check_args_kwargs_length(args, kwargs, f'__torch_dispatch__, {func}', len_args=1, len_kwargs=0)
    if not torch.is_tensor(args[0]):
        raise ValueError(f'__torch_dispatch__, {func}: expected args[0] to be a tensor')
    mt = args[0]
    if <MASK>:
        mt = MaskedTensor(mt, torch.ones_like(mt).bool())
    new_data = func(_get_data(args[0]))
    new_mask = func(_maybe_get_mask(args[0]))
    return MaskedTensor(new_data, new_mask)

def _generate_marginal_results(table, data: DataFrame, values, rows, cols, aggfunc, kwargs, observed: bool, margins_name: Hashable='All', dropna: bool=True):
    margin_keys: list | Index
    if <MASK>:
        table_pieces = []
        margin_keys = []

        def _all_key(key):
            return (key, margins_name) + ('',) * (len(cols) - 1)
        if len(rows) > 0:
            margin = data[rows + values].groupby(rows, observed=observed, dropna=dropna).agg(aggfunc, **kwargs)
            cat_axis = 1
            for (key, piece) in table.T.groupby(level=0, observed=observed):
                piece = piece.T
                all_key = _all_key(key)
                piece[all_key] = margin[key]
                table_pieces.append(piece)
                margin_keys.append(all_key)
        else:
            margin = data[cols[:1] + values].groupby(cols[:1], observed=observed, dropna=dropna).agg(aggfunc, **kwargs).T
            cat_axis = 0
            for (key, piece) in table.groupby(level=0, observed=observed):
                if len(cols) > 1:
                    all_key = _all_key(key)
                else:
                    all_key = margins_name
                table_pieces.append(piece)
                transformed_piece = margin[key].to_frame().T
                if isinstance(piece.index, MultiIndex):
                    transformed_piece.index = MultiIndex.from_tuples([all_key], names=piece.index.names + [None])
                else:
                    transformed_piece.index = Index([all_key], name=piece.index.name)
                table_pieces.append(transformed_piece)
                margin_keys.append(all_key)
        if not table_pieces:
            return table
        else:
            result = concat(table_pieces, axis=cat_axis)
        if len(rows) == 0:
            return result
    else:
        result = table
        margin_keys = table.columns
    if len(cols) > 0:
        row_margin = data[cols + values].groupby(cols, observed=observed, dropna=dropna).agg(aggfunc, **kwargs)
        row_margin = row_margin.stack()
        new_order_indices = itertools.chain([len(cols)], range(len(cols)))
        new_order_names = [row_margin.index.names[i] for i in new_order_indices]
        row_margin.index = row_margin.index.reorder_levels(new_order_names)
    else:
        row_margin = data._constructor_sliced(np.nan, index=result.columns)
    return (result, margin_keys, row_margin)

def _create_storer(self, group, format=None, value: DataFrame | Series | None=None, encoding: str='UTF-8', errors: str='strict') -> GenericFixed | Table:
    """return a suitable class to operate"""
    cls: type[GenericFixed | Table]
    if value is not None and (not isinstance(value, (Series, DataFrame))):
        raise TypeError('value must be None, Series, or DataFrame')
    pt = getattr(group._v_attrs, 'pandas_type', None)
    tt = getattr(group._v_attrs, 'table_type', None)
    if pt is None:
        if value is None:
            _tables()
            assert _table_mod is not None
            if getattr(group, 'table', None) or isinstance(group, _table_mod.table.Table):
                pt = 'frame_table'
                tt = 'generic_table'
            else:
                raise TypeError('cannot create a storer if the object is not existing nor a value are passed')
        else:
            if isinstance(value, Series):
                pt = 'series'
            else:
                pt = 'frame'
            if format == 'table':
                pt += '_table'
    if <MASK>:
        _STORER_MAP = {'series': SeriesFixed, 'frame': FrameFixed}
        try:
            cls = _STORER_MAP[pt]
        except KeyError as err:
            raise TypeError(f'cannot properly create the storer for: [_STORER_MAP] [group->{group},value->{type(value)},format->{format}') from err
        return cls(self, group, encoding=encoding, errors=errors)
    if tt is None:
        if value is not None:
            if pt == 'series_table':
                index = getattr(value, 'index', None)
                if index is not None:
                    if index.nlevels == 1:
                        tt = 'appendable_series'
                    elif index.nlevels > 1:
                        tt = 'appendable_multiseries'
            elif pt == 'frame_table':
                index = getattr(value, 'index', None)
                if index is not None:
                    if index.nlevels == 1:
                        tt = 'appendable_frame'
                    elif index.nlevels > 1:
                        tt = 'appendable_multiframe'
    _TABLE_MAP = {'generic_table': GenericTable, 'appendable_series': AppendableSeriesTable, 'appendable_multiseries': AppendableMultiSeriesTable, 'appendable_frame': AppendableFrameTable, 'appendable_multiframe': AppendableMultiFrameTable, 'worm': WORMTable}
    try:
        cls = _TABLE_MAP[tt]
    except KeyError as err:
        raise TypeError(f'cannot properly create the storer for: [_TABLE_MAP] [group->{group},value->{type(value)},format->{format}') from err
    return cls(self, group, encoding=encoding, errors=errors)

def __init__(self, cropping=((1, 1), (1, 1), (1, 1)), data_format=None, **kwargs):
    super(Cropping3D, self).__init__(**kwargs)
    self.data_format = conv_utils.normalize_data_format(data_format)
    if isinstance(cropping, int):
        self.cropping = ((cropping, cropping), (cropping, cropping), (cropping, cropping))
    elif hasattr(cropping, '__len__'):
        if <MASK>:
            raise ValueError('`cropping` should have 3 elements. Found: ' + str(cropping))
        dim1_cropping = conv_utils.normalize_tuple(cropping[0], 2, '1st entry of cropping')
        dim2_cropping = conv_utils.normalize_tuple(cropping[1], 2, '2nd entry of cropping')
        dim3_cropping = conv_utils.normalize_tuple(cropping[2], 2, '3rd entry of cropping')
        self.cropping = (dim1_cropping, dim2_cropping, dim3_cropping)
    else:
        raise ValueError('`cropping` should be either an int, a tuple of 3 ints (symmetric_dim1_crop, symmetric_dim2_crop, symmetric_dim3_crop), or a tuple of 3 tuples of 2 ints ((left_dim1_crop, right_dim1_crop), (left_dim2_crop, right_dim2_crop), (left_dim3_crop, right_dim2_crop)). Found: ' + str(cropping))
    self.input_spec = InputSpec(ndim=5)

def _create_nonlocal_declarations(self, vars_):
    vars_ = set(vars_)
    results = []
    global_vars = self.state[_Function].scope.globals & vars_
    if global_vars:
        results.append(gast.Global([str(v) for v in global_vars]))
    nonlocal_vars = [v for v in vars_ if not v.is_composite() and v not in global_vars]
    if <MASK>:
        results.append(gast.Nonlocal([str(v) for v in nonlocal_vars]))
    return results

def remove_field(self, model, field):
    """
        Remove a field from a model. Usually involves deleting a column,
        but for M2Ms may involve deleting a table.
        """
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        return self.delete_model(field.remote_field.through)
    if field.db_parameters(connection=self.connection)['type'] is None:
        return
    if field.remote_field:
        fk_names = self._constraint_names(model, [field.column], foreign_key=True)
        for fk_name in fk_names:
            self.execute(self._delete_fk_sql(model, fk_name))
    sql = self.sql_delete_column % {'table': self.quote_name(model._meta.db_table), 'column': self.quote_name(field.column)}
    self.execute(sql)
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()
    for sql in list(self.deferred_sql):
        if <MASK>:
            self.deferred_sql.remove(sql)

def get_traceback_frames(self):
    exceptions = []
    exc_value = self.exc_value
    while exc_value:
        exceptions.append(exc_value)
        exc_value = self._get_explicit_or_implicit_cause(exc_value)
        if <MASK>:
            warnings.warn("Cycle in the exception chain detected: exception '%s' encountered again." % exc_value, ExceptionCycleWarning)
            break
    frames = []
    if not exceptions:
        return frames
    exc_value = exceptions.pop()
    tb = self.tb if not exceptions else exc_value.__traceback__
    while True:
        frames.extend(self.get_exception_traceback_frames(exc_value, tb))
        try:
            exc_value = exceptions.pop()
        except IndexError:
            break
        tb = exc_value.__traceback__
    return frames

@staticmethod
def _get_call_args(backend_name: str, data: Series | DataFrame, args, kwargs):
    """
        This function makes calls to this accessor `__call__` method compatible
        with the previous `SeriesPlotMethods.__call__` and
        `DataFramePlotMethods.__call__`. Those had slightly different
        signatures, since `DataFramePlotMethods` accepted `x` and `y`
        parameters.
        """
    if isinstance(data, ABCSeries):
        arg_def = [('kind', 'line'), ('ax', None), ('figsize', None), ('use_index', True), ('title', None), ('grid', None), ('legend', False), ('style', None), ('logx', False), ('logy', False), ('loglog', False), ('xticks', None), ('yticks', None), ('xlim', None), ('ylim', None), ('rot', None), ('fontsize', None), ('colormap', None), ('table', False), ('yerr', None), ('xerr', None), ('label', None), ('secondary_y', False), ('xlabel', None), ('ylabel', None)]
    elif <MASK>:
        arg_def = [('x', None), ('y', None), ('kind', 'line'), ('ax', None), ('subplots', False), ('sharex', None), ('sharey', False), ('layout', None), ('figsize', None), ('use_index', True), ('title', None), ('grid', None), ('legend', True), ('style', None), ('logx', False), ('logy', False), ('loglog', False), ('xticks', None), ('yticks', None), ('xlim', None), ('ylim', None), ('rot', None), ('fontsize', None), ('colormap', None), ('table', False), ('yerr', None), ('xerr', None), ('secondary_y', False), ('xlabel', None), ('ylabel', None)]
    else:
        raise TypeError(f'Called plot accessor for type {type(data).__name__}, expected Series or DataFrame')
    if args and isinstance(data, ABCSeries):
        positional_args = str(args)[1:-1]
        keyword_args = ', '.join([f'{name}={value!r}' for ((name, _), value) in zip(arg_def, args, strict=False)])
        msg = f'`Series.plot()` should not be called with positional arguments, only keyword arguments. The order of positional arguments will change in the future. Use `Series.plot({keyword_args})` instead of `Series.plot({positional_args})`.'
        raise TypeError(msg)
    pos_args = {name: value for ((name, _), value) in zip(arg_def, args, strict=False)}
    if backend_name == 'pandas.plotting._matplotlib':
        kwargs = dict(arg_def, **pos_args, **kwargs)
    else:
        kwargs = dict(pos_args, **kwargs)
    x = kwargs.pop('x', None)
    y = kwargs.pop('y', None)
    kind = kwargs.pop('kind', 'line')
    return (x, y, kind, kwargs)

def init_xsel_clipboard():
    DEFAULT_SELECTION = '-b'
    PRIMARY_SELECTION = '-p'

    def copy_xsel(text, primary=False):
        text = _stringifyText(text)
        selection_flag = DEFAULT_SELECTION
        if <MASK>:
            selection_flag = PRIMARY_SELECTION
        with subprocess.Popen(['xsel', selection_flag, '-i'], stdin=subprocess.PIPE, close_fds=True) as p:
            p.communicate(input=text.encode(ENCODING))

    def paste_xsel(primary=False):
        selection_flag = DEFAULT_SELECTION
        if primary:
            selection_flag = PRIMARY_SELECTION
        with subprocess.Popen(['xsel', selection_flag, '-o'], stdout=subprocess.PIPE, close_fds=True) as p:
            stdout = p.communicate()[0]
        return stdout.decode(ENCODING)
    return (copy_xsel, paste_xsel)

