def _persistent_reduction_configs(size_hints, reduction_hint=False, inductor_meta=None, triton_meta=None):
    xnumel = size_hints['x']
    rnumel = get_total_reduction_numel(size_hints)
    loads_and_stores = inductor_meta.get('num_load', 0) + inductor_meta.get('num_store', 0)
    MAX_PERSISTENT_BLOCK_NUMEL = 4096
    if triton_meta.get('native_matmul'):
        if <MASK>:
            return [make_matmul_triton_config(sizes, num_warps, num_stages) for (sizes, num_warps, num_stages) in triton_native_persistent_mm_configs]
        elif len(size_hints) == 4:
            return [make_matmul_triton_config(sizes, num_warps, num_stages) for (sizes, num_warps, num_stages) in triton_native_persistent_bmm_configs]
        else:
            raise NotImplementedError('native matmul only supports mm/bmm pattern')
    max_autotune_enabled = inductor_meta.get('max_autotune') or inductor_meta.get('max_autotune_pointwise')
    if torch.version.hip:
        xblock_vals = [1, 4, 8, 16, 32, 64, 128, 256]
    else:
        xblock_vals = [1, 8, 32, 128]
    if 'y' not in size_hints:
        configs = [triton_config_reduction(size_hints, xblock, rnumel, register_intensive=True, reduction_hint=reduction_hint) for xblock in xblock_vals if xblock == 1 or (rnumel * xblock <= MAX_PERSISTENT_BLOCK_NUMEL and xblock <= xnumel)]
    else:
        configs = []
        assert 'tiling_scores' in inductor_meta
        x_y_scores = {dim: inductor_meta['tiling_scores'][dim] for dim in ('x', 'y')}
        for target_block_size in xblock_vals:
            if target_block_size * rnumel > MAX_PERSISTENT_BLOCK_NUMEL:
                continue
            block_sizes = match_target_block_product(size_hints, x_y_scores, target_block_size)
            configs.append(triton_config_tiled_reduction(size_hints, block_sizes['x'], block_sizes['y'], rnumel))
    tiny_configs = [triton_config_reduction(size_hints, 2 * (256 // rnumel) if rnumel <= 256 else 1, rnumel)]
    if 'y' in size_hints:
        pass
    elif not max_autotune_enabled:
        if reduction_hint == ReductionHint.INNER and rnumel >= 256:
            if rnumel > 1024:
                configs = configs[:1]
            else:
                x_block = 8
                if xnumel // x_block < 128 or loads_and_stores >= 5:
                    x_block = 1
                configs = [triton_config_reduction(size_hints, x_block, rnumel, register_intensive=True)]
        elif reduction_hint == ReductionHint.OUTER:
            configs = configs[-1:]
        elif reduction_hint == ReductionHint.OUTER_TINY:
            configs = tiny_configs
    elif torch.version.hip:
        for conf in tiny_configs:
            if conf not in configs:
                configs.append(conf)
    for c in configs:
        for prefix in size_hints:
            if prefix_is_reduction(prefix):
                c.kwargs.pop(f'{prefix.upper()}BLOCK')
    return configs

def match(self, event: _ProfilerEvent):
    if event.name != 'aten::select':
        return False
    if event.id in self.visited:
        return False
    repeat_count = 1
    (_, next) = self.siblings_of(event)
    if len(next) <= 1:
        return False

    def same_ops(list1, list2) -> bool:
        if len(list1) != len(list2):
            return False
        for (op1, op2) in zip(list1, list2):
            if op1.name != op2.name:
                return False
        return True
    next_select_idx = index_of_first_match(next, lambda e: e.name == 'aten::select')
    if <MASK>:
        return False
    indexing_ops = [event] + next[:next_select_idx]
    next = next[len(indexing_ops) - 1:]
    for i in range(0, len(next), len(indexing_ops)):
        if same_ops(indexing_ops, next[i:i + len(indexing_ops)]):
            repeat_count += 1
            self.visited.add(next[i].id)
        else:
            break
    return repeat_count >= 10

def _unique_np(values, return_inverse=False, return_counts=False):
    """Helper function to find unique values for numpy arrays that correctly
    accounts for nans. See `_unique` documentation for details."""
    (xp, _) = get_namespace(values)
    (inverse, counts) = (None, None)
    if return_inverse and return_counts:
        (uniques, _, inverse, counts) = xp.unique_all(values)
    elif <MASK>:
        (uniques, inverse) = xp.unique_inverse(values)
    elif return_counts:
        (uniques, counts) = xp.unique_counts(values)
    else:
        uniques = xp.unique_values(values)
    if uniques.size and is_scalar_nan(uniques[-1]):
        nan_idx = xp.searchsorted(uniques, xp.nan)
        uniques = uniques[:nan_idx + 1]
        if return_inverse:
            inverse[inverse > nan_idx] = nan_idx
        if return_counts:
            counts[nan_idx] = xp.sum(counts[nan_idx:])
            counts = counts[:nan_idx + 1]
    ret = (uniques,)
    if return_inverse:
        ret += (inverse,)
    if return_counts:
        ret += (counts,)
    return ret[0] if len(ret) == 1 else ret

@dispatch.dispatch_for_binary_elementwise_apis(ragged_tensor.RaggedOrDense, ragged_tensor.RaggedOrDense)
def ragged_binary_elementwise_op_impl(op, x, y):
    """Binary elementwise api handler for RaggedTensors."""
    x_is_ragged = ragged_tensor.is_ragged(x)
    y_is_ragged = ragged_tensor.is_ragged(y)
    x = ragged_tensor.convert_to_tensor_or_ragged_tensor(x, preferred_dtype=y.dtype if y_is_ragged else None)
    y = ragged_tensor.convert_to_tensor_or_ragged_tensor(y, preferred_dtype=x.dtype)
    if x_is_ragged and y_is_ragged:
        (x, y) = ragged_tensor.match_row_splits_dtypes(x, y)
    if x_is_ragged and y_is_ragged or (x_is_ragged and x.flat_values.shape.ndims <= y.shape.ndims) or (y_is_ragged and y.flat_values.shape.ndims <= x.shape.ndims):
        shape_x = DynamicRaggedShape.from_tensor(x)
        shape_y = DynamicRaggedShape.from_tensor(y)
        if shape_x.dtype != shape_y.dtype:
            if <MASK>:
                shape_x = shape_x.with_dtype(shape_y.dtype)
            elif not y_is_ragged:
                shape_y = shape_y.with_dtype(shape_x.dtype)
        if _row_partitions_identical(shape_x, shape_y):
            return shape_x._add_row_partitions(op(x.flat_values, y.flat_values), validate=False)
        (shape_z, bcast_xz, bcast_yz) = broadcast_dynamic_shape_extended(shape_x, shape_y)
        x_new_flat = bcast_xz.broadcast_flat_values(x, inner_dimensions=False)
        y_new_flat = bcast_yz.broadcast_flat_values(y, inner_dimensions=False)
        z_flat = op(x_new_flat, y_new_flat)
        return shape_z._add_row_partitions(z_flat, validate=True)
    x_values = x.flat_values if ragged_tensor.is_ragged(x) else x
    y_values = y.flat_values if ragged_tensor.is_ragged(y) else y
    mapped_values = op(x_values, y_values)
    if isinstance(mapped_values, bool):
        return mapped_values
    if ragged_tensor.is_ragged(x):
        return x.with_flat_values(mapped_values)
    else:
        return y.with_flat_values(mapped_values)

def _filter(self, category=Warning, message='', module=None, record=False):
    if <MASK>:
        record = []
    else:
        record = None
    if self._entered:
        if module is None:
            warnings.filterwarnings('always', category=category, message=message)
        else:
            module_regex = module.__name__.replace('.', '\\.') + '$'
            warnings.filterwarnings('always', category=category, message=message, module=module_regex)
            self._tmp_modules.add(module)
            self._clear_registries()
        self._tmp_suppressions.append((category, message, re.compile(message, re.I), module, record))
    else:
        self._suppressions.append((category, message, re.compile(message, re.I), module, record))
    return record

def _returnIfTrue(self, data: _T) -> tuple[bool, _T]:
    condition = self._apply_filter_fn(data)
    if <MASK>:
        result = []
        for (idx, mask) in enumerate(df_wrapper.iterate(condition)):
            if mask:
                result.append(df_wrapper.get_item(data, idx))
        if result:
            return (True, df_wrapper.concat(result))
        else:
            return (False, None)
    if not isinstance(condition, bool):
        raise ValueError('Boolean output is required for `filter_fn` of FilterIterDataPipe, got', type(condition))
    return (condition, data)

def generate_statement(self):
    """Generate a statement node, dispatching to the correct class method."""
    desired_node = StatementSampler().sample()
    self.depth += 1
    if <MASK>:
        if self.depth > self.max_depth:
            return self.generate_statement()
    method = 'generate_' + desired_node.__name__
    visitor = getattr(self, method)
    node = visitor()
    self.depth -= 1
    return node

def after_run(self, run_context, run_values):
    _ = run_context
    if not self._summary_writer:
        return
    stale_global_step = run_values.results['global_step']
    global_step = stale_global_step + 1
    if self._next_step is None or self._request_summary:
        global_step = run_context.session.run(self._global_step_tensor)
    if self._next_step is None:
        self._summary_writer.add_session_log(SessionLog(status=SessionLog.START), global_step)
    if self._request_summary:
        self._timer.update_last_triggered_step(global_step)
        if <MASK>:
            for summary in run_values.results['summary']:
                self._summary_writer.add_summary(summary, global_step)
    self._next_step = global_step + 1

def reduce(self, operation, app_label):
    if <MASK>:
        return []
    if isinstance(operation, RenameIndex) and self.index.name == operation.old_name:
        index = copy(self.index)
        index.name = operation.new_name
        return [replace(self, index=index)]
    return super().reduce(operation, app_label)

def _remove_bias_handles(module: nn.Module) -> None:
    if hasattr(module, '_forward_hooks'):
        bias_hooks: list[int] = []
        for (key, hook) in module._forward_hooks.items():
            if <MASK>:
                bias_hooks.append(key)
        for key in bias_hooks:
            del module._forward_hooks[key]

