@_onnx_symbolic('aten::prelu')
def prelu(g: jit_utils.GraphContext, self, weight):
    self_rank = symbolic_helper._get_tensor_rank(self)
    weight_sizes = symbolic_helper._get_tensor_sizes(weight)
    weight_rank = len(weight_sizes)
    if self_rank is not None:
        if self_rank > 2:
            weight = symbolic_helper._unsqueeze_helper(g, weight, list(range(1, self_rank - 1)))
        elif self_rank == 0 and weight_sizes == [1]:
            weight = symbolic_helper._squeeze_helper(g, weight, [0])
            weight_rank = 0
    if <MASK>:
        assert self_rank >= weight_rank, f'rank(x) should be >= rank(slope) but got {self_rank} < {weight_rank}'
    return g.op('PRelu', self, weight)

def sort_index(self, *, axis: Axis=0, level: IndexLabel | None=None, ascending: bool | Sequence[bool]=True, inplace: bool=False, kind: SortKind='quicksort', na_position: NaPosition='last', sort_remaining: bool=True, ignore_index: bool=False, key: IndexKeyFunc | None=None) -> Self | None:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    axis = self._get_axis_number(axis)
    ascending = validate_ascending(ascending)
    target = self._get_axis(axis)
    indexer = get_indexer_indexer(target, level, ascending, kind, na_position, sort_remaining, key)
    if indexer is None:
        if inplace:
            result = self
        else:
            result = self.copy(deep=False)
        if <MASK>:
            if axis == 1:
                result.columns = default_index(len(self.columns))
            else:
                result.index = default_index(len(self))
        if inplace:
            return None
        else:
            return result
    baxis = self._get_block_manager_axis(axis)
    new_data = self._mgr.take(indexer, axis=baxis, verify=False)
    if not ignore_index:
        new_axis = new_data.axes[baxis]._sort_levels_monotonic()
    else:
        new_axis = default_index(len(indexer))
    new_data.set_axis(baxis, new_axis)
    result = self._constructor_from_mgr(new_data, axes=new_data.axes)
    if inplace:
        return self._update_inplace(result)
    else:
        return result.__finalize__(self, method='sort_index')

def print_summary_table(data, print_dataframe=False):
    if print_dataframe:
        pd.options.display.max_rows = 1000
        pd.options.display.max_columns = 1000
        pd.options.display.width = 2000
        print(data)
    width = max(map(len, data.columns))
    for col in data.columns:
        try:
            if <MASK>:
                continue
            elif col in ('pct_ops', 'pct_time'):
                print(col.ljust(width), f'{data[col].mean():.3%}')
            elif col in ('graphs', 'graph_calls', 'captured_ops', 'total_ops'):
                print(col.ljust(width), f'{data[col].mean():.3f}')
            elif col in 'compilation_latency':
                print(col.ljust(width), f'mean={data[col].mean():.3f} seconds')
            elif col in 'compression_ratio':
                print(col.ljust(width), f'mean={data[col].mean():.3f}x')
            elif col in 'accuracy':
                pass_rate = (data[col] == 'pass').mean()
                print(col.ljust(width), f'pass_rate={100 * pass_rate:.2f}%')
            else:
                cdata = data[col]
                print(col.ljust(width), f'gmean={gmean(cdata):.2f}x mean={cdata.mean():.3f}x')
        except Exception:
            pass

@_onnx_symbolic('aten::binary_cross_entropy_with_logits')
@symbolic_helper.parse_args('v', 'v', 'v', 'v', 'i')
def binary_cross_entropy_with_logits(g: jit_utils.GraphContext, input, target, weight, pos_weight, reduction):
    p = g.op('Constant', value_t=torch.tensor([1]))
    sig_x = opset9.sigmoid(g, input)
    log_sig_x = opset9.log(g, sig_x)
    sub_1_x = opset9.sub(g, p, sig_x)
    sub_1_y = opset9.sub(g, p, target)
    log_1_x = opset9.log(g, sub_1_x)
    if pos_weight is None or symbolic_helper._is_none(pos_weight):
        output = opset9.neg(g, opset9.add(g, opset9.mul(g, target, log_sig_x), opset9.mul(g, sub_1_y, log_1_x)))
    else:
        output = opset9.neg(g, opset9.add(g, opset9.mul(g, opset9.mul(g, target, log_sig_x), pos_weight), opset9.mul(g, sub_1_y, log_1_x)))
    if weight is not None and (not symbolic_helper._is_none(weight)):
        output = opset9.mul(g, weight, output)
    reduction = symbolic_helper._maybe_get_const(reduction, 'i')
    if reduction == 0:
        return output
    elif reduction == 1:
        return g.op('ReduceMean', output, keepdims_i=0)
    elif <MASK>:
        return g.op('ReduceSum', output, keepdims_i=0)
    else:
        return symbolic_helper._onnx_unsupported('binary_cross_entropy_with_logits with reduction other than none, mean, or sum', input)

def _reorder_indexer(self, seq: tuple[Scalar | Iterable | AnyArrayLike, ...], indexer: npt.NDArray[np.intp]) -> npt.NDArray[np.intp]:
    """
        Reorder an indexer of a MultiIndex (self) so that the labels are in the
        same order as given in seq

        Parameters
        ----------
        seq : label/slice/list/mask or a sequence of such
        indexer: a position indexer of self

        Returns
        -------
        indexer : a sorted position indexer of self ordered as seq
        """
    need_sort = False
    for (i, k) in enumerate(seq):
        if com.is_null_slice(k) or com.is_bool_indexer(k) or is_scalar(k):
            pass
        elif is_list_like(k):
            if len(k) <= 1:
                pass
            elif self._is_lexsorted():
                k_codes = self.levels[i].get_indexer(k)
                k_codes = k_codes[k_codes >= 0]
                need_sort = (k_codes[:-1] > k_codes[1:]).any()
            else:
                need_sort = True
        elif isinstance(k, slice):
            if self._is_lexsorted():
                need_sort = k.step is not None and k.step < 0
            else:
                need_sort = True
        else:
            need_sort = True
        if need_sort:
            break
    if not need_sort:
        return indexer
    n = len(self)
    keys: tuple[np.ndarray, ...] = ()
    for (i, k) in enumerate(seq):
        if is_scalar(k):
            k = [k]
        if <MASK>:
            new_order = np.arange(n)[indexer]
        elif is_list_like(k):
            if not isinstance(k, (np.ndarray, ExtensionArray, Index, ABCSeries)):
                k = sanitize_array(k, None)
            k = algos.unique(k)
            key_order_map = np.ones(len(self.levels[i]), dtype=np.uint64) * len(self.levels[i])
            level_indexer = self.levels[i].get_indexer(k)
            level_indexer = level_indexer[level_indexer >= 0]
            key_order_map[level_indexer] = np.arange(len(level_indexer))
            new_order = key_order_map[self.codes[i][indexer]]
        elif isinstance(k, slice) and k.step is not None and (k.step < 0):
            new_order = np.arange(n - 1, -1, -1)[indexer]
        elif isinstance(k, slice) and k.start is None and (k.stop is None):
            new_order = np.ones((n,), dtype=np.intp)[indexer]
        else:
            new_order = np.arange(n)[indexer]
        keys = (new_order,) + keys
    ind = np.lexsort(keys)
    return indexer[ind]

def _validate_compile(self, optimizer, metrics, **kwargs):
    """Performs validation checks for the default `compile`."""
    if any((isinstance(opt, optimizer_v1.Optimizer) for opt in nest.flatten(optimizer))):
        raise ValueError('`tf.compat.v1.keras` Optimizer (', optimizer, ') is not supported when eager execution is enabled. Use a `tf.keras` Optimizer instead, or disable eager execution.')
    kwargs.pop('cloning', None)
    kwargs.pop('experimental_run_tf_function', None)
    if <MASK>:
        raise ValueError('Distribute argument in compile is not available in TF 2.0 please create the model under the distribution strategy scope.')
