def compare(before, after, format_flamegraph=format_flamegraph):

    def _seg_key(seg):
        return (seg['address'], seg['total_size'])

    def _seg_info(seg):
        return f"stream_{seg['stream']};seg_{seg['address']}"
    f = io.StringIO()
    before_segs = {_seg_key(seg) for seg in before}
    after_segs = {_seg_key(seg) for seg in after}
    print(f'only_before = {[a for (a, _) in before_segs - after_segs]}')
    print(f'only_after = {[a for (a, _) in after_segs - before_segs]}')
    for seg in before:
        if _seg_key(seg) not in after_segs:
            _write_blocks(f, f'only_before;{_seg_info(seg)}', seg['blocks'])
    for seg in after:
        if <MASK>:
            _write_blocks(f, f'only_after;{_seg_info(seg)}', seg['blocks'])
    return format_flamegraph(f.getvalue())

def _validate_call_args(self, inputs, mask):
    """Validates arguments of the call method."""
    class_name = self.__class__.__name__
    if <MASK>:
        raise ValueError('{} layer must be called on a list of inputs, namely [query, value] or [query, value, key].'.format(class_name))
    if len(inputs) < 2 or len(inputs) > 3:
        raise ValueError('{} layer accepts inputs list of length 2 or 3, namely [query, value] or [query, value, key]. Given length: {}'.format(class_name, len(inputs)))
    if mask:
        if not isinstance(mask, list):
            raise ValueError('{} layer mask must be a list, namely [query_mask, value_mask].'.format(class_name))
        if len(mask) < 2 or len(mask) > len(inputs):
            raise ValueError('{} layer mask must be a list of length 2, namely [query_mask, value_mask]. Given length: {}'.format(class_name, len(mask)))

def _value_formatter(self, float_format: FloatFormatType | None=None, threshold: float | None=None) -> Callable:
    """Returns a function to be applied on each value to format it"""
    if float_format is None:
        float_format = self.float_format
    if float_format:

        def base_formatter(v):
            assert float_format is not None
            return float_format(value=v) if notna(v) else self.na_rep
    else:

        def base_formatter(v):
            return str(v) if notna(v) else self.na_rep
    if self.decimal != '.':

        def decimal_formatter(v):
            return base_formatter(v).replace('.', self.decimal, 1)
    else:
        decimal_formatter = base_formatter
    if threshold is None:
        return decimal_formatter

    def formatter(value):
        if notna(value):
            if <MASK>:
                return decimal_formatter(value)
            else:
                return decimal_formatter(0.0)
        else:
            return self.na_rep
    return formatter

def _get_indexer(self, target: Index, method: str_t | None=None, limit: int | None=None, tolerance=None) -> npt.NDArray[np.intp]:
