def to_dict(self) -> dict[str, Union[int, float, str, list[int], list[float], list[str]]]:
    """Convert the encoded attributes back to a dictionary for creating an ONNX node."""
    attrs: dict[str, Union[int, float, str, list[int], list[float], list[str]]] = {}
    for (i, key) in enumerate(self.attr_keys):
        attr_type = self.attr_types[i]
        if attr_type == _INT_TYPE:
            attrs[key] = self.attr_ints[self.attr_pos[i][0]]
        elif attr_type == _FLOAT_TYPE:
            attrs[key] = self.attr_floats[self.attr_pos[i][0]]
        elif attr_type == _STRING_TYPE:
            attrs[key] = self.attr_strs[self.attr_pos[i][0]]
        elif attr_type == _FLOAT_SEQ_TYPE:
            attrs[key] = self.attr_floats[self.attr_pos[i][0]:self.attr_pos[i][1]]
        elif <MASK>:
            attrs[key] = self.attr_ints[self.attr_pos[i][0]:self.attr_pos[i][1]]
        elif attr_type == _STRING_SEQ_TYPE:
            attrs[key] = self.attr_strs[self.attr_pos[i][0]:self.attr_pos[i][1]]
        else:
            raise ValueError(f'Unsupported attribute type: {attr_type}')
    return attrs

def compute_workload(self):
    if self.mode == 'fwd':
        count = 1
    elif <MASK>:
        count = 1 + (1 + 1)
    else:
        raise ValueError(f'invalid mode: {self.mode}')
    op_count = self.N * self.iC / self.groups * self.oC * self.kernel_size * self.kernel_size * self.H * self.W
    op_count *= 2
    return op_count * count

def _unwrap_batched(batched_outputs: Union[Tensor, tuple[Tensor, ...]], out_dims: out_dims_t, vmap_level: int, batch_size: int, func: Callable, allow_none_pass_through: bool=False) -> tuple:
    num_outputs = _num_outputs(batched_outputs)
    out_dims_as_tuple = _as_tuple(out_dims, num_outputs, lambda : f'vmap({_get_name(func)}, ..., out_dims={out_dims}): `out_dims` must have one dim per output (got {num_outputs} outputs) of {_get_name(func)}.')
    if isinstance(batched_outputs, Tensor):
        out_dim = out_dims_as_tuple[0]
        return torch._remove_batch_dim(batched_outputs, vmap_level, batch_size, out_dim)
    if <MASK>:
        return tuple((torch._remove_batch_dim(out, vmap_level, batch_size, out_dim) if out is not None else None for (out, out_dim) in zip(batched_outputs, out_dims_as_tuple)))
    else:
        return tuple((torch._remove_batch_dim(out, vmap_level, batch_size, out_dim) for (out, out_dim) in zip(batched_outputs, out_dims_as_tuple)))

def _check_algorithm_metric(self):
    if self.algorithm == 'auto':
        if self.metric == 'precomputed':
            alg_check = 'brute'
        elif <MASK>:
            alg_check = 'ball_tree'
        else:
            alg_check = 'brute'
    else:
        alg_check = self.algorithm
    if callable(self.metric):
        if self.algorithm == 'kd_tree':
            raise ValueError("kd_tree does not support callable metric '%s'Function call overhead will resultin very poor performance." % self.metric)
    elif self.metric not in VALID_METRICS[alg_check] and (not isinstance(self.metric, DistanceMetric)):
        raise ValueError("Metric '%s' not valid. Use sorted(sklearn.neighbors.VALID_METRICS['%s']) to get valid options. Metric can also be a callable function." % (self.metric, alg_check))
    if self.metric_params is not None and 'p' in self.metric_params:
        if self.p is not None:
            warnings.warn('Parameter p is found in metric_params. The corresponding parameter from __init__ is ignored.', SyntaxWarning, stacklevel=3)

def _create_storer(self, group, format=None, value: DataFrame | Series | None=None, encoding: str='UTF-8', errors: str='strict') -> GenericFixed | Table:
    """return a suitable class to operate"""
    cls: type[GenericFixed | Table]
    if value is not None and (not isinstance(value, (Series, DataFrame))):
        raise TypeError('value must be None, Series, or DataFrame')
    pt = getattr(group._v_attrs, 'pandas_type', None)
    tt = getattr(group._v_attrs, 'table_type', None)
    if pt is None:
        if value is None:
            _tables()
            assert _table_mod is not None
            if getattr(group, 'table', None) or isinstance(group, _table_mod.table.Table):
                pt = 'frame_table'
                tt = 'generic_table'
            else:
                raise TypeError('cannot create a storer if the object is not existing nor a value are passed')
        else:
            if isinstance(value, Series):
                pt = 'series'
            else:
                pt = 'frame'
            if <MASK>:
                pt += '_table'
    if 'table' not in pt:
        _STORER_MAP = {'series': SeriesFixed, 'frame': FrameFixed}
        try:
            cls = _STORER_MAP[pt]
        except KeyError as err:
            raise TypeError(f'cannot properly create the storer for: [_STORER_MAP] [group->{group},value->{type(value)},format->{format}') from err
        return cls(self, group, encoding=encoding, errors=errors)
    if tt is None:
        if value is not None:
            if pt == 'series_table':
                index = getattr(value, 'index', None)
                if index is not None:
                    if index.nlevels == 1:
                        tt = 'appendable_series'
                    elif index.nlevels > 1:
                        tt = 'appendable_multiseries'
            elif pt == 'frame_table':
                index = getattr(value, 'index', None)
                if index is not None:
                    if index.nlevels == 1:
                        tt = 'appendable_frame'
                    elif index.nlevels > 1:
                        tt = 'appendable_multiframe'
    _TABLE_MAP = {'generic_table': GenericTable, 'appendable_series': AppendableSeriesTable, 'appendable_multiseries': AppendableMultiSeriesTable, 'appendable_frame': AppendableFrameTable, 'appendable_multiframe': AppendableMultiFrameTable, 'worm': WORMTable}
    try:
        cls = _TABLE_MAP[tt]
    except KeyError as err:
        raise TypeError(f'cannot properly create the storer for: [_TABLE_MAP] [group->{group},value->{type(value)},format->{format}') from err
    return cls(self, group, encoding=encoding, errors=errors)

