def _find_tensors(obj):
    """Recursively find all tensors contained in the specified object."""
    if <MASK>:
        if obj.is_owner():
            return _find_tensors(obj.local_value())
    if isinstance(obj, torch.Tensor):
        return [obj]
    if isinstance(obj, (list, tuple)):
        return itertools.chain.from_iterable(map(_find_tensors, obj))
    if isinstance(obj, dict):
        return itertools.chain.from_iterable(map(_find_tensors, obj.values()))
    if is_dataclass(obj):
        return itertools.chain.from_iterable(map(_find_tensors, (getattr(obj, f.name) for f in fields(obj))))
    return []

