        inner_fn = fn.value
    if hasattr(fn, 'fn'):
        inner_fn = fn.fn
    if <MASK>:
        raise AssertionError(f'Attempt to trace forbidden callable {inner_fn}')
    self.push(fn.call_function(self, args, kwargs))

def signature_of(arg: KernelArgType, *, size_dtype: Optional[str]) -> str:
    if isinstance(arg, TensorArg):
        if arg.dtype == torch.float8_e4m3fn:
            typ = '*fp8e4nv'
        elif arg.dtype == torch.float8_e5m2:
            typ = '*fp8e5'
        elif arg.dtype == torch.float8_e4m3fnuz:
            typ = '*fp8e4b8'
        elif arg.dtype == torch.float8_e5m2fnuz:
            typ = '*fp8e5b16'
        else:
            typ = _type_of(arg.dtype)
        if <MASK>:
            new_typ = typ.lstrip('*')
            if new_typ in ['fp16', 'bf16']:
                return 'fp32'
            else:
                return new_typ
        else:
            return typ
    if isinstance(arg, SizeArg):
        if arg.expr is None:
            if triton_version_uses_attrs_dict():
                return 'constexpr'
            else:
                return '*i8'
        elif _arg_equals_1(arg) and triton_version_uses_attrs_dict():
            return 'constexpr'
        elif isinstance(arg.expr, (float, sympy.Float)):
            return 'fp32'
        elif isinstance(arg.expr, bool):
            return 'i1'
        if size_dtype == 'tl.int32':
            return 'i32'
        elif size_dtype == 'tl.int64':
            return 'i64'
        elif size_dtype is None:
            int_max = torch.iinfo(torch.int32).max
            if expr_fits_within_32bit(arg.expr):
                V.graph.sizevars.check_leq(arg.expr, int_max)
                return 'i32'
            else:
                return 'i64'
        else:
            raise NotImplementedError(f'unhandled size_dtype {size_dtype}')
    if isinstance(arg, WorkspaceArg):
        return _type_of(arg.dtype)
    if isinstance(arg, TMADescriptorArg):
        if arg.api_type == 'experimental':
            return 'nvTmaDesc'
        else:
            assert arg.api_type == 'stable'
            assert arg.block_shape is not None
            assert arg.dtype is not None
            inner = _type_of(arg.dtype)[1:]
            return f'tensordesc<{inner}{list(arg.block_shape)}>'
    if isinstance(arg, ConstexprArg):
        return 'constexpr'
    raise NotImplementedError(f'unhandled {type(arg)}: {arg}')

def _interleave(self, iterators, cycle_length):
    pending_iterators = iterators
    open_iterators = []
    num_open = 0
    for i in range(cycle_length):
        if pending_iterators:
            open_iterators.append(pending_iterators.pop(0))
            num_open += 1
    while num_open:
        for i in range(min(cycle_length, len(open_iterators))):
            if <MASK>:
                continue
            try:
                yield next(open_iterators[i])
            except StopIteration:
                if pending_iterators:
                    open_iterators[i] = pending_iterators.pop(0)
                else:
                    open_iterators[i] = None
                    num_open -= 1

def isdtype(dtype: DType, kind: Union[DType, str, Tuple[Union[DType, str], ...]], *, _tuple=True) -> bool:
    """
    Returns a boolean indicating whether a provided dtype is of a specified data type ``kind``.

    Note that outside of this function, this compat library does not yet fully
    support complex numbers.

    See
    https://data-apis.org/array-api/latest/API_specification/generated/array_api.isdtype.html
    for more details
    """
    if isinstance(kind, tuple) and _tuple:
        return _builtin_any((isdtype(dtype, k, _tuple=False) for k in kind))
    elif <MASK>:
        if kind == 'bool':
            return dtype == torch.bool
        elif kind == 'signed integer':
            return dtype in _int_dtypes and dtype.is_signed
        elif kind == 'unsigned integer':
            return dtype in _int_dtypes and (not dtype.is_signed)
        elif kind == 'integral':
            return dtype in _int_dtypes
        elif kind == 'real floating':
            return dtype.is_floating_point
        elif kind == 'complex floating':
            return dtype.is_complex
        elif kind == 'numeric':
            return isdtype(dtype, ('integral', 'real floating', 'complex floating'))
        else:
            raise ValueError(f'Unrecognized data type kind: {kind!r}')
    else:
        return dtype == kind

def process_rhs(self, compiler, connection):
    value = self.rhs
