        A masked array can also be created by taking a .view(MaskedArray).

        """
    copy = None if not copy else True
    _data = np.array(data, dtype=dtype, copy=copy, order=order, subok=True, ndmin=ndmin)
    _baseclass = getattr(data, '_baseclass', type(_data))
    if isinstance(data, MaskedArray) and data.shape != _data.shape:
        copy = True
    if isinstance(data, cls) and subok and (not isinstance(data, MaskedConstant)):
        _data = ndarray.view(_data, type(data))
    else:
        _data = ndarray.view(_data, cls)
    if hasattr(data, '_mask') and (not isinstance(data, ndarray)):
        _data._mask = data._mask
    mdtype = make_mask_descr(_data.dtype)
    if mask is nomask:
        if not keep_mask:
            if shrink:
                _data._mask = nomask
            else:
                _data._mask = np.zeros(_data.shape, dtype=mdtype)
        elif isinstance(data, (tuple, list)):
            try:
                mask = np.array([getmaskarray(np.asanyarray(m, dtype=_data.dtype)) for m in data], dtype=mdtype)
            except (ValueError, TypeError):
                mask = nomask
            if mdtype == MaskType and mask.any():
                _data._mask = mask
                _data._sharedmask = False
        else:
            _data._sharedmask = not copy
            if copy:
                _data._mask = _data._mask.copy()
                if getmask(data) is not nomask:
                    if data._mask.shape != data.shape:
                        data._mask.shape = data.shape
    else:
        if <MASK>:
            mask = False
        if mask is True and mdtype == MaskType:
            mask = np.ones(_data.shape, dtype=mdtype)
        elif mask is False and mdtype == MaskType:
            mask = np.zeros(_data.shape, dtype=mdtype)
        else:
            try:
                mask = np.array(mask, copy=copy, dtype=mdtype)
            except TypeError:
                mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
        if mask.shape != _data.shape:
            (nd, nm) = (_data.size, mask.size)
            if nm == 1:
                mask = np.resize(mask, _data.shape)
            elif nm == nd:
                mask = np.reshape(mask, _data.shape)
            else:
                msg = f'Mask and data not compatible: data size is {nd}, mask size is {nm}.'
                raise MaskError(msg)
            copy = True
        if _data._mask is nomask:
            _data._mask = mask
            _data._sharedmask = not copy
        elif not keep_mask:
            _data._mask = mask
            _data._sharedmask = not copy
        else:
            if _data.dtype.names is not None:

                def _recursive_or(a, b):
                    """do a|=b on each field of a, recursively"""
                    for name in a.dtype.names:
                        (af, bf) = (a[name], b[name])
                        if af.dtype.names is not None:
                            _recursive_or(af, bf)
                        else:
                            af |= bf
                _recursive_or(_data._mask, mask)
            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

def parse(self) -> list[CoverageRecord]:
    records: list[CoverageRecord] = []
    for file_info in self._llvm_coverage['files']:
        filepath = file_info['file']
        if self._skip_coverage(filepath):
            continue
        covered_lines: set[int] = set()
        uncovered_lines: set[int] = set()
        for line in file_info['lines']:
            line_number = line['line_number']
            count = line['count']
            if <MASK>:
                uncovered_lines.update([line_number])
            else:
                covered_lines.update([line_number])
        records.append(CoverageRecord(filepath, sorted(covered_lines), sorted(uncovered_lines)))
    return records

def _broadcast_dynamic_shape_next_layer(ac_0: _LayerBroadcaster, bc_0: _LayerBroadcaster, a_1: RowPartition, b_1: RowPartition) -> Tuple[RowPartition, _LayerBroadcaster, _LayerBroadcaster]:
    """Broadcast target and next layer broadcaster of two dynamic shapes.

     *--ac_0-->*<--bc_0--*
     |         |         |
    a_1       c_1       b_1
     |         |         |
     V         V         V
     *--ac_1-->*<--bc_1--*

  Args:
    ac_0: _LayerBroadcaster from a to c in the previous layer.
    bc_0: _LayerBroadcaster from b to c in the previous layer.
    a_1: a RowPartition for the next layer of a.
    b_1: a RowPartition for the next layer of b.

  Returns:
    (c_1, ac_1, bc_1)
    c_1: a RowPartition for the next layer of the dynamic shape.
    ac_1: _LayerBroadcaster from a to c in the next layer.
    bc_1: _LayerBroadcaster from b to c in the next layer.
  """
    if not isinstance(ac_0, _LayerBroadcaster):
        raise TypeError('ac_0 should be a _LayerBroadcaster')
    if not isinstance(bc_0, _LayerBroadcaster):
        raise TypeError('bc_0 should be a _LayerBroadcaster')
    if not isinstance(a_1, RowPartition):
        raise TypeError('a_1 should be a RowPartition')
    if <MASK>:
        raise TypeError('b_1 should be a RowPartition')
    if a_1.is_uniform():
        if b_1.is_uniform():
            return _broadcast_dynamic_shape_next_layer_both_uniform(ac_0, bc_0, a_1, b_1)
        else:
            return _broadcast_dynamic_shape_next_layer_half_ragged(ac_0, bc_0, a_1, b_1)
    elif b_1.is_uniform():
        [c_1, bc_1, ac_1] = _broadcast_dynamic_shape_next_layer_half_ragged(bc_0, ac_0, b_1, a_1)
        return (c_1, ac_1, bc_1)
    else:
        [ac_1, c_1a] = _broadcast_half(ac_0, a_1)
        [bc_1, c_1b] = _broadcast_half(bc_0, b_1)
        check_valid = [check_ops.assert_equal(c_1a.row_splits(), c_1b.row_splits())]
        return (c_1a._with_dependencies(check_valid), ac_1.with_dependencies(check_valid), bc_1.with_dependencies(check_valid))

@Appender(_read_method_doc)
def read(self, nrows: int | None=None) -> pd.DataFrame:
    if nrows is None:
        nrows = self.nobs
    read_lines = min(nrows, self.nobs - self._lines_read)
    read_len = read_lines * self.record_length
    if read_len <= 0:
        self.close()
        raise StopIteration
    raw = self.filepath_or_buffer.read(read_len)
    data = np.frombuffer(raw, dtype=self._dtype, count=read_lines)
    df_data = {}
    for (j, x) in enumerate(self.columns):
        vec = data['s' + str(j)]
        ntype = self.fields[j]['ntype']
        if ntype == 'numeric':
            vec = _handle_truncated_float_vec(vec, self.fields[j]['field_length'])
            miss = self._missing_double(vec)
            v = _parse_float_vec(vec)
            v[miss] = np.nan
        elif self.fields[j]['ntype'] == 'char':
            v = [y.rstrip() for y in vec]
            if <MASK>:
                v = [y.decode(self._encoding) for y in v]
        df_data.update({x: v})
    df = pd.DataFrame(df_data)
    if self._index is None:
        df.index = pd.Index(range(self._lines_read, self._lines_read + read_lines))
    else:
        df = df.set_index(self._index)
    self._lines_read += read_lines
    return df

def __init__(self, param, cursor, strings_only=False):
    if settings.USE_TZ and (isinstance(param, datetime.datetime) and (not isinstance(param, Oracle_datetime))):
        param = Oracle_datetime.from_datetime(param)
    string_size = 0
    has_boolean_data_type = cursor.database.features.supports_boolean_expr_in_select_clause
    if not has_boolean_data_type:
        if param is True:
            param = 1
        elif param is False:
            param = 0
    if hasattr(param, 'bind_parameter'):
        self.force_bytes = param.bind_parameter(cursor)
    elif isinstance(param, (bytes, datetime.timedelta)):
        self.force_bytes = param
    else:
        self.force_bytes = force_str(param, cursor.charset, strings_only)
        if isinstance(self.force_bytes, str):
            string_size = len(force_bytes(param, cursor.charset, strings_only))
    if <MASK>:
        self.input_size = param.input_size
    elif string_size > 4000:
        self.input_size = Database.DB_TYPE_CLOB
    elif isinstance(param, datetime.datetime):
        self.input_size = Database.DB_TYPE_TIMESTAMP
    elif has_boolean_data_type and isinstance(param, bool):
        self.input_size = Database.DB_TYPE_BOOLEAN
    else:
        self.input_size = None

def _get_output_names(self, graph_outputs: list[ir.IRNode]) -> list[str]:
    names = []
    shape_counter = itertools.count(0)
    none_counter = itertools.count(0)
    for node in graph_outputs:
        if isinstance(node, ir.NoneAsConstantBuffer):
            names.append(f'{self.name}_none{next(none_counter)}')
        elif <MASK>:
            names.append(f'{self.name}_shape{next(shape_counter)}')
        else:
            names.append(node.get_name())
    return names

@property
def underlying_value(self):
    if isinstance(self.vt, variables.LazyVariableTracker) and (not self.vt.is_realized()) and self.vt.is_hashable():
        return self.vt.original_value()
    if isinstance(self.vt, variables.TensorVariable):
        x = self.vt.as_proxy().node.meta['example_value']
    elif isinstance(self.vt, variables.TupleVariable):
        Hashable = ConstDictVariable._HashableTracker
        x = tuple((Hashable(e).underlying_value for e in self.vt.items))
    elif <MASK>:
        return self.vt.value
    elif isinstance(self.vt, variables.UnspecializedNNModuleVariable):
        return self.vt.value
    elif isinstance(self.vt, variables.UserFunctionVariable):
        return self.vt.get_function()
    elif isinstance(self.vt, variables.WeakRefVariable):
        Hashable = ConstDictVariable._HashableTracker
        return Hashable(self.vt.referent_vt).underlying_value
    elif isinstance(self.vt, variables.FrozenDataClassVariable):
        Hashable = ConstDictVariable._HashableTracker
        fields_values = {k: Hashable(v).underlying_value for (k, v) in self.vt.fields.items()}
        return variables.FrozenDataClassVariable.HashWrapper(self.vt.python_type(), fields_values)
    elif isinstance(self.vt, variables.UserDefinedObjectVariable):
        return self.vt.value
    else:
        x = self.vt.as_python_constant()
    return x

def _score(estimator, X_test, y_test, scorer, score_params, error_score='raise'):
    """Compute the score(s) of an estimator on a given test set.

    Will return a dict of floats if `scorer` is a _MultiMetricScorer, otherwise a single
    float is returned.
    """
    score_params = {} if score_params is None else score_params
    try:
        if y_test is None:
            scores = scorer(estimator, X_test, **score_params)
        else:
            scores = scorer(estimator, X_test, y_test, **score_params)
    except Exception:
        if isinstance(scorer, _MultimetricScorer):
            raise
        elif <MASK>:
            raise
        else:
            scores = error_score
            warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{format_exc()}', UserWarning)
    if isinstance(scorer, _MultimetricScorer):
        exception_messages = [(name, str_e) for (name, str_e) in scores.items() if isinstance(str_e, str)]
        if exception_messages:
            for (name, str_e) in exception_messages:
                scores[name] = error_score
                warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{str_e}', UserWarning)
    error_msg = 'scoring must return a number, got %s (%s) instead. (scorer=%s)'
    if isinstance(scores, dict):
        for (name, score) in scores.items():
            if hasattr(score, 'item'):
                with suppress(ValueError):
                    score = score.item()
            if not isinstance(score, numbers.Number):
                raise ValueError(error_msg % (score, type(score), name))
            scores[name] = score
    else:
        if hasattr(scores, 'item'):
            with suppress(ValueError):
                scores = scores.item()
        if not isinstance(scores, numbers.Number):
            raise ValueError(error_msg % (scores, type(scores), scorer))
    return scores

def generate_py_arg_inner(lines, raw_arg, arg_type):

    def handle_scalar(scalar):
        if isinstance(scalar, int):
            return f'PyLong_FromLongLong({scalar})'
        if isinstance(scalar, float):
            return f'PyFloat_FromDouble({self.generate_float_value(scalar)})'
        if isinstance(scalar, bool):
            return f'PyBool_FromLong({(1 if scalar else 0)})'
        if isinstance(scalar, complex):
            real = self.generate_float_value(scalar.real)
            imag = self.generate_float_value(scalar.imag)
            return f'PyComplex_FromDoubles({real}, {imag})'
        if isinstance(scalar, SymTypes):
            scalar_var = cexpr(scalar.node.expr)
            if isinstance(scalar, torch.SymBool):
                return f'PyBool_FromLong({scalar_var})'
            if isinstance(scalar, torch.SymFloat):
                return f'PyFloat_FromDouble({scalar_var})'
            return f'PyLong_FromLongLong({scalar_var})'
        raise NotImplementedError(f'scalar {scalar}, {type(scalar)} cannot be handled by handle_scalar')
    if raw_arg is None:
        lines.append('Py_INCREF(Py_None);\n')
        return 'Py_None'
    elif isinstance(arg_type, torch.TensorType):
        if not hasattr(raw_arg, 'codegen_reference'):
            return handle_scalar(raw_arg)
        base_handle = self.create_tmp_raii_handle_var_if_needed(raw_arg.codegen_reference(), lines)
        return f'PyCapsule_New(reinterpret_cast<void*>({base_handle}.get()), NULL, NULL)'
    elif isinstance(arg_type, torch.OptionalType):
        return generate_py_arg_inner(lines, raw_arg, arg_type.getElementType())
    elif isinstance(arg_type, torch.IntType):
        return f'PyLong_FromLongLong({raw_arg})'
    elif isinstance(arg_type, torch.SymIntType):
        expr = raw_arg.node.expr if isinstance(raw_arg, torch.SymInt) else raw_arg
        return f'PyLong_FromLongLong({cexpr(expr)})'
    elif isinstance(arg_type, torch.FloatType):
        return f'PyFloat_FromDouble({self.generate_float_value(raw_arg)})'
    elif isinstance(arg_type, torch.BoolType):
        return f'PyBool_FromLong({(1 if raw_arg else 0)})'
    elif isinstance(arg_type, torch.StringType):
        return f'PyUnicode_FromString("{raw_arg}")'
    elif <MASK>:
        return handle_scalar(raw_arg)
    elif isinstance(raw_arg, torch.device):
        (device_str, device_index) = self.codegen_device(raw_arg).split(', ')
        return f'THPDevice_New(c10::Device(static_cast<c10::DeviceType>({device_str}), {device_index}))'
    elif isinstance(raw_arg, torch.dtype):
        return f'Py_NewRef(torch::getTHPDtype(static_cast<c10::ScalarType>({self.codegen_dtype(raw_arg)})))'
    elif isinstance(raw_arg, torch.layout):
        return f'Py_NewRef(torch::getTHPLayout(static_cast<c10::Layout>({self.codegen_layout(raw_arg)})))'
    elif isinstance(raw_arg, torch.memory_format):
        return f'Py_NewRef(torch::utils::getTHPMemoryFormat(static_cast<c10::MemoryFormat>({self.codegen_memory_format(raw_arg)})))'
    else:
        raise NotImplementedError(f'arg type {arg_type} is not yet supported by custom_op_wrapper')

def _get_next_label(label):
    dtype = getattr(label, 'dtype', type(label))
    if <MASK>:
        dtype = 'datetime64[ns]'
    dtype = pandas_dtype(dtype)
    if lib.is_np_dtype(dtype, 'mM') or isinstance(dtype, DatetimeTZDtype):
        return label + np.timedelta64(1, 'ns')
    elif is_integer_dtype(dtype):
        return label + 1
    elif is_float_dtype(dtype):
        return np.nextafter(label, np.inf)
    else:
        raise TypeError(f'cannot determine next label for type {type(label)!r}')

def _get_variable_nodes_from_graph_def(graph_def):
    """Get the list of Variable nodes from `graph_def`.

  Args:
    graph_def: An instance of `GraphDef`.  This GraphDef *must*
      have already been optimized by Grappler.  In particular, function
      inlining must have already happened.

  Returns:
    A dict mapping string names of variables to tuples `(node_def, modified)`,
    where `node_def` is the `NodeDef` corresponding to variable, and `modified`
    is a python bool describing whether the variable is modified during runtime.
  """
    variables = [n for n in graph_def.node if n.op == 'VarHandleOp']
    variable_name_map = dict(((n.name, n) for n in variables))
    child_map = collections.defaultdict(lambda : [])
    for n in graph_def.node:
        for inp in n.input:
            if not inp.startswith('^'):
                child_map[inp].append(n)
    variables = {}
    for (v_name, v_node) in variable_name_map.items():
        queue = list(child_map[v_name])
        processed = set([])
        while queue:
            n_current = queue.pop()
            if n_current.name in processed:
                continue
            processed.add(n_current.name)
            if n_current.op in _PASS_THROUGH_VARIABLE_OPS:
                children = child_map.get(n_current.name, [])
                queue.extend(children)
            elif <MASK>:
                variables[v_name] = (v_node, True)
                queue = []
        if v_name not in variables:
            variables[v_name] = (v_node, False)
    return variables

def _stack_gradients(self, gradients):
    """Stack the incoming gradients to per table gradients."""
    table_to_gradient_list = {table_name: [[], [], [], []] for table_name in self._stacked_table_to_tables}
    flattend_gradients = nest.flatten(gradients)
    for (gradient, (path, feature)) in zip(flattend_gradients, self._flat_features):
        sample_count = functools.reduce(operator.mul, feature.output_shape)
        if <MASK>:
            raise ValueError(f'found non-tensor type: {type(gradient)} at path {path}.')
        if gradient is None:
            logging.warning('No gradient passed for feature %s, sending zero gradient. This may not be correct behavior for certain optimizers like Adam.', path)
            gradient = array_ops.zeros((sample_count, feature.table.dim), dtype=dtypes.float32)
        table_name = self._table_to_stacked_table_offset[feature.table.name][0]
        extra_cols = self._table_to_padding_columns[feature.table.name]
        gradient = array_ops.reshape(gradient, [-1, feature.table.dim - extra_cols])
        if extra_cols != 0:
            gradient = array_ops.pad(gradient, [[0, 0], [0, extra_cols]])
            gradient.set_shape([sample_count, feature.table.dim])
        per_sc_sample_count = sample_count // self._num_sc_per_chip
        for i in range(self._num_sc_per_chip):
            table_to_gradient_list[table_name][i].append(array_ops.slice(gradient, [i * per_sc_sample_count, 0], [per_sc_sample_count, feature.table.dim]))
    for table_name in table_to_gradient_list:
        table_to_gradient_list[table_name] = array_ops.concat([array_ops.concat(table_to_gradient_list[table_name][i], axis=0) for i in range(self._num_sc_per_chip)], axis=0)
    return table_to_gradient_list

def __setattr__(self, name, value):
    if name in TRACKABLE_RESOURCE_METHODS:
        if <MASK>:
            self._restored_function = {}
        self._restored_function[name] = value
        if all((method in self._restored_function for method in TRACKABLE_RESOURCE_METHODS)):
            with self._has_resource_functions:
                self._has_resource_functions.notify_all()
        return self._coordinator_instance.__setattr__(name, value)
    else:
        return super(RestoredDistributedTable, self).__setattr__(name, value)

def _raise_error_for_non_direct_inputs(self, features):
    """Checks all tensors in features to see if they are a direct input."""
    for (path, input_tensor) in nest.flatten_with_joined_string_paths(features, expand_composites=True):
        if <MASK>:
            continue
        try:
            is_input = input_tensor.op.get_attr('_tpu_input_identity')
        except ValueError:
            is_input = False
        if not is_input:
            raise ValueError('Received input tensor {} which is the output of op {} (type {}) which does not have the `_tpu_input_identity` attr. Please ensure that the inputs to this layer are taken directly from the arguments of the function called by strategy.run. Two possible causes are: dynamic batch size support or you are using a keras layer and are not passing tensors which match the dtype of the `tf.keras.Input`s.If you are triggering dynamic batch size support, you can disable it by passing tf.distribute.RunOptions(experimental_enable_dynamic_batch_size=False) to the options argument of strategy.run().'.format(path, input_tensor.op.name, input_tensor.op.type))

def _ragged_tensor_apply_loss(loss_fn, y_true, y_pred, y_pred_extra_dim=False):
    """Apply a loss function on a per batch basis.

  Args:
    loss_fn: The loss function
    y_true: truth values (RaggedTensor)
    y_pred: predicted values (RaggedTensor)
    y_pred_extra_dim: whether y_pred has an additional dimension compared to
      y_true

  Returns:
    Loss-function result. A dense tensor if the output has a single dimension
    (per-batch loss value); a ragged tensor otherwise.
  """

    def rt_is_equiv_dense(rt):
        """Returns true if this RaggedTensor has the same row_lengths across

       all ragged dimensions and thus can be converted to a dense tensor
       without loss of information.

    Args:
      rt: RaggedTensor.
    """
        return math_ops.reduce_all([math_ops.equal(math_ops.reduce_variance(math_ops.cast(row_lens, backend.floatx())), constant_op.constant([0.0])) for row_lens in rt.nested_row_lengths()])

    def _convert_to_dense(inputs):
        return tuple((rt.to_tensor() if isinstance(rt, ragged_tensor.RaggedTensor) else rt for rt in inputs))

    def _call_loss(inputs, ragged_output):
        """ Adapt the result to ragged or dense tensor according to the expected

        output type. This is done so that all the return values of the map
        operation have the same type.
    """
        r = loss_fn(*inputs)
        if ragged_output and (not isinstance(r, ragged_tensor.RaggedTensor)):
            r = ragged_tensor.RaggedTensor.from_tensor(r)
        elif not ragged_output and isinstance(r, ragged_tensor.RaggedTensor):
            r = r.to_tensor()
        return r

    def _wrapper(inputs, ragged_output):
        (_, y_pred) = inputs
        if <MASK>:
            return cond.cond(rt_is_equiv_dense(y_pred), lambda : _call_loss(_convert_to_dense(inputs), ragged_output), lambda : _call_loss(inputs, ragged_output))
        return loss_fn(*inputs)
    if not isinstance(y_true, ragged_tensor.RaggedTensor):
        return loss_fn(y_true, y_pred.to_tensor())
    lshape = y_pred.shape.as_list()[1:-1]
    if len(lshape) > 0:
        spec = ragged_tensor.RaggedTensorSpec(shape=lshape, dtype=y_pred.dtype)
    else:
        spec = tensor_spec.TensorSpec(shape=[], dtype=y_pred.dtype)
    nested_splits_list = [rt.nested_row_splits for rt in (y_true, y_pred)]
    if y_pred_extra_dim:
        rdims = [len(slist) for slist in nested_splits_list]
        if rdims[0] == rdims[1] - 1:
            nested_splits_list[1] = nested_splits_list[1][:-1]
    map_fn = functools.partial(_wrapper, ragged_output=len(lshape) > 1)
    assertion_list = ragged_util.assert_splits_match(nested_splits_list)
    with ops.control_dependencies(assertion_list):
        return ragged_map_ops.map_fn(map_fn, elems=(y_true, y_pred), dtype=spec)

def report_error_callback(custom_op: typing.Any, key: str) -> None:
    if <MASK>:
        raise NotImplementedError(f'{custom_op}: There were no Tensor inputs to this operator (e.g. you passed an empty list of Tensors). If your operator is a factory function (that is, it takes no Tensors and constructs a new one), then please use CustomOp.impl_factory to register an implementation for it')
    if key == 'Meta':
        raise NotImplementedError(f"{custom_op}: when running with device='Meta' tensors: there is no abstract impl registered for this CustomOp. Please register one via CustomOp.impl_abstract to get this CustomOp to work with Meta tensors")
    if key in ('CPU', 'CUDA'):
        device = key.lower()
        raise NotImplementedError(f"{custom_op}: when running with device='{device}' tensors: there is no {device} impl registered for this CustomOp. Please register one via CustomOp.impl(device_type='{device}')")
    raise NotImplementedError(f"{custom_op}: No implementation for dispatch key {key}. It is likely that we have not added this functionality yet, please either open an issue or if you're feeling adventurous, use the low-level torch.library API")

def fields_for_model(model, fields=None, exclude=None, widgets=None, formfield_callback=None, localized_fields=None, labels=None, help_texts=None, error_messages=None, field_classes=None, *, apply_limit_choices_to=True, form_declared_fields=None):
    """
    Return a dictionary containing form fields for the given model.

    ``fields`` is an optional list of field names. If provided, return only the
    named fields.

    ``exclude`` is an optional list of field names. If provided, exclude the
    named fields from the returned fields, even if they are listed in the
    ``fields`` argument.

    ``widgets`` is a dictionary of model field names mapped to a widget.

    ``formfield_callback`` is a callable that takes a model field and returns
    a form field.

    ``localized_fields`` is a list of names of fields which should be
    localized.

    ``labels`` is a dictionary of model field names mapped to a label.

    ``help_texts`` is a dictionary of model field names mapped to a help text.

    ``error_messages`` is a dictionary of model field names mapped to a
    dictionary of error messages.

    ``field_classes`` is a dictionary of model field names mapped to a form
    field class.

    ``apply_limit_choices_to`` is a boolean indicating if limit_choices_to
    should be applied to a field's queryset.

    ``form_declared_fields`` is a dictionary of form fields created directly on
    a form.
    """
    form_declared_fields = form_declared_fields or {}
    field_dict = {}
    ignored = []
    opts = model._meta
    from django.db.models import Field as ModelField
    sortable_private_fields = [f for f in opts.private_fields if isinstance(f, ModelField)]
    for f in sorted(chain(opts.concrete_fields, sortable_private_fields, opts.many_to_many)):
        if not getattr(f, 'editable', False):
            if fields is not None and f.name in fields and (exclude is None or f.name not in exclude):
                raise FieldError("'%s' cannot be specified for %s model form as it is a non-editable field" % (f.name, model.__name__))
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.name in form_declared_fields:
            field_dict[f.name] = form_declared_fields[f.name]
            continue
        kwargs = {}
        if widgets and f.name in widgets:
            kwargs['widget'] = widgets[f.name]
        if <MASK>:
            kwargs['localize'] = True
        if labels and f.name in labels:
            kwargs['label'] = labels[f.name]
        if help_texts and f.name in help_texts:
            kwargs['help_text'] = help_texts[f.name]
        if error_messages and f.name in error_messages:
            kwargs['error_messages'] = error_messages[f.name]
        if field_classes and f.name in field_classes:
            kwargs['form_class'] = field_classes[f.name]
        if formfield_callback is None:
            formfield = f.formfield(**kwargs)
        elif not callable(formfield_callback):
            raise TypeError('formfield_callback must be a function or callable')
        else:
            formfield = formfield_callback(f, **kwargs)
        if formfield:
            if apply_limit_choices_to:
                apply_limit_choices_to_to_formfield(formfield)
            field_dict[f.name] = formfield
        else:
            ignored.append(f.name)
    if fields:
        field_dict = {f: field_dict.get(f) for f in fields if (not exclude or f not in exclude) and f not in ignored}
    return field_dict

def _tf_ag_dataset_for_stmt(ds, extra_test, body, get_state, set_state, symbol_names, opts):
    """Overload of _dataset_for_stmt with early stopping. See for_stmt."""
    init_vars = get_state()
    control_flow.verify_loop_init_vars(init_vars, symbol_names)
    if not init_vars:
        init_vars = (constant_op.constant(0),)
        symbol_names = ('<internal dummy>',)

        def dummy_set_state(unused_dummy):
            pass

        def dummy_get_state():
            return (constant_op.constant(0),)
        (get_state, set_state) = (dummy_get_state, dummy_set_state)

    def scan_body(scan_state, scan_inputs):
        """Main body of the Dataset.scan."""
        (loop_vars, iterate) = (scan_state, scan_inputs)
        set_state(loop_vars)

        def main_path():
            body(iterate)
            new_loop_vars = get_state()
            control_flow.verify_tf_loop_vars(init_vars, loop_vars, new_loop_vars, symbol_names, opts, check_shapes=False)
            return new_loop_vars
        if <MASK>:
            extra_cond = extra_test()
            new_loop_vars = cond.cond(extra_cond, main_path, lambda : loop_vars)
        else:
            extra_cond = (constant_op.constant(True),)
            new_loop_vars = main_path()
        scan_outputs = (new_loop_vars, extra_cond)
        new_scan_state = new_loop_vars
        return (new_scan_state, scan_outputs)

    def take_while_predicate(unused_loop_vars, extra_cond):
        return extra_cond

    def reduce_body(unused_reduce_state, scan_outputs):
        (output_loop_vars, unused_extra_cond) = scan_outputs
        new_reduce_state = output_loop_vars
        return new_reduce_state
    ds = _general_purpose_scan(ds, init_vars, scan_body)
    if extra_test is not None:
        ds = ds.apply(take_while_ops.take_while(take_while_predicate))
    final_loop_vars = ds.reduce(init_vars, reduce_body)
    set_state(final_loop_vars)

def select_one_layer_lstm_function(input, hx, params):
    """Check whether we could use decompose lstm with mkldnn_rnn_layer.
    All the below conditions need to be met:
        * ``torch._C._get_mkldnn_enabled()`` returns ``True``.
        * All the input args are on CPU.
        * The dtypes of args are either torch.float or torch.bfloat16.
        * Inference.
        * ``has_projections`` returns ``False``.

    Args:
        * input: the input sequence to LSTM
        * hx: a tuple of the input hidden state and cell state ``(h_0, c_0)`` to LSTM
        * params: the weight and bias tensors of LSTM
    """

    def use_mkldnn(input, hx, params):
        if not torch._C._get_mkldnn_enabled():
            return False
        tensors = [input] + list(hx) + list(chain.from_iterable(params))
        devices = {t.device for t in tensors}
        if len(devices) != 1:
            return False
        device = devices.pop()
        if device != torch.device('cpu'):
            return False
        dtypes = {t.dtype for t in tensors}
        for dtype in dtypes:
            if dtype not in [torch.float, torch.bfloat16]:
                return False
        if input.requires_grad:
            return False
        has_projections = hx[0].size(2) != hx[1].size(2)
        if has_projections:
            return False
        return True
    if <MASK>:
        return mkldnn_one_layer_lstm
    else:
        return one_layer_lstm

def expand_to_include(self, *args):
    """
        Modify the envelope to expand to include the boundaries of
        the passed-in 2-tuple (a point), 4-tuple (an extent) or
        envelope.
        """
    if len(args) == 1:
        if isinstance(args[0], Envelope):
            return self.expand_to_include(args[0].tuple)
        elif hasattr(args[0], 'x') and hasattr(args[0], 'y'):
            return self.expand_to_include(args[0].x, args[0].y, args[0].x, args[0].y)
        elif isinstance(args[0], (tuple, list)):
            if len(args[0]) == 2:
                return self.expand_to_include((args[0][0], args[0][1], args[0][0], args[0][1]))
            elif <MASK>:
                (minx, miny, maxx, maxy) = args[0]
                if minx < self._envelope.MinX:
                    self._envelope.MinX = minx
                if miny < self._envelope.MinY:
                    self._envelope.MinY = miny
                if maxx > self._envelope.MaxX:
                    self._envelope.MaxX = maxx
                if maxy > self._envelope.MaxY:
                    self._envelope.MaxY = maxy
            else:
                raise GDALException('Incorrect number of tuple elements (%d).' % len(args[0]))
        else:
            raise TypeError('Incorrect type of argument: %s' % type(args[0]))
    elif len(args) == 2:
        return self.expand_to_include((args[0], args[1], args[0], args[1]))
    elif len(args) == 4:
        return self.expand_to_include(args)
    else:
        raise GDALException('Incorrect number (%d) of arguments.' % len(args[0]))

def check_compatibility(self, other: 'SystemInfo', device_type: str='cpu') -> None:
    """
        Check if this SystemInfo is compatible with another SystemInfo.
        Raises RuntimeError if incompatible.
        """
    if self.python_version != other.python_version:
        raise RuntimeError(f'Compile package was created with a different Python version: {self.python_version}')
    if self.torch_version != other.torch_version:
        raise RuntimeError(f'Compile package was created with a different PyTorch version: {self.torch_version}')
    if device_type in self.CHECK_GPUS:
        if not getattr(torch, device_type).is_available():
            raise RuntimeError(f'{device_type} is not available')
        if self.toolkit_version != other.toolkit_version:
            raise RuntimeError(f'Compile package was created with a different toolkit version: {self.toolkit_version}')
        if other.triton_version != (0, 0) and self.triton_version != other.triton_version:
            raise RuntimeError(f'Compile package was created with a different Triton version: {self.triton_version}')
        if <MASK>:
            raise RuntimeError(f'Compile package was created with different GPU: cached={self.gpu_name}, current={other.gpu_name}')

def _check_pattern_startswith_slash(self):
    """
        Check that the pattern does not begin with a forward slash.
        """
    if not settings.APPEND_SLASH:
        return []
    if <MASK>:
        warning = Warning("Your URL pattern {} has a route beginning with a '/'. Remove this slash as it is unnecessary. If this pattern is targeted in an include(), ensure the include() pattern has a trailing '/'.".format(self.describe()), id='urls.W002')
        return [warning]
    else:
        return []

@doc(NDFrame.shift, klass=_shared_doc_kwargs['klass'])
def shift(self, periods: int | Sequence[int]=1, freq: Frequency | None=None, axis: Axis=0, fill_value: Hashable=lib.no_default, suffix: str | None=None) -> DataFrame:
    if freq is not None and fill_value is not lib.no_default:
        raise ValueError("Passing a 'freq' together with a 'fill_value' is not allowed.")
    if self.empty and freq is None:
        return self.copy()
    axis = self._get_axis_number(axis)
    if is_list_like(periods):
        periods = cast(Sequence, periods)
        if axis == 1:
            raise ValueError('If `periods` contains multiple shifts, `axis` cannot be 1.')
        if len(periods) == 0:
            raise ValueError('If `periods` is an iterable, it cannot be empty.')
        from pandas.core.reshape.concat import concat
        shifted_dataframes = []
        for period in periods:
            if not is_integer(period):
                raise TypeError(f'Periods must be integer, but {period} is {type(period)}.')
            period = cast(int, period)
            shifted_dataframes.append(super().shift(periods=period, freq=freq, axis=axis, fill_value=fill_value).add_suffix(f'{suffix}_{period}' if suffix else f'_{period}'))
        return concat(shifted_dataframes, axis=1)
    elif suffix:
        raise ValueError('Cannot specify `suffix` if `periods` is an int.')
    periods = cast(int, periods)
    ncols = len(self.columns)
    if axis == 1 and periods != 0 and (ncols > 0) and (freq is None):
        if fill_value is lib.no_default:
            label = self.columns[0]
            if <MASK>:
                result = self.iloc[:, :-periods]
                for col in range(min(ncols, abs(periods))):
                    filler = self.iloc[:, 0].shift(len(self))
                    result.insert(0, label, filler, allow_duplicates=True)
            else:
                result = self.iloc[:, -periods:]
                for col in range(min(ncols, abs(periods))):
                    filler = self.iloc[:, -1].shift(len(self))
                    result.insert(len(result.columns), label, filler, allow_duplicates=True)
            result.columns = self.columns.copy()
            return result
        elif len(self._mgr.blocks) > 1 or not can_hold_element(self._mgr.blocks[0].values, fill_value):
            nper = abs(periods)
            nper = min(nper, ncols)
            if periods > 0:
                indexer = np.array([-1] * nper + list(range(ncols - periods)), dtype=np.intp)
            else:
                indexer = np.array(list(range(nper, ncols)) + [-1] * nper, dtype=np.intp)
            mgr = self._mgr.reindex_indexer(self.columns, indexer, axis=0, fill_value=fill_value, allow_dups=True)
            res_df = self._constructor_from_mgr(mgr, axes=mgr.axes)
            return res_df.__finalize__(self, method='shift')
        else:
            return self.T.shift(periods=periods, fill_value=fill_value).T
    return super().shift(periods=periods, freq=freq, axis=axis, fill_value=fill_value)

def call(self, gm: torch.fx.GraphModule) -> Optional[PassResult]:

    def get_arg_spec(arg) -> Union[TensorArgument, ConstantArgument]:
        if isinstance(arg, torch.fx.Node):
            if <MASK>:
                return TensorArgument(name=arg.name)
            else:
                raise AssertionError('Symint input is not implemented yet for submodule call signature.')
        else:
            return ConstantArgument(name='', value=arg)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        nn_module_stack = None
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_outputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_inputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None
        nn_module_stack = None
        for node in reversed(module.graph.nodes):
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_inputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_outputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None

    def copy_sig(sig) -> ModuleCallSignature:
        from torch.export.exported_program import ModuleCallSignature
        return ModuleCallSignature(inputs=[], outputs=[], in_spec=sig.in_spec, out_spec=sig.out_spec, forward_arg_names=None)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                path = node.kwargs['path']
                (fqn, _) = next(reversed(node.meta['nn_module_stack'].values()))
                module_key = next(reversed(node.meta['nn_module_stack']))
                if '@' in module_key:
                    suffix = module_key.split('@')[-1]
                    path = f'{path}@{suffix}'
                    call_fqn = f'{fqn}@{suffix}'
                    if call_fqn not in self.specs:
                        self.specs[call_fqn] = copy_sig(self.specs[fqn])
                    fqn = call_fqn
                kind = node.kwargs['kind']
                for (i, arg) in enumerate(node.args):
                    if fqn == path:
                        if kind == 'module_call_inputs':
                            self.specs[path].inputs.append(get_arg_spec(arg))
                        elif kind == 'module_call_outputs':
                            self.specs[path].outputs.append(get_arg_spec(arg))
                        else:
                            raise AssertionError(f'Unknown tracepoint kind: {kind}')
                    if isinstance(arg, torch.fx.Node):
                        for user in node.users:
                            assert user.op == 'call_function'
                            assert user.target == operator.getitem
                            assert isinstance(user.args[1], int)
                            if user.args[1] == i:
                                user.replace_all_uses_with(arg)
                                self.sig.replace_all_uses(user.name, arg.name)
                                break
                users = list(node.users)
                for user in users:
                    assert len(user.users) == 0
                    gm.graph.erase_node(user)
                gm.graph.erase_node(node)
        return PassResult(gm, True)
    return None

def call_function(self, name, tensor_inputs, num_outputs):
    """Calls the function associated with the given name."""
    attrs = tuple(itertools.chain(*self.function_call_options.as_attrs().items()))
    cancellation_context = cancellation.context()
    if <MASK>:
        outputs = execute.execute(name.decode('utf-8'), num_outputs=num_outputs, inputs=tensor_inputs, attrs=attrs, ctx=self)
    else:
        outputs = execute.execute_with_cancellation(name.decode('utf-8'), num_outputs=num_outputs, inputs=tensor_inputs, attrs=attrs, ctx=self, cancellation_manager=cancellation_context)
    outputs = outputs or None
    return outputs

@final
def _get_merge_keys(self) -> tuple[list[ArrayLike], list[ArrayLike], list[Hashable], list[Hashable], list[Hashable]]:
    """
        Returns
        -------
        left_keys, right_keys, join_names, left_drop, right_drop
        """
    left_keys: list[ArrayLike] = []
    right_keys: list[ArrayLike] = []
    join_names: list[Hashable] = []
    right_drop: list[Hashable] = []
    left_drop: list[Hashable] = []
    (left, right) = (self.left, self.right)
    is_lkey = lambda x: isinstance(x, _known) and len(x) == len(left)
    is_rkey = lambda x: isinstance(x, _known) and len(x) == len(right)
    if _any(self.left_on) and _any(self.right_on):
        for (lk, rk) in zip(self.left_on, self.right_on):
            lk = extract_array(lk, extract_numpy=True)
            rk = extract_array(rk, extract_numpy=True)
            if is_lkey(lk):
                lk = cast(ArrayLike, lk)
                left_keys.append(lk)
                if is_rkey(rk):
                    rk = cast(ArrayLike, rk)
                    right_keys.append(rk)
                    join_names.append(None)
                else:
                    rk = cast(Hashable, rk)
                    if rk is not None:
                        right_keys.append(right._get_label_or_level_values(rk))
                        join_names.append(rk)
                    else:
                        right_keys.append(right.index._values)
                        join_names.append(right.index.name)
            else:
                if not is_rkey(rk):
                    rk = cast(Hashable, rk)
                    if rk is not None:
                        right_keys.append(right._get_label_or_level_values(rk))
                    else:
                        right_keys.append(right.index._values)
                    if lk is not None and lk == rk:
                        right_drop.append(rk)
                else:
                    rk = cast(ArrayLike, rk)
                    right_keys.append(rk)
                if lk is not None:
                    lk = cast(Hashable, lk)
                    left_keys.append(left._get_label_or_level_values(lk))
                    join_names.append(lk)
                else:
                    left_keys.append(left.index._values)
                    join_names.append(left.index.name)
    elif _any(self.left_on):
        for k in self.left_on:
            if is_lkey(k):
                k = extract_array(k, extract_numpy=True)
                k = cast(ArrayLike, k)
                left_keys.append(k)
                join_names.append(None)
            else:
                k = cast(Hashable, k)
                left_keys.append(left._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.right.index, MultiIndex):
            right_keys = [lev._values.take(lev_codes) for (lev, lev_codes) in zip(self.right.index.levels, self.right.index.codes)]
        else:
            right_keys = [self.right.index._values]
    elif _any(self.right_on):
        for k in self.right_on:
            k = extract_array(k, extract_numpy=True)
            if <MASK>:
                k = cast(ArrayLike, k)
                right_keys.append(k)
                join_names.append(None)
            else:
                k = cast(Hashable, k)
                right_keys.append(right._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.left.index, MultiIndex):
            left_keys = [lev._values.take(lev_codes) for (lev, lev_codes) in zip(self.left.index.levels, self.left.index.codes)]
        else:
            left_keys = [self.left.index._values]
    return (left_keys, right_keys, join_names, left_drop, right_drop)

def __init__(self, x, y=None, sample_weights=None, sample_weight_modes=None, batch_size=None, shuffle=False, **kwargs):
    super(ListsOfScalarsDataAdapter, self).__init__(x, y, **kwargs)
