        y = numpy_compat.np_asarray(y)
    if sample_weights is not None:
        sample_weights = numpy_compat.np_asarray(sample_weights)
    sample_weight_modes = broadcast_sample_weight_modes(sample_weights, sample_weight_modes)
    self._internal_adapter = TensorLikeDataAdapter(x, y=y, sample_weights=sample_weights, sample_weight_modes=sample_weight_modes, batch_size=batch_size, shuffle=shuffle, **kwargs)

def has_tensors(ls):
    """Returns true if `ls` contains tensors."""
    if <MASK>:
        return any((tensor_util.is_tf_type(v) and (not isinstance(v, ragged_tensor.RaggedTensor)) for v in ls))
    if isinstance(ls, dict):
        return any((tensor_util.is_tf_type(v) and (not isinstance(v, ragged_tensor.RaggedTensor)) for (_, v) in ls.items()))
    return tensor_util.is_tf_type(ls) and (not isinstance(ls, ragged_tensor.RaggedTensor))

def _get_optimization_cflags(cpp_compiler: str, min_optimize: bool=False) -> tuple[list[str], list[str]]:
    cflags: list[str] = []
    ldflags: list[str] = []
    b_debug_build = config.aot_inductor.debug_compile or os.environ.get('TORCHINDUCTOR_DEBUG_SYMBOL', '0') == '1'
    wrapper_opt_level = config.aot_inductor.compile_wrapper_opt_level
    if b_debug_build:
        (cflags, ldflags) = _get_inductor_debug_symbol_cflags()
        if <MASK>:
            cflags += ['Od', 'Ob0', 'Oy-']
        else:
            cflags.append('O0')
    elif _IS_WINDOWS:
        cflags = ['O1' if min_optimize else 'O2']
    else:
        cflags = [wrapper_opt_level if min_optimize else 'O3', 'DNDEBUG']
    cflags += _get_ffast_math_flags()
    if _IS_WINDOWS:
        pass
    else:
        if sys.platform != 'darwin':
            if _is_gcc(cpp_compiler):
                cflags.append('fno-tree-loop-vectorize')
            if not config.is_fbcode():
                if platform.machine() == 'ppc64le':
                    cflags.append('mcpu=native')
                else:
                    cflags.append('march=native')
        if config.aot_inductor.enable_lto and _is_clang(cpp_compiler):
            cflags.append('flto=thin')
    return (cflags, ldflags)

def _load_from_state_dict(self, state_dict, prefix, local_metadata, strict, missing_keys, unexpected_keys, error_msgs):
    local_state = ['scale', 'zero_point']
    for name in local_state:
        key = prefix + name
        if <MASK>:
            val = state_dict[key]
            if name == 'scale':
                self.scale.resize_(val.shape)
            else:
                assert name == 'zero_point'
                self.zero_point.resize_(val.shape)
            if torch.jit.is_scripting():
                if name == 'scale':
                    self.scale.copy_(val)
                else:
                    assert name == 'zero_point'
                    self.zero_point.copy_(val)
        elif strict:
            missing_keys.append(key)
    super()._load_from_state_dict(state_dict, prefix, local_metadata, strict, missing_keys, unexpected_keys, error_msgs)

def _state_dict_fn(obj: Union[nn.Module, torch.optim.Optimizer], api: str) -> Callable:
    call = getattr(obj, api)
