def extract_info_from_keyword(source: str, kw: ast.keyword) -> Any:
    """
    Extracts and returns the value of a keyword argument from an AST node.

    This function handles different types of AST nodes:
    - If the node is a constant, it returns the constant value.
    - If the node is an f-string, it reconstructs the string by
      evaluating formatted values and concatenating them with string literals.
    - For other types, it cleans the source segment to remove formatting artifacts.

    """
    param_source = get_source_segment(source, kw.value)
    if isinstance(kw.value, ast.Constant):
        return kw.value.value
    elif isinstance(kw.value, ast.JoinedStr):
        evaluated_context = []
        for value in kw.value.values:
            if <MASK>:
                evaluated_context.append(f'{{{ast.unparse(value.value)}}}')
            elif isinstance(value, ast.Constant):
                evaluated_context.append(value.value)
        return ''.join(evaluated_context)
    else:
        return clean_string(param_source)

def save_global(self, obj, name=None):
    write = self.write
    memo = self.memo
    try:
        (module_name, name) = self.importer.get_name(obj, name)
    except (ObjNotFoundError, ObjMismatchError) as err:
        raise PicklingError(f"Can't pickle {obj}: {str(err)}") from err
    module = self.importer.import_module(module_name)
    (_, parent) = _getattribute(module, name)
    if self.proto >= 2:
        code = _extension_registry.get((module_name, name))
        if <MASK>:
            assert code > 0
            if code <= 255:
                write(EXT1 + pack('<B', code))
            elif code <= 65535:
                write(EXT2 + pack('<H', code))
            else:
                write(EXT4 + pack('<i', code))
            return
    lastname = name.rpartition('.')[2]
    if parent is module:
        name = lastname
    if self.proto >= 4:
        self.save(module_name)
        self.save(name)
        write(STACK_GLOBAL)
    elif parent is not module:
        self.save_reduce(getattr, (parent, lastname))
    elif self.proto >= 3:
        write(GLOBAL + bytes(module_name, 'utf-8') + b'\n' + bytes(name, 'utf-8') + b'\n')
    else:
        if self.fix_imports:
            r_name_mapping = _compat_pickle.REVERSE_NAME_MAPPING
            r_import_mapping = _compat_pickle.REVERSE_IMPORT_MAPPING
            if (module_name, name) in r_name_mapping:
                (module_name, name) = r_name_mapping[module_name, name]
            elif module_name in r_import_mapping:
                module_name = r_import_mapping[module_name]
        try:
            write(GLOBAL + bytes(module_name, 'ascii') + b'\n' + bytes(name, 'ascii') + b'\n')
        except UnicodeEncodeError as exc:
            raise PicklingError(f"can't pickle global identifier '{module}.{name}' using pickle protocol {self.proto:d}") from exc
    self.memoize(obj)

def _save(self, name, content):
    full_path = self.path(name)
    directory = os.path.dirname(full_path)
    try:
        if <MASK>:
            old_umask = os.umask(511 & ~self.directory_permissions_mode)
            try:
                os.makedirs(directory, self.directory_permissions_mode, exist_ok=True)
            finally:
                os.umask(old_umask)
        else:
            os.makedirs(directory, exist_ok=True)
    except FileExistsError:
        raise FileExistsError('%s exists and is not a directory.' % directory)
    while True:
        try:
            if hasattr(content, 'temporary_file_path'):
                file_move_safe(content.temporary_file_path(), full_path, allow_overwrite=self._allow_overwrite)
            else:
                open_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_BINARY', 0)
                if self._allow_overwrite:
                    open_flags = open_flags & ~os.O_EXCL | os.O_TRUNC
                fd = os.open(full_path, open_flags, 438)
                _file = None
                try:
                    locks.lock(fd, locks.LOCK_EX)
                    for chunk in content.chunks():
                        if _file is None:
                            mode = 'wb' if isinstance(chunk, bytes) else 'wt'
                            _file = os.fdopen(fd, mode)
                        _file.write(chunk)
                finally:
                    locks.unlock(fd)
                    if _file is not None:
                        _file.close()
                    else:
                        os.close(fd)
        except FileExistsError:
            name = self.get_available_name(name)
            full_path = self.path(name)
        else:
            break
    if self.file_permissions_mode is not None:
        os.chmod(full_path, self.file_permissions_mode)
    name = os.path.relpath(full_path, self.location)
    self._ensure_location_group_id(full_path)
    return str(name).replace('\\', '/')

