def codegen_config(self) -> str:
    """Convert config to Python statements that replicate current config.
        This does NOT include config settings that are at default values.
        """
    imports = set()

    def get_module_name(func: Callable, add_dot: bool) -> str:
        module_name = func.__module__
        if module_name == 'builtins':
            module_name = ''
        if add_dot and module_name != '':
            module_name += '.'
        return module_name

    def add_import(func: Callable) -> None:
        module_name = get_module_name(func, False)
        if module_name:
            imports.add(module_name)

    def list_of_callables_to_string(v: Union[list, set]) -> list[str]:
        return [f'{get_module_name(item, True)}{item.__name__}' for item in v]

    def importable_callable(v: Any) -> bool:
        return callable(v) and hasattr(v, '__module__') and hasattr(v, '__name__')

    def get_config_line(mod, k, v) -> str:
        """
            Return a string version of the config line.
            Handle v when v is a callable, or a list/dict of callables. Add import statements for callables if necessary.
            We assume that the value of a single config won't be a mix of callables and non-callables.

            Example output:
                import logging
                import _warnings
                torch._dynamo.config.reorderable_logging_functions = { _warnings.warn, logging.warn, print }
            """
        if <MASK>:
            add_import(v)
            return f'{mod}.{k} = {get_module_name(v, True)}{v.__name__}'
        elif isinstance(v, (list, set)) and all((importable_callable(item) for item in v)):
            for item in v:
                add_import(item)
            v_list = list_of_callables_to_string(v)
            if isinstance(v, list):
                return f'{mod}.{k} = {v_list}'
            else:
                return f"{mod}.{k} = {{ {', '.join(v_list)} }}"
        else:
            return f'{mod}.{k} = {v!r}'
    lines = []
    mod = self.__name__
    for (k, v) in self._get_dict(ignored_keys=getattr(self, '_save_config_ignore', []), skip_default=True).items():
        lines.append(get_config_line(mod, k, v))
    for import_name in imports:
        lines.insert(0, f'import {import_name}')
    return '\n'.join(lines)

@tf_export.tf_export('experimental.numpy.var', v1=[])
@np_utils.np_doc('var')
def var(a, axis=None, dtype=None, out=None, ddof=0, keepdims=None):
    if dtype:
        working_dtype = np_utils.result_type(a, dtype)
    else:
        working_dtype = None
    if out is not None:
        raise ValueError('Setting out is not supported.')
    if ddof != 0:

        def reduce_fn(input_tensor, axis, keepdims):
            means = math_ops.reduce_mean(input_tensor, axis=axis, keepdims=True)
            centered = input_tensor - means
            if <MASK>:
                centered = math_ops.cast(math_ops.real(centered * math_ops.conj(centered)), input_tensor.dtype)
            else:
                centered = math_ops.square(centered)
            squared_deviations = math_ops.reduce_sum(centered, axis=axis, keepdims=keepdims)
            if axis is None:
                n = array_ops.size(input_tensor)
            else:
                if axis < 0:
                    axis += array_ops.rank(input_tensor)
                n = math_ops.reduce_prod(array_ops.gather(array_ops.shape(input_tensor), axis))
            n = math_ops.cast(n - ddof, input_tensor.dtype)
            return math_ops.cast(math_ops.divide(squared_deviations, n), dtype)
    else:
        reduce_fn = math_ops.reduce_variance
    result = _reduce(reduce_fn, a, axis=axis, dtype=working_dtype, keepdims=keepdims, promote_int=_TO_FLOAT)
    if dtype:
        result = math_ops.cast(result, dtype)
    return result

def export_for_aoti_minifier(gm: torch.nn.Module, tuple_inputs: tuple[Any], strict: bool=False, skip_export_error: bool=True) -> Optional[torch.nn.Module]:
    from torch._dynamo.exc import UserError, UserErrorType
    try:
        ep = torch.export.export(gm, tuple_inputs, strict=strict)
        gm = ep.module(check_guards=False)
        return gm
    except Exception as e:
        if skip_export_error:
            return None
        if isinstance(e, UserError) and e.error_type == UserErrorType.INVALID_OUTPUT:
            return None
        if <MASK>:
            pattern = 'Found .* in output, which is not a known type\\.'
            if re.search(pattern, str(e)) is not None:
                return None
        raise AOTIMinifierError(e) from e
    return None

def _unique_np(values, return_inverse=False, return_counts=False):
    """Helper function to find unique values for numpy arrays that correctly
    accounts for nans. See `_unique` documentation for details."""
    (xp, _) = get_namespace(values)
    (inverse, counts) = (None, None)
    if return_inverse and return_counts:
        (uniques, _, inverse, counts) = xp.unique_all(values)
    elif return_inverse:
        (uniques, inverse) = xp.unique_inverse(values)
    elif <MASK>:
        (uniques, counts) = xp.unique_counts(values)
    else:
        uniques = xp.unique_values(values)
    if uniques.size and is_scalar_nan(uniques[-1]):
        nan_idx = xp.searchsorted(uniques, xp.nan)
        uniques = uniques[:nan_idx + 1]
        if return_inverse:
            inverse[inverse > nan_idx] = nan_idx
        if return_counts:
            counts[nan_idx] = xp.sum(counts[nan_idx:])
            counts = counts[:nan_idx + 1]
    ret = (uniques,)
    if return_inverse:
        ret += (inverse,)
    if return_counts:
        ret += (counts,)
    return ret[0] if len(ret) == 1 else ret

def _write_ninja_file_to_build_library(path, name, sources, extra_cflags, extra_cuda_cflags, extra_sycl_cflags, extra_ldflags, extra_include_paths, with_cuda, with_sycl, is_standalone) -> None:
    extra_cflags = [flag.strip() for flag in extra_cflags]
    extra_cuda_cflags = [flag.strip() for flag in extra_cuda_cflags]
    extra_sycl_cflags = [flag.strip() for flag in extra_sycl_cflags]
    extra_ldflags = [flag.strip() for flag in extra_ldflags]
    extra_include_paths = [flag.strip() for flag in extra_include_paths]
    user_includes = [os.path.abspath(file) for file in extra_include_paths]
    if with_cuda:
        system_includes = include_paths('cuda')
    else:
        system_includes = include_paths('cpu')
    python_include_path = sysconfig.get_path('include', scheme='nt' if IS_WINDOWS else 'posix_prefix')
    if python_include_path is not None:
        system_includes.append(python_include_path)
    common_cflags = []
    if not is_standalone:
        common_cflags.append(f'-DTORCH_EXTENSION_NAME={name}')
        common_cflags.append('-DTORCH_API_INCLUDE_EXTENSION_H')
    if IS_WINDOWS:
        common_cflags += [f'-I{include}' for include in user_includes + system_includes]
    else:
        common_cflags += [f'-I{shlex.quote(include)}' for include in user_includes]
        common_cflags += [f'-isystem {shlex.quote(include)}' for include in system_includes]
    if IS_WINDOWS:
        COMMON_HIP_FLAGS.extend(['-fms-runtime-lib=dll'])
        cflags = common_cflags + ['/std:c++17'] + extra_cflags
        cflags += COMMON_MSVC_FLAGS + (COMMON_HIP_FLAGS if IS_HIP_EXTENSION else [])
        cflags = _nt_quote_args(cflags)
    else:
        cflags = common_cflags + ['-fPIC', '-std=c++17'] + extra_cflags
    if with_cuda and IS_HIP_EXTENSION:
        cuda_flags = ['-DWITH_HIP'] + common_cflags + extra_cflags + COMMON_HIP_FLAGS + COMMON_HIPCC_FLAGS
        cuda_flags = cuda_flags + ['-std=c++17']
        cuda_flags += _get_rocm_arch_flags(cuda_flags)
        cuda_flags += extra_cuda_cflags
        if IS_WINDOWS:
            cuda_flags = _nt_quote_args(cuda_flags)
    elif with_cuda:
        cuda_flags = common_cflags + COMMON_NVCC_FLAGS + _get_cuda_arch_flags(extra_cuda_cflags)
        if IS_WINDOWS:
            for flag in COMMON_MSVC_FLAGS:
                cuda_flags = ['-Xcompiler', flag] + cuda_flags
            for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                cuda_flags = ['-Xcudafe', '--diag_suppress=' + ignore_warning] + cuda_flags
            cuda_flags = cuda_flags + ['-std=c++17']
            cuda_flags = _nt_quote_args(cuda_flags)
            cuda_flags += _nt_quote_args(extra_cuda_cflags)
        else:
            cuda_flags += ['--compiler-options', "'-fPIC'"]
            cuda_flags += extra_cuda_cflags
            if not any((flag.startswith('-std=') for flag in cuda_flags)):
                cuda_flags.append('-std=c++17')
            cc_env = os.getenv('CC')
            if cc_env is not None:
                cuda_flags = ['-ccbin', cc_env] + cuda_flags
    else:
        cuda_flags = None
    if with_sycl:
        sycl_cflags = cflags + _COMMON_SYCL_FLAGS
        sycl_cflags += extra_sycl_cflags
        _append_sycl_targets_if_missing(sycl_cflags)
        _append_sycl_std_if_no_std_present(sycl_cflags)
        host_cflags = cflags
        icpx_version = _get_icpx_version()
        if int(icpx_version) < 20250200:
            host_cflags = [item.replace('\\"', '\\\\"') for item in host_cflags]
        host_cflags = ' '.join(host_cflags)
        sycl_cflags += _wrap_sycl_host_flags(host_cflags)
        sycl_dlink_post_cflags = _SYCL_DLINK_FLAGS.copy()
        sycl_dlink_post_cflags += _get_sycl_device_flags(sycl_cflags)
    else:
        sycl_cflags = None
        sycl_dlink_post_cflags = None

    def object_file_path(source_file: str) -> str:
        file_name = os.path.splitext(os.path.basename(source_file))[0]
        if <MASK>:
            target = f'{file_name}.cuda.o'
        elif _is_sycl_file(source_file) and with_sycl:
            target = f'{file_name}.sycl.o'
        else:
            target = f'{file_name}.o'
        return target
    objects = [object_file_path(src) for src in sources]
    ldflags = ([] if is_standalone else [SHARED_FLAG]) + extra_ldflags
    if IS_MACOS:
        ldflags.append('-undefined dynamic_lookup')
    elif IS_WINDOWS:
        ldflags = _nt_quote_args(ldflags)
    ext = EXEC_EXT if is_standalone else LIB_EXT
    library_target = f'{name}{ext}'
    _write_ninja_file(path=path, cflags=cflags, post_cflags=None, cuda_cflags=cuda_flags, cuda_post_cflags=None, cuda_dlink_post_cflags=None, sycl_cflags=sycl_cflags, sycl_post_cflags=[], sycl_dlink_post_cflags=sycl_dlink_post_cflags, sources=sources, objects=objects, ldflags=ldflags, library_target=library_target, with_cuda=with_cuda, with_sycl=with_sycl)

