    if name in ('__getitem__', 'get') and self.name == '__dict__' and (not kwargs) and args[0].is_python_constant() and isinstance(self.obj, (variables.UserDefinedObjectVariable, variables.NNModuleVariable, variables.UserDefinedClassVariable)):
        obj = self.obj
        key = args[0].as_python_constant()
        if obj.has_key_in_generic_dict(tx, key):
            return obj.var_getattr(tx, key)
