            else:
                return variables.ConstantVariable(None)
    elif name == '__contains__' and self.name == '__dict__' and (len(args) == 1) and args[0].is_python_constant() and (not kwargs) and isinstance(self.obj, (variables.UserDefinedObjectVariable, variables.NNModuleVariable, variables.UserDefinedClassVariable)):
        obj = self.obj
        key = args[0].as_python_constant()
        if obj.has_key_in_generic_dict(tx, key):
            return variables.ConstantVariable(True)
        else:
            return variables.ConstantVariable(False)
    elif name == '__setitem__' and self.name == '__dict__' and (not kwargs):
        if isinstance(self.obj, variables.UserDefinedObjectVariable):
            return self.obj.method_setattr_standard(tx, args[0], args[1], directly_update_dict=True)
        if isinstance(self.obj, variables.NNModuleVariable):
            self.obj.convert_to_unspecialized(tx)
    return super().call_method(tx, name, args, kwargs)

def _runtests(self, x_shape, is_training, gradient_test=False):
    use_gpu_vals = [False]
    if test.is_gpu_available(cuda_only=True):
        use_gpu_vals += [True]
    factors = [1.0]
    if compat.forward_compatible(2020, 3, 6):
        factors += [0.6]
    for dtype in [np.float16, np.float32]:
        for use_gpu in use_gpu_vals:
            for data_format in ['NHWC', 'NCHW']:
                if <MASK>:
                    scale_shape = x_shape[-1:]
                else:
                    scale_shape = x_shape[1:2]
                for exponential_avg_factor in factors:
                    if gradient_test:
                        self._test_gradient(x_shape, dtype, scale_shape, np.float32, use_gpu=use_gpu, data_format=data_format, is_training=is_training)
                    elif is_training:
                        self._test_training(x_shape, dtype, scale_shape, np.float32, use_gpu=use_gpu, data_format=data_format, exponential_avg_factor=exponential_avg_factor)
                    else:
                        self._test_inference(x_shape, dtype, scale_shape, np.float32, use_gpu=use_gpu, data_format=data_format, exponential_avg_factor=exponential_avg_factor)

def validateMoments(self, shape, mean, stddev, minval, maxval, use_stateless=False, seed=1618):
    try:
        random_seed.set_random_seed(seed)
        with self.cached_session():
            if <MASK>:
                new_seed = random_ops.random_uniform([2], seed=seed, minval=0, maxval=2 ** 31 - 1, dtype=np.int32)
                samples = stateless.stateless_parameterized_truncated_normal(shape, new_seed, mean, stddev, minval, maxval).eval()
            else:
                samples = random_ops.parameterized_truncated_normal(shape, mean, stddev, minval, maxval).eval()
            assert (~np.isnan(samples)).all()
        moments = calculate_moments(samples, self.max_moment)
        expected_moments = TruncatedNormalMoments(mean, stddev, minval, maxval)
        num_samples = functools.reduce(lambda x, y: x * y, shape, 1)
        for i in range(1, len(moments)):
            self.assertLess(z_test(moments, expected_moments, i, num_samples), self.z_limit)
    except ImportError as e:
        tf_logging.warn('Cannot test truncated normal op: %s' % str(e))

@register_jagged_func(torch.ops.aten.transpose.int, 'self: jt_all, dim0: any, dim1: any')
def transpose_int(func, *args, **kwargs):
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    from torch._prims_common import canonicalize_dims
    inp = new_kwargs.pop('input')
    (dim0, dim1) = canonicalize_dims(inp.dim(), (new_kwargs['dim0'], new_kwargs['dim1']))
    if <MASK>:
        if dim0 == 0 or dim1 == 0:
            raise ValueError('Transpose is not supported on the batch dimension for jagged NT')
        if dim0 == inp._ragged_idx:
            to_dim = dim1
        else:
            to_dim = dim0
        inp_kwargs = extract_kwargs(inp)
        inp_kwargs['_ragged_idx'] = to_dim
        return NestedTensor(inp.values().transpose(_outer_to_inner_dim(len(inp._size), dim0, inp._ragged_idx), _outer_to_inner_dim(len(inp._size), dim1, inp._ragged_idx)), **inp_kwargs)
    new_kwargs['dim0'] = _wrap_jagged_dim(inp.dim(), new_kwargs['dim0'], inp._ragged_idx, 'transpose')
    new_kwargs['dim1'] = _wrap_jagged_dim(inp.dim(), new_kwargs['dim1'], inp._ragged_idx, 'transpose')
    return NestedTensor(func(inp._values, **new_kwargs), **extract_kwargs(inp))

def watch_for_translation_changes(sender, **kwargs):
    """Register file watchers for .mo files in potential locale paths."""
    from django.conf import settings
    if <MASK>:
        directories = [Path('locale')]
        directories.extend((Path(config.path) / 'locale' for config in apps.get_app_configs() if not is_django_module(config.module)))
        directories.extend((Path(p) for p in settings.LOCALE_PATHS))
        for path in directories:
