@torch.library.impl(lib, 'fused_all_gather_matmul', 'CUDA')
def _fused_all_gather_matmul(A_shard: torch.Tensor, Bs: list[torch.Tensor], gather_dim: int, group_name: str, *, return_A: bool=True) -> tuple[torch.Tensor | None, list[torch.Tensor]]:
    """
    Perform the following logic with micro-pipelined computation and
    communication:

        all_gather_tensor(A_shard, gather_dim, group_name) @ B

    Optimal stride order for A_shard - if A_shard.movedim(gather_dim, 0) is
    contiguous, no extra copy is required for input layout transformation.
    Otherwise A_shard needs to be copied once.
    """
    if <MASK>:
        return _fused_all_gather_matmul_fallback(A_shard, Bs, gather_dim, group_name, return_A=return_A)
    if _should_use_fused_all_gather_matmul_native(A_shard, Bs, gather_dim, group_name):
        group = c10d._resolve_process_group(group_name)
        leading_dims = list(A_shard.shape[:-1])
        leading_dims[0] *= group.size()
        (A, out) = _fused_all_gather_matmul_native(A_shard.flatten(0, -2), Bs[0], group_name)
        return (A.view(*leading_dims, -1), [out.view(*leading_dims, -1)])
    if _should_use_multimem_all_gather_matmul(A_shard, gather_dim, group_name, return_A):
        return (None, _multimem_all_gather_matmul(A_shard, Bs, group_name))
    with torch.profiler.record_function('fused_all_gather_matmul'):
        return _fused_all_gather_matmul_impl(torch.ops.aten.mm.out, A_shard, Bs, None, [{} for B in Bs], [B.dtype for B in Bs], gather_dim, group_name, return_A)

def _partition_value(self, tensor: torch.Tensor, mesh: DeviceMesh, mesh_dim: int) -> torch.Tensor:
    """
        For example, consider 4 ranks, a (3,) replicated tensor, and 2-norm:
            Ranks 0 and 1: sqrt(t1^2 + t2^2 + t3^3)
        To convert from replicated to partial, we want f(x) such that
            sqrt(t1^2 + t2^2 + t3^3) = sqrt(4f(t1)^2 + 4f(t2)^2 + 4f(t3)^2)
                                     = sqrt(4) sqrt(f(t1)^2 + f(t2)^2 + f(t3)^2).
        One such f(x) is f(x) = x / sqrt(4). This generalizes to d ranks and
        p-norm as f(x) = x / d^(1/p).
        """
    if self.reduce_op in ('max', 'min'):
        return tensor
    elif <MASK>:
        if self.norm_type == 0:
            raise NotImplementedError(f'Unsupported norm type:: {self.norm_type}')
        elif self.norm_type == 1:
            return tensor / mesh.size(mesh_dim)
        if not isinstance(self.norm_type, (int, float)):
            raise AssertionError(f'Expected int or float, got {type(self.norm_type)}')
        return tensor / math.pow(mesh.size(mesh_dim), 1 / self.norm_type)
    raise NotImplementedError(self.reduce_op)

def symbolic_hint(self, expr: Union[Expr, int], hint_override: Optional[int]=None, use_user_provided_hint_override: bool=False) -> Union[Expr, int]:
    if isinstance(expr, int):
        return expr
    expr = self.simplify(expr)
    if <MASK>:
        assert isinstance(expr, int)
        return expr
    free_symbols = expr.free_symbols
    if not free_symbols:
        try:
            return int(expr)
        except TypeError:
            return expr
    if hint_override:
        return hint_override
    expr = self.remove_precomputed_replacements(expr)
    if use_user_provided_hint_override:
        expr = sympy_subs(expr, self.var_to_hint_override)
    return sympy_subs(expr, self.var_to_val)

def __getstate__(self):
    """Hook to allow choosing the attributes to pickle."""
    state = self.__dict__.copy()
    state['_state'] = copy.copy(state['_state'])
    state['_state'].fields_cache = state['_state'].fields_cache.copy()
    _memoryview_attrs = []
    for (attr, value) in state.items():
        if isinstance(value, memoryview):
            _memoryview_attrs.append((attr, bytes(value)))
    if <MASK>:
        state['_memoryview_attrs'] = _memoryview_attrs
        for (attr, value) in _memoryview_attrs:
            state.pop(attr)
    return state

@ignore_warnings
def check_classifiers_train(name, classifier_orig, readonly_memmap=False, X_dtype='float64'):
    (X_m, y_m) = make_blobs(n_samples=300, random_state=0)
    X_m = X_m.astype(X_dtype)
    (X_m, y_m) = shuffle(X_m, y_m, random_state=7)
    X_m = StandardScaler().fit_transform(X_m)
    y_b = y_m[y_m != 2]
    X_b = X_m[y_m != 2]
    if name in ['BernoulliNB', 'MultinomialNB', 'ComplementNB', 'CategoricalNB']:
        X_m -= X_m.min()
        X_b -= X_b.min()
    if readonly_memmap:
        (X_m, y_m, X_b, y_b) = create_memmap_backed_data([X_m, y_m, X_b, y_b])
    problems = [(X_b, y_b)]
    tags = get_tags(classifier_orig)
    if tags.classifier_tags.multi_class:
        problems.append((X_m, y_m))
    for (X, y) in problems:
        classes = np.unique(y)
        n_classes = len(classes)
        (n_samples, n_features) = X.shape
        classifier = clone(classifier_orig)
        X = _enforce_estimator_tags_X(classifier, X)
        y = _enforce_estimator_tags_y(classifier, y)
        set_random_state(classifier)
        if not tags.no_validation:
            with raises(ValueError, err_msg=f'The classifier {name} does not raise an error when incorrect/malformed input data for fit is passed. The number of training examples is not the same as the number of labels. Perhaps use check_X_y in fit.'):
                classifier.fit(X, y[:-1])
        classifier.fit(X, y)
        classifier.fit(X.tolist(), y.tolist())
        assert hasattr(classifier, 'classes_')
        y_pred = classifier.predict(X)
        assert y_pred.shape == (n_samples,)
        if not tags.classifier_tags.poor_score:
            assert accuracy_score(y, y_pred) > 0.83
        msg_pairwise = 'The classifier {} does not raise an error when shape of X in  {} is not equal to (n_test_samples, n_training_samples)'
        msg = 'The classifier {} does not raise an error when the number of features in {} is different from the number of features in fit.'
        if not tags.no_validation:
            if <MASK>:
                with raises(ValueError, err_msg=msg_pairwise.format(name, 'predict')):
                    classifier.predict(X.reshape(-1, 1))
            else:
                with raises(ValueError, err_msg=msg.format(name, 'predict')):
                    classifier.predict(X.T)
        if hasattr(classifier, 'decision_function'):
            try:
                decision = classifier.decision_function(X)
                if n_classes == 2:
                    if tags.target_tags.single_output:
                        assert decision.shape == (n_samples,)
                    else:
                        assert decision.shape == (n_samples, 1)
                    dec_pred = (decision.ravel() > 0).astype(int)
                    assert_array_equal(dec_pred, y_pred)
                else:
                    assert decision.shape == (n_samples, n_classes)
                    assert_array_equal(np.argmax(decision, axis=1), y_pred)
                if not tags.no_validation:
                    if tags.input_tags.pairwise:
                        with raises(ValueError, err_msg=msg_pairwise.format(name, 'decision_function')):
                            classifier.decision_function(X.reshape(-1, 1))
                    else:
                        with raises(ValueError, err_msg=msg.format(name, 'decision_function')):
                            classifier.decision_function(X.T)
            except NotImplementedError:
                pass
        if hasattr(classifier, 'predict_proba'):
            y_prob = classifier.predict_proba(X)
            assert y_prob.shape == (n_samples, n_classes)
            assert_array_equal(np.argmax(y_prob, axis=1), y_pred)
            assert_array_almost_equal(np.sum(y_prob, axis=1), np.ones(n_samples))
            if not tags.no_validation:
                if tags.input_tags.pairwise:
                    with raises(ValueError, err_msg=msg_pairwise.format(name, 'predict_proba')):
                        classifier.predict_proba(X.reshape(-1, 1))
                else:
                    with raises(ValueError, err_msg=msg.format(name, 'predict_proba')):
                        classifier.predict_proba(X.T)
            if hasattr(classifier, 'predict_log_proba'):
                y_log_prob = classifier.predict_log_proba(X)
                assert_allclose(y_log_prob, np.log(y_prob), 8, atol=1e-09)
                assert_array_equal(np.argsort(y_log_prob), np.argsort(y_prob))

def get_dated_items(self):
    """Return (date_list, items, extra_context) for this request."""
    year = self.get_year()
    week = self.get_week()
    date_field = self.get_date_field()
    week_format = self.get_week_format()
    week_choices = {'%W': '1', '%U': '0', '%V': '1'}
    try:
        week_start = week_choices[week_format]
    except KeyError:
        raise ValueError('Unknown week format %r. Choices are: %s' % (week_format, ', '.join(sorted(week_choices))))
    year_format = self.get_year_format()
    if <MASK>:
        raise ValueError("ISO week directive '%s' is incompatible with the year directive '%s'. Use the ISO year '%%G' instead." % (week_format, year_format))
    date = _date_from_string(year, year_format, week_start, '%w', week, week_format)
    since = self._make_date_lookup_arg(date)
    until = self._make_date_lookup_arg(self._get_next_week(date))
    lookup_kwargs = {'%s__gte' % date_field: since, '%s__lt' % date_field: until}
    qs = self.get_dated_queryset(**lookup_kwargs)
    return (None, qs, {'week': date, 'next_week': self.get_next_week(date), 'previous_week': self.get_previous_week(date)})

def get_prep_lookup(self):
    from django.db.models.sql.query import Query
    if <MASK>:
        if not query.has_limit_one():
            raise ValueError('The QuerySet value for an exact lookup must be limited to one result using slicing.')
        lhs_len = len(self.lhs) if isinstance(self.lhs, (ColPairs, tuple)) else 1
        if (rhs_len := query._subquery_fields_len) != lhs_len:
            raise ValueError(f'The QuerySet value for the exact lookup must have {lhs_len} selected fields (received {rhs_len})')
        if not query.has_select_fields:
            query.clear_select_clause()
            query.add_fields(['pk'])
    return super().get_prep_lookup()

@register_graph_pattern(CallFunctionVarArgs(torch.ops.higher_order.auto_functionalized_v2), pass_dict=graph_pass)
def _(match: Match, *args, **kwargs):
    from torch._higher_order_ops.auto_functionalize import auto_functionalized_v2_dense
    only_clone_these_bases = tuple(match.nodes[0].meta.get('only_clone_these_tensors', []))
    (flat_args, spec) = pytree.tree_flatten((args, kwargs))

    def _maybe_resolve_constant_get_attr(node):
        if <MASK>:
            const_attr = getattr(graph.owning_module, node.target)
            assert isinstance(const_attr, (torch.fx.GraphModule, pytree.TreeSpec)), (type(const_attr), const_attr)
            return const_attr
        return node
    flat_args = [_maybe_resolve_constant_get_attr(arg) for arg in flat_args]

    def decomp(*flat_args):
        (args, kwargs) = pytree.tree_unflatten(flat_args, spec)
        assert len(args) == 1
        mutable_op = args[0]
        return auto_functionalized_v2_dense(mutable_op, only_clone_these_bases, **kwargs)
    match.replace_by_example(decomp, flat_args, run_functional_passes=False)

def _get_support_mask(self):
    check_is_fitted(self)
    if self.percentile == 100:
        return np.ones(len(self.scores_), dtype=bool)
    elif self.percentile == 0:
        return np.zeros(len(self.scores_), dtype=bool)
    scores = _clean_nans(self.scores_)
    threshold = np.percentile(scores, 100 - self.percentile)
    mask = scores > threshold
    ties = np.where(scores == threshold)[0]
    if <MASK>:
        max_feats = int(len(scores) * self.percentile / 100)
        kept_ties = ties[:max_feats - mask.sum()]
        mask[kept_ties] = True
    return mask

def _scalar_str(dtype, short):
    byteorder = _byte_order_str(dtype)
    if dtype.type == np.bool:
        if short:
            return "'?'"
        else:
            return "'bool'"
    elif dtype.type == np.object_:
        return "'O'"
    elif dtype.type == np.bytes_:
        if _isunsized(dtype):
            return "'S'"
        else:
            return "'S%d'" % dtype.itemsize
    elif dtype.type == np.str_:
        if _isunsized(dtype):
            return f"'{byteorder}U'"
        else:
            return "'%sU%d'" % (byteorder, dtype.itemsize / 4)
    elif dtype.type == str:
        return "'T'"
    elif not type(dtype)._legacy:
        return f"'{byteorder}{type(dtype).__name__}{dtype.itemsize * 8}'"
    elif issubclass(dtype.type, np.void):
        if _isunsized(dtype):
            return "'V'"
        else:
            return "'V%d'" % dtype.itemsize
    elif dtype.type == np.datetime64:
        return f"'{byteorder}M8{_datetime_metadata_str(dtype)}'"
    elif dtype.type == np.timedelta64:
        return f"'{byteorder}m8{_datetime_metadata_str(dtype)}'"
    elif dtype.isbuiltin == 2:
        return dtype.type.__name__
    elif <MASK>:
        if short or dtype.byteorder not in ('=', '|'):
            return "'%s%c%d'" % (byteorder, dtype.kind, dtype.itemsize)
        else:
            return "'%s%d'" % (_kind_name(dtype), 8 * dtype.itemsize)
    else:
        raise RuntimeError('Internal error: NumPy dtype unrecognized type number')

def match(self, actual, expected, msg=None):
    msg_ = 'Expected: {} Actual: {}'.format(expected, actual)
    if <MASK>:
        msg = '{} {}'.format(msg_, msg)
    else:
        msg = msg_
    self.assertIsInstance(actual, np_arrays.ndarray)
    self.match_dtype(actual, expected, msg)
    self.match_shape(actual, expected, msg)
    if not actual.shape.rank:
        self.assertEqual(actual.tolist(), expected.tolist())
    else:
        self.assertSequenceEqual(actual.tolist(), expected.tolist())

def get_signatures_from_saved_model(saved_model_path: str, signature_keys: Optional[Sequence[str]]=None, tags: Optional[Collection[str]]=None) -> Dict[str, meta_graph_pb2.SignatureDef]:
    """Gets a map from signature keys to their SignatureDef.

  Args:
    saved_model_path: Path to the saved model.
    signature_keys: List of keys identifying SignatureDef to retrieve. If None,
      retrieve all except the init signature.
    tags: Set of tags identifying the MetaGraphDef within the SavedModel.

  Returns:
    A map from signature_key to its SignatureDef.
  """
    if tags is None:
        tags = {tag_constants.SERVING}
    loader = saved_model_loader.SavedModelLoader(saved_model_path)
    meta_graphdef = loader.get_meta_graph_def_from_tags(tags)
    signatures = {}
    for (key, signature_def) in meta_graphdef.signature_def.items():
        if <MASK>:
            continue
        if signature_keys is not None and key not in signature_keys:
            continue
        signatures[key] = signature_def
    return signatures

@normalizer
def divmod(x1: ArrayLike, x2: ArrayLike, out1: Optional[OutArray]=None, out2: Optional[OutArray]=None, /, out: tuple[Optional[OutArray], Optional[OutArray]]=(None, None), *, where: NotImplementedType=True, casting: Optional[CastingModes]='same_kind', order: NotImplementedType='K', dtype: Optional[DTypeLike]=None, subok: NotImplementedType=False, signature: NotImplementedType=None, extobj: NotImplementedType=None):
    num_outs = sum((x is not None for x in [out1, out2]))
    if num_outs == 1:
        raise ValueError('both out1 and out2 need to be provided')
    elif <MASK>:
        (o1, o2) = out
        if o1 is not None or o2 is not None:
            raise TypeError("cannot specify 'out' as both a positional and keyword argument")
    else:
        (out1, out2) = out
    if dtype is None:
        dtype = _dtypes_impl.result_type_impl(x1, x2)
    (x1, x2) = _util.typecast_tensors((x1, x2), dtype, casting)
    (quot, rem) = _binary_ufuncs_impl.divmod(x1, x2)
    quot = _ufunc_postprocess(quot, out1, casting)
    rem = _ufunc_postprocess(rem, out2, casting)
    return (quot, rem)

def _get_ufunc_and_otypes(self, func, args):
    """Return (ufunc, otypes)."""
    if not args:
        raise ValueError('args can not be empty')
    if self.otypes is not None:
        otypes = self.otypes
        nin = len(args)
        nout = len(self.otypes)
        if func is not self.pyfunc or nin not in self._ufunc:
            ufunc = frompyfunc(func, nin, nout)
        else:
            ufunc = None
        if <MASK>:
            ufunc = self._ufunc.setdefault(nin, ufunc)
    else:
        args = [asarray(a) for a in args]
        if builtins.any((arg.size == 0 for arg in args)):
            raise ValueError('cannot call `vectorize` on size 0 inputs unless `otypes` is set')
        inputs = [arg.flat[0] for arg in args]
        outputs = func(*inputs)
        if self.cache:
            _cache = [outputs]

            def _func(*vargs):
                if _cache:
                    return _cache.pop()
                else:
                    return func(*vargs)
        else:
            _func = func
        if isinstance(outputs, tuple):
            nout = len(outputs)
        else:
            nout = 1
            outputs = (outputs,)
        otypes = ''.join([asarray(outputs[_k]).dtype.char for _k in range(nout)])
        ufunc = frompyfunc(_func, len(args), nout)
    return (ufunc, otypes)

@final
def __setstate__(self, state) -> None:
    if isinstance(state, BlockManager):
        self._mgr = state
    elif isinstance(state, dict):
        if '_data' in state and '_mgr' not in state:
            state['_mgr'] = state.pop('_data')
        typ = state.get('_typ')
        if typ is not None:
            attrs = state.get('_attrs', {})
            if attrs is None:
                attrs = {}
            object.__setattr__(self, '_attrs', attrs)
            flags = state.get('_flags', {'allows_duplicate_labels': True})
            object.__setattr__(self, '_flags', Flags(self, **flags))
            meta = set(self._internal_names + self._metadata)
            for k in meta:
                if <MASK>:
                    v = state[k]
                    object.__setattr__(self, k, v)
            for (k, v) in state.items():
                if k not in meta:
                    object.__setattr__(self, k, v)
        else:
            raise NotImplementedError('Pre-0.12 pickles are no longer supported')
    elif len(state) == 2:
        raise NotImplementedError('Pre-0.12 pickles are no longer supported')

def create_local_plan(self) -> LoadPlan:
    if self.metadata is None:
        raise AssertionError('self.metadata is not None')
    if self.flatten_state_dict:
        current_keys = set(self.state_dict.keys())
        load_keys = set(self.metadata.state_dict_metadata.keys())
        missing_keys = load_keys - current_keys
        if missing_keys:
            _version._derived_version = '2_3'
            (old_state_dict, old_mappings) = flatten_state_dict(self.original_state_dict)
            old_keys = set(old_state_dict.keys())
            if <MASK>:
                (self.state_dict, self.mappings) = (old_state_dict, old_mappings)
            _version._derived_version = None
    return create_default_local_load_plan(self.state_dict, self.metadata, not self.allow_partial_load)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    if <MASK>:
        values = values.astype(self.dtype, copy=False)
    else:
        if not lib.is_string_array(np.asarray(values), skipna=True):
            values = np.array([val for val in values if isinstance(val, str) or isna(val)], dtype=object)
            if not len(values):
                return np.zeros(self.shape, dtype=bool)
        values = self._from_sequence(values, dtype=self.dtype)
    return isin(np.asarray(self), np.asarray(values))

def get_flex_attn_bwd_configs(self, head_dim: int, dtype: Any) -> list[FlexBwDConfig]:
    flex_attn_bwd_configs: list[FlexBwDConfig] = []
    if config.max_autotune:
        if config.max_autotune_flex_search_space == 'EXHAUSTIVE':
            return self.exhaustive_flex_attn_bwd_configs
        flex_attn_bwd_configs += self.flex_attn_bwd_autotune_configs
    if dtype == torch.float32:
        default_config = ROCmFlexBwDConfig(16, 16, 16, 16, 1, 4)
    elif <MASK>:
        if head_dim == 64:
            default_config = ROCmFlexBwDConfig(64, 64, 64, 64, 1, 4)
        elif head_dim == 128:
            default_config = ROCmFlexBwDConfig(64, 128, 128, 64, 1, 8)
        else:
            default_config = ROCmFlexBwDConfig(64, 64, 64, 64, 1, 4)
    else:
        default_config = ROCmFlexBwDConfig(16, 16, 16, 16, 1, 4)
    if default_config not in flex_attn_bwd_configs:
        flex_attn_bwd_configs.append(default_config)
    return flex_attn_bwd_configs

def __eq__(self, other: object) -> bool:
    if isinstance(other, _StridedShard):
        return self.dim == other.dim and self.split_factor == other.split_factor
    elif <MASK>:
        return self.dim == other.dim
    return False

def numpy(self):

    def to_numpy(t):
        if <MASK>:
            if t.dtype is torch.bfloat16:
                return t.detach().cpu().to(torch.float32).numpy()
            if t.dtype is torch.chalf:
                return t.detach().cpu().to(torch.cfloat).numpy()
            return t.detach().cpu().numpy()
        elif isinstance(t, torch.dtype):
            return torch_to_numpy_dtype_dict[t]
        return t
    return self.transform(to_numpy)

def make_key(self, input_nodes: tuple[ir.IRNode], num_stages: int, num_warps: int, call_sizes: Sequence[sympy.core.symbol.Symbol], prefix_args: int, suffix_args: int, epilogue_fn: Optional[Callable[..., Any]], epilogue_fn_hash: Optional[str], tma_store: bool, subgraphs: Optional[list[ir.Buffer]], workspace_arg: Optional[WorkspaceArg], layout: ir.Layout, num_consumer_groups: int, num_buffers_warp_spec: int, kwargs: dict[str, Any], hint_override: Optional[int]=None) -> Optional[str]:

    def layout_key(layout: ir.Layout) -> str:
        assert not isinstance(layout, ir.FlexibleLayout)
        return repr([layout.size, layout.stride, layout.dtype, layout.device, layout.offset])

    def has_flexible_layout() -> bool:
        if isinstance(layout, ir.FlexibleLayout):
            return True
        for input in input_nodes:
            if isinstance(input.get_layout(), ir.FlexibleLayout):
                return True
        return False
    if <MASK>:
        assert epilogue_fn_hash is None
        epilogue_fn_hash = 'identity'
    if has_flexible_layout() or subgraphs is not None or workspace_arg is not None or (epilogue_fn_hash is None):
        return None
    return repr({'input_nodes': [layout_key(input.get_layout()) for input in input_nodes], 'num_stages': num_stages, 'num_warps': num_warps, 'prefix_args': prefix_args, 'suffix_args': suffix_args, 'call_sizes': call_sizes, 'layout': layout_key(layout), 'num_consumer_groups': num_consumer_groups, 'num_buffers_warp_spec': num_buffers_warp_spec, 'epilogue_fn_hash': epilogue_fn_hash, 'tma_store': tma_store, 'kwargs': kwargs, 'hint_override': hint_override})

@click.command()
@click.option('--tests', '-t', default=None, metavar='TESTS', multiple=True, help='Which tests to run')
@click.option('--compare', '-c', is_flag=True, default=False, help='Compare benchmarks between the current branch and main (unless other branches specified). The benchmarks are each executed in a new isolated environment.')
@click.option('--verbose', '-v', is_flag=True, default=False)
@click.option('--quick', '-q', is_flag=True, default=False, help="Run each benchmark only once (timings won't be accurate)")
@click.argument('commits', metavar='', required=False, nargs=-1)
@meson.build_dir_option
@click.pass_context
def bench(ctx, tests, compare, verbose, quick, commits, build_dir):
    """🏋 Run benchmarks.

    \x08
    Examples:

    \x08
    $ spin bench -t bench_lib
    $ spin bench -t bench_random.Random
    $ spin bench -t Random -t Shuffle

    Two benchmark runs can be compared.
    By default, `HEAD` is compared to `main`.
    You can also specify the branches/commits to compare:

    \x08
    $ spin bench --compare
    $ spin bench --compare main
    $ spin bench --compare main HEAD

    You can also choose which benchmarks to run in comparison mode:

    $ spin bench -t Random --compare
    """
    if not commits:
        commits = ('main', 'HEAD')
    elif len(commits) == 1:
        commits = commits + ('HEAD',)
    elif len(commits) > 2:
        raise click.ClickException('Need a maximum of two revisions to compare')
    bench_args = []
    for t in tests:
        bench_args += ['--bench', t]
    if <MASK>:
        bench_args = ['-v'] + bench_args
    if quick:
        bench_args = ['--quick'] + bench_args
    if not compare:
        click.secho('Invoking `build` prior to running benchmarks:', bold=True, fg='bright_green')
        ctx.invoke(build)
        meson._set_pythonpath(build_dir)
        p = spin.util.run(['python', '-c', 'import numpy as np; print(np.__version__)'], cwd='benchmarks', echo=False, output=False)
        os.chdir('..')
        np_ver = p.stdout.strip().decode('ascii')
        click.secho(f'Running benchmarks on NumPy {np_ver}', bold=True, fg='bright_green')
        cmd = ['asv', 'run', '--dry-run', '--show-stderr', '--python=same'] + bench_args
        _run_asv(cmd)
    else:
        (commit_a, commit_b) = [_commit_to_sha(c) for c in commits]
        if commit_b == 'HEAD' and _dirty_git_working_dir():
            click.secho('WARNING: you have uncommitted changes --- these will NOT be benchmarked!', fg='red')
        cmd_compare = ['asv', 'continuous', '--factor', '1.05'] + bench_args + [commit_a, commit_b]
        _run_asv(cmd_compare)

def process_inputs(flat_args: list[Any], aot_config: AOTConfig, fake_mode: FakeTensorMode, shape_env: Optional[ShapeEnv], ignore_shape_env: bool=False) -> FakifiedFlatArgs:
    with fake_mode:

        def convert(idx, x):
            if shape_env is not None and (not ignore_shape_env):
                from torch._dynamo.source import ConstantSource
                if isinstance(x, int):
                    if aot_config.is_export:
                        return x
                    source = ConstantSource(f'sym_{idx}')
                    return shape_env.create_symintnode(shape_env.create_symbol(x, source), hint=x, source=source)
            if isinstance(x, torch.ScriptObject):
                return torch._library.fake_class_registry.maybe_to_fake_obj(fake_mode, x)
            if not isinstance(x, torch.Tensor):
                return x
            if isinstance(x, FakeTensor):
                assert x.fake_mode is fake_mode
                return x
            if <MASK>:
                (attrs, _) = x.__tensor_flatten__()
                if all((isinstance(getattr(x, attr), FakeTensor) for attr in attrs)):
                    assert all((getattr(x, attr).fake_mode is fake_mode for attr in attrs))
                    return x
            symbolic_context = None
            source = None
            trace = True
            if (tracing_context := torch._guards.TracingContext.try_get()):
                if x in tracing_context.tensor_to_context:
                    symbolic_context = tracing_context.tensor_to_context[x]
                    source = symbolic_context.tensor_source
                    trace = False
            if idx < aot_config.num_params_buffers and config.static_weight_shapes and (not symbolic_context):
                return fake_mode.from_tensor(x, static_shapes=True)
            result = fake_mode.from_tensor(x, static_shapes=ignore_shape_env, symbolic_context=symbolic_context, source=source, trace=trace)
            return result
        return FakifiedFlatArgs([convert(idx, x) for (idx, x) in enumerate(flat_args)])

def _integer_repr(x, vdt, comp):
    rx = x.view(vdt)
    if <MASK>:
        rx[rx < 0] = comp - rx[rx < 0]
    elif rx < 0:
        rx = comp - rx
    return rx

def check_graph_breaks(actual_csv, expected_csv, expected_filename):
    failed = []
    improved = []
    if 'rocm' in expected_filename:
        flaky_models.update({'alexnet', 'demucs', 'densenet121', 'detectron2_fcos_r_50_fpn', 'doctr_det_predictor', 'doctr_reco_predictor', 'levit_128', 'llava', 'microbench_unbacked_tolist_sum', 'resnet50', 'resnet152', 'sam', 'sam_fast', 'stable_diffusion_text_encoder', 'stable_diffusion_unet', 'timm_efficientdet', 'torchrec_dlrm', 'vgg16', 'meta-llama/Llama-3.2-1B', 'google/gemma-2-2b', 'google/gemma-3-4b-it', 'openai/whisper-tiny', 'Qwen/Qwen3-0.6B', 'mistralai/Mistral-7B-Instruct-v0.3', 'openai/gpt-oss-20b'})
    for model in actual_csv['name']:
        graph_breaks = get_field(actual_csv, model, 'graph_breaks')
        expected_graph_breaks = get_field(expected_csv, model, 'graph_breaks')
        flaky = model in flaky_models
        if expected_graph_breaks is None:
            status = 'MISSING:'
            improved.append(model)
        elif graph_breaks == expected_graph_breaks:
            status = 'PASS_BUT_FLAKY' if flaky else 'PASS'
            print(f'{model:34}  {status}')
            continue
        elif graph_breaks > expected_graph_breaks:
            if <MASK>:
                status = 'FAIL_BUT_FLAKY:'
            else:
                status = 'FAIL:'
                failed.append(model)
        elif graph_breaks < expected_graph_breaks:
            if flaky:
                status = 'IMPROVED_BUT_FLAKY:'
            else:
                status = 'IMPROVED:'
                improved.append(model)
        print(f'{model:34}  {status:19} graph_breaks={graph_breaks}, expected={expected_graph_breaks}')
    msg = ''
    if failed or improved:
        if failed:
            msg += textwrap.dedent(f"\n            Error: {len(failed)} models have new dynamo graph breaks:\n                {' '.join(failed)}\n\n            ")
        if improved:
            msg += textwrap.dedent(f"\n            Improvement: {len(improved)} models have fixed dynamo graph breaks:\n                {' '.join(improved)}\n\n            ")
        sha = os.getenv('SHA1', '{your CI commit sha}')
        msg += textwrap.dedent(f'\n        If this change is expected, you can update `{expected_filename}` to reflect the new baseline.\n        from pytorch/pytorch root, run\n        `python benchmarks/dynamo/ci_expected_accuracy/update_expected.py {sha}`\n        and then `git add` the resulting local changes to expected CSVs to your commit.\n        ')
    return (failed or improved, msg)

def render(self, context):
    """
        Render the specified template and context. Cache the template object
        in render_context to avoid reparsing and loading when used in a for
        loop.
        """
    template = self.template.resolve(context)
    if not callable(getattr(template, 'render', None)):
        template_name = template or ()
        if <MASK>:
            template_name = (construct_relative_path(self.origin.template_name, template_name),)
        else:
            template_name = tuple(template_name)
        cache = context.render_context.dicts[0].setdefault(self, {})
        template = cache.get(template_name)
        if template is None:
            template = context.template.engine.select_template(template_name)
            cache[template_name] = template
    elif hasattr(template, 'template'):
        template = template.template
    values = {name: var.resolve(context) for (name, var) in self.extra_context.items()}
    if self.isolated_context:
        return template.render(context.new(values))
    with context.push(**values):
        return template.render(context)

def replace_cascade_sum_with_add(buffer: IndentedBuffer):
    """
    Replaces `acc = cascade_sum_combine(value, ...)` with `acc = acc + value;`
    """
    pattern = '(.*?)\\s*=\\s*cascade_sum_combine\\(([^,]+),.*?\\);'
    for (i, line) in enumerate(buffer._lines):
        assert isinstance(line, (str, DeferredLine))
        content = line.line if isinstance(line, DeferredLine) else line
        match = re.search(pattern, content)
        if <MASK>:
            (acc, value) = match.groups()
            new_content = re.sub(pattern, f'{acc} = {acc} + {value};', content)
            if isinstance(line, DeferredLine):
                line.line = new_content
            else:
                buffer._lines[i] = new_content

def get_reruns(grouped_tests: list[list[dict[str, Any]]]) -> dict[str, Any]:
    reruns: dict[str, Any] = defaultdict(lambda : defaultdict(lambda : defaultdict(lambda : defaultdict(lambda : defaultdict(list)))))
    for tests in grouped_tests:
        if len(tests) > 1:
            build_name = tests[0]['build_name']
            test_config = tests[0]['test_config']
            file = tests[0].get('file', 'NoFile')
            class_name = tests[0].get('classname', 'NoClass')
            test_name = tests[0].get('name', 'NoName')
            if <MASK>:
                continue
            reruns[build_name][test_config][file][class_name][test_name] = tests
    return reruns

def initialize_lazy_module(tx: 'InstructionTranslator', mod, args, kwargs):
    """
    Fairly coupled helper used by NNModuleVariable and UnspecializedNNModuleVariable.

    Used to cause lazy module to be initialized (and delete its init hook) before tracing. Especially
    useful now that 'allowed' modules graph-break on hooks, calling this first ensures there is no hook
    by the time we trace __call__ and thus no graph-break for lazy allowed modules.
    """
    if hasattr(mod, '_initialize_hook'):

        def convert_to_fake(x):
            if <MASK>:
                return type(x)(*(convert_to_fake(elem) for elem in x))
            elif isinstance(x, dict):
                return {k: convert_to_fake(v) for (k, v) in x.items()}
            elif isinstance(x, (list, tuple, set)):
                return type(x)((convert_to_fake(elem) for elem in x))
            elif isinstance(x, torch.fx.Proxy):
                return get_fake_value(x.node, tx)
            else:
                return x
        (proxy_args, proxy_kwargs) = proxy_args_kwargs(args, kwargs)
        fake_args = [convert_to_fake(arg) for arg in proxy_args]
        fake_kwargs = {k: convert_to_fake(v) for (k, v) in proxy_kwargs.items()}
        try:
            mod._infer_parameters(mod, fake_args, fake_kwargs)
        except AttributeError as e:
            raise_observed_exception(AttributeError, tx, msg=str(e) if str(e) else 'AttributeError during lazy module initialization')

