    raise ValueError('Unable to get batched dataset from the input dataset. `batch` `map_and_batch` need to be the last operations on the dataset. The batch operations can be followed by a prefetch.')

def _dtype_to_stata_type(dtype: np.dtype, column: Series) -> int:
    """
    Convert dtype types to stata types. Returns the byte of the given ordinal.
    See TYPE_MAP and comments for an explanation. This is also explained in
    the dta spec.
    1 - 244 are strings of this length
                         Pandas    Stata
    251 - for int8      byte
    252 - for int16     int
    253 - for int32     long
    254 - for float32   float
    255 - for double    double

    If there are dates to convert, then dtype will already have the correct
    type inserted.
    """
    if dtype.type is np.object_:
        itemsize = max_len_string_array(ensure_object(column._values))
        return max(itemsize, 1)
    elif dtype.type is np.float64:
        return 255
    elif dtype.type is np.float32:
        return 254
    elif dtype.type is np.int32:
        return 253
    elif <MASK>:
        return 252
    elif dtype.type is np.int8:
        return 251
    else:
        raise NotImplementedError(f'Data type {dtype} not supported.')

def write_data(self, plan: SavePlan, planner: SavePlanner) -> Future[list[WriteResult]]:
    storage_plan: _StoragePrefix = plan.storage_data
    file_count = 0

    def gen_file():
        nonlocal file_count
        file_name = f'{storage_plan.prefix}{file_count}{DEFAULT_SUFFIX}'
        file_count += 1
        return file_name
    file_queue: queue.Queue = queue.Queue()
    if <MASK>:
        for bucket in _split_by_size_and_type(self.thread_count, plan.items):
            file_name = gen_file()
            path = self.fs.concat_path(self.path, file_name)
            file_queue.put((path, file_name, bucket))
    else:
        for item in plan.items:
            file_name = gen_file()
            path = self.fs.concat_path(self.path, file_name)
            file_queue.put((path, file_name, [item]))
    return self._write_data(planner, file_queue)

def _reduce(self, name: str, *, skipna: bool=True, keepdims: bool=False, axis: AxisInt | None=0, **kwargs):
    if self.dtype.na_value is np.nan and name in ['any', 'all']:
