def _test_input_iteration(self, input_type, api_type, iteration_type, dataset_or_input_fn, worker_device_pairs, expected_values, strategy, sess=None, num_replicas_in_sync=None, input_context=None):
    if iteration_type == 'for_loop' and (not context.executing_eagerly()):
        self.skipTest('unsupported test combination.')
    if api_type == 'wrap_into_iterator' and iteration_type == 'for_loop':
        self.skipTest('unsupported test combination.')
    if api_type == 'wrap_into_iterator' and input_type == 'input_fn':
        self.skipTest('unsupported test combination.')
    devices = nest.flatten([ds for (_, ds) in worker_device_pairs])
    input_workers = input_lib.InputWorkers(worker_device_pairs)
    if api_type == 'wrap_into_iterator':
        iterator = self._wrap_iterator(input_type, dataset_or_input_fn, input_workers, devices, num_replicas_in_sync, strategy, input_context=input_context)
    else:
        dataset = self._wrap_dataset(input_type, dataset_or_input_fn, input_workers, num_replicas_in_sync, strategy, input_context=input_context)
        if <MASK>:
            iterator = iter(dataset)
        elif isinstance(dataset, input_lib_v1.DistributedDatasetV1):
            iterator = dataset.make_initializable_iterator()
        else:
            self.skipTest('unsupported test combination')
    if isinstance(iterator, composite_tensor.CompositeTensor):
        nest.assert_same_structure(iterator, iterator._type_spec, expand_composites=True)
    if iteration_type == 'get_next':
        evaluate = lambda x: sess.run(x) if sess else self.evaluate(x)
        if not ops.executing_eagerly_outside_functions():
            evaluate(control_flow_ops.group(iterator.initializer))

        def test_get_next(iterator):
            self._assert_iterator_values(iterator, expected_values, evaluate, devices)
            with self.assertRaises(errors.OutOfRangeError):
                self._assert_iterator_values(iterator, expected_values, evaluate, devices)
            if not ops.executing_eagerly_outside_functions():
                evaluate(control_flow_ops.group(iterator.initializer))
            elif api_type == 'wrap_into_iterator':
                self.skipTest('unsupported test combination')
            else:
                iterator = iter(dataset)
            self._assert_iterator_values(iterator, expected_values, evaluate, devices)

        def test_get_next_as_optional(iterator):
            self._assert_iterator_values(iterator, expected_values, evaluate, devices, enable_get_next_as_optional=True)
            next_element = iterator.get_next_as_optional()
            self.assertFalse(self.evaluate(next_element.has_value()))
            with self.assertRaises(errors.InvalidArgumentError):
                self._assert_iterator_values(iterator, [0], evaluate, devices, enable_get_next_as_optional=True)
        test_get_next(iterator)
        if not tf2.enabled():
            return
        elif api_type == 'wrap_into_iterator':
            return
        else:
            iterator = iter(dataset)
        test_get_next_as_optional(iterator)
    if iteration_type == 'for_loop' and context.executing_eagerly():
        self._assert_dataset_values_for_loop(dataset, expected_values, self.evaluate, devices)

@convert_phase(Component.PREPARE_TF_MODEL, SubComponent.VALIDATE_INPUTS)
def _validate_inputs(self, input_tensors, quantized_input_stats):
    """Validate input parameters.

    Args:
      input_tensors: List of input tensors.
      quantized_input_stats: Map of input tensor names to a tuple of floats
        representing the mean and standard deviation of the training data.

    Raises:
      ValueError:
        Input shape is not specified.
        Quantization input stats is required but not provided.
    """
    if not self._is_unknown_shapes_allowed() and self._has_valid_tensors():
        for tensor in input_tensors:
            shape = tensor.shape
            if not shape:
                raise ValueError("Provide an input shape for input array '{0}'.".format(_get_tensor_name(tensor)))
            shape_list = shape.as_list()
            if None in shape_list[1:]:
                raise ValueError("None is only supported in the 1st dimension. Tensor '{0}' has invalid shape '{1}'.".format(_get_tensor_name(tensor), shape_list))
            elif <MASK>:
                self._set_batch_size(batch_size=1)
    if quantized_input_stats:
        self._quantized_stats = []
        invalid_stats = []
        for name in self.get_input_arrays():
            if name in quantized_input_stats:
                self._quantized_stats.append(quantized_input_stats[name])
            else:
                invalid_stats.append(name)
        if invalid_stats:
            raise ValueError("Quantization input stats are not available for input tensors '{0}'.".format(','.join(invalid_stats)))
    else:
        self._quantized_stats = None

def build_filter(self, filter_expr, branch_negated=False, current_negated=False, can_reuse=None, allow_joins=True, split_subq=True, check_filterable=True, summarize=False, update_join_types=True):
    """
        Build a WhereNode for a single filter clause but don't add it
        to this Query. Query.add_q() will then add this filter to the where
        Node.

        The 'branch_negated' tells us if the current branch contains any
        negations. This will be used to determine if subqueries are needed.

        The 'current_negated' is used to determine if the current filter is
        negated or not and this will be used to determine if IS NULL filtering
        is needed.

        The difference between current_negated and branch_negated is that
        branch_negated is set on first negation, but current_negated is
        flipped for each negation.

        Note that add_filter will not do any negating itself, that is done
        upper in the code by add_q().

        The 'can_reuse' is a set of reusable joins for multijoins.

        The method will create a filter clause that can be added to the current
        query. However, if the filter isn't added to the query then the caller
        is responsible for unreffing the joins used.
        """
    if isinstance(filter_expr, dict):
        raise FieldError('Cannot parse keyword query as dict')
    if isinstance(filter_expr, Q):
        return self._add_q(filter_expr, branch_negated=branch_negated, current_negated=current_negated, used_aliases=can_reuse, allow_joins=allow_joins, split_subq=split_subq, check_filterable=check_filterable, summarize=summarize, update_join_types=update_join_types)
    if hasattr(filter_expr, 'resolve_expression'):
        if not getattr(filter_expr, 'conditional', False):
            raise TypeError('Cannot filter against a non-conditional expression.')
        condition = filter_expr.resolve_expression(self, allow_joins=allow_joins, reuse=can_reuse, summarize=summarize)
        if not isinstance(condition, Lookup):
            condition = self.build_lookup(['exact'], condition, True)
        return (WhereNode([condition], connector=AND), [])
    (arg, value) = filter_expr
    if not arg:
        raise FieldError('Cannot parse keyword query %r' % arg)
    (lookups, parts, reffed_expression) = self.solve_lookup_type(arg, summarize)
    if check_filterable:
        self.check_filterable(reffed_expression)
    if not allow_joins and len(parts) > 1:
        raise FieldError('Joined field references are not permitted in this query')
    pre_joins = self.alias_refcount.copy()
    value = self.resolve_lookup_value(value, can_reuse, allow_joins, summarize)
    used_joins = {k for (k, v) in self.alias_refcount.items() if v > pre_joins.get(k, 0)}
    if check_filterable:
        self.check_filterable(value)
    if reffed_expression:
        condition = self.build_lookup(lookups, reffed_expression, value)
        return (WhereNode([condition], connector=AND), [])
    opts = self.get_meta()
    alias = self.get_initial_alias()
    allow_many = not branch_negated or not split_subq
    try:
        join_info = self.setup_joins(parts, opts, alias, can_reuse=can_reuse, allow_many=allow_many)
        if <MASK>:
            value = list(value)
        self.check_related_objects(join_info.final_field, value, join_info.opts)
        self._lookup_joins = join_info.joins
    except MultiJoin as e:
        return self.split_exclude(filter_expr, can_reuse, e.names_with_path)
    used_joins.update(join_info.joins)
    (targets, alias, join_list) = self.trim_joins(join_info.targets, join_info.joins, join_info.path)
    if can_reuse is not None:
        can_reuse.update(join_list)
    if join_info.final_field.is_relation:
        if len(targets) == 1:
            col = self._get_col(targets[0], join_info.final_field, alias)
        else:
            col = ColPairs(alias, targets, join_info.targets, join_info.final_field)
    else:
        col = self._get_col(targets[0], join_info.final_field, alias)
    condition = self.build_lookup(lookups, col, value)
    lookup_type = condition.lookup_name
    clause = WhereNode([condition], connector=AND)
    require_outer = lookup_type == 'isnull' and condition.rhs is True and (not current_negated)
    if current_negated and (lookup_type != 'isnull' or condition.rhs is False) and (condition.rhs is not None):
        require_outer = True
        if lookup_type != 'isnull':
            if self.is_nullable(targets[0]) or self.alias_map[join_list[-1]].join_type == LOUTER:
                lookup_class = targets[0].get_lookup('isnull')
                col = self._get_col(targets[0], join_info.targets[0], alias)
                clause.add(lookup_class(col, False), AND)
            if isinstance(value, Col) and self.is_nullable(value.target):
                lookup_class = value.target.get_lookup('isnull')
                clause.add(lookup_class(value, False), AND)
    return (clause, used_joins if not require_outer else ())

def _process_equalities(constraint: Constraint, get_sources: Callable[[int, int], list['Source']], shape_env: 'ShapeEnv', names: dict[str, tuple[int, int]], source_pairs: list[tuple['Source', 'Source']], derived_equalities: list[tuple['Source', Union['Source', 'Symbol'], Callable]], phantom_symbols: dict[str, 'Symbol'], relaxed_sources: set['Source']):
    """
    Updates `source_pairs`, `derived_equalities`, and `phantom_symbols` (which become
    fields of `EqualityConstraint`) based on a given input `constraint`.
    """
    sources = get_sources(constraint.t_id, constraint.dim)
    if not sources:
        return
    (source, *other_sources) = sources
    source_pairs.extend(((source, other_source) for other_source in other_sources))
    if isinstance(constraint, _Constraint):
        if <MASK>:
            (shared_t_id, shared_dim) = names[constraint.name]
            other_sources = get_sources(shared_t_id, shared_dim)
            source_pairs.extend(((source, other_source) for other_source in other_sources))
        else:
            names[constraint.name] = (constraint.t_id, constraint.dim)
    elif isinstance(constraint, _DerivedConstraint):
        if not isinstance(constraint.root, _PhantomRoot):
            root = get_sources(constraint.root.t_id, constraint.root.dim)[0]
        elif constraint.root.name in phantom_symbols:
            root = phantom_symbols[constraint.root.name]
        else:
            root = shape_env.create_symbol(val=constraint.root.val, source=torch._dynamo.source.ConstantSource(constraint.root.name), dynamic_dim=torch.fx.experimental.symbolic_shapes.DimDynamic.DYNAMIC, constraint_dim=constraint.root.constraint_range)
            phantom_symbols[constraint.root.name] = root
        fn = constraint.fn
        derived_equalities.append((source, root, fn))
    elif isinstance(constraint, _RelaxedConstraint):
        relaxed_sources.add(source)

def find_functions(filename, tag='API'):
    """
    Scan the file, looking for tagged functions.

    Assuming ``tag=='API'``, a tagged function looks like::

        /*API*/
        static returntype*
        function_name(argtype1 arg1, argtype2 arg2)
        {
        }

    where the return type must be on a separate line, the function
    name must start the line, and the opening ``{`` must start the line.

    An optional documentation comment in ReST format may follow the tag,
    as in::

        /*API
          This function does foo...
         */
    """
    if filename.endswith(('.c.src', '.h.src')):
        fo = io.StringIO(process_c_file(filename))
    else:
        fo = open(filename, 'r')
    functions = []
    return_type = None
    function_name = None
    function_args = []
    doclist = []
    (SCANNING, STATE_DOC, STATE_RETTYPE, STATE_NAME, STATE_ARGS) = list(range(5))
    state = SCANNING
    tagcomment = '/*' + tag
    for (lineno, line) in enumerate(fo):
        try:
            line = line.strip()
            if state == SCANNING:
                if line.startswith(tagcomment):
                    if <MASK>:
                        state = STATE_RETTYPE
                    else:
                        state = STATE_DOC
            elif state == STATE_DOC:
                if line.startswith('*/'):
                    state = STATE_RETTYPE
                else:
                    line = line.lstrip(' *')
                    doclist.append(line)
            elif state == STATE_RETTYPE:
                m = re.match('NPY_NO_EXPORT\\s+(.*)$', line)
                if m:
                    line = m.group(1)
                return_type = line
                state = STATE_NAME
            elif state == STATE_NAME:
                m = re.match('(\\w+)\\s*\\(', line)
                if m:
                    function_name = m.group(1)
                else:
                    raise ParseError(filename, lineno + 1, 'could not find function name')
                function_args.append(line[m.end():])
                state = STATE_ARGS
            elif state == STATE_ARGS:
                if line.startswith('{'):
                    fargs_str = ' '.join(function_args).rstrip()[:-1].rstrip()
                    fargs = split_arguments(fargs_str)
                    f = Function(function_name, return_type, fargs, '\n'.join(doclist))
                    functions.append(f)
                    return_type = None
                    function_name = None
                    function_args = []
                    doclist = []
                    state = SCANNING
                else:
                    function_args.append(line)
        except ParseError:
            raise
        except Exception as e:
            msg = 'see chained exception for details'
            raise ParseError(filename, lineno + 1, msg) from e
    fo.close()
    return functions

def assert_helper(a: Any, b: Any) -> None:
    if isinstance(a, tuple):
        assert isinstance(b, tuple)
        assert len(a) == len(b)
        for (l, r) in zip(a, b):
            assert_helper(l, r)
    elif <MASK>:
        assert isinstance(b, int) and a == b
    elif a is None:
        assert b is None
    elif isinstance(a, py_sym_types):
        assert type(a) is type(b) and a.node is b.node
    elif isinstance(a, torch.Tensor):
        assert isinstance(b, torch.Tensor)
        assert_metadata_eq(assert_eq, a, b)
    else:
        raise RuntimeError(f'Unsupported type {type(a)}')

def deprecated_wrapper(func):
    """Deprecation decorator."""
    decorator_utils.validate_callable(func, 'deprecated_arg_values')

    @functools.wraps(func)
    def new_func(*args, **kwargs):
        """Deprecation wrapper."""
        if _PRINT_DEPRECATION_WARNINGS:
            named_args = tf_inspect.getcallargs(func, *args, **kwargs)
            for (arg_name, arg_value) in deprecated_kwargs.items():
                if <MASK>:
                    if (func, arg_name) not in _PRINTED_WARNING:
                        if warn_once:
                            _PRINTED_WARNING[func, arg_name] = True
                        _log_deprecation('From %s: calling %s (from %s) with %s=%s is deprecated and will be removed %s.\nInstructions for updating:\n%s', _call_location(), decorator_utils.get_qualified_name(func), func.__module__, arg_name, arg_value, 'in a future version' if date is None else 'after %s' % date, instructions)
        return func(*args, **kwargs)
    doc = _add_deprecated_arg_value_notice_to_docstring(func.__doc__, date, instructions, deprecated_kwargs)
    return tf_decorator.make_decorator(func, new_func, 'deprecated', doc)

@ignore_warnings
def check_classifiers_train(name, classifier_orig, readonly_memmap=False, X_dtype='float64'):
    (X_m, y_m) = make_blobs(n_samples=300, random_state=0)
    X_m = X_m.astype(X_dtype)
    (X_m, y_m) = shuffle(X_m, y_m, random_state=7)
    X_m = StandardScaler().fit_transform(X_m)
    y_b = y_m[y_m != 2]
    X_b = X_m[y_m != 2]
    if name in ['BernoulliNB', 'MultinomialNB', 'ComplementNB', 'CategoricalNB']:
        X_m -= X_m.min()
        X_b -= X_b.min()
    if readonly_memmap:
        (X_m, y_m, X_b, y_b) = create_memmap_backed_data([X_m, y_m, X_b, y_b])
    problems = [(X_b, y_b)]
    tags = get_tags(classifier_orig)
    if <MASK>:
        problems.append((X_m, y_m))
    for (X, y) in problems:
        classes = np.unique(y)
        n_classes = len(classes)
        (n_samples, n_features) = X.shape
        classifier = clone(classifier_orig)
        X = _enforce_estimator_tags_X(classifier, X)
        y = _enforce_estimator_tags_y(classifier, y)
        set_random_state(classifier)
        if not tags.no_validation:
            with raises(ValueError, err_msg=f'The classifier {name} does not raise an error when incorrect/malformed input data for fit is passed. The number of training examples is not the same as the number of labels. Perhaps use check_X_y in fit.'):
                classifier.fit(X, y[:-1])
        classifier.fit(X, y)
        classifier.fit(X.tolist(), y.tolist())
        assert hasattr(classifier, 'classes_')
        y_pred = classifier.predict(X)
        assert y_pred.shape == (n_samples,)
        if not tags.classifier_tags.poor_score:
            assert accuracy_score(y, y_pred) > 0.83
        msg_pairwise = 'The classifier {} does not raise an error when shape of X in  {} is not equal to (n_test_samples, n_training_samples)'
        msg = 'The classifier {} does not raise an error when the number of features in {} is different from the number of features in fit.'
        if not tags.no_validation:
            if tags.input_tags.pairwise:
                with raises(ValueError, err_msg=msg_pairwise.format(name, 'predict')):
                    classifier.predict(X.reshape(-1, 1))
            else:
                with raises(ValueError, err_msg=msg.format(name, 'predict')):
                    classifier.predict(X.T)
        if hasattr(classifier, 'decision_function'):
            try:
                decision = classifier.decision_function(X)
                if n_classes == 2:
                    if tags.target_tags.single_output:
                        assert decision.shape == (n_samples,)
                    else:
                        assert decision.shape == (n_samples, 1)
                    dec_pred = (decision.ravel() > 0).astype(int)
                    assert_array_equal(dec_pred, y_pred)
                else:
                    assert decision.shape == (n_samples, n_classes)
                    assert_array_equal(np.argmax(decision, axis=1), y_pred)
                if not tags.no_validation:
                    if tags.input_tags.pairwise:
                        with raises(ValueError, err_msg=msg_pairwise.format(name, 'decision_function')):
                            classifier.decision_function(X.reshape(-1, 1))
                    else:
                        with raises(ValueError, err_msg=msg.format(name, 'decision_function')):
                            classifier.decision_function(X.T)
            except NotImplementedError:
                pass
        if hasattr(classifier, 'predict_proba'):
            y_prob = classifier.predict_proba(X)
            assert y_prob.shape == (n_samples, n_classes)
            assert_array_equal(np.argmax(y_prob, axis=1), y_pred)
            assert_array_almost_equal(np.sum(y_prob, axis=1), np.ones(n_samples))
            if not tags.no_validation:
                if tags.input_tags.pairwise:
                    with raises(ValueError, err_msg=msg_pairwise.format(name, 'predict_proba')):
                        classifier.predict_proba(X.reshape(-1, 1))
                else:
                    with raises(ValueError, err_msg=msg.format(name, 'predict_proba')):
                        classifier.predict_proba(X.T)
            if hasattr(classifier, 'predict_log_proba'):
                y_log_prob = classifier.predict_log_proba(X)
                assert_allclose(y_log_prob, np.log(y_prob), 8, atol=1e-09)
                assert_array_equal(np.argsort(y_log_prob), np.argsort(y_prob))

def _parse_column_or_constraint_definition(self, tokens, columns):
    token = None
    is_constraint_definition = None
    field_name = None
    constraint_name = None
    unique = False
    unique_columns = []
    check = False
    check_columns = []
    braces_deep = 0
    for token in tokens:
        if token.match(sqlparse.tokens.Punctuation, '('):
            braces_deep += 1
        elif token.match(sqlparse.tokens.Punctuation, ')'):
            braces_deep -= 1
            if braces_deep < 0:
                break
        elif braces_deep == 0 and token.match(sqlparse.tokens.Punctuation, ','):
            break
        if is_constraint_definition is None:
            is_constraint_definition = token.match(sqlparse.tokens.Keyword, 'CONSTRAINT')
            if is_constraint_definition:
                continue
        if is_constraint_definition:
            if constraint_name is None:
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    constraint_name = token.value
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    constraint_name = token.value[1:-1]
            if <MASK>:
                unique = True
                unique_braces_deep = braces_deep
            elif unique:
                if unique_braces_deep == braces_deep:
                    if unique_columns:
                        unique = False
                    continue
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    unique_columns.append(token.value)
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    unique_columns.append(token.value[1:-1])
        else:
            if field_name is None:
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    field_name = token.value
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    field_name = token.value[1:-1]
            if token.match(sqlparse.tokens.Keyword, 'UNIQUE'):
                unique_columns = [field_name]
        if token.match(sqlparse.tokens.Keyword, 'CHECK'):
            check = True
            check_braces_deep = braces_deep
        elif check:
            if check_braces_deep == braces_deep:
                if check_columns:
                    check = False
                continue
            if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                if token.value in columns:
                    check_columns.append(token.value)
            elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                if token.value[1:-1] in columns:
                    check_columns.append(token.value[1:-1])
    unique_constraint = {'unique': True, 'columns': unique_columns, 'primary_key': False, 'foreign_key': None, 'check': False, 'index': False} if unique_columns else None
    check_constraint = {'check': True, 'columns': check_columns, 'primary_key': False, 'unique': False, 'foreign_key': None, 'index': False} if check_columns else None
    return (constraint_name, unique_constraint, check_constraint, token)

