def _while(self, f=None):
    if <MASK>:
        f = lambda x, y: (x, y)

    def _f(x, y):
        return (while_loop.while_loop(lambda j, _: j < y, lambda j, t: (j + 1, t + array_ops.gather(f(x, y)[0], j)), [0, x])[1], y)
    return _f

def decorator(fn):

    @functools.wraps(fn)
    def wrapper(g, *args, **kwargs):
        nonlocal scale
        nonlocal zero_point
        if scale is not None:
            _scale = g.op('Constant', value_t=torch.tensor(scale))
        else:
            _scale = None
        if zero_point is not None:
            _zero_point = g.op('Constant', value_t=torch.tensor(zero_point))
        else:
            _zero_point = None
        arg_q_descriptors_extended = arg_q_descriptors + (False,) * (len(args) - len(arg_q_descriptors))
        descriptor_args = tuple(zip(arg_q_descriptors_extended, args))

        def _is_arg_quantized(descriptor, arg):
            return descriptor and _is_value(arg) and _is_tuple_construct(arg)
        is_quantized: list[bool] = []
        for (descriptor, arg) in descriptor_args:
            if _is_packed_list(arg):
                is_quantized.extend((_is_arg_quantized(descriptor, arg_input) for arg_input in arg.node().inputs()))
            else:
                is_quantized.append(_is_arg_quantized(descriptor, arg))
        if not any(is_quantized):
            return fn(g, *args, **kwargs)
        non_quantized_args = []
        for (descriptor, arg) in descriptor_args:
            if _is_arg_quantized(descriptor, arg):
                (dequantized_arg, arg_scale, arg_zero_point, _) = dequantize_helper(g, arg)
                non_quantized_args.append(dequantized_arg)
                if _scale is None:
                    _scale = arg_scale
                if <MASK>:
                    _zero_point = arg_zero_point
            elif _is_packed_list(arg):
                for arg_input in arg.node().inputs():
                    if _is_arg_quantized(descriptor, arg_input):
                        (dequantized_arg, arg_scale, arg_zero_point, _) = dequantize_helper(g, arg_input)
                        if _scale is None:
                            _scale = arg_scale
                        if _zero_point is None:
                            _zero_point = arg_zero_point
                        arg_input.replaceAllUsesWith(dequantized_arg)
                non_quantized_args.append(arg)
            else:
                non_quantized_args.append(arg)
        output = fn(g, *non_quantized_args, **kwargs)
        assert _scale is not None, 'Bug: Scale must be set for quantized operator'
        assert _zero_point is not None, 'Bug: Zero point must be set for quantized operator'
        if quantize_output:
            return quantize_helper(g, output, _scale, _zero_point)
        return output
    return wrapper

@register.tag
def now(parser, token):
    """
    Display the date, formatted according to the given string.

    Use the same format as PHP's ``date()`` function; see https://php.net/date
    for all the possible values.

    Sample usage::

        It is {% now "jS F Y H:i" %}
    """
    bits = token.split_contents()
    asvar = None
    if <MASK>:
        asvar = bits[-1]
        bits = bits[:-2]
    if len(bits) != 2:
        raise TemplateSyntaxError("'now' statement takes one argument")
    format_string = bits[1][1:-1]
    return NowNode(format_string, asvar)

def substitute(self, env: Mapping[str, object] | None=None, **kwargs: object) -> str:
    if env is None:
        env = {}

    def lookup(v: str) -> object:
        assert env is not None
        return kwargs[v] if v in kwargs else env[v]

    def indent_lines(indent: str, v: Sequence[object]) -> str:
        content = '\n'.join(itertools.chain.from_iterable((str(e).splitlines() for e in v)))
        content = textwrap.indent(content, prefix=indent)
        return '\n'.join(map(str.rstrip, content.splitlines())).rstrip()

    def replace(match: re.Match[str]) -> str:
        indent = match.group(1)
        key = match.group(2)
        comma_before = ''
        comma_after = ''
        if key[0] == '{':
            key = key[1:-1]
            if key[0] == ',':
                comma_before = ', '
                key = key[1:]
            if key[-1] == ',':
                comma_after = ', '
                key = key[:-1]
        v = lookup(key)
        if <MASK>:
            if not isinstance(v, list):
                v = [v]
            return indent_lines(indent, v)
        elif isinstance(v, list):
            middle = ', '.join([str(x) for x in v])
            if len(v) == 0:
                return middle
            return comma_before + middle + comma_after
        else:
            return str(v)
    return self.substitution.sub(replace, self.pattern)

@ops.RegisterGradient('Pow')
def _PowGrad(op: ops.Operation, grad):
    """Returns grad * (y*x^(y-1), z*log(x))."""
    x = op.inputs[0]
    y = op.inputs[1]
    cx = math_ops.conj(x)
    cy = math_ops.conj(y)
    try:
        skip_input_indices = op.skip_input_indices or ()
        if 1 in skip_input_indices and _IsScalar(y):
            return (grad * cy * math_ops.pow(cx, cy - 1), None)
    except AttributeError:
        skip_input_indices = ()
    if 0 in skip_input_indices:
        gx = None
    else:
        gx = grad * cy * math_ops.pow(cx, cy - 1)
    if 1 in skip_input_indices:
        gy = None
    else:
        if <MASK>:
            mask = math_ops.not_equal(cx, 0)
        else:
            mask = cx > 0
        safe_x = array_ops.where(mask, cx, array_ops.ones_like(x))
        log_x = array_ops.where(mask, math_ops.log(safe_x), array_ops.zeros_like(x))
        gy = grad * math_ops.conj(op.outputs[0]) * log_x
    return _ReduceGradientArgs(x, y, gx, gy)

def test_lambda_basic(self):

    def test_fn(a):
        a = lambda b: a + b
        return a
    graphs = self._build_cfg(test_fn)
    for (k, v) in graphs.items():
        if <MASK>:
            lam_graph = v
        else:
            fn_graph = v
    self.assertGraphMatches(fn_graph, (('a', '(lambda b: (a + b))', 'a = (lambda b: (a + b))'), ('(lambda b: (a + b))', 'a = (lambda b: (a + b))', 'return a'), ('a = (lambda b: (a + b))', 'return a', None)))
    self.assertGraphEnds(fn_graph, 'a', ('return a',))
    self.assertGraphMatches(lam_graph, (('b', '(a + b)', None),))
    self.assertGraphEnds(lam_graph, 'b', ('(a + b)',))

def get_monitor_value(self, logs):
    logs = logs or {}
    monitor_value = logs.get(self.monitor)
    if <MASK>:
        logging.warning('Early stopping conditioned on metric `%s` which is not available. Available metrics are: %s', self.monitor, ','.join(list(logs.keys())))
    return monitor_value

def __init__(self, params: ParamsT, lr: Union[float, Tensor]=0.001, betas: tuple[Union[float, Tensor], Union[float, Tensor]]=(0.9, 0.999), eps: float=1e-08, weight_decay: float=0, amsgrad: bool=False, *, foreach: Optional[bool]=None, maximize: bool=False, capturable: bool=False, differentiable: bool=False, fused: Optional[bool]=None, decoupled_weight_decay: bool=False):
    if isinstance(lr, Tensor):
        if foreach and (not capturable):
            raise ValueError('lr as a Tensor is not supported for capturable=False and foreach=True')
        if lr.numel() != 1:
            raise ValueError('Tensor lr must be 1-element')
    if <MASK>:
        raise ValueError(f'Invalid learning rate: {lr}')
    if not 0.0 <= eps:
        raise ValueError(f'Invalid epsilon value: {eps}')
    if not 0.0 <= betas[0] < 1.0:
        raise ValueError(f'Invalid beta parameter at index 0: {betas[0]}')
    if not 0.0 <= betas[1] < 1.0:
        raise ValueError(f'Invalid beta parameter at index 1: {betas[1]}')
    if not 0.0 <= weight_decay:
        raise ValueError(f'Invalid weight_decay value: {weight_decay}')
    if not (isinstance(betas[0], float) and isinstance(betas[1], float) or (isinstance(betas[0], Tensor) and isinstance(betas[1], Tensor))):
        raise ValueError('betas must be either both floats or both Tensors')
    if isinstance(betas[0], Tensor):
        if not capturable and foreach:
            raise ValueError('betas[0] as a Tensor is not supported for capturable=False and foreach=True')
        if betas[0].numel() != 1:
            raise ValueError('Tensor betas[0] must be 1-element')
    if isinstance(betas[1], Tensor):
        if not capturable and foreach:
            raise ValueError('betas[1] as a Tensor is not supported for capturable=False and foreach=True')
        if betas[1].numel() != 1:
            raise ValueError('Tensor betas[1] must be 1-element')
    betas = tuple(map(_to_scalar, betas))
    defaults = {'lr': lr, 'betas': betas, 'eps': eps, 'weight_decay': weight_decay, 'amsgrad': amsgrad, 'maximize': maximize, 'foreach': foreach, 'capturable': capturable, 'differentiable': differentiable, 'fused': fused, 'decoupled_weight_decay': decoupled_weight_decay}
    super().__init__(params, defaults)
    if fused:
        if differentiable:
            raise RuntimeError('`fused` does not support `differentiable`')
        self._step_supports_amp_scaling = True
        if foreach:
            raise RuntimeError('`fused` and `foreach` cannot be `True` together.')

def maybe_dequantize_first_two_tensor_args_and_handle_tuples(f):

    def inner(*args, **kwargs):
        (a0, a1, *a_other) = args
        if isinstance(a0, tuple) and isinstance(a1, tuple) or (isinstance(a0, list) and isinstance(a1, list)):
            results = []
            for (el0, el1) in zip(a0, a1):
                new_args = (el0, el1, *a_other)
                results.append(inner(*new_args, **kwargs))
            return results
        elif isinstance(a0, torch.Tensor) and isinstance(a1, torch.Tensor):
            if <MASK>:
                a0 = a0.dequantize()
            if a1.is_quantized:
                a1 = a1.dequantize()
        if a0.dtype != torch.float or a1.dtype != torch.float:
            return None
        new_args = (a0, a1, *a_other)
        return f(*new_args, **kwargs)
    return inner

def forward(self, input: Tensor) -> Tensor:
    """
        Runs the forward pass.
        """
    self._check_input_dim(input)
    self._check_non_zero_input_channels(input)
    if self.momentum is None:
        exponential_average_factor = 0.0
    else:
        exponential_average_factor = self.momentum
    if self.training and self.track_running_stats:
        assert self.num_batches_tracked is not None
        self.num_batches_tracked.add_(1)
        if self.momentum is None:
            exponential_average_factor = 1.0 / self.num_batches_tracked.item()
        else:
            exponential_average_factor = self.momentum
    '\n        Decide whether the mini-batch stats should be used for normalization rather than the buffers.\n        Mini-batch stats are used in training mode, and in eval mode when buffers are None.\n        '
    if self.training:
        bn_training = True
    else:
        bn_training = self.running_mean is None and self.running_var is None
    '\n        Buffers are only updated if they are to be tracked and we are in training mode. Thus they only need to be\n        passed when the update should occur (i.e. in training mode when they are tracked), or when buffer stats are\n        used for normalization (i.e. in eval mode when buffers are not None).\n        '
    running_mean = self.running_mean if not self.training or self.track_running_stats else None
    running_var = self.running_var if not self.training or self.track_running_stats else None
    need_sync = bn_training and self.training and torch.distributed.is_available() and torch.distributed.is_initialized()
    if need_sync:
        if <MASK>:
            raise ValueError(f'SyncBatchNorm expected input tensor to be on GPU or XPU or {torch._C._get_privateuse1_backend_name()}')
        process_group = torch.distributed.group.WORLD
        if self.process_group:
            process_group = self.process_group
        world_size = torch.distributed.get_world_size(process_group)
        need_sync = world_size > 1
    if not need_sync:
        return F.batch_norm(input, running_mean, running_var, self.weight, self.bias, bn_training, exponential_average_factor, self.eps)
    else:
        assert bn_training
        return sync_batch_norm.apply(input, self.weight, self.bias, running_mean, running_var, self.eps, exponential_average_factor, process_group, world_size)

def _dp_init_subclass(sub_cls, *args, **kwargs):
    sub_cls.reinforce_type = reinforce_type
    if <MASK>:
        return
    if isinstance(sub_cls.type.param, ForwardRef):
        base_globals = sys.modules[sub_cls.__module__].__dict__
        try:
            param = _eval_type(sub_cls.type.param, base_globals, locals())
            sub_cls.type.param = param
        except TypeError as e:
            raise TypeError(f'{sub_cls.type.param.__forward_arg__} is not supported by Python typing') from e
    if '__iter__' in sub_cls.__dict__:
        iter_fn = sub_cls.__dict__['__iter__']
        hints = get_type_hints(iter_fn)
        if 'return' in hints:
            return_hint = hints['return']
            if return_hint == Iterator:
                return
            if not (hasattr(return_hint, '__origin__') and (return_hint.__origin__ == Iterator or return_hint.__origin__ == collections.abc.Iterator)):
                raise TypeError("Expected 'Iterator' as the return annotation for `__iter__` of {}, but found {}".format(sub_cls.__name__, _type_repr(hints['return'])))
            data_type = return_hint.__args__[0]
            if not issubtype(data_type, sub_cls.type.param):
                raise TypeError(f"Expected return type of '__iter__' as a subtype of {sub_cls.type}, but found {_type_repr(data_type)} for {sub_cls.__name__}")

