def _rescale_data(X, y, sample_weight, inplace=False):
    """Rescale data sample-wise by square root of sample_weight.

    For many linear models, this enables easy support for sample_weight because

        (y - X w)' S (y - X w)

    with S = diag(sample_weight) becomes

        ||y_rescaled - X_rescaled w||_2^2

    when setting

        y_rescaled = sqrt(S) y
        X_rescaled = sqrt(S) X

    The parameter `inplace` only takes effect for dense X and dense y.

    Returns
    -------
    X_rescaled : {array-like, sparse matrix}

    y_rescaled : {array-like, sparse matrix}

    sample_weight_sqrt : array-like of shape (n_samples,)
    """
    (xp, _) = get_namespace(X, y, sample_weight)
    n_samples = X.shape[0]
    sample_weight_sqrt = xp.sqrt(sample_weight)
    if sp.issparse(X) or sp.issparse(y):
        sw_matrix = sparse.dia_matrix((sample_weight_sqrt, 0), shape=(n_samples, n_samples))
    if sp.issparse(X):
        X = safe_sparse_dot(sw_matrix, X)
    elif inplace:
        X *= sample_weight_sqrt[:, None]
    else:
        X = X * sample_weight_sqrt[:, None]
    if sp.issparse(y):
        y = safe_sparse_dot(sw_matrix, y)
    elif inplace:
        if <MASK>:
            y *= sample_weight_sqrt
        else:
            y *= sample_weight_sqrt[:, None]
    elif y.ndim == 1:
        y = y * sample_weight_sqrt
    else:
        y = y * sample_weight_sqrt[:, None]
    return (X, y, sample_weight_sqrt)

def generate_FA_callable(attn_type: str, shape: tuple[int], dtype: torch.dtype, backend: str, **kwargs) -> Callable | None:
    if dtype not in [torch.float16, torch.bfloat16]:
        return None
    if backend == 'fav2':
        try:
            from flash_attn import flash_attn_func, flash_attn_varlen_func
        except ImportError:
            print('Flash attention 2 is not installed. Please install it to run fav2 backend. ')
            raise
    elif backend == 'fav3':
        try:
            from flash_attn.flash_attn_interface import flash_attn_func, flash_attn_varlen_func
        except ImportError:
            print('Flash attention 3 is not installed. Please install it to run fav3 backend. ')
            raise
    else:
        print('Unknown backend ' + backend)
        return None
    (B, Hq, M, Hkv, N, D) = shape
    FA_kwargs = {}
    if <MASK>:
        h = torch.arange(Hq, dtype=torch.float32, device='cuda')
        alibi_slopes = torch.exp2(-((h + 1) * 8.0 / Hq))
        FA_kwargs = dict(alibi_slopes=alibi_slopes)
    elif attn_type == 'document_mask':
        FA_kwargs['cu_seqlens_q'] = kwargs['offsets'].to(torch.int32)
        FA_kwargs['cu_seqlens_k'] = kwargs['offsets'].to(torch.int32)

        def offsets_to_lengths(offsets: torch.Tensor, device: Union[str, torch.device]) -> torch.tensor:
            lengths = offsets[1:] - offsets[:-1]
            return lengths
        lengths = offsets_to_lengths(kwargs['offsets'], 'cpu')
        max_length = torch.max(lengths)
        FA_kwargs['max_seqlen_q'] = max_length
        FA_kwargs['max_seqlen_k'] = max_length
    FA_dict = {'noop': partial(flash_attn_func, causal=False), 'causal': partial(flash_attn_func, causal=True), 'rel': None, 'head_bias': None, 'alibi': partial(flash_attn_func, causal=True, **FA_kwargs), 'sliding_window': partial(flash_attn_func, window_size=(sliding_window_size, 0), causal=True), 'document_mask': partial(flash_attn_varlen_func, causal=True, **FA_kwargs), 'prefix_lm': None, 'softcap': partial(flash_attn_func, softcap=softcap_value, causal=True)}
    return FA_dict[attn_type]

def add(self, *objs, bulk=True):
    self._remove_prefetched_objects()
    db = router.db_for_write(self.model, instance=self.instance)

    def check_and_update_obj(obj):
        if not isinstance(obj, self.model):
            raise TypeError("'%s' instance expected, got %r" % (self.model._meta.object_name, obj))
        setattr(obj, self.content_type_field_name, self.content_type)
        setattr(obj, self.object_id_field_name, self.pk_val)
    if <MASK>:
        pks = []
        for obj in objs:
            if obj._state.adding or obj._state.db != db:
                raise ValueError("%r instance isn't saved. Use bulk=False or save the object first." % obj)
            check_and_update_obj(obj)
            pks.append(obj.pk)
        self.model._base_manager.using(db).filter(pk__in=pks).update(**{self.content_type_field_name: self.content_type, self.object_id_field_name: self.pk_val})
    else:
        with transaction.atomic(using=db, savepoint=False):
            for obj in objs:
                check_and_update_obj(obj)
                obj.save()

def __init__(self, regex=None, message=None, code=None, inverse_match=None, flags=None):
    if regex is not None:
        self.regex = regex
    if message is not None:
        self.message = message
    if code is not None:
        self.code = code
    if <MASK>:
        self.inverse_match = inverse_match
    if flags is not None:
        self.flags = flags
    if self.flags and (not isinstance(self.regex, str)):
        raise TypeError('If the flags are set, regex must be a regular expression string.')
    self.regex = _lazy_re_compile(self.regex, self.flags)

def add_loggers_to_model(gm: GraphModule, node_to_instrument_inputs_to_ref_node_name: dict[Node, tuple[str, str]], node_to_instrument_outputs_to_ref_node_name: dict[Node, tuple[str, str]], logger_cls: Callable, model_name: str) -> GraphModule:
    """
    Takes the graph of gm, adds loggers to the output
    of each node in nodes_to_instrument. Returns a GraphModule with the new
    graph.
    """
    new_graph = Graph()
    env: dict[str, Any] = {}

    def load_arg(a):
        return map_arg(a, lambda node: env[node.name])
    for node in gm.graph.nodes:
        if node.op == 'output':
            new_graph.output(map_arg(get_normalized_nth_input(node, gm, 0), load_arg))
            continue
        if node in node_to_instrument_inputs_to_ref_node_name or node in node_to_instrument_outputs_to_ref_node_name:
            fqn = _maybe_get_fqn(node, gm)
            if <MASK>:
                (ref_name, ref_node_type) = node_to_instrument_inputs_to_ref_node_name[node]
                arg_indices_to_log = get_arg_indices_of_inputs_to_log(node)
                for node_arg_idx in arg_indices_to_log:
                    node_arg = get_normalized_nth_input(node, gm, node_arg_idx)
                    if type(node_arg) is Node:
                        prev_node = env[node_arg.name]
                        env[node_arg.name] = _insert_logger_after_node(prev_node, gm, logger_cls, '_ns_logger_', node.name, model_name, ref_name, ref_node_type, NSSingleResultValuesType.NODE_INPUT.value, index_within_arg=0, index_of_arg=node_arg_idx, fqn=fqn)
                    elif type(node_arg) is torch.fx.immutable_collections.immutable_list:
                        for (arg_idx, arg) in enumerate(node_arg):
                            prev_node = env[arg.name]
                            env[prev_node.name] = _insert_logger_after_node(prev_node, gm, logger_cls, '_ns_logger_', node.name, model_name, ref_name, ref_node_type, NSSingleResultValuesType.NODE_INPUT.value, index_within_arg=arg_idx, index_of_arg=node_arg_idx, fqn=fqn)
            env[node.name] = new_graph.node_copy(node, load_arg)
            if node in node_to_instrument_outputs_to_ref_node_name:
                (ref_name, ref_node_type) = node_to_instrument_outputs_to_ref_node_name[node]
                env[node.name] = _insert_logger_after_node(env[node.name], gm, logger_cls, '_ns_logger_', node.name, model_name, ref_name, ref_node_type, NSSingleResultValuesType.NODE_OUTPUT.value, index_within_arg=0, index_of_arg=0, fqn=fqn)
        else:
            env[node.name] = new_graph.node_copy(node, load_arg)
    new_gm = GraphModule(gm, new_graph)
    return new_gm

def get_formset(self, request, obj=None, **kwargs):
    """Return a BaseInlineFormSet class for use in add/change views."""
    if 'fields' in kwargs:
        fields = kwargs.pop('fields')
    else:
        fields = flatten_fieldsets(self.get_fieldsets(request, obj))
    excluded = self.get_exclude(request, obj)
    exclude = [] if excluded is None else list(excluded)
    exclude.extend(self.get_readonly_fields(request, obj))
    if excluded is None and hasattr(self.form, '_meta') and self.form._meta.exclude:
        exclude.extend(self.form._meta.exclude)
    exclude = exclude or None
    can_delete = self.can_delete and self.has_delete_permission(request, obj)
    defaults = {'form': self.form, 'formset': self.formset, 'fk_name': self.fk_name, 'fields': fields, 'exclude': exclude, 'formfield_callback': partial(self.formfield_for_dbfield, request=request), 'extra': self.get_extra(request, obj, **kwargs), 'min_num': self.get_min_num(request, obj, **kwargs), 'max_num': self.get_max_num(request, obj, **kwargs), 'can_delete': can_delete, **kwargs}
    base_model_form = defaults['form']
    can_change = self.has_change_permission(request, obj) if request else True
    can_add = self.has_add_permission(request, obj) if request else True

    class DeleteProtectedModelForm(base_model_form):

        def hand_clean_DELETE(self):
            """
                We don't validate the 'DELETE' field itself because on
                templates it's not rendered using the field information, but
                just using a generic "deletion_field" of the InlineModelAdmin.
                """
            if self.cleaned_data.get(DELETION_FIELD_NAME, False):
                using = router.db_for_write(self._meta.model)
                collector = NestedObjects(using=using)
                if self.instance._state.adding:
                    return
                collector.collect([self.instance])
                if collector.protected:
                    objs = []
                    for p in collector.protected:
                        objs.append(_('%(class_name)s %(instance)s') % {'class_name': p._meta.verbose_name, 'instance': p})
                    params = {'class_name': self._meta.model._meta.verbose_name, 'instance': self.instance, 'related_objects': get_text_list(objs, _('and'))}
                    msg = _('Deleting %(class_name)s %(instance)s would require deleting the following protected related objects: %(related_objects)s')
                    raise ValidationError(msg, code='deleting_protected', params=params)

        def is_valid(self):
            result = super().is_valid()
            self.hand_clean_DELETE()
            return result

        def has_changed(self):
            if not can_change and (not self.instance._state.adding):
                return False
            if not can_add and self.instance._state.adding:
                return False
            return super().has_changed()
    defaults['form'] = DeleteProtectedModelForm
    if <MASK>:
        defaults['fields'] = forms.ALL_FIELDS
    return inlineformset_factory(self.parent_model, self.model, **defaults)

def handle(self, *args, **options):
    locale = options['locale']
    exclude = options['exclude']
    self.domain = options['domain']
    self.verbosity = options['verbosity']
    process_all = options['all']
    extensions = options['extensions']
    self.symlinks = options['symlinks']
    ignore_patterns = options['ignore_patterns']
    if options['use_default_ignore_patterns']:
        ignore_patterns += ['CVS', '.*', '*~', '*.pyc']
    self.ignore_patterns = list(set(ignore_patterns))
    if options['no_wrap']:
        self.msgmerge_options = self.msgmerge_options[:] + ['--no-wrap']
        self.msguniq_options = self.msguniq_options[:] + ['--no-wrap']
        self.msgattrib_options = self.msgattrib_options[:] + ['--no-wrap']
        self.xgettext_options = self.xgettext_options[:] + ['--no-wrap']
    if options['no_location']:
        self.msgmerge_options = self.msgmerge_options[:] + ['--no-location']
        self.msguniq_options = self.msguniq_options[:] + ['--no-location']
        self.msgattrib_options = self.msgattrib_options[:] + ['--no-location']
        self.xgettext_options = self.xgettext_options[:] + ['--no-location']
    if options['add_location']:
        arg_add_location = '--add-location=%s' % options['add_location']
        self.msgmerge_options = self.msgmerge_options[:] + [arg_add_location]
        self.msguniq_options = self.msguniq_options[:] + [arg_add_location]
        self.msgattrib_options = self.msgattrib_options[:] + [arg_add_location]
        self.xgettext_options = self.xgettext_options[:] + [arg_add_location]
    self.no_obsolete = options['no_obsolete']
    self.keep_pot = options['keep_pot']
    if <MASK>:
        raise CommandError("currently makemessages only supports domains 'django' and 'djangojs'")
    if self.domain == 'djangojs':
        exts = extensions or ['js']
    else:
        exts = extensions or ['html', 'txt', 'py']
    self.extensions = handle_extensions(exts)
    if not locale and (not exclude) and (not process_all) or self.domain is None:
        raise CommandError("Type '%s help %s' for usage information." % (os.path.basename(sys.argv[0]), sys.argv[1]))
    if self.verbosity > 1:
        self.stdout.write('examining files with the extensions: %s' % get_text_list(list(self.extensions), 'and'))
    self.invoked_for_django = False
    self.locale_paths = []
    self.default_locale_path = None
    if os.path.isdir(os.path.join('conf', 'locale')):
        self.locale_paths = [os.path.abspath(os.path.join('conf', 'locale'))]
        self.default_locale_path = self.locale_paths[0]
        self.ignore_patterns.append('views/templates/i18n_catalog.js')
        self.invoked_for_django = True
    else:
        if self.settings_available:
            for path in settings.LOCALE_PATHS:
                locale_path = os.path.abspath(path)
                if locale_path not in self.locale_paths:
                    self.locale_paths.append(locale_path)
        if os.path.isdir('locale'):
            locale_path = os.path.abspath('locale')
            if locale_path not in self.locale_paths:
                self.locale_paths.append(locale_path)
        if self.locale_paths:
            self.default_locale_path = self.locale_paths[0]
            os.makedirs(self.default_locale_path, exist_ok=True)
    looks_like_locale = re.compile('[a-z]{2}')
    locale_dirs = filter(os.path.isdir, glob.glob('%s/*' % self.default_locale_path))
    all_locales = [lang_code for lang_code in map(os.path.basename, locale_dirs) if looks_like_locale.match(lang_code)]
    if process_all:
        locales = all_locales
    else:
        locales = locale or all_locales
        locales = set(locales).difference(exclude)
    if locales:
        check_programs('msguniq', 'msgmerge', 'msgattrib')
    check_programs('xgettext')
    try:
        potfiles = self.build_potfiles()
        for locale in locales:
            if not is_valid_locale(locale):
                match = re.match('^(?P<language>[a-zA-Z]+)(?P<separator>[^a-zA-Z])(?P<territory>.+)$', locale)
                if match:
                    locale_parts = match.groupdict()
                    language = locale_parts['language'].lower()
                    territory = locale_parts['territory'][:2].upper() + locale_parts['territory'][2:]
                    proposed_locale = f'{language}_{territory}'
                else:
                    proposed_locale = locale.lower()
                if is_valid_locale(proposed_locale):
                    self.stdout.write('invalid locale %s, did you mean %s?' % (locale, proposed_locale))
                else:
                    self.stdout.write('invalid locale %s' % locale)
                continue
            if self.verbosity > 0:
                self.stdout.write('processing locale %s' % locale)
            for potfile in potfiles:
                self.write_po_file(potfile, locale)
    finally:
        if not self.keep_pot:
            self.remove_potfiles()

def _validate_compile(self, optimizer, metrics, **kwargs):
    """Performs validation checks for the default `compile`."""
    if any((isinstance(opt, optimizer_v1.Optimizer) for opt in nest.flatten(optimizer))):
        raise ValueError('`tf.compat.v1.keras` Optimizer (', optimizer, ') is not supported when eager execution is enabled. Use a `tf.keras` Optimizer instead, or disable eager execution.')
    kwargs.pop('cloning', None)
    kwargs.pop('experimental_run_tf_function', None)
    if kwargs.pop('distribute', None) is not None:
        raise ValueError('Distribute argument in compile is not available in TF 2.0 please create the model under the distribution strategy scope.')
    if kwargs.pop('target_tensors', None) is not None:
        raise ValueError('target_tensors argument is not supported when executing eagerly.')
    invalid_kwargs = set(kwargs) - {'sample_weight_mode'}
    if invalid_kwargs:
        raise TypeError('Invalid keyword argument(s) in `compile`: %s' % (invalid_kwargs,))
    if self.built and distribute_lib.has_strategy():
        strategy = distribute_lib.get_strategy()
        for v in self.variables:
            if <MASK>:
                raise ValueError('Variable (%s) was not created in the distribution strategy scope of (%s). It is most likely due to not all layers or the model or optimizer being created outside the distribution strategy scope. Try to make sure your code looks similar to the following.\nwith strategy.scope():\n  model=_create_model()\n  model.compile(...)' % (v, strategy))
    strategy = self.distribute_strategy
    for metric in nest.flatten(metrics):
        for v in getattr(metric, 'variables', []):
            if not strategy.extended.variable_created_in_scope(v):
                raise ValueError('Metric (%s) passed to model.compile was created inside of a different distribution strategy scope than the model. All metrics must be created in the same distribution strategy scope as the model (in this case %s). If you pass in a string identifier for a metric to compile the metric will automatically be created in the correct distribution strategy scope.' % (metric, strategy))
    for opt in nest.flatten(optimizer):
        for v in getattr(opt, '_weights', []):
            if not strategy.extended.variable_created_in_scope(v):
                raise ValueError('Optimizer (%s) passed to model.compile was created inside of a different distribution strategy scope than the model. All optimizers must be created in the same distribution strategy scope as the model (in this case %s). If you pass in a string identifier for an optimizer to compile the optimizer will automatically be created in the correct distribution strategy scope.' % (opt, strategy))

def check_memory_pool(device: int, pool_id: tuple[int, int], live_storages_ptrs: list[StorageWeakRefWrapper]) -> None:
    assert all((isinstance(elem, StorageWeakRefWrapper) for elem in live_storages_ptrs))
    unique_storages = {stor.data_ptr() for stor in live_storages_ptrs if stor()}
    if torch._C._cuda_checkPoolLiveAllocations(device, pool_id, unique_storages):
        return
    gc.collect()
    torch.cuda.synchronize()
    segments = get_cudagraph_segments(pool_id)
    allocated_not_in_live_storages = {}
    for segment in segments:
        addr = segment['address']
        for block in segment['blocks']:
            if block['state'] == 'active_allocated':
                if addr not in unique_storages:
                    allocated_not_in_live_storages[addr] = block
                else:
                    unique_storages.remove(addr)
            addr += block['size']
    torch._check(len(unique_storages) == 0, lambda : f'These storage data ptrs are not allocated in pool {pool_id} but should be {unique_storages}')
    if <MASK>:
        formatted = []
        for (dp, block) in allocated_not_in_live_storages.items():
            trace = format_tb(block.get('frames', []))
            formatted.append(f'Data Pointer: {dp}, history: \n{trace}')
        formatted_s = '\n'.join(formatted)
        msg = f'These live storage data ptrs are in the cudagraph pool but not accounted for as an output of cudagraph trees: \n\n{formatted_s}'
        raise RuntimeError(msg)

def on_epoch_end(self, epoch, logs=None):
    if logs is not None:
        for k in self.params['metrics']:
            if k in self.totals:
                if <MASK>:
                    logs[k] = self.totals[k]
                else:
                    logs[k] = self.totals[k] / self.seen

@classmethod
def _box_pa_scalar(cls, value, pa_type: pa.DataType | None=None) -> pa.Scalar:
    """
        Box value into a pyarrow Scalar.

        Parameters
        ----------
        value : any
        pa_type : pa.DataType | None

        Returns
        -------
        pa.Scalar
        """
    if isinstance(value, pa.Scalar):
        pa_scalar = value
    elif <MASK>:
        pa_scalar = pa.scalar(None, type=pa_type)
    else:
        if isinstance(value, Timedelta):
            if pa_type is None:
                pa_type = pa.duration(value.unit)
            elif value.unit != pa_type.unit:
                value = value.as_unit(pa_type.unit)
            value = value._value
        elif isinstance(value, Timestamp):
            if pa_type is None:
                pa_type = pa.timestamp(value.unit, tz=value.tz)
            elif value.unit != pa_type.unit:
                value = value.as_unit(pa_type.unit)
            value = value._value
        pa_scalar = pa.scalar(value, type=pa_type)
    if pa_type is not None and pa_scalar.type != pa_type:
        pa_scalar = pa_scalar.cast(pa_type)
    return pa_scalar

def __init__(self, input_shape, filter_shape, padding, data_format=None, strides=None, name=None, num_batch_dims=1):
    if input_shape.ndims is not None:
        filter_shape = filter_shape.with_rank(input_shape.ndims - num_batch_dims + 1)
    self.padding = padding
    self.name = name
    if filter_shape.ndims is not None:
        input_shape = input_shape.with_rank(filter_shape.ndims + num_batch_dims - 1)
    if input_shape.ndims is None:
        raise ValueError(f'Rank of convolution must be known. Received: input_shape={input_shape} of rank {input_shape.rank}')
    if input_shape.ndims < 3 or input_shape.ndims - num_batch_dims + 1 > 5:
        raise ValueError(f'`input_shape.rank - num_batch_dims + 1` must be at least 3 and at most 5. Received: input_shape.rank={input_shape.rank} and num_batch_dims={num_batch_dims}')
    conv_dims = input_shape.ndims - num_batch_dims - 1
    if strides is None:
        strides = [1] * conv_dims
    elif len(strides) != conv_dims:
        raise ValueError(f'`len(strides)` should be {conv_dims}. Received: strides={strides} of length {len(strides)}')
    if conv_dims == 1:
        if <MASK>:
            data_format = 'NWC'
        elif data_format not in {'NCW', 'NWC', 'NCHW', 'NHWC'}:
            raise ValueError(f"`data_format` must be 'NWC' or 'NCW'. Received: data_format={data_format}")
        self.strides = strides[0]
        self.data_format = data_format
        self.conv_op = self._conv1d
    elif conv_dims == 2:
        if data_format is None or data_format == 'NHWC':
            data_format = 'NHWC'
            strides = [1] + list(strides) + [1]
        elif data_format == 'NCHW':
            strides = [1, 1] + list(strides)
        else:
            raise ValueError(f"`data_format` must be 'NHWC' or 'NCHW'. Received: data_format={data_format}")
        self.strides = strides
        self.data_format = data_format
        self.conv_op = conv2d
    elif conv_dims == 3:
        if data_format is None or data_format == 'NDHWC':
            strides = [1] + list(strides) + [1]
        elif data_format == 'NCDHW':
            strides = [1, 1] + list(strides)
        else:
            raise ValueError(f"`data_format` must be 'NDHWC' or 'NCDHW'. Received: data_format={data_format}")
        self.strides = strides
        self.data_format = data_format
        self.conv_op = _conv3d_expanded_batch

def call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if inspect.getattr_static(self.value, '_torchdynamo_disable', False):
        msg = inspect.getattr_static(self.value, '_torchdynamo_disable_msg', None)
        unimplemented_v2(gb_type='Skip calling `torch.compiler.disable()`d function', context=str(self.value), explanation=f'Skip calling function `{self.value}` since it was wrapped with `torch.compiler.disable` (reason: {msg})', hints=['Remove the `torch.compiler.disable` call'])
    elif self.value is torch._dynamo.graph_break:
        graph_break_msg = kwargs.get('msg', None)
        if graph_break_msg:
            graph_break_msg = graph_break_msg.as_python_constant()
        unimplemented_v2(gb_type='Call to `torch._dynamo.graph_break()`', context=f'Called `torch._dynamo.graph_break()` with args `{args}`, kwargs `{kwargs}`', explanation=f'User-inserted graph break. Message: {graph_break_msg}', hints=['Remove the `torch._dynamo.graph_break()` call.'])
    elif self.value is torch._dynamo.skip_frame:
        skip_frame_msg = kwargs.get('msg', None)
        if skip_frame_msg:
            skip_frame_msg = skip_frame_msg.as_python_constant()
        raise SkipFrame(f'Skip frame due to `torch._dynamo.skip_frame()`. Message: {skip_frame_msg}')
    elif self.value is torch._dynamo.step_unsupported:
        raise StepUnsupported
    else:
        if config.dont_skip_tracing:
            from .builder import SourcelessBuilder
            rebuilt_fn = SourcelessBuilder.create(tx, self.value)
            if not isinstance(rebuilt_fn, SkipFunctionVariable):
                return rebuilt_fn.call_function(tx, args, kwargs)
        qualname = getattr(self.value, '__qualname__', '<unknown qualname>')
        module_or = getattr(self.value, '__module__', None)
        module_name = '<unknown module>' if module_or is None else str(module_or)
        try:
            path = inspect.getfile(self.value)
            explanation = f'Dynamo developers have intentionally marked that the function `{qualname}` in file `{path}` should not be traced.'
            hints = [f'Avoid calling the function `{qualname}`.']
            if '_dynamo' not in path:
                hints += [f'Apply `@torch._dynamo.dont_skip_tracing` to the function `{qualname}` to force tracing into the function. More graph breaks may occur as a result of attempting to trace into the function.', 'Please file an issue to PyTorch.']
        except TypeError:
            known_python_builtin_modules = {'_abc', '_warnings'}
            if module_or in known_python_builtin_modules:
                explanation = f'Dynamo does not know how to trace the Python builtin `{module_name}.{qualname}`.'
                hints = ['If you are attempting to call a logging function (e.g. `_warnings.warn`), you can try adding it to `torch._dynamo.config.reorderable_logging_functions`.', 'Please file an issue on GitHub so the PyTorch team can add support for it. ']
            elif <MASK>:
                explanation = f'Dynamo cannot trace optree C/C++ function {module_name}.{qualname}.'
                hints = [' Consider using torch.utils._pytree - https://github.com/pytorch/pytorch/blob/main/torch/utils/_pytree.py']
                torch._dynamo.utils.warn_once(explanation + '\n' + '\n'.join(hints))
            else:
                explanation = f'Dynamo does not know how to trace the builtin `{module_name}.{qualname}.` This function is either a Python builtin (e.g. _warnings.warn) or a third-party C/C++ Python extension (perhaps created with pybind).'
                hints = ['If it is a Python builtin, please file an issue on GitHub so the PyTorch team can add support for it and see the next case for a workaround.', 'If it is a third-party C/C++ Python extension, please either wrap it into a PyTorch-understood custom operator (see https://pytorch.org/tutorials/advanced/custom_ops_landing_page.html for more details) or, if it is traceable, use `torch.compiler.allow_in_graph`.']
                torch._dynamo.utils.warn_once(explanation + '\n' + '\n'.join(hints))
        if qualname == 'allow_in_graph':
            explanation = 'Found an allow_in_graph decorator to a function which is created inside the parent function that is getting compiled. This is not supported for now.'
            hints = []
        reason = self.reason if self.reason else '<missing reason>'
        unimplemented_v2(gb_type='Attempted to call function marked as skipped', context=f'module: {module_name}, qualname: {qualname}, skip reason: {reason}', explanation=explanation, hints=hints)

@register_inference_rule(operator.mul)
@register_inference_rule(torch.ne)
@register_inference_rule('ne')
@register_inference_rule(torch.add)
@register_inference_rule(operator.add)
def broadcasting_inference_rule(n: Node, symbols, constraints, counter):
    op_code = None
    if <MASK>:
        op_code = op_add
    elif n.target == operator.mul:
        op_code = op_mul
    if isinstance(n.args[0], Node) and isinstance(n.args[1], Node):
        if isinstance(symbols[n.args[0]], TVar) and isinstance(symbols[n.args[1]], TVar):
            (my_output, counter) = gen_tvar(counter)
            symbols[n] = my_output
            e1 = symbols[n.args[0]]
            e2 = symbols[n.args[1]]
            return gen_broadcasting_constraints(e1, e2, symbols, counter, my_output)
        else:
            raise NotImplementedError('Method not yet implemented')
    elif isinstance(n.args[0], Node) and isinstance(n.args[1], (int, float)):
        if isinstance(symbols[n.args[0]], TVar):
            (my_output, counter) = gen_tvar(counter)
            symbols[n] = my_output
            e1 = symbols[n.args[0]]
            return ([BinConstraintT(my_output, e1, op_eq)], counter)
        elif isinstance(symbols[n.args[0]], DVar):
            (my_output, counter) = gen_dvar(counter)
            symbols[n] = my_output
            e1 = symbols[n.args[0]]
            c = Conj([BinConstraintD(my_output, BinConstraintD(e1, n.args[1], op_code), op_eq), BinConstraintD(0, my_output, op_leq)])
            return ([c], counter)
    elif isinstance(n.args[1], Node) and isinstance(n.args[0], (int, float)):
        if isinstance(symbols[n.args[1]], TVar):
            (my_output, counter) = gen_tvar(counter)
            symbols[n] = my_output
            e2 = symbols[n.args[1]]
            return ([BinConstraintT(my_output, e2, op_eq)], counter)
        elif isinstance(symbols[n.args[1]], DVar):
            (my_output, counter) = gen_dvar(counter)
            symbols[n] = my_output
            e2 = symbols[n.args[1]]
            c = Conj([BinConstraintD(my_output, BinConstraintD(e2, n.args[0], op_code), op_eq), BinConstraintD(0, my_output, op_leq)])
            return ([c], counter)
        else:
            raise NotImplementedError('Method not yet implemented')
    else:
        raise NotImplementedError('Addition not yet implemented')

def compute_batch_size(*args, **kwargs):
    args_and_kwargs = pytree.arg_tree_leaves(*args, **kwargs)
    batch_size = None
    for arg in args_and_kwargs:
        if <MASK>:
            continue
        arg_batch_size = arg.shape[0] if batch_first else arg.shape[1]
        if batch_size is not None and batch_size != arg_batch_size:
            raise RuntimeError(f'When computing batch size, found at least one input with batch size {batch_size} and one with batch size {arg_batch_size}. Please specify it explicitly using the batch size kwarg in call_for_per_sample_grads')
        batch_size = arg_batch_size
    if batch_size is None:
        raise RuntimeError('Unable to find a tensor in the passed args and kwargs. They may not be pytree-able and so ExpandedWeights cannot compute the batch size from the inputs. Please specify it explicitly')
    return batch_size

def validate_data_columns(self, data_columns, min_itemsize, non_index_axes) -> list:
    """
        take the input data_columns and min_itemize and create a data
        columns spec
        """
    if not len(non_index_axes):
        return []
    (axis, axis_labels) = non_index_axes[0]
    info = self.info.get(axis, {})
    if <MASK>:
        raise ValueError(f'cannot use a multi-index on axis [{axis}] with data_columns {data_columns}')
    if data_columns is True:
        data_columns = list(axis_labels)
    elif data_columns is None:
        data_columns = []
    if isinstance(min_itemsize, dict):
        existing_data_columns = set(data_columns)
        data_columns = list(data_columns)
        data_columns.extend([k for k in min_itemsize.keys() if k != 'values' and k not in existing_data_columns])
    return [c for c in data_columns if c in axis_labels]

def m_fn(m, d):
    if isinstance(m, torch.nn.Linear):
        return MkldnnLinear(m, d)
    elif isinstance(m, torch.nn.Conv1d):
        return MkldnnConv1d(m, d)
    elif isinstance(m, torch.nn.Conv2d):
        return MkldnnConv2d(m, d)
    elif isinstance(m, torch.nn.Conv3d):
        return MkldnnConv3d(m, d)
    elif <MASK>:
        return MkldnnBatchNorm(m)
    elif isinstance(m, torch.nn.PReLU):
        return MkldnnPrelu(m, d)
    else:
        return m

def generate_input_output_runtime_checks(self):
    """
        In debug_compile mode, we generate checks to ensure the dtype/shape/stride/device of each
        real input/output tensor match ones provided at compile time via sample
        input/output.
        """

    def gen_check(handle_kind, idx, name, tensor):
        self.prefix.writeline(f'ConstantHandle {name} = ConstantHandle({handle_kind}[{idx}]);')
        self.codegen_tensor_dtype_var_decl(self.prefix, name)
        expected_dtype_name = DTYPE_TO_ATEN[tensor.dtype]
        dtype_str = str(tensor.dtype).split('.')[-1]
        self.prefix.splice(f'
                    int32_t {name}_expected_dtype = aoti_torch_dtype_{dtype_str}();
                    if ({name}_expected_dtype != {name}_dtype) {{
                        std::stringstream ss;
                        ss << "{handle_kind}[{idx}]: unmatched dtype, "
                           << "expected: " << {name}_expected_dtype << "({expected_dtype_name}), "
                           << "but got: " << {name}_dtype << "\n";
                        throw std::runtime_error(ss.str());
                    }}
                ')
        self.codegen_input_size_var_decl(self.prefix, name)
        for (dim_idx, d) in enumerate(tensor.get_size()):
            if isinstance(d, (int, sympy.Integer)):
                self.prefix.splice(f'
                            if ({d} != {name}_size[{dim_idx}]) {{
                                std::stringstream ss;
                                ss << "{handle_kind}[{idx}]: unmatched dim value at {dim_idx}, "
                                   << "expected: {d}, " << "but got: " << {name}_size[{dim_idx}]
                                   << "\n";
                                throw std::runtime_error(ss.str());
                            }}
                        ')
            else:
                from torch.utils._sympy.value_ranges import bound_sympy
                sym_range = bound_sympy(d, V.graph.sizevars.shape_env.var_to_range)
                if not math.isinf(sym_range.lower):
                    self.prefix.splice(f'
                                if ({name}_size[{dim_idx}] < {sym_range.lower}) {{
                                    std::stringstream ss;
                                    ss << "{handle_kind}[{idx}]: dim value is too small at {dim_idx}, "
                                       << "expected it to be >= {sym_range.lower}, " << "but got: "
                                       << {name}_size[{dim_idx}] << "\n";
                                    throw std::runtime_error(ss.str());
                                }}
                            ')
                if <MASK>:
                    max_long_long = ctypes.c_longlong(2 ** 63 - 1).value
                    upper_bound = min(sym_range.upper, max_long_long)
                    self.prefix.splice(f'
                                if ({name}_size[{dim_idx}] > {upper_bound}) {{
                                    std::stringstream ss;
                                    ss << "{handle_kind}[{idx}]: dim value is too large at {dim_idx}, "
                                       << "expected to be <= {upper_bound}, " << "but got: "
                                       << {name}_size[{dim_idx}] << "\n";
                                    throw std::runtime_error(ss.str());
                                }}
                            ')
        self.codegen_input_stride_var_decl(self.prefix, name)
        for (stride_idx, s) in enumerate(tensor.get_stride()):
            if not isinstance(s, (int, sympy.Integer)):
                continue
            self.prefix.splice(f'
                        if ({s} != {name}_stride[{stride_idx}]) {{
                            std::stringstream ss;
                            ss << "{handle_kind}[{idx}]: unmatched stride value at {stride_idx}, "
                               << "expected: {s}, " << "but got: " << {name}_stride[{stride_idx}]
                               << "\n";
                            throw std::runtime_error(ss.str());
                        }}
                    ')
        if isinstance(tensor, ir.TensorBox):
            tensor_device = tensor.get_device()
            if tensor_device is not None:
                expected_device_type = DEVICE_TO_INT.get(tensor_device.type)
                if expected_device_type is not None:
                    self.codegen_input_device_type_var_decl(self.prefix, name)
                    device_type_str = str(tensor_device.type)
                    self.prefix.splice(f'
                                int32_t {name}_expected_device_type = {expected_device_type};
                                if ({name}_expected_device_type != {name}_device_type) {{
                                    std::stringstream ss;
                                    ss << "{handle_kind}[{idx}]: unmatched device type, "
                                    << "expected: " << {name}_expected_device_type << "{expected_device_type}({device_type_str}), "
                                    << "but got: " << {name}_device_type << "\n";
                                    throw std::runtime_error(ss.str());
                                }}
                            ')
    for (idx, (name, tensor)) in enumerate(V.graph.graph_inputs.items()):
        self.prefix.splice(f'
                AOTI_NOINLINE static void check_input_{idx}(
                    AtenTensorHandle* input_handles
                ) {{
                ')
        with self.prefix.indent():
            gen_check('input_handles', idx, name, tensor)
        self.prefix.writeline('}')
    self.prefix.splice('
            static bool _check_aoti_runtime_check_inputs_env() {
                const static char* env_var_value = getenv("AOTI_RUNTIME_CHECK_INPUTS");
                const static bool result = env_var_value != nullptr && env_var_value[0] != '0';
                return result;
            }

            AOTI_NOINLINE static void __check_inputs_outputs(
                AtenTensorHandle* input_handles,
                AtenTensorHandle* output_handles) {
                if (!_check_aoti_runtime_check_inputs_env()){
                    return;
                }
            ')
    with self.prefix.indent():
        for idx in range(len(V.graph.graph_inputs)):
            self.prefix.writeline(f'check_input_{idx}(input_handles);')
    self.prefix.writeline('}')

def _get_dtype_and_is_dynamic(obs_or_fq: Optional[ObserverOrFakeQuantize]) -> tuple[Optional[torch.dtype], bool]:
    """Given a constructor for observer or fake quant module, returns
    a Tuple of dtype and is_dynamic
    """
    if <MASK>:
        return (None, False)
    else:
        return (obs_or_fq.dtype, getattr(obs_or_fq, 'is_dynamic', False))

def get_flex_attn_bwd_configs(self, head_dim: int, dtype: Any) -> list[FlexBwDConfig]:
    flex_attn_bwd_configs: list[FlexBwDConfig] = []
    if <MASK>:
        if config.max_autotune_flex_search_space == 'EXHAUSTIVE':
            return self.exhaustive_flex_attn_bwd_configs
        flex_attn_bwd_configs += self.flex_attn_bwd_autotune_configs
    if dtype == torch.float32:
        default_config = ROCmFlexBwDConfig(16, 16, 16, 16, 1, 4)
    elif head_dim <= 256:
        if head_dim == 64:
            default_config = ROCmFlexBwDConfig(64, 64, 64, 64, 1, 4)
        elif head_dim == 128:
            default_config = ROCmFlexBwDConfig(64, 128, 128, 64, 1, 8)
        else:
            default_config = ROCmFlexBwDConfig(64, 64, 64, 64, 1, 4)
    else:
        default_config = ROCmFlexBwDConfig(16, 16, 16, 16, 1, 4)
    if default_config not in flex_attn_bwd_configs:
        flex_attn_bwd_configs.append(default_config)
    return flex_attn_bwd_configs

def __new__(subtype, filename, dtype=uint8, mode='r+', offset=0, shape=None, order='C'):
    import mmap
    import os.path
    try:
        mode = mode_equivalents[mode]
    except KeyError as e:
        if mode not in valid_filemodes:
            all_modes = valid_filemodes + list(mode_equivalents.keys())
            raise ValueError(f'mode must be one of {all_modes!r} (got {mode!r})') from None
    if <MASK>:
        raise ValueError("shape must be given if mode == 'w+'")
    if hasattr(filename, 'read'):
        f_ctx = nullcontext(filename)
    else:
        f_ctx = open(os.fspath(filename), ('r' if mode == 'c' else mode) + 'b')
    with f_ctx as fid:
        fid.seek(0, 2)
        flen = fid.tell()
        descr = dtypedescr(dtype)
        _dbytes = descr.itemsize
        if shape is None:
            bytes = flen - offset
            if bytes % _dbytes:
                raise ValueError('Size of available data is not a multiple of the data-type size.')
            size = bytes // _dbytes
            shape = (size,)
        else:
            if not isinstance(shape, (tuple, list)):
                try:
                    shape = [operator.index(shape)]
                except TypeError:
                    pass
            shape = tuple(shape)
            size = np.intp(1)
            for k in shape:
                size *= k
        bytes = int(offset + size * _dbytes)
        if mode in ('w+', 'r+'):
            bytes = max(bytes, 1)
            if flen < bytes:
                fid.seek(bytes - 1, 0)
                fid.write(b'\x00')
                fid.flush()
        if mode == 'c':
            acc = mmap.ACCESS_COPY
        elif mode == 'r':
            acc = mmap.ACCESS_READ
        else:
            acc = mmap.ACCESS_WRITE
        start = offset - offset % mmap.ALLOCATIONGRANULARITY
        bytes -= start
        if bytes == 0 and start > 0:
            bytes += mmap.ALLOCATIONGRANULARITY
            start -= mmap.ALLOCATIONGRANULARITY
        array_offset = offset - start
        mm = mmap.mmap(fid.fileno(), bytes, access=acc, offset=start)
        self = ndarray.__new__(subtype, shape, dtype=descr, buffer=mm, offset=array_offset, order=order)
        self._mmap = mm
        self.offset = offset
        self.mode = mode
        if isinstance(filename, os.PathLike):
            self.filename = filename.resolve()
        elif hasattr(fid, 'name') and isinstance(fid.name, str):
            self.filename = os.path.abspath(fid.name)
        else:
            self.filename = None
    return self

def legacy_get_string(size_average: Optional[bool], reduce: Optional[bool], emit_warning: bool=True) -> str:
    warning = "size_average and reduce args will be deprecated, please use reduction='{}' instead."
    if size_average is None:
        size_average = True
    if reduce is None:
        reduce = True
    if <MASK>:
        ret = 'mean'
    elif reduce:
        ret = 'sum'
    else:
        ret = 'none'
    if emit_warning:
        warnings.warn(warning.format(ret))
    return ret

def apply_var_mapping(iter_vars: list[sympy.Symbol], red_vars: list[sympy.Symbol], norm_pw_vars: list[sympy.Symbol], norm_red_vars: list[sympy.Symbol], new_ranges: list[list[sympy.Expr]], return_getters_groups: list[list[Callable[[list[sympy.Expr]], sympy.Expr]]]) -> dict[sympy.Symbol, sympy.Expr]:
    """Maps original variables to expressions using normalized variables."""
    num_vars = sum((len(s) for s in new_ranges))
    flat_vars = sympy.symbols(f'v_0:{num_vars}')
    count = 0
    if len(iter_vars) == 0 and len(red_vars) == 0:
        return {}
    assert len(new_ranges) == len(norm_pw_vars + norm_red_vars)
    apply_groups = []
    for group in return_getters_groups:
        apply_groups.append([g(flat_vars) for g in group])
    iter_vars_to_flat_vars = {}
    for (i, (group, var_group)) in enumerate(zip(apply_groups, (iter_vars, red_vars), strict=True)):
        if <MASK>:
            assert i == 1
            assert len(var_group) == 0
            continue
        iter_vars_to_flat_vars.update({v: g for (g, v) in zip(group, var_group)})
    count = 0
    flat_vars_to_new_vars = {}
    for (new_range, new_var) in zip(new_ranges, norm_pw_vars + norm_red_vars, strict=True):
        range_vars = []
        for i in range(len(new_range)):
            range_vars.append(flat_vars[count])
            count += 1
        prod = 1
        for i in range(len(new_range) - 1, -1, -1):
            flat_vars_to_new_vars[range_vars[i]] = new_var * prod
            prod = new_range[i] * prod
    return {k: sympy_subs(v, flat_vars_to_new_vars) for (k, v) in iter_vars_to_flat_vars.items()}

def _safe_repr(object, context, maxlevels, level, changed_only=False):
    """Same as the builtin _safe_repr, with added support for Estimator
    objects."""
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if issubclass(typ, dict) and r is dict.__repr__:
        if not object:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if issubclass(typ, list) and r is list.__repr__ or (issubclass(typ, tuple) and r is tuple.__repr__):
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            (orepr, oreadable, orecur) = _safe_repr(o, context, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if <MASK>:
                readable = False
            if orecur:
                recursive = True
        del context[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

@test_util.run_in_graph_and_eager_modes
def testScalarStateIsAccepted(self):
    cell = ScalarStateRNNCell()
    in_eager_mode = context.executing_eagerly()
    if <MASK>:
        inputs = np.array([[[1], [2], [3], [4]]], dtype=np.float32)
    else:
        inputs = array_ops.placeholder(dtypes.float32, shape=(1, 4, 1))
    with self.cached_session() as sess:
        (outputs, state) = rnn.dynamic_rnn(cell, inputs, dtype=dtypes.float32, sequence_length=[4])
        if not in_eager_mode:
            (outputs, state) = sess.run([outputs, state], feed_dict={inputs: [[[1], [2], [3], [4]]]})
    self.assertAllEqual([[[1], [2], [3], [4]]], outputs)
    self.assertAllEqual(4, state)

def node_ctor_arg_rvalue_string(arg: LazyArgument) -> str:
    """
    Given a LazyArgument,
    generate a c++ string for materializing an rvalue of that arg for passing into
    a lazy Node constructor.
    """
    if <MASK>:
        if isinstance(arg.lazy_type, BaseCType):
            if arg.is_wrapped_scalar:
                return f'node_{arg.name}'
            elif arg.lazy_type.type is tensorListValueT:
                return f'lazy_{arg.name}_tensorlist'
            elif arg.is_symint_or_list:
                return f'GetSymIntValue({arg.name})'
            return f'lazy_{arg.name}->GetIrValue()'
        elif isinstance(arg.lazy_type, OptionalCType):
            if arg.is_symint_or_list:
                return f'{arg.name} ? std::make_optional(GetSymIntValue(*{arg.name})) : ::std::nullopt'
            elif arg.is_wrapped_scalar:
                return f'node_{arg.name}'
            return f'lazy_{arg.name} ? std::make_optional(lazy_{arg.name}->GetIrValue()) : ::std::nullopt'
        else:
            raise AssertionError(f'TODO not sure if there are other valid types to handle here ({arg.lazy_type})')
    elif isinstance(arg.orig_type, ListType) and arg.orig_type.elem == BaseType(BaseTy.SymInt):
        if arg.symint:
            return f'GetSymIntArrayRefValue({arg.name})'
        else:
            return f'std::vector<int64_t>({arg.name}.begin(), {arg.name}.end())'
    elif isinstance(arg.lazy_type, VectorCType) and isinstance(arg.lazy_type.elem, BaseCType):
        return f'std::vector<{arg.lazy_type.elem.type}>({arg.name}.begin(), {arg.name}.end())'
    elif isinstance(arg.lazy_type, OptionalCType) and isinstance(arg.lazy_type.elem, VectorCType) and isinstance(arg.lazy_type.elem.elem, BaseCType):
        return f'torch::lazy::ToOptionalVector<{arg.lazy_type.elem.elem.type}>({arg.name})'
    else:
        return f'{arg.name}'

def _get_restore_location(map_location):
    if map_location is None:
        restore_location = default_restore_location
    elif isinstance(map_location, dict):

        def restore_location(storage, location):
            location = map_location.get(location, location)
            return default_restore_location(storage, location)
    elif isinstance(map_location, (str, bytes)):

        def restore_location(storage, location):
            return default_restore_location(storage, map_location)
    elif isinstance(map_location, torch.device):

        def restore_location(storage, location):
            return default_restore_location(storage, str(map_location))
    else:

        def restore_location(storage, location):
            result = map_location(storage, location)
            if <MASK>:
                result = default_restore_location(storage, location)
            return result
    return restore_location

def _call_impl(self, *args, **kwargs):
    forward_call = self._slow_forward if torch._C._get_tracing_state() else self.forward
    if <MASK>:
        return forward_call(*args, **kwargs)
    result = None
    called_always_called_hooks = set()

    def inner():
        nonlocal result, args, kwargs
        (full_backward_hooks, non_full_backward_hooks) = ([], [])
        backward_pre_hooks = []
        if self._backward_pre_hooks or _global_backward_pre_hooks:
            backward_pre_hooks = self._get_backward_pre_hooks()
        if self._backward_hooks or _global_backward_hooks:
            (full_backward_hooks, non_full_backward_hooks) = self._get_backward_hooks()
        if _global_forward_pre_hooks or self._forward_pre_hooks:
            for (hook_id, hook) in (*_global_forward_pre_hooks.items(), *self._forward_pre_hooks.items()):
                if hook_id in self._forward_pre_hooks_with_kwargs:
                    args_kwargs_result = hook(self, args, kwargs)
                    if args_kwargs_result is not None:
                        if isinstance(args_kwargs_result, tuple) and len(args_kwargs_result) == 2:
                            (args, kwargs) = args_kwargs_result
                        else:
                            raise RuntimeError(f'forward pre-hook must return None or a tuple of (new_args, new_kwargs), but got {args_kwargs_result}.')
                else:
                    args_result = hook(self, args)
                    if args_result is not None:
                        if not isinstance(args_result, tuple):
                            args_result = (args_result,)
                        args = args_result
        bw_hook = None
        if full_backward_hooks or backward_pre_hooks:
            bw_hook = BackwardHook(self, full_backward_hooks, backward_pre_hooks)
            args = bw_hook.setup_input_hook(args)
        result = forward_call(*args, **kwargs)
        if _global_forward_hooks or self._forward_hooks:
            for (hook_id, hook) in (*_global_forward_hooks.items(), *self._forward_hooks.items()):
                if hook_id in self._forward_hooks_always_called or hook_id in _global_forward_hooks_always_called:
                    called_always_called_hooks.add(hook_id)
                if hook_id in self._forward_hooks_with_kwargs or hook_id in _global_forward_hooks_with_kwargs:
                    hook_result = hook(self, args, kwargs, result)
                else:
                    hook_result = hook(self, args, result)
                if hook_result is not None:
                    result = hook_result
        if bw_hook:
            if not isinstance(result, (torch.Tensor, tuple)):
                warnings.warn(f'For backward hooks to be called, module output should be a Tensor or a tuple of Tensors but received {type(result)}')
            result = bw_hook.setup_output_hook(result)
        if non_full_backward_hooks:
            var = result
            while not isinstance(var, torch.Tensor):
                if isinstance(var, dict):
                    var = next((v for v in var.values() if isinstance(v, torch.Tensor)))
                else:
                    var = var[0]
            grad_fn = var.grad_fn
            if grad_fn is not None:
                for hook in non_full_backward_hooks:
                    grad_fn.register_hook(_WrappedHook(hook, self))
                self._maybe_warn_non_full_backward_hook(args, result, grad_fn)
        return result
    if torch.compiler.is_compiling():
        return inner()
    try:
        return inner()
    except Exception:
        for (hook_id, hook) in _global_forward_hooks.items():
            if hook_id in _global_forward_hooks_always_called and hook_id not in called_always_called_hooks:
                try:
                    hook_result = hook(self, args, result)
                    if hook_result is not None:
                        result = hook_result
                except Exception as e:
                    warnings.warn(f'global module forward hook with ``always_call=True`` raised an exception that was silenced as another error was raised in forward: {str(e)}')
                    continue
        for (hook_id, hook) in self._forward_hooks.items():
            if hook_id in self._forward_hooks_always_called and hook_id not in called_always_called_hooks:
                try:
                    if hook_id in self._forward_hooks_with_kwargs:
                        hook_result = hook(self, args, kwargs, result)
                    else:
                        hook_result = hook(self, args, result)
                    if hook_result is not None:
                        result = hook_result
                except Exception as e:
                    warnings.warn(f'module forward hook with ``always_call=True`` raised an exception that was silenced as another error was raised in forward: {str(e)}')
                    continue
        raise

def _process_constant(self, node: ast.Constant) -> None:
    """Process top-level constant for a potential API docstring export."""
    if isinstance(node.value, str):
        (docstring, modules) = self._extract_docstring(node.value)
        if <MASK>:
            self._exports.add_doc(exported_api.ExportedDoc.create(file_name=self._current_file, line_no=node.lineno, modules=modules, docstring=docstring))
        else:
            self.visit(node)

def indexing_to_dimensions(self, var: str, index: sympy.Expr, is_store: bool):
    """Convert address-based indexing into dimensions using self.halide_vars"""
    symbols = []
    for sym in sorted(index.free_symbols, key=lambda x: x.name):
        if symbol_is_type(sym, (SymT.HALIDE, SymT.TMP)):
            symbols.append(sym)
        else:
            assert symbol_is_type(sym, (SymT.UNBACKED_INT, SymT.SIZE, SymT.PRECOMPUTED_SIZE)), sym
    offset = sympy.S.Zero
    split_expr = dict.fromkeys(symbols, sympy.S.Zero)
    split_failed: list[tuple[list[sympy.Symbol], sympy.Expr]] = []
    index = sympy.expand(self.rename_indexing(index))
    for part in index.args if isinstance(index, sympy.Add) else [index]:
        part_vars = [v for v in part.free_symbols if v in split_expr]
        if <MASK>:
            offset += part
        elif len(part_vars) == 1:
            split_expr[part_vars[0]] += part
        else:
            new_split_failed = []
            for i in range(len(split_failed)):
                assert split_failed[i] is not None
                (other_vars, other_part) = split_failed[i]
                if OrderedSet(other_vars) & OrderedSet(part_vars):
                    part_vars.extend([v for v in other_vars if v not in part_vars])
                    part += other_part
                else:
                    new_split_failed.append((other_vars, other_part))
            split_failed = [*new_split_failed, (part_vars, part)]

    def expr_to_dimension(expr, syms):
        expr = sympy.factor(expr)
        if len(syms) == 1:
            stride_wild = sympy.Wild('wild', exclude=symbols)
            m = expr.match(stride_wild * syms[0])
            if m:
                return DimensionInfo(syms[0], self.sym_size(syms[0]), m[stride_wild])
        assert not is_store, expr
        length = sympy.simplify(sympy_subs(expr, {sym: self.sym_size(sym) - 1 for sym in syms}) + 1)
        stride = sympy.S.One
        if isinstance(expr, sympy.Mul):
            for term in expr.args:
                if isinstance(term, sympy.Integer):
                    stride *= term
                    expr = sympy.simplify(expr / term)
                    length = sympy.simplify(sympy.ceiling(length / term))
        return DimensionInfo(expr, length, stride)
    dims = []
    for (syms, expr) in split_failed:
        for v in syms:
            expr += split_expr.pop(v)
        dims.append(expr_to_dimension(expr, syms))
    for (sym, expr) in split_expr.items():
        dims.append(expr_to_dimension(expr, [sym]))
    dims.sort(key=lambda d: V.graph.sizevars.size_hint(d.stride, fallback=inf))
    if not dims:
        if self.has_indirect_indexing:
            dims.append(DimensionInfo(sympy.S.Zero, 1, 1))
    elif not V.graph.sizevars.statically_known_equals(dims[0].stride, 1):
        dims.insert(0, DimensionInfo(sympy.S.Zero, 1 if is_store else dims[0].stride, 1))
    if dims and (not is_store):
        if var in self.buffer_offsets and V.graph.sizevars.statically_known_geq(offset, self.buffer_offsets[var]):
            self.apply_offset_to_dimension(dims, offset - self.buffer_offsets[var])
            offset = self.buffer_offsets[var]
        elif V.graph.sizevars.statically_known_gt(offset, 0):
            self.apply_offset_to_dimension(dims, offset)
            offset = 0
    orig_var = var
    for i in itertools.count():
        if self.install_dims(var, dims, offset, is_store):
            return (var, dims)
        assert not is_store
        var = f'{orig_var}_view{i}'
        if var not in self.buffer_aliases[orig_var]:
            self.buffer_aliases[orig_var].append(var)

def _make_prim(*, schema: str, return_type: Union[RETURN_TYPE, tuple[RETURN_TYPE, ...]], meta: Callable, impl_aten: Callable, doc: str, tags: Optional[Sequence[torch.Tag]]=None, use_old_custom_ops_api: bool=False, register_conj_neg_fallthrough: bool=False):
    """
    Creates a primitive operation.

    """

    def _prim_impl(*args, **kwargs):
        meta(*args, **kwargs)
        return impl_aten(*args, **kwargs)

    def _autograd_impl(*args, **kwargs):
        return backwards_not_supported(_prim)(*args, **kwargs)

    def _backend_select_impl(*args, **kwargs):
        if kwargs.get('device') and kwargs['device'].type == 'meta':
            return meta(*args, **kwargs)
        if any((isinstance(x, torch.device) and x.type == 'meta' for x in args)):
            return meta(*args, **kwargs)
        else:
            return _prim_impl(*args, **kwargs)
    name = schema.split('(', maxsplit=1)[0]
    schema = schema[len(name):]
    cpp_schema = torch._C.parse_schema(name + schema)
    if use_old_custom_ops_api or not is_functional_schema(cpp_schema):
        prim.define(name + schema, tags=torch.Tag.pt2_compliant_tag)
        prim_impl.impl(name, _prim_impl)
        prim_autograd_impl.impl(name, _autograd_impl)
        prim_meta_impl.impl(name, meta)
    else:
        mutates_args = [arg.name for arg in cpp_schema.arguments if arg.alias_info is not None and arg.alias_info.is_write]
        prim_def = torch.library.custom_op('prims::' + name, _prim_impl, mutates_args=tuple(mutates_args), schema=schema)
        prim_def.register_fake(meta)
        if return_type == RETURN_TYPE.VIEW or register_conj_neg_fallthrough:
            prim_def._lib.impl(name, torch.library.fallthrough_kernel, 'Conjugate')
            prim_def._lib.impl(name, torch.library.fallthrough_kernel, 'Negative')
    _prim_packet = getattr(torch._ops.ops.prims, name)
    _prim = _prim_packet.default
    if tags:
        _prim._tags = tags
    elif (aten_packet := getattr(torch.ops.aten, name, None)):
        overload_tags = [getattr(aten_packet, overload).tags for overload in aten_packet.overloads()]
        tags_intersection = set(overload_tags[0])
        tags_intersection.intersection_update(*overload_tags[1:])
        tags_intersection.discard(torch.Tag.core)
        tags_intersection.discard(torch.Tag.data_dependent_output)
        _prim._tags = tuple((t for t in overload_tags[0] if t in tags_intersection))
    from torch._subclasses.fake_tensor import contains_tensor_types
    if <MASK>:
        prim_backend_select_impl.impl(name, _backend_select_impl)
    for p in (_prim_packet, _prim):
        p.__doc__ = doc
        p.return_type = return_type
        p.schema = schema
        p.prim_impl = _prim_impl
        p.prim_meta_impl = meta
        p.impl_aten = impl_aten
    return _prim

def create_init_files(dst_dir: str) -> None:
    """Create __init__.py files."""
    for (root, _, files) in os.walk(dst_dir):
        if <MASK>:
            curr_dir = root
            while curr_dir != dst_dir:
                init_path = os.path.join(curr_dir, '__init__.py')
                if not os.path.exists(init_path):
                    open(init_path, 'w').close()
                curr_dir = os.path.dirname(curr_dir)

def _run(self, handle, fetches, feed_dict, options, run_metadata):
    """Perform either run or partial_run, depending the presence of `handle`."""

    def _feed_fn(feed, feed_val):
        for (tensor_type, _, feed_fn, _) in _REGISTERED_EXPANSIONS:
            if isinstance(feed, tensor_type):
                return feed_fn(feed, feed_val)
        raise TypeError(f'{feed} in argument `feed_dict` has invalid type "{type(feed).__name__}"')
    if self._closed:
        raise RuntimeError('Attempted to use a closed Session.')
    if <MASK>:
        raise RuntimeError('The Session graph is empty. Add operations to the graph before calling run().')
    feed_dict_tensor = {}
    feed_map = {}
    feed_handles = {}
    if feed_dict:
        feed_dict = nest.flatten_dict_items(feed_dict)
        for (feed, feed_val) in feed_dict.items():
            for (subfeed, subfeed_val) in _feed_fn(feed, feed_val):
                try:
                    subfeed_t = self.graph.as_graph_element(subfeed, allow_tensor=True, allow_operation=False)
                except Exception as e:
                    raise TypeError(f'Cannot interpret feed_dict key as Tensor: {e.args[0]}')
                if isinstance(subfeed_val, tensor.Tensor):
                    raise TypeError(f'The value of a feed cannot be a tf.Tensor object. Acceptable feed values include Python scalars, strings, lists, numpy ndarrays, or TensorHandles. For reference, the tensor object was {str(feed_val)} which was passed to the argument `feed_dict` with key {str(feed)}.')
                subfeed_dtype = subfeed_t.dtype.as_numpy_dtype
                if isinstance(subfeed_val, int) and _convert_to_numpy_obj(subfeed_dtype, subfeed_val) != subfeed_val:
                    raise TypeError(f'Type of feed value {str(subfeed_val)} with type ' + f'{str(type(subfeed_val))} is not compatible with Tensor type {str(subfeed_dtype)}. Try explicitly setting the type of the feed tensor to a larger type (e.g. int64).')
                is_tensor_handle_feed = isinstance(subfeed_val, session_ops.TensorHandle)
                if is_tensor_handle_feed:
                    np_val = subfeed_val.to_numpy_array()
                    feed_handles[subfeed_t.ref()] = subfeed_val
                else:
                    np_val = numpy_compat.np_asarray(subfeed_val, subfeed_dtype)
                if not is_tensor_handle_feed and (not subfeed_t.get_shape().is_compatible_with(np_val.shape)):
                    raise ValueError(f'Cannot feed value of shape {str(np_val.shape)} for Tensor {subfeed_t.name}, which has shape {str(subfeed_t.get_shape())}')
                if not self.graph.is_feedable(subfeed_t):
                    raise ValueError(f'Tensor {subfeed_t.name} may not be fed.')
                feed_dict_tensor[subfeed_t.ref()] = np_val
                feed_map[compat.as_bytes(subfeed_t.name)] = (subfeed_t, subfeed_val)
    fetch_handler = _FetchHandler(self._graph, fetches, feed_dict_tensor, feed_handles=feed_handles)
    _ = self._update_with_movers(feed_dict_tensor, feed_map)
    final_fetches = fetch_handler.fetches()
    final_targets = fetch_handler.targets()
    if final_fetches or final_targets or (handle and feed_dict_tensor):
        results = self._do_run(handle, final_targets, final_fetches, feed_dict_tensor, options, run_metadata)
    else:
        results = []
    return fetch_handler.build_results(self, results)

def get_prep_value(self, value):
    obj = super().get_prep_value(value)
    if obj is None:
        return None
    if isinstance(obj, GEOSGeometry):
        pass
    else:
        is_candidate = isinstance(obj, (bytes, str)) or hasattr(obj, '__geo_interface__')
        raster = self.get_raster_prep_value(obj, is_candidate)
        if <MASK>:
            obj = raster
        elif is_candidate:
            try:
                obj = GEOSGeometry(obj)
            except (GEOSException, GDALException):
                raise ValueError("Couldn't create spatial object from lookup value '%s'." % obj)
        else:
            raise ValueError('Cannot use object with type %s for a spatial lookup parameter.' % type(obj).__name__)
    obj.srid = self.get_srid(obj)
    return obj

def _get_string_to_hash_bucket_fn(self, hasher_spec):
    """Returns the string_to_hash_bucket op to use based on `hasher_spec`."""
    if not isinstance(hasher_spec, HasherSpec):
        raise TypeError(f'`hasher_spec` must be of type HasherSpec, got {type(hasher_spec)}.')
    if hasher_spec.hasher == 'fasthash':
        return string_ops.string_to_hash_bucket_fast
    if hasher_spec.hasher == 'legacy':
        return string_ops.string_to_hash_bucket
    if <MASK>:
        return functools.partial(string_ops.string_to_hash_bucket_strong, key=hasher_spec.key)
    raise ValueError(f'Found unknown hasher {hasher_spec.hasher} in `hasher_spec`')

def has_internal_changes(self) -> bool:
    checkrun_name = INTERNAL_CHANGES_CHECKRUN_NAME
    if <MASK>:
        return False
    checks = self.get_checkrun_conclusions()
    if checks is None or checkrun_name not in checks:
        return False
    return checks[checkrun_name].status != 'SUCCESS'

def _is_valid_predict_signature(signature_def):
    """Determine whether the argument is a servable 'predict' SignatureDef."""
    if <MASK>:
        return False
    if not signature_def.inputs.keys():
        return False
    if not signature_def.outputs.keys():
        return False
    return True

def _port_metadata_for_input_quant_nodes(input_node: torch.fx.Node, node: torch.fx.Node, qspec: Optional[QuantizationSpecBase]):
    if <MASK>:
        return
    is_dynamic_quant = getattr(qspec, 'is_dynamic', None)
    if is_dynamic_quant is not None and is_dynamic_quant is True:
        choose_qparams_node = _find_choose_qparams_node(input_node)
        if choose_qparams_node is None:
            raise ValueError(f'No chose qparams node found for {node}')
        choose_qparam_users = _filter_sym_size_users(choose_qparams_node)
        if len(choose_qparam_users) != 2:
            raise InternalError(f'Expecting exactly two user for {choose_qparams_node}')
        scale_node = choose_qparam_users.pop()
        dynamic_q_node = next(iter(scale_node.users.keys()))
        dynamic_q_node_users = _filter_sym_size_users(dynamic_q_node)
        if len(dynamic_q_node_users) > 1:
            raise InternalError(f'Expecting single user for {dynamic_q_node}')
        dynamic_dq_node = dynamic_q_node_users.pop()
        _add_metadata(choose_qparams_node, node)
        _add_metadata(dynamic_q_node, node)
        _add_metadata(dynamic_dq_node, node)
    else:
        (q_node, dq_node) = _find_q_dq_node_for_user(input_node, node)
        if q_node is None or dq_node is None:
            return
        q_to_get_attr_nodes = [q_node]
        q_node_input = q_node.args[0]
        while isinstance(q_node_input, torch.fx.Node) and q_node_input.op == 'call_function' and (q_node_input.target in [torch.ops.aten.flatten.using_ints, torch.ops.aten.permute.default, torch.ops.aten.permute_copy.default, torch.ops.aten.slice_copy.Tensor, torch.ops.aten.squeeze.dim, torch.ops.aten.squeeze_copy.dim, torch.ops.aten.transpose.Dimname, torch.ops.aten.transpose.int, torch.ops.aten.transpose_, torch.ops.aten.view_copy.default, torch.ops.aten.view.default, torch.ops.aten._mkldnn_transpose]):
            q_to_get_attr_nodes.append(q_node_input)
            q_node_input = q_node_input.args[0]
        if isinstance(q_node_input, torch.fx.Node) and q_node_input.op == 'get_attr':
            for n in q_to_get_attr_nodes:
                _add_metadata(n, q_node_input)
        _add_metadata(dq_node, node)

@functools.lru_cache
def get_symmetric_quantization_config(is_per_channel: bool=False, is_qat: bool=False, is_dynamic: bool=False, act_qmin: int=-128, act_qmax: int=127, weight_qmin: int=-127, weight_qmax: int=127):
    extra_args: dict[str, Any] = {'eps': 2 ** (-12)}
    if is_qat:
        if is_dynamic:
            act_observer_or_fake_quant_ctr = FakeQuantize
            dynamic_quant_observer = MovingAverageMinMaxObserver.with_args(averaging_constant=1)
            extra_args['observer'] = dynamic_quant_observer
        else:
            act_observer_or_fake_quant_ctr = FusedMovingAvgObsFakeQuantize
    elif is_dynamic:
        act_observer_or_fake_quant_ctr = PlaceholderObserver
    else:
        act_observer_or_fake_quant_ctr = HistogramObserver
    act_quantization_spec = QuantizationSpec(dtype=torch.int8, quant_min=act_qmin, quant_max=act_qmax, qscheme=torch.per_tensor_affine, is_dynamic=is_dynamic, observer_or_fake_quant_ctr=act_observer_or_fake_quant_ctr.with_args(**extra_args))
    weight_qscheme = torch.per_channel_symmetric if is_per_channel else torch.per_tensor_symmetric
    weight_observer_or_fake_quant_ctr: _ObserverOrFakeQuantizeConstructor = MinMaxObserver
    if is_qat:
        weight_observer_or_fake_quant_ctr = FusedMovingAvgObsFakeQuantize
    elif <MASK>:
        weight_observer_or_fake_quant_ctr = PerChannelMinMaxObserver
    extra_args: dict[str, Any] = {'eps': 2 ** (-12)}
    if is_qat:
        if weight_qscheme == torch.per_tensor_symmetric:
            extra_args['observer'] = MovingAverageMinMaxObserver
        else:
            extra_args['observer'] = MovingAveragePerChannelMinMaxObserver
    weight_quantization_spec = QuantizationSpec(dtype=torch.int8, quant_min=weight_qmin, quant_max=weight_qmax, qscheme=weight_qscheme, ch_axis=0, is_dynamic=False, observer_or_fake_quant_ctr=weight_observer_or_fake_quant_ctr.with_args(**extra_args))
    bias_quantization_spec = None
    if is_dynamic:
        quantization_config = QuantizationConfig(act_quantization_spec, None, weight_quantization_spec, bias_quantization_spec, is_qat)
    else:
        quantization_config = QuantizationConfig(act_quantization_spec, act_quantization_spec, weight_quantization_spec, bias_quantization_spec, is_qat)
    return quantization_config

def _validate_sdpa_input(query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, attn_mask: Optional[torch.Tensor]=None, dropout_p=0.0, is_causal=False, scale=None):
    if not isinstance(query, NestedTensor) or not isinstance(key, NestedTensor) or (not isinstance(value, NestedTensor)):
        raise ValueError(f'Expected query, key, and value to be nested tensors, but got query.is_nested: {query.is_nested}, key.is_nested: {key.is_nested}, and value.is_nested: {value.is_nested} instead.')
    if query.dtype != key.dtype or query.dtype != value.dtype:
        raise ValueError(f'Expected query, key, and value to have the same dtype, but got query.dtype: {query.dtype}, key.dtype: {key.dtype}, and value.dtype: {value.dtype} instead.')
    if query.device != key.device or query.device != value.device:
        raise ValueError(f'Expected query, key, and value to have the same device type, but got query.device: {query.device}, key.device: {key.device}, and value.device: {value.device} instead.')
    if <MASK>:
        raise ValueError(f'Expected query, key, and value to all be  at least 3 dimensional, but got query.dim: {query.dim()}, key.dim: {key.dim()} and value.dim: {value.dim()} instead.')
    if query._ragged_idx != key._ragged_idx or query._ragged_idx != value._ragged_idx:
        raise ValueError(f'Expected query, key, and value to all be ragged on the same dimension, but got ragged dims {query._ragged_idx}, {key._ragged_idx}, and {value._ragged_idx}, respectively.')
    if attn_mask is not None:
        raise ValueError('Masks are not yet supported!')
        if attn_mask.dtype != torch.bool and attn_mask.dtype != query.dtype:
            raise ValueError(f'Expected attn_mask dtype to be bool or to match query dtype, but got attn_mask.dtype: {attn_mask.dtype}, and query.dtype: {query.dtype} instead.')

def _read_config(f):
    (meta, vars, sections, reqs) = parse_config(f, dirs)
    for (rname, rvalue) in reqs.items():
        (nmeta, nvars, nsections, nreqs) = _read_config(pkg_to_filename(rvalue))
        for (k, v) in nvars.items():
            if <MASK>:
                vars[k] = v
        for (oname, ovalue) in nsections[rname].items():
            if ovalue:
                sections[rname][oname] += ' %s' % ovalue
    return (meta, vars, sections, reqs)

def fuzz_inputs_specs(self, output_spec: Spec, num_inputs: int=2) -> list[Spec]:
    """Decompose tensor into input tensors for pointwise operation with type promotion."""
    if <MASK>:
        raise ValueError(f'{self.__class__.__name__} can only produce TensorSpec outputs')
    promotion_table = get_promotion_table_for_strings()
    dtype_str = get_dtype_name(output_spec.dtype)
    supported_types = promotion_table.get(dtype_str, [(dtype_str, dtype_str)])
    if num_inputs >= 2:
        dtypes = list(random.choice(supported_types))
        while len(dtypes) < num_inputs:
            dtypes.append(dtype_str)
    else:
        dtypes = [dtype_str] * num_inputs
    dtype_map = get_dtype_map()
    return [TensorSpec(size=output_spec.size, stride=output_spec.stride, dtype=dtype_map.get(dt, output_spec.dtype)) for dt in dtypes]

def _asarray_with_order(array, dtype=None, order=None, copy=None, *, xp=None, device=None):
    """Helper to support the order kwarg only for NumPy-backed arrays

    Memory layout parameter `order` is not exposed in the Array API standard,
    however some input validation code in scikit-learn needs to work both
    for classes and functions that will leverage Array API only operations
    and for code that inherently relies on NumPy backed data containers with
    specific memory layout constraints (e.g. our own Cython code). The
    purpose of this helper is to make it possible to share code for data
    container validation without memory copies for both downstream use cases:
    the `order` parameter is only enforced if the input array implementation
    is NumPy based, otherwise `order` is just silently ignored.
    """
    (xp, _) = get_namespace(array, xp=xp)
    if _is_numpy_namespace(xp):
        if <MASK>:
            array = numpy.array(array, order=order, dtype=dtype)
        else:
            array = numpy.asarray(array, order=order, dtype=dtype)
        return xp.asarray(array)
    else:
        return xp.asarray(array, dtype=dtype, copy=copy, device=device)

def init_wl_clipboard():
    PRIMARY_SELECTION = '-p'

    def copy_wl(text, primary=False):
        text = _stringifyText(text)
        args = ['wl-copy']
        if <MASK>:
            args.append(PRIMARY_SELECTION)
        if not text:
            args.append('--clear')
            subprocess.check_call(args, close_fds=True)
        else:
            p = subprocess.Popen(args, stdin=subprocess.PIPE, close_fds=True)
            p.communicate(input=text.encode(ENCODING))

    def paste_wl(primary=False):
        args = ['wl-paste', '-n']
        if primary:
            args.append(PRIMARY_SELECTION)
        p = subprocess.Popen(args, stdout=subprocess.PIPE, close_fds=True)
        (stdout, _stderr) = p.communicate()
        return stdout.decode(ENCODING)
    return (copy_wl, paste_wl)

def _to_ort_value(input: torch.Tensor | int | float | str | bool) -> ort.OrtValue:
    """Convert a PyTorch tensor to an ONNX Runtime OrtValue."""
    import numpy as np
    import onnxruntime as ort
    from torch.onnx._internal.exporter import _core
    if isinstance(input, (int, float, str, bool)):
        dtype_mapping = {int: np.int64, float: np.float32}
        dtype = dtype_mapping.get(type(input), None)
        return ort.OrtValue.ortvalue_from_numpy(np.array(input, dtype=dtype))
    if <MASK>:
        if hasattr(ort.OrtValue, 'ortvalue_from_numpy_with_onnx_type'):
            if input.dtype == torch.bfloat16:
                uint_type = torch.uint16
            else:
                uint_type = torch.uint8
            onnx_type = _core.torch_dtype_to_onnx_dtype(input.dtype)
            input = input.contiguous()
            return ort.OrtValue.ortvalue_from_numpy_with_onnx_type(input.view(uint_type).numpy(force=True), onnx_element_type=onnx_type)
        raise RuntimeError(f"Failed to convert tensor of type '{input.dtype}' to OrtValue. Please ensure that ONNX Runtime is built with DLPack support or is the latest version")
    return ort.OrtValue.ortvalue_from_numpy(input.numpy(force=True))

def guard_to_detect_forward_monkeypatching(source, mod):
    if <MASK>:
        if 'forward' in mod.__dict__ and callable(mod.__dict__['forward']):
            fwd = mod.__dict__['forward']
            forward_source = AttrSource(source, 'forward')
            if type(fwd) is types.MethodType:
                forward_source = AttrSource(forward_source, '__func__')
            install_guard(forward_source.make_guard(GuardBuilder.CLOSURE_MATCH))
        else:
            install_guard(source.make_guard(functools.partial(GuardBuilder.NOT_PRESENT_IN_GENERIC_DICT, attr='forward')))

def _check_single_device_module(module: nn.Module, ignored_params: set[nn.Parameter], device_id: Optional[Union[int, torch.device]]) -> None:
    """
    Raise an error if ``module`` has original parameters on multiple devices, ignoring the parameters in ``ignored_params``.

    Thus, after this method, the
    module must be either fully on the CPU or fully on a non-CPU device.
    """
    devices = {param.device for param in _get_orig_params(module, ignored_params)}
    if <MASK>:
        if device_id is None:
            raise RuntimeError('To support a module with both CPU and GPU params, please pass in device_id argument.')
    elif len(devices) > 1:
        raise RuntimeError(f'FSDP only supports single device modules but got params on {devices}')

def elu(input: Tensor, alpha: float=1.0, inplace: bool=False) -> Tensor:
    """Apply the Exponential Linear Unit (ELU) function element-wise.

    See :class:`~torch.nn.ELU` for more details.
    """
    if <MASK>:
        return handle_torch_function(elu, (input,), input, alpha=alpha, inplace=inplace)
    if inplace:
        result = torch._C._nn.elu_(input, alpha)
    else:
        result = torch._C._nn.elu(input, alpha)
    return result

