def determine_clipboard():
    """
    Determine the OS/platform and set the copy() and paste() functions
    accordingly.
    """
    global Foundation, AppKit, qtpy, PyQt4, PyQt5
    if 'cygwin' in platform.system().lower():
        if os.path.exists('/dev/clipboard'):
            warnings.warn("Pyperclip's support for Cygwin is not perfect, see https://github.com/asweigart/pyperclip/issues/55", stacklevel=find_stack_level())
            return init_dev_clipboard_clipboard()
    elif os.name == 'nt' or platform.system() == 'Windows':
        return init_windows_clipboard()
    if platform.system() == 'Linux':
        if _executable_exists('wslconfig.exe'):
            return init_wsl_clipboard()
    if <MASK>:
        try:
            import AppKit
            import Foundation
        except ImportError:
            return init_osx_pbcopy_clipboard()
        else:
            return init_osx_pyobjc_clipboard()
    if HAS_DISPLAY:
        if os.environ.get('WAYLAND_DISPLAY') and _executable_exists('wl-copy'):
            return init_wl_clipboard()
        if _executable_exists('xsel'):
            return init_xsel_clipboard()
        if _executable_exists('xclip'):
            return init_xclip_clipboard()
        if _executable_exists('klipper') and _executable_exists('qdbus'):
            return init_klipper_clipboard()
        try:
            import qtpy
        except ImportError:
            try:
                import PyQt5
            except ImportError:
                try:
                    import PyQt4
                except ImportError:
                    pass
                else:
                    return init_qt_clipboard()
            else:
                return init_qt_clipboard()
        else:
            return init_qt_clipboard()
    return init_no_clipboard()

def run(self):
    headers = self.distribution.headers
    if <MASK>:
        return
    prefix = os.path.dirname(self.install_dir)
    for header in headers:
        if isinstance(header, tuple):
            if header[0] == 'numpy._core':
                header = ('numpy', header[1])
                if os.path.splitext(header[1])[1] == '.inc':
                    continue
            d = os.path.join(*[prefix] + header[0].split('.'))
            header = header[1]
        else:
            d = self.install_dir
        self.mkpath(d)
        (out, _) = self.copy_file(header, d)
        self.outfiles.append(out)

def _sparse_fit(self, X, strategy, missing_values, fill_value):
    """Fit the transformer on sparse data."""
    missing_mask = _get_mask(X, missing_values)
    mask_data = missing_mask.data
    n_implicit_zeros = X.shape[0] - np.diff(X.indptr)
    statistics = np.empty(X.shape[1])
    if strategy == 'constant':
        statistics.fill(fill_value)
        if not self.keep_empty_features:
            for i in range(missing_mask.shape[1]):
                if all(missing_mask[:, i].data):
                    statistics[i] = np.nan
    else:
        for i in range(X.shape[1]):
            column = X.data[X.indptr[i]:X.indptr[i + 1]]
            mask_column = mask_data[X.indptr[i]:X.indptr[i + 1]]
            column = column[~mask_column]
            mask_zeros = _get_mask(column, 0)
            column = column[~mask_zeros]
            n_explicit_zeros = mask_zeros.sum()
            n_zeros = n_implicit_zeros[i] + n_explicit_zeros
            if len(column) == 0 and self.keep_empty_features:
                statistics[i] = 0
            elif strategy == 'mean':
                s = column.size + n_zeros
                statistics[i] = np.nan if s == 0 else column.sum() / s
            elif <MASK>:
                statistics[i] = _get_median(column, n_zeros)
            elif strategy == 'most_frequent':
                statistics[i] = _most_frequent(column, 0, n_zeros)
            elif isinstance(strategy, Callable):
                statistics[i] = self.strategy(column)
    super()._fit_indicator(missing_mask)
    return statistics

def reference_sgn(x):
    if <MASK>:
        return reference_sign(x)
    out = x / np.abs(x)
    if out.ndim == 0:
        if x == 0:
            return np.array(complex(0, 0), dtype=x.dtype)
        return out
    mask = x == 0
    out[mask] = complex(0, 0)
    return out

def can_auto_functionalize(op: Union[OperatorBase, HopInstance]) -> bool:
    if isinstance(op, HopInstance):
        if not _has_gen_schema(op._op):
            return False
    else:
        if not isinstance(op, OpOverload):
            return False
        if <MASK>:
            return False
    schema = op._schema
    if not schema.is_mutable:
        return False
    schema = op._schema
    for arg in schema.arguments:
        if arg.alias_info is None:
            continue
        if not arg.alias_info.is_write:
            continue
        if torch._library.utils.is_tensor_like_type(arg.type):
            continue
        if torch._library.utils.is_tensorlist_like_type(arg.type):
            continue
        return False
    if len(schema.returns) == 1 and isinstance(schema.returns[0].type, torch.NoneType):
        return True
    if isinstance(op, OpOverload):
        for ret in schema.returns:
            if ret.alias_info is None and type(ret.type) is torch.TensorType:
                continue
            return False
        if torch._C._dispatch_has_kernel_for_dispatch_key(op.name(), 'Functionalize'):
            return False
    return True

def _add_file(filename: str) -> None:
    try:
        with tokenize.open(filename) as f:
            tokens = list(tokenize.generate_tokens(f.readline))
    except (OSError, tokenize.TokenError):
        cache[filename] = {}
        return
    result: dict[int, str] = {}
    cur_name = ''
    cur_indent = 0
    significant_indents: list[int] = []
    for (i, token) in enumerate(tokens):
        if token.type == tokenize.INDENT:
            cur_indent += 1
        elif token.type == tokenize.DEDENT:
            cur_indent -= 1
            if <MASK>:
                significant_indents.pop()
                cur_name = cur_name.rpartition('.')[0]
        elif token.type == tokenize.NAME and i + 1 < len(tokens) and (tokens[i + 1].type == tokenize.NAME) and (token.string == 'class' or token.string == 'def'):
            significant_indents.append(cur_indent)
            if cur_name:
                cur_name += '.'
            cur_name += tokens[i + 1].string
        result[token.start[0]] = cur_name
    cache[filename] = result

def _update(self, var, fn, args, kwargs, group):
    assert isinstance(var, tpu_values.TPUVariableMixin) or isinstance(var, resource_variable_ops.BaseResourceVariable)
    if tpu_util.enclosing_tpu_context() is not None:
        if group:
            return fn(var, *args, **kwargs)
        else:
            return (fn(var, *args, **kwargs),)
    packed_var = var._packed_variable
    if packed_var is not None and (not context.executing_eagerly()):
        if group:
            return fn(packed_var, *args, **kwargs)
        else:
            return (fn(packed_var, *args, **kwargs),)
    updates = []
    values_and_devices = []
    if <MASK>:
        for device in packed_var.devices:
            values_and_devices.append((packed_var, device))
    else:
        for value in var.values:
            values_and_devices.append((value, value.device))
    if var.synchronization != variables_lib.VariableSynchronization.ON_READ and var.aggregation != variables_lib.VariableAggregation.NONE:
        distribute_utils.assert_mirrored(args)
        distribute_utils.assert_mirrored(kwargs)
    for (i, value_and_device) in enumerate(values_and_devices):
        value = value_and_device[0]
        device = value_and_device[1]
        name = 'update_%d' % i
        with ops.device(device), distribute_lib.UpdateContext(i), ops.name_scope(name):
            updates.append(fn(value, *distribute_utils.select_replica(i, args), **distribute_utils.select_replica(i, kwargs)))
    return distribute_utils.update_regroup(self, updates, group)

def unlift_tokens(fw_module, fw_metadata, aot_config, bw_module=None):
    num_forward_tokens = len(fw_metadata.tokens)
    num_backward_tokens = fw_metadata.num_backward_tokens

    def rewrite_with_effects_input_token(module, node):
        with module.graph.inserting_before(node):
            new_token_node = module.graph.call_function(torch.ops.prims._make_token.default, ())
            new_token_node.meta['val'] = torch.tensor([])
            new_token_node.meta['tensor_meta'] = torch.tensor([])
            args = list(node.args)
            args[0] = new_token_node
            node.args = tuple(args)

    def rewrite_output(module, node, output_token_nodes, other_output_args):
        for output_token_node in output_token_nodes:
            assert output_token_node.op == 'call_function' and output_token_node.target == operator.getitem and (output_token_node.args[1] == 0)
        with module.graph.inserting_before(node):
            module.graph.call_function(torch.ops.prims._sink_tokens.default, (output_token_nodes,))
            node.args = (other_output_args,)

    def do(module, subgraph, expected_num_erased):
        num_erased_inputs = 0
        num_erased_outs = 0
        input_nodes = []
        input_token_nodes = set()
        with_effect_nodes = []
        output_token_nodes = []
        other_output_nodes = []
        for node in module.graph.nodes:
            if node.op == 'placeholder':
                input_nodes.append(node)
            elif is_with_effects(node):
                with_effect_nodes.append(node)
                if node.args[0] in input_nodes:
                    input_token_nodes.add(node.args[0])
                    rewrite_with_effects_input_token(module, node)
            elif node.op == 'output':
                outs = node.args[0]
                for out in outs:
                    if isinstance(out, torch.fx.node.Node) and out.op == 'call_function' and (out.target == operator.getitem) and (out.args[1] == 0) and (out.args[0] in with_effect_nodes):
                        output_token_nodes.append(out)
                    else:
                        other_output_nodes.append(out)
                rewrite_output(module, node, output_token_nodes, other_output_nodes)
                num_erased_outs = len(output_token_nodes)
        for input_token_node in input_token_nodes:
            module.graph.erase_node(input_token_node)
        num_erased_inputs = len(input_token_nodes)
        assert num_erased_inputs == expected_num_erased, f'{subgraph} num_erased_inputs:{num_erased_inputs} {input_token_nodes}!=expected {expected_num_erased}'
        assert num_erased_outs == expected_num_erased, f'{subgraph} num_erased_outs:{num_erased_outs} {output_token_nodes}!=expected {expected_num_erased}'
        module.recompile()
    if num_forward_tokens > 0:
        if <MASK>:
            from torch._dynamo.utils import lazy_format_graph_code
            aot_graphs_effects_log.debug('%s', lazy_format_graph_code('Forward graph before unlifting tokens', fw_module, aot_config.aot_id, include_stride=True, include_device=True, colored=True))
        do(fw_module, 'forward', num_forward_tokens)
    if bw_module is not None and num_backward_tokens > 0:
        if aot_config.enable_log:
            from torch._dynamo.utils import lazy_format_graph_code
            aot_graphs_effects_log.debug('%s', lazy_format_graph_code('Backward graph before unlifting tokens', bw_module, aot_config.aot_id, include_stride=True, include_device=True, colored=True))
        do(bw_module, 'backward', num_backward_tokens)
    fw_metadata.tokens = {}
    fw_metadata.num_backward_tokens = 0

@tf_export.tf_export('experimental.numpy.logspace', v1=[])
@np_utils.np_doc('logspace')
def logspace(start, stop, num=50, endpoint=True, base=10.0, dtype=None, axis=0):
    if <MASK>:
        dtype = np_utils.result_type([start * 1.0, stop * 1.0])
    else:
        dtype = np_utils.result_type(start, stop, dtype)
    result = linspace(start, stop, num=num, endpoint=endpoint, dtype=dtype, axis=axis)
    result = math_ops.pow(math_ops.cast(base, result.dtype), result)
    if dtype:
        result = math_ops.cast(result, dtype)
    return result

@no_type_check
def _init_process_group_state_for_hybrid_shard(state: _FSDPState, process_group: ProcessGroupType, device_mesh: DeviceMesh) -> _FSDPState:
    if device_mesh:
        if <MASK>:
            state._device_mesh = device_mesh
            state._inter_node_pg = device_mesh.get_group(mesh_dim=0)
            state.process_group = device_mesh.get_group(mesh_dim=1)
        else:
            raise ValueError(f'Expected device_mesh to have ndim=2 but got {device_mesh.ndim}')
    elif process_group is None:
        default_group = _get_default_group()
        (intra_node_group, inter_node_group) = _init_intra_and_inter_node_groups(default_group, state._device_handle.device_count())
        state.process_group = intra_node_group
        state._inter_node_pg = inter_node_group
    elif _is_valid_hybrid_shard_pg_type(process_group):
        (state.process_group, state._inter_node_pg) = process_group
    else:
        raise ValueError(f'Expected process_group to be passed in as either None or Tuple[dist.ProcessGroup, dist.ProcessGroup] but got {type(process_group)}')
    state._inter_node_state = _get_default_comm_hook_state(process_group=state._inter_node_pg)
    return state

def _compare_values(self, actual: torch.Tensor, expected: torch.Tensor) -> None:
    if <MASK>:
        compare_fn = self._compare_quantized_values
    elif actual.is_sparse:
        compare_fn = self._compare_sparse_coo_values
    elif actual.layout in {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}:
        compare_fn = self._compare_sparse_compressed_values
    elif actual.layout == torch.jagged:
        (actual, expected) = (actual.values(), expected.values())
        compare_fn = self._compare_regular_values_close
    elif actual.dtype.is_floating_point and actual.dtype.itemsize == 1:

        def bitwise_comp(actual: torch.Tensor, expected: torch.Tensor, *, rtol: float, atol: float, equal_nan: bool, identifier: Optional[Union[str, Callable[[str], str]]]=None) -> None:
            if rtol != 0.0 or atol != 0.0:
                raise ErrorMeta(AssertionError, f'Rtol={rtol} and atol={atol} are not supported for bitwise comparison of low dimensional floats. Please use rtol=0.0 and atol=0.0.')
            return self._compare_regular_values_close(actual, expected, rtol=rtol, atol=atol, equal_nan=equal_nan, identifier=identifier)
        compare_fn = bitwise_comp
    else:
        compare_fn = self._compare_regular_values_close
    compare_fn(actual, expected, rtol=self.rtol, atol=self.atol, equal_nan=self.equal_nan)

def _pad_or_backfill(self, *, method: FillnaOptions, limit: int | None=None, limit_area: Literal['inside', 'outside'] | None=None, copy: bool=True) -> Self:
    mask = self._mask
    if mask.any():
        func = missing.get_fill_func(method, ndim=self.ndim)
        npvalues = self._data.T
        new_mask = mask.T
        if copy:
            npvalues = npvalues.copy()
            new_mask = new_mask.copy()
        elif <MASK>:
            mask = mask.copy()
        func(npvalues, limit=limit, mask=new_mask)
        if limit_area is not None and (not mask.all()):
            mask = mask.T
            neg_mask = ~mask
            first = neg_mask.argmax()
            last = len(neg_mask) - neg_mask[::-1].argmax() - 1
            if limit_area == 'inside':
                new_mask[:first] |= mask[:first]
                new_mask[last + 1:] |= mask[last + 1:]
            elif limit_area == 'outside':
                new_mask[first + 1:last] |= mask[first + 1:last]
        if copy:
            return self._simple_new(npvalues.T, new_mask.T)
        else:
            return self
    elif copy:
        new_values = self.copy()
    else:
        new_values = self
    return new_values

def find_legit_leaks_from_referrers(active_fakes: weakref.WeakSet) -> weakref.WeakSet:
    legit_leak: weakref.WeakSet = weakref.WeakSet()
    fake_list = list(active_fakes)
    fake_list_id = id(fake_list)
    for act in fake_list:
        seen = set()
        flagged = False
        for r in gc.get_referrers(act):
            rid = id(r)
            if rid in seen:
                continue
            seen.add(rid)
            if rid == fake_list_id:
                continue
            if _is_globals_or_locals(r):
                continue
            if isinstance(r, _SKIP_TYPES):
                continue
            if _is_tracked_fake(r):
                continue
            if <MASK>:
                if _is_gm_meta_like_dict(r, act):
                    continue
                if _dict_is_attr_of_tracked_fake(r):
                    continue
                flagged = True
                break
            flagged = True
            break
        if flagged:
            legit_leak.add(act)
    return legit_leak

def _coerce(self, value):
    """
        Validate that the value can be coerced to the right type (if not
        empty).
        """
    if <MASK>:
        return self.empty_value
    try:
        value = self.coerce(value)
    except (ValueError, TypeError, ValidationError):
        raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': value})
    return value

@capture_provenance
def unary_magic_impl(self):
    from torch.fx.experimental.proxy_tensor import get_proxy_mode, handle_sym_dispatch
    op = method_to_operator(method)
    if get_proxy_mode():
        return to_node(self, handle_sym_dispatch(op, (wrap_node(self),), {}))
    expr = self.expr
    if method == 'floor' or method == 'ceiling':
        expr = self.shape_env._simplify_floor_div(expr)
    try:
        out = func(expr)
    except Exception:
        log.warning('failed to eval %s(%s)', method, expr)
        raise
    sym_node_log.debug('%s %s -> %s', func, expr, out)
    out_hint = None
    if <MASK>:
        out_hint = op(self.hint)
    pytype: type
    if method in always_int_magic_methods:
        pytype = int
    elif method in always_bool_magic_methods:
        pytype = bool
    elif method in always_float_magic_methods:
        pytype = float
    else:
        pytype = self.pytype
    (fx_node, _) = self.shape_env._create_fx_call_function(op, (self.fx_node,))
    return SymNode(out, self.shape_env, pytype, out_hint, fx_node=fx_node)

def _check_lazy_references(apps, ignore=None):
    """
    Ensure all lazy (i.e. string) model references have been resolved.

    Lazy references are used in various places throughout Django, primarily in
    related fields and model signals. Identify those common cases and provide
    more helpful error messages for them.

    The ignore parameter is used by StateApps to exclude swappable models from
    this check.
    """
    pending_models = set(apps._pending_operations) - (ignore or set())
    if not pending_models:
        return []
    from django.db.models import signals
    model_signals = {signal: name for (name, signal) in vars(signals).items() if isinstance(signal, signals.ModelSignal)}

    def extract_operation(obj):
        """
        Take a callable found in Apps._pending_operations and identify the
        original callable passed to Apps.lazy_model_operation(). If that
        callable was a partial, return the inner, non-partial function and
        any arguments and keyword arguments that were supplied with it.

        obj is a callback defined locally in Apps.lazy_model_operation() and
        annotated there with a `func` attribute so as to imitate a partial.
        """
        (operation, args, keywords) = (obj, [], {})
        while hasattr(operation, 'func'):
            args.extend(getattr(operation, 'args', []))
            keywords.update(getattr(operation, 'keywords', {}))
            operation = operation.func
        return (operation, args, keywords)

    def app_model_error(model_key):
        try:
            apps.get_app_config(model_key[0])
            model_error = "app '%s' doesn't provide model '%s'" % model_key
        except LookupError:
            model_error = "app '%s' isn't installed" % model_key[0]
        return model_error

    def field_error(model_key, func, args, keywords):
        error_msg = "The field %(field)s was declared with a lazy reference to '%(model)s', but %(model_error)s."
        params = {'model': '.'.join(model_key), 'field': keywords['field'], 'model_error': app_model_error(model_key)}
        return Error(error_msg % params, obj=keywords['field'], id='fields.E307')

    def signal_connect_error(model_key, func, args, keywords):
        error_msg = "%(receiver)s was connected to the '%(signal)s' signal with a lazy reference to the sender '%(model)s', but %(model_error)s."
        receiver = args[0]
        if isinstance(receiver, types.FunctionType):
            description = "The function '%s'" % receiver.__name__
        elif <MASK>:
            description = "Bound method '%s.%s'" % (receiver.__self__.__class__.__name__, receiver.__name__)
        else:
            description = "An instance of class '%s'" % receiver.__class__.__name__
        signal_name = model_signals.get(func.__self__, 'unknown')
        params = {'model': '.'.join(model_key), 'receiver': description, 'signal': signal_name, 'model_error': app_model_error(model_key)}
        return Error(error_msg % params, obj=receiver.__module__, id='signals.E001')

    def default_error(model_key, func, args, keywords):
        error_msg = '%(op)s contains a lazy reference to %(model)s, but %(model_error)s.'
        params = {'op': func, 'model': '.'.join(model_key), 'model_error': app_model_error(model_key)}
        return Error(error_msg % params, obj=func, id='models.E022')
    known_lazy = {('django.db.models.fields.related', 'resolve_related_class'): field_error, ('django.db.models.fields.related', 'set_managed'): None, ('django.dispatch.dispatcher', 'connect'): signal_connect_error}

    def build_error(model_key, func, args, keywords):
        key = (func.__module__, func.__name__)
        error_fn = known_lazy.get(key, default_error)
        return error_fn(model_key, func, args, keywords) if error_fn else None
    return sorted(filter(None, (build_error(model_key, *extract_operation(func)) for model_key in pending_models for func in apps._pending_operations[model_key])), key=lambda error: error.msg)

def _check_file_or_buffer(self, f, engine: CSVEngine) -> None:
    if <MASK>:
        raise ValueError("The 'python' engine cannot iterate through this file buffer.")
    if hasattr(f, 'encoding'):
        file_encoding = f.encoding
        orig_reader_enc = self.orig_options.get('encoding', None)
        any_none = file_encoding is None or orig_reader_enc is None
        if file_encoding != orig_reader_enc and (not any_none):
            file_path = getattr(f, 'name', None)
            raise ValueError(f'The specified reader encoding {orig_reader_enc} is different from the encoding {file_encoding} of file {file_path}.')

def expand_hostlist(hostlist):
    """Create a list of hosts out of a SLURM hostlist.

  The order of nodes is preserved and no deduplication is done
  Input: 'n[1-2],m5,o[3-4,6,7-9]')
  Output: ['n1', 'n2', 'm5', 'o3', 'o4', 'o6', 'o7', 'o8', 'o9']
  """

    def split_hostlist(hostlist):
        """Split hostlist at commas outside of range expressions ('[3-5]')."""
        in_brackets = False
        cur_host = ''
        for c in hostlist:
            if <MASK>:
                assert c != '['
                if c == ']':
                    in_brackets = False
            elif c == '[':
                in_brackets = True
            elif c == ',':
                assert cur_host != ''
                yield cur_host
                cur_host = ''
                continue
            cur_host += c
        if cur_host:
            yield cur_host

    def expand_range_expression(range_exp):
        """Expand a range expression like '3-5' to values 3,4,5."""
        for part in range_exp.split(','):
            sub_range = part.split('-')
            if len(sub_range) == 1:
                sub_range = sub_range * 2
            else:
                assert len(sub_range) == 2
            num_digits = len(sub_range[0])
            for i in range(int(sub_range[0]), int(sub_range[1]) + 1):
                yield str(i).zfill(num_digits)
    hosts = []
    try:
        for part in split_hostlist(hostlist):
            m = re.match('([^,[\\]]*)(\\[([^\\]]+)\\])?$', part)
            if m is None:
                raise ValueError('Invalid part: %s' % part)
            prefix = m.group(1) or ''
            if m.group(3) is None:
                hosts.append(prefix)
            else:
                hosts.extend((prefix + i for i in expand_range_expression(m.group(3))))
    except Exception as e:
        raise ValueError('Invalid hostlist format "%s": %s' % (hostlist, e))
    return hosts

def testDumpingDebugHookWithStatefulWatchFnWorks(self):
    watch_fn_state = {'run_counter': 0}

    def counting_watch_fn(fetches, feed_dict):
        del fetches, feed_dict
        watch_fn_state['run_counter'] += 1
        if watch_fn_state['run_counter'] % 2 == 1:
            return framework.WatchOptions(debug_ops='DebugIdentity', tensor_dtype_regex_allowlist='.*_ref')
        else:
            return framework.WatchOptions(debug_ops='DebugIdentity', node_name_regex_allowlist='^$', op_type_regex_allowlist='^$')
    dumping_hook = hooks.DumpingDebugHook(self.session_root, watch_fn=counting_watch_fn)
    mon_sess = monitored_session._HookedSession(self.sess, [dumping_hook])
    for _ in range(4):
        mon_sess.run(self.inc_v)
    dump_dirs = glob.glob(os.path.join(self.session_root, 'run_*'))
    dump_dirs = sorted(dump_dirs, key=lambda x: int(os.path.basename(x).split('_')[1]))
    self.assertEqual(4, len(dump_dirs))
    for (i, dump_dir) in enumerate(dump_dirs):
        self._assert_correct_run_subdir_naming(os.path.basename(dump_dir))
        dump = debug_data.DebugDumpDir(dump_dir)
        if <MASK>:
            self.assertAllClose([10.0 + 1.0 * i], dump.get_tensors('v', 0, 'DebugIdentity'))
            self.assertNotIn('delta', [datum.node_name for datum in dump.dumped_tensor_data])
        else:
            self.assertEqual(0, dump.size)
        self.assertEqual(repr(self.inc_v), dump.run_fetches_info)
        self.assertEqual(repr(None), dump.run_feed_keys_info)

def __init__(self, input_shape=None, batch_size=None, dtype=None, input_tensor=None, sparse=None, name=None, ragged=None, type_spec=None, **kwargs):
    self._init_input_shape = input_shape
    self._init_batch_size = batch_size
    self._init_dtype = dtype
    self._init_sparse = sparse
    self._init_ragged = ragged
    self._init_type_spec = type_spec
    strategy = distribute_lib.get_strategy()
    if strategy and batch_size is not None and distributed_training_utils.global_batch_size_supported(strategy):
        if batch_size % strategy.num_replicas_in_sync != 0:
            raise ValueError('The `batch_size` argument ({}) must be divisible by the number of replicas ({})'.format(batch_size, strategy.num_replicas_in_sync))
        batch_size = batch_size // strategy.num_replicas_in_sync
    if 'batch_input_shape' in kwargs:
        batch_input_shape = kwargs.pop('batch_input_shape')
        if input_shape and batch_input_shape:
            raise ValueError('Only provide the input_shape OR batch_input_shape argument to InputLayer, not both at the same time.')
        if batch_input_shape:
            batch_size = batch_input_shape[0]
            input_shape = batch_input_shape[1:]
    if kwargs:
        raise ValueError('Unrecognized keyword arguments:', kwargs.keys())
    if sparse and ragged:
        raise ValueError('Cannot set both sparse and ragged to True in a Keras input.')
    if not name:
        prefix = 'input'
        name = prefix + '_' + str(backend.get_uid(prefix))
    if not dtype:
        if input_tensor is None:
            dtype = backend.floatx()
        else:
            dtype = backend.dtype(input_tensor)
    elif input_tensor is not None and input_tensor.dtype != dtype:
        raise ValueError('`input_tensor.dtype` differs from `dtype`: %s vs. %s' % (input_tensor.dtype, dtype))
    super(InputLayer, self).__init__(dtype=dtype, name=name)
    self.built = True
    self.sparse = True if sparse else False
    self.ragged = True if ragged else False
    self.batch_size = batch_size
    self.supports_masking = True
    if isinstance(input_shape, tensor_shape.TensorShape):
        input_shape = tuple(input_shape.as_list())
    elif isinstance(input_shape, int):
        input_shape = (input_shape,)
    if type_spec is not None:
        args_that_must_be_none = [('(input_)shape', self._init_input_shape), ('batch_size', self._init_batch_size), ('dtype', self._init_dtype), ('input_tensor', input_tensor), ('sparse', self._init_sparse), ('ragged', self._init_ragged)]
        for (arg_name, arg) in args_that_must_be_none:
            _assert_other_arg_none(arg_name, arg)
        if not ops.executing_eagerly_outside_functions():
            raise ValueError('Creating Keras inputs from a type_spec is only supported when eager execution is enabled.')
        input_tensor = keras_tensor.keras_tensor_from_type_spec(type_spec)
        if isinstance(input_tensor, keras_tensor.SparseKerasTensor):
            self.sparse = True
        if isinstance(input_tensor, keras_tensor.RaggedKerasTensor):
            self.ragged = True
        self.is_placeholder = True
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    elif input_tensor is None:
        if input_shape is not None:
            batch_input_shape = (batch_size,) + tuple(input_shape)
        else:
            batch_input_shape = None
        graph = backend.get_graph()
        with graph.as_default():
            input_tensor = backend.placeholder(shape=batch_input_shape, dtype=dtype, name=self.name, sparse=sparse, ragged=ragged)
        self.is_placeholder = True
        self._batch_input_shape = batch_input_shape
    else:
        if ops.executing_eagerly_outside_functions():
            if <MASK>:
                input_tensor = keras_tensor.keras_tensor_from_tensor(input_tensor)
        elif not tf_utils.is_symbolic_tensor(input_tensor):
            raise ValueError('You should not pass an EagerTensor to `Input`. For example, instead of creating an InputLayer, you should instantiate your model and directly call it on your input.')
        self.is_placeholder = False
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    input_tensor._keras_mask = None
    node_module.Node(layer=self, outputs=input_tensor)
    if isinstance(input_tensor, keras_tensor.KerasTensor) or tf_utils.is_extension_type(input_tensor):
        self._type_spec = input_tensor._type_spec
    else:
        self._type_spec = tensor_spec.TensorSpec(shape=input_tensor.shape, dtype=input_tensor.dtype, name=self.name)

def _local_alltoall_base_(output_tensor: torch.Tensor, input_tensor: torch.Tensor, process_group_so: ScriptObject, output_split_sizes: list[int], input_split_sizes: list[int], async_op: bool=True, timeout: int=-1) -> ScriptObject:
    from . import LocalTensor
    (ranks, group_offsets, _offset) = _prepare_collective_groups(process_group_so)
    assert isinstance(input_tensor, LocalTensor), 'Input tensor must be a LocalTensor'
    assert isinstance(output_tensor, LocalTensor), 'Output tensor must be a LocalTensor'
    if output_split_sizes is not None:
        output_split_sizes = list(output_split_sizes)
    if input_split_sizes is not None:
        input_split_sizes = list(input_split_sizes)
    for group_offset in group_offsets:
        group_ranks = [group_offset + r for r in ranks]
        for (i, rank_i) in enumerate(group_ranks):
            rank_tensor = input_tensor._local_tensors[rank_i]
            if input_split_sizes is not None and len(input_split_sizes) > 0:
                input_splits = torch.split(rank_tensor, input_split_sizes, dim=0)
            else:
                split_size = rank_tensor.size(0) // len(group_ranks)
                input_splits = torch.split(rank_tensor, split_size, dim=0)
            for (j, rank_j) in enumerate(group_ranks):
                if j < len(input_splits):
                    split_tensor = input_splits[j]
                    if output_split_sizes is not None and len(output_split_sizes) > 0:
                        output_offset = sum(output_split_sizes[:i]) if i > 0 else 0
                        end_offset = output_offset + output_split_sizes[i] if i < len(output_split_sizes) else output_tensor._local_tensors[rank_j].size(0)
                    else:
                        split_size = output_tensor._local_tensors[rank_j].size(0) // len(group_ranks)
                        output_offset = i * split_size
                        end_offset = min((i + 1) * split_size, output_tensor._local_tensors[rank_j].size(0))
                    output_section = output_tensor._local_tensors[rank_j][output_offset:end_offset]
                    if output_section.numel() > 0:
                        if <MASK>:
                            split_tensor = split_tensor.view(output_section.size())
                        output_section.copy_(split_tensor)
    work = FakeWork()
    work_so = Work.boxed(work)
    return work_so

def _update_log_state_from_env() -> None:
    global log_state
    log_setting = os.environ.get(LOG_ENV_VAR, None)
