def create_local_plan(self) -> SavePlan:
    plan = create_default_local_save_plan(self.state_dict, self.is_coordinator)
    if self.flatten_state_dict:
        plan = dataclasses.replace(plan, planner_data=self.mappings)
    self.plan = plan
    if self._enable_plan_caching:
        if <MASK>:
            logger.info('No change in the local plan. Skipping sending the plan to the coordinator')
            return SavePlan([], usable=False)
        else:
            SavePlanner._cached_save_plan[self._cached_plans_key] = plan
    return self.plan

def create_rename_mapping(inputs, dynamic_shapes: dict[str, Any] | tuple[Any, ...] | list[Any]) -> dict[str, str]:
    """Create a mapping from old names to new names for dynamic axes."""
    (flat_dynamic_shapes, _) = _flatten_dynamic_shapes_to_axes(dynamic_shapes)
    if len(inputs) != len(flat_dynamic_shapes):
        warnings.warn('# ONNX model has different number of inputs than the flatten dynamic_shapes. The dynamic axes will not be renamed.', UserWarning, stacklevel=3)
        return {}
    rename_mapping: dict[str, str] = {}
    for (idx, axes) in enumerate(flat_dynamic_shapes):
        input = inputs[idx]
        if isinstance(axes, dict):
            for (dim, axis) in axes.items():
                if not isinstance(input.shape[dim], ir.SymbolicDim):
                    continue
                old_name = input.shape[dim].value
                if old_name is None:
                    continue
                if isinstance(axis, (_DimHint, int)) or axis is None:
                    continue
                custom_name = _get_custom_axis_name(axis)
                if <MASK>:
                    warnings.warn(f'# The axis name: {custom_name} will not be used, since it shares the same shape constraints with another axis: {rename_mapping[input.shape[dim].value]}.')
                    continue
                rename_mapping[input.shape[dim].value] = custom_name
        elif isinstance(axes, (list, tuple)):
            for (dim, axis) in enumerate(axes):
                if not isinstance(input.shape[dim], ir.SymbolicDim):
                    continue
                old_name = input.shape[dim].value
                if old_name is None:
                    continue
                if isinstance(axis, (_DimHint, int)) or axis is None:
                    continue
                custom_name = _get_custom_axis_name(axis)
                if input.shape[dim].value in rename_mapping:
                    warnings.warn(f'# The axis name: {custom_name} will not be used, since it shares the same shape constraints with another axis: {rename_mapping[input.shape[dim].value]}.', UserWarning, stacklevel=3)
                    continue
                rename_mapping[input.shape[dim].value] = _get_custom_axis_name(axis)
    return rename_mapping

def _median(a, axis=None, out=None, overwrite_input=False):
    a = np.asanyarray(a)
    if axis is None:
        sz = a.size
    else:
        sz = a.shape[axis]
    if sz % 2 == 0:
        szh = sz // 2
        kth = [szh - 1, szh]
    else:
        kth = [(sz - 1) // 2]
    supports_nans = np.issubdtype(a.dtype, np.inexact) or a.dtype.kind in 'Mm'
    if supports_nans:
        kth.append(-1)
    if overwrite_input:
        if axis is None:
            part = a.ravel()
            part.partition(kth)
        else:
            a.partition(kth, axis=axis)
            part = a
    else:
        part = partition(a, kth, axis=axis)
    if part.shape == ():
        return part.item()
    if axis is None:
        axis = 0
    indexer = [slice(None)] * part.ndim
    index = part.shape[axis] // 2
    if <MASK>:
        indexer[axis] = slice(index, index + 1)
    else:
        indexer[axis] = slice(index - 1, index + 1)
    indexer = tuple(indexer)
    rout = mean(part[indexer], axis=axis, out=out)
    if supports_nans and sz > 0:
        rout = np.lib._utils_impl._median_nancheck(part, rout, axis)
    return rout

def __truediv__(self, other):
    if <MASK>:
        return poly1d(self.coeffs / other)
    else:
        other = poly1d(other)
        return polydiv(self, other)

def maybe_skip_test(self, mode):
    if mode == 'cuda':
        if os.name == 'nt':
            self.skipTest("This test doesn't support Windows")
        if not test.is_gpu_available(cuda_only=True):
            self.skipTest('This test requires GPU.')
        cuda_version_str = sysconfig_lib.get_build_info().get('cuda_version', '0.0')
        cuda_version = tuple([int(x) for x in cuda_version_str.split('.')])
        if <MASK>:
            self.skipTest('This test requires CUDA >= 11.4.')
    if mode == 'mkl' and (not test_util.IsMklEnabled()):
        self.skipTest('MKL is not enabled.')

def _zeros(shape, dtype):
    """Helper to return (possibly cached) zero tensors in eager mode."""
    if <MASK>:
        return None
    ctx = context.context()
    if not ctx.executing_eagerly():
        return array_ops.zeros(shape, dtype)
    device = ctx.device_name
    if tensor_util.is_tf_type(shape):
        shape_key = shape.ref()
    else:
        shape_key = shape
    cache_key = (shape_key, dtype, device)
    cached = ctx.zeros_cache().get(cache_key)
    if cached is None:
        if dtypes.as_dtype(dtype).is_bool:
            value = False
        else:
            value = 0
        cached = _fast_fill(value, shape, dtype)
        ctx.zeros_cache().put(cache_key, cached)
    return cached

def iter_encode(self, obj):
    """The iterative version of `arff.ArffEncoder.encode`.

        This encodes iteratively a given object and return, one-by-one, the
        lines of the ARFF file.

        :param obj: the object containing the ARFF information.
        :return: (yields) the ARFF file as strings.
        """
    if obj.get('description', None):
        for row in obj['description'].split('\n'):
            yield self._encode_comment(row)
    if not obj.get('relation'):
        raise BadObject('Relation name not found or with invalid value.')
    yield self._encode_relation(obj['relation'])
    yield ''
    if not obj.get('attributes'):
        raise BadObject('Attributes not found.')
    attribute_names = set()
    for attr in obj['attributes']:
        if not isinstance(attr, (tuple, list)) or len(attr) != 2 or (not isinstance(attr[0], str)):
            raise BadObject('Invalid attribute declaration "%s"' % str(attr))
        if <MASK>:
            if attr[1] not in _SIMPLE_TYPES:
                raise BadObject('Invalid attribute type "%s"' % str(attr))
        elif not isinstance(attr[1], (tuple, list)):
            raise BadObject('Invalid attribute type "%s"' % str(attr))
        if attr[0] in attribute_names:
            raise BadObject('Trying to use attribute name "%s" for the second time.' % str(attr[0]))
        else:
            attribute_names.add(attr[0])
        yield self._encode_attribute(attr[0], attr[1])
    yield ''
    attributes = obj['attributes']
    yield _TK_DATA
    if 'data' in obj:
        data = _get_data_object_for_encoding(obj.get('data'))
        yield from data.encode_data(obj.get('data'), attributes)
    yield ''

def run(addr, port, wsgi_handler, ipv6=False, threading=False, on_bind=None, server_cls=WSGIServer):
    server_address = (addr, port)
    if threading:
        httpd_cls = type('WSGIServer', (socketserver.ThreadingMixIn, server_cls), {})
    else:
        httpd_cls = server_cls
    httpd = httpd_cls(server_address, WSGIRequestHandler, ipv6=ipv6)
    if <MASK>:
        on_bind(getattr(httpd, 'server_port', port))
    if threading:
        httpd.daemon_threads = True
    httpd.set_app(wsgi_handler)
    httpd.serve_forever()

def read_column(self, column: str, where=None, start: int | None=None, stop: int | None=None):
    """
        return a single column from the table, generally only indexables
        are interesting
        """
    self.validate_version()
    if not self.infer_axes():
        return False
    if <MASK>:
        raise TypeError('read_column does not currently accept a where clause')
    for a in self.axes:
        if column == a.name:
            if not a.is_data_indexable:
                raise ValueError(f'column [{column}] can not be extracted individually; it is not data indexable')
            c = getattr(self.table.cols, column)
            a.set_info(self.info)
            col_values = a.convert(c[start:stop], nan_rep=self.nan_rep, encoding=self.encoding, errors=self.errors)
            cvs = col_values[1]
            dtype = getattr(self.table.attrs, f'{column}_meta', None)
            return Series(cvs, name=column, copy=False, dtype=dtype)
    raise KeyError(f'column [{column}] not found in the table')

def embedding_lookup_sparse_impl(params, segment_ids, sp_weights, ids, combiner, ignore_weights, max_norm, allow_fast_lookup, partition_strategy, name):
    """Implementation of sparse embedding aggregation."""
    need_sparse_segment_gradient = False
    segment_ids = ops.convert_to_tensor(segment_ids, name='segment_ids')
    if len(params) == 1 and (not isinstance(params[0], (core.Tensor, composite_tensor.CompositeTensor))):
        params = [ops.convert_to_tensor(params[0], name='params')]
    if len(params) == 1 and (not isinstance(params[0], composite_tensor.CompositeTensor)) and (params[0].device == segment_ids.device) and (max_norm is None) and (allow_fast_lookup or (ignore_weights and compat.forward_compatible(2023, 9, 26))):
        idx = ids
        embeddings = params[0]
        if isinstance(embeddings, resource_variable_ops.BaseResourceVariable):
            embeddings = embeddings.read_value_no_copy()
        if not allow_fast_lookup:
            need_sparse_segment_gradient = True
    else:
        (ids, idx) = array_ops.unique(ids)
        embeddings = embedding_lookup(params, ids, partition_strategy=partition_strategy, max_norm=max_norm)
    if not ignore_weights:
        if segment_ids.dtype != dtypes.int32:
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        weights = sp_weights.values
        embeddings = array_ops.gather(embeddings, idx)
        original_dtype = embeddings.dtype
        if embeddings.dtype in (dtypes.float16, dtypes.bfloat16):
            embeddings = math_ops.cast(embeddings, dtypes.float32)
        if weights.dtype != embeddings.dtype:
            weights = math_ops.cast(weights, embeddings.dtype)
        ones_shape = array_ops.expand_dims(array_ops.rank(embeddings) - 1, 0)
        weights_shape = array_ops.shape(weights)
        ones = array_ops.ones(ones_shape, dtype=weights_shape.dtype)
        bcast_weights_shape = array_ops.concat([weights_shape, ones], 0)
        orig_weights_shape = weights.get_shape()
        weights = array_ops.reshape(weights, bcast_weights_shape)
        if embeddings.get_shape().ndims is not None:
            weights.set_shape(orig_weights_shape.concatenate([1 for _ in range(embeddings.get_shape().ndims - 1)]))
        embeddings *= weights
        if combiner == 'sum':
            embeddings = math_ops.segment_sum(embeddings, segment_ids, name=name)
        elif combiner == 'mean':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weight_sum = math_ops.segment_sum(weights, segment_ids)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum, name=name)
        elif combiner == 'sqrtn':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weights_squared = math_ops.pow(weights, 2)
            weight_sum = math_ops.segment_sum(weights_squared, segment_ids)
            weight_sum_sqrt = math_ops.sqrt(weight_sum)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum_sqrt, name=name)
        else:
            assert False, 'Unrecognized combiner'
        if <MASK>:
            embeddings = math_ops.cast(embeddings, original_dtype)
    else:
        if segment_ids.dtype not in (dtypes.int32, dtypes.int64):
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        assert idx is not None
        if combiner == 'sum':
            embeddings = math_ops.sparse_segment_sum(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'mean':
            embeddings = math_ops.sparse_segment_mean(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'sqrtn':
            embeddings = math_ops.sparse_segment_sqrt_n(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        else:
            assert False, 'Unrecognized combiner'
    return embeddings

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name == '__subclasses__' and len(args) == 0 and (not kwargs) and ('__subclasses__' not in self.value.__dict__):
        source = self.source
        if self.source:
            source = AttrSource(self.source, '__subclasses__')
            source = CallFunctionNoArgsSource(source)
        return VariableTracker.build(tx, self.value.__subclasses__(), source)
    elif self.value in {collections.OrderedDict, collections.defaultdict} and name == 'fromkeys':
        from .builtin import BuiltinVariable
        return BuiltinVariable.call_custom_dict_fromkeys(tx, self.value, *args, **kwargs)
    elif self.value is collections.OrderedDict and name == 'move_to_end':
        return args[0].call_method(tx, name, [*args[1:]], kwargs)
    elif name == '__eq__' and len(args) == 1 and hasattr(args[0], 'value'):
        return variables.ConstantVariable(self.value == args[0].value)
    elif name == '__ne__' and len(args) == 1 and hasattr(args[0], 'value'):
        return variables.ConstantVariable(self.value != args[0].value)
    elif <MASK>:
        return variables.BuiltinVariable(dict).call_method(tx, name, args, kwargs)
    elif issubclass(self.value, (set, frozenset)) and name != '__new__':
        return variables.BuiltinVariable(set).call_method(tx, name, args, kwargs)
    elif name == '__new__' and self.value is collections.OrderedDict and isinstance(args[0], UserDefinedClassVariable) and (args[0].value is collections.OrderedDict):
        if kwargs and len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return variables.ConstDictVariable({}, collections.OrderedDict, mutation_type=ValueMutationNew())
    elif name == '__new__' and UserDefinedClassVariable.is_supported_new_method(self.value.__new__):
        return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
    elif name == '__setattr__' and self.ban_mutation:
        unimplemented_v2(gb_type='Class attribute mutation when the __dict__ was already materialized', context=str(self.value), explanation='Dyanmo does not support tracing mutations on a class when its __dict__ is materialized', hints=graph_break_hints.SUPPORTABLE)
    return super().call_method(tx, name, args, kwargs)

def _is_framework_filename(filename):
    """Returns whether a filename should be considered a part of the framework.

  A file is part of the framework if it does not match a pattern in
  _EXTERNAL_FILENAME_PATTERNS and it either matches a pattern in
  _FRAMEWORK_FILENAME_PATTERNS or starts with a _FRAMEWORK_PATH_PREFIXES prefix.

  Args:
    filename: A filename string.

  Returns:
    Whether the filename should be considered to be internal to the
    TensorFlow framework for the purposes of reporting errors.
  """
    for pattern in _EXTERNAL_FILENAME_PATTERNS:
        if <MASK>:
            return False
    for pattern in _FRAMEWORK_FILENAME_PATTERNS:
        if pattern.search(filename):
            return True
    for prefix in _FRAMEWORK_PATH_PREFIXES:
        if filename.startswith(prefix):
            return True
    return False

def get_group(self, mesh_dim: Optional[Union[int, str]]=None) -> ProcessGroup:
    """
            Returns the single ProcessGroup specified by mesh_dim, or, if mesh_dim is not specified and the
            DeviceMesh is 1-dimensional, returns the only ProcessGroup in the mesh.

            Args:
                mesh_dim (str/int, optional): it can be the name of the mesh dimension or the index
                of the mesh dimension. Default is None.

            Returns:
                A :class:`ProcessGroup` object.
            """
    if not hasattr(self, '_dim_group_names'):
        raise RuntimeError('DeviceMesh process groups not initialized!')
    if len(self._layout) > 1 and mesh_dim is None:
        raise RuntimeError(f'Found the DeviceMesh have {len(self._layout)} dimensions', 'Optional kwarg `mesh_dim` needs to be specified when device_mesh.ndim > 1.', 'If you want to get the list of all the ProcessGroups in the DeviceMesh,please use `get_all_groups()` instead.')
    if len(self._layout) == 1 and mesh_dim is None:
        return not_none(_resolve_process_group(self._dim_group_names[0]))
    root_mesh = self._get_root_mesh()
    root_to_flatten_mapping = root_mesh._flatten_mapping
    if <MASK>:
        dim_group_name = root_to_flatten_mapping[mesh_dim]._dim_group_names[0]
        return not_none(_resolve_process_group(dim_group_name))
    else:
        mesh_dim = self._get_mesh_dim_by_name(mesh_dim) if isinstance(mesh_dim, str) else mesh_dim
        assert isinstance(mesh_dim, int)
        return not_none(_resolve_process_group(self._dim_group_names[mesh_dim]))

def widget_attrs(self, widget):
