        if self.min_value is not None:
            attrs['min'] = self.min_value
        if self.max_value is not None:
            attrs['max'] = self.max_value
        if self.step_size is not None:
            attrs['step'] = self.step_size
    return attrs

def full_clean(self):
    """
        Clean all of self.data and populate self._errors and
        self._non_form_errors.
        """
    self._errors = []
    self._non_form_errors = self.error_class(error_class='nonform', renderer=self.renderer)
    empty_forms_count = 0
    if not self.is_bound:
        return
    if not self.management_form.is_valid():
        error = ValidationError(self.error_messages['missing_management_form'], params={'field_names': ', '.join((self.management_form.add_prefix(field_name) for field_name in self.management_form.errors))}, code='missing_management_form')
        self._non_form_errors.append(error)
    for (i, form) in enumerate(self.forms):
        if not form.has_changed() and i >= self.initial_form_count():
            empty_forms_count += 1
        form_errors = form.errors
        if <MASK>:
            continue
        self._errors.append(form_errors)
    try:
        if self.validate_max and self.total_form_count() - len(self.deleted_forms) > self.max_num or self.management_form.cleaned_data[TOTAL_FORM_COUNT] > self.absolute_max:
            raise ValidationError(self.error_messages['too_many_forms'] % {'num': self.max_num}, code='too_many_forms')
        if self.validate_min and self.total_form_count() - len(self.deleted_forms) - empty_forms_count < self.min_num:
            raise ValidationError(self.error_messages['too_few_forms'] % {'num': self.min_num}, code='too_few_forms')
        self.clean()
    except ValidationError as e:
        self._non_form_errors = self.error_class(e.error_list, error_class='nonform', renderer=self.renderer)

@classmethod
def __torch_dispatch__(cls, func, types, args=(), kwargs=None):
    all_args = pytree.arg_tree_leaves(*args, **kwargs or {})
    modes = tuple((e.mode for e in all_args if isinstance(e, CompositeCompliantTensor)))
    if <MASK>:
        raise RuntimeError('Multiple CompositeCompliantTensorModes NYI')
    with modes[0]:
        return func(*args, **kwargs)

def compute_auc(tp, fn, tn, fp, name):
    """Computes the roc-auc or pr-auc based on confusion counts."""
    if <MASK>:
        if summation_method == 'trapezoidal':
            logging.warning('Trapezoidal rule is known to produce incorrect PR-AUCs; please switch to "careful_interpolation" instead.')
        elif summation_method == 'careful_interpolation':
            return interpolate_pr_auc(tp, fp, fn)
    rec = math_ops.divide(tp + epsilon, tp + fn + epsilon)
    if curve == 'ROC':
        fp_rate = math_ops.divide(fp, fp + tn + epsilon)
        x = fp_rate
        y = rec
    else:
        prec = math_ops.divide(tp + epsilon, tp + fp + epsilon)
        x = rec
        y = prec
    if summation_method in ('trapezoidal', 'careful_interpolation'):
        return math_ops.reduce_sum(math_ops.multiply(x[:num_thresholds - 1] - x[1:], (y[:num_thresholds - 1] + y[1:]) / 2.0), name=name)
    elif summation_method == 'minoring':
        return math_ops.reduce_sum(math_ops.multiply(x[:num_thresholds - 1] - x[1:], math_ops.minimum(y[:num_thresholds - 1], y[1:])), name=name)
    elif summation_method == 'majoring':
        return math_ops.reduce_sum(math_ops.multiply(x[:num_thresholds - 1] - x[1:], math_ops.maximum(y[:num_thresholds - 1], y[1:])), name=name)
    else:
        raise ValueError(f"Invalid summation_method: {summation_method} summation_method should be 'trapezoidal', 'careful_interpolation', 'minoring', or 'majoring'.")

def _maybe_convert_for_string_atom(name: str, bvalues: ArrayLike, existing_col, min_itemsize, nan_rep, encoding, errors, columns: list[str]):
    if isinstance(bvalues.dtype, StringDtype):
        bvalues = bvalues.to_numpy()
    if bvalues.dtype != object:
        return bvalues
    bvalues = cast(np.ndarray, bvalues)
    dtype_name = bvalues.dtype.name
    inferred_type = lib.infer_dtype(bvalues, skipna=False)
    if inferred_type == 'date':
        raise TypeError('[date] is not implemented as a table column')
    if inferred_type == 'datetime':
        raise TypeError('too many timezones in this block, create separate data columns')
    if not (inferred_type == 'string' or dtype_name == 'object'):
        return bvalues
    mask = isna(bvalues)
    data = bvalues.copy()
    data[mask] = nan_rep
    if existing_col and mask.any() and (len(nan_rep) > existing_col.itemsize):
        raise ValueError('NaN representation is too large for existing column size')
    inferred_type = lib.infer_dtype(data, skipna=False)
    if inferred_type != 'string':
        for i in range(data.shape[0]):
            col = data[i]
            inferred_type = lib.infer_dtype(col, skipna=False)
            if inferred_type != 'string':
                error_column_label = columns[i] if len(columns) > i else f'No.{i}'
                raise TypeError(f'Cannot serialize the column [{error_column_label}]\nbecause its data contents are not [string] but [{inferred_type}] object dtype')
    data_converted = _convert_string_array(data, encoding, errors).reshape(data.shape)
    itemsize = data_converted.itemsize
    if isinstance(min_itemsize, dict):
        min_itemsize = int(min_itemsize.get(name) or min_itemsize.get('values') or 0)
    itemsize = max(min_itemsize or 0, itemsize)
    if <MASK>:
        eci = existing_col.validate_col(itemsize)
        if eci is not None and eci > itemsize:
            itemsize = eci
    data_converted = data_converted.astype(f'|S{itemsize}', copy=False)
    return data_converted

def __init__(self):
    if self.conf_tmp_path is None:
        import shutil
        import tempfile
        tmp = tempfile.mkdtemp()

        def rm_temp():
            try:
                shutil.rmtree(tmp)
            except OSError:
                pass
        atexit.register(rm_temp)
        self.conf_tmp_path = tmp
    if <MASK>:
        self.conf_cache_factors = [os.path.getmtime(__file__), self.conf_nocache]

def clone_preserve_reinterpret_view(x):
    reinterpret_view_layouts = []
    if isinstance(x, TensorBox) and isinstance(x.data, ir.ReinterpretView):
        x = x.data
        while isinstance(x, ir.ReinterpretView):
            reinterpret_view_layouts.append(x.get_layout())
            x = x.data
        x = TensorBox(x)
    x = clone(x)
    if <MASK>:
        x = x.data
        for layout in reinterpret_view_layouts[::-1]:
            x = ir.ReinterpretView(data=x, layout=layout)
        x = TensorBox(x)
    return x

def raise_for_status(self):
    """Raises :class:`HTTPError`, if one occurred."""
    http_error_msg = ''
    if isinstance(self.reason, bytes):
        try:
            reason = self.reason.decode('utf-8')
        except UnicodeDecodeError:
            reason = self.reason.decode('iso-8859-1')
    else:
        reason = self.reason
    if 400 <= self.status_code < 500:
        http_error_msg = f'{self.status_code} Client Error: {reason} for url: {self.url}'
    elif 500 <= self.status_code < 600:
        http_error_msg = f'{self.status_code} Server Error: {reason} for url: {self.url}'
    if <MASK>:
        raise HTTPError(http_error_msg, response=self)

def _CheckGrayscaleImage(image, require_static=True):
    """Assert that we are working with properly shaped grayscale image.

  Args:
    image: >= 2-D Tensor of size [*, 1]
    require_static: Boolean, whether static shape is required.

  Raises:
    ValueError: if image.shape is not a [>= 2] vector or if
              last dimension is not size 1.

  Returns:
    An empty list, if `image` has fully defined dimensions. Otherwise, a list
    containing an assert op is returned.
  """
    try:
        if image.get_shape().ndims is None:
            image_shape = image.get_shape().with_rank(2)
        else:
            image_shape = image.get_shape().with_rank_at_least(2)
    except ValueError:
        raise ValueError('A grayscale image (shape %s) must be at least two-dimensional.' % image.shape)
    if require_static and (not image_shape.is_fully_defined()):
        raise ValueError("'image' must be fully defined.")
    if image_shape.is_fully_defined():
        if <MASK>:
            raise ValueError('Last dimension of a grayscale image should be size 1.')
    if not image_shape.is_fully_defined():
        return [check_ops.assert_equal(array_ops.shape(image)[-1], 1, message='Last dimension of a grayscale image should be size 1.'), check_ops.assert_greater_equal(array_ops.rank(image), 3, message='A grayscale image must be at least two-dimensional.')]
    else:
        return []

def _clear_registries(self):
    if <MASK>:
        warnings._filters_mutated()
        return
    for module in self._tmp_modules:
        if hasattr(module, '__warningregistry__'):
            module.__warningregistry__.clear()

def _npSoftmax(self, features, dim=-1, log=False):
    if dim == -1:
        dim = len(features.shape) - 1
    one_only_on_dim = list(features.shape)
    one_only_on_dim[dim] = 1
    is_fp16 = features.dtype == np.float16
    if <MASK>:
        features = features.astype(np.float32)
    e = np.exp(features - np.reshape(np.amax(features, axis=dim), one_only_on_dim))
    softmax = e / np.reshape(np.sum(e, axis=dim), one_only_on_dim)
    if log:
        res = np.log(softmax)
    else:
        res = softmax
    if is_fp16:
        res = res.astype(np.float16)
    return res

@staticmethod
def create(func, args, kwargs):
    assert func in [torch.amp.autocast_mode.autocast, torch.cuda.amp.autocast, torch.cpu.amp.autocast]
    bound_args = inspect.signature(func).bind(*args, **kwargs)
    bound_args.apply_defaults()
    target_values = []
    kwargs.clear()
    for key in ['device_type', 'dtype', 'enabled', 'cache_enabled']:
        if <MASK>:
            arg = 'cuda' if func is torch.cuda.amp.autocast else 'cpu'
        else:
            arg = bound_args.arguments[key]
        if isinstance(arg, VariableTracker):
            target_values.append(arg.as_python_constant())
        else:
            target_values.append(arg)
    var = AutocastModeVariable(target_values, initial_values=None, **kwargs)
    return var

def _record_and_ignore_transient_timeouts(self, e):
    """Records observed timeout error and return if it should be ignored."""
    if <MASK>:
        return False
    if not isinstance(e, errors.DeadlineExceededError):
        return False
    with self._transient_timeouts_lock:
        self._transient_timeouts_count += 1
        if self._transient_timeouts_count >= self._transient_timeouts_threshold:
            return False
    return True

def _add(self, op1, op2, operator_name, hints):
    if <MASK>:
        (op_add_to_tensor, op_other) = (op1, op2)
    else:
        (op_add_to_tensor, op_other) = (op2, op1)
    return linear_operator_full_matrix.LinearOperatorFullMatrix(matrix=op_add_to_tensor.add_to_tensor(op_other.to_dense()), is_non_singular=hints.is_non_singular, is_self_adjoint=hints.is_self_adjoint, is_positive_definite=hints.is_positive_definite, name=operator_name)

@_onnx_symbolic('aten::to')
def to(g: jit_utils.GraphContext, self, *args):

    def is_aten_to_device_only(args):
        if len(args) == 4:
            return args[0].node().kind() == 'prim::device' or args[0].type().isSubtypeOf(_C.ListType.ofInts()) or isinstance(args[0].type(), _C.DeviceObjType)
        elif len(args) == 5:
            dtype = symbolic_helper._get_const(args[1], 'i', 'dtype')
            return dtype is None
        elif len(args) in (6, 7):
            dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
            return dtype is None
        return False
    if is_aten_to_device_only(args):
        return self
    if len(args) == 4:
        dtype = args[0]
        if symbolic_helper._is_value(args[0]) and args[0].node().kind() == 'onnx::Constant':
            tval = symbolic_helper._node_get(args[0].node(), 'value')
            if isinstance(tval, torch.Tensor):
                if <MASK>:
                    tval = tval.item()
                    dtype = int(tval)
                else:
                    dtype = tval
        if symbolic_helper._is_value(dtype) or isinstance(dtype, torch.Tensor):
            dtype = _type_utils.JitScalarType.from_value(args[0])
            return g.op('Cast', self, to_i=dtype.onnx_type())
        else:
            return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    elif len(args) == 5:
        dtype = symbolic_helper._get_const(args[1], 'i', 'dtype')
        return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    elif len(args) == 6:
        dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
        return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    elif len(args) == 7:
        dtype = symbolic_helper._get_const(args[0], 'i', 'dtype')
        return g.op('Cast', self, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    return symbolic_helper._onnx_unsupported('Unknown aten::to signature', self)

def match(self, event: _ProfilerEvent) -> bool:
    if <MASK>:
        return False
    if not event.children:
        return False
    for sub_event in traverse_dfs(event.children):
        if sub_event.name == 'aten::zero_' and sub_event.parent.name != 'aten::zeros':
            return True
    return False

def __init__(self, key_transform, *args, **kwargs):
    if <MASK>:
        raise TypeError('Transform should be an instance of KeyTransform in order to use this lookup.')
    key_text_transform = KeyTextTransform(key_transform.key_name, *key_transform.source_expressions, **key_transform.extra)
    super().__init__(key_text_transform, *args, **kwargs)

def astype(self, dtype: AstypeArg, copy: bool=True) -> ArrayLike:
    """
        Coerce this type to another dtype

        Parameters
        ----------
        dtype : numpy dtype or pandas type
        copy : bool, default True
            By default, astype always returns a newly allocated object.
            If copy is set to False and dtype is categorical, the original
            object is returned.
        """
    dtype = pandas_dtype(dtype)
    result: Categorical | np.ndarray
    if self.dtype is dtype:
        result = self.copy() if copy else self
    elif isinstance(dtype, CategoricalDtype):
        dtype = self.dtype.update_dtype(dtype)
        self = self.copy() if copy else self
        result = self._set_dtype(dtype, copy=False)
        wrong = result.isna() & ~self.isna()
        if wrong.any():
            warnings.warn("Constructing a Categorical with a dtype and values containing non-null entries not in that dtype's categories is deprecated and will raise in a future version.", Pandas4Warning, stacklevel=find_stack_level())
    elif <MASK>:
        return super().astype(dtype, copy=copy)
    elif dtype.kind in 'iu' and self.isna().any():
        raise ValueError('Cannot convert float NaN to integer')
    elif len(self.codes) == 0 or len(self.categories) == 0:
        if not copy:
            result = np.asarray(self, dtype=dtype)
        else:
            result = np.array(self, dtype=dtype)
    else:
        new_cats = self.categories._values
        try:
            new_cats = new_cats.astype(dtype=dtype, copy=copy)
            fill_value = self.categories._na_value
            if not is_valid_na_for_dtype(fill_value, dtype):
                fill_value = lib.item_from_zerodim(np.array(self.categories._na_value).astype(dtype))
        except (TypeError, ValueError) as err:
            msg = f'Cannot cast {self.categories.dtype} dtype to {dtype}'
            raise ValueError(msg) from err
        result = take_nd(new_cats, ensure_platform_int(self._codes), fill_value=fill_value)
    return result

def arg_parser_unpack_method(t: Type, default: str | None, default_init: str | None, *, symint: bool=True) -> str:
    has_default_init = default_init is not None
    if has_default_init and str(t) not in ('ScalarType?', 'ScalarType', 'Device', 'Device?', 'Layout', 'Layout?', 'bool', 'bool?'):
        raise RuntimeError(f"type '{t}' does not supported unpacking with default")
    if isinstance(t, BaseType):
        if t.name in [BaseTy.Tensor, BaseTy.Stream, BaseTy.Storage, BaseTy.Scalar, BaseTy.Dimname]:
            return t.name.name.lower()
        elif t.name == BaseTy.ScalarType:
            return 'scalartypeWithDefault' if has_default_init else 'scalartype'
        elif t.name == BaseTy.Device:
            return 'deviceWithDefault' if has_default_init else 'device'
        elif t.name == BaseTy.DeviceIndex:
            return 'toInt64'
        elif t.name == BaseTy.int:
            return 'toInt64'
        elif t.name == BaseTy.SymInt:
            return 'toSymInt' if symint else 'toInt64'
        elif <MASK>:
            return 'toBoolWithDefault' if has_default_init else 'toBool'
        elif t.name == BaseTy.float:
            return 'toDouble'
        elif t.name == BaseTy.str:
            return 'stringView'
        elif t.name == BaseTy.Layout:
            return 'layoutWithDefault' if has_default_init else 'layout'
        elif t.name == BaseTy.MemoryFormat:
            return 'memoryformat'
    elif isinstance(t, OptionalType):
        if str(t.elem) == 'Tensor':
            return 'optionalTensor'
        elif str(t.elem) == 'Generator':
            return 'generator'
        elif str(t.elem) == 'Dimname[]':
            return 'toDimnameListOptional'
        elif not has_default_init and default in (None, 'None', '::std::nullopt', 'std::nullopt'):
            return arg_parser_unpack_method(t.elem, None, None, symint=symint) + 'Optional'
        else:
            return arg_parser_unpack_method(t.elem, default, default_init, symint=symint)
    elif isinstance(t, ListType):
        if str(t.elem) == 'Tensor':
            return f'tensorlist_n<{t.size}>' if t.size is not None else 'tensorlist'
        elif str(t.elem) == 'Tensor?':
            return 'list_of_optional_tensors'
        elif str(t.elem) == 'Dimname':
            return 'dimnamelist'
        elif str(t.elem) == 'int':
            return 'intlist'
        elif str(t.elem) == 'float':
            return 'doublelist'
        elif str(t.elem) == 'SymInt':
            return 'symintlist' if symint else 'intlist'
        elif str(t.elem) == 'Scalar':
            return 'scalarlist'
    raise RuntimeError(f"type '{t}' is not supported by PythonArgParser")

def _remove_redundant_quantize_ops_per_subgraph(model, subgraph_index, signature_index):
    """Remove redundant quantize ops per subgraph."""
    subgraph = model.subgraphs[subgraph_index]
    tensors = subgraph.tensors
    operators = subgraph.operators
    quant_opcode_idxs = get_quantize_opcode_idx(model)
    dequant_opcode_idxs = get_dequantize_opcode_idx(model)
    all_quant_ops = []
    redundant_quant_tensors = {}
    output_dequant_tensors = {}
    for op in operators:
        if op.opcodeIndex in quant_opcode_idxs:
            all_quant_ops.append(op)
            input_tensor = tensors[op.inputs[0]]
            output_tensor = tensors[op.outputs[0]]
            input_type = _convert_tflite_enum_type_to_tf_type(input_tensor.type)
            output_type = _convert_tflite_enum_type_to_tf_type(output_tensor.type)
            if input_type != dtypes.float32 and output_type != dtypes.float32:
                redundant_quant_tensors[op.inputs[0]] = op
        if op.opcodeIndex in dequant_opcode_idxs and op.outputs[0] in subgraph.outputs:
            output_dequant_tensors[op.inputs[0]] = op
    for op in all_quant_ops:
        output_tensor_idx = op.outputs[0]
        if output_tensor_idx in redundant_quant_tensors:
            requantize_op = redundant_quant_tensors[output_tensor_idx]
            if model.signatureDefs:
                signature_def = model.signatureDefs[0]
                for output in signature_def.outputs:
                    if output.tensorIndex == op.outputs[0]:
                        output.tensorIndex = op.inputs[0]
            deleted_tensor = requantize_op.inputs[0]
            requantize_op.inputs[0] = op.inputs[0]
            for op_user in operators:
                if deleted_tensor in op_user.inputs and op_user != requantize_op:
                    for (idx, input_tensor) in enumerate(op_user.inputs):
                        if input_tensor == deleted_tensor:
                            op_user.inputs[idx] = requantize_op.outputs[0]
            operators.remove(op)
    for op in all_quant_ops:
        output_tensor_idx = op.outputs[0]
        if output_tensor_idx in output_dequant_tensors:
            dequant_op = output_dequant_tensors[output_tensor_idx]
            subgraph.outputs[subgraph.outputs == dequant_op.outputs[0]] = op.inputs[0]
            if signature_index >= 0:
                signature_def = model.signatureDefs[signature_index]
                for output in signature_def.outputs:
                    if <MASK>:
                        output.tensorIndex = op.inputs[0]
            operators.remove(op)
            operators.remove(dequant_op)

def prepare_local_plan(self, plan: SavePlan) -> SavePlan:
    self.fs.mkdir(self.path)
    if <MASK>:
        if self.overwrite:
            warnings.warn(f'Detected an existing checkpoint in {self.path}, overwriting since self.overwrite={self.overwrite!r}. Past version 2.5 of PyTorch, `overwrite` will default to False. Set this variable to True to maintain this functionality or False to raise when an existing checkpoint is found.')
        else:
            raise RuntimeError(f'Checkpoint already exists and self.overwrite={self.overwrite!r}.')
    if self.rank is not None and (not self.use_collectives):
        plan = dataclasses.replace(plan, storage_data=_StoragePrefix(f'__{self.rank}_'))
    return plan

def _validate_X_predict(self, X, check_input):
    """Validate the training data on predict (probabilities)."""
    if <MASK>:
        if self._support_missing_values(X):
            ensure_all_finite = 'allow-nan'
        else:
            ensure_all_finite = True
        X = validate_data(self, X, dtype=DTYPE, accept_sparse='csr', reset=False, ensure_all_finite=ensure_all_finite)
        if issparse(X) and (X.indices.dtype != np.intc or X.indptr.dtype != np.intc):
            raise ValueError('No support for np.int64 index based sparse matrices')
    else:
        _check_n_features(self, X, reset=False)
    return X

def _try_replicate_spec_for_scalar_tensor(self, op_call: torch._ops.OpOverload, tensor_arg: torch.Tensor, compute_mesh: DeviceMesh) -> DTensorSpec:
    if <MASK>:
        warnings.warn('Found a non-scalar tensor with numel=1 and ndim!=0, we are implicitly creating a replicated DTensor for it. However, please consider changing it to a scalar tensor or explicitly create a DTensor under distributed environment.')
    if tensor_arg.numel() == 1 or self._allow_implicit_replication:
        replication_spec = DTensorSpec(compute_mesh, (Replicate(),) * compute_mesh.ndim, tensor_meta=TensorMeta(shape=tensor_arg.shape, stride=tensor_arg.stride(), dtype=tensor_arg.dtype))
    else:
        raise RuntimeError(f'{op_call}: got mixed torch.Tensor and DTensor, need to convert all torch.Tensor to DTensor before calling distributed operators! Please see https://docs.pytorch.org/docs/main/distributed.tensor.html#mixed-tensor-and-dtensor-operations for more details.')
    return replication_spec

def __getitem__(self, indx):
    """
        x.__getitem__(y) <==> x[y]

        Return the item described by i, as a masked array.

        """
    dout = self.data[indx]
    _mask = self._mask

    def _is_scalar(m):
        return not isinstance(m, np.ndarray)

    def _scalar_heuristic(arr, elem):
        """
            Return whether `elem` is a scalar result of indexing `arr`, or None
            if undecidable without promoting nomask to a full mask
            """
        if not isinstance(elem, np.ndarray):
            return True
        elif arr.dtype.type is np.object_:
            if <MASK>:
                return True
        elif type(arr).__getitem__ == ndarray.__getitem__:
            return False
        return None
    if _mask is not nomask:
        mout = _mask[indx]
        scalar_expected = _is_scalar(mout)
    else:
        mout = nomask
        scalar_expected = _scalar_heuristic(self.data, dout)
        if scalar_expected is None:
            scalar_expected = _is_scalar(getmaskarray(self)[indx])
    if scalar_expected:
        if isinstance(dout, np.void):
            return mvoid(dout, mask=mout, hardmask=self._hardmask)
        elif self.dtype.type is np.object_ and isinstance(dout, np.ndarray) and (dout is not masked):
            if mout:
                return MaskedArray(dout, mask=True)
            else:
                return dout
        elif mout:
            return masked
        else:
            return dout
    else:
        dout = dout.view(type(self))
        dout._update_from(self)
        if is_string_or_list_of_strings(indx):
            if self._fill_value is not None:
                dout._fill_value = self._fill_value[indx]
                if not isinstance(dout._fill_value, np.ndarray):
                    raise RuntimeError('Internal NumPy error.')
                if dout._fill_value.ndim > 0:
                    if not (dout._fill_value == dout._fill_value.flat[0]).all():
                        warnings.warn(f'Upon accessing multidimensional field {indx!s}, need to keep dimensionality of fill_value at 0. Discarding heterogeneous fill_value and setting all to {dout._fill_value[0]!s}.', stacklevel=2)
                    dout._fill_value = dout._fill_value.flat[0:1].squeeze(axis=0)
            dout._isfield = True
        if mout is not nomask:
            dout._mask = reshape(mout, dout.shape)
            dout._sharedmask = True
    return dout

def _display_window(self, pf: PythonFile, r: LintResult) -> Iterator[str]:
    """Display a window onto the code with an error"""
    if <MASK>:
        yield f'{pf.path}:{r.line}: {r.name}'
    else:
        yield f'{pf.path}:{r.line}:{r.char + 1}: {r.name}'
    begin = max((r.line or 0) - ErrorLines.BEFORE, 1)
    end = min(begin + ErrorLines.WINDOW, 1 + len(pf.lines))
    for lineno in range(begin, end):
        source_line = pf.lines[lineno - 1].rstrip()
        yield f'{lineno:5} | {source_line}'
        if lineno == r.line:
            spaces = 8 + (r.char or 0)
            carets = len(source_line) if r.char is None else r.length or 1
            yield (spaces * ' ' + carets * '^')

def nargsort(items: ArrayLike | Index | Series, kind: SortKind='quicksort', ascending: bool=True, na_position: str='last', key: Callable | None=None, mask: npt.NDArray[np.bool_] | None=None) -> npt.NDArray[np.intp]:
    """
    Intended to be a drop-in replacement for np.argsort which handles NaNs.

    Adds ascending, na_position, and key parameters.

    (GH #6399, #5231, #27237)

    Parameters
    ----------
    items : np.ndarray, ExtensionArray, Index, or Series
    kind : {'quicksort', 'mergesort', 'heapsort', 'stable'}, default 'quicksort'
    ascending : bool, default True
    na_position : {'first', 'last'}, default 'last'
    key : Optional[Callable], default None
    mask : Optional[np.ndarray[bool]], default None
        Passed when called by ExtensionArray.argsort.

    Returns
    -------
    np.ndarray[np.intp]
    """
    if key is not None:
        items = ensure_key_mapped(items, key)
        return nargsort(items, kind=kind, ascending=ascending, na_position=na_position, key=None, mask=mask)
    if isinstance(items, ABCRangeIndex):
        return items.argsort(ascending=ascending)
    elif not isinstance(items, ABCMultiIndex):
        items = extract_array(items)
    else:
        raise TypeError('nargsort does not support MultiIndex. Use index.sort_values instead.')
    if <MASK>:
        mask = np.asarray(isna(items))
    if not isinstance(items, np.ndarray):
        return items.argsort(ascending=ascending, kind=kind, na_position=na_position)
    idx = np.arange(len(items))
    non_nans = items[~mask]
    non_nan_idx = idx[~mask]
    nan_idx = np.nonzero(mask)[0]
    if not ascending:
        non_nans = non_nans[::-1]
        non_nan_idx = non_nan_idx[::-1]
    indexer = non_nan_idx[non_nans.argsort(kind=kind)]
    if not ascending:
        indexer = indexer[::-1]
    if na_position == 'last':
        indexer = np.concatenate([indexer, nan_idx])
    elif na_position == 'first':
        indexer = np.concatenate([nan_idx, indexer])
    else:
        raise ValueError(f'invalid na_position: {na_position}')
    return ensure_platform_int(indexer)

def _as_strided_meta(a: TensorLikeType, size: ShapeType, stride: StrideType, storage_offset: int) -> TensorLikeType:
    assert len(size) == len(stride)
    assert storage_offset >= 0
    utils.validate_strides(stride)
    utils.validate_shape(size)
    if <MASK>:
        pass
    elif isinstance(a, torch.Tensor):
        utils.check_in_bounds_for_storage(a._typed_storage(), size, stride, storage_offset)
    return torch.as_strided(a, size, stride, storage_offset)

def download_reports(commit_sha, configs=('dynamo39', 'dynamo313', 'eager313')):
    log_dir = 'tmp_test_reports_' + commit_sha

    def subdir_path(config):
        return f'{log_dir}/{config}'
    for config in configs:
        assert config in CONFIGS.keys(), config
    subdir_paths = [subdir_path(config) for config in configs]
    missing_configs = []
    for (config, path) in zip(configs, subdir_paths):
        if os.path.exists(path):
            continue
        missing_configs.append(config)
    if len(missing_configs) == 0:
        print(f'All required logs appear to exist, not downloading again. Run `rm -rf {log_dir}` if this is not the case')
        return subdir_paths
    output = subprocess.check_output(['gh', 'run', 'list', '-c', commit_sha, '-w', 'pull', '--json', 'databaseId']).decode()
    workflow_run_id = str(json.loads(output)[0]['databaseId'])
    output = subprocess.check_output(['gh', 'run', 'view', workflow_run_id])
    workflow_jobs = parse_workflow_jobs(output)
    print('found the following workflow jobs:')
    pprint.pprint(workflow_jobs)
    required_jobs = []
    for config in configs:
        required_jobs.extend(list(CONFIGS[config]))
    for job in required_jobs:
        assert job in workflow_jobs, f'{job} not found, is the commit_sha correct? has the job finished running? The GitHub API may take a couple minutes to update.'
    listings = requests.get(f'https://hud.pytorch.org/api/artifacts/s3/{workflow_run_id}').json()

    def download_report(job_name, subdir):
        job_id = workflow_jobs[job_name]
        for listing in listings:
            name = listing['name']
            if not name.startswith('test-reports-'):
                continue
            if <MASK>:
                url = listing['url']
                subprocess.run(['wget', '-P', subdir, url], check=True)
                path_to_zip = f'{subdir}/{name}'
                dir_name = path_to_zip[:-4]
                subprocess.run(['unzip', path_to_zip, '-d', dir_name], check=True)
                return
        raise AssertionError('should not be hit')
    if not os.path.exists(log_dir):
        os.mkdir(log_dir)
    for config in set(configs) - set(missing_configs):
        print(f'Logs for {config} already exist, not downloading again. Run `rm -rf {subdir_path(config)}` if this is not the case.')
    for config in missing_configs:
        subdir = subdir_path(config)
        os.mkdir(subdir)
        job_names = CONFIGS[config]
        for job_name in job_names:
            download_report(job_name, subdir)
    return subdir_paths

def create_index(self, columns=None, optlevel=None, kind: str | None=None) -> None:
    """
        Create a pytables index on the specified columns.

        Parameters
        ----------
        columns : None, bool, or listlike[str]
            Indicate which columns to create an index on.

            * False : Do not create any indexes.
            * True : Create indexes on all columns.
            * None : Create indexes on all columns.
            * listlike : Create indexes on the given columns.

        optlevel : int or None, default None
            Optimization level, if None, pytables defaults to 6.
        kind : str or None, default None
            Kind of index, if None, pytables defaults to "medium".

        Raises
        ------
        TypeError if trying to create an index on a complex-type column.

        Notes
        -----
        Cannot index Time64Col or ComplexCol.
        Pytables must be >= 3.0.
        """
    if not self.infer_axes():
        return
    if columns is False:
        return
    if columns is None or columns is True:
        columns = [a.cname for a in self.axes if a.is_data_indexable]
    if not isinstance(columns, (tuple, list)):
        columns = [columns]
    kw = {}
    if optlevel is not None:
        kw['optlevel'] = optlevel
    if <MASK>:
        kw['kind'] = kind
    table = self.table
    for c in columns:
        v = getattr(table.cols, c, None)
        if v is not None:
            if v.is_indexed:
                index = v.index
                cur_optlevel = index.optlevel
                cur_kind = index.kind
                if kind is not None and cur_kind != kind:
                    v.remove_index()
                else:
                    kw['kind'] = cur_kind
                if optlevel is not None and cur_optlevel != optlevel:
                    v.remove_index()
                else:
                    kw['optlevel'] = cur_optlevel
            if not v.is_indexed:
                if v.type.startswith('complex'):
                    raise TypeError('Columns containing complex values can be stored but cannot be indexed when using table format. Either use fixed format, set index=False, or do not include the columns containing complex values to data_columns when initializing the table.')
                v.create_index(**kw)
        elif c in self.non_index_axes[0][1]:
            raise AttributeError(f'column {c} is not a data_column.\nIn order to read column {c} you must reload the dataframe \ninto HDFStore and include {c} with the data_columns argument.')

@final
def _dti_setop_align_tzs(self, other: Index, setop: str_t) -> tuple[Index, Index]:
    """
        With mismatched timezones, cast both to UTC.
        """
    if <MASK>:
        if self.tz == other.tz:
            return (self, other)
        else:
            left = self.tz_convert('UTC')
            right = other.tz_convert('UTC')
            return (left, right)
    return (self, other)

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    from ..exc import unimplemented_v2
    from ..utils import numpy_method_wrapper
    (args, kwargs) = self.patch_args(name, args, kwargs)
    if name == 'astype':
        from .builtin import BuiltinVariable
        dtype_arg = None
        if 'dtype' in kwargs:
            dtype_arg = kwargs['dtype']
        elif len(args) > 0:
            dtype_arg = args[0]
        is_object_str = isinstance(dtype_arg, ConstantVariable) and dtype_arg.value == 'O'
        is_object_type = isinstance(dtype_arg, BuiltinVariable) and dtype_arg.fn is object
        if <MASK>:
            unimplemented_v2(gb_type='ndarray.astype(object)', context=f'call_method {self} {name} {args} {kwargs}', explanation="`ndarray.astype('O')` or `ndarray.astype(object)` is not supported by torch.compile, as there is no equivalent to object type in torch.Tensor. This will be executed eagerly.", hints=[*graph_break_hints.FUNDAMENTAL])
    if name in ['__len__', 'size', 'tolist']:
        return super().call_method(tx, name, args, kwargs)
    if name in ('tostring', 'tobytes', '__delattr__'):
        unimplemented_v2(gb_type='Unsupported ndarray method call', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'`ndarray.{name}()` is not modelled in `torch._numpy`.', hints=[])
    proxy = tx.output.create_proxy('call_function', numpy_method_wrapper(name), *proxy_args_kwargs([self] + list(args), kwargs))
    return NumpyNdarrayVariable.create(tx, proxy)

def prepare_url(self, url, params):
    """Prepares the given HTTP URL."""
    if <MASK>:
        url = url.decode('utf8')
    else:
        url = str(url)
    url = url.lstrip()
    if ':' in url and (not url.lower().startswith('http')):
        self.url = url
        return
    try:
        (scheme, auth, host, port, path, query, fragment) = parse_url(url)
    except LocationParseError as e:
        raise InvalidURL(*e.args)
    if not scheme:
        raise MissingSchema(f'Invalid URL {url!r}: No scheme supplied. Perhaps you meant https://{url}?')
    if not host:
        raise InvalidURL(f'Invalid URL {url!r}: No host supplied')
    if not unicode_is_ascii(host):
        try:
            host = self._get_idna_encoded_host(host)
        except UnicodeError:
            raise InvalidURL('URL has an invalid label.')
    elif host.startswith(('*', '.')):
        raise InvalidURL('URL has an invalid label.')
    netloc = auth or ''
    if netloc:
        netloc += '@'
    netloc += host
    if port:
        netloc += f':{port}'
    if not path:
        path = '/'
    if isinstance(params, (str, bytes)):
        params = to_native_string(params)
    enc_params = self._encode_params(params)
    if enc_params:
        if query:
            query = f'{query}&{enc_params}'
        else:
            query = enc_params
    url = requote_uri(urlunparse([scheme, netloc, path, None, query, fragment]))
    self.url = url

def sample_kwargs_vector_norm(t, **kwargs):

    def ords():
        has_id = (6, 4, 2, 1, 0, 0.9)
        no_id = (inf, -2.1, -inf)
        if t.numel() == 0:
            dim = kwargs.get('dim')
            if dim is None:
                return has_id
            if not isinstance(dim, Iterable):
                dim = (dim,)
            for d in dim:
                if <MASK>:
                    return has_id
        return has_id + no_id
    return (((), dict(ord=o)) for o in ords())

