@classmethod
def from_db(cls, db, field_names, values, *, fetch_mode=None):
    if len(values) != len(cls._meta.concrete_fields):
        values_iter = iter(values)
        values = [next(values_iter) if f.attname in field_names else DEFERRED for f in cls._meta.concrete_fields]
    new = cls(*values)
    new._state.adding = False
    new._state.db = db
    if <MASK>:
        new._state.fetch_mode = fetch_mode
    return new

def add(self, *objs, bulk=True):
    self._check_fk_val()
    self._remove_prefetched_objects()
    db = router.db_for_write(self.model, instance=self.instance)

    def check_and_update_obj(obj):
        if not isinstance(obj, self.model):
            raise TypeError("'%s' instance expected, got %r" % (self.model._meta.object_name, obj))
        setattr(obj, self.field.name, self.instance)
    if <MASK>:
        pks = []
        for obj in objs:
            check_and_update_obj(obj)
            if obj._state.adding or obj._state.db != db:
                raise ValueError("%r instance isn't saved. Use bulk=False or save the object first." % obj)
            pks.append(obj.pk)
        self.model._base_manager.using(db).filter(pk__in=pks).update(**{self.field.name: self.instance})
    else:
        with transaction.atomic(using=db, savepoint=False):
            for obj in objs:
                check_and_update_obj(obj)
                obj.save()

def maybe_convert_to_ragged(is_ragged_input, output, nested_row_lengths, go_backwards=False):
    """Converts any ragged input back to its initial structure."""
    if not is_ragged_input:
        return output
    if <MASK>:
        output = reverse(output, [1])
        ragged = ragged_tensor.RaggedTensor.from_tensor(output, nested_row_lengths)
        return reverse(ragged, [1])
    else:
        return ragged_tensor.RaggedTensor.from_tensor(output, nested_row_lengths)

def _serialize_hyperparameter(self, hyperparameter_name):
