@staticmethod
def _multilayer_second_step_hint(split: _IntLike, numel_hint: int, reduction_hint: ReductionHint) -> ReductionHint:
    if split == -1:
        return reduction_hint
    if split <= 512 and numel_hint <= 512 and (reduction_hint == ReductionHint.OUTER):
        return ReductionHint.OUTER_TINY
    if <MASK>:
        return ReductionHint.OUTER_TINY
    return reduction_hint

def _maybe_record_pointwise_barrier(func: object, proxy_mode: ProxyTorchDispatchMode) -> None:
    """
    Records operators whose tensor outputs or inputs are fp16/bf16 so downstream pointwise code can
    emulate eager's rounding behavior when emulate_precision_casts is enabled.
    """
    if proxy_mode.decomp_layers or not proxy_mode.emulate_precision_casts:
        return
    if not isinstance(func, torch._ops.OpOverload):
        return
    last_node = next(iter(reversed(proxy_mode.tracer.graph.nodes)))
    t = last_node.meta.get('val')
    low_pr_fp = (torch.bfloat16, torch.float16)
    output_low_precision = isinstance(t, torch.Tensor) and t.dtype in low_pr_fp
    if <MASK>:
        for input_node in last_node.all_input_nodes:
            val = input_node.meta.get('val') if hasattr(input_node, 'meta') else None
            if isinstance(val, torch.Tensor) and val.dtype in low_pr_fp:
                output_low_precision = True
                break
    if not output_low_precision:
        return
    last_node.meta['low_precision_pointwise_barrier'] = True

def bsr_dense_addmm_meta(M, K, N, Ms, Ks, beta, alpha, SPLIT_N=None, GROUP_SIZE_ROW=None, num_warps=None, num_stages=None, sparsity=None, dtype=None, out_dtype=None, _version=0, **extra):
    if dtype is None:
        dtype = torch.float16
    if out_dtype is None:
        out_dtype = dtype
    if sparsity is None:
        sparsity = 0.5
    if {SPLIT_N, num_warps, num_stages, GROUP_SIZE_ROW} == {None}:
        device_name = torch.cuda.get_device_name()
        key = (M, K, N, Ms, Ks, beta == 0, beta == 1, alpha == 1)
        if dtype is out_dtype:
            version_dtype = dtype
        else:
            version_dtype = (dtype, out_dtype)
        meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, version_dtype, sparsity))
        if <MASK>:
            meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, version_dtype, 0.5))
        if meta is None and dtype is not out_dtype:
            meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, dtype, 0.5))
        if meta is None:
            matching_meta = get_meta('bsr_dense_addmm', (*key[:2], '*', *key[3:]), device_name, version=(_version, version_dtype, 0.5))
            if matching_meta is None and dtype is not out_dtype:
                matching_meta = get_meta('bsr_dense_addmm', (*key[:2], '*', *key[3:]), device_name, version=(_version, dtype, 0.5))
            for mkey in sorted(matching_meta or {}):
                meta_ = matching_meta[mkey]
                n = mkey[2]
                split_n = meta_['SPLIT_N']
                c = n // split_n
                if N % c == 0 and n <= N:
                    meta = dict(meta_)
                    meta['SPLIT_N'] = N // c
        if meta is not None:
            meta.update(**extra)
            return meta
        else:
            warn_once(f'bsr_dense_addmm uses non-optimal triton kernel parameters for M={M!r} K={K!r} N={N!r} Ms={Ms!r}, Ks={Ks!r} beta={beta!r} alpha={alpha!r} dtype={dtype!r} out_dtype={out_dtype!r}')
    SPLIT_N = SPLIT_N or max(N // Ms, 1)
    GROUP_SIZE_ROW = GROUP_SIZE_ROW or 4
    num_stages = num_stages or 1
    num_warps = num_warps or 4
    return dict(SPLIT_N=SPLIT_N, GROUP_SIZE_ROW=GROUP_SIZE_ROW, num_stages=num_stages, num_warps=num_warps, **extra)

def call(self, graph_module) -> PassResult:
    self.existing_inline_assertions = _get_existing_inline_assertions(graph_module, self.range_constraints)
    for module in graph_module.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if 'val' not in node.meta:
                continue
            val = node.meta['val']

            def add_assertions(val):
                call_backs: list[Callable] = []
                messages: list[str] = []
                if isinstance(val, (torch.SymInt, torch.SymFloat, torch.SymBool)):
                    symbol = val.node.expr
                    if symbol in self.existing_inline_assertions:
                        return (call_backs, messages)
                    if isinstance(symbol, sympy.Symbol) and free_unbacked_symbols(symbol):
                        if symbol in self._asserts_generated_unbacked_symbols:
                            return (call_backs, messages)
                        constraint = self.range_constraints[symbol]
                        (min_val, max_val) = _convert_range_to_int(constraint)
                        assert_msg = f' is outside of inline constraint [{min_val}, {max_val}].'
                        call_backs.append(partial(self._assert_range_constraint, lower=min_val, upper=max_val))
                        messages.append(assert_msg)
                        self._asserts_generated_unbacked_symbols.add(symbol)
                elif isinstance(val, torch.Tensor):
                    for (i, sym) in enumerate(val.shape):
                        (cbs, msgs) = add_assertions(sym)
                        for (cb, msg) in zip(cbs, msgs):

                            def sym_size_cb(node, assert_msg, dim):
                                with node.graph.inserting_after(node):
                                    dim_node = module.graph.call_function(torch.ops.aten.sym_size.int, (node, dim), {})
                                cb(node=dim_node, assert_msg=assert_msg)
                            call_backs.append(partial(sym_size_cb, dim=i))
                            messages.append(f'.shape[{i}]' + msg)
                return (call_backs, messages)
            (callbacks, messages) = add_assertions(val)
            for (cb, msg) in zip(callbacks, messages):
                cb(node=node, assert_msg=f'{node}' + msg)
        module.recompile()
    if self.counter == 0 and type(self) is _AddRuntimeAssertionsForInlineConstraintsPass:
        return PassResult(graph_module, False)
    for node in graph_module.graph.nodes:
        if <MASK>:
            node.meta['stack_trace'] = ''.join(traceback.format_stack(limit=1))
    return PassResult(graph_module, True)

def _get_tensor_ops():

    def is_tensor_method(schema):
        if <MASK>:
            return False
        self = schema.arguments[0]
        if self.name != 'self':
            return False
        if not self.type.isSubtypeOf(torch._C.TensorType.get()):
            return False
        return True
    methods = []
    for elem in dir(torch.Tensor):
        if not _hidden(elem):
            schemas = torch._C._jit_get_schemas_for_operator('aten::' + elem)
            for schema in schemas:
                if is_tensor_method(schema):
                    methods.append(_emit_schema('Tensor', elem, schema, arg_start=1))
    return ('Supported Tensor Methods', methods)

def patterns_to_regex(allowed_patterns: list[str]) -> Any:
    """
    pattern is glob-like, i.e. the only special sequences it has are:
      - ? - matches single character
      - * - matches any non-folder separator characters or no character
      - ** - matches any characters or no character
      Assuming that patterns are free of braces and backslashes
      the only character that needs to be escaped are dot and plus
    """
    rc = '('
    for (idx, pattern) in enumerate(allowed_patterns):
        if <MASK>:
            rc += '|'
        pattern_ = PeekableIterator(pattern)
        assert not any((c in pattern for c in '{}()[]\\'))
        for c in pattern_:
            if c == '.':
                rc += '\\.'
            elif c == '+':
                rc += '\\+'
            elif c == '*':
                if pattern_.peek() == '*':
                    next(pattern_)
                    rc += '.*'
                else:
                    rc += '[^/]*'
            else:
                rc += c
    rc += ')'
    return re.compile(rc)

def override_binary_operator_helper(func, op_name, clazz_object=tensor_lib.Tensor):
    """Register operators with different tensor and scalar versions.

  If `clazz_object` is `SparseTensor`, assumes `func` takes `(sp_indices,
  sp_values, sp_shape, dense)` and outputs `(new_sp_values)`.

  Args:
    func: the operator
    op_name: name of the operator being overridden
    clazz_object: class to override for.  Either `Tensor` or `SparseTensor`.
  """

    @traceback_utils.filter_traceback
    def binary_op_wrapper(x, y):
        with ops.name_scope(None, op_name, [x, y]) as name:
            try:
                (x, y) = maybe_promote_tensors(x, y)
                return func(x, y, name=name)
            except (TypeError, ValueError) as e:
                if hasattr(type(y), '__r%s__' % op_name):
                    try:
                        r_op = getattr(y, '__r%s__' % op_name)
                        out = r_op(x)
                        if <MASK>:
                            raise
                        return out
                    except (TypeError, ValueError):
                        raise e
                else:
                    raise

    @traceback_utils.filter_traceback
    def binary_op_wrapper_sparse(sp_x, y):
        with ops.name_scope(None, op_name, [sp_x, y]) as name:
            y = ops.convert_to_tensor(y, dtype=sp_x.dtype.base_dtype, name='y')
            return clazz_object(sp_x.indices, func(sp_x.indices, sp_x.values, sp_x.dense_shape, y, name=name), sp_x.dense_shape)

    @traceback_utils.filter_traceback
    def r_binary_op_wrapper(y, x):
        with ops.name_scope(None, op_name, [x, y]) as name:
            (y, x) = maybe_promote_tensors(y, x, force_same_dtype=True)
            return func(x, y, name=name)
    try:
        doc = func.__doc__
    except AttributeError:
        doc = None
    binary_op_wrapper.__doc__ = doc
    r_binary_op_wrapper.__doc__ = doc
    binary_op_wrapper_sparse.__doc__ = doc
    if clazz_object is tensor_lib.Tensor:
        clazz_object._override_operator('__%s__' % op_name, binary_op_wrapper)
        del binary_op_wrapper
        clazz_object._override_operator('__r%s__' % op_name, r_binary_op_wrapper)
        del r_binary_op_wrapper
    else:
        clazz_object._override_operator('__%s__' % op_name, binary_op_wrapper_sparse)
        del binary_op_wrapper_sparse

@staticmethod
def color_segment(segment, value, best_value):
    if value <= best_value * 1.01 or value <= best_value + 1e-07:
        return BEST + BOLD + segment + TERMINATE * 2
    if value <= best_value * 1.1:
        return GOOD + BOLD + segment + TERMINATE * 2
    if value >= best_value * 5:
        return VERY_BAD + BOLD + segment + TERMINATE * 2
    if <MASK>:
        return BAD + segment + TERMINATE * 2
    return segment

def str2bool(value: Optional[str]) -> bool:
    """Convert environment variables to boolean values."""
    if <MASK>:
        return False
    if not isinstance(value, str):
        raise ValueError(f'Expected a string value for boolean conversion, got {type(value)}')
    value = value.strip().lower()
    true_value_set = {'1', 'true', 't', 'yes', 'y', 'on', 'enable', 'enabled', 'found'}
    false_value_set = {'0', 'false', 'f', 'no', 'n', 'off', 'disable'}
    if value in true_value_set:
        return True
    if value in false_value_set:
        return False
    raise ValueError(f'Invalid string value for boolean conversion: {value}')

def solve_for_tiling(expr: sympy.Expr) -> Optional[sympy.Expr]:
    """
    Giving an expr with a single free symbol, try to find a tiling that would
    make the expression coalesced with respect to that symbol.

    Tiling an expression `x` by `y` means that the expression will now be indexed
    by both the original (x) and by (x * y). So we are looking for a
    multiplicative factor that will make ((x + 1) * y) - (x * y) == 1.

    To simplify things for sympy, we'll try just x * y == 1, check x(1) and x(0).
    """
    if len(expr.free_symbols) == 0:
        return None
    free_symbol = next(iter(expr.free_symbols))

    def _solve_simple_expr(expr: sympy.Expr) -> Optional[sympy.Expr]:
        assert not expr.has(ModularIndexing) and (not expr.has(FloorDiv))
        if len(expr.free_symbols) != 1:
            return None
        out = try_solve(sympy.Eq(expr, 1), free_symbol)
        if not out or not out[1].is_constant():
            return None
        return out[1]
    if not expr.has(ModularIndexing) and (not expr.has(FloorDiv)):
        return _solve_simple_expr(expr)
    required_values = []
    eq_1_expressions = []
    for arg in sympy.Add.make_args(expr):
        if isinstance(arg, sympy.Mul):
            seen = False
            for mul_arg in arg.args:
                out = solve_for_zero(mul_arg)
                if out is None:
                    continue
                assert out.is_constant()
                seen = True
                required_values.append(out)
            if not seen:
                return None
        else:
            eq_1_expressions.append(arg)
    if <MASK>:
        return None
    eq_1_expr = sum(eq_1_expressions)

    def indexing_div_rep(x: sympy.Expr, y: sympy.Expr, z: Optional[sympy.Expr]=None) -> sympy.Expr:
        return x / y
    eq_1_expr_simplified = eq_1_expr.replace(ModularIndexing, indexing_div_rep).replace(FloorDiv, indexing_div_rep)
    out = _solve_simple_expr(eq_1_expr_simplified)
    if not out or sympy_subs(eq_1_expr, {free_symbol: out}) != 1:
        return None
    required_values.append(out)
    if len(OrderedSet(required_values)) == 1:
        return required_values[0]
    return None

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    """Fit the baseline regressor.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            Training data.

        y : array-like of shape (n_samples,) or (n_samples, n_outputs)
            Target values.

        sample_weight : array-like of shape (n_samples,), default=None
            Sample weights.

        Returns
        -------
        self : object
            Fitted estimator.
        """
    validate_data(self, X, skip_check_array=True)
    y = check_array(y, ensure_2d=False, input_name='y')
    if len(y) == 0:
        raise ValueError('y must not be empty.')
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    self.n_outputs_ = y.shape[1]
    check_consistent_length(X, y, sample_weight)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if self.strategy == 'mean':
        self.constant_ = np.average(y, axis=0, weights=sample_weight)
    elif <MASK>:
        if sample_weight is None:
            self.constant_ = np.median(y, axis=0)
        else:
            self.constant_ = [_weighted_percentile(y[:, k], sample_weight, percentile_rank=50.0) for k in range(self.n_outputs_)]
    elif self.strategy == 'quantile':
        if self.quantile is None:
            raise ValueError("When using `strategy='quantile', you have to specify the desired quantile in the range [0, 1].")
        percentile_rank = self.quantile * 100.0
        if sample_weight is None:
            self.constant_ = np.percentile(y, axis=0, q=percentile_rank)
        else:
            self.constant_ = [_weighted_percentile(y[:, k], sample_weight, percentile_rank=percentile_rank) for k in range(self.n_outputs_)]
    elif self.strategy == 'constant':
        if self.constant is None:
            raise TypeError('Constant target value has to be specified when the constant strategy is used.')
        self.constant_ = check_array(self.constant, accept_sparse=['csr', 'csc', 'coo'], ensure_2d=False, ensure_min_samples=0)
        if self.n_outputs_ != 1 and self.constant_.shape[0] != y.shape[1]:
            raise ValueError('Constant target value should have shape (%d, 1).' % y.shape[1])
    self.constant_ = np.reshape(self.constant_, (1, -1))
    return self

def _convert_anonymous_fields(value, for_spec=False):
    """Type-checks and converts `value` for inclusion in an AnonymousExtensionType."""
    if isinstance(value, (int, float, bool, str, bytes, type(None), dtypes.DType, tensor_shape.TensorShape)):
        return value
    if isinstance(value, tuple):
        return tuple((_convert_anonymous_fields(v, for_spec) for v in value))
    if <MASK>:
        return immutable_dict.ImmutableDict([(_convert_anonymous_fields(k, for_spec), _convert_anonymous_fields(v, for_spec)) for (k, v) in value.items()])
    if isinstance(value, (tensor.Tensor, composite_tensor.CompositeTensor)) and (not for_spec):
        return value
    if isinstance(value, type_spec.TypeSpec) and for_spec:
        return value
    raise ValueError(f'Cannot convert anonymous fields from an unsupported `value` argument: {value!r}.')

def call_function(self, tx, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    mod = tx.output.get_submodule(self.module_key)
    with record_nn_module_stack(self.module_key, self.get_nn_module_stack_source(), tx, mod):
        is_lazy = is_lazy_module(mod)
        if isinstance(mod, torch.nn.Sequential) and mod.__class__.forward is torch.nn.Sequential.forward:
            if nnmodule_has_hooks(mod):
                self.convert_to_unspecialized(tx)
            assert not is_lazy, "Expected lazy sequential isn't a valid combination?"
            if kwargs:
                raise_args_mismatch(tx, 'torch.nn.Module.Sequential', '0 kwargs', f'{len(kwargs)} kwargs')
            (arg,) = args
            for (child_name, submod) in mod._modules.items():
                tx.call_function(tx.output.register_attr_or_module(submod, self.module_key, child_name, source=NNModuleSource(AttrSource(self.source, child_name))), [arg], {})
                arg = tx.pop()
            return arg
        if is_lazy:
            if mod.cls_to_become is not None:
                self.module_type = mod.cls_to_become
            initialize_lazy_module(tx, mod, args, kwargs)
        if tx.output.is_root_tracer() and mod.__module__.startswith(('torch.nn.', 'torch.ao.')) and (mod.__module__ != 'torch.nn.utils.parametrize') and (not isinstance(mod, torch.ao.quantization.pt2e.export_utils._WrapperModule)):
            if nnmodule_has_hooks(mod, check_forward_hooks=True, check_backward_hooks=True):
                self.convert_to_unspecialized(tx)
            from .builder import wrap_fx_proxy
            return wrap_fx_proxy(tx=tx, proxy=tx.output.create_proxy('call_module', self.module_key, *proxy_args_kwargs(args, kwargs)))
        else:
            assert self.source, 'Must provide a valid source in order to inline, since inlined function may have default args which must be guarded.'
            if <MASK>:
                fn = mod.forward
                fn_source = AttrSource(self.source, 'forward')
            else:
                fn = mod._call_impl
                fn_source = AttrSource(self.source, '_call_impl')
            if istype(fn, types.MethodType):
                fn = fn.__func__
                fn_source = AttrSource(fn_source, '__func__')
                args = [self] + args
            else:
                assert istype(fn, types.FunctionType)
            return tx.inline_user_function_return(variables.UserFunctionVariable(fn, source=fn_source), args, kwargs)

