@torch.no_grad()
def foreach_reduce(fsdp_params: list[FSDPParam], unsharded_grads: list[torch.Tensor], reduce_scatter_group: dist.ProcessGroup, reduce_scatter_stream: torch.Stream, reduce_scatter_comm: ReduceScatter, orig_dtype: Optional[torch.dtype], reduce_dtype: Optional[torch.dtype], device: torch.device, gradient_divide_factor: Optional[float], all_reduce_group: Optional[dist.ProcessGroup], all_reduce_stream: torch.Stream, all_reduce_grads: bool, partial_reduce_output: Optional[torch.Tensor], all_reduce_hook: Optional[Callable[[torch.Tensor], None]], force_sum_reduction_for_comms: bool=False) -> tuple[torch.Tensor, torch.Event, torch.Event, Optional[torch.Tensor], Optional[torch.Event], Optional[torch.Tensor]]:
    """
    ``unsharded_grads`` owns the references to the gradients computed by
    autograd, so clearing the list frees the gradients.
    """
    grad_dtypes = {grad.dtype for grad in unsharded_grads}
    if len(grad_dtypes) != 1:
        _raise_assert_with_print(f'FSDP reduce-scatter expects uniform gradient dtype but got {grad_dtypes}')
    grad_dtype = unsharded_grads[0].dtype
    reduce_dtype = reduce_dtype or grad_dtype
    (predivide_factor, postdivide_factor, reduce_scatter_op, all_reduce_op) = _get_gradient_divide_factors(reduce_scatter_group, all_reduce_group, reduce_dtype, device.type, gradient_divide_factor, force_sum_reduction_for_comms)
    world_size = reduce_scatter_group.size()
    device_handle = _get_device_handle(device.type)
    current_stream = device_handle.current_stream()
    if world_size > 1:
        for (i, (fsdp_param, unsharded_grad)) in enumerate(zip(fsdp_params, unsharded_grads)):
            if (shard_dim := fsdp_param.fsdp_placement.dim) == 0:
                continue
            if unsharded_grad.size(shard_dim) % world_size != 0:
                raise AssertionError(f'Shard({shard_dim}) requires even sharding: unsharded_grad.size()={unsharded_grad.size()!r} world_size={world_size!r}')
            chunks = torch.chunk(unsharded_grad, world_size, dim=shard_dim)
            unsharded_grads[i] = torch.cat(chunks, dim=0)
    padded_unsharded_sizes = tuple((_get_dim0_padded_size(grad.size(), world_size) for grad in unsharded_grads))
    reduce_scatter_input_numel = sum((s.numel() for s in padded_unsharded_sizes))
    reduce_scatter_output_numel = reduce_scatter_input_numel // world_size
    reduce_scatter_input = reduce_scatter_comm.allocate((reduce_scatter_input_numel,), dtype=reduce_dtype, device=device)
    foreach_reduce_scatter_copy_in(unsharded_grads, reduce_scatter_input, world_size)
    unsharded_grads.clear()
    reduce_scatter_stream.wait_stream(current_stream)
    all_reduce_input = None
    all_reduce_event = None
    with device_handle.stream(reduce_scatter_stream):
        reduce_output = reduce_scatter_comm.allocate((reduce_scatter_output_numel,), dtype=reduce_dtype, device=device)
        _div_if_needed(reduce_scatter_input, predivide_factor)
        if world_size > 1:
            reduce_scatter_comm(output_tensor=reduce_output, input_tensor=reduce_scatter_input, group=reduce_scatter_group, op=reduce_scatter_op)
        else:
            reduce_output.copy_(reduce_scatter_input)
        reduce_scatter_event = reduce_scatter_stream.record_event()
        post_reduce_stream = reduce_scatter_stream
        if all_reduce_group is not None:
            if not all_reduce_grads:
                if <MASK>:
                    partial_reduce_output += reduce_output
                else:
                    partial_reduce_output = reduce_output
                return (reduce_scatter_input, reduce_scatter_event, post_reduce_stream.record_event(), all_reduce_input, all_reduce_event, partial_reduce_output)
            if partial_reduce_output is not None:
                reduce_output += partial_reduce_output
            post_reduce_stream = all_reduce_stream
            if world_size >= 1:
                all_reduce_stream.wait_stream(reduce_scatter_stream)
            else:
                all_reduce_stream.wait_stream(current_stream)
            with device_handle.stream(all_reduce_stream):
                dist.all_reduce(reduce_output, group=all_reduce_group, op=all_reduce_op)
                all_reduce_input = reduce_output
                all_reduce_event = all_reduce_stream.record_event()
    if all_reduce_hook is not None:
        post_reduce_stream = all_reduce_stream
        all_reduce_stream.wait_stream(reduce_scatter_stream)
        with device_handle.stream(all_reduce_stream):
            all_reduce_hook(reduce_output)
    with device_handle.stream(post_reduce_stream):
        _div_if_needed(reduce_output, postdivide_factor)
        reduce_output = _to_dtype_if_needed(reduce_output, orig_dtype)
        flat_grad_offset = 0
        for (padded_unsharded_size, fsdp_param) in zip(padded_unsharded_sizes, fsdp_params):
            new_sharded_grad = torch.as_strided(reduce_output, size=fsdp_param.sharded_size, stride=fsdp_param.contiguous_sharded_stride, storage_offset=flat_grad_offset)
            to_accumulate_grad = fsdp_param.sharded_param.grad is not None
            if fsdp_param.offload_to_cpu:
                non_blocking = fsdp_param.pin_memory and (not to_accumulate_grad)
                new_sharded_grad = new_sharded_grad.to(torch.device('cpu'), non_blocking=non_blocking)
                if non_blocking:
                    fsdp_param.grad_offload_event = post_reduce_stream.record_event()
            if to_accumulate_grad:
                if not isinstance(fsdp_param.sharded_param.grad, DTensor):
                    raise AssertionError(f'Expected fsdp_param.sharded_param.grad to be DTensor, got {type(fsdp_param.sharded_param.grad)}')
                fsdp_param.sharded_param.grad._local_tensor += new_sharded_grad
            else:
                new_sharded_dtensor_grad = fsdp_param.to_sharded_dtensor(new_sharded_grad)
                fsdp_param.sharded_param.grad = new_sharded_dtensor_grad
            if not compiled_autograd_enabled():
                for hook in (getattr(fsdp_param.sharded_param, '_post_accumulate_grad_hooks', {}) or {}).values():
                    hook(fsdp_param.sharded_param)
            padded_sharded_numel = padded_unsharded_size.numel() // world_size
            flat_grad_offset += padded_sharded_numel
        post_reduce_event = post_reduce_stream.record_event()
    return (reduce_scatter_input, reduce_scatter_event, post_reduce_event, all_reduce_input, all_reduce_event, None)

def __hash__(self):
    if <MASK>:
