def get_dequantize_opcode_idx(model):
    """Returns the quantize op idx."""
    quant_opcode_idxs = []
    for (idx, opcode) in enumerate(model.operatorCodes):
        builtin_code = schema_util.get_builtin_code_from_operator_code(opcode)
        if <MASK>:
