@torch.no_grad()
def deepcopy_with_tensor_offload(self, x, memo=None, _nil=[], non_blocking=False):
    """Deep copy operation on arbitrary Python objects with special handling for PyTorch tensors.

        This implementation extends the standard deepcopy functionality to handle PyTorch tensors
        and their storages in a way that optimizes memory usage and performance, similar to the
        stage method. It applies memory sharing and pinning optimizations based on the StateDictStager
        configuration.

        Args:
            x: The object to deep copy
            memo: Memo dictionary for tracking already copied objects
            _nil: Sentinel value for memo dictionary
            non_blocking: Whether to perform non-blocking copies where possible

        Returns:
            A deep copy of the input object with optimized tensor storage handling
        """
    if memo is None:
        memo = {}
    d = id(x)
    y = memo.get(d, _nil)
    if y is not _nil:
        return y
    cls = type(x)
    if isinstance(x, torch.Tensor):
        y = self._offload_tensor(x, memo, non_blocking=non_blocking)
    else:
        copier = self._deepcopy_dispatch.get(cls)
        if <MASK>:
            if copier.__name__ == '_deepcopy_atomic':
                y = copier(x, memo)
            else:
                y = copier(x, memo, non_blocking=non_blocking)
        elif issubclass(cls, type):
            y = self._deepcopy_dispatch[type](x, memo)
        else:
            copier = getattr(x, '__deepcopy__', None)
            if copier is not None:
                y = copier(memo)
            else:
                reductor = dispatch_table.get(cls)
                if reductor:
                    rv = reductor(x)
                else:
                    reductor = getattr(x, '__reduce_ex__', None)
                    if reductor is not None:
                        rv = reductor(4)
                    else:
                        reductor = getattr(x, '__reduce__', None)
                        if reductor:
                            rv = reductor()
                        else:
                            raise RuntimeError(f'un(deep)copyable object of type {cls}')
                if isinstance(rv, str):
                    y = x
                elif len(rv) == 2:
                    (func, args) = rv
                    y = self._reconstruct(x, memo, func, args, non_blocking=non_blocking)
                elif len(rv) == 3:
                    (func, args, state) = rv
                    y = self._reconstruct(x, memo, func, args, state, non_blocking=non_blocking)
                elif len(rv) == 4:
                    (func, args, state, listiter) = rv
                    y = self._reconstruct(x, memo, func, args, state, listiter, non_blocking=non_blocking)
                elif len(rv) == 5:
                    (func, args, state, listiter, dictiter) = rv
                    y = self._reconstruct(x, memo, func, args, state, listiter, dictiter, non_blocking=non_blocking)
                else:
                    raise RuntimeError(f'Unexpected pickle protocol return value length: {len(rv)}')
    if y is not x:
        memo[d] = y
        self._keep_alive(x, memo)
    return y

def _weak_tensor_from_str(s):
    if s == 'weak_i64':
        return _get_weak_tensor(1, dtype=dtypes.int64)
    elif s == 'weak_f64':
        return _get_weak_tensor(1.0, dtype=dtypes.float64)
    elif <MASK>:
        return _get_weak_tensor(1.0 + 2j, dtype=dtypes.complex128)
    else:
        raise ValueError(f'Unsupported str: {s}')

def codegen(self, output_name: str, input_names: list[str], output_spec: Spec) -> str:
    """Generate code for batch matrix multiplication."""
    if <MASK>:
        raise ValueError('torch.bmm requires exactly 2 inputs')
    if isinstance(output_spec, TensorSpec):
        target_dtype_str = f'torch.{output_spec.dtype}'.replace('torch.torch.', 'torch.')
        return f'{output_name} = torch.bmm({input_names[0]}.to({target_dtype_str}), {input_names[1]}.to({target_dtype_str}))'
    else:
        return f'{output_name} = torch.bmm({input_names[0]}, {input_names[1]})'

def _get_batched_dataset_attributes(d):
    """Get `batch_size`, `drop_remainder` of dataset."""
    assert isinstance(d, (dataset_ops.BatchDataset, batching._MapAndBatchDataset))
    if isinstance(d, dataset_ops.BatchDataset):
        batch_size = d._batch_size
        drop_remainder = d._drop_remainder
    elif isinstance(d, batching._MapAndBatchDataset):
        batch_size = d._batch_size_t
        drop_remainder = d._drop_remainder_t
    if <MASK>:
        batch_size = tensor_util.constant_value(batch_size)
    if tensor_util.is_tf_type(drop_remainder):
        drop_remainder = tensor_util.constant_value(drop_remainder)
    return (batch_size, drop_remainder)

@L.register_lowering(aten.bmm)
def tuned_bmm(mat1, mat2, out_dtype=None, *, layout=None):
    """
    Lowering for autotuning aten.bmm with different backends (Aten, Triton, CUTLASS, etc.)
    """
    if all((x.get_device().type == 'cpu' for x in [mat1, mat2])):
        if mat1.get_size()[1] == 1 or mat2.get_size()[2] == 1:
            mat1 = L.unsqueeze(mat1, -1)
            mat2 = L.unsqueeze(mat2, 1)
            return L.sum_(L.mul(mat1, mat2), axis=2)

        def is_valid_to_require_contiguous(t):
            if not ir.is_storage_and_layout(t):
                return True
            (_, layout) = ir.as_storage_and_layout(t, freeze=False)
            return isinstance(layout, ir.FlexibleLayout)

        def is_preferred_layout_as_bmm_input(sizes, strides):
            return strides[-1] == 1 and (sizes[-2] == 1 or strides[-2] >= sizes[-1]) or (strides[-2] == 1 and (sizes[-1] == 1 or strides[-1] >= sizes[-2]))

        def may_require_contiguous(t, meta_t):
            sizes = meta_t.meta['val'].size()
            strides = meta_t.meta['val'].stride()
            if <MASK>:
                t = ir.ExternKernel.require_contiguous(t)
            return t
        if is_valid_to_require_contiguous(mat1):
            meta_mat1 = V.graph.current_node.args[0]
            mat1 = may_require_contiguous(mat1, meta_mat1)
        if is_valid_to_require_contiguous(mat2):
            meta_mat2 = V.graph.current_node.args[1]
            mat2 = may_require_contiguous(mat2, meta_mat2)
    if use_native_matmul(mat1, mat2):
        mat1 = lowerings[aten.unsqueeze](mat1, -1)
        mat2 = lowerings[aten.unsqueeze](mat2, 1)
        (args, kwargs) = transform_args(args=[mat1, mat2], kwargs={}, broadcast=True, type_promotion_kind=None, convert_input_to_bool=False)
        if inductor_config.triton.codegen_upcast_to_fp32 and mat1.dtype in [torch.float16, torch.bfloat16]:

            def _to_dtype(x):
                return ops.to_dtype(x, mat1.dtype, use_compute_types=False)
            args = [make_pointwise(_to_dtype)(x) for x in args]
        mul_pointwise = make_pointwise(ops.dot)(*args)
        dot_reduction = make_reduction('dot')(mul_pointwise, 2)
        return dot_reduction
    (m, n, k, layout, mat1, mat2) = mm_args(mat1, mat2, layout=layout, out_dtype=out_dtype)
    name = 'bmm'
    kernel_inputs = MMKernelInputs([mat1, mat2], out_dtype=out_dtype)
    batch_size = mat1.get_size()[0]
    counters['aten_mm_info'][f'aten.bmm_{batch_size}_{m}_{n}_{k}'] += 1
    log.info('Tuned aten.bmm: batch=%s, m=%s, n=%s, k=%s, mat1_dtype=%s, mat2_dtype=%s, output_layout=%s', batch_size, m, n, k, mat1.get_dtype(), mat2.get_dtype(), layout)
    aten_handler: ExternKernelChoice = aten_bmm
    aten_extra_kwargs = {}
    if out_dtype:
        assert mat1.get_device().type == 'cuda', 'out_dtype is only supported for CUDA'
        aten_handler = aten_bmm_dtype
        aten_extra_kwargs = {'out_dtype': out_dtype}
    choices: list[ChoiceCaller] = []
    templates_to_use: list[Union[ExternKernelChoice, KernelTemplate]] = []
    kwarg_overrides = {}
    if use_aten_gemm_kernels():
        templates_to_use.append(aten_handler)
        kwarg_overrides[aten_handler.uid] = aten_extra_kwargs
    if use_triton_template(layout, check_max_autotune=False):
        assert out_dtype is None, 'out_dtype is not supported for Triton'
        templates_to_use.append(bmm_template)
    choices.extend(V.choices.get_template_configs(kernel_inputs, templates_to_use, name, kwarg_overrides=kwarg_overrides))
    (_, is_nonzero) = _is_static_problem(layout)
    batch_stride_largest_or_zero = is_batch_stride_largest_or_zero(mat1, mat2, layout)
    if batch_stride_largest_or_zero and is_nonzero and use_cutlass_template(layout, m, n, k) and _use_cutlass_for_op(name):
        from ..codegen.cuda.gemm_template import CUTLASS3xGemmTemplate
        CUTLASS3xGemmTemplate.add_cutlass_gemm_choices(choices, layout, kernel_inputs.nodes())
    if use_cpp_bmm_template(layout, mat1, mat2):
        from ..codegen.cpp_bmm_template import CppBmmTemplate
        CppBmmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    if use_ck_gemm_template(layout, m, n, k):
        CKGemmTemplate.add_ck_gemm_choices(choices, layout, kernel_inputs.nodes())
    return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout)

def __new__(cls, data=None, mask=nomask, dtype=None, copy=False, subok=True, ndmin=0, fill_value=None, keep_mask=True, hard_mask=None, shrink=True, order=None):
    """
        Create a new masked array from scratch.

        Notes
        -----
        A masked array can also be created by taking a .view(MaskedArray).

        """
    copy = None if not copy else True
    _data = np.array(data, dtype=dtype, copy=copy, order=order, subok=True, ndmin=ndmin)
    _baseclass = getattr(data, '_baseclass', type(_data))
    if isinstance(data, MaskedArray) and data.shape != _data.shape:
        copy = True
    if isinstance(data, cls) and subok and (not isinstance(data, MaskedConstant)):
        _data = ndarray.view(_data, type(data))
    else:
        _data = ndarray.view(_data, cls)
    if hasattr(data, '_mask') and (not isinstance(data, ndarray)):
        _data._mask = data._mask
    mdtype = make_mask_descr(_data.dtype)
    if mask is nomask:
        if not keep_mask:
            if shrink:
                _data._mask = nomask
            else:
                _data._mask = np.zeros(_data.shape, dtype=mdtype)
        elif isinstance(data, (tuple, list)):
            try:
                mask = np.array([getmaskarray(np.asanyarray(m, dtype=_data.dtype)) for m in data], dtype=mdtype)
            except (ValueError, TypeError):
                mask = nomask
            if mdtype == MaskType and mask.any():
                _data._mask = mask
                _data._sharedmask = False
        else:
            _data._sharedmask = not copy
            if copy:
                _data._mask = _data._mask.copy()
                if getmask(data) is not nomask:
                    if data._mask.shape != data.shape:
                        data._mask.shape = data.shape
    else:
        if mask is None:
            mask = False
        if mask is True and mdtype == MaskType:
            mask = np.ones(_data.shape, dtype=mdtype)
        elif mask is False and mdtype == MaskType:
            mask = np.zeros(_data.shape, dtype=mdtype)
        else:
            try:
                mask = np.array(mask, copy=copy, dtype=mdtype)
            except TypeError:
                mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
        if mask.shape != _data.shape:
            (nd, nm) = (_data.size, mask.size)
            if nm == 1:
                mask = np.resize(mask, _data.shape)
            elif nm == nd:
                mask = np.reshape(mask, _data.shape)
            else:
                msg = f'Mask and data not compatible: data size is {nd}, mask size is {nm}.'
                raise MaskError(msg)
            copy = True
        if _data._mask is nomask:
            _data._mask = mask
            _data._sharedmask = not copy
        elif not keep_mask:
            _data._mask = mask
            _data._sharedmask = not copy
        else:
            if _data.dtype.names is not None:

                def _recursive_or(a, b):
                    """do a|=b on each field of a, recursively"""
                    for name in a.dtype.names:
                        (af, bf) = (a[name], b[name])
                        if <MASK>:
                            _recursive_or(af, bf)
                        else:
                            af |= bf
                _recursive_or(_data._mask, mask)
            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

@staticmethod
def _process_value_according_to_param_policy(param: torch.Tensor, value: torch.Tensor, param_id: int, param_groups: list[dict[Any, Any]], key: Hashable=None) -> torch.Tensor:
    fused = False
    capturable = False
    if param_groups is None:
        raise AssertionError('Expected param_groups to be set')
    for pg in param_groups:
        if param_id in pg['params']:
            fused = pg.get('fused', False)
            capturable = pg.get('capturable', False)
            break
    if key == 'step':
        if capturable or fused:
            return value.to(dtype=torch.float32, device=param.device)
        else:
            return value
    elif <MASK>:
        return value.to(dtype=param.dtype, device=param.device)
    else:
        return value.to(device=param.device)

def time_methods_0v(self, method, msize):
    if <MASK>:
        mdat = self.nmxs
    elif msize == 'big':
        mdat = self.nmxl
    getattr(mdat, method)()

def _parametrize_test(self, test, generic_cls, device_cls):
    """Parameterizes the given test function across each op and its associated dtypes."""
    if device_cls is None:
        raise RuntimeError('The @ops decorator is only intended to be used in a device-specific context; use it with instantiate_device_type_tests() instead of instantiate_parametrized_tests()')
    op = check_exhausted_iterator = object()
    for op in self.op_list:
        dtypes: Union[set[torch.dtype], set[None]]
        if isinstance(self.opinfo_dtypes, Sequence):
            dtypes = set(self.opinfo_dtypes)
        elif self.opinfo_dtypes == OpDTypes.unsupported_backward:
            dtypes = set(get_all_dtypes()).difference(op.supported_backward_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported_backward:
            dtypes = op.supported_backward_dtypes(device_cls.device_type)
        elif self.opinfo_dtypes == OpDTypes.unsupported:
            dtypes = set(get_all_dtypes()).difference(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported:
            dtypes = set(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.any_one:
            supported = op.supported_dtypes(device_cls.device_type)
            supported_backward = op.supported_backward_dtypes(device_cls.device_type)
            supported_both = supported.intersection(supported_backward)
            dtype_set = supported_both if len(supported_both) > 0 else supported
            for dtype in ANY_DTYPE_ORDER:
                if dtype in dtype_set:
                    dtypes = {dtype}
                    break
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.any_common_cpu_cuda_one:
            supported = set(op.dtypes).intersection(op.dtypesIfCUDA)
            if supported:
                dtypes = {next((dtype for dtype in ANY_DTYPE_ORDER if dtype in supported))}
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.none:
            dtypes = {None}
        else:
            raise RuntimeError(f'Unknown OpDType: {self.opinfo_dtypes}')
        if self.allowed_dtypes is not None:
            dtypes = dtypes.intersection(self.allowed_dtypes)
        test_name = op.formatted_name
        sample_skips_and_xfails = getattr(test, 'sample_skips_and_xfails', None)
        if sample_skips_and_xfails is not None:
            sample_skips_and_xfails = [rule for rule in sample_skips_and_xfails if rule.op_match_fn(device_cls.device_type, op)]
        for dtype in dtypes:
            param_kwargs = {'op': op}
            _update_param_kwargs(param_kwargs, 'dtype', dtype)
            try:

                @wraps(test)
                def test_wrapper(*args, **kwargs):
                    try:
                        return test(*args, **kwargs)
                    except unittest.SkipTest as e:
                        raise e
                    except Exception as e:
                        tracked_input = get_tracked_input()
                        if PRINT_REPRO_ON_FAILURE and tracked_input is not None:
                            e_tracked = Exception(f'{str(e)}\n\nCaused by {tracked_input.type_desc} at index {tracked_input.index}: {_serialize_sample(tracked_input.val)}')
                            e_tracked._tracked_input = tracked_input
                            raise e_tracked from e
                        raise e
                    finally:
                        clear_tracked_input()
                if <MASK>:
                    test_wrapper = skipIfTorchDynamo("Policy: we don't run OpInfo tests w/ Dynamo")(test_wrapper)
                test.tracked_input = None
                decorator_fn = partial(op.get_decorators, generic_cls.__name__, test.__name__, device_cls.device_type, dtype)
                if sample_skips_and_xfails is not None:
                    test_wrapper.sample_skips_and_xfails = sample_skips_and_xfails
                yield (test_wrapper, test_name, param_kwargs, decorator_fn)
            except Exception as ex:
                print(f'Failed to instantiate {test_name} for op {op.name}!')
                raise ex
    if op is check_exhausted_iterator:
        raise ValueError('An empty op_list was passed to @ops. Note that this may result from reuse of a generator.')

def _ready_to_schedule(action: Optional[_Action]) -> bool:
    if action is None:
        return True
    stage_idx = action.stage_index
    prev_ops = _prev_ops_rank[stage_to_rank(stage_idx)]
    if action.computation_type == F:
        if action.stage_index == 0:
            return True
        elif _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_ops:
            return True
        elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_ops:
            return True
        return False
    elif <MASK>:
        if action.stage_index == num_stages - 1:
            return True
        if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_ops:
            return True
        if _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_ops:
            return True
        if _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_ops:
            return True
        return False
    elif action.computation_type == BACKWARD_WEIGHT:
        return True
    elif action.computation_type == SEND_F:
        expected_f = _Action(action.stage_index, F, action.microbatch_index)
        return expected_f in prev_ops
    elif action.computation_type == RECV_F:
        peer_stage_idx = stage_idx - 1
        expected_send = _Action(peer_stage_idx, SEND_F, action.microbatch_index)
        return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
    elif action.computation_type == SEND_B:
        expected_b = _Action(action.stage_index, BACKWARD_INPUT, action.microbatch_index)
        expected_bw = _Action(action.stage_index, FULL_BACKWARD, action.microbatch_index)
        return expected_b in prev_ops or expected_bw in prev_ops
    elif action.computation_type == RECV_B:
        peer_stage_idx = stage_idx + 1
        expected_send = _Action(peer_stage_idx, SEND_B, action.microbatch_index)
        return expected_send in _prev_ops_rank[stage_to_rank(peer_stage_idx)]
    else:
        raise ValueError(f'Unsupported action type {action}')

def _call(self, inst: Instruction, call_kw: bool=False) -> None:
    if call_kw:
        assert sys.version_info >= (3, 13)
        kw_names = self.pop()
        assert isinstance(kw_names, TupleVariable) and kw_names.is_python_constant()
        kw_names = kw_names.as_python_constant()
    else:
        kw_names = self.kw_names.value if self.kw_names else ()
    assert inst.arg is not None
    contents = self.popn(inst.arg + 2)
    if sys.version_info >= (3, 13):
        fn = contents[0]
        args = [] if isinstance(contents[1], NullVariable) else [contents[1]]
    elif <MASK>:
        fn = contents[1]
        args = []
    else:
        fn = contents[0]
        args = [contents[1]]
    if kw_names:
        args = args + contents[2:-len(kw_names)]
        kwargs_list = contents[-len(kw_names):]
        kwargs = dict(zip(kw_names, kwargs_list))
        assert len(kwargs) == len(kw_names)
    else:
        args = args + contents[2:]
        kwargs = {}
    try:
        self.call_function(fn, args, kwargs)
    finally:
        self.kw_names = None

def _compare_values(path, old_val, new_val):
    """Recursively compare values, handling containers."""
    if old_val is new_val:
        return
    if old_val is None or new_val is None:
        if <MASK>:
            assigned_tensor_attributes.append(path)
        return
    if isinstance(new_val, torch.Tensor):
        assigned_tensor_attributes.append(path)
        return
    if isinstance(old_val, dict) and isinstance(new_val, dict):
        all_keys = set(old_val.keys()) | set(new_val.keys())
        for key in all_keys:
            old_item = old_val.get(key)
            new_item = new_val.get(key)
            _compare_values(f'{path}[{key!r}]', old_item, new_item)
        return
    if isinstance(old_val, (list, tuple)) and isinstance(new_val, (list, tuple)):
        max_len = max(len(old_val), len(new_val))
        for i in range(max_len):
            old_item = old_val[i] if i < len(old_val) else None
            new_item = new_val[i] if i < len(new_val) else None
            _compare_values(f'{path}[{i}]', old_item, new_item)
        return

def _multi_tensor_rmsprop(params: list[Tensor], grads: list[Tensor], square_avgs: list[Tensor], grad_avgs: list[Tensor], momentum_buffer_list: list[Tensor], state_steps: list[Tensor], *, lr: float, alpha: float, eps: float, weight_decay: float, momentum: float, centered: bool, maximize: bool, differentiable: bool, capturable: bool, has_complex: bool):
    if len(params) == 0:
        return
    if differentiable:
        raise AssertionError("_foreach ops don't support autograd")
    if not torch.compiler.is_compiling() and capturable:
        capturable_supported_devices = _get_capturable_supported_devices()
        if not all((p.device.type == step.device.type and p.device.type in capturable_supported_devices for (p, step) in zip(params, state_steps))):
            raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
    lr = _to_scalar(lr)
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, square_avgs, grad_avgs, momentum_buffer_list, state_steps])
    for ((grouped_params_, grouped_grads_, grouped_square_avgs_, grouped_grad_avgs_, grouped_momentum_buffer_list_, grouped_state_steps_), _) in grouped_tensors.values():
        grouped_params = cast(list[Tensor], grouped_params_)
        grouped_grads = cast(list[Tensor], grouped_grads_)
        grouped_square_avgs = cast(list[Tensor], grouped_square_avgs_)
        grouped_state_steps = cast(list[Tensor], grouped_state_steps_)
        if has_complex:
            state_and_grads = [grouped_grads, grouped_square_avgs]
            if momentum > 0:
                grouped_momentum_buffer_list = cast(list[Tensor], grouped_momentum_buffer_list_)
                state_and_grads.append(grouped_momentum_buffer_list)
            if centered:
                grouped_grad_avgs = cast(list[Tensor], grouped_grad_avgs_)
                state_and_grads.append(grouped_grad_avgs)
            _view_as_real(grouped_params, *state_and_grads)
        if maximize:
            grouped_grads = torch._foreach_neg(grouped_grads)
        if not torch.compiler.is_compiling() and grouped_state_steps[0].is_cpu:
            torch._foreach_add_(grouped_state_steps, torch.tensor(1.0, device='cpu'), alpha=1.0)
        else:
            torch._foreach_add_(grouped_state_steps, 1)
        if weight_decay != 0:
            if maximize:
                torch._foreach_add_(grouped_grads, grouped_params, alpha=weight_decay)
            else:
                grouped_grads = torch._foreach_add(grouped_grads, grouped_params, alpha=weight_decay)
        torch._foreach_mul_(grouped_square_avgs, alpha)
        torch._foreach_addcmul_(grouped_square_avgs, grouped_grads, grouped_grads, value=1 - alpha)
        if centered:
            grouped_grad_avgs = cast(list[Tensor], grouped_grad_avgs_)
            torch._foreach_lerp_(grouped_grad_avgs, grouped_grads, 1 - alpha)
            avg = torch._foreach_addcmul(grouped_square_avgs, grouped_grad_avgs, grouped_grad_avgs, value=-1)
            torch._foreach_sqrt_(avg)
            torch._foreach_add_(avg, eps)
        else:
            avg = torch._foreach_sqrt(grouped_square_avgs)
            torch._foreach_add_(avg, eps)
        if momentum > 0:
            grouped_momentum_buffer_list = cast(list[Tensor], grouped_momentum_buffer_list_)
            torch._foreach_mul_(grouped_momentum_buffer_list, momentum)
            torch._foreach_addcdiv_(grouped_momentum_buffer_list, grouped_grads, avg)
            if <MASK>:
                momentum_lr = torch._foreach_mul(grouped_momentum_buffer_list, -lr)
                torch._foreach_add_(grouped_params, momentum_lr)
            else:
                torch._foreach_add_(grouped_params, grouped_momentum_buffer_list, alpha=-lr)
        elif capturable and isinstance(lr, torch.Tensor):
            torch._foreach_div_(avg, -lr)
            torch._foreach_addcdiv_(grouped_params, grouped_grads, avg)
        else:
            torch._foreach_addcdiv_(grouped_params, grouped_grads, avg, value=-lr)

def _chunk_to_dataframe(self) -> DataFrame:
    n = self._current_row_in_chunk_index
    m = self._current_row_in_file_index
    ix = range(m - n, m)
    rslt = {}
    (js, jb) = (0, 0)
    infer_string = get_option('future.infer_string')
    for j in range(self.column_count):
        name = self.column_names[j]
        if self._column_types[j] == b'd':
            col_arr = self._byte_chunk[jb, :].view(dtype=self.byte_order + 'd')
            rslt[name] = pd.Series(col_arr, dtype=np.float64, index=ix, copy=False)
            if self.convert_dates:
                if self.column_formats[j] in const.sas_date_formats:
                    rslt[name] = _convert_datetimes(rslt[name], 'd')
                elif self.column_formats[j] in const.sas_datetime_formats:
                    rslt[name] = _convert_datetimes(rslt[name], 's')
            jb += 1
        elif <MASK>:
            rslt[name] = pd.Series(self._string_chunk[js, :], index=ix, copy=False)
            if self.convert_text and self.encoding is not None:
                rslt[name] = self._decode_string(rslt[name].str)
                if infer_string:
                    rslt[name] = rslt[name].astype('str')
            js += 1
        else:
            self.close()
            raise ValueError(f'unknown column type {self._column_types[j]!r}')
    df = DataFrame(rslt, columns=self.column_names, index=ix, copy=False)
    return df

@classmethod
def load_async(cls, main_code: str, device_type: str='cpu', submit_fn: Any=None, extra_flags: Sequence[str]=(), optimized_code: str | None=None) -> Any:
    """Compile and load a C++ library.  Returns a callable that returns the loaded
        library."""
    compile_command = {**cls.cpp_compile_command_flags, 'device_type': device_type, 'extra_flags': extra_flags, 'use_relative_path': config.is_fbcode(), 'vec_isa': pick_vec_isa()}
    _set_gpu_runtime_env()
    main_build_option = CppTorchDeviceOptions(compile_only=bool(optimized_code), min_optimize=optimized_code is not None, **compile_command)
    optimized_build_option = CppTorchDeviceOptions(compile_only=True, **compile_command)

    def get_hashable_command_line(build_option: BuildOptionsBase) -> str:
        """Writing the code to file will calculate a hash, which we need to vary if
            the command line flags change.  This implements a mostly-generic way of
            validating that."""
        return CppBuilder(name='o', sources='i', BuildOption=build_option).get_command_line()
    main_cmd_line = get_hashable_command_line(main_build_option)
    optimized_cmd_line = get_hashable_command_line(optimized_build_option)
    (key, main_path) = write(main_code, 'main.cpp', extra=f'{optimized_code} {main_cmd_line}')
    if <MASK>:
        (_, optimized_path) = write(optimized_code, 'optimized.cpp', extra=optimized_cmd_line)
    else:
        optimized_path = os.devnull
    if key not in cls.cache:
        from torch.utils._filelock import FileLock
        lock_path = os.path.join(get_lock_dir(), key + '.lock')
        future: Future[Any] | None = None
        lib = None
        if config.cpp_cache_precompile_headers and (not _IS_WINDOWS):
            if (header := cls._get_uncompiled_header(device_type)):
                main_build_option.precompiled_header = _precompile_header(header, main_cmd_line, min_optimize=optimized_code is not None, **compile_command)
            if optimized_code and (header := _get_cpp_prefix_header(device_type)):
                optimized_build_option.precompiled_header = _precompile_header(header, optimized_cmd_line, **compile_command)
        (main_name, output_dir) = get_name_and_dir_from_output_file_path(main_path)
        main_builder = CppBuilder(name=main_name, sources=main_path, BuildOption=main_build_option, output_dir=output_dir)
        if optimized_code:
            (optimized_name, _) = get_name_and_dir_from_output_file_path(optimized_path)
            optimized_builder = CppBuilder(name=optimized_name, sources=optimized_path, BuildOption=optimized_build_option, output_dir=output_dir)
            linker = CppBuilder(name=main_name, sources=[main_builder.get_target_file_path(), optimized_builder.get_target_file_path()], BuildOption=CppTorchDeviceOptions(**compile_command), output_dir=output_dir)
            worker_fn = functools.partial(_worker_compile_cpp, lock_path, (main_builder, optimized_builder, linker))
            binary_path = normalize_path_separator(linker.get_target_file_path())
        else:
            worker_fn = functools.partial(_worker_compile_cpp, lock_path, (main_builder,))
            binary_path = normalize_path_separator(main_builder.get_target_file_path())

        def load_fn() -> Any:
            nonlocal lib
            if lib is None:
                if future is not None:
                    future.result()
                result = worker_fn()
                assert result is None
                lib = cls._load_library(binary_path, key)
                assert lib is not None
            return lib
        if submit_fn is not None:
            with FileLock(lock_path, timeout=LOCK_TIMEOUT):
                if not os.path.exists(binary_path):
                    future = submit_fn(worker_fn)
        cls.cache[key] = load_fn
    return cls.cache[key]

def __init__(self, *args):
    super().__init__()
    if <MASK>:
        for (key, module) in args[0].items():
            self.add_module(key, module)
    else:
        for (idx, module) in enumerate(args):
            self.add_module(str(idx), module)

def _emit_binary_op(self, op, lhs, lhs_ty, rhs, rhs_ty):
    assert lhs_ty, rhs_ty
    if isinstance(op, ast.Sub):
        code = 'arith.sub'
    elif isinstance(op, ast.Add):
        code = 'arith.add'
    elif isinstance(op, ast.Mult):
        code = 'arith.mul'
    elif isinstance(op, ast.Div):
        code = 'arith.div'
    else:
        raise NotImplementedError('BinOp operator not recognized' + op)
    if lhs_ty == TFRTypes.I64 or lhs_ty == TFRTypes.I32:
        suffix = 'i'
    elif <MASK>:
        suffix = 'f'
    else:
        raise NotImplementedError('BinOp operand type not recognized' + op)
    ret = self._ssa_name(code)
    self._emit_with_loc('\n{} = {}{} {}, {} : {}'.format(ret, code, suffix, lhs, rhs, lhs_ty), op)
    return (ret, lhs_ty)

@combinations.generate(combinations.times(test_base.default_test_combinations(), combinations.combine(existing_prefetch=[True, False]), combinations.combine(autotune=[True, False]), combinations.combine(inject_prefetch=[True, False])))
