    else:
        return i

def get_operator_range(chars_range):
    """Generates the characters from chars_range inclusive."""
    if <MASK>:
        return None
    if all((item not in chars_range for item in [',', '-'])):
        raise ValueError('The correct format for operator_range is <start>-<end>, or <point>, <start>-<end>')
    ops_start_chars_set = set()
    ranges = chars_range.split(',')
    for item in ranges:
        if len(item) == 1:
            ops_start_chars_set.add(item.lower())
            continue
        (start, end) = item.split('-')
        ops_start_chars_set.update((chr(c).lower() for c in range(ord(start), ord(end) + 1)))
    return ops_start_chars_set

def _match_nodes(self, pn: Node, gn: Node, match: InternalMatch, node_name_match: str='') -> bool:
    logger.info('  matching %s to %s', pn, gn)
    assert isinstance(pn, Node) and isinstance(gn, Node), str(f'pn and gn must be Node, pn: {pn}, gn: {gn}')
    if pn in match.nodes_map:
        return match.nodes_map[pn] == gn
    if gn in match.nodes_map.values():
        return False
    if not self._nodes_are_equal(pn, gn, node_name_match):
        return False
    saved_match = copy.copy(match)
    match.nodes_map[pn] = gn
    if pn.op == 'placeholder':
        return True
    match_found = True

    def _match_args(args1: Union[list, tuple], args2: Union[list, tuple]) -> bool:
        if len(args1) != len(args2):
            return False
        for (a1, a2) in zip(args1, args2):
            if isinstance(a1, Node) and isinstance(a2, Node):
                matched = self._match_nodes(a1, a2, match)
            elif isinstance(a1, (list, tuple)) and isinstance(a2, (list, tuple)):
                matched = _match_args(a1, a2)
            else:
                matched = self._match_literals(a1, a2, match) or self.ignore_literals
            if <MASK>:
                return False
        return True
    (pn_args, gn_args) = (None, None)
    if (len(pn.args) != len(gn.args) or list(pn.kwargs.keys()) != list(gn.kwargs.keys())) and pn.op == 'call_function' and isinstance(pn.target, torch._ops.OpOverload):
        args_schema = pn.target._schema.arguments

        def get_all_arguments(orig_args, orig_kwargs):
            all_args = []
            for (i, schema) in enumerate(args_schema):
                if schema.name in orig_kwargs:
                    all_args.append(orig_kwargs[schema.name])
                elif not schema.kwarg_only and i < len(orig_args):
                    all_args.append(orig_args[i])
                else:
                    all_args.append(schema.default_value)
            return all_args
        pn_args = get_all_arguments(pn.args, pn.kwargs)
        gn_args = get_all_arguments(gn.args, gn.kwargs)
    elif len(pn.args) == len(gn.args) and list(pn.kwargs.keys()) == list(gn.kwargs.keys()):
        pn_args = list(pn.args)
        gn_args = list(gn.args)
        pn_args.extend(list(pn.kwargs.values()))
        gn_args.extend(list(gn.kwargs.values()))
    else:
        match_found = False
    match_found = match_found and pn_args is not None and (gn_args is not None) and _match_args(pn_args, gn_args)
    if not match_found:
        match = copy.copy(saved_match)
        return False
    return True

def _get_available_device_type():
    if torch.cuda.is_available():
        return 'cuda'
    if torch.backends.mps.is_available():
        return 'mps'
    if hasattr(torch, 'xpu') and torch.xpu.is_available():
        return 'xpu'
    if <MASK>:
        return 'mtia'
    custom_backend_name = torch._C._get_privateuse1_backend_name()
    custom_device_mod = getattr(torch, custom_backend_name, None)
    if custom_device_mod and custom_device_mod.is_available():
        return custom_backend_name
    return None

def inner(*args, **kwargs):
    nonlocal checked
    if checked:
        return func(*args, **kwargs)
    op = torch._library.utils.lookup_op(qualname)
    if <MASK>:
        checked = True
        return func(*args, **kwargs)
    maybe_pystub = torch._C._dispatch_pystub(op._schema.name, op._schema.overload_name)
    if maybe_pystub is None:
        if torch._library.utils.requires_set_python_module():
            namespace = op.namespace
            cpp_filename = op._handle.debug()
            raise RuntimeError(f'''Operator '{qualname}' was defined in C++ and has a Python fake impl. In this situation, we require there to also be a companion C++ `m.set_python_module("{actual_module_name}")` call, but we could not find one. Please add that to to the top of the C++ TORCH_LIBRARY({namespace}, ...) block the operator was registered in ({cpp_filename})''')
    else:
        pystub_module = maybe_pystub[0]
        if actual_module_name != pystub_module:
            cpp_filename = op._handle.debug()
            raise RuntimeError(f"Operator '{qualname}' specified that its python fake impl is in the Python module '{pystub_module}' but it was actually found in '{actual_module_name}'. Please either move the fake impl or correct the m.set_python_module call ({cpp_filename})")
    checked = True
    return func(*args, **kwargs)

def resize_fn(images_t, new_size):
    """Resize core function, passed to _resize_images_common."""
    scale_and_translate_methods = [ResizeMethod.LANCZOS3, ResizeMethod.LANCZOS5, ResizeMethod.GAUSSIAN, ResizeMethod.MITCHELLCUBIC]

    def resize_with_scale_and_translate(method):
        scale = math_ops.cast(new_size, dtype=dtypes.float32) / math_ops.cast(array_ops.shape(images_t)[1:3], dtype=dtypes.float32)
        return gen_image_ops.scale_and_translate(images_t, new_size, scale, array_ops.zeros([2]), kernel_type=method, antialias=antialias)
    if method == ResizeMethod.BILINEAR:
        if antialias:
            return resize_with_scale_and_translate('triangle')
        else:
            return gen_image_ops.resize_bilinear(images_t, new_size, half_pixel_centers=True)
    elif <MASK>:
        return gen_image_ops.resize_nearest_neighbor(images_t, new_size, half_pixel_centers=True)
    elif method == ResizeMethod.BICUBIC:
        if antialias:
            return resize_with_scale_and_translate('keyscubic')
        else:
            return gen_image_ops.resize_bicubic(images_t, new_size, half_pixel_centers=True)
    elif method == ResizeMethod.AREA:
        return gen_image_ops.resize_area(images_t, new_size)
    elif method in scale_and_translate_methods:
        return resize_with_scale_and_translate(method)
    else:
        raise ValueError('Resize method is not implemented: {}'.format(method))

def object_annotation(obj):
    """
    Return a string to be used for Graphviz nodes.

    The string should be short but as informative as possible.
    """

    def format_sequence(obj):
        body = ','.join((repr(x) if isinstance(x, BASE_TYPES) else type(x).__name__ for (i, x) in zip(range(8), obj)))
        if len(obj) > 8:
            body = f'{body}, ...{len(obj) - 8}'
        return body
    if isinstance(obj, BASE_TYPES):
        return repr(obj)
    if type(obj).__name__ == 'function':
        return f'function\n{obj.__name__}'
    elif isinstance(obj, types.MethodType):
        try:
            func_name = obj.__func__.__qualname__
        except AttributeError:
            func_name = '<anonymous>'
        return f'instancemethod\n{func_name}'
    elif <MASK>:
        return f'[{format_sequence(obj)}]'
    elif isinstance(obj, tuple):
        return f'({format_sequence(obj)})'
    elif isinstance(obj, dict):
        return f'dict[{len(obj)}]'
    elif isinstance(obj, types.ModuleType):
        return f'module\n{obj.__name__}'
    elif isinstance(obj, type):
        return f'type\n{obj.__name__}'
    elif isinstance(obj, weakref.ref):
        referent = obj()
        if referent is None:
            return 'weakref (dead referent)'
        else:
            return f'weakref to id 0x{id(referent):x}'
    elif isinstance(obj, types.FrameType):
        filename = obj.f_code.co_filename
        if len(filename) > FRAME_FILENAME_LIMIT:
            filename = '...' + filename[-(FRAME_FILENAME_LIMIT - 3):]
        return f'frame\n{filename}:{obj.f_lineno}'
    else:
        return f'object\n{type(obj).__module__}.{type(obj).__name__}'

@classmethod
def _standardize_dtype(cls, dtype: NumericDtype | str | np.dtype) -> NumericDtype:
    """
        Convert a string representation or a numpy dtype to NumericDtype.
        """
    if isinstance(dtype, str) and dtype.startswith(('Int', 'UInt', 'Float')):
        dtype = dtype.lower()
    if <MASK>:
        mapping = cls._get_dtype_mapping()
        try:
            dtype = mapping[np.dtype(dtype)]
        except KeyError as err:
            raise ValueError(f'invalid dtype specified {dtype}') from err
    return dtype

