def check_tensorimpl_and_storage(call: str, unpacked_bindings: list[Binding]) -> str:
    stmts_before_call: list[str] = []
    stmts_after_call: list[str] = []
    if cpp.name(f.func) in DONT_ENFORCE_SAME_TENSOR_IMPL_OR_STORAGE:
        return call
    for unpacked_binding in unpacked_bindings:
        arg = unpacked_binding.name
        noref_cpp_type = unpacked_binding.nctype.type.remove_const_ref()
        if noref_cpp_type == BaseCType(tensorListT) or noref_cpp_type == BaseCType(iTensorListRefT):
            stmts_before_call += [SAVE_TENSORLIST_STORAGE.substitute(tensorlist_name=arg), SAVE_TENSORLIST_IMPL.substitute(tensorlist_name=arg)]
            stmts_after_call += [ENFORCE_SAME_TENSORLIST_STORAGE.substitute(tensorlist_name=arg), ENFORCE_SAME_TENSORLIST_IMPL.substitute(tensorlist_name=arg)]
        elif noref_cpp_type == ListCType(OptionalCType(BaseCType(tensorT))):
            stmts_before_call += [SAVE_OPTIONALTENSORLIST_STORAGE.substitute(tensorlist_name=arg), SAVE_OPTIONALTENSORLIST_IMPL.substitute(tensorlist_name=arg)]
            stmts_after_call += [ENFORCE_SAME_OPTIONALTENSORLIST_STORAGE.substitute(tensorlist_name=arg), ENFORCE_SAME_OPTIONALTENSORLIST_IMPL.substitute(tensorlist_name=arg)]
        elif noref_cpp_type == BaseCType(tensorT):
            stmts_before_call += [SAVE_TENSOR_STORAGE.substitute(tensor_name=arg), SAVE_TENSOR_IMPL.substitute(tensor_name=arg)]
            stmts_after_call += [ENFORCE_SAME_TENSOR_STORAGE.substitute(tensor_name=arg, out_tensor_name=arg), ENFORCE_SAME_TENSOR_IMPL.substitute(tensor_name=arg)]
    assert stmts_before_call and stmts_after_call or (not stmts_before_call and (not stmts_after_call))
    if f.func.kind() not in (SchemaKind.inplace, SchemaKind.out):
        base_name = f.func.name.name.base
        aliased_arg_name = ALL_VIEW_FUNCTIONS.get(base_name, None)
        if <MASK>:
            aliased_arg_name = unpacked_name(aliased_arg_name)
        for (i, (ret, ret_name)) in enumerate(zip(f.func.returns, cpp.return_names(f))):
            noref_cpp_type = cpp.return_type(ret, symint=True).remove_const_ref()
            if noref_cpp_type == BaseCType(tensorT):
                if aliased_arg_name is not None:
                    assert i == 0, 'Expect non-CompositeImplicitAutograd view function {base} to return single output'
                    stmts_after_call += [ENFORCE_SAME_TENSOR_STORAGE.substitute(tensor_name=aliased_arg_name, out_tensor_name=ret_name)]
                elif type_wrapper_name(f) not in DONT_ENFORCE_STORAGE_IMPL_USE_COUNT:
                    stmts_after_call += [ENFORCE_TENSOR_STORAGE_USE_COUNT_EQUALS_ONE.substitute(tensor_name=ret_name, fn_name=type_wrapper_name(f))]
                if type_wrapper_name(f) not in DONT_ENFORCE_TENSOR_IMPL_USE_COUNT:
                    stmts_after_call += [ENFORCE_TENSOR_IMPL_USE_COUNT_LT_OR_EQ_ONE.substitute(tensor_name=ret_name, fn_name=type_wrapper_name(f))]
            elif noref_cpp_type == ListCType(OptionalCType(BaseCType(tensorT))):
                raise AssertionError(f'Please add use_count checks for {noref_cpp_type}')
            elif noref_cpp_type == BaseCType(tensorListT):
                raise AssertionError(f'Please add use_count checks for {noref_cpp_type}')
    if stmts_before_call and stmts_after_call:
        call = RUN_ONLY_IN_DEBUG_MODE.substitute(statements=stmts_before_call) + call + RUN_ONLY_IN_DEBUG_MODE.substitute(statements=stmts_after_call)
    return call

def _has_constant_mask(self, tree: IterationRangesRoot) -> bool:
    if self.is_native_matmul:
        if V.graph.sizevars.statically_known_lt(tree.numel, 16):
            return False
    if not self.optimize_mask:
        return False
    if self.fixed_config and f'{tree.prefix.upper()}BLOCK' in self.fixed_config:
        if self.fixed_config[f'{tree.prefix.upper()}BLOCK'] == 1:
            return True
    elif V.graph.sizevars.statically_known_equals(tree.numel, 1):
        return True
    if <MASK>:
        max_block = self._get_persistent_RBLOCK(tree.numel)
    elif tree.prefix == 'x' and self.no_x_dim:
        max_block = 1
    else:
        max_block = self.max_block(tree.prefix)
    if tree.is_reduction and self.cooperative_reduction:
        max_block = max_block * self.max_rsplit()
    if V.graph.sizevars.statically_known_multiple_of(tree.numel, max_block):
        return tree.grid_dim != 1 or tree.has_zdim or V.graph.sizevars.statically_known_leq(tree.numel, get_max_y_grid())
    return False

@no_type_check
def _finalize_params(state: _FSDPState) -> None:
    """Finalizes the parameters before the next iteration."""
    handle = state._handle
    if not handle:
        return
    flat_param = handle.flat_param
    if torch.distributed._functional_collectives.is_torchdynamo_compiling():
        if <MASK>:
            pbhs_handle = flat_param._post_backward_hook_handle
            pbhs_handle.remove()
            del flat_param._post_backward_hook_handle
    elif hasattr(flat_param, '_post_backward_hook_state'):
        post_backward_hook_state_len = len(flat_param._post_backward_hook_state)
        expected_post_backward_hook_state_len = int(flat_param.requires_grad) + 1
        _p_assert(post_backward_hook_state_len == expected_post_backward_hook_state_len, f'Invalid: ``_post_backward_hook_state``: {flat_param._post_backward_hook_state}')
        flat_param._post_backward_hook_state[-1].remove()
        delattr(flat_param, '_post_backward_hook_state')
    if flat_param.requires_grad:
        if not state._sync_gradients:
            return
        if not handle._has_optim_in_backward:
            handle.prepare_gradient_for_optim()
        _p_assert(hasattr(flat_param, '_post_backward_called'), 'Expects `_post_backward_called` to be set on the `FlatParameter`')
        flat_param._post_backward_called = False

def on_node_replace(old: Node, new: str, user: Node):
    new_node = self.name_to_node.get(new, None)
    if not new_node:
        return
    assert isinstance(new_node, Node)
    added_nodes = {s.name for s in new_node.meta.get('from_node', [])}
    if old.name in added_nodes:
        return
    action = [NodeSourceAction.REPLACE]
    if <MASK>:
        action.append(NodeSourceAction.CREATE)

    def created_this_pass(source):
        return source.pass_name == self.passname and source.action == [NodeSourceAction.CREATE]
    new_from_node = new_node.meta.get('from_node', [])
    new_from_node = [source for source in new_from_node if not created_this_pass(source)]
    new_node_source = NodeSource(old, self.passname, action)
    new_from_node.append(new_node_source)
    new_node.meta['from_node'] = new_from_node

def executemany(self, query, args):
    try:
        return self.cursor.executemany(query, args)
    except Database.OperationalError as e:
        if <MASK>:
            raise IntegrityError(*tuple(e.args))
        raise

def _raise_if_missing(self, key, indexer, axis_name: str) -> None:
    keyarr = key
    if not isinstance(key, Index):
        keyarr = com.asarray_tuplesafe(key)
    if len(keyarr) and (not isinstance(keyarr[0], tuple)):
        mask = indexer == -1
        if mask.any():
            check = self.levels[0].get_indexer(keyarr)
            cmask = check == -1
            if <MASK>:
                raise KeyError(f'{keyarr[cmask]} not in index')
            raise KeyError(f'{keyarr} not in index')
    else:
        return super()._raise_if_missing(key, indexer, axis_name)

def _AssertCompatible(values, dtype):
    if dtype is None:
        fn = _check_not_tensor
    else:
        try:
            fn = _TF_TO_IS_OK[dtype]
        except KeyError:
            if <MASK>:
                fn = _check_int
            elif dtype.is_floating:
                fn = _check_float
            elif dtype.is_complex:
                fn = _check_complex
            elif dtype.is_quantized:
                fn = _check_quantized
            else:
                fn = _check_not_tensor
    try:
        fn(values)
    except ValueError as e:
        [mismatch] = e.args
        if dtype is None:
            raise TypeError('Expected any non-tensor type, but got a tensor instead.')
        else:
            raise TypeError(f"Expected {dtype.name}, but got {mismatch} of type '{type(mismatch).__name__}'.")

def wrapper(x):
    if is_float(x) or is_integer(x) or is_complex(x):
        if decimal != '.' and thousands is not None and (thousands != ','):
            return formatter(x).replace(',', '§_§-').replace('.', decimal).replace('§_§-', thousands)
        elif <MASK>:
            return formatter(x).replace('.', decimal)
        elif decimal == '.' and thousands is not None and (thousands != ','):
            return formatter(x).replace(',', thousands)
    return formatter(x)

def do_auto_functionalize(mode: 'torch._subclasses.functional_tensor.FunctionalTensorMode', op: OpOverload, args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
    """Functionalizes a call to op(*args, **kwargs) by emitting a call to
    `outs = auto_functionalized(op, normalized_kwargs)`
    and replacing the mutated (args, kwargs) with the corresponding outputs.

    The normalized_kwargs are just the (args, kwargs), but all in kwarg form.
    This makes handling easier for the auto_functionalized HOP.
    """
    from torch._subclasses.functional_tensor import PythonFunctionalizeAPI
    ctx = PythonFunctionalizeAPI(mode=mode)
    normalized_kwargs = {}
    schema = op._schema
    for (idx, arg) in enumerate(schema.arguments):
        if <MASK>:
            normalized_kwargs[arg.name] = kwargs[arg.name]
        elif idx < len(args):
            normalized_kwargs[arg.name] = args[idx]
        else:
            normalized_kwargs[arg.name] = arg.default_value
    unwrapped_kwargs = ctx.unwrap_tensors(normalized_kwargs)
    if 'self' in unwrapped_kwargs or 'self_' in unwrapped_kwargs:
        warnings.warn('Using `self` or `self_` as an argument in the definition of custom ops may lead to ambiguous parsing. Please consider using a different name for this argument to avoid potential issues.')
    with ctx.redispatch_to_next():
        unwrapped_outs = auto_functionalized(op, **unwrapped_kwargs)
    (mutable_args_names, _) = get_mutable_args(op)
    unwrapped_actual_out: Union[Any, tuple[Any]] = unwrapped_outs[:-len(mutable_args_names)]
    unwrapped_mutable_out = unwrapped_outs[-len(mutable_args_names):]
    if len(op._schema.returns) == 0:
        assert unwrapped_actual_out[0] is None
        unwrapped_actual_out = None
    elif len(op._schema.returns) == 1:
        assert len(unwrapped_actual_out) == 1
        unwrapped_actual_out = unwrapped_actual_out[0]
    else:
        assert len(unwrapped_actual_out) == len(op._schema.returns)
    for (name, unwrapped_out) in zip(mutable_args_names, unwrapped_mutable_out):
        if unwrapped_out is None:
            continue

        def sync_update(o, orig_arg):
            ctx.replace(orig_arg, o)
            ctx.commit_update(orig_arg)
            ctx.sync(orig_arg)
        orig_arg = normalized_kwargs[name]
        if isinstance(unwrapped_out, torch.Tensor):
            sync_update(unwrapped_out, orig_arg)
        elif isinstance(unwrapped_out, list) and all((isinstance(o, torch.Tensor) for o in unwrapped_out)):
            assert len(orig_arg) == len(unwrapped_out)
            for (orig_a, o) in zip(orig_arg, unwrapped_out):
                sync_update(o, orig_a)
        else:
            raise RuntimeError(f'unsupported type for auto-functionalization: {unwrapped_out}')
    return ctx.wrap_tensors(unwrapped_actual_out)

def wrap_literal(self, value):
    if type(value) is int:
        if <MASK>:
            log.debug('%s marked dynamic via source whitelist', self.source.name())
            return self.wrap_symint(value, dynamism=DimDynamic.DYNAMIC)
        if is_unbacked_source(self.source.name()):
            log.debug('%s marked unbacked via source whitelist', self.source.name())
            return self.wrap_symint(value, dynamism=DimDynamic.SIZE_LIKE_UNBACKED)
        if not config.specialize_int:
            if is_int_specialization_case(value, self.source):
                recompile_hint = None
                if self.source.guard_source().is_unspecialized_builtin_nn_module() or self.source.guard_source().is_unspecialized_nn_module():
                    recompile_hint = 'torch.compile considers integer attributes of the nn.Module to be static. If you are observing recompilation, you might want to make this integer dynamic using torch._dynamo.config.allow_unspec_int_on_nn_module = True, or convert this integer into a tensor.'
                process_automatic_dynamic(self.tx, self.source.name(), FrameStateSizeEntry.make_scalar(value), is_unspecialized_nn_module=self.source.guard_source().is_unspecialized_nn_module())
                self.install_guards(functools.partial(GuardBuilder.EQUALS_MATCH, recompile_hint=recompile_hint))
                return ConstantVariable.create(value=value, source=self.source)
        return self.wrap_symint(value)
    elif not config.specialize_float and type(value) is float:
        return self.wrap_symfloat(value)
    else:
        self.install_guards(GuardBuilder.CONSTANT_MATCH)
        result = ConstantVariable.create(value=value, source=self.source)
        if isinstance(value, (list, set)):
            return self.tx.output.side_effects.track_mutable(value, result)
        return result

def _fused_adagrad(params: list[Tensor], grads: list[Tensor], state_sums: list[Tensor], state_steps: list[Tensor], grad_scale: Optional[Tensor], found_inf: Optional[Tensor], *, lr: float, weight_decay: float, lr_decay: float, eps: float, has_sparse_grad: bool, maximize: bool, differentiable: bool, has_complex: bool) -> None:
    if not params:
        return
    if has_sparse_grad or has_complex:
        raise RuntimeError('`fused` does not support sparse grad or complex param')
    if differentiable:
        raise RuntimeError('adagrad with fused=True does not support differentiable=True')
    lr = _to_scalar(lr)
    grad_scale_dict = {grad_scale.device: grad_scale} if grad_scale is not None else None
    found_inf_dict = {found_inf.device: found_inf} if found_inf is not None else None
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, state_sums, state_steps])
    for ((device, _), ((device_params_, device_grads_, device_state_sums_, device_state_steps_), _)) in grouped_tensors.items():
        device_params = cast(list[Tensor], device_params_)
        device_grads = cast(list[Tensor], device_grads_)
        device_state_sums = cast(list[Tensor], device_state_sums_)
        device_state_steps = cast(list[Tensor], device_state_steps_)
        (device_grad_scale, device_found_inf) = (None, None)
        if grad_scale is not None and grad_scale_dict is not None:
            if <MASK>:
                grad_scale_dict[device] = grad_scale.to(device, non_blocking=True)
            device_grad_scale = grad_scale_dict[device]
        if found_inf is not None and found_inf_dict is not None:
            if found_inf not in found_inf_dict:
                found_inf_dict[device] = found_inf.to(device, non_blocking=True)
            device_found_inf = found_inf_dict[device]
        torch._foreach_add_(device_state_steps, 1)
        torch._fused_adagrad_(device_params, device_grads, device_state_sums, device_state_steps, lr=lr, lr_decay=lr_decay, weight_decay=weight_decay, eps=eps, maximize=maximize, grad_scale=device_grad_scale, found_inf=device_found_inf)
        if device_found_inf is not None:
            torch._foreach_sub_(device_state_steps, [device_found_inf] * len(device_state_steps))

def to_output_spec(idx: int, o: ArgumentSpec) -> OutputSpec:
    if isinstance(o, TokenArgument):
        return OutputSpec(kind=OutputKind.TOKEN, arg=o, target=None)
    if not isinstance(o, TensorArgument):
        return OutputSpec(kind=OutputKind.USER_OUTPUT, arg=o, target=None)
    name = o.name
    if idx < len(buffer_mutations) + len(parameter_mutations) + len(user_input_mutations) + len(output_tokens):
        if name in buffer_mutations:
            return OutputSpec(kind=OutputKind.BUFFER_MUTATION, arg=o, target=buffer_mutations[name])
        elif name in parameter_mutations:
            return OutputSpec(kind=OutputKind.PARAMETER_MUTATION, arg=o, target=parameter_mutations[name])
        elif name in user_input_mutations:
            return OutputSpec(kind=OutputKind.USER_INPUT_MUTATION, arg=o, target=user_input_mutations[name])
        else:
            raise AssertionError(f'Unknown tensor mutation kind: {name}')
    elif name in user_outputs:
        return OutputSpec(kind=OutputKind.USER_OUTPUT, arg=o, target=None)
    elif name in grad_params:
        return OutputSpec(kind=OutputKind.GRADIENT_TO_PARAMETER, arg=o, target=grad_params[name])
    elif name in grad_user_inputs:
        return OutputSpec(kind=OutputKind.GRADIENT_TO_USER_INPUT, arg=o, target=grad_user_inputs[name])
    elif <MASK>:
        return OutputSpec(kind=OutputKind.LOSS_OUTPUT, arg=o, target=None)
    else:
        raise AssertionError(f'Unknown tensor output kind: {name}')

@classmethod
def _from_tensor_shape(cls, shape: Any, num_row_partitions: int, dtype: dtypes.DType) -> 'DynamicRaggedShape.Spec':
    """Creates a `DynamicRaggedShape.Spec` corresponding to a `tf.TensorShape`.

      It is assumed that this is a `tf.TensorShape` coming from a
      `tf.TensorSpec`, not from `RaggedTensor.shape`.

      In addition to the shape, we need to know the number of row partitions,
      and the dtype used in the shape (tf.int32 or tf.int64).

      Within the dimensions that are partitioned, all dimensions are assumed
      to be uniform.

      Args:
        shape: a TensorShape.
        num_row_partitions: the ragged rank of the RaggedShape.
        dtype: the dtype of the shape (not the tensor); tf.int64 or tf.int32.

      Returns:
        a DynamicRaggedShape.Spec representing a TensorShape.
      """
    if dtype != dtypes.int32 and dtype != dtypes.int64:
        raise ValueError('dtype must be tf.int32 or tf.int64')
    shape = tensor_shape.as_shape(shape)
    if shape.rank is None:
        row_partitions = [RowPartitionSpec(dtype=dtype) for _ in range(num_row_partitions)]
        return DynamicRaggedShape.Spec(row_partitions=row_partitions, static_inner_shape=tensor_shape.TensorShape(None), dtype=dtype)
    if shape.rank <= 1:
        if num_row_partitions:
            raise ValueError('num_row_partitions should be zero ' + 'if shape is a scalar or vector.')
        return DynamicRaggedShape.Spec(row_partitions=[], static_inner_shape=shape, dtype=dtype)
    if <MASK>:
        raise ValueError('num_row_partitions must be less than rank')
    num_elements_so_far = tensor_shape.dimension_value(shape[0])
    rp_specs = []
    for i in range(num_row_partitions):
        current_dim = tensor_shape.dimension_value(shape[i + 1])
        if current_dim is None or num_elements_so_far is None:
            nvals = None
        else:
            nvals = num_elements_so_far * current_dim
        rp_specs.append(RowPartitionSpec(nrows=num_elements_so_far, nvals=nvals, uniform_row_length=current_dim, dtype=dtype))
        num_elements_so_far = nvals
    static_inner_shape = tensor_shape.TensorShape([num_elements_so_far]) + shape[num_row_partitions + 1:]
    return DynamicRaggedShape.Spec(row_partitions=rp_specs, static_inner_shape=static_inner_shape, dtype=dtype)

def plot_training_data_with_decision_boundary(kernel, ax=None, long_title=True, support_vectors=True):
    clf = svm.SVC(kernel=kernel, gamma=2).fit(X, y)
    if ax is None:
        (_, ax) = plt.subplots(figsize=(4, 3))
    (x_min, x_max, y_min, y_max) = (-3, 3, -3, 3)
    ax.set(xlim=(x_min, x_max), ylim=(y_min, y_max))
    common_params = {'estimator': clf, 'X': X, 'ax': ax}
    DecisionBoundaryDisplay.from_estimator(**common_params, response_method='predict', plot_method='pcolormesh', alpha=0.3)
    DecisionBoundaryDisplay.from_estimator(**common_params, response_method='decision_function', plot_method='contour', levels=[-1, 0, 1], colors=['k', 'k', 'k'], linestyles=['--', '-', '--'])
    if <MASK>:
        ax.scatter(clf.support_vectors_[:, 0], clf.support_vectors_[:, 1], s=150, facecolors='none', edgecolors='k')
    ax.scatter(X[:, 0], X[:, 1], c=y, s=30, edgecolors='k')
    ax.legend(*scatter.legend_elements(), loc='upper right', title='Classes')
    if long_title:
        ax.set_title(f' Decision boundaries of {kernel} kernel in SVC')
    else:
        ax.set_title(kernel)
    if ax is None:
        plt.show()

def __init__(self, param_grid):
    if not isinstance(param_grid, (Mapping, Iterable)):
        raise TypeError(f'Parameter grid should be a dict or a list, got: {param_grid!r} of type {type(param_grid).__name__}')
    if isinstance(param_grid, Mapping):
        param_grid = [param_grid]
    for grid in param_grid:
        if not isinstance(grid, dict):
            raise TypeError(f'Parameter grid is not a dict ({grid!r})')
        for (key, value) in grid.items():
            if isinstance(value, np.ndarray) and value.ndim > 1:
                raise ValueError(f'Parameter array for {key!r} should be one-dimensional, got: {value!r} with shape {value.shape}')
            if isinstance(value, str) or not isinstance(value, (np.ndarray, Sequence)):
                raise TypeError(f'Parameter grid for parameter {key!r} needs to be a list or a numpy array, but got {value!r} (of type {type(value).__name__}) instead. Single values need to be wrapped in a list with one element.')
            if <MASK>:
                raise ValueError(f'Parameter grid for parameter {key!r} need to be a non-empty sequence, got: {value!r}')
    self.param_grid = param_grid

def assert_input_compatibility(input_spec, inputs, layer_name):
    """Checks compatibility between the layer and provided inputs.

  This checks that the tensor(s) `inputs` verify the input assumptions
  of a layer (if any). If not, a clear and actional exception gets raised.

  Args:
      input_spec: An InputSpec instance, list of InputSpec instances, a nested
          structure of InputSpec instances, or None.
      inputs: Input tensor, list of input tensors, or a nested structure of
          input tensors.
      layer_name: String, name of the layer (for error message formatting).

  Raises:
      ValueError: in case of mismatch between
          the provided inputs and the expectations of the layer.
  """
    if not input_spec:
        return
    input_spec = nest.flatten(input_spec)
    if isinstance(inputs, dict):
        names = [spec.name for spec in input_spec]
        if all(names):
            list_inputs = []
            for name in names:
                if name not in inputs:
                    raise ValueError('Missing data for input "%s". You passed a data dictionary with keys %s. Expected the following keys: %s' % (name, list(inputs.keys()), names))
                list_inputs.append(inputs[name])
            inputs = list_inputs
    inputs = nest.flatten(inputs)
    for x in inputs:
        if not hasattr(x, 'shape'):
            raise TypeError('Inputs to a layer should be tensors. Got: %s' % (x,))
    if len(inputs) != len(input_spec):
        raise ValueError('Layer ' + layer_name + ' expects ' + str(len(input_spec)) + ' input(s), but it received ' + str(len(inputs)) + ' input tensors. Inputs received: ' + str(inputs))
    for (input_index, (x, spec)) in enumerate(zip(inputs, input_spec)):
        if spec is None:
            continue
        shape = tensor_shape.TensorShape(x.shape)
        if shape.rank is None:
            return
        if spec.ndim is not None and (not spec.allow_last_axis_squeeze):
            ndim = shape.rank
            if ndim != spec.ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected ndim=' + str(spec.ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.max_ndim is not None:
            ndim = x.shape.rank
            if ndim is not None and ndim > spec.max_ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected max_ndim=' + str(spec.max_ndim) + ', found ndim=' + str(ndim))
        if spec.min_ndim is not None:
            ndim = x.shape.rank
            if ndim is not None and ndim < spec.min_ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: : expected min_ndim=' + str(spec.min_ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.dtype is not None:
            if x.dtype.name != spec.dtype:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected dtype=' + str(spec.dtype) + ', found dtype=' + str(x.dtype))
        shape_as_list = shape.as_list()
        if spec.axes:
            for (axis, value) in spec.axes.items():
                if hasattr(value, 'value'):
                    value = value.value
                if value is not None and shape_as_list[int(axis)] not in {value, None}:
                    raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected axis ' + str(axis) + ' of input shape to have value ' + str(value) + ' but received input with shape ' + display_shape(x.shape))
        if spec.shape is not None and shape.rank is not None:
            spec_shape = spec.shape
            if spec.allow_last_axis_squeeze:
                if shape_as_list and shape_as_list[-1] == 1:
                    shape_as_list = shape_as_list[:-1]
                if spec_shape and spec_shape[-1] == 1:
                    spec_shape = spec_shape[:-1]
            for (spec_dim, dim) in zip(spec_shape, shape_as_list):
                if spec_dim is not None and dim is not None:
                    if <MASK>:
                        raise ValueError('Input ' + str(input_index) + ' is incompatible with layer ' + layer_name + ': expected shape=' + str(spec.shape) + ', found shape=' + display_shape(x.shape))

@out_wrapper(exact_dtype=True)
def norm(A: TensorLikeType, ord: Optional[Union[float, str]]=None, dim: Optional[DimsType]=None, keepdim: bool=False, *, dtype: Optional[torch.dtype]=None) -> TensorLikeType:
    if dim is not None:
        if isinstance(dim, Dim):
            dim = (dim,)
        torch._check(len(dim) in (1, 2), lambda : f'linalg.norm: If dim is specified, it must be of length 1 or 2. Got {dim}')
    elif ord is not None:
        torch._check(A.ndim in (1, 2), lambda : f'linalg.norm: If dim is not specified but ord is, the input must be 1D or 2D. Got {A.ndim}D')
    if ord is not None and (dim is not None and len(dim) == 2 or (dim is None and A.ndim == 2)):
        if dim is None:
            dim = (0, 1)
        return matrix_norm(A, ord, dim, keepdim, dtype=dtype)
    else:
        if <MASK>:
            ord = 2.0
        return vector_norm(A, ord, dim, keepdim, dtype=dtype)

def build_py_modules_sources(self):
    if not self.py_modules:
        return
    log.info('building py_modules sources')
    new_py_modules = []
    for source in self.py_modules:
        if is_sequence(source) and len(source) == 3:
            (package, module_base, source) = source
            if self.inplace:
                build_dir = self.get_package_dir(package)
            else:
                build_dir = os.path.join(self.build_src, os.path.join(*package.split('.')))
            if hasattr(source, '__call__'):
                target = os.path.join(build_dir, module_base + '.py')
                source = source(target)
            if <MASK>:
                continue
            modules = [(package, module_base, source)]
            if package not in self.py_modules_dict:
                self.py_modules_dict[package] = []
            self.py_modules_dict[package] += modules
        else:
            new_py_modules.append(source)
    self.py_modules[:] = new_py_modules

def _constant_eager_impl(ctx, value, dtype, shape, verify_shape) -> ops._EagerTensorBase:
    """Creates a constant on the current device."""
    t = convert_to_eager_tensor(value, ctx, dtype)
    if shape is None:
        return t
    shape = tensor_shape.as_shape(shape)
    if <MASK>:
        return t
    if verify_shape:
        raise TypeError(f'Expected Tensor {t} (converted from {value}) with shape {tuple(shape)}, but got shape {tuple(t.shape)}.')
    num_t = t.shape.num_elements()
    if num_t == shape.num_elements():
        return _eager_reshape(t, shape.as_list(), ctx)
    if num_t == 1:
        if t.dtype == dtypes.bool:
            with ops.device('/device:CPU:0'):
                x = _eager_fill(shape.as_list(), _eager_identity(t, ctx), ctx)
            return _eager_identity(x, ctx)
        else:
            return _eager_fill(shape.as_list(), t, ctx)
    raise TypeError(f'Eager execution of tf.constant with unsupported shape. Tensor {t} (converted from {value}) has {num_t:d} elements, but got `shape` {shape} with {shape.num_elements()} elements).')

def _remove_participant_epilogue(state: _RendezvousState, settings: RendezvousSettings) -> None:
    if state.complete:
        if <MASK>:
            msg = 'No participants left in the rendezvous, marking rendezvous as incomplete'
            logger.debug(msg)
            state.complete = False
            state.round += 1
    elif len(state.participants) < settings.min_nodes:
        msg = f'Number of participants {len(state.participants)}) less thanmin_nodes {settings.min_nodes}, clearning deadline in state'
        logger.debug(msg)
        state.deadline = None

def get_tolerance_and_cosine_flag(self, is_training, current_device, name):
    tolerance = 0.0001
    cosine = self.args.cosine
    if self.args.float16 or self.args.amp:
        if self.args.freezing and (freezing := self._tolerance['freezing']):
            higher_fp16 = freezing.get('higher_fp16', None)
            even_higher = freezing.get('even_higher', None)
            if higher_fp16 and name in higher_fp16:
                return (0.01, cosine)
            elif even_higher and name in even_higher:
                return (8 * 0.01, cosine)
        if name in self._tolerance['higher_fp16']:
            return (0.01, cosine)
        elif name in self._tolerance['even_higher']:
            return (8 * 0.01, cosine)
        return (0.001, cosine)
    if self.args.bfloat16:
        if name in self._tolerance['higher_bf16']:
            return (0.01, cosine)
        elif current_device == 'xpu' and name in self._tolerance['higher_bf16_xpu']:
            return (8 * 0.01, cosine)
    if is_training and (current_device == 'cuda' or current_device == 'xpu'):
        tolerance = 0.001
        if name in self._tolerance['cosine']:
            cosine = True
        elif <MASK>:
            tolerance = 0.001
        elif name in self._tolerance['even_higher']:
            tolerance = 8 * 0.01
    return (tolerance, cosine)

def e(self):
    """
        Timezone name.

        If timezone information is not available, return an empty string.
        """
    if not self.timezone:
        return ''
    try:
        if <MASK>:
            return self.data.tzname() or ''
    except NotImplementedError:
        pass
    return ''

def __getattr__(self, key):
    if key in closure:
        return closure[key]
    elif hasattr(typing, key):
        return getattr(typing, key)
    elif <MASK>:
        return getattr(builtins, key)
    return None

def test_global_local(self):

    def f(n):
        if n > 0:
            global for_test_global_local
            if <MASK>:
                for_test_global_local = 1
            else:
                for_test_global_local += 1
            n += for_test_global_local
        return n
    tr = self.transform(f, control_flow)
    assert for_test_global_local is None
    self.assertEqual(tr(1), 2)
    self.assertEqual(for_test_global_local, 1)

def __rmul__(self, other):
    if <MASK>:
        return poly1d(other * self.coeffs)
    else:
        other = poly1d(other)
        return poly1d(polymul(self.coeffs, other.coeffs))

def const_getattr(self, tx: 'InstructionTranslator', name):
    if <MASK>:
        raise_observed_exception(AttributeError, tx, args=[name])
    member = getattr(self.value, name)
    if callable(member):
        raise NotImplementedError
    return member

def _warn_for_unused_params(self):
    if self.tokenizer is not None and self.token_pattern is not None:
        warnings.warn("The parameter 'token_pattern' will not be used since 'tokenizer' is not None'")
    if self.preprocessor is not None and callable(self.analyzer):
        warnings.warn("The parameter 'preprocessor' will not be used since 'analyzer' is callable'")
    if <MASK>:
        warnings.warn("The parameter 'ngram_range' will not be used since 'analyzer' is callable'")
    if self.analyzer != 'word' or callable(self.analyzer):
        if self.stop_words is not None:
            warnings.warn("The parameter 'stop_words' will not be used since 'analyzer' != 'word'")
        if self.token_pattern is not None and self.token_pattern != '(?u)\\b\\w\\w+\\b':
            warnings.warn("The parameter 'token_pattern' will not be used since 'analyzer' != 'word'")
        if self.tokenizer is not None:
            warnings.warn("The parameter 'tokenizer' will not be used since 'analyzer' != 'word'")

def _ifftn_wrapper(ifft_n, default_name):
    """Wrapper around gen_spectral_ops.ifftn."""

    def _ifftn(input_tensor, fft_length=None, axes=None, norm=None, name=None):
        """Wrapper around gen_spectral_ops.*fft that infers fft_length and axes arguments."""
        with _ops.name_scope(name, default_name, [input_tensor, fft_length, axes]) as name:
            axes = _process_empty_axes(input_tensor, axes)
            fft_rank = axes.shape[0]
            input_tensor = _ops.convert_to_tensor(input_tensor, preferred_dtype=_dtypes.complex64)
            input_tensor.shape.with_rank_at_least(fft_rank)
            if fft_length is None:
                fft_length = _infer_fft_length_for_fftn(input_tensor)
            else:
                fft_length = _ops.convert_to_tensor(fft_length, _dtypes.int32)
            input_tensor = _maybe_pad_for_rfft(input_tensor, fft_rank, fft_length)
            fft_length_static = _tensor_util.constant_value(fft_length)
            if fft_length_static is not None:
                fft_length = fft_length_static
            if <MASK>:
                norm = 'backward'
            n = 1
            if norm != 'backward':
                for fft_length_i in fft_length:
                    n *= fft_length_i
                if norm == 'forward':
                    input_tensor *= n
                elif norm == 'ortho':
                    input_tensor *= np.sqrt(n)
            return ifft_n(input_tensor, fft_length, axes, name=name)
    if ifft_n.__doc__ is not None:
        _ifftn.__doc__ = re.sub('    Tcomplex.*?\\n', '', ifft_n.__doc__)
    return _ifftn

def _get_session(op_input_list=()):
    """Returns the session object for the current thread."""
    global _SESSION
    default_session = ops.get_default_session()
    if default_session is not None:
        session = default_session
    else:
        if <MASK>:
            raise RuntimeError('Cannot get session inside Tensorflow graph function.')
        if getattr(_SESSION, 'session', None) is None or _SESSION.session.graph is not _current_graph(op_input_list):
            if distribute_lib.has_strategy():
                configure_and_create_distributed_session(distribute_lib.get_strategy())
            else:
                _SESSION.session = session_module.Session(config=get_default_session_config())
        session = _SESSION.session
    return session

def bulk_update(self, objs, fields, batch_size=None):
    """
        Update the given fields in each of the given objects in the database.
        """
    if batch_size is not None and batch_size <= 0:
        raise ValueError('Batch size must be a positive integer.')
    if not fields:
        raise ValueError('Field names must be given to bulk_update().')
    objs = tuple(objs)
    if not all((obj._is_pk_set() for obj in objs)):
        raise ValueError('All bulk_update() objects must have a primary key set.')
    opts = self.model._meta
    fields = [opts.get_field(name) for name in fields]
    if <MASK>:
        raise ValueError('bulk_update() can only be used with concrete fields.')
    all_pk_fields = set(opts.pk_fields)
    for parent in opts.all_parents:
        all_pk_fields.update(parent._meta.pk_fields)
    if any((f in all_pk_fields for f in fields)):
        raise ValueError('bulk_update() cannot be used with primary key fields.')
    if not objs:
        return 0
    for obj in objs:
        obj._prepare_related_fields_for_save(operation_name='bulk_update', fields=fields)
    self._for_write = True
    connection = connections[self.db]
    max_batch_size = connection.ops.bulk_batch_size([opts.pk, opts.pk, *fields], objs)
    batch_size = min(batch_size, max_batch_size) if batch_size else max_batch_size
    requires_casting = connection.features.requires_casted_case_in_updates
    batches = (objs[i:i + batch_size] for i in range(0, len(objs), batch_size))
    updates = []
    for batch_objs in batches:
        update_kwargs = {}
        for field in fields:
            when_statements = []
            for obj in batch_objs:
                attr = getattr(obj, field.attname)
                if not hasattr(attr, 'resolve_expression'):
                    attr = Value(attr, output_field=field)
                when_statements.append(When(pk=obj.pk, then=attr))
            case_statement = Case(*when_statements, output_field=field)
            if requires_casting:
                case_statement = Cast(case_statement, output_field=field)
            update_kwargs[field.attname] = case_statement
        updates.append(([obj.pk for obj in batch_objs], update_kwargs))
    rows_updated = 0
    queryset = self.using(self.db)
    with transaction.atomic(using=self.db, savepoint=False):
        for (pks, update_kwargs) in updates:
            rows_updated += queryset.filter(pk__in=pks).update(**update_kwargs)
    return rows_updated

def all_test_methods_impl(cls: _TC) -> _TC:
    """Apply decorator to all test methods in class."""
    for name in dir(cls):
        value = getattr(cls, name)
        if <MASK>:
            setattr(cls, name, decorator(*args, **kwargs)(value))
    return cls

@register_decomposition(aten.reflection_pad1d_backward)
@register_decomposition(aten.reflection_pad2d_backward)
@register_decomposition(aten.reflection_pad3d_backward)
@out_wrapper('grad_input')
def _reflection_pad_backward(grad_output, x, padding):
    dim = len(padding) // 2
    dhw = [h - 1 for h in x.shape[-dim:]]
    padding_left = [padding[2 * (dim - 1 - i)] for i in range(dim)]
    padding_right = [padding[2 * (dim - 1 - i) + 1] for i in range(dim)]
    indices = []
    for i in range(x.ndim):
        view_shape = [1] * x.ndim
        view_shape[i] = -1
        indices.append(torch.arange(x.shape[i], device=x.device).view(view_shape))
    b = indices[:-dim]
    xyz = indices[-dim:]

    def index_range_condition(index_range):
        (i, lb, ub) = index_range
        return torch.logical_and(i >= lb, i <= ub)
    center = [xyz[i] + padding_left[i] for i in range(dim)]
    left_reflect = [padding_left[i] - xyz[i] for i in range(dim)]
    right_reflect = [2 * dhw[i] + padding_left[i] - xyz[i] for i in range(dim)]
    range_c = [(center[i], 0, dhw[i] + padding_left[i] + padding_right[i]) for i in range(dim)]
    cond = functools.reduce(aten.logical_and, [index_range_condition(range_c[i]) for i in range(dim)])
    grad = aten._unsafe_masked_index(grad_output, cond, b + center, 0.0)

    def accumulate(grad, out, index_ranges):
        for i in range(dim):
            upper_less_than_lower = index_ranges[i][2] < index_ranges[i][1]
            if <MASK>:
                return grad
        cond = functools.reduce(aten.logical_and, [index_range_condition(index_range) for index_range in index_ranges])
        g = aten._unsafe_masked_index(grad_output, cond, b + out, 0.0)
        return grad + g
    for area in itertools.product(*[[-1, 0, 1] for _ in range(dim)]):
        if area == tuple([0] * dim):
            continue
        outs = []
        index_ranges = []
        for i in range(dim):
            if area[i] == 0:
                out = center[i]
                index_range = range_c[i]
            elif area[i] == -1:
                out = left_reflect[i]
                index_range = (xyz[i], 1, padding_left[i])
            elif area[i] == 1:
                out = right_reflect[i]
                index_range = (xyz[i], dhw[i] - padding_right[i], dhw[i] - 1)
            outs.append(out)
            index_ranges.append(index_range)
        grad = accumulate(grad, outs, index_ranges)
    return grad

def _get_cached_session(self, graph: Optional[ops.Graph]=None, config: Optional[config_pb2.ConfigProto]=None, force_gpu: bool=False, crash_if_inconsistent_args: bool=True) -> s.Session:
    """See cached_session() for documentation."""
    if <MASK>:
        sess = self._create_session(graph=graph, config=config, force_gpu=force_gpu)
        self._cached_session = sess
        self._cached_graph = graph
        self._cached_config = config
        self._cached_force_gpu = force_gpu
        return sess
    else:
        if crash_if_inconsistent_args and self._cached_graph is not graph:
            raise ValueError('The graph used to get the cached session is different than the one that was used to create the session. Maybe create a new session with self.session()')
        if crash_if_inconsistent_args and self._cached_config is not config:
            raise ValueError('The config used to get the cached session is different than the one that was used to create the session. Maybe create a new session with self.session()')
        if crash_if_inconsistent_args and self._cached_force_gpu is not force_gpu:
            raise ValueError('The force_gpu value used to get the cached session is different than the one that was used to create the session. Maybe create a new session with self.session()')
        return self._cached_session

def _override(self, func, args, kwargs):
    if torch.distributed.is_available():
        from torch.distributed._functional_collectives import REDUCE_OP_TO_STR, traceable_collective_remaps
        if <MASK>:
            mapped_func = traceable_collective_remaps[func]
            signature = inspect.signature(func)
            kwargs = dict(signature.bind(*args, **kwargs).arguments)
            args = ()
            if func in (torch.distributed.all_reduce, torch.distributed.reduce_scatter_tensor, torch.distributed._reduce_scatter_base):
                if 'op' in kwargs:
                    kwargs['op'] = REDUCE_OP_TO_STR[kwargs['op']]
            return (mapped_func, args, kwargs)
    if func is torch.tensor:
        if any((isinstance(a, (torch.SymInt, torch.SymFloat, torch.SymBool)) for a in pytree.tree_flatten(args[0])[0])):
            return (torch._refs.tensor, args, kwargs)
    if func.__name__ == '__getitem__' and isinstance(args[0], torch.Tensor):

        def rewrite(dim, item):
            if item is None:
                return (dim + 1, (torch.unsqueeze, [dim]))
            if isinstance(item, (int, torch.SymInt)):
                return (dim, (torch.select, [dim, item]))
            if isinstance(item, slice):
                step = item.step or 1
                if item.start is None and item.stop is None and (step == 1):
                    return (dim + 1, (lambda t: t, []))
                return (dim + 1, (torch.ops.aten.slice, [dim, item.start, item.stop, step]))
        items = list(args[1]) if isinstance(args[1], tuple) else [args[1]]
        has_symint = False
        index_ellipsis = None
        t = args[0]
        n_none_slices = t.ndim + 1
        for (i, item) in enumerate(items):
            if isinstance(item, torch.SymInt) or (isinstance(item, slice) and any((isinstance(s, torch.SymInt) for s in (item.start, item.stop, item.step)))):
                has_symint = True
            if item is Ellipsis:
                index_ellipsis = i
            if item is not None:
                n_none_slices -= 1
        if has_symint:
            if index_ellipsis is not None:
                none_slices = [slice(None)] * n_none_slices
                items[index_ellipsis:index_ellipsis + 1] = none_slices
            dim = 0
            sequence = []
            for item in items:
                if (r := rewrite(dim, item)) is None:
                    return (func, args, kwargs)
                (dim, call_spec) = r
                sequence.append(call_spec)

            def run():
                t = args[0]
                for (_method, _args) in sequence:
                    t = _method(t, *_args)
                return t
            return (run, [], {})
    return (func, args, kwargs)

@trackable.no_automatic_dependency_tracking
def add(self, layer):
    """Adds a layer instance on top of the layer stack.

    Args:
        layer: layer instance.

    Raises:
        TypeError: If `layer` is not a layer instance.
        ValueError: In case the `layer` argument does not
            know its input shape.
        ValueError: In case the `layer` argument has
            multiple output tensors, or is already connected
            somewhere else (forbidden in `Sequential` models).
    """
    if hasattr(layer, '_keras_history'):
        origin_layer = layer._keras_history[0]
        if isinstance(origin_layer, input_layer.InputLayer):
            layer = origin_layer
            logging.warning('Please add `keras.layers.InputLayer` instead of `keras.Input` to Sequential model. `keras.Input` is intended to be used by Functional model.')
    if isinstance(layer, module.Module):
        if not isinstance(layer, base_layer.Layer):
            layer = functional.ModuleWrapper(layer)
    else:
        raise TypeError('The added layer must be an instance of class Layer. Found: ' + str(layer))
    tf_utils.assert_no_legacy_layers([layer])
    if not self._is_layer_name_unique(layer):
        raise ValueError('All layers added to a Sequential model should have unique names. Name "%s" is already the name of a layer in this model. Update the `name` argument to pass a unique name.' % (layer.name,))
    self.built = False
    set_inputs = False
    self._maybe_create_attribute('_self_tracked_trackables', [])
    if not self._self_tracked_trackables:
        if isinstance(layer, input_layer.InputLayer):
            set_inputs = True
        else:
            (batch_shape, dtype) = training_utils.get_input_shape_and_dtype(layer)
            if batch_shape:
                x = input_layer.Input(batch_shape=batch_shape, dtype=dtype, name=layer.name + '_input')
                layer(x)
                set_inputs = True
        if set_inputs:
            outputs = nest.flatten(layer._inbound_nodes[-1].outputs)
            if len(outputs) != 1:
                raise ValueError(SINGLE_LAYER_OUTPUT_ERROR_MSG)
            self.outputs = outputs
            self.inputs = layer_utils.get_source_inputs(self.outputs[0])
            self.built = True
            self._has_explicit_input_shape = True
    elif <MASK>:
        output_tensor = layer(self.outputs[0])
        if len(nest.flatten(output_tensor)) != 1:
            raise ValueError(SINGLE_LAYER_OUTPUT_ERROR_MSG)
        self.outputs = [output_tensor]
        self.built = True
    if set_inputs or self._graph_initialized:
        self._init_graph_network(self.inputs, self.outputs)
        self._graph_initialized = True
    else:
        self._self_tracked_trackables.append(layer)
        self._handle_deferred_layer_dependencies([layer])
    self._layer_call_argspecs[layer] = tf_inspect.getfullargspec(layer.call)

def run_compile_forward(self, num_runs, print_per_iter=False, cuda_sync=False):
    """Run the forward path of an op with compile mode"""
    if self._compile_forward_graph is None:
        self._compile_forward_graph = self._generate_compile_forward_graph()
    self._compile_forward_graph(num_runs)
    if <MASK>:
        torch.cuda.synchronize(torch.cuda.current_device())

def __setattr__(self, attr, val):
    if attr in ('setfield', 'getfield', 'dtype'):
        raise AttributeError(f"Cannot set '{attr}' attribute")
    fielddict = nt.void.__getattribute__(self, 'dtype').fields
    res = fielddict.get(attr, None)
    if res:
        return self.setfield(val, *res[:2])
    elif <MASK>:
        return nt.void.__setattr__(self, attr, val)
    else:
        raise AttributeError(f"'record' object has no attribute '{attr}'")

def _match_nodes(self, pn: Node, gn: Node, match: InternalMatch, node_name_match: str='') -> bool:
    logger.info('  matching %s to %s', pn, gn)
    assert isinstance(pn, Node) and isinstance(gn, Node), str(f'pn and gn must be Node, pn: {pn}, gn: {gn}')
    if pn in match.nodes_map:
        return match.nodes_map[pn] == gn
    if gn in match.nodes_map.values():
        return False
    if not self._nodes_are_equal(pn, gn, node_name_match):
        return False
    saved_match = copy.copy(match)
    match.nodes_map[pn] = gn
    if pn.op == 'placeholder':
        return True
    match_found = True

    def _match_args(args1: Union[list, tuple], args2: Union[list, tuple]) -> bool:
        if <MASK>:
            return False
        for (a1, a2) in zip(args1, args2):
            if isinstance(a1, Node) and isinstance(a2, Node):
                matched = self._match_nodes(a1, a2, match)
            elif isinstance(a1, (list, tuple)) and isinstance(a2, (list, tuple)):
                matched = _match_args(a1, a2)
            else:
                matched = self._match_literals(a1, a2, match) or self.ignore_literals
            if not matched:
                return False
        return True
    (pn_args, gn_args) = (None, None)
    if (len(pn.args) != len(gn.args) or list(pn.kwargs.keys()) != list(gn.kwargs.keys())) and pn.op == 'call_function' and isinstance(pn.target, torch._ops.OpOverload):
        args_schema = pn.target._schema.arguments

        def get_all_arguments(orig_args, orig_kwargs):
            all_args = []
            for (i, schema) in enumerate(args_schema):
                if schema.name in orig_kwargs:
                    all_args.append(orig_kwargs[schema.name])
                elif not schema.kwarg_only and i < len(orig_args):
                    all_args.append(orig_args[i])
                else:
                    all_args.append(schema.default_value)
            return all_args
        pn_args = get_all_arguments(pn.args, pn.kwargs)
        gn_args = get_all_arguments(gn.args, gn.kwargs)
    elif len(pn.args) == len(gn.args) and list(pn.kwargs.keys()) == list(gn.kwargs.keys()):
        pn_args = list(pn.args)
        gn_args = list(gn.args)
        pn_args.extend(list(pn.kwargs.values()))
        gn_args.extend(list(gn.kwargs.values()))
    else:
        match_found = False
    match_found = match_found and pn_args is not None and (gn_args is not None) and _match_args(pn_args, gn_args)
    if not match_found:
        match = copy.copy(saved_match)
        return False
    return True

def _commastring(astr):
    startindex = 0
    result = []
    islist = False
    while startindex < len(astr):
        mo = format_re.match(astr, pos=startindex)
        try:
            (order1, repeats, order2, dtype) = mo.groups()
        except (TypeError, AttributeError):
            raise ValueError(f'format number {len(result) + 1} of "{astr}" is not recognized') from None
        startindex = mo.end()
        if startindex < len(astr):
            if space_re.match(astr, pos=startindex):
                startindex = len(astr)
            else:
                mo = sep_re.match(astr, pos=startindex)
                if not mo:
                    raise ValueError('format number %d of "%s" is not recognized' % (len(result) + 1, astr))
                startindex = mo.end()
                islist = True
        if order2 == '':
            order = order1
        elif order1 == '':
            order = order2
        else:
            order1 = _convorder.get(order1, order1)
            order2 = _convorder.get(order2, order2)
            if order1 != order2:
                raise ValueError(f'inconsistent byte-order specification {order1} and {order2}')
            order = order1
        if order in ('|', '=', _nbo):
            order = ''
        dtype = order + dtype
        if repeats == '':
            newitem = dtype
        else:
            if <MASK>:
                warnings.warn('Passing in a parenthesized single number for repeats is deprecated; pass either a single number or indicate a tuple with a comma, like "(2,)".', DeprecationWarning, stacklevel=2)
            newitem = (dtype, ast.literal_eval(repeats))
        result.append(newitem)
    return result if islist else result[0]

def deserialize_graph_output(self, output) -> Optional[Union[torch.fx.Node, int]]:
    if output.type == 'as_tensor':
        return self.serialized_name_to_node[output.as_tensor.name]
    elif output.type == 'as_sym_int':
        return self.serialized_name_to_node[output.as_sym_int.as_name]
    elif output.type == 'as_sym_bool':
        return self.serialized_name_to_node[output.as_sym_bool.as_name]
    elif output.type == 'as_sym_float':
        return self.serialized_name_to_node[output.as_sym_float.as_name]
    elif <MASK>:
        return output.as_int
    elif output.type == 'as_float':
        return output.as_float
    elif output.type == 'as_bool':
        return output.as_bool
    elif output.type == 'as_none':
        return None
    else:
        raise SerializeError(f'Unable to deserialize output node {output}')

