@_apply_requires_grad_to_samples
def _maybe_failing_sample_inputs_sparse_elementwise_binary_mul(op_info, device, dtype, requires_grad, layout, **kwargs):
    """Generator of samples that are known to fail or that were failing in past."""
    blocksize = (1, 1) if layout in {torch.sparse_bsr, torch.sparse_bsc} else None
    regular = torch.tensor([[1, 2], [3, 4]], device=device, dtype=dtype).to_sparse(layout=layout, dense_dim=0, blocksize=blocksize)
    batch = torch.tensor([[[1, 2], [3, 4]], [[4, 5], [6, 7]]], device=device, dtype=dtype).to_sparse(layout=layout, dense_dim=0, blocksize=blocksize)
    hybrid = torch.tensor([[[1], [2]], [[3], [4]]], device=device, dtype=dtype).to_sparse(layout=layout, dense_dim=1, blocksize=blocksize)
    if layout is torch.sparse_csr:
        yield SampleInput(batch, args=(batch,))
        yield SampleInput(torch.zeros_like(hybrid).requires_grad_(requires_grad), args=(torch.zeros_like(hybrid).requires_grad_(requires_grad),))
        if dtype is torch.complex32:
            yield SampleInput(regular, args=(regular,))
        if <MASK>:
            yield SampleInput(regular, args=(regular,))
    if layout is torch.sparse_csc:
        yield SampleInput(regular, args=(regular,))
    if layout is torch.sparse_bsr:
        yield SampleInput(regular, args=(regular,))
    if layout is torch.sparse_bsc:
        yield SampleInput(regular, args=(regular,))
    if layout is torch.sparse_coo:
        if dtype is torch.complex32:
            yield SampleInput(regular, args=(regular,))
        if dtype is torch.bool and regular.is_cpu:
            yield SampleInput(regular, args=(regular,))
        if dtype in {torch.bool, torch.float16} and regular.is_cpu:
            yield SampleInput(hybrid, args=(hybrid,))

def compute_output_shape(self, input_shape):
    input_shape = tensor_shape.TensorShape(input_shape).as_list()
    if self.data_format == 'channels_first':
        if input_shape[2] is not None:
            rows = input_shape[2] + self.padding[0][0] + self.padding[0][1]
        else:
            rows = None
        if input_shape[3] is not None:
            cols = input_shape[3] + self.padding[1][0] + self.padding[1][1]
        else:
            cols = None
        return tensor_shape.TensorShape([input_shape[0], input_shape[1], rows, cols])
    elif self.data_format == 'channels_last':
        if <MASK>:
            rows = input_shape[1] + self.padding[0][0] + self.padding[0][1]
        else:
            rows = None
        if input_shape[2] is not None:
            cols = input_shape[2] + self.padding[1][0] + self.padding[1][1]
        else:
            cols = None
        return tensor_shape.TensorShape([input_shape[0], rows, cols, input_shape[3]])

def _meta_grouped_mm_common(mat_a: Tensor, mat_b: Tensor, scale_a: Optional[torch.Tensor], scale_b: Optional[torch.Tensor], offs: Optional[Tensor]=None, bias: Optional[Tensor]=None, scale_result: Optional[torch.Tensor]=None, out_dtype: Optional[torch.dtype]=None, use_fast_accum: bool=False):
    torch._check((scale_a is None) == (scale_b is None), lambda : 'Either both scale factors are given, or none')
    scaled = scale_a is not None and scale_b is not None
    if <MASK>:
        fp8_dtype = torch.float8_e4m3fnuz if torch.version.hip else torch.float8_e4m3fn
        torch._check(mat_a.dtype == fp8_dtype and mat_b.dtype == fp8_dtype, lambda : f'Expected inputs of E4M3 FP8 type but got mat_a.dtype={mat_a.dtype} and mat_b.dtype={mat_b.dtype}.')
    else:
        torch._check(mat_a.dtype == torch.bfloat16 and mat_b.dtype == torch.bfloat16, lambda : f'Expected inputs of BF16 type but got mat_a.dtype={mat_a.dtype} and mat_b.dtype={mat_b.dtype}.')
    torch._check(mat_a.dim() in [2, 3] and mat_b.dim() in [2, 3], lambda : f'Multiplicands must be 2D or 3D but got mat_a.dim()={mat_a.dim()} and mat_b.dim()={mat_b.dim()}')
    mat_a_is_2d = mat_a.dim() == 2
    mat_b_is_2d = mat_b.dim() == 2
    if not mat_a_is_2d or not mat_b_is_2d:
        torch._check(mat_a.size(-1) == mat_b.size(-2), lambda : 'contraction dimension of mat_a and mat_b must match')
    if scaled:

        def is_row_major(mat):
            mat_stride = mat.stride()
            return mat_stride[-2] > 1 and mat_stride[-1] == 1

        def is_col_major(mat):
            mat_stride = mat.stride()
            return mat_stride[-2] == 1 and mat_stride[-1] > 1
        torch._check(is_row_major(mat_a), lambda : f'Expected mat_a tensor to be row major in the last two dimensions, got strides {mat_a.stride()[-2:]}')
        torch._check(is_col_major(mat_b), lambda : f'Expected mat_b tensor to be column major in the last two dimensions, got strides {mat_b.stride()[-2:]}')

    def check_valid_strides(mat_name, mat):
        end_dim = mat.dim() - 1
        alignment = 16 // mat.element_size()
        mat_stride = mat.stride()
        if mat_stride[end_dim - 1] == 1 and mat_stride[end_dim] >= max(1, mat.shape[end_dim - 1]):
            torch._check(mat_stride[end_dim] % alignment == 0, lambda : f'Expected {mat_name} stride along {end_dim} dim to be multiple of 16 bytes, got {mat_stride[end_dim]}.')
        elif mat_stride[end_dim] == 1 and mat_stride[end_dim - 1] >= max(1, mat.shape[end_dim]):
            torch._check(mat_stride[end_dim - 1] % alignment == 0, lambda : f'Expected {mat_name} stride along {end_dim - 1} dim to be multiple of 16 bytes, got {mat_stride[end_dim - 1]}.')
        else:
            torch._check(False, lambda : f'Invalid strides/sizes, got {mat_stride} for strides and {mat.shape} for sizes.')
    check_valid_strides('mat_a', mat_a)
    check_valid_strides('mat_b', mat_b)
    if scale_a is not None and scale_b is not None:
        torch._check(scale_a.dtype == torch.float32 and scale_b.dtype == torch.float32 or (scale_a.dtype == torch.float8_e8m0fnu and scale_b.dtype == torch.float8_e8m0fnu), lambda : f'For FP8 scales must both be float32, or for MXFP8 both scales must be float8_e8m0fnu. Got scale_a.dtype={scale_a.dtype} and scale_b.dtype={scale_b.dtype}.')
        is_mxfp8 = scale_a.dtype == torch.float8_e8m0fnu and scale_b.dtype == torch.float8_e8m0fnu

        def round_up(x, y):
            """Rounds up x to nearest multiple of y"""
            return (x + y - 1) // y * y

        def check_scale(scale_name, scale, mat, scaled_dim, scale_multiplier=1):
            if mat.dim() == 2:
                torch._check(scale.is_contiguous(), lambda : f'Expected {scale_name} to be contiguous.')
                if is_mxfp8:
                    torch._check(scale.dim() == mat.dim(), lambda : f'For MXFP8, scale must have same number of dimensions as target tensor, but {scale_name} has mat.ndim={mat.ndim} and scale.ndim={scale.ndim}')
                else:
                    torch._check(scale.dim() == 1, lambda : f'Expected {scale_name} to be 1D tensor, but got {scale.dim()}D tensor.')
                    torch._check(scale.shape[0] == mat.shape[scaled_dim] * scale_multiplier, lambda : f'Expected {scale_name} to have {mat.shape[scaled_dim] * scale_multiplier} elements, got {scale.shape[0]} elements.')
            else:
                torch._check(scale.stride(-1) == 1, lambda : f'Expected {scale_name} to be contiguous in the last dimension.')
                torch._check(scale.shape[0] == mat.shape[0], lambda : f'Expected {scale_name} batch dimension to be {mat.shape[0]}, got {scale.shape[0]}.')
                if is_mxfp8:
                    torch._check(scale.ndim == mat.ndim - 1, lambda : f'For MXFP8, 3d tensor should have 2d scales, but {scale_name} has mat.ndim={mat.ndim} and scale.ndim={scale.ndim}')
                    (G, K, N) = mat.shape
                    block_size = 32
                    blocked_K = round_up(K / block_size, 4)
                    blocked_N = round_up(N, 128)
                    torch._check(scale.shape[0] == G and scale.shape[1] == blocked_K * blocked_N, lambda : f'For MXFP8, expected mat.shape={mat.shape} to have scale shape of ({G},{blocked_K * blocked_N}), but got {scale.shape}')
                else:
                    torch._check(scale.dim() == 2, lambda : f'Expected {scale_name} to be 2D tensor, but got {scale.dim()}D tensor.')
                    torch._check(scale.shape[1] == mat.shape[1 + scaled_dim], lambda : f'Expected {scale_name} non-batch dimension to be {mat.shape[1 + scaled_dim]}, got {scale.shape[1]}.')
        scale_multiplier = offs.shape[0] if offs is not None and mat_a_is_2d and mat_b_is_2d else 1
        check_scale('scale_a', scale_a, mat_a, 0, scale_multiplier)
        check_scale('scale_b', scale_b, mat_b, 1, scale_multiplier)
        torch._check(scale_result is None, lambda : 'Scale result tensor provided, but it is not supported yet.')
    if mat_a_is_2d or mat_b_is_2d:
        torch._check(offs is not None, lambda : f'Offsets tensor not provided, but is needed for {mat_a.dim()}D/{mat_b.dim()}D multiplicand layouts.')
        if offs is not None:
            torch._check(offs.dim() == 1, lambda : f'Offsets tensor must be 1D, but got offs.dim()={offs.dim()}.')
            torch._check(offs.dtype == torch.int32, lambda : f'Offsets tensor must be integer (int32) tensor, but got {offs.dtype}.')
    else:
        torch._check(offs is None, lambda : 'Offsets tensor provided, but is not needed for 3D/3D multiplicand layouts.')
    torch._check(bias is None, lambda : 'Bias tensor provided, but it is not supported yet.')
    torch._check(out_dtype is None or out_dtype == torch.bfloat16, lambda : 'If output dtype provided, it must be torch.bfloat16.')
    return _create_grouped_mm_output_tensor(mat_a, mat_b, offs, out_dtype)

@functools.cache
def _get_overridable_functions() -> tuple[dict[Any, list[Callable]], dict[Callable, str]]:
    overridable_funcs = collections.defaultdict(list)
    index = {}
    tested_namespaces = [('torch', torch, torch.__all__), ('torch.functional', torch.functional, torch.functional.__all__), ('torch.nn.functional', torch.nn.functional, dir(torch.nn.functional)), ('torch.nn.init', torch.nn.init, dir(torch.nn.init)), ('torch.Tensor', torch.Tensor, dir(torch.Tensor)), ('torch.linalg', torch.linalg, dir(torch.linalg)), ('torch.fft', torch.fft, dir(torch.fft)), ('torch.special', torch.special, dir(torch.special))]
    for (namespace_str, namespace, ns_funcs) in tested_namespaces:
        for func_name in ns_funcs:
            ignore = False
            if namespace is not torch.Tensor:
                if func_name.startswith('__'):
                    continue
                elif func_name.startswith('_'):
                    ignore = True
                elif func_name.endswith('_'):
                    ignore = True
                elif not func_name[0].islower():
                    ignore = True
                elif func_name == 'unique_dim':
                    continue
            else:
                func = getattr(namespace, func_name)
                if getattr(object, func_name, None) == func:
                    continue
                if func_name == '__weakref__':
                    continue
            func = getattr(namespace, func_name)
            if namespace is torch.Tensor and getattr(object, func_name, None) == func:
                continue
            if isinstance(func, types.ModuleType):
                continue
            if isinstance(func, __future__._Feature):
                continue
            if not callable(func) and hasattr(func, '__get__'):
                index[func.__get__] = f'{namespace_str}.{func_name}.__get__'
                index[func.__set__] = f'{namespace_str}.{func_name}.__set__'
                if <MASK>:
                    continue
                if func.__get__ in get_ignored_functions():
                    msg = '{}.{} is in the tuple returned by torch._overrides.get_ignored_functions but still has an explicit override'
                    assert func.__get__ not in get_testing_overrides(), msg.format(namespace, func.__name__)
                    continue
                else:
                    overridable_funcs[func].append(func.__get__)
                    continue
            if not callable(func):
                continue
            index[func] = f'{namespace_str}.{func_name}'
            if ignore:
                continue
            if func in get_ignored_functions():
                msg = '{}.{} is in the tuple returned by torch._overrides.get_ignored_functions but still has an explicit override'
                assert func not in get_testing_overrides(), msg.format(namespace, func.__name__)
                continue
            overridable_funcs[namespace].append(func)
    return (overridable_funcs, index)

def __call__(self, inputs):
    inputs = nest.flatten(inputs, expand_composites=True)
    session = get_session(inputs)
    feed_arrays = []
    array_vals = []
    feed_symbols = []
    symbol_vals = []
    for (tensor, value) in zip(self.inputs, inputs):
        if value is None:
            continue
        if tensor_util.is_tf_type(value):
            feed_symbols.append(tensor)
            symbol_vals.append(value)
        else:
            feed_arrays.append(tensor)
            tensor_type = dtypes_module.as_dtype(tensor.dtype)
            array_vals.append(numpy_compat.np_asarray(value, dtype=tensor_type.as_numpy_dtype))
    if <MASK>:
        for key in sorted(self.feed_dict.keys()):
            array_vals.append(numpy_compat.np_asarray(self.feed_dict[key], dtype=key.dtype.as_numpy_dtype))
    if self._callable_fn is None or feed_arrays != self._feed_arrays or symbol_vals != self._symbol_vals or (feed_symbols != self._feed_symbols) or (self.fetches != self._fetches) or (session != self._session):
        self._make_callable(feed_arrays, feed_symbols, symbol_vals, session)
    fetched = self._callable_fn(*array_vals, run_metadata=self.run_metadata)
    self._call_fetch_callbacks(fetched[-len(self._fetches):])
    output_structure = nest.pack_sequence_as(self._outputs_structure, fetched[:len(self.outputs)], expand_composites=True)
    return nest.map_structure(self._eval_if_composite, output_structure)

@keep_lazy_text
def capfirst(x):
    """Capitalize the first letter of a string."""
    if not x:
        return x
    if <MASK>:
        x = str(x)
    return x[0].upper() + x[1:]

