        unimplemented_v2(gb_type='Unsupported key type for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace itertools.groupby with key type: {str(type(key))}. We only support grouping keys that are constants (int, float, str, etc.)', hints=[*graph_break_hints.SUPPORTABLE])

def __init__(self, kernel_size: _size_3_t, output_size: Optional[_size_3_t]=None, output_ratio: Optional[_ratio_3_t]=None, return_indices: bool=False, _random_samples=None) -> None:
    super().__init__()
    if <MASK>:
        raise ValueError(f'kernel_size must greater than 0, but got {kernel_size}')
    self.kernel_size = _triple(kernel_size)
    self.return_indices = return_indices
    self.register_buffer('_random_samples', _random_samples)
    self.output_size = _triple(output_size) if output_size is not None else None
    self.output_ratio = _triple(output_ratio) if output_ratio is not None else None
    if output_size is None and output_ratio is None:
        raise ValueError('FractionalMaxPool3d requires specifying either an output size, or a pooling ratio')
    if output_size is not None and output_ratio is not None:
        raise ValueError('only one of output_size and output_ratio may be specified')
    if self.output_ratio is not None:
        if not (0 < self.output_ratio[0] < 1 and 0 < self.output_ratio[1] < 1 and (0 < self.output_ratio[2] < 1)):
            raise ValueError(f'output_ratio must be between 0 and 1 (got {output_ratio})')

def _compute_stats(self) -> None:
    """populates the name -> stats map"""
    for event in self.events:
        if <MASK>:
            continue
        if 'device' not in event['args']:
            continue
        dev_tmp = event['args']['device']
        if dev_tmp not in self._devices:
            continue
        dev = self._devices[event['args']['device']]
        dur = event['dur']
        if 'kernel_flop' in event['args']:
            assert dur != 0
            op_flops = event['args']['kernel_flop'] / (dur / 1000000.0)
        else:
            op_flops = 0
        if 'kernel_num_gb' in event['args']:
            assert dur != 0
            op_gbps = event['args']['kernel_num_gb'] / (dur / 1000000.0)
        else:
            op_gbps = 0
        if dev.info is not None:
            dtype = self.convert_dtype(event) or self.dtype
            if dtype is None:
                raise RuntimeError('dtype is not found on tensor and default dtype is not set')
            achieved_flops = 100 * op_flops / (1000000000000.0 * dev.info.tops[dtype])
            achieved_bandwidth = 100 * op_gbps / dev.info.dram_bw_gbs
        else:
            achieved_flops = 0
            achieved_bandwidth = 0
        if 'name' not in event['args']:
            continue
        dev.stats[event['name']].add(KernelStats(flops=op_flops, bw=op_gbps, latency=dur, achieved_bandwidth=achieved_bandwidth, achieved_flops=achieved_flops))

@classmethod
def convert(cls, style_dict, num_format_str=None) -> dict[str, Any]:
    """
        converts a style_dict to an xlsxwriter format dict

        Parameters
        ----------
        style_dict : style dictionary to convert
        num_format_str : optional number format string
        """
    props = {}
    if num_format_str is not None:
        props['num_format'] = num_format_str
    if style_dict is None:
        return props
    if 'borders' in style_dict:
        style_dict = style_dict.copy()
        style_dict['border'] = style_dict.pop('borders')
    for (style_group_key, style_group) in style_dict.items():
        for (src, dst) in cls.STYLE_MAPPING.get(style_group_key, []):
            if dst in props:
                continue
            v = style_group
            for k in src:
                try:
                    v = v[k]
                except (KeyError, TypeError):
                    break
            else:
                props[dst] = v
    if isinstance(props.get('pattern'), str):
        props['pattern'] = 0 if props['pattern'] == 'none' else 1
    for k in ['border', 'top', 'right', 'bottom', 'left']:
        if isinstance(props.get(k), str):
            try:
                props[k] = ['none', 'thin', 'medium', 'dashed', 'dotted', 'thick', 'double', 'hair', 'mediumDashed', 'dashDot', 'mediumDashDot', 'dashDotDot', 'mediumDashDotDot', 'slantDashDot'].index(props[k])
            except ValueError:
                props[k] = 2
    if <MASK>:
        props['font_script'] = ['baseline', 'superscript', 'subscript'].index(props['font_script'])
    if isinstance(props.get('underline'), str):
        props['underline'] = {'none': 0, 'single': 1, 'double': 2, 'singleAccounting': 33, 'doubleAccounting': 34}[props['underline']]
    if props.get('valign') == 'center':
        props['valign'] = 'vcenter'
    return props

def is_closed(self, name=None):
    """Returns true if queue is closed.

    This operation returns true if the queue is closed and false if the queue
    is open.

    >>> q = tf.queue.FIFOQueue(capacity=3, dtypes=tf.int32)
    >>> q.is_closed()
    <tf.Tensor: shape=(), dtype=bool, numpy=False>

    Args:
      name: A name for the operation (optional).

    Returns:
      True if the queue is closed and false if the queue is open.
    """
    if name is None:
        name = '%s_Is_Closed' % self._name
    if <MASK>:
        return gen_data_flow_ops.queue_is_closed_v2(self._queue_ref, name=name)
    else:
        return gen_data_flow_ops.queue_is_closed_(self._queue_ref, name=name)

@functools.wraps(func)
def new_func(*args, **kwargs):
    """Keyword args only wrapper."""
    if <MASK>:
        raise ValueError(f'The function {func.__name__} only accepts keyword arguments. Do not pass positional arguments. Received the following positional arguments: {args}')
    return func(**kwargs)

def _wrap_applied_output(self, data: Series, values: list[Any], not_indexed_same: bool=False, is_transform: bool=False) -> DataFrame | Series:
    """
        Wrap the output of SeriesGroupBy.apply into the expected result.

        Parameters
        ----------
        data : Series
            Input data for groupby operation.
        values : List[Any]
            Applied output for each group.
        not_indexed_same : bool, default False
            Whether the applied outputs are not indexed the same as the group axes.

        Returns
        -------
        DataFrame or Series
        """
    if len(values) == 0:
        if is_transform:
            res_index = data.index
        elif not self.group_keys:
            res_index = None
        else:
            res_index = self._grouper.result_index
        return self.obj._constructor([], name=self.obj.name, index=res_index, dtype=data.dtype)
    assert values is not None
    if <MASK>:
        index = self._grouper.result_index
        res_df = self.obj._constructor_expanddim(values, index=index)
        res_ser = res_df.stack()
        res_ser.name = self.obj.name
        return res_ser
    elif isinstance(values[0], (Series, DataFrame)):
        result = self._concat_objects(values, not_indexed_same=not_indexed_same, is_transform=is_transform)
        if isinstance(result, Series):
            result.name = self.obj.name
        if not self.as_index and not_indexed_same:
            result = self._insert_inaxis_grouper(result)
            result.index = default_index(len(result))
        return result.__finalize__(self.obj, method='groupby')
    else:
        result = self.obj._constructor(data=values, index=self._grouper.result_index, name=self.obj.name)
        if not self.as_index:
            result = self._insert_inaxis_grouper(result)
            result.index = default_index(len(result))
        return result.__finalize__(self.obj, method='groupby')

def maybe_cythonize(extensions, *args, **kwargs):
    """
    Render tempita templates before calling cythonize. This is skipped for

    * clean
    * sdist
    """
    if <MASK>:
        return extensions
    elif not _CYTHON_INSTALLED:
        if _CYTHON_VERSION:
            raise RuntimeError(f'Cannot cythonize with old Cython version ({_CYTHON_VERSION} installed, needs {min_cython_ver})')
        raise RuntimeError('Cannot cythonize without Cython installed.')
    parser = argparse.ArgumentParser()
    parser.add_argument('--parallel', '-j', type=int, default=1)
    (parsed, _) = parser.parse_known_args()
    kwargs['nthreads'] = parsed.parallel
    build_ext.render_templates(_pxifiles)
    if debugging_symbols_requested:
        kwargs['gdb_debug'] = True
    return cythonize(extensions, *args, **kwargs)

def trackable_has_serialize_to_tensor(obj):
    """Returns whether obj's class has `_serialize_to_tensors` defined."""
    if obj is base_delegate.DelegatingTrackableMixin:
        return trackable_has_serialize_to_tensor(obj._trackable)
    try:
        if '_serialize_to_tensors' in obj.__dict__:
            return True
    except (AttributeError, TypeError):
        pass
    for t in type(obj).mro():
        if <MASK>:
            return trackable_has_serialize_to_tensor(obj._trackable)
        if t is trackable.Trackable:
            return False
        elif '_serialize_to_tensors' in t.__dict__:
            return True
        elif '_gather_saveables_for_checkpoint' in t.__dict__:
            return False
    return False

def from_dynamic_shapes_to_dynamic_axes(dynamic_shapes: dict[str, Any] | tuple[Any, ...] | list[Any], input_names: Sequence[str], exception: Exception) -> dict[str, Any] | None:
    """
    Converts dynamic_shapes into dynamic_axes by removing torch.export.Dim wrapping
    and converting to list or dict form based on whether dimension names are present.

    dynamic_shapes examples:
    (1) dynamic_shapes = {"x": {0: Dim("my_custom_axis_name_1")}, "y": {1: Dim("my_custom_axis_name_2")}}
    (2) dynamic_shapes = ({0: Dim("my_custom_axis_name_1"}, {1: Dim("my_custom_axis_name_2")})

    these will be converted to dynamic_axes respectively:
    (1) dynamic_axes = {"x": [0], "y": [1]}
    (2) dynamic_axes = {"x": [0], "y": [1]}

    NOTE: If the model input is nested, so is the dynamic_shapes, we need to flatten the dynamic_shapes,
    and then assign the axes to the input names in the order they are provided.

    NOTE: input_names are used to assign the axes to the correct input names. If the input names are not
    provided, or less than the dynamic inputs/axes, it raises an error.
    """
    (flat_dynamic_shapes, _) = _flatten_dynamic_shapes_to_axes(dynamic_shapes)
    if <MASK>:
        raise ValueError(f'To construct dynamic_axes from dynamic_shapes, number of input names ({len(input_names)}) should be greater than or equal to the number of graph inputs(flat) ({len(flat_dynamic_shapes)})') from exception
    dynamic_axes: dict[str, list[int]] = {}
    for (input_name, axes) in zip(input_names, flat_dynamic_shapes):
        if axes is None:
            continue
        converted_axes: list[int] = []
        if isinstance(axes, dict):
            for (axis, dim) in axes.items():
                if dim is None:
                    continue
                converted_axes.append(axis)
            dynamic_axes[input_name] = converted_axes
        elif isinstance(axes, (list, tuple)):
            for (idx, dim) in enumerate(axes):
                if dim is None:
                    continue
                converted_axes.append(idx)
            dynamic_axes[input_name] = converted_axes
    return dynamic_axes

def to_json(path_or_buf: FilePath | WriteBuffer[str] | WriteBuffer[bytes] | None, obj: NDFrame, orient: str | None=None, date_format: str='epoch', double_precision: int=10, force_ascii: bool=True, date_unit: str='ms', default_handler: Callable[[Any], JSONSerializable] | None=None, lines: bool=False, compression: CompressionOptions='infer', index: bool | None=None, indent: int=0, storage_options: StorageOptions | None=None, mode: Literal['a', 'w']='w') -> str | None:
    if orient in ['records', 'values'] and index is True:
        raise ValueError("'index=True' is only valid when 'orient' is 'split', 'table', 'index', or 'columns'.")
    elif orient in ['index', 'columns'] and index is False:
        raise ValueError("'index=False' is only valid when 'orient' is 'split', 'table', 'records', or 'values'.")
    elif index is None:
        index = True
    if lines and orient != 'records':
        raise ValueError("'lines' keyword only valid when 'orient' is records")
    if mode not in ['a', 'w']:
        msg = f"mode={mode} is not a valid option.Only 'w' and 'a' are currently supported."
        raise ValueError(msg)
    if mode == 'a' and (not lines or orient != 'records'):
        msg = "mode='a' (append) is only supported when lines is True and orient is 'records'"
        raise ValueError(msg)
    if orient == 'table' and isinstance(obj, Series):
        obj = obj.to_frame(name=obj.name or 'values')
    writer: type[Writer]
    if orient == 'table' and isinstance(obj, DataFrame):
        writer = JSONTableWriter
    elif isinstance(obj, Series):
        writer = SeriesWriter
    elif isinstance(obj, DataFrame):
        writer = FrameWriter
    else:
        raise NotImplementedError("'obj' should be a Series or a DataFrame")
    s = writer(obj, orient=orient, date_format=date_format, double_precision=double_precision, ensure_ascii=force_ascii, date_unit=date_unit, default_handler=default_handler, index=index, indent=indent).write()
    if lines:
        s = convert_to_line_delimits(s)
    if <MASK>:
        with get_handle(path_or_buf, mode, compression=compression, storage_options=storage_options) as handles:
            handles.handle.write(s)
    else:
        return s
    return None

def __init__(self, initial_value, *args, dtype=None, **kwargs):
    """Overrides tf.Variable to fix VarHandleOp placements."""
    layout = kwargs.pop('layout', None)
    shape = kwargs.get('shape', None)
    if callable(initial_value):
        unwrapped = initial_value
        if issubclass(type(initial_value), functools.partial):
            unwrapped = initial_value.func
        if issubclass(type(unwrapped), trackable.CheckpointInitialValueCallable):
            if <MASK>:
                raise ValueError('Expected shape and layout to be not None.')
            initial_value = api.call_with_layout(initial_value, layout, shard_info=trackable.ShardInfo(shape=shape, offset=[0] * len(shape)))
        else:
            initial_value = initial_value()
    if isinstance(initial_value, trackable.CheckpointInitialValue):
        initial_value = initial_value.wrapped_value
    initial_value = ops.convert_to_tensor(initial_value, dtype=dtype)
    variable_device = initial_value.device
    self._save_as_bf16 = False
    with ops.device(variable_device):
        if context.executing_eagerly():
            if api.is_dtensor(initial_value):
                value_layout = api.fetch_layout(initial_value)
                if layout is not None and layout != value_layout:
                    raise errors_impl.InvalidArgumentError(None, None, f'Conflicting layout are provided for initial value layout ({value_layout}) and variable ({layout}).')
                layout = value_layout
            elif layout is not None:
                initial_value = api.relayout(initial_value, layout)
            else:
                raise errors_impl.InvalidArgumentError(None, None, 'Neither layout nor DTensor initial value are provided.')
            self.layout = layout
            with api.default_mesh(layout.mesh):
                super(DVariable, self).__init__(initial_value, *args, dtype=dtype, **kwargs)
        else:
            if layout is not None:
                initial_value = api.relayout(initial_value, layout)
            super(DVariable, self).__init__(initial_value, *args, dtype=dtype, **kwargs)

def get_version(self, *args, **kwds):
    version = FCompiler.get_version(self, *args, **kwds)
    if version is None and sys.platform.startswith('aix'):
        lslpp = find_executable('lslpp')
        xlf = find_executable('xlf')
        if os.path.exists(xlf) and os.path.exists(lslpp):
            try:
                o = subprocess.check_output([lslpp, '-Lc', 'xlfcmp'])
            except (OSError, subprocess.CalledProcessError):
                pass
            else:
                m = re.search('xlfcmp:(?P<version>\\d+([.]\\d+)+)', o)
                if m:
                    version = m.group('version')
    xlf_dir = '/etc/opt/ibmcmp/xlf'
    if <MASK>:
        l = sorted(os.listdir(xlf_dir))
        l.reverse()
        l = [d for d in l if os.path.isfile(os.path.join(xlf_dir, d, 'xlf.cfg'))]
        if l:
            from distutils.version import LooseVersion
            self.version = version = LooseVersion(l[0])
    return version

def __init__(self, in_channels, out_channels, kernel_size, stride, padding, dilation, transposed, output_padding, groups, bias, padding_mode, eps=1e-05, momentum=0.1, freeze_bn=False, qconfig=None, dim=2):
    nn.modules.conv._ConvNd.__init__(self, in_channels, out_channels, kernel_size, stride, padding, dilation, transposed, output_padding, groups, False, padding_mode)
    assert qconfig, 'qconfig must be provided for QAT module'
    self.qconfig = qconfig
    self.freeze_bn = freeze_bn if self.training else True
    self.bn = _BN_CLASS_MAP[dim](out_channels, eps, momentum, True, True)
    self.weight_fake_quant = self.qconfig.weight()
    if bias:
        self.bias = Parameter(torch.empty(out_channels))
    else:
        self.register_parameter('bias', None)
    self.reset_bn_parameters()
    if self.training:
        if <MASK>:
            self.freeze_bn_stats()
        else:
            self.update_bn_stats()
    else:
        self.freeze_bn_stats()
    self._enable_slow_path_for_better_numerical_stability = False

def _call_overload_packet_from_python(op: OpOverloadPacket[_P, _T], *args: _P.args, **kwargs: _P.kwargs) -> _T:
    (torch_function_called, ret) = torch._C._maybe_call_torch_function_for_op_packet(op, *args, **kwargs)
    if torch_function_called:
        return ret
    exceptions = {}
    found_op = None
    for overload_name in op.overloads():
        op_overload = getattr(op, overload_name)
        try:
            _ = torch._C._check_schema_allow_fake_script_object(op_overload._schema, *args, **kwargs)
            found_op = op_overload
            break
        except RuntimeError as e:
            exceptions[overload_name] = e
    if <MASK>:
        return found_op(*args, **kwargs)
    err_msg = f'Fail to match any TorchBindOverload of {op} with following exceptions:\n'
    for (key, msg) in exceptions.items():
        err_msg += f'Overload name {key}:\n {msg}\n'
    raise RuntimeError(err_msg)

@classmethod
def _from_sequence_of_strings(cls, strings, *, dtype: ExtensionDtype, copy: bool=False) -> Self:
    """
        Construct a new ExtensionArray from a sequence of strings.
        """
    mask = isna(strings)
    if <MASK>:
        strings = strings._pa_array
    pa_type = to_pyarrow_type(dtype)
    if pa_type is None or pa.types.is_binary(pa_type) or pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type):
        scalars = strings
    elif pa.types.is_timestamp(pa_type):
        from pandas.core.tools.datetimes import to_datetime
        scalars = to_datetime(strings, errors='raise')
    elif pa.types.is_date(pa_type):
        from pandas.core.tools.datetimes import to_datetime
        scalars = to_datetime(strings, errors='raise').date
        scalars = pa.array(scalars, type=pa_type, mask=mask)
    elif pa.types.is_duration(pa_type):
        from pandas.core.tools.timedeltas import to_timedelta
        scalars = to_timedelta(strings, errors='raise')
        if pa_type.unit != 'ns':
            mask = isna(scalars)
            if not isinstance(strings, (pa.Array, pa.ChunkedArray)):
                strings = pa.array(strings, type=pa.string(), mask=mask)
            strings = pc.if_else(mask, None, strings)
            try:
                scalars = strings.cast(pa.int64())
            except pa.ArrowInvalid:
                pass
    elif pa.types.is_time(pa_type):
        from pandas.core.tools.times import to_time
        scalars = to_time(strings, errors='coerce')
    elif pa.types.is_boolean(pa_type):
        if isinstance(strings, (pa.Array, pa.ChunkedArray)):
            scalars = strings
        else:
            scalars = pa.array(strings, type=pa.string(), mask=mask)
        scalars = pc.if_else(pc.equal(scalars, '1.0'), '1', scalars)
        scalars = pc.if_else(pc.equal(scalars, '0.0'), '0', scalars)
        scalars = scalars.cast(pa.bool_())
    elif pa.types.is_integer(pa_type) or pa.types.is_floating(pa_type) or pa.types.is_decimal(pa_type):
        from pandas.core.tools.numeric import to_numeric
        scalars = to_numeric(strings, errors='raise')
        if isinstance(strings, (pa.Array, pa.ChunkedArray)):
            scalars = strings.cast(pa_type)
        elif mask is not None:
            scalars = pa.array(scalars, mask=mask, type=pa_type)
    else:
        raise NotImplementedError(f'Converting strings to {pa_type} is not implemented.')
    return cls._from_sequence(scalars, dtype=pa_type, copy=copy)

@executorch_call_delegate.py_autograd_impl
def call_delegate_autograd(lowered_module, *args):
    (flat_operands, _) = tree_flatten([lowered_module, *args])
    requires_grad = any((f.requires_grad for f in flat_operands if isinstance(f, torch.Tensor)))
    with torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.AutogradCPU)):
        res = executorch_call_delegate(lowered_module, *args)
        if requires_grad:

            def fake_requires_grad(var):
                if var is not None:
                    var = var.detach()
                    if <MASK>:
                        var.requires_grad = True
                return var
            return pytree.tree_map_only(torch.Tensor, fake_requires_grad, res)
        return res

def scale(self, outputs: Union[torch.Tensor, Iterable[torch.Tensor]]) -> Union[torch.Tensor, Iterable[torch.Tensor]]:
    if not self._enabled:
        return outputs
    if isinstance(outputs, torch.Tensor):
        if <MASK>:
            raise AssertionError(f'Expected supported device, got {outputs.device}')
        if self._scale is None:
            self._lazy_init_scale_growth_tracker(outputs.device)
        if self._scale is None:
            raise AssertionError('Expected _scale to be initialized, got None')
        scaled_output = outputs * self._scale.to(device=outputs.device, non_blocking=True)
        return scaled_output.type(outputs.dtype)
    stash: list[_GeneralMultiDeviceReplicator] = []

    def apply_scale(val: Union[torch.Tensor, Iterable[torch.Tensor]]):
        if isinstance(val, torch.Tensor):
            if not _is_supported_device(val):
                raise AssertionError(f'Expected supported device, got {val.device}')
            if len(stash) == 0:
                if self._scale is None:
                    self._lazy_init_scale_growth_tracker(val.device)
                if self._scale is None:
                    raise AssertionError('Expected _scale to be initialized, got None')
                stash.append(_GeneralMultiDeviceReplicator(self._scale))
            scaled_val = val * stash[0].get(val.device)
            return scaled_val.type(val.dtype)
        if isinstance(val, abc.Iterable):
            iterator = map(apply_scale, val)
            if isinstance(val, (list, tuple)):
                return type(val)(iterator)
            return iterator
        raise ValueError('outputs must be a Tensor or an iterable of Tensors')
    return apply_scale(outputs)

def rendezvous_barrier(self):
    """
        Main entry point for next rendezvous.

        This method is blocking until rendezvous succeeds or a timeout occurs.

        Returns:
             ``(rdzv_version, rank, world_size)``

        Raises:
            RendezvousTimeoutError - timeout waiting for rendezvous
            RendezvousClosedError - rendezvous is or was closed while waiting
            RendezvousError - other persistent errors that
             render the rendezvous non-retryable
        """
    self._rendezvous_deadline = time.time() + self._timeout
    while True:
        if time.time() > self._rendezvous_deadline:
            raise RendezvousTimeoutError
        logger.info('Attempting to join next rendezvous')
        try:
            if <MASK>:
                self._lease_this_rank_stop.set()
            return self.init_phase()
        except EtcdRendezvousRetryImmediately:
            pass
        except EtcdRendezvousRetryableFailure:
            time.sleep(1)
        except RendezvousTimeoutError:
            logger.info('Rendezvous timeout occurred in EtcdRendezvousHandler')
            raise
        except RendezvousClosedError:
            logger.info('Rendezvous for run_id=%s was observed to be closed', self._run_id)
            raise
        except RendezvousError:
            raise
        except Exception as e:
            logger.info('Rendezvous attempt failed, will retry. Reason: %s', e)
            time.sleep(1)

def __new__(subtype, shape, dtype=None, buf=None, offset=0, strides=None, formats=None, names=None, titles=None, byteorder=None, aligned=False, order='C'):
