    else:
        self = ndarray.__new__(subtype, shape, (record, descr), buffer=buf, offset=offset, strides=strides, order=order)
    return self

def _get_subgraph_relationship_type(subgraph_a: NSSubgraph, subgraph_b: NSSubgraph, gm_a: GraphModule, gm_b: GraphModule, type_a_related_to_b: set[tuple[NSNodeTargetType, NSNodeTargetType]]) -> SubgraphTypeRelationship:
    node_a = subgraph_a.base_op_node
    node_b = subgraph_b.base_op_node
    if node_a.op != node_b.op:
        if not (node_a.op in ('call_function', 'call_method') and node_b.op in ('call_function', 'call_method')):
            return SubgraphTypeRelationship.NOT_RELATED
    if node_a.op in ('call_function', 'call_method'):
        key = (node_a.target, node_b.target)
        if <MASK>:
            if node_a.target == node_b.target:
                return SubgraphTypeRelationship.EQUAL_BUT_UKNOWN
            else:
                return SubgraphTypeRelationship.NOT_RELATED
        if node_a.target == node_b.target:
            node_a_has_prev = subgraph_a.base_op_node == subgraph_a.start_node
            node_b_has_prev = subgraph_b.base_op_node == subgraph_b.start_node
            if node_a_has_prev and (not node_b_has_prev):
                return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
            elif not node_a_has_prev and node_b_has_prev:
                return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
            elif not node_a_has_prev and (not node_b_has_prev):
                return SubgraphTypeRelationship.EQUAL
            else:
                return SubgraphTypeRelationship.EQUAL
        if key in type_a_related_to_b:
            return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
        else:
            return SubgraphTypeRelationship.NOT_RELATED
    elif node_a.op == 'call_module':
        if subgraph_a.base_op_node != subgraph_a.start_node or subgraph_b.base_op_node != subgraph_b.start_node:
            raise AssertionError('Matching call_module patterns where base_op_node != start_node is not supported yet')
        if not isinstance(node_a.target, str):
            raise AssertionError(f'Expected str, got {type(node_a.target)}')
        mod_a = getattr_from_fqn(gm_a, node_a.target)
        if not isinstance(node_b.target, str):
            raise AssertionError(f'Expected str, got {type(node_b.target)}')
        mod_b = getattr_from_fqn(gm_b, node_b.target)
        key = (type(mod_a), type(mod_b))
        if key not in type_a_related_to_b:
            if type(mod_a) is type(mod_b):
                return SubgraphTypeRelationship.EQUAL_BUT_UKNOWN
            else:
                return SubgraphTypeRelationship.NOT_RELATED
        elif type(mod_a) is type(mod_b):
            return SubgraphTypeRelationship.EQUAL
        else:
            return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
    return SubgraphTypeRelationship.NOT_RELATED

def finalize_outputs(self):
    self.created_modules.pop(self.fqn, None)
    orig_outputs = []
    signature = self.module_call_graph.get(self.child_fqn)
    if signature is not None and self.parent is not None:
        for output in signature.outputs:
            if <MASK>:
                if output.name in self.seen_nodes:
                    orig_outputs.append(self.seen_nodes[output.name])
                else:
                    orig_outputs.append(None)
            else:
                raise RuntimeError(f'Unsupported data type for output node: {output}')

        def get_actual_output_node(output):
            if output is None:
                return None
            seen_node = self.seen_nodes[output.name]
            if seen_node in self.node_map:
                return self.node_map[seen_node]
            elif seen_node in self.node_to_placeholder:
                return self.node_to_placeholder[seen_node]
            else:
                raise RuntimeError(f'Could not find output node {output}. Graph: {self.graph}')
        tree_out_node = _generate_unflatten(self.module, tuple((get_actual_output_node(output) for output in orig_outputs)), signature.out_spec)
        parent_out: Optional[torch.fx.Node] = _generate_flatten_spec(self.parent.module, self.parent_call_module, signature.out_spec)
        graph_outputs: Union[torch.fx.Node, list[torch.fx.Node]] = tree_out_node
    else:
        graph_outputs = []
        for orig_node in self.node_map.keys():
            for user_node in orig_node.users:
                if user_node.name not in self.seen_nodes:
                    orig_outputs.append(orig_node)
                    graph_outputs.append(self.node_map[orig_node])
                    break
        parent_out = self.parent_call_module
        if len(graph_outputs) == 1:
            graph_outputs = graph_outputs[0]
    assert isinstance(graph_outputs, (list, torch.fx.Node))
    self.graph.output(graph_outputs)
    if parent_out is None:
        return
    parent_out.meta['val'] = graph_outputs.meta.get('val') if isinstance(graph_outputs, torch.fx.Node) else [o.meta.get('val') for o in graph_outputs]
    if len(orig_outputs) == 1 and signature is None:
        self.parent.node_map[orig_outputs[0]] = parent_out
    else:
        for (i, orig_output) in enumerate(orig_outputs):
            if orig_output is None:
                continue
            proxy_out = torch.fx.Proxy(parent_out)[i].node
            proxy_out.meta['val'] = orig_output.meta.get('val')
            self.parent.node_map[orig_output] = proxy_out

