@classmethod
def load_async(cls, main_code: str, device_type: str='cpu', submit_fn: Any=None, extra_flags: Sequence[str]=(), optimized_code: str | None=None) -> Any:
    """Compile and load a C++ library.  Returns a callable that returns the loaded
        library."""
    compile_command = {**cls.cpp_compile_command_flags, 'device_type': device_type, 'extra_flags': extra_flags, 'use_relative_path': config.is_fbcode(), 'vec_isa': pick_vec_isa()}
    _set_gpu_runtime_env()
    main_build_option = CppTorchDeviceOptions(compile_only=bool(optimized_code), min_optimize=optimized_code is not None, **compile_command)
    optimized_build_option = CppTorchDeviceOptions(compile_only=True, **compile_command)

    def get_hashable_command_line(build_option: BuildOptionsBase) -> str:
        """Writing the code to file will calculate a hash, which we need to vary if
            the command line flags change.  This implements a mostly-generic way of
            validating that."""
        return CppBuilder(name='o', sources='i', BuildOption=build_option).get_command_line()
    main_cmd_line = get_hashable_command_line(main_build_option)
    optimized_cmd_line = get_hashable_command_line(optimized_build_option)
    (key, main_path) = write(main_code, 'main.cpp', extra=f'{optimized_code} {main_cmd_line}')
    if optimized_code:
        (_, optimized_path) = write(optimized_code, 'optimized.cpp', extra=optimized_cmd_line)
    else:
        optimized_path = os.devnull
    if key not in cls.cache:
        from torch.utils._filelock import FileLock
        lock_path = os.path.join(get_lock_dir(), key + '.lock')
        future: Future[Any] | None = None
        lib = None
        if config.cpp_cache_precompile_headers and (not _IS_WINDOWS):
            if (header := cls._get_uncompiled_header(device_type)):
                main_build_option.precompiled_header = _precompile_header(header, main_cmd_line, min_optimize=optimized_code is not None, **compile_command)
            if optimized_code and (header := _get_cpp_prefix_header(device_type)):
                optimized_build_option.precompiled_header = _precompile_header(header, optimized_cmd_line, **compile_command)
        (main_name, output_dir) = get_name_and_dir_from_output_file_path(main_path)
        main_builder = CppBuilder(name=main_name, sources=main_path, BuildOption=main_build_option, output_dir=output_dir)
        if optimized_code:
            (optimized_name, _) = get_name_and_dir_from_output_file_path(optimized_path)
            optimized_builder = CppBuilder(name=optimized_name, sources=optimized_path, BuildOption=optimized_build_option, output_dir=output_dir)
            linker = CppBuilder(name=main_name, sources=[main_builder.get_target_file_path(), optimized_builder.get_target_file_path()], BuildOption=CppTorchDeviceOptions(**compile_command), output_dir=output_dir)
            worker_fn = functools.partial(_worker_compile_cpp, lock_path, (main_builder, optimized_builder, linker))
            binary_path = normalize_path_separator(linker.get_target_file_path())
        else:
            worker_fn = functools.partial(_worker_compile_cpp, lock_path, (main_builder,))
            binary_path = normalize_path_separator(main_builder.get_target_file_path())

        def load_fn() -> Any:
            nonlocal lib
            if lib is None:
                if future is not None:
                    future.result()
                result = worker_fn()
                assert result is None
                lib = cls._load_library(binary_path, key)
                assert lib is not None
            return lib
        if <MASK>:
            with FileLock(lock_path, timeout=LOCK_TIMEOUT):
                if not os.path.exists(binary_path):
                    future = submit_fn(worker_fn)
        cls.cache[key] = load_fn
    return cls.cache[key]

def generate_rand_batch(batch_size, max_sequence_len, embed_dimension, pad_percentage=None, dtype=torch.float16, device='cuda'):
    if <MASK>:
        return (torch.randn(batch_size, max_sequence_len, embed_dimension, dtype=dtype, device=device), None)
    seq_len_list = [int(max_sequence_len * (1 - random.gauss(pad_percentage, 0.01))) for _ in range(batch_size)]
    seq_len_list[random.randint(0, batch_size - 1)] = max_sequence_len
    return (torch.nested.nested_tensor([torch.randn(seq_len, embed_dimension, dtype=dtype, device=device) for seq_len in seq_len_list]), seq_len_list)

def validate_sample_input_sparse(op_info, sample, check_validate=False):
    """Return the specified sample when it is valid and supported by the
    operation. Otherwise, return the sample as ErrorInput instance.

    When check_validate is True, the result is validated against
    calling the op on the sample.
    """
    if isinstance(op_info, ReductionOpInfo):
        return _validate_sample_input_sparse_reduction(op_info, sample, check_validate=check_validate)
    elif <MASK>:
        return _validate_sample_input_sparse_elementwise_binary_operation(op_info, sample, check_validate=check_validate)
    else:
        return _validate_sample_input_sparse_default(op_info, sample, check_validate=check_validate)

def pin_memory(data, device=None):
    if isinstance(data, torch.Tensor):
        return data.pin_memory(device)
    elif isinstance(data, (str, bytes)):
        return data
    elif isinstance(data, collections.abc.Mapping):
        try:
            if <MASK>:
                clone = copy.copy(data)
                clone.update({k: pin_memory(sample, device) for (k, sample) in data.items()})
                return clone
            else:
                return type(data)({k: pin_memory(sample, device) for (k, sample) in data.items()})
        except TypeError:
            return {k: pin_memory(sample, device) for (k, sample) in data.items()}
    elif isinstance(data, tuple) and hasattr(data, '_fields'):
        return type(data)(*(pin_memory(sample, device) for sample in data))
    elif isinstance(data, tuple):
        return [pin_memory(sample, device) for sample in data]
    elif isinstance(data, collections.abc.Sequence):
        try:
            if isinstance(data, collections.abc.MutableSequence):
                clone = copy.copy(data)
                for (i, item) in enumerate(data):
                    clone[i] = pin_memory(item, device)
                return clone
            return type(data)([pin_memory(sample, device) for sample in data])
        except TypeError:
            return [pin_memory(sample, device) for sample in data]
    elif hasattr(data, 'pin_memory'):
        return data.pin_memory()
    else:
        return data

def _find_all_reduce_mesh_dim(placements: tuple[Placement, ...], dim: int) -> int:
    if <MASK>:
        raise ValueError('Currently loss_parallel() only supports input on one-dimensional DeviceMesh.')
    if not placements[0].is_shard(dim):
        raise ValueError(f'loss_parallel() should be enabled only when the input tensor is sharded on dimension {dim}.')
    return 0

def _convert_listlike_datetimes(arg, format: str | None, name: Hashable | None=None, utc: bool=False, unit: str | None=None, errors: DateTimeErrorChoices='raise', dayfirst: bool | None=None, yearfirst: bool | None=None, exact: bool=True):
    """
    Helper function for to_datetime. Performs the conversions of 1D listlike
    of dates

    Parameters
    ----------
    arg : list, tuple, ndarray, Series, Index
        date to be parsed
    name : object
        None or string for the Index name
    utc : bool
        Whether to convert/localize timestamps to UTC.
    unit : str
        None or string of the frequency of the passed data
    errors : str
        error handing behaviors from to_datetime, 'raise', 'coerce'
    dayfirst : bool
        dayfirst parsing behavior from to_datetime
    yearfirst : bool
        yearfirst parsing behavior from to_datetime
    exact : bool, default True
        exact format matching behavior from to_datetime

    Returns
    -------
    Index-like of parsed dates
    """
    if isinstance(arg, (list, tuple)):
        arg = np.array(arg, dtype='O')
    elif isinstance(arg, NumpyExtensionArray):
        arg = np.array(arg)
    arg_dtype = getattr(arg, 'dtype', None)
    tz = 'utc' if utc else None
    if isinstance(arg_dtype, DatetimeTZDtype):
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        if utc:
            arg = arg.tz_convert(None).tz_localize('utc')
        return arg
    elif isinstance(arg_dtype, ArrowDtype) and arg_dtype.type is Timestamp:
        if utc:
            if isinstance(arg, Index):
                arg_array = cast(ArrowExtensionArray, arg.array)
                if arg_dtype.pyarrow_dtype.tz is not None:
                    arg_array = arg_array._dt_tz_convert('UTC')
                else:
                    arg_array = arg_array._dt_tz_localize('UTC')
                arg = Index(arg_array)
            elif arg_dtype.pyarrow_dtype.tz is not None:
                arg = arg._dt_tz_convert('UTC')
            else:
                arg = arg._dt_tz_localize('UTC')
        return arg
    elif lib.is_np_dtype(arg_dtype, 'M'):
        if not is_supported_dtype(arg_dtype):
            arg = astype_overflowsafe(np.asarray(arg), np.dtype('M8[s]'), is_coerce=errors == 'coerce')
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        elif utc:
            return arg.tz_localize('utc')
        return arg
    elif <MASK>:
        if format is not None:
            raise ValueError('cannot specify both format and unit')
        return _to_datetime_with_unit(arg, unit, name, utc, errors)
    elif getattr(arg, 'ndim', 1) > 1:
        raise TypeError('arg must be a string, datetime, list, tuple, 1-d array, or Series')
    try:
        (arg, _) = maybe_convert_dtype(arg, copy=False, tz=libtimezones.maybe_get_tz(tz))
    except TypeError:
        if errors == 'coerce':
            npvalues = np.full(len(arg), np.datetime64('NaT', 'ns'))
            return DatetimeIndex(npvalues, name=name)
        raise
    arg = ensure_object(arg)
    if format is None:
        format = _guess_datetime_format_for_array(arg, dayfirst=dayfirst)
    if format is not None and format != 'mixed':
        return _array_strptime_with_fallback(arg, name, utc, format, exact, errors)
    (result, tz_parsed) = objects_to_datetime64(arg, dayfirst=dayfirst, yearfirst=yearfirst, utc=utc, errors=errors, allow_object=True)
    if tz_parsed is not None:
        out_unit = np.datetime_data(result.dtype)[0]
        dtype = tz_to_dtype(tz_parsed, out_unit)
        dt64_values = result.view(f'M8[{dtype.unit}]')
        dta = DatetimeArray._simple_new(dt64_values, dtype=dtype)
        return DatetimeIndex._simple_new(dta, name=name)
    return _box_as_indexlike(result, utc=utc, name=name)

def SortEigenDecomposition(e, v):
    if <MASK>:
        return (e, v)
    perm = np.argsort(e.real + e.imag, -1)
    return (np.take(e, perm, -1), np.take(v, perm, -1))

def _ComputeReferenceDilatedConvParameters(self, tensor_in_sizes, filter_in_sizes, stride, dilation, padding, data_format, use_gpu, op_name):
    x1 = self._CreateNumpyTensor(tensor_in_sizes)
    x2 = self._CreateNumpyTensor(filter_in_sizes)
    with test_util.device(use_gpu):
        t1 = constant_op.constant(x1, shape=tensor_in_sizes)
        t2 = constant_op.constant(x2, shape=filter_in_sizes)
        if <MASK>:
            strides = list(stride)
        else:
            strides = [stride, stride]
        if data_format == 'NCHW':
            t1 = test_util.NHWCToNCHW(t1)
            full_strides = [1, 1] + strides
            full_dilation = [1, 1] + dilation
        else:
            full_strides = [1] + strides + [1]
            full_dilation = [1] + dilation + [1]
        expected = nn_ops.convolution(t1, t2, padding=padding, strides=strides, dilation_rate=dilation, data_format=data_format)
        if op_name == 'Conv2D':
            computed = nn_ops.conv2d(t1, t2, strides=full_strides, dilations=full_dilation, padding=padding, data_format=data_format)
        elif op_name == 'Conv':
            conv_format = 'CHANNELS_LAST' if data_format == 'NHWC' else 'CHANNELS_FIRST'
            (conv_padding, explicit_paddings) = nn_ops.convert_padding(padding)
            computed = gen_nn_ops.conv(t1, t2, strides=full_strides, dilations=full_dilation, padding=conv_padding, explicit_paddings=explicit_paddings, data_format=conv_format)
        else:
            raise ValueError('Invalid op name: %s' % op_name)
        if data_format == 'NCHW':
            expected = test_util.NCHWToNHWC(expected)
            computed = test_util.NCHWToNHWC(computed)
    return (expected, computed)

def _validate_indices_list(indices_list, formatted):
    prev_ind = None
    for ind in indices_list:
        dims = formatted.annotations['tensor_metadata']['shape']
        if <MASK>:
            raise ValueError('Dimensions mismatch: requested: %d; actual: %d' % (len(ind), len(dims)))
        for (req_idx, siz) in zip(ind, dims):
            if req_idx >= siz:
                raise ValueError('Indices exceed tensor dimensions.')
            if req_idx < 0:
                raise ValueError('Indices contain negative value(s).')
        if prev_ind and ind < prev_ind:
            raise ValueError('Input indices sets are not in ascending order.')
        prev_ind = ind

def _flip(image, flip_index, scope_name):
    """Flip an image either horizontally or vertically.

  Outputs the contents of `image` flipped along the dimension `flip_index`.

  See also `reverse()`.

  Args:
    image: 4-D Tensor of shape `[batch, height, width, channels]` or 3-D Tensor
      of shape `[height, width, channels]`.
    flip_index: 0 For vertical, 1 for horizontal.
    scope_name: string, scope name.

  Returns:
    A `Tensor` of the same type and shape as `image`.

  Raises:
    ValueError: if the shape of `image` not supported.
  """
    with ops.name_scope(None, scope_name, [image]):
        image = ops.convert_to_tensor(image, name='image')
        image = _AssertAtLeast3DImage(image)
        shape = image.get_shape()

        def f_rank3():
            return fix_image_flip_shape(image, array_ops.reverse(image, [flip_index]))

        def f_rank4():
            return array_ops.reverse(image, [flip_index + 1])
        if shape.ndims is None:
            rank = array_ops.rank(image)
            return tf_cond.cond(math_ops.equal(rank, 3), f_rank3, f_rank4)
        elif shape.ndims == 3:
            return f_rank3()
        elif <MASK>:
            return f_rank4()
        else:
            raise ValueError("'image' (shape %s)must have either 3 or 4 dimensions." % shape)

def _poll_termination_signal(self):
    """Poll maintenance notice and notify peers if receiving one."""
    while True:
        if self._poll_termination_signal_thread_should_stop.is_set() or self._final_checkpoint_countdown:
            return
        if <MASK>:
            break
        time.sleep(1)
    self._maybe_set_received_own_sigterm()

def get_flaky_jobs(self) -> list[Any]:
    unique_failures = self.get_unique_failures(self.filtered_statuses)
    flaky_jobs = []
    for failure in unique_failures:
        failure_list = unique_failures[failure]
        if <MASK>:
            flaky_jobs.append(failure_list[0])
    return flaky_jobs

def _allocate_parameter_mem(self, n_classes, n_features, input_dtype, coef_init=None, intercept_init=None, one_class=0):
    """Allocate mem for parameters; initialize if provided."""
    if n_classes > 2:
        if coef_init is not None:
            coef_init = np.asarray(coef_init, dtype=input_dtype, order='C')
            if <MASK>:
                raise ValueError('Provided ``coef_`` does not match dataset. ')
            self.coef_ = coef_init
        else:
            self.coef_ = np.zeros((n_classes, n_features), dtype=input_dtype, order='C')
        if intercept_init is not None:
            intercept_init = np.asarray(intercept_init, order='C', dtype=input_dtype)
            if intercept_init.shape != (n_classes,):
                raise ValueError('Provided intercept_init does not match dataset.')
            self.intercept_ = intercept_init
        else:
            self.intercept_ = np.zeros(n_classes, dtype=input_dtype, order='C')
    else:
        if coef_init is not None:
            coef_init = np.asarray(coef_init, dtype=input_dtype, order='C')
            coef_init = coef_init.ravel()
            if coef_init.shape != (n_features,):
                raise ValueError('Provided coef_init does not match dataset.')
            self.coef_ = coef_init
        else:
            self.coef_ = np.zeros(n_features, dtype=input_dtype, order='C')
        if intercept_init is not None:
            intercept_init = np.asarray(intercept_init, dtype=input_dtype)
            if intercept_init.shape != (1,) and intercept_init.shape != ():
                raise ValueError('Provided intercept_init does not match dataset.')
            if one_class:
                self.offset_ = intercept_init.reshape(1)
            else:
                self.intercept_ = intercept_init.reshape(1)
        elif one_class:
            self.offset_ = np.zeros(1, dtype=input_dtype, order='C')
        else:
            self.intercept_ = np.zeros(1, dtype=input_dtype, order='C')
    if self.average > 0:
        self._standard_coef = self.coef_
        self._average_coef = np.zeros(self.coef_.shape, dtype=input_dtype, order='C')
        if one_class:
            self._standard_intercept = 1 - self.offset_
        else:
            self._standard_intercept = self.intercept_
        self._average_intercept = np.zeros(self._standard_intercept.shape, dtype=input_dtype, order='C')

def _assert_scalar(value, name):
    """Asserts that `value` is scalar, and returns `value`."""
    value_rank = value.shape.rank
    if value_rank is None:
        check = control_flow_assert.Assert(math_ops.equal(array_ops.rank(value), 0), ['Input %s must be a scalar' % name], name='%sIsScalar' % name.capitalize())
        result = control_flow_ops.with_dependencies([check], value, name='%sDependencies' % name)
        result.set_shape([])
        return result
    elif <MASK>:
        return value
    else:
        raise ValueError('Input %s must be a scalar' % name)

