def var_getattr(self, tx: 'InstructionTranslator', name):
    source = self.source and AttrSource(self.source, name)
    base = tx.output.get_submodule(self.module_key)
    base_dict = object.__getattribute__(base, '__dict__')
    object_member = True
    all_class_attribute_names = set()
    for x in inspect.getmro(base.__class__):
        all_class_attribute_names.update(x.__dict__.keys())
    if not self.source:
        unimplemented_v2(gb_type='getattr with no source', context=f'var_getattr {self} {name}', explanation='Dynamo does not know how to access an attribute on an `nn.Module` instance that lacks a source. This is usually an internal error in Dynamo.', hints=[*graph_break_hints.DYNAMO_BUG])
    if name == '__dict__':
        return variables.GetAttrVariable(self, name, source=source)
    if name in base_dict:
        subobj = base_dict[name]
    elif '_modules' in base_dict and name in base_dict['_modules'] and (name not in all_class_attribute_names):
        subobj = base_dict['_modules'][name]
    elif '_parameters' in base_dict and name in base_dict['_parameters']:
        subobj = base_dict['_parameters'][name]
    elif '_buffers' in base_dict and name in base_dict['_buffers']:
        subobj = base_dict['_buffers'][name]
    else:
        try:
            subobj = inspect.getattr_static(base, name)
            object_member = False
        except AttributeError:
            result = self._custom_getattr_fallback(base=base, tx=tx, name=name, obj_source=self.source)
            if result is not None:
                return result
            raise_observed_exception(AttributeError, tx, msg=f"'{type(base).__name__}' object has no attribute '{name}'")
    if name == 'forward':
        guard_to_detect_forward_monkeypatching(self.source, base)
    if name == '__class__' and (not object_member):
        return variables.UserDefinedClassVariable(base.__class__, source=source)
    if object_member:
        out = VariableTracker.build(tx, subobj, NNModuleSource(source))
        if isinstance(out, (NNModuleVariable, UnspecializedNNModuleVariable)):
            out.set_nn_module_stack_source(AttrSource(self.get_nn_module_stack_source(), name))
        return out
    elif istype(subobj, property):
        if <MASK>:
            source = AttrSource(AttrSource(self.source, '__class__'), name)
            source = AttrSource(source, 'fget')
        return variables.UserFunctionVariable(subobj.fget, source=source).call_function(tx, [self], {})
    elif istype(subobj, classmethod):
        return variables.UserMethodVariable(subobj.__func__, variables.UserDefinedObjectVariable(type(base)), source=source)
    elif istype(subobj, staticmethod):
        return variables.UserFunctionVariable(subobj.__get__(base), source=source)
    elif istype(subobj, types.FunctionType):
        return variables.UserMethodVariable(subobj, self, source=source)
    elif is_safe_constant(subobj) or istensor(subobj):
        return VariableTracker.build(tx, subobj, NNModuleSource(source))
    else:
        unimplemented_v2(gb_type='Unsupported nn.Module attribute type', context=f'nn.Module subclass: {typestr(base)}, name: {name}, attribute type: {typestr(subobj)}', explanation=f'Dynamo does not support tracing nn.Module attributes of type `{typestr(subobj)}`', hints=[f'Refactor your code so that `{name}` (type `{typestr(subobj)}`) is not an attribute of `{typestr(base)}`', 'Currently supported attribute types are methods, classmethods, staticmethods, properties, constants, and tensors.', *graph_break_hints.SUPPORTABLE])
    return variables.GetAttrVariable(self, name, source=source)

def get_default_qat_qconfig(backend='x86', version=1):
    """
    Returns the default QAT qconfig for the specified backend.

    Args:
      * `backend` (str): a string representing the target backend. Currently supports
        `x86` (default), `fbgemm`, `qnnpack` and `onednn`.
      * `version`: version, for backwards compatibility. Can be `None` or `1`.

    Return:
        qconfig
    """
    supported_backends = ['fbgemm', 'x86', 'qnnpack', 'onednn']
    if backend not in supported_backends:
        raise AssertionError('backend: ' + str(backend) + f' not supported. backend must be one of {supported_backends}')
    if <MASK>:
        if backend == 'fbgemm':
            qconfig = QConfig(activation=FakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255, reduce_range=True), weight=default_per_channel_weight_fake_quant)
        elif backend == 'qnnpack':
            qconfig = QConfig(activation=FakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255, reduce_range=False), weight=default_weight_fake_quant)
        elif backend == 'onednn':
            qconfig = QConfig(activation=FakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255), weight=default_per_channel_weight_fake_quant)
        elif backend == 'x86':
            qconfig = QConfig(activation=FakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255, reduce_range=True), weight=default_per_channel_weight_fake_quant)
        else:
            qconfig = default_qat_qconfig
    elif version == 1:
        if backend == 'fbgemm':
            qconfig = QConfig(activation=FusedMovingAvgObsFakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255, reduce_range=True), weight=default_fused_per_channel_wt_fake_quant)
        elif backend == 'qnnpack':
            qconfig = QConfig(activation=FusedMovingAvgObsFakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255, reduce_range=False), weight=default_fused_wt_fake_quant)
        elif backend == 'onednn':
            qconfig = QConfig(activation=FusedMovingAvgObsFakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255), weight=default_fused_per_channel_wt_fake_quant)
        elif backend == 'x86':
            qconfig = QConfig(activation=FusedMovingAvgObsFakeQuantize.with_args(observer=MovingAverageMinMaxObserver, quant_min=0, quant_max=255, reduce_range=True), weight=default_fused_per_channel_wt_fake_quant)
        else:
            qconfig = default_qat_qconfig_v2
    else:
        raise AssertionError('Version number: ' + str(version) + 'in get_default_qat_qconfig is not supported. Version number must be 0 or 1')
    return qconfig

