def inner(fn: Callable[..., object]) -> CustomOpDef:
    import torch
    if schema is None:
        schema_str = torch.library.infer_schema(fn, mutates_args=mutates_args)
    else:
        schema_str = schema
    (namespace, opname) = name.split('::')
    result = CustomOpDef(namespace, opname, schema_str, fn, tags)
    if schema is not None:
        expected = set()
        for arg in result._opoverload._schema.arguments:
            if arg.alias_info is not None and arg.alias_info.is_write:
                expected.add(arg.name)
        if <MASK>:
            raise ValueError(f'Attempted to create a custom op with `mutates_args={mutates_args}` and `schema={schema}. The schema suggests that the op mutates {expected}which is different from what was provided to us in `mutates_args`. Please make these consistent.')
    result.register_kernel(device_types)(fn)
    return result

