def __init__(self, *, name, expressions, index_type=None, condition=None, deferrable=None, include=None, violation_error_code=None, violation_error_message=None):
    if index_type and index_type.lower() not in {'gist', 'spgist'}:
        raise ValueError('Exclusion constraints only support GiST or SP-GiST indexes.')
    if not expressions:
        raise ValueError('At least one expression is required to define an exclusion constraint.')
    if not all((isinstance(expr, (list, tuple)) and len(expr) == 2 for expr in expressions)):
        raise ValueError('The expressions must be a list of 2-tuples.')
    if not isinstance(condition, (NoneType, Q)):
        raise ValueError('ExclusionConstraint.condition must be a Q instance.')
    if <MASK>:
        raise ValueError('ExclusionConstraint.deferrable must be a Deferrable instance.')
    if not isinstance(include, (NoneType, list, tuple)):
        raise ValueError('ExclusionConstraint.include must be a list or tuple.')
    self.expressions = expressions
    self.index_type = index_type or 'GIST'
    self.condition = condition
    self.deferrable = deferrable
    self.include = tuple(include) if include else ()
    super().__init__(name=name, violation_error_code=violation_error_code, violation_error_message=violation_error_message)

def start_trace(self) -> None:
    if self.execution_trace_observer:
        self.execution_trace_observer.start()
    assert self.profiler is not None
    self.profiler._start_trace()
    if self.profile_memory:
        self.add_metadata_json('profile_memory', '1')
    if <MASK>:
        self.add_metadata_json('with_stack', '1')
    if self.record_shapes:
        self.add_metadata_json('record_shapes', '1')
    if self.with_modules:
        self.add_metadata_json('with_modules', '1')
    if self.with_flops:
        self.add_metadata_json('with_flops', '1')
    if kineto_available():
        dist_info = self._get_distributed_info()
        if dist_info:
            self.add_metadata_json('distributedInfo', json.dumps(dist_info, cls=_NumpyEncoder))
        cuda_version = None
        if hasattr(torch, 'version'):
            from torch.torch_version import TorchVersion
            cuda_version = TorchVersion(getattr(torch.version, 'cuda', '0.0'))
        if self.has_cudagraphs and (cuda_version and cuda_version < '12.6' or not profiler_allow_cudagraph_cupti_lazy_reinit_cuda12()):
            os.environ['DISABLE_CUPTI_LAZY_REINIT'] = '1'
            self.add_metadata_json('DISABLE_CUPTI_LAZY_REINIT', '1')
            os.environ['TEARDOWN_CUPTI'] = '0'
        for (k, v) in self.preset_metadata.items():
            self.add_metadata_json(k, v)

@register_op_impl(torch.ops.aten._padded_dense_to_jagged_forward.default)
def _padded_dense_to_jagged_forward(fake_mode, func, padded, offsets, total_L=None):
    assert len(offsets) == 1
    if <MASK>:
        if fake_mode.shape_env is None or not fake_mode.shape_env.allow_dynamic_output_shape_ops:
            raise DynamicOutputShapeException(func)
        total_L = fake_mode.shape_env.create_unbacked_symint()
        maxval = sys.maxsize - 1
        from torch.fx.experimental.symbolic_shapes import _constrain_range_for_size, has_free_symbols
        if not has_free_symbols(padded.numel()):
            maxval = int(padded.numel())
        _constrain_range_for_size(total_L, min=0, max=maxval)
    output_shape = (total_L, *padded.shape[2:])
    return padded.new_empty(output_shape)

def _get_applicable_entries(self, transformer_field, full_name, name):
    """Get all list entries indexed by name that apply to full_name or name."""
    function_transformers = getattr(self._api_change_spec, transformer_field, {})
    glob_name = '*.' + name if name else None
    transformers = []
    if full_name in function_transformers:
        transformers.append(function_transformers[full_name])
    if glob_name in function_transformers:
        transformers.append(function_transformers[glob_name])
    if <MASK>:
        transformers.append(function_transformers['*'])
    return transformers

@numba.njit(nogil=True, parallel=False)
def bisect_left(a: list[Any], x: Any, lo: int=0, hi: int=-1) -> int:
    """Same as https://docs.python.org/3/library/bisect.html; not in numba yet!"""
    if hi == -1:
        hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if <MASK>:
            lo = mid + 1
        else:
            hi = mid
    return lo

def __init__(self, index: Index, grouper=None, obj: NDFrame | None=None, level=None, sort: bool=True, observed: bool=False, in_axis: bool=False, dropna: bool=True, uniques: ArrayLike | None=None) -> None:
    self.level = level
    self._orig_grouper = grouper
    grouping_vector = _convert_grouper(index, grouper)
    self._orig_cats = None
    self._index = index
    self._sort = sort
    self.obj = obj
    self._observed = observed
    self.in_axis = in_axis
    self._dropna = dropna
    self._uniques = uniques
    ilevel = self._ilevel
    if <MASK>:
        if isinstance(index, MultiIndex):
            index_level = index.get_level_values(ilevel)
        else:
            index_level = index
        if grouping_vector is None:
            grouping_vector = index_level
        else:
            mapper = grouping_vector
            grouping_vector = index_level.map(mapper)
    elif isinstance(grouping_vector, Grouper):
        assert self.obj is not None
        (newgrouper, newobj) = grouping_vector._get_grouper(self.obj, validate=False)
        self.obj = newobj
        if isinstance(newgrouper, ops.BinGrouper):
            grouping_vector = newgrouper
        else:
            ng = newgrouper.groupings[0].grouping_vector
            grouping_vector = Index(ng, name=newgrouper.result_index.name)
    elif not isinstance(grouping_vector, (Series, Index, ExtensionArray, np.ndarray)):
        if getattr(grouping_vector, 'ndim', 1) != 1:
            t = str(type(grouping_vector))
            raise ValueError(f"Grouper for '{t}' not 1-dimensional")
        grouping_vector = index.map(grouping_vector)
        if not (hasattr(grouping_vector, '__len__') and len(grouping_vector) == len(index)):
            grper = pprint_thing(grouping_vector)
            errmsg = f'Grouper result violates len(labels) == len(data)\nresult: {grper}'
            raise AssertionError(errmsg)
    if isinstance(grouping_vector, np.ndarray):
        if grouping_vector.dtype.kind in 'mM':
            grouping_vector = Series(grouping_vector).to_numpy()
    elif isinstance(getattr(grouping_vector, 'dtype', None), CategoricalDtype):
        self._orig_cats = grouping_vector.categories
        grouping_vector = recode_for_groupby(grouping_vector, sort, observed)
    self.grouping_vector = grouping_vector

def _preprocess_data(self, data, mask):
    from .._ops import _sparse_coo_where, _sparse_csr_where
    if data.layout != mask.layout:
        raise TypeError('data and mask must have the same layout.')
    if data.layout == torch.sparse_coo:
        data = data.coalesce()
        mask = mask.coalesce()
        if data._nnz() != mask._nnz():
            data = _sparse_coo_where(mask, data, torch.tensor(0))
    elif <MASK>:
        if data._nnz() != mask._nnz():
            data = _sparse_csr_where(mask, data, torch.tensor(0))
    self._masked_data = data.clone()
    self._masked_mask = mask.clone()

