def asarray(obj: complex | NestedSequence[complex] | Array | SupportsBufferProtocol, /, *, dtype: DType | None=None, device: Device | None=None, copy: py_bool | None=None, **kwargs: object) -> Array:
    """
    Array API compatibility wrapper for asarray().

    See the corresponding documentation in the array library and/or the array API
    specification for more details.
    """
    _helpers._check_device(da, device)
    if isinstance(obj, da.Array):
        if <MASK>:
            if copy is False:
                raise ValueError('Unable to avoid copy when changing dtype')
            obj = obj.astype(dtype)
        return obj.copy() if copy else obj
    if copy is False:
        raise ValueError('Unable to avoid copy when converting a non-dask object to dask')
    obj = np.array(obj, dtype=dtype, copy=True)
    return da.from_array(obj)

@classmethod
def eval(cls, base: sympy.Integer, divisor: sympy.Integer) -> Union[sympy.Basic, None]:
    if divisor.is_zero:
        raise ZeroDivisionError('division by zero')
    if base in (int_oo, -int_oo, sympy.oo, -sympy.oo) and divisor in (int_oo, -int_oo, sympy.oo, -sympy.oo):
        return sympy.nan
    if base is sympy.nan or divisor is sympy.nan:
        return sympy.nan
    if base.is_zero:
        return sympy.S.Zero
    if base.is_integer and equal_valued(divisor, 1):
        return base
    if base.is_integer and equal_valued(divisor, -1):
        return sympy.Mul(base, -1)
    if isinstance(base, sympy.Number) and isinstance(divisor, sympy.Number) and (base in (int_oo, -int_oo, sympy.oo, -sympy.oo) or divisor in (int_oo, -int_oo, sympy.oo, -sympy.oo)):
        r = float(base) / float(divisor)
        if r == math.inf:
            return int_oo
        elif r == -math.inf:
            return -int_oo
        elif math.isnan(r):
            return sympy.nan
        else:
            return sympy.Integer(math.floor(r))
    if isinstance(base, sympy.Integer) and isinstance(divisor, sympy.Integer):
        return sympy.Integer(int(base) // int(divisor))
    if isinstance(base, FloorDiv):
        return FloorDiv(base.args[0], base.args[1] * divisor)
    if isinstance(divisor, sympy.Integer):
        quotients = 0
        terms = []
        for term in sympy.Add.make_args(base):
            quotient = term / divisor
            quotient_is_integer = None
            if <MASK>:
                rationals = quotient.atoms(sympy.Rational)
                all_rationals_ints = all((r.q == 1 for r in rationals))
                quotient_is_integer = quotient.is_integer and all_rationals_ints
            else:
                quotient_is_integer = quotient.is_integer
            if quotient_is_integer:
                terms.append(term)
                quotients += quotient
        if len(terms) != 0:
            return FloorDiv(base - sympy.Add(*terms, evaluate=False), divisor) + quotients
    try:
        gcd = simple_floordiv_gcd(base, divisor)
        if equal_valued(gcd, 1) and isinstance(divisor, sympy.Add):
            gcd = sympy.gcd(base, divisor)
        if not equal_valued(gcd, 1):
            return FloorDiv(sympy.simplify(base / gcd), sympy.simplify(divisor / gcd))
    except sympy.PolynomialError:
        pass
    return None

def _setitem_with_indexer(self, indexer, value, name: str='iloc') -> None:
    """
        _setitem_with_indexer is for setting values on a Series/DataFrame
        using positional indexers.

        If the relevant keys are not present, the Series/DataFrame may be
        expanded.
        """
    info_axis = self.obj._info_axis_number
    take_split_path = self._decide_split_path(indexer, value)
    if <MASK>:
        nindexer = []
        for (i, idx) in enumerate(indexer):
            (idx, missing) = convert_missing_indexer(idx)
            if missing:
                key = idx
                if self.ndim > 1 and i == info_axis:
                    self._setitem_new_column(indexer, key, value, name=name)
                    return
                index = self.obj._get_axis(i)
                labels = index.insert(len(index), key)
                taker = np.arange(len(index) + 1, dtype=np.intp)
                taker[-1] = -1
                reindexers = {i: (labels, taker)}
                new_obj = self.obj._reindex_with_indexers(reindexers, allow_dups=True)
                self.obj._mgr = new_obj._mgr
                nindexer.append(labels.get_loc(key))
            else:
                nindexer.append(idx)
        indexer = tuple(nindexer)
    else:
        (indexer, missing) = convert_missing_indexer(indexer)
        if missing:
            self._setitem_with_indexer_missing(indexer, value)
            return
    if name == 'loc':
        (indexer, value) = self._maybe_mask_setitem_value(indexer, value)
    if take_split_path:
        self._setitem_with_indexer_split_path(indexer, value, name)
    else:
        self._setitem_single_block(indexer, value, name)

