def astype(self, dtype: AstypeArg, copy: bool=True) -> ArrayLike:
    dtype = pandas_dtype(dtype)
    if dtype == self.dtype:
        if <MASK>:
            return self.copy()
        return self
    if isinstance(dtype, BaseMaskedDtype):
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', category=RuntimeWarning)
            data = self._data.astype(dtype.numpy_dtype, copy=copy)
        mask = self._mask if data is self._data else self._mask.copy()
        cls = dtype.construct_array_type()
        return cls(data, mask, copy=False)
    if isinstance(dtype, ExtensionDtype):
        eacls = dtype.construct_array_type()
        return eacls._from_sequence(self, dtype=dtype, copy=copy)
    na_value: float | np.datetime64 | lib.NoDefault
    if dtype.kind == 'f':
        na_value = np.nan
    elif dtype.kind == 'M':
        na_value = np.datetime64('NaT')
    else:
        na_value = lib.no_default
    if dtype.kind in 'iu' and self._hasna:
        raise ValueError('cannot convert NA to integer')
    if dtype.kind == 'b' and self._hasna:
        raise ValueError('cannot convert float NaN to bool')
    data = self.to_numpy(dtype=dtype, na_value=na_value, copy=copy)
    return data

def _GetNormalizeOpTest(dtype_, shape_, ord_, axis_):

    @test_util.run_in_graph_and_eager_modes
    def Test(self):
        is_matrix_norm = (isinstance(axis_, tuple) or isinstance(axis_, list)) and len(axis_) == 2
        is_fancy_p_norm = np.isreal(ord_) and np.floor(ord_) != ord_
        if not is_matrix_norm and ord_ == 'fro' or (is_matrix_norm and is_fancy_p_norm):
            self.skipTest('Not supported by neither numpy.linalg.norm nor tf.norm')
        if ord_ == 'euclidean' or (axis_ is None and len(shape) > 2):
            self.skipTest('Not supported by numpy.linalg.norm')
        matrix = np.random.randn(*shape_).astype(dtype_)
        if <MASK>:
            matrix += 1j * np.random.randn(*shape_).astype(dtype_)
        (tf_np_n, _) = self.evaluate(nn_impl.normalize(matrix, ord_, axis_))
        np_n = _Normalize(matrix, ord_, axis_)
        self.assertAllClose(tf_np_n, np_n, rtol=1e-05, atol=1e-05)
    return Test

def gen_foreach_derivativeinfo(foreach_function: NativeFunction, functional_info_by_signature: dict[FunctionSchema, dict[str, DifferentiabilityInfo]], non_functional_info_by_signature: dict[FunctionSchema, dict[str, DifferentiabilityInfo]], dispatch_key: str='Default') -> tuple[DifferentiabilityInfo | None, bool]:
    """Generate DifferentiabilityInfo for out-place foreach function, return the existing one for in-place.

    The second return value indicates whether the info is generated in this function.
    """
    ref_diff_info: DifferentiabilityInfo | None = None
    for (function_schema, diff_info) in functional_info_by_signature.items():
        if not is_reference_for_foreach(foreach_function, function_schema):
            continue
        ref_diff_info = diff_info[dispatch_key]
        if ref_diff_info is not None:
            break
    if ref_diff_info is None and foreach_function.func.kind() == SchemaKind.inplace and (str(foreach_function.func.name) in _foreach_with_inplace_ref):
        for (function_schema, diff_info) in non_functional_info_by_signature.items():
            if not is_reference_for_foreach(foreach_function, function_schema):
                continue
            ref_diff_info = diff_info[dispatch_key]
            if ref_diff_info is not None:
                break
    if ref_diff_info is None:
        return (None, False)
    if foreach_function.func.kind() == SchemaKind.inplace:
        return (ref_diff_info, False)
    (map_refarg2foreacharg, map_name2arg) = ({}, {})
    for (i, (arg, ref_arg)) in enumerate(zip(foreach_function.func.arguments.flat_non_out, function_schema.arguments.flat_non_out)):
        map_refarg2foreacharg[ref_arg.name] = arg.name
        map_name2arg[arg.name] = arg
    (all_saved_inputs, all_saved_outputs, all_var_names) = ([], [], [])
    modified_derivative_formulas = []
    for (i, derivative) in enumerate(ref_diff_info.derivatives):
        modified_formula = derivative.formula.replace('grad', 'grads[i]').replace('result', 'result[i]')
        (saved_inputs, saved_outputs) = ([], [])
