            elif foreach_arg.name != ref_arg.name:
                modified_formula = modified_formula.replace(ref_arg.name, foreach_arg.name)
            for (i, name) in enumerate(var_names):
                if name == ref_arg.name:
                    var_names[i] = foreach_arg.name
