def __new__(cls, dtype):
    try:
        obj = cls._finfo_cache.get(dtype)
        if obj is not None:
            return obj
    except TypeError:
        pass
    if dtype is None:
        warnings.warn('finfo() dtype cannot be None. This behavior will raise an error in the future. (Deprecated in NumPy 1.25)', DeprecationWarning, stacklevel=2)
    try:
        dtype = numeric.dtype(dtype)
    except TypeError:
        dtype = numeric.dtype(type(dtype))
    obj = cls._finfo_cache.get(dtype)
    if obj is not None:
        return obj
    dtypes = [dtype]
    newdtype = ntypes.obj2sctype(dtype)
    if <MASK>:
        dtypes.append(newdtype)
        dtype = newdtype
    if not issubclass(dtype, numeric.inexact):
        raise ValueError(f'data type {dtype!r} not inexact')
    obj = cls._finfo_cache.get(dtype)
    if obj is not None:
        return obj
    if not issubclass(dtype, numeric.floating):
        newdtype = _convert_to_float[dtype]
        if newdtype is not dtype:
            dtypes.append(newdtype)
            dtype = newdtype
            obj = cls._finfo_cache.get(dtype, None)
            if obj is not None:
                for dt in dtypes:
                    cls._finfo_cache[dt] = obj
                return obj
    obj = object.__new__(cls)._init(dtype)
    for dt in dtypes:
        cls._finfo_cache[dt] = obj
    return obj

def as_sql(self, compiler, connection):
    connection.ops.check_expression_support(self)
