@register_decomposition([aten.arange.start_step, aten.arange.start_out])
@out_wrapper()
def arange(start: NumberType=0, end: Optional[NumberType]=None, step: NumberType=1, *, dtype: Optional[torch.dtype]=None, layout: torch.layout=torch.strided, device: Optional[DeviceLikeType]=None, pin_memory: bool=False, requires_grad: bool=False) -> TensorLikeType:
    utils.check_layout(layout)
    utils.check_pin_memory(pin_memory)
    device = torch.device(utils.device_or_default(device))
    assert not isinstance(start, complex)
    assert not isinstance(end, complex)
    assert not isinstance(step, complex)
    if <MASK>:
        end = start
        start = 0
    torch._check(step != 0, lambda : 'step must be nonzero')
    if step > 0:
        torch._check(end >= start, lambda : 'upper bound and lower bound inconsistent with step sign')
    elif step < 0:
        torch._check(end <= start, lambda : 'upper bound and lower bound inconsistent with step sign')

    def is_finite(x):
        return not isinstance(x, FloatWithoutSymFloat) or math.isfinite(x)
    torch._check(is_finite(start) and is_finite(end), lambda : f'unsupported range: {start} -> {end}')
    torch._check(is_finite(step), lambda : f'step must be finite but got {step}')
    args = (start, end, step)
    integer_args = builtins.all((isinstance(arg, IntLike) for arg in args))
    if dtype is None:
        dtype = torch.int64 if integer_args else torch.get_default_dtype()
    is_integer = utils.is_integer_dtype(dtype)
    if is_integer or integer_args:
        xstart = sym_int(start)
        xend = sym_int(end)
        xstep = sym_int(step)
    if dtype == torch.int64 or integer_args:
        sgn = bool(xstep > 0) - bool(xstep < 0)
        length = (xend - xstart + xstep - sgn) // xstep
    else:
        length = math.ceil((end - start) / step)
    if is_integer:
        return prims.iota(length, start=xstart, step=xstep, dtype=dtype, device=device, requires_grad=requires_grad)
    index = prims.iota(length, start=0, step=1, dtype=torch.int64, device=device, requires_grad=False)
    computation_dtype = torch.long if integer_args else utils.get_acc_type(dtype, device)
    index = _maybe_convert_to_dtype(index, computation_dtype)
    result = start + step * index
    result = _maybe_convert_to_dtype(result, dtype)
    if requires_grad:
        result.requires_grad_(True)
    return result

def trim_lex(tokens):
    """
    Takes a lexed set of tokens, and removes whitespace when there is
    a directive on a line by itself:

       >>> tokens = lex('{{if x}}\\nx\\n{{endif}}\\ny', trim_whitespace=False)
       >>> tokens
       [('if x', (1, 3)), '\\nx\\n', ('endif', (3, 3)), '\\ny']
       >>> trim_lex(tokens)
       [('if x', (1, 3)), 'x\\n', ('endif', (3, 3)), 'y']
    """
    last_trim = None
    for (i, current) in enumerate(tokens):
        if isinstance(current, basestring_):
            continue
        item = current[0]
        if <MASK>:
            continue
        if not i:
            prev = ''
        else:
            prev = tokens[i - 1]
        if i + 1 >= len(tokens):
            next_chunk = ''
        else:
            next_chunk = tokens[i + 1]
        if not isinstance(next_chunk, basestring_) or not isinstance(prev, basestring_):
            continue
        prev_ok = not prev or trail_whitespace_re.search(prev)
        if i == 1 and (not prev.strip()):
            prev_ok = True
        if last_trim is not None and last_trim + 2 == i and (not prev.strip()):
            prev_ok = 'last'
        if prev_ok and (not next_chunk or lead_whitespace_re.search(next_chunk) or (i == len(tokens) - 2 and (not next_chunk.strip()))):
            if prev:
                if i == 1 and (not prev.strip()) or prev_ok == 'last':
                    tokens[i - 1] = ''
                else:
                    m = trail_whitespace_re.search(prev)
                    prev = prev[:m.start() + 1]
                    tokens[i - 1] = prev
            if next_chunk:
                last_trim = i
                if i == len(tokens) - 2 and (not next_chunk.strip()):
                    tokens[i + 1] = ''
                else:
                    m = lead_whitespace_re.search(next_chunk)
                    next_chunk = next_chunk[m.end():]
                    tokens[i + 1] = next_chunk
    return tokens

def unsupported_input_tensor(t: torch.Tensor, node=None):
