def _sample_callback_fn(self, use_subtests, device):
    sample_skips_and_xfails = getattr(extract_test_fn(), 'sample_skips_and_xfails', None)
    if sample_skips_and_xfails is not None and (not use_subtests):
        raise RuntimeError('Sample-specific skips / xfails require use_subtests=True.\nPlease pass this to the sample generation function and run the test logic within the\nreturned contexts (NB: order matters!). For example:\n\ndef test_foo(self, device, dtype, op):\n    for sample, subtest_ctx, skip_xfail_ctx in op.sample_inputs(..., use_subtests=True):\n        # these contexts handle running within subtests and skips / xfails\n        with subtest_ctx(self), skip_xfail_ctx(self):\n            # test logic here\n            ...')
    if not use_subtests:
        return None
    if <MASK>:
        try:
            import pytest_subtests
        except ModuleNotFoundError:
            raise RuntimeError('Encountered an OpInfo test with use_subtests=True and pytest-subtests is not installed. The feature will not work correctly within pytest without this package; please install it.') from None

    def _f(sample, idx, self=self, device=device, sample_skips_and_xfails=sample_skips_and_xfails, use_subtests=use_subtests):
        return (sample, *self._maybe_skip_or_xfail(sample_skips_and_xfails, device, sample, idx))
    return _f

def _tcp_rendezvous_handler(url: str, timeout: timedelta=default_pg_timeout, **kwargs):

    def _error(msg):
        return _rendezvous_error('tcp:// rendezvous: ' + msg)
    result = urlparse(url)
    if result.port is None:
        raise _error('port number missing')
    query_dict = _query_to_dict(result.query)
    if <MASK>:
        raise _error('rank parameter missing')
    if 'world_size' not in query_dict:
        raise _error('world size parameter missing')
    rank = int(query_dict['rank'])
    world_size = int(query_dict['world_size'])
    use_libuv = _get_use_libuv_from_query_dict(query_dict)
    assert result.hostname is not None
    store = _create_c10d_store(result.hostname, result.port, rank, world_size, timeout, use_libuv)
    yield (store, rank, world_size)
    raise RuntimeError('Unable to perform re-rendezvous using tcp:// method')

def _param_type_compatible_with_arg(param: _schemas.Parameter, value: ir.TypeProtocol | str | int | float | complex | Sequence[int] | Sequence[float] | None, assigned_types: dict[str, ir.TypeProtocol]) -> bool:
    if <MASK>:
        if param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.BOOL)}:
            return True
    if isinstance(value, int) and param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.INT4), ir.TensorType(ir.DataType.INT8), ir.TensorType(ir.DataType.INT16), ir.TensorType(ir.DataType.INT32), ir.TensorType(ir.DataType.INT64), ir.TensorType(ir.DataType.FLOAT4E2M1), ir.TensorType(ir.DataType.FLOAT8E4M3FN), ir.TensorType(ir.DataType.FLOAT8E4M3FNUZ), ir.TensorType(ir.DataType.FLOAT8E5M2), ir.TensorType(ir.DataType.FLOAT8E5M2FNUZ), ir.TensorType(ir.DataType.FLOAT16), ir.TensorType(ir.DataType.FLOAT), ir.TensorType(ir.DataType.DOUBLE)}:
        return True
    if isinstance(value, float) and param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.FLOAT4E2M1), ir.TensorType(ir.DataType.FLOAT8E4M3FN), ir.TensorType(ir.DataType.FLOAT8E4M3FNUZ), ir.TensorType(ir.DataType.FLOAT8E5M2), ir.TensorType(ir.DataType.FLOAT8E5M2FNUZ), ir.TensorType(ir.DataType.FLOAT16), ir.TensorType(ir.DataType.FLOAT), ir.TensorType(ir.DataType.DOUBLE)}:
        return True
    if isinstance(value, complex) and param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.FLOAT), ir.TensorType(ir.DataType.DOUBLE), ir.TensorType(ir.DataType.COMPLEX64), ir.TensorType(ir.DataType.COMPLEX128)}:
        return True
    if isinstance(value, str):
        if param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.STRING)}:
            return True
    if isinstance(value, (list, tuple)):
        if param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.INT32), ir.TensorType(ir.DataType.INT64), ir.TensorType(ir.DataType.FLOAT), ir.TensorType(ir.DataType.DOUBLE), ir.SequenceType(ir.TensorType(ir.DataType.INT32)), ir.SequenceType(ir.TensorType(ir.DataType.INT64)), ir.SequenceType(ir.TensorType(ir.DataType.FLOAT)), ir.SequenceType(ir.TensorType(ir.DataType.DOUBLE))} and all((isinstance(i, int) for i in value)):
            return True
        if param.type_constraint.allowed_types & {ir.TensorType(ir.DataType.FLOAT), ir.TensorType(ir.DataType.DOUBLE), ir.SequenceType(ir.TensorType(ir.DataType.FLOAT)), ir.SequenceType(ir.TensorType(ir.DataType.DOUBLE))} and all((isinstance(i, (int, float)) for i in value)):
            return True
    if value is None and (not param.required):
        return True
    if not isinstance(value, ir.TypeProtocol):
        return False
    if param.type_constraint.name in assigned_types:
        assigned_type = assigned_types[param.type_constraint.name]
        return assigned_type == value
    if value in param.type_constraint.allowed_types:
        assigned_types[param.type_constraint.name] = value
        return True
    return False

def get_as_bool(self, key: str, default: Optional[bool]=None) -> Optional[bool]:
    """Return the value for ``key`` as a ``bool``."""
    value = self.get(key, default)
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        if value == 1:
            return True
        if value == 0:
            return False
    elif <MASK>:
        if value.lower() in ['1', 'true', 't', 'yes', 'y']:
            return True
        if value.lower() in ['0', 'false', 'f', 'no', 'n']:
            return False
    raise ValueError(f"The rendezvous configuration option '{key}' does not represent a valid boolean value.")

