def _align_for_op(self, other, axis: AxisInt, flex: bool | None=False, level: Level | None=None):
    """
        Convert rhs to meet lhs dims if input is list, tuple or np.ndarray.

        Parameters
        ----------
        other : Any
        axis : int
        flex : bool or None, default False
            Whether this is a flex op, in which case we reindex.
            None indicates not to check for alignment.
        level : int or level name, default None

        Returns
        -------
        left : DataFrame
        right : Any
        """
    (left, right) = (self, other)

    def to_series(right):
        msg = 'Unable to coerce to Series, length must be {req_len}: given {given_len}'
        dtype = None
        if getattr(right, 'dtype', None) == object:
            dtype = object
        if axis == 0:
            if <MASK>:
                raise ValueError(msg.format(req_len=len(left.index), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.index, dtype=dtype)
        else:
            if len(left.columns) != len(right):
                raise ValueError(msg.format(req_len=len(left.columns), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.columns, dtype=dtype)
        return right
    if isinstance(right, np.ndarray):
        if right.ndim == 1:
            right = to_series(right)
        elif right.ndim == 2:
            dtype = None
            if right.dtype == object:
                dtype = object
            if right.shape == left.shape:
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[0] == left.shape[0] and right.shape[1] == 1:
                right = np.broadcast_to(right, left.shape)
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[1] == left.shape[1] and right.shape[0] == 1:
                right = to_series(right[0, :])
            else:
                raise ValueError(f'Unable to coerce to DataFrame, shape must be {left.shape}: given {right.shape}')
        elif right.ndim > 2:
            raise ValueError(f'Unable to coerce to Series/DataFrame, dimension must be <= 2: {right.shape}')
    elif is_list_like(right) and (not isinstance(right, (Series, DataFrame))):
        if any((is_array_like(el) for el in right)):
            raise ValueError(f'Unable to coerce list of {type(right[0])} to Series/DataFrame')
        right = to_series(right)
    if flex is not None and isinstance(right, DataFrame):
        if not left._indexed_same(right):
            if flex:
                (left, right) = left.align(right, join='outer', level=level)
            else:
                raise ValueError('Can only compare identically-labeled (both index and columns) DataFrame objects')
    elif isinstance(right, Series):
        axis = axis if axis is not None else 1
        if not flex:
            if not left.axes[axis].equals(right.index):
                raise ValueError('Operands are not aligned. Do `left, right = left.align(right, axis=1)` before operating.')
        (left, right) = left.align(right, join='outer', axis=axis, level=level)
        right = left._maybe_align_series_as_frame(right, axis)
    return (left, right)

@property
def initializer(self):
    if <MASK>:
        return self._table._init_op
    with ops.name_scope(None, 'init'):
        return control_flow_ops.no_op()

def check_array_lengths(inputs, targets, weights=None):
    """Does user input validation for numpy arrays.

  Args:
      inputs: list of Numpy arrays of inputs.
      targets: list of Numpy arrays of targets.
      weights: list of Numpy arrays of sample weights.

  Raises:
      ValueError: in case of incorrectly formatted data.
  """

    def is_tensor_or_composite_tensor(x):
        return tensor_util.is_tf_type(x) or is_composite_or_composite_value(x)

    def set_of_lengths(x):
        if x is None:
            return {}
        else:
            return set([y.shape[0] for y in x if y is not None and (not is_tensor_or_composite_tensor(y))])
    set_x = set_of_lengths(inputs)
    set_y = set_of_lengths(targets)
    set_w = set_of_lengths(weights)
    if len(set_x) > 1:
        raise ValueError('All input arrays (x) should have the same number of samples. Got array shapes: ' + str([x.shape for x in inputs]))
    if len(set_y) > 1:
        raise ValueError('All target arrays (y) should have the same number of samples. Got array shapes: ' + str([y.shape for y in targets]))
    if set_x and set_y and (list(set_x)[0] != list(set_y)[0]):
        raise ValueError('Input arrays should have the same number of samples as target arrays. Found ' + str(list(set_x)[0]) + ' input samples and ' + str(list(set_y)[0]) + ' target samples.')
    if len(set_w) > 1:
        raise ValueError('All sample_weight arrays should have the same number of samples. Got array shapes: ' + str([w.shape for w in weights]))
    if <MASK>:
        raise ValueError('Sample_weight arrays should have the same number of samples as target arrays. Got ' + str(list(set_y)[0]) + ' input samples and ' + str(list(set_w)[0]) + ' target samples.')

def _validate_schedule(actions: dict[int, list[Optional[_Action]]], pp_group_size: int, num_stages: int, num_microbatches: int) -> dict[int, int]:
    assert len(actions) == pp_group_size, f'Schedule has incorrect number of ranks - expected {pp_group_size}, actual {len(actions)}'
    for rank in range(pp_group_size):
        assert rank in actions, f'Schedule is missing actions for rank {rank}'
    stage_actions: dict[int, dict[_ComputationType, set]] = {stage_id: {F: set(), B: set(), I: set(), W: set()} for stage_id in range(num_stages)}
    stage_index_to_rank_mapping = {}

    def _process_action(action: _Action, rank: int, step: int):
        """Process a single action and update stage_actions and stage_index_to_rank_mapping"""
        s_id = action.stage_index
        ctype = action.computation_type
        mb_id = action.microbatch_index
        if ctype == F:
            stage_actions[s_id][F].add(mb_id)
        elif ctype == B:
            if mb_id not in stage_actions[s_id][F]:
                error_msg = f'Rank {rank}, step {step}: Running Full Backward for stage {s_id}, microbatch {mb_id} without first running Forward'
                formatted_schedule = _format_pipeline_order(actions, error_step_number=step)
                full_error_msg = f'{error_msg}\n\nFull pipeline schedule:\n{formatted_schedule}'
                raise AssertionError(full_error_msg)
            stage_actions[s_id][B].add(mb_id)
        elif ctype == I:
            if mb_id not in stage_actions[s_id][F]:
                error_msg = f'Rank {rank}, step {step}: Running Backward Input for stage {s_id}, microbatch {mb_id} without first running Forward'
                formatted_schedule = _format_pipeline_order(actions, error_step_number=step)
                full_error_msg = f'{error_msg}\n\nFull pipeline schedule:\n{formatted_schedule}'
                raise AssertionError(full_error_msg)
            stage_actions[s_id][I].add(mb_id)
        elif <MASK>:
            if mb_id not in stage_actions[s_id][I]:
                error_msg = f'Rank {rank}, step {step}: Running Backward Weight for stage {s_id}, microbatch {mb_id} without first running Backward Input'
                formatted_schedule = _format_pipeline_order(actions, error_step_number=step)
                full_error_msg = f'{error_msg}\n\nFull pipeline schedule:\n{formatted_schedule}'
                raise AssertionError(full_error_msg)
            stage_actions[s_id][W].add(mb_id)
        if s_id not in stage_index_to_rank_mapping:
            stage_index_to_rank_mapping[s_id] = rank
        else:
            existing_rank = stage_index_to_rank_mapping[s_id]
            assert rank == existing_rank, f'Rank {rank}, step {step}: Stage {s_id} is assigned to both rank {rank} and rank {existing_rank}'
    for rank in actions:
        for (step, action) in enumerate(actions[rank]):
            if action is None:
                continue
            assert isinstance(action, _Action), f'Rank {rank}, step {step}: Got an invalid action: {action}, expected instance of _Action'
            if action.sub_actions is not None:
                for sub_action in action.sub_actions:
                    _process_action(sub_action, rank, step)
            else:
                _process_action(action, rank, step)
    for s_id in stage_actions:
        f_mb = len(stage_actions[s_id][F])
        b_mb = len(stage_actions[s_id][B])
        i_mb = len(stage_actions[s_id][I])
        w_mb = len(stage_actions[s_id][W])
        assert f_mb == num_microbatches, f'Got {f_mb} {F} microbatches for stage {s_id}, expected {num_microbatches}'
        assert i_mb == w_mb, f'Invalid backward microbatches for stage {s_id}: I and W must have equal counts,             but got I={i_mb}, W={w_mb}'
        assert b_mb + (i_mb + w_mb) // 2 == num_microbatches, f'Invalid backward microbatches for stage {s_id}: expected {num_microbatches} total backwards,             but got B={b_mb}, I={i_mb}, W={w_mb}'
    return stage_index_to_rank_mapping

def map_arg(arg):

    def maybe_non_contig(tensor):
        if not non_contiguous or tensor.numel() < 2:
            return tensor.clone()
        return noncontiguous_like(tensor)

    def conjugate(tensor):
        return tensor.conj()
    if isinstance(arg, (torch.Size, dont_convert)):
        return arg
    elif <MASK>:
        var = conjugate(torch.randn((), dtype=dtype, device=device))
        var.requires_grad = requires_grad
        return var
    elif isinstance(arg, tuple) and (not isinstance(arg[0], torch.Tensor)):
        return conjugate(maybe_non_contig(torch.randn(*arg, dtype=dtype, device=device))).requires_grad_(requires_grad)
    elif isinstance(arg, non_differentiable):
        if isinstance(arg.tensor, torch.Tensor):
            return conjugate(maybe_non_contig(arg.tensor.to(device=device)))
        return conjugate(maybe_non_contig(arg.tensor.to(device=device)))
    elif isinstance(arg, torch.Tensor):
        if arg.is_complex() != dtype.is_complex:
            raise RuntimeError('User provided tensor is real for a test that runs with complex dtype, ', 'which is not supported for now')
        v = conjugate(maybe_non_contig(arg)).detach().to(device=device).clone()
        v.requires_grad = requires_grad and (v.is_floating_point() or v.is_complex())
        return v
    elif callable(arg):
        return map_arg(arg(dtype=dtype, device=device))
    else:
        return arg

def _training_ref(self, x, scale, offset, old_mean, old_var, exponential_avg_factor, epsilon, data_format):
    if data_format not in ['NHWC', 'NCHW', 'NDHWC', 'NCDHW']:
        raise ValueError('data_format must be NCHW or NHWC for 4D tensors orNCDHW or NDHWC for 5D tensors, got %s.' % data_format)
    use_4d_tensor = x.shape.ndims == 4
    if data_format == 'NCHW':
        x = array_ops.transpose(x, [0, 2, 3, 1])
    elif <MASK>:
        x = array_ops.transpose(x, [0, 2, 3, 4, 1])
    mean_axis = [0, 1, 2] if use_4d_tensor else [0, 1, 2, 3]
    (batch_mean, batch_var) = nn_impl.moments(math_ops.cast(x, scale.dtype), mean_axis, keep_dims=False)
    y = self._batch_norm(x, batch_mean, batch_var, offset, scale, epsilon)
    if data_format == 'NCHW':
        y = array_ops.transpose(y, [0, 3, 1, 2])
    elif data_format == 'NCDHW':
        y = array_ops.transpose(y, [0, 4, 1, 2, 3])
    sample_size = math_ops.cast(array_ops.size(x) / array_ops.size(scale), scale.dtype)
    batch_var_corrected = batch_var * sample_size / math_ops.maximum(sample_size - 1.0, 1.0)
    mean = self._running_mean(old_mean, batch_mean, exponential_avg_factor)
    var = self._running_mean(old_var, batch_var_corrected, exponential_avg_factor)
    return (self.evaluate(y), self.evaluate(mean), self.evaluate(var))

def _replace_pattern(gm: GraphModule, pattern: Union[Callable, Graph, GraphModule], replacement: Union[Callable, Graph, GraphModule, None]=None, match_filters: Optional[list[Callable[['InternalMatch', Graph, Graph], bool]]]=None, ignore_literals: bool=False, replacement_callback: Optional[Callable[['InternalMatch', Graph, Graph], Graph]]=None, node_name_match: str='') -> list[ReplacedPatterns]:
    from torch.fx.passes.utils.matcher_utils import InternalMatch, SubgraphMatcher
    if match_filters is None:
        match_filters = []
    original_graph: Graph = gm.graph
    if isinstance(pattern, GraphModule):
        pattern_graph = pattern.graph
    elif isinstance(pattern, Graph):
        pattern_graph = pattern
    else:
        pattern_graph = symbolic_trace(pattern).graph
    matcher = SubgraphMatcher(pattern_graph, match_output=False, match_placeholder=False, remove_overlapping_matches=True, ignore_literals=ignore_literals)
    _matches: list[InternalMatch] = matcher.match(original_graph, node_name_match=node_name_match)
    _matches = [m for m in _matches if all((match_filter(m, original_graph, pattern_graph) for match_filter in match_filters))]
    if isinstance(replacement, GraphModule):
        common_replacement_graph = replacement.graph
    elif isinstance(replacement, Graph):
        common_replacement_graph = replacement
    elif callable(replacement):
        common_replacement_graph = symbolic_trace(replacement).graph
    else:
        assert replacement_callback is not None, 'Must provide either a replacement GraphModule or a replacement callback'
        common_replacement_graph = None
    match_changed_node: dict[Node, Node] = {}
    match_and_replacements = []
    for match in _matches:
        if replacement_callback is not None:
            replacement_graph = replacement_callback(match, original_graph, pattern_graph)
        else:
            assert common_replacement_graph is not None, 'Must provide either a replacement GraphModule or a replacement callback'
            replacement_graph = common_replacement_graph
        replacement_placeholders = [n for n in replacement_graph.nodes if n.op == 'placeholder']
        assert len(match.placeholder_nodes) == len(replacement_placeholders)
        val_map: dict[Node, Node] = {}
        for (rn, gn) in zip(replacement_placeholders, match.placeholder_nodes):
            if isinstance(gn, Node):
                val_map[rn] = match_changed_node.get(gn, gn)
                if gn != val_map[rn]:
                    gn_ind = match.placeholder_nodes.index(gn)
                    match.placeholder_nodes[gn_ind] = match_changed_node[gn]
                    map_key = list(match.nodes_map.keys())[list(match.nodes_map.values()).index(gn)]
                    match.nodes_map[map_key] = match_changed_node[gn]
            else:
                val_map[rn] = gn
        user_nodes: set[Node] = set()
        for n in match.returning_nodes:
            user_nodes.update(n.users)
        first_user_node = None
        if len(user_nodes) == 0:
            first_user_node = None
        elif len(user_nodes) == 1:
            first_user_node = next(iter(user_nodes))
        else:
            for n in original_graph.nodes:
                if n in user_nodes:
                    first_user_node = n
                    break
        first_next_node = None
        if first_user_node is None:
            next_node = None
            for n in reversed(original_graph.nodes):
                if n in match.returning_nodes:
                    first_next_node = next_node
                    break
                else:
                    next_node = n
        insert_point = first_user_node if first_user_node is not None else first_next_node
        assert insert_point is not None, "The insert point can't be None"
        with original_graph.inserting_before(insert_point):
            copied_returning_nodes = original_graph.graph_copy(replacement_graph, val_map)
        if isinstance(copied_returning_nodes, Node):
            copied_returning_nodes = (copied_returning_nodes,)
        replacement_nodes: list[Node] = [v for v in val_map.values() if v not in match.placeholder_nodes]
        assert len(match.returning_nodes) == len(copied_returning_nodes)
        for (gn, copied_node) in zip(match.returning_nodes, copied_returning_nodes):
            gn.replace_all_uses_with(copied_node)
            match_changed_node[gn] = copied_node
        for node in reversed(pattern_graph.nodes):
            if node.op != 'placeholder' and node.op != 'output':
                gn = match.nodes_map[node]
                gm.graph.erase_node(gn)
        match_and_replacements.append(ReplacedPatterns(anchor=match.anchors[0], nodes_map=match.nodes_map, replacements=replacement_nodes))
    gm.recompile()
    if <MASK>:
        _replace_attributes(gm, replacement)
    return match_and_replacements

def parenthesize(self, item: sympy.Expr, level: int, strict: bool=False) -> str:
    if <MASK>:
        return f'({self._print(item)})'
    else:
        return super().parenthesize(item, level, strict)

def divide_by_n_tensors_or_indexed_slices(value, n):
    if <MASK>:
        value = backprop_util.FlattenNestedIndexedSlices(value)
        return indexed_slices.IndexedSlices(value.values / n, value.indices, value.dense_shape)
    else:
        return value / n

def identify_license(f, exception=''):
    """
    Read f and try to identify the license type
    This is __very__ rough and probably not legally binding, it is specific for
    this repo.
    """

    def squeeze(t):
        """Remove 'n and ' ', normalize quotes
        """
        t = t.replace('\n', '').replace(' ', '')
        t = t.replace('``', '"').replace("''", '"')
        return t
    with open(f) as fid:
        txt = fid.read()
        if not exception and 'exception' in txt:
            license = identify_license(f, 'exception')
            return license + ' with exception'
        txt = squeeze(txt)
        if 'ApacheLicense' in txt:
            return 'Apache-2.0'
        elif 'MITLicense' in txt:
            return 'MIT'
        elif 'BSD-3-ClauseLicense' in txt:
            return 'BSD-3-Clause'
        elif 'BSD3-ClauseLicense' in txt:
            return 'BSD-3-Clause'
        elif 'BoostSoftwareLicense-Version1.0' in txt:
            return 'BSL-1.0'
        elif 'gettimeofday' in txt:
            return 'Apache-2.0'
        elif 'libhungarian' in txt:
            return 'Permissive (free to use)'
        elif 'PDCurses' in txt:
            return 'Public Domain for core'
        elif 'Copyright1999UniversityofNorthCarolina' in txt:
            return 'Apache-2.0'
        elif 'sigslot' in txt:
            return 'Public Domain'
        elif squeeze('Clarified Artistic License') in txt:
            return 'Clarified Artistic License'
        elif all([squeeze(m) in txt.lower() for m in bsd3_txt]):
            return 'BSD-3-Clause'
        elif all([squeeze(m) in txt.lower() for m in bsd3_v1_txt]):
            return 'BSD-3-Clause'
        elif <MASK>:
            return 'BSD-2-Clause'
        elif all([squeeze(m) in txt.lower() for m in bsd3_src_txt]):
            return 'BSD-Source-Code'
        elif any([squeeze(m) in txt.lower() for m in mit_txt]):
            return 'MIT'
        else:
            raise ValueError('unknown license')

def _add_object_graph_edges(self, proto, node_id):
    """Adds edges from an object to its children."""
    obj = self._nodes[node_id]
    setter = self._node_setters[node_id]
    for reference in proto.children:
        setter(obj, reference.local_name, self._nodes[reference.node_id])
        if <MASK>:
            setattr(type(obj), '__call__', _call_attribute)

def parse_cookie(cookie):
    """
    Return a dictionary parsed from a `Cookie:` header string.
    """
    cookiedict = {}
    for chunk in cookie.split(';'):
        if <MASK>:
            (key, val) = chunk.split('=', 1)
        else:
            (key, val) = ('', chunk)
        (key, val) = (key.strip(), val.strip())
        if key or val:
            cookiedict[key] = cookies._unquote(val)
    return cookiedict

def common_sign2map(a, var):
    ret = {'varname': a, 'ctype': getctype(var)}
    if isstringarray(var):
        ret['ctype'] = 'char'
    if <MASK>:
        ret['atype'] = c2capi_map[ret['ctype']]
        ret['elsize'] = get_elsize(var)
    if ret['ctype'] in cformat_map:
        ret['showvalueformat'] = f"{cformat_map[ret['ctype']]}"
    if isarray(var):
        ret = dictappend(ret, getarrdims(a, var))
    elif isstring(var):
        ret['size'] = getstrlength(var)
        ret['rank'] = '1'
    (ret['pydocsign'], ret['pydocsignout']) = getpydocsign(a, var)
    if hasnote(var):
        ret['note'] = var['note']
        var['note'] = ['See elsewhere.']
    ret['arrdocstr'] = getarrdocsign(a, var)
    return ret

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif name == 'extend' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
        if isinstance(idx, SymNodeVariable):
            const_idx = idx.evaluate_expr()
        else:
            const_idx = idx.as_python_constant()
        tx.output.side_effects.mutation(self)
        self.items.insert(const_idx, value)
        return ConstantVariable.create(None)
    elif <MASK>:
        if kwargs or len(args) > 1:
            raise_args_mismatch(tx, name, 'at most 1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if len(self.items) == 0:
            msg = ConstantVariable.create('pop from empty list')
            raise_observed_exception(IndexError, tx, args=[msg])
        if len(args):
            idx = args[0].as_python_constant()
            if idx > len(self.items):
                msg = ConstantVariable.create('pop index out of range')
                raise_observed_exception(IndexError, tx, args=[msg])
        tx.output.side_effects.mutation(self)
        return self.items.pop(*[a.as_python_constant() for a in args])
    elif name == 'clear' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        self.items.clear()
        return ConstantVariable.create(None)
    elif name == '__setitem__' and self.is_mutable() and args and (args[0].is_python_constant() or isinstance(args[0], SymNodeVariable) or (isinstance(args[0], SliceVariable) and all((s.is_python_constant() or isinstance(s, SymNodeVariable) for s in args[0].items)))):
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        (key, value) = args
        tx.output.side_effects.mutation(self)
        if isinstance(key, SymNodeVariable):
            self.items[key.evaluate_expr()] = value
        elif isinstance(key, SliceVariable):
            if key.is_python_constant():
                self.items[key.as_python_constant()] = list(value.items)
            else:
                items = slice(*[s.evaluate_expr() if isinstance(s, SymNodeVariable) else s.as_python_constant() for s in key.items])
                self.items[items] = list(value.items)
        else:
            self.items[key.as_python_constant()] = value
        return ConstantVariable.create(None)
    elif name == '__delitem__' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        if args[0].is_python_constant() and isinstance(args[0].as_python_constant(), (int, slice)):
            if isinstance(args[0], SymNodeVariable):
                idx = args[0].evaluate_expr()
            else:
                idx = args[0].as_python_constant()
            try:
                self.items.__delitem__(idx)
            except (IndexError, ValueError) as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            msg = ConstantVariable.create(f'list indices must be integers or slices, not {args[0].python_type_name()}')
            raise_observed_exception(TypeError, tx, args=[msg])
        return ConstantVariable.create(None)
    elif name == 'copy':
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        items = list(self.items)
        return self.modified(items, mutation_type=ValueMutationNew())
    elif name == 'reverse' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        self.items.reverse()
        tx.output.side_effects.mutation(self)
        return ConstantVariable.create(None)
    elif name == 'remove' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        idx = self.call_method(tx, 'index', args, kwargs)
        self.call_method(tx, 'pop', [idx], {})
        return ConstantVariable.create(None)
    else:
        return super().call_method(tx, name, args, kwargs)

def _safe_pow(base, exponent):
    if exponent < 0:
        raise ValueError('Exponent must be non-negative.')
    if exponent == 0:
        return 1
    half_exp = safe_pow(base, exponent // 2)
    if half_exp is int_oo:
        return int_oo
    result = half_exp * half_exp
    if result > sys.maxsize:
        return int_oo
    if <MASK>:
        result *= base
        if result > sys.maxsize:
            return int_oo
    return result

