@staticmethod
def compute_default_shard_order(placements: tuple[Placement, ...]) -> ShardOrder:
    """
        Compute the default shard order from placements.

        Returns a ShardOrder where each ShardOrderEntry maps a tensor dimension
        to the mesh dimensions it's sharded on, in left-to-right order.
        """
    tensor_dim_to_mesh_dims: defaultdict[int, list[int]] = defaultdict(list)
    mesh_ndim = len(placements)
    for mesh_dim in range(mesh_ndim):
        if <MASK>:
            return ()
        if isinstance(placements[mesh_dim], Shard):
            placement = cast(Shard, placements[mesh_dim])
            shard_dim = placement.dim
            assert shard_dim >= 0, f'Shard dim {shard_dim} in placements {placements} must be normalized'
            tensor_dim_to_mesh_dims[shard_dim].append(mesh_dim)
    default_shard_order = tuple((ShardOrderEntry(tensor_dim=key, mesh_dims=tuple(value)) for (key, value) in sorted(tensor_dim_to_mesh_dims.items()) if value))
    return default_shard_order

def _check_valid_op(op) -> None:

    def _allowed_builtin_ops() -> list:
        ret = self.allowed_builtin_ops()
        assert all((inspect.isbuiltin(op) for op in ret))
        return ret

    def _allowed_op_types() -> tuple[type[Any], ...]:
        ret = self.allowed_op_types()
        assert not any((t is object for t in ret))
        return ret
    _allowed_torch_functions = (torch.autograd.grad_mode.set_grad_enabled, torch.sym_int, torch.sym_float, torch.sym_ite, torch.sym_max, torch.sym_min, torch.sym_not, torch.sym_sqrt, torch.sym_sum, torch.export.custom_ops._call_custom_autograd_function_in_pre_dispatch, torch._C._set_grad_enabled, torch.amp.autocast_mode._enter_autocast, torch.amp.autocast_mode._exit_autocast, torch.fx.experimental.symbolic_shapes.cast_symbool_to_symint_guardless, torch._functorch.predispatch._add_batch_dim, torch._functorch.predispatch._remove_batch_dim, torch._functorch.predispatch._vmap_increment_nesting, torch._functorch.predispatch._vmap_decrement_nesting, torch._functorch.predispatch.lazy_load_decompositions)
    if <MASK>:
        if op not in _allowed_builtin_ops() and op not in _allowed_torch_functions:
            raise SpecViolationError(f"Operator '{op}' is not an allowed operator type: {_allowed_op_types()}\nValid builtin ops: {_allowed_builtin_ops()}Valid torch functions: {_allowed_torch_functions}")
    if isinstance(op, OpOverload):
        if self.dialect != 'TRAINING' and (not is_functional(op)):
            raise SpecViolationError(f"operator '{op}' is not functional")
    self.check_valid_op(op)

def next_variable(self, tx):
    assert self.is_mutable()
    if len(self.iterables) == 0:
        raise_observed_exception(StopIteration, tx)
    old_index = self.index
    args = []

    def get_item(it):
        if isinstance(it, list):
            if old_index >= len(it):
                raise_observed_exception(StopIteration, tx)
            return it[old_index]
        else:
            return it.next_variable(tx)
    try:
        for (idx, it) in enumerate(self.iterables):
            args.append(get_item(it))
    except ObservedUserStopIteration:
        if <MASK>:
            if idx == 0:
                for it in self.iterables:
                    try:
                        get_item(it)
                    except ObservedUserStopIteration:
                        handle_observed_exception(tx)
                        continue
                    break
                else:
                    raise
            handle_observed_exception(tx)
            raise UserError(ValueError, 'zip() has one argument of len differing from others') from None
        raise
    tx.output.side_effects.mutation(self)
    self.index += 1
    return variables.TupleVariable(args)

def combo_grid_meta(self) -> dict[str, Any]:
    dynamic_shape = bool(self.dynamic_shape_args)
    num_kernels = len(self.sub_kernels)
    min_blocks = max(self.min_x_blocks_list) * num_kernels if not dynamic_shape else None
    if <MASK>:
        if 'YBLOCK' in self.block_args:
            default_config = {'XBLOCK': self.block_size_2d, 'YBLOCK': self.block_size_2d}
        else:
            default_config = {'XBLOCK': self.block_size_1d}
    else:
        default_config = None
    meta = {'num_kernels': num_kernels, 'min_blocks': min_blocks, 'default_config': default_config}
    for (num, sub_kernel) in enumerate(self.sub_kernels):
        meta[f'no_x_dim_{num}'] = sub_kernel.no_x_dim
        for (i, tree) in enumerate(sub_kernel.range_trees):
            if not tree.is_reduction:
                numel_name = f'{tree.prefix}numel_{num}'
                if numel_name in self.dynamic_shape_args:
                    meta[numel_name] = None
                else:
                    meta[numel_name] = int(V.graph.sizevars.simplify(tree.numel))
    return meta

def get_multiplier() -> float:
    if force_max_multiplier:
        return 10.0
    multiplier = 3.0 if res.dtype in (torch.float16, torch.bfloat16) else 2.0
    if use_larger_multiplier_for_smaller_tensor and fp64_ref.numel() <= 10:
        multiplier = 10.0
    elif use_larger_multiplier_for_smaller_tensor and fp64_ref.numel() <= 500:
        multiplier = 8.0
    elif <MASK>:
        multiplier = 3.0
    return multiplier

def _iter(obj):
    if conversion is not None:
        obj = conversion(obj)
    if <MASK>:
        yield obj
    elif obj is None:
        return
    elif isinstance(obj, (list, tuple)):
        for o in obj:
            yield from _iter(o)
    elif isinstance(obj, dict):
        for o in obj.values():
            yield from _iter(o)
    elif allow_unknown:
        yield obj
    else:
        raise ValueError("Auto nesting doesn't know how to process an input object of type " + torch.typename(obj) + ('. Accepted types: ' + condition_msg + ', or lists/tuples of them' if condition_msg else ''))

@torch.jit.ignore
def update_scale(self, X: torch.Tensor, _scale: torch.Tensor, _zero_point: torch.Tensor) -> None:
    if <MASK>:
        self.scale.data = _scale.to(X.device)
        self.zero_point = _zero_point.to(X.device)
    else:
        self.scale.data = _scale
        if not self.is_symmetric:
            self.zero_point = _zero_point
        else:
            self.zero_point = torch.zeros_like(_zero_point)
        for i in range(X.dim()):
            if i == self.ch_axis:
                continue
            self.zero_point = self.zero_point.unsqueeze(i)
    X_q = X / self.scale
    X_q_floor = torch.floor(X_q)
    residual = X_q - X_q_floor
    if not torch.all(torch.ge(residual, 0)):
        raise AssertionError('residual should be non-negative in [0, 1)')
    V_init = -torch.log((self.zeta - self.gamma) / (residual - self.gamma) - 1)
    self.V.data = V_init

def lint_test_case_extension(suite):
    succeed = True
    for test_case_or_suite in suite:
        test_case = test_case_or_suite
        if isinstance(test_case_or_suite, unittest.TestSuite):
            first_test = test_case_or_suite._tests[0] if len(test_case_or_suite._tests) > 0 else None
            if <MASK>:
                return succeed and lint_test_case_extension(test_case_or_suite)
            test_case = first_test
        if test_case is not None:
            if not isinstance(test_case, TestCase):
                test_class = test_case.id().split('.', 1)[1].split('.')[0]
                err = "This test class should extend from torch.testing._internal.common_utils.TestCase but it doesn't."
                print(f'{test_class} - failed. {err}')
                succeed = False
    return succeed

def to(self, *args, **kwargs) -> ShardedTensor:
    current_device: torch.device
    if self._local_shards:
        current_device = self._local_shards[0].tensor.device
    elif <MASK>:
        current_device = torch.device('cpu')
    else:
        current_device = torch.device(torch.cuda.current_device())
    current_dtype = self.dtype
    device_to = current_device
    dtype_to = current_dtype
    if len(args) == 1:
        if isinstance(args[0], torch.dtype):
            dtype_to = args[0]
        elif isinstance(args[0], torch.device):
            device_to = args[0]
        elif isinstance(args[0], (str, int)):
            device_to = torch.device(args[0])
        elif isinstance(args[0], torch.Tensor):
            dtype_to = args[0].dtype
            device_to = args[0].device
        else:
            raise RuntimeError(f'ShardedTensor.to() have wrong arguments: {args}')
    elif len(args) == 2:
        (device_to, dtype_to) = args
    else:
        dtype_to = kwargs.get('dtype', current_dtype)
        device_to = kwargs.get('device', current_device)
    device_to = torch.device(device_to) if isinstance(device_to, (str, int)) else device_to
    if device_to.type == 'cuda':
        current_idx = torch.cuda.current_device()
        if device_to.index != current_idx:
            warnings.warn('ShardedTensor.to only move tensor to its current deviceIf you want to put to different device, use `reshard` instead.')
        device_to = torch.device(current_idx)
    copy_tensor = kwargs.get('copy', False)
    non_blocking = kwargs.get('non_blocking', False)
    memory_format = kwargs.get('memory_format', torch.preserve_format)
    process_group = kwargs.get('process_group')
    if not copy_tensor and dtype_to == current_dtype and (device_to == current_device):
        return self
    list_shards: list[Shard] = []
    for shard in self._local_shards:
        new_tensor = shard.tensor.to(device=device_to, dtype=dtype_to, non_blocking=non_blocking, copy=copy_tensor, memory_format=memory_format)
        metadata = copy.deepcopy(shard.metadata)
        if metadata.placement is not None:
            metadata.placement._device = device_to
        list_shards.append(Shard(new_tensor, metadata))
    st_meta = copy.deepcopy(self.metadata())
    st_meta.tensor_properties.dtype = dtype_to
    for meta in st_meta.shards_metadata:
        meta.placement._device = device_to
    pg = self._process_group if process_group is None else process_group
    st_to = ShardedTensor._init_from_local_shards_and_global_metadata(list_shards, sharded_tensor_metadata=st_meta, process_group=pg, init_rrefs=self._init_rrefs)
    return st_to

