def should_load(self, proto):
    """Checks if this object should load the SavedUserObject `proto`."""
    if proto.identifier != self.identifier:
        return False
    if self.version < proto.version.min_consumer:
        return False
    if proto.version.producer < self._min_producer_version:
        return False
    for bad_version in proto.version.bad_consumers:
        if <MASK>:
            return False
    return True

@parameterized.parameters(testing.parameter_combinations([{'bias_fn': (None, nn_ops.bias_add), 'activation_fn': (None, nn_ops.relu, nn_ops.relu6), 'dim_sizes': (([None, 1024], [1024, 3]), ([1, 1024], [1024, 3]), ([10, 1, 1024], [10, 1024, 3]), ([2, 3, 1, 1024], [2, 3, 1024, 3])), 'merge_fusion_with_dequantize': (False, True)}]))
@test_util.run_in_graph_and_eager_modes
def test_matmul_ptq_model(self, bias_fn: Optional[ops.Operation], activation_fn: Optional[ops.Operation], dim_sizes: Sequence[int], merge_fusion_with_dequantize: bool):
    (lhs_dim_size, rhs_dim_size) = dim_sizes
    input_shape = (*lhs_dim_size,)
    filter_shape = (*rhs_dim_size,)
    static_input_shape = [dim if dim is not None else 2 for dim in input_shape]
    model = self._create_matmul_model(input_shape, filter_shape, self._input_saved_model_path, bias_fn, activation_fn)
    rng = np.random.default_rng(seed=42)
    input_data = ops.convert_to_tensor(rng.uniform(low=0.0, high=1.0, size=static_input_shape).astype(np.float32))

    def data_gen() -> repr_dataset.RepresentativeDataset:
        for _ in range(100):
            yield {'input_tensor': rng.uniform(low=0.0, high=1.0, size=static_input_shape).astype(np.float32)}
    dataset_path = self.create_tempfile('tfrecord').full_path
    path_map = {'serving_default': dataset_path}
    repr_dataset.TfRecordRepresentativeDatasetSaver(path_map).save({'serving_default': data_gen()})
    config = qc.QuantizationConfig(static_range_ptq_preset=qc.StaticRangePtqPreset(representative_datasets=[qc.RepresentativeDatasetConfig(tf_record=qc.TfRecordFile(path=dataset_path))]), tf_saved_model=qc.TfSavedModelConfig(tags=[tag_constants.SERVING]), pipeline_config=qc.PipelineConfig(merge_fusion_with_dequantize=merge_fusion_with_dequantize))
    quantization.quantize_saved_model(self._input_saved_model_path, self._output_saved_model_path, config)
    expected_outputs = model.matmul(input_data)
    root = load.load(self._output_saved_model_path)
    self.assertCountEqual(root.signatures.keys(), {'serving_default'})
    new_outputs = root.signatures['serving_default'](input_tensor=ops.convert_to_tensor(input_data))
    module_str = self._extract_first_xla_call_module_op(self._output_saved_model_path)
    self.assertTrue(re.search('stablehlo.dot_general.*xi8>', module_str))
    if bias_fn:
        self.assertTrue(re.search('stablehlo.add.*xi32>', module_str))
    self.assertAllClose(new_outputs, expected_outputs, rtol=0.3, atol=0.2)
    self.assertLess(testing.get_size_ratio(self._output_saved_model_path, self._input_saved_model_path), 0.65)
    if <MASK>:
        if activation_fn is nn_ops.relu6:
            self.assertRegex(module_str, 'stablehlo.clamp.*\\n.*return')
        elif activation_fn is nn_ops.relu:
            self.assertRegex(module_str, 'stablehlo.maximum.*\\n.*return')
    else:
        self.assertNotRegex(module_str, 'stablehlo.clamp.*\\n.*return')
        self.assertNotRegex(module_str, 'stablehlo.maximum.*\\n.*return')

def add(import_name: str) -> None:
    if isinstance(import_name, types.ModuleType):
        return add(import_name.__name__)
    assert isinstance(import_name, str)
    from importlib.util import find_spec
    module_spec = find_spec(import_name)
    if <MASK>:
        return
    origin = module_spec.origin
    if origin is None:
        return
    SKIP_DIRS.append(_strip_init_py(origin))
    _recompile_re()

