def pack_eager_tensors(tensors, ctx=None) -> EagerTensor:
    """Pack multiple `EagerTensor`s of the same dtype and shape.

  Args:
    tensors: a list of EagerTensors to pack.
    ctx: context.context().

  Returns:
    A packed EagerTensor.
  """
    if <MASK>:
        raise TypeError(f'tensors must be a list, but got a {type(tensors)}')
    if not tensors:
        raise ValueError('Cannot pack an empty list of tensors.')
    dtype = tensors[0].dtype
    shape = tensors[0].shape
    handle_data = tensors[0]._handle_data
    is_resource = dtype == dtypes.resource
    for i in range(len(tensors)):
        t = tensors[i]
        if not isinstance(t, EagerTensor):
            raise TypeError(f'All tensors being packed must be EagerTensor. Found an item of type {type(t)}.')
        if t.dtype != dtype:
            raise ValueError(f'All tensors being packed should have the same dtype {dtype}, but the {i}-th tensor is of dtype {t.dtype}')
        if t.shape != shape:
            raise ValueError(f'All tensors being packed should have the same shape {shape}, but the {i}-th tensor is of shape {t.shape}')
        if is_resource and t._handle_data != handle_data:
            raise ValueError(f'All tensors being packed should have the same handle data {handle_data}, but the {i}-th tensor is of handle data {t._handle_data}')
    if ctx is None:
        ctx = context.context()
    packed_tensor = ctx.pack_eager_tensors(tensors)
    if handle_data is not None:
        packed_tensor._handle_data = handle_data

    def grad_fun(_):
        raise ValueError('Computing gradients through pack_eager_tensors is not supported.')
    record.record_operation('pack_eager_tensors', [packed_tensor], tensors, grad_fun)
    return packed_tensor

def actual_grad_fn(*result_grad_components):
    """Custom grad fn wrapper."""
    result_grads = composite_tensor_gradient.replace_flat_tensors_for_gradients(nest.flatten(result), result_grad_components)
    if not isinstance(result_grads, (list, tuple)):
        result_grads = [result_grads]
    if <MASK>:
        (input_grads, variable_grads) = grad_fn(*result_grads, variables=variables)
        if len(variable_grads) != len(variables):
            raise ValueError('Must return gradient for each variable from @custom_gradient grad_fn.')
    else:
        input_grads = grad_fn(*result_grads)
        variable_grads = []
    flat_grads = composite_tensor_gradient.get_flat_tensors_for_gradients(nest.flatten(input_grads))
    if len(flat_grads) != arg_count:
        raise ValueError(f'custom_gradient function expected to return {arg_count} gradients, but returned {len(flat_grads)} instead.')
    return flat_grads + variable_grads

def to_ast(self):
    assert self._finalized
    if <MASK>:
        result = self._argspec[0]
        for i in range(1, len(self._argspec)):
            result = gast.BinOp(result, gast.Add(), self._argspec[i])
        return result
    return gast.Tuple([], gast.Load())

def _toDataType(self, dtype):
    """Returns TensorFlow data type for numpy type."""
    if dtype == np.float32:
        return dtypes.float32
    elif dtype == np.float64:
        return dtypes.float64
    elif dtype == np.int32:
        return dtypes.int32
    elif dtype == np.int64:
        return dtypes.int64
    elif dtype == np.bool_:
        return dtypes.bool
    elif dtype == np.complex64:
        return dtypes.complex64
    elif <MASK>:
        return dtypes.complex128
    else:
        return None

@register_decomposition(aten.masked_fill)
@out_wrapper()
def masked_fill(a: TensorLikeType, mask: TensorLikeType, value: TensorOrNumberLikeType):
    python_type = utils.dtype_to_type(a.dtype)
    if isinstance(value, Number):
        value_type = type(value)
    else:
        value_ndim = value.ndim
        torch._check(value_ndim == 0, lambda : f'only supports a 0-dimensional value tensor, but got tensor with {value_ndim} dimension')
        is_cpu_scalar = a.device.type in ['cuda', 'xpu', 'mps', torch._C._get_privateuse1_backend_name(), 'hpu'] and value.device.type == 'cpu'
        torch._check(is_cpu_scalar or value.device == a.device, lambda : 'Expected `value` to be on same device as `a`')
        value_type = utils.dtype_to_type(value.dtype)
    if <MASK>:
        torch._check(utils.is_weakly_lesser_type(value_type, python_type), lambda : f'could not convert to type {python_type} without overflow')
    value = _maybe_convert_to_dtype(value, a.dtype)
    r = torch.where(mask, value, a)
    return r.contiguous()

def get_redirects(redirects_filename):
    """Parse the redirections and build a transitively closed map out of it"""
    redirects = {}
    print('Parsing the NT redirect file')
    for (l, line) in enumerate(BZ2File(redirects_filename)):
        split = line.split()
        if len(split) != 4:
            print('ignoring malformed line: ' + line)
            continue
        redirects[short_name(split[0])] = short_name(split[2])
        if <MASK>:
            print('[%s] line: %08d' % (datetime.now().isoformat(), l))
    print('Computing the transitive closure of the redirect relation')
    for (l, source) in enumerate(redirects.keys()):
        transitive_target = None
        target = redirects[source]
        seen = {source}
        while True:
            transitive_target = target
            target = redirects.get(target)
            if target is None or target in seen:
                break
            seen.add(target)
        redirects[source] = transitive_target
        if l % 1000000 == 0:
            print('[%s] line: %08d' % (datetime.now().isoformat(), l))
    return redirects

