            line = line[:-1] + ' '
        line += str(fields[i])
        line = line[:positions[i]]
        line += ' ' * (positions[i] - len(line))
    print_fn(line)

def _get_dtype_and_weakness(x):
    """Returns a TF type and weak type information from x.

  Args:
    x: an input scalar, array or a NumPy/TF/Python dtype.

  Raises:
    OverflowError: if Python int x is too large to convert to int32.
    NotImplementedError: when x is an unsupported input type.

  Returns:
    TF type and weak type information inferred from x in the form of
    (dtype, bool).
  """
    if isinstance(x, weak_tensor.WeakTensor):
        return (x.dtype, True)
    if isinstance(x, dtypes.DType):
        return (x, False)
    tf_dtype = getattr(x, 'dtype', None)
    if isinstance(tf_dtype, dtypes.DType):
        return (tf_dtype, False)
    if isinstance(x, (np.ndarray, np.generic)) or isinstance(tf_dtype, np.dtype):
        infer_dtype = dtypes.as_dtype(tf_dtype)
        return (infer_dtype, False)
    if isinstance(x, (bytes, str)) or tf_dtype in _all_str_dtypes:
        return _str
    try:
        if x in _NP_TO_TF:
            return (_NP_TO_TF[x], False)
    except TypeError:
        pass
    if isinstance(x, bool) or x == bool:
        return _b8
    if isinstance(x, _pi):
        if x < np.iinfo(np.int32).min or x > np.iinfo(np.int32).max:
            raise OverflowError(f'Python int {x} too large to convert to np.int32')
        return _i32w
    if x == int:
        return _i32w
    if isinstance(x, _pf) or x == float:
        return _f32w
    if <MASK>:
        return _c128w
    if isinstance(x, tensor_shape.TensorShape):
        return _i32
    if isinstance(x, np.dtype):
        try:
            np_dtype = dtypes.as_dtype(x)
            return (np_dtype, False)
        except TypeError as exc:
            raise NotImplementedError(f'Auto dtype conversion semantics does not support {x}. Try using a NumPy built-in dtype objects or cast them explicitly.') from exc
    raise NotImplementedError(f'Auto dtype conversion semantics does not support {type(x)} type.')

def is_action_ready(action: _Action, timestep: int) -> bool:
    """Check if an action is ready to be scheduled at the given timestep."""
    if action.computation_type in (_ComputationType.FULL_BACKWARD, _ComputationType.BACKWARD_INPUT, _ComputationType.BACKWARD_WEIGHT):
        dependencies = get_dependencies(action)
        return any((is_dependency_ready(dep, timestep) for dep in dependencies))
    elif <MASK>:
        dependencies = get_dependencies(action)
        return all((is_dependency_ready(dep, timestep) for dep in dependencies))
    elif action.computation_type == _ComputationType.OVERLAP_F_B:
        assert action.sub_actions is not None, f'OVERLAP_F_B action {action} has None sub_actions'
        dep_list: list[bool] = []
        for sub_action in action.sub_actions:
            dep_list.append(is_action_ready(sub_action, timestep))
        return all(dep_list)
    else:
        raise RuntimeError(f'Unknown computation type: {action.computation_type}')

def _worker_loop(dataset_kind, dataset, index_queue, data_queue, done_event, auto_collation, collate_fn, drop_last, base_seed, init_fn, worker_id, num_workers, persistent_workers, shared_seed):
    try:
        signal_handling._set_worker_signal_handlers()
        torch.multiprocessing._set_thread_name('pt_data_worker')
        torch.set_num_threads(1)
        seed = base_seed + worker_id
        random.seed(seed)
        torch.manual_seed(seed)
        if HAS_NUMPY:
            np_seed = _generate_state(base_seed, worker_id)
            import numpy as np
            np.random.seed(np_seed)
        from torch.utils.data import IterDataPipe
        from torch.utils.data.graph_settings import apply_random_seed
        shared_rng = torch.Generator()
        if <MASK>:
            if shared_seed is None:
                raise AssertionError('shared_seed must be provided for IterDataPipe workers')
            shared_rng.manual_seed(shared_seed)
            dataset = apply_random_seed(dataset, shared_rng)
        global _worker_info
        _worker_info = WorkerInfo(id=worker_id, num_workers=num_workers, seed=seed, dataset=dataset)
        from torch.utils.data import _DatasetKind
        init_exception = None
        try:
            if init_fn is not None:
                init_fn(worker_id)
            fetcher = _DatasetKind.create_fetcher(dataset_kind, dataset, auto_collation, collate_fn, drop_last)
        except Exception:
            init_exception = ExceptionWrapper(where=f'in DataLoader worker process {worker_id}')
        iteration_end = False
        watchdog = ManagerWatchdog()
        while watchdog.is_alive():
            try:
                r = index_queue.get(timeout=MP_STATUS_CHECK_INTERVAL)
            except queue.Empty:
                continue
            if isinstance(r, _ResumeIteration):
                data_queue.put((r, None))
                iteration_end = False
                if isinstance(dataset, IterDataPipe):
                    if r.seed is None:
                        raise AssertionError('resume iteration seed is None for IterDataPipe')
                    shared_rng.manual_seed(r.seed)
                    dataset = apply_random_seed(dataset, shared_rng)
                fetcher = _DatasetKind.create_fetcher(dataset_kind, dataset, auto_collation, collate_fn, drop_last)
                continue
            elif r is None:
                if not done_event.is_set() and (not iteration_end):
                    raise AssertionError('Received final signal but neither done_event nor iteration_end is set')
                break
            elif done_event.is_set() or iteration_end:
                continue
            (idx, index) = r
            data: Union[_IterableDatasetStopIteration, ExceptionWrapper]
            if init_exception is not None:
                data = init_exception
                init_exception = None
            else:
                try:
                    data = fetcher.fetch(index)
                except Exception as e:
                    if isinstance(e, StopIteration) and dataset_kind == _DatasetKind.Iterable:
                        data = _IterableDatasetStopIteration(worker_id)
                        iteration_end = True
                    else:
                        data = ExceptionWrapper(where=f'in DataLoader worker process {worker_id}')
            data_queue.put((idx, data))
            del data, idx, index, r
    except KeyboardInterrupt:
        pass
    if done_event.is_set():
        data_queue.cancel_join_thread()
        data_queue.close()

