@deco_stream
@normalizer
def choice(a: ArrayLike, size=None, replace=True, p: Optional[ArrayLike]=None):
    if a.numel() == 1:
        a = torch.arange(a)
    if <MASK>:
        num_el = 1
    elif _util.is_sequence(size):
        num_el = 1
        for el in size:
            num_el *= el
    else:
        num_el = size
    if p is None:
        p = torch.ones_like(a) / a.shape[0]
    atol = sqrt(torch.finfo(p.dtype).eps)
    if abs(p.sum() - 1.0) > atol:
        raise ValueError('probabilities do not sum to 1.')
    indices = torch.multinomial(p, num_el, replacement=replace)
    if _util.is_sequence(size):
        indices = indices.reshape(size)
    samples = a[indices]
    return samples

@staticmethod
def decide_layout_opt(gm: GraphModule, *, is_inference: bool) -> bool:
    """
        Decide if we should enable layout optimization for this graph based on
        heuristics.
        """
    if not config.layout_optimization:
        return False
    if config.force_layout_optimization:
        return True
    conv_nodes = [n for n in gm.graph.nodes if n.target == torch.ops.aten.convolution.default]
    nconv = len(conv_nodes)
    if nconv == 0:
        return False
    if torch.backends.mkldnn.enabled and torch.backends.mkldnn.is_available() and all((n.args[idx].meta['val'].device.type in SUPPORTED_MKLDNN_DEVICES for n in conv_nodes for idx in [0, 1])):
        return True
    if len(list(gm.graph.nodes)) >= 300 * nconv:
        log.debug('Skipped layout opt because only a few conv')
        return False
    if any((has_free_symbols(n.args[idx].meta['val']) for n in conv_nodes for idx in [0, 1])):
        log.debug('See perf regression with dynamic shape. Follow up in https://github.com/pytorch/pytorch/issues/102670')
        return False

    def is_grouped(n: Any) -> bool:
        meta_val = n.args[1].meta['val']
        assert isinstance(meta_val, torch.Tensor)
        return n.args[-1] > 1 and meta_val.size(1) > 1

    def is_in_out_channel(n: torch.fx.Node) -> bool:
        return n.args[1].meta['val'].size(0) * 2 <= n.args[1].meta['val'].size(1) and n.args[1].meta['val'].size(2) > 1

    def is_small_channel(n: torch.fx.Node) -> bool:
        return n.args[1].meta['val'].size(0) <= 64 and n.args[1].meta['val'].size(1) <= 64
    if is_inference:
        flop_counts: dict[str, float] = defaultdict(float)
        for node in conv_nodes:
            counted_flops = count_flops_fx(node)
            if counted_flops is None:
                continue
            if is_grouped(node):
                node_type = 'grouped'
            elif is_small_channel(node):
                node_type = 'small'
            elif is_in_out_channel(node):
                node_type = 'in_out'
            else:
                node_type = 'default'
            flop_counts[node_type] += counted_flops
        else:
            log.debug('Conv inputs meta not found')
        GROUPED_MULTIPLIER = 1.358
        DEFAULT_MULTIPLIER = 0.823
        IN_OUT_MULTIPLIER = 0.725
        SMALL_MULTIPLIER = 0.783
        total_flops = sum(flop_counts.values())
        weighted_flops = flop_counts['grouped'] * GROUPED_MULTIPLIER + flop_counts['small'] * SMALL_MULTIPLIER + flop_counts['in_out'] * IN_OUT_MULTIPLIER + flop_counts['default'] * DEFAULT_MULTIPLIER
        do_layout_opt = weighted_flops <= total_flops
        if not do_layout_opt:
            log.debug('Skipped layout opt in inference because weighted flops indicate slowdown, default: %d, channels last: %d', total_flops, weighted_flops)
        return do_layout_opt
    if any(map(is_grouped, conv_nodes)):
        log.debug('Skip layout opt because found grouped convolution with >1 in_channels!')
        return False
    if <MASK>:
        log.debug('Skip layout opt because some convolutions have smaller out_channel')
        return False
    if all(map(is_small_channel, conv_nodes)):
        log.debug('Skip layout opt because all convolution channels are too small')
        return False
    return True

def _single_tensor_adamax(params: list[Tensor], grads: list[Tensor], exp_avgs: list[Tensor], exp_infs: list[Tensor], state_steps: list[Tensor], *, eps: float, beta1: float, beta2: float, lr: float, weight_decay: float, maximize: bool, differentiable: bool, capturable: bool, has_complex: bool):
    if not torch.jit.is_scripting():
        lr = _to_scalar(lr)
    for (i, param) in enumerate(params):
        grad = grads[i]
        grad = grad if not maximize else -grad
        exp_avg = exp_avgs[i]
        exp_inf = exp_infs[i]
        step_t = state_steps[i]
        if not torch.compiler.is_compiling() and capturable:
            capturable_supported_devices = _get_capturable_supported_devices()
            if not (param.device.type == step_t.device.type and param.device.type in capturable_supported_devices):
                raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
        step_t += 1
        if <MASK>:
            grad = grad.add(param, alpha=weight_decay)
        if torch.is_complex(param):
            param = torch.view_as_real(param)
            grad = torch.view_as_real(grad)
            exp_avg = torch.view_as_real(exp_avg)
            exp_inf = torch.view_as_real(exp_inf)
        exp_avg.lerp_(grad, 1 - beta1)
        if not differentiable:
            torch.maximum(exp_inf.mul_(beta2), grad.abs().add_(eps), out=exp_inf)
        else:
            norm_buf = torch.cat([exp_inf.mul_(beta2).unsqueeze(0), grad.abs().add_(eps).unsqueeze_(0)], 0)
            exp_inf.copy_(torch.amax(norm_buf, 0, keepdim=False))
        if capturable:
            neg_bias_correction = beta1 ** step_t - 1
            neg_bias_correction.div_(lr)
            denom = exp_inf * neg_bias_correction
            param.addcdiv_(exp_avg, denom)
        else:
            bias_correction = 1 - beta1 ** _get_value(step_t)
            clr = lr / bias_correction
            param.addcdiv_(exp_avg, exp_inf, value=-clr)

def helper(treespec: TreeSpec, tree: PyTree, subtrees: list[PyTree]) -> None:
    if treespec.is_leaf():
        subtrees.append(tree)
        return
    node_type = _get_node_type(tree)
    if treespec.type not in BUILTIN_TYPES:
        if node_type != treespec.type:
            raise ValueError(f'Type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
        (children, context) = flatten_fn(tree)
        if len(children) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(children)}.')
        if context != treespec.context:
            raise ValueError(f'Node context mismatch for custom node type {treespec.type!r}.')
    else:
        both_standard_dict = treespec.type in STANDARD_DICT_TYPES and node_type in STANDARD_DICT_TYPES
        if not both_standard_dict and node_type != treespec.type:
            raise ValueError(f'Node type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        if len(tree) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(tree)}.')
        if <MASK>:
            dict_context = treespec.context if treespec.type is not defaultdict else treespec.context[1]
            expected_keys = dict_context
            got_key_set = set(tree)
            expected_key_set = set(expected_keys)
            if got_key_set != expected_key_set:
                missing_keys = expected_key_set.difference(got_key_set)
                extra_keys = got_key_set.difference(expected_key_set)
                message = ''
                if missing_keys:
                    message += f'; missing key(s): {missing_keys}'
                if extra_keys:
                    message += f'; extra key(s): {extra_keys}'
                raise ValueError(f'Node keys mismatch{message}.')
            children = [tree[key] for key in expected_keys]
        else:
            flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
            (children, context) = flatten_fn(tree)
            if node_type is not deque and context != treespec.context:
                raise ValueError(f'Node context mismatch for node type {treespec.type!r}; expected {treespec.context!r}, but got {context!r}.')
    for (subtree, subspec) in zip(children, treespec.children_specs):
        helper(subspec, subtree, subtrees)

def SEQUENCE_LENGTH(self, guard: Guard) -> None:
    ref = self.arg_ref(guard)
