def __getattribute__(self, name):
    """Un-wrap `_NumpyWrapper` objects when accessing attributes."""
    try:
        arrays = super(_NumpyState, self).__getattribute__('_arrays')
    except AttributeError:
        return super(_NumpyState, self).__getattribute__(name)
    try:
        value = getattr(arrays, name)
    except AttributeError:
        dummy_array = numpy.array([])
        setattr(arrays, name, _NumpyWrapper(dummy_array))
        value = getattr(arrays, name)
        if value.array is dummy_array:
            delattr(arrays, name)
            return super(_NumpyState, self).__getattribute__(name)
    if <MASK>:
        return value.array
    return super(_NumpyState, self).__getattribute__(name)

def _can_fast_union(self, other: Self) -> bool:
    freq = self.freq
    if freq is None or freq != other.freq:
        return False
    if not self.is_monotonic_increasing:
        return False
    if len(self) == 0 or len(other) == 0:
        return True
    if <MASK>:
        (left, right) = (self, other)
    else:
        (left, right) = (other, self)
    right_start = right[0]
    left_end = left[-1]
    return right_start == left_end + freq or right_start in left

def __init__(self, probs: Optional[Union[Tensor, Number]]=None, logits: Optional[Union[Tensor, Number]]=None, validate_args: Optional[bool]=None) -> None:
    if (probs is None) == (logits is None):
        raise ValueError('Either `probs` or `logits` must be specified, but not both.')
    if probs is not None:
        (self.probs,) = broadcast_all(probs)
    else:
        assert logits is not None
        (self.logits,) = broadcast_all(logits)
    probs_or_logits = probs if probs is not None else logits
    if <MASK>:
        batch_shape = torch.Size()
    else:
        assert probs_or_logits is not None
        batch_shape = probs_or_logits.size()
    super().__init__(batch_shape, validate_args=validate_args)
    if self._validate_args and probs is not None:
        value = self.probs
        valid = value > 0
        if not valid.all():
            invalid_value = value.data[~valid]
            raise ValueError(f'Expected parameter probs ({type(value).__name__} of shape {tuple(value.shape)}) of distribution {repr(self)} to be positive but found invalid values:\n{invalid_value}')

