def _recursive_maybe_replace_node_with_obs(maybe_node: Argument, model: torch.nn.Module, named_modules: dict[str, torch.nn.Module], graph: Graph) -> Argument:
    """
        Navigate an arbitrary data structure of lists, tuples, dicts.
        For each container type, recurse on all inputs. Once any Node
        is found, insert an observer if needed and do not recurse further.

        For example, given a structure of

          {'foo1': [[bar1]], 'foo2': {'foo3': [[[bar3]]]}}

        we recurse down to bar1 and bar3, observe them if necessary,
        and if we inserted an observer then replace the original node
        with its observer.

        Returns the data structure with all nodes needing observation being
        replaced by their observers.
        """
    if isinstance(maybe_node, Node):
        arg_as_output_target_dtype = _get_arg_target_dtype_as_output(maybe_node, named_modules, obs_or_fq_map, is_qat)
        observer_mod = None
        arg_as_input_target_dtype = torch.float
        if 'target_dtype_info' in maybe_node.meta:
            observer_cls = maybe_node.meta['target_dtype_info'].get('input_act_obs_or_fq_ctr', None)
            if observer_cls is not None:
                observer_mod = observer_cls()
                arg_as_input_target_dtype = observer_mod.dtype
        need_obs = arg_as_output_target_dtype != arg_as_input_target_dtype and arg_as_input_target_dtype != torch.float
        if need_obs:
            assert observer_mod is not None
            observer_node = _insert_obs_or_fq(maybe_node, observer_mod, model, named_modules, graph)
            return observer_node
        else:
            return maybe_node
    elif <MASK>:
        results = [_recursive_maybe_replace_node_with_obs(inner_node, model, named_modules, graph) for inner_node in maybe_node]
        if isinstance(maybe_node, list):
            return results
        else:
            return tuple(results)
    elif isinstance(maybe_node, dict):
        results_dict = {}
        for (k, inner_v) in maybe_node.items():
            results_dict[k] = _recursive_maybe_replace_node_with_obs(inner_v, model, named_modules, graph)
        return results_dict
    elif maybe_node is None:
        return None
    else:
        raise Exception('Unhandled type for returned node:', maybe_node)

def __str__(self):
    if <MASK>:
        output = ['%s\n\nOriginal stack trace for %r:\n' % (self.message, self._op.name)]
        curr_traceback_list = traceback.format_list(self._op.traceback or [])
        output.extend(curr_traceback_list)
        original_op = self._op._original_op
        while original_op is not None:
            output.append('\n...which was originally created as op %r, defined at:\n' % (original_op.name,))
            prev_traceback_list = curr_traceback_list
            curr_traceback_list = traceback.format_list(original_op.traceback or [])
            is_eliding = False
            elide_count = 0
            last_elided_line = None
            for (line, line_in_prev) in zip(curr_traceback_list, prev_traceback_list):
                if line == line_in_prev:
                    if is_eliding:
                        elide_count += 1
                        last_elided_line = line
                    else:
                        output.append(line)
                        is_eliding = True
                        elide_count = 0
                else:
                    if is_eliding:
                        if elide_count > 0:
                            output.extend(['[elided %d identical lines from previous traceback]\n' % (elide_count - 1,), last_elided_line])
                        is_eliding = False
                    output.extend(line)
            original_op = original_op._original_op
        return ''.join(output)
    else:
        return self.message

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if <MASK>:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif name == 'extend' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
        if isinstance(idx, SymNodeVariable):
            const_idx = idx.evaluate_expr()
        else:
            const_idx = idx.as_python_constant()
        tx.output.side_effects.mutation(self)
        self.items.insert(const_idx, value)
        return ConstantVariable.create(None)
    elif name == 'pop' and self.is_mutable():
        if kwargs or len(args) > 1:
            raise_args_mismatch(tx, name, 'at most 1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if len(self.items) == 0:
            msg = ConstantVariable.create('pop from empty list')
            raise_observed_exception(IndexError, tx, args=[msg])
        if len(args):
            idx = args[0].as_python_constant()
            if idx > len(self.items):
                msg = ConstantVariable.create('pop index out of range')
                raise_observed_exception(IndexError, tx, args=[msg])
        tx.output.side_effects.mutation(self)
        return self.items.pop(*[a.as_python_constant() for a in args])
    elif name == 'clear' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        self.items.clear()
        return ConstantVariable.create(None)
    elif name == '__setitem__' and self.is_mutable() and args and (args[0].is_python_constant() or isinstance(args[0], SymNodeVariable) or (isinstance(args[0], SliceVariable) and all((s.is_python_constant() or isinstance(s, SymNodeVariable) for s in args[0].items)))):
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        (key, value) = args
        tx.output.side_effects.mutation(self)
        if isinstance(key, SymNodeVariable):
            self.items[key.evaluate_expr()] = value
        elif isinstance(key, SliceVariable):
            if key.is_python_constant():
                self.items[key.as_python_constant()] = list(value.items)
            else:
                items = slice(*[s.evaluate_expr() if isinstance(s, SymNodeVariable) else s.as_python_constant() for s in key.items])
                self.items[items] = list(value.items)
        else:
            self.items[key.as_python_constant()] = value
        return ConstantVariable.create(None)
    elif name == '__delitem__' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        if args[0].is_python_constant() and isinstance(args[0].as_python_constant(), (int, slice)):
            if isinstance(args[0], SymNodeVariable):
                idx = args[0].evaluate_expr()
            else:
                idx = args[0].as_python_constant()
            try:
                self.items.__delitem__(idx)
            except (IndexError, ValueError) as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            msg = ConstantVariable.create(f'list indices must be integers or slices, not {args[0].python_type_name()}')
            raise_observed_exception(TypeError, tx, args=[msg])
        return ConstantVariable.create(None)
    elif name == 'copy':
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        items = list(self.items)
        return self.modified(items, mutation_type=ValueMutationNew())
    elif name == 'reverse' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        self.items.reverse()
        tx.output.side_effects.mutation(self)
        return ConstantVariable.create(None)
    elif name == 'remove' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        idx = self.call_method(tx, 'index', args, kwargs)
        self.call_method(tx, 'pop', [idx], {})
        return ConstantVariable.create(None)
    else:
        return super().call_method(tx, name, args, kwargs)

def _check_can_register_backward(self):

    def error(detail):
        raise RuntimeError(f'Cannot use torch._custom_ops APIs to register backward formula for {detail}. Got operator {self._qualname} with schema: {schema}')
    schema = self._schema
    if <MASK>:
        error('non-functional operator')
    rets = schema.returns
    if not schema.returns:
        error('operator with no returns')
    assert len(rets) > 0
    is_non_mutating_view = any((r.annotation is not None and (not r.annotation.is_write) for r in rets))
    if is_non_mutating_view:
        error('operator that returns views')
    allowed_return_types = {BaseType(BaseTy.int): 'int', BaseType(BaseTy.SymInt): 'SymInt', BaseType(BaseTy.bool): 'bool', BaseType(BaseTy.float): 'float', BaseType(BaseTy.Tensor): 'Tensor', ListType(BaseType(BaseTy.Tensor), None): 'List[Tensor]'}
    for ret in schema.returns:
        if ret.type in allowed_return_types:
            continue
        error(f'operator with return not in {list(allowed_return_types.values())} (got {ret.type})')

