    """
    if not isinstance(actual, torch.Tensor):
        actual = torch.tensor(actual)
    if <MASK>:
        expected = torch.tensor(expected, dtype=actual.dtype)
    if rtol is None and atol is None:
        (rtol, atol) = default_tolerances(actual, expected, dtype_precisions={torch.float16: (0.001, 0.001), torch.float32: (0.0001, 1e-05), torch.float64: (1e-05, 1e-08)})
    torch.testing.assert_close(actual, expected, rtol=rtol, atol=atol, equal_nan=equal_nan, check_device=True, check_dtype=False, check_stride=False, msg=msg or None)

def _get_file_writer(self):
    """Return the default FileWriter instance. Recreates it if closed."""
    if self.all_writers is None or self.file_writer is None:
        self.file_writer = FileWriter(self.log_dir, self.max_queue, self.flush_secs, self.filename_suffix)
        self.all_writers = {self.file_writer.get_logdir(): self.file_writer}
        if <MASK>:
            most_recent_step = self.purge_step
            self.file_writer.add_event(Event(step=most_recent_step, file_version='brain.Event:2'))
            self.file_writer.add_event(Event(step=most_recent_step, session_log=SessionLog(status=SessionLog.START)))
            self.purge_step = None
    return self.file_writer

@test_util.run_in_graph_and_eager_modes
def testUniformVariance(self):
    a = 10.0
    b = 100.0
    uniform = uniform_lib.Uniform(low=a, high=b)
    if <MASK>:
        return
    s_uniform = stats.uniform(loc=a, scale=b - a)
    self.assertAllClose(self.evaluate(uniform.variance()), s_uniform.var())

def should_ban_recomputation(node):
    if node.op != 'call_function':
        return False
    if node.target == operator.getitem:
        return False
    if node.meta.get('recompute', None) == CheckpointPolicy.MUST_SAVE:
        return True
    if config.recompute_views and op_types.is_view(node):
        return False
    if node.target in [aten.lift_fresh_copy.default, aten.lift_fresh.default]:
        return False
    if <MASK>:
        if not op_types.is_recomputable(node):
            return True
    elif op_types.is_random(node) or op_types.is_compute_intensive(node):
        return True
    if min_cut_options.ban_if_materialized_backward and is_materialized_backwards(node):
        log.debug('materialized backwards: %s %s', node, tuple(node.users))
        return True
    if node.dist_from_bw < 1000 and node.dist_from_bw > config.max_dist_from_bw:
        return True
    if min_cut_options.ban_if_reduction:
        input_tensors_size = sum((_size_of(i) for i in node.args if isinstance(i, fx.Node)))
        output_size = _size_of(node)
        return output_size * 4 < input_tensors_size
    return False

def symbol_is_type(sym: sympy.Basic, prefix: Union[SymT, Iterable[SymT]]) -> bool:
    if <MASK>:
        raise AssertionError('expected sympy.Symbol')
    name_str = sym.name.lower()
    if isinstance(prefix, SymT):
        return name_str.startswith(prefix_str[prefix])
    else:
        return name_str.startswith(tuple((prefix_str[p] for p in prefix)))

def _reverse_with_prefix(self, lookup_view, _prefix, *args, **kwargs):
    if args and kwargs:
        raise ValueError("Don't mix *args and **kwargs in call to reverse()!")
    if not self._populated:
        self._populate()
    possibilities = self.reverse_dict.getlist(lookup_view)
    for (possibility, pattern, defaults, converters) in possibilities:
        for (result, params) in possibility:
            if args:
                if len(args) != len(params):
                    continue
                candidate_subs = dict(zip(params, args))
            else:
                if set(kwargs).symmetric_difference(params).difference(defaults):
                    continue
                matches = True
                for (k, v) in defaults.items():
                    if k in params:
                        continue
                    if kwargs.get(k, v) != v:
                        matches = False
                        break
                if not matches:
                    continue
                candidate_subs = kwargs
            text_candidate_subs = {}
            match = True
            for (k, v) in candidate_subs.items():
                if k in converters:
                    try:
                        text_candidate_subs[k] = converters[k].to_url(v)
                    except ValueError:
                        match = False
                        break
                else:
                    text_candidate_subs[k] = str(v)
            if <MASK>:
                continue
            candidate_pat = _prefix.replace('%', '%%') + result
            if re.search('^%s%s' % (re.escape(_prefix), pattern), candidate_pat % text_candidate_subs):
                url = quote(candidate_pat % text_candidate_subs, safe=RFC3986_SUBDELIMS + '/~:@')
                return escape_leading_slashes(url)
    m = getattr(lookup_view, '__module__', None)
    n = getattr(lookup_view, '__name__', None)
    if m is not None and n is not None:
        lookup_view_s = '%s.%s' % (m, n)
    else:
        lookup_view_s = lookup_view
    patterns = [pattern for (_, pattern, _, _) in possibilities]
    if patterns:
        if args:
            arg_msg = "arguments '%s'" % (args,)
        elif kwargs:
            arg_msg = "keyword arguments '%s'" % kwargs
        else:
            arg_msg = 'no arguments'
        msg = "Reverse for '%s' with %s not found. %d pattern(s) tried: %s" % (lookup_view_s, arg_msg, len(patterns), patterns)
    else:
        msg = "Reverse for '%(view)s' not found. '%(view)s' is not a valid view function or pattern name." % {'view': lookup_view_s}
    raise NoReverseMatch(msg)

