def as_factors(obj):
    """Return expression as FACTORS expression.
    """
    if <MASK>:
        obj = normalize(obj)
        if obj.op is Op.FACTORS:
            return obj
        if obj.op is Op.TERMS:
            if len(obj.data) == 1:
                ((term, coeff),) = obj.data.items()
                if coeff == 1:
                    return Expr(Op.FACTORS, {term: 1})
                return Expr(Op.FACTORS, {term: 1, Expr.number(coeff): 1})
        if obj.op is Op.APPLY and obj.data[0] is ArithOp.DIV and (not obj.data[2]):
            return Expr(Op.FACTORS, {obj.data[1][0]: 1, obj.data[1][1]: -1})
        return Expr(Op.FACTORS, {obj: 1})
    raise OpError(f'cannot convert {type(obj)} to terms Expr')

def sample_inputs_unary_dimwise(op_info, device, dtype, requires_grad, op_kwargs=None, **kwargs):
    if <MASK>:
        op_kwargs = {}
    assert op_info._extra_op_data is not None
    (single_dim_argname, dimlist_argname) = op_info._extra_op_data.get_dim_argnames()
    assert single_dim_argname is not None
    assert dimlist_argname is None
    for njt in _sample_njts(device=device, dtype=dtype, requires_grad=requires_grad, dims=[2, 3, 4]):
        for dim in range(njt.dim()):
            kwargs = {single_dim_argname: dim}
            kwargs.update(op_kwargs)
            yield SampleInput(_clone(njt), kwargs=kwargs, name=f'{_describe_njt(njt)}: {_describe_dim(njt, dim)}')

@final
def _maybe_coerce_merge_keys(self) -> None:
    for (lk, rk, name) in zip(self.left_join_keys, self.right_join_keys, self.join_names):
        if len(lk) and (not len(rk)) or (not len(lk) and len(rk)):
            continue
        lk = extract_array(lk, extract_numpy=True)
        rk = extract_array(rk, extract_numpy=True)
        lk_is_cat = isinstance(lk.dtype, CategoricalDtype)
        rk_is_cat = isinstance(rk.dtype, CategoricalDtype)
        lk_is_object_or_string = is_object_dtype(lk.dtype) or is_string_dtype(lk.dtype)
        rk_is_object_or_string = is_object_dtype(rk.dtype) or is_string_dtype(rk.dtype)
        if lk_is_cat and rk_is_cat:
            lk = cast(Categorical, lk)
            rk = cast(Categorical, rk)
            if lk._categories_match_up_to_permutation(rk):
                continue
        elif lk_is_cat or rk_is_cat:
            pass
        elif lk.dtype == rk.dtype:
            continue
        msg = f"You are trying to merge on {lk.dtype} and {rk.dtype} columns for key '{name}'. If you wish to proceed you should use pd.concat"
        if is_numeric_dtype(lk.dtype) and is_numeric_dtype(rk.dtype):
            if lk.dtype.kind == rk.dtype.kind:
                continue
            if isinstance(lk.dtype, ExtensionDtype) and (not isinstance(rk.dtype, ExtensionDtype)):
                ct = find_common_type([lk.dtype, rk.dtype])
                if isinstance(ct, ExtensionDtype):
                    com_cls = ct.construct_array_type()
                    rk = com_cls._from_sequence(rk, dtype=ct, copy=False)
                else:
                    rk = rk.astype(ct)
            elif isinstance(rk.dtype, ExtensionDtype):
                ct = find_common_type([lk.dtype, rk.dtype])
                if isinstance(ct, ExtensionDtype):
                    com_cls = ct.construct_array_type()
                    lk = com_cls._from_sequence(lk, dtype=ct, copy=False)
                else:
                    lk = lk.astype(ct)
            if is_integer_dtype(rk.dtype) and is_float_dtype(lk.dtype):
                with np.errstate(invalid='ignore'):
                    casted = lk.astype(rk.dtype)
                mask = ~np.isnan(lk)
                match = lk == casted
                if <MASK>:
                    warnings.warn('You are merging on int and float columns where the float values are not equal to their int representation.', UserWarning, stacklevel=find_stack_level())
                continue
            if is_float_dtype(rk.dtype) and is_integer_dtype(lk.dtype):
                with np.errstate(invalid='ignore'):
                    casted = rk.astype(lk.dtype)
                mask = ~np.isnan(rk)
                match = rk == casted
                if not match[mask].all():
                    warnings.warn('You are merging on int and float columns where the float values are not equal to their int representation.', UserWarning, stacklevel=find_stack_level())
                continue
            if lib.infer_dtype(lk, skipna=False) == lib.infer_dtype(rk, skipna=False):
                continue
        elif lk_is_object_or_string and is_bool_dtype(rk.dtype) or (is_bool_dtype(lk.dtype) and rk_is_object_or_string):
            pass
        elif lk_is_object_or_string and is_numeric_dtype(rk.dtype) or (is_numeric_dtype(lk.dtype) and rk_is_object_or_string):
            inferred_left = lib.infer_dtype(lk, skipna=False)
            inferred_right = lib.infer_dtype(rk, skipna=False)
            bool_types = ['integer', 'mixed-integer', 'boolean', 'empty']
            string_types = ['string', 'unicode', 'mixed', 'bytes', 'empty']
            if inferred_left in bool_types and inferred_right in bool_types:
                pass
            elif inferred_left in string_types and inferred_right not in string_types or (inferred_right in string_types and inferred_left not in string_types):
                raise ValueError(msg)
        elif needs_i8_conversion(lk.dtype) and (not needs_i8_conversion(rk.dtype)):
            raise ValueError(msg)
        elif not needs_i8_conversion(lk.dtype) and needs_i8_conversion(rk.dtype):
            raise ValueError(msg)
        elif isinstance(lk.dtype, DatetimeTZDtype) and (not isinstance(rk.dtype, DatetimeTZDtype)):
            raise ValueError(msg)
        elif not isinstance(lk.dtype, DatetimeTZDtype) and isinstance(rk.dtype, DatetimeTZDtype):
            raise ValueError(msg)
        elif isinstance(lk.dtype, DatetimeTZDtype) and isinstance(rk.dtype, DatetimeTZDtype) or (lk.dtype.kind == 'M' and rk.dtype.kind == 'M'):
            continue
        elif lk.dtype.kind == 'M' and rk.dtype.kind == 'm':
            raise ValueError(msg)
        elif lk.dtype.kind == 'm' and rk.dtype.kind == 'M':
            raise ValueError(msg)
        elif is_object_dtype(lk.dtype) and is_object_dtype(rk.dtype):
            continue
        if name in self.left.columns:
            typ = cast(Categorical, lk).categories.dtype if lk_is_cat else object
            self.left = self.left.copy()
            self.left[name] = self.left[name].astype(typ)
        if name in self.right.columns:
            typ = cast(Categorical, rk).categories.dtype if rk_is_cat else object
            self.right = self.right.copy()
            self.right[name] = self.right[name].astype(typ)

def _is_qconfig_supported_by_dtype_configs(qconfig: QConfig, dtype_configs: list[DTypeConfig]):
    for dtype_config in dtype_configs:
        is_dynamic = dtype_config.is_dynamic
        if is_dynamic is None:
            is_dynamic = False
        input_dtype = dtype_config.input_dtype or torch.float
        weight_dtype = dtype_config.weight_dtype or torch.float
        bias_dtype = dtype_config.bias_dtype or torch.float
        output_dtype = dtype_config.output_dtype or torch.float
        (qconfig_activation_dtype, qconfig_weight_dtype, qconfig_input_act_is_dynamic) = get_qconfig_dtypes(qconfig)
        qconfig_bias_dtype = torch.float16 if qconfig_activation_dtype == torch.float16 and qconfig_weight_dtype == torch.float16 and (not is_dynamic) else torch.float
        if <MASK>:
            is_match = qconfig_input_act_is_dynamic and input_dtype == qconfig_activation_dtype and (output_dtype == torch.float) and (weight_dtype == qconfig_weight_dtype)
        else:
            is_match = input_dtype == qconfig_activation_dtype and output_dtype == qconfig_activation_dtype and (weight_dtype == qconfig_weight_dtype) and (bias_dtype == qconfig_bias_dtype)
        if is_match:
            return True
    return False

@contextlib.contextmanager
def set_subgraph_body(self, body_name: str):
    assert all((hasattr(self, field.name) for field in dataclasses.fields(SubgraphInfo)))
    old_state = {key.name: getattr(self, key.name) for key in dataclasses.fields(SubgraphInfo)}
    assert body_name in self.subgraph_bodies, body_name
    subgraph = self.subgraph_bodies[body_name]
    for (key, value) in subgraph.to_dict().items():
        if <MASK>:
            continue
        setattr(self, key, value)
    context = contextlib.nullcontext if not self.ops_handler else lambda : V.set_ops_handler(self.ops_handler(V.get_ops_handler()))
    with context():
        yield
    self.subgraph_bodies[body_name] = SubgraphInfo(**{key.name: getattr(self, key.name) for key in dataclasses.fields(SubgraphInfo)})
    for (key, value) in old_state.items():
        setattr(self, key, value)

@simple_wraps(compiled_fn)
def runtime_wrapper(args: list[Any]):
    cm = record_runtime_wrapper_prologue_enter()
    orig_inputs = {i: args[i] for i in epilogue_args_idx}
    if keep_input_mutations:
        mutated_args = (args[i] for i in runtime_metadata.mutated_graph_handled_indices_seen_by_autograd)
        torch.autograd.graph.increment_version(mutated_args)
    if trace_joint:
        args_ = list(args)
        for idx in indices_of_inps_to_detach:
            if isinstance(args_[idx], torch.Tensor):
                args_[idx] = args_[idx].detach()
        with torch.autograd._force_original_view_tracking(True), torch.enable_grad():
            record_runtime_wrapper_prologue_exit(cm)
            all_outs = call_func_at_runtime_with_args(compiled_fn, args_, disable_amp=disable_amp, steal_args=True)
    else:
        grad_enabled = torch.is_grad_enabled()
        try:
            if grad_enabled:
                torch._C._set_grad_enabled(False)
            record_runtime_wrapper_prologue_exit(cm)
            all_outs = call_func_at_runtime_with_args(compiled_fn, args, disable_amp=disable_amp, steal_args=True)
        finally:
            if grad_enabled:
                torch._C._set_grad_enabled(True)
    del args
    num_mutated_runtime_inps = runtime_metadata.num_mutated_inp_runtime_indices
    num_intermediate_bases = runtime_metadata.num_intermediate_bases
    assert len(all_outs) == num_mutated_runtime_inps + runtime_metadata.num_outputs + num_intermediate_bases
    num_mutations_to_apply = runtime_metadata.num_mutated_inp_runtime_indices
    if num_mutations_to_apply > 0:
        updated_inputs = all_outs[:num_mutations_to_apply]
        fw_outs = all_outs[num_mutations_to_apply:]
        for (i, inpt_idx) in enumerate(runtime_metadata.mutated_inp_runtime_indices):
            meta = runtime_metadata.input_info[inpt_idx]
            if not meta.mutates_data and (not meta.mutates_metadata):
                continue
            original_inpt = orig_inputs[inpt_idx]
            updated_inpt = updated_inputs[i]
            if meta.mutates_storage_metadata:
                if trace_joint:
                    assert isinstance(updated_inpt, TensorAlias)
                    updated_inpt = updated_inpt.alias
                with torch.no_grad():
                    original_inpt.set_(updated_inpt)
                continue
            if meta.mutates_metadata and (not meta.mutates_data):
                if trace_joint:
                    assert isinstance(updated_inpt, TensorAlias)
                    updated_inpt = updated_inpt.alias
                original_inpt.as_strided_(updated_inpt.size(), updated_inpt.stride(), updated_inpt.storage_offset())
            else:
                if meta.mutates_data and meta.mutates_metadata:
                    original_inpt.as_strided_(updated_inpt.size(), updated_inpt.stride(), updated_inpt.storage_offset())
                else:
                    assert meta.mutates_data
                if meta.is_leaf and original_inpt.requires_grad:
                    original_inpt.detach().copy_(updated_inpt)
                else:
                    original_inpt.copy_(updated_inpt)
    else:
        fw_outs = all_outs
    if runtime_metadata.num_outputs_aliased > 0:
        expect_num_outputs = len(output_handlers) + runtime_metadata.num_intermediate_bases
        assert len(fw_outs) == expect_num_outputs
        ret_outs = [handler(orig_inputs, fw_outs, out) for (out, handler) in builtins.zip(fw_outs, output_handlers)]
    else:
        ret_outs = fw_outs
    if runtime_metadata.dynamic_outputs:
        for (t, o) in zip(ret_outs, runtime_metadata.output_info):
            if o.dynamic_dims is None:
                continue
            maybe_mark_dynamic_helper(t, o.dynamic_dims)
    if <MASK>:
        torch._C._set_grad_enabled(runtime_metadata.grad_enabled_mutation)
    return ret_outs

@tf_export.tf_export('experimental.numpy.ix_', v1=[])
@np_utils.np_doc('ix_')
def ix_(*args):
    n = len(args)
    output = []
    for (i, a) in enumerate(args):
        a = asarray(a)
        a_rank = array_ops.rank(a)
        a_rank_temp = np_utils.get_static_value(a_rank)
        if a_rank_temp is not None:
            a_rank = a_rank_temp
            if <MASK>:
                raise ValueError('Arguments must be 1-d, got arg {} of rank {}'.format(i, a_rank))
        else:
            control_flow_assert.Assert(math_ops.equal(a_rank, 1), [a_rank])
        new_shape = [1] * n
        new_shape[i] = -1
        dtype = a.dtype
        if dtype == dtypes.bool:
            output.append(array_ops.reshape(nonzero(a)[0], new_shape))
        elif dtype.is_integer:
            output.append(array_ops.reshape(a, new_shape))
        else:
            raise ValueError('Only integer and bool dtypes are supported, got {}'.format(dtype))
    return output

def _check_params(self):
    if self.type not in (Integral, Real, RealNotInt):
        raise ValueError(f'type must be either numbers.Integral, numbers.Real or RealNotInt. Got {self.type} instead.')
    if self.closed not in ('left', 'right', 'both', 'neither'):
        raise ValueError(f"closed must be either 'left', 'right', 'both' or 'neither'. Got {self.closed} instead.")
    if self.type is Integral:
        suffix = 'for an interval over the integers.'
        if self.left is not None and (not isinstance(self.left, Integral)):
            raise TypeError(f'Expecting left to be an int {suffix}')
        if self.right is not None and (not isinstance(self.right, Integral)):
            raise TypeError(f'Expecting right to be an int {suffix}')
        if <MASK>:
            raise ValueError(f"left can't be None when closed == {self.closed} {suffix}")
        if self.right is None and self.closed in ('right', 'both'):
            raise ValueError(f"right can't be None when closed == {self.closed} {suffix}")
    else:
        if self.left is not None and (not isinstance(self.left, Real)):
            raise TypeError('Expecting left to be a real number.')
        if self.right is not None and (not isinstance(self.right, Real)):
            raise TypeError('Expecting right to be a real number.')
    if self.right is not None and self.left is not None and (self.right <= self.left):
        raise ValueError(f"right can't be less than left. Got left={self.left} and right={self.right}")

def _explicit_order_placements(mesh_shape: ShapeType, placements: Sequence[Placement]) -> Sequence[tuple[int, Placement]]:
    """
    Replace Strided Shards with regular shards in an adjusted order.

    Returns a list of (mesh_dim, placement) tuples where the list order is the sharding order.

    ex.
    [Shard(0), _StridedShard(0, split_factor=2), Shard(0)] ->
    [(0, Shard(0)), (2, Shard(0)), (1, Shard(0))]

    """
    if <MASK>:
        raise RuntimeError(f'Expected one placement per mesh dim, but found {len(placements)} placements and {len(mesh_shape)} mesh dims.')
    ordered = []
    deferred_strided_placements = defaultdict(list)
    strided_part_ended_for_dim = set()
    for (mesh_dim, p) in enumerate(placements):
        if isinstance(p, _StridedShard):
            deferred_strided_placements[p.dim].append((mesh_dim, p))
        else:
            ordered.append((mesh_dim, p))
            if isinstance(p, Shard):
                if p.dim in strided_part_ended_for_dim:
                    raise NotImplementedError(f'Strided sharding does not allow Shard() to appear after the strided part has ended. {p} at mesh dim {mesh_dim} in {placements} violates this assumption.')
                if p.dim in deferred_strided_placements:
                    strided_part_ended_for_dim.add(p.dim)
                    strided_placements = deferred_strided_placements.pop(p.dim)
                    aggregate_size = mesh_shape[mesh_dim]
                    while len(strided_placements) > 0:
                        (strided_mesh_dim, strided) = strided_placements.pop()
                        if not strided.split_factor == aggregate_size:
                            raise RuntimeError(f'Can only convert _StridedShard to ordered Shard if split_factor({strided.split_factor}) == aggregate mesh size ({aggregate_size})')
                        aggregate_size *= mesh_shape[strided_mesh_dim]
                        ordered.append((strided_mesh_dim, Shard(p.dim)))
    return ordered

def main(argv: list[str] | None=None) -> int:
    suspicious_funcs: tuple[str, ...] = ('PyList_GetItem', 'PyDict_GetItem', 'PyDict_GetItemWithError', 'PyDict_GetItemString', 'PyDict_SetDefault', 'PyDict_Next', 'PyWeakref_GetObject', 'PyWeakref_GET_OBJECT', 'PyList_GET_ITEM', '_PyDict_GetItemStringWithError', 'PySequence_Fast')
    func_rx = build_func_rx(suspicious_funcs)
    noqa_markers = ('noqa: borrowed-ref OK', 'noqa: borrowed-ref - manual fix needed')
    default_exts = {'.c', '.h', '.c.src', '.cpp'}
    default_excludes = {'pythoncapi-compat'}
    ap = argparse.ArgumentParser(description='Borrow-ref C API linter (Python).')
    ap.add_argument('--quiet', action='store_true', help='Suppress normal output; exit status alone indicates result (useful              for CI).')
    ap.add_argument('-j', '--jobs', type=int, default=0, help='Number of worker threads (0=auto, 1=sequential).')
    ap.add_argument('--root', default='numpy', type=str, help='Root directory to scan (default: numpy)')
    ap.add_argument('--ext', action='append', default=None, help=f'File extension(s) to include (repeatable). Defaults to {default_exts}')
    ap.add_argument('--exclude', action='append', default=None, help=f'Directory name(s) to exclude (repeatable). Default: {default_excludes}')
    args = ap.parse_args(argv)
    if args.ext:
        exts = {e if e.startswith('.') else f'.{e}' for e in args.ext}
    else:
        exts = set(default_exts)
    excludes = set(args.exclude) if args.exclude else set(default_excludes)
    root = Path(args.root)
    if not root.exists():
        print(f"error: root '{root}' does not exist", file=sys.stderr)
        return 2
    files = sorted(iter_source_files(root, exts, excludes), key=str)
    if <MASK>:
        max_workers = min(32, (os.cpu_count() or 1) * 5)
    else:
        max_workers = max(1, args.jobs)
    print(f'Scanning {len(files)} C/C++ source files...\n')
    tmpdir = Path('.tmp')
    tmpdir.mkdir(exist_ok=True)
    findings = 0
    all_hits: list[tuple[str, int, str, str]] = []
    if max_workers == 1:
        for p in files:
            all_hits.extend(scan_file(p, func_rx, noqa_markers))
    else:
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            fut_to_file = {ex.submit(scan_file, p, func_rx, noqa_markers): p for p in files}
            for fut in as_completed(fut_to_file):
                try:
                    all_hits.extend(fut.result())
                except Exception as e:
                    print(f'Failed to scan {fut_to_file[fut]}: {e}')
    all_hits.sort(key=lambda t: (t[2], t[1]))
    if not all_hits:
        if not args.quiet:
            print('All checks passed! C API borrow-ref linter found no issues.\n')
        return 0
    with tempfile.NamedTemporaryFile(prefix='c_api_usage_report.', suffix='.txt', dir=tmpdir, mode='w+', encoding='utf-8', delete=False) as out:
        report_path = Path(out.name)
        out.write('Running Suspicious C API usage report workflow...\n\n')
        for (func, lineo, pstr, raw) in all_hits:
            findings += 1
            out.write(f'Found suspicious call to {func} in file: {pstr}\n')
            out.write(f' -> {pstr}:{lineo}a:{raw}\n')
            out.write('Recommendation:\n')
            out.write("If this use is intentional and safe, add '// noqa: borrowed-ref OK' on the same line to silence this warning.\n")
            out.write('Otherwise, consider replacing the call with a thread-safe API function.\n\n')
        out.flush()
        if not args.quiet:
            out.seek(0)
            sys.stdout.write(out.read())
            print(f'Report written to: {report_path}\n\nC API borrow-ref linter FAILED.')
    return 1

def compute_output_shape(self, input_shape):
    if isinstance(input_shape, list):
        input_shape = input_shape[0]
    try:
        input_shape = tensor_shape.TensorShape(input_shape)
    except (ValueError, TypeError):
        input_shape = nest.flatten(input_shape)[0]
    batch = input_shape[0]
    time_step = input_shape[1]
    if <MASK>:
        (batch, time_step) = (time_step, batch)
    if _is_multiple_state(self.cell.state_size):
        state_size = self.cell.state_size
    else:
        state_size = [self.cell.state_size]

    def _get_output_shape(flat_output_size):
        output_dim = tensor_shape.TensorShape(flat_output_size).as_list()
        if self.return_sequences:
            if self.time_major:
                output_shape = tensor_shape.TensorShape([time_step, batch] + output_dim)
            else:
                output_shape = tensor_shape.TensorShape([batch, time_step] + output_dim)
        else:
            output_shape = tensor_shape.TensorShape([batch] + output_dim)
        return output_shape
    if getattr(self.cell, 'output_size', None) is not None:
        output_shape = nest.flatten(nest.map_structure(_get_output_shape, self.cell.output_size))
        output_shape = output_shape[0] if len(output_shape) == 1 else output_shape
    else:
        output_shape = _get_output_shape(state_size[0])
    if self.return_state:

        def _get_state_shape(flat_state):
            state_shape = [batch] + tensor_shape.TensorShape(flat_state).as_list()
            return tensor_shape.TensorShape(state_shape)
        state_shape = nest.map_structure(_get_state_shape, state_size)
        return generic_utils.to_list(output_shape) + nest.flatten(state_shape)
    else:
        return output_shape

@classmethod
def process_subsystem(cls, curr_backend: str, curr_subsystem: Subsystem, fn: Callable[[], bool], cli_interface: bool=True) -> bool:
    """
        Process the current subsystem. Returns True if the issue is found, False otherwise.
        """
    assert isinstance(curr_subsystem, Subsystem)
    while True:
        run_state = cls.get_run_state(curr_backend, curr_subsystem.name)
        reset_counters()
        if run_state == 'test_disable':
            if not fn():
                next_subsystem = cls.advance_subsystem(curr_backend, curr_subsystem)
                if not next_subsystem:
                    return False
                curr_subsystem = next_subsystem
            else:
                if <MASK>:
                    print(f'Setting config {curr_subsystem.config_name} field {curr_subsystem.config_field} to {curr_subsystem.config_value} fixed the issue')
                else:
                    print(f'Disabling {curr_subsystem.name} fixed the issue.')
                if isinstance(curr_subsystem, BinarySubsystem):
                    return True
                print('Starting bisect by getting upper bound.')
                cls.update_run_state(curr_backend, curr_subsystem, 'find_max_bounds')
        elif run_state == 'find_max_bounds':
            if fn():
                raise RuntimeError(f"Function succeeded with 'find_max_bounds' status for {curr_backend} - {curr_subsystem.name}.")
            else:
                (_, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
                print(f'Upper bound of {high} found for {curr_backend}.')
                cls.update_run_state(curr_backend, curr_subsystem, 'bisect')
        elif run_state == 'bisect':
            (low, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
            midpoint = (low + high) // 2
            print(f'Bisecting {curr_backend} - {curr_subsystem.name} (Range: [{low}, {high}], Midpoint: {midpoint})')
            if fn():
                cls.update_bisect_range(curr_backend, curr_subsystem.name, midpoint + 1, high)
            else:
                cls.update_bisect_range(curr_backend, curr_subsystem.name, low, midpoint)
            (low, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
            if low == high:
                print(f"Binary search completed for {curr_backend} - {curr_subsystem.name}. The bisect number is {low}. Debug info: {call_counter_debug_info.get(low, 'not found')}")
                return True
        else:
            raise RuntimeError(f'Unexpected run_state {run_state}')
        if cli_interface:
            sys.exit(0)

def log_prob(self, value):
    if <MASK>:
        self._validate_sample(value)
    z = self._z(value)
    eq_zero = torch.isclose(self.concentration, torch.tensor(0.0))
    safe_conc = torch.where(eq_zero, torch.ones_like(self.concentration), self.concentration)
    y = 1 / safe_conc + torch.ones_like(z)
    where_nonzero = torch.where(y == 0, y, y * torch.log1p(safe_conc * z))
    log_scale = math.log(self.scale) if isinstance(self.scale, Real) else self.scale.log()
    return -log_scale - torch.where(eq_zero, z, where_nonzero)

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name == '__getitem__':
        return dynamo_triton_hopifier_singleton.call_getitem(self, args)
    elif <MASK>:
        return dynamo_triton_hopifier_singleton.call_run(self, args, kwargs, tx)
    return super().call_method(tx, name, args, kwargs)

def fuzz_valid_stride(size: tuple[int, ...]) -> tuple[int, ...]:
    """
    Fuzzes PyTorch tensor strides by generating valid stride patterns for a given size.

    Args:
        size: Tensor shape/size as a tuple of integers

    Returns:
        Tuple[int, ...]: A tuple representing valid tensor strides
    """
    if len(size) == 0:
        return ()
    stride_types = ['contiguous', 'transposed', 'custom_gaps', 'minimal', 'nonoverlapping_and_dense', 'nonoverlapping_and_dense_non_contig', 'overlapping', 'sparse_gaps']
    stride_type: str = random.choice(stride_types)
    if stride_type in ['contiguous', 'nonoverlapping_and_dense']:
        return tuple(_compute_contiguous_strides(size))
    elif stride_type == 'transposed':
        base_strides = list(_compute_contiguous_strides(size))
        if len(base_strides) >= 2:
            (i, j) = random.sample(range(len(base_strides)), 2)
            (base_strides[i], base_strides[j]) = (base_strides[j], base_strides[i])
        return tuple(base_strides)
    elif stride_type == 'custom_gaps':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] != 0 and random.random() < 0.3:
                gap_multiplier: int = random.randint(2, 5)
                base_strides[i] *= gap_multiplier
        return tuple(base_strides)
    elif stride_type == 'minimal':
        return tuple([1] * len(size))
    elif stride_type == 'nonoverlapping_and_dense_non_contig':
        return tuple(_compute_non_contiguous_dense_strides(size))
    elif stride_type == 'overlapping':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if <MASK>:
                base_strides[i] = 0
        return tuple(base_strides)
    elif stride_type == 'sparse_gaps':
        base_strides = list(_compute_contiguous_strides(size))
        for i in range(len(base_strides)):
            if size[i] > 1:
                gap_multiplier: int = random.randint(10, 100)
                base_strides[i] *= gap_multiplier
        return tuple(base_strides)
    return tuple(_compute_contiguous_strides(size))

def _maybe_infer_fake_kernel_from_pytree_out(self, func: OpOverload, fake_in: object, real_in: object, fake_out: object, real_out: object) -> Optional[object]:
    """
        Helper to cross-check fake/real output properties & values,
        and create new fake vals if mismatched, but at the kernel level.
        Means this handles pytree outputs & checks aliasing.
        """
    from torch._subclasses.fake_utils import _check_alias_info
    pending_unbacked = None
    if self.shape_env:
        pending_unbacked = list(self.shape_env.pending_fresh_unbacked_symbols)

    def _clear_pending_unbacked() -> None:
        self.shape_env.pending_fresh_unbacked_symbols = list(set(self.shape_env.pending_fresh_unbacked_symbols).difference(pending_unbacked))
    (fake_paths_leaves, fake_spec) = pytree.tree_flatten_with_path(fake_out)
    (real_leaves, _) = pytree.tree_flatten(real_out)
    try:
        _check_alias_info('Real tensor propagation found', real_out, real_in, fake_out, fake_in)
    except MetadataMismatchError as exc:
        if torch._functorch.config.generate_fake_kernels_from_real_mismatches:
            dtrace_structured('mismatched_fake_kernel', metadata_fn=lambda : {'op': str(func), 'reason': f'Mismatched aliasing spec between fake kernel and real kernel: {exc.reason}'})
            _clear_pending_unbacked()
            return tree_map(lambda x: _infer_fake_from_real_tensor(self, func, x), real_out)
        else:
            raise MetadataMismatchError(f'Real tensor propagation found an aliasing mismatch between fake output {fake_out} and real output {real_out},  for func: {func}') from exc
    (fake_leaves, overrides) = zip(*[self._maybe_infer_fake(func, _fake_path, _fake_out, _real_out) for ((_fake_path, _fake_out), _real_out) in zip(fake_paths_leaves, real_leaves)])
    if <MASK>:
        _clear_pending_unbacked()
    return pytree.tree_unflatten(fake_leaves, fake_spec)

