def get_model(self, app_label, model_name=None, require_ready=True):
    """
        Return the model matching the given app_label and model_name.

        As a shortcut, app_label may be in the form <app_label>.<model_name>.

        model_name is case-insensitive.

        Raise LookupError if no application exists with this label, or no
        model exists with this name in the application. Raise ValueError if
        called with a single argument that doesn't contain exactly one dot.
        """
    if require_ready:
        self.check_models_ready()
    else:
        self.check_apps_ready()
    if model_name is None:
        (app_label, model_name) = app_label.split('.')
    app_config = self.get_app_config(app_label)
    if <MASK>:
        app_config.import_models()
    return app_config.get_model(model_name, require_ready=require_ready)

def is_superperiod(source, target) -> bool:
    """
    Returns True if upsampling is possible between source and target
    frequencies

    Parameters
    ----------
    source : str or DateOffset
        Frequency converting from
    target : str or DateOffset
        Frequency converting to

    Returns
    -------
    bool
    """
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)
    if _is_annual(source):
        if _is_annual(target):
            return get_rule_month(source) == get_rule_month(target)
        if _is_quarterly(target):
            smonth = get_rule_month(source)
            tmonth = get_rule_month(target)
            return _quarter_months_conform(smonth, tmonth)
        return target in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_quarterly(source):
        return target in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_monthly(source):
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_weekly(source):
        return target in {source, 'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'B':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'C':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'D':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'h':
        return target in {'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'min':
        return target in {'min', 's', 'ms', 'us', 'ns'}
    elif source == 's':
        return target in {'s', 'ms', 'us', 'ns'}
    elif source == 'ms':
        return target in {'ms', 'us', 'ns'}
    elif <MASK>:
        return target in {'us', 'ns'}
    elif source == 'ns':
        return target in {'ns'}
    else:
        return False

def get_cpp_compiler() -> str:
    if config.aot_inductor.cross_target_platform == 'windows' and sys.platform != 'win32':
        compiler = MINGW_GXX
        if not config.aot_inductor.package_cpp_only:
            check_mingw_win32_flavor(compiler)
        return compiler
    if _IS_WINDOWS:
        compiler = os.environ.get('CXX', 'cl')
        compiler = normalize_path_separator(compiler)
        check_compiler_exist_windows(compiler)
        check_msvc_cl_language_id(compiler)
    else:
        if config.is_fbcode():
            return build_paths.cc
        if <MASK>:
            search = tuple(config.cpp.cxx)
        else:
            search = (config.cpp.cxx,)
        compiler = cpp_compiler_search(search)
    return compiler

def copy(src: Union[str, Path], dst: Union[str, Path]) -> None:
    """Copy file or directory from src to dst."""
    src_path = get_path(src, resolve=True)
    dst_path = get_path(dst, resolve=True)
    if <MASK>:
        raise FileNotFoundError(f'Source does not exist: {src_path}')
    dst_path.parent.mkdir(parents=True, exist_ok=True)
    if src_path.is_file():
        shutil.copy2(src_path, dst_path)
    elif src_path.is_dir():
        shutil.copytree(src_path, dst_path, dirs_exist_ok=True)
    else:
        raise ValueError(f'Unsupported path type: {src_path}')

def test_cuda_gds_errors_captured() -> None:
    major_version = int(torch.version.cuda.split('.')[0])
    minor_version = int(torch.version.cuda.split('.')[1])
    if target_os == 'windows':
        print(f'{target_os} is not supported for GDS smoke test')
        return
    if major_version < 12 or (major_version == 12 and minor_version < 6):
        print('CUDA version is not supported for GDS smoke test')
        return
    cuda_exception_missed = True
    try:
        print('Testing test_cuda_gds_errors_captured')
        with NamedTemporaryFile() as f:
            torch.cuda.gds.GdsFile(f.name, os.O_CREAT | os.O_RDWR)
    except RuntimeError as e:
        expected_error = 'cuFileHandleRegister failed'
        if <MASK>:
            print(f'Caught CUDA exception with success: {e}')
            cuda_exception_missed = False
        else:
            raise e
    if cuda_exception_missed:
        raise RuntimeError('Expected cuFileHandleRegister failed RuntimeError but have not received!')

@unpack_zerodim_and_defer('__add__')
def __add__(self, other):
    other_dtype = getattr(other, 'dtype', None)
    other = ensure_wrapped_if_datetimelike(other)
    if other is NaT:
        result: np.ndarray | DatetimeLikeArrayMixin = self._add_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_timedeltalike_scalar(other)
    elif isinstance(other, Day) and lib.is_np_dtype(self.dtype, 'Mm'):
        td = Timedelta(days=other.n).as_unit('s')
        result = self._add_timedeltalike_scalar(td)
    elif isinstance(other, BaseOffset):
        result = self._add_offset(other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._add_datetimelike_scalar(other)
    elif isinstance(other, Period) and lib.is_np_dtype(self.dtype, 'm'):
        result = self._add_period(other)
    elif lib.is_integer(other):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast('PeriodArray', self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.add)
    elif lib.is_np_dtype(other_dtype, 'm'):
        result = self._add_timedelta_arraylike(other)
    elif is_object_dtype(other_dtype):
        result = self._addsub_object_array(other, operator.add)
    elif lib.is_np_dtype(other_dtype, 'M') or isinstance(other_dtype, DatetimeTZDtype):
        return self._add_datetime_arraylike(other)
    elif is_integer_dtype(other_dtype):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast('PeriodArray', self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.add)
    else:
        return NotImplemented
    if <MASK>:
        from pandas.core.arrays import TimedeltaArray
        return TimedeltaArray._from_sequence(result, dtype=result.dtype)
    return result

@unpack_zerodim_and_defer('__sub__')
def __sub__(self, other):
    other_dtype = getattr(other, 'dtype', None)
    other = ensure_wrapped_if_datetimelike(other)
    if other is NaT:
        result: np.ndarray | DatetimeLikeArrayMixin = self._sub_nat()
    elif isinstance(other, (Tick, timedelta, np.timedelta64)):
        result = self._add_timedeltalike_scalar(-other)
    elif isinstance(other, Day) and lib.is_np_dtype(self.dtype, 'Mm'):
        td = Timedelta(days=other.n).as_unit('s')
        result = self._add_timedeltalike_scalar(-td)
    elif isinstance(other, BaseOffset):
        result = self._add_offset(-other)
    elif isinstance(other, (datetime, np.datetime64)):
        result = self._sub_datetimelike_scalar(other)
    elif lib.is_integer(other):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast('PeriodArray', self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.sub)
    elif isinstance(other, Period):
        result = self._sub_periodlike(other)
    elif lib.is_np_dtype(other_dtype, 'm'):
        result = self._add_timedelta_arraylike(-other)
    elif is_object_dtype(other_dtype):
        result = self._addsub_object_array(other, operator.sub)
    elif <MASK>:
        result = self._sub_datetime_arraylike(other)
    elif isinstance(other_dtype, PeriodDtype):
        result = self._sub_periodlike(other)
    elif is_integer_dtype(other_dtype):
        if not isinstance(self.dtype, PeriodDtype):
            raise integer_op_not_supported(self)
        obj = cast('PeriodArray', self)
        result = obj._addsub_int_array_or_scalar(other * obj.dtype._n, operator.sub)
    else:
        return NotImplemented
    if isinstance(result, np.ndarray) and lib.is_np_dtype(result.dtype, 'm'):
        from pandas.core.arrays import TimedeltaArray
        return TimedeltaArray._from_sequence(result, dtype=result.dtype)
    return result

def _codegen_single_template(self, kernel, render, template_node, epilogue_nodes, prologue_nodes, *, only_gen_src_code=False):
    """
        Helper method to codegen a single template kernel variant
        """
    buf_name_to_prologue_group = {}
    template_reads = template_node.used_buffer_names()
    prologue_group = []
    for prologue in prologue_nodes:
        names = prologue.get_buffer_names()
        prologue_group.append(prologue)
        if names & template_reads:
            assert len(names) == 1
            buf_name_to_prologue_group[next(iter(names))] = prologue_group
            kernel.prologue_fused_inputs.add(next(iter(names)))
            prologue_group = []
    assert len(prologue_group) == 0
    with kernel:
        if not only_gen_src_code:
            for node in [template_node, *epilogue_nodes]:
                node.mark_run()
        partial_code = render()
        num_store_subgraphs = kernel.get_store_output_count()
        for i in range(num_store_subgraphs):
            subgraph_name = kernel._get_store_output_subgraph_name(i)
            with kernel.set_subgraph_body(subgraph_name):
                for node in epilogue_nodes:
                    node.codegen(kernel.split_and_set_ranges(node.get_ranges()))
                kernel.cse.invalidate(OrderedSet())
        for (input_name, buffer) in kernel.named_input_nodes.items():
            subgraph_name = f'<LOAD_INPUT_{input_name}>'
            if <MASK>:
                can_codegen_without_upcast = all((p_n.can_codegen_without_upcasts() for p_n in prologue_group))
                with config.patch('triton.codegen_upcast_to_fp32', not can_codegen_without_upcast):
                    with kernel.set_subgraph_body(subgraph_name):
                        for prologue_node in prologue_group:
                            if len(prologue_node.get_buffer_names()) == 1 and len(prologue_group) == 1:
                                if prologue_preserves_zero_mask(prologue_node):
                                    kernel.prologue_fused_inputs_preserve_zero |= prologue_node.get_buffer_names()
                            prologue_node.codegen(kernel.split_and_set_ranges(prologue_node.get_ranges()))
                        kernel.cse.invalidate(OrderedSet())
    with V.set_kernel_handler(kernel):
        if not isinstance(partial_code, str):
            with ir.IRNode.current_origins(template_node.node.origins):
                partial_code.finalize_hook('<DEF_KERNEL>')
            partial_code.finalize_hook('<ARGDEFS>', strict=False)
        for input_name in kernel.named_input_nodes.keys():
            subgraph_name = f'<LOAD_INPUT_{input_name}>'
            partial_code.finalize_hook(subgraph_name, strict=False)
        num_store_subgraphs = kernel.get_store_output_count()
        for i in range(num_store_subgraphs):
            subgraph_name = kernel._get_store_output_subgraph_name(i)
            partial_code.finalize_hook(subgraph_name)
        if isinstance(partial_code, str):
            src_code = partial_code
        else:
            src_code = partial_code.finalize_remaining()
        node_schedule = [*prologue_nodes, template_node, *epilogue_nodes]
        if config.benchmark_kernel:
            num_gb = kernel.estimate_kernel_num_bytes() / 1000000000.0
            src_code = f'{kernel.imports_for_benchmark_kernel()}\n{src_code}\n{kernel.codegen_kernel_benchmark(num_gb).getvalue()}'
        if only_gen_src_code:
            return src_code
        kernel.kernel_name = self.define_kernel(src_code, node_schedule, kernel)
        return kernel

@compatibility(is_backward_compatible=False)
def legalize_graph(gm: torch.fx.GraphModule) -> torch.fx.GraphModule:
    """
    Replace the graph of the given GraphModule with one that contains the same nodes as the
    original, but in topologically sorted order.

    This is used by the merge_matmul transformation below, which disturbs the topologically sorted
    order of its input GraphModule, so that this order is restored before further transformation.

    Arguments:
        gm: The graph module to topologically sort. It is modified in-place.

    Returns:
        The graph module in-place sorted
    """
    PRIORITIZED_OPS = [operator.add, operator.mul, operator.sub, operator.floordiv, operator.truediv, operator.mod, operator.le, operator.lt, operator.ge, operator.gt, operator.eq, operator.ne, torch.ops.aten.sym_constrain_range.default, torch.ops.aten.sym_constrain_range_for_size.default, torch.ops.aten._assert_async.msg, torch.ops.aten.scalar_tensor.default, torch.ops.aten._assert_scalar.default]
    indeg = dict.fromkeys(gm.graph.nodes, 0)
    new_graph = torch.fx.Graph()
    for node in gm.graph.nodes:
        for user in node.users:
            indeg[user] += 1
    queue: collections.deque = collections.deque()
    for node in gm.graph.nodes:
        if <MASK>:
            queue.append(node)
    env: dict[torch.fx.Node, torch.fx.Node] = {}
    while len(queue) > 0:
        cur = queue.popleft()
        env[cur] = new_graph.node_copy(cur, lambda x: env[x])
        for user in cur.users:
            indeg[user] -= 1
            if indeg[user] == 0:
                if user.op == 'call_function' and user.target in PRIORITIZED_OPS:
                    queue.appendleft(user)
                else:
                    queue.append(user)
    if len(new_graph.nodes) < len(gm.graph.nodes):
        raise RuntimeError(f'Input graph has cycles, unable to add {[node for node in indeg if indeg[node] != 0]}')
    new_graph._codegen = gm.graph._codegen
    gm.graph = new_graph
    return gm

def _free_unbacked_symbols_with_path(a: object, path: pytree.KeyPath, real: Optional[object]=None, shape_env: Optional[ShapeEnv]=None, pending: Optional[set[sympy.Symbol]]=None, simplify: bool=False) -> dict[sympy.Symbol, pytree.KeyPath]:
    """
    Recursively traverses a structure to find unbacked symbols and their access paths.

    This function walks through tensors, lists, tuples, and symbolic values to locate
    unbacked symbols that are in the pending set, and returns a mapping from those
    symbols to their access paths in the structure.

    Args:
        a: The object to traverse (tensor, list, tuple, SymInt, etc.)
        path: The current path in the object tree
        real: Optional real tensor corresponding to the fake tensor being traversed
        shape_env: Optional ShapeEnv to register unbacked values with
        pending: Set of unbacked symbols to look for (will be modified in-place)
        simplify: Whether to use simplified expressions

    Returns:
        A dictionary mapping unbacked symbols to their access paths
    """
    go = functools.partial(_free_unbacked_symbols_with_path, shape_env=shape_env, pending=pending, simplify=simplify)

    def expr(s: Union[SymInt, SymFloat, SymBool]) -> sympy.Expr:
        if simplify:
            return s.node.expr
        return s.node._expr
    if pending is None:
        pending = set()
    r = {}
    if isinstance(a, (tuple, list)):
        for i in range(len(a)):
            r.update(go(a[i], path + (pytree.SequenceKey(i),), real=real[i] if real is not None else None))
    elif is_traceable_wrapper_subclass(a):
        (attrs, _) = a.__tensor_flatten__()
        for attr in attrs:
            sub = getattr(a, attr)
            r.update(go(sub, path + (InnerTensorKey(attr),)))
    elif isinstance(a, torch.Tensor) and is_batchedtensor(a):
        unwrapped_tensor = get_unwrapped(a)
        r.update(go(unwrapped_tensor, path))
    elif <MASK>:
        from torch._subclasses.fake_tensor import FakeTensor
        assert isinstance(a, FakeTensor)
        r.update(go(a.size(), path + (CallMethodKey('size'),), real=a.real_tensor.size() if a.real_tensor is not None else None))
        if a.layout not in [torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc]:
            r.update(go(a.stride(), path + (CallMethodKey('stride'),), real=a.real_tensor.stride() if a.real_tensor is not None else None))
        r.update(go(a.storage_offset(), path + (CallMethodKey('storage_offset'),), real=a.real_tensor.storage_offset() if a.real_tensor is not None else None))
    elif isinstance(a, (torch.SymInt, torch.SymFloat)) and isinstance((s := expr(a)), sympy.Symbol) and (s in pending):
        r[s] = path
        if shape_env and real is not None:
            assert isinstance(real, (int, float))
            shape_env.set_unbacked_var_to_val(s, real)
        pending.remove(s)
    elif isinstance(a, torch.SymInt) and isinstance((s := expr(a)), sympy.Mul) and (len(s.args) == 2) and isinstance((lhs := s.args[0]), (sympy.Integer, sympy.Symbol)) and isinstance((rhs := s.args[1]), sympy.Symbol) and ((rhs in pending) ^ (lhs in pending)) and (isinstance((coeff := (lhs if lhs not in pending else rhs)), sympy.Integer) or (shape_env and coeff in shape_env.var_to_val)):

        def _symint_wrap(s: sympy.Symbol) -> SymInt:
            return shape_env.create_symintnode(s, hint=int(shape_env.var_to_val[s]), source=shape_env.var_to_sources.get(s, [None])[0])
        unbacked = lhs if lhs in pending else rhs
        divisor: IntLikeType = int(coeff) if shape_env and isinstance(coeff, sympy.Integer) else _symint_wrap(coeff)
        r[unbacked] = path + (DivideByKey(divisor),)
        if real is not None:
            assert isinstance(real, int)
            val = real // int(coeff) if isinstance(coeff, sympy.Integer) else CleanDiv(real, coeff)
            if shape_env:
                shape_env.set_unbacked_var_to_val(unbacked, val)
        pending.remove(unbacked)
    elif isinstance(a, torch.SymBool) and isinstance((s := expr(a)), sympy.Eq) and isinstance(s.lhs, sympy.Symbol) and (s.rhs == 1) and (s.lhs in pending):
        r[s.lhs] = path + (ConvertIntKey(),)
        if real is not None:
            assert type(real) is bool
            if shape_env:
                shape_env.set_unbacked_var_to_val(s, int(real))
        pending.remove(s.lhs)
    return r

def _exec_command(command, use_shell=None, use_tee=None, **env):
    """
    Internal workhorse for exec_command().
    """
    if use_shell is None:
        use_shell = os.name == 'posix'
    if use_tee is None:
        use_tee = os.name == 'posix'
    if os.name == 'posix' and use_shell:
        sh = os.environ.get('SHELL', '/bin/sh')
        if is_sequence(command):
            command = [sh, '-c', ' '.join(command)]
        else:
            command = [sh, '-c', command]
        use_shell = False
    elif os.name == 'nt' and is_sequence(command):
        command = ' '.join((_quote_arg(arg) for arg in command))
    env = env or None
    try:
        proc = subprocess.Popen(command, shell=use_shell, env=env, text=False, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    except OSError:
        return (127, '')
    (text, err) = proc.communicate()
    mylocale = locale.getpreferredencoding(False)
    if <MASK>:
        mylocale = 'ascii'
    text = text.decode(mylocale, errors='replace')
    text = text.replace('\r\n', '\n')
    if text[-1:] == '\n':
        text = text[:-1]
    if use_tee and text:
        print(text)
    return (proc.returncode, text)

def _log_signature_report(signature_def_map, excluded_signatures):
    """Log a report of which signatures were produced."""
    sig_names_by_method_name = collections.defaultdict(list)
    for method_name in _FRIENDLY_METHOD_NAMES:
        sig_names_by_method_name[method_name] = []
    for (signature_name, sig) in signature_def_map.items():
        sig_names_by_method_name[sig.method_name].append(signature_name)
    for (method_name, sig_names) in sig_names_by_method_name.items():
        if method_name in _FRIENDLY_METHOD_NAMES:
            method_name = _FRIENDLY_METHOD_NAMES[method_name]
        logging.info('Signatures INCLUDED in export for {}: {}'.format(method_name, sig_names if sig_names else 'None'))
    if excluded_signatures:
        logging.info('Signatures EXCLUDED from export because they cannot be be served via TensorFlow Serving APIs:')
        for (signature_name, message) in excluded_signatures.items():
            logging.info("'{}' : {}".format(signature_name, message))
    if not signature_def_map:
        logging.warning('Export includes no signatures!')
    elif <MASK>:
        logging.warning('Export includes no default signature!')

@torch.autograd.no_grad()
def right_inverse(self, Q: torch.Tensor) -> torch.Tensor:
    if Q.shape != self.shape:
        raise ValueError(f'Expected a matrix or batch of matrices of shape {self.shape}. Got a tensor of shape {Q.shape}.')
    Q_init = Q
    (n, k) = (Q.size(-2), Q.size(-1))
    transpose = n < k
    if <MASK>:
        Q = Q.mT
        (n, k) = (k, n)
    if not hasattr(self, 'base'):
        if self.orthogonal_map == _OrthMaps.cayley or self.orthogonal_map == _OrthMaps.matrix_exp:
            raise NotImplementedError('It is not possible to assign to the matrix exponential or the Cayley parametrizations when use_trivialization=False.')
        (A, tau) = torch.geqrf(Q)
        A.diagonal(dim1=-2, dim2=-1).sign_()
        A.diagonal(dim1=-2, dim2=-1)[tau == 0.0] *= -1
        return A.mT if transpose else A
    else:
        if n == k:
            if not _is_orthogonal(Q):
                Q = _make_orthogonal(Q)
            else:
                Q = Q.clone()
        else:
            N = torch.randn(*Q.size()[:-2] + (n, n - k), dtype=Q.dtype, device=Q.device)
            Q = torch.cat([Q, N], dim=-1)
            Q = _make_orthogonal(Q)
        self.base = Q
        neg_Id = torch.zeros_like(Q_init)
        neg_Id.diagonal(dim1=-2, dim2=-1).fill_(-1.0)
        return neg_Id

def STORE_ATTR(self, inst: Instruction) -> None:
    speculation = self.speculate()
    if <MASK>:
        return self.store_attr_graph_break(inst)
    (val, obj) = self.popn(2)
    if isinstance(obj, NNModuleVariable) and (not isinstance(val, ConstantVariable)):
        assert not self.export, f'Mutating module attribute {inst.argval} during export.'
    try:
        BuiltinVariable(setattr).call_function(self, [obj, ConstantVariable.create(inst.argval), val], {})
        return
    except Unsupported as e:
        if not self.should_compile_partial_graph():
            raise
        log.debug('STORE_ATTR triggered compile', exc_info=True)
        e.remove_from_stats()
        e.add_to_stats('graph_break')
    speculation.fail_and_restart_analysis(self.error_on_graph_break)

def _get_next_prev(generic_view, date, is_previous, period):
    """
    Get the next or the previous valid date. The idea is to allow links on
    month/day views to never be 404s by never providing a date that'll be
    invalid for the given view.

    This is a bit complicated since it handles different intervals of time,
    hence the coupling to generic_view.

    However in essence the logic comes down to:

        * If allow_empty and allow_future are both true, this is easy: just
          return the naive result (just the next/previous day/week/month,
          regardless of object existence.)

        * If allow_empty is true, allow_future is false, and the naive result
          isn't in the future, then return it; otherwise return None.

        * If allow_empty is false and allow_future is true, return the next
          date *that contains a valid object*, even if it's in the future. If
          there are no next objects, return None.

        * If allow_empty is false and allow_future is false, return the next
          date that contains a valid object. If that date is in the future, or
          if there are no next objects, return None.
    """
    date_field = generic_view.get_date_field()
    allow_empty = generic_view.get_allow_empty()
    allow_future = generic_view.get_allow_future()
    get_current = getattr(generic_view, '_get_current_%s' % period)
    get_next = getattr(generic_view, '_get_next_%s' % period)
    (start, end) = (get_current(date), get_next(date))
    if allow_empty:
        if is_previous:
            result = get_current(start - datetime.timedelta(days=1))
        else:
            result = end
        if allow_future or result <= timezone_today():
            return result
        else:
            return None
    else:
        if is_previous:
            lookup = {'%s__lt' % date_field: generic_view._make_date_lookup_arg(start)}
            ordering = '-%s' % date_field
        else:
            lookup = {'%s__gte' % date_field: generic_view._make_date_lookup_arg(end)}
            ordering = date_field
        if not allow_future:
            if <MASK>:
                now = timezone.now()
            else:
                now = timezone_today()
            lookup['%s__lte' % date_field] = now
        qs = generic_view.get_queryset().filter(**lookup).order_by(ordering)
        try:
            result = getattr(qs[0], date_field)
        except IndexError:
            return None
        if generic_view.uses_datetime_field:
            if settings.USE_TZ:
                result = timezone.localtime(result)
            result = result.date()
        return get_current(result)

def triplet_margin_with_distance_loss(anchor: Tensor, positive: Tensor, negative: Tensor, *, distance_function: Optional[Callable[[Tensor, Tensor], Tensor]]=None, margin: float=1.0, swap: bool=False, reduction: str='mean') -> Tensor:
    """Compute the triplet margin loss for input tensors using a custom distance function.

    See :class:`~torch.nn.TripletMarginWithDistanceLoss` for details.
    """
    if torch.jit.is_scripting():
        raise NotImplementedError('F.triplet_margin_with_distance_loss does not support JIT scripting: functions requiring Callables cannot be scripted.')
    if has_torch_function_variadic(anchor, positive, negative):
        return handle_torch_function(triplet_margin_with_distance_loss, (anchor, positive, negative), anchor, positive, negative, distance_function=distance_function, margin=margin, swap=swap, reduction=reduction)
    if reduction not in ('mean', 'sum', 'none'):
        raise ValueError(f'{reduction} is not a valid value for reduction')
    if margin <= 0:
        raise ValueError(f'margin must be greater than 0, got {margin}')
    a_dim = anchor.ndim
    p_dim = positive.ndim
    n_dim = negative.ndim
    if not (a_dim == p_dim and p_dim == n_dim):
        raise RuntimeError(f'The anchor, positive, and negative tensors are expected to have the same number of dimensions, but got: anchor {a_dim}D, positive {p_dim}D, and negative {n_dim}D inputs')
    if distance_function is None:
        distance_function = torch.pairwise_distance
    dist_pos = distance_function(anchor, positive)
    dist_neg = distance_function(anchor, negative)
    if swap:
        dist_swap = distance_function(positive, negative)
        dist_neg = torch.minimum(dist_neg, dist_swap)
    loss = torch.clamp_min(margin + dist_pos - dist_neg, 0)
    if reduction == 'sum':
        return torch.sum(loss)
    elif <MASK>:
        return torch.mean(loss)
    else:
        return loss

def _calculate_qparams(self, signed: bool, min_val=None, max_val=None):
    if <MASK>:
        self.min_val = min_val
    if max_val is not None:
        self.max_val = max_val
    alpha = torch.max(-self.min_val, self.max_val)
    if not self.k or self.k == 0:
        raise AssertionError(f'k must be a non-zero integer, got k={self.k}')
    if self.b % self.k != 0:
        raise AssertionError(f'b must be divisible by k, got b={self.b}, k={self.k}')
    self.n = self.b // self.k
    p_all = []
    for i in range(self.n):
        p_curr = torch.tensor([0])
        for j in range(2 ** self.k - 2 + 1):
            curr_ele = 2 ** (-(i + j * self.n))
            p_append = torch.tensor([curr_ele])
            p_curr = torch.cat((p_curr, p_append))
            if signed:
                p_curr = torch.cat((p_curr, torch.tensor([-curr_ele])))
        if signed:
            (sorted, _indices) = torch.sort(p_curr, descending=True)
            p_all.append(sorted)
        else:
            p_all.append(p_curr)
    p_sum = 0.0
    for tens in p_all:
        if signed:
            p_sum += float(tens[0])
        else:
            p_sum += float(tens[1])
    gamma = alpha / p_sum
    cartesian_product = list(itertools.product(*p_all))
    quantization_levels_list = []
    for row in cartesian_product:
        sum = 0.0
        for ele in row:
            sum += ele
        quantization_levels_list.append(sum)
    quantization_levels_gamma = [float(gamma) * ele for ele in quantization_levels_list]
    quantization_levels = torch.tensor(quantization_levels_gamma)
    level_indices = torch.tensor([])
    (quantization_levels, level_indices) = quantization_levels.sort()
    return (alpha, gamma, quantization_levels, level_indices)

def _match_pattern(match_pattern: list[Callable]) -> Optional[Node]:
    """
        Traverse up the graph and match the args one by one.
        If there is a match, return the last matched node, or None otherwise.
        """
    a = arg
    for (i, match) in enumerate(match_pattern):
        if not match(a):
            return None
        if <MASK>:
            if match == match_tuple:
                a = a.args[0][0]
            else:
                a = a.args[0]
    return a

def __new__(cls, data=None, mask=nomask, dtype=None, copy=False, subok=True, ndmin=0, fill_value=None, keep_mask=True, hard_mask=None, shrink=True, order=None):
    """
        Create a new masked array from scratch.

        Notes
        -----
        A masked array can also be created by taking a .view(MaskedArray).

        """
    copy = None if not copy else True
    _data = np.array(data, dtype=dtype, copy=copy, order=order, subok=True, ndmin=ndmin)
    _baseclass = getattr(data, '_baseclass', type(_data))
    if isinstance(data, MaskedArray) and data.shape != _data.shape:
        copy = True
    if isinstance(data, cls) and subok and (not isinstance(data, MaskedConstant)):
        _data = ndarray.view(_data, type(data))
    else:
        _data = ndarray.view(_data, cls)
    if hasattr(data, '_mask') and (not isinstance(data, ndarray)):
        _data._mask = data._mask
    mdtype = make_mask_descr(_data.dtype)
    if mask is nomask:
        if not keep_mask:
            if shrink:
                _data._mask = nomask
            else:
                _data._mask = np.zeros(_data.shape, dtype=mdtype)
        elif isinstance(data, (tuple, list)):
            try:
                mask = np.array([getmaskarray(np.asanyarray(m, dtype=_data.dtype)) for m in data], dtype=mdtype)
            except (ValueError, TypeError):
                mask = nomask
            if mdtype == MaskType and mask.any():
                _data._mask = mask
                _data._sharedmask = False
        else:
            _data._sharedmask = not copy
            if copy:
                _data._mask = _data._mask.copy()
                if getmask(data) is not nomask:
                    if data._mask.shape != data.shape:
                        data._mask.shape = data.shape
    else:
        if mask is None:
            mask = False
        if mask is True and mdtype == MaskType:
            mask = np.ones(_data.shape, dtype=mdtype)
        elif mask is False and mdtype == MaskType:
            mask = np.zeros(_data.shape, dtype=mdtype)
        else:
            try:
                mask = np.array(mask, copy=copy, dtype=mdtype)
            except TypeError:
                mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
        if mask.shape != _data.shape:
            (nd, nm) = (_data.size, mask.size)
            if nm == 1:
                mask = np.resize(mask, _data.shape)
            elif <MASK>:
                mask = np.reshape(mask, _data.shape)
            else:
                msg = f'Mask and data not compatible: data size is {nd}, mask size is {nm}.'
                raise MaskError(msg)
            copy = True
        if _data._mask is nomask:
            _data._mask = mask
            _data._sharedmask = not copy
        elif not keep_mask:
            _data._mask = mask
            _data._sharedmask = not copy
        else:
            if _data.dtype.names is not None:

                def _recursive_or(a, b):
                    """do a|=b on each field of a, recursively"""
                    for name in a.dtype.names:
                        (af, bf) = (a[name], b[name])
                        if af.dtype.names is not None:
                            _recursive_or(af, bf)
                        else:
                            af |= bf
                _recursive_or(_data._mask, mask)
            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

def create_name(self, candidate: str, obj: Optional[Any]) -> str:
    """Create a unique name.

        Arguments:
            candidate: used as the basis for the unique name, relevant to the user.
            obj: If not None, an object that will be associated with the unique name.
        """
    if obj is not None and obj in self._obj_to_name:
        return self._obj_to_name[obj]
    match = _name_regex.match(candidate)
    if match is None:
        candidate = _illegal_char_regex.sub('_', candidate)
        if not candidate:
            candidate = '_unnamed'
        if <MASK>:
            candidate = f'_{candidate}'
        match = _name_regex.match(candidate)
        assert match is not None
    (base, num) = match.group(1, 2)
    if num is None or candidate in self._used_names:
        num = self._base_count.get(candidate, 0)
        if _illegal_names.get(candidate, obj) is not obj:
            num += 1
            candidate = f'{base}_{num}'
    else:
        num = int(num)
    while candidate in self._used_names:
        num += 1
        candidate = f'{base}_{num}'
    self._used_names.add(candidate)
    self._base_count[base] = num
    if obj is not None:
        self._obj_to_name[obj] = candidate
    return candidate

def check_geography(self, lookup, template_params):
    """Convert geography fields to geometry types, if necessary."""
