def is_static_true(b_node: fx.node.Argument) -> bool:
    if <MASK>:
        return True
    if not isinstance(b_node, fx.Node):
        return False
    b = b_node.meta.get('example_value')
    if b is None:
        return False
    if b is True:
        return True
    if isinstance(b, torch.SymBool) and (r := b.node.maybe_as_bool()) is not None:
        return r
    return False

def _get_arg_lists(self, arg_names, constexprs) -> tuple[list[str], list[str], OrderedSet[str]]:
    """
        Return a bunch of intermediate lists of args needed for generating
        launcher code.
        """
    compile_meta = self.compile_meta
    cfg = self.config
    known_constants = OrderedSet((arg for (i, arg) in enumerate(arg_names) if i in constexprs))
    '\n        https://github.com/pytorch/pytorch/issues/115344\n\n        self.fn.constexprs doesn\'t properly deal with None args, so when we filter out\n        an arg in UserDefinedTritonKernel.codegen, we need to filter it here as well.\n        We also don\'t want to modify self.fn.\n\n        We know that we removed something from the signature if:\n            1. It\'s in compile_meta["constants"]\n            2. It isn\'t a constant we already know about\n                Note: The value of interest has already been added to compile_meta[\'constants\'],\n                    so we use self.fn.constexprs instead.\n            3. It isn\'t in the compile_meta signature\n        '
    none_args = OrderedSet((k for (k, v) in compile_meta['constants'].items() if v is None and k not in known_constants))
    none_args = none_args.difference(OrderedSet(compile_meta['signature'].keys()))

    def _convert_constant(constant):
        if isinstance(constant, str):
            return "r'" + constant + "'"
        else:
            return repr(constant)
    if triton_version_uses_attrs_dict():
        call_args = arg_names
        def_args = arg_names
        implicit_constants = OrderedSet(('num_warps', 'num_stages')).union(OrderedSet((k for k in known_constants)))
        if (implicit_constants := (implicit_constants & OrderedSet(compile_meta['constants'].keys()))):
            def_args = [arg for arg in def_args if arg not in implicit_constants]
            repl = {k: _convert_constant(compile_meta['constants'].get(k)) for k in implicit_constants}
            call_args = [repl.get(arg, arg) for arg in call_args]
    else:
        call_args = [arg for (i, arg) in enumerate(arg_names) if i not in constexprs and arg not in none_args]
        cfg_dict = config_to_dict(cfg)
        def_args = [name for name in arg_names if name not in cfg_dict and name not in none_args]
    if <MASK>:
        def_args = [*def_args, *self.inductor_meta['extra_launcher_args']]
    return (call_args, def_args, none_args)

def find_nodes(self, *, op: str, target: Optional['Target']=None):
    if <MASK>:
        assert target is not None
        return [*self.table[op, target].keys()]
    if target is None:
        return [*self.table[op, None].keys()]
    return [node for node in self.table[op, None].keys() if node.target == target]

@compatibility(is_backward_compatible=False)
def getattr(self, attr: str, attr_val: Any, parameter_proxy_cache: dict[str, Any]):
    """
        Method that specifies the behavior of this ``Tracer`` when we call getattr
        on a call to an ``nn.Module`` instance.

        By default, the behavior is to return a proxy value for the attribute. It
        also stores the proxy value in the ``parameter_proxy_cache``, so that future
        calls will reuse the proxy rather than creating a new one.

        This method can be overridden to --for example-- not return proxies when
        querying parameters.

        Args:

            attr (str): The name of the attribute being queried
            attr_val (Any): The value of the attribute
            parameter_proxy_cache (Dict[str, Any]): A cache of attr names to proxies

        Return:

            The return value from the getattr call.
        """

    def maybe_get_proxy_for_attr(attr_val, collection_to_search, parameter_proxy_cache):
        for (n, p) in collection_to_search:
            if attr_val is p:
                if <MASK>:
                    kwargs = {}
                    if 'proxy_factory_fn' in inspect.signature(self.create_proxy).parameters:
                        kwargs['proxy_factory_fn'] = None if not self.param_shapes_constant else lambda node: ParameterProxy(self, node, n, attr_val)
                    val_proxy = self.create_proxy('get_attr', n, (), {}, **kwargs)
                    parameter_proxy_cache[n] = val_proxy
                return parameter_proxy_cache[n]
        return None
    if isinstance(attr_val, torch.nn.Parameter):
        maybe_parameter_proxy = maybe_get_proxy_for_attr(attr_val, self.root.named_parameters(), parameter_proxy_cache)
        if maybe_parameter_proxy is not None:
            return maybe_parameter_proxy
    if self.proxy_buffer_attributes and isinstance(attr_val, torch.Tensor):
        maybe_buffer_proxy = maybe_get_proxy_for_attr(attr_val, self.root.named_buffers(), parameter_proxy_cache)
        if maybe_buffer_proxy is not None:
            return maybe_buffer_proxy
    return attr_val

def _formatted_str_repr(self, idx, name, value):
    """ Returns a string representation for the given arg that is suitable for use in test function names. """
    if isinstance(value, torch.dtype):
        return dtype_name(value)
    elif isinstance(value, torch.device):
        return str(value)
    elif <MASK>:
        return value.formatted_name
    elif isinstance(value, (int, float, str)):
        return f"{name}_{str(value).replace('.', '_')}"
    else:
        return f'{name}{idx}'

