    super().write(obj=obj, data_columns=data_columns, **kwargs)

@dispatch.add_dispatch_support
@doc_controls.do_not_generate_docs
def elu(x, alpha=1.0):
    """Exponential linear unit.

  Args:
      x: A tensor or variable to compute the activation function for.
      alpha: A scalar, slope of negative section.

  Returns:
      A tensor.
  """
    res = nn.elu(x)
    if <MASK>:
        return res
    else:
        return array_ops.where_v2(x > 0, res, alpha * res)

def _select_strategy(self, strategy: OpStrategy, op_schema: Optional[OpSchema]=None) -> OpSpec:
    if len(strategy.strategies) == 1:
        return strategy.strategies[0]
    op_spec_costs: list[float] = []
    no_redistribute_strategy_index: int = -1
    for (strategy_idx, op_spec) in enumerate(strategy.strategies):
        assert op_spec.redistribute_cost is not None, 'must set redistribute cost each OpSpec!'
        redistribute_cost = sum(chain.from_iterable(op_spec.redistribute_cost))
        op_spec_costs.append(redistribute_cost)
        if op_schema is not None and redistribute_cost == 0:
            needs_redistribute = False
            for (spec_idx, input_spec) in enumerate(op_schema.args_spec):
                desired_spec = op_spec.output_spec if op_spec.input_specs is None else op_spec.input_specs[spec_idx]
                if input_spec.placements != desired_spec.placements:
                    needs_redistribute = True
                    break
            if not needs_redistribute:
                no_redistribute_strategy_index = strategy_idx
    min_cost = min(op_spec_costs)
    if <MASK>:
        selected_strategy_index = op_spec_costs.index(min_cost)
    elif min_cost == 0 and no_redistribute_strategy_index != -1:
        selected_strategy_index = no_redistribute_strategy_index
    else:
        selected_strategy_index = op_spec_costs.index(min_cost)
    return strategy.strategies[selected_strategy_index]

def get_default_quantizer(is_qat, is_dynamic, inputs):
    has_xpu = any((isinstance(input, torch.Tensor) and input.device.type == 'xpu' for input in inputs))
    if <MASK>:
        quantizer = XPUInductorQuantizer()
        assert not is_qat and (not is_dynamic), 'QAT and dynamic quantization is not supported at XPU backend currently'
        quantizer.set_global(xpuiq.get_default_xpu_inductor_quantization_config())
    else:
        quantizer = X86InductorQuantizer()
        quantizer.set_global(xiq.get_default_x86_inductor_quantization_config(is_qat=is_qat, is_dynamic=is_dynamic))
    return quantizer

@_onnx_symbolic('aten::cross_entropy_loss')
def cross_entropy_loss(g: jit_utils.GraphContext, self, target, weight, reduction, ignore_index, label_smoothing):
    reduction = symbolic_helper._maybe_get_const(reduction, 'i')
    reduction_vals = ['none', 'mean', 'sum']
    reduction = reduction_vals[reduction]
    label_smoothing = symbolic_helper._maybe_get_const(label_smoothing, 'f')
    if label_smoothing is not None and label_smoothing > 0.0:
        raise errors.SymbolicValueError('Unsupported: ONNX does not support label_smoothing', self)
    ignore_index = symbolic_helper._maybe_get_const(ignore_index, 'i')
    if <MASK>:
        celoss = g.op('SoftmaxCrossEntropyLoss', self, target, reduction_s=reduction, ignore_index_i=ignore_index)
    else:
        celoss = g.op('SoftmaxCrossEntropyLoss', self, target, weight, reduction_s=reduction, ignore_index_i=ignore_index)
    return celoss

