def substitute(self, symbols_map):
    """Recursively substitute symbols with values in symbols map.

        Symbols map is a dictionary of symbol-expression pairs.
        """
    if self.op is Op.SYMBOL:
        value = symbols_map.get(self)
        if value is None:
            return self
        m = re.match('\\A(@__f2py_PARENTHESIS_(\\w+)_\\d+@)\\Z', self.data)
        if m:
            (items, paren) = m.groups()
            if paren in ['ROUNDDIV', 'SQUARE']:
                return as_array(value)
            assert paren == 'ROUND', (paren, value)
        return value
    if self.op in (Op.INTEGER, Op.REAL, Op.STRING):
        return self
    if self.op in (Op.ARRAY, Op.COMPLEX):
        return Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data)))
    if self.op is Op.CONCAT:
        return normalize(Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data))))
    if self.op is Op.TERMS:
        r = None
        for (term, coeff) in self.data.items():
            if <MASK>:
                r = term.substitute(symbols_map) * coeff
            else:
                r += term.substitute(symbols_map) * coeff
        if r is None:
            ewarn('substitute: empty TERMS expression interpreted as int-literal 0')
            return as_number(0)
        return r
    if self.op is Op.FACTORS:
        r = None
        for (base, exponent) in self.data.items():
            if r is None:
                r = base.substitute(symbols_map) ** exponent
            else:
                r *= base.substitute(symbols_map) ** exponent
        if r is None:
            ewarn('substitute: empty FACTORS expression interpreted as int-literal 1')
            return as_number(1)
        return r
    if self.op is Op.APPLY:
        (target, args, kwargs) = self.data
        if isinstance(target, Expr):
            target = target.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in args))
        kwargs = {k: v.substitute(symbols_map) for (k, v) in kwargs.items()}
        return normalize(Expr(self.op, (target, args, kwargs)))
    if self.op is Op.INDEXING:
        func = self.data[0]
        if isinstance(func, Expr):
            func = func.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in self.data[1:]))
        return normalize(Expr(self.op, (func,) + args))
    if self.op is Op.TERNARY:
        operands = tuple((a.substitute(symbols_map) for a in self.data))
        return normalize(Expr(self.op, operands))
    if self.op in (Op.REF, Op.DEREF):
        return normalize(Expr(self.op, self.data.substitute(symbols_map)))
    if self.op is Op.RELATIONAL:
        (rop, left, right) = self.data
        left = left.substitute(symbols_map)
        right = right.substitute(symbols_map)
        return normalize(Expr(self.op, (rop, left, right)))
    raise NotImplementedError(f'substitute method for {self.op}: {self!r}')

def _correct_storage_aliasing(func, schema_info, args, outs):
    """
    Given: an OpOverload, a SchemaInfo (cached information from torchgen about schema),
    and the inputs/outputs to the OpOverload,
    this function checks to see if func is a view operator
    (by checking if any of the outputs in the op's schema
     are immutable aliases of inputs).
    If so, this function manually aliases the storage of the output tensor
    with its corresponding input tensor alias.
    It does this by unsafely overwriting the storage field of the output tensor
    to be the same storage as the input.
    """
    assert isinstance(func, torch._ops.OpOverload)
    assert isinstance(args, tuple)
    assert isinstance(outs, (list, tuple))

    def alias_non_inplace_storage(arg, ret):
        arg_type = type(arg)
        ret_type = type(ret)
        if arg_type is not ret_type and (is_traceable_wrapper_subclass_type(arg_type) or is_traceable_wrapper_subclass_type(ret_type)):
            ret_list = ret if isinstance(ret, list) else [ret]
            for r in ret_list:
                assert type(arg) is type(r), f'Called {str(func)} with input of type {type(arg)}\nand output of type {type(ret)}. But expected types to match.'
        if isinstance(ret, list):
            for r in ret:
                torch._functionalize_unsafe_set(r, arg)
        else:
            assert isinstance(ret, torch.Tensor), f'type: {type(ret)}'
            torch._functionalize_unsafe_set(ret, arg)
    for (arg_idx, schema_arg) in enumerate(schema_info.args):
        for (return_idx, schema_out) in enumerate(schema_info.outs):
            is_read_only_alias_match = schema_arg.alias_set & schema_out.alias_set and (not schema_arg.is_write)
            if <MASK>:
                alias_non_inplace_storage(args[arg_idx], outs[return_idx])

def __init__(self, encoder_layer: 'TransformerEncoderLayer', num_layers: int, norm: Optional[Module]=None, enable_nested_tensor: bool=True, mask_check: bool=True) -> None:
    super().__init__()
    torch._C._log_api_usage_once(f'torch.nn.modules.{self.__class__.__name__}')
    self.layers = _get_clones(encoder_layer, num_layers)
    self.num_layers = num_layers
    self.norm = norm
    self.enable_nested_tensor = enable_nested_tensor
    self.use_nested_tensor = enable_nested_tensor
    self.mask_check = mask_check
    enc_layer = 'encoder_layer'
    why_not_sparsity_fast_path = ''
    if not isinstance(encoder_layer, torch.nn.TransformerEncoderLayer):
        why_not_sparsity_fast_path = f'{enc_layer} was not TransformerEncoderLayer'
    elif encoder_layer.norm_first:
        why_not_sparsity_fast_path = f'{enc_layer}.norm_first was True'
    elif not encoder_layer.self_attn.batch_first:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn.batch_first was not True' + '(use batch_first for better inference performance)'
    elif not encoder_layer.self_attn._qkv_same_embed_dim:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn._qkv_same_embed_dim was not True'
    elif encoder_layer.self_attn.in_proj_bias is None:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn was passed bias=False'
    elif not encoder_layer.activation_relu_or_gelu:
        why_not_sparsity_fast_path = f'{enc_layer}.activation_relu_or_gelu was not True'
    elif encoder_layer.norm1.eps != encoder_layer.norm2.eps:
        why_not_sparsity_fast_path = f'{enc_layer}.norm1.eps was not equal to {enc_layer}.norm2.eps'
    elif encoder_layer.self_attn.num_heads % 2 == 1:
        why_not_sparsity_fast_path = f'{enc_layer}.self_attn.num_heads is odd'
    if <MASK>:
        warnings.warn(f'enable_nested_tensor is True, but self.use_nested_tensor is False because {why_not_sparsity_fast_path}')
        self.use_nested_tensor = False

def isin(comps: ListLike, values: ListLike) -> npt.NDArray[np.bool_]:
    """
    Compute the isin boolean array.

    Parameters
    ----------
    comps : list-like
    values : list-like

    Returns
    -------
    ndarray[bool]
        Same length as `comps`.
    """
    if not is_list_like(comps):
        raise TypeError(f'only list-like objects are allowed to be passed to isin(), you passed a `{type(comps).__name__}`')
    if not is_list_like(values):
        raise TypeError(f'only list-like objects are allowed to be passed to isin(), you passed a `{type(values).__name__}`')
    if not isinstance(values, (ABCIndex, ABCSeries, ABCExtensionArray, np.ndarray)):
        orig_values = list(values)
        values = _ensure_arraylike(orig_values, func_name='isin-targets')
        if len(values) > 0 and values.dtype.kind in 'iufcb' and (not is_signed_integer_dtype(comps)) and (not is_dtype_equal(values, comps)):
            values = construct_1d_object_array_from_listlike(orig_values)
    elif <MASK>:
        values = np.array(values)
    else:
        values = extract_array(values, extract_numpy=True, extract_range=True)
    comps_array = _ensure_arraylike(comps, func_name='isin')
    comps_array = extract_array(comps_array, extract_numpy=True)
    if not isinstance(comps_array, np.ndarray):
        return comps_array.isin(values)
    elif needs_i8_conversion(comps_array.dtype):
        return pd_array(comps_array).isin(values)
    elif needs_i8_conversion(values.dtype) and (not is_object_dtype(comps_array.dtype)):
        return np.zeros(comps_array.shape, dtype=bool)
    elif needs_i8_conversion(values.dtype):
        return isin(comps_array, values.astype(object))
    elif isinstance(values.dtype, ExtensionDtype):
        return isin(np.asarray(comps_array), np.asarray(values))
    if len(comps_array) > _MINIMUM_COMP_ARR_LEN and len(values) <= 26 and (comps_array.dtype != object) and (not any((v is NA for v in values))):
        if isna(values).any():

            def f(c, v):
                return np.logical_or(np.isin(c, v).ravel(), np.isnan(c))
        else:
            f = lambda a, b: np.isin(a, b).ravel()
    else:
        common = np_find_common_type(values.dtype, comps_array.dtype)
        values = values.astype(common, copy=False)
        comps_array = comps_array.astype(common, copy=False)
        f = htable.ismember
    return f(comps_array, values)

def __init__(self, params: ParamsT, lr: Union[float, Tensor]=0.001, momentum: float=0, dampening: float=0, weight_decay: Union[float, Tensor]=0, nesterov: bool=False, *, maximize: bool=False, foreach: Optional[bool]=None, differentiable: bool=False, fused: Optional[bool]=None):
    if <MASK>:
        raise ValueError('Tensor lr must be 1-element')
    if lr < 0.0:
        raise ValueError(f'Invalid learning rate: {lr}')
    if momentum < 0.0:
        raise ValueError(f'Invalid momentum value: {momentum}')
    if weight_decay < 0.0:
        raise ValueError(f'Invalid weight_decay value: {weight_decay}')
    defaults = {'lr': lr, 'momentum': momentum, 'dampening': dampening, 'weight_decay': weight_decay, 'nesterov': nesterov, 'maximize': maximize, 'foreach': foreach, 'differentiable': differentiable, 'fused': fused}
    if nesterov and (momentum <= 0 or dampening != 0):
        raise ValueError('Nesterov momentum requires a momentum and zero dampening')
    super().__init__(params, defaults)
    if fused:
        self._step_supports_amp_scaling = True
        self._need_device_dtype_check_for_fused = True
        if differentiable:
            raise RuntimeError('`fused` does not support `differentiable`')
        if foreach:
            raise RuntimeError('`fused` and `foreach` cannot be `True` together.')

def _broadcast_dynamic_shape_next_layer(ac_0: _LayerBroadcaster, bc_0: _LayerBroadcaster, a_1: RowPartition, b_1: RowPartition) -> Tuple[RowPartition, _LayerBroadcaster, _LayerBroadcaster]:
    """Broadcast target and next layer broadcaster of two dynamic shapes.

     *--ac_0-->*<--bc_0--*
     |         |         |
    a_1       c_1       b_1
     |         |         |
     V         V         V
     *--ac_1-->*<--bc_1--*

  Args:
    ac_0: _LayerBroadcaster from a to c in the previous layer.
    bc_0: _LayerBroadcaster from b to c in the previous layer.
    a_1: a RowPartition for the next layer of a.
    b_1: a RowPartition for the next layer of b.

  Returns:
    (c_1, ac_1, bc_1)
    c_1: a RowPartition for the next layer of the dynamic shape.
    ac_1: _LayerBroadcaster from a to c in the next layer.
    bc_1: _LayerBroadcaster from b to c in the next layer.
  """
    if not isinstance(ac_0, _LayerBroadcaster):
        raise TypeError('ac_0 should be a _LayerBroadcaster')
    if not isinstance(bc_0, _LayerBroadcaster):
        raise TypeError('bc_0 should be a _LayerBroadcaster')
    if not isinstance(a_1, RowPartition):
        raise TypeError('a_1 should be a RowPartition')
    if not isinstance(b_1, RowPartition):
        raise TypeError('b_1 should be a RowPartition')
    if a_1.is_uniform():
        if <MASK>:
            return _broadcast_dynamic_shape_next_layer_both_uniform(ac_0, bc_0, a_1, b_1)
        else:
            return _broadcast_dynamic_shape_next_layer_half_ragged(ac_0, bc_0, a_1, b_1)
    elif b_1.is_uniform():
        [c_1, bc_1, ac_1] = _broadcast_dynamic_shape_next_layer_half_ragged(bc_0, ac_0, b_1, a_1)
        return (c_1, ac_1, bc_1)
    else:
        [ac_1, c_1a] = _broadcast_half(ac_0, a_1)
        [bc_1, c_1b] = _broadcast_half(bc_0, b_1)
        check_valid = [check_ops.assert_equal(c_1a.row_splits(), c_1b.row_splits())]
        return (c_1a._with_dependencies(check_valid), ac_1.with_dependencies(check_valid), bc_1.with_dependencies(check_valid))

def _validate_device_maps(all_names, all_device_counts, all_device_maps, all_devices, is_static_group=True):
    for node in all_names:
        devices = all_devices[node]
        if <MASK>:
            raise ValueError(f'Node {node} has duplicated devices\ndevices = {devices}')
        if not _tensorpipe_validate_devices(devices, all_device_counts[node]):
            raise ValueError(f'Node {node} has devices with invalid indices\ndevices = {devices}\ndevice count = {all_device_counts[node]}')
    for source_node in all_names:
        if is_static_group and (not set(all_device_maps[source_node].keys()).issubset(all_names)):
            raise ValueError(f'Node {source_node} has invalid target node names in its device maps\ndevice maps = {all_device_maps[source_node].keys()}\nnode names = {all_names}')
        for (target_node, map_) in all_device_maps[source_node].items():
            if len(set(map_.values())) != len(map_):
                raise ValueError(f'Node {source_node} has duplicated target devices in its device map for {target_node}\ndevice map = {map_}')
            if all_devices[source_node]:
                if not set(map_.keys()).issubset(all_devices[source_node]):
                    raise ValueError(f'Node {source_node} has unexpected source devices in its device map for {target_node}\ndevice map = {map_}\ndevices = {all_devices[source_node]}')
            elif not _tensorpipe_validate_devices(map_.keys(), all_device_counts[source_node]):
                raise ValueError(f'Node {source_node} has source devices with invalid indices in its device map for {target_node}\ndevice map = {map_}\ndevice count = {all_device_counts[source_node]}')
            if all_devices.get(target_node, []):
                if not set(map_.values()).issubset(all_devices[target_node]):
                    raise ValueError(f'Node {source_node} has unexpected target devices in its device map for {target_node}\ndevice map = {map_}\ndevices = {all_devices[target_node]}')
            elif target_node in all_device_counts and (not _tensorpipe_validate_devices(map_.values(), all_device_counts[target_node])):
                raise ValueError(f'Node {source_node} has target devices with invalid indices in its device map for {target_node}\ndevice map = {map_}\ndevice count = {all_device_counts[target_node]}')

def unique_with_mask(values, mask: npt.NDArray[np.bool_] | None=None):
    """See algorithms.unique for docs. Takes a mask for masked arrays."""
    values = _ensure_arraylike(values, func_name='unique')
    if <MASK>:
        return values.unique()
    if isinstance(values, ABCIndex):
        return values.unique()
    original = values
    (hashtable, values) = _get_hashtable_algo(values)
    table = hashtable(len(values))
    if mask is None:
        uniques = table.unique(values)
        uniques = _reconstruct_data(uniques, original.dtype, original)
        return uniques
    else:
        (uniques, mask) = table.unique(values, mask=mask)
        uniques = _reconstruct_data(uniques, original.dtype, original)
        assert mask is not None
        return (uniques, mask.astype('bool'))

def filter_sources(sources):
    """Return four lists of filenames containing
    C, C++, Fortran, and Fortran 90 module sources,
    respectively.
    """
    c_sources = []
    cxx_sources = []
    f_sources = []
    fmodule_sources = []
    for source in sources:
        if <MASK>:
            modules = _get_f90_modules(source)
            if modules:
                fmodule_sources.append(source)
            else:
                f_sources.append(source)
        elif cxx_ext_match(source):
            cxx_sources.append(source)
        else:
            c_sources.append(source)
    return (c_sources, cxx_sources, f_sources, fmodule_sources)

def create_table(self, database, tablename, dry_run):
    cache = BaseDatabaseCache(tablename, {})
    if not router.allow_migrate_model(database, cache.cache_model_class):
        return
    connection = connections[database]
    if tablename in connection.introspection.table_names():
        if <MASK>:
            self.stdout.write("Cache table '%s' already exists." % tablename)
        return
    fields = (models.CharField(name='cache_key', max_length=255, unique=True, primary_key=True), models.TextField(name='value'), models.DateTimeField(name='expires', db_index=True))
    table_output = []
    index_output = []
    qn = connection.ops.quote_name
    for f in fields:
        field_output = [qn(f.name), f.db_type(connection=connection), '%sNULL' % ('NOT ' if not f.null else '')]
        if f.primary_key:
            field_output.append('PRIMARY KEY')
        elif f.unique:
            field_output.append('UNIQUE')
        if f.db_index:
            unique = 'UNIQUE ' if f.unique else ''
            index_output.append('CREATE %sINDEX %s ON %s (%s);' % (unique, qn('%s_%s' % (tablename, f.name)), qn(tablename), qn(f.name)))
        table_output.append(' '.join(field_output))
    full_statement = ['CREATE TABLE %s (' % qn(tablename)]
    for (i, line) in enumerate(table_output):
        full_statement.append('    %s%s' % (line, ',' if i < len(table_output) - 1 else ''))
    full_statement.append(');')
    full_statement = '\n'.join(full_statement)
    if dry_run:
        self.stdout.write(full_statement)
        for statement in index_output:
            self.stdout.write(statement)
        return
    with transaction.atomic(using=database, savepoint=connection.features.can_rollback_ddl):
        with connection.cursor() as curs:
            try:
                curs.execute(full_statement)
            except DatabaseError as e:
                raise CommandError("Cache table '%s' could not be created.\nThe error was: %s." % (tablename, e))
            for statement in index_output:
                curs.execute(statement)
    if self.verbosity > 1:
        self.stdout.write("Cache table '%s' created." % tablename)

def _constant_value(ragged_factory, inner_factory, pylist, dtype, ragged_rank, inner_shape):
    """Constructs a constant RaggedTensor or RaggedTensorValue.

  Args:
    ragged_factory: A factory function with the signature:
      `ragged_factory(values, row_splits)`
    inner_factory: A factory function with the signature: `inner_factory(pylist,
      dtype, shape, name)`
    pylist: A nested `list`, `tuple` or `np.ndarray`.
    dtype: Data type for returned value.
    ragged_rank: Ragged rank for returned value.
    inner_shape: Inner value shape for returned value.

  Returns:
    A value returned by `ragged_factory` or `inner_factory`.

  Raises:
    ValueError: If the scalar values in `pylist` have inconsistent nesting
      depth; or if ragged_rank or inner_shape are incompatible with `pylist`.
  """
    if ragged_tensor.is_ragged(pylist):
        raise TypeError('pylist may not be a RaggedTensor or RaggedTensorValue.')
    if not isinstance(pylist, (list, tuple)) and np.ndim(pylist) == 0:
        if ragged_rank is not None and ragged_rank != 0:
            raise ValueError('Invalid pylist=%r: incompatible with ragged_rank=%d' % (pylist, ragged_rank))
        if inner_shape is not None and inner_shape:
            raise ValueError('Invalid pylist=%r: incompatible with dim(inner_shape)=%d' % (pylist, len(inner_shape)))
        return inner_factory(pylist, dtype, ())
    if ragged_rank is not None and ragged_rank < 0:
        raise ValueError('Invalid ragged_rank=%r: must be nonnegative' % ragged_rank)
    (scalar_depth, max_depth) = _find_scalar_and_max_depth(pylist)
    if scalar_depth is not None:
        if max_depth > scalar_depth:
            raise ValueError('Invalid pylist=%r: empty list nesting is greater than scalar value nesting' % pylist)
        if ragged_rank is not None and max_depth < ragged_rank:
            raise ValueError(f'Invalid pylist={pylist}, max depth smaller than ragged_rank={ragged_rank}')
    if inner_shape is not None and ragged_rank is not None:
        expected_depth = ragged_rank + len(inner_shape) + 1
        if scalar_depth is not None and expected_depth != scalar_depth or (scalar_depth is None and expected_depth < max_depth):
            raise ValueError('Invalid pylist=%r: incompatible with ragged_rank=%d and dim(inner_shape)=%d' % (pylist, ragged_rank, len(inner_shape)))
    if ragged_rank == 0 or (ragged_rank is None and (max_depth < 2 or (inner_shape is not None and max_depth - len(inner_shape) < 2))):
        return inner_factory(pylist, dtype, inner_shape)
    if inner_shape is None:
        if <MASK>:
            inner_shape = ()
        else:
            inner_shape = _default_inner_shape_for_pylist(pylist, ragged_rank)
    if ragged_rank is None:
        if scalar_depth is None:
            ragged_rank = max(1, max_depth - 1)
        else:
            ragged_rank = max(1, scalar_depth - 1 - len(inner_shape))
    nested_splits = []
    values = pylist
    for dim in range(ragged_rank):
        nested_splits.append([0])
        concatenated_values = []
        for row in values:
            nested_splits[dim].append(nested_splits[dim][-1] + len(row))
            concatenated_values.extend(row)
        values = concatenated_values
    values = inner_factory(values, dtype=dtype, shape=(len(values),) + inner_shape, name='values')
    for row_splits in reversed(nested_splits):
        values = ragged_factory(values, row_splits)
    return values

def make_constraint(constraint):
    """Convert the constraint into the appropriate Constraint object.

    Parameters
    ----------
    constraint : object
        The constraint to convert.

    Returns
    -------
    constraint : instance of _Constraint
        The converted constraint.
    """
    if isinstance(constraint, str) and constraint == 'array-like':
        return _ArrayLikes()
    if isinstance(constraint, str) and constraint == 'sparse matrix':
        return _SparseMatrices()
    if isinstance(constraint, str) and constraint == 'random_state':
        return _RandomStates()
    if constraint is callable:
        return _Callables()
    if constraint is None:
        return _NoneConstraint()
    if isinstance(constraint, type):
        return _InstancesOf(constraint)
    if <MASK>:
        return constraint
    if isinstance(constraint, str) and constraint == 'boolean':
        return _Booleans()
    if isinstance(constraint, str) and constraint == 'verbose':
        return _VerboseHelper()
    if isinstance(constraint, str) and constraint == 'cv_object':
        return _CVObjects()
    if isinstance(constraint, Hidden):
        constraint = make_constraint(constraint.constraint)
        constraint.hidden = True
        return constraint
    if isinstance(constraint, str) and constraint == 'nan' or (isinstance(constraint, float) and np.isnan(constraint)):
        return _NanConstraint()
    raise ValueError(f'Unknown constraint type: {constraint}')

def _check_container_source(container_type, source_file, original_source):
    try:
        current_source = ''.join(get_source_lines_and_file(container_type)[0])
    except Exception:
        warnings.warn("Couldn't retrieve source code for container of type " + container_type.__name__ + ". It won't be checked for correctness upon loading.")
        return
    if <MASK>:
        if container_type.dump_patches:
            file_name = container_type.__name__ + '.patch'
            diff = difflib.unified_diff(current_source.split('\n'), original_source.split('\n'), source_file, source_file, lineterm='')
            lines = '\n'.join(diff)
            try:
                with open(file_name, 'a+') as f:
                    file_size = f.seek(0, 2)
                    f.seek(0)
                    if file_size == 0:
                        f.write(lines)
                    elif file_size != len(lines) or f.read() != lines:
                        raise OSError
                msg = 'Saved a reverse patch to ' + file_name + '. Run `patch -p0 < ' + file_name + '` to revert your changes.'
            except OSError:
                msg = "Tried to save a patch, but couldn't create a writable file " + file_name + ". Make sure it doesn't exist and your working directory is writable."
        else:
            msg = "you can retrieve the original source code by accessing the object's source attribute or set `torch.nn.Module.dump_patches = True` and use the patch tool to revert the changes."
        msg = f"source code of class '{torch.typename(container_type)}' has changed. {msg}"
        warnings.warn(msg, SourceChangeWarning)

def _clone_aliasing_output(inputs: Sequence[Any], outputs: Sequence[Any]):
    seen_input_storages = {StorageWeakRef(t._typed_storage()) for t in inputs if isinstance(t, torch.Tensor)}
    seen_output_storages = set()
    final_outputs = []
    for out in outputs:
        if <MASK>:
            out_storage = StorageWeakRef(out._typed_storage())
            if out_storage in seen_input_storages or out_storage in seen_output_storages:
                out = out.clone()
            seen_output_storages.add(StorageWeakRef(out._typed_storage()))
        final_outputs.append(out)
    return final_outputs

def standardize_input_data(data, names, shapes=None, check_batch_axis=True, exception_prefix=''):
    """Normalizes inputs and targets provided by users.

  Users may pass data as a list of arrays, dictionary of arrays,
  or as a single array. We normalize this to an ordered list of
  arrays (same order as `names`), while checking that the provided
  arrays have shapes that match the network's expectations.

  Args:
      data: User-provided input data (polymorphic).
      names: List of expected array names.
      shapes: Optional list of expected array shapes.
      check_batch_axis: Boolean; whether to check that the batch axis of the
        arrays matches the expected value found in `shapes`.
      exception_prefix: String prefix used for exception formatting.

  Returns:
      List of standardized input arrays (one array per model input).

  Raises:
      ValueError: in case of improperly formatted user-provided data.
  """
    try:
        data_len = len(data)
    except TypeError:
        data_len = None
    if not names:
        if data_len and (not isinstance(data, dict)):
            raise ValueError('Error when checking model ' + exception_prefix + ': expected no data, but got:', data)
        return []
    if data is None:
        return [None for _ in range(len(names))]
    if isinstance(data, dict):
        try:
            data = [data[x].values if data[x].__class__.__name__ == 'DataFrame' else data[x] for x in names]
        except KeyError as e:
            raise ValueError('No data provided for "' + e.args[0] + '". Need data for each key in: ' + str(names))
    elif isinstance(data, (list, tuple)):
        if isinstance(data[0], (list, tuple)):
            data = [numpy_compat.np_asarray(d) for d in data]
        elif len(names) == 1 and isinstance(data[0], (float, int)):
            data = [numpy_compat.np_asarray(data)]
        else:
            data = [x.values if x.__class__.__name__ == 'DataFrame' else x for x in data]
    else:
        data = data.values if data.__class__.__name__ == 'DataFrame' else data
        data = [data]
    if shapes is not None:
        data = [standardize_single_array(x, shape) for (x, shape) in zip(data, shapes)]
    else:
        data = [standardize_single_array(x) for x in data]
    if len(data) != len(names):
        if data and hasattr(data[0], 'shape'):
            raise ValueError('Error when checking model ' + exception_prefix + ': the list of Numpy arrays that you are passing to your model is not the size the model expected. Expected to see ' + str(len(names)) + ' array(s), ' + 'for inputs ' + str(names) + ' but instead got the following list of ' + str(len(data)) + ' arrays: ' + str(data)[:200] + '...')
        elif <MASK>:
            raise ValueError('Error when checking model ' + exception_prefix + ': you are passing a list as input to your model, but the model expects a list of ' + str(len(names)) + ' Numpy arrays instead. The list you passed was: ' + str(data)[:200])
        elif len(data) == 1 and (not hasattr(data[0], 'shape')):
            raise TypeError('Error when checking model ' + exception_prefix + ': data should be a Numpy array, or list/dict of Numpy arrays. Found: ' + str(data)[:200] + '...')
        elif len(names) == 1:
            data = [numpy_compat.np_asarray(data)]
    if shapes:
        for i in range(len(names)):
            if shapes[i] is not None:
                if tensor_util.is_tf_type(data[i]):
                    tensorshape = data[i].shape
                    if not tensorshape:
                        continue
                    data_shape = tuple(tensorshape.as_list())
                elif is_composite_or_composite_value(data[i]):
                    tensorshape = get_composite_shape(data[i])
                    data_shape = tuple(tensorshape.as_list())
                else:
                    data_shape = data[i].shape
                shape = shapes[i]
                if len(data_shape) != len(shape):
                    raise ValueError('Error when checking ' + exception_prefix + ': expected ' + names[i] + ' to have ' + str(len(shape)) + ' dimensions, but got array with shape ' + str(data_shape))
                if not check_batch_axis:
                    data_shape = data_shape[1:]
                    shape = shape[1:]
                for (dim, ref_dim) in zip(data_shape, shape):
                    if ref_dim != dim and ref_dim is not None and (dim is not None):
                        raise ValueError('Error when checking ' + exception_prefix + ': expected ' + names[i] + ' to have shape ' + str(shape) + ' but got array with shape ' + str(data_shape))
    return data

def gnu_version_match(self, version_string):
    """Handle the different versions of GNU fortran compilers"""
    while version_string.startswith('gfortran: warning'):
        version_string = version_string[version_string.find('\n') + 1:].strip()
    if len(version_string) <= 20:
        m = re.search('([0-9.]+)', version_string)
        if m:
            if version_string.startswith('GNU Fortran'):
                return ('g77', m.group(1))
            elif <MASK>:
                return ('gfortran', m.group(1))
    else:
        m = re.search('GNU Fortran\\s+95.*?([0-9-.]+)', version_string)
        if m:
            return ('gfortran', m.group(1))
        m = re.search('GNU Fortran.*?\\-?([0-9-.]+\\.[0-9-.]+)', version_string)
        if m:
            v = m.group(1)
            if v.startswith(('0', '2', '3')):
                return ('g77', v)
            else:
                return ('gfortran', v)
    err = 'A valid Fortran version was not found in this string:\n'
    raise ValueError(err + version_string)

def _validate_device_maps(all_names, all_device_counts, all_device_maps, all_devices, is_static_group=True):
    for node in all_names:
        devices = all_devices[node]
        if len(set(devices)) != len(devices):
            raise ValueError(f'Node {node} has duplicated devices\ndevices = {devices}')
        if not _tensorpipe_validate_devices(devices, all_device_counts[node]):
            raise ValueError(f'Node {node} has devices with invalid indices\ndevices = {devices}\ndevice count = {all_device_counts[node]}')
    for source_node in all_names:
        if is_static_group and (not set(all_device_maps[source_node].keys()).issubset(all_names)):
            raise ValueError(f'Node {source_node} has invalid target node names in its device maps\ndevice maps = {all_device_maps[source_node].keys()}\nnode names = {all_names}')
        for (target_node, map_) in all_device_maps[source_node].items():
            if len(set(map_.values())) != len(map_):
                raise ValueError(f'Node {source_node} has duplicated target devices in its device map for {target_node}\ndevice map = {map_}')
            if all_devices[source_node]:
                if not set(map_.keys()).issubset(all_devices[source_node]):
                    raise ValueError(f'Node {source_node} has unexpected source devices in its device map for {target_node}\ndevice map = {map_}\ndevices = {all_devices[source_node]}')
            elif not _tensorpipe_validate_devices(map_.keys(), all_device_counts[source_node]):
                raise ValueError(f'Node {source_node} has source devices with invalid indices in its device map for {target_node}\ndevice map = {map_}\ndevice count = {all_device_counts[source_node]}')
            if all_devices.get(target_node, []):
                if not set(map_.values()).issubset(all_devices[target_node]):
                    raise ValueError(f'Node {source_node} has unexpected target devices in its device map for {target_node}\ndevice map = {map_}\ndevices = {all_devices[target_node]}')
            elif <MASK>:
                raise ValueError(f'Node {source_node} has target devices with invalid indices in its device map for {target_node}\ndevice map = {map_}\ndevice count = {all_device_counts[target_node]}')

