    else:
        return None

def forward(self, x, y):
    """
        """
    if len(x) > 1:
        x = x[0]
    if <MASK>:
        y = y[0]
    self.stats['quantized'].append(x.detach())
    self.stats['float'].append(y.detach())

@functools.cache
def generate_apply_looper(func, nopython=True, nogil=True, parallel=False):
    if TYPE_CHECKING:
        import numba
    else:
        numba = import_optional_dependency('numba')
    nb_compat_func = jit_user_function(func)

    @numba.jit(nopython=nopython, nogil=nogil, parallel=parallel)
    def nb_looper(values, axis, *args):
        if <MASK>:
            first_elem = values[:, 0]
            dim0 = values.shape[1]
        else:
            first_elem = values[0]
            dim0 = values.shape[0]
        res0 = nb_compat_func(first_elem, *args)
        buf_shape = (dim0,) + np.atleast_1d(np.asarray(res0)).shape
        if axis == 0:
            buf_shape = buf_shape[::-1]
        buff = np.empty(buf_shape)
        if axis == 1:
            buff[0] = res0
            for i in numba.prange(1, values.shape[0]):
                buff[i] = nb_compat_func(values[i], *args)
        else:
            buff[:, 0] = res0
            for j in numba.prange(1, values.shape[1]):
                buff[:, j] = nb_compat_func(values[:, j], *args)
        return buff
    return nb_looper

@register_op_impl(aten.select.int)
def meta_select(fake_mode, func, self, dim, index):
    from torch.fx.experimental.symbolic_shapes import guard_or_false
    if self.is_sparse:
        return NotImplemented
    ndim = self.dim()
    torch._check_index(ndim != 0, lambda : 'select() cannot be applied to a 0-dim tensor.')
    dim = dim if dim >= 0 else dim + ndim
    size = self.size(dim)
    new_size = list(self.size())
    new_stride = list(self.stride())
    new_storage_offset = None
    if guard_or_false(index >= 0):
        new_storage_offset = self.storage_offset() + index * new_stride[dim]
    elif <MASK>:
        new_storage_offset = self.storage_offset() + (index + size) * new_stride[dim]
    if new_storage_offset is None:
        if fake_mode.shape_env is None or (not fake_mode.shape_env.allow_scalar_outputs and (not fake_mode.allow_scalar_outputs)):
            raise DataDependentOutputException(func)
        new_storage_offset = fake_mode.shape_env.create_unbacked_symint()
    del new_size[dim]
    del new_stride[dim]
    assert new_storage_offset is not None
    return self.as_strided(new_size, new_stride, new_storage_offset)

def backward_maybe_with_nosync(self, backward_type, bwd_kwargs: dict, last_backward: bool=False) -> tuple[tuple[Optional[torch.Tensor], ...], Optional[list[dict[str, Any]]]]:
    """
        Whether using PP with FSDP, DDP, or replicate there are some runtime differences between the last backward step and the
        other steps.  Namely, we need to accumulate gradients on previous steps and reduce them on the last step, but
        there are additional state-variables and performance considerations depending on the data parallelism used.
        This helper should adapt any pipeline parallel schedule to work with common/supported data parallel libraries.
        """

    def perform_backward(backward_type) -> Callable[[], tuple[tuple[Optional[torch.Tensor], ...], Optional[list[dict[str, Any]]]]]:
        if <MASK>:
            return lambda : (stage_backward(bwd_kwargs['stage_output'], bwd_kwargs['output_grads'], bwd_kwargs['input_values']), None)
        elif backward_type == 'input':
            return lambda : stage_backward_input(bwd_kwargs['stage_output'], bwd_kwargs['output_grads'], bwd_kwargs['input_values'], self.submod.parameters())
        elif backward_type == 'weight':
            return lambda : (stage_backward_weight(self.submod.parameters(), bwd_kwargs['param_groups']), None)
        else:
            raise RuntimeError(f'Unknown backward type: {backward_type}')
    if isinstance(self.submod, DistributedDataParallel):
        if last_backward:
            self.submod.reducer.prepare_for_backward(list(torch.nn.parallel.distributed._find_tensors(bwd_kwargs['stage_output'])))
            result = perform_backward(backward_type)()
        else:
            with self.submod.no_sync():
                result = perform_backward(backward_type)()
    elif isinstance(self.submod, FSDPModule):
        self.submod.set_is_last_backward(False)
        self.submod.set_reshard_after_backward(False)
        self.submod.set_requires_gradient_sync(False)
        result = perform_backward(backward_type)()
    else:
        result = perform_backward(backward_type)()
    (grads, param_groups) = result
    return (grads, param_groups)

@register_jagged_func(torch.ops.aten.index_put.default, 'input: jt_all, indices: any, values: t, accumulate: any?')
@register_jagged_func(torch.ops.aten.index_put_.default, 'input: jt_all, indices: any, values: t, accumulate: any?')
def index_put_(func, *args, **kwargs):
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    inp: NestedTensor = new_kwargs.pop('input')
    indices = new_kwargs.pop('indices')
    assert len(indices) <= inp.dim()
    if len(indices) < inp._ragged_idx + 1:
        if not inp.is_contiguous():
            raise RuntimeError('index_put(): If ragged dimension is not part of indices, this only works on contiguous NJTs')
        from .nested_tensor import nested_from_padded
        min_seqlen = inp._maybe_min_seqlen
        max_seqlen = inp._maybe_max_seqlen
        padded_max_S = max_seqlen
        total_L = inp._values.shape[inp._ragged_idx - 1]
        if padded_max_S is None:
            padded_max_S = total_L
        padded_shape = (*inp.shape[:inp._ragged_idx], padded_max_S, *inp.shape[inp._ragged_idx + 1:])
        padded_inp = inp.to_padded_tensor(0.0, output_size=padded_shape)
        new_njt = nested_from_padded(func(padded_inp, indices, **new_kwargs), offsets=inp._offsets, ragged_idx=inp._ragged_idx, sum_S=total_L, min_seqlen=min_seqlen, max_seqlen=max_seqlen)
        if <MASK>:
            inp._values.copy_(new_njt.values())
            return inp
        return new_njt
    if inp.lengths() is None:
        lengths = inp.offsets().diff()
    else:
        lengths = inp.lengths()
    torch._assert_async(torch.all(indices[inp._ragged_idx] < lengths), 'Some indices in the ragged dimension are out of bounds!')
    ragged_indices = inp.offsets()[indices[0]] + indices[inp._ragged_idx]
    func_indices = indices[1:inp._ragged_idx] + [ragged_indices] + indices[inp._ragged_idx + 1:]
    if func == torch.ops.aten.index_put_.default:
        inp._values = func(inp._values, func_indices, **new_kwargs)
        return inp
    return NestedTensor(func(inp._values, func_indices, **new_kwargs), **extract_kwargs(inp))

@no_type_check
def _sharded_pre_load_state_dict_hook(module: nn.Module, fsdp_state: _FSDPState, state_dict: dict[str, Any], prefix: str) -> None:
    """
    The hook combines the unflattened, sharded parameters (ShardedTensor) to
    a new FlatParameter and shards the new FlatParameter to the local chunk.
    """
    _lazy_init(fsdp_state, module)
    if <MASK>:
        _replace_by_prefix(state_dict, prefix, prefix + f'{FSDP_PREFIX}')
    if not _has_fsdp_params(fsdp_state, module):
        return
    handle = _module_handle(fsdp_state, module)
    if not handle.uses_sharded_strategy:
        raise RuntimeError('load_sharded_state_dict can only be called when parameters are flattened and sharded.')
    fqn_to_param_ext = dict(zip(handle.flat_param._fqns, handle.flat_param._param_extensions))
    for (fqn, _, _) in _param_name_infos(module, fsdp_state):
        if not _is_composable(fsdp_state):
            fqn_from_global_root = f'{prefix}{FSDP_PREFIX}{fqn}'
        else:
            fqn_from_global_root = f'{prefix}{fqn}'
        try:
            param = state_dict.pop(fqn_from_global_root)
        except KeyError:
            logger.warning(f'Did not find param with FQN {fqn_from_global_root}, skipping it. The weight will not be filled if you expect it to be.')
            continue
        if not fsdp_state._state_dict_config._use_dtensor:
            (param, shards) = _ext_pre_load_state_dict_transform(param, fsdp_state._fsdp_extension)
            if len(shards) >= 2:
                raise AssertionError(f'Expects 0 or 1 shard per rank but got {len(shards)} shards on rank {fsdp_state.rank}.')
            param_numel = param.size().numel()
            dim_0_size = param.size()[0]
            chunk_size = math.ceil(dim_0_size / fsdp_state.world_size) * param_numel // dim_0_size
            if len(shards) == 1:
                local_tensor = shards[0].tensor.flatten()
                with SimpleProfiler.profile(SimpleProfiler.Type.H2D):
                    local_tensor = local_tensor.to(fsdp_state.compute_device)
                num_padding = chunk_size - local_tensor.numel()
                if num_padding > 0:
                    local_tensor = F.pad(local_tensor, [0, num_padding])
            else:
                local_tensor = torch.zeros(chunk_size, dtype=param.dtype, device=fsdp_state.compute_device)
            tensor = torch.empty(chunk_size * fsdp_state.world_size, dtype=local_tensor.dtype, device=fsdp_state.compute_device)
            with SimpleProfiler.profile(SimpleProfiler.Type.ALLGATHER):
                dist.all_gather_into_tensor(tensor, local_tensor, group=fsdp_state.process_group)
            tensor = tensor.narrow(0, 0, param_numel).reshape(param.size())
            state_dict[fqn_from_global_root] = tensor
        else:
            if param.device != fsdp_state._device_mesh.device_type:
                param = param.to(fsdp_state._device_mesh.device_type)
            root_mesh = fsdp_state._device_mesh._get_root_mesh()
            local_tensor = _ext_all_gather_dtensor(param, root_mesh, fsdp_state._fsdp_extension)
            if fqn_to_param_ext.get(fqn) is not None:
                ext = fqn_to_param_ext[fqn]
                local_tensor = _ext_post_unflatten_transform(local_tensor, ext, fsdp_state._fsdp_extension)
            state_dict[fqn_from_global_root] = local_tensor
    with SimpleProfiler.profile('_enter_unshard_params_ctx'):
        _enter_unshard_params_ctx(module, fsdp_state, writeback=True)

def enforce_comm_ordering_for_fsdp(snodes: list[torch._inductor.scheduler.BaseSchedulerNode], name_to_buf: dict[str, torch._inductor.scheduler.SchedulerBuffer], name_to_fused_node: dict[str, BaseSchedulerNode]) -> list[torch._inductor.scheduler.BaseSchedulerNode]:
    from . import scheduler
    new_order: list[BaseSchedulerNode] = []
    scheduled = OrderedSet[Any]()
    ag_exists = False
    rs_exists = False
    ag_grouped_node_to_wait_grouped_node = {}
    rs_grouped_node_to_wait_grouped_node = {}
    snode_name_to_final_snode = {}

    def _create_group_node(snodes_to_group):
        group_node = scheduler.GroupedSchedulerNode.create(snodes_to_group)
        for snode in snodes_to_group:
            snode_name_to_final_snode[snode.get_name()] = group_node
        snode_name_to_final_snode[group_node.get_name()] = group_node
        return group_node
    for snode in snodes:
        if <MASK>:
            ag_exists = True
            ag_snode = snode
            ag_related_snode_set: OrderedSet[scheduler.BaseSchedulerNode] = OrderedSet()
            find_recursive_deps_of_node(ag_snode, ag_related_snode_set, name_to_buf, name_to_fused_node)
            allowed_ops = OrderedSet([torch.ops._c10d_functional.all_gather_into_tensor_out.default, torch.ops._c10d_functional.wait_tensor.default, torch.ops.fsdp.split_with_sizes_copy.default])
            find_recursive_users_of_node(ag_snode, ag_related_snode_set, name_to_buf, name_to_fused_node, criteria_cb=lambda x: not (isinstance(x, scheduler.NopKernelSchedulerNode) or (isinstance(x, scheduler.ExternKernelSchedulerNode) and x.node.op_overload in allowed_ops)))
            ag_related_snodes = sorted(ag_related_snode_set, key=lambda x: get_op_idx(x))
            end_idx_of_current_ag_block = len(ag_related_snodes)
            copy_out_count = 0
            for i in range(len(ag_related_snodes)):
                cur_snode = ag_related_snodes[i]
                if is_fallback_op(cur_snode.node, torch.ops.fsdp.split_with_sizes_copy.default):
                    copy_out_count += 1
                if copy_out_count > 1:
                    end_idx_of_current_ag_block = i
                    break
            ag_related_snodes = ag_related_snodes[:end_idx_of_current_ag_block]
            wait_node_idx = None
            for i in range(len(ag_related_snodes) - 1):
                if isinstance(ag_related_snodes[i + 1].node, ir._WaitKernel):
                    wait_node_idx = i + 1
                    break
            assert wait_node_idx is not None
            ag_group_node = _create_group_node(ag_related_snodes[:wait_node_idx])
            ag_wait_group_node = _create_group_node(ag_related_snodes[wait_node_idx:])
            ag_grouped_node_to_wait_grouped_node[ag_group_node] = ag_wait_group_node
        elif is_fallback_op(snode.node, torch.ops.fsdp.chunk_cat.default):
            rs_exists = True
            rs_snode = snode
            rs_related_snode_set: OrderedSet[scheduler.BaseSchedulerNode] = OrderedSet()
            find_recursive_users_of_node(rs_snode, rs_related_snode_set, name_to_buf, name_to_fused_node)
            rs_related_snodes = sorted(rs_related_snode_set, key=lambda x: get_op_idx(x))
            wait_node_idx = None
            for i in range(len(rs_related_snodes) - 1):
                if isinstance(rs_related_snodes[i + 1].node, ir._WaitKernel):
                    wait_node_idx = i + 1
                    break
            assert wait_node_idx is not None
            rs_group_node = _create_group_node(rs_related_snodes[:wait_node_idx])
            rs_wait_group_node = _create_group_node(rs_related_snodes[wait_node_idx:])
            rs_grouped_node_to_wait_grouped_node[rs_group_node] = rs_wait_group_node
    assert len(snode_name_to_final_snode) > 0
    if ag_exists:
        assert len(ag_grouped_node_to_wait_grouped_node) > 0
    if rs_exists:
        assert len(rs_grouped_node_to_wait_grouped_node) > 0
    for snode in snodes:
        if snode.get_name() in snode_name_to_final_snode:
            snode = snode_name_to_final_snode[snode.get_name()]
        if snode in scheduled:
            continue
        new_order.append(snode)
        scheduled.add(snode)
    prev_ag_wait = None
    for (ag_group_node, wait_group_node) in ag_grouped_node_to_wait_grouped_node.items():
        if prev_ag_wait is not None:
            mutating_buf = next(iter(ag_group_node.get_buffer_names()))
            for o in prev_ag_wait.get_outputs():
                ag_group_node.add_fake_dep(WeakDep(o.get_name(), mutating_buf=mutating_buf, is_fake=True))
        prev_ag_wait = wait_group_node
    prev_rs_wait = None
    for (rs_group_node, wait_group_node) in rs_grouped_node_to_wait_grouped_node.items():
        if prev_rs_wait is not None:
            mutating_buf = next(iter(rs_group_node.get_buffer_names()))
            for o in prev_rs_wait.get_outputs():
                rs_group_node.add_fake_dep(WeakDep(o.get_name(), mutating_buf=mutating_buf, is_fake=True))
        prev_rs_wait = wait_group_node
    return new_order

def compare_with_numpy(self, torch_fn, np_fn, tensor_like, device=None, dtype=None, **kwargs):
    assert TEST_NUMPY
    if isinstance(tensor_like, torch.Tensor):
        assert device is None
        assert dtype is None
        t_cpu = tensor_like.detach().cpu()
        if t_cpu.dtype is torch.bfloat16:
            t_cpu = t_cpu.float()
        a = t_cpu.numpy()
        t = tensor_like
    else:
        d = copy.copy(torch_to_numpy_dtype_dict)
        d[torch.bfloat16] = np.float32
        a = np.array(tensor_like, dtype=d[dtype])
        t = torch.tensor(tensor_like, device=device, dtype=dtype)
    np_result = np_fn(a)
    torch_result = torch_fn(t).cpu()
    if <MASK>:
        try:
            np_result = torch.from_numpy(np_result)
        except Exception:
            np_result = torch.from_numpy(np_result.copy())
        if t.dtype is torch.bfloat16 and torch_result.dtype is torch.bfloat16 and (np_result.dtype is torch.float):
            torch_result = torch_result.to(torch.float)
    self.assertEqual(np_result, torch_result, **kwargs)

def check_file(filename: str) -> list[LintMessage]:
    path = Path(filename).absolute()
    basename = path.name.lower()
    if basename in ('cmakelists.txt', 'cmakelists.txt.in') or basename.endswith(('.cmake', '.cmake.in')):
        return check_cmake(path)
    if basename == 'pyproject.toml':
        return check_pyproject(path)
    if <MASK>:
        return check_requirements(path)
    return []

def _single_tensor_sgd(params: list[Tensor], grads: list[Tensor], momentum_buffer_list: list[Optional[Tensor]], grad_scale: Optional[Tensor], found_inf: Optional[Tensor], *, weight_decay: float, momentum: float, lr: float, dampening: float, nesterov: bool, maximize: bool, has_sparse_grad: bool):
    if grad_scale is not None or found_inf is not None:
        raise AssertionError('Expected grad_scale and found_inf to be None')
    if not torch.jit.is_scripting():
        lr = _to_scalar(lr)
    for (i, param) in enumerate(params):
        grad = grads[i] if not maximize else -grads[i]
        if weight_decay != 0:
            if isinstance(weight_decay, Tensor):
                if weight_decay.requires_grad:
                    grad = grad.addcmul_(param.clone(), weight_decay)
                else:
                    grad = grad.add(param, alpha=weight_decay)
            else:
                grad = grad.add(param, alpha=weight_decay)
        if momentum != 0:
            buf = momentum_buffer_list[i]
            if buf is None:
                buf = grad.detach().clone()
                momentum_buffer_list[i] = buf
            else:
                buf.mul_(momentum).add_(grad, alpha=1 - dampening)
            if <MASK>:
                grad = grad.add(buf, alpha=momentum)
            else:
                grad = buf
        if isinstance(lr, Tensor):
            if lr.requires_grad:
                param.addcmul_(grad, lr, value=-1)
            else:
                param.add_(grad, alpha=-lr)
        else:
            param.add_(grad, alpha=-lr)

def __call__(self, value):
    keys = set(value)
    missing_keys = self.keys - keys
    if <MASK>:
        raise ValidationError(self.messages['missing_keys'], code='missing_keys', params={'keys': ', '.join(missing_keys)})
    if self.strict:
        extra_keys = keys - self.keys
        if extra_keys:
            raise ValidationError(self.messages['extra_keys'], code='extra_keys', params={'keys': ', '.join(extra_keys)})

def issubtype(left, right, recursive=True):
    """
    Check if the left-side type is a subtype of the right-side type.

    If any of type is a composite type like `Union` and `TypeVar` with
    bounds, it would be expanded into a list of types and check all
    of left-side types are subtypes of either one from right-side types.
    """
    left = TYPE2ABC.get(left, left)
    right = TYPE2ABC.get(right, right)
    if right is Any or left == right:
        return True
    if <MASK>:
        if getattr(right, '__origin__', None) is Generic:
            return True
    if right is type(None):
        return False
    constraints = _decompose_type(right)
    if len(constraints) == 0 or Any in constraints:
        return True
    if left is Any:
        return False
    variants = _decompose_type(left)
    if len(variants) == 0:
        return False
    return all((_issubtype_with_constraints(variant, constraints, recursive) for variant in variants))

@property
def metrics_names(self):
    """Returns the model's display labels for all outputs."""
    metrics_names = ['loss']
    if self._is_compiled:
        if not hasattr(self, '_v1_compile_was_called'):
            return super(Model, self).metrics_names
        if <MASK>:
            metrics_names.extend([e.loss_name() for e in self._training_endpoints if not e.should_skip_target()])
    metrics_names += [m.name for m in self.metrics]
    return metrics_names

