def get_inner_triton_kernels(fn: Callable[..., Any]) -> list[object]:
    """
    Inspect the source of an arbitrary callable passed to torch._library.triton_op,
    and grab all of the triton kernels that are wrapped inside of it.

    TODO: This check is best effort. It does *not* handle the case where the triton
    kernel is hidden behind recursive function calls.
    """

    def find_triton_kernels(fn: Callable[..., Any]) -> list[object]:
        try:
            source = inspect.getsource(fn)
        except (OSError, TypeError):
            return []
        from torch._inductor.utils import IndentedBuffer
        buffer = IndentedBuffer()
        buffer.splice(source, strip=True)
        tree = ast.parse(buffer.getrawvalue())

        class Visitor(ast.NodeVisitor):

            def __init__(self) -> None:
                self.triton_kernels: list[Any] = []

            def visit_Call(self, node: ast.Call) -> None:
                triton_func_names = ('capture_triton', 'wrap_triton')
                if isinstance(node.func, ast.Attribute):
                    attr = node.func
                    if <MASK>:
                        if node.args and isinstance(node.args[0], ast.Name):
                            self.triton_kernels.append(node.args[0].id)
                elif isinstance(node.func, ast.Name):
                    if node.func.id in triton_func_names:
                        if node.args and isinstance(node.args[0], ast.Name):
                            self.triton_kernels.append(node.args[0].id)
                self.generic_visit(node)
        collector = Visitor()
        collector.visit(tree)
        closure_vars = inspect.getclosurevars(fn)
        resolved = []
        for name in collector.triton_kernels:
            if name in closure_vars.nonlocals:
                resolved.append(closure_vars.nonlocals[name])
            elif name in closure_vars.globals:
                resolved.append(closure_vars.globals[name])
            elif name in closure_vars.builtins:
                resolved.append(closure_vars.builtins[name])
        return resolved
    return find_triton_kernels(fn)

@property
def updates(self):
    collected_updates = []
    all_layers = self._flatten_layers()
    with backend.get_graph().as_default():
        for layer in all_layers:
            if not layer.trainable and (not layer.stateful):
                continue
            for u in layer._updates:
                if <MASK>:
                    try:
                        u = u()
                    except ValueError as e:
                        if 'InaccessibleTensorError' in type(e).__name__:
                            base_layer_utils.check_graph_consistency(method='add_update', force_raise=True)
                        raise
                base_layer_utils.check_graph_consistency(u, method='add_update')
                collected_updates.append(u)
    return collected_updates

def _out_wrapper(fn: Callable[_P, _T]) -> Callable[_P, _T]:
    """
        Adds the out parameter to a Python reference.
        """
    out_type = TensorLikeType if is_tensor else GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
    bc_out_type = TensorLikeType if is_tensor else types.GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
    return_type = TensorLikeType if is_tensor else NamedTuple(f'return_types_{fn.__name__}', [(o, TensorLikeType) for o in out_names])
    sig = inspect.signature(fn)
    factory_kwargs = ('device', 'dtype')
    is_factory_fn = all((p in sig.parameters for p in factory_kwargs))

    @wraps(fn)
    def _fn(*args: _P.args, **kwargs: _P.kwargs):
        out = kwargs.pop('out', None)
        if is_factory_fn and out is not None:
            for k in factory_kwargs:
                out_attr = getattr(out, k)
                if k not in kwargs:
                    kwargs[k] = out_attr

        def maybe_check_copy_devices(out):
            if isinstance(out, TensorLike) and isinstance(args[0], TensorLike):
                check_copy_devices(copy_from=args[0], copy_to=out)
        if <MASK>:
            for o in out:
                maybe_check_copy_devices(o)
        else:
            maybe_check_copy_devices(out)
        if pass_is_out:
            result = fn(*args, is_out=out is not None, **kwargs)
        else:
            result = fn(*args, **kwargs)
        if result is NotImplemented:
            return NotImplemented
        assert isinstance(result, TensorLike) and is_tensor or (isinstance(result, tuple) and len(result) == len(out_names)) or (fn.__name__ == 'unbind' and isinstance(result, (list, tuple)))
        if out is not None:
            if is_tensor and fn.__name__ != 'unbind':
                assert isinstance(out, TensorLike)
                _maybe_resize_out(out, result.shape, maybe_compute_memory_format(result))
                _safe_copy_out(copy_from=result, copy_to=out, exact_dtype=exact_dtype)
            else:
                if fn.__name__ != 'unbind':
                    assert isinstance(out, tuple)
                else:
                    assert isinstance(out, (list, tuple))
                torch._check_type(len(out) == len(result), lambda : f'expected tuple of {len(result)} elements but got {len(out)}')
                for (r, o) in zip(result, out):
                    _maybe_resize_out(o, r.shape, maybe_compute_memory_format(r))
                    _safe_copy_out(copy_from=r, copy_to=o, exact_dtype=exact_dtype)
        else:
            out = result
        return out if is_tensor else return_type(*out)
    out_param = inspect.Parameter('out', kind=inspect.Parameter.KEYWORD_ONLY, default=None, annotation=out_type)
    assert isinstance(sig.return_annotation, (str, TypeVar)) or sig.return_annotation in (sig.empty, out_type, bc_out_type)
    params = (*sig.parameters.values(), out_param)
    params = sorted(params, key=lambda p: p.kind)
    _fn.__signature__ = inspect.Signature(parameters=params, return_annotation=return_type)
    _fn.__annotations__ = dict(getattr(fn, '__annotations__', {}))
    _fn.__annotations__['out'] = out_type
    _fn.__annotations__['return'] = return_type
    if is_tensor and out_names != default_out_names:
        _fn.__annotations__[CustomOutParamAnnotation] = out_names[0]
    _fn._torch_decompositions_out_wrapper = f'This function is wrapped by {out_wrapper.__module__}.out_wrapper'
    return _fn

def linkcode_resolve(domain, info):
    """
    Determine the URL corresponding to Python object
    """
    if domain != 'py':
        return None
    modname = info['module']
    fullname = info['fullname']
    submod = sys.modules.get(modname)
    if submod is None:
        return None
    obj = submod
    for part in fullname.split('.'):
        try:
            obj = getattr(obj, part)
        except Exception:
            return None
    try:
        unwrap = inspect.unwrap
    except AttributeError:
        pass
    else:
        obj = unwrap(obj)
    fn = None
    lineno = None
    if isinstance(obj, type):
        if <MASK>:
            fn = _get_c_source_file(obj)
        if hasattr(obj, '_module_source'):
            (obj.__module__, obj._module_source) = (obj._module_source, obj.__module__)
    if fn is None:
        try:
            fn = inspect.getsourcefile(obj)
        except Exception:
            fn = None
        if not fn:
            return None
        module = inspect.getmodule(obj)
        if module is not None and (not module.__name__.startswith('numpy')):
            return None
        try:
            (source, lineno) = inspect.getsourcelines(obj)
        except Exception:
            lineno = None
        fn = relpath(fn, start=dirname(numpy.__file__))
    if lineno:
        linespec = '#L%d-L%d' % (lineno, lineno + len(source) - 1)
    else:
        linespec = ''
    if isinstance(obj, type) and hasattr(obj, '_module_source'):
        (obj.__module__, obj._module_source) = (obj._module_source, obj.__module__)
    if 'dev' in numpy.__version__:
        return f'https://github.com/numpy/numpy/blob/main/numpy/{fn}{linespec}'
    else:
        return 'https://github.com/numpy/numpy/blob/v%s/numpy/%s%s' % (numpy.__version__, fn, linespec)

