@register_decomposition(aten.addr)
@out_wrapper()
@elementwise_type_promotion_wrapper(type_promoting_args=('self', 'vec1', 'vec2'), type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT)
def addr(self: TensorLikeType, vec1: TensorLikeType, vec2: TensorLikeType, *, beta: NumberType=1, alpha: NumberType=1) -> TensorLikeType:
    torch._check(vec1.ndim == 1, lambda : f'addr: Expected 1-D argument vec1, but got {vec1.ndim}-D')
    torch._check(vec2.ndim == 1, lambda : f'addr: Expected 1-D argument vec2, but got {vec2.ndim}-D')
    for (arg, arg_name) in ((alpha, 'alpha'), (beta, 'beta')):
        if isinstance(arg, bool):
            torch._check(utils.is_boolean_dtype(self.dtype) and utils.is_boolean_dtype(vec1.dtype) and utils.is_boolean_dtype(vec2.dtype), lambda : f'Boolean {arg_name} only supported for Boolean results.')
    self = self.expand(vec1.shape[0], vec2.shape[0])
    if <MASK>:
        torch._check(is_weakly_lesser_type(type(beta), int), lambda : f'expected bool/int beta but got {type(beta)}')
        torch._check(is_weakly_lesser_type(type(alpha), int), lambda : f'expected bool/int alpha but got {type(beta)}')
        if not beta:
            return torch.outer(vec1, vec2) if alpha else torch.full_like(self, False)
        else:
            return torch.logical_or(self, torch.outer(vec1, vec2) if alpha else torch.full_like(self, False))
    else:
        torch._check(is_weakly_lesser_type(type(beta), dtype_to_type(self.dtype)), lambda : f'cannot safely convert {type(beta)} to {self.dtype}')
        torch._check(is_weakly_lesser_type(type(alpha), dtype_to_type(self.dtype)), lambda : f'cannot safely convert {type(alpha)} to {self.dtype}')
        if beta == 0:
            return alpha * torch.outer(vec1, vec2)
        else:
            return beta * self + alpha * torch.outer(vec1, vec2)

def trim_lex(tokens):
    """
    Takes a lexed set of tokens, and removes whitespace when there is
    a directive on a line by itself:

       >>> tokens = lex('{{if x}}\\nx\\n{{endif}}\\ny', trim_whitespace=False)
       >>> tokens
       [('if x', (1, 3)), '\\nx\\n', ('endif', (3, 3)), '\\ny']
       >>> trim_lex(tokens)
       [('if x', (1, 3)), 'x\\n', ('endif', (3, 3)), 'y']
    """
    last_trim = None
    for (i, current) in enumerate(tokens):
        if isinstance(current, basestring_):
            continue
        item = current[0]
        if not statement_re.search(item) and item not in single_statements:
            continue
        if not i:
            prev = ''
        else:
            prev = tokens[i - 1]
        if i + 1 >= len(tokens):
            next_chunk = ''
        else:
            next_chunk = tokens[i + 1]
        if not isinstance(next_chunk, basestring_) or not isinstance(prev, basestring_):
            continue
        prev_ok = not prev or trail_whitespace_re.search(prev)
        if i == 1 and (not prev.strip()):
            prev_ok = True
        if last_trim is not None and last_trim + 2 == i and (not prev.strip()):
            prev_ok = 'last'
        if prev_ok and (not next_chunk or lead_whitespace_re.search(next_chunk) or (i == len(tokens) - 2 and (not next_chunk.strip()))):
            if prev:
                if <MASK>:
                    tokens[i - 1] = ''
                else:
                    m = trail_whitespace_re.search(prev)
                    prev = prev[:m.start() + 1]
                    tokens[i - 1] = prev
            if next_chunk:
                last_trim = i
                if i == len(tokens) - 2 and (not next_chunk.strip()):
                    tokens[i + 1] = ''
                else:
                    m = lead_whitespace_re.search(next_chunk)
                    next_chunk = next_chunk[m.end():]
                    tokens[i + 1] = next_chunk
    return tokens

def as_sql(self, compiler, connection):
    """
        Return the SQL version of the where clause and the value to be
        substituted in. Return '', [] if this node matches everything,
        None, [] if this node is empty, and raise EmptyResultSet if this
        node can't match anything.
        """
    result = []
    result_params = []
    if self.connector == AND:
        (full_needed, empty_needed) = (len(self.children), 1)
    else:
        (full_needed, empty_needed) = (1, len(self.children))
    if self.connector == XOR and (not connection.features.supports_logical_xor):
        lhs = self.__class__(self.children, OR)
        rhs_sum = reduce(operator.add, (Case(When(c, then=1), default=0) for c in self.children))
        if len(self.children) > 2:
            rhs_sum = Mod(rhs_sum, 2)
        rhs = Exact(1, rhs_sum)
        return self.__class__([lhs, rhs], AND, self.negated).as_sql(compiler, connection)
    for child in self.children:
        try:
            (sql, params) = compiler.compile(child)
        except EmptyResultSet:
            empty_needed -= 1
        except FullResultSet:
            full_needed -= 1
        else:
            if <MASK>:
                result.append(sql)
                result_params.extend(params)
            else:
                full_needed -= 1
        if empty_needed == 0:
            if self.negated:
                raise FullResultSet
            else:
                raise EmptyResultSet
        if full_needed == 0:
            if self.negated:
                raise EmptyResultSet
            else:
                raise FullResultSet
    conn = ' %s ' % self.connector
    sql_string = conn.join(result)
    if not sql_string:
        raise FullResultSet
    if self.negated:
        sql_string = 'NOT (%s)' % sql_string
    elif len(result) > 1 or self.resolved:
        sql_string = '(%s)' % sql_string
    return (sql_string, result_params)

def _make_mirrored(distribution=None):
    v = []
    if <MASK>:
        devices = distribution.extended.worker_devices
    else:
        devices = ['/device:GPU:0', '/device:CPU:0']
    for (d, n, init) in zip(devices, ['v', 'v/replica'], [1.0, 2.0]):
        with ops.device(d):
            v.append(variable_scope.get_variable(name=n, initializer=init, use_resource=True))
    if distribution is not None and strategy_test_lib.is_tpu_strategy(distribution):
        var_cls = tpu_values.TPUMirroredVariable
    else:
        var_cls = values_lib.MirroredVariable
    mirrored = var_cls(distribution, v, variable_scope.VariableAggregation.SUM)
    return mirrored

def validate_sparse_weights(values, weights, dtype=None):
    """Validates the passed weight tensor or creates an empty one."""
    if weights is None:
        if dtype:
            return array_ops.constant([], dtype=dtype)
        return array_ops.constant([], dtype=values.values.dtype)
    if not isinstance(weights, sparse_tensor.SparseTensor):
        raise ValueError(f'Argument `weights` must be a SparseTensor if `values` is a SparseTensor. Received weights={weights} of type: {type(weights).__name__}')
    checks = []
    if weights.dense_shape is not values.dense_shape:
        checks.append(check_ops.assert_equal(weights.dense_shape, values.dense_shape, message="'weights' and 'values' must have the same dense shape."))
    if weights.indices is not values.indices:
        checks.append(check_ops.assert_equal(weights.indices, values.indices, message="'weights' and 'values' must have the same indices."))
    if <MASK>:
        with ops.control_dependencies(checks):
            weights = array_ops.identity(weights.values)
    else:
        weights = weights.values
    return weights

@contextlib.contextmanager
def clipboard(hwnd):
    """
        Context manager that opens the clipboard and prevents
        other applications from modifying the clipboard content.
        """
    t = time.time() + 0.5
    success = False
    while time.time() < t:
        success = OpenClipboard(hwnd)
        if success:
            break
        time.sleep(0.01)
    if <MASK>:
        raise PyperclipWindowsException('Error calling OpenClipboard')
    try:
        yield
    finally:
        safeCloseClipboard()

