@parameterized.parameters(True, False)
def testDatasetsShuffledDifferently(self, use_input_fn):
    self.assertGreaterEqual(len(self.coordinator._cluster.workers), 2)
    random_seed.set_random_seed(None)

    def input_fn():
        dataset = dataset_ops.DatasetV2.range(0, 100).shuffle(100).batch(1)
        return self.strategy.experimental_distribute_dataset(dataset)
    if <MASK>:
        distributed_dataset = self.coordinator.create_per_worker_dataset(input_fn)
    else:
        distributed_dataset = self.coordinator.create_per_worker_dataset(input_fn())
    distributed_iterator = iter(distributed_dataset)
    iterator_1 = distributed_iterator._values[0]
    iterator_1 = iterator_1.fetch()
    elements_in_iterator_1 = [self.strategy.experimental_local_results(e) for e in iterator_1]
    iterator_2 = distributed_iterator._values[1]
    iterator_2 = iterator_2.fetch()
    elements_in_iterator_2 = [self.strategy.experimental_local_results(e) for e in iterator_2]
    self.assertNotAllEqual(elements_in_iterator_1, elements_in_iterator_2)

@classmethod
def eval(cls, *args):
    if len(args) % 2 != 0:
        raise AssertionError(f'expected an even number of arguments, got {len(args)}')
    dim = len(args) // 2
    sizes = args[0:dim]
    strides = args[dim:]
    from torch.fx.experimental.symbolic_shapes import eval_is_non_overlapping_and_dense
    if all((isinstance(a, sympy.Integer) for a in args)):
        return eval_is_non_overlapping_and_dense([int(a) for a in sizes], [int(a) for a in strides])
    if dim == 1:
        if strides[0].is_Number and strides[0] == 1:
            return 1
        if <MASK>:
            return 1
    if all((isinstance(a, sympy.Integer) for a in strides)):
        if dim == 0:
            raise AssertionError('dim must not be zero')
        (s_sizes, s_strides) = zip(*sorted(zip(sizes, strides), key=operator.itemgetter(1)))
        if all((isinstance(a, sympy.Integer) for a in s_sizes[:-1])):
            s_sizes = s_sizes[:-1] + (42,)
            return eval_is_non_overlapping_and_dense([int(a) for a in s_sizes], [int(a) for a in s_strides])
    return None

