    if preferred_element_type is None:
        preferred_element_type = np_utils.result_type(lhs.dtype, rhs.dtype)
    if <MASK>:
        return gen_xla_ops.xla_dot_v2(lhs, rhs, dimension_numbers=dimension_numbers.SerializeToString(), precision_config=precision_config_proto, preferred_element_type=preferred_element_type, name=name)
    return gen_xla_ops.xla_dot(lhs, rhs, dimension_numbers=dimension_numbers.SerializeToString(), precision_config=precision_config_proto, name=name)

def forward(self, input, hx=None):
    """
        Runs the forward pass.
        """
    self._update_flat_weights()
    num_directions = 2 if self.bidirectional else 1
    orig_input = input
    if isinstance(orig_input, PackedSequence):
        (input, batch_sizes, sorted_indices, unsorted_indices) = input
        max_batch_size = batch_sizes[0]
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    else:
        batch_sizes = None
        if input.dim() not in (2, 3):
            raise ValueError(f'RNN: Expected input to be 2D or 3D, got {input.dim()}D tensor instead')
        is_batched = input.dim() == 3
        batch_dim = 0 if self.batch_first else 1
        if <MASK>:
            input = input.unsqueeze(batch_dim)
            if hx is not None:
                if hx.dim() != 2:
                    raise RuntimeError(f'For unbatched 2-D input, hx should also be 2-D but got {hx.dim()}-D tensor')
                hx = hx.unsqueeze(1)
        elif hx is not None and hx.dim() != 3:
            raise RuntimeError(f'For batched 3-D input, hx should also be 3-D but got {hx.dim()}-D tensor')
        max_batch_size = input.size(0) if self.batch_first else input.size(1)
        sorted_indices = None
        unsorted_indices = None
        if hx is None:
            hx = torch.zeros(self.num_layers * num_directions, max_batch_size, self.hidden_size, dtype=input.dtype, device=input.device)
        else:
            hx = self.permute_hidden(hx, sorted_indices)
    assert hx is not None
    self.check_forward_args(input, hx, batch_sizes)
    assert self.mode == 'RNN_TANH' or self.mode == 'RNN_RELU'
    if batch_sizes is None:
        if self.mode == 'RNN_TANH':
            result = _VF.rnn_tanh(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
        else:
            result = _VF.rnn_relu(input, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional, self.batch_first)
    elif self.mode == 'RNN_TANH':
        result = _VF.rnn_tanh(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    else:
        result = _VF.rnn_relu(input, batch_sizes, hx, self._flat_weights, self.bias, self.num_layers, self.dropout, self.training, self.bidirectional)
    output = result[0]
    hidden = result[1]
    if isinstance(orig_input, PackedSequence):
        output_packed = PackedSequence(output, batch_sizes, sorted_indices, unsorted_indices)
        return (output_packed, self.permute_hidden(hidden, unsorted_indices))
    if not is_batched:
        output = output.squeeze(batch_dim)
        hidden = hidden.squeeze(1)
    return (output, self.permute_hidden(hidden, unsorted_indices))

def _skip_tensor(self, op_id, out_tensor, report_handler):
    """Returns True if we should not trace out_tensor.

    Args:
      op_id: Topological index of the op producing tensor.
      out_tensor: tf.Tensor
      report_handler: An instance of tensor_tracer_report.TTReportHandle.
    Returns:
      True if the tensor should not be traced, false otherwise.
    """
    non_numeric_tensor_types = set([dtypes.variant, dtypes.resource, dtypes.string])
    if out_tensor.dtype in non_numeric_tensor_types:
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_NON_NUMERIC_TENSOR))
        return True
    if <MASK>:
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_FEEDS_WHILELOOP_OP))
        return True
    if self._is_user_included_op(out_tensor.op):
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_USER_INCLUDED))
        if tensor_tracer_flags.TT_CHECK_FILTER.value:
            logging.info('USER_INCLUDED tensor %s', out_tensor.name)
        return False
    if self._is_user_excluded_op(out_tensor.op):
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_USER_EXCLUDED))
        if tensor_tracer_flags.TT_CHECK_FILTER.value:
            logging.info('USER_EXCLUDED tensor %s', out_tensor.name)
        return True
    if not out_tensor.get_shape().is_fully_defined():
        if self._parameters.trace_mode in (tensor_tracer_flags.TRACE_MODE_NAN_INF, tensor_tracer_flags.TRACE_MODE_NORM, tensor_tracer_flags.TRACE_MODE_HISTORY, tensor_tracer_flags.TRACE_MODE_MAX_ABS, tensor_tracer_flags.TRACE_MODE_SUMMARY):
            report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_TENSOR_GET_TRACED))
            return False
        else:
            report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_DYNAMIC_SHAPE))
            return True
    rank = len(out_tensor.shape)
    if rank < 1:
        if self._parameters.trace_scalar_ops:
            if TensorTracer.unsafe_scalar_trace(out_tensor.op):
                report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_UNSAFE_SCALAR))
                return True
            else:
                report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_SCALAR_GET_TRACED))
                return False
        else:
            report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_SKIP_SCALAR))
            return True
    else:
        report_handler.instrument_tensor(out_tensor, TensorTracer.reason(op_id, _REASON_TENSOR_GET_TRACED))
        return False

def __getitem__(self, idx: Union[int, slice]) -> AttrProxy:
    if isinstance(idx, slice):
        if isinstance(self, torch.nn.Sequential):
            res = torch.nn.Sequential(OrderedDict(list(self._modules.items())[idx]))
            return AttrProxy(res, f'{tracer.proxy_paths[self]}.{idx}')
        elif <MASK>:
            res = torch.nn.ModuleList(list(self._modules.values())[idx])
            return AttrProxy(res, f'{tracer.proxy_paths[self]}.{idx}')
    return super().__getitem__(idx)

def register_refinement_rule(call_target: Target) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:

    def register(fn: Callable[_P, _T]) -> Callable[_P, _T]:
        if <MASK>:
            raise RuntimeError(f'Refinement rule already registered for {call_target}!')
        _REFINEMENT_RULES[call_target] = fn
        return fn
    return register

def format(self, record):
    artifact_name = getattr(logging.getLogger(record.name), 'artifact_name', None)
    if artifact_name is not None:
        artifact_formatter = log_registry.artifact_log_formatters.get(artifact_name, None)
        if <MASK>:
            return artifact_formatter.format(record)
    record.message = record.getMessage()
    record.asctime = self.formatTime(record, '%m%d %H:%M:%S')
    s = record.message
    if record.exc_info:
        if not record.exc_text:
            record.exc_text = self.formatException(record.exc_info)
    if record.exc_text:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + record.exc_text
    if record.stack_info:
        if s[-1:] != '\n':
            s = s + '\n'
        s = s + self.formatStack(record.stack_info)
    record.rankprefix = ''
    if not self._is_trace and dist.is_available() and dist.is_initialized():
        record.rankprefix = f'[rank{dist.get_rank()}]:'
    record.traceid = ''
    if not self._is_trace and (trace_id := torch._guards.CompileContext.current_trace_id()) is not None:
        record.traceid = f' [{trace_id}]'
    glog_level_to_abbr = {'DEBUG': 'V', 'INFO': 'I', 'WARNING': 'W', 'ERROR': 'E', 'CRITICAL': 'C'}
    shortlevel = glog_level_to_abbr.get(record.levelname, record.levelname)
    record.artifactprefix = ''
    if artifact_name is not None:
        record.artifactprefix = f' [__{artifact_name}]'
    filepath = make_module_path_relative(record.pathname)
    if self._trace_id_filter and record.traceid.strip() not in self._trace_id_filter:
        return ''
    prefix = f'{record.rankprefix}{shortlevel}{record.asctime}.{int(record.msecs * 1000):06d} {record.process} {filepath}:{record.lineno}]{record.traceid}{record.artifactprefix}'
    if self._is_trace:
        assert s == ''
        try:
            r = f'{prefix} {json.dumps(record.metadata)}'
        except TypeError:
            log.warning('failing metadata: %r', record.metadata)
            raise
        if record.payload is not None:
            r += ''.join((f'\n\t{l}' for l in record.payload.split('\n')))
        return r
    else:
        lines = s.split('\n')
        return '\n'.join((f'{prefix} {l}' for l in lines))

def main(argv: list[str] | None=None) -> int:
    suspicious_funcs: tuple[str, ...] = ('PyList_GetItem', 'PyDict_GetItem', 'PyDict_GetItemWithError', 'PyDict_GetItemString', 'PyDict_SetDefault', 'PyDict_Next', 'PyWeakref_GetObject', 'PyWeakref_GET_OBJECT', 'PyList_GET_ITEM', '_PyDict_GetItemStringWithError', 'PySequence_Fast')
    func_rx = build_func_rx(suspicious_funcs)
    noqa_markers = ('noqa: borrowed-ref OK', 'noqa: borrowed-ref - manual fix needed')
    default_exts = {'.c', '.h', '.c.src', '.cpp'}
    default_excludes = {'pythoncapi-compat'}
    ap = argparse.ArgumentParser(description='Borrow-ref C API linter (Python).')
    ap.add_argument('--quiet', action='store_true', help='Suppress normal output; exit status alone indicates result (useful              for CI).')
    ap.add_argument('-j', '--jobs', type=int, default=0, help='Number of worker threads (0=auto, 1=sequential).')
    ap.add_argument('--root', default='numpy', type=str, help='Root directory to scan (default: numpy)')
    ap.add_argument('--ext', action='append', default=None, help=f'File extension(s) to include (repeatable). Defaults to {default_exts}')
    ap.add_argument('--exclude', action='append', default=None, help=f'Directory name(s) to exclude (repeatable). Default: {default_excludes}')
    args = ap.parse_args(argv)
    if args.ext:
        exts = {e if e.startswith('.') else f'.{e}' for e in args.ext}
    else:
        exts = set(default_exts)
    excludes = set(args.exclude) if args.exclude else set(default_excludes)
    root = Path(args.root)
    if not root.exists():
        print(f"error: root '{root}' does not exist", file=sys.stderr)
        return 2
    files = sorted(iter_source_files(root, exts, excludes), key=str)
    if args.jobs is None or args.jobs <= 0:
        max_workers = min(32, (os.cpu_count() or 1) * 5)
    else:
        max_workers = max(1, args.jobs)
    print(f'Scanning {len(files)} C/C++ source files...\n')
    tmpdir = Path('.tmp')
    tmpdir.mkdir(exist_ok=True)
    findings = 0
    all_hits: list[tuple[str, int, str, str]] = []
    if max_workers == 1:
        for p in files:
            all_hits.extend(scan_file(p, func_rx, noqa_markers))
    else:
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            fut_to_file = {ex.submit(scan_file, p, func_rx, noqa_markers): p for p in files}
            for fut in as_completed(fut_to_file):
                try:
                    all_hits.extend(fut.result())
                except Exception as e:
                    print(f'Failed to scan {fut_to_file[fut]}: {e}')
    all_hits.sort(key=lambda t: (t[2], t[1]))
    if <MASK>:
        if not args.quiet:
            print('All checks passed! C API borrow-ref linter found no issues.\n')
        return 0
    with tempfile.NamedTemporaryFile(prefix='c_api_usage_report.', suffix='.txt', dir=tmpdir, mode='w+', encoding='utf-8', delete=False) as out:
        report_path = Path(out.name)
        out.write('Running Suspicious C API usage report workflow...\n\n')
        for (func, lineo, pstr, raw) in all_hits:
            findings += 1
            out.write(f'Found suspicious call to {func} in file: {pstr}\n')
            out.write(f' -> {pstr}:{lineo}a:{raw}\n')
            out.write('Recommendation:\n')
            out.write("If this use is intentional and safe, add '// noqa: borrowed-ref OK' on the same line to silence this warning.\n")
            out.write('Otherwise, consider replacing the call with a thread-safe API function.\n\n')
        out.flush()
        if not args.quiet:
            out.seek(0)
            sys.stdout.write(out.read())
            print(f'Report written to: {report_path}\n\nC API borrow-ref linter FAILED.')
    return 1

def DUPLICATE_INPUT(self, guard: Guard, source_b: Source) -> None:
    if self.save_guards:
        if (name := get_local_source_name(source_b)):
            self.check_fn_manager.additional_used_local_vars.add(name)
        if (name := get_global_source_name(source_b)):
            self.check_fn_manager.additional_used_global_vars.add(name)
    ref_a = self.arg_ref(guard)
    ref_b = self.arg_ref(source_b.name())
    if is_from_optimizer_source(guard.originating_source) or is_from_optimizer_source(source_b):
        return
    key = (ref_a, ref_b)
    if key in self._cached_duplicate_input_guards:
        return
    self._cached_duplicate_input_guards.add((ref_a, ref_b))
    self._cached_duplicate_input_guards.add((ref_b, ref_a))
    code = [f'{ref_b} is {ref_a}']
    self._set_guard_export_info(guard, code)
    if <MASK>:
        code_part = code[0]
        verbose_code_part = get_verbose_code_parts(code_part, guard)[0]
        self.object_aliasing_guard_codes.append((code_part, verbose_code_part))
    else:
        install_object_aliasing_guard(self.get_guard_manager(guard), self.get_guard_manager_from_source(source_b), get_verbose_code_parts(code, guard))

def _get_enclosing_context(graph) -> Any:
    if graph is None:
        return None
    if graph._control_flow_context is not None:
        return graph._control_flow_context
    if <MASK>:
        return _get_enclosing_context(graph.outer_graph)

def __enter__(self) -> str:
    """Start the scope block.

    Returns:
      The scope name.
    """
    ctx = context.context()
    if ctx.executing_eagerly():
        old_name = ctx.scope_name
        name = self._name
        if not name:
            scope_name = ''
        elif <MASK>:
            scope_name = name
        elif old_name:
            scope_name = old_name + name + '/'
        else:
            scope_name = name + '/'
        ctx.scope_name = scope_name

        def _restore_name_scope(*_):
            ctx.scope_name = old_name
        self._exit_fns.append(_restore_name_scope)
    else:
        scope = get_default_graph().name_scope(self._name)
        scope_name = scope.__enter__()
        self._exit_fns.append(scope.__exit__)
    return scope_name

def _get_lines(self, rows: int | None=None) -> list[list[Scalar]]:
    lines = self.buf
    new_rows = None
    if rows is not None:
        if len(self.buf) >= rows:
            (new_rows, self.buf) = (self.buf[:rows], self.buf[rows:])
        else:
            rows -= len(self.buf)
    if new_rows is None:
        if isinstance(self.data, list):
            if self.pos > len(self.data):
                raise StopIteration
            if rows is None:
                new_rows = self.data[self.pos:]
                new_pos = len(self.data)
            else:
                new_rows = self.data[self.pos:self.pos + rows]
                new_pos = self.pos + rows
            new_rows = self._remove_skipped_rows(new_rows)
            lines.extend(new_rows)
            self.pos = new_pos
        else:
            new_rows = []
            try:
                if rows is not None:
                    row_index = 0
                    row_ct = 0
                    offset = self.pos if self.pos is not None else 0
                    while row_ct < rows:
                        new_row = next(self.data)
                        if not self.skipfunc(offset + row_index):
                            row_ct += 1
                        row_index += 1
                        new_rows.append(new_row)
                    len_new_rows = len(new_rows)
                    new_rows = self._remove_skipped_rows(new_rows)
                    lines.extend(new_rows)
                else:
                    rows = 0
                    while True:
                        next_row = self._next_iter_line(row_num=self.pos + rows + 1)
                        rows += 1
                        if next_row is not None:
                            new_rows.append(next_row)
                    len_new_rows = len(new_rows)
            except StopIteration:
                len_new_rows = len(new_rows)
                new_rows = self._remove_skipped_rows(new_rows)
                lines.extend(new_rows)
                if len(lines) == 0:
                    raise
            self.pos += len_new_rows
        self.buf = []
    else:
        lines = new_rows
    if self.skipfooter:
        lines = lines[:-self.skipfooter]
    lines = self._check_comments(lines)
    if <MASK>:
        lines = self._remove_empty_lines(lines)
    lines = self._check_thousands(lines)
    return self._check_decimal(lines)

def _get_node_target_type(node: Node, gm: GraphModule) -> Optional[NSNodeTargetType]:
    if <MASK>:
        return node.target
    elif node.op == 'call_module':
        if not isinstance(node.target, str):
            raise AssertionError(f'Expected str, got {type(node.target)}')
        mod = getattr_from_fqn(gm, node.target)
        return type(mod)
    return None

def create_zeros_slot(primary, name, dtype=None, colocate_with_primary=True, *, copy_xla_sharding=False):
    """Create a slot initialized to 0 with same shape as the primary object.

  Args:
    primary: The primary `Variable` or `Tensor`.
    name: Name to use for the slot variable.
    dtype: Type of the slot variable.  Defaults to the type of `primary`.
    colocate_with_primary: Boolean.  If True the slot is located
      on the same device as `primary`.
    copy_xla_sharding: Boolean. If True also copies XLA sharding
      from primary.

  Returns:
    A `Variable` object.
  """
    if dtype is None:
        dtype = primary.dtype
    slot_shape = primary.get_shape()
    if <MASK>:
        initializer = init_ops.zeros_initializer()
        return create_slot_with_initializer(primary, initializer, slot_shape, dtype, name, colocate_with_primary=colocate_with_primary, copy_xla_sharding=copy_xla_sharding)
    else:
        if isinstance(primary, variables.Variable):
            slot_shape = array_ops.shape(cond.cond(variable_v1.is_variable_initialized(primary), primary.read_value, lambda : primary.initial_value))
        else:
            slot_shape = array_ops.shape(primary)
        val = array_ops.zeros(slot_shape, dtype=dtype)
        return create_slot(primary, val, name, colocate_with_primary=colocate_with_primary, copy_xla_sharding=copy_xla_sharding)

def get_view_on_site_url(self, obj=None):
    if <MASK>:
        return None
    if callable(self.view_on_site):
        return self.view_on_site(obj)
    elif hasattr(obj, 'get_absolute_url'):
