def _from_numpy_array(array: np.ndarray) -> torch.Tensor:
    """Convert a NumPy array to a PyTorch tensor."""
    import ml_dtypes
    import numpy as np
    if array.dtype == ml_dtypes.bfloat16:
        return torch.from_numpy(array.view(np.uint16)).view(torch.bfloat16)
    if array.dtype == ml_dtypes.float8_e4m3fn:
        return torch.from_numpy(array.view(np.uint8)).view(torch.float8_e4m3fn)
    if array.dtype == ml_dtypes.float8_e4m3fnuz:
        return torch.from_numpy(array.view(np.uint8)).view(torch.float8_e4m3fnuz)
    if array.dtype == ml_dtypes.float8_e5m2:
        return torch.from_numpy(array.view(np.uint8)).view(torch.float8_e5m2)
    if <MASK>:
        return torch.from_numpy(array.view(np.uint8)).view(torch.float8_e5m2fnuz)
    return torch.from_numpy(array)

@parameterized.parameters(True, False)
def testSummaryControlFlowIfWithAutoOutsideCompilation(self, take_true_branch):
    strategy = get_tpu_strategy()

    @def_function.function
    def step():

        def computation(x):
            x = x + 1.0
            if <MASK>:
                scalar_summary_v2.scalar('x', x, step=0)
                x = x * 2.0
            return x + 1.0
        if take_true_branch:
            return strategy.run(computation, args=(2.0,))
        else:
            return strategy.run(computation, args=(10.0,))
    logdir = tempfile.mkdtemp()
    summary_writer = summary.create_file_writer(logdir, flush_millis=10000)
    output_value = 12.0
    if take_true_branch:
        output_value = 7.0
    with summary_writer.as_default(), summary.always_record_summaries():
        self.assertAllEqual(strategy.experimental_local_results(step()), constant_op.constant(output_value, shape=strategy.num_replicas_in_sync))
    if take_true_branch:
        events = _events_from_logdir(self, logdir)
        self.assertLen(events, 2)
        self.assertEqual(events[1].summary.value[0].tag, 'cond/x')

def format(number, decimal_sep, decimal_pos=None, grouping=0, thousand_sep='', force_grouping=False, use_l10n=None):
    """
    Get a number (as a number or string), and return it as a string,
    using formats defined as arguments:

    * decimal_sep: Decimal separator symbol (for example ".")
    * decimal_pos: Number of decimal positions
    * grouping: Number of digits in every group limited by thousand separator.
        For non-uniform digit grouping, it can be a sequence with the number
        of digit group sizes following the format used by the Python locale
        module in locale.localeconv() LC_NUMERIC grouping (e.g. (3, 2, 0)).
    * thousand_sep: Thousand separator symbol (for example ",")
    """
    if number is None or number == '':
        return mark_safe(number)
    if use_l10n is None:
        use_l10n = True
    use_grouping = use_l10n and settings.USE_THOUSAND_SEPARATOR
    use_grouping = use_grouping or force_grouping
    use_grouping = use_grouping and grouping != 0
    if isinstance(number, int) and (not use_grouping) and (not decimal_pos):
        return mark_safe(number)
    sign = ''
    if isinstance(number, float) and 'e' in str(number).lower():
        number = Decimal(str(number))
    if isinstance(number, Decimal):
        if decimal_pos is not None:
            cutoff = Decimal('0.' + '1'.rjust(decimal_pos, '0'))
            if abs(number) < cutoff:
                number = Decimal('0')
        (_, digits, exponent) = number.as_tuple()
        if abs(exponent) + len(digits) > 200:
            number = '{:e}'.format(number)
            (coefficient, exponent) = number.split('e')
            coefficient = format(coefficient, decimal_sep, decimal_pos, grouping, thousand_sep, force_grouping, use_l10n)
            return '{}e{}'.format(coefficient, exponent)
        else:
            str_number = '{:f}'.format(number)
    else:
        str_number = str(number)
    if str_number[0] == '-':
        sign = '-'
        str_number = str_number[1:]
    if '.' in str_number:
        (int_part, dec_part) = str_number.split('.')
        if decimal_pos is not None:
            dec_part = dec_part[:decimal_pos]
    else:
        (int_part, dec_part) = (str_number, '')
    if decimal_pos is not None:
        dec_part += '0' * (decimal_pos - len(dec_part))
    dec_part = dec_part and decimal_sep + dec_part
    if <MASK>:
        try:
            intervals = list(grouping)
        except TypeError:
            intervals = [grouping, 0]
        active_interval = intervals.pop(0)
        int_part_gd = ''
        cnt = 0
        for digit in int_part[::-1]:
            if cnt and cnt == active_interval:
                if intervals:
                    active_interval = intervals.pop(0) or active_interval
                int_part_gd += thousand_sep[::-1]
                cnt = 0
            int_part_gd += digit
            cnt += 1
        int_part = int_part_gd[::-1]
    return sign + int_part + dec_part

def collect_function_arg_names(function_names, return_all_args_function_names, function_renames):
    """Determines argument names for reordered function signatures.

  Args:
    function_names: Functions to collect arguments for.
    return_all_args_function_names: Functions to collect all argument names for.
    function_renames: Function renames between v1 and v2.

  Returns:
    Dictionary mapping function names to a list of argument names. Each argument
    name list can have leading `None` elements to indicate that some of the
    function arguments did not change between v1 and v2.
  """
    function_name_v1_to_attr = {}
    function_name_v2_to_attr = {}

    def visit(unused_path, unused_parent, children):
        """Visitor that collects arguments for reordered functions."""
        for child in children:
            (_, attr) = tf_decorator.unwrap(child[1])
            api_names_v1 = ['tf.' + name for name in tf_export.get_v1_names(attr)]
            if any((name in function_names for name in api_names_v1)):
                for name in api_names_v1:
                    function_name_v1_to_attr[name] = attr
            api_names_v2 = ['tf.' + name for name in tf_export.get_v2_names(attr)]
            for name in api_names_v2:
                function_name_v2_to_attr[name] = attr
    visitor = public_api.PublicAPIVisitor(visit)
    visitor.do_not_descend_map['tf'].append('contrib')
    visitor.private_map['tf.compat'] = ['v1', 'v2']
    traverse.traverse(tf.compat.v1, visitor)
    traverse.traverse(tf.compat.v2, visitor)

    def get_arguments_list(attr):
        if tf_inspect.isclass(attr):
            arg_list = tf_inspect.getargspec(getattr(attr, '__init__'))[0]
            return arg_list[1:]
        else:
            return tf_inspect.getargspec(attr)[0]
    function_to_args = {}
    if any((name not in function_name_v1_to_attr for name in function_names)):
        raise ValueError(f"Symbols not found in `tf.compat.v1`: `{'`, `'.join(function_names - function_name_v1_to_attr.keys())}`")
    for (name_v1, attr_v1) in function_name_v1_to_attr.items():
        args_v1 = get_arguments_list(attr_v1)
        if name_v1 in return_all_args_function_names:
            function_to_args[name_v1] = args_v1
            continue
        name_v2 = name_v1
        if name_v1 in function_renames:
            name_v2 = function_renames[name_v1]
            if name_v2.startswith('tf.compat.v1.'):
                raise ValueError(f'Symbol `{name_v1}` is renamed to `{name_v2}`, no need to add keyword argument names, remove from `reordered_function_names`')
        if <MASK>:
            raise ValueError(f'Symbol `{name_v2}` not found in `tf.compat.v2`')
        args_v2 = get_arguments_list(function_name_v2_to_attr[name_v2])
        if args_v1 == args_v2:
            raise ValueError(f'Symbol `{name_v1}` has no changes in arguments, no need to add keyword argument names, remove from `reordered_function_names`')
        needed_arg_names = []
        same_so_far = True
        for (index, arg) in enumerate(args_v1):
            if same_so_far and index < len(args_v2) and (arg == args_v2[index]):
                needed_arg_names.append(None)
            else:
                same_so_far = False
                needed_arg_names.append(arg)
        function_to_args[name_v1] = needed_arg_names
    return function_to_args

def promote2(self, other):
    if method not in ['add', 'sub', 'mul', 'mod', 'float_pow', 'float_truediv', 'int_floordiv', 'sym_min', 'sym_max', 'eq', 'ne', 'gt', 'lt', 'le', 'ge']:
        return (self, other)
    f_self = isinstance(self, (float, torch.SymFloat))
    f_other = isinstance(other, (float, torch.SymFloat))
    if f_self or f_other:
        if <MASK>:
            self = torch.sym_float(self)
        if not f_other:
            other = torch.sym_float(other)
    return (self, other)

def get_json_type(obj):
    """Serializes any object to a JSON-serializable structure.

  Args:
      obj: the object to serialize

  Returns:
      JSON-serializable structure representing `obj`.

  Raises:
      TypeError: if `obj` cannot be serialized.
  """
    if hasattr(obj, 'get_config'):
        return {'class_name': obj.__class__.__name__, 'config': obj.get_config()}
    if type(obj).__module__ == np.__name__:
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        else:
            return obj.item()
    if callable(obj):
        return obj.__name__
    if type(obj).__name__ == type.__name__:
        return obj.__name__
    if isinstance(obj, tensor_shape.Dimension):
        return obj.value
    if <MASK>:
        return obj.as_list()
    if isinstance(obj, dtypes.DType):
        return obj.name
    if isinstance(obj, collections_abc.Mapping):
        return dict(obj)
    if obj is Ellipsis:
        return {'class_name': '__ellipsis__'}
    if isinstance(obj, wrapt.ObjectProxy):
        return obj.__wrapped__
    raise TypeError(f'Object {obj} is not JSON-serializable. You may implement a `get_config()` method on the class (returning a JSON-serializable dictionary) to make it serializable.')

def group_overloads(overloads: Sequence[PythonSignatureNativeFunctionPair], *, symint: bool=True) -> Sequence[PythonSignatureGroup]:
    bases: dict[str, PythonSignatureNativeFunctionPair] = {}
    outplaces: dict[str, PythonSignatureNativeFunctionPair] = {}
    for overload in overloads:
        sig = overload.signature.signature_str(skip_outputs=True, symint=symint)
        if overload.function.func.is_out_fn():
            if <MASK>:
                raise RuntimeError(f'Found duplicated function definition:\n- {overload.function.func}.\nExisting definition:\n- {outplaces[sig].function.func}.')
            outplaces[sig] = overload
        else:
            if sig in bases:
                raise RuntimeError(f'Found duplicated function definition:\n- {overload.function.func}.\nExisting definition:\n- {bases[sig].function.func}.')
            bases[sig] = overload
    for (sig, out) in outplaces.items():
        if sig not in bases:
            candidates: list[str] = []
            for overload in overloads:
                if str(overload.function.func.name.name) == str(out.function.func.name.name) and (not overload.function.func.is_out_fn()) and (not overload.signature.deprecated):
                    candidates.append(overload.signature.signature_str(skip_outputs=True, symint=symint))
            out_sig = out.signature.signature_str(symint=symint)
            raise RuntimeError(f'While identifying overloads, we found an out schema {out_sig} without a corresponding non-out variant. We expected the non-out variant to have schema: \n- {sig}\nPlease check that you spelled the schema correctly in native_functions.yaml. We discovered the following candidate(s): \n' + '\n'.join((f'- {candidate}' for candidate in candidates)))
    grouped = [PythonSignatureGroup.from_pairs(functional=base, out=outplaces.get(sig)) for (sig, base) in bases.items()]
    return sort_overloads(grouped, symint=symint)

def _einsum_v1(equation, *inputs, **kwargs):
    """Legacy implementation of einsum without using EinsumOp."""
    name = kwargs.pop('name', None)
    if kwargs:
        raise TypeError(f"Invalid keyword arguments for this function: {', '.join([format(key) for key in sorted(list(kwargs.keys()))])}. Expected: name.")
    with ops.name_scope(name, 'einsum', [equation, inputs]) as name:
        inputs = list(inputs)
        input_shapes = [x.shape for x in inputs]
        (input_axis_labels, output_axis_labels) = _einsum_v1_parse_and_resolve_equation(equation, input_shapes)
        axis_labels = set(''.join(input_axis_labels) + output_axis_labels)
        for a in axis_labels:
            for input_labels in input_axis_labels:
                if len(input_axis_labels) == 1 and input_labels.count(a) == 2 and (input_labels == input_labels[::-1]) and ('->' not in equation):
                    return math_ops.trace(inputs[0])
                if input_labels.count(a) > 1:
                    raise ValueError(f'Subscript not supported: the axis {a} appears more than once in {input_labels}.')
        for a in axis_labels:
            input_count = sum((1 for s in input_axis_labels if a in s))
            if input_count > 2 and a not in output_axis_labels:
                logging.warn(f'Falling back to exponential-space implementation of einsum() because index {a} is summed over more than two inputs.')
                return _exponential_space_einsum_v1(equation, *inputs)
        if <MASK>:
            return gen_xla_ops.xla_einsum(inputs[0], inputs[1], input_axis_labels[0] + ',' + input_axis_labels[1] + '->' + output_axis_labels)
        temp = inputs[0]
        temp_axis_labels = input_axis_labels[0]
        for i in range(len(inputs) - 1):
            axes_to_sum = set(temp_axis_labels) & set(input_axis_labels[i + 1]) - set(output_axis_labels)
            (temp, temp_axis_labels) = _einsum_v1_reduction(temp, temp_axis_labels, inputs[i + 1], input_axis_labels[i + 1], axes_to_sum)
        missing_indices = set(temp_axis_labels) - set(output_axis_labels)
        if missing_indices:
            axis = [i for (i, a) in enumerate(temp_axis_labels) if a not in output_axis_labels]
            temp = math_ops.reduce_sum(temp, axis=axis)
            temp_axis_labels = ''.join((a for a in temp_axis_labels if a in output_axis_labels))
        if sorted(temp_axis_labels) != sorted(output_axis_labels):
            raise ValueError(f'Invalid equation: {equation}. The computed and specified output labels do not match: {temp_axis_labels} vs {output_axis_labels}.')
        perm = [temp_axis_labels.index(a) for a in output_axis_labels]
        return _transpose_if_necessary(temp, perm)

def load_middleware(self, is_async=False):
    """
        Populate middleware lists from settings.MIDDLEWARE.

        Must be called after the environment is fixed (see __call__ in
        subclasses).
        """
    self._view_middleware = []
    self._template_response_middleware = []
    self._exception_middleware = []
    get_response = self._get_response_async if is_async else self._get_response
    handler = convert_exception_to_response(get_response)
    handler_is_async = is_async
    for middleware_path in reversed(settings.MIDDLEWARE):
        middleware = import_string(middleware_path)
        middleware_can_sync = getattr(middleware, 'sync_capable', True)
        middleware_can_async = getattr(middleware, 'async_capable', False)
        if not middleware_can_sync and (not middleware_can_async):
            raise RuntimeError('Middleware %s must have at least one of sync_capable/async_capable set to True.' % middleware_path)
        elif not handler_is_async and middleware_can_sync:
            middleware_is_async = False
        else:
            middleware_is_async = middleware_can_async
        try:
            adapted_handler = self.adapt_method_mode(middleware_is_async, handler, handler_is_async, debug=settings.DEBUG, name='middleware %s' % middleware_path)
            mw_instance = middleware(adapted_handler)
        except MiddlewareNotUsed as exc:
            if settings.DEBUG:
                if <MASK>:
                    logger.debug('MiddlewareNotUsed(%r): %s', middleware_path, exc)
                else:
                    logger.debug('MiddlewareNotUsed: %r', middleware_path)
            continue
        else:
            handler = adapted_handler
        if mw_instance is None:
            raise ImproperlyConfigured('Middleware factory %s returned None.' % middleware_path)
        if hasattr(mw_instance, 'process_view'):
            self._view_middleware.insert(0, self.adapt_method_mode(is_async, mw_instance.process_view))
        if hasattr(mw_instance, 'process_template_response'):
            self._template_response_middleware.append(self.adapt_method_mode(is_async, mw_instance.process_template_response))
        if hasattr(mw_instance, 'process_exception'):
            self._exception_middleware.append(self.adapt_method_mode(False, mw_instance.process_exception))
        handler = convert_exception_to_response(mw_instance)
        handler_is_async = middleware_is_async
    handler = self.adapt_method_mode(is_async, handler, handler_is_async)
    self._middleware_chain = handler

def _get_next_or_previous_in_order(self, is_next):
    cachename = '__%s_order_cache' % is_next
    if <MASK>:
        op = 'gt' if is_next else 'lt'
        order = '_order' if is_next else '-_order'
        order_field = self._meta.order_with_respect_to
        filter_args = order_field.get_filter_kwargs_for_object(self)
        obj = self.__class__._default_manager.filter(**filter_args).filter(**{'_order__%s' % op: self.__class__._default_manager.values('_order').filter(**{self._meta.pk.name: self.pk})}).order_by(order)[:1].get()
        setattr(self, cachename, obj)
    return getattr(self, cachename)

@timed('Installing packages')
def pip_install(self, *packages: str, prerelease: bool=False, upgrade: bool=False, no_deps: bool=False, **popen_kwargs: Any) -> subprocess.CompletedProcess[str]:
    """Run a pip install command in the virtual environment."""
    pip_args = []
    if VERBOSE:
        pip_args.append('-v')
    if prerelease:
        pip_args.append('--pre')
    if <MASK>:
        pip_args.append('--upgrade')
        verb = 'Upgrading'
    else:
        verb = 'Installing'
    if no_deps:
        pip_args.append('--no-deps')
    print(f'{verb} package(s) ({self.pip_source.index_url}):')
    for package in packages:
        print(f'  - {os.path.basename(package)}')
    return self.pip('install', *pip_args, *packages, **popen_kwargs)

def inner_fn(index):
    assert len(index) == len(repeats)
    index = list(index)
    for i in range(len(repeats)):
        if repeats[i] != 1:
            if <MASK>:
                index[i] = sympy.S.Zero
            else:
                index[i] = ModularIndexing(index[i], 1, old_size[i])
    return x_loader(index)

def _delete_proxy_attr(obj: Module, target: str) -> bool:
    atoms = target.split('.')
    (path, target_submod) = (atoms[:-1], atoms[-1])
    assert isinstance(obj, Module)
    mod = obj
    for item in path:
        if not hasattr(mod, item):
            return False
        mod = getattr(mod, item)
        if <MASK>:
            return False
    if not hasattr(mod, target_submod):
        return False
    if not isinstance(getattr(mod, target_submod), _AttrProxy):
        return False
    delattr(mod, target_submod)
    return True

def _validate_transformers(self):
    (names, transformers) = zip(*self.transformer_list)
    self._validate_names(names)
    for t in transformers:
        if <MASK>:
            continue
        if not (hasattr(t, 'fit') or hasattr(t, 'fit_transform')) or not hasattr(t, 'transform'):
            raise TypeError("All estimators should implement fit and transform. '%s' (type %s) doesn't" % (t, type(t)))

def prefetch_related_objects(model_instances, *related_lookups):
    """
    Populate prefetched object caches for an iterable of model instances based
    on the lookups/Prefetch instances given.
    """
    if not model_instances:
        return
    done_queries = {}
    auto_lookups = set()
    followed_descriptors = set()
    all_lookups = normalize_prefetch_lookups(reversed(related_lookups))
    while all_lookups:
        lookup = all_lookups.pop()
        if lookup.prefetch_to in done_queries:
            if lookup.queryset is not None:
                raise ValueError("'%s' lookup was already seen with a different queryset. You may need to adjust the ordering of your lookups." % lookup.prefetch_to)
            continue
        obj_list = model_instances
        through_attrs = lookup.prefetch_through.split(LOOKUP_SEP)
        for (level, through_attr) in enumerate(through_attrs):
            if not obj_list:
                break
            prefetch_to = lookup.get_current_prefetch_to(level)
            if prefetch_to in done_queries:
                obj_list = done_queries[prefetch_to]
                continue
            good_objects = True
            for obj in obj_list:
                if not hasattr(obj, '_prefetched_objects_cache'):
                    try:
                        obj._prefetched_objects_cache = {}
                    except (AttributeError, TypeError):
                        good_objects = False
                        break
            if not good_objects:
                break
            first_obj = next(iter(obj_list))
            to_attr = lookup.get_current_to_attr(level)[0]
            (prefetcher, descriptor, attr_found, is_fetched) = get_prefetcher(first_obj, through_attr, to_attr)
            if not attr_found:
                raise AttributeError("Cannot find '%s' on %s object, '%s' is an invalid parameter to prefetch_related()" % (through_attr, first_obj.__class__.__name__, lookup.prefetch_through))
            if level == len(through_attrs) - 1 and prefetcher is None:
                raise ValueError("'%s' does not resolve to an item that supports prefetching - this is an invalid parameter to prefetch_related()." % lookup.prefetch_through)
            obj_to_fetch = None
            if prefetcher is not None:
                obj_to_fetch = [obj for obj in obj_list if not is_fetched(obj)]
            if obj_to_fetch:
                (obj_list, additional_lookups) = prefetch_one_level(obj_to_fetch, prefetcher, lookup, level)
                if not (prefetch_to in done_queries and lookup in auto_lookups and (descriptor in followed_descriptors)):
                    done_queries[prefetch_to] = obj_list
                    new_lookups = normalize_prefetch_lookups(reversed(additional_lookups), prefetch_to)
                    auto_lookups.update(new_lookups)
                    all_lookups.extend(new_lookups)
                followed_descriptors.add(descriptor)
            else:
                new_obj_list = []
                for obj in obj_list:
                    if through_attr in getattr(obj, '_prefetched_objects_cache', ()):
                        new_obj = list(obj._prefetched_objects_cache.get(through_attr))
                    else:
                        try:
                            new_obj = getattr(obj, through_attr)
                        except exceptions.ObjectDoesNotExist:
                            continue
                    if <MASK>:
                        continue
                    if isinstance(new_obj, list):
                        new_obj_list.extend(new_obj)
                    else:
                        new_obj_list.append(new_obj)
                obj_list = new_obj_list

def codegen_input_symbol_assignment(self, name: str, value: ir.TensorBox, bound_vars: OrderedSet[sympy.Symbol]):
    code = self.prefix

    @functools.cache
    def sizeof(name):
        self.codegen_input_size_var_decl(code, name)
        return f'{name}_size'

    @functools.cache
    def strideof(name):
        self.codegen_input_stride_var_decl(code, name)
        return f'{name}_stride'

    def codegen_symbol(sym_or_exp: Union[sympy.Symbol, sympy.Expr], base_name: str, name_fn: Callable[[str], str], dim: int):
        if isinstance(sym_or_exp, sympy.Symbol):
            if <MASK>:
                return
            code.writeline(f'int64_t {sym_or_exp} = {name_fn(base_name)}[{dim}];')
            bound_vars.add(sym_or_exp)
        elif isinstance(sym_or_exp, sympy.Expr):
            undefined_symbols = [sym for sym in sym_or_exp.free_symbols if sym not in bound_vars]
            if len(undefined_symbols) != 1:
                return
            from torch.utils._sympy.solve import try_solve
            free_symbol = undefined_symbols.pop()
            base_name = name_fn(base_name)
            size_symbol = sympy.Symbol(f'{base_name}_{dim}', integer=True)
            code.writeline(f'int64_t {size_symbol} = {base_name}[{dim}];')
            solution = try_solve(sympy.Eq(sym_or_exp, size_symbol), free_symbol)
            if solution is not None:
                code.writeline(f'int64_t {free_symbol} = {cexpr(solution[1])};')
                bound_vars.add(free_symbol)
            else:
                raise AssertionError(str(sympy.Eq(sym_or_exp, size_symbol)) + ' is not solvable')
    if isinstance(value, sympy.Expr):
        if not isinstance(value, sympy.Symbol) or value in bound_vars:
            return
        if value.is_integer:
            decl = 'int64_t'
        elif value.is_float:
            decl = 'double'
        else:
            raise AssertionError('Unexpected symbol type')
        code.writeline(f'{decl} {value} = {name};')
        bound_vars.add(value)
    elif isinstance(value, ir.TensorBox):
        for (dim, size) in enumerate(value.get_size()):
            codegen_symbol(size, name, sizeof, dim)
        for (dim, stride) in enumerate(value.get_stride()):
            codegen_symbol(stride, name, strideof, dim)
    elif isinstance(value, ir.TorchBindObject):
        pass
    else:
        raise AssertionError(f'Unknown value type: {type(value)}')

@classmethod
def eval(cls, number):
    if number in (sympy.oo, int_oo):
        return int_oo
    if number in (-sympy.oo, -int_oo):
        return -int_oo
    if <MASK>:
        return sympy.Integer(math.ceil(float(number)))

def _parse_config_to_function(config, custom_objects, func_attr_name, func_type_attr_name, module_attr_name):
    """Reconstruct the function from the config."""
    globs = globals()
    module = config.pop(module_attr_name, None)
    if module in sys.modules:
        globs.update(sys.modules[module].__dict__)
    elif module is not None:
        warnings.warn('{} is not loaded, but a layer uses it. It may cause errors.'.format(module), UserWarning)
    if custom_objects:
        globs.update(custom_objects)
    function_type = config.pop(func_type_attr_name)
    if function_type == 'function':
        function = generic_utils.deserialize_keras_object(config[func_attr_name], custom_objects=custom_objects, printable_module_name='function in wrapper')
    elif <MASK>:
        function = generic_utils.func_load(config[func_attr_name], globs=globs)
    else:
        raise TypeError('Unknown function type:', function_type)
    return function

def get_mm_tensors(m: int, k: int, n: int, transpose_left: bool, transpose_right: bool, dtype_left: Any, dtype_right: Any) -> tuple[Any, Any]:
    if <MASK>:
        a = torch.randn(k, m, dtype=dtype_left).t()
    else:
        a = torch.randn(m, k, dtype=dtype_left)
    if transpose_right:
        b = torch.randn(n, k, dtype=dtype_right).t()
    else:
        b = torch.randn(k, n, dtype=dtype_right)
    return (a, b)

def my_map(x):
    if x == 0:
        return dataset_ops.Dataset.from_tensor_slices([0, 1, 2, 3])
    elif <MASK>:
        return dataset_ops.Dataset.from_tensor_slices([4, 5, 6, 7])
    else:
        return dataset_ops.Dataset.from_tensor_slices([8, 9, 10, 11])

def _get_template_configs_impl(self, kernel_inputs: KernelInputs, op_name: str) -> Generator[dict[str, Any], None, None]:
    """
        Generate scaled MM template configs with scaled MM-specific options.
        Handles the remaining logic from mm_common, including assertions.
        """
    kernel_inputs = self.adjust_kernel_inputs(kernel_inputs, op_name)
    input_nodes = kernel_inputs.nodes()
    assert len(input_nodes) >= 4, f'scaled_mm requires at least 4 inputs, got {len(input_nodes)}'
    scale_a = input_nodes[2]
    scale_b = input_nodes[3]

    def are_compatible_scales(size_a: Any, size_b: Any) -> bool:
        if <MASK>:
            return True
        if len(size_a) <= 1 and len(size_b) <= 1:
            return True
        return False

    def is_scalar_like(sz: Any) -> bool:
        return len(sz) == 0 or all((V.graph.sizevars.statically_known_equals(d, 1) for d in sz))
    (size_a, size_b) = (scale_a.get_size(), scale_b.get_size())
    assert are_compatible_scales(size_a, size_b), f'Expect scale_a and scale_b to be either both scalars (including single-element tensors) or 1-dimensional tensors with the same size. Got scale_a: {len(size_a)} and scale_b: {len(size_b)}.'
    assert isinstance(kernel_inputs, MMKernelInputs), f'{self.__class__.__name__} requires MMKernelInputs'
    if not self._valid(kernel_inputs):
        return
    for template_kwargs in super()._get_template_configs_impl(kernel_inputs, op_name):
        template_kwargs['ACC_TYPE'] = 'tl.float32'
        yield template_kwargs

def _get_svn_revision(self, path):
    """Return path's SVN revision number.
        """
    try:
        output = subprocess.check_output(['svnversion'], cwd=path)
    except (subprocess.CalledProcessError, OSError):
        pass
    else:
        m = re.match(b'(?P<revision>\\d+)', output)
        if m:
            return int(m.group('revision'))
    if <MASK>:
        entries = njoin(path, '_svn', 'entries')
    else:
        entries = njoin(path, '.svn', 'entries')
    if os.path.isfile(entries):
        with open(entries) as f:
            fstr = f.read()
        if fstr[:5] == '<?xml':
            m = re.search('revision="(?P<revision>\\d+)"', fstr)
            if m:
                return int(m.group('revision'))
        else:
            m = re.search('dir[\\n\\r]+(?P<revision>\\d+)', fstr)
            if m:
                return int(m.group('revision'))
    return None

def __init__(self, data, sparse_index=None, fill_value=None, kind: SparseIndexKind='integer', dtype: Dtype | None=None, copy: bool=False) -> None:
    if fill_value is None and isinstance(dtype, SparseDtype):
        fill_value = dtype.fill_value
    if isinstance(data, type(self)):
        if sparse_index is None:
            sparse_index = data.sp_index
        if <MASK>:
            fill_value = data.fill_value
        if dtype is None:
            dtype = data.dtype
        data = data.sp_values
    if isinstance(dtype, str):
        try:
            dtype = SparseDtype.construct_from_string(dtype)
        except TypeError:
            dtype = pandas_dtype(dtype)
    if isinstance(dtype, SparseDtype):
        if fill_value is None:
            fill_value = dtype.fill_value
        dtype = dtype.subtype
    if is_scalar(data):
        raise TypeError(f'Cannot construct {type(self).__name__} from scalar data. Pass a sequence instead.')
    if dtype is not None:
        dtype = pandas_dtype(dtype)
    if data is None:
        data = np.array([], dtype=dtype)
    try:
        data = sanitize_array(data, index=None)
    except ValueError:
        if dtype is None:
            dtype = np.dtype(object)
            data = np.atleast_1d(np.asarray(data, dtype=dtype))
        else:
            raise
    if copy:
        data = data.copy()
    if fill_value is None:
        fill_value_dtype = data.dtype if dtype is None else dtype
        if fill_value_dtype is None:
            fill_value = np.nan
        else:
            fill_value = na_value_for_dtype(fill_value_dtype)
    if isinstance(data, type(self)) and sparse_index is None:
        sparse_index = data._sparse_index
        sparse_values = np.asarray(data.sp_values, dtype=dtype)
    elif sparse_index is None:
        data = extract_array(data, extract_numpy=True)
        if not isinstance(data, np.ndarray):
            if isinstance(data.dtype, DatetimeTZDtype):
                warnings.warn(f'Creating SparseArray from {data.dtype} data loses timezone information. Cast to object before sparse to retain timezone information.', UserWarning, stacklevel=find_stack_level())
                data = np.asarray(data, dtype='datetime64[ns]')
                if fill_value is NaT:
                    fill_value = np.datetime64('NaT', 'ns')
            data = np.asarray(data)
        (sparse_values, sparse_index, fill_value) = _make_sparse(data, kind=kind, fill_value=fill_value, dtype=dtype)
    else:
        sparse_values = np.asarray(data, dtype=dtype)
        if len(sparse_values) != sparse_index.npoints:
            raise AssertionError(f'Non array-like type {type(sparse_values)} must have the same length as the index')
    self._sparse_index = sparse_index
    self._sparse_values = sparse_values
    self._dtype = SparseDtype(sparse_values.dtype, fill_value)

def from_current_timezone(value):
    """
    When time zone support is enabled, convert naive datetimes
    entered in the current time zone to aware datetimes.
    """
    if settings.USE_TZ and value is not None and timezone.is_naive(value):
        current_timezone = timezone.get_current_timezone()
        try:
            if <MASK>:
                raise ValueError('Ambiguous or non-existent time.')
            return timezone.make_aware(value, current_timezone)
        except Exception as exc:
            raise ValidationError(_('%(datetime)s couldn’t be interpreted in time zone %(current_timezone)s; it may be ambiguous or it may not exist.'), code='ambiguous_timezone', params={'datetime': value, 'current_timezone': current_timezone}) from exc
    return value

def _init() -> bool:
    global __cusparselt_version
    global __MAX_ALG_ID
    if __cusparselt_version is None:
        __cusparselt_version = _cusparselt.getVersionInt()
        if __cusparselt_version == 400:
            __MAX_ALG_ID = 4
        elif <MASK>:
            __MAX_ALG_ID = 5
        elif __cusparselt_version == 602:
            __MAX_ALG_ID = 37
    return True

def _var_key(var):
    """Returns slot key for `var`."""
    var = distribute_utils.value_container(var)
