def should_lower_cat_input(x) -> bool:
    if ir.is_storage_and_layout(x):
        (storage, _) = ir.as_storage_and_layout(x, freeze=False)
        return not ir.ConcatKernel.can_realize_into_without_copy(storage)
    if <MASK>:
        return should_lower_cat_input(unwrap_tensor(x))
    if isinstance(x, ir.Pointwise):
        return True
    return False

def _padded_impl(a, b):
    if <MASK>:
        nt = a
    else:
        nt = b
    from .nested_tensor import nested_from_padded
    min_seqlen = nt._maybe_min_seqlen
    max_seqlen = nt._maybe_max_seqlen
    padded_max_S = max_seqlen
    total_L = nt._values.shape[nt._ragged_idx - 1]
    if padded_max_S is None:
        padded_max_S = total_L
    padded_shape = (*nt.shape[:nt._ragged_idx], padded_max_S, *nt.shape[nt._ragged_idx + 1:])
    padded_nt = nt.to_padded_tensor(0.0, output_size=padded_shape)
    if a.is_nested:
        padded_t = func(padded_nt, b)
    else:
        padded_t = func(a, padded_nt)
    return nested_from_padded(padded_t, offsets=nt._offsets, ragged_idx=nt._ragged_idx, sum_S=total_L, min_seqlen=min_seqlen, max_seqlen=max_seqlen)

def _recursive_copy_to_device(value: Any, non_blocking: bool, device: torch.device) -> Any:
    """
    Recursively searches lists, tuples, dicts and copies tensors to device if possible.

    Non-tensor values are passed as-is in the result.

    .. note::
        These are all copies, so if there are two objects that reference
        the same object, then after this call, there will be two different objects
        referenced on the device.
    """
    if isinstance(value, torch.Tensor):
        return value.to(device, non_blocking=non_blocking)
    if isinstance(value, (list, tuple)):
        values = [_recursive_copy_to_device(val, non_blocking=non_blocking, device=device) for val in value]
        return values if isinstance(value, list) else tuple(values)
    if <MASK>:
        return {key: _recursive_copy_to_device(val, non_blocking=non_blocking, device=device) for (key, val) in value.items()}
    return value

def add_push_null_call_function_ex(inst_or_insts: Union[Instruction, list[Instruction]]) -> list[Instruction]:
    """Like add_push_null, but the low bit of LOAD_ATTR/LOAD_SUPER_ATTR
    is not set, due to an expected CALL_FUNCTION_EX instruction.
    """
    if isinstance(inst_or_insts, Instruction):
        insts: list[Instruction] = [inst_or_insts]
    else:
        assert isinstance(inst_or_insts, list)
        insts = inst_or_insts
    if sys.version_info < (3, 11):
        return insts
    idx = -1 if sys.version_info >= (3, 13) else 0
    if <MASK>:
        assert insts[idx].arg is not None
        if insts[idx].arg & 1 == 0:
            insts[idx].arg |= 1
            return insts
    if sys.version_info >= (3, 13):
        insts = insts + [create_instruction('PUSH_NULL')]
    else:
        insts = [create_instruction('PUSH_NULL')] + insts
    return insts

@np.errstate(over='ignore', invalid='ignore')
def __setitem__(self, indx, value):
    """
        x.__setitem__(i, y) <==> x[i]=y

        Set item described by index. If value is masked, masks those
        locations.

        """
    if self is masked:
        raise MaskError('Cannot alter the masked element.')
    _data = self._data
    _mask = self._mask
    if isinstance(indx, str):
        _data[indx] = value
        if <MASK>:
            self._mask = _mask = make_mask_none(self.shape, self.dtype)
        _mask[indx] = getmask(value)
        return
    _dtype = _data.dtype
    if value is masked:
        if _mask is nomask:
            _mask = self._mask = make_mask_none(self.shape, _dtype)
        if _dtype.names is not None:
            _mask[indx] = tuple([True] * len(_dtype.names))
        else:
            _mask[indx] = True
        return
    dval = getattr(value, '_data', value)
    mval = getmask(value)
    if _dtype.names is not None and mval is nomask:
        mval = tuple([False] * len(_dtype.names))
    if _mask is nomask:
        _data[indx] = dval
        if mval is not nomask:
            _mask = self._mask = make_mask_none(self.shape, _dtype)
            _mask[indx] = mval
    elif not self._hardmask:
        if isinstance(indx, masked_array) and (not isinstance(value, masked_array)):
            _data[indx.data] = dval
        else:
            _data[indx] = dval
            _mask[indx] = mval
    elif hasattr(indx, 'dtype') and indx.dtype == MaskType:
        indx = indx * umath.logical_not(_mask)
        _data[indx] = dval
    else:
        if _dtype.names is not None:
            err_msg = "Flexible 'hard' masks are not yet supported."
            raise NotImplementedError(err_msg)
        mindx = mask_or(_mask[indx], mval, copy=True)
        dindx = self._data[indx]
        if dindx.size > 1:
            np.copyto(dindx, dval, where=~mindx)
        elif mindx is nomask:
            dindx = dval
        _data[indx] = dindx
        _mask[indx] = mindx
    return

def add_root_elements(self, handler):
    handler.addQuickElement('title', self.feed['title'])
    handler.addQuickElement('link', '', {'rel': 'alternate', 'href': self.feed['link']})
    if self.feed['feed_url'] is not None:
        handler.addQuickElement('link', '', {'rel': 'self', 'href': self.feed['feed_url']})
    handler.addQuickElement('id', self.feed['id'])
    handler.addQuickElement('updated', rfc3339_date(self.latest_post_date()))
    if self.feed['author_name'] is not None:
        handler.startElement('author', {})
        handler.addQuickElement('name', self.feed['author_name'])
        if <MASK>:
            handler.addQuickElement('email', self.feed['author_email'])
        if self.feed['author_link'] is not None:
            handler.addQuickElement('uri', self.feed['author_link'])
        handler.endElement('author')
    if self.feed['subtitle'] is not None:
        handler.addQuickElement('subtitle', self.feed['subtitle'])
