def is_unexpected_success(testcase):

    def condition(children):
        for child in children:
            if child.tag != 'failure':
                continue
            is_unexpected_success = 'unexpected success' in child.attrib['message'].lower()
            if <MASK>:
                return True
        return False
    return find(testcase, condition)

