def strip_graph_default_valued_attrs(meta_graph_def):
    """Strips default valued attributes for node defs in given MetaGraphDef.

  This method also sets `meta_info_def.stripped_default_attrs` in the given
  `MetaGraphDef` proto to True.

  Args:
    meta_graph_def: `MetaGraphDef` protocol buffer

  Returns:
    None.
  """
    op_name_to_function = {}
    for function_def in meta_graph_def.graph_def.library.function:
        op_name_to_function[function_def.signature.name] = function_def

    def _strip_node_default_valued_attrs(node_def):
        """Removes default valued attributes from a single node def."""
        if <MASK>:
            return
        op_def = op_def_registry.get(node_def.op)
        if op_def is None:
            return
        attrs_to_strip = set()
        for (attr_name, attr_value) in node_def.attr.items():
            if _is_default_attr_value(op_def, attr_name, attr_value):
                attrs_to_strip.add(attr_name)
        for attr in attrs_to_strip:
            del node_def.attr[attr]
    for node_def in meta_graph_def.graph_def.node:
        _strip_node_default_valued_attrs(node_def)
    for function_def in meta_graph_def.graph_def.library.function:
        for function_node_def in function_def.node_def:
            _strip_node_default_valued_attrs(function_node_def)
    meta_graph_def.meta_info_def.stripped_default_attrs = True

def log_abs_det_jacobian(self, x, y):
    if <MASK>:
        return torch.zeros_like(x)
    xs = [x]
    for part in self.parts[:-1]:
        xs.append(part(xs[-1]))
    xs.append(y)
    terms = []
    event_dim = self.domain.event_dim
    for (part, x, y) in zip(self.parts, xs[:-1], xs[1:]):
        terms.append(_sum_rightmost(part.log_abs_det_jacobian(x, y), event_dim - part.domain.event_dim))
        event_dim += part.codomain.event_dim - part.domain.event_dim
    return functools.reduce(operator.add, terms)

def _yeo_johnson_inverse_transform(self, x, lmbda):
    """Return inverse-transformed input x following Yeo-Johnson inverse
        transform with parameter lambda.
        """
    x_inv = np.zeros_like(x)
    pos = x >= 0
    if <MASK>:
        x_inv[pos] = np.exp(x[pos]) - 1
    else:
        x_inv[pos] = np.power(x[pos] * lmbda + 1, 1 / lmbda) - 1
    if abs(lmbda - 2) > np.spacing(1.0):
        x_inv[~pos] = 1 - np.power(-(2 - lmbda) * x[~pos] + 1, 1 / (2 - lmbda))
    else:
        x_inv[~pos] = 1 - np.exp(-x[~pos])
    return x_inv

@traceback_utils.filter_traceback
def __call__(cls, *args, **kwargs):
    if <MASK>:
        variable_call = cls._variable_call(*args, **kwargs)
        if variable_call is not None:
            return variable_call
    return super(VariableMetaclass, cls).__call__(*args, **kwargs)

def z3str(e: z3.ExprRef) -> str:
    assert z3.is_expr(e), f'unsupported expression type: {e}'

    def get_args_str(e: z3.ExprRef) -> list[str]:
        return [z3str(e.arg(i)) for i in range(e.num_args())]
    e = z3.simplify(e)
    if not z3.is_app(e):
        raise ValueError(f"can't print Z3 expression: {e}")
    if z3.is_int_value(e) or z3.is_rational_value(e):
        return e.as_string()
    decl = e.decl()
    kind = decl.kind()
    op = str(decl)
    args = get_args_str(e)
    if kind == z3.Z3_OP_POWER:
        op = 'pow'
    elif <MASK>:

        def collect_str_args(e):
            if not (z3.is_app(e) and e.decl().kind() == kind):
                return [z3str(e)]
            else:
                return [x for i in range(e.num_args()) for x in collect_str_args(e.arg(i))]
        args = collect_str_args(e)
    elif kind == z3.Z3_OP_NOT:
        assert e.num_args() == 1
        arg = e.arg(0)
        assert z3.is_app(arg)
        argkind = arg.decl().kind()
        logic_inverse = {z3.Z3_OP_EQ: '!=', z3.Z3_OP_LE: '>', z3.Z3_OP_GE: '<'}
        if argkind in logic_inverse:
            op = logic_inverse[argkind]
            args = get_args_str(arg)
    elif kind in (z3.Z3_OP_TO_INT, z3.Z3_OP_TO_REAL):
        assert e.num_args() == 1
        argstr = z3str(e.arg(0))
        if argstr.startswith('(/'):
            return '(idiv' + argstr[2:]
        return argstr
    elif kind == z3.Z3_OP_UNINTERPRETED:
        assert e.num_args() == 0
        return str(decl)
    string = op + ' ' + ' '.join(args)
    return f'({string.rstrip()})'

def call_dist_op(self, profiling_title_postfix, is_async, op, *args, expect_event=True, secondary_op_call=None, profile_cuda=False, tensor_shapes=None, **kwargs):
    op_calls = [lambda : op(*args, **kwargs)]
    if secondary_op_call is not None:
        op_calls.append(secondary_op_call)
    autograd_profiler_ctx = torch.autograd.profiler.profile(use_cuda=profile_cuda, record_shapes=True)
    with autograd_profiler_ctx:
        works = [op_call() for op_call in op_calls]
        if <MASK>:
            for work in works:
                work.wait()
    if expect_event and dist.get_backend() in PROFILING_SUPPORTED_BACKENDS:
        events = get_profiling_event(dist.get_backend() + profiling_title_postfix, autograd_profiler_ctx)
        if dist.get_debug_level() != dist.DebugLevel.DETAIL:
            self.assertEqual(len(events), len(op_calls))
        for e in events:
            self.assertTrue(e.is_async)
            self.assertEqual(e.count, 1)
            self.assertGreaterEqual(e.cpu_time, 0)
            if tensor_shapes is not None and dist.get_debug_level() != dist.DebugLevel.DETAIL:
                self.assertEqual(e.input_shapes, tensor_shapes, f'event shape: {e.input_shapes} vs tensor {tensor_shapes}')

def fix_vars(instructions: list[Instruction], code_options: dict[str, Any], varname_from_oparg: Optional[Callable[..., Any]]=None) -> None:
    names = {name: idx for (idx, name) in enumerate(code_options['co_names'])}

    def get_name_index(name: str) -> int:
        try:
            idx = names[name]
        except KeyError:
            idx = names[name] = len(names)
            code_options['co_names'] = (*code_options['co_names'], name)
            assert len(code_options['co_names']) == len(names)
        return idx
    if sys.version_info < (3, 11):
        assert varname_from_oparg is None
        varnames = {name: idx for (idx, name) in enumerate(code_options['co_varnames'])}
        freenames = {name: idx for (idx, name) in enumerate(code_options['co_cellvars'] + code_options['co_freevars'])}
    else:
        assert callable(varname_from_oparg)
        allnames = {}
        for idx in itertools.count():
            try:
                name = varname_from_oparg(idx)
                allnames[name] = idx
            except IndexError:
                break
        varnames = {name: allnames[name] for name in code_options['co_varnames']}
        freenames = {name: allnames[name] for name in code_options['co_cellvars'] + code_options['co_freevars']}
    for i in range(len(instructions)):

        def should_compute_arg() -> bool:
            return instructions[i].argval is not _NotProvided
        if instructions[i].opname == 'LOAD_GLOBAL':
            assert instructions[i].argval is not _NotProvided
            if sys.version_info >= (3, 11):
                assert instructions[i].arg is not None
                instructions[i].arg = (get_name_index(instructions[i].argval) << 1) + cast(int, instructions[i].arg) % 2
            else:
                instructions[i].arg = get_name_index(instructions[i].argval)
        elif instructions[i].opname == 'LOAD_ATTR':
            assert instructions[i].argval is not _NotProvided
            if sys.version_info >= (3, 12):
                assert instructions[i].arg is not None
                instructions[i].arg = (get_name_index(instructions[i].argval) << 1) + cast(int, instructions[i].arg) % 2
            else:
                instructions[i].arg = get_name_index(instructions[i].argval)
        elif instructions[i].opname == 'LOAD_SUPER_ATTR':
            assert instructions[i].arg is not None
            assert instructions[i].argval is not _NotProvided
            instructions[i].arg = (get_name_index(instructions[i].argval) << 2) + cast(int, instructions[i].arg) % 2 + 2
        elif instructions[i].opname in FUSED_INSTS:
            assert sys.version_info >= (3, 13)
            assert isinstance(instructions[i].argval, tuple)
            assert len(instructions[i].argval) == 2
            arg_tuple = tuple((varnames[name] if name in varnames else freenames[name] for name in instructions[i].argval))
            instructions[i].arg = (arg_tuple[0] << 4) + (arg_tuple[1] & 15)
        elif instructions[i].opcode in HAS_LOCAL:
            if should_compute_arg():
                if sys.version_info >= (3, 13) and instructions[i].argval not in varnames:
                    instructions[i].arg = freenames[instructions[i].argval]
                else:
                    instructions[i].arg = varnames[instructions[i].argval]
        elif instructions[i].opcode in HAS_NAME:
            if should_compute_arg():
                instructions[i].arg = get_name_index(instructions[i].argval)
        elif <MASK>:
            if should_compute_arg():
                instructions[i].arg = freenames[instructions[i].argval]
        elif instructions[i].opcode in HAS_CONST:
            if instructions[i].arg is None:
                idx = get_const_index(code_options, instructions[i].argval)
                assert idx >= 0
                instructions[i].arg = idx

def forward(self, *args, **kwargs):
    executor_args = args
    if len(kwargs) > 0:
        parameters = []
        for node in self.split_gm.graph.nodes:
            if node.op == 'placeholder':
                if node.args and len(node.args) > 0:
                    parameters.append(Parameter(node.target, Parameter.POSITIONAL_OR_KEYWORD, default=node.args[0]))
                else:
                    parameter_kind = Parameter.POSITIONAL_OR_KEYWORD
                    param_name = node.target
                    if node.target.startswith('**'):
                        parameter_kind = Parameter.VAR_KEYWORD
                        param_name = param_name[2:]
                    elif <MASK>:
                        parameter_kind = Parameter.VAR_POSITIONAL
                        param_name = param_name[1:]
                    parameters.append(Parameter(param_name, parameter_kind))
        signature = Signature(parameters)
        ba = signature.bind(*args, **kwargs)
        ba.apply_defaults()
        executor_args = ba.arguments.values()
    res = self.executor.run(*executor_args)
    return res

def _parse_multi_target(self, targets):
    """validate multi targets that defined between parentheses()"""
    if not targets:
        self.dist_fatal("empty multi-target '()'")
    if <MASK>:
        self.dist_fatal('invalid target name in multi-target', targets)
    if not all([tar in self.parse_baseline_names or tar in self.parse_dispatch_names for tar in targets]):
        return None
    targets = self.feature_ahead(targets)
    if not targets:
        return None
    targets = self.feature_sorted(targets)
    targets = tuple(targets)
    return targets

def _coalesce_timeline(self, device_str):
    """Convert the memory timeline and categories into a memory plot
        consisting of timestamps and their respective sizes by category
        for a given device.

        Input: device
        Output: [timestamps, sizes by category]
        """
    device = torch.device(device_str)
    times: list[int] = []
    sizes: list[list[int]] = []

    def update(key, version, delta) -> None:
        category = self.categories.get(key, version) if isinstance(key, TensorKey) else None
        index = _CATEGORY_TO_INDEX[category] + 1
        sizes[-1][index] += int(delta)
    t_min = -1
    for (t, action, (key, version), numbytes) in self.timeline:
        if key.device != device:
            continue
        if t != -1:
            t = int(t / 1000)
        if t_min == -1 or (t < t_min and t > 0):
            t_min = t
        if <MASK>:
            times.append(t)
            sizes.append([0] + [0 for _ in _CATEGORY_TO_INDEX])
        elif t != times[-1]:
            times.append(t)
            sizes.append(sizes[-1].copy())
        if action in (Action.PREEXISTING, Action.CREATE):
            update(key, version, numbytes)
        elif action == Action.INCREMENT_VERSION:
            update(key, version, -numbytes)
            update(key, version + 1, numbytes)
        elif action == Action.DESTROY:
            update(key, version, -numbytes)
        else:
            raise ValueError(f'Unknown action: {action}')
    times = [t_min if t < 0 else t for t in times]
    return (times, sizes)

