        tmp_results = {key: value}
        tmp_attr_list.append(tmp_results)
    return tmp_attr_list

def __check_tensor_list(self, tensor_list):
    """Raises an exception if tensor_list incompatible w/ flat_tensor_specs."""
    expected = self._flat_tensor_specs
    specs = [type_spec_from_value(t) for t in tensor_list]
    if len(specs) != len(expected):
        raise ValueError(f'Cannot create a {self.value_type.__name__} from the tensor list because the TypeSpec expects {len(expected)} items, but the provided tensor list has {len(specs)} items.')
    for (i, (s1, s2)) in enumerate(zip(specs, expected)):
        if <MASK>:
            raise ValueError(f'Cannot create a {self.value_type.__name__} from the tensor list because item {i} ({tensor_list[i]!r}) is incompatible with the expected TypeSpec {s2}.')

def _size_of(node: fx.Node) -> int:

    def object_nbytes(x) -> int:
        if not isinstance(x, torch.Tensor):
            return 0
        return _tensor_nbytes(hint_int(x.numel(), fallback=4096), x.dtype)
    if 'val' in node.meta:
        val = node.meta['val']
        if isinstance(val, py_sym_types):
            return 1
        elif isinstance(val, (list, tuple)):
            return sum((object_nbytes(n) for n in val))
        elif <MASK>:
            return sum((object_nbytes(n) for (_, n) in val.items()))
        elif isinstance(val, torch.Tensor):
            return object_nbytes(val)
        raise RuntimeError(f'Unknown metadata type {type(val)} on node {node}')
    if node.op == 'get_attr' or node.target is torch.ops.aten._assert_scalar.default:
        return 0
    raise RuntimeError(f"Node {node} didn't have `val` metadata; we should always have `val` metadata on the nodes.")

def find_common_type(types):
    """
    Find a common data type among the given dtypes.

    Parameters
    ----------
    types : list of dtypes

    Returns
    -------
    pandas extension or numpy dtype

    See Also
    --------
    numpy.find_common_type

    """
    if not types:
        raise ValueError('no types given')
    first = types[0]
    if lib.dtypes_all_equal(list(types)):
        return first
    types = list(dict.fromkeys(types).keys())
    if any((isinstance(t, ExtensionDtype) for t in types)):
        for t in types:
            if isinstance(t, ExtensionDtype):
                res = t._get_common_dtype(types)
                if res is not None:
                    return res
        return np.dtype('object')
    if all((lib.is_np_dtype(t, 'M') for t in types)):
        return np.dtype(max(types))
    if all((lib.is_np_dtype(t, 'm') for t in types)):
        return np.dtype(max(types))
    has_bools = any((t.kind == 'b' for t in types))
    if <MASK>:
        for t in types:
            if t.kind in 'iufc':
                return np.dtype('object')
    return np_find_common_type(*types)

def clean_interp_method(method: str, index: Index, **kwargs) -> str:
    order = kwargs.get('order')
    if method in ('spline', 'polynomial') and order is None:
        raise ValueError('You must specify the order of the spline or polynomial.')
    valid = NP_METHODS + SP_METHODS
    if <MASK>:
        raise ValueError(f"method must be one of {valid}. Got '{method}' instead.")
    if method in ('krogh', 'piecewise_polynomial', 'pchip'):
        if not index.is_monotonic_increasing:
            raise ValueError(f'{method} interpolation requires that the index be monotonic.')
    return method

def polyfit(x, y, deg, rcond=None, full=False, w=None, cov=False):
    """
    Any masked values in x is propagated in y, and vice-versa.

    """
    x = asarray(x)
    y = asarray(y)
    m = getmask(x)
    if y.ndim == 1:
        m = mask_or(m, getmask(y))
    elif y.ndim == 2:
        my = getmask(mask_rows(y))
        if my is not nomask:
            m = mask_or(m, my[:, 0])
    else:
        raise TypeError('Expected a 1D or 2D array for y!')
    if w is not None:
        w = asarray(w)
        if w.ndim != 1:
            raise TypeError('expected a 1-d array for weights')
        if <MASK>:
            raise TypeError('expected w and y to have the same length')
        m = mask_or(m, getmask(w))
    if m is not nomask:
        not_m = ~m
        if w is not None:
            w = w[not_m]
        return np.polyfit(x[not_m], y[not_m], deg, rcond, full, w, cov)
    else:
        return np.polyfit(x, y, deg, rcond, full, w, cov)

def as_factors(obj):
    """Return expression as FACTORS expression.
    """
    if isinstance(obj, Expr):
        obj = normalize(obj)
        if obj.op is Op.FACTORS:
            return obj
        if obj.op is Op.TERMS:
            if len(obj.data) == 1:
                ((term, coeff),) = obj.data.items()
                if coeff == 1:
                    return Expr(Op.FACTORS, {term: 1})
                return Expr(Op.FACTORS, {term: 1, Expr.number(coeff): 1})
        if <MASK>:
            return Expr(Op.FACTORS, {obj.data[1][0]: 1, obj.data[1][1]: -1})
        return Expr(Op.FACTORS, {obj: 1})
    raise OpError(f'cannot convert {type(obj)} to terms Expr')

def _unwrap_setitem_indexer(self, indexer):
    """
        Adapt a 2D-indexer to our 1D values.

        This is intended for 'setitem', not 'iget' or '_slice'.
        """
    if isinstance(indexer, tuple) and len(indexer) == 2:
        if all((isinstance(x, np.ndarray) and x.ndim == 2 for x in indexer)):
            (first, second) = indexer
            if <MASK>:
                raise NotImplementedError('This should not be reached. Please report a bug at github.com/pandas-dev/pandas/')
            indexer = first[:, 0]
        elif lib.is_integer(indexer[1]) and indexer[1] == 0:
            indexer = indexer[0]
        elif com.is_null_slice(indexer[1]):
            indexer = indexer[0]
        elif is_list_like(indexer[1]) and indexer[1][0] == 0:
            indexer = indexer[0]
        else:
            raise NotImplementedError('This should not be reached. Please report a bug at github.com/pandas-dev/pandas/')
    return indexer

def rich_text_lines_from_rich_line_list(rich_text_list, annotations=None):
    """Convert a list of RichLine objects or strings to a RichTextLines object.

  Args:
    rich_text_list: a list of RichLine objects or strings
    annotations: annotations for the resultant RichTextLines object.

  Returns:
    A corresponding RichTextLines object.
  """
    lines = []
    font_attr_segs = {}
    for (i, rl) in enumerate(rich_text_list):
        if isinstance(rl, RichLine):
            lines.append(rl.text)
            if <MASK>:
                font_attr_segs[i] = rl.font_attr_segs
        else:
            lines.append(rl)
    return RichTextLines(lines, font_attr_segs, annotations=annotations)

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif name == 'extend' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
