def _populate_quantization_options_default_values(quantization_options: _QuantizationOptions) -> None:
    """Populates default values for QuantizationOptions.

  Populates unspecified or unset fields of QuantizationOptions with the default
  values.

  * If `op_set` is unspecified, it defaults to `OpSet.XLA`.
  * If `freeze_all_variables` is not set, it defaults to `True`.
  * Check if configurations are set correctly:
    - Per-channel quantization is supported for Uniform Quantized opset only.

  Args:
    quantization_options: An instance of QuantizationOptions.
  """
    if quantization_options.op_set == quant_opts_pb2.OpSet.OP_SET_UNSPECIFIED:
        quantization_options.op_set = quant_opts_pb2.OpSet.XLA
    if not quantization_options.tags:
        quantization_options.tags.append(tag_constants.SERVING)
    if not quantization_options.signature_keys:
        quantization_options.signature_keys.append(signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY)
    if not quantization_options.HasField('freeze_all_variables'):
        quantization_options.freeze_all_variables = True
    if quantization_options.enable_legacy_weight_only:
        raise ValueError('Legacy weight-only is deprecated. Use weight-only quantization method.')
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_UNSPECIFIED:
        logging.debug('"preset_method" for QuantizationMethod is not specified.Static range quantization is used by default.')
        quantization_options.quantization_method.preset_method = _PresetMethod.METHOD_STATIC_RANGE_INT8
    if quantization_options.min_num_elements_for_weights == 0:
        quantization_options.min_num_elements_for_weights = _DYNAMIC_RANGE_DEFAULT_MIN_NUM_ELEMENTS_FOR_WEIGHTS
        logging.warning('QuantizationOptions.min_num_elements_for_weights is not set (0). Setting to the default value: %d.', _DYNAMIC_RANGE_DEFAULT_MIN_NUM_ELEMENTS_FOR_WEIGHTS)
    if not quantization_options.HasField('enable_per_channel_quantization'):
        quantization_options.enable_per_channel_quantization = False
    if quantization_options.enable_per_channel_quantization and (not ((quantization_options.op_set == quant_opts_pb2.OpSet.UNIFORM_QUANTIZED or quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8) or (quantization_options.op_set in (quant_opts_pb2.OpSet.XLA, quant_opts_pb2.OpSet.STABLEHLO) and quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8))):
        raise ValueError('Currently, per-channel quantization is supported for Uniform Quantized opset, weight only quantization, or XLA/StableHLO opset with static range quantization.')
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8 and (quantization_options.op_set == quant_opts_pb2.OpSet.UNIFORM_QUANTIZED or quantization_options.op_set == quant_opts_pb2.OpSet.TF):
        raise ValueError('TF/Uniform quantized opset does not support weight-only.')
    if <MASK>:
        raise ValueError('StableHLO quantized opset currently only supports static range quantization and weight-only quantizationvia TF Quantizer.')
    logging.debug('Setting `force_graph_mode_calibration = True` to ensure the calibration mode is executed properly.')
    quantization_options.force_graph_mode_calibration = True
    if quantization_options.HasField('debugger_config'):
        if not quantization_options.debugger_config.log_dir_path:
            quantization_options.debugger_config.log_dir_path = '/tmp/dumps'
        if quantization_options.debugger_config.debugger_type == stablehlo_quant_config_pb2.DebuggerConfig.DebuggerType.DEBUGGER_TYPE_UNSPECIFIED:
            raise ValueError('Debugger is enabled but debugger type was not specified.')
        if quantization_options.debugger_config.debugger_type == stablehlo_quant_config_pb2.DebuggerConfig.DebuggerType.DEBUGGER_TYPE_WHOLE_MODEL and (not quantization_options.debugger_config.unquantized_dump_model_path):
            raise ValueError('Debugger type whole model verify was used but unquantized_dump_model_path was not specified.')
    _populate_quantization_component_spec(quantization_options.quantization_method)
    _populate_unitwise_quantization_specs(quantization_options)
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8:
        _populate_calibration_options(quantization_options)

def run(self, fetches, feed_dict=None, options=None, run_metadata=None, callable_runner=None, callable_runner_args=None, callable_options=None):
    """Wrapper around Session.run() that inserts tensor watch options.

    Args:
      fetches: Same as the `fetches` arg to regular `Session.run()`.
      feed_dict: Same as the `feed_dict` arg to regular `Session.run()`.
      options: Same as the `options` arg to regular `Session.run()`.
      run_metadata: Same as the `run_metadata` arg to regular `Session.run()`.
      callable_runner: A `callable` returned by `Session.make_callable()`.
        If not `None`, `fetches` and `feed_dict` must both be `None`.
        Mutually exclusive with `callable_options`.
      callable_runner_args: An optional list of arguments to `callable_runner`
        or for `callable_options`.
      callable_options: An instance of `config_pb2.CallableOptions`, to be
        used with `Session._make_callable_from_options()`. Mutually exclusive
        with `callable_runner`.

    Returns:
      Simply forwards the output of the wrapped `Session.run()` call.

    Raises:
      ValueError: On invalid `OnRunStartAction` value. Or if `callable_runner`
        is not `None` and either or both of `fetches` and `feed_dict` is `None`.
    """
    if callable_runner and callable_options:
        raise ValueError('callable_runner and callable_options are mutually exclusive, but are both specified in this call to BaseDebugWrapperSession.run().')
    if callable_runner and (fetches or feed_dict):
        raise ValueError('callable_runner and fetches/feed_dict are mutually exclusive, but are used simultaneously.')
    elif callable_options and (fetches or feed_dict):
        raise ValueError('callable_options and fetches/feed_dict are mutually exclusive, but are used simultaneously.')
    self.increment_run_call_count()

    def is_empty(x):
        """Check whether a possibly nested structure is empty."""
        if not nest.is_nested(x):
            return False
        if isinstance(x, collections_abc.Mapping):
            return is_empty(list(x.values()))
        for item in x:
            if not is_empty(item):
                return False
        return True
    empty_fetches = is_empty(fetches)
    if empty_fetches:
        tf_logging.info('Due to empty fetches, tfdbg Session wrapper is letting a Session.run pass through without any debugging actions.')
    if self._is_disabled_thread() or empty_fetches:
        if callable_runner:
            return callable_runner(*callable_runner_args)
        elif callable_options:
            return self._sess._make_callable_from_options(callable_options)(*callable_runner_args)
        else:
            return self._sess.run(fetches, feed_dict=feed_dict, options=options, run_metadata=run_metadata)
    run_start_resp = self.on_run_start(OnRunStartRequest(fetches, feed_dict, options, run_metadata, self._run_call_count, is_callable_runner=bool(callable_runner)))
    _check_type(run_start_resp, OnRunStartResponse)
    if run_start_resp.action == OnRunStartAction.DEBUG_RUN:
        (retvals, run_end_req) = self._run_with_debugging(run_start_resp, fetches, feed_dict, options, run_metadata, callable_runner, callable_runner_args, callable_options)
    elif run_start_resp.action == OnRunStartAction.PROFILE_RUN:
        (retvals, run_end_req) = self._run_with_profiling(run_start_resp, fetches, feed_dict, options, run_metadata, callable_runner, callable_runner_args, callable_options)
    elif <MASK>:
        if callable_runner:
            retvals = callable_runner(*callable_runner_args)
        elif callable_options:
            callable_object = self._sess._make_callable_from_options(callable_options)
            retvals = callable_object(*callable_runner_args)
        else:
            retvals = self._sess.run(fetches, feed_dict=feed_dict, options=options, run_metadata=run_metadata)
        run_end_req = OnRunEndRequest(run_start_resp.action)
    else:
        raise ValueError('Invalid OnRunStartAction value: %s' % run_start_resp.action)
    run_end_resp = self.on_run_end(run_end_req)
    _check_type(run_end_resp, OnRunEndResponse)
    return retvals

def _is_packable_convolution(match):
    """
        Check if the node is supported for MKLDNN convolution.
        """
    conv_node = match.output_node()
    device_type = conv_node.meta.get('val').device.type
    if match.kwargs['is_transposed'] and device_type == 'xpu':
        return False
    input_meta_value = conv_node.args[0].meta.get('val')
    weight_meta_value = conv_node.args[1].meta.get('val')
    if input_meta_value is None or weight_meta_value is None:
        return False
    input_size = input_meta_value.shape
    if conv_node.args[1].op != 'get_attr':
        return False
    for meta_value in [input_meta_value, weight_meta_value]:
        if meta_value is None or meta_value.device.type not in SUPPORTED_MKLDNN_DEVICES or (meta_value.dim() != 4 and meta_value.dim() != 5):
            return False
    if input_meta_value.dtype == torch.bfloat16 or weight_meta_value.dtype == torch.bfloat16:
        if not is_mkldnn_bf16_supported(device_type):
            return False
    if input_meta_value.dtype == torch.float16 or weight_meta_value.dtype == torch.float16:
        if <MASK>:
            return False
    is_transposed = conv_node.args[-3]
    if is_transposed:
        if has_free_symbols(input_size):
            return False
        groups = conv_node.args[-1]
        in_channels = weight_meta_value.size(0)
        if groups > 1 and groups == in_channels:
            return False
        output_paddings = conv_node.args[-2]
        strides = conv_node.args[3]
        if any((output_padding >= stride for (output_padding, stride) in zip(output_paddings, strides))):
            return False
    return True

def get_select2_language():
    lang_code = get_language()
    supported_code = SELECT2_TRANSLATIONS.get(lang_code)
    if <MASK>:
        i = None
        while (i := lang_code.rfind('-', 0, i)) > -1:
            if (supported_code := SELECT2_TRANSLATIONS.get(lang_code[:i])):
                return supported_code
    return supported_code

@register_meta(aten._cslt_sparse_mm)
def meta__cslt_sparse_mm(compressed_A: torch.Tensor, dense_B: torch.Tensor, bias: Optional[Tensor]=None, alpha: Optional[Tensor]=None, out_dtype: Optional[torch.dtype]=None, transpose_result: bool=False, alg_id: int=0, split_k: int=1, split_k_mode: int=-1):
    assert dense_B.dtype in {torch.float32, torch.float16, torch.bfloat16, torch.int8, torch.float8_e4m3fn}, '_cslt_sparse_mm only supports fp16, bf16, int8, and fp8e4m3'
    assert compressed_A.dtype == dense_B.dtype, 'inputs must have the same dtype'
    assert len(dense_B.shape) == 2, '_cslt_sparse_mm only supports 2d inputs'
    is_8bit_input_type = compressed_A.dtype in [torch.int8, torch.float8_e4m3fn]
    if is_8bit_input_type:
        assert not dense_B.is_contiguous(), 'dense input must be transposed for 8bit dtypes'
    n = dense_B.size(1)
    m = compressed_A.size(0)
    if <MASK>:
        assert m == bias.size(0)
    if out_dtype is not None:
        assert is_8bit_input_type and out_dtype in {torch.float16, torch.bfloat16, torch.int32, torch.float8_e4m3fn}, f'out_dtype is not supported for {compressed_A.dtype} x {dense_B.dtype} -> {out_dtype} matmul!'
    output_shape = (n, m) if transpose_result else (m, n)
    return dense_B.new_empty(output_shape, dtype=out_dtype)

def call_kernel(self, name: str, node: Any=None) -> None:
    """
        Codegens a call to this kernel
        """
    wrapper = V.graph.wrapper_code
    for v in self.args.sizevars.keys():
        wrapper.ensure_size_computed(v)
    (_, call_args, _, arg_types) = self.args.python_argdefs()
    arg_name_to_type = {str(call_arg): arg_type for (call_arg, arg_type) in zip(call_args, arg_types)}
    args = [*self.args.output_buffers.keys(), *self.args.input_buffers.keys()]
    args = [arg for arg in args if arg not in self.removed_buffers]
    args += [str(v) for v in self.args.sizevars.keys()]
    arg_types = [arg_name_to_type[arg] for arg in args]
    for tree in self.range_trees:
        if isinstance(tree.numel, (sympy.Integer, int)):
            continue
        elif isinstance(tree.numel, sympy.Symbol):
            expr = tree.numel
        else:
            expr = V.graph.wrapper_code.generate_numel_expr(name, tree).inner
        if not tree.is_reduction or self.inside_reduction:
            args.append(str(expr))
            arg_types.append(int)
    expr_printer = self.cexpr if V.graph.cpp_wrapper else self.pexpr

    def format_threads(threads: list[str], kwarg: str) -> str:
        if V.graph.cpp_wrapper:
            threads = [f'static_cast<uint64_t>({t})' for t in threads]
            return f"{{{', '.join(threads)}}}"
        else:
            return f"{kwarg}=[{', '.join(threads)}]"
    if <MASK>:
        threads = [expr_printer(sympy.Min(v.numel, self.max_threadgroup_size) if v.is_reduction else v.numel) for v in self.active_range_trees()]
        args.append(format_threads(threads, 'threads'))
        arg_types.append(list)
    elif V.graph.cpp_wrapper:
        raise RuntimeError('We should always have threads?')
    if self.inside_reduction:
        threads = [expr_printer(sympy.Min(v.numel, self.max_threadgroup_size)) if v.is_reduction else '1' for v in self.active_range_trees()]
        args.append(format_threads(threads, 'group_size'))
        arg_types.append(list)
    elif V.graph.cpp_wrapper:
        args += [None]
        arg_types.append(None)
    wrapper.generate_kernel_call(name, args, device=torch.device('mps'), triton=False, arg_types=arg_types)

def __lt__(self, other: object) -> bool:
    if not isinstance(other, ShardedTest):
        raise NotImplementedError
    if self.name != other.name:
        return self.name < other.name
    if self.shard != other.shard:
        return self.shard < other.shard
    if self.num_shards != other.num_shards:
        return self.num_shards < other.num_shards
    if self.time is None:
        return True
    if <MASK>:
        return False
    return self.time < other.time

def generate_fallback_kernel_with_runtime_lookup(self, buf_name: str, python_kernel_name: str, get_args: Callable[[], Sequence[str]], op_overload: Union[torch._ops.OpOverload, torch._ops.HigherOrderOperator], raw_args: Sequence[Any], outputs: Sequence[ir.Buffer]) -> None:
    """Generate a call to a kernel not contained in the C-shim.  This results in
        different code paths for AOT Inductor vs cpp_wrapper Inductor mode."""

    def extract_output_name(out: Optional[Union[ir.Buffer, Sequence[ir.Buffer]]]) -> Union[Optional[str], _OUTPUT_ARGS_TYPE]:
        if out is None:
            return None
        if isinstance(out, (ir.MultiOutput, ir._CollectiveKernel)):
            return out.get_name()
        if isinstance(out, ir.MutationOutput):
            mutated_buf_names = out.get_mutation_names()
            assert isinstance(mutated_buf_names, list) and len(mutated_buf_names) == 1, 'Expect only one mutated buffer in MutationOutput'
            return mutated_buf_names[0]
        if isinstance(out, (list, tuple)):
            return [extract_output_name(o) for o in out]
        if isinstance(out, int):
            return str(out)
        raise AssertionError(f'Unexpected output: {type(out)}')
    if <MASK>:
        assert isinstance(op_overload, torch._higher_order_ops.torchbind.CallTorchBind), type(op_overload)
        assert len(raw_args) > 1
        obj = raw_args[0]
        method = raw_args[1]
        return_schema = op_overload.schema(obj, method).returns
    else:
        return_schema = op_overload._schema.returns
    if not return_schema:
        output_args: _OUTPUT_ARGS_TYPE = []
    elif isinstance((output_name := extract_output_name(outputs)), str):
        output_args = [output_name]
    else:
        assert isinstance(output_name, list), type(output_name)
        output_args = output_name
    if V.graph.aot_mode:
        self.generate_fallback_kernel_with_runtime_lookup_aot(op_overload, raw_args, output_args, outputs)
        return
    assert isinstance(op_overload, torch._ops.OpOverload), type(op_overload)
    for output in output_args:
        assert output is None or isinstance(output, str), 'fallback kernels with runtime lookup currently only support tensor returns, not more complicated types (such as list-of-list-of-tensor)'
    if self._compatible_with_stableivalue(op_overload):
        self.generate_fallback_kernel_with_runtime_lookup_nopython(get_args, op_overload, output_args, outputs)
        return
    self.generate_fallback_kernel_with_runtime_lookup_python(buf_name, python_kernel_name, op_overload, raw_args, output_args, outputs)

