            traceable_sig = inspect.signature(traceable_fn)

            def sig_ident(sig: inspect.Signature) -> tuple[tuple[str, ...], set[str], dict[str, Any]]:
                return (tuple((p.name for p in sig.parameters.values() if p.kind not in {p.KEYWORD_ONLY, p.VAR_POSITIONAL, p.VAR_KEYWORD})), {p.name for p in sig.parameters.values() if p.kind == p.KEYWORD_ONLY}, {p.name: p.default for p in sig.parameters.values() if p.kind not in {p.VAR_POSITIONAL, p.VAR_KEYWORD}})
            wildcard_sig = inspect.signature(lambda *args, **kwargs: None)
            if sig_ident(original_sig) != sig_ident(traceable_sig) and sig_ident(original_sig) != sig_ident(wildcard_sig) and (sig_ident(traceable_sig) != sig_ident(wildcard_sig)):
                raise TypeError(f'Signature mismatch between {original_fn} and {traceable_fn}: {original_sig} != {traceable_sig}')
    from torch._dynamo.guards import GuardBuilder
    from torch._dynamo.trace_rules import _polyfilled_function_ids, get_torch_obj_rule_map
    from torch._dynamo.variables import PolyfilledFunctionVariable
    from torch._dynamo.variables.builder import VariableBuilder
    id_dispatch_map = VariableBuilder._id_dispatch()
    if id(original_fn) in id_dispatch_map:
        raise ValueError(f"Duplicate dispatch rule for {original_fn}: already registered in VariableBuilder's id dispatch map")
    if id(original_fn) in _polyfilled_function_ids:
        raise ValueError(f'Duplicate polyfilled object {original_fn}')
    rule_map: dict[Any, type[VariableTracker]] = get_torch_obj_rule_map()
    if original_fn in rule_map:
        raise ValueError(f'Duplicate object {original_fn} with different rules: {PolyfilledFunctionVariable}, {rule_map[original_fn]}')
    polyfill_handlers: dict[Callable[..., Any], FunctionType]
    polyfill_handlers = PolyfilledFunctionVariable._get_polyfill_handlers()
    if original_fn in polyfill_handlers:
        raise ValueError(f'Duplicate polyfill handlers for {original_fn}: already handled by {polyfill_handlers[original_fn]}')

    @functools.wraps(traceable_fn)
    def wrapped(*args: _P.args, **kwargs: _P.kwargs) -> _R:
        return original_fn(*args, **kwargs)

    def dispatch_fn(self: VariableBuilder, value: Callable[_P, _R]) -> PolyfilledFunctionVariable:
        return PolyfilledFunctionVariable(value, source=self.source, **self.install_guards(GuardBuilder.FUNCTION_MATCH))
    id_dispatch_map[id(original_fn)] = id_dispatch_map[id(wrapped)] = dispatch_fn
    _polyfilled_function_ids.add(id(original_fn))
    _polyfilled_function_ids.add(id(wrapped))
    rule_map[original_fn] = rule_map[wrapped] = PolyfilledFunctionVariable
    polyfill_handlers[original_fn] = polyfill_handlers[wrapped] = wrapped
    wrapped.__torch_dynamo_original__ = original_fn
    wrapped.__torch_dynamo_polyfill__ = traceable_fn
    wrapped.__torch_dynamo_can_constant_fold_through__ = can_constant_fold_through
    return wrapped

@functools.wraps(func)
def new_func(*args, **kwargs):
