    return func(*args, **kwargs)

def _populate(self):
    if getattr(self._local, 'populating', False):
        return
    try:
        self._local.populating = True
        lookups = MultiValueDict()
        namespaces = {}
        apps = {}
        language_code = get_language()
        for url_pattern in reversed(self.url_patterns):
            p_pattern = url_pattern.pattern.regex.pattern
            p_pattern = p_pattern.removeprefix('^')
            if isinstance(url_pattern, URLPattern):
                self._callback_strs.add(url_pattern.lookup_str)
                bits = normalize(url_pattern.pattern.regex.pattern)
                lookups.appendlist(url_pattern.callback, (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters))
                if <MASK>:
                    lookups.appendlist(url_pattern.name, (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters))
            else:
                url_pattern._populate()
                if url_pattern.app_name:
                    apps.setdefault(url_pattern.app_name, []).append(url_pattern.namespace)
                    namespaces[url_pattern.namespace] = (p_pattern, url_pattern)
                else:
                    for name in url_pattern.reverse_dict:
                        for (matches, pat, defaults, converters) in url_pattern.reverse_dict.getlist(name):
                            new_matches = normalize(p_pattern + pat)
                            lookups.appendlist(name, (new_matches, p_pattern + pat, {**defaults, **url_pattern.default_kwargs}, {**self.pattern.converters, **url_pattern.pattern.converters, **converters}))
                    for (namespace, (prefix, sub_pattern)) in url_pattern.namespace_dict.items():
                        current_converters = url_pattern.pattern.converters
                        sub_pattern.pattern.converters.update(current_converters)
                        namespaces[namespace] = (p_pattern + prefix, sub_pattern)
                    for (app_name, namespace_list) in url_pattern.app_dict.items():
                        apps.setdefault(app_name, []).extend(namespace_list)
                self._callback_strs.update(url_pattern._callback_strs)
        self._namespace_dict[language_code] = namespaces
        self._app_dict[language_code] = apps
        self._reverse_dict[language_code] = lookups
        self._populated = True
    finally:
        self._local.populating = False

def lookup_allowed(self, lookup, value, request):
    from django.contrib.admin.filters import SimpleListFilter
    model = self.model
    for fk_lookup in model._meta.related_fkey_lookups:
        if callable(fk_lookup):
            fk_lookup = fk_lookup()
        if (lookup, value) in widgets.url_params_from_lookup_dict(fk_lookup).items():
            return True
    relation_parts = []
    prev_field = None
    parts = lookup.split(LOOKUP_SEP)
    for part in parts:
        try:
            field = model._meta.get_field(part)
        except FieldDoesNotExist:
            break
        if not prev_field or (prev_field.is_relation and field not in model._meta.parents.values() and (field is not model._meta.auto_field) and (model._meta.auto_field is None or part not in getattr(prev_field, 'to_fields', [])) and (field.is_relation or not field.primary_key)):
            relation_parts.append(part)
        if <MASK>:
            break
        prev_field = field
        model = field.path_infos[-1].to_opts.model
    if len(relation_parts) <= 1:
        return True
    valid_lookups = {self.date_hierarchy}
    for filter_item in self.get_list_filter(request):
        if isinstance(filter_item, type) and issubclass(filter_item, SimpleListFilter):
            valid_lookups.add(filter_item.parameter_name)
        elif isinstance(filter_item, (list, tuple)):
            valid_lookups.add(filter_item[0])
        else:
            valid_lookups.add(filter_item)
    return not {LOOKUP_SEP.join(relation_parts), LOOKUP_SEP.join([*relation_parts, part])}.isdisjoint(valid_lookups)

@classmethod
def create(cls, kernel: _OpOverloads, *args: Any, **kwargs: Any) -> FallbackKernel:
    """Create an instance of FallbackKernel from an _OpOverloads"""
    fake_incorrect_kernels = (aten._fused_moving_avg_obs_fq_helper_functional,)
    if <MASK>:
        context = cast(AbstractContextManager[None], V.graph.fake_mode)
    else:
        context = nullcontext()
    with context:
        (example_output, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings) = cls.process_kernel(kernel, *args, **kwargs)
    has_unaligned_input = any((is_unaligned(arg) for arg in tensor_args))
    device = cls.find_device(tensor_args, example_output)
    if not device and isinstance(kernel, torch._higher_order_ops.torchbind.CallTorchBind):
        device = torch.device('cpu')
    if example_output is None:
        packed = cls(NoneLayout(device=device), kernel, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings=unbacked_bindings)
    else:
        assert device, 'Not sure where to find device info'
        packed = cls(MultiOutputLayout(device=device), kernel, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings=unbacked_bindings)

    def generate_output(output: Any, indices: list[tuple[Any, int]]) -> Any:
        if isinstance(output, (list, tuple)):
            return type(output)((generate_output(output[i], indices + [(type(output), i)]) for i in range(len(output))))
        elif isinstance(output, dict):
            return {key: generate_output(val, indices + [(type(output), key)]) for (key, val) in output.items()}
        elif isinstance(output, torch.Tensor):
            buf = MultiOutput(cls.tensor_to_layout(output), packed, indices)
            if config.assume_unaligned_fallback_output or has_unaligned_input or (not tensor_is_aligned(output)):
                V.graph.unaligned_buffers.add(buf.name)
            return buf
        elif isinstance(output, int):
            return output
        elif isinstance(output, torch.SymInt):
            return output.node.expr
        else:
            assert output is None, f'FallbackKernel output type {type(output)} is not supported'
            return None
    outputs = generate_output(example_output, [])
    if isinstance(outputs, (list, tuple)):
        packed.outputs = outputs
    elif isinstance(outputs, dict):
        packed.outputs = tuple(outputs)
    else:
        packed.outputs = [outputs]
    return outputs

def _compile_start() -> None:
