    if client_key:
        args += ['--ssl-key=%s' % client_key]
    if charset:
        args += ['--default-character-set=%s' % charset]
    if database:
        args += [database]
    args.extend(parameters)
    return (args, env)

def __post_init__(self) -> None:
    assert self.view.is_view_op
    if self.view_copy is None:
        assert not gets_generated_view_copy(self.view), f'{str(self.view.func.name)} appears to be a new operator that aliases its inputs. The codegen expects you to add a corresponding operator to native_functions.yaml: {get_view_copy_name(self.view)!s}. See Note [view_copy NativeFunctions] for details.'
    else:
        assert self.view_copy.func.name.name.base.endswith(('_copy', '_scatter'))
        assert self.view.func.signature() == self.view_copy.func.signature(strip_view_copy_name=True)
        assert 'view_copy' in self.view_copy.tags, f"{(str(self.view_copy.func.name), str(self.view.tags))} appears to be a view_copy operator. The codegen expects view_copy operators to be annotated with the 'view_copy' tag in native_functions.yaml. See Note [view_copy NativeFunction] for details."
    if self.view_inplace is not None:
        assert self.view.func.signature() == self.view_inplace.func.signature()
    if self.view.has_composite_implicit_autograd_kernel:
        if self.view_inplace is not None:
            assert self.view_inplace.has_composite_implicit_autograd_kernel, f'{str(self.view.func.name)} and {str(self.view_inplace.func.name)} must either both have CompositeImplicitAutograd kernels, or both not have composite kernels.'
    if <MASK>:
        if self.view_inplace is not None:
            assert self.view_inplace.has_composite_implicit_autograd_nested_tensor_kernel, f'{str(self.view.func.name)} and {str(self.view_inplace.func.name)} must either both have CompositeImplicitAutogradNestedTensor kernels, or both not have composite kernels.'

@register_decomposition([aten.baddbmm])
@out_wrapper(exact_dtype=True)
@pw_cast_for_opmath
def baddbmm(self, batch1, batch2, beta=1, alpha=1):
    if <MASK>:
        beta = int(beta)
        alpha = int(alpha)
    result = torch.bmm(batch1, batch2)
    if not isinstance(alpha, numbers.Number) or alpha != 1:
        result = result * alpha
    if beta == 0:
        return result
    if not isinstance(beta, numbers.Number) or beta != 1:
        self = self * beta
    return self + result

@final
def _call_cython_op(self, values: np.ndarray, *, min_count: int, ngroups: int, comp_ids: np.ndarray, mask: npt.NDArray[np.bool_] | None, result_mask: npt.NDArray[np.bool_] | None, initial: Any=0, **kwargs) -> np.ndarray:
    orig_values = values
    dtype = values.dtype
    is_numeric = dtype.kind in 'iufcb'
    is_datetimelike = dtype.kind in 'mM'
    if self.how in ['any', 'all']:
        if mask is None:
            mask = isna(values)
    if is_datetimelike:
        values = values.view('int64')
        is_numeric = True
    elif dtype.kind == 'b':
        values = values.view('uint8')
    if values.dtype == 'float16':
        values = values.astype(np.float32)
    if self.how in ['any', 'all']:
        if dtype == object:
            if kwargs['skipna']:
                if mask is not None and mask.any():
                    values = values.copy()
                    values[mask] = True
        values = values.astype(bool, copy=False).view(np.int8)
        is_numeric = True
    values = values.T
    if mask is not None:
        mask = mask.T
        if <MASK>:
            result_mask = result_mask.T
    out_shape = self._get_output_shape(ngroups, values)
    func = self._get_cython_function(self.kind, self.how, values.dtype, is_numeric)
    values = self._get_cython_vals(values)
    out_dtype = self._get_out_dtype(values.dtype)
    result = maybe_fill(np.empty(out_shape, dtype=out_dtype))
    if self.kind == 'aggregate':
        counts = np.zeros(ngroups, dtype=np.int64)
        if self.how in ['idxmin', 'idxmax', 'min', 'max', 'mean', 'last', 'first', 'sum', 'median']:
            if self.how == 'sum':
                kwargs['initial'] = initial
            func(out=result, counts=counts, values=values, labels=comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, is_datetimelike=is_datetimelike, **kwargs)
        elif self.how in ['sem', 'std', 'var', 'ohlc', 'prod']:
            if self.how in ['std', 'sem']:
                kwargs['is_datetimelike'] = is_datetimelike
            func(result, counts, values, comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, **kwargs)
        elif self.how in ['any', 'all']:
            func(out=result, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            result = result.astype(bool, copy=False)
        elif self.how in ['skew', 'kurt']:
            func(out=result, counts=counts, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            if dtype == object:
                result = result.astype(object)
        else:
            raise NotImplementedError(f'{self.how} is not implemented')
    else:
        if self.how != 'rank':
            kwargs['result_mask'] = result_mask
        func(out=result, values=values, labels=comp_ids, ngroups=ngroups, is_datetimelike=is_datetimelike, mask=mask, **kwargs)
    if self.kind == 'aggregate' and self.how not in ['idxmin', 'idxmax']:
        if result.dtype.kind in 'iu' and (not is_datetimelike):
            cutoff = max(0 if self.how in ['sum', 'prod'] else 1, min_count)
            empty_groups = counts < cutoff
            if empty_groups.any():
                if result_mask is not None:
                    assert result_mask[empty_groups].all()
                else:
                    result = result.astype('float64')
                    result[empty_groups] = np.nan
    result = result.T
    if self.how not in self.cast_blocklist:
        res_dtype = self._get_result_dtype(orig_values.dtype)
        op_result = maybe_downcast_to_dtype(result, res_dtype)
    else:
        op_result = result
    return op_result

@classmethod
def create_out_of_place(cls, kernel: _OpOverloads, inputs: Union[TensorBox, list[TensorBox]], *args: Any, **kwargs: Any) -> Union[list[MultiOutput], _CollectiveKernel]:
    with V.graph.fake_mode:
        (example_output, tensor_args, non_tensor_args, unflatten_args, unbacked_bindings) = cls.process_kernel(kernel, inputs, *args, **kwargs)
    assert not unbacked_bindings, f'{kernel}, {unbacked_bindings}'
    for tensor_arg in tensor_args:
        tensor_arg.realize()
    if isinstance(example_output, list):
        device = cls.find_device(tensor_args, example_output)
        assert device is not None
        packed = cls(MultiOutputLayout(device=device), kernel, tensor_args, non_tensor_args, unflatten_args)
        packed.outputs = [MultiOutput(cls.tensor_to_layout(tensor), packed, [(list, i)]) for (i, tensor) in enumerate(example_output)]
        for (buf, tensor) in zip(packed.outputs, example_output):
            if config.assume_unaligned_fallback_output or not tensor_is_aligned(tensor):
                V.graph.unaligned_buffers.add(buf.name)
        return packed.outputs
    else:
        packed = cls(cls.tensor_to_layout(example_output), kernel, tensor_args, non_tensor_args, unflatten_args)
        if <MASK>:
            V.graph.unaligned_buffers.add(packed.name)
        packed.outputs = [packed]
        return packed

@contextlib.contextmanager
def _set_node_metadata_hook(gm: torch.fx.GraphModule, f):
    """
    Takes a callable which will be called after we create a new node. The
    callable takes the newly created node as input and returns None.
    """
    assert callable(f), 'node_metadata_hook must be a callable.'
    for m in gm.modules():
        if <MASK>:
            m._register_create_node_hook(f)
    try:
        yield
    finally:
        for m in gm.modules():
            if isinstance(m, GraphModule):
                m._unregister_create_node_hook(f)

@tf_export.tf_export('experimental.numpy.var', v1=[])
@np_utils.np_doc('var')
def var(a, axis=None, dtype=None, out=None, ddof=0, keepdims=None):
    if <MASK>:
        working_dtype = np_utils.result_type(a, dtype)
    else:
        working_dtype = None
    if out is not None:
        raise ValueError('Setting out is not supported.')
    if ddof != 0:

        def reduce_fn(input_tensor, axis, keepdims):
            means = math_ops.reduce_mean(input_tensor, axis=axis, keepdims=True)
            centered = input_tensor - means
            if input_tensor.dtype in (dtypes.complex64, dtypes.complex128):
                centered = math_ops.cast(math_ops.real(centered * math_ops.conj(centered)), input_tensor.dtype)
            else:
                centered = math_ops.square(centered)
            squared_deviations = math_ops.reduce_sum(centered, axis=axis, keepdims=keepdims)
            if axis is None:
                n = array_ops.size(input_tensor)
            else:
                if axis < 0:
                    axis += array_ops.rank(input_tensor)
                n = math_ops.reduce_prod(array_ops.gather(array_ops.shape(input_tensor), axis))
            n = math_ops.cast(n - ddof, input_tensor.dtype)
            return math_ops.cast(math_ops.divide(squared_deviations, n), dtype)
    else:
        reduce_fn = math_ops.reduce_variance
    result = _reduce(reduce_fn, a, axis=axis, dtype=working_dtype, keepdims=keepdims, promote_int=_TO_FLOAT)
    if dtype:
        result = math_ops.cast(result, dtype)
    return result

@final
def _get_arithmetic_result_freq(self, other) -> BaseOffset | None:
    """
        Check if we can preserve self.freq in addition or subtraction.
        """
    if isinstance(self.dtype, PeriodDtype):
        return self.freq
    elif not lib.is_scalar(other):
        return None
    elif isinstance(self.freq, Tick):
        return self.freq
    elif self.dtype.kind == 'm' and isinstance(other, Timedelta):
        return self.freq
    elif self.dtype.kind == 'm' and isinstance(other, Timestamp) and (other.tz is None or timezones.is_utc(other.tz)):
        return self.freq
    elif lib.is_np_dtype(self.dtype, 'M') and isinstance(self.freq, Day) and isinstance(other, Timedelta):
        return self.freq
    elif <MASK>:
        return self.freq
    return None

def unscale_(self, optimizer: torch.optim.Optimizer) -> None:
    if not self._enabled:
        return
    self._check_scale_growth_tracker('unscale_')
    optimizer_state = self._per_optimizer_states[id(optimizer)]
    if optimizer_state['stage'] is OptState.UNSCALED:
        raise RuntimeError('unscale_() has already been called on this optimizer since the last update().')
    elif <MASK>:
        raise RuntimeError('unscale_() is being called after step().')
    if self._scale is None:
        raise AssertionError('Expected _scale to be initialized, got None')
    inv_scale = self._scale.double().reciprocal().float()
    found_inf = torch.full((1,), 0.0, dtype=torch.float32, device=self._scale.device)
    optimizer_state['found_inf_per_device'] = self._unscale_grads_(optimizer, inv_scale, found_inf, True)
    optimizer_state['stage'] = OptState.UNSCALED
    optimizer_state = self._per_optimizer_states[id(optimizer)]
    works = []
    found_inf_on_cpus = []
    found_inf_on_devices = []
    for found_inf in optimizer_state['found_inf_per_device'].values():
        if self._device != 'cpu' and found_inf.device.type == 'cpu':
            found_inf_on_cpus.append(found_inf)
            found_inf_on_device = found_inf.to(self._device)
            found_inf_on_devices.append(found_inf_on_device)
            works.append(dist.all_reduce(found_inf_on_device, async_op=True, group=self.process_group))
        else:
            works.append(dist.all_reduce(found_inf, async_op=True, group=self.process_group))
    for work in works:
        work.wait()
    if found_inf_on_cpus:
        torch._foreach_copy_(found_inf_on_cpus, found_inf_on_devices)

