def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if ann is None:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if is_dict(ann):
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if value is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if ann is str:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if ann is Any:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if <MASK>:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if maybe_script_class is not None:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

def _einsum_v2_parse_and_resolve_equation(equation, input_shapes):
    """Helper which validates einsum equation and resolves input shapes."""
    resolved_equation = equation.replace(' ', '')
    ellipsis_label = None
    if '...' in equation:
        ellipsis_label = '0'
        if ellipsis_label in resolved_equation:
            raise ValueError(f'Invalid character "{ellipsis_label}" in equation: {equation}.')
        resolved_equation = resolved_equation.replace('...', ellipsis_label)
    allowed_labels = 'a-zA-Z'
    if ellipsis_label:
        allowed_labels += ellipsis_label
    match = re.match('^([{0},]*)(->[{0}]*)?$'.format(allowed_labels), resolved_equation)
    if not match:
        raise ValueError('Subscripts have incorrect format: {}'.format(resolved_equation))
    input_labels = match.group(1).split(',')
    output_labels = match.group(2)[2:] if match.group(2) else None
    if len(input_shapes) != len(input_labels):
        raise ValueError('Got {} inputs for equation "{}", expecting {}'.format(len(input_shapes), equation, len(input_labels)))
    if '->' not in resolved_equation:
        label_counts = collections.Counter(match.group(1))
        output_labels = ''.join([x for x in sorted(list(label_counts)) if x != ',' and label_counts[x] == 1])
        resolved_equation += '->' + output_labels
    if output_labels and len(set(output_labels)) != len(output_labels):
        raise ValueError('Output subscripts contain a label appearing more than once: {}'.format(equation))
    input_label_set = set(match.group(1))
    for label in output_labels:
        if label != ellipsis_label and label not in input_label_set:
            raise ValueError('Output subscripts contain the label {} not present in the input subscripts.'.format(label))
    if ellipsis_label and output_labels:
        num_output_ellipses = output_labels.count(ellipsis_label)
        if num_output_ellipses > 1:
            raise ValueError('Output subscripts contain multiple ellipsis: {}'.format(equation))
    if len(input_shapes) <= 2:
        return (resolved_equation, None, ellipsis_label)
    label_to_dim = collections.defaultdict(lambda : 1)
    for (i, (labels, shape)) in enumerate(zip(input_labels, input_shapes)):
        if shape is None:
            continue
        ellipsis_start = labels.find(ellipsis_label) if ellipsis_label else -1
        if ellipsis_start != -1:
            if ellipsis_start != labels.rfind(ellipsis_label):
                raise ValueError(f"Too many ellipses in input label {labels.replace(ellipsis_label, '...')}.")
            if <MASK>:
                raise ValueError('Too many named labels in {}th subscript string of equation {} for input shape {} '.format(i, equation, shape))
            ellipsis_end = ellipsis_start + len(shape) + 1 - len(labels)
            shape[ellipsis_start:ellipsis_end] = [np.prod(list(filter(None, shape[ellipsis_start:ellipsis_end])), dtype=np.int64)]
        elif len(labels) != len(shape):
            raise ValueError('Number of named labels in input #{} of equation {} must be equal to the number of dimensions in shape {}'.format(i, equation, shape))
        for (dim, label) in zip(shape, labels):
            if dim is not None:
                label_to_dim[label] = max(label_to_dim[label], dim)
    resolved_shapes = []
    for labels in input_labels:
        resolved_shapes.append([label_to_dim[label] for label in labels])
    return (resolved_equation, resolved_shapes, ellipsis_label)

def deserialize_metadata(self, metadata: dict[str, str]) -> dict[str, Any]:
    ret: dict[str, Any] = {}
    if (stack_trace := metadata.get('stack_trace')):
        ret['stack_trace'] = stack_trace

    def deserialize_meta_func(serialized_target: str):
        module = None
        if serialized_target.startswith('torch.nn'):
            module = torch.nn
            serialized_target_names = serialized_target.split('.')[2:]
        elif serialized_target.startswith('torch'):
            module = torch
            serialized_target_names = serialized_target.split('.')[1:]
        else:
            return self.deserialize_operator(serialized_target)
        target = module
        for name in serialized_target_names:
            if not hasattr(target, name):
                return serialized_target
            else:
                target = getattr(target, name)
        return target
    if (nn_module_stack_str := metadata.get('nn_module_stack')):

        def import_nn_module_stack(key, path, ty):
            return (key, (path, ty))

        def metadata_split(metadata):
            out = []
            (start, n) = (0, 0)
            (a, b) = ('[(', ')]')
            for (end, c) in enumerate(metadata):
                if c in a:
                    n += 1
                elif c in b:
                    n -= 1
                elif c == ',' and n == 0:
                    out.append(metadata[start:end])
                    start = end + 1
            out.append(metadata[start:])
            assert len(out) == 3
            return out
        nn_module_stack = dict((import_nn_module_stack(*metadata_split(item)) for item in nn_module_stack_str.split(ST_DELIMITER)))
        ret['nn_module_stack'] = nn_module_stack
    if (source_fn_st_str := metadata.get('source_fn_stack')):
        source_fn_st = []
        for source_fn_str in source_fn_st_str.split(ST_DELIMITER):
            (name, target_str) = source_fn_str.split(',')
            source_fn_st.append((name, deserialize_meta_func(target_str)))
        ret['source_fn_stack'] = source_fn_st
    if <MASK>:
        ret['torch_fn'] = tuple(torch_fn_str.split(ST_DELIMITER))
    if (custom_str := metadata.get('custom')):
        ret['custom'] = json.loads(custom_str)
    return ret

def _get_cpu_exclude_function(self, method: str='bmm') -> Callable[[sympy.Integer, sympy.Integer, sympy.Integer], bool]:
    """
        Get CPU-specific exclude function based on method type.
        Returns a function that can be used as exclude condition.
        Moved from mm_common._is_large_block_for_cpu and refactored to return a function.
        """
    if method in 'conv':

        def exclude_conv(m: sympy.Integer, n: sympy.Integer, k: sympy.Integer) -> bool:
            if <MASK>:
                return True
            return m * n * k > 2 ** 17
        return exclude_conv
    elif method in ('mm', 'addmm', 'int_mm'):

        def exclude_mm(m: sympy.Integer, n: sympy.Integer, k: sympy.Integer) -> bool:
            return m * n > 2 ** 13
        return exclude_mm
    else:

        def exclude_bmm(m: sympy.Integer, n: sympy.Integer, k: sympy.Integer) -> bool:
            if m > 128 or n > 128 or k > 128:
                return True
            return m * n > 2 ** 12
        return exclude_bmm

def _get_enclosing_except_scopes(self, stop_at):
    included = []
    for node in reversed(self.lexical_scopes):
        if <MASK>:
            included.extend(node.handlers)
        if isinstance(node, stop_at):
            break
    return included

def _get_all_later_node_usages(tensor_aliases: set[Node], op_index: int):

    def _add_if_tensor(x, set_):
        if isinstance(x, FakeTensor):
            set_.add(StorageWeakRef(x._typed_storage()))
    nodes_used_after = set()
    for t in tensor_aliases:
        usage_nodes = t.users
        for n in usage_nodes:
            if <MASK>:
                continue
            if n in tensor_aliases:
                if isinstance(n.target, torch._ops.OpOverload) or n.target == _operator.getitem:
                    continue
            nodes_used_after.add(n)
    return nodes_used_after

def _invoke_rpc(rref, rpc_api, func_name, timeout, *args, **kwargs):

    def _rref_type_cont(rref_fut):
        rref_type = rref_fut.value()
        _invoke_func = _local_invoke
        bypass_type = issubclass(rref_type, torch.jit.ScriptModule) or issubclass(rref_type, torch._C.ScriptModule)
        if not bypass_type:
            func = getattr(rref_type, func_name)
            if <MASK>:
                _invoke_func = _local_invoke_async_execution
        return rpc_api(rref.owner(), _invoke_func, args=(rref, func_name, args, kwargs), timeout=timeout)
    rref_fut = rref._get_type(timeout=timeout, blocking=False)
    if rpc_api != rpc_async:
        rref_fut.wait()
        return _rref_type_cont(rref_fut)
    else:
        result: Future = Future()

        def _wrap_rref_type_cont(fut):
            try:
                _rref_type_cont(fut).then(_complete_op)
            except BaseException as ex:
                result.set_exception(ex)

        def _complete_op(fut):
            try:
                result.set_result(fut.value())
            except BaseException as ex:
                result.set_exception(ex)
        rref_fut.then(_wrap_rref_type_cont)
        return result

def _laplacian_sparse_flo(graph, normed, axis, copy, form, dtype, symmetrized):
    del copy
    if dtype is None:
        dtype = graph.dtype
    graph_sum = np.asarray(graph.sum(axis=axis)).ravel()
    graph_diagonal = graph.diagonal()
    diag = graph_sum - graph_diagonal
    if symmetrized:
        graph_sum += np.asarray(graph.sum(axis=1 - axis)).ravel()
        diag = graph_sum - graph_diagonal - graph_diagonal
    if normed:
        isolated_node_mask = diag == 0
        w = np.where(isolated_node_mask, 1, np.sqrt(diag))
        if symmetrized:
            md = _laplace_normed_sym(graph, graph_sum, 1.0 / w)
        else:
            md = _laplace_normed(graph, graph_sum, 1.0 / w)
        if <MASK>:
            return (md, w.astype(dtype, copy=False))
        elif form == 'lo':
            m = _linearoperator(md, shape=graph.shape, dtype=dtype)
            return (m, w.astype(dtype, copy=False))
        else:
            raise ValueError(f'Invalid form: {form!r}')
    else:
        if symmetrized:
            md = _laplace_sym(graph, graph_sum)
        else:
            md = _laplace(graph, graph_sum)
        if form == 'function':
            return (md, diag.astype(dtype, copy=False))
        elif form == 'lo':
            m = _linearoperator(md, shape=graph.shape, dtype=dtype)
            return (m, diag.astype(dtype, copy=False))
        else:
            raise ValueError(f'Invalid form: {form!r}')

def _run_sympy_handler(analysis, args, expr, index_dtype=torch.int64):
    if isinstance(expr, sympy.Pow) and isinstance(expr.args[1], sympy.core.numbers.Half):
        return analysis.sqrt(args[0])
    if isinstance(expr, ToFloat):
        return analysis.to_dtype(args[0], torch.float64)
    INDEX_DTYPE_HANDLERS = {TruncToInt: 'trunc_to_int', sympy.floor: 'floor_to_int', sympy.ceiling: 'ceil_to_int', FloorToInt: 'floor_to_int', CeilToInt: 'ceil_to_int', RoundToInt: 'round_to_int'}
    if (handler_name := INDEX_DTYPE_HANDLERS.get(expr.func)) is not None:
        return getattr(analysis, handler_name)(*args, index_dtype)
    if expr.func is sympy.Add and expr.is_integer and hasattr(analysis, 'sym_sum'):
        r = analysis.sym_sum(args)
        log.debug('sym_sum(%s) -> %s', args, r)
        return r
    if hasattr(expr.func, '_torch_handler_name'):
        handler_name = expr.func._torch_handler_name
    else:
        handler_name = handlers()[expr.func]
    handler = getattr(analysis, handler_name)
    try:
        if <MASK>:
            if len(args) <= 1:
                raise AssertionError('associative op needs >1 args')
            acc = handler(args[0], args[1])
            for i in range(2, len(args)):
                acc = handler(acc, args[i])
            log.debug('%s(%s) -> %s', handler_name, args, acc)
            return acc
        else:
            r = handler(*args)
            log.debug('%s(%s) -> %s', handler_name, args, r)
            return r
    except NotImplementedError:
        raise
    except Exception:
        log.warning('failed while executing %s(%s)', handler_name, args)
        raise

def _validate_left_right_on(self, left_on, right_on):
    (left_on, right_on) = super()._validate_left_right_on(left_on, right_on)
    if len(left_on) != 1 and (not self.left_index):
        raise MergeError('can only asof on a key for left')
    if len(right_on) != 1 and (not self.right_index):
        raise MergeError('can only asof on a key for right')
    if self.left_index and isinstance(self.left.index, MultiIndex):
        raise MergeError('left can only have one index')
    if self.right_index and isinstance(self.right.index, MultiIndex):
        raise MergeError('right can only have one index')
    if self.by is not None:
        if self.left_by is not None or self.right_by is not None:
            raise MergeError('Can only pass by OR left_by and right_by')
        self.left_by = self.right_by = self.by
    if self.left_by is None and self.right_by is not None:
        raise MergeError('missing left_by')
    if self.left_by is not None and self.right_by is None:
        raise MergeError('missing right_by')
    if not self.left_index:
        left_on_0 = left_on[0]
        if isinstance(left_on_0, _known):
            lo_dtype = left_on_0.dtype
        else:
            lo_dtype = self.left._get_label_or_level_values(left_on_0).dtype if left_on_0 in self.left.columns else self.left.index.get_level_values(left_on_0)
    else:
        lo_dtype = self.left.index.dtype
    if not self.right_index:
        right_on_0 = right_on[0]
        if isinstance(right_on_0, _known):
            ro_dtype = right_on_0.dtype
        else:
            ro_dtype = self.right._get_label_or_level_values(right_on_0).dtype if right_on_0 in self.right.columns else self.right.index.get_level_values(right_on_0)
    else:
        ro_dtype = self.right.index.dtype
    if is_object_dtype(lo_dtype) or is_object_dtype(ro_dtype) or is_string_dtype(lo_dtype) or is_string_dtype(ro_dtype):
        raise MergeError(f'Incompatible merge dtype, {lo_dtype!r} and {ro_dtype!r}, both sides must have numeric dtype')
    if <MASK>:
        if not is_list_like(self.left_by):
            self.left_by = [self.left_by]
        if not is_list_like(self.right_by):
            self.right_by = [self.right_by]
        if len(self.left_by) != len(self.right_by):
            raise MergeError('left_by and right_by must be the same length')
        left_on = self.left_by + list(left_on)
        right_on = self.right_by + list(right_on)
    return (left_on, right_on)

@bottleneck_switch()
def nanmedian(values: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, mask=None) -> float | np.ndarray:
    """
    Parameters
    ----------
    values : ndarray
    axis : int, optional
    skipna : bool, default True
    mask : ndarray[bool], optional
        nan-mask if known

    Returns
    -------
    result : float | ndarray
        Unless input is a float array, in which case use the same
        precision as the input array.

    Examples
    --------
    >>> from pandas.core import nanops
    >>> s = pd.Series([1, np.nan, 2, 2])
    >>> nanops.nanmedian(s.values)
    2.0

    >>> s = pd.Series([np.nan, np.nan, np.nan])
    >>> nanops.nanmedian(s.values)
    nan
    """
    using_nan_sentinel = values.dtype.kind == 'f' and mask is None

    def get_median(x: np.ndarray, _mask=None):
        if _mask is None:
            _mask = notna(x)
        else:
            _mask = ~_mask
        if not skipna and (not _mask.all()):
            return np.nan
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
            warnings.filterwarnings('ignore', 'Mean of empty slice', RuntimeWarning)
            res = np.nanmedian(x[_mask])
        return res
    dtype = values.dtype
    (values, mask) = _get_values(values, skipna, mask=mask, fill_value=None)
    if values.dtype.kind != 'f':
        if <MASK>:
            inferred = lib.infer_dtype(values)
            if inferred in ['string', 'mixed']:
                raise TypeError(f'Cannot convert {values} to numeric')
        try:
            values = values.astype('f8')
        except ValueError as err:
            raise TypeError(str(err)) from err
    if not using_nan_sentinel and mask is not None:
        if not values.flags.writeable:
            values = values.copy()
        values[mask] = np.nan
    notempty = values.size
    res: float | np.ndarray
    if values.ndim > 1 and axis is not None:
        if notempty:
            if not skipna:
                res = np.apply_along_axis(get_median, axis, values)
            else:
                with warnings.catch_warnings():
                    warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
                    if values.shape[1] == 1 and axis == 0 or (values.shape[0] == 1 and axis == 1):
                        res = np.nanmedian(np.squeeze(values), keepdims=True)
                    else:
                        res = np.nanmedian(values, axis=axis)
        else:
            res = _get_empty_reduction_result(values.shape, axis)
    else:
        res = get_median(values, mask) if notempty else np.nan
    return _wrap_results(res, dtype)

def persistent_id(obj: Any) -> Optional[tuple]:
    if isinstance(obj, type) and issubclass(obj, nn.Module):
        if obj in serialized_container_types:
            return None
        serialized_container_types[obj] = True
        source_file = source = None
        try:
            (source_lines, _, source_file) = get_source_lines_and_file(obj)
            source = ''.join(source_lines)
        except Exception:
            warnings.warn("Couldn't retrieve source code for container of type " + obj.__name__ + ". It won't be checked for correctness upon loading.")
        return ('module', obj, source_file, source)
    if isinstance(obj, torch.storage.TypedStorage) or torch.is_storage(obj):
        storage: torch.UntypedStorage
        if isinstance(obj, torch.storage.TypedStorage):
            storage = obj._untyped_storage
            storage_dtype = obj.dtype
            storage_type_str = obj._pickle_storage_type()
            storage_type = getattr(torch, storage_type_str)
            dtype = obj.dtype
            storage_numel = obj._size()
        elif isinstance(obj, torch.UntypedStorage):
            storage = obj
            storage_dtype = torch.uint8
            storage_type = normalize_storage_type(type(obj))
            dtype = torch.uint8
            storage_numel = storage.nbytes()
        else:
            raise TypeError(f'type not recognized: {type(obj)}')
        if storage.data_ptr() != 0:
            if storage.data_ptr() in storage_dtypes:
                if storage_dtype != storage_dtypes[storage.data_ptr()]:
                    raise RuntimeError('Cannot save multiple tensors or storages that view the same data as different types')
            else:
                storage_dtypes[storage.data_ptr()] = storage_dtype
        view_metadata: Optional[tuple[str, int, int]]
        offset = 0
        storage_key = str(storage._cdata)
        location = location_tag(storage)
        if storage_key not in serialized_storages:
            serialized_storages[storage_key] = (storage, dtype)
        is_view = storage._cdata != storage._cdata
        if <MASK>:
            view_metadata = (str(storage._cdata), offset, storage.nbytes())
        else:
            view_metadata = None
        res = ('storage', storage_type, storage_key, location, storage_numel, view_metadata)
        return res
    return None

def helper(treespec: PyTreeSpec, node: PyTree, subtrees: list[PyTree]) -> None:
    if treespec.is_leaf():
        subtrees.append(node)
        return
    node_type = type(node)
    if treespec.type not in BUILTIN_TYPES:
        if <MASK>:
            raise ValueError(f'Type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        (children, metadata, *_) = optree.tree_flatten_one_level(node, none_is_leaf=self.none_is_leaf, namespace=self.namespace)
        if len(children) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(children)}.')
        if metadata != treespec._metadata:
            raise ValueError(f'Node context mismatch for custom node type {treespec.type!r}.')
    else:
        both_standard_dict = treespec.type in STANDARD_DICT_TYPES and node_type in STANDARD_DICT_TYPES
        if not both_standard_dict and node_type != treespec.type:
            raise ValueError(f'Node type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        if len(node) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(node)}.')
        if both_standard_dict:
            expected_keys = treespec.entries()
            got_key_set = set(node)
            expected_key_set = set(expected_keys)
            if got_key_set != expected_key_set:
                missing_keys = expected_key_set.difference(got_key_set)
                extra_keys = got_key_set.difference(expected_key_set)
                message = ''
                if missing_keys:
                    message += f'; missing key(s): {missing_keys}'
                if extra_keys:
                    message += f'; extra key(s): {extra_keys}'
                raise ValueError(f'Node keys mismatch{message}.')
            children = [node[key] for key in expected_keys]
        else:
            (children, metadata, *_) = optree.tree_flatten_one_level(node, none_is_leaf=self.none_is_leaf, namespace=self.namespace)
            if node_type is not deque and metadata != treespec._metadata:
                raise ValueError(f'Node metadata mismatch for node type {treespec.type!r}; expected {treespec._metadata!r}, but got {metadata!r}.')
    for (subtree, subspec) in zip(children, treespec._children):
        helper(subspec, subtree, subtrees)

@tf_export.tf_export('experimental.numpy.compress', v1=[])
@np_utils.np_doc('compress')
def compress(condition, a, axis=None):
    condition = asarray(condition, dtype=bool)
    a = asarray(a)
    if <MASK>:
        raise ValueError('condition must be a 1-d array.')
    if a.ndim == 0:
        a = ravel(a)
    if axis is None:
        a = ravel(a)
        axis = 0
    if axis < 0:
        axis += a.ndim
    assert axis >= 0 and axis < a.ndim
    condition_t = condition
    a_t = a
    if condition.shape[0] < a.shape[axis]:
        padding = array_ops.fill([a.shape[axis] - condition.shape[0]], False)
        condition_t = array_ops.concat([condition_t, padding], axis=0)
    return array_ops.boolean_mask(tensor=a_t, mask=condition_t, axis=axis)

def key_averages(self, group_by_input_shape=False, group_by_stack_n=0):
    self._check_finish()
    if <MASK>:
        raise AssertionError('Expected profiling results')
    return self.function_events.key_averages(group_by_input_shape, group_by_stack_n)

@register_jagged_func(torch.ops.aten.matmul_backward.default, 'grad: any, self: any, other: any, mask: any')
def matmul_backward_default(func, *args, **kwargs):
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    grad = new_kwargs.pop('grad')
    inp = new_kwargs.pop('input')
    other = new_kwargs.pop('other')
    grad_input_mask = new_kwargs.pop('mask')
    if grad is None:
        return (None, None)
    grad_self = None
    if grad_input_mask[0]:
        grad_self = torch.matmul(grad, other.transpose(-1, -2))
    grad_other = None
    if <MASK>:
        grad_other = torch.matmul(inp.transpose(-1, -2), grad)
    return (grad_self, grad_other)

def run_impl(self, use_fuser):
    warmups = 10
    if self.device == 'cuda':
        iters = 1000
    else:
        iters = 10
    engine = tensor_engine.get_engine()
    self.bm_jit = None
    for i in range(warmups + iters):
        if <MASK>:
            if self.device == 'cuda':
                engine.sync_cuda()
            time_start = time.time()
        if i == 0:
            if self.jit_mode == 'trace' and use_fuser:
                self.bm_jit = torch.jit.trace(self.forward, example_inputs=self.inputs, check_trace=False)
            if callable(getattr(self, 'reference', None)):
                self.check()
            else:
                print('Warning: no reference result for ', self.module())
        elif i == 1:
            if self.jit_mode == 'trace' and use_fuser and self.print_ir:
                print(self.bm_jit.graph_for(*self.inputs))
        z = self.compute()
        if self.mode == 'both':
            if self.result_grad is None:
                self.result_grad = engine.rand_like(z)
            engine.backward([z], [self.result_grad], self.grad_variables)
    if self.device == 'cuda':
        engine.sync_cuda()
    duration = time.time() - time_start
    iter_time = duration / iters
    memory_workload = self.memory_workload()
    compute_workload = self.compute_workload()
    result_dict = {'desc': self.desc(), 'us': iter_time * 1000000.0, 'sol': memory_workload['sol'] * self.dtype_to_bytes() / iter_time / 1000000000.0, 'algorithmic': memory_workload['algorithmic'] * self.dtype_to_bytes() / iter_time / 1000000000.0}
    if compute_workload:
        result_dict['compute_workload'] = compute_workload / iter_time / 1000000000.0
    self.dump_result(result_dict)

def is_superperiod(source, target) -> bool:
    """
    Returns True if upsampling is possible between source and target
    frequencies

    Parameters
    ----------
    source : str or DateOffset
        Frequency converting from
    target : str or DateOffset
        Frequency converting to

    Returns
    -------
    bool
    """
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)
    if _is_annual(source):
        if _is_annual(target):
            return get_rule_month(source) == get_rule_month(target)
        if _is_quarterly(target):
            smonth = get_rule_month(source)
            tmonth = get_rule_month(target)
            return _quarter_months_conform(smonth, tmonth)
        return target in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_quarterly(source):
        return target in {'D', 'C', 'B', 'M', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_monthly(source):
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif _is_weekly(source):
        return target in {source, 'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'B':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'C':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'D':
        return target in {'D', 'C', 'B', 'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'h':
        return target in {'h', 'min', 's', 'ms', 'us', 'ns'}
    elif source == 'min':
        return target in {'min', 's', 'ms', 'us', 'ns'}
    elif source == 's':
        return target in {'s', 'ms', 'us', 'ns'}
    elif <MASK>:
        return target in {'ms', 'us', 'ns'}
    elif source == 'us':
        return target in {'us', 'ns'}
    elif source == 'ns':
        return target in {'ns'}
    else:
        return False

@combinations.generate(strategy_and_run_tf_function_combinations())
def testAssignOnReadVar(self, distribution, experimental_run_tf_function):
    with distribution.scope():
        v_to_assign = variable_v1.VariableV1(2.0, aggregation=variables_lib.VariableAggregation.MEAN)
        v_to_assign_sub = variable_v1.VariableV1(-2.0, aggregation=variables_lib.VariableAggregation.MEAN)

    def assign(fn, v, update_value, cross_replica):
        update_fn = lambda : getattr(v, fn)(update_value)
        if <MASK>:
            return update_fn()
        else:
            if experimental_run_tf_function:
                update_fn = def_function.function(update_fn)
            return test_util.gather(distribution, distribution.run(update_fn))
    updates = [('assign', v_to_assign), ('assign_add', v_to_assign), ('assign_sub', v_to_assign_sub)]
    expected_cross_replica = {variables_lib.VariableAggregation.SUM: 1.0, variables_lib.VariableAggregation.MEAN: 2.0, variables_lib.VariableAggregation.ONLY_FIRST_REPLICA: 2.0}
    expected_replica = {variables_lib.VariableAggregation.SUM: 2.0, variables_lib.VariableAggregation.MEAN: 2.0, variables_lib.VariableAggregation.ONLY_FIRST_REPLICA: 2.0}
    aggregations = [variables_lib.VariableAggregation.SUM, variables_lib.VariableAggregation.MEAN, variables_lib.VariableAggregation.ONLY_FIRST_REPLICA]
    options = list((x for x in itertools.product(updates, aggregations, [True, False])))
    for (update, aggregation, cross_replica) in options:
        if aggregation == variables_lib.VariableAggregation.SUM:
            continue
        with distribution.scope():
            v = variable_v1.VariableV1(0.0, aggregation=aggregation)
        self.evaluate(variables_lib.global_variables_initializer())
        (fn, update_value) = update
        self.evaluate(assign(fn, v, update_value, cross_replica))
        if cross_replica:
            for component in v._values:
                self.assertAllEqual(expected_cross_replica.get(aggregation), self.evaluate(component.read_value()))
        else:
            for component in v._values:
                self.assertAllEqual(expected_replica.get(aggregation), self.evaluate(component.read_value()))

def delete(self):
    for (model, instances) in self.data.items():
        self.data[model] = sorted(instances, key=attrgetter('pk'))
    self.sort()
    deleted_counter = Counter()
    if len(self.data) == 1 and len(instances) == 1:
        instance = list(instances)[0]
        if self.can_fast_delete(instance):
            with transaction.mark_for_rollback_on_error(self.using):
                count = sql.DeleteQuery(model).delete_batch([instance.pk], self.using)
            setattr(instance, model._meta.pk.attname, None)
            return (count, {model._meta.label: count})
    with transaction.atomic(using=self.using, savepoint=False):
        for (model, obj) in self.instances_with_model():
            if <MASK>:
                signals.pre_delete.send(sender=model, instance=obj, using=self.using, origin=self.origin)
        for qs in self.fast_deletes:
            count = qs._raw_delete(using=self.using)
            if count:
                deleted_counter[qs.model._meta.label] += count
        for ((field, value), instances_list) in self.field_updates.items():
            updates = []
            objs = []
            for instances in instances_list:
                if isinstance(instances, models.QuerySet) and instances._result_cache is None:
                    updates.append(instances)
                else:
                    objs.extend(instances)
            if updates:
                combined_updates = reduce(or_, updates)
                combined_updates.update(**{field.name: value})
            if objs:
                model = objs[0].__class__
                query = sql.UpdateQuery(model)
                query.update_batch(list({obj.pk for obj in objs}), {field.name: value}, self.using)
        for instances in self.data.values():
            instances.reverse()
        for (model, instances) in self.data.items():
            query = sql.DeleteQuery(model)
            pk_list = [obj.pk for obj in instances]
            count = query.delete_batch(pk_list, self.using)
            if count:
                deleted_counter[model._meta.label] += count
            if not model._meta.auto_created:
                for obj in instances:
                    signals.post_delete.send(sender=model, instance=obj, using=self.using, origin=self.origin)
    for (model, instances) in self.data.items():
        for instance in instances:
            setattr(instance, model._meta.pk.attname, None)
    return (sum(deleted_counter.values()), dict(deleted_counter))

def rename_axis(model: ir.Model, rename_mapping: dict[str, str]) -> None:
    """Rename dynamic axes in a model according to the specified dynamic_axes names."""
    sorted_rename_mapping = dict(sorted(rename_mapping.items(), key=lambda item: len(item[0]), reverse=True))
    for value in _all_values(model):
        if value.shape is None:
            continue
        new_shape = []
        changed = False
        for dim in value.shape:
            if not isinstance(dim, ir.SymbolicDim):
                new_shape.append(dim)
                continue
            dim_name = dim.value
            if dim_name in sorted_rename_mapping:
                new_shape.append(sorted_rename_mapping[dim_name])
                changed = True
            elif dim_name is not None:
                new_name = _replace_names(dim_name, sorted_rename_mapping)
                new_shape.append(new_name)
                if <MASK>:
                    changed = True
            else:
                new_shape.append(None)
        if changed:
            value.shape = ir.Shape(new_shape)

def _write_data(input_files_data: dict[str, _InputFileData], output_files_data: dict[str, _OutputFileData], num_threads: int=1) -> None:
    """
    Write tensor data from input files to the output files using memory mapping.

    This function reads tensor data from each input file and writes it to the appropriate
    position in the output files based on the tensor's offsets. When num_threads > 1,
    the work is split across threads with each thread handling a different output file.

    Args:
        input_files_data: Dictionary mapping input file paths to their metadata
        output_files_data: Dictionary mapping output file paths to their metadata
        num_threads: Number of threads to use for parallel processing
    """
    if <MASK>:
        for (output_file, output_data) in output_files_data.items():
            _process_output_file(output_file, output_data, input_files_data)
    else:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(num_threads, len(output_files_data))) as executor:
            futures = []
            for (output_file, output_data) in output_files_data.items():
                futures.append(executor.submit(_process_output_file, output_file, output_data, input_files_data))
            for future in concurrent.futures.as_completed(futures):
                try:
                    future.result()
                except Exception as e:
                    print(f'Error processing output file: {e}')
                    raise

@final
@_maybe_return_indexers
def join(self, other: Index, *, how: JoinHow='left', level: Level | None=None, return_indexers: bool=False, sort: bool=False) -> Index | tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    """
        Compute join_index and indexers to conform data structures to the new index.

        Parameters
        ----------
        other : Index
            The other index on which join is performed.
        how : {'left', 'right', 'inner', 'outer'}
        level : int or level name, default None
            It is either the integer position or the name of the level.
        return_indexers : bool, default False
            Whether to return the indexers or not for both the index objects.
        sort : bool, default False
            Sort the join keys lexicographically in the result Index. If False,
            the order of the join keys depends on the join type (how keyword).

        Returns
        -------
        join_index, (left_indexer, right_indexer)
            The new index.

        See Also
        --------
        DataFrame.join : Join columns with `other` DataFrame either on index
            or on a key.
        DataFrame.merge : Merge DataFrame or named Series objects with a
            database-style join.

        Examples
        --------
        >>> idx1 = pd.Index([1, 2, 3])
        >>> idx2 = pd.Index([4, 5, 6])
        >>> idx1.join(idx2, how="outer")
        Index([1, 2, 3, 4, 5, 6], dtype='int64')
        >>> idx1.join(other=idx2, how="outer", return_indexers=True)
        (Index([1, 2, 3, 4, 5, 6], dtype='int64'),
        array([ 0,  1,  2, -1, -1, -1]), array([-1, -1, -1,  0,  1,  2]))
        """
    other = ensure_index(other)
    sort = sort or how == 'outer'
    if <MASK>:
        if (self.tz is None) ^ (other.tz is None):
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
    if not self._is_multi and (not other._is_multi):
        (pself, pother) = self._maybe_downcast_for_indexing(other)
        if pself is not self or pother is not other:
            return pself.join(pother, how=how, level=level, return_indexers=True, sort=sort)
    if level is None and (self._is_multi or other._is_multi):
        if self.names == other.names:
            pass
        else:
            return self._join_multi(other, how=how)
    if level is not None and (self._is_multi or other._is_multi):
        return self._join_level(other, level, how=how)
    if len(self) == 0 or len(other) == 0:
        try:
            return self._join_empty(other, how, sort)
        except TypeError:
            pass
    if self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        other = other.astype(dtype, copy=False)
        return this.join(other, how=how, return_indexers=True)
    elif isinstance(self, ABCCategoricalIndex) and isinstance(other, ABCCategoricalIndex) and (not self.ordered) and (not self.categories.equals(other.categories)):
        other = Index(other._values.reorder_categories(self.categories))
    _validate_join_method(how)
    if self.is_monotonic_increasing and other.is_monotonic_increasing and self._can_use_libjoin and other._can_use_libjoin and (self.is_unique or other.is_unique):
        try:
            return self._join_monotonic(other, how=how)
        except TypeError:
            pass
    elif not self.is_unique or not other.is_unique:
        return self._join_non_unique(other, how=how, sort=sort)
    return self._join_via_get_indexer(other, how, sort)

@dispatch.add_dispatch_support
@doc_controls.do_not_generate_docs
def conv2d_transpose(x, kernel, output_shape, strides=(1, 1), padding='valid', data_format=None, dilation_rate=(1, 1)):
    """2D deconvolution (i.e.

  transposed convolution).

  Args:
      x: Tensor or variable.
      kernel: kernel tensor.
      output_shape: 1D int tensor for the output shape.
      strides: strides tuple.
      padding: string, `"same"` or `"valid"`.
      data_format: string, `"channels_last"` or `"channels_first"`.
      dilation_rate: Tuple of 2 integers.

  Returns:
      A tensor, result of transposed 2D convolution.

  Raises:
      ValueError: if `data_format` is neither `channels_last` or
      `channels_first`.
  """
    if data_format is None:
        data_format = image_data_format()
    if <MASK>:
        raise ValueError('Unknown data_format: ' + str(data_format))
    if data_format == 'channels_first' and dilation_rate != (1, 1):
        force_transpose = True
    else:
        force_transpose = False
    (x, tf_data_format) = _preprocess_conv2d_input(x, data_format, force_transpose)
    if data_format == 'channels_first' and tf_data_format == 'NHWC':
        output_shape = (output_shape[0], output_shape[2], output_shape[3], output_shape[1])
    if output_shape[0] is None:
        output_shape = (shape(x)[0],) + tuple(output_shape[1:])
    if isinstance(output_shape, (tuple, list)):
        output_shape = array_ops_stack.stack(list(output_shape))
    padding = _preprocess_padding(padding)
    if tf_data_format == 'NHWC':
        strides = (1,) + strides + (1,)
    else:
        strides = (1, 1) + strides
    if dilation_rate == (1, 1):
        x = nn.conv2d_transpose(x, kernel, output_shape, strides, padding=padding, data_format=tf_data_format)
    else:
        assert dilation_rate[0] == dilation_rate[1]
        x = nn.atrous_conv2d_transpose(x, kernel, output_shape, rate=dilation_rate[0], padding=padding)
    if data_format == 'channels_first' and tf_data_format == 'NHWC':
        x = array_ops.transpose(x, (0, 3, 1, 2))
    return x

@tf_export.tf_export('experimental.numpy.linspace', v1=[])
@np_utils.np_doc('linspace')
def linspace(start, stop, num=50, endpoint=True, retstep=False, dtype=float, axis=0):
    if dtype:
        if np.lib.NumpyVersion(np.__version__) >= '2.0.0.dev0':
            dtype = np_utils.result_type([start * 1.0, stop * 1.0])
        else:
            dtype = np_utils.result_type(dtype)
    start = np_array_ops.array(start, dtype=dtype)
    stop = np_array_ops.array(stop, dtype=dtype)
    if num < 0:
        raise ValueError(f'Argument `num` (number of samples) must be a non-negative integer. Received: num={num}')
    step = ops.convert_to_tensor(np.nan)
    if endpoint:
        result = math_ops.linspace(start, stop, num, axis=axis)
        if num > 1:
            step = (stop - start) / (num - 1)
    else:
        if num > 0:
            step = (stop - start) / num
        if num > 1:
            new_stop = math_ops.cast(stop, step.dtype) - step
            start = math_ops.cast(start, new_stop.dtype)
            result = math_ops.linspace(start, new_stop, num, axis=axis)
        else:
            result = math_ops.linspace(start, stop, num, axis=axis)
    if dtype:
        if <MASK>:
            result = math_ops.floor(result)
        result = math_ops.cast(result, dtype)
    if retstep:
        return (result, step)
    else:
        return result

