def call_for_each_replica(strategy, fn, args=None, kwargs=None):
    """Call `fn` on each worker devices(replica).

  It's highly recommended to wrap the call to this function inside a
  `tf.function`, otherwise the performance is poor.

  Args:
    strategy: `tf.distribute.Strategy`.
    fn: function to call on each worker devices.
    args: positional arguments to `fn`.
    kwargs: keyword arguments to `fn`.

  Returns:
    Wrapped returned value of `fn` from all replicas.
  """
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}
    if isinstance(fn, def_function.Function):
        if fn._jit_compile and all([_is_gpu_device(d) for d in strategy.extended.worker_devices]):
            return _call_for_each_replica(strategy, fn, args, kwargs)
        if strategy not in _cfer_fn_cache:
            _cfer_fn_cache[strategy] = weakref.WeakKeyDictionary()
        wrapped = _cfer_fn_cache[strategy].get(fn)
        if wrapped is None:

            def wrapped_fn(*args, **kwargs):
                return call_for_each_replica(strategy, fn.python_function, args, kwargs)
            wrapped = fn._clone(python_function=wrapped_fn)
            _cfer_fn_cache[strategy][fn] = wrapped
        return wrapped(*args, **kwargs)
    if <MASK>:
        logging.log_first_n(logging.WARN, 'Using %s eagerly has significant overhead currently. We will be working on improving this in the future, but for now please wrap `call_for_each_replica` or `experimental_run` or `run` inside a tf.function to get the best performance.' % strategy.__class__.__name__, 5)
    else:
        fn = autograph.tf_convert(fn, autograph_ctx.control_status_ctx())
    return _call_for_each_replica(strategy, fn, args, kwargs)

def handle(self, **options):
    self.set_options(**options)
    message = ['\n']
    if self.dry_run:
        message.append('You have activated the --dry-run option so no files will be modified.\n\n')
    message.append('You have requested to collect static files at the destination\nlocation as specified in your settings')
    if self.is_local_storage() and self.storage.location:
        destination_path = self.storage.location
        message.append(':\n\n    %s\n\n' % destination_path)
        should_warn_user = self.storage.exists(destination_path) and any(self.storage.listdir(destination_path))
    else:
        destination_path = None
        message.append('.\n\n')
        should_warn_user = True
    if self.interactive and should_warn_user:
        if self.clear:
            message.append('This will DELETE ALL FILES in this location!\n')
        else:
            message.append('This will overwrite existing files!\n')
        message.append("Are you sure you want to do this?\n\nType 'yes' to continue, or 'no' to cancel: ")
        if input(''.join(message)) != 'yes':
            raise CommandError('Collecting static files cancelled.')
    collected = self.collect()
    if <MASK>:
        deleted_count = len(collected['deleted'])
        modified_count = len(collected['modified'])
        unmodified_count = len(collected['unmodified'])
        post_processed_count = len(collected['post_processed'])
        skipped_count = len(collected['skipped'])
        return '\n%(deleted)s%(modified_count)s %(identifier)s %(action)s%(destination)s%(unmodified)s%(post_processed)s%(skipped)s.' % {'deleted': '%s static file%s deleted, ' % (deleted_count, '' if deleted_count == 1 else 's') if deleted_count > 0 else '', 'modified_count': modified_count, 'identifier': 'static file' + ('' if modified_count == 1 else 's'), 'action': 'symlinked' if self.symlink else 'copied', 'destination': " to '%s'" % destination_path if destination_path else '', 'unmodified': ', %s unmodified' % unmodified_count if collected['unmodified'] else '', 'post_processed': collected['post_processed'] and ', %s post-processed' % post_processed_count or '', 'skipped': ', %s skipped due to conflict' % skipped_count if collected['skipped'] else ''}

def _get_example_outputs(model, args):
    input_args = copy.deepcopy(args)
    input_kwargs = {}
    if <MASK>:
        input_kwargs = input_args[-1]
        input_args = input_args[:-1]
    example_outputs = model(*input_args, **input_kwargs)
    if isinstance(example_outputs, list):
        example_outputs = [example_outputs]
    elif not isinstance(example_outputs, tuple):
