def strobelight(profiler: Optional[StrobelightCLIFunctionProfiler]=None, **kwargs: Any) -> Callable[[Callable[_P, _R]], Callable[_P, Optional[_R]]]:
    if <MASK>:
        profiler = StrobelightCLIFunctionProfiler(**kwargs)

    def strobelight_inner(work_function: Callable[_P, _R]) -> Callable[_P, Optional[_R]]:

        @functools.wraps(work_function)
        def wrapper_function(*args: _P.args, **kwargs: _P.kwargs) -> Optional[_R]:
            return profiler.profile(work_function, *args, **kwargs)
        return wrapper_function
    return strobelight_inner

def fns_repr(self) -> str:
    first_repr = self.fns[0]
    if <MASK>:
        first_repr = first_repr.__name__
    if len(self.fns) > 1:
        return f'[{first_repr}, ...]'
    elif self.fns[0] is getattr(torch, first_repr, None):
        return f'torch.{first_repr}'
    elif self.fns[0] is getattr(operator, first_repr, None):
        return f'operator.{first_repr}'
    elif isinstance(self.fns[0], torch._ops.OpOverload):
        return str(self.fns[0])
    else:
        return first_repr

def _most_frequent(array, extra_value, n_repeat):
    """Compute the most frequent value in a 1d array extended with
    [extra_value] * n_repeat, where extra_value is assumed to be not part
    of the array."""
    if array.size > 0:
        if array.dtype == object:
            counter = Counter(array)
            most_frequent_count = counter.most_common(1)[0][1]
            most_frequent_value = _safe_min([value for (value, count) in counter.items() if count == most_frequent_count])
        else:
            mode = _mode(array)
            most_frequent_value = mode[0][0]
            most_frequent_count = mode[1][0]
    else:
        most_frequent_value = 0
        most_frequent_count = 0
    if most_frequent_count == 0 and n_repeat == 0:
        return np.nan
    elif <MASK>:
        return extra_value
    elif most_frequent_count > n_repeat:
        return most_frequent_value
    elif most_frequent_count == n_repeat:
        return _safe_min([most_frequent_value, extra_value])

def create_proxy(self, kind, target, args, kwargs, name=None, type_expr=None, proxy_factory_fn=None):
    rv = super().create_proxy(kind, target, args, kwargs, name, type_expr, proxy_factory_fn)
    if kind == 'placeholder' and target in self.meta_args:
        rv.install_tensor_meta(self.meta_args[target])
        return rv
    if <MASK>:
        if 'device' in kwargs:
            kwargs['device'] = 'meta'
    try:
        args_metas = torch.fx.node.map_aggregate(args, proxys_to_metas)
        kwargs_metas = torch.fx.node.map_aggregate(kwargs, proxys_to_metas)
        if kind == 'call_function':
            meta_target = manual_meta_overrides.get(target, target)
            meta_out = meta_target(*args_metas, **kwargs_metas)
        elif kind == 'call_method':
            meta_target = getattr(args_metas[0], target)
            meta_out = meta_target(*args_metas[1:], **kwargs_metas)
        elif kind == 'call_module':
            assert hasattr(self, 'orig_forward')
            self._disable_module_getattr = True
            try:
                mod = self.root.get_submodule(target)
                mod_type = type(mod)
                if mod_type in manual_meta_overrides:
                    meta_out = manual_meta_overrides[mod_type](mod, *args_metas, **kwargs_metas)
                else:
                    meta_out = self.orig_forward(*args_metas, **kwargs_metas)
            finally:
                self._disable_module_getattr = False
        elif kind == 'get_attr':
            self._disable_module_getattr = True
            try:
                attr_itr = self.root
                atoms = target.split('.')
                for atom in atoms:
                    attr_itr = getattr(attr_itr, atom)
                assert isinstance(attr_itr, torch.Tensor)
                meta_out = attr_itr.to(device='meta')
            finally:
                self._disable_module_getattr = False
        else:
            return rv
        assert isinstance(rv, torch.fx.Proxy), 'Dont support composite output yet'
        rv.install_tensor_meta(meta_out)
    except Exception as e:
        warnings.warn(f'Could not compute metadata for {kind} target {target}: {e}')
    return rv

