def _ask_default(self, default=''):
    """
        Prompt for a default value.

        The ``default`` argument allows providing a custom default value (as a
        string) which will be shown to the user and used as the return value
        if the user doesn't provide any other input.
        """
    self.prompt_output.write('Please enter the default value as valid Python.')
    if default:
        self.prompt_output.write(f"Accept the default '{default}' by pressing 'Enter' or provide another value.")
    self.prompt_output.write('The datetime and django.utils.timezone modules are available, so it is possible to provide e.g. timezone.now as a value.')
    self.prompt_output.write("Type 'exit' to exit this prompt")
    while True:
        if default:
            prompt = '[default: {}] >>> '.format(default)
        else:
            prompt = '>>> '
        self.prompt_output.write(prompt, ending='')
        try:
            code = input()
        except KeyboardInterrupt:
            self.prompt_output.write('\nCancelled.')
            sys.exit(1)
        if <MASK>:
            code = default
        if not code:
            self.prompt_output.write("Please enter some code, or 'exit' (without quotes) to exit.")
        elif code == 'exit':
            sys.exit(1)
        else:
            try:
                return eval(code, {}, {'datetime': datetime, 'timezone': timezone})
            except Exception as e:
                self.prompt_output.write(f'{e.__class__.__name__}: {e}')

def step(self, epoch=None):
    if self._step_count == 1:
        if not hasattr(self.sparsifier.step, '_with_counter'):
            warnings.warn('Seems like `sparsifier.step()` has been overridden after sparsity scheduler initialization. Please, make sure to call `sparsifier.step()` before `scheduler.step()`.', UserWarning)
        elif <MASK>:
            warnings.warn('Detected call of `scheduler.step()` before `sparsifier.step()`. You have to make sure you run the sparsifier.step() BEFORE any calls to the scheduler.step().', UserWarning)
    self._step_count += 1

    class _enable_get_sl_call:

        def __init__(self, o):
            self.o = o

        def __enter__(self):
            self.o._get_sl_called_within_step = True
            return self

        def __exit__(self, type, value, traceback):
            self.o._get_sl_called_within_step = False
    with _enable_get_sl_call(self):
        self.last_epoch += 1
        values = self.get_sl()
    for (i, data) in enumerate(zip(self.sparsifier.groups, values)):
        (param_group, sl) = data
        param_group['sparsity_level'] = sl
        self.print_sl(self.verbose, i, sl, epoch)
    self._last_sl = [group['sparsity_level'] for group in self.sparsifier.groups]
    self.sparsifier.enable_mask_update = True

def __call__(self, fn: Callable) -> Callable:
    sig = inspect.signature(fn)

    @torch._disable_dynamo
    @wraps(fn)
    def _fn(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        type_promoting_args = tuple((bound.arguments[x] for x in self.type_promoting_arg_names if x in bound.arguments.keys()))
        flattened_type_promoting_args = pytree.arg_tree_leaves(*type_promoting_args)
        (compute_dtype, result_dtype) = utils.elementwise_dtypes(*flattened_type_promoting_args, type_promotion_kind=self.type_promotion_kind)
        promoted_args = {x: _maybe_convert_to_dtype(bound.arguments[x], compute_dtype) for x in self.type_promoting_arg_names if x in bound.arguments.keys()}
        bound.arguments.update(promoted_args)
        result = fn(**bound.arguments)
        if 'dtype' in bound.arguments:
            maybe_dtype = bound.arguments['dtype']
            if <MASK>:
                result_dtype = maybe_dtype
        if isinstance(result, TensorLike):
            return _maybe_convert_to_dtype(result, result_dtype)
        if isinstance(result, Sequence):
            return tuple((_maybe_convert_to_dtype(x, result_dtype) for x in result))
        raise AssertionError(f'Unhandled result type: {type(result)}')
    _fn.__signature__ = sig
    return _fn

