def comparison_op(left: ArrayLike, right: Any, op) -> ArrayLike:
    """
    Evaluate a comparison operation `=`, `!=`, `>=`, `>`, `<=`, or `<`.

    Note: the caller is responsible for ensuring that numpy warnings are
    suppressed (with np.errstate(all="ignore")) if needed.

    Parameters
    ----------
    left : np.ndarray or ExtensionArray
    right : object
        Cannot be a DataFrame, Series, or Index.
    op : {operator.eq, operator.ne, operator.gt, operator.ge, operator.lt, operator.le}

    Returns
    -------
    ndarray or ExtensionArray
    """
    lvalues = ensure_wrapped_if_datetimelike(left)
    rvalues = ensure_wrapped_if_datetimelike(right)
    rvalues = lib.item_from_zerodim(rvalues)
    if isinstance(rvalues, list):
        rvalues = np.asarray(rvalues)
    if isinstance(rvalues, (np.ndarray, ABCExtensionArray)):
        if len(lvalues) != len(rvalues):
            raise ValueError('Lengths must match to compare', lvalues.shape, rvalues.shape)
    if should_extension_dispatch(lvalues, rvalues) or ((isinstance(rvalues, (Timedelta, BaseOffset, Timestamp)) or right is NaT) and lvalues.dtype != object):
        res_values = op(lvalues, rvalues)
    elif is_scalar(rvalues) and isna(rvalues):
        if op is operator.ne:
            res_values = np.ones(lvalues.shape, dtype=bool)
        else:
            res_values = np.zeros(lvalues.shape, dtype=bool)
    elif is_numeric_v_string_like(lvalues, rvalues):
        return invalid_comparison(lvalues, rvalues, op)
    elif <MASK>:
        res_values = comp_method_OBJECT_ARRAY(op, lvalues, rvalues)
    else:
        res_values = _na_arithmetic_op(lvalues, rvalues, op, is_cmp=True)
    return res_values

def codegen_kernel(self, name: Optional[str]=None) -> str:
    """Called at the end to generate a final kernel string"""
    self.codegen_body()
    code = IndentedBuffer()
    if <MASK>:
        code.writeline('(R"MTL(')
    else:
        code.writeline("compile_mps_shader('''")
    idx_vars = self.active_range_trees()
    with code.indent():
        if not V.graph.cpp_wrapper:
            for header in self.headers:
                code.writeline(f'#include <c10/metal/{header}.h>')
        else:
            headers = [f'#include <c10/metal/{header}.h>' for header in self.headers]
            header_contents = _embed_headers(headers, [Path(__file__).parent.parent.parent / 'include'], OrderedSet())
            code.writeline(header_contents)
        if self.inside_reduction:
            total_reduction_size = math.prod((t.numel for t in self.range_trees if t.is_reduction))
            threadgroup_size = min(total_reduction_size, self.max_threadgroup_size) if isinstance(total_reduction_size, sympy.Integer) else self.max_threadgroup_size
            code.writeline(f'[[max_total_threads_per_threadgroup({threadgroup_size})]]')
        code.writeline('kernel void generated_kernel(')
        with code.indent():
            for (outer, inner) in self.args.output_buffers.items():
                if outer in self.removed_buffers:
                    continue
                dtype_str = self.dtype_to_str(V.graph.get_dtype(outer))
                code.writeline(f'device {dtype_str}* {inner},')
            for (outer, inner) in self.args.input_buffers.items():
                dtype = V.graph.get_dtype(outer)
                if dtype == torch.float64:
                    outer_buf = V.graph.try_get_buffer(outer)
                    if outer_buf is None or outer_buf.get_size() != []:
                        raise RuntimeError('float64 is not supported by MPS')
                    dtype_str = 'float'
                else:
                    dtype_str = self.dtype_to_str(dtype)
                code.writeline(f'constant {dtype_str}* {inner},')
            for (outer, inner) in self.args.sizevars.items():
                code.writeline(f'constant long& {inner},')
            for idx_var in idx_vars:
                if isinstance(idx_var.numel, sympy.Integer):
                    pass
                else:
                    code.writeline(f'constant long& {idx_var.prefix}numel,')
            assert len(idx_vars) < 4, 'Up to 3 index variables are supported'
            thread_pos_dtype = f'uint{len(idx_vars)}' if len(idx_vars) > 1 else 'uint'
            thread_pos_var_name = idx_vars[0].name if len(idx_vars) == 1 else 'thread_pos'
            thread_pos_suffix = ',' if self.inside_reduction else ''
            code.writeline(f'{thread_pos_dtype} {thread_pos_var_name} [[thread_position_in_grid]]{thread_pos_suffix}')
            if self.inside_reduction:
                code.writeline(f'{thread_pos_dtype} group_pos [[thread_position_in_threadgroup]]')
        code.writeline(') {')
        with code.indent():
            if len(idx_vars) > 1:
                for (idx, var) in enumerate(idx_vars):
                    code.writeline(f'auto {var.name} = thread_pos.{chr(120 + idx)};')
            code.splice(self.indexing_code)
            code.splice(self.body)
        code.writeline('}')
    if V.graph.cpp_wrapper:
        code.writeline(')MTL");')
    else:
        code.writeline("''')")
    return code.getvalue()

def __call__(self, a, b, *args, **kwargs):
    """
        Execute the call behavior.

        """
    (da, db) = (getdata(a), getdata(b))
    with np.errstate():
        np.seterr(divide='ignore', invalid='ignore')
        result = self.f(da, db, *args, **kwargs)
    (ma, mb) = (getmask(a), getmask(b))
    if ma is nomask:
        if mb is nomask:
            m = nomask
        else:
            m = umath.logical_or(getmaskarray(a), mb)
    elif mb is nomask:
        m = umath.logical_or(ma, getmaskarray(b))
    else:
        m = umath.logical_or(ma, mb)
    if not result.ndim:
        if m:
            return masked
        return result
    if m is not nomask and m.any():
        try:
            np.copyto(result, da, casting='unsafe', where=m)
        except Exception:
            pass
    masked_result = result.view(get_masked_subclass(a, b))
    masked_result._mask = m
    if <MASK>:
        masked_result._update_from(a)
    elif isinstance(b, MaskedArray):
        masked_result._update_from(b)
    return masked_result

def all_reduce(self, step: str, map_fun: Callable[[], T], reduce_fun: Callable[[list[T]], R]) -> R:
    """
        Compute a value on each rank, then do centralized reduce on a single rank, followed by a broadcast.

        This method operates in the following way:
            Run ``map_fun`` on all ranks
            Gather results on rank 0
            Call ``reduce_fun`` on all those values
            Broadcast the reduced value to all ranks.
        """
    local_data: Union[T, WRAPPED_EXCEPTION]
    try:
        local_data = map_fun()
    except BaseException as e:
        local_data = _wrap_exception(e)
    all_data = self.gather_object(local_data)
    result: Optional[Union[R, CheckpointException]] = None
    if self.is_coordinator:
        if <MASK>:
            raise AssertionError('all_data is None')
        node_failures = _get_failure_dict(all_data)
        if len(node_failures) == 0:
            try:
                result = reduce_fun(cast(list[T], all_data))
            except BaseException as e:
                node_failures[self.rank] = _wrap_exception(e)
        if len(node_failures) > 0:
            result = CheckpointException(step, node_failures)
    final_result = self.broadcast_object(result)
    if isinstance(final_result, CheckpointException):
        raise final_result
    return cast(R, final_result)

