def valuetype_type(t: Type, *, binds: ArgName, mutable: bool=True, symint: bool=False) -> NamedCType | None:
    if isinstance(t, BaseType):
        if t.name in (BaseTy.Tensor, BaseTy.Scalar):
            return None
        elif str(t) == 'SymInt':
            if <MASK>:
                return NamedCType(binds, BaseCType(SymIntT))
            else:
                return NamedCType(binds, BaseCType(longT))
        return NamedCType(binds, BaseCType(BaseTypeToCppMapping[t.name]))
    elif isinstance(t, OptionalType):
        elem = valuetype_type(t.elem, binds=binds, mutable=mutable, symint=symint)
        if elem is None:
            return None
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if str(t.elem) == 'bool':
            assert t.size is not None
            return NamedCType(binds, ArrayCType(BaseCType(boolT), t.size))
        else:
            return None
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

@staticmethod
def constant(value, dtype):
    if isinstance(value, ValueRanges):
        if not value.is_singleton():
            raise AssertionError('ValueRanges must be a singleton for constant()')
        value = value.lower
    is_python = isinstance(value, (int, float, bool))
    if not is_python and (not isinstance(value, (BooleanAtom, sympy.Integer, sympy.Number))):
        raise AssertionError(f'not a supported constant type: {type(value)}')
    if isinstance(value, SupportsFloat) and math.isnan(value):
        if dtype == torch.bool:
            return ValueRanges.unknown_bool()
        elif dtype.is_floating_point:
            return ValueRanges.unknown()
        else:
            return ValueRanges.unknown_int()
    if is_python:
        type_ = dtype_to_type(dtype)
        value = type_(value)
    elif dtype == torch.bool:
        if not isinstance(value, BooleanAtom):
            raise AssertionError('expected BooleanAtom for bool dtype')
    elif dtype.is_floating_point:
        if <MASK>:
            raise AssertionError('expected float-like sympy value for float dtype')
    elif not getattr(value, 'is_integer', False):
        raise AssertionError('expected integer sympy value for int dtype')
    r = ValueRanges.wrap(value)
    return r

def func(*args, **kw):
    """Updates the `_metadata_request` attribute of the consumer (`instance`)
