def parse_arg(arg_type: torch.JitType, codegen_arg: str) -> str:
    new_codegen_arg = codegen_arg.removeprefix('&temporary_reference(')
    if new_codegen_arg != codegen_arg:
        if codegen_arg.endswith('.get())'):
            codegen_arg = new_codegen_arg.removesuffix('.get())')
        else:
            codegen_arg = new_codegen_arg.removesuffix(')')
    if isinstance(arg_type, torch.OptionalType):
        codegen_arg = codegen_arg.removeprefix('&')
        if <MASK>:
            return 'from(std::nullopt)'
        var_name = f'tmp_var_{next(tmp_var_number)}'
        dispatch_lines.writeline(f'std::optional {var_name}{{{parse_arg(arg_type.getElementType(), codegen_arg)}}};')
        return f'from({var_name})'
    raii_var = self.create_tmp_raii_handle_var_if_needed(codegen_arg, dispatch_lines)
    temp_handle = raii_var != codegen_arg
    if isinstance(arg_type, torch.TensorType):
        if not temp_handle:
            var_name = f'tmp_var_{next(tmp_var_number)}'
            dispatch_lines.writeline(f'AtenTensorHandle {var_name};')
            dispatch_lines.writeline(f'aoti_torch_new_tensor_handle({raii_var}, &{var_name});')
            return f'from({var_name})'
        return f'from({raii_var}.release())'
    return f'from({codegen_arg})'

def _create_wrapped_method(cls, name):
    orig_fn = getattr(cls, name)

    @functools.wraps(orig_fn)
    def wrapped(*args, **kwargs):
        """
        Search the args and kwargs for a Proxy object. If there is one,
        emit a ``call_method`` node to preserve the call to this method
        directly. Otherwise, just return the results of this function
        call, as this function is not being traced.
        """
        proxy = _find_proxy(args, kwargs)
        if <MASK>:
            return proxy.tracer.create_proxy('call_method', name, args, kwargs)
        return orig_fn(*args, **kwargs)
    return wrapped

@functools.cache
def get_assert_bytecode_sequence(with_msg: bool) -> list[str]:
    if <MASK>:

        def fn(x: Any) -> None:
            assert x, 'msg'
    else:

        def fn(x: Any) -> None:
            assert x
    insts = [inst.opname for inst in dis.get_instructions(fn)]
    begin_idx = next((i for (i, inst) in enumerate(insts) if inst.startswith('POP_JUMP')))
    end_idx = insts.index('RAISE_VARARGS')
    return insts[begin_idx + 1:end_idx + 1]

def _find_frame_locals(self) -> _FrameLocalResult:
    """
        Given the current user code frame, finds the relevant lines of code,
        values of symbolic locals, and free symbols involved.
        """
    frame_locals: dict[str, Any] = {}
    frame_symbols: dict[str, str] = {}
    if (frame := _find_user_code_frame()) is None or frame.f_code.co_filename == '<string>':
        return _FrameLocalResult()
    instructions = list(dis.Bytecode(frame.f_code))
    (co_lines, offset) = inspect.getsourcelines(frame.f_code)
    (start, end, cur) = (None, None, None)
    for (i, instr) in enumerate(instructions):
        if instr.starts_line is not None:
            cur = instr.starts_line
        if cur != frame.f_lineno:
            continue
        if start is None:
            start = end = i
        else:
            end = i
    if start is None or end is None:
        return _FrameLocalResult()

    def go(x: Any) -> Optional[str]:
        if isinstance(x, torch.Tensor):
            for y in x.size():
                go(y)
            for y in x.stride():
                go(y)
            go(x.storage_offset())
            return f'Tensor(shape: {x.size()}, stride: {x.stride()}, storage_offset: {x.storage_offset()})'
        elif isinstance(x, (SymBool, SymInt, SymFloat)):
            for s in x.node.expr.free_symbols:
                if str(s) in frame_symbols:
                    continue
                if s in self.var_to_sources:
                    frame_symbols[str(s)] = self.var_to_sources[s][0].name()
            return str(x)
        return None
    last_lineno = frame.f_lineno
    for instr in instructions[start:end + 1]:
        if (lineno := instr.starts_line) is not None:
            last_lineno = max(last_lineno, lineno)
        if <MASK>:
            flat_locals = pytree.tree_flatten(frame.f_locals[instr.argval])[0]
            frame_locals[instr.argval] = [go(flat_local) for flat_local in flat_locals]
    locs = co_lines[frame.f_lineno - offset:last_lineno + 1 - offset]
    if not locs:
        return _FrameLocalResult()
    indent = len(locs[0]) - len(locs[0].lstrip())
    frame_loc = ''.join([loc[indent:] for loc in locs]).strip()
    return _FrameLocalResult(loc=frame_loc, locals=frame_locals, symbols=frame_symbols)

def get_test_db_clone_settings(self, suffix):
    orig_settings_dict = self.connection.settings_dict
    source_database_name = orig_settings_dict['NAME'] or ':memory:'
    if <MASK>:
        (root, ext) = os.path.splitext(source_database_name)
        return {**orig_settings_dict, 'NAME': f'{root}_{suffix}{ext}'}
    start_method = multiprocessing.get_start_method()
    if start_method == 'fork':
        return orig_settings_dict
    if start_method in {'forkserver', 'spawn'}:
        return {**orig_settings_dict, 'NAME': f'{self.connection.alias}_{suffix}.sqlite3'}
    raise NotSupportedError(f'Cloning with start method {start_method!r} is not supported.')

