def broadcast_dimension(self, axis, lengths):
    """Returns a shape that is broadcast-compatible with self & lengths.

    * If dimension[axis] is uniform and lengths is a scalar, the check
      that either lengths==1 or axis==1 or lengths==axis, and tile
      dimension[axis] with tf.where(lengths==axis, 1, axis) repeats.

    * If dimension[axis] is uniform and lengths is a vector, then check
      that dimension[axis]==1, and raggedly tile dimension[axis] with
      lengths repeats.  (we can skip tiling if we statically know that
      slice_lengths == 1??)

    * If dimension[axis] is ragged and lengths is a scalar, then check
      that lengths==1.

    * If dimension[axis] is ragged and lengths is a vector, then check
      that self.dimension_size(axis) == lengths.

    Args:
      axis: `int`.  The dimension to broadcast.
      lengths: 0-D or 1-D integer `Tensor`.

    Returns:
      A `RaggedTensorDynamicShape`.
    """
    lengths = ragged_util.convert_to_int_tensor(lengths, name='lengths', dtype=self.dim_size_dtype)
    if lengths.shape.ndims is None:
        raise ValueError('lengths must have a known rank.')
    elif lengths.shape.ndims > 1:
        raise ValueError('lengths must be a scalar or vector')
    else:
        lengths_is_scalar = lengths.shape.ndims == 0
    if self.is_ragged(axis):
        if lengths_is_scalar:
            condition = math_ops.equal(lengths, 1)
        else:
            condition = math_ops.reduce_all(math_ops.equal(lengths, self.dimension_size(axis)))
    else:
        axis_dim_size = self.dimension_size(axis)
        if lengths_is_scalar:
            condition = math_ops.equal(lengths, 1) | math_ops.equal(axis_dim_size, 1) | math_ops.equal(axis_dim_size, lengths)
        else:
            condition = math_ops.equal(axis_dim_size, 1)
    broadcast_err = ['Unable to broadcast: dimension size mismatch in dimension', axis, 'lengths=', lengths, 'dim_size=', self.dimension_size(axis)]
    broadcast_check = control_flow_assert.Assert(condition, data=broadcast_err, summarize=10)
    with ops.control_dependencies([broadcast_check]):
        if axis < self.num_partitioned_dimensions:
            if self.is_ragged(axis):
                return RaggedTensorDynamicShape(self._partitioned_dim_sizes, array_ops.identity(self.inner_dim_sizes), self.dim_size_dtype)
            else:
                return self._broadcast_uniform_partitioned_dimension(axis, lengths)
        elif lengths_is_scalar:
            return self._broadcast_inner_dimension_to_uniform(axis, lengths)
        else:
            if <MASK>:
                raise ValueError('Unable to broadcast: outermost dimension must be uniform.')
            return self._broadcast_inner_dimension_to_ragged(axis, lengths)

def rsample(self, sample_shape: _size=torch.Size()) -> Tensor:
    shape = self._extended_shape(sample_shape)
    finfo = torch.finfo(self.loc.dtype)
    if <MASK>:
        u = torch.rand(shape, dtype=self.loc.dtype, device=self.loc.device) * 2 - 1
        return self.loc - self.scale * u.sign() * torch.log1p(-u.abs().clamp(min=finfo.tiny))
    u = self.loc.new(shape).uniform_(finfo.eps - 1, 1)
    return self.loc - self.scale * u.sign() * torch.log1p(-u.abs())

def _skip_op(self, op_id, op, ops_in_exec_path, report_handler):
    """Returns True if we should not trace Op.

    Args:
      op_id: Topological index of the op.
      op: tf.Operation
      ops_in_exec_path: Set of operations that are in the execution path.
      report_handler: An instance of tensor_tracer_report.TTReportHandle.
    Returns:
      True if the op should not be traced, false otherwise.
    """
    if <MASK>:
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_WHILELOOP_OP))
        return True
    if TensorTracer.control_flow_op(op):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_CONTROLFLOW_OP))
        return True
    if TensorTracer.unsafe_op(op):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_UNSAFE_OP))
        return True
    if TensorTracer.device_mismatch(self._tt_config.device_type, op):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_DEVICE_MISMATCH))
        return True
    if op not in ops_in_exec_path:
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_NOT_EXECUTED))
        return True
    if self._is_in_control_flow(op) or not self._is_in_outmost_while_loop(op):
        if not self._should_trace_in_control_flow():
            report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_IN_CONTROL_FLOW))
            return True
    if self._is_user_included_op(op):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_USER_INCLUDED))
        if tensor_tracer_flags.TT_CHECK_FILTER.value:
            logging.info('USER_INCLUDED op %s', op.name)
        return False
    if not self._inside_op_range(op_id):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_OUTSIDE_OP_RANGE))
        return True
    if not self._is_interesting_op(op):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_LESS_INTERESTING_OP))
        return True
    if self._is_user_excluded_op(op):
        report_handler.instrument_op(op, TensorTracer.reason(op_id, _REASON_USER_EXCLUDED))
        if tensor_tracer_flags.TT_CHECK_FILTER.value:
            logging.info('USER_EXCLUDED op %s', op.name)
        return True
    return False

def _assert_all_finite(X, allow_nan=False, msg_dtype=None, estimator_name=None, input_name=''):
    """Like assert_all_finite, but only for ndarray."""
    (xp, is_array_api) = get_namespace(X)
    if _get_config()['assume_finite']:
        return
    X = xp.asarray(X)
    if not is_array_api and X.dtype == np.dtype('object') and (not allow_nan):
        if _object_dtype_isnan(X).any():
            raise ValueError('Input contains NaN')
    if <MASK>:
        return
    with np.errstate(over='ignore'):
        first_pass_isfinite = xp.isfinite(xp.sum(X))
    if first_pass_isfinite:
        return
    _assert_all_finite_element_wise(X, xp=xp, allow_nan=allow_nan, msg_dtype=msg_dtype, estimator_name=estimator_name, input_name=input_name)

def find_smallest_i(graph: fx.Graph, prefix: str) -> int:
    i = 0
    for node in graph.nodes:
        if node.op == 'get_attr' and node.target.startswith(prefix):
            if len(node.target) > len(prefix):
                post_fix = node.target.split(prefix)[-1]
                if <MASK>:
                    i = max(i, int(post_fix))
    for key in existing_keys:
        if key.startswith(prefix):
            if len(key) > len(prefix):
                post_fix = key.split(prefix)[-1]
                if post_fix.isdigit():
                    i = max(i, int(post_fix))
    return i + 1

@final
def _call_cython_op(self, values: np.ndarray, *, min_count: int, ngroups: int, comp_ids: np.ndarray, mask: npt.NDArray[np.bool_] | None, result_mask: npt.NDArray[np.bool_] | None, initial: Any=0, **kwargs) -> np.ndarray:
    orig_values = values
    dtype = values.dtype
    is_numeric = dtype.kind in 'iufcb'
    is_datetimelike = dtype.kind in 'mM'
    if self.how in ['any', 'all']:
        if <MASK>:
            mask = isna(values)
    if is_datetimelike:
        values = values.view('int64')
        is_numeric = True
    elif dtype.kind == 'b':
        values = values.view('uint8')
    if values.dtype == 'float16':
        values = values.astype(np.float32)
    if self.how in ['any', 'all']:
        if dtype == object:
            if kwargs['skipna']:
                if mask is not None and mask.any():
                    values = values.copy()
                    values[mask] = True
        values = values.astype(bool, copy=False).view(np.int8)
        is_numeric = True
    values = values.T
    if mask is not None:
        mask = mask.T
        if result_mask is not None:
            result_mask = result_mask.T
    out_shape = self._get_output_shape(ngroups, values)
    func = self._get_cython_function(self.kind, self.how, values.dtype, is_numeric)
    values = self._get_cython_vals(values)
    out_dtype = self._get_out_dtype(values.dtype)
    result = maybe_fill(np.empty(out_shape, dtype=out_dtype))
    if self.kind == 'aggregate':
        counts = np.zeros(ngroups, dtype=np.int64)
        if self.how in ['idxmin', 'idxmax', 'min', 'max', 'mean', 'last', 'first', 'sum', 'median']:
            if self.how == 'sum':
                kwargs['initial'] = initial
            func(out=result, counts=counts, values=values, labels=comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, is_datetimelike=is_datetimelike, **kwargs)
        elif self.how in ['sem', 'std', 'var', 'ohlc', 'prod']:
            if self.how in ['std', 'sem']:
                kwargs['is_datetimelike'] = is_datetimelike
            func(result, counts, values, comp_ids, min_count=min_count, mask=mask, result_mask=result_mask, **kwargs)
        elif self.how in ['any', 'all']:
            func(out=result, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            result = result.astype(bool, copy=False)
        elif self.how in ['skew', 'kurt']:
            func(out=result, counts=counts, values=values, labels=comp_ids, mask=mask, result_mask=result_mask, **kwargs)
            if dtype == object:
                result = result.astype(object)
        else:
            raise NotImplementedError(f'{self.how} is not implemented')
    else:
        if self.how != 'rank':
            kwargs['result_mask'] = result_mask
        func(out=result, values=values, labels=comp_ids, ngroups=ngroups, is_datetimelike=is_datetimelike, mask=mask, **kwargs)
    if self.kind == 'aggregate' and self.how not in ['idxmin', 'idxmax']:
        if result.dtype.kind in 'iu' and (not is_datetimelike):
            cutoff = max(0 if self.how in ['sum', 'prod'] else 1, min_count)
            empty_groups = counts < cutoff
            if empty_groups.any():
                if result_mask is not None:
                    assert result_mask[empty_groups].all()
                else:
                    result = result.astype('float64')
                    result[empty_groups] = np.nan
    result = result.T
    if self.how not in self.cast_blocklist:
        res_dtype = self._get_result_dtype(orig_values.dtype)
        op_result = maybe_downcast_to_dtype(result, res_dtype)
    else:
        op_result = result
    return op_result

def __call__(self, x):
    """
        Computes the transform `x => y`.
        """
    if <MASK>:
        return self._call(x)
    (x_old, y_old) = self._cached_x_y
    if x is x_old:
        return y_old
    y = self._call(x)
    self._cached_x_y = (x, y)
    return y

def _interpolate_scipy_wrapper(x: np.ndarray, y: np.ndarray, new_x: np.ndarray, method: str, fill_value=None, bounds_error: bool=False, order=None, **kwargs):
    """
    Passed off to scipy.interpolate.interp1d. method is scipy's kind.
    Returns an array interpolated at new_x.  Add any new methods to
    the list in _clean_interp_method.
    """
    extra = f'{method} interpolation requires SciPy.'
    import_optional_dependency('scipy', extra=extra)
    from scipy import interpolate
    new_x = np.asarray(new_x)
    alt_methods: dict[str, Callable[..., np.ndarray]] = {'barycentric': interpolate.barycentric_interpolate, 'krogh': interpolate.krogh_interpolate, 'from_derivatives': _from_derivatives, 'piecewise_polynomial': _from_derivatives, 'cubicspline': _cubicspline_interpolate, 'akima': _akima_interpolate, 'pchip': interpolate.pchip_interpolate}
    interp1d_methods = ['nearest', 'zero', 'slinear', 'quadratic', 'cubic', 'polynomial']
    terp: Callable[..., np.ndarray] | None
    if method in interp1d_methods:
        if method == 'polynomial':
            kind = order
        else:
            kind = method
        terp = interpolate.interp1d(x, y, kind=kind, fill_value=fill_value, bounds_error=bounds_error)
        new_y = terp(new_x)
    elif method == 'spline':
        if <MASK>:
            raise ValueError(f'order needs to be specified and greater than 0; got order: {order}')
        terp = interpolate.UnivariateSpline(x, y, k=order, **kwargs)
        new_y = terp(new_x)
    else:
        if not x.flags.writeable:
            x = x.copy()
        if not y.flags.writeable:
            y = y.copy()
        if not new_x.flags.writeable:
            new_x = new_x.copy()
        terp = alt_methods.get(method, None)
        if terp is None:
            raise ValueError(f'Can not interpolate with method={method}.')
        kwargs.pop('downcast', None)
        new_y = terp(x, y, new_x, **kwargs)
    return new_y

def check_pt2_compliant_op(output_graph: OutputGraph, kind: str, target: Any, args: Any, kwargs: Any) -> None:
    if kind != 'call_function':
        return

    def encountered_compliant_op(target: torch._ops.OpOverload) -> None:
        if target.namespace in {'prim', 'prims', 'aten'}:
            return
        output_graph.compliant_custom_ops.add(target)

    def encountered_non_compliant_op(target: torch._ops.OpOverload, msg: str) -> None:
        output_graph.non_compliant_ops.add(target)
        if config.only_allow_pt2_compliant_ops:
            unimplemented_v2(gb_type='Encountered non-PT2-compliant op', context='', explanation=msg + ' ' + err_epilogue, hints=[])
    if isinstance(target, torch._ops.OpOverload):
        if torch.Tag.pt2_compliant_tag in target.tags:
            encountered_compliant_op(target)
            return
        encountered_non_compliant_op(target, f'Encountered the torch.ops.OpOverload {target} that is not PT2 compliant.')
        return
    if isinstance(target, torch._ops.OpOverloadPacket):
        overloads = tuple(target.overloads())
        if <MASK>:
            op = getattr(target, overloads[0])
            if torch.Tag.pt2_compliant_tag in op.tags:
                encountered_compliant_op(op)
                return
            encountered_non_compliant_op(op, f'Encountered the non-overloaded torch.ops.OpOverloadPacket {target} that is not PT2 compliant. ')
            return
        (args, kwargs) = torch._dynamo.utils.get_fake_values_from_nodes(output_graph.current_tx, (args, kwargs), False)
        try:
            overload = torch._C._jit_resolve_packet(target._qualified_op_name, *args, **kwargs)
        except RuntimeError as e:
            unimplemented_v2(gb_type='Error when attempting to resolve op packet', context='', explanation=str(e), hints=[])
        op = getattr(target, overload)
        if torch.Tag.pt2_compliant_tag in op.tags:
            encountered_compliant_op(op)
        else:
            encountered_non_compliant_op(op, f'Encountered the torch.ops.OpOverloadPacket {target} which resolves to the overload ({overload}) that is not PT2 compliant.')

def get_variable(self, var_store, name, shape=None, dtype=None, initializer=None, regularizer=None, reuse=None, trainable=None, collections=None, caching_device=None, partitioner=None, validate_shape=True, use_resource=None, custom_getter=None, constraint=None, synchronization=VariableSynchronization.AUTO, aggregation=VariableAggregation.NONE):
    """Gets an existing variable with this name or create a new one."""
    if regularizer is None:
        regularizer = self._regularizer
    if caching_device is None:
        caching_device = self._caching_device
    if partitioner is None:
        partitioner = self._partitioner
    if custom_getter is None:
        custom_getter = self._custom_getter
    if context.executing_eagerly():
        reuse = False
        use_resource = True
    else:
        if reuse is None:
            reuse = self._reuse
        if <MASK>:
            use_resource = self._use_resource
    full_name = self.name + '/' + name if self.name else name
    with ops.name_scope(None, skip_on_eager=False):
        if dtype is not None and initializer is not None and (not callable(initializer)):
            init_dtype = ops.convert_to_tensor(initializer).dtype.base_dtype
            if init_dtype != dtype:
                raise ValueError("Initializer type '%s' and explicit dtype '%s' don't match." % (init_dtype, dtype))
        if initializer is None:
            initializer = self._initializer
        if constraint is None:
            constraint = self._constraint
        if dtype is None:
            dtype = self._dtype
        return var_store.get_variable(full_name, shape=shape, dtype=dtype, initializer=initializer, regularizer=regularizer, reuse=reuse, trainable=trainable, collections=collections, caching_device=caching_device, partitioner=partitioner, validate_shape=validate_shape, use_resource=use_resource, custom_getter=custom_getter, constraint=constraint, synchronization=synchronization, aggregation=aggregation)

def disallow_legacy_graph(cls_name, method_name):
    if <MASK>:
