def gen_vmap_plumbing(native_function: NativeFunction) -> str | None:
    schema = native_function.func
    sig = DispatcherSignature.from_schema(schema)
    returns = schema.returns
    if <MASK>:
        return None
    if len(returns) == 0:
        return gen_vmap_plumbing_no_returns(native_function)
    return_symint_overrides = ['_scaled_dot_product_flash_attention', '_scaled_dot_product_cudnn_attention']
    if not all((ret.type.is_tensor_like() for ret in returns)) and schema.name.unambiguous_name() not in return_symint_overrides:
        return None
    if 'inplace_view' in native_function.tags:
        return None
    if schema.kind() == SchemaKind.inplace:
        return gen_vmap_inplace_plumbing(native_function)
    if schema.kind() != SchemaKind.functional:
        return None
    results_var = 'results'
    cur_level_var = 'cur_level'
    (unwraps, unwrapped_arg_list) = gen_unwraps(schema.arguments.flat_all, cur_level_var)
    bdims_all_none_case = gen_case_where_all_bdims_are_none(sig, schema, cur_level_var)
    wrapped_returns = gen_returns(returns, cur_level_var, results_var)
    return f"""template <typename batch_rule_t, batch_rule_t batch_rule>\n{sig.decl(name=schema.name.unambiguous_name() + '_generated_plumbing')} {{\n  c10::impl::ExcludeDispatchKeyGuard guard(DispatchKey::FuncTorchBatched);\n  auto maybe_layer = maybeCurrentDynamicLayer();\n  vmap_check_escaped(maybe_layer, "gen_vmap_plumbing");\n  int64_t {cur_level_var} = maybe_layer->layerId();\n{textwrap.indent(bdims_all_none_case, '  ')}\n{textwrap.indent(unwraps, '  ')}\n  auto {results_var} = batch_rule({', '.join(unwrapped_arg_list)});\n  {wrapped_returns}\n}}"""

def __repr__(self):
    if self._device is not None:
        if self._worker_name is not None:
            return f'{self._worker_name}/{self._device}'
        elif <MASK>:
            return f'rank:{self._rank}/{self._device}'
        else:
            return str(self._device)
    elif self._worker_name is not None:
        return f'{self._worker_name}'
    elif self._rank is not None:
        return f'{self._rank}'
    else:
        raise RuntimeError('Invalid state!')

def full_clean(self, exclude=None, validate_unique=True, validate_constraints=True):
    """
        Call clean_fields(), clean(), validate_unique(), and
        validate_constraints() on the model. Raise a ValidationError for any
        errors that occur.
        """
    errors = {}
    if exclude is None:
        exclude = set()
    else:
        exclude = set(exclude)
    try:
        self.clean_fields(exclude=exclude)
    except ValidationError as e:
        errors = e.update_error_dict(errors)
    try:
        self.clean()
    except ValidationError as e:
        errors = e.update_error_dict(errors)
    if validate_unique:
        for name in errors:
            if name != NON_FIELD_ERRORS and name not in exclude:
                exclude.add(name)
        try:
            self.validate_unique(exclude=exclude)
        except ValidationError as e:
            errors = e.update_error_dict(errors)
    if <MASK>:
        for name in errors:
            if name != NON_FIELD_ERRORS and name not in exclude:
                exclude.add(name)
        try:
            self.validate_constraints(exclude=exclude)
        except ValidationError as e:
            errors = e.update_error_dict(errors)
    if errors:
        raise ValidationError(errors)

def set_kernel_post_grad_provenance_tracing(node_schedule: Union[Sequence[BaseSchedulerNode], ExternKernel], kernel_name: str, is_extern: bool=False) -> Optional[int]:
    """
    Set the mapping between `kernel_name` and the post_grad nodes in `node_schedule`.

    Returns a unique int debug handler for each call to this function.
    """
    if config.trace.provenance_tracking_level == 0:
        return None
    try:
        from .codegen.simd_kernel_features import DisableReduction, EnableReduction
        global _inductor_triton_kernel_to_post_grad_node_info
        global _inductor_kernel_stack_trace
        global _inductor_kernel_provenance_debug_handle
        _inductor_kernel_provenance_debug_handle += 1
        stack_traces: list[str] = []
        kernel_name = f'{kernel_name}:{_inductor_kernel_provenance_debug_handle}'
        if is_extern:
            assert isinstance(node_schedule, ExternKernel)
            curr_node_info = _inductor_triton_kernel_to_post_grad_node_info.setdefault(kernel_name, [])
            if node_schedule.origin_node:
                origin_node_name = node_schedule.origin_node.name
                if origin_node_name not in curr_node_info:
                    curr_node_info.append(origin_node_name)
            else:
                curr_node_info.extend((origin.name for origin in node_schedule.origins if origin.name not in curr_node_info))
            stack_traces = list(node_schedule.get_stack_traces())
        else:
            assert isinstance(node_schedule, list)
            stack_traces_set: OrderedSet[str] = OrderedSet()
            for snode in node_schedule:
                if <MASK>:
                    if snode.node is not None:
                        curr_node_info = _inductor_triton_kernel_to_post_grad_node_info.setdefault(kernel_name, [])
                        stack_traces_set.update(snode.node.get_stack_traces())
                        curr_node_info.extend((origin.name for origin in snode.node.origins if origin.name not in curr_node_info))
            stack_traces = list(stack_traces_set)
        _inductor_kernel_stack_trace.setdefault(kernel_name, []).extend(stack_traces)
        return _inductor_kernel_provenance_debug_handle
    except Exception as e:
        signpost_event('inductor', 'provenance_tracking_error', {'function': 'set_kernel_post_grad_provenance_tracing', 'error_msg': str(e), 'stack_trace': traceback.format_exc()})
        return None

