            if type(static_attr) is not types.GetSetDescriptorType:
                return None
            proxy = GetAttrVariable.create_getattr_proxy(self.as_proxy(), name)
            if self.source is not None:
                return wrap_fx_proxy(tx=tx, proxy=proxy, source=AttrSource(self.source, name))
            else:
                return wrap_fx_proxy(tx=tx, proxy=proxy)
        result = try_generic_attr_handling()
    if <MASK>:
        result = self.dynamic_getattr(tx, name)
    if result is None:
        raise NotImplementedError
    return result

def _shape_invariant_to_type_spec(var, shape=None):
    """Converts a shape invariant to a TypeSpec.

  If `var` is a TensorArray, it will first be converted to its flow.

  Args:
    var: The tensor, tensor array or composite tensor whose shape is described
      by the shape invariant.
    shape: A `TypeSpec` or `TensorShape`.  If `shape` is already a `TypeSpec`,
      then it is simply returned as-is.

  Returns:
    A `TypeSpec` for `var`, consistent with the given shape.

  Raises:
    TypeError: If `shape` is a TypeSpec and not compatible with `var`.
    TypeError: If `shape` is not None, a TypeSpec, or a TensorShape.
    TypeError: If `shape` is a TensorShape, `var` is a CompositeTensor, and
      `var` doesn't implement the `_shape_invariant_to_type_spec` method.
  """
    var = _convert_tensorarray_to_flow(var)
    if <MASK>:
        return type_spec.type_spec_from_value(var)
    elif isinstance(shape, type_spec.TypeSpec):
        if not shape.is_compatible_with(var):
            raise TypeError('TypeSpec %r is not compatible with %r' % (shape, var))
        return shape
    elif not isinstance(shape, tensor_shape.TensorShape):
        raise TypeError(f"'shape' must be one of TypeSpec, TensorShape or None. Received: {type(shape)}")
    if isinstance(var, tensor_lib.Tensor):
        return tensor_lib.TensorSpec(shape, var.dtype)
    else:
        try:
            return var._shape_invariant_to_type_spec(shape)
        except NotImplementedError as e:
            raise TypeError(f'To describe or constrain a {type(var).__name__}, use a {type(var._type_spec).__name__} instead of a TensorShape.') from e

def is_cacheable_function(target):
    if isinstance(target, (torch._ops.OpOverload, torch._ops.OpOverloadPacket)):
        return True
    if <MASK>:
        return True
    if isinstance(target, torch._ops.HigherOrderOperator):
        return target.cacheable()
    is_builtin_fun_or_type = type(target).__name__ == 'builtin_function_or_method'
    if is_builtin_fun_or_type:
        return True
    if is_safe_torch_function(target):
        return True
    function_name = f'{target.__module__}.{target.__name__}'
    if function_name in SAFE_NON_TORCH_FUNCTIONS:
        return True
    return False

def _take_2d_multi_object(arr: np.ndarray, indexer: tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]], out: np.ndarray, fill_value, mask_info) -> None:
    (row_idx, col_idx) = indexer
    if mask_info is not None:
        ((row_mask, col_mask), (row_needs, col_needs)) = mask_info
    else:
        row_mask = row_idx == -1
        col_mask = col_idx == -1
        row_needs = row_mask.any()
        col_needs = col_mask.any()
    if fill_value is not None:
        if row_needs:
            out[row_mask, :] = fill_value
        if <MASK>:
            out[:, col_mask] = fill_value
    for (i, u_) in enumerate(row_idx):
        if u_ != -1:
            for (j, v) in enumerate(col_idx):
                if v != -1:
                    out[i, j] = arr[u_, v]

def forward(self, X):
    if <MASK>:
        self.activation_post_process(X.detach())
        (_scale, _zero_point) = self.calculate_qparams()
        (_scale, _zero_point) = (_scale.to(self.scale.device), _zero_point.to(self.zero_point.device))
        if self.scale.shape != _scale.shape:
            self.scale.resize_(_scale.shape)
            self.zero_point.resize_(_zero_point.shape)
        self.scale.copy_(_scale)
        self.zero_point.copy_(_zero_point)
    if self.fake_quant_enabled[0] == 1:
        if self.is_per_channel:
            X = torch.fake_quantize_per_channel_affine(X, self.scale, self.zero_point, self.ch_axis, self.activation_post_process.quant_min, self.activation_post_process.quant_max)
        else:
            X = torch.fake_quantize_per_tensor_affine(X, self.scale, self.zero_point, self.activation_post_process.quant_min, self.activation_post_process.quant_max)
    return X

@compatibility(is_backward_compatible=True)
def delete_all_unused_submodules(self) -> None:
    """
        Deletes all unused submodules from ``self``.

        A Module is considered "used" if any one of the following is
        true:
        1. It has children that are used
        2. Its forward is called directly via a ``call_module`` node
        3. It has a non-Module attribute that is used from a
        ``get_attr`` node

        This method can be called to clean up an ``nn.Module`` without
        manually calling ``delete_submodule`` on each unused submodule.
        """
    used: list[str] = []
    for node in self.graph.nodes:
        if node.op == 'call_module' or node.op == 'get_attr':
            fullpath = node.target.split('.')

            def join_fn(x: str, y: str) -> str:
                return '.'.join([x, y] if y else [x])
            used.extend(itertools.accumulate(fullpath, join_fn))
            if <MASK>:
                try:
                    submod = self.get_submodule(node.target)
                    for (submod_name, _) in submod.named_modules():
                        if submod_name != '':
                            used.append('.'.join([node.target, submod_name]))
                except AttributeError:
                    pass
    to_delete = [name for (name, _) in self.named_modules() if name not in used]
    for name in to_delete:
        self.delete_submodule(name)

def test_impact_of_file(filename: str) -> str:
    """Determine what class of impact this file has on test runs.

    Possible values:
        TORCH - torch python code
        CAFFE2 - caffe2 python code
        TEST - torch test code
        UNKNOWN - may affect all tests
        NONE - known to have no effect on test outcome
        CI - CI configuration files
    """
    parts = filename.split(os.sep)
    if parts[0] in ['.jenkins', '.circleci', '.ci']:
        return 'CI'
    if <MASK>:
        return 'NONE'
    elif parts[0] == 'torch':
        if parts[-1].endswith('.py') or parts[-1].endswith('.pyi'):
            return 'TORCH'
    elif parts[0] == 'caffe2':
        if parts[-1].endswith('.py') or parts[-1].endswith('.pyi'):
            return 'CAFFE2'
    elif parts[0] == 'test':
        if parts[-1].endswith('.py') or parts[-1].endswith('.pyi'):
            return 'TEST'
    return 'UNKNOWN'

def __init__(self, mixture_distribution: Categorical, component_distribution: Distribution, validate_args: Optional[bool]=None) -> None:
    self._mixture_distribution = mixture_distribution
    self._component_distribution = component_distribution
    if not isinstance(self._mixture_distribution, Categorical):
        raise ValueError(' The Mixture distribution needs to be an  instance of torch.distributions.Categorical')
    if not isinstance(self._component_distribution, Distribution):
        raise ValueError('The Component distribution need to be an instance of torch.distributions.Distribution')
    mdbs = self._mixture_distribution.batch_shape
    cdbs = self._component_distribution.batch_shape[:-1]
    for (size1, size2) in zip(reversed(mdbs), reversed(cdbs)):
        if <MASK>:
            raise ValueError(f'`mixture_distribution.batch_shape` ({mdbs}) is not compatible with `component_distribution.batch_shape`({cdbs})')
    km = self._mixture_distribution.logits.shape[-1]
    kc = self._component_distribution.batch_shape[-1]
    if km is not None and kc is not None and (km != kc):
        raise ValueError(f'`mixture_distribution component` ({km}) does not equal `component_distribution.batch_shape[-1]` ({kc})')
    self._num_component = km
    event_shape = self._component_distribution.event_shape
    self._event_ndims = len(event_shape)
    super().__init__(batch_shape=cdbs, event_shape=event_shape, validate_args=validate_args)

def exception_handler(self, raised_exception: ObservedException) -> None:
    observed_exn_gb_explanation = 'Dynamo found no exception handler at the top-level compiled function when encountering an exception. Exception will propagate outside the compiled region.'

    def bubble_exception_to_interpreter() -> None:
        curr_exc = self.exn_vt_stack.get_current_exception()
        dynamo_exc = exc.get_dynamo_observed_exception(curr_exc.python_type())
        assert isinstance(raised_exception, dynamo_exc)
        unimplemented_v2(gb_type='Observed exception', context=f'raised exception {curr_exc.python_type_name()}({curr_exc.args})', explanation=observed_exn_gb_explanation, hints=[*graph_break_hints.USER_ERROR, *graph_break_hints.SUPPORTABLE], from_exc=raised_exception)
    if sys.version_info >= (3, 11):
        exn_tab_entry = self.current_instruction.exn_tab_entry
        if exn_tab_entry:
            while len(self.stack) > exn_tab_entry.depth:
                self.pop()
            if <MASK>:
                self.push(variables.ConstantVariable(self.current_instruction.offset))
            self.push(self.exn_vt_stack.get_current_exception())
            self.jump(exn_tab_entry)
        else:
            self.stack.clear()
            if type(self) is InstructionTranslator:
                bubble_exception_to_interpreter()
            raise raised_exception
    elif len(self.block_stack):
        block_stack_entry = self.block_stack.pop()
        while block_stack_entry.inst.opname == 'EXCEPT_HANDLER':
            self.popn(3)
            self.exn_vt_stack.pop()
            if len(self.block_stack) == 0:
                self.stack.clear()
                if type(self) is InstructionTranslator:
                    unimplemented_v2(gb_type='Observed exception (EXCEPT_HANDLER)', context=str(raised_exception), explanation=observed_exn_gb_explanation + ' This graph break is unexpected.', hints=[*graph_break_hints.DYNAMO_BUG])
                raise raised_exception
            block_stack_entry = self.block_stack.pop()
        exception_var = self.exn_vt_stack.get_current_exception()
        self.exn_vt_stack.move_current_exception_to_stack()
        while len(self.stack) > block_stack_entry.stack_index:
            self.pop()
        except_handler_inst = Instruction(1000000.0, 'EXCEPT_HANDLER', None, 0)
        self.block_stack.append(BlockStackEntry(except_handler_inst, None, len(self.stack)))
        if len(self.exn_vt_stack) >= 2:
            old_exception = self.exn_vt_stack[-2]
            self.push(variables.UnknownVariable())
            self.push(old_exception)
            self.push(variables.BuiltinVariable(old_exception.exc_type))
        else:
            self.push(variables.ConstantVariable(None))
            self.push(variables.ConstantVariable(None))
            self.push(variables.ConstantVariable(None))
        self.push(variables.UnknownVariable())
        self.push(exception_var)
        self.push(variables.BuiltinVariable(exception_var.exc_type))
        self.jump(block_stack_entry)
    else:
        self.stack.clear()
        if type(self) is InstructionTranslator:
            bubble_exception_to_interpreter()
        raise raised_exception

def _detect_function_free_vars(fn):
    """Detect free vars in any Python function."""
    assert isinstance(fn, types.FunctionType) or isinstance(fn, types.MethodType), f'The input should be of Python function type. Got type: {type(fn)}.'
    queue = collections.deque([fn])
    fn_map = dict()
    while queue:
        obj = queue.popleft()
        signature = _make_callable_signature(obj)
        if signature not in fn_map:
            free_vars = _search_callable_free_vars(obj)
            if not free_vars:
                continue
            fn_map[signature] = free_vars
            for var in free_vars:
                if var.is_function:
                    obj = var.obj
                    if <MASK>:
                        queue.append(obj)
    return fn_map

def _floatify_na_values(na_values) -> set[float]:
    result = set()
    for v in na_values:
        try:
            v = float(v)
            if <MASK>:
                result.add(v)
        except (TypeError, ValueError, OverflowError):
            pass
    return result

def _prim_elementwise_meta(*args, type_promotion: ELEMENTWISE_PRIM_TYPE_PROMOTION_KIND, args_with_fixed_dtypes: Optional[tuple[TensorLikeType, ...]]=None) -> FakeTensor:
    """
    Meta function for elementwise operations that produce outputs in the same dtype
    as their inputs.

    Stride logic is currently incorrect.
    """
    assert len(args) > 0
    utils.check_same_dtype(*args)
    args_ = list(args)
    if args_with_fixed_dtypes is not None:
        args_ = list(args_with_fixed_dtypes) + args_
    utils.check_same_device(*args_, allow_cpu_scalar_tensors=True)
    utils.check_same_shape(*args_, allow_cpu_scalar_tensors=True)
    (l2p_perm, _) = utils.compute_elementwise_output_logical_to_physical_perm(*args_)
    shape = utils.extract_shape(*args_, allow_cpu_scalar_tensors=True)
    dtype = None
    scalar_type = None
    for arg in args:
        if isinstance(arg, TensorLike):
            if not utils.is_cpu_scalar_tensor(arg):
                dtype = arg.dtype
                break
            else:
                dtype = arg.dtype
        elif isinstance(arg, Number):
            scalar_type = type(arg)
    if dtype is None and scalar_type is not None:
        dtype = utils.type_to_dtype(scalar_type)
    device = None
    number = None
    for arg in args_:
        if isinstance(arg, TensorLike):
            if utils.is_cpu_scalar_tensor(arg):
                if device is None:
                    device = arg.device
            else:
                device = arg.device
                break
        elif isinstance(arg, Number):
            if number is None:
                number = arg
    if device is not None:
        assert dtype is not None
        if type_promotion == ELEMENTWISE_PRIM_TYPE_PROMOTION_KIND.ALWAYS_BOOL:
            dtype = torch.bool
        elif <MASK>:
            if utils.is_integer_dtype(dtype) or utils.is_boolean_dtype(dtype):
                dtype = torch.get_default_dtype()
        elif type_promotion == ELEMENTWISE_PRIM_TYPE_PROMOTION_KIND.COMPLEX_TO_FLOAT:
            if utils.is_complex_dtype(dtype):
                dtype = utils.corresponding_real_dtype(dtype)
        assert shape is not None
        return torch.empty_permuted(shape, l2p_perm, device=device, dtype=dtype)
    seen_float = False
    if isinstance(number, (torch.SymInt, torch.SymFloat)):
        for a in args:
            assert isinstance(a, (int, float, torch.SymInt, torch.SymFloat)), 'NYI'
            seen_float = seen_float or isinstance(a, (float, torch.SymFloat))
        if seen_float:
            number = sym_float(number)
    return TensorMeta(number)

def __init__(self, param_grid):
    if <MASK>:
        raise TypeError(f'Parameter grid should be a dict or a list, got: {param_grid!r} of type {type(param_grid).__name__}')
    if isinstance(param_grid, Mapping):
        param_grid = [param_grid]
    for grid in param_grid:
        if not isinstance(grid, dict):
            raise TypeError(f'Parameter grid is not a dict ({grid!r})')
        for (key, value) in grid.items():
            if isinstance(value, np.ndarray) and value.ndim > 1:
                raise ValueError(f'Parameter array for {key!r} should be one-dimensional, got: {value!r} with shape {value.shape}')
            if isinstance(value, str) or not isinstance(value, (np.ndarray, Sequence)):
                raise TypeError(f'Parameter grid for parameter {key!r} needs to be a list or a numpy array, but got {value!r} (of type {type(value).__name__}) instead. Single values need to be wrapped in a list with one element.')
            if len(value) == 0:
                raise ValueError(f'Parameter grid for parameter {key!r} need to be a non-empty sequence, got: {value!r}')
    self.param_grid = param_grid

def spawn(cmd):
    src_regex = re.compile('/T(p|c)(.*)')
    src_list = [m.group(2) for m in (src_regex.match(elem) for elem in cmd) if m]
    obj_regex = re.compile('/Fo(.*)')
    obj_list = [m.group(1) for m in (obj_regex.match(elem) for elem in cmd) if m]
    include_regex = re.compile('((\\-|\\/)I.*)')
    include_list = [m.group(1) for m in (include_regex.match(elem) for elem in cmd) if m]
    if <MASK>:
        src = src_list[0]
        obj = obj_list[0]
        if _is_cuda_file(src):
            if IS_HIP_EXTENSION:
                nvcc = _get_hipcc_path()
            else:
                nvcc = _join_cuda_home('bin', 'nvcc')
            if isinstance(self.cflags, dict):
                cflags = self.cflags['nvcc']
            elif isinstance(self.cflags, list):
                cflags = self.cflags
            else:
                cflags = []
            if IS_HIP_EXTENSION:
                cflags = win_hip_flags(cflags)
            else:
                cflags = win_cuda_flags(cflags) + ['-std=c++17', '--use-local-env']
                for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                    cflags = ['-Xcudafe', '--diag_suppress=' + ignore_warning] + cflags
            for flag in COMMON_MSVC_FLAGS:
                cflags = ['-Xcompiler', flag] + cflags
            cmd = [nvcc, '-c', src, '-o', obj] + include_list + cflags
        elif isinstance(self.cflags, dict):
            cflags = COMMON_MSVC_FLAGS + self.cflags['cxx']
            append_std17_if_no_std_present(cflags)
            cmd += cflags
        elif isinstance(self.cflags, list):
            cflags = COMMON_MSVC_FLAGS + self.cflags
            append_std17_if_no_std_present(cflags)
            cmd += cflags
    return original_spawn(cmd)

def standardize_weights(y, sample_weight=None, class_weight=None, sample_weight_mode=None):
    """Performs sample weight validation and standardization.

  Everything gets normalized to a single sample-wise (or timestep-wise)
  weight array. If both `sample_weight` and `class_weight` are provided,
  the weights are multiplied.

  Args:
      y: Numpy array or Tensor of model targets to be weighted.
      sample_weight: User-provided `sample_weight` argument.
      class_weight: User-provided `class_weight` argument.
      sample_weight_mode: One of `None` or `"temporal"`. `"temporal"` indicated
        that we expect 2D weight data that will be applied to the last 2
        dimensions of the targets (i.e. we are weighting timesteps, not
        samples).

  Returns:
      A numpy array of target weights, one entry per sample to weight.

  Raises:
      ValueError: In case of invalid user-provided arguments.
  """
    if isinstance(sample_weight, tuple):
        sample_weight = sample_weight[0]
    if sample_weight_mode is not None and sample_weight_mode != 'samplewise':
        if sample_weight_mode != 'temporal':
            raise ValueError('"sample_weight_mode should be None or "temporal". Found: ' + str(sample_weight_mode))
        if len(y.shape) < 3:
            raise ValueError('Found a sample_weight array for an input with shape ' + str(y.shape) + '. Timestep-wise sample weighting (use of sample_weight_mode="temporal") is restricted to outputs that are at least 3D, i.e. that have a time dimension.')
        if sample_weight is not None and len(sample_weight.shape) != 2:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + '. In order to use timestep-wise sample weighting, you should pass a 2D sample_weight array.')
    elif sample_weight is not None and len(sample_weight.shape) != 1:
        raise ValueError('Found a sample_weight array with shape {}. In order to use timestep-wise sample weights, you should specify sample_weight_mode="temporal" in compile(); founssd "{}" instead. If you just mean to use sample-wise weights, make sure your sample_weight array is 1D.'.format(sample_weight.shape, sample_weight_mode))
    if sample_weight is not None:
        if len(sample_weight.shape) > len(y.shape):
            raise ValueError('Found a sample_weight with shape' + str(sample_weight.shape) + '.Expected sample_weight with rank less than or equal to ' + str(len(y.shape)))
        if not tensor_util.is_tf_type(sample_weight) and y.shape[:sample_weight.ndim] != sample_weight.shape:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + ' for an input with shape ' + str(y.shape) + '. sample_weight cannot be broadcast.')
    class_sample_weight = None
    if isinstance(class_weight, dict):
        if len(y.shape) > 2:
            raise ValueError('`class_weight` not supported for 3+ dimensional targets.')
        if <MASK>:
            keys = np.array(sorted(class_weight.keys()))
            values = np.array([class_weight[i] for i in keys])
            weight_vector = np.zeros(np.max(keys) + 1)
            weight_vector[:] = np.nan
            weight_vector[keys] = values
            y_classes = smart_cond.smart_cond(len(y.shape.as_list()) == 2 and backend.shape(y)[1] > 1, lambda : backend.argmax(y, axis=1), lambda : math_ops.cast(backend.reshape(y, (-1,)), dtypes.int64))
            class_sample_weight = array_ops.gather(weight_vector, y_classes)
            gen_array_ops.check_numerics(class_sample_weight, 'Invalid classes or class weights detected. NaN values indicate that an appropriate class weight could not be determined.')
            class_sample_weight = math_ops.cast(class_sample_weight, backend.floatx())
            if sample_weight is not None:
                sample_weight = math_ops.cast(tensor_conversion.convert_to_tensor_v2_with_dispatch(sample_weight), backend.floatx())
        else:
            y_classes = y
            if len(y.shape) == 2:
                if y.shape[1] > 1:
                    y_classes = np.argmax(y, axis=1)
                elif y.shape[1] == 1:
                    y_classes = np.reshape(y, y.shape[0])
            class_sample_weight = numpy_compat.np_asarray([class_weight[cls] for cls in y_classes if cls in class_weight])
            if len(class_sample_weight) != len(y_classes):
                existing_classes = set(y_classes)
                existing_class_weight = set(class_weight.keys())
                raise ValueError('`class_weight` must contain all classes in the data. The classes %s exist in the data but not in `class_weight`.' % (existing_classes - existing_class_weight))
    if class_sample_weight is not None and sample_weight is not None:
        return class_sample_weight * sample_weight
    if sample_weight is not None:
        return sample_weight
    if class_sample_weight is not None:
        return class_sample_weight
    return None

def normalizer(_func=None, *, promote_scalar_result=False):

    def normalizer_inner(func):

        @functools.wraps(func)
        def wrapped(*args, **kwds):
            sig = inspect.signature(func)
            params = sig.parameters
            first_param = next(iter(params.values()))
            if first_param.kind == inspect.Parameter.VAR_POSITIONAL:
                args = [maybe_normalize(arg, first_param) for arg in args]
            else:
                args = tuple((maybe_normalize(arg, parm) for (arg, parm) in zip(args, params.values()))) + args[len(params.values()):]
            kwds = {name: maybe_normalize(arg, params[name]) if name in params else arg for (name, arg) in kwds.items()}
            result = func(*args, **kwds)
            bound_args = None
            if 'keepdims' in params and params['keepdims'].annotation == 'KeepDims':
                bound_args = sig.bind(*args, **kwds).arguments
                if <MASK>:
                    tensor = args[0]
                    axis = bound_args.get('axis')
                    result = _util.apply_keepdims(result, axis, tensor.ndim)
            if 'out' in params:
                if bound_args is None:
                    bound_args = sig.bind(*args, **kwds).arguments
                out = bound_args.get('out')
                result = maybe_copy_to(out, result, promote_scalar_result)
            result = wrap_tensors(result)
            return result
        return wrapped
    if _func is None:
        return normalizer_inner
    else:
        return normalizer_inner(_func)

@register_graph_pattern(CallFunctionVarArgs(aten.rand.default), pass_dict=patterns)
@register_graph_pattern(CallFunctionVarArgs(aten.rand.generator), pass_dict=patterns)
@register_graph_pattern(CallFunctionVarArgs(aten.randn.default), pass_dict=patterns)
@register_graph_pattern(CallFunctionVarArgs(aten.randn.generator), pass_dict=patterns)
def replace_random(match: Match, size, *, generator=None, dtype=None, device=None, layout=None, pin_memory=None):
    if generator is not None:
        return

    def replacement(size):
        result = inductor_prims.random(size, inductor_prims.seed(device), mode, **default_kwargs(device))
        if <MASK>:
            result = result.to(dtype)
        return result
    mode = {aten.rand: 'rand', aten.randn: 'randn'}[match.output_node().target.overloadpacket]
    device = get_device(device)
    match.replace_by_example(replacement, [size])

def __init__(self, filepath_or_buffer, storage_options: StorageOptions | None=None, engine_kwargs: dict | None=None) -> None:
    if engine_kwargs is None:
        engine_kwargs = {}
    self.handles = IOHandles(handle=filepath_or_buffer, compression={'method': None})
    if <MASK>:
        self.handles = get_handle(filepath_or_buffer, 'rb', storage_options=storage_options, is_text=False)
    if isinstance(self.handles.handle, self._workbook_class):
        self.book = self.handles.handle
    elif hasattr(self.handles.handle, 'read'):
        self.handles.handle.seek(0)
        try:
            self.book = self.load_workbook(self.handles.handle, engine_kwargs)
        except Exception:
            self.close()
            raise
    else:
        raise ValueError('Must explicitly set engine if not passing in buffer or path for io.')

def sql_flush(self, style, tables, *, reset_sequences=False, allow_cascade=False):
    if <MASK>:
        return []
    sql_parts = [style.SQL_KEYWORD('TRUNCATE'), ', '.join((style.SQL_FIELD(self.quote_name(table)) for table in tables))]
    if reset_sequences:
        sql_parts.append(style.SQL_KEYWORD('RESTART IDENTITY'))
    if allow_cascade:
        sql_parts.append(style.SQL_KEYWORD('CASCADE'))
    return ['%s;' % ' '.join(sql_parts)]

def _process_tensorlike(inputs):
    """Process tensor-like inputs.

  This function:

  (1) Converts `Numpy` arrays to `Tensor`s.
  (2) Converts `Scipy` sparse matrices to `SparseTensor`s.
  (2) Converts `list`s to `tuple`s (for `tf.data` support).

  Args:
    inputs: Structure of `Tensor`s, `NumPy` arrays, or tensor-like.

  Returns:
    Structure of `Tensor`s or tensor-like.
  """

    def _convert_numpy_and_scipy(x):
        if <MASK>:
            dtype = None
            if issubclass(x.dtype.type, np.floating):
                dtype = backend.floatx()
            return tensor_conversion.convert_to_tensor_v2_with_dispatch(x, dtype=dtype)
        elif _is_scipy_sparse(x):
            return _scipy_sparse_to_sparse_tensor(x)
        return x
    inputs = nest.map_structure(_convert_numpy_and_scipy, inputs)
    return nest.list_to_tuple(inputs)

def copy_tensor(composite_tensor_obj):
    """Copy a remote tensor to local (coordinator)."""
    if <MASK>:
        return composite_tensor_obj
    with ops.device('/job:%s' % context.get_server_def().job_name):
        return array_ops.identity(composite_tensor_obj)

def doTestBasic(self, use_locking=False, use_resource=False, use_callable_params=False):
    for dtype in [dtypes.half, dtypes.float32, dtypes.float64]:
        if use_resource:
            var0 = resource_variable_ops.ResourceVariable([1.0, 2.0], dtype=dtype)
            var1 = resource_variable_ops.ResourceVariable([3.0, 4.0], dtype=dtype)
        else:
            var0 = variables.Variable([1.0, 2.0], dtype=dtype)
            var1 = variables.Variable([3.0, 4.0], dtype=dtype)
        grads0 = constant_op.constant([0.1, 0.1], dtype=dtype)
        grads1 = constant_op.constant([0.01, 0.01], dtype=dtype)
        learning_rate = lambda : 3.0
        if <MASK>:
            learning_rate = learning_rate()
        ada_opt = adagrad.AdagradOptimizer(learning_rate, initial_accumulator_value=0.1, use_locking=use_locking)
        if not context.executing_eagerly():
            ada_update = ada_opt.apply_gradients(zip([grads0, grads1], [var0, var1]))
            self.evaluate(variables.global_variables_initializer())
        (v0_val, v1_val) = self.evaluate([var0, var1])
        self.assertAllClose([1.0, 2.0], v0_val)
        self.assertAllClose([3.0, 4.0], v1_val)
        for _ in range(3):
            if not context.executing_eagerly():
                self.evaluate(ada_update)
            else:
                ada_opt.apply_gradients(zip([grads0, grads1], [var0, var1]))
        (v0_val, v1_val) = self.evaluate([var0, var1])
        self.assertAllCloseAccordingToType(np.array([-1.6026098728179932, -0.6026098728179932]), v0_val)
        self.assertAllCloseAccordingToType(np.array([2.715679168701172, 3.715679168701172]), v1_val)

def filter_op(self, op_info: InductorROCmOp):
    """
        Determines whether a given op definition is suitable for the current
        input / output of the operation that this template implements.

        Filter is based on inputs' dtype, layout and statically inferred size.

        Returns None if the op is not suitable, otherwise returns the op to be used.
        """
    (op, kBatch) = (op_info.op, op_info.kBatch)
    metas = [T.get_layout() for T in [*self.input_nodes, self.output_node]]
    X_meta = metas[0]
    W_meta = metas[1]
    Y_meta = metas[-1]
    if op.a_element_dtype != self._TORCH_DTYPE_TO_CK[X_meta.dtype]:
        return None
    if op.b_element_dtype != self._TORCH_DTYPE_TO_CK[W_meta.dtype]:
        return None
    if op.c_element_dtype != self._TORCH_DTYPE_TO_CK[Y_meta.dtype]:
        return None
    if <MASK>:
        return None
    if op.b_layout != torch_layout_to_ck_layout(W_meta):
        return None
    if op.c_layout != torch_layout_to_ck_layout(Y_meta):
        return None
    M = X_meta.size[-2]
    K = X_meta.size[-1]
    N = W_meta.size[-1]
    if is_static_int(M):
        if not self._has_padding('M', op.gemm_specialization):
            if M % op.m_per_block != 0:
                return None
    if is_static_int(N):
        if not self._has_padding('N', op.gemm_specialization):
            if N % op.n_per_block != 0:
                return None
    if is_static_int(K):
        if not self._has_padding('K', op.gemm_specialization):
            if K % op.k_per_block != 0:
                return None
            K_t = kBatch * op.k_per_block
            if K % K_t != 0:
                return None
        else:
            lcm = abs(op.a_k1 * op.b_k1) // math.gcd(op.a_k1, op.b_k1)
            K_t = kBatch * lcm
            k_read_pad_splited = math.ceil(K / K_t) * lcm
            if k_read_pad_splited * (kBatch - 1) >= K:
                return None
    a_contig_size = K if op.a_layout == 'Row' else M if op.a_layout == 'Col' else None
    if is_static_int(a_contig_size) and a_contig_size % op.a_block_transfer_src_scalar_per_vector != 0:
        return None
    b_contig_size = N if op.b_layout == 'Row' else K if op.b_layout == 'Col' else None
    if is_static_int(b_contig_size) and b_contig_size % op.b_block_transfer_src_scalar_per_vector != 0:
        return None
    c_contig_size = N if op.c_layout == 'Row' else M if op.c_layout == 'Col' else None
    c_shuffle_block_transfer_scalar_per_vector_n_per_block = op.c_shuffle_block_transfer_scalar_per_vector_n_per_block[0] if isinstance(op.c_shuffle_block_transfer_scalar_per_vector_n_per_block, tuple) else op.c_shuffle_block_transfer_scalar_per_vector_n_per_block
    if is_static_int(c_contig_size) and c_contig_size % c_shuffle_block_transfer_scalar_per_vector_n_per_block != 0:
        return None
    if not self._check_num_k_loops(op, kBatch):
        return None
    return op

@out_wrapper(exact_dtype=True)
def matrix_norm(A: TensorLikeType, ord: Union[float, str]='fro', dim: DimsType=(-2, -1), keepdim: bool=False, *, dtype: Optional[torch.dtype]=None) -> TensorLikeType:
    check_is_matrix(A, 'linalg.matrix_norm')
    dim = utils.canonicalize_dims(A.ndim, dim)
    if isinstance(dim, Dim):
        dim = (dim,)
    torch._check(len(dim) == 2, lambda : f'linalg.matrix_norm: dim must be a 2-tuple. Got {dim}')
    torch._check(dim[0] != dim[1], lambda : f'linalg.matrix_norm: dims must be different. Got ({dim[0]}, {dim[1]})')
    _check_norm_dtype(dtype, A.dtype, 'linalg.matrix_norm')
    if <MASK>:
        torch._check(ord in ('fro', 'nuc'), lambda : f'linalg.matrix_norm: Order {ord} not supported.')
        check_fp_or_complex(A.dtype, 'linalg.matrix_norm', allow_low_precision_dtypes=ord != 'nuc')
        if ord == 'fro':
            return vector_norm(A, 2, dim, keepdim, dtype=dtype)
        else:
            if dtype is not None:
                A = _maybe_convert_to_dtype(A, dtype)
            perm = _backshift_permutation(dim[0], dim[1], A.ndim)
            result = torch.sum(svdvals(prims.transpose(A, perm)), -1, keepdim)
            if keepdim:
                inv_perm = _inverse_permutation(perm)
                result = prims.transpose(torch.unsqueeze(result, -1), inv_perm)
            return result
    else:
        abs_ord = abs(ord)
        torch._check(abs_ord in (2, 1, float('inf')), lambda : f'linalg.matrix_norm: Order {ord} not supported.')
        check_fp_or_complex(A.dtype, 'linalg.matrix_norm', allow_low_precision_dtypes=ord != 2)
        max_min = partial(torch.amax if ord > 0.0 else torch.amin, keepdim=keepdim)
        if abs_ord == 2.0:
            if dtype is not None:
                A = _maybe_convert_to_dtype(A, dtype)
            perm = _backshift_permutation(dim[0], dim[1], A.ndim)
            result = max_min(svdvals(prims.transpose(A, perm)), dim=-1)
            if keepdim:
                inv_perm = _inverse_permutation(perm)
                result = prims.transpose(torch.unsqueeze(result, -1), inv_perm)
            return result
        else:
            (dim0, dim1) = dim
            if abs_ord == float('inf'):
                (dim0, dim1) = (dim1, dim0)
            if not keepdim and dim0 < dim1:
                dim1 -= 1
            return max_min(vector_norm(A, 1.0, dim=dim0, keepdim=keepdim, dtype=dtype), dim1)

@contextlib.contextmanager
def _enable(compiler_fn: Callable[..., Any], dynamic: bool=True, ignore_active_disable_ctx: bool=True) -> Generator[None, None, None]:
    if <MASK>:
        yield
    else:
        if dynamic:
            assert type(dynamic) is bool
        from torch._dynamo import eval_frame
        if eval_frame._stance.stance == 'force_eager':
            global compiled_autograd_enabled_force_eager
            compiled_autograd_enabled_force_eager = True
            try:
                yield
            finally:
                compiled_autograd_enabled_force_eager = False
        else:
            if torch.cuda.is_available():
                from torch._inductor import cudagraph_trees
            (prior_compiler, prior_dynamic) = torch._C._dynamo.compiled_autograd.set_autograd_compiler(functools.partial(AutogradCompilerInstance, compiler_fn), dynamic)
            if snapshot_verbose_logging_enabled():
                torch._C._dynamo.compiled_autograd.set_verbose_logger(verbose_log)
            global compiled_autograd_enabled
            compiled_autograd_enabled = True
            global depth
            prior_depth = depth
            depth += 1
            try:
                with torch.autograd.set_multithreading_enabled(False):
                    yield
            finally:
                if not prior_compiler:
                    compiled_autograd_enabled = False
                torch._C._dynamo.compiled_autograd.set_autograd_compiler(prior_compiler, prior_dynamic)
                depth -= 1
                assert depth == prior_depth, 'Nested Compiled Autograd Contexts must return before their parent context'

