def _convert_container(container, constructor_name, columns_name=None, dtype=None, minversion=None, categorical_feature_names=None):
    """Convert a given container to a specific array-like with a dtype.

    Parameters
    ----------
    container : array-like
        The container to convert.
    constructor_name : {"list", "tuple", "array", "sparse", "dataframe",             "pandas", "series", "index", "slice", "sparse_csr", "sparse_csc",             "sparse_csr_array", "sparse_csc_array", "pyarrow", "polars",             "polars_series"}
        The type of the returned container.
    columns_name : index or array-like, default=None
        For pandas/polars container supporting `columns_names`, it will affect
        specific names.
    dtype : dtype, default=None
        Force the dtype of the container. Does not apply to `"slice"`
        container.
    minversion : str, default=None
        Minimum version for package to install.
    categorical_feature_names : list of str, default=None
        List of column names to cast to categorical dtype.

    Returns
    -------
    converted_container
    """
    if constructor_name == 'list':
        if dtype is None:
            return list(container)
        else:
            return np.asarray(container, dtype=dtype).tolist()
    elif constructor_name == 'tuple':
        if dtype is None:
            return tuple(container)
        else:
            return tuple(np.asarray(container, dtype=dtype).tolist())
    elif constructor_name == 'array':
        return np.asarray(container, dtype=dtype)
    elif constructor_name in ('pandas', 'dataframe'):
        pd = pytest.importorskip('pandas', minversion=minversion)
        result = pd.DataFrame(container, columns=columns_name, dtype=dtype, copy=False)
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result[col_name] = result[col_name].astype('category')
        return result
    elif constructor_name == 'pyarrow':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        array = np.asarray(container)
        array = array[:, None] if array.ndim == 1 else array
        if columns_name is None:
            columns_name = [f'col{i}' for i in range(array.shape[1])]
        data = {name: array[:, i] for (i, name) in enumerate(columns_name)}
        result = pa.Table.from_pydict(data)
        if categorical_feature_names is not None:
            for (col_idx, col_name) in enumerate(result.column_names):
                if col_name in categorical_feature_names:
                    result = result.set_column(col_idx, col_name, result.column(col_name).dictionary_encode())
        return result
    elif constructor_name == 'polars':
        pl = pytest.importorskip('polars', minversion=minversion)
        result = pl.DataFrame(container, schema=columns_name, orient='row')
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result = result.with_columns(pl.col(col_name).cast(pl.Categorical))
        return result
    elif <MASK>:
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Series(container, dtype=dtype)
    elif constructor_name == 'pyarrow_array':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        return pa.array(container)
    elif constructor_name == 'polars_series':
        pl = pytest.importorskip('polars', minversion=minversion)
        return pl.Series(values=container)
    elif constructor_name == 'index':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Index(container, dtype=dtype)
    elif constructor_name == 'slice':
        return slice(container[0], container[1])
    elif 'sparse' in constructor_name:
        if not sp.sparse.issparse(container):
            container = np.atleast_2d(container)
        if constructor_name in ('sparse', 'sparse_csr'):
            return sp.sparse.csr_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csr_array':
            return sp.sparse.csr_array(container, dtype=dtype)
        elif constructor_name == 'sparse_csc':
            return sp.sparse.csc_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csc_array':
            return sp.sparse.csc_array(container, dtype=dtype)

def formfield_for_manytomany(self, db_field, request, **kwargs):
    """
        Get a form Field for a ManyToManyField.
        """
    if not db_field.remote_field.through._meta.auto_created:
        return None
    db = kwargs.get('using')
    if 'widget' not in kwargs:
        autocomplete_fields = self.get_autocomplete_fields(request)
        if db_field.name in autocomplete_fields:
            kwargs['widget'] = AutocompleteSelectMultiple(db_field, self.admin_site, using=db)
        elif db_field.name in self.raw_id_fields:
            kwargs['widget'] = widgets.ManyToManyRawIdWidget(db_field.remote_field, self.admin_site, using=db)
        elif db_field.name in [*self.filter_vertical, *self.filter_horizontal]:
            kwargs['widget'] = widgets.FilteredSelectMultiple(db_field.verbose_name, db_field.name in self.filter_vertical)
    if 'queryset' not in kwargs:
        queryset = self.get_field_queryset(db, db_field, request)
        if <MASK>:
            kwargs['queryset'] = queryset
    form_field = db_field.formfield(**kwargs)
    if isinstance(form_field.widget, SelectMultiple) and form_field.widget.allow_multiple_selected and (not isinstance(form_field.widget, (CheckboxSelectMultiple, AutocompleteSelectMultiple))):
        msg = _('Hold down “Control”, or “Command” on a Mac, to select more than one.')
        help_text = form_field.help_text
        form_field.help_text = format_lazy('{} {}', help_text, msg) if help_text else msg
    return form_field

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name == '__setattr__':
        return super().call_method(tx, name, args, kwargs)
    elif name == 'mark_non_differentiable':
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        self.non_differentiable = proxy_args_kwargs(args, {})[0]
        return variables.ConstantVariable.create(None)
    if name != 'save_for_backward':
        unimplemented_v2(gb_type='Unsupported autograd.Function context method', context=f'call_method {self} {name}', explanation=f'Dynamo does not support calling the method `{name}` on `autograd.Function` context objects. Supported methods are `__setattr__`, `save_for_backward` and `mark_non_differentiable`.', hints=[*graph_break_hints.SUPPORTABLE])
    if <MASK>:
        unimplemented_v2(gb_type='Unsupported autograd.Function context `save_for_backward`', context=f'call_method {self} {name}', explanation='Dynamo requires the `saved_tensors` attribute to be initialized on the `autograd.Function` context object.', hints=['Ensure that the `saved_tensors` attribute is properly initialized before calling `save_for_backward`. `save_for_backward` only supported on a newly constructed `torch.autograd.function.FunctionCtx`.'])
    if not self.inference:
        if kwargs or not self.source:
            raise_type_error_exc(tx, 'save_for_backward() requires a source and no keyword arguments')
        tx.output.side_effects.track_save_for_backward(self, args)
    if len(self.saved_tensors.tensors) > 0:
        self.saved_tensors.tensors = []
    for arg in args:
        self.saved_tensors.tensors.append(arg)
    return variables.ConstantVariable.create(None)

def _detect_function_free_vars(fn):
    """Detect free vars in any Python function."""
    assert isinstance(fn, types.FunctionType) or isinstance(fn, types.MethodType), f'The input should be of Python function type. Got type: {type(fn)}.'
    queue = collections.deque([fn])
    fn_map = dict()
    while queue:
        obj = queue.popleft()
        signature = _make_callable_signature(obj)
        if signature not in fn_map:
            free_vars = _search_callable_free_vars(obj)
            if <MASK>:
                continue
            fn_map[signature] = free_vars
            for var in free_vars:
                if var.is_function:
                    obj = var.obj
                    if _make_callable_signature(obj) not in fn_map:
                        queue.append(obj)
    return fn_map

