def stride(self, node: IRNode, index: int, default_value: int=0) -> str:
    """
        Hook called from template code to get the stride of an arg.
        Generates code which represents stride of a given node at index.
        If node is None, returns default_value.

        TODO: Will add needed args to pass it in if it is dynamic.
        """
    if node is None:
        return str(default_value)
    index = _normalize_idx(index, len(node.get_size()))
    if index < 0:
        return str(default_value)
    stride = node.get_stride()[index]
    if <MASK>:
        return str(stride)
    return self.find_symbol(node, 'stride', dim=index) or str(stride)

def _walk_fields(proto: message.Message, fields: FieldTypes):
    """Yields fields in a proto.

  Args:
    proto: Parent proto of any message type.
    fields: List of string/int/map key fields, e.g. ["nodes", "attr", "value"]
      can represent `proto.nodes.attr["value"]`.

  Yields:
    Tuple of (
      Field in the proto or `None` if none are found,
      Field descriptor,
      Key into this map field (or None),
      Index into this repeated field (or None))
  """
    if not isinstance(fields, list):
        fields = [fields]
    field_proto = proto
    parent_desc = proto.DESCRIPTOR
    i = 0
    while i < len(fields):
        field = fields[i]
        field_desc = None
        map_key = None
        index = None
        if parent_desc is None:
            raise ValueError(f'Unable to find fields: {fields} in proto of type {type(proto)}.')
        if <MASK>:
            try:
                field_desc = parent_desc.fields_by_number[field]
            except KeyError:
                raise KeyError(f'Unable to find field number {field} in {parent_desc.full_name}. Valid field numbers: {parent_desc.fields_by_number.keys()}')
        elif isinstance(field, str):
            try:
                field_desc = parent_desc.fields_by_name[field]
            except KeyError:
                raise KeyError(f"Unable to find field '{field}' in {parent_desc.full_name}. Valid field names: {parent_desc.fields_by_name.keys()}")
        else:
            raise TypeError('Unexpected bool found in field list.')
        i += 1
        parent_desc = field_desc.message_type
        if field_proto is not None:
            field_proto = getattr(field_proto, field_desc.name)
        if _is_map(parent_desc) and i < len(fields):
            map_key = fields[i]
            try:
                field_proto = field_proto[map_key] if field_proto is not None else None
            except KeyError:
                field_proto = None
            i += 1
            if i < len(fields):
                value_desc = parent_desc.fields_by_name['value']
                assert value_desc.message_type is not None
                parent_desc = value_desc.message_type
        elif is_repeated(field_desc) and i < len(fields):
            index = fields[i]
            try:
                field_proto = field_proto[index] if field_proto is not None else None
            except IndexError:
                field_proto = None
            i += 1
        yield (field_proto, field_desc, map_key, index)

