        elif func is torch.ops.c10d.recv_.default:
            return _c10d._local_recv_(*args, **kwargs)
        elif func is torch.ops.c10d.recv_any_source_.default:
            return _c10d._local_recv_any_source_(*args, **kwargs)
        raise NotImplementedError(f'{func} not implemented')
    if func.namespace == '_c10d_functional' or func.namespace == '_dtensor':
        with LocalTensorMode(self.ranks):
            return func._op_dk(DispatchKey.CompositeExplicitAutograd, *args, **kwargs)
    if func.namespace == 'profiler':
        return func(*args, **kwargs)
    if func.namespace == '_c10d_functional_autograd':
        raise NotImplementedError(f'{func} not implemented')
    if func.namespace == 'symm_mem':
        raise NotImplementedError(f'{func} not implemented')
    return _for_each_rank_run_func(func, self.ranks, args, kwargs, alias=True)

def _load_csv(self, filename: str, format: str='compute_only'):
    """Loads a csv in simple format and then lowers it to include communication actions

        format must be either "compute_only" or "compute_comms".  If compute_only, the lowering passes
        will automatically be run to generate a compute_comms schedule.
        """
    if format == 'compute_only':
        super()._load_csv(filename)
        self._prepare_schedule_with_comms(self.pipeline_order)
    elif <MASK>:
        actions = {}
        with open(filename, newline='') as csvfile:
            reader = csv.reader(csvfile)
            for (rank, row) in enumerate(reader):
                actions[rank] = [_Action.from_str(s) for s in row]
            self._prepare_schedule_with_comms(actions, format=format)
    else:
        raise NotImplementedError(f'format={format!r} is not implemented')

def gen_class_set_output_body(self, k: SchemaKind, maybe_create_proxy: bool) -> str:
    if self.backend_index.dispatch_key in [DispatchKey.CUDA, DispatchKey.MPS, DispatchKey.XPU, DispatchKey.CompositeExplicitAutogradNonFunctional]:
        maybe_set_guard = '
auto current_device = guard_.current_device();
if (C10_UNLIKELY(current_device.has_value())) {
  TORCH_INTERNAL_ASSERT(*current_device == options.device(),
    "structured kernels don't support multi-device outputs");
} else {
  guard_.reset_device(options.device());
}
'
        maybe_set_guard_line = maybe_set_guard + '
'
    else:
        maybe_set_guard_line = maybe_set_guard = ''
    if maybe_create_proxy:
        create_proxy = '
auto maybe_proxy = maybe_create_proxy(out, sizes, strides, options);
if (C10_UNLIKELY(maybe_proxy.has_value())) {
    proxy_outputs_[output_idx] = std::move(maybe_proxy).value();
}
'
    else:
        create_proxy = ''
    if k is SchemaKind.functional:
        assert self.backend_index.dispatch_key in (DispatchKey.Meta, DispatchKey.CPU, DispatchKey.CUDA, DispatchKey.MPS, DispatchKey.XPU, DispatchKey.MTIA, DispatchKey.CompositeExplicitAutogradNonFunctional)
        return f'{maybe_set_guard_line}
outputs_[output_idx] = create_out(sizes, strides, options);'
    elif <MASK>:
        return f'{maybe_set_guard_line}
const auto& out = outputs_[output_idx].get();
check_inplace(out, sizes, options);
{create_proxy}'
    elif k is SchemaKind.out:
        return f'{maybe_set_guard_line}
const auto& out = outputs_[output_idx].get();
resize_out(out, sizes, strides, options);
{create_proxy}'
    elif k is SchemaKind.mutable or k is SchemaKind.scratch:
        raise AssertionError(f'{k} structured operators are currently not supported')
    else:
        assert_never(k)

@RegisterPFor('TensorArrayScatterV3')
def _convert_tensor_array_scatter_v3(pfor_input: _PforInput):
    handle = pfor_input.unstacked_input(0)
    (indices, indices_stacked, _) = pfor_input.input(1)
    indices = array_ops.reshape(indices, [-1])
    (value, value_stacked, _) = pfor_input.input(2)
    (flow, flow_stacked, _) = pfor_input.input(3)
    if flow_stacked:
        flow = _unstack_flow(flow)
    is_inside = _handle_inside_pfor(pfor_input, pfor_input.op.inputs[0])
    if is_inside:
        if indices_stacked:
            raise ValueError(f'Need indices for {handle} to be loop invariant.')
        if not flow_stacked and (not value_stacked):
            flow_out = data_flow_ops.tensor_array_scatter_v3(handle, indices, value, flow)
            return wrap(flow_out, False)
        if <MASK>:
            value = _stack(value, pfor_input.pfor.loop_len_vector).t
        value = _transpose_first_two_dims(value)
        flow_out = data_flow_ops.tensor_array_scatter_v3(handle, indices, value, flow)
        return _stack(flow_out, pfor_input.pfor.loop_len_vector)
    if not indices_stacked:
        raise ValueError(f'Need indices for {handle} to be not loop invariant.')
    if not value_stacked:
        value = _stack(value, pfor_input.pfor.loop_len_vector).t
    value = _flatten_first_two_dims(value)
    flow_out = data_flow_ops.tensor_array_scatter_v3(handle, indices, value, flow)
    return _stack(flow_out, pfor_input.pfor.loop_len_vector)

@staticmethod
def _parse(t: str) -> Type:
    m = re.match('^(.+)\\?$', t)
    if <MASK>:
        return OptionalType(Type.parse(m.group(1)))
    m = re.match('^(.+)\\[([0-9]+)?\\]$', t)
    if m is not None:
        size = int(m.group(2)) if m.group(2) is not None else None
        return ListType(elem=Type.parse(m.group(1)), size=size)
    m = re.match('^__torch__\\.torch\\.classes\\.([a-zA-Z0-9_.]+)$', t)
    if m is not None:
        return CustomClassType(m.group(1))
    try:
        return BaseType(BaseTy[t])
    except KeyError as e:
        raise RuntimeError(f'unrecognized type {t}') from e

def _model_loss(model, inputs, targets, output_loss_metrics=None, sample_weights=None, training=False):
    """Calculates the loss for a given model.

  Args:
      model: The model on which metrics are being calculated.
      inputs: Either a dictionary of inputs to the model or a list of input
        arrays.
      targets: List of target arrays.
      output_loss_metrics: List of metrics that are used to aggregated output
        loss values.
      sample_weights: Optional list of sample weight arrays.
      training: Whether the model should be run in inference or training mode.

  Returns:
     Returns the model output, total loss, loss value calculated using the
     specified loss function and masks for each output. The total loss includes
     regularization losses and applies masking and sample weighting
     to the loss value.
  """
    total_loss = 0
    kwargs = {}
    if model._expects_training_arg:
        kwargs['training'] = training
    if len(inputs) == 1 and (not isinstance(inputs, dict)):
        inputs = inputs[0]
    if any((isinstance(input_t, (np.ndarray, float, int)) for input_t in nest.flatten(inputs))):
        inputs = nest.map_structure(tensor_conversion.convert_to_tensor_v2_with_dispatch, inputs)
    outs = model(inputs, **kwargs)
    outs = nest.flatten(outs)
    if targets:
        targets = training_utils_v1.cast_if_floating_dtype_and_mismatch(targets, outs)
    if sample_weights:
        new_sample_weights = []
        for val in sample_weights:
            if val is not None:
                new_sample_weights.append(training_utils_v1.cast_if_floating_dtype(tensor_conversion.convert_to_tensor_v2_with_dispatch(val)))
            else:
                new_sample_weights.append(None)
        sample_weights = new_sample_weights
    masks = [getattr(t, '_keras_mask', None) for t in outs]
    targets = nest.flatten(targets)
    output_losses = []
    with backend.name_scope('loss'):
        loss_fns = [loss_fn for loss_fn in model.loss_functions if loss_fn is not None]
        custom_losses = model.losses
        if <MASK>:
            if training:
                raise ValueError('The model cannot be trained because it has no loss to optimize.')
            else:
                raise ValueError('The model cannot be evaluated because it has no loss to compute.')
        for (i, loss_fn) in enumerate(loss_fns):
            weights = sample_weights[i] if sample_weights else None
            mask = masks[i]
            with backend.name_scope(model.output_names[i] + '_loss'):
                if mask is not None:
                    mask = math_ops.cast(mask, outs[i].dtype)
                    if weights is None:
                        weights = mask
                    else:
                        weights = math_ops.cast(weights, outs[i].dtype)
                        (mask, _, weights) = losses_utils.squeeze_or_expand_dimensions(mask, sample_weight=weights)
                        weights *= mask
                if hasattr(loss_fn, 'reduction'):
                    per_sample_losses = loss_fn.call(targets[i], outs[i])
                    weighted_losses = losses_utils.compute_weighted_loss(per_sample_losses, sample_weight=weights, reduction=losses_utils.ReductionV2.NONE)
                    loss_reduction = loss_fn.reduction
                    if loss_reduction == losses_utils.ReductionV2.AUTO:
                        loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
                    output_loss = losses_utils.reduce_weighted_loss(weighted_losses, reduction=loss_reduction)
                else:
                    output_loss = loss_fn(targets[i], outs[i], sample_weight=weights)
                    loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
            if len(model.outputs) > 1:
                output_losses.append(output_loss_metrics[i](output_loss))
            if loss_reduction == losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE:
                output_loss = losses_utils.scale_loss_for_distribution(output_loss)
            total_loss += model._loss_weights_list[i] * output_loss
        if custom_losses:
            total_loss += losses_utils.scale_loss_for_distribution(math_ops.add_n(custom_losses))
    return (outs, total_loss, output_losses, masks)

def to_string(self) -> str:
    series = self.tr_series
    footer = self._get_footer()
    if len(series) == 0:
        return f'{type(self.series).__name__}([], {footer})'
    index = series.index
    have_header = _has_names(index)
    if <MASK>:
        fmt_index = index._format_multi(include_names=True, sparsify=None)
        adj = printing.get_adjustment()
        fmt_index = adj.adjoin(2, *fmt_index).split('\n')
    else:
        fmt_index = index._format_flat(include_name=True)
    fmt_values = self._get_formatted_values()
    if self.is_truncated_vertically:
        n_header_rows = 0
        row_num = self.tr_row_num
        row_num = cast(int, row_num)
        width = self.adj.len(fmt_values[row_num - 1])
        if width > 3:
            dot_str = '...'
        else:
            dot_str = '..'
        dot_str = self.adj.justify([dot_str], width, mode='center')[0]
        fmt_values.insert(row_num + n_header_rows, dot_str)
        fmt_index.insert(row_num + 1, '')
    if self.index:
        result = self.adj.adjoin(3, *[fmt_index[1:], fmt_values])
    else:
        result = self.adj.adjoin(3, fmt_values)
    if self.header and have_header:
        result = fmt_index[0] + '\n' + result
    if footer:
        result += '\n' + footer
    return str(''.join(result))

def lookup_unbound_symbols(self, s: torch.SymInt) -> list[sympy.Symbol]:
    free_symbols = s.node.expr.free_symbols
    if len(free_symbols) == 0:
        return []
    to_be_bound = []
    for s0 in free_symbols:
        if s0 not in self.bound_symbols:
            to_be_bound.append(s0)
            continue
        proxy = self.bound_symbols[s0]
        if <MASK>:
            proxy = proxy()
            self.bound_symbols[s0] = proxy
        assert isinstance(proxy, torch.fx.Proxy) and proxy.tracer is self, f"The proxy of symbol {s0} doesn't belong to current tracer."
    return sorted(to_be_bound, key=lambda s: s.name)

@register_meta([aten.baddbmm.default, aten.baddbmm.out])
@out_wrapper(exact_dtype=True)
def meta_baddbmm(self, batch1, batch2, *, beta=1, alpha=1):
    from torch.fx.experimental.symbolic_shapes import guard_or_true, sym_eq
    dim1 = batch1.size(0)
    dim2 = batch1.size(1)
    dim3 = batch2.size(2)
    if guard_or_true(torch.sym_not(sym_eq(self.shape, (dim1, dim2, dim3)))):
        self = self.expand((dim1, dim2, dim3))
    torch._check(batch1.dim() == 3, lambda : 'batch1 must be a 3D tensor')
    torch._check(batch2.dim() == 3, lambda : 'batch2 must be a 3D tensor')
    if <MASK>:
        torch._check(self.dtype == batch1.dtype == batch2.dtype, lambda : f'Input dtypes must be the same, got: input: {self.dtype}, batch1: {batch1.dtype}, batch2: {batch2.dtype}')
    batch1_sizes = batch1.shape
    batch2_sizes = batch2.shape
    bs = batch1_sizes[0]
    contraction_size = batch1_sizes[2]
    torch._check(batch2_sizes[0] == bs and batch2_sizes[1] == contraction_size, lambda : f'Expected size for first two dimensions of batch2 tensor to be: [{bs}, {contraction_size}] but got: [{batch2_sizes[0]}, {batch2_sizes[1]}].')
    return self.new_empty(self.size())

def add_item_elements(self, handler, item):
    handler.addQuickElement('title', item['title'])
    handler.addQuickElement('link', '', {'href': item['link'], 'rel': 'alternate'})
    if item['pubdate'] is not None:
        handler.addQuickElement('published', rfc3339_date(item['pubdate']))
    if item['updateddate'] is not None:
        handler.addQuickElement('updated', rfc3339_date(item['updateddate']))
    if item['author_name'] is not None:
        handler.startElement('author', {})
        handler.addQuickElement('name', item['author_name'])
        if <MASK>:
            handler.addQuickElement('email', item['author_email'])
        if item['author_link'] is not None:
            handler.addQuickElement('uri', item['author_link'])
        handler.endElement('author')
    if item['unique_id'] is not None:
        unique_id = item['unique_id']
    else:
        unique_id = get_tag_uri(item['link'], item['pubdate'])
    handler.addQuickElement('id', unique_id)
    if item['description'] is not None:
        handler.addQuickElement('summary', item['description'], {'type': 'html'})
    for enclosure in item['enclosures']:
        handler.addQuickElement('link', '', {'rel': 'enclosure', 'href': enclosure.url, 'length': enclosure.length, 'type': enclosure.mime_type})
    for cat in item['categories']:
        handler.addQuickElement('category', '', {'term': cat})
    if item['item_copyright'] is not None:
        handler.addQuickElement('rights', item['item_copyright'])

def _check_args(x, div, mod, is_first):
    if <MASK>:
        return False
    if div != 1:
        return False
    if mod <= 0:
        return False
    if is_first:
        if not isinstance(x, ModularIndexing):
            return False
    elif not isinstance(x, sympy.Symbol) or not self.statically_known_geq(x, 0):
        return False
    return True

def url(self, name):
    if self.base_url is None:
        raise ValueError('This file is not accessible via a URL.')
    url = filepath_to_uri(name)
    if <MASK>:
        url = url.lstrip('/')
    return urljoin(self.base_url, url)

def datetime_trunc_sql(self, lookup_type, sql, params, tzname):
    (sql, params) = self._convert_sql_to_tz(sql, params, tzname)
    trunc_param = None
    if lookup_type in ('year', 'month'):
        trunc_param = lookup_type.upper()
    elif lookup_type == 'quarter':
        trunc_param = 'Q'
    elif <MASK>:
        trunc_param = 'IW'
    elif lookup_type == 'hour':
        trunc_param = 'HH24'
    elif lookup_type == 'minute':
        trunc_param = 'MI'
    elif lookup_type == 'day':
        return (f'TRUNC({sql})', params)
    else:
        return (f'CAST({sql} AS DATE)', params)
    return (f'TRUNC({sql}, %s)', (*params, trunc_param))

@register_decomposition(aten.native_batch_norm_backward.out)
def native_batch_norm_backward_out(grad_out: Tensor, input: Tensor, weight: Optional[Tensor], running_mean: Optional[Tensor], running_var: Optional[Tensor], save_mean: Optional[Tensor], save_invstd: Optional[Tensor], train: bool, eps: float, output_mask: list[bool], *, out0: torch.Tensor, out1: torch.Tensor, out2: torch.Tensor) -> tuple[Tensor, Optional[Tensor], Optional[Tensor]]:
    result = native_batch_norm_backward(grad_out, input, weight, running_mean, running_var, save_mean, save_invstd, train, eps, output_mask)
    grad_input = (out0, out1, out2)
    for (i, r) in enumerate(result):
        if <MASK>:
            _maybe_resize_out(grad_input[i], r.shape)
            _safe_copy_out(copy_from=r, copy_to=grad_input[i], exact_dtype=True)
    return grad_input

@register.tag
def language(parser, token):
    """
    Enable the given language just for this block.

    Usage::

        {% language "de" %}
            This is {{ bar }} and {{ boo }}.
        {% endlanguage %}
    """
    bits = token.split_contents()
    if <MASK>:
        raise TemplateSyntaxError("'%s' takes one argument (language)" % bits[0])
    language = parser.compile_filter(bits[1])
    nodelist = parser.parse(('endlanguage',))
    parser.delete_first_token()
    return LanguageNode(nodelist, language)

def _call_min_max_binary(self, tx: 'InstructionTranslator', a, b):
    if a is None or b is None:
        return
    if self.tensor_args(a, b):
        if not isinstance(a, variables.TensorVariable):
            (a, b) = (b, a)
        assert isinstance(a, variables.TensorVariable)
        if <MASK>:
            a = variables.TorchInGraphFunctionVariable(torch.tensor).call_function(tx, [a], {})
        if isinstance(a, SymNodeVariable) or isinstance(b, SymNodeVariable):
            from .builder import wrap_fx_proxy_cls
            return wrap_fx_proxy_cls(type(a), tx=tx, proxy=tx.output.create_proxy('call_function', self.fn, *proxy_args_kwargs([a, b], {})))
        if b.is_python_constant():
            fn: VariableTracker
            if isinstance(a, variables.NumpyNdarrayVariable):
                import numpy as np
                fn = variables.NumpyVariable(np.clip)
            else:
                fn = variables.TorchInGraphFunctionVariable(torch.clamp)
            kwargs = {'min': b} if self.fn is max else {'max': b}
            result = fn.call_function(tx, [a], kwargs)
        else:
            if isinstance(a, variables.NumpyNdarrayVariable):
                import numpy as np
                np_fn = {max: np.maximum, min: np.minimum}[self.fn]
                fn = variables.NumpyVariable(np_fn)
            else:
                torch_fn = {max: torch.maximum, min: torch.minimum}[self.fn]
                fn = variables.TorchInGraphFunctionVariable(torch_fn)
            result = fn.call_function(tx, [a, b], {})
        if all((isinstance(i, (variables.UnspecializedPythonVariable, variables.ConstantVariable)) for i in [a, b])):
            if any((isinstance(val, FakeItemVariable) for val in [a, b])):
                return variables.FakeItemVariable.from_tensor_variable(result)
            if b.is_python_constant():
                raw_b = b.as_python_constant()
            else:
                raw_b = b.raw_value
            if self.fn is max:
                raw_res = max(a.raw_value, raw_b)
            else:
                raw_res = min(a.raw_value, raw_b)
            need_unwrap = any((x.need_unwrap for x in [a, b] if isinstance(x, variables.UnspecializedPythonVariable)))
            return variables.UnspecializedPythonVariable.from_tensor_variable(result, raw_res, need_unwrap)
        else:
            return result
    elif isinstance(a, SymNodeVariable) or isinstance(b, SymNodeVariable):
        py_fn = torch.sym_max if self.fn is max else torch.sym_min
        proxy = tx.output.create_proxy('call_function', py_fn, *proxy_args_kwargs([a, b], {}))
        return SymNodeVariable.create(tx, proxy, None)
    elif isinstance(a, ConstantVariable) and isinstance(b, ConstantVariable):
        value = self.fn(a.as_python_constant(), b.as_python_constant())
        return ConstantVariable(value)

def resolve_expression(self, query=None, allow_joins=True, reuse=None, summarize=False, for_save=False):
    c = super().resolve_expression(query, allow_joins, reuse, summarize)
    if summarize:
        for ref in c.get_refs():
            if query.annotations[ref].is_summary:
                raise FieldError(f"Cannot compute {c.name}('{ref}'): '{ref}' is an aggregate")
    elif not self.is_summary:
        expressions = super(Aggregate, c).get_source_expressions()
        for (index, expr) in enumerate(expressions):
            if <MASK>:
                before_resolved = self.get_source_expressions()[index]
                name = before_resolved.name if hasattr(before_resolved, 'name') else repr(before_resolved)
                raise FieldError("Cannot compute %s('%s'): '%s' is an aggregate" % (c.name, name, name))
    if (default := c.default) is None:
        return c
    if hasattr(default, 'resolve_expression'):
        default = default.resolve_expression(query, allow_joins, reuse, summarize)
        if default._output_field_or_none is None:
            default.output_field = c._output_field_or_none
    else:
        default = Value(default, c._output_field_or_none)
    c.default = None
    coalesce = Coalesce(c, default, output_field=c._output_field_or_none)
    coalesce.is_summary = c.is_summary
    return coalesce

def handle(self, *args, **options):
    locale = options['locale']
    exclude = options['exclude']
    self.domain = options['domain']
    self.verbosity = options['verbosity']
    process_all = options['all']
    extensions = options['extensions']
    self.symlinks = options['symlinks']
    ignore_patterns = options['ignore_patterns']
    if options['use_default_ignore_patterns']:
        ignore_patterns += ['CVS', '.*', '*~', '*.pyc']
    self.ignore_patterns = list(set(ignore_patterns))
    if options['no_wrap']:
        self.msgmerge_options = self.msgmerge_options[:] + ['--no-wrap']
        self.msguniq_options = self.msguniq_options[:] + ['--no-wrap']
        self.msgattrib_options = self.msgattrib_options[:] + ['--no-wrap']
        self.xgettext_options = self.xgettext_options[:] + ['--no-wrap']
    if options['no_location']:
        self.msgmerge_options = self.msgmerge_options[:] + ['--no-location']
        self.msguniq_options = self.msguniq_options[:] + ['--no-location']
        self.msgattrib_options = self.msgattrib_options[:] + ['--no-location']
        self.xgettext_options = self.xgettext_options[:] + ['--no-location']
    if options['add_location']:
        arg_add_location = '--add-location=%s' % options['add_location']
        self.msgmerge_options = self.msgmerge_options[:] + [arg_add_location]
        self.msguniq_options = self.msguniq_options[:] + [arg_add_location]
        self.msgattrib_options = self.msgattrib_options[:] + [arg_add_location]
        self.xgettext_options = self.xgettext_options[:] + [arg_add_location]
    self.no_obsolete = options['no_obsolete']
    self.keep_pot = options['keep_pot']
    if self.domain not in ('django', 'djangojs'):
        raise CommandError("currently makemessages only supports domains 'django' and 'djangojs'")
    if self.domain == 'djangojs':
        exts = extensions or ['js']
    else:
        exts = extensions or ['html', 'txt', 'py']
    self.extensions = handle_extensions(exts)
    if not locale and (not exclude) and (not process_all) or self.domain is None:
        raise CommandError("Type '%s help %s' for usage information." % (os.path.basename(sys.argv[0]), sys.argv[1]))
    if self.verbosity > 1:
        self.stdout.write('examining files with the extensions: %s' % get_text_list(list(self.extensions), 'and'))
    self.invoked_for_django = False
    self.locale_paths = []
    self.default_locale_path = None
    if os.path.isdir(os.path.join('conf', 'locale')):
        self.locale_paths = [os.path.abspath(os.path.join('conf', 'locale'))]
        self.default_locale_path = self.locale_paths[0]
        self.ignore_patterns.append('views/templates/i18n_catalog.js')
        self.invoked_for_django = True
    else:
        if <MASK>:
            for path in settings.LOCALE_PATHS:
                locale_path = os.path.abspath(path)
                if locale_path not in self.locale_paths:
                    self.locale_paths.append(locale_path)
        if os.path.isdir('locale'):
            locale_path = os.path.abspath('locale')
            if locale_path not in self.locale_paths:
                self.locale_paths.append(locale_path)
        if self.locale_paths:
            self.default_locale_path = self.locale_paths[0]
            os.makedirs(self.default_locale_path, exist_ok=True)
    looks_like_locale = re.compile('[a-z]{2}')
    locale_dirs = filter(os.path.isdir, glob.glob('%s/*' % self.default_locale_path))
    all_locales = [lang_code for lang_code in map(os.path.basename, locale_dirs) if looks_like_locale.match(lang_code)]
    if process_all:
        locales = all_locales
    else:
        locales = locale or all_locales
        locales = set(locales).difference(exclude)
    if locales:
        check_programs('msguniq', 'msgmerge', 'msgattrib')
    check_programs('xgettext')
    try:
        potfiles = self.build_potfiles()
        for locale in locales:
            if not is_valid_locale(locale):
                match = re.match('^(?P<language>[a-zA-Z]+)(?P<separator>[^a-zA-Z])(?P<territory>.+)$', locale)
                if match:
                    locale_parts = match.groupdict()
                    language = locale_parts['language'].lower()
                    territory = locale_parts['territory'][:2].upper() + locale_parts['territory'][2:]
                    proposed_locale = f'{language}_{territory}'
                else:
                    proposed_locale = locale.lower()
                if is_valid_locale(proposed_locale):
                    self.stdout.write('invalid locale %s, did you mean %s?' % (locale, proposed_locale))
                else:
                    self.stdout.write('invalid locale %s' % locale)
                continue
            if self.verbosity > 0:
                self.stdout.write('processing locale %s' % locale)
            for potfile in potfiles:
                self.write_po_file(potfile, locale)
    finally:
        if not self.keep_pot:
            self.remove_potfiles()

def bsr_dense_mm(bsr: torch.Tensor, dense: torch.Tensor, *, out: Optional[torch.Tensor]=None, skip_checks: bool=False, max_grid: Optional[tuple[Optional[int], Optional[int], Optional[int]]]=None, meta: Optional[dict]=None):
    f_name = 'bsr_dense_mm'
    (m, _kl) = bsr.shape[-2:]
    if not skip_checks:
        check_bsr_layout(f_name, bsr)
        check_device(f_name, bsr, dense.device)
        check_dtype(f_name, bsr, dense.dtype, (torch.int8,))
        check_mm_compatible_shapes(f_name, bsr, dense)
        n = dense.size(-1)
        (row_block, col_block) = bsr.values().shape[-2:]
        check_blocksize(f_name, (row_block, col_block))
        check(not n % 16, f'{f_name}(): dense.size(-1) == {n} should be divisible by 16')
    else:
        (_kr, n) = dense.shape[-2:]
    original_batch_dims_broadcasted = broadcast_batch_dims(f_name, bsr, dense)
    if out is not None and (not skip_checks):
        expected_out_shape = original_batch_dims_broadcasted + (m, n)
        check(out.shape == expected_out_shape, f'bsr_dense_mm(): `out` argument has wrong shape, expected {expected_out_shape}, but got {out.shape}.')
        check(out.is_contiguous() or out.transpose(-2, -1).is_contiguous(), 'bsr_dense_mm(): only row-major/col-major `out` arguments are supported, i.e. (out.is_contiguous() or out.transpose(-2, -1).is_contiguous()) should be True.')
    if out is None:
        out = dense.new_empty(original_batch_dims_broadcasted + (m, n))
    if <MASK>:
        return out.zero_()
    return bsr_dense_addmm(out, bsr, dense, alpha=1, beta=0, out=out)

