def create_index(self, columns=None, optlevel=None, kind: str | None=None) -> None:
    """
        Create a pytables index on the specified columns.

        Parameters
        ----------
        columns : None, bool, or listlike[str]
            Indicate which columns to create an index on.

            * False : Do not create any indexes.
            * True : Create indexes on all columns.
            * None : Create indexes on all columns.
            * listlike : Create indexes on the given columns.

        optlevel : int or None, default None
            Optimization level, if None, pytables defaults to 6.
        kind : str or None, default None
            Kind of index, if None, pytables defaults to "medium".

        Raises
        ------
        TypeError if trying to create an index on a complex-type column.

        Notes
        -----
        Cannot index Time64Col or ComplexCol.
        Pytables must be >= 3.0.
        """
    if not self.infer_axes():
        return
    if columns is False:
        return
    if columns is None or columns is True:
        columns = [a.cname for a in self.axes if a.is_data_indexable]
    if not isinstance(columns, (tuple, list)):
        columns = [columns]
    kw = {}
    if optlevel is not None:
        kw['optlevel'] = optlevel
    if kind is not None:
        kw['kind'] = kind
    table = self.table
    for c in columns:
        v = getattr(table.cols, c, None)
        if v is not None:
            if v.is_indexed:
                index = v.index
                cur_optlevel = index.optlevel
                cur_kind = index.kind
                if kind is not None and cur_kind != kind:
                    v.remove_index()
                else:
                    kw['kind'] = cur_kind
                if <MASK>:
                    v.remove_index()
                else:
                    kw['optlevel'] = cur_optlevel
            if not v.is_indexed:
                if v.type.startswith('complex'):
                    raise TypeError('Columns containing complex values can be stored but cannot be indexed when using table format. Either use fixed format, set index=False, or do not include the columns containing complex values to data_columns when initializing the table.')
                v.create_index(**kw)
        elif c in self.non_index_axes[0][1]:
            raise AttributeError(f'column {c} is not a data_column.\nIn order to read column {c} you must reload the dataframe \ninto HDFStore and include {c} with the data_columns argument.')

def decorator(func):

    @wraps(func)
    def wrapper(*args, **kwargs):
        original_fully_shard: Any = torch.distributed.fsdp.fully_shard
        for mode in FullyShardMode:
            if mode != FullyShardMode.EAGER and (not has_triton()):
                warnings.warn('Inductor on GPU needs Triton and recent GPU arch')
                continue
            original_skip_fsdp_hooks = torch._dynamo.config.skip_fsdp_hooks
            original_compile_threads = torch._inductor.config.compile_threads
            torch.distributed.barrier()
            if mode == FullyShardMode.EAGER:
                fully_shard_patch = original_fully_shard
            elif <MASK>:
                torch._dynamo.config.skip_fsdp_hooks = True
                torch._inductor.config.compile_threads = 1
                fully_shard_patch = fully_shard_with_compiled_compute
            else:
                raise NotImplementedError(f'Need to implement FullyShardMode={mode}')
            func.__globals__[original_fully_shard.__name__] = fully_shard_patch
            func(*args, **kwargs)
            torch.distributed.barrier()
            func.__globals__[original_fully_shard.__name__] = original_fully_shard
            torch._dynamo.config.skip_fsdp_hooks = original_skip_fsdp_hooks
            torch._inductor.config.compile_threads = original_compile_threads
    return wrapper

def set_group_by(self, allow_aliases=True):
    """
        Expand the GROUP BY clause required by the query.

        This will usually be the set of all non-aggregate fields in the
        return data. If the database backend supports grouping by the
        primary key, and the query would be equivalent, the optimization
        will be made automatically.
        """
    if allow_aliases and self.values_select:
        group_by_annotations = {}
        values_select = {}
        for (alias, expr) in zip(self.values_select, self.select):
            if isinstance(expr, Col):
                values_select[alias] = expr
            else:
                group_by_annotations[alias] = expr
        self.annotations = {**group_by_annotations, **self.annotations}
        self.append_annotation_mask(group_by_annotations)
        self.select = tuple(values_select.values())
        self.values_select = tuple(values_select)
        if self.selected is not None:
            for (index, value_select) in enumerate(values_select):
                self.selected[value_select] = index
    group_by = list(self.select)
    for (alias, annotation) in self.annotation_select.items():
        if not (group_by_cols := annotation.get_group_by_cols()):
            continue
        if <MASK>:
            group_by.append(Ref(alias, annotation))
        else:
            group_by.extend(group_by_cols)
    self.group_by = tuple(group_by)

def _floats_wrapper(*args, **kwargs):
    if 'width' in kwargs and hypothesis.version.__version_info__ < (3, 67, 0):
        no_nan_and_inf = ('allow_nan' in kwargs and (not kwargs['allow_nan']) or 'allow_nan' not in kwargs) and ('allow_infinity' in kwargs and (not kwargs['allow_infinity']) or 'allow_infinity' not in kwargs)
        min_and_max_not_specified = len(args) == 0 and 'min_value' not in kwargs and ('max_value' not in kwargs)
        if no_nan_and_inf and min_and_max_not_specified:
            if kwargs['width'] == 16:
                kwargs['min_value'] = torch.finfo(torch.float16).min
                kwargs['max_value'] = torch.finfo(torch.float16).max
            elif <MASK>:
                kwargs['min_value'] = torch.finfo(torch.float32).min
                kwargs['max_value'] = torch.finfo(torch.float32).max
            elif kwargs['width'] == 64:
                kwargs['min_value'] = torch.finfo(torch.float64).min
                kwargs['max_value'] = torch.finfo(torch.float64).max
        kwargs.pop('width')
    return st.floats(*args, **kwargs)

def _fuse_ddp_communication(graph: fx.Graph, algorithm_fn: Callable[..., Any], fusion_fn: Callable[..., Any]) -> None:
    for output in reversed(graph.nodes):
        if <MASK>:
            break

    def ddp_reducer_filter(block: CommBlock) -> bool:
        if not isinstance(block.comm_node.args[0], fx.Node) or block.comm_node.args[0].target != aten.div.Tensor:
            return False
        if len(block.wait_nodes[0].users) != 1:
            return False
        if output not in block.wait_nodes[0].users and next(iter(block.wait_nodes[0].users)).target != aten.copy_.default:
            return False
        return True
    ops = (torch.ops._c10d_functional.all_reduce_.default, torch.ops._c10d_functional.all_reduce.default)
    comm_blocks = get_all_comm_blocks(graph, ops, comm_filter=ddp_reducer_filter)
    node_indices = {node: i for (i, node) in enumerate(graph.nodes)}
    for block in algorithm_fn(graph, comm_blocks):
        fusion_fn(graph, block, node_indices)

def _get_device_index(device: Any, optional: bool=False, allow_cpu: bool=False) -> int:
    """Get the device index from :attr:`device`, which can be a torch.device object, a Python integer, or ``None``.

    If :attr:`device` is a torch.device object, returns the device index if it
    is a CUDA device. Note that for a CUDA device without a specified index,
    i.e., ``torch.device('cuda')``, this will return the current default CUDA
    device if :attr:`optional` is ``True``. If :attr:`allow_cpu` is ``True``,
    CPU devices will be accepted and ``-1`` will be returned in this case.

    If :attr:`device` is a Python integer, it is returned as is.

    If :attr:`device` is ``None``, this will return the current default CUDA
    device if :attr:`optional` is ``True``.
    """
    if isinstance(device, int):
        return device
    if isinstance(device, str):
        device = torch.device(device)
    if isinstance(device, torch.device):
        if allow_cpu:
            if <MASK>:
                raise ValueError(f'Expected a cuda or cpu device, but got: {device}')
        elif device.type != 'cuda':
            raise ValueError(f'Expected a cuda device, but got: {device}')
    if not torch.jit.is_scripting():
        if isinstance(device, torch.cuda.device):
            return device.idx
    return _torch_get_device_index(device, optional, allow_cpu)

def prefer_static_broadcast_shape(shape1, shape2, name='prefer_static_broadcast_shape'):
    """Convenience function which statically broadcasts shape when possible.

  Args:
    shape1:  `1-D` integer `Tensor`.  Already converted to tensor!
    shape2:  `1-D` integer `Tensor`.  Already converted to tensor!
    name:  A string name to prepend to created ops.

  Returns:
    The broadcast shape, either as `TensorShape` (if broadcast can be done
      statically), or as a `Tensor`.
  """
    with ops.name_scope(name, values=[shape1, shape2]):

        def make_shape_tensor(x):
            return ops.convert_to_tensor(x, name='shape', dtype=dtypes.int32)

        def get_tensor_shape(s):
            if isinstance(s, tensor_shape.TensorShape):
                return s
            s_ = tensor_util.constant_value(make_shape_tensor(s))
            if s_ is not None:
                return tensor_shape.TensorShape(s_)
            return None

        def get_shape_tensor(s):
            if not isinstance(s, tensor_shape.TensorShape):
                return make_shape_tensor(s)
            if s.is_fully_defined():
                return make_shape_tensor(s.as_list())
            raise ValueError('Cannot broadcast from partially defined `TensorShape`.')
        shape1_ = get_tensor_shape(shape1)
        shape2_ = get_tensor_shape(shape2)
        if <MASK>:
            return array_ops.broadcast_static_shape(shape1_, shape2_)
        shape1_ = get_shape_tensor(shape1)
        shape2_ = get_shape_tensor(shape2)
        return array_ops.broadcast_dynamic_shape(shape1_, shape2_)

def _searchsorted_monotonic(self, label, side: Literal['left', 'right']='left'):
    if not self.is_non_overlapping_monotonic:
        raise KeyError('can only get slices from an IntervalIndex if bounds are non-overlapping and all monotonic increasing or decreasing')
    if isinstance(label, (IntervalMixin, IntervalIndex)):
        raise NotImplementedError('Interval objects are not currently supported')
    if side == 'left' and self.left.is_monotonic_increasing or (side == 'right' and (not self.left.is_monotonic_increasing)):
        sub_idx = self.right
        if self.open_right:
            label = _get_next_label(label)
    else:
        sub_idx = self.left
        if <MASK>:
            label = _get_prev_label(label)
    return sub_idx._searchsorted_monotonic(label, side)

def TD(types, f=None, astype=None, in_=None, out=None, cfunc_alias=None, dispatch=None):
    """
    Generate a TypeDescription instance for each item in types
    """
    if <MASK>:
        if isinstance(f, str):
            func_data = build_func_data(types, f)
        elif len(f) != len(types):
            raise ValueError('Number of types and f do not match')
        else:
            func_data = f
    else:
        func_data = (None,) * len(types)
    if isinstance(in_, str):
        in_ = (in_,) * len(types)
    elif in_ is None:
        in_ = (None,) * len(types)
    elif len(in_) != len(types):
        raise ValueError('Number of types and inputs do not match')
    if isinstance(out, str):
        out = (out,) * len(types)
    elif out is None:
        out = (None,) * len(types)
    elif len(out) != len(types):
        raise ValueError('Number of types and outputs do not match')
    tds = []
    for (t, fd, i, o) in zip(types, func_data, in_, out):
        if dispatch:
            dispt = ([k for (k, v) in dispatch if t in v] + [None])[0]
        else:
            dispt = None
        tds.append(TypeDescription(t, f=fd, in_=i, out=o, astype=astype, cfunc_alias=cfunc_alias, dispatch=dispt))
    return tds

def reconstruct(x: np.ndarray):
    from pandas.core.arrays import BooleanArray, FloatingArray, IntegerArray
    if <MASK>:
        m = mask.copy()
        return BooleanArray(x, m)
    elif x.dtype.kind in 'iu':
        m = mask.copy()
        return IntegerArray(x, m)
    elif x.dtype.kind == 'f':
        m = mask.copy()
        if x.dtype == np.float16:
            x = x.astype(np.float32)
        if is_nan_na():
            m[np.isnan(x)] = True
        return FloatingArray(x, m)
    else:
        x[mask] = np.nan
    return x

def _generate_kernel_call_helper(self, kernel_name: str, call_args: list[str], *, device: Optional[torch.device]=None, triton: bool=True, arg_types: Optional[tuple[Any, ...]]=None, raw_keys: Optional[tuple[Any, ...]]=None, raw_args: Optional[tuple[Any, ...]]=None, triton_meta: Optional[dict[str, Any]]=None, graph_name: str='', original_fxnode_name: Optional[str]=None) -> None:
    """
        Generates MPS kernel call code. It should look something like:
        ```
        auto mps_lib_0_lambda = [&](AOTIMetalKernelFunctionHandle handle) {
            aoti_torch_mps_start_encoding(handle);
            aoti_torch_mps_set_arg_tensor(handle, 0, buf0);
            aoti_torch_mps_set_arg_tensor(handle, 1, arg0_1);
            aoti_torch_mps_set_arg_tensor(handle, 2, arg1_1);
            aoti_torch_mps_dispatch_single(handle, static_cast<uint64_t>(10LL));
        };

        std::function<void(AOTIMetalKernelFunctionHandle)> mps_lib_0_func_wrapper = mps_lib_0_lambda;
        aoti_torch_mps_run_command_block(get_mps_lib_0_handle(), aoti_torch_mps_shared_callback, &mps_lib_0_func_wrapper);
        ```
        """
    device = device or V.graph.get_current_device_or_throw()
    if device.type == 'cpu':
        return CppWrapperCpu._generate_kernel_call_helper(self, kernel_name, call_args, device=device, triton=triton, arg_types=arg_types, raw_keys=raw_keys, raw_args=raw_args, triton_meta=triton_meta)
    assert device.type == 'mps'
    assert arg_types is not None
    new_args = []
    for (idx, (arg, arg_type)) in enumerate(zip(call_args[:-2], arg_types[:-2])):
        if isinstance(arg_type, torch.dtype):
            new_args.append(f'aoti_torch_mps_set_arg_tensor(handle, {idx}, {arg});')
        elif arg_type in (int, sympy.core.symbol.Symbol):
            new_args.append(f'aoti_torch_mps_set_arg_int(handle, {idx}, {arg});')
        else:
            raise NotImplementedError(f'Unsupported arg type {arg_type} for arg {arg} for kernel {kernel_name}')
    (threads, group_size) = (call_args[-2], call_args[-1])
    if threads is None:
        raise NotImplementedError('No threads or group_size provided')
    threads_str = str(threads)
    is_single_value = threads_str.startswith('{') and threads_str.endswith('}') and (threads_str.count(',') == 0) or not threads_str.startswith(('{', '['))
    if is_single_value:
        if threads_str.startswith('{') and threads_str.endswith('}'):
            single_value = threads_str[1:-1].strip()
        else:
            single_value = threads_str
        if group_size is None:
            new_args.append(f'aoti_torch_mps_dispatch_single(handle, {single_value});')
        else:
            group_size_str = str(group_size)
            if <MASK>:
                group_size_value = group_size_str[1:-1].strip()
            else:
                group_size_value = group_size_str
            new_args.append(f'aoti_torch_mps_dispatch_single_with_group_size(handle, {single_value}, {group_size_value});')
    else:
        threads_var = f'{kernel_name}_threads_array'
        group_size_var = f'{kernel_name}_group_size_array'

        def get_array_size(array_str: str) -> int:
            content = array_str.strip()
            if content.startswith('{') and content.endswith('}'):
                content = content[1:-1].strip()
            if not content:
                return 0
            depth = 0
            comma_count = 0
            for char in content:
                if char in '({[<':
                    depth += 1
                elif char in ')}]>':
                    depth -= 1
                elif char == ',' and depth == 0:
                    comma_count += 1
            return comma_count + 1
        threads_size = get_array_size(threads_str)
        if group_size is None:
            new_args.append('{')
            new_args.append(f'    uint64_t {threads_var}[] = {threads};')
            new_args.append(f'    aoti_torch_mps_dispatch_array(handle, {threads_var}, {threads_size});')
            new_args.append('}')
        else:
            group_size_str = str(group_size)
            group_size_size = get_array_size(group_size_str)
            new_args.append('{')
            new_args.append(f'    uint64_t {threads_var}[] = {threads};')
            new_args.append(f'    uint64_t {group_size_var}[] = {group_size};')
            dispatch_args = f'handle, {threads_var}, {threads_size}, {group_size_var}, {group_size_size}'
            new_args.append(f'    aoti_torch_mps_dispatch_array_with_group_size({dispatch_args});')
            new_args.append('}')
    debug_printer_manager = V.graph.wrapper_code.debug_printer
    debug_printer_manager.set_printer_args(call_args[:-2], kernel_name, None, None, 'cpp')
    with debug_printer_manager:
        self.write_mps_kernel_call(kernel_name, new_args)

def _match_nodes(self, pn: Node, gn: Node, match: InternalMatch, node_name_match: str='') -> bool:
    logger.info('  matching %s to %s', pn, gn)
    assert isinstance(pn, Node) and isinstance(gn, Node), str(f'pn and gn must be Node, pn: {pn}, gn: {gn}')
    if pn in match.nodes_map:
        return match.nodes_map[pn] == gn
    if gn in match.nodes_map.values():
        return False
    if not self._nodes_are_equal(pn, gn, node_name_match):
        return False
    saved_match = copy.copy(match)
    match.nodes_map[pn] = gn
    if <MASK>:
        return True
    match_found = True

    def _match_args(args1: Union[list, tuple], args2: Union[list, tuple]) -> bool:
        if len(args1) != len(args2):
            return False
        for (a1, a2) in zip(args1, args2):
            if isinstance(a1, Node) and isinstance(a2, Node):
                matched = self._match_nodes(a1, a2, match)
            elif isinstance(a1, (list, tuple)) and isinstance(a2, (list, tuple)):
                matched = _match_args(a1, a2)
            else:
                matched = self._match_literals(a1, a2, match) or self.ignore_literals
            if not matched:
                return False
        return True
    (pn_args, gn_args) = (None, None)
    if (len(pn.args) != len(gn.args) or list(pn.kwargs.keys()) != list(gn.kwargs.keys())) and pn.op == 'call_function' and isinstance(pn.target, torch._ops.OpOverload):
        args_schema = pn.target._schema.arguments

        def get_all_arguments(orig_args, orig_kwargs):
            all_args = []
            for (i, schema) in enumerate(args_schema):
                if schema.name in orig_kwargs:
                    all_args.append(orig_kwargs[schema.name])
                elif not schema.kwarg_only and i < len(orig_args):
                    all_args.append(orig_args[i])
                else:
                    all_args.append(schema.default_value)
            return all_args
        pn_args = get_all_arguments(pn.args, pn.kwargs)
        gn_args = get_all_arguments(gn.args, gn.kwargs)
    elif len(pn.args) == len(gn.args) and list(pn.kwargs.keys()) == list(gn.kwargs.keys()):
        pn_args = list(pn.args)
        gn_args = list(gn.args)
        pn_args.extend(list(pn.kwargs.values()))
        gn_args.extend(list(gn.kwargs.values()))
    else:
        match_found = False
    match_found = match_found and pn_args is not None and (gn_args is not None) and _match_args(pn_args, gn_args)
    if not match_found:
        match = copy.copy(saved_match)
        return False
    return True

@final
def _drop_level_numbers(self, levnums: list[int]):
    """
        Drop MultiIndex levels by level _number_, not name.
        """
    if not levnums and (not isinstance(self, ABCMultiIndex)):
        return self
    if len(levnums) >= self.nlevels:
        raise ValueError(f'Cannot remove {len(levnums)} levels from an index with {self.nlevels} levels: at least one level must be left.')
    self = cast('MultiIndex', self)
    new_levels = list(self.levels)
    new_codes = list(self.codes)
    new_names = list(self.names)
    for i in levnums:
        new_levels.pop(i)
        new_codes.pop(i)
        new_names.pop(i)
    if len(new_levels) == 1:
        lev = new_levels[0]
        if <MASK>:
            if len(new_codes[0]) == 0:
                result = lev[:0]
            else:
                res_values = algos.take(lev._values, new_codes[0], allow_fill=True)
                result = lev._constructor._simple_new(res_values, name=new_names[0])
        else:
            mask = new_codes[0] == -1
            result = new_levels[0].take(new_codes[0])
            if mask.any():
                result = result.putmask(mask, np.nan)
            result._name = new_names[0]
        return result
    else:
        from pandas.core.indexes.multi import MultiIndex
        return MultiIndex(levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False)

def get_simplified_split_ranges(self, split_sections, next_users, user_inputs_list: list[list[torch.fx.Node | _Range]]) -> list[_Range] | None:
    ranges = OrderedSet[Any]()
    for user_inputs in user_inputs_list:
        ranges.update((u for u in user_inputs if isinstance(u, tuple)))
    cumulative_sizes = [0] + torch.cumsum(torch.tensor(split_sections), 0).tolist()
    split_ranges = sorted([(cumulative_sizes[r[0]], cumulative_sizes[r[1] + 1]) for r in ranges])
    if <MASK>:
        return None
    split_ranges = self.fill_gaps(split_ranges, 0, cumulative_sizes[-1])
    if len(split_sections) == len(split_ranges):
        return None
    counters[backend]['scmerge_split_sections_removed'] = len(split_sections) - len(split_ranges)
    return split_ranges

def is_unsupported(o):
    """Checks whether an entity is supported by AutoGraph at all."""
    if _is_known_loaded_type(o, 'wrapt', 'FunctionWrapper') or _is_known_loaded_type(o, 'wrapt', 'BoundFunctionWrapper'):
        logging.warning('{} appears to be decorated by wrapt, which is not yet supported by AutoGraph. The function will run as-is. You may still apply AutoGraph before the wrapt decorator.'.format(o))
        logging.log(2, 'Permanently allowed: %s: wrapt decorated', o)
        return True
    if _is_known_loaded_type(o, 'functools', '_lru_cache_wrapper'):
        logging.log(2, 'Permanently allowed: %s: lru_cache', o)
        return True
    if inspect_utils.isconstructor(o):
        logging.log(2, 'Permanently allowed: %s: constructor', o)
        return True
    if any((_is_of_known_loaded_module(o, m) for m in ('collections', 'pdb', 'copy', 'inspect', 're'))):
        logging.log(2, 'Permanently allowed: %s: part of builtin module', o)
        return True
    if <MASK>:
        logging.log(2, 'Permanently allowed: %s: TensorFlow plugin', o)
        return True
    return False

def _alter_column_default_sql(self, model, old_field, new_field, drop=False):
    """
        Hook to specialize column default alteration.

        Return a (sql, params) fragment to add or drop (depending on the drop
        argument) a default to new_field's column.
        """
    new_default = self.effective_default(new_field)
    default = self._column_default_sql(new_field)
    params = [new_default]
    if drop:
        params = []
    elif <MASK>:
        default = self.prepare_default(new_default)
        params = []
    new_db_params = new_field.db_parameters(connection=self.connection)
    if drop:
        if new_field.null:
            sql = self.sql_alter_column_no_default_null
        else:
            sql = self.sql_alter_column_no_default
    else:
        sql = self.sql_alter_column_default
    return (sql % {'column': self.quote_name(new_field.column), 'type': new_db_params['type'], 'default': default}, params)

def recurser(index, hanging_indent, curr_width):
    """
        By using this local function, we don't need to recurse with all the
        arguments. Since this function is not created recursively, the cost is
        not significant
        """
    axis = len(index)
    axes_left = a.ndim - axis
    if axes_left == 0:
        return format_function(a[index])
    next_hanging_indent = hanging_indent + ' '
    if legacy <= 113:
        next_width = curr_width
    else:
        next_width = curr_width - len(']')
    a_len = a.shape[axis]
    show_summary = summary_insert and 2 * edge_items < a_len
    if <MASK>:
        leading_items = edge_items
        trailing_items = edge_items
    else:
        leading_items = 0
        trailing_items = a_len
    s = ''
    if axes_left == 1:
        if legacy <= 113:
            elem_width = curr_width - len(separator.rstrip())
        else:
            elem_width = curr_width - max(len(separator.rstrip()), len(']'))
        line = hanging_indent
        for i in range(leading_items):
            word = recurser(index + (i,), next_hanging_indent, next_width)
            (s, line) = _extendLine_pretty(s, line, word, elem_width, hanging_indent, legacy)
            line += separator
        if show_summary:
            (s, line) = _extendLine(s, line, summary_insert, elem_width, hanging_indent, legacy)
            if legacy <= 113:
                line += ', '
            else:
                line += separator
        for i in range(trailing_items, 1, -1):
            word = recurser(index + (-i,), next_hanging_indent, next_width)
            (s, line) = _extendLine_pretty(s, line, word, elem_width, hanging_indent, legacy)
            line += separator
        if legacy <= 113:
            elem_width = curr_width
        word = recurser(index + (-1,), next_hanging_indent, next_width)
        (s, line) = _extendLine_pretty(s, line, word, elem_width, hanging_indent, legacy)
        s += line
    else:
        s = ''
        line_sep = separator.rstrip() + '\n' * (axes_left - 1)
        for i in range(leading_items):
            nested = recurser(index + (i,), next_hanging_indent, next_width)
            s += hanging_indent + nested + line_sep
        if show_summary:
            if legacy <= 113:
                s += hanging_indent + summary_insert + ', \n'
            else:
                s += hanging_indent + summary_insert + line_sep
        for i in range(trailing_items, 1, -1):
            nested = recurser(index + (-i,), next_hanging_indent, next_width)
            s += hanging_indent + nested + line_sep
        nested = recurser(index + (-1,), next_hanging_indent, next_width)
        s += hanging_indent + nested
    s = '[' + s[len(hanging_indent):] + ']'
    return s

def __init__(self, cache_path=None, *factors):
    self.cache_me = {}
    self.cache_private = set()
    self.cache_infile = False
    self._cache_path = None
    if self.conf_nocache:
        self.dist_log('cache is disabled by `Config`')
        return
    self._cache_hash = self.cache_hash(*factors, *self.conf_cache_factors)
    self._cache_path = cache_path
    if cache_path:
        if os.path.exists(cache_path):
            self.dist_log('load cache from file ->', cache_path)
            cache_mod = self.dist_load_module('cache', cache_path)
            if not cache_mod:
                self.dist_log('unable to load the cache file as a module', stderr=True)
            elif not hasattr(cache_mod, 'hash') or not hasattr(cache_mod, 'data'):
                self.dist_log('invalid cache file', stderr=True)
            elif self._cache_hash == cache_mod.hash:
                self.dist_log('hit the file cache')
                for (attr, val) in cache_mod.data.items():
                    setattr(self, attr, val)
                self.cache_infile = True
            else:
                self.dist_log('miss the file cache')
    if <MASK>:
        other_cache = _share_cache.get(self._cache_hash)
        if other_cache:
            self.dist_log('hit the memory cache')
            for (attr, val) in other_cache.__dict__.items():
                if attr in other_cache.cache_private or re.match(self._cache_ignore, attr):
                    continue
                setattr(self, attr, val)
    _share_cache[self._cache_hash] = self
    atexit.register(self.cache_flush)

def codegen_input_symbol_assignment(self, name: str, value: ir.TensorBox, bound_vars: OrderedSet[sympy.Symbol]):
    code = self.prefix

    @functools.cache
    def sizeof(name):
        self.codegen_input_size_var_decl(code, name)
        return f'{name}_size'

    @functools.cache
    def strideof(name):
        self.codegen_input_stride_var_decl(code, name)
        return f'{name}_stride'

    def codegen_symbol(sym_or_exp: Union[sympy.Symbol, sympy.Expr], base_name: str, name_fn: Callable[[str], str], dim: int):
        if isinstance(sym_or_exp, sympy.Symbol):
            if sym_or_exp in bound_vars:
                return
            code.writeline(f'int64_t {sym_or_exp} = {name_fn(base_name)}[{dim}];')
            bound_vars.add(sym_or_exp)
        elif isinstance(sym_or_exp, sympy.Expr):
            undefined_symbols = [sym for sym in sym_or_exp.free_symbols if sym not in bound_vars]
            if <MASK>:
                return
            from torch.utils._sympy.solve import try_solve
            free_symbol = undefined_symbols.pop()
            base_name = name_fn(base_name)
            size_symbol = sympy.Symbol(f'{base_name}_{dim}', integer=True)
            code.writeline(f'int64_t {size_symbol} = {base_name}[{dim}];')
            solution = try_solve(sympy.Eq(sym_or_exp, size_symbol), free_symbol)
            if solution is not None:
                code.writeline(f'int64_t {free_symbol} = {cexpr(solution[1])};')
                bound_vars.add(free_symbol)
            else:
                raise AssertionError(str(sympy.Eq(sym_or_exp, size_symbol)) + ' is not solvable')
    if isinstance(value, sympy.Expr):
        if not isinstance(value, sympy.Symbol) or value in bound_vars:
            return
        if value.is_integer:
            decl = 'int64_t'
        elif value.is_float:
            decl = 'double'
        else:
            raise AssertionError('Unexpected symbol type')
        code.writeline(f'{decl} {value} = {name};')
        bound_vars.add(value)
    elif isinstance(value, ir.TensorBox):
        for (dim, size) in enumerate(value.get_size()):
            codegen_symbol(size, name, sizeof, dim)
        for (dim, stride) in enumerate(value.get_stride()):
            codegen_symbol(stride, name, strideof, dim)
    elif isinstance(value, ir.TorchBindObject):
        pass
    else:
        raise AssertionError(f'Unknown value type: {type(value)}')

def gen_transposed_tile_load_store(self, name, var, index, is_store, store_mode=None):
    dtype = V.graph.get_dtype(name)
    factor = self.tiling_factor
    src = f'{var} + {cexpr_index(index)}'
    dst = '__place_holder__'
    ld_src = f'{cexpr_index(stride_at_vec_range(index, self.itervars[self.tiling_idx], self.tiling_factor))}'
    ld_dst = f'{cexpr_index(self.num_elems)}'
    if <MASK>:
        (src, dst) = (dst, src)
        (ld_src, ld_dst) = (ld_dst, ld_src)
    need_define = True
    if self.inner_is_tiling_idx ^ is_store:
        (M, N) = (self.inner_num_elems, self.outer_num_elems)
    else:
        (M, N) = (self.outer_num_elems, self.inner_num_elems)
    atomic_add = 'true' if is_store and store_mode == 'atomic_add' else 'false'
    if isinstance(M, sympy.Expr) and (not M.is_number) or (isinstance(N, sympy.Expr) and (not N.is_number)):
        load_or_store = f'transpose_mxn<{DTYPE_TO_CPP[dtype]},{atomic_add}>({src}, {ld_src}, {dst}, {ld_dst}, {cexpr_index(M)}, {cexpr_index(N)});'
    else:
        load_or_store = f'transpose_mxn<{DTYPE_TO_CPP[dtype]},{cexpr_index(M)},{cexpr_index(N)},{atomic_add}>({src}, {ld_src}, {dst}, {ld_dst});'
    if is_store:
        tile_var = self.cse.newvar()
    elif not self.cse.contains(load_or_store):
        tile_var = self.cse.generate(self.preloads, load_or_store, write=False)
    else:
        need_define = False
        tile_var = self.cse.get(load_or_store)
    if need_define:
        cpp_dtype = DTYPE_TO_CPP[dtype]
        alignas = f'alignas(std::max(std::size_t({factor}), alignof({cpp_dtype})))'
        define_line = f'{alignas} {cpp_dtype} {tile_var}[{factor}*{factor}];'
        self.preloads.writeline(define_line)
    load_or_store = load_or_store.replace('__place_holder__', str(tile_var))
    if is_store:
        self.poststores.writeline(DeferredLine(name, load_or_store))
    else:
        self.preloads.writeline(load_or_store)
    return tile_var

def make_temp_file(suffix='', prefix='', text=True):
    if <MASK>:
        _tdata.tempdir = tempfile.mkdtemp()
        _tmpdirs.append(_tdata.tempdir)
    (fid, name) = tempfile.mkstemp(suffix=suffix, prefix=prefix, dir=_tdata.tempdir, text=text)
    fo = os.fdopen(fid, 'w')
    return (fo, name)

def _lower_dynamic_weighted_ref_functional(model: GraphModule, qconfig_map: dict[str, QConfigAny]):
    """
    Traverse the graph and replace functional reference patterns with their dynamically
    quantized versions.
    Examples:
    quantize_per_tensor_dynamic - dequantize - functional linear --> linear_dynamic
    to(torch.float16) - dequantize - functional linear --> linear_dynamic_fp16
    """
    modules = dict(model.named_modules(remove_duplicate=False))
    for n in reversed(model.graph.nodes):
        func_node = n
        if func_node.op == 'call_function' and func_node.target == F.relu or (func_node.op == 'call_module' and type(modules[str(func_node.target)]) is torch.nn.ReLU):
            relu_node = func_node
            func_node = relu_node.args[0]
        else:
            relu_node = None
        if should_skip_lowering(func_node, qconfig_map):
            continue
        if func_node.op != 'call_function' or func_node.target not in DYNAMIC_LOWER_FUNCTIONAL_MAP:
            continue
        (input_dq_node, weight_dq_node, *remaining_func_args) = func_node.args
        if input_dq_node.op != 'call_method' or input_dq_node.target != 'dequantize' or weight_dq_node.op != 'call_method' or (weight_dq_node.target != 'dequantize'):
            continue
        input_dynamic_q_node = input_dq_node.args[0]
        if input_dynamic_q_node.op != 'call_function' or input_dynamic_q_node.target != torch.quantize_per_tensor_dynamic:
            continue
        reduce_range_node = None
        (pattern_input, activation_dtype, reduce_range_node) = input_dynamic_q_node.args
        is_fp16 = activation_dtype == torch.float16
        is_int8 = activation_dtype in [torch.quint8, torch.qint8]
        if not is_int8 and (not is_fp16):
            continue
        quantized_weight = weight_dq_node.args[0]
        weight_dtype = quantized_weight.args[-1]
        dynamic_quant_dtype_key = (activation_dtype, weight_dtype)
        if dynamic_quant_dtype_key not in DYNAMIC_LOWER_FUNCTIONAL_MAP[func_node.target]:
            print(f"Didn't find dtype combination {dynamic_quant_dtype_key} during dynamic quantized op lowering for {func_node.target}")
            continue
        (q_func, q_relu_func) = DYNAMIC_LOWER_FUNCTIONAL_MAP[func_node.target][dynamic_quant_dtype_key]
        if q_func is None or q_relu_func is None:
            print(f"Didn't find corresponding quantized function or quantized relu function for {func_node.target}, {dynamic_quant_dtype_key}")
            continue
        prepack_args = [quantized_weight] + remaining_func_args
        prepack_kwargs = {}
        if func_node.target == F.linear:
            prepack_op = get_linear_prepack_op_for_dtype(weight_dtype)
            kwargs = func_node.kwargs.copy()
            if 'bias' in kwargs:
                prepack_kwargs['B'] = kwargs['bias']
                del kwargs['bias']
                func_node.kwargs = kwargs
        elif <MASK>:
            prepack_op = get_qconv_prepack_op(func_node.target)
            if func_node.target == F.conv1d:
                for i in [2, 3, 4]:
                    if len(prepack_args) > i and isinstance(prepack_args[i], int):
                        prepack_args[i] = (prepack_args[i],)
        else:
            raise ValueError(f"Lowering is not supported for op '{func_node.target}'")
        with model.graph.inserting_before(func_node):
            packed_weight = model.graph.create_node('call_function', prepack_op, tuple(prepack_args), prepack_kwargs)
        func_node.target = q_relu_func if relu_node is not None else q_func
        if is_int8:
            func_node.args = (pattern_input, packed_weight, reduce_range_node)
        else:
            func_node.args = (pattern_input, packed_weight)
        if relu_node is not None:
            relu_node.replace_all_uses_with(func_node)
        if relu_node is not None:
            model.graph.erase_node(relu_node)

def __init__(self, function, cancellation_mgr, args=None, kwargs=None):
    if not callable(function):
        raise ValueError('Function passed to `ClusterCoordinator.schedule` must be a callable object.')
    self._args = args or ()
    self._kwargs = kwargs or {}
    _disallow_remote_value_as_input(self._args)
    _disallow_remote_value_as_input(self._kwargs)
    if isinstance(function, def_function.Function):
        replica_args = _select_worker_slice(0, self._args)
        replica_kwargs = _select_worker_slice(0, self._kwargs)
        with metric_utils.monitored_timer('function_tracing', state_tracker=function._get_tracing_count):
            self._concrete_function = function.get_concrete_function(*nest.map_structure(_maybe_as_type_spec, replica_args), **nest.map_structure(_maybe_as_type_spec, replica_kwargs))
    elif <MASK>:
        self._concrete_function = function
    if hasattr(self, '_concrete_function'):
        self._output_type_spec = func_graph.convert_structure_to_signature(self._concrete_function.structured_outputs)
        self._function = cancellation_mgr.get_cancelable_function(self._concrete_function)
    else:
        self._output_type_spec = None
        self._function = function
    self._output_remote_value_ref = None

def _at_k_name(name, k=None, class_id=None):
    if k is not None:
        name = '%s_at_%d' % (name, k)
    else:
        name = '%s_at_k' % name
    if <MASK>:
        name = '%s_class%d' % (name, class_id)
    return name

def build_analyzer(self):
    """Return a callable to process input data.

        The callable handles preprocessing, tokenization, and n-grams generation.

        Returns
        -------
        analyzer: callable
            A function to handle preprocessing, tokenization
            and n-grams generation.
        """
    if <MASK>:
        return partial(_analyze, analyzer=self.analyzer, decoder=self.decode)
    preprocess = self.build_preprocessor()
    if self.analyzer == 'char':
        return partial(_analyze, ngrams=self._char_ngrams, preprocessor=preprocess, decoder=self.decode)
    elif self.analyzer == 'char_wb':
        return partial(_analyze, ngrams=self._char_wb_ngrams, preprocessor=preprocess, decoder=self.decode)
    elif self.analyzer == 'word':
        stop_words = self.get_stop_words()
        tokenize = self.build_tokenizer()
        self._check_stop_words_consistency(stop_words, preprocess, tokenize)
        return partial(_analyze, ngrams=self._word_ngrams, tokenizer=tokenize, preprocessor=preprocess, decoder=self.decode, stop_words=stop_words)
    else:
        raise ValueError('%s is not a valid tokenization scheme/analyzer' % self.analyzer)

