    if <MASK>:
        state_dict = _flatten_sharded_tensors(state_dict)
    self.state_dict = state_dict
    self.is_coordinator = is_coordinator

def _bind_dims_to_size(sz: int, sd: int, dims: list, nsz: list, nsd: list) -> None:
    """
    Bind dimensions to size and calculate proper strides for dim packs.
    """
    from . import DimensionBindError
    rhs_prod = 1
    for (i, dim) in enumerate(dims):
        if not dim.is_bound:
            for j in range(i + 1, len(dims)):
                if not dims[j].is_bound:
                    raise DimensionBindError(f'cannot infer the sizes of two dimensions at once {dim!r} and {dims[j]!r}')
                rhs_prod *= dims[j].size
            if <MASK>:
                tup = tuple((dim.size if dim.is_bound else '?' for dim in dims))
                raise DimensionBindError(f'inferred dimension does not evenly fit into larger dimension: {sz} vs {tup}')
            inferred_size = sz // rhs_prod
            dim.size = inferred_size
            rhs_prod = sz
            break
        else:
            rhs_prod *= dim.size
    if rhs_prod != sz:
        tup = tuple(dims)
        raise DimensionBindError(f'Dimension sizes to do not match ({sz} != {rhs_prod}) when matching dimension pack {tup}')
    new_strides = [0] * len(dims)
    current_stride = sd
    for i in reversed(range(len(dims))):
        new_strides[i] = current_stride
        current_stride *= dims[i].size
    for i in range(len(dims)):
        nsz.append(dims[i].size)
        nsd.append(new_strides[i])

def _batchnorm_helper(g: jit_utils.GraphContext, input, weight, bias, running_mean, running_var):
    from torch.onnx._internal.torchscript_exporter.symbolic_opset9 import _var_mean
    batch_size = _get_tensor_dim_size(input, 0)
    channel_size = _get_tensor_dim_size(input, 1)
    if <MASK>:
        if channel_size is None:
            raise errors.SymbolicValueError('Unsupported: ONNX export of batch_norm for unknown channel size.', input)
        weight_value = torch.tensor([1.0] * channel_size, dtype=_type_utils.JitScalarType.from_value(input).dtype())
        weight = g.op('Constant', value_t=weight_value)
    if bias is None or _is_none(bias):
        if channel_size is None:
            raise errors.SymbolicValueError('Unsupported: ONNX export of batch_norm for unknown channel size.', input)
        bias_value = torch.tensor([0.0] * channel_size, dtype=_type_utils.JitScalarType.from_value(input).dtype())
        bias = g.op('Constant', value_t=bias_value)
    if running_mean is None or _is_none(running_mean) or running_var is None or _is_none(running_var):
        assert batch_size is not None and channel_size is not None
        reshape_in = _reshape_helper(g, input, g.op('Constant', value_t=torch.tensor([batch_size, channel_size, -1], dtype=torch.int64)))
        trans_in = g.op('Transpose', reshape_in, perm_i=[0, 2, 1])
        (running_var, running_mean) = _var_mean(g, trans_in, g.op('Constant', value_t=torch.tensor([0, 1], dtype=torch.int64)), False, False)
    return (weight, bias, running_mean, running_var)

def _get_optimizer(self, optimizer):
    """Wraps `optimizer` in `LossScaleOptimizer` if necessary."""
    if isinstance(self._dtype_policy, policy.PolicyV1):
        loss_scale = self._dtype_policy.loss_scale
    elif self._dtype_policy.name == 'mixed_float16':
        loss_scale = 'dynamic'
    else:
        loss_scale = None

    def _get_single_optimizer(opt):
        opt = optimizers.get(opt)
        if loss_scale is not None and (not isinstance(opt, lso.LossScaleOptimizer)):
            if <MASK>:
                opt = lso.LossScaleOptimizer(opt)
            else:
                opt = lso.LossScaleOptimizerV1(opt, loss_scale)
        return opt
    return nest.map_structure(_get_single_optimizer, optimizer)

def _tensordot_axes(a, axes):
    """Generates two sets of contraction axes for the two tensor arguments."""
    a_shape = a.get_shape()
    if isinstance(axes, compat.integral_types):
        if axes < 0:
            raise ValueError(f'`axes` must be at least 0. Received: {axes}.')
        if a_shape.ndims is not None:
            if axes > a_shape.ndims:
                raise ValueError(f'`axes` must not be larger than the number of dimensions of tensor {a}.  Received {axes}, vs tensor dimensions {a_shape.ndims}.')
            return (list(builtins.range(a_shape.ndims - axes, a_shape.ndims)), list(builtins.range(axes)))
        else:
            rank = array_ops.rank(a)
            return (range(rank - axes, rank, dtype=dtypes.int32), range(axes, dtype=dtypes.int32))
    elif isinstance(axes, (list, tuple)):
        if len(axes) != 2:
            raise ValueError(f'`axes` must be an integer or have length 2. Received {axes}.')
        a_axes = axes[0]
        b_axes = axes[1]
        if <MASK>:
            a_axes = [a_axes]
            b_axes = [b_axes]
        if len(a_axes) != len(b_axes):
            raise ValueError(f'Different number of contraction axes `a` and `b`, {len(a_axes)} != {len(b_axes)}.')
        return (a_axes, b_axes)
    else:
        axes = ops.convert_to_tensor(axes, name='axes', dtype=dtypes.int32)
        return (axes[0], axes[1])

def _is_valid_qlinear_lowering_pattern():

    def fn(match):
