    return fn

def _HasAnyNotNoneGrads(grads, op: ops.Operation):
    """Return true iff op has real gradient."""
    out_grads = _GetGrads(grads, op)
    for out_grad in out_grads:
        if isinstance(out_grad, (tensor_lib.Tensor, indexed_slices.IndexedSlices)):
            return True
        if out_grad and isinstance(out_grad, collections_abc.Sequence):
            if <MASK>:
                return True
    return False

def create_copy(i: int) -> list[Instruction]:
    if sys.version_info >= (3, 11):
        return [create_instruction('COPY', arg=i)]
    if <MASK>:
        return [create_instruction('DUP_TOP')]
    return [*create_swap(i), create_dup_top(), *create_swap(i + 1), *create_swap(2)]

def _convert_to_indexer(self, key, axis: AxisInt):
    """
        Convert indexing key into something we can use to do actual fancy
        indexing on a ndarray.

        Examples
        ix[:5] -> slice(0, 5)
        ix[[1,2,3]] -> [1,2,3]
        ix[['foo', 'bar', 'baz']] -> [i, j, k] (indices of foo, bar, baz)

        Going by Zen of Python?
        'In the face of ambiguity, refuse the temptation to guess.'
        raise AmbiguousIndexError with integer labels?
        - No, prefer label-based indexing
        """
    labels = self.obj._get_axis(axis)
    if isinstance(key, slice):
        return labels._convert_slice_indexer(key, kind='loc')
    if isinstance(key, tuple) and (not isinstance(labels, MultiIndex)) and (self.ndim < 2) and (len(key) > 1):
        raise IndexingError('Too many indexers')
    contains_slice = False
    if isinstance(key, tuple):
        contains_slice = any((isinstance(v, slice) for v in key))
    if is_scalar(key) or (isinstance(labels, MultiIndex) and is_hashable(key) and (not contains_slice)):
        try:
            return labels.get_loc(key)
        except LookupError:
            if <MASK>:
                if len(key) == labels.nlevels:
                    return {'key': key}
                raise
        except InvalidIndexError:
            if not isinstance(labels, MultiIndex):
                raise
        except ValueError:
            if not is_integer(key):
                raise
            return {'key': key}
    if is_nested_tuple(key, labels):
        if self.ndim == 1 and any((isinstance(k, tuple) for k in key)):
            raise IndexingError('Too many indexers')
        return labels.get_locs(key)
    elif is_list_like_indexer(key):
        if is_iterator(key):
            key = list(key)
        if com.is_bool_indexer(key):
            key = check_bool_indexer(labels, key)
            return key
        else:
            return self._get_listlike_indexer(key, axis)[1]
    else:
        try:
            return labels.get_loc(key)
        except LookupError:
            if not is_list_like_indexer(key):
                return {'key': key}
            raise

@_onnx_symbolic('aten::upsample_nearest1d', decorate=[symbolic_helper._apply_params('upsample_nearest1d', 3, 'nearest')])
@_onnx_symbolic('aten::upsample_nearest2d', decorate=[symbolic_helper._apply_params('upsample_nearest2d', 4, 'nearest')])
@_onnx_symbolic('aten::upsample_nearest3d', decorate=[symbolic_helper._apply_params('upsample_nearest3d', 5, 'nearest')])
@_onnx_symbolic('aten::upsample_linear1d', decorate=[symbolic_helper._apply_params('upsample_linear1d', 3, 'linear')])
@_onnx_symbolic('aten::upsample_bilinear2d', decorate=[symbolic_helper._apply_params('upsample_bilinear2d', 4, 'linear')])
