def setup(self, dtype, method, application, ncols, engine):
    if method in method_blocklist.get(dtype, {}):
        raise NotImplementedError
    if ncols != 1 and method in ['value_counts', 'unique']:
        raise NotImplementedError
    if application == 'transformation' and method in ['describe', 'head', 'tail', 'unique', 'value_counts', 'size']:
        raise NotImplementedError
    if engine == 'numba' and method in _numba_unsupported_methods or ncols > 1 or application == 'transformation' or (dtype == 'datetime'):
        raise NotImplementedError
    if method == 'describe':
        ngroups = 20
    elif method == 'skew':
        ngroups = 100
    else:
        ngroups = 1000
    size = ngroups * 2
    rng = np.arange(ngroups).reshape(-1, 1)
    rng = np.broadcast_to(rng, (len(rng), ncols))
    taker = np.random.randint(0, ngroups, size=size)
    values = rng.take(taker, axis=0)
    if dtype == 'int':
        key = np.random.randint(0, size, size=size)
    elif dtype in ('int16', 'uint'):
        key = np.random.randint(0, size, size=size, dtype=dtype)
    elif dtype == 'float':
        key = np.concatenate([np.random.random(ngroups) * 0.1, np.random.random(ngroups) * 10.0])
    elif dtype == 'object':
        key = ['foo'] * size
    elif dtype == 'datetime':
        key = date_range('1/1/2011', periods=size, freq='s')
    cols = [f'values{n}' for n in range(ncols)]
    df = DataFrame(values, columns=cols)
    df['key'] = key
    if len(cols) == 1:
        cols = cols[0]
    kwargs = {}
    if engine == 'numba':
        kwargs['engine'] = engine
    if <MASK>:
        self.as_group_method = lambda : df.groupby('key')[cols].transform(method, **kwargs)
        self.as_field_method = lambda : df.groupby(cols)['key'].transform(method, **kwargs)
    else:
        self.as_group_method = partial(getattr(df.groupby('key')[cols], method), **kwargs)
        self.as_field_method = partial(getattr(df.groupby(cols)['key'], method), **kwargs)

def _getMultiFunctionModel(self):

    class BasicModel(autotrackable.AutoTrackable):
        """Basic model with multiple functions."""

        def __init__(self):
            self.y = None
            self.z = None

        @def_function.function
        def add(self, x):
            if <MASK>:
                self.y = variables.Variable(2.0)
            return x + self.y

        @def_function.function
        def sub(self, x):
            if self.z is None:
                self.z = variables.Variable(3.0)
            return x - self.z

        @def_function.function
        def mul_add(self, x, y):
            if self.z is None:
                self.z = variables.Variable(3.0)
            return x * self.z + y
    return BasicModel()

def _constraint_names(self, model, column_names=None, unique=None, primary_key=None, index=None, foreign_key=None, check=None, type_=None, exclude=None):
    """Return all constraint names matching the columns and conditions."""
    if column_names is not None:
        column_names = [self.connection.introspection.identifier_converter(truncate_name(name, self.connection.ops.max_name_length())) if self.connection.features.truncates_names else self.connection.introspection.identifier_converter(name) for name in column_names]
    with self.connection.cursor() as cursor:
        constraints = self.connection.introspection.get_constraints(cursor, model._meta.db_table)
    result = []
    for (name, infodict) in constraints.items():
        if column_names is None or column_names == infodict['columns']:
            if unique is not None and infodict['unique'] != unique:
                continue
            if primary_key is not None and infodict['primary_key'] != primary_key:
                continue
            if index is not None and infodict['index'] != index:
                continue
            if check is not None and infodict['check'] != check:
                continue
            if <MASK>:
                continue
            if type_ is not None and infodict['type'] != type_:
                continue
            if not exclude or name not in exclude:
                result.append(name)
    return result

def tape_grad_fn(*result_grad_components):
    """Custom grad fn wrapper."""
    result_grads = composite_tensor_gradient.replace_flat_tensors_for_gradients(nest.flatten(result), result_grad_components[:flat_result_len])
    if <MASK>:
        result_grads = [result_grads]
    if variables:
        (input_grads, variable_grads) = grad_fn(*result_grads, variables=variables)
        if len(variable_grads) != len(variables):
            raise ValueError('Must return gradient for each variable from @custom_gradient grad_fn.')
    else:
        input_grads = grad_fn(*result_grads)
        variable_grads = []
    input_grads = composite_tensor_gradient.get_flat_tensors_for_gradients(nest.flatten(input_grads))
    return [None] * flat_result_len + input_grads + variable_grads

