@staticmethod
def _parse_signature(signature: Optional[str]) -> tuple[Optional[tuple[str, ...]], Optional[str]]:
    if <MASK>:
        return (None, None)
    match = re.search('^f\\((.*)\\) -> (.*)$', signature)
    if match is None:
        raise ValueError(f'Invalid signature: `{signature}`')
    args: tuple[str, ...] = tuple(match.groups()[0].split(', '))
    output: str = match.groups()[1].strip()
    if ',' in output:
        raise ValueError(f'Multiple return values are not currently allowed: `{output}`')
    if output == 'None':
        return (args, None)
    return (args, output)

def set_headers(self, filelike):
    """
        Set some common response headers (Content-Length, Content-Type, and
        Content-Disposition) based on the `filelike` response content.
        """
    filename = getattr(filelike, 'name', '')
    filename = filename if isinstance(filename, str) else ''
    seekable = hasattr(filelike, 'seek') and (not hasattr(filelike, 'seekable') or filelike.seekable())
    if hasattr(filelike, 'tell'):
        if <MASK>:
            initial_position = filelike.tell()
            filelike.seek(0, io.SEEK_END)
            self.headers['Content-Length'] = filelike.tell() - initial_position
            filelike.seek(initial_position)
        elif hasattr(filelike, 'getbuffer'):
            self.headers['Content-Length'] = filelike.getbuffer().nbytes - filelike.tell()
        elif os.path.exists(filename):
            self.headers['Content-Length'] = os.path.getsize(filename) - filelike.tell()
    elif seekable:
        self.headers['Content-Length'] = sum(iter(lambda : len(filelike.read(self.block_size)), 0))
        filelike.seek(-int(self.headers['Content-Length']), io.SEEK_END)
    filename = os.path.basename(self.filename or filename)
    if self._no_explicit_content_type:
        if filename:
            (content_type, encoding) = mimetypes.guess_type(filename)
            content_type = {'br': 'application/x-brotli', 'bzip2': 'application/x-bzip', 'compress': 'application/x-compress', 'gzip': 'application/gzip', 'xz': 'application/x-xz'}.get(encoding, content_type)
            self.headers['Content-Type'] = content_type or 'application/octet-stream'
        else:
            self.headers['Content-Type'] = 'application/octet-stream'
    if (content_disposition := content_disposition_header(self.as_attachment, filename)):
        self.headers['Content-Disposition'] = content_disposition

def testARange(self):
    int_values = np.arange(-3, 3).tolist()
    float_values = np.arange(-3.5, 3.5).tolist()
    all_values = int_values + float_values
    for dtype in self.all_types:
        for start in all_values:
            msg = 'dtype:{} start:{}'.format(dtype, start)
            self.match(np_array_ops.arange(start), np.arange(start), msg=msg)
            self.match(np_array_ops.arange(start, dtype=dtype), np.arange(start, dtype=dtype), msg=msg)
            for stop in all_values:
                msg = 'dtype:{} start:{} stop:{}'.format(dtype, start, stop)
                self.match(np_array_ops.arange(start, stop), np.arange(start, stop), msg=msg)
                if not isinstance(start, float) and (not isinstance(stop, float)):
                    self.match(np_array_ops.arange(start, stop, dtype=dtype), np.arange(start, stop, dtype=dtype), msg=msg)
                for step in int_values:
                    msg = 'dtype:{} start:{} stop:{} step:{}'.format(dtype, start, stop, step)
                    if <MASK>:
                        with self.assertRaises(ValueError):
                            self.match(np_array_ops.arange(start, stop, step), np.arange(start, stop, step), msg=msg)
                            if not isinstance(start, float) and (not isinstance(stop, float)):
                                self.match(np_array_ops.arange(start, stop, step, dtype=dtype), np.arange(start, stop, step, dtype=dtype), msg=msg)
                    else:
                        self.match(np_array_ops.arange(start, stop, step), np.arange(start, stop, step), msg=msg)
                        if not isinstance(start, float) and (not isinstance(stop, float)):
                            self.match(np_array_ops.arange(start, stop, step, dtype=dtype), np.arange(start, stop, step, dtype=dtype), msg=msg)

def key_averages(self, group_by_input_shapes=False, group_by_stack_n=0, group_by_overload_name=False):
    """Averages all function events over their keys.

        Args:
            group_by_input_shapes: group entries by
                (event name, input shapes) rather than just event name.
                This is useful to see which input shapes contribute to the runtime
                the most and may help with size-specific optimizations or
                choosing the best candidates for quantization (aka fitting a roof line)

            group_by_stack_n: group by top n stack trace entries

            group_by_overload_name: Differentiate operators by their overload name e.g. aten::add.Tensor
            and aten::add.out will be aggregated separately

        Returns:
            An EventList containing FunctionEventAvg objects.
        """
    if <MASK>:
        raise AssertionError('Expected tree to be built before calling key_averages')
    stats: dict[tuple[str, ...], FunctionEventAvg] = defaultdict(FunctionEventAvg)

    def get_key(event, group_by_input_shapes, group_by_stack_n, group_by_overload_name) -> tuple[str, ...]:
        key = [str(event.key), str(event.node_id), str(event.device_type), str(event.is_legacy), str(event.is_user_annotation)]
        if group_by_overload_name:
            key.append(evt.overload_name)
        if group_by_input_shapes:
            key.append(str(event.input_shapes))
        if group_by_stack_n > 0:
            key += event.stack[:group_by_stack_n]
        return tuple(key)
    for evt in self:
        stats[get_key(evt, group_by_input_shapes, group_by_stack_n, group_by_overload_name)].add(evt)
    avg_list = EventList(stats.values(), use_device=self._use_device, profile_memory=self._profile_memory, with_flops=self._with_flops)
    for evt in avg_list:
        evt.stack = evt.stack[:group_by_stack_n]
        if not group_by_input_shapes:
            evt.input_shapes = ''
        if not group_by_overload_name:
            evt.overload_name = ''
    return avg_list

def _collapse_view_helper(a: TensorLikeType, start: int, end: int, must_be_valid: Optional[str]) -> tuple[Optional[ShapeType], Optional[StrideType]]:
    assert isinstance(a, TensorLike)
    from torch.fx.experimental.symbolic_shapes import guard_or_false, guard_or_true, sym_and, sym_or
    _validate_collapse_args(a, start, end)
    if a.ndim == 0:
        shape = (1,)
        strides = (1,)
    else:
        shape = a.shape
        strides = a.stride()
    if a.ndim == 0 or end == start:
        return (shape, strides)
    valid_op = True
    if <MASK>:
        for idx in range(end - 1, start - 1, -1):
            valid_op = sym_and(valid_op, sym_or(shape[idx] == 1, shape[idx + 1] == 1, strides[idx] == strides[idx + 1] * shape[idx + 1]))
            if guard_or_false(valid_op is False):
                break
    valid_op = sym_or(valid_op, a.numel() == 0)
    if must_be_valid:
        torch._check(valid_op, lambda : must_be_valid)
    elif not guard_or_false(valid_op):
        return (None, None)
    stride = strides[end]
    for idx in range(end - 1, start - 1, -1):
        if shape[idx] != 1:
            stride = min(stride, strides[idx])
    length = shape[end]
    if guard_or_true(length != 0):
        for idx in range(end - 1, start - 1, -1):
            if guard_or_false(shape[idx] == 0):
                length = 0
                stride = 0
                break
            length = length * shape[idx]
    else:
        stride = 0
    new_shape = shape[:start] + (length,) + shape[end + 1:]
    new_strides = strides[:start] + (stride,) + strides[end + 1:]
    if guard_or_false(a.numel() == 0):
        new_strides = utils.make_contiguous_strides_for(new_shape)
    return (new_shape, new_strides)

def assertGraphContainsExactly(self, graph, kind, num_kind_nodes, consider_subgraphs=False):

    def perform_assert(graph, kind, actual, expected, consider_subgraphs):
        if actual == expected:
            return
        subgraph = 'including' if consider_subgraphs else 'excluding'
        raise AssertionError(f'{graph}\nError: graph contains {actual} {kind} nodes ({subgraph} subgraphs) but expected {expected}')
    if consider_subgraphs:
        strgraph = str(graph)
        count = strgraph.count(kind) - strgraph.count(f'with {kind}')
        perform_assert(graph, kind, count, num_kind_nodes, consider_subgraphs)
        return

    def nodes(block):
        out = []
        for node in block.nodes():
            if <MASK>:
                out.append(node)
            for block in node.blocks():
                out += nodes(block)
        return out
    out_nodes = nodes(graph)
    perform_assert(graph, kind, len(out_nodes), num_kind_nodes, consider_subgraphs)

def run_impl(self, use_fuser):
    warmups = 10
    if <MASK>:
        iters = 1000
    else:
        iters = 10
    engine = tensor_engine.get_engine()
    self.bm_jit = None
    for i in range(warmups + iters):
        if i == warmups:
            if self.device == 'cuda':
                engine.sync_cuda()
            time_start = time.time()
        if i == 0:
            if self.jit_mode == 'trace' and use_fuser:
                self.bm_jit = torch.jit.trace(self.forward, example_inputs=self.inputs, check_trace=False)
            if callable(getattr(self, 'reference', None)):
                self.check()
            else:
                print('Warning: no reference result for ', self.module())
        elif i == 1:
            if self.jit_mode == 'trace' and use_fuser and self.print_ir:
                print(self.bm_jit.graph_for(*self.inputs))
        z = self.compute()
        if self.mode == 'both':
            if self.result_grad is None:
                self.result_grad = engine.rand_like(z)
            engine.backward([z], [self.result_grad], self.grad_variables)
    if self.device == 'cuda':
        engine.sync_cuda()
    duration = time.time() - time_start
    iter_time = duration / iters
    memory_workload = self.memory_workload()
    compute_workload = self.compute_workload()
    result_dict = {'desc': self.desc(), 'us': iter_time * 1000000.0, 'sol': memory_workload['sol'] * self.dtype_to_bytes() / iter_time / 1000000000.0, 'algorithmic': memory_workload['algorithmic'] * self.dtype_to_bytes() / iter_time / 1000000000.0}
    if compute_workload:
        result_dict['compute_workload'] = compute_workload / iter_time / 1000000000.0
    self.dump_result(result_dict)

def reverse(viewname, urlconf=None, args=None, kwargs=None, current_app=None, *, query=None, fragment=None):
    if urlconf is None:
        urlconf = get_urlconf()
    resolver = get_resolver(urlconf)
    args = args or []
    kwargs = kwargs or {}
    prefix = get_script_prefix()
    if not isinstance(viewname, str):
        view = viewname
    else:
        (*path, view) = viewname.split(':')
        if <MASK>:
            current_path = current_app.split(':')
            current_path.reverse()
        else:
            current_path = None
        resolved_path = []
        ns_pattern = ''
        ns_converters = {}
        for ns in path:
            current_ns = current_path.pop() if current_path else None
            try:
                app_list = resolver.app_dict[ns]
                if current_ns and current_ns in app_list:
                    ns = current_ns
                elif ns not in app_list:
                    ns = app_list[0]
            except KeyError:
                pass
            if ns != current_ns:
                current_path = None
            try:
                (extra, resolver) = resolver.namespace_dict[ns]
                resolved_path.append(ns)
                ns_pattern += extra
                ns_converters.update(resolver.pattern.converters)
            except KeyError as key:
                if resolved_path:
                    raise NoReverseMatch("%s is not a registered namespace inside '%s'" % (key, ':'.join(resolved_path)))
                else:
                    raise NoReverseMatch('%s is not a registered namespace' % key)
        if ns_pattern:
            resolver = get_ns_resolver(ns_pattern, resolver, tuple(ns_converters.items()))
    resolved_url = resolver._reverse_with_prefix(view, prefix, *args, **kwargs)
    if query is not None:
        if isinstance(query, QueryDict):
            query_string = query.urlencode()
        else:
            query_string = urlencode(query, doseq=True)
        if query_string:
            resolved_url += '?' + query_string
    if fragment is not None:
        resolved_url += '#' + fragment
    return resolved_url

