def get_fake_values_from_nodes(tx: InstructionTranslatorBase, nodes: Any, allow_non_graph_fake: bool) -> Any:

    def visit(n: torch.fx.Node) -> Any:
        if n.op == 'call_function' and 'example_value' not in n.meta:
            return get_fake_value(n, tx, allow_non_graph_fake)
        elif <MASK>:
            assert n.target in tx.output.nn_modules
            gm = tx.output.nn_modules[n.target]
            assert isinstance(gm, torch.fx.GraphModule)
            return gm
        out = n.meta['example_value']
        if not allow_non_graph_fake and isinstance(out, torch.Tensor):
            return ensure_graph_fake(out, tx)
        return out
    return torch.fx.node.map_arg(nodes, visit)

def finalize_options(self):
    self.set_undefined_options('build', ('build_base', 'build_base'), ('build_lib', 'build_lib'), ('force', 'force'))
    if <MASK>:
        self.package = self.distribution.ext_package
    self.extensions = self.distribution.ext_modules
    self.libraries = self.distribution.libraries or []
    self.py_modules = self.distribution.py_modules or []
    self.data_files = self.distribution.data_files or []
    if self.build_src is None:
        plat_specifier = '.{}-{}.{}'.format(get_platform(), *sys.version_info[:2])
        self.build_src = os.path.join(self.build_base, 'src' + plat_specifier)
    self.py_modules_dict = {}
    if self.f2pyflags:
        if self.f2py_opts:
            log.warn('ignoring --f2pyflags as --f2py-opts already used')
        else:
            self.f2py_opts = self.f2pyflags
        self.f2pyflags = None
    if self.f2py_opts is None:
        self.f2py_opts = []
    else:
        self.f2py_opts = shlex.split(self.f2py_opts)
    if self.swigflags:
        if self.swig_opts:
            log.warn('ignoring --swigflags as --swig-opts already used')
        else:
            self.swig_opts = self.swigflags
        self.swigflags = None
    if self.swig_opts is None:
        self.swig_opts = []
    else:
        self.swig_opts = shlex.split(self.swig_opts)
    build_ext = self.get_finalized_command('build_ext')
    if self.inplace is None:
        self.inplace = build_ext.inplace
    if self.swig_cpp is None:
        self.swig_cpp = build_ext.swig_cpp
    for c in ['swig', 'swig_opt']:
        o = '--' + c.replace('_', '-')
        v = getattr(build_ext, c, None)
        if v:
            if getattr(self, c):
                log.warn('both build_src and build_ext define %s option' % o)
            else:
                log.info('using "%s=%s" option from build_ext command' % (o, v))
                setattr(self, c, v)

def grouped_mm_args(mat1: TensorBox, mat2: TensorBox, offs: Optional[TensorBox], layout=None, out_dtype=None):
    (mat1, mat2) = realize_inputs(mat1, mat2)
    if offs is not None:
        realize_inputs(offs)
    mat1_size = mat1.get_size()
    mat2_size = mat2.get_size()
    (m1dim, m2dim) = (len(mat1_size), len(mat2_size))
    assert m1dim == 2 or m1dim == 3
    assert m2dim == 2 or m2dim == 3
    if layout is None:
        from torch._inductor.ir import FixedLayout
        if out_dtype is None:
            out_dtype = mat1.get_dtype()
        alignment = 16 // out_dtype.itemsize
        if m1dim == 2:
            if m2dim == 2:
                assert offs is not None
                out_size = [offs.get_size()[0], mat1_size[0], mat2_size[1]]
            else:
                out_size = [mat1_size[0], mat2_size[-1]]
        elif m2dim == 2:
            out_size = [mat1_size[1], mat2_size[1]]
        else:
            out_size = [mat1_size[0], mat1_size[1], mat2_size[-1]]
        size_padded = (out_size[-1] + alignment - 1) // alignment * alignment
        if <MASK>:
            out_stride = [size_padded, 1]
        else:
            out_stride = [out_size[1] * size_padded, size_padded, 1]
        layout = FixedLayout(mat1.get_device(), out_dtype, out_size, out_stride)
    else:
        assert out_dtype is None, 'out_dtype is ignored if layout is specified.'
    return (mat1_size, mat2_size, layout, mat1, mat2, offs)

def var_getattr(self, tx: 'InstructionTranslator', name):
    from ..utils import numpy_attr_wrapper
    from .builder import wrap_fx_proxy
    result = None
    example_value = self.as_proxy().node.meta['example_value']
    example_ndarray = tnp.ndarray(example_value)

    def insert_into_graph():
        return wrap_fx_proxy(tx, tx.output.create_proxy('call_function', numpy_attr_wrapper, (self.as_proxy(), name), {}))
    if <MASK>:
        proxy = tx.output.create_proxy('call_function', numpy_attr_wrapper, (self.as_proxy(), name), {})
        result = NumpyNdarrayVariable.create(tx, proxy)
    elif name in ('ndim', 'itemsize'):
        return ConstantVariable.create(getattr(example_ndarray, name))
    elif name in ('shape', 'stride'):
        if not has_free_symbols((r := getattr(example_ndarray, name))):
            return ConstantVariable.create(tuple((int(r) for r in r)))
        return insert_into_graph()
    elif name == 'size':
        if not has_free_symbols((r := example_ndarray.size)):
            return ConstantVariable.create(int(r))
        return insert_into_graph()
    elif name in ['base', 'flags', 'dtype']:
        unimplemented_v2(gb_type='Unsupported ndarray attribute access', context=f'var_getattr {self} {name}', explanation=f'Dynamo currently does not support tracing `ndarray.{name}`.', hints=[])
    elif name == '__version__':
        unimplemented_v2(gb_type='Unsupported ndarray.__version__ access', context=f'var_getattr {self} {name}', explanation=f'Dynamo currently does not support tracing `ndarray.{name}`.', hints=[])
    if result is None:
        raise NotImplementedError
    return result

def _ExtractAttrProto(op_type_name, op_def, attrs, attr_protos):
    """Extracts `attr_protos`. For use in _apply_op_helper."""
    for attr_def in op_def.attr:
        key = attr_def.name
        value = attrs[key]
        if attr_def.HasField('default_value') and value is None:
            attr_value = attr_value_pb2.AttrValue()
            attr_value.CopyFrom(attr_def.default_value)
            attr_protos[key] = attr_value
            continue
        attr_value = value_to_attr_value(value, attr_def.type, key)
        if attr_def.type.startswith('list('):
            _SatisfiesLengthConstraint(len(value), attr_def, key, op_type_name)
        if attr_def.HasField('allowed_values'):
            if attr_def.type == 'string':
                _SatisfiesAllowedStringsConstraint(attr_value.s, attr_def, key, op_type_name)
            elif attr_def.type == 'list(string)':
                for value in attr_value.list.s:
                    _SatisfiesAllowedStringsConstraint(value, attr_def, key, op_type_name)
        if <MASK>:
            _SatisfiesIntMinimumConstraint(attr_value.i, attr_def, key, op_type_name)
        if attr_def.type == 'type':
            _SatisfiesTypeConstraint(attr_value.type, attr_def, key)
        if attr_def.type == 'list(type)':
            for value in attr_value.list.type:
                _SatisfiesTypeConstraint(value, attr_def, key)
        attr_protos[key] = attr_value

def assemble(instructions: list[Instruction], firstlineno: int) -> tuple[bytes, bytes]:
    """Do the opposite of dis.get_instructions()"""
    code: list[int] = []
    if sys.version_info >= (3, 11):
        (lnotab, update_lineno) = linetable_311_writer(firstlineno)
        num_ext = 0
        for (i, inst) in enumerate(instructions):
            if <MASK>:
                inst_size = 1
                num_ext += 1
                for j in (1, 2, 3):
                    if instructions[i + j].opname != 'EXTENDED_ARG':
                        inst.positions = instructions[i + j].positions
                        break
            else:
                inst_size = instruction_size(inst) // 2 + num_ext
                num_ext = 0
            update_lineno(inst.positions, inst_size)
            num_ext = 0
            arg = inst.arg or 0
            code.extend((inst.opcode, arg & 255))
            for _ in range(instruction_size(inst) // 2 - 1):
                code.extend((0, 0))
    else:
        (lnotab, update_lineno, end) = linetable_writer(firstlineno)
        for inst in instructions:
            if inst.starts_line is not None:
                update_lineno(inst.starts_line, len(code))
            arg = inst.arg or 0
            code.extend((inst.opcode, arg & 255))
        end(len(code))
    return (bytes(code), bytes(lnotab))

def extractIndices(index: Any, indices: list) -> bool:
    if <MASK>:
        indices.extend(index)
        return True
    elif isinstance(index, torch.Tensor):
        indices.append(index)
        return False
    elif not hasattr(index, '__iter__') or isinstance(index, (str, bytes)):
        indices.append(index)
        return False
    if isinstance(index, list):
        if len(index) >= 32:
            indices.extend(index)
            return True
        for item in index:
            if isinstance(item, (torch.Tensor, slice)) or hasattr(item, '__iter__') or item is ... or (item is None) or has_dims(item):
                indices.extend(index)
                return True
        indices.append(index)
        return False
    indices.append(index)
    return False

def process_forward_inputs(self, *args, **kwargs):
    signature = self.module_call_graph[0].signature
    reordered_kwargs = kwargs
    if kwargs:
        reordered_kwargs = reorder_kwargs(kwargs, signature.in_spec)
    (flat_args_with_path, in_spec) = pytree.tree_flatten_with_path((args, reordered_kwargs))
    flat_args = [x[1] for x in flat_args_with_path]
    if is_fx_symbolic_tracing():
        return flat_args
    if <MASK>:
        if not self.adapted:
            print(f"Input treespec does not match with exported module's: \nInput treespec: {in_spec}. ", f'Exported module treespec: {signature.in_spec}')
            print("Adapting flat arg to match exported module's treespec")
        flat_args = self._adapt_flat_args(flat_args, in_spec, args)
        self.adapted = True
    if self.check_input_constraints:
        from torch._export.utils import _check_input_constraints_for_graph
        if self.adapted is True:
            flat_arg_paths = self.flat_args_adapter.get_flat_arg_paths() if self.flat_args_adapter else []
            assert not flat_arg_paths or len(flat_arg_paths) == len(flat_args)
            new_flat_args_with_path = [((SequenceKey(idx=idx), GetAttrKey(name=flat_arg_paths[idx] if flat_arg_paths else '<unknown location>')), arg) for (idx, arg) in enumerate(flat_args)]
        else:
            new_flat_args_with_path = flat_args_with_path
        _check_input_constraints_for_graph(self.input_placeholders, new_flat_args_with_path, self.range_constraints)
    return flat_args

def _reductions(func: Callable, values: np.ndarray, mask: npt.NDArray[np.bool_], *, skipna: bool=True, min_count: int=0, axis: AxisInt | None=None, **kwargs):
    """
    Sum, mean or product for 1D masked array.

    Parameters
    ----------
    func : np.sum or np.prod
    values : np.ndarray
        Numpy array with the values (can be of any dtype that support the
        operation).
    mask : np.ndarray[bool]
        Boolean numpy array (True values indicate missing values).
    skipna : bool, default True
        Whether to skip NA.
    min_count : int, default 0
        The required number of valid values to perform the operation. If fewer than
        ``min_count`` non-NA values are present the result will be NA.
    axis : int, optional, default None
    """
    if not skipna:
        if mask.any() or check_below_min_count(values.shape, None, min_count):
            return libmissing.NA
        else:
            return func(values, axis=axis, **kwargs)
    else:
        if <MASK>:
            return libmissing.NA
        if values.dtype == np.dtype(object):
            values = values[~mask]
            return func(values, axis=axis, **kwargs)
        return func(values, where=~mask, axis=axis, **kwargs)

def save(self, output_saved_model_dir):
    """Save the converted graph as a SavedModel.

    Args:
      output_saved_model_dir: construct a SavedModel using the converted
        GraphDef and save it to the specified directory. This option only works
        when the input graph is loaded from a SavedModel, i.e. when
        input_saved_model_dir is specified and input_graph_def is None in
        __init__().

    Raises:
      ValueError: if the input to the converter is a GraphDef instead of a
      SavedModel.
    """
    assert self._converted
    if <MASK>:
        assert self._calibration_data_collected
    if self._input_graph_def:
        raise ValueError('Not able to save to a SavedModel since input is a GraphDef')

    def _restore_collections(dest_graph, src_meta_graph_def, collection_keys):
        """Restores collections that we need to keep."""
        scope = ''
        for key in collection_keys:
            collection_def = src_meta_graph_def.collection_def[key]
            kind = collection_def.WhichOneof('kind')
            if kind is None:
                logging.error('Cannot identify data type for collection %s. Skipping.', key)
                continue
            from_proto = ops.get_from_proto_function(key)
            if from_proto and kind == 'bytes_list':
                proto_type = ops.get_collection_proto_type(key)
                for value in collection_def.bytes_list.value:
                    proto = proto_type()
                    proto.ParseFromString(value)
                    try:
                        new_value = from_proto(proto, import_scope=scope)
                    except:
                        continue
                    dest_graph.add_to_collection(key, new_value)
            else:
                field = getattr(collection_def, kind)
                if kind == 'node_list':
                    for value in field.value:
                        name = ops.prepend_name_scope(value, scope)
                        try:
                            col_op = dest_graph.as_graph_element(name)
                        except (TypeError, ValueError, KeyError):
                            continue
                        dest_graph.add_to_collection(key, col_op)
                elif kind == 'int64_list':
                    for value in field.value:
                        dest_graph.add_to_collection(key, int(value))
                else:
                    for value in field.value:
                        dest_graph.add_to_collection(key, ops.prepend_name_scope(value, scope))
    saved_model_builder = builder.SavedModelBuilder(output_saved_model_dir)
    with ops.Graph().as_default():
        importer.import_graph_def(self._converted_graph_def, name='')
        _restore_collections(ops.get_default_graph(), self._grappler_meta_graph_def, self._collections_to_keep(self._grappler_meta_graph_def.collection_def))
        with session.Session() as sess:
            saved_model_builder.add_meta_graph_and_variables(sess, self._input_saved_model_tags, signature_def_map=self._grappler_meta_graph_def.signature_def)
    saved_model_builder.save()

def _build_internal(self, names_to_saveables, reshape=False, sharded=False, max_to_keep=5, keep_checkpoint_every_n_hours=10000.0, name=None, restore_sequentially=False, filename='model', build_save=True, build_restore=True):
    """build() with option to only perform save and restore."""
    if not context.executing_eagerly() and (not build_save or not build_restore):
        raise ValueError('save and restore operations need to be built together  when eager execution is not enabled.')
    if not isinstance(names_to_saveables, dict):
        names_to_saveables = saveable_object_util.op_list_to_dict(names_to_saveables)
    saveables = saveable_object_util.validate_and_slice_inputs(names_to_saveables)
    if <MASK>:
        max_to_keep = 0
    with ops.name_scope(name, 'save', [saveable.op for saveable in saveables]) as name:
        filename_tensor = array_ops.placeholder_with_default(filename or 'model', shape=(), name='filename')
        filename_tensor = array_ops.placeholder_with_default(filename_tensor, shape=(), name='Const')
        if sharded:
            per_device = self._GroupByDevices(saveables)
            if build_save:
                save_tensor = self._AddShardedSaveOps(filename_tensor, per_device)
            if build_restore:
                restore_op = self._AddShardedRestoreOps(filename_tensor, per_device, restore_sequentially, reshape)
        else:
            if build_save:
                save_tensor = self._AddSaveOps(filename_tensor, saveables)
            if build_restore:
                restore_op = self._AddRestoreOps(filename_tensor, saveables, restore_sequentially, reshape)
    if context.executing_eagerly():
        save_tensor_name = save_tensor.numpy() if build_save else ''
        return saver_pb2.SaverDef(filename_tensor_name=filename_tensor.numpy(), save_tensor_name=save_tensor_name, restore_op_name='', max_to_keep=max_to_keep, sharded=sharded, keep_checkpoint_every_n_hours=keep_checkpoint_every_n_hours, version=self._write_version)
    else:
        graph = ops.get_default_graph()
        check_collection_list = graph.get_all_collection_keys()
        for collection_type in check_collection_list:
            for element in graph.get_collection(collection_type):
                if isinstance(element, variables.PartitionedVariable):
                    try:
                        graph.get_operation_by_name(element.name)
                    except KeyError:
                        element.as_tensor()
        return saver_pb2.SaverDef(filename_tensor_name=filename_tensor.name, save_tensor_name=save_tensor.name, restore_op_name=restore_op.name, max_to_keep=max_to_keep, sharded=sharded, keep_checkpoint_every_n_hours=keep_checkpoint_every_n_hours, version=self._write_version)

def reorder(self, on_ambiguity=ambiguity_warn):
    self._ordering = od = ordering(self.funcs)
    amb = ambiguities(self.funcs)
    if <MASK>:
        on_ambiguity(self, amb)
    return od

def lazy_binding_method(cpp_module, *args):

    def init_fn(script_module):
        orig_class = concrete_type.py_class
        for name in dir(orig_class):
            item = getattr(orig_class, name, None)
            if <MASK>:
                setattr(script_module, name, item)
        for (name, value) in concrete_type.get_constants().items():
            setattr(script_module, name, value)
    script_module = torch.jit.RecursiveScriptModule._construct(cpp_module, init_fn)
    method = types.MethodType(unbound_method, script_module)
    return method(*args)

