def handle(self, **options):
    db = options['database']
    include_stale_apps = options['include_stale_apps']
    interactive = options['interactive']
    verbosity = options['verbosity']
    if not router.allow_migrate_model(db, ContentType):
        return
    ContentType.objects.clear_cache()
    apps_content_types = itertools.groupby(ContentType.objects.using(db).order_by('app_label', 'model'), lambda obj: obj.app_label)
    for (app_label, content_types) in apps_content_types:
        if not include_stale_apps and app_label not in apps.app_configs:
            continue
        to_remove = [ct for ct in content_types if ct.model_class() is None]
        using = router.db_for_write(ContentType)
        if to_remove:
            if <MASK>:
                ct_info = []
                for ct in to_remove:
                    ct_info.append('    - Content type for %s.%s' % (ct.app_label, ct.model))
                    collector = Collector(using=using, origin=ct, force_collection=True)
                    collector.collect([ct])
                    for (obj_type, objs) in collector.data.items():
                        if objs != {ct}:
                            ct_info.append('    - %s %s object(s)' % (len(objs), obj_type._meta.label))
                content_type_display = '\n'.join(ct_info)
                self.stdout.write(f"Some content types in your database are stale and can be deleted.\nAny objects that depend on these content types will also be deleted.\nThe content types and dependent objects that would be deleted are:\n\n{content_type_display}\n\nThis list doesn't include any cascade deletions to data outside of Django\nmodels (uncommon).\n\nAre you sure you want to delete these content types?\nIf you're unsure, answer 'no'.")
                ok_to_delete = input("Type 'yes' to continue, or 'no' to cancel: ")
            else:
                ok_to_delete = 'yes'
            if ok_to_delete == 'yes':
                for ct in to_remove:
                    if verbosity >= 2:
                        self.stdout.write("Deleting stale content type '%s | %s'" % (ct.app_label, ct.model))
                    ct.delete()
            elif verbosity >= 2:
                self.stdout.write('Stale content types remain.')

@numba.jit(nopython=True, nogil=True, parallel=False)
def remove_var(val: float, nobs: int, mean_x: float, ssqdm_x: float, compensation: float) -> tuple[int, float, float, float]:
    if not np.isnan(val):
        nobs -= 1
        if <MASK>:
            prev_mean = mean_x - compensation
            y = val - compensation
            t = y - mean_x
            compensation = t + mean_x - y
            delta = t
            mean_x -= delta / nobs
            ssqdm_x -= (val - prev_mean) * (val - mean_x)
        else:
            mean_x = 0
            ssqdm_x = 0
    return (nobs, mean_x, ssqdm_x, compensation)

def _validate_arguments(num_mel_bins, sample_rate, lower_edge_hertz, upper_edge_hertz, dtype):
    """Checks the inputs to linear_to_mel_weight_matrix."""
    if num_mel_bins <= 0:
        raise ValueError('num_mel_bins must be positive. Got: %s' % num_mel_bins)
    if lower_edge_hertz < 0.0:
        raise ValueError('lower_edge_hertz must be non-negative. Got: %s' % lower_edge_hertz)
    if lower_edge_hertz >= upper_edge_hertz:
        raise ValueError('lower_edge_hertz %.1f >= upper_edge_hertz %.1f' % (lower_edge_hertz, upper_edge_hertz))
    if not isinstance(sample_rate, tensor.Tensor):
        if <MASK>:
            raise ValueError('sample_rate must be positive. Got: %s' % sample_rate)
        if upper_edge_hertz > sample_rate / 2:
            raise ValueError('upper_edge_hertz must not be larger than the Nyquist frequency (sample_rate / 2). Got %s for sample_rate: %s' % (upper_edge_hertz, sample_rate))
    if not dtype.is_floating:
        raise ValueError('dtype must be a floating point type. Got: %s' % dtype)

def _linkcode_resolve(domain, info, package, url_fmt, revision):
    """Determine a link to online source for a class/method/function

    This is called by sphinx.ext.linkcode

    An example with a long-untouched module that everyone has
    >>> _linkcode_resolve('py', {'module': 'tty',
    ...                          'fullname': 'setraw'},
    ...                   package='tty',
    ...                   url_fmt='https://hg.python.org/cpython/file/'
    ...                           '{revision}/Lib/{package}/{path}#L{lineno}',
    ...                   revision='xxxx')
    'https://hg.python.org/cpython/file/xxxx/Lib/tty/tty.py#L18'
    """
    if revision is None:
        return
    if domain not in ('py', 'pyx'):
        return
    if not info.get('module') or not info.get('fullname'):
        return
    class_name = info['fullname'].split('.')[0]
    module = __import__(info['module'], fromlist=[class_name])
    obj = attrgetter(info['fullname'])(module)
    obj = inspect.unwrap(obj)
    try:
        fn = inspect.getsourcefile(obj)
    except Exception:
        fn = None
    if <MASK>:
        try:
            fn = inspect.getsourcefile(sys.modules[obj.__module__])
        except Exception:
            fn = None
    if not fn:
        return
    try:
        fn = os.path.relpath(fn, start=os.path.dirname(__import__(package).__file__))
    except ValueError:
        return None
    try:
        lineno = inspect.getsourcelines(obj)[1]
    except Exception:
        lineno = ''
    return url_fmt.format(revision=revision, package=package, path=fn, lineno=lineno)

def signature_str_pyi(self, *, skip_outputs: bool=False) -> str:
    args = self.arguments(skip_outputs=skip_outputs)
    schema_formals: list[str] = [a.argument_str_pyi(method=self.method) for a in args]
    positional_argc = len(self.input_args)
    if len(schema_formals) > positional_argc:
        schema_formals.insert(positional_argc, '*')
    returns_str = returns_str_pyi(self)
    if <MASK>:
        schema_formals.insert(0, 'self')
    return format_function_signature(self.name, schema_formals, returns_str)

def _test_broadcast_helper(self, group, group_id, rank, cuda=False, rank_to_GPU=None, with_options=False):
    for (dtype, value, requires_cuda) in [(torch.float, -1e-10, False), (torch.double, -1e-100, False), (torch.half, -0.1, True), (torch.int8, -2, False), (torch.uint8, 129, False), (torch.int, -100000.0, False), (torch.long, -1000000000000000.0, False)]:
        if requires_cuda and (not cuda):
            continue
        for src in group:
            expected_tensor = _build_tensor(src + 1, value, dtype)
            if cuda:
                expected_tensor = expected_tensor.cuda(rank_to_GPU[rank][0])
            if <MASK>:
                if with_options:
                    opts = dist.BroadcastOptions()
                    opts.rootTensor = 0
                    opts.rootRank = src
                    self.call_dist_op(':broadcast', True, group_id.broadcast, [expected_tensor], opts)
                else:
                    self.call_dist_op(':broadcast', False, dist.broadcast, expected_tensor, src, group_id)
            else:
                tensor = _build_tensor(src + 1, -1, dtype)
                if cuda:
                    tensor = tensor.cuda(rank_to_GPU[rank][0])
                if with_options:
                    opts = dist.BroadcastOptions()
                    opts.rootTensor = 0
                    opts.rootRank = src
                    self.call_dist_op(':broadcast', True, group_id.broadcast, [tensor], opts)
                else:
                    self.call_dist_op(':broadcast', False, dist.broadcast, tensor, src, group_id)
                self.assertEqual(tensor.size(), expected_tensor.size())
                self.assertEqual(tensor.ne(expected_tensor).max(), torch.tensor(False))
    self._barrier()

def _cmp_method(self, other, op):
    if is_list_like(other):
        if len(self) != len(other):
            raise ValueError('Lengths must match to compare')
        other = pd_array(other)
    elif <MASK>:
        if other is NA:
            from pandas.core.arrays import BooleanArray
            arr = np.empty(self.shape, dtype=bool)
            mask = np.ones(self.shape, dtype=bool)
            return BooleanArray(arr, mask)
        return invalid_comparison(self, other, op)
    if isinstance(other, Interval):
        other_dtype = pandas_dtype('interval')
    elif not isinstance(other.dtype, CategoricalDtype):
        other_dtype = other.dtype
    else:
        other_dtype = other.categories.dtype
        if isinstance(other_dtype, IntervalDtype):
            if self.closed != other.categories.closed:
                return invalid_comparison(self, other, op)
            other = other.categories._values.take(other.codes, allow_fill=True, fill_value=other.categories._na_value)
    if isinstance(other_dtype, IntervalDtype):
        if self.closed != other.closed:
            return invalid_comparison(self, other, op)
        elif not isinstance(other, Interval):
            other = type(self)(other)
        if op is operator.eq:
            return (self._left == other.left) & (self._right == other.right)
        elif op is operator.ne:
            return (self._left != other.left) | (self._right != other.right)
        elif op is operator.gt:
            return (self._left > other.left) | (self._left == other.left) & (self._right > other.right)
        elif op is operator.ge:
            return (self == other) | (self > other)
        elif op is operator.lt:
            return (self._left < other.left) | (self._left == other.left) & (self._right < other.right)
        else:
            return (self == other) | (self < other)
    if not is_object_dtype(other_dtype):
        return invalid_comparison(self, other, op)
    result = np.zeros(len(self), dtype=bool)
    for (i, obj) in enumerate(other):
        try:
            result[i] = op(self[i], obj)
        except TypeError:
            if obj is NA:
                result = result.astype(object)
                result[i] = NA
            else:
                raise
    return result

def bound_sympy(expr: sympy.Expr, ranges: Optional[dict[sympy.Symbol, ValueRanges]]=None) -> ValueRanges:
    log.debug('bound_sympy(%s)%s', expr, LazyString(lambda : '\n' + '\n'.join((f'  {k}: {r}' for (k, r) in ranges.items() if k in expr.free_symbols)) if ranges else ''))
    if isinstance(expr, sympy.Number):
        return ValueRanges.wrap(expr)
    ranges = ranges or {}
    context = torch._guards.TracingContext.try_get()
    if context and context.fake_mode and context.fake_mode.shape_env:
        if <MASK>:
            ranges = {**context.fake_mode.shape_env.var_to_range, **ranges}
        else:
            ranges = context.fake_mode.shape_env.var_to_range

    def missing_handler(s):
        if s.is_integer:
            if s.is_positive:
                vr = ValueRanges(1, int_oo)
            elif s.is_nonnegative:
                vr = ValueRanges(0, int_oo)
            else:
                vr = ValueRanges.unknown_int()
        else:
            vr = ValueRanges.unknown()
        return vr
    return sympy_interp(SymPyValueRangeAnalysis, ranges, expr, missing_handler=missing_handler)

def _array_repr_implementation(arr, max_line_width=None, precision=None, suppress_small=None, array2string=array2string):
    """Internal version of array_repr() that allows overriding array2string."""
    current_options = format_options.get()
    override_repr = current_options['override_repr']
    if override_repr is not None:
        return override_repr(arr)
    if <MASK>:
        max_line_width = current_options['linewidth']
    if type(arr) is not ndarray:
        class_name = type(arr).__name__
    else:
        class_name = 'array'
    prefix = class_name + '('
    if current_options['legacy'] <= 113 and arr.shape == () and (not arr.dtype.names):
        lst = repr(arr.item())
    else:
        lst = array2string(arr, max_line_width, precision, suppress_small, ', ', prefix, suffix=')')
    extras = []
    if arr.size == 0 and arr.shape != (0,) or (current_options['legacy'] > 210 and arr.size > current_options['threshold']):
        extras.append(f'shape={arr.shape}')
    if not dtype_is_implied(arr.dtype) or arr.size == 0:
        extras.append(f'dtype={dtype_short_repr(arr.dtype)}')
    if not extras:
        return prefix + lst + ')'
    arr_str = prefix + lst + ','
    extra_str = ', '.join(extras) + ')'
    last_line_len = len(arr_str) - (arr_str.rfind('\n') + 1)
    spacer = ' '
    if current_options['legacy'] <= 113:
        if issubclass(arr.dtype.type, flexible):
            spacer = '\n' + ' ' * len(prefix)
    elif last_line_len + len(extra_str) + 1 > max_line_width:
        spacer = '\n' + ' ' * len(prefix)
    return arr_str + spacer + extra_str

def reorder_loops_by_dep_pair(self, self_dep: MemoryDep, other_dep: MemoryDep) -> bool:
    new_order = None
    self_sizes = self._sizes[0]
    if len(self_sizes) == self_dep.num_vars == other_dep.num_vars:
        new_order = self_dep.decide_loop_order_to_match(other_dep)
    if <MASK>:
        metrics.num_loop_reordering += 1
        loop_ordering_log.debug('Reorder loops for %s with order %s', self.get_name(), new_order)
        self.apply_new_loop_order(new_order)
        return True
    else:
        loop_ordering_log.debug("Don't reordering %s because we can not decide the suitable loop order", self.get_name())
        return False

def _schedule_collectives_for_overlap(self, compute_node: fx.Node, available_compute_time: float) -> None:
    """Opportunistically schedule collectives that can be hidden by compute."""
    compute_ancestors = self.node_ancestors[compute_node]
    possible_collectives = []
    for collective in self.unscheduled_collectives:
        distance = abs(self.node_idx[compute_node] - self.node_idx[collective])
        if distance > self.max_node_distance:
            break
        if <MASK>:
            if self.compute_index_domination[collective] - self.current_compute_index > self.max_compute_pre_fetch:
                continue
        possible_collectives.append(collective)
    possible_collectives = sorted(possible_collectives, key=lambda n: (self.compute_index_domination[n], self.node_idx[n]))
    log.debug('Scheduling collectives for overlap: compute_node=%s, available_time=%.2f ms, candidates=%d, current_memory=%d bytes', compute_node.name, available_compute_time, len(possible_collectives), self.memory_tracker.current_memory_bytes)
    for collective in possible_collectives:
        if available_compute_time == 0:
            break
        info = self.collective_info[collective]
        if collective in compute_ancestors or compute_node in self.node_ancestors[collective]:
            continue
        while self.in_flight and self.max_in_flight_bytes - self.in_flight_bytes < info.size_bytes and self._wait_is_hidden(self._get_oldest_wait(), compute_node):
            self._force_oldest_wait()
        if self.max_in_flight_bytes - self.in_flight_bytes < info.size_bytes:
            continue
        path = self._find_schedulable_path(collective, compute_node)
        if path is None:
            continue
        log.debug('Overlapping collective %s with compute %s: coll_domination=%d, current_depth=%d', collective.name, compute_node.name, self.compute_index_domination[collective], self.current_compute_index)
        self._schedule_path_to_collective(path, compute_node)
        self._handle_collective_start(collective)
        overlap_amount = min(available_compute_time, info.exposed_time_ms)
        info.exposed_time_ms -= overlap_amount
        if info.exposed_time_ms == 0:
            info.hiding_node = compute_node
        available_compute_time -= overlap_amount

def _compute_task_and_cores_to_replicas(core_assignment, topology):
    """Computes a nested dict which maps task and logical core to replicas."""
    task_and_cores_to_replicas = {}
    for replica in range(core_assignment.shape[0]):
        for logical_core in range(core_assignment.shape[1]):
            coordinates = core_assignment[replica, logical_core, :]
            task_id = topology.task_ordinal_at_coordinates(coordinates)
            if task_id not in task_and_cores_to_replicas:
                task_and_cores_to_replicas[task_id] = {}
            if <MASK>:
                task_and_cores_to_replicas[task_id][logical_core] = set()
            task_and_cores_to_replicas[task_id][logical_core].add(replica)
    task_to_sorted_replica_id = {}
    for (task, core_to_replicas) in task_and_cores_to_replicas.items():
        core_to_sorted_replicas = {}
        for (core, replicas) in core_to_replicas.items():
            core_to_sorted_replicas[core] = sorted(replicas)
        task_to_sorted_replica_id[task] = core_to_sorted_replicas
    return task_to_sorted_replica_id

def _get_object_parser(self, json: str) -> DataFrame | Series:
    """
        Parses a json document into a pandas object.
        """
    typ = self.typ
    dtype = self.dtype
    kwargs = {'orient': self.orient, 'dtype': self.dtype, 'convert_axes': self.convert_axes, 'convert_dates': self.convert_dates, 'keep_default_dates': self.keep_default_dates, 'precise_float': self.precise_float, 'date_unit': self.date_unit, 'dtype_backend': self.dtype_backend}
    if typ == 'frame':
        return FrameParser(json, **kwargs).parse()
    elif <MASK>:
        if not isinstance(dtype, bool):
            kwargs['dtype'] = dtype
        return SeriesParser(json, **kwargs).parse()
    else:
        raise ValueError(f"typ={typ!r} must be 'frame' or 'series'.")

def get_cpp_torch_device_options(device_type: str, aot_mode: bool=False, compile_only: bool=False) -> tuple[list[str], list[str], list[str], list[str], list[str], list[str], list[str]]:
    """
    This function is used to get the build args of device related build options.
    1. Device include_directories, libraries, libraries_directories.
    2. Device MACROs.
    3. MISC
    4. Return the build args
    """
    definitions: list[str] = []
    include_dirs: list[str] = []
    cflags: list[str] = []
    ldflags: list[str] = []
    libraries_dirs: list[str] = []
    libraries: list[str] = []
    passthrough_args: list[str] = []
    if config.is_fbcode() and 'CUDA_HOME' not in os.environ and ('CUDA_PATH' not in os.environ):
        os.environ['CUDA_HOME'] = build_paths.sdk_home
    _set_gpu_runtime_env()
    from torch.utils import cpp_extension
    include_dirs = cpp_extension.include_paths(device_type, config.aot_inductor.link_libtorch is None)
    link_libtorch = config.aot_inductor.link_libtorch
    libraries_dirs = cpp_extension.library_paths(device_type, torch_include_dirs=link_libtorch, cross_target_platform=config.aot_inductor.cross_target_platform)
    if not config.is_fbcode() and link_libtorch:
        libraries += ['c10']
    if device_type == 'cuda':
        definitions.append(' USE_ROCM' if torch.version.hip else ' USE_CUDA')
        if torch.version.hip is not None:
            if config.is_fbcode() or not link_libtorch:
                libraries += ['amdhip64']
            else:
                libraries += ['c10_hip', 'torch_hip']
            definitions.append(' __HIP_PLATFORM_AMD__')
        else:
            if config.is_fbcode() or not link_libtorch:
                libraries += ['cuda']
            else:
                libraries += ['c10_cuda', 'cuda', 'torch_cuda']
            if config.aot_inductor.cross_target_platform == 'windows':
                libraries += ['cudart']
            _transform_cuda_paths(libraries_dirs)
    if device_type == 'xpu':
        definitions.append(' USE_XPU')
        xpu_error_string = 'Intel GPU driver is not properly installed, please follow the instruction in https://github.com/pytorch/pytorch?tab=readme-ov-file#intel-gpu-support.'
        if _IS_WINDOWS:
            ze_root = os.getenv('LEVEL_ZERO_V1_SDK_PATH')
            if ze_root is None:
                raise OSError(xpu_error_string)
            include_dirs += [os.path.join(ze_root, 'include')]
            libraries_dirs += [os.path.join(ze_root, 'lib')]
        else:
            cflags += ['Wno-comment']
            if not find_library('ze_loader'):
                raise OSError(xpu_error_string)
        libraries += ['ze_loader', 'sycl']
        if <MASK>:
            libraries += ['c10_xpu', 'torch_xpu']
    if device_type == 'mps':
        definitions.append(' USE_MPS')
    if config.is_fbcode():
        include_dirs.append(build_paths.sdk_include)
        if aot_mode and device_type == 'cuda':
            if torch.version.hip is None:
                if not compile_only:
                    passthrough_args = ['-Wl,-Bstatic -lcudart_static -Wl,-Bdynamic']
        if device_type == 'cpu':
            (stdcxx_lib_dir_paths, stdcxx_libs) = _get_libstdcxx_args()
            libraries_dirs += stdcxx_lib_dir_paths
            libraries += stdcxx_libs
    if config.aot_inductor.custom_op_libs:
        libraries += config.aot_inductor.custom_op_libs
    return (definitions, include_dirs, cflags, ldflags, libraries_dirs, libraries, passthrough_args)

@staticmethod
def relu(x):
    bug = config.cpp.inject_relu_bug_TESTING_ONLY
    if bug == 'compile_error':
        return 'compile error!'
    elif <MASK>:
        return f'{x}; throw 1'
    elif bug == 'accuracy':
        return f'{x} + decltype({x})(1)'
    elif bug is None:
        return f'at::vec::clamp_min({x}, decltype({x})(0))'
    else:
        raise AssertionError(f'unrecognized config cpp.inject_relu_bug_TESTING_ONLY = {bug!r}')

