def spawn_threads_and_init_comms(func=None, timeout=TIMEOUT_DEFAULT, world_size=DEFAULT_WORLD_SIZE):
    """
    Wrapper to use with a test method
    """
    if <MASK>:
        return partial(spawn_threads_and_init_comms, timeout=timeout, world_size=world_size)

    def _run_test_method_with_multi_threads(world_size, callback):
        world = _install_threaded_pg()
        global_store = c10d.HashStore()

        def world_is_valid():
            return world == c10d.distributed_c10d._world

        def worker(rank, world_pg, store):
            c10d.init_process_group(backend='threaded', rank=rank, world_size=world_size, store=store)
            try:
                callback()
            except BaseException as ex:
                MultiThreadedTestCase.exception_queue.put((rank, sys.exc_info()))
                ProcessLocalGroup.exception_handle(ex)
            finally:
                if world_is_valid():
                    c10d.destroy_process_group()
        threads = []
        for rank in range(world_size):
            t = threading.Thread(target=worker, args=(rank, world, global_store))
            t.start()
            threads.append(t)
        return threads

    @wraps(func)
    def wrapper(self, *args, **kwargs):
        torch._C._distributed_c10d._set_thread_isolation_mode(True)
        try:
            threads = _run_test_method_with_multi_threads(world_size, lambda : func(self, *args, **kwargs))
            MultiThreadedTestCase._join_threads(threads, func)
        finally:
            torch._C._distributed_c10d._set_thread_isolation_mode(False)
    return wrapper

def add_conclusions(edges: Any) -> None:
    for (edge_idx, edge) in enumerate(edges):
        node = edge['node']
        workflow_run = node['workflowRun']
        checkruns = node['checkRuns']
        workflow_obj: WorkflowCheckState = no_workflow_obj
        if <MASK>:
            workflow_run_id = workflow_run['databaseId']
            workflow_name = workflow_run['workflow']['name']
            workflow_id = workflow_run['workflow']['databaseId']
            workflow_conclusion = node['conclusion']
            if workflow_conclusion == 'CANCELLED' and workflow_name in workflows:
                continue
            if workflow_id not in workflows or workflows[workflow_id].run_id < workflow_run_id:
                workflows[workflow_id] = WorkflowCheckState(name=workflow_name, status=workflow_conclusion, url=workflow_run['url'], run_id=workflow_run_id)
            workflow_obj = workflows[workflow_id]
        while checkruns is not None:
            for checkrun_node in checkruns['nodes']:
                if not isinstance(checkrun_node, dict):
                    warn(f'Expected dictionary, but got {type(checkrun_node)}')
                    continue
                checkrun_name = f"{get_check_run_name_prefix(workflow_run)}{checkrun_node['name']}"
                existing_checkrun = workflow_obj.jobs.get(checkrun_name)
                if existing_checkrun is None or not is_passing_status(existing_checkrun.status):
                    workflow_obj.jobs[checkrun_name] = JobCheckState(checkrun_name, checkrun_node['detailsUrl'], checkrun_node['conclusion'], classification=None, job_id=checkrun_node['databaseId'], title=checkrun_node['title'], summary=checkrun_node['summary'])
            if bool(checkruns['pageInfo']['hasNextPage']):
                checkruns = get_next_checkruns_page(edges, edge_idx, checkruns)
            else:
                checkruns = None

def get_op(qualname):

    def error_not_found():
        raise ValueError(f'Could not find the operator {qualname}. Please make sure you have already registered the operator and (if registered from C++) loaded it via torch.ops.load_library.')
    (ns, name) = parse_qualname(qualname)
    if <MASK>:
        error_not_found()
    opnamespace = getattr(torch.ops, ns)
    if not hasattr(opnamespace, name):
        error_not_found()
    packet = getattr(opnamespace, name)
    if not hasattr(packet, 'default'):
        error_not_found()
    return packet.default

def var2fixfortran(vars, a, fa=None, f90mode=None):
    if fa is None:
        fa = a
    if a not in vars:
        show(vars)
        outmess(f'var2fixfortran: No definition for argument "{a}".\n')
        return ''
    if 'typespec' not in vars[a]:
        show(vars[a])
        outmess(f'var2fixfortran: No typespec for argument "{a}".\n')
        return ''
    vardef = vars[a]['typespec']
    if vardef == 'type' and 'typename' in vars[a]:
        vardef = f"{vardef}({vars[a]['typename']})"
    selector = {}
    lk = ''
    if 'kindselector' in vars[a]:
        selector = vars[a]['kindselector']
        lk = 'kind'
    elif 'charselector' in vars[a]:
        selector = vars[a]['charselector']
        lk = 'len'
    if '*' in selector:
        if <MASK>:
            if selector['*'] in ['*', ':', '(*)']:
                vardef = f'{vardef}(len=*)'
            else:
                vardef = f"{vardef}({lk}={selector['*']})"
        elif selector['*'] in ['*', ':']:
            vardef = f"{vardef}*({selector['*']})"
        else:
            vardef = f"{vardef}*{selector['*']}"
    elif 'len' in selector:
        vardef = f"{vardef}(len={selector['len']}"
        if 'kind' in selector:
            vardef = f"{vardef},kind={selector['kind']})"
        else:
            vardef = f'{vardef})'
    elif 'kind' in selector:
        vardef = f"{vardef}(kind={selector['kind']})"
    vardef = f'{vardef} {fa}'
    if 'dimension' in vars[a]:
        vardef = f"{vardef}({','.join(vars[a]['dimension'])})"
    return vardef

def _annotate_linear_unary(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    postop_list = [torch.nn.ReLU, torch.nn.LeakyReLU, torch.nn.Tanh, torch.nn.GELU]
    fused_partitions: list[tuple] = []
    for postop in postop_list:
        fused_partitions = fused_partitions + find_sequential_partitions(gm, [torch.nn.Linear, postop])
    for fused_partition in fused_partitions:
        (linear_partition, unary_partition) = fused_partition
        (linear_node, unary_node) = self._get_output_nodes_of_partitions([linear_partition, unary_partition])
        if linear_node.op != 'call_function' or linear_node.target != torch.ops.aten.linear.default:
            continue
        if <MASK>:
            continue
        if quantization_config is None:
            _annotate_nodes_not_quantize([linear_node, unary_node])
            continue
        self._annotate_linear_node_helper(linear_node, False, quantization_config)
        unary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(_annotated=True, _is_output_of_quantized_pattern=True)

def _isinstance(obj, target_type) -> bool:
    if isinstance(target_type, collections.abc.Container):
        if not isinstance(target_type, tuple):
            raise RuntimeError('The second argument to `torch.jit.isinstance` must be a type or a tuple of types')
        for t_type in target_type:
            if _isinstance(obj, t_type):
                return True
        return False
    origin_type = get_origin(target_type)
    if <MASK>:
        return container_checker(obj, target_type)
    check_args_exist(target_type)
    return isinstance(obj, target_type)

def full_clean(self):
    """
        Clean all of self.data and populate self._errors and
        self._non_form_errors.
        """
    self._errors = []
    self._non_form_errors = self.error_class(error_class='nonform', renderer=self.renderer)
    empty_forms_count = 0
    if <MASK>:
        return
    if not self.management_form.is_valid():
        error = ValidationError(self.error_messages['missing_management_form'], params={'field_names': ', '.join((self.management_form.add_prefix(field_name) for field_name in self.management_form.errors))}, code='missing_management_form')
        self._non_form_errors.append(error)
    for (i, form) in enumerate(self.forms):
        if not form.has_changed() and i >= self.initial_form_count():
            empty_forms_count += 1
        form_errors = form.errors
        if self.can_delete and self._should_delete_form(form):
            continue
        self._errors.append(form_errors)
    try:
        if self.validate_max and self.total_form_count() - len(self.deleted_forms) > self.max_num or self.management_form.cleaned_data[TOTAL_FORM_COUNT] > self.absolute_max:
            raise ValidationError(self.error_messages['too_many_forms'] % {'num': self.max_num}, code='too_many_forms')
        if self.validate_min and self.total_form_count() - len(self.deleted_forms) - empty_forms_count < self.min_num:
            raise ValidationError(self.error_messages['too_few_forms'] % {'num': self.min_num}, code='too_few_forms')
        self.clean()
    except ValidationError as e:
        self._non_form_errors = self.error_class(e.error_list, error_class='nonform', renderer=self.renderer)

@staticmethod
def _serialize_path(path):
    (module, name) = path.rsplit('.', 1)
    if <MASK>:
        imports = {'from django.db import models'}
        name = 'models.%s' % name
    else:
        imports = {'import %s' % module}
        name = path
    return (name, imports)

def _element_size(dtype):
    """
    Returns the element size for a dtype, in bytes
    """
    if not isinstance(dtype, torch.dtype):
        raise RuntimeError(f'expected torch.dtype, but got {type(dtype)}')
    if dtype.is_complex:
        return torch.finfo(dtype).bits >> 2
    elif dtype.is_floating_point:
        return torch.finfo(dtype).bits >> 3
    elif <MASK>:
        return 1
    else:
        return torch.iinfo(dtype).bits >> 3

def init_shard_fn(shard_index):
    if <MASK>:
        logging.log_if(logging.WARN, _INEFFICIENT_INIT_WARNING % name, shard_index == 0 and shape.num_elements() > _LARGE_VARIABLE_NUM_ELEMENTS)
        return initial_value[offsets[shard_index]:offsets[shard_index + 1]]
    partition_shape = (offsets[shard_index + 1] - offsets[shard_index],) + shape[1:]
    partition_offset = (offsets[shard_index],) + (0,) * len(shape[1:])
    arg_spec = tf_inspect.getfullargspec(initial_value)
    if 'shard_info' not in arg_spec.args and 'shard_info' not in arg_spec.kwonlyargs:
        try:
            value = initial_value(partition_shape=partition_shape, partition_offset=partition_offset)
        except (TypeError, ValueError):
            value = initial_value()
        if value.shape == partition_shape:
            return value
        else:
            logging.log_if(logging.WARN, _INEFFICIENT_INIT_WARNING % name, shard_index == 0 and shape.num_elements() > _LARGE_VARIABLE_NUM_ELEMENTS)
            return value[offsets[shard_index]:offsets[shard_index + 1]]
    else:
        return initial_value(shard_info=trackable.ShardInfo(shape=tensor_shape.as_shape(partition_shape), offset=partition_offset))

@numba.jit(nopython=True, nogil=True, parallel=False)
def remove_mean(val: float, nobs: int, sum_x: float, neg_ct: int, compensation: float) -> tuple[int, float, int, float]:
    if not np.isnan(val):
        nobs -= 1
        y = -val - compensation
        t = sum_x + y
        compensation = t - sum_x - y
        sum_x = t
        if <MASK>:
            neg_ct -= 1
    return (nobs, sum_x, neg_ct, compensation)

