def _distributed_apply(self, distribution, grads_and_vars, name, apply_state):
    """`apply_gradients` using a `DistributionStrategy`."""

    def apply_grad_to_update_var(var, grad):
        """Apply gradient to variable."""
        if isinstance(var, tensor.Tensor):
            raise NotImplementedError('Trying to update a Tensor ', var)
        apply_kwargs = {}
        if isinstance(grad, indexed_slices.IndexedSlices):
            if var.constraint is not None:
                raise RuntimeError('Cannot use a constraint function on a sparse variable.')
            if <MASK>:
                apply_kwargs['apply_state'] = apply_state
            return self._resource_apply_sparse_duplicate_indices(grad.values, var, grad.indices, **apply_kwargs)
        if 'apply_state' in self._dense_apply_args:
            apply_kwargs['apply_state'] = apply_state
        update_op = self._resource_apply_dense(grad, var, **apply_kwargs)
        if var.constraint is not None:
            with ops.control_dependencies([update_op]):
                return var.assign(var.constraint(var))
        else:
            return update_op
    eagerly_outside_functions = ops.executing_eagerly_outside_functions()
    update_ops = []
    with name_scope_only_in_function_or_graph(name or self._name):
        for (grad, var) in grads_and_vars:
            with distribution.extended.colocate_vars_with(var):
                with name_scope_only_in_function_or_graph('update' if eagerly_outside_functions else 'update_' + var.op.name):
                    update_op = distribution.extended.update(var, apply_grad_to_update_var, args=(grad,), group=False)
                    if distribute_lib.in_cross_replica_context():
                        update_ops.extend(update_op)
                    else:
                        update_ops.append(update_op)
        any_symbolic = any((isinstance(i, ops.Operation) or tf_utils.is_symbolic_tensor(i) for i in update_ops))
        if not context.executing_eagerly() or any_symbolic:
            with backend._current_graph(update_ops).as_default():
                with ops.control_dependencies([control_flow_ops.group(update_ops)]):
                    return self._iterations.assign_add(1, read_value=False)
        return self._iterations.assign_add(1)

def _bytecode_from_template_with_split(template: Callable[..., Any], stack_index: int, varname_map: Optional[dict[str, Any]]=None) -> tuple[list[Instruction], list[Instruction]]:
    template_code = bytecode_from_template(template, varname_map=varname_map)
    template_code.append(create_instruction('POP_TOP'))
    for inst in template_code:
        if <MASK>:
            inst.exn_tab_entry.depth += stack_index
    (dummy_idx, dummy_inst) = next(((i, inst) for (i, inst) in enumerate(template_code) if inst.opname in ('LOAD_FAST', 'LOAD_FAST_BORROW') and inst.argval == 'dummy'), (None, None))
    assert dummy_idx is not None and dummy_inst is not None
    overwrite_instruction(dummy_inst, [create_instruction('NOP')])
    assert template_code[dummy_idx + 1].opname == 'POP_TOP'
    overwrite_instruction(template_code[dummy_idx + 1], [create_instruction('NOP')])
    return (template_code[:dummy_idx + 1], template_code[dummy_idx + 1:])

@classmethod
def copy_of(cls, other):
    if <MASK>:
        assert other.parent is not None
        parent = cls.copy_of(other.parent)
    else:
        parent = None
    new_copy = cls(parent)
    new_copy.copy_from(other)
    return new_copy

def deep_deconstruct(self, obj):
    """
        Recursive deconstruction for a field and its arguments.
        Used for full comparison for rename/alter; sometimes a single-level
        deconstruction will not compare correctly.
        """
    if isinstance(obj, list):
        return [self.deep_deconstruct(value) for value in obj]
    elif <MASK>:
        return tuple((self.deep_deconstruct(value) for value in obj))
    elif isinstance(obj, dict):
        return {key: self.deep_deconstruct(value) for (key, value) in obj.items()}
    elif isinstance(obj, functools.partial):
        return (obj.func, self.deep_deconstruct(obj.args), self.deep_deconstruct(obj.keywords))
    elif isinstance(obj, COMPILED_REGEX_TYPE):
        return RegexObject(obj)
    elif isinstance(obj, type):
        return obj
    elif hasattr(obj, 'deconstruct'):
        deconstructed = obj.deconstruct()
        if isinstance(obj, models.Field):
            deconstructed = deconstructed[1:]
        (path, args, kwargs) = deconstructed
        return (path, [self.deep_deconstruct(value) for value in args], {key: self.deep_deconstruct(value) for (key, value) in kwargs.items()})
    else:
        return obj

def prune(self, klass):

    def pr(left, right):
        """create and return a new specialized BinOp from myself"""
        if left is None:
            return right
        elif right is None:
            return left
        k = klass
        if isinstance(left, ConditionBinOp):
            if <MASK>:
                k = JointConditionBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right
        elif isinstance(left, FilterBinOp):
            if isinstance(right, FilterBinOp):
                k = JointFilterBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right
        return k(self.op, left, right, queryables=self.queryables, encoding=self.encoding).evaluate()
    (left, right) = (self.lhs, self.rhs)
    if is_term(left) and is_term(right):
        res = pr(left.value, right.value)
    elif not is_term(left) and is_term(right):
        res = pr(left.prune(klass), right.value)
    elif is_term(left) and (not is_term(right)):
        res = pr(left.value, right.prune(klass))
    elif not (is_term(left) or is_term(right)):
        res = pr(left.prune(klass), right.prune(klass))
    return res

