def _tridiagonal_solve_compact_format(diagonals, rhs, transpose_rhs, conjugate_rhs, partial_pivoting, perturb_singular, name):
    """Helper function used after the input has been cast to compact form."""
    (diags_rank, rhs_rank) = (diagonals.shape.rank, rhs.shape.rank)
    if diags_rank:
        if diags_rank < 2:
            raise ValueError('Expected diagonals to have rank at least 2, got {}'.format(diags_rank))
        if rhs_rank and rhs_rank != diags_rank and (rhs_rank != diags_rank - 1):
            raise ValueError('Expected the rank of rhs to be {} or {}, got {}'.format(diags_rank - 1, diags_rank, rhs_rank))
        if rhs_rank and (not diagonals.shape[:-2].is_compatible_with(rhs.shape[:diags_rank - 2])):
            raise ValueError('Batch shapes {} and {} are incompatible'.format(diagonals.shape[:-2], rhs.shape[:diags_rank - 2]))
    if diagonals.shape[-2] and diagonals.shape[-2] != 3:
        raise ValueError('Expected 3 diagonals got {}'.format(diagonals.shape[-2]))

    def check_num_lhs_matches_num_rhs():
        if diagonals.shape[-1] and rhs.shape[-2] and (diagonals.shape[-1] != rhs.shape[-2]):
            raise ValueError('Expected number of left-hand sided and right-hand sides to be equal, got {} and {}'.format(diagonals.shape[-1], rhs.shape[-2]))
    if rhs_rank and diags_rank and (rhs_rank == diags_rank - 1):
        if <MASK>:
            rhs = math_ops.conj(rhs)
        rhs = array_ops.expand_dims(rhs, -1)
        check_num_lhs_matches_num_rhs()
        return array_ops.squeeze(linalg_ops.tridiagonal_solve(diagonals, rhs, partial_pivoting, perturb_singular, name), -1)
    if transpose_rhs:
        rhs = array_ops.matrix_transpose(rhs, conjugate=conjugate_rhs)
    elif conjugate_rhs:
        rhs = math_ops.conj(rhs)
    check_num_lhs_matches_num_rhs()
    return linalg_ops.tridiagonal_solve(diagonals, rhs, partial_pivoting, perturb_singular, name)

def test_structure(values):
    for (i, value) in enumerate(values):
        self.assertIsInstance(value, tpu_replicated_variable.TPUReplicatedVariable)
        packed_var = getattr(value, '_packed_var', None)
        if <MASK>:
            if i == 0:
                self.assertIsInstance(packed_var, packed.PackedDistributedVariable)
            else:
                self.assertIs(packed_var, values[0]._packed_var, 'all vals should share the same packed var instance')
        else:
            self.assertIsNone(packed_var)
    if enable_packing:
        resources = sum((value._vars for value in values), [])
        dist_vars = packed_var._distributed_variables
        self.assertLen(resources, len(dist_vars))
        for (dist_var, resource) in zip(dist_vars, resources):
            self.assertIs(dist_var, resource)

def codegen_intermediate_tensor_value_print(self, args_to_print, kernel_name, before_launch=True, arg_signatures: Optional[list[type]]=None) -> None:
    launch_prefix = 'before_launch' if before_launch else 'after_launch'
    if self.debug_printer_level == IntermediateValueDebuggingLevel.PRINT_KERNEL_NAMES_ONLY:
        if <MASK>:
            V.graph.wrapper_code.writeline(f'printf("[ {launch_prefix}: {kernel_name} ]\\n");')
        return
    if self.debug_printer_level != IntermediateValueDebuggingLevel.PRINT_ONLY:
        return
    for (i, arg) in enumerate(args_to_print):
        if len(self.filtered_kernel_names_to_print) > 0 and kernel_name.lower() not in self.filtered_kernel_names_to_print:
            continue
        if V.graph.cpp_wrapper:
            if arg_signatures is not None and isinstance(arg_signatures[i], torch_dtype):
                V.graph.wrapper_code.writeline(f'aoti_torch_print_tensor_handle({arg}, "{launch_prefix} - {kernel_name} - {arg}");')
            elif arg_signatures is not None and isinstance(arg_signatures[i], (type(torch._inductor.codegen.wrapper.SymbolicCallArg), type(int), type(float), type(bool))):
                V.graph.wrapper_code.writeline(f'printf("[  {launch_prefix} - {kernel_name} - {arg}: %ld  ]", {arg}); printf("\\\\n");')
            elif arg_signatures is None and self.kernel_type in ('cpp', 'extern'):
                V.graph.wrapper_code.writeline(f'aoti_torch_print_tensor_handle({arg}, "{launch_prefix} - {kernel_name} - {arg}");')
        else:
            V.graph.wrapper_code.writeline(f'_print_debugging_tensor_value_info("inductor: {launch_prefix} - {kernel_name} - {arg}", {arg})')

def cumulative_prod(x: Array, /, xp: Namespace, *, axis: int | None=None, dtype: DType | None=None, include_initial: bool=False, **kwargs: object) -> Array:
    wrapped_xp = array_namespace(x)
    if <MASK>:
        if x.ndim > 1:
            raise ValueError('axis must be specified in cumulative_prod for more than one dimension')
        axis = 0
    res = xp.cumprod(x, axis=axis, dtype=dtype, **kwargs)
    if include_initial:
        initial_shape = list(x.shape)
        initial_shape[axis] = 1
        res = xp.concatenate([wrapped_xp.ones(shape=initial_shape, dtype=res.dtype, device=_get_device(res)), res], axis=axis)
    return res

