def get_file_map(data_folder: Path, regen_data, assert_stored=False):
    if <MASK>:
        with open(data_folder / 'file_map.pkl', 'rb') as f:
            return pickle.load(f)
    else:
        if assert_stored:
            raise FileNotFoundError('File map not found, you are loading for inference you need to have a file map!')
        print('Regenerating File Map')
        all_data = pd.read_csv(data_folder / 'commitlist.csv')
        files = all_data.files_changed.to_list()
        all_files = []
        for file in files:
            paths = [Path(file_part) for file_part in file.split(' ')]
            all_files.extend(paths)
        all_files.append(Path(UNKNOWN_TOKEN))
        file_set = build_file_set(all_files, MAX_LEN_FILE)
        file_map = {file: i for (i, file) in enumerate(file_set)}
        with open(data_folder / 'file_map.pkl', 'wb') as f:
            pickle.dump(file_map, f)
        return file_map

@register_lowering(aten.scatter_reduce_, type_promotion_kind=None)
def scatter_reduce_(self, dim: int, index, src, reduce, *, include_self: bool=True):
    assert reduce in (None, 'sum', 'prod', 'mean', 'amax', 'amin')
    assert len(aten.scatter_reduce_.overloads()) == 1 and 'two' in aten.scatter_reduce_.overloads(), 'aten.scatter_reduce_.two is not the unique overload of aten.scatter_reduce_'
    if isinstance(src, Number):
        src = full_like(self, src)
    fallback_result = scatter_fallback(aten.scatter_reduce_.two, self, dim, index, src, reduce=reduce, include_self=include_self)
    if fallback_result:
        return fallback_result
    assert isinstance(self, TensorBox)
    assert 'int' in str(index.get_dtype())
    ndim = len(self.get_size())
    if ndim == 0:
        self = view(self, [1])
    if isinstance(src, TensorBox) and len(src.get_size()) == 0:
        src = view(src, [1])
    if isinstance(index, TensorBox) and len(index.get_size()) == 0:
        index = view(index, [1])
    if index.get_numel() == 0:
        return self
    dim = _validate_dim(self, dim)
    self.realize()
    index_loader = index.make_loader()
    src_loader = src.make_loader() if isinstance(src, TensorBox) else None

    def output_indexer(idx):
        shape = self.get_size()
        ndim = len(shape)
        indirect_idx = list(idx)
        indirect_idx[dim] = ops.indirect_indexing(index_loader(idx), 1 if ndim == 0 else shape[dim], wrap_neg=False)
        return indirect_idx

    def fn(idx):
        if src_loader:
            return src_loader(idx)
        else:
            return ops.constant(src, self.get_dtype())

    def backend_reduce_str(reduce):
        if <MASK>:
            return 'atomic_add'
        else:
            assert reduce is None
            return None
    device = self.get_device()
    assert device is not None
    if not include_self:
        zero_out = ir.Scatter(device=device, dtype=self.get_dtype(), inner_fn=lambda index: ops.constant(0, self.get_dtype()), ranges=index.get_size(), output_indexer=output_indexer, scatter_mode=None)
        buffer = ir.ComputedBuffer(name=None, layout=ir.MutationLayoutSHOULDREMOVE(self), data=zero_out)
        buffer.name = V.graph.register_buffer(buffer)
        V.graph.register_operation(buffer)
    scatter = ir.Scatter(device=device, dtype=self.get_dtype(), inner_fn=fn, ranges=index.get_size(), output_indexer=output_indexer, scatter_mode=backend_reduce_str(reduce))
    buffer = ir.ComputedBuffer(name=None, layout=ir.MutationLayoutSHOULDREMOVE(self), data=scatter)
    buffer.name = V.graph.register_buffer(buffer)
    V.graph.register_operation(buffer)
    if ndim == 0:
        self = view(self, [])
    return self

@register_lowering(quantized_decomposed.quantize_per_channel, type_promotion_kind=None)
def quantized_decomposed_quantize_per_channel(input: TensorBox, scales: TensorBox, zero_points: TensorBox, axis: int, quant_min: int, quant_max: int, dtype: torch.dtype) -> Union[TensorBox, ShapeAsConstantBuffer]:
    assert len(scales.get_size()) == 1, 'expect scales 1 dim'
    assert len(zero_points.get_size()) == 1, 'expect zero_points 1 dim'
    if input.get_dtype() == torch.bfloat16:
        input = to_dtype(input, torch.float32)
    assert input.get_dtype() == torch.float32, f'Expecting input to have dtype torch.float32, but got dtype: {input.get_dtype()}'
    assert axis < len(input.get_size()), f'Expecting axis to be < {len(input.get_size())}'
    input_loader = input.make_loader()
    scales_loader = scales.make_loader()
    zero_points_loader = zero_points.make_loader()

    def inner_fn(idx):
        channel_idx = (idx[axis],)
        input = input_loader(idx)
        scale = scales_loader(channel_idx)
        zero_point = zero_points_loader(channel_idx)
        (qmin, qmax) = _create_constants(quant_min, quant_max, dtype=torch.float32)
        if scales.dtype != torch.float32:
            scale = ops.to_dtype(scale, torch.float32)
        if <MASK>:
            zero_point = ops.to_dtype(zero_point, torch.int32)
        inv_scale = ops.reciprocal(scale)
        val = ops.round(input * inv_scale) + zero_point
        clamped = ops.maximum(qmin, ops.minimum(qmax, val))
        return ops.to_dtype(clamped, dtype)
    return Pointwise.create(device=input.get_device(), dtype=dtype, inner_fn=inner_fn, ranges=input.get_size())

def __init__(self, m: torch.fx.GraphModule, flat_args: list[Any], matched_input_elements_positions: list[int], flat_results: Sequence[Any], matched_output_elements_positions: list[int], example_fake_inputs: list[torch.Tensor], flat_args_dynamic_dims: list[set[int]], fake_mode: Optional[fake_tensor.FakeTensorMode]=None) -> None:
    super().__init__(m)
    assert len(flat_args_dynamic_dims) == len(flat_args)
    matched_input_elements_to_fake = {val: example_fake_inputs[ix] for (ix, val) in enumerate(matched_input_elements_positions)}
    self.new_args = []
    for i in range(len(flat_args)):
        arg = super().placeholder(f'arg{i}', (), {})
        if i in matched_input_elements_to_fake:
            arg.node.meta['val'] = matched_input_elements_to_fake[i]
        elif <MASK>:
            arg.node.meta['val'] = fake_mode.from_tensor(flat_args[i], symbolic_context=StatelessSymbolicContext(dynamic_sizes=[DimDynamic.DYNAMIC if d in flat_args_dynamic_dims[i] else DimDynamic.STATIC for d in range(len(flat_args[i].shape))], constraint_sizes=[None] * len(flat_args[i].shape)))
        elif isinstance(flat_args[i], _IntWrapper):
            arg.node.meta['val'] = flat_args[i].val
        else:
            arg.node.meta['val'] = flat_args[i]
        self.new_args.append(arg)
    self.old_args_gen = (self.new_args[i] for i in matched_input_elements_positions)
    self.matched_output_elements_positions = matched_output_elements_positions
    self.flat_results = flat_results

@final
@doc(_shared_docs['replace'], klass=_shared_doc_kwargs['klass'], inplace=_shared_doc_kwargs['inplace'])
def replace(self, to_replace=None, value=lib.no_default, *, inplace: bool=False, regex: bool=False) -> Self | None:
    if not is_bool(regex) and to_replace is not None:
        raise ValueError("'to_replace' must be 'None' if 'regex' is not a bool")
    if not (is_scalar(to_replace) or is_re_compilable(to_replace) or is_list_like(to_replace)):
        raise TypeError(f"Expecting 'to_replace' to be either a scalar, array-like, dict or None, got invalid type {type(to_replace).__name__!r}")
    if value is lib.no_default and (not (is_dict_like(to_replace) or is_dict_like(regex))):
        raise ValueError(f"{type(self).__name__}.replace must specify either 'value', a dict-like 'to_replace', or dict-like 'regex'.")
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if <MASK>:
        if not PYPY and (not WARNING_CHECK_DISABLED):
            if sys.getrefcount(self) <= REF_COUNT:
                warnings.warn(_chained_assignment_method_msg, ChainedAssignmentError, stacklevel=2)
    if value is lib.no_default:
        if not is_dict_like(to_replace):
            to_replace = regex
            regex = True
        items = list(to_replace.items())
        if items:
            (keys, values) = zip(*items, strict=True)
        else:
            (keys, values) = ([], [])
        are_mappings = [is_dict_like(v) for v in values]
        if any(are_mappings):
            if not all(are_mappings):
                raise TypeError('If a nested mapping is passed, all values of the top level mapping must be mappings')
            to_rep_dict = {}
            value_dict = {}
            for (k, v) in items:
                (keys, values) = list(zip(*v.items(), strict=True)) or ([], [])
                to_rep_dict[k] = list(keys)
                value_dict[k] = list(values)
            (to_replace, value) = (to_rep_dict, value_dict)
        else:
            (to_replace, value) = (keys, values)
        return self.replace(to_replace, value, inplace=inplace, regex=regex)
    else:
        if not self.size:
            if inplace:
                return None
            return self.copy(deep=False)
        if is_dict_like(to_replace):
            if is_dict_like(value):
                if isinstance(self, ABCSeries):
                    raise ValueError('to_replace and value cannot be dict-like for Series.replace')
                mapping = {col: (to_replace[col], value[col]) for col in to_replace.keys() if col in value.keys() and col in self}
                return self._replace_columnwise(mapping, inplace, regex)
            elif not is_list_like(value):
                if self.ndim == 1:
                    raise ValueError("Series.replace cannot specify both a dict-like 'to_replace' and a 'value'")
                mapping = {col: (to_rep, value) for (col, to_rep) in to_replace.items()}
                return self._replace_columnwise(mapping, inplace, regex)
            else:
                raise TypeError('value argument must be scalar, dict, or Series')
        elif is_list_like(to_replace):
            if not is_list_like(value):
                value = [value] * len(to_replace)
            if len(to_replace) != len(value):
                raise ValueError(f'Replacement lists must match in length. Expecting {len(to_replace)} got {len(value)} ')
            new_data = self._mgr.replace_list(src_list=to_replace, dest_list=value, inplace=inplace, regex=regex)
        elif to_replace is None:
            if not (is_re_compilable(regex) or is_list_like(regex) or is_dict_like(regex)):
                raise TypeError(f"'regex' must be a string or a compiled regular expression or a list or dict of strings or regular expressions, you passed a {type(regex).__name__!r}")
            return self.replace(regex, value, inplace=inplace, regex=True)
        elif is_dict_like(value):
            if self.ndim == 1:
                raise ValueError('Series.replace cannot use dict-value and non-None to_replace')
            mapping = {col: (to_replace, val) for (col, val) in value.items()}
            return self._replace_columnwise(mapping, inplace, regex)
        elif not is_list_like(value):
            regex = should_use_regex(regex, to_replace)
            if regex:
                new_data = self._mgr.replace_regex(to_replace=to_replace, value=value, inplace=inplace)
            else:
                new_data = self._mgr.replace(to_replace=to_replace, value=value, inplace=inplace)
        else:
            raise TypeError(f'Invalid "to_replace" type: {type(to_replace).__name__!r}')
    result = self._constructor_from_mgr(new_data, axes=new_data.axes)
    if inplace:
        return self._update_inplace(result)
    else:
        return result.__finalize__(self, method='replace')

def deserialize_constant_input(self, inp: ConstantValue) -> Any:
    if inp.type == 'as_int':
        return int(inp.as_int)
    elif inp.type == 'as_float':
        return float(inp.as_float)
    elif <MASK>:
        return str(inp.as_string)
    elif inp.type == 'as_bool':
        return bool(inp.as_bool)
    elif inp.type == 'as_none':
        return None
    else:
        raise SerializeError(f'Unhandled constant argument {inp} to deserialize')

def _join_multiline(self, strcols_input: Iterable[list[str]]) -> str:
    lwidth = self.line_width
    adjoin_width = 1
    strcols = list(strcols_input)
    if <MASK>:
        idx = strcols.pop(0)
        lwidth -= np.array([self.adj.len(x) for x in idx]).max() + adjoin_width
    col_widths = [np.array([self.adj.len(x) for x in col]).max() if len(col) > 0 else 0 for col in strcols]
    assert lwidth is not None
    col_bins = _binify(col_widths, lwidth)
    nbins = len(col_bins)
    str_lst = []
    start = 0
    for (i, end) in enumerate(col_bins):
        row = strcols[start:end]
        if self.fmt.index:
            row.insert(0, idx)
        if nbins > 1:
            nrows = len(row[-1])
            if end <= len(strcols) and i < nbins - 1:
                row.append([' \\'] + ['  '] * (nrows - 1))
            else:
                row.append([' '] * nrows)
        str_lst.append(self.adj.adjoin(adjoin_width, *row))
        start = end
    return '\n\n'.join(str_lst)

@ops.RegisterGradient('MatMul')
def _MatMulGrad(op: ops.Operation, grad):
    """Gradient for MatMul."""
    try:
        skip_input_indices = op.skip_input_indices
        if skip_input_indices is not None:
            if 1 in skip_input_indices:
                return _MatMulGradAgainstFirstOnly(op, grad)
            elif 0 in skip_input_indices:
                return _MatMulGradAgainstSecondOnly(op, grad)
    except AttributeError:
        pass
    t_a = op.get_attr('transpose_a')
    t_b = op.get_attr('transpose_b')
    a = math_ops.conj(op.inputs[0])
    b = math_ops.conj(op.inputs[1])
    if not t_a and (not t_b):
        grad_a = gen_math_ops.mat_mul(grad, b, transpose_b=True, grad_a=True)
        grad_b = gen_math_ops.mat_mul(a, grad, transpose_a=True, grad_b=True)
    elif not t_a and t_b:
        grad_a = gen_math_ops.mat_mul(grad, b, grad_a=True)
        grad_b = gen_math_ops.mat_mul(grad, a, transpose_a=True, grad_b=True)
    elif <MASK>:
        grad_a = gen_math_ops.mat_mul(b, grad, transpose_b=True, grad_a=True)
        grad_b = gen_math_ops.mat_mul(a, grad, grad_b=True)
    elif t_a and t_b:
        grad_a = gen_math_ops.mat_mul(b, grad, transpose_a=True, transpose_b=True, grad_a=True)
        grad_b = gen_math_ops.mat_mul(grad, a, transpose_a=True, transpose_b=True, grad_b=True)
    return (grad_a, grad_b)

def _split_line(name, arguments, width):
    firstwidth = len(name)
    k = firstwidth
    newstr = name
    sepstr = ', '
    arglist = arguments.split(sepstr)
    for argument in arglist:
        if <MASK>:
            addstr = ''
        else:
            addstr = sepstr
        k = k + len(argument) + len(addstr)
        if k > width:
            k = firstwidth + 1 + len(argument)
            newstr = newstr + ',\n' + ' ' * (firstwidth + 2) + argument
        else:
            newstr = newstr + addstr + argument
    return newstr

def benchmark(self, *input_tensors: torch.Tensor, out: Optional[torch.Tensor]=None) -> float:
    debug = autotuning_log.isEnabledFor(logging.DEBUG)
    if <MASK>:
        start_ts = time.time()
    if out is None:
        assert len(input_tensors) == 0
        input_tensors = tuple((x.to_tensor() for x in self.input_tensor_meta))
        out = self.output_tensor_meta.to_tensor()
    if debug:
        create_tensor_elapse = time.time() - start_ts
        start_ts = time.time()
    try:
        fn = self.make_run_fn(*input_tensors, out=out)
    except NonzeroWorkspaceNotSupportedError:
        autotuning_log.info('Skipping op due to nonzero workspace requirement')
        return float('inf')
    if debug:
        load_elapse = time.time() - start_ts
        start_ts = time.time()
    res = self.do_bench(fn, *input_tensors, out)
    if debug:
        bench_elapse = time.time() - start_ts
        autotuning_log.debug('InChildProcess %s: load %f, create tensor %f, bench %f', str(self), load_elapse, create_tensor_elapse, bench_elapse)
    self.cleanup_run_fn()
    return res

@staticmethod
def to_dtype(a, dtype, src_dtype=None):
    if dtype == torch.float64:
        return ValueRanges.increasing_map(a, ToFloat)
    elif dtype == torch.bool:
        return ValueRanges.unknown_bool()
    elif <MASK>:
        return ValueRanges.unknown_int()
    return ValueRanges.unknown()

def _load_global(self, inst: Instruction) -> None:
    name = inst.argval
    if self.exec_recorder:
        if name in self.f_globals:
            self.exec_recorder.add_global_var(name, self.f_globals[name])
        else:
            assert name in self.f_builtins
            self.exec_recorder.builtins[name] = self.f_builtins[name]
    if name not in self.f_globals:
        return self.load_builtin(inst)
    if <MASK>:
        variable = self.output.side_effects[self.symbolic_globals[name]]
        self.push(self.output.side_effects.load_global(variable, name))
        return
    value = self.f_globals[name]
    self.push(VariableTracker.build(self, value, GlobalSource(name)))

def _unique1d(ar, return_index=False, return_inverse=False, return_counts=False, *, equal_nan=True, inverse_shape=None, axis=None, sorted=True):
    """
    Find the unique elements of an array, ignoring shape.

    Uses a hash table to find the unique elements if possible.
    """
    ar = np.asanyarray(ar).flatten()
    if len(ar.shape) != 1:
        ar = np.asarray(ar).flatten()
    optional_indices = return_index or return_inverse
    if not optional_indices and (not return_counts) and (not np.ma.is_masked(ar)):
        conv = _array_converter(ar)
        (ar_,) = conv
        if (hash_unique := _unique_hash(ar_, equal_nan=equal_nan)) is not NotImplemented:
            if <MASK>:
                hash_unique.sort()
            return (conv.wrap(hash_unique),)
    if optional_indices:
        perm = ar.argsort(kind='mergesort' if return_index else 'quicksort')
        aux = ar[perm]
    else:
        ar.sort()
        aux = ar
    mask = np.empty(aux.shape, dtype=np.bool)
    mask[:1] = True
    if equal_nan and aux.shape[0] > 0 and (aux.dtype.kind in 'cfmM') and np.isnan(aux[-1]):
        if aux.dtype.kind == 'c':
            aux_firstnan = np.searchsorted(np.isnan(aux), True, side='left')
        else:
            aux_firstnan = np.searchsorted(aux, aux[-1], side='left')
        if aux_firstnan > 0:
            mask[1:aux_firstnan] = aux[1:aux_firstnan] != aux[:aux_firstnan - 1]
        mask[aux_firstnan] = True
        mask[aux_firstnan + 1:] = False
    else:
        mask[1:] = aux[1:] != aux[:-1]
    ret = (aux[mask],)
    if return_index:
        ret += (perm[mask],)
    if return_inverse:
        imask = np.cumsum(mask) - 1
        inv_idx = np.empty(mask.shape, dtype=np.intp)
        inv_idx[perm] = imask
        ret += (inv_idx.reshape(inverse_shape) if axis is None else inv_idx,)
    if return_counts:
        idx = np.concatenate(np.nonzero(mask) + ([mask.size],))
        ret += (np.diff(idx),)
    return ret

def _order_by_pairs(self):
    if self.query.extra_order_by:
        ordering = self.query.extra_order_by
    elif not self.query.default_ordering:
        ordering = self.query.order_by
    elif self.query.order_by:
        ordering = self.query.order_by
    elif (meta := self.query.get_meta()) and meta.ordering:
        ordering = meta.ordering
        self._meta_ordering = ordering
    else:
        ordering = []
    if self.query.standard_ordering:
        (default_order, _) = ORDER_DIR['ASC']
    else:
        (default_order, _) = ORDER_DIR['DESC']
    selected_exprs = {}
    if ordering and (select := self.select):
        for (ordinal, (expr, _, alias)) in enumerate(select, start=1):
            pos_expr = PositionRef(ordinal, alias, expr)
            if alias:
                selected_exprs[alias] = pos_expr
            selected_exprs[expr] = pos_expr
    for field in ordering:
        if hasattr(field, 'resolve_expression'):
            if isinstance(field, Value):
                field = Cast(field, field.output_field)
            if <MASK>:
                field = field.asc()
            if not self.query.standard_ordering:
                field = field.copy()
                field.reverse_ordering()
            select_ref = selected_exprs.get(field.expression)
            if select_ref or (isinstance(field.expression, F) and (select_ref := selected_exprs.get(field.expression.name))):
                if field.nulls_first is None and field.nulls_last is None or self.connection.features.supports_order_by_nulls_modifier:
                    field = field.copy()
                    field.expression = select_ref
                elif self.query.combinator:
                    field = field.copy()
                    field.expression = Ref(select_ref.refs, select_ref.source)
            yield (field, select_ref is not None)
            continue
        if field == '?':
            yield (OrderBy(Random()), False)
            continue
        (col, order) = get_order_dir(field, default_order)
        descending = order == 'DESC'
        if (select_ref := selected_exprs.get(col)):
            yield (OrderBy(select_ref, descending=descending), True)
            continue
        if (expr := self.query.annotations.get(col)):
            ref = col
            transforms = []
        else:
            (ref, *transforms) = col.split(LOOKUP_SEP)
            expr = self.query.annotations.get(ref)
        if expr:
            if self.query.combinator and self.select:
                if transforms:
                    raise NotImplementedError('Ordering combined queries by transforms is not implemented.')
                expr = F(ref)
            if transforms:
                for name in transforms:
                    expr = self.query.try_transform(expr, name)
            if isinstance(expr, Value):
                expr = Cast(expr, expr.output_field)
            yield (OrderBy(expr, descending=descending), False)
            continue
        if '.' in field:
            (table, col) = col.split('.', 1)
            yield (OrderBy(RawSQL('%s.%s' % (self.quote_name_unless_alias(table), col), []), descending=descending), False)
            continue
        if self.query.extra and col in self.query.extra:
            if col in self.query.extra_select:
                yield (OrderBy(Ref(col, RawSQL(*self.query.extra[col])), descending=descending), True)
            else:
                yield (OrderBy(RawSQL(*self.query.extra[col]), descending=descending), False)
        elif self.query.combinator and self.select:
            yield (OrderBy(F(col), descending=descending), False)
        else:
            yield from self.find_ordering_name(field, self.query.get_meta(), default_order=default_order)

def dtypes(self, *, device: Device | None=None, kind: str | tuple[str, ...] | None=None) -> dict[str, DType]:
    """
        The array API data types supported by NumPy.

        Note that this function only returns data types that are defined by
        the array API.

        Parameters
        ----------
        device : str, optional
            The device to get the data types for. For NumPy, only ``'cpu'`` is
            allowed.
        kind : str or tuple of str, optional
            The kind of data types to return. If ``None``, all data types are
            returned. If a string, only data types of that kind are returned.
            If a tuple, a dictionary containing the union of the given kinds
            is returned. The following kinds are supported:

            - ``'bool'``: boolean data types (i.e., ``bool``).
            - ``'signed integer'``: signed integer data types (i.e., ``int8``,
              ``int16``, ``int32``, ``int64``).
            - ``'unsigned integer'``: unsigned integer data types (i.e.,
              ``uint8``, ``uint16``, ``uint32``, ``uint64``).
            - ``'integral'``: integer data types. Shorthand for ``('signed
              integer', 'unsigned integer')``.
            - ``'real floating'``: real-valued floating-point data types
              (i.e., ``float32``, ``float64``).
            - ``'complex floating'``: complex floating-point data types (i.e.,
              ``complex64``, ``complex128``).
            - ``'numeric'``: numeric data types. Shorthand for ``('integral',
              'real floating', 'complex floating')``.

        Returns
        -------
        dtypes : dict
            A dictionary mapping the names of data types to the corresponding
            NumPy data types.

        See Also
        --------
        __array_namespace_info__.capabilities,
        __array_namespace_info__.default_device,
        __array_namespace_info__.default_dtypes,
        __array_namespace_info__.devices

        Examples
        --------
        >>> info = np.__array_namespace_info__()
        >>> info.dtypes(kind='signed integer')
        {'int8': numpy.int8,
         'int16': numpy.int16,
         'int32': numpy.int32,
         'int64': numpy.int64}

        """
    if device not in ['cpu', None]:
        raise ValueError(f'Device not understood. Only "cpu" is allowed, but received: {device}')
    if kind is None:
        return {'bool': dtype(bool), 'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'bool':
        return {'bool': dtype(bool)}
    if kind == 'signed integer':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'integral':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'real floating':
        return {'float32': dtype(float32), 'float64': dtype(float64)}
    if kind == 'complex floating':
        return {'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'numeric':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if <MASK>:
        res: dict[str, DType] = {}
        for k in kind:
            res.update(self.dtypes(kind=k))
        return res
    raise ValueError(f'unsupported kind: {kind!r}')

def forward(self, args: list[torch.Tensor]) -> list[torch.Tensor]:
    if self.comp is None:
        self.init(args)
    comp = self.comp
    assert comp is not None
    outs = [torch.empty_like(out) for out in self.out_templates]
    assert len(args) == len(self.inp_mem_fmts)
    fixed_args = []
    for idx in range(len(args)):
        fmt = self.inp_mem_fmts[idx]
        if fmt == 0:
            fixed_args.append(args[idx].contiguous())
        elif <MASK>:
            fixed_args.append(args[idx].permute(0, 2, 3, 1).contiguous())
        else:
            raise ValueError('Invalid mem_fmt')
    comp.run(fixed_args, outs)
    assert len(outs) == len(self.out_mem_fmts)
    for idx in range(len(self.out_templates)):
        fmt = self.out_mem_fmts[idx]
        if fmt in (0, 2):
            pass
        elif fmt == 1:
            outs[idx] = outs[idx].permute(0, 3, 1, 2)
        else:
            raise ValueError('Invalid mem_fmt')
    return outs

def _sparse_fit(self, X, random_state):
    """Compute percentiles for sparse matrices.

        Parameters
        ----------
        X : sparse matrix of shape (n_samples, n_features)
            The data used to scale along the features axis. The sparse matrix
            needs to be nonnegative. If a sparse matrix is provided,
            it will be converted into a sparse ``csc_matrix``.
        """
    (n_samples, n_features) = X.shape
    references = self.references_ * 100
    self.quantiles_ = []
    for feature_idx in range(n_features):
        column_nnz_data = X.data[X.indptr[feature_idx]:X.indptr[feature_idx + 1]]
        if <MASK>:
            column_subsample = self.subsample * len(column_nnz_data) // n_samples
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=column_subsample, dtype=X.dtype)
            else:
                column_data = np.zeros(shape=self.subsample, dtype=X.dtype)
            column_data[:column_subsample] = random_state.choice(column_nnz_data, size=column_subsample, replace=False)
        else:
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=len(column_nnz_data), dtype=X.dtype)
            else:
                column_data = np.zeros(shape=n_samples, dtype=X.dtype)
            column_data[:len(column_nnz_data)] = column_nnz_data
        if not column_data.size:
            self.quantiles_.append([0] * len(references))
        else:
            self.quantiles_.append(np.nanpercentile(column_data, references))
    self.quantiles_ = np.transpose(self.quantiles_)
    self.quantiles_ = np.maximum.accumulate(self.quantiles_)

@staticmethod
def masked(mask, body, other):
    if <MASK>:
        mask = V.kernel.cse.generate(V.kernel.compute, f'{mask}.to(tl.int1)', dtype=torch.bool, shape=mask.shape)
    nodes = body.graph.find_nodes(op='output')
    assert nodes, 'graph for body does not contain an output'
    need_where = False
    for node in nodes:
        for arg in node.args:
            if arg.target != 'load' or should_unwrap_unspec_arg(arg.args[1]):
                need_where = True
                break
    value = None if need_where else other
    with V.kernel.mask_loads(mask, value=value) as new_mask:
        result = body()
    if need_where:
        if result.bounds.is_bool:
            other = bool(other)
        other = V.kernel.cse.generate(V.kernel.compute, f'tl.full({result}.shape, {constant_repr(other)}, {result}.dtype)', bounds=ValueRanges.wrap(other), dtype=result.dtype, shape=result.shape)
        ret = ops.where(new_mask, result, other)
    else:
        ret = result
    ret.mask_vars.discard(new_mask)
    return ret

def _get_numeric_verify_tensor_details(self) -> List[str]:
    """Returns all names of all tensors from NumericVerify op."""
    if <MASK>:
        self._numeric_verify_tensor_details = []
        self._numeric_verify_op_details = {}
        for op_info in self._quant_interpreter._get_ops_details():
            if op_info['op_name'] == _NUMERIC_VERIFY_OP_NAME:
                self._numeric_verify_tensor_details.append(self._quant_interpreter._get_tensor_details(op_info['outputs'][0], subgraph_index=0))
                tensor_name = self._numeric_verify_tensor_details[-1]['name']
                self._numeric_verify_op_details[tensor_name] = op_info
    return self._numeric_verify_tensor_details

def _check_unique_target(self):
    rel_is_string = isinstance(self.remote_field.model, str)
    if rel_is_string or not self.requires_unique_target:
        return []
    try:
        self.foreign_related_fields
    except exceptions.FieldDoesNotExist:
        return []
    if <MASK>:
        return []
    has_unique_constraint = any((rel_field.unique for rel_field in self.foreign_related_fields))
    if not has_unique_constraint:
        foreign_fields = {f.name for f in self.foreign_related_fields}
        remote_opts = self.remote_field.model._meta
        has_unique_constraint = any((frozenset(ut) <= foreign_fields for ut in remote_opts.unique_together)) or any((frozenset(uc.fields) <= foreign_fields for uc in remote_opts.total_unique_constraints)) or frozenset((field.name for field in remote_opts.pk_fields)) == foreign_fields
    if not has_unique_constraint:
        if len(self.foreign_related_fields) > 1:
            field_combination = ', '.join((f"'{rel_field.name}'" for rel_field in self.foreign_related_fields))
            model_name = self.remote_field.model.__name__
            return [checks.Error(f"No subset of the fields {field_combination} on model '{model_name}' is unique.", hint='Mark a single field as unique=True or add a set of fields to a unique constraint (via unique_together or a UniqueConstraint (without condition) in the model Meta.constraints).', obj=self, id='fields.E310')]
        else:
            field_name = self.foreign_related_fields[0].name
            model_name = self.remote_field.model.__name__
            return [checks.Error(f"'{model_name}.{field_name}' must be unique because it is referenced by a foreign key.", hint='Add unique=True to this field or add a UniqueConstraint (without condition) in the model Meta.constraints.', obj=self, id='fields.E311')]
    return []

def _safe_repr(object, context, maxlevels, level, changed_only=False):
    """Same as the builtin _safe_repr, with added support for Estimator
    objects."""
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if issubclass(typ, dict) and r is dict.__repr__:
        if not object:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if <MASK>:
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            (orepr, oreadable, orecur) = _safe_repr(o, context, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if not oreadable:
                readable = False
            if orecur:
                recursive = True
        del context[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

def __next__(self) -> NSSubgraph:
    """
        Returns the next matchable subgraph.
        """
    while len(self.stack) > 0:
        cur_end_node = self.stack.pop()
        if cur_end_node in self.seen_nodes:
            continue
        cur_start_node = cur_end_node
        cur_base_op_node = cur_end_node
        for (_reverse_fusion_ops, base_op_idx) in get_reversed_fusions():
            is_match = end_node_matches_reversed_fusion(cur_end_node, _reverse_fusion_ops, self.gm, self.seen_nodes)
            if is_match:
                for rev_fusion_idx in range(len(_reverse_fusion_ops) - 1):
                    self.seen_nodes.add(cur_start_node)
                    cur_start_node = cur_start_node.args[0]
                    rev_base_op_idx = len(_reverse_fusion_ops) - 2 - base_op_idx
                    if rev_fusion_idx == rev_base_op_idx:
                        cur_base_op_node = cur_start_node
                break
        self.seen_nodes.add(cur_start_node)
        for arg in cur_start_node.all_input_nodes:
            self._recursively_add_node_arg_to_stack(arg)
        if not self._is_matchable(cur_base_op_node):
            continue
        if cur_end_node.op == 'call_module' and cur_start_node is cur_end_node:
            maybe_obs = getattr_from_fqn(self.gm, cur_end_node.target)
            if <MASK>:
                continue
        return NSSubgraph(start_node=cur_start_node, end_node=cur_end_node, base_op_node=cur_base_op_node)
    raise StopIteration

@triton_kernel_wrapper_mutation.py_impl(DispatchKey.CompositeExplicitAutograd)
def triton_kernel_wrapper_mutation_dense(*, kernel_idx: int, constant_args_idx: int, grid: list['TritonGridType'], tma_descriptor_metadata: TMADescriptorMetadata, kwargs: dict[str, Any]) -> None:
    from torch._inductor.codegen.wrapper import user_defined_kernel_grid_fn_code
    kernel = kernel_side_table.get_kernel(kernel_idx)
    constant_args = kernel_side_table.get_constant_args(constant_args_idx)
    if len(grid) == 1:
        grid_fn = grid[0]
    else:
        (fn_name, code) = user_defined_kernel_grid_fn_code(kernel.fn.__name__, kernel.configs, grid)
        namespace: dict[str, Any] = {}
        exec(code, namespace)
        grid_fn = namespace[fn_name]
    if tma_descriptor_metadata:
        kwargs = kwargs.copy()
        for (k, v) in tma_descriptor_metadata.items():
            tensor = kwargs[k]
            if (exp_meta := maybe_unpack_tma_experimental_metadata(v)) is not None:
                from triton.tools.experimental_descriptor import create_1d_tma_descriptor, create_2d_tma_descriptor
                (dims, block_dims, element_size) = exp_meta
                create_tma_descriptor = create_1d_tma_descriptor if len(dims) == 1 else create_2d_tma_descriptor
                kwargs[k] = create_tma_descriptor(tensor.data_ptr(), *dims, *block_dims, element_size)
            else:
                stable_meta = maybe_unpack_tma_stable_metadata(v)
                assert stable_meta is not None
                from triton.tools.tensor_descriptor import TensorDescriptor
                block_shape = stable_meta[0]
                kwargs[k] = TensorDescriptor.from_tensor(tensor, block_shape)
    args = []
    kwargs = kwargs.copy()
    constant_args = constant_args.copy()
    for name in kernel.arg_names:
        if <MASK>:
            args.append(kwargs.pop(name))
        elif name in constant_args:
            args.append(constant_args.pop(name))
        else:
            break
    kernel[grid_fn](*args, **kwargs, **constant_args)

def appenddecl(decl, decl2, force=1):
    if not decl:
        decl = {}
    if not decl2:
        return decl
    if decl is decl2:
        return decl
    for k in list(decl2.keys()):
        if k == 'typespec':
            if force or k not in decl:
                decl[k] = decl2[k]
        elif k == 'attrspec':
            for l in decl2[k]:
                decl = setattrspec(decl, l, force)
        elif k == 'kindselector':
            decl = setkindselector(decl, decl2[k], force)
        elif k == 'charselector':
            decl = setcharselector(decl, decl2[k], force)
        elif k in ['=', 'typename']:
            if force or k not in decl:
                decl[k] = decl2[k]
        elif <MASK>:
            pass
        elif k in ['intent', 'check', 'dimension', 'optional', 'required', 'depend']:
            errmess(f'appenddecl: "{k}" not implemented.\n')
        else:
            raise Exception('appenddecl: Unknown variable definition key: ' + str(k))
    return decl

def _update_initial(self, props: dict[str, str], inherited: dict[str, str]) -> dict[str, str]:
    for (prop, val) in inherited.items():
        if <MASK>:
            props[prop] = val
    new_props = props.copy()
    for (prop, val) in props.items():
        if val == 'inherit':
            val = inherited.get(prop, 'initial')
        if val in ('initial', None):
            del new_props[prop]
        else:
            new_props[prop] = val
    return new_props

