        raise ValueError(f'Missing {self.name}. Please set the {self.env_var} environment variable to pass in this value.')
    if <MASK>:
        return self.type_conversion_fn(value)
    return value

def _set_replacement(self, a: sympy.Symbol, tgt: sympy.Expr, msg: str) -> None:
    """
        Adds or updates a replacement for a symbol.
        Use this instead of `self.replacements[a] = tgt`.
        """
    if tgt == self.replacements.get(a, None):
        return
    if a in tgt.free_symbols:
        return
    assert isinstance(a, sympy.Symbol)
    if self.prefer_deferred_runtime_asserts_over_guards and (not _is_supported_equivalence(tgt)):
        return
    tgt_bound = None
    if a in self.var_to_range:
        src_bound = self.var_to_range[a]
        tgt_bound = self.bound_sympy(tgt)
        self._update_var_to_range(a, tgt_bound)
        if not tgt_bound.issubset(src_bound) and len(tgt.free_symbols) == 1:
            b = next(iter(tgt.free_symbols))
            r = try_solve(sympy.Eq(a, tgt), b, floordiv_inequality=False)
            if r is not None:
                self.log.debug('set_replacement: solve for %s in %s == %s gives %s', b, a, tgt, r)
                rat_b_bound = self.bound_sympy(r[1])
                b_bound = ValueRanges(CeilToInt(rat_b_bound.lower), FloorToInt(rat_b_bound.upper))
                self._update_var_to_range(b, b_bound, self.var_to_range_sloc[a])
                tgt_bound = self.bound_sympy(tgt)
                assert tgt_bound.issubset(src_bound), f'tgt_bound={tgt_bound!r} not a subset of src_bound={src_bound!r}'
        if a in self.size_like and isinstance(tgt, sympy.Symbol):
            self.size_like.add(tgt)
        elif isinstance(tgt, sympy.Symbol) and tgt in self.size_like:
            self.size_like.add(a)
        if not tgt_bound.issubset(src_bound):
            self.log.debug('skipped set_replacement %s = %s (%s) [%s not subset of %s]', a, tgt, msg, tgt_bound, src_bound)
            return
        elif a in self.size_like:
            tgt_bound_so = self.bound_sympy(tgt, size_oblivious=True)
            src_bound_so = self.bound_sympy(a, size_oblivious=True)
            if not tgt_bound_so.issubset(src_bound_so):
                self.log.debug('skipped set_replacement %s = %s (%s) [%s not subset of %s (size-oblivious conditions)]', a, tgt, msg, tgt_bound_so, src_bound_so)
                return
    if isinstance(tgt, (sympy.Integer, sympy.Float)):
        user_tb = TracingContext.extract_stack()
        trace_structured('symbolic_shape_specialization', metadata_fn=lambda : {'symbol': repr(a), 'sources': [s.name() for s in self.var_to_sources.get(a, [])], 'value': repr(tgt), 'reason': msg, 'stack': structured.from_traceback(CapturedTraceback.extract(skip=1).summary()), 'user_stack': structured.from_traceback(user_tb) if user_tb else None})
        for source in self.var_to_sources.get(a, []):
            if user_tb:
                self.specialization_stacks[source] = user_tb
        if <MASK>:
            self.log.warning('Specializing %s to %s', self.var_to_sources[a][0].name(), tgt)
            self.log.debug('SPECIALIZATION', stack_info=True)
    log.info('set_replacement %s = %s (%s) %s', a, tgt, msg, tgt_bound)
    self.replacements[a] = tgt
    if a not in self.replacements_slocs:
        self.replacements_slocs[a] = self._get_sloc()
    self._update_version_counter()
    self._add_target_expr(sympy.Eq(a, tgt, evaluate=False))

@contextlib.contextmanager
