def _parse_multi_target(self, targets):
    """validate multi targets that defined between parentheses()"""
    if not targets:
        self.dist_fatal("empty multi-target '()'")
    if not all([self.feature_is_exist(tar) for tar in targets]):
        self.dist_fatal('invalid target name in multi-target', targets)
    if <MASK>:
        return None
    targets = self.feature_ahead(targets)
    if not targets:
        return None
    targets = self.feature_sorted(targets)
    targets = tuple(targets)
    return targets

def match_row_splits_dtypes(*tensors, **kwargs):
    """Return a copy of `tensors` with row_splits all having the same dtype.

  Args:
    *tensors: A list of Tensors or RaggedTensors.
    **kwargs: If 'return_dtype=True', then return a tuple (dtype, tensors),
      where `dtype` is the data type used by row-splits, and `tensors` is the
      converted list of `Tensors` and `RaggedTensors`.

  Returns:
    The converted list of `Tensors` and `RaggedTensors`.
  """
    return_dtype = kwargs.pop('return_dtype', False)
    if <MASK>:
        raise ValueError(f'Unexpected keyword args {kwargs}.')
    has_int32 = False
    has_int64 = False
    for tensor in tensors:
        if isinstance(tensor, RaggedTensor):
            if tensor.row_splits.dtype == dtypes.int32:
                has_int32 = True
            else:
                has_int64 = True
    if has_int32 and has_int64:
        if not ragged_config.auto_cast_partition_dtype():
            raise ValueError('Input RaggedTensors have mismatched row_splits dtypes; use RaggedTensor.with_row_splits_dtype() to convert them to compatible dtypes.')
        dtype = dtypes.int64
        tensors = tuple((t.with_row_splits_dtype(dtypes.int64) if isinstance(t, RaggedTensor) else t for t in tensors))
    elif has_int32:
        dtype = dtypes.int32
    else:
        dtype = dtypes.int64
    if return_dtype:
        return (dtype, tensors)
    else:
        return tensors

def should_trigger_for_step(self, step):
    """Return true if the timer should trigger for the specified step.

    Args:
      step: Training step to trigger on.

    Returns:
      True if the difference between the current time and the time of the last
      trigger exceeds `every_secs`, or if the difference between the current
      step and the last triggered step exceeds `every_steps`. False otherwise.
    """
    if self._last_triggered_step is None:
        return True
    if self._last_triggered_step == step:
        return False
    if self._every_secs is not None:
        if <MASK>:
            return True
    if self._every_steps is not None:
        if step >= self._last_triggered_step + self._every_steps:
            return True
    return False

def datetimes(self, field_name, kind, order='ASC', tzinfo=None):
    """
        Return a list of datetime objects representing all available
        datetimes for the given field_name, scoped to 'kind'.
        """
    if kind not in ('year', 'month', 'week', 'day', 'hour', 'minute', 'second'):
        raise ValueError("'kind' must be one of 'year', 'month', 'week', 'day', 'hour', 'minute', or 'second'.")
    if order not in ('ASC', 'DESC'):
        raise ValueError("'order' must be either 'ASC' or 'DESC'.")
    if settings.USE_TZ:
        if <MASK>:
            tzinfo = timezone.get_current_timezone()
    else:
        tzinfo = None
    return self.annotate(datetimefield=Trunc(field_name, kind, output_field=DateTimeField(), tzinfo=tzinfo), plain_field=F(field_name)).values_list('datetimefield', flat=True).distinct().filter(plain_field__isnull=False).order_by(('-' if order == 'DESC' else '') + 'datetimefield')

@wraps(func)
def wrapper(*args, **kwargs) -> Callable[..., Any]:
    __tracebackhide__ = True
    old_arg_value = kwargs.pop(old_arg_name, None)
    if old_arg_value is not None:
        if new_arg_name is None:
            msg = f'the {old_arg_name!r} keyword is deprecated and will be removed in a future version. Please take steps to stop the use of {old_arg_name!r}'
            warnings.warn(msg, klass, stacklevel=stacklevel)
            kwargs[old_arg_name] = old_arg_value
            return func(*args, **kwargs)
        elif mapping is not None:
            if <MASK>:
                new_arg_value = mapping(old_arg_value)
            else:
                new_arg_value = mapping.get(old_arg_value, old_arg_value)
            msg = f'the {old_arg_name}={old_arg_value!r} keyword is deprecated, use {new_arg_name}={new_arg_value!r} instead.'
        else:
            new_arg_value = old_arg_value
            msg = f'the {old_arg_name!r} keyword is deprecated, use {new_arg_name!r} instead.'
        warnings.warn(msg, klass, stacklevel=stacklevel)
        if kwargs.get(new_arg_name) is not None:
            msg = f'Can only specify {old_arg_name!r} or {new_arg_name!r}, not both.'
            raise TypeError(msg)
        kwargs[new_arg_name] = new_arg_value
    return func(*args, **kwargs)

