def suffix_product(a: IntTuple, init: IntTuple=1) -> IntTuple:
    if <MASK>:
        if is_tuple(init):
            assert len(a) == len(init)
            return tuple((suffix_product(x, i) for (x, i) in zip(a, init)))
        else:
            r = []
            for i in range(len(a) - 1, -1, -1):
                r.append(suffix_product(a[i], init))
                init = init * product(a[i])
            r.reverse()
            return tuple(r)
    elif is_tuple(init):
        raise AssertionError('Invalid combination: int with tuple init')
    else:
        return init

def _override(self, func, args, kwargs):
    if torch.distributed.is_available():
        from torch.distributed._functional_collectives import REDUCE_OP_TO_STR, traceable_collective_remaps
        if func in traceable_collective_remaps:
            mapped_func = traceable_collective_remaps[func]
            signature = inspect.signature(func)
            kwargs = dict(signature.bind(*args, **kwargs).arguments)
            args = ()
            if func in (torch.distributed.all_reduce, torch.distributed.reduce_scatter_tensor, torch.distributed._reduce_scatter_base):
                if 'op' in kwargs:
                    kwargs['op'] = REDUCE_OP_TO_STR[kwargs['op']]
            return (mapped_func, args, kwargs)
    if func is torch.tensor:
        if any((isinstance(a, (torch.SymInt, torch.SymFloat, torch.SymBool)) for a in pytree.tree_flatten(args[0])[0])):
            return (torch._refs.tensor, args, kwargs)
    if func.__name__ == '__getitem__' and isinstance(args[0], torch.Tensor):

        def rewrite(dim, item):
            if item is None:
                return (dim + 1, (torch.unsqueeze, [dim]))
            if isinstance(item, (int, torch.SymInt)):
                return (dim, (torch.select, [dim, item]))
            if isinstance(item, slice):
                step = item.step or 1
                if item.start is None and item.stop is None and (step == 1):
                    return (dim + 1, (lambda t: t, []))
                return (dim + 1, (torch.ops.aten.slice, [dim, item.start, item.stop, step]))
        items = list(args[1]) if isinstance(args[1], tuple) else [args[1]]
        has_symint = False
        index_ellipsis = None
        t = args[0]
        n_none_slices = t.ndim + 1
        for (i, item) in enumerate(items):
            if isinstance(item, torch.SymInt) or (isinstance(item, slice) and any((isinstance(s, torch.SymInt) for s in (item.start, item.stop, item.step)))):
                has_symint = True
            if <MASK>:
                index_ellipsis = i
            if item is not None:
                n_none_slices -= 1
        if has_symint:
            if index_ellipsis is not None:
                none_slices = [slice(None)] * n_none_slices
                items[index_ellipsis:index_ellipsis + 1] = none_slices
            dim = 0
            sequence = []
            for item in items:
                if (r := rewrite(dim, item)) is None:
                    return (func, args, kwargs)
                (dim, call_spec) = r
                sequence.append(call_spec)

            def run():
                t = args[0]
                for (_method, _args) in sequence:
                    t = _method(t, *_args)
                return t
            return (run, [], {})
    return (func, args, kwargs)

def _emit_default_constant_from_proto(self, attr_def):
    """emit mlir constant statement from default value of the ArgDef proto."""
    name = self._ssa_name('cst')
    cst_ty = _get_type_from_proto(None, attr_def)
    try:
        cst_val = _get_val_from_proto(cst_ty, attr_def.default_value)
    except AttributeError:
        raise AttributeError(f'''attribute "{attr_def.name}" does not have default_value. If the attribute names from the API and OpDef don't match, please add it to _ATTRIBUTE_RENAMES.''')
    if cst_ty == TFRTypes.ATTR:
        self._emit_with_loc('\n{} = tfr.constant {} -> {}'.format(name, cst_val, cst_ty))
    elif <MASK>:
        self._emit_with_loc('\n{} = arith.constant {}'.format(name, cst_val))
    else:
        self._emit_with_loc('\n{} = arith.constant {} : {}'.format(name, cst_val, cst_ty))
    return (name, cst_ty)

def average(a: ArrayLike, axis=None, weights: ArrayLike=None, returned=False, *, keepdims=False):
    if weights is None:
        result = mean(a, axis=axis)
        wsum = torch.as_tensor(a.numel() / result.numel(), dtype=result.dtype)
    else:
        if not a.dtype.is_floating_point:
            a = a.double()
        if a.shape != weights.shape:
            if axis is None:
                raise TypeError('Axis must be specified when shapes of a and weights differ.')
            if weights.ndim != 1:
                raise TypeError('1D weights expected when shapes of a and weights differ.')
            if weights.shape[0] != a.shape[axis]:
                raise ValueError('Length of weights not compatible with specified axis.')
            weights = torch.broadcast_to(weights, (a.ndim - 1) * (1,) + weights.shape)
            weights = weights.swapaxes(-1, axis)
        result_dtype = _dtypes_impl.result_type_impl(a, weights)
        numerator = sum(a * weights, axis, dtype=result_dtype)
        wsum = sum(weights, axis, dtype=result_dtype)
        result = numerator / wsum
    if keepdims:
        result = _util.apply_keepdims(result, axis, a.ndim)
    if returned:
        if <MASK>:
            wsum = torch.broadcast_to(wsum, result.shape).clone()
        return (result, wsum)
    else:
        return result

def max_pool2d_checks_and_compute_shape(input, kernel_size, stride, padding, dilation, ceil_mode):

    def unpack(name, val):
        torch._check(len(val) in [1, 2], lambda : f'max_pool2d: {name} must either be a single int, or a tuple of two ints')
        H = val[0]
        W = H if len(val) == 1 else val[1]
        return (H, W)
    (kH, kW) = unpack('kernel_size', kernel_size)
    torch._check(len(stride) in [0, 1, 2], lambda : 'max_pool2d: stride must either be omitted, a single int, or a tuple of two ints')
    if <MASK>:
        (dH, dW) = (kH, kW)
    else:
        (dH, dW) = unpack('stride', stride)
    (padH, padW) = unpack('padding', padding)
    (dilationH, dilationW) = unpack('dilation', dilation)
    nInputPlane = input.size(-3)
    inputHeight = input.size(-2)
    inputWidth = input.size(-1)
    memory_format = utils.suggest_memory_format(input)
    if memory_format == torch.channels_last:
        torch._check(input.dim() == 4, lambda : 'non-empty 4D (batch mode) tensor expected for input with channels_last layout')
    elif memory_format == torch.contiguous_format:
        torch._check(input.dim() in [3, 4], lambda : 'non-empty 3D or 4D (batch mode) tensor expected for input')
    else:
        torch._check(False, lambda : 'Unsupported memory format. Supports only ChannelsLast, Contiguous')
    outputHeight = pooling_output_shape(inputHeight, kH, padH, dH, dilationH, ceil_mode)
    outputWidth = pooling_output_shape(inputWidth, kW, padW, dW, dilationW, ceil_mode)
    pool2d_shape_check(input, kH, kW, dH, dW, padH, padW, dilationH, dilationW, nInputPlane, inputHeight, inputWidth, outputHeight, outputWidth, memory_format)
    return (nInputPlane, outputHeight, outputWidth)

def _has_proper_decorator(self, node: ast.FunctionDef) -> bool:
    for d in node.decorator_list:
        if <MASK>:
            return True
        if isinstance(d, ast.Call) and isinstance(d.func, ast.Name) and (d.func.id in GPU_RELATED_DECORATORS):
            return True
    return False

@tf_export.tf_export('experimental.numpy.result_type', v1=[])
@np_doc_only('result_type')
def result_type(*arrays_and_dtypes):
    if <MASK>:
        (dtype, _) = flexible_dtypes.result_type(*arrays_and_dtypes)
        return dtype
    arrays_and_dtypes = [_maybe_get_dtype(x) for x in nest.flatten(arrays_and_dtypes)]
    if not arrays_and_dtypes:
