    return np_dtypes._result_type(*arrays_and_dtypes)

def _ConstructAndTestGradientForConfig(self, batch, input_shape, filter_shape, in_depth, out_depth, stride, padding, test_input, data_format, use_gpu):
    (input_planes, input_rows, input_cols) = input_shape
    (filter_planes, filter_rows, filter_cols) = filter_shape
    input_shape = [batch, input_planes, input_rows, input_cols, in_depth]
    filter_shape = [filter_planes, filter_rows, filter_cols, in_depth, out_depth]
    if isinstance(stride, collections_abc.Iterable):
        strides = [1] + list(stride) + [1]
    else:
        strides = [1, stride, stride, stride, 1]
    if <MASK>:
        output_planes = int(math.ceil((input_planes - filter_planes + 1.0) / strides[1]))
        output_rows = int(math.ceil((input_rows - filter_rows + 1.0) / strides[2]))
        output_cols = int(math.ceil((input_cols - filter_cols + 1.0) / strides[3]))
    else:
        output_planes = int(math.ceil(float(input_planes) / strides[1]))
        output_rows = int(math.ceil(float(input_rows) / strides[2]))
        output_cols = int(math.ceil(float(input_cols) / strides[3]))
    output_shape = [batch, output_planes, output_rows, output_cols, out_depth]
    input_size = 1
    for x in input_shape:
        input_size *= x
    filter_size = 1
    for x in filter_shape:
        filter_size *= x
    input_data = [x * 1.0 / input_size for x in range(0, input_size)]
    filter_data = [x * 1.0 / filter_size for x in range(0, filter_size)]
    for data_type in DtypesToTest(use_gpu=use_gpu):
        if data_type == dtypes.float64:
            tolerance = 1e-08
        elif data_type == dtypes.float32:
            tolerance = 0.005
        elif data_type == dtypes.float16:
            tolerance = 0.005 if test.is_built_with_rocm() else 0.001
        elif data_type == dtypes.bfloat16:
            tolerance = 0.01
        with self.cached_session(use_gpu=use_gpu):
            orig_input_tensor = constant_op.constant(input_data, shape=input_shape, dtype=data_type, name='input')
            filter_tensor = constant_op.constant(filter_data, shape=filter_shape, dtype=data_type, name='filter')
            if data_format == 'NCDHW':
                input_tensor = test_util.NHWCToNCHW(orig_input_tensor)
                new_strides = test_util.NHWCToNCHW(strides)
            else:
                input_tensor = orig_input_tensor
                new_strides = strides
            conv = nn_ops.conv3d(input_tensor, filter_tensor, new_strides, padding, data_format=data_format, name='conv')
            if data_format == 'NCDHW':
                conv = test_util.NCHWToNHWC(conv)
            self.assertEqual(conv.shape, tensor_shape.TensorShape(output_shape))
            if test_input:
                (jacob_t, jacob_n) = gradient_checker.compute_gradient(orig_input_tensor, input_shape, conv, output_shape)
            else:
                (jacob_t, jacob_n) = gradient_checker.compute_gradient(filter_tensor, filter_shape, conv, output_shape)
            if data_type != dtypes.float16 and data_type != dtypes.bfloat16:
                reference_jacob_t = jacob_t
                err = np.fabs(jacob_t - jacob_n).max()
            else:
                err = np.fabs(jacob_t - reference_jacob_t).max()
        print('conv3d gradient error = ', err)
        self.assertLess(err, tolerance)

def prettify_results(self, original_signature: inspect.Signature, dynamic_shapes: Union[dict[str, Any], tuple[Any], list[Any]], constraint_violation_error: object, forced_specializations: dict[str, str]) -> str:
    """Format a message for constraint violation errors"""
    from torch.export.dynamic_shapes import _get_dim_name_mapping
    if not self._dcp.source_name_to_debug_name:
        return ''

    def transform(s: str, inverse: bool=False) -> str:
        for (k, v) in self._dcp.source_name_to_debug_name.items():
            s = s.replace(k, v) if not inverse else s.replace(v, k)
        return s
    results: defaultdict[str, dict[str, Any]] = defaultdict(dict)
    if dynamic_shapes is None:
        dynamic_shapes = {}

    def flip(op: str) -> str:
        if op == '<=':
            return '>='
        if <MASK>:
            return '<='
        if op == '<':
            return '>'
        if op == '>':
            return '<'
        assert op == '=='
        return op

    def relation_with_digit(expr: str, op: str, digit: int) -> None:
        if op == '<=':
            results[expr]['max'] = digit
        elif op == '<':
            results[expr]['max'] = digit - 1
        elif op == '>=':
            results[expr]['min'] = digit
        elif op == '>':
            results[expr]['min'] = digit + 1
        else:
            assert op == '=='
            results[expr]['eq'] = digit
    name_to_dim = _get_dim_name_mapping(dynamic_shapes)
    for s in self._static_results.union(self._dynamic_results):
        t = transform(s)
        if t == s:
            continue
        (left, op, right) = re.split('( == | <= | >= | < | > )', t)
        op = op.strip()
        if op == '==' and left == right:
            continue
        if right.isdigit():
            relation_with_digit(left, op, int(right))
        elif left.isdigit():
            relation_with_digit(right, flip(op), int(left))
        else:
            assert op == '==', t
            try:
                results[left]['eq'] = sympy.sympify(right)
            except TypeError:
                pass
    forced_specializations = {k: forced_specializations[k] for k in sorted(forced_specializations.keys(), key=lambda x: x.split(' = ')[1])}
    buf = ''
    if forced_specializations:
        debug_names = set()
        for k in forced_specializations:
            dim = name_to_dim[k.split(' = ')[0]]
            if self._is_derived_dim(dim):
                debug_names.add(dim.root.__name__)
            else:
                debug_names.add(dim.__name__)
        buf += f"""Specializations unexpectedly required ({', '.join(sorted(debug_names))})! For more information, run with TORCH_LOGS="+dynamic".\n"""
        for (s, val) in forced_specializations.items():
            buf += f'  - solving the guards generated for {s} resulted in a specialized value of {val}.\n'
    self._process_derived_dim_roots(results, name_to_dim)
    dims = []
    others = []
    results2 = {k: results[k] for k in sorted(results.keys(), key=lambda x: transform(x, inverse=True))}
    for (k, c) in results2.items():
        if 'eq' in c:
            other = c['eq']
            if isinstance(other, int):
                others.append(f'{k} = {other}')
            elif _is_supported_equivalence(other):
                others.append(f'{k} = {other}')
        else:
            min_ = c.get('min', None)
            if min_ == 2:
                min_ = None
            max_ = c.get('max', None)
            if min_ is not None and max_ is not None:
                dims.append(f"{k} = Dim('{k}', min={min_}, max={max_})")
            elif min_ is not None:
                dims.append(f"{k} = Dim('{k}', min={min_})")
            elif max_ is not None:
                dims.append(f"{k} = Dim('{k}', max={max_})")
            else:
                dims.append(f"{k} = Dim('{k}')")
    if dims or others:
        buf += '\nSuggested fixes:\n  '
        buf += '\n  '.join(dims + others)
    return buf

def __call__(self, ctx: _RendezvousContext, deadline: float) -> _Action:
    if ctx.node in ctx.state.participants:
        if <MASK>:
            return _Action.ERROR_TIMEOUT
        return _Action.REMOVE_FROM_PARTICIPANTS
    return _Action.FINISH

def run_node(self, node: torch.fx.Node) -> Any:
    if node.op in ('placeholder', 'output'):
        return super().run_node(node)
    target = node.target
    (args, kwargs) = self.fetch_args_kwargs_from_env(node)
    if node.op == 'call_function':
        assert callable(target)
        result = graph.call_function(target, args, kwargs)
        added_replacement_nodes.append(result)
        _transfer_meta(new_meta=result.meta, old_node=node, pass_name='Interpreter_Replacer')
        if 'eager_input_vals' in node.meta:
            result.meta['eager_input_vals'] = node.meta['eager_input_vals']
        if 'val' in node.meta and 'val' not in result.meta:
            result.meta['val'] = node.meta['val']
            if isinstance(node.meta['val'], torch.Tensor):
                assert 'tensor_meta' in node.meta
                result.meta['tensor_meta'] = node.meta['tensor_meta']
        return result
    if node.op == 'get_attr':
        from torch._higher_order_ops.utils import unique_graph_name_with_root
        sub_gm = super().get_attr(target, args, kwargs)
        if not isinstance(sub_gm, torch.fx.GraphModule):
            raise NotImplementedError(f'NYI: replacement_graph.{target} is not a graph module. Got {sub_gm}.')
        assert graph.owning_module is not None
        graph_name = None
        for (n, mod) in graph.owning_module.named_modules():
            if <MASK>:
                graph_name = n
                break
        if graph_name is None:
            assert isinstance(target, str)
            (_, graph_name) = unique_graph_name_with_root(graph.owning_module, target)
            graph.owning_module.register_module(graph_name, sub_gm)
        getattr_node = graph.get_attr(graph_name)
        added_replacement_nodes.append(getattr_node)
        return getattr_node
    raise NotImplementedError(f'unhandled {node}')

def _generate_tensor_methods_for_privateuse1_backend(custom_backend_name: str) -> None:

    @property
    def wrap_tensor_backend(self: torch.Tensor) -> bool:
        if <MASK>:
            return handle_torch_function(wrap_tensor_backend.__get__, (self,), self)
        return self.device.type == custom_backend_name
    _check_register_once(torch.Tensor, f'is_{custom_backend_name}')
    wrap_tensor_backend.fget.__name__ = f'is_{custom_backend_name}'
    setattr(torch.Tensor, f'is_{custom_backend_name}', wrap_tensor_backend)

    def wrap_tensor_to(self: torch.Tensor, device: Optional[Union[int, torch.device]]=None, non_blocking=False, **kwargs) -> torch.Tensor:
        """Perform Tensor device conversion. Call the to operator implementation.

        .. note::
            If the ``self`` Tensor already
            has the correct :class:`torch.device`, then ``self`` is returned.
            Otherwise, the returned tensor is a copy of ``self`` with the desired :class:`torch.device`.

        Args:
            device (int, optional): if specified, all parameters will be copied to that device
            non_blocking (bool): If ``True`` and the source is in pinned memory,
                the copy will be asynchronous with respect to the host. Otherwise,
                the argument has no effect.
            **kwargs (dict): For compatibility, may contain the key ``memory_format`` argument.
        """
        if has_torch_function_unary(self):
            return handle_torch_function(wrap_tensor_to, (self,), self, device=device, non_blocking=False, **kwargs)
        device_idx = _normalization_device(custom_backend_name, device)
        return self.to(device=torch.device(f'{custom_backend_name}:{device_idx}'), non_blocking=non_blocking, **kwargs)
    _check_register_once(torch.Tensor, custom_backend_name)
    wrap_tensor_to.__name__ = custom_backend_name
    setattr(torch.Tensor, custom_backend_name, wrap_tensor_to)

def _call_func(self, args, kwargs):
    try:
        if self._variables_created:
            vars_at_start = len(ops.get_collection_ref(ops.GraphKeys.GLOBAL_VARIABLES))
            trainable_at_start = len(ops.get_collection_ref(ops.GraphKeys.TRAINABLE_VARIABLES))
            result = self._func(*args, **kwargs)
            trainable_variables = ops.get_collection_ref(ops.GraphKeys.TRAINABLE_VARIABLES)
            if trainable_at_start != len(trainable_variables):
                raise ValueError('Trainable variable created when calling a template after the first time, perhaps you used tf.Variable when you meant tf.get_variable: %s' % (trainable_variables[trainable_at_start:],))
            variables = ops.get_collection_ref(ops.GraphKeys.GLOBAL_VARIABLES)
            if vars_at_start != len(variables):
                logging.info('New variables created when calling a template after the first time, perhaps you used tf.Variable when you meant tf.get_variable: %s', variables[vars_at_start:])
        elif self._first_call:
            self._first_call = False
            try:
                with trackable_util.capture_dependencies(template=self):
                    result = self._func(*args, **kwargs)
            except:
                self._first_call = True
                raise
            self._variables_created = True
        else:
            result = self._func(*args, **kwargs)
        return result
    except Exception as exc:
        args = exc.args
        if <MASK>:
            arg0 = ''
        else:
            arg0 = args[0]
        trace = ''.join(_skip_common_stack_elements(self._stacktrace, traceback.format_stack()))
        arg0 = '%s\n\noriginally defined at:\n%s' % (arg0, trace)
        new_args = [arg0]
        new_args.extend(args[1:])
        exc.args = tuple(new_args)
        raise

def _get_loc_level(self, key, level: int | list[int]=0):
    """
        get_loc_level but with `level` known to be positional, not name-based.
        """

    def maybe_mi_droplevels(indexer, levels):
        """
            If level does not exist or all levels were dropped, the exception
            has to be handled outside.
            """
        new_index = self[indexer]
        for i in sorted(levels, reverse=True):
            new_index = new_index._drop_level_numbers([i])
        return new_index
    if isinstance(level, (tuple, list)):
        if len(key) != len(level):
            raise AssertionError('Key for location must have same length as number of levels')
        result = None
        for (lev, k) in zip(level, key, strict=True):
            (loc, new_index) = self._get_loc_level(k, level=lev)
            if isinstance(loc, slice):
                mask = np.zeros(len(self), dtype=bool)
                mask[loc] = True
                loc = mask
            result = loc if result is None else result & loc
        try:
            mi = maybe_mi_droplevels(result, level)
        except ValueError:
            mi = self[result]
        return (result, mi)
    if isinstance(key, list):
        key = tuple(key)
    if isinstance(key, tuple) and level == 0:
        try:
            if key in self.levels[0]:
                indexer = self._get_level_indexer(key, level=level)
                new_index = maybe_mi_droplevels(indexer, [0])
                return (indexer, new_index)
        except (TypeError, InvalidIndexError):
            pass
        if not any((isinstance(k, slice) for k in key)):
            if len(key) == self.nlevels and self.is_unique:
                try:
                    return (self._engine.get_loc(key), None)
                except KeyError as err:
                    raise KeyError(key) from err
                except TypeError:
                    pass
            indexer = self.get_loc(key)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            if len(ilevels) == self.nlevels:
                if is_integer(indexer):
                    return (indexer, None)
                ilevels = [i for i in range(len(key)) if (not isinstance(key[i], str) or not self.levels[i]._supports_partial_string_indexing) and key[i] != slice(None, None)]
                if len(ilevels) == self.nlevels:
                    ilevels = []
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
        else:
            indexer = None
            for (i, k) in enumerate(key):
                if not isinstance(k, slice):
                    loc_level = self._get_level_indexer(k, level=i)
                    if isinstance(loc_level, slice):
                        if com.is_null_slice(loc_level) or com.is_full_slice(loc_level, len(self)):
                            continue
                        k_index = np.zeros(len(self), dtype=bool)
                        k_index[loc_level] = True
                    else:
                        k_index = loc_level
                elif com.is_null_slice(k):
                    continue
                else:
                    raise TypeError(f'Expected label or tuple of labels, got {key}')
                if indexer is None:
                    indexer = k_index
                else:
                    indexer &= k_index
            if indexer is None:
                indexer = slice(None, None)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
    else:
        indexer = self._get_level_indexer(key, level=level)
        if isinstance(key, str) and self.levels[level]._supports_partial_string_indexing:
            check = self.levels[level].get_loc(key)
            if <MASK>:
                return (indexer, self[indexer])
        try:
            result_index = maybe_mi_droplevels(indexer, [level])
        except ValueError:
            result_index = self[indexer]
        return (indexer, result_index)

def match_expected_attrs(self, actual, expected, expected_dtype, res_type, msg=None):
    msg_ = 'Expected: {} Actual: {}'.format(expected, actual)
    if msg:
        msg = '{} {}'.format(msg_, msg)
    else:
        msg = msg_
    self.match_dtype_and_type(actual, expected_dtype, res_type, msg)
    self.match_shape(actual, expected, msg)
    if <MASK>:
        self.assertAllClose(actual.tolist(), expected.tolist())
    else:
        self.assertAllClose(actual.tolist(), expected.tolist())

def parseNestedExpr(expr, module) -> tuple[Any, int]:
    i = 0
    while i < len(expr) and expr[i] not in (',', '[', ']'):
        i += 1
    if expr[:i] == '()':
        return ((), i)
    base = lookupInModule(expr[:i].strip(), module)
    assert base is not None, f'Unresolvable type {expr[:i]}'
    if <MASK>:
        return (base, i)
    assert expr[i] == '['
    parts = []
    while expr[i] != ']':
        part_len = 0
        i += 1
        (part, part_len) = parseNestedExpr(expr[i:], module)
        parts.append(part)
        i += part_len
    if len(parts) > 1:
        return (base[tuple(parts)], i + 1)
    else:
        return (base[parts[0]], i + 1)

def calculate_extra_mem_bytes_needed_for(partition: Partition, partitions: list[Partition]):
    all_nodes: set[Node] = set()
    for p in partitions:
        all_nodes = all_nodes.union(p.nodes)
    if <MASK>:
        return partition.used_mem_bytes
    all_nodes = all_nodes.union(partition.nodes)
    extra_size_needed = 0
    for node in partition.nodes:
        extra_size_needed += get_extra_size_of(node, all_nodes)
    return extra_size_needed

def find_coalesced_group_with_non_p2p(pg_name: str, entries: list[dict[str, Any]], _pg_guids: dict[tuple[str, int], str], rank: int) -> list[tuple[int, dict[str, Any]]]:
    """Given a list of entries, if the collective_seq_id of the first entry matches that of subsequent ones,
    build an return a list of entries terminating in a 'coalesced' op entry all sharing a collective_seq_id
    """
    found = []
    collective_seq_id = None
    for (i, e) in enumerate(entries):
        if _pg_guids[e['process_group'][0], rank] != pg_name:
            continue
        elif collective_seq_id is None:
            collective_seq_id = e['p2p_seq_id'] if e['is_p2p'] else e['collective_seq_id']
            found.append((i, e))
        elif not e['is_p2p'] and e['collective_seq_id'] == collective_seq_id:
            found.append((i, e))
        elif e['is_p2p'] and e['p2p_seq_id'] == collective_seq_id:
            found.append((i, e))
        else:
            break
    if len(found) > 1:
        name = found[-1][1]['profiling_name']
        if <MASK>:
            logger.error('Rank %s does not have a coalesced end.', rank)
        return found
    return []

def _type_name(t):
    """Convert type into human readable string."""
    module = t.__module__
    qualname = t.__qualname__
    if <MASK>:
        return qualname
    elif t == Real:
        return 'float'
    elif t == Integral:
        return 'int'
    return f'{module}.{qualname}'

@classmethod
def disable_subsystem(cls, backend: str, subsystem: str, debug_info: Optional[Callable[[], str]]=None) -> bool:
    if not cls.bisection_enabled:
        return False
    if cls.get_backend() != backend:
        return False
    if cls.get_subsystem() != subsystem:
        return False
    if (val := get_env_val('TORCH_BISECT_MAX')):
        counter = cls.get_system_counter(subsystem, increment=True)
        return counter > int(val)
    run_state = cls.get_run_state(backend, subsystem)
    if run_state == 'test_disable':
        return True
    elif <MASK>:
        cls.update_bisect_range(backend, subsystem, 0, cls.get_system_counter(subsystem, increment=True))
        return False
    else:
        assert run_state == 'bisect'
        (low, high) = cls.get_bisect_range(backend, subsystem)
        midpoint = (low + high) // 2
        call_counter = cls.get_system_counter(subsystem)
        if call_counter >= low and call_counter <= high and (low - high <= 2) and (debug_info is not None):
            call_counter_debug_info[call_counter] = debug_info()
        return call_counter > midpoint

def _convert_to_export_graph_signature(graph_signature: 'GraphSignature', gm: 'torch.fx.GraphModule', non_persistent_buffers: set[str]) -> 'ExportGraphSignature':
    from torch.utils import _pytree as pytree
    is_joint = graph_signature.backward_signature is not None
    user_inputs = set(graph_signature.user_inputs)
    inputs_to_parameters = graph_signature.inputs_to_parameters
    inputs_to_buffers = graph_signature.inputs_to_buffers
    user_outputs = set(graph_signature.user_outputs)
    buffer_mutations = graph_signature.buffers_to_mutate
    parameter_mutations = graph_signature.parameters_to_mutate
    user_input_mutations = graph_signature.user_inputs_to_mutate
    grad_params = graph_signature.backward_signature.gradients_to_parameter if is_joint else {}
    grad_user_inputs = graph_signature.backward_signature.gradients_to_user_inputs if is_joint else {}
    loss_output = graph_signature.backward_signature.loss_output if is_joint else None
    input_tokens = graph_signature.input_tokens
    output_tokens = graph_signature.output_tokens
    inputs = [_make_argument_spec(node, input_tokens) for node in gm.graph.nodes if node.op == 'placeholder']
    outputs = [_make_argument_spec(node, output_tokens) for node in pytree.tree_leaves(next(iter(reversed(gm.graph.nodes))).args)]

    def to_input_spec(inp: ArgumentSpec) -> InputSpec:
        if isinstance(inp, TokenArgument):
            return InputSpec(kind=InputKind.TOKEN, arg=inp, target=None)
        if not isinstance(inp, TensorArgument):
            return InputSpec(kind=InputKind.USER_INPUT, arg=inp, target=None)
        name = inp.name
        if name in user_inputs:
            return InputSpec(kind=InputKind.USER_INPUT, arg=inp, target=None)
        elif name in inputs_to_parameters:
            return InputSpec(kind=InputKind.PARAMETER, arg=inp, target=inputs_to_parameters[name])
        elif <MASK>:
            return InputSpec(kind=InputKind.BUFFER, arg=inp, target=inputs_to_buffers[name], persistent=inputs_to_buffers[name] not in non_persistent_buffers)
        else:
            raise AssertionError(f'Unknown tensor input kind: {name}')

    def to_output_spec(idx: int, o: ArgumentSpec) -> OutputSpec:
        if isinstance(o, TokenArgument):
            return OutputSpec(kind=OutputKind.TOKEN, arg=o, target=None)
        if not isinstance(o, TensorArgument):
            return OutputSpec(kind=OutputKind.USER_OUTPUT, arg=o, target=None)
        name = o.name
        if idx < len(buffer_mutations) + len(parameter_mutations) + len(user_input_mutations) + len(output_tokens):
            if name in buffer_mutations:
                return OutputSpec(kind=OutputKind.BUFFER_MUTATION, arg=o, target=buffer_mutations[name])
            elif name in parameter_mutations:
                return OutputSpec(kind=OutputKind.PARAMETER_MUTATION, arg=o, target=parameter_mutations[name])
            elif name in user_input_mutations:
                return OutputSpec(kind=OutputKind.USER_INPUT_MUTATION, arg=o, target=user_input_mutations[name])
            else:
                raise AssertionError(f'Unknown tensor mutation kind: {name}')
        elif name in user_outputs:
            return OutputSpec(kind=OutputKind.USER_OUTPUT, arg=o, target=None)
        elif name in grad_params:
            return OutputSpec(kind=OutputKind.GRADIENT_TO_PARAMETER, arg=o, target=grad_params[name])
        elif name in grad_user_inputs:
            return OutputSpec(kind=OutputKind.GRADIENT_TO_USER_INPUT, arg=o, target=grad_user_inputs[name])
        elif name == loss_output:
            return OutputSpec(kind=OutputKind.LOSS_OUTPUT, arg=o, target=None)
        else:
            raise AssertionError(f'Unknown tensor output kind: {name}')
    input_specs = [to_input_spec(inp) for inp in inputs]
    output_specs = [to_output_spec(idx, o) for (idx, o) in enumerate(outputs)]
    return ExportGraphSignature(input_specs=input_specs, output_specs=output_specs)

def generate_inputs_for_model(model_cls, model, model_name, bs, device, include_loss_args=False):
    num_choices = 3
    num_visual_features = 42
    seq_length = get_sequence_length(model_cls, model_name)
    vocab_size = model.config.vocab_size
    if model_name.startswith('Wav2Vec2'):
        target_length = 100
        return {'input_values': torch.randn((bs, seq_length), device=device), 'attention_mask': rand_int_tensor(device, 0, 2, (bs, seq_length)), 'labels': rand_int_tensor(device, 0, vocab_size, (bs, target_length))}
    if model_name.endswith('MultipleChoice'):
        input = rand_int_tensor(device, 0, vocab_size, (bs, num_choices, seq_length))
    elif model_name.startswith('Roberta'):
        input = rand_int_tensor(device, 0, 1, (bs, seq_length))
    else:
        input = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
    if 'Bart' in model_name:
        input[:, -1] = model.config.eos_token_id
    input_dict = {'input_ids': input}
    if model_name.startswith(('T5', 'M2M100', 'MT5')) or model_cls in [BlenderbotModel, BlenderbotSmallModel, BlenderbotForConditionalGeneration, PegasusModel, MarianModel, MarianMTModel]:
        input_dict['decoder_input_ids'] = input
    if model_name.startswith('Lxmert'):
        (visual_feat_dim, visual_pos_dim) = (model.config.visual_feat_dim, model.config.visual_pos_dim)
        input_dict['visual_feats'] = torch.randn(bs, num_visual_features, visual_feat_dim)
        input_dict['visual_pos'] = torch.randn(bs, num_visual_features, visual_pos_dim)
    if include_loss_args:
        if model_name.endswith('PreTraining'):
            if <MASK>:
                input_dict['labels'] = rand_int_tensor(device, 0, 1, (bs, seq_length))
            else:
                label_name = 'sentence_order_label' if model_cls in [AlbertForPreTraining] else 'next_sentence_label'
                input_dict['labels'] = (rand_int_tensor(device, 0, vocab_size, (bs, seq_length)),)
                input_dict[label_name] = rand_int_tensor(device, 0, 1, (bs,))
        elif model_name.endswith('QuestionAnswering'):
            input_dict['start_positions'] = rand_int_tensor(device, 0, seq_length, (bs,))
            input_dict['end_positions'] = rand_int_tensor(device, 0, seq_length, (bs,))
        elif model_name.endswith(('MaskedLM', 'HeadModel', 'CausalLM', 'DoubleHeadsModel')):
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
        elif model_name.endswith('TokenClassification'):
            input_dict['labels'] = rand_int_tensor(device, 0, model.config.num_labels - 1, (bs, seq_length))
        elif model_name.endswith('MultipleChoice'):
            input_dict['labels'] = rand_int_tensor(device, 0, num_choices, (bs,))
        elif model_name.endswith('SequenceClassification'):
            input_dict['labels'] = rand_int_tensor(device, 0, model.config.num_labels - 1, (bs,))
        elif model_name.endswith('NextSentencePrediction'):
            input_dict['labels'] = rand_int_tensor(device, 0, 1, (bs,))
        elif model_name.endswith('ForConditionalGeneration'):
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size - 1, (bs, seq_length))
        elif model_name in EXTRA_MODELS:
            input_dict['labels'] = rand_int_tensor(device, 0, vocab_size, (bs, seq_length))
        else:
            raise NotImplementedError(f'Class {model_name} unsupported for training test ')
    return input_dict

def gen_vmap_inplace_plumbing(native_function: NativeFunction) -> str | None:
    schema = native_function.func
    sig = DispatcherSignature.from_schema(schema)
    returns = schema.returns
    assert schema.kind() == SchemaKind.inplace
    if not is_mutated_arg(schema.arguments.flat_all[0]):
        return None
    if len([arg for arg in schema.arguments.flat_all if is_mutated_arg(arg)]) != 1:
        return None
    if len(returns) == 0:
        return None
    if not all((is_tensor(ret.type) or is_tensor_list(ret.type) for ret in returns)):
        return None
    if <MASK>:
        return None
    cur_level_var = 'cur_level'
    (unwraps, unwrapped_arg_list) = gen_unwraps(schema.arguments.flat_all, cur_level_var)
    bdims_all_none_case = gen_case_where_all_bdims_are_none(sig, schema, cur_level_var)
    return f"""template <typename batch_rule_t, batch_rule_t batch_rule>\n{sig.decl(name=schema.name.unambiguous_name() + '_generated_plumbing')} {{\n  c10::impl::ExcludeDispatchKeyGuard guard(DispatchKey::FuncTorchBatched);\n  auto maybe_layer = maybeCurrentDynamicLayer();\n  vmap_check_escaped(maybe_layer, "gen_vmap_inplace_plumbing");\n  int64_t {cur_level_var} = maybe_layer->layerId();\n{textwrap.indent(bdims_all_none_case, '  ')}\n{textwrap.indent(unwraps, '  ')}\n  batch_rule({', '.join(unwrapped_arg_list)});\n  return {schema.arguments.flat_all[0].name};\n}}"""

def _InferGradientReductionAxes(x_shape, y_shape):
    """Infers the sets of axes that might have been broadcasted."""
    x_rank = x_shape.rank
    y_rank = y_shape.rank
    if x_rank is None or y_rank is None:
        return (None, None)
    x_shape = x_shape.as_list()
    y_shape = y_shape.as_list()
    b_rank = max(x_rank, y_rank)
    x_axes = []
    y_axes = []
    for axis in range(b_rank):
        x_dim = 1 if axis < b_rank - x_rank else x_shape[axis - (b_rank - x_rank)]
        y_dim = 1 if axis < b_rank - y_rank else y_shape[axis - (b_rank - y_rank)]
        if x_dim == 1 and y_dim != 1:
            x_axes.append(axis)
        elif <MASK>:
            y_axes.append(axis)
        elif x_dim is None or y_dim is None:
            return (None, None)
    return (x_axes, y_axes)

def _maybe_name(obj) -> str:
    """Returns object name if it has one, or a message otherwise.

  This is useful for names that apper in error messages.
  Args:
    obj: Object to get the name of.
  Returns:
    name, "None", or a "no name" message.
  """
    if <MASK>:
        return 'None'
    elif hasattr(obj, 'name'):
        return obj.name
    else:
        return '<no name for %s>' % type(obj)

def create(self, batch_outs):
    self._structure = nest.get_traverse_shallow_structure(lambda x: not is_composite_or_composite_value(x), batch_outs)
    batch_outs = nest.flatten_up_to(self._structure, batch_outs)
    for batch_element in batch_outs:
        if <MASK>:
            self.results.append(ConcatAggregator(self.batch_size))
        elif isinstance(batch_element, np.ndarray):
            self.results.append(ConcatAggregator(self.batch_size) if self.use_steps else SliceAggregator(self.num_samples, self.batch_size))
        else:
            raise RuntimeError('Attempted to aggregate unsupported object {}.'.format(batch_element))
        self.results[-1].create(batch_element)

def res_slice(self, ns, types_ns, node_or_slice, value, slice_):
    if <MASK>:
        return value
    if isinstance(value, set):
        type_tuple = value.pop()
        if isinstance(type_tuple, tuple):
            value = {type_tuple[node_or_slice]}
        else:
            value = {type_tuple}
    assert len(value) == 1
    (value,) = tuple(value)
    if value == TFRTypes.TF_TENSOR_SHAPE_LIST:
        return {int}
    elif value in (TFRTypes.TENSOR_LIST, TFRTypes.TENSOR):
        return {TFRTypes.TENSOR}
    else:
        return {value}

@no_type_check
@torch.no_grad()
def init_flat_param_attributes(self) -> None:
    """
        This initializes some attributes on the handle's ``FlatParameter``.
        This should be called during lazy initialization since it requires the
        parameter to be on the compute device if not offloading to CPU and we
        want to give users the chance to move the parameter appropriately after
        the FSDP constructor.

        For each tensor attribute on the ``FlatParameter``, see the unshard and
        reshard methods in this class for the allocation and free pattern.
        """
    flat_param = self.flat_param
    if flat_param.dtype != self._orig_param_dtype:
        if not self._low_prec_param_dtype_specified:
            self._fwd_bwd_param_dtype = flat_param.dtype
        if not self._low_prec_reduce_dtype_specified and (not self._low_prec_param_dtype_specified):
            self._reduce_dtype = flat_param.dtype
        self._orig_param_dtype = flat_param.dtype
    cpu_device = torch.device('cpu')
    if self._offload_params:
        _p_assert(flat_param.device == cpu_device, f'Expects the `FlatParameter` to be on CPU when parameter CPU offloading is enabled, not {flat_param.device}')
    else:
        self._check_on_compute_device(self.flat_param)
    flat_param._local_shard = flat_param.data
    if self._offload_params:
        flat_param._local_shard = flat_param._local_shard.pin_memory()
        flat_param._cpu_grad = torch.zeros_like(flat_param._local_shard, device=cpu_device).pin_memory()
    if self._uses_param_mixed_precision:
        flat_param._mp_shard = torch.empty_like(flat_param._local_shard, device=self.device, dtype=self._fwd_bwd_param_dtype)
        _free_storage(flat_param._mp_shard)
    if <MASK>:
        unsharded_param_dtype = self._fwd_bwd_param_dtype if self._uses_param_mixed_precision else flat_param.dtype
        padded_unsharded_numel = flat_param.numel() * self.world_size
        flat_param._full_param_padded = torch.empty(padded_unsharded_numel, device=self.device, dtype=unsharded_param_dtype)
        flat_param._padded_unsharded_size = flat_param._full_param_padded.size()
        _free_storage(flat_param._full_param_padded)
        if self._uses_param_mixed_precision:
            flat_param._full_prec_full_param_padded = torch.empty(padded_unsharded_numel, device=self.device, dtype=flat_param.dtype)
            _free_storage(flat_param._full_prec_full_param_padded)

def check_inputs_type(args, kwargs):
    if not isinstance(args, tuple):
        raise ValueError(f'Expecting args type to be a tuple, got: {type(args)}')
    if not isinstance(kwargs, dict):
        raise ValueError(f'Expecting kwargs type to be a dict, got: {type(kwargs)}')
    for key in kwargs:
        if <MASK>:
            raise ValueError(f'Expecting kwargs keys to be a string, got: {type(key)}')

def can_fuse_horizontal(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode) -> bool:
    for node in (node1, node2):
        if self._cuda_cpp_scheduling.is_cuda_cpp_template(node):
            return self._cuda_cpp_scheduling.can_fuse_horizontal(node1, node2)
        if <MASK>:
            return self._cutedsl_scheduling.can_fuse_horizontal(node1, node2)
    return self._triton_scheduling.can_fuse_horizontal(node1, node2)

def _cmp_method(self, other, op) -> ArrowExtensionArray:
    pc_func = ARROW_CMP_FUNCS[op.__name__]
    ltype = self._pa_array.type
    if isinstance(other, (ExtensionArray, np.ndarray, list)):
        try:
            boxed = self._box_pa(other)
        except pa.lib.ArrowInvalid:
            res_values = [op(x, y) for (x, y) in zip(self, other, strict=True)]
            result = pa.array(res_values, type=pa.bool_(), from_pandas=True)
        else:
            rtype = boxed.type
            if pa.types.is_timestamp(ltype) and pa.types.is_date(rtype) or (pa.types.is_timestamp(rtype) and pa.types.is_date(ltype)):
                result = ops.invalid_comparison(self, other, op)
                result = pa.array(result, type=pa.bool_())
            else:
                try:
                    result = pc_func(self._pa_array, boxed)
                except pa.ArrowNotImplementedError:
                    result = ops.invalid_comparison(self, other, op)
                    result = pa.array(result, type=pa.bool_())
    elif <MASK>:
        if isinstance(other, datetime) and pa.types.is_date(ltype) or (type(other) is date and pa.types.is_timestamp(ltype)):
            result = ops.invalid_comparison(self, other, op)
            result = pa.array(result, type=pa.bool_())
        else:
            try:
                result = pc_func(self._pa_array, self._box_pa(other))
            except (pa.lib.ArrowNotImplementedError, pa.lib.ArrowInvalid):
                mask = isna(self) | isna(other)
                valid = ~mask
                result = np.zeros(len(self), dtype='bool')
                np_array = np.array(self)
                try:
                    result[valid] = op(np_array[valid], other)
                except TypeError:
                    result = ops.invalid_comparison(self, other, op)
                result = pa.array(result, type=pa.bool_())
                result = pc.if_else(valid, result, None)
    else:
        raise NotImplementedError(f'{op.__name__} not implemented for {type(other)}')
    return ArrowExtensionArray(result)

def _determine_input_dtype(param: _schemas.Parameter, arg: AllowedArgType, type_binding: Mapping[_schemas.TypeConstraintParam, ir.TypeProtocol]) -> ir.DataType:
    """Determine the dtype of the input that is a mix of Python constants and ir.Value."""
    if param.type_constraint in type_binding:
        return type_binding[param.type_constraint].dtype
    if len(param.type_constraint.allowed_types) == 1:
        return next(iter(param.type_constraint.allowed_types)).dtype
    if isinstance(arg, bool):
        return ir.DataType.BOOL
    if isinstance(arg, float):
        return ir.DataType.FLOAT
    if isinstance(arg, int):
        return ir.DataType.INT64
    if isinstance(arg, str):
        return ir.DataType.STRING
    if isinstance(arg, (ir.Tensor, ir.TensorProtocol)):
        return arg.dtype
    if isinstance(arg, complex):
        return ir.DataType.FLOAT
    if arg is None:
        return ir.DataType.UNDEFINED
    if isinstance(arg, (tuple, list)):
        if len(arg) == 0:
            return ir.DataType.INT64
        for val in arg:
            if isinstance(val, ir.Value) and val.dtype is not None:
                return val.dtype
        if <MASK>:
            return ir.DataType.FLOAT
        elif any((isinstance(val, int) for val in arg)):
            return ir.DataType.INT64
    raise ValueError(f"Could not determine the dtype for the input '{param.name}'. param={param}, arg={arg}, param_type_constraint={param.type_constraint}, type_binding={type_binding}")

def _post_init(self):
    if self._init_rrefs:
        with _sharded_tensor_lock:
            global _sharded_tensor_current_id, _sharded_tensor_map
            self._sharded_tensor_id = _sharded_tensor_current_id
            _sharded_tensor_map[self._sharded_tensor_id] = weakref.ref(self)
            _sharded_tensor_current_id += 1
        if <MASK>:
            raise RuntimeError('RPC Framework needs to be initialized using torch.distributed.rpc.init_rpc if init_rrefs is set to True')
        self._init_rpc()

def get_to_dtype_expr(self, src, dtype, src_dtype):
    assert isinstance(src, CppCSEVariable)
    if not src.is_vec:
        return super().get_to_dtype_expr(src, dtype, src_dtype)
    src_cpp_type = DTYPE_TO_CPP[src_dtype]
    src_num_vectors = self._get_num_vectors(src_dtype)
    dst_cpp_type = DTYPE_TO_CPP[dtype]
    dst_num_vectors = self._get_num_vectors(dtype)
    expr = f'({src})'
    if src_dtype != torch.bool and dtype == torch.bool:
        expr = f'{self._get_mask_type(src_dtype)}::from<{src_cpp_type},{src_num_vectors}>({src})'
    elif src_dtype == torch.bool and dtype != torch.bool:
        expr = f'{src}.to<{dst_cpp_type},{dst_num_vectors}>()'
    elif src_dtype != dtype:
        if <MASK>:
            expr = f'at::vec::convert<{dst_cpp_type}>({src})'
        else:
            expr = f'at::vec::convert<{dst_cpp_type},{dst_num_vectors},{src_cpp_type},{src_num_vectors}>({src})'
    return expr

def var_mean_welford_(x, axis, *, correction, keepdim, return_mean):
    if correction is None:
        correction = 1
    kwargs = _make_reduction_inner(x, axis=axis, keepdims=keepdim, dtype=None, override_return_dtype=None)
    loader = kwargs.pop('inner_fn')
    kwargs.pop('dst_dtype')
    kwargs.pop('src_dtype')
    (mean, m2, _) = ir.WelfordReduction.create(inner_fns=(loader,), reduction_type='welford_reduce', dtype=x.get_dtype(), **kwargs)
    m2.realize()
    dtype = x.get_dtype()
    size = x.get_size()
    axis = _validate_reduction_axis(x, axis)
    rnumel = sympy_product((size[i] for i in axis))

    def get_constant_or_index_expr(x, dtype):
        if <MASK>:
            return ops.to_dtype(ops.index_expr(x, torch.int64), dtype)
        return ops.constant(x, dtype)

    def scale_fn(data):
        c = get_constant_or_index_expr(correction, dtype)
        N = get_constant_or_index_expr(rnumel, dtype)
        zero = ops.constant(0, dtype)
        return data / ops.maximum(zero, N - c)
    var = make_pointwise(scale_fn)(m2)
    if return_mean:
        mean.realize()
        return (var, mean)
    return (var,)

def build_graph(parameters):
    """Build the gather op testing graph."""
    inputs = []
    if <MASK>:
        params = create_tensor_data(parameters['params_dtype'], parameters['params_shape'])
    else:
        params = tf.compat.v1.placeholder(dtype=parameters['params_dtype'], name='params', shape=parameters['params_shape'])
        inputs.append(params)
    if parameters.get('constant_indices', False):
        indices = create_tensor_data(parameters['indices_dtype'], parameters['indices_shape'], min_value=0, max_value=parameters['params_shape'][0] - 1)
    else:
        indices = tf.compat.v1.placeholder(dtype=parameters['indices_dtype'], name='indices', shape=parameters['indices_shape'])
        inputs.append(indices)
    axis = min(len(parameters['params_shape']), parameters['axis'])
    out = tf.gather(params, indices, axis=axis, batch_dims=parameters['batch_dims'])
    return (inputs, [out])

def __iter__(self) -> _BaseDataLoaderIter:
    if <MASK>:
        if self._iterator is None:
            self._iterator = self._get_iterator()
        else:
            self._iterator._reset(self)
        return self._iterator
    else:
        return self._get_iterator()

def _get_level_indexer(self, key, level: int=0, indexer: npt.NDArray[np.bool_] | None=None):
    level_index = self.levels[level]
    level_codes = self.codes[level]

    def convert_indexer(start, stop, step, indexer=indexer, codes=level_codes):
        if indexer is not None:
            codes = codes[indexer]
        if step is None or step == 1:
            new_indexer = (codes >= start) & (codes < stop)
        else:
            r = np.arange(start, stop, step, dtype=codes.dtype)
            new_indexer = algos.isin(codes, r)
        if indexer is None:
            return new_indexer
        indexer = indexer.copy()
        indexer[indexer] = new_indexer
        return indexer
    if isinstance(key, slice):
        step = key.step
        is_negative_step = step is not None and step < 0
        try:
            if key.start is not None:
                start = level_index.get_loc(key.start)
            elif <MASK>:
                start = len(level_index) - 1
            else:
                start = 0
            if key.stop is not None:
                stop = level_index.get_loc(key.stop)
            elif is_negative_step:
                stop = 0
            elif isinstance(start, slice):
                stop = len(level_index)
            else:
                stop = len(level_index) - 1
        except KeyError:
            start = stop = level_index.slice_indexer(key.start, key.stop, key.step)
            step = start.step
        if isinstance(start, slice) or isinstance(stop, slice):
            start = getattr(start, 'start', start)
            stop = getattr(stop, 'stop', stop)
            return convert_indexer(start, stop, step)
        elif level > 0 or self._lexsort_depth == 0 or step is not None:
            stop = stop - 1 if is_negative_step else stop + 1
            return convert_indexer(start, stop, step)
        else:
            i = algos.searchsorted(level_codes, start, side='left')
            j = algos.searchsorted(level_codes, stop, side='right')
            return slice(i, j, step)
    else:
        idx = self._get_loc_single_level_index(level_index, key)
        if level > 0 or self._lexsort_depth == 0:
            if isinstance(idx, slice):
                locs = (level_codes >= idx.start) & (level_codes < idx.stop)
                return locs
            locs = np.asarray(level_codes == idx, dtype=bool)
            if not locs.any():
                raise KeyError(key)
            return locs
        if isinstance(idx, slice):
            start = algos.searchsorted(level_codes, idx.start, side='left')
            end = algos.searchsorted(level_codes, idx.stop, side='left')
        else:
            start = algos.searchsorted(level_codes, idx, side='left')
            end = algos.searchsorted(level_codes, idx, side='right')
        if start == end:
            raise KeyError(key)
        return slice(start, end)

def check_dtype(buffer: IndentedBuffer, var: CSEVariableType, dtype: torch.dtype) -> None:
    backend = get_current_backend()
    if <MASK>:
        buffer.writeline(f'tl.static_assert({var}.dtype == {triton_type(dtype)})')
    elif config.test_configs.static_cpp_dtype_assert and backend == 'cpp':
        from .cpp_utils import CppCSEVariable, DTYPE_TO_CPP
        assert isinstance(var, CppCSEVariable), type(var)
        if dtype == torch.bool:
            if var.is_vec:
                is_same_dt = f'IsVecMaskType<decltype({var})>::value'
            else:
                is_same_dt = f'std::is_same_v<decltype({var}), bool> || std::is_same_v<decltype({var}), int>'
        else:
            c_var_type = f'decltype({var})'
            if var.is_vec:
                c_var_type = f'typename {c_var_type}::value_type'
            is_same_dt = f'std::is_same_v<{c_var_type}, {DTYPE_TO_CPP[dtype]}>'
        buffer.writeline(f'static_assert({is_same_dt});')

def _format_header_regular(self) -> Iterable[ExcelCell]:
    if <MASK>:
        coloffset = 0
        if self.index:
            coloffset = 1
            if isinstance(self.df.index, MultiIndex):
                coloffset = len(self.df.index.names)
        colnames = self.columns
        if self._has_aliases:
            self.header = cast(Sequence, self.header)
            if len(self.header) != len(self.columns):
                raise ValueError(f'Writing {len(self.columns)} cols but got {len(self.header)} aliases')
            colnames = self.header
        for (colindex, colname) in enumerate(colnames):
            yield CssExcelCell(row=self.rowcounter, col=colindex + coloffset, val=colname, style=None, css_styles=getattr(self.styler, 'ctx_columns', None), css_row=0, css_col=colindex, css_converter=self.style_converter)

def adapt_timefield_value(self, value):
    """
        Transform a time value to an object compatible with what is expected
        by the backend driver for time columns.
        """
    if <MASK>:
        return None
    if timezone.is_aware(value):
        raise ValueError('Django does not support timezone-aware times.')
    return str(value)

@ops.RegisterGradient('SparseMatrixMatMul')
def _SparseMatrixMatMulGrad(op: ops.Operation, grad):
    """Gradient for sparse_matrix_mat_mul op."""
    t_a = op.get_attr('transpose_a')
    t_b = op.get_attr('transpose_b')
    adj_a = op.get_attr('adjoint_a')
    adj_b = op.get_attr('adjoint_b')
    transpose_output = op.get_attr('transpose_output')
    conjugate_output = op.get_attr('conjugate_output')
    a = op.inputs[0]
    b = op.inputs[1]
    conj = math_ops.conj
    sparse_matmul = sparse_csr_matrix_ops.sparse_matrix_mat_mul

    def matmul(x, y, **kwargs):
        return _PrunedDenseMatrixMultiplication(x, y, indices=sparse_csr_matrix_ops.csr_sparse_matrix_to_sparse_tensor(a, type=x.dtype).indices, **kwargs)
    if conjugate_output:
        grad = conj(grad)
    if not transpose_output:
        if not adj_a and (not adj_b):
            a = conj(a)
            b = conj(b)
            if not t_a:
                grad_a = matmul(grad, b, transpose_b=not t_b)
            else:
                grad_a = matmul(b, grad, transpose_a=t_b, transpose_b=True)
            grad_b = sparse_matmul(a, grad, transpose_a=not t_a, transpose_output=t_b)
        elif <MASK>:
            if not adj_a:
                grad_a = matmul(grad, b, adjoint_b=not adj_b)
            else:
                grad_a = matmul(b, grad, adjoint_a=adj_b, adjoint_b=True)
            grad_b = sparse_matmul(a, grad, adjoint_a=not adj_a, transpose_output=adj_b, conjugate_output=adj_b)
        elif adj_a and t_b:
            grad_a = matmul(b, grad, transpose_a=True, adjoint_b=True)
            grad_b = sparse_matmul(a, grad, transpose_output=True)
        elif t_a and adj_b:
            grad_a = matmul(b, grad, transpose_a=True, transpose_b=True)
            grad_b = sparse_matmul(conj(a), grad, transpose_output=True, conjugate_output=True)
    elif not adj_a and (not adj_b):
        a = conj(a)
        b = conj(b)
        if not t_a:
            grad_a = matmul(grad, b, transpose_a=True, transpose_b=not t_b)
        else:
            grad_a = matmul(b, grad, transpose_a=t_b)
        grad_b = sparse_matmul(a, grad, transpose_a=not t_a, transpose_b=True, transpose_output=t_b)
    elif not t_a and (not t_b):
        if not adj_a:
            grad_a = matmul(grad, b, transpose_a=True, adjoint_b=not adj_b)
        else:
            grad_a = matmul(b, conj(grad), adjoint_a=adj_b)
        grad_b = sparse_matmul(a, grad, adjoint_a=not adj_a, transpose_b=True, transpose_output=adj_b, conjugate_output=adj_b)
    elif adj_a and t_b:
        grad_a = matmul(b, conj(grad), transpose_a=True)
        grad_b = sparse_matmul(a, grad, transpose_b=True, transpose_output=True)
    elif t_a and adj_b:
        grad_a = matmul(b, grad, transpose_a=True)
        grad_b = sparse_matmul(a, grad, adjoint_b=True, transpose_output=True)
    return (grad_a, grad_b)

def make_function_context(scope_type=None) -> function_cache.FunctionContext:
    """Generates a FunctionContext based on current contextual info."""
    ctx = context.context()
    executing_eagerly = ctx.executing_eagerly()
    parent_graph = None
    xla_context_id = 0
    if not executing_eagerly:
        xla_context = _enclosing_xla_context()
        if xla_context is not None and xla_context.RequiresUniqueFunctionRetracing():
            xla_context_id = id(xla_context)
        with ops.init_scope():
            executing_eagerly = ctx.executing_eagerly()
            parent_graph = None if executing_eagerly else ops.get_default_graph()
    default_graph = ops.get_default_graph()
    strategy_stack = default_graph._distribution_strategy_stack
    uses_distribution_strategy = strategy_stack and strategy_stack[-1].strategy.extended._retrace_functions_for_each_device
    if executing_eagerly:
        colocation_stack = ()
        if uses_distribution_strategy:
            device_functions = (pydev.merge_device(ctx.device_name),)
        else:
            device_functions = ()
    else:
        colocation_stack = tuple(default_graph._colocation_stack.peek_objs())
        if uses_distribution_strategy or func_graph_module.device_stack_has_callable(default_graph._device_function_stack):
            device_functions = tuple(default_graph._device_functions_outer_to_inner)
        else:
            device_functions = ()
    in_cross_replica_context = False
    try:
        in_cross_replica_context = strategy_stack[-1].replica_context is None
    except (AttributeError, IndexError):
        pass
    if <MASK>:
        variable_policy = save_context.get_save_options().experimental_variable_policy
    else:
        variable_policy = None
    return function_cache.FunctionContext(EagerContext(parent_graph, device_functions, colocation_stack, in_cross_replica_context, variable_policy, xla_context_id), scope_type)

def _get_dense_tensor_internal(self, transformation_cache, state_manager):
    """Private method that follows _get_dense_tensor_internal."""
    _check_invalid_cases(self._embedding_lookup_device)
    is_cpu = self._embedding_lookup_device == EmbeddingDevice.CPU
    is_cpu = is_cpu or _is_running_on_cpu()
    if <MASK>:
        return super(_TPUSharedDeviceSpecificEmbeddingColumnV2, self)._get_dense_tensor_internal(transformation_cache, state_manager)
    if self._embedding_lookup_device == EmbeddingDevice.TPU_EMBEDDING_CORE:
        return super(_TPUSharedDeviceSpecificEmbeddingColumnV2, self)._get_dense_tensor_internal(transformation_cache, state_manager)
    if tpu.under_tpu_inference_context():
        sparse_tensor = transformation_cache.get(self.categorical_column.name, state_manager)

        def host_computation():
            return pad_sparse_embedding_lookup_indices(sparse_tensor, self._tensor_core_shape[1])
        (values, mask) = tpu_replication.outside_compilation(host_computation)
    else:
        values = transformation_cache.get(self.categorical_column.name, state_manager)
        mask = transformation_cache.get(self.categorical_column.name + _TENSOR_CORE_MASK_KEY_SUFFIX, state_manager)
    embedding_weights = self.shared_embedding_column_creator.embedding_weights
    return sparse_embedding_aggregate_slice(embedding_weights, (values, mask), self.get_combiner())

def _simplify_loops_impl(self, index_vars: list[sympy.Symbol], sizes, index_formulas):
    """
        Try to remove as many axis from loop iterations as possible, by:
            1) removing size==1 dimensions
            2) fuse contiguous dimensions into a single loop
            If channel_last = True, we will prevent the last dim fused with other dims
        """
    sizes = list(map(self.simplify, sizes))
    strides = [self.stride_vars(x, index_vars) if isinstance(x, sympy.Expr) else [0] * len(index_vars) for x in index_formulas]
    assert len(sizes) == len(strides[0]), (len(sizes), len(strides[0]))
    for i in range(len(sizes)):
        if sizes[i] == 1:
            sizes[i] = None

    def can_merge_dims(a, b):
        for k in range(len(strides)):
            if self.simplify(strides[k][a] * sizes[a]) == self.simplify(strides[k][b]):
                va = index_vars[a]
                vb = index_vars[b]
                m1 = sympy_index_symbol('_merge_tester1')
                m2 = sympy_index_symbol('_merge_tester2')
                expr1 = sympy_subs(index_formulas[k], {va: m1 * sizes[a], vb: m2})
                expr2 = sympy_subs(index_formulas[k], {va: 0, vb: m1 + m2})
                if self.simplify(expr1) == self.simplify(expr2):
                    continue
            return False
        return True
    changed = True
    while changed:
        changed = False
        for (i, j) in itertools.product(reversed(range(len(sizes))), reversed(range(len(sizes)))):
            if i == j or sizes[i] is None or sizes[j] is None:
                continue
            if <MASK>:
                changed = True
                sizes[i] = sizes[i] * sizes[j]
                sizes[j] = None

    def reindex(index):
        it = list(reversed(index))
        new_index = []
        for size in sizes:
            if size is None:
                new_index.append(sympy.S.Zero)
            else:
                new_index.append(it.pop())
        assert not it
        return new_index

    def prune(index):
        assert len(index) == len(sizes)
        return [i for (i, s) in zip(index, sizes) if s is not None]
    return ([x for x in sizes if x is not None], reindex, prune)

def _reorder_submodules(parent: torch.nn.Module, fqn_order: dict[str, int], prefix: str=''):
    if prefix == '':
        for fqn in list(fqn_order.keys())[1:]:
            if <MASK>:
                _add_submodule(parent, fqn, torch.nn.Module())
    children = []
    for (name, child) in list(parent._modules.items()):
        if child is None:
            continue
        fqn = prefix + name
        _reorder_submodules(child, fqn_order, prefix=fqn.split('@')[0] + '.')
        delattr(parent, name)
        children.append((fqn_order[fqn], name, child))
    children.sort(key=operator.itemgetter(0))
    for (_, name, child) in children:
        parent.register_module(name, child)

def pad_batch(self, *dataset_batch_elements):
    """Pads out the batch dimension of a tensor to the complete batch size."""

    def _pad(batch):
        """Helper function to pad nested data within each batch elements."""
        padded_dict_batch = {}
        if <MASK>:
            for (key, value) in batch.items():
                padded_dict_batch[key] = _pad(value)
            return padded_dict_batch
        rank = len(batch.shape)
        assert rank > 0
        missing_count = self.padded_batch_size - self.get_real_batch_size(batch)
        padding = backend.stack([[0, missing_count]] + [[0, 0]] * (rank - 1))
        return array_ops.pad(batch, padding, 'constant')
    if len(dataset_batch_elements) == 1:
        return _pad(dataset_batch_elements[0])
    batch_elements = []
    for batch_element in dataset_batch_elements:
        batch_elements.append(_pad(batch_element))
    return tuple(batch_elements)

def _check_input_sizes(n, computation_op):
    computation_node = n.args[0] if n.args[1] is match.kwargs['other'] else n.args[1]
    assert computation_node.target == computation_op
    computation_node_size = get_meta_value(computation_node).size()
    if <MASK>:
        broadcast_sizes = []
        if len(computation_node_size) >= 2:
            broadcast_sizes = [torch.Size([1 for _ in range(len(computation_node_size) - 1)] + [computation_node_size[-1]])]
    else:
        assert len(computation_node_size) > 2
        broadcast_sizes = [torch.Size([computation_node_size[0], computation_node_size[1]] + [1 for _ in range(len(computation_node_size) - 2)]), torch.Size([1, computation_node_size[1]] + [1 for _ in range(len(computation_node_size) - 2)]), torch.Size([1 for _ in range(len(computation_node_size))])]
    return get_meta_value(match.kwargs['other']).size() in [computation_node_size] + broadcast_sizes

@staticmethod
def _merge_atom(x: _T, y: _T) -> Union[AutoDynamic, _T]:
    if <MASK>:
        return y
    if y is auto_unset:
        return x
    if x is auto_dynamic or y is auto_dynamic or x != y:
        return auto_dynamic
    return x

def lookup(self, keys, name=None):
    """Looks up `keys` in the table, outputs the corresponding values.

    It assigns out-of-vocabulary keys to buckets based in their hashes.

    Args:
      keys: Keys to look up. May be either a `SparseTensor` or dense `Tensor`.
      name: Optional name for the op.

    Returns:
      A `SparseTensor` if keys are sparse, a `RaggedTensor` if keys are ragged,
      otherwise a dense `Tensor`.

    Raises:
      TypeError: when `keys` doesn't match the table key data type.
    """
    if keys.dtype.base_dtype != self._key_dtype:
        raise TypeError(f'Dtype of argument `keys` must be {self._key_dtype}, received: {keys.dtype}')
    values = keys
    if isinstance(keys, (sparse_tensor.SparseTensor, internal.RaggedTensor)):
        values = keys.values
    if <MASK>:
        values = math_ops.cast(values, dtypes.int64)
    if self._num_oov_buckets == 0:
        ids = self._table.lookup(values, name=name)
    else:
        with ops.name_scope(name, '%s_Lookup' % self.name):
            str_to_hash_bucket = self._get_string_to_hash_bucket_fn(self._hasher_spec)
            buckets = str_to_hash_bucket(_as_string(values), num_buckets=self._num_oov_buckets, name='hash_bucket')
            if self._table:
                ids = self._table.lookup(values)
                buckets = math_ops.add(buckets, self._table.size())
                is_id_non_default = math_ops.not_equal(ids, self._table.default_value)
                ids = array_ops.where_v2(is_id_non_default, ids, buckets)
            else:
                ids = buckets
    if isinstance(keys, sparse_tensor.SparseTensor):
        return sparse_tensor.SparseTensor(keys.indices, ids, keys.dense_shape)
    elif isinstance(keys, internal.RaggedTensor):
        return keys.with_values(ids)
    return ids

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    (inner_fn, source) = self._resolved_getattr_and_source(self, name)
    if inner_fn is object.__init__:
        return LambdaVariable(identity)
    elif inner_fn is torch.nn.Module.__init__:
        objvar = self.objvar
        from ..side_effects import AttributeMutationNew
        if isinstance(objvar, variables.UserDefinedObjectVariable) and isinstance(objvar.mutation_type, AttributeMutationNew) and (not (args or kwargs)):
            with do_not_convert_to_tracable_parameter():
                return variables.UserFunctionVariable(unpatched_nn_module_init, source=source).call_function(tx, [self.objvar] + args, kwargs)
        else:
            unimplemented_v2(gb_type='Unsupported super().__init__() call', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'Dynamo encountered a super().__init__() call on {objvar} that resolved to a `torch.nn.Module.__init__()` call that we cannot trace.', hints=[*graph_break_hints.DIFFICULT])
    elif self.objvar.source and hasattr(inner_fn, '__name__') and (inner_fn.__name__ == '__new__') and variables.UserDefinedClassVariable.is_supported_new_method(inner_fn):
        user_cls = inner_fn.__self__
        if hasattr(user_cls, '__module__') and user_cls.__module__ == 'builtins':
            user_cls_vt = variables.BuiltinVariable(user_cls)
        else:
            user_cls_source = source.member
            user_cls_vt = variables.UserDefinedClassVariable(user_cls, source=user_cls_source)
        return user_cls_vt.call_method(tx, '__new__', args, kwargs)
    elif isinstance(inner_fn, staticmethod) and isinstance(inner_fn.__func__, types.FunctionType):
        return variables.UserFunctionVariable(inner_fn.__func__, source=source).call_function(tx, args, kwargs)
    elif isinstance(inner_fn, classmethod) and isinstance(inner_fn.__func__, types.FunctionType):
        if isinstance(self.objvar, variables.UserDefinedClassVariable):
            cls_variable = self.objvar
        else:
            cls_source = None
            if self.objvar.source:
                cls_source = TypeSource(self.objvar.source)
            cls_variable = VariableTracker.build(tx, self.objvar.value_type, cls_source)
        return variables.UserFunctionVariable(inner_fn.__func__, source=AttrSource(source, '__func__')).call_function(tx, [cls_variable, *args], kwargs)
    elif isinstance(inner_fn, types.FunctionType):
        return variables.UserFunctionVariable(inner_fn, source=source).call_function(tx, [self.objvar] + args, kwargs)
    elif isinstance(inner_fn, types.MethodType):
        return variables.UserMethodVariable(inner_fn.__func__, self.objvar, source=source).call_function(tx, args, kwargs)
    elif is_standard_setattr(inner_fn) and isinstance(self.objvar, UserDefinedObjectVariable):
        return self.objvar.method_setattr_standard(tx, *args, **kwargs)
    elif inner_fn is object.__delattr__:
        attr = args[0]
        try:
            attr = attr.as_python_constant()
        except NotImplementedError as exc:
            unimplemented_v2(gb_type='Non-constant attribute given to `super().__delattr__()`', context=f'call_method {self} {name}', explanation='Dynamo requires the attribute name passed to `super().__delattr__(...)` to be a constant (string).', hints=['Ensure the attribute name is a string literal or a constant variable.'], from_exc=exc)
        if not tx.output.side_effects.is_attribute_mutation(self.objvar):
            unimplemented_v2(gb_type='Attempted super().__delattr__() on an object without mutation tracking', context=f'call_method {self} {name}', explanation=f"Dynamo needs to track mutations on an object before `super().__delattr__` can be used on it. But the object ({self.objvar}) doesn't have attribute mutation tracking enabled.", hints=["Ensure the object is tracked by Dynamo's side effect system.", *graph_break_hints.DYNAMO_BUG])
        tx.output.side_effects.store_attr(self.objvar, attr, variables.DeletedVariable())
        return variables.ConstantVariable(None)
    elif isinstance(self.objvar, variables.UserDefinedDictVariable) and inner_fn in self.objvar._dict_methods:
        return self.objvar._dict_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedSetVariable) and inner_fn in self.objvar._set_methods:
        return self.objvar._set_vt.call_method(tx, name, args, kwargs)
    elif <MASK>:
        return self.objvar._tuple_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedListVariable) and inner_fn in list_methods:
        return self.objvar._list_vt.call_method(tx, name, args, kwargs)
    elif inner_fn is object.__getattribute__:
        attr_name = args[0].value
        if tx.output.side_effects.has_pending_mutation_of_attr(self.objvar, attr_name):
            result = tx.output.side_effects.load_attr(self.objvar, attr_name, deleted_ok=True)
            if isinstance(result, variables.DeletedVariable):
                raise_observed_exception(AttributeError, tx)
            return result
        try:
            attr_value = object.__getattribute__(self.objvar.value, attr_name)
        except AttributeError:
            raise_observed_exception(AttributeError, tx)
        attr_source = None
        if self.objvar.source is not None:
            attr_source = GenericAttrSource(self.objvar.source, attr_name)
        return VariableTracker.build(tx, attr_value, attr_source)
    elif inner_fn is torch._C._disabled_torch_function_impl:
        func = args[0]
        tf_kwargs = {}
        tf_args = args[2].items
        for (hash_key_vt, value_vt) in args[3].items.items():
            key_str = hash_key_vt.vt.as_python_constant()
            tf_kwargs[key_str] = value_vt
        tx_old = tx.symbolic_torch_function_state.torch_function_subclass_enabled
        tx.symbolic_torch_function_state.torch_function_subclass_enabled = False
        try:
            return func.call_function(tx, tf_args, tf_kwargs)
        finally:
            tx.symbolic_torch_function_state.torch_function_subclass_enabled = tx_old
    elif isinstance(inner_fn, types.MethodDescriptorType) and inner_fn in trace_rules.get_tensor_method():
        fn_var = VariableTracker.build(tx, inner_fn, source)
        return fn_var.call_function(tx, [self.objvar] + args, kwargs)
    unimplemented_v2(gb_type='Attempted to call a super() attribute that is not a function or method', context=f'call_method {self} {name}', explanation=f'Dynamo does not know how to trace the call `super().{name}()` because `super().{name}` is not a function or method attribute.', hints=['Ensure the attribute accessed via `super()` is a standard method or function.'])

def _determine_input_dtype(param: _schemas.Parameter, arg: AllowedArgType, type_binding: Mapping[_schemas.TypeConstraintParam, ir.TypeProtocol]) -> ir.DataType:
    """Determine the dtype of the input that is a mix of Python constants and ir.Value."""
    if param.type_constraint in type_binding:
        return type_binding[param.type_constraint].dtype
    if len(param.type_constraint.allowed_types) == 1:
        return next(iter(param.type_constraint.allowed_types)).dtype
    if isinstance(arg, bool):
        return ir.DataType.BOOL
    if isinstance(arg, float):
        return ir.DataType.FLOAT
    if <MASK>:
        return ir.DataType.INT64
    if isinstance(arg, str):
        return ir.DataType.STRING
    if isinstance(arg, (ir.Tensor, ir.TensorProtocol)):
        return arg.dtype
    if isinstance(arg, complex):
        return ir.DataType.FLOAT
    if arg is None:
        return ir.DataType.UNDEFINED
    if isinstance(arg, (tuple, list)):
        if len(arg) == 0:
            return ir.DataType.INT64
        for val in arg:
            if isinstance(val, ir.Value) and val.dtype is not None:
                return val.dtype
        if any((isinstance(val, float) for val in arg)):
            return ir.DataType.FLOAT
        elif any((isinstance(val, int) for val in arg)):
            return ir.DataType.INT64
    raise ValueError(f"Could not determine the dtype for the input '{param.name}'. param={param}, arg={arg}, param_type_constraint={param.type_constraint}, type_binding={type_binding}")

def sample_inputs_interpolate(mode, self, device, dtype, requires_grad, **kwargs):
    (N, C) = (2, 3)
    D = 4
    S = 3
    L = 5
    align_corners_options: tuple[Any, ...] = (None,)
    if mode in ('linear', 'bilinear', 'bicubic', 'trilinear'):
        align_corners_options = (True, False, None)
    ranks_for_mode = {'nearest': [1, 2, 3], 'nearest-exact': [1, 2, 3], 'linear': [1], 'bilinear': [2], 'bicubic': [2], 'trilinear': [3], 'area': [1, 2, 3]}

    def shape(size, rank, with_batch_channel=True):
        if with_batch_channel:
            return tuple([N, C] + [size] * rank)
        return tuple([size] * rank)

    def uneven_shape(size, rank, with_batch_channel=True):
        rc = list(shape(size, rank, with_batch_channel))
        rc[-1] += 1
        if rank > 2:
            rc[-2] -= 1
        return tuple(rc)
    if <MASK>:
        make_arg = partial(make_tensor, device=device, dtype=dtype, requires_grad=requires_grad, high=256 if dtype == torch.uint8 else None)
        rank = 2
        for memory_format in [torch.contiguous_format, torch.channels_last]:
            yield SampleInput(make_arg(shape(270, rank), memory_format=memory_format), shape(130, rank, False), scale_factor=None, mode=mode, align_corners=False)
    make_arg = partial(make_tensor, device=device, dtype=dtype, requires_grad=requires_grad)
    for align_corners in align_corners_options:
        for rank in ranks_for_mode[mode]:
            yield SampleInput(make_arg(shape(D, rank)), shape(S, rank, False), scale_factor=None, mode=mode, align_corners=align_corners)
            yield SampleInput(make_arg(shape(D, rank)), shape(L, rank, False), scale_factor=None, mode=mode, align_corners=align_corners)
            if rank > 1 and dtype.is_floating_point:
                yield SampleInput(make_arg(uneven_shape(D, rank)), uneven_shape(S, rank, False), scale_factor=None, mode=mode, align_corners=align_corners)
                yield SampleInput(make_arg(uneven_shape(D, rank)), uneven_shape(L, rank, False), scale_factor=None, mode=mode, align_corners=align_corners)
            for recompute_scale_factor in [False, True]:
                for scale_factor in [1.7, 0.6]:
                    yield SampleInput(make_arg(shape(D, rank)), size=None, scale_factor=scale_factor, mode=mode, align_corners=align_corners, recompute_scale_factor=recompute_scale_factor)

def _check_save_as(self, obj):
    """Check save_as is a boolean."""
    if <MASK>:
        return must_be('a boolean', option='save_as', obj=obj, id='admin.E101')
    else:
        return []

def sortvarnames(vars):
    indep = []
    dep = []
    for v in list(vars.keys()):
        if 'depend' in vars[v] and vars[v]['depend']:
            dep.append(v)
        else:
            indep.append(v)
    n = len(dep)
    i = 0
    while dep:
        v = dep[0]
        fl = 0
        for w in dep[1:]:
            if <MASK>:
                fl = 1
                break
        if fl:
            dep = dep[1:] + [v]
            i = i + 1
            if i > n:
                errmess('sortvarnames: failed to compute dependencies because of cyclic dependencies between ' + ', '.join(dep) + '\n')
                indep = indep + dep
                break
        else:
            indep.append(v)
            dep = dep[1:]
            n = len(dep)
            i = 0
    return indep

def _match_attributes(self, pn: Node, gn: Node) -> bool:
    assert isinstance(pn.target, str), f'pn.target {pn.target} must be a string.'
    assert isinstance(gn.target, str), f'gn.target {gn.target} must be a string.'
    pn_value = torch.fx.graph_module._get_attr(pn.graph.owning_module, pn.target)
    gn_value = torch.fx.graph_module._get_attr(gn.graph.owning_module, gn.target)
    if type(pn_value) is not type(gn_value):
        return False
    if <MASK>:
        return isinstance(gn_value, torch.Tensor)
    else:
        raise RuntimeError(f'Unsupported type {pn_value} when matching attributes')
    return False

def add_item_elements(self, handler, item):
    handler.addQuickElement('title', item['title'])
    handler.addQuickElement('link', item['link'])
    if <MASK>:
        handler.addQuickElement('description', item['description'])
    if item['author_name'] and item['author_email']:
        handler.addQuickElement('author', '%s (%s)' % (item['author_email'], item['author_name']))
    elif item['author_email']:
        handler.addQuickElement('author', item['author_email'])
    elif item['author_name']:
        handler.addQuickElement('dc:creator', item['author_name'], {'xmlns:dc': 'http://purl.org/dc/elements/1.1/'})
    if item['pubdate'] is not None:
        handler.addQuickElement('pubDate', rfc2822_date(item['pubdate']))
    if item['comments'] is not None:
        handler.addQuickElement('comments', item['comments'])
    if item['unique_id'] is not None:
        guid_attrs = {}
        if isinstance(item.get('unique_id_is_permalink'), bool):
            guid_attrs['isPermaLink'] = str(item['unique_id_is_permalink']).lower()
        handler.addQuickElement('guid', item['unique_id'], guid_attrs)
    if item['ttl'] is not None:
        handler.addQuickElement('ttl', item['ttl'])
    if item['enclosures']:
        enclosures = list(item['enclosures'])
        if len(enclosures) > 1:
            raise ValueError('RSS feed items may only have one enclosure, see http://www.rssboard.org/rss-profile#element-channel-item-enclosure')
        enclosure = enclosures[0]
        handler.addQuickElement('enclosure', '', {'url': enclosure.url, 'length': enclosure.length, 'type': enclosure.mime_type})
    for cat in item['categories']:
        handler.addQuickElement('category', cat)

def _InferGradientReductionAxes(x_shape, y_shape):
    """Infers the sets of axes that might have been broadcasted."""
    x_rank = x_shape.rank
    y_rank = y_shape.rank
    if <MASK>:
        return (None, None)
    x_shape = x_shape.as_list()
    y_shape = y_shape.as_list()
    b_rank = max(x_rank, y_rank)
    x_axes = []
    y_axes = []
    for axis in range(b_rank):
        x_dim = 1 if axis < b_rank - x_rank else x_shape[axis - (b_rank - x_rank)]
        y_dim = 1 if axis < b_rank - y_rank else y_shape[axis - (b_rank - y_rank)]
        if x_dim == 1 and y_dim != 1:
            x_axes.append(axis)
        elif y_dim == 1 and x_dim != 1:
            y_axes.append(axis)
        elif x_dim is None or y_dim is None:
            return (None, None)
    return (x_axes, y_axes)

def __init__(self, data=None, index=None, dtype: Dtype | None=None, name=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if isinstance(data, SingleBlockManager) and index is None and (dtype is None) and (copy is False or copy is None):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        NDFrame.__init__(self, data)
        self.name = name
        return
    if isinstance(data, (ExtensionArray, np.ndarray)):
        if copy is not False:
            if dtype is None or astype_is_view(data.dtype, pandas_dtype(dtype)):
                data = data.copy()
    if copy is None:
        copy = False
    if isinstance(data, SingleBlockManager) and (not copy):
        data = data.copy(deep=False)
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
    name = ibase.maybe_extract_name(name, data, type(self))
    if index is not None:
        index = ensure_index(index)
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if data is None:
        index = index if index is not None else default_index(0)
        if len(index) or dtype is not None:
            data = na_value_for_dtype(pandas_dtype(dtype), compat=False)
        else:
            data = []
    if isinstance(data, MultiIndex):
        raise NotImplementedError('initializing a Series from a MultiIndex is not supported')
    refs = None
    if isinstance(data, Index):
        if dtype is not None:
            data = data.astype(dtype)
        refs = data._references
        copy = False
    elif isinstance(data, np.ndarray):
        if len(data.dtype):
            raise ValueError('Cannot construct a Series from an ndarray with compound dtype.  Use DataFrame instead.')
    elif isinstance(data, Series):
        if index is None:
            index = data.index
            data = data._mgr.copy(deep=False)
        else:
            data = data.reindex(index)
            copy = False
            data = data._mgr
    elif isinstance(data, Mapping):
        (data, index) = self._init_dict(data, index, dtype)
        dtype = None
        copy = False
    elif <MASK>:
        if index is None:
            index = data.index
        elif not data.index.equals(index) or copy:
            raise AssertionError('Cannot pass both SingleBlockManager `data` argument and a different `index` argument. `copy` must be False.')
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
            allow_mgr = True
    elif isinstance(data, ExtensionArray):
        pass
    else:
        data = com.maybe_iterable_to_list(data)
        if is_list_like(data) and (not len(data)) and (dtype is None):
            dtype = np.dtype(object)
    if index is None:
        if not is_list_like(data):
            data = [data]
        index = default_index(len(data))
    elif is_list_like(data):
        com.require_length_match(data, index)
    if isinstance(data, SingleBlockManager):
        if dtype is not None:
            data = data.astype(dtype=dtype)
        elif copy:
            data = data.copy()
    else:
        data = sanitize_array(data, index, dtype, copy)
        data = SingleBlockManager.from_array(data, index, refs=refs)
    NDFrame.__init__(self, data)
    self.name = name
    self._set_axis(0, index)

def _padded_batch(input_dataset, batch_size, padded_shapes=None, padding_values=None, drop_remainder=False, name=None):
    """See `tf.data.Dataset.padded_batch` for details."""
    if padded_shapes is None:
        padded_shapes = dataset_ops.get_legacy_output_shapes(input_dataset)
        for (i, shape) in enumerate(nest.flatten(padded_shapes)):
            if <MASK>:
                raise ValueError(f'You must provide `padded_shapes` argument because component {i} has unknown rank.')
    return _PaddedBatchDataset(input_dataset, batch_size, padded_shapes, padding_values, drop_remainder, name=name)

def _build_model_with_inputs(self, inputs, targets):
    """Build the model (set model inputs/outputs), mainly for subclass model."""
    processed_inputs = []
    is_dict_inputs = False
    orig_inputs = inputs
    if isinstance(inputs, (data_types.DatasetV1, data_types.DatasetV2)):
        (inputs, targets, _) = training_utils_v1.extract_tensors_from_dataset(inputs)
    training_utils_v1.validate_input_types(inputs, orig_inputs)
    if <MASK>:
        processed_inputs += list(inputs)
    elif isinstance(inputs, dict):
        is_dict_inputs = True
        keys = sorted(inputs.keys())
        processed_inputs = [inputs[k] for k in keys]
    else:
        processed_inputs.append(inputs)
    for input_tensor in processed_inputs:
        if training_utils_v1.is_composite_or_composite_value(input_tensor):
            raise ValueError('All SparseTensor and RaggedTensor inputs must be explicitly declared using a keras.Input() with sparse=True or ragged=True. We found an undeclared input %s. For Sequential models, please add a keras.Input() as your first Layer. For subclassed models, please call self._set_inputs() on your input set, which you can create using keras.Input() for each input to your model.' % (input_tensor,))
    if isinstance(orig_inputs, (data_types.DatasetV1, data_types.DatasetV2, iterator_ops.Iterator)):
        if not self.inputs:
            inputs = training_utils_v1.cast_if_floating_dtype(inputs, self.dtype)

        def create_tensor_spec(t):
            return tensor_spec.TensorSpec(t.shape, t.dtype)
        cast_inputs = nest.map_structure(create_tensor_spec, inputs)
    elif training_utils_v1.has_tensors(inputs):
        cast_inputs = training_utils_v1.cast_if_floating_dtype(inputs)
    else:
        cast_inputs = inputs
    self._set_inputs(cast_inputs)
    return (processed_inputs, targets, is_dict_inputs)

def is_mutated_later_in_fw(node):
    if _has_tag_is_backward(node):
        return False
    tensor_arg_aliases = [x for x in node.args if isinstance(x, fx.Node) and 'val' in x.meta and isinstance(x.meta['val'], torch.Tensor)]
    while len(tensor_arg_aliases) > 0:
        a = tensor_arg_aliases.pop()
        for u in a.users:
            if not isinstance(u.target, torch._ops.OpOverload):
                continue
            if u.target._schema.is_mutable and order[u] > order[node] and (not (_has_tag_is_backward(u) or _has_tag_must_be_in_backward(u))):
                for (idx, alias_info) in enumerate(u.target._schema.arguments):
                    if alias_info.is_write and u.args[idx] is a:
                        return True
            elif <MASK>:
                tensor_arg_aliases.append(u)
    return False

@_apply_docstring_templates
def amax(input: Union[Tensor, MaskedTensor], dim: DimOrDims=None, *, keepdim: Optional[bool]=False, dtype: Optional[DType]=None, mask: Optional[Tensor]=None) -> Tensor:
    """{reduction_signature}

{reduction_descr}

{reduction_identity_dtype}

{reduction_args}

{reduction_example}"""
    if dtype is None:
        dtype = input.dtype
    mask_input = _combine_input_and_mask(amax, input, mask)
    dim_ = _canonical_dim(dim, mask_input.ndim)
    if mask_input.layout == torch.strided:
        return torch.amax(mask_input, dim_, bool(keepdim)).to(dtype=dtype)
    elif <MASK>:
        if mask is None:
            raise ValueError('masked amax expects explicit mask for sparse_coo tensor input')
        return _sparse_coo_scatter_reduction_helper(torch.amax, mask_input, dim_, bool(keepdim), dtype)
    elif mask_input.layout == torch.sparse_csr:
        if mask is None:
            raise ValueError('masked amax expects explicit mask for sparse_csr tensor input')
        return _sparse_csr_segment_reduction_helper(torch.amax, mask_input, dim_, bool(keepdim), dtype)
    else:
        raise ValueError(f'masked amax expects strided, sparse_coo or sparse_csr tensor (got {mask_input.layout} tensor)')

def wrapper(*args, **kwargs):
    scalars = [arg for arg in args if isinstance(arg, (int, sympy.Expr)) or (isinstance(arg, CppCSEVariable) and (not arg.is_vec))]
    vectors = [arg for arg in args if isinstance(arg, CppCSEVariable) and arg.is_vec]
    new_args = list(args)
    if <MASK>:
        new_args = []
        for arg in args:
            if isinstance(arg, (int, sympy.Expr)):
                if isinstance(arg, sympy.Expr) and (not arg.is_number):
                    arg = ops.index_expr(arg, torch.int64)
                else:
                    arg = ops.constant(arg, torch.int64)
                arg = arg.value if isinstance(arg, OpsValue) else arg
            new_args.append(arg)
    if vectors:
        if len(new_args) == 2:
            new_args = promote_args(new_args)
        elif func == CppVecOverrides.where:
            new_args[1:] = promote_args(new_args[1:])
    if scalars and vectors:
        assert isinstance(V.kernel, CppVecKernel)
        new_args = [V.kernel.broadcast(new_arg) if isinstance(new_arg, CppCSEVariable) and (not new_arg.is_vec) and (func not in [CppVecOverrides.rand, CppVecOverrides.randn, CppVecOverrides.randint64]) else new_arg for new_arg in new_args]
    if vectors:
        return func(*new_args, **kwargs)
    else:
        scalar_ops = super(CppVecOverrides, self)
        scalar_func = getattr(scalar_ops, func.__name__)
        assert scalar_func is not None
        return scalar_func(*args, **kwargs)

def astype(self, dtype, copy: bool=True):
    dtype = pandas_dtype(dtype)
    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self
    elif isinstance(dtype, ExtensionDtype):
        if <MASK>:
            return super().astype(dtype, copy=copy)
        elif self.tz is None:
            raise TypeError('Cannot use .astype to convert from timezone-naive dtype to timezone-aware dtype. Use obj.tz_localize instead or series.dt.tz_localize instead')
        else:
            np_dtype = np.dtype(dtype.str)
            res_values = astype_overflowsafe(self._ndarray, np_dtype, copy=copy)
            return type(self)._simple_new(res_values, dtype=dtype, freq=self.freq)
    elif self.tz is None and lib.is_np_dtype(dtype, 'M') and (not is_unitless(dtype)) and is_supported_dtype(dtype):
        res_values = astype_overflowsafe(self._ndarray, dtype, copy=True)
        return type(self)._simple_new(res_values, dtype=res_values.dtype)
    elif self.tz is not None and lib.is_np_dtype(dtype, 'M'):
        raise TypeError("Cannot use .astype to convert from timezone-aware dtype to timezone-naive dtype. Use obj.tz_localize(None) or obj.tz_convert('UTC').tz_localize(None) instead.")
    elif self.tz is None and lib.is_np_dtype(dtype, 'M') and (dtype != self.dtype) and is_unitless(dtype):
        raise TypeError("Casting to unit-less dtype 'datetime64' is not supported. Pass e.g. 'datetime64[ns]' instead.")
    elif isinstance(dtype, PeriodDtype):
        return self.to_period(freq=dtype.freq)
    return dtl.DatetimeLikeArrayMixin.astype(self, dtype, copy)

def filter_nodes(nodes: Iterable[torch.fx.Node], fn: Any) -> list[torch.fx.Node]:
    fns = [fn]
    if <MASK>:
        fns.extend([getattr(fn, overload) for overload in fn.overloads()])
    return [node for node in nodes if node.target in fns]

def __init__(self, stream: Optional['torch.cuda.Stream']):
