def _populate_quantization_component_spec(quant_method: _QuantizationMethod) -> None:
    """Populates default values for QuantizationComponentSpec.

  Args:
    quant_method: The quantization method to be updated.
  """
    updated_component_spec = dict()
    if quant_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8 or quant_method.preset_method == _PresetMethod.METHOD_DYNAMIC_RANGE_INT8:
        updated_component_spec[_QuantizationComponent.COMPONENT_ACTIVATION] = _QuantizationComponentSpec(quantization_component=_QuantizationComponent.COMPONENT_ACTIVATION, tensor_type=_TensorType.TENSORTYPE_INT_8)
        updated_component_spec[_QuantizationComponent.COMPONENT_WEIGHT] = _QuantizationComponentSpec(quantization_component=_QuantizationComponent.COMPONENT_WEIGHT, tensor_type=_TensorType.TENSORTYPE_INT_8)
        updated_component_spec[_QuantizationComponent.COMPONENT_BIAS] = _QuantizationComponentSpec(quantization_component=_QuantizationComponent.COMPONENT_BIAS, tensor_type=_TensorType.TENSORTYPE_INT_32)
    elif quant_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8:
        updated_component_spec[_QuantizationComponent.COMPONENT_WEIGHT] = _QuantizationComponentSpec(quantization_component=_QuantizationComponent.COMPONENT_WEIGHT, tensor_type=_TensorType.TENSORTYPE_INT_8)
    if <MASK>:
        for component_spec in quant_method.quantization_component_specs:
            if component_spec.quantization_component in [_QuantizationComponent.COMPONENT_WEIGHT, _QuantizationComponent.COMPONENT_ACTIVATION]:
                if component_spec.tensor_type != _TensorType.TENSORTYPE_INT_8:
                    raise ValueError('Only int8 precision is supported for input operands.')
            elif component_spec.tensor_type != _TensorType.TENSORTYPE_INT_32:
                raise ValueError('Only int32 precision is supported for bias.')
            updated_component_spec[component_spec.quantization_component] = component_spec
    del quant_method.quantization_component_specs[:]
    quant_method.quantization_component_specs.extend(updated_component_spec.values())
    if (quant_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8 or quant_method.preset_method == _PresetMethod.METHOD_DYNAMIC_RANGE_INT8) and len(quant_method.quantization_component_specs) != 3:
        raise ValueError('Only 3 components are needed for', quant_method)
    elif quant_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8 and len(quant_method.quantization_component_specs) != 1:
        raise ValueError('At least one component spec needs to be specified.')

@classmethod
def eval(cls, p, q):
    if q.is_zero:
        raise ZeroDivisionError('Modulo by zero')
    if p is S.Zero or p in (q, -q) or q == 1:
        return S.Zero
    if q.is_Number and p.is_Number:
        if p < 0:
            raise AssertionError(p)
        if q < 1:
            raise AssertionError(q)
        return p % q
    if q.is_Number and q == 2:
        if p.is_even:
            return S.Zero
        if p.is_odd:
            return S.One
    r = p / q
    if <MASK>:
        return S.Zero
    less = p < q
    if less.is_Boolean and bool(less) and r.is_positive:
        return p

@torch.no_grad()
def _get_model_state_dict(model: nn.Module, info: _StateDictInfo) -> dict[str, ValueType]:
    if not info.handle_model:
        return {}
    with info.fsdp_context():
        state_dict = _state_dict_fn(model, 'state_dict')()
    for key in list(state_dict.keys()):
        fqns = _get_fqns(model, key)
        if len(fqns) != 1:
            raise AssertionError(f"Expected 1 FQN for key '{key}', got {len(fqns)}: {fqns}")
        fqn = next(iter(fqns))
        if fqn != key:

            def verify(key, fqn) -> bool:
                if len(fqn) >= len(key):
                    return False
                fqn_split = fqn.split('.')
                key_split = key.split('.')
                fqn_idx = 0
                for (key_idx, key_name) in enumerate(key_split):
                    if key_name == fqn_split[fqn_idx]:
                        fqn_idx += 1
                        if fqn_idx == len(fqn_split):
                            return key_idx == len(key_split) - 1
                    elif key_name in ('module', '_orig_mod'):
                        continue
                    else:
                        return False
                return True
            if not verify(key, fqn):
                raise RuntimeError(f'An unexpected key, {key}, exists. FQN is {fqn}')
            state_dict[fqn] = state_dict.pop(key)
    if <MASK>:
        new_state_dict: dict[str, ValueType] = {}
        for fqn in state_dict.keys():
            for prefix in info.submodule_prefixes:
                if not fqn.startswith(prefix):
                    continue
                if info.keep_submodule_prefixes:
                    new_state_dict[fqn] = state_dict[fqn]
                else:
                    new_fqn = fqn[len(prefix):]
                    new_state_dict[new_fqn] = state_dict[fqn]
        state_dict = new_state_dict
    if info.ignore_frozen_params:
        for (key, param) in model.named_parameters():
            if param.requires_grad:
                continue
            fqns = _get_fqns(model, key)
            for fqn in fqns:
                state_dict.pop(fqn)
    return _maybe_full_or_cpu_state_dict(state_dict, info)

def get_formset(self, request, obj=None, **kwargs):
    """Return a BaseInlineFormSet class for use in add/change views."""
    if <MASK>:
        fields = kwargs.pop('fields')
    else:
        fields = flatten_fieldsets(self.get_fieldsets(request, obj))
    excluded = self.get_exclude(request, obj)
    exclude = [] if excluded is None else list(excluded)
    exclude.extend(self.get_readonly_fields(request, obj))
    if excluded is None and hasattr(self.form, '_meta') and self.form._meta.exclude:
        exclude.extend(self.form._meta.exclude)
    exclude = exclude or None
    can_delete = self.can_delete and self.has_delete_permission(request, obj)
    defaults = {'form': self.form, 'formset': self.formset, 'fk_name': self.fk_name, 'fields': fields, 'exclude': exclude, 'formfield_callback': partial(self.formfield_for_dbfield, request=request), 'extra': self.get_extra(request, obj, **kwargs), 'min_num': self.get_min_num(request, obj, **kwargs), 'max_num': self.get_max_num(request, obj, **kwargs), 'can_delete': can_delete, **kwargs}
    base_model_form = defaults['form']
    can_change = self.has_change_permission(request, obj) if request else True
    can_add = self.has_add_permission(request, obj) if request else True

    class DeleteProtectedModelForm(base_model_form):

        def hand_clean_DELETE(self):
            """
                We don't validate the 'DELETE' field itself because on
                templates it's not rendered using the field information, but
                just using a generic "deletion_field" of the InlineModelAdmin.
                """
            if self.cleaned_data.get(DELETION_FIELD_NAME, False):
                using = router.db_for_write(self._meta.model)
                collector = NestedObjects(using=using)
                if self.instance._state.adding:
                    return
                collector.collect([self.instance])
                if collector.protected:
                    objs = []
                    for p in collector.protected:
                        objs.append(_('%(class_name)s %(instance)s') % {'class_name': p._meta.verbose_name, 'instance': p})
                    params = {'class_name': self._meta.model._meta.verbose_name, 'instance': self.instance, 'related_objects': get_text_list(objs, _('and'))}
                    msg = _('Deleting %(class_name)s %(instance)s would require deleting the following protected related objects: %(related_objects)s')
                    raise ValidationError(msg, code='deleting_protected', params=params)

        def is_valid(self):
            result = super().is_valid()
            self.hand_clean_DELETE()
            return result

        def has_changed(self):
            if not can_change and (not self.instance._state.adding):
                return False
            if not can_add and self.instance._state.adding:
                return False
            return super().has_changed()
    defaults['form'] = DeleteProtectedModelForm
    if defaults['fields'] is None and (not modelform_defines_fields(defaults['form'])):
        defaults['fields'] = forms.ALL_FIELDS
    return inlineformset_factory(self.parent_model, self.model, **defaults)

def encode_arg(arg, path):
    """A representation for this argument, for converting into signatures."""
    if isinstance(arg, tensor_lib.Tensor):
        user_specified_name = None
        try:
            user_specified_name = compat.as_str(arg.op.get_attr('_user_specified_name'))
        except (ValueError, AttributeError):
            pass
        if path and user_specified_name and (user_specified_name != path[0]):
            name = user_specified_name
        else:
            name = tensor_lib.sanitize_spec_name('_'.join((str(p) for p in path)))
        return tensor_lib.TensorSpec(arg.shape, arg.dtype, name)
    if <MASK>:
        return trace_type.from_value(arg, signature_context)
    if isinstance(arg, composite_tensor.CompositeTensor):
        return arg._type_spec
    if isinstance(arg, (int, float, bool, str, type(None), dtypes.DType, tensor_lib.TensorSpec, type_spec.TypeSpec)):
        return arg
    return UnknownArgument()

def promote_constants(inputs, override_return_dtype=None, type_promotion_kind=None):
    assert override_return_dtype is None or type_promotion_kind is None, 'only one of override_return_dtype or type_promotion_kind may be given'
    if <MASK>:
        type_promotion_kind = ELEMENTWISE_TYPE_PROMOTION_KIND.DEFAULT
    if not any((isinstance(x, (sympy.Basic, int, float)) for x in inputs)):
        return inputs
    if all((isinstance(x, (int, float, sympy.Basic)) for x in inputs)):
        dtype = override_return_dtype or get_promoted_dtype(*inputs, type_promotion_kind=type_promotion_kind)

        def const_func(x):
            if isinstance(x, sympy.Basic):
                return ir.IndexingConstant(index=x, dtype=dtype, device=decode_device(None))
            else:
                return ir.Constant(value=x, dtype=dtype, device=decode_device(None))
        return [const_func(x) for x in inputs]
    ex = next((x for x in inputs if isinstance(x, (TensorBox, ExpandView, ir.Constant))))
    out = []
    for x in inputs:
        if isinstance(x, (int, float)):
            out.append(ExpandView.create(ir.Constant(value=x, dtype=ex.get_dtype(), device=ex.get_device_or_error()), list(ex.get_size())))
        elif isinstance(x, sympy.Basic):
            out.append(ExpandView.create(IndexingConstant(index=x, dtype=ex.get_dtype(), device=ex.get_device_or_error()), list(ex.get_size())))
        else:
            out.append(x)
    return out

