@torch_key_cache
def cutlass_key() -> bytes:
    """
    Compute a key representing the state of the CUTLASS library.

    Note: OSS and fbcode will have different keys.
    """
    if <MASK>:
        with importlib.resources.path('cutlass_library', 'src_hash.txt') as resource_path:
            with open(resource_path) as resource_file:
                return resource_file.read().encode()
    combined_hash = hashlib.sha256()
    build_code_hash([config.cuda.cutlass_dir], '', combined_hash)
    return combined_hash.digest()

def iteration_ranges_codegen_header(self, entry: IterationRangesRoot, code: IndentedBuffer) -> None:
    x = entry.prefix
    if entry.is_loop:
        code.writeline(f'{entry.name} = {x}offset + {x}base')
    elif entry.grid_dim is None:
        code.writeline(f'{entry.name} = {self.iteration_ranges_ranges_code(entry)}')
        code.writeline(f'{x}offset = 0')
    else:
        if <MASK>:
            line = f'{x}offset + {self.iteration_ranges_ranges_code(entry)}'
        else:
            line = self.iteration_ranges_scalar_code(entry, f'{x}offset')
        code.writelines([f'{x}offset = {self.iteration_ranges_get_pid(entry)} * {x.upper()}BLOCK', f'{entry.name} = {line}'])
    if self._has_constant_mask(entry):
        sizes = self.dense_size_str()
        code.writeline(f'{x}mask = tl.full({sizes}, True, tl.int1)')
    else:
        code.writeline(f'{x}mask = {entry.name} < {x}numel')

