def __iter__(self):
    for x in self.datapipe:
        key = self.group_key_fn(x)
        self.buffer_elements[key].append(x)
        self.curr_buffer_size += 1
        if self.group_size is not None and self.group_size == len(self.buffer_elements[key]):
            result: DataChunk[Any] = self.wrapper_class(self.buffer_elements[key])
            yield ((key, result) if self.keep_key else result)
            self.curr_buffer_size -= len(self.buffer_elements[key])
            del self.buffer_elements[key]
        if <MASK>:
            result_to_yield = self._remove_biggest_key()
            if result_to_yield is not None:
                result = self.wrapper_class(result_to_yield)
                yield ((key, result) if self.keep_key else result)
    for key in tuple(self.buffer_elements.keys()):
        result = self.wrapper_class(self.buffer_elements.pop(key))
        self.curr_buffer_size -= len(result)
        yield ((key, result) if self.keep_key else result)

def init_xsel_clipboard():
    DEFAULT_SELECTION = '-b'
    PRIMARY_SELECTION = '-p'

    def copy_xsel(text, primary=False):
        text = _stringifyText(text)
        selection_flag = DEFAULT_SELECTION
        if <MASK>:
            selection_flag = PRIMARY_SELECTION
        with subprocess.Popen(['xsel', selection_flag, '-i'], stdin=subprocess.PIPE, close_fds=True) as p:
            p.communicate(input=text.encode(ENCODING))

    def paste_xsel(primary=False):
        selection_flag = DEFAULT_SELECTION
        if primary:
            selection_flag = PRIMARY_SELECTION
        with subprocess.Popen(['xsel', selection_flag, '-o'], stdout=subprocess.PIPE, close_fds=True) as p:
            stdout = p.communicate()[0]
        return stdout.decode(ENCODING)
    return (copy_xsel, paste_xsel)

def use_native_matmul(mat1, mat2):
    if <MASK>:
        return False
    if config.triton.enable_persistent_tma_matmul and torch.utils._triton.has_triton_tma_device():
        raise AssertionError("native matmul doesn't support tma codegen yet")
    if config.triton.use_block_ptr:
        raise AssertionError("native matmul doesn't support block_ptr codegen yet")
    if not (mat1.get_device().type == 'cuda' and config.cuda_backend == 'triton'):
        return False
    triton_supported_dtype = [torch.int8, torch.uint8, torch.float16, torch.bfloat16, torch.float32]
    if mat1.dtype not in triton_supported_dtype:
        return False
    if mat2.dtype not in triton_supported_dtype:
        return False
    (m, k, n) = (mat1.get_size()[-2], mat1.get_size()[-1], mat2.get_size()[-1])
    if any(map(has_free_unbacked_symbols, [m, k, n])):
        return False
    if V.graph.sizevars.statically_known_leq(m, 1) or V.graph.sizevars.statically_known_leq(k, 1) or V.graph.sizevars.statically_known_leq(n, 1):
        return False
    return True

def _extract_dtype(x: Optional[Union[torch.dtype, TensorLikeType, NumberType]]) -> Optional[torch.dtype]:
    if <MASK>:
        return None
    if isinstance(x, torch.dtype):
        return x
    if isinstance(x, TensorLike):
        return x.dtype
    if isinstance(x, Number):
        return type_to_dtype(type(x))
    raise RuntimeError('Unexpected type given to _extract_dtype!')

def sample_inputs_sparse_reduction(op_info, device, dtype, requires_grad, layout, blocksize=None, **kwargs):
    """Sample inputs for reduction operations on sparse tensors."""
    layout_name = str(layout).split('.', 1)[-1].rsplit('_coo', 1)[0]
    op_supports_layout = getattr(op_info, 'supports_' + layout_name)
    if not op_supports_layout:
        return
    for sample_input in sample_inputs_reduction(op_info, device, dtype, requires_grad, **kwargs):
        if sample_input.input.ndim == 0:
            continue
        if layout in {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}:
            if sample_input.input.ndim < 2:
                continue
            if sample_input.input.ndim > 2 and (sample_input.input == 0).any():
                continue
        if layout in {torch.sparse_bsr, torch.sparse_bsc} and blocksize is None:
            blocksize = (1, 1)
        yield SampleInput(sample_input.input.detach().to_sparse(layout=layout, blocksize=blocksize).requires_grad_(requires_grad), args=sample_input.args, kwargs=sample_input.kwargs)
        if <MASK>:
            inp = sample_input.input.detach().to_sparse(layout=layout)
            inp = torch.sparse_coo_tensor(inp.indices().repeat(1, 2), inp.values().repeat(2), inp.shape, dtype=inp.dtype, device=inp.device)
            assert not inp.is_coalesced()
            yield SampleInput(inp.requires_grad_(requires_grad), args=sample_input.args, kwargs=sample_input.kwargs)
        if sample_input.input.ndim > 2:
            yield SampleInput(sample_input.input.detach().to_sparse(layout=layout, blocksize=blocksize, dense_dim=sample_input.input.ndim - 2).requires_grad_(requires_grad), args=sample_input.args, kwargs=sample_input.kwargs)

@staticmethod
def _template_from_string(source: str) -> Any:
    env = jinja2_env()
    if env is None:
        return None
    env.filters['indent_except_first'] = KernelTemplate.indent_except_first
    from jinja2 import TemplateSyntaxError
    try:
        return env.from_string(source)
    except TemplateSyntaxError as e:

        class DetailedTemplateSyntaxError(TemplateSyntaxError):

            def __init__(self, original_error: TemplateSyntaxError) -> None:
                super().__init__(original_error.message, original_error.lineno, original_error.name, original_error.filename)
                self.original_error = original_error

            def __str__(self) -> str:
                error_info = f'Error in template at line {self.lineno}\n'
                error_info += f'Error message: {self.message}\n'
                if <MASK>:
                    lines = self.original_error.source.split('\n')
                    error_info += 'Context:\n'
                    start = max(0, self.lineno - 2)
                    end = min(len(lines), self.lineno + 2)
                    for i in range(start, end):
                        if i == self.lineno - 1:
                            error_info += f'{i + 1}: --> {lines[i]}\n'
                            if hasattr(self.original_error, 'column'):
                                error_info += '     ' + ' ' * (self.original_error.column - 1) + '^\n'
                        else:
                            error_info += f'{i + 1}:     {lines[i]}\n'
                return error_info
        raise DetailedTemplateSyntaxError(e) from e

def matched_files_iter(root_path: str, includes: Iterable=(), ignores: Iterable=(), extensions: Iterable=(), out_of_place_only: bool=False, is_pytorch_extension: bool=False) -> Iterator[str]:
    exact_matches = set(includes)
    for (abs_dirpath, dirs, filenames) in os.walk(root_path, topdown=True):
        rel_dirpath = os.path.relpath(abs_dirpath, root_path)
        if rel_dirpath == '.':
            if '.git' in dirs:
                dirs.remove('.git')
            if 'build' in dirs:
                dirs.remove('build')
            if 'third_party' in dirs:
                dirs.remove('third_party')
                dirs.append('third_party/nvfuser')
        for filename in filenames:
            filepath = _to_unix_path(os.path.join(abs_dirpath, filename))
            rel_filepath = _to_unix_path(os.path.join(rel_dirpath, filename))
            if _fnmatch(filepath, includes) and (not _fnmatch(filepath, ignores)) and (match_extensions(filepath, extensions) or filepath in exact_matches):
                if <MASK>:
                    if not is_pytorch_file(rel_filepath) and (not is_caffe2_gpu_file(rel_filepath)):
                        continue
                    if out_of_place_only and (not is_out_of_place(rel_filepath)):
                        continue
                yield filepath

def _find_concrete_model_from_proxy(self, proxy_models, model_state):
    for base in model_state.bases:
        if <MASK>:
            continue
        base_key = make_model_tuple(base)
        base_state = proxy_models.get(base_key)
        if not base_state:
            return base_key
        return self._find_concrete_model_from_proxy(proxy_models, base_state)

def resolve_expression(self, query=None, allow_joins=True, reuse=None, summarize=False, for_save=False):
    c = super().resolve_expression(query, allow_joins, reuse, summarize)
    if summarize:
        for ref in c.get_refs():
            if query.annotations[ref].is_summary:
                raise FieldError(f"Cannot compute {c.name}('{ref}'): '{ref}' is an aggregate")
    elif not self.is_summary:
        expressions = super(Aggregate, c).get_source_expressions()
        for (index, expr) in enumerate(expressions):
            if expr.contains_aggregate:
                before_resolved = self.get_source_expressions()[index]
                name = before_resolved.name if hasattr(before_resolved, 'name') else repr(before_resolved)
                raise FieldError("Cannot compute %s('%s'): '%s' is an aggregate" % (c.name, name, name))
    if (default := c.default) is None:
        return c
    if <MASK>:
        default = default.resolve_expression(query, allow_joins, reuse, summarize)
        if default._output_field_or_none is None:
            default.output_field = c._output_field_or_none
    else:
        default = Value(default, c._output_field_or_none)
    c.default = None
    coalesce = Coalesce(c, default, output_field=c._output_field_or_none)
    coalesce.is_summary = c.is_summary
    return coalesce

def gather_ops_or_named_saveables(self):
    """Looks up or creates SaveableObjects which don't have cached ops.

    Returns:
      A tuple of (
          existing_restore_ops: list,
          named_saveables: dict,
          python_positions: list,
          registered_savers: dict)
    """
    recorded_registered_saver = self.get_registered_saver_name()
    if not (self.object_proto.attributes or recorded_registered_saver):
        return ([], {}, [], {})
    existing_restore_ops = []
    named_saveables = {}
    python_positions = []
    registered_savers = collections.defaultdict(dict)
    saveable_factories = saveable_object_util.saveable_objects_from_trackable(self.trackable)
    saver_name = registration.get_registered_saver_name(self.trackable)
    if recorded_registered_saver:
        if <MASK>:
            name = self.object_proto.registered_saver.object_name
            registered_savers[recorded_registered_saver][name] = self.trackable
    elif saver_name:
        registered_savers[saver_name] = {self.object_proto.attributes[0].checkpoint_key: self.trackable}
    elif isinstance(self.trackable, python_state.PythonState):
        python_positions.append(self)
    elif saveable_factories.keys() == {trackable_utils.SERIALIZE_TO_TENSORS_NAME}:
        (existing_restore_ops, named_saveables) = self._create_serialize_to_tensor_saveable(saveable_factories)
    elif saveable_factories:
        (existing_restore_ops, named_saveables) = self._create_saveables_by_attribute_name(saveable_factories)
    else:
        for serialized_tensor in self.object_proto.attributes:
            self._checkpoint.unused_attributes.setdefault(self._proto_id, []).append(serialized_tensor.name)
    return (existing_restore_ops, named_saveables, python_positions, registered_savers)

def compare_dict_tensors(dict_base, dict_control, precision):
    if len(OrderedSet(dict_base.keys())) != len(OrderedSet(dict_control.keys())):
        logger.warning('Mismatch keys found before and after pre/post grad fx passes.')
        logger.debug('keys before pre/post grad fx passes %s', dict_base.keys())
        logger.debug('keys after pre/post grad fx passes %s', dict_control.keys())
        return False
    is_allclose = True
    for key in dict_base.keys():
        if key not in dict_control:
            logger.warning('Mismatch parameter name %s does not exist after pre/post grad fx passes', key)
        if <MASK>:
            continue
        if not torch.allclose(dict_base[key], dict_control[key], rtol=precision, atol=precision, equal_nan=True):
            logger.warning('Mismatch parameter values found before and after pre/post grad fx passes.')
            logger.debug('value before pre/post grad fx passes %s', dict_base[key])
            logger.debug('value after pre/post grad fx passes %s', dict_control[key])
            is_allclose = False
    return is_allclose

def _extract_anchors_from_expr(segment: str) -> Optional[_Anchors]:
    """
    Given source code `segment` corresponding to a bytecode
    instruction, determine:
        - for binary ops, the location of the binary op
        - for indexing, the location of the brackets.
    `segment` is expected to be a valid Python expression
    """
    assert sys.version_info >= (3, 11)
    import ast
    try:
        tree = ast.parse('(\n' + segment + '\n)')
    except SyntaxError:
        return None
    if len(tree.body) != 1:
        return None
    lines = segment.split('\n')

    def normalize(lineno: int, offset: int) -> int:
        return _fix_offset(lines[lineno], offset)

    def next_valid_char(lineno: int, col: int) -> tuple[int, int]:
        while lineno < len(lines) and col >= len(lines[lineno]):
            col = 0
            lineno += 1
        assert lineno < len(lines) and col < len(lines[lineno])
        return (lineno, col)

    def increment(lineno: int, col: int) -> tuple[int, int]:
        col += 1
        (lineno, col) = next_valid_char(lineno, col)
        assert lineno < len(lines) and col < len(lines[lineno])
        return (lineno, col)

    def nextline(lineno: int, col: int) -> tuple[int, int]:
        col = 0
        lineno += 1
        (lineno, col) = next_valid_char(lineno, col)
        assert lineno < len(lines) and col < len(lines[lineno])
        return (lineno, col)
    statement = tree.body[0]
    if isinstance(statement, ast.Expr):
        expr = statement.value
        if isinstance(expr, ast.BinOp):
            cur_lineno = cast(int, expr.left.end_lineno) - 2
            assert expr.left.end_col_offset is not None
            cur_col = normalize(cur_lineno, expr.left.end_col_offset)
            (cur_lineno, cur_col) = next_valid_char(cur_lineno, cur_col)
            while (ch := lines[cur_lineno][cur_col]).isspace() or ch in ')\\#':
                if ch in '\\#':
                    (cur_lineno, cur_col) = nextline(cur_lineno, cur_col)
                else:
                    (cur_lineno, cur_col) = increment(cur_lineno, cur_col)
            right_col = cur_col + 1
            if right_col < len(lines[cur_lineno]) and (not (ch := lines[cur_lineno][right_col]).isspace()) and (ch not in '\\#'):
                right_col += 1
            return _Anchors(cur_lineno, cur_col, cur_lineno, right_col)
        elif <MASK>:
            left_lineno = cast(int, expr.value.end_lineno) - 2
            assert expr.value.end_col_offset is not None
            left_col = normalize(left_lineno, expr.value.end_col_offset)
            (left_lineno, left_col) = next_valid_char(left_lineno, left_col)
            while lines[left_lineno][left_col] != '[':
                (left_lineno, left_col) = increment(left_lineno, left_col)
            right_lineno = cast(int, expr.end_lineno) - 2
            assert expr.end_col_offset is not None
            right_col = normalize(right_lineno, expr.end_col_offset)
            return _Anchors(left_lineno, left_col, right_lineno, right_col)
        elif isinstance(expr, ast.Call):
            left_lineno = cast(int, expr.func.end_lineno) - 2
            assert expr.func.end_col_offset is not None
            left_col = normalize(left_lineno, expr.func.end_col_offset)
            (left_lineno, left_col) = next_valid_char(left_lineno, left_col)
            while lines[left_lineno][left_col] != '(':
                (left_lineno, left_col) = increment(left_lineno, left_col)
            right_lineno = cast(int, expr.end_lineno) - 2
            assert expr.end_col_offset is not None
            right_col = normalize(right_lineno, expr.end_col_offset)
            return _Anchors(left_lineno, left_col, right_lineno, right_col)
    return None

def _annotate_conv2d_binary_unary(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = find_sequential_partitions(gm, [torch.nn.Conv2d, operator.add, torch.nn.ReLU])
    for fused_partition in fused_partitions:
        (conv_partition, binary_partition, unary_partition) = fused_partition
        (conv_node, binary_node, unary_node) = self._get_output_nodes_of_partitions([conv_partition, binary_partition, unary_partition])
        if len(conv_node.users) != 1:
            continue
        (conv_node_idx, extra_input_node_idx) = self._get_input_idx_for_binary_node(conv_node, binary_node)
        if conv_node_idx is None or extra_input_node_idx is None:
            continue
        if conv_node != binary_node.args[conv_node_idx]:
            raise ValueError(f"{conv_node} doesn't match input of binary node")
        extra_input_node = binary_node.args[extra_input_node_idx]
        if conv_node.op != 'call_function' or conv_node.target != torch.ops.aten.conv2d.default:
            continue
        if <MASK>:
            continue
        if quantization_config is None:
            _annotate_nodes_not_quantize([conv_node, binary_node, unary_node])
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        binary_node_input_qspec_map = {}
        binary_node_input_qspec_map[extra_input_node] = get_input_act_qspec(quantization_config)
        binary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(input_qspec_map=binary_node_input_qspec_map, _annotated=True)
        unary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(_annotated=True, _is_output_of_quantized_pattern=True)

def _new_DatetimeIndex(cls, d):
    """
    This is called upon unpickling, rather than the default which doesn't
    have arguments and breaks __new__
    """
    if 'data' in d and (not isinstance(d['data'], DatetimeIndex)):
        data = d.pop('data')
        if not isinstance(data, DatetimeArray):
            tz = d.pop('tz')
            freq = d.pop('freq')
            dta = DatetimeArray._simple_new(data, dtype=tz_to_dtype(tz), freq=freq)
        else:
            dta = data
            for key in ['tz', 'freq']:
                if <MASK>:
                    assert d[key] == getattr(dta, key)
                    d.pop(key)
        result = cls._simple_new(dta, **d)
    else:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            result = cls.__new__(cls, **d)
    return result

def valid_grouped_mm_strides(input_specs: list[DTensorSpec], output_specs: tuple[Optional[DTensorSpec], ...]) -> bool:

    def local_meta(spec: OpSpec, placements: tuple[Placement, ...]) -> TensorMeta:
        if not isinstance(spec.output_specs, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(spec.output_specs)}')
        if not isinstance(spec.output_specs.tensor_meta, TensorMeta):
            raise AssertionError(f'Expected TensorMeta, got {type(spec.output_specs.tensor_meta)}')
        meta: TensorMeta = spec.output_specs.tensor_meta
        local_stride = compute_local_stride(meta.stride, mesh, placements)
        (local_shape, _) = compute_local_shape_and_global_offset(meta.shape, mesh, placements)
        return TensorMeta(torch.Size(local_shape), local_stride, meta.dtype)
    mat1_meta = local_meta(mat1_strategy.strategies[0], input_specs[0].placements)
    mat2_meta = local_meta(mat2_strategy.strategies[0], input_specs[1].placements)

    def check_valid_strides(meta: TensorMeta) -> bool:
        end_dim = len(meta.shape) - 1
        alignment = 16 // meta.dtype.itemsize
        if <MASK>:
            if meta.stride[end_dim] % alignment != 0:
                return False
        elif meta.stride[end_dim] == 1 and meta.stride[end_dim - 1] >= max(1, meta.shape[end_dim]):
            if meta.stride[end_dim - 1] % alignment != 0:
                return False
        else:
            return False
        return True
    mat1_valid = check_valid_strides(mat1_meta)
    mat2_valid = check_valid_strides(mat2_meta)
    return mat1_valid and mat2_valid

def _replace_attributes(gm: GraphModule, replacement: torch.nn.Module) -> None:
    gm.delete_all_unused_submodules()
    if <MASK>:
        replacement.graph.lint()

    def try_get_attr(gm: torch.nn.Module, target: str) -> Optional[Any]:
        (module_path, _, attr_name) = target.rpartition('.')
        try:
            mod: torch.nn.Module = gm.get_submodule(module_path)
        except AttributeError:
            return None
        attr = getattr(mod, attr_name, None)
        return attr
    for node in gm.graph.nodes:
        if node.op == 'call_module' or node.op == 'get_attr':
            gm_attr = try_get_attr(gm, node.target)
            replacement_attr = try_get_attr(replacement, node.target)
            if gm_attr is not None:
                continue
            elif replacement_attr is not None:
                new_attr = copy.deepcopy(replacement_attr)
                if isinstance(replacement_attr, torch.nn.Module):
                    gm.add_submodule(node.target, new_attr)
                else:
                    setattr(gm, node.target, new_attr)
            else:
                raise RuntimeError('Attempted to create a "', node.op, f'" node during subgraph rewriting with target {node.target}, but the referenced attribute does not exist in the replacement GraphModule')
    gm.graph.lint()

def _script_impl(obj, optimize=None, _frames_up=0, _rcb=None, example_inputs: Union[list[tuple], dict[Callable, list[tuple]], None]=None):
    global type_trace_db
    if optimize is not None:
        warnings.warn('`optimize` is deprecated and has no effect. Use `with torch.jit.optimized_execution()` instead', FutureWarning, stacklevel=3)
    if isinstance(obj, RecursiveScriptClass):
        return obj
    if isinstance(obj, ScriptModule):
        return obj
    if <MASK>:
        return obj
    if example_inputs:
        type_trace_db = JitTypeTraceStore()
        if monkeytype_trace:
            monkeytype_config = JitTypeTraceConfig(type_trace_db)
            with monkeytype_trace(monkeytype_config):
                if isinstance(example_inputs, dict):
                    for (module, example_input) in example_inputs.items():
                        for example in example_input:
                            module(*example)
                elif isinstance(example_inputs, list):
                    for examples in example_inputs:
                        obj(*examples)
                else:
                    raise ValueError('Error: Unable to infer types. Please format the inputs to type `List[Tuple]` or `Dict[Callable, List[Tuple]]` to be run with MonkeyType.')
        else:
            warnings.warn('Warning: monkeytype is not installed. Please install https://github.com/Instagram/MonkeyType to enable Profile-Directed Typing in TorchScript. Refer to https://github.com/Instagram/MonkeyType/blob/master/README.rst to install MonkeyType. ')
    if isinstance(obj, torch.nn.Module):
        obj = call_prepare_scriptable_func(obj)
        return torch.jit._recursive.create_script_module(obj, torch.jit._recursive.infer_methods_to_compile)
    else:
        obj = obj.__prepare_scriptable__() if hasattr(obj, '__prepare_scriptable__') else obj
    if isinstance(obj, dict):
        return create_script_dict(obj)
    if isinstance(obj, list):
        return create_script_list(obj)
    if inspect.isclass(obj):
        qualified_name = _qualified_name(obj)
        if issubclass(obj, torch.nn.Module):
            raise RuntimeError(f"Type '{obj}' cannot be compiled since it inherits from nn.Module, pass an instance instead")
        if issubclass(obj, enum.Enum):
            return obj
        if not _is_new_style_class(obj):
            raise RuntimeError("TorchScript classes must be new-style classes. Please inherit from 'object'.")
        if len(obj.mro()) > 2:
            raise RuntimeError("TorchScript classes does not support inheritance yet. Please directly inherit from 'object'.")
        if _rcb is None:
            _rcb = _jit_internal.createResolutionCallbackFromFrame(_frames_up + 1)
        _compile_and_register_class(obj, _rcb, qualified_name)
        return obj
    elif inspect.isfunction(obj) or inspect.ismethod(obj):
        qualified_name = _qualified_name(obj)
        if hasattr(obj, '__script_if_tracing_wrapper'):
            obj = obj.__original_fn
            _rcb = _jit_internal.createResolutionCallbackFromClosure(obj)
        if hasattr(obj, '__script_unsupported'):
            raise RuntimeError('TorchScript error: ' + obj.__script_unsupported)
        _check_directly_compile_overloaded(obj)
        maybe_already_compiled_fn = _try_get_jit_cached_function(obj)
        if maybe_already_compiled_fn:
            maybe_already_compiled_fn._torchdynamo_inline = obj
            return maybe_already_compiled_fn
        ast = get_jit_def(obj, obj.__name__)
        if _rcb is None:
            _rcb = _jit_internal.createResolutionCallbackFromClosure(obj)
        fn = torch._C._jit_script_compile(qualified_name, ast, _rcb, get_default_args(obj))
        fn.__doc__ = obj.__doc__
        fn.__name__ = 'ScriptFunction'
        fn.__qualname__ = 'torch.jit.ScriptFunction'
        fn._torchdynamo_inline = obj
        _set_jit_function_cache(obj, fn)
        return fn
    else:
        return torch.jit._recursive.create_script_class(obj)

def construct_reverse_graph(roots: list[Node]) -> dict[Node, list[Node]]:
    q: collections.deque[Node] = collections.deque()
    root_seen: set[Node] = set()
    reverse_edges_dict: dict[Node, list[Node]] = collections.defaultdict(list)
    for node in roots:
        if node is not None and node not in root_seen:
            q.append(node)
            root_seen.add(node)
    while q:
        node = q.popleft()
        for (fn, _) in node.next_functions:
            if <MASK>:
                if len(reverse_edges_dict[fn]) == 0:
                    q.append(fn)
                reverse_edges_dict[fn].append(node)
    return reverse_edges_dict

def scatter_kwargs(inputs: tuple[Any, ...], kwargs: Optional[dict[str, Any]], target_gpus: Sequence[Union[int, torch.device]], dim: int=0) -> tuple[tuple[Any, ...], tuple[dict[str, Any], ...]]:
    """Scatter with support for kwargs dictionary."""
    scattered_inputs = scatter(inputs, target_gpus, dim) if inputs else []
    scattered_kwargs = scatter(kwargs, target_gpus, dim) if kwargs else []
    if len(scattered_inputs) < len(scattered_kwargs):
        scattered_inputs.extend((() for _ in range(len(scattered_kwargs) - len(scattered_inputs))))
    elif <MASK>:
        scattered_kwargs.extend(({} for _ in range(len(scattered_inputs) - len(scattered_kwargs))))
    return (tuple(scattered_inputs), tuple(scattered_kwargs))

def getLapackRoutines(wrapped_routines, ignores, lapack_dir):
    blas_src_dir = os.path.join(lapack_dir, 'BLAS', 'SRC')
    if not os.path.exists(blas_src_dir):
        blas_src_dir = os.path.join(lapack_dir, 'blas', 'src')
    lapack_src_dir = os.path.join(lapack_dir, 'SRC')
    if not os.path.exists(lapack_src_dir):
        lapack_src_dir = os.path.join(lapack_dir, 'src')
    install_src_dir = os.path.join(lapack_dir, 'INSTALL')
    if <MASK>:
        install_src_dir = os.path.join(lapack_dir, 'install')
    library = LapackLibrary([install_src_dir, blas_src_dir, lapack_src_dir])
    for r in ignores:
        library.addIgnorableRoutine(r)
    for w in wrapped_routines:
        library.addRoutine(w)
    library.resolveAllDependencies()
    return library

def _sqlalchemy_type(self, col: Index | Series):
    dtype: DtypeArg = self.dtype or {}
    if is_dict_like(dtype):
        dtype = cast(dict, dtype)
        if col.name in dtype:
            return dtype[col.name]
    col_type = lib.infer_dtype(col, skipna=True)
    from sqlalchemy.types import TIMESTAMP, BigInteger, Boolean, Date, DateTime, Float, Integer, SmallInteger, Text, Time
    if col_type in ('datetime64', 'datetime'):
        try:
            if col.dt.tz is not None:
                return TIMESTAMP(timezone=True)
        except AttributeError:
            if getattr(col, 'tz', None) is not None:
                return TIMESTAMP(timezone=True)
        return DateTime
    if col_type == 'timedelta64':
        warnings.warn("the 'timedelta' type is not supported, and will be written as integer values (ns frequency) to the database.", UserWarning, stacklevel=find_stack_level())
        return BigInteger
    elif col_type == 'floating':
        if <MASK>:
            return Float(precision=23)
        else:
            return Float(precision=53)
    elif col_type == 'integer':
        if col.dtype.name.lower() in ('int8', 'uint8', 'int16'):
            return SmallInteger
        elif col.dtype.name.lower() in ('uint16', 'int32'):
            return Integer
        elif col.dtype.name.lower() == 'uint64':
            raise ValueError('Unsigned 64 bit integer datatype is not supported')
        else:
            return BigInteger
    elif col_type == 'boolean':
        return Boolean
    elif col_type == 'date':
        return Date
    elif col_type == 'time':
        return Time
    elif col_type == 'complex':
        raise ValueError('Complex datatypes not supported')
    return Text

def setup(self, dtype, structure, axis, sort):
    N = 10000
    if dtype == 'datetime64[ns]':
        vals = date_range('1970-01-01', periods=N)
    elif dtype in ('int64', 'Int64', 'int64[pyarrow]'):
        vals = np.arange(N, dtype=np.int64)
    elif dtype in ('string[python]', 'string[pyarrow]'):
        vals = Index([f'i-{i}' for i in range(N)], dtype=object)
    else:
        raise NotImplementedError
    idx = Index(vals, dtype=dtype)
    if structure == 'monotonic':
        idx = idx.sort_values()
    elif <MASK>:
        idx = idx[::-1]
    elif structure == 'has_na':
        if not idx._can_hold_na:
            raise NotImplementedError
        idx = Index([None], dtype=dtype).append(idx)
    else:
        raise NotImplementedError
    self.series = [Series(i, idx[:-i]) for i in range(1, 6)]

def _dispatch_modules(self, redirected_call_indices, consts_targets):
    """For a module whose call signatures are preserved, replace
        multiple modules corresponding to multiple calls to that module
        with a single dispatcher module that tracks which module to call.
        """
    called_modules = defaultdict(list)
    for entry in self.module_call_graph:
        if entry.fqn and entry.signature:
            fqn = entry.fqn
            mod = _get_attr(self, redirected_call_indices.get(fqn, fqn))
            (base, idx) = fqn.split('@') if '@' in fqn else [fqn, '0']
            called_modules[base].append((int(idx), mod))
    attrs_map = defaultdict(set)
    for target in consts_targets:
        if '.' in target:
            (orig_fqn, name) = target.rsplit('.', 1)
            attrs_map[orig_fqn].add(name)
        else:
            attrs_map[''].add(target)
    for (orig_fqn, indexed_call_modules) in called_modules.items():
        call_modules = [mod for (_, mod) in sorted(indexed_call_modules)]
        if len(call_modules) > 1:
            for i in range(len(call_modules)):
                fqn = _call_name(orig_fqn, i + 1)
                if fqn not in redirected_call_indices:
                    (*prefix, name) = fqn.split('.')
                    _get_attr_via_attr_list(self, prefix)._modules.pop(name)
            self.set_submodule(orig_fqn, InterpreterModuleDispatcher(attrs_map[orig_fqn], call_modules))

    def elide_call_indices(prefix, graph):
        for node in graph.nodes:
            if <MASK>:
                fqn = node.target.split('@')[0]
                path = f'{prefix}.{fqn}' if prefix else fqn
                if path in called_modules:
                    node.target = fqn
    for (fqn, mod) in self.named_modules(remove_duplicate=False):
        if hasattr(mod, 'graph'):
            elide_call_indices(fqn, mod.graph)
        elif hasattr(mod, '_call_modules'):
            for mod_ in mod._call_modules:
                assert hasattr(mod_, 'graph')
                elide_call_indices(fqn, mod_.graph)

@property
def simplified_fx_joint_graph(self) -> Graph:
    if <MASK>:
        self._lazily_initialized_graphs[self.__SIMPLIFIED_FX_JOINT_GRAPH] = self._recreate_psuedo_joint_graph()
    return self._lazily_initialized_graphs[self.__SIMPLIFIED_FX_JOINT_GRAPH]

def __str__(self):
    if self.rank is None:
        return '<unknown>'
    elif self.rank == 1:
        if <MASK>:
            return '(%s,)' % self._dims[0]
        else:
            return '(%s,)' % self.dims[0]
    elif self._v2_behavior:
        return '(%s)' % ', '.join((str(d) for d in self._dims))
    else:
        return '(%s)' % ', '.join((str(d) for d in self.dims))

def deserialize_node(self, serialized_node: Node, target: Callable) -> None:

    def _is_single_tensor_return(target) -> bool:
        schema = _get_schema_from_target(target)
        returns = schema.returns
        return len(returns) == 1 and isinstance(returns[0].real_type, torch.TensorType)
    if target in _SYM_OPS or target == torch.ops.aten.item.default:
        name = serialized_node.outputs[0].value.as_name
        args = self.deserialize_sym_op_inputs(serialized_node.inputs)
        fx_node = self.graph.create_node('call_function', target, args, {}, name)
        self.deserialize_sym_op_outputs(serialized_node, fx_node)
    elif target is torch._higher_order_ops.triton_kernel_wrap.triton_kernel_wrapper_functional:
        raise SerializeError('deserialize nyi for torch._higher_order_ops.triton_kernel_wrap.triton_kernel_wrapper_functional')
    elif isinstance(target, torch._ops.HigherOrderOperator):
        (args, kwargs) = self.deserialize_hoo_inputs(serialized_node.inputs)
        metadata = self.deserialize_metadata(serialized_node.metadata)
        for x in (*args, *kwargs.values()):
            if isinstance(x, torch.fx.Node) and x.op == 'get_attr':
                x.meta.update(metadata)
        name = serialized_node.outputs[0].as_tensor.name if len(serialized_node.outputs) == 1 and hasattr(serialized_node.outputs[0], 'as_tensor') and getattr(serialized_node, 'is_hop_single_tensor_return', True) else None
        fx_node = self.graph.create_node('call_function', target, args, kwargs, name)
        self.deserialize_outputs(serialized_node, fx_node)
        fx_node.meta.update(metadata)
    elif isinstance(target, (torch._ops.OpOverload, *_registered_extension_types())):
        name = serialized_node.outputs[0].as_tensor.name if _is_single_tensor_return(target) else None
        (args, kwargs) = self.deserialize_inputs(target, serialized_node)
        fx_node = self.graph.create_node('call_function', target, args, kwargs, name)
        self.deserialize_outputs(serialized_node, fx_node)
    else:
        _additional_msg = f'We failed to resolve {target} to an operator. ' + "If it's a custom op/custom triton op, this is usually because the custom op is not registered" + ' when deserializing. Please import the custom op to register it before deserializing.' + ' Otherwise, please file an issue on github.' if isinstance(target, str) else ''
        raise SerializeError(_additional_msg + f' Unsupported target type for node {serialized_node}: {type(target)}.')
    fx_node.meta.update(self.deserialize_metadata(serialized_node.metadata))
    log.debug('[deserialize_node] %s: %s(%s, {%s}) -> %s', fx_node.name, fx_node.target, fx_node.args, fx_node.kwargs, fx_node.meta.get('val'))
    if target == torch.ops.aten._assert_scalar.default:
        if <MASK>:
            expr = arg.meta['val']
            if isinstance(expr, torch.SymBool):
                self.shape_env.guard_or_defer_runtime_assert(expr.node.expr, '', fx_node)
    elif target == torch.ops.aten.sym_constrain_range_for_size.default:
        sym = fx_node.args[0].meta['val']
        if isinstance(sym, torch.SymInt):
            self.shape_env._constrain_range_for_size(sym.node.expr)
    if fx_node.op not in ['placeholder', 'output'] and 'nn_module_stack' not in fx_node.meta:
        fx_node.meta['nn_module_stack'] = {}

def set_model(self, model):
    """Sets Keras model and creates summary ops."""
    self.model = model
    self._init_writer(model)
    if <MASK>:
        self._make_histogram_ops(model)
        self.merged = tf_summary.merge_all()
    if self.embeddings_freq and self.embeddings_data is not None:
        from tensorflow.python.keras.engine import training_utils_v1
        self.embeddings_data = training_utils_v1.standardize_input_data(self.embeddings_data, model.input_names)
        embeddings_layer_names = self.embeddings_layer_names
        if not embeddings_layer_names:
            embeddings_layer_names = [layer.name for layer in self.model.layers if type(layer).__name__ == 'Embedding']
        self.assign_embeddings = []
        embeddings_vars = {}
        self.batch_id = batch_id = array_ops.placeholder(dtypes.int32)
        self.step = step = array_ops.placeholder(dtypes.int32)
        for layer in self.model.layers:
            if layer.name in embeddings_layer_names:
                embedding_input = self.model.get_layer(layer.name).output
                embedding_size = np.prod(embedding_input.shape[1:])
                embedding_input = array_ops.reshape(embedding_input, (step, int(embedding_size)))
                shape = (self.embeddings_data[0].shape[0], int(embedding_size))
                embedding = variables.Variable(array_ops.zeros(shape), name=layer.name + '_embedding')
                embeddings_vars[layer.name] = embedding
                batch = state_ops.assign(embedding[batch_id:batch_id + step], embedding_input)
                self.assign_embeddings.append(batch)
        self.saver = saver.Saver(list(embeddings_vars.values()))
        if isinstance(self.embeddings_metadata, str):
            embeddings_metadata = {layer_name: self.embeddings_metadata for layer_name in embeddings_vars.keys()}
        else:
            embeddings_metadata = self.embeddings_metadata
        try:
            from tensorboard.plugins import projector
        except ImportError:
            raise ImportError('Failed to import TensorBoard. Please make sure that TensorBoard integration is complete."')
        config = projector.ProjectorConfig()
        for (layer_name, tensor) in embeddings_vars.items():
            embedding = config.embeddings.add()
            embedding.tensor_name = tensor.name
            if embeddings_metadata is not None and layer_name in embeddings_metadata:
                embedding.metadata_path = embeddings_metadata[layer_name]
        projector.visualize_embeddings(self.writer, config)

def assertExpectedInline(self, actual, expect, skip=0, ignore_comments=False, ignore_empty_lines=False):
    actual = actual if isinstance(actual, str) else str(actual)
    actual = self._remove_ansi_escape(actual)
    expect = self._remove_ansi_escape(expect)
    if <MASK>:
        actual = self.remove_comment_lines(actual)
        expect = self.remove_comment_lines(expect)
    if ignore_empty_lines:
        actual = self.remove_empty_lines(actual)
        expect = self.remove_empty_lines(expect)
    return super().assertExpectedInline(actual if isinstance(actual, str) else str(actual), expect, skip + 1)

def _schedule_collectives_for_overlap(self, compute_node: fx.Node, available_compute_time: float) -> None:
    """Opportunistically schedule collectives that can be hidden by compute."""
    compute_ancestors = self.node_ancestors[compute_node]
    possible_collectives = []
    for collective in self.unscheduled_collectives:
        distance = abs(self.node_idx[compute_node] - self.node_idx[collective])
        if distance > self.max_node_distance:
            break
        if not self.off_compute_path(collective):
            if self.compute_index_domination[collective] - self.current_compute_index > self.max_compute_pre_fetch:
                continue
        possible_collectives.append(collective)
    possible_collectives = sorted(possible_collectives, key=lambda n: (self.compute_index_domination[n], self.node_idx[n]))
    log.debug('Scheduling collectives for overlap: compute_node=%s, available_time=%.2f ms, candidates=%d, current_memory=%d bytes', compute_node.name, available_compute_time, len(possible_collectives), self.memory_tracker.current_memory_bytes)
    for collective in possible_collectives:
        if available_compute_time == 0:
            break
        info = self.collective_info[collective]
        if collective in compute_ancestors or compute_node in self.node_ancestors[collective]:
            continue
        while self.in_flight and self.max_in_flight_bytes - self.in_flight_bytes < info.size_bytes and self._wait_is_hidden(self._get_oldest_wait(), compute_node):
            self._force_oldest_wait()
        if self.max_in_flight_bytes - self.in_flight_bytes < info.size_bytes:
            continue
        path = self._find_schedulable_path(collective, compute_node)
        if <MASK>:
            continue
        log.debug('Overlapping collective %s with compute %s: coll_domination=%d, current_depth=%d', collective.name, compute_node.name, self.compute_index_domination[collective], self.current_compute_index)
        self._schedule_path_to_collective(path, compute_node)
        self._handle_collective_start(collective)
        overlap_amount = min(available_compute_time, info.exposed_time_ms)
        info.exposed_time_ms -= overlap_amount
        if info.exposed_time_ms == 0:
            info.hiding_node = compute_node
        available_compute_time -= overlap_amount

def _register_parameter_or_buffer(module, name, X):
    if <MASK>:
        module.register_parameter(name, X)
    else:
        module.register_buffer(name, X)

def create_table(self, database, tablename, dry_run):
    cache = BaseDatabaseCache(tablename, {})
    if not router.allow_migrate_model(database, cache.cache_model_class):
        return
    connection = connections[database]
    if tablename in connection.introspection.table_names():
        if self.verbosity > 0:
            self.stdout.write("Cache table '%s' already exists." % tablename)
        return
    fields = (models.CharField(name='cache_key', max_length=255, unique=True, primary_key=True), models.TextField(name='value'), models.DateTimeField(name='expires', db_index=True))
    table_output = []
    index_output = []
    qn = connection.ops.quote_name
    for f in fields:
        field_output = [qn(f.name), f.db_type(connection=connection), '%sNULL' % ('NOT ' if not f.null else '')]
        if f.primary_key:
            field_output.append('PRIMARY KEY')
        elif f.unique:
            field_output.append('UNIQUE')
        if <MASK>:
            unique = 'UNIQUE ' if f.unique else ''
            index_output.append('CREATE %sINDEX %s ON %s (%s);' % (unique, qn('%s_%s' % (tablename, f.name)), qn(tablename), qn(f.name)))
        table_output.append(' '.join(field_output))
    full_statement = ['CREATE TABLE %s (' % qn(tablename)]
    for (i, line) in enumerate(table_output):
        full_statement.append('    %s%s' % (line, ',' if i < len(table_output) - 1 else ''))
    full_statement.append(');')
    full_statement = '\n'.join(full_statement)
    if dry_run:
        self.stdout.write(full_statement)
        for statement in index_output:
            self.stdout.write(statement)
        return
    with transaction.atomic(using=database, savepoint=connection.features.can_rollback_ddl):
        with connection.cursor() as curs:
            try:
                curs.execute(full_statement)
            except DatabaseError as e:
                raise CommandError("Cache table '%s' could not be created.\nThe error was: %s." % (tablename, e))
            for statement in index_output:
                curs.execute(statement)
    if self.verbosity > 1:
        self.stdout.write("Cache table '%s' created." % tablename)

@register_meta(aten._embedding_bag_backward)
def meta_embedding_bag_backward(grad, indices, offsets, offset2bag, bag_size, maximum_indices, num_weights, scale_grad_by_freq, mode, sparse, per_sample_weights, padding_idx=-1):
    if <MASK>:
        return aten._embedding_bag_sparse_backward(grad, indices, offsets, offset2bag, bag_size, num_weights, scale_grad_by_freq, mode, per_sample_weights, padding_idx)
