def _track_value(self, value, name):
    """Add a dependency on `value`."""
    value = sticky_attribute_assignment(trackable=self, value=value, name=name)
    if isinstance(value, variables.Variable):
        self._self_extra_variables.append(value)
    if not isinstance(value, base.Trackable):
        raise _UntrackableError(value)
    if <MASK>:
        value._use_resource_variables = True
    value_attribute_sentinel = getattr(value, '_attribute_sentinel', None)
    if value_attribute_sentinel:
        value_attribute_sentinel.add_parent(self._attribute_sentinel)
    return value

def __torch_dispatch__(self, func, types, args=(), kwargs=None):
    if self.advanced_module_tracker.name not in self.comm_module_operation_counts:
        self.comm_module_operation_counts[self.advanced_module_tracker.name] = {'operations_list': []}
    operation_dict = {}
    operation_dict['name'] = func
    operation_dict['input_shape'] = []
    operation_dict['input_sharding'] = []
    operation_dict['device_mesh'] = ''
    operation_dict['is_bw'] = self.advanced_module_tracker.is_bw
    operation_dict['is_activation_checkpointing'] = self.advanced_module_tracker.activation_checkpointing
    if any((t == DTensor for t in types)):
        for ele in args:
            if isinstance(ele, DTensor):
                operation_dict['input_shape'].append(ele.shape)
                operation_dict['input_sharding'].append(ele.placements)
                operation_dict['device_mesh'] = str(ele.device_mesh)
        self.comm_module_operation_counts[self.advanced_module_tracker.name]['operations_list'].append(operation_dict)
        return NotImplemented
    kwargs = kwargs if kwargs else {}
    out = func(*args, **kwargs)
    func_packet = func._overloadpacket
    if func_packet in self.comm_registry or func_packet in c10d_collective_ops:
        if func_packet in NATIVE_TO_PY_MAPPING:
            func_packet = NATIVE_TO_PY_MAPPING[func_packet]
        self.comm_counts[func_packet] += 1
        key = 'forward'
        if self.advanced_module_tracker.is_bw:
            key = 'backward'
        if self.advanced_module_tracker.name not in self.comm_module_counts:
            self.comm_module_counts[self.advanced_module_tracker.name] = {}
            self.comm_module_counts[self.advanced_module_tracker.name]['forward'] = defaultdict(int)
            self.comm_module_counts[self.advanced_module_tracker.name]['backward'] = defaultdict(int)
        self.comm_module_counts[self.advanced_module_tracker.name][key][func_packet] += 1
        for par in self.advanced_module_tracker.module_parents_dict[self.advanced_module_tracker.name]:
            if par != self.advanced_module_tracker.name:
                if <MASK>:
                    self.comm_module_counts[par] = {}
                    self.comm_module_counts[par]['forward'] = defaultdict(int)
                    self.comm_module_counts[par]['backward'] = defaultdict(int)
                self.comm_module_counts[par][key][func_packet] += 1
    if detect_fake_mode(args):
        return out
    self.comm_module_operation_counts[self.advanced_module_tracker.name]['operations_list'].append(operation_dict)
    return out

@property
def type(self):
    """
        Returns associated scalar type.
        """
    pa_type = self.pyarrow_dtype
    if pa.types.is_integer(pa_type):
        return int
    elif pa.types.is_floating(pa_type):
        return float
    elif pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type):
        return str
    elif pa.types.is_binary(pa_type) or pa.types.is_fixed_size_binary(pa_type) or pa.types.is_large_binary(pa_type):
        return bytes
    elif pa.types.is_boolean(pa_type):
        return bool
    elif pa.types.is_duration(pa_type):
        if <MASK>:
            return Timedelta
        else:
            return timedelta
    elif pa.types.is_timestamp(pa_type):
        if pa_type.unit == 'ns':
            return Timestamp
        else:
            return datetime
    elif pa.types.is_date(pa_type):
        return date
    elif pa.types.is_time(pa_type):
        return time
    elif pa.types.is_decimal(pa_type):
        return Decimal
    elif pa.types.is_dictionary(pa_type):
        return CategoricalDtypeType
    elif pa.types.is_list(pa_type) or pa.types.is_large_list(pa_type):
        return list
    elif pa.types.is_fixed_size_list(pa_type):
        return list
    elif pa.types.is_map(pa_type):
        return list
    elif pa.types.is_struct(pa_type):
        return dict
    elif pa.types.is_null(pa_type):
        return type(pa_type)
    elif isinstance(pa_type, pa.BaseExtensionType):
        return type(self)(pa_type.storage_type).type
    raise NotImplementedError(pa_type)

@lru_cache(256)
def size_hint(self, expr: sympy.Basic, *, allow_none: bool=False) -> Optional[sympy.Basic]:
    """
        Gets a size hint for a given expression from the underlying shapes we had.
        Does not introduce a guard, so only use this when you can guarantee that
        your code is still valid for arbitrary shapes (such as optimization decisions)
        """
    result_expr = safe_expand(expr).xreplace(self.var_to_val)
    if not result_expr.is_number:
        from torch.utils._sympy.singleton_int import SingletonInt
        if isinstance(result_expr, SingletonInt):
            return None
        r = self._maybe_evaluate_static(result_expr, compute_hint=True)
        if r is not None:
            return r
        if allow_none:
            return None
        if self.oblivious_var_to_val:
            correct_hint = result_expr.xreplace(self.oblivious_var_to_val)
            counterfactual_hint = result_expr.xreplace({k: max(v, 2) for (k, v) in self.oblivious_var_to_val.items()})
            if not correct_hint.free_symbols and (not counterfactual_hint.free_symbols):
                if correct_hint == counterfactual_hint:
                    log.info('oblivious_size hit %s -> %s', expr, correct_hint)
                    return correct_hint
                else:
                    log.info('oblivious_size counterfactual failed %s -> %s != %s', expr, correct_hint, counterfactual_hint)
            else:
                log.info('oblivious_size miss %s -> %s (counterfactual: %s)', expr, correct_hint, counterfactual_hint)
        if self.unbacked_var_to_val:
            unsound_expr = result_expr.xreplace(self.unbacked_var_to_val)
            if <MASK>:
                log.warning('propagate_real_tensors size_hint(%s) -> %s', expr, unsound_expr)
                trace_structured('propagate_real_tensors', metadata_fn=lambda : {'expr': repr(expr), 'result': repr(unsound_expr), 'stack': structured.from_traceback(CapturedTraceback.extract(skip=1).summary())})
                self.guard_or_defer_runtime_assert(sympy.Eq(result_expr, unsound_expr), f'propagate_real_tensors: {result_expr} == {unsound_expr}')
                return unsound_expr
        raise self._make_data_dependent_error(result_expr, expr)
    return result_expr

def go(node, keypath):
    if keypath == ():
        return node
    if len(keypath) >= 2 and isinstance(keypath[0], CallMethodKey) and isinstance(keypath[1], pytree.SequenceKey):
        if keypath[0].name == 'size':
            return go(graph.call_function(torch.ops.aten.sym_size.int, (node, keypath[1].idx)), keypath[2:])
        if keypath[0].name == 'stride':
            return go(graph.call_function(torch.ops.aten.sym_stride.int, (node, keypath[1].idx)), keypath[2:])
        return go(graph.call_method(keypath[0].name, (node, keypath[1].idx)), keypath[2:])
    elif <MASK>:
        if keypath[0].name == 'storage_offset':
            return go(graph.call_function(torch.ops.aten.sym_storage_offset.default, (node,)), keypath[1:])
        return go(graph.call_method(keypath[0].name, (node,)), keypath[1:])
    elif isinstance(keypath[0], pytree.SequenceKey):
        return go(graph.call_function(operator.getitem, (node, keypath[0].idx)), keypath[1:])
    elif isinstance(keypath[0], ConvertIntKey):
        return go(graph.call_function(cast_symbool_to_symint_guardless, (node,)), keypath[1:])
    elif isinstance(keypath[0], DivideByKey):
        return go(graph.call_function(operator.floordiv, (node, keypath[0].divisor)), keypath[1:])
    elif isinstance(keypath[0], InnerTensorKey):
        return go(graph.call_function(getattr, (node, keypath[0].inner_name)), keypath[1:])
    else:
        raise AssertionError(f'unrecognized keypath {keypath}')

def _check_relationship_model(self, from_model=None, **kwargs):
    from django.db.models.fields.composite import CompositePrimaryKey
    if hasattr(self.remote_field.through, '_meta'):
        qualified_model_name = '%s.%s' % (self.remote_field.through._meta.app_label, self.remote_field.through.__name__)
    else:
        qualified_model_name = self.remote_field.through
    errors = []
    if self.remote_field.through not in self.opts.apps.get_models(include_auto_created=True):
        errors.append(checks.Error("Field specifies a many-to-many relation through model '%s', which has not been installed." % qualified_model_name, obj=self, id='fields.E331'))
    else:
        assert from_model is not None, "ManyToManyField with intermediate tables cannot be checked if you don't pass the model where the field is attached to."
        to_model = resolve_relation(from_model, self.remote_field.model)
        from_model_name = from_model._meta.object_name
        if <MASK>:
            to_model_name = to_model
        else:
            to_model_name = to_model._meta.object_name
        if self.remote_field.through_fields is None and (not isinstance(to_model, str)):
            model_name = None
            if isinstance(to_model._meta.pk, CompositePrimaryKey):
                model_name = self.remote_field.model._meta.object_name
            elif isinstance(from_model._meta.pk, CompositePrimaryKey):
                model_name = from_model_name
            if model_name:
                errors.append(checks.Error(f'Field defines a relation involving model {model_name!r} which has a CompositePrimaryKey and such relations are not supported.', obj=self, id='fields.E347'))
        relationship_model_name = self.remote_field.through._meta.object_name
        self_referential = from_model == to_model
        if self_referential:
            seen_self = sum((from_model == getattr(field.remote_field, 'model', None) for field in self.remote_field.through._meta.fields))
            if seen_self > 2 and (not self.remote_field.through_fields):
                errors.append(checks.Error("The model is used as an intermediate model by '%s', but it has more than two foreign keys to '%s', which is ambiguous. You must specify which two foreign keys Django should use via the through_fields keyword argument." % (self, from_model_name), hint='Use through_fields to specify which two foreign keys Django should use.', obj=self.remote_field.through, id='fields.E333'))
        else:
            seen_from = sum((from_model == getattr(field.remote_field, 'model', None) for field in self.remote_field.through._meta.fields))
            seen_to = sum((to_model == getattr(field.remote_field, 'model', None) for field in self.remote_field.through._meta.fields))
            if seen_from > 1 and (not self.remote_field.through_fields):
                errors.append(checks.Error("The model is used as an intermediate model by '%s', but it has more than one foreign key from '%s', which is ambiguous. You must specify which foreign key Django should use via the through_fields keyword argument." % (self, from_model_name), hint='If you want to create a recursive relationship, use ManyToManyField("%s", through="%s").' % (RECURSIVE_RELATIONSHIP_CONSTANT, relationship_model_name), obj=self, id='fields.E334'))
            if seen_to > 1 and (not self.remote_field.through_fields):
                errors.append(checks.Error("The model is used as an intermediate model by '%s', but it has more than one foreign key to '%s', which is ambiguous. You must specify which foreign key Django should use via the through_fields keyword argument." % (self, to_model_name), hint='If you want to create a recursive relationship, use ManyToManyField("%s", through="%s").' % (RECURSIVE_RELATIONSHIP_CONSTANT, relationship_model_name), obj=self, id='fields.E335'))
            if seen_from == 0 or seen_to == 0:
                errors.append(checks.Error("The model is used as an intermediate model by '%s', but it does not have a foreign key to '%s' or '%s'." % (self, from_model_name, to_model_name), obj=self.remote_field.through, id='fields.E336'))
    if self.remote_field.through_fields is not None:
        if not (len(self.remote_field.through_fields) >= 2 and self.remote_field.through_fields[0] and self.remote_field.through_fields[1]):
            errors.append(checks.Error("Field specifies 'through_fields' but does not provide the names of the two link fields that should be used for the relation through model '%s'." % qualified_model_name, hint="Make sure you specify 'through_fields' as through_fields=('field1', 'field2')", obj=self, id='fields.E337'))
        else:
            assert from_model is not None, "ManyToManyField with intermediate tables cannot be checked if you don't pass the model where the field is attached to."
            (source, through, target) = (from_model, self.remote_field.through, self.remote_field.model)
            (source_field_name, target_field_name) = self.remote_field.through_fields[:2]
            for (field_name, related_model) in ((source_field_name, source), (target_field_name, target)):
                possible_field_names = []
                for f in through._meta.fields:
                    if hasattr(f, 'remote_field') and getattr(f.remote_field, 'model', None) == related_model:
                        possible_field_names.append(f.name)
                if possible_field_names:
                    hint = "Did you mean one of the following foreign keys to '%s': %s?" % (related_model._meta.object_name, ', '.join(possible_field_names))
                else:
                    hint = None
                try:
                    field = through._meta.get_field(field_name)
                except exceptions.FieldDoesNotExist:
                    errors.append(checks.Error("The intermediary model '%s' has no field '%s'." % (qualified_model_name, field_name), hint=hint, obj=self, id='fields.E338'))
                else:
                    if not (hasattr(field, 'remote_field') and getattr(field.remote_field, 'model', None) == related_model):
                        related_object_name = related_model if isinstance(related_model, str) else related_model._meta.object_name
                        errors.append(checks.Error("'%s.%s' is not a foreign key to '%s'." % (through._meta.object_name, field_name, related_object_name), hint=hint, obj=self, id='fields.E339'))
    return errors

def check_unspec_python_args(args: Iterable[Any], kwargs: Mapping[Any, Any]) -> bool:
    from .variables.constant import ConstantVariable
    from .variables.tensor import UnspecializedPythonVariable
    unspec_count = 0
    for x in itertools.chain(args, kwargs.values()):
        if <MASK>:
            unspec_count += 1
        elif not isinstance(x, ConstantVariable):
            return False
    return unspec_count > 0

def __init__(self, *expressions, distinct=False, filter=None, default=None, order_by=None, **extra):
    if <MASK>:
        raise TypeError('%s does not allow distinct.' % self.__class__.__name__)
    if order_by and (not self.allow_order_by):
        raise TypeError('%s does not allow order_by.' % self.__class__.__name__)
    if default is not None and self.empty_result_set_value is not None:
        raise TypeError(f'{self.__class__.__name__} does not allow default.')
    self.distinct = distinct
    self.filter = None if filter is None else AggregateFilter(filter)
    self.default = default
    self.order_by = AggregateOrderBy.from_param(f'{self.__class__.__name__}.order_by', order_by)
    super().__init__(*expressions, **extra)

@TorchPatcher.suppress_torch_distributed_warnings
def has_tensor_in_frame(frame: DynamoFrameType) -> bool:
    """Check if the frame has torch.* related bits"""
    if frame.f_code in always_optimize_code_objects:
        return True
    for co_name in frame.f_code.co_names:
        if co_name in frame.f_globals:
            obj = frame.f_globals[co_name]
            if isinstance(obj, ModuleType) and (obj.__name__.startswith('torch.') or obj is torch):
                return True
            if np and config.trace_numpy and (obj is np or is_numpy(obj)):
                return True
    seen_ids: dict[int, bool] = {}

    def has_tensor(obj: object) -> bool:
        """Recursively check if the obj has a tensor"""
        obj_id = id(obj)
        if obj_id in seen_ids:
            return seen_ids[obj_id]
        seen_ids[obj_id] = False
        if <MASK>:
            seen_ids[obj_id] = True
            return seen_ids[obj_id]
        elif config.trace_numpy and np and (istype(obj, np.ndarray) or isinstance(obj, np.generic)):
            seen_ids[obj_id] = True
            return seen_ids[obj_id]
        elif istype(obj, (list, tuple)):
            seen_ids[obj_id] = any((has_tensor(v) for v in obj))
            return seen_ids[obj_id]
        elif istype(obj, dict):
            values = list(obj.values())
            seen_ids[obj_id] = any((has_tensor(v) for v in values))
            return seen_ids[obj_id]
        elif istype(obj, (str, int, float, type(None), bool)):
            seen_ids[obj_id] = False
            return seen_ids[obj_id]
        elif is_namedtuple(obj) and hasattr(obj, '_fields'):
            seen_ids[obj_id] = any((has_tensor(getattr(obj, v)) for v in obj._fields))
            return seen_ids[obj_id]
        else:
            return False
    for value in frame.f_locals.values():
        if has_tensor(value):
            return True
    log.debug('skipping because no torch.* %s             %s %s', frame.f_code.co_name, frame.f_code.co_filename, frame.f_code.co_firstlineno)
    return False

