    else:
        self.on_train_end = lambda logs: None

@ops.RegisterGradient('SparseMatrixSparseMatMul')
def _SparseMatrixSparseMatMulGrad(op: ops.Operation, grad):
    """Gradient for sparse_matrix_sparse_mat_mul op."""
    t_a = op.get_attr('transpose_a')
    t_b = op.get_attr('transpose_b')
    adj_a = op.get_attr('adjoint_a')
    adj_b = op.get_attr('adjoint_b')
    dtype = op.get_attr('type')
    a = op.inputs[0]
    b = op.inputs[1]
    conj = math_ops.conj
    matmul = sparse_csr_matrix_ops.sparse_matrix_sparse_mat_mul
    if not t_a and (not t_b):
        if not adj_a:
            if <MASK>:
                grad_a = matmul(grad, b, adjoint_b=True, type=dtype)
                grad_b = matmul(a, grad, adjoint_a=True, type=dtype)
            else:
                grad_a = matmul(grad, b, type=dtype)
                grad_b = matmul(grad, a, adjoint_a=True, type=dtype)
        elif not adj_b:
            grad_a = matmul(b, grad, adjoint_b=True, type=dtype)
            grad_b = matmul(a, grad, type=dtype)
        else:
            grad_a = matmul(b, grad, adjoint_a=True, adjoint_b=True, type=dtype)
            grad_b = matmul(grad, a, adjoint_a=True, adjoint_b=True, type=dtype)
    elif not adj_a and (not adj_b):
        if not t_a and t_b:
            grad_a = matmul(grad, conj(b), type=dtype)
            grad_b = matmul(grad, conj(a), transpose_a=True, type=dtype)
        elif t_a and (not t_b):
            grad_a = matmul(conj(b), grad, transpose_b=True, type=dtype)
            grad_b = matmul(conj(a), grad, type=dtype)
        else:
            grad_a = matmul(b, grad, adjoint_a=True, transpose_b=True, type=dtype)
            grad_b = matmul(grad, a, transpose_a=True, adjoint_b=True, type=dtype)
    elif adj_a and t_b:
        grad_a = matmul(b, grad, transpose_a=True, adjoint_b=True, type=dtype)
        grad_b = matmul(grad, a, transpose_a=True, transpose_b=True, type=dtype)
    elif t_a and adj_b:
        grad_a = matmul(b, grad, transpose_a=True, transpose_b=True, type=dtype)
        grad_b = matmul(grad, a, adjoint_a=True, transpose_b=True, type=dtype)
    return (_PruneCSRMatrix(grad_a, a), _PruneCSRMatrix(grad_b, b))

@property
def trainable_weights(self):
    if not self._self_trainable:
        return []
    trainable_variables = []
    for obj in self._values:
        if <MASK>:
            trainable_variables += obj.trainable_variables
    trainable_extra_variables = [v for v in self._self_extra_variables if v.trainable]
    return trainable_variables + trainable_extra_variables

def to_json(path_or_buf: FilePath | WriteBuffer[str] | WriteBuffer[bytes] | None, obj: NDFrame, orient: str | None=None, date_format: str='epoch', double_precision: int=10, force_ascii: bool=True, date_unit: str='ms', default_handler: Callable[[Any], JSONSerializable] | None=None, lines: bool=False, compression: CompressionOptions='infer', index: bool | None=None, indent: int=0, storage_options: StorageOptions | None=None, mode: Literal['a', 'w']='w') -> str | None:
    if orient in ['records', 'values'] and index is True:
        raise ValueError("'index=True' is only valid when 'orient' is 'split', 'table', 'index', or 'columns'.")
    elif orient in ['index', 'columns'] and index is False:
        raise ValueError("'index=False' is only valid when 'orient' is 'split', 'table', 'records', or 'values'.")
    elif index is None:
        index = True
    if lines and orient != 'records':
        raise ValueError("'lines' keyword only valid when 'orient' is records")
    if mode not in ['a', 'w']:
        msg = f"mode={mode} is not a valid option.Only 'w' and 'a' are currently supported."
        raise ValueError(msg)
    if mode == 'a' and (not lines or orient != 'records'):
        msg = "mode='a' (append) is only supported when lines is True and orient is 'records'"
        raise ValueError(msg)
    if orient == 'table' and isinstance(obj, Series):
        obj = obj.to_frame(name=obj.name or 'values')
    writer: type[Writer]
    if orient == 'table' and isinstance(obj, DataFrame):
        writer = JSONTableWriter
    elif isinstance(obj, Series):
        writer = SeriesWriter
    elif isinstance(obj, DataFrame):
        writer = FrameWriter
    else:
        raise NotImplementedError("'obj' should be a Series or a DataFrame")
    s = writer(obj, orient=orient, date_format=date_format, double_precision=double_precision, ensure_ascii=force_ascii, date_unit=date_unit, default_handler=default_handler, index=index, indent=indent).write()
    if <MASK>:
        s = convert_to_line_delimits(s)
    if path_or_buf is not None:
        with get_handle(path_or_buf, mode, compression=compression, storage_options=storage_options) as handles:
            handles.handle.write(s)
    else:
        return s
    return None

def numel(self, tx):
    from .builtin import BuiltinVariable
    from .tensor import SymNodeVariable
    const_result = 1
    sym_sizes = []
    for v in self.items:
        if isinstance(v, ConstantVariable):
            const_result *= v.value
        else:
            assert isinstance(v, SymNodeVariable), type(v)
            sym_sizes.append(v)
    result = ConstantVariable.create(const_result)
    if <MASK>:
        (result, *sym_sizes) = sym_sizes
    if not sym_sizes or const_result == 0:
        return result
    mul = BuiltinVariable(operator.mul)
    for v in sym_sizes:
        result = mul.call_function(tx, [result, v], {})
    return result

def assubr(rout):
    if <MASK>:
        fortranname = getfortranname(rout)
        name = rout['name']
        outmess('\t\tCreating wrapper for Fortran function "%s"("%s")...\n' % (name, fortranname))
        rout = copy.copy(rout)
        fname = name
        rname = fname
        if 'result' in rout:
            rname = rout['result']
            rout['vars'][fname] = rout['vars'][rname]
        fvar = rout['vars'][fname]
        if not isintent_out(fvar):
            if 'intent' not in fvar:
                fvar['intent'] = []
            fvar['intent'].append('out')
            flag = 1
            for i in fvar['intent']:
                if i.startswith('out='):
                    flag = 0
                    break
            if flag:
                fvar['intent'].append(f'out={rname}')
        rout['args'][:] = [fname] + rout['args']
        return (rout, createfuncwrapper(rout))
    if issubroutine_wrap(rout):
        fortranname = getfortranname(rout)
        name = rout['name']
        outmess('\t\tCreating wrapper for Fortran subroutine "%s"("%s")...\n' % (name, fortranname))
        rout = copy.copy(rout)
        return (rout, createsubrwrapper(rout))
    return (rout, '')

def widget_attrs(self, widget):
    attrs = super().widget_attrs(widget)
    if isinstance(widget, NumberInput) and 'step' not in widget.attrs:
        if <MASK>:
            step = str(Decimal(1).scaleb(-self.decimal_places)).lower()
        else:
            step = 'any'
        attrs.setdefault('step', step)
    return attrs

def _generate_kernel_call_helper(self, kernel_name: str, call_args: list[str], *, device: Optional[torch.device]=None, triton: bool=True, arg_types: Optional[tuple[Any, ...]]=None, raw_keys: Optional[tuple[Any, ...]]=None, raw_args: Optional[tuple[Any, ...]]=None, triton_meta: Optional[dict[str, Any]]=None, graph_name: str='', original_fxnode_name: Optional[str]=None) -> None:
    """
        Generates MPS kernel call code. It should look something like:
        ```
        auto mps_lib_0_lambda = [&](AOTIMetalKernelFunctionHandle handle) {
            aoti_torch_mps_start_encoding(handle);
            aoti_torch_mps_set_arg_tensor(handle, 0, buf0);
            aoti_torch_mps_set_arg_tensor(handle, 1, arg0_1);
            aoti_torch_mps_set_arg_tensor(handle, 2, arg1_1);
            aoti_torch_mps_dispatch_single(handle, static_cast<uint64_t>(10LL));
        };

        std::function<void(AOTIMetalKernelFunctionHandle)> mps_lib_0_func_wrapper = mps_lib_0_lambda;
        aoti_torch_mps_run_command_block(get_mps_lib_0_handle(), aoti_torch_mps_shared_callback, &mps_lib_0_func_wrapper);
        ```
        """
    device = device or V.graph.get_current_device_or_throw()
    if device.type == 'cpu':
        return CppWrapperCpu._generate_kernel_call_helper(self, kernel_name, call_args, device=device, triton=triton, arg_types=arg_types, raw_keys=raw_keys, raw_args=raw_args, triton_meta=triton_meta)
    assert device.type == 'mps'
    assert arg_types is not None
    new_args = []
    for (idx, (arg, arg_type)) in enumerate(zip(call_args[:-2], arg_types[:-2])):
        if isinstance(arg_type, torch.dtype):
            new_args.append(f'aoti_torch_mps_set_arg_tensor(handle, {idx}, {arg});')
        elif arg_type in (int, sympy.core.symbol.Symbol):
            new_args.append(f'aoti_torch_mps_set_arg_int(handle, {idx}, {arg});')
        else:
            raise NotImplementedError(f'Unsupported arg type {arg_type} for arg {arg} for kernel {kernel_name}')
    (threads, group_size) = (call_args[-2], call_args[-1])
    if threads is None:
        raise NotImplementedError('No threads or group_size provided')
    threads_str = str(threads)
    is_single_value = threads_str.startswith('{') and threads_str.endswith('}') and (threads_str.count(',') == 0) or not threads_str.startswith(('{', '['))
    if is_single_value:
        if threads_str.startswith('{') and threads_str.endswith('}'):
            single_value = threads_str[1:-1].strip()
        else:
            single_value = threads_str
        if group_size is None:
            new_args.append(f'aoti_torch_mps_dispatch_single(handle, {single_value});')
        else:
            group_size_str = str(group_size)
            if group_size_str.startswith('{') and group_size_str.endswith('}'):
                group_size_value = group_size_str[1:-1].strip()
            else:
                group_size_value = group_size_str
            new_args.append(f'aoti_torch_mps_dispatch_single_with_group_size(handle, {single_value}, {group_size_value});')
    else:
        threads_var = f'{kernel_name}_threads_array'
        group_size_var = f'{kernel_name}_group_size_array'

        def get_array_size(array_str: str) -> int:
            content = array_str.strip()
            if content.startswith('{') and content.endswith('}'):
                content = content[1:-1].strip()
            if not content:
                return 0
            depth = 0
            comma_count = 0
            for char in content:
                if char in '({[<':
                    depth += 1
                elif <MASK>:
                    depth -= 1
                elif char == ',' and depth == 0:
                    comma_count += 1
            return comma_count + 1
        threads_size = get_array_size(threads_str)
        if group_size is None:
            new_args.append('{')
            new_args.append(f'    uint64_t {threads_var}[] = {threads};')
            new_args.append(f'    aoti_torch_mps_dispatch_array(handle, {threads_var}, {threads_size});')
            new_args.append('}')
        else:
            group_size_str = str(group_size)
            group_size_size = get_array_size(group_size_str)
            new_args.append('{')
            new_args.append(f'    uint64_t {threads_var}[] = {threads};')
            new_args.append(f'    uint64_t {group_size_var}[] = {group_size};')
            dispatch_args = f'handle, {threads_var}, {threads_size}, {group_size_var}, {group_size_size}'
            new_args.append(f'    aoti_torch_mps_dispatch_array_with_group_size({dispatch_args});')
            new_args.append('}')
    debug_printer_manager = V.graph.wrapper_code.debug_printer
    debug_printer_manager.set_printer_args(call_args[:-2], kernel_name, None, None, 'cpp')
    with debug_printer_manager:
        self.write_mps_kernel_call(kernel_name, new_args)

def main() -> None:
    ref = os.environ['GITHUB_REF']
    m = re.match('^refs/(\\w+)/(.*)$', ref)
    if m:
        (category, stripped) = m.groups()
        if category == 'heads':
            set_output('branch', stripped)
        elif category == 'pull':
            set_output('branch', 'pull/' + stripped.split('/')[0])
        elif <MASK>:
            set_output('tag', stripped)

def _AddMember(member_name, member_obj, proto):
    """Add the child object to the object being constructed."""
    (_, member_obj) = tf_decorator.unwrap(member_obj)
    if <MASK>:
        return
    if member_name == '__init__' or not member_name.startswith('_'):
        if tf_inspect.isroutine(member_obj):
            new_method = proto.member_method.add()
            new_method.name = member_name
            if hasattr(member_obj, '__code__'):
                new_method.argspec = _SanitizedArgSpec(member_obj)
            elif member_name != '__init__' and hasattr(member_obj, '__doc__'):
                doc = member_obj.__doc__
                try:
                    spec_str = _ParseDocstringArgSpec(doc)
                except ValueError:
                    pass
                else:
                    new_method.argspec = spec_str
        else:
            new_member = proto.member.add()
            new_member.name = member_name
            if tf_inspect.ismodule(member_obj):
                new_member.mtype = "<type 'module'>"
            else:
                new_member.mtype = _NormalizeType(str(type(member_obj)))

def _test(self, global_batch_size, num_workers, num_replicas_per_worker, is_batch_size_static):
    """Test that all constraints are met for given parameters."""
    if <MASK>:
        global_batch_size += constant_op.constant(0, dtypes.int64)
    batch_sizes_list = []
    for i in range(num_workers):
        batch_sizes_list.append(self.evaluate(distribute.batch_sizes_for_worker(global_batch_size, num_workers, num_replicas_per_worker, i)))
    for batch_sizes in batch_sizes_list:
        self.assertLen(batch_sizes, num_workers * num_replicas_per_worker)
        self.assertAllEqual(np.sum(batch_sizes), global_batch_size)
    for step_index in range(num_workers):
        actual_global_batch = 0
        offset = step_index * num_replicas_per_worker
        for batch_sizes in batch_sizes_list:
            actual_global_batch += np.sum(batch_sizes[offset:offset + num_replicas_per_worker])
        self.assertAllEqual(global_batch_size, actual_global_batch)
    self.assertLessEqual(np.max(batch_sizes_list) - np.min(batch_sizes_list), 1)

def extract_normalized_read_writes(node: Union['FusedSchedulerNode', 'SchedulerNode']) -> Optional[FusedNormalizedReadsWrites]:
    """Extracts index variables, reduce variables, read/write expressions, and variable ranges from a fused node."""
    reads: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
    writes: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
    all_output_names = node.get_buffer_names()
    op_names = node.get_operation_names()
    outputs: OrderedSet[str] = OrderedSet()
    removed_buffers: OrderedSet[str] = OrderedSet()
    for buf_name in all_output_names:
        if <MASK>:
            removed_buffers.add(buf_name)
        else:
            outputs.add(buf_name)
    inputs = OrderedSet((dep.name for dep in node.read_writes.reads if dep.name not in removed_buffers))
    pointwise_numel: sympy.Expr = node.group[1][0]
    red_numel: sympy.Expr = node.group[1][1]
    if any((isinstance(var, sympy.Expr) and (not var.is_constant()) for var in (pointwise_numel, red_numel))):
        return None
    (pw_splits, red_splits) = NodeSplitGetter(node).get_node_splits()
    ((norm_pw_vars, norm_red_vars), ranges) = index_vars_no_squeeze(pw_splits, red_splits, prefix='n')
    for n in list(node.get_nodes()):
        if not isinstance(n, torch._inductor.scheduler.SchedulerNode):
            continue
        body = n._body
        if body.indirect_vars:
            return None
        n_reads: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
        n_writes: dict[sympy.Expr, OrderedSet[str]] = defaultdict(OrderedSet)
        for inp in inputs:
            for expr in body.get_all_read_expr(inp):
                n_reads[expr].add(inp)
        for out in outputs:
            for expr in body.get_all_write_expr(out):
                n_writes[expr].add(out)
        if not n_reads and (not n_writes):
            continue
        ((iter_vars, n_pw_splits), (red_vars, n_red_splits)) = get_pw_red_splits(n, pointwise_numel, red_numel)
        groups = pw_splits + red_splits
        lengths = (n_pw_splits, n_red_splits)
        lengths = torch._inductor.codegen.simd.SIMDKernel.prepare_split_iteration_lengths(groups, lengths, red_numel)
        (new_ranges, return_getters_groups) = torch._inductor.codegen.simd.SIMDKernel._split_iteration_ranges(groups, lengths)
        var_map = apply_var_mapping(iter_vars, red_vars, norm_pw_vars, norm_red_vars, new_ranges, return_getters_groups)

        def remove_identity(expr: sympy.Expr) -> sympy.Expr:
            return expr.replace(Identity, lambda x: x)
        n_reads_new = {sympy_subs(remove_identity(read), var_map): v for (read, v) in n_reads.items()}
        n_writes_new = {sympy_subs(remove_identity(write), var_map): v for (write, v) in n_writes.items()}
        for (expr, buf_names) in n_reads_new.items():
            reads[expr] |= buf_names
        for (expr, buf_names) in n_writes_new.items():
            writes[expr] |= buf_names
    reads = {V.graph.sizevars.simplify_with_ranges(r, ranges): v for (r, v) in reads.items()}
    writes = {V.graph.sizevars.simplify_with_ranges(w, ranges): v for (w, v) in writes.items()}
    fused_out = FusedNormalizedReadsWrites(norm_pw_vars, norm_red_vars, reads, writes, ranges)
    loop_tiling_log.info('Normalized Fused reads: %s', fused_out)
    return fused_out

def emit_fw_derivatives() -> list[str]:
    content: list[str] = []
    fw_grad_setters: list[str] = []
    for derivative in fw_derivatives:
        res = derivative.var_names
        if f.func.name.name.inplace:
            assert len(res) == 1, 'Expected number of outputs to be 1 if function is inplace'
            res = ('self',)
        assert derivative.required_inputs_fw_grad is not None
        unpacked_arguments = ''
        for inp in differentiable_inputs:
            inp_name = inp.name
            is_input_tensorlist = is_foreach and is_tensor_list_type(inp.type if not inplace else refargname2inplace_foreacharg[inp.name].type)
            input_suffix = '[i]' if is_input_tensorlist else ''
            if is_inplace_foreach:
                if inp.name in refargname2inplace_foreacharg:
                    inp_name = refargname2inplace_foreacharg[inp.name].name
            zeros_fn = 'zeros_symint' if inplace and inp.name == 'self' else '_efficientzerotensor_symint'
            if inp.name in derivative.required_inputs_fw_grad:
                unpacked_arguments += FW_DERIVATIVE_DEFINED_GRAD_TEMPLATE.substitute(inp_name=inp.name, inp=inp_name + input_suffix, zeros_fn=zeros_fn)
            if inp.name in (derivative.required_inputs_primal or []):
                unpacked_arguments += FW_DERIVATIVE_DEFINED_PRIMAL_TEMPLATE.substitute(inp_name=inp.name, inp=inp_name + input_suffix)
        if derivative.required_original_self_value:
            input_suffix = 's[i]' if is_inplace_foreach else ''
            unpacked_arguments += FW_DERIVATIVE_DEFINED_GRAD_TEMPLATE.substitute(inp_name='original_self', inp='original_self' + input_suffix, zeros_fn=zeros_fn)
            unpacked_arguments += FW_DERIVATIVE_DEFINED_PRIMAL_TEMPLATE.substitute(inp_name='original_self', inp='original_self' + input_suffix)
        elif inplace and derivative.is_reusing_outplace_formula:
            unpacked_arguments += 'self_t = GradMode::is_enabled() ? self_t.clone() : self_t;'
        if inplace:
            is_inplace_str = 'true'
        else:
            is_inplace_str = 'false'
        requires_fw_grad = get_any_has_forward_grad_name(derivative.var_names)
        if all((isinstance(var_type, BaseType) and var_type.is_tensor_like() for var_type in derivative.var_types)):
            if len(derivative.var_types) == 1:
                opt_res_grad_type = OptionalCType(BaseCType(tensorT)).cpp_type()
                if <MASK>:
                    fw_grad_setters.append(FW_DERIVATIVE_SETTER_TENSOR.substitute(out_arg=res[0], is_inplace=is_inplace_str))
                else:
                    assert res[0] == ('result' if not inplace else 'self')
                    fw_grad_setters.append(FW_DERIVATIVE_SETTER_TENSOR_FOREACH.substitute(out_arg=res[0], is_inplace=is_inplace_str))
                requires_fw_grad += f' && ({derivative.var_names[0]}.defined())'
            else:
                tuple_type = TupleCType([BaseCType(tensorT)] * len(derivative.var_types))
                opt_res_grad_type = OptionalCType(tuple_type).cpp_type()
                for (idx, single_res) in enumerate(res):
                    fw_grad_setters.append(FW_DERIVATIVE_SETTER_MULTI_OUTPUT.substitute(idx=idx, all_res='_'.join(res), out_arg=single_res))
        elif isinstance(derivative.var_types[0], ListType) and derivative.var_types[0].is_tensor_like():
            assert len(derivative.var_types) == 1, 'Expected number of outputs to be 1 if function returns ListType'
            if not is_foreach:
                opt_res_grad_type = OptionalCType(VectorCType(BaseCType(tensorT))).cpp_type()
                fw_grad_setters.append(FW_DERIVATIVE_SETTER_TENSOR_LIST.substitute(out_arg=res[0], is_inplace=is_inplace_str))
            else:
                opt_res_grad_type = OptionalCType(BaseCType(tensorT)).cpp_type()
                fw_grad_setters.append(FW_DERIVATIVE_SETTER_TENSOR_FOREACH.substitute(out_arg=res[0], is_inplace=is_inplace_str))
        else:
            raise RuntimeError('Unsupported output type for forward derivative')
        if not is_foreach:
            fw_grad_opt_definition = f"{opt_res_grad_type} {'_'.join(res)}_new_fw_grad_opt = ::std::nullopt;"
            content.append(FW_DERIVATIVE_TEMPLATE.substitute(fw_grad_opt_definition=fw_grad_opt_definition, requires_fw_grad=requires_fw_grad, formula=derivative.formula, out_arg='_'.join(res), unpacked_arguments=unpacked_arguments))
        else:
            fw_grad_opt_definition = f"std::vector<{opt_res_grad_type}> {'_'.join(res)}_new_fw_grad_opts(self.size(), ::std::nullopt);"
            foreach_forward_grad_formula = derivative.formula
            _foreach_arg: Argument | DifferentiableInput
            if inplace:
                for (_foreach_arg, _ref_arg) in inplace_foreacharg2refarg.items():
                    if not (is_tensor_type(_foreach_arg.type) or is_tensor_list_type(_foreach_arg.type)):
                        pattern = _foreach_arg.name
                        if isinstance(_foreach_arg.type, ListType):
                            pattern += '[i]'
                        foreach_forward_grad_formula = foreach_forward_grad_formula.replace(_ref_arg.name, pattern)
            elif 'result' in foreach_forward_grad_formula and 'result[i]' not in foreach_forward_grad_formula:
                foreach_forward_grad_formula = foreach_forward_grad_formula.replace('result', 'result[i]')
            content.append(FW_DERIVATIVE_FOREACH_TEMPLATE.substitute(fw_grad_opt_definition=fw_grad_opt_definition, vector_of_optional_tensor=f"{'_'.join(res)}_new_fw_grad_opts", any_has_forward_grad_for_current_index=' || '.join((get_any_has_forward_grad_name(derivative.var_names) + '[i]' for derivative in fw_derivatives)), formula=foreach_forward_grad_formula, unpacked_arguments=unpacked_arguments))
    content.append('\n'.join(fw_grad_setters))
    return content

def _check_related_query_name_is_valid(self):
    if self.remote_field.hidden:
        return []
    rel_query_name = self.related_query_name()
    errors = []
    if <MASK>:
        errors.append(checks.Error("Reverse query name '%s' must not end with an underscore." % rel_query_name, hint='Add or change a related_name or related_query_name argument for this field.', obj=self, id='fields.E308'))
    if LOOKUP_SEP in rel_query_name:
        errors.append(checks.Error("Reverse query name '%s' must not contain '%s'." % (rel_query_name, LOOKUP_SEP), hint='Add or change a related_name or related_query_name argument for this field.', obj=self, id='fields.E309'))
    return errors

def _get_param_key_to_param(optim: torch.optim.Optimizer, model: Optional[nn.Module]=None, is_named_optimizer: bool=False, param_to_fqns: Optional[dict[nn.Parameter, list[str]]]=None, flat_param_to_fqn: Optional[dict[FlatParameter, str]]=None) -> dict[Union[int, str], nn.Parameter]:
    """
    Constructs a mapping from parameter keys to parameters. For the regular
    optimizers, the keys are parameter IDs. For NamedOptimizer, the keys
    are FQNs. This API may be used both for models with ``FlatParameter`` s and
    without.
    """
    clean_fqn_to_curr_fqn: dict[str, str] = {}
    if is_named_optimizer:
        if param_to_fqns is None or flat_param_to_fqn is None:
            raise AssertionError('The optimizer is a NamedOptimizer, `param_to_fqns` must not be None.')
        if model is None:
            raise AssertionError(f'Expected model to be not None, got {model}')
        for (key, _) in _named_parameters_with_duplicates(model):
            clean_fqn_to_curr_fqn[clean_tensor_name(key)] = key
    param_key_to_param: dict[Union[str, int], nn.Parameter] = {}
    pid = 0
    for param_group in optim.param_groups:
        if is_named_optimizer:
            for param in param_group['params']:
                if flat_param_to_fqn is None:
                    raise AssertionError(f'Expected flat_param_to_fqn to be not None, got {flat_param_to_fqn}')
                if <MASK>:
                    key = flat_param_to_fqn[param]
                else:
                    if param_to_fqns is None:
                        raise AssertionError(f'Expected param_to_fqns to be not None, got {param_to_fqns}')
                    if len(param_to_fqns[param]) != 1:
                        raise AssertionError(f'Expected len(param_to_fqns[param]) == 1, got {len(param_to_fqns[param])}')
                    key = param_to_fqns[param][0]
                try:
                    key = clean_fqn_to_curr_fqn[key]
                except KeyError as e:
                    raise KeyError(f"Can't find {key} from {list(clean_fqn_to_curr_fqn.keys())}.") from e
                param_key_to_param[key] = param
        else:
            for param in param_group['params']:
                param_key_to_param[pid] = param
                pid += 1
    return param_key_to_param

def is_bf16_supported(including_emulation: bool=True):
    """Return a bool indicating if the current CUDA/ROCm device supports dtype bfloat16."""
    if torch.version.hip:
        return True
    if not is_available():
        return False
    device = torch.cuda.current_device()
    cuda_version = torch.version.cuda
    if cuda_version is not None and torch.cuda.get_device_properties(device).major >= 8:
        return True
    if <MASK>:
        return False
    return _check_bf16_tensor_supported(device)

def _convert_container(container, constructor_name, columns_name=None, dtype=None, minversion=None, categorical_feature_names=None):
    """Convert a given container to a specific array-like with a dtype.

    Parameters
    ----------
    container : array-like
        The container to convert.
    constructor_name : {"list", "tuple", "array", "sparse", "dataframe",             "pandas", "series", "index", "slice", "sparse_csr", "sparse_csc",             "sparse_csr_array", "sparse_csc_array", "pyarrow", "polars",             "polars_series"}
        The type of the returned container.
    columns_name : index or array-like, default=None
        For pandas/polars container supporting `columns_names`, it will affect
        specific names.
    dtype : dtype, default=None
        Force the dtype of the container. Does not apply to `"slice"`
        container.
    minversion : str, default=None
        Minimum version for package to install.
    categorical_feature_names : list of str, default=None
        List of column names to cast to categorical dtype.

    Returns
    -------
    converted_container
    """
    if constructor_name == 'list':
        if dtype is None:
            return list(container)
        else:
            return np.asarray(container, dtype=dtype).tolist()
    elif constructor_name == 'tuple':
        if dtype is None:
            return tuple(container)
        else:
            return tuple(np.asarray(container, dtype=dtype).tolist())
    elif constructor_name == 'array':
        return np.asarray(container, dtype=dtype)
    elif constructor_name in ('pandas', 'dataframe'):
        pd = pytest.importorskip('pandas', minversion=minversion)
        result = pd.DataFrame(container, columns=columns_name, dtype=dtype, copy=False)
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result[col_name] = result[col_name].astype('category')
        return result
    elif constructor_name == 'pyarrow':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        array = np.asarray(container)
        array = array[:, None] if array.ndim == 1 else array
        if columns_name is None:
            columns_name = [f'col{i}' for i in range(array.shape[1])]
        data = {name: array[:, i] for (i, name) in enumerate(columns_name)}
        result = pa.Table.from_pydict(data)
        if categorical_feature_names is not None:
            for (col_idx, col_name) in enumerate(result.column_names):
                if col_name in categorical_feature_names:
                    result = result.set_column(col_idx, col_name, result.column(col_name).dictionary_encode())
        return result
    elif constructor_name == 'polars':
        pl = pytest.importorskip('polars', minversion=minversion)
        result = pl.DataFrame(container, schema=columns_name, orient='row')
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result = result.with_columns(pl.col(col_name).cast(pl.Categorical))
        return result
    elif constructor_name == 'series':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Series(container, dtype=dtype)
    elif constructor_name == 'pyarrow_array':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        return pa.array(container)
    elif constructor_name == 'polars_series':
        pl = pytest.importorskip('polars', minversion=minversion)
        return pl.Series(values=container)
    elif constructor_name == 'index':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Index(container, dtype=dtype)
    elif constructor_name == 'slice':
        return slice(container[0], container[1])
    elif 'sparse' in constructor_name:
        if not sp.sparse.issparse(container):
            container = np.atleast_2d(container)
        if constructor_name in ('sparse', 'sparse_csr'):
            return sp.sparse.csr_matrix(container, dtype=dtype)
        elif <MASK>:
            return sp.sparse.csr_array(container, dtype=dtype)
        elif constructor_name == 'sparse_csc':
            return sp.sparse.csc_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csc_array':
            return sp.sparse.csc_array(container, dtype=dtype)

def sample_inputs_sparse_elementwise_binary_operation(op_info, device, dtype, requires_grad, layout, **kwargs):
    """Sample inputs for elementwise binary operations on sparse tensors.

    The samples include regular, zero-sized, batched, and hybrid
    sparse tensors as well as rhs scalars. All tensors are full tensors.
    """

    def _to_sparse(tensor, **kwargs):
        return tensor.detach().to_sparse(**kwargs).requires_grad_(requires_grad)
    for sample_input in generate_elementwise_binary_tensors(op_info, device=device, dtype=dtype, requires_grad=requires_grad, exclude_zero=True, **kwargs):
        (lhs, rhs) = (sample_input.input, sample_input.args[0])
        min_dense_dim = 0
        max_dense_dim = lhs.ndim - 1
        if layout in {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}:
            if lhs.ndim < 2:
                continue
            max_dense_dim = lhs.ndim - 2
        for dense_dim in range(min_dense_dim, max_dense_dim + 1):
            if layout in {torch.sparse_bsr, torch.sparse_bsc}:
                blocksizes = [(1, 1)]
                if <MASK>:
                    blocksizes.append((lhs.shape[lhs.ndim - 2 - dense_dim], lhs.shape[lhs.ndim - 1 - dense_dim]))
            else:
                blocksizes = [None]
            for blocksize in blocksizes:
                to_sparse_kwargs = dict(layout=layout, dense_dim=dense_dim, blocksize=blocksize)
                lhs_sparse = _to_sparse(lhs, **to_sparse_kwargs)
                rhs_sparse = _to_sparse(rhs, **to_sparse_kwargs)
                yield SampleInput(lhs_sparse, args=(rhs_sparse, *sample_input.args[1:]), kwargs=sample_input.kwargs)
                yield SampleInput(lhs_sparse, args=(make_tensor((), dtype=dtype, device=device, requires_grad=requires_grad), *sample_input.args[1:]), kwargs=sample_input.kwargs)

def check_layer(self):
    """
        Check the Layer metadata and ensure that it's compatible with the
        mapping information and model. Unlike previous revisions, there is no
        need to increment through each feature in the Layer.
        """
    self.geom_field = False
    self.fields = {}
    ogr_fields = self.layer.fields
    ogr_field_types = self.layer.field_types

    def check_ogr_fld(ogr_map_fld):
        try:
            idx = ogr_fields.index(ogr_map_fld)
        except ValueError:
            raise LayerMapError('Given mapping OGR field "%s" not found in OGR Layer.' % ogr_map_fld)
        return idx
    for (field_name, ogr_name) in self.mapping.items():
        try:
            model_field = self.model._meta.get_field(field_name)
        except FieldDoesNotExist:
            raise LayerMapError('Given mapping field "%s" not in given Model fields.' % field_name)
        fld_name = model_field.__class__.__name__
        if isinstance(model_field, GeometryField):
            if self.geom_field:
                raise LayerMapError('LayerMapping does not support more than one GeometryField per model.')
            coord_dim = model_field.dim
            try:
                if <MASK>:
                    gtype = OGRGeomType(ogr_name + '25D')
                else:
                    gtype = OGRGeomType(ogr_name)
            except GDALException:
                raise LayerMapError('Invalid mapping for GeometryField "%s".' % field_name)
            ltype = self.layer.geom_type
            if not (ltype.name.startswith(gtype.name) or self.make_multi(ltype, model_field)):
                raise LayerMapError('Invalid mapping geometry; model has %s%s, layer geometry type is %s.' % (fld_name, '(dim=3)' if coord_dim == 3 else '', ltype))
            self.geom_field = field_name
            self.coord_dim = coord_dim
            fields_val = model_field
        elif isinstance(model_field, models.ForeignKey):
            if isinstance(ogr_name, dict):
                rel_model = model_field.remote_field.model
                for (rel_name, ogr_field) in ogr_name.items():
                    idx = check_ogr_fld(ogr_field)
                    try:
                        rel_model._meta.get_field(rel_name)
                    except FieldDoesNotExist:
                        raise LayerMapError('ForeignKey mapping field "%s" not in %s fields.' % (rel_name, rel_model.__class__.__name__))
                fields_val = rel_model
            else:
                raise TypeError('ForeignKey mapping must be of dictionary type.')
        else:
            if model_field.__class__ not in self.FIELD_TYPES:
                raise LayerMapError('Django field type "%s" has no OGR mapping (yet).' % fld_name)
            idx = check_ogr_fld(ogr_name)
            ogr_field = ogr_field_types[idx]
            if not issubclass(ogr_field, self.FIELD_TYPES[model_field.__class__]):
                raise LayerMapError('OGR field "%s" (of type %s) cannot be mapped to Django %s.' % (ogr_field, ogr_field.__name__, fld_name))
            fields_val = model_field
        self.fields[field_name] = fields_val

def _cancel_all_tasks(loop: AbstractEventLoop, tasks: OrderedSet[Future]) -> None:
    to_cancel = [task for task in tasks if not task.done()]
    if <MASK>:
        return
    for task in to_cancel:
        task.cancel()
    loop.run_until_complete(asyncio.gather(*to_cancel, return_exceptions=True))
    for task in to_cancel:
        if task.cancelled():
            continue
        if task.exception() is not None:
            loop.call_exception_handler({'message': 'unhandled exception during asyncio.run() shutdown', 'exception': task.exception(), 'task': task})

@_onnx_symbolic('aten::upsample_nearest1d', decorate=[symbolic_helper._apply_params('upsample_nearest1d', 3, 'nearest')])
@_onnx_symbolic('aten::upsample_nearest2d', decorate=[symbolic_helper._apply_params('upsample_nearest2d', 4, 'nearest')])
@_onnx_symbolic('aten::upsample_nearest3d', decorate=[symbolic_helper._apply_params('upsample_nearest3d', 5, 'nearest')])
