def _write_row(self, row: list[str | float | None]) -> None:
    filename = self.output_filename()
    if self.num_rows_added == 0 and (not os.path.exists(filename)):
        self.write_header()
    self.num_rows_added += 1
    for (idx, orig_val) in enumerate(row):
        if <MASK>:
            new_val = f'{orig_val:.6f}'
        elif orig_val is None:
            new_val = ''
        else:
            new_val = orig_val
        row[idx] = new_val
    with open(filename, 'a') as fd:
        writer = csv.writer(fd, lineterminator='\n')
        writer.writerow(row)

@register_lowering(aten.mm, type_promotion_kind=None)
def tuned_mm(mat1, mat2, out_dtype=None, *, layout=None):
    """
    Lowering for autotuning aten.mm with different backends (Aten, Triton, CUTLASS, etc.)
    """
    if <MASK>:
        input_dtype = mat1.get_dtype()
        torch._check(mat2.get_dtype() == input_dtype, lambda : 'input dtypes must be the same')
        torch._check(mat1.get_device().type == 'cuda', lambda : 'out_dtype is only supported for CUDA')
        torch._check(out_dtype == input_dtype or (out_dtype == torch.float32 and input_dtype in (torch.float16, torch.bfloat16)), lambda : 'out_dtype must be the same as input dtype or fp32 for fp16/bf16 inputs')
    if use_native_matmul(mat1, mat2):
        mat1 = lowerings[aten.unsqueeze](mat1, -1)
        mat2 = lowerings[aten.unsqueeze](mat2, 0)
        (args, kwargs) = transform_args(args=[mat1, mat2], kwargs={}, broadcast=True, type_promotion_kind=None, convert_input_to_bool=False)
        if inductor_config.triton.codegen_upcast_to_fp32 and mat1.dtype in [torch.float16, torch.bfloat16]:

            def _to_dtype(x):
                return ops.to_dtype(x, mat1.dtype, use_compute_types=False)
            args = [make_pointwise(_to_dtype)(x) for x in args]
        mul_pointwise = make_pointwise(ops.dot)(*args)
        dot_reduction = make_reduction('dot')(mul_pointwise, 1)
        return dot_reduction
    (m, n, k, layout, mat1, mat2) = mm_args(mat1, mat2, layout=layout, out_dtype=out_dtype)
    (static_shape, is_nonzero) = _is_static_problem(layout)
    name = 'mm'
    kernel_inputs = MMKernelInputs([mat1, mat2], out_dtype=out_dtype)
    counters['aten_mm_info'][f'aten.mm_{m}_{n}_{k}'] += 1
    log.info('Tuned aten.mm: m=%s, n=%s, k=%s, mat1_dtype=%s, mat2_dtype=%s, output_layout=%s', m, n, k, mat1.get_dtype(), mat2.get_dtype(), layout)
    choices: list[ChoiceCaller] = []
    (static_shape, is_nonzero) = _is_static_problem(layout)
    aten_handler: ExternKernelChoice = aten_mm
    aten_extra_kwargs: dict[str, Any] = {}
    if out_dtype is not None:
        aten_handler = aten_mm_dtype
        aten_extra_kwargs = {'out_dtype': out_dtype}
    templates_to_use: list[Union[ExternKernelChoice, KernelTemplate]] = []
    kwarg_overrides: dict[str, dict[str, Any]] = {}
    if use_aten_gemm_kernels():
        templates_to_use.append(aten_handler)
        if aten_extra_kwargs:
            kwarg_overrides[aten_handler.uid] = aten_extra_kwargs
    if out_dtype is None and is_nonzero and use_triton_template(layout, check_max_autotune=True):
        if use_decompose_k_choice(m, n, k):
            templates_to_use.append(decompose_k_subgraph_template)
        is_exhaustive = inductor_config.max_autotune_gemm_search_space == 'exhaustive'
        if is_exhaustive or not use_decompose_k_choice(m, n, k, threshold_multiple=2):
            templates_to_use.append(mm_template)
            if use_triton_tma_template(mat1, mat2, output_layout=layout):
                templates_to_use.append(persistent_tma_mm_template)
            if use_triton_blackwell_tma_template(mat1, mat2, output_layout=layout):
                templates_to_use.append(blackwell_ws_persistent_device_tma_mm_template)
        templates_to_use.append(mm_contiguous_subgraph_template)
    choices.extend(V.choices.get_template_configs(kernel_inputs, templates_to_use, 'mm', kwarg_overrides=kwarg_overrides))
    if out_dtype is None and is_nonzero and use_cutlass_template(layout, m, n, k) and _use_cutlass_for_op('mm'):
        CUTLASS3xGemmTemplate.add_cutlass_gemm_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and is_nonzero and use_ck_gemm_template(layout, m, n, k):
        CKGemmTemplate.add_ck_gemm_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and is_nonzero and use_ck_tile_gemm_template(layout, m, n, k):
        CKTileGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    if out_dtype is None and use_cpp_gemm_template(layout, mat1, mat2):
        CppGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes())
    input_nodes = [mat1, mat2]
    if out_dtype is None and is_nonzero and use_triton_template(layout) and torch._inductor.config.run_autoheuristic(name) and is_triton(mat1):
        always_included = []
        if use_aten_gemm_kernels():
            always_included.append('extern_mm')
        num_choices_before_extra_configs = len(choices)
        choices.extend(V.choices.get_template_configs(kernel_inputs, [mm_template], 'mm-ah'))
        ah_choices = mm_autoheuristic(mat1, mat2, m, n, k, choices, name, input_nodes, mm_operations(), None, top_k=10, always_included=always_included)
        if not torch._inductor.config.collect_autoheuristic(name):
            if ah_choices is not None and len(ah_choices) > 0:
                choices = [choice for choice in choices if choice in ah_choices]
            else:
                choices = choices[:num_choices_before_extra_configs]
    if out_dtype is None:
        for k in inductor_config.external_matmul:
            choices.append(lazy_register_extern_choice(k).bind(kernel_inputs.nodes(), layout))
    best_config_future = None
    if out_dtype is None and torch._inductor.config.remote_gemm_autotune_cache:
        best_config_future = gen_best_config(mat1, mat2)
    return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout, best_config_future=best_config_future)

@final
def _validate_key_length(self, key: tuple) -> tuple:
    if <MASK>:
        if key[0] is Ellipsis:
            key = key[1:]
            if Ellipsis in key:
                raise IndexingError(_one_ellipsis_message)
            return self._validate_key_length(key)
        raise IndexingError('Too many indexers')
    return key

def _select_data(self) -> DataFrame:
    """Select columns to be described."""
    if self.include is None and self.exclude is None:
        default_include: list[npt.DTypeLike] = [np.number, 'datetime']
        data = self.obj.select_dtypes(include=default_include)
        if len(data.columns) == 0:
            data = self.obj
    elif <MASK>:
        if self.exclude is not None:
            msg = "exclude must be None when include is 'all'"
            raise ValueError(msg)
        data = self.obj
    else:
        data = self.obj.select_dtypes(include=self.include, exclude=self.exclude)
        if len(data.columns) == 0:
            msg = 'No columns match the specified include or exclude data types'
            raise ValueError(msg)
    return data

def _get_inputs_and_attributes(node: torch.fx.Node) -> tuple[list[torch.fx.Node | None], dict[str, Any], list[str], list[str]]:
    """Find and Fill in the not provided kwargs with default values.

    Returns:
        (inputs, attributes, input_names, output_names)
    """
    if inspect.isbuiltin(node.target) or isinstance(node.target, str):
        inputs = list(node.args)
        return (inputs, {}, [], [node.name])
    assert hasattr(node.target, '_schema'), f'The target should be an ATen operator now, but node target {node.target} has no schema'
    node_schema: torch.FunctionSchema = node.target._schema
    inputs: list[Any] = []
    input_names: list[str] = []
    attributes: dict[str, Any] = {}
    if <MASK>:
        inputs = list(node.args)
    else:
        for (arg, schema_arg) in zip(node.args, node_schema.arguments):
            if arg is None or isinstance(arg, torch.fx.Node):
                inputs.append(arg)
                input_names.append(schema_arg.name)
            elif isinstance(arg, Sequence) and all((elem is None or isinstance(elem, torch.fx.Node) for elem in arg)):
                inputs.extend(arg)
                input_names.extend([schema_arg.name] * len(arg))
            elif isinstance(arg, torch.device):
                attributes[schema_arg.name] = str(arg)
            elif isinstance(arg, torch.dtype):
                attributes[schema_arg.name] = torch_dtype_to_onnx_dtype(arg)
            else:
                attributes[schema_arg.name] = arg
        for schema_arg in node_schema.arguments:
            if schema_arg.name not in node.kwargs:
                continue
            kwarg = node.kwargs[schema_arg.name]
            if schema_arg.name in {'layout', 'device', 'requires_grad', 'memory_format', 'implicit'} or isinstance(kwarg, torch.device):
                attr = str(kwarg)
            elif isinstance(kwarg, torch.dtype):
                attr = torch_dtype_to_onnx_dtype(kwarg)
            else:
                attr = kwarg
            attributes[schema_arg.name] = attr
    output_names = [f'{node.name}_{output.name}' for output in node_schema.returns]
    return (inputs, attributes, input_names, output_names)

def _testBinaryOp(self, math_fun, np_fun, name, operands=None, extra_operands=None, check_promotion=True, check_promotion_result_type=True):

    def run_test(a, b):
        for fn in self.array_transforms:
            arg1 = fn(a)
            arg2 = fn(b)
            self.match(math_fun(arg1, arg2), np_fun(arg1, arg2), msg='{}({}, {})'.format(name, arg1, arg2))
        for type_a in self.types:
            for type_b in self.types:
                if <MASK>:
                    continue
                arg1 = np_array_ops.array(a, dtype=type_a)
                arg2 = np_array_ops.array(b, dtype=type_b)
                self.match(math_fun(arg1, arg2), np_fun(arg1, arg2), msg='{}({}, {})'.format(name, arg1, arg2), check_dtype=check_promotion_result_type)
    if operands is None:
        operands = [(5, 2), (5, [2, 3]), (5, [[2, 3], [6, 7]]), ([1, 2, 3], 7), ([1, 2, 3], [5, 6, 7])]
    for (operand1, operand2) in operands:
        run_test(operand1, operand2)
    if extra_operands is not None:
        for (operand1, operand2) in extra_operands:
            run_test(operand1, operand2)

def __init__(self, callable, ctx=None, **kwargs):
    if <MASK>:
        self.ctx = {'operations': [], 'variables': []}
    else:
        self.ctx = ctx
    self.kwargs = kwargs
    self.callable = callable

def _GetDenseDimensions(list_of_lists):
    """Returns the inferred dense dimensions of a list of lists."""
    if not isinstance(list_of_lists, (list, tuple)):
        return []
    elif <MASK>:
        return [0]
    else:
        return [len(list_of_lists)] + _GetDenseDimensions(list_of_lists[0])

def _convert_to_indexer(self, key, axis: AxisInt):
    """
        Convert indexing key into something we can use to do actual fancy
        indexing on a ndarray.

        Examples
        ix[:5] -> slice(0, 5)
        ix[[1,2,3]] -> [1,2,3]
        ix[['foo', 'bar', 'baz']] -> [i, j, k] (indices of foo, bar, baz)

        Going by Zen of Python?
        'In the face of ambiguity, refuse the temptation to guess.'
        raise AmbiguousIndexError with integer labels?
        - No, prefer label-based indexing
        """
    labels = self.obj._get_axis(axis)
    if isinstance(key, slice):
        return labels._convert_slice_indexer(key, kind='loc')
    if isinstance(key, tuple) and (not isinstance(labels, MultiIndex)) and (self.ndim < 2) and (len(key) > 1):
        raise IndexingError('Too many indexers')
    contains_slice = False
    if <MASK>:
        contains_slice = any((isinstance(v, slice) for v in key))
    if is_scalar(key) or (isinstance(labels, MultiIndex) and is_hashable(key) and (not contains_slice)):
        try:
            return labels.get_loc(key)
        except LookupError:
            if isinstance(key, tuple) and isinstance(labels, MultiIndex):
                if len(key) == labels.nlevels:
                    return {'key': key}
                raise
        except InvalidIndexError:
            if not isinstance(labels, MultiIndex):
                raise
        except ValueError:
            if not is_integer(key):
                raise
            return {'key': key}
    if is_nested_tuple(key, labels):
        if self.ndim == 1 and any((isinstance(k, tuple) for k in key)):
            raise IndexingError('Too many indexers')
        return labels.get_locs(key)
    elif is_list_like_indexer(key):
        if is_iterator(key):
            key = list(key)
        if com.is_bool_indexer(key):
            key = check_bool_indexer(labels, key)
            return key
        else:
            return self._get_listlike_indexer(key, axis)[1]
    else:
        try:
            return labels.get_loc(key)
        except LookupError:
            if not is_list_like_indexer(key):
                return {'key': key}
            raise

def to_list(self):
    """Convert tuple to a list where None is always first."""
    output = []
    if <MASK>:
        output.append(None)
    if self.nan:
        output.append(np.nan)
    return output

def call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if self.value is itertools.product:
        if any((kw != 'repeat' for kw in kwargs.keys())):
            unimplemented_v2(gb_type='Unsupported kwargs for itertools.product', context=f'call_function {self} {args} {kwargs}', explanation=f"Expected kwargs: 'repeat', but got {','.join(set(kwargs.keys()) - {'repeat'})}", hints=[*graph_break_hints.USER_ERROR])
        if <MASK>:
            r = kwargs['repeat'].as_python_constant()
        else:
            r = 1
        seqs = [arg.force_unpack_var_sequence(tx) for arg in args]
        items = [variables.TupleVariable(list(item)) for item in itertools.product(*seqs, repeat=r)]
        return variables.ListIteratorVariable(items, mutation_type=ValueMutationNew())
    elif self.value is itertools.combinations and (not kwargs) and (len(args) == 2) and args[0].has_unpack_var_sequence(tx) and args[1].is_python_constant():
        iterable = args[0].unpack_var_sequence(tx)
        r = args[1].as_python_constant()
        items = []
        for item in itertools.combinations(iterable, r):
            items.append(variables.TupleVariable(list(item)))
        return variables.ListIteratorVariable(items, mutation_type=ValueMutationNew())
    elif self.value is itertools.groupby:
        if any((kw != 'key' for kw in kwargs.keys())):
            unimplemented_v2(gb_type='Unsupported kwargs for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f"Expected kwargs: 'key', but got {','.join(set(kwargs.keys()) - {'key'})}", hints=[*graph_break_hints.USER_ERROR])

        def retrieve_const_key(key):
            if isinstance(key, variables.SymNodeVariable):
                return key.evaluate_expr()
            elif isinstance(key, variables.ConstantVariable):
                return key.as_python_constant()
            else:
                unimplemented_v2(gb_type='Unsupported key type for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace itertools.groupby with key type: {str(type(key))}. We only support grouping keys that are constants (int, float, str, etc.)', hints=[*graph_break_hints.SUPPORTABLE])
        if len(args) == 1 and args[0].has_unpack_var_sequence(tx):
            seq = args[0].unpack_var_sequence(tx)
        else:
            unimplemented_v2(gb_type='Unsupported arguments for itertools.groupby', context=f'call_function {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace itertools.groupby with args: {args} and kwargs: {kwargs}. itertools.groupby expects an iterable to group and an optional key function to determine groupings.', hints=['Make sure the arguments to itertools.groupby are correct.', *graph_break_hints.SUPPORTABLE])
        if 'key' in kwargs:

            def keyfunc(x):
                return retrieve_const_key(kwargs.get('key').call_function(tx, [x], {}))
        else:

            def keyfunc(x):
                return retrieve_const_key(x)
        result = []
        try:
            for (k, v) in itertools.groupby(seq, key=keyfunc):
                result.append(variables.TupleVariable([variables.ConstantVariable.create(k) if variables.ConstantVariable.is_literal(k) else k, variables.ListIteratorVariable(list(v), mutation_type=ValueMutationNew())], mutation_type=ValueMutationNew()))
        except Exception as e:
            unimplemented_v2(gb_type='Unexpected failure during itertools.groupby() iteration', context=f'call_function {self} {args} {kwargs}', explanation='Unexpected failure in invoking function during groupby', hints=[*graph_break_hints.SUPPORTABLE], from_exc=e)
        return variables.ListIteratorVariable(result, mutation_type=ValueMutationNew())
    elif self.value is itertools.repeat:
        if len(args) < 2:
            return variables.RepeatIteratorVariable(*args, mutation_type=ValueMutationNew())
        return tx.inline_user_function_return(VariableTracker.build(tx, polyfills.repeat), args, kwargs)
    elif self.value is itertools.count:
        return variables.CountIteratorVariable(*args, mutation_type=ValueMutationNew())
    elif self.value is itertools.permutations and (len(args) == 1 or (len(args) == 2 and args[1].is_python_constant())) and (not kwargs):
        if len(args) == 2:
            r = args[1].as_python_constant()
        else:
            r = None
        items = [variables.TupleVariable(list(item)) for item in itertools.permutations(args[0].force_unpack_var_sequence(tx), r)]
        return variables.ListIteratorVariable(items, mutation_type=ValueMutationNew())
    else:
        return super().call_function(tx, args, kwargs)

