    array_np = _convert_to_numpy(array, xp=xp)
    return [element.item() for element in array_np]

def skipIfRocmVersionLessThan(version=None):

    def dec_fn(fn):

        @wraps(fn)
        def wrap_fn(self, *args, **kwargs):
            if TEST_WITH_ROCM:
                rocm_version_tuple = getRocmVersion()
                if <MASK>:
                    reason = f'ROCm {rocm_version_tuple} is available but {version} required'
                    raise unittest.SkipTest(reason)
            return fn(self, *args, **kwargs)
        return wrap_fn
    return dec_fn

@classmethod
@register_pandas_matplotlib_converters
def _plot(cls, ax: Axes, x, y: np.ndarray, style=None, is_errorbar: bool=False, **kwds):
    mask = isna(y)
    if mask.any():
        y = np.ma.array(y)
        y = np.ma.masked_where(mask, y)
    if isinstance(x, ABCIndex):
        x = x._mpl_repr()
    if is_errorbar:
        if 'xerr' in kwds:
            kwds['xerr'] = np.array(kwds.get('xerr'))
        if <MASK>:
            kwds['yerr'] = np.array(kwds.get('yerr'))
        return ax.errorbar(x, y, **kwds)
    else:
        args = (x, y, style) if style is not None else (x, y)
        return ax.plot(*args, **kwds)

def check_for_mutation_ignore_cuda_graph_managed_tensor(gm: torch.fx.GraphModule, mutated_inputs: OrderedSet[str], mutated_input_idxs: OrderedSet[int], static_input_idxs: Sequence[int]) -> Optional[str]:
    default_msg = format_default_skip_message('mutated inputs')
    if <MASK>:
        unique_idxs = OrderedSet(static_input_idxs)
        mutation_indices = [idx for idx in mutated_input_idxs if idx not in unique_idxs]
        has_mutation = len(mutation_indices) != 0
        if not has_mutation:
            return None
        placeholders = get_placeholder_info(gm.graph)
        return get_mutation_stack_trace(placeholders, mutation_indices)
    else:
        has_mutation = len(mutated_inputs) != 0
        return None if not has_mutation else default_msg

def helper(treespec: TreeSpec, tree: PyTree, subtrees: list[PyTree]) -> None:
    if treespec.is_leaf():
        subtrees.append(tree)
        return
    node_type = _get_node_type(tree)
    if treespec.type not in BUILTIN_TYPES:
        if node_type != treespec.type:
            raise ValueError(f'Type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
        (children, context) = flatten_fn(tree)
        if len(children) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(children)}.')
        if <MASK>:
            raise ValueError(f'Node context mismatch for custom node type {treespec.type!r}.')
    else:
        both_standard_dict = treespec.type in STANDARD_DICT_TYPES and node_type in STANDARD_DICT_TYPES
        if not both_standard_dict and node_type != treespec.type:
            raise ValueError(f'Node type mismatch; expected {treespec.type!r}, but got {node_type!r}.')
        if len(tree) != treespec.num_children:
            raise ValueError(f'Node arity mismatch; expected {treespec.num_children}, but got {len(tree)}.')
        if both_standard_dict:
            dict_context = treespec.context if treespec.type is not defaultdict else treespec.context[1]
            expected_keys = dict_context
            got_key_set = set(tree)
            expected_key_set = set(expected_keys)
            if got_key_set != expected_key_set:
                missing_keys = expected_key_set.difference(got_key_set)
                extra_keys = got_key_set.difference(expected_key_set)
                message = ''
                if missing_keys:
                    message += f'; missing key(s): {missing_keys}'
                if extra_keys:
                    message += f'; extra key(s): {extra_keys}'
                raise ValueError(f'Node keys mismatch{message}.')
            children = [tree[key] for key in expected_keys]
        else:
            flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
            (children, context) = flatten_fn(tree)
            if node_type is not deque and context != treespec.context:
                raise ValueError(f'Node context mismatch for node type {treespec.type!r}; expected {treespec.context!r}, but got {context!r}.')
    for (subtree, subspec) in zip(children, treespec.children_specs):
        helper(subspec, subtree, subtrees)

def __lt__(self, other):
    if isinstance(other, Expr):
        if self.op is not other.op:
            return self.op.value < other.op.value
        if self.op in (Op.TERMS, Op.FACTORS):
            return tuple(sorted(self.data.items())) < tuple(sorted(other.data.items()))
        if <MASK>:
            if self.data[:2] != other.data[:2]:
                return self.data[:2] < other.data[:2]
            return tuple(sorted(self.data[2].items())) < tuple(sorted(other.data[2].items()))
        return self.data < other.data
    return NotImplemented

@_lru_cache
def simplify(self, expr: _SympyT, size_oblivious: bool=False) -> _SympyT:
    """Use known constraints and replacements to simplify the given expr"""
    expr = safe_expand(expr)
    expr = self.replace(expr)
    if not size_oblivious:
        min_max_replacements = {}
        for atom in expr.atoms(Max):
            if len(atom.args) > 2:
                continue
            (a, b) = atom.args
            if b == 1 or b == 0:
                (a, b) = (b, a)
            if a == 1 and self._maybe_evaluate_static(sympy.Ge(b, 1)):
                min_max_replacements[atom] = b
            if <MASK>:
                min_max_replacements[atom] = b
        if min_max_replacements:
            expr = expr.xreplace(min_max_replacements)
    if expr.has(TruncToInt):
        trunc_replacements = {}
        for atom in expr.atoms(TruncToInt):
            if isinstance(atom.args[0], IntTrueDiv):
                (base, divisor) = atom.args[0].args
                if base % divisor == 0:
                    trunc_replacements[atom] = CleanDiv(base, divisor)
                else:
                    trunc_replacements[atom] = FloorDiv(base, divisor)
        if trunc_replacements:
            expr = expr.xreplace(trunc_replacements)
    if expr.has(FloorDiv):
        self._update_divisible()
        div_replacements = {}
        for atom in expr.atoms(FloorDiv):
            (base, divisor) = atom.args
            if isinstance(divisor, FloorDiv):
                (base1, divisor1) = divisor.args
                if self.replace(Mod(base, divisor)) in self.divisible and base == base1 and (self.replace(Mod(base1, divisor1)) in self.divisible):
                    div_replacements[atom] = divisor1
        if div_replacements:
            expr = expr.xreplace(div_replacements)
            expr = safe_expand(expr)
    if expr.has(FloorDiv):
        div_replacements = {}
        pows = expr.atoms(sympy.Pow)
        rationals = expr.atoms(sympy.Rational).difference(expr.atoms(sympy.Integer))
        for fd in expr.atoms(FloorDiv):
            (base, divisor) = fd.args
            if self.replace(Mod(base, divisor)) in self.divisible:
                div_replacements[fd] = CleanDiv(base, divisor)
        if div_replacements:
            new_expr = expr.xreplace(div_replacements)
            new_expr = safe_expand(new_expr)
            new_pows = new_expr.atoms(sympy.Pow)
            new_rationals = new_expr.atoms(sympy.Rational).difference(new_expr.atoms(sympy.Integer))
            if new_pows.issubset(pows) and new_rationals.issubset(rationals):
                expr = new_expr
    return expr

@register_lowering(aten.addmm, type_promotion_kind=None)
def tuned_addmm(inp, mat1, mat2, *, alpha=1, beta=1, layout=None):
    """
    Lowering for autotuning aten.addmm with different backends (Aten, Triton, CUTLASS, etc.)
    """
    if use_native_matmul(mat1, mat2):
        if beta == 0:
            arg1 = 0
        else:
            arg1 = lowerings[aten.mul](beta, inp)
        if alpha == 0:
            arg2 = 0
        else:
            arg2 = lowerings[aten.mul](alpha, lowerings[aten.mm](mat1, mat2))
        return lowerings[aten.add](arg1, arg2)
    (m, n, k, layout, mat1, mat2, inp_expanded) = mm_args(mat1, mat2, inp, layout=layout)
    (static_shape, is_nonzero) = _is_static_problem(layout)
    name = 'addmm'
    kernel_inputs = MMKernelInputs([inp_expanded, mat1, mat2], scalars=dict(alpha=alpha, beta=beta))
    choices: list[ChoiceCaller] = []
    counters['aten_mm_info'][f'aten.addmm_{m}_{n}_{k}'] += 1
    log.info('Tuned aten.addmm: m=%s, n=%s, k=%s, mat1_dtype=%s, mat2_dtype=%s, output_layout=%s', m, n, k, mat1.get_dtype(), mat2.get_dtype(), layout)
    if not is_nonzero or not (inductor_config.max_autotune or inductor_config.max_autotune_gemm):
        kernel_inputs = MMKernelInputs([inp, mat1, mat2], scalars=dict(alpha=alpha, beta=beta))
        choices.extend(V.choices.get_template_configs(kernel_inputs, [aten_addmm], name))
        return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout)
    templates_to_use: list[Union[ExternKernelChoice, KernelTemplate]] = []
    if use_aten_gemm_kernels():
        templates_to_use.extend([aten_bias_addmm, aten_addmm])
    if is_nonzero and use_triton_template(layout, check_max_autotune=False):
        templates_to_use.append(mm_template)
        if use_triton_tma_template(mat1, mat2, output_layout=layout):
            templates_to_use.append(persistent_tma_mm_template)
        if use_triton_blackwell_tma_template(mat1, mat2, output_layout=layout):
            templates_to_use.append(blackwell_ws_persistent_device_tma_mm_template)
        templates_to_use.append(addmm_contiguous_subgraph_template)
    choices.extend(V.choices.get_template_configs(kernel_inputs, templates_to_use, name))
    if is_nonzero and use_cutlass_template(layout, m, n, k) and _use_cutlass_for_op(name):
        CUTLASS3xGemmTemplate.add_cutlass_gemm_choices(choices, layout, kernel_inputs.nodes(reorder=[1, 2, 0]), alpha=alpha, beta=beta)
    if <MASK>:
        CKGemmTemplate.add_ck_gemm_choices(choices, layout, kernel_inputs.nodes(reorder=[1, 2, 0]), alpha=alpha, beta=beta, input_reorder=[2, 0, 1])
    if use_cpp_gemm_template(layout, mat1, mat2):
        CppGemmTemplate.add_choices(choices, layout, kernel_inputs.nodes(), alpha=alpha, beta=beta, has_bias=True)
    return autotune_select_algorithm(name, choices, kernel_inputs.nodes(), layout)

def _traverse_obj(path: OBJ_PATH, value: STATE_DICT_ITEM) -> None:
    if <MASK>:
        visitor(path, value)
    elif isinstance(value, Mapping):
        for (k, v) in value.items():
            _traverse_obj(path + (str(k),), v)
    elif isinstance(value, list):
        for (i, v) in enumerate(value):
            _traverse_obj(path + (i,), v)

@dispatch.add_dispatch_support
@doc_controls.do_not_generate_docs
def batch_normalization(x, mean, var, beta, gamma, axis=-1, epsilon=0.001):
    """Applies batch normalization on x given mean, var, beta and gamma.

  I.e. returns:
  `output = (x - mean) / (sqrt(var) + epsilon) * gamma + beta`

  Args:
      x: Input tensor or variable.
      mean: Mean of batch.
      var: Variance of batch.
      beta: Tensor with which to center the input.
      gamma: Tensor by which to scale the input.
      axis: Integer, the axis that should be normalized.
          (typically the features axis).
      epsilon: Fuzz factor.

  Returns:
      A tensor.
  """
    if ndim(x) == 4:
        if axis == 1 or axis == -3:
            tf_data_format = 'NCHW'
        elif axis == 3 or axis == -1:
            tf_data_format = 'NHWC'
        else:
            tf_data_format = None
        if tf_data_format == 'NHWC' or (tf_data_format == 'NCHW' and _has_nchw_support()):
            if ndim(mean) > 1:
                mean = array_ops.reshape(mean, [-1])
            if ndim(var) > 1:
                var = array_ops.reshape(var, [-1])
            if <MASK>:
                beta = zeros_like(mean)
            elif ndim(beta) > 1:
                beta = array_ops.reshape(beta, [-1])
            if gamma is None:
                gamma = ones_like(mean)
            elif ndim(gamma) > 1:
                gamma = array_ops.reshape(gamma, [-1])
        (y, _, _) = nn.fused_batch_norm(x, gamma, beta, epsilon=epsilon, mean=mean, variance=var, data_format=tf_data_format, is_training=False)
        return y
    return nn.batch_normalization(x, mean, var, beta, gamma, epsilon)

def _create_storer(self, group, format=None, value: DataFrame | Series | None=None, encoding: str='UTF-8', errors: str='strict') -> GenericFixed | Table:
    """return a suitable class to operate"""
    cls: type[GenericFixed | Table]
    if value is not None and (not isinstance(value, (Series, DataFrame))):
        raise TypeError('value must be None, Series, or DataFrame')
    pt = getattr(group._v_attrs, 'pandas_type', None)
    tt = getattr(group._v_attrs, 'table_type', None)
    if pt is None:
        if value is None:
            _tables()
            assert _table_mod is not None
            if getattr(group, 'table', None) or isinstance(group, _table_mod.table.Table):
                pt = 'frame_table'
                tt = 'generic_table'
            else:
                raise TypeError('cannot create a storer if the object is not existing nor a value are passed')
        else:
            if isinstance(value, Series):
                pt = 'series'
            else:
                pt = 'frame'
            if format == 'table':
                pt += '_table'
    if 'table' not in pt:
        _STORER_MAP = {'series': SeriesFixed, 'frame': FrameFixed}
        try:
            cls = _STORER_MAP[pt]
        except KeyError as err:
            raise TypeError(f'cannot properly create the storer for: [_STORER_MAP] [group->{group},value->{type(value)},format->{format}') from err
        return cls(self, group, encoding=encoding, errors=errors)
    if tt is None:
        if value is not None:
            if pt == 'series_table':
                index = getattr(value, 'index', None)
                if index is not None:
                    if index.nlevels == 1:
                        tt = 'appendable_series'
                    elif <MASK>:
                        tt = 'appendable_multiseries'
            elif pt == 'frame_table':
                index = getattr(value, 'index', None)
                if index is not None:
                    if index.nlevels == 1:
                        tt = 'appendable_frame'
                    elif index.nlevels > 1:
                        tt = 'appendable_multiframe'
    _TABLE_MAP = {'generic_table': GenericTable, 'appendable_series': AppendableSeriesTable, 'appendable_multiseries': AppendableMultiSeriesTable, 'appendable_frame': AppendableFrameTable, 'appendable_multiframe': AppendableMultiFrameTable, 'worm': WORMTable}
    try:
        cls = _TABLE_MAP[tt]
    except KeyError as err:
        raise TypeError(f'cannot properly create the storer for: [_TABLE_MAP] [group->{group},value->{type(value)},format->{format}') from err
    return cls(self, group, encoding=encoding, errors=errors)

def reducer_override(self, obj: Any) -> Union[tuple[Callable[..., Any], tuple[Any, ...]], Any]:
    import sympy
    if id(obj) in self.empty_values:
        return (type(obj).__new__, (type(obj),))
    if id(obj) in self.missing_values:
        return (_Missing, ('missing values',))
    if isinstance(obj, torch.Tensor) and obj.device.type != 'meta':
        from torch.utils._python_dispatch import is_traceable_wrapper_subclass
        if id(obj) not in self.guard_tree_values:
            return (_Missing, ('tensor guard tree',))
        if is_traceable_wrapper_subclass(obj):
            inner_data = []
            (attrs, ctx) = obj.__tensor_flatten__()
            for attr in attrs:
                inner = getattr(obj, attr)
                if isinstance(inner, torch.Tensor):
                    self.guard_tree_values[id(inner)] = inner
                (func, args_tuple) = self.reducer_override(inner)
                inner_data.append((attr, func, args_tuple))
            return (type(self)._unpickle_traceable_wrapper_subclass, (torch.empty_like(obj, device='meta'), obj.device, type(obj), torch._C._dispatch_keys(obj).raw_repr(), ctx, inner_data))
        return (type(self)._unpickle_tensor, (torch.empty_like(obj, device='meta', requires_grad=obj.requires_grad), obj.device, type(obj), torch._C._dispatch_keys(obj).raw_repr(), obj.grad))
    elif isinstance(obj, torch.nn.Module):
        if id(obj) not in self.guard_tree_values:
            return (_Missing, ('module guard tree',))
        if isinstance(obj, torch.nn.parallel.DistributedDataParallel):
            return (type(self)._unpickle_ddp_module, (obj.__getstate__(),))
        if type(obj).__qualname__ == type(obj).__name__:
            return NotImplemented
        if obj.__class__.__getstate__ == torch.nn.Module.__getstate__:
            return (type(self)._unpickle_module, (obj.__getstate__(),))
    elif inspect.ismodule(obj):
        return (type(self)._unpickle_python_module, (obj.__name__,))
    elif isinstance(obj, torch._C.DispatchKeySet):
        return (type(self)._unpickle_dispatch_key_set, (obj.raw_repr(),))
    elif isinstance(obj, torch._C._functorch.CInterpreter):
        return (type(self)._unpickle_functorch_interpreter, (obj.serialize(),))
    elif inspect.isclass(obj) and issubclass(obj, sympy.Function) and hasattr(obj, '_torch_handler_name'):
        assert hasattr(obj, '_torch_unpickler')
        return (obj._torch_unpickler, (obj._torch_handler_name,))
    elif isinstance(obj, torch.SymInt):
        raise RuntimeError(f'Cannot serialize SymInt {obj} (node: {obj.node})')
    elif isinstance(obj, types.MappingProxyType):
        return (type(self)._unpickle_mapping_proxy, (obj.copy(),))
    elif isinstance(obj, torch._dynamo.utils.dict_keys):
        return (type(self)._unpickle_dict_keys, (list(obj),))
    elif isinstance(obj, torch._ops.OpOverloadPacket) and obj._qualified_op_name.startswith('_C::'):
        return (type(self)._unpickle_c_op, (obj.__name__,))
    elif obj.__class__.__module__ == 'builtins' and obj.__class__.__name__ == 'PyCapsule':
        return (_Missing, ('capsule',))
    elif isinstance(obj, _get_unsupported_types()):
        return (_Missing, ('unsupported',))
    elif inspect.isfunction(obj):
        if obj.__code__.co_flags & inspect.CO_NESTED:
            return (_Missing, ('nested function',))
        if obj.__module__ in sys.modules:
            f = sys.modules[obj.__module__]
            for name in obj.__qualname__.split('.'):
                f = getattr(f, name, None)
            if f is not obj:
                return (_Missing, ('fqn mismatch',))
    elif inspect.ismethod(obj):
        func = obj.__func__
        method_self = obj.__self__
        inner_func = getattr(method_self, func.__name__)
        if inspect.ismethod(inner_func):
            inner_func = inner_func.__func__
        if func is not inner_func:
            return (type(self)._unpickle_bound_method, (func, method_self))
    elif isinstance(obj, type((lambda x: lambda : x)(0).__closure__[0])):
        return (type(self)._unpickle_cell, (obj.cell_contents,))
    if hasattr(torch.distributed, 'distributed_c10d') and isinstance(obj, torch.distributed.distributed_c10d.Work):
        if id(obj) not in self.guard_tree_values:
            return (_Missing, ('distributed_c10d.Work',))
    if <MASK>:
        raise torch._dynamo.exc.PackageError(f'Type {type(obj)} for object {obj} cannot be saved ' + "into torch.compile() package since it's defined in local scope. " + 'Please define the class at global scope (top level of a module).')
    if inspect.isclass(obj) and hasattr(torch.distributed, 'fsdp') and issubclass(obj, torch.distributed.fsdp._fully_shard.FSDPModule):
        if obj is not torch.distributed.fsdp._fully_shard.FSDPModule:
            original_type = obj.__mro__[2]
            assert issubclass(original_type, torch.nn.Module)
            assert original_type in torch.distributed.fsdp._fully_shard._fully_shard.get_cls_to_fsdp_cls()
            return (type(self)._unpickle_fsdp_module_type, (original_type,))
    return NotImplemented

def coalesce(layout: Layout, profile: LayoutProfile=None) -> Layout:
    if is_tuple(profile):
        assert len(layout) >= len(profile)
        return make_layout(chain((coalesce(layout[i], profile[i]) for i in range(len(profile))), (layout[i] for i in range(len(profile), len(layout)))))
    result_shape = [1]
    result_stride = [0]
    for (shape, stride) in zip(reversed(flatten(layout.shape)), reversed(flatten(layout.stride))):
        if shape == 1:
            continue
        elif result_shape[-1] == 1:
            result_shape[-1] = shape
            result_stride[-1] = stride
        elif <MASK>:
            result_shape[-1] = result_shape[-1] * shape
        else:
            result_shape.append(shape)
            result_stride.append(stride)
    if len(result_shape) == 1:
        return Layout(result_shape[0], result_stride[0])
    else:
        result_shape.reverse()
        result_stride.reverse()
        return Layout(tuple(result_shape), tuple(result_stride))

