    x = self.bijector.inverse(y)
    return self.distribution.survival_function(x)

def as_signature_def(self, receiver_tensors):
    if <MASK>:
        raise ValueError(f'Regression signatures can only accept a single tensor input of type tf.string. Please check to make sure that you have structured the serving_input_receiver_fn so that it creates a single string placeholder. If your model function expects multiple inputs, then use `tf.io.parse_example()` to parse the string into multiple tensors.\n Received: {receiver_tensors}')
    ((_, examples),) = receiver_tensors.items()
    if dtypes.as_dtype(examples.dtype) != dtypes.string:
        raise ValueError(f'Regression signatures can only accept a single tensor input of type tf.string. Please check to make sure that you have structured the serving_input_receiver_fn so that it creates a single string placeholder. If your model function expects multiple inputs, then use `tf.io.parse_example()` to parse the string into multiple tensors.\n Received: {receiver_tensors}')
    return signature_def_utils.regression_signature_def(examples, self.value)

@final
def _cast_types(self, values: ArrayLike, cast_type: DtypeObj, column) -> ArrayLike:
    """
        Cast values to specified type

        Parameters
        ----------
        values : ndarray or ExtensionArray
        cast_type : np.dtype or ExtensionDtype
           dtype to cast values to
        column : string
            column name - used only for error reporting

        Returns
        -------
        converted : ndarray or ExtensionArray
        """
    if isinstance(cast_type, CategoricalDtype):
        known_cats = cast_type.categories is not None
        if not is_object_dtype(values.dtype) and (not known_cats):
            values = lib.ensure_string_array(values, skipna=False, convert_na_value=False)
        cats = Index(values).unique().dropna()
        values = Categorical._from_inferred_categories(cats, cats.get_indexer(values), cast_type, true_values=self.true_values)
    elif isinstance(cast_type, ExtensionDtype):
        array_type = cast_type.construct_array_type()
        try:
            if <MASK>:
                values_str = [str(val) for val in values]
                return array_type._from_sequence_of_strings(values_str, dtype=cast_type, true_values=self.true_values, false_values=self.false_values, none_values=self.na_values)
            else:
                return array_type._from_sequence_of_strings(values, dtype=cast_type)
        except NotImplementedError as err:
            raise NotImplementedError(f'Extension Array: {array_type} must implement _from_sequence_of_strings in order to be used in parser methods') from err
    elif isinstance(values, ExtensionArray):
        values = values.astype(cast_type, copy=False)
    elif issubclass(cast_type.type, str):
        values = lib.ensure_string_array(values, skipna=True, convert_na_value=False)
    else:
        try:
            values = astype_array(values, cast_type, copy=True)
        except ValueError as err:
            raise ValueError(f'Unable to convert column {column} to type {cast_type}') from err
    return values

@tf_export('__internal__.tracking.streaming_restore', v1=[])
def streaming_restore(status, session=None):
    """When graph building, runs restore ops as soon as they come in.

  Args:
    status: A _LoadStatus objects from an object-based saver's restore().
      Streaming restore from name-based checkpoints is not currently supported.
    session: A session to run new restore ops in.
  """
    if context.executing_eagerly():
        return
    if <MASK>:
        session = get_session()
    if isinstance(status, NameBasedSaverStatus):
        raise NotImplementedError('Streaming restore not supported from name-based checkpoints when graph building. File a feature request if this limitation bothers you. As a workaround, consider either using tf.train.Checkpoint to load name-based checkpoints or enabling eager execution.')
    status.run_restore_ops(session=session)
    status._checkpoint.new_restore_ops_callback = lambda ops: session.run(ops, feed_dict=status._feed_dict)

def _persistent_id(self, obj):
    if <MASK>:
        storage: Storage
        if isinstance(obj, torch.storage.TypedStorage):
            untyped_storage = obj._untyped_storage
            storage_type_str = obj.pickle_storage_type()
            storage_type = getattr(torch, storage_type_str)
            storage = cast(Storage, untyped_storage)
            storage_numel = obj.size()
        elif isinstance(obj, torch.UntypedStorage):
            untyped_storage = obj
            storage = cast(Storage, untyped_storage)
            storage_type = normalize_storage_type(type(storage))
            storage_numel = storage.nbytes()
        else:
            raise RuntimeError(f'storage type not recognized: {type(obj)}')
        location = location_tag(storage)
        storage_present = self.storage_context.has_storage(storage)
        storage_id = self.storage_context.get_or_add_storage(storage)
        if not storage_present:
            if storage.device.type != 'cpu':
                storage = storage.cpu()
            num_bytes = storage.nbytes()
            self.zip_file.write_record(f'.data/{storage_id}.storage', storage, num_bytes)
        return ('storage', storage_type, storage_id, location, storage_numel)
    if hasattr(obj, '__reduce_package__'):
        if _gate_torchscript_serialization and isinstance(obj, torch.jit.RecursiveScriptModule):
            raise Exception('Serializing ScriptModules directly into a package is a beta feature. To use, set global `torch.package.package_exporter._gate_torchscript_serialization` to `False`.')
        if self.serialized_reduces.get(id(obj)) is None:
            self.serialized_reduces[id(obj)] = ('reduce_package', id(obj), *obj.__reduce_package__(self))
        return self.serialized_reduces[id(obj)]
    return None

@classmethod
def process_subsystem(cls, curr_backend: str, curr_subsystem: Subsystem, fn: Callable[[], bool], cli_interface: bool=True) -> bool:
    """
        Process the current subsystem. Returns True if the issue is found, False otherwise.
        """
    assert isinstance(curr_subsystem, Subsystem)
    while True:
        run_state = cls.get_run_state(curr_backend, curr_subsystem.name)
        reset_counters()
        if run_state == 'test_disable':
            if not fn():
                next_subsystem = cls.advance_subsystem(curr_backend, curr_subsystem)
                if not next_subsystem:
                    return False
                curr_subsystem = next_subsystem
            else:
                if isinstance(curr_subsystem, ConfigChange):
                    print(f'Setting config {curr_subsystem.config_name} field {curr_subsystem.config_field} to {curr_subsystem.config_value} fixed the issue')
                else:
                    print(f'Disabling {curr_subsystem.name} fixed the issue.')
                if isinstance(curr_subsystem, BinarySubsystem):
                    return True
                print('Starting bisect by getting upper bound.')
                cls.update_run_state(curr_backend, curr_subsystem, 'find_max_bounds')
        elif <MASK>:
            if fn():
                raise RuntimeError(f"Function succeeded with 'find_max_bounds' status for {curr_backend} - {curr_subsystem.name}.")
            else:
                (_, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
                print(f'Upper bound of {high} found for {curr_backend}.')
                cls.update_run_state(curr_backend, curr_subsystem, 'bisect')
        elif run_state == 'bisect':
            (low, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
            midpoint = (low + high) // 2
            print(f'Bisecting {curr_backend} - {curr_subsystem.name} (Range: [{low}, {high}], Midpoint: {midpoint})')
            if fn():
                cls.update_bisect_range(curr_backend, curr_subsystem.name, midpoint + 1, high)
            else:
                cls.update_bisect_range(curr_backend, curr_subsystem.name, low, midpoint)
            (low, high) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
            if low == high:
                print(f"Binary search completed for {curr_backend} - {curr_subsystem.name}. The bisect number is {low}. Debug info: {call_counter_debug_info.get(low, 'not found')}")
                return True
        else:
            raise RuntimeError(f'Unexpected run_state {run_state}')
        if cli_interface:
            sys.exit(0)

def get_nop_func() -> Callable[[torch.fx.GraphModule, list[torch.Tensor]], Callable[..., Any]]:
    if not torch._functorch.config.fake_tensor_crossref:
        return boxed_nop
    elif <MASK>:
