@invoke_subgraph.py_impl(ProxyTorchDispatchMode)
def _(proxy_mode: ProxyTorchDispatchMode, subgraph, identifier, *operands):
    graph = None
    invoke_subgraph_cache = get_invoke_subgraph_cache()
    if invoke_subgraph_cache:
        graph = invoke_subgraph_cache.get_proxy_dispatch_entry(identifier)
    if graph is None:
        from torch._dynamo.utils import dynamo_timed
        with dynamo_timed('invoke_subgraph_proxy_tensor', log_pt2_compile_event=True):
            graph = reenter_make_fx(subgraph)(*operands)
        from torch._guards import detect_fake_mode
        fake_mode = detect_fake_mode(operands)
        assert fake_mode is not None and fake_mode.shape_env is not None
        insert_deferred_runtime_asserts(graph, fake_mode.shape_env, 'invoke_subgraph_proxy_torch_dispatch_mode', export=True)
        graph.recompile()
        assert isinstance(proxy_mode.tracer, torch.fx.Tracer)
        if invoke_subgraph_cache:
            invoke_subgraph_cache.add_proxy_dispatch_entry(identifier, graph)
    node_args = (graph, identifier, *operands)

    def _unwrap_proxy(arg):
        if isinstance(arg, torch.fx.GraphModule):
            registered_before = False
            for (_, submod) in proxy_mode.tracer.root.named_modules():
                if arg is submod:
                    registered_before = True
            if <MASK>:
                qualname = proxy_mode.tracer.get_fresh_qualname('repeated_subgraph')
                proxy_mode.tracer.root.register_module(qualname, arg)
        return proxy_mode.tracer.unwrap_proxy(arg)
    proxy_args = pytree.tree_map(_unwrap_proxy, node_args)
    out_proxy = proxy_mode.tracer.create_proxy('call_function', invoke_subgraph, proxy_args, {})
    example_out = invoke_subgraph(graph, identifier, *operands)
    return track_tensor_tree(example_out, out_proxy, constant=None, tracer=proxy_mode.tracer)

def wrap_compiler_debug(unconfigured_compiler_fn: _CompileFxCallable, compiler_name: str) -> _CompileFxCallable:
    """
    Minifier for Fx Graph modules after Aot Autograd has finished. We wrap both
    forward and backward call separately with the backend compiler_fn - like
    inductor or nvfuser. Intercepting after Aot Autograd presents neat
    abstraction, where all the params are lifted as graph inputs, making it easy
    to save the graph as a string.
    """

    @functools.wraps(unconfigured_compiler_fn)
    def debug_wrapper(gm: torch.fx.GraphModule, example_inputs: Sequence[InputType], **kwargs: Unpack[_CompileFxKwargs]) -> OutputCode:
        from torch._subclasses import FakeTensorMode
        compiler_fn = functools.partial(unconfigured_compiler_fn, **kwargs)
        from torch._functorch.aot_autograd import get_aot_graph_name
        graph_name = get_aot_graph_name()
        orig_graph = copy.deepcopy(gm.graph)
        assert config.repro_after in ('dynamo', 'aot', None)
        try:
            inner_compiled_fn = compiler_fn(gm, example_inputs)
        except Exception:
            if config.repro_after == 'aot':
                if config.repro_level == 1:
                    dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), example_inputs, compiler_name)
                elif config.repro_level == 2:
                    dump_to_minify(fx.GraphModule(gm, orig_graph), example_inputs, compiler_name)
                log.error('CompilerError')
            raise

        def deferred_for_real_inputs(real_inputs: Sequence[InputType], **_kwargs: object) -> Any:
            assert not _kwargs
            if config.repro_after != 'aot':
                assert not isinstance(inner_compiled_fn, str)
                return inner_compiled_fn(real_inputs)
            with config.patch(repro_after=None):
                return inner_debug_fn(real_inputs)

        def inner_debug_fn(real_inputs: Sequence[InputType]) -> Any:
            """
            Aot Autograd fw_compiler and bw_compiler can have fake tensors. So,
            example_inputs can be fake tensors. We can call compiler_fn (which is
            inductor or nvfuser) with fake tensors but the actually compiled_fn
            should be called with real tensors. Therefore, the actual invocation
            is deferred.
            """
            fake_mode = FakeTensorMode()
            copy_tensor_attrs = [fake_mode.from_tensor(x) if isinstance(x, torch.Tensor) else x for x in real_inputs]
            if config.repro_level == 3:
                dump_to_minify(fx.GraphModule(gm, orig_graph), real_inputs, compiler_name)
            if <MASK>:
                if compiler_name != 'inductor':
                    raise NotImplementedError('Accuracy minification is supported for inductor only')
                failed = not same_two_models(gm, inner_compiled_fn, real_inputs, only_fwd=True, ignore_non_fp=config.repro_ignore_non_fp)
                if failed:
                    log.warning('Accuracy failed for the AOT Autograd graph %s', graph_name)
                    dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), real_inputs, f'{compiler_name}_accuracy')
                    dump_to_minify(fx.GraphModule(gm, orig_graph), real_inputs, f'{compiler_name}_accuracy')
                    raise AccuracyError('Bad accuracy detected')
                else:
                    return inner_compiled_fn(real_inputs)
            else:
                try:
                    out = inner_compiled_fn(real_inputs)
                    for arg in example_inputs:
                        if isinstance(arg, torch.Tensor) and arg.is_cuda:
                            torch.cuda.synchronize()
                            break
                    return out
                except Exception:
                    if config.repro_level == 1:
                        dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), copy_tensor_attrs, compiler_name)
                    elif config.repro_level == 2:
                        dump_to_minify(fx.GraphModule(gm, orig_graph), copy_tensor_attrs, compiler_name)
                    raise
        if config.repro_after == 'aot':
            compiled_fn = deferred_for_real_inputs
            compiled_fn._boxed_call = True
            return compiled_fn
        else:
            return inner_compiled_fn
    return debug_wrapper

def __call__(self, module: nn.Module) -> PassResult:
    """
        Runs a list of passes in the order based on `self.passes` on the given
        graph module. Each time a pass is run, checks and linting will be run on
        the graph module if `run_checks_after_each_pass` is set.

        If the module is a graph module, we will run the list of passes until
        the graph stops changing, or until `steps` number of times.
        """
    if not self._validated:
        self.solve_constraints()
    self.check(module)
    overall_modified = False
    for _ in range(self.steps):
        modified = False
        for (i, fn) in enumerate(self.passes):
            fn_name = fn.__name__ if inspect.isfunction(fn) else type(fn).__name__
            logger.debug("Running pass '%s'", fn_name)
            try:
                res = fn(module)
                if <MASK>:
                    raise TypeError(f'The result of the pass {fn_name} should be type PassResult.' + 'Please wrap it with pass_result_wrapper()')
                module = res.graph_module
                modified = modified or res.modified
                if isinstance(module, GraphModule):
                    logger.debug("Graph after pass '%s': %s", fn_name, module.graph)
                    module.recompile()
                if self.run_checks_after_each_pass:
                    self.check(module)
            except Exception as e:
                prev_pass_names = [p.__name__ if inspect.isfunction(p) else type(p).__name__ for p in self.passes[:i]]
                msg = f"An error occurred when running the '{fn_name}' pass after the following passes: {prev_pass_names}"
                raise Exception(msg) from e
        overall_modified = overall_modified or modified
        if not modified:
            break
    return PassResult(module, overall_modified)

def is_non_default(param_name, param_value):
    """Finds the parameters that have been set by the user."""
    if param_name not in init_default_params:
        return True
    if <MASK>:
        return True
    if isinstance(param_value, BaseEstimator) and type(param_value) is not type(init_default_params[param_name]):
        return True
    if is_pandas_na(param_value) and (not is_pandas_na(init_default_params[param_name])):
        return True
    if not np.array_equal(param_value, init_default_params[param_name]) and (not (is_scalar_nan(init_default_params[param_name]) and is_scalar_nan(param_value))):
        return True
    return False

def system_specific_test_config(environ_cp):
    """Add default build and test flags required for TF tests to bazelrc."""
    write_to_bazelrc('test --test_size_filters=small,medium')
    test_and_build_filters = ['-benchmark-test', '-no_oss', '-oss_excluded']
    test_only_filters = ['-oss_serial']
    if <MASK>:
        test_and_build_filters += ['-no_windows', '-windows_excluded']
        if environ_cp.get('TF_NEED_CUDA', None) == '1' or environ_cp.get('TF_NEED_ROCM', None) == '1':
            test_and_build_filters += ['-no_windows_gpu', '-no_gpu']
        else:
            test_and_build_filters.append('-gpu')
    elif is_macos():
        test_and_build_filters += ['-gpu', '-nomac', '-no_mac', '-mac_excluded']
    elif is_linux():
        if environ_cp.get('TF_NEED_CUDA', None) == '1' or environ_cp.get('TF_NEED_ROCM', None) == '1':
            test_and_build_filters.append('-no_gpu')
            write_to_bazelrc('test --test_env=LD_LIBRARY_PATH')
        else:
            test_and_build_filters.append('-gpu')
    write_to_bazelrc('test:v1 --test_tag_filters=%s' % ','.join(test_and_build_filters + test_only_filters))
    write_to_bazelrc('test:v1 --build_tag_filters=%s' % ','.join(test_and_build_filters))
    write_to_bazelrc('test:v2 --test_tag_filters=%s' % ','.join(test_and_build_filters + test_only_filters + ['-v1only']))
    write_to_bazelrc('test:v2 --build_tag_filters=%s' % ','.join(test_and_build_filters + ['-v1only']))

def model_training_evaluation(backend, train_dataloader, eval_dataloader, model, optimizer, num_epochs, evaluation):
    model.to(device)
    model.train()
    loss_history = []
    if not backend:
        opt_training_iter_fn = training_iter_fn
    else:
        opt_training_iter_fn = torch._dynamo.optimize(backend)(training_iter_fn)
    for epoch in range(num_epochs):
        running_loss = 0.0
        for (i, batch) in enumerate(train_dataloader, 0):
            batch = {k: v.to(device) for (k, v) in batch.items()}
            loss = opt_training_iter_fn(batch, model, optimizer)
            running_loss += loss.item()
            if <MASK>:
                loss_history.append(running_loss / 100)
                running_loss = 0.0
    if evaluation:
        metric = load_metric('accuracy')
        model.eval()
        if not backend:
            opt_model = model
        else:
            opt_model = torch._dynamo.optimize(backend)(model)
        for batch in eval_dataloader:
            batch = {k: v.to(device) for (k, v) in batch.items()}
            with torch.no_grad():
                outputs = opt_model(**batch)
            logits = outputs.logits
            predictions = torch.argmax(logits, dim=-1)
            metric.add_batch(predictions=predictions, references=batch['labels'])
        return (loss_history, metric.compute())
    else:
        return (loss_history, None)

def check_free_memory(free_bytes):
    """
    Check whether `free_bytes` amount of memory is currently free.
    Returns: None if enough memory available, otherwise error message
    """
    env_var = 'NPY_AVAILABLE_MEM'
    env_value = os.environ.get(env_var)
    if env_value is not None:
        try:
            mem_free = _parse_size(env_value)
        except ValueError as exc:
            raise ValueError(f'Invalid environment variable {env_var}: {exc}')
        msg = f'{free_bytes / 1000000000.0} GB memory required, but environment variable NPY_AVAILABLE_MEM={env_value} set'
    else:
        mem_free = _get_mem_available()
        if <MASK>:
            msg = 'Could not determine available memory; set NPY_AVAILABLE_MEM environment variable (e.g. NPY_AVAILABLE_MEM=16GB) to run the test.'
            mem_free = -1
        else:
            msg = f'{free_bytes / 1000000000.0} GB memory required, but {mem_free / 1000000000.0} GB available'
    return msg if mem_free < free_bytes else None

def can_fast_delete(self, objs, from_field=None):
    """
        Determine if the objects in the given queryset-like or single object
        can be fast-deleted. This can be done if there are no cascades, no
        parents and no signal listeners for the object class.

        The 'from_field' tells where we are coming from - we need this to
        determine if the objects are in fact to be deleted. Allow also
        skipping parent -> child -> parent chain preventing fast delete of
        the child.
        """
    if <MASK>:
        return False
    if from_field and from_field.remote_field.on_delete is not CASCADE:
        return False
    if hasattr(objs, '_meta'):
        model = objs._meta.model
    elif hasattr(objs, 'model') and hasattr(objs, '_raw_delete'):
        model = objs.model
    else:
        return False
    if self._has_signal_listeners(model):
        return False
    opts = model._meta
    return all((link == from_field for link in opts.concrete_model._meta.parents.values())) and all((related.field.remote_field.on_delete in SKIP_COLLECTION for related in get_candidate_relations_to_delete(opts))) and (not any((hasattr(field, 'bulk_related_objects') for field in opts.private_fields)))

def dict_append(d, **kws):
    languages = []
    for (k, v) in kws.items():
        if k == 'language':
            languages.append(v)
            continue
        if <MASK>:
            if k in ['library_dirs', 'include_dirs', 'extra_compile_args', 'extra_link_args', 'runtime_library_dirs', 'define_macros']:
                [d[k].append(vv) for vv in v if vv not in d[k]]
            else:
                d[k].extend(v)
        else:
            d[k] = v
    if languages:
        l = inv_language_map[max([language_map.get(l, 0) for l in languages])]
        d['language'] = l
    return

def process_view(self, request, view_func, view_args, view_kwargs):
