def __init__(self, dims):
    """Creates a new TensorShape with the given dimensions.

    Args:
      dims: A list of Dimensions, or None if the shape is unspecified.

    Raises:
      TypeError: If dims cannot be converted to a list of dimensions.
    """
    if <MASK>:
        self._dims = tuple((as_dimension(d).value for d in dims))
    elif dims is None:
        self._dims = None
    elif isinstance(dims, tensor_shape_pb2.TensorShapeProto):
        if dims.unknown_rank:
            self._dims = None
        else:
            self._dims = tuple((dim.size if dim.size != -1 else None for dim in dims.dim))
    elif isinstance(dims, TensorShape):
        self._dims = dims._dims
    else:
        try:
            dims_iter = iter(dims)
        except TypeError:
            self._dims = (as_dimension(dims).value,)
        else:
            self._dims = []
            for d in dims_iter:
                try:
                    self._dims.append(as_dimension(d).value)
                except TypeError as e:
                    raise TypeError("Failed to convert '{0!r}' to a shape: '{1!r}'could not be converted to a dimension. A shape should either be single dimension (e.g. 10), or an iterable of dimensions (e.g. [1, 10, None]).".format(dims, d)) from e
            self._dims = tuple(self._dims)

def __getitem__(self, k):
    """Retrieve an item or slice from the set of results."""
    if not isinstance(k, (int, slice)):
        raise TypeError('QuerySet indices must be integers or slices, not %s.' % type(k).__name__)
    if isinstance(k, int) and k < 0 or (isinstance(k, slice) and (k.start is not None and k.start < 0 or (k.stop is not None and k.stop < 0))):
        raise ValueError('Negative indexing is not supported.')
    if <MASK>:
        return self._result_cache[k]
    if isinstance(k, slice):
        qs = self._chain()
        if k.start is not None:
            start = int(k.start)
        else:
            start = None
        if k.stop is not None:
            stop = int(k.stop)
        else:
            stop = None
        qs.query.set_limits(start, stop)
        return list(qs)[::k.step] if k.step else qs
    qs = self._chain()
    qs.query.set_limits(k, k + 1)
    qs._fetch_all()
    return qs._result_cache[0]

def ann_to_type(ann, loc, rcb=None):
    the_type = try_ann_to_type(ann, loc, rcb)
