    raise ValueError(f"Unknown type annotation: '{ann}' at {loc.highlight()}")

def out_wrapper(*out_names: str, exact_dtype: bool=False, pass_is_out: bool=False, preserve_memory_format: bool=False) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:
    default_out_names = ('out',)
    if len(out_names) == 0:
        out_names = default_out_names
    is_tensor = len(out_names) == 1

    def maybe_compute_memory_format(t):
        return utils.suggest_memory_format(t) if preserve_memory_format else None

    def _out_wrapper(fn: Callable[_P, _T]) -> Callable[_P, _T]:
        """
        Adds the out parameter to a Python reference.
        """
        out_type = TensorLikeType if is_tensor else GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
        bc_out_type = TensorLikeType if is_tensor else types.GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
        return_type = TensorLikeType if is_tensor else NamedTuple(f'return_types_{fn.__name__}', [(o, TensorLikeType) for o in out_names])
        sig = inspect.signature(fn)
        factory_kwargs = ('device', 'dtype')
        is_factory_fn = all((p in sig.parameters for p in factory_kwargs))

        @wraps(fn)
        def _fn(*args: _P.args, **kwargs: _P.kwargs):
            out = kwargs.pop('out', None)
            if is_factory_fn and out is not None:
                for k in factory_kwargs:
                    out_attr = getattr(out, k)
                    if k not in kwargs:
                        kwargs[k] = out_attr

            def maybe_check_copy_devices(out):
                if isinstance(out, TensorLike) and isinstance(args[0], TensorLike):
                    check_copy_devices(copy_from=args[0], copy_to=out)
            if isinstance(out, (tuple, list)):
                for o in out:
                    maybe_check_copy_devices(o)
            else:
                maybe_check_copy_devices(out)
            if pass_is_out:
                result = fn(*args, is_out=out is not None, **kwargs)
            else:
                result = fn(*args, **kwargs)
            if result is NotImplemented:
                return NotImplemented
            assert isinstance(result, TensorLike) and is_tensor or (isinstance(result, tuple) and len(result) == len(out_names)) or (fn.__name__ == 'unbind' and isinstance(result, (list, tuple)))
            if out is not None:
                if is_tensor and fn.__name__ != 'unbind':
                    assert isinstance(out, TensorLike)
                    _maybe_resize_out(out, result.shape, maybe_compute_memory_format(result))
                    _safe_copy_out(copy_from=result, copy_to=out, exact_dtype=exact_dtype)
                else:
                    if fn.__name__ != 'unbind':
                        assert isinstance(out, tuple)
                    else:
                        assert isinstance(out, (list, tuple))
                    torch._check_type(len(out) == len(result), lambda : f'expected tuple of {len(result)} elements but got {len(out)}')
                    for (r, o) in zip(result, out):
                        _maybe_resize_out(o, r.shape, maybe_compute_memory_format(r))
                        _safe_copy_out(copy_from=r, copy_to=o, exact_dtype=exact_dtype)
            else:
                out = result
            return out if is_tensor else return_type(*out)
        out_param = inspect.Parameter('out', kind=inspect.Parameter.KEYWORD_ONLY, default=None, annotation=out_type)
        assert isinstance(sig.return_annotation, (str, TypeVar)) or sig.return_annotation in (sig.empty, out_type, bc_out_type)
        params = (*sig.parameters.values(), out_param)
        params = sorted(params, key=lambda p: p.kind)
        _fn.__signature__ = inspect.Signature(parameters=params, return_annotation=return_type)
        _fn.__annotations__ = dict(getattr(fn, '__annotations__', {}))
        _fn.__annotations__['out'] = out_type
        _fn.__annotations__['return'] = return_type
        if <MASK>:
            _fn.__annotations__[CustomOutParamAnnotation] = out_names[0]
        _fn._torch_decompositions_out_wrapper = f'This function is wrapped by {out_wrapper.__module__}.out_wrapper'
        return _fn
    return _out_wrapper

def compute(outer, start_idx):
    placeholders = compute_symint_placeholders(outer)
    has_symbolic = any(placeholders)
    if <MASK>:
        start = curr_start_idx
        end = start_idx + sum(placeholders)
        it_args = iter(all_args[start:end])
        it_placeholders = iter(placeholders)
        return (pytree.tree_map_only(lambda _: next(it_placeholders), lambda _: next(it_args), outer), start + len(placeholders))
    else:
        return (outer, start_idx)

def _ensure_arraylike(values, func_name: str) -> ArrayLike:
    """
    ensure that we are arraylike if not already
    """
    if not isinstance(values, (ABCIndex, ABCSeries, ABCExtensionArray, np.ndarray, ABCNumpyExtensionArray)):
        if func_name != 'isin-targets':
            raise TypeError(f'{func_name} requires a Series, Index, ExtensionArray, np.ndarray or NumpyExtensionArray got {type(values).__name__}.')
        inferred = lib.infer_dtype(values, skipna=False)
        if inferred in ['mixed', 'string', 'mixed-integer']:
            if <MASK>:
                values = list(values)
            values = construct_1d_object_array_from_listlike(values)
        else:
            values = np.asarray(values)
    return values

def _get_tid(tensor: torch.Tensor) -> _TID:
    if <MASK>:
        data_ptr = 0
    else:
        data_ptr = tensor.data_ptr()
    return (id(tensor), data_ptr, tensor._version)

def get_qparam_dict(observer_or_fake_quant):
    from torch.ao.quantization.observer import PlaceholderObserver
    qscheme = getattr(observer_or_fake_quant, 'qscheme', None)
    dtype = observer_or_fake_quant.dtype
    qparams = {'qscheme': qscheme, 'dtype': dtype}
    if not qscheme or isinstance(observer_or_fake_quant, PlaceholderObserver):
        return {'qscheme': None, 'dtype': dtype}
    if is_per_tensor(qscheme):
        qscheme = torch.per_tensor_affine
    elif is_per_channel(qscheme):
        if qscheme == torch.per_channel_symmetric:
            qscheme = torch.per_channel_affine
        qparams['axis'] = observer_or_fake_quant.ch_axis
    else:
        raise RuntimeError(f'Unrecognized qscheme: {qscheme}')
    qparams['qscheme'] = qscheme
    (scale, zero_point) = observer_or_fake_quant.calculate_qparams()
    qparams['scale'] = scale
    qparams['zero_point'] = zero_point
    if hasattr(observer_or_fake_quant, 'quant_min'):
        qparams['quant_min'] = observer_or_fake_quant.quant_min
    if <MASK>:
        qparams['quant_max'] = observer_or_fake_quant.quant_max
    return qparams

@wraps(meth)
def new_meth(self, *args, **kwargs):
    if <MASK>:
        return meth(self, *args, **kwargs)
    arr = self.view('M8[ns]')
    result = meth(arr, *args, **kwargs)
    if result is NaT:
        return NaT
    elif isinstance(result, Timestamp):
        return self._box_func(result._value)
    res_i8 = result.view('i8')
    return self._from_backing_data(res_i8)

def _is_valid_quantized_op_binary_optimization_pattern(qop, extra_input_from_dequant=True):

    def fn(match):
        output_dtype = _get_pattern_output_dtype(match)
        compute_node = filter_nodes(match.nodes, qop)[0]
        if len(compute_node.users) != 1:
            return False
        binary_node_inputs = next(iter(compute_node.users)).args
        assert len(binary_node_inputs) == 2, 'Expects binary node with 2 inputs'
        if output_dtype in [torch.float32, torch.bfloat16]:
            extra_input_of_binary_node = None
            for arg in binary_node_inputs:
                if arg != compute_node:
                    extra_input_of_binary_node = arg
                    break
            assert extra_input_of_binary_node is not None
            if extra_input_from_dequant and (not isinstance(extra_input_of_binary_node, torch.fx.Node) or extra_input_of_binary_node.target != quantized_decomposed.dequantize_per_tensor.default):
                return False
        if <MASK>:
            return False
        if binary_node_inputs[0].meta['val'].size() != binary_node_inputs[1].meta['val'].size():
            return False
        from .mkldnn_fusion import _get_remaining_users
        extra_input_of_pattern = match.kwargs['other'] if 'other' in match.kwargs else match.kwargs['accum'] if output_dtype in [torch.uint8, torch.int8] or not extra_input_from_dequant else match.kwargs['accum_after_dequant']
        if len(_get_remaining_users(extra_input_of_pattern, compute_node)) > 1 or extra_input_of_pattern == compute_node.args[0]:
            return False
        return True
    return fn

def __getitem__(self, indx):
    """
        x.__getitem__(y) <==> x[y]

        Return the item described by i, as a masked array.

        """
    dout = self.data[indx]
    _mask = self._mask

    def _is_scalar(m):
        return not isinstance(m, np.ndarray)

    def _scalar_heuristic(arr, elem):
        """
            Return whether `elem` is a scalar result of indexing `arr`, or None
            if undecidable without promoting nomask to a full mask
            """
        if not isinstance(elem, np.ndarray):
            return True
        elif arr.dtype.type is np.object_:
            if arr.dtype is not elem.dtype:
                return True
        elif type(arr).__getitem__ == ndarray.__getitem__:
            return False
        return None
    if _mask is not nomask:
        mout = _mask[indx]
        scalar_expected = _is_scalar(mout)
    else:
        mout = nomask
        scalar_expected = _scalar_heuristic(self.data, dout)
        if scalar_expected is None:
            scalar_expected = _is_scalar(getmaskarray(self)[indx])
    if scalar_expected:
        if isinstance(dout, np.void):
            return mvoid(dout, mask=mout, hardmask=self._hardmask)
        elif self.dtype.type is np.object_ and isinstance(dout, np.ndarray) and (dout is not masked):
            if mout:
                return MaskedArray(dout, mask=True)
            else:
                return dout
        elif mout:
            return masked
        else:
            return dout
    else:
        dout = dout.view(type(self))
        dout._update_from(self)
        if is_string_or_list_of_strings(indx):
            if self._fill_value is not None:
                dout._fill_value = self._fill_value[indx]
                if <MASK>:
                    raise RuntimeError('Internal NumPy error.')
                if dout._fill_value.ndim > 0:
                    if not (dout._fill_value == dout._fill_value.flat[0]).all():
                        warnings.warn(f'Upon accessing multidimensional field {indx!s}, need to keep dimensionality of fill_value at 0. Discarding heterogeneous fill_value and setting all to {dout._fill_value[0]!s}.', stacklevel=2)
                    dout._fill_value = dout._fill_value.flat[0:1].squeeze(axis=0)
            dout._isfield = True
        if mout is not nomask:
            dout._mask = reshape(mout, dout.shape)
            dout._sharedmask = True
    return dout

def _cast(value, device_type: str, dtype: _dtype):
    if <MASK>:
        is_eligible = value.is_floating_point() and value.device.type == device_type and (value.dtype is not torch.float64)
        return value.to(dtype) if is_eligible else value
    elif isinstance(value, (str, bytes)):
        return value
    elif isinstance(value, collections.abc.Iterable):
        iterable = (_cast(v, device_type, dtype) for v in value)
        if isinstance(value, (list, tuple)):
            return type(value)(iterable)
        else:
            return iterable
    else:
        return value

@simple_wraps(compiled_fn)
def runtime_wrapper(args: list[Any]):
    cm = record_runtime_wrapper_prologue_enter()
    orig_inputs = {i: args[i] for i in epilogue_args_idx}
    if keep_input_mutations:
        mutated_args = (args[i] for i in runtime_metadata.mutated_graph_handled_indices_seen_by_autograd)
        torch.autograd.graph.increment_version(mutated_args)
    if trace_joint:
        args_ = list(args)
        for idx in indices_of_inps_to_detach:
            if isinstance(args_[idx], torch.Tensor):
                args_[idx] = args_[idx].detach()
        with torch.autograd._force_original_view_tracking(True), torch.enable_grad():
            record_runtime_wrapper_prologue_exit(cm)
            all_outs = call_func_at_runtime_with_args(compiled_fn, args_, disable_amp=disable_amp, steal_args=True)
    else:
        grad_enabled = torch.is_grad_enabled()
        try:
            if grad_enabled:
                torch._C._set_grad_enabled(False)
            record_runtime_wrapper_prologue_exit(cm)
            all_outs = call_func_at_runtime_with_args(compiled_fn, args, disable_amp=disable_amp, steal_args=True)
        finally:
            if grad_enabled:
                torch._C._set_grad_enabled(True)
    del args
    num_mutated_runtime_inps = runtime_metadata.num_mutated_inp_runtime_indices
    num_intermediate_bases = runtime_metadata.num_intermediate_bases
    assert len(all_outs) == num_mutated_runtime_inps + runtime_metadata.num_outputs + num_intermediate_bases
    num_mutations_to_apply = runtime_metadata.num_mutated_inp_runtime_indices
    if num_mutations_to_apply > 0:
        updated_inputs = all_outs[:num_mutations_to_apply]
        fw_outs = all_outs[num_mutations_to_apply:]
        for (i, inpt_idx) in enumerate(runtime_metadata.mutated_inp_runtime_indices):
            meta = runtime_metadata.input_info[inpt_idx]
            if not meta.mutates_data and (not meta.mutates_metadata):
                continue
            original_inpt = orig_inputs[inpt_idx]
            updated_inpt = updated_inputs[i]
            if meta.mutates_storage_metadata:
                if trace_joint:
                    assert isinstance(updated_inpt, TensorAlias)
                    updated_inpt = updated_inpt.alias
                with torch.no_grad():
                    original_inpt.set_(updated_inpt)
                continue
            if meta.mutates_metadata and (not meta.mutates_data):
                if trace_joint:
                    assert isinstance(updated_inpt, TensorAlias)
                    updated_inpt = updated_inpt.alias
                original_inpt.as_strided_(updated_inpt.size(), updated_inpt.stride(), updated_inpt.storage_offset())
            else:
                if meta.mutates_data and meta.mutates_metadata:
                    original_inpt.as_strided_(updated_inpt.size(), updated_inpt.stride(), updated_inpt.storage_offset())
                else:
                    assert meta.mutates_data
                if meta.is_leaf and original_inpt.requires_grad:
                    original_inpt.detach().copy_(updated_inpt)
                else:
                    original_inpt.copy_(updated_inpt)
    else:
        fw_outs = all_outs
    if runtime_metadata.num_outputs_aliased > 0:
        expect_num_outputs = len(output_handlers) + runtime_metadata.num_intermediate_bases
        assert len(fw_outs) == expect_num_outputs
        ret_outs = [handler(orig_inputs, fw_outs, out) for (out, handler) in builtins.zip(fw_outs, output_handlers)]
    else:
        ret_outs = fw_outs
    if <MASK>:
        for (t, o) in zip(ret_outs, runtime_metadata.output_info):
            if o.dynamic_dims is None:
                continue
            maybe_mark_dynamic_helper(t, o.dynamic_dims)
    if runtime_metadata.grad_enabled_mutation is not None:
        torch._C._set_grad_enabled(runtime_metadata.grad_enabled_mutation)
    return ret_outs

def _get_index_freq(index: Index) -> BaseOffset | None:
    freq = getattr(index, 'freq', None)
    if <MASK>:
        freq = getattr(index, 'inferred_freq', None)
        freq = to_offset(freq)
    return freq

def main() -> None:
    args = parse_args()
    if <MASK>:
        if args.python:
            logger.warning('Both --python and --find-python specified. Using --find-python and ignoring --python.')
        pythons = find_python_interpreters(args.find_python)
        if not pythons:
            logger.error('No Python interpreters found with --find-python %s', args.find_python)
            sys.exit(1)
        logger.info('Found %d supported Python interpreters: %s', len(pythons), ', '.join(pythons))
    else:
        pythons = args.python or [sys.executable]
    build_times: dict[str, float] = dict()
    if len(pythons) > 1 and args.destination == 'dist/':
        logger.warning("dest is 'dist/' while multiple python versions specified, output will be overwritten")
    for interpreter in pythons:
        with venv(interpreter) as venv_interpreter:
            builder = Builder(venv_interpreter)
            builder.install_requirements()
            builder.clean()
            start_time = time.time()
            builder.build_wheel(args.destination)
            end_time = time.time()
            build_times[interpreter_version(venv_interpreter)] = end_time - start_time
    for (version, build_time) in build_times.items():
        logger.info('Build time (%s): %fs', version, build_time)

def _single_tensor_radam(params: list[Tensor], grads: list[Tensor], exp_avgs: list[Tensor], exp_avg_sqs: list[Tensor], state_steps: list[Tensor], *, beta1: float, beta2: float, lr: float, weight_decay: float, eps: float, decoupled_weight_decay: bool, differentiable: bool, maximize: bool, capturable: bool, has_complex: bool):
    if not torch.jit.is_scripting():
        lr = _to_scalar(lr)
    for (i, param) in enumerate(params):
        grad = grads[i] if not maximize else -grads[i]
        exp_avg = exp_avgs[i]
        exp_avg_sq = exp_avg_sqs[i]
        step_t = state_steps[i]
        if not torch.compiler.is_compiling() and capturable:
            capturable_supported_devices = _get_capturable_supported_devices()
            if not (param.device.type == step_t.device.type and param.device.type in capturable_supported_devices):
                raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
        if torch.is_complex(param):
            param = torch.view_as_real(param)
            grad = torch.view_as_real(grad)
            exp_avg = torch.view_as_real(exp_avg)
            exp_avg_sq = torch.view_as_real(exp_avg_sq)
        step_t += 1
        step = step_t if capturable else _get_value(step_t)
        if weight_decay != 0:
            if decoupled_weight_decay:
                param.mul_(1 - lr * weight_decay)
            else:
                grad = grad.add(param, alpha=weight_decay)
        exp_avg.lerp_(grad, 1 - beta1)
        exp_avg_sq.mul_(beta2).addcmul_(grad, grad, value=1 - beta2)
        bias_correction1 = 1 - beta1 ** step
        bias_correction2 = 1 - beta2 ** step
        bias_corrected_exp_avg = exp_avg / bias_correction1
        rho_inf = 2 / (1 - beta2) - 1
        rho_t = rho_inf - 2 * step * beta2 ** step / bias_correction2

        def _compute_rect():
            return ((rho_t - 4) * (rho_t - 2) * rho_inf / ((rho_inf - 4) * (rho_inf - 2) * rho_t)) ** 0.5

        def _compute_adaptive_lr():
            exp_avg_sq_sqrt = exp_avg_sq.sqrt()
            if differentiable:
                exp_avg_sq_sqrt = exp_avg_sq_sqrt.add(eps)
            else:
                exp_avg_sq_sqrt = exp_avg_sq_sqrt.add_(eps)
            return bias_correction2 ** 0.5 / exp_avg_sq_sqrt
        if <MASK>:
            update = torch.where(rho_t > 5.0, _compute_rect() * _compute_adaptive_lr(), 1.0)
            param.add_(bias_corrected_exp_avg * lr * update, alpha=-1.0)
        elif rho_t > 5.0:
            param.add_(bias_corrected_exp_avg * lr * _compute_adaptive_lr() * _compute_rect(), alpha=-1.0)
        else:
            param.add_(bias_corrected_exp_avg * lr, alpha=-1.0)

def _validate_tolerance(self, left_join_keys: list[ArrayLike]) -> None:
    if self.tolerance is not None:
        if self.left_index:
            lt = self.left.index._values
        else:
            lt = left_join_keys[-1]
        msg = f'incompatible tolerance {self.tolerance}, must be compat with type {lt.dtype!r}'
        if needs_i8_conversion(lt.dtype) or (isinstance(lt, ArrowExtensionArray) and lt.dtype.kind in 'mM'):
            if not isinstance(self.tolerance, datetime.timedelta):
                raise MergeError(msg)
            if <MASK>:
                raise MergeError('tolerance must be positive')
        elif is_integer_dtype(lt.dtype):
            if not is_integer(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError('tolerance must be positive')
        elif is_float_dtype(lt.dtype):
            if not is_number(self.tolerance):
                raise MergeError(msg)
            if self.tolerance < 0:
                raise MergeError('tolerance must be positive')
        else:
            raise MergeError('key must be integer, timestamp or float')

def node_to_str(self, tree, node_id, criterion):
    if tree.n_outputs == 1:
        value = tree.value[node_id][0, :]
    else:
        value = tree.value[node_id]
    labels = self.label == 'root' and node_id == 0 or self.label == 'all'
    characters = self.characters
    node_string = characters[-1]
    if self.node_ids:
        if labels:
            node_string += 'node '
        node_string += characters[0] + str(node_id) + characters[4]
    if tree.children_left[node_id] != _tree.TREE_LEAF:
        if self.feature_names is not None:
            feature = self.feature_names[tree.feature[node_id]]
            feature = self.str_escape(feature)
        else:
            feature = 'x%s%s%s' % (characters[1], tree.feature[node_id], characters[2])
        node_string += '%s %s %s%s' % (feature, characters[3], round(tree.threshold[node_id], self.precision), characters[4])
    if self.impurity:
        if isinstance(criterion, _criterion.FriedmanMSE):
            criterion = 'friedman_mse'
        elif isinstance(criterion, _criterion.MSE) or criterion == 'squared_error':
            criterion = 'squared_error'
        elif not isinstance(criterion, str):
            criterion = 'impurity'
        if labels:
            node_string += '%s = ' % criterion
        node_string += str(round(tree.impurity[node_id], self.precision)) + characters[4]
    if labels:
        node_string += 'samples = '
    if <MASK>:
        percent = 100.0 * tree.n_node_samples[node_id] / float(tree.n_node_samples[0])
        node_string += str(round(percent, 1)) + '%' + characters[4]
    else:
        node_string += str(tree.n_node_samples[node_id]) + characters[4]
    if not self.proportion and tree.n_classes[0] != 1:
        value = value * tree.weighted_n_node_samples[node_id]
    if labels:
        node_string += 'value = '
    if tree.n_classes[0] == 1:
        value_text = np.around(value, self.precision)
    elif self.proportion:
        value_text = np.around(value, self.precision)
    elif np.all(np.equal(np.mod(value, 1), 0)):
        value_text = value.astype(int)
    else:
        value_text = np.around(value, self.precision)
    value_text = str(value_text.astype('S32')).replace("b'", "'")
    value_text = value_text.replace("' '", ', ').replace("'", '')
    if tree.n_classes[0] == 1 and tree.n_outputs == 1:
        value_text = value_text.replace('[', '').replace(']', '')
    value_text = value_text.replace('\n ', characters[4])
    node_string += value_text + characters[4]
    if self.class_names is not None and tree.n_classes[0] != 1 and (tree.n_outputs == 1):
        if labels:
            node_string += 'class = '
        if self.class_names is not True:
            class_name = self.class_names[np.argmax(value)]
            class_name = self.str_escape(class_name)
        else:
            class_name = 'y%s%s%s' % (characters[1], np.argmax(value), characters[2])
        node_string += class_name
    if node_string.endswith(characters[4]):
        node_string = node_string[:-len(characters[4])]
    return node_string + characters[5]

def _parse_target_tokens(self, tokens):
    assert isinstance(tokens, str)
    final_targets = []
    extra_flags = []
    has_baseline = False
    skipped = set()
    policies = set()
    multi_target = None
    tokens = list(filter(None, re.split(self._parse_regex_target, tokens)))
    if not tokens:
        self.dist_fatal('expected one token at least')
    for tok in tokens:
        TOK = tok.upper()
        ch = tok[0]
        if ch in ('+', '-'):
            self.dist_fatal("+/- are 'not' allowed from target's groups or @targets, only from cpu_baseline and cpu_dispatch parms")
        elif ch == '$':
            if multi_target is not None:
                self.dist_fatal("policies aren't allowed inside multi-target '()', only CPU features")
            policies.add(self._parse_token_policy(TOK))
        elif ch == '#':
            if multi_target is not None:
                self.dist_fatal("target groups aren't allowed inside multi-target '()', only CPU features")
            (has_baseline, final_targets, extra_flags) = self._parse_token_group(TOK, has_baseline, final_targets, extra_flags)
        elif ch == '(':
            if multi_target is not None:
                self.dist_fatal("unclosed multi-target, missing ')'")
            multi_target = set()
        elif ch == ')':
            if <MASK>:
                self.dist_fatal("multi-target opener '(' wasn't found")
            targets = self._parse_multi_target(multi_target)
            if targets is None:
                skipped.add(tuple(multi_target))
            else:
                if len(targets) == 1:
                    targets = targets[0]
                if targets and targets not in final_targets:
                    final_targets.append(targets)
            multi_target = None
        else:
            if TOK == 'BASELINE':
                if multi_target is not None:
                    self.dist_fatal("baseline isn't allowed inside multi-target '()'")
                has_baseline = True
                continue
            if multi_target is not None:
                multi_target.add(TOK)
                continue
            if not self.feature_is_exist(TOK):
                self.dist_fatal("invalid target name '%s'" % TOK)
            is_enabled = TOK in self.parse_baseline_names or TOK in self.parse_dispatch_names
            if is_enabled:
                if TOK not in final_targets:
                    final_targets.append(TOK)
                continue
            skipped.add(TOK)
    if multi_target is not None:
        self.dist_fatal("unclosed multi-target, missing ')'")
    if skipped:
        self.dist_log('skip targets', skipped, 'not part of baseline or dispatch-able features')
    final_targets = self.feature_untied(final_targets)
    for p in list(policies):
        (_, _, deps) = self._parse_policies[p]
        for d in deps:
            if d in policies:
                continue
            self.dist_log("policy '%s' force enables '%s'" % (p, d))
            policies.add(d)
    for (p, (have, nhave, _)) in self._parse_policies.items():
        func = None
        if p in policies:
            func = have
            self.dist_log("policy '%s' is ON" % p)
        else:
            func = nhave
        if not func:
            continue
        (has_baseline, final_targets, extra_flags) = func(has_baseline, final_targets, extra_flags)
    return (has_baseline, final_targets, extra_flags)

@combinations.generate(combinations.times(test_base.default_test_combinations(), checkpoint_test_base.default_test_combinations(), combinations.combine(dataset_range=[10], num_shards=[1, 3], shard_index=[0, 1, 2], reshuffle_each_iteration=[True, False], symbolic_checkpoint=[True, False])))
