@disallow('M8', 'm8')
def nancov(a: np.ndarray, b: np.ndarray, *, min_periods: int | None=None, ddof: int | None=1) -> float:
    if len(a) != len(b):
        raise AssertionError('Operands to nancov must have same size')
    if min_periods is None:
        min_periods = 1
    valid = notna(a) & notna(b)
    if <MASK>:
        a = a[valid]
        b = b[valid]
    if len(a) < min_periods:
        return np.nan
    a = _ensure_numeric(a)
    b = _ensure_numeric(b)
    return np.cov(a, b, ddof=ddof)[0, 1]

def halide_argdefs(self):
    """
        Halide requires scalar inputs before outputs, so need to reorder args.
        """

    def arg_order(arg_tuple):
        (_call_str, arg) = arg_tuple
        if <MASK>:
            return 1
        elif 'out_ptr' in arg.name:
            return 2
        else:
            assert 'in_ptr' in arg.name
            return 0
    result: list[tuple[Optional[str], KernelArgType]] = []
    (_, a, b, _) = self.args.python_argdefs()
    for (call_str, arg) in sorted(zip(a, b), key=arg_order):
        result.append((call_str, arg))
        if isinstance(arg, TensorArg):
            assert arg.offset == 0 and arg.alias_of is None
            result.extend(((None, TensorArg(alias, arg.buffer, arg.dtype, arg.offset, alias_of=arg.name)) for alias in self.buffer_aliases.get(arg.name, ())))
    return result

def hist_series(self: Series, by=None, ax=None, grid: bool=True, xlabelsize: int | None=None, xrot=None, ylabelsize: int | None=None, yrot=None, figsize: tuple[float, float] | None=None, bins: int=10, legend: bool=False, **kwds):
    import matplotlib.pyplot as plt
    if legend and 'label' in kwds:
        raise ValueError('Cannot use both legend and label')
    if by is None:
        if kwds.get('layout', None) is not None:
            raise ValueError("The 'layout' keyword is not supported when 'by' is None")
        fig = kwds.pop('figure', plt.gcf() if plt.get_fignums() else plt.figure(figsize=figsize))
        if figsize is not None and tuple(figsize) != tuple(fig.get_size_inches()):
            fig.set_size_inches(*figsize, forward=True)
        if ax is None:
            ax = fig.gca()
        elif ax.get_figure() != fig:
            raise AssertionError('passed axis not bound to passed figure')
        values = self.dropna().values
        if legend:
            kwds['label'] = self.name
        ax.hist(values, bins=bins, **kwds)
        if legend:
            ax.legend()
        ax.grid(grid)
        axes = np.array([ax])
        set_ticks_props(axes, xlabelsize=xlabelsize, xrot=xrot, ylabelsize=ylabelsize, yrot=yrot)
    else:
        if 'figure' in kwds:
            raise ValueError("Cannot pass 'figure' when using the 'by' argument, since a new 'Figure' instance will be created")
        axes = _grouped_hist(self, by=by, ax=ax, grid=grid, figsize=figsize, bins=bins, xlabelsize=xlabelsize, xrot=xrot, ylabelsize=ylabelsize, yrot=yrot, legend=legend, **kwds)
    if hasattr(axes, 'ndim'):
        if <MASK>:
            return axes[0]
    return axes

def _find_originating_frame(caller_fn_scope, innermost=True):
    """Locates the frame in which `caller_fn_scope` was defined."""
    ctx_frame = inspect.currentframe()
    result = None
    while ctx_frame is not None:
        if ctx_frame.f_locals.get(caller_fn_scope.name, None) is caller_fn_scope:
            result = ctx_frame
            if <MASK>:
                break
        ctx_frame = ctx_frame.f_back
    assert result is not None, 'the conversion process should ensure the caller_fn_scope is always found somewhere on the call stack'
    return result

def resolve_ref(self, name, allow_joins=True, reuse=None, summarize=False):
    annotation = self.annotations.get(name)
    if annotation is not None:
        if not allow_joins:
            for alias in self._gen_col_aliases([annotation]):
                if isinstance(self.alias_map[alias], Join):
                    raise FieldError('Joined field references are not permitted in this query')
        if summarize:
            if name not in self.annotation_select:
                raise FieldError("Cannot aggregate over the '%s' alias. Use annotate() to promote it." % name)
            return Ref(name, self.annotation_select[name])
        else:
            return annotation
    else:
        field_list = name.split(LOOKUP_SEP)
        annotation = self.annotations.get(field_list[0])
        if annotation is not None:
            for transform in field_list[1:]:
                annotation = self.try_transform(annotation, transform)
            return annotation
        join_info = self.setup_joins(field_list, self.get_meta(), self.get_initial_alias(), can_reuse=reuse)
        (targets, final_alias, join_list) = self.trim_joins(join_info.targets, join_info.joins, join_info.path)
        if <MASK>:
            raise FieldError('Joined field references are not permitted in this query')
        if len(targets) > 1:
            raise FieldError("Referencing multicolumn fields with F() objects isn't supported")
        transform = join_info.transform_function(targets[0], final_alias)
        if reuse is not None:
            reuse.update(join_list)
        return transform

def _find_first_node_in_dequant_pattern(_node):
    if <MASK>:
        return _node
    else:
        assert len(_node.args) >= 1, 'In in dequant pattern, each node should have more than 1 arg.'
        return _find_first_node_in_dequant_pattern(_node.args[0])

def fast_binary_impl(mode, *args, **kwargs):

    def slow(msg):
        count_label(f'slow {msg}')
        with mode:
            return slow_ref(*args, **kwargs)
    count_label('attempt fast')
    operands = args
    final_shape = None
    for op in operands:
        shape = op.shape if isinstance(op, torch.Tensor) else ()
        if final_shape is None:
            final_shape = shape
        final_shape = infer_size(final_shape, shape)
    assert final_shape is not None
    from torch.fx.experimental.symbolic_shapes import guard_or_false, sym_eq
    for op in operands:
        if isinstance(op, torch.Tensor) and len(op.shape) == len(final_shape) and guard_or_false(sym_eq(op.shape, final_shape)):
            break
    else:
        return slow('both tensors nontrivially broadcast')
    cpu = torch.device('cpu')
    common_device = cpu
    common_dtype = None
    has_different_input_dtypes = False
    for op in operands:
        if not isinstance(op, torch.Tensor):
            has_different_input_dtypes = True
            continue
        if common_device == cpu and op.device.type != 'cpu':
            common_device = op.device
        if common_dtype is None:
            common_dtype = op.dtype
        elif <MASK>:
            has_different_input_dtypes = True
    if has_different_input_dtypes:
        (_, common_dtype) = elementwise_dtypes(*operands, type_promotion_kind=type_promotion_kind)
    current_cpu_scalars_on_non_cpu = 0
    max_cpu_scalars_on_non_cpu = 1
    for op in operands:
        if not isinstance(op, torch.Tensor):
            continue
        if common_device != cpu and op.dim() == 0 and (op.device == cpu):
            if current_cpu_scalars_on_non_cpu >= max_cpu_scalars_on_non_cpu:
                return slow('error')
            current_cpu_scalars_on_non_cpu += 1
        elif op.device != common_device:
            return slow('error')
    definitely_contiguous = True
    definitely_channels_last = True
    if is_noncontiguous_supported(common_device):
        for op in operands:
            if not isinstance(op, torch.Tensor):
                continue
            definitely_contiguous = definitely_contiguous and is_contiguous_for_memory_format_or_false(op, memory_format=torch.contiguous_format)
            definitely_channels_last = definitely_channels_last and is_contiguous_for_memory_format_or_false(op, memory_format=torch.channels_last)
    if definitely_contiguous:
        count_label('fast is_contiguous')
        return FakeTensor(mode, torch.empty(final_shape, dtype=common_dtype, device='meta', memory_format=torch.contiguous_format), device=common_device)
    if definitely_channels_last:
        count_label('fast channels_last')
        return FakeTensor(mode, torch.empty(final_shape, dtype=common_dtype, device='meta', memory_format=torch.channels_last), device=common_device)
    return slow('no contiguity match')

def _handle_activity_regularization(self, inputs, outputs):
