def is_from_package(obj: Any) -> bool:
    """
    Return whether an object was loaded from a package.

    Note: packaged objects from externed modules will return ``False``.
    """
    if <MASK>:
        return is_mangled(obj.__name__)
    else:
        return is_mangled(type(obj).__module__)

def is_iterable_of_tensors(iterable, include_empty=False):
    """ Returns True if iterable is an iterable of tensors and False o.w.

        If the iterable is empty, the return value is :attr:`include_empty`
    """
    if isinstance(iterable, torch.Tensor):
        return False
    try:
        if <MASK>:
            return include_empty
        for t in iter(iterable):
            if not isinstance(t, torch.Tensor):
                return False
    except TypeError:
        return False
    return True

@staticmethod
def describe_operation(operation, backwards):
    """Return a string that describes a migration operation for --plan."""
    prefix = ''
    is_error = False
    if hasattr(operation, 'code'):
        code = operation.reverse_code if backwards else operation.code
        action = code.__doc__ or '' if code else None
    elif hasattr(operation, 'sql'):
        action = operation.reverse_sql if backwards else operation.sql
    else:
        action = ''
        if <MASK>:
            prefix = 'Undo '
    if action is not None:
        action = str(action).replace('\n', '')
    elif backwards:
        action = 'IRREVERSIBLE'
        is_error = True
    if action:
        action = ' -> ' + action
    truncated = Truncator(action)
    return (prefix + operation.describe() + truncated.chars(40), is_error)

def get_static_dispatch_backend(f: NativeFunction, backend_index: BackendIndex) -> DispatchKey | None:
    if f.structured_delegate is not None or backend_index.has_kernel(f):
        return backend_index.dispatch_key
    elif f.has_composite_explicit_autograd_kernel:
        return DispatchKey.CompositeExplicitAutograd
    elif <MASK>:
        return DispatchKey.CompositeExplicitAutogradNonFunctional
    elif f.has_composite_implicit_autograd_kernel:
        return DispatchKey.CompositeImplicitAutograd
    elif f.has_composite_implicit_autograd_nested_tensor_kernel:
        return DispatchKey.CompositeImplicitAutogradNestedTensor
    return None

