def _lookup_inner(obj: Any, name: Optional[str]=None, filename: Optional[str]=None, is_direct_call: bool=True, reasons: Optional[set[str]]=None) -> Optional[type[VariableTracker]]:
    try:
        can_hash = hashable(obj)
    except Exception:
        can_hash = False
    if not can_hash:
        if <MASK>:
            reasons.add('obj is not hashable')
        return None
    if obj is not None:
        if is_aten_op_or_tensor_method(obj):
            return TorchInGraphFunctionVariable
        rule = get_torch_obj_rule_map().get(obj, None)
        if rule is not None:
            if reasons is not None:
                reasons.add('get_torch_obj_rule_map')
            return rule
    elif name is not None and filename is not None and (not is_direct_call):
        if name.startswith(TORCH_DYNAMO_RESUME_IN_PREFIX):
            rule = get_torch_obj_rule_map().get(filename + '#' + TORCH_DYNAMO_RESUME_IN_PREFIX, None)
        else:
            rule = get_torch_obj_rule_map().get(filename + '#' + name, None)
        if rule is not None:
            if reasons is not None:
                reasons.add('get_torch_obj_rule_map')
            return rule
    elif name == '<listcomp>':
        if reasons is not None:
            reasons.add('inlining frame from list comprehension')
        return UserFunctionVariable
    if is_direct_call:
        if name == 'patched_init':
            if reasons is not None:
                reasons.add('func name is patched_init')
            return SkipFunctionVariable
        elif name == '__torch_function__' or (obj and getattr(obj, '__name__', None) == '__torch_function__'):
            if reasons is not None:
                reasons.add('func name is __torch_function__')
            return UserFunctionVariable
    if not is_direct_call:
        if name == '__getattr__':
            if reasons is not None:
                reasons.add('Tracing __getattr__ as the top level frame, unsuitable for tracing.')
            return SkipFunctionVariable
    if filename is None:
        filename = getfile(obj)
    skip_result = check_file(filename, is_direct_call)
    if reasons is not None and skip_result.reason is not None:
        reasons.add(skip_result.reason)
    if skip_result.skipped:
        return SkipFunctionVariable
    else:
        return UserFunctionVariable

def process_update(x):
    """Standardize update ops.

      Args:
        x: Tensor, op, or callable.

      Returns:
        An update op.
      """
    if callable(x):
        update = lambda : process_update(x())
        return update()
    elif <MASK>:
        update = x
    elif hasattr(x, 'op'):
        update = x.op
    else:
        update = tensor_conversion.convert_to_tensor_v2_with_dispatch(x)
    reachable = tf_utils.get_reachable_from_inputs(relevant_inputs, [update])
    update._unconditional_update = update not in reachable
    return update

def put_code_state() -> None:
    if <MASK>:
        log.info('put_code_state: never initialized, will not write')
        return
    if _CODE_STATE == _INIT_CODE_STATE:
        log.info('put_code_state: no change, skipping')
        return
    cache_key = get_cache_key()
    if cache_key is None:
        log.info('put_code_state: no cache key, skipping')
        return
    put_local_code_state(cache_key)
    put_remote_code_state(cache_key)
    if (sticky_write := torch.compiler.config.pgo_extra_write_key) is not None:
        extra_write_key = get_extra_cache_key(sticky_write)
        if extra_write_key is not None:
            put_remote_code_state(extra_write_key)

def select_tiling(self, fn_list, var_sizes_list) -> tuple[list[int], list[int]]:
    loop_bodies = _get_loop_body(fn_list)
    all_dtypes = _get_dtype_from_loopbodies(loop_bodies)
    assert all_dtypes
    if any((dtype not in VECTORIZABLE_DTYPES for dtype in all_dtypes)):
        return ([], [])
    dtype = torch.float
    _lowp_fp_dtype = get_loop_body_lowp_fp(loop_bodies[0])[0]
    if _lowp_fp_dtype and all((get_loop_body_lowp_fp(loop_body)[0] == _lowp_fp_dtype for loop_body in loop_bodies[1:])):
        dtype = _lowp_fp_dtype
    tiling_factor = cpu_vec_isa.pick_vec_isa().nelements(dtype=dtype)
    tiling_indices = self._select_tiling_indices(fn_list, var_sizes_list, tiling_factor)
    if tiling_indices:
        (group, reduction_group) = max(var_sizes_list, key=lambda sizes: len(sizes[1]))
        call_ranges = tuple(group) + tuple(reduction_group)
        if config.cpp.enable_tiling_heuristics:

            def _try_get_stride(index, itervars, tiling_factor, tiling_indices):
                itervar = itervars[tiling_indices[0]]
                stride = stride_at_vec_range(index, itervar, tiling_factor)
                return stride if stride.is_number else None

            def _update_negative_op_count(node_name, non_contig_indexing_op_counter):
                if node_name not in non_contig_indexing_op_counter:
                    non_contig_indexing_op_counter[node_name] = 1
                else:
                    non_contig_indexing_op_counter[node_name] += 1

            def _is_valid_indices(itervars, tiling_indices):
                return len(tiling_indices) == 1 and len(itervars) > 0 and ((tiling_indices[0] if tiling_indices[0] >= 0 else tiling_indices[0] + len(itervars)) < len(itervars))
            itervars = [sympy_index_symbol_with_prefix(SymT.XBLOCK, n) for n in range(len(call_ranges))]
            reduction_depth = len(group)
            (vars, reduction_vars) = (itervars[:reduction_depth], itervars[reduction_depth:])
            op_counter: dict[str, int] = {}
            non_contig_indexing_op_counter: dict[str, int] = {}
            for _body in loop_bodies:
                sub_blocks = [_body.root_block] + list(_body.subblocks.values())
                for sub_block in sub_blocks:
                    for _node in sub_block.graph.nodes:
                        if _node.target in ['index_expr', 'load', 'store']:
                            arg_idx = 1 if _node.target == 'index_expr' else 2
                            index = sub_block.body.indexing_from_args((vars, reduction_vars))[_node.args[arg_idx].args[0]]
                            if _is_valid_indices(itervars, tiling_indices):
                                stride = _try_get_stride(index, itervars, tiling_factor, tiling_indices)
                                if stride is None if _node.target == 'index_expr' else stride not in [0, 1]:
                                    _update_negative_op_count(_node.target, non_contig_indexing_op_counter)
                        if <MASK>:
                            if _node.target not in op_counter:
                                op_counter[_node.target] = 1
                            else:
                                op_counter[_node.target] += 1
            op_num = sum(op_counter.values())
            non_contig_indexing_op_num = sum(non_contig_indexing_op_counter.values())
            ratio_threshold = 0.12
            quantity_threshold = 35
            if non_contig_indexing_op_num >= quantity_threshold or (op_num > 0 and non_contig_indexing_op_num / op_num >= ratio_threshold):
                return ([], [])
            if not reduction_group and group and (len(tiling_indices) == 1) and (not has_free_symbols([group[tiling_indices[0]]])) and (group[tiling_indices[0]] < tiling_factor / 4) and (op_num < 10):
                return ([], [])
        if dtype in DTYPE_LOWP_FP:
            factor_lowp = cpu_vec_isa.pick_vec_isa().nelements(dtype=dtype)
            for tiling_indice in tiling_indices:
                if tiling_indice < 0:
                    tiling_indice = tiling_indice + len(call_ranges)
                if tiling_indice < 0 or tiling_indice >= len(call_ranges):
                    continue
                if has_free_symbols(call_ranges):
                    call_range = V.graph.sizevars.size_hint(call_ranges[tiling_indice], fallback=0)
                    if call_range < factor_lowp:
                        V.graph.sizevars.check_lt(call_range, factor_lowp)
                        tiling_factor = factor_lowp // 2
                        break
                elif call_ranges[tiling_indice] < factor_lowp:
                    tiling_factor = factor_lowp // 2
                    break
        if len(tiling_indices) == 1:
            return ([tiling_factor], tiling_indices)
        if len(tiling_indices) == 2:
            return ([tiling_factor, tiling_factor], tiling_indices)
    return ([], [])

@register_lowering(aten.cumprod)
def cumprod(x, axis=None, dtype=None):
    if (is_integer_dtype(x.get_dtype()) or is_boolean_dtype(x.get_dtype())) and dtype is None:
        dtype = torch.int64
    if <MASK>:
        assert axis in [0, -1]
        dtype = dtype or x.get_dtype()
        return to_dtype(x, dtype, copy=True)

    def combine_fn(a_tuple, b_tuple):
        (a,) = a_tuple
        (b,) = b_tuple
        return (ops.mul(a, b),)
    kwargs = _make_scan_inner(x, axis=axis, dtype=dtype)
    (result,) = ir.Scan.create(**kwargs, combine_fn=combine_fn)
    if result is None:
        return fallback_cumprod(x, dim=axis, dtype=dtype)
    return result

def _fftn_wrapper(fft_n, default_name):
    """Wrapper around gen_spectral_ops.fftn."""

    def _fftn(input_tensor, fft_length=None, axes=None, norm=None, name=None):
        """Wrapper around gen_spectral_ops.*fft that infers fft_length and axes arguments."""
        with _ops.name_scope(name, default_name, [input_tensor, fft_length, axes]) as name:
            axes = _process_empty_axes(input_tensor, axes)
            fft_rank = axes.shape[0]
            input_tensor = _ops.convert_to_tensor(input_tensor, preferred_dtype=_dtypes.complex64)
            input_tensor.shape.with_rank_at_least(fft_rank)
            if <MASK>:
                fft_length = _infer_fft_length_for_fftn(input_tensor)
            else:
                fft_length = _ops.convert_to_tensor(fft_length, _dtypes.int32)
            input_tensor = _maybe_pad_for_rfft(input_tensor, fft_rank, fft_length)
            fft_length_static = _tensor_util.constant_value(fft_length)
            if fft_length_static is not None:
                fft_length = fft_length_static
            if norm is None:
                norm = 'backward'
            n = 1
            if norm != 'backward':
                for fft_length_i in fft_length:
                    n *= fft_length_i
                if norm == 'forward':
                    input_tensor /= n
                elif norm == 'ortho':
                    input_tensor /= np.sqrt(n)
            return fft_n(input_tensor, fft_length, axes, name=name)
    if fft_n.__doc__ is not None:
        _fftn.__doc__ = re.sub('    Tcomplex.*?\\n', '', fft_n.__doc__)
    return _fftn

