    return opt

def draft_export(mod: torch.nn.Module, args: tuple[Any, ...], kwargs: Optional[Mapping[str, Any]]=None, *, dynamic_shapes: Optional[Union[dict[str, Any], tuple[Any], list[Any]]]=None, preserve_module_call_signature: tuple[str, ...]=(), strict: bool=False, pre_dispatch: bool=True, prefer_deferred_runtime_asserts_over_guards: bool=False) -> ExportedProgram:
    start_time = time.time()
    kwargs = kwargs or {}
    dynamic_shapes = dynamic_shapes or {}
    constraint_violation_msg = None
    capture_structured_log = CaptureStructuredTrace()
    with torch._functorch.config.patch(fake_tensor_propagate_real_tensors=True, generate_fake_kernels_from_real_mismatches=True), capture_structured_log:
        try:
            new_shapes = None
            ep = _export(mod, args, kwargs, dynamic_shapes=dynamic_shapes, strict=strict, pre_dispatch=pre_dispatch, preserve_module_call_signature=preserve_module_call_signature, prefer_deferred_runtime_asserts_over_guards=prefer_deferred_runtime_asserts_over_guards)
        except Exception as exc:
            if <MASK>:
                constraint_violation_msg = exc.msg

                def convert_dim_to_auto(dim: Any) -> Any:
                    if isinstance(dim, Dim):
                        return Dim.AUTO(min=dim.min, max=dim.max)
                    elif isinstance(dim, _DimHint) and dim.type == _DimHintType.DYNAMIC:
                        return Dim.AUTO(min=dim.min, max=dim.max)
                    return dim
                new_shapes = pytree.tree_map(convert_dim_to_auto, dynamic_shapes)
                ep = _export(mod, args, kwargs, dynamic_shapes=new_shapes, strict=strict, pre_dispatch=pre_dispatch, preserve_module_call_signature=preserve_module_call_signature, prefer_deferred_runtime_asserts_over_guards=prefer_deferred_runtime_asserts_over_guards)
            else:
                log_draft_export_usage(error=True, export_time=time.time() - start_time, strict=strict, message=str(exc), type=f'{type(exc).__name__}.{type(exc).__qualname__}')
                raise exc
        torch._logging.dtrace_structured('exported_program', payload_fn=lambda : str(ep))
        str_to_filename: dict[int, str] = {}
        failures: list[FailureReport] = []
        incorrect_custom_ops: set[str] = set()
        expressions_created: dict[int, dict[str, Any]] = {}
        for (log_name, log_contents) in capture_structured_log.log_record.logs:
            failure_type = None
            if log_name == 'str':
                str_to_filename[log_contents[1]] = log_contents[0]
                continue
            elif log_name == 'propagate_real_tensors_provenance':
                log_contents['occurrences'] = capture_structured_log.log_record.get_log_count((log_name, log_contents))
                failure_type = FailureType.DATA_DEPENDENT_ERROR
            elif log_name == 'guard_added':
                if new_shapes is None:
                    continue
                failure_type = FailureType.GUARD_ADDED
                log_contents['new_dynamic_shapes'] = new_shapes
            elif log_name == 'missing_fake_kernel':
                failure_type = FailureType.MISSING_FAKE_KERNEL
                incorrect_custom_ops.add(log_contents['op'])
            elif log_name == 'mismatched_fake_kernel':
                failure_type = FailureType.MISMATCHED_FAKE_KERNEL
                incorrect_custom_ops.add(log_contents['op'])
            else:
                continue
            assert failure_type is not None
            failures.append(FailureReport(failure_type, log_contents))
        for (k, v) in capture_structured_log.expression_created_logs.items():
            if v.visited:
                expressions_created[k] = v.record
        op_profiles = get_op_profiles(ep.graph_module, incorrect_custom_ops)
        report = DraftExportReport(failures, str_to_filename, expressions_created, op_profiles)
        insert_custom_op_guards(ep.graph_module, incorrect_custom_ops)
    ep._report = report
    if not report.successful():
        log_filename = capture_structured_log.stream.name
        warning_msg = f'\n###################################################################################################\nWARNING: {len(report.failures)} issue(s) found during export, and it was not able to soundly produce a graph.\nTo view the report of failures in an html page, please run the command:\n    `tlparse {log_filename} --export`\nOr, you can view the errors in python by inspecting `print(ep._report)`.\n'
        if len(report.op_profiles) > 0:
            warning_msg += f'\nWhile tracing we found {len(report.op_profiles)} operator(s) which do not have a fake kernel registered.\nIf you intend to retrace the exported graph or run it with fake tensors, please run it under the\nfollowing context manager, which will register a fake kernel for those operators.\n```\nwith torch._library.fake_profile.unsafe_generate_fake_kernels(ep._report.op_profiles):\n    # run with fake tensors\n```\n'
        warning_msg += '#################################################################################################'
        log.warning(warning_msg)
    else:
        log.info('\n##############################################################################################\nCongratuations: No issues are found during export, and it was able to soundly produce a graph.\nYou can now change back to torch.export.export()\n##############################################################################################\n    ')
    log_draft_export_usage(error=False, export_time=time.time() - start_time, strict=strict, constraint_violations=constraint_violation_msg, report=ep._report, **get_ep_stats(ep))
    return ep

def _get_path_or_handle(path: FilePath | ReadBuffer[bytes] | WriteBuffer[bytes], fs: Any, storage_options: StorageOptions | None=None, mode: str='rb', is_dir: bool=False) -> tuple[FilePath | ReadBuffer[bytes] | WriteBuffer[bytes], IOHandles[bytes] | None, Any]:
    """File handling for PyArrow."""
    path_or_handle = stringify_path(path)
    if <MASK>:
        pa_fs = import_optional_dependency('pyarrow.fs', errors='ignore')
        fsspec = import_optional_dependency('fsspec', errors='ignore')
        if pa_fs is not None and isinstance(fs, pa_fs.FileSystem):
            if storage_options:
                raise NotImplementedError('storage_options not supported with a pyarrow FileSystem.')
        elif fsspec is not None and isinstance(fs, fsspec.spec.AbstractFileSystem):
            pass
        else:
            raise ValueError(f'filesystem must be a pyarrow or fsspec FileSystem, not a {type(fs).__name__}')
    if is_fsspec_url(path_or_handle) and fs is None:
        if storage_options is None:
            pa = import_optional_dependency('pyarrow')
            pa_fs = import_optional_dependency('pyarrow.fs')
            try:
                (fs, path_or_handle) = pa_fs.FileSystem.from_uri(path)
            except (TypeError, pa.ArrowInvalid):
                pass
        if fs is None:
            fsspec = import_optional_dependency('fsspec')
            (fs, path_or_handle) = fsspec.core.url_to_fs(path_or_handle, **storage_options or {})
    elif storage_options and (not is_url(path_or_handle) or mode != 'rb'):
        raise ValueError('storage_options passed with buffer, or non-supported URL')
    handles = None
    if not fs and (not is_dir) and isinstance(path_or_handle, str) and (not os.path.isdir(path_or_handle)):
        handles = get_handle(path_or_handle, mode, is_text=False, storage_options=storage_options)
        fs = None
        path_or_handle = handles.handle
    return (path_or_handle, handles, fs)

def replace_output(out):
    assert isinstance(spec, OutputSpec)
    if spec.type == 'user_output':
        arg = spec.user_output.arg
        if arg.type == 'as_tensor':
            t = arg.as_tensor
            t.name = replace_table[t.name]
        elif arg.type == 'as_sym_int':
            s = arg.as_sym_int
            if s.type == 'as_name':
                s.as_name = replace_table[s.as_name]
            elif s.type == 'as_int':
                pass
            else:
                raise AssertionError(f'Unknown sym_int type: {s}')
        elif arg.type == 'as_sym_float':
            f = arg.as_sym_float
            if f.type == 'as_name':
                f.as_name = replace_table[f.as_name]
            elif <MASK>:
                pass
            else:
                raise AssertionError(f'Unknown sym_float type: {f}')
        elif arg.type in ('as_none', 'as_bool', 'as_int', 'as_float', 'as_string'):
            return
        else:
            raise AssertionError(f'Unknown input type: {arg}')
    elif spec.type == 'loss_output':
        t = spec.loss_output.arg
        t.name = replace_table[t.name]
    elif spec.type == 'buffer_mutation':
        t = spec.buffer_mutation.arg
        t.name = replace_table[t.name]
    elif spec.type == 'parameter_mutation':
        t = spec.parameter_mutation.arg
        t.name = replace_table[t.name]
    elif spec.type == 'gradient_to_parameter':
        t = spec.gradient_to_parameter.arg
        t.name = replace_table[t.name]
    elif spec.type == 'gradient_to_user_input':
        g = spec.gradient_to_user_input
        g.arg.name = replace_table[g.arg.name]
        g.user_input_name = replace_table[g.user_input_name]
    elif spec.type == 'user_input_mutation':
        u = spec.user_input_mutation
        u.arg.name = replace_table[u.arg.name]
        u.user_input_name = replace_table[u.user_input_name]
    elif spec.type == 'token':
        tok = spec.token.arg
        tok.name = replace_table[tok.name]
    else:
        raise AssertionError(f'Unknown output type: {spec}')

def debug_str(self) -> str:
    result = IndentedBuffer()
    name = self.get_name()
    result.writeline(f'{name}: {type(self.node).__name__}')
    result.writeline(f'{name}.layout = {self.node.layout}')
    if <MASK>:
        result.writeline(f'{name}.aliases = {pformat(self.get_aliases())}')
    if self.get_mutations():
        result.writeline(f'{name}.mutations = {pformat(self.get_mutations())}')
    if len(self.users) <= 1:
        result.writeline(f'{name}.users = {self.users}')
    else:
        result.writeline(f'{name}.users = [')
        with result.indent(1):
            for user in self.users:
                result.writeline(f'{user},')
        result.writeline(']')
    return result.getrawvalue()

def _device(t):
    if <MASK>:
        nonlocal device
        if device is None:
            device = t.device
        elif device != t.device:
            raise ValueError('Device mismatch')
    return t

def merge_single_node(node: Node, node_order: Optional[int], id: Optional[int]):

    def _update_partition_map(node: Node, id: int):
        for user_node in node.users:
            target_id = assignment.get(user_node)
            if target_id is not None:
                partition_map[id].add(target_id)
                partition_map[id].update(partition_map[target_id])
    if node in assignment:
        partitions_by_id[assignment[node]].remove_node(node)
    if <MASK>:
        assignment.pop(node)
    elif id not in partitions_by_id:
        assignment[node] = id
        assert node_order is not None
        partitions_by_id[id] = Partition(id=id, nodes=[node], node_orders=[node_order])
        partition_users[id] = set(node.users)
        _update_partition_map(node, id)
    else:
        assignment[node] = id
        partitions_by_id[id].add_node(node, node_order)

def jagged_from_list(tensors: List[torch.Tensor], offsets: Optional[torch.Tensor], dtype=None, device=None) -> tuple[NestedTensor, torch.Tensor]:
    """Constructs a NestedTensor backed by jagged layout from a list of tensors"""
    if len(tensors) == 0:
        raise RuntimeError('Cannot construct a nested tensor from an empty tensor list')
    if not len(set((t.dtype for t in tensors))) == 1:
        raise RuntimeError('When constructing a nested tensor, all tensors in list must have the same dtype')
    if not len(set((t.device for t in tensors))) == 1:
        raise RuntimeError('When constructing a nested tensor, all tensors in list must be on the same device')
    if not len(set((t.dim() for t in tensors))) == 1:
        raise RuntimeError('When constructing a nested tensor, all tensors in list must have the same dim')
    component_dim = tensors[0].dim()
    if <MASK>:
        raise RuntimeError('Cannot construct a nested tensor from a list of zero-dim tensors')
    sizes = [t.shape for t in tensors]
    ragged_idx = None
    for d in range(component_dim):
        dim_is_ragged = any((size[d] != sizes[0][d] for size in sizes))
        if dim_is_ragged:
            if ragged_idx is None:
                ragged_idx = d + 1
            else:
                raise RuntimeError('Cannot represent given tensor list as a nested tensor with the jagged layout. Note that the jagged layout only allows for a single ragged dimension. For example: (B, *, D_0, D_1, ..., D_N), with ragged * dim.')
    if ragged_idx is None:
        ragged_idx = 1
    values = torch.cat(tensors, dim=ragged_idx - 1)
    to_kwargs = {}
    if device is not None:
        to_kwargs['device'] = device
    if dtype is not None:
        to_kwargs['dtype'] = dtype
    values = values.to(**to_kwargs)
    if offsets is None:
        offsets = torch.cat([torch.zeros(1, dtype=torch.int64, device=values.device), torch.tensor([s[ragged_idx - 1] for s in sizes], device=values.device).cumsum(dim=0)])
    min_seqlen = min((t.shape[ragged_idx - 1] for t in tensors))
    max_seqlen = max((t.shape[ragged_idx - 1] for t in tensors))
    ret_nt = nested_view_from_values_offsets(values, offsets, min_seqlen=min_seqlen, max_seqlen=max_seqlen, ragged_idx=ragged_idx)
    return (ret_nt, offsets)

@staticmethod
def handle_equal(args, kwargs) -> bool:
    """
        LocalShardsWrapper equal impl also checks for equality of storage metadata
        and the order of shards
        """
    (a, b) = (args[0], args[1])
    if <MASK>:
        return False
    if not all((aten.equal.default(x, y) for (x, y) in zip(a.local_shards(), b.local_shards()))):
        return False
    if a.storage_metadata() != b.storage_metadata():
        return False
    return True

def __init__(self, name: str, sources: Union[str, list[str]], BuildOption: BuildOptionsBase, output_dir: str='') -> None:
    self._compiler = ''
    self._cflags_args = ''
    self._definitions_args = ''
    self._include_dirs_args = ''
    self._ldflags_args = ''
    self._libraries_dirs_args = ''
    self._libraries_args = ''
    self._passthrough_parameters_args = ''
    self._orig_source_paths = []
    self._output_dir = ''
    self._target_file = ''
    self._use_relative_path: bool = False
    self._aot_mode: bool = False
    self._name = name
    self._target_name = config.aot_inductor.model_name_for_generated_files or 'aoti_model'
    self._build_option = BuildOption
    self._compiler = BuildOption.get_compiler()
    self._use_relative_path = BuildOption.get_use_relative_path()
    self._aot_mode = BuildOption.get_aot_mode()
    self._output_dir = output_dir
    self._compile_only = BuildOption.get_compile_only()
    self._precompiling = BuildOption.get_precompiling()
    self._preprocessing = BuildOption.get_preprocessing()
    assert sum((self._compile_only, self._precompiling, self._preprocessing)) <= 1
    self._do_link = not (self._compile_only or self._precompiling or self._preprocessing)
    assert not _IS_WINDOWS or not self._precompiling, 'Cannot currently precompile headers on Windows!'
    if self._compile_only:
        (file_ext, output_flags) = self.__get_object_flags()
    elif self._precompiling:
        (file_ext, output_flags) = self.__get_precompiled_header_flags()
    elif <MASK>:
        (file_ext, output_flags) = self.__get_preprocessor_output_flags()
    else:
        (file_ext, output_flags) = self.__get_python_module_flags()
    self._target_file = os.path.join(self._output_dir, f'{self._name}{file_ext}')
    relative_target_file = os.path.basename(self._target_file) if self._use_relative_path else self._target_file
    if _IS_WINDOWS:
        if self._preprocessing:
            self._output = output_flags
        else:
            self._output = f'{output_flags}{relative_target_file}'
    else:
        self._output = f'{output_flags} {relative_target_file}'
    if isinstance(sources, str):
        sources = [sources]
    if config.is_fbcode() and self._use_relative_path:
        self._orig_source_paths = list(sources)
        sources = [os.path.basename(i) for i in sources]
    if self._precompiling:
        assert len(sources) == 1
        self._sources_args = f'-x c++-header {sources[0]}'
    else:
        self._sources_args = ' '.join(sources)
    for cflag in BuildOption.get_cflags():
        if _IS_WINDOWS:
            self._cflags_args += f'/{cflag} '
        else:
            self._cflags_args += f'-{cflag} '
    for definition in BuildOption.get_definitions():
        if _IS_WINDOWS:
            self._definitions_args += f'/D {definition} '
        else:
            self._definitions_args += f'-D {definition} '
    if (precompiled_header := BuildOption.precompiled_header):
        if _IS_WINDOWS:
            log.warning('Precompiled header support for MSVC is currently unavailable; ignoring %s', precompiled_header)
        else:
            self._include_dirs_args = f'-include {precompiled_header} '
    for inc_dir in BuildOption.get_include_dirs():
        if _IS_WINDOWS:
            self._include_dirs_args += f'/I "{inc_dir}" '
        else:
            self._include_dirs_args += f'-I{shlex.quote(inc_dir)} '
    for ldflag in BuildOption.get_ldflags():
        if _IS_WINDOWS:
            self._ldflags_args += f'/{ldflag} '
        else:
            self._ldflags_args += f'-{ldflag} '
    for lib_dir in BuildOption.get_libraries_dirs():
        if _IS_WINDOWS:
            self._libraries_dirs_args += f'/LIBPATH:"{lib_dir}" '
        else:
            self._libraries_dirs_args += f'-L{lib_dir} '
    for lib in BuildOption.get_libraries():
        if _IS_WINDOWS:
            self._libraries_args += f'"{lib}.lib" '
        else:
            self._libraries_args += f'-l{lib} '
    for passthrough_arg in BuildOption.get_passthrough_args():
        self._passthrough_parameters_args += f'{passthrough_arg} '

