def _default_tolerance(dtype):
    """Returns a sensible default tolerance for comparing results of a given type.

  Args:
    dtype: A datatype.
  """
    if dtype == dtypes_lib.bfloat16.as_numpy_dtype:
        return 0.005
    if dtype == np.float16:
        return 0.005
    elif <MASK>:
        return 0.001
    elif dtype in (np.float64, np.complex128):
        return 1e-05
    else:
        return None

def _get_insert_freq(self, loc: int, item):
    """
        Find the `freq` for self.insert(loc, item).
        """
    value = self._data._validate_scalar(item)
    item = self._data._box_func(value)
    freq = None
    if self.freq is not None:
        if self.size:
            if item is NaT:
                pass
            elif <MASK>:
                freq = self.freq
            elif loc == len(self) and item - self.freq == self[-1]:
                freq = self.freq
        elif isinstance(self.freq, Tick):
            freq = self.freq
        elif self.freq.is_on_offset(item):
            freq = self.freq
    return freq

def shares_memory(left, right) -> bool:
    """
    Pandas-compat for np.shares_memory.
    """
    if isinstance(left, np.ndarray) and isinstance(right, np.ndarray):
        return np.shares_memory(left, right)
    elif isinstance(left, np.ndarray):
        return shares_memory(right, left)
    if isinstance(left, RangeIndex):
        return False
    if isinstance(left, MultiIndex):
        return shares_memory(left._codes, right)
    if <MASK>:
        if isinstance(right, (Index, Series)):
            return shares_memory(left._values, right._values)
        return shares_memory(left._values, right)
    if isinstance(left, NDArrayBackedExtensionArray):
        return shares_memory(left._ndarray, right)
    if isinstance(left, pd.core.arrays.SparseArray):
        return shares_memory(left.sp_values, right)
    if isinstance(left, pd.core.arrays.IntervalArray):
        return shares_memory(left._left, right) or shares_memory(left._right, right)
    if isinstance(left, ArrowExtensionArray):
        if isinstance(right, ArrowExtensionArray):
            left_pa_data = left._pa_array
            right_pa_data = right._pa_array
            left_buf1 = left_pa_data.chunk(0).buffers()[1]
            right_buf1 = right_pa_data.chunk(0).buffers()[1]
            return left_buf1.address == right_buf1.address
        else:
            return np.shares_memory(left, right)
    if isinstance(left, BaseMaskedArray) and isinstance(right, BaseMaskedArray):
        return np.shares_memory(left._data, right._data) or np.shares_memory(left._mask, right._mask)
    if isinstance(left, DataFrame) and len(left._mgr.blocks) == 1:
        arr = left._mgr.blocks[0].values
        return shares_memory(arr, right)
    raise NotImplementedError(type(left), type(right))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    """
        Fit the OrdinalEncoder to X.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            The data to determine the categories of each feature.

        y : None
            Ignored. This parameter exists only for compatibility with
            :class:`~sklearn.pipeline.Pipeline`.

        Returns
        -------
        self : object
            Fitted encoder.
        """
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif self.unknown_value is not None:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if self._infrequent_enabled:
        for (feature_idx, infrequent) in enumerate(self.infrequent_categories_):
            if <MASK>:
                cardinalities[feature_idx] -= len(infrequent)
    for (cat_idx, categories_for_idx) in enumerate(self.categories_):
        if is_scalar_nan(categories_for_idx[-1]):
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for (cat_idx, cardinality) in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

def remove_noop_ops(graph: torch.fx.Graph):
    """
    Removes both operations that are essentially aten.clone and operations that are essentially aten.alias from the graph.
    """
    inputs = OrderedSet[torch.fx.Node]()
    input_storages = OrderedSet[int | None]()
    output_storages = OrderedSet[int | None]()
    for node in graph.find_nodes(op='placeholder'):
        inputs.add(node)
        input_storages.add(get_node_storage(node))
    output_node = next(iter(reversed(graph.nodes)))
    assert output_node.op == 'output'
    outputs = output_node.args[0]
    if not isinstance(outputs, (list, tuple)):
        outputs = (outputs,)
    for out in outputs:
        if isinstance(out, torch.fx.Node):
            output_storages.add(get_node_storage(out))
    for node in graph.nodes:
        if node.target in noop_registry:
            (cond, src_index) = noop_registry[node.target]
            if isinstance(src_index, int):
                src = node.args[src_index]
            else:
                src = src_index(node.args)
            if not isinstance(src, torch.fx.Node):
                continue
            node_storage = get_node_storage(node)
            src_storage = get_node_storage(src)
            node_is_view = node_storage == src_storage
            if <MASK>:
                continue
            if node_is_view and node in output_node.args and (src in inputs or src in output_node.args):
                continue
            (is_valid, args, kwargs) = get_fake_args_kwargs(node)
            if not is_valid:
                continue
            if same_meta(node, src) and cond(*args, **kwargs):
                node.replace_all_uses_with(src)
                graph.erase_node(node)

def generate_graph_based_transform_infos(self, src_spec: DTensorSpec, dst_spec: DTensorSpec, full_tensor_shape: tuple[int, ...]) -> list[_TransformInfo]:
    assert src_spec.shard_order is not None and dst_spec.shard_order is not None
    src_state = self.DistState(src_spec.placements, src_spec.shard_order)
    dst_state = self.DistState(dst_spec.placements, dst_spec.shard_order)
    transform_infos: list[_TransformInfo] = []
    state_path = self.find_min_cost_path(src_state, dst_state)
    for (cur_state, nxt_state) in itertools.pairwise(state_path):
        if cur_state.placements != nxt_state.placements:
            update_mesh_dim = -1
            for (mesh_dim, (cur_placement, nxt_placement)) in enumerate(zip(cur_state.placements, nxt_state.placements)):
                if cur_placement != nxt_placement:
                    if <MASK>:
                        raise AssertionError('Multiple mesh_dims are different between cur_state and nxt_state')
                    update_mesh_dim = mesh_dim
                    logical_shape = self.get_logical_shape(cur_state, mesh_dim, full_tensor_shape)
                    transform_infos.append(_TransformInfo(mesh_dim=update_mesh_dim, src_dst_placements=(cur_placement, nxt_placement), logical_shape=logical_shape))
    return transform_infos

