        self._testRelu(np.array([[-9, 7, -5, 3, -1], [1, -3, 5, -7, 9]]).astype(t))

@dispatch.dispatch_for_api(math_ops.matmul)
def matmul(a: ragged_tensor.RaggedOrDense, b: ragged_tensor.RaggedOrDense, transpose_a=False, transpose_b=False, adjoint_a=False, adjoint_b=False, a_is_sparse=False, b_is_sparse=False, output_type=None, grad_a=False, grad_b=False, name=None):
    """Multiplies matrix `a` by matrix `b`.

  If all transpose or adjoint attributes are `False` then:

  ```
  output[..., i, j] = sum_k (a[..., i, k] * b[..., k, j]), for all indices i, j.
  ```

  The inputs `a` and `b` must have `rank >= 2`, where the outermost `rank - 2`
  dimensions are batch dimensions.  The inputs must have the same dtype.  See
  `tf.matmul` for more information.

  Args:
    a: `tf.Tensor` or `RaggedTensor` with `rank > 1`.
    b: `tf.Tensor` or `RaggedTensor` with same type and rank as `a`.
    transpose_a: If `True`, `a` is transposed before multiplication.
    transpose_b: If `True`, `b` is transposed before multiplication.
    adjoint_a: If `True`, `a` is conjugated & transposed before multiplication.
    adjoint_b: If `True`, `b` is conjugated & transposed before multiplication.
    a_is_sparse: If `True`, optimize assuming `a` is mostly zero.
    b_is_sparse: If `True`, optimize assuming `b` is mostly zero.
    output_type: The output datatype (optional).
    grad_a: Unused.
    grad_b: Unused.
    name: Name for the operation (optional).

  Returns:
    A `Tensor` or `RaggedTensor` with the same rank and shape as `a`, where
    each inner-most matrix is the product of the corresponding matrices in `a`
    and `b`.
  """
    del grad_a
    del grad_b
    if transpose_a and adjoint_a:
        raise ValueError('Only one of transpose_a and adjoint_a can be True.')
    if transpose_b and adjoint_b:
        raise ValueError('Only one of transpose_b and adjoint_b can be True.')
    kwargs = dict(transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b, a_is_sparse=a_is_sparse, b_is_sparse=b_is_sparse, output_type=output_type)
    with ops.name_scope(name, 'RaggedMatMul', [a, b]) as name:
        a = ragged_tensor.convert_to_tensor_or_ragged_tensor(a, name='a')
        b = ragged_tensor.convert_to_tensor_or_ragged_tensor(b, name='b')
        a_is_ragged = isinstance(a, ragged_tensor.RaggedTensor)
        b_is_ragged = isinstance(b, ragged_tensor.RaggedTensor)
        if not (a_is_ragged or b_is_ragged):
            return math_ops.matmul(a, b, **kwargs)
        if a.dtype != b.dtype:
            raise ValueError('`a` and `b` must have the same dtype.')
        if a.shape.rank is None:
            if b.shape.rank is None:
                raise ValueError('matmul requires at least one input to have known rank if either input is ragged.')
            rank = b.shape.rank
        else:
            if <MASK>:
                raise ValueError('`a` and `b` must have the same rank.')
            rank = a.shape.rank
        if rank < 2:
            raise ValueError('`a` and `b` must have the same rank.')
        if rank > 3:
            shape_err = 'Batch dimensions of `a` and `b` do not have the same size.'
            if not a_is_ragged:
                a = ragged_tensor.RaggedTensor.from_tensor(a, ragged_rank=1)
            if not b_is_ragged:
                b = ragged_tensor.RaggedTensor.from_tensor(b, ragged_rank=1)
            with ops.control_dependencies([check_ops.assert_equal(a.row_splits, b.row_splits, message=shape_err)]):
                flat_result = matmul(a.values, b.values, **kwargs)
                return a.with_values(flat_result)
        if rank == 2:
            return _matmul_2d(a, b, **kwargs)
        assert rank == 3
        a_ragged_rank = a.ragged_rank if a_is_ragged else 0
        if a_ragged_rank == 1 and (not (b_is_ragged or transpose_a or adjoint_a)):
            return _matmul_3d_with_batch_dim_folding(a, b, **kwargs)
        else:
            return _matmul_3d_with_map_fn(a, b, **kwargs)

def _fix_stop_index(index, rank):
    """Slice indexes are always silently truncated."""
    if index is None:
        if rank is None:
            raise ValueError('Rank must be known to use __getitem__ without a stop.')
        index = rank
    if <MASK>:
        if rank is None:
            raise ValueError('Rank must be known to use __getitem__ on a negative index.')
        index = rank + index
    if index < 0:
        index = 0
    if rank is not None:
        index = min(rank, index)
    return index

@final
def _drop_axis(self, labels, axis, level=None, errors: IgnoreRaise='raise', only_slice: bool=False) -> Self:
    """
        Drop labels from specified axis. Used in the ``drop`` method
        internally.

        Parameters
        ----------
        labels : single label or list-like
        axis : int or axis name
        level : int or level name, default None
            For MultiIndex
        errors : {'ignore', 'raise'}, default 'raise'
            If 'ignore', suppress error and existing labels are dropped.
        only_slice : bool, default False
            Whether indexing along columns should be view-only.

        """
    axis_num = self._get_axis_number(axis)
    axis = self._get_axis(axis)
    if <MASK>:
        if level is not None:
            if not isinstance(axis, MultiIndex):
                raise AssertionError('axis must be a MultiIndex')
            new_axis = axis.drop(labels, level=level, errors=errors)
        else:
            new_axis = axis.drop(labels, errors=errors)
        indexer = axis.get_indexer(new_axis)
    else:
        is_tuple_labels = is_nested_list_like(labels) or isinstance(labels, tuple)
        labels = ensure_object(common.index_labels_to_array(labels))
        if level is not None:
            if not isinstance(axis, MultiIndex):
                raise AssertionError('axis must be a MultiIndex')
            mask = ~axis.get_level_values(level).isin(labels)
            if errors == 'raise' and mask.all():
                raise KeyError(f'{labels} not found in axis')
        elif isinstance(axis, MultiIndex) and labels.dtype == 'object' and (not is_tuple_labels):
            mask = ~axis.get_level_values(0).isin(labels)
        else:
            mask = ~axis.isin(labels)
            labels_missing = (axis.get_indexer_for(labels) == -1).any()
            if errors == 'raise' and labels_missing:
                raise KeyError(f'{labels} not found in axis')
        if isinstance(mask.dtype, ExtensionDtype):
            mask = mask.to_numpy(dtype=bool)
        indexer = mask.nonzero()[0]
        new_axis = axis.take(indexer)
    bm_axis = self.ndim - axis_num - 1
    new_mgr = self._mgr.reindex_indexer(new_axis, indexer, axis=bm_axis, allow_dups=True, only_slice=only_slice)
    result = self._constructor_from_mgr(new_mgr, axes=new_mgr.axes)
    if self.ndim == 1:
        result._name = self.name
    return result.__finalize__(self)

@constraints.dependent_property(is_discrete=False)
def codomain(self):
    if not self.parts:
        return constraints.real
    codomain = self.parts[-1].codomain
    event_dim = self.parts[0].domain.event_dim
    for part in self.parts:
        event_dim += part.codomain.event_dim - part.domain.event_dim
        event_dim = max(event_dim, part.codomain.event_dim)
    assert event_dim >= codomain.event_dim
    if <MASK>:
        codomain = constraints.independent(codomain, event_dim - codomain.event_dim)
    return codomain

def _reduce_ex_internal(self, proto):
    check_serializing_named_tensor(self)
    from torch.utils.hooks import warn_if_has_hooks
    warn_if_has_hooks(self)
    backward_hooks: dict[Any, Any] = OrderedDict()
    skip_data = torch.serialization._serialization_tls.skip_data
    materialize_fake_tensors = torch.serialization._serialization_tls.materialize_fake_tensors
    if self.device.type in ['xla', 'maia', 'mtia'] or (not torch._C._has_storage(self) and self.device.type == torch._C._get_privateuse1_backend_name()):
        if skip_data:
            raise RuntimeError('Cannot serialize tensors on backends with no storage under skip_data context manager')
        cpu_tensor = self.cpu()
        return (torch._utils._rebuild_device_tensor_from_cpu_tensor, (cpu_tensor, self.dtype, str(self.device), self.requires_grad))
    if self.device.type == 'meta':
        if skip_data:
            warnings.warn('Serializing tensors on the meta device under skip_data context manager is a no-op')
        arg_meta = (self.dtype, tuple(self.size()), self.stride(), self.requires_grad)
        return (torch._utils._rebuild_meta_tensor_no_storage, arg_meta)
    if self.is_quantized:
        if skip_data:
            raise RuntimeError('Cannot serialize qtensor under skip_data context manager, file an issue if you need this feature')
        quantizer_params: Union[tuple[torch.qscheme, float, int], tuple[Any, Tensor, Tensor, int]]
        if self.qscheme() == torch.per_tensor_affine:
            quantizer_params = (torch.per_tensor_affine, self.q_scale(), self.q_zero_point())
        elif self.qscheme() in (torch.per_channel_affine, torch.per_channel_affine_float_qparams):
            quantizer_params = (torch.per_channel_affine, self.q_per_channel_scales(), self.q_per_channel_zero_points(), self.q_per_channel_axis())
        else:
            raise RuntimeError(f'Serialization is not supported for tensors of type {self.qscheme()}')
        args_qtensor = (torch.storage.TypedStorage(wrap_storage=self._typed_storage()._untyped_storage, dtype=self.dtype, _internal=True), self.storage_offset(), tuple(self.size()), self.stride(), quantizer_params, self.requires_grad, backward_hooks)
        return (torch._utils._rebuild_qtensor, args_qtensor)
    elif self.is_sparse:
        if self.layout == torch.sparse_coo:
            args_sparse = (self.layout, (self._indices(), self._values(), self.size(), self.is_coalesced()))
        else:
            raise NotImplementedError(f'sparse tensor __reduce_ex__ for layout `{self.layout}`')
        return (torch._utils._rebuild_sparse_tensor, args_sparse)
    elif self.layout in {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}:
        if self.layout in {torch.sparse_csr, torch.sparse_bsr}:
            (compressed_indices, plain_indices) = (self.crow_indices(), self.col_indices())
        else:
            (compressed_indices, plain_indices) = (self.ccol_indices(), self.row_indices())
        args_sparse_compressed = (self.layout, (compressed_indices, plain_indices, self.values(), self.size()))
        return (torch._utils._rebuild_sparse_tensor, args_sparse_compressed)
    elif <MASK>:
        if skip_data:
            raise RuntimeError('Cannot serialize nested tensor under skip_data context manager, file an issue if you need this feature')
        args_nested = (self.values(), self._nested_tensor_size(), self._nested_tensor_strides(), self._nested_tensor_storage_offsets())
        return (torch._utils._rebuild_nested_tensor, args_nested)
    elif type(self) is not torch.Tensor and type(self).__torch_dispatch__ is not torch.Tensor.__torch_dispatch__ and (isinstance(self, torch._subclasses.functional_tensor.FunctionalTensor) or (not isinstance(self, torch._subclasses.fake_tensor.FakeTensor) and self.data_ptr() == 0)):
        arg_wrapper_subclass = (type(self), self.dtype, tuple(self.size()), self.stride(), self.storage_offset(), self.layout, self.device, self.requires_grad)
        return (torch._utils._rebuild_wrapper_subclass, arg_wrapper_subclass)
    elif type(self) is not torch.Tensor and type(self).__torch_dispatch__ is not torch.Tensor.__torch_dispatch__ and (isinstance(self, torch._subclasses.fake_tensor.FakeTensor) and (not (skip_data and materialize_fake_tensors))):
        arg_wrapper_subclass = (type(self), self.dtype, tuple(self.size()), self.stride(), self.storage_offset(), self.layout, self.device, self.requires_grad)
        return (torch._utils._rebuild_wrapper_subclass, arg_wrapper_subclass)
    else:
        v3_dtypes = torch.storage._new_dtypes()
        if self.dtype in v3_dtypes:
            rebuild_func = torch._utils._rebuild_tensor_v3
            storage = self.untyped_storage()
        else:
            rebuild_func = torch._utils._rebuild_tensor_v2
            storage = torch.storage.TypedStorage(wrap_storage=self._typed_storage()._untyped_storage, dtype=self.dtype, _internal=True)
        if hasattr(torch, '_subclasses') and isinstance(self, torch._subclasses.fake_tensor.FakeTensor) and skip_data:
            storage._fake_device = self.device
        args = (storage, self.storage_offset(), tuple(self.size()), self.stride(), self.requires_grad, backward_hooks)
        if isinstance(storage, torch.storage.UntypedStorage):
            args = args + (self.dtype,)
        metadata = torch._utils.get_tensor_metadata(self)
        if metadata:
            args = args + (metadata,)
        return (rebuild_func, args)

@register_decomposition([aten.squeeze.default, aten.squeeze.dim])
def squeeze_default(self: Tensor, dim: Optional[int]=None):
    if <MASK>:
        return self
    if dim is None:
        return aten.squeeze.dims(self, list(range(self.dim())))
    else:
        return aten.squeeze.dims(self, [dim])

def deserialize_output_spec(self, o: OutputSpec) -> ep.OutputSpec:
    log.debug('[deserialize_output_spec] %s', o)
    if o.type == 'user_output':
        return ep.OutputSpec(kind=ep.OutputKind.USER_OUTPUT, arg=self.deserialize_argument_spec(o.user_output.arg), target=None)
    elif o.type == 'loss_output':
        return ep.OutputSpec(kind=ep.OutputKind.LOSS_OUTPUT, arg=ep.TensorArgument(name=o.loss_output.arg.name), target=None)
    elif o.type == 'buffer_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.BUFFER_MUTATION, arg=ep.TensorArgument(name=o.buffer_mutation.arg.name), target=o.buffer_mutation.buffer_name)
    elif o.type == 'parameter_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.PARAMETER_MUTATION, arg=ep.TensorArgument(name=o.parameter_mutation.arg.name), target=o.parameter_mutation.parameter_name)
    elif o.type == 'gradient_to_parameter':
        return ep.OutputSpec(kind=ep.OutputKind.GRADIENT_TO_PARAMETER, arg=ep.TensorArgument(name=o.gradient_to_parameter.arg.name), target=o.gradient_to_parameter.parameter_name)
    elif o.type == 'gradient_to_user_input':
        return ep.OutputSpec(kind=ep.OutputKind.GRADIENT_TO_USER_INPUT, arg=ep.TensorArgument(name=o.gradient_to_user_input.arg.name), target=o.gradient_to_user_input.user_input_name)
    elif o.type == 'user_input_mutation':
        return ep.OutputSpec(kind=ep.OutputKind.USER_INPUT_MUTATION, arg=ep.TensorArgument(name=o.user_input_mutation.arg.name), target=o.user_input_mutation.user_input_name)
    elif <MASK>:
        return ep.OutputSpec(kind=ep.OutputKind.TOKEN, arg=ep.TokenArgument(name=o.token.arg.name), target=None)
    else:
        raise AssertionError(f'Unknown output spec {o}')

@wraps(func)
def compile_func(parser, token):
    tag_params = params.copy()
    if takes_context:
        if len(tag_params) >= 2 and tag_params[1] == 'content':
            del tag_params[1]
        else:
            raise TemplateSyntaxError(f"{function_name!r} is decorated with takes_context=True so it must have a first argument of 'context' and a second argument of 'content'")
    elif <MASK>:
        del tag_params[0]
    else:
        raise TemplateSyntaxError(f"'{function_name}' must have a first argument of 'content'")
    bits = token.split_contents()[1:]
    target_var = None
    if len(bits) >= 2 and bits[-2] == 'as':
        target_var = bits[-1]
        bits = bits[:-2]
    nodelist = parser.parse((end_name,))
    parser.delete_first_token()
    (args, kwargs) = parse_bits(parser, bits, tag_params, varargs, varkw, defaults, kwonly, kwonly_defaults, takes_context, function_name)
    return SimpleBlockNode(nodelist, func, takes_context, args, kwargs, target_var)

@dispatch.dispatch_for_api(math_ops.matmul)
def matmul(a: ragged_tensor.RaggedOrDense, b: ragged_tensor.RaggedOrDense, transpose_a=False, transpose_b=False, adjoint_a=False, adjoint_b=False, a_is_sparse=False, b_is_sparse=False, output_type=None, grad_a=False, grad_b=False, name=None):
    """Multiplies matrix `a` by matrix `b`.

  If all transpose or adjoint attributes are `False` then:

  ```
  output[..., i, j] = sum_k (a[..., i, k] * b[..., k, j]), for all indices i, j.
  ```

  The inputs `a` and `b` must have `rank >= 2`, where the outermost `rank - 2`
  dimensions are batch dimensions.  The inputs must have the same dtype.  See
  `tf.matmul` for more information.

  Args:
    a: `tf.Tensor` or `RaggedTensor` with `rank > 1`.
    b: `tf.Tensor` or `RaggedTensor` with same type and rank as `a`.
    transpose_a: If `True`, `a` is transposed before multiplication.
    transpose_b: If `True`, `b` is transposed before multiplication.
    adjoint_a: If `True`, `a` is conjugated & transposed before multiplication.
    adjoint_b: If `True`, `b` is conjugated & transposed before multiplication.
    a_is_sparse: If `True`, optimize assuming `a` is mostly zero.
    b_is_sparse: If `True`, optimize assuming `b` is mostly zero.
    output_type: The output datatype (optional).
    grad_a: Unused.
    grad_b: Unused.
    name: Name for the operation (optional).

  Returns:
    A `Tensor` or `RaggedTensor` with the same rank and shape as `a`, where
    each inner-most matrix is the product of the corresponding matrices in `a`
    and `b`.
  """
    del grad_a
    del grad_b
    if transpose_a and adjoint_a:
        raise ValueError('Only one of transpose_a and adjoint_a can be True.')
    if transpose_b and adjoint_b:
        raise ValueError('Only one of transpose_b and adjoint_b can be True.')
    kwargs = dict(transpose_a=transpose_a, transpose_b=transpose_b, adjoint_a=adjoint_a, adjoint_b=adjoint_b, a_is_sparse=a_is_sparse, b_is_sparse=b_is_sparse, output_type=output_type)
    with ops.name_scope(name, 'RaggedMatMul', [a, b]) as name:
        a = ragged_tensor.convert_to_tensor_or_ragged_tensor(a, name='a')
        b = ragged_tensor.convert_to_tensor_or_ragged_tensor(b, name='b')
        a_is_ragged = isinstance(a, ragged_tensor.RaggedTensor)
        b_is_ragged = isinstance(b, ragged_tensor.RaggedTensor)
        if not (a_is_ragged or b_is_ragged):
            return math_ops.matmul(a, b, **kwargs)
        if <MASK>:
            raise ValueError('`a` and `b` must have the same dtype.')
        if a.shape.rank is None:
            if b.shape.rank is None:
                raise ValueError('matmul requires at least one input to have known rank if either input is ragged.')
            rank = b.shape.rank
        else:
            if b.shape.rank is not None and a.shape.rank != b.shape.rank:
                raise ValueError('`a` and `b` must have the same rank.')
            rank = a.shape.rank
        if rank < 2:
            raise ValueError('`a` and `b` must have the same rank.')
        if rank > 3:
            shape_err = 'Batch dimensions of `a` and `b` do not have the same size.'
            if not a_is_ragged:
                a = ragged_tensor.RaggedTensor.from_tensor(a, ragged_rank=1)
            if not b_is_ragged:
                b = ragged_tensor.RaggedTensor.from_tensor(b, ragged_rank=1)
            with ops.control_dependencies([check_ops.assert_equal(a.row_splits, b.row_splits, message=shape_err)]):
                flat_result = matmul(a.values, b.values, **kwargs)
                return a.with_values(flat_result)
        if rank == 2:
            return _matmul_2d(a, b, **kwargs)
        assert rank == 3
        a_ragged_rank = a.ragged_rank if a_is_ragged else 0
        if a_ragged_rank == 1 and (not (b_is_ragged or transpose_a or adjoint_a)):
            return _matmul_3d_with_batch_dim_folding(a, b, **kwargs)
        else:
            return _matmul_3d_with_map_fn(a, b, **kwargs)

@prof
def _monitor_workers(self, worker_group: WorkerGroup) -> RunResult:
    role = worker_group.spec.role
    worker_pids = {w.id for w in worker_group.workers}
    assert self._pcontext is not None
    pc_pids = set(self._pcontext.pids().values())
    if worker_pids != pc_pids:
        logger.error('[%s] worker pids do not match process_context pids. Expected: %s, actual: %s', role, worker_pids, pc_pids)
        return RunResult(state=WorkerState.UNKNOWN)
    result = self._pcontext.wait(0)
    if result:
        if <MASK>:
            worker_failures = {}
            for (local_rank, failure) in result.failures.items():
                worker = worker_group.workers[local_rank]
                worker_failures[worker.global_rank] = failure
            return RunResult(state=WorkerState.FAILED, failures=worker_failures)
        else:
            workers_ret_vals = {}
            for (local_rank, ret_val) in result.return_values.items():
                worker = worker_group.workers[local_rank]
                workers_ret_vals[worker.global_rank] = ret_val
            return RunResult(state=WorkerState.SUCCEEDED, return_values=workers_ret_vals)
    else:
        return RunResult(state=WorkerState.HEALTHY)

def _createV2QATLowBitKerasModel(self, shape, weight_only, num_bits, bit_min, bit_max):
    """Creates a simple QAT num_bits-Weight Keras Model."""
    input_name = 'input'
    output_name = 'scores'

    class ConvWrapper(tf.keras.layers.Wrapper):
        """A Wrapper for simulating QAT on Conv2D layers."""

        def build(self, input_shape):
            if not self.layer.built:
                self.layer.build(input_shape)
            self.quantized_weights = self.layer.kernel

        def call(self, inputs):
            self.layer.kernel = tf.quantization.fake_quant_with_min_max_vars_per_channel(self.quantized_weights, min=[bit_min], max=[bit_max], num_bits=num_bits, narrow_range=True)
            if <MASK>:
                quant_inputs = tf.quantization.fake_quant_with_min_max_vars(inputs, min=0, max=6, num_bits=8)
                outputs = self.layer.call(quant_inputs)
                return tf.quantization.fake_quant_with_min_max_vars(outputs, min=0, max=6, num_bits=8)
            return self.layer.call(inputs)
    input_tensor = tf.keras.layers.Input(shape, name=input_name)
    kernel_shape = (shape[-1], 3, 3, 1)
    initial_weights = np.linspace(bit_min, bit_max, np.prod(kernel_shape)).reshape(kernel_shape)
    test_initializer = tf.constant_initializer(initial_weights)
    x = ConvWrapper(tf.keras.layers.Conv2D(1, (3, 3), kernel_initializer=test_initializer, activation='relu6'))(input_tensor)
    scores = tf.keras.layers.Flatten(name=output_name)(x)
    model = tf.keras.Model(input_tensor, scores)
    return (model, input_name, output_name)

def install_config_module(module: ModuleType) -> None:
    """
    Converts a module-level config into a `ConfigModule()`.

    See _config_typing.pyi for instructions on how to get the converted module to typecheck.
    """

    class ConfigModuleInstance(ConfigModule):
        _bypass_keys = set({'_is_dirty', '_hash_digest', '__annotations__'})

    def visit(source: Union[ModuleType, type], dest: Union[ModuleType, SubConfigProxy], prefix: str) -> None:
        """Walk the module structure and move everything to module._config"""
        type_hints = inspect.get_annotations(source)
        for (key, value) in list(source.__dict__.items()):
            if key.startswith('__') or isinstance(value, (ModuleType, FunctionType)) or (hasattr(value, '__module__') and value.__module__ == 'typing') or (isinstance(value, type) and issubclass(value, _Config)):
                continue
            name = f'{prefix}{key}'
            annotated_type = type_hints.get(key, None)
            if isinstance(value, CONFIG_TYPES):
                config[name] = _ConfigEntry(_Config(default=value, value_type=annotated_type))
                if <MASK>:
                    delattr(module, key)
            elif isinstance(value, _Config):
                if annotated_type is not None and value.value_type is None:
                    value.value_type = annotated_type
                config[name] = _ConfigEntry(value)
                if dest is module:
                    delattr(module, key)
            elif isinstance(value, type):
                assert value.__module__ == module.__name__
                proxy = SubConfigProxy(module, f'{name}.')
                visit(value, proxy, f'{name}.')
                if dest is module:
                    setattr(dest, key, proxy)
                else:
                    dest.__dict__[key] = proxy
            else:
                raise AssertionError(f'Unhandled config {key}={value} ({type(value)})')
    config: dict[str, _ConfigEntry] = {}
    compile_ignored_keys = get_assignments_with_compile_ignored_comments(module)
    visit(module, module, '')
    module._config = config
    module._compile_ignored_keys = compile_ignored_keys
    module.__class__ = ConfigModuleInstance
    module._is_dirty = True
    module._hash_digest = None

def _raw_fft(a, n, axis, is_real, is_forward, norm, out=None):
    if n < 1:
        raise ValueError(f'Invalid number of FFT data points ({n}) specified.')
    if not is_forward:
        norm = _swap_direction(norm)
    real_dtype = result_type(a.real.dtype, 1.0)
    if norm is None or norm == 'backward':
        fct = 1
    elif norm == 'ortho':
        fct = reciprocal(sqrt(n, dtype=real_dtype))
    elif norm == 'forward':
        fct = reciprocal(n, dtype=real_dtype)
    else:
        raise ValueError(f'Invalid norm value {norm}; should be "backward","ortho" or "forward".')
    n_out = n
    if <MASK>:
        if is_forward:
            ufunc = pfu.rfft_n_even if n % 2 == 0 else pfu.rfft_n_odd
            n_out = n // 2 + 1
        else:
            ufunc = pfu.irfft
    else:
        ufunc = pfu.fft if is_forward else pfu.ifft
    axis = normalize_axis_index(axis, a.ndim)
    if out is None:
        if is_real and (not is_forward):
            out_dtype = real_dtype
        else:
            out_dtype = result_type(a.dtype, 1j)
        out = empty_like(a, shape=a.shape[:axis] + (n_out,) + a.shape[axis + 1:], dtype=out_dtype)
    elif (shape := getattr(out, 'shape', None)) is not None and (len(shape) != a.ndim or shape[axis] != n_out):
        raise ValueError('output array has wrong shape.')
    return ufunc(a, fct, axes=[(axis,), (), (axis,)], out=out)

def __torch_dispatch__(self, func, types, args=(), kwargs=None):

    def unwrap(e):
        return e.elem if isinstance(e, CompositeCompliantTensor) else e

    def wrap(e):
        return CompositeCompliantTensor(e, self) if isinstance(e, torch.Tensor) else e
    if func == torch.ops.aten._local_scalar_dense.default:
        raise RuntimeError('.item() is not allowed to be called inside of composite functions in the PyTorch library because not all backends and/or Tensor subclasses (e.g. vmap, ProxyTensor) support them.')
    if func.overloadpacket.__name__ in ('set_', 'resize_'):
        raise RuntimeError(f'{func.__name__} is not allowed to be called inside of Composite operators.')
    if is_inplace(func):
        mutated_argument = args[0]
        if not isinstance(mutated_argument, CompositeCompliantTensor) and any((isinstance(a, CompositeCompliantTensor) for a in args[1:])):
            raise RuntimeError(f'Not composite compliant: performing in-place operation {func.__name__} where the Tensor being written to is regular Tensor but the other tensors are Tensor Subclasses. Please try to avoid this in-place operation.')
    unwrapped_args = tree_map(unwrap, args)
    unwrapped_kwargs = tree_map(unwrap, kwargs)
    unwrapped_rs = func(*unwrapped_args, **unwrapped_kwargs)
    rs = tree_map(wrap, unwrapped_rs)
    if is_view_fn(func) and autograd_view_consistency:
        with no_dispatch():
            result = func(*args, **kwargs)
            if <MASK>:
                for (a, b) in zip(rs, result, strict=True):
                    a.set_(b)
            else:
                rs.set_(result)
    with no_dispatch():
        if is_inplace_view_fn(func):
            func(*args, **kwargs)
    check = partial(check_metadata_consistency, CCT=CompositeCompliantTensor)
    pytree.tree_map_(check, args)
    pytree.tree_map_(check, kwargs)
    pytree.tree_map_(check, rs)
    return rs

def _cast_pointwise_result(self, values) -> ArrayLike:
    if len(values) == 0:
        return self[:0].copy()
    try:
        if self.dtype.kind in 'iufc' and (not is_nan_na()):
            values = np.asarray(values, dtype=object)
            mask = is_pdna_or_none(values)
            arr = pa.array(values, mask=mask)
        else:
            arr = pa.array(values, from_pandas=True)
    except (ValueError, TypeError):
        return super()._cast_pointwise_result(values)
    if pa.types.is_null(arr.type):
        if lib.infer_dtype(values) == 'decimal':
            arr = arr.cast(pa.decimal128(1))
    if <MASK>:
        result = ArrowExtensionArray._from_sequence(values)
        if pa.types.is_duration(self._pa_array.type):
            result = result.astype(self.dtype)
        elif pa.types.is_timestamp(self._pa_array.type):
            new_dtype = ArrowDtype(pa.duration(self._pa_array.type.unit))
            try:
                result = result.astype(new_dtype)
            except ValueError:
                pass
        elif pa.types.is_date64(self._pa_array.type):
            dtype = ArrowDtype(pa.duration('ms'))
            result = result.astype(dtype)
        elif pa.types.is_date(self._pa_array.type):
            dtype = ArrowDtype(pa.duration('s'))
            result = result.astype(dtype)
        return result
    elif pa.types.is_date(arr.type) and pa.types.is_date(self._pa_array.type):
        arr = arr.cast(self._pa_array.type)
    elif pa.types.is_time(arr.type) and pa.types.is_time(self._pa_array.type):
        arr = arr.cast(self._pa_array.type)
    elif pa.types.is_decimal(arr.type) and pa.types.is_decimal(self._pa_array.type):
        arr = arr.cast(self._pa_array.type)
    elif pa.types.is_integer(arr.type) and pa.types.is_integer(self._pa_array.type):
        try:
            arr = arr.cast(self._pa_array.type)
        except pa.lib.ArrowInvalid:
            pass
    elif pa.types.is_floating(arr.type) and pa.types.is_floating(self._pa_array.type):
        try:
            arr = arr.cast(self._pa_array.type)
        except pa.lib.ArrowInvalid:
            pass
    if isinstance(self.dtype, StringDtype):
        if pa.types.is_string(arr.type) or pa.types.is_large_string(arr.type):
            return self._from_pyarrow_array(arr)
        if self.dtype.na_value is np.nan:
            return super()._cast_pointwise_result(values)
        return ArrowExtensionArray(arr)
    return self._from_pyarrow_array(arr)

@wraps(fn)
def dep_fn(slf, *args, **kwargs):
    if self.device_type is None or self.device_type == slf.device_type or (isinstance(self.device_type, Iterable) and slf.device_type in self.device_type):
        if <MASK>:
            raise unittest.SkipTest(self.reason)
    return fn(slf, *args, **kwargs)

def migration_progress_callback(self, action, migration=None, fake=False):
    if self.verbosity >= 1:
        compute_time = self.verbosity > 1
        if action == 'apply_start':
            if compute_time:
                self.start = time.monotonic()
            self.stdout.write('  Applying %s...' % migration, ending='')
            self.stdout.flush()
        elif action == 'apply_success':
            elapsed = ' (%.3fs)' % (time.monotonic() - self.start) if compute_time else ''
            if fake:
                self.stdout.write(self.style.SUCCESS(' FAKED' + elapsed))
            else:
                self.stdout.write(self.style.SUCCESS(' OK' + elapsed))
        elif <MASK>:
            if compute_time:
                self.start = time.monotonic()
            self.stdout.write('  Unapplying %s...' % migration, ending='')
            self.stdout.flush()
        elif action == 'unapply_success':
            elapsed = ' (%.3fs)' % (time.monotonic() - self.start) if compute_time else ''
            if fake:
                self.stdout.write(self.style.SUCCESS(' FAKED' + elapsed))
            else:
                self.stdout.write(self.style.SUCCESS(' OK' + elapsed))
        elif action == 'render_start':
            if compute_time:
                self.start = time.monotonic()
            self.stdout.write('  Rendering model states...', ending='')
            self.stdout.flush()
        elif action == 'render_success':
            elapsed = ' (%.3fs)' % (time.monotonic() - self.start) if compute_time else ''
            self.stdout.write(self.style.SUCCESS(' DONE' + elapsed))

