def _concat(self, indexes: list[Index], name: Hashable) -> Index:
    """
        Overriding parent method for the case of all RangeIndex instances.

        When all members of "indexes" are of type RangeIndex: result will be
        RangeIndex if possible, Index with a int64 dtype otherwise. E.g.:
        indexes = [RangeIndex(3), RangeIndex(3, 6)] -> RangeIndex(6)
        indexes = [RangeIndex(3), RangeIndex(4, 6)] -> Index([0,1,2,4,5], dtype='int64')
        """
    if not all((isinstance(x, RangeIndex) for x in indexes)):
        result = super()._concat(indexes, name)
        if result.dtype.kind == 'i':
            return self._shallow_copy(result._values)
        return result
    elif <MASK>:
        return indexes[0]
    rng_indexes = cast(list[RangeIndex], indexes)
    start = step = next_ = None
    non_empty_indexes = []
    all_same_index = True
    prev: RangeIndex | None = None
    for obj in rng_indexes:
        if len(obj):
            non_empty_indexes.append(obj)
            if all_same_index:
                if prev is not None:
                    all_same_index = prev.equals(obj)
                else:
                    prev = obj
    for obj in non_empty_indexes:
        rng = obj._range
        if start is None:
            start = rng.start
            if step is None and len(rng) > 1:
                step = rng.step
        elif step is None:
            if rng.start == start:
                if all_same_index:
                    values = np.tile(non_empty_indexes[0]._values, len(non_empty_indexes))
                else:
                    values = np.concatenate([x._values for x in rng_indexes])
                result = self._constructor(values)
                return result.rename(name)
            step = rng.start - start
        non_consecutive = step != rng.step and len(rng) > 1 or (next_ is not None and rng.start != next_)
        if non_consecutive:
            if all_same_index:
                values = np.tile(non_empty_indexes[0]._values, len(non_empty_indexes))
            else:
                values = np.concatenate([x._values for x in rng_indexes])
            result = self._constructor(values)
            return result.rename(name)
        if step is not None:
            next_ = rng[-1] + step
    if non_empty_indexes:
        stop = non_empty_indexes[-1].stop if next_ is None else next_
        if len(non_empty_indexes) == 1:
            step = non_empty_indexes[0].step
        return RangeIndex(start, stop, step, name=name)
    return RangeIndex(_empty_range, name=name)

def get_numel(self, buffer_name: str) -> Union[int, Expr]:
    if buffer_name in self.constants:
        return self.constants[buffer_name].numel()
    if buffer_name in self.name_to_buffer:
        buf = self.name_to_buffer[buffer_name]
        if <MASK>:
            return 1
        return buf.get_numel()
    if buffer_name in self.graph_inputs:
        return self.graph_inputs[buffer_name].get_numel()
    raise KeyError(f'could not find {buffer_name}')

def embedding_lookup_sparse_impl(params, segment_ids, sp_weights, ids, combiner, ignore_weights, max_norm, allow_fast_lookup, partition_strategy, name):
    """Implementation of sparse embedding aggregation."""
    need_sparse_segment_gradient = False
    segment_ids = ops.convert_to_tensor(segment_ids, name='segment_ids')
    if len(params) == 1 and (not isinstance(params[0], (core.Tensor, composite_tensor.CompositeTensor))):
        params = [ops.convert_to_tensor(params[0], name='params')]
    if len(params) == 1 and (not isinstance(params[0], composite_tensor.CompositeTensor)) and (params[0].device == segment_ids.device) and (max_norm is None) and (allow_fast_lookup or (ignore_weights and compat.forward_compatible(2023, 9, 26))):
        idx = ids
        embeddings = params[0]
        if isinstance(embeddings, resource_variable_ops.BaseResourceVariable):
            embeddings = embeddings.read_value_no_copy()
        if not allow_fast_lookup:
            need_sparse_segment_gradient = True
    else:
        (ids, idx) = array_ops.unique(ids)
        embeddings = embedding_lookup(params, ids, partition_strategy=partition_strategy, max_norm=max_norm)
    if not ignore_weights:
        if <MASK>:
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        weights = sp_weights.values
        embeddings = array_ops.gather(embeddings, idx)
        original_dtype = embeddings.dtype
        if embeddings.dtype in (dtypes.float16, dtypes.bfloat16):
            embeddings = math_ops.cast(embeddings, dtypes.float32)
        if weights.dtype != embeddings.dtype:
            weights = math_ops.cast(weights, embeddings.dtype)
        ones_shape = array_ops.expand_dims(array_ops.rank(embeddings) - 1, 0)
        weights_shape = array_ops.shape(weights)
        ones = array_ops.ones(ones_shape, dtype=weights_shape.dtype)
        bcast_weights_shape = array_ops.concat([weights_shape, ones], 0)
        orig_weights_shape = weights.get_shape()
        weights = array_ops.reshape(weights, bcast_weights_shape)
        if embeddings.get_shape().ndims is not None:
            weights.set_shape(orig_weights_shape.concatenate([1 for _ in range(embeddings.get_shape().ndims - 1)]))
        embeddings *= weights
        if combiner == 'sum':
            embeddings = math_ops.segment_sum(embeddings, segment_ids, name=name)
        elif combiner == 'mean':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weight_sum = math_ops.segment_sum(weights, segment_ids)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum, name=name)
        elif combiner == 'sqrtn':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weights_squared = math_ops.pow(weights, 2)
            weight_sum = math_ops.segment_sum(weights_squared, segment_ids)
            weight_sum_sqrt = math_ops.sqrt(weight_sum)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum_sqrt, name=name)
        else:
            assert False, 'Unrecognized combiner'
        if embeddings.dtype != original_dtype:
            embeddings = math_ops.cast(embeddings, original_dtype)
    else:
        if segment_ids.dtype not in (dtypes.int32, dtypes.int64):
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        assert idx is not None
        if combiner == 'sum':
            embeddings = math_ops.sparse_segment_sum(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'mean':
            embeddings = math_ops.sparse_segment_mean(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'sqrtn':
            embeddings = math_ops.sparse_segment_sqrt_n(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        else:
            assert False, 'Unrecognized combiner'
    return embeddings

def merge(pr: GitHubPR, repo: GitRepo, comment_id: int, dry_run: bool=False, skip_mandatory_checks: bool=False, timeout_minutes: int=400, stale_pr_days: int=3, ignore_current: bool=False) -> None:
    initial_commit_sha = pr.last_commit_sha()
    pr_link = f'https://github.com/{pr.org}/{pr.project}/pull/{pr.pr_num}'
    print(f'Attempting merge of {initial_commit_sha} ({pr_link})')
    if MERGE_IN_PROGRESS_LABEL not in pr.get_labels():
        gh_add_labels(pr.org, pr.project, pr.pr_num, [MERGE_IN_PROGRESS_LABEL], dry_run)
    explainer = TryMergeExplainer(skip_mandatory_checks, pr.get_labels(), pr.pr_num, pr.org, pr.project, ignore_current)
    ignore_current_checks_info = []
    if pr.is_ghstack_pr():
        get_ghstack_prs(repo, pr)
    check_for_sev(pr.org, pr.project, skip_mandatory_checks)
    if skip_mandatory_checks:
        post_starting_merge_comment(repo, pr, explainer, dry_run)
        return pr.merge_into(repo, dry_run=dry_run, skip_mandatory_checks=skip_mandatory_checks, comment_id=comment_id)
    find_matching_merge_rule(pr, repo, skip_mandatory_checks=True)
    if not has_required_labels(pr):
        raise RuntimeError(LABEL_ERR_MSG.lstrip(' #'))
    if ignore_current:
        checks = pr.get_checkrun_conclusions()
        (_, failing, _) = categorize_checks(checks, list(checks.keys()), ok_failed_checks_threshold=IGNORABLE_FAILED_CHECKS_THESHOLD)
        ignore_current_checks_info = failing
    post_starting_merge_comment(repo, pr, explainer, dry_run, ignore_current_checks_info=ignore_current_checks_info)
    start_time = time.time()
    last_exception = ''
    elapsed_time = 0.0
    ignore_current_checks = [x[0] for x in ignore_current_checks_info]
    while elapsed_time < timeout_minutes * 60:
        check_for_sev(pr.org, pr.project, skip_mandatory_checks)
        current_time = time.time()
        elapsed_time = current_time - start_time
        print(f'Attempting merge of https://github.com/{pr.org}/{pr.project}/pull/{pr.pr_num} ({elapsed_time / 60} minutes elapsed)')
        pr = GitHubPR(pr.org, pr.project, pr.pr_num)
        if initial_commit_sha != pr.last_commit_sha():
            raise RuntimeError('New commits were pushed while merging. Please rerun the merge command.')
        try:
            required_checks = []
            failed_rule_message = None
            ignore_flaky_failures = True
            try:
                find_matching_merge_rule(pr, repo, ignore_current_checks=ignore_current_checks)
            except MandatoryChecksMissingError as ex:
                if ex.rule is not None:
                    ignore_flaky_failures = ex.rule.ignore_flaky_failures
                    if ex.rule.mandatory_checks_name is not None:
                        required_checks = ex.rule.mandatory_checks_name
                failed_rule_message = ex
            checks = pr.get_checkrun_conclusions()
            checks = get_classifications(pr.pr_num, pr.project, checks, ignore_current_checks=ignore_current_checks)
            (pending, failing, _) = categorize_checks(checks, required_checks + [x for x in checks.keys() if x not in required_checks], ok_failed_checks_threshold=IGNORABLE_FAILED_CHECKS_THESHOLD if ignore_flaky_failures else 0)
            startup_failures = filter_checks_with_lambda(checks, lambda status: status == 'STARTUP_FAILURE')
            if len(startup_failures) > 0:
                raise RuntimeError(f'{len(startup_failures)} STARTUP failures reported, please check workflows syntax! ' + ', '.join((f'[{x.name}]({x.url})' for x in startup_failures[:5])))
            if len(failing) > 0:
                raise RuntimeError(f'{len(failing)} jobs have failed, first few of them are: ' + ', '.join((f'[{x[0]}]({x[1]})' for x in failing[:5])))
            if <MASK>:
                if failed_rule_message is not None:
                    raise failed_rule_message
                else:
                    raise MandatoryChecksMissingError(f'Still waiting for {len(pending)} jobs to finish, ' + f"first few of them are: {', '.join((x[0] for x in pending[:5]))}")
            return pr.merge_into(repo, dry_run=dry_run, skip_mandatory_checks=skip_mandatory_checks, comment_id=comment_id, ignore_current_checks=ignore_current_checks)
        except MandatoryChecksMissingError as ex:
            last_exception = str(ex)
            print(f'Merge of https://github.com/{pr.org}/{pr.project}/pull/{pr.pr_num} failed due to: {ex}. Retrying in 5 min', flush=True)
            time.sleep(5 * 60)
    msg = f'Merged timed out after {timeout_minutes} minutes. Please contact the pytorch_dev_infra team.'
    msg += f'The last exception was: {last_exception}'
    gh_add_labels(pr.org, pr.project, pr.pr_num, ['land-failed'], dry_run)
    raise RuntimeError(msg)

def emit(self, record: Any) -> None:

    def _log_expression_created(emit_func: Callable[[Any], None], sym_node_id: int) -> None:
        if sym_node_id is None:
            return
        if (res := self.expression_created_logs.get(sym_node_id, None)):
            if not res.visited:
                res.visited = True
                for arg in res.argument_ids:
                    _log_expression_created(emit_func, arg)
            emit_func(res.record)
    metadata = record.metadata
    for key in self.specific_log_keys:
        if <MASK>:
            if self.log_record.try_add((key, metadata[key])):
                if key == 'expression_created':
                    self.expression_created_logs[metadata[key]['result_id']] = ExpressionCreatedNode(metadata[key]['result_id'], metadata[key].get('argument_ids', []), record)
                    return
                elif key == 'propagate_real_tensors_provenance':
                    _log_expression_created(super().emit, metadata[key].get('expr_node_id'))
                elif key == 'guard_added':
                    if len(metadata[key]['symbol_to_sources']) == 0:
                        return
                    elif metadata[key]['prefix'] == 'runtime_assert':
                        return
                    _log_expression_created(super().emit, metadata[key].get('expr_node_id'))
                super().emit(record)

@staticmethod
def _get_gram(precompute, X, y):
    if <MASK>:
        precompute = np.dot(X.T, X)
    return precompute

def wrapper(f):
    params = inspect.signature(f).parameters
    arg_names = tuple(params.keys())

    @functools.wraps(f)
    def wrapped(*args, **kwargs):
        kwargs.update(zip(arg_names, args, strict=False))
        cond = True
        if 'device' in kwargs:
            cond = cond and torch.device(kwargs['device']).type == 'cpu'
        if 'dtype' in kwargs:
            cond = cond and kwargs['dtype'] == torch.float
        bf32_cond = cond and bf32_is_not_fp32()
        tf32_cond = cond and tf32_is_not_fp32()
        if bf32_cond or tf32_cond:
            with_reduced_f32_disabled(kwargs['self'], lambda : f(**kwargs))
            if bf32_cond:
                with_bf32_enabled(kwargs['self'], lambda : f(**kwargs))
            if <MASK>:
                with_tf32_enabled(kwargs['self'], lambda : f(**kwargs))
        else:
            f(**kwargs)
    return wrapped

def resize_fn(images_t, new_size):
    """Resize core function, passed to _resize_images_common."""
    scale_and_translate_methods = [ResizeMethod.LANCZOS3, ResizeMethod.LANCZOS5, ResizeMethod.GAUSSIAN, ResizeMethod.MITCHELLCUBIC]

    def resize_with_scale_and_translate(method):
        scale = math_ops.cast(new_size, dtype=dtypes.float32) / math_ops.cast(array_ops.shape(images_t)[1:3], dtype=dtypes.float32)
        return gen_image_ops.scale_and_translate(images_t, new_size, scale, array_ops.zeros([2]), kernel_type=method, antialias=antialias)
    if <MASK>:
        if antialias:
            return resize_with_scale_and_translate('triangle')
        else:
            return gen_image_ops.resize_bilinear(images_t, new_size, half_pixel_centers=True)
    elif method == ResizeMethod.NEAREST_NEIGHBOR:
        return gen_image_ops.resize_nearest_neighbor(images_t, new_size, half_pixel_centers=True)
    elif method == ResizeMethod.BICUBIC:
        if antialias:
            return resize_with_scale_and_translate('keyscubic')
        else:
            return gen_image_ops.resize_bicubic(images_t, new_size, half_pixel_centers=True)
    elif method == ResizeMethod.AREA:
        return gen_image_ops.resize_area(images_t, new_size)
    elif method in scale_and_translate_methods:
        return resize_with_scale_and_translate(method)
    else:
        raise ValueError('Resize method is not implemented: {}'.format(method))

