def pin_min_versions_to_yaml_file(yaml_map: dict[str, list[str] | None], toml_map: dict[str, str], yaml_file_data: str) -> str:
    data = yaml_file_data
    for (yaml_package, yaml_versions) in yaml_map.items():
        old_dep = yaml_package
        if yaml_versions is not None:
            old_dep = old_dep + ', '.join(yaml_versions)
        if CONDA_TO_PIP.get(yaml_package, yaml_package) in toml_map:
            min_dep = toml_map[CONDA_TO_PIP.get(yaml_package, yaml_package)]
        elif yaml_package in toml_map:
            min_dep = toml_map[yaml_package]
        else:
            continue
        if yaml_versions is None:
            new_dep = old_dep + '>=' + min_dep
            data = data.replace(old_dep, new_dep, 1)
            continue
        toml_version = version.parse(min_dep)
        yaml_versions_list = clean_version_list(yaml_versions, toml_version)
        cleaned_yaml_versions = [x for x in yaml_versions_list if '-' not in x]
        new_dep = yaml_package
        for clean_yaml_version in cleaned_yaml_versions:
            new_dep += clean_yaml_version + ', '
        operator = get_operator_from(new_dep)
        if <MASK>:
            new_dep += '>=' + min_dep
        else:
            new_dep = new_dep[:-2]
        data = data.replace(old_dep, new_dep)
    return data

@_lru_cache
def simplify(self, expr: _SympyT, size_oblivious: bool=False) -> _SympyT:
    """Use known constraints and replacements to simplify the given expr"""
    expr = safe_expand(expr)
    expr = self.replace(expr)
    if not size_oblivious:
        min_max_replacements = {}
        for atom in expr.atoms(Max):
            if len(atom.args) > 2:
                continue
            (a, b) = atom.args
            if b == 1 or b == 0:
                (a, b) = (b, a)
            if a == 1 and self._maybe_evaluate_static(sympy.Ge(b, 1)):
                min_max_replacements[atom] = b
            if a == 0 and self._maybe_evaluate_static(sympy.Ge(b, 0)):
                min_max_replacements[atom] = b
        if min_max_replacements:
            expr = expr.xreplace(min_max_replacements)
    if expr.has(TruncToInt):
        trunc_replacements = {}
        for atom in expr.atoms(TruncToInt):
            if <MASK>:
                (base, divisor) = atom.args[0].args
                if base % divisor == 0:
                    trunc_replacements[atom] = CleanDiv(base, divisor)
                else:
                    trunc_replacements[atom] = FloorDiv(base, divisor)
        if trunc_replacements:
            expr = expr.xreplace(trunc_replacements)
    if expr.has(FloorDiv):
        self._update_divisible()
        div_replacements = {}
        for atom in expr.atoms(FloorDiv):
            (base, divisor) = atom.args
            if isinstance(divisor, FloorDiv):
                (base1, divisor1) = divisor.args
                if self.replace(Mod(base, divisor)) in self.divisible and base == base1 and (self.replace(Mod(base1, divisor1)) in self.divisible):
                    div_replacements[atom] = divisor1
        if div_replacements:
            expr = expr.xreplace(div_replacements)
            expr = safe_expand(expr)
    if expr.has(FloorDiv):
        div_replacements = {}
        pows = expr.atoms(sympy.Pow)
        rationals = expr.atoms(sympy.Rational).difference(expr.atoms(sympy.Integer))
        for fd in expr.atoms(FloorDiv):
            (base, divisor) = fd.args
            if self.replace(Mod(base, divisor)) in self.divisible:
                div_replacements[fd] = CleanDiv(base, divisor)
        if div_replacements:
            new_expr = expr.xreplace(div_replacements)
            new_expr = safe_expand(new_expr)
            new_pows = new_expr.atoms(sympy.Pow)
            new_rationals = new_expr.atoms(sympy.Rational).difference(new_expr.atoms(sympy.Integer))
            if new_pows.issubset(pows) and new_rationals.issubset(rationals):
                expr = new_expr
    return expr

def indexing_to_dimensions(self, var: str, index: sympy.Expr, is_store: bool):
    """Convert address-based indexing into dimensions using self.halide_vars"""
    symbols = []
    for sym in sorted(index.free_symbols, key=lambda x: x.name):
        if <MASK>:
            symbols.append(sym)
        else:
            assert symbol_is_type(sym, (SymT.UNBACKED_INT, SymT.SIZE, SymT.PRECOMPUTED_SIZE)), sym
    offset = sympy.S.Zero
    split_expr = dict.fromkeys(symbols, sympy.S.Zero)
    split_failed: list[tuple[list[sympy.Symbol], sympy.Expr]] = []
    index = sympy.expand(self.rename_indexing(index))
    for part in index.args if isinstance(index, sympy.Add) else [index]:
        part_vars = [v for v in part.free_symbols if v in split_expr]
        if len(part_vars) == 0:
            offset += part
        elif len(part_vars) == 1:
            split_expr[part_vars[0]] += part
        else:
            new_split_failed = []
            for i in range(len(split_failed)):
                assert split_failed[i] is not None
                (other_vars, other_part) = split_failed[i]
                if OrderedSet(other_vars) & OrderedSet(part_vars):
                    part_vars.extend([v for v in other_vars if v not in part_vars])
                    part += other_part
                else:
                    new_split_failed.append((other_vars, other_part))
            split_failed = [*new_split_failed, (part_vars, part)]

    def expr_to_dimension(expr, syms):
        expr = sympy.factor(expr)
        if len(syms) == 1:
            stride_wild = sympy.Wild('wild', exclude=symbols)
            m = expr.match(stride_wild * syms[0])
            if m:
                return DimensionInfo(syms[0], self.sym_size(syms[0]), m[stride_wild])
        assert not is_store, expr
        length = sympy.simplify(sympy_subs(expr, {sym: self.sym_size(sym) - 1 for sym in syms}) + 1)
        stride = sympy.S.One
        if isinstance(expr, sympy.Mul):
            for term in expr.args:
                if isinstance(term, sympy.Integer):
                    stride *= term
                    expr = sympy.simplify(expr / term)
                    length = sympy.simplify(sympy.ceiling(length / term))
        return DimensionInfo(expr, length, stride)
    dims = []
    for (syms, expr) in split_failed:
        for v in syms:
            expr += split_expr.pop(v)
        dims.append(expr_to_dimension(expr, syms))
    for (sym, expr) in split_expr.items():
        dims.append(expr_to_dimension(expr, [sym]))
    dims.sort(key=lambda d: V.graph.sizevars.size_hint(d.stride, fallback=inf))
    if not dims:
        if self.has_indirect_indexing:
            dims.append(DimensionInfo(sympy.S.Zero, 1, 1))
    elif not V.graph.sizevars.statically_known_equals(dims[0].stride, 1):
        dims.insert(0, DimensionInfo(sympy.S.Zero, 1 if is_store else dims[0].stride, 1))
    if dims and (not is_store):
        if var in self.buffer_offsets and V.graph.sizevars.statically_known_geq(offset, self.buffer_offsets[var]):
            self.apply_offset_to_dimension(dims, offset - self.buffer_offsets[var])
            offset = self.buffer_offsets[var]
        elif V.graph.sizevars.statically_known_gt(offset, 0):
            self.apply_offset_to_dimension(dims, offset)
            offset = 0
    orig_var = var
    for i in itertools.count():
        if self.install_dims(var, dims, offset, is_store):
            return (var, dims)
        assert not is_store
        var = f'{orig_var}_view{i}'
        if var not in self.buffer_aliases[orig_var]:
            self.buffer_aliases[orig_var].append(var)

