        type_str = generate_test_ir_arguments_base_ty_to_type_str_[t.name]
    if <MASK>:
        type_str = f'{type_str}?'
    return ('%' + arg.name, type_str)

@classmethod
def from_function(cls, func, domain: str, name: str | None=None, overload: str='', *, opset_version: int=1) -> OpSignature:
    """Produce an OpSignature from a function using type annotation."""
    py_signature = inspect.signature(func)
    type_hints = typing.get_type_hints(func)
    params: list[Parameter | AttributeParameter] = []
    type_constraints: dict[str, TypeConstraintParam] = {}
    for param in py_signature.parameters.values():
        if param.name not in type_hints:
            logger.warning("Missing annotation for parameter '%s' from %s. Treating as an Input.", param.name, py_signature)
            type_constraint = TypeConstraintParam.any_value(f'T_{param.name}')
            type_constraints[param.name] = type_constraint
            params.append(Parameter(name=param.name, type_constraint=type_constraint, required=param.default is inspect.Parameter.empty, variadic=False, default=param.default if param.default is not inspect.Parameter.empty else _EMPTY_DEFAULT))
        else:
            type_ = type_hints[param.name]
            if (attr_type := _get_attr_type(type_)) != ir.AttributeType.UNDEFINED:
                if param.default is not inspect.Parameter.empty:
                    default = ir.Attr(param.name, attr_type, param.default)
                else:
                    default = None
                params.append(AttributeParameter(name=param.name, type=attr_type, required=param.default is inspect.Parameter.empty, default=default))
            else:
                type_constraint_name = _get_type_constraint_name(type_)
                if <MASK>:
                    type_constraint_name = f'T_{param.name}'
                if type_constraint_name in type_constraints:
                    type_constraint = type_constraints[type_constraint_name]
                else:
                    type_constraint = TypeConstraintParam(name=type_constraint_name, allowed_types=_get_allowed_types_from_type_annotation(type_))
                    type_constraints[type_constraint_name] = type_constraint
                params.append(Parameter(name=param.name, type_constraint=type_constraint, required=param.default is inspect.Parameter.empty, variadic=False, default=param.default if param.default is not inspect.Parameter.empty else _EMPTY_DEFAULT))
    return_type = type_hints.get('return')
    outputs = []
    if return_type is None:
        pass
    else:
        if typing.get_origin(return_type) is tuple:
            return_types = typing.get_args(return_type)
        else:
            return_types = [return_type]
        for (i, return_type_i) in enumerate(return_types):
            if (return_param_name := _get_type_constraint_name(return_type_i)) in type_constraints:
                type_constraint = type_constraints[return_param_name]
            else:
                return_param_name = f'TReturn{i}'
                type_constraint = TypeConstraintParam(name=return_param_name, allowed_types=_get_allowed_types_from_type_annotation(return_type_i))
                type_constraints[return_param_name] = type_constraint
            outputs.append(Parameter(name=return_param_name, type_constraint=type_constraint, required=True, variadic=False, default=_EMPTY_DEFAULT))
    return cls(domain=domain, name=name or func.__name__, overload=overload, params=params, outputs=outputs, opset_version=opset_version)

def TYPE_MATCH(self, guard: Guard) -> None:
    value = self.get(guard.name)
    if <MASK>:
        t = value.pytype
    else:
        t = type(value)
    if t.__qualname__ != t.__name__:
        guard._unserializable = True
    obj_id = self.id_ref(t, f'type({guard.name})')
    code = f'___check_type_id({self.arg_ref(guard)}, {obj_id})'
    self._set_guard_export_info(guard, [code])
    self.get_guard_manager(guard).add_type_match_guard(obj_id, get_verbose_code_parts(code, guard))

@torch.library.custom_op('cplib::flex_cp_allgather_backward', mutates_args=())
def flex_cp_allgather_backward(grad_full_k: torch.Tensor, grad_full_v: torch.Tensor, seq_dim: int, pg_name: str) -> tuple[torch.Tensor, torch.Tensor]:
    grad_k = funcol.reduce_scatter_tensor(grad_full_k, 'sum', seq_dim, pg_name)
    if <MASK>:
        grad_k = grad_k.wait()
    grad_v = funcol.reduce_scatter_tensor(grad_full_v, 'sum', seq_dim, pg_name)
    if isinstance(grad_v, funcol.AsyncCollectiveTensor):
        grad_v = grad_v.wait()
    return (grad_k, grad_v)

def extract_output_name(out: Optional[Union[ir.Buffer, Sequence[ir.Buffer]]]) -> Union[Optional[str], _OUTPUT_ARGS_TYPE]:
    if out is None:
        return None
    if <MASK>:
        return out.get_name()
    if isinstance(out, ir.MutationOutput):
        mutated_buf_names = out.get_mutation_names()
        assert isinstance(mutated_buf_names, list) and len(mutated_buf_names) == 1, 'Expect only one mutated buffer in MutationOutput'
        return mutated_buf_names[0]
    if isinstance(out, (list, tuple)):
        return [extract_output_name(o) for o in out]
    if isinstance(out, int):
        return str(out)
    raise AssertionError(f'Unexpected output: {type(out)}')

def build_xlstyle(self, props: Mapping[str, str]) -> dict[str, dict[str, str]]:
