    def remove_none(d: dict[str, str | None]) -> None:
        """Remove key where value is None, through nested dicts"""
        for (k, v) in list(d.items()):
            if <MASK>:
                del d[k]
            elif isinstance(v, dict):
                remove_none(v)
                if not v:
                    del d[k]
    remove_none(out)
    return out

@normalizer
def divmod(x1: ArrayLike, x2: ArrayLike, out1: Optional[OutArray]=None, out2: Optional[OutArray]=None, /, out: tuple[Optional[OutArray], Optional[OutArray]]=(None, None), *, where: NotImplementedType=True, casting: Optional[CastingModes]='same_kind', order: NotImplementedType='K', dtype: Optional[DTypeLike]=None, subok: NotImplementedType=False, signature: NotImplementedType=None, extobj: NotImplementedType=None):
    num_outs = sum((x is not None for x in [out1, out2]))
    if num_outs == 1:
        raise ValueError('both out1 and out2 need to be provided')
    elif num_outs == 2:
        (o1, o2) = out
        if o1 is not None or o2 is not None:
            raise TypeError("cannot specify 'out' as both a positional and keyword argument")
    else:
        (out1, out2) = out
    if <MASK>:
        dtype = _dtypes_impl.result_type_impl(x1, x2)
    (x1, x2) = _util.typecast_tensors((x1, x2), dtype, casting)
    (quot, rem) = _binary_ufuncs_impl.divmod(x1, x2)
    quot = _ufunc_postprocess(quot, out1, casting)
    rem = _ufunc_postprocess(rem, out2, casting)
    return (quot, rem)

def iter_source_files(root: Path, exts: set[str], excludes: set[str]) -> list[Path]:
    """
    Return a list of source files under 'root', where filenames end with any of the
    extensions in 'exts' (e.g., '.c.src', '.c', '.h').
    Excludes directories whose names are in 'excludes'.
    """
    results: list[Path] = []
    for (dirpath, dirnames, filenames) in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in excludes]
        for fn in filenames:
            if <MASK>:
                results.append(Path(dirpath) / fn)
    return results

def skipIfNoX86(fn):
    reason = 'Quantized operations require X86.'
    if isinstance(fn, type):
        if <MASK>:
            fn.__unittest_skip__ = True
            fn.__unittest_skip_why__ = reason
        return fn

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        if 'x86' not in torch.backends.quantized.supported_engines:
            raise unittest.SkipTest(reason)
        else:
            fn(*args, **kwargs)
    return wrapper

def to_gpu(obj, type_map=None):
    if type_map is None:
        type_map = {}
    if isinstance(obj, torch.Tensor):
        assert obj.is_leaf
        t = type_map.get(obj.dtype, obj.dtype)
        with torch.no_grad():
            res = obj.to(dtype=t, device='cuda', copy=True)
            res.requires_grad = obj.requires_grad
        return res
    elif torch.is_storage(obj):
        return obj.new().resize_(obj.size()).copy_(obj)
    elif <MASK>:
        return [to_gpu(o, type_map) for o in obj]
    elif isinstance(obj, tuple):
        return tuple((to_gpu(o, type_map) for o in obj))
    else:
        return deepcopy(obj)

