def out_wrapper(*out_names: str, exact_dtype: bool=False, pass_is_out: bool=False, preserve_memory_format: bool=False) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:
    default_out_names = ('out',)
    if len(out_names) == 0:
        out_names = default_out_names
    is_tensor = len(out_names) == 1

    def maybe_compute_memory_format(t):
        return utils.suggest_memory_format(t) if preserve_memory_format else None

    def _out_wrapper(fn: Callable[_P, _T]) -> Callable[_P, _T]:
        """
        Adds the out parameter to a Python reference.
        """
        out_type = TensorLikeType if is_tensor else GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
        bc_out_type = TensorLikeType if is_tensor else types.GenericAlias(tuple, tuple((TensorLikeType for _ in range(len(out_names)))))
        return_type = TensorLikeType if is_tensor else NamedTuple(f'return_types_{fn.__name__}', [(o, TensorLikeType) for o in out_names])
        sig = inspect.signature(fn)
        factory_kwargs = ('device', 'dtype')
        is_factory_fn = all((p in sig.parameters for p in factory_kwargs))

        @wraps(fn)
        def _fn(*args: _P.args, **kwargs: _P.kwargs):
            out = kwargs.pop('out', None)
            if is_factory_fn and out is not None:
                for k in factory_kwargs:
                    out_attr = getattr(out, k)
                    if k not in kwargs:
                        kwargs[k] = out_attr

            def maybe_check_copy_devices(out):
                if isinstance(out, TensorLike) and isinstance(args[0], TensorLike):
                    check_copy_devices(copy_from=args[0], copy_to=out)
            if <MASK>:
                for o in out:
                    maybe_check_copy_devices(o)
            else:
                maybe_check_copy_devices(out)
            if pass_is_out:
                result = fn(*args, is_out=out is not None, **kwargs)
            else:
                result = fn(*args, **kwargs)
            if result is NotImplemented:
                return NotImplemented
            assert isinstance(result, TensorLike) and is_tensor or (isinstance(result, tuple) and len(result) == len(out_names)) or (fn.__name__ == 'unbind' and isinstance(result, (list, tuple)))
            if out is not None:
                if is_tensor and fn.__name__ != 'unbind':
                    assert isinstance(out, TensorLike)
                    _maybe_resize_out(out, result.shape, maybe_compute_memory_format(result))
                    _safe_copy_out(copy_from=result, copy_to=out, exact_dtype=exact_dtype)
                else:
                    if fn.__name__ != 'unbind':
                        assert isinstance(out, tuple)
                    else:
                        assert isinstance(out, (list, tuple))
                    torch._check_type(len(out) == len(result), lambda : f'expected tuple of {len(result)} elements but got {len(out)}')
                    for (r, o) in zip(result, out):
                        _maybe_resize_out(o, r.shape, maybe_compute_memory_format(r))
                        _safe_copy_out(copy_from=r, copy_to=o, exact_dtype=exact_dtype)
            else:
                out = result
            return out if is_tensor else return_type(*out)
        out_param = inspect.Parameter('out', kind=inspect.Parameter.KEYWORD_ONLY, default=None, annotation=out_type)
        assert isinstance(sig.return_annotation, (str, TypeVar)) or sig.return_annotation in (sig.empty, out_type, bc_out_type)
        params = (*sig.parameters.values(), out_param)
        params = sorted(params, key=lambda p: p.kind)
        _fn.__signature__ = inspect.Signature(parameters=params, return_annotation=return_type)
        _fn.__annotations__ = dict(getattr(fn, '__annotations__', {}))
        _fn.__annotations__['out'] = out_type
        _fn.__annotations__['return'] = return_type
        if is_tensor and out_names != default_out_names:
            _fn.__annotations__[CustomOutParamAnnotation] = out_names[0]
        _fn._torch_decompositions_out_wrapper = f'This function is wrapped by {out_wrapper.__module__}.out_wrapper'
        return _fn
    return _out_wrapper

def decorator(func):

    @wraps(func)
    def inner(*args, **kwargs):
        try:
            get_running_loop()
        except RuntimeError:
            pass
        else:
            if <MASK>:
                raise SynchronousOnlyOperation(message)
        return func(*args, **kwargs)
    return inner

def resolve(self, args):
    n = len(args)
    for signature in self.ordering:
        if <MASK>:
            continue
        s = unify(freeze(args), signature)
        if s is not False:
            result = self.funcs[signature]
            return (result, s)
    raise NotImplementedError('No match found. \nKnown matches: ' + str(self.ordering) + '\nInput: ' + str(args))

def _fused_all_gather_matmul_impl(mm_out_op: torch._ops.OpOverload, A_shard: torch.Tensor, Bs: list[torch.Tensor], A_scale: torch.Tensor | None, kwargs_list: list[dict[str, Any]], out_dtypes: list[torch.dtype | None], gather_dim: int, group_name: str, return_A: bool) -> tuple[torch.Tensor | None, list[torch.Tensor]]:
    if A_shard.dim() < 2:
        raise ValueError('A_shard must be a matrix')
    for B in Bs:
        if B.dim() != 2:
            raise ValueError('B must be a matrix')
    if <MASK>:
        raise ValueError('len(out_types) must be the same as len(Bs)')
    if len(kwargs_list) != len(Bs):
        raise ValueError('len(kwargs_list) must be the same as len(Bs)')
    if gather_dim < 0 or gather_dim >= A_shard.dim():
        raise ValueError('Invalid gather_dim')
    group = c10d._resolve_process_group(group_name)
    if gather_dim == A_shard.ndim - 1 or gather_dim == -1:
        return _fused_all_gather_matmul_last_gather_dim_impl(mm_out_op, A_shard, Bs, A_scale, kwargs_list, out_dtypes, gather_dim, group_name, return_A)
    A_shard_flat = A_shard.movedim(gather_dim, 0)
    leading_dims = [group.size()] + list(A_shard_flat.shape[:-1])
    A_shard_flat = A_shard_flat.flatten(0, -2)

    def unflatten(t: torch.Tensor) -> torch.Tensor:
        return t.view(*leading_dims, -1).flatten(0, 1).movedim(0, gather_dim)
    A_flat = A_shard_flat.new_empty(A_shard_flat.shape[0] * group.size(), A_shard_flat.shape[1])
    outputs = [A_flat.new_empty(A_flat.shape[0], B.shape[1], dtype=out_dtype or B.dtype) for (B, out_dtype) in zip(Bs, out_dtypes)]
    output_shards = [output.chunk(group.size()) for output in outputs]
    scale_mode = _check_and_verify_fp8_all_gather_scale_mode(shard=A_shard, scale=A_scale, gather_dim=gather_dim, group_size=group.size())
    if scale_mode == _ScaleMode.ROW_WISE_SHARDED:
        assert A_scale is not None
        A_scale_shard = A_scale.movedim(gather_dim, 0).flatten(0, -2)
        A_scale_flat = A_scale_shard.new_empty(A_scale_shard.shape[0] * group.size(), A_scale_shard.shape[1])

        def row_wise_sharded_consumer(shard: list[torch.Tensor], rank: int) -> None:
            for (idx, (B, kwargs)) in enumerate(zip(Bs, kwargs_list)):
                mm_out_op(shard[0], B, scale_a=shard[1], **kwargs, out=output_shards[idx][rank])
        _pipelined_multi_all_gather_and_consume([A_shard_flat, A_scale_shard], row_wise_sharded_consumer, [A_flat, A_scale_flat], group_name, return_A)
    elif scale_mode == _ScaleMode.ROW_WISE_REPLICATED:
        assert A_scale is not None
        A_scale_shards = A_scale.movedim(gather_dim, 0).flatten(0, -2).chunk(group.size())

        def row_wise_replicated_consumer(shard: torch.Tensor, rank: int) -> None:
            for (idx, (B, kwargs)) in enumerate(zip(Bs, kwargs_list)):
                mm_out_op(shard, B, scale_a=A_scale_shards[rank], **kwargs, out=output_shards[idx][rank])
        _pipelined_all_gather_and_consume(A_shard_flat, row_wise_replicated_consumer, A_flat, group_name, return_A)
    else:
        if scale_mode == _ScaleMode.TENSOR_WISE:
            assert A_scale is not None
            for kwargs in kwargs_list:
                kwargs['scale_a'] = A_scale
        else:
            assert scale_mode == _ScaleMode.UNSCALED

        def default_consumer(shard: torch.Tensor, rank: int) -> None:
            for (idx, (B, kwargs)) in enumerate(zip(Bs, kwargs_list)):
                mm_out_op(shard, B, **kwargs, out=output_shards[idx][rank])
        _pipelined_all_gather_and_consume(A_shard_flat, default_consumer, A_flat, group_name, return_A)
    A = unflatten(A_flat) if return_A else None
    return (A, [unflatten(output) for output in outputs])

def _fw_pre_hook(self, mod, input):
    """
        This function is called before the forward pass of a module. It
        collects the parameters and sharding information of a module and
        stores it in a dictionary.
        """
    if self.is_bw:
        self.activation_checkpointing = True
    else:
        self.activation_checkpointing = False
    self.name = super()._get_mod_name(mod)
    w_mod = weakref.ref(mod)
    super()._get_append_fn(w_mod, self.name, False)()
    (args, _) = tree_flatten(input)
    tensors = [a for a in args if isinstance(a, torch.Tensor) and a.requires_grad]
    if not self.is_bw and tensors:
        register_multi_grad_hook(tensors, super()._get_pop_fn(w_mod, self.name, True))
    if not self.activation_checkpointing:
        if self.name not in self.module_helper_dict:
            self.module_helper_dict[self.name] = {}
        self.module_helper_dict[self.name]['module_type'] = str(type(mod)).replace('<', '').replace('>', '')
        self.module_helper_dict[self.name]['depth'] = len(self.parents) - 1
        for (param_name, param) in mod.named_parameters(recurse=False):
            if self.name not in self.module_parameters_dict:
                self.module_parameters_dict[self.name] = {}
            self.module_parameters_dict[self.name][param_name] = param.data
            if <MASK>:
                key_name = self.name + '.' + param_name
                self.sharding_dict[key_name] = param.data.placements
                if 'parameters' not in self.module_helper_dict[self.name]:
                    self.module_helper_dict[self.name]['parameters'] = {}
                self.module_helper_dict[self.name]['parameters'][param_name] = str(param.data.placements)
        if self.name not in self.module_parents_dict:
            self.module_parents_dict[self.name] = copy.deepcopy(self.parents)
        parent = self.parent_list[-1]
        if parent not in self.parent_dict:
            self.parent_dict[parent] = []
        self.parent_dict[parent].append(self.name)
        self.parent_list.append(self.name)
        self.register_forward_hook_handles[self.name] = mod.register_forward_hook(self._fw_set_module_hook)

@no_type_check
def sync_grad_hook(grad, *, device_handle=None, compute_stream=None):
    if isinstance(grad, AsyncCollectiveTensor):
        if <MASK>:
            with device_handle.stream(compute_stream):
                grad = grad.wait()
        else:
            grad = grad.wait()
    return grad

def get_json_type(obj):
    """Serializes any object to a JSON-serializable structure.

  Args:
      obj: the object to serialize

  Returns:
      JSON-serializable structure representing `obj`.

  Raises:
      TypeError: if `obj` cannot be serialized.
  """
    if hasattr(obj, 'get_config'):
        return {'class_name': obj.__class__.__name__, 'config': obj.get_config()}
    if type(obj).__module__ == np.__name__:
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        else:
            return obj.item()
    if callable(obj):
        return obj.__name__
    if type(obj).__name__ == type.__name__:
        return obj.__name__
    if isinstance(obj, tensor_shape.Dimension):
        return obj.value
    if isinstance(obj, tensor_shape.TensorShape):
        return obj.as_list()
    if isinstance(obj, dtypes.DType):
        return obj.name
    if isinstance(obj, collections.abc.Mapping):
        return dict(obj)
    if obj is Ellipsis:
        return {'class_name': '__ellipsis__'}
    if isinstance(obj, wrapt.ObjectProxy):
        return obj.__wrapped__
    if <MASK>:
        try:
            type_spec_name = type_spec_registry.get_name(type(obj))
            return {'class_name': 'TypeSpec', 'type_spec': type_spec_name, 'serialized': obj._serialize()}
        except ValueError:
            raise ValueError('Unable to serialize {} to JSON, because the TypeSpec class {} has not been registered.'.format(obj, type(obj)))
    if isinstance(obj, enum.Enum):
        return obj.value
    raise TypeError('Not JSON Serializable:', obj)

def _check_token_format(token):
    """
    Raise an InvalidTokenFormat error if the token has an invalid length or
    characters that aren't allowed. The token argument can be a CSRF cookie
    secret or non-cookie CSRF token, and either masked or unmasked.
    """
    if <MASK>:
        raise InvalidTokenFormat(REASON_INCORRECT_LENGTH)
    if invalid_token_chars_re.search(token):
        raise InvalidTokenFormat(REASON_INVALID_CHARACTERS)

def _cast_to_stata_types(data: DataFrame) -> DataFrame:
    """
    Checks the dtypes of the columns of a pandas DataFrame for
    compatibility with the data types and ranges supported by Stata, and
    converts if necessary.

    Parameters
    ----------
    data : DataFrame
        The DataFrame to check and convert

    Notes
    -----
    Numeric columns in Stata must be one of int8, int16, int32, float32 or
    float64, with some additional value restrictions.  int8 and int16 columns
    are checked for violations of the value restrictions and upcast if needed.
    int64 data is not usable in Stata, and so it is downcast to int32 whenever
    the value are in the int32 range, and sidecast to float64 when larger than
    this range.  If the int64 values are outside of the range of those
    perfectly representable as float64 values, a warning is raised.

    bool columns are cast to int8.  uint columns are converted to int of the
    same size if there is no loss in precision, otherwise are upcast to a
    larger type.  uint64 is currently not supported since it is concerted to
    object in a DataFrame.
    """
    ws = ''
    conversion_data: tuple[tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type]] = ((np.bool_, np.int8, np.int8), (np.uint8, np.int8, np.int16), (np.uint16, np.int16, np.int32), (np.uint32, np.int32, np.int64), (np.uint64, np.int64, np.float64))
    float32_max = struct.unpack('<f', b'\xff\xff\xff~')[0]
    float64_max = struct.unpack('<d', b'\xff\xff\xff\xff\xff\xff\xdf\x7f')[0]
    for col in data:
        is_nullable_int = isinstance(data[col].dtype, ExtensionDtype) and data[col].dtype.kind in 'iub'
        orig_missing = data[col].isna()
        if is_nullable_int:
            fv = 0 if data[col].dtype.kind in 'iu' else False
            data[col] = data[col].fillna(fv).astype(data[col].dtype.numpy_dtype)
        elif isinstance(data[col].dtype, ExtensionDtype):
            if getattr(data[col].dtype, 'numpy_dtype', None) is not None:
                data[col] = data[col].astype(data[col].dtype.numpy_dtype)
            elif is_string_dtype(data[col].dtype):
                data[col] = data[col].astype('object')
                data.loc[data[col].isna(), col] = None
        dtype = data[col].dtype
        empty_df = data.shape[0] == 0
        for c_data in conversion_data:
            if dtype == c_data[0]:
                if empty_df or data[col].max() <= np.iinfo(c_data[1]).max:
                    dtype = c_data[1]
                else:
                    dtype = c_data[2]
                if c_data[2] == np.int64:
                    if data[col].max() >= 2 ** 53:
                        ws = precision_loss_doc.format('uint64', 'float64')
                data[col] = data[col].astype(dtype)
        if dtype == np.int8 and (not empty_df):
            if data[col].max() > 100 or data[col].min() < -127:
                data[col] = data[col].astype(np.int16)
        elif dtype == np.int16 and (not empty_df):
            if data[col].max() > 32740 or data[col].min() < -32767:
                data[col] = data[col].astype(np.int32)
        elif dtype == np.int64:
            if empty_df or (data[col].max() <= 2147483620 and data[col].min() >= -2147483647):
                data[col] = data[col].astype(np.int32)
            else:
                data[col] = data[col].astype(np.float64)
                if data[col].max() >= 2 ** 53 or data[col].min() <= -2 ** 53:
                    ws = precision_loss_doc.format('int64', 'float64')
        elif dtype in (np.float32, np.float64):
            if np.isinf(data[col]).any():
                raise ValueError(f'Column {col} contains infinity or -infinitywhich is outside the range supported by Stata.')
            value = data[col].max()
            if dtype == np.float32 and value > float32_max:
                data[col] = data[col].astype(np.float64)
            elif dtype == np.float64:
                if value > float64_max:
                    raise ValueError(f'Column {col} has a maximum value ({value}) outside the range supported by Stata ({float64_max})')
        if is_nullable_int:
            if orig_missing.any():
                sentinel = StataMissingValue.BASE_MISSING_VALUES[data[col].dtype.name]
                data.loc[orig_missing, col] = sentinel
    if <MASK>:
        warnings.warn(ws, PossiblePrecisionLoss, stacklevel=find_stack_level())
    return data

@register_decomposition([aten.arange.start_step, aten.arange.start_out])
@out_wrapper()
def arange(start: NumberType=0, end: Optional[NumberType]=None, step: NumberType=1, *, dtype: Optional[torch.dtype]=None, layout: torch.layout=torch.strided, device: Optional[DeviceLikeType]=None, pin_memory: bool=False, requires_grad: bool=False) -> TensorLikeType:
    utils.check_layout(layout)
    utils.check_pin_memory(pin_memory)
    device = torch.device(utils.device_or_default(device))
    assert not isinstance(start, complex)
    assert not isinstance(end, complex)
    assert not isinstance(step, complex)
    if end is None:
        end = start
        start = 0
    torch._check(step != 0, lambda : 'step must be nonzero')
    if <MASK>:
        torch._check(end >= start, lambda : 'upper bound and lower bound inconsistent with step sign')
    elif step < 0:
        torch._check(end <= start, lambda : 'upper bound and lower bound inconsistent with step sign')

    def is_finite(x):
        return not isinstance(x, FloatWithoutSymFloat) or math.isfinite(x)
    torch._check(is_finite(start) and is_finite(end), lambda : f'unsupported range: {start} -> {end}')
    torch._check(is_finite(step), lambda : f'step must be finite but got {step}')
    args = (start, end, step)
    integer_args = builtins.all((isinstance(arg, IntLike) for arg in args))
    if dtype is None:
        dtype = torch.int64 if integer_args else torch.get_default_dtype()
    is_integer = utils.is_integer_dtype(dtype)
    if is_integer or integer_args:
        xstart = sym_int(start)
        xend = sym_int(end)
        xstep = sym_int(step)
    if dtype == torch.int64 or integer_args:
        sgn = bool(xstep > 0) - bool(xstep < 0)
        length = (xend - xstart + xstep - sgn) // xstep
    else:
        length = math.ceil((end - start) / step)
    if is_integer:
        return prims.iota(length, start=xstart, step=xstep, dtype=dtype, device=device, requires_grad=requires_grad)
    index = prims.iota(length, start=0, step=1, dtype=torch.int64, device=device, requires_grad=False)
    computation_dtype = torch.long if integer_args else utils.get_acc_type(dtype, device)
    index = _maybe_convert_to_dtype(index, computation_dtype)
    result = start + step * index
    result = _maybe_convert_to_dtype(result, dtype)
    if requires_grad:
        result.requires_grad_(True)
    return result

def get_initial_state(self, inputs):
    initial_state = backend.zeros_like(inputs)
    initial_state = backend.sum(initial_state, axis=1)
    shape = list(self.cell.kernel_shape)
    shape[-1] = self.cell.filters
    initial_state = self.cell.input_conv(initial_state, array_ops.zeros(tuple(shape), initial_state.dtype), padding=self.cell.padding)
    if <MASK>:
        return [initial_state for _ in self.cell.state_size]
    else:
        return [initial_state]

def _build_element_shape(shape):
    """Converts shape to a format understood by list_ops for element_shape.

  If `shape` is already a `Tensor` it is returned as-is. We do not perform a
  type check here.

  If shape is None or a TensorShape with unknown rank, -1 is returned.

  If shape is a scalar, an int32 tensor with empty list is returned. Note we
  do directly return an empty list since ops.convert_to_tensor would convert it
  to a float32 which is not a valid type for element_shape.

  If shape is a sequence of dims, None's in the list are replaced with -1. We
  do not check the dtype of the other dims.

  Args:
    shape: Could be None, Tensor, TensorShape or a list of dims (each dim could
      be a None, scalar or Tensor).

  Returns:
    A None-free shape that can be converted to a tensor.
  """
    if isinstance(shape, tensor_lib.Tensor):
        return shape
    if isinstance(shape, tensor_shape.TensorShape):
        shape = shape.as_list() if shape else None
    if shape is None:
        return -1
    if <MASK>:
        return ops.convert_to_tensor(shape, dtype=dtypes.int32)

    def convert(val):
        if val is None:
            return -1
        if isinstance(val, tensor_lib.Tensor):
            return val
        if isinstance(val, tensor_shape.Dimension):
            return val.value if val.value is not None else -1
        return val
    return [convert(d) for d in shape]

def _convert_guards_to_code(graph_module):
    shape_env = _get_shape_env(graph_module)
    if <MASK>:
        return []
    local_vars = {var for (var, sources) in shape_env.var_to_sources.items() if all((not isinstance(source, torch._dynamo.source.ConstantSource) for source in sources))}
    py_printer = torch.fx.experimental.symbolic_shapes.ShapeGuardPythonPrinter(shape_env.var_to_sources, lambda s: s.name(), shape_env.var_to_sources)
    return [py_printer.doprint(guard.expr) for guard in shape_env.guards if guard.expr.free_symbols.issubset(local_vars)]

