def _process_assign(self, node: ast.Assign) -> None:
    """Process top-level assign for potential symbol export."""
    if isinstance(node.value, ast.Call) and self._is_export_call(node.value.func):
        if len(node.targets) != 1:
            raise BadExportError(f'{self._current_file}:{node.lineno} export must be assigned to a single value: {ast.dump(node)}')
        symbol = self._name(node.targets[0])
        if <MASK>:
            raise BadExportError(f'{self._current_file}:{node.lineno} export must be assigned to a single value: {ast.dump(node)}')
        self._add_exported_symbol(node.value.func, symbol)
    else:
        self.visit(node)

def _enable_get_next_as_optional(strategy, dataset, cardinality):
    """Returns whether to enable using partial batch handling."""
    if <MASK>:
        return False
    if cardinality == cardinality_lib.INFINITE:
        return False
    return not _is_statically_shaped(dataset.element_spec) or strategy.extended._in_multi_worker_mode()

def _verifySolve(self, x, y, batch_dims=None):
    for np_type in [np.float32, np.float64, np.complex64, np.complex128]:
        if np_type == np.float32 or np_type == np.complex64:
            tol = 1e-05
        else:
            tol = 1e-12
        for adjoint in (False, True):
            if np_type in (np.float32, np.float64):
                a = x.real.astype(np_type)
                b = y.real.astype(np_type)
                a_np = np.transpose(a) if adjoint else a
            else:
                a = x.astype(np_type)
                b = y.astype(np_type)
                a_np = np.conj(np.transpose(a)) if adjoint else a
            if batch_dims is not None:
                a = np.tile(a, batch_dims + [1, 1])
                a_np = np.tile(a_np, batch_dims + [1, 1])
                b = np.tile(b, batch_dims + [1, 1])
            np_ans = np.linalg.solve(a_np, b)
            for use_placeholder in set((False, not context.executing_eagerly())):
                if <MASK>:
                    a_ph = array_ops.placeholder(dtypes.as_dtype(np_type))
                    b_ph = array_ops.placeholder(dtypes.as_dtype(np_type))
                    tf_ans = linalg_ops.matrix_solve(a_ph, b_ph, adjoint=adjoint)
                    with self.cached_session() as sess:
                        out = sess.run(tf_ans, {a_ph: a, b_ph: b})
                else:
                    tf_ans = linalg_ops.matrix_solve(a, b, adjoint=adjoint)
                    out = self.evaluate(tf_ans)
                    self.assertEqual(tf_ans.get_shape(), out.shape)
                self.assertEqual(np_ans.shape, out.shape)
                self.assertAllClose(np_ans, out, atol=tol, rtol=tol)

@register_prop_rule(aten.index.Tensor, schema_info=RuntimeSchemaInfo(needs_pytree=True))
def prop_index(op_schema: OpSchema) -> OutputSharding:
    """
    Expect replicated on the first input; _mostly_ pointwise on the second input.

    TODO: exception: when the dtype of second input is "bool", then a torch.nonzero needs to be triggered first.
    """
    (values_spec, multi_indices_spec) = op_schema.args_schema
    if not isinstance(values_spec, DTensorSpec):
        raise AssertionError(f'Expected DTensorSpec, got {type(values_spec)}')
    if not isinstance(multi_indices_spec, list):
        raise AssertionError(f'Expected list, got {type(multi_indices_spec)}')
    multi_indices_spec = cast(list[Optional[DTensorSpec]], multi_indices_spec)
    valid_indices_spec: list[tuple[int, DTensorSpec]] = [(i, a) for (i, a) in enumerate(multi_indices_spec) if a is not None]
    indices_out = pointwise_rule(OpSchema(op=op_schema.op, args_schema=tuple((v[1] for v in valid_indices_spec)), kwargs_schema={}))
    need_reshard_on_indices = indices_out.output_spec is None
    if <MASK>:
        if not isinstance(indices_out.output_spec, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(indices_out.output_spec)}')
        indices_spec: DTensorSpec = indices_out.output_spec
    else:
        if indices_out.redistribute_schema is None:
            raise AssertionError('redistribute_schema should not be None')
        valid_indices_suggestion = indices_out.redistribute_schema
        for (i, v) in enumerate(valid_indices_suggestion.args_spec):
            multi_indices_spec[valid_indices_spec[i][0]] = v
        indices_output_spec = pointwise_rule(valid_indices_suggestion).output_spec
        if not isinstance(indices_output_spec, DTensorSpec):
            raise AssertionError(f'Expected DTensorSpec, got {type(indices_output_spec)}')
        indices_spec = indices_output_spec
    lookup_dims = {v[0] for v in valid_indices_spec}
    need_reshard_on_values = tuple((isinstance(vp, Shard) and (vp.dim in lookup_dims or isinstance(ip, Shard)) for (vp, ip) in zip(values_spec.placements, indices_spec.placements)))
    if not need_reshard_on_indices and (not any(need_reshard_on_values)):
        value_placements = values_spec.placements
        all_dims_consecutive = all((b[0] - a[0] == 1 for (b, a) in zip(valid_indices_spec[1:], valid_indices_spec[:-1])))
        if all_dims_consecutive:
            insert_dim: int = valid_indices_spec[0][0]
        else:
            insert_dim = 0

        def place(vp: Placement, ip: Placement) -> Placement:
            if isinstance(vp, Shard):
                return Shard(vp.dim if vp.dim < insert_dim else vp.dim + indices_spec.ndim - sum((1 if vp.dim > v[0] else 0 for v in valid_indices_spec)))
            if isinstance(ip, Shard):
                return Shard(ip.dim + insert_dim)
            return vp
        value_placements = tuple((place(vp, ip) for (vp, ip) in zip(values_spec.placements, indices_spec.placements)))
        result = OutputSharding(output_spec=DTensorSpec(mesh=values_spec.mesh, placements=value_placements))
        return result
    else:
        result = OutputSharding(output_spec=None, redistribute_schema=OpSchema(op=op_schema.op, args_schema=(DTensorSpec(mesh=values_spec.mesh, placements=tuple((Replicate() if need_reshard_on_values[i] else v for (i, v) in enumerate(values_spec.placements))), tensor_meta=values_spec.tensor_meta), multi_indices_spec), kwargs_schema=op_schema.kwargs_schema))
        return result

def bytecode_from_template(fn: Callable[..., Any], varname_map: Optional[Mapping[Any, Any]]=None, noreturn: bool=True, noprefix: bool=True) -> list[Instruction]:
    """Generates bytecode from a template function `fn` for use in
    dynamo bytecode generation.

    For example, we can generate Python-version-independent bytecode
    for looping through a dictionary and copying the values to a new dictionary.

    def template(d1, d2):
        for k, v in d1.items():
            d2[k] = v


    or a try block:

    def template():
        try:
            dummy1
        except:
            dummy2
            raise
        dummy3

    Args:
        fn: a function template to generate bytecode from
        varname_map: a mapping of `fn`'s varnames to new names. This
            map will be applied to the generated bytecode's varnames.
            For example, local variables in `fn` can be replaced with
            new names that are generated by `OutputGraph.new_var`.
        noreturn: remove all RETURN_* bytecodes and replace them with a jump
            to the end of the bytecode. NOTE: any items pushed to the stack
            for return WILL remain on the stack! Append a POP_TOP if you don't want
            that item to be present.
        noprefix: remove prefix bytecodes (all bytecode before the first RESUME, inclusive).
    """
    insts = cleaned_instructions(fn.__code__)
    clear_instruction_args(insts)
    if noprefix:
        for (i, inst) in enumerate(insts):
            if inst.opname == 'RESUME':
                insts = insts[i + 1:]
                break
    for inst in insts:
        inst.starts_line = None
        inst.positions = None
        if varname_map and inst.argval in varname_map:
            inst.argval = varname_map[inst.argval]
    if noreturn:
        if sys.version_info >= (3, 12):
            new_insts = []
            for inst in insts:
                if <MASK>:
                    inst.opcode = dis.opmap['LOAD_CONST']
                    inst.opname = 'LOAD_CONST'
                    new_insts.append(inst)
                    new_insts.append(create_instruction('RETURN_VALUE'))
                else:
                    new_insts.append(inst)
            insts = new_insts
        returns = []
        for inst in insts:
            if inst.opname == 'RETURN_VALUE':
                returns.append(inst)
        if len(returns) == 1 and returns[0] is insts[-1]:
            insts.pop(-1)
        elif len(returns) > 0:
            if insts[-1] is returns[-1]:
                insts[-1].opname = 'NOP'
                insts[-1].opcode = dis.opmap['NOP']
                insts[-1].arg = None
                insts[-1].argval = _NotProvided
                returns.pop(-1)
            else:
                insts.append(create_instruction('NOP'))
            for inst in returns:
                jump_inst = create_jump_absolute(insts[-1])
                inst.opname = jump_inst.opname
                inst.opcode = jump_inst.opcode
                inst.arg = jump_inst.arg
                inst.argval = jump_inst.argval
                inst.target = jump_inst.target
    return insts

def get_key_func(key_func):
    """
    Function to decide which key function to use.

    Default to ``default_key_func``.
    """
    if <MASK>:
        if callable(key_func):
            return key_func
        else:
            return import_string(key_func)
    return default_key_func

def remove_field(self, model, field):
    """
        Remove a field from a model. Usually involves deleting a column,
        but for M2Ms may involve deleting a table.
        """
    if <MASK>:
        if field.remote_field.through._meta.auto_created:
            self.delete_model(field.remote_field.through)
    elif not field.primary_key and (not field.unique) and (not field.db_index) and (not (field.remote_field and field.db_constraint)):
        super().remove_field(model, field)
    else:
        if field.db_parameters(connection=self.connection)['type'] is None:
            return
        self._remake_table(model, delete_field=field)

def _compareValues(self, fd, vs, evs):
    """Compare lists/arrays of field values."""
    if <MASK>:
        self.fail('Field %s decoded %d outputs, expected %d' % (fd.name, len(vs), len(evs)))
    for (i, ev) in enumerate(evs):
        if fd.cpp_type == fd.CPPTYPE_FLOAT:
            self.assertTrue(np.isclose(vs[i], ev), 'expected %r, actual %r' % (ev, vs[i]))
        elif fd.cpp_type == fd.CPPTYPE_STRING:
            self.assertEqual(vs[i], ev.encode('ascii'))
        else:
            self.assertEqual(vs[i], ev)

def dimlists(n: Optional[int]=None, sizes: Optional[list[Optional[int]]]=None) -> Union[DimList, tuple[DimList, ...]]:
    """
    Create and return one or more DimList objects.

    Similar to dims() but creates DimList objects instead.
    """
    specified_ndims = -1
    found_ndims = 0
    if sizes is not None:
        specified_ndims = len(sizes)
    if n is not None:
        specified_ndims = n
    frame = inspect.currentframe()
    if frame is None:
        raise RuntimeError('Unable to get current frame')
    frame = frame.f_back
    try:
        if frame is None:
            raise RuntimeError('Unable to get caller frame')
        code = frame.f_code
        lasti = frame.f_lasti
        decoder = _PyInstDecoder(code, lasti)
        if sys.version_info >= (3, 11):
            if decoder.opcode() == 'PRECALL':
                decoder.next()
        decoder.next()
        if _relevant_op(decoder.opcode()):
            found_ndims = 1
        elif decoder.opcode() == 'UNPACK_SEQUENCE':
            found_ndims = decoder.oparg()
            decoder.next()
        if specified_ndims == -1:
            if found_ndims == 0:
                raise SyntaxError('dimlists() must be assigned to a sequence of variable names or have argument n specified')
            specified_ndims = found_ndims
        if found_ndims != specified_ndims:
            found_ndims = 0

        def genobject(i: int) -> str:
            nonlocal found_ndims
            name = None
            if <MASK>:
                name = decoder.name()
            if not name:
                name = f'd{i}'
                found_ndims = 0
            else:
                decoder.next()
            return name
        if sizes is not None and len(sizes) != specified_ndims:
            raise ValueError(f'expected {specified_ndims} sizes but found {len(sizes)}')
        if specified_ndims == 1:
            name = genobject(0)
            return _create_dimlist(name, sizes[0] if sizes is not None else None)
        result = []
        for i in range(specified_ndims):
            name = genobject(i)
            size = sizes[i] if sizes is not None else None
            result.append(_create_dimlist(name, size))
        return tuple(result)
    finally:
        del frame

def __str__(self) -> str:
    if self.is_empty():
        return 'Empty'
    pytest_filter = self.get_pytest_filter()
    if <MASK>:
        return self.test_file + ', ' + pytest_filter
    return self.test_file

def wrap(e: T) -> Union[T, FakeTensor]:
    nonlocal common_device
    nonlocal has_scalar_only_inputs
    if not isinstance(e, Tensor):
        return e
    if common_device is None:
        (common_device, has_scalar_only_inputs) = FakeTensor._find_common_device(func, flat_args)
    is_our_fake = self.is_our_fake(e)
    if <MASK>:
        torch._check(e.device == common_device, lambda : f'FakeTensor is wrapped to wrong device, found {e.device}, expected {common_device}')
        return cast(T, e)
    elif converter is not None:
        if has_scalar_only_inputs:
            return converter.from_real_tensor(self, e)
        else:
            return converter.from_meta_and_device(self, e, device or common_device)
    else:
        return e

def _flatten_optim_state_dict(optim_state_dict: dict[str, Any], model: nn.Module, use_orig_params: bool=False, optim: Optional[torch.optim.Optimizer]=None, rank0_only: bool=False, group: Optional[dist.ProcessGroup]=None) -> dict[str, Any]:
    """
    Flattens the full optimizer state dict, still keying by unflattened parameter
    names.

    If ``use_orig_params`` is True, each rank will have all FSDP-managed
    parameters but some of these parameters may be empty due to the sharding.
    For a regular optim.Optimizer, states for those empty parameters will
    not be initialized. So, when aggregating the FQNs across ranks, no assert
    will be raised on a rank even if it does not have all the states -- it is
    valid and FSDP know how to aggregate them. However, FSDP has to ignore
    handling those parameters that are not managed by FSDP and do not exist on
    the local rank -- it is managed by other parallelism and FSDP does not
    know ho to handle/aggregate them.

    Note that ``_flatten_tensor_optim_state`` does not need ``optim`` to
    flatten/shard the state. However, NamedOptimizer and KeyedOptimizer require
    all the states even if the corresponding parameters are empty. To this end,
    ``optim`` will be used to get the initial state of the empty parameters.
    ``optim`` should only be non-None if the ``optim` is KeyedOptimizer or
    NamedOptimizer.

    Returns:
        Dict[str, Any]: The flattened optimizer state dict.
    """
    SimpleProfiler.reset()
    unflat_osd = optim_state_dict
    if 'state' not in unflat_osd and (not rank0_only):
        raise ValueError('`optim_state_dict` must have the keys "state"to be a valid optimizer state dict')
    param_to_fqns = _get_param_to_fqns(model)
    fqn_to_fsdp_param_info = _get_fqn_to_fsdp_param_info(model)
    fsdp_state = next(iter(fqn_to_fsdp_param_info.values())).state
    if rank0_only:
        unflat_osd = _broadcast_processed_state(fsdp_state, unflat_osd, group=group)
    flat_osd_state: dict[Union[_OptimStateKey, str], Any] = {}
    unflat_osd_state = unflat_osd['state']
    all_state_keys = set(unflat_osd_state.keys())
    for (param, fqns) in param_to_fqns.items():
        fqn = fqns[0]
        if fqn not in unflat_osd_state:
            continue
        all_state_keys.difference_update(fqns)
        if rank0_only:
            for fqn in fqns:
                if not unflat_osd_state[fqn]:
                    continue
                for state_name in unflat_osd_state[fqn].keys():
                    unflat_osd_state[fqn][state_name] = _broadcast_state(fsdp_state, unflat_osd_state[fqn][state_name], group=group)
            fqn = fqns[0]
        if fqn in fqn_to_fsdp_param_info:
            fsdp_param_info = fqn_to_fsdp_param_info[fqn]
            if use_orig_params:
                with SimpleProfiler.profile(SimpleProfiler.Type.RESHARDING):
                    flat_state = _shard_orig_param_state(fsdp_param_info, fqn, unflat_osd_state[fqn])
            else:
                flat_state = _flatten_optim_state(fsdp_param_info, unflat_osd_state, fqns)
            key = _OptimStateKey(tuple(fqns), True)
            if flat_state:
                flat_osd_state[key] = flat_state
            elif use_orig_params:
                if len(fqns) != 1:
                    raise AssertionError(f'use_orig_params is True but there are multiple FQNs, {fqns}.')
                if <MASK>:
                    state = optim.state.get(param, None)
                    if state is not None:
                        flat_osd_state[key] = copy.deepcopy(state)
                    else:
                        warnings.warn(f'optim_state[{key}] is not on rank{fsdp_state.rank}.')
            else:
                raise RuntimeError(f'The state of {key} is empty. This should happen when use_orig_params=True.')
        else:
            if len(fqns) != 1:
                raise AssertionError(f'Expected len(fqns) == 1, got {len(fqns)}')
            key = _OptimStateKey(tuple(fqns), False)
            flat_osd_state[key] = copy.copy(unflat_osd_state[fqn])
        if rank0_only:
            for fqn in fqns:
                if not unflat_osd_state[fqn]:
                    continue
                for (state_name, param_state) in list(unflat_osd_state[fqn].items()):
                    if fsdp_state.rank > 0:
                        del unflat_osd_state[fqn][state_name]
                    else:
                        unflat_osd_state[fqn][state_name] = param_state.cpu()
    for key in all_state_keys:
        user_state = unflat_osd_state[key]
        if isinstance(user_state, torch.Tensor) and rank0_only and use_orig_params:
            user_state = _broadcast_state(fsdp_state, user_state, group=group)
        flat_osd_state[key] = copy.copy(user_state)
    SimpleProfiler.dump_and_reset('FSDP _flatten_optim_state_dict() profiling: ')
    if 'param_groups' in unflat_osd:
        flat_osd_param_groups = copy.deepcopy(unflat_osd['param_groups'])
        return {'state': flat_osd_state, 'param_groups': flat_osd_param_groups}
    else:
        return {'state': flat_osd_state}

def arg_is_blockwise(block_dimensions, arg, arg_split_dim):
    """Detect if input should be interpreted as a list of blocks."""
    if isinstance(arg, (tuple, list)) and len(arg) == len(block_dimensions):
        if not any((nest.is_nested(x) for x in arg)):
            return True
        else:
            arg_dims = [tensor_conversion.convert_to_tensor_v2_with_dispatch(x).shape[arg_split_dim] for x in arg]
            self_dims = [dim.value for dim in block_dimensions]
            if all((self_d is None for self_d in self_dims)):
                if <MASK>:
                    return False
                elif any((dim != arg_dims[0] for dim in arg_dims)):
                    return True
                else:
                    raise ValueError('Parsing of the input structure is ambiguous. Please input a blockwise iterable of `Tensor`s or a single `Tensor`.')
            if all((self_d == arg_d or self_d is None for (self_d, arg_d) in zip(self_dims, arg_dims))):
                return True
            self_dim = sum((self_d for self_d in self_dims if self_d is not None))
            if all((s == arg_dims[0] for s in arg_dims)) and arg_dims[0] >= self_dim:
                return False
            raise ValueError('Input dimension does not match operator dimension.')
    else:
        return False

def _check_single_device_module(module: nn.Module, ignored_params: set[nn.Parameter], device_id: Optional[Union[int, torch.device]]) -> None:
    """
    Raise an error if ``module`` has original parameters on multiple devices, ignoring the parameters in ``ignored_params``.

    Thus, after this method, the
    module must be either fully on the CPU or fully on a non-CPU device.
    """
    devices = {param.device for param in _get_orig_params(module, ignored_params)}
    if len(devices) == 2 and torch.device('cpu') in devices:
        if <MASK>:
            raise RuntimeError('To support a module with both CPU and GPU params, please pass in device_id argument.')
    elif len(devices) > 1:
        raise RuntimeError(f'FSDP only supports single device modules but got params on {devices}')

def skipIfNoONEDNNBF16(fn):
    reason = 'Quantized operations require BF16 support.'
    if isinstance(fn, type):
        if <MASK>:
            fn.__unittest_skip__ = True
            fn.__unittest_skip_why__ = reason
        return fn

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        if not torch.ops.mkldnn._is_mkldnn_bf16_supported():
            raise unittest.SkipTest(reason)
        else:
            fn(*args, **kwargs)
    return wrapper

def _get_shape(tensor):
    if <MASK>:
        return tensor_array_ops.TensorArray
    elif isinstance(tensor, indexed_slices.IndexedSlices):
        return tensor.dense_shape
    else:
        return tensor.get_shape()

def _str_map_nan_semantics(self, f, na_value=lib.no_default, dtype: Dtype | None=None):
    if dtype is None:
        dtype = self.dtype
    if na_value is lib.no_default:
        if <MASK>:
            na_value = False
        else:
            na_value = self.dtype.na_value
    mask = isna(self)
    arr = np.asarray(self)
    if is_integer_dtype(dtype) or is_bool_dtype(dtype):
        na_value_is_na = isna(na_value)
        if na_value_is_na:
            if is_integer_dtype(dtype):
                na_value = 0
            else:
                na_value = False
        result = lib.map_infer_mask(arr, f, mask.view('uint8'), convert=False, na_value=na_value, dtype=np.dtype(cast(type, dtype)))
        if na_value_is_na and is_integer_dtype(dtype) and mask.any():
            result = result.astype('float64')
            result[mask] = np.nan
        return result
    else:
        return self._str_map_str_or_object(dtype, na_value, arr, f, mask)

def speculate_subgraph(tx, f, sub_args, sub_kwargs, description, *, source_target=None, always_restore=False, enable_grad=None, set_subgraph_inputs='automatic', restore_side_effects=True, should_flatten_outputs=False, remove_consts_from_outputs=True, under_activation_checkpoint=False, supports_input_mutation=True, supports_aliasing=True, tracer=None):
    if sub_kwargs is None:
        sub_kwargs = {}
    assert set_subgraph_inputs in {'automatic', 'semi_automatic', 'flatten_manual', 'manual'}, 'Please use one of the supported set_subgraph_inputs options.'
    if sub_kwargs and set_subgraph_inputs != 'automatic':
        unimplemented('Use `set_subgraph_inputs=automatic` when passing `sub_kwargs`.')
    try:
        (f, sub_args, sub_kwargs) = LazyVariableTracker.realize_all((f, sub_args, sub_kwargs))
        with tx.output.subtracer(source_target, tracer) as subtracer:
            sub_args_names = maybe_positional_arg_names(f)
            if sub_args_names is not None and len(sub_args_names) < len(sub_args):
                sub_args_names = None
            args = validate_args_and_maybe_create_graph_inputs(sub_args, subtracer, tx, set_subgraph_inputs, description, sub_args_names)
            validate_args_and_maybe_create_graph_inputs(sub_kwargs.values(), subtracer, tx, set_subgraph_inputs='automatic', description=description)
            autograd_ctx = dynamo_enable_grad(tx, enable_grad) if enable_grad is not None else contextlib.nullcontext()
            checkpoint_ctx = dynamo_under_activation_checkpoint(tx) if under_activation_checkpoint else contextlib.nullcontext()
            if restore_side_effects:
                prev_side_effects = tx.output.side_effects.clone()
            with autograd_ctx, checkpoint_ctx:
                output = f.call_function(tx, args, sub_kwargs)
            if restore_side_effects:
                new_side_effects = tx.output.side_effects.clone()
                prev_side_effects.track_runahead_tensor_and_symvar_side_effects(new_side_effects)
                tx.output.side_effects = prev_side_effects
            treespec = None
            masks_to_filter_const_values = None
            const_values = None
            if should_flatten_outputs:
                from torch._dynamo.external_utils import filter_out_const_values
                (output, treespec) = _make_inlined(tx, pytree.tree_flatten)(output).unpack_var_sequence(tx)
                output = BuiltinVariable(tuple).call_function(tx, [output], {})
                if remove_consts_from_outputs:
                    output_proxies = output.as_proxy()
                    masks_to_filter_const_values = pytree.tree_map(lambda x: not isinstance(x, torch.fx.Proxy), output_proxies)
                    const_values = pytree.tree_map(lambda x: None if isinstance(x, torch.fx.Proxy) else x, output_proxies)
                    output = _make_inlined(tx, filter_out_const_values)(output, masks_to_filter_const_values)
            if always_restore:
                return ((output, OutputSpec(treespec, masks_to_filter_const_values, const_values)), tx.output.graph, subtracer.lifted_freevars)
            else:
                validate_subgraph_output_types(output)
                output_proxies = output.as_proxy()
                output_proxies = pytree.tree_map(subtracer.maybe_lift_tracked_freevar_to_input, output_proxies)
                tx.output.create_node('output', 'output', subtracer.create_arg((output_proxies,)), {})
                graph = tx.output.graph
                graph.lint()
                lifted_freevars = subtracer.lifted_freevars

                def move_lifted_freevars_phs_to_end(graph: torch.fx.Graph, lifted_freevars: tuple[torch.fx.Node]):
                    lifted_ph_set = {child_p.node for child_p in lifted_freevars.values()}
                    prev_phs = [n for n in graph.nodes if n.op == 'placeholder']
                    if len(prev_phs) == 0 or len(lifted_ph_set) == 0 or len(prev_phs) == len(lifted_ph_set):
                        return
                    for x1 in prev_phs:
                        if x1 in lifted_ph_set:
                            break
                    assert x1 is not None and x1.op == 'placeholder'
                    cand_x = x1.next
                    while cand_x is not None and cand_x.op == 'placeholder':
                        if cand_x in lifted_ph_set:
                            cand_x = cand_x.next
                        else:
                            nxt = cand_x.next
                            cand_x._remove_from_list()
                            x1.prepend(cand_x)
                            cand_x = nxt
                    after_phs = [node for node in graph.nodes if node.op == 'placeholder'][-len(lifted_freevars):]
                    assert len(after_phs) == len(lifted_freevars)
                    for (child_proxy, ph) in zip(lifted_freevars.values(), after_phs):
                        assert child_proxy.node is ph, 'The order of placeholders is different from the order of lifted_freevars'
                    graph.lint()
                if <MASK>:
                    move_lifted_freevars_phs_to_end(graph, lifted_freevars)
                if not supports_input_mutation:
                    mutation_info = subtracer.has_input_mutation()
                    if mutation_info.has_mutation:
                        context = f'{mutation_info.msg} in\n {graph}'
                        unimplemented_v2(gb_type='Encountered input mutation during higher order op tracing', context=context, explanation=f'Higher order ops do not support input mutation. Found in {source_target.name()}', hints=['Consider using the debug context to change user code to avoid mutation.', 'Please open an issue.'])
                if not supports_aliasing:
                    aliasing_info = subtracer.has_aliasing()
                    if aliasing_info.has_aliasing:
                        context = f'{aliasing_info.msg} in\n {graph}'
                        unimplemented_v2(gb_type='Encountered aliasing during higher order op tracing', context=context, explanation=f'Higher order ops do not support aliasing. Found in {source_target.name()}', hints=['Replace `return input` with `return input.clone()` to avoid aliasing.', 'Consider using the debug context to change user code to avoid aliasing.', 'Please open an issue.'])
                return ((output, OutputSpec(treespec, masks_to_filter_const_values, const_values)), graph, lifted_freevars)
    except Unsupported as ex:
        f_name = f'{type(f).__name__}'
        if isinstance(f, UserFunctionVariable):
            f_name = f.get_name()
        msg = f'speculate_subgraph: while introspecting {description}, we were unable to trace function `{f_name}` into a single graph. This means that Dynamo was unable to prove safety for this API and will fall back to eager-mode PyTorch, which could lead to a slowdown.'
        log.info(msg)
        log.info(ex)
        raise ex

def _annotate_propagation_quantizable_pattern(self, node: Node, quantization_config, filter_fn) -> None:
    if <MASK>:

        def is_all_inputs_connected_to_quantized_op(input_nodes):
            for input_node in input_nodes:
                if not _is_quantized_op_pt2e(input_node):
                    return False
            return True
        if _skip_annotate([node], filter_fn):
            return
        if quantization_config is None:
            _annotate_nodes_not_quantize(node)
            return
        if node.target is torch.ops.aten.max_pool2d.default:
            input_nodes_to_check = [node.all_input_nodes[0]]
            if not is_all_inputs_connected_to_quantized_op(input_nodes_to_check):
                if quantization_config is not None:
                    warnings.warn(f'The input of maxpool2d is not quantized, skip annotate maxpool2d with config {quantization_config}.')
                return
            self._annotate_maxpool2d(node, quantization_config)
            return
        elif node.target is torch.ops.aten.cat.default:
            input_nodes_to_check = node.all_input_nodes
            if not is_all_inputs_connected_to_quantized_op(input_nodes_to_check):
                return
            self._annotate_cat(node, quantization_config)
        elif node.target is torch.ops.aten.flatten.using_ints and len(node.users) > 0 and (not any((user.target in quantizable_ops for user in node.users.keys()))):
            return
        else:
            input_node = node.all_input_nodes[0]
            if not is_all_inputs_connected_to_quantized_op([input_node]):
                return
            input_qspec_map = {}
            input_qspec_map[input_node] = get_input_act_qspec(quantization_config)
            node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(input_qspec_map=input_qspec_map, _annotated=True, _is_output_of_quantized_pattern=True)
    return

def nontensors_match(self, other: 'SplitInputs'):
    if <MASK>:
        return False
    if self.kwarg_types != other.kwarg_types:
        return False
    if self.kwarg_order != other.kwarg_order:
        return False
    if self.nontensor_args != other.nontensor_args:
        return False
    if self.nontensor_kwargs != other.nontensor_kwargs:
        return False
    return True

@_onnx_symbolic('aten::as_strided')
@symbolic_helper.quantized_args(True)
@symbolic_helper.parse_args('v', 'v', 'is', 'i')
def as_strided(g: jit_utils.GraphContext, self, sizes, strides, offset=None):
    sizes = symbolic_helper._maybe_get_const(sizes, 'is')
    rank = len(strides)
    self_1d = symbolic_helper._reshape_helper(g, self, g.op('Constant', value_t=torch.tensor([-1], dtype=torch.int64)))
    ind: torch.Tensor | None
    if not symbolic_helper._is_value(sizes):
        ind = torch.tensor([0], dtype=torch.long)
        for (i, (size, stride)) in enumerate(zip(sizes, strides)):
            r_size = [1] * rank
            r_size[i] = -1
            ind = ind + torch.arange(size).view(r_size) * stride
        if offset:
            ind = ind + offset
        return g.op('Gather', self_1d, g.op('Constant', value_t=ind))
    else:
        ind = None
        for (i, stride) in enumerate(strides):
            r_size = [1] * rank
            r_size[i] = -1
            size = select(g, sizes, g.op('Constant', value_t=torch.tensor([0])), g.op('Constant', value_t=torch.tensor(i)))
            tmp_ind = symbolic_helper._reshape_helper(g, arange(g, size, 4, None, None, None), g.op('Constant', value_t=torch.tensor(r_size)))
            tmp_ind = g.op('Mul', tmp_ind, g.op('Constant', value_t=torch.tensor([stride])))
            if <MASK>:
                ind = tmp_ind
            else:
                ind = g.op('Add', ind, tmp_ind)
        if offset:
            ind = g.op('Add', ind, g.op('Constant', torch.tensor([offset])))
        return g.op('Gather', self_1d, ind)

def load_tensor(dtype, numel, key, location):
    name = f'data/{key}'
    if torch._guards.detect_fake_mode(None) is not None:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes, device='meta')
        if can_calculate_storage_offsets:
            storage._checkpoint_offset = _get_offset(key, name, numel)
        else:
            storage._checkpoint_offset = zip_file.get_record_offset(name)
    elif _serialization_tls.skip_data:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes)
    elif overall_storage is not None:
        if can_calculate_storage_offsets and calculate_storage_offsets:
            storage_offset = _get_offset(key, name, numel)
            if run_debug_asserts:
                if storage_offset != zip_file.get_record_offset(name):
                    raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        else:
            storage_offset = zip_file.get_record_offset(name)
        storage = overall_storage[storage_offset:storage_offset + numel]
    else:
        if <MASK>:
            storage_offset = _get_offset(key, name, numel)
            if storage_offset != zip_file.get_record_offset(name):
                raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        storage = zip_file.get_storage_from_record(name, numel, torch.UntypedStorage)._typed_storage()._untyped_storage
    if byteorderdata is not None:
        if byteorderdata.decode() != sys.byteorder:
            storage.byteswap(dtype)
    if torch._guards.detect_fake_mode(None) is None:
        wrap_storage = restore_location(storage, location)
    else:
        storage._fake_device = location
        wrap_storage = storage
    typed_storage = torch.storage.TypedStorage(wrap_storage=wrap_storage, dtype=dtype, _internal=True)
    if typed_storage._data_ptr() != 0:
        loaded_storages[key] = typed_storage
    return typed_storage

@property
def flat_captures(self) -> List[trace.TraceType]:
    """Flat tensor captures needed by this FunctionType."""
    if <MASK>:
        cached_flat_captures = []
        for t in self.captures.values():
            cached_flat_captures.extend(t.flatten())
        self._cached_flat_captures = cached_flat_captures
    return self._cached_flat_captures

def calc_info(self):
    lib_dirs = self.get_lib_dirs()
    info = {}
    opt = self.get_option_single('atlas_libs', 'libraries')
    atlas_libs = self.get_libs(opt, self._lib_names + self._lib_atlas)
    lapack_libs = self.get_libs('lapack_libs', self._lib_lapack)
    atlas = None
    lapack = None
    atlas_1 = None
    for d in lib_dirs:
        atlas = self.check_libs2(d, atlas_libs, [])
        if atlas is not None:
            lib_dirs2 = [d] + self.combine_paths(d, ['atlas*', 'ATLAS*'])
            lapack = self.check_libs2(lib_dirs2, lapack_libs, [])
            if lapack is not None:
                break
        if atlas:
            atlas_1 = atlas
    log.info(self.__class__)
    if atlas is None:
        atlas = atlas_1
    if atlas is None:
        return
    include_dirs = self.get_include_dirs()
    h = self.combine_paths(lib_dirs + include_dirs, 'cblas.h') or [None]
    h = h[0]
    if h:
        h = os.path.dirname(h)
        dict_append(info, include_dirs=[h])
    info['language'] = 'c'
    if lapack is not None:
        dict_append(info, **lapack)
        dict_append(info, **atlas)
    elif 'lapack_atlas' in atlas['libraries']:
        dict_append(info, **atlas)
        dict_append(info, define_macros=[('ATLAS_WITH_LAPACK_ATLAS', None)])
        self.set_info(**info)
        return
    else:
        dict_append(info, **atlas)
        dict_append(info, define_macros=[('ATLAS_WITHOUT_LAPACK', None)])
        message = textwrap.dedent('\n                *********************************************************************\n                    Could not find lapack library within the ATLAS installation.\n                *********************************************************************\n                ')
        warnings.warn(message, stacklevel=2)
        self.set_info(**info)
        return
    lapack_dir = lapack['library_dirs'][0]
    lapack_name = lapack['libraries'][0]
    lapack_lib = None
    lib_prefixes = ['lib']
    if <MASK>:
        lib_prefixes.append('')
    for e in self.library_extensions():
        for prefix in lib_prefixes:
            fn = os.path.join(lapack_dir, prefix + lapack_name + e)
            if os.path.exists(fn):
                lapack_lib = fn
                break
        if lapack_lib:
            break
    if lapack_lib is not None:
        sz = os.stat(lapack_lib)[6]
        if sz <= 4000 * 1024:
            message = textwrap.dedent('\n                    *********************************************************************\n                        Lapack library (from ATLAS) is probably incomplete:\n                          size of %s is %sk (expected >4000k)\n\n                        Follow the instructions in the KNOWN PROBLEMS section of the file\n                        numpy/INSTALL.txt.\n                    *********************************************************************\n                    ') % (lapack_lib, sz / 1024)
            warnings.warn(message, stacklevel=2)
        else:
            info['language'] = 'f77'
    (atlas_version, atlas_extra_info) = get_atlas_version(**atlas)
    dict_append(info, **atlas_extra_info)
    self.set_info(**info)

def _jit_compile(name, sources, extra_cflags, extra_cuda_cflags, extra_sycl_cflags, extra_ldflags, extra_include_paths, build_directory: str, verbose: bool, with_cuda: Optional[bool], with_sycl: Optional[bool], is_python_module, is_standalone, keep_intermediates=True) -> Union[types.ModuleType, str]:
    if is_python_module and is_standalone:
        raise ValueError('`is_python_module` and `is_standalone` are mutually exclusive.')
    if with_cuda is None:
        with_cuda = any(map(_is_cuda_file, sources))
    with_cudnn = any(('cudnn' in f for f in extra_ldflags or []))
    if with_sycl is None:
        with_sycl = any(map(_is_sycl_file, sources))
    old_version = JIT_EXTENSION_VERSIONER.get_version(name)
    version = JIT_EXTENSION_VERSIONER.bump_version_if_changed(name, sources, build_arguments=[extra_cflags, extra_cuda_cflags, extra_ldflags, extra_include_paths], build_directory=build_directory, with_cuda=with_cuda, with_sycl=with_sycl, is_python_module=is_python_module, is_standalone=is_standalone)
    if version > 0:
        if version != old_version and verbose:
            logger.info('The input conditions for extension module %s have changed.', name)
            logger.info('Bumping to version %s and re-building as %s_v%s...', version, name, version)
        name = f'{name}_v{version}'
    baton = FileBaton(os.path.join(build_directory, 'lock'))
    if <MASK>:
        try:
            if version != old_version:
                from .hipify import hipify_python
                from .hipify.hipify_python import GeneratedFileCleaner
                with GeneratedFileCleaner(keep_intermediates=keep_intermediates) as clean_ctx:
                    if IS_HIP_EXTENSION and (with_cuda or with_cudnn):
                        hipify_result = hipify_python.hipify(project_directory=build_directory, output_directory=build_directory, header_include_dirs=extra_include_paths if extra_include_paths is not None else [], extra_files=[os.path.abspath(s) for s in sources], ignores=[_join_rocm_home('*'), os.path.join(_TORCH_PATH, '*')], show_detailed=verbose, show_progress=verbose, is_pytorch_extension=True, clean_ctx=clean_ctx)
                        hipified_sources = set()
                        for source in sources:
                            s_abs = os.path.abspath(source)
                            hipified_sources.add(hipify_result[s_abs].hipified_path if s_abs in hipify_result else s_abs)
                        sources = list(hipified_sources)
                    _write_ninja_file_and_build_library(name=name, sources=sources, extra_cflags=extra_cflags or [], extra_cuda_cflags=extra_cuda_cflags or [], extra_sycl_cflags=extra_sycl_cflags or [], extra_ldflags=extra_ldflags or [], extra_include_paths=extra_include_paths or [], build_directory=build_directory, verbose=verbose, with_cuda=with_cuda, with_sycl=with_sycl, is_standalone=is_standalone)
            elif verbose:
                logger.debug('No modifications detected for re-loaded extension module %s, skipping build step...', name)
        finally:
            baton.release()
    else:
        baton.wait()
    if verbose:
        logger.info('Loading extension module %s...', name)
    if is_standalone:
        return _get_exec_path(name, build_directory)
    return _import_module_from_library(name, build_directory, is_python_module)

def _manager_path():
    if platform.system() == 'Windows':
        return b''
    path = get_file_path('torch', 'bin', 'torch_shm_manager')
    prepare_multiprocessing_environment(get_file_path('torch'))
    if <MASK>:
        raise RuntimeError('Unable to find torch_shm_manager at ' + path)
    return path.encode('utf-8')

def placeholder_naming_pass(gm: torch.fx.GraphModule, export_graph_signature: 'ExportGraphSignature', mod: torch.nn.Module, fake_args, fake_kwargs, fake_params_buffers, constants: dict[str, Any]) -> None:
    """
    This pass is run at the end of _export_non_strict() to assign better placeholder node names:
        - User inputs:
            These follow the signature of mod.forward(), e.g. forward(x, y) produces nodes x, y.
            For nested inputs from dictionaries, lists, tuples, or dataclasses,
            the names are a concatenation of the path to the tensor.
                e.g. x = {
                    'a': torch.randn(),
                    'b': [torch.randn(), torch.randn()]
                }
            produces nodes x_a, x_b_0, x_b_1.
        - Parameters/buffers/constants/custom objects:
            These follow the FQN of the object, prefixed by "p", "b", "c", "obj" respectively.
                e.g. self.bar.l0.weight produces "p_bar_l0_weight".
        - Effect tokens:
            These are named token, token_1, ...
    """
    custom_meta: dict[str, Any] = {}
    if isinstance(mod, torch.fx.GraphModule):
        for node in mod.graph.nodes:
            if 'custom' in node.meta:
                custom_meta[node.name] = node.meta['custom']

    def _strip_name(x):
        if <MASK>:
            x = x[len('L__self___'):]
        elif x.startswith('self_'):
            x = x[len('self_'):]
        x = re.sub('[^a-zA-Z0-9]', '_', x)
        return x

    def _extract_pytree_key(x):
        if isinstance(x, MappingKey):
            x = re.sub('[^a-zA-Z0-9]', '_', str(x.key))
            return x
        elif isinstance(x, SequenceKey):
            return str(x.idx)
        elif isinstance(x, GetAttrKey):
            return x.name
        else:
            raise RuntimeError(f'Pytree key of type {type(x)} not handled for {x}')
    name_map: dict[str, str] = {}
    find_available: dict[str, int] = defaultdict(int)
    used_names: set[str] = set()
    combined_args = _bind_signature_to_inputs(mod, fake_args, fake_kwargs)
    (flat_args_with_path, _) = tree_flatten_with_path(combined_args)
    user_input_names = [spec.arg.name for spec in export_graph_signature.input_specs if spec.kind == InputKind.USER_INPUT]
    for ((arg_path, _arg), user_input_name) in zip(flat_args_with_path, user_input_names):
        if user_input_name:
            _rename_without_collisions(name_map, find_available, used_names, user_input_name, placeholder_prefixes[InputKind.USER_INPUT] + '_'.join((_extract_pytree_key(x).lower() for x in arg_path)), is_placeholder=True)
    for spec in export_graph_signature.input_specs:
        if spec.kind == InputKind.USER_INPUT:
            continue
        if spec.kind == InputKind.TOKEN:
            base_name = ''
        else:
            base_name = _strip_name(spec.target).lower()
        base_name = re.sub('[^a-zA-Z0-9]', '_', base_name)
        _rename_without_collisions(name_map, find_available, used_names, spec.arg.name, placeholder_prefixes[spec.kind] + base_name, is_placeholder=True)
        if base_name in custom_meta:
            custom_meta[name_map[spec.arg.name]] = custom_meta[base_name]
            del custom_meta[base_name]
    for node in gm.graph.nodes:
        if node.op == 'placeholder':
            continue
        _rename_without_collisions(name_map, find_available, used_names, node.name, node.name)
    for node in gm.graph.nodes:
        if node.op == 'placeholder':
            assert node.name in name_map
            node.name = node.target = name_map[node.name]
            if node.name in custom_meta:
                if node.meta.get('custom') is None:
                    node.meta['custom'] = custom_meta[node.name]
                else:
                    assert node.meta['custom'] == custom_meta[node.name]
            if isinstance(node.meta['val'], CustomObjArgument):
                node.meta['val'].name = node.name
        elif node.name in name_map:
            node.name = name_map[node.name]
    _name_hoo_subgraph_placeholders(gm)
    gm.recompile()
    for spec in export_graph_signature.input_specs:
        assert spec.arg.name in name_map
        spec.arg.name = name_map[spec.arg.name]
        if spec.kind == InputKind.CUSTOM_OBJ and spec.target in name_map:
            spec.target = name_map[spec.target][4:]
    for spec in export_graph_signature.output_specs:
        if spec.arg.name in name_map:
            spec.arg.name = name_map[spec.arg.name]
        if spec.kind == OutputKind.USER_INPUT_MUTATION and spec.target in name_map:
            spec.target = name_map[spec.target]
    for name in list(constants.keys()):
        constant = constants[name]
        if name in name_map and (not isinstance(constant, torch.Tensor)):
            new_name = name_map[name]
            if new_name != name and re.match('arg(\\d+)_1', name) and (new_name != placeholder_prefixes[InputKind.CUSTOM_OBJ] + name):
                constants[new_name] = constant
                del constants[name]

def _interleave(self, dtype: np.dtype | None=None, na_value: object=lib.no_default) -> np.ndarray:
    """
        Return ndarray from blocks with specified item order
        Items must be contained in the blocks
        """
    if not dtype:
        dtype = interleaved_dtype([blk.dtype for blk in self.blocks])
    dtype = ensure_np_dtype(dtype)
    result = np.empty(self.shape, dtype=dtype)
    itemmask = np.zeros(self.shape[0])
    if <MASK>:
        for blk in self.blocks:
            rl = blk.mgr_locs
            arr = blk.get_values(dtype)
            result[rl.indexer] = arr
            itemmask[rl.indexer] = 1
        return result
    for blk in self.blocks:
        rl = blk.mgr_locs
        if blk.is_extension:
            arr = blk.values.to_numpy(dtype=dtype, na_value=na_value)
        else:
            arr = blk.get_values(dtype)
        result[rl.indexer] = arr
        if na_value is not lib.no_default and blk.dtype.kind in 'mM':
            result[rl.indexer][isna(arr)] = na_value
        itemmask[rl.indexer] = 1
    if not itemmask.all():
        raise AssertionError('Some items were not contained in blocks')
    return result

def run_gpu_or_tpu(func: _F) -> _F:
    """Execute the decorated test only if a physical GPU or TPU is available.

  This function is intended to be applied to tests that require the presence
  of a physical GPU or TPU. It complies with the following rules:
  - If a GPU is available, the test will run on the GPU.
  - If a GPU is absent and a TPU is available, the test will run on the TPU.
  - If both GPU and TPU are absent, the test will be skipped.

  Args:
    func: function to be annotated.

  Returns:
    Returns a function that will conditionally skip the decorated test method.
  """
    if <MASK>:
        raise ValueError('`run_gpu_or_tpu` only supports test methods.')

    def decorated(self: 'TensorFlowTestCase', *args, **kwargs):
        if config.list_physical_devices('GPU'):
            return func(self, 'GPU', *args, **kwargs)
        if config.list_physical_devices('TPU'):
            return func(self, 'TPU', *args, **kwargs)
        self.skipTest('Test requires GPU or TPU')
    return decorated

def _annotate_conv2d_binary_unary(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = find_sequential_partitions(gm, [torch.nn.Conv2d, operator.add, torch.nn.ReLU])
    for fused_partition in fused_partitions:
        (conv_partition, binary_partition, unary_partition) = fused_partition
        (conv_node, binary_node, unary_node) = self._get_output_nodes_of_partitions([conv_partition, binary_partition, unary_partition])
        if len(conv_node.users) != 1:
            continue
        (conv_node_idx, extra_input_node_idx) = self._get_input_idx_for_binary_node(conv_node, binary_node)
        if conv_node_idx is None or extra_input_node_idx is None:
            continue
        if <MASK>:
            raise ValueError(f"{conv_node} doesn't match input of binary node")
        extra_input_node = binary_node.args[extra_input_node_idx]
        if conv_node.op != 'call_function' or conv_node.target != torch.ops.aten.conv2d.default:
            continue
        if _skip_annotate([unary_node, binary_node, conv_node], filter_fn):
            continue
        if quantization_config is None:
            _annotate_nodes_not_quantize([conv_node, binary_node, unary_node])
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        binary_node_input_qspec_map = {}
        binary_node_input_qspec_map[extra_input_node] = get_input_act_qspec(quantization_config)
        binary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(input_qspec_map=binary_node_input_qspec_map, _annotated=True)
        unary_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(_annotated=True, _is_output_of_quantized_pattern=True)

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == 'append' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (arg,) = args
        tx.output.side_effects.mutation(self)
        self.items.append(arg)
        return ConstantVariable.create(None)
    elif name == 'extend' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if not args[0].has_force_unpack_var_sequence(tx):
            msg = ConstantVariable.create(f'{type(args[0])} object is not iterable')
            raise_observed_exception(TypeError, tx, args=[msg])
        (arg,) = args
        arg.force_apply_to_var_sequence(tx, lambda item: self.call_method(tx, 'append', [item], {}))
        return ConstantVariable.create(None)
    elif name == 'insert' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (idx, value) = args
        if isinstance(idx, SymNodeVariable):
            const_idx = idx.evaluate_expr()
        else:
            const_idx = idx.as_python_constant()
        tx.output.side_effects.mutation(self)
        self.items.insert(const_idx, value)
        return ConstantVariable.create(None)
    elif name == 'pop' and self.is_mutable():
        if kwargs or len(args) > 1:
            raise_args_mismatch(tx, name, 'at most 1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if len(self.items) == 0:
            msg = ConstantVariable.create('pop from empty list')
            raise_observed_exception(IndexError, tx, args=[msg])
        if len(args):
            idx = args[0].as_python_constant()
            if idx > len(self.items):
                msg = ConstantVariable.create('pop index out of range')
                raise_observed_exception(IndexError, tx, args=[msg])
        tx.output.side_effects.mutation(self)
        return self.items.pop(*[a.as_python_constant() for a in args])
    elif name == 'clear' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        self.items.clear()
        return ConstantVariable.create(None)
    elif name == '__setitem__' and self.is_mutable() and args and (args[0].is_python_constant() or isinstance(args[0], SymNodeVariable) or (isinstance(args[0], SliceVariable) and all((s.is_python_constant() or isinstance(s, SymNodeVariable) for s in args[0].items)))):
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        (key, value) = args
        tx.output.side_effects.mutation(self)
        if isinstance(key, SymNodeVariable):
            self.items[key.evaluate_expr()] = value
        elif isinstance(key, SliceVariable):
            if key.is_python_constant():
                self.items[key.as_python_constant()] = list(value.items)
            else:
                items = slice(*[s.evaluate_expr() if isinstance(s, SymNodeVariable) else s.as_python_constant() for s in key.items])
                self.items[items] = list(value.items)
        else:
            self.items[key.as_python_constant()] = value
        return ConstantVariable.create(None)
    elif name == '__delitem__' and self.is_mutable():
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        tx.output.side_effects.mutation(self)
        if args[0].is_python_constant() and isinstance(args[0].as_python_constant(), (int, slice)):
            if isinstance(args[0], SymNodeVariable):
                idx = args[0].evaluate_expr()
            else:
                idx = args[0].as_python_constant()
            try:
                self.items.__delitem__(idx)
            except (IndexError, ValueError) as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            msg = ConstantVariable.create(f'list indices must be integers or slices, not {args[0].python_type_name()}')
            raise_observed_exception(TypeError, tx, args=[msg])
        return ConstantVariable.create(None)
    elif name == 'copy':
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        items = list(self.items)
        return self.modified(items, mutation_type=ValueMutationNew())
    elif name == 'reverse' and self.is_mutable():
        if args or kwargs:
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        self.items.reverse()
        tx.output.side_effects.mutation(self)
        return ConstantVariable.create(None)
    elif <MASK>:
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        idx = self.call_method(tx, 'index', args, kwargs)
        self.call_method(tx, 'pop', [idx], {})
        return ConstantVariable.create(None)
    else:
        return super().call_method(tx, name, args, kwargs)

def _parse_target_tokens(self, tokens):
    assert isinstance(tokens, str)
    final_targets = []
    extra_flags = []
    has_baseline = False
    skipped = set()
    policies = set()
    multi_target = None
    tokens = list(filter(None, re.split(self._parse_regex_target, tokens)))
    if not tokens:
        self.dist_fatal('expected one token at least')
    for tok in tokens:
        TOK = tok.upper()
        ch = tok[0]
        if ch in ('+', '-'):
            self.dist_fatal("+/- are 'not' allowed from target's groups or @targets, only from cpu_baseline and cpu_dispatch parms")
        elif ch == '$':
            if multi_target is not None:
                self.dist_fatal("policies aren't allowed inside multi-target '()', only CPU features")
            policies.add(self._parse_token_policy(TOK))
        elif ch == '#':
            if multi_target is not None:
                self.dist_fatal("target groups aren't allowed inside multi-target '()', only CPU features")
            (has_baseline, final_targets, extra_flags) = self._parse_token_group(TOK, has_baseline, final_targets, extra_flags)
        elif ch == '(':
            if multi_target is not None:
                self.dist_fatal("unclosed multi-target, missing ')'")
            multi_target = set()
        elif ch == ')':
            if multi_target is None:
                self.dist_fatal("multi-target opener '(' wasn't found")
            targets = self._parse_multi_target(multi_target)
            if targets is None:
                skipped.add(tuple(multi_target))
            else:
                if len(targets) == 1:
                    targets = targets[0]
                if targets and targets not in final_targets:
                    final_targets.append(targets)
            multi_target = None
        else:
            if TOK == 'BASELINE':
                if multi_target is not None:
                    self.dist_fatal("baseline isn't allowed inside multi-target '()'")
                has_baseline = True
                continue
            if multi_target is not None:
                multi_target.add(TOK)
                continue
            if not self.feature_is_exist(TOK):
                self.dist_fatal("invalid target name '%s'" % TOK)
            is_enabled = TOK in self.parse_baseline_names or TOK in self.parse_dispatch_names
            if is_enabled:
                if <MASK>:
                    final_targets.append(TOK)
                continue
            skipped.add(TOK)
    if multi_target is not None:
        self.dist_fatal("unclosed multi-target, missing ')'")
    if skipped:
        self.dist_log('skip targets', skipped, 'not part of baseline or dispatch-able features')
    final_targets = self.feature_untied(final_targets)
    for p in list(policies):
        (_, _, deps) = self._parse_policies[p]
        for d in deps:
            if d in policies:
                continue
            self.dist_log("policy '%s' force enables '%s'" % (p, d))
            policies.add(d)
    for (p, (have, nhave, _)) in self._parse_policies.items():
        func = None
        if p in policies:
            func = have
            self.dist_log("policy '%s' is ON" % p)
        else:
            func = nhave
        if not func:
            continue
        (has_baseline, final_targets, extra_flags) = func(has_baseline, final_targets, extra_flags)
    return (has_baseline, final_targets, extra_flags)

def call_setattr(self, tx: 'InstructionTranslator', obj: VariableTracker, name_var: VariableTracker, val: VariableTracker):
    if isinstance(obj, (variables.PlacementVariable, variables.NamedTupleVariable, variables.UserDefinedObjectVariable, variables.NestedUserFunctionVariable, variables.ExceptionVariable)):
        return obj.call_method(tx, '__setattr__', [name_var, val], {})
    elif tx.output.side_effects.is_attribute_mutation(obj) and name_var.is_python_constant():
        name = name_var.as_python_constant()
        if isinstance(obj, variables.TensorVariable):
            from .builder import wrap_fx_proxy
            if <MASK>:
                unimplemented_v2(gb_type='setattr() on Tensor.requires_grad', context=f'setattr({obj}, {name}, {val})', explanation='setattr() on Tensor.requires_grad not supported. Mutating requires_grad can introduce a new leaf from non-leaf or vice versa in the middle of the graph, which AOTAutograd does not currently know how to handle.', hints=[*graph_break_hints.SUPPORTABLE])
            elif name == 'data':
                if obj.source is None:
                    unimplemented_v2(gb_type='Failed to mutate tensor data attribute', context=f'setattr({obj}, {name}, {val})', explanation='Dyanmo only supports mutating `.data` of tensor created outside `torch.compile` region', hints=["Don't mutate `.data` on this tensor, or move the mutation out of `torch.compile` region"])
                elif obj.dtype != val.dtype:
                    unimplemented_v2(gb_type='Failed to mutate tensor data attribute to different dtype', context=f'setattr({obj}, {name}, {val})', explanation='Dyanmo only supports mutating `.data` of tensor to a new one with the same dtype', hints=["Don't mutate `.data` on this tensor, or move the mutation out of `torch.compile` region"])
                to_remove = [tf for tf in tx.output.tracked_fakes if tf.source == obj.source]
                for tf in to_remove:
                    tx.output.tracked_fakes.remove(tf)
                with dynamo_disable_grad(tx), torch.no_grad():
                    out = wrap_fx_proxy(tx, tx.output.create_proxy('call_function', torch.Tensor.set_, *proxy_args_kwargs([obj, val], {})))

                def _lower_version_count_by_1(x):
                    version = x._version
                    if version > 0:
                        version = version - 1
                    torch._C._autograd._unsafe_set_version_counter((x,), (version,))
                    return x
                tx.output.create_proxy('call_function', _lower_version_count_by_1, (out.as_proxy(),), {})
                _lower_version_count_by_1(obj.as_proxy().node.meta['example_value'])
                return out
            elif name in ('_grad', 'grad'):
                name = 'grad'
            elif is_tensor_getset_descriptor(name):
                unimplemented_v2(gb_type='Failed to set tensor attribute', context=f'setattr({obj}, {name}, {val})', explanation="Dyanmo doesn't support setting these tensor attributes", hints=[f"Don't mutate attribute '{name}' on tensors, or move the mutation out of `torch.compile` region"])
        tx.output.side_effects.store_attr(obj, name, val)
        return val
    elif isinstance(obj, variables.NNModuleVariable):
        if not tx.output.is_root_tracer():
            raise AttributeMutationError("Can't inplace modify module params/buffers inside HigherOrderOp")
        if name_var.is_python_constant() and isinstance(val, variables.TensorVariable):
            assigning_fake_val = get_fake_value(val.as_proxy().node, tx)
            try:
                getattr_var = obj.var_getattr(tx, name_var.as_python_constant())
            except (AttributeError, ObservedAttributeError):
                getattr_var = None
            if isinstance(getattr_var, variables.TensorVariable):
                existing_fake_attr = get_fake_value(getattr_var.as_proxy().node, tx)
                mod_setattr = inspect.getattr_static(obj.module_type, '__setattr__')
                if existing_fake_attr is assigning_fake_val and mod_setattr is torch.nn.Module.__setattr__:
                    return getattr_var
        obj.convert_to_unspecialized(tx)

def add_scripts(self, *files):
    """Add scripts to configuration.

        Add the sequence of files to the beginning of the scripts list.
        Scripts will be installed under the <prefix>/bin/ directory.

        """
    scripts = self.paths(files)
    dist = self.get_distribution()
    if dist is not None:
        if <MASK>:
            dist.scripts = []
        dist.scripts.extend(scripts)
    else:
        self.scripts.extend(scripts)

def operator_and_matrix(self, build_info, dtype, use_placeholder, ensure_self_adjoint_and_pd=False):
    shape = list(build_info.shape)
    if <MASK>:
        matrix = linear_operator_test_util.random_positive_definite_matrix(shape, dtype, force_well_conditioned=True)
    else:
        matrix = linear_operator_test_util.random_tril_matrix(shape, dtype, force_well_conditioned=True, remove_upper=True)
    lin_op_matrix = matrix
    if use_placeholder:
        lin_op_matrix = array_ops.placeholder_with_default(matrix, shape=None)
    if ensure_self_adjoint_and_pd:
        operator = LinearOperatorInversion(linalg.LinearOperatorFullMatrix(lin_op_matrix, is_positive_definite=True, is_self_adjoint=True))
    else:
        operator = LinearOperatorInversion(linalg.LinearOperatorLowerTriangular(lin_op_matrix))
    return (operator, linalg.inv(matrix))

def parse_log_file(file_path):
    with open(file_path) as f:
        logs = json.load(f)
    occurrence_count = {}
    benchmark_logs = {}
    for entry in logs:
        if 'invoke' in entry:
            shape = entry['invoke']
            if shape not in occurrence_count:
                occurrence_count[shape] = 0
            occurrence_count[shape] += 1
        else:
            for (shape, timings) in entry.items():
                if <MASK>:
                    benchmark_logs[shape] = []
                benchmark_logs[shape].extend(timings)
    return (occurrence_count, benchmark_logs)

def remove_kernel_local_buffers(self) -> None:
    """
        Any buffers that are both created and have a last use in the
        same kernel can be removed.

        Note that V.graph.scheduler can be None when codegening triton template
        kernels.
        """
    scheduler = V.graph.scheduler
    if not scheduler:
        return
    fused_node_names = OrderedSet((scheduler.name_to_buf[buf].defining_op_name() for buf in self.store_buffer_names if buf in scheduler.name_to_buf))
    names_to_remove: OrderedSet[str] = OrderedSet()
    for name in self.store_buffer_names:
        if name not in self.must_keep_buffers and name not in self.args.input_buffers and scheduler.can_buffer_be_removed_through_fusion(name, fused_node_names):
            self.num_store -= 1
            names_to_remove.add(name)
    for name in names_to_remove:
        if <MASK>:
            buf = self.args.inplace_buffers[name]
            if isinstance(buf, RemovedArg):
                continue
            remove = all((n in names_to_remove for n in buf.other_names))
            if remove:
                self.remove_inplace_buffer(name)
            self.inplaced_to_remove.add(name)
        else:
            self.remove_buffer(name)

