@staticmethod
def _convert_1d(values, unit, axis):

    def try_parse(values):
        try:
            return mdates.date2num(tools.to_datetime(values))
        except Exception:
            return values
    if isinstance(values, (datetime, pydt.date, np.datetime64, pydt.time)):
        return mdates.date2num(values)
    elif is_integer(values) or is_float(values):
        return values
    elif isinstance(values, str):
        return try_parse(values)
    elif isinstance(values, (list, tuple, np.ndarray, Index, Series)):
        if isinstance(values, Series):
            values = Index(values)
        if <MASK>:
            values = values.values
        if not isinstance(values, np.ndarray):
            values = com.asarray_tuplesafe(values)
        if is_integer_dtype(values) or is_float_dtype(values):
            return values
        try:
            values = tools.to_datetime(values)
        except Exception:
            pass
        values = mdates.date2num(values)
    return values

def check_bazel(filename: str, disallowed_checksums: set[str]) -> list[LintMessage]:
    original = ''
    replacement = ''
    with open(filename) as f:
        for line in f:
            original += f'{line}'
            m = SHA256_REGEX.match(line)
            if m:
                sha256 = m.group('sha256')
                if sha256 in disallowed_checksums:
                    continue
            replacement += f'{line}'
        if <MASK>:
            return []
        return [LintMessage(path=filename, line=None, char=None, code=LINTER_CODE, severity=LintSeverity.ADVICE, name='format', original=original, replacement=replacement, description='Found redundant SHA checksums. Run `lintrunner -a` to apply this patch.')]

def make_opaque_bitwise_fn(name, real_op_name):
    if name == 'bitwise_and':
        prec = PRECEDENCE['BitwiseAnd']
    elif name == 'bitwise_or':
        prec = PRECEDENCE['BitwiseOr']
    else:
        raise AssertionError(f'unrecognized {name}')

    class BitwiseFn(sympy.Function):
        _torch_handler_name = name
        precedence: int = prec
        _torch_unpickler = functools.partial(make_opaque_bitwise_fn, real_op_name=real_op_name)

        @classmethod
        def eval(cls, a, b):
            if <MASK>:
                return getattr(operator, real_op_name)(a, b)
            if a.is_Boolean:
                a = sympy.Integer(1 if a else 0)
            if b.is_Boolean:
                b = sympy.Integer(1 if b else 0)
            if isinstance(a, (sympy.Integer, int)) and isinstance(b, (sympy.Integer, int)):
                return sympy.Integer(getattr(operator, real_op_name)(int(a), int(b)))
            return None
    nm = 'BitwiseFn_' + name
    BitwiseFn.__name__ = nm
    BitwiseFn.__qualname__ = nm
    return BitwiseFn

