def is_nested(modality, structure):
    """Returns true if its input is a nested structure.

  For Modality.CORE refer to
  [tf.nest](https://www.tensorflow.org/api_docs/python/tf/nest)
  for the definition of a nested structure.

  Args:
    modality: enum value of supported modality [Modality.CORE or Modality.DATA]
    structure: the value to test.

  Returns:
    True if the input is a nested structure.
  """
    if modality == Modality.CORE:
        return _tf_core_is_nested(structure)
    elif <MASK>:
        return _tf_data_is_nested(structure)
    else:
        raise ValueError('Unknown modality used {} for nested structure'.format(modality))

def _post_order_apply_inner(module: nn.Module, module_name: str, parent_module: Optional[nn.Module]):
    for (child_module_name, child_module) in module.named_children():
        if child_module not in visited_modules:
            visited_modules.add(child_module)
            _post_order_apply_inner(child_module, child_module_name, module)
    optional_module = fn(module)
    if optional_module is not None:
        if not isinstance(parent_module, nn.Module):
            raise AssertionError(f'Non-root modules should have their parent module set but got {parent_module} for {module}')
        if <MASK>:
            raise AssertionError(f'Non-root modules should have their module name set but got an empty module name for {module}')
        if not isinstance(optional_module, nn.Module):
            raise AssertionError(f'fn should return None or an nn.Module but got {optional_module}')
        setattr(parent_module, module_name, optional_module)

def generate_libtorch_matrix(os: str, release_type: str, arches: Optional[list[str]]=None, libtorch_variants: Optional[list[str]]=None) -> list[dict[str, str]]:
    if arches is None:
        arches = ['cpu']
        if os == 'linux':
            arches += CUDA_ARCHES
            arches += ROCM_ARCHES
        elif os == 'windows':
            windows_cuda_arches = CUDA_ARCHES.copy()
            windows_cuda_arches.remove('12.9')
            arches += windows_cuda_arches
    if libtorch_variants is None:
        libtorch_variants = ['shared-with-deps', 'shared-without-deps', 'static-with-deps', 'static-without-deps']
    ret: list[dict[str, str]] = []
    for arch_version in arches:
        for libtorch_variant in libtorch_variants:
            gpu_arch_type = arch_type(arch_version)
            gpu_arch_version = '' if arch_version == 'cpu' else arch_version
            if <MASK>:
                continue
            ret.append({'gpu_arch_type': gpu_arch_type, 'gpu_arch_version': gpu_arch_version, 'desired_cuda': translate_desired_cuda(gpu_arch_type, gpu_arch_version), 'libtorch_config': release_type, 'libtorch_variant': libtorch_variant, 'container_image': LIBTORCH_CONTAINER_IMAGES[arch_version].split(':')[0] if os not in ('windows', 'windows-arm64') else '', 'container_image_tag_prefix': LIBTORCH_CONTAINER_IMAGES[arch_version].split(':')[1] if os not in ('windows', 'windows-arm64') else '', 'package_type': 'libtorch', 'build_name': f'libtorch-{gpu_arch_type}{gpu_arch_version}-{libtorch_variant}-{release_type}'.replace('.', '_')})
    return ret

def maybe_downcast_numeric(result: ArrayLike, dtype: DtypeObj, do_round: bool=False) -> ArrayLike:
    """
    Subset of maybe_downcast_to_dtype restricted to numeric dtypes.

    Parameters
    ----------
    result : ndarray or ExtensionArray
    dtype : np.dtype or ExtensionDtype
    do_round : bool

    Returns
    -------
    ndarray or ExtensionArray
    """
    if not isinstance(dtype, np.dtype) or not isinstance(result.dtype, np.dtype):
        return result

    def trans(x):
        if do_round:
            return x.round()
        return x
    if dtype.kind == result.dtype.kind:
        if result.dtype.itemsize <= dtype.itemsize and result.size:
            return result
    if <MASK>:
        if not result.size:
            return trans(result).astype(dtype)
        if isinstance(result, np.ndarray):
            element = result.item(0)
        else:
            element = result.iloc[0]
        if not isinstance(element, (np.integer, np.floating, int, float, bool)):
            return result
        if issubclass(result.dtype.type, (np.object_, np.number)) and notna(result).all():
            new_result = trans(result).astype(dtype)
            if new_result.dtype.kind == 'O' or result.dtype.kind == 'O':
                if (new_result == result).all():
                    return new_result
            elif np.allclose(new_result, result, rtol=0):
                return new_result
    elif issubclass(dtype.type, np.floating) and result.dtype.kind != 'b' and (not is_string_dtype(result.dtype)):
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'overflow encountered in cast', RuntimeWarning)
            new_result = result.astype(dtype)
        size_tols = {4: 0.0005, 8: 5e-08, 16: 5e-16}
        atol = size_tols.get(new_result.dtype.itemsize, 0.0)
        if np.allclose(new_result, result, equal_nan=True, rtol=0.0, atol=atol):
            return new_result
    elif dtype.kind == result.dtype.kind == 'c':
        new_result = result.astype(dtype)
        if np.array_equal(new_result, result, equal_nan=True):
            return new_result
    return result

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName, remove_non_owning_ref_types: bool=False, symint: bool=False) -> NamedCType:
    r = valuetype_type(t, binds=binds, mutable=mutable, symint=symint)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            if mutable and (not local.use_const_ref_for_mutable_tensors()):
                return NamedCType(binds, MutRefCType(BaseCType(tensorT)))
            else:
                return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if str(t.elem) == 'Tensor':
            if mutable and (not local.use_const_ref_for_mutable_tensors()):
                return NamedCType(binds, MutRefCType(BaseCType(tensorT)))
            else:
                return NamedCType(binds, ConstRefCType(OptionalCType(BaseCType(tensorT))))
        elif str(t.elem) == 'Scalar':
            return NamedCType(binds, ConstRefCType(OptionalCType(BaseCType(scalarT))))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'SymInt':
            if symint:
                return NamedCType(binds, BaseCType(optionalSymIntArrayRefT))
            else:
                return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds, symint=symint)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if str(t.elem) == 'int':
            if remove_non_owning_ref_types:
                return NamedCType(binds, VectorCType(BaseCType(longT)))
            else:
                return NamedCType(binds, BaseCType(intArrayRefT))
        if str(t.elem) == 'SymInt':
            if remove_non_owning_ref_types:
                if symint:
                    return NamedCType(binds, VectorCType(BaseCType(SymIntT)))
                else:
                    return NamedCType(binds, VectorCType(BaseCType(longT)))
            elif symint:
                return NamedCType(binds, BaseCType(symIntArrayRefT))
            else:
                return NamedCType(binds, BaseCType(intArrayRefT))
        if str(t.elem) == 'Tensor':
            if <MASK>:
                return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
            else:
                return NamedCType(binds, BaseCType(tensorListT))
        elif str(t.elem) == 'Scalar':
            return NamedCType(binds, ArrayRefCType(BaseCType(scalarT)))
        elif str(t.elem) == 'Dimname':
            return NamedCType(binds, BaseCType(dimnameListT))
        elif str(t.elem) == 'Tensor?':
            return NamedCType(binds, ConstRefCType(ListCType(OptionalCType(BaseCType(tensorT)))))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds, symint=symint)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

def check_dependency(self, operation, dependency):
    """
        Return True if the given operation depends on the given dependency,
        False otherwise.
        """
    if dependency.field_name is None and dependency.type == OperationDependency.Type.CREATE:
        return isinstance(operation, operations.CreateModel) and operation.name_lower == dependency.model_name_lower
    elif dependency.field_name is not None and dependency.type == OperationDependency.Type.CREATE:
        return isinstance(operation, operations.CreateModel) and operation.name_lower == dependency.model_name_lower and any((dependency.field_name == x for (x, y) in operation.fields)) or (isinstance(operation, operations.AddField) and operation.model_name_lower == dependency.model_name_lower and (operation.name_lower == dependency.field_name_lower))
    elif dependency.field_name is not None and dependency.type == OperationDependency.Type.REMOVE:
        return isinstance(operation, operations.RemoveField) and operation.model_name_lower == dependency.model_name_lower and (operation.name_lower == dependency.field_name_lower)
    elif dependency.field_name is None and dependency.type == OperationDependency.Type.REMOVE:
        return isinstance(operation, operations.DeleteModel) and operation.name_lower == dependency.model_name_lower
    elif dependency.field_name is not None and dependency.type == OperationDependency.Type.ALTER:
        return isinstance(operation, operations.AlterField) and operation.model_name_lower == dependency.model_name_lower and (operation.name_lower == dependency.field_name_lower)
    elif dependency.field_name is not None and dependency.type == OperationDependency.Type.REMOVE_ORDER_WRT:
        return isinstance(operation, operations.AlterOrderWithRespectTo) and operation.name_lower == dependency.model_name_lower and ((operation.order_with_respect_to or '').lower() != dependency.field_name_lower)
    elif dependency.field_name is not None and dependency.type == OperationDependency.Type.ALTER_FOO_TOGETHER:
        return isinstance(operation, (operations.AlterUniqueTogether, operations.AlterIndexTogether)) and operation.name_lower == dependency.model_name_lower
    elif <MASK>:
        return isinstance(operation, (operations.RemoveIndex, operations.RemoveConstraint)) and operation.model_name_lower == dependency.model_name_lower
    else:
        raise ValueError("Can't handle dependency %r" % (dependency,))

def _fit_transform_in_place(self, K):
    """Fit's using kernel K"""
    K = self._centerer.fit(K).transform(K, copy=False)
    if self.n_components is None:
        n_components = K.shape[0]
    else:
        n_components = min(K.shape[0], self.n_components)
    if <MASK>:
        if K.shape[0] > 200 and n_components < 10:
            eigen_solver = 'arpack'
        else:
            eigen_solver = 'dense'
    else:
        eigen_solver = self.eigen_solver
    if eigen_solver == 'dense':
        (self.eigenvalues_, self.eigenvectors_) = eigh(K, subset_by_index=(K.shape[0] - n_components, K.shape[0] - 1))
    elif eigen_solver == 'arpack':
        v0 = _init_arpack_v0(K.shape[0], self.random_state)
        (self.eigenvalues_, self.eigenvectors_) = eigsh(K, n_components, which='LA', tol=self.tol, maxiter=self.max_iter, v0=v0)
    elif eigen_solver == 'randomized':
        (self.eigenvalues_, self.eigenvectors_) = _randomized_eigsh(K, n_components=n_components, n_iter=self.iterated_power, random_state=self.random_state, selection='module')
    self.eigenvalues_ = _check_psd_eigenvalues(self.eigenvalues_, enable_warnings=False)
    (self.eigenvectors_, _) = svd_flip(u=self.eigenvectors_, v=None)
    indices = self.eigenvalues_.argsort()[::-1]
    self.eigenvalues_ = self.eigenvalues_[indices]
    self.eigenvectors_ = self.eigenvectors_[:, indices]
    if self.remove_zero_eig or self.n_components is None:
        self.eigenvectors_ = self.eigenvectors_[:, self.eigenvalues_ > 0]
        self.eigenvalues_ = self.eigenvalues_[self.eigenvalues_ > 0]
    return K

def _resolve_name_collision(mod: GraphModule, gm: GraphModule) -> None:
    """
    In aot_export_module (make_fx), we create get_attr nodes with name prefix
    "_tensor_constant" and "_torchbind_obj". See Tracer.create_arg() in
    torch/fx/_symbolic_trace.py

    However, this might result in name collision if the original mod already
    has a different buffer with the same name.

    We resolve this potential name collision here by changing the target name
    with a new number post fix.
    """
    existing_keys = OrderedSet([name for (name, val) in mod.named_parameters(remove_duplicate=False)])
    existing_keys.update(OrderedSet([name for (name, val) in mod.named_buffers(remove_duplicate=False)]))

    def find_smallest_i(graph: fx.Graph, prefix: str) -> int:
        i = 0
        for node in graph.nodes:
            if node.op == 'get_attr' and node.target.startswith(prefix):
                if <MASK>:
                    post_fix = node.target.split(prefix)[-1]
                    if post_fix.isdigit():
                        i = max(i, int(post_fix))
        for key in existing_keys:
            if key.startswith(prefix):
                if len(key) > len(prefix):
                    post_fix = key.split(prefix)[-1]
                    if post_fix.isdigit():
                        i = max(i, int(post_fix))
        return i + 1
    for node in gm.graph.nodes:
        if node.op == 'get_attr':
            target_name = node.target
            if not target_name.startswith('_tensor_constant') and (not target_name.startswith('_torchbind_obj')):
                continue
            if not hasattr(mod, target_name):
                continue
            gm_target = attrgetter(target_name)(gm)
            model_target = attrgetter(target_name)(mod)
            if isinstance(gm_target, FakeScriptObject):
                if isinstance(model_target, FakeScriptObject) and gm_target.real_obj is model_target.real_obj:
                    continue
            elif gm_target.device == model_target.device and gm_target.dtype == model_target.dtype and torch.equal(gm_target, model_target):
                continue
            prefix = '_tensor_constant' if target_name.startswith('_tensor_constant') else '_torchbind_obj'
            new_id = find_smallest_i(gm.graph, prefix)
            new_target_name = f'{prefix}{new_id}'
            node.target = new_target_name
            setattr(gm, new_target_name, gm_target)
            existing_keys.add(new_target_name)

def _gather_constant_attrs(m: torch.nn.Module) -> ConstantAttrMap:
    """Search the module hierarchy, gathering up all tensor and ScriptObject constants.

    Returns a dictionary mapping hash(value) to the name of the constant. We
    have to abuse `hash` here unfortunately, see: [ScriptObject hash].
    """
    constants = ConstantAttrMap()
    buffers_parameters = set(m.buffers())
    buffers_parameters.update(m.parameters())

    def inner(m: torch.nn.Module, prefix_atoms: list[str], constants):
        for (k, v) in m.__dict__.items():
            if <MASK>:
                if v in buffers_parameters:
                    continue
                fqn = '.'.join(prefix_atoms + [k])
                constants.add(v, fqn)
        for (k, v) in m.named_children():
            inner(v, prefix_atoms + [k], constants)
    inner(m, [], constants)
    return constants

def batchable_from_tensor_list(spec, tensor_list):
    """Returns a value with type `spec` decoded from `tensor_list`."""
    if isinstance(spec, internal.TensorSpec):
        assert len(tensor_list) == 1
        return tensor_list[0]
    elif <MASK>:
        encoded_specs = spec.__batch_encoder__.encoding_specs(spec)
        flat_specs = nest.map_structure(get_batchable_flat_tensor_specs, encoded_specs)
        encoded_flats = nest.pack_sequence_as(flat_specs, tensor_list)
        encoded_value = nest.map_structure_up_to(encoded_specs, batchable_from_tensor_list, encoded_specs, encoded_flats)
        return spec.__batch_encoder__.decode(spec, encoded_value)
    else:
        return spec._from_compatible_tensor_list(tensor_list)

def BUILTIN_MATCH(self, guard: Guard) -> None:
    if self.save_guards:
        if <MASK>:
            self.check_fn_manager.used_builtin_vars.add(guard.originating_source.index)
        return self.id_match_unchecked(guard)
    return self.ID_MATCH(guard)

def quantized_args(*arg_q_descriptors: bool, scale: float | None=None, zero_point: int | None=None, quantize_output: bool=True) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:
    """A decorator which extends support for quantized version of the base operator.

    Quantization is detected by examining the arguments that are annotated by
    `arg_q_descriptors`.

    If quantization is detected, the base operator symbolic function will be wrapped with
    argument de-quantization and output quantization.

    Otherwise, only the base symbolic function will be invoked.

    For example:

    ```
    @quantized_args(True, False)
    def foo(g, x, y):
        return x + y
    ```

    is equivalent to

    ```
    def q_foo(g, x, y):
        if is_quantized_tensor(x):
            x = dequantize(x)
            out = foo(g, x, y)
            return quantize(out)
        else:
            return foo(g, x, y)
    ```

    Args:
        arg_q_descriptors: A sequence of bool, where each element represents if the
          argument is QTensor for quantized version of this operator. It defaults
          to False for unspecified (variable length) arguments.
        scale: Quantized output scale. If None, derive from
          the first quantized input scale.
        zero_point: Quantized output zero point. If None,
          derive from the first quantized input zero point.
        quantize_output: If True, quantize the output of the base operator. Default is True
    """

    def decorator(fn):

        @functools.wraps(fn)
        def wrapper(g, *args, **kwargs):
            nonlocal scale
            nonlocal zero_point
            if scale is not None:
                _scale = g.op('Constant', value_t=torch.tensor(scale))
            else:
                _scale = None
            if zero_point is not None:
                _zero_point = g.op('Constant', value_t=torch.tensor(zero_point))
            else:
                _zero_point = None
            arg_q_descriptors_extended = arg_q_descriptors + (False,) * (len(args) - len(arg_q_descriptors))
            descriptor_args = tuple(zip(arg_q_descriptors_extended, args))

            def _is_arg_quantized(descriptor, arg):
                return descriptor and _is_value(arg) and _is_tuple_construct(arg)
            is_quantized: list[bool] = []
            for (descriptor, arg) in descriptor_args:
                if _is_packed_list(arg):
                    is_quantized.extend((_is_arg_quantized(descriptor, arg_input) for arg_input in arg.node().inputs()))
                else:
                    is_quantized.append(_is_arg_quantized(descriptor, arg))
            if not any(is_quantized):
                return fn(g, *args, **kwargs)
            non_quantized_args = []
            for (descriptor, arg) in descriptor_args:
                if _is_arg_quantized(descriptor, arg):
                    (dequantized_arg, arg_scale, arg_zero_point, _) = dequantize_helper(g, arg)
                    non_quantized_args.append(dequantized_arg)
                    if _scale is None:
                        _scale = arg_scale
                    if <MASK>:
                        _zero_point = arg_zero_point
                elif _is_packed_list(arg):
                    for arg_input in arg.node().inputs():
                        if _is_arg_quantized(descriptor, arg_input):
                            (dequantized_arg, arg_scale, arg_zero_point, _) = dequantize_helper(g, arg_input)
                            if _scale is None:
                                _scale = arg_scale
                            if _zero_point is None:
                                _zero_point = arg_zero_point
                            arg_input.replaceAllUsesWith(dequantized_arg)
                    non_quantized_args.append(arg)
                else:
                    non_quantized_args.append(arg)
            output = fn(g, *non_quantized_args, **kwargs)
            assert _scale is not None, 'Bug: Scale must be set for quantized operator'
            assert _zero_point is not None, 'Bug: Zero point must be set for quantized operator'
            if quantize_output:
                return quantize_helper(g, output, _scale, _zero_point)
            return output
        return wrapper
    return decorator

def setup_output_hook(self, args):

    def fn(grad_fn):

        def hook(_, grad_output):
            self.grad_outputs = self._pack_with_none(self.output_tensors_index, grad_output, self.n_outputs)
            if self.user_pre_hooks:
                expected_len = len(self.grad_outputs)
                for user_pre_hook in self.user_pre_hooks:
                    hook_grad_outputs = user_pre_hook(self.module, self.grad_outputs)
                    if hook_grad_outputs is None:
                        continue
                    actual_len = len(hook_grad_outputs)
                    if <MASK>:
                        raise RuntimeError(f'Backward pre hook returned an invalid number of grad_output, got {actual_len}, but expected {expected_len}')
                    self.grad_outputs = hook_grad_outputs
            local_grad_outputs = self.grad_outputs
            if self.input_tensors_index is None:
                warnings.warn('Full backward hook is firing when gradients are computed with respect to module outputs since no inputs require gradients. See https://docs.pytorch.org/docs/main/generated/torch.nn.Module.html#torch.nn.Module.register_full_backward_hook for more details.', stacklevel=5)
                grad_inputs = self._pack_with_none([], [], self.n_inputs)
                for user_hook in self.user_hooks:
                    res = user_hook(self.module, grad_inputs, self.grad_outputs)
                    if res is not None and (not (isinstance(res, tuple) and all((el is None for el in res)))):
                        raise RuntimeError('Backward hook for Modules where no input requires gradient should always return None or None for all gradients.')
                self.grad_outputs = None
            if local_grad_outputs is not None:
                assert self.output_tensors_index is not None
                return tuple((local_grad_outputs[i] for i in self.output_tensors_index))
        grad_fn.register_hook(hook)
    is_tuple = True
    if not isinstance(args, tuple):
        args = (args,)
        is_tuple = False
    (res, output_idx) = self._apply_on_tensors(fn, args)
    self.n_outputs = len(args)
    self.output_tensors_index = output_idx
    if not is_tuple:
        res = res[0]
    return res

def _update(self, values, returning_fields=None):
    """
        A version of update() that accepts field objects instead of field
        names. Used primarily for model saving and not intended for use by
        general code (it requires too much poking around at model internals to
        be useful at that level).
        """
    if self.query.is_sliced:
        raise TypeError('Cannot update a query once a slice has been taken.')
    query = self.query.chain(sql.UpdateQuery)
    query.add_update_fields(values)
    query.annotations = {}
    self._result_cache = None
    if <MASK>:
        return query.get_compiler(self.db).execute_sql(ROW_COUNT)
    return query.get_compiler(self.db).execute_returning_sql(returning_fields)

@classmethod
def _validate_dtype(cls, dtype: Dtype | None) -> None:
    if <MASK>:
        return
    (validation_func, expected) = cls._dtype_validation_metadata
    if not validation_func(dtype):
        raise ValueError(f'Incorrect `dtype` passed: expected {expected}, received {dtype}')

def validate(self, model, instance, exclude=None, using=DEFAULT_DB_ALIAS):
    queryset = model._default_manager.using(using)
    if self.fields:
        lookup_kwargs = {}
        generated_field_names = []
        for field_name in self.fields:
            if exclude and field_name in exclude:
                return
            field = model._meta.get_field(field_name)
            if field.generated:
                if exclude and self._expression_refs_exclude(model, field.expression, exclude):
                    return
                generated_field_names.append(field.name)
            else:
                lookup_value = getattr(instance, field.attname)
                if self.nulls_distinct is not False and lookup_value is None or (lookup_value == '' and connections[using].features.interprets_empty_strings_as_nulls):
                    return
                lookup_kwargs[field.name] = lookup_value
        lookup_args = []
        if generated_field_names:
            field_expression_map = instance._get_field_expression_map(meta=model._meta, exclude=exclude)
            for field_name in generated_field_names:
                expression = field_expression_map[field_name]
                if self.nulls_distinct is False:
                    lhs = F(field_name)
                    condition = Q(Exact(lhs, expression)) | Q(IsNull(lhs, True), IsNull(expression, True))
                    lookup_args.append(condition)
                else:
                    lookup_kwargs[field_name] = expression
        queryset = queryset.filter(*lookup_args, **lookup_kwargs)
    else:
        if exclude and any((self._expression_refs_exclude(model, expression, exclude) for expression in self.expressions)):
            return
        replacements = {F(field): value for (field, value) in instance._get_field_expression_map(meta=model._meta, exclude=exclude).items()}
        filters = []
        for expr in self.expressions:
            if hasattr(expr, 'get_expression_for_validation'):
                expr = expr.get_expression_for_validation()
            rhs = expr.replace_expressions(replacements)
            condition = Exact(expr, rhs)
            if self.nulls_distinct is False:
                condition = Q(condition) | Q(IsNull(expr, True), IsNull(rhs, True))
            filters.append(condition)
        queryset = queryset.filter(*filters)
    model_class_pk = instance._get_pk_val(model._meta)
    if not instance._state.adding and instance._is_pk_set(model._meta):
        queryset = queryset.exclude(pk=model_class_pk)
    if not self.condition:
        if queryset.exists():
            if self.fields and self.violation_error_message == self.default_violation_error_message:
                validation_error_message = instance.unique_error_message(model, self.fields)
                raise ValidationError(validation_error_message, code=validation_error_message.code)
