            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)

def sym_sum(args):
    """
    N-ary add which is faster to compute for long lists than iterated binary
    addition.  Only does something special for integers.
    """
    if overrides.has_torch_function(args):
        return overrides.handle_torch_function(sym_sum, args, args)
    found = None
    for a in args:
        if not isinstance(a, (SymInt, builtins.int)):
            return builtins.sum(args)
        if isinstance(a, SymInt):
            found = a.node
    if <MASK>:
        return builtins.sum(args)
    from torch.fx.experimental.sym_node import to_node, wrap_node
    return wrap_node(found.sym_sum(tuple((to_node(found, a) for a in args))))

def generate_altered_fields(self):
    """
        Make AlterField operations, or possibly RemovedField/AddField if alter
        isn't possible.
        """
    for (app_label, model_name, field_name) in sorted(self.old_field_keys & self.new_field_keys):
        old_model_name = self.renamed_models.get((app_label, model_name), model_name)
        old_field_name = self.renamed_fields.get((app_label, model_name, field_name), field_name)
        old_field = self.from_state.models[app_label, old_model_name].get_field(old_field_name)
        new_field = self.to_state.models[app_label, model_name].get_field(field_name)
        dependencies = []
        if hasattr(new_field, 'remote_field') and getattr(new_field.remote_field, 'model', None):
            rename_key = resolve_relation(new_field.remote_field.model, app_label, model_name)
            if rename_key in self.renamed_models:
                new_field.remote_field.model = old_field.remote_field.model
            remote_field_name = getattr(new_field.remote_field, 'field_name', None)
            if remote_field_name:
                to_field_rename_key = (*rename_key, remote_field_name)
                if to_field_rename_key in self.renamed_fields:
                    new_field.remote_field.model = old_field.remote_field.model
                    new_field.remote_field.field_name = old_field.remote_field.field_name
            from_fields = getattr(new_field, 'from_fields', None)
            if from_fields:
                from_rename_key = (app_label, model_name)
                new_field.from_fields = tuple([self.renamed_fields.get((*from_rename_key, from_field), from_field) for from_field in from_fields])
                new_field.to_fields = tuple([self.renamed_fields.get((*rename_key, to_field), to_field) for to_field in new_field.to_fields])
                if (old_from_fields := getattr(old_field, 'from_fields', None)):
                    old_field.from_fields = tuple(old_from_fields)
                    old_field.to_fields = tuple(old_field.to_fields)
            dependencies.extend(self._get_dependencies_for_foreign_key(app_label, model_name, new_field, self.to_state))
        if hasattr(new_field, 'remote_field') and getattr(new_field.remote_field, 'through', None):
            rename_key = resolve_relation(new_field.remote_field.through, app_label, model_name)
            if rename_key in self.renamed_models:
                new_field.remote_field.through = old_field.remote_field.through
        old_field_dec = self.deep_deconstruct(old_field)
        new_field_dec = self.deep_deconstruct(new_field)
        if old_field_dec != new_field_dec and old_field_name == field_name:
            both_m2m = old_field.many_to_many and new_field.many_to_many
            neither_m2m = not old_field.many_to_many and (not new_field.many_to_many)
            if <MASK>:
                preserve_default = True
                if old_field.null and (not new_field.null) and (not new_field.has_default()) and (not new_field.has_db_default()) and (not new_field.many_to_many):
                    field = new_field.clone()
                    new_default = self.questioner.ask_not_null_alteration(field_name, model_name)
                    if new_default is not models.NOT_PROVIDED:
                        field.default = new_default
                        preserve_default = False
                else:
                    field = new_field
                self.add_operation(app_label, operations.AlterField(model_name=model_name, name=field_name, field=field, preserve_default=preserve_default), dependencies=dependencies)
            else:
                self._generate_removed_field(app_label, model_name, field_name)
                self._generate_added_field(app_label, model_name, field_name)

def unbind_reference(op, sample, wrap_output_as_njt=True):
    nt_inp = sample.input if sample.input.is_nested else next((a for a in sample.args if a.is_nested))
    out_ref_components = []
    for i in range(nt_inp.shape[0]):

        def _slice_input(t, i=i, inp=nt_inp):
            if isinstance(t, torch.Tensor) and _raggedness_matches(t, inp):
                return t[i]
            elif isinstance(t, torch.Tensor) and hasattr(t, '_batch_dim'):
                bdim = t._batch_dim
                if <MASK>:
                    return t[0]
                else:
                    return t.select(bdim, i)
            else:
                return t
        inp = _slice_input(sample.input)
        args = tree_map(_slice_input, sample.args)
        kwargs = tree_map(_slice_input, sample.kwargs)
        if 'index_put' in op.full_name and 'indices' in kwargs:
            if len(kwargs['indices']) > 1:
                kwargs['indices'] = [t[i] for t in kwargs['indices'][1:]]
            else:
                sequence_put = kwargs['indices'][0].tolist()
                if i in sequence_put:
                    kwargs['indices'] = [torch.tensor(list(range(inp.shape[0])), dtype=torch.int32, device=kwargs['indices'][0].device)]
                else:
                    kwargs['indices'] = [torch.tensor([], dtype=torch.int32, device=kwargs['indices'][0].device)]
        from torch.nested._internal.ops import _outer_to_inner_dim
        if op._extra_op_data.dim_args is not None:
            argnames = tree_map(lambda a: a.replace('...', ''), tree_flatten(op._extra_op_data.dim_args)[0])
            for argname in {a for a in argnames if a in kwargs}:
                ndim = nt_inp._ndim if hasattr(nt_inp, '_ndim') else nt_inp.dim()
                kwargs[argname] = _outer_to_inner_dim(ndim, kwargs[argname], nt_inp._ragged_idx, canonicalize=True)
        out_ref_component = op.op(inp, *args, **kwargs)
        out_ref_components.append(out_ref_component)
    if wrap_output_as_njt:
        if len(out_ref_components) > 0 and isinstance(out_ref_components[0], (list, tuple)):
            num_returns = len(out_ref_components[0])
            assert all((len(o) == num_returns for o in out_ref_components))
            njt_returns = [torch.nested.as_nested_tensor([o[r] for o in out_ref_components], layout=torch.jagged) for r in range(num_returns)]
            return type(out_ref_components[0])(njt_returns)
        return torch.nested.as_nested_tensor(out_ref_components, layout=torch.jagged)
    return out_ref_components

@contextlib.contextmanager
def _truncate_execution_to_epoch(self):
    """Truncates steps per execution to at most one epoch."""
    should_truncate = self._inferred_steps is not None and self._steps_per_execution_value > self._inferred_steps
    original_value = self._steps_per_execution_value
    try:
        if <MASK>:
            self._steps_per_execution.assign(self._inferred_steps)
            self._steps_per_execution_value = self._inferred_steps
        yield
    finally:
        if should_truncate:
            self._steps_per_execution.assign(original_value)
            self._steps_per_execution_value = original_value

@classmethod
def create(cls, entry):
    """
        Factory that creates an app config from an entry in INSTALLED_APPS.
        """
    app_config_class = None
    app_name = None
    app_module = None
    try:
        app_module = import_module(entry)
    except Exception:
        pass
    else:
        if module_has_submodule(app_module, APPS_MODULE_NAME):
            mod_path = '%s.%s' % (entry, APPS_MODULE_NAME)
            mod = import_module(mod_path)
            app_configs = [(name, candidate) for (name, candidate) in inspect.getmembers(mod, inspect.isclass) if issubclass(candidate, cls) and candidate is not cls and getattr(candidate, 'default', True)]
            if len(app_configs) == 1:
                app_config_class = app_configs[0][1]
            else:
                app_configs = [(name, candidate) for (name, candidate) in app_configs if getattr(candidate, 'default', False)]
                if len(app_configs) > 1:
                    candidates = [repr(name) for (name, _) in app_configs]
                    raise RuntimeError('%r declares more than one default AppConfig: %s.' % (mod_path, ', '.join(candidates)))
                elif len(app_configs) == 1:
                    app_config_class = app_configs[0][1]
        if <MASK>:
            app_config_class = cls
            app_name = entry
    if app_config_class is None:
        try:
            app_config_class = import_string(entry)
        except Exception:
            pass
    if app_module is None and app_config_class is None:
        (mod_path, _, cls_name) = entry.rpartition('.')
        if mod_path and cls_name[0].isupper():
            mod = import_module(mod_path)
            candidates = [repr(name) for (name, candidate) in inspect.getmembers(mod, inspect.isclass) if issubclass(candidate, cls) and candidate is not cls]
            msg = "Module '%s' does not contain a '%s' class." % (mod_path, cls_name)
            if candidates:
                msg += ' Choices are: %s.' % ', '.join(candidates)
            raise ImportError(msg)
        else:
            import_module(entry)
    if not issubclass(app_config_class, AppConfig):
        raise ImproperlyConfigured("'%s' isn't a subclass of AppConfig." % entry)
    if app_name is None:
        try:
            app_name = app_config_class.name
        except AttributeError:
            raise ImproperlyConfigured("'%s' must supply a name attribute." % entry)
    try:
        app_module = import_module(app_name)
    except ImportError:
        raise ImproperlyConfigured("Cannot import '%s'. Check that '%s.%s.name' is correct." % (app_name, app_config_class.__module__, app_config_class.__qualname__))
    return app_config_class(app_name, app_module)

@register_lowering(aten.div, broadcast=True)
def div_mode(a, b, rounding_mode=None):
    both_integer = is_integer_type(a) and is_integer_type(b)
    both_boolean = is_boolean_type(a) and is_boolean_type(b)
    if <MASK>:
        assert not both_boolean, 'floordiv operands can not be boolean at the same time'
        return floordiv(a, b) if both_integer else floor(div(a, b))
    if rounding_mode == 'trunc':
        assert not both_boolean, 'truncdiv operands can not be boolean at the same time'
        return truncdiv(a, b) if both_integer else trunc(div(a, b))
    return div(a, b)

