def _exponential_space_einsum_v1(equation, *inputs):
    """Fallback implementation that supports summing an index over > 2 inputs."""
    inputs = list(inputs)
    input_shapes = [x.shape for x in inputs]
    (idx_in, idx_out) = _einsum_v1_parse_and_resolve_equation(equation, input_shapes)
    idx_all = set(''.join(idx_in) + idx_out)
    indices = ''.join(sorted(idx_all))
    missing_idx = set(idx_out).difference(idx_all)
    if missing_idx:
        raise ValueError(f'Unknown output axes: {missing_idx}.')
    axis_order = {}
    for ax in indices:
        if ax not in idx_out:
            axis_order[ax] = len(axis_order)
    for ax in idx_out:
        axis_order[ax] = len(axis_order)
    for (i, (input_, axes_)) in enumerate(zip(inputs, idx_in)):
        if input_.shape.ndims != len(axes_):
            raise ValueError(f'Input {i} with axes {axes_} has incorrect number of dimensions (expected {len(axes_)}, got {input_.shape.ndims}).')
        sorted_idx = sorted(axes_, key=axis_order.get)
        if len(set(axes_)) != len(axes_):
            raise ValueError(f'Subscript not supported: an axis appears more than once: {axes_}.')
        if list(axes_) != sorted_idx:
            permuted = [axes_.find(ax) for ax in sorted_idx]
            inputs[i] = array_ops.transpose(input_, permuted)
            idx_in[i] = sorted_idx
    reduction_idx = []
    shapes = [[dim if dim else -1 for dim in tensor.shape.as_list()] for tensor in inputs]
    for (j, ax) in enumerate(sorted(idx_all, key=axis_order.get)):
        dims = []
        for (i, idx) in enumerate(idx_in):
            if ax not in idx:
                shapes[i].insert(j, 1)
            else:
                dim = shapes[i][j]
                if <MASK>:
                    dims.append(dim)
        if len(set(dims)) > 1:
            raise ValueError(f'Dimension mismatch on axis: {ax}. Found {len(set(dims))}, expected 1.')
        if ax not in idx_out:
            reduction_idx.append(j)
    expanded_inputs = [array_ops.reshape(input_, shape) for (input_, shape) in zip(inputs, shapes)]
    expanded_output = 1
    for input_ in expanded_inputs:
        expanded_output *= input_
    return math_ops.reduce_sum(expanded_output, reduction_idx)

def build_all_signature_defs(receiver_tensors, export_outputs, receiver_tensors_alternatives=None, serving_only=True):
    """Build `SignatureDef`s for all export outputs.

  Args:
    receiver_tensors: a `Tensor`, or a dict of string to `Tensor`, specifying
      input nodes where this receiver expects to be fed by default.  Typically,
      this is a single placeholder expecting serialized `tf.Example` protos.
    export_outputs: a dict of ExportOutput instances, each of which has
      an as_signature_def instance method that will be called to retrieve
      the signature_def for all export output tensors.
    receiver_tensors_alternatives: a dict of string to additional
      groups of receiver tensors, each of which may be a `Tensor` or a dict of
      string to `Tensor`.  These named receiver tensor alternatives generate
      additional serving signatures, which may be used to feed inputs at
      different points within the input receiver subgraph.  A typical usage is
      to allow feeding raw feature `Tensor`s *downstream* of the
      tf.io.parse_example() op.  Defaults to None.
    serving_only: boolean; if true, resulting signature defs will only include
      valid serving signatures. If false, all requested signatures will be
      returned.

  Returns:
    signature_def representing all passed args.

  Raises:
    ValueError: if export_outputs is not a dict
  """
    if not isinstance(receiver_tensors, dict):
        receiver_tensors = {SINGLE_RECEIVER_DEFAULT_NAME: receiver_tensors}
    if export_outputs is None or not isinstance(export_outputs, dict):
        raise ValueError('export_outputs must be a dict and not{}'.format(type(export_outputs)))
    signature_def_map = {}
    excluded_signatures = {}
    for (output_key, export_output) in export_outputs.items():
        signature_name = '{}'.format(output_key or 'None')
        try:
            signature = export_output.as_signature_def(receiver_tensors)
            signature_def_map[signature_name] = signature
        except ValueError as e:
            excluded_signatures[signature_name] = str(e)
    if receiver_tensors_alternatives:
        for (receiver_name, receiver_tensors_alt) in receiver_tensors_alternatives.items():
            if not isinstance(receiver_tensors_alt, dict):
                receiver_tensors_alt = {SINGLE_RECEIVER_DEFAULT_NAME: receiver_tensors_alt}
            for (output_key, export_output) in export_outputs.items():
                signature_name = '{}:{}'.format(receiver_name or 'None', output_key or 'None')
                try:
                    signature = export_output.as_signature_def(receiver_tensors_alt)
                    signature_def_map[signature_name] = signature
                except ValueError as e:
                    excluded_signatures[signature_name] = str(e)
    _log_signature_report(signature_def_map, excluded_signatures)
    if <MASK>:
        signature_def_map = {k: v for (k, v) in signature_def_map.items() if signature_def_utils.is_valid_signature(v)}
    return signature_def_map

def _create_state_functions(self, block_vars, nonlocal_declarations, getter_name, setter_name):
    if not block_vars:
        template = '\n        def getter_name():\n          return ()\n        def setter_name(block_vars):\n          pass\n      '
        return templates.replace(template, getter_name=getter_name, setter_name=setter_name)
    guarded_block_vars = []
    for v in block_vars:
        if <MASK>:
            guarded_block_vars.append(v)
        else:
            guarded_block_vars.append(templates.replace_as_expression('ag__.ldu(lambda: var_, name)', var_=v, name=gast.Constant(str(v), kind=None)))
    template = '\n      def getter_name():\n        return guarded_state_vars,\n      def setter_name(vars_):\n        nonlocal_declarations\n        state_vars, = vars_\n    '
    return templates.replace(template, nonlocal_declarations=nonlocal_declarations, getter_name=getter_name, guarded_state_vars=guarded_block_vars, setter_name=setter_name, state_vars=tuple(block_vars))

def _take_nd_object(arr: np.ndarray, indexer: npt.NDArray[np.intp], out: np.ndarray, axis: AxisInt, fill_value, mask_info) -> None:
    if mask_info is not None:
        (mask, needs_masking) = mask_info
    else:
        mask = indexer == -1
        needs_masking = mask.any()
    if <MASK>:
        arr = arr.astype(out.dtype)
    if arr.shape[axis] > 0:
        arr.take(indexer, axis=axis, out=out)
    if needs_masking:
        outindexer = [slice(None)] * arr.ndim
        outindexer[axis] = mask
        out[tuple(outindexer)] = fill_value

def get_custom_build_selector(provided_op_registration_allowlist: list[str] | None, op_selection_yaml_path: str | None) -> SelectiveBuilder:
    assert not (provided_op_registration_allowlist is not None and op_selection_yaml_path is not None), 'Both provided_op_registration_allowlist and ' + 'op_selection_yaml_path can NOT be provided at the ' + 'same time.'
    op_registration_allowlist: set[str] | None = None
    if provided_op_registration_allowlist is not None:
        op_registration_allowlist = set(provided_op_registration_allowlist)
    if op_registration_allowlist is not None:
        selector = SelectiveBuilder.from_legacy_op_registration_allow_list(op_registration_allowlist, True, False)
    elif <MASK>:
        selector = SelectiveBuilder.from_yaml_path(op_selection_yaml_path)
    else:
        selector = SelectiveBuilder.get_nop_selector()
    return selector

