def _string_split_transformer(parent, node, full_name, name, logs):
    """Update tf.string_split arguments: skip_empty, sep, result_type, source."""
    for (i, kw) in enumerate(node.keywords):
        if kw.arg == 'skip_empty':
            if _is_ast_false(kw.value):
                logs.append((ast_edits.INFO, node.lineno, node.col_offset, 'removed argument skip_empty for tf.string_split.'))
                node.keywords.pop(i)
                break
            else:
                return _rename_to_compat_v1(node, full_name, logs, "tf.string_split's replacement no longer takes the skip_empty argument.")
    found_sep = False
    for (i, kw) in enumerate(node.keywords):
        if kw.arg == 'sep':
            found_sep = True
            if <MASK>:
                if kw.value.s == '':
                    node = _rename_func(node, full_name, 'tf.strings.bytes_split', logs, 'Splitting bytes is not handled by tf.strings.bytes_split().')
                    node.keywords.pop(i)
            else:
                return _rename_to_compat_v1(node, full_name, logs, "The semantics for tf.string_split's sep parameter have changed when sep is the empty string; but sep is not a string literal, so we can't tell if it's an empty string.")
    if not found_sep:
        return _rename_to_compat_v1(node, full_name, logs, "The semantics for tf.string_split's sep parameter have changed when sep unspecified: it now splits on all whitespace, not just the space character.")
    return _string_split_rtype_transformer(parent, node, full_name, name, logs)

def __enter__(self):
    ctx = self._ctx
    old_device_name = ctx.device_name
    old_device_spec = ctx.device_spec
    new_device_name = self._device_name
    cache_key = (old_device_name, new_device_name)
    try:
        (new_device_name, new_device_spec) = _device_parsing_cache[cache_key]
    except TypeError as exc:
        raise ValueError('Expecting a string device name. Got %s(%s)' % (type(new_device_name), new_device_name)) from exc
    except KeyError as exc:
        if <MASK>:
            if not isinstance(new_device_name, str):
                raise ValueError('Expecting a string device name. Got %s(%s)' % (type(new_device_name), new_device_name)) from exc
            device_spec = pydev.DeviceSpec.from_string(new_device_name)
            if old_device_name:
                new_device_spec = copy.copy(old_device_spec)
            else:
                ctx.ensure_initialized()
                new_device_spec = pydev.DeviceSpec.from_string(ctx._context_devices[0])
            new_device_spec = new_device_spec.make_merged_spec(device_spec)
        else:
            new_device_spec = pydev.DeviceSpec.from_string('')
        new_device_name = new_device_spec.to_string()
        _device_parsing_cache[cache_key] = (new_device_name, new_device_spec)
    ctx._set_device(new_device_name, new_device_spec)
    self._stack.append((old_device_name, old_device_spec, new_device_spec))

def _num_samples(x):
    """Return number of samples in array-like x."""
    message = 'Expected sequence or array-like, got %s' % type(x)
    if hasattr(x, 'fit') and callable(x.fit):
        raise TypeError(message)
    if _use_interchange_protocol(x):
        return x.__dataframe__().num_rows()
    if not hasattr(x, '__len__') and (not hasattr(x, 'shape')):
        if <MASK>:
            (xp, _) = get_namespace(x)
            x = xp.asarray(x)
        else:
            raise TypeError(message)
    if hasattr(x, 'shape') and x.shape is not None:
        if len(x.shape) == 0:
            raise TypeError(f'Input should have at least 1 dimension i.e. satisfy `len(x.shape) > 0`, got scalar `{x!r}` instead.')
        if isinstance(x.shape[0], numbers.Integral):
            return x.shape[0]
    try:
        return len(x)
    except TypeError as type_error:
        raise TypeError(message) from type_error

