def _changeform_view(self, request, object_id, form_url, extra_context):
    to_field = request.POST.get(TO_FIELD_VAR, request.GET.get(TO_FIELD_VAR))
    if <MASK>:
        raise DisallowedModelAdminToField('The field %s cannot be referenced.' % to_field)
    if request.method == 'POST' and '_saveasnew' in request.POST:
        object_id = None
    add = object_id is None
    if add:
        if not self.has_add_permission(request):
            raise PermissionDenied
        obj = None
    else:
        obj = self.get_object(request, unquote(object_id), to_field)
        if request.method == 'POST':
            if not self.has_change_permission(request, obj):
                raise PermissionDenied
        elif not self.has_view_or_change_permission(request, obj):
            raise PermissionDenied
        if obj is None:
            return self._get_obj_does_not_exist_redirect(request, self.opts, object_id)
    fieldsets = self.get_fieldsets(request, obj)
    ModelForm = self.get_form(request, obj, change=not add, fields=flatten_fieldsets(fieldsets))
    if request.method == 'POST':
        form = ModelForm(request.POST, request.FILES, instance=obj)
        (formsets, inline_instances) = self._create_formsets(request, form.instance, change=not add)
        form_validated = form.is_valid()
        if form_validated:
            new_object = self.save_form(request, form, change=not add)
        else:
            new_object = form.instance
        if all_valid(formsets) and form_validated:
            self.save_model(request, new_object, form, not add)
            self.save_related(request, form, formsets, not add)
            change_message = self.construct_change_message(request, form, formsets, add)
            if add:
                self.log_addition(request, new_object, change_message)
                return self.response_add(request, new_object)
            else:
                self.log_change(request, new_object, change_message)
                return self.response_change(request, new_object)
        else:
            form_validated = False
    elif add:
        initial = self.get_changeform_initial_data(request)
        form = ModelForm(initial=initial)
        (formsets, inline_instances) = self._create_formsets(request, form.instance, change=False)
    else:
        form = ModelForm(instance=obj)
        (formsets, inline_instances) = self._create_formsets(request, obj, change=True)
    if not add and (not self.has_change_permission(request, obj)):
        readonly_fields = flatten_fieldsets(fieldsets)
    else:
        readonly_fields = self.get_readonly_fields(request, obj)
    admin_form = helpers.AdminForm(form, list(fieldsets), self.get_prepopulated_fields(request, obj) if add or self.has_change_permission(request, obj) else {}, readonly_fields, model_admin=self)
    media = self.media + admin_form.media
    inline_formsets = self.get_inline_formsets(request, formsets, inline_instances, obj)
    for inline_formset in inline_formsets:
        media += inline_formset.media
    if add:
        title = _('Add %s')
    elif self.has_change_permission(request, obj):
        title = _('Change %s')
    else:
        title = _('View %s')
    context = {**self.admin_site.each_context(request), 'title': title % self.opts.verbose_name, 'subtitle': str(obj) if obj else None, 'adminform': admin_form, 'object_id': object_id, 'original': obj, 'is_popup': IS_POPUP_VAR in request.POST or IS_POPUP_VAR in request.GET, 'to_field': to_field, 'media': media, 'inline_admin_formsets': inline_formsets, 'errors': helpers.AdminErrorList(form, formsets), 'preserved_filters': self.get_preserved_filters(request)}
    if request.method == 'POST' and (not form_validated) and ('_saveasnew' in request.POST):
        context['show_save'] = False
        context['show_save_and_continue'] = False
        add = False
    context.update(extra_context or {})
    return self.render_change_form(request, context, add=add, change=not add, obj=obj, form_url=form_url)

def stage_backward(stage_output, output_grads, input_values, outputs_with_grads_idxs: Optional[list[int]]=None) -> tuple[Optional[torch.Tensor], ...]:
    """
    This is a helper function to:
    1. compute the gradients for the stage inputs, and
    2. accumulate gradients for the stage module's parameters.

    Given the input value(s) and the corresponding gradient for the output
    value(s), compute and accumulate gradients for all parameter values (leaves
    in the autograd trace) as well as return a list of the gradients for the
    input values
    """
    if outputs_with_grads_idxs is not None:
        stage_output = [stage_output[i] for i in outputs_with_grads_idxs]
        output_grads = [output_grads[i] for i in outputs_with_grads_idxs]
    try:
        stage_output_tensors: list[torch.Tensor] = []
        output_grad_tensors: list[Optional[torch.Tensor]] = []

        def extract_tensors_with_grads(output_val, grad_val, extract_tensors_with_grads):
            if isinstance(output_val, torch.Tensor):
                if not output_val.requires_grad and output_val.grad_fn is None:
                    return
                assert isinstance(grad_val, (torch.Tensor, type(None))), f'Expected Tensor or None gradient but got {type(grad_val)}'
                stage_output_tensors.append(output_val)
                output_grad_tensors.append(grad_val)
            elif <MASK>:
                if grad_val is None:
                    return
                assert isinstance(grad_val, (tuple, list)), f'grad_value expected to have type {type(output_val)} but got {type(grad_val)}'
                assert len(output_val) == len(grad_val)
                for (ov, gv) in zip(output_val, grad_val):
                    extract_tensors_with_grads(ov, gv, extract_tensors_with_grads)
            elif isinstance(output_val, dict):
                if grad_val is None:
                    return
                assert isinstance(grad_val, dict)
                assert set(output_val.keys()) == set(grad_val.keys())
                for k in output_val.keys():
                    extract_tensors_with_grads(output_val[k], grad_val[k], extract_tensors_with_grads)
            else:
                pass
        extract_tensors_with_grads(stage_output, output_grads, extract_tensors_with_grads)
        torch.autograd.backward(stage_output_tensors, grad_tensors=output_grad_tensors)
        grad_inputs: list[Optional[torch.Tensor]] = []
        for val in input_values:
            if isinstance(val, torch.Tensor):
                grad_inputs.append(val.grad)
                val.grad = None
            else:
                grad_inputs.append(None)
        '\n        inputs_with_grad = []\n        for val in input_values:\n            if isinstance(val, torch.Tensor) and val.requires_grad:\n                inputs_with_grad.append(val)\n\n        grad_inputs = torch.autograd.grad(\n            stage_output_tensors, inputs_with_grad, output_grad_tensors,  # type: ignore[arg-type]\n        )\n        '
    except Exception as e:
        exc_msg = f'\n        Failed to run stage backward:\n        Stage output: {map_debug_info(stage_output)}\n        Output gradient: {map_debug_info(output_grads)}\n        Input: {map_debug_info(input_values)}\n        '
        raise RuntimeError(exc_msg) from e
    return tuple(grad_inputs)

@staticmethod
@deprecated('`torch.nn.utils.weight_norm` is deprecated in favor of `torch.nn.utils.parametrizations.weight_norm`.', category=FutureWarning)
def apply(module, name: str, dim: int) -> 'WeightNorm':
    for hook in module._forward_pre_hooks.values():
        if isinstance(hook, WeightNorm) and hook.name == name:
            raise RuntimeError(f'Cannot register two weight_norm hooks on the same parameter {name}')
    if <MASK>:
        dim = -1
    fn = WeightNorm(name, dim)
    weight = getattr(module, name)
    if isinstance(weight, UninitializedParameter):
        raise ValueError("The module passed to `WeightNorm` can't have uninitialized parameters. Make sure to run the dummy forward before applying weight normalization")
    del module._parameters[name]
    module.register_parameter(name + '_g', Parameter(norm_except_dim(weight, 2, dim).data))
    module.register_parameter(name + '_v', Parameter(weight.data))
    setattr(module, name, fn.compute_weight(module))
    module.register_forward_pre_hook(fn)
    return fn

def __init__(self, *expressions, fields=(), name=None, condition=None, deferrable=None, include=None, opclasses=(), nulls_distinct=None, violation_error_code=None, violation_error_message=None):
    if not name:
        raise ValueError('A unique constraint must be named.')
    if not expressions and (not fields):
        raise ValueError('At least one field or expression is required to define a unique constraint.')
    if expressions and fields:
        raise ValueError('UniqueConstraint.fields and expressions are mutually exclusive.')
    if not isinstance(condition, (NoneType, Q)):
        raise ValueError('UniqueConstraint.condition must be a Q instance.')
    if condition and deferrable:
        raise ValueError('UniqueConstraint with conditions cannot be deferred.')
    if include and deferrable:
        raise ValueError('UniqueConstraint with include fields cannot be deferred.')
    if opclasses and deferrable:
        raise ValueError('UniqueConstraint with opclasses cannot be deferred.')
    if expressions and deferrable:
        raise ValueError('UniqueConstraint with expressions cannot be deferred.')
    if <MASK>:
        raise ValueError('UniqueConstraint.opclasses cannot be used with expressions. Use django.contrib.postgres.indexes.OpClass() instead.')
    if not isinstance(deferrable, (NoneType, Deferrable)):
        raise TypeError('UniqueConstraint.deferrable must be a Deferrable instance.')
    if not isinstance(include, (NoneType, list, tuple)):
        raise TypeError('UniqueConstraint.include must be a list or tuple.')
    if not isinstance(opclasses, (list, tuple)):
        raise TypeError('UniqueConstraint.opclasses must be a list or tuple.')
    if not isinstance(nulls_distinct, (NoneType, bool)):
        raise TypeError('UniqueConstraint.nulls_distinct must be a bool.')
    if opclasses and len(fields) != len(opclasses):
        raise ValueError('UniqueConstraint.fields and UniqueConstraint.opclasses must have the same number of elements.')
    self.fields = tuple(fields)
    self.condition = condition
    self.deferrable = deferrable
    self.include = tuple(include) if include else ()
    self.opclasses = opclasses
    self.nulls_distinct = nulls_distinct
    self.expressions = tuple((F(expression) if isinstance(expression, str) else expression for expression in expressions))
    super().__init__(name=name, violation_error_code=violation_error_code, violation_error_message=violation_error_message)

def _codegen(self, nodes: list[BaseSchedulerNode]) -> None:
    if config.check_stack_no_cycles_TESTING_ONLY:
        import torch._dynamo.convert_frame
        stack = traceback.extract_stack()
        seen: OrderedSet[tuple[str, int | None]] = OrderedSet()
        for frame in reversed(stack):
            if <MASK>:
                break
            key = (frame.filename, frame.lineno)
            assert key not in seen, f'Duplicate stack frame {frame.filename}:{frame.lineno}; did you add a decorator to one of the functions in this stack trace?  If so, try using a context manager instead.'
            seen.add(key)
    self.current_device = self.default_device_context
    if self.default_device_context and config.triton.autotune_at_compile_time:
        V.graph.wrapper_code.write_get_raw_stream_header()
    for node in nodes:
        if log.isEnabledFor(logging.DEBUG):
            try:
                log.debug('Generating code for node %s with estimated runtime %f', node.get_name(), node.get_estimated_runtime())
            except Exception:
                log.debug('Generating code for node %s with estimated runtime 0.0', node.get_name())
        self.enter_context(node)
        if (device := node.get_device()):
            if device != self.current_device or node.is_extern() or node.is_template():
                self.flush()
            if device != self.current_device:
                if self.current_device and device_need_guard(self.current_device.type):
                    V.graph.wrapper_code.codegen_device_guard_exit()
                self.current_device = device
                if device_need_guard(device.type):
                    assert device.index is not None, 'device should have an index'
                    V.graph.wrapper_code.codegen_device_guard_enter(device.index)
        self.current_node = node
        self.buffer_names_to_free.update(node.last_usage)
        if node.is_template():
            (prologue, template_node, epilogue) = node.get_prologue_template_epilogue(list(node.get_nodes()))
            self.get_backend(device).codegen_template(template_node, epilogue, prologue)
        elif node.is_extern():
            node = typing.cast(ExternKernelSchedulerNode, node)
            self.codegen_extern_call(node)
        elif node.is_foreach():
            node = typing.cast(ForeachKernelSchedulerNode, node)
            backend_ = self.get_backend(device)
            from .codegen.cuda_combined_scheduling import CUDACombinedScheduling
            from .codegen.simd import SIMDScheduling
            if isinstance(backend_, (SIMDScheduling, CUDACombinedScheduling)):
                backend = backend_
            else:
                raise AssertionError(f'type(self)={type(self)!r}')
            backend.codegen_combo_kernel(node)
        elif isinstance(node, (FusedSchedulerNode, SchedulerNode)):
            self.get_backend(device).codegen_node(node)
        else:
            assert isinstance(node, NopKernelSchedulerNode)
            node.mark_run()
        if config.triton.debug_sync_kernel:
            self.get_backend(device).codegen_sync()
        self.available_buffer_names.update(node.get_buffer_names())
        self.completed_operations.update(node.get_operation_names())
        if not isinstance(node, NopKernelSchedulerNode):
            device = node.get_device()
            if device is not None and device.type != 'meta' and self.get_backend(device).ready_to_flush():
                self.flush()
    if self.current_device != self.default_device_context:
        assert self.current_device is not None
        if device_need_guard(self.current_device.type):
            V.graph.wrapper_code.codegen_device_guard_exit()
    self.flush()

