def remove_no_ops(gm: torch.fx.GraphModule, zeros: OrderedSet[torch.fx.Node], ones: OrderedSet[torch.fx.Node]):
    with torch.utils._python_dispatch._disable_current_modes():
        'Removes no-ops: (+ 0, - 0, * 1, / 1)'
        graph = gm.graph

        def fake_tensors_eq(t1, t2, fields=('shape', 'dtype', 'device')):
            if any((not isinstance(t, torch.Tensor) for t in (t1, t2))):
                return False
            for field in fields:
                if getattr(t1, field) != getattr(t2, field):
                    return False
            return True

        def replace_no_op(node, replace_input_index):
            replacement = node.args[replace_input_index]
            if not all((isinstance(arg, torch.fx.Node) for arg in node.args)):
                return
            if not fake_tensors_eq(node.meta['val'], replacement.meta['val']):
                if fake_tensors_eq(node.meta['val'], replacement.meta['val'], ('shape', 'device')):
                    with graph.inserting_after(node):
                        replacement = graph.call_function(torch.ops.prims.convert_element_type.default, args=(replacement, node.meta['val'].dtype))
                else:
                    return
            node.replace_all_uses_with(replacement)
            replacement.meta.update(node.meta)
            graph.erase_node(node)
        for node in graph.find_nodes(op='call_function', target=aten.add.Tensor):
            if len(node.args) == 2:
                if not any((e in zeros for e in node.args)) or node.kwargs.get('alpha', 1) != 1:
                    continue
                replace_index = 1 if node.args[0] in zeros else 0
                replace_no_op(node, replace_index)
        for node in graph.find_nodes(op='call_function', target=aten.sub.Tensor):
            if len(node.args) == 2:
                if node.args[1] not in zeros or node.kwargs.get('alpha', 1) != 1:
                    continue
                replace_no_op(node, 0)
        for node in graph.find_nodes(op='call_function', target=aten.mul.Tensor):
            if len(node.args) == 2:
                if not any((e in ones for e in node.args)):
                    continue
                replace_input_index = 1 if node.args[0] in ones else 0
                replace_no_op(node, replace_input_index)
        for node in graph.find_nodes(op='call_function', target=aten.div.Tensor):
            if <MASK>:
                replace_no_op(node, 0)
        for output_node in graph.find_nodes(op='output'):
            had_meta_return = False

            def visit(n):
                nonlocal had_meta_return
                val = n.meta.get('val')
                if isinstance(val, torch.Tensor) and val.device.type == 'meta':
                    with graph.inserting_before(output_node):
                        n.replace_all_uses_with(graph.call_function(torch.ops.aten.empty_strided.default, args=(val.size(), val.stride()), kwargs={'dtype': val.dtype, 'device': val.device}))
                    had_meta_return = True
            torch.fx.map_arg(output_node.args, visit)
            if had_meta_return:
                graph.eliminate_dead_code()

def fuse_matmul_reduce_scatter(reduce_scatter: _ReduceScatterMatch) -> None:
    """
    Fused the pattern

        reduce_scatter_tensor(A @ B, scatter_dim, group_name)

    into

        torch.ops.symm_mem.fused_matmul_reduce_scatter(
            A, B, scatter_dim, group_name,
        )

    Returns boolean indicating if fusion was successful or not.
    """
    if not torch.distributed.is_available() or not torch.distributed.is_nccl_available():
        return
    from torch.distributed._symmetric_memory import is_symm_mem_enabled_for_group, restride_A_for_fused_matmul_reduce_scatter
    (input_node, _reduce_scatter_node, rs_wait_tensor_node, reduce_op, orig_scatter_dim, group_name) = (reduce_scatter.input_node, reduce_scatter.reduce_scatter_node, reduce_scatter.wait_tensor_node, reduce_scatter.reduce_op, reduce_scatter.scatter_dim, reduce_scatter.group_name)
    if <MASK>:
        return
    filter_matmul = None
    if _is_last_dim(_get_tensor(input_node), orig_scatter_dim):

        def _filter_out_scaled_matmul(matmul: _Matmul):
            return not isinstance(matmul, _ScaledMatmul)
        filter_matmul = _filter_out_scaled_matmul
    if len(input_node.users) != 1:
        log.warning('matmul result has more than one user, skipping fused_matmul_reduce_scatter fusion.')
        return
    matmul = _find_producer_matmul(input_node)
    if matmul is None:
        log.warning('no producer matmul found for reduce scatter, skipping fuse_matmul_reduce_scatter fusion')
        return
    if filter_matmul and (not filter_matmul(matmul)):
        return
    if rs_wait_tensor_node in matmul.arg_ancestor_nodes:
        log.warning('reduce-scatter result node is an ancestor of matmul, skipping fuse_matmul_reduce_scatter fusion')
        return
    if matmul.pre_mm_reshape:
        scatter_dim_after_maybe_reshape = _scatter_dim_after_reshape(matmul.pre_mm_reshape, orig_scatter_dim)
    else:
        scatter_dim_after_maybe_reshape = orig_scatter_dim
    if matmul.post_mm_reshape:
        output_shape = list(_get_tensor(matmul.post_mm_reshape).shape)
    else:
        A_orig_shape = list(_get_tensor(matmul.A_node).shape)
        B_shape = list(_get_tensor(matmul.B_node).shape)
        output_shape = [*A_orig_shape[:-1], B_shape[-1]]
    graph = rs_wait_tensor_node.graph
    with graph.inserting_before(rs_wait_tensor_node):
        if 'val' in matmul.A_node.meta:
            restrided = restride_A_for_fused_matmul_reduce_scatter(_get_tensor(matmul.A_node), scatter_dim_after_maybe_reshape)
            matmul.A_node = graph.call_function(inductor_prims.force_stride_order, args=(matmul.A_node, restrided.stride()))
        fused_node = _insert_fused_matmul_reduce_scatter(graph, matmul, reduce_op, orig_scatter_dim, group_name, scatter_dim_after_maybe_reshape, output_shape)
        reduce_scatter.replace_with(fused_node)
        reduce_scatter.erase()
        matmul.erase()
    order = {node: idx for (idx, node) in enumerate(graph.nodes)}
    nodes_to_raise = sorted(matmul.arg_ancestor_nodes, key=lambda x: order[x])
    for node in nodes_to_raise:
        if order[node] > order[fused_node]:
            fused_node.prepend(node)
    log.debug('successfully fused matmul reduce scatter')

def get_attribute_fqn_from_ts_node(name_to_attribute_fqn: dict[str, str], node: torch._C.Node) -> str:

    def get_attr(name: str):
        if name in name_to_attribute_fqn:
            return name_to_attribute_fqn[name]
        else:
            raise ValueError(f'Attribute {name} not found')
    if <MASK>:
        input_name = next(node.inputs()).debugName()
    elif node.kind() == 'prim::GetAttr':
        input_name = node.input().debugName()
    else:
        raise RuntimeError(f'Unexpected node kind when getting attribute fqn. node: {node} ')
    attr_name = node.s('name')
    root_attr_name = get_attr(input_name)
    attr_fqn = f'{root_attr_name}.{attr_name}' if root_attr_name else attr_name
    return attr_fqn

def codegen_nodes(self, nodes: list[SchedulerNode]):
    self.legalize_lowp_fp_dtype(nodes)
    self.data_type_propagation(nodes)
    assert len(nodes) >= 1

    def fn(node, *index_vars):
        node.decide_inplace_update()
        node.mark_run()
        if isinstance(V.kernel, NullKernelHandler):
            return node._body(*index_vars)
        else:
            return node.codegen(index_vars)
    fn_list = [functools.partial(fn, node) for node in nodes]
    if <MASK>:

        def wrap_fn(fn):
            wrapped_fn = V.local_buffer_context.localize_function(fn)
            wrapped_fn.original_fn = fn
            return wrapped_fn
        fn_list = [wrap_fn(fn) for fn in fn_list]
    var_sizes_list = [node.group[1] for node in nodes]
    self.codegen_functions(fn_list, var_sizes_list)

def validate_domain_part(self, domain_part):
    if self.domain_regex.match(domain_part):
        return True
    literal_match = self.literal_regex.match(domain_part)
    if <MASK>:
        ip_address = literal_match[1]
        try:
            validate_ipv46_address(ip_address)
            return True
        except ValidationError:
            pass
    return False

def codegen_invoke_subgraph(self, invoke_subgraph):
    name = invoke_subgraph.get_name()
    self.writeline(f'{name} = [None] * {len(invoke_subgraph.outputs)}')
    outer_inputs = [buf.codegen_reference() for buf in invoke_subgraph.inputs]
    if <MASK>:
        outer_outputs = [f'{name}[{i}]' for i in range(len(invoke_subgraph.outputs))]
        self.codegen_subgraph_by_inlining(invoke_subgraph.subgraph, outer_inputs, outer_outputs)
    else:
        self.codegen_subgraph(invoke_subgraph.subgraph, outer_inputs, name)

def _modify_model_output_type_per_subgraph(model, subgraph_index, signature_index, inference_output_type):
    """Modify model output type per subgraph."""
    subgraph = model.subgraphs[subgraph_index]
    tensors = subgraph.tensors
    operators = subgraph.operators
    dequant_opcode_idxs = get_dequantize_opcode_idx(model)
    if operators and (not dequant_opcode_idxs):
        for output in subgraph.outputs:
            output_type = _convert_tflite_enum_type_to_tf_type(tensors[output].type)
            if output_type == dtypes.float32:
                raise ValueError('Model output is not dequantized.')
        return
    output_dequant_ops = []
    for op in operators:
        if op.opcodeIndex in dequant_opcode_idxs and op.outputs[0] in subgraph.outputs:
            (quant_tensor, float_tensor) = (tensors[op.inputs[0]], tensors[op.outputs[0]])
            float_type = _convert_tflite_enum_type_to_tf_type(float_tensor.type)
            if float_type != dtypes.float32:
                if float_type == inference_output_type:
                    continue
                else:
                    raise ValueError("Initial model output type must be tf.float32. Expected type for tensor with name '{}' is tf.float32, instead type is {}".format(float_tensor.name, get_tf_type_name(float_type)))
            quant_type = _convert_tflite_enum_type_to_tf_type(quant_tensor.type)
            if quant_type not in _MAP_QUANT_TO_IO_TYPES:
                raise ValueError("Initial model output is not dequantized. Expected type for tensor with name '{}' should be in {}, instead type is {}".format(quant_tensor.name, tuple((get_tf_type_name(t) for t in _MAP_QUANT_TO_IO_TYPES.keys())), get_tf_type_name(quant_type)))
            else:
                inference_io_types = _MAP_QUANT_TO_IO_TYPES[quant_type]
                if inference_output_type not in inference_io_types:
                    raise ValueError('Unsupported `inference_output_type` value. Expected to be in {}, instead got {}.'.format(tuple((get_tf_type_name(t) for t in inference_io_types)), get_tf_type_name(inference_output_type)))
            output_dequant_ops.append(op)
    if <MASK>:
        logging.warning('For model outputs containing unsupported operations which cannot be quantized, the `inference_output_type` attribute will default to the original type.')
    if inference_output_type == dtypes.uint8:
        quant_opcode_idx = -1
        for (idx, opcode) in enumerate(model.operatorCodes):
            builtin_code = schema_util.get_builtin_code_from_operator_code(opcode)
            if builtin_code == schema_fb.BuiltinOperator.QUANTIZE:
                quant_opcode_idx = idx
                break
        if quant_opcode_idx == -1:
            quant_op = schema_fb.OperatorCodeT()
            quant_op.builtinCode = schema_fb.BuiltinOperator.QUANTIZE
            quant_op.deprecatedBuiltinCode = schema_fb.BuiltinOperator.QUANTIZE
            model.operatorCodes.append(quant_op)
            quant_opcode_idx = len(model.operatorCodes) - 1
        for op in output_dequant_ops:
            op.opcodeIndex = quant_opcode_idx
            int8_quantization = tensors[op.inputs[0]].quantization
            uint8_quantization = schema_fb.QuantizationParametersT()
            uint8_quantization.scale = [int8_quantization.scale[0]]
            uint8_quantization.zeroPoint = [int8_quantization.zeroPoint[0] + 128]
            tensors[op.outputs[0]].quantization = uint8_quantization
            tensors[op.outputs[0]].type = schema_fb.TensorType.UINT8
    elif inference_output_type in _MAP_QUANT_TO_IO_TYPES:
        remove_tensors_idxs = set()
        for op in output_dequant_ops:
            subgraph.outputs[subgraph.outputs == op.outputs[0]] = op.inputs[0]
            if signature_index >= 0:
                signature_def = model.signatureDefs[signature_index]
                for i in range(len(signature_def.outputs)):
                    if signature_def.outputs[i].tensorIndex == op.outputs[0]:
                        signature_def.outputs[i].tensorIndex = op.inputs[0]
            remove_tensors_idxs.add(op.outputs[0])
            operators.remove(op)
        _remove_tensors_from_model(model, remove_tensors_idxs)
    else:
        raise ValueError('Unsupported `inference_output_type` value {}.'.format(get_tf_type_name(inference_output_type)))

def wrap_compiler_debug(unconfigured_compiler_fn: _CompileFxCallable, compiler_name: str) -> _CompileFxCallable:
    """
    Minifier for Fx Graph modules after Aot Autograd has finished. We wrap both
    forward and backward call separately with the backend compiler_fn - like
    inductor or nvfuser. Intercepting after Aot Autograd presents neat
    abstraction, where all the params are lifted as graph inputs, making it easy
    to save the graph as a string.
    """

    @functools.wraps(unconfigured_compiler_fn)
    def debug_wrapper(gm: torch.fx.GraphModule, example_inputs: Sequence[InputType], **kwargs: Unpack[_CompileFxKwargs]) -> OutputCode:
        from torch._subclasses import FakeTensorMode
        compiler_fn = functools.partial(unconfigured_compiler_fn, **kwargs)
        from torch._functorch.aot_autograd import get_aot_graph_name
        graph_name = get_aot_graph_name()
        orig_graph = copy.deepcopy(gm.graph)
        assert config.repro_after in ('dynamo', 'aot', None)
        try:
            inner_compiled_fn = compiler_fn(gm, example_inputs)
        except Exception:
            if config.repro_after == 'aot':
                if config.repro_level == 1:
                    dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), example_inputs, compiler_name)
                elif config.repro_level == 2:
                    dump_to_minify(fx.GraphModule(gm, orig_graph), example_inputs, compiler_name)
                log.error('CompilerError')
            raise

        def deferred_for_real_inputs(real_inputs: Sequence[InputType], **_kwargs: object) -> Any:
            assert not _kwargs
            if <MASK>:
                assert not isinstance(inner_compiled_fn, str)
                return inner_compiled_fn(real_inputs)
            with config.patch(repro_after=None):
                return inner_debug_fn(real_inputs)

        def inner_debug_fn(real_inputs: Sequence[InputType]) -> Any:
            """
            Aot Autograd fw_compiler and bw_compiler can have fake tensors. So,
            example_inputs can be fake tensors. We can call compiler_fn (which is
            inductor or nvfuser) with fake tensors but the actually compiled_fn
            should be called with real tensors. Therefore, the actual invocation
            is deferred.
            """
            fake_mode = FakeTensorMode()
            copy_tensor_attrs = [fake_mode.from_tensor(x) if isinstance(x, torch.Tensor) else x for x in real_inputs]
            if config.repro_level == 3:
                dump_to_minify(fx.GraphModule(gm, orig_graph), real_inputs, compiler_name)
            if config.repro_level == 4:
                if compiler_name != 'inductor':
                    raise NotImplementedError('Accuracy minification is supported for inductor only')
                failed = not same_two_models(gm, inner_compiled_fn, real_inputs, only_fwd=True, ignore_non_fp=config.repro_ignore_non_fp)
                if failed:
                    log.warning('Accuracy failed for the AOT Autograd graph %s', graph_name)
                    dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), real_inputs, f'{compiler_name}_accuracy')
                    dump_to_minify(fx.GraphModule(gm, orig_graph), real_inputs, f'{compiler_name}_accuracy')
                    raise AccuracyError('Bad accuracy detected')
                else:
                    return inner_compiled_fn(real_inputs)
            else:
                try:
                    out = inner_compiled_fn(real_inputs)
                    for arg in example_inputs:
                        if isinstance(arg, torch.Tensor) and arg.is_cuda:
                            torch.cuda.synchronize()
                            break
                    return out
                except Exception:
                    if config.repro_level == 1:
                        dump_compiler_graph_state(fx.GraphModule(gm, orig_graph), copy_tensor_attrs, compiler_name)
                    elif config.repro_level == 2:
                        dump_to_minify(fx.GraphModule(gm, orig_graph), copy_tensor_attrs, compiler_name)
                    raise
        if config.repro_after == 'aot':
            compiled_fn = deferred_for_real_inputs
            compiled_fn._boxed_call = True
            return compiled_fn
        else:
            return inner_compiled_fn
    return debug_wrapper

def _block_traverse_impl(self, nodes: NodeList, start_idx: int, end_idx: int, find_last_node: bool) -> Optional[int]:
    """
        Recursive block search implementation.
        find_last_node: If True, search for the last node which result in numerics difference
        if False: find first node in sorted node list
        """
    report: list[str] = []
    mid = (start_idx + end_idx) // 2
    cur_nodes_list: NodeList = nodes[:mid + 1] if find_last_node else nodes[mid:]
    if self.exclusion_fn:
        self.exclusion_fn(cur_nodes_list, -1, -1)
    cur_nodes = set(cur_nodes_list)
    first_node_name = cur_nodes_list[0].name
    last_node_name = cur_nodes_list[-1].name
    target_node_name = last_node_name if find_last_node else first_node_name
    self.iteration += 1
    self.reports.append(report)
    report.extend(['=' * 30, f'Block search iteration {self.iteration}'])
    report.extend([f"Search for {('last' if find_last_node else 'first')} node in culprits", f'From node index {start_idx}:{nodes[start_idx].name} to {end_idx}:{nodes[end_idx].name}. ', f'Subgraph constructed by {first_node_name} to {last_node_name}', f'Targeting node: {target_node_name}', f'Size of the interested node list is {end_idx - start_idx + 1}'])
    report_idx = len(self.reports) - 1
    try:
        (split_module, submod_name) = self._build_submodule(cur_nodes)
        self._run_and_compare(split_module, submod_name, [last_node_name], report_idx)
    except (FxNetMinimizerResultMismatchError, FxNetMinimizerRunFuncError):
        report.append(f'Culprits found from node {first_node_name} to {last_node_name}.')
        if start_idx == mid == end_idx:
            report.extend(['This is the last node in the sub-module. ', 'Search in the current branch is successful with node :', f'{start_idx}, node name: {nodes[start_idx].name}.'])
            self.print_report(report)
            return start_idx
        report.append('Proceed to split and lower the halves of the current sub-module individually.')
        self.print_report(report)
        if <MASK>:
            return self._block_traverse_impl(nodes, start_idx, mid, find_last_node)
        else:
            return self._block_traverse_impl(nodes, mid + 1, end_idx, find_last_node)
    else:
        report.append(f'Culprits not found from node start to {mid}:{nodes[mid].name}.')
        if start_idx == mid == end_idx:
            if start_idx == 0 and (not find_last_node) or (start_idx == len(nodes) - 1 and find_last_node):
                report.append(f"At {('last' if find_last_node else 'first')} node, no culprits found.")
                self.print_report(report)
                return None
            return start_idx + (1 if find_last_node else -1)
        report.append('Proceed to split and lower the halves of the current sub-module individually.')
        self.print_report(report)
        if find_last_node:
            return self._block_traverse_impl(nodes, mid + 1, end_idx, find_last_node)
        else:
            return self._block_traverse_impl(nodes, start_idx, mid, find_last_node)

def _convert_container(container, constructor_name, columns_name=None, dtype=None, minversion=None, categorical_feature_names=None):
    """Convert a given container to a specific array-like with a dtype.

    Parameters
    ----------
    container : array-like
        The container to convert.
    constructor_name : {"list", "tuple", "array", "sparse", "dataframe",             "pandas", "series", "index", "slice", "sparse_csr", "sparse_csc",             "sparse_csr_array", "sparse_csc_array", "pyarrow", "polars",             "polars_series"}
        The type of the returned container.
    columns_name : index or array-like, default=None
        For pandas/polars container supporting `columns_names`, it will affect
        specific names.
    dtype : dtype, default=None
        Force the dtype of the container. Does not apply to `"slice"`
        container.
    minversion : str, default=None
        Minimum version for package to install.
    categorical_feature_names : list of str, default=None
        List of column names to cast to categorical dtype.

    Returns
    -------
    converted_container
    """
    if <MASK>:
        if dtype is None:
            return list(container)
        else:
            return np.asarray(container, dtype=dtype).tolist()
    elif constructor_name == 'tuple':
        if dtype is None:
            return tuple(container)
        else:
            return tuple(np.asarray(container, dtype=dtype).tolist())
    elif constructor_name == 'array':
        return np.asarray(container, dtype=dtype)
    elif constructor_name in ('pandas', 'dataframe'):
        pd = pytest.importorskip('pandas', minversion=minversion)
        result = pd.DataFrame(container, columns=columns_name, dtype=dtype, copy=False)
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result[col_name] = result[col_name].astype('category')
        return result
    elif constructor_name == 'pyarrow':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        array = np.asarray(container)
        array = array[:, None] if array.ndim == 1 else array
        if columns_name is None:
            columns_name = [f'col{i}' for i in range(array.shape[1])]
        data = {name: array[:, i] for (i, name) in enumerate(columns_name)}
        result = pa.Table.from_pydict(data)
        if categorical_feature_names is not None:
            for (col_idx, col_name) in enumerate(result.column_names):
                if col_name in categorical_feature_names:
                    result = result.set_column(col_idx, col_name, result.column(col_name).dictionary_encode())
        return result
    elif constructor_name == 'polars':
        pl = pytest.importorskip('polars', minversion=minversion)
        result = pl.DataFrame(container, schema=columns_name, orient='row')
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result = result.with_columns(pl.col(col_name).cast(pl.Categorical))
        return result
    elif constructor_name == 'series':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Series(container, dtype=dtype)
    elif constructor_name == 'pyarrow_array':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        return pa.array(container)
    elif constructor_name == 'polars_series':
        pl = pytest.importorskip('polars', minversion=minversion)
        return pl.Series(values=container)
    elif constructor_name == 'index':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Index(container, dtype=dtype)
    elif constructor_name == 'slice':
        return slice(container[0], container[1])
    elif 'sparse' in constructor_name:
        if not sp.sparse.issparse(container):
            container = np.atleast_2d(container)
        if constructor_name in ('sparse', 'sparse_csr'):
            return sp.sparse.csr_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csr_array':
            return sp.sparse.csr_array(container, dtype=dtype)
        elif constructor_name == 'sparse_csc':
            return sp.sparse.csc_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csc_array':
            return sp.sparse.csc_array(container, dtype=dtype)

def gen_schema(self, subgraph, *operands, **kwargs):
    from .schema import HopSchemaGenerator
    subgraph = materialize_as_graph(subgraph, operands)
    (inp_inp_alias, inp_out_alias, out_out_alias, mutated_inp_idx, output) = check_input_alias_and_mutation_return_outputs(subgraph)
    if <MASK>:
        import warnings
        warnings.warn(f'Aliasing is not supported for HOP subgraph.\n{subgraph.print_readable(print_output=False)}\nAlias info: inp-inp alias: {inp_inp_alias}, inp-out alias: {inp_out_alias}, out-out alias{out_out_alias}This may lead to silent incorrectness.')
    schema_gen = HopSchemaGenerator(self)
    schema_gen.add_arg('subgraph', subgraph)
    for (idx, arg) in enumerate(operands):
        schema_gen.add_arg(f'arg{idx}', arg, is_mutated=idx in mutated_inp_idx)
    for (name, arg) in kwargs.items():
        schema_gen.add_arg(name, arg, default_value=arg, kw_only=True)
    for out in output:
        schema_gen.add_output(out)
    return schema_gen.gen_schema()

@staticmethod
def create(func, args, kwargs):
    assert func in [torch.amp.autocast_mode.autocast, torch.cuda.amp.autocast, torch.cpu.amp.autocast]
    bound_args = inspect.signature(func).bind(*args, **kwargs)
    bound_args.apply_defaults()
    target_values = []
    kwargs.clear()
    for key in ['device_type', 'dtype', 'enabled', 'cache_enabled']:
        if key == 'device_type' and func in [torch.cuda.amp.autocast, torch.cpu.amp.autocast]:
            arg = 'cuda' if func is torch.cuda.amp.autocast else 'cpu'
        else:
            arg = bound_args.arguments[key]
        if <MASK>:
            target_values.append(arg.as_python_constant())
        else:
            target_values.append(arg)
    var = AutocastModeVariable(target_values, initial_values=None, **kwargs)
    return var

@final
def _convert_to_ndarrays(self, dct: Mapping, na_values, na_fvalues, converters=None, dtypes=None) -> dict[Any, np.ndarray]:
    result = {}
    parse_date_cols = validate_parse_dates_presence(self.parse_dates, self.columns)
    for (c, values) in dct.items():
        conv_f = None if converters is None else converters.get(c, None)
        if <MASK>:
            cast_type = dtypes.get(c, None)
        else:
            cast_type = dtypes
        if self.na_filter:
            (col_na_values, col_na_fvalues) = get_na_values(c, na_values, na_fvalues, self.keep_default_na)
        else:
            (col_na_values, col_na_fvalues) = (set(), set())
        if c in parse_date_cols:
            mask = algorithms.isin(values, set(col_na_values) | col_na_fvalues)
            np.putmask(values, mask, np.nan)
            result[c] = values
            continue
        if conv_f is not None:
            if cast_type is not None:
                warnings.warn(f'Both a converter and dtype were specified for column {c} - only the converter will be used.', ParserWarning, stacklevel=find_stack_level())
            try:
                values = lib.map_infer(values, conv_f)
            except ValueError:
                mask = algorithms.isin(values, list(na_values)).view(np.uint8)
                values = lib.map_infer_mask(values, conv_f, mask)
            (cvals, na_count) = self._infer_types(values, set(col_na_values) | col_na_fvalues, cast_type is None, try_num_bool=False)
        else:
            is_ea = is_extension_array_dtype(cast_type)
            is_str_or_ea_dtype = is_ea or is_string_dtype(cast_type)
            try_num_bool = not (cast_type and is_str_or_ea_dtype)
            (cvals, na_count) = self._infer_types(values, set(col_na_values) | col_na_fvalues, cast_type is None, try_num_bool)
            if cast_type is not None:
                cast_type = pandas_dtype(cast_type)
            if cast_type and (cvals.dtype != cast_type or is_ea):
                if not is_ea and na_count > 0:
                    if is_bool_dtype(cast_type):
                        raise ValueError(f'Bool column has NA values in column {c}')
                cvals = self._cast_types(cvals, cast_type, c)
        result[c] = cvals
    return result

def resize(a: ArrayLike, new_shape=None):
    if new_shape is None:
        return a
    if isinstance(new_shape, int):
        new_shape = (new_shape,)
    a = a.flatten()
    new_size = 1
    for dim_length in new_shape:
        new_size *= dim_length
        if <MASK>:
            raise ValueError('all elements of `new_shape` must be non-negative')
    if a.numel() == 0 or new_size == 0:
        return torch.zeros(new_shape, dtype=a.dtype)
    repeats = -(-new_size // a.numel())
    a = concatenate((a,) * repeats)[:new_size]
    return reshape(a, new_shape)

@csrf_protect_m
def changelist_view(self, request, extra_context=None):
    """
        The 'change list' admin view for this model.
        """
    from django.contrib.admin.views.main import ERROR_FLAG
    app_label = self.opts.app_label
    if not self.has_view_or_change_permission(request):
