def use2fortran(use, tab=''):
    ret = ''
    for m in list(use.keys()):
        ret = f'{ret}{tab}use {m},'
        if <MASK>:
            if ret and ret[-1] == ',':
                ret = ret[:-1]
            continue
        if 'only' in use[m] and use[m]['only']:
            ret = f'{ret} only:'
        if 'map' in use[m] and use[m]['map']:
            c = ' '
            for k in list(use[m]['map'].keys()):
                if k == use[m]['map'][k]:
                    ret = f'{ret}{c}{k}'
                    c = ','
                else:
                    ret = f"{ret}{c}{k}=>{use[m]['map'][k]}"
                    c = ','
        if ret and ret[-1] == ',':
            ret = ret[:-1]
    return ret

def close_if_unusable_or_obsolete(self):
    """
        Close the current connection if unrecoverable errors have occurred
        or if it outlived its maximum age.
        """
    if <MASK>:
        self.health_check_done = False
        if self.get_autocommit() != self.settings_dict['AUTOCOMMIT']:
            self.close()
            return
        if self.errors_occurred:
            if self.is_usable():
                self.errors_occurred = False
                self.health_check_done = True
            else:
                self.close()
                return
        if self.close_at is not None and time.monotonic() >= self.close_at:
            self.close()
            return

def _validate_sample_input_sparse_reduction(op_info, sample, check_validate=False):
    """Return the specified sample when it is valid and supported by the
    operation. Otherwise, return the sample as ErrorInput instance.

    When check_validate is True, the result is validated against
    calling the op on the sample.
    """
    UNSPECIFIED = object()
    if op_info.name == 'sum':
        sample = _validate_sample_input_sparse_reduction_sum(sample)
    if op_info.name == 'masked.sum':
        mask = sample.kwargs.get('mask', UNSPECIFIED)
        if mask not in {None, UNSPECIFIED} and mask.ndim > 2 and (mask.layout is torch.strided) and (mask == 0).any():
            sample = ErrorInput(sample, error_regex='Expect the same number of specified elements per batch.')
        elif not sample.kwargs.get('keepdim'):
            sample = ErrorInput(sample, error_type=(AssertionError, RuntimeError), error_regex='reduction operations on (CSR|CSC) tensors with keepdim=False is unsupported')
        elif mask is UNSPECIFIED:
            sample = ErrorInput(sample, error_type=ValueError, error_regex='masked (.*) expects explicit mask for sparse_csr tensor input')
        elif <MASK>:
            sample = ErrorInput(sample, error_regex='crow_indices is supposed to be a vector, but got 3 dimensional tensor.')
    if op_info.name in {'masked.amax', 'masked.amin', 'masked.mean', 'masked.prod'}:
        t_inp = sample.input
        mask = sample.kwargs.get('mask')
        if mask is not None and mask.ndim > 2 and (mask.layout is torch.strided) and (mask == 0).any():
            sample = ErrorInput(sample, error_regex='Expect the same number of specified elements per batch.')
        elif mask is None:
            sample = ErrorInput(sample, error_type=ValueError, error_regex='masked (.*) expects explicit mask for sparse_csr tensor input')
        elif mask.layout is sample.input.layout and mask.ndim > 2 and (op_info.name == 'masked.mean'):
            sample = ErrorInput(sample, error_type=TypeError, error_regex='where[(][)] received an invalid combination of arguments - got [(]Tensor, Tensor, NoneType[)]')
        elif not sample.kwargs.get('keepdim'):
            sample = ErrorInput(sample, error_type=(AssertionError, RuntimeError), error_regex='reduction operations on (CSR|CSC) tensors with keepdim=False is unsupported')
        elif sample.input.ndim > 2 and sample.kwargs.get('dim') not in {0, 1} and (mask.ndim > 2) and (mask.layout is not torch.strided):
            if sample.kwargs.get('dim') == (0, -1):
                sample = ErrorInput(sample, error_regex='tensor dimensionality must be sum of batch, base, and dense dimensionalities')
            elif op_info.name == 'masked.prod':
                sample = ErrorInput(sample, error_regex='input_dim == 2 INTERNAL ASSERT FAILED at')
            else:
                sample = ErrorInput(sample, error_type=AssertionError, error_regex='Sparse CSR tensors are 2D and only support reduction along dim 0 or 1.')
        elif sample.input.ndim > 2:
            sample = ErrorInput(sample, error_regex='crow_indices is supposed to be a vector, but got 3 dimensional tensor.')
        elif mask.layout is t_inp.layout and mask._nnz() != t_inp._nnz() and (t_inp.dense_dim() > 0):
            sample = ErrorInput(sample, error_regex='Index tensor must have the same number of dimensions as src tensor')
    if check_validate:
        _check_validate(op_info, sample)
    return sample

def reductify_leaf(grad_input, grad_input_bdim, input_bdim, batch_size, target_shape_without_bdim_to_reduce_to=None):
    if grad_input is None:
        return None
    if grad_input_bdim is None and input_bdim is None:
        return grad_input
    if grad_input_bdim is not None and input_bdim is None:
        return grad_input.sum(grad_input_bdim)
    assert input_bdim is not None
    if <MASK>:
        grad_input = grad_input.unsqueeze(input_bdim)
        new_shape = list(grad_input.shape)
        new_shape[input_bdim] = batch_size
        grad_input = grad_input.expand(new_shape)
        grad_input_bdim = input_bdim
    if target_shape_without_bdim_to_reduce_to is not None:
        return vmap(torch.Tensor.sum_to_size, in_dims=(grad_input_bdim, None), out_dims=input_bdim)(grad_input, target_shape_without_bdim_to_reduce_to)
    if input_bdim != grad_input_bdim:
        grad_input = grad_input.movedim(grad_input_bdim, input_bdim)
    return grad_input

def _testGradient(self, np_input, bias, dtype, data_format, use_gpu):
    with self.cached_session(use_gpu=use_gpu):
        if data_format == 'NCHW':
            np_input = self._NHWCToNCHW(np_input)
        (jacob_a, jacob_n) = self._computeGradient(np_input, bias, dtype, data_format)
        (input_jacob_a, bias_jacob_a, grad_jacob_a) = jacob_a
        (input_jacob_n, bias_jacob_n, grad_jacob_n) = jacob_n
        if dtype in [np.float16, dtypes.bfloat16.as_numpy_dtype]:
            (_, jacob_n) = self._computeGradient(np_input, bias, np.float32, data_format)
            (input_jacob_n, bias_jacob_n, grad_jacob_n) = jacob_n
        if dtype == dtypes.float64:
            threshold = 1e-10
        elif <MASK>:
            threshold = 0.05
        else:
            threshold = 0.005
        self.assertAllClose(input_jacob_a, input_jacob_n, threshold, threshold)
        self.assertAllClose(bias_jacob_a, bias_jacob_n, threshold, threshold)
        self.assertAllClose(grad_jacob_a, grad_jacob_n, threshold, threshold)

@property
def underlying_value(self):
    if isinstance(self.vt, variables.LazyVariableTracker) and (not self.vt.is_realized()) and self.vt.is_hashable():
        return self.vt.original_value()
    if isinstance(self.vt, variables.TensorVariable):
        x = self.vt.as_proxy().node.meta['example_value']
    elif isinstance(self.vt, variables.TupleVariable):
        Hashable = ConstDictVariable._HashableTracker
        x = tuple((Hashable(e).underlying_value for e in self.vt.items))
    elif isinstance(self.vt, variables.NNModuleVariable):
        return self.vt.value
    elif <MASK>:
        return self.vt.value
    elif isinstance(self.vt, variables.UserFunctionVariable):
        return self.vt.get_function()
    elif isinstance(self.vt, variables.WeakRefVariable):
        Hashable = ConstDictVariable._HashableTracker
        return Hashable(self.vt.referent_vt).underlying_value
    elif isinstance(self.vt, variables.FrozenDataClassVariable):
        Hashable = ConstDictVariable._HashableTracker
        fields_values = {k: Hashable(v).underlying_value for (k, v) in self.vt.fields.items()}
        return variables.FrozenDataClassVariable.HashWrapper(self.vt.python_type(), fields_values)
    elif isinstance(self.vt, variables.UserDefinedObjectVariable):
        return self.vt.value
    else:
        x = self.vt.as_python_constant()
    return x

def convert_value(self, value, expression, connection):
    if isinstance(self.output_field, DateTimeField):
        if not settings.USE_TZ:
            pass
        elif value is not None:
            value = value.replace(tzinfo=None)
            value = timezone.make_aware(value, self.tzinfo)
        elif not connection.features.has_zoneinfo_database:
            raise ValueError('Database returned an invalid datetime value. Are time zone definitions for your database installed?')
    elif isinstance(value, datetime):
        if <MASK>:
            value = value.date()
        elif isinstance(self.output_field, TimeField):
            value = value.time()
    return value

def entropy(self):
    half_log_det = self._unbroadcasted_scale_tril.diagonal(dim1=-2, dim2=-1).log().sum(-1)
    H = 0.5 * self._event_shape[0] * (1.0 + math.log(2 * math.pi)) + half_log_det
    if <MASK>:
        return H
    else:
        return H.expand(self._batch_shape)

def op_list_to_dict(op_list, convert_variable_to_tensor=True):
    """Create a dictionary of names to operation lists.

  This method is only used when the variable name matters (e.g. when saving
  or restoring from a TF1 name-based checkpoint). In TF2, this can be called
  from `tf.train.Checkpoint.restore` when loading from a name-based checkpoint.

  Args:
    op_list: A (nested) list, tuple, or set of Variables or SaveableObjects.
    convert_variable_to_tensor: Whether or not to convert single Variables
      with no slice info into Tensors.

  Returns:
    A dictionary of names to the operations that must be saved under
    that name.  Variables with save_slice_info are grouped together under the
    same key in no particular order.

  Raises:
    TypeError: If the type of op_list or its elements is not supported.
    ValueError: If at least two saveables share the same name.
  """
    if not isinstance(op_list, (list, tuple, set)):
        raise TypeError(f'Variables to save should be passed in a dict or a list. Got {op_list}')
    op_list = nest.flatten(list(op_list))
    op_list = sorted(op_list, key=lambda x: x.name)
    names_to_saveables = {}
    for var in op_list:
        resource_or_ref_variable = isinstance(var, resource_variable_ops.BaseResourceVariable) or isinstance(var, ref_variable.RefVariable)
        if isinstance(var, saveable_object.SaveableObject):
            names_to_saveables[var.name] = var
        elif isinstance(var, variables.PartitionedVariable):
            if var.name in names_to_saveables:
                raise ValueError(f'At least two variables have the same name: {var.name}')
            names_to_saveables[var.name] = var
        elif isinstance(var, variables.Variable) and var._save_slice_info:
            name = var._save_slice_info.full_name
            if name in names_to_saveables:
                if not isinstance(names_to_saveables[name], list):
                    raise ValueError(f'Mixing slices and non-slices with the same name: {name}')
                names_to_saveables[name].append(var)
            else:
                names_to_saveables[name] = [var]
        elif isinstance(var, trackable.Trackable) and (not resource_or_ref_variable):
            trackable_saveables = [factory() if callable(factory) else factory for factory in saveable_objects_from_trackable(var, tf1_saver=True).values()]
            names_to_saveables.update(op_list_to_dict(trackable_saveables))
        elif not getattr(var, '_in_graph_mode', True):
            if not isinstance(var, resource_variable_ops.BaseResourceVariable):
                raise ValueError(f'Can only save/restore ResourceVariables when eager execution is enabled. Got type: {type(var)}.')
            set_var = names_to_saveables.setdefault(var._shared_name, var)
            if set_var is not var:
                raise ValueError(f"Two different ResourceVariable objects with the same shared_name '{var._shared_name}' were passed to the Saver. This likely means that they were created in different Graphs or isolated contexts, and may not be checkpointed together.")
        else:
            if convert_variable_to_tensor:
                if <MASK>:
                    var = var._graph_element
                else:
                    var = ops.convert_to_tensor(var, as_ref=True)
                if not _tensor_comes_from_variable(var):
                    raise TypeError(f'Variable to save is not a Variable: {var}')
            if var.op.type == 'ReadVariableOp':
                name = var.op.inputs[0].op.name
            else:
                name = var.op.name
            if name in names_to_saveables:
                raise ValueError(f'At least two variables have the same name: {name}')
            names_to_saveables[name] = var
    return names_to_saveables

def enumerate_epochs(self):
    """Yields `(epoch, tf.data.Iterator)`."""
    with self._truncate_execution_to_epoch():
        data_iterator = iter(self._dataset)
        for epoch in range(self._initial_epoch, self._epochs):
            if self._insufficient_data:
                break
            if <MASK>:
                data_iterator = iter(self._dataset)
            yield (epoch, data_iterator)
            self._adapter.on_epoch_end()

def _handle_insert_op_in_graph(self, tx: 'InstructionTranslator', args, kwargs):
    from .builder import wrap_fx_proxy, wrap_fx_proxy_cls
    if kwargs and (not self.tensor_args(*args, *kwargs.values())):
        return
    from .builder import SourcelessBuilder
    from .torch_function import can_dispatch_torch_function, dispatch_torch_function
    global BUILTIN_TO_TENSOR_RFN_MAP, BUILTIN_TO_TENSOR_FN_MAP
    if can_dispatch_torch_function(tx, args, kwargs):
        if not tx.export:
            populate_builtin_to_tensor_fn_map()
            if not isinstance(args[0], TensorVariable):
                if self.fn in BUILTIN_TO_TENSOR_RFN_MAP:
                    func = BUILTIN_TO_TENSOR_RFN_MAP[self.fn]
                else:
                    func = BUILTIN_TO_TENSOR_FN_MAP[self.fn]
                tmp = args[0]
                args[0] = args[1]
                args[1] = tmp
            else:
                func = BUILTIN_TO_TENSOR_FN_MAP[self.fn]
        else:
            func = self.fn
        fn_var = SourcelessBuilder.create(tx, func)
        return dispatch_torch_function(tx, fn_var, args, kwargs)
    fn = self.fn
    try:
        if self.python_and_tensor_constant_only(*args, **kwargs):
            from ..bytecode_transformation import unique_id
            from .functions import invoke_and_store_as_constant
            return invoke_and_store_as_constant(tx, fn, unique_id(fn.__name__), args, kwargs)
        if fn in IN_PLACE_DESUGARING_MAP and isinstance(args[0], variables.ConstantVariable):
            (fn, args) = (IN_PLACE_DESUGARING_MAP[fn], [args[0], args[1]])
        if <MASK>:
            (fn, args) = (torch.select, [args[0], variables.ConstantVariable.create(0), args[1]])
        if check_numpy_ndarray_args(args, kwargs) and (not any((type(arg) is variables.TensorVariable for arg in args))):
            proxy = tx.output.create_proxy('call_function', numpy_operator_wrapper(fn), *proxy_args_kwargs(args, kwargs))
            return wrap_fx_proxy_cls(variables.NumpyNdarrayVariable, tx, proxy)
        if fn is operator.eq and len(args) == 2 and isinstance(args[0], variables.TensorVariable):
            return args[0].call_method(tx, '__eq__', args[1:], kwargs)
        proxy = tx.output.create_proxy('call_function', fn, *proxy_args_kwargs(args, kwargs))
        if any((isinstance(arg, FakeItemVariable) for arg in args)):
            return wrap_fx_proxy_cls(FakeItemVariable, tx, proxy)
        elif check_unspec_python_args(args, kwargs):
            (_args, _kwargs) = self.unwrap_unspec_args_kwargs(args, kwargs)
            raw_value = fn(*_args, **_kwargs)
            need_unwrap = any((x.need_unwrap for x in itertools.chain(args, kwargs.values()) if isinstance(x, variables.UnspecializedPythonVariable)))
            return wrap_fx_proxy_cls(UnspecializedPythonVariable, tx, proxy, raw_value=raw_value, need_unwrap=need_unwrap)
        elif all((isinstance(x, SymNodeVariable) for x in args)):
            return SymNodeVariable.create(tx, proxy, None)
        else:
            if fn is operator.truediv and isinstance(args[0], variables.UnspecializedPythonVariable):
                args[0] = args[0].as_python_constant()
            return wrap_fx_proxy(tx, proxy)
    except NotImplementedError:
        unimplemented_v2(gb_type='unimplemented builtin op on tensor arguments', context=f'partial tensor op: {self} {args} {kwargs}', explanation=f'Dynamo does not know how to trace builtin operator {self.fn} with tensor arguments', hints=[*graph_break_hints.SUPPORTABLE])

def value_to_cpp(value, cpp_type):
    if value == float('-inf'):
        return f'-std::numeric_limits<{cpp_type}>::infinity()'
    elif value == float('inf'):
        return f'std::numeric_limits<{cpp_type}>::infinity()'
    elif isinstance(value, bool):
        return f'static_cast<{cpp_type}>({str(value).lower()})'
    elif <MASK>:
        return f'std::numeric_limits<{cpp_type}>::quiet_NaN()'
    else:
        return f'static_cast<{cpp_type}>({repr(value)})'

def _tree_map_with_path(func: Callable[..., Any], tree: Any, *dynamic_shapes: Any, tree_name: Optional[str]=None) -> Any:
    """
    Customized tree_map for mapping pytrees to dynamic_shapes.

    For built-in types (e.g., standard collections) this behaves exactly like tree_map.

    OTOH for a user-defined class C registered with pytree, we cannot assume that a C
    containing tensors can be mapped to a C containing dynamic shapes (i.e., C may not
    be a polymorphic container). In that case we use the flattened form of C instead.
    Thus a C(**tensors) that flattens to (**tensors) will map to (**dynamic_shapes).

    Args:
        func: function to apply to each (int, float, str, bool, None, torch.Tensor)
        tree: input pytree
        dynamic_shapes: zero or more (typically one) dynamic_shapes to match

    Returns:
        output pytree mapping func to each (int, float, str, bool, None, torch.Tensor)
    """

    def is_leaf(t):
        return _get_node_type(t) not in BUILTIN_TYPES

    def f(path, t, *dynamic_shapes):
        typ = _get_node_type(t)
        if typ in SUPPORTED_NODES:
            return tree_map_with_path(f, SUPPORTED_NODES[typ].flatten_fn(t)[0], *dynamic_shapes, is_leaf=is_leaf)
        else:
            return func(path, t, *dynamic_shapes)
    try:
        return tree_map_with_path(f, tree, *dynamic_shapes, is_leaf=is_leaf)
    except ValueError as e:
        if 'mismatch' in e.args[0]:
            assert dynamic_shapes, 'Cannot be a mismatch if there is no dynamic_shapes'
            assert tree_name, 'Must provide a tree_name when there might be a mismatch'

            def _key(type_, context, i):
                if <MASK>:
                    return MappingKey(context[i])
                if type_ in (list, tuple):
                    assert context is None
                    return SequenceKey(i)
                raise AssertionError(f'Did not expect type {type_}')

            def raise_mismatch_error(msg):
                from torch._dynamo.exc import UserError, UserErrorType
                raise UserError(UserErrorType.INVALID_INPUT, f'Detected mismatch between the structure of `{tree_name}` and `dynamic_shapes`: {msg}', case_name='dynamic_shapes_validation')

            def _compare(tree, dynamic_shapes, path):
                rendered_path = keystr(path)
                if isinstance(tree, LeafSpec):
                    return
                if isinstance(dynamic_shapes, LeafSpec):
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is not')
                if tree.type != dynamic_shapes.type:
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is a {dynamic_shapes.type}')
                if len(tree.children_specs) != len(dynamic_shapes.children_specs):
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` has {len(tree.children_specs)} elements, but `dynamic_shapes{rendered_path}` has {len(dynamic_shapes.children_specs)} elements')
                if tree.type is dict:
                    if sorted(tree.context) != sorted(dynamic_shapes.context):
                        raise_mismatch_error(f'`{tree_name}{rendered_path}` has keys {tree.context}, but `dynamic_shapes{rendered_path}` has keys {dynamic_shapes.context}')
                    _remap = dict(zip(dynamic_shapes.context, dynamic_shapes.children_specs))
                    dynamic_shapes_children_specs = [_remap[k] for k in tree.context]
                else:
                    dynamic_shapes_children_specs = dynamic_shapes.children_specs
                for (i, (tree_, dynamic_shapes_)) in enumerate(zip(tree.children_specs, dynamic_shapes_children_specs)):
                    _compare(tree_, dynamic_shapes_, path + [_key(tree.type, tree.context, i)])
            (_, tree_spec) = tree_flatten(tree, is_leaf=is_leaf)
            for other_tree in dynamic_shapes:
                (_, other_tree_spec) = tree_flatten(other_tree, is_leaf)
                _compare(tree_spec, other_tree_spec, [])
        raise

def handle_placeholder(self, node: torch.fx.Node):
    assert node.op == 'placeholder'
    val = node.meta['val']
    log.debug('[handle_placeholder] %s: %s', node.name, val)
    if isinstance(val, torch.Tensor):
        graph_input = Argument.create(as_tensor=self.serialize_tensor_output(node.name, val))
    elif <MASK>:
        graph_input = Argument.create(as_sym_int=self.serialize_sym_int_output(node.name, val))
    elif isinstance(val, torch.SymFloat):
        raise AssertionError('SymFloat graph input is not implemented yet.')
    elif isinstance(val, (int, bool, str, float, type(None))):
        graph_input = self.serialize_input(val)
    elif isinstance(val, ep.CustomObjArgument):
        class_fqn = val.class_fqn
        graph_input = Argument.create(as_custom_obj=CustomObjArgument(name=node.name, class_fqn=class_fqn))
        self.graph_state.custom_obj_values[node.name] = self.serialize_script_obj_meta(val)
    else:
        raise AssertionError(f"Unimplemented graph input type: {node.meta['val']}")
    self.graph_state.inputs.append(graph_input)

def __init__(self, data=None, index: Axes | None=None, columns: Axes | None=None, dtype: Dtype | None=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if dtype is not None:
        dtype = self._validate_dtype(dtype)
    if isinstance(data, DataFrame):
        data = data._mgr
        allow_mgr = True
        if not copy:
            data = data.copy(deep=False)
    if isinstance(data, BlockManager):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        if index is None and columns is None and (dtype is None) and (not copy):
            NDFrame.__init__(self, data)
            return
    if isinstance(index, set):
        raise ValueError('index cannot be a set')
    if isinstance(columns, set):
        raise ValueError('columns cannot be a set')
    if copy is None:
        if <MASK>:
            copy = True
        elif not isinstance(data, (Index, DataFrame, Series)):
            copy = True
        else:
            copy = False
    if data is None:
        index = index if index is not None else default_index(0)
        columns = columns if columns is not None else default_index(0)
        dtype = dtype if dtype is not None else pandas_dtype(object)
        data = []
    if isinstance(data, BlockManager):
        mgr = self._init_mgr(data, axes={'index': index, 'columns': columns}, dtype=dtype, copy=copy)
    elif isinstance(data, dict):
        mgr = dict_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, ma.MaskedArray):
        from numpy.ma import mrecords
        if isinstance(data, mrecords.MaskedRecords):
            raise TypeError('MaskedRecords are not supported. Pass {name: data[name] for name in data.dtype.names} instead')
        data = sanitize_masked_array(data)
        mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif isinstance(data, (np.ndarray, Series, Index, ExtensionArray)):
        if data.dtype.names:
            data = cast(np.ndarray, data)
            mgr = rec_array_to_mgr(data, index, columns, dtype, copy)
        elif isinstance(data, (ABCSeries, ABCIndex)) and data.name is not None:
            mgr = dict_to_mgr({data.name: data}, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
    elif is_list_like(data):
        if not isinstance(data, abc.Sequence):
            if hasattr(data, '__array__'):
                data = np.asarray(data)
            else:
                data = list(data)
        if len(data) > 0:
            if is_dataclass(data[0]):
                data = dataclasses_to_dicts(data)
            if not isinstance(data, np.ndarray) and treat_as_nested(data):
                if columns is not None:
                    columns = ensure_index(columns)
                (arrays, columns, index) = nested_data_to_arrays(data, columns, index, dtype)
                mgr = arrays_to_mgr(arrays, columns, index, dtype=dtype)
            else:
                mgr = ndarray_to_mgr(data, index, columns, dtype=dtype, copy=copy)
        else:
            mgr = dict_to_mgr({}, index, columns if columns is not None else default_index(0), dtype=dtype)
    else:
        if index is None or columns is None:
            raise ValueError('DataFrame constructor not properly called!')
        index = ensure_index(index)
        columns = ensure_index(columns)
        if not dtype:
            (dtype, _) = infer_dtype_from_scalar(data)
        if isinstance(dtype, ExtensionDtype):
            values = [construct_1d_arraylike_from_scalar(data, len(index), dtype) for _ in range(len(columns))]
            mgr = arrays_to_mgr(values, columns, index, dtype=None)
        else:
            arr2d = construct_2d_arraylike_from_scalar(data, len(index), len(columns), dtype, copy)
            mgr = ndarray_to_mgr(arr2d, index, columns, dtype=arr2d.dtype, copy=False)
    NDFrame.__init__(self, mgr)

def getmethodclass(m):
    """Resolves a function's owner, e.g.

  a method's class.

  Note that this returns the object that the function was retrieved from, not
  necessarily the class where it was defined.

  This function relies on Python stack frame support in the interpreter, and
  has the same limitations that inspect.currentframe.

  Limitations. This function will only work correctly if the owned class is
  visible in the caller's global or local variables.

  Args:
    m: A user defined function

  Returns:
    The class that this function was retrieved from, or None if the function
    is not an object or class method, or the class that owns the object or
    method is not visible to m.

  Raises:
    ValueError: if the class could not be resolved for any unexpected reason.
  """
    if not hasattr(m, '__name__') and hasattr(m, '__class__') and hasattr(m, '__call__'):
        if isinstance(m.__class__, type):
            return m.__class__
    m_self = getattr(m, '__self__', None)
    if m_self is not None:
        if inspect.isclass(m_self):
            return m_self
        return m_self.__class__
    owners = []
    caller_frame = tf_inspect.currentframe().f_back
    try:
        for v in itertools.chain(caller_frame.f_locals.values(), caller_frame.f_globals.values()):
            if hasattr(v, m.__name__):
                candidate = getattr(v, m.__name__)
                if hasattr(candidate, 'im_func'):
                    candidate = candidate.im_func
                if hasattr(m, 'im_func'):
                    m = m.im_func
                if candidate is m:
                    owners.append(v)
    finally:
        del caller_frame
    if <MASK>:
        if len(owners) == 1:
            return owners[0]
        owner_types = tuple((o if tf_inspect.isclass(o) else type(o) for o in owners))
        for o in owner_types:
            if tf_inspect.isclass(o) and issubclass(o, tuple(owner_types)):
                return o
        raise ValueError('Found too many owners of %s: %s' % (m, owners))
    return None

def _check_list_display_item(self, obj, item, label):
    if callable(item):
        return []
    elif <MASK>:
        return []
    try:
        field = obj.model._meta.get_field(item)
    except FieldDoesNotExist:
        try:
            field = getattr(obj.model, item)
        except AttributeError:
            try:
                field = get_fields_from_path(obj.model, item)[-1]
            except (FieldDoesNotExist, NotRelationField):
                return [checks.Error(f"The value of '{label}' refers to '{item}', which is not a callable or attribute of '{obj.__class__.__name__}', or an attribute, method, or field on '{obj.model._meta.label}'.", obj=obj.__class__, id='admin.E108')]
    if getattr(field, 'is_relation', False) and (field.many_to_many or field.one_to_many) or (getattr(field, 'rel', None) and field.rel.field.many_to_one):
        return [checks.Error(f"The value of '{label}' must not be a many-to-many field or a reverse foreign key.", obj=obj.__class__, id='admin.E109')]
    return []

def add_arg(self, name: str, example_value: Any, default_value: Optional[Any]=None, is_mutated: bool=False, kw_only: bool=False) -> None:
    if callable(example_value):
        assert isinstance(example_value, (torch.fx.GraphModule, torch._ops.OperatorBase)), f'Expect callable to be a GraphModule or an. Please call materialize_as_graph first to turn callable arguments {example_value} into a GraphModule.'
    (_, flat_spec) = pytree.tree_flatten(example_value)
    if <MASK>:
        raise RuntimeError(f'example_value {example_value} is not a leaf node. Please only add flattened inputs to the hop schema. If you need some structure in the arguments, pleaseadd_arg for flattened args one by one then call add_schema_tree_spec to register the original pytree  spec of the args.')
    arg_info = HopArgumentInfoGen.from_example(example_value=example_value, name=name, default_value=default_value, is_mutated=is_mutated, kw_only=kw_only)
    self.arg_infos.append(arg_info)

def shared_data_after_reordering_loop(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode) -> int:
    """
        Right now just greedily reorder the loop of node1 to be compatible with node2,
        but ideally we should have some heuristics to reorder the loop for node2
        to be compatible with node1 if that's more efficient.

        Return the amount of shared data re-computed in this method.
        If no such recomputation happens, return -1 (not return 0 since 0 is a valid
        amount of shared data).

        """
    if not config.loop_ordering_after_fusion or any((n.is_cpu() for n in [node1, node2])):
        return -1
    if node1.is_template() or node2.is_template():
        return -1
    node1_buffer_names = node1.read_writes.buffer_names()
    node2_buffer_names = node2.read_writes.buffer_names()
    common_buffer_names = node1_buffer_names & node2_buffer_names
    if not common_buffer_names:
        return -1
    node1_name2dep = {dep.name: dep for dep in node1.read_writes.reads_and_writes()}
    node2_name2dep = {dep.name: dep for dep in node2.read_writes.reads_and_writes()}
    candidates = []
    for buffer_name in common_buffer_names:
        lhs_dep = node1_name2dep[buffer_name]
        rhs_dep = node2_name2dep[buffer_name]
        if lhs_dep.normalize_with_stride_order() == rhs_dep.normalize_with_stride_order():
            candidates.append((V.graph.sizevars.size_hint(lhs_dep.get_numel(), fallback=0), lhs_dep, rhs_dep))
    if len(candidates) == 0:
        return -1
    (_numel, lhs_dep, rhs_dep) = max(candidates, key=operator.itemgetter(0))
    if not isinstance(lhs_dep, MemoryDep) or not isinstance(rhs_dep, MemoryDep):
        return -1
    if lhs_dep.num_vars != rhs_dep.num_vars:
        if <MASK>:
            return self.dep_size_hint(lhs_dep)
        return -1
    reordered = False
    if not node1.is_reduction():
        reordered = node1.reorder_loops_by_dep_pair(lhs_dep, rhs_dep)
    elif not node2.is_reduction():
        reordered = node2.reorder_loops_by_dep_pair(rhs_dep, lhs_dep)
    else:
        loop_ordering_log.debug("Don't reorder loops since both nodes are reductions: %s v.s. %s", node1.get_name(), node2.get_name())
    return self.score_fusion_memory(node1, node2) if reordered else -1

