def testFromFields(self, shape, fields, expected_shape=None, nrows=None, row_partitions=None):
    if <MASK>:
        fields = fields()
    if callable(nrows):
        nrows = nrows()
    if callable(row_partitions):
        row_partitions = row_partitions()
    for validate in (True, False):
        struct = StructuredTensor.from_fields(fields, shape, nrows=nrows, row_partitions=row_partitions, validate=validate)
        if expected_shape is None:
            expected_shape = shape
        self.assertEqual(struct.shape.as_list(), expected_shape)
        self.assertLen(expected_shape, struct.rank)
        self.assertCountEqual(struct.field_names(), tuple(fields.keys()))
        for (field, value) in fields.items():
            self.assertIsInstance(struct.field_value(field), (tensor.Tensor, structured_tensor.StructuredTensor, ragged_tensor.RaggedTensor))
            self.assertAllEqual(struct.field_value(field), value)

def clone_metric(metric):
    """Returns a clone of the metric if stateful, otherwise returns it as is."""
    if <MASK>:
        with ops.init_scope():
            return metric.__class__.from_config(metric.get_config())
    return metric

def visit_Name(self, node):
    if not anno.hasanno(node, anno.Static.ORIG_DEFINITIONS):
        return node
    if <MASK>:
        node = templates.replace_as_expression('ag__.ld(var_)', var_=node)
    return node

def make_run_fn(self, *input_tensors: torch.Tensor, out: torch.Tensor) -> Callable[[], None]:
    mod = PyCodeCache.load_by_key_path(self.module_cache_key, self.module_path)
    autotuning_log.debug('benchmark module key: %s, path: %s', self.module_cache_key, self.module_path)
    run_method = getattr(mod, self.kernel_name).run
    extra_args = list(self.extra_args)
    run_method.__self__.with_bandwidth_info = False
    warmup_arg = {}
    import inspect
    if 'warmup' in inspect.signature(run_method).parameters:
        warmup_arg['warmup'] = False
    if <MASK>:
        stream = 0
    else:
        device_type = out.device.type
        device_interface = get_interface_for_device(device_type)
        stream = device_interface.get_raw_stream(self.output_tensor_meta.device.index)
    if isinstance(getattr(mod, self.kernel_name), torch._inductor.runtime.triton_heuristics.DebugAutotuner):
        return functools.partial(run_method, *input_tensors, out, *extra_args, **warmup_arg, stream=stream)
    else:
        return functools.partial(run_method, *input_tensors, out, *extra_args, **warmup_arg, stream=stream, benchmark_run=True)

def _parse_qr_mode(mode: str) -> tuple[bool, bool]:
    if mode == 'reduced':
        compute_q = True
        reduced = True
    elif mode == 'complete':
        compute_q = True
        reduced = False
    elif <MASK>:
        compute_q = False
        reduced = True
    else:
        torch._check(False, lambda : f"qr received unrecognized mode '{mode}' but expected one of 'reduced' (default), 'r', or 'complete'")
    return (compute_q, reduced)

def record_migration(self, app_label, name, forward=True):
    migration = self.loader.disk_migrations.get((app_label, name))
    if migration and migration.replaces:
        for (replaced_app_label, replaced_name) in migration.replaces:
            self.record_migration(replaced_app_label, replaced_name, forward)
    if <MASK>:
        self.recorder.record_applied(app_label, name)
    else:
        self.recorder.record_unapplied(app_label, name)

@property
def write_cols(self) -> SequenceNotStr[Hashable]:
    if self._has_aliases:
        assert not isinstance(self.header, bool)
        if <MASK>:
            raise ValueError(f'Writing {len(self.cols)} cols but got {len(self.header)} aliases')
        return self.header
    else:
        return cast(SequenceNotStr[Hashable], self.cols)

def reduce_tensor(tensor):
    if tensor.requires_grad and (not tensor.is_leaf):
        raise RuntimeError('Cowardly refusing to serialize non-leaf tensor which requires_grad, since autograd does not support crossing process boundaries.  If you just want to transfer the data, call detach() on the tensor before serializing (e.g., putting it on the queue).')
    check_serializing_named_tensor(tensor)
    torch.utils.hooks.warn_if_has_hooks(tensor)
    from torch.nested._internal.nested_tensor import NestedTensor
    if tensor.is_nested and (not isinstance(tensor, NestedTensor)):
        return reduce_nested_tensor(tensor)
    if tensor.layout in {torch.sparse_coo, torch.sparse_csr, torch.sparse_bsr, torch.sparse_csc, torch.sparse_bsc}:
        return reduce_sparse_tensor(tensor)
    storage = tensor._typed_storage()
    if <MASK>:
        (device, handle, storage_size_bytes, storage_offset_bytes, ref_counter_handle, ref_counter_offset, event_handle, event_sync_required) = storage._share_cuda_()
        tensor_offset = tensor.storage_offset()
        shared_cache[handle] = StorageWeakRef(storage)
        return (rebuild_cuda_tensor, (type(tensor), tensor.size(), tensor.stride(), tensor_offset, type(storage), tensor.dtype, device, handle, storage_size_bytes, storage_offset_bytes, tensor.requires_grad, ref_counter_handle, ref_counter_offset, event_handle, event_sync_required))
    elif storage._untyped_storage.device.type == 'meta':
        return (rebuild_meta_tensor, (type(tensor), tensor.size(), tensor.stride(), tensor.storage_offset(), tensor.dtype, tensor.untyped_storage().size(), tensor.requires_grad))
    metadata = (tensor.storage_offset(), tensor.size(), tensor.stride(), tensor.requires_grad)
    return (rebuild_tensor, (type(tensor), storage, metadata))

def condition(children):
    for child in children:
        if <MASK>:
            continue
        is_unexpected_success = 'unexpected success' in child.attrib['message'].lower()
        if not is_unexpected_success:
            return True
    return False

def _ragged_stack_concat_helper(rt_inputs, axis, stack_values):
    """Helper function to concatenate or stack ragged tensors.

  Args:
    rt_inputs: A list of RaggedTensors or Tensors to combine.
    axis: The axis along which to concatenate or stack.
    stack_values: A boolean -- if true, then stack values; otherwise,
      concatenate them.

  Returns:
    A RaggedTensor.
  Raises:
    ValueError: If rt_inputs is empty, or if axis is out of range.
  """
    if not rt_inputs:
        raise ValueError('rt_inputs may not be empty.')
    rt_inputs = [ragged_tensor.convert_to_tensor_or_ragged_tensor(rt_input, name='rt_input') for rt_input in rt_inputs]
    (row_splits_dtype, rt_inputs) = ragged_tensor.match_row_splits_dtypes(*rt_inputs, return_dtype=True)
    rt_inputs = list(rt_inputs)
    if len(rt_inputs) == 1 and (not stack_values):
        return rt_inputs[0]
    ndims = None
    for rt in rt_inputs:
        if <MASK>:
            ndims = rt.shape.ndims
        else:
            rt.shape.assert_has_rank(ndims)
    out_ndims = ndims if ndims is None or not stack_values else ndims + 1
    axis = array_ops.get_positive_axis(axis, out_ndims)
    if stack_values and ndims == 1 and (axis == 0):
        return ragged_tensor.RaggedTensor.from_row_lengths(values=array_ops.concat(rt_inputs, axis=0), row_lengths=array_ops.concat([array_ops.shape(r) for r in rt_inputs], axis=0))
    if all((not ragged_tensor.is_ragged(rt) for rt in rt_inputs)):
        if ndims is not None and (axis == out_ndims - 1 or axis == ndims - 1):
            if stack_values:
                return array_ops_stack.stack(rt_inputs, axis)
            else:
                return array_ops.concat(rt_inputs, axis)
    for i in range(len(rt_inputs)):
        if not ragged_tensor.is_ragged(rt_inputs[i]):
            rt_inputs[i] = ragged_tensor.RaggedTensor.from_tensor(rt_inputs[i], ragged_rank=1, row_splits_dtype=row_splits_dtype)
    ragged_rank = max(max((rt.ragged_rank for rt in rt_inputs)), 1)
    rt_inputs = [_increase_ragged_rank_to(rt, ragged_rank, row_splits_dtype) for rt in rt_inputs]
    if axis == 0:
        return _ragged_stack_concat_axis_0(rt_inputs, stack_values)
    elif axis == 1:
        return _ragged_stack_concat_axis_1(rt_inputs, stack_values)
    else:
        values = [rt.values for rt in rt_inputs]
        splits = [[rt_input.row_splits] for rt_input in rt_inputs]
        with ops.control_dependencies(ragged_util.assert_splits_match(splits)):
            return ragged_tensor.RaggedTensor.from_row_splits(_ragged_stack_concat_helper(values, axis - 1, stack_values), splits[0][0], validate=False)

