def swap_tensors_dict(self, named_tensors: dict[str, torch.Tensor], allow_missing: bool=False) -> tuple[dict[str, torch.Tensor], list[str]]:
    """
        Swap the attributes specified by the given paths to values.

        For example, to swap the attributes mod.layer1.conv1.weight and
        mod.layer1.conv1.bias, use accessor.swap_tensors_dict({
            "layer1.conv1.weight": weight,
            "layer1.conv1.bias": bias,
        })
        """
    orig_named_tensors = {}
    missing_keys = []
    try:
        for (name, tensor) in named_tensors.items():
            orig_tensor = self.swap_tensor(name, tensor, allow_missing=True)
            if <MASK>:
                missing_keys.append(name)
            orig_named_tensors[name] = orig_tensor
    except Exception:
        for (name, orig_tensor) in orig_named_tensors.items():
            self.swap_tensor(name, orig_tensor, allow_missing=True)
        raise
    if missing_keys and (not allow_missing):
        for (name, orig_tensor) in orig_named_tensors.items():
            self.swap_tensor(name, orig_tensor, allow_missing=True)
        raise RuntimeError(f"Missing key(s): {', '.join(map(repr, missing_keys))}.")
    return (orig_named_tensors, missing_keys)

def _add_send_recv(compute_actions: dict[int, list[_Action]], stage_to_rank: Callable[[int], int], num_stages: int) -> dict[int, list[_Action]]:
    """
    Transforms a compute-only schedule into a complete schedule with communication actions.

    For actions with sub-actions (OVERLAP_F_B) we ensure that all the subactions have been
    computed and the communication is ready
    """
    comm_actions: dict[int, list[_Action]] = {rank: [] for rank in compute_actions}
    prev_actions: dict[int, set[_Action]] = {rank: set() for rank in compute_actions}

    def _has_comms(action: _Action) -> bool:
        if action.computation_type == F:
            return action.stage_index != num_stages - 1 and stage_to_rank(action.stage_index + 1) != stage_to_rank(action.stage_index)
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
            return action.stage_index != 0 and stage_to_rank(action.stage_index - 1) != stage_to_rank(action.stage_index)
        return False

    def _get_comms(action: _Action) -> tuple[_Action, _Action]:
        assert _has_comms(action), f'{action} is not a valid comm action'
        stage_idx = action.stage_index
        ctype = action.computation_type
        mb_idx = action.microbatch_index
        send = _Action(stage_idx, SEND_F if ctype == F else SEND_B, mb_idx)
        recv_stage_idx = stage_idx + 1 if ctype == F else stage_idx - 1
        recv = _Action(recv_stage_idx, RECV_F if ctype == F else RECV_B, mb_idx)
        return (send, recv)

    def _ready_to_schedule(action: Optional[_Action], prev_actions: set[_Action]) -> bool:
        """We don't put our own recv ops in the schedule, we let a sender on another rank put our recv ops in place.
        This helps ensure a sane (non-hanging) ordering of sends and recvs.
        But it also means we might not be able to schedule our next compute action yet.
        """
        if action is None:
            return True
        elif action.computation_type == F and action.stage_index != 0:
            if _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_actions:
                return True
            return False
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD) and action.stage_index != num_stages - 1:
            if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_actions:
                return True
            elif <MASK>:
                return True
            return False
        else:
            return True
    while compute_actions:
        progress = False
        for rank in sorted(compute_actions):
            assert len(compute_actions[rank]) > 0, f'rank={rank!r}, len(compute_actions[rank])={len(compute_actions[rank])!r}'
            action = compute_actions[rank][0]
            if action is not None and action.sub_actions is not None:
                all_actions = action.sub_actions
            else:
                all_actions = (action,)
            if not all((_ready_to_schedule(a, prev_actions[rank]) for a in all_actions)):
                continue
            if action is not None:
                comm_actions[rank].append(action)
                for a in all_actions:
                    prev_actions[rank].add(a)
                    if _has_comms(a):
                        (send, recv) = _get_comms(a)
                        comm_actions[rank].append(send)
                        prev_actions[rank].add(send)
                        comm_actions[stage_to_rank(recv.stage_index)].append(recv)
                        prev_actions[stage_to_rank(recv.stage_index)].add(recv)
            compute_actions[rank].pop(0)
            if len(compute_actions[rank]) == 0:
                del compute_actions[rank]
            progress = True
        assert progress, "Malformed compute schedule, can't schedule sends/recvs"
    return comm_actions

@register_lowering_pattern(pattern, extra_check=_is_valid_computation_binary_inplace(computation_op, binary_op, other_index))
def fn(match, *args, **kwargs):
    other = kwargs.get('other')
    assert isinstance(other, ir.TensorBox)
    binary_attr = _binary_attr[binary_op]
    args_list = list(args)
    computation_args = [args_list[0], other] + args_list[1:-3] + [binary_attr]
    if <MASK>:
        if unary_attr is not None:
            computation_args += [1.0, unary_attr.op_name, unary_attr.scalars_attr, unary_attr.algorithm_attr]
        else:
            computation_args += [1.0, None, [], None]
    counters['inductor']['mkldnn_conv_binary_unary_fusion_matcher_count'] += 1
    counters['inductor']['mkldnn_conv_binary_unary_fusion_matcher_nodes'] += len(match.nodes)
    other.realize()
    if not _can_be_inplace(other) or other.data.shape != list(match.nodes[0].meta['val'].size()):
        return L[outplace_fusion_op](*computation_args)
    return L[inplace_fusion_op](*computation_args)

def prepare_value(self, field, value):
    """
        Prepare a value to be used in a query by resolving it if it is an
        expression and otherwise calling the field's get_db_prep_save().
        """
    if <MASK>:
        value = value.resolve_expression(self.query, allow_joins=False, for_save=True)
        if value.contains_column_references:
            raise ValueError('Failed to insert expression "%s" on %s. F() expressions can only be used to update, not to insert.' % (value, field))
        if value.contains_aggregate:
            raise FieldError('Aggregate functions are not allowed in this query (%s=%r).' % (field.name, value))
        if value.contains_over_clause:
            raise FieldError('Window expressions are not allowed in this query (%s=%r).' % (field.name, value))
    return field.get_db_prep_save(value, connection=self.connection)

def as_postgresql(self, compiler, connection, **extra_context):
    clone = self.copy()
