    elif <MASK>:
        function = connection.ops.spatial_function_name('LengthSpheroid')
        clone.source_expressions.append(Value(self.geo_field.spheroid(connection)))
    else:
        dim = min((f.dim for f in self.get_source_fields() if f))
        if dim > 2:
            function = connection.ops.length3d
    return super(Length, clone).as_sql(compiler, connection, function=function, **extra_context)

def convert_to_eager_tensor(value, ctx, dtype=None) -> ops._EagerTensorBase:
    """Converts the given `value` to an `EagerTensor`.

  Note that this function could return cached copies of created constants for
  performance reasons.

  Args:
    value: value to convert to EagerTensor.
    ctx: value of context.context().
    dtype: optional desired dtype of the converted EagerTensor.

  Returns:
    EagerTensor created from value.

  Raises:
    TypeError: if `dtype` is not compatible with the type of t.
  """
    if isinstance(value, np.ndarray):
        value = value.copy()
    if isinstance(value, ops.EagerTensor):
        if dtype is not None and value.dtype != dtype:
            raise TypeError(f'Expected tensor {value} with dtype {dtype!r}, but got dtype {value.dtype!r}.')
        return value
    if <MASK>:
        try:
            dtype = dtype.as_datatype_enum
        except AttributeError:
            dtype = dtypes.as_dtype(dtype).as_datatype_enum
    ctx.ensure_initialized()
    return ops.EagerTensor(value, ctx.device_name, dtype)

def _checknames(descr, names=None):
    """
    Checks that field names ``descr`` are not reserved keywords.

    If this is the case, a default 'f%i' is substituted.  If the argument
    `names` is not None, updates the field names to valid names.

    """
    ndescr = len(descr)
    default_names = [f'f{i}' for i in range(ndescr)]
    if names is None:
        new_names = default_names
    else:
        if <MASK>:
            new_names = names
        elif isinstance(names, str):
            new_names = names.split(',')
        else:
            raise NameError(f'illegal input names {names!r}')
        nnames = len(new_names)
        if nnames < ndescr:
            new_names += default_names[nnames:]
    ndescr = []
    for (n, d, t) in zip(new_names, default_names, descr.descr):
        if n in reserved_fields:
            if t[0] in reserved_fields:
                ndescr.append((d, t[1]))
            else:
                ndescr.append(t)
        else:
            ndescr.append((n, t[1]))
    return np.dtype(ndescr)

def test_nested(self):

    def f(x):
        v = []
        u = []
        w = []
        while x > 0:
            x -= 1
            if <MASK>:
                if x % 3 != 0:
                    u.append(x)
                else:
                    w.append(x)
                    continue
            v.append(x)
        return (v, u, w)
    self.assertTransformedEquivalent(f, 0)
    self.assertTransformedEquivalent(f, 1)
    self.assertTransformedEquivalent(f, 3)
    self.assertTransformedEquivalent(f, 4)

def filter_reduction_configs_for_determinism(inductor_meta: dict[str, Any], configs: list[Config]) -> list[Config]:
    """
    Filter configs for reduction so the numerics can be deterministic.

    Heuristics:
    - skip reduction configs with too small RBLOCK
    - skip reduction configs with XBLOCK==1 if we are confident it will not perform well
    - if there is a tie, pick the config with second largest RBLOCK
    - if there is still a tie, pick the config with second largest num_warps
    - if there is still a tie, pick the config with second largest XBLOCK
    """
    configs = unique_configs(configs)
    assert len(configs) > 0

    def _do_filter_due_to_inductor_config():
        return (inductor_meta.get('deterministic', False) or inductor_meta.get('force_filter_reduction_configs', False)) or inductor_meta.get('are_deterministic_algorithms_enabled')
    if not _do_filter_due_to_inductor_config() or len(configs) == 1:
        return configs
    if log.isEnabledFor(logging.DEBUG):
        log.debug('reduction configs before filtering:')
        for c in configs:
            log.debug('%s', c)
            log.debug('')

    def _has_too_small_rblock(config):
        rblock = config.kwargs.get('R0_BLOCK')
        return rblock is not None and rblock <= 4

    def _nonpromising_xblock_1(config):
        return config.kwargs['XBLOCK'] == 1 and (not inductor_meta.get('has_loadstore_with_contiguous_rdim', True))
    newconfigs = [*filter(lambda x: not _has_too_small_rblock(x), configs)]
    if len(newconfigs) > 0:
        configs = newconfigs
    newconfigs = [*filter(lambda x: not _nonpromising_xblock_1(x), configs)]
    if len(newconfigs) > 0:
        configs = newconfigs
    assert len(configs) > 0

    def _r0_block(c):
        return c.kwargs.get('R0_BLOCK', -1)

    def _xblock(c):
        return c.kwargs.get('XBLOCK', -1)

    def _num_warps(c):
        return c.num_warps

    def _pick_second_largest(accessor):
        nonlocal configs
        configs = sorted(configs, key=lambda x: accessor(x))
        if <MASK>:
            max_val = accessor(configs[-1])
            configs = [*filter(lambda x: accessor(x) != max_val, configs)]
            second_max_val = accessor(configs[-1])
            configs = [*filter(lambda x: accessor(x) == second_max_val, configs)]
        return configs

    def _pick_config():
        nonlocal configs
        assert len(configs) > 0
        if len(configs) == 1:
            return configs[0]
        configs = _pick_second_largest(_r0_block)
        if len(configs) == 1:
            return configs[0]
        configs = _pick_second_largest(_num_warps)
        if len(configs) == 1:
            return configs[0]
        configs = _pick_second_largest(_xblock)
        return configs[0]
    configs = [_pick_config()]
    if log.isEnabledFor(logging.DEBUG):
        log.debug('reduction configs after filtering:')
        for c in configs:
            log.debug('%s', c)
            log.debug('')
    return configs

def markDynamoStrictTest(cls_or_func=None, nopython=False):
    """
    Marks the test as 'strict'. In strict mode, we reset before and after the
    test, and run without suppress errors.

    Args:
    - nopython: if we should run torch._dynamo.optimize with nopython={True/False}.
    """

    def decorator(cls_or_func):
        if inspect.isclass(cls_or_func):
            cls_or_func.dynamo_strict = True
            cls_or_func.dynamo_strict_nopython = nopython
            return cls_or_func
        fn = cls_or_func

        @wraps(fn)
        def wrapper(*args, **kwargs):
            torch._dynamo.reset()
            with unittest.mock.patch('torch._dynamo.config.suppress_errors', False):
                fn(*args, **kwargs)
            torch._dynamo.reset()
        return wrapper
    if <MASK>:
        return decorator
    else:
        return decorator(cls_or_func)

def _setitem_with_indexer_frame_value(self, indexer, value: DataFrame, name: str) -> None:
    ilocs = self._ensure_iterable_column_indexer(indexer[1])
    sub_indexer = list(indexer)
    pi = indexer[0]
    multiindex_indexer = isinstance(self.obj.columns, MultiIndex)
    unique_cols = value.columns.is_unique
    if <MASK>:
        for (i, loc) in enumerate(ilocs):
            val = value.iloc[:, i]
            self._setitem_single_column(loc, val, pi)
    elif not unique_cols and value.columns.equals(self.obj.columns):
        for loc in ilocs:
            item = self.obj.columns[loc]
            if item in value:
                sub_indexer[1] = item
                val = self._align_series(tuple(sub_indexer), value.iloc[:, loc], multiindex_indexer)
            else:
                val = np.nan
            self._setitem_single_column(loc, val, pi)
    elif not unique_cols:
        raise ValueError('Setting with non-unique columns is not allowed.')
    else:
        for loc in ilocs:
            item = self.obj.columns[loc]
            if item in value:
                sub_indexer[1] = item
                val = self._align_series(tuple(sub_indexer), value[item], multiindex_indexer, using_cow=True)
            else:
                val = np.nan
            self._setitem_single_column(loc, val, pi)

