def _find_dll_in_winsxs(dll_name):
    winsxs_path = os.path.join(os.environ.get('WINDIR', 'C:\\WINDOWS'), 'winsxs')
    if not os.path.exists(winsxs_path):
        return None
    for (root, dirs, files) in os.walk(winsxs_path):
