def _verify_and_get_subgroup_size(self, group_assignment, num_shards):
    """Verify group_assignment and get the subgroup size".

    Args:
      group_assignment: list of group ids for applying the optimizer
        to subgroups.
      num_shards: The number of TPU shards.

    Returns:
      The size of one subgroup in group_assignment.

    Raises:
      ValueError: If group_assignment is invalid.
    """
    if <MASK>:
        return None
    if not (isinstance(group_assignment, list) and all((isinstance(i, list) for i in group_assignment))):
        raise ValueError(f'Argument `group_assignment` must be a list of lists. Received: {group_assignment}')
    replica_ids = set()
    for g in group_assignment:
        for i in g:
            replica_ids.add(i)
    if set(range(num_shards)) != replica_ids:
        raise ValueError(f'Argument `group_assignment` must be a permutation of range({num_shards}). Received: {group_assignment}')
    subgroup_size_list = [len(group) for group in group_assignment]
    if all((subgroup_size_list[0] == size for size in subgroup_size_list)):
        return subgroup_size_list[0]
    else:
        raise ValueError(f'The size of each subgroup in `group_assignment` must be equal. Received: {group_assignment}')

def input_buffers_require_grads(graph_module, num_score_mod_placeholders: int):
    """Check if any of the input buffers (beyond the score mod placeholders) require gradients."""
    inputs = []
    for node in graph_module.graph.nodes:
        if node.op == 'placeholder':
            inputs.append(node)
    if <MASK>:
        return False

    def requires_grad(n):
        tensor_meta = n.meta.get('tensor_meta')
        return tensor_meta.requires_grad if tensor_meta is not None else False
    return any((requires_grad(n) for n in inputs[num_score_mod_placeholders:]))

@classmethod
def get_compression_type_string(cls, options):
    """Convert various option types to a unified string.

    Args:
      options: `TFRecordOption`, `TFRecordCompressionType`, or string.

    Returns:
      Compression type as string (e.g. `'ZLIB'`, `'GZIP'`, or `''`).

    Raises:
      ValueError: If compression_type is invalid.
    """
    if <MASK>:
        return ''
    elif isinstance(options, TFRecordOptions):
        return cls.get_compression_type_string(options.compression_type)
    elif isinstance(options, TFRecordCompressionType):
        return cls.compression_type_map[options]
    elif options in TFRecordOptions.compression_type_map:
        return cls.compression_type_map[options]
    elif options in TFRecordOptions.compression_type_map.values():
        return options
    else:
        raise ValueError('Not a valid compression_type: "{}"'.format(options))

def emit_node(node: Node):
    maybe_type_annotation = '' if node.type is None else f' : {type_repr(node.type)}'
    maybe_comment = ''
    if verbose:
        from torch.fx.experimental.proxy_tensor import py_sym_types
        from torch.fx.passes.shape_prop import TensorMetadata
        meta_val = node.meta.get('val', node.meta.get('tensor_meta', node.meta.get('example_value', None)))

        def _tensor_annotation(t: torch.Tensor) -> str:
            stride = stringify_shape(t.stride()) if include_stride else ''
            device = f'{t.device}' if include_device else ''
            return f'{red(dtype_abbrs[t.dtype])}{blue(stringify_shape(t.shape))}{dim_blue(stride)}{dim_green(device)}'
        if isinstance(meta_val, torch.Tensor) and meta_val.layout not in (torch.sparse_csc, torch.sparse_csr):
            is_plain = type(meta_val) is torch.Tensor or isinstance(meta_val, torch._subclasses.FakeTensor)
            core = _tensor_annotation(meta_val)
            if is_plain:
                maybe_type_annotation = f': "{core}"'
            else:
                cls = meta_val.__class__.__name__
                maybe_type_annotation = f': "{cls}({core})"'
        elif isinstance(meta_val, py_sym_types):
            val_str = CodeGen._sym_repr(meta_val)
            maybe_type_annotation = f': "Sym({val_str})"'
        elif isinstance(meta_val, TensorMetadata):
            maybe_type_annotation = f': "{dtype_abbrs[meta_val.dtype]}{stringify_shape(meta_val.shape)}"'
    desc = None
    if expanded_def:
        desc = node.meta.get('desc', None)
        if <MASK>:
            maybe_comment += f'  # {desc}'
    if node.op == 'placeholder':
        assert isinstance(node.target, str)
        maybe_default_arg = '' if not node.args else f' = {_get_repr(node.args[0])}'
        free_vars.append(f'{node.target}{maybe_type_annotation}{maybe_default_arg}{maybe_comment}')
        raw_name = node.target.replace('*', '')
        if raw_name != repr(node):
            body.append(f'{repr(node)} = {raw_name}\n')
        return
    elif node.op == 'call_method':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.target)}({_format_args(node.args[1:], node.kwargs)})')
        return
    elif node.op == 'call_function':
        assert callable(node.target)
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in magic_methods:
            assert isinstance(node.args, tuple)
            body.append(f'{repr(node)}{maybe_type_annotation} = {magic_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))}')
            return
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in inplace_methods:
            body.append(f'{inplace_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))};  {repr(node)}{maybe_type_annotation} = {_get_repr(node.args[0])}')
            return
        qualified_name = _get_qualified_name(node.target)
        global_name = add_global(qualified_name, node.target)
        if global_name == 'getattr' and isinstance(node.args, tuple) and isinstance(node.args[1], str) and node.args[1].isidentifier() and (len(node.args) == 2):
            body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.args[1])}')
            return
        body.append(f'{repr(node)}{maybe_type_annotation} = {global_name}({_format_args(node.args, node.kwargs)})')
        if node.meta.get('is_wrapped', False):
            wrapped_fns.setdefault(global_name)
        return
    elif node.op == 'call_module':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}({_format_args(node.args, node.kwargs)})')
        return
    elif node.op == 'get_attr':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}')
        return
    elif node.op == 'output':
        if node.type is not None:
            maybe_return_annotation[0] = f' -> {type_repr(node.type)}'
        body.append(self._call_method_with_signature_check(self.generate_output, node.args[0], descs=desc if expanded_def else None))
        return
    raise NotImplementedError(f'node: {node.op} {node.target}')

def find_state_dict_object(state_dict: STATE_DICT_TYPE, index: MetadataIndex) -> Any:
    if index.fqn not in state_dict:
        raise ValueError(f"Could not find FQN: '{index.fqn}'")
    obj = state_dict[index.fqn]
    if isinstance(obj, torch.Tensor):
        return find_tensor_shard(obj, index)
    elif <MASK>:
        raise ValueError(f"FQN: '{index.fqn}' is not a ShardedTensor, can't find by offset: '{index.offset}'")
    return obj

def synchronize(device: str='cuda') -> None:
    if device == 'cpu':
        return
    device_interface = get_interface_for_device(device)
    if <MASK>:
        device_interface.synchronize()

def __post_init__(self) -> None:
    if self.func.arguments.out:
        assert self.variants == {Variant.function}, 'Native functions with out arguments MUST be declared with only function variant; e.g., variants: function; otherwise you will tickle a Python argument binding bug (which usually manifests itself as the result variable being undefined.)'
    if self.structured:
        assert self.func.kind() == SchemaKind.out, 'Put structured field on the out= variant of a function; did you mean structured_delegate?'
        assert self.device_guard, 'device_guard: False is not respected by structured kernels'
    if <MASK>:
        assert self.func.kind() != SchemaKind.out, 'structured_delegate field not allowed on out= functions; did you mean structured?'
        assert self.device_guard, 'device_guard: False is not respected by structured kernels'
    assert not (self.structured and self.structured_delegate), 'Cannot have both structured and structured_delegate on function'
    defaulted_arguments = {a.name for a in self.func.schema_order_arguments() if a.default is not None}
    invalid_args = set.difference(self.cpp_no_default_args, defaulted_arguments)
    assert len(invalid_args) == 0, f'Invalid cpp_no_default_args: {invalid_args}'
    if self.structured_inherits is not None:
        assert self.structured, 'structured_inherits must also imply structured: True'
    if str(self.func.name).startswith('_foreach'):
        assert self.device_check == DeviceCheckType.NoCheck, 'foreach kernels fall back to slow path when tensor are on different devices, device_check not allowed to be enabled'
    if 'rand' in str(self.func.name) or (('dropout' in str(self.func.name) or any(('dropout' in arg.name for arg in self.func.arguments.flat_all))) and 'backward' not in str(self.func.name) and (str(self.func.name.name) not in ['_cudnn_init_dropout_state'])) or self.func.arguments.has_generator_arg():
        assert 'nondeterministic_seeded' in self.tags, str(self.func.name)

def deconstruct(self):
    (name, path, args, kwargs) = super().deconstruct()
    if self.width_field:
        kwargs['width_field'] = self.width_field
    if <MASK>:
        kwargs['height_field'] = self.height_field
    return (name, path, args, kwargs)

def __call__(self, X, Y=None, eval_gradient=False):
    """Return the kernel k(X, Y) and optionally its gradient.

        Parameters
        ----------
        X : ndarray of shape (n_samples_X, n_features)
            Left argument of the returned kernel k(X, Y)

        Y : ndarray of shape (n_samples_Y, n_features), default=None
            Right argument of the returned kernel k(X, Y). If None, k(X, X)
            if evaluated instead.

        eval_gradient : bool, default=False
            Determines whether the gradient with respect to the log of
            the kernel hyperparameter is computed.
            Only supported when Y is None.

        Returns
        -------
        K : ndarray of shape (n_samples_X, n_samples_Y)
            Kernel k(X, Y)

        K_gradient : ndarray of shape (n_samples_X, n_samples_X, n_dims),                optional
            The gradient of the kernel k(X, X) with respect to the log of the
            hyperparameter of the kernel. Only returned when `eval_gradient`
            is True.
        """
    pairwise_kernels_kwargs = self.pairwise_kernels_kwargs
    if self.pairwise_kernels_kwargs is None:
        pairwise_kernels_kwargs = {}
    X = np.atleast_2d(X)
    K = pairwise_kernels(X, Y, metric=self.metric, gamma=self.gamma, filter_params=True, **pairwise_kernels_kwargs)
    if eval_gradient:
        if <MASK>:
            return (K, np.empty((X.shape[0], X.shape[0], 0)))
        else:

            def f(gamma):
                return pairwise_kernels(X, Y, metric=self.metric, gamma=np.exp(gamma), filter_params=True, **pairwise_kernels_kwargs)
            return (K, _approx_fprime(self.theta, f, 1e-10))
    else:
        return K

def pprint_thing(thing: object, _nest_lvl: int=0, escape_chars: EscapeChars | None=None, default_escapes: bool=False, quote_strings: bool=False, max_seq_items: int | None=None) -> str:
    """
    This function is the sanctioned way of converting objects
    to a string representation and properly handles nested sequences.

    Parameters
    ----------
    thing : anything to be formatted
    _nest_lvl : internal use only. pprint_thing() is mutually-recursive
        with pprint_sequence, this argument is used to keep track of the
        current nesting level, and limit it.
    escape_chars : list[str] or Mapping[str, str], optional
        Characters to escape. If a Mapping is passed the values are the
        replacements
    default_escapes : bool, default False
        Whether the input escape characters replaces or adds to the defaults
    max_seq_items : int or None, default None
        Pass through to other pretty printers to limit sequence printing

    Returns
    -------
    str
    """

    def as_escaped_string(thing: Any, escape_chars: EscapeChars | None=escape_chars) -> str:
        translate = {'\t': '\\t', '\n': '\\n', '\r': '\\r', "'": "\\'"}
        if isinstance(escape_chars, Mapping):
            if default_escapes:
                translate.update(escape_chars)
            else:
                translate = escape_chars
            escape_chars = list(escape_chars.keys())
        else:
            escape_chars = escape_chars or ()
        result = str(thing)
        for c in escape_chars:
            result = result.replace(c, translate[c])
        return result
    if hasattr(thing, '__next__'):
        return str(thing)
    elif <MASK>:
        result = _pprint_dict(thing, _nest_lvl, quote_strings=True, max_seq_items=max_seq_items)
    elif is_sequence(thing) and _nest_lvl < get_option('display.pprint_nest_depth'):
        result = _pprint_seq(thing, _nest_lvl, escape_chars=escape_chars, quote_strings=quote_strings, max_seq_items=max_seq_items)
    elif isinstance(thing, str) and quote_strings:
        result = f"'{as_escaped_string(thing)}'"
    else:
        result = as_escaped_string(thing)
    return result

def sort_values(self, *, return_indexer: bool=False, ascending: bool=True, na_position: NaPosition='last', key: Callable | None=None) -> Self | tuple[Self, np.ndarray | RangeIndex]:
    if key is not None:
        return super().sort_values(return_indexer=return_indexer, ascending=ascending, na_position=na_position, key=key)
    else:
        sorted_index = self
        inverse_indexer = False
        if ascending:
            if self.step < 0:
                sorted_index = self[::-1]
                inverse_indexer = True
        elif self.step > 0:
            sorted_index = self[::-1]
            inverse_indexer = True
    if return_indexer:
        if <MASK>:
            rng = range(len(self) - 1, -1, -1)
        else:
            rng = range(len(self))
        return (sorted_index, RangeIndex(rng))
    else:
        return sorted_index

@deprecation.deprecated(date=None, instructions=_DEPRECATION_MSG)
@tf_export(v1=['graph_util.must_run_on_cpu'])
def must_run_on_cpu(node, pin_variables_on_cpu=False):
    """Returns True if the given node_def must run on CPU, otherwise False.

  Args:
    node: The node to be assigned to a device. Could be either an ops.Operation
      or NodeDef.
    pin_variables_on_cpu: If True, this function will return False if node_def
      represents a variable-related op.

  Returns:
    True if the given node must run on CPU, otherwise False.
  """
    if isinstance(node, ops.Operation):
        node_def = node.node_def
    else:
        assert isinstance(node, node_def_pb2.NodeDef)
        node_def = node
    if pin_variables_on_cpu and _is_variable_op(node_def.op):
        return True
    if node_def.op == 'Const':
        dtype = node_def.attr['dtype'].type
        if <MASK>:
            return True
    if node_def.op in ['DynamicStitch', 'ParallelDynamicStitch']:
        dtype = node_def.attr['T'].type
        if dtype == dtypes.int32:
            return True
    if node_def.op in ['Cast']:
        dtype = node_def.attr['SrcT'].type
        if dtype == dtypes.int32:
            return True
    return False

def astype(self, dtype, copy: bool=True):
    dtype = pandas_dtype(dtype)
    if dtype == self.dtype:
        if <MASK>:
            return self.copy()
        return self
    result = astype_array(self._ndarray, dtype=dtype, copy=copy)
    return result

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    (inner_fn, source) = self._resolved_getattr_and_source(self, name)
    if <MASK>:
        return LambdaVariable(identity)
    elif inner_fn is torch.nn.Module.__init__:
        objvar = self.objvar
        from ..side_effects import AttributeMutationNew
        if isinstance(objvar, variables.UserDefinedObjectVariable) and isinstance(objvar.mutation_type, AttributeMutationNew) and (not (args or kwargs)):
            with do_not_convert_to_tracable_parameter():
                return variables.UserFunctionVariable(unpatched_nn_module_init, source=source).call_function(tx, [self.objvar] + args, kwargs)
        else:
            unimplemented_v2(gb_type='Unsupported super().__init__() call', context=f'call_method {self} {name} {args} {kwargs}', explanation=f'Dynamo encountered a super().__init__() call on {objvar} that resolved to a `torch.nn.Module.__init__()` call that we cannot trace.', hints=[*graph_break_hints.DIFFICULT])
    elif self.objvar.source and hasattr(inner_fn, '__name__') and (inner_fn.__name__ == '__new__') and variables.UserDefinedClassVariable.is_supported_new_method(inner_fn):
        user_cls = inner_fn.__self__
        if hasattr(user_cls, '__module__') and user_cls.__module__ == 'builtins':
            user_cls_vt = variables.BuiltinVariable(user_cls)
        else:
            user_cls_source = source.member
            user_cls_vt = variables.UserDefinedClassVariable(user_cls, source=user_cls_source)
        return user_cls_vt.call_method(tx, '__new__', args, kwargs)
    elif isinstance(inner_fn, staticmethod) and isinstance(inner_fn.__func__, types.FunctionType):
        return variables.UserFunctionVariable(inner_fn.__func__, source=source).call_function(tx, args, kwargs)
    elif isinstance(inner_fn, classmethod) and isinstance(inner_fn.__func__, types.FunctionType):
        if isinstance(self.objvar, variables.UserDefinedClassVariable):
            cls_variable = self.objvar
        else:
            cls_source = None
            if self.objvar.source:
                cls_source = TypeSource(self.objvar.source)
            cls_variable = VariableTracker.build(tx, self.objvar.value_type, cls_source)
        return variables.UserFunctionVariable(inner_fn.__func__, source=AttrSource(source, '__func__')).call_function(tx, [cls_variable, *args], kwargs)
    elif isinstance(inner_fn, types.FunctionType):
        return variables.UserFunctionVariable(inner_fn, source=source).call_function(tx, [self.objvar] + args, kwargs)
    elif isinstance(inner_fn, types.MethodType):
        return variables.UserMethodVariable(inner_fn.__func__, self.objvar, source=source).call_function(tx, args, kwargs)
    elif is_standard_setattr(inner_fn) and isinstance(self.objvar, UserDefinedObjectVariable):
        return self.objvar.method_setattr_standard(tx, *args, **kwargs)
    elif inner_fn is object.__delattr__:
        attr = args[0]
        try:
            attr = attr.as_python_constant()
        except NotImplementedError as exc:
            unimplemented_v2(gb_type='Non-constant attribute given to `super().__delattr__()`', context=f'call_method {self} {name}', explanation='Dynamo requires the attribute name passed to `super().__delattr__(...)` to be a constant (string).', hints=['Ensure the attribute name is a string literal or a constant variable.'], from_exc=exc)
        if not tx.output.side_effects.is_attribute_mutation(self.objvar):
            unimplemented_v2(gb_type='Attempted super().__delattr__() on an object without mutation tracking', context=f'call_method {self} {name}', explanation=f"Dynamo needs to track mutations on an object before `super().__delattr__` can be used on it. But the object ({self.objvar}) doesn't have attribute mutation tracking enabled.", hints=["Ensure the object is tracked by Dynamo's side effect system.", *graph_break_hints.DYNAMO_BUG])
        tx.output.side_effects.store_attr(self.objvar, attr, variables.DeletedVariable())
        return variables.ConstantVariable(None)
    elif isinstance(self.objvar, variables.UserDefinedDictVariable) and inner_fn in self.objvar._dict_methods:
        return self.objvar._dict_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedSetVariable) and inner_fn in self.objvar._set_methods:
        return self.objvar._set_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedTupleVariable) and inner_fn in tuple_methods:
        return self.objvar._tuple_vt.call_method(tx, name, args, kwargs)
    elif isinstance(self.objvar, variables.UserDefinedListVariable) and inner_fn in list_methods:
        return self.objvar._list_vt.call_method(tx, name, args, kwargs)
    elif inner_fn is object.__getattribute__:
        attr_name = args[0].value
        if tx.output.side_effects.has_pending_mutation_of_attr(self.objvar, attr_name):
            result = tx.output.side_effects.load_attr(self.objvar, attr_name, deleted_ok=True)
            if isinstance(result, variables.DeletedVariable):
                raise_observed_exception(AttributeError, tx)
            return result
        try:
            attr_value = object.__getattribute__(self.objvar.value, attr_name)
        except AttributeError:
            raise_observed_exception(AttributeError, tx)
        attr_source = None
        if self.objvar.source is not None:
            attr_source = GenericAttrSource(self.objvar.source, attr_name)
        return VariableTracker.build(tx, attr_value, attr_source)
    elif inner_fn is torch._C._disabled_torch_function_impl:
        func = args[0]
        tf_kwargs = {}
        tf_args = args[2].items
        for (hash_key_vt, value_vt) in args[3].items.items():
            key_str = hash_key_vt.vt.as_python_constant()
            tf_kwargs[key_str] = value_vt
        tx_old = tx.symbolic_torch_function_state.torch_function_subclass_enabled
        tx.symbolic_torch_function_state.torch_function_subclass_enabled = False
        try:
            return func.call_function(tx, tf_args, tf_kwargs)
        finally:
            tx.symbolic_torch_function_state.torch_function_subclass_enabled = tx_old
    elif isinstance(inner_fn, types.MethodDescriptorType) and inner_fn in trace_rules.get_tensor_method():
        fn_var = VariableTracker.build(tx, inner_fn, source)
        return fn_var.call_function(tx, [self.objvar] + args, kwargs)
    unimplemented_v2(gb_type='Attempted to call a super() attribute that is not a function or method', context=f'call_method {self} {name}', explanation=f'Dynamo does not know how to trace the call `super().{name}()` because `super().{name}` is not a function or method attribute.', hints=['Ensure the attribute accessed via `super()` is a standard method or function.'])

def codegen_inputs(self):
    if config.is_fbcode():
        return super().codegen_inputs()
    if <MASK>:
        for idx in V.graph.inputs_to_check:
            input_name = V.graph.graph_input_names[idx]
            assert input_name in V.graph.graph_inputs, f'{input_name} not found in graph inputs'
            value = V.graph.graph_inputs[input_name]
            assert isinstance(value, TensorBox), f'{input_name} is expected to be tensor but found as {type(value)}'
            warn_msg = f'Input {idx} was compiled as {GPU_ALIGN_BYTES}-bytes aligned, but it is not aligned at run time. Copying to an aligned tensor to guarantee correctness, but expect a performance hit.'
            self.prefix.splice(f'\n                    if ((reinterpret_cast<std::uintptr_t>({input_name}.data_ptr()) & ({GPU_ALIGN_BYTES} -1)) != 0) {{\n                        AOTI_TORCH_WARN("{warn_msg}");\n                        AtenTensorHandle {input_name}_aligned;\n                        aoti_torch_clone_preserve_strides({input_name}, &{input_name}_aligned);\n                        {input_name} = std::move(RAIIAtenTensorHandle({input_name}_aligned));\n                    }}\n                    ')
    super().codegen_inputs()

def _inner(match):
    conv_node = match.output_node()
    assert conv_node.target is aten.convolution.default
    input_meta_value = conv_node.args[0].meta.get('val')
    weight_meta_value = conv_node.args[1].meta.get('val')
    for meta_value in [input_meta_value, weight_meta_value]:
        if meta_value is None or (meta_value.device.type != 'cpu' and meta_value.device.type != 'xpu') or meta_value.dim() not in [3, 4]:
            return False
    assert dtype in [torch.float32, torch.bfloat16]
    if <MASK>:
        dequant_node = conv_node.args[0]
    else:
        convert_to_bf16 = conv_node.args[0]
        dequant_node = convert_to_bf16.args[0]
    if len(list(dequant_node.users)) != 1:
        return False
    return True

def _get_greedy_order_meta(self, sac_stats: SACStats) -> SACGreedyOrderMeta:
    inplace_op_groups: dict[int, set[int]] = {}
    inplace_op_to_group_head: dict[int, int] = dict(sac_stats.inplace_ops)
    for (op_idx, group_head_idx) in inplace_op_to_group_head.items():
        op_group = inplace_op_groups.setdefault(group_head_idx, {group_head_idx})
        op_group.add(op_idx)
    random_ops_group: dict[int, set[int]] = {}
    random_group_head_idx = min(sac_stats.rand_ops, default=-1)
    has_rand_ops = bool(sac_stats.rand_ops)
    if has_rand_ops:
        random_ops_group[random_group_head_idx] = set(sac_stats.rand_ops)
    stored_ops: set[int] = set()
    recomputed_ops: set[int] = set()
    if has_rand_ops and sac_stats.force_store_random:
        stored_ops.add(random_group_head_idx)
    recomputed_ops.update(set(sac_stats.view_like_ops))
    for (group_head_idx, op_group) in inplace_op_groups.items():
        if group_head_idx in inplace_op_to_group_head:
            stored_ops.add(group_head_idx)
        if sac_stats.force_store_random & len(op_group & set(sac_stats.rand_ops)) > 0:
            stored_ops.add(group_head_idx)
    recompute_candidates: set[int] = set()
    if <MASK>:
        recompute_candidates.add(random_group_head_idx)
    recompute_candidates.update(set(inplace_op_groups.keys()) - stored_ops)
    recompute_candidates.update(set(range(len(sac_stats.memory))) - recomputed_ops - stored_ops - set(inplace_op_to_group_head.keys()) - set(sac_stats.rand_ops))
    msps_meta: list[MSPS] = []
    for cand_idx in recompute_candidates:
        op_indices = {cand_idx}
        if cand_idx in inplace_op_groups:
            op_indices.update(inplace_op_groups[cand_idx])
        if has_rand_ops and cand_idx == random_group_head_idx:
            op_indices.update(sac_stats.rand_ops)
        mem = sum((sac_stats.memory[op_idx] for op_idx in op_indices))
        runtime = sum((sac_stats.runtimes[op_idx] for op_idx in op_indices))
        func_names = {sac_stats.func_names[op_idx] for op_idx in op_indices}
        msps = mem / runtime if runtime > 0 else sys.float_info.max
        msps_meta.append(MSPS(func_names, cand_idx, mem, runtime, msps))
    msps_meta.sort(key=lambda x: x.msps, reverse=True)
    return SACGreedyOrderMeta(recomputed_ops, stored_ops, inplace_op_groups, random_ops_group, msps_meta)

def revive_custom_object(identifier, metadata):
    """Revives object from SavedModel."""
    if <MASK>:
        model_class = training_lib.Model
    else:
        model_class = training_lib_v1.Model
    revived_classes = {constants.INPUT_LAYER_IDENTIFIER: (RevivedInputLayer, input_layer.InputLayer), constants.LAYER_IDENTIFIER: (RevivedLayer, base_layer.Layer), constants.MODEL_IDENTIFIER: (RevivedNetwork, model_class), constants.NETWORK_IDENTIFIER: (RevivedNetwork, functional_lib.Functional), constants.SEQUENTIAL_IDENTIFIER: (RevivedNetwork, models_lib.Sequential)}
    parent_classes = revived_classes.get(identifier, None)
    if parent_classes is not None:
        parent_classes = revived_classes[identifier]
        revived_cls = type(compat.as_str(metadata['class_name']), parent_classes, {})
        return revived_cls._init_from_metadata(metadata)
    else:
        raise ValueError('Unable to restore custom object of type {} currently. Please make sure that the layer implements `get_config`and `from_config` when saving. In addition, please use the `custom_objects` arg when calling `load_model()`.'.format(identifier))

def saved_variables(formula: str, nctypes: list[NamedCType], var_names: tuple[str, ...]) -> tuple[str, tuple[SavedAttribute, ...]]:

    def stride_expr(name: str) -> str:
        assert var_names == (name,), 'Replacement for ".strides()" is currently only supported for single derivatives of the same tensor that ".strides()" is being called on.'
        return f'strides_or_error({name}, "{name}")'
    REPLACEMENTS: list[tuple[str, dict[str, Any]]] = [('{}.sym_sizes\\(\\)', {'suffix': '_sym_sizes', 'nctype': lambda name: NamedCType(name, BaseCType(symIntArrayRefT))}), ('{}->sym_sizes\\(\\)', {'suffix': '_sym_sizes_opt', 'nctype': lambda name: NamedCType(name, OptionalCType(BaseCType(symIntArrayRefT))), 'expr': lambda name: f'{name}.has_value() ? std::optional<c10::SymIntArrayRef>({name}->sym_sizes()) : std::nullopt'}), ('{}.sym_blocksize\\(\\)', {'suffix': '_self_sym_blocksize_opt', 'nctype': lambda name: NamedCType(name, OptionalCType(BaseCType(symIntArrayRefT))), 'expr': lambda name: f'at::sparse_csr::getSymIntBlockSize({name})'}), ('{}.options\\(\\)', {'suffix': '_options', 'nctype': lambda name: NamedCType(name, BaseCType(tensorOptionsT))}), ('zeros_like\\({}\\)', {'suffix': '_info', 'nctype': lambda name: NamedCType(name, BaseCType(typeAndSizeT)), 'expr': lambda name: name, 'res': lambda name: name + '_info.zeros()'}), ('{}.sym_size\\((-?\\w+)\\)', {'suffix': lambda m: f"_sym_argsize_{m.groups()[0].replace('-', 'minus_')}", 'nctype': lambda name: NamedCType(name, BaseCType(SymIntT))}), ('{}.numel\\(\\)', {'suffix': '_numel', 'nctype': lambda name: NamedCType(name, BaseCType(longT))}), ('{}.sym_numel\\(\\)', {'suffix': '_sym_numel', 'nctype': lambda name: NamedCType(name, BaseCType(SymIntT))}), ('to_args_sizes\\({}\\)', {'suffix': '_args_sizes', 'nctype': lambda name: NamedCType(name, VectorCType(VectorCType(BaseCType(longT))))}), ('to_args_sizes_symint\\({}\\)', {'suffix': '_args_sizes_symint', 'nctype': lambda name: NamedCType(name, VectorCType(VectorCType(BaseCType(SymIntT))))}), ('to_args_scalartypes\\({}\\)', {'suffix': '_args_scalartypes', 'nctype': lambda name: NamedCType(name, VectorCType(BaseCType(scalarTypeT)))}), ('TensorGeometry\\({}\\)', {'suffix': '_geometry', 'nctype': lambda name: NamedCType(name, BaseCType(tensorGeometryT))}), ('{}.scalar_type\\(\\)', {'suffix': '_scalar_type', 'nctype': lambda name: NamedCType(name, BaseCType(scalarTypeT))}), ('{}.dim\\(\\)', {'suffix': '_dim', 'nctype': lambda name: NamedCType(name, BaseCType(longT))}), ('{}.sym_strides\\(\\)', {'suffix': '_sym_strides', 'nctype': lambda name: NamedCType(name, BaseCType(symIntArrayRefT)), 'expr': stride_expr}), ('{}.layout\\(\\)', {'suffix': '_layout', 'nctype': lambda name: NamedCType(name, BaseCType(layoutT))}), ('{}.is_conj\\(\\)', {'suffix': '_conjugate', 'nctype': lambda name: NamedCType(name, BaseCType(boolT))})]
    saved: list[SavedAttribute] = []
    if <MASK>:
        raise RuntimeError('.sizes() is not supported in derivative formulas. Instead, please use the SymInt version,' + f'.sym_sizes(), which returned a c10::SymIntArrayRef. formula={formula}')
    if re.search('\\.size\\([-]?\\d+\\)', formula) or re.search('->size\\([-]?\\d+\\)', formula):
        raise RuntimeError('.size(int) is not supported in derivative formulas. Instead, please use the SymInt version,' + f'.sym_size(int), which returned a c10::SymIntArrayRef. formula={formula}')
    if '.strides()' in formula or '->strides()' in formula:
        raise RuntimeError('.strides() is not supported in derivative formulas. Instead, please use the SymInt version,' + f'.sym_strides(), which returned a c10::SymIntArrayRef. formula={formula}')
    for nctype in nctypes:
        name = nctype.name.name if isinstance(nctype.name, SpecialArgName) else nctype.name
        for (regex, info) in REPLACEMENTS:

            def repl(m: re.Match[str]) -> str:
                suffix: str = info['suffix'](m) if callable(info['suffix']) else info['suffix']
                expr: str = info['expr'](name) if 'expr' in info else m.group(0)
                saved.append(SavedAttribute(nctype=info['nctype'](name + suffix), expr=expr))
                if 'res' in info:
                    replacement: str = info['res'](name)
                    return replacement
                return name + suffix
            formula = re.sub(regex.format(name), repl, formula)
        if nctype.type == OptionalCType(BaseCType(stringT)):
            formula = re.sub(f'\\b{name}\\b', f'{name}.has_value() ? std::optional<std::string_view>({name}.value()) : std::nullopt', formula)
        if re.search(IDENT_REGEX.format(name), formula):
            saved.append(SavedAttribute(nctype=nctype, expr=name))
    return (formula, tuple(saved))

def _call_arg_was_passed(self, arg_name, args, kwargs, inputs_in_args=False):
    if <MASK>:
        return True
    call_fn_args = self._call_fn_args
    if not inputs_in_args:
        call_fn_args = call_fn_args[1:]
    if arg_name in dict(zip(call_fn_args, args)):
        return True
    return False

@dist_init(setup_rpc=False)
def test_dynamic_rpc_existing_rank_can_communicate_with_new_rank(self):
    initialize_pg(self.file_init_method, self.rank, self.world_size)
    if <MASK>:
        rpc.init_rpc(name=worker_name(self.rank), backend=self.rpc_backend, rank=self.rank, rpc_backend_options=self.rpc_backend_options)
    dist.barrier()
    if self.rank != 0:
        rpc.init_rpc(name=worker_name(self.rank), backend=self.rpc_backend, rank=self.rank, rpc_backend_options=self.rpc_backend_options)
    dist.barrier()
    if self.rank == 0:
        for i in range(1, self.world_size):
            result = rpc.rpc_sync(worker_name(i), torch.add, args=(torch.tensor(1), torch.tensor(1)))
            self.assertEqual(torch.add(torch.tensor(1), torch.tensor(1)), result)
    dist.barrier()
    rpc.shutdown()

def sample_inputs_baddbmm(op_info, device, dtype, requires_grad, **kwargs):
    test_cases = [((S, S, M), (S, S, S), (S, S, M), 1, 1, False), ((1,), (S, S, S), (S, S, M), 1, 1, True), ((S, S, M), (S, S, S), (S, S, M), 0.6, 0.2, False), ((1,), (S, S, S), (S, S, M), 0.6, 0.2, True), ((), (S, S, S), (S, S, M), 1, 1, True), ((), (S, S, S), (S, S, M), 0.6, 0.2, True)]
    make_arg = partial(make_tensor, device=device, dtype=dtype, requires_grad=requires_grad, low=None, high=None)
    for (input_shape, batch1_shape, batch2_shape, alpha, beta, broadcasts_input) in test_cases:
        yield SampleInput(make_arg(input_shape), make_arg(batch1_shape), make_arg(batch2_shape), beta=beta, alpha=alpha).with_metadata(broadcasts_input=broadcasts_input)
        if <MASK>:
            yield SampleInput(make_arg(input_shape), make_arg(batch1_shape), make_arg(batch2_shape), beta=beta * (1 + 2j), alpha=alpha * (2 + 3j)).with_metadata(broadcasts_input=broadcasts_input)
    if dtype.is_complex:
        shapes = [(S, S, S), (S, M, S), (S, S, M)]
        args = tuple((make_arg(s) for s in shapes))
        yield SampleInput(args[0].transpose_(-1, 1), args[1].transpose(-1, 1).conj().requires_grad_(requires_grad), args[2].transpose(-1, 1).conj().requires_grad_(requires_grad), beta=beta * (1 + 2j), alpha=alpha * (2 + 3j))

def _tag_nodes(self, selected_nodes: NodeSet):
    """
        Tag selected nodes with tag "minimize". Nodes with the same tags will
        be split to the same submodule afterwards.

        Args:
            selected_nodes: Nodes that we want to minimize. We will tag those nodes
                with "minimize", all preceding nodes with "main_0" and all following
                nodes with "main_1".
        """
    for node in self.module.graph.nodes:
        if <MASK>:
            continue
        if node in selected_nodes:
            node.tag = 'minimize'
        elif any((n.tag in {'minimize', 'main_1'} for n in node.all_input_nodes if n.op in CALLABLE_NODE_OPS)):
            node.tag = 'main_1'
        else:
            node.tag = 'main_0'

def eye(num_rows, num_columns=None, batch_shape=None, dtype=dtypes.float32, name=None):
    """Construct an identity matrix, or a batch of matrices.

  See `linalg_ops.eye`.
  """
    with ops.name_scope(name, default_name='eye', values=[num_rows, num_columns, batch_shape]):
        is_square = num_columns is None
        batch_shape = [] if batch_shape is None else batch_shape
        num_columns = num_rows if num_columns is None else num_columns
        if <MASK>:
            diag_size = math_ops.minimum(num_rows, num_columns)
        else:
            if not isinstance(num_rows, compat.integral_types) or not isinstance(num_columns, compat.integral_types):
                raise TypeError(f'Arguments `num_rows` and `num_columns` must be positive integer values. Received: num_rows={num_rows}, num_columns={num_columns}')
            is_square = num_rows == num_columns
            diag_size = np.minimum(num_rows, num_columns)
        if isinstance(batch_shape, tensor.Tensor) or isinstance(diag_size, tensor.Tensor):
            batch_shape = ops.convert_to_tensor(batch_shape, name='shape', dtype=dtypes.int32)
            diag_shape = array_ops.concat((batch_shape, [diag_size]), axis=0)
            if not is_square:
                shape = array_ops.concat((batch_shape, [num_rows, num_columns]), axis=0)
        else:
            batch_shape = list(batch_shape)
            diag_shape = batch_shape + [diag_size]
            if not is_square:
                shape = batch_shape + [num_rows, num_columns]
        diag_ones = array_ops.ones(diag_shape, dtype=dtype)
        if is_square:
            return array_ops.matrix_diag(diag_ones)
        else:
            zero_matrix = array_ops.zeros(shape, dtype=dtype)
            return array_ops.matrix_set_diag(zero_matrix, diag_ones)

def create_default_global_save_plan(all_plans: list[SavePlan], rewrite_index_hints: bool=True) -> tuple[list[SavePlan], Metadata]:
    """
    Create the global plan and metadata used by DefaultSavePlanner.

    Metadata is produced by concatenating the metadata of all ``WriteItem`` from the supplied plans.

    The only global planning change is to update index hints in all ``MetadataIndex`` objects if
    ``rewrite_index_hints`` is True.
    """
    md: dict[str, STORAGE_TYPES] = {}
    new_plans = []
    for plan in all_plans:
        new_items = []
        for item in plan.items:
            if item.type != WriteItemType.SHARD:
                if item.index.fqn in md:
                    raise AssertionError('item.index.fqn not in md')
            if <MASK>:
                md[item.index.fqn] = BytesStorageMetadata()
                new_items.append(item)
            else:
                if item.tensor_data is None:
                    raise AssertionError('item.tensor_data is not None')
                tensor_md = cast(TensorStorageMetadata, md.setdefault(item.index.fqn, TensorStorageMetadata(properties=item.tensor_data.properties, size=item.tensor_data.size, chunks=[])))
                new_item = item
                if rewrite_index_hints:
                    new_index = dataclasses.replace(item.index, index=len(tensor_md.chunks))
                    new_item = dataclasses.replace(item, index=new_index)
                new_items.append(new_item)
                if item.tensor_data.chunk is None:
                    raise AssertionError(f'\n                    Cannot create MD for tensor without bounds.\n                    FQN: {item.index.fqn}\n                ')
                tensor_md.chunks.append(item.tensor_data.chunk)
        new_plans.append(dataclasses.replace(plan, items=new_items))
    return (new_plans, Metadata(md))

def __new__(cls, freq) -> PeriodDtype:
    """
        Parameters
        ----------
        freq : PeriodDtype, BaseOffset, or string
        """
    if isinstance(freq, PeriodDtype):
        return freq
    if not isinstance(freq, BaseOffset):
        freq = cls._parse_dtype_strict(freq)
    if <MASK>:
        warnings.warn("PeriodDtype[B] is deprecated and will be removed in a future version. Use a DatetimeIndex with freq='B' instead", FutureWarning, stacklevel=find_stack_level())
    try:
        dtype_code = cls._cache_dtypes[freq]
    except KeyError:
        dtype_code = freq._period_dtype_code
        cls._cache_dtypes[freq] = dtype_code
    u = PeriodDtypeBase.__new__(cls, dtype_code, freq.n)
    u._freq = freq
    return u

def decide_fusion_fail_reason(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode, common_buf_names: Union[tuple[str], OrderedSet[str]]) -> str:
    """
        Try to decide reasons why fusion fail due to no shared memory even though
        there are common buffers.
        """
    reasons = {}
    node1_name2dep = {dep.name: dep for dep in node1.read_writes.reads_and_writes()}
    node2_name2dep = {dep.name: dep for dep in node2.read_writes.reads_and_writes()}
    for buf_name in common_buf_names:
        buf = V.graph.get_buffer(buf_name)
        lhs_dep = node1_name2dep[buf_name]
        rhs_dep = node2_name2dep[buf_name]
        if <MASK>:
            reasons[buf_name] = f'not MemoryDep: {type(lhs_dep)} v.s. {type(rhs_dep)}'
            continue
        if lhs_dep.get_numel() != rhs_dep.get_numel():
            reasons[buf_name] = f'different numel: {lhs_dep.get_numel()} v.s. {rhs_dep.get_numel()}'
            continue
        if sympy_product(lhs_dep.size) != sympy_product(rhs_dep.size):
            reasons[buf_name] = 'broadcast'
            continue
        lhs_off = lhs_dep.get_offset()
        rhs_off = rhs_dep.get_offset()
        if lhs_off != rhs_off:
            reasons[buf_name] = f'different offset: {lhs_off} v.s. {rhs_off}'
            continue
        if lhs_dep.normalize_with_stride_order() == rhs_dep.normalize_with_stride_order():
            reasons[buf_name] = f'Mismatch loop orders: {lhs_dep} v.s. {rhs_dep}'
            continue
        layout_str = ''
        if not isinstance(buf, ir.TorchBindObject):
            layout_str = f'Layout: {buf.layout}'
        reasons[buf_name] = f'Unknown reason: {lhs_dep} v.s. {rhs_dep}. {layout_str}'
    return str(reasons)

def _parse_config_to_function(config, custom_objects, func_attr_name, func_type_attr_name, module_attr_name):
    """Reconstruct the function from the config."""
    globs = globals()
    module = config.pop(module_attr_name, None)
    if module in sys.modules:
        globs.update(sys.modules[module].__dict__)
    elif module is not None:
        warnings.warn('{} is not loaded, but a layer uses it. It may cause errors.'.format(module), UserWarning)
    if custom_objects:
        globs.update(custom_objects)
    function_type = config.pop(func_type_attr_name)
    if <MASK>:
        function = generic_utils.deserialize_keras_object(config[func_attr_name], custom_objects=custom_objects, printable_module_name='function in wrapper')
    elif function_type == 'lambda':
        function = generic_utils.func_load(config[func_attr_name], globs=globs)
    else:
        raise TypeError('Unknown function type:', function_type)
    return function

@_onnx_symbolic('aten::squeeze')
def squeeze(g: jit_utils.GraphContext, self, dim=None):
    if dim is None:
        return g.op('Squeeze', self)
    if <MASK>:
        return symbolic_helper._squeeze_helper(g, self, [dim])
    dim = symbolic_helper._get_const(dim, 'i', 'dim')
    input_rank = symbolic_helper._get_tensor_rank(self)
    adjusted_dim = dim
    if input_rank is not None and dim < 0:
        adjusted_dim += input_rank
    dim_size = symbolic_helper._get_tensor_dim_size(self, adjusted_dim)
    if dim < 0 and input_rank is None or dim_size is None:
        dim_constant = g.op('Constant', value_t=torch.tensor([dim]))
        size = symbolic_helper._size_helper(g, self, dim_constant)
        const_one = g.op('Constant', value_t=torch.ones(1, dtype=torch.int64))
        cond = g.op('Equal', size, const_one)
        (if_op, (if_context, else_context), _) = jit_utils.add_op_with_blocks(g, 'If', cond, n_blocks=2)
        squeeze_ = symbolic_helper._squeeze_helper(if_context, self, [dim])
        utils._add_output_to_block(if_context.block, squeeze_)
        identity_ = else_context.op('Identity', self)
        utils._add_output_to_block(else_context.block, identity_)
        return if_op
    dim = adjusted_dim
    if dim_size > 1:
        warnings.warn('This model contains a squeeze operation on dimension ' + str(dim) + '. The size of ' + 'this dimension in the given input is ' + str(dim_size) + '. The model will ' + 'be exported without the squeeze node. If the model is intended to be used with dynamic ' + 'input shapes, please export with dynamic_axes argument.')
        return self
    return symbolic_helper._squeeze_helper(g, self, [dim])

def _fit(self, X):
    """Fit without validation

        Parameters
        ----------
        X : ndarray of shape (n_samples, n_features) or (n_samples, n_samples)
            Training instances to cluster, or distances between instances if
            ``metric='precomputed'``.

        Returns
        -------
        self : object
            Returns the fitted instance.
        """
    memory = check_memory(self.memory)
    if not (self.n_clusters is None) ^ (self.distance_threshold is None):
        raise ValueError('Exactly one of n_clusters and distance_threshold has to be set, and the other needs to be None.')
    if self.distance_threshold is not None and (not self.compute_full_tree):
        raise ValueError('compute_full_tree must be True if distance_threshold is set.')
    if self.linkage == 'ward' and self.metric != 'euclidean':
        raise ValueError(f'{self.metric} was provided as metric. Ward can only work with euclidean distances.')
    tree_builder = _TREE_BUILDERS[self.linkage]
    connectivity = self.connectivity
    if self.connectivity is not None:
        if callable(self.connectivity):
            connectivity = self.connectivity(X)
        connectivity = check_array(connectivity, accept_sparse=['csr', 'coo', 'lil'])
    n_samples = len(X)
    compute_full_tree = self.compute_full_tree
    if self.connectivity is None:
        compute_full_tree = True
    if <MASK>:
        if self.distance_threshold is not None:
            compute_full_tree = True
        else:
            compute_full_tree = self.n_clusters < max(100, 0.02 * n_samples)
    n_clusters = self.n_clusters
    if compute_full_tree:
        n_clusters = None
    kwargs = {}
    if self.linkage != 'ward':
        kwargs['linkage'] = self.linkage
        kwargs['affinity'] = self.metric
    distance_threshold = self.distance_threshold
    return_distance = distance_threshold is not None or self.compute_distances
    out = memory.cache(tree_builder)(X, connectivity=connectivity, n_clusters=n_clusters, return_distance=return_distance, **kwargs)
    (self.children_, self.n_connected_components_, self.n_leaves_, parents) = out[:4]
    if return_distance:
        self.distances_ = out[-1]
    if self.distance_threshold is not None:
        self.n_clusters_ = np.count_nonzero(self.distances_ >= distance_threshold) + 1
    else:
        self.n_clusters_ = self.n_clusters
    if compute_full_tree:
        self.labels_ = _hc_cut(self.n_clusters_, self.children_, self.n_leaves_)
    else:
        labels = _hierarchical.hc_get_heads(parents, copy=False)
        labels = np.copy(labels[:n_samples])
        self.labels_ = np.searchsorted(np.unique(labels), labels)
    return self

def decorator_fn(params, decorator=self.decorator, predicate_fn=self.predicate_fn):
    if <MASK>:
        return [decorator]
    else:
        return []

def _all_gather_tensor(value, axis):
    value = ops.convert_to_tensor(value)
    if value.shape.rank is None:
        value_rank = array_ops.rank(value)
        value_shape = array_ops.shape(value)
    else:
        value_rank = value.shape.rank
        value_shape = value.shape.as_list()
        value_shape_tensor = array_ops.shape(value)
        for i in range(len(value_shape)):
            if <MASK>:
                value_shape[i] = value_shape_tensor[i]
    axis = _make_axis_nonnegative(axis, value_rank)
    if isinstance(value_rank, int):
        replica_broadcast_shape = [1] * (value_rank + 1)
        replica_broadcast_shape[axis] = self.num_replicas_in_sync
    else:
        replica_broadcast_shape = array_ops.where_v2(math_ops.equal(math_ops.range(value_rank + 1), axis), self.num_replicas_in_sync, 1)
    output_shape = self._compute_all_gather_output_shape(value_shape, value_rank, axis)
    if value.dtype in _DTYPES_SUPPORTED_BY_CROSS_REPLICA_SUM:
        replica_id_mask = array_ops.one_hot(self.replica_id_in_sync_group, self.num_replicas_in_sync)
        replica_id_mask = array_ops.reshape(replica_id_mask, replica_broadcast_shape)
        replica_id_mask = math_ops.cast(replica_id_mask, value.dtype)
        gathered_value = array_ops.expand_dims(value, axis) * replica_id_mask
        gathered_value = self.all_reduce(reduce_util.ReduceOp.SUM, gathered_value)
        return array_ops.reshape(gathered_value, output_shape)
    else:
        inputs = array_ops.expand_dims(value, axis=axis)
        inputs = array_ops.tile(inputs, replica_broadcast_shape)
        unordered_output = tpu_ops.all_to_all(inputs, concat_dimension=axis, split_dimension=axis, split_count=self.num_replicas_in_sync)
        concat_replica_id = array_ops.reshape(self.replica_id_in_sync_group, [1])
        concat_replica_id = array_ops.tile(concat_replica_id, [self.num_replicas_in_sync])
        xla_to_replica_context_id = tpu_ops.all_to_all(concat_replica_id, concat_dimension=0, split_dimension=0, split_count=self.num_replicas_in_sync)
        replica_context_to_xla_id = math_ops.argmax(array_ops.one_hot(xla_to_replica_context_id, self.num_replicas_in_sync), axis=0)
        sorted_with_extra_dim = array_ops.gather(unordered_output, replica_context_to_xla_id, axis=axis)
        return array_ops.reshape(sorted_with_extra_dim, output_shape)

def has_internal_changes(self) -> bool:
    checkrun_name = INTERNAL_CHANGES_CHECKRUN_NAME
    if self.get_diff_revision() is None:
        return False
    checks = self.get_checkrun_conclusions()
    if <MASK>:
        return False
    return checks[checkrun_name].status != 'SUCCESS'

def checkGraphModuleNodes(self, graph_module, expected_node=None, expected_node_occurrence=None, expected_node_list=None):
    """Check if GraphModule contains the target node
        Args:
            graph_module: the GraphModule instance we want to check
            expected_node, expected_node_occurrence, expected_node_list:
               see docs for checkGraphModeFxOp
        """
    nodes_in_graph = {}
    node_list = []
    modules = dict(graph_module.named_modules(remove_duplicate=False))
    for node in graph_module.graph.nodes:
        n = None
        if node.op == 'call_function' or node.op == 'call_method':
            n = NodeSpec(node.op, node.target)
        elif node.op == 'call_module':
            n = NodeSpec(node.op, type(modules[node.target]))
        if n is not None:
            node_list.append(n)
            if n in nodes_in_graph:
                nodes_in_graph[n] += 1
            else:
                nodes_in_graph[n] = 1
    if <MASK>:
        self.assertTrue(expected_node in nodes_in_graph, 'node:' + str(expected_node) + ' not found in the graph module')
    if expected_node_occurrence is not None:
        for (expected_node, occurrence) in expected_node_occurrence.items():
            if occurrence != 0:
                self.assertTrue(expected_node in nodes_in_graph, 'Check failed for node:' + str(expected_node) + ' not found')
                self.assertTrue(nodes_in_graph[expected_node] == occurrence, 'Check failed for node:' + str(expected_node) + ' Expected occurrence:' + str(occurrence) + ' Found occurrence:' + str(nodes_in_graph[expected_node]))
            else:
                self.assertTrue(expected_node not in nodes_in_graph, 'Check failed for node:' + str(expected_node) + ' expected no occurrence but found')
    if expected_node_list is not None:
        cur_index = 0
        for n in node_list:
            if cur_index == len(expected_node_list):
                return
            if n == expected_node_list[cur_index]:
                cur_index += 1
        self.assertTrue(cur_index == len(expected_node_list), 'Check failed for graph:' + self.printGraphModule(graph_module, print_str=False) + 'Expected ordered list:' + str(expected_node_list))

def _iter_test_masks(self, X, y, groups):
    if <MASK>:
        raise ValueError("The 'groups' parameter should not be None.")
    groups = check_array(groups, input_name='groups', copy=True, ensure_2d=False, dtype=None)
    unique_groups = np.unique(groups)
    if len(unique_groups) <= 1:
        raise ValueError('The groups parameter contains fewer than 2 unique groups (%s). LeaveOneGroupOut expects at least 2.' % unique_groups)
    for i in unique_groups:
        yield (groups == i)

def visit_Compare(self, node):
    (lhs, lhs_ty) = self.visit(node.left)
    for (op, right) in zip(node.ops, node.comparators):
        (rhs, rhs_ty) = self.visit(right)
        if isinstance(op, ast.Eq):
            pred = 'eq'
        elif <MASK>:
            pred = 'ult'
        elif isinstance(op, ast.LtE):
            pred = 'ule'
        elif isinstance(op, ast.Gt):
            pred = 'ugt'
        elif isinstance(op, ast.GtE):
            pred = 'uge'
        elif isinstance(op, ast.NotEq):
            pred = 'ne'
        else:
            raise NotImplementedError('Compare operator not recognized')
        ret = self._ssa_name(pred)
        if lhs_ty == TFRTypes.ATTR:
            self._emit_with_loc('\n{} = tfr.equal {}, {} -> i1'.format(ret, lhs, rhs), node)
        else:
            if lhs_ty == TFRTypes.I64:
                code = 'arith.cmpi'
            elif lhs_ty == TFRTypes.F32:
                code = 'arith.cmpf'
            elif lhs_ty == TFRTypes.INDEX:
                code = 'arith.cmpi'
                (rhs, _) = self._i64_to_index(rhs, rhs_ty)
            else:
                raise NotImplementedError('Compare operand type not recognized')
            self._emit_with_loc('\n{} = {} "{}", {}, {} : {}'.format(ret, code, pred, lhs, rhs, lhs_ty), node)
        return (ret, TFRTypes.I1)

def clean_nn_module_stack_and_source_fn(graph_module: torch.fx.GraphModule, is_inline_builtin=False) -> torch.fx.GraphModule:
    """
    Clean up nn_module_stack metadata by removing export_root references.

    Removes the _export_root module references from nn_module_stack metadata
    in graph nodes, which are artifacts from the export process. Fixes two patterns:

    1. Keys: Removes "__export_root_" and "__modules['_export_root']_" prefixes
       - Normal case: "L__self____export_root_child" -> "L__self__child"
       - inline_builtin case: Uses numeric ID strings like "140468831433840"

    2. Values: Removes "._export_root" and "._modules['_export_root']" from child names
       e.g., "L['self']._export_root.child" -> "L['self'].child"
       e.g., "L['self']._modules['_export_root'].child" -> "L['self'].child"

    Also removes the root export entry "L__self____export_root" entirely.

    Args:
        graph_module: The GraphModule to clean up
        is_inline_builtin: If True, keys are numeric ID strings and self references
                          (L['self']) are filtered out

    Returns:
        The cleaned GraphModule (modified in-place)
    """

    def _process_nn_module_stack(nn_module_stack):
        if 'L__self____export_root' in nn_module_stack:
            del nn_module_stack['L__self____export_root']
        cleaned_stack = {}
        for (key, (child_name, child_class)) in nn_module_stack.items():
            clean_key = clean_export_root_string(key)
            clean_name = clean_export_root_string(child_name)
            if <MASK>:
                continue
            cleaned_stack[clean_key] = (clean_name, child_class)
        return cleaned_stack

    def _process_source_fn(source_fn_stack):
        cleaned_stack = []
        for item in source_fn_stack:
            if isinstance(item, tuple) and len(item) == 2:
                (name, cls) = item
                if isinstance(name, str):
                    clean_name = clean_export_root_string(name)
                    cleaned_stack.append((clean_name, cls))
                else:
                    cleaned_stack.append(item)
            else:
                cleaned_stack.append(item)
        return cleaned_stack
    for node in graph_module.graph.nodes:
        if 'nn_module_stack' in node.meta:
            node.meta['nn_module_stack'] = _process_nn_module_stack(node.meta['nn_module_stack'].copy())
        if 'source_fn_stack' in node.meta:
            node.meta['source_fn_stack'] = _process_source_fn(node.meta['source_fn_stack'].copy())
    if 'dynamo_flat_name_to_original_fqn' in graph_module.meta:
        clean_name_to_original_fqn = {}
        for (flat_name, original_fqn) in graph_module.meta['dynamo_flat_name_to_original_fqn'].items():
            clean_name_to_original_fqn[clean_export_root_string(flat_name)] = clean_export_root_string(original_fqn)
        graph_module.meta['dynamo_flat_name_to_original_fqn'] = clean_name_to_original_fqn
    return graph_module

def validate(self, model, instance, exclude=None, using=DEFAULT_DB_ALIAS):
    queryset = model._default_manager.using(using)
    if <MASK>:
        lookup_kwargs = {}
        generated_field_names = []
        for field_name in self.fields:
            if exclude and field_name in exclude:
                return
            field = model._meta.get_field(field_name)
            if field.generated:
                if exclude and self._expression_refs_exclude(model, field.expression, exclude):
                    return
                generated_field_names.append(field.name)
            else:
                lookup_value = getattr(instance, field.attname)
                if self.nulls_distinct is not False and lookup_value is None or (lookup_value == '' and connections[using].features.interprets_empty_strings_as_nulls):
                    return
                lookup_kwargs[field.name] = lookup_value
        lookup_args = []
        if generated_field_names:
            field_expression_map = instance._get_field_expression_map(meta=model._meta, exclude=exclude)
            for field_name in generated_field_names:
                expression = field_expression_map[field_name]
                if self.nulls_distinct is False:
                    lhs = F(field_name)
                    condition = Q(Exact(lhs, expression)) | Q(IsNull(lhs, True), IsNull(expression, True))
                    lookup_args.append(condition)
                else:
                    lookup_kwargs[field_name] = expression
        queryset = queryset.filter(*lookup_args, **lookup_kwargs)
    else:
        if exclude and any((self._expression_refs_exclude(model, expression, exclude) for expression in self.expressions)):
            return
        replacements = {F(field): value for (field, value) in instance._get_field_expression_map(meta=model._meta, exclude=exclude).items()}
        filters = []
        for expr in self.expressions:
            if hasattr(expr, 'get_expression_for_validation'):
                expr = expr.get_expression_for_validation()
            rhs = expr.replace_expressions(replacements)
            condition = Exact(expr, rhs)
            if self.nulls_distinct is False:
                condition = Q(condition) | Q(IsNull(expr, True), IsNull(rhs, True))
            filters.append(condition)
        queryset = queryset.filter(*filters)
    model_class_pk = instance._get_pk_val(model._meta)
    if not instance._state.adding and instance._is_pk_set(model._meta):
        queryset = queryset.exclude(pk=model_class_pk)
    if not self.condition:
        if queryset.exists():
            if self.fields and self.violation_error_message == self.default_violation_error_message:
                validation_error_message = instance.unique_error_message(model, self.fields)
                raise ValidationError(validation_error_message, code=validation_error_message.code)
            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)
    else:
        if exclude and self._expression_refs_exclude(model, self.condition, exclude):
            return
        against = instance._get_field_expression_map(meta=model._meta, exclude=exclude)
        if (self.condition & Exists(queryset.filter(self.condition))).check(against, using=using):
            raise ValidationError(self.get_violation_error_message(), code=self.violation_error_code)

def _reshape_view_helper_core_alg(a: TensorLikeType, shape, allow_copy: bool) -> TensorLikeType:
    idx = 0
    a_ = a
    for length in shape:
        if idx >= a_.ndim:
            assert length == 1
            last_dim = a_.ndim - 1
            a_ = prims.split_dim(a_, last_dim, a_.shape[last_dim])
            idx = idx + 1
            continue
        if length == a_.shape[idx]:
            idx = idx + 1
            continue
        accum = a_.shape[idx]
        end = idx
        while accum % length != 0:
            end += 1
            accum *= a_.shape[end]
        if end != idx:
            (new_shape, _new_strides) = prims._collapse_view_helper(a_, idx, end, must_be_valid=None)
            if new_shape is None:
                if allow_copy:
                    return prims.reshape(a, shape)
                msg = f'Cannot view a tensor with shape {a.shape} and strides {a.stride()} as a tensor with shape {shape}!'
                raise ValueError(msg)
            a_ = flatten(a_, idx, end)
        if <MASK>:
            a_ = prims.split_dim(a_, idx, length)
        idx = idx + 1
    while idx < a_.ndim:
        torch._check(a_.shape[idx] == 1, lambda : f'a.size({idx}) expected to be 1 but got {a_.shape[idx]}')
        a_ = squeeze(a_, idx)
    if a_ is a:
        return prims.view_of(a)
    else:
        return a_

def astype(self, dtype: AstypeArg, copy: bool=True) -> ArrayLike:
    """
        Coerce this type to another dtype

        Parameters
        ----------
        dtype : numpy dtype or pandas type
        copy : bool, default True
            By default, astype always returns a newly allocated object.
            If copy is set to False and dtype is categorical, the original
            object is returned.
        """
    dtype = pandas_dtype(dtype)
    result: Categorical | np.ndarray
    if self.dtype is dtype:
        result = self.copy() if copy else self
    elif isinstance(dtype, CategoricalDtype):
        dtype = self.dtype.update_dtype(dtype)
        self = self.copy() if copy else self
        result = self._set_dtype(dtype, copy=False)
        wrong = result.isna() & ~self.isna()
        if wrong.any():
            warnings.warn("Constructing a Categorical with a dtype and values containing non-null entries not in that dtype's categories is deprecated and will raise in a future version.", Pandas4Warning, stacklevel=find_stack_level())
    elif isinstance(dtype, ExtensionDtype):
        return super().astype(dtype, copy=copy)
    elif dtype.kind in 'iu' and self.isna().any():
        raise ValueError('Cannot convert float NaN to integer')
    elif <MASK>:
        if not copy:
            result = np.asarray(self, dtype=dtype)
        else:
            result = np.array(self, dtype=dtype)
    else:
        new_cats = self.categories._values
        try:
            new_cats = new_cats.astype(dtype=dtype, copy=copy)
            fill_value = self.categories._na_value
            if not is_valid_na_for_dtype(fill_value, dtype):
                fill_value = lib.item_from_zerodim(np.array(self.categories._na_value).astype(dtype))
        except (TypeError, ValueError) as err:
            msg = f'Cannot cast {self.categories.dtype} dtype to {dtype}'
            raise ValueError(msg) from err
        result = take_nd(new_cats, ensure_platform_int(self._codes), fill_value=fill_value)
    return result

def aot_dispatch_base_graph(flat_fn: TraceFn, flat_args: list[FxValue], flat_args_descs: list[AOTInput], aot_config: AOTConfig, *, fw_metadata: ViewAndMutationMeta) -> tuple[torch.fx.GraphModule, list[FxValue], list[AOTInput], Optional[SubclassMeta]]:
    fn_to_trace = fn_input_mutations_to_outputs(flat_fn, flat_args_descs, fw_metadata, keep_data_input_mutations=aot_config.keep_inference_input_mutations)
    if aot_config.disable_functionalization:
        (updated_flat_args, updated_flat_args_descs) = (flat_args, flat_args_descs)
    else:
        (fn_to_trace, updated_flat_args, updated_flat_args_descs) = create_functionalized_fn(fn_to_trace, flat_args, flat_args_descs, meta=fw_metadata, aot_config=aot_config, trace_joint=False)
    (fn_to_trace, updated_flat_args_subclasses_desugared, updated_flat_args_subclasses_desugared_descs, maybe_subclass_meta) = aot_dispatch_subclass(fn_to_trace, updated_flat_args, updated_flat_args_descs, is_joint_structure=False, meta=fw_metadata, fw_only=flat_fn)
    if <MASK>:
        (fn_to_trace, updated_flat_args_subclasses_desugared, updated_flat_args_subclasses_desugared_descs) = handle_effect_tokens_fn(fn_to_trace, updated_flat_args_subclasses_desugared, updated_flat_args_subclasses_desugared_descs, meta=fw_metadata, trace_joint=False)
    aot_graphs_log.debug('aot_config id: %s, fw_metadata=%s,subclass_metadata=%s', str(aot_config.aot_id), str(fw_metadata), str(maybe_subclass_meta))
    mod_when_exporting_non_strict = root_module_when_exporting_non_strict(flat_fn)
    if aot_config.is_export and mod_when_exporting_non_strict is not None:
        assigned_buffers: dict[str, str] = {}
        hook = register_buffer_assignment_hook(mod_when_exporting_non_strict, assigned_buffers)
    fake_mode = detect_fake_mode()
    if fake_mode:
        saved_updated_flat_args_subclasses_desugared = pytree.tree_map_only(torch.Tensor, _detach_and_copy_item_memo, updated_flat_args_subclasses_desugared)
    else:
        saved_updated_flat_args_subclasses_desugared = pytree.tree_map_only(torch.Tensor, lambda t: t.detach(), updated_flat_args_subclasses_desugared)
    saved_updated_flat_args_subclasses_desugared_descs = updated_flat_args_subclasses_desugared_descs
    fw_module = _create_graph(fn_to_trace, updated_flat_args_subclasses_desugared, updated_flat_args_subclasses_desugared_descs, aot_config=aot_config)
    if aot_config.is_export and mod_when_exporting_non_strict is not None:
        i = len(dict(mod_when_exporting_non_strict.named_parameters()))
        for (name, _) in mod_when_exporting_non_strict.named_buffers():
            if name in assigned_buffers and (not fw_metadata.input_info[i].mutates_data):
                fw_metadata.input_info[i] = dataclasses.replace(fw_metadata.input_info[i], mutates_data=True)
                fw_metadata.num_mutated_inp_runtime_indices += 1
            i += 1
        add_nodes = []
        output_node = list(fw_module.graph.nodes)[-1]
        for name in assigned_buffers.values():
            for node in fw_module.graph.nodes:
                if node.name == name:
                    add_nodes.append(node)
                    node.users[output_node] = None
        output_node.args = ((*add_nodes, *output_node.args[0]),)
        hook.remove()
    if not aot_config.disable_functionalization:
        copy_count = assert_functional_graph(fw_module.graph)
        fw_module.graph.eliminate_dead_code()
        fw_module.recompile()
        copy_count2 = assert_functional_graph(fw_module.graph)
        propagate_input_mutation_stacktraces(fw_module.graph)
        assert copy_count == copy_count2
    else:
        fw_module.graph.eliminate_dead_code()
    num_tokens = len(fw_metadata.tokens)
    if num_tokens != 0 and config.unlift_effect_tokens:
        unlift_tokens(fw_module, fw_metadata, aot_config)
        saved_updated_flat_args_subclasses_desugared = saved_updated_flat_args_subclasses_desugared[num_tokens:]
        saved_updated_flat_args_subclasses_desugared_descs = saved_updated_flat_args_subclasses_desugared_descs[num_tokens:]
    if aot_config.enable_log:
        aot_graphs_log.info('%s', lazy_format_graph_code('Forward graph', fw_module, aot_config.aot_id, include_stride=True, include_device=True, colored=True))
        trace_structured('artifact', metadata_fn=lambda : {'name': 'aot_forward_graph_fw_metadata', 'encoding': 'string'}, payload_fn=lambda : dataclass_repr(fw_metadata))
        if maybe_subclass_meta is not None:
            trace_structured('artifact', metadata_fn=lambda : {'name': 'aot_forward_graph_fw_subclass_metadata', 'encoding': 'string'}, payload_fn=lambda : dataclass_repr(maybe_subclass_meta))
        trace_structured('aot_inference_graph', payload_fn=lambda : fw_module.print_readable(print_output=False, include_stride=True, include_device=True, expanded_def=True))
    if aot_config.is_export:
        assert maybe_subclass_meta is None, 'aot_export_module does not support tensor subclass inputs for now.'
    return (fw_module, saved_updated_flat_args_subclasses_desugared, saved_updated_flat_args_subclasses_desugared_descs, maybe_subclass_meta)

def match_dtype_and_rank(y_t, y_p, sw):
    """Match dtype and rank of predictions."""
    if y_t.shape.rank == 1 and y_p.shape.rank == 2:
        y_t = array_ops.expand_dims_v2(y_t, axis=-1)
    if sw is not None:
        if sw.shape.rank == 1 and y_p.shape.rank == 2:
            sw = array_ops.expand_dims_v2(sw, axis=-1)
    if <MASK>:
        y_t = math_ops.cast(y_t, y_p.dtype)
    if sw is not None:
        sw = math_ops.cast(sw, y_p.dtype)
    return (y_t, y_p, sw)

def actual_grad_fn(*result_grad_components):
    """Custom grad fn wrapper."""
    result_grads = composite_tensor_gradient.replace_flat_tensors_for_gradients(nest.flatten(result), result_grad_components)
    if not isinstance(result_grads, (list, tuple)):
        result_grads = [result_grads]
    if variables:
        (input_grads, variable_grads) = grad_fn(*result_grads, variables=variables)
        if <MASK>:
            raise ValueError('Must return gradient for each variable from @custom_gradient grad_fn.')
    else:
        input_grads = grad_fn(*result_grads)
        variable_grads = []
    flat_grads = composite_tensor_gradient.get_flat_tensors_for_gradients(nest.flatten(input_grads))
    if len(flat_grads) != arg_count:
        raise ValueError(f'custom_gradient function expected to return {arg_count} gradients, but returned {len(flat_grads)} instead.')
    return flat_grads + variable_grads

def visit_Call(self, node):
    full_name = str(anno.getanno(node.func, anno.Basic.QN, default=''))
    function_context_name = self.state[_Function].context_name
    node = self.generic_visit(node)
    if full_name.startswith('ag__.'):
        return node
    if full_name.startswith(function_context_name + '.'):
        return node
    if full_name in ('pdb.set_trace', 'ipdb.set_trace', 'breakpoint'):
        global set_trace_warned
        if <MASK>:
            ag_logging.warning('Detected `pdb.set_trace()` in user code. The code generated by AutoGraph is not optimized for step-by-step debugging. See https://github.com/tensorflow/tensorflow/blob/master/tensorflow/python/autograph/g3doc/reference/debugging.md.')
            set_trace_warned = True
        return node
    if full_name == 'print' and (not self.ctx.user.options.uses(converter.Feature.BUILTIN_FUNCTIONS)):
        return node
    template = '\n      ag__.converted_call(func, args, kwargs, function_ctx)\n    '
    new_call = templates.replace_as_expression(template, func=node.func, args=self._args_to_tuple(node), kwargs=self._kwargs_to_dict(node), function_ctx=function_context_name)
    return new_call

def arrays_to_mgr(arrays, columns: Index, index, *, dtype: DtypeObj | None=None, verify_integrity: bool=True, consolidate: bool=True) -> Manager:
    """
    Segregate Series based on type and coerce into matrices.

    Needs to handle a lot of exceptional cases.
    """
    if verify_integrity:
        if index is None:
            index = _extract_index(arrays)
        else:
            index = ensure_index(index)
        (arrays, refs) = _homogenize(arrays, index, dtype)
    else:
        index = ensure_index(index)
        arrays = [extract_array(x, extract_numpy=True) for x in arrays]
        refs = [None] * len(arrays)
        for arr in arrays:
            if <MASK>:
                raise ValueError('Arrays must be 1-dimensional np.ndarray or ExtensionArray with length matching len(index)')
    columns = ensure_index(columns)
    if len(columns) != len(arrays):
        raise ValueError('len(arrays) must match len(columns)')
    axes = [columns, index]
    return create_block_manager_from_column_arrays(arrays, axes, consolidate=consolidate, refs=refs)

def _generate_range_overflow_safe_signed(endpoint: int, periods: int, stride: int, side: str) -> int:
    """
    A special case for _generate_range_overflow_safe where `periods * stride`
    can be calculated without overflowing int64 bounds.
    """
    assert side in ['start', 'end']
    if side == 'end':
        stride *= -1
    with np.errstate(over='raise'):
        addend = np.int64(periods) * np.int64(stride)
        try:
            result = np.int64(endpoint) + addend
            if result == iNaT:
                raise OverflowError
            return int(result)
        except (FloatingPointError, OverflowError):
            pass
        assert stride > 0 and endpoint >= 0 or (stride < 0 and endpoint <= 0)
        if <MASK>:
            uresult = np.uint64(endpoint) + np.uint64(addend)
            i64max = np.uint64(i8max)
            assert uresult > i64max
            if uresult <= i64max + np.uint64(stride):
                return int(uresult)
    raise OutOfBoundsDatetime(f'Cannot generate range with {side}={endpoint} and periods={periods}')

def isin(comps: ListLike, values: ListLike) -> npt.NDArray[np.bool_]:
    """
    Compute the isin boolean array.

    Parameters
    ----------
    comps : list-like
    values : list-like

    Returns
    -------
    ndarray[bool]
        Same length as `comps`.
    """
    if not is_list_like(comps):
        raise TypeError(f'only list-like objects are allowed to be passed to isin(), you passed a `{type(comps).__name__}`')
    if <MASK>:
        raise TypeError(f'only list-like objects are allowed to be passed to isin(), you passed a `{type(values).__name__}`')
    if not isinstance(values, (ABCIndex, ABCSeries, ABCExtensionArray, np.ndarray)):
        orig_values = list(values)
        values = _ensure_arraylike(orig_values, func_name='isin-targets')
        if len(values) > 0 and values.dtype.kind in 'iufcb' and (not is_signed_integer_dtype(comps)) and (not is_dtype_equal(values, comps)):
            values = construct_1d_object_array_from_listlike(orig_values)
    elif isinstance(values, ABCMultiIndex):
        values = np.array(values)
    else:
        values = extract_array(values, extract_numpy=True, extract_range=True)
    comps_array = _ensure_arraylike(comps, func_name='isin')
    comps_array = extract_array(comps_array, extract_numpy=True)
    if not isinstance(comps_array, np.ndarray):
        return comps_array.isin(values)
    elif needs_i8_conversion(comps_array.dtype):
        return pd_array(comps_array).isin(values)
    elif needs_i8_conversion(values.dtype) and (not is_object_dtype(comps_array.dtype)):
        return np.zeros(comps_array.shape, dtype=bool)
    elif needs_i8_conversion(values.dtype):
        return isin(comps_array, values.astype(object))
    elif isinstance(values.dtype, ExtensionDtype):
        return isin(np.asarray(comps_array), np.asarray(values))
    if len(comps_array) > _MINIMUM_COMP_ARR_LEN and len(values) <= 26 and (comps_array.dtype != object) and (not any((v is NA for v in values))):
        if isna(values).any():

            def f(c, v):
                return np.logical_or(np.isin(c, v).ravel(), np.isnan(c))
        else:
            f = lambda a, b: np.isin(a, b).ravel()
    else:
        common = np_find_common_type(values.dtype, comps_array.dtype)
        values = values.astype(common, copy=False)
        comps_array = comps_array.astype(common, copy=False)
        f = htable.ismember
    return f(comps_array, values)

def recalc_global_sharded_tensor_metadata(global_sharded_tensor_metadata: ShardedTensorMetadata, sharded_dim: int) -> None:
    placement_idx_pairs = []
    for (i, shard_metadata) in enumerate(global_sharded_tensor_metadata.shards_metadata):
        if <MASK>:
            placement_idx_pairs.append((shard_metadata.placement.rank(), i))
        else:
            raise AssertionError('currently only support rw, it should always have valid rank info')
    sorted_idx = sorted(placement_idx_pairs)
    shard_sizes = [global_sharded_tensor_metadata.shards_metadata[idx].shard_sizes[sharded_dim] for (_, idx) in sorted_idx]
    cum_sum = [0] + list(itertools.accumulate(shard_sizes))
    for (shard_id, shard_metadata) in enumerate(global_sharded_tensor_metadata.shards_metadata):
        shard_metadata.shard_offsets[sharded_dim] = cum_sum[shard_id]
        for other_dim in range(len(global_sharded_tensor_metadata.shards_metadata[0].shard_sizes)):
            if other_dim != sharded_dim:
                shard_metadata.shard_offsets[other_dim] = 0
    global_size_list = []
    for other_dim in range(len(global_sharded_tensor_metadata.shards_metadata[0].shard_sizes)):
        if other_dim != sharded_dim:
            global_size_list.append(global_sharded_tensor_metadata.shards_metadata[0].shard_sizes[other_dim])
        else:
            global_size_list.append(cum_sum[-1])
    global_sharded_tensor_metadata.size = torch.Size(global_size_list)

def __init__(self, backend: str=torch.backends.quantized.engine):
    super().__init__()
    self.backend_chosen = backend
    self.supported_modules = set()
    if <MASK>:
        self.supported_modules = self.DEFAULT_BACKEND_PER_CHANNEL_SUPPORTED_MODULES[self.backend_chosen]
    else:
        raise ValueError(f'Not configured to work with {self.backend_chosen}. Try a different default backend')

def convert(self, values: np.ndarray, nan_rep, encoding: str, errors: str) -> tuple[np.ndarray, np.ndarray] | tuple[Index, Index]:
    """
        Convert the data from this selection to the appropriate pandas type.
        """
    assert isinstance(values, np.ndarray), type(values)
    if values.dtype.fields is not None:
        values = values[self.cname].copy()
    val_kind = self.kind
    values = _maybe_convert(values, val_kind, encoding, errors)
    kwargs = {}
    kwargs['name'] = self.index_name
    if self.freq is not None:
        kwargs['freq'] = self.freq
    factory: type[Index | DatetimeIndex] = Index
    if lib.is_np_dtype(values.dtype, 'M') or isinstance(values.dtype, DatetimeTZDtype):
        factory = DatetimeIndex
    elif values.dtype == 'i8' and 'freq' in kwargs:
        factory = lambda x, **kwds: PeriodIndex.from_ordinals(x, freq=kwds.get('freq', None))._rename(kwds['name'])
    try:
        new_pd_index = factory(values, **kwargs)
    except UnicodeEncodeError as err:
        if errors == 'surrogatepass' and get_option('future.infer_string') and str(err).endswith('surrogates not allowed') and HAS_PYARROW:
            new_pd_index = factory(values, dtype=StringDtype(storage='python', na_value=np.nan), **kwargs)
        else:
            raise
    except ValueError:
        if <MASK>:
            kwargs['freq'] = None
        new_pd_index = factory(values, **kwargs)
    final_pd_index: Index
    if self.tz is not None and isinstance(new_pd_index, DatetimeIndex):
        final_pd_index = new_pd_index.tz_localize('UTC').tz_convert(self.tz)
    else:
        final_pd_index = new_pd_index
    return (final_pd_index, final_pd_index)

def _to_placeholder(self):
    """Convert this KerasTensor to a placeholder in a graph."""
    if <MASK>:
        inferred_value = array_ops.shape(array_ops.placeholder(shape=self._inferred_value, dtype=dtypes.int32))
        if self.type_spec.shape.rank == 0:
            inferred_value = inferred_value[0]
        return inferred_value

    def component_to_placeholder(component):
        return array_ops.placeholder(component.dtype, component.shape)
    return nest.map_structure(component_to_placeholder, self.type_spec, expand_composites=True)

def create_script_module_impl(nn_module, concrete_type, stubs_fn):
    """
    Convert an nn.Module to a RecursiveScriptModule.

    Args:
        nn_module:  The original Python nn.Module that we are creating a ScriptModule for.
        concrete_type:  The fully initialized ConcreteType of the module.
        stubs_fn:  Lambda that takes an nn.Module and generates a list of ScriptMethodStubs to compile.
    """
    cpp_module = torch._C._create_module_with_type(concrete_type.jit_type)
    method_stubs = stubs_fn(nn_module)
    property_stubs = get_property_stubs(nn_module)
    (hook_stubs, pre_hook_stubs) = get_hook_stubs(nn_module)
    ignored_properties = jit_ignored_properties(nn_module)

    def init_fn(script_module):
        for name in concrete_type.get_attributes().keys():
            orig_value = getattr(nn_module, name)
            orig_value = orig_value.value if isinstance(orig_value, torch.jit.Attribute) else orig_value
            cpp_module.setattr(name, orig_value)
        for (name, sub_concrete_type) in concrete_type.get_modules():
            orig_value = getattr(nn_module, name)
            assert isinstance(orig_value, Module), f'Expected Module but got {type(orig_value)}'
            module_type = sub_concrete_type.jit_type
            if isinstance(module_type, torch._C.InterfaceType):
                scripted = interface_script(module_type, orig_value)
            elif isinstance(orig_value, torch.jit.ScriptModule):
                scripted = orig_value
            else:
                scripted = create_script_module_impl(orig_value, sub_concrete_type, stubs_fn)
            cpp_module.setattr(name, scripted)
            script_module._modules[name] = scripted
        for name in dir(nn_module):
            if name in ignored_properties:
                continue
            item = getattr(nn_module, name, None)
            if <MASK>:
                unbound_function = getattr(nn_module, name).__func__
                bound_method = unbound_function.__get__(script_module)
                setattr(script_module, name, bound_method)
            elif concrete_type.is_ignored_attribute(name):
                setattr(script_module, name, item)
        script_module._concrete_type = concrete_type
    script_module = torch.jit.RecursiveScriptModule._construct(cpp_module, init_fn)
    if concrete_type not in concrete_type_store.methods_compiled:
        create_methods_and_properties_from_stubs(concrete_type, method_stubs, property_stubs)
        create_hooks_from_stubs(concrete_type, hook_stubs, pre_hook_stubs)
        torch._C._run_emit_module_hook(cpp_module)
        concrete_type_store.methods_compiled.add(concrete_type)
    for (idx, fn) in enumerate(script_module._c._get_forward_pre_hooks()):
        script_module._forward_pre_hooks[idx] = fn
    for (idx, fn) in enumerate(script_module._c._get_forward_hooks()):
        script_module._forward_hooks[idx] = fn
    if isinstance(nn_module, (torch.nn.ModuleList, torch.nn.Sequential, torch.nn.ModuleDict)) and '__len__' not in cpp_module._method_names():
        script_module.define(f'def __len__(self):\n   return {len(nn_module)}\n')
    if isinstance(nn_module, torch.nn.ModuleDict) and '__contains__' not in cpp_module._method_names():
        if len(nn_module.keys()):
            keys = repr(list(nn_module.keys()))
            script_module.define(f'def __contains__(self, key: str):\n   return key in {keys}\n')
        else:
            script_module.define('def __contains__(self, key: str):\n   return False\n')
    for method_stub in method_stubs:
        if method_stub.original_method is None:
            continue
        name = method_stub.original_method.__name__
        if name != method_stub.def_.name().name:
            continue
        script_method = cpp_module._get_method(name)
        wrapped_script_method = functools.wraps(method_stub.original_method)(script_method)
        script_module.__dict__[name] = wrapped_script_method
    for property_stub in property_stubs:
        property_name = property_stub.def_.name().name
        fget = cpp_module._get_method(property_stub.def_.getter_name().name)
        setter_name = property_stub.def_.setter_name()
        fset = cpp_module._get_method(setter_name.name) if setter_name else None
        script_module.__dict__[property_name] = property(property_name, fget, fset)
    for name in dir(nn_module):
        if name in ignored_properties:
            continue
        item = getattr(nn_module, name, None)
        if _jit_internal.get_torchscript_modifier(item) is _jit_internal.FunctionModifiers.COPY_TO_SCRIPT_WRAPPER:
            add_python_attr_to_scripted_model(script_module, nn_module, name)
    return script_module

def build_graph(parameters):
    """Build a transpose_conv graph given `parameters`."""
    (input_shape, filter_shape) = get_tensor_shapes(parameters)
    input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=input_shape)
    filter_input = tf.compat.v1.placeholder(dtype=tf.float32, name='filter', shape=filter_shape)
    if not parameters['const_weight_bias']:
        input_tensors = [input_tensor, filter_input]
        conv_outputs = tf.nn.conv2d(input=input_tensor, filters=filter_input, strides=parameters['strides'], padding=parameters['padding'], data_format=parameters['data_format'])
        out = tf.compat.v1.nn.conv2d_backprop_input(input_shape, filter_input, conv_outputs, strides=parameters['strides'], padding=parameters['padding'], data_format=parameters['data_format'])
    else:
        input_tensors = [input_tensor]
        if <MASK>:
            filter_input = create_tensor_data(np.float32, filter_shape, min_value=-1, max_value=1)
        else:
            filter_input = create_tensor_data(np.float32, filter_shape)
        out = tf.nn.conv2d_transpose(input_tensor, filter_input, parameters['output_shape'], strides=parameters['strides'], padding=parameters['padding'], data_format=parameters['data_format'])
        if parameters['has_bias']:
            if parameters['fully_quantize']:
                bias_input = create_tensor_data(np.float32, (parameters['output_shape'][-1],), min_value=-1, max_value=1)
            else:
                bias_input = create_tensor_data(np.float32, (parameters['output_shape'][-1],))
            out = tf.nn.bias_add(out, bias_input, data_format=parameters['data_format'])
            mul_data = create_tensor_data(np.float32, (parameters['output_shape'][-1],))
            out = tf.math.multiply(out, mul_data)
    return (input_tensors, [out])

def remove_replaced_nodes(self, replacement, replaced):
    """
        Remove each of the `replaced` nodes (when they exist). Any
        dependencies that were referencing them are changed to reference the
        `replacement` node instead.
        """
    replaced = set(replaced)
    try:
        replacement_node = self.node_map[replacement]
    except KeyError as err:
        raise NodeNotFoundError('Unable to find replacement node %r. It was either never added to the migration graph, or has been removed.' % (replacement,), replacement) from err
    for replaced_key in replaced:
        self.nodes.pop(replaced_key, None)
        replaced_node = self.node_map.pop(replaced_key, None)
        if replaced_node:
            for child in replaced_node.children:
                child.parents.remove(replaced_node)
                if child.key not in replaced:
                    replacement_node.add_child(child)
                    child.add_parent(replacement_node)
            for parent in replaced_node.parents:
                parent.children.remove(replaced_node)
                if <MASK>:
                    replacement_node.add_parent(parent)
                    parent.add_child(replacement_node)

@parameterized.named_parameters([('packed', True), ('unpacked', False)])
def test_spmd_variable_structure(self, enable_packing):
    (strategy, num_replicas) = get_tpu_strategy(enable_spmd=True)
    if <MASK>:
        self.assertTrue(strategy._enable_packed_variable_in_eager_mode, 'packed variables should be enabled by default')
    else:
        strategy._enable_packed_variable_in_eager_mode = False
    tensor = constant_op.constant([[0.0, 1.0], [2.0, 3.0]])
    with strategy.scope():
        v = variables.Variable(tensor, name='v', synchronization=vs.VariableSynchronization.ON_READ)
        w = variables.Variable(tensor, name='w', synchronization=vs.VariableSynchronization.ON_WRITE)

    def test_read(x):

        @def_function.function
        def fn():
            return x.read_value()
        results = strategy.run(fn)
        results = strategy.experimental_local_results(results)
        for i in range(num_replicas):
            self.assertAllClose(results[i], tensor)

    def test_structure(values):
        for (i, value) in enumerate(values):
            self.assertIsInstance(value, tpu_replicated_variable.TPUReplicatedVariable)
            packed_var = getattr(value, '_packed_var', None)
            if enable_packing:
                if i == 0:
                    self.assertIsInstance(packed_var, packed.PackedDistributedVariable)
                else:
                    self.assertIs(packed_var, values[0]._packed_var, 'all vals should share the same packed var instance')
            else:
                self.assertIsNone(packed_var)
        if enable_packing:
            resources = sum((value._vars for value in values), [])
            dist_vars = packed_var._distributed_variables
            self.assertLen(resources, len(dist_vars))
            for (dist_var, resource) in zip(dist_vars, resources):
                self.assertIs(dist_var, resource)
    test_read(v)
    test_structure(v.values)
    test_read(w)
    test_structure(w.values)

def filter_op(self, op_info: InductorROCmOp):
    """
        Determines whether a given op definition is suitable for the current
        input / output of the operation that this template implements.

        Filter is based on inputs' dtype, layout and statically inferred size.

        Returns None if the op is not suitable, otherwise returns the op to be used.
        """
    (op, kBatch) = (op_info.op, op_info.kBatch)
    metas = [T.get_layout() for T in [*self.input_nodes, self.output_node]]
    X_meta = metas[0]
    W_meta = metas[1]
    Y_meta = metas[-1]
    if op.a_element_dtype != self._TORCH_DTYPE_TO_CK[X_meta.dtype]:
        return None
    if op.b_element_dtype != self._TORCH_DTYPE_TO_CK[W_meta.dtype]:
        return None
    if op.c_element_dtype != self._TORCH_DTYPE_TO_CK[Y_meta.dtype]:
        return None
    if op.a_layout != torch_layout_to_ck_layout(X_meta):
        return None
    if <MASK>:
        return None
    if op.c_layout != torch_layout_to_ck_layout(Y_meta):
        return None
    M = X_meta.size[-2]
    K = X_meta.size[-1]
    N = W_meta.size[-1]
    if is_static_int(M):
        if not self._has_padding('M', op.gemm_specialization):
            if M % op.m_per_block != 0:
                return None
    if is_static_int(N):
        if not self._has_padding('N', op.gemm_specialization):
            if N % op.n_per_block != 0:
                return None
    if is_static_int(K):
        if not self._has_padding('K', op.gemm_specialization):
            if K % op.k_per_block != 0:
                return None
            K_t = kBatch * op.k_per_block
            if K % K_t != 0:
                return None
        else:
            lcm = abs(op.a_k1 * op.b_k1) // math.gcd(op.a_k1, op.b_k1)
            K_t = kBatch * lcm
            k_read_pad_splited = math.ceil(K / K_t) * lcm
            if k_read_pad_splited * (kBatch - 1) >= K:
                return None
    a_contig_size = K if op.a_layout == 'Row' else M if op.a_layout == 'Col' else None
    if is_static_int(a_contig_size) and a_contig_size % op.a_block_transfer_src_scalar_per_vector != 0:
        return None
    b_contig_size = N if op.b_layout == 'Row' else K if op.b_layout == 'Col' else None
    if is_static_int(b_contig_size) and b_contig_size % op.b_block_transfer_src_scalar_per_vector != 0:
        return None
    c_contig_size = N if op.c_layout == 'Row' else M if op.c_layout == 'Col' else None
    c_shuffle_block_transfer_scalar_per_vector_n_per_block = op.c_shuffle_block_transfer_scalar_per_vector_n_per_block[0] if isinstance(op.c_shuffle_block_transfer_scalar_per_vector_n_per_block, tuple) else op.c_shuffle_block_transfer_scalar_per_vector_n_per_block
    if is_static_int(c_contig_size) and c_contig_size % c_shuffle_block_transfer_scalar_per_vector_n_per_block != 0:
        return None
    if not self._check_num_k_loops(op, kBatch):
        return None
    return op

def _create_ordered_metrics(self):
    """Cache the flat order needed when returning metrics, for backwards compat."""
    self._metrics_in_order = []
    for (output_metrics, output_weighted_metrics) in zip(self._metrics, self._weighted_metrics):
        for m in nest.flatten(output_metrics):
            if m is not None:
                self._metrics_in_order.append(m)
        for wm in nest.flatten(output_weighted_metrics):
            if <MASK>:
                self._metrics_in_order.append(wm)

def __init__(self, excludelist=None, deletechars=None, case_sensitive=None, replace_space='_'):
    if excludelist is None:
        excludelist = []
    excludelist.extend(self.defaultexcludelist)
    self.excludelist = excludelist
    if deletechars is None:
        delete = set(self.defaultdeletechars)
    else:
        delete = set(deletechars)
    delete.add('"')
    self.deletechars = delete
    if case_sensitive is None or case_sensitive is True:
        self.case_converter = lambda x: x
    elif case_sensitive is False or case_sensitive.startswith('u'):
        self.case_converter = lambda x: x.upper()
    elif <MASK>:
        self.case_converter = lambda x: x.lower()
    else:
        msg = f'unrecognized case_sensitive value {case_sensitive}.'
        raise ValueError(msg)
    self.replace_space = replace_space

def __getattribute__(self, name):
    """Overridden to support hyperparameter access."""
    try:
        return super(OptimizerV2, self).__getattribute__(name)
    except AttributeError as e:
        if name == '_hyper':
            raise e
        if name == 'lr':
            name = 'learning_rate'
        if <MASK>:
            return self._get_hyper(name)
        raise e

def _reconstruct(result):
    if lib.is_scalar(result):
        return result
    if result.ndim != self.ndim:
        if method == 'outer':
            raise NotImplementedError
        return result
    if isinstance(result, BlockManager):
        result = self._constructor_from_mgr(result, axes=result.axes)
    else:
        result = self._constructor(result, **reconstruct_axes, **reconstruct_kwargs, copy=False)
    if <MASK>:
        result = result.__finalize__(self)
    return result

def _initialize_columns(self, cols: Iterable[Hashable] | None) -> npt.NDArray[np.object_]:
    if self.has_mi_columns:
        if cols is not None:
            msg = 'cannot specify cols with a MultiIndex on the columns'
            raise TypeError(msg)
    if cols is not None:
        if <MASK>:
            cols = cols._get_values_for_csv(**self._number_format)
        else:
            cols = list(cols)
        self.obj = self.obj.loc[:, cols]
    new_cols = self.obj.columns
    return new_cols._get_values_for_csv(**self._number_format)

def _check_fetch_lfw(data_home=None, funneled=True, download_if_missing=True, n_retries=3, delay=1.0):
    """Helper function to download any missing LFW data"""
    data_home = get_data_home(data_home=data_home)
    lfw_home = join(data_home, 'lfw_home')
    if not exists(lfw_home):
        makedirs(lfw_home)
    for target in TARGETS:
        target_filepath = join(lfw_home, target.filename)
        if not exists(target_filepath):
            if download_if_missing:
                logger.info('Downloading LFW metadata: %s', target.url)
                _fetch_remote(target, dirname=lfw_home, n_retries=n_retries, delay=delay)
            else:
                raise OSError('%s is missing' % target_filepath)
    if funneled:
        data_folder_path = join(lfw_home, 'lfw_funneled')
        archive = FUNNELED_ARCHIVE
    else:
        data_folder_path = join(lfw_home, 'lfw')
        archive = ARCHIVE
    if <MASK>:
        archive_path = join(lfw_home, archive.filename)
        if not exists(archive_path):
            if download_if_missing:
                logger.info('Downloading LFW data (~200MB): %s', archive.url)
                _fetch_remote(archive, dirname=lfw_home, n_retries=n_retries, delay=delay)
            else:
                raise OSError('%s is missing' % archive_path)
        import tarfile
        logger.debug('Decompressing the data archive to %s', data_folder_path)
        with tarfile.open(archive_path, 'r:gz') as fp:
            tarfile_extractall(fp, path=lfw_home)
        remove(archive_path)
    return (lfw_home, data_folder_path)

def construct_1d_arraylike_from_scalar(value: Scalar, length: int, dtype: DtypeObj | None) -> ArrayLike:
    """
    create a np.ndarray / pandas type of specified shape and dtype
    filled with values

    Parameters
    ----------
    value : scalar value
    length : int
    dtype : pandas_dtype or np.dtype

    Returns
    -------
    np.ndarray / pandas type of length, filled with value

    """
    if dtype is None:
        try:
            (dtype, value) = infer_dtype_from_scalar(value)
        except OutOfBoundsDatetime:
            dtype = _dtype_obj
    if isinstance(dtype, ExtensionDtype):
        cls = dtype.construct_array_type()
        seq = [] if length == 0 else [value]
        return cls._from_sequence(seq, dtype=dtype).repeat(length)
    if length and dtype.kind in 'iu' and isna(value):
        dtype = np.dtype('float64')
    elif <MASK>:
        dtype = np.dtype('object')
        if not isna(value):
            value = ensure_str(value)
    elif dtype.kind in 'mM':
        value = _maybe_box_and_unbox_datetimelike(value, dtype)
    subarr = np.empty(length, dtype=dtype)
    if length:
        subarr.fill(value)
    return subarr

def check_graph_consistency(tensor=None, method='add_loss', force_raise=False):
    """Checks that tensors passed to `add_*` method match the Keras graph.

  When one of the `add_*` method is called inside a V2 conditional branch,
  the underlying tensor gets created in a FuncGraph managed by control_flow_v2.
  We need to raise clear error messages in such cases.

  Args:
    tensor: Tensor to check, or `False` if it is known that an error
      should be raised.
    method: Caller method, one of {'add_metric', 'add_loss', 'add_update'}.
    force_raise: If an error should be raised regardless of `tensor`.

  Raises:
    RuntimeError: In case of an out-of-graph tensor.
  """
    if <MASK>:
        if method == 'activity_regularizer':
            bad_example = "
      class TestModel(tf.keras.Model):

        def __init__(self):
          super(TestModel, self).__init__(name='test_model')
          self.dense = tf.keras.layers.Dense(2, activity_regularizer='l2')

        def call(self, x, training=None):
          if training:
            return self.dense(x)
          else:
            return self.dense(x)
      "
            correct_example = "
      class TestModel(tf.keras.Model):

        def __init__(self):
          super(TestModel, self).__init__(name='test_model')
          self.dense = tf.keras.layers.Dense(2, activity_regularizer='l2')

        def call(self, x, training=None):
          return self.dense(x)
      "
            raise RuntimeError('You are using a layer with `activity_regularizer` in a control flow branch, e.g.:
{bad_example}
This is currently not supported. Please move your call to the layer with `activity_regularizer` out of the control flow branch, e.g.:
{correct_example}
You can also resolve this by marking your outer model/layer dynamic (eager-only) by passing `dynamic=True` to the layer constructor. Any kind of control flow is supported with dynamic layers. Note that using `dynamic=True` requires you to implement static shape inference in the `compute_output_shape(input_shape)` method.'.format(bad_example=bad_example, correct_example=correct_example))
        if method == 'add_metric':
            bad_example = "
      def call(self, inputs, training=None):
        if training:
          metric = compute_metric(inputs)
          self.add_metric(metric, name='my_metric', aggregation='mean')
        return inputs
      "
            correct_example = "
      def call(self, inputs, training=None):
        if training:
          metric = compute_metric(inputs)
        else:
          metric = 0.
        self.add_metric(metric, name='my_metric', aggregation='mean')
        return inputs
      "
        elif method == 'add_loss':
            bad_example = '
      def call(self, inputs, training=None):
        if training:
          loss = compute_loss(inputs)
          self.add_loss(loss)
        return inputs
      '
            correct_example = '
      def call(self, inputs, training=None):
        if training:
          loss = compute_loss(inputs)
        else:
          loss = 0.
        self.add_loss(loss)
        return inputs
      '
        else:
            bad_example = '
      def call(self, inputs, training=None):
        if training:
          self.add_update(self.w.assign_add(1))
        return inputs
      '
            correct_example = '
      def call(self, inputs, training=None):
        if training:
          increment = 1
        else:
          increment = 0
        self.add_update(self.w.assign_add(increment))
        return inputs
      '
        raise RuntimeError('You are using the method `{method}` in a control flow branch in your layer, e.g.:
{bad_example}
This is not currently supported. Please move your call to {method} out of the control flow branch, e.g.:
{correct_example}
You can also resolve this by marking your layer as dynamic (eager-only) by passing `dynamic=True` to the layer constructor. Any kind of control flow is supported with dynamic layers. Note that using `dynamic=True` requires you to implement static shape inference in the `compute_output_shape(input_shape)` method.'.format(method=method, bad_example=bad_example, correct_example=correct_example))

def _to_numpy(elem) -> list | npt.NDArray:
    if isinstance(elem, torch.Tensor):
        if elem.requires_grad:
            return elem.detach().cpu().numpy()
        else:
            return elem.cpu().numpy()
    elif isinstance(elem, (list, tuple)):
        return [_to_numpy(inp) for inp in elem]
    elif isinstance(elem, (bool, int, float)):
        return np.array(elem)
    elif <MASK>:
        flattened = []
        for k in elem:
            flattened.extend([_to_numpy(k), _to_numpy(elem[k])])
        return flattened
    return elem

def _get_text_color(color: str) -> str:
    (r, g, b) = map(lambda x: int(x, 16), (color[1:3], color[3:5], color[5:7]))
    if <MASK>:
        return '#000000'
    return '#ffffff'

def construct_change_message(form, formsets, add):
    """
    Construct a JSON structure describing changes from a changed object.
    Translations are deactivated so that strings are stored untranslated.
    Translation happens later on LogEntry access.
    """
    changed_data = form.changed_data
    with translation_override(None):
        changed_field_labels = _get_changed_field_labels_from_form(form, changed_data)
    change_message = []
    if add:
        change_message.append({'added': {}})
    elif <MASK>:
        change_message.append({'changed': {'fields': changed_field_labels}})
    if formsets:
        with translation_override(None):
            for formset in formsets:
                for added_object in formset.new_objects:
                    change_message.append({'added': {'name': str(added_object._meta.verbose_name), 'object': str(added_object)}})
                for (changed_object, changed_fields) in formset.changed_objects:
                    change_message.append({'changed': {'name': str(changed_object._meta.verbose_name), 'object': str(changed_object), 'fields': _get_changed_field_labels_from_form(formset.forms[0], changed_fields)}})
                for deleted_object in formset.deleted_objects:
                    change_message.append({'deleted': {'name': str(deleted_object._meta.verbose_name), 'object': str(deleted_object)}})
    return change_message

def check_tensor_meta(local_tensor, check_shape_stride=False) -> Optional['dtensor_spec.TensorMeta']:
    local_metadata = {'dtype': local_tensor.dtype, 'requires_grad': local_tensor.requires_grad}
    if <MASK>:
        local_metadata.update({'shape': local_tensor.shape, 'stride': local_tensor.stride()})
    gathered_metadata = [None for _ in range(torch.distributed.get_world_size())]
    torch.distributed.all_gather_object(gathered_metadata, local_metadata)
    if not all((meta == local_metadata for meta in gathered_metadata)):
        raise ValueError('Inconsistent tensor metadata (including shape and stride) across ranks.')
    return None

def post_grad_passes(gm: torch.fx.GraphModule, is_inference: bool):
    """
    Passes that run on after grad.  This is called once on the forwards
    graph and once on the backwards graph.

    The IR here has been normalized and functionalized.
    """
    GraphTransformObserver = functools.partial(torch.fx.passes.graph_transform_observer.GraphTransformObserver, subsystem='post_grad_passes')
    if not torch._dynamo.config.skip_fsdp_hooks:
        remove_fsdp2_unsharded_param_graph_input_usage(gm.graph)
    if config.dce:
        gm.graph.eliminate_dead_code()
    if is_inference and config.reorder_for_locality:
        GraphTransformObserver(gm, 'reorder_for_locality').apply_graph_pass(reorder_for_locality)
    fake_tensor_updater = FakeTensorUpdater(gm.graph)
    if (post_grad_custom_pre_pass := config.post_grad_custom_pre_pass):
        GraphTransformObserver(gm, 'post_grad_custom_pre_pass').apply_graph_pass(post_grad_custom_pre_pass)
    if torch._C._has_mkldnn:
        if config.cpp.enable_grouped_gemm_template and config.max_autotune and ('CPP' in config.max_autotune_gemm_backends):
            from .mkldnn_fusion import grouped_gemm_pass
            grouped_gemm_pass(gm.graph)
        if config.cpp.enable_concat_linear:
            from .quantization import concat_linear_woq_int4
            concat_linear_woq_int4(gm)
    if config.pattern_matcher:
        lazy_init()
        GraphTransformObserver(gm, 'post_grad_custom_pre_pass').apply_graph_pass(functools.partial(group_batch_fusion_passes, pre_grad=False))
        GraphTransformObserver(gm, 'remove_noop_ops').apply_graph_pass(remove_noop_ops)
        GraphTransformObserver(gm, 'remove_assert_ops').apply_graph_pass(remove_assert_ops)
        for (i, patterns) in enumerate(pass_patterns):
            GraphTransformObserver(gm, f'pass_pattern_{i}').apply_graph_pass(patterns.apply)
        for pass_name in config.post_grad_fusion_options:
            if pass_name in POST_GRAD_FUSIONS or pass_name in OPTIMUS_EXCLUDE_POST_GRAD:
                continue
            pattern_matcher_pass = POST_GRAD_PATTERNS[pass_name]
            inductor_before_change = save_inductor_dict([pattern_matcher_pass.pass_name])
            GraphTransformObserver(gm, pass_name).apply_graph_pass(pattern_matcher_pass.apply)
            if not is_same_dict(counters['inductor'], inductor_before_change):
                trace_structured('artifact', metadata_fn=lambda : {'name': f'{pattern_matcher_pass.pass_name}_post_grad', 'encoding': 'string'}, payload_fn=lambda : gm.print_readable(print_output=False, include_stride=True, include_device=True))
        if config.b2b_gemm_pass:
            B2B_GEMM_PASS.apply(gm.graph)
    if config._micro_pipeline_tp:
        micro_pipeline_tp_pass(gm.graph)
    if config._fuse_ddp_communication:
        GraphTransformObserver(gm, 'fuse_ddp_communication').apply_graph_pass(lambda graph: fuse_ddp_communication(graph, config._fuse_ddp_communication_passes, config._fuse_ddp_bucket_size))
    if (post_grad_custom_post_pass := config.post_grad_custom_post_pass):
        GraphTransformObserver(gm, 'post_grad_custom_post_pass').apply_graph_pass(post_grad_custom_post_pass)
    GraphTransformObserver(gm, 'stable_sort').apply_graph_pass(stable_topological_sort)
    GraphTransformObserver(gm, 'move_constructors_to_cuda').apply_graph_pass(move_constructors_to_gpu)
    fake_tensor_updater.incremental_update()
    for (device, custom_backend_pass) in custom_backend_passes.items():
        if custom_backend_pass is not None:
            gm_devices = [d.type for d in get_all_devices(gm)]
            if device in gm_devices:
                pass_name = 'custom_backend_passes_' + device
                GraphTransformObserver(gm, pass_name).apply_gm_pass(custom_backend_pass)
    collectives_bucketing: bool = False
    if <MASK>:
        from torch._inductor.fx_passes.bucketing import bucket_reduce_scatter
        from torch._inductor.fx_passes.fsdp import bucket_fsdp_reduce_scatter
        p = bucket_fsdp_reduce_scatter if 'fsdp' in config.bucket_reduce_scatters_fx else bucket_reduce_scatter
        GraphTransformObserver(gm, 'bucket_reduce_scatters').apply_graph_pass(lambda graph: p(graph.owning_module, config.bucket_reduce_scatters_fx_bucket_size_determinator, config.bucket_reduce_scatters_fx))
        collectives_bucketing = True
    if config.bucket_all_gathers_fx != 'none':
        from torch._inductor.fx_passes.bucketing import bucket_all_gather
        from torch._inductor.fx_passes.fsdp import bucket_fsdp_all_gather
        p = bucket_fsdp_all_gather if 'fsdp' in config.bucket_all_gathers_fx else bucket_all_gather
        GraphTransformObserver(gm, 'bucket_all_gathers').apply_graph_pass(lambda graph: p(graph.owning_module, config.bucket_all_gathers_fx_bucket_size_determinator, config.bucket_all_gathers_fx))
        collectives_bucketing = True
    if collectives_bucketing:
        stable_topological_sort(gm.graph)
    GraphTransformObserver(gm, 'reinplace_inplaceable_ops').apply_graph_pass(functools.partial(reinplace_inplaceable_ops, fake_tensor_updater))
    GraphTransformObserver(gm, 'decompose_triton_kernel_wrapper_functional').apply_graph_pass(decompose_triton_kernel_wrapper_functional)
    GraphTransformObserver(gm, 'decompose_auto_functionalized').apply_graph_pass(decompose_auto_functionalized)
    if not torch._dynamo.config.skip_fsdp_hooks:
        GraphTransformObserver(gm, 'reinplace_fsdp_all_gather').apply_graph_pass(comms.reinplace_fsdp_all_gather)
    GraphTransformObserver(gm, 'decompose_scan_to_while_loop').apply_gm_pass(decompose_scan_to_while_loop)
    GraphTransformObserver(gm, 'decompose_map_to_while_loop').apply_gm_pass(decompose_map_to_while_loop)
    gm.recompile()
    gm.graph.lint()

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if self.fn is object and name == '__setattr__':
        assert len(args) == 3
        assert len(kwargs) == 0
        (obj, name_var, val) = args
        obj = obj.realize()
        if isinstance(obj, UserDefinedObjectVariable) and tx.output.side_effects.is_attribute_mutation(obj) and name_var.is_python_constant():
            return obj.method_setattr_standard(tx, name_var, val)
    if name == '__new__':
        if self.fn is object and len(args) == 1:
            assert len(kwargs) == 0
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is dict and len(args) == 1 and (not kwargs):
            dict_vt = ConstDictVariable({}, dict, mutation_type=ValueMutationNew())
            if isinstance(args[0], BuiltinVariable) and args[0].fn is dict:
                return dict_vt
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is tuple and len(args) == 2 and args[1].has_force_unpack_var_sequence(tx) and (not kwargs):
            if isinstance(args[0], BuiltinVariable) and args[0].fn is tuple:
                init_args = args[1].force_unpack_var_sequence(tx)
                return variables.TupleVariable(init_args, mutation_type=ValueMutationNew())
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
        if self.fn is list:
            list_vt = ListVariable([], mutation_type=ValueMutationNew())
            if isinstance(args[0], BuiltinVariable) and args[0].fn is list:
                return list_vt
            return tx.output.side_effects.track_new_user_defined_object(self, args[0], args[1:])
    if self.fn is float and len(args) == 1 and (name in ('fromhex', 'hex')):
        if <MASK>:
            try:
                fn = getattr(float, name)
                res = fn(args[0].as_python_constant())
                return variables.ConstantVariable.create(res)
            except (OverflowError, ValueError) as e:
                raise_observed_exception(type(e), tx, args=list(map(ConstantVariable.create, e.args)))
    if self.fn is object and name == '__init__':
        return variables.ConstantVariable(None)
    if self.fn is dict and name == 'fromkeys':
        return BuiltinVariable.call_custom_dict_fromkeys(tx, dict, *args, **kwargs)
    if self.fn is dict:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in dict_methods:
            if isinstance(args[0], variables.UserDefinedDictVariable):
                return args[0]._dict_vt.call_method(tx, name, args[1:], kwargs)
            elif isinstance(args[0], variables.ConstDictVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is set:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in set_methods:
            if isinstance(args[0], variables.UserDefinedSetVariable):
                return args[0]._set_vt.call_method(tx, name, args[1:], kwargs)
            elif isinstance(args[0], variables.SetVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is frozenset:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in frozenset_methods:
            if isinstance(args[0], variables.FrozensetVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is str and len(args) >= 1:
        resolved_fn = getattr(self.fn, name)
        if resolved_fn in str_methods:
            if isinstance(args[0], ConstantVariable):
                return args[0].call_method(tx, name, args[1:], kwargs)
    if self.fn is float and len(args) >= 1:
        if isinstance(args[0], ConstantVariable):
            return ConstantVariable.create(getattr(float, name)(args[0].as_python_constant()))
    return super().call_method(tx, name, args, kwargs)

@method_with_native_function
def gen_one(self, f: NativeFunction) -> str | None:
    assert not f.manual_kernel_registration
    if self.target is Target.REGISTRATION and (not self.selector.is_native_function_selected(f)):
        return None
    if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional and f.func.kind() is SchemaKind.out:
        return None
    cpp_sig_group = CppSignatureGroup.from_native_function(f, method=False, fallback_binding=False)
    kern = self.backend_index.get_kernel(f)
    sig = NativeSignature(f.func, prefix=f'wrapper_{self.backend_index.dispatch_key}_', symint=kern is not None and kern.supports_symint())
    if self.target is Target.NAMESPACED_DECLARATION:
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += f'TORCH_API {cpp_sig.decl()};\n'
        return result
    elif <MASK>:

        def generate_defn(cpp_sig: CppSignature) -> str:
            return f"\n{cpp_sig.defn()} {{\nreturn {sig.name()}({', '.join((e.expr for e in translate(cpp_sig.arguments(), sig.arguments())))});\n}}\n"
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += generate_defn(cpp_sig)
        return result
    elif self.target is Target.ANONYMOUS_DEFINITION:
        k = f.func.kind()
        sig_body = []
        context: list[Binding | Expr] = list(sig.arguments())
        if self.backend_index.dispatch_key is DispatchKey.Meta:
            class_name = f'structured_{meta.name(self.g)}_meta_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        elif self.backend_index.dispatch_key is DispatchKey.CompositeExplicitAutogradNonFunctional:
            class_name = f'structured_{meta.name(self.g)}_default_backend_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        else:
            metadata = self.backend_index.get_kernel(self.g)
            assert metadata is not None
            class_name = f'structured_{metadata.kernel}_{k.name}'
            parent_class = f'{metadata.cpp_namespace}::structured_{metadata.kernel}'
        if self.backend_index.device_guard:
            device_check_args = itertools.chain(f.func.arguments.out, f.func.arguments.flat_positional)
            sig_body.append(RegisterDispatchKey.gen_device_check(f.device_check, list(device_check_args), sig.name()))
        if k is SchemaKind.functional:
            sig_body.append(f'{class_name} op;')
        elif k is SchemaKind.inplace:
            sig_body.append(f'{class_name} op(self);')
        elif k is SchemaKind.out:
            out_args_str = ', '.join((a.name for a in f.func.arguments.out))
            sig_body.append(f'{class_name} op({out_args_str});')
        meta_exprs = ', '.join((e.expr for e in translate(context, structured.meta_arguments(self.g), method=False)))
        if self.g.out.precomputed:
            sig_body.append(f'auto precompute = op.meta({meta_exprs});')
            precomputed_values = [*self.g.out.precomputed.replace.values(), self.g.out.precomputed.add]
            for precomputed_elems in precomputed_values:
                context.extend((Expr(expr=f'precompute.{arg.name}', type=structured.argument_type(arg, binds=arg.name)) for arg in precomputed_elems))
            sig_body.append('(void)precompute;')
        else:
            sig_body.append(f'op.meta({meta_exprs});')
        out_args = structured.out_arguments(self.g)
        for (i, out_arg) in enumerate(out_args):
            assert ConstRefCType(BaseCType(tensorT)) == out_arg.nctype.type
            if k is SchemaKind.out:
                expr = f'op.maybe_get_output({i})'
            else:
                expr = f'op.outputs_[{i}]'
            context.append(Expr(expr=expr, type=NamedCType(out_arg.nctype.name, MutRefCType(BaseCType(tensorT)))))
        if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional:
            out_sig_group = CppSignatureGroup.from_native_function(self.g.out, method=False, fallback_binding=f.manual_cpp_binding)
            out_sig = out_sig_group.most_faithful_signature()
            api_name = out_sig.name()
            out_exprs = ', '.join((e.expr for e in translate(context, out_sig.arguments(), method=False)))
            sig_body.append(f'at::{api_name}({out_exprs});')
        elif self.backend_index.dispatch_key != DispatchKey.Meta:
            impl_exprs = ', '.join((e.expr for e in translate(context, structured.impl_arguments(self.g), method=False)))
            sig_body.append(f'op.impl({impl_exprs});')
        if k is SchemaKind.out or k is SchemaKind.inplace:
            for i in range(len(f.func.returns)):
                sig_body.append(f'if (op.proxy_outputs_[{i}].has_value()) op.outputs_[{i}].get().copy_(*op.proxy_outputs_[{i}]);')
        if k is SchemaKind.functional:
            if len(f.func.returns) == 1:
                ret_expr = 'std::move(op.outputs_[0])'
            else:
                moved = ', '.join((f'std::move(op.outputs_[{i}])' for i in range(len(f.func.returns))))
                ret_expr = f'std::make_tuple({moved})'
        elif k is SchemaKind.inplace:
            ret_expr = 'self'
        elif k is SchemaKind.out:
            if len(f.func.returns) == 1:
                ret_expr = f.func.arguments.out[0].name
            else:
                refs = ', '.join((a.name for a in f.func.arguments.out))
                ret_expr = f'std::forward_as_tuple({refs})'
        sig_body.append(f'return {ret_expr};')
        sig_body_str = '\n'.join(sig_body)
        return f'{self.gen_class(f, k, class_name=class_name, parent_class=parent_class, generate_super=self.g.out.structured_inherits is not None)}\n\n{sig.defn()} {{\n{sig_body_str}\n}}\n'
    elif self.target is Target.REGISTRATION:
        return f'm.impl("{f.func.name}", TORCH_FN({sig.name()}));'
    else:
        assert_never(self.target)
        return None

def _scalar_heuristic(arr, elem):
    """
            Return whether `elem` is a scalar result of indexing `arr`, or None
            if undecidable without promoting nomask to a full mask
            """
    if <MASK>:
        return True
    elif arr.dtype.type is np.object_:
        if arr.dtype is not elem.dtype:
            return True
    elif type(arr).__getitem__ == ndarray.__getitem__:
        return False
    return None

def can_fuse_vertical(self, node1, node2):
    if node2.is_template():
        return False
    if <MASK>:
        (template_fusion_supported, _) = template_fusion_with_epilogues_supported(node1, [node2])
        return not node2.is_reduction() and template_fusion_supported
    return self._can_fuse_horizontal_impl(node1, node2) and (not node1.is_reduction()) or self.can_fuse_vertical_outer_loop(node1, node2)

def _gather(strategy, value):
    """Gathers a single value."""
    if not isinstance(value, values.DistributedValues):
        value = values.PerReplica([ops.convert_to_tensor(value)])
    if <MASK>:
        return array_ops_stack.stack(value._values)
    assert len(strategy.extended.worker_devices) == len(value._values)
    inputs = [array_ops.expand_dims_v2(v, axis=0) for v in value._values]
    return strategy.gather(values.PerReplica(inputs), axis=0)

def test_converted_call_method(self):

    class TestClass:

        def __init__(self, x):
            self.x = x

        def test_method(self):
            if <MASK>:
                return -self.x
            return self.x
    tc = TestClass(constant_op.constant(-1))
    x = api.converted_call(tc.test_method, (), None, options=DEFAULT_RECURSIVE)
    self.assertEqual(1, self.evaluate(x))

def _parse_tables(self, document, match, attrs):
    element_name = 'table'
    tables = document.find_all(element_name, attrs=attrs)
    if not tables:
        raise ValueError('No tables found')
    result = []
    unique_tables = set()
    tables = self._handle_hidden_tables(tables, 'attrs')
    for table in tables:
        if <MASK>:
            for elem in table.find_all('style'):
                elem.decompose()
            for elem in table.find_all(style=re.compile('display:\\s*none')):
                elem.decompose()
        if table not in unique_tables and table.find(string=match) is not None:
            result.append(table)
        unique_tables.add(table)
    if not result:
        raise ValueError(f'No tables found matching pattern {match.pattern!r}')
    return result

def is_empty(x):
    """Check whether a possibly nested structure is empty."""
    if <MASK>:
        return False
    if isinstance(x, collections_abc.Mapping):
        return is_empty(list(x.values()))
    for item in x:
        if not is_empty(item):
            return False
    return True

def extension_extract_fn(pathname):
    ext = os.path.splitext(pathname)[1]
