@_onnx_symbolic('aten::flatten')
@symbolic_helper.quantized_args(True, False, False)
@symbolic_helper.parse_args('v', 'i', 'i')
def flatten(g: jit_utils.GraphContext, input, start_dim, end_dim):
    dim = symbolic_helper._get_tensor_rank(input)
    if dim == 1:
        return input
    if <MASK>:
        if end_dim == -1 or (dim is not None and end_dim == dim - 1):
            return g.op('Flatten', input, axis_i=start_dim)
    elif start_dim == 0:
        if end_dim == -2 or (dim is not None and end_dim == dim - 2):
            return g.op('Flatten', input, axis_i=end_dim + 1)
    if dim is None:
        return symbolic_helper._unimplemented('dim', 'ONNX and PyTorch use different strategies to split the input. Input rank must be known at export time.')
    if end_dim < 0:
        end_dim = dim + end_dim
    return symbolic_helper._flatten_helper(g, input, start_dim, end_dim, dim)

def _batch_gather(params, indices, axis, batch_dims):
    """Helper that implements the body for ragged gather() when batch_dims>0.

  Args:
    params: The tensor from which to gather values.
    indices: The indices of values to gather.
    axis: The axis in `params` to gather `indices` from.
    batch_dims: The number of batch dimensions.

  Returns:
    A potentially ragged tensor.
  """
    if <MASK>:
        raise ValueError('batch shape from indices %s does not match params shape %s' % (indices.shape[:batch_dims], params.shape))
    if batch_dims > 1:
        if not isinstance(params, ragged_tensor.RaggedTensor):
            if indices.uniform_row_length is None:
                raise ValueError('batch shape from indices does not match params shape: ragged indices dimension corresponds to uniform params dimension')
            params = ragged_tensor.RaggedTensor.from_tensor(params, ragged_rank=1, row_splits_dtype=indices.row_splits.dtype)
        if not isinstance(indices, ragged_tensor.RaggedTensor):
            if params.uniform_row_length is None:
                raise ValueError('batch shape from indices does not match params shape: ragged params dimension corresponds to uniform indices dimension')
            indices = ragged_tensor.RaggedTensor.from_tensor(indices, ragged_rank=1, row_splits_dtype=params.row_splits.dtype)
        return params.with_values(_gather(params.values, indices.values, axis - 1, batch_dims - 1))
    if axis > 1:
        if not isinstance(indices, ragged_tensor.RaggedTensor):
            adjusted_indices = params.with_values(array_ops.repeat(indices, params.row_lengths(), 0))
        else:
            if not isinstance(params, ragged_tensor.RaggedTensor):
                params = ragged_tensor.RaggedTensor.from_tensor(params, ragged_rank=1, row_splits_dtype=indices.row_splits.dtype)
            adjusted_indices = _gather(indices, params.with_values(array_ops.repeat(math_ops.range(params.nrows()), params.row_lengths())), 0, 0)
        return _batch_gather(params, adjusted_indices, axis, batch_dims + 1)
    if indices.shape.rank is None:
        raise ValueError('rank(indices) must be known statically')
    assert batch_dims == 1
    flat_params = _flatten_dims_0_and_1(params)
    adjustments = _row_starts(params, indices.dtype)
    adjustments = _increase_rank_to(adjustments, indices.shape.ndims)
    adjusted_indices = indices + adjustments
    return _gather(flat_params, adjusted_indices, axis - 1, 0)

def restore(self, restored_tensors, restored_shapes):
    """Restores tensors. Raises ValueError if incompatible shape found."""
    restored_tensor = restored_tensors[0]
    if <MASK>:
        restored_tensor = array_ops.reshape(restored_tensor, restored_shapes[0])
    with ops.device(self._var_device):
        restored_tensor = array_ops.identity(restored_tensor)
        try:
            assigned_variable = resource_variable_ops.shape_safe_assign_variable_handle(self.handle_op, self._var_shape, restored_tensor)
        except ValueError as e:
            raise ValueError(f'Received incompatible tensor with shape {restored_tensor.shape} when attempting to restore variable with shape {self._var_shape} and name {self.name}.') from e
        return assigned_variable

def get_table(self, table_name: str, schema: str | None=None) -> Table:
    from sqlalchemy import Numeric, Table
    schema = schema or self.meta.schema
    tbl = Table(table_name, self.meta, autoload_with=self.con, schema=schema)
    for column in tbl.columns:
        if <MASK>:
            column.type.asdecimal = False
    return tbl

def inner():
    nonlocal result, args, kwargs
    (full_backward_hooks, non_full_backward_hooks) = ([], [])
    backward_pre_hooks = []
    if self._backward_pre_hooks or _global_backward_pre_hooks:
        backward_pre_hooks = self._get_backward_pre_hooks()
    if self._backward_hooks or _global_backward_hooks:
        (full_backward_hooks, non_full_backward_hooks) = self._get_backward_hooks()
    if <MASK>:
        for (hook_id, hook) in (*_global_forward_pre_hooks.items(), *self._forward_pre_hooks.items()):
            if hook_id in self._forward_pre_hooks_with_kwargs:
                args_kwargs_result = hook(self, args, kwargs)
                if args_kwargs_result is not None:
                    if isinstance(args_kwargs_result, tuple) and len(args_kwargs_result) == 2:
                        (args, kwargs) = args_kwargs_result
                    else:
                        raise RuntimeError(f'forward pre-hook must return None or a tuple of (new_args, new_kwargs), but got {args_kwargs_result}.')
            else:
                args_result = hook(self, args)
                if args_result is not None:
                    if not isinstance(args_result, tuple):
                        args_result = (args_result,)
                    args = args_result
    bw_hook = None
    if full_backward_hooks or backward_pre_hooks:
        bw_hook = BackwardHook(self, full_backward_hooks, backward_pre_hooks)
        args = bw_hook.setup_input_hook(args)
    result = forward_call(*args, **kwargs)
    if _global_forward_hooks or self._forward_hooks:
        for (hook_id, hook) in (*_global_forward_hooks.items(), *self._forward_hooks.items()):
            if hook_id in self._forward_hooks_always_called or hook_id in _global_forward_hooks_always_called:
                called_always_called_hooks.add(hook_id)
            if hook_id in self._forward_hooks_with_kwargs or hook_id in _global_forward_hooks_with_kwargs:
                hook_result = hook(self, args, kwargs, result)
            else:
                hook_result = hook(self, args, result)
            if hook_result is not None:
                result = hook_result
    if bw_hook:
        if not isinstance(result, (torch.Tensor, tuple)):
            warnings.warn(f'For backward hooks to be called, module output should be a Tensor or a tuple of Tensors but received {type(result)}')
        result = bw_hook.setup_output_hook(result)
    if non_full_backward_hooks:
        var = result
        while not isinstance(var, torch.Tensor):
            if isinstance(var, dict):
                var = next((v for v in var.values() if isinstance(v, torch.Tensor)))
            else:
                var = var[0]
        grad_fn = var.grad_fn
        if grad_fn is not None:
            for hook in non_full_backward_hooks:
                grad_fn.register_hook(_WrappedHook(hook, self))
            self._maybe_warn_non_full_backward_hook(args, result, grad_fn)
    return result

@register_make_test_function()
def make_mirror_pad_tests(options):
    """Make a set of tests to do mirror_pad."""
    test_parameters = [{'input_shape': [[2, 3]], 'padding_matrix': [[[1, 1], [2, 1]]], 'mode': ['REFLECT'], 'type': ['const'], 'fully_quantize': [True, False]}, {'input_shape': [[2, 3]], 'padding_matrix': [[[1, 1], [1, 1]]], 'mode': ['REFLECT'], 'type': ['const'], 'fully_quantize': [False]}, {'input_shape': [[2, 3]], 'padding_matrix': [[[1, 1], [2, 1]]], 'mode': ['SYMMETRIC'], 'type': ['placeholder'], 'fully_quantize': [False]}, {'input_shape': [[2, 3]], 'padding_matrix': [[[1, 1], [2, 1]]], 'mode': ['REFLECT'], 'type': ['placeholder'], 'fully_quantize': [False]}, {'input_shape': [[3]], 'padding_matrix': [[[0, 2]]], 'mode': ['SYMMETRIC'], 'type': ['placeholder'], 'fully_quantize': [False]}, {'input_shape': [[3]], 'padding_matrix': [[[0, 2]]], 'mode': ['SYMMETRIC'], 'type': ['const'], 'fully_quantize': [False]}, {'input_shape': [[3]], 'padding_matrix': [[[0, 2]]], 'mode': ['REFLECT'], 'type': ['const'], 'fully_quantize': [False, True], 'quant_16x8': [False, True]}, {'input_shape': [[3, 2, 4, 5]], 'padding_matrix': [[[1, 1], [2, 2], [1, 1], [1, 1]]], 'mode': ['SYMMETRIC'], 'type': ['placeholder'], 'fully_quantize': [False]}]

    def build_graph(parameters):
        """Build the graph for the test case."""
        input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=parameters['input_shape'])
        if parameters['type'] != 'const' and (not parameters['fully_quantize']):
            padding_matrix = tf.compat.v1.placeholder(dtype=tf.int32, name='padding', shape=[len(parameters['input_shape']), 2])
            input_tensors = [input_tensor, padding_matrix]
        else:
            padding_matrix = tf.constant(np.array(parameters['padding_matrix']))
            input_tensors = [input_tensor]
        output = tf.pad(tensor=input_tensor, paddings=padding_matrix, mode=parameters['mode'])
        return (input_tensors, [output])

    def build_inputs(parameters, sess, inputs, outputs):
        if not parameters['fully_quantize']:
            input_values = [create_tensor_data(tf.float32, parameters['input_shape'])]
        else:
            input_values = [create_tensor_data(tf.float32, parameters['input_shape'], min_value=-1, max_value=1)]
        if <MASK>:
            input_values.append(np.array(parameters['padding_matrix']))
        return (input_values, sess.run(outputs, feed_dict=dict(zip(inputs, input_values))))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs)

