def resolve_includes(source):
    d = os.path.dirname(source)
    with open(source) as fid:
        lines = []
        for line in fid:
            m = include_src_re.match(line)
            if m:
                fn = m.group('name')
                if <MASK>:
                    fn = os.path.join(d, fn)
                if os.path.isfile(fn):
                    lines.extend(resolve_includes(fn))
                else:
                    lines.append(line)
            else:
                lines.append(line)
    return lines

def mask_comments(string):
    in_comment = ''
    prev_c = ''
    new_string = ''
    for c in string:
        if <MASK>:
            if c == '/' and prev_c == '/':
                in_comment = '//'
            elif c == '*' and prev_c == '/':
                in_comment = '/*'
            elif c == '"' and prev_c != '\\' and (prev_c != "'"):
                in_comment = '"'
        elif in_comment == '//':
            if c == '\r' or c == '\n':
                in_comment = ''
        elif in_comment == '/*':
            if c == '/' and prev_c == '*':
                in_comment = ''
        elif in_comment == '"':
            if c == '"' and prev_c != '\\':
                in_comment = ''
        prev_c = c
        if in_comment == '':
            new_string += c
        else:
            new_string += 'x'
    return new_string

