def default_deepcopy(self, memo):
    obj = memo.get(id(self), None)
    if <MASK>:
        return obj
    replica = self.__new__(self.__class__)
    memo[id(self)] = replica
    replica.__dict__ = deepcopy(self.__dict__, memo)
    slots_to_save = copyreg._slotnames(self.__class__)
    for slot in slots_to_save:
        if hasattr(self, slot):
            setattr(replica, slot, deepcopy(getattr(self, slot), memo))
    return replica

def _replace_pattern(gm: GraphModule, pattern: Union[Callable, Graph, GraphModule], replacement: Union[Callable, Graph, GraphModule, None]=None, match_filters: Optional[list[Callable[['InternalMatch', Graph, Graph], bool]]]=None, ignore_literals: bool=False, replacement_callback: Optional[Callable[['InternalMatch', Graph, Graph], Graph]]=None, node_name_match: str='') -> list[ReplacedPatterns]:
    from torch.fx.passes.utils.matcher_utils import InternalMatch, SubgraphMatcher
    if match_filters is None:
        match_filters = []
    original_graph: Graph = gm.graph
    if isinstance(pattern, GraphModule):
        pattern_graph = pattern.graph
    elif isinstance(pattern, Graph):
        pattern_graph = pattern
    else:
        pattern_graph = symbolic_trace(pattern).graph
    matcher = SubgraphMatcher(pattern_graph, match_output=False, match_placeholder=False, remove_overlapping_matches=True, ignore_literals=ignore_literals)
    _matches: list[InternalMatch] = matcher.match(original_graph, node_name_match=node_name_match)
    _matches = [m for m in _matches if all((match_filter(m, original_graph, pattern_graph) for match_filter in match_filters))]
    if isinstance(replacement, GraphModule):
        common_replacement_graph = replacement.graph
    elif isinstance(replacement, Graph):
        common_replacement_graph = replacement
    elif callable(replacement):
        common_replacement_graph = symbolic_trace(replacement).graph
    else:
        assert replacement_callback is not None, 'Must provide either a replacement GraphModule or a replacement callback'
        common_replacement_graph = None
    match_changed_node: dict[Node, Node] = {}
    match_and_replacements = []
    for match in _matches:
        if replacement_callback is not None:
            replacement_graph = replacement_callback(match, original_graph, pattern_graph)
        else:
            assert common_replacement_graph is not None, 'Must provide either a replacement GraphModule or a replacement callback'
            replacement_graph = common_replacement_graph
        replacement_placeholders = [n for n in replacement_graph.nodes if n.op == 'placeholder']
        assert len(match.placeholder_nodes) == len(replacement_placeholders)
        val_map: dict[Node, Node] = {}
        for (rn, gn) in zip(replacement_placeholders, match.placeholder_nodes):
            if isinstance(gn, Node):
                val_map[rn] = match_changed_node.get(gn, gn)
                if gn != val_map[rn]:
                    gn_ind = match.placeholder_nodes.index(gn)
                    match.placeholder_nodes[gn_ind] = match_changed_node[gn]
                    map_key = list(match.nodes_map.keys())[list(match.nodes_map.values()).index(gn)]
                    match.nodes_map[map_key] = match_changed_node[gn]
            else:
                val_map[rn] = gn
        user_nodes: set[Node] = set()
        for n in match.returning_nodes:
            user_nodes.update(n.users)
        first_user_node = None
        if len(user_nodes) == 0:
            first_user_node = None
        elif len(user_nodes) == 1:
            first_user_node = next(iter(user_nodes))
        else:
            for n in original_graph.nodes:
                if n in user_nodes:
                    first_user_node = n
                    break
        first_next_node = None
        if <MASK>:
            next_node = None
            for n in reversed(original_graph.nodes):
                if n in match.returning_nodes:
                    first_next_node = next_node
                    break
                else:
                    next_node = n
        insert_point = first_user_node if first_user_node is not None else first_next_node
        assert insert_point is not None, "The insert point can't be None"
        with original_graph.inserting_before(insert_point):
            copied_returning_nodes = original_graph.graph_copy(replacement_graph, val_map)
        if isinstance(copied_returning_nodes, Node):
            copied_returning_nodes = (copied_returning_nodes,)
        replacement_nodes: list[Node] = [v for v in val_map.values() if v not in match.placeholder_nodes]
        assert len(match.returning_nodes) == len(copied_returning_nodes)
        for (gn, copied_node) in zip(match.returning_nodes, copied_returning_nodes):
            gn.replace_all_uses_with(copied_node)
            match_changed_node[gn] = copied_node
        for node in reversed(pattern_graph.nodes):
            if node.op != 'placeholder' and node.op != 'output':
                gn = match.nodes_map[node]
                gm.graph.erase_node(gn)
        match_and_replacements.append(ReplacedPatterns(anchor=match.anchors[0], nodes_map=match.nodes_map, replacements=replacement_nodes))
    gm.recompile()
    if isinstance(replacement, torch.nn.Module):
        _replace_attributes(gm, replacement)
    return match_and_replacements

@register.tag
def cycle(parser, token):
    """
    Cycle among the given strings each time this tag is encountered.

    Within a loop, cycles among the given strings each time through
    the loop::

        {% for o in some_list %}
            <tr class="{% cycle 'row1' 'row2' %}">
                ...
            </tr>
        {% endfor %}

    Outside of a loop, give the values a unique name the first time you call
    it, then use that name each successive time through::

            <tr class="{% cycle 'row1' 'row2' 'row3' as rowcolors %}">...</tr>
            <tr class="{% cycle rowcolors %}">...</tr>
            <tr class="{% cycle rowcolors %}">...</tr>

    You can use any number of values, separated by spaces. Commas can also
    be used to separate values; if a comma is used, the cycle values are
    interpreted as literal strings.

    The optional flag "silent" can be used to prevent the cycle declaration
    from returning any value::

        {% for o in some_list %}
            {% cycle 'row1' 'row2' as rowcolors silent %}
            <tr class="{{ rowcolors }}">{% include "subtemplate.html " %}</tr>
        {% endfor %}
    """
    args = token.split_contents()
    if len(args) < 2:
        raise TemplateSyntaxError("'cycle' tag requires at least two arguments")
    if len(args) == 2:
        name = args[1]
        if <MASK>:
            raise TemplateSyntaxError("No named cycles in template. '%s' is not defined" % name)
        if name not in parser._named_cycle_nodes:
            raise TemplateSyntaxError("Named cycle '%s' does not exist" % name)
        return parser._named_cycle_nodes[name]
    as_form = False
    if len(args) > 4:
        if args[-3] == 'as':
            if args[-1] != 'silent':
                raise TemplateSyntaxError("Only 'silent' flag is allowed after cycle's name, not '%s'." % args[-1])
            as_form = True
            silent = True
            args = args[:-1]
        elif args[-2] == 'as':
            as_form = True
            silent = False
    if as_form:
        name = args[-1]
        values = [parser.compile_filter(arg) for arg in args[1:-2]]
        node = CycleNode(values, name, silent=silent)
        if not hasattr(parser, '_named_cycle_nodes'):
            parser._named_cycle_nodes = {}
        parser._named_cycle_nodes[name] = node
    else:
        values = [parser.compile_filter(arg) for arg in args[1:]]
        node = CycleNode(values)
    parser._last_cycle_node = node
    return node

def argumenttype_type(t: Type, *, mutable: bool, binds: ArgName) -> NamedCType:
    r = cpp.valuetype_type(t, symint=False, binds=binds, mutable=mutable)
    if r is not None:
        return r
    if isinstance(t, BaseType):
        if t.name == BaseTy.Tensor:
            return NamedCType(binds, ConstRefCType(BaseCType(tensorT)))
        elif t.name == BaseTy.Scalar:
            return NamedCType(binds, ConstRefCType(BaseCType(scalarT)))
        else:
            raise AssertionError(f'base type should have been value type {t}')
    elif isinstance(t, OptionalType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, BaseCType(optionalTensorRefT))
        elif t.elem == BaseType(BaseTy.Scalar):
            return NamedCType(binds, BaseCType(optionalScalarRefT))
        elif isinstance(t.elem, ListType) and str(t.elem.elem) == 'int':
            return NamedCType(binds, BaseCType(optionalIntArrayRefT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, OptionalCType(elem.type))
    elif isinstance(t, ListType):
        if t.elem == BaseType(BaseTy.Tensor):
            return NamedCType(binds, ConstRefCType(BaseCType(iTensorListRefT)))
        elif t.elem == OptionalType(BaseType(BaseTy.Tensor)):
            return NamedCType(binds, BaseCType(iOptTensorListRefT))
        elif str(t.elem) == 'int':
            return NamedCType(binds, BaseCType(intArrayRefT))
        elif <MASK>:
            return NamedCType(binds, BaseCType(dimnameListT))
        elem = argumenttype_type(t.elem, mutable=mutable, binds=binds)
        return NamedCType(binds, ArrayRefCType(elem.type))
    else:
        raise AssertionError(f'unrecognized type {repr(t)}')

def __init__(self, optimizer: Optimizer, schedulers: list[LRScheduler], milestones: list[int], last_epoch: int=-1) -> None:
    if len(schedulers) < 1:
        raise ValueError(f'{self.__class__.__name__} expects at least one scheduler, but got no scheduler.')
    for (scheduler_idx, scheduler) in enumerate(schedulers):
        if not hasattr(scheduler, 'optimizer'):
            raise TypeError(f'{self.__class__.__name__} at index {scheduler_idx} should have `optimizer` as its attribute.')
        if <MASK>:
            raise ValueError(f'{self.__class__.__name__} does not support `ReduceLROnPlateau` scheduler as it requires additional kwargs to be specified when calling `step`, but got one at index {scheduler_idx} in the given schedulers sequence.')
        if optimizer != scheduler.optimizer:
            raise ValueError(f'{self.__class__.__name__} expects all schedulers to belong to the same optimizer, but got scheduler {scheduler.__class__.__name__} at index {scheduler_idx} has {scheduler.optimizer}, which is different from {optimizer.__class__.__name__}.')
    if len(milestones) != len(schedulers) - 1:
        raise ValueError(f'Sequential Schedulers expects number of schedulers provided to be one more than the number of milestone points, but got number of schedulers {len(schedulers)} and the number of milestones to be equal to {len(milestones)}')
    self._schedulers = schedulers
    self._milestones = milestones
    self.last_epoch = last_epoch + 1
    self.optimizer = optimizer
    for group in self.optimizer.param_groups:
        _update_param_group_val(group, 'lr', group['initial_lr'])
    self.recursive_undo()
    self._schedulers[0]._initial_step()
    self._last_lr = schedulers[0].get_last_lr()

def get_select(self, with_col_aliases=False):
    """
        Return three values:
        - a list of 3-tuples of (expression, (sql, params), alias)
        - a klass_info structure,
        - a dictionary of annotations

        The (sql, params) is what the expression will produce, and alias is the
        "AS alias" for the column (possibly None).

        The klass_info structure contains the following information:
        - The base model of the query.
        - Which columns for that model are present in the query (by
          position of the select clause).
        - related_klass_infos: [f, klass_info] to descent into

        The annotations is a dictionary of {'attname': column position} values.
        """
    select = []
    klass_info = None
    annotations = {}
    assert not (self.query.select and self.query.default_cols)
    select_mask = self.query.get_select_mask()
    if self.query.default_cols:
        cols = self.get_default_columns(select_mask)
    else:
        cols = self.query.select
    selected = []
    select_fields = None
    if self.query.selected is None:
        selected = [*((alias, RawSQL(*args)) for (alias, args) in self.query.extra_select.items()), *((None, col) for col in cols), *self.query.annotation_select.items()]
        select_fields = list(range(len(self.query.extra_select), len(self.query.extra_select) + len(cols)))
    else:
        select_fields = []
        for (index, (alias, expression)) in enumerate(self.query.selected.items()):
            if isinstance(expression, str):
                expression = self.query.annotations[expression]
            elif isinstance(expression, int):
                select_fields.append(index)
                expression = cols[expression]
            if <MASK>:
                alias = None
            selected.append((alias, expression))
    if select_fields:
        klass_info = {'model': self.query.model, 'select_fields': select_fields}
    for (select_idx, (alias, expression)) in enumerate(selected):
        if alias:
            annotations[alias] = select_idx
        select.append((expression, alias))
    if self.query.select_related:
        related_klass_infos = self.get_related_selections(select, select_mask)
        klass_info['related_klass_infos'] = related_klass_infos

        def get_select_from_parent(klass_info):
            for ki in klass_info['related_klass_infos']:
                if ki['from_parent']:
                    ki['select_fields'] = klass_info['select_fields'] + ki['select_fields']
                get_select_from_parent(ki)
        get_select_from_parent(klass_info)
    ret = []
    col_idx = 1
    for (col, alias) in select:
        try:
            (sql, params) = self.compile(col)
        except EmptyResultSet:
            empty_result_set_value = getattr(col, 'empty_result_set_value', NotImplemented)
            if empty_result_set_value is NotImplemented:
                (sql, params) = ('0', ())
            else:
                (sql, params) = self.compile(Value(empty_result_set_value))
        except FullResultSet:
            (sql, params) = self.compile(Value(True))
        else:
            (sql, params) = col.select_format(self, sql, params)
        if alias is None and with_col_aliases:
            alias = f'col{col_idx}'
            col_idx += 1
        ret.append((col, (sql, params), alias))
    return (ret, klass_info, annotations)

@property
def grad_state(self):
    if <MASK>:
        return self.GetWhileContext().grad_state
    return None

def run_mod_and_filter_tensor_outputs(mod, inputs, running_what):
    try:
        if <MASK>:
            outs = wrap_retval(mod(**inputs))
        else:
            outs = wrap_retval(mod(*_clone_inputs(inputs)))
        outs = [out for out in outs if isinstance(out, torch.Tensor)]
        return outs
    except Exception as e:
        (graph_diff_errors, tensor_compare_errors) = graph_diagnostic_info()
        msg = f'encountered an exception while running the {running_what} with test inputs.\nException:\n{indent(str(e))}'
        raise TracingCheckError(graph_diff_errors, tensor_compare_errors, extra_msg=msg) from e

def _lift_basic_symbols(self, example_value: Union[torch.SymInt, torch.Tensor], src: Optional[Source]) -> None:

    def _lift_symbols_in_symint(s: Union[int, torch.SymInt], source: Optional[Source], before: bool=False) -> None:
        if not is_symbolic(s):
            return
        assert isinstance(s, torch.SymInt)
        self_to_be_bound = self.lookup_unbound_symbols(s)
        if len(self_to_be_bound) == 0:
            return
        if <MASK>:
            self.parent._lift_basic_symbols(s, source)
            for s0 in self_to_be_bound:
                parent_proxy = self.parent.bound_symbols[s0]
                example_val = parent_proxy.node.meta['example_value']
                assert isinstance(example_val, torch.SymInt)
                ph = self.create_graph_input(str(s0), type(example_val), example_val, before=before, source=source)
                log.debug('_lift_symbols_in_symint %s from %s at debug_level %s', s0, source.name() if source is not None else 'subgraph inputs', self.debug_level)
                self.lifted_freevars[parent_proxy] = ph
        else:
            assert len(self_to_be_bound) == 1, f'For root tracer, we only expect to bind basic symbols (compound symbols should be cached before) but got unbound symbols {self_to_be_bound} in {s}'
            assert source is not None, f"Source of '{s}' is None when lifting it to input of top-level. If it's an unbacked symbol, this could be because it's not tracked with lazy_bind_unbacked_symbols. Otherwise, should provide a source when create_graph_input for `{s}` at root tracer."
            s0 = next(iter(self_to_be_bound))
            ph = self.create_graph_input(str(s0), type(s), s, before=before, source=source)
            log.debug('_lift_symbols_in_symint %s from %s at debug_level %s', s, source.name() if source is not None else 'subgraph inputs', self.debug_level)
            ph.node.meta['grapharg'] = GraphArg(source, s, pass_arg_as_tensor=False, fake_tensor=None, is_tensor=False)
    if isinstance(example_value, torch.Tensor):
        for (i, s) in enumerate(example_value.size()):
            _lift_symbols_in_symint(s, TensorPropertySource(src, TensorProperty.SIZE, i) if src is not None else None, before=True)
        if example_value.layout is torch.strided:
            for (i, s) in enumerate(example_value.stride()):
                _lift_symbols_in_symint(s, TensorPropertySource(src, TensorProperty.STRIDE, i) if src is not None else None, before=True)
            _lift_symbols_in_symint(example_value.storage_offset(), TensorPropertySource(src, TensorProperty.STORAGE_OFFSET) if src is not None else None, before=True)
        elif example_value.layout is torch.sparse_coo:
            self._lift_basic_symbols(example_value._indices(), src)
            self._lift_basic_symbols(example_value._values(), src)
        elif example_value.layout in {torch.sparse_csr, torch.sparse_bsr}:
            self._lift_basic_symbols(example_value.crow_indices(), src)
            self._lift_basic_symbols(example_value.col_indices(), src)
        elif example_value.layout in {torch.sparse_csc, torch.sparse_bsc}:
            self._lift_basic_symbols(example_value.ccol_indices(), src)
            self._lift_basic_symbols(example_value.row_indices(), src)
        if is_traceable_wrapper_subclass(example_value):
            (attrs, ctx) = example_value.__tensor_flatten__()
            for attr in attrs:
                inner_t = getattr(example_value, attr)
                self._lift_basic_symbols(inner_t, AttrSource(src, attr) if src is not None else None)
    elif isinstance(example_value, torch.SymInt):
        _lift_symbols_in_symint(example_value, src)

def _find_loss_output(mod: torch.nn.Module, g: fx.Graph, output_loss_value_spec):
    output_nodes = [n for n in g.nodes if n.op == 'output']
    assert len(output_nodes) == 1
    output_node = output_nodes[0]
    output_val = output_node.args[0]
    generated_spec: Any = None
    if isinstance(mod, TrivialLossWrapper):
        assert len(output_node.args) == 1
        loss_node = output_val
        generated_spec = TrivialLossWrapper.loss_spec
    elif <MASK>:
        if isinstance(output_val, dict) and 'loss' in output_val.keys():
            loss_node = output_val['loss']
            generated_spec = {k: k == 'loss' for k in output_val}
        else:
            loss_node = None
            generated_spec = None
    else:
        loss_node = _find_loss_from_output_and_spec(output_val, output_loss_value_spec)
        generated_spec = output_loss_value_spec
    return (loss_node, output_node, generated_spec)

def get_in_dim_to_shard(cmd: DimSpec) -> Optional[InputDim]:
    if isinstance(cmd, InputDim):
        return cmd
    elif isinstance(cmd, Flatten):
        for (i, dim) in enumerate(cmd.input_dims):
            if not isinstance(dim, InputDim):
                raise AssertionError(f'Expected InputDim, got {type(dim)}')
            can_shard_dim = True
            (shard_mesh_dim, shard_placement) = maybe_get_shard_mesh_dim_and_placement(dim)
            input_sharded = shard_mesh_dim is not None
            if i > 0:
                can_shard_dim = False
                if strict_view and input_sharded:
                    raise RuntimeError(f'Attempted to flatten multiple dimensions, with dimension {dim.input_dim} being sharded. ', 'It cannot be performed without redistribution, which is disallowed by the current operator.')
            elif input_sharded:
                if not (shard_placement is not None and shard_mesh_dim is not None):
                    raise AssertionError('Expected shard_placement and shard_mesh_dim to be not None')
                tensor_dim_size = global_input_shape[shard_placement.dim]
                mesh_dim_size = mesh_sizes[shard_mesh_dim]
                if tensor_dim_size % mesh_dim_size != 0:
                    can_shard_dim = False
                    if strict_view:
                        raise RuntimeError(f'Attempted to flatten unevenly sharded dimension {i}, which would require resharding the input. Please explicitly redistribute the tensor instead.')
            shardable_dims[dim.input_dim] = [can_shard_dim] * mesh_ndim
        if not isinstance(cmd.input_dims[0], InputDim):
            raise AssertionError(f'Expected InputDim, got {type(cmd.input_dims[0])}')
        return cmd.input_dims[0]
    elif isinstance(cmd, Split):
        in_dim = get_in_dim_to_shard(cmd.input_dim)
        out_size = cmd.group_shape[cmd.split_id]
        if cmd.split_id == 0 and in_dim is not None:
            shardable_dims[in_dim.input_dim] = [out_size % mesh_dim_size == 0 for mesh_dim_size in mesh_sizes]
            (shard_mesh_dim, _) = maybe_get_shard_mesh_dim_and_placement(in_dim)
            if strict_view and shard_mesh_dim is not None:
                if not shardable_dims[in_dim.input_dim][shard_mesh_dim]:
                    raise RuntimeError(f'Attempted to split the sharded dimension {in_dim.input_dim} into multiple subdimensions. ', 'It cannot be performed without redistribution, which is disallowed by the current operator.')
            submesh_size = 1
            for (size, shard) in zip(mesh_sizes, input_src_placements):
                if <MASK>:
                    submesh_size *= size
            if not out_size % submesh_size == 0:
                raise AssertionError(f'Resulting dimension size {out_size} is not divisible by its mesh dimension {submesh_size}.')
        return in_dim if cmd.split_id == 0 else None
    elif isinstance(cmd, Repeat):
        in_dim = get_in_dim_to_shard(cmd.input_dim)
        if in_dim is not None:
            shardable_dims[in_dim.input_dim] = [False] * mesh_ndim
        return None
    else:
        return None

@final
def _logical_func(self, name: str, func, axis: Axis | None=0, bool_only: bool=False, skipna: bool=True, **kwargs) -> Series | bool:
    nv.validate_logical_func((), kwargs, fname=name)
    validate_bool_kwarg(skipna, 'skipna', none_allowed=False)
    if self.ndim > 1 and axis is None:
        res = self._logical_func(name, func, axis=0, bool_only=bool_only, skipna=skipna, **kwargs)
        return res._logical_func(name, func, skipna=skipna, **kwargs)
    elif <MASK>:
        axis = 0
    if self.ndim > 1 and axis == 1 and (len(self._mgr.blocks) > 1) and all((block.values.ndim == 2 for block in self._mgr.blocks)) and (not kwargs):
        obj = self
        if bool_only:
            obj = self._get_bool_data()
        return obj._reduce_axis1(name, func, skipna=skipna)
    return self._reduce(func, name=name, axis=axis, skipna=skipna, numeric_only=bool_only, filter_type='bool')

@property
def user_inputs(self) -> Collection[Union[int, float, bool, None, str]]:
    user_inputs: list[Union[int, float, bool, None, str]] = []
    for s in self.input_specs:
        if <MASK>:
            continue
        if isinstance(s.arg, (TensorArgument, SymIntArgument, SymFloatArgument, SymBoolArgument, CustomObjArgument)):
            user_inputs.append(s.arg.name)
        elif isinstance(s.arg, ConstantArgument):
            user_inputs.append(s.arg.value)
        else:
            raise RuntimeError(f'{s.arg} is not a valid user inputs')
    return tuple(user_inputs)

def _codegen_dynamic_scalar(self, node):
    (data,) = (t.codegen_reference() for t in node.inputs)
    if <MASK>:
        self.writeline(f'{node.sym} = {data}.item()')
    elif len(node.keypath) == 1 and isinstance(node.keypath[0], ConvertIntKey):
        self.writeline(f'{node.sym} = 1 if {data}.item() else 0')
    elif len(node.keypath) == 1 and isinstance(node.keypath[0], DivideByKey):
        self.writeline(f'{node.sym}_undivided = {data}.item()')
        self.writeline(f"assert {node.sym}_undivided % {node.keypath[0].divisor} == 0, f'{{{node.sym}_undivided}} not divisible by {node.keypath[0].divisor}'")
        self.writeline(f'{node.sym} = {node.sym}_undivided // {node.keypath[0].divisor}')
    else:
        raise AssertionError(f'unrecognized keypath {node.keypath}')
    self.writeline(f'{node.get_name()} = None')

@staticmethod
def frexp(x):
    cache_keys = (f'frexp({x})[0]', f'frexp({x})[1]')
    if <MASK>:
        return tuple((V.kernel.cse.try_get(cache_key) for cache_key in cache_keys))
    code = BracesBuffer()
    exponent = V.kernel.cse.newvar(dtype=torch.int32, shape=x.shape)
    mantissa = V.kernel.cse.newvar(dtype=x.dtype, shape=x.shape)
    code.writeline(f'int32_t {exponent};')
    code.writeline(f'auto {mantissa} = std::frexp({x}, &{exponent});')
    V.kernel.compute.splice(code)
    cse_vars = (mantissa, exponent)
    for (cache_key, cse_var) in zip(cache_keys, cse_vars):
        V.kernel.cse.put(cache_key, cse_var)
    return (mantissa, exponent)

def _nll_loss_nd(input: TensorLikeType, target: TensorLikeType, weight: Optional[TensorLikeType], reduction: str, ignore_index: int) -> TensorLikeType:
    torch._check(input.ndim > 0 and input.ndim <= 3, lambda : f'Expected input dimension to be either [1, 2, 3] but received {input.ndim}.')
    torch._check(input.ndim == 1 or input.shape[0] == target.shape[0], lambda : f'Expected input batch size {input.shape[0]} to match target batch size {target.shape[0]}.')
    _check_reduction_value(reduction)
    flat_target = torch.flatten(target)
    ignore_classes_mask = torch.eq(flat_target, ignore_index)
    '\n    from torch._subclasses.fake_tensor import FakeTensor\n    num_classes = input.shape[1] if input.ndim > 1 else input.shape[0]\n    valid_classes_mask = torch.logical_and(\n        (flat_target >= 0), (flat_target < num_classes)\n    )\n    class_check = torch.all(torch.logical_or(ignore_classes_mask, valid_classes_mask))\n    torch._check(\n        isinstance(target, FakeTensor) or bool(class_check.item()),\n        lambda: "A target class is out-of-bounds and not the ignore index.",\n    )\n    '
    ignore_class_weight = torch.scalar_tensor(0, dtype=input.dtype, device=input.device)
    class_weight = torch.scalar_tensor(1, dtype=input.dtype, device=input.device) if weight is None else weight[flat_target]
    current_weight = torch.where(ignore_classes_mask, ignore_class_weight, class_weight)
    if input.ndim == 1:
        loss = -input[target] * current_weight
    elif input.ndim == 2:
        batch_size = input.shape[0]
        loss = -input[torch.arange(batch_size), target] * current_weight
    else:
        batch_size = input.shape[0]
        extent = input.shape[2]
        numel = batch_size * extent
        indices = torch.arange(numel)
        bdx = indices // extent
        kdx = indices % extent
        loss = -input[bdx, flat_target, kdx] * current_weight
    loss = torch.reshape(loss, target.shape)
    if reduction == 'none':
        return loss
    elif <MASK>:
        return torch.sum(loss)
    else:
        return torch.sum(loss) / torch.sum(current_weight)

def with_dim_size_dtype(self, dtype):
    if dtype not in (dtypes.int32, dtypes.int64):
        raise ValueError('dtype must be int32 or int64')
    if <MASK>:
        return self
    return RaggedTensorDynamicShape([math_ops.cast(p, dtype) for p in self._partitioned_dim_sizes], math_ops.cast(self._inner_dim_sizes, dtype))

def _nanmax(X, axis=None, xp=None):
    (xp, _, device_) = get_namespace_and_device(X, xp=xp)
    if <MASK>:
        return xp.asarray(numpy.nanmax(X, axis=axis))
    else:
        mask = xp.isnan(X)
        X = xp.max(xp.where(mask, xp.asarray(-xp.inf, dtype=X.dtype, device=device_), X), axis=axis)
        mask = xp.all(mask, axis=axis)
        if xp.any(mask):
            X = xp.where(mask, xp.asarray(xp.nan, dtype=X.dtype, device=device_), X)
        return X

def flatten_bases(model):
    bases = []
    for base in model.__bases__:
        if <MASK>:
            bases.extend(flatten_bases(base))
        else:
            bases.append(base)
    return bases

@classmethod
def _from_sequence_of_strings(cls, strings, *, dtype: ExtensionDtype, copy: bool=False) -> Self:
    """
        Construct a new ExtensionArray from a sequence of strings.
        """
    mask = isna(strings)
    if isinstance(strings, cls):
        strings = strings._pa_array
    pa_type = to_pyarrow_type(dtype)
    if pa_type is None or pa.types.is_binary(pa_type) or pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type):
        scalars = strings
    elif pa.types.is_timestamp(pa_type):
        from pandas.core.tools.datetimes import to_datetime
        scalars = to_datetime(strings, errors='raise')
    elif pa.types.is_date(pa_type):
        from pandas.core.tools.datetimes import to_datetime
        scalars = to_datetime(strings, errors='raise').date
        scalars = pa.array(scalars, type=pa_type, mask=mask)
    elif <MASK>:
        from pandas.core.tools.timedeltas import to_timedelta
        scalars = to_timedelta(strings, errors='raise')
        if pa_type.unit != 'ns':
            mask = isna(scalars)
            if not isinstance(strings, (pa.Array, pa.ChunkedArray)):
                strings = pa.array(strings, type=pa.string(), mask=mask)
            strings = pc.if_else(mask, None, strings)
            try:
                scalars = strings.cast(pa.int64())
            except pa.ArrowInvalid:
                pass
    elif pa.types.is_time(pa_type):
        from pandas.core.tools.times import to_time
        scalars = to_time(strings, errors='coerce')
    elif pa.types.is_boolean(pa_type):
        if isinstance(strings, (pa.Array, pa.ChunkedArray)):
            scalars = strings
        else:
            scalars = pa.array(strings, type=pa.string(), mask=mask)
        scalars = pc.if_else(pc.equal(scalars, '1.0'), '1', scalars)
        scalars = pc.if_else(pc.equal(scalars, '0.0'), '0', scalars)
        scalars = scalars.cast(pa.bool_())
    elif pa.types.is_integer(pa_type) or pa.types.is_floating(pa_type) or pa.types.is_decimal(pa_type):
        from pandas.core.tools.numeric import to_numeric
        scalars = to_numeric(strings, errors='raise')
        if isinstance(strings, (pa.Array, pa.ChunkedArray)):
            scalars = strings.cast(pa_type)
        elif mask is not None:
            scalars = pa.array(scalars, mask=mask, type=pa_type)
    else:
        raise NotImplementedError(f'Converting strings to {pa_type} is not implemented.')
    return cls._from_sequence(scalars, dtype=pa_type, copy=copy)

@method_with_native_function
def gen_one(self, f: NativeFunction) -> str | None:
    assert not f.manual_kernel_registration
    if self.target is Target.REGISTRATION and (not self.selector.is_native_function_selected(f)):
        return None
    if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional and f.func.kind() is SchemaKind.out:
        return None
    cpp_sig_group = CppSignatureGroup.from_native_function(f, method=False, fallback_binding=False)
    kern = self.backend_index.get_kernel(f)
    sig = NativeSignature(f.func, prefix=f'wrapper_{self.backend_index.dispatch_key}_', symint=kern is not None and kern.supports_symint())
    if self.target is Target.NAMESPACED_DECLARATION:
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += f'TORCH_API {cpp_sig.decl()};\n'
        return result
    elif self.target is Target.NAMESPACED_DEFINITION:

        def generate_defn(cpp_sig: CppSignature) -> str:
            return f"\n{cpp_sig.defn()} {{\nreturn {sig.name()}({', '.join((e.expr for e in translate(cpp_sig.arguments(), sig.arguments())))});\n}}\n"
        result = ''
        for cpp_sig in cpp_sig_group.signatures(symint=self.symint):
            result += generate_defn(cpp_sig)
        return result
    elif self.target is Target.ANONYMOUS_DEFINITION:
        k = f.func.kind()
        sig_body = []
        context: list[Binding | Expr] = list(sig.arguments())
        if self.backend_index.dispatch_key is DispatchKey.Meta:
            class_name = f'structured_{meta.name(self.g)}_meta_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        elif self.backend_index.dispatch_key is DispatchKey.CompositeExplicitAutogradNonFunctional:
            class_name = f'structured_{meta.name(self.g)}_default_backend_{k.name}'
            parent_class = f'at::meta::structured_{meta.name(self.g)}'
        else:
            metadata = self.backend_index.get_kernel(self.g)
            assert metadata is not None
            class_name = f'structured_{metadata.kernel}_{k.name}'
            parent_class = f'{metadata.cpp_namespace}::structured_{metadata.kernel}'
        if self.backend_index.device_guard:
            device_check_args = itertools.chain(f.func.arguments.out, f.func.arguments.flat_positional)
            sig_body.append(RegisterDispatchKey.gen_device_check(f.device_check, list(device_check_args), sig.name()))
        if k is SchemaKind.functional:
            sig_body.append(f'{class_name} op;')
        elif k is SchemaKind.inplace:
            sig_body.append(f'{class_name} op(self);')
        elif k is SchemaKind.out:
            out_args_str = ', '.join((a.name for a in f.func.arguments.out))
            sig_body.append(f'{class_name} op({out_args_str});')
        meta_exprs = ', '.join((e.expr for e in translate(context, structured.meta_arguments(self.g), method=False)))
        if self.g.out.precomputed:
            sig_body.append(f'auto precompute = op.meta({meta_exprs});')
            precomputed_values = [*self.g.out.precomputed.replace.values(), self.g.out.precomputed.add]
            for precomputed_elems in precomputed_values:
                context.extend((Expr(expr=f'precompute.{arg.name}', type=structured.argument_type(arg, binds=arg.name)) for arg in precomputed_elems))
            sig_body.append('(void)precompute;')
        else:
            sig_body.append(f'op.meta({meta_exprs});')
        out_args = structured.out_arguments(self.g)
        for (i, out_arg) in enumerate(out_args):
            assert ConstRefCType(BaseCType(tensorT)) == out_arg.nctype.type
            if k is SchemaKind.out:
                expr = f'op.maybe_get_output({i})'
            else:
                expr = f'op.outputs_[{i}]'
            context.append(Expr(expr=expr, type=NamedCType(out_arg.nctype.name, MutRefCType(BaseCType(tensorT)))))
        if self.backend_index.dispatch_key == DispatchKey.CompositeExplicitAutogradNonFunctional:
            out_sig_group = CppSignatureGroup.from_native_function(self.g.out, method=False, fallback_binding=f.manual_cpp_binding)
            out_sig = out_sig_group.most_faithful_signature()
            api_name = out_sig.name()
            out_exprs = ', '.join((e.expr for e in translate(context, out_sig.arguments(), method=False)))
            sig_body.append(f'at::{api_name}({out_exprs});')
        elif self.backend_index.dispatch_key != DispatchKey.Meta:
            impl_exprs = ', '.join((e.expr for e in translate(context, structured.impl_arguments(self.g), method=False)))
            sig_body.append(f'op.impl({impl_exprs});')
        if k is SchemaKind.out or k is SchemaKind.inplace:
            for i in range(len(f.func.returns)):
                sig_body.append(f'if (op.proxy_outputs_[{i}].has_value()) op.outputs_[{i}].get().copy_(*op.proxy_outputs_[{i}]);')
        if k is SchemaKind.functional:
            if <MASK>:
                ret_expr = 'std::move(op.outputs_[0])'
            else:
                moved = ', '.join((f'std::move(op.outputs_[{i}])' for i in range(len(f.func.returns))))
                ret_expr = f'std::make_tuple({moved})'
        elif k is SchemaKind.inplace:
            ret_expr = 'self'
        elif k is SchemaKind.out:
            if len(f.func.returns) == 1:
                ret_expr = f.func.arguments.out[0].name
            else:
                refs = ', '.join((a.name for a in f.func.arguments.out))
                ret_expr = f'std::forward_as_tuple({refs})'
        sig_body.append(f'return {ret_expr};')
        sig_body_str = '\n'.join(sig_body)
        return f'{self.gen_class(f, k, class_name=class_name, parent_class=parent_class, generate_super=self.g.out.structured_inherits is not None)}\n\n{sig.defn()} {{\n{sig_body_str}\n}}\n'
    elif self.target is Target.REGISTRATION:
        return f'm.impl("{f.func.name}", TORCH_FN({sig.name()}));'
    else:
        assert_never(self.target)
        return None

def _get_pass_name_func(p):
    if <MASK>:
        pass_name = p.pass_name
        pass_func = p.apply
    elif isinstance(p, types.FunctionType):
        pass_name = p.__name__.lstrip('_')
        pass_func = p
    else:
        pass_name = None
        pass_func = None
    return (pass_name, pass_func)

def get_distribution(always=False):
    dist = distutils.core._setup_distribution
    if <MASK>:
        dist = None
    if always and dist is None:
        dist = NumpyDistribution()
    return dist

@property
def _component_specs(self):
    if self._ragged_rank <= 0:
        if self._flat_values_spec is not None:
            return [self._flat_values_spec]
        else:
            return [tensor_lib.TensorSpec(self._shape, self._dtype)]
    flat_values_spec = self._flat_values_spec
    if <MASK>:
        flat_values_shape = tensor_shape.TensorShape([None]).concatenate(self._shape[self._ragged_rank + 1:])
        flat_values_spec = tensor_lib.TensorSpec(flat_values_shape, self._dtype)
    outer_dim = tensor_shape.dimension_at_index(self._shape, 0)
    outer_splits_shape = [None if outer_dim is None else outer_dim + 1]
    inner_splits_spec = tensor_lib.TensorSpec([None], self._row_splits_dtype)
    specs = [flat_values_spec, tensor_lib.TensorSpec(outer_splits_shape, self._row_splits_dtype)] + [inner_splits_spec for _ in range(self._ragged_rank - 1)]
    return specs

def _setup_world_group_and_device(self):
    default_initialized = is_initialized()
    if not default_initialized:
        init_process_group()
    world_size = get_world_size()
    if self._layout.numel() > world_size:
        raise RuntimeError(f'Mesh should not be bigger than default world size {world_size}, but found {self._layout.numel()} ranks!')
    device_handle = _get_device_handle(self._device_type)
    if <MASK>:
        if 'LOCAL_RANK' in os.environ:
            local_rank = int(os.environ['LOCAL_RANK'])
            logger.info('Setting default device for the current process based on LOCAL_RANK=%s', local_rank)
            device_handle.set_device(local_rank)
        else:
            warnings.warn('It seems like you did not set/select the default device for the current process before the DeviceMesh initialization or use a launcher (i.e. torchrun) which populates `LOCAL_RANK` environment variable. It is recommended to set the current device for the process BEFORE the DeviceMesh initialization so that the underlying communicator (i.e. NCCL) can be initialized properly. Given that the current process has no default device selected, DeviceMesh will use a heuristic to set the device_id via `global_rank % num_devices_per_host`, assuming homogeneous hardware cluster. ')
            num_devices_per_host = device_handle.device_count()
            if world_size > num_devices_per_host and world_size % num_devices_per_host != 0:
                raise RuntimeError(f'DeviceMesh only support homogeneous hardware, but found {world_size} ranks and {num_devices_per_host} {self._device_type} devices!')
            device_handle.set_device(get_rank() % num_devices_per_host)
    return _get_default_group()

def test_argument_of_local_function(self):
    test_self = self

    class Resolver(type_inference.Resolver):

        def res_arg(self, ns, types_ns, f_name, name, type_anno, f_is_local):
            if f_name == 'test_fn':
                test_self.assertFalse(f_is_local)
                test_self.assertEqual(name, qual_names.QN('a'))
                test_self.assertEqual(type_anno, qual_names.QN('int'))
            elif f_name == 'foo':
                test_self.assertTrue(f_is_local)
                if <MASK>:
                    test_self.assertEqual(type_anno, qual_names.QN('float'))
                elif name == qual_names.QN('y'):
                    test_self.assertIsNone(type_anno)
                else:
                    test_self.fail('unexpected argument {} for {}'.format(name, f_name))
            else:
                test_self.fail('unexpected function name {}'.format(f_name))
            return {str(name) + '_type'}

    def test_fn(a: int):

        def foo(x: float, y):
            return (x, y)
        return foo(a, a)
    tr = TestTranspiler(Resolver)
    (node, _) = tr.transform(test_fn, None)
    fn_body = node.body
    self.assertTypes(fn_body[0].body[0].value, (('x_type', 'y_type'),))
    self.assertTypes(fn_body[0].body[0].value.elts[0], 'x_type')
    self.assertTypes(fn_body[0].body[0].value.elts[1], 'y_type')

def _get_outer_edges(a, range):
    """
    Determine the outer bin edges to use, from either the data or the range
    argument
    """
    if <MASK>:
        (first_edge, last_edge) = range
        if first_edge > last_edge:
            raise ValueError('max must be larger than min in range parameter.')
        if not (np.isfinite(first_edge) and np.isfinite(last_edge)):
            raise ValueError(f'supplied range of [{first_edge}, {last_edge}] is not finite')
    elif a.size == 0:
        (first_edge, last_edge) = (0, 1)
    else:
        (first_edge, last_edge) = (a.min(), a.max())
        if not (np.isfinite(first_edge) and np.isfinite(last_edge)):
            raise ValueError(f'autodetected range of [{first_edge}, {last_edge}] is not finite')
    if first_edge == last_edge:
        first_edge = first_edge - 0.5
        last_edge = last_edge + 0.5
    return (first_edge, last_edge)

def generate_values(base, densesize):
    """Generates a tensor of shape densesize with values equal to

              base + i_1 * 10^0 + ... + i_d * 10^{d - 1}

            at indices i_1, ..., i_d (with 0 <= i_j < densesize[j] for any 1 <= j <=
            len(densesize))

            This mapping produces unique values as long as
            densesize[i] < 10 for all i in range(len(densesize)).
            """
    if not densesize:
        return base
    if not isinstance(base, int) and base.ndim > 0:
        return torch.stack([generate_values(b, densesize) for b in base])
    if <MASK>:
        return torch.zeros(densesize, dtype=torch.int64)
    r = torch.arange(densesize[0], dtype=torch.int64)
    for (i, d) in enumerate(densesize[1:]):
        y = torch.arange(d, dtype=torch.int64) * 10 ** (i + 1)
        r = r[..., None] + y[None, ...]
    r.add_(base)
    return r

def _get_index_tablespace_sql(self, model, fields, db_tablespace=None):
    if db_tablespace is None:
        if len(fields) == 1 and fields[0].db_tablespace:
            db_tablespace = fields[0].db_tablespace
        elif <MASK>:
            db_tablespace = settings.DEFAULT_INDEX_TABLESPACE
        elif model._meta.db_tablespace:
            db_tablespace = model._meta.db_tablespace
    if db_tablespace is not None:
        return ' ' + self.connection.ops.tablespace_sql(db_tablespace)
    return ''

def _align_for_op(self, other, axis: AxisInt, flex: bool | None=False, level: Level | None=None):
    """
        Convert rhs to meet lhs dims if input is list, tuple or np.ndarray.

        Parameters
        ----------
        other : Any
        axis : int
        flex : bool or None, default False
            Whether this is a flex op, in which case we reindex.
            None indicates not to check for alignment.
        level : int or level name, default None

        Returns
        -------
        left : DataFrame
        right : Any
        """
    (left, right) = (self, other)

    def to_series(right):
        msg = 'Unable to coerce to Series, length must be {req_len}: given {given_len}'
        dtype = None
        if getattr(right, 'dtype', None) == object:
            dtype = object
        if axis == 0:
            if len(left.index) != len(right):
                raise ValueError(msg.format(req_len=len(left.index), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.index, dtype=dtype)
        else:
            if len(left.columns) != len(right):
                raise ValueError(msg.format(req_len=len(left.columns), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.columns, dtype=dtype)
        return right
    if isinstance(right, np.ndarray):
        if right.ndim == 1:
            right = to_series(right)
        elif right.ndim == 2:
            dtype = None
            if right.dtype == object:
                dtype = object
            if right.shape == left.shape:
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[0] == left.shape[0] and right.shape[1] == 1:
                right = np.broadcast_to(right, left.shape)
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[1] == left.shape[1] and right.shape[0] == 1:
                right = to_series(right[0, :])
            else:
                raise ValueError(f'Unable to coerce to DataFrame, shape must be {left.shape}: given {right.shape}')
        elif right.ndim > 2:
            raise ValueError(f'Unable to coerce to Series/DataFrame, dimension must be <= 2: {right.shape}')
    elif is_list_like(right) and (not isinstance(right, (Series, DataFrame))):
        if any((is_array_like(el) for el in right)):
            raise ValueError(f'Unable to coerce list of {type(right[0])} to Series/DataFrame')
        right = to_series(right)
    if flex is not None and isinstance(right, DataFrame):
        if not left._indexed_same(right):
            if flex:
                (left, right) = left.align(right, join='outer', level=level)
            else:
                raise ValueError('Can only compare identically-labeled (both index and columns) DataFrame objects')
    elif <MASK>:
        axis = axis if axis is not None else 1
        if not flex:
            if not left.axes[axis].equals(right.index):
                raise ValueError('Operands are not aligned. Do `left, right = left.align(right, axis=1)` before operating.')
        (left, right) = left.align(right, join='outer', axis=axis, level=level)
        right = left._maybe_align_series_as_frame(right, axis)
    return (left, right)

def get_fusion_candidates(rule: GroupBatchFusionBase, root_node: torch.fx.Node, fused_set: OrderedSet[torch.fx.Node]) -> collections.defaultdict[Any, list[torch.fx.Node]]:
    """
    Search fusion candidates for a specific rule using BFS starting from the root node.
    We only search the subgraph within graph_search_options["max_fuse_search_depth"].
    """
    q: collections.deque[tuple[int, torch.fx.Node]] = collections.deque()
    candidate_dict: collections.defaultdict[Any, list[torch.fx.Node]] = collections.defaultdict(list)
    if root_node.target in SEARCH_EXCLUSIONS:
        return candidate_dict
    visited_set = OrderedSet[torch.fx.Node]()
    for next_node in root_node.all_input_nodes:
        q.append((1, next_node))
        visited_set.add(next_node)
    while len(q) > 0:
        (depth, node) = q.popleft()
        if node in fused_set:
            continue
        key = rule.match(node)
        if key is not None:
            candidate_nodes = candidate_dict[key]
            if node not in candidate_nodes:
                candidate_nodes.append(node)
        elif <MASK>:
            for next_node in node.all_input_nodes:
                if next_node not in visited_set:
                    visited_set.add(next_node)
                    q.append((depth + 1, next_node))
    return candidate_dict

def compute_slice_index(index, size, default=None):
    if index is None:
        return default
    fn = lambda x: V.graph.sizevars.guard_or_false(x)
    index = sympy.expand(index)
    size = sympy.expand(size)
    if fn(sympy.Ge(index, 0)) and fn(sympy.Le(index, size)):
        return index
    elif fn(sympy.Lt(index, 0)) and fn(sympy.Ge(index, -size)):
        return index + size
    elif fn(sympy.Gt(index, size)):
        return size
    elif <MASK>:
        return 0
    return None

@torch._disable_dynamo
@wraps(fn)
def _fn(*args, **kwargs):
    bound = sig.bind(*args, **kwargs)
    type_promoting_args = tuple((bound.arguments[x] for x in self.type_promoting_arg_names if x in bound.arguments.keys()))
    flattened_type_promoting_args = pytree.arg_tree_leaves(*type_promoting_args)
    (compute_dtype, result_dtype) = utils.elementwise_dtypes(*flattened_type_promoting_args, type_promotion_kind=self.type_promotion_kind)
    promoted_args = {x: _maybe_convert_to_dtype(bound.arguments[x], compute_dtype) for x in self.type_promoting_arg_names if x in bound.arguments.keys()}
    bound.arguments.update(promoted_args)
    result = fn(**bound.arguments)
    if 'dtype' in bound.arguments:
        maybe_dtype = bound.arguments['dtype']
        if maybe_dtype:
            result_dtype = maybe_dtype
    if <MASK>:
        return _maybe_convert_to_dtype(result, result_dtype)
    if isinstance(result, Sequence):
        return tuple((_maybe_convert_to_dtype(x, result_dtype) for x in result))
    raise AssertionError(f'Unhandled result type: {type(result)}')

def _get_cuda_arch_flags(cflags: Optional[list[str]]=None) -> list[str]:
    """
    Determine CUDA arch flags to use.

    For an arch, say "6.1", the added compile flag will be
    ``-gencode=arch=compute_61,code=sm_61``.
    For an added "+PTX", an additional
    ``-gencode=arch=compute_xx,code=compute_xx`` is added.

    See select_compute_arch.cmake for corresponding named and supported arches
    when building with CMake.
    """
    if cflags is not None:
        for flag in cflags:
            if 'TORCH_EXTENSION_NAME' in flag:
                continue
            if 'arch' in flag:
                return []
    named_arches = collections.OrderedDict([('Kepler+Tesla', '3.7'), ('Kepler', '3.5+PTX'), ('Maxwell+Tegra', '5.3'), ('Maxwell', '5.0;5.2+PTX'), ('Pascal', '6.0;6.1+PTX'), ('Volta+Tegra', '7.2'), ('Volta', '7.0+PTX'), ('Turing', '7.5+PTX'), ('Ampere+Tegra', '8.7'), ('Ampere', '8.0;8.6+PTX'), ('Ada', '8.9+PTX'), ('Hopper', '9.0+PTX'), ('Blackwell+Tegra', '11.0'), ('Blackwell', '10.0;10.3;12.0;12.1+PTX')])
    supported_arches = ['3.5', '3.7', '5.0', '5.2', '5.3', '6.0', '6.1', '6.2', '7.0', '7.2', '7.5', '8.0', '8.6', '8.7', '8.9', '9.0', '9.0a', '10.0', '10.0a', '11.0', '11.0a', '10.3', '10.3a', '12.0', '12.0a', '12.1', '12.1a']
    valid_arch_strings = supported_arches + [s + '+PTX' for s in supported_arches]
    _arch_list = os.environ.get('TORCH_CUDA_ARCH_LIST', None)
    if not _arch_list or _arch_list == 'native':
        arch_list = []
        for i in range(torch.cuda.device_count()):
            capability = torch.cuda.get_device_capability(i)
            supported_sm = [int(''.join(re.findall('\\d+', arch.split('_')[1]))) for arch in torch.cuda.get_arch_list() if 'sm_' in arch]
            max_supported_sm = max(((sm // 10, sm % 10) for sm in supported_sm))
            capability = min(max_supported_sm, capability)
            arch = f'{capability[0]}.{capability[1]}'
            if arch not in arch_list:
                arch_list.append(arch)
        arch_list = sorted(arch_list)
        arch_list[-1] += '+PTX'
        if not _arch_list:
            if <MASK>:
                arch_list_str = ';'.join(arch_list)
                logger.debug("TORCH_CUDA_ARCH_LIST is not set, using TORCH_CUDA_ARCH_LIST='%s' for visible GPU architectures. Set os.environ['TORCH_CUDA_ARCH_LIST'] to override.", arch_list_str)
    else:
        _arch_list = _arch_list.replace(' ', ';')
        for (named_arch, archival) in named_arches.items():
            _arch_list = _arch_list.replace(named_arch, archival)
        arch_list = _arch_list.split(';')
    flags = []
    for arch in arch_list:
        if arch not in valid_arch_strings:
            raise ValueError(f'Unknown CUDA arch ({arch}) or GPU not supported')
        else:
            version = arch.split('+')[0]
            (major, minor) = version.split('.')
            num = f'{major}{minor}'
            flags.append(f'-gencode=arch=compute_{num},code=sm_{num}')
            if arch.endswith('+PTX'):
                flags.append(f'-gencode=arch=compute_{num},code=compute_{num}')
    return sorted(set(flags))

def _sympy_interp(expr: sympy.Expr) -> MetaProxy:
    if isinstance(expr, Symbol) and expr not in expr_to_tensor_proxy:
        expr_to_tensor_proxy[expr] = torch.ops.aten.scalar_tensor.default(expr_to_sym_proxy[expr])
    if isinstance(expr, (Integer, Number, BooleanAtom)):
        dtype = None
        c: Union[bool, int, float]
        if <MASK>:
            dtype = torch.bool
            c = bool(expr)
        elif isinstance(expr, sympy.Integer):
            dtype = torch.int64
            c = int(expr)
        elif isinstance(expr, sympy.Number):
            dtype = torch.float64
            c = float(expr)
        node = graph.call_function(torch.ops.aten.scalar_tensor.default, (c,), {'dtype': dtype})
        with fake_mode:
            node.meta['val'] = torch.ops.aten.scalar_tensor.default(c, dtype=dtype)
        expr_to_tensor_proxy[expr] = MetaProxy(node, tracer=tracer, fake_mode=fake_mode)
    if expr in expr_to_tensor_proxy:
        return expr_to_tensor_proxy[expr]
    if isinstance(expr, Symbol):
        return sympy_interp(Analysis, expr_to_tensor_proxy, expr)
    expr_to_tensor_proxy[expr] = _run_sympy_handler(Analysis, [_sympy_interp(arg) for arg in expr.args], expr)
    return expr_to_tensor_proxy[expr]

def wrapDeterministicFlagAPITest(fn):

    @wraps(fn)
    def wrapper(*args, **kwargs):
        with DeterministicGuard(torch.are_deterministic_algorithms_enabled(), warn_only=torch.is_deterministic_algorithms_warn_only_enabled()):

            class CuBLASConfigGuard:
                cublas_var_name = 'CUBLAS_WORKSPACE_CONFIG'

                def __enter__(self):
                    self.cublas_config_restore = os.environ.get(self.cublas_var_name)
                    os.environ[self.cublas_var_name] = ':4096:8'

                def __exit__(self, exception_type, exception_value, traceback):
                    cur_cublas_config = os.environ.get(self.cublas_var_name)
                    if self.cublas_config_restore is None:
                        if <MASK>:
                            del os.environ[self.cublas_var_name]
                    else:
                        os.environ[self.cublas_var_name] = self.cublas_config_restore
            with CuBLASConfigGuard():
                fn(*args, **kwargs)
    return wrapper

def _get_fields(self, forward=True, reverse=True, include_parents=True, include_hidden=False, topmost_call=True):
    """
        Internal helper function to return fields of the model.
        * If forward=True, then fields defined on this model are returned.
        * If reverse=True, then relations pointing to this model are returned.
        * If include_hidden=True, then fields with is_hidden=True are returned.
        * The include_parents argument toggles if fields from parent models
          should be included. It has three values: True, False, and
          PROXY_PARENTS. When set to PROXY_PARENTS, the call will return all
          fields defined for the current model or any of its parents in the
          parent chain to the model's concrete model.
        """
    if include_parents not in (True, False, PROXY_PARENTS):
        raise TypeError('Invalid argument for include_parents: %s' % (include_parents,))
    cache_key = (forward, reverse, include_parents, include_hidden, topmost_call)
    try:
        return self._get_fields_cache[cache_key]
    except KeyError:
        pass
    fields = []
    if include_parents is not False:
        parent_fields = set()
        for parent in self.parents:
            if parent._meta.concrete_model != self.concrete_model and include_parents == PROXY_PARENTS:
                continue
            for obj in parent._meta._get_fields(forward=forward, reverse=reverse, include_parents=include_parents, include_hidden=include_hidden, topmost_call=False):
                if (not getattr(obj, 'parent_link', False) or obj.model == self.concrete_model) and obj not in parent_fields:
                    fields.append(obj)
                    parent_fields.add(obj)
    if reverse and (not self.proxy):
        all_fields = self._relation_tree
        for field in all_fields:
            if include_hidden or not field.remote_field.hidden:
                fields.append(field.remote_field)
    if <MASK>:
        fields += self.local_fields
        fields += self.local_many_to_many
        if topmost_call:
            fields += self.private_fields
    fields = make_immutable_fields_list('get_fields()', fields)
    self._get_fields_cache[cache_key] = fields
    return fields

def enclosing_tpu_context_and_graph():
    """Returns the TPUReplicateContext which exists inside a tpu.rewrite(), and its associated graph."""
    graph = ops.get_default_graph()
    while graph is not None:
        ctx = graph._get_control_flow_context()
        while ctx is not None:
            if <MASK>:
                return (ctx, graph)
            ctx = ctx.outer_context
        graph = getattr(graph, 'outer_graph', None)
    return (None, None)

def _compareCpu(self, x, p, conjugate=False):
    if p is None:
        rank = x.ndim
        perm = rank - 1 - np.arange(rank)
    else:
        perm = p
    np_ans = self._np_transpose(x, perm)
    if conjugate:
        np_ans = np.conj(np_ans)
    with self.cached_session(use_gpu=False):
        inx = ops.convert_to_tensor(x)
        y = array_ops.transpose(inx, p, conjugate=conjugate)
        tf_ans = self.evaluate(y)
        self.assertShapeEqual(np_ans, y)
        self.assertAllEqual(np_ans, tf_ans)
        jacob_t = None
        if <MASK>:
            (jacob_t, jacob_n) = gradient_checker_v2.compute_gradient(lambda x: array_ops.transpose(x, p, conjugate=conjugate), [inx])
            self.assertAllClose(jacob_t, jacob_n, 0.001, 0.001)
        elif x.dtype in [np.float64, np.complex128]:
            (jacob_t, jacob_n) = gradient_checker_v2.compute_gradient(lambda x: array_ops.transpose(x, p, conjugate=conjugate), [inx])
            self.assertAllClose(jacob_t, jacob_n, 1e-06, 1e-06)
        return (tf_ans, jacob_t)

@staticmethod
@rpc.functions.async_execution
def update_and_fetch_model(ps_rref, grads):
    self = ps_rref.local_value()
    for (p, g) in zip(self.model.parameters(), grads, strict=True):
        if p.grad is None:
            p.grad = g
        else:
            p.grad += g
    with self.lock:
        timed_log(f'PS got {self.curr_update_size}/{self.batch_update_size} updates')
        self.curr_update_size += 1
        fut = self.future_model
        if <MASK>:
            for p in self.model.parameters():
                p.grad /= self.batch_update_size
            self.curr_update_size = 0
            self.optimizer.step()
            self.optimizer.zero_grad()
            fut.set_result(self.model)
            timed_log('PS updated model')
            self.future_model = torch.futures.Future()
    return fut

def gaussian_nll_loss(input: Tensor, target: Tensor, var: Union[Tensor, float], full: bool=False, eps: float=1e-06, reduction: str='mean') -> Tensor:
    """Compute the Gaussian negative log likelihood loss.

    See :class:`~torch.nn.GaussianNLLLoss` for details.

    Args:
        input: Expectation of the Gaussian distribution.
        target: Sample from the Gaussian distribution.
        var: Tensor of positive variance(s), one for each of the expectations
            in the input (heteroscedastic), or a single one (homoscedastic),
            or a positive scalar value to be used for all expectations.
        full (bool, optional): Whether to include the constant term in the loss calculation. Default: ``False``.
        eps (float, optional): Value added to var, for stability. Default: 1e-6.
        reduction (str, optional): Specifies the reduction to apply to the output:
            ``'none'`` | ``'mean'`` | ``'sum'``. ``'none'``: no reduction will be applied,
            ``'mean'``: the output is the average of all batch member losses,
            ``'sum'``: the output is the sum of all batch member losses.
            Default: ``'mean'``.
    """
    if has_torch_function_variadic(input, target, var):
        return handle_torch_function(gaussian_nll_loss, (input, target, var), input, target, var, full=full, eps=eps, reduction=reduction)
    if <MASK>:
        if var < 0:
            raise ValueError('var has negative entry/entries')
        var = var * torch.ones_like(input)
    elif torch.any(var < 0):
        raise ValueError('var has negative entry/entries')
    if var.size() != input.size():
        if input.size()[:-1] == var.size():
            var = torch.unsqueeze(var, -1)
        elif input.ndim == var.ndim and sum((y for (x, y) in zip(input.size(), var.size()) if x != y)) == 1:
            pass
        else:
            raise ValueError('var is of incorrect size')
    if reduction != 'none' and reduction != 'mean' and (reduction != 'sum'):
        raise ValueError(reduction + ' is not valid')
    var = var.clone()
    with torch.no_grad():
        var.clamp_(min=eps)
    loss = 0.5 * (torch.log(var) + (input - target) ** 2 / var)
    if full:
        loss += 0.5 * math.log(2 * math.pi)
    if reduction == 'mean':
        return loss.mean()
    elif reduction == 'sum':
        return loss.sum()
    else:
        return loss

def _find_reshape_mm_reshape(node: torch.fx.Node) -> list[_Matmul]:
    if node.target != aten.reshape.default:
        return []
    matches = []
    for mm_node in node.users:
        if mm_node.target not in (aten.mm.default, aten._scaled_mm.default):
            continue
        for reshape_node in mm_node.users:
            if <MASK>:
                continue
            matmul_input_node = cast('torch.fx.Node', node.args[0])
            B_node = cast('torch.fx.Node', mm_node.args[1])
            matmul_out_shape = torch.Size([*_get_tensor(matmul_input_node).shape[:-1], _get_tensor(B_node).shape[-1]])
            if _get_tensor(reshape_node).shape != matmul_out_shape:
                continue
            matches.append([node, mm_node, reshape_node])
            break
    matmuls = []
    for match in matches:
        mm_node = match[1]
        if mm_node.target == aten.mm.default:
            matmul = _Matmul.from_match(match)
            matmuls.append(matmul)
        elif mm_node.target == aten._scaled_mm.default:
            matmul = _ScaledMatmul.from_match(match)
            matmuls.append(matmul)
        else:
            raise AssertionError(f"Expect the node's target to be either aten.mm.default or aten._scaled_mm.default. Got {mm_node.target}.")
    return matmuls

@local_map_hop.py_impl(FakeTensorMode)
def fake_mode_key(mode: FakeTensorMode, gm: GraphModule, *args: Any, **kwargs: Any) -> GraphArg:
    with mode:
        if <MASK>:
            return gm(*args, **kwargs)
        is_backward = gm.meta['is_backward']
        redistribute_inputs = redistribute_bw_inputs if is_backward else redistribute_fw_inputs
        local_args = redistribute_inputs(args, gm.meta['local_map_kwargs']['in_placements'], gm.meta['local_map_kwargs']['device_mesh'], gm.meta['num_activations'])
        local_outs = gm(*local_args)
        redistribute_outputs = redistribute_bw_outputs if is_backward else redistribute_fw_outputs
        global_outs = redistribute_outputs(local_outs, gm.meta['local_map_kwargs']['out_placements'], gm.meta['local_map_kwargs']['device_mesh'], gm.meta['num_activations'])
        return global_outs

