def _normalize_feature_columns(feature_columns):
    """Normalizes the `feature_columns` input.

  This method converts the `feature_columns` to list type as best as it can. In
  addition, verifies the type and other parts of feature_columns, required by
  downstream library.

  Args:
    feature_columns: The raw feature columns, usually passed by users.

  Returns:
    The normalized feature column list.

  Raises:
    ValueError: for any invalid inputs, such as empty, duplicated names, etc.
  """
    if isinstance(feature_columns, _FeatureColumn):
        feature_columns = [feature_columns]
    if isinstance(feature_columns, collections_abc.Iterator):
        feature_columns = list(feature_columns)
    if <MASK>:
        raise ValueError('Expected feature_columns to be iterable, found dict.')
    for column in feature_columns:
        if not isinstance(column, _FeatureColumn):
            raise ValueError('Items of feature_columns must be a _FeatureColumn. Given (type {}): {}.'.format(type(column), column))
    if not feature_columns:
        raise ValueError('feature_columns must not be empty.')
    name_to_column = {}
    for column in feature_columns:
        if column.name in name_to_column:
            raise ValueError('Duplicate feature column name found for columns: {} and {}. This usually means that these columns refer to same base feature. Either one must be discarded or a duplicated but renamed item must be inserted in features dict.'.format(column, name_to_column[column.name]))
        name_to_column[column.name] = column
    return feature_columns

def get_df(self, log_path, cat_feature2cats=None, nrows=None, apply_filters=False, add_near_best=False):
    """
        Parses the log file and processes the data into a dataframe that can be used for training.
        """
    (df, metadata, features, categorical_features, choices) = self.parse_log(log_path, nrows)

    def calculate_stats(group):
        count = len(group)
        has_inf = np.isinf(group['feedback']).any()
        if has_inf:
            relative_std = np.inf
            median = np.inf
        else:
            mean = group['feedback'].mean()
            std = group['feedback'].std()
            relative_std = std / mean * 100 if mean != 0 else np.inf
            median = group['feedback'].median()
        if relative_std > 5:
            times = group['feedback'].tolist()
            times_str = ', '.join([f'{t:.3f}' for t in sorted(times)])
            log.debug('High relative std: %f. times=%s', relative_std, times_str)
        return pd.Series({'count': count, 'relative_std': relative_std, 'median_execution_time': median})
    feature_columns = features
    stats = df.groupby(feature_columns + ['choice'], as_index=False).apply(calculate_stats, include_groups=False).reset_index()
    if apply_filters:
        valid_stats = stats[(stats['count'] >= 3) & (stats['relative_std'] <= 5)]
        valid_inputs = valid_stats.groupby(feature_columns).filter(lambda x: len(x) >= 2)
    else:
        valid_inputs = stats

    def get_winner_and_speedup(group):
        assert len(group) >= 2, 'Need at least 2 choices'
        sorted_group = group.sort_values('median_execution_time')
        winner = sorted_group.iloc[0]['choice']
        winning_time = sorted_group.iloc[0]['median_execution_time']
        second_best_time = sorted_group.iloc[1]['median_execution_time']
        speedup = second_best_time / winning_time
        unique_choices = group['choice'].unique()
        choice2time = {}
        for row in group.itertuples():
            choice2time[row.choice] = row.median_execution_time
        assert len(unique_choices) == len(group), f'len(unique_choices) != len(group): {len(unique_choices)} != {len(group)}'
        return pd.Series({'winner': winner, 'speedup': speedup, 'avail_choices': unique_choices, 'choice2time': json.dumps(choice2time)})
    results = valid_inputs.groupby(feature_columns, as_index=False).filter(lambda x: len(x) >= 2).groupby(feature_columns, as_index=False).apply(get_winner_and_speedup, include_groups=False).reset_index()

    def add_near_best_configs(df):
        new_rows = []
        for (index, row) in df.iterrows():
            dictionary = json.loads(row['choice2time'])
            min_value = min(dictionary.values())
            for (key, value) in dictionary.items():
                new_row = row.copy()
                relative_performance = min_value / value
                new_row['relative_performance'] = relative_performance
                if relative_performance is None or relative_performance is np.inf:
                    breakpoint()
                new_row['actual_winner'] = row['winner']
                new_row['winner'] = key
                if relative_performance >= 0.98:
                    new_rows.append(new_row)
        return pd.DataFrame(new_rows).reset_index(drop=True)
    if <MASK>:
        results = add_near_best_configs(results)
    (results, added_categorical_features) = self.add_new_features(results)
    categorical_features += added_categorical_features
    (results, cat_feature2cats, dummy_col_2_col_val) = self.handle_categorical_features(cat_feature2cats, categorical_features, results)
    return (results, choices, cat_feature2cats, dummy_col_2_col_val, metadata)

@register_meta(aten._pdist_forward)
@out_wrapper()
def meta__pdist_forward(self: Tensor, p: float=2) -> Tensor:
    torch._check(self.is_contiguous(), lambda : '_pdist_forward requires contiguous input')
    n = self.size(0)
    if <MASK>:
        return self.new_empty([0]).to(memory_format=torch.legacy_contiguous_format)
    else:
        return self.new_empty((n * (n - 1) // 2,)).to(memory_format=torch.legacy_contiguous_format)

def _py_sorted(iterable, key, reverse):
    if key is not UNSPECIFIED and reverse is UNSPECIFIED:
        return sorted(iterable, key=key)
    if <MASK>:
        return sorted(iterable, reverse=reverse)
    if key is not UNSPECIFIED and reverse is not UNSPECIFIED:
        return sorted(iterable, key=key, reverse=reverse)
    return sorted(iterable)

def _split_optim_state_dict(model: nn.Module, optim: torch.optim.Optimizer, optim_state_dict: OptimizerStateType, info: _StateDictInfo) -> OptimizerStateType:
    """
    Extract the corresponding optim state_dict from ``optim_state_dict`` for
    ``optim`` and return the result optim state_dict.

    Args:
        model (nn.Module): the root model.
        optim (torch.optim.Optimizer): the optimizer.
        optim_state_dict (Dict[str, ValueType]): the superset optim state_dict that
            contains the optim state_dict of ``optim``.
        info (_StateDictInfo): state dict information.

    Returns:
        The optim state_dict of ``optim``.
    """
    state: DictValueType = {}
    pg_state: ListDictValueType = []
    return_osd: OptimizerStateType = {_STATE: state, _PG: pg_state}
    pg_mapping: dict[int, int] = {}
    if all((isinstance(k, int) for k in cast(DictValueType, optim_state_dict[_STATE]).keys())):
        return optim_state_dict
    for param_group in optim.param_groups:
        pg_state.append({_PARAMS: []})
        for param in param_group[_PARAMS]:
            for fqn in info.fqn_param_mapping[param]:
                if fqn in info.shared_params_mapping:
                    in_params = False
                    for loaded_param_group in cast(ListDictValueType, optim_state_dict[_PG]):
                        if fqn in cast(list[str], loaded_param_group[_PARAMS]):
                            in_params = True
                            break
                else:
                    in_params = True
                if not in_params:
                    continue
                params = pg_state[-1][_PARAMS]
                if not isinstance(params, list):
                    raise AssertionError(f'Expected list, got {type(params)}')
                params.append(fqn)
                if param.requires_grad:
                    state[fqn] = cast(DictValueType, optim_state_dict[_STATE])[fqn]
                for loaded_param_group in cast(ListDictValueType, optim_state_dict[_PG]):
                    if fqn in cast(list[str], loaded_param_group[_PARAMS]):
                        pg_mapping[id(loaded_param_group)] = len(return_osd[_PG]) - 1
        if <MASK>:
            ret = []
            for loaded_param_group in cast(ListDictValueType, optim_state_dict[_PG]):
                if len(cast(list[str], loaded_param_group[_PARAMS])) == 0:
                    ret.append(loaded_param_group)
            if len(ret) != 1:
                raise ValueError('There are param groups that have zero parameters. In such a case, DSD only support exactly one param group with zero parameters.But the loaded state_dict has zero or more than one param groups that have zero parameters.')
            if len(optim_state_dict[_PG]) != len(optim.param_groups):
                raise ValueError('When there is a parameter group that has zero parameters, multiple optimizers are not supported.')
            pg_mapping[id(loaded_param_group)] = len(return_osd[_PG]) - 1
    for param_group in cast(ListDictValueType, optim_state_dict[_PG]):
        pg_idx = pg_mapping.get(id(param_group), -1)
        if pg_idx == -1:
            continue
        for (key, value) in param_group.items():
            if key == _PARAMS:
                continue
            pg_state[pg_idx][key] = value
    return return_osd

@async_unsafe
def create_cursor(self, name=None):
    if name:
        if is_psycopg3 and self.settings_dict['OPTIONS'].get('server_side_binding') is not True:
            cursor = ServerSideCursor(self.connection, name=name, scrollable=False, withhold=self.connection.autocommit)
        else:
            cursor = self.connection.cursor(name, scrollable=False, withhold=self.connection.autocommit)
    else:
        cursor = self.connection.cursor()
    if is_psycopg3:
        tzloader = self.connection.adapters.get_loader(TIMESTAMPTZ_OID, Format.TEXT)
        if <MASK>:
            register_tzloader(self.timezone, cursor)
    else:
        cursor.tzinfo_factory = self.tzinfo_factory if settings.USE_TZ else None
    return cursor

def serializer_factory(value):
    if isinstance(value, Promise):
        value = str(value)
    elif isinstance(value, LazyObject):
        value = value.__reduce__()[1][0]
    if isinstance(value, models.Field):
        return ModelFieldSerializer(value)
    if isinstance(value, models.manager.BaseManager):
        return ModelManagerSerializer(value)
    if isinstance(value, Operation):
        return OperationSerializer(value)
    if isinstance(value, type):
        return TypeSerializer(value)
    if hasattr(value, 'deconstruct'):
        return DeconstructibleSerializer(value)
    for (type_, serializer_cls) in Serializer._registry.items():
        if <MASK>:
            return serializer_cls(value)
    raise ValueError('Cannot serialize: %r\nThere are some values Django cannot serialize into migration files.\nFor more, see https://docs.djangoproject.com/en/%s/topics/migrations/#migration-serializing' % (value, get_docs_version()))

def _parametrize_test(self, test, generic_cls, device_cls):
    """Parameterizes the given test function across each op and its associated dtypes."""
    if device_cls is None:
        raise RuntimeError('The @ops decorator is only intended to be used in a device-specific context; use it with instantiate_device_type_tests() instead of instantiate_parametrized_tests()')
    op = check_exhausted_iterator = object()
    for op in self.op_list:
        dtypes: Union[set[torch.dtype], set[None]]
        if isinstance(self.opinfo_dtypes, Sequence):
            dtypes = set(self.opinfo_dtypes)
        elif self.opinfo_dtypes == OpDTypes.unsupported_backward:
            dtypes = set(get_all_dtypes()).difference(op.supported_backward_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported_backward:
            dtypes = op.supported_backward_dtypes(device_cls.device_type)
        elif <MASK>:
            dtypes = set(get_all_dtypes()).difference(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported:
            dtypes = set(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.any_one:
            supported = op.supported_dtypes(device_cls.device_type)
            supported_backward = op.supported_backward_dtypes(device_cls.device_type)
            supported_both = supported.intersection(supported_backward)
            dtype_set = supported_both if len(supported_both) > 0 else supported
            for dtype in ANY_DTYPE_ORDER:
                if dtype in dtype_set:
                    dtypes = {dtype}
                    break
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.any_common_cpu_cuda_one:
            supported = set(op.dtypes).intersection(op.dtypesIfCUDA)
            if supported:
                dtypes = {next((dtype for dtype in ANY_DTYPE_ORDER if dtype in supported))}
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.none:
            dtypes = {None}
        else:
            raise RuntimeError(f'Unknown OpDType: {self.opinfo_dtypes}')
        if self.allowed_dtypes is not None:
            dtypes = dtypes.intersection(self.allowed_dtypes)
        test_name = op.formatted_name
        sample_skips_and_xfails = getattr(test, 'sample_skips_and_xfails', None)
        if sample_skips_and_xfails is not None:
            sample_skips_and_xfails = [rule for rule in sample_skips_and_xfails if rule.op_match_fn(device_cls.device_type, op)]
        for dtype in dtypes:
            param_kwargs = {'op': op}
            _update_param_kwargs(param_kwargs, 'dtype', dtype)
            try:

                @wraps(test)
                def test_wrapper(*args, **kwargs):
                    try:
                        return test(*args, **kwargs)
                    except unittest.SkipTest as e:
                        raise e
                    except Exception as e:
                        tracked_input = get_tracked_input()
                        if PRINT_REPRO_ON_FAILURE and tracked_input is not None:
                            e_tracked = Exception(f'{str(e)}\n\nCaused by {tracked_input.type_desc} at index {tracked_input.index}: {_serialize_sample(tracked_input.val)}')
                            e_tracked._tracked_input = tracked_input
                            raise e_tracked from e
                        raise e
                    finally:
                        clear_tracked_input()
                if self.skip_if_dynamo and (not TEST_WITH_TORCHINDUCTOR):
                    test_wrapper = skipIfTorchDynamo("Policy: we don't run OpInfo tests w/ Dynamo")(test_wrapper)
                test.tracked_input = None
                decorator_fn = partial(op.get_decorators, generic_cls.__name__, test.__name__, device_cls.device_type, dtype)
                if sample_skips_and_xfails is not None:
                    test_wrapper.sample_skips_and_xfails = sample_skips_and_xfails
                yield (test_wrapper, test_name, param_kwargs, decorator_fn)
            except Exception as ex:
                print(f'Failed to instantiate {test_name} for op {op.name}!')
                raise ex
    if op is check_exhausted_iterator:
        raise ValueError('An empty op_list was passed to @ops. Note that this may result from reuse of a generator.')

@staticmethod
def _gpu_add_multi_gpu(x, y):
    if <MASK>:
        return (x.to(0) + y, x - y.to(1))
