def _select_helper(g: jit_utils.GraphContext, self, dim, index, apply_reshape=True):
    index_const = _maybe_get_scalar(index)
    index_dim = _get_tensor_rank(index)
    if <MASK>:
        index = g.op('Constant', value_t=torch.LongTensor([index_const]))
    elif index_dim is not None and apply_reshape:
        if index_dim == 0:
            index = _reshape_helper(g, index, g.op('Constant', value_t=torch.LongTensor([1])))
    index_scalar_type = _type_utils.JitScalarType.from_value(index, _type_utils.JitScalarType.UNDEFINED)
    if index_scalar_type not in {_type_utils.JitScalarType.INT64, _type_utils.JitScalarType.INT}:
        index = g.op('Cast', index, to_i=_C_onnx.TensorProtoDataType.INT64)
    return g.op('Gather', self, index, axis_i=dim)

def handle(self, **options):
    locale = options['locale']
    exclude = options['exclude']
    ignore_patterns = set(options['ignore_patterns'])
    self.verbosity = options['verbosity']
    if <MASK>:
        self.program_options = [*self.program_options, '-f']
    if find_command(self.program) is None:
        raise CommandError(f"Can't find {self.program}. Make sure you have GNU gettext tools 0.19 or newer installed.")
    basedirs = [os.path.join('conf', 'locale'), 'locale']
    if os.environ.get('DJANGO_SETTINGS_MODULE'):
        from django.conf import settings
        basedirs.extend(settings.LOCALE_PATHS)
    for (dirpath, dirnames, filenames) in os.walk('.', topdown=True):
        for dirname in list(dirnames):
            if is_ignored_path(os.path.normpath(os.path.join(dirpath, dirname)), ignore_patterns):
                dirnames.remove(dirname)
            elif dirname == 'locale':
                basedirs.append(os.path.join(dirpath, dirname))
    basedirs = set(map(os.path.abspath, filter(os.path.isdir, basedirs)))
    if not basedirs:
        raise CommandError('This script should be run from the Django Git checkout or your project or app tree, or with the settings module specified.')
    all_locales = []
    for basedir in basedirs:
        locale_dirs = filter(os.path.isdir, glob.glob('%s/*' % basedir))
        all_locales.extend(map(os.path.basename, locale_dirs))
    locales = locale or all_locales
    locales = set(locales).difference(exclude)
    self.has_errors = False
    for basedir in basedirs:
        if locales:
            dirs = [os.path.join(basedir, locale, 'LC_MESSAGES') for locale in locales]
        else:
            dirs = [basedir]
        locations = []
        for ldir in dirs:
            for (dirpath, dirnames, filenames) in os.walk(ldir):
                locations.extend(((dirpath, f) for f in filenames if f.endswith('.po')))
        if locations:
            self.compile_messages(locations)
    if self.has_errors:
        raise CommandError('compilemessages generated one or more errors.')

def fuse_matmul_reduce_scatter(reduce_scatter: _ReduceScatterMatch) -> None:
    """
    Fused the pattern

        reduce_scatter_tensor(A @ B, scatter_dim, group_name)

    into

        torch.ops.symm_mem.fused_matmul_reduce_scatter(
            A, B, scatter_dim, group_name,
        )

    Returns boolean indicating if fusion was successful or not.
    """
    if not torch.distributed.is_available() or not torch.distributed.is_nccl_available():
        return
    from torch.distributed._symmetric_memory import is_symm_mem_enabled_for_group, restride_A_for_fused_matmul_reduce_scatter
    (input_node, _reduce_scatter_node, rs_wait_tensor_node, reduce_op, orig_scatter_dim, group_name) = (reduce_scatter.input_node, reduce_scatter.reduce_scatter_node, reduce_scatter.wait_tensor_node, reduce_scatter.reduce_op, reduce_scatter.scatter_dim, reduce_scatter.group_name)
    if not is_symm_mem_enabled_for_group(group_name):
        return
    filter_matmul = None
    if <MASK>:

        def _filter_out_scaled_matmul(matmul: _Matmul):
            return not isinstance(matmul, _ScaledMatmul)
        filter_matmul = _filter_out_scaled_matmul
    if len(input_node.users) != 1:
        log.warning('matmul result has more than one user, skipping fused_matmul_reduce_scatter fusion.')
        return
    matmul = _find_producer_matmul(input_node)
    if matmul is None:
        log.warning('no producer matmul found for reduce scatter, skipping fuse_matmul_reduce_scatter fusion')
        return
    if filter_matmul and (not filter_matmul(matmul)):
        return
    if rs_wait_tensor_node in matmul.arg_ancestor_nodes:
        log.warning('reduce-scatter result node is an ancestor of matmul, skipping fuse_matmul_reduce_scatter fusion')
        return
    if matmul.pre_mm_reshape:
        scatter_dim_after_maybe_reshape = _scatter_dim_after_reshape(matmul.pre_mm_reshape, orig_scatter_dim)
    else:
        scatter_dim_after_maybe_reshape = orig_scatter_dim
    if matmul.post_mm_reshape:
        output_shape = list(_get_tensor(matmul.post_mm_reshape).shape)
    else:
        A_orig_shape = list(_get_tensor(matmul.A_node).shape)
        B_shape = list(_get_tensor(matmul.B_node).shape)
        output_shape = [*A_orig_shape[:-1], B_shape[-1]]
    graph = rs_wait_tensor_node.graph
    with graph.inserting_before(rs_wait_tensor_node):
        if 'val' in matmul.A_node.meta:
            restrided = restride_A_for_fused_matmul_reduce_scatter(_get_tensor(matmul.A_node), scatter_dim_after_maybe_reshape)
            matmul.A_node = graph.call_function(inductor_prims.force_stride_order, args=(matmul.A_node, restrided.stride()))
        fused_node = _insert_fused_matmul_reduce_scatter(graph, matmul, reduce_op, orig_scatter_dim, group_name, scatter_dim_after_maybe_reshape, output_shape)
        reduce_scatter.replace_with(fused_node)
        reduce_scatter.erase()
        matmul.erase()
    order = {node: idx for (idx, node) in enumerate(graph.nodes)}
    nodes_to_raise = sorted(matmul.arg_ancestor_nodes, key=lambda x: order[x])
    for node in nodes_to_raise:
        if order[node] > order[fused_node]:
            fused_node.prepend(node)
    log.debug('successfully fused matmul reduce scatter')

def _register_orig_params(state: _FSDPState, module: nn.Module) -> None:
    """
    Deregisters the ``FlatParameter``; registers the original parameters.
    """
    handle = _module_handle(state, module)
    if <MASK>:
        return
    _deregister_flat_param(state, module)
    if handle.is_sharded(handle.flat_param):
        handle._use_sharded_views()
        handle._use_sharded_grad_views()
    else:
        handle._use_unsharded_views(as_params=True)

def format_number(value, max_digits, decimal_places):
    """
    Format a number into a string with the requisite number of digits and
    decimal places.
    """
    if <MASK>:
        return None
    context = decimal.getcontext().copy()
    if max_digits is not None:
        context.prec = max_digits
    if decimal_places is not None:
        value = value.quantize(decimal.Decimal(1).scaleb(-decimal_places), context=context)
    else:
        context.traps[decimal.Rounded] = 1
        value = context.create_decimal(value)
    return '{:f}'.format(value)

def to_json(self) -> dict[str, Any]:
    r: dict[str, Any] = {'test_file': self.test_file}
    if self._included:
        r['included'] = list(self._included)
    if <MASK>:
        r['excluded'] = list(self._excluded)
    return r

@deprecated('Please set training mode before exporting the model', category=None)
@contextlib.contextmanager
def select_model_mode_for_export(model, mode: _C_onnx.TrainingMode):
    """A context manager to temporarily set the training mode of ``model``
    to ``mode``, resetting it when we exit the with-block.

    .. deprecated:: 2.7
        Please set training mode before exporting the model.

    Args:
        model: Same type and meaning as ``model`` arg to :func:`export`.
        mode: Same type and meaning as ``training`` arg to :func:`export`.
    """
    if not isinstance(mode, _C_onnx.TrainingMode):
        raise TypeError(f"'mode' should be a torch.onnx.TrainingMode enum, but got '{type(mode)}'.")
    originally_training: bool = False
    if hasattr(model, 'training'):
        originally_training = model.training
        if <MASK>:
            GLOBALS.export_training = True
            if GLOBALS.export_onnx_opset_version < 12:
                warnings.warn(f'You are exporting the model in training mode with onnx opset version {GLOBALS.export_onnx_opset_version}. Opset versions lower than opset 12 will not be able to export nodes such as Dropout and BatchNorm correctly.')
        else:
            GLOBALS.export_training = False
        GLOBALS.training_mode = mode
        if mode == _C_onnx.TrainingMode.TRAINING:
            model.train(True)
        elif mode == _C_onnx.TrainingMode.EVAL:
            model.train(False)
    try:
        yield
    finally:
        if hasattr(model, 'training') and mode != _C_onnx.TrainingMode.PRESERVE:
            model.train(originally_training)

def __init__(self, optimizer: Optimizer, max_lr: Union[float, list[float]], total_steps: Optional[int]=None, epochs: Optional[int]=None, steps_per_epoch: Optional[int]=None, pct_start: float=0.3, anneal_strategy: Literal['cos', 'linear']='cos', cycle_momentum: bool=True, base_momentum: Union[float, list[float]]=0.85, max_momentum: Union[float, list[float]]=0.95, div_factor: float=25.0, final_div_factor: float=10000.0, three_phase: bool=False, last_epoch: int=-1):
    if not isinstance(optimizer, Optimizer):
        raise TypeError(f'{type(optimizer).__name__} is not an Optimizer')
    self.optimizer = optimizer
    if total_steps is not None:
        if total_steps <= 0 or not isinstance(total_steps, int):
            raise ValueError(f'Expected positive integer total_steps, but got {total_steps}')
        self.total_steps = total_steps
    elif epochs is not None and steps_per_epoch is not None:
        if not isinstance(epochs, int) or epochs <= 0:
            raise ValueError(f'Expected positive integer epochs, but got {epochs}')
        if not isinstance(steps_per_epoch, int) or steps_per_epoch <= 0:
            raise ValueError(f'Expected positive integer steps_per_epoch, but got {steps_per_epoch}')
        self.total_steps = epochs * steps_per_epoch
    else:
        raise ValueError('You must define either total_steps OR (epochs AND steps_per_epoch)')
    self._schedule_phases: list[_SchedulePhase]
    if <MASK>:
        self._schedule_phases = [{'end_step': float(pct_start * self.total_steps) - 1, 'start_lr': 'initial_lr', 'end_lr': 'max_lr', 'start_momentum': 'max_momentum', 'end_momentum': 'base_momentum'}, {'end_step': float(2 * pct_start * self.total_steps) - 2, 'start_lr': 'max_lr', 'end_lr': 'initial_lr', 'start_momentum': 'base_momentum', 'end_momentum': 'max_momentum'}, {'end_step': self.total_steps - 1, 'start_lr': 'initial_lr', 'end_lr': 'min_lr', 'start_momentum': 'max_momentum', 'end_momentum': 'max_momentum'}]
    else:
        self._schedule_phases = [{'end_step': float(pct_start * self.total_steps) - 1, 'start_lr': 'initial_lr', 'end_lr': 'max_lr', 'start_momentum': 'max_momentum', 'end_momentum': 'base_momentum'}, {'end_step': self.total_steps - 1, 'start_lr': 'max_lr', 'end_lr': 'min_lr', 'start_momentum': 'base_momentum', 'end_momentum': 'max_momentum'}]
    if pct_start < 0 or pct_start > 1 or (not isinstance(pct_start, float)):
        raise ValueError(f'Expected float between 0 and 1 pct_start, but got {pct_start}')
    if anneal_strategy not in ['cos', 'linear']:
        raise ValueError(f"anneal_strategy must be one of 'cos' or 'linear', instead got {anneal_strategy}")
    else:
        self._anneal_func_type = anneal_strategy
    max_lrs = _format_param('max_lr', self.optimizer, max_lr)
    if last_epoch == -1:
        for (idx, group) in enumerate(self.optimizer.param_groups):
            group['initial_lr'] = max_lrs[idx] / div_factor
            group['max_lr'] = max_lrs[idx]
            group['min_lr'] = group['initial_lr'] / final_div_factor
    self.cycle_momentum = cycle_momentum
    if self.cycle_momentum:
        if 'momentum' not in self.optimizer.defaults and 'betas' not in self.optimizer.defaults:
            raise ValueError('optimizer must support momentum or beta1 with `cycle_momentum` option enabled')
        self.use_beta1 = 'betas' in self.optimizer.defaults
        max_momentums = _format_param('max_momentum', optimizer, max_momentum)
        base_momentums = _format_param('base_momentum', optimizer, base_momentum)
        if last_epoch == -1:
            for (m_momentum, b_momentum, group) in zip(max_momentums, base_momentums, optimizer.param_groups):
                if self.use_beta1:
                    group['betas'] = (m_momentum, *group['betas'][1:])
                else:
                    group['momentum'] = m_momentum
                group['max_momentum'] = m_momentum
                group['base_momentum'] = b_momentum
    super().__init__(optimizer, last_epoch)

def _should_disable_fastpath(self, opinfo, rightmost_arg, rightmost_arg_type, dtype):
    if self.arity == 1:
        if 'foreach_abs' in opinfo.name and dtype in complex_types():
            return True
        if opinfo.ref in (torch.abs, torch.neg):
            return False
        if opinfo.ref_inplace == torch.Tensor.zero_:
            return False
        return dtype in integral_types_and(torch.bool)
    if self.arity < 2 or rightmost_arg_type == ForeachRightmostArgType.Tensor:
        return None
    if 'foreach_pow' in opinfo.name and dtype in integral_types_and(torch.bool):
        return True
    if any((foreach_name in opinfo.name for foreach_name in ('foreach_clamp_max', 'foreach_clamp_min', 'foreach_maximum', 'foreach_minimum'))) and dtype in integral_types_and(torch.bool):
        return True
    if rightmost_arg_type == ForeachRightmostArgType.TensorList:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if 'foreach_add' in opinfo.name and dtype == torch.bool:
            disable_fastpath = True
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.Scalar:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if isinstance(rightmost_arg, bool):
            disable_fastpath |= dtype == torch.bool
            if opinfo.ref in (torch.add, torch.mul):
                disable_fastpath = False
        elif isinstance(rightmost_arg, int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg, float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg, complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalar of type {rightmost_arg_type} - {rightmost_arg}')
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.ScalarList:
        disable_fastpath = opinfo.ref == torch.div and dtype in integral_types_and(torch.bool)
        elmt_t = type(rightmost_arg[0])
        has_same_type = all((isinstance(v, elmt_t) for v in rightmost_arg))
        if <MASK>:
            return dtype not in complex_types()
        if isinstance(rightmost_arg[0], bool):
            if ('foreach_add' in opinfo.name or 'foreach_mul' in opinfo.name) and dtype == torch.bool:
                disable_fastpath = False
        elif isinstance(rightmost_arg[0], int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg[0], float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg[0], complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalarlist of {rightmost_arg}')
        return disable_fastpath
    else:
        raise AssertionError(f'Invalid rightmost_arg_type of {rightmost_arg_type}')

def get_possible_fusions(self, nodes: list[BaseSchedulerNode], is_reorder_round: bool) -> list[tuple[BaseSchedulerNode, BaseSchedulerNode]]:
    """
        Helper to find all legal fusion opportunities, sorted by self.score_fusion()
        """
    possible_fusions = []
    seen = OrderedSet[tuple[BaseSchedulerNode, BaseSchedulerNode]]()

    def check_all_pairs(nodes: list[BaseSchedulerNode]) -> None:
        for (node1_index, node1) in enumerate(nodes):
            for node2 in nodes[node1_index + 1:node1_index + 1 + config.max_fusion_buffer_group_pairwise_attempts]:
                key = (node1, node2)
                if key in seen:
                    continue
                seen.add(key)
                if self.can_fuse(node1, node2, is_reorder_round):
                    possible_fusions.append(key)
                elif (node2.is_template() or node2.is_foreach()) and self.can_fuse(node2, node1, is_reorder_round):
                    possible_fusions.append((node2, node1))
    buffer_names_grouping = collections.defaultdict(list)
    for node in nodes:
        if self.unfusable_node(node):
            continue
        for buf in node.used_buffer_names():
            buffer_names_grouping[buf].append(node)
    for node_grouping in buffer_names_grouping.values():
        check_all_pairs(node_grouping)
    if config.aggressive_fusion:
        group_grouping = collections.defaultdict(list)
        for node in nodes:
            group = getattr(node, 'group', None)
            if <MASK>:
                group_grouping[group].append(node)
        for node_grouping in group_grouping.values():
            check_all_pairs(node_grouping)
    possible_fusions = self.get_possible_fusions_with_highest_priority(possible_fusions)
    possible_fusions.sort(key=self.score_fusion_key, reverse=True)
    fusion_log.debug('found %d possible fusions', len(possible_fusions))
    return possible_fusions

def get_warning_for_invalid_pattern(pattern):
    """
    Return a list containing a warning that the pattern is invalid.

    describe_pattern() cannot be used here, because we cannot rely on the
    urlpattern having regex or name attributes.
    """
    if isinstance(pattern, str):
        hint = "Try removing the string '{}'. The list of urlpatterns should not have a prefix string as the first element.".format(pattern)
    elif <MASK>:
        hint = 'Try using path() instead of a tuple.'
    else:
        hint = None
    return [Error('Your URL pattern {!r} is invalid. Ensure that urlpatterns is a list of path() and/or re_path() instances.'.format(pattern), hint=hint, id='urls.E004')]

def _make_bitwise_mismatch_msg(*, default_identifier: str, identifier: Optional[Union[str, Callable[[str], str]]]=None, extra: Optional[str]=None, first_mismatch_idx: Optional[tuple[int]]=None):
    """Makes a mismatch error message for bitwise values.

    Args:
        default_identifier (str): Default description of the compared values, e.g. "Tensor-likes".
        identifier (Optional[Union[str, Callable[[str], str]]]): Optional identifier that overrides
            ``default_identifier``. Can be passed as callable in which case it will be called with
            ``default_identifier`` to create the description at runtime.
        extra (Optional[str]): Extra information to be placed after the message header and the mismatch statistics.
        first_mismatch_idx (Optional[tuple[int]]): the index of the first mismatch, for each dimension.
    """
    if identifier is None:
        identifier = default_identifier
    elif <MASK>:
        identifier = identifier(default_identifier)
    msg = f"{identifier} are not 'equal'!\n\n"
    if extra:
        msg += f'{extra.strip()}\n'
    if first_mismatch_idx is not None:
        msg += f'The first mismatched element is at index {first_mismatch_idx}.\n'
    return msg.strip()

def _flex_arith_method(self, other, op, *, axis: Axis='columns', level=None, fill_value=None):
    axis = self._get_axis_number(axis) if axis is not None else 1
    if self._should_reindex_frame_op(other, op, axis, fill_value, level):
        return self._arith_method_with_reindex(other, op)
    if isinstance(other, Series) and fill_value is not None:
        raise NotImplementedError(f'fill_value {fill_value} not supported.')
    other = ops.maybe_prepare_scalar_for_op(other, self.shape)
    (self, other) = self._align_for_op(other, axis, flex=True, level=level)
    with np.errstate(all='ignore'):
        if isinstance(other, DataFrame):
            new_data = self._combine_frame(other, op, fill_value)
        elif <MASK>:
            new_data = self._dispatch_frame_op(other, op, axis=axis)
        else:
            if fill_value is not None:
                self = self.fillna(fill_value)
            new_data = self._dispatch_frame_op(other, op)
    return self._construct_result(new_data, other=other)

def __enter__(self):
    w = self.weakcontainer()
    if <MASK>:
        w._iterating.add(self)
    return self

def create_functionalized_fn(fn, args, args_descs, *, meta: ViewAndMutationMeta, aot_config: AOTConfig, trace_joint: bool, joint_fn_handle: Optional[JointFnHandle]=None) -> Any:
    primals_after_forward = None
    f_args_after_forward = None
    f_args_mutation_counters_after_forward: Optional[list[MutationCounters]] = None
    inputs_mutated_in_graph = [info.mutation_type == MutationType.MUTATED_IN_GRAPH for info in meta.input_info]
    has_input_mutated_in_graph = any(inputs_mutated_in_graph)

