def memoize(f):
    _memoized = {}

    def wrapped(*args):
        if <MASK>:
            _memoized[args] = f(*args)
        return _memoized[args].copy()
    return f

def _maybe_null_out(result: np.ndarray | float | NaTType, axis: AxisInt | None, mask: npt.NDArray[np.bool_] | None, shape: tuple[int, ...], min_count: int=1, datetimelike: bool=False) -> np.ndarray | float | NaTType:
    """
    Returns
    -------
    Dtype
        The product of all elements on a given axis. ( NaNs are treated as 1)
    """
    if mask is None and min_count == 0:
        return result
    if axis is not None and isinstance(result, np.ndarray):
        if mask is not None:
            null_mask = mask.shape[axis] - mask.sum(axis) - min_count < 0
        else:
            below_count = shape[axis] - min_count < 0
            new_shape = shape[:axis] + shape[axis + 1:]
            null_mask = np.broadcast_to(below_count, new_shape)
        if np.any(null_mask):
            if datetimelike:
                result[null_mask] = iNaT
            elif <MASK>:
                if np.iscomplexobj(result):
                    result = result.astype('c16')
                elif not is_float_dtype(result):
                    result = result.astype('f8', copy=False)
                result[null_mask] = np.nan
            else:
                result[null_mask] = None
    elif result is not NaT:
        if check_below_min_count(shape, mask, min_count):
            result_dtype = getattr(result, 'dtype', None)
            if is_float_dtype(result_dtype):
                result = result_dtype.type('nan')
            else:
                result = np.nan
    return result

def _annotate_qat_conv2d_bn(self, gm: torch.fx.GraphModule, quantization_config: Optional[QuantizationConfig], filter_fn: Optional[FilterFn]=None) -> None:
    fused_partitions = find_sequential_partitions(gm, [torch.nn.Conv2d, torch.nn.BatchNorm2d])
    for fused_partition in fused_partitions:
        (conv_partition, bn_partition) = fused_partition
        (conv_node, bn_output_node) = self._get_output_nodes_of_partitions([conv_partition, bn_partition])
        if conv_node.op != 'call_function' or conv_node.target != torch.ops.aten.conv2d.default:
            continue
        if _skip_annotate([bn_output_node, conv_node], filter_fn):
            continue
        self._annotate_conv_node_helper(conv_node, False, quantization_config)
        if <MASK>:
            bn_output_node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation(output_qspec=get_output_act_qspec(quantization_config), _annotated=True, _is_output_of_quantized_pattern=True)
        else:
            _annotate_nodes_not_quantize(bn_output_node)
        nodes_to_mark_annotated = list(conv_partition.nodes)
        nodes_to_mark_annotated.extend(list(bn_partition.nodes))
        _mark_nodes_as_annotated(nodes_to_mark_annotated)

@doc(ExtensionArray.searchsorted)
def searchsorted(self, value: NumpyValueArrayLike | ExtensionArray, side: Literal['left', 'right']='left', sorter: NumpySorter | None=None) -> npt.NDArray[np.intp] | np.intp:
    if self._hasna:
        raise ValueError('searchsorted requires array to be sorted, which is impossible with NAs present.')
    if isinstance(value, ExtensionArray):
        value = value.astype(object)
    dtype = None
    if <MASK>:
        pa_dtype = self.dtype.pyarrow_dtype
        if (pa.types.is_timestamp(pa_dtype) or pa.types.is_duration(pa_dtype)) and pa_dtype.unit == 'ns':
            dtype = object
    return self.to_numpy(dtype=dtype).searchsorted(value, side=side, sorter=sorter)

def get_new_columns(self, value_columns: Index | None):
    if value_columns is None:
        if not self.has_nan:
            return self.removed_level._rename(name=self.removed_name)
        lev = self.removed_level.insert(0, item=self.removed_level._na_value)
        return lev.rename(self.removed_name)
    stride = len(self.removed_level) + self.has_nan
    width = len(value_columns)
    propagator = np.repeat(np.arange(width), stride)
    new_levels: FrozenList | list[Index]
    if <MASK>:
        new_levels = value_columns.levels + (self.removed_level_full,)
        new_names = value_columns.names + (self.removed_name,)
        new_codes = [lab.take(propagator) for lab in value_columns.codes]
    else:
        new_levels = [value_columns, self.removed_level_full]
        new_names = [value_columns.name, self.removed_name]
        new_codes = [propagator]
    repeater = self._repeater
    new_codes.append(np.tile(repeater, width))
    return MultiIndex(levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False)

def _check_categorical_features(self, X):
    """Check and validate categorical features in X

        Parameters
        ----------
        X : {array-like, pandas DataFrame} of shape (n_samples, n_features)
            Input data.

        Return
        ------
        is_categorical : ndarray of shape (n_features,) or None, dtype=bool
            Indicates whether a feature is categorical. If no feature is
            categorical, this is None.
        """
    if _is_pandas_df(X):
        X_is_dataframe = True
        categorical_columns_mask = np.asarray(X.dtypes == 'category')
    elif hasattr(X, '__dataframe__'):
        X_is_dataframe = True
        categorical_columns_mask = np.asarray([c.dtype[0].name == 'CATEGORICAL' for c in X.__dataframe__().get_columns()])
    else:
        X_is_dataframe = False
        categorical_columns_mask = None
    categorical_features = self.categorical_features
    categorical_by_dtype = isinstance(categorical_features, str) and categorical_features == 'from_dtype'
    no_categorical_dtype = categorical_features is None or (categorical_by_dtype and (not X_is_dataframe))
    if <MASK>:
        return None
    use_pandas_categorical = categorical_by_dtype and X_is_dataframe
    if use_pandas_categorical:
        categorical_features = categorical_columns_mask
    else:
        categorical_features = np.asarray(categorical_features)
    if categorical_features.size == 0:
        return None
    if categorical_features.dtype.kind not in ('i', 'b', 'U', 'O'):
        raise ValueError(f'categorical_features must be an array-like of bool, int or str, got: {categorical_features.dtype.name}.')
    if categorical_features.dtype.kind == 'O':
        types = set((type(f) for f in categorical_features))
        if types != {str}:
            raise ValueError(f"categorical_features must be an array-like of bool, int or str, got: {', '.join(sorted((t.__name__ for t in types)))}.")
    n_features = X.shape[1]
    feature_names_in_ = getattr(X, 'columns', None)
    if categorical_features.dtype.kind in ('U', 'O'):
        if feature_names_in_ is None:
            raise ValueError('categorical_features should be passed as an array of integers or as a boolean mask when the model is fitted on data without feature names.')
        is_categorical = np.zeros(n_features, dtype=bool)
        feature_names = list(feature_names_in_)
        for feature_name in categorical_features:
            try:
                is_categorical[feature_names.index(feature_name)] = True
            except ValueError as e:
                raise ValueError(f"categorical_features has a item value '{feature_name}' which is not a valid feature name of the training data. Observed feature names: {feature_names}") from e
    elif categorical_features.dtype.kind == 'i':
        if np.max(categorical_features) >= n_features or np.min(categorical_features) < 0:
            raise ValueError('categorical_features set as integer indices must be in [0, n_features - 1]')
        is_categorical = np.zeros(n_features, dtype=bool)
        is_categorical[categorical_features] = True
    else:
        if categorical_features.shape[0] != n_features:
            raise ValueError(f'categorical_features set as a boolean mask must have shape (n_features,), got: {categorical_features.shape}')
        is_categorical = categorical_features
    if not np.any(is_categorical):
        return None
    return is_categorical

def _deprecate_kwarg(func: F) -> F:

    @wraps(func)
    def wrapper(*args, **kwargs) -> Callable[..., Any]:
        __tracebackhide__ = True
        old_arg_value = kwargs.pop(old_arg_name, None)
        if old_arg_value is not None:
            if new_arg_name is None:
                msg = f'the {old_arg_name!r} keyword is deprecated and will be removed in a future version. Please take steps to stop the use of {old_arg_name!r}'
                warnings.warn(msg, klass, stacklevel=stacklevel)
                kwargs[old_arg_name] = old_arg_value
                return func(*args, **kwargs)
            elif mapping is not None:
                if callable(mapping):
                    new_arg_value = mapping(old_arg_value)
                else:
                    new_arg_value = mapping.get(old_arg_value, old_arg_value)
                msg = f'the {old_arg_name}={old_arg_value!r} keyword is deprecated, use {new_arg_name}={new_arg_value!r} instead.'
            else:
                new_arg_value = old_arg_value
                msg = f'the {old_arg_name!r} keyword is deprecated, use {new_arg_name!r} instead.'
            warnings.warn(msg, klass, stacklevel=stacklevel)
            if <MASK>:
                msg = f'Can only specify {old_arg_name!r} or {new_arg_name!r}, not both.'
                raise TypeError(msg)
            kwargs[new_arg_name] = new_arg_value
        return func(*args, **kwargs)
    return cast(F, wrapper)

