        return algorithm

def __init__(self, data=None, index=None, dtype: Dtype | None=None, name=None, copy: bool | None=None) -> None:
    allow_mgr = False
    if isinstance(data, SingleBlockManager) and index is None and (dtype is None) and (copy is False or copy is None):
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
        data = data.copy(deep=False)
        NDFrame.__init__(self, data)
        self.name = name
        return
    if isinstance(data, (ExtensionArray, np.ndarray)):
        if copy is not False:
            if dtype is None or astype_is_view(data.dtype, pandas_dtype(dtype)):
                data = data.copy()
    if copy is None:
        copy = False
    if isinstance(data, SingleBlockManager) and (not copy):
        data = data.copy(deep=False)
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
    name = ibase.maybe_extract_name(name, data, type(self))
    if index is not None:
        index = ensure_index(index)
    if <MASK>:
