    if data is None:
        index = index if index is not None else default_index(0)
        if len(index) or dtype is not None:
            data = na_value_for_dtype(pandas_dtype(dtype), compat=False)
        else:
            data = []
    if isinstance(data, MultiIndex):
        raise NotImplementedError('initializing a Series from a MultiIndex is not supported')
    refs = None
    if isinstance(data, Index):
        if dtype is not None:
            data = data.astype(dtype)
        refs = data._references
        copy = False
    elif isinstance(data, np.ndarray):
        if len(data.dtype):
            raise ValueError('Cannot construct a Series from an ndarray with compound dtype.  Use DataFrame instead.')
    elif isinstance(data, Series):
        if index is None:
            index = data.index
            data = data._mgr.copy(deep=False)
        else:
            data = data.reindex(index)
            copy = False
            data = data._mgr
    elif isinstance(data, Mapping):
        (data, index) = self._init_dict(data, index, dtype)
        dtype = None
        copy = False
    elif isinstance(data, SingleBlockManager):
        if index is None:
            index = data.index
        elif not data.index.equals(index) or copy:
            raise AssertionError('Cannot pass both SingleBlockManager `data` argument and a different `index` argument. `copy` must be False.')
        if not allow_mgr:
            warnings.warn(f'Passing a {type(data).__name__} to {type(self).__name__} is deprecated and will raise in a future version. Use public APIs instead.', Pandas4Warning, stacklevel=2)
            allow_mgr = True
    elif isinstance(data, ExtensionArray):
        pass
    else:
        data = com.maybe_iterable_to_list(data)
        if is_list_like(data) and (not len(data)) and (dtype is None):
            dtype = np.dtype(object)
    if index is None:
        if not is_list_like(data):
            data = [data]
        index = default_index(len(data))
    elif is_list_like(data):
        com.require_length_match(data, index)
    if isinstance(data, SingleBlockManager):
        if dtype is not None:
            data = data.astype(dtype=dtype)
        elif copy:
            data = data.copy()
    else:
        data = sanitize_array(data, index, dtype, copy)
        data = SingleBlockManager.from_array(data, index, refs=refs)
    NDFrame.__init__(self, data)
    self.name = name
    self._set_axis(0, index)

def most_specific_common_supertype(self, others: Sequence[trace.TraceType]) -> Optional['TypeSpec']:
    """Returns the most specific supertype TypeSpec  of `self` and `others`.

    Implements the tf.types.experimental.func.TraceType interface.

    If not overridden by a subclass, the default behavior is to assume the
    TypeSpec is covariant upon attributes that implement TraceType and
    invariant upon rest of the attributes as well as the structure and type
    of the TypeSpec.

    Args:
      others: A sequence of TraceTypes.
    """
    if <MASK>:
        return None
    has_supertype = True

    def make_supertype_attribute(attribute_self, *attribute_others):
        nonlocal has_supertype
        if not has_supertype:
            return
        if isinstance(attribute_self, trace.TraceType):
            attribute_supertype = attribute_self.most_specific_common_supertype(attribute_others)
            if attribute_supertype is None:
                has_supertype = False
                return
            return attribute_supertype
        else:
            if not all((attribute_self == attribute_other for attribute_other in attribute_others)):
                has_supertype = False
                return
            return attribute_self
    try:
        serialized_supertype = nest.map_structure(make_supertype_attribute, self._serialize(), *(o._serialize() for o in others))
    except (ValueError, TypeError):
        return None
    return self._deserialize(serialized_supertype) if has_supertype else None

@with_native_function_and_index
