@ops.RegisterGradient('SparseMatrixMatMul')
def _SparseMatrixMatMulGrad(op: ops.Operation, grad):
    """Gradient for sparse_matrix_mat_mul op."""
    t_a = op.get_attr('transpose_a')
    t_b = op.get_attr('transpose_b')
    adj_a = op.get_attr('adjoint_a')
    adj_b = op.get_attr('adjoint_b')
    transpose_output = op.get_attr('transpose_output')
    conjugate_output = op.get_attr('conjugate_output')
    a = op.inputs[0]
    b = op.inputs[1]
    conj = math_ops.conj
    sparse_matmul = sparse_csr_matrix_ops.sparse_matrix_mat_mul

    def matmul(x, y, **kwargs):
        return _PrunedDenseMatrixMultiplication(x, y, indices=sparse_csr_matrix_ops.csr_sparse_matrix_to_sparse_tensor(a, type=x.dtype).indices, **kwargs)
    if conjugate_output:
        grad = conj(grad)
    if <MASK>:
        if not adj_a and (not adj_b):
            a = conj(a)
            b = conj(b)
            if not t_a:
                grad_a = matmul(grad, b, transpose_b=not t_b)
            else:
                grad_a = matmul(b, grad, transpose_a=t_b, transpose_b=True)
            grad_b = sparse_matmul(a, grad, transpose_a=not t_a, transpose_output=t_b)
        elif not t_a and (not t_b):
            if not adj_a:
                grad_a = matmul(grad, b, adjoint_b=not adj_b)
            else:
                grad_a = matmul(b, grad, adjoint_a=adj_b, adjoint_b=True)
            grad_b = sparse_matmul(a, grad, adjoint_a=not adj_a, transpose_output=adj_b, conjugate_output=adj_b)
        elif adj_a and t_b:
            grad_a = matmul(b, grad, transpose_a=True, adjoint_b=True)
            grad_b = sparse_matmul(a, grad, transpose_output=True)
        elif t_a and adj_b:
            grad_a = matmul(b, grad, transpose_a=True, transpose_b=True)
            grad_b = sparse_matmul(conj(a), grad, transpose_output=True, conjugate_output=True)
    elif not adj_a and (not adj_b):
        a = conj(a)
        b = conj(b)
        if not t_a:
            grad_a = matmul(grad, b, transpose_a=True, transpose_b=not t_b)
        else:
            grad_a = matmul(b, grad, transpose_a=t_b)
        grad_b = sparse_matmul(a, grad, transpose_a=not t_a, transpose_b=True, transpose_output=t_b)
    elif not t_a and (not t_b):
        if not adj_a:
            grad_a = matmul(grad, b, transpose_a=True, adjoint_b=not adj_b)
        else:
            grad_a = matmul(b, conj(grad), adjoint_a=adj_b)
        grad_b = sparse_matmul(a, grad, adjoint_a=not adj_a, transpose_b=True, transpose_output=adj_b, conjugate_output=adj_b)
    elif adj_a and t_b:
        grad_a = matmul(b, conj(grad), transpose_a=True)
        grad_b = sparse_matmul(a, grad, transpose_b=True, transpose_output=True)
    elif t_a and adj_b:
        grad_a = matmul(b, grad, transpose_a=True)
        grad_b = sparse_matmul(a, grad, adjoint_b=True, transpose_output=True)
    return (grad_a, grad_b)

def _reset_flat_param_grad_info_if_needed(handles: list[FlatParamHandle]):
    """
    Clears the original parameters' gradients if needed. This method's CPU
    overhead is minimal, so we may call it throughout FSDP methods, which serve
    as callsites to free the gradient memory earlier.
    """
    if not isinstance(handles, list):
        handles = [handles]
    for handle in handles:
        if <MASK>:
            handle._reset_flat_param_grad_info_if_needed()

def _infer_steps(self, steps, dataset):
    """Infers steps_per_epoch needed to loop through a dataset."""
    if steps == -1:
        self._log_indefinite_training_warning()
        return None
    if <MASK>:
        return steps
    adapter_steps = self._adapter.get_size()
    if adapter_steps is not None:
        return adapter_steps
    size = cardinality.cardinality(dataset)
    if size == cardinality.INFINITE and steps is None:
        raise ValueError('When passing an infinitely repeating dataset, please specify a `steps_per_epoch` value so that epoch level callbacks continue to work. The value can be arbitrary, or a number that you think correctly defines the size of an epoch. Epoch-level callbacks will then be called at this interval.')
    if size >= 0:
        return size.numpy().item()
    return None

def __init__(self, unit: str_type | DatetimeTZDtype='ns', tz=None) -> None:
    if <MASK>:
        (unit, tz) = (unit.unit, unit.tz)
    if unit != 'ns':
        if isinstance(unit, str) and tz is None:
            result = type(self).construct_from_string(unit)
            unit = result.unit
            tz = result.tz
            msg = f"Passing a dtype alias like 'datetime64[ns, {tz}]' to DatetimeTZDtype is no longer supported. Use 'DatetimeTZDtype.construct_from_string()' instead."
            raise ValueError(msg)
        if unit not in ['s', 'ms', 'us', 'ns']:
            raise ValueError('DatetimeTZDtype only supports s, ms, us, ns units')
    if tz:
        tz = timezones.maybe_get_tz(tz)
        tz = timezones.tz_standardize(tz)
    elif tz is not None:
        raise zoneinfo.ZoneInfoNotFoundError(tz)
    if tz is None:
        raise TypeError("A 'tz' is required.")
    self._unit = unit
    self._tz = tz

def reinplace_and_refine_tensors_to_clone(old_tensors_to_clone, kwargs, node_name, trigger):
    tensors_to_clone: list[str] = []
    storage_of_reinplaced_args = OrderedSet[int | None]()
    missed_nodes = []
    missed_args = []

    def tensor_with_same_storage_already_reinplaced(arg):
        if <MASK>:
            return any((get_node_storage(a) in storage_of_reinplaced_args for a in arg))
        return get_node_storage(mutated_arg) in storage_of_reinplaced_args
    for arg in old_tensors_to_clone:
        assert arg in kwargs
        mutated_arg = kwargs[arg]
        should_attempt_reinplace = not tensor_with_same_storage_already_reinplaced(mutated_arg)
        if should_attempt_reinplace and can_inplace(node, mutated_arg):
            copy_node = copy_args_to_copy_nodes.get((mutated_arg, node))
            if copy_node is not None:
                replace_dict[copy_node] = copy_node.args[0]
            if trigger != ReInplaceTrigger.AUTO_FUNC_V2:
                for user in node.users:
                    if user.target == operator.getitem and user.args[1] == arg:
                        replace_dict[user] = mutated_arg
            if isinstance(mutated_arg, (list, tuple)):
                for a in mutated_arg:
                    storage_of_reinplaced_args.add(get_node_storage(a))
            else:
                storage_of_reinplaced_args.add(get_node_storage(mutated_arg))
        else:
            if should_attempt_reinplace:
                missed_args.append(arg)
                missed_nodes.append(mutated_arg)
            tensors_to_clone.append(arg)
    log_inplace_results(node_name, old_tensors_to_clone, tensors_to_clone, missed_args, missed_nodes, trigger)
    return tensors_to_clone

def register_adapter(aten: Union[str, list[str]]) -> Callable[[AdapterType], AdapterType]:

    def decorator(func: AdapterType) -> AdapterType:
