def check_outer_fusion_loop_level_attr(self, cpp_kernel_proxy_list, outer_loop_fusion_depth):

    def _inner(left_loop_nest: LoopNest, right_loop_nest: LoopNest, loop_fusion_depth: int, current_checking_depth: int) -> bool:
        assert left_loop_nest.loops
        assert right_loop_nest.loops
        left_loop_level = left_loop_nest.loops[current_checking_depth]
        right_loop_level = right_loop_nest.loops[current_checking_depth]
        outer_loops_attr_compare_list = ['var', 'size', 'offset', 'steps']
        if <MASK>:
            return False
        assert loop_fusion_depth >= 1
        if (loop_fusion_depth := (loop_fusion_depth - 1)) > 0:
            current_checking_depth = current_checking_depth + 1
            assert current_checking_depth < len(left_loop_nest.loops)
            assert current_checking_depth < len(right_loop_nest.loops)
            if not _inner(left_loop_nest, right_loop_nest, loop_fusion_depth, current_checking_depth):
                return False
        return True
    for idx in range(len(cpp_kernel_proxy_list) - 1):
        left_loop_nest = cpp_kernel_proxy_list[idx].loop_nest
        right_loop_nest = cpp_kernel_proxy_list[idx + 1].loop_nest
        if not _inner(left_loop_nest, right_loop_nest, outer_loop_fusion_depth, 0):
            return False
    for cpp_kernel_proxy in cpp_kernel_proxy_list:
        outer_ranges = functools.reduce(operator.mul, cpp_kernel_proxy.ranges[:outer_loop_fusion_depth])
        if len(cpp_kernel_proxy.ranges) > outer_loop_fusion_depth and isinstance(outer_ranges, sympy.Integer) and isinstance(cpp_kernel_proxy.ranges[outer_loop_fusion_depth], sympy.Integer) and (outer_ranges * 300 < cpp_kernel_proxy.ranges[outer_loop_fusion_depth]):
            return False
    return True

def is_namedtuple_cls(cls: Any) -> bool:
    """Test if an object is a namedtuple or a (torch.return_types|torch.autograd.forward_ad).* quasi-namedtuple"""
    try:
        if <MASK>:
            module = getattr(cls, '__module__', None)
            if module in ('torch.return_types', 'torch.autograd.forward_ad'):
                return True
            if isinstance(getattr(cls, '_fields', None), tuple) and callable(getattr(cls, '_make', None)):
                bases = tuple((t for t in cls.__bases__ if t is not Generic))
                if bases == (tuple,):
                    return True
                if bases and any((is_namedtuple_cls(t) and cls.__new__ is t.__new__ for t in bases)):
                    return True
    except TypeError:
        pass
    return False

@classmethod
def from_float(cls, mod, use_precomputed_fake_quant=False):
    assert type(mod) in {torch.nn.LSTMCell, torch.nn.GRUCell, torch.nn.RNNCell}, 'nn.quantized.dynamic.RNNCellBase.from_float                                  only works for nn.LSTMCell, nn.GRUCell and nn.RNNCell'
    assert hasattr(mod, 'qconfig'), 'Input float module must have qconfig defined'
    if <MASK>:
        weight_observer_method = mod.qconfig.weight
    else:
        from torch.ao.quantization.qconfig import default_dynamic_qconfig
        weight_observer_method = default_dynamic_qconfig.weight
    dtype = weight_observer_method().dtype
    supported_scalar_types = [torch.qint8, torch.float16]
    if dtype not in supported_scalar_types:
        raise RuntimeError(f'Unsupported dtype for dynamic RNN quantization: {dtype}')
    qRNNCellBase: Union[LSTMCell, GRUCell, RNNCell]
    if type(mod) is torch.nn.LSTMCell:
        qRNNCellBase = LSTMCell(mod.input_size, mod.hidden_size, bias=mod.bias, dtype=dtype)
    elif type(mod) is torch.nn.GRUCell:
        qRNNCellBase = GRUCell(mod.input_size, mod.hidden_size, bias=mod.bias, dtype=dtype)
    elif type(mod) is torch.nn.RNNCell:
        qRNNCellBase = RNNCell(mod.input_size, mod.hidden_size, bias=mod.bias, nonlinearity=mod.nonlinearity, dtype=dtype)
    else:
        raise NotImplementedError('Only LSTMCell, GRUCell and RNNCell             are supported for QuantizedRNN for now')
    assert mod.bias

    def _observe_and_quantize_weight(weight):
        if dtype == torch.qint8:
            weight_observer = weight_observer_method()
            weight_observer(weight)
            qweight = _quantize_weight(weight.float(), weight_observer)
            return qweight
        else:
            return weight.float()
    qRNNCellBase._packed_weight_ih = pack_weight_bias(_observe_and_quantize_weight(mod.weight_ih), mod.bias_ih, dtype)
    qRNNCellBase._packed_weight_hh = pack_weight_bias(_observe_and_quantize_weight(mod.weight_hh), mod.bias_hh, dtype)
    return qRNNCellBase

def dispatch_functionalize(func, mode: FunctionalTensorMode=FunctionalTensorMode()):

    def to_fun(t):
        if <MASK>:
            return FunctionalTensor.to_functional(t)
        return t

    def from_fun(t):
        if not isinstance(t, FunctionalTensor):
            if isinstance(t, torch.Tensor):
                assert not torch._is_functional_tensor(t)
            return t
        torch._sync(t)
        return torch._from_functional_tensor(t.elem)

    def inner(*args, **kwargs):
        disable_above = torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize))
        with disable_above, mode:
            func_args = pytree.tree_map_only(torch.Tensor, to_fun, args)
            func_kwargs = pytree.tree_map_only(torch.Tensor, to_fun, kwargs)
            func_outputs = func(*func_args, **func_kwargs)
            outputs = pytree.tree_map_only(FunctionalTensor, from_fun, func_outputs)
            return outputs
    return inner

def cb_routsign2map(rout, um):
    """
    name,begintitle,endtitle,argname
    ctype,rctype,maxnofargs,nofoptargs,returncptr
    """
    ret = {'name': f"cb_{rout['name']}_in_{um}", 'returncptr': ''}
    if isintent_callback(rout):
        if '_' in rout['name']:
            F_FUNC = 'F_FUNC_US'
        else:
            F_FUNC = 'F_FUNC'
        ret['callbackname'] = f"{F_FUNC}({rout['name'].lower()},{rout['name'].upper()})"
        ret['static'] = 'extern'
    else:
        ret['callbackname'] = ret['name']
        ret['static'] = 'static'
    ret['argname'] = rout['name']
    ret['begintitle'] = gentitle(ret['name'])
    ret['endtitle'] = gentitle(f"end of {ret['name']}")
    ret['ctype'] = getctype(rout)
    ret['rctype'] = 'void'
    if ret['ctype'] == 'string':
        ret['rctype'] = 'void'
    else:
        ret['rctype'] = ret['ctype']
    if ret['rctype'] != 'void':
        if iscomplexfunction(rout):
            ret['returncptr'] = '\n#ifdef F2PY_CB_RETURNCOMPLEX\nreturn_value=\n#endif\n'
        else:
            ret['returncptr'] = 'return_value='
    if ret['ctype'] in cformat_map:
        ret['showvalueformat'] = f"{cformat_map[ret['ctype']]}"
    if <MASK>:
        ret['strlength'] = getstrlength(rout)
    if isfunction(rout):
        if 'result' in rout:
            a = rout['result']
        else:
            a = rout['name']
        if hasnote(rout['vars'][a]):
            ret['note'] = rout['vars'][a]['note']
            rout['vars'][a]['note'] = ['See elsewhere.']
        ret['rname'] = a
        (ret['pydocsign'], ret['pydocsignout']) = getpydocsign(a, rout)
        if iscomplexfunction(rout):
            ret['rctype'] = '\n#ifdef F2PY_CB_RETURNCOMPLEX\n#ctype#\n#else\nvoid\n#endif\n'
    elif hasnote(rout):
        ret['note'] = rout['note']
        rout['note'] = ['See elsewhere.']
    nofargs = 0
    nofoptargs = 0
    if 'args' in rout and 'vars' in rout:
        for a in rout['args']:
            var = rout['vars'][a]
            if l_or(isintent_in, isintent_inout)(var):
                nofargs = nofargs + 1
                if isoptional(var):
                    nofoptargs = nofoptargs + 1
    ret['maxnofargs'] = repr(nofargs)
    ret['nofoptargs'] = repr(nofoptargs)
    if hasnote(rout) and isfunction(rout) and ('result' in rout):
        ret['routnote'] = rout['note']
        rout['note'] = ['See elsewhere.']
    return ret

def partial_shape_to_tensor(shape_like):
    """Returns a `tf.Tensor` that represents the given shape.

  Args:
    shape_like: A value that can be converted to a `tf.TensorShape` or a
      `tf.Tensor`.

  Returns:
    A 1-D `tf.Tensor` of `tf.int64` elements representing the given shape, where
    `-1` is substituted for any unknown dimensions.
  """
    try:
        shape_like = tensor_shape.as_shape(shape_like)
        return ops.convert_to_tensor([dim if dim is not None else -1 for dim in shape_like.as_list()], dtype=dtypes.int64)
    except (TypeError, ValueError):
        ret = ops.convert_to_tensor(shape_like, preferred_dtype=dtypes.int64)
        if <MASK>:
