def dot(lhs: Any, rhs: Any, sum_dims: Any) -> Union[_Tensor, torch.Tensor]:
    """
    Perform dot product between two tensors along specified dimensions.

    Args:
        lhs: Left-hand side tensor
        rhs: Right-hand side tensor
        sum_dims: Dimensions to sum over (contract)

    Returns:
        Result of dot product
    """
    lhs_info = TensorInfo.create(lhs, ensure_batched=False, ensure_present=False)
    rhs_info = TensorInfo.create(rhs, ensure_batched=False, ensure_present=False)
    if not (lhs_info and rhs_info):
        return torch.matmul(lhs, rhs)
    assert lhs_info.tensor is not None and rhs_info.tensor is not None, 'Cannot perform dot product on None tensors'
    lhs_strides = lhs_info.tensor.stride()
    rhs_strides = rhs_info.tensor.stride()
    lro_dims = DotPart()
    lo_dims = DotPart()
    ro_dims = DotPart()
    lr_dims = DotPart()

    def insert_dim(d: Any, lhs_idx: Any, rhs_idx: Any) -> None:
        """Insert dimension into appropriate part based on stride pattern."""
        reduced = d in sum_dims
        lhs_stride = lhs_strides[lhs_idx] if lhs_idx is not None else 0
        rhs_stride = rhs_strides[rhs_idx] if rhs_idx is not None else 0
        if reduced:
            lr_dims.append(d)
        elif (lhs_stride == 0) == (rhs_stride == 0):
            lro_dims.append(d)
        elif lhs_stride != 0:
            lo_dims.append(d)
        else:
            ro_dims.append(d)
    rhs_seen = [False] * len(rhs_info.levels)
    for (i, lhs_level) in enumerate(lhs_info.levels):
        rhs_idx = None
        for (j, rhs_level) in enumerate(rhs_info.levels):
            if lhs_level == rhs_level:
                rhs_idx = j
                rhs_seen[j] = True
                break
        insert_dim(lhs_level, i, rhs_idx)
    for (i, rhs_level) in enumerate(rhs_info.levels):
        if not rhs_seen[i]:
            insert_dim(rhs_level, None, i)
    if <MASK>:
        for d in sum_dims:
            if d not in lhs_info.levels and d not in rhs_info.levels:
                raise ValueError(f'summing over non-existent dimension {d}')
    if len(lro_dims.dims) != 0:
        lhs_tensor = dot_prepare([lro_dims, lo_dims, lr_dims], lhs_info)
        rhs_tensor = dot_prepare([lro_dims, lr_dims, ro_dims], rhs_info)
        result = torch.bmm(lhs_tensor, rhs_tensor)
        return dot_finish([lro_dims, lo_dims, ro_dims], result)
    else:
        lhs_tensor = dot_prepare([lo_dims, lr_dims], lhs_info)
        rhs_tensor = dot_prepare([lr_dims, ro_dims], rhs_info)
        result = torch.mm(lhs_tensor, rhs_tensor)
        return dot_finish([lo_dims, ro_dims], result)

@dispatch.dispatch_for_api(math_ops.reduce_mean)
def reduce_mean(input_tensor: ragged_tensor.Ragged, axis=None, keepdims=None, name=None):
    """For docs, see: _RAGGED_REDUCE_DOCSTRING."""
    with ops.name_scope(name, 'RaggedReduceMean', [input_tensor, axis]):
        total = reduce_sum(input_tensor, axis, keepdims)
        if ragged_tensor.is_ragged(input_tensor):
            ones = ragged_tensor.RaggedTensor.from_nested_row_splits(array_ops.ones_like(input_tensor.flat_values), input_tensor.nested_row_splits, validate=False)
        else:
            ones = array_ops.ones_like(input_tensor)
        count = reduce_sum(ones, axis, keepdims)
        if <MASK>:
            return ragged_tensor.RaggedTensor.from_nested_row_splits(total.flat_values / count.flat_values, total.nested_row_splits, validate=False)
        else:
            return total / count

def remove_dead_code(instructions: list['Instruction']) -> list['Instruction']:
    """Dead code elimination"""
    indexof = get_indexof(instructions)
    live_code = set()

    def find_live_code(start: int) -> None:
        for i in range(start, len(instructions)):
            if i in live_code:
                return
            live_code.add(i)
            inst = instructions[i]
            if inst.exn_tab_entry:
                find_live_code(indexof[inst.exn_tab_entry.target])
            if <MASK>:
                assert inst.target is not None
                find_live_code(indexof[inst.target])
            if inst.opcode in TERMINAL_OPCODES:
                return
    find_live_code(0)
    if sys.version_info >= (3, 11):
        live_idx = sorted(live_code)
        for (i, inst) in enumerate(instructions):
            if i in live_code and inst.exn_tab_entry:
                start_idx = bisect.bisect_left(live_idx, indexof[inst.exn_tab_entry.start])
                assert start_idx < len(live_idx)
                end_idx = bisect.bisect_right(live_idx, indexof[inst.exn_tab_entry.end]) - 1
                assert end_idx >= 0
                assert live_idx[start_idx] <= i <= live_idx[end_idx]
                inst.exn_tab_entry.start = instructions[live_idx[start_idx]]
                inst.exn_tab_entry.end = instructions[live_idx[end_idx]]
    return [inst for (i, inst) in enumerate(instructions) if i in live_code]

def cumprod(a: ArrayLike, axis: AxisLike=None, dtype: Optional[DTypeLike]=None, out: Optional[OutArray]=None):
    if <MASK>:
        dtype = _dtypes_impl.default_dtypes().int_dtype
    if dtype is None:
        dtype = a.dtype
    ((a,), axis) = _util.axis_none_flatten(a, axis=axis)
    axis = _util.normalize_axis_index(axis, a.ndim)
    return a.cumprod(axis=axis, dtype=dtype)

