def get_comm_latency_between(parent_partition: Partition, child_partition: Partition, transfer_rate_bytes_per_sec: float):
    """Given two partitions (parent and child),
    calculate the communication latency between the two.
    """
    if parent_partition.logical_device_ids != [] and child_partition.logical_device_ids != [] and (parent_partition.logical_device_ids == child_partition.logical_device_ids):
        return 0.0
    comm_size = 0
    visited_nodes = set()
    for node in child_partition.nodes:
        input_nodes: dict[Node, None] = {}
        map_arg(node.args, input_nodes.setdefault)
        map_arg(node.kwargs, input_nodes.setdefault)
        for n in input_nodes:
            if <MASK>:
                size_bytes = getattr(n, 'size_bytes', None)
                if size_bytes is not None:
                    comm_size += size_bytes.output_size
                visited_nodes.add(n)
    return comm_size / transfer_rate_bytes_per_sec

def pad_addmm(input: Tensor | None, mat1: Tensor, mat2: Tensor, m_padded_length: int, k_padded_length: int, n_padded_length: int, beta: float=1.0, alpha: float=1.0, mat1_pre_padded: bool=False, mat2_pre_padded: bool=False) -> Tensor:
    if not mat1_pre_padded:
        mat1 = pad_mat1(mat1, m_padded_length=m_padded_length, k_padded_length=k_padded_length)
    if not mat2_pre_padded:
        mat2 = pad_mat2(mat2, k_padded_length=k_padded_length, n_padded_length=n_padded_length)
    if input is not None:
        if <MASK>:
            if input.dim() == 2 and input.shape[1] != 1:
                input = pad_dim(input, n_padded_length, 1)
            elif input.dim() == 1 and input.shape[0] != 1:
                input = pad_dim(input, n_padded_length, 0)
        if m_padded_length != 0 and input.dim() == 2 and (input.shape[0] != 1):
            input = pad_dim(input, m_padded_length, 0)
    res = aten.addmm(input, mat1, mat2, beta=beta, alpha=alpha)
    if m_padded_length != 0:
        res = res[:-m_padded_length, :]
    if n_padded_length != 0:
        res = res[:, :-n_padded_length]
    return res

def _CheckAtLeast3DImage(image, require_static=True):
    """Assert that we are working with a properly shaped image.

  Args:
    image: >= 3-D Tensor of size [*, height, width, depth]
    require_static: If `True`, requires that all dimensions of `image` are known
      and non-zero.

  Raises:
    ValueError: if image.shape is not a [>= 3] vector.

  Returns:
    An empty list, if `image` has fully defined dimensions. Otherwise, a list
    containing an assert op is returned.
  """
    try:
        if image.get_shape().ndims is None:
            image_shape = image.get_shape().with_rank(3)
        else:
            image_shape = image.get_shape().with_rank_at_least(3)
    except ValueError:
        raise ValueError("'image' (shape %s) must be at least three-dimensional." % image.shape)
    if require_static and (not image_shape.is_fully_defined()):
        raise ValueError("'image' must be fully defined.")
    if any((x == 0 for x in image_shape[-3:])):
        raise ValueError("inner 3 dims of 'image.shape' must be > 0: %s" % image_shape)
    if <MASK>:
        return [check_ops.assert_positive(array_ops.shape(image)[-3:], ["inner 3 dims of 'image.shape' must be > 0."]), check_ops.assert_greater_equal(array_ops.rank(image), 3, message="'image' must be at least three-dimensional.")]
    else:
        return []

