def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == '__setitem__' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (key, value) = args
        if not key.is_python_constant():
            super().call_method(tx, name, args, kwargs)
        tx.output.side_effects.mutation(self)
        if isinstance(key, SliceVariable):
            if <MASK>:
                msg = ConstantVariable.create('can only assign an iterable')
                raise_observed_exception(TypeError, tx, args=[msg])
            key = key.as_python_constant()
            if key.step == 0:
                msg = ConstantVariable.create('slice step cannot be zero')
                raise_observed_exception(ValueError, tx, args=[msg])
            value = value.force_unpack_var_sequence(tx)
            try:
                self.items[key] = value
            except Exception as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            if isinstance(key, SymNodeVariable):
                key = key.evaluate_expr()
            else:
                key = key.as_python_constant()
            try:
                self.items[key] = value
            except (IndexError, TypeError) as e:
                raise_observed_exception(type(e), tx, args=list(map(ConstantVariable.create, e.args)))
        return ConstantVariable.create(None)
    if name == 'sort' and self.is_mutable():
        if len(args) != 0:
            raise_args_mismatch(tx, name, '0 args', f'{len(args)} args')
        key_fn_var = kwargs.pop('key', ConstantVariable.create(None))
        reverse = kwargs.pop('reverse', ConstantVariable.create(False)).as_python_constant()
        if len(kwargs) != 0:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        if key_fn_var.is_python_constant() and key_fn_var.as_python_constant() is None:
            keys = self.items.copy()
        else:
            keys = [key_fn_var.call_function(tx, [x], {}) for x in self.items]
        if not all((k.is_python_constant() for k in keys)):
            first_non_constant_key = None
            for k in keys:
                if not k.is_python_constant():
                    first_non_constant_key = k
            assert first_non_constant_key is not None
            try:
                python_type = first_non_constant_key.python_type()
            except NotImplementedError:
                python_type = 'unknown'
            unimplemented_v2(gb_type='sort with non-constant keys', context=str(first_non_constant_key), explanation=f'Cannot perform sort with non-constant key. First non-constant key type: {python_type}. Most notably, we cannot sort with Tensor or SymInt keys, but we can sort ints.', hints=['Use something else as the key.'])
        tx.output.side_effects.mutation(self)
        sorted_items_with_keys = sorted(((x, k.as_python_constant(), -i if reverse else i) for (i, (k, x)) in enumerate(zip(keys, self.items))), key=operator.itemgetter(1, 2), reverse=reverse)
        self.items[:] = [x for (x, *_) in sorted_items_with_keys]
        return ConstantVariable.create(None)
    if name == '__init__' and self.is_mutable():
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        if len(args) == 0:
            return ConstantVariable.create(None)
        elif len(args) == 1 and args[0].has_force_unpack_var_sequence(tx):
            (arg,) = args
            tx.output.side_effects.mutation(self)
            self.items[:] = arg.force_unpack_var_sequence(tx)
            return ConstantVariable.create(None)
    return super().call_method(tx, name, args, kwargs)

def _unwrap_simple_call(self, node: ast.expr) -> ast.expr:
    """Unwraps a function call that takes a single unnamed parameter."""
    if <MASK>:
        return self._unwrap_simple_call(node.args[0])
    return node

def _cancel_all_tasks(loop: AbstractEventLoop, tasks: OrderedSet[Future]) -> None:
    to_cancel = [task for task in tasks if not task.done()]
    if not to_cancel:
        return
    for task in to_cancel:
        task.cancel()
    loop.run_until_complete(asyncio.gather(*to_cancel, return_exceptions=True))
    for task in to_cancel:
        if task.cancelled():
            continue
        if <MASK>:
            loop.call_exception_handler({'message': 'unhandled exception during asyncio.run() shutdown', 'exception': task.exception(), 'task': task})

def __init__(self, data=None, files=None, auto_id='id_%s', prefix=None, initial=None, error_class=ErrorList, label_suffix=None, empty_permitted=False, field_order=None, use_required_attribute=None, renderer=None, bound_field_class=None):
    self.is_bound = data is not None or files is not None
    self.data = MultiValueDict() if data is None else data
    self.files = MultiValueDict() if files is None else files
    self.auto_id = auto_id
    if prefix is not None:
        self.prefix = prefix
    self.initial = initial or {}
    self.error_class = error_class
    self.label_suffix = label_suffix if label_suffix is not None else _(':')
    self.empty_permitted = empty_permitted
    self._errors = None
    self.fields = copy.deepcopy(self.base_fields)
    self._bound_fields_cache = {}
    self.order_fields(self.field_order if field_order is None else field_order)
    if use_required_attribute is not None:
        self.use_required_attribute = use_required_attribute
    if self.empty_permitted and self.use_required_attribute:
        raise ValueError('The empty_permitted and use_required_attribute arguments may not both be True.')
    if renderer is None:
        if <MASK>:
            renderer = get_default_renderer()
        else:
            renderer = self.default_renderer
            if isinstance(self.default_renderer, type):
                renderer = renderer()
    self.renderer = renderer
    self.bound_field_class = bound_field_class or self.bound_field_class or getattr(self.renderer, 'bound_field_class', None)

def get_next_element_by_instance(self, instance_id: int):
    if self._datapipe_iterator is None and self._child_stop[instance_id]:
        self._datapipe_iterator = iter(self.main_datapipe)
        self._snapshot_state = _SnapshotState.Iterating
        for i in range(self.num_instances):
            self._child_stop[i] = False
    try:
        while not self._child_stop[instance_id]:
            self.child_pointers[instance_id] += 1
            if self.end_ptr is not None and self.child_pointers[instance_id] == self.end_ptr:
                self._child_stop[instance_id] = True
                break
            if self.buffer and self.child_pointers[instance_id] <= self.leading_ptr:
                idx = self.child_pointers[instance_id] - self.slowest_ptr - 1
                return_val = self.buffer[idx]
            else:
                self.leading_ptr = self.child_pointers[instance_id]
                try:
                    return_val = next(self._datapipe_iterator)
                    self.buffer.append(return_val)
                except StopIteration:
                    self._child_stop[instance_id] = True
                    self._datapipe_iterator = None
                    self.end_ptr = self.leading_ptr
                    continue
            if self.child_pointers[instance_id] == self.slowest_ptr + 1:
                new_min = min(self.child_pointers)
                if <MASK>:
                    self.slowest_ptr = new_min
                    self.buffer.popleft()
            if self.buffer_size >= 0 and self.leading_ptr > self.buffer_size + self.slowest_ptr:
                raise BufferError('ForkerIterDataPipe buffer overflow,' + f'buffer size {self.buffer_size} is insufficient.')
            yield self.copy_fn(return_val)
    finally:
        self._child_stop[instance_id] = True
        if all(self._child_stop):
            self._datapipe_iterator = None
            self._cleanup()

def _element_size(dtype):
    """
    Returns the element size for a dtype, in bytes
    """
    if <MASK>:
        raise RuntimeError(f'expected torch.dtype, but got {type(dtype)}')
    if dtype.is_complex:
        return torch.finfo(dtype).bits >> 2
    elif dtype.is_floating_point:
        return torch.finfo(dtype).bits >> 3
    elif dtype == torch.bool:
        return 1
    else:
        return torch.iinfo(dtype).bits >> 3

def _fit_stages(self, X, y, raw_predictions, sample_weight, random_state, X_val, y_val, sample_weight_val, begin_at_stage=0, monitor=None):
    """Iteratively fits the stages.

        For each stage it computes the progress (OOB, train score)
        and delegates to ``_fit_stage``.
        Returns the number of stages fit; might differ from ``n_estimators``
        due to early stopping.
        """
    n_samples = X.shape[0]
    do_oob = self.subsample < 1.0
    sample_mask = np.ones((n_samples,), dtype=bool)
    n_inbag = max(1, int(self.subsample * n_samples))
    if self.verbose:
        verbose_reporter = VerboseReporter(verbose=self.verbose)
        verbose_reporter.init(self, begin_at_stage)
    X_csc = csc_matrix(X) if issparse(X) else None
    X_csr = csr_matrix(X) if issparse(X) else None
    if self.n_iter_no_change is not None:
        loss_history = np.full(self.n_iter_no_change, np.inf)
        y_val_pred_iter = self._staged_raw_predict(X_val, check_input=False)
    if isinstance(self._loss, (HalfSquaredError, HalfBinomialLoss)):
        factor = 2
    else:
        factor = 1
    i = begin_at_stage
    for i in range(begin_at_stage, self.n_estimators):
        if do_oob:
            sample_mask = _random_sample_mask(n_samples, n_inbag, random_state)
            y_oob_masked = y[~sample_mask]
            sample_weight_oob_masked = sample_weight[~sample_mask]
            if i == 0:
                initial_loss = factor * self._loss(y_true=y_oob_masked, raw_prediction=raw_predictions[~sample_mask], sample_weight=sample_weight_oob_masked)
        raw_predictions = self._fit_stage(i, X, y, raw_predictions, sample_weight, sample_mask, random_state, X_csc=X_csc, X_csr=X_csr)
        if do_oob:
            self.train_score_[i] = factor * self._loss(y_true=y[sample_mask], raw_prediction=raw_predictions[sample_mask], sample_weight=sample_weight[sample_mask])
            self.oob_scores_[i] = factor * self._loss(y_true=y_oob_masked, raw_prediction=raw_predictions[~sample_mask], sample_weight=sample_weight_oob_masked)
            previous_loss = initial_loss if i == 0 else self.oob_scores_[i - 1]
            self.oob_improvement_[i] = previous_loss - self.oob_scores_[i]
            self.oob_score_ = self.oob_scores_[-1]
        else:
            self.train_score_[i] = factor * self._loss(y_true=y, raw_prediction=raw_predictions, sample_weight=sample_weight)
        if self.verbose > 0:
            verbose_reporter.update(i, self)
        if <MASK>:
            early_stopping = monitor(i, self, locals())
            if early_stopping:
                break
        if self.n_iter_no_change is not None:
            validation_loss = factor * self._loss(y_val, next(y_val_pred_iter), sample_weight_val)
            if np.any(validation_loss + self.tol < loss_history):
                loss_history[i % len(loss_history)] = validation_loss
            else:
                break
    return i + 1

@input_spec.setter
@trackable.no_automatic_dependency_tracking
def input_spec(self, value):
    for v in nest.flatten(value):
        if <MASK>:
            raise TypeError('Layer input_spec must be an instance of InputSpec. Got: {}'.format(v))
    self._input_spec = value

def __init__(self, df: Union[Tensor, Number], covariance_matrix: Optional[Tensor]=None, precision_matrix: Optional[Tensor]=None, scale_tril: Optional[Tensor]=None, validate_args: Optional[bool]=None) -> None:
    assert (covariance_matrix is not None) + (scale_tril is not None) + (precision_matrix is not None) == 1, 'Exactly one of covariance_matrix or precision_matrix or scale_tril may be specified.'
    param = next((p for p in (covariance_matrix, precision_matrix, scale_tril) if p is not None))
    if param.dim() < 2:
        raise ValueError('scale_tril must be at least two-dimensional, with optional leading batch dimensions')
    if isinstance(df, _Number):
        batch_shape = torch.Size(param.shape[:-2])
        self.df = torch.tensor(df, dtype=param.dtype, device=param.device)
    else:
        batch_shape = torch.broadcast_shapes(param.shape[:-2], df.shape)
        self.df = df.expand(batch_shape)
    event_shape = param.shape[-2:]
    if self.df.le(event_shape[-1] - 1).any():
        raise ValueError(f'Value of df={df} expected to be greater than ndim - 1 = {event_shape[-1] - 1}.')
    if scale_tril is not None:
        self.scale_tril = param.expand(batch_shape + (-1, -1))
    elif covariance_matrix is not None:
        self.covariance_matrix = param.expand(batch_shape + (-1, -1))
    elif <MASK>:
        self.precision_matrix = param.expand(batch_shape + (-1, -1))
    if self.df.lt(event_shape[-1]).any():
        warnings.warn('Low df values detected. Singular samples are highly likely to occur for ndim - 1 < df < ndim.')
    super().__init__(batch_shape, event_shape, validate_args=validate_args)
    self._batch_dims = [-(x + 1) for x in range(len(self._batch_shape))]
    if scale_tril is not None:
        self._unbroadcasted_scale_tril = scale_tril
    elif covariance_matrix is not None:
        self._unbroadcasted_scale_tril = torch.linalg.cholesky(covariance_matrix)
    else:
        self._unbroadcasted_scale_tril = _precision_to_scale_tril(precision_matrix)
    self._dist_chi2 = torch.distributions.chi2.Chi2(df=self.df.unsqueeze(-1) - torch.arange(self._event_shape[-1], dtype=self._unbroadcasted_scale_tril.dtype, device=self._unbroadcasted_scale_tril.device).expand(batch_shape + (-1,)))

def __new__(mcs, name, bases, attrs):
    attrs['declared_fields'] = {key: attrs.pop(key) for (key, value) in list(attrs.items()) if isinstance(value, Field)}
    new_class = super().__new__(mcs, name, bases, attrs)
    declared_fields = {}
    for base in reversed(new_class.__mro__):
        if <MASK>:
            declared_fields.update(base.declared_fields)
        for (attr, value) in base.__dict__.items():
            if value is None and attr in declared_fields:
                declared_fields.pop(attr)
    new_class.base_fields = declared_fields
    new_class.declared_fields = declared_fields
    return new_class

def resolve_lookup_value(self, value, can_reuse, allow_joins, summarize=False):
    if hasattr(value, 'resolve_expression'):
        value = value.resolve_expression(self, reuse=can_reuse, allow_joins=allow_joins, summarize=summarize)
    elif <MASK>:
        values = (self.resolve_lookup_value(sub_value, can_reuse, allow_joins, summarize) for sub_value in value)
        type_ = type(value)
        if hasattr(type_, '_make'):
            return type_(*values)
        return type_(values)
    return value

def intervals_overlap(self, intervals: list[Interval]):
    overlap_time = 0
    intervals = sorted(intervals, key=lambda x: x.start)
    if intervals:
        overlap_start = max(self.event.start_time_ns, intervals[0].start)
        overlap_end = min(self.event.end_time_ns, intervals[0].end)
        if overlap_start < overlap_end:
            overlap_time += overlap_end - overlap_start
    (i, j) = (0, 1)
    while j < len(intervals):
        prev_interval = intervals[i]
        curr_interval = intervals[j]
        j += 1
        if <MASK>:
            if prev_interval.end > curr_interval.end:
                j += 1
                continue
            else:
                curr_interval.start = prev_interval.end
                i = j
        overlap_start = max(self.event.start_time_ns, curr_interval.start)
        overlap_end = min(self.event.end_time_ns, curr_interval.end)
        if overlap_start < overlap_end:
            overlap_time += overlap_end - overlap_start
    return overlap_time

def _euclidean_distances(X, Y, X_norm_squared=None, Y_norm_squared=None, squared=False):
    """Computational part of euclidean_distances

    Assumes inputs are already checked.

    If norms are passed as float32, they are unused. If arrays are passed as
    float32, norms needs to be recomputed on upcast chunks.
    TODO: use a float64 accumulator in row_norms to avoid the latter.
    """
    (xp, _, device_) = get_namespace_and_device(X, Y)
    if X_norm_squared is not None and X_norm_squared.dtype != xp.float32:
        XX = xp.reshape(X_norm_squared, (-1, 1))
    elif X.dtype != xp.float32:
        XX = row_norms(X, squared=True)[:, None]
    else:
        XX = None
    if Y is X:
        YY = None if XX is None else XX.T
    elif Y_norm_squared is not None and Y_norm_squared.dtype != xp.float32:
        YY = xp.reshape(Y_norm_squared, (1, -1))
    elif Y.dtype != xp.float32:
        YY = row_norms(Y, squared=True)[None, :]
    else:
        YY = None
    if X.dtype == xp.float32 or Y.dtype == xp.float32:
        distances = _euclidean_distances_upcast(X, XX, Y, YY)
    else:
        distances = -2 * safe_sparse_dot(X, Y.T, dense_output=True)
        distances += XX
        distances += YY
    xp_zero = xp.asarray(0, device=device_, dtype=distances.dtype)
    distances = _modify_in_place_if_numpy(xp, xp.maximum, distances, xp_zero, out=distances)
    if <MASK>:
        _fill_diagonal(distances, 0, xp=xp)
    if squared:
        return distances
    distances = _modify_in_place_if_numpy(xp, xp.sqrt, distances, out=distances)
    return distances

def _adjust_attributes_of_max_pool(expand_size: int, kernel_size: Sequence[int] | int, stride: Sequence[int] | int, padding: Sequence[int] | int, dilation: Sequence[int] | int) -> tuple[Sequence[int], Sequence[int], Sequence[int], Sequence[int]]:
    """Adjust attributes of avg_pool to match ONNX specification."""
    if isinstance(dilation, int):
        dilation = [dilation] * expand_size
    if isinstance(kernel_size, int):
        kernel_shape = [kernel_size] * expand_size
    else:
        kernel_shape = kernel_size
    if isinstance(padding, int):
        pads = [padding] * expand_size * 2
    elif <MASK>:
        pads = padding * expand_size * 2
    elif len(padding) == 2:
        pads = padding * 2
    elif len(padding) == 3:
        pads = padding * 2
    else:
        pads = padding
    if isinstance(stride, int):
        strides = [stride] * expand_size
    elif not stride:
        strides = kernel_shape
    else:
        strides = stride
    return (kernel_shape, strides, pads, dilation)

def deduplicate_readonly_buffers(tflite_model):
    """Generates a new model byte array after deduplicating readonly buffers.

  This function should be invoked after the model optimization toolkit. The
  model optimization toolkit assumes that each tensor object owns its each
  buffer separately.

  Args:
    tflite_model: TFLite flatbuffer in a byte array to be deduplicated.

  Returns:
    TFLite flatbuffer in a bytes array, processed with the deduplication method.
  """
    model = flatbuffer_utils.convert_bytearray_to_object(tflite_model)
    read_only_buffer_indices = set()
    for subgraph in model.subgraphs:
        read_only_input_tensor_indices = set()
        for op in subgraph.operators:
            if op.inputs is None:
                continue
            for (i, input_tensor_idx) in enumerate(op.inputs):
                if op.mutatingVariableInputs is not None:
                    if i < len(op.mutatingVariableInputs) and op.mutatingVariableInputs[i]:
                        continue
                if subgraph.tensors[input_tensor_idx].isVariable:
                    continue
                read_only_input_tensor_indices.add(input_tensor_idx)
        for op in subgraph.operators:
            if op.outputs is not None:
                for output_tensor_idx in op.outputs:
                    read_only_input_tensor_indices.discard(output_tensor_idx)
            if op.intermediates is not None:
                for intermediate_tensor_idx in op.intermediates:
                    read_only_input_tensor_indices.discard(intermediate_tensor_idx)
        if subgraph.inputs is not None:
            for input_tensor_idx in subgraph.inputs:
                read_only_input_tensor_indices.discard(input_tensor_idx)
        if subgraph.outputs is not None:
            for output_tensor_idx in subgraph.outputs:
                read_only_input_tensor_indices.discard(output_tensor_idx)
        for tensor_idx in read_only_input_tensor_indices:
            read_only_buffer_indices.add(subgraph.tensors[tensor_idx].buffer)
    for buffer_idx in read_only_buffer_indices.copy():
        if buffer_idx < 0 or (model.buffers[buffer_idx].data is None or isinstance(model.buffers[buffer_idx].data, list) or model.buffers[buffer_idx].data.size == 0):
            read_only_buffer_indices.discard(buffer_idx)

    class BufferIndex:
        """A class to store index, size, hash of the buffers in TFLite model."""

        def __init__(self, idx, size, hash_value):
            self.idx = idx
            self.size = size
            self.hash_value = hash_value
    read_only_buffers = list(map(lambda index: BufferIndex(index, model.buffers[index].data.size, hashlib.md5(model.buffers[index].data.data.tobytes()).hexdigest()), read_only_buffer_indices))
    read_only_buffers = sorted(read_only_buffers, key=lambda buffer: (buffer.size, buffer.hash_value), reverse=True)
    duplicate_buffer_map = {}
    for (i, buffer_i) in enumerate(read_only_buffers):
        if <MASK>:
            continue
        for buffer_j in read_only_buffers[i + 1:]:
            if buffer_j.idx in duplicate_buffer_map:
                continue
            if buffer_i.size != buffer_j.size:
                break
            if buffer_i.hash_value != buffer_j.hash_value:
                continue
            duplicate_buffer_map[buffer_j.idx] = buffer_i.idx
    for subgraph in model.subgraphs:
        for op in subgraph.operators:
            if op.inputs is None:
                continue
            for input_tensor in op.inputs:
                buffer_idx = subgraph.tensors[input_tensor].buffer
                if buffer_idx in duplicate_buffer_map:
                    subgraph.tensors[input_tensor].buffer = duplicate_buffer_map[buffer_idx]
    for idx in duplicate_buffer_map:
        model.buffers[idx].data = None
    return flatbuffer_utils.convert_object_to_bytearray(model)

def write_wrapper_decl(self):
    inputs_len = len(V.graph.graph_inputs.keys())
    if V.graph.aot_mode:
        if config.aot_inductor.use_minimal_arrayref_interface and (not V.graph.is_const_graph):
            input_cpp_types = ', '.join((f'{CppWrapperCpuArrayRef.get_input_cpp_type(x)}' for x in V.graph.graph_inputs.values()))
            output_arrayref_types = ', '.join((f'ArrayRefTensor<{DTYPE_TO_CPP[x.get_dtype()]}>' for x in V.graph.graph_outputs))
            self.prefix.splice(f'
                    using AOTInductorModelInputs = std::tuple<{input_cpp_types}>;
                    using AOTInductorModelOutputs = std::tuple<{output_arrayref_types}>;
                    ')
        if V.graph.const_module:
            self.header.splice(V.graph.const_module.wrapper_code.header)
            assert V.graph.const_wrapper_code is not None
            self.prefix.splice(V.graph.const_wrapper_code)
            assert V.graph.const_kernel_code is not None
            self.kernel_declarations.splice(V.graph.const_kernel_code)
        if V.graph.is_const_graph:
            self.prefix.splice('
                    void AOTInductorModel::_const_run_impl(
                        std::vector<AtenTensorHandle>& output_handles,
                        DeviceStreamType stream,
                        AOTIProxyExecutorHandle proxy_executor
                    ) {
                    ')
        else:
            if not config.aot_inductor.use_runtime_constant_folding:
                self.prefix.splice('
                        void AOTInductorModel::_const_run_impl(
                            std::vector<AtenTensorHandle>& output_handles,
                            DeviceStreamType stream,
                            AOTIProxyExecutorHandle proxy_executor
                        ) {}

                        ')
            run_impl_proto = '
                    void AOTInductorModel::run_impl(
                        AtenTensorHandle*
                            input_handles, // array of input AtenTensorHandle; handles
                                            // are stolen; the array itself is borrowed
                        AtenTensorHandle*
                            output_handles, // array for writing output AtenTensorHandle; handles
                                            // will be stolen by the caller; the array itself is
                                            // borrowed
                        DeviceStreamType stream,
                        AOTIProxyExecutorHandle proxy_executor
                    ) {
                    '
            self.generate_input_output_runtime_checks()
            run_impl_proto += '
                    __check_inputs_outputs(input_handles, output_handles);
                '
            if config.aot_inductor.use_minimal_arrayref_interface:
                self.prefix.splice('
                        template <>
                        AOTInductorModelOutputs AOTInductorModel::run_impl_minimal_arrayref_interface<
                          AOTInductorModelInputs, AOTInductorModelOutputs>(
                            const AOTInductorModelInputs& inputs,
                            DeviceStreamType stream,
                            AOTIProxyExecutorHandle proxy_executor
                        ) {
                        ')
                self.suffix.splice(run_impl_proto)
                self.suffix.splice('
                            AOTInductorModelInputs inputs;
                            convert_handles_to_inputs(input_handles, inputs);
                            auto outputs = run_impl_minimal_arrayref_interface<AOTInductorModelInputs, AOTInductorModelOutputs>(
                                inputs, stream, proxy_executor);
                            // NOTE: outputs is full of ArrayRef to thread_local storage. If in the future we need this
                            // interface to perform well for a DSO using the minimal arrayref interface, all we need
                            // to do is provide ThreadLocalCachedTensor for each one!
                            convert_outputs_to_handles(outputs, output_handles);
                        }
                    ')
                self.suffix.splice('
                        extern "C" AOTIRuntimeError AOTInductorModelRunMinimalArrayrefInterface(
                            AOTInductorModelHandle model_handle,
                            const AOTInductorModelInputs& inputs,
                            AOTInductorModelOutputs& outputs) {
                          auto model = reinterpret_cast<torch::aot_inductor::AOTInductorModel*>(model_handle);
                          CONVERT_EXCEPTION_TO_ERROR_CODE({
                              outputs = model->run_impl_minimal_arrayref_interface<AOTInductorModelInputs, AOTInductorModelOutputs>(
                                  inputs,
                                  (torch::aot_inductor::DeviceStreamType)nullptr,
                                  nullptr);
                          })
                        }
                    ')
            else:
                self.prefix.splice(run_impl_proto)
    else:
        self.prefix.splice('
                void inductor_entry_impl(
                    AtenTensorHandle*
                        input_handles, // array of input AtenTensorHandle; handles
                                        // are stolen; the array itself is borrowed
                    AtenTensorHandle*
                        output_handles  // array for writing output AtenTensorHandle; handles
                                        // will be stolen by the caller; the array itself is
                                        // borrowed)
                ) {
                ')
    with self.prefix.indent():
        if not config.aot_inductor.use_minimal_arrayref_interface:
            if not V.graph.is_const_graph:
                if V.graph.aot_mode:
                    num_args = len(V.graph.graph_inputs)
                else:
                    num_args = len(V.graph.graph_inputs) + len(V.graph.constants)
                    self.prefix.splice('py::gil_scoped_release_simple release;')
                self.prefix.splice(f'
                            auto inputs = steal_from_raw_handles_to_raii_handles(input_handles, {num_args});
                        ')
        if inputs_len != 0:
            for (idx, input_key) in enumerate(V.graph.graph_inputs.keys()):
                if config.aot_inductor.use_minimal_arrayref_interface:
                    self.prefix.writeline(f'auto {input_key} = std::get<{idx}>(inputs);')
                    continue
                if <MASK>:
                    from ..graph import may_get_constant_buffer_dtype
                    dtype = may_get_constant_buffer_dtype(V.graph.graph_inputs[input_key])
                    assert dtype is not None, 'Fails to get the dtype of the sympy.Expr'
                    self.codegen_tensor_item(dtype, f'inputs[{idx}]', input_key, self.prefix)
                else:
                    self.prefix.writeline(f'auto {input_key} = std::move(inputs[{idx}]);')
        assert all((isinstance(v, torch.Tensor) for v in list(V.graph.constants.values()))), 'Expect all constants to be Tensor'
        for (idx, constants_key) in enumerate(V.graph.constants.keys()):
            if V.graph.aot_mode:
                self.prefix.writeline(f'auto {constants_key} = constants_->at({idx});')
            else:
                constants_idx = inputs_len + idx
                self.prefix.writeline(f'auto {constants_key} = std::move(inputs[{constants_idx}]);')
        self.codegen_inputs()
        if V.graph.aot_mode:
            if not V.graph.is_const_graph:
                if config.aot_inductor.use_minimal_arrayref_interface:
                    self.codegen_input_numel_asserts()
                else:
                    self.prefix.writeline('inputs.clear();')
            self.prefix.writeline('[[maybe_unused]] auto& kernels = static_cast<AOTInductorModelKernels&>(*this->kernels_.get());')

@classmethod
def realize_into(cls, src: IRNode, dst: IRNode) -> IRNode:
    if not isinstance(dst, ReinterpretView):
        if is_storage_and_layout(dst):
            (storage, layout) = as_storage_and_layout(dst)
            dst = ReinterpretView(data=storage, layout=layout)
    assert isinstance(dst, ReinterpretView), type(dst)
    if <MASK>:
        return cls.realize_into(src.data, dst)
    if isinstance(src, StorageBox):
        src.realize()
        assert hasattr(src.data, 'layout')
        if cls.can_realize_into_without_copy(src, dst):
            src.data.layout = NonOwningLayout(dst)
            return src.data
    pw = Pointwise.create(device=src.get_device(), dtype=src.get_dtype(), inner_fn=src.make_loader(), ranges=[V.graph.sizevars.check_equals_and_simplify(a, b) for (a, b) in zip(src.get_size(), dst.get_size())])
    return cls.realize_into(pw, dst)

def _npSuffStats(self, x, axes, shift, keep_dims):
    axis = tuple(axes)
    if shift is not None:
        m_ss = np.sum(x - shift, axis=axis, keepdims=keep_dims)
        v_ss = np.sum((x - shift) * (x - shift), axis=axis, keepdims=keep_dims)
    else:
        m_ss = np.sum(x, axis=axis, keepdims=keep_dims)
        v_ss = np.sum(x * x, axis=axis, keepdims=keep_dims)
    count = 1.0
    for d in range(x.ndim):
        if d in set(axes):
            count *= x.shape[d]
    if <MASK>:
        shift = np.asarray(shift)
    return (count, m_ss, v_ss, shift)

def get_branches(repo: GitRepo) -> dict[str, Any]:
    git_response = repo._run_git('for-each-ref', '--sort=creatordate', '--format=%(refname) %(committerdate:iso-strict)', 'refs/remotes/origin')
    branches_by_base_name: dict[str, Any] = {}
    for line in git_response.splitlines():
        (branch, date) = line.split(' ')
        re_branch = re.match('refs/remotes/origin/(.*)', branch)
        assert re_branch
        branch = branch_base_name = re_branch.group(1)
        if <MASK>:
            branch_base_name = x.group(1)
        date = datetime.fromisoformat(date).timestamp()
        if branch_base_name not in branches_by_base_name:
            branches_by_base_name[branch_base_name] = [date, [branch]]
        else:
            branches_by_base_name[branch_base_name][1].append(branch)
            if date > branches_by_base_name[branch_base_name][0]:
                branches_by_base_name[branch_base_name][0] = date
    return branches_by_base_name

def use2fortran(use, tab=''):
    ret = ''
    for m in list(use.keys()):
        ret = f'{ret}{tab}use {m},'
        if use[m] == {}:
            if ret and ret[-1] == ',':
                ret = ret[:-1]
            continue
        if 'only' in use[m] and use[m]['only']:
            ret = f'{ret} only:'
        if 'map' in use[m] and use[m]['map']:
            c = ' '
            for k in list(use[m]['map'].keys()):
                if <MASK>:
                    ret = f'{ret}{c}{k}'
                    c = ','
                else:
                    ret = f"{ret}{c}{k}=>{use[m]['map'][k]}"
                    c = ','
        if ret and ret[-1] == ',':
            ret = ret[:-1]
    return ret

def _wrap_source(self, attr_source):
    if not isinstance(attr_source, (FSDPNNModuleSource, UnspecializedNNModuleSource)):
        if <MASK>:
            return FSDPNNModuleSource(attr_source)
        else:
            return UnspecializedNNModuleSource(attr_source)
    return attr_source

def idx2crd(idx: IntTuple, shape: IntTuple, stride: Optional[IntTuple]=None) -> IntTuple:
    if stride is None:
        stride = suffix_product(shape)
    if is_tuple(idx):
        if <MASK>:
            assert len(idx) == len(shape) and len(stride) == len(shape)
            return tuple((idx2crd(i, s, d) for (i, s, d) in zip(idx, shape, stride)))
        else:
            raise AssertionError('Invalid combination: tuple with int stride')
    elif is_tuple(shape) and is_tuple(stride):
        assert len(shape) == len(stride)
        return tuple((idx2crd(idx, s, d) for (s, d) in zip(shape, stride)))
    else:
        assert not is_tuple(shape) and (not is_tuple(stride))
        return idx // stride % shape

def run(self, *args, stream, benchmark_run=False, **kwargs):
    if hasattr(triton, 'set_allocator'):

        def alloc_fn(size: int, align: int, stream: int | None):
            return torch.empty(size, dtype=torch.int8, device=self.device_props.type)
        triton.set_allocator(alloc_fn)
    if self.triton_interpret:
        (args, grid) = self._interpret_args_grid(args, self.configs[0])
        return self.fn[grid](*args, **kwargs, **self.configs[0].kwargs)
    if len(self.launchers) != 1:
        if len(self.launchers) == 0:
            start_time = time.time_ns()
            self.precompile()
            self.precompile_time_taken_ns = time.time_ns() - start_time
        if len(self.launchers) > 1:
            self.autotune_to_one_config(*args, **kwargs)
    if not getattr(self.launchers[0].config, 'found_by_coordesc', False) and self.inductor_meta.get('coordinate_descent_tuning', False):
        self.launchers = [self.coordinate_descent_tuning(self.launchers[0], *args, **kwargs)]
    (launcher,) = self.launchers
    if launcher.store_cubin and (not benchmark_run or not self.cuda_kernel_saved):
        self.save_gpu_kernel(stream, launcher)
    args_without_constexprs = tuple(args)
    if self.dump_launch_params:
        (new_args, grid) = self._interpret_args_grid(args, launcher.config)
        _dump_launch_params(new_args, kwargs, launcher, self.fn.__name__, grid)
    if <MASK>:
        profiler_kwargs = self.get_profiler_kwargs(stream, launcher)
        with torch._C._profiler._RecordFunctionFast(self.inductor_meta.get('kernel_name', 'triton kernel'), args_without_constexprs, profiler_kwargs):
            return launcher(*args, **kwargs, stream=stream)
    else:
        return launcher(*args, **kwargs, stream=stream)

def is_required_checksum(urls: list[str | None]) -> bool:
    if not urls:
        return False
    for url in urls:
        if not url:
            continue
        parsed_url = urlparse(url)
        if <MASK>:
            return False
    return True

def MATCH_KEYS(self, inst: Instruction) -> None:
    tos = self.stack[-1]
    assert isinstance(tos, TupleVariable)
    keys = tos.unpack_var_sequence(self)
    tos1 = self.stack[-2]
    assert isinstance(tos1, ConstDictVariable)
    if <MASK>:
        self.push(TupleVariable([tos1.getitem_const(self, k) for k in keys]))
        if sys.version_info < (3, 11):
            self.push(ConstantVariable.create(True))
    else:
        self.push(ConstantVariable.create(None))
        if sys.version_info < (3, 11):
            self.push(ConstantVariable.create(False))

def request_stop(self, ex=None):
    """Request that the threads stop.

    After this is called, calls to `should_stop()` will return `True`.

    Note: If an exception is being passed in, in must be in the context of
    handling the exception (i.e. `try: ... except Exception as ex: ...`) and not
    a newly created one.

    Args:
      ex: Optional `Exception`, or Python `exc_info` tuple as returned by
        `sys.exc_info()`.  If this is the first call to `request_stop()` the
        corresponding exception is recorded and re-raised from `join()`.
    """
    with self._lock:
        ex = self._filter_exception(ex)
        if self._joined:
            if isinstance(ex, tuple):
                (_, ex_instance, _) = ex
                raise ex_instance
            elif ex is not None:
                (_, ex_instance, _) = sys.exc_info()
                raise ex_instance
        if <MASK>:
            if ex and self._exc_info_to_raise is None:
                if isinstance(ex, tuple):
                    logging.info('Error reported to Coordinator: %s', compat.as_str_any(ex[1]), exc_info=ex)
                    self._exc_info_to_raise = ex
                else:
                    logging.info('Error reported to Coordinator: %s, %s', type(ex), compat.as_str_any(ex))
                    self._exc_info_to_raise = sys.exc_info()
                if len(self._exc_info_to_raise) != 3 or not self._exc_info_to_raise[0] or (not self._exc_info_to_raise[1]):
                    try:
                        raise ValueError('ex must be a tuple or sys.exc_info must return the current exception: %s' % self._exc_info_to_raise)
                    except ValueError:
                        self._exc_info_to_raise = sys.exc_info()
            self._stop_event.set()

@_add_docstr('
Computes the Kaiser window.

The Kaiser window is defined as follows:

.. math::
    w_n = I_0 \left( \beta \sqrt{1 - \left( {\frac{n - N/2}{N/2}} \right) ^2 } \right) / I_0( \beta )

where ``I_0`` is the zeroth order modified Bessel function of the first kind (see :func:`torch.special.i0`), and
``N = M - 1 if sym else M``.
    ', '

{normalization}

Args:
    {M}

Keyword args:
    beta (float, optional): shape parameter for the window. Must be non-negative. Default: 12.0
    {sym}
    {dtype}
    {layout}
    {device}
    {requires_grad}

Examples::

    >>> # Generates a symmetric gaussian window with a standard deviation of 1.0.
    >>> torch.signal.windows.kaiser(5)
    tensor([4.0065e-05, 2.1875e-03, 4.3937e-02, 3.2465e-01, 8.8250e-01, 8.8250e-01, 3.2465e-01, 4.3937e-02, 2.1875e-03, 4.0065e-05])
    >>> # Generates a periodic gaussian window and standard deviation equal to 0.9.
    >>> torch.signal.windows.kaiser(5, sym=False,std=0.9)
    tensor([1.9858e-07, 5.1365e-05, 3.8659e-03, 8.4658e-02, 5.3941e-01, 1.0000e+00, 5.3941e-01, 8.4658e-02, 3.8659e-03, 5.1365e-05])
'.format(**window_common_args))
def kaiser(M: int, *, beta: float=12.0, sym: bool=True, dtype: Optional[torch.dtype]=None, layout: torch.layout=torch.strided, device: Optional[torch.device]=None, requires_grad: bool=False) -> Tensor:
    if dtype is None:
        dtype = torch.get_default_dtype()
    _window_function_checks('kaiser', M, dtype, layout)
    if beta < 0:
        raise ValueError(f'beta must be non-negative, got: {beta} instead.')
    if <MASK>:
        return torch.empty((0,), dtype=dtype, layout=layout, device=device, requires_grad=requires_grad)
    if M == 1:
        return torch.ones((1,), dtype=dtype, layout=layout, device=device, requires_grad=requires_grad)
    beta = torch.tensor(beta, dtype=dtype, device=device)
    start = -beta
    constant = 2.0 * beta / (M if not sym else M - 1)
    end = torch.minimum(beta, start + (M - 1) * constant)
    k = torch.linspace(start=start, end=end, steps=M, dtype=dtype, layout=layout, device=device, requires_grad=requires_grad)
    return torch.i0(torch.sqrt(beta * beta - torch.pow(k, 2))) / torch.i0(beta)

@classmethod
def create(cls, x: IRNode, dims: Sequence[int]) -> BaseView:
    dims = cls._map_neg_dims(dims)
    assert OrderedSet(dims) == OrderedSet(range(len(dims)))
    if <MASK>:
        (storage, old_layout) = as_storage_and_layout(x)
        new_layout = FixedLayout(old_layout.device, old_layout.dtype, [old_layout.size[i] for i in dims], [old_layout.stride[i] for i in dims], old_layout.offset, old_layout.is_pinned)
        return ReinterpretView(data=storage, layout=new_layout)
    return PermuteView(data=x, dims=dims)

@staticmethod
def call_custom_dict_fromkeys(tx: 'InstructionTranslator', user_cls, *args, **kwargs):
    if user_cls not in {dict, OrderedDict, defaultdict}:
        unimplemented_v2(gb_type='Unsupported dict type for fromkeys()', context=f'{user_cls.__name__}.fromkeys(): {args} {kwargs}', explanation=f'Failed to call {user_cls.__name__}.fromkeys() because {user_cls.__name__} is not any type of dict, OrderedDict, or defaultdict', hints=[f'Ensure {user_cls.__name__} is a type of dict, OrderedDict, or defaultdict.'])
    if kwargs:
        if user_cls is not OrderedDict or len(args) != 1 or len(kwargs) != 1 or ('value' not in kwargs):
            raise_args_mismatch(tx, f'{user_cls.__name__}.fromkeys', '1 args and 1 kwargs (`value`)', f'{len(args)} args and {len(kwargs)} kwargs')
        args = (*args, kwargs.pop('value'))
    if len(args) == 0:
        raise_args_mismatch(tx, f'{user_cls.__name__}.fromkeys', 'at least 1 args', f'{len(args)} args')
    if len(args) == 1:
        args = (*args, ConstantVariable.create(None))
    if len(args) != 2:
        raise_args_mismatch(tx, f'{user_cls.__name__}.fromkeys', '2 args', f'{len(args)} args')
    (arg, value) = args
    DictVariableType = ConstDictVariable if user_cls is not defaultdict else DefaultDictVariable
    if isinstance(arg, dict):
        arg = [ConstantVariable.create(k) for k in arg.keys()]
        return DictVariableType(dict.fromkeys(arg, value), user_cls, mutation_type=ValueMutationNew())
    elif <MASK>:
        keys = arg.force_unpack_var_sequence(tx)
        if all((is_hashable(v) for v in keys)):
            return DictVariableType(dict.fromkeys(keys, value), user_cls, mutation_type=ValueMutationNew())
    unimplemented_v2(gb_type='failed to call dict.fromkeys()', context=f'{user_cls.__name__}.fromkeys(): {args} {kwargs}', explanation=f'Failed to call {user_cls.__name__}.fromkeys() because arguments could not be automatically converted to a list, or some dict key is not hashable.', hints=['Manually convert the argument to a list.', 'Ensure all keys are hashable.'])

def build_inputs(parameters, sess, inputs, outputs):
    (input_shape, filter_shape) = get_tensor_shapes(parameters)
    if <MASK>:
        values = [create_tensor_data(np.float32, input_shape), create_tensor_data(np.float32, filter_shape)]
    elif parameters['fully_quantize']:
        values = [create_tensor_data(np.float32, input_shape, min_value=-1, max_value=1)]
    else:
        values = [create_tensor_data(np.float32, input_shape)]
    return (values, sess.run(outputs, feed_dict=dict(zip(inputs, values))))

def tripletmarginloss_reference(anchor, positive, negative, margin=1.0, p=2, eps=1e-06, swap=False, reduction='mean'):
    d_p = torch.pairwise_distance(anchor, positive, p, eps)
    d_n = torch.pairwise_distance(anchor, negative, p, eps)
    if swap:
        d_s = torch.pairwise_distance(positive, negative, p, eps)
        d_n = torch.min(d_n, d_s)
    output = torch.clamp(margin + d_p - d_n, min=0.0)
    if <MASK>:
        return output.mean()
    elif reduction == 'sum':
        return output.sum()
    return output

def _populate_quantization_options_default_values(quantization_options: _QuantizationOptions) -> None:
    """Populates default values for QuantizationOptions.

  Populates unspecified or unset fields of QuantizationOptions with the default
  values.

  * If `op_set` is unspecified, it defaults to `OpSet.XLA`.
  * If `freeze_all_variables` is not set, it defaults to `True`.
  * Check if configurations are set correctly:
    - Per-channel quantization is supported for Uniform Quantized opset only.

  Args:
    quantization_options: An instance of QuantizationOptions.
  """
    if quantization_options.op_set == quant_opts_pb2.OpSet.OP_SET_UNSPECIFIED:
        quantization_options.op_set = quant_opts_pb2.OpSet.XLA
    if not quantization_options.tags:
        quantization_options.tags.append(tag_constants.SERVING)
    if <MASK>:
        quantization_options.signature_keys.append(signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY)
    if not quantization_options.HasField('freeze_all_variables'):
        quantization_options.freeze_all_variables = True
    if quantization_options.enable_legacy_weight_only:
        raise ValueError('Legacy weight-only is deprecated. Use weight-only quantization method.')
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_UNSPECIFIED:
        logging.debug('"preset_method" for QuantizationMethod is not specified.Static range quantization is used by default.')
        quantization_options.quantization_method.preset_method = _PresetMethod.METHOD_STATIC_RANGE_INT8
    if quantization_options.min_num_elements_for_weights == 0:
        quantization_options.min_num_elements_for_weights = _DYNAMIC_RANGE_DEFAULT_MIN_NUM_ELEMENTS_FOR_WEIGHTS
        logging.warning('QuantizationOptions.min_num_elements_for_weights is not set (0). Setting to the default value: %d.', _DYNAMIC_RANGE_DEFAULT_MIN_NUM_ELEMENTS_FOR_WEIGHTS)
    if not quantization_options.HasField('enable_per_channel_quantization'):
        quantization_options.enable_per_channel_quantization = False
    if quantization_options.enable_per_channel_quantization and (not ((quantization_options.op_set == quant_opts_pb2.OpSet.UNIFORM_QUANTIZED or quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8) or (quantization_options.op_set in (quant_opts_pb2.OpSet.XLA, quant_opts_pb2.OpSet.STABLEHLO) and quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8))):
        raise ValueError('Currently, per-channel quantization is supported for Uniform Quantized opset, weight only quantization, or XLA/StableHLO opset with static range quantization.')
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8 and (quantization_options.op_set == quant_opts_pb2.OpSet.UNIFORM_QUANTIZED or quantization_options.op_set == quant_opts_pb2.OpSet.TF):
        raise ValueError('TF/Uniform quantized opset does not support weight-only.')
    if quantization_options.op_set == quant_opts_pb2.OpSet.STABLEHLO and (quantization_options.quantization_method.preset_method != _PresetMethod.METHOD_STATIC_RANGE_INT8 and quantization_options.quantization_method.preset_method != _PresetMethod.METHOD_STATIC_RANGE_WEIGHT_ONLY_INT8):
        raise ValueError('StableHLO quantized opset currently only supports static range quantization and weight-only quantizationvia TF Quantizer.')
    logging.debug('Setting `force_graph_mode_calibration = True` to ensure the calibration mode is executed properly.')
    quantization_options.force_graph_mode_calibration = True
    if quantization_options.HasField('debugger_config'):
        if not quantization_options.debugger_config.log_dir_path:
            quantization_options.debugger_config.log_dir_path = '/tmp/dumps'
        if quantization_options.debugger_config.debugger_type == stablehlo_quant_config_pb2.DebuggerConfig.DebuggerType.DEBUGGER_TYPE_UNSPECIFIED:
            raise ValueError('Debugger is enabled but debugger type was not specified.')
        if quantization_options.debugger_config.debugger_type == stablehlo_quant_config_pb2.DebuggerConfig.DebuggerType.DEBUGGER_TYPE_WHOLE_MODEL and (not quantization_options.debugger_config.unquantized_dump_model_path):
            raise ValueError('Debugger type whole model verify was used but unquantized_dump_model_path was not specified.')
    _populate_quantization_component_spec(quantization_options.quantization_method)
    _populate_unitwise_quantization_specs(quantization_options)
    if quantization_options.quantization_method.preset_method == _PresetMethod.METHOD_STATIC_RANGE_INT8:
        _populate_calibration_options(quantization_options)

def deconstruct(self):
    (name, path, args, kwargs) = super().deconstruct()
    if self.auto_now:
        kwargs['auto_now'] = True
    if self.auto_now_add:
        kwargs['auto_now_add'] = True
    if <MASK>:
        del kwargs['editable']
        del kwargs['blank']
    return (name, path, args, kwargs)

def __call__(self, op, output_dtype, *args):
    if not isinstance(op, torch._ops.OpOverload):
        raise ValueError("out_dtype's first argument must be an OpOverload")
    if op._schema.is_mutable:
        raise ValueError("out_dtype's first argument needs to be a functional operator")
    if not (len(op._schema.returns) == 1 and isinstance(op._schema.returns[0].type, torch.TensorType)):
        raise ValueError(f"out_dtype's can only apply to ops that return a single tensorInstead got {[r.type for r in op._schema.returns]}")
    if <MASK>:
        raise ValueError(f'out_dtype only allows the following operators: {ALLOWABLE_OPS}.')
    res = super().__call__(op, output_dtype, *args)
    return res

def __init__(self, dataset, coordinator):
    """Makes an iterable from datasets created by the given dataset.

    It creates a dataset_fn which deserializes a dataset from a graph under the
    hood.

    Args:
      dataset: A tf.data.Dataset, a DistributedDataset or a
        DistributedDatasetsFromFunction
      coordinator: a `ClusterCoordinator` object, used to create dataset
        resources.
    """
    if <MASK>:
        original_dataset = dataset._original_dataset
        serialized = serialize_dataset_to_graph(original_dataset)

        def dataset_fn():
            deserialized = deserialize_dataset_from_graph(serialized, original_dataset.element_spec)
            dataset.build(dataset_to_replace=deserialized)
            return dataset
    elif isinstance(dataset, input_lib.DistributedDatasetsFromFunction):

        def dataset_fn():
            dataset.build()
            return dataset
    elif isinstance(dataset, dataset_ops.Dataset):
        serialized = serialize_dataset_to_graph(dataset)

        def dataset_fn():
            return deserialize_dataset_from_graph(serialized, dataset.element_spec)
    else:
        raise ValueError('Unexpected dataset type!')
    super(PerWorkerDatasetFromDataset, self).__init__(dataset_fn, coordinator)

@final
def __delitem__(self, key) -> None:
    """
        Delete item
        """
    deleted = False
    maybe_shortcut = False
    if <MASK>:
        try:
            maybe_shortcut = key not in self.columns._engine
        except TypeError:
            pass
    if maybe_shortcut:
        if not isinstance(key, tuple):
            key = (key,)
        for col in self.columns:
            if isinstance(col, tuple) and col[:len(key)] == key:
                del self[col]
                deleted = True
    if not deleted:
        loc = self.axes[-1].get_loc(key)
        self._mgr = self._mgr.idelete(loc)

def __init__(self, obj: Grouper | None=None, freq: Frequency='Min', key: str | None=None, closed: Literal['left', 'right'] | None=None, label: Literal['left', 'right'] | None=None, how: str='mean', fill_method=None, limit: int | None=None, convention: Literal['start', 'end', 'e', 's'] | None=None, origin: Literal['epoch', 'start', 'start_day', 'end', 'end_day'] | TimestampConvertibleTypes='start_day', offset: TimedeltaConvertibleTypes | None=None, group_keys: bool=False, **kwargs) -> None:
    if label not in {None, 'left', 'right'}:
        raise ValueError(f'Unsupported value {label} for `label`')
    if closed not in {None, 'left', 'right'}:
        raise ValueError(f'Unsupported value {closed} for `closed`')
    if convention not in {None, 'start', 'end', 'e', 's'}:
        raise ValueError(f'Unsupported value {convention} for `convention`')
    if key is None and obj is not None and isinstance(obj.index, PeriodIndex) or (key is not None and obj is not None and (getattr(obj[key], 'dtype', None) == 'period')):
        freq = to_offset(freq, is_period=True)
    else:
        freq = to_offset(freq)
    if not isinstance(freq, Tick):
        if offset is not None:
            warnings.warn("The 'offset' keyword does not take effect when resampling with a 'freq' that is not Tick-like (h, m, s, ms, us, ns)", RuntimeWarning, stacklevel=find_stack_level())
        if origin != 'start_day':
            warnings.warn("The 'origin' keyword does not take effect when resampling with a 'freq' that is not Tick-like (h, m, s, ms, us, ns)", RuntimeWarning, stacklevel=find_stack_level())
    end_types = {'ME', 'YE', 'QE', 'BME', 'BYE', 'BQE', 'W'}
    rule = freq.rule_code
    if rule in end_types or ('-' in rule and rule[:rule.find('-')] in end_types):
        if closed is None:
            closed = 'right'
        if <MASK>:
            label = 'right'
    elif origin in ['end', 'end_day']:
        if closed is None:
            closed = 'right'
        if label is None:
            label = 'right'
    else:
        if closed is None:
            closed = 'left'
        if label is None:
            label = 'left'
    self.closed = closed
    self.label = label
    self.convention = convention if convention is not None else 'e'
    self.how = how
    self.fill_method = fill_method
    self.limit = limit
    self.group_keys = group_keys
    self._arrow_dtype: ArrowDtype | None = None
    if origin in ('epoch', 'start', 'start_day', 'end', 'end_day'):
        self.origin = origin
    else:
        try:
            self.origin = Timestamp(origin)
        except (ValueError, TypeError) as err:
            raise ValueError(f"'origin' should be equal to 'epoch', 'start', 'start_day', 'end', 'end_day' or should be a Timestamp convertible type. Got '{origin}' instead.") from err
    try:
        self.offset = Timedelta(offset) if offset is not None else None
    except (ValueError, TypeError) as err:
        raise ValueError(f"'offset' should be a Timedelta convertible type. Got '{offset}' instead.") from err
    kwargs['sort'] = True
    super().__init__(freq=freq, key=key, **kwargs)

def _order_by_pairs(self):
    if self.query.extra_order_by:
        ordering = self.query.extra_order_by
    elif not self.query.default_ordering:
        ordering = self.query.order_by
    elif self.query.order_by:
        ordering = self.query.order_by
    elif (meta := self.query.get_meta()) and meta.ordering:
        ordering = meta.ordering
        self._meta_ordering = ordering
    else:
        ordering = []
    if self.query.standard_ordering:
        (default_order, _) = ORDER_DIR['ASC']
    else:
        (default_order, _) = ORDER_DIR['DESC']
    selected_exprs = {}
    if ordering and (select := self.select):
        for (ordinal, (expr, _, alias)) in enumerate(select, start=1):
            pos_expr = PositionRef(ordinal, alias, expr)
            if alias:
                selected_exprs[alias] = pos_expr
            selected_exprs[expr] = pos_expr
    for field in ordering:
        if hasattr(field, 'resolve_expression'):
            if isinstance(field, Value):
                field = Cast(field, field.output_field)
            if not isinstance(field, OrderBy):
                field = field.asc()
            if not self.query.standard_ordering:
                field = field.copy()
                field.reverse_ordering()
            select_ref = selected_exprs.get(field.expression)
            if select_ref or (isinstance(field.expression, F) and (select_ref := selected_exprs.get(field.expression.name))):
                if field.nulls_first is None and field.nulls_last is None or self.connection.features.supports_order_by_nulls_modifier:
                    field = field.copy()
                    field.expression = select_ref
                elif self.query.combinator:
                    field = field.copy()
                    field.expression = Ref(select_ref.refs, select_ref.source)
            yield (field, select_ref is not None)
            continue
        if field == '?':
            yield (OrderBy(Random()), False)
            continue
        (col, order) = get_order_dir(field, default_order)
        descending = order == 'DESC'
        if (select_ref := selected_exprs.get(col)):
            yield (OrderBy(select_ref, descending=descending), True)
            continue
        if (expr := self.query.annotations.get(col)):
            ref = col
            transforms = []
        else:
            (ref, *transforms) = col.split(LOOKUP_SEP)
            expr = self.query.annotations.get(ref)
        if expr:
            if self.query.combinator and self.select:
                if transforms:
                    raise NotImplementedError('Ordering combined queries by transforms is not implemented.')
                expr = F(ref)
            if transforms:
                for name in transforms:
                    expr = self.query.try_transform(expr, name)
            if isinstance(expr, Value):
                expr = Cast(expr, expr.output_field)
            yield (OrderBy(expr, descending=descending), False)
            continue
        if '.' in field:
            (table, col) = col.split('.', 1)
            yield (OrderBy(RawSQL('%s.%s' % (self.quote_name_unless_alias(table), col), []), descending=descending), False)
            continue
        if self.query.extra and col in self.query.extra:
            if <MASK>:
                yield (OrderBy(Ref(col, RawSQL(*self.query.extra[col])), descending=descending), True)
            else:
                yield (OrderBy(RawSQL(*self.query.extra[col]), descending=descending), False)
        elif self.query.combinator and self.select:
            yield (OrderBy(F(col), descending=descending), False)
        else:
            yield from self.find_ordering_name(field, self.query.get_meta(), default_order=default_order)

def _find_matches(graph: Graph, modules: dict[str, torch.nn.Module], patterns: dict[Pattern, QuantizeHandler], root_node_getter_mapping: dict[Pattern, Callable], standalone_module_names: Optional[list[str]]=None, standalone_module_classes: Optional[list[type]]=None, custom_module_classes: Optional[list[Any]]=None) -> dict[str, _MatchResult]:
    """
    Matches the nodes in the input graph to quantization patterns, and
    outputs the information needed to quantize them in future steps.

    Inputs:
      - graph: an fx.Graph object
      - modules: a mapping of fully qualified module name to instance,
          for example, {'foo': ModuleFoo, ...}
      - patterns: a mapping from a tuple of nodes in reverse order to
          uninitialized QuantizeHandler subclass.

    Outputs a map of
      node_name ->
        (node, matched_values, matched_pattern, QuantizeHandler instance,
         qconfig)

    For example, {
      'relu_1': (relu_1, [relu_1], torch.nn.functional.relu,
                 <CopyNodeQuantizeHandler instance>, QConfig(...)),
      ...
    }
    """
    if custom_module_classes is None:
        custom_module_classes = []
    if standalone_module_classes is None:
        standalone_module_classes = []
    if standalone_module_names is None:
        standalone_module_names = []
    match_map: dict[str, _MatchResult] = {}
    all_matched: set[str] = set()

    def _recursive_record_node_in_match_map(last_node, match_map, node_pattern, matched_node_pattern, pattern, match_value):
        if <MASK>:
            match_map[node_pattern.name] = (last_node, matched_node_pattern, pattern, match_value)
        elif not isinstance(node_pattern, Iterable):
            return
        else:
            for n in node_pattern:
                _recursive_record_node_in_match_map(last_node, match_map, n, matched_node_pattern, pattern, match_value)

    def record_match(pattern, node, last_node, matched_node_pattern, match_map):
        if isinstance(pattern, tuple):
            (s, *args) = pattern
            is_single_arg = len(args) == 1
            current_node_pattern: list[Node] = []
            record_match(s, node, last_node, matched_node_pattern, match_map)
            if pattern[0] is not getattr:
                for (subpattern, arg) in zip(args, node.args):
                    record_match(subpattern, arg, node, current_node_pattern, match_map)
            if len(current_node_pattern) > 1:
                if is_single_arg:
                    matched_node_pattern.append(tuple(current_node_pattern))
                else:
                    matched_node_pattern.extend(list(current_node_pattern))
            else:
                matched_node_pattern.append(current_node_pattern[0])
        else:
            matched_node_pattern.append(node)
    for node in reversed(graph.nodes):
        if node.name not in match_map and node.name not in all_matched:
            for (pattern, quantize_handler_cls) in patterns.items():
                root_node_getter = root_node_getter_mapping.get(pattern)
                if _is_match(modules, node, pattern) and node.name not in match_map:
                    matched_node_pattern: list[Node] = []
                    record_match(pattern, node, node, matched_node_pattern, match_map)
                    quantize_handler = quantize_handler_cls(matched_node_pattern, modules, root_node_getter)
                    last_node = node
                    _recursive_record_node_in_match_map(last_node, match_map, matched_node_pattern, matched_node_pattern, pattern, quantize_handler)
                    break
    assert modules is not None
    for node in graph.nodes:
        if node.op == 'call_module' and type(modules[node.target]) in custom_module_classes:
            match_map[node.name] = (node, node, None, QuantizeHandler(node, modules, is_custom_module=True))

    def is_standalone_module(node_target: str, modules: dict[str, torch.nn.Module]):
        assert modules is not None
        return node_target in standalone_module_names or type(modules[node_target]) in standalone_module_classes
    for node in graph.nodes:
        if node.op == 'call_module' and (is_standalone_module(node.target, modules) or _is_observed_standalone_module(modules[node.target])):
            match_map[node.name] = (node, node, None, QuantizeHandler(node, modules, is_standalone_module=True))
    return match_map

def supercedes(a, b):
    """A is consistent and strictly more specific than B"""
    if len(a) < len(b):
        return not a and len(b) == 1 and isvariadic(b[-1])
    elif <MASK>:
        return all(map(issubclass, a, b))
    else:
        p1 = 0
        p2 = 0
        while p1 < len(a) and p2 < len(b):
            cur_a = a[p1]
            cur_b = b[p2]
            if not (isvariadic(cur_a) or isvariadic(cur_b)):
                if not issubclass(cur_a, cur_b):
                    return False
                p1 += 1
                p2 += 1
            elif isvariadic(cur_a):
                assert p1 == len(a) - 1
                return p2 == len(b) - 1 and issubclass(cur_a, cur_b)
            elif isvariadic(cur_b):
                assert p2 == len(b) - 1
                if not issubclass(cur_a, cur_b):
                    return False
                p1 += 1
        return p2 == len(b) - 1 and p1 == len(a)

def _helper(graph, prev_applied=None):
    for (dp, sub_graph) in graph.values():
        applied = None
        if <MASK>:
            if prev_applied is not None:
                raise RuntimeError(f'Sharding twice on a single pipeline is likely unintended and will cause data loss. Sharding already applied to {prev_applied} while trying to apply to {dp}')
            sig = inspect.signature(dp.apply_sharding)
            if len(sig.parameters) < 3:
                dp.apply_sharding(num_of_instances, instance_id)
            else:
                dp.apply_sharding(num_of_instances, instance_id, sharding_group=sharding_group)
            applied = dp
        if applied is None:
            applied = prev_applied
        _helper(sub_graph, applied)

def decorator(f):
    """The decorator."""
    if hasattr(inspect, 'signature') and np_sig is not None:
        try:
            sig = inspect.signature(f)
        except ValueError:
            sig = None
        if sig is not None:
            for (name, param) in sig.parameters.items():
                np_param = np_sig.parameters.get(name)
                if np_param is None:
                    if <MASK>:
                        raise TypeError(f"Cannot find parameter {name} in the numpy function's signature (which has these parameters: {list(np_sig.parameters.keys())}). Argument `np_fun_name` is {np_fun_name_orig}. Argument `np_fun` is {np_fun_orig}.")
                    else:
                        continue
                if is_sig_mismatch_an_error() and (not _is_compatible_param_kind(param.kind, np_param.kind)):
                    raise TypeError(f'Parameter {name} is of kind {param.kind} while in numpy it is of kind {np_param.kind}. Argument `np_fun_name` is {np_fun_name_orig}. Argument `np_fun` is {np_fun_orig}.')
                has_default = param.default != inspect.Parameter.empty
                np_has_default = np_param.default != inspect.Parameter.empty
                if is_sig_mismatch_an_error() and has_default != np_has_default:
                    raise TypeError('Parameter {} should{} have a default value. Argument `np_fun_name` is {}. Argument `np_fun` is {}.'.format(name, '' if np_has_default else ' not', np_fun_name_orig, np_fun_orig))
            for name in np_sig.parameters:
                if name not in sig.parameters:
                    unsupported_params.append(name)
    f.__doc__ = _np_doc_helper(f, np_fun, np_fun_name=np_fun_name, unsupported_params=unsupported_params, link=link)
    return f

def _linalg_vector_norm_helper(g: jit_utils.GraphContext, self: torch._C.Value, ord: float, dim: Sequence[int] | None, keepdim: bool, dtype: torch._C.Value):
    axes = None
    if _is_none(dim):
        self = _reshape_helper(g, self, [-1])
        keepdim = False
    elif g.opset >= 18:
        axes = g.op('Constant', value_t=torch.tensor(dim, dtype=torch.long))
    if ord == math.inf:
        if <MASK>:
            result = g.op('ReduceMax', g.op('Abs', self), axes_i=dim, keepdims_i=keepdim)
        elif axes is None:
            result = g.op('ReduceMax', g.op('Abs', self), keepdims_i=keepdim)
        else:
            result = g.op('ReduceMax', g.op('Abs', self), axes, keepdims_i=keepdim)
    elif ord == -math.inf:
        if g.opset < 18:
            result = g.op('ReduceMin', g.op('Abs', self), axes_i=dim, keepdims_i=keepdim)
        elif axes is None:
            result = g.op('ReduceMin', g.op('Abs', self), keepdims_i=keepdim)
        else:
            result = g.op('ReduceMin', g.op('Abs', self), axes, keepdims_i=keepdim)
    elif ord == 0:
        if g.opset < 11:
            return _onnx_opset_unsupported_detailed('linalg_vector_norm', 9, 11, 'ord=0 not supported', self)
        else:
            if dim is None:
                self = _reshape_helper(g, self, g.op('Constant', value_t=torch.tensor([-1], dtype=torch.int64)))
                keepdim = False
            cond_op = g.op('Not', g.op('Equal', self, g.op('Constant', value_t=torch.LongTensor([0]))))
            cond_op = g.op('Cast', cond_op, to_i=_type_utils.JitScalarType.from_value(self).onnx_type())
            return _reducesum_helper(g, cond_op, axes_i=dim, keepdims_i=keepdim)
    elif ord == 1:
        if g.opset < 18:
            result = _reduce_op_symbolic_helper('ReduceL1')(g, self, dim=dim, keepdim=keepdim)
        elif axes is None:
            result = _reduce_op_symbolic_helper('ReduceL1')(g, self, keepdim=keepdim)
        else:
            result = _reduce_op_symbolic_helper('ReduceL1')(g, self, axes, keepdim=keepdim)
    elif ord == 2:
        if g.opset < 18:
            result = _reduce_op_symbolic_helper('ReduceL2')(g, self, dim=dim, keepdim=keepdim)
        elif axes is None:
            result = _reduce_op_symbolic_helper('ReduceL2')(g, self, keepdim=keepdim)
        else:
            result = _reduce_op_symbolic_helper('ReduceL2')(g, self, axes, keepdim=keepdim)
    else:
        ord_op = g.op('Constant', value_t=torch.tensor(ord, dtype=torch.float32))
        result = _reducesum_helper(g, g.op('Pow', g.op('Abs', self), ord_op), axes_i=dim, keepdims_i=keepdim)
        result = g.op('Pow', result, g.op('Div', g.op('Constant', value_t=torch.tensor(1, dtype=torch.float32)), ord_op))
    if not _is_none(dtype):
        dtype = _get_const(dtype, 'i', 'dtype')
        result = g.op('Cast', result, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    return result

def _create_chunk_list(tensor: torch.Tensor) -> list[ChunkStorageMetadata]:
    if hasattr(tensor, '__create_chunk_list__'):
        local_chunks = tensor.__create_chunk_list__()
    elif <MASK>:
        local_chunks = [_chunk_for_shard(shard.metadata) for shard in tensor.local_shards()]
    elif isinstance(tensor, torch.Tensor):
        local_chunks = [_create_chunk_from_tensor(tensor)]
    else:
        raise ValueError(f'Unsupported Type, expecting one of [Tensor, DTensor, ShardedTensor] ,but got {type(tensor)}')
    return local_chunks

@final
def _getitem_slice(self, key: slice) -> Self:
    """
        __getitem__ for the case where the key is a slice object.
        """
    slobj = self.index._convert_slice_indexer(key, kind='getitem')
    if isinstance(slobj, np.ndarray):
        indexer = lib.maybe_indices_to_slice(slobj.astype(np.intp), len(self))
        if <MASK>:
            return self.take(indexer, axis=0)
        slobj = indexer
    return self._slice(slobj)

def _get_split_source(pg):
    split_from = None
    if <MASK>:
        split_from = pg._get_backend(pg.bound_device_id)
    elif pg is _world.default_pg:
        try:
            split_from = pg._get_backend(torch.device('cuda'))
        except RuntimeError:
            pass
    if not split_from or not split_from.supports_splitting:
        return None
    while _GLOO_AVAILABLE and isinstance(split_from, _ProcessGroupWrapper):
        split_from = split_from.wrapped_pg
    return split_from

@wraps(func)
def wrapper(*args, **kwargs):
    if not (TEST_CUDA or TEST_HPU or TEST_XPU):
        sys.exit(TEST_SKIPS['no_cuda'].exit_code)
    world_size = int(os.environ['WORLD_SIZE'])
    if TEST_CUDA and torch.cuda.device_count() < world_size:
        sys.exit(TEST_SKIPS[f'multi-gpu-{world_size}'].exit_code)
    if TEST_HPU and torch.hpu.device_count() < world_size:
        sys.exit(TEST_SKIPS[f'multi-gpu-{world_size}'].exit_code)
    if <MASK>:
        sys.exit(TEST_SKIPS[f'multi-gpu-{world_size}'].exit_code)
    return func(*args, **kwargs)

@property
def underlying_value(self):
    if isinstance(self.vt, variables.LazyVariableTracker) and (not self.vt.is_realized()) and self.vt.is_hashable():
        return self.vt.original_value()
    if isinstance(self.vt, variables.TensorVariable):
        x = self.vt.as_proxy().node.meta['example_value']
    elif isinstance(self.vt, variables.TupleVariable):
        Hashable = ConstDictVariable._HashableTracker
        x = tuple((Hashable(e).underlying_value for e in self.vt.items))
    elif isinstance(self.vt, variables.NNModuleVariable):
        return self.vt.value
    elif isinstance(self.vt, variables.UnspecializedNNModuleVariable):
        return self.vt.value
    elif <MASK>:
        return self.vt.get_function()
    elif isinstance(self.vt, variables.WeakRefVariable):
        Hashable = ConstDictVariable._HashableTracker
        return Hashable(self.vt.referent_vt).underlying_value
    elif isinstance(self.vt, variables.FrozenDataClassVariable):
        Hashable = ConstDictVariable._HashableTracker
        fields_values = {k: Hashable(v).underlying_value for (k, v) in self.vt.fields.items()}
        return variables.FrozenDataClassVariable.HashWrapper(self.vt.python_type(), fields_values)
    elif isinstance(self.vt, variables.UserDefinedObjectVariable):
        return self.vt.value
    else:
        x = self.vt.as_python_constant()
    return x

def split_args_kwargs_into_chunks(args: tuple[Any, ...], kwargs: Optional[dict[str, Any]], chunks: int, args_chunk_spec: Optional[tuple[TensorChunkSpec, ...]]=None, kwargs_chunk_spec: Optional[dict[str, TensorChunkSpec]]=None) -> tuple[list[tuple], list[dict]]:
    """
    Given a sequence of args and kwargs, split them into a number of chunks
    according to  their respective chunking specs.

    Args:
        args: Tuple of args
        kwargs: Dict of kwargs
        chunks: Number of chunks to split the args and kwargs into
        args_chunk_spec: chunking specs for args, in same shape as args
        kwargs_chunk_spec: chunking specs for kwargs, in same shape as kwargs

    Returns:
        args_split: List of sharded args
        kwargs_split: List of sharded kwargs
    """
    if kwargs is None:
        kwargs = {}

    def default_spec(v):
        if isinstance(v, torch.Tensor | BlockMask):
            return TensorChunkSpec(DEFAULT_CHUNK_DIM)
        else:
            return _Replicate()
    if <MASK>:
        args_chunk_spec = tree_map(default_spec, args)
    if kwargs_chunk_spec is None:
        kwargs_chunk_spec = tree_map(default_spec, kwargs)
    args_split_dict = _shard_dict_of_args(dict(enumerate(args)), dict(enumerate(args_chunk_spec)), chunks)
    real_num_chunks = len(args_split_dict)
    kwargs_split = _shard_dict_of_args(kwargs, kwargs_chunk_spec, real_num_chunks)
    if len(kwargs_split) < real_num_chunks:
        real_num_chunks = len(kwargs_split)
        args_split_dict = _shard_dict_of_args(dict(enumerate(args)), dict(enumerate(args_chunk_spec)), real_num_chunks)
    if len(args_split_dict) != len(kwargs_split):
        raise RuntimeError(f'args and kwargs are split into different number of chunks: {len(args_split_dict)}, {len(kwargs_split)}')
    args_split = [tuple((chunk_args[i] for i in range(len(chunk_args)))) for chunk_args in args_split_dict]
    return (args_split, kwargs_split)

def get_devices_from(destinations, canonicalize_devices=True):
    if isinstance(destinations, value_lib.DistributedValues):
        return destinations._devices
    if <MASK>:
        if isinstance(destinations, six.string_types):
            return (device_util.resolve(destinations),)
        return (device_util.resolve(destinations.device),)
    if isinstance(destinations, six.string_types):
        return (device_util.canonicalize_without_job_and_task(destinations),)
    return (device_util.canonicalize_without_job_and_task(destinations.device),)

def __new__(cls, shape, dtype=None, buf=None, offset=0, strides=None, formats=None, names=None, titles=None, byteorder=None, aligned=False, mask=ma.nomask, hard_mask=False, fill_value=None, keep_mask=True, copy=False, **options):
    self = np.recarray.__new__(cls, shape, dtype=dtype, buf=buf, offset=offset, strides=strides, formats=formats, names=names, titles=titles, byteorder=byteorder, aligned=aligned)
    mdtype = ma.make_mask_descr(self.dtype)
    if <MASK>:
        if not keep_mask:
            self._mask = tuple([False] * len(mdtype))
    else:
        mask = np.array(mask, copy=copy)
        if mask.shape != self.shape:
            (nd, nm) = (self.size, mask.size)
            if nm == 1:
                mask = np.resize(mask, self.shape)
            elif nm == nd:
                mask = np.reshape(mask, self.shape)
            else:
                msg = f'Mask and data not compatible: data size is {nd}, mask size is {{nm}}.'
                raise ma.MAError(msg)
        if not keep_mask:
            self.__setmask__(mask)
            self._sharedmask = True
        else:
            if mask.dtype == mdtype:
                _mask = mask
            else:
                _mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
            self._mask = _mask
    return self

