def _add_bodies(self, msg):
    if self.body or not self.alternatives:
        super()._add_bodies(msg)
    if self.alternatives:
        if <MASK>:
            raise AttributeError('EmailMultiAlternatives no longer supports the undocumented `alternative_subtype` attribute')
        msg.make_alternative()
        encoding = self.encoding or settings.DEFAULT_CHARSET
        for alternative in self.alternatives:
            (maintype, subtype) = alternative.mimetype.split('/', 1)
            content = alternative.content
            if maintype == 'text':
                if isinstance(content, bytes):
                    content = content.decode()
                msg.add_alternative(content, subtype=subtype, charset=encoding)
            else:
                content = force_bytes(content, encoding=encoding, strings_only=True)
                msg.add_alternative(content, maintype=maintype, subtype=subtype)
    return msg

def get_multiplier() -> float:
    if <MASK>:
        return 10.0
    multiplier = 3.0 if res.dtype in (torch.float16, torch.bfloat16) else 2.0
    if use_larger_multiplier_for_smaller_tensor and fp64_ref.numel() <= 10:
        multiplier = 10.0
    elif use_larger_multiplier_for_smaller_tensor and fp64_ref.numel() <= 500:
        multiplier = 8.0
    elif fp64_ref.numel() < 1000 or (ref.ndim == 4 and ref.shape[-1] == ref.shape[-2] == 1) or tol >= 2 * 0.01:
        multiplier = 3.0
    return multiplier

def unwrap_proxy(self, e: T) -> object:
    if isinstance(e, Tensor):
