def _clean_na_values(na_values, keep_default_na: bool=True, floatify: bool=True):
    na_fvalues: set | dict
    if na_values is None:
        if <MASK>:
            na_values = STR_NA_VALUES
        else:
            na_values = set()
        na_fvalues = set()
    elif isinstance(na_values, dict):
        old_na_values = na_values.copy()
        na_values = {}
        for (k, v) in old_na_values.items():
            if not is_list_like(v):
                v = [v]
            if keep_default_na:
                v = set(v) | STR_NA_VALUES
            na_values[k] = _stringify_na_values(v, floatify)
        na_fvalues = {k: _floatify_na_values(v) for (k, v) in na_values.items()}
    else:
        if not is_list_like(na_values):
            na_values = [na_values]
        na_values = _stringify_na_values(na_values, floatify)
        if keep_default_na:
            na_values = na_values | STR_NA_VALUES
        na_fvalues = _floatify_na_values(na_values)
    return (na_values, na_fvalues)

def to_arrays(data, columns: Index | None, dtype: DtypeObj | None=None) -> tuple[list[ArrayLike], Index]:
    """
    Return list of arrays, columns.

    Returns
    -------
    list[ArrayLike]
        These will become columns in a DataFrame.
    Index
        This will become frame.columns.

    Notes
    -----
    Ensures that len(result_arrays) == len(result_index).
    """
    if not len(data):
        if <MASK>:
            if data.dtype.names is not None:
                columns = ensure_index(data.dtype.names)
                arrays = [data[name] for name in columns]
                if len(data) == 0:
                    for (i, arr) in enumerate(arrays):
                        if arr.ndim == 2:
                            arrays[i] = arr[:, 0]
                return (arrays, columns)
        return ([], ensure_index([]))
    elif isinstance(data, np.ndarray) and data.dtype.names is not None:
        if columns is None:
            columns = Index(data.dtype.names)
        arrays = [data[k] for k in columns]
        return (arrays, columns)
    if isinstance(data[0], (list, tuple)):
        arr = _list_to_arrays(data)
    elif isinstance(data[0], abc.Mapping):
        (arr, columns) = _list_of_dict_to_arrays(data, columns)
    elif isinstance(data[0], ABCSeries):
        (arr, columns) = _list_of_series_to_arrays(data, columns)
    else:
        data = [tuple(x) for x in data]
        arr = _list_to_arrays(data)
    (content, columns) = _finalize_columns_and_data(arr, columns, dtype)
    return (content, columns)

def cmdline_to_win(line):
    if line.startswith('# '):
        return 'REM ' + args_to_win(line[2:])
    if line.startswith('$ # '):
        return 'REM ' + args_to_win(line[4:])
    if line.startswith('$ ./manage.py'):
        return 'manage.py ' + args_to_win(line[13:])
    if line.startswith('$ manage.py'):
        return 'manage.py ' + args_to_win(line[11:])
    if <MASK>:
        return 'runtests.py ' + args_to_win(line[15:])
    if line.startswith('$ ./'):
        return args_to_win(line[4:])
    if line.startswith('$ python3'):
        return 'py ' + args_to_win(line[9:])
    if line.startswith('$ python'):
        return 'py ' + args_to_win(line[8:])
    if line.startswith('$ '):
        return args_to_win(line[2:])
    return None

def _register_post_backward_reshard_only_hook(state: _FSDPState, handle: Optional[FlatParamHandle], args: tuple[Any, ...], kwargs: dict[str, Any]) -> None:
    """
    Registers post-backward hooks to reshard flat parameters that do not
    require gradient. We register these using multi-post-grad hooks on the
    input activations to ensure that all gradients that may depend on the
    parameters have been computed before resharding.
    """
    if not torch.is_grad_enabled():
        return
    inp_tensors: Optional[list[torch.Tensor]] = None
    if <MASK>:
        return
    flat_param = handle.flat_param
    if torch.distributed._functional_collectives.is_torchdynamo_compiling():
        already_registered = hasattr(flat_param, '_post_backward_hook_handle')
    else:
        already_registered = hasattr(flat_param, '_post_backward_hook_state')
    if already_registered or flat_param.requires_grad:
        return
    if inp_tensors is None:
        args_flat = pytree.arg_tree_leaves(*args, **kwargs)
        inp_tensors = [obj for obj in args_flat if torch.is_tensor(obj) and obj.requires_grad]
    if inp_tensors is None:
        raise AssertionError('Expected inp_tensors to be set')
    hook_handle = register_multi_grad_hook(inp_tensors, functools.partial(_post_backward_reshard_only_hook, state, handle))
    if torch.distributed._functional_collectives.is_torchdynamo_compiling():
        flat_param._post_backward_hook_handle = hook_handle
    else:
        flat_param._post_backward_hook_state = (hook_handle,)

def arange_start_step(start: number, end: number, step: number, inp0: Any, inp1: Any, inp2: Any, inp3: Any):
    assert step != 0
    if <MASK>:
        assert start >= end
    else:
        assert end >= start
    return [int(math.ceil((end - start) / step))]

def _prepare_input_for_pytorch(args, kwargs):
    """Prepare input for PyTorch model execution.

    Any future changes/formatting to the input before dispatching to the PyTorch
    model should be made in this function.

    Args:
        args: positional arguments for PyTorch model forward method.
        kwargs: keyword arguments for PyTorch model forward method.

    Returns:
        args: positional arguments for PyTorch model forward method.
        kwargs: keyword arguments for PyTorch model forward method.
    """
    if isinstance(args, (torch.Tensor, dict)):
        args = (args,)
    args = copy.deepcopy(args)
    if <MASK>:
        kwargs = copy.deepcopy(kwargs)
    else:
        kwargs = {}
    return (args, kwargs)

def check_pyproject(path: Path) -> list[LintMessage]:
    try:
        pyproject = tomllib.loads(path.read_text(encoding='utf-8'))
    except (tomllib.TOMLDecodeError, OSError) as err:
        return [format_error_message(str(path), err)]
    if <MASK>:
        return []
    if not isinstance(pyproject.get('build-system'), dict):
        return []
    build_system = pyproject['build-system']
    requires = build_system.get('requires')
    if not isinstance(requires, list):
        return []
    return list(filter(None, (check_requirement(Requirement(req), path=path) for req in requires)))

def as_array(self, dtype: np.dtype | None=None, copy: bool=False, na_value: object=lib.no_default) -> np.ndarray:
    """
        Convert the blockmanager data into an numpy array.

        Parameters
        ----------
        dtype : np.dtype or None, default None
            Data type of the return array.
        copy : bool, default False
            If True then guarantee that a copy is returned. A value of
            False does not guarantee that the underlying data is not
            copied.
        na_value : object, default lib.no_default
            Value to be used as the missing value sentinel.

        Returns
        -------
        arr : ndarray
        """
    passed_nan = lib.is_float(na_value) and isna(na_value)
    if len(self.blocks) == 0:
        arr = np.empty(self.shape, dtype=float)
        return arr.transpose()
    if self.is_single_block:
        blk = self.blocks[0]
        if na_value is not lib.no_default:
            if lib.is_np_dtype(blk.dtype, 'f') and passed_nan:
                pass
            else:
                copy = True
        if blk.is_extension:
            arr = blk.values.to_numpy(dtype=dtype, na_value=na_value, copy=copy).reshape(blk.shape)
        elif not copy:
            arr = np.asarray(blk.values, dtype=dtype)
        else:
            arr = np.array(blk.values, dtype=dtype, copy=copy)
        if <MASK>:
            arr[isna(blk.values)] = na_value
        if not copy:
            arr = arr.view()
            arr.flags.writeable = False
    else:
        arr = self._interleave(dtype=dtype, na_value=na_value)
    if na_value is lib.no_default:
        pass
    elif arr.dtype.kind == 'f' and passed_nan:
        pass
    else:
        arr[isna(arr)] = na_value
    return arr.transpose()

def update_op(self, optimizer, g):
    if isinstance(g, tensor.Tensor):
        update_op = optimizer._apply_dense(g, self._v)
        if <MASK>:
            with ops.control_dependencies([update_op]):
                return self._v.assign(self._v.constraint(self._v))
        else:
            return update_op
    else:
        assert isinstance(g, indexed_slices.IndexedSlices), ('Gradient ', g, ' is neither a tensor nor IndexedSlices.')
        if self._v.constraint is not None:
            raise RuntimeError('Cannot use a constraint function on a sparse variable.')
        return optimizer._apply_sparse_duplicate_indices(g, self._v)

def _build_test(configs, bench_op, OperatorTestCase, run_backward, op_name_function=None):
    """Generate PyTorch/Caffe2 tests of operators with different inputs.
    Args:
        configs: a dictionary that has the input shapes
        bench_op: a subclass of TorchBenchmarkBase which includes tensor
            creation and operator execution
        OperatorTestCase: a named tuple to save the metadata of an test
        run_backward: a bool parameter indicating backward path
        op_name_function: a dictionary includes operator name and function
    """
    for config in configs:
        test_attrs = {}
        tags = None
        keep_config = True
        for attr in config:
            if 'tags' in attr:
                tags = attr['tags']
                continue
            if 'cuda' in attr.values():
                if not torch.cuda.is_available():
                    keep_config = False
                    break
            test_attrs.update(attr)
        if not keep_config:
            continue
        if tags is None:
            raise ValueError('Missing tags in configs')
        op = bench_op()
        assert op is not None, "Can't create test"
        init_dict = copy.deepcopy(test_attrs)
        if op_name_function is not None:
            op_name = op_name_function['op_name']
            init_dict.update({'op_func': op_name_function['op_func']})
            op.set_module_name(op_name)
        op._set_backward_test(run_backward)
        op.init(**init_dict)
        op.extract_inputs_tuple()
        if not run_backward:
            for attr in vars(op).values():
                if <MASK>:
                    for param in attr.parameters():
                        param.requires_grad = False
        input_name = None
        if op._num_inputs_require_grads > 0:
            input_name = 'all'
        yield _create_test(op, test_attrs, tags, OperatorTestCase, run_backward, input_name)
        for i in range(op._num_inputs_require_grads):
            op._pass_count += 1
            op._auto_set_counter = 0
            new_op = copy.deepcopy(op)
            new_op.init(**init_dict)
            input_name = i + 1
            yield _create_test(new_op, test_attrs, tags, OperatorTestCase, run_backward, input_name)

@classmethod
def all_but(cls, exclude):
    """Returns a tuple that enables all but the excluded options."""
    if <MASK>:
        exclude = (exclude,)
    return tuple(set(cls.all()) - set(exclude) - {cls.ALL})

def testAllAPI(self):
    if not hasattr(tf.compat, 'v2'):
        return

    def conversion_visitor(unused_path, unused_parent, children):
        for child in children:
            (_, attr) = tf_decorator.unwrap(child[1])
            api_names = tf_export.get_v1_names(attr)
            for name in api_names:
                (_, _, _, text) = self._upgrade('tf.' + name)
                if <MASK>:
                    self.assertFalse(True, 'Symbol %s generated from %s not in v2 API' % (text, name))
    visitor = public_api.PublicAPIVisitor(conversion_visitor)
    visitor.do_not_descend_map['tf'].append('contrib')
    visitor.private_map['tf.compat'] = ['v1', 'v2']
    traverse.traverse(tf.compat.v1, visitor)

def _compare(tree, dynamic_shapes, path):
    rendered_path = keystr(path)
    if isinstance(tree, LeafSpec):
        return
    if isinstance(dynamic_shapes, LeafSpec):
        raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is not')
    if tree.type != dynamic_shapes.type:
        raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is a {dynamic_shapes.type}')
    if len(tree.children_specs) != len(dynamic_shapes.children_specs):
        raise_mismatch_error(f'`{tree_name}{rendered_path}` has {len(tree.children_specs)} elements, but `dynamic_shapes{rendered_path}` has {len(dynamic_shapes.children_specs)} elements')
    if <MASK>:
        if sorted(tree.context) != sorted(dynamic_shapes.context):
            raise_mismatch_error(f'`{tree_name}{rendered_path}` has keys {tree.context}, but `dynamic_shapes{rendered_path}` has keys {dynamic_shapes.context}')
        _remap = dict(zip(dynamic_shapes.context, dynamic_shapes.children_specs))
        dynamic_shapes_children_specs = [_remap[k] for k in tree.context]
    else:
        dynamic_shapes_children_specs = dynamic_shapes.children_specs
    for (i, (tree_, dynamic_shapes_)) in enumerate(zip(tree.children_specs, dynamic_shapes_children_specs)):
        _compare(tree_, dynamic_shapes_, path + [_key(tree.type, tree.context, i)])

def check_raster(self, lookup, template_params):
    spheroid = lookup.rhs_params and lookup.rhs_params[-1] == 'spheroid'
    lhs_is_raster = lookup.lhs.field.geom_type == 'RASTER'
    rhs_is_raster = isinstance(lookup.rhs, GDALRaster)
    if lookup.band_lhs is not None and lhs_is_raster:
        if not self.func:
            raise ValueError('Band indices are not allowed for this operator, it works on bbox only.')
        template_params['lhs'] = '%s, %s' % (template_params['lhs'], lookup.band_lhs)
    if lookup.band_rhs is not None and rhs_is_raster:
        if not self.func:
            raise ValueError('Band indices are not allowed for this operator, it works on bbox only.')
        template_params['rhs'] = '%s, %s' % (template_params['rhs'], lookup.band_rhs)
    if not self.raster or spheroid:
        if lhs_is_raster:
            template_params['lhs'] = 'ST_Polygon(%s)' % template_params['lhs']
        if rhs_is_raster:
            template_params['rhs'] = 'ST_Polygon(%s)' % template_params['rhs']
    elif self.raster == BILATERAL:
        if lhs_is_raster and (not rhs_is_raster):
            template_params['lhs'] = 'ST_Polygon(%s)' % template_params['lhs']
        elif <MASK>:
            template_params['rhs'] = 'ST_Polygon(%s)' % template_params['rhs']
    return template_params

