def compute_returns_yaml(f: NativeFunction) -> tuple[list[dict[str, str]], dict[str, str]]:
    name_to_field_name: dict[str, str] = {}
    names = cpp.return_names(f)
    returns = []
    for (i, (r, name)) in enumerate(zip(f.func.returns, names)):
        ret = {'dynamic_type': dynamic_type(r.type), 'name': name, 'type': cpp.return_type(r, symint=False).cpp_type()}
        if <MASK>:
            ret['field_name'] = r.name
            if f.func.is_out_fn():
                name_to_field_name[f.func.arguments.out[i].name] = r.name
        returns.append(ret)
    return (returns, name_to_field_name)

@parameterized.parameters((True, quant_opts_pb2.XLA), (False, quant_opts_pb2.XLA), (True, quant_opts_pb2.UNIFORM_QUANTIZED), (False, quant_opts_pb2.UNIFORM_QUANTIZED))
