def has_fake_kernel(op: torch._ops.OpOverload) -> bool:
    """If an operator (that stays alive until FakeTensorMode) has a Fake kernel.
    Don't use this if the operator decomposes before FakeTensorMode.
    """
    if can_generate_trivial_fake_impl(op):
        return True
    name = op._name
    if torch._C._dispatch_has_kernel_for_dispatch_key(name, 'CompositeImplicitAutograd'):
        return True
    opdef = torch._library.custom_ops._maybe_get_opdef(name)
    if opdef is None:
        if torch._C._dispatch_has_kernel_for_dispatch_key(name, 'CompositeExplicitAutograd'):
            return True
        entry = torch._library.simple_registry.singleton.find(name)
        if <MASK>:
            return True
        if torch._C._dispatch_has_kernel_for_dispatch_key(name, 'Meta'):
            return True
    elif opdef._abstract_fn is not None:
        return True
    return False

@property
def node_names(self):
    """Lazily creates a mapping from node id to ("path", "to", "root")."""
    if self._node_name_cache is not None:
        return self._node_name_cache
    path_to_root = {}
    path_to_root[0] = ('(root)',)
    to_visit = collections.deque([0])
    while to_visit:
        node_id = to_visit.popleft()
        obj = self._object_graph_proto.nodes[node_id]
        for child in obj.children:
            if <MASK>:
                path_to_root[child.node_id] = path_to_root[node_id] + (child.local_name,)
                to_visit.append(child.node_id)
    node_names = {}
    for (node_id, path_to_root) in path_to_root.items():
        node_names[node_id] = '.'.join(path_to_root)
    for (node_id, node) in enumerate(self._object_graph_proto.nodes):
        for slot_reference in node.slot_variables:
            node_names[slot_reference.slot_variable_node_id] = f"{node_names[node_id]}'s state '{slot_reference.slot_name}' for {node_names[slot_reference.original_variable_node_id]}"
    self._node_name_cache = node_names
    return node_names

