def _parse_interval(interval_str):
    """Convert a human-readable interval to a tuple of start and end value.

  Args:
    interval_str: (`str`) A human-readable str representing an interval
      (e.g., "[1M, 2M]", "<100k", ">100ms"). The items following the ">", "<",
      ">=" and "<=" signs have to start with a number (e.g., 3.0, -2, .98).
      The same requirement applies to the items in the parentheses or brackets.

  Returns:
    Interval object where start or end can be None
    if the range is specified as "<N" or ">N" respectively.

  Raises:
    ValueError: if the input is not valid.
  """
    interval_str = interval_str.strip()
    if interval_str.startswith('<='):
        if _NUMBER_PATTERN.match(interval_str[2:].strip()):
            return Interval(start=None, start_included=False, end=interval_str[2:].strip(), end_included=True)
        else:
            raise ValueError("Invalid value string after <= in '%s'" % interval_str)
    if interval_str.startswith('<'):
        if _NUMBER_PATTERN.match(interval_str[1:].strip()):
            return Interval(start=None, start_included=False, end=interval_str[1:].strip(), end_included=False)
        else:
            raise ValueError("Invalid value string after < in '%s'" % interval_str)
    if interval_str.startswith('>='):
        if _NUMBER_PATTERN.match(interval_str[2:].strip()):
            return Interval(start=interval_str[2:].strip(), start_included=True, end=None, end_included=False)
        else:
            raise ValueError("Invalid value string after >= in '%s'" % interval_str)
    if interval_str.startswith('>'):
        if _NUMBER_PATTERN.match(interval_str[1:].strip()):
            return Interval(start=interval_str[1:].strip(), start_included=False, end=None, end_included=False)
        else:
            raise ValueError("Invalid value string after > in '%s'" % interval_str)
    if not interval_str.startswith(('[', '(')) or not interval_str.endswith((']', ')')):
        raise ValueError('Invalid interval format: %s. Valid formats are: [min, max], (min, max), <max, >min' % interval_str)
    interval = interval_str[1:-1].split(',')
    if len(interval) != 2:
        raise ValueError('Incorrect interval format: %s. Interval should specify two values: [min, max] or (min, max).' % interval_str)
    start_item = interval[0].strip()
    if <MASK>:
        raise ValueError("Invalid first item in interval: '%s'" % start_item)
    end_item = interval[1].strip()
    if not _NUMBER_PATTERN.match(end_item):
        raise ValueError("Invalid second item in interval: '%s'" % end_item)
    return Interval(start=start_item, start_included=interval_str[0] == '[', end=end_item, end_included=interval_str[-1] == ']')

def _calculate_permutation_scores(estimator, X, y, sample_weight, col_idx, random_state, n_repeats, scorer, max_samples):
    """Calculate score when `col_idx` is permuted."""
    random_state = check_random_state(random_state)
    if max_samples < X.shape[0]:
        row_indices = _generate_indices(random_state=random_state, bootstrap=False, n_population=X.shape[0], n_samples=max_samples)
        X_permuted = _safe_indexing(X, row_indices, axis=0)
        y = _safe_indexing(y, row_indices, axis=0)
        if sample_weight is not None:
            sample_weight = _safe_indexing(sample_weight, row_indices, axis=0)
    else:
        X_permuted = X.copy()
    scores = []
    shuffling_idx = np.arange(X_permuted.shape[0])
    for _ in range(n_repeats):
        random_state.shuffle(shuffling_idx)
        if <MASK>:
            col = X_permuted.iloc[shuffling_idx, col_idx]
            col.index = X_permuted.index
            X_permuted[X_permuted.columns[col_idx]] = col
        else:
            X_permuted[:, col_idx] = X_permuted[shuffling_idx, col_idx]
        scores.append(_weights_scorer(scorer, estimator, X_permuted, y, sample_weight))
    if isinstance(scores[0], dict):
        scores = _aggregate_score_dicts(scores)
    else:
        scores = np.array(scores)
    return scores

def ndarrays_to_tensors(*inputs):
    """Convert all ndarrays from `inputs` to tensors. (other things are intact)"""
    from ._ndarray import ndarray
    if len(inputs) == 0:
        return ValueError()
    elif len(inputs) == 1:
        input_ = inputs[0]
        if isinstance(input_, ndarray):
            return input_.tensor
        elif <MASK>:
            result = []
            for sub_input in input_:
                sub_result = ndarrays_to_tensors(sub_input)
                result.append(sub_result)
            return tuple(result)
        else:
            return input_
    else:
        assert isinstance(inputs, tuple)
        return ndarrays_to_tensors(inputs)

def match(self, other: 'Op') -> MatchInfo:
    if self.type == 'send':
        return MatchInfo(MatchState.FULLY_MATCHED) if other.type == 'recv' and self.src == other.src and (self.dst == other.dst) and (self.input_sizes == other.output_sizes) else MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH)
    elif <MASK>:
        return MatchInfo(MatchState.FULLY_MATCHED) if other.type == 'send' and self.src == other.src and (self.dst == other.dst) and (self.output_sizes == other.input_sizes) else MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH)
    elif self.type in COLLECTIVES:
        if self.type != other.type:
            return MatchInfo(MatchState.COLLECTIVE_TYPE_MISMATCH, f"Expected collective type: '{self.type}' does not match found collective type: '{other.type}'")
        if self.type not in ['all_to_all', 'scatter'] and self.input_sizes != other.input_sizes:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Expected input sizes: '{self.input_sizes}' does not match found input sizes: '{other.input_sizes}'")
        if self.type not in ['all_to_all', 'gather'] and self.output_sizes != other.output_sizes:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Expected output sizes: '{self.output_sizes}' does not match found output sizes: '{other.output_sizes}'")
        if self.type in ['all_reduce', 'allreduce_coalesced'] and self.input_sizes != other.output_sizes:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Expected input sizes: '{self.input_sizes}' does not match found output sizes: '{other.output_sizes}'")
        if self.type in ['all_gather', 'all_gather_base', 'all_gather_into_tensor_coalesced'] and math.prod(other.output_sizes[0]) != math.prod(self.input_sizes[0]) * self.pg_size:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Found input numel '{math.prod(other.input_sizes[0])} * pg size {self.pg_size}' does not match output numel '{math.prod(other.output_sizes[0])}'")
        if self.type in ['reduce_scatter', '_reduce_scatter_base', 'reduce_scatter_tensor_coalesced'] and math.prod(other.input_sizes[0]) != math.prod(self.output_sizes[0]) * self.pg_size:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Found input numel '{math.prod(other.input_sizes[0])}' does not match output numel '{math.prod(other.output_sizes[0])} * pg size {self.pg_size}'")
        if self.dtype_mismatch(other):
            return MatchInfo(MatchState.COLLECTIVE_DTYPE_MISMATCH, f"Expected dtypes: '{set(self.input_dtypes)}' does not match found dtype: '{set(self.output_dtypes)}/{set(other.input_dtypes)}/{set(other.output_dtypes)}'")
        if self.state != other.state:
            return MatchInfo(MatchState.COLLECTIVE_STATE_MISMATCH, f"Expected state: '{self.state}' does not match found state: '{other.state}'")
        if self.type == 'all_to_all':
            return MatchInfo(MatchState.UNDECIDED)
    elif self.type in ['coalesced', 'ALLGATHER_coalesced', 'REDUCE_SCATTER_coalesced']:
        return MatchInfo(MatchState.FULLY_MATCHED) if other.type == self.type else MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH)
    return MatchInfo(MatchState.FULLY_MATCHED)

def _call_end_hook(self, mode):
    """Helper function for on_{train|test|predict}_end methods."""
    if <MASK>:
        self.on_train_end()
    elif mode == ModeKeys.TEST:
        self.on_test_end()
    else:
        self.on_predict_end()

def create_local_plan(self) -> SavePlan:
    plan = create_default_local_save_plan(self.state_dict, self.is_coordinator)
    if self.flatten_state_dict:
        plan = dataclasses.replace(plan, planner_data=self.mappings)
    self.plan = plan
    if <MASK>:
        if self._cached_plans_key in SavePlanner._cached_save_plan and _compare_save_plans(plan, SavePlanner._cached_save_plan[self._cached_plans_key]):
            logger.info('No change in the local plan. Skipping sending the plan to the coordinator')
            return SavePlan([], usable=False)
        else:
            SavePlanner._cached_save_plan[self._cached_plans_key] = plan
    return self.plan

@compatibility(is_backward_compatible=False)
def reset_grad_fn_seq_nr():
    global current_meta
    if <MASK>:
        current_level = current_meta.get('in_grad_fn', 0)
        assert current_level > 0
        if current_level == 1:
            del current_meta['in_grad_fn']
            del current_meta['grad_fn_seq_nr']
        else:
            current_meta['in_grad_fn'] = current_level - 1
            current_meta['grad_fn_seq_nr'] = current_meta['grad_fn_seq_nr'][:-1]

def DISABLED_testFromGeneratorsRunningInParallel(self):
    self.skipTest('b/67868766')
    num_parallel_iterators = 3
    lock = threading.Lock()
    condition = threading.Condition(lock)
    next_ticket = [0]

    def generator():
        yield 0
        condition.acquire()
        ticket = next_ticket[0]
        next_ticket[0] += 1
        if <MASK>:
            condition.notify_all()
        else:
            while next_ticket[0] < num_parallel_iterators:
                condition.wait()
        condition.release()
        yield 1

    def interleave_fn(_):
        return dataset_ops.Dataset.from_generator(generator, output_types=dtypes.int64, output_shapes=[]).prefetch(2)
    dataset = dataset_ops.Dataset.range(num_parallel_iterators).interleave(interleave_fn, cycle_length=num_parallel_iterators, block_length=1)
    get_next = self.getNext(dataset)
    for elem in [0, 1]:
        for _ in range(num_parallel_iterators):
            self.assertAllEqual(elem, self.evaluate(get_next()))
    with self.assertRaises(errors.OutOfRangeError):
        self.evaluate(get_next())

def record(fn: Callable[_P, _R], error_handler: Optional[ErrorHandler]=None) -> Callable[_P, Union[_R, None]]:
    """
    Syntactic sugar to record errors/exceptions that happened in the decorated
    function using the provided ``error_handler``.

    Using this decorator is equivalent to:

    ::

     error_handler = get_error_handler()
     error_handler.initialize()
     try:
         foobar()
     except ChildFailedError as e:
         _, failure = e.get_first_failure()
         error_handler.dump_error_file(failure.error_file, failure.exitcode)
         raise
     except Exception as e:
         error_handler.record_exception(e)
         raise

    .. important:: use this decorator once per process at the top level method,
                   typically this is the main method.

    Example

    ::

     @record
     def main():
         pass


     if __name__ == "__main__":
         main()

    """
    if not error_handler:
        error_handler = get_error_handler()

    def wrap(f: Callable[_P, _R]) -> Callable[_P, Union[_R, None]]:

        @wraps(f)
        def wrapper(*args: _P.args, **kwargs: _P.kwargs):
            assert error_handler is not None
            error_handler.initialize()
            try:
                return f(*args, **kwargs)
            except SystemExit as se:
                if <MASK>:
                    return None
                else:
                    raise
            except ChildFailedError as e:
                (rank, failure) = e.get_first_failure()
                if failure.error_file != _NOT_AVAILABLE:
                    error_handler.dump_error_file(failure.error_file, failure.exitcode)
                else:
                    logger.info(('local_rank %s FAILED with no error file. Decorate your entrypoint fn with @record for traceback info. See: https://pytorch.org/docs/stable/elastic/errors.html', rank))
                raise
            except Exception as e:
                error_handler.record_exception(e)
                raise
        return wrapper
    return wrap(fn)

def dictappend(rd, ar):
    if <MASK>:
        for a in ar:
            rd = dictappend(rd, a)
        return rd
    for k in ar.keys():
        if k[0] == '_':
            continue
        if k in rd:
            if isinstance(rd[k], str):
                rd[k] = [rd[k]]
            if isinstance(rd[k], list):
                if isinstance(ar[k], list):
                    rd[k] = rd[k] + ar[k]
                else:
                    rd[k].append(ar[k])
            elif isinstance(rd[k], dict):
                if isinstance(ar[k], dict):
                    if k == 'separatorsfor':
                        for k1 in ar[k].keys():
                            if k1 not in rd[k]:
                                rd[k][k1] = ar[k][k1]
                    else:
                        rd[k] = dictappend(rd[k], ar[k])
        else:
            rd[k] = ar[k]
    return rd

def _register_dead_handle(self, handle):
    tensors_to_delete = None
    with self._delete_lock:
        self._dead_handles.append(handle)
        if len(self._dead_handles) == BaseSession._DEAD_HANDLES_THRESHOLD:
            tensors_to_delete = self._dead_handles
            self._dead_handles = []
    if <MASK>:
        feeds = {}
        fetches = []
        for (deleter_key, tensor_handle) in enumerate(tensors_to_delete):
            (holder, deleter) = session_ops._get_handle_deleter(self.graph, deleter_key, tensor_handle)
            feeds[holder] = tensor_handle
            fetches.append(deleter)
        self.run(fetches, feed_dict=feeds)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    """
        Fit the OrdinalEncoder to X.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            The data to determine the categories of each feature.

        y : None
            Ignored. This parameter exists only for compatibility with
            :class:`~sklearn.pipeline.Pipeline`.

        Returns
        -------
        self : object
            Fitted encoder.
        """
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif self.unknown_value is not None:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if self._infrequent_enabled:
        for (feature_idx, infrequent) in enumerate(self.infrequent_categories_):
            if infrequent is not None:
                cardinalities[feature_idx] -= len(infrequent)
    for (cat_idx, categories_for_idx) in enumerate(self.categories_):
        if <MASK>:
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for (cat_idx, cardinality) in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

def expr_fits_within_32bit(e: sympy.Expr) -> bool:
    from .virtualized import V
    int_max = torch.iinfo(torch.int32).max
    size_hint = V.graph.sizevars.size_hint
    has_hint = V.graph.sizevars.shape_env.has_hint
    if V.graph.sizevars.statically_known_true(e <= int_max):
        return True
    if <MASK>:
        if V.graph.sizevars.statically_known_true(e < 1e+20):
            return False
    return has_hint(e) and size_hint(e) <= int_max

def map_array(arr: ArrayLike, mapper, na_action: Literal['ignore'] | None=None) -> np.ndarray | ExtensionArray | Index:
    """
    Map values using an input mapping or function.

    Parameters
    ----------
    mapper : function, dict, or Series
        Mapping correspondence.
    na_action : {None, 'ignore'}, default None
        If 'ignore', propagate NA values, without passing them to the
        mapping correspondence.

    Returns
    -------
    Union[ndarray, Index, ExtensionArray]
        The output of the mapping function applied to the array.
        If the function returns a tuple with more than one element
        a MultiIndex will be returned.
    """
    from pandas import Index
    if na_action not in (None, 'ignore'):
        msg = f"na_action must either be 'ignore' or None, {na_action} was passed"
        raise ValueError(msg)
    if is_dict_like(mapper):
        if <MASK>:
            dict_with_default = mapper
            mapper = lambda x: dict_with_default[np.nan if isinstance(x, float) and np.isnan(x) else x]
        else:
            from pandas import Series
            if len(mapper) == 0:
                mapper = Series(mapper, dtype=np.float64)
            elif isinstance(mapper, dict):
                mapper = Series(mapper.values(), index=Index(mapper.keys(), tupleize_cols=False))
            else:
                mapper = Series(mapper)
    if isinstance(mapper, ABCSeries):
        if na_action == 'ignore':
            mapper = mapper[mapper.index.notna()]
        indexer = mapper.index.get_indexer(arr)
        new_values = take_nd(mapper._values, indexer)
        return new_values
    if not len(arr):
        return arr.copy()
    values = arr.astype(object, copy=False)
    if na_action is None:
        return lib.map_infer(values, mapper)
    else:
        return lib.map_infer_mask(values, mapper, mask=isna(values).view(np.uint8))

def _get_collective_to_overlappable_nodes(graph: torch.fx.Graph) -> dict[torch.fx.Node, list[torch.fx.Node]]:
    """
    For each collective in the graph, find nodes that are neither ancestors nor
    descendants of the collective.
    """

    def is_collective(node) -> bool:
        return node.target in [torch.ops._c10d_functional.all_gather_into_tensor.default, torch.ops._c10d_functional.reduce_scatter_tensor.default]
    node_to_ancestors = _get_node_to_ancestors(graph)
    collective_to_overlappable_nodes = defaultdict(list)
    for node in graph.nodes:
        if not is_collective(node):
            continue
        for x in graph.nodes:
            if <MASK>:
                collective_to_overlappable_nodes[node].append(x)
    return collective_to_overlappable_nodes

def bsr_dense_addmm_meta(M, K, N, Ms, Ks, beta, alpha, SPLIT_N=None, GROUP_SIZE_ROW=None, num_warps=None, num_stages=None, sparsity=None, dtype=None, out_dtype=None, _version=0, **extra):
    if dtype is None:
        dtype = torch.float16
    if out_dtype is None:
        out_dtype = dtype
    if sparsity is None:
        sparsity = 0.5
    if <MASK>:
        device_name = torch.cuda.get_device_name()
        key = (M, K, N, Ms, Ks, beta == 0, beta == 1, alpha == 1)
        if dtype is out_dtype:
            version_dtype = dtype
        else:
            version_dtype = (dtype, out_dtype)
        meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, version_dtype, sparsity))
        if meta is None and sparsity != 0.5:
            meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, version_dtype, 0.5))
        if meta is None and dtype is not out_dtype:
            meta = get_meta('bsr_dense_addmm', key, device_name, version=(_version, dtype, 0.5))
        if meta is None:
            matching_meta = get_meta('bsr_dense_addmm', (*key[:2], '*', *key[3:]), device_name, version=(_version, version_dtype, 0.5))
            if matching_meta is None and dtype is not out_dtype:
                matching_meta = get_meta('bsr_dense_addmm', (*key[:2], '*', *key[3:]), device_name, version=(_version, dtype, 0.5))
            for mkey in sorted(matching_meta or {}):
                meta_ = matching_meta[mkey]
                n = mkey[2]
                split_n = meta_['SPLIT_N']
                c = n // split_n
                if N % c == 0 and n <= N:
                    meta = dict(meta_)
                    meta['SPLIT_N'] = N // c
        if meta is not None:
            meta.update(**extra)
            return meta
        else:
            warn_once(f'bsr_dense_addmm uses non-optimal triton kernel parameters for M={M!r} K={K!r} N={N!r} Ms={Ms!r}, Ks={Ks!r} beta={beta!r} alpha={alpha!r} dtype={dtype!r} out_dtype={out_dtype!r}')
    SPLIT_N = SPLIT_N or max(N // Ms, 1)
    GROUP_SIZE_ROW = GROUP_SIZE_ROW or 4
    num_stages = num_stages or 1
    num_warps = num_warps or 4
    return dict(SPLIT_N=SPLIT_N, GROUP_SIZE_ROW=GROUP_SIZE_ROW, num_stages=num_stages, num_warps=num_warps, **extra)

def _get_bin_edges(a, bins, range, weights):
    """
    Computes the bins used internally by `histogram`.

    Parameters
    ==========
    a : ndarray
        Ravelled data array
    bins, range
        Forwarded arguments from `histogram`.
    weights : ndarray, optional
        Ravelled weights array, or None

    Returns
    =======
    bin_edges : ndarray
        Array of bin edges
    uniform_bins : (Number, Number, int):
        The upper bound, lowerbound, and number of bins, used in the optimized
        implementation of `histogram` that works on uniform bins.
    """
    n_equal_bins = None
    bin_edges = None
    if isinstance(bins, str):
        bin_name = bins
        if bin_name not in _hist_bin_selectors:
            raise ValueError(f'{bin_name!r} is not a valid estimator for `bins`')
        if weights is not None:
            raise TypeError('Automated estimation of the number of bins is not supported for weighted data')
        (first_edge, last_edge) = _get_outer_edges(a, range)
        if range is not None:
            keep = a >= first_edge
            keep &= a <= last_edge
            if not np.logical_and.reduce(keep):
                a = a[keep]
        if a.size == 0:
            n_equal_bins = 1
        else:
            width = _hist_bin_selectors[bin_name](a, (first_edge, last_edge))
            if width:
                if <MASK>:
                    width = 1
                delta = _unsigned_subtract(last_edge, first_edge)
                n_equal_bins = int(np.ceil(delta / width))
            else:
                n_equal_bins = 1
    elif np.ndim(bins) == 0:
        try:
            n_equal_bins = operator.index(bins)
        except TypeError as e:
            raise TypeError('`bins` must be an integer, a string, or an array') from e
        if n_equal_bins < 1:
            raise ValueError('`bins` must be positive, when an integer')
        (first_edge, last_edge) = _get_outer_edges(a, range)
    elif np.ndim(bins) == 1:
        bin_edges = np.asarray(bins)
        if np.any(bin_edges[:-1] > bin_edges[1:]):
            raise ValueError('`bins` must increase monotonically, when an array')
    else:
        raise ValueError('`bins` must be 1d, when an array')
    if n_equal_bins is not None:
        bin_type = np.result_type(first_edge, last_edge, a)
        if np.issubdtype(bin_type, np.integer):
            bin_type = np.result_type(bin_type, float)
        bin_edges = np.linspace(first_edge, last_edge, n_equal_bins + 1, endpoint=True, dtype=bin_type)
        if np.any(bin_edges[:-1] >= bin_edges[1:]):
            raise ValueError(f'Too many bins for data range. Cannot create {n_equal_bins} finite-sized bins.')
        return (bin_edges, (first_edge, last_edge, n_equal_bins))
    else:
        return (bin_edges, None)

def _move_states_to_device(params: list[nn.Parameter], buffers: list[torch.Tensor], device_from_device_id: Optional[torch.device]) -> None:
    """
    Move states to the specified device.

    Precondition: ``_check_single_device_module()`` and module's parameters and
    buffers have been materialized if needed.
    """
    if len(params) == 0 and len(buffers) == 0:
        return
    if len(params) > 0:
        current_device = params[0].device
    elif <MASK>:
        current_device = buffers[0].device
    cpu_device = torch.device('cpu')
    if device_from_device_id is not None:
        for param in params:
            with torch.no_grad():
                param.data = param.to(device_from_device_id)
                if param.grad is not None:
                    param.grad.data = param.grad.to(device_from_device_id)
        for buffer in buffers:
            buffer.data = buffer.to(device_from_device_id)
    elif current_device == cpu_device:
        _warn_cpu_init()

def _replace_literals_with_existing_placeholders(gm: torch.fx.GraphModule, exclude_literals: Optional[list[Any]]=None, literal_to_ph_idx: Optional[dict[Union[float, int, bool, torch.dtype], int]]=None):
    """Replace the literals in the graph with **existing** placeholder nodes, so that the literal arguments
    in the graph can be matched and replaced

    To use this, all literal args in the graph should be unique and each of them should correspond
    to exactly one placeholder node

    # 1. Original Graph
    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        return torch.dequantize_per_tensor(x_i8, scale, zero_point, quant_min, quant_max)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        x_i8 = torch.clamp(x_i8, quant_min, quant_max)
        return ((x_i8.to(torch.float32) - zero_point) * scale).to(dtype=torch.float32)

    example_inputs = (
        torch.randn(1, 3, 3, 3),
        1.0,
        0,
        -128,
        127,
    )
    pattern_gm = _get_aten_graph_module_for_pattern(pattern, example_inputs)
    replacement_gm = _get_aten_graph_module_for_pattern(pattern, example_inptus)

    # 2. Before calling replace literals we'll see the following graph:
    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        return torch.dequantize_per_tensor(x_i8, 1.0, 0, -128, 127)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        x_i8 = torch.clamp(x_i8, -128, 127)
        return ((x_i8.to(torch.float32) - 0) * 1.0).to(dtype=torch.float32)

    # Note that literal args appear in different order in pattern and replacement graph, so
    # we can't use _replace_literals_with_new_placeholders

    literal_to_ph_idx = {1.0: 1, 0: 2, -128: 3, 127: 4}
    pattern_gm = _replace_literals_with_existing_placeholders(pattern_gm, literal_to_ph_idx)
    replacement_gm = _replace_literals_with_existing_placeholders(replacement_gm, literal_to_ph_idx)

    # 3. After replacing literals with existing placeholder nodes

    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        return torch.dequantize_per_tensor(x_i8, scale, zero_point, quant_min, quant_max)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        x_i8 = torch.clamp(x_i8, quant_min, quant_max)
        return ((x_i8.to(torch.float32) - zero_point) * scale).to(dtype=torch.float32)
    """
    if exclude_literals is None:
        exclude_literals = []
    if literal_to_ph_idx is None:
        literal_to_ph_idx = {}
    phs = [node for node in gm.graph.nodes if node.op == 'placeholder']
    for node in gm.graph.nodes:
        if <MASK>:
            continue
        new_args = []
        for arg in node.args:
            if _is_literal(arg) and arg not in exclude_literals and (arg in literal_to_ph_idx):
                ph_idx = literal_to_ph_idx[arg]
                ph_node = phs[ph_idx]
                new_args.append(ph_node)
            else:
                new_args.append(arg)
        new_args = tuple(new_args)
        node.args = new_args
    return gm

def _get_var_info(var, prev_tensor_name=None):
    """Helper method for standarizing Variable and naming.

  Args:
    var: Current graph's variable that needs to be warm-started (initialized).
      Can be either of the following: (i) `Variable` (ii) `ResourceVariable`
      (iii) list of `Variable`: The list must contain slices of the same larger
        variable. (iv) `PartitionedVariable`
    prev_tensor_name: Name of the tensor to lookup in provided `prev_ckpt`. If
      None, we lookup tensor with same name as given `var`.

  Returns:
    A tuple of the Tensor name and var.
  """
    if checkpoint_utils._is_variable(var):
        current_var_name = _infer_var_name([var])
    elif isinstance(var, list) and all((checkpoint_utils._is_variable(v) for v in var)):
        current_var_name = _infer_var_name(var)
    elif <MASK>:
        current_var_name = _infer_var_name([var])
        var = var._get_variable_list()
    else:
        raise TypeError('var MUST be one of the following: a Variable, list of Variable or PartitionedVariable, but is {}'.format(type(var)))
    if not prev_tensor_name:
        prev_tensor_name = current_var_name
    return (prev_tensor_name, var)

def _get_m2m_attr(self, related, attr):
    """
        Function that can be curried to provide the source accessor or DB
        column name for the m2m table.
        """
    cache_attr = '_m2m_%s_cache' % attr
    if <MASK>:
        return getattr(self, cache_attr)
    if self.remote_field.through_fields is not None:
        link_field_name = self.remote_field.through_fields[0]
    else:
        link_field_name = None
    for f in self.remote_field.through._meta.fields:
        if f.is_relation and f.remote_field.model == related.related_model and (link_field_name is None or link_field_name == f.name):
            setattr(self, cache_attr, getattr(f, attr))
            return getattr(self, cache_attr)

def _as_spec_tuple(slice_spec):
    """Convert slice_spec to tuple."""
    if isinstance(slice_spec, (list, tuple)) and (not isinstance(slice_spec, np.ndarray)):
        is_index = True
        for s in slice_spec:
            if s is None or s is Ellipsis or isinstance(s, (list, tuple, slice)):
                is_index = False
                break
            elif <MASK>:
                is_index = False
                break
        if not is_index:
            return tuple(slice_spec)
    return (slice_spec,)

def _transform_feature(self, inputs):
    feature_tensors = []
    for key in _collect_leaf_level_keys(self):
        if isinstance(key, six.string_types):
            feature_tensors.append(inputs.get(key))
        elif <MASK>:
            ids_and_weights = key._get_sparse_tensors(inputs)
            if ids_and_weights.weight_tensor is not None:
                raise ValueError('crossed_column does not support weight_tensor, but the given column populates weight_tensor. Given column: {}'.format(key.name))
            feature_tensors.append(ids_and_weights.id_tensor)
        else:
            raise ValueError('Unsupported column type. Given: {}'.format(key))
    return sparse_ops.sparse_cross_hashed(inputs=feature_tensors, num_buckets=self.hash_bucket_size, hash_key=self.hash_key)

def call_method(self, tx: 'InstructionTranslator', name: str, args: list[VariableTracker], kwargs: dict[str, VariableTracker]) -> 'VariableTracker':
    assert hasattr(self.value, name), f'no stream method found named {name}'
    from ..utils import cmp_name_to_op_mapping, proxy_args_kwargs
    from .builder import wrap_fx_proxy_cls
    if name in ('wait_stream', 'synchronize', 'wait_event'):
        tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self] + args, kwargs))
        return ConstantVariable(None)
    elif name == 'query':
        return wrap_fx_proxy_cls(target_cls=ConstantVariable, tx=tx, proxy=tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self] + args, kwargs)))
    elif name == 'record_event':
        return wrap_fx_proxy_cls(target_cls=EventVariable, tx=tx, proxy=tx.output.create_proxy('call_method', name, *proxy_args_kwargs([self] + args, kwargs)))
    elif name in cmp_name_to_op_mapping and len(args) == 1 and (not kwargs):
        from ..guards import GuardBuilder, install_guard
        if self.source:
            install_guard(self.source.make_guard(GuardBuilder.EQUALS_MATCH))
        other = args[0]
        if <MASK>:
            return ConstantVariable.create(NotImplemented)
        if other.source:
            install_guard(self.source.make_guard(GuardBuilder.EQUALS_MATCH))
        return ConstantVariable.create(cmp_name_to_op_mapping[name](self.value, other.value))
    return super().call_method(tx, name, args, kwargs)

def _quantize(self, result, input_type, output_type, activations_type, bias_type, allow_float, enable_variable_quantization, debug_options):
    """Quantize the model."""
    custom_op_registerers_by_name = [x for x in self.target_spec._experimental_custom_op_registerers if isinstance(x, str)]
    custom_op_registerers_by_func = [x for x in self.target_spec._experimental_custom_op_registerers if not isinstance(x, str)]
    if not isinstance(self.representative_dataset, RepresentativeDataset):
        self.representative_dataset = RepresentativeDataset(self.representative_dataset)
    result = _calibrator.add_intermediate_tensors(result)
    calibrate_quantize = _calibrator.Calibrator(result, custom_op_registerers_by_name, custom_op_registerers_by_func)
    if self._experimental_calibrate_only or self.experimental_new_quantizer:
        calibrated = calibrate_quantize.calibrate(self.representative_dataset.input_gen)
    if <MASK>:
        return calibrated
    elif self.experimental_new_quantizer and activations_type != _dtypes.int16:
        return _mlir_quantize(calibrated, self._experimental_disable_per_channel, input_data_type=input_type, output_data_type=output_type, enable_variable_quantization=enable_variable_quantization, disable_per_channel_for_dense_layers=self._experimental_disable_per_channel_quantization_for_dense_layers, debug_options_str=debug_options.SerializeToString())
    else:
        return calibrate_quantize.calibrate_and_quantize(self.representative_dataset.input_gen, input_type, output_type, allow_float, activations_type, bias_type, disable_per_channel=self._experimental_disable_per_channel, disable_per_channel_quantization_for_dense_layers=self._experimental_disable_per_channel_quantization_for_dense_layers)

def _ext_pre_load_state_dict_transform(tensor: torch.Tensor, fsdp_extension: Optional[FSDPExtensions]=None) -> tuple[torch.Tensor, list[Shard]]:
    if <MASK>:
        return fsdp_extension.pre_load_state_dict_transform(tensor)
    if type(tensor) is not ShardedTensor:
        raise AssertionError(f'Expected ShardedTensor, got {type(tensor)}')
    shards = tensor.local_shards()
    return (tensor, shards)

def put_code_state() -> None:
    if _CODE_STATE is None:
        log.info('put_code_state: never initialized, will not write')
        return
    if _CODE_STATE == _INIT_CODE_STATE:
        log.info('put_code_state: no change, skipping')
        return
    cache_key = get_cache_key()
    if <MASK>:
        log.info('put_code_state: no cache key, skipping')
        return
    put_local_code_state(cache_key)
    put_remote_code_state(cache_key)
    if (sticky_write := torch.compiler.config.pgo_extra_write_key) is not None:
        extra_write_key = get_extra_cache_key(sticky_write)
        if extra_write_key is not None:
            put_remote_code_state(extra_write_key)

