    else:
        sizes = [None] * len(params_list[0])
        for params in params_list:
            for (i, value) in enumerate(params):
                if value.input_size:
                    sizes[i] = value.input_size
        if sizes:
            self.setinputsizes(*sizes)

@compatibility(is_backward_compatible=False)
def is_consistent(t1, t2):
    """
    A binary relation denoted by ~ that determines if t1 is consistent with t2.
    The relation is reflexive, symmetric but not transitive.
    returns True if t1 and t2 are consistent and False otherwise.
    Example:
        Dyn ~ TensorType((1,2,3))
        int ~ Dyn
        int ~ int
        TensorType((1,Dyn,3)) ~ TensorType((1,2,3))
    """
    if t1 == t2:
        return True
    if <MASK>:
        return True
    if isinstance(t1, TensorType) and isinstance(t2, TensorType):
        return len(t1.__args__) == len(t2.__args__) and all((is_consistent(elem1, elem2) for (elem1, elem2) in zip(t1.__args__, t2.__args__)))
    else:
        return False

@parameterized.named_parameters(('NoTensor', 'NO_TENSOR'), ('CurtHealth', 'CURT_HEALTH'), ('ConciseHealth', 'CONCISE_HEALTH'), ('FullHealth', 'FULL_HEALTH'), ('Shape', 'SHAPE'), ('FullTensor', 'FULL_TENSOR'))
def testMultiThreadedExecutionWithSameSetting(self, tensor_debug_mode):
    """Dumping from multiple threads using the same setting."""
    writer = dumping_callback.enable_dump_debug_info(self.dump_root, tensor_debug_mode=tensor_debug_mode)
    x = variables.Variable(10.0, dtype=dtypes.float32)
    y = variables.Variable(3.0, dtype=dtypes.float32)

    @def_function.function
    def increase_x():
        return x.assign_add(y * 2.0)
    increase_x()
    num_threads = 3
    threads = []
    for _ in range(num_threads):
        threads.append(threading.Thread(target=increase_x))
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    self.assertAllClose(x.read_value(), 34.0)
    writer.FlushNonExecutionFiles()
    writer.FlushExecutionFiles()
    with debug_events_reader.DebugDataReader(self.dump_root) as reader:
        reader.update()
        exec_digests = reader.executions(digest=True)
        prev_wall_time = 1
        for exec_digest in exec_digests:
            self.assertGreaterEqual(exec_digest.wall_time, prev_wall_time)
            prev_wall_time = exec_digest.wall_time
        graph_exec_traces = reader.graph_execution_traces()
        executed_op_types = [trace.op_type for trace in graph_exec_traces]
        self.assertEqual(executed_op_types.count('Mul'), 1 + num_threads)
        self.assertEqual(executed_op_types.count('ReadVariableOp'), 2 * (1 + num_threads))
        for trace in graph_exec_traces:
            self.assertEqual(trace.output_slot, 0)
    tensor_values = [reader.graph_execution_trace_to_tensor_value(trace) for trace in graph_exec_traces]
    if tensor_debug_mode == 'NO_TENSOR':
        for tensor_value in tensor_values:
            self.assertAllEqual(tensor_value, [])
    elif <MASK>:
        for trace in graph_exec_traces:
            tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
            self.assertAllClose(trace.debug_tensor_value, [tensor_id, 0])
    elif tensor_debug_mode == 'CONCISE_HEALTH':
        for trace in graph_exec_traces:
            tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
            self.assertAllClose(trace.debug_tensor_value, [tensor_id, 1, 0, 0, 0])
    elif tensor_debug_mode == 'FULL_HEALTH':
        for trace in graph_exec_traces:
            tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
            self.assertAllClose(trace.debug_tensor_value, [tensor_id, -1, 1, 0, 1, 0, 0, 0, 0, 0, 1])
    elif tensor_debug_mode == 'SHAPE':
        for trace in graph_exec_traces:
            if trace.op_type == 'Mul':
                tensor_id = reader.graph_execution_trace_to_tensor_id(trace)
                mul_value = reader.graph_execution_trace_to_tensor_value(trace)
                self.assertAllClose(mul_value, [tensor_id, 1, 0, 1, 0, 0, 0, 0, 0, 0])
    elif tensor_debug_mode == 'FULL_TENSOR':
        mul_values = [reader.graph_execution_trace_to_tensor_value(trace) for trace in graph_exec_traces if trace.op_type == 'Mul']
        self.assertAllClose(mul_values, [6.0, 6.0, 6.0, 6.0])

def set_logical_devices_to_at_least(device, num):
    """Create logical devices of at least a given number."""
    if num < 1:
        raise ValueError('`num` must be at least 1 not %r' % (num,))
    physical_devices = config.list_physical_devices(device)
    if not physical_devices:
        raise RuntimeError('No {} found'.format(device))
    if <MASK>:
        return
    num = num - len(physical_devices) + 1
    logical_devices = []
    for _ in range(num):
        if device.upper() == 'GPU':
            logical_devices.append(context.LogicalDeviceConfiguration(memory_limit=2048))
        else:
            logical_devices.append(context.LogicalDeviceConfiguration())
    config.set_logical_device_configuration(physical_devices[-1], logical_devices)

def _compute_stride(old_shape, old_stride, new_shape, size_oblivious=False):
    from torch.fx.experimental.symbolic_shapes import guard_or_false, guard_or_true, sym_eq

    def maybe_guard_or_false(x):
        if <MASK>:
            return guard_or_false(x)
        return x

    def maybe_guard_or_true(x):
        if size_oblivious:
            return guard_or_true(x)
        return x
    if len(old_shape) == 0:
        return [1] * len(new_shape)
    numel = reduce(operator.mul, old_shape, 1)
    zero_numel = maybe_guard_or_false(numel == 0)
    if zero_numel and maybe_guard_or_false(sym_eq(old_shape, new_shape)):
        return old_stride
    new_stride = [0] * len(new_shape)
    if zero_numel:
        for view_d in range(len(new_shape) - 1, -1, -1):
            if view_d == len(new_shape) - 1:
                new_stride[view_d] = 1
            else:
                new_stride[view_d] = max(new_shape[view_d + 1], 1) * new_stride[view_d + 1]
        return new_stride
    view_d = len(new_shape) - 1
    chunk_base_stride = old_stride[-1]
    tensor_numel = 1
    view_numel = 1
    for tensor_d in range(len(old_shape) - 1, -1, -1):
        tensor_numel *= old_shape[tensor_d]
        if tensor_d == 0 or (maybe_guard_or_true(old_shape[tensor_d - 1] != 1) and maybe_guard_or_true(old_stride[tensor_d - 1] != tensor_numel * chunk_base_stride)):
            while view_d >= 0 and (maybe_guard_or_true(view_numel < tensor_numel) or maybe_guard_or_false(new_shape[view_d] == 1)):
                new_stride[view_d] = view_numel * chunk_base_stride
                view_numel *= new_shape[view_d]
                view_d -= 1
            if maybe_guard_or_true(view_numel != tensor_numel):
                return None
            if tensor_d > 0:
                chunk_base_stride = old_stride[tensor_d - 1]
                tensor_numel = 1
                view_numel = 1
    if view_d != -1:
        return None
    return new_stride

def __array_wrap__(self, obj, context=None, return_scalar=False):
    """
        Special hook for ufuncs.

        Wraps the numpy array and sets the mask according to context.

        """
    if obj is self:
        result = obj
    else:
        result = obj.view(type(self))
        result._update_from(self)
    if <MASK>:
        result._mask = result._mask.copy()
        (func, args, out_i) = context
        input_args = args[:func.nin]
        m = functools.reduce(mask_or, [getmaskarray(arg) for arg in input_args])
        domain = ufunc_domain.get(func)
        if domain is not None:
            with np.errstate(divide='ignore', invalid='ignore'):
                d = domain(*input_args).astype(bool, copy=False)
                d = filled(d, True)
            if d.any():
                try:
                    fill_value = ufunc_fills[func][-1]
                except TypeError:
                    fill_value = ufunc_fills[func]
                except KeyError:
                    fill_value = self.fill_value
                np.copyto(result, fill_value, where=d)
                if m is nomask:
                    m = d
                else:
                    m = m | d
        if result is not self and result.shape == () and m:
            return masked
        else:
            result._mask = m
            result._sharedmask = False
    return result

def link(self, target_desc, objects, output_filename, output_dir=None, libraries=None, library_dirs=None, runtime_library_dirs=None, export_symbols=None, debug=0, extra_preargs=None, extra_postargs=None, build_temp=None, target_lang=None):
    (objects, output_dir) = self._fix_object_args(objects, output_dir)
    (libraries, library_dirs, runtime_library_dirs) = self._fix_lib_args(libraries, library_dirs, runtime_library_dirs)
    lib_opts = gen_lib_options(self, library_dirs, runtime_library_dirs, libraries)
    if is_string(output_dir):
        output_filename = os.path.join(output_dir, output_filename)
    elif output_dir is not None:
        raise TypeError("'output_dir' must be a string or None")
    if self._need_link(objects, output_filename):
        if self.library_switch[-1] == ' ':
            o_args = [self.library_switch.strip(), output_filename]
        else:
            o_args = [self.library_switch.strip() + output_filename]
        if is_string(self.objects):
            ld_args = objects + [self.objects]
        else:
            ld_args = objects + self.objects
        ld_args = ld_args + lib_opts + o_args
        if <MASK>:
            ld_args[:0] = ['-g']
        if extra_preargs:
            ld_args[:0] = extra_preargs
        if extra_postargs:
            ld_args.extend(extra_postargs)
        self.mkpath(os.path.dirname(output_filename))
        if target_desc == CCompiler.EXECUTABLE:
            linker = self.linker_exe[:]
        else:
            linker = self.linker_so[:]
        command = linker + ld_args
        try:
            self.spawn(command)
        except DistutilsExecError as e:
            msg = str(e)
            raise LinkError(msg) from None
    else:
        log.debug('skipping %s (up-to-date)', output_filename)

def tf_tensor_array_new(elements, element_dtype=None, element_shape=None):
    """Overload of new_list that stages a Tensor list creation."""
    elements = tuple((ops.convert_to_tensor(el) for el in elements))
    all_dtypes = set((el.dtype for el in elements))
    if len(all_dtypes) == 1:
        (inferred_dtype,) = tuple(all_dtypes)
        if element_dtype is not None and element_dtype != inferred_dtype:
            raise ValueError('incompatible dtype; specified: {}, inferred from {}: {}'.format(element_dtype, elements, inferred_dtype))
    elif len(all_dtypes) > 1:
        raise ValueError('TensorArray requires all elements to have the same dtype: {}'.format(elements))
    elif element_dtype is None:
        raise ValueError('dtype is required to create an empty TensorArray')
    all_shapes = set((tuple(el.shape.as_list()) for el in elements))
    if len(all_shapes) == 1:
        (inferred_shape,) = tuple(all_shapes)
        if element_shape is not None and element_shape != inferred_shape:
            raise ValueError('incompatible shape; specified: {}, inferred from {}: {}'.format(element_shape, elements, inferred_shape))
    elif <MASK>:
        raise ValueError('TensorArray requires all elements to have the same shape: {}'.format(elements))
    else:
        inferred_shape = None
    if element_dtype is None:
        element_dtype = inferred_dtype
    if element_shape is None:
        element_shape = inferred_shape
    l = tensor_array_ops.TensorArray(dtype=element_dtype, size=len(elements), dynamic_size=True, infer_shape=element_shape is None, element_shape=element_shape)
    for (i, el) in enumerate(elements):
        l = l.write(i, el)
    return l

def _filter(self, category=Warning, message='', module=None, record=False):
    if record:
        record = []
    else:
        record = None
    if self._entered:
        if <MASK>:
            warnings.filterwarnings('always', category=category, message=message)
        else:
            module_regex = module.__name__.replace('.', '\\.') + '$'
            warnings.filterwarnings('always', category=category, message=message, module=module_regex)
            self._tmp_modules.add(module)
            self._clear_registries()
        self._tmp_suppressions.append((category, message, re.compile(message, re.I), module, record))
    else:
        self._suppressions.append((category, message, re.compile(message, re.I), module, record))
    return record

def process_response(self, request, response):
    if self.sts_seconds and request.is_secure() and ('Strict-Transport-Security' not in response):
        sts_header = 'max-age=%s' % self.sts_seconds
        if <MASK>:
            sts_header += '; includeSubDomains'
        if self.sts_preload:
            sts_header += '; preload'
        response.headers['Strict-Transport-Security'] = sts_header
    if self.content_type_nosniff:
        response.headers.setdefault('X-Content-Type-Options', 'nosniff')
    if self.referrer_policy:
        response.headers.setdefault('Referrer-Policy', ','.join([v.strip() for v in self.referrer_policy.split(',')] if isinstance(self.referrer_policy, str) else self.referrer_policy))
    if self.cross_origin_opener_policy:
        response.setdefault('Cross-Origin-Opener-Policy', self.cross_origin_opener_policy)
    return response

def unwrap(self, a: Union[Any, IndexPropVar]) -> Any:
    if isinstance(a, (list, tuple)):
        return tuple((self.unwrap(v) for v in a))
    if <MASK>:
        return a
    if a.is_symbolic:
        return self.materialize_expr(a.value.expr, a.value.dtype)
    return a.value

def _step_microbatches(self, arg_mbs: Optional[list]=None, kwarg_mbs: Optional[list]=None, target_mbs: Optional[list]=None, losses: Optional[list]=None, return_outputs: bool=True):
    """
        Operate on the microbatches for looped schedules (multiple stages on each rank).

        TODO: Does not use sorted_batch_isend_irecv(). As a result, this schedule does
        not support models with skip connections.
        """
    (arg_mbs, kwarg_mbs) = self._check_inputs(arg_mbs, kwarg_mbs, target_mbs, losses)
    self._initialize_stages(arg_mbs[0], kwarg_mbs[0])
    stage_index_to_stage: dict[int, _PipelineStageBase] = {stage.stage_index: stage for stage in self._stages}
    all_prev_ranks: set[int] = set()
    all_next_ranks: set[int] = set()
    for stage_index in stage_index_to_stage.keys():
        if stage_index > 0:
            all_prev_ranks.add(self.stage_index_to_group_rank[stage_index - 1])
        if stage_index < self._num_stages - 1:
            all_next_ranks.add(self.stage_index_to_group_rank[stage_index + 1])
    backward_counter: Counter[int] = Counter()
    for (time_step, action) in enumerate(self.pipeline_order[self.rank]):
        try:
            ops: list[dist.P2POp] = []
            if action is not None:
                computation_type = action.computation_type
                mb_index = action.microbatch_index
                stage_index = action.stage_index
                assert mb_index is not None, 'All currently supported action types require valid microbatch_index'
                if computation_type == _ComputationType.FORWARD:
                    stage = stage_index_to_stage[stage_index]
                    output = stage.forward_one_chunk(mb_index, arg_mbs[mb_index], kwarg_mbs[mb_index], save_forward_output=return_outputs)
                    self._maybe_compute_loss(stage, output, target_mbs, mb_index)
                    ops.extend(stage.get_fwd_send_ops(mb_index))
                elif <MASK>:
                    stage = stage_index_to_stage[stage_index]
                    loss = self._maybe_get_loss(stage, mb_index)
                    backward_counter[stage_index] += 1
                    last_backward = backward_counter[stage_index] == self._n_microbatches
                    grad_scale_factor = self._n_microbatches if self.scale_grads else 1
                    stage.backward_one_chunk(mb_index, loss=loss, full_backward=True, last_backward=last_backward)
                    if last_backward:
                        stage.scale_grads(grad_scale_factor)
                    ops.extend(stage.get_bwd_send_ops(mb_index))
                elif computation_type == _ComputationType.BACKWARD_INPUT:
                    stage = stage_index_to_stage[stage_index]
                    loss = self._maybe_get_loss(stage, mb_index)
                    stage.backward_one_chunk(mb_index, loss=loss, full_backward=False, last_backward=False)
                    ops.extend(stage.get_bwd_send_ops(mb_index))
                elif computation_type == _ComputationType.BACKWARD_WEIGHT:
                    stage = stage_index_to_stage[stage_index]
                    backward_counter[stage_index] += 1
                    last_backward = backward_counter[stage_index] == self._n_microbatches
                    grad_scale_factor = self._n_microbatches if self.scale_grads else 1
                    stage.backward_weight_one_chunk(mb_index, last_backward=last_backward)
                    if last_backward:
                        stage.scale_grads(grad_scale_factor)
                else:
                    raise ValueError(f'Unknown computation type {computation_type}')
            for prev_rank in all_prev_ranks:
                prev_rank_ops = self.pipeline_order[prev_rank]
                prev_rank_action = None
                if time_step < len(prev_rank_ops):
                    prev_rank_action = prev_rank_ops[time_step]
                if prev_rank_action is not None:
                    computation_type = prev_rank_action.computation_type
                    mb_index = prev_rank_action.microbatch_index
                    stage_index = prev_rank_action.stage_index
                    assert mb_index is not None, 'All currently supported action types require valid microbatch_index'
                    if computation_type == _ComputationType.FORWARD:
                        if stage_index + 1 in stage_index_to_stage:
                            stage = stage_index_to_stage[stage_index + 1]
                            ops.extend(stage.get_fwd_recv_ops(mb_index))
                    elif computation_type in (FULL_BACKWARD, BACKWARD_INPUT, BACKWARD_WEIGHT):
                        pass
                    else:
                        raise ValueError(f'Unknown computation type {computation_type}')
            for next_rank in all_next_ranks:
                next_rank_ops = self.pipeline_order[next_rank]
                next_rank_action = None
                if time_step < len(next_rank_ops):
                    next_rank_action = next_rank_ops[time_step]
                if next_rank_action is not None:
                    computation_type = next_rank_action.computation_type
                    mb_index = next_rank_action.microbatch_index
                    stage_index = next_rank_action.stage_index
                    assert mb_index is not None, 'All currently supported action types require valid microbatch_index'
                    if computation_type in (FORWARD, BACKWARD_WEIGHT):
                        pass
                    elif computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
                        if stage_index - 1 in stage_index_to_stage:
                            stage = stage_index_to_stage[stage_index - 1]
                            ops.extend(stage.get_bwd_recv_ops(mb_index))
                    else:
                        raise ValueError(f'Unknown computation type {computation_type}')
            _wait_batch_p2p(_batch_p2p(ops))
        except Exception as e:
            logger.error("[Rank %s] pipeline schedule %s caught the following exception '%s' at time_step %s when running action %s", self.rank, self.__class__.__name__, str(e), time_step, action)
            logger.error('%s', _format_pipeline_order(self.pipeline_order, error_step_number=time_step))
            raise e
    self._update_losses(self._stages, losses)

def __init__(self, supported_ops=None, supported_types=None, experimental_select_user_tf_ops=None, experimental_supported_backends=None):
    if supported_ops is None:
        supported_ops = {OpsSet.TFLITE_BUILTINS}
    self.supported_ops = supported_ops
    if supported_types is None:
        supported_types = set()
    self.supported_types = supported_types
    if <MASK>:
        experimental_select_user_tf_ops = set()
    self.experimental_select_user_tf_ops = experimental_select_user_tf_ops
    self.experimental_supported_backends = experimental_supported_backends
    self._experimental_custom_op_registerers = []
    self._experimental_supported_accumulation_type = None

def _convert_fx_arg_to_onnx_arg(arg, node_name_to_values: dict[str, ir.Value | Sequence[ir.Value]], node_name_to_local_functions: dict[str, ir.Function]) -> Any:
    """Convert an FX argument to an ONNX compatible argument.

    This function
    - Converts a torch dtype to an integer
    - Converts a torch device/memory_format/layout to a string
    - Converts a torch.fx.Node to an ir.Value
    - Converts a sequence of torch.fx.Node to a sequence of ir.Value
    - Converts a get_attr node to an ir.Function
    """
    if arg is None:
        return None
    if hasattr(arg, 'name'):
        if isinstance(arg, torch.fx.Node) and arg.target == operator.getitem:
            source = arg.all_input_nodes[0]
            source_outputs = node_name_to_values[source.name]
            if isinstance(source_outputs, Sequence):
                return _handle_getitem_node(arg, node_name_to_values)
            else:
                pass
        if isinstance(arg, torch.fx.Node) and arg.op == 'get_attr':
            return node_name_to_local_functions[arg.name]
        return node_name_to_values[arg.name]
    if <MASK>:
        return [_convert_fx_arg_to_onnx_arg(elem, node_name_to_values, node_name_to_local_functions) for elem in arg]
    if isinstance(arg, (torch.device, torch.memory_format, torch.layout)):
        return str(arg)
    if isinstance(arg, torch.dtype):
        return torch_dtype_to_onnx_dtype(arg)
    return arg

@raise_hard_error_if_graph_break(reason='torch.compile requires the `nested_compile_region` decorated function to be capturable into a single graph')
def _call_function(self, tx: 'InstructionTranslator', args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    (p_args, p_kwargs, example_value, body_r, treespec, body_gmod, body_name) = self.create_wrapped_node(tx, args[0], args[1:], kwargs, 'invoke_subgraph')
    if <MASK>:
        unimplemented('kwargs should have been flattened into lifted args')
    flat_example_value = pytree.tree_map_only(torch.fx.Proxy, lambda a: a.node.meta['example_value'], body_r.as_proxy())
    p_args = (p_args[0], body_name, *p_args[1:])
    return _call_function_and_unflatten_output(tx, torch._higher_order_ops.invoke_subgraph, tuple(p_args), p_kwargs, flat_example_value, treespec)

def _is_onnx_op(op: Any) -> bool:
    """Whether the op overload is an ONNX custom op implemented with PyTorch."""
    if <MASK>:
        return False
    return op.name().startswith('onnx::')

def __array_finalize__(self, obj):
    if <MASK>:
        return super().__array_finalize__(obj)
    elif self is self.__singleton:
        pass
    else:
        self.__class__ = MaskedArray
        MaskedArray.__array_finalize__(self, obj)

def _output_shapes(self):
    output_shapes = [out.shape for out in self._pfor_input.op.outputs]
    shapes = self._pfor_input.get_attr('output_shapes')
    if not shapes:
        shapes = [tensor_shape.TensorShape(None) for _ in output_shapes]
    else:
        shapes = [tensor_shape.TensorShape(shape) for shape in shapes]
    for (i, shape) in enumerate(shapes):
        shape = shape.merge_with(output_shapes[i])
        pfor_input = self._pfor_input.input(i)
        if <MASK>:
            if _is_variant_with_internal_stacking(pfor_input.t):
                shape = tensor_shape.TensorShape([]).concatenate(shape)
            else:
                shape = tensor_shape.TensorShape([None]).concatenate(shape)
        output_shapes[i] = shape
    assert len(output_shapes) == self._pfor_input.num_inputs
    return output_shapes

def compile_fn(self, gm: fx.GraphModule, example_inputs: list[torch.Tensor]) -> CompiledFn:
    """
        Implements graph splitting, first determining a set of of buckets by counting
        parameter sizes in reverse graph order, then invoking the user/backend compiler
        to compile each subgraph. Finally, stiches compiled graphs into one graphmodule
        and returns its callable.
        """
    buckets = [Bucket()]
    processed_modules: set[torch.nn.Module] = set()
    for node in reversed(gm.graph.nodes):
        if node.op in ('output', 'placeholder'):
            continue
        if buckets[0].size >= self.bucket_bytes_cap or (len(buckets) == 1 and buckets[0].size >= self.first_bucket_cap):
            if bucket_has_external_output(buckets[0]):
                buckets.insert(0, Bucket())
            else:
                if buckets[0].opcount_increased_to_capture_external_output == 0:
                    buckets[0].paramsize_before_opcount_increase = buckets[0].size
                buckets[0].opcount_increased_to_capture_external_output += 1
        if node.op == 'call_function':
            self.add_param_args(buckets[0], node)
        elif node.op == 'call_module':
            target_mod = gm.get_submodule(node.target)
            if target_mod not in processed_modules:
                self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
        elif <MASK>:
            if isinstance(node.args[0].target, str):
                target_mod = None
                try:
                    target_mod = gm.get_submodule(node.args[0].target)
                except AttributeError:
                    pass
                if target_mod is not None and target_mod not in processed_modules:
                    self.add_module_params_to_bucket(target_mod, buckets[0], processed_modules, node.target)
                self.add_param_args(buckets[0], node)
        elif node.op == 'get_attr':
            maybe_param = getattr(gm, node.target)
            if isinstance(maybe_param, torch.nn.Parameter) and maybe_param.requires_grad and (not self._ignore_parameter(maybe_param)):
                self.add_param(buckets[0], maybe_param, node.target)
        buckets[0].nodes.append(node)
    if len(buckets) > 1 and buckets[0].size == 0:
        buckets[1].nodes.extend(buckets[0].nodes)
        assert len(buckets[0].params) == 0, 'Params should be empty if size is 0'
        del buckets[0]
    self.buckets = buckets
    pretty_print_buckets(buckets, self.bucket_bytes_cap)
    if len(buckets) == 1:
        return self.backend_compile_fn(gm, example_inputs)
    partition_map = {}
    for (idx, b) in enumerate(buckets):
        for node in b.nodes:
            partition_map[node] = idx
    split_gm = fx.passes.split_module.split_module(gm, None, lambda node: partition_map[node])
    propagate_dynamo_source(gm, split_gm)
    propagate_metadata(gm, split_gm)
    debug_str = f'\n---orig graph---\n{gm.graph}\n' + f'\n---split graph---\n{split_gm.graph}\n'
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            debug_str += f'\n---{name} graph---\n{module.graph}\n'
    debug_str += '\n---------------\n'
    ddp_graph_log.debug(debug_str)
    trace_structured('optimize_ddp_split_graph', payload_fn=lambda : split_gm.print_readable(print_output=False))
    for (name, module) in split_gm.named_modules():
        if '.' not in name and len(name):
            trace_structured('optimize_ddp_split_child', lambda : {'name': name}, payload_fn=lambda : module.print_readable(print_output=False))
    fake_mode = detect_fake_mode(example_inputs)
    if fake_mode is None:
        fake_mode = torch._subclasses.fake_tensor.FakeTensorMode()
    submod_compiler = SubmodCompiler(split_gm, self.backend_compile_fn, fake_mode)
    with torch._dynamo.utils._disable_saved_tensors_hooks_during_tracing():
        submod_compiler.run(*example_inputs)
    split_gm.recompile()
    ddp_graph_log.debug('\n---final graph---\n%s\n---------------\n', split_gm.graph)
    return split_gm

def reducer_override(self, obj: Any) -> Union[tuple[Callable[..., Any], tuple[Any, ...]], Any]:
    import sympy
    if id(obj) in self.empty_values:
        return (type(obj).__new__, (type(obj),))
    if id(obj) in self.missing_values:
        return (_Missing, ('missing values',))
    if isinstance(obj, torch.Tensor) and obj.device.type != 'meta':
        from torch.utils._python_dispatch import is_traceable_wrapper_subclass
        if id(obj) not in self.guard_tree_values:
            return (_Missing, ('tensor guard tree',))
        if is_traceable_wrapper_subclass(obj):
            inner_data = []
            (attrs, ctx) = obj.__tensor_flatten__()
            for attr in attrs:
                inner = getattr(obj, attr)
                if isinstance(inner, torch.Tensor):
                    self.guard_tree_values[id(inner)] = inner
                (func, args_tuple) = self.reducer_override(inner)
                inner_data.append((attr, func, args_tuple))
            return (type(self)._unpickle_traceable_wrapper_subclass, (torch.empty_like(obj, device='meta'), obj.device, type(obj), torch._C._dispatch_keys(obj).raw_repr(), ctx, inner_data))
        return (type(self)._unpickle_tensor, (torch.empty_like(obj, device='meta', requires_grad=obj.requires_grad), obj.device, type(obj), torch._C._dispatch_keys(obj).raw_repr(), obj.grad))
    elif isinstance(obj, torch.nn.Module):
        if id(obj) not in self.guard_tree_values:
            return (_Missing, ('module guard tree',))
        if isinstance(obj, torch.nn.parallel.DistributedDataParallel):
            return (type(self)._unpickle_ddp_module, (obj.__getstate__(),))
        if type(obj).__qualname__ == type(obj).__name__:
            return NotImplemented
        if obj.__class__.__getstate__ == torch.nn.Module.__getstate__:
            return (type(self)._unpickle_module, (obj.__getstate__(),))
    elif inspect.ismodule(obj):
        return (type(self)._unpickle_python_module, (obj.__name__,))
    elif isinstance(obj, torch._C.DispatchKeySet):
        return (type(self)._unpickle_dispatch_key_set, (obj.raw_repr(),))
    elif isinstance(obj, torch._C._functorch.CInterpreter):
        return (type(self)._unpickle_functorch_interpreter, (obj.serialize(),))
    elif inspect.isclass(obj) and issubclass(obj, sympy.Function) and hasattr(obj, '_torch_handler_name'):
        assert hasattr(obj, '_torch_unpickler')
        return (obj._torch_unpickler, (obj._torch_handler_name,))
    elif isinstance(obj, torch.SymInt):
        raise RuntimeError(f'Cannot serialize SymInt {obj} (node: {obj.node})')
    elif isinstance(obj, types.MappingProxyType):
        return (type(self)._unpickle_mapping_proxy, (obj.copy(),))
    elif isinstance(obj, torch._dynamo.utils.dict_keys):
        return (type(self)._unpickle_dict_keys, (list(obj),))
    elif isinstance(obj, torch._ops.OpOverloadPacket) and obj._qualified_op_name.startswith('_C::'):
        return (type(self)._unpickle_c_op, (obj.__name__,))
    elif obj.__class__.__module__ == 'builtins' and obj.__class__.__name__ == 'PyCapsule':
        return (_Missing, ('capsule',))
    elif isinstance(obj, _get_unsupported_types()):
        return (_Missing, ('unsupported',))
    elif inspect.isfunction(obj):
        if obj.__code__.co_flags & inspect.CO_NESTED:
            return (_Missing, ('nested function',))
        if obj.__module__ in sys.modules:
            f = sys.modules[obj.__module__]
            for name in obj.__qualname__.split('.'):
                f = getattr(f, name, None)
            if f is not obj:
                return (_Missing, ('fqn mismatch',))
    elif inspect.ismethod(obj):
        func = obj.__func__
        method_self = obj.__self__
        inner_func = getattr(method_self, func.__name__)
        if inspect.ismethod(inner_func):
            inner_func = inner_func.__func__
        if func is not inner_func:
            return (type(self)._unpickle_bound_method, (func, method_self))
    elif isinstance(obj, type((lambda x: lambda : x)(0).__closure__[0])):
        return (type(self)._unpickle_cell, (obj.cell_contents,))
    if hasattr(torch.distributed, 'distributed_c10d') and isinstance(obj, torch.distributed.distributed_c10d.Work):
        if id(obj) not in self.guard_tree_values:
            return (_Missing, ('distributed_c10d.Work',))
    if type(obj).__qualname__ != type(obj).__name__:
        raise torch._dynamo.exc.PackageError(f'Type {type(obj)} for object {obj} cannot be saved ' + "into torch.compile() package since it's defined in local scope. " + 'Please define the class at global scope (top level of a module).')
    if inspect.isclass(obj) and hasattr(torch.distributed, 'fsdp') and issubclass(obj, torch.distributed.fsdp._fully_shard.FSDPModule):
        if <MASK>:
            original_type = obj.__mro__[2]
            assert issubclass(original_type, torch.nn.Module)
            assert original_type in torch.distributed.fsdp._fully_shard._fully_shard.get_cls_to_fsdp_cls()
            return (type(self)._unpickle_fsdp_module_type, (original_type,))
    return NotImplemented

def _run_autocast_outofplace(self, op, args, run_as_type, device, out_type=None, module=torch, add_kwargs=None, amp_dtype=torch.bfloat16):

    def cast(val, to_type):
        if isinstance(val, torch.Tensor):
            return val.to(to_type) if val.is_floating_point() else val
        elif isinstance(val, collections.abc.Iterable):
            return type(val)((cast(v, to_type) for v in val))
        else:
            return val
    if add_kwargs is None:
        add_kwargs = {}
    self.assertFalse(torch.is_autocast_enabled(device_type=device))
    with torch.amp.autocast(device_type=device, dtype=amp_dtype):
        self.assertTrue(torch.is_autocast_enabled(device_type=device))
        out_type = out_type if out_type is not None else run_as_type
        output = output_method = None
        if <MASK>:
            output = getattr(module, op)(*args, **add_kwargs)
            if isinstance(output, torch.Tensor):
                self.assertTrue(out_type == output.dtype, f'autocast for torch.{op} produced {output.dtype}, should produce {out_type}')
        if hasattr(torch.Tensor, op):
            output_method = getattr(args[0], op)(*args[1:], **add_kwargs)
            if isinstance(output_method, torch.Tensor):
                self.assertTrue(out_type == output_method.dtype, f'autocast for torch.{op} produced {output_method.dtype}, should produce torch.{out_type}')
        self.assertTrue(output is not None or output_method is not None, f'{op} not found as an attribute on either Tensor or the requested module {module}')

        def compare(first, second):
            if isinstance(first, torch.Tensor):
                return torch.equal(first, second)
            elif isinstance(first, collections.abc.Iterable):
                return all((compare(f, s) for (f, s) in zip(first, second, strict=False)))
            else:
                return first == second
        if output is not None and output_method is not None:
            self.assertTrue(type(output) is type(output_method))
            comparison = compare(output, output_method)
            self.assertTrue(comparison, f'torch.{op} result did not match Tensor.{op} result')
        output_to_compare = output if output is not None else output_method
        with torch.amp.autocast(device_type=device, enabled=False):
            self.assertFalse(torch.is_autocast_enabled(device_type=device))
            if module is not None and hasattr(module, op):
                control = getattr(module, op)(*cast(args, run_as_type), **add_kwargs)
            else:
                control = getattr(args[0].to(run_as_type), op)(*cast(args[1:], run_as_type), **add_kwargs)
            self.assertTrue(type(output_to_compare) is type(control))
            comparison = compare(output_to_compare, control)
            self.assertTrue(comparison, f'torch.{op} result did not match control')
        self.assertTrue(torch.is_autocast_enabled(device_type=device))
    self.assertFalse(torch.is_autocast_enabled(device_type=device))

def _convert_value(value, expected_type, path, context=_ConversionContext.VALUE):
    """Type-checks and converts a value.

  Args:
    value: The value to type-check.
    expected_type: The expected type for the value.
    path: Tuple of `str` naming the value (used for exception messages).
    context: _ConversionContext, indicates what kind of value we are converting.

  Returns:
    A copy of `value`, converted to the expected type.

  Raises:
    TypeError: If `value` can not be converted to the expected type.
  """
    assert isinstance(path, tuple)
    if expected_type is None:
        expected_type = _NoneType
    if expected_type is tensor.Tensor:
        return _convert_tensor(value, path, context)
    elif <MASK>:
        return _convert_composite_tensor(value, expected_type, path, context)
    elif expected_type is tensor_shape.TensorShape:
        try:
            return tensor_shape.as_shape(value)
        except TypeError as e:
            raise TypeError(f"{''.join(path)}: expected 'tf.TensorShape', got {type(value).__name__!r}") from e
    elif expected_type is dtypes.DType:
        try:
            return dtypes.as_dtype(value)
        except TypeError as e:
            raise TypeError(f"{''.join(path)}: expected 'tf.DType', got {type(value).__name__!r}") from e
    elif expected_type in (int, float, bool, str, bytes, _NoneType):
        if not isinstance(value, expected_type):
            raise TypeError(f"{''.join(path)}: expected {expected_type.__name__!r}, got {type(value).__name__!r}")
        return value
    elif type_annotations.is_generic_tuple(expected_type):
        return _convert_tuple(value, expected_type, path, context)
    elif type_annotations.is_generic_mapping(expected_type):
        return _convert_mapping(value, expected_type, path, context)
    elif type_annotations.is_generic_union(expected_type):
        return _convert_union(value, expected_type, path, context)
    else:
        raise TypeError(f"{''.join(path)}: Unsupported type annotation {expected_type!r}")

@property
def original_name(self):
    if <MASK>:
        return ''
    return str(self._c._type().name())

def STORE_ATTR(self, inst: Instruction) -> None:
    speculation = self.speculate()
    if speculation.failed(self):
        return self.store_attr_graph_break(inst)
    (val, obj) = self.popn(2)
    if <MASK>:
        assert not self.export, f'Mutating module attribute {inst.argval} during export.'
    try:
        BuiltinVariable(setattr).call_function(self, [obj, ConstantVariable.create(inst.argval), val], {})
        return
    except Unsupported as e:
        if not self.should_compile_partial_graph():
            raise
        log.debug('STORE_ATTR triggered compile', exc_info=True)
        e.remove_from_stats()
        e.add_to_stats('graph_break')
    speculation.fail_and_restart_analysis(self.error_on_graph_break)

def _parse_values(s):
    """(INTERNAL) Split a line into a list of values"""
    if not _RE_NONTRIVIAL_DATA.search(s):
        return [None if s in ('?', '') else s for s in next(csv.reader([s]))]
    (values, errors) = zip(*_RE_DENSE_VALUES.findall(',' + s))
    if not any(errors):
        return [_unquote(v) for v in values]
    if <MASK>:
        try:
            return {int(k): _unquote(v) for (k, v) in _RE_SPARSE_KEY_VALUES.findall(s)}
        except ValueError:
            for match in _RE_SPARSE_KEY_VALUES.finditer(s):
                if not match.group(1):
                    raise BadLayout('Error parsing %r' % match.group())
            raise BadLayout('Unknown parsing error')
    else:
        for match in _RE_DENSE_VALUES.finditer(s):
            if match.group(2):
                raise BadLayout('Error parsing %r' % match.group())
        raise BadLayout('Unknown parsing error')

@wraps(func)
def wrapper(*args, **kwargs):

    def load_inline(*args, **kwargs):
        if IS_WINDOWS:
            return cpp_extension.load_inline(*args, **kwargs)
        assert 'build_directory' not in kwargs
        with TemporaryDirectoryName() as temp_dir_name:
            if <MASK>:
                print(f'Using temporary extension directory {temp_dir_name}...', file=sys.stderr)
            kwargs['build_directory'] = temp_dir_name
            return cpp_extension.load_inline(*args, **kwargs)
    return func(*args, load_inline=load_inline, **kwargs)

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    if name == '__getitem__':
        from .tensor import TensorVariable
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if isinstance(args[0], TensorVariable):
            value = get_fake_value(args[0].as_proxy().node, tx)
            if value.constant is not None and value.constant.numel() == 1:
                value = variables.ConstantVariable.create(value.constant.item())
            else:
                unimplemented_v2(gb_type='Indexing list with non-scalar tensor', context=f'call_method {self} {name} {args} {kwargs}', explanation='Attempted to index list-like object with tensor with > 1 element.', hints=[*graph_break_hints.USER_ERROR])
        else:
            value = args[0]
        if value.python_type() not in (int, slice):
            msg = f'indices must be integers or slices, not {value.python_type()}'
            raise_observed_exception(TypeError, tx, args=[ConstantVariable(msg)])
        return self.getitem_const(tx, value)
    elif name == '__contains__':
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return iter_contains(self.unpack_var_sequence(tx), args[0], tx)
    elif name == 'index':
        if not len(args):
            raise_args_mismatch(tx, name, '0 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return tx.inline_user_function_return(VariableTracker.build(tx, polyfills.index), [self] + list(args), kwargs)
    elif name == 'count':
        if len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        return VariableTracker.build(tx, operator.countOf).call_function(tx, [self, args[0]], kwargs)
    elif name in ('__add__', '__iadd__'):
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if type(self) is not type(args[0]):
            tp_name = self.python_type_name()
            other = args[0].python_type_name()
            msg = ConstantVariable.create(f'can only concatenate {tp_name} (not "{other}") to {tp_name}')
            raise_observed_exception(TypeError, tx, args=[msg])
        if name == '__add__':
            return type(self)(self.items + args[0].items, source=self.source)
        else:
            self.items += args[0].items
            return self
    elif name in ('__mul__', '__imul__'):
        if kwargs or len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        if <MASK>:
            msg = ConstantVariable.create(f"can't multiply sequence by non-int type of '{args[0].python_type_name()}'")
            raise_observed_exception(TypeError, tx, args=[msg])
        val = args[0].as_python_constant()
        if name == '__mul__':
            return type(self)(self.items * val, source=self.source)
        else:
            self.items *= val
            return self
    elif name in cmp_name_to_op_mapping:
        if len(args) != 1:
            raise_args_mismatch(tx, name, '1 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        left = self
        right = args[0]
        if not isinstance(left, BaseListVariable) or not isinstance(right, BaseListVariable):
            if name == '__eq__':
                return variables.BuiltinVariable(operator.is_).call_function(tx, (left, right), {})
            elif name == '__ne__':
                return variables.BuiltinVariable(operator.is_not).call_function(tx, (left, right), {})
            else:
                op_str = cmp_name_to_op_str_mapping[name]
                left_ty = left.python_type_name()
                right_ty = right.python_type_name()
                msg = f"{op_str} not supported between instances of '{left_ty}' and '{right_ty}'"
                raise_observed_exception(TypeError, tx, args=[msg])
        return variables.UserFunctionVariable(polyfills.list_cmp).call_function(tx, [variables.BuiltinVariable(cmp_name_to_op_mapping[name]), left, right], {})
    return super().call_method(tx, name, args, kwargs)

def _fit(self, X, y, alpha, loss, learning_rate, coef_init=None, intercept_init=None, sample_weight=None):
    if hasattr(self, 'classes_'):
        delattr(self, 'classes_')
    y = validate_data(self, y=y)
    classes = np.unique(y)
    if self.warm_start and hasattr(self, 'coef_'):
        if coef_init is None:
            coef_init = self.coef_
        if <MASK>:
            intercept_init = self.intercept_
    else:
        self.coef_ = None
        self.intercept_ = None
    if self.average > 0:
        self._standard_coef = self.coef_
        self._standard_intercept = self.intercept_
        self._average_coef = None
        self._average_intercept = None
    self.t_ = 1.0
    self._partial_fit(X, y, alpha, loss, learning_rate, self.max_iter, classes, sample_weight, coef_init, intercept_init)
    if self.tol is not None and self.tol > -np.inf and (self.n_iter_ == self.max_iter):
        warnings.warn('Maximum number of iteration reached before convergence. Consider increasing max_iter to improve the fit.', ConvergenceWarning)
    if self.power_t < 0:
        warnings.warn('Negative values for `power_t` are deprecated in version 1.8 and will raise an error in 1.10. Use values in the range [0.0, inf) instead.', FutureWarning)
    return self

def make_decorator(target, decorator_func, decorator_name=None, decorator_doc='', decorator_argspec=None):
    """Make a decorator from a wrapper and a target.

  Args:
    target: The final callable to be wrapped.
    decorator_func: The wrapper function.
    decorator_name: The name of the decorator. If `None`, the name of the
      function calling make_decorator.
    decorator_doc: Documentation specific to this application of
      `decorator_func` to `target`.
    decorator_argspec: Override the signature using FullArgSpec.

  Returns:
    The `decorator_func` argument with new metadata attached.
  """
    if decorator_name is None:
        decorator_name = inspect.currentframe().f_back.f_code.co_name
    decorator = TFDecorator(decorator_name, target, decorator_doc, decorator_argspec)
    setattr(decorator_func, '_tf_decorator', decorator)
    if hasattr(target, '__name__'):
        decorator_func.__name__ = target.__name__
    if <MASK>:
        decorator_func.__qualname__ = target.__qualname__
    if hasattr(target, '__module__'):
        decorator_func.__module__ = target.__module__
    if hasattr(target, '__dict__'):
        for name in target.__dict__:
            if name not in decorator_func.__dict__:
                decorator_func.__dict__[name] = target.__dict__[name]
    if hasattr(target, '__doc__'):
        decorator_func.__doc__ = decorator.__doc__
    decorator_func.__wrapped__ = target
    decorator_func.__original_wrapped__ = target
    if decorator_argspec:
        decorator_func.__signature__ = fullargspec_to_signature(decorator_argspec)
    elif callable(target):
        try:
            signature = inspect.signature(target)
        except (TypeError, ValueError):
            pass
        else:
            bound_instance = _get_bound_instance(target)
            if bound_instance and 'self' in signature.parameters:
                signature = inspect.Signature(list(signature.parameters.values())[1:])
                decorator_func.__self__ = bound_instance
            decorator_func.__signature__ = signature
    return decorator_func

@tf_export.tf_export('experimental.numpy.rot90', v1=[])
@np_utils.np_doc('rot90')
def rot90(m, k=1, axes=(0, 1)):
    m_rank = array_ops.rank(m)
    (ax1, ax2) = np_utils._canonicalize_axes(axes, m_rank)
    k = k % 4
    if k == 0:
        return m
    elif k == 2:
        return flip(flip(m, ax1), ax2)
    else:
        perm = math_ops.range(m_rank)
        perm = array_ops.tensor_scatter_update(perm, [[ax1], [ax2]], [ax2, ax1])
        if <MASK>:
            return transpose(flip(m, ax2), perm)
        else:
            return flip(transpose(m, perm), ax2)

def replace_use(a):
    if a is None:
        return
    if isinstance(a, TensorArgument):
        a.name = name_table.get(a.name, a.name)
    elif isinstance(a, (SymIntArgument, SymFloatArgument)):
        if <MASK>:
            a.as_name = name_table.get(a.as_name, a.as_name)
    elif isinstance(a, SymBoolArgument):
        if a.type == 'as_name':
            a.as_name = name_table.get(a.as_name, a.as_name)
    elif isinstance(a, OptionalTensorArgument):
        if a.type == 'as_tensor':
            a.as_tensor.name = name_table.get(a.as_tensor.name, a.as_tensor.name)
    elif isinstance(a, CustomObjArgument):
        a.name = name_table.get(a.name, a.name)
    else:
        raise AssertionError(f'Unknown argument type: {a}')

