def __call__(self, path, parent, children):
    """Visitor interface, see `traverse` for details."""
    if tf_inspect.ismodule(parent) and len(path.split('.')) > 10:
        raise RuntimeError('Modules nested too deep:\n%s.%s\n\nThis is likely a problem with an accidental public import.' % (self._root_name, path))
    full_path = '.'.join([self._root_name, path]) if path else self._root_name
    for (name, child) in list(children):
        if self._is_private(full_path, name, child):
            children.remove((name, child))
    self._visitor(path, parent, children)
    for (name, child) in list(children):
        if <MASK>:
            children.remove((name, child))

def _raise_error_for_non_direct_inputs(self, features):
    """Checks all tensors in features to see if they are a direct input."""
    for (path, input_tensor) in nest.flatten_with_joined_string_paths(features, expand_composites=True):
        if input_tensor.op.type == 'Placeholder':
            continue
        try:
            is_input = input_tensor.op.get_attr('_tpu_input_identity')
        except ValueError:
            is_input = False
        if <MASK>:
            raise ValueError('Received input tensor {} which is the output of op {} (type {}) which does not have the `_tpu_input_identity` attr. Please ensure that the inputs to this layer are taken directly from the arguments of the function called by strategy.run. Two possible causes are: dynamic batch size support or you are using a keras layer and are not passing tensors which match the dtype of the `tf.keras.Input`s.If you are triggering dynamic batch size support, you can disable it by passing tf.distribute.RunOptions(experimental_enable_dynamic_batch_size=False) to the options argument of strategy.run().'.format(path, input_tensor.op.name, input_tensor.op.type))

def _get_slice_indices(self, length, slice):
    step_is_negative = 0
    if slice.step is None:
        step = 1
        step_is_negative = False
    else:
        step = slice.step
        step_is_negative = slice.step < 0
    if step_is_negative:
        lower = -1
        upper = length + lower
    else:
        lower = 0
        upper = length
    if slice.start is None:
        start = upper if step_is_negative else lower
    else:
        start = slice.start
    if start < 0:
        start += length
        if start < lower:
            start = lower
    elif <MASK>:
        start = upper
    if slice.stop is None:
        stop = lower if step_is_negative else upper
    else:
        stop = slice.stop
        if stop < 0:
            stop += length
            if stop < lower:
                stop = lower
        elif stop > upper:
            stop = upper
    return [start, stop, step]

def compare_tensor_meta(a: TensorLikeType, b: TensorLikeType, check_sizes=True, check_strides=False, *, allow_rhs_unbacked=False, check_conj=True):
    """
    Checks that two tensor likes have the same shape,
    dtype and device.

    In the future this will validate additional metadata, like
    strides.
    """
    from torch._subclasses.fake_tensor import MetadataMismatchError
    assert isinstance(a, TensorLike)
    assert isinstance(b, TensorLike)
    if check_sizes and (not same_shape(a.shape, b.shape, allow_rhs_unbacked=allow_rhs_unbacked)):
        msg = f'Shapes {a.shape} and {b.shape} are not equal!'
        raise MetadataMismatchError(msg)
    if a.dtype != b.dtype:
        msg = f'Dtypes {a.dtype} and {b.dtype} are not equal!'
        raise MetadataMismatchError(msg)
    if a.device != b.device:
        if (str(a.device) == 'cuda:0' or str(a.device) == 'cuda') and (str(b.device) == 'cuda:0' or str(b.device) == 'cuda'):
            pass
        else:
            msg = f'Devices {a.device} and {b.device} are not equal!'
            raise MetadataMismatchError(msg)
    if check_strides:
        (same_strides, idx) = check_significant_strides(a, b, allow_rhs_unbacked=allow_rhs_unbacked)
        if not same_strides:
            msg = f'Stride mismatch! Strides are {a.stride()} and {b.stride()} (mismatched at {idx})!'
            raise MetadataMismatchError(msg)
        if a.storage_offset() != b.storage_offset():
            msg = f'Storage offset mismatch! Storage offsets are {a.storage_offset()} and {b.storage_offset()}!'
            raise MetadataMismatchError(msg)
    if <MASK>:
        if a.is_conj() != b.is_conj():
            raise MetadataMismatchError(f'Conj mismatch! is_conj is set to {a.is_conj()} and {b.is_conj()}')
    if a.is_neg() != b.is_neg():
        raise MetadataMismatchError(f'Neg mismatch! is_neg is set to {a.is_neg()} and {b.is_neg()}')

def at_least_x_gpu(x):
    if TEST_CUDA and torch.cuda.device_count() >= x:
        return True
    if <MASK>:
        return True
    if TEST_XPU and torch.xpu.device_count() >= x:
        return True
    return False

def triton_reshape(value: str, old_shape: Sequence[sympy.Expr], new_shape: Sequence[sympy.Expr]) -> str:
    """Workaround https://github.com/triton-lang/triton/issues/2836"""
    assert isinstance(old_shape, list) and isinstance(new_shape, list)
    old_shape_str = [V.kernel.index_to_str(shape) for shape in old_shape]
    new_shape_str = [V.kernel.index_to_str(shape) for shape in new_shape]
    if old_shape_str == new_shape_str:
        return value
    if [s for s in new_shape_str if s != '1'] != old_shape_str:
        return f"tl.reshape({value}, [{', '.join(new_shape_str)}])"
    idx = 0
    expand = []
    for size in new_shape_str:
        if <MASK>:
            expand.append(':')
            idx += 1
        else:
            assert size == '1'
            expand.append('None')
    assert idx == len(old_shape_str)
    return f"{value}[{', '.join(expand)}]"

def __next__(self) -> Any:
    with torch.autograd.profiler.record_function(self._profile_name):
        if <MASK>:
            self._reset()
        data = self._next_data()
        self._num_yielded += 1
        if self._dataset_kind == _DatasetKind.Iterable and self._IterableDataset_len_called is not None and (self._num_yielded > self._IterableDataset_len_called):
            warn_msg = f'Length of IterableDataset {self._dataset} was reported to be {self._IterableDataset_len_called}(when accessing len(dataloader)), but {self._num_yielded} samples have been fetched. '
            if self._num_workers > 0:
                warn_msg += 'For multiprocessing data-loading, this could be caused by not properly configuring the IterableDataset replica at each worker. Please see https://pytorch.org/docs/stable/data.html#torch.utils.data.IterableDataset for examples.'
            warnings.warn(warn_msg)
        return data

