def _load_dynamic_shapes(spec: Union[DynamicShapesSpec, dict[str, Any]], from_dict: Optional[bool]=False) -> Union[dict[str, Any], tuple[Any], list[Any], None]:
    """
    Utility function for dynamic shapes serialization.
    Deserializes a DynamicShapesSpec or corresponding dictionary into a dynamic_shapes input to export().
    """
    import sympy
    from torch.fx.experimental.symbolic_shapes import _is_supported_equivalence
    if <MASK>:
        if not isinstance(spec, dict):
            raise UserError(UserErrorType.INVALID_INPUT, f'With from_dict=True, expected `spec` to be a dict, got {type(spec)}')
        if sorted(spec.keys()) != ['dims', 'dynamic_shapes']:
            raise UserError(UserErrorType.INVALID_INPUT, f'With from_dict=True, expected `spec` to have keys `dims` and `dynamic_shapes`, instead found {spec.keys()}')
        dims = {}
        for (k, v) in spec['dims'].items():
            if not isinstance(k, str):
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected `spec['dims']` keys to be strings for symbols, got key {type(k)}")
            if sorted(v.keys()) != ['derived', 'max', 'min']:
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected `spec['dims']` values to have keys `derived`, `max`, and `min`, instead found {v.keys()}")
            if not isinstance(v['min'], int):
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dims']` to map `min` to an int, got {k}: {v['min']}")
            if not isinstance(v['max'], int) or v['max'] is None:
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dims']` to map `max` to an int or None, got {k}: {v['max']}")
            if not isinstance(v['derived'], list) or any((not isinstance(d, str) for d in v['derived'])):
                raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dims']` to map `derived` to a list of derived expressions, got {k}: {v['derived']}")
            dims[k] = RootDim(**v)
        dynamic_shapes = spec['dynamic_shapes']
    else:
        if not isinstance(spec, DynamicShapesSpec):
            raise UserError(UserErrorType.INVALID_INPUT, f'Expected `spec` to be a DynamicShapesSpec, got {type(spec)}')
        dims = spec.dims
        dynamic_shapes = spec.dynamic_shapes
    if dynamic_shapes is None:
        return None
    dim_cache = {}
    for (name, info) in dims.items():
        symbol = sympy.sympify(name)
        if not isinstance(symbol, sympy.Symbol):
            raise UserError(UserErrorType.INVALID_INPUT, f"Expected `spec['dims']` keys to be symbols, got {name}")
        dim_cache[name] = Dim(name, min=info.min, max=info.max)
        for _expr in info.derived:
            expr = sympy.sympify(_expr)
            if len(expr.free_symbols) != 1 or symbol not in expr.free_symbols:
                raise UserError(UserErrorType.INVALID_INPUT, f'Expected derived expressions in to have {name} as the only free symbol, got {expr}')
            if not _is_supported_equivalence(expr):
                raise UserError(UserErrorType.INVALID_INPUT, f'Expected derived expressions to be linear expressions, got {expr}')
            (modulus, remainder) = sympy.polys.polytools.div(expr, symbol)
            ddim = dim_cache[name]
            if modulus != 1:
                ddim = int(modulus) * ddim
            if remainder != 0:
                ddim = ddim + int(remainder)
            dim_cache[_expr] = ddim

    def deserialize_shape(val: Union[None, int, str]) -> Union[None, int, Dim, _DimHint]:
        if val is None or isinstance(val, int):
            return val
        elif val == '_DimHint.AUTO':
            return _DimHint.AUTO()
        elif val == '_DimHint.DYNAMIC':
            return _DimHint.DYNAMIC()
        elif val == '_DimHint.STATIC':
            return _DimHint.STATIC()
        if not isinstance(val, str):
            raise UserError(UserErrorType.INVALID_INPUT, f"Expected leaves in `spec['dynamic_shapes']` to be ints, None, Dim.AUTO/STATIC, symbols,  or derived expressions, got {val}")
        if val not in dim_cache:
            raise UserError(UserErrorType.INVALID_INPUT, f"Expected dims in `spec['dynamic_shapes']` to be tracked in `spec['dims']`, got {val} which is not in {dims.keys()}")
        return dim_cache[val]
    return tree_map(deserialize_shape, dynamic_shapes)

def _gather_tunableop_results() -> None:
    """Gather results from multiple tunableop results file and create a single file."""
    gemm_lines = set()
    validator_lines = []
    results_filename = get_filename()
    if results_filename is not None and results_filename != '':
        dot_pos = results_filename.find('.')
        if <MASK>:
            filename_pattern = results_filename[:dot_pos - 1] + '?' + results_filename[dot_pos:]
        else:
            filename_pattern = ''
    else:
        results_filename_env = os.getenv('PYTORCH_TUNABLEOP_FILENAME')
        if results_filename_env is None or results_filename_env == '':
            filename_pattern = 'tunableop_results?.csv'
        elif '%d' in results_filename_env:
            filename_pattern = results_filename_env.replace('%d', '?')
        else:
            filename_pattern = results_filename_env.replace('.', '?.')
    assert '?' in filename_pattern
    FirstFile = False
    matching_files = glob.glob(filename_pattern)
    num_matching_files = len(matching_files)
    for file_path in matching_files:
        with open(file_path) as file:
            for line in file:
                if line.startswith('Validator'):
                    if not FirstFile:
                        validator_lines.append(line)
                else:
                    gemm_lines.add(line)
        FirstFile = True
    output_file = filename_pattern.replace('?', '_full0')
    with open(output_file, 'w') as out_file:
        for line in validator_lines:
            out_file.write(line)
        for line in gemm_lines:
            out_file.write(line)
    for i in range(1, num_matching_files):
        duplicate_file = output_file.replace('0', str(i))
        shutil.copy(output_file, duplicate_file)

def __init__(self, params: ParamsT, lr: Union[float, Tensor]=0.001, betas: tuple[float, float]=(0.9, 0.999), eps: float=1e-08, maximize: bool=False):
    if isinstance(lr, Tensor) and lr.numel() != 1:
        raise ValueError('Tensor lr must be 1-element')
    if not 0.0 < lr:
        raise ValueError(f'Invalid learning rate: {lr}')
    if not 0.0 < eps:
        raise ValueError(f'Invalid epsilon value: {eps}')
    if not 0.0 <= betas[0] < 1.0:
        raise ValueError(f'Invalid beta parameter at index 0: {betas[0]}')
    if <MASK>:
        raise ValueError(f'Invalid beta parameter at index 1: {betas[1]}')
    defaults = {'lr': lr, 'betas': betas, 'eps': eps, 'maximize': maximize}
    super().__init__(params, defaults)
    sparse_params = []
    complex_params = []
    for (index, param_group) in enumerate(self.param_groups):
        if not isinstance(param_group, dict):
            raise AssertionError(f'param_groups must be a list of dicts, but got {type(param_group)}')
        for (d_index, d_param) in enumerate(param_group['params']):
            if d_param.is_sparse:
                sparse_params.append([index, d_index])
            if d_param.is_complex():
                complex_params.append([index, d_index])
    if sparse_params:
        raise ValueError(f'Sparse params at indices {sparse_params}: SparseAdam requires dense parameter tensors')
    if complex_params:
        raise ValueError(f'Complex params at indices {complex_params}: SparseAdam does not support complex parameters')

def __eq__(self, other: object) -> bool:
    if other is None:
        return True
    if <MASK>:
        return NotImplemented
    return self.metadata == other.metadata

def _cast_to_stata_types(data: DataFrame) -> DataFrame:
    """
    Checks the dtypes of the columns of a pandas DataFrame for
    compatibility with the data types and ranges supported by Stata, and
    converts if necessary.

    Parameters
    ----------
    data : DataFrame
        The DataFrame to check and convert

    Notes
    -----
    Numeric columns in Stata must be one of int8, int16, int32, float32 or
    float64, with some additional value restrictions.  int8 and int16 columns
    are checked for violations of the value restrictions and upcast if needed.
    int64 data is not usable in Stata, and so it is downcast to int32 whenever
    the value are in the int32 range, and sidecast to float64 when larger than
    this range.  If the int64 values are outside of the range of those
    perfectly representable as float64 values, a warning is raised.

    bool columns are cast to int8.  uint columns are converted to int of the
    same size if there is no loss in precision, otherwise are upcast to a
    larger type.  uint64 is currently not supported since it is concerted to
    object in a DataFrame.
    """
    ws = ''
    conversion_data: tuple[tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type]] = ((np.bool_, np.int8, np.int8), (np.uint8, np.int8, np.int16), (np.uint16, np.int16, np.int32), (np.uint32, np.int32, np.int64), (np.uint64, np.int64, np.float64))
    float32_max = struct.unpack('<f', b'\xff\xff\xff~')[0]
    float64_max = struct.unpack('<d', b'\xff\xff\xff\xff\xff\xff\xdf\x7f')[0]
    for col in data:
        is_nullable_int = isinstance(data[col].dtype, ExtensionDtype) and data[col].dtype.kind in 'iub'
        orig_missing = data[col].isna()
        if is_nullable_int:
            fv = 0 if data[col].dtype.kind in 'iu' else False
            data[col] = data[col].fillna(fv).astype(data[col].dtype.numpy_dtype)
        elif isinstance(data[col].dtype, ExtensionDtype):
            if getattr(data[col].dtype, 'numpy_dtype', None) is not None:
                data[col] = data[col].astype(data[col].dtype.numpy_dtype)
            elif is_string_dtype(data[col].dtype):
                data[col] = data[col].astype('object')
                data.loc[data[col].isna(), col] = None
        dtype = data[col].dtype
        empty_df = data.shape[0] == 0
        for c_data in conversion_data:
            if dtype == c_data[0]:
                if empty_df or data[col].max() <= np.iinfo(c_data[1]).max:
                    dtype = c_data[1]
                else:
                    dtype = c_data[2]
                if c_data[2] == np.int64:
                    if data[col].max() >= 2 ** 53:
                        ws = precision_loss_doc.format('uint64', 'float64')
                data[col] = data[col].astype(dtype)
        if dtype == np.int8 and (not empty_df):
            if data[col].max() > 100 or data[col].min() < -127:
                data[col] = data[col].astype(np.int16)
        elif dtype == np.int16 and (not empty_df):
            if data[col].max() > 32740 or data[col].min() < -32767:
                data[col] = data[col].astype(np.int32)
        elif dtype == np.int64:
            if empty_df or (data[col].max() <= 2147483620 and data[col].min() >= -2147483647):
                data[col] = data[col].astype(np.int32)
            else:
                data[col] = data[col].astype(np.float64)
                if data[col].max() >= 2 ** 53 or data[col].min() <= -2 ** 53:
                    ws = precision_loss_doc.format('int64', 'float64')
        elif dtype in (np.float32, np.float64):
            if np.isinf(data[col]).any():
                raise ValueError(f'Column {col} contains infinity or -infinitywhich is outside the range supported by Stata.')
            value = data[col].max()
            if <MASK>:
                data[col] = data[col].astype(np.float64)
            elif dtype == np.float64:
                if value > float64_max:
                    raise ValueError(f'Column {col} has a maximum value ({value}) outside the range supported by Stata ({float64_max})')
        if is_nullable_int:
            if orig_missing.any():
                sentinel = StataMissingValue.BASE_MISSING_VALUES[data[col].dtype.name]
                data.loc[orig_missing, col] = sentinel
    if ws:
        warnings.warn(ws, PossiblePrecisionLoss, stacklevel=find_stack_level())
    return data

def render(self, context):
    first = ''
    for var in self.vars:
        value = var.resolve(context, ignore_failures=True)
        if <MASK>:
