def _create_test_user(self, cursor, parameters, verbosity, keepdb=False):
    if <MASK>:
        self.log('_create_test_user(): username = %s' % parameters['user'])
    statements = ['CREATE USER %(user)s\n               IDENTIFIED BY "%(password)s"\n               DEFAULT TABLESPACE %(tblspace)s\n               TEMPORARY TABLESPACE %(tblspace_temp)s\n               QUOTA UNLIMITED ON %(tblspace)s\n            ', 'GRANT CREATE SESSION,\n                     CREATE TABLE,\n                     CREATE SEQUENCE,\n                     CREATE PROCEDURE,\n                     CREATE TRIGGER\n               TO %(user)s']
    acceptable_ora_err = 'ORA-01920' if keepdb else None
    success = self._execute_allow_fail_statements(cursor, statements, parameters, verbosity, acceptable_ora_err)
    if not success and self._test_settings_get('PASSWORD') is None:
        set_password = 'ALTER USER %(user)s IDENTIFIED BY "%(password)s"'
        self._execute_statements(cursor, [set_password], parameters, verbosity)
    for object_type in ('VIEW', 'MATERIALIZED VIEW'):
        extra = 'GRANT CREATE %(object_type)s TO %(user)s'
        parameters['object_type'] = object_type
        success = self._execute_allow_fail_statements(cursor, [extra], parameters, verbosity, 'ORA-01031')
        if not success and verbosity >= 2:
            self.log('Failed to grant CREATE %s permission to test user. This may be ok.' % object_type)

def gen_vmap_plumbing(native_function: NativeFunction) -> str | None:
    schema = native_function.func
    sig = DispatcherSignature.from_schema(schema)
    returns = schema.returns
    if not accepts_at_least_one_tensor_input(schema):
        return None
    if len(returns) == 0:
        return gen_vmap_plumbing_no_returns(native_function)
    return_symint_overrides = ['_scaled_dot_product_flash_attention', '_scaled_dot_product_cudnn_attention']
    if not all((ret.type.is_tensor_like() for ret in returns)) and schema.name.unambiguous_name() not in return_symint_overrides:
        return None
    if <MASK>:
        return None
    if schema.kind() == SchemaKind.inplace:
        return gen_vmap_inplace_plumbing(native_function)
    if schema.kind() != SchemaKind.functional:
        return None
    results_var = 'results'
    cur_level_var = 'cur_level'
    (unwraps, unwrapped_arg_list) = gen_unwraps(schema.arguments.flat_all, cur_level_var)
    bdims_all_none_case = gen_case_where_all_bdims_are_none(sig, schema, cur_level_var)
    wrapped_returns = gen_returns(returns, cur_level_var, results_var)
    return f"""template <typename batch_rule_t, batch_rule_t batch_rule>\n{sig.decl(name=schema.name.unambiguous_name() + '_generated_plumbing')} {{\n  c10::impl::ExcludeDispatchKeyGuard guard(DispatchKey::FuncTorchBatched);\n  auto maybe_layer = maybeCurrentDynamicLayer();\n  vmap_check_escaped(maybe_layer, "gen_vmap_plumbing");\n  int64_t {cur_level_var} = maybe_layer->layerId();\n{textwrap.indent(bdims_all_none_case, '  ')}\n{textwrap.indent(unwraps, '  ')}\n  auto {results_var} = batch_rule({', '.join(unwrapped_arg_list)});\n  {wrapped_returns}\n}}"""

def _make_prim(*, schema: str, return_type: Union[RETURN_TYPE, tuple[RETURN_TYPE, ...]], meta: Callable, impl_aten: Callable, doc: str, tags: Optional[Sequence[torch.Tag]]=None, use_old_custom_ops_api: bool=False, register_conj_neg_fallthrough: bool=False):
    """
    Creates a primitive operation.

    """

    def _prim_impl(*args, **kwargs):
        meta(*args, **kwargs)
        return impl_aten(*args, **kwargs)

    def _autograd_impl(*args, **kwargs):
        return backwards_not_supported(_prim)(*args, **kwargs)

    def _backend_select_impl(*args, **kwargs):
        if kwargs.get('device') and kwargs['device'].type == 'meta':
            return meta(*args, **kwargs)
        if any((isinstance(x, torch.device) and x.type == 'meta' for x in args)):
            return meta(*args, **kwargs)
        else:
            return _prim_impl(*args, **kwargs)
    name = schema.split('(', maxsplit=1)[0]
    schema = schema[len(name):]
    cpp_schema = torch._C.parse_schema(name + schema)
    if use_old_custom_ops_api or not is_functional_schema(cpp_schema):
        prim.define(name + schema, tags=torch.Tag.pt2_compliant_tag)
        prim_impl.impl(name, _prim_impl)
        prim_autograd_impl.impl(name, _autograd_impl)
        prim_meta_impl.impl(name, meta)
    else:
        mutates_args = [arg.name for arg in cpp_schema.arguments if arg.alias_info is not None and arg.alias_info.is_write]
        prim_def = torch.library.custom_op('prims::' + name, _prim_impl, mutates_args=tuple(mutates_args), schema=schema)
        prim_def.register_fake(meta)
        if return_type == RETURN_TYPE.VIEW or register_conj_neg_fallthrough:
            prim_def._lib.impl(name, torch.library.fallthrough_kernel, 'Conjugate')
            prim_def._lib.impl(name, torch.library.fallthrough_kernel, 'Negative')
    _prim_packet = getattr(torch._ops.ops.prims, name)
    _prim = _prim_packet.default
    if <MASK>:
        _prim._tags = tags
    elif (aten_packet := getattr(torch.ops.aten, name, None)):
        overload_tags = [getattr(aten_packet, overload).tags for overload in aten_packet.overloads()]
        tags_intersection = set(overload_tags[0])
        tags_intersection.intersection_update(*overload_tags[1:])
        tags_intersection.discard(torch.Tag.core)
        tags_intersection.discard(torch.Tag.data_dependent_output)
        _prim._tags = tuple((t for t in overload_tags[0] if t in tags_intersection))
    from torch._subclasses.fake_tensor import contains_tensor_types
    if not any((contains_tensor_types(a.type) for a in _prim._schema.arguments)) or str(_prim) == 'prims.device_put.default':
        prim_backend_select_impl.impl(name, _backend_select_impl)
    for p in (_prim_packet, _prim):
        p.__doc__ = doc
        p.return_type = return_type
        p.schema = schema
        p.prim_impl = _prim_impl
        p.prim_meta_impl = meta
        p.impl_aten = impl_aten
    return _prim

def score_mod(t):
    score_factor = 1.0
    for tile_size in t[0].tiling.values():
        if <MASK>:
            score_factor = score_factor / bad_size_additional_tiling_penalty
        else:
            score_factor = score_factor / good_size_tiling_penalty
    return -t[0].score * score_factor

def _make_table(self, key_dtype, state_manager):
