def _parametrize_test(self, test, generic_cls, device_cls):
    """Parameterizes the given test function across each op and its associated dtypes."""
    if device_cls is None:
        raise RuntimeError('The @ops decorator is only intended to be used in a device-specific context; use it with instantiate_device_type_tests() instead of instantiate_parametrized_tests()')
    op = check_exhausted_iterator = object()
    for op in self.op_list:
        dtypes: Union[set[torch.dtype], set[None]]
        if isinstance(self.opinfo_dtypes, Sequence):
            dtypes = set(self.opinfo_dtypes)
        elif self.opinfo_dtypes == OpDTypes.unsupported_backward:
            dtypes = set(get_all_dtypes()).difference(op.supported_backward_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported_backward:
            dtypes = op.supported_backward_dtypes(device_cls.device_type)
        elif self.opinfo_dtypes == OpDTypes.unsupported:
            dtypes = set(get_all_dtypes()).difference(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.supported:
            dtypes = set(op.supported_dtypes(device_cls.device_type))
        elif self.opinfo_dtypes == OpDTypes.any_one:
            supported = op.supported_dtypes(device_cls.device_type)
            supported_backward = op.supported_backward_dtypes(device_cls.device_type)
            supported_both = supported.intersection(supported_backward)
            dtype_set = supported_both if len(supported_both) > 0 else supported
            for dtype in ANY_DTYPE_ORDER:
                if dtype in dtype_set:
                    dtypes = {dtype}
                    break
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.any_common_cpu_cuda_one:
            supported = set(op.dtypes).intersection(op.dtypesIfCUDA)
            if supported:
                dtypes = {next((dtype for dtype in ANY_DTYPE_ORDER if dtype in supported))}
            else:
                dtypes = {}
        elif self.opinfo_dtypes == OpDTypes.none:
            dtypes = {None}
        else:
            raise RuntimeError(f'Unknown OpDType: {self.opinfo_dtypes}')
        if self.allowed_dtypes is not None:
            dtypes = dtypes.intersection(self.allowed_dtypes)
        test_name = op.formatted_name
        sample_skips_and_xfails = getattr(test, 'sample_skips_and_xfails', None)
        if sample_skips_and_xfails is not None:
            sample_skips_and_xfails = [rule for rule in sample_skips_and_xfails if rule.op_match_fn(device_cls.device_type, op)]
        for dtype in dtypes:
            param_kwargs = {'op': op}
            _update_param_kwargs(param_kwargs, 'dtype', dtype)
            try:

                @wraps(test)
                def test_wrapper(*args, **kwargs):
                    try:
                        return test(*args, **kwargs)
                    except unittest.SkipTest as e:
                        raise e
                    except Exception as e:
                        tracked_input = get_tracked_input()
                        if PRINT_REPRO_ON_FAILURE and tracked_input is not None:
                            e_tracked = Exception(f'{str(e)}\n\nCaused by {tracked_input.type_desc} at index {tracked_input.index}: {_serialize_sample(tracked_input.val)}')
                            e_tracked._tracked_input = tracked_input
                            raise e_tracked from e
                        raise e
                    finally:
                        clear_tracked_input()
                if self.skip_if_dynamo and (not TEST_WITH_TORCHINDUCTOR):
                    test_wrapper = skipIfTorchDynamo("Policy: we don't run OpInfo tests w/ Dynamo")(test_wrapper)
                test.tracked_input = None
                decorator_fn = partial(op.get_decorators, generic_cls.__name__, test.__name__, device_cls.device_type, dtype)
                if sample_skips_and_xfails is not None:
                    test_wrapper.sample_skips_and_xfails = sample_skips_and_xfails
                yield (test_wrapper, test_name, param_kwargs, decorator_fn)
            except Exception as ex:
                print(f'Failed to instantiate {test_name} for op {op.name}!')
                raise ex
    if <MASK>:
        raise ValueError('An empty op_list was passed to @ops. Note that this may result from reuse of a generator.')

def is_free_format(fname):
    """Check if file is in free format Fortran."""
    result = False
    if <MASK>:
        result = True
    with openhook(fname, 'r') as fhandle:
        line = fhandle.readline()
        n = 15
        if _has_f_header(line):
            n = 0
        elif _has_f90_header(line):
            n = 0
            result = True
        while n > 0 and line:
            if line[0] != '!' and line.strip():
                n -= 1
                if line[0] != '\t' and _free_f90_start(line[:5]) or line[-2:-1] == '&':
                    result = True
                    break
            line = fhandle.readline()
    return result

def _reduction_configs(*, size_hints: dict[str, int], inductor_meta: dict[str, Any], triton_meta: dict[str, Any], num_dynamic=0) -> list[Config]:
    reduction_hint = inductor_meta.get('reduction_hint')
    rnumel = get_total_reduction_numel(size_hints)
    max_autotune_enabled = inductor_meta.get('max_autotune') or inductor_meta.get('max_autotune_pointwise')
    register_intensive = False
    MAX_R0_BLOCK = 2048
    loads_and_red = inductor_meta.get('num_load', 0) + inductor_meta.get('num_reduction', 0)
    if size_hints['x'] >= 1024 and loads_and_red >= 10:
        MAX_R0_BLOCK = 1024
        register_intensive = True
    if triton_meta.get('native_matmul'):
        if len(size_hints) == 3:
            return [make_matmul_triton_config(sizes, num_warps, num_stages) for (sizes, num_warps, num_stages) in triton_native_mm_configs]
        elif len(size_hints) == 4:
            return [make_matmul_triton_config(sizes, num_warps, num_stages) for (sizes, num_warps, num_stages) in triton_native_bmm_configs]
        else:
            raise NotImplementedError('native matmul only supports mm/bmm pattern')

    def make_config(x, r, num_warps=None, num_stages=1, register_intensive=False, dynamic_scale_rblock=True, waves_per_eu=None):
        if 'y' in size_hints:
            assert 'tiling_scores' in inductor_meta
            return adapt_config_for_tiling(size_hints, inductor_meta['tiling_scores'], x, r, num_warps=num_warps, num_stages=num_stages, register_intensive=register_intensive, waves_per_eu=waves_per_eu)
        else:
            return triton_config_reduction(size_hints, x, r, num_warps=num_warps, num_stages=num_stages, register_intensive=register_intensive, waves_per_eu=waves_per_eu, dynamic_scale_rblock=dynamic_scale_rblock, reduction_hint=reduction_hint)

    def outer_config_opt():
        (max_x_block, x_block) = (256, 64)
        load_factor = inductor_meta.get('num_load', 0)
        x = size_hints['x']
        num_warps = None
        if x <= 1024:
            x_block = max(min(x // 128, 8), 2)
            outer_r_block = min(rnumel, 64)
        elif x // 4096 <= 8:
            x_block = 16
            outer_r_block = 512 // x_block
        elif num_dynamic > 1:
            outer_r_block = max(min(rnumel // 64, 64), 8)
        elif num_dynamic == 1:
            outer_r_block = 1 if load_factor >= 3 else min(next_power_of_2(max(rnumel, 128) // 128), 8)
        else:
            x_block = max(min(max_x_block, next_power_of_2(x // 4096)), x_block)
            if load_factor < 4 or rnumel <= 128:
                outer_r_block = 512 // x_block
            else:
                if rnumel >= 2048:
                    outer_r_block = 64
                else:
                    outer_r_block = 32
                x_block = min(x_block, 32)
                num_warps = 4
        return make_config(x_block, outer_r_block, num_warps=num_warps, register_intensive=register_intensive)
    contiguous_config = make_config(2 if rnumel <= 2048 and (not is_fbcode()) else 1, min(rnumel, MAX_R0_BLOCK), register_intensive=register_intensive)
    tiny_config = make_config(2 * (256 // rnumel) if rnumel <= 256 else 1, min(rnumel, MAX_R0_BLOCK), register_intensive=register_intensive)
    outer_config = make_config(64, 8, register_intensive=register_intensive)
    if not torch.version.hip and (not is_fbcode()):
        outer_config = outer_config_opt()
    configs = []
    if inductor_meta.get('add_persistent_rblock') and loads_and_red <= 8:
        xnumel = max(4096 // rnumel, 1)
        c = make_config(xnumel, min(rnumel, 32768), register_intensive=register_intensive, dynamic_scale_rblock=False)
        configs.append(c)
    result_configs = []
    if 'y' in size_hints:
        pass
    elif max_autotune_enabled:
        pass
    elif reduction_hint == ReductionHint.INNER:
        return configs + [contiguous_config]
    elif reduction_hint == ReductionHint.OUTER:
        return configs + [outer_config]
    elif reduction_hint == ReductionHint.OUTER_TINY:
        return configs + [tiny_config]
    result_configs = configs + [contiguous_config, outer_config, tiny_config, make_config(64, 64), make_config(8, 512), make_config(64, 4, num_warps=8)]
    if <MASK>:
        result_configs.extend([make_config(1024, 8, num_warps=4, num_stages=1, waves_per_eu=2), make_config(512, 8, num_warps=4, num_stages=1, waves_per_eu=1)])
    return result_configs

def __eq__(self, other: object) -> bool:
    if not isinstance(other, OpSchema):
        return False
    if <MASK>:
        return False
    if len(self.args_schema) != len(other.args_schema):
        return False
    return self._comparison_key == other._comparison_key

def _infer_inputs(self, layer_node_id, convert_to_shapes=False):
    """Infers input shape of layer from SavedModel functions."""
    call_fn_id = self._search_for_child_node(layer_node_id, ['call_and_return_all_conditional_losses'])
    if <MASK>:
        return None
    concrete_functions = self._proto.nodes[call_fn_id].function.concrete_functions
    if not concrete_functions:
        return None
    call_fn_name = concrete_functions[0]
    call_fn_proto = self._proto.concrete_functions[call_fn_name]
    structured_input_signature = nested_structure_coder.decode_proto(call_fn_proto.canonicalized_input_signature)
    inputs = structured_input_signature[0][0]
    if convert_to_shapes:
        return nest.map_structure(lambda spec: spec.shape, inputs)
    else:
        return inputs

def autoDiffErrorMessage(self, should_autodiff_node, nodes_not_in_diff_graph, fusion_nodes_not_found, non_fusible_nodes_being_fused, fusion_nodes_found, nodes_in_diff_graph):
    err_msg = "\nFailure in testing nodes' autodifferentiation. "
    if should_autodiff_node:
        err_msg += 'One or more nodes were expected to be autodiffed, but were not found in specified fusible/nonfusible DifferentiableGraph groups. \nSpecifically:'
        diff_nodes_missing = []
        diff_nodes_in_fusion = []
        fusion_nodes_missing = []
        fusion_nodes_in_diff = []
        for node in nodes_not_in_diff_graph:
            if <MASK>:
                diff_nodes_in_fusion.append(node)
            else:
                diff_nodes_missing.append(node)
        for node in fusion_nodes_not_found:
            if node in nodes_in_diff_graph:
                fusion_nodes_in_diff.append(node)
            else:
                fusion_nodes_missing.append(node)
        if len(diff_nodes_missing) > 0:
            err_msg += f'\n  {diff_nodes_missing} were not in one of the DifferentiableGraphs when they were expected to be. Did you intend for these nodes to be autodiffed? If not, remove them from the list of nonfusible nodes.'
        if len(diff_nodes_in_fusion) > 0:
            err_msg += f'\n  {diff_nodes_in_fusion} were found in one of the FusionGroups when they were expected to be just in a DifferentiableGraph. If it was intended for these nodes to be in FusionGroups, reclassify these nodes as fusible nodes. If these nodes were not intended to be fused, your autodifferentiation logic might be wrong.'
        if len(fusion_nodes_missing) > 0:
            err_msg += f"\n  {fusion_nodes_missing} were not in one of the FusionGroups of the DifferentiableGraphs when they were expected to be. They were also not found in an outer DifferentiableGraph. Did you intend for these nodes to be autodifferentiated? If not, you should remove these nodes from the test's fusible nodes. Otherwise your autodifferentiation logic might be wrong."
        if len(fusion_nodes_in_diff) > 0:
            err_msg += f"\n  {fusion_nodes_in_diff} were not in one of the FusionGroups of the DifferentiableGraphs when they were expected to be, instead they were found just in an outer DifferentiableGraph. Did you intend for these nodes to be fused? If not, you should move these nodes into the test's nonfusible nodes. Otherwise your autodifferentiation logic might be wrong."
    else:
        err_msg += 'One or more nodes were not expected to be autodiffed but were found in a DifferentiableGraph or in a FusionGroup of a DifferentiableGraph. Did you intend for these nodes to be autodiffed? If so, change this test to expect autodifferentiation. \nSpecifically:'
        if len(fusion_nodes_found) > 0:
            err_msg += f'\n  {fusion_nodes_found} were not expected to be in one of the DifferentiableGraphs, but appeared in a FusionGroup of a DifferentiableGraph. '
        if len(nodes_in_diff_graph) > 0:
            err_msg += f'\n  {nodes_in_diff_graph} were not expected to be in one of the DifferentiableGraphs but were.'
    return err_msg

def fallback_node_due_to_unsupported_type(node: torch.fx.Node, allow_cpu_inputs=True):
    if node.target is aten.view_as_complex.default:
        return False
    if node.op == 'placeholder':
        return False
    if node.target is aten.lift_fresh_copy.default:
        return False

    def check_skip_condition(inp_out_node, is_output):
        if not isinstance(inp_out_node, torch.fx.Node):
            return False
        if 'val' not in inp_out_node.meta:
            return False
        for meta in pytree.tree_leaves(inp_out_node.meta['val']):
            if not isinstance(meta, torch._subclasses.FakeTensor):
                continue
            if <MASK>:
                if unsupported_output_tensor(meta, node):
                    return True
            elif unsupported_input_tensor(meta, node):
                return True
        return False
    for arg in pytree.arg_tree_leaves(*node.args, **node.kwargs):
        if check_skip_condition(arg, is_output=False):
            return True
    return check_skip_condition(node, is_output=True)

