        return translation.get_language_info(language[0])
    else:
        return translation.get_language_info(str(language))

def _get_ps_strategy_creator(num_workers, num_ps, required_gpus=0, variable_partitioner=DEFAULT_PARTITIONER):

    def _create_ps_strategy(resolver, variable_partitioner):
        return parameter_server_strategy_v2.ParameterServerStrategyV2(resolver, variable_partitioner=variable_partitioner)

    def _create_parameter_server():
        if framework_test_util.is_xla_enabled():
            cluster_def = multi_worker_test_base.create_in_process_cluster(num_workers=num_workers, num_ps=num_ps, rpc_layer='grpc')
            resolver = cluster_resolver.SimpleClusterResolver(server_lib.ClusterSpec(cluster_def), num_accelerators={'GPU': required_gpus}, rpc_layer='grpc')
            return _create_ps_strategy(resolver, variable_partitioner)
        else:
            tf_config = cluster_resolver.TFConfigClusterResolver()
            cluster_def = tf_config.cluster_spec().as_dict()
            if not cluster_def:
                return None
            resolver = cluster_resolver.SimpleClusterResolver(server_lib.ClusterSpec(cluster_def), num_accelerators={'GPU': required_gpus}, task_type=tf_config.task_type, task_id=tf_config.task_id, environment=tf_config.environment, rpc_layer=tf_config.rpc_layer or 'grpc')
            if <MASK>:
                worker_config = config_pb2.ConfigProto()
                worker_config.inter_op_parallelism_threads = 4
                try:
                    server = server_lib.Server(cluster_def, job_name=tf_config.task_type, task_index=tf_config.task_id, protocol='grpc', config=worker_config)
                except errors.UnknownError as e:
                    if 'Could not start gRPC server' in e.message:
                        raise unittest.SkipTest('Cannot start std servers.')
                    else:
                        raise
                server.join()
            return _create_ps_strategy(resolver, variable_partitioner)
    return _create_parameter_server

def _to_bytes_or_str_array(result, output_dtype_like):
    """
    Helper function to cast a result back into an array
    with the appropriate dtype if an object array must be used
    as an intermediary.
    """
    output_dtype_like = np.asarray(output_dtype_like)
    if result.size == 0:
        return result.astype(output_dtype_like.dtype)
    ret = np.asarray(result.tolist())
    if <MASK>:
        return ret.astype(type(output_dtype_like.dtype))
    return ret.astype(type(output_dtype_like.dtype)(_get_num_chars(ret)))

def _test_input_iteration(self, input_type, api_type, iteration_type, dataset_or_input_fn, worker_device_pairs, expected_values, strategy, sess=None, num_replicas_in_sync=None, input_context=None):
    if iteration_type == 'for_loop' and (not context.executing_eagerly()):
        self.skipTest('unsupported test combination.')
    if api_type == 'wrap_into_iterator' and iteration_type == 'for_loop':
        self.skipTest('unsupported test combination.')
    if api_type == 'wrap_into_iterator' and input_type == 'input_fn':
        self.skipTest('unsupported test combination.')
    devices = nest.flatten([ds for (_, ds) in worker_device_pairs])
    input_workers = input_lib.InputWorkers(worker_device_pairs)
    if api_type == 'wrap_into_iterator':
        iterator = self._wrap_iterator(input_type, dataset_or_input_fn, input_workers, devices, num_replicas_in_sync, strategy, input_context=input_context)
    else:
        dataset = self._wrap_dataset(input_type, dataset_or_input_fn, input_workers, num_replicas_in_sync, strategy, input_context=input_context)
        if ops.executing_eagerly_outside_functions():
            iterator = iter(dataset)
        elif isinstance(dataset, input_lib_v1.DistributedDatasetV1):
            iterator = dataset.make_initializable_iterator()
        else:
            self.skipTest('unsupported test combination')
    if isinstance(iterator, composite_tensor.CompositeTensor):
        nest.assert_same_structure(iterator, iterator._type_spec, expand_composites=True)
    if <MASK>:
        evaluate = lambda x: sess.run(x) if sess else self.evaluate(x)
        if not ops.executing_eagerly_outside_functions():
            evaluate(control_flow_ops.group(iterator.initializer))

        def test_get_next(iterator):
            self._assert_iterator_values(iterator, expected_values, evaluate, devices)
            with self.assertRaises(errors.OutOfRangeError):
                self._assert_iterator_values(iterator, expected_values, evaluate, devices)
            if not ops.executing_eagerly_outside_functions():
                evaluate(control_flow_ops.group(iterator.initializer))
            elif api_type == 'wrap_into_iterator':
                self.skipTest('unsupported test combination')
            else:
                iterator = iter(dataset)
            self._assert_iterator_values(iterator, expected_values, evaluate, devices)

        def test_get_next_as_optional(iterator):
            self._assert_iterator_values(iterator, expected_values, evaluate, devices, enable_get_next_as_optional=True)
            next_element = iterator.get_next_as_optional()
            self.assertFalse(self.evaluate(next_element.has_value()))
            with self.assertRaises(errors.InvalidArgumentError):
                self._assert_iterator_values(iterator, [0], evaluate, devices, enable_get_next_as_optional=True)
        test_get_next(iterator)
        if not tf2.enabled():
            return
        elif api_type == 'wrap_into_iterator':
            return
        else:
            iterator = iter(dataset)
        test_get_next_as_optional(iterator)
    if iteration_type == 'for_loop' and context.executing_eagerly():
        self._assert_dataset_values_for_loop(dataset, expected_values, self.evaluate, devices)

def _insert_strls(self, data: DataFrame) -> DataFrame:
    if <MASK>:
