def validate(self, other) -> None:
    """validate against an existing table"""
    if other is None:
        return
    if other.table_type != self.table_type:
        raise TypeError(f'incompatible table_type with existing [{other.table_type} - {self.table_type}]')
    for c in ['index_axes', 'non_index_axes', 'values_axes']:
        sv = getattr(self, c, None)
        ov = getattr(other, c, None)
        if sv != ov:
            for (i, sax) in enumerate(sv):
                oax = ov[i]
                if sax != oax:
                    if <MASK>:
                        raise ValueError(f'Cannot serialize the column [{oax.values[0]}] because its data contents are not [{sax.kind}] but [{oax.kind}] object dtype')
                    raise ValueError(f'invalid combination of [{c}] on appending data [{sax}] vs current table [{oax}]')
            raise Exception(f'invalid combination of [{c}] on appending data [{sv}] vs current table [{ov}]')

def __init__(self, geom):
    """
        Oracle requires that polygon rings are in proper orientation. This
        affects spatial operations and an invalid orientation may cause
        failures. Correct orientations are:
         * Outer ring - counter clockwise
         * Inner ring(s) - clockwise
        """
    if <MASK>:
        if self._polygon_must_be_fixed(geom):
            geom = self._fix_polygon(geom)
    elif isinstance(geom, GeometryCollection):
        if any((isinstance(g, Polygon) and self._polygon_must_be_fixed(g) for g in geom)):
            geom = self._fix_geometry_collection(geom)
    self.wkt = geom.wkt
    self.srid = geom.srid

def add_type_constraints(function_type: FunctionType, input_signature: Any, default_values: Dict[str, Any]) -> FunctionType:
    """Adds type constraints to a FunctionType based on the input_signature."""
    context = trace_type.InternalTracingContext(is_legacy_signature=True)
    constraints = [trace_type.from_value(c, context) for c in input_signature]
    parameters = []
    has_var_pos = any((p.kind is p.VAR_POSITIONAL for p in function_type.parameters.values()))
    for param in function_type.parameters.values():
        sanitized_kind = param.POSITIONAL_ONLY if has_var_pos and param.kind is param.POSITIONAL_OR_KEYWORD else param.kind
        if param.name == 'self':
            parameters.append(Parameter('self', sanitized_kind, param.optional, None))
        elif param.kind is param.VAR_KEYWORD:
            continue
        elif param.kind is param.VAR_POSITIONAL:
            for i in range(len(constraints)):
                parameters.append(Parameter(param.name + '_' + str(i), Parameter.POSITIONAL_ONLY, False, constraints.pop(0)))
        elif <MASK>:
            if param.kind is param.KEYWORD_ONLY and param.name not in default_values:
                raise TypeError(f'Since input_signature is defined, keyword-only parameter `{param.name}` must have a default value')
            if constraints:
                parameters.append(Parameter(param.name, sanitized_kind, param.optional, constraints.pop(0)))
            elif param.name in default_values:
                type_constraint = trace_type.from_value(default_values[param.name])
                parameters.append(Parameter(param.name, sanitized_kind, param.optional, type_constraint))
            else:
                raise TypeError(f'input_signature missing type constraint for {param.name}')
    if constraints:
        raise TypeError(f'input_signature contains {len(constraints)} extra type constraints.')
    return FunctionType(parameters)

def analyzecommon(block):
    if not hascommon(block):
        return block
    commonvars = []
    for k in list(block['common'].keys()):
        comvars = []
        for e in block['common'][k]:
            m = re.match('\\A\\s*\\b(?P<name>.*?)\\b\\s*(\\((?P<dims>.*?)\\)|)\\s*\\Z', e, re.I)
            if <MASK>:
                dims = []
                if m.group('dims'):
                    dims = [x.strip() for x in markoutercomma(m.group('dims')).split('@,@')]
                n = rmbadname1(m.group('name').strip())
                if n in block['vars']:
                    if 'attrspec' in block['vars'][n]:
                        block['vars'][n]['attrspec'].append(f"dimension({','.join(dims)})")
                    else:
                        block['vars'][n]['attrspec'] = [f"dimension({','.join(dims)})"]
                elif dims:
                    block['vars'][n] = {'attrspec': [f"dimension({','.join(dims)})"]}
                else:
                    block['vars'][n] = {}
                if n not in commonvars:
                    commonvars.append(n)
            else:
                n = e
                errmess(f'analyzecommon: failed to extract "<name>[(<dims>)]" from "{e}" in common /{k}/.\n')
            comvars.append(n)
        block['common'][k] = comvars
    if 'commonvars' not in block:
        block['commonvars'] = commonvars
    else:
        block['commonvars'] = block['commonvars'] + commonvars
    return block

def _str_split(self, pat: str | None=None, n: int | None=-1, expand: bool=False, regex: bool | None=None) -> Self:
    if <MASK>:
        n = None
    if pat is None:
        split_func = pc.utf8_split_whitespace
    elif regex:
        split_func = functools.partial(pc.split_pattern_regex, pattern=pat)
    else:
        split_func = functools.partial(pc.split_pattern, pattern=pat)
    return self._from_pyarrow_array(split_func(self._pa_array, max_splits=n))

def CheckVersusNumpy(self, ndims_mask, arr_shape, make_mask=None, axis=None):
    """Check equivalence between boolean_mask and numpy masking."""
    if make_mask is None:
        make_mask = lambda shape: self.rng.randint(0, 2, size=shape).astype(bool)
    arr = np.random.rand(*arr_shape)
    mask = make_mask(arr_shape[:ndims_mask])
    if <MASK>:
        mask = make_mask(arr_shape[axis:ndims_mask + axis])
    if axis is None or axis == 0:
        masked_arr = arr[mask]
    elif axis == 1:
        masked_arr = arr[:, mask]
    elif axis == 2:
        masked_arr = arr[:, :, mask]
    masked_tensor = array_ops.boolean_mask(arr, mask, axis=axis)
    leading = 1 if axis is None else axis + 1
    self.assertAllEqual(masked_tensor.get_shape()[leading:], masked_arr.shape[leading:])
    self.assertAllClose(masked_arr, masked_tensor)

def node_to_str(self, tree, node_id, criterion):
    if tree.n_outputs == 1:
        value = tree.value[node_id][0, :]
    else:
        value = tree.value[node_id]
    labels = self.label == 'root' and node_id == 0 or self.label == 'all'
    characters = self.characters
    node_string = characters[-1]
    if self.node_ids:
        if labels:
            node_string += 'node '
        node_string += characters[0] + str(node_id) + characters[4]
    if tree.children_left[node_id] != _tree.TREE_LEAF:
        if self.feature_names is not None:
            feature = self.feature_names[tree.feature[node_id]]
            feature = self.str_escape(feature)
        else:
            feature = 'x%s%s%s' % (characters[1], tree.feature[node_id], characters[2])
        node_string += '%s %s %s%s' % (feature, characters[3], round(tree.threshold[node_id], self.precision), characters[4])
    if self.impurity:
        if isinstance(criterion, _criterion.FriedmanMSE):
            criterion = 'friedman_mse'
        elif isinstance(criterion, _criterion.MSE) or criterion == 'squared_error':
            criterion = 'squared_error'
        elif not isinstance(criterion, str):
            criterion = 'impurity'
        if labels:
            node_string += '%s = ' % criterion
        node_string += str(round(tree.impurity[node_id], self.precision)) + characters[4]
    if labels:
        node_string += 'samples = '
    if self.proportion:
        percent = 100.0 * tree.n_node_samples[node_id] / float(tree.n_node_samples[0])
        node_string += str(round(percent, 1)) + '%' + characters[4]
    else:
        node_string += str(tree.n_node_samples[node_id]) + characters[4]
    if not self.proportion and tree.n_classes[0] != 1:
        value = value * tree.weighted_n_node_samples[node_id]
    if labels:
        node_string += 'value = '
    if tree.n_classes[0] == 1:
        value_text = np.around(value, self.precision)
    elif self.proportion:
        value_text = np.around(value, self.precision)
    elif np.all(np.equal(np.mod(value, 1), 0)):
        value_text = value.astype(int)
    else:
        value_text = np.around(value, self.precision)
    value_text = str(value_text.astype('S32')).replace("b'", "'")
    value_text = value_text.replace("' '", ', ').replace("'", '')
    if <MASK>:
        value_text = value_text.replace('[', '').replace(']', '')
    value_text = value_text.replace('\n ', characters[4])
    node_string += value_text + characters[4]
    if self.class_names is not None and tree.n_classes[0] != 1 and (tree.n_outputs == 1):
        if labels:
            node_string += 'class = '
        if self.class_names is not True:
            class_name = self.class_names[np.argmax(value)]
            class_name = self.str_escape(class_name)
        else:
            class_name = 'y%s%s%s' % (characters[1], np.argmax(value), characters[2])
        node_string += class_name
    if node_string.endswith(characters[4]):
        node_string = node_string[:-len(characters[4])]
    return node_string + characters[5]

@functools.wraps(f)
def inner(*args, **kwargs):
    allowed_types = (Tensor, torch.types._Number) if include_non_tensor_args else (Tensor,)
    flat_args = [x for x in pytree.arg_tree_leaves(*args, **kwargs) if isinstance(x, allowed_types)]
    (computation_dtype, result_dtype) = utils.elementwise_dtypes(*flat_args, type_promotion_kind=type_promotion)

    def increase_prec(x):
        if <MASK>:
            return x.to(computation_dtype)
        else:
            return x

    def decrease_prec(x):
        if isinstance(x, Tensor):
            return x.to(result_dtype)
        else:
            return x
    r = f(*tree_map(increase_prec, args), **tree_map(increase_prec, kwargs))
    if compute_dtype_only:
        return r
    else:
        return tree_map(decrease_prec, r)

def read(self, path, columns=None, filters=None, storage_options: StorageOptions | None=None, filesystem=None, to_pandas_kwargs: dict | None=None, **kwargs) -> DataFrame:
    parquet_kwargs: dict[str, Any] = {}
    dtype_backend = kwargs.pop('dtype_backend', lib.no_default)
    parquet_kwargs['pandas_nulls'] = False
    if dtype_backend is not lib.no_default:
        raise ValueError("The 'dtype_backend' argument is not supported for the fastparquet engine")
    if filesystem is not None:
        raise NotImplementedError('filesystem is not implemented for the fastparquet engine.')
    if to_pandas_kwargs is not None:
        raise NotImplementedError('to_pandas_kwargs is not implemented for the fastparquet engine.')
    path = stringify_path(path)
    handles = None
    if is_fsspec_url(path):
        fsspec = import_optional_dependency('fsspec')
        parquet_kwargs['fs'] = fsspec.open(path, 'rb', **storage_options or {}).fs
    elif isinstance(path, str) and (not os.path.isdir(path)):
        handles = get_handle(path, 'rb', is_text=False, storage_options=storage_options)
        path = handles.handle
    try:
        parquet_file = self.api.ParquetFile(path, **parquet_kwargs)
        with catch_warnings():
            filterwarnings('ignore', 'make_block is deprecated', Pandas4Warning)
            return parquet_file.to_pandas(columns=columns, filters=filters, **kwargs)
    finally:
        if <MASK>:
            handles.close()

@final
def _infer_types(self, values, na_values, no_dtype_specified, try_num_bool: bool=True) -> tuple[ArrayLike, int]:
    """
        Infer types of values, possibly casting

        Parameters
        ----------
        values : ndarray
        na_values : set
        no_dtype_specified: Specifies if we want to cast explicitly
        try_num_bool : bool, default try
           try to cast values to numeric (first preference) or boolean

        Returns
        -------
        converted : ndarray or ExtensionArray
        na_count : int
        """
    na_count = 0
    if issubclass(values.dtype.type, (np.number, np.bool_)):
        na_values = np.array([val for val in na_values if not isinstance(val, str)])
        mask = algorithms.isin(values, na_values)
        na_count = mask.astype('uint8', copy=False).sum()
        if na_count > 0:
            if is_integer_dtype(values):
                values = values.astype(np.float64)
            np.putmask(values, mask, np.nan)
        return (values, na_count)
    dtype_backend = self.dtype_backend
    non_default_dtype_backend = no_dtype_specified and dtype_backend is not lib.no_default
    result: ArrayLike
    if try_num_bool and is_object_dtype(values.dtype):
        try:
            (result, result_mask) = lib.maybe_convert_numeric(values, na_values, False, convert_to_masked_nullable=non_default_dtype_backend)
        except (ValueError, TypeError):
            na_count = parsers.sanitize_objects(values, na_values)
            result = values
        else:
            if non_default_dtype_backend:
                if result_mask is None:
                    result_mask = np.zeros(result.shape, dtype=np.bool_)
                if <MASK>:
                    result = IntegerArray(np.ones(result_mask.shape, dtype=np.int64), result_mask)
                elif is_integer_dtype(result):
                    result = IntegerArray(result, result_mask)
                elif is_bool_dtype(result):
                    result = BooleanArray(result, result_mask)
                elif is_float_dtype(result):
                    result = FloatingArray(result, result_mask)
                na_count = result_mask.sum()
            else:
                na_count = isna(result).sum()
    else:
        result = values
        if values.dtype == np.object_:
            na_count = parsers.sanitize_objects(values, na_values)
    if result.dtype == np.object_ and try_num_bool:
        (result, bool_mask) = libops.maybe_convert_bool(np.asarray(values), true_values=self.true_values, false_values=self.false_values, convert_to_masked_nullable=non_default_dtype_backend)
        if result.dtype == np.bool_ and non_default_dtype_backend:
            if bool_mask is None:
                bool_mask = np.zeros(result.shape, dtype=np.bool_)
            result = BooleanArray(result, bool_mask)
        elif result.dtype == np.object_ and non_default_dtype_backend:
            if not lib.is_datetime_array(result, skipna=True):
                dtype = StringDtype()
                cls = dtype.construct_array_type()
                result = cls._from_sequence(values, dtype=dtype)
    if dtype_backend == 'pyarrow':
        pa = import_optional_dependency('pyarrow')
        if isinstance(result, np.ndarray):
            result = ArrowExtensionArray(pa.array(result, from_pandas=True))
        elif isinstance(result, BaseMaskedArray):
            if result._mask.all():
                result = ArrowExtensionArray(pa.array([None] * len(result)))
            else:
                result = ArrowExtensionArray(pa.array(result._data, mask=result._mask))
        else:
            result = ArrowExtensionArray(pa.array(result.to_numpy(), from_pandas=True))
    return (result, na_count)

def _serialize_object_graph(saveable_view: _SaveableView, asset_file_def_index):
    """Save a SavedObjectGraph proto for `root`."""
    proto = saved_object_graph_pb2.SavedObjectGraph()
    saveable_view.fill_object_graph_proto(proto)
    for concrete_function in saveable_view.concrete_and_gradient_functions:
        name = compat.as_text(concrete_function.name)
        serialized = function_serialization.serialize_concrete_function(concrete_function, saveable_view.captured_tensor_node_ids)
        if <MASK>:
            proto.concrete_functions[name].CopyFrom(serialized)
    for (obj, obj_proto) in zip(saveable_view.nodes, proto.nodes):
        _write_object_proto(obj, obj_proto, asset_file_def_index, saveable_view.augmented_graph_view.list_children)
    return proto

def _wait_for_variable_initialization(session):
    """Utility to wait for variables to be initialized."""
    all_variables = backend._get_variables(backend.get_graph())
    candidate_vars = []
    for v in all_variables:
        if not getattr(v, '_keras_initialized', False):
            candidate_vars.append(v)
    if not candidate_vars:
        return
    while True:
        is_initialized = session.run([variable_v1.is_variable_initialized(v) for v in candidate_vars])
        uninitialized_vars = []
        for (flag, v) in zip(is_initialized, candidate_vars):
            if not flag:
                uninitialized_vars.append(v)
            v._keras_initialized = True
        if <MASK>:
            break

def validate_input_col(fn: Callable, input_col: Optional[Union[int, tuple, list]]):
    """
    Check that function used in a callable datapipe works with the input column.

    This simply ensures that the number of positional arguments matches the size
    of the input column. The function must not contain any non-default
    keyword-only arguments.

    Examples:
        >>> # xdoctest: +SKIP("Failing on some CI machines")
        >>> def f(a, b, *, c=1):
        >>>     return a + b + c
        >>> def f_def(a, b=1, *, c=1):
        >>>     return a + b + c
        >>> assert validate_input_col(f, [1, 2])
        >>> assert validate_input_col(f_def, 1)
        >>> assert validate_input_col(f_def, [1, 2])

    Notes:
        If the function contains variable positional (`inspect.VAR_POSITIONAL`) arguments,
        for example, f(a, *args), the validator will accept any size of input column
        greater than or equal to the number of positional arguments.
        (in this case, 1).

    Args:
        fn: The function to check.
        input_col: The input column to check.

    Raises:
        ValueError: If the function is not compatible with the input column.
    """
    try:
        sig = inspect.signature(fn)
    except ValueError:
        return
    if isinstance(input_col, (list, tuple)):
        input_col_size = len(input_col)
    else:
        input_col_size = 1
    pos = []
    var_positional = False
    non_default_kw_only = []
    for p in sig.parameters.values():
        if <MASK>:
            pos.append(p)
        elif p.kind is inspect.Parameter.VAR_POSITIONAL:
            var_positional = True
        elif p.kind is inspect.Parameter.KEYWORD_ONLY:
            if p.default is p.empty:
                non_default_kw_only.append(p)
        else:
            continue
    if isinstance(fn, functools.partial):
        fn_name = getattr(fn.func, '__name__', repr(fn.func))
    else:
        fn_name = getattr(fn, '__name__', repr(fn))
    if len(non_default_kw_only) > 0:
        raise ValueError(f'The function {fn_name} takes {len(non_default_kw_only)} non-default keyword-only parameters, which is not allowed.')
    if len(sig.parameters) < input_col_size:
        if not var_positional:
            raise ValueError(f'The function {fn_name} takes {len(sig.parameters)} parameters, but {input_col_size} are required.')
    elif len(pos) > input_col_size:
        if any((p.default is p.empty for p in pos[input_col_size:])):
            raise ValueError(f'The function {fn_name} takes {len(pos)} positional parameters, but {input_col_size} are required.')
    elif len(pos) < input_col_size:
        if not var_positional:
            raise ValueError(f'The function {fn_name} takes {len(pos)} positional parameters, but {input_col_size} are required.')

def rekey_logger_info_on_node_name_of_model(results: NSResultsType, model_name: str) -> NSResultsType:
    """
    Rekeys the layer name of a results dictionary to use node names
    from `model_name`.

    For example, transforms

        {'base_op_1_0': {'node_output': {'model_a':
          [{'ref_node_name': 'linear1', ...}]}}}

    into

        {'linear1': {'node_output': {'model_a':
          [{'ref_node_name': 'linear1', ...}]}}}

    Note: we cannot use these node names directly because they are not
    guaranteed to be consistent across models. This is why we extract
    the results first and rekey afterwards.
    """
    new_results = {}
    for (old_layer_name, result_type_to_results) in results.items():
        new_layer_name = None
        for model_name_to_results in result_type_to_results.values():
            for (cur_model_name, list_of_results) in model_name_to_results.items():
                if cur_model_name == model_name:
                    if len(list_of_results) == 0:
                        raise AssertionError('Expected list_of_results to be not empty')
                    new_layer_name = list_of_results[0]['ref_node_name']
                else:
                    continue
        if <MASK>:
            new_results[new_layer_name] = result_type_to_results
        else:
            new_results[old_layer_name] = result_type_to_results
    return new_results

def _get_loc_level(self, key, level: int | list[int]=0):
    """
        get_loc_level but with `level` known to be positional, not name-based.
        """

    def maybe_mi_droplevels(indexer, levels):
        """
            If level does not exist or all levels were dropped, the exception
            has to be handled outside.
            """
        new_index = self[indexer]
        for i in sorted(levels, reverse=True):
            new_index = new_index._drop_level_numbers([i])
        return new_index
    if isinstance(level, (tuple, list)):
        if len(key) != len(level):
            raise AssertionError('Key for location must have same length as number of levels')
        result = None
        for (lev, k) in zip(level, key, strict=True):
            (loc, new_index) = self._get_loc_level(k, level=lev)
            if <MASK>:
                mask = np.zeros(len(self), dtype=bool)
                mask[loc] = True
                loc = mask
            result = loc if result is None else result & loc
        try:
            mi = maybe_mi_droplevels(result, level)
        except ValueError:
            mi = self[result]
        return (result, mi)
    if isinstance(key, list):
        key = tuple(key)
    if isinstance(key, tuple) and level == 0:
        try:
            if key in self.levels[0]:
                indexer = self._get_level_indexer(key, level=level)
                new_index = maybe_mi_droplevels(indexer, [0])
                return (indexer, new_index)
        except (TypeError, InvalidIndexError):
            pass
        if not any((isinstance(k, slice) for k in key)):
            if len(key) == self.nlevels and self.is_unique:
                try:
                    return (self._engine.get_loc(key), None)
                except KeyError as err:
                    raise KeyError(key) from err
                except TypeError:
                    pass
            indexer = self.get_loc(key)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            if len(ilevels) == self.nlevels:
                if is_integer(indexer):
                    return (indexer, None)
                ilevels = [i for i in range(len(key)) if (not isinstance(key[i], str) or not self.levels[i]._supports_partial_string_indexing) and key[i] != slice(None, None)]
                if len(ilevels) == self.nlevels:
                    ilevels = []
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
        else:
            indexer = None
            for (i, k) in enumerate(key):
                if not isinstance(k, slice):
                    loc_level = self._get_level_indexer(k, level=i)
                    if isinstance(loc_level, slice):
                        if com.is_null_slice(loc_level) or com.is_full_slice(loc_level, len(self)):
                            continue
                        k_index = np.zeros(len(self), dtype=bool)
                        k_index[loc_level] = True
                    else:
                        k_index = loc_level
                elif com.is_null_slice(k):
                    continue
                else:
                    raise TypeError(f'Expected label or tuple of labels, got {key}')
                if indexer is None:
                    indexer = k_index
                else:
                    indexer &= k_index
            if indexer is None:
                indexer = slice(None, None)
            ilevels = [i for i in range(len(key)) if key[i] != slice(None, None)]
            return (indexer, maybe_mi_droplevels(indexer, ilevels))
    else:
        indexer = self._get_level_indexer(key, level=level)
        if isinstance(key, str) and self.levels[level]._supports_partial_string_indexing:
            check = self.levels[level].get_loc(key)
            if not is_integer(check):
                return (indexer, self[indexer])
        try:
            result_index = maybe_mi_droplevels(indexer, [level])
        except ValueError:
            result_index = self[indexer]
        return (indexer, result_index)

def create_name(self, candidate: str, obj: Optional[Any]) -> str:
    """Create a unique name.

        Arguments:
            candidate: used as the basis for the unique name, relevant to the user.
            obj: If not None, an object that will be associated with the unique name.
        """
    if obj is not None and obj in self._obj_to_name:
        return self._obj_to_name[obj]
    match = _name_regex.match(candidate)
    if match is None:
        candidate = _illegal_char_regex.sub('_', candidate)
        if <MASK>:
            candidate = '_unnamed'
        if candidate[0].isdigit():
            candidate = f'_{candidate}'
        match = _name_regex.match(candidate)
        assert match is not None
    (base, num) = match.group(1, 2)
    if num is None or candidate in self._used_names:
        num = self._base_count.get(candidate, 0)
        if _illegal_names.get(candidate, obj) is not obj:
            num += 1
            candidate = f'{base}_{num}'
    else:
        num = int(num)
    while candidate in self._used_names:
        num += 1
        candidate = f'{base}_{num}'
    self._used_names.add(candidate)
    self._base_count[base] = num
    if obj is not None:
        self._obj_to_name[obj] = candidate
    return candidate

def visit_If(self, node):
    node.test = self.visit(node.test)
    (node.body, body_definitely_returns) = self._visit_statement_block(node, node.body)
    if body_definitely_returns:
        anno.setanno(node, BODY_DEFINITELY_RETURNS, True)
    (node.orelse, orelse_definitely_returns) = self._visit_statement_block(node, node.orelse)
    if <MASK>:
        anno.setanno(node, ORELSE_DEFINITELY_RETURNS, True)
    if body_definitely_returns and orelse_definitely_returns:
        self.state[_RewriteBlock].definitely_returns = True
    return node

