def refine_node(self, n: Node):
    """
        Returns a list of equality constraints for
        call_module and call_function nodes.
        Models the relation between input and output dimensions
        using constraints in case they are both tensors.
        All operations used in resnet50 are defined.
        """
    if n.type is None:
        n.type = Dyn
    n.type = self.replace_dyn_with_fresh_var(n.type)
    if n.op == 'call_function':
        if n.target in _REFINEMENT_RULES:
            self.constraints += _REFINEMENT_RULES[n.target](n)
    if n.op == 'call_module':
        module_instance = self.traced.get_submodule(n.target)
        if type(module_instance) in _REFINEMENT_RULES:
            self.constraints += _REFINEMENT_RULES[type(module_instance)](n)
    if <MASK>:

        def get_node_type(a):
            return a.type
        n.type = torch.fx.node.map_arg(n.args[0], get_node_type)
        return n.type

def conv_input_length(output_length, filter_size, padding, stride):
    """Determines input length of a convolution given output length.

  Args:
      output_length: integer.
      filter_size: integer.
      padding: one of "same", "valid", "full".
      stride: integer.

  Returns:
      The input length (integer).
  """
    if <MASK>:
        return None
    assert padding in {'same', 'valid', 'full'}
    if padding == 'same':
        pad = filter_size // 2
    elif padding == 'valid':
        pad = 0
    elif padding == 'full':
        pad = filter_size - 1
    return (output_length - 1) * stride - 2 * pad + filter_size

def _datetime_to_stata_elapsed_vec(dates: Series, fmt: str) -> Series:
    """
    Convert from datetime to SIF. https://www.stata.com/help.cgi?datetime

    Parameters
    ----------
    dates : Series
        Series or array containing datetime or datetime64[ns] to
        convert to the Stata Internal Format given by fmt
    fmt : str
        The format to convert to. Can be, tc, td, tw, tm, tq, th, ty
    """
    index = dates.index
    NS_PER_DAY = 24 * 3600 * 1000 * 1000 * 1000
    US_PER_DAY = NS_PER_DAY / 1000
    MS_PER_DAY = NS_PER_DAY / 1000000

    def parse_dates_safe(dates: Series, delta: bool=False, year: bool=False, days: bool=False) -> DataFrame:
        d = {}
        if lib.is_np_dtype(dates.dtype, 'M'):
            if delta:
                time_delta = dates.dt.as_unit('ms') - Timestamp(stata_epoch).as_unit('ms')
                d['delta'] = time_delta._values.view(np.int64)
            if days or year:
                date_index = DatetimeIndex(dates)
                d['year'] = date_index._data.year
                d['month'] = date_index._data.month
            if days:
                year_start = np.asarray(dates).astype('M8[Y]').astype(dates.dtype)
                diff = dates - year_start
                d['days'] = np.asarray(diff).astype('m8[D]').view('int64')
        elif infer_dtype(dates, skipna=False) == 'datetime':
            warnings.warn('Converting object-dtype columns of datetimes to datetime64 when writing to stata is deprecated. Call `df=df.infer_objects(copy=False)` before writing to stata instead.', Pandas4Warning, stacklevel=find_stack_level())
            if delta:
                delta = dates._values - stata_epoch

                def f(x: timedelta) -> float:
                    return US_PER_DAY * x.days + 1000000 * x.seconds + x.microseconds
                v = np.vectorize(f)
                d['delta'] = v(delta) // 1000
            if year:
                year_month = dates.apply(lambda x: 100 * x.year + x.month)
                d['year'] = year_month._values // 100
                d['month'] = year_month._values - d['year'] * 100
            if days:

                def g(x: datetime) -> int:
                    return (x - datetime(x.year, 1, 1)).days
                v = np.vectorize(g)
                d['days'] = v(dates)
        else:
            raise ValueError('Columns containing dates must contain either datetime64, datetime or null values.')
        return DataFrame(d, index=index)
    bad_loc = isna(dates)
    index = dates.index
    if <MASK>:
        if lib.is_np_dtype(dates.dtype, 'M'):
            dates._values[bad_loc] = to_datetime(stata_epoch)
        else:
            dates._values[bad_loc] = stata_epoch
    if fmt in ['%tc', 'tc']:
        d = parse_dates_safe(dates, delta=True)
        conv_dates = d.delta
    elif fmt in ['%tC', 'tC']:
        warnings.warn('Stata Internal Format tC not supported.', stacklevel=find_stack_level())
        conv_dates = dates
    elif fmt in ['%td', 'td']:
        d = parse_dates_safe(dates, delta=True)
        conv_dates = d.delta // MS_PER_DAY
    elif fmt in ['%tw', 'tw']:
        d = parse_dates_safe(dates, year=True, days=True)
        conv_dates = 52 * (d.year - stata_epoch.year) + d.days // 7
    elif fmt in ['%tm', 'tm']:
        d = parse_dates_safe(dates, year=True)
        conv_dates = 12 * (d.year - stata_epoch.year) + d.month - 1
    elif fmt in ['%tq', 'tq']:
        d = parse_dates_safe(dates, year=True)
        conv_dates = 4 * (d.year - stata_epoch.year) + (d.month - 1) // 3
    elif fmt in ['%th', 'th']:
        d = parse_dates_safe(dates, year=True)
        conv_dates = 2 * (d.year - stata_epoch.year) + (d.month > 6).astype(int)
    elif fmt in ['%ty', 'ty']:
        d = parse_dates_safe(dates, year=True)
        conv_dates = d.year
    else:
        raise ValueError(f'Format {fmt} is not a known Stata date format')
    conv_dates = Series(conv_dates, dtype=np.float64, copy=False)
    missing_value = struct.unpack('<d', b'\x00\x00\x00\x00\x00\x00\xe0\x7f')[0]
    conv_dates[bad_loc] = missing_value
    return Series(conv_dates, index=index, copy=False)

def get_hip_file_path(rel_filepath, is_pytorch_extension=False):
    """
    Returns the new name of the hipified file
    """
    if os.path.isabs(rel_filepath):
        raise AssertionError('rel_filepath must be a relative path')
    if not is_pytorch_extension and (not is_out_of_place(rel_filepath)):
        return rel_filepath
    (dirpath, filename) = os.path.split(rel_filepath)
    (root, ext) = os.path.splitext(filename)
    if <MASK>:
        ext = '.hip'
    orig_filename = filename
    orig_dirpath = dirpath
    dirpath = dirpath.replace('cuda', 'hip')
    dirpath = dirpath.replace('CUDA', 'HIP')
    dirpath = dirpath.replace('THC', 'THH')
    root = root.replace('cuda', 'hip')
    root = root.replace('CUDA', 'HIP')
    if dirpath != 'caffe2/core':
        root = root.replace('THC', 'THH')
    if not is_pytorch_extension and dirpath == orig_dirpath:
        dirpath = os.path.join(dirpath, 'hip')
    if is_pytorch_extension and dirpath == orig_dirpath and (root + ext == orig_filename):
        root = root + '_hip'
    return os.path.join(dirpath, root + ext)

def default_units(self, kwargs):
    """
        Return the unit value and the default units specified
        from the given keyword arguments dictionary.
        """
    val = 0.0
    default_unit = self.STANDARD_UNIT
    for (unit, value) in kwargs.items():
        if not isinstance(value, float):
            value = float(value)
        if <MASK>:
            val += self.UNITS[unit] * value
            default_unit = unit
        elif unit in self.ALIAS:
            u = self.ALIAS[unit]
            val += self.UNITS[u] * value
            default_unit = u
        else:
            lower = unit.lower()
            if lower in self.UNITS:
                val += self.UNITS[lower] * value
                default_unit = lower
            elif lower in self.LALIAS:
                u = self.LALIAS[lower]
                val += self.UNITS[u] * value
                default_unit = u
            else:
                raise AttributeError('Unknown unit type: %s' % unit)
    return (val, default_unit)

def dimlists(n: Optional[int]=None, sizes: Optional[list[Optional[int]]]=None) -> Union[DimList, tuple[DimList, ...]]:
    """
    Create and return one or more DimList objects.

    Similar to dims() but creates DimList objects instead.
    """
    specified_ndims = -1
    found_ndims = 0
    if sizes is not None:
        specified_ndims = len(sizes)
    if n is not None:
        specified_ndims = n
    frame = inspect.currentframe()
    if frame is None:
        raise RuntimeError('Unable to get current frame')
    frame = frame.f_back
    try:
        if frame is None:
            raise RuntimeError('Unable to get caller frame')
        code = frame.f_code
        lasti = frame.f_lasti
        decoder = _PyInstDecoder(code, lasti)
        if sys.version_info >= (3, 11):
            if decoder.opcode() == 'PRECALL':
                decoder.next()
        decoder.next()
        if _relevant_op(decoder.opcode()):
            found_ndims = 1
        elif decoder.opcode() == 'UNPACK_SEQUENCE':
            found_ndims = decoder.oparg()
            decoder.next()
        if specified_ndims == -1:
            if found_ndims == 0:
                raise SyntaxError('dimlists() must be assigned to a sequence of variable names or have argument n specified')
            specified_ndims = found_ndims
        if found_ndims != specified_ndims:
            found_ndims = 0

        def genobject(i: int) -> str:
            nonlocal found_ndims
            name = None
            if i < found_ndims:
                name = decoder.name()
            if not name:
                name = f'd{i}'
                found_ndims = 0
            else:
                decoder.next()
            return name
        if sizes is not None and len(sizes) != specified_ndims:
            raise ValueError(f'expected {specified_ndims} sizes but found {len(sizes)}')
        if <MASK>:
            name = genobject(0)
            return _create_dimlist(name, sizes[0] if sizes is not None else None)
        result = []
        for i in range(specified_ndims):
            name = genobject(i)
            size = sizes[i] if sizes is not None else None
            result.append(_create_dimlist(name, size))
        return tuple(result)
    finally:
        del frame

def __post_init__(self) -> None:
    if <MASK>:
        assert not self.pre_self_positional
    if self.tensor_options is None:
        assert not self.post_tensor_options_kwarg_only
    mutable_pre_self_positionals = [a for a in self.pre_self_positional if a.annotation is not None and a.annotation.is_write]
    assert len(mutable_pre_self_positionals) == 0, 'mutable pre_self_positional arguments are not currently supported in the schema'

def pytest_generate_tests(metafunc):
    """Parametrization of global_random_seed fixture

    based on the SKLEARN_TESTS_GLOBAL_RANDOM_SEED environment variable.

    The goal of this fixture is to prevent tests that use it to be sensitive
    to a specific seed value while still being deterministic by default.

    See the documentation for the SKLEARN_TESTS_GLOBAL_RANDOM_SEED
    variable for instructions on how to use this fixture.

    https://scikit-learn.org/dev/computing/parallelism.html#sklearn-tests-global-random-seed

    """
    RANDOM_SEED_RANGE = list(range(100))
    random_seed_var = environ.get('SKLEARN_TESTS_GLOBAL_RANDOM_SEED')
    default_random_seeds = [42]
    if random_seed_var is None:
        random_seeds = default_random_seeds
    elif random_seed_var == 'all':
        random_seeds = RANDOM_SEED_RANGE
    else:
        if '-' in random_seed_var:
            (start, stop) = random_seed_var.split('-')
            random_seeds = list(range(int(start), int(stop) + 1))
        else:
            random_seeds = [int(random_seed_var)]
        if min(random_seeds) < 0 or max(random_seeds) > 99:
            raise ValueError(f"The value(s) of the environment variable SKLEARN_TESTS_GLOBAL_RANDOM_SEED must be in the range [0, 99] (or 'all'), got: {random_seed_var}")
    if <MASK>:
        metafunc.parametrize('global_random_seed', random_seeds)

@register_make_test_function()
def make_depthwiseconv_tests(options):
    """Make a set of tests to do convolution."""
    test_parameters = [{'input_shape': [[1, 3, 4, 3], [1, 10, 10, 3]], 'filter_size': [[1, 1], [1, 2], [3, 3]], 'strides': [[1, 1, 1, 1], [1, 3, 3, 1]], 'dilations': [[1, 1, 1, 1], [1, 3, 2, 1], [1, 2, 2, 1]], 'channel_multiplier': [1, 2], 'rate': [[1, 1]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'constant_filter': [True, False], 'fully_quantize': [False], 'quant_16x8': [False]}, {'input_shape': [[1, 3, 4, 3]], 'filter_size': [[1, 1]], 'strides': [[1, 1, 2, 1]], 'dilations': [[1, 1, 1, 1], [1, 2, 2, 1]], 'channel_multiplier': [2], 'rate': [[2, 2]], 'padding': ['SAME'], 'data_format': ['NHWC'], 'constant_filter': [True, False], 'fully_quantize': [False], 'quant_16x8': [False]}, {'input_shape': [[1, 3, 4, 3], [1, 10, 10, 3]], 'filter_size': [[1, 1], [1, 2], [3, 3]], 'strides': [[1, 1, 1, 1], [1, 3, 3, 1]], 'dilations': [[1, 1, 1, 1], [1, 3, 2, 1], [1, 2, 2, 1]], 'channel_multiplier': [1, 2], 'rate': [[1, 1]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'constant_filter': [True], 'fully_quantize': [True], 'quant_16x8': [False]}, {'input_shape': [[1, 3, 3, 3000]], 'filter_size': [[3, 3]], 'strides': [[1, 1, 1, 1]], 'dilations': [[1, 1, 1, 1]], 'channel_multiplier': [1], 'rate': [[1, 1]], 'padding': ['VALID'], 'data_format': ['NHWC'], 'constant_filter': [True], 'fully_quantize': [True], 'quant_16x8': [False]}, {'input_shape': [[1, 3, 4, 3]], 'filter_size': [[1, 2]], 'strides': [[1, 3, 3, 1]], 'dilations': [[1, 3, 2, 1]], 'channel_multiplier': [1], 'rate': [[1, 1]], 'padding': ['SAME', 'VALID'], 'data_format': ['NHWC'], 'constant_filter': [True], 'fully_quantize': [True], 'quant_16x8': [True]}]

    def get_tensor_shapes(parameters):
        input_shape = parameters['input_shape']
        filter_size = parameters['filter_size']
        filter_shape = filter_size + [input_shape[3], parameters['channel_multiplier']]
        return [input_shape, filter_shape]

    def build_graph(parameters):
        """Build a depthwise conv graph given `parameters`."""
        (input_shape, filter_shape) = get_tensor_shapes(parameters)
        input_tensor = tf.compat.v1.placeholder(dtype=tf.float32, name='input', shape=input_shape)
        if <MASK>:
            filter_input = create_tensor_data(np.float32, filter_shape)
            input_tensors = [input_tensor]
        else:
            filter_input = tf.compat.v1.placeholder(dtype=tf.float32, name='filter', shape=filter_shape)
            input_tensors = [input_tensor, filter_input]
        out = tf.nn.depthwise_conv2d(input=input_tensor, filter=filter_input, strides=parameters['strides'], dilations=parameters['rate'], padding=parameters['padding'], data_format=parameters['data_format'])
        return (input_tensors, [out])

    def build_inputs(parameters, sess, inputs, outputs):
        """Build list of input values.

    It either contains 1 tensor (input) or 2 tensors (input, filter) based on
    whether filter is constant or variable input.
    """
        (input_shape, filter_shape) = get_tensor_shapes(parameters)
        values = [create_tensor_data(np.float32, input_shape, min_value=-1, max_value=1)]
        if not parameters['constant_filter']:
            values.append(create_tensor_data(np.float32, filter_shape, min_value=-1, max_value=1))
        return (values, sess.run(outputs, feed_dict=dict(zip(inputs, values))))
    make_zip_of_tests(options, test_parameters, build_graph, build_inputs, expected_tf_failures=4)

def assert_almost_equal(actual, desired, decimal=7, err_msg='', verbose=True):
    """
    Asserts that two items are almost equal.

    The test is equivalent to abs(desired-actual) < 0.5 * 10**(-decimal).

    """
    if <MASK>:
        return assert_array_almost_equal(actual, desired, decimal=decimal, err_msg=err_msg, verbose=verbose)
    msg = build_err_msg([actual, desired], err_msg=err_msg, verbose=verbose)
    if not round(abs(desired - actual), decimal) == 0:
        raise AssertionError(msg)

