sparse': None, 'unique': None}
    SKIPLIST_GRAD = {'nn.functional.pairwise_distance': [torch.float16], 'nn.functional.conv1d': [torch.float16], 'nn.functional.conv2d': [torch.float16], 'nn.functional.conv3d': [torch.float16], 'nn.functional.conv_transpose1d': [torch.float16], 'nn.functional.conv_transpose2d': [torch.float16], 'nn.functional.conv_transpose3d': [torch.float16]}
    ON_MPS_XFAILLIST = {'linalg.matrix_rank': None, 'nn.functional.conv3d': [torch.float32]}

    def addDecorator(op: OpInfo, d: DecorateInfo) -> None:
        op.decorators = op.decorators + (d,)
    for op in ops:
        key = op.name + op.variant_test_name
        if key in XFAILLIST_GRAD:
            addDecorator(op, DecorateInfo(unittest.expectedFailure, dtypes=XFAILLIST_GRAD[key]))
