def _check_create_file_writer_args(inside_function, **kwargs):
    """Helper to check the validity of arguments to a create_file_writer() call.

  Args:
    inside_function: whether the create_file_writer() call is in a tf.function
    **kwargs: the arguments to check, as kwargs to give them names.

  Raises:
    ValueError: if the arguments are graph tensors.
  """
    for (arg_name, arg) in kwargs.items():
        if <MASK>:
            if inside_function:
                raise ValueError(f"Invalid graph Tensor argument '{arg_name}={arg}' to create_file_writer() inside an @tf.function. The create call will be lifted into the outer eager execution context, so it cannot consume graph tensors defined inside the function body.")
            else:
                raise ValueError(f"Invalid graph Tensor argument '{arg_name}={arg}' to eagerly executed create_file_writer().")

@register_op_strategy([aten.equal.default, aten.is_same_size.default])
def equal_strategy(op_schema: OpSchema) -> StrategyType:
    mesh = op_schema.get_mesh_from_args()
    (self_strategy, other_strategy) = op_schema.args_schema
    if not isinstance(self_strategy, OpStrategy):
        raise AssertionError(f'Expected OpStrategy, got {type(self_strategy)}')
    if <MASK>:
        raise AssertionError(f'Expected OpStrategy, got {type(other_strategy)}')
    select_strategy = self_strategy if self_strategy.max_num_shards() >= other_strategy.max_num_shards() else other_strategy
    equal_strategy = OpStrategy([])
    for arg_strategy in select_strategy.strategies:
        arg_spec = arg_strategy.output_spec
        if is_tensor_partial(arg_spec):
            output_spec = DTensorSpec(mesh=mesh, placements=tuple((Replicate() if isinstance(p, Partial) else p for p in arg_spec.placements)))
            equal_strategy.strategies.append(OpSpec(output_specs=output_spec))
        else:
            equal_strategy.strategies.append(OpSpec(arg_spec))
    return equal_strategy

def _oom_event(self, symptoms):
    """Check if a runtime OOM event is reported."""
    if <MASK>:
        return False
    for symptom in reversed(symptoms):
        if symptom['symptomType'] != 'OUT_OF_MEMORY':
            continue
        oom_datetime_str = symptom['createTime'].split('.')[0]
        oom_datetime = datetime.datetime.strptime(oom_datetime_str, '%Y-%m-%dT%H:%M:%S')
        time_diff = _utcnow() - oom_datetime
        if time_diff < datetime.timedelta(seconds=_OOM_EVENT_COOL_TIME_SEC):
            logging.warning(self._symptom_msg('a recent runtime OOM has occurred ~{} seconds ago. The model script will terminate automatically. To prevent future OOM events, please consider reducing the model size. To disable this behavior, set flag --runtime_oom_exit=false when starting the script.'.format(time_diff.seconds)))
            return True
    return False

def __init__(self, relu, dim=2, bn=True, bias=True, padding=0):
    super().__init__()
    convs = {1: torch.nn.Conv1d, 2: torch.nn.Conv2d, 3: torch.nn.Conv3d}
    bns = {1: torch.nn.BatchNorm1d, 2: torch.nn.BatchNorm2d, 3: torch.nn.BatchNorm3d}
    self.conv = convs[dim](3, 3, 3, bias=bias, padding=padding)
    if <MASK>:
        self.bn = bns[dim](3)
    else:
        self.bn = torch.nn.Identity()
    if relu:
        self.relu = torch.nn.ReLU()
    else:
        self.relu = torch.nn.Identity()

def _get_arg(self, name, unpack):
    assert name in self._required_arg_names
    if name not in self._arg_cache:
        fn_name = name + '_fn'
        size_name = name + '_size'
        if <MASK>:
            self._arg_cache[name] = self._extra_kwargs[name]
        elif fn_name in self._extra_kwargs:
            self._arg_cache[name] = self._extra_kwargs[fn_name]()
        else:
            assert size_name in self._extra_kwargs, f'Missing `{name}`, `{size_name}` or `{fn_name}` for {self.get_name()}'

            def map_tensor_sizes(sizes):
                if isinstance(sizes, list):
                    return [map_tensor_sizes(s) for s in sizes]
                elif isinstance(sizes, torch.Tensor):
                    return sizes.double()
                else:
                    return torch.randn(sizes)
            self._arg_cache[name] = map_tensor_sizes(self._extra_kwargs[size_name])
    return self._unpack(self._arg_cache[name]) if unpack else self._arg_cache[name]

def _dense_fit(self, X, strategy, missing_values, fill_value):
    """Fit the transformer on dense data."""
    missing_mask = _get_mask(X, missing_values)
    masked_X = ma.masked_array(X, mask=missing_mask)
    super()._fit_indicator(missing_mask)
    if <MASK>:
        mean_masked = np.ma.mean(masked_X, axis=0)
        mean = np.ma.getdata(mean_masked)
        mean[np.ma.getmask(mean_masked)] = 0 if self.keep_empty_features else np.nan
        return mean
    elif strategy == 'median':
        median_masked = np.ma.median(masked_X, axis=0)
        median = np.ma.getdata(median_masked)
        median[np.ma.getmaskarray(median_masked)] = 0 if self.keep_empty_features else np.nan
        return median
    elif strategy == 'most_frequent':
        X = X.transpose()
        mask = missing_mask.transpose()
        if X.dtype.kind == 'O':
            most_frequent = np.empty(X.shape[0], dtype=object)
        else:
            most_frequent = np.empty(X.shape[0])
        for (i, (row, row_mask)) in enumerate(zip(X[:], mask[:])):
            row_mask = np.logical_not(row_mask).astype(bool)
            row = row[row_mask]
            if len(row) == 0 and self.keep_empty_features:
                most_frequent[i] = 0
            else:
                most_frequent[i] = _most_frequent(row, np.nan, 0)
        return most_frequent
    elif strategy == 'constant':
        statistics = np.full(X.shape[1], fill_value, dtype=np.object_)
        if not self.keep_empty_features:
            for i in range(missing_mask.shape[1]):
                if missing_mask[:, i].all():
                    statistics[i] = np.nan
        return statistics
    elif isinstance(strategy, Callable):
        statistics = np.empty(masked_X.shape[1])
        for i in range(masked_X.shape[1]):
            statistics[i] = self.strategy(masked_X[:, i].compressed())
        return statistics

def _is_terminal(value: STATE_DICT_ITEM) -> bool:
    values: Collection[STATE_DICT_ITEM]
    if isinstance(value, Mapping):
        values = value.values()
    elif isinstance(value, list):
        values = value
    else:
        return True
    for entry in values:
        if isinstance(entry, (Mapping, list)) and (not _is_terminal(entry)):
            return False
        if <MASK>:
            return False
    return True

def format(self, record):
    msg = record.msg
    status_code = getattr(record, 'status_code', None)
    if status_code:
        if <MASK>:
            msg = self.style.HTTP_SUCCESS(msg)
        elif 100 <= status_code < 200:
            msg = self.style.HTTP_INFO(msg)
        elif status_code == 304:
            msg = self.style.HTTP_NOT_MODIFIED(msg)
        elif 300 <= status_code < 400:
            msg = self.style.HTTP_REDIRECT(msg)
        elif status_code == 404:
            msg = self.style.HTTP_NOT_FOUND(msg)
        elif 400 <= status_code < 500:
            msg = self.style.HTTP_BAD_REQUEST(msg)
        else:
            msg = self.style.HTTP_SERVER_ERROR(msg)
    if self.uses_server_time() and (not hasattr(record, 'server_time')):
        record.server_time = self.formatTime(record, self.datefmt)
    record.msg = msg
    return super().format(record)

