def _get_strcols_without_index(self) -> list[list[str]]:
    strcols: list[list[str]] = []
    if <MASK>:
        for (i, c) in enumerate(self.tr_frame):
            fmt_values = self.format_col(i)
            fmt_values = _make_fixed_width(strings=fmt_values, justify=self.justify, minimum=int(self.col_space.get(c, 0)), adj=self.adj)
            strcols.append(fmt_values)
        return strcols
    if is_list_like(self.header):
        self.header = cast(list[str], self.header)
        if len(self.header) != len(self.columns):
            raise ValueError(f'Writing {len(self.columns)} cols but got {len(self.header)} aliases')
        str_columns = [[label] for label in self.header]
    else:
        str_columns = self._get_formatted_column_labels(self.tr_frame)
    if self.show_row_idx_names:
        for x in str_columns:
            x.append('')
    for (i, c) in enumerate(self.tr_frame):
        cheader = str_columns[i]
        header_colwidth = max(int(self.col_space.get(c, 0)), *(self.adj.len(x) for x in cheader))
        fmt_values = self.format_col(i)
        fmt_values = _make_fixed_width(fmt_values, self.justify, minimum=header_colwidth, adj=self.adj)
        max_len = max(*(self.adj.len(x) for x in fmt_values), header_colwidth)
        cheader = self.adj.justify(cheader, max_len, mode=self.justify)
        strcols.append(cheader + fmt_values)
    return strcols

def __init__(self, content, name=None, namespace=None, stacklevel=None, get_template=None, default_inherit=None, line_offset=0, delimiters=None):
    self.content = content
    if delimiters is None:
        delimiters = (self.default_namespace['start_braces'], self.default_namespace['end_braces'])
    else:
        self.default_namespace = self.__class__.default_namespace.copy()
        self.default_namespace['start_braces'] = delimiters[0]
        self.default_namespace['end_braces'] = delimiters[1]
    self.delimiters = delimiters
    self._unicode = isinstance(content, str)
    if name is None and stacklevel is not None:
        try:
            caller = sys._getframe(stacklevel)
        except ValueError:
            pass
        else:
            globals = caller.f_globals
            lineno = caller.f_lineno
            if '__file__' in globals:
                name = globals['__file__']
                if name.endswith(('.pyc', '.pyo')):
                    name = name[:-1]
            elif '__name__' in globals:
                name = globals['__name__']
            else:
                name = '<string>'
            if lineno:
                name += ':%s' % lineno
    self.name = name
    self._parsed = parse(content, name=name, line_offset=line_offset, delimiters=self.delimiters)
    if namespace is None:
        namespace = {}
    self.namespace = namespace
    self.get_template = get_template
    if <MASK>:
        self.default_inherit = default_inherit

def check_api_dict(d):
    """Check that an api dict is valid (does not use the same index twice)
    and removed `__unused_indices__` from it (which is important only here)
    """
    removed = set(d.pop('__unused_indices__', []))
    index_d = {k: v[0] for (k, v) in d.items()}
    revert_dict = {v: k for (k, v) in index_d.items()}
    if not len(revert_dict) == len(index_d):
        doubled = {}
        for (name, index) in index_d.items():
            try:
                doubled[index].append(name)
            except KeyError:
                doubled[index] = [name]
        fmt = 'Same index has been used twice in api definition: {}'
        val = ''.join((f'\n\tindex {index} -> {names}' for (index, names) in doubled.items() if len(names) != 1))
        raise ValueError(fmt.format(val))
    indexes = set(index_d.values())
    expected = set(range(len(indexes) + len(removed)))
    if <MASK>:
        raise ValueError(f'API index used but marked unused: {indexes.intersection(removed)}')
    if indexes.union(removed) != expected:
        diff = expected.symmetric_difference(indexes.union(removed))
        msg = f'There are some holes in the API indexing: (symmetric diff is {diff})'
        raise ValueError(msg)

def _fuzz_helper(self, results: ResultType, combo: ComboType) -> Status:
    print(combo)
    if (st := results.lookup(combo)):
