    config = self.new_config()
    skip = False
    for field_name in combo:
        if field_name in config:
            skip = True
        if field_name.startswith('_'):
            skip = True
        field = self.fields[field_name]
        value = self.sample(field_name, field.value_type, field.default)
        config[field_name] = value
    if <MASK>:
        results.set(combo, Status.SKIPPED)
        return Status.SKIPPED
    return self.test_config(results, config)

@symbolic_helper.quantized_args(True, False, False, False, False, False)
@symbolic_helper.parse_args('v', 'is', 'is', 'is', 'is', 'i')
def symbolic_fn(g, input, kernel_size, stride, padding, dilation, ceil_mode):
    if set(tuple_fn(dilation)) != {1}:
        return symbolic_helper._unimplemented(name, 'dilation', input)
    if not stride:
        stride = kernel_size
    padding = tuple(tuple_fn(padding))
    if ceil_mode:
        padding_ceil = get_pool_ceil_padding(input, kernel_size, stride, padding)
        padding = padding + tuple((a + b for (a, b) in zip(padding_ceil, padding)))
    else:
        padding = padding * 2
    kwargs = {'kernel_shape_i': tuple_fn(kernel_size), 'pads_i': padding, 'strides_i': tuple_fn(stride)}
    if <MASK>:
        (r, indices) = g.op('MaxPool', input, outputs=2, **kwargs)
        (_, flattened_indices) = g.op('MaxPool', input, outputs=2, kernel_shape_i=[1 for _ in range(ndims)], strides_i=[1 for _ in range(ndims)])
        s = symbolic_helper._slice_helper(g, flattened_indices, axes=[2 + i for i in range(ndims)], starts=list(tuple_fn(0)), ends=list(tuple_fn(1)))
        indices = sub(g, indices, s)
        return (r, indices)
    else:
        r = g.op('MaxPool', input, outputs=1, **kwargs)
        return r

def arrange_for_graph(self, changes, graph, migration_name=None):
    """
        Take a result from changes() and a MigrationGraph, and fix the names
        and dependencies of the changes so they extend the graph from the leaf
        nodes for each app.
        """
    leaves = graph.leaf_nodes()
    name_map = {}
    for (app_label, migrations) in list(changes.items()):
        if not migrations:
            continue
        app_leaf = None
        for leaf in leaves:
            if leaf[0] == app_label:
                app_leaf = leaf
                break
        if app_leaf is None and (not self.questioner.ask_initial(app_label)):
            for migration in migrations:
                name_map[app_label, migration.name] = (app_label, '__first__')
            del changes[app_label]
            continue
        if <MASK>:
            next_number = 1
        else:
            next_number = (self.parse_number(app_leaf[1]) or 0) + 1
        for (i, migration) in enumerate(migrations):
            if i == 0 and app_leaf:
                migration.dependencies.append(app_leaf)
            new_name_parts = ['%04i' % next_number]
            if migration_name:
                new_name_parts.append(migration_name)
            elif i == 0 and (not app_leaf):
                new_name_parts.append('initial')
            else:
                new_name_parts.append(migration.suggest_name()[:100])
            new_name = '_'.join(new_name_parts)
            name_map[app_label, migration.name] = (app_label, new_name)
            next_number += 1
            migration.name = new_name
    for migrations in changes.values():
        for migration in migrations:
            migration.dependencies = [name_map.get(d, d) for d in migration.dependencies]
    return changes

def as_sql(self, compiler, connection, **extra_context):
    if self.distinct and (not connection.features.supports_aggregate_distinct_multiple_argument) and (len(super().get_source_expressions()) > 1):
        raise NotSupportedError(f'{self.name} does not support distinct with multiple expressions on this database backend.')
    distinct_sql = 'DISTINCT ' if self.distinct else ''
    order_by_sql = ''
    order_by_params = []
    filter_sql = ''
    filter_params = []
    if (order_by := self.order_by) is not None:
        (order_by_sql, order_by_params) = compiler.compile(order_by)
    if <MASK>:
        try:
            (filter_sql, filter_params) = compiler.compile(self.filter)
        except NotSupportedError:
            copy = self.copy()
            copy.filter = None
            source_expressions = copy.get_source_expressions()
            condition = When(self.filter.condition, then=source_expressions[0])
            copy.set_source_expressions([Case(condition)] + source_expressions[1:])
            return copy.as_sql(compiler, connection, **extra_context)
    extra_context.update(distinct=distinct_sql, filter=filter_sql, order_by=order_by_sql)
    (sql, params) = super().as_sql(compiler, connection, **extra_context)
    return (sql, (*params, *order_by_params, *filter_params))

