def add_dependency(self, module_name: str, dependencies=True):
    """Given a module, add it to the dependency graph according to patterns
        specified by the user.
        """
    if module_name in self.dependency_graph and self.dependency_graph.nodes[module_name].get('provided') is True:
        return
    if module_name == 'torch_package_importer':
        self.dependency_graph.add_node(module_name, action=_ModuleProviderAction.SKIP, provided=True)
        return
    if module_name == '_mock':
        self.dependency_graph.add_node(module_name, action=_ModuleProviderAction.REPACKAGED_MOCK_MODULE, provided=True)
        return
    if self._can_implicitly_extern(module_name):
        self.dependency_graph.add_node(module_name, action=_ModuleProviderAction.EXTERN, provided=True)
        return
    for (pattern, pattern_info) in self.patterns.items():
        if pattern.matches(module_name):
            pattern_info.was_matched = True
            self.dependency_graph.add_node(module_name, action=pattern_info.action, provided=True)
            if pattern_info.action == _ModuleProviderAction.DENY:
                self.dependency_graph.add_node(module_name, error=PackagingErrorReason.DENIED)
            if <MASK>:
                self._intern_module(module_name, dependencies)
            return
    self.dependency_graph.add_node(module_name, error=PackagingErrorReason.NO_ACTION)

def _add_op_and_parents(self, op: ops.Operation):
    op_def = graph_to_function_def._get_op_def(op)
    if <MASK>:
        raise ValueError(f'Cannot capture a stateful node (name:{op.name}, type:{op.type}) by value.')
    elif op.type in ('Placeholder', 'PlaceholderV2'):
        raise ValueError(f'Cannot capture a placeholder (name:{op.name}, type:{op.type}) by value.')
    captured_inputs = [self._add_tensor_and_parents(x) for x in op.inputs]
    captured_op = self._create_op_internal(op.type, captured_inputs, [o.dtype for o in op.outputs], name=op.name, attrs=op.node_def.attr, op_def=op_def)
    for (t, captured_t) in zip(op.outputs, captured_op.outputs):
        self._captured[t.ref()] = captured_t
    return captured_op

def populate(self, installed_apps=None):
    """
        Load application configurations and models.

        Import each application module and then each model module.

        It is thread-safe and idempotent, but not reentrant.
        """
    if self.ready:
        return
    with self._lock:
        if self.ready:
            return
        if self.loading:
            raise RuntimeError("populate() isn't reentrant")
        self.loading = True
        for entry in installed_apps:
            if <MASK>:
                app_config = entry
            else:
                app_config = AppConfig.create(entry)
            if app_config.label in self.app_configs:
                raise ImproperlyConfigured("Application labels aren't unique, duplicates: %s" % app_config.label)
            self.app_configs[app_config.label] = app_config
            app_config.apps = self
        counts = Counter((app_config.name for app_config in self.app_configs.values()))
        duplicates = [name for (name, count) in counts.most_common() if count > 1]
        if duplicates:
            raise ImproperlyConfigured("Application names aren't unique, duplicates: %s" % ', '.join(duplicates))
        self.apps_ready = True
        for app_config in self.app_configs.values():
            app_config.import_models()
        self.clear_cache()
        self.models_ready = True
        for app_config in self.get_app_configs():
            app_config.ready()
        self.ready = True
        self.ready_event.set()

def __getattr__(self, key: str) -> Any:
    properties = self.__dict__['properties']
    for values in LazyIrProperties.Properties:
        if <MASK>:
            return properties[values] == key
    return self.__getattribute__(key)

def __call__(self, estimator, *args, **kwargs):
    """Evaluate predicted target values."""
    scores = {}
    cache = {} if self._use_cache(estimator) else None
    cached_call = partial(_cached_call, cache)
    if <MASK>:
        routed_params = process_routing(self, 'score', **kwargs)
    else:
        common_kwargs = {arg: value for (arg, value) in kwargs.items() if arg != 'sample_weight'}
        routed_params = Bunch(**{name: Bunch(score=common_kwargs.copy()) for name in self._scorers})
        if 'sample_weight' in kwargs:
            for (name, scorer) in self._scorers.items():
                if scorer._accept_sample_weight():
                    routed_params[name].score['sample_weight'] = kwargs['sample_weight']
    for (name, scorer) in self._scorers.items():
        try:
            if isinstance(scorer, _BaseScorer):
                score = scorer._score(cached_call, estimator, *args, **routed_params.get(name).score)
            else:
                score = scorer(estimator, *args, **routed_params.get(name).score)
            scores[name] = score
        except Exception as e:
            if self._raise_exc:
                raise e
            else:
                scores[name] = format_exc()
    return scores

def _convert_to_export_graph_signature(graph_signature: 'GraphSignature', gm: 'torch.fx.GraphModule', non_persistent_buffers: set[str]) -> 'ExportGraphSignature':
    from torch.utils import _pytree as pytree
    is_joint = graph_signature.backward_signature is not None
    user_inputs = set(graph_signature.user_inputs)
    inputs_to_parameters = graph_signature.inputs_to_parameters
    inputs_to_buffers = graph_signature.inputs_to_buffers
    user_outputs = set(graph_signature.user_outputs)
    buffer_mutations = graph_signature.buffers_to_mutate
    parameter_mutations = graph_signature.parameters_to_mutate
    user_input_mutations = graph_signature.user_inputs_to_mutate
    grad_params = graph_signature.backward_signature.gradients_to_parameter if is_joint else {}
    grad_user_inputs = graph_signature.backward_signature.gradients_to_user_inputs if is_joint else {}
    loss_output = graph_signature.backward_signature.loss_output if is_joint else None
    input_tokens = graph_signature.input_tokens
    output_tokens = graph_signature.output_tokens
    inputs = [_make_argument_spec(node, input_tokens) for node in gm.graph.nodes if node.op == 'placeholder']
    outputs = [_make_argument_spec(node, output_tokens) for node in pytree.tree_leaves(next(iter(reversed(gm.graph.nodes))).args)]

    def to_input_spec(inp: ArgumentSpec) -> InputSpec:
        if isinstance(inp, TokenArgument):
            return InputSpec(kind=InputKind.TOKEN, arg=inp, target=None)
        if not isinstance(inp, TensorArgument):
            return InputSpec(kind=InputKind.USER_INPUT, arg=inp, target=None)
        name = inp.name
        if name in user_inputs:
            return InputSpec(kind=InputKind.USER_INPUT, arg=inp, target=None)
        elif name in inputs_to_parameters:
            return InputSpec(kind=InputKind.PARAMETER, arg=inp, target=inputs_to_parameters[name])
        elif name in inputs_to_buffers:
            return InputSpec(kind=InputKind.BUFFER, arg=inp, target=inputs_to_buffers[name], persistent=inputs_to_buffers[name] not in non_persistent_buffers)
        else:
            raise AssertionError(f'Unknown tensor input kind: {name}')

    def to_output_spec(idx: int, o: ArgumentSpec) -> OutputSpec:
        if <MASK>:
            return OutputSpec(kind=OutputKind.TOKEN, arg=o, target=None)
        if not isinstance(o, TensorArgument):
            return OutputSpec(kind=OutputKind.USER_OUTPUT, arg=o, target=None)
        name = o.name
        if idx < len(buffer_mutations) + len(parameter_mutations) + len(user_input_mutations) + len(output_tokens):
            if name in buffer_mutations:
                return OutputSpec(kind=OutputKind.BUFFER_MUTATION, arg=o, target=buffer_mutations[name])
            elif name in parameter_mutations:
                return OutputSpec(kind=OutputKind.PARAMETER_MUTATION, arg=o, target=parameter_mutations[name])
            elif name in user_input_mutations:
                return OutputSpec(kind=OutputKind.USER_INPUT_MUTATION, arg=o, target=user_input_mutations[name])
            else:
                raise AssertionError(f'Unknown tensor mutation kind: {name}')
        elif name in user_outputs:
            return OutputSpec(kind=OutputKind.USER_OUTPUT, arg=o, target=None)
        elif name in grad_params:
            return OutputSpec(kind=OutputKind.GRADIENT_TO_PARAMETER, arg=o, target=grad_params[name])
        elif name in grad_user_inputs:
            return OutputSpec(kind=OutputKind.GRADIENT_TO_USER_INPUT, arg=o, target=grad_user_inputs[name])
        elif name == loss_output:
            return OutputSpec(kind=OutputKind.LOSS_OUTPUT, arg=o, target=None)
        else:
            raise AssertionError(f'Unknown tensor output kind: {name}')
    input_specs = [to_input_spec(inp) for inp in inputs]
    output_specs = [to_output_spec(idx, o) for (idx, o) in enumerate(outputs)]
    return ExportGraphSignature(input_specs=input_specs, output_specs=output_specs)

def apply_sharding(self, num_of_instances, instance_id, sharding_group=SHARDING_PRIORITIES.DEFAULT):
    if instance_id >= num_of_instances:
        raise ValueError(f'instance_id({instance_id}) should be smaller than num_of_instances({num_of_instances})')
    if sharding_group == SHARDING_PRIORITIES.DEFAULT:
        if <MASK>:
            raise RuntimeError('ShardingFilter cannot mix DEFAULT and non DEFAULT groups')
    elif SHARDING_PRIORITIES.DEFAULT in self.groups:
        raise RuntimeError('ShardingFilter cannot mix DEFAULT and non DEFAULT groups')
    self.groups[sharding_group] = (num_of_instances, instance_id)
    self._update_num_of_instances()

def bind_symbols(self, placeholders: Sequence[FakeTensor], args: Sequence[Tensor]) -> dict[sympy.Symbol, int]:
    """
        Given a paired list of placeholders (fake tensors with
        symbolic sizes) and concrete arguments (regular tensors
        with real sizes), returns a dictionary mapping each
        symbol to its real value.  So for example, if you
        have a placeholder with size (s0, s1), binding
        (2, 4) to it will give you {s0: 2, s1: 4}.  This is
        not guaranteed to bind ALL symbols in the ShapeEnv;
        we can't bind a symbol if it doesn't occur in any placeholder,
        and symbols that already have replacements won't get bindings.

        This is a little duplicative with evaluate_guards but
        it's different enough that it seemed cleanest to make
        another copy.  This assumes the guards are already checked,
        though if it's cheap we'll check for shenanigans
        """
    bindings: dict[sympy.Symbol, int] = {}

    def bind_symint(arg: object, val: object) -> None:
        if isinstance(val, SymInt):
            assert isinstance(arg, int)
            s = val.node.expr
            if isinstance(s, sympy.Symbol):
                if s in bindings:
                    assert bindings[s] == arg, f'{bindings[s]} != {arg}'
                else:
                    bindings[s] = arg
            elif isinstance(-s, sympy.Symbol):
                if -s in bindings:
                    assert bindings[-s] == -arg, f'{bindings[-s]} != {-arg}'
                else:
                    bindings[-s] = -arg
    for (t, arg) in zip(placeholders, args):
        if t is None:
            continue
        if <MASK>:
            bind_symint(arg, t)
            continue
        assert isinstance(t, torch.Tensor)
        for (i, s) in enumerate(t.size()):
            bind_symint(arg.size(i), s)
        for (i, s) in enumerate(t.stride()):
            bind_symint(arg.stride(i), s)
        bind_symint(arg.storage_offset(), t.storage_offset())
    return bindings

def enable_activation_quantization(saved_values: list[fx.Node], fwd_module: fx.GraphModule, bwd_module: fx.GraphModule, static_lifetime_input_nodes: Optional[OrderedSet[fx.Node]]=None) -> None:
    if inductor_config.post_grad_fusion_options.get('activation_quantization_aten_pass', None) is None:
        return
    static_input_names = [node.name for node in static_lifetime_input_nodes] if static_lifetime_input_nodes else []
    saved_values_names = {node.name: node for node in saved_values}
    if <MASK>:
        saved_values_names = {node.name: node for node in saved_values if 'primals' not in node.name}
    fwd_module_outputs = fwd_module.graph.find_nodes(op='output')[0].args[0]
    bwd_module_inputs = {node.name: node for node in bwd_module.graph.find_nodes(op='placeholder')}
    should_perform_fp8_quant = False
    for node in fwd_module_outputs:
        if node.name in saved_values_names and should_quantize(node):
            if node.name in static_input_names:
                log.debug('Skipping quantization of static input %s: ', node.name)
                continue
            node.meta['saved_for_quantization'] = True
            node.meta['dequant_type'] = node.meta['val'].dtype
            bwd_module_inputs[node.name].meta['saved_for_quantization'] = True
            bwd_module_inputs[node.name].meta['dequant_type'] = node.meta['val'].dtype
            should_perform_fp8_quant = True
    if should_perform_fp8_quant:
        perform_fp8_activation_quantization(fwd_module, bwd_module, bwd_module_inputs)

@property
def vsi_buffer(self):
    if <MASK>:
        return None
    out_length = c_int()
    dat = capi.get_mem_buffer_from_vsi_file(force_bytes(self.name), byref(out_length), VSI_DELETE_BUFFER_ON_READ)
    return string_at(dat, out_length.value)

def _simplify_with_ranges(self, expr: Expr, var_ranges: VarRanges) -> Expr:
    """
        Simplify indexing expression with knowledge of the ranges of
        iteration variables.
        """
    expr = join_dimensions(self.simplify(expr))
    original_expr = expr
    var_to_range = dict(self.shape_env.var_to_range)
    var_to_range.update({k: ValueRanges(0, max(0, v - 1) if not has_free_symbols([v]) else IntInfinity()) for (k, v) in var_ranges.items()})
    for var in expr.free_symbols:
        if var not in var_to_range:
            var_to_range[var] = ValueRanges(0, IntInfinity())
    var_to_range_tuple = cast(tuple[tuple[sympy.Symbol, ValueRanges[sympy.Expr]]], tuple(var_to_range.items()))
    axioms = []
    for (var, upper_bound) in var_ranges.items():
        axioms.append(0 <= var)
        axioms.append(var < upper_bound)
    axioms = tuple(axioms) + self.shape_env.get_axioms()

    def statically_known(expr):
        evaluated = self.shape_env._maybe_evaluate_static(expr, axioms=axioms, var_to_range=var_to_range_tuple)
        return bool(evaluated)

    def remove_zero_terms(base, divisor):
        """Symbols smaller than the divisor are zero"""
        if not statically_known(base >= 0):
            return base
        for v in base.free_symbols:
            if v in var_ranges:
                rest = sympy.Wild('_rest', exclude=[v])
                m = base.match(v + rest)
                if <MASK>:
                    gcd = sympy.gcd(m[rest], divisor)
                    if gcd == divisor:
                        if statically_known(v < divisor):
                            base = m[rest]
        return base

    def visit_indexing_div(base, divisor):
        return FloorDiv(remove_zero_terms(base, divisor), divisor)

    def visit_modular_indexing(base, divisor, modulus):
        base = remove_zero_terms(base, divisor)
        can_remove_mod = statically_known(base >= 0) and statically_known(base < modulus * divisor)
        if can_remove_mod:
            return FloorDiv(base, divisor)
        return ModularIndexing(base, divisor, modulus)
    if expr.has(ModularIndexing):
        expr = expr.replace(ModularIndexing(sympy.Wild('base', integer=True), sympy.Wild('divisor', integer=True), sympy.Wild('modulus', integer=True)), visit_modular_indexing)
    if expr.has(FloorDiv):
        expr = expr.replace(FloorDiv(sympy.Wild('base', integer=True), sympy.Wild('divisor', integer=True)), visit_indexing_div)
    if expr != original_expr:
        return self._simplify_with_ranges(expr, var_ranges)
    return expr

@parameterized.parameters(*testing.parameter_combinations([{'activation_fn': [None, nn_ops.relu, nn_ops.relu6], 'has_bias': [True, False], 'batch_sizes': [([], []), ([10], [10]), ([2, 3], [2, 3])], 'target_opset': [quant_opts_pb2.XLA]}, {'activation_fn': [None], 'has_bias': [True], 'batch_sizes': [([2], []), ([], [2]), ([1], [2]), ([None], [])], 'target_opset': [quant_opts_pb2.XLA]}, {'activation_fn': [None, nn_ops.relu, nn_ops.relu6], 'has_bias': [True, False], 'batch_sizes': [([], []), ([10], [10]), ([2, 3], [2, 3])], 'target_opset': [quant_opts_pb2.UNIFORM_QUANTIZED]}]))
@test_util.run_in_graph_and_eager_modes
def test_matmul_ptq_model(self, activation_fn: Optional[ops.Operation], has_bias: bool, batch_sizes: Sequence[int], target_opset: quant_opts_pb2.OpSet):
    (lhs_batch_size, rhs_batch_size) = batch_sizes
    input_shape = (*lhs_batch_size, 1, 1024)
    filter_shape = (*rhs_batch_size, 1024, 3)
    static_input_shape = [dim if dim is not None else 2 for dim in input_shape]
    model = self._create_matmul_model(input_shape, filter_shape, self._input_saved_model_path, has_bias, activation_fn)
    rng = np.random.default_rng(seed=1234)

    def data_gen() -> repr_dataset.RepresentativeDataset:
        for _ in range(500):
            yield {'input_tensor': rng.uniform(low=0.0, high=1.0, size=static_input_shape).astype(np.float32)}
    tags = {tag_constants.SERVING}
    input_data = ops.convert_to_tensor(rng.uniform(low=0.0, high=1.0, size=static_input_shape).astype(np.float32))
    expected_outputs = model.matmul(input_data)
    quantization_options = quant_opts_pb2.QuantizationOptions(quantization_method=quant_opts_pb2.QuantizationMethod(preset_method=_PresetMethod.METHOD_STATIC_RANGE_INT8), tags=tags, signature_keys=['serving_default'], op_set=target_opset)
    converted_model = quantize_model.quantize(self._input_saved_model_path, self._output_saved_model_path, quantization_options, representative_dataset=data_gen())
    self.assertIsNotNone(converted_model)
    self.assertCountEqual(converted_model.signatures._signatures.keys(), {'serving_default'})
    loader = saved_model_loader.SavedModelLoader(self._output_saved_model_path)
    output_graphdef = loader.get_meta_graph_def_from_tags(tags).graph_def
    if target_opset == quant_opts_pb2.XLA:
        self.assertTrue(self._contains_op(output_graphdef, 'XlaDotV2', node_name='sample/matmul.*'))
    elif <MASK>:
        self.assertTrue(self._contains_op(output_graphdef, 'UniformQuantizedDot', node_name='sample/matmul.*'))
    new_outputs = converted_model.signatures['serving_default'](input_tensor=ops.convert_to_tensor(input_data))
    if target_opset == quant_opts_pb2.UNIFORM_QUANTIZED:
        self.assertAllClose(new_outputs, expected_outputs, atol=0.25)
    else:
        self.assertAllClose(new_outputs, expected_outputs, atol=0.13)

def applyrules(rules, d, var={}):
    ret = {}
    if isinstance(rules, list):
        for r in rules:
            rr = applyrules(r, d, var)
            ret = dictappend(ret, rr)
            if '_break' in rr:
                break
        return ret
    if '_check' in rules and (not rules['_check'](var)):
        return ret
    if 'need' in rules:
        res = applyrules({'needs': rules['need']}, d, var)
        if 'needs' in res:
            cfuncs.append_needs(res['needs'])
    for k in rules.keys():
        if k == 'separatorsfor':
            ret[k] = rules[k]
            continue
        if isinstance(rules[k], str):
            ret[k] = replace(rules[k], d)
        elif <MASK>:
            ret[k] = []
            for i in rules[k]:
                ar = applyrules({k: i}, d, var)
                if k in ar:
                    ret[k].append(ar[k])
        elif k[0] == '_':
            continue
        elif isinstance(rules[k], dict):
            ret[k] = []
            for k1 in rules[k].keys():
                if isinstance(k1, types.FunctionType) and k1(var):
                    if isinstance(rules[k][k1], list):
                        for i in rules[k][k1]:
                            if isinstance(i, dict):
                                res = applyrules({'supertext': i}, d, var)
                                i = res.get('supertext', '')
                            ret[k].append(replace(i, d))
                    else:
                        i = rules[k][k1]
                        if isinstance(i, dict):
                            res = applyrules({'supertext': i}, d)
                            i = res.get('supertext', '')
                        ret[k].append(replace(i, d))
        else:
            errmess(f'applyrules: ignoring rule {repr(rules[k])}.\n')
        if isinstance(ret[k], list):
            if len(ret[k]) == 1:
                ret[k] = ret[k][0]
            if ret[k] == []:
                del ret[k]
    return ret

def read_metadata(self) -> Metadata:
    from safetensors import safe_open
    from safetensors.torch import _getdtype
    state_dict_metadata: dict[str, TensorStorageMetadata] = {}
    storage_data: dict[MetadataIndex, _HFStorageInfo] = {}
    safetensors_files = []
    for file in self.fs.ls(self.path):
        if file.endswith(SUFFIX):
            safetensors_files.append(file)
    for safetensor_file in safetensors_files:
        with safe_open(safetensor_file, framework='pt') as f:
            keys = f.keys()
            extra_metadata = f.metadata()
            dcp_sharding_info = None
            if extra_metadata and extra_metadata.get(CUSTOM_METADATA_KEY):
                dcp_sharding_info = json.loads(extra_metadata.get(CUSTOM_METADATA_KEY))
            for key in keys:
                shape = f.get_slice(key).get_shape()
                dtype = f.get_slice(key).get_dtype()
                if dcp_sharding_info is not None:
                    offset = dcp_sharding_info[key][SAVED_OFFSETS_KEY]
                else:
                    offset = [0] * len(shape)
                if <MASK>:
                    state_dict_metadata[key] = TensorStorageMetadata(properties=TensorProperties(dtype=_getdtype(dtype)), size=torch.Size([saved + offset for (saved, offset) in zip(shape, offset)]), chunks=[ChunkStorageMetadata(offsets=torch.Size(offset), sizes=torch.Size(shape))])
                else:
                    state_dict_metadata[key].chunks.append(ChunkStorageMetadata(torch.Size(offset), sizes=torch.Size(shape)))
                    size = list(state_dict_metadata[key].size)
                    for i in range(len(size)):
                        size[i] = max(size[i], shape[i] + offset[i])
                    state_dict_metadata[key].size = torch.Size(size)
                if dcp_sharding_info is not None:
                    metadata_index = MetadataIndex(fqn=key, offset=dcp_sharding_info[key][SAVED_OFFSETS_KEY])
                else:
                    metadata_index = MetadataIndex(fqn=key, offset=[0] * len(shape))
                storage_data[metadata_index] = _HFStorageInfo(relative_path=safetensor_file, shape=torch.Size(shape), dtype=_getdtype(dtype))
    metadata = Metadata(state_dict_metadata=state_dict_metadata, storage_data=storage_data)
    if getattr(metadata, 'storage_meta', None) is None:
        metadata.storage_meta = StorageMeta()
    metadata.storage_meta.load_id = self.load_id
    return metadata

def patched_dim_method(wrapper: WrappedOperator, *args: Any, **kwargs: Any) -> Any:
    """
    This is the core method that handles dimension-aware operations.
    """
    if not args:
        raise ValueError('Expected at least one argument (self)')
    dim_arg = kwargs.get(wrapper.dim_name)
    if dim_arg is None and wrapper.dim_offset < len(args):
        dim_idx = wrapper.dim_offset + 1
        if dim_idx < len(args):
            dim_arg = args[dim_idx]
    if dim_arg is None:
        info = TensorInfo.create(args[0], ensure_batched=True, ensure_present=False)
        if not info:
            return wrapper.orig(*args, **kwargs)
        with EnableAllLayers(info.levels) as guard:
            assert info.batchedtensor is not None
            guard.inplace_update_layers(info.batchedtensor, info.levels)
            new_args = list(args)
            new_args[0] = handle_from_tensor(info.batchedtensor)
            result = wrapper.orig(*new_args, **kwargs)
            return guard.from_batched(result, info.has_device)
    info = TensorInfo.create(args[0])
    if not info:
        return wrapper.orig(*args, **kwargs)
    keepdim = False
    if wrapper.reduce:
        keepdim_arg = kwargs.get('keepdim')
        if keepdim_arg is None and wrapper.keepdim_offset < len(args):
            keepdim_idx = wrapper.keepdim_offset + 1
            if keepdim_idx < len(args):
                keepdim_arg = args[keepdim_idx]
        if keepdim_arg is not None:
            keepdim = bool(keepdim_arg)
    ndim = info.ndim()
    dims = _wrap_dims(dim_arg, ndim, keepdim)
    dim_indices: list[int] = []
    seen = [False] * len(info.levels)
    for d in dims:
        midx = None
        for (i, level) in enumerate(info.levels):
            if level == d:
                midx = i
                break
        if midx is None:
            for (i, level) in enumerate(info.levels):
                if hasattr(level, 'matches') and level.matches(d):
                    midx = i
                    break
            if midx is None:
                level_strs = [str(level) for level in info.levels]
                raise ValueError(f'Tensor with dimensions {level_strs} does not contain {d}')
        seen[midx] = True
        dim_indices.append(midx)
    new_levels = []
    if wrapper.reduce and (not keepdim):
        for (i, level) in enumerate(info.levels):
            if <MASK>:
                new_levels.append(level)
    else:
        new_levels = info.levels[:]
    if len(dim_indices) == 1:
        py_indices: Any = dim_indices[0]
    else:
        py_indices = tuple(dim_indices)
    new_args = list(args)
    new_kwargs = kwargs.copy()
    assert info.tensor is not None
    new_args[0] = handle_from_tensor(info.tensor)
    if wrapper.dim_name in new_kwargs:
        new_kwargs[wrapper.dim_name] = py_indices
    else:
        dim_idx = wrapper.dim_offset + 1
        if dim_idx < len(new_args):
            new_args = list(new_args)
            new_args[dim_idx] = py_indices
    result = wrapper.orig(*new_args, **new_kwargs)

    def wrap_result(obj: Any) -> Any:
        if isinstance(obj, torch.Tensor):
            from . import Tensor
            return Tensor.from_positional(obj, new_levels, info.has_device)
        return obj
    return tree_map(wrap_result, result)

def decorator(f: Callable[..., Any]) -> Callable[..., None]:
    if tf_inspect.isclass(f):
        raise ValueError('`with_forward_compatibility_horizons` only supports test methods.')

    def decorated(*args, **kwargs):
        for horizon in horizons:
            if <MASK>:
                f(*args, **kwargs)
            else:
