    return tf_decorator.make_decorator(f, decorated)

@wraps(orig_fsdp_state_pre_fw)
def inner(*args: _P.args, **kwargs: _P.kwargs) -> tuple[tuple[Unpack[_Ts]], dict[str, Any]]:
    self._fsdp_state = _FSDPState.PRE_FW
    mod_fqn = self._mod_tracker.get_known_fqn(fsdp_mod)
    assert mod_fqn is not None
    if fsdp_mod not in self.memory_tracking:
        mod_stat = _FSDPModMemStats(mod_fqn)
        self.memory_tracking[fsdp_mod] = mod_stat
        snapshot = self.get_tracker_snapshot()
        mod_stat.local_peak = {dev: dev_snap[_TOTAL_KEY] for (dev, dev_snap) in snapshot.items()}
        mod_stat.snapshots.setdefault(_FSDPModState.PEAK_FW, []).append(snapshot)
        mod_stat.snapshots.setdefault(_FSDPModState.BEF_PRE_FW, []).append(deepcopy(snapshot))
    elif not self._mod_tracker.is_bw:
        parents = self._mod_tracker.parents - {mod_fqn}
        if len(parents) == 1 and 'Global' in parents:
            raise NotImplementedError('FSDPMemTracker does not support memory tracking for multiple iterative calls. Either use ``reset_mod_stats`` to clear module memory stats for the previous iteration or file a github issue if you need this feature.')
    (args, kwargs) = orig_fsdp_state_pre_fw(*args, **kwargs)
    fsdp_state = fsdp_mod._get_fsdp_state()
    if (fsdp_param_group := fsdp_state._fsdp_param_group):
        for fsdp_param in fsdp_param_group.fsdp_params:
            self._update_and_maybe_create_winfos(fsdp_param.unsharded_param, _FSDPRefType.UNSHARDED_PARAM)
    mod_stat = self.memory_tracking[fsdp_mod]
    if self._mod_tracker.is_bw:
        state = _FSDPModState.PRE_FW_AC
        if <MASK>:
            self._ac_mod = weakref.ref(fsdp_mod)
            self._in_ac = True
    else:
        state = _FSDPModState.AFT_PRE_FW
    mod_stat.snapshots.setdefault(state, []).append(self.get_tracker_snapshot())
    self._fsdp_state = _FSDPState.FW
    return (args, kwargs)

def get_fma_per_cycle_per_sm_tensor_cores(self, data_type: dtype) -> int:
    hardcoded_device_values = {'int8_80': 2048, 'fp16_80': 1024, 'fp32_80': 512, 'fp64_80': 64, 'int8_90': 4096, 'fp8_90': 4096, 'fp16_90': 2048, 'fp32_90': 1024, 'fp64_90': 128, 'int8_100': 8192, 'fp8_100': 8192, 'fp16_100': 4096, 'fp32_100': 2048}
    dict_key = ''
    if <MASK>:
        dict_key = f'fp16_{self.compute_capability}'
    elif data_type is torch.bfloat16:
        dict_key = f'fp16_{self.compute_capability}'
    elif data_type is torch.float32:
        dict_key = f'fp32_{self.compute_capability}'
    elif data_type is torch.int8:
        dict_key = f'int8_{self.compute_capability}'
    elif data_type is torch.float64:
        dict_key = f'fp64_{self.compute_capability}'
    else:
        dict_key = 'unknown'
    if dict_key not in hardcoded_device_values.keys():
        raise RuntimeError(f'No data for sm_{self.compute_capability} and {data_type}.')
    return hardcoded_device_values[dict_key]

def generate_FA_callable(attn_type: str, shape: tuple[int], dtype: torch.dtype, backend: str, **kwargs) -> Callable | None:
    if <MASK>:
        return None
    if backend == 'fav2':
        try:
            from flash_attn import flash_attn_func, flash_attn_varlen_func
        except ImportError:
            print('Flash attention 2 is not installed. Please install it to run fav2 backend. ')
            raise
    elif backend == 'fav3':
        try:
            from flash_attn.flash_attn_interface import flash_attn_func, flash_attn_varlen_func
        except ImportError:
            print('Flash attention 3 is not installed. Please install it to run fav3 backend. ')
            raise
    else:
        print('Unknown backend ' + backend)
        return None
    (B, Hq, M, Hkv, N, D) = shape
    FA_kwargs = {}
    if attn_type == 'alibi':
        h = torch.arange(Hq, dtype=torch.float32, device='cuda')
        alibi_slopes = torch.exp2(-((h + 1) * 8.0 / Hq))
        FA_kwargs = dict(alibi_slopes=alibi_slopes)
    elif attn_type == 'document_mask':
        FA_kwargs['cu_seqlens_q'] = kwargs['offsets'].to(torch.int32)
        FA_kwargs['cu_seqlens_k'] = kwargs['offsets'].to(torch.int32)

        def offsets_to_lengths(offsets: torch.Tensor, device: Union[str, torch.device]) -> torch.tensor:
            lengths = offsets[1:] - offsets[:-1]
            return lengths
        lengths = offsets_to_lengths(kwargs['offsets'], 'cpu')
        max_length = torch.max(lengths)
        FA_kwargs['max_seqlen_q'] = max_length
        FA_kwargs['max_seqlen_k'] = max_length
    FA_dict = {'noop': partial(flash_attn_func, causal=False), 'causal': partial(flash_attn_func, causal=True), 'rel': None, 'head_bias': None, 'alibi': partial(flash_attn_func, causal=True, **FA_kwargs), 'sliding_window': partial(flash_attn_func, window_size=(sliding_window_size, 0), causal=True), 'document_mask': partial(flash_attn_varlen_func, causal=True, **FA_kwargs), 'prefix_lm': None, 'softcap': partial(flash_attn_func, softcap=softcap_value, causal=True)}
    return FA_dict[attn_type]

