def load_model(self, device, model_name, batch_size=None, extra_args=None):
    is_training = self.args.training
    use_eval_mode = self.args.use_eval_mode
    dtype = torch.float32
    reset_rng_state()
    if model_name in BATCH_SIZE_KNOWN_MODELS:
        batch_size_default = BATCH_SIZE_KNOWN_MODELS[model_name]
    elif <MASK>:
        batch_size_default = 16
        log.info(f'Batch size not specified for {model_name}. Setting batch_size=16')
    if batch_size is None:
        batch_size = batch_size_default
        batch_size_divisors = self._config['batch_size']['divisors']
        if model_name in batch_size_divisors:
            batch_size = max(int(batch_size / batch_size_divisors[model_name]), 1)
            log.info(f'Running smaller batch size={batch_size} for {model_name}, orig batch_size={batch_size_default}')
    if model_name in HF_LLM_MODELS:
        benchmark_cls = HF_LLM_MODELS[model_name]
        (model, example_inputs) = benchmark_cls.get_model_and_inputs(model_name, device)
        self.hf_llm = True

        def generate(self, _, example_inputs, collect_outputs=True):
            return model.generate(**example_inputs)
        self.generate = types.MethodType(generate, self)
    else:
        self.hf_llm = False
        (model_cls, config) = self._get_model_cls_and_config(model_name)
        model = self._download_model(model_name)
        model = model.to(device, dtype=dtype)
        example_inputs = generate_inputs_for_model(model_cls, model, model_name, batch_size, device, include_loss_args=True)
        for attr in dir(config):
            if 'drop' in attr and isinstance(getattr(config, attr), float):
                setattr(config, attr, 1e-30)
        if hasattr(model, 'config') and hasattr(model.config, 'use_cache'):
            model.config.use_cache = False
    if self.args.enable_activation_checkpointing:
        model.gradient_checkpointing_enable()
    if is_training and (not use_eval_mode) and (not (self.args.accuracy and model_name in self._config['only_inference'])):
        model.train()
    else:
        model.eval()
    self.validate_model(model, example_inputs)
    return (device, model_name, model, example_inputs, batch_size)

def shortcut(request, content_type_id, object_id):
    """
    Redirect to an object's page based on a content-type ID and an object ID.
    """
    try:
        content_type = ContentType.objects.get(pk=content_type_id)
        if not content_type.model_class():
            raise Http404(_('Content type %(ct_id)s object has no associated model') % {'ct_id': content_type_id})
        obj = content_type.get_object_for_this_type(pk=object_id)
    except (ObjectDoesNotExist, ValueError, ValidationError):
        raise Http404(_('Content type %(ct_id)s object %(obj_id)s doesn’t exist') % {'ct_id': content_type_id, 'obj_id': object_id})
    try:
        get_absolute_url = obj.get_absolute_url
    except AttributeError:
        raise Http404(_('%(ct_name)s objects don’t have a get_absolute_url() method') % {'ct_name': content_type.name})
    absurl = get_absolute_url()
    if absurl.startswith(('http://', 'https://', '//')):
        return HttpResponseRedirect(absurl)
    try:
        object_domain = get_current_site(request).domain
    except ObjectDoesNotExist:
        object_domain = None
    if apps.is_installed('django.contrib.sites'):
        Site = apps.get_model('sites.Site')
        opts = obj._meta
        for field in opts.many_to_many:
            if field.remote_field.model is Site:
                site_qs = getattr(obj, field.name).all()
                if <MASK>:
                    break
                site = site_qs.first()
                if site:
                    object_domain = site.domain
                    break
        else:
            for field in obj._meta.fields:
                if field.remote_field and field.remote_field.model is Site:
                    try:
                        site = getattr(obj, field.name)
                    except Site.DoesNotExist:
                        continue
                    if site is not None:
                        object_domain = site.domain
                        break
    if object_domain is not None:
        protocol = request.scheme
        return HttpResponseRedirect('%s://%s%s' % (protocol, object_domain, absurl))
    else:
        return HttpResponseRedirect(absurl)

def _build_debug_param_to_name_mapping(self, parameters):
    param_to_param_index = {parameters[i]: i for i in range(len(parameters))}
    param_set = set(parameters)
    param_index_to_param_fqn = {}
    for (module_name, module) in self.module.named_modules():
        for (param_name, param) in module.named_parameters(recurse=False):
            fqn = f'{module_name}.{param_name}'
            if <MASK>:
                if param not in param_set:
                    self._log_and_throw(ValueError, f'Param with name {fqn} found in module parameters, but not DDP parameters. This indicates a bug in DDP, please report an issue to PyTorch.')
                param_index = param_to_param_index[param]
                param_index_to_param_fqn[param_index] = fqn
    if len(param_set) != len(param_index_to_param_fqn):
        self._log_and_throw(ValueError, f'Expected param to name mapping to cover all parameters, but got conflicting lengths: {len(param_set)} vs {len(param_index_to_param_fqn)}. This indicates a bug in DDP, please report an issue to PyTorch.')
    return param_index_to_param_fqn

