@classmethod
def combinable_nodes(cls, nodes: list[BaseSchedulerNode]) -> list[BaseSchedulerNode]:
    extern = [x for x in nodes if isinstance(x, ExternKernelSchedulerNode)]
    if extern:
        log.debug('ComboKernels: %d external nodes are filtered %s', len(extern), [node.node.get_origins() for node in extern if node.node is not None])
    filtered_nodes = [x for x in nodes if not isinstance(x, (NopKernelSchedulerNode, ExternKernelSchedulerNode))]
    foreach_nodes = [x for x in filtered_nodes if isinstance(x, ForeachKernelSchedulerNode)]
    if foreach_nodes:
        log.debug('ComboKernels: %d foreach nodes are filtered', len(foreach_nodes))
    filtered_nodes = [x for x in filtered_nodes if not isinstance(x, ForeachKernelSchedulerNode)]
    template_nodes = [x for x in filtered_nodes if x.is_template()]
    if <MASK>:
        log.debug('ComboKernels: %d template nodes are filtered: %s', len(template_nodes), template_nodes)
    filtered_nodes = [x for x in filtered_nodes if x not in template_nodes]
    return filtered_nodes

