def _initializer(shape, dtype=dtypes.float32, partition_info=None):
    """Variable initializer.

    Args:
      shape: Shape of `Tensor` to return. Should include OOV on both axes.
      dtype: Must be float32.
      partition_info: variable_scope._PartitionInfo.

    Returns:
      `Tensor` of shape `shape`.

    Raises:
      TypeError: If `dtype` is anything other than float32.
      ValueError: For shape mismatch upon invocation.
    """
    if dtype != dtypes.float32:
        raise TypeError('Currently, only float32 is supported. Received dtype: {}'.format(dtype))
    if <MASK>:
        raise ValueError('Expected 2-dim shape, but received: {}'.format(shape))
    if shape[0] <= 0:
        raise ValueError('Expected 1st dim of shape to be > 0, but received shape: {}'.format(shape))
    if shape[1] != new_col_vocab_size + num_col_oov_buckets:
        raise ValueError('Expected 2nd dim of shape to be new_col_vocab_size ({}) + num_col_oov_buckets ({}) = {}, but received shape: {}'.format(new_col_vocab_size, num_col_oov_buckets, new_col_vocab_size + num_col_oov_buckets, shape))
    offset = 0
    if partition_info is not None:
        offset = partition_info.single_offset(shape)
    if offset + shape[0] > new_row_vocab_size + num_row_oov_buckets:
        raise ValueError('Trying to initialize {} additional rows after {} rows have already been initialized, which would exceed expected total row count of new_row_vocab_size ({}) + num_row_oov_buckets ({}) = {}.'.format(shape[0], offset, new_row_vocab_size, num_row_oov_buckets, new_row_vocab_size + num_row_oov_buckets))
    row_oov_buckets_to_use = min(shape[0], max(0, offset + shape[0] - new_row_vocab_size))
    num_rows_to_load = shape[0] - row_oov_buckets_to_use
    if offset > new_row_vocab_size:
        if shape[0] != row_oov_buckets_to_use:
            raise ValueError('Partitioned variable offset is greater than new vocab size and not operating on OOV-only partition.')
        return initializer(shape)
    return _load_and_remap_matrix(ckpt_path=ckpt_path, old_tensor_name=old_tensor_name, new_row_vocab_offset=offset, num_rows_to_load=num_rows_to_load, new_col_vocab_size=new_col_vocab_size, initializer=initializer, old_row_vocab_size=old_row_vocab_size, old_row_vocab_file=old_row_vocab_file, new_row_vocab_file=new_row_vocab_file, old_col_vocab_file=old_col_vocab_file, new_col_vocab_file=new_col_vocab_file, num_row_oov_buckets=row_oov_buckets_to_use, num_col_oov_buckets=num_col_oov_buckets, max_rows_in_memory=max_rows_in_memory)

def select_cross_device_ops(devices, session_config=None):
    """Find the best `CrossDeviceOps` locally given a `tf.compat.v1.ConfigProto`.

  Args:
    devices: a list of devices passed to `tf.distribute.Strategy`.
    session_config: a `tf.compat.v1.ConfigProto` or `None`. If `None`, it will
      make decision based on all logical devices.

  Returns:
    A subclass of `CrossDeviceOps`.
  """
    requested_devices = set((device_util.canonicalize(d) for d in devices))
    if ops.executing_eagerly_outside_functions():
        logical_gpus = context.context().list_logical_devices(device_type='GPU')
        physical_gpus = context.context().list_physical_devices(device_type='GPU')
        if len(logical_gpus) != len(physical_gpus):
            logging.warning('NCCL is not supported when using virtual GPUs, fallingback to reduction to one device')
            return ReductionToOneDevice()
        machine_devices = context.context().list_logical_devices()
    else:
        machine_devices = device_lib.list_local_devices(session_config=session_config)
    using_devices = set()
    for d in machine_devices:
        if device_util.canonicalize(d.name) in requested_devices:
            using_devices.add(d.name)
    if len(using_devices) != len(requested_devices):
        logging.warning('Some requested devices in `tf.distribute.Strategy` are not visible to TensorFlow: %s', ','.join(list(requested_devices - using_devices)))
    if <MASK>:
        logging.warning('There are non-GPU devices in `tf.distribute.Strategy`, not using nccl allreduce.')
        return ReductionToOneDevice()
    if kernels.get_registered_kernels_for_op('NcclAllReduce'):
        return NcclAllReduce(num_packs=1)
    else:
        logging.warning('Nccl kernel is not found, not using nccl allreduce.')
        return ReductionToOneDevice()

def persistent_id(obj: Any) -> Optional[tuple]:
    if isinstance(obj, type) and issubclass(obj, nn.Module):
        if obj in serialized_container_types:
            return None
        serialized_container_types[obj] = True
        source_file = source = None
        try:
            (source_lines, _, source_file) = get_source_lines_and_file(obj)
            source = ''.join(source_lines)
        except Exception:
            warnings.warn("Couldn't retrieve source code for container of type " + obj.__name__ + ". It won't be checked for correctness upon loading.")
        return ('module', obj, source_file, source)
    if <MASK>:
        storage: torch.UntypedStorage
        if isinstance(obj, torch.storage.TypedStorage):
            storage = obj._untyped_storage
            storage_dtype = obj.dtype
            storage_type_str = obj._pickle_storage_type()
            storage_type = getattr(torch, storage_type_str)
            dtype = obj.dtype
            storage_numel = obj._size()
        elif isinstance(obj, torch.UntypedStorage):
            storage = obj
            storage_dtype = torch.uint8
            storage_type = normalize_storage_type(type(obj))
            dtype = torch.uint8
            storage_numel = storage.nbytes()
        else:
            raise TypeError(f'type not recognized: {type(obj)}')
        if storage.data_ptr() != 0:
            if storage.data_ptr() in storage_dtypes:
                if storage_dtype != storage_dtypes[storage.data_ptr()]:
                    raise RuntimeError('Cannot save multiple tensors or storages that view the same data as different types')
            else:
                storage_dtypes[storage.data_ptr()] = storage_dtype
        view_metadata: Optional[tuple[str, int, int]]
        offset = 0
        storage_key = str(storage._cdata)
        location = location_tag(storage)
        if storage_key not in serialized_storages:
            serialized_storages[storage_key] = (storage, dtype)
        is_view = storage._cdata != storage._cdata
        if is_view:
            view_metadata = (str(storage._cdata), offset, storage.nbytes())
        else:
            view_metadata = None
        res = ('storage', storage_type, storage_key, location, storage_numel, view_metadata)
        return res
    return None

@functools.cache
def get_device_tflops(dtype: torch.dtype) -> float:
    """
    We don't want to throw errors in this function. First check to see if the device is in device_info.py,
    then fall back to the inaccurate triton estimation.
    """
    ds_tops = datasheet_tops(dtype, is_tf32=torch.backends.cuda.matmul.allow_tf32)
    if ds_tops is not None:
        return ds_tops
    from triton.testing import get_max_simd_tflops, get_max_tensorcore_tflops
    SM80OrLater = torch.cuda.is_available() and torch.cuda.get_device_capability() >= (8, 0)
    assert dtype in (torch.float16, torch.bfloat16, torch.float32)
    if <MASK>:
        from torch._utils_internal import max_clock_rate
        sm_clock = max_clock_rate()
        if dtype in (torch.float16, torch.bfloat16) and SM80OrLater:
            return get_max_tensorcore_tflops(dtype, sm_clock)
        if torch.backends.cuda.matmul.allow_tf32:
            return get_max_tensorcore_tflops(torch.float32, sm_clock)
        else:
            return get_max_simd_tflops(torch.float32, sm_clock)
    else:
        if dtype in (torch.float16, torch.bfloat16) and SM80OrLater:
            return get_max_tensorcore_tflops(dtype)
        if torch.backends.cuda.matmul.allow_tf32:
            return get_max_tensorcore_tflops(torch.float32)
        else:
            return get_max_simd_tflops(torch.float32)

