def notebook_modification_function(notebook_content, notebook_filename):
    notebook_content_str = str(notebook_content)
    warning_template = '\n'.join(["<div class='alert alert-{message_class}'>", '', '# JupyterLite warning', '', '{message}', '</div>'])
    message_class = 'warning'
    message = 'Running the scikit-learn examples in JupyterLite is experimental and you may encounter some unexpected behavior.\n\nThe main difference is that imports will take a lot longer than usual, for example the first `import sklearn` can take roughly 10-20s.\n\nIf you notice problems, feel free to open an [issue](https://github.com/scikit-learn/scikit-learn/issues/new/choose) about it.'
    markdown = warning_template.format(message_class=message_class, message=message)
    dummy_notebook_content = {'cells': []}
    add_markdown_cell(dummy_notebook_content, markdown)
    code_lines = []
    if 'seaborn' in notebook_content_str:
        code_lines.append('%pip install seaborn')
    if 'plotly.express' in notebook_content_str:
        code_lines.append('%pip install plotly nbformat')
    if <MASK>:
        code_lines.append('%pip install scikit-image')
    if 'polars' in notebook_content_str:
        code_lines.append('%pip install polars')
    if 'fetch_' in notebook_content_str:
        code_lines.extend(['%pip install pyodide-http', 'import pyodide_http', 'pyodide_http.patch_all()'])
    code_lines.extend(['import matplotlib', 'import pandas'])
    if 'dev' in release:
        dev_docs_specific_code = ['import piplite', 'import joblib', 'import threadpoolctl', 'import scipy', f"await piplite.install(\n  'scikit-learn=={release}',\n   index_urls='https://pypi.anaconda.org/scientific-python-nightly-wheels/simple',\n)"]
        code_lines.extend(dev_docs_specific_code)
    if code_lines:
        code_lines = ['# JupyterLite-specific code'] + code_lines
        code = '\n'.join(code_lines)
        add_code_cell(dummy_notebook_content, code)
    notebook_content['cells'] = dummy_notebook_content['cells'] + notebook_content['cells']

def reconstruct(x: np.ndarray):
    from pandas.core.arrays import BooleanArray, FloatingArray, IntegerArray
    if x.dtype.kind == 'b':
        m = mask.copy()
        return BooleanArray(x, m)
    elif <MASK>:
        m = mask.copy()
        return IntegerArray(x, m)
    elif x.dtype.kind == 'f':
