def _is_valid_binary(match, computation_op, binary_op):
    binary_nodes = filter_nodes(match.nodes, binary_op)
    if len(binary_nodes) < 1:
        return False

    def get_meta_value(argument: torch.fx.node.Argument):
        if isinstance(argument, torch.fx.Node):
            return argument.meta.get('val', None)
        return None
    if any((not isinstance(get_meta_value(n.args[0]), torch.Tensor) or not isinstance(get_meta_value(n.args[1]), torch.Tensor) for n in binary_nodes)):
        return False
    if any((get_arg_value(n, 2, kwarg_name='alpha') != 1.0 and get_arg_value(n, 2, kwarg_name='alpha') is not None for n in binary_nodes)):
        return False

    def _check_input_sizes(n, computation_op):
        computation_node = n.args[0] if n.args[1] is match.kwargs['other'] else n.args[1]
        assert computation_node.target == computation_op
        computation_node_size = get_meta_value(computation_node).size()
        if computation_op is mkldnn._linear_pointwise.default:
            broadcast_sizes = []
            if <MASK>:
                broadcast_sizes = [torch.Size([1 for _ in range(len(computation_node_size) - 1)] + [computation_node_size[-1]])]
        else:
            assert len(computation_node_size) > 2
            broadcast_sizes = [torch.Size([computation_node_size[0], computation_node_size[1]] + [1 for _ in range(len(computation_node_size) - 2)]), torch.Size([1, computation_node_size[1]] + [1 for _ in range(len(computation_node_size) - 2)]), torch.Size([1 for _ in range(len(computation_node_size))])]
        return get_meta_value(match.kwargs['other']).size() in [computation_node_size] + broadcast_sizes
    if any((not _check_input_sizes(n, computation_op) or get_meta_value(n.args[0]).device != get_meta_value(n.args[1]).device or get_meta_value(n.args[0]).dtype != get_meta_value(n.args[1]).dtype for n in binary_nodes)):
        return False
    if any((n.args[0] == n.args[1] for n in binary_nodes)):
        return False
    return True

