def check_block_tiles(self, op: 'CKTileGemmOperation'):
    """
        The contiguous dimension of a tensor must be divisible by the block tile size
        This helper function enforces it for the inputs and the output.
        """
    (M, N, K) = self.get_gemm_problem_size()

    def check(dim_size, tile_size, is_padded):
        if is_static_int(dim_size) and dim_size % tile_size != 0 and (is_padded == 'false'):
            return False
        return True
    if op.layout_a == 'Row':
        return True
    elif op.layout_a == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_a={op.layout_a!r}')
    if op.layout_b == 'Row':
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif <MASK>:
        return True
    else:
        raise AssertionError(f'Invalid op.layout_b={op.layout_b!r}')
    if op.layout_c == 'Row':
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_c == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_c={op.layout_c!r}')
    return True

def serialize_keras_object(instance):
    """Serialize a Keras object into a JSON-compatible representation.

  Calls to `serialize_keras_object` while underneath the
  `SharedObjectSavingScope` context manager will cause any objects re-used
  across multiple layers to be saved with a special shared object ID. This
  allows the network to be re-created properly during deserialization.

  Args:
    instance: The object to serialize.

  Returns:
    A dict-like, JSON-compatible representation of the object's config.
  """
    (_, instance) = tf_decorator.unwrap(instance)
    if instance is None:
        return None
    supports_masking = getattr(instance, 'supports_masking', False) or (hasattr(instance, 'compute_mask') and (not is_default(instance.compute_mask)))
    if supports_masking and is_default(instance.get_config):
        warnings.warn('Custom mask layers require a config and must override get_config. When loading, the custom mask layer must be passed to the custom_objects argument.', category=CustomMaskWarning)
    if hasattr(instance, 'get_config'):
        name = get_registered_name(instance.__class__)
        try:
            config = instance.get_config()
        except NotImplementedError as e:
            if _SKIP_FAILED_SERIALIZATION:
                return serialize_keras_class_and_config(name, {_LAYER_UNDEFINED_CONFIG_KEY: True})
            raise e
        serialization_config = {}
        for (key, item) in config.items():
            if isinstance(item, str):
                serialization_config[key] = item
                continue
            try:
                serialized_item = serialize_keras_object(item)
                if <MASK>:
                    serialized_item['__passive_serialization__'] = True
                serialization_config[key] = serialized_item
            except ValueError:
                serialization_config[key] = item
        name = get_registered_name(instance.__class__)
        return serialize_keras_class_and_config(name, serialization_config, instance)
    if hasattr(instance, '__name__'):
        return get_registered_name(instance)
    raise ValueError('Cannot serialize', instance)

def read_coordinates(self, where=None, start: int | None=None, stop: int | None=None):
