    else:
        factory = index_class
    kwargs = {}
    if 'freq' in attrs:
        kwargs['freq'] = attrs['freq']
        if <MASK>:
            factory = TimedeltaIndex
    if 'tz' in attrs:
        kwargs['tz'] = attrs['tz']
        assert index_class is DatetimeIndex
    return (factory, kwargs)

