    support_virtual_devices = device_type == 'GPU'
    for dev in compatible_devices:
        device_index = device_to_indices[dev.device_type]
        device_to_indices[dev.device_type] += 1
        if dev not in self._visible_device_list:
            continue
        growth = self._memory_growth_map[dev]
        memory_growths.add(growth)
        if device_type == 'PluggableDevice':
            visible_device_list.append(dev.device_type + ':' + str(device_index))
        else:
            visible_device_list.append(str(device_index))
        if support_virtual_devices and self._virtual_device_map:
            vdevs = self._virtual_device_map.get(dev, [])
            device_ordinals = []
            device_limits = []
            priority = []
            for virt_dev in vdevs:
                if virt_dev.experimental_device_ordinal is not None:
                    device_ordinals.append(virt_dev.experimental_device_ordinal)
                device_limits.append(virt_dev.memory_limit)
                if virt_dev.experimental_priority is not None:
                    priority.append(virt_dev.experimental_priority)
            if priority and len(device_limits) != len(priority):
                raise ValueError('priority must be specified for all virtual devices')
            if device_ordinals and len(device_limits) != len(device_ordinals):
                raise ValueError('device_ordinals must be specified for all virtual devices')
            virtual_devices.append(config_pb2.GPUOptions.Experimental.VirtualDevices(memory_limit_mb=device_limits, priority=priority, device_ordinal=device_ordinals))
    if not virtual_devices and memory_growths:
        if len(memory_growths) > 1:
            raise ValueError('Memory growth cannot differ between GPU devices')
        allow_growth = memory_growths.pop()
    else:
        allow_growth = None
    return config_pb2.GPUOptions(allow_growth=allow_growth, visible_device_list=','.join(visible_device_list), experimental=config_pb2.GPUOptions.Experimental(virtual_devices=virtual_devices))

def map_placements_after_broadcast(placements: tuple[Placement, ...], shape: torch.Size, broadcast_dims_map: list[int], partial_to_replicate: bool=False) -> tuple[Placement, ...]:
    """Map each placement based on the output shape after broadcast."""
    new_placements: list[Placement] = []
    for placement in placements:
        if isinstance(placement, Partial):
            if partial_to_replicate:
                new_placements.append(Replicate())
            else:
                new_placements.append(placement)
        elif <MASK>:
            new_placements.append(placement)
        else:
            assert isinstance(placement, Shard)
            shard_dim = normalize_dim(placement.dim, len(shape))
            new_shard_dim = broadcast_dims_map[shard_dim]
            if new_shard_dim != -1:
                new_placements.append(Shard(new_shard_dim))
            else:
                new_placements.append(Replicate())
    return tuple(new_placements)

def _autograd_grad(outputs, inputs, grad_outputs=None, create_graph=False, retain_graph=None, is_grads_batched=False):
    if not isinstance(outputs, tuple):
        raise AssertionError('Expected outputs to be a tuple')
    if grad_outputs is None:
        grad_outputs = (None,) * len(outputs)
    if not isinstance(grad_outputs, tuple):
        raise AssertionError('Expected grad_outputs to be a tuple')
    if len(outputs) != len(grad_outputs):
        raise AssertionError(f'Expected outputs and grad_outputs to have the same length, but got {len(outputs)} and {len(grad_outputs)}')
    new_outputs: tuple[torch.Tensor, ...] = ()
    new_grad_outputs: tuple[torch.Tensor, ...] = ()
    for (out, grad_out) in zip(outputs, grad_outputs):
        if out is not None and out.requires_grad:
            new_outputs += (out,)
            new_grad_outputs += (grad_out,)
    if <MASK>:
        return (None,) * len(inputs)
    else:
        return torch.autograd.grad(new_outputs, inputs, new_grad_outputs, allow_unused=True, create_graph=create_graph, retain_graph=retain_graph, is_grads_batched=is_grads_batched)

def make_middleware_decorator(middleware_class):

    def _make_decorator(*m_args, **m_kwargs):

        def _decorator(view_func):
            middleware = middleware_class(view_func, *m_args, **m_kwargs)

            def _pre_process_request(request, *args, **kwargs):
                if hasattr(middleware, 'process_request'):
                    result = middleware.process_request(request)
                    if result is not None:
                        return result
                if hasattr(middleware, 'process_view'):
                    result = middleware.process_view(request, view_func, args, kwargs)
                    if result is not None:
                        return result
                return None

            def _process_exception(request, exception):
                if <MASK>:
                    result = middleware.process_exception(request, exception)
                    if result is not None:
                        return result
                raise

            def _post_process_request(request, response):
                if hasattr(response, 'render') and callable(response.render):
                    if hasattr(middleware, 'process_template_response'):
                        response = middleware.process_template_response(request, response)
                    if hasattr(middleware, 'process_response'):

                        def callback(response):
                            return middleware.process_response(request, response)
                        response.add_post_render_callback(callback)
                elif hasattr(middleware, 'process_response'):
                    return middleware.process_response(request, response)
                return response
            if iscoroutinefunction(view_func):

                async def _view_wrapper(request, *args, **kwargs):
                    result = _pre_process_request(request, *args, **kwargs)
                    if result is not None:
                        return result
                    try:
                        response = await view_func(request, *args, **kwargs)
                    except Exception as e:
                        result = _process_exception(request, e)
                        if result is not None:
                            return result
                    return _post_process_request(request, response)
            else:

                def _view_wrapper(request, *args, **kwargs):
                    result = _pre_process_request(request, *args, **kwargs)
                    if result is not None:
                        return result
                    try:
                        response = view_func(request, *args, **kwargs)
                    except Exception as e:
                        result = _process_exception(request, e)
                        if result is not None:
                            return result
                    return _post_process_request(request, response)
            return wraps(view_func)(_view_wrapper)
        return _decorator
    return _make_decorator

