def _compare_onnx_pytorch_outputs_in_np(onnx_outs: _OutputsType, pt_outs: _OutputsType, options: VerificationOptions):
    assert len(onnx_outs) == len(pt_outs), f'Number of outputs differ ONNX runtime: ({len(onnx_outs)}) PyTorch: ({len(pt_outs)})'
    acceptable_error_percentage = options.acceptable_error_percentage
    if acceptable_error_percentage and (acceptable_error_percentage > 1.0 or acceptable_error_percentage < 0.0):
        raise ValueError('If set, acceptable_error_percentage should be between 0.0 and 1.0')
    for (ort_out, pt_out) in zip(onnx_outs, pt_outs):
        try:
            if <MASK>:
                (ort_out, pt_out) = np.broadcast_arrays(ort_out, pt_out)
            torch.testing.assert_close(ort_out, pt_out, rtol=options.rtol, atol=options.atol, check_dtype=options.check_dtype, equal_nan=True)
        except AssertionError as e:
            if acceptable_error_percentage:
                error_percentage = 1 - np.sum(np.isclose(ort_out, pt_out, rtol=options.rtol, atol=options.atol)) / np.prod(ort_out.shape)
                if error_percentage <= acceptable_error_percentage:
                    warnings.warn(f'Suppressed AssertionError:\n{e}.\nError percentage {error_percentage} within acceptable range {acceptable_error_percentage}.')
                    continue
            if ort_out.dtype == np.uint8 or ort_out.dtype == np.int8:
                warnings.warn('ONNX output is quantized')
            if pt_out.dtype == np.uint8 or pt_out.dtype == np.int8:
                warnings.warn('PyTorch output is quantized')
            raise

def check_consistent_history(self, connection):
    """
        Raise InconsistentMigrationHistory if any applied migrations have
        unapplied dependencies.
        """
    recorder = MigrationRecorder(connection)
    applied = recorder.applied_migrations()
    for migration in applied:
        if <MASK>:
            continue
        for parent in self.graph.node_map[migration].parents:
            if parent not in applied:
                if parent in self.replacements:
                    if all((m in applied for m in self.replacements[parent].replaces)):
                        continue
                raise InconsistentMigrationHistory("Migration {}.{} is applied before its dependency {}.{} on database '{}'.".format(migration[0], migration[1], parent[0], parent[1], connection.alias))

def gen(self, schema: LazyIrSchema) -> list[str]:
    opkind = schema.opkind or aten_symbol(schema)
    all_args = schema.filtered_args()
    scalar_args = schema.filtered_args(values=False, scalars=True)
    ctor_args = [f'const {i.lazy_type.cpp_type()}& {i.name}' for i in all_args]
    reuse_ctor_args = ', '.join(ctor_args)
    if self.use_lazy_shape and schema.properties.ShapePrecompute:
        ctor_args.append('std::vector<torch::lazy::Shape>&& shapes')
    node_ctor_args = ', '.join(ctor_args)
    scalar_initializers = ',
        '.join([f'{a.name}({a.name}.has_value() ? ::std::make_optional(std::string(*{a.name})) : ::std::nullopt)' if a.lazy_type.cpp_type() == '::std::optional<c10::string_view>' else f'{a.name}({a.name})' for a in scalar_args])
    if len(scalar_initializers):
        scalar_initializers = f',
        {scalar_initializers}'
    scalar_decls = '
  '.join([f'std::string {a.name};' if a.lazy_type.cpp_type() == 'c10::string_view' else f'::std::optional<std::string> {a.name};' if a.lazy_type.cpp_type() == '::std::optional<c10::string_view>' else f'{a.lazy_type.cpp_type()} {a.name};' for a in scalar_args])
    optional_values = [arg.name for arg in schema.filtered_args(values=True, scalars=False) if isinstance(arg.lazy_type, OptionalCType)]
    has_optional_decls = '
  '.join([f'bool has_{value}: 1;' for value in optional_values])
    has_optional_defs = '
    '.join([f'has_{value} = !!{value};' for value in optional_values])
    members_to_string = []
    for arg in scalar_args:
        if <MASK>:
            value = f'{arg.name}.value()'
            if arg.is_generator:
                value = '"torch.Generator()"'
            members_to_string.append(f'if ({arg.name}.has_value()) {{
      ss << ", {arg.name}=" << {value};
    }} else {{
      ss << ", {arg.name}=null";
    }}')
        else:
            members_to_string.append(f'ss << ", {arg.name}=" << {arg.name};')
    members_to_string_str = '
    '.join(members_to_string)
    return [f'class {schema.node_name} : public {self.node_base} {{
 public:
  static torch::lazy::OpKind ClassOpKind() {{
    return torch::lazy::OpKind({opkind});
  }}

  {schema.node_name}({node_ctor_args})
      : {self.node_base_ctor_call(schema)}{scalar_initializers}
  {{
    {has_optional_defs}
  }}

  std::string ToString() const override {{
    std::stringstream ss;
    ss << {self.node_base}::ToString();
    {members_to_string_str}
    return ss.str();
  }}

  {self.create_function(schema, reuse_ctor_args)}

  {self.can_be_reused_function(schema, reuse_ctor_args)}

  {self.lowering_function(schema)}

  {scalar_decls}
  {has_optional_decls}

}};

']

@simple_wraps(mod)
def functional_call(*args, **kwargs):
    flat_params = args[:params_len]
    if isinstance(params_spec, TreeSpec):
        params = pytree.tree_unflatten(flat_params, params_spec)
    else:
        assert isinstance(params_spec, list)
        params = dict(zip(params_spec, flat_params))
    with stateless._reparametrize_module(mod, params), maybe_disable_thunkify():
        if <MASK>:
            if kwargs:
                arg_list = list(args[params_len:])
                arg_list.extend(list(kwargs.values()))
                args = tuple(arg_list)
            else:
                args = args[params_len:]
            with fx_traceback.preserve_node_meta(), warnings.catch_warnings():
                warnings.filterwarnings('ignore', 'Anomaly Detection has been enabled.')
                with torch.autograd.detect_anomaly(check_nan=False):
                    fake_mode = detect_fake_mode()
                    assert fake_mode is not None
                    fake_mode.epoch += 1
                    out = PropagateUnbackedSymInts(mod).run(*args)
        else:
            out = mod(*args[params_len:], **kwargs)
    if strict_out_tuple and (not isinstance(out, (tuple, list))):
        raise RuntimeError('Graph output must be a (). This is so that we can avoid pytree processing of the outputs. Please change the module to have tuple outputs or use aot_module instead.')
    return out

def __init__(self, content, name=None, namespace=None, stacklevel=None, get_template=None, default_inherit=None, line_offset=0, delimiters=None):
    self.content = content
    if delimiters is None:
        delimiters = (self.default_namespace['start_braces'], self.default_namespace['end_braces'])
    else:
        self.default_namespace = self.__class__.default_namespace.copy()
        self.default_namespace['start_braces'] = delimiters[0]
        self.default_namespace['end_braces'] = delimiters[1]
    self.delimiters = delimiters
    self._unicode = isinstance(content, str)
    if name is None and stacklevel is not None:
        try:
            caller = sys._getframe(stacklevel)
        except ValueError:
            pass
        else:
            globals = caller.f_globals
            lineno = caller.f_lineno
            if '__file__' in globals:
                name = globals['__file__']
                if <MASK>:
                    name = name[:-1]
            elif '__name__' in globals:
                name = globals['__name__']
            else:
                name = '<string>'
            if lineno:
                name += ':%s' % lineno
    self.name = name
    self._parsed = parse(content, name=name, line_offset=line_offset, delimiters=self.delimiters)
    if namespace is None:
        namespace = {}
    self.namespace = namespace
    self.get_template = get_template
    if default_inherit is not None:
        self.default_inherit = default_inherit

def common_supertype(a, b):
    result = a.most_specific_common_supertype([b])
    if <MASK>:
        raise TypeError(f'No common supertype of {a} and {b}.')
    return result

def print_all_configs(configs, missing, warning):
    """Prints the status and info on all configurations in a table format.

  Args:
    configs: List of all configurations found.
    missing: List of all configurations that are missing.
    warning: List of all configurations found with warnings.
  """
    print_text = ''
    llen = 65
    for (i, row) in enumerate(configs):
        if i != 0:
            print_text += '-' * llen + '\n'
        if isinstance(row[1], list):
            val = ', '.join(row[1])
        else:
            val = row[1]
        print_text += ' {: <28}'.format(row[0]) + '    {: <25}'.format(val) + '\n'
    print_text += '=' * llen
    print('\n\n {: ^32}    {: ^25}'.format('Configuration(s)', 'Detected value(s)'))
    print('=' * llen)
    print(print_text)
    if <MASK>:
        print('\n * ERROR: The following configurations are missing:')
        for m in missing:
            print('   ', *m)
    if warning:
        print('\n * WARNING: The following configurations could cause issues:')
        for w in warning:
            print('   ', *w)
    if not missing and (not warning):
        print('\n * INFO: Successfully found all configurations.')
    print('\n')

