def _check_choices(self):
    if not self.choices:
        return []
    if not isinstance(self.choices, Iterable) or isinstance(self.choices, str):
        return [checks.Error("'choices' must be a mapping (e.g. a dictionary) or an iterable (e.g. a list or tuple).", obj=self, id='fields.E004')]
    choice_max_length = 0
    for choices_group in self.choices:
        try:
            (group_name, group_choices) = choices_group
        except (TypeError, ValueError):
            break
        try:
            if not all((self._choices_is_value(value) and self._choices_is_value(human_name) for (value, human_name) in group_choices)):
                break
            if self.max_length is not None and group_choices:
                choice_max_length = max([choice_max_length, *(len(value) for (value, _) in group_choices if isinstance(value, str))])
        except (TypeError, ValueError):
            (value, human_name) = (group_name, group_choices)
            if not self._choices_is_value(value) or not self._choices_is_value(human_name):
                break
            if self.max_length is not None and isinstance(value, str):
                choice_max_length = max(choice_max_length, len(value))
        if <MASK>:
            break
    else:
        if self.max_length is not None and choice_max_length > self.max_length:
            return [checks.Error("'max_length' is too small to fit the longest value in 'choices' (%d characters)." % choice_max_length, obj=self, id='fields.E009')]
        return []
    return [checks.Error("'choices' must be a mapping of actual values to human readable names or an iterable containing (actual value, human readable name) tuples.", obj=self, id='fields.E005')]

def modified_arguments(self, kwargs, requested_parameters):
    strategy = None
    for (_, v) in kwargs.items():
        if <MASK>:
            if strategy is not None and _num_total_workers(v.has_chief, v.num_workers) > 1:
                raise ValueError('Only support one NamedDistribution for multi workertests.')
            strategy = v
    if strategy:
        has_chief = strategy.has_chief
        num_workers = strategy.num_workers
        runner = strategy.runner
        share_gpu = strategy.share_gpu
        num_ps = strategy.num_ps
        if 'has_chief' in kwargs and kwargs['has_chief'] != has_chief:
            raise ValueError('both has_chief and strategy specified but are not compatible')
        if 'num_workers' in kwargs and kwargs['num_workers'] != num_workers:
            raise ValueError('both num_workers and strategy specified but are not compatible')
    else:
        has_chief = kwargs.get('has_chief', False)
        num_workers = kwargs.get('num_workers', 1)
        runner = kwargs.get('runner', None)
        share_gpu = kwargs.get('share_gpu', True)
        num_ps = kwargs.get('num_ps', 0)
    update = {}
    if 'has_chief' in requested_parameters:
        update['has_chief'] = has_chief
    if 'num_workers' in requested_parameters:
        update['num_workers'] = num_workers
    if 'runner' in requested_parameters:
        update['runner'] = runner
    if 'share_gpu' in requested_parameters:
        update['share_gpu'] = share_gpu
    if 'num_ps' in requested_parameters:
        update['num_ps'] = num_ps
    return update

def infer_inputs_from_restored_call_function(fn):
    """Returns TensorSpec of inputs from a restored call function.

  Args:
    fn: Restored layer call function. It is assumed that `fn` has at least
        one concrete function and that the inputs are in the first argument.

  Returns:
    TensorSpec of call function inputs.
  """

    def common_spec(x, y):
        common_shape = get_common_shape(x.shape, y.shape)
        if <MASK>:
            return sparse_tensor.SparseTensorSpec(common_shape, x.dtype)
        elif isinstance(x, ragged_tensor.RaggedTensorSpec):
            return ragged_tensor.RaggedTensorSpec(common_shape, x.dtype)
        return tensor_spec.TensorSpec(common_shape, x.dtype, x.name)
    spec = fn.concrete_functions[0].structured_input_signature[0][0]
    for concrete in fn.concrete_functions[1:]:
        spec2 = concrete.structured_input_signature[0][0]
        spec = nest.map_structure(common_spec, spec, spec2)
    return spec

