def _save(obj, zip_file, pickle_module, pickle_protocol, _disable_byteorder_record):
    serialized_storages: dict[str, torch.storage.UntypedStorage] = {}
    id_map: dict[int, str] = {}
    storage_dtypes: dict[int, torch.dtype] = {}

    def persistent_id(obj):
        if isinstance(obj, torch.storage.TypedStorage) or torch.is_storage(obj):
            if isinstance(obj, torch.storage.TypedStorage):
                storage = obj._untyped_storage
                storage_dtype = obj.dtype
                storage_type_str = obj._pickle_storage_type()
                storage_type = getattr(torch, storage_type_str)
                storage_numel = obj._size()
            else:
                storage = obj
                storage_dtype = torch.uint8
                storage_type = normalize_storage_type(type(obj))
                storage_numel = storage.nbytes()
            if str(storage.device) != 'meta' and storage.data_ptr() != 0:
                if storage.data_ptr() in storage_dtypes:
                    if <MASK>:
                        raise RuntimeError('Cannot save multiple tensors or storages that view the same data as different types')
                else:
                    storage_dtypes[storage.data_ptr()] = storage_dtype
            storage_key = id_map.setdefault(storage._cdata, str(len(id_map)))
            if hasattr(obj, '_fake_device') and obj._fake_device is not None:
                location = str(obj._fake_device)
            else:
                location = location_tag(storage)
            serialized_storages[storage_key] = storage
            return ('storage', storage_type, storage_key, location, storage_numel)
        return None
    data_buf = io.BytesIO()

    class PyTorchPickler(pickle_module.Pickler):

        def persistent_id(self, obj):
            return persistent_id(obj)
    pickler = PyTorchPickler(data_buf, protocol=pickle_protocol)
    pickler.dump(obj)
    data_value = data_buf.getvalue()
    zip_file.write_record('data.pkl', data_value, len(data_value))
    zip_file.write_record('.format_version', '1', len('1'))
    storage_alignment = str(_get_storage_alignment())
    zip_file.write_record('.storage_alignment', storage_alignment, len(storage_alignment))
    if not _disable_byteorder_record:
        if sys.byteorder not in ['little', 'big']:
            raise ValueError('Unknown endianness type: ' + sys.byteorder)
        zip_file.write_record('byteorder', sys.byteorder, len(sys.byteorder))
    for key in serialized_storages.keys():
        name = f'data/{key}'
        storage = serialized_storages[key]
        num_bytes = storage.nbytes()
        global _serialization_tls
        if _serialization_tls.skip_data:
            zip_file.write_record_metadata(name, num_bytes)
        else:
            if storage.device.type != 'cpu':
                from torch.utils.serialization import config
                if config.save.use_pinned_memory_for_d2h and (acc := torch.accelerator.current_accelerator(check_available=True)) is not None and (acc.type == storage.device.type):
                    new_storage = torch.empty(num_bytes, dtype=torch.uint8, device='cpu', pin_memory=True).untyped_storage()
                    new_storage.copy_(storage)
                    torch.accelerator.current_stream(storage.device.index).synchronize()
                    storage = new_storage
                else:
                    storage = storage.cpu()
            zip_file.write_record(name, storage, num_bytes)

def read(self, index, name=None):
    """See TensorArray."""
    del name
    if isinstance(index, ops.EagerTensor):
        index = index.numpy()
    if index < 0:
        raise errors_impl.OutOfRangeError(None, None, 'Reading from negative indices (index %d) is not allowed.' % index)
    if index >= len(self._tensor_array):
        raise errors_impl.OutOfRangeError(None, None, 'Tried to read from index %d but array size is: %d ' % (index, len(self._tensor_array)))
    tensor = self._tensor_array[index]
    if tensor is None:
        if <MASK>:
            raise errors_impl.InvalidArgumentError(None, None, 'Could not read index %d twice because it was cleared after a previous read (perhaps try setting clear_after_read = false?)' % index)
        else:
            tensor = self._maybe_zero(index)
    if self._clear_after_read:
        self._tensor_array[index] = None
        self._previously_read_indices.append(index)
    return tensor

def _xy_helper_corrcoef(x_tensor, y_tensor=None, rowvar=True):
    """Prepare inputs for cov and corrcoef."""
    if y_tensor is not None:
        ndim_extra = 2 - x_tensor.ndim
        if ndim_extra > 0:
            x_tensor = x_tensor.view((1,) * ndim_extra + x_tensor.shape)
        if <MASK>:
            x_tensor = x_tensor.mT
        x_tensor = x_tensor.clone()
        ndim_extra = 2 - y_tensor.ndim
        if ndim_extra > 0:
            y_tensor = y_tensor.view((1,) * ndim_extra + y_tensor.shape)
        if not rowvar and y_tensor.shape[0] != 1:
            y_tensor = y_tensor.mT
        y_tensor = y_tensor.clone()
        x_tensor = _concatenate((x_tensor, y_tensor), axis=0)
    return x_tensor

def _init_mp_dtypes(self) -> None:
    for fsdp_param in self.fsdp_params:
        fsdp_param.init_dtype_attrs(self.mp_policy)
    trainable_params: list[FSDPParam] = [p for p in self.fsdp_params if p.sharded_param.requires_grad]
    orig_dtypes = {p.orig_dtype for p in trainable_params}
    reduce_dtypes = {p.reduce_dtype for p in trainable_params}
    if len(trainable_params) > 0 and len(orig_dtypes) != 1:
        raise AssertionError(f'FSDP expects uniform original parameter dtype but got {orig_dtypes}')
    self._orig_dtype = next(iter(orig_dtypes)) if trainable_params else None
    if <MASK>:
        raise AssertionError(f'FSDP expects uniform reduce dtype but got {reduce_dtypes}')
    self._reduce_dtype = next(iter(reduce_dtypes)) if trainable_params else None

def __call__(self) -> dict[torch.fx.Node, NodeSet]:
    result: dict[torch.fx.Node, NodeSet] = {}
    acc_nodes = list(self.acc_nodes)
    for node in acc_nodes:
        if node in result:
            continue
        if node.op not in CALLABLE_NODE_OPS:
            continue
        if 'tensor_meta' in node.meta:
            continue
        if node not in self.acc_nodes:
            continue
        fusion_group: FxNetAccFusionsFinder.FusionGroup = self.FusionGroup(top_node_idx=self.nodes.index(node), nodes={node}, inputs=set(node.all_input_nodes), nodes_need_process={node})
        while fusion_group.nodes_need_process:
            node = fusion_group.nodes_need_process.pop()
            self.recursive_add_node(fusion_group, fusion_group.inputs, visited=set())
            if 'tensor_meta' not in node.meta:
                for user in node.users:
                    if user.op not in CALLABLE_NODE_OPS:
                        continue
                    if user in fusion_group.nodes:
                        continue
                    fusion_group.add_node(user)
                    self.recursive_add_node(fusion_group, fusion_group.inputs, visited=set())
            for arg in node.all_input_nodes:
                if <MASK>:
                    continue
                if 'tensor_meta' in arg.meta:
                    continue
                if arg in fusion_group.nodes:
                    continue
                fusion_group.add_node(arg)
                fusion_group.top_node_idx = min(fusion_group.top_node_idx, self.nodes.index(arg))
                self.recursive_add_node(fusion_group, fusion_group.inputs, visited=set())
        if not set(fusion_group.nodes) <= self.acc_nodes:
            self.acc_nodes -= fusion_group.nodes
        else:
            for n in fusion_group.nodes:
                result[n] = fusion_group.nodes
    return result

def to_real_tensor(e):
    if cls.fake_mode.is_our_fake(e):
        if <MASK>:
            out = torch.rand_like(e, device=e.fake_device)
        else:
            out = torch.ones_like(e, device=e.fake_device)
        if e.is_sparse:
            out._coalesced_(e.is_coalesced())
        inp_impls[id(out)] = e
        return out
    return e

def evaluate_candidates(candidate_params, cv=None, more_results=None):
    cv = cv or cv_orig
    candidate_params = list(candidate_params)
    n_candidates = len(candidate_params)
    if self.verbose > 0:
        print('Fitting {0} folds for each of {1} candidates, totalling {2} fits'.format(n_splits, n_candidates, n_candidates * n_splits))
    out = parallel((delayed(_fit_and_score)(clone(base_estimator), X, y, train=train, test=test, parameters=parameters, split_progress=(split_idx, n_splits), candidate_progress=(cand_idx, n_candidates), **fit_and_score_kwargs) for ((cand_idx, parameters), (split_idx, (train, test))) in product(enumerate(candidate_params), enumerate(cv.split(X, y, **routed_params.splitter.split)))))
    if len(out) < 1:
        raise ValueError('No fits were performed. Was the CV iterator empty? Were there no candidates?')
    elif len(out) != n_candidates * n_splits:
        raise ValueError('cv.split and cv.get_n_splits returned inconsistent results. Expected {} splits, got {}'.format(n_splits, len(out) // n_candidates))
    _warn_or_raise_about_fit_failures(out, self.error_score)
    if <MASK>:
        _insert_error_scores(out, self.error_score)
    all_candidate_params.extend(candidate_params)
    all_out.extend(out)
    if more_results is not None:
        for (key, value) in more_results.items():
            all_more_results[key].extend(value)
    nonlocal results
    results = self._format_results(all_candidate_params, n_splits, all_out, all_more_results)
    return results

def traverse(self, visit, *args, **kwargs):
    """Traverse expression tree with visit function.

        The visit function is applied to an expression with given args
        and kwargs.

        Traverse call returns an expression returned by visit when not
        None, otherwise return a new normalized expression with
        traverse-visit sub-expressions.
        """
    result = visit(self, *args, **kwargs)
    if result is not None:
        return result
    if self.op in (Op.INTEGER, Op.REAL, Op.STRING, Op.SYMBOL):
        return self
    elif self.op in (Op.COMPLEX, Op.ARRAY, Op.CONCAT, Op.TERNARY):
        return normalize(Expr(self.op, tuple((item.traverse(visit, *args, **kwargs) for item in self.data))))
    elif self.op in (Op.TERMS, Op.FACTORS):
        data = {}
        for (k, v) in self.data.items():
            k = k.traverse(visit, *args, **kwargs)
            v = v.traverse(visit, *args, **kwargs) if isinstance(v, Expr) else v
            if k in data:
                v = data[k] + v
            data[k] = v
        return normalize(Expr(self.op, data))
    elif self.op is Op.APPLY:
        obj = self.data[0]
        func = obj.traverse(visit, *args, **kwargs) if isinstance(obj, Expr) else obj
        operands = tuple((operand.traverse(visit, *args, **kwargs) for operand in self.data[1]))
        kwoperands = {k: v.traverse(visit, *args, **kwargs) for (k, v) in self.data[2].items()}
        return normalize(Expr(self.op, (func, operands, kwoperands)))
    elif <MASK>:
        obj = self.data[0]
        obj = obj.traverse(visit, *args, **kwargs) if isinstance(obj, Expr) else obj
        indices = tuple((index.traverse(visit, *args, **kwargs) for index in self.data[1:]))
        return normalize(Expr(self.op, (obj,) + indices))
    elif self.op in (Op.REF, Op.DEREF):
        return normalize(Expr(self.op, self.data.traverse(visit, *args, **kwargs)))
    elif self.op is Op.RELATIONAL:
        (rop, left, right) = self.data
        left = left.traverse(visit, *args, **kwargs)
        right = right.traverse(visit, *args, **kwargs)
        return normalize(Expr(self.op, (rop, left, right)))
    raise NotImplementedError(f'traverse method for {self.op}')

def _compile_end() -> None:
    global _cumulative_compile_time, _t0, _triton_kernel_metrics
    if <MASK>:
        t1 = time()
        _cumulative_compile_time += t1 - _t0
        _t0 = None
    if _triton_kernel_metrics:
        sorted_info = dict(sorted(_triton_kernel_metrics.items()))
        torch._logging.trace_structured('artifact', metadata_fn=lambda : {'name': 'triton_kernel_info', 'encoding': 'json'}, payload_fn=lambda : json.dumps(sorted_info))
        _triton_kernel_metrics = None

def huber_loss(input: Tensor, target: Tensor, reduction: str='mean', delta: float=1.0, weight: Optional[Tensor]=None) -> Tensor:
    """Compute the Huber loss, with optional weighting.

    Function uses a squared term if the absolute
    element-wise error falls below delta and a delta-scaled L1 term otherwise.

    When delta equals 1, this loss is equivalent to SmoothL1Loss.
    In general, Huber loss differs from SmoothL1Loss by a factor of delta (AKA beta in Smooth L1).

    See :class:`~torch.nn.HuberLoss` for details.

    Args:
        input (Tensor): Predicted values.
        target (Tensor): Ground truth values.
        reduction (str, optional): Specifies the reduction to apply to the output:
                                   'none' | 'mean' | 'sum'. 'mean': the mean of the output is taken.
                                   'sum': the output will be summed. 'none': no reduction will be applied.
                                   Default: 'mean'.
        delta (float, optional): The threshold at which to change between delta-scaled L1 and L2 loss. Default: 1.0.
        weight (Tensor, optional): Weights for each sample. Default: None.

    Returns:
        Tensor: Huber loss (optionally weighted).
    """
    if <MASK>:
        return handle_torch_function(huber_loss, (input, target, weight), input, target, reduction=reduction, delta=delta, weight=weight)
    if target.size() != input.size():
        warnings.warn(f'Using a target size ({target.size()}) that is different to the input size ({input.size()}). This will likely lead to incorrect results due to broadcasting. Please ensure they have the same size.', stacklevel=2)
    (expanded_input, expanded_target) = torch.broadcast_tensors(input, target)
    if weight is None:
        return torch._C._nn.huber_loss(expanded_input, expanded_target, _Reduction.get_enum(reduction), delta)
    else:
        if weight.size() != input.size():
            raise ValueError('Weights and input must have the same size.')
        unweighted_loss = torch._C._nn.huber_loss(expanded_input, expanded_target, _Reduction.get_enum('none'), delta)
        weighted_loss = unweighted_loss * weight
        if reduction == 'none':
            return weighted_loss
        elif reduction == 'sum':
            return torch.sum(weighted_loss)
        elif reduction == 'mean':
            return weighted_loss.mean()
        else:
            raise ValueError(f"Invalid reduction mode: {reduction}. Expected one of 'none', 'mean', 'sum'.")

def _parse_with_reso(self, label: str) -> tuple[Timestamp, Resolution]:
