@combinations.generate(combinations.times(test_base.default_test_combinations(), checkpoint_test_base.default_test_combinations(), combinations.combine(symbolic_checkpoint=[True], num_skips=[3, 4])))
def testWithSkip(self, verify_fn, symbolic_checkpoint, num_skips):
    """Test `.flat_map().skip()` checkpointing behavior.

    `SkipInternal` and `GetNextInternal` are separate functions
    but with slightly different implementations.
    Therefore, we should test this op's behavior when used with `.skip()`.

    Args:
      verify_fn: Verify the correctness of this dataset's checkpointing.
      symbolic_checkpoint: Whether symbolic checkpointing is turned on.
      num_skips: `.skip(num_skips)`
    """

    def build_dataset():

        def my_map(x):
            if x == 0:
                return dataset_ops.Dataset.from_tensor_slices([0, 1, 2, 3])
            elif <MASK>:
                return dataset_ops.Dataset.from_tensor_slices([4, 5, 6, 7])
            else:
                return dataset_ops.Dataset.from_tensor_slices([8, 9, 10, 11])
        indices = dataset_ops.Dataset.from_tensor_slices([0, 1, 2])
        dataset = indices.flat_map(my_map)
        dataset = dataset.skip(num_skips)
        options = options_lib.Options()
        options.experimental_symbolic_checkpoint = symbolic_checkpoint
        return dataset.with_options(options)
    verify_fn(self, build_dataset, num_outputs=3 * 4 - num_skips)

def sample_inputs_linalg_solve_triangular(op_info, device, dtype, requires_grad=False, **kwargs):
    make_arg = partial(make_tensor, dtype=dtype, device=device)
    bs = (1, 2, 0)
    ns = (3, 0)
    ks = (1, 3, 0)
    for (b, n, k, (left, upper, uni)) in product(bs, ns, ks, product((True, False), repeat=3)):
        if b == 1:
            A = make_arg((n, n)) if left else make_arg((k, k))
            B = make_arg((n, k))
        else:
            A = make_arg((b, n, n)) if left else make_arg((b, k, k))
            B = make_arg((b, n, k))
        if uni:
            A.diagonal(0, -2, -1).fill_(1.0)
        else:
            d = A.diagonal(0, -2, -1)
            d[d.abs() < 1e-06] = 1.0
        if <MASK>:
            A.triu_()
        else:
            A.tril_()
        kwargs = {'upper': upper, 'left': left, 'unitriangular': uni}
        if requires_grad:
            for (grad_A, grad_B) in product((True, False), repeat=2):
                if not grad_A and (not grad_B):
                    continue
                yield SampleInput(A.clone().requires_grad_(grad_A), args=(B.clone().requires_grad_(grad_B),), kwargs=kwargs)
        else:
            yield SampleInput(A, args=(B,), kwargs=kwargs)

def predict(self, X, return_std=False, return_cov=False):
    """Predict using the Gaussian process regression model.

        We can also predict based on an unfitted model by using the GP prior.
        In addition to the mean of the predictive distribution, optionally also
        returns its standard deviation (`return_std=True`) or covariance
        (`return_cov=True`). Note that at most one of the two can be requested.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features) or list of object
            Query points where the GP is evaluated.

        return_std : bool, default=False
            If True, the standard-deviation of the predictive distribution at
            the query points is returned along with the mean.

        return_cov : bool, default=False
            If True, the covariance of the joint predictive distribution at
            the query points is returned along with the mean.

        Returns
        -------
        y_mean : ndarray of shape (n_samples,) or (n_samples, n_targets)
            Mean of predictive distribution at query points.

        y_std : ndarray of shape (n_samples,) or (n_samples, n_targets), optional
            Standard deviation of predictive distribution at query points.
            Only returned when `return_std` is True.

        y_cov : ndarray of shape (n_samples, n_samples) or                 (n_samples, n_samples, n_targets), optional
            Covariance of joint predictive distribution at query points.
            Only returned when `return_cov` is True.
        """
    if return_std and return_cov:
        raise RuntimeError('At most one of return_std or return_cov can be requested.')
    if <MASK>:
        (dtype, ensure_2d) = ('numeric', True)
    else:
        (dtype, ensure_2d) = (None, False)
    X = validate_data(self, X, ensure_2d=ensure_2d, dtype=dtype, reset=False)
    if not hasattr(self, 'X_train_'):
        if self.kernel is None:
            kernel = C(1.0, constant_value_bounds='fixed') * RBF(1.0, length_scale_bounds='fixed')
        else:
            kernel = self.kernel
        n_targets = self.n_targets if self.n_targets is not None else 1
        y_mean = np.zeros(shape=(X.shape[0], n_targets)).squeeze()
        if return_cov:
            y_cov = kernel(X)
            if n_targets > 1:
                y_cov = np.repeat(np.expand_dims(y_cov, -1), repeats=n_targets, axis=-1)
            return (y_mean, y_cov)
        elif return_std:
            y_var = kernel.diag(X)
            if n_targets > 1:
                y_var = np.repeat(np.expand_dims(y_var, -1), repeats=n_targets, axis=-1)
            return (y_mean, np.sqrt(y_var))
        else:
            return y_mean
    else:
        K_trans = self.kernel_(X, self.X_train_)
        y_mean = K_trans @ self.alpha_
        y_mean = self._y_train_std * y_mean + self._y_train_mean
        if y_mean.ndim > 1 and y_mean.shape[1] == 1:
            y_mean = np.squeeze(y_mean, axis=1)
        if not return_cov and (not return_std):
            return y_mean
        V = solve_triangular(self.L_, K_trans.T, lower=GPR_CHOLESKY_LOWER, check_finite=False)
        if return_cov:
            y_cov = self.kernel_(X) - V.T @ V
            y_cov = np.outer(y_cov, self._y_train_std ** 2).reshape(*y_cov.shape, -1)
            if y_cov.shape[2] == 1:
                y_cov = np.squeeze(y_cov, axis=2)
            return (y_mean, y_cov)
        else:
            y_var = self.kernel_.diag(X).copy()
            y_var -= np.einsum('ij,ji->i', V.T, V)
            y_var_negative = y_var < 0
            if np.any(y_var_negative):
                warnings.warn('Predicted variances smaller than 0. Setting those variances to 0.')
                y_var[y_var_negative] = 0.0
            y_var = np.outer(y_var, self._y_train_std ** 2).reshape(*y_var.shape, -1)
            if y_var.shape[1] == 1:
                y_var = np.squeeze(y_var, axis=1)
            return (y_mean, np.sqrt(y_var))

