def call_getattr(self, tx: 'InstructionTranslator', obj: VariableTracker, name_var: VariableTracker, default=None):
    if not name_var.is_python_constant():
        unimplemented_v2(gb_type='getattr() with non-constant name argument', context=f'getattr({obj}, {name_var}, {default})', explanation='getattr() with non-constant name argument is not supported', hints=['Ensure the name argument of getattr() is a string'])
    name = name_var.as_python_constant()
    if isinstance(obj, TensorVariable) and name == '_grad':
        name = 'grad'
    if tx.output.side_effects.is_attribute_mutation(obj):
        if <MASK>:
            if name in ('named_parameters', 'parameters', 'named_buffers', 'buffers', 'named_modules', 'modules') and obj.is_state_mutated and tx.output.side_effects.has_pending_mutation(obj):
                unimplemented_v2(gb_type='getattr() on nn.Module with pending mutation', context=f'getattr({obj}, {name}, {default})', explanation='Intentionally graph breaking on getattr() on a nn.Module with a pending mutation', hints=[])
    if tx.output.side_effects.has_pending_mutation_of_attr(obj, name):
        return tx.output.side_effects.load_attr(obj, name)
    if default is not None:
        hasattr_var = self.call_hasattr(tx, obj, name_var)
        assert hasattr_var.as_python_constant() in (True, False)
        if not hasattr_var.as_python_constant():
            return default
    source = obj.source and AttrSource(obj.source, name)
    if name in {'__bases__', '__base__', '__flags__'}:
        try:
            value = obj.as_python_constant()
            if isinstance(value, type):
                if name == '__bases__':
                    tuple_args = [VariableTracker.build(tx, b, source and GetItemSource(source, i)) for (i, b) in enumerate(value.__bases__)]
                    return variables.TupleVariable(tuple_args, source=source)
                if name == '__base__':
                    return VariableTracker.build(tx, value.__base__, source)
                if name == '__flags__':
                    return ConstantVariable.create(value.__flags__)
        except NotImplementedError:
            pass
    if isinstance(obj, variables.NNModuleVariable):
        return obj.var_getattr(tx, name)
    elif isinstance(obj, (variables.TensorVariable, variables.NamedTupleVariable, variables.ConstantVariable, variables.DistributedVariable, variables.UserDefinedClassVariable, variables.UserDefinedObjectVariable)):
        if isinstance(obj, variables.UserDefinedObjectVariable) and issubclass(obj.value.__class__, unittest.TestCase) and config.enable_trace_unittest and (name in ('assertRaisesRegex', 'assertNotWarns', 'assertWarnsRegex', 'assertWarns')):
            unimplemented_v2(gb_type='Failed to trace unittest method', context=f'function: unittest.TestCase.{name}', explanation=f'Dynamo does not know how to trace unittest method `{name}` ', hints=[f'Avoid calling `TestCase.{name}`. Please report an issue to PyTorch.'])
        if isinstance(obj, TensorVariable):
            fake_val = obj.proxy.node.meta['example_value']
            if isinstance(fake_val, torch.Tensor) and is_sparse_any(fake_val) and (not tx.export or not config.capture_sparse_compute):
                unimplemented_v2(gb_type='Attempted to wrap sparse Tensor', context='', explanation='torch.compile does not support sparse Tensors', hints=[*graph_break_hints.SUPPORTABLE])
        try:
            return obj.var_getattr(tx, name)
        except NotImplementedError:
            return variables.GetAttrVariable(obj, name, source=source)
    elif isinstance(obj, variables.TorchInGraphFunctionVariable):
        member = getattr(obj.value, name)
        if isinstance(member, (torch._ops.OpOverloadPacket, torch._ops.OpOverload)) and torch._dynamo.trace_rules.is_aten_op_or_tensor_method(member):
            return variables.TorchInGraphFunctionVariable(member, source=source)
        elif name in cmp_name_to_op_mapping:
            return variables.GetAttrVariable(obj, name, source=source)
    elif isinstance(obj, DummyModule):
        if obj.is_torch or name not in obj.value.__dict__:
            member = getattr(obj.value, name)
        else:
            member = obj.value.__dict__[name]
        if config.replay_record_enabled:
            tx.exec_recorder.record_module_access(obj.value, name, member)
        return VariableTracker.build(tx, member, source)
    elif istype(obj, variables.UserFunctionVariable) and name in ('__name__', '__module__'):
        return ConstantVariable.create(getattr(obj.fn, name))
    else:
        try:
            return obj.var_getattr(tx, name)
        except NotImplementedError:
            return variables.GetAttrVariable(obj, name, source=source)

def getsetitem(self: Any, index: Any, tensors_have_dims: bool) -> IndexingInfo:
    from . import DimList
    can_call_original_getitem = not tensors_have_dims
    input_list = []
    if has_dims(index):
        input_list.append(index)
    else:
        is_sequence = extractIndices(index, input_list)
        if can_call_original_getitem and (not is_sequence):
            return IndexingInfo(can_call_original=True)
    dims_indexed = 0
    expanding_object = -1
    unbound_dim_list = None
    dimlists = []

    def check_expanding(i: int) -> None:
        nonlocal expanding_object
        if expanding_object != -1:
            from . import DimensionBindError
            raise DimensionBindError(f'at most one ... or unbound dimension list can exist in indexing list but found 2 at offsets {expanding_object} and {i}')
        expanding_object = i

    def is_dimpack(s: Any) -> bool:
        from . import Dim
        return isinstance(s, (tuple, list)) and len(s) > 0 and all((Dim.check_exact(item) for item in s))
    has_dimpacks_or_none = False
    for (i, s) in enumerate(input_list):
        if has_dims(s):
            can_call_original_getitem = False
            dims_indexed += 1
        elif s is ...:
            check_expanding(i)
        elif isinstance(s, DimList):
            can_call_original_getitem = False
            if not s.is_bound:
                check_expanding(i)
                unbound_dim_list = s
            else:
                dims_indexed += len(s._dims)
            dimlists.append(i)
        elif s is None:
            has_dimpacks_or_none = True
        elif <MASK>:
            can_call_original_getitem = False
            has_dimpacks_or_none = True
            dims_indexed += 1
        else:
            dims_indexed += 1
    if can_call_original_getitem:
        return IndexingInfo(can_call_original=True)
    self_info = TensorInfo.create(self, False, True)
    total_dims = len(self_info.levels)
    if dims_indexed > total_dims:
        raise ValueError(f'at least {dims_indexed} indices were supplied but the tensor only has {total_dims} dimensions')
    expanding_dims = total_dims - dims_indexed
    if expanding_object != -1:
        if unbound_dim_list is not None:
            unbound_dim_list.bind_len(expanding_dims)
        else:
            no_slices = [slice(None)] * expanding_dims
            input_list = input_list[:expanding_object] + no_slices + input_list[expanding_object + 1:]
    for i in range(len(dimlists) - 1, -1, -1):
        idx = dimlists[i]
        if unbound_dim_list is None and expanding_object != -1 and (idx > expanding_object):
            idx += expanding_dims
        dl = input_list[idx]
        input_list = input_list[:idx] + dl._dims + input_list[idx + 1:]
    return getsetitem_flat(self_info, input_list, [], [], has_dimpacks_or_none)

@functools.lru_cache
def _parse_log_settings(settings):
    settings = process_env_var_string_for_windows(settings)
    if <MASK>:
        return {}
    if settings == 'help':
        raise ValueError(help_message(verbose=False))
    elif settings == '+help':
        raise ValueError(help_message(verbose=True))
    if not _validate_settings(settings):
        raise ValueError(_invalid_settings_err_msg(settings))
    settings = re.sub('\\s+', '', settings)
    log_names = settings.split(',')

    def get_name_level_pair(name):
        clean_name = name.replace(INCR_VERBOSITY_CHAR, '')
        clean_name = clean_name.replace(DECR_VERBOSITY_CHAR, '')
        if name[0] == INCR_VERBOSITY_CHAR:
            level = logging.DEBUG
        elif name[0] == DECR_VERBOSITY_CHAR:
            level = logging.ERROR
        else:
            level = logging.INFO
        return (clean_name, level)
    log_state = LogState()
    for name in log_names:
        (name, level) = get_name_level_pair(name)
        if name == 'all':
            name = 'torch'
        if log_registry.is_log(name):
            assert level is not None
            log_qnames = log_registry.log_alias_to_log_qnames[name]
            log_state.enable_log(log_qnames, level)
        elif log_registry.is_artifact(name):
            log_state.enable_artifact(name)
        elif _is_valid_module(name):
            if not _has_registered_parent(name):
                log_registry.register_log(name, name)
            else:
                log_registry.register_child_log(name)
            log_state.enable_log(name, level)
        else:
            raise ValueError(_invalid_settings_err_msg(settings))
    return log_state

def _can_insert_copy_of_subgraph_a(subgraph_a: NSSubgraph, gm_a: GraphModule, num_non_param_args_node_a: int) -> bool:
    """
    This function returns `False` if the input subgraph cannot be copied by
    `_insert_copy_of_subgraph_a_after_input_node_c`. This usually means
    that there is a corner case logic for which copy is not yet implemented.
    """
    nodes = []
    cur_node = subgraph_a.end_node
    while cur_node != subgraph_a.start_node:
        nodes.append(cur_node)
        cur_node = get_normalized_nth_input(cur_node, gm_a, 0)
    nodes.append(cur_node)
    nodes.reverse()

    def _can_insert(node_a_arg, gm_a):
        if isinstance(node_a_arg, Node):
            arg_a = return_first_non_observer_node(node_a_arg, gm_a)
            if arg_a.op == 'call_method':
                return arg_a.target in ('dequantize', 'to')
            elif arg_a.op == 'get_attr':
                return True
            else:
                return False
        elif isinstance(node_a_arg, (list, tuple)):
            for el in node_a_arg:
                if not isinstance(el, Node):
                    return False
        return True
    for node_a in nodes:
        local_num_non_param_args_node_a = num_non_param_args_node_a if node_a is nodes[0] else 1
        norm_args_kwargs = node_a.normalized_arguments(gm_a, normalize_to_only_use_kwargs=True)
        if norm_args_kwargs is not None:
            (norm_args, norm_kwargs) = norm_args_kwargs
        else:
            (norm_args, norm_kwargs) = (node_a.args, node_a.kwargs)
        cur_idx = 0
        while cur_idx < len(norm_args):
            if <MASK>:
                pass
            elif cur_idx == 1 and local_num_non_param_args_node_a == 2:
                pass
            elif not _can_insert(norm_args[cur_idx], gm_a):
                return False
            cur_idx += 1
        for kwarg_val in norm_kwargs.values():
            if cur_idx == 0:
                pass
            elif cur_idx == 1 and local_num_non_param_args_node_a == 2:
                pass
            elif not _can_insert(kwarg_val, gm_a):
                return False
            cur_idx += 1
    return True

def logical_product(layoutA: Layout, layoutB: LayoutInput) -> Layout:
    if layoutB is None:
        return layoutA
    elif <MASK>:
        return logical_divide(layoutA, Layout(layoutB))
    elif is_tuple(layoutB):
        assert len(layoutA) >= len(layoutB)
        return make_layout(chain((logical_product(layoutA[i], layoutB[i]) for i in range(len(layoutB))), (layoutA[i] for i in range(len(layoutB), len(layoutA)))))
    return make_layout(layoutA, composition(complement(layoutA, size(layoutA) * cosize(layoutB)), layoutB))

def sample_inputs_dropout(op_info, device, dtype, requires_grad, *, train=None, valid_input_dim=None, **kwargs):
    make_arg = partial(make_tensor, device=device, dtype=dtype, requires_grad=requires_grad)
    if <MASK>:
        cases = ((S,) * i for i in valid_input_dim)
    else:
        cases = ((S, S), (S,), ())
    p_vals = [0.0, 0.5, 1.0]
    training_vals = [train] if train is not None else [True, False]
    for (case, p, training) in product(cases, p_vals, training_vals):
        yield SampleInput(make_arg(case), p=p, training=training)
    yield SampleInput(make_arg(case))

def load_label(self, fixture_label):
    """Load fixtures files for a given label."""
    show_progress = self.verbosity >= 3
    for (fixture_file, fixture_dir, fixture_name) in self.find_fixtures(fixture_label):
        (_, ser_fmt, cmp_fmt) = self.parse_name(os.path.basename(fixture_file))
        (open_method, mode) = self.compression_formats[cmp_fmt]
        fixture = open_method(fixture_file, mode)
        self.fixture_count += 1
        objects_in_fixture = 0
        loaded_objects_in_fixture = 0
        if self.verbosity >= 2:
            self.stdout.write("Installing %s fixture '%s' from %s." % (ser_fmt, fixture_name, humanize(fixture_dir)))
        try:
            objects = serializers.deserialize(ser_fmt, fixture, using=self.using, ignorenonexistent=self.ignore, handle_forward_references=True)
            for obj in objects:
                objects_in_fixture += 1
                if self.save_obj(obj):
                    loaded_objects_in_fixture += 1
                    if show_progress:
                        self.stdout.write('\rProcessed %i object(s).' % loaded_objects_in_fixture, ending='')
        except Exception as e:
            if not isinstance(e, CommandError):
                e.args = ("Problem installing fixture '%s': %s" % (fixture_file, e),)
            raise
        finally:
            fixture.close()
        if <MASK>:
            self.stdout.write()
        self.loaded_object_count += loaded_objects_in_fixture
        self.fixture_object_count += objects_in_fixture
        if objects_in_fixture == 0:
            warnings.warn("No fixture data found for '%s'. (File format may be invalid.)" % fixture_name, RuntimeWarning)

@final
@doc(_shared_docs['replace'], klass=_shared_doc_kwargs['klass'], inplace=_shared_doc_kwargs['inplace'])
def replace(self, to_replace=None, value=lib.no_default, *, inplace: bool=False, regex: bool=False) -> Self | None:
    if not is_bool(regex) and to_replace is not None:
        raise ValueError("'to_replace' must be 'None' if 'regex' is not a bool")
    if not (is_scalar(to_replace) or is_re_compilable(to_replace) or is_list_like(to_replace)):
        raise TypeError(f"Expecting 'to_replace' to be either a scalar, array-like, dict or None, got invalid type {type(to_replace).__name__!r}")
    if value is lib.no_default and (not (is_dict_like(to_replace) or is_dict_like(regex))):
        raise ValueError(f"{type(self).__name__}.replace must specify either 'value', a dict-like 'to_replace', or dict-like 'regex'.")
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if inplace:
        if not PYPY and (not WARNING_CHECK_DISABLED):
            if sys.getrefcount(self) <= REF_COUNT:
                warnings.warn(_chained_assignment_method_msg, ChainedAssignmentError, stacklevel=2)
    if value is lib.no_default:
        if not is_dict_like(to_replace):
            to_replace = regex
            regex = True
        items = list(to_replace.items())
        if <MASK>:
            (keys, values) = zip(*items, strict=True)
        else:
            (keys, values) = ([], [])
        are_mappings = [is_dict_like(v) for v in values]
        if any(are_mappings):
            if not all(are_mappings):
                raise TypeError('If a nested mapping is passed, all values of the top level mapping must be mappings')
            to_rep_dict = {}
            value_dict = {}
            for (k, v) in items:
                (keys, values) = list(zip(*v.items(), strict=True)) or ([], [])
                to_rep_dict[k] = list(keys)
                value_dict[k] = list(values)
            (to_replace, value) = (to_rep_dict, value_dict)
        else:
            (to_replace, value) = (keys, values)
        return self.replace(to_replace, value, inplace=inplace, regex=regex)
    else:
        if not self.size:
            if inplace:
                return None
            return self.copy(deep=False)
        if is_dict_like(to_replace):
            if is_dict_like(value):
                if isinstance(self, ABCSeries):
                    raise ValueError('to_replace and value cannot be dict-like for Series.replace')
                mapping = {col: (to_replace[col], value[col]) for col in to_replace.keys() if col in value.keys() and col in self}
                return self._replace_columnwise(mapping, inplace, regex)
            elif not is_list_like(value):
                if self.ndim == 1:
                    raise ValueError("Series.replace cannot specify both a dict-like 'to_replace' and a 'value'")
                mapping = {col: (to_rep, value) for (col, to_rep) in to_replace.items()}
                return self._replace_columnwise(mapping, inplace, regex)
            else:
                raise TypeError('value argument must be scalar, dict, or Series')
        elif is_list_like(to_replace):
            if not is_list_like(value):
                value = [value] * len(to_replace)
            if len(to_replace) != len(value):
                raise ValueError(f'Replacement lists must match in length. Expecting {len(to_replace)} got {len(value)} ')
            new_data = self._mgr.replace_list(src_list=to_replace, dest_list=value, inplace=inplace, regex=regex)
        elif to_replace is None:
            if not (is_re_compilable(regex) or is_list_like(regex) or is_dict_like(regex)):
                raise TypeError(f"'regex' must be a string or a compiled regular expression or a list or dict of strings or regular expressions, you passed a {type(regex).__name__!r}")
            return self.replace(regex, value, inplace=inplace, regex=True)
        elif is_dict_like(value):
            if self.ndim == 1:
                raise ValueError('Series.replace cannot use dict-value and non-None to_replace')
            mapping = {col: (to_replace, val) for (col, val) in value.items()}
            return self._replace_columnwise(mapping, inplace, regex)
        elif not is_list_like(value):
            regex = should_use_regex(regex, to_replace)
            if regex:
                new_data = self._mgr.replace_regex(to_replace=to_replace, value=value, inplace=inplace)
            else:
                new_data = self._mgr.replace(to_replace=to_replace, value=value, inplace=inplace)
        else:
            raise TypeError(f'Invalid "to_replace" type: {type(to_replace).__name__!r}')
    result = self._constructor_from_mgr(new_data, axes=new_data.axes)
    if inplace:
        return self._update_inplace(result)
    else:
        return result.__finalize__(self, method='replace')

def call(self, gm: torch.fx.GraphModule) -> Optional[PassResult]:

    def get_arg_spec(arg) -> Union[TensorArgument, ConstantArgument]:
        if isinstance(arg, torch.fx.Node):
            if isinstance(arg.meta.get('val'), torch.Tensor):
                return TensorArgument(name=arg.name)
            else:
                raise AssertionError('Symint input is not implemented yet for submodule call signature.')
        else:
            return ConstantArgument(name='', value=arg)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        nn_module_stack = None
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_outputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif <MASK>:
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None
        nn_module_stack = None
        for node in reversed(module.graph.nodes):
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                kind = node.kwargs['kind']
                if kind == 'module_call_inputs':
                    nn_module_stack = node.meta['nn_module_stack']
                elif kind == 'module_call_outputs':
                    nn_module_stack = None
                else:
                    raise AssertionError(f'Unknown tracepoint kind: {kind}')
            elif node.meta['nn_module_stack'] == nn_module_stack:
                node.meta['nn_module_stack'].popitem()
            else:
                nn_module_stack = None

    def copy_sig(sig) -> ModuleCallSignature:
        from torch.export.exported_program import ModuleCallSignature
        return ModuleCallSignature(inputs=[], outputs=[], in_spec=sig.in_spec, out_spec=sig.out_spec, forward_arg_names=None)
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        for node in module.graph.nodes:
            if node.op != 'call_function':
                continue
            if node.target == torch.ops.higher_order._export_tracepoint:
                path = node.kwargs['path']
                (fqn, _) = next(reversed(node.meta['nn_module_stack'].values()))
                module_key = next(reversed(node.meta['nn_module_stack']))
                if '@' in module_key:
                    suffix = module_key.split('@')[-1]
                    path = f'{path}@{suffix}'
                    call_fqn = f'{fqn}@{suffix}'
                    if call_fqn not in self.specs:
                        self.specs[call_fqn] = copy_sig(self.specs[fqn])
                    fqn = call_fqn
                kind = node.kwargs['kind']
                for (i, arg) in enumerate(node.args):
                    if fqn == path:
                        if kind == 'module_call_inputs':
                            self.specs[path].inputs.append(get_arg_spec(arg))
                        elif kind == 'module_call_outputs':
                            self.specs[path].outputs.append(get_arg_spec(arg))
                        else:
                            raise AssertionError(f'Unknown tracepoint kind: {kind}')
                    if isinstance(arg, torch.fx.Node):
                        for user in node.users:
                            assert user.op == 'call_function'
                            assert user.target == operator.getitem
                            assert isinstance(user.args[1], int)
                            if user.args[1] == i:
                                user.replace_all_uses_with(arg)
                                self.sig.replace_all_uses(user.name, arg.name)
                                break
                users = list(node.users)
                for user in users:
                    assert len(user.users) == 0
                    gm.graph.erase_node(user)
                gm.graph.erase_node(node)
        return PassResult(gm, True)
    return None

def _get_reduction_dtype(input, dtype, promote_int_to_long=True):
    if dtype:
        return dtype
    if input.dtype.is_floating_point or input.dtype.is_complex:
        return input.dtype
    elif <MASK>:
        return torch.long
    return input.dtype

def load_pickle(self, package: str, resource: str, map_location=None) -> Any:
    """Unpickles the resource from the package, loading any modules that are needed to construct the objects
        using :meth:`import_module`.

        Args:
            package (str): The name of module package (e.g. ``"my_package.my_subpackage"``).
            resource (str): The unique name for the resource.
            map_location: Passed to `torch.load` to determine how tensors are mapped to devices. Defaults to ``None``.

        Returns:
            Any: The unpickled object.
        """
    pickle_file = self._zipfile_path(package, resource)
    restore_location = _get_restore_location(map_location)
    loaded_storages = {}
    loaded_reduces = {}
    storage_context = torch._C.DeserializationStorageContext()

    def load_tensor(dtype, size, key, location, restore_location):
        name = f'{key}.storage'
        if storage_context.has_storage(name):
            storage = storage_context.get_storage(name, dtype)._typed_storage()
        else:
            tensor = self.zip_reader.get_storage_from_record('.data/' + name, size, dtype)
            if isinstance(self.zip_reader, torch._C.PyTorchFileReader):
                storage_context.add_storage(name, tensor)
            storage = tensor._typed_storage()
        loaded_storages[key] = restore_location(storage, location)

    def persistent_load(saved_id):
        assert isinstance(saved_id, tuple)
        typename = _maybe_decode_ascii(saved_id[0])
        data = saved_id[1:]
        if <MASK>:
            (storage_type, key, location, size) = data
            if storage_type is torch.UntypedStorage:
                dtype = torch.uint8
            else:
                dtype = storage_type.dtype
            if key not in loaded_storages:
                load_tensor(dtype, size, key, _maybe_decode_ascii(location), restore_location)
            storage = loaded_storages[key]
            return torch.storage.TypedStorage(wrap_storage=storage._untyped_storage, dtype=dtype, _internal=True)
        elif typename == 'reduce_package':
            if len(data) == 2:
                (func, args) = data
                return func(self, *args)
            (reduce_id, func, args) = data
            if reduce_id not in loaded_reduces:
                loaded_reduces[reduce_id] = func(self, *args)
            return loaded_reduces[reduce_id]
        else:
            f"Unknown typename for persistent_load, expected 'storage' or 'reduce_package' but got '{typename}'"
    data_file = io.BytesIO(self.zip_reader.get_record(pickle_file))
    unpickler = self.Unpickler(data_file)
    unpickler.persistent_load = persistent_load

    @contextmanager
    def set_deserialization_context():
        self.storage_context = storage_context
        self.last_map_location = map_location
        try:
            yield
        finally:
            self.storage_context = None
            self.last_map_location = None
    with set_deserialization_context():
        result = unpickler.load()
    torch._utils._validate_loaded_sparse_tensors()
    return result

