@ops.RegisterStatistics('BatchMatMul', 'flops')
@ops.RegisterStatistics('BatchMatMulV2', 'flops')
@ops.RegisterStatistics('BatchMatMulV3', 'flops')
def _calc_batch_mat_mul_flops(graph, node):
    """Calculates the compute resources needed for BatchMatMul."""
    transpose_a = node.attr['transpose_a'].b
    a_shape = graph_util.tensor_shape_from_node_def_name(graph, node.input[0])
    a_shape.assert_is_fully_defined()
    if <MASK>:
        k = int(a_shape[-2])
    else:
        k = int(a_shape[-1])
    output_shape = graph_util.tensor_shape_from_node_def_name(graph, node.name)
    output_shape.assert_is_fully_defined()
    output_count = np.prod(output_shape.as_list())
    return ops.OpStats('flops', k * output_count * 2)

def visit(var: VariableTracker) -> None:
    if var in visited:
        return
    visited.add(var)
    if <MASK>:
        live_new_objects.add(var)
    if var in self.store_attr_mutations:
        VariableTracker.visit(visit, self.store_attr_mutations[var])

def are_block_parameters_compatible(self, block_params: BlockParameters) -> bool:
    """
        Check if the block parameters are valid for TMA.
        If force, we allow relying on symbolic hints equivalent
        to what we check for Triton templates.
        """
    if self.force:
        strides = [V.graph.sizevars.symbolic_hint(st) for st in block_params.strides]
    else:
        strides = block_params.strides
    if not V.graph.sizevars.statically_known_equals(strides[-1], sympy.Integer(1)):
        log.debug('%s TMA API requires innermost stride to be 1.', self.failed_debug_prefix)
        return False
    element_size = self.dtype.itemsize
    for stride in strides[:-1]:
        if not V.graph.sizevars.statically_known_equals(ModularIndexing(stride * element_size, 1, sympy.Integer(16)), sympy.Integer(0)):
            log.debug('%s TMA API requires outer strides to be 16 byte aligned.', self.failed_debug_prefix)
            return False
    innermost_block_shape = block_params.block_shape[-1]
    innermost_block_type = None
    innermost_block_symt = None
    for block_type_str in innermost_block_shape.free_symbols:
        for block_symt in TritonSymbols.block_types:
            if symbol_is_type(block_type_str, block_symt):
                innermost_block_type = block_type_str
                innermost_block_symt = block_symt
                break
    assert innermost_block_type and innermost_block_symt, f'{innermost_block_shape} expr must contain a single block type from {TritonSymbols.block_types}'
    if self.kernel.persistent_reduction and (not self.for_store):
        innermost_tree_prefix = prefix_str[innermost_block_symt]
        tree_numel = None
        for t in self.kernel.range_trees:
            if t.is_reduction:
                if <MASK>:
                    tree_numel = t.numel
                    break
        assert tree_numel is not None
        persistent_rblock = self.kernel._get_persistent_RBLOCK(tree_numel)
        innermost_block_bytes = innermost_block_shape.subs({innermost_block_type: persistent_rblock}) * element_size
        if not V.graph.sizevars.statically_known_geq(innermost_block_bytes, sympy.Integer(16)):
            log.debug('%s persistent reduction innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    else:
        try:
            min_block_size = next_power_of_2(int(sympy.nsolve(innermost_block_shape * element_size - 16, innermost_block_type, 1)))
            block_type_str = V.kernel.index_to_str(innermost_block_type)
            if self.kernel.fixed_config:
                if min_block_size > self.kernel.fixed_config[block_type_str]:
                    log.debug('%s For block %s, fixed config block size %d is smaller than the minimum required: %d', self.failed_debug_prefix, block_type_str, self.kernel.fixed_config[block_type_str], min_block_size)
                    return False
            else:
                self.kernel.tma_min_block_sizes[block_type_str] = max(min_block_size, self.kernel.tma_min_block_sizes.get(block_type_str, 1))
        except ValueError:
            log.debug('%s innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    return True

def _check_transformer(name, transformer_orig, X, y):
    (n_samples, n_features) = np.asarray(X).shape
    transformer = clone(transformer_orig)
    set_random_state(transformer)
    if <MASK>:
        y_ = np.c_[np.asarray(y), np.asarray(y)]
        y_[::2, 1] *= 2
        if isinstance(X, _NotAnArray):
            y_ = _NotAnArray(y_)
    else:
        y_ = y
    transformer.fit(X, y_)
    transformer_clone = clone(transformer)
    X_pred = transformer_clone.fit_transform(X, y=y_)
    if isinstance(X_pred, tuple):
        for x_pred in X_pred:
            assert x_pred.shape[0] == n_samples
    else:
        assert X_pred.shape[0] == n_samples
    if hasattr(transformer, 'transform'):
        if name in CROSS_DECOMPOSITION:
            X_pred2 = transformer.transform(X, y_)
            X_pred3 = transformer.fit_transform(X, y=y_)
        else:
            X_pred2 = transformer.transform(X)
            X_pred3 = transformer.fit_transform(X, y=y_)
        if get_tags(transformer_orig).non_deterministic:
            msg = name + ' is non deterministic'
            raise SkipTest(msg)
        if isinstance(X_pred, tuple) and isinstance(X_pred2, tuple):
            for (x_pred, x_pred2, x_pred3) in zip(X_pred, X_pred2, X_pred3):
                assert_allclose_dense_sparse(x_pred, x_pred2, atol=0.01, err_msg='fit_transform and transform outcomes not consistent in %s' % transformer)
                assert_allclose_dense_sparse(x_pred, x_pred3, atol=0.01, err_msg='consecutive fit_transform outcomes not consistent in %s' % transformer)
        else:
            assert_allclose_dense_sparse(X_pred, X_pred2, err_msg='fit_transform and transform outcomes not consistent in %s' % transformer, atol=0.01)
            assert_allclose_dense_sparse(X_pred, X_pred3, atol=0.01, err_msg='consecutive fit_transform outcomes not consistent in %s' % transformer)
            assert _num_samples(X_pred2) == n_samples
            assert _num_samples(X_pred3) == n_samples
        if hasattr(X, 'shape') and get_tags(transformer).requires_fit and (X.ndim == 2) and (X.shape[1] > 1):
            with raises(ValueError, err_msg=f'The transformer {name} does not raise an error when the number of features in transform is different from the number of features in fit.'):
                transformer.transform(X[:, :-1])

def _infer_daily_rule(self) -> str | None:
    annual_rule = self._get_annual_rule()
    if annual_rule:
        nyears = self.ydiffs[0]
        month = MONTH_ALIASES[self.rep_stamp.month]
        alias = f'{annual_rule}-{month}'
        return _maybe_add_count(alias, nyears)
    quarterly_rule = self._get_quarterly_rule()
    if <MASK>:
        nquarters = self.mdiffs[0] / 3
        mod_dict = {0: 12, 2: 11, 1: 10}
        month = MONTH_ALIASES[mod_dict[self.rep_stamp.month % 3]]
        alias = f'{quarterly_rule}-{month}'
        return _maybe_add_count(alias, nquarters)
    monthly_rule = self._get_monthly_rule()
    if monthly_rule:
        return _maybe_add_count(monthly_rule, self.mdiffs[0])
    if self.is_unique:
        return self._get_daily_rule()
    if self._is_business_daily():
        return 'B'
    wom_rule = self._get_wom_rule()
    if wom_rule:
        return wom_rule
    return None

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    from .tensor import SymNodeVariable
    if name == '__setitem__' and self.is_mutable():
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (key, value) = args
        if not key.is_python_constant():
            super().call_method(tx, name, args, kwargs)
        tx.output.side_effects.mutation(self)
        if isinstance(key, SliceVariable):
            if not value.has_force_unpack_var_sequence(tx):
                msg = ConstantVariable.create('can only assign an iterable')
                raise_observed_exception(TypeError, tx, args=[msg])
            key = key.as_python_constant()
            if key.step == 0:
                msg = ConstantVariable.create('slice step cannot be zero')
                raise_observed_exception(ValueError, tx, args=[msg])
            value = value.force_unpack_var_sequence(tx)
            try:
                self.items[key] = value
            except Exception as exc:
                raise_observed_exception(type(exc), tx, args=list(map(ConstantVariable.create, exc.args)))
        else:
            if isinstance(key, SymNodeVariable):
                key = key.evaluate_expr()
            else:
                key = key.as_python_constant()
            try:
                self.items[key] = value
            except (IndexError, TypeError) as e:
                raise_observed_exception(type(e), tx, args=list(map(ConstantVariable.create, e.args)))
        return ConstantVariable.create(None)
    if name == 'sort' and self.is_mutable():
        if <MASK>:
            raise_args_mismatch(tx, name, '0 args', f'{len(args)} args')
        key_fn_var = kwargs.pop('key', ConstantVariable.create(None))
        reverse = kwargs.pop('reverse', ConstantVariable.create(False)).as_python_constant()
        if len(kwargs) != 0:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        if key_fn_var.is_python_constant() and key_fn_var.as_python_constant() is None:
            keys = self.items.copy()
        else:
            keys = [key_fn_var.call_function(tx, [x], {}) for x in self.items]
        if not all((k.is_python_constant() for k in keys)):
            first_non_constant_key = None
            for k in keys:
                if not k.is_python_constant():
                    first_non_constant_key = k
            assert first_non_constant_key is not None
            try:
                python_type = first_non_constant_key.python_type()
            except NotImplementedError:
                python_type = 'unknown'
            unimplemented_v2(gb_type='sort with non-constant keys', context=str(first_non_constant_key), explanation=f'Cannot perform sort with non-constant key. First non-constant key type: {python_type}. Most notably, we cannot sort with Tensor or SymInt keys, but we can sort ints.', hints=['Use something else as the key.'])
        tx.output.side_effects.mutation(self)
        sorted_items_with_keys = sorted(((x, k.as_python_constant(), -i if reverse else i) for (i, (k, x)) in enumerate(zip(keys, self.items))), key=operator.itemgetter(1, 2), reverse=reverse)
        self.items[:] = [x for (x, *_) in sorted_items_with_keys]
        return ConstantVariable.create(None)
    if name == '__init__' and self.is_mutable():
        if kwargs:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        if len(args) == 0:
            return ConstantVariable.create(None)
        elif len(args) == 1 and args[0].has_force_unpack_var_sequence(tx):
            (arg,) = args
            tx.output.side_effects.mutation(self)
            self.items[:] = arg.force_unpack_var_sequence(tx)
            return ConstantVariable.create(None)
    return super().call_method(tx, name, args, kwargs)

def sym_max(a, b):
    """
    SymInt-aware utility for max which avoids branching on a < b.
    Unlike builtins.max(), this only works for int/float, and it always
    promotes to float if any argument is float (unlike builtins.max, which
    will faithfully preserve the type of the input argument).
    """
    if overrides.has_torch_function((a, b)):
        return overrides.handle_torch_function(sym_max, (a, b), a, b)
    if <MASK>:
        return a.__sym_max__(b)
    elif isinstance(b, (SymInt, SymFloat)):
        return b.__sym_max__(a)
    (all_types, float_types) = __all_and_float_types()
    assert isinstance(a, all_types), type(a)
    assert isinstance(b, all_types), type(b)
    if isinstance(a, float_types) or isinstance(b, float_types):
        return builtins.float(builtins.max(a, b))
    else:
        return builtins.max(a, b)

def typecast_time(s):
    if not s:
        return None
    (hour, minutes, seconds) = s.split(':')
    if <MASK>:
        (seconds, microseconds) = seconds.split('.')
    else:
        microseconds = '0'
    return datetime.time(int(hour), int(minutes), int(seconds), int((microseconds + '000000')[:6]))

def apply_sharding(datapipe: DataPipe, num_of_instances: int, instance_id: int, sharding_group=SHARDING_PRIORITIES.DEFAULT) -> DataPipe:
    """
    Apply dynamic sharding over the ``sharding_filter`` DataPipe that has a method ``apply_sharding``.

    RuntimeError will be raised when multiple ``sharding_filter`` are presented in the same branch.
    """
    graph = traverse_dps(datapipe)

    def _helper(graph, prev_applied=None):
        for (dp, sub_graph) in graph.values():
            applied = None
            if _is_sharding_datapipe(dp):
                if prev_applied is not None:
                    raise RuntimeError(f'Sharding twice on a single pipeline is likely unintended and will cause data loss. Sharding already applied to {prev_applied} while trying to apply to {dp}')
                sig = inspect.signature(dp.apply_sharding)
                if len(sig.parameters) < 3:
                    dp.apply_sharding(num_of_instances, instance_id)
                else:
                    dp.apply_sharding(num_of_instances, instance_id, sharding_group=sharding_group)
                applied = dp
            if <MASK>:
                applied = prev_applied
            _helper(sub_graph, applied)
    _helper(graph)
    return datapipe

def __setstate__(self, state):
    pickled_version = state.get(DJANGO_VERSION_PICKLE_KEY)
    if pickled_version:
        if <MASK>:
            warnings.warn("Pickled model instance's Django version %s does not match the current version %s." % (pickled_version, django.__version__), RuntimeWarning, stacklevel=2)
    else:
        warnings.warn("Pickled model instance's Django version is not specified.", RuntimeWarning, stacklevel=2)
    if '_memoryview_attrs' in state:
        for (attr, value) in state.pop('_memoryview_attrs'):
            state[attr] = memoryview(value)
    self.__dict__.update(state)

def __init__(self, expression, query, *, config=None, start_sel=None, stop_sel=None, max_words=None, min_words=None, short_word=None, highlight_all=None, max_fragments=None, fragment_delimiter=None):
