    self.options = {option: value for (option, value) in options.items() if value is not None}
    expressions = (expression, query)
    if <MASK>:
        config = SearchConfig.from_parameter(config)
        expressions = (config, *expressions)
    super().__init__(*expressions)

def emit(self, record) -> None:
    if self.stream is None:
        if self.root_dir is None:
            TRACE_LOG_DIR = '/logs'
            import torch.version as torch_version
            if hasattr(torch_version, 'git_version') and os.getenv('MAST_HPC_JOB_NAME') is None:
                log.info('LazyTraceHandler: disabled because not fbcode or conda on mast')
            elif <MASK>:
                log.info("LazyTraceHandler: disabled because justknobs_check('pytorch/trace:enable') returned False")
            elif not os.path.exists(TRACE_LOG_DIR):
                log.info('LazyTraceHandler: disabled because %s does not exist', TRACE_LOG_DIR)
            elif not os.access(TRACE_LOG_DIR, os.W_OK):
                log.info('LazyTraceHandler: disabled because %s is not writeable', TRACE_LOG_DIR)
            else:
                self.root_dir = TRACE_LOG_DIR
        if self.root_dir is not None:
            os.makedirs(self.root_dir, exist_ok=True)
            ranksuffix = ''
            if dist.is_available() and dist.is_initialized():
                ranksuffix = f'rank_{dist.get_rank()}_'
            self.stream = tempfile.NamedTemporaryFile(mode='w+', suffix='.log', prefix=f'dedicated_log_torch_trace_{ranksuffix}', dir=self.root_dir, delete=False)
            log.info('LazyTraceHandler: logging to %s', self.stream.name)
        else:
            trace_log.removeHandler(self)
            return
    if self.stream:
        super().emit(record)

def embedding_lookup_sparse_impl(params, segment_ids, sp_weights, ids, combiner, ignore_weights, max_norm, allow_fast_lookup, partition_strategy, name):
    """Implementation of sparse embedding aggregation."""
    need_sparse_segment_gradient = False
    segment_ids = ops.convert_to_tensor(segment_ids, name='segment_ids')
    if len(params) == 1 and (not isinstance(params[0], (core.Tensor, composite_tensor.CompositeTensor))):
        params = [ops.convert_to_tensor(params[0], name='params')]
    if len(params) == 1 and (not isinstance(params[0], composite_tensor.CompositeTensor)) and (params[0].device == segment_ids.device) and (max_norm is None) and (allow_fast_lookup or (ignore_weights and compat.forward_compatible(2023, 9, 26))):
        idx = ids
        embeddings = params[0]
        if isinstance(embeddings, resource_variable_ops.BaseResourceVariable):
            embeddings = embeddings.read_value_no_copy()
        if not allow_fast_lookup:
            need_sparse_segment_gradient = True
    else:
        (ids, idx) = array_ops.unique(ids)
        embeddings = embedding_lookup(params, ids, partition_strategy=partition_strategy, max_norm=max_norm)
    if not ignore_weights:
        if segment_ids.dtype != dtypes.int32:
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        weights = sp_weights.values
        embeddings = array_ops.gather(embeddings, idx)
        original_dtype = embeddings.dtype
        if embeddings.dtype in (dtypes.float16, dtypes.bfloat16):
            embeddings = math_ops.cast(embeddings, dtypes.float32)
        if weights.dtype != embeddings.dtype:
            weights = math_ops.cast(weights, embeddings.dtype)
        ones_shape = array_ops.expand_dims(array_ops.rank(embeddings) - 1, 0)
        weights_shape = array_ops.shape(weights)
        ones = array_ops.ones(ones_shape, dtype=weights_shape.dtype)
        bcast_weights_shape = array_ops.concat([weights_shape, ones], 0)
        orig_weights_shape = weights.get_shape()
        weights = array_ops.reshape(weights, bcast_weights_shape)
        if <MASK>:
            weights.set_shape(orig_weights_shape.concatenate([1 for _ in range(embeddings.get_shape().ndims - 1)]))
        embeddings *= weights
        if combiner == 'sum':
            embeddings = math_ops.segment_sum(embeddings, segment_ids, name=name)
        elif combiner == 'mean':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weight_sum = math_ops.segment_sum(weights, segment_ids)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum, name=name)
        elif combiner == 'sqrtn':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weights_squared = math_ops.pow(weights, 2)
            weight_sum = math_ops.segment_sum(weights_squared, segment_ids)
            weight_sum_sqrt = math_ops.sqrt(weight_sum)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum_sqrt, name=name)
        else:
            assert False, 'Unrecognized combiner'
        if embeddings.dtype != original_dtype:
            embeddings = math_ops.cast(embeddings, original_dtype)
    else:
        if segment_ids.dtype not in (dtypes.int32, dtypes.int64):
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        assert idx is not None
        if combiner == 'sum':
            embeddings = math_ops.sparse_segment_sum(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'mean':
            embeddings = math_ops.sparse_segment_mean(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'sqrtn':
            embeddings = math_ops.sparse_segment_sqrt_n(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        else:
            assert False, 'Unrecognized combiner'
    return embeddings

def __init__(self, storage: str | None=None, na_value: libmissing.NAType | float=libmissing.NA) -> None:
    if storage is None:
        storage = get_option('mode.string_storage')
        if storage == 'auto':
            if HAS_PYARROW:
                storage = 'pyarrow'
            else:
                storage = 'python'
    if <MASK>:
        raise ValueError(f"Storage must be 'python' or 'pyarrow'. Got {storage} instead.")
    if storage == 'pyarrow' and (not HAS_PYARROW):
        raise ImportError(f'pyarrow>={PYARROW_MIN_VERSION} is required for PyArrow backed StringArray.')
    if isinstance(na_value, float) and np.isnan(na_value):
        na_value = np.nan
    elif na_value is not libmissing.NA:
        raise ValueError(f"'na_value' must be np.nan or pd.NA, got {na_value}")
    self.storage = cast(str, storage)
    self._na_value = na_value

def test_cuda(self, test_case, dtype, extra_args=None):

    def convert_dtype(obj, dtype, requires_grad=False):
        if isinstance(obj, torch.Tensor):
            return obj.detach().to(dtype=dtype).requires_grad_(requires_grad)
        elif isinstance(obj, tuple):
            return tuple((convert_dtype(o, dtype, requires_grad) for o in obj))
        else:
            return obj
    if <MASK>:
        raise unittest.SkipTest('Excluded from CUDA tests')
    with set_default_dtype(self.default_dtype):
        cpu_input = self._get_input()
        cpu_target = self._get_target()
        cpu_module = self.constructor(*self.constructor_args)
        gpu_module = self.constructor(*self.constructor_args)
        cpu_input = convert_dtype(cpu_input, dtype, True)
        if cpu_target.is_floating_point() or cpu_target.is_complex():
            cpu_target = convert_dtype(cpu_target, dtype)
        cpu_module.type(dtype)
        gpu_module.type(dtype)
        gpu_input = to_gpu(cpu_input)
        gpu_target = to_gpu(cpu_target)
        gpu_module.cuda()
        if dtype in {torch.half, torch.bfloat16}:
            cpu_input = self._get_input()
            cpu_target = self._get_target()
            cpu_module = self.constructor(*self.constructor_args)
        cpu_output = test_case._forward_criterion(cpu_module, cpu_input, cpu_target, extra_args=extra_args)
        gpu_output = test_case._forward_criterion(gpu_module, gpu_input, gpu_target, extra_args=extra_args)
        test_case.assertEqual(cpu_output, gpu_output, atol=0.1 if dtype in {torch.half, torch.bfloat16} else 0.0004, rtol=0, exact_dtype=False)
        cpu_gradInput = test_case._backward_criterion(cpu_module, cpu_input, cpu_output, cpu_target, extra_args=extra_args)
        gpu_gradInput = test_case._backward_criterion(gpu_module, gpu_input, gpu_output, gpu_target, extra_args=extra_args)
        test_case.assertEqual(cpu_gradInput, gpu_gradInput, atol=0.1 if dtype in {torch.half, torch.bfloat16} else 0.0004, rtol=0, exact_dtype=False)

def __call__(self, func, *args, **kwargs):
    """
        Decorator call.  Refer to ``decorate``.

        """
    old_name = self.old_name
    new_name = self.new_name
    message = self.message
    if old_name is None:
        old_name = func.__name__
    if new_name is None:
        depdoc = f'`{old_name}` is deprecated!'
    else:
        depdoc = f'`{old_name}` is deprecated, use `{new_name}` instead!'
    if message is not None:
        depdoc += '\n' + message

    @functools.wraps(func)
    def newfunc(*args, **kwds):
        warnings.warn(depdoc, DeprecationWarning, stacklevel=2)
        return func(*args, **kwds)
    newfunc.__name__ = old_name
    doc = func.__doc__
    if doc is None:
        doc = depdoc
    else:
        lines = doc.expandtabs().split('\n')
        indent = _get_indent(lines[1:])
        if <MASK>:
            doc = indent * ' ' + doc
        else:
            skip = len(lines[0]) + 1
            for line in lines[1:]:
                if len(line) > indent:
                    break
                skip += len(line) + 1
            doc = doc[skip:]
        depdoc = textwrap.indent(depdoc, ' ' * indent)
        doc = f'{depdoc}\n\n{doc}'
    newfunc.__doc__ = doc
    return newfunc

def max_(x, y):
    if <MASK>:
        return math_ops.maximum(x, y)
    else:
        return max(x, y)

@torch._disable_dynamo
def zero_grad(self, set_to_none: bool=True) -> None:
    """Reset the gradients of all optimized :class:`torch.Tensor` s.

        Args:
            set_to_none (bool, optional): Instead of setting to zero, set the grads to None. Default: ``True``

                This will in general have lower memory footprint, and can modestly improve performance.
                However, it changes certain behaviors. For example:

                1. When the user tries to access a gradient and perform manual ops on it,
                   a None attribute or a Tensor full of 0s will behave differently.
                2. If the user requests ``zero_grad(set_to_none=True)`` followed by a backward pass, ``.grad``\\ s
                   are guaranteed to be None for params that did not receive a gradient.
                3. ``torch.optim`` optimizers have a different behavior if the gradient is 0 or None
                   (in one case it does the step with a gradient of 0 and in the other it skips
                   the step altogether).
        """
    foreach = self.defaults.get('foreach', False) or self.defaults.get('fused', False)
    if not hasattr(self, '_zero_grad_profile_name'):
        self._patch_step_function()
    per_device_and_dtype_grads: Optional[defaultdict[torch.device, defaultdict[torch.dtype, list[torch.Tensor]]]]
    if <MASK>:
        per_device_and_dtype_grads = defaultdict(lambda : defaultdict(list))
    else:
        per_device_and_dtype_grads = None
    with torch.autograd.profiler.record_function(self._zero_grad_profile_name):
        for group in self.param_groups:
            for p in group['params']:
                if p.grad is not None:
                    if set_to_none:
                        p.grad = None
                    else:
                        if p.grad.grad_fn is not None:
                            p.grad.detach_()
                        else:
                            p.grad.requires_grad_(False)
                        if not foreach or p.grad.is_sparse:
                            p.grad.zero_()
                        else:
                            if per_device_and_dtype_grads is None:
                                raise AssertionError('Expected per_device_and_dtype_grads to be set')
                            per_device_and_dtype_grads[p.grad.device][p.grad.dtype].append(p.grad)
        if foreach:
            if per_device_and_dtype_grads is None:
                raise AssertionError('Expected per_device_and_dtype_grads to be set')
            for per_dtype_grads in per_device_and_dtype_grads.values():
                for grads in per_dtype_grads.values():
                    torch._foreach_zero_(grads)

def is_placeholder(x):
    """Returns whether `x` is a placeholder.

  Args:
      x: A candidate placeholder.

  Returns:
      Boolean.
  """
    try:
        if ops.executing_eagerly_outside_functions():
            return hasattr(x, '_is_backend_placeholder')
        from tensorflow.python.keras.utils import tf_utils
        if <MASK>:
            flat_components = nest.flatten(x, expand_composites=True)
            return py_any((is_placeholder(c) for c in flat_components))
        else:
            return x.op.type == 'Placeholder'
    except AttributeError:
        return False

def _ctype_from_dtype_structured(dtype):
    field_data = []
    for name in dtype.names:
        (field_dtype, offset) = dtype.fields[name][:2]
        field_data.append((offset, name, _ctype_from_dtype(field_dtype)))
    field_data = sorted(field_data, key=lambda f: f[0])
    if <MASK>:
        size = 0
        _fields_ = []
        for (offset, name, ctype) in field_data:
            _fields_.append((name, ctype))
            size = max(size, ctypes.sizeof(ctype))
        if dtype.itemsize != size:
            _fields_.append(('', ctypes.c_char * dtype.itemsize))
        return type('union', (ctypes.Union,), {'_fields_': _fields_, '_pack_': 1, '__module__': None})
    else:
        last_offset = 0
        _fields_ = []
        for (offset, name, ctype) in field_data:
            padding = offset - last_offset
            if padding < 0:
                raise NotImplementedError('Overlapping fields')
            if padding > 0:
                _fields_.append(('', ctypes.c_char * padding))
            _fields_.append((name, ctype))
            last_offset = offset + ctypes.sizeof(ctype)
        padding = dtype.itemsize - last_offset
        if padding > 0:
            _fields_.append(('', ctypes.c_char * padding))
        return type('struct', (ctypes.Structure,), {'_fields_': _fields_, '_pack_': 1, '__module__': None})

def _cached_dispatch_impl(self, func: OpOverload, types: Sequence[type], args: Sequence[object], kwargs: Mapping[str, object]) -> object:
    """
        Lookup a cache entry for the given arguments. If none exists, dispatch
        and cache the result (if the result is eligible for caching).
        """
    state = None
    key = None
    try:
        state = _CacheKeyState(self.shape_env)
        key = self._cache_key(state, func, args, kwargs)
    except _BypassDispatchCache as e:
        if <MASK>:
            hc_log.debug('Fake tensor cache failed: identifier = %s, reason = %s', args[1], e.reason)
        FakeTensorMode.cache_bypasses[e.reason] += 1
    if key is None:
        return self._dispatch_impl(func, types, args, kwargs)
    assert state is not None
    if state.cache_on_shape_env():
        assert state.shape_env is not None
        cache = state.shape_env.fake_tensor_cache
        set_cache_key = _set_cache_key_for_shape_env
    else:
        cache = FakeTensorMode.cache
        set_cache_key = _set_cache_key
    entry = cache.get(key, None)
    if entry is not None:
        if isinstance(entry, _DispatchCacheBypassEntry):
            FakeTensorMode.cache_bypasses[entry.reason] += 1
            return self._dispatch_impl(func, types, args, kwargs)
        output = self._output_from_cache_entry(state, entry, key, func, args)
        FakeTensorMode.cache_hits += 1
        if self.cache_crosscheck_enabled:
            with disable_fake_tensor_cache(self):
                self._crosscheck_cache_output(output, func, types, args, kwargs)
        return output
    output = self._dispatch_impl(func, types, args, kwargs)
    try:
        entry = self._make_cache_entry(state, key, func, args, kwargs, output)
    except _BypassDispatchCache as e:
        if isinstance(func, torch._ops.HigherOrderOperator) and func.name() == 'invoke_subgraph':
            hc_log.debug('Fake tensor cache failed: identifier = %s, reason = %s', args[1], e.reason)
        FakeTensorMode.cache_bypasses[e.reason] += 1
        set_cache_key(cache, key, _DispatchCacheBypassEntry(e.reason))
        return output
    set_cache_key(cache, key, entry)
    FakeTensorMode.cache_misses += 1
    return output

def _pandas_arff_parser(gzip_file, output_arrays_type, openml_columns_info, feature_names_to_select, target_names_to_select, read_csv_kwargs=None):
    """ARFF parser using `pandas.read_csv`.

    This parser uses the metadata fetched directly from OpenML and skips the metadata
    headers of ARFF file itself. The data is loaded as a CSV file.

    Parameters
    ----------
    gzip_file : GzipFile instance
        The GZip compressed file with the ARFF formatted payload.

    output_arrays_type : {"numpy", "sparse", "pandas"}
        The type of the arrays that will be returned. The possibilities are:

        - `"numpy"`: both `X` and `y` will be NumPy arrays;
        - `"sparse"`: `X` will be sparse matrix and `y` will be a NumPy array;
        - `"pandas"`: `X` will be a pandas DataFrame and `y` will be either a
          pandas Series or DataFrame.

    openml_columns_info : dict
        The information provided by OpenML regarding the columns of the ARFF
        file.

    feature_names_to_select : list of str
        A list of the feature names to be selected to build `X`.

    target_names_to_select : list of str
        A list of the target names to be selected to build `y`.

    read_csv_kwargs : dict, default=None
        Keyword arguments to pass to `pandas.read_csv`. It allows to overwrite
        the default options.

    Returns
    -------
    X : {ndarray, sparse matrix, dataframe}
        The data matrix.

    y : {ndarray, dataframe, series}
        The target.

    frame : dataframe or None
        A dataframe containing both `X` and `y`. `None` if
        `output_array_type != "pandas"`.

    categories : list of str or None
        The names of the features that are categorical. `None` if
        `output_array_type == "pandas"`.
    """
    import pandas as pd
    for line in gzip_file:
        if line.decode('utf-8').lower().startswith('@data'):
            break
    dtypes = {}
    for name in openml_columns_info:
        column_dtype = openml_columns_info[name]['data_type']
        if column_dtype.lower() == 'integer':
            dtypes[name] = 'Int64'
        elif column_dtype.lower() == 'nominal':
            dtypes[name] = 'category'
    dtypes_positional = {col_idx: dtypes[name] for (col_idx, name) in enumerate(openml_columns_info) if name in dtypes}
    default_read_csv_kwargs = {'header': None, 'index_col': False, 'na_values': ['?'], 'keep_default_na': False, 'comment': '%', 'quotechar': '"', 'skipinitialspace': True, 'escapechar': '\\', 'dtype': dtypes_positional}
    read_csv_kwargs = {**default_read_csv_kwargs, **(read_csv_kwargs or {})}
    frame = pd.read_csv(gzip_file, **read_csv_kwargs)
    try:
        frame.columns = [name for name in openml_columns_info]
    except ValueError as exc:
        raise pd.errors.ParserError('The number of columns provided by OpenML does not match the number of columns inferred by pandas when reading the file.') from exc
    columns_to_select = feature_names_to_select + target_names_to_select
    columns_to_keep = [col for col in frame.columns if col in columns_to_select]
    frame = frame[columns_to_keep]
    single_quote_pattern = re.compile("^'(?P<contents>.*)'$")

    def strip_single_quotes(input_string):
        match = re.search(single_quote_pattern, input_string)
        if <MASK>:
            return input_string
        return match.group('contents')
    categorical_columns = [name for (name, dtype) in frame.dtypes.items() if isinstance(dtype, pd.CategoricalDtype)]
    for col in categorical_columns:
        frame[col] = frame[col].cat.rename_categories(strip_single_quotes)
    (X, y) = _post_process_frame(frame, feature_names_to_select, target_names_to_select)
    if output_arrays_type == 'pandas':
        return (X, y, frame, None)
    else:
        (X, y) = (X.to_numpy(), y.to_numpy())
    categories = {name: dtype.categories.tolist() for (name, dtype) in frame.dtypes.items() if isinstance(dtype, pd.CategoricalDtype)}
    return (X, y, None, categories)

@register_meta([aten.index.Tensor, aten._unsafe_index.Tensor])
def meta_index_Tensor(self, indices):
    torch._check(bool(indices), lambda : 'at least one index must be provided')
    result: list[Optional[Tensor]] = []
    for (i, index) in enumerate(indices):
        if index is not None:
            torch._check(index.dtype in [torch.long, torch.int, torch.int8, torch.bool], lambda : 'tensors used as indices must be long, int, byte or bool tensors')
            if index.dtype in [torch.int8, torch.bool]:
                nonzero = index.nonzero()
                k = len(result)
                torch._check_index(k + index.ndim <= self.ndim, lambda : f'too many indices for tensor of dimension {self.ndim}')
                for j in range(index.ndim):
                    torch._check_index(index.shape[j] == self.shape[k + j], lambda : f'The shape of the mask {index.shape} at index {i} does not match the shape of the indexed tensor {self.shape} at index {k + j}')
                    result.append(nonzero.select(1, j))
            else:
                result.append(index)
        else:
            result.append(index)
    indices = result
    torch._check(len(indices) <= self.ndim, lambda : f'too many indices for tensor of dimension {self.ndim} (got {len(indices)})')
    import torch._refs as refs
    indices = list(refs._maybe_broadcast(*indices))
    while len(indices) < self.ndim:
        indices.append(None)
    state = 0
    has_contiguous_subspace = False
    for index in indices:
        if <MASK>:
            if index is not None:
                state = 1
        elif state == 1:
            if index is None:
                state = 2
        elif index is not None:
            break
    else:
        has_contiguous_subspace = True
    if not has_contiguous_subspace:
        dims = []
        transposed_indices = []
        for (i, index) in enumerate(indices):
            if index is not None:
                dims.append(i)
                transposed_indices.append(index)
        for (i, index) in enumerate(indices):
            if index is None:
                dims.append(i)
                transposed_indices.append(index)
        self = self.permute(dims)
        indices = transposed_indices
    before_shape: list[int] = []
    after_shape: list[int] = []
    replacement_shape: list[int] = []
    for (dim, index) in enumerate(indices):
        if index is None:
            if replacement_shape:
                after_shape.append(self.shape[dim])
            else:
                before_shape.append(self.shape[dim])
        else:
            replacement_shape = list(index.shape)

    def _restride_src(self):
        """
        This follows restride_src in TensorAdvancedIndexing.cpp
        """
        shape = before_shape + replacement_shape + after_shape
        strides = list(self.stride())
        strides[len(before_shape):len(self.shape) - len(after_shape)] = [0] * len(replacement_shape)
        return self.as_strided(shape, strides)
    out = self.new_empty(before_shape + replacement_shape + after_shape)
    from torch.fx.experimental.symbolic_shapes import guard_or_false
    if guard_or_false(self.numel() == 0):
        return out
    restrided_self = _restride_src(self)
    (perm, _) = utils.compute_elementwise_output_logical_to_physical_perm(restrided_self)
    if list(perm) != list(range(len(perm))):
        perm_shape = utils.apply_perm(out.shape, perm)
        new_stride = utils.make_contiguous_strides_for(perm_shape)
        new_stride = utils.apply_perm(new_stride, utils.invert_perm(perm))
        out = out.as_strided(out.size(), new_stride)
    return out

def _einsum_v1(equation, *inputs, **kwargs):
    """Legacy implementation of einsum without using EinsumOp."""
    name = kwargs.pop('name', None)
    if <MASK>:
        raise TypeError(f"Invalid keyword arguments for this function: {', '.join([format(key) for key in sorted(list(kwargs.keys()))])}. Expected: name.")
    with ops.name_scope(name, 'einsum', [equation, inputs]) as name:
        inputs = list(inputs)
        input_shapes = [x.shape for x in inputs]
        (input_axis_labels, output_axis_labels) = _einsum_v1_parse_and_resolve_equation(equation, input_shapes)
        axis_labels = set(''.join(input_axis_labels) + output_axis_labels)
        for a in axis_labels:
            for input_labels in input_axis_labels:
                if len(input_axis_labels) == 1 and input_labels.count(a) == 2 and (input_labels == input_labels[::-1]) and ('->' not in equation):
                    return math_ops.trace(inputs[0])
                if input_labels.count(a) > 1:
                    raise ValueError(f'Subscript not supported: the axis {a} appears more than once in {input_labels}.')
        for a in axis_labels:
            input_count = sum((1 for s in input_axis_labels if a in s))
            if input_count > 2 and a not in output_axis_labels:
                logging.warn(f'Falling back to exponential-space implementation of einsum() because index {a} is summed over more than two inputs.')
                return _exponential_space_einsum_v1(equation, *inputs)
        if _enclosing_tpu_context() is not None and len(inputs) == 2:
            return gen_xla_ops.xla_einsum(inputs[0], inputs[1], input_axis_labels[0] + ',' + input_axis_labels[1] + '->' + output_axis_labels)
        temp = inputs[0]
        temp_axis_labels = input_axis_labels[0]
        for i in range(len(inputs) - 1):
            axes_to_sum = set(temp_axis_labels) & set(input_axis_labels[i + 1]) - set(output_axis_labels)
            (temp, temp_axis_labels) = _einsum_v1_reduction(temp, temp_axis_labels, inputs[i + 1], input_axis_labels[i + 1], axes_to_sum)
        missing_indices = set(temp_axis_labels) - set(output_axis_labels)
        if missing_indices:
            axis = [i for (i, a) in enumerate(temp_axis_labels) if a not in output_axis_labels]
            temp = math_ops.reduce_sum(temp, axis=axis)
            temp_axis_labels = ''.join((a for a in temp_axis_labels if a in output_axis_labels))
        if sorted(temp_axis_labels) != sorted(output_axis_labels):
            raise ValueError(f'Invalid equation: {equation}. The computed and specified output labels do not match: {temp_axis_labels} vs {output_axis_labels}.')
        perm = [temp_axis_labels.index(a) for a in output_axis_labels]
        return _transpose_if_necessary(temp, perm)

def signal_connect_error(model_key, func, args, keywords):
    error_msg = "%(receiver)s was connected to the '%(signal)s' signal with a lazy reference to the sender '%(model)s', but %(model_error)s."
    receiver = args[0]
    if isinstance(receiver, types.FunctionType):
        description = "The function '%s'" % receiver.__name__
    elif <MASK>:
        description = "Bound method '%s.%s'" % (receiver.__self__.__class__.__name__, receiver.__name__)
    else:
        description = "An instance of class '%s'" % receiver.__class__.__name__
    signal_name = model_signals.get(func.__self__, 'unknown')
    params = {'model': '.'.join(model_key), 'receiver': description, 'signal': signal_name, 'model_error': app_model_error(model_key)}
    return Error(error_msg % params, obj=receiver.__module__, id='signals.E001')

def while_loop(cond_fn, body_fn, carried_inputs):
    """
    Run body_fn(*carried_inputs) while cond_fn(*carried_inputs) returns a True scalar tensor. Returns the output of body_fn or
    initial carried_inputs.

    .. warning::
        `torch.while_loop` is a prototype feature in PyTorch. It has limited support for input and output types and
        doesn't support training currently. Please look forward to a more stable implementation in a future version of PyTorch.
        Read more about feature classification at: https://pytorch.org/blog/pytorch-feature-classification-changes/#prototype

    `while_loop` is a structured control flow operator. It preserves the loop semantic across the torch.compile and torch.export.

    `while_loop` is equivalent to the following:

        def while_loop(cond_fn, body_fn, carried_inputs):
            val = carried_inputs
            while cond_fn(*val):
                val = body_fn(*val)
            return val

    Args:
        cond_fn (Callable): A callable function that returns a boolean Scalar tensor or a python boolean.

        body_fn (Callable): A callable function that takes the same inputs as `cond_fn` and returns a tuple of tensors or ints

        carried_inputs (Tuple of possibly nested dict/list/tuple of tensors or ints): A tuple of inputs to cond_fn and body_fn.
            It's also the initial value of states that are carried across iterations. Note that when pass an integer as carry,
            the corresponding return of while_loop will be another int with unknown values because we don't know how many
            iterations while_loop will run.

    Example 1:

        def cond_fn(iter, x):
            return iter.sum() < 10

        def body_fn(iter, x):
            return iter + 1, x.sin()

        while_loop(cond_fn, body_fn, (torch.zeros(1), torch.randn(3, 4)))

    Example 2:

        def cond_fn(int_iter, x):
            return 2 * int_iter < x.shape[0]

        def body_fn(int_iter, x):
            return int_iter + 1, x + int_iter

        while_loop(cond,_fn, body_fn, (0, torch.randn(3, 4)))

    Restrictions:

        - body_fn must return tensors or int with the same metadata (e.g.shape, dtype) as inputs.

        - body_fn and cond_fn must not in-place mutate the carried_inputs. A clone before the mutation is required.

        - body_fn and cond_fn must not mutate python variables (e.g. list/dict) created outside of the body_fn.

        - body_fn and cond_fn's output cannot alias any of the inputs. A clone is required.

    .. warning::
        Temporal Limitations:

        - 'while_loop' only supports **inference** right now. Autograd will be supported in the future.

    """
    from torch._dynamo.backends.debugging import make_eager_backend_with_torch_function_mode
    additional_inputs: tuple = ()
    (flat_inputs, in_spec) = pytree.tree_flatten((carried_inputs, additional_inputs))

    def flat_cond_fn(*flat_args):
        (carried, additional) = pytree.tree_unflatten(flat_args, in_spec)
        return cond_fn(*carried, *additional)

    def flat_body_fn(*flat_args):
        (carried, additional) = pytree.tree_unflatten(flat_args, in_spec)
        return body_fn(*carried, *additional)
    if torch.compiler.is_dynamo_compiling():
        return while_loop_op(flat_cond_fn, flat_body_fn, tuple(flat_inputs), tuple())

    def _validate_input(cond_fn, body_fn, carried_inputs):
        from torch._higher_order_ops.utils import validate_subgraph_args_types
        if not callable(cond_fn) or not callable(body_fn):
            raise RuntimeError('Expect cond_fn and body_fn to be callable.')
        validate_subgraph_args_types(flat_inputs)
        if not pytree.tree_all(lambda t: isinstance(t, (torch.Tensor, torch.SymInt, int)), carried_inputs):
            raise RuntimeError(f'Expect carried_inputs to be a tuple of possibly nested dict/list/tuple that onlyconsists of tensor or int leaves, but got {carried_inputs}.')
    _validate_input(cond_fn, body_fn, carried_inputs)

    def _while_loop_op_wrapper(*args, **kwargs):
        return while_loop_op(*args, **kwargs)
    with _set_compilation_env(), torch._dynamo.utils.disable_cache_limit():
        with _temp_remove_metadata_torch_function_mode() as metadata_mode:
            with _temp_remove_metadata_torch_function_mode() as metadata_mode:
                if <MASK>:
                    backend: Union[str, Callable[..., Any]] = make_eager_backend_with_torch_function_mode(metadata_mode)
                else:
                    backend = 'eager'
                return torch.compile(_while_loop_op_wrapper, backend=backend, fullgraph=True)(flat_cond_fn, flat_body_fn, tuple(flat_inputs), tuple())

def __getattr__(self, name):
    """Return the value of a setting and cache it in self.__dict__."""
    if (_wrapped := self._wrapped) is empty:
        self._setup(name)
        _wrapped = self._wrapped
    val = getattr(_wrapped, name)
    if <MASK>:
        val = self._add_script_prefix(val)
    elif name == 'SECRET_KEY' and (not val):
        raise ImproperlyConfigured('The SECRET_KEY setting must not be empty.')
    self.__dict__[name] = val
    return val

@aten.native_batch_norm.default.py_impl(DispatchKey.Autograd)
@aten.native_batch_norm.default.py_impl(DispatchKey.CompositeImplicitAutograd)
def native_batch_norm_decomposition(input: Tensor, weight: Optional[Tensor], bias: Optional[Tensor], running_mean: Optional[Tensor], running_var: Optional[Tensor], training: bool, momentum: float, eps: float) -> tuple[Tensor, Tensor, Tensor]:
    if running_mean is None and running_var is None:
        return aten._native_batch_norm_legit(input, weight, bias, training, momentum, eps)
    if running_mean is None:
        raise RuntimeError('running_mean is None, but running_var is provided. They should both be None or both be provided.')
    if running_var is None:
        raise RuntimeError('running_var is None, but running_mean is provided. They should both be None or both be provided.')
    if <MASK>:
        return aten._native_batch_norm_legit(input, weight, bias, running_mean, running_var, training, momentum, eps)
    else:
        return aten._native_batch_norm_legit_no_training(input, weight, bias, running_mean, running_var, momentum, eps)

def generate_output(output: Any, indices: list[tuple[Any, int]]) -> Any:
    if isinstance(output, (list, tuple)):
        return type(output)((generate_output(output[i], indices + [(type(output), i)]) for i in range(len(output))))
    elif <MASK>:
        return {key: generate_output(val, indices + [(type(output), key)]) for (key, val) in output.items()}
    elif isinstance(output, torch.Tensor):
        buf = MultiOutput(cls.tensor_to_layout(output), packed, indices)
        if config.assume_unaligned_fallback_output or has_unaligned_input or (not tensor_is_aligned(output)):
            V.graph.unaligned_buffers.add(buf.name)
        return buf
    elif isinstance(output, int):
        return output
    elif isinstance(output, torch.SymInt):
        return output.node.expr
    else:
        assert output is None, f'FallbackKernel output type {type(output)} is not supported'
        return None

def _maybe_pad_for_rfft(input_tensor, fft_rank, fft_length, is_reverse=False):
    """Pads `input_tensor` to `fft_length` on its inner-most `fft_rank` dims."""
    fft_shape = _tensor_util.constant_value_as_shape(fft_length)
    if input_tensor.shape.ndims is not None and any((dim.value == 0 for dim in input_tensor.shape.dims)):
        return input_tensor
    if fft_shape.is_fully_defined() and input_tensor.shape.ndims is not None:
        input_fft_shape = input_tensor.shape[-fft_shape.ndims:]
        if <MASK>:
            if is_reverse:
                fft_shape = fft_shape[:-1].concatenate(fft_shape.dims[-1].value // 2 + 1)
            paddings = [[0, max(fft_dim.value - input_dim.value, 0)] for (fft_dim, input_dim) in zip(fft_shape.dims, input_fft_shape.dims)]
            if any((pad > 0 for (_, pad) in paddings)):
                outer_paddings = [[0, 0]] * max(input_tensor.shape.ndims - fft_shape.ndims, 0)
                return _array_ops.pad(input_tensor, outer_paddings + paddings)
            return input_tensor
    input_rank = _array_ops.rank(input_tensor)
    input_fft_shape = _array_ops.shape(input_tensor)[-fft_rank:]
    outer_dims = _math_ops.maximum(0, input_rank - fft_rank)
    outer_paddings = _array_ops.zeros([outer_dims], fft_length.dtype)
    if is_reverse:
        fft_length = _array_ops.concat([fft_length[:-1], fft_length[-1:] // 2 + 1], 0)
    fft_paddings = _math_ops.maximum(0, fft_length - input_fft_shape)
    paddings = _array_ops.concat([outer_paddings, fft_paddings], 0)
    paddings = _array_ops_stack.stack([_array_ops.zeros_like(paddings), paddings], axis=1)
    return _array_ops.pad(input_tensor, paddings)

def create_joint(fn: Any, primals_descs: Optional[list[AOTInput]]=None, *, aot_config: AOTConfig) -> Any:
    joint_fn_handle = JointFnHandle()

    @simple_wraps(fn)
    def inner_fn(primals: list[FxValue], tangents: list[FxValue]) -> tuple[tuple[list[FxValue], list[Optional[Tensor]]], tuple[list[AOTOutput], list[Optional[AOTOutput]]]]:
        outs_descs = None
        if primals_descs is None:
            (outs, tangent_mask) = fn(*primals)
            assert not pytree.tree_any(lambda x: isinstance(x, AOTOutput), tangent_mask)
        else:
            ((outs, tangent_mask), (outs_descs, _)) = call_and_expect_output_descs(fn, primals)
        if <MASK>:
            joint_fn_handle.post_forward(primals)
        assert len(tangent_mask) == len(outs)
        outs_to_grad = [o for (needs_tangent, o) in zip(tangent_mask, outs) if needs_tangent]
        assert len(outs_to_grad) == len(tangents)
        grad_primals: list[torch.Tensor] = []
        inputs_needs_grads = []
        for p in primals:
            if isinstance(p, Tensor) and p.requires_grad:
                inputs_needs_grads.append(True)
                assert isinstance(p, torch.Tensor)
                grad_primals.append(p)
            else:
                inputs_needs_grads.append(False)
        needed_outs = []
        needed_tangents = []
        for (out, tangent) in zip(outs_to_grad, tangents):
            if isinstance(out, Tensor) and out.requires_grad:
                assert isinstance(tangent, torch.Tensor), f'Expected tensor tangent, got {type(tangent)}'
                needed_outs.append(out if guard_or_true(sym_eq(out.shape, tangent.shape)) else out.view(tangent.shape))
                needed_tangents.append(tangent)
        setup_stacktrace_preservation_hooks([out.grad_fn for out in needed_outs])
        if config.functionalize_rng_ops:
            PhiloxStateTracker.mark_beginning_of_backward()
        backward_out: tuple[Tensor, ...] = ()
        if grad_primals:
            functional_tensor_mode = torch.utils._python_dispatch._detect_infra_mode(torch._C._TorchDispatchModeKey.FUNCTIONAL)
            if functional_tensor_mode is not None:
                functional_tensor_mode._tokens_forward_output = functional_tensor_mode._tokens
                functional_tensor_mode._tokens = {}
            with set_partitioner_tag_is_backward(), fx_traceback.preserve_node_meta(), ExitStack() as stack:
                backward_pass_autocast = torch._functorch.config.backward_pass_autocast
                if backward_pass_autocast == 'same_as_forward':
                    pass
                elif backward_pass_autocast == 'off':
                    stack.enter_context(disable_autocast())
                else:
                    stack.enter_context(disable_autocast())
                    assert isinstance(backward_pass_autocast, list)
                    for kwargs in backward_pass_autocast:
                        assert isinstance(kwargs, dict)
                        stack.enter_context(torch.amp.autocast(**kwargs))
                if aot_config.no_tangents:
                    assert len(needed_tangents) == 1 and needed_tangents[0].numel() == 1
                    backward_out = torch.autograd.grad(needed_outs, grad_primals, allow_unused=True)
                else:
                    backward_out = torch.autograd.grad(needed_outs, grad_primals, grad_outputs=needed_tangents, allow_unused=True)
        backward_out_iter = iter(backward_out)
        final_outs = (outs, [next(backward_out_iter) if i else None for i in inputs_needs_grads])
        if primals_descs is None:
            return final_outs
        assert outs_descs is not None
        return (final_outs, (outs_descs, [GradAOTOutput(desc) if i else None for (i, desc) in zip(inputs_needs_grads, primals_descs)]))

    @simple_wraps(inner_fn)
    def inner_fn_with_anomaly(primals: list[FxValue], tangents: list[FxValue]) -> tuple[tuple[list[FxValue], list[Optional[Tensor]]], tuple[list[AOTOutput], list[Optional[AOTOutput]]]]:
        with fx_traceback.preserve_node_meta(), warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'Anomaly Detection has been enabled.')
            with torch.autograd.detect_anomaly(check_nan=False):
                return inner_fn(primals, tangents)

    def joint_helper(primals, tangents):
        return inner_fn_with_anomaly(primals, tangents)
    joint_helper.handle = joint_fn_handle
    return joint_helper

def _correct_storage_aliasing(func, schema_info, args, outs):
    """
    Given: an OpOverload, a SchemaInfo (cached information from torchgen about schema),
    and the inputs/outputs to the OpOverload,
    this function checks to see if func is a view operator
    (by checking if any of the outputs in the op's schema
     are immutable aliases of inputs).
    If so, this function manually aliases the storage of the output tensor
    with its corresponding input tensor alias.
    It does this by unsafely overwriting the storage field of the output tensor
    to be the same storage as the input.
    """
    assert isinstance(func, torch._ops.OpOverload)
    assert isinstance(args, tuple)
    assert isinstance(outs, (list, tuple))

    def alias_non_inplace_storage(arg, ret):
        arg_type = type(arg)
        ret_type = type(ret)
        if <MASK>:
            ret_list = ret if isinstance(ret, list) else [ret]
            for r in ret_list:
                assert type(arg) is type(r), f'Called {str(func)} with input of type {type(arg)}\nand output of type {type(ret)}. But expected types to match.'
        if isinstance(ret, list):
            for r in ret:
                torch._functionalize_unsafe_set(r, arg)
        else:
            assert isinstance(ret, torch.Tensor), f'type: {type(ret)}'
            torch._functionalize_unsafe_set(ret, arg)
    for (arg_idx, schema_arg) in enumerate(schema_info.args):
        for (return_idx, schema_out) in enumerate(schema_info.outs):
            is_read_only_alias_match = schema_arg.alias_set & schema_out.alias_set and (not schema_arg.is_write)
            if is_read_only_alias_match:
                alias_non_inplace_storage(args[arg_idx], outs[return_idx])

def _validate_device_maps(all_names, all_device_counts, all_device_maps, all_devices, is_static_group=True):
    for node in all_names:
        devices = all_devices[node]
        if len(set(devices)) != len(devices):
            raise ValueError(f'Node {node} has duplicated devices\ndevices = {devices}')
        if <MASK>:
            raise ValueError(f'Node {node} has devices with invalid indices\ndevices = {devices}\ndevice count = {all_device_counts[node]}')
    for source_node in all_names:
        if is_static_group and (not set(all_device_maps[source_node].keys()).issubset(all_names)):
            raise ValueError(f'Node {source_node} has invalid target node names in its device maps\ndevice maps = {all_device_maps[source_node].keys()}\nnode names = {all_names}')
        for (target_node, map_) in all_device_maps[source_node].items():
            if len(set(map_.values())) != len(map_):
                raise ValueError(f'Node {source_node} has duplicated target devices in its device map for {target_node}\ndevice map = {map_}')
            if all_devices[source_node]:
                if not set(map_.keys()).issubset(all_devices[source_node]):
                    raise ValueError(f'Node {source_node} has unexpected source devices in its device map for {target_node}\ndevice map = {map_}\ndevices = {all_devices[source_node]}')
            elif not _tensorpipe_validate_devices(map_.keys(), all_device_counts[source_node]):
                raise ValueError(f'Node {source_node} has source devices with invalid indices in its device map for {target_node}\ndevice map = {map_}\ndevice count = {all_device_counts[source_node]}')
            if all_devices.get(target_node, []):
                if not set(map_.values()).issubset(all_devices[target_node]):
                    raise ValueError(f'Node {source_node} has unexpected target devices in its device map for {target_node}\ndevice map = {map_}\ndevices = {all_devices[target_node]}')
            elif target_node in all_device_counts and (not _tensorpipe_validate_devices(map_.values(), all_device_counts[target_node])):
                raise ValueError(f'Node {source_node} has target devices with invalid indices in its device map for {target_node}\ndevice map = {map_}\ndevice count = {all_device_counts[target_node]}')

def _allocate(self, block: Allocation, is_last: bool):
    slot_size = self.get_size_hint()
    block_size = block.get_size_hint()
    if not is_last and block_size > slot_size:
        return False
    block_live = block.get_live_ranges()
    overlapping = [s for s in self.allocations if s.get_live_ranges().overlaps(block_live)]
    if <MASK>:
        return False
    elif len(overlapping) == 1:
        return overlapping[0].allocate(block, is_last)
    else:
        block.mark_allocated()
        if len(self.allocations) == 1 and isinstance(self.allocations[-1], Empty):
            self.allocations.pop()
        if slot_size == block_size:
            self.allocations.append(block)
        elif slot_size > block_size:
            self.allocations.append(SpatialSplit.create(block, slot_size - block_size))
        else:
            assert is_last
            self.allocations = [*(SpatialSplit.create(a, block_size - slot_size) for a in self.allocations), block]
        return True

def assert_correct_number_of_output_shapes(node):
    if node.op == 'StatefulPartitionedCall':
        fn_name = node.attr['f'].func.name
        if fn_name.startswith('__inference_f'):
            self.assertLen(node.attr['_output_shapes'].list.shape, 2)
        if <MASK>:
