        tags = {child.tag for child in children}
        return 'skipped' not in tags and 'failed' not in tags
    return find(testcase, condition)

def visit_manager(node: GuardManager) -> list[GuardManager]:
    assert not isinstance(node, DictGuardManager)
    tag_safe_roots = []
    for child_mgr in node.get_child_managers():
        tag_safe_roots.extend(visit(child_mgr))
    if node.is_guarded_value_immutable():
        if issubclass(node.get_type_of_guarded_value(), torch.Tensor):
            if node.has_no_accessors() and (not node.has_object_aliasing_guard()):
                node.mark_tag_safe()
        else:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), dict):
        accessors = node.get_accessors()
        child_mgrs = node.get_child_managers()
        is_subtree_tag_safe = all((isinstance(accessor, DictGetItemGuardAccessor) and mgr.is_tag_safe() for (accessor, mgr) in zip(accessors, child_mgrs)))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), torch.nn.Module):
        is_subtree_tag_safe = check_tag_safety(node, (GetGenericDictGuardAccessor, TypeGuardAccessor))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
            return [node]
    elif node.get_type_of_guarded_value() in (types.FunctionType, types.MethodType, staticmethod, classmethod) and config.assume_dunder_attributes_remain_unchanged:
        is_subtree_tag_safe = check_tag_safety(node, (CodeGuardAccessor, ClosureGuardAccessor, FuncDefaultsGuardAccessor, FuncKwDefaultsGuardAccessor, GetAttrGuardAccessor))
        for accessor in node.get_accessors():
            if <MASK>:
                is_subtree_tag_safe &= accessor.get_attr_name() in dunder_attrs_assumed_constants
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), types.CellType):
        is_subtree_tag_safe = check_tag_safety(node, (GetAttrGuardAccessor,))
        is_subtree_tag_safe &= all((isinstance(accessor, GetAttrGuardAccessor) and accessor.get_attr_name() == 'cell_contents' for accessor in node.get_accessors()))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), tuple) and node.get_source().endswith(dunder_attrs_assumed_constants) and config.assume_dunder_attributes_remain_unchanged:
        is_subtree_tag_safe = check_tag_safety(node, (TupleGetItemGuardAccessor,))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    elif issubclass(node.get_type_of_guarded_value(), type):
        is_subtree_tag_safe = check_tag_safety(node, (TypeDictGuardAccessor, TypeMROGuardAccessor))
        if is_subtree_tag_safe:
            node.mark_tag_safe()
    return tag_safe_roots

def _graph_mode_decorator(f, args, kwargs):
    """Implement custom gradient decorator for graph mode."""
    if kwargs:
        raise ValueError('The custom_gradient decorator currently supports keywords arguments only when eager execution is enabled.')
    name = generate_name()
    args = variable_utils.convert_variables_to_tensors(args)
    args = nest.map_structure(ops.convert_to_tensor, args, expand_composites=True)
    current_var_scope = variable_scope.get_variable_scope()
    before_vars = set([v.ref() for v in current_var_scope.global_variables() + current_var_scope.local_variables()])
    with record.VariableWatcher() as variable_watcher:
        (result, grad_fn) = f(*args)
    flat_args = composite_tensor_gradient.get_flat_tensors_for_gradients(nest.flatten(args))
    flat_result = composite_tensor_gradient.get_flat_tensors_for_gradients(nest.flatten(result))
    flat_result_len = len(flat_result)
    after_vars = set([v.ref() for v in current_var_scope.global_variables() + current_var_scope.local_variables()])
    new_vars = after_vars - before_vars
    new_vars_list = [v.deref() for v in new_vars]
    for v in new_vars_list:
        if not resource_variable_ops.is_resource_variable(v):
            raise TypeError('All variables used by a function wrapped with @custom_gradient must be `ResourceVariable`s. Ensure that no `variable_scope` is created with `use_resource=False`.')
    variables_in_tape = frozenset([v.ref() for v in variable_watcher.watched_variables()])
    graphs = {getattr(o, 'graph', None) for o in flat_result}
    graphs.discard(None)
    if graphs:
        if <MASK>:
            raise ValueError('All custom_gradient outputs should be from the same graph')
        output_graph = graphs.pop()
        filtered_input_tensors = []
        for i in flat_args:
            if i.graph == output_graph:
                filtered_input_tensors.append(i)
    else:
        filtered_input_tensors = flat_args
    variables_in_subgraph = frozenset([v.ref() for v in _get_dependent_variables(input_ops=filtered_input_tensors, output_ops=flat_result)])
    variables = sorted([v.deref() for v in variables_in_subgraph.union(variables_in_tape)], key=lambda v: v.name)
    grad_argspec = tf_inspect.getfullargspec(grad_fn)
    variables_in_signature = 'variables' in grad_argspec.args or 'variables' in grad_argspec.kwonlyargs or grad_argspec.varkw
    if variables and (not variables_in_signature):
        raise TypeError("@tf.custom_gradient grad_fn must accept keyword argument 'variables', since function uses variables: {}".format(variables))
    if variables_in_signature and (not variables):
        logging.vlog(1, "@custom_gradient grad_fn has 'variables' in signature, but no ResourceVariables were used on the forward pass.")
    all_tensors = flat_result + flat_args + variables

    def tape_grad_fn(*result_grad_components):
        """Custom grad fn wrapper."""
        result_grads = composite_tensor_gradient.replace_flat_tensors_for_gradients(nest.flatten(result), result_grad_components[:flat_result_len])
        if not isinstance(result_grads, (list, tuple)):
            result_grads = [result_grads]
        if variables:
            (input_grads, variable_grads) = grad_fn(*result_grads, variables=variables)
            if len(variable_grads) != len(variables):
                raise ValueError('Must return gradient for each variable from @custom_gradient grad_fn.')
        else:
            input_grads = grad_fn(*result_grads)
            variable_grads = []
        input_grads = composite_tensor_gradient.get_flat_tensors_for_gradients(nest.flatten(input_grads))
        return [None] * flat_result_len + input_grads + variable_grads

    @ops.RegisterGradient(name)
    def internal_grad_fn(unused_op, *result_grads):
        """Custom grad fn wrapper."""
        return tape_grad_fn(*result_grads)
    original_tensors = all_tensors
    with ops.get_default_graph().gradient_override_map({'IdentityN': name}):
        all_tensors = array_ops.identity_n(all_tensors)
    original_tensors = [ops.convert_to_tensor(x) for x in original_tensors]
    for (i, t) in enumerate(original_tensors):
        if t.dtype == dtypes.resource and hasattr(t, '_handle_data'):
            all_tensors[i]._handle_data = t._handle_data
    record.record_operation(f.__name__, all_tensors, original_tensors, tape_grad_fn)
    for (ot, t) in zip(original_tensors, all_tensors):
        handle_data_util.copy_handle_data(ot, t)
    flat_result = composite_tensor_gradient.replace_flat_tensors_for_gradients(nest.flatten(result), all_tensors[:flat_result_len])
    return nest.pack_sequence_as(result, flat_result)

def _create_recomputable_node_only_graph_with_larger_graph_context(self) -> nx.DiGraph:
    all_recomputable_banned_nodes_set = set(self.all_recomputable_banned_nodes)
    reachable_nodes = {}
    for node in all_recomputable_banned_nodes_set:
        predecessors = dict(nx.bfs_predecessors(self.full_joint_nx_graph, node))
        reachable_recomputable_nodes = set(predecessors.keys()).intersection(all_recomputable_banned_nodes_set)
        reachable_nodes[node] = reachable_recomputable_nodes
    candidate_graph = nx.DiGraph()
    candidate_graph.add_nodes_from(all_recomputable_banned_nodes_set)
    for node1 in all_recomputable_banned_nodes_set:
        for node2 in reachable_nodes[node1]:
            overlapping_path = False
            for intermediate_node in reachable_nodes[node1]:
                if <MASK>:
                    overlapping_path = True
                    break
            if not overlapping_path:
                candidate_graph.add_edge(node1, node2)
    return candidate_graph

def _trace_impl(func, example_inputs=None, optimize=None, check_trace=True, check_inputs=None, check_tolerance=1e-05, strict=True, _force_outplace=False, _module_class=None, _compilation_unit=_python_cu, example_kwarg_inputs=None, _store_inputs=True):
    if isinstance(func, torch.jit.ScriptModule):
        warnings.warn('The input to trace is already a ScriptModule, tracing it is a no-op. Returning the object as is.')
        return func
    if isinstance(func, torch.nn.Module):
        if <MASK>:
            if isinstance(example_kwarg_inputs, dict):
                example_inputs = example_kwarg_inputs
            else:
                raise RuntimeError('example_kwarg_inputs should be a dict')
        return trace_module(func, {'forward': example_inputs}, None, check_trace, wrap_check_inputs(check_inputs), check_tolerance, strict, _force_outplace, _module_class, example_inputs_is_kwarg=isinstance(example_kwarg_inputs, dict), _store_inputs=_store_inputs)
    if hasattr(func, '__self__') and isinstance(func.__self__, torch.nn.Module) and (func.__name__ == 'forward'):
        if example_inputs is None:
            if isinstance(example_kwarg_inputs, dict):
                example_inputs = example_kwarg_inputs
            else:
                raise RuntimeError('example_kwarg_inputs should be a dict')
        return trace_module(func.__self__, {'forward': example_inputs}, None, check_trace, wrap_check_inputs(check_inputs), check_tolerance, strict, _force_outplace, _module_class, example_inputs_is_kwarg=isinstance(example_kwarg_inputs, dict), _store_inputs=_store_inputs)
    if isinstance(example_inputs, (torch.Tensor, dict)) and example_kwarg_inputs is None:
        example_inputs = (example_inputs,)
    elif example_kwarg_inputs is None and (not isinstance(example_inputs, tuple)):
        example_inputs = tuple(example_inputs)
    var_lookup_fn = _create_interpreter_name_lookup_fn(0)
    if hasattr(func, '__self__') and isinstance(func.__self__, torch.nn.Module):
        raise AttributeError("trace doesn't support compiling individual module's functions.\nPlease use trace_module")
    name = _qualified_name(func)
    if isinstance(example_kwarg_inputs, dict):
        example_inputs = example_kwarg_inputs
        traced = torch._C._create_function_from_trace_with_dict(name, func, example_kwarg_inputs, var_lookup_fn, strict, _force_outplace, get_callable_argument_names(func))
    else:
        traced = torch._C._create_function_from_trace(name, func, example_inputs, var_lookup_fn, strict, _force_outplace, get_callable_argument_names(func))
    if check_trace:
        if check_inputs is not None:
            _check_trace(check_inputs, func, traced, check_tolerance, strict, _force_outplace, False, _module_class, example_inputs_is_kwarg=isinstance(example_kwarg_inputs, dict))
        else:
            _check_trace([example_inputs], func, traced, check_tolerance, strict, _force_outplace, False, _module_class, example_inputs_is_kwarg=isinstance(example_kwarg_inputs, dict))
    traced._torchdynamo_inline = func
    return traced

def print_summary_table(data, print_dataframe=False):
    if print_dataframe:
        pd.options.display.max_rows = 1000
        pd.options.display.max_columns = 1000
        pd.options.display.width = 2000
        print(data)
    width = max(map(len, data.columns))
    for col in data.columns:
        try:
            if col in ('dev', 'name', 'batch_size', 'tag'):
                continue
            elif col in ('pct_ops', 'pct_time'):
                print(col.ljust(width), f'{data[col].mean():.3%}')
            elif <MASK>:
                print(col.ljust(width), f'{data[col].mean():.3f}')
            elif col in 'compilation_latency':
                print(col.ljust(width), f'mean={data[col].mean():.3f} seconds')
            elif col in 'compression_ratio':
                print(col.ljust(width), f'mean={data[col].mean():.3f}x')
            elif col in 'accuracy':
                pass_rate = (data[col] == 'pass').mean()
                print(col.ljust(width), f'pass_rate={100 * pass_rate:.2f}%')
            else:
                cdata = data[col]
                print(col.ljust(width), f'gmean={gmean(cdata):.2f}x mean={cdata.mean():.3f}x')
        except Exception:
            pass

def build(self, input_shape):
    if self.data_format == 'channels_first':
        channel_axis = 1
    else:
        channel_axis = -1
    if input_shape[channel_axis] is None:
        raise ValueError('The channel dimension of the inputs should be defined. Found `None`.')
    input_dim = input_shape[channel_axis]
    kernel_shape = self.kernel_size + (input_dim, self.filters * 4)
    self.kernel_shape = kernel_shape
    recurrent_kernel_shape = self.kernel_size + (self.filters, self.filters * 4)
    self.kernel = self.add_weight(shape=kernel_shape, initializer=self.kernel_initializer, name='kernel', regularizer=self.kernel_regularizer, constraint=self.kernel_constraint)
    self.recurrent_kernel = self.add_weight(shape=recurrent_kernel_shape, initializer=self.recurrent_initializer, name='recurrent_kernel', regularizer=self.recurrent_regularizer, constraint=self.recurrent_constraint)
    if self.use_bias:
        if <MASK>:

            def bias_initializer(_, *args, **kwargs):
                return backend.concatenate([self.bias_initializer((self.filters,), *args, **kwargs), initializers.get('ones')((self.filters,), *args, **kwargs), self.bias_initializer((self.filters * 2,), *args, **kwargs)])
        else:
            bias_initializer = self.bias_initializer
        self.bias = self.add_weight(shape=(self.filters * 4,), name='bias', initializer=bias_initializer, regularizer=self.bias_regularizer, constraint=self.bias_constraint)
    else:
        self.bias = None
    self.built = True

def can_fuse_vertical(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode) -> bool:
    """
        Check if it is legal to fuse a consumer (node2) into a producer (node1).

        We can fuse them if all the reads of node2 either match
        corresponding writes in node1, or are written by nodes that can
        be scheduled before the fusion of node1 and node2.
        """
    node1_buf_names = node1.get_buffer_names()
    why = WhyNoFuse(node1, node2)
    remaining_deps_by_name: dict[str, list[Dep]] = defaultdict(list)
    for dep in node2.unmet_dependencies:
        name = self.mutation_renames.get(dep.name, dep.name)
        if isinstance(dep, WeakDep) and self.fusable_weak_dep(dep, node1, node2):
            continue
        remaining_deps_by_name[name].append(dep)
    for cd in node1.read_writes.writes:
        if not isinstance(cd, MemoryDep):
            continue
        remaining = remaining_deps_by_name.get(self.mutation_renames.get(cd.name, cd.name))
        if remaining:
            for rd in remaining:
                if <MASK>:
                    remaining.remove(rd)
    remaining_deps = OrderedSet((dep.name for dep in itertools.chain.from_iterable(remaining_deps_by_name.values())))
    if remaining_deps & node1_buf_names:
        why('memory deps did not match')
        return False
    node1_op_names = node1.get_operation_names()
    for name in remaining_deps:
        op_name = self.name_to_buf[name].defining_op_name()
        if node1_op_names & self.name_to_fused_node[op_name].ancestors:
            why('intermediate nodes between node1 & node2')
            return False
    return True

def get(self, key, default=None, version=None):
    key = self.make_and_validate_key(key, version=version)
    with self._lock:
        if <MASK>:
            self._delete(key)
            return default
        pickled = self._cache[key]
        self._cache.move_to_end(key, last=False)
    return pickle.loads(pickled)

def _get_regex_match(line, regex, is_last_match=False):
    match = re.search(regex, line)
    if <MASK>:
        return (match.group(1), is_last_match)
    return (None, False)

def _find_code_source(obj: Any) -> Optional[str]:
    nonlocal toplevel
    nonlocal seen
    if obj in seen:
        return None
    seen.add(obj)
    if inspect.iscode(obj):
        if obj is code:
            return ''
        for (i, const) in enumerate(obj.co_consts):
            if (res := _find_code_source(const)) is not None:
                return f'.co_consts[{i}]{res}'
    if inspect.isfunction(obj):
        if (res := _find_code_source(obj.__code__)) is not None:
            toplevel = obj
            return f'.__code__{res}'
        if obj.__closure__ is not None:
            for (i, cell) in enumerate(obj.__closure__):
                try:
                    cell_contents = cell.cell_contents
                except ValueError:
                    continue
                if not (inspect.isfunction(cell_contents) or inspect.iscode(cell_contents)):
                    continue
                if (res := _find_code_source(cell_contents)) is not None:
                    toplevel = obj
                    return f'.__closure__[{i}].cell_contents{res}'
    if sys.version_info < (3, 11):
        if inspect.ismodule(obj):
            for value in obj.__dict__.values():
                if not (inspect.isfunction(value) or inspect.isclass(value)):
                    continue
                if (res := _find_code_source(value)) is not None:
                    return res
        if inspect.isclass(obj):
            for (name, value) in obj.__dict__.items():
                value = getattr(obj, name)
                if not (inspect.isfunction(value) or inspect.isclass(value)):
                    continue
                if (res := _find_code_source(value)) is not None:
                    if <MASK>:
                        _raise_resolution_error(code, toplevel)
                    return res
    return None

def _get_lines(self, rows: int | None=None) -> list[list[Scalar]]:
    lines = self.buf
    new_rows = None
    if <MASK>:
        if len(self.buf) >= rows:
            (new_rows, self.buf) = (self.buf[:rows], self.buf[rows:])
        else:
            rows -= len(self.buf)
    if new_rows is None:
        if isinstance(self.data, list):
            if self.pos > len(self.data):
                raise StopIteration
            if rows is None:
                new_rows = self.data[self.pos:]
                new_pos = len(self.data)
            else:
                new_rows = self.data[self.pos:self.pos + rows]
                new_pos = self.pos + rows
            new_rows = self._remove_skipped_rows(new_rows)
            lines.extend(new_rows)
            self.pos = new_pos
        else:
            new_rows = []
            try:
                if rows is not None:
                    row_index = 0
                    row_ct = 0
                    offset = self.pos if self.pos is not None else 0
                    while row_ct < rows:
                        new_row = next(self.data)
                        if not self.skipfunc(offset + row_index):
                            row_ct += 1
                        row_index += 1
                        new_rows.append(new_row)
                    len_new_rows = len(new_rows)
                    new_rows = self._remove_skipped_rows(new_rows)
                    lines.extend(new_rows)
                else:
                    rows = 0
                    while True:
                        next_row = self._next_iter_line(row_num=self.pos + rows + 1)
                        rows += 1
                        if next_row is not None:
                            new_rows.append(next_row)
                    len_new_rows = len(new_rows)
            except StopIteration:
                len_new_rows = len(new_rows)
                new_rows = self._remove_skipped_rows(new_rows)
                lines.extend(new_rows)
                if len(lines) == 0:
                    raise
            self.pos += len_new_rows
        self.buf = []
    else:
        lines = new_rows
    if self.skipfooter:
        lines = lines[:-self.skipfooter]
    lines = self._check_comments(lines)
    if self.skip_blank_lines:
        lines = self._remove_empty_lines(lines)
    lines = self._check_thousands(lines)
    return self._check_decimal(lines)

@tf_export.tf_export('experimental.numpy.geomspace', v1=[])
@np_utils.np_doc('geomspace')
def geomspace(start, stop, num=50, endpoint=True, dtype=None, axis=0):
    dtype = dtypes.as_dtype(dtype) if dtype else np_utils.result_type(start, stop, float(num), np_array_ops.zeros((), dtype))
    computation_dtype = np.promote_types(dtype.as_numpy_dtype, np.float32)
    start = np_array_ops.asarray(start, dtype=computation_dtype)
    stop = np_array_ops.asarray(stop, dtype=computation_dtype)
    start_sign = 1 - np_array_ops.sign(np_array_ops.real(start))
    stop_sign = 1 - np_array_ops.sign(np_array_ops.real(stop))
    signflip = 1 - start_sign * stop_sign // 2
    res = signflip * logspace(log10(signflip * start), log10(signflip * stop), num, endpoint=endpoint, base=10.0, dtype=computation_dtype, axis=0)
    if <MASK>:
        res = np_array_ops.moveaxis(res, 0, axis)
    return math_ops.cast(res, dtype)

def clear_dir(self, path):
    """
        Delete the given relative path using the destination storage backend.
        """
    if <MASK>:
        return
    (dirs, files) = self.storage.listdir(path)
    for f in files:
        fpath = os.path.join(path, f)
        if self.dry_run:
            self.log("Pretending to delete '%s'" % fpath, level=2)
            self.deleted_files.append(fpath)
        else:
            self.log("Deleting '%s'" % fpath, level=2)
            self.deleted_files.append(fpath)
            try:
                full_path = self.storage.path(fpath)
            except NotImplementedError:
                self.storage.delete(fpath)
            else:
                if not os.path.exists(full_path) and os.path.lexists(full_path):
                    os.unlink(full_path)
                else:
                    self.storage.delete(fpath)
    for d in dirs:
        self.clear_dir(os.path.join(path, d))

def wrapper(op_info, device, dtype, requires_grad, layout, **kwargs):

    def apply_requires_grad(x):
        if <MASK>:
            return x
        return x.detach().clone().requires_grad_(requires_grad)
    if requires_grad:
        for sample_input in sample_inputs(op_info, device, dtype, requires_grad, layout, **kwargs):
            yield sample_input.transform(apply_requires_grad)
    else:
        yield from sample_inputs(op_info, device, dtype, requires_grad, layout, **kwargs)

def legalize_lowp_fp_dtype(self, nodes):
    if <MASK>:
        for _node in nodes:
            sub_blocks = [_node._body.root_block] + list(_node._body.subblocks.values())
            for sub_block in sub_blocks:
                for fx_node in sub_block.graph.nodes:
                    if fx_node.target in ['load', 'store']:
                        assert fx_node.meta
                        assert OptimizationContext.key in fx_node.meta
                        opt_ctx: OptimizationContext = fx_node.meta[OptimizationContext.key]
                        assert opt_ctx.dtype in DTYPE_LOWP_FP
        return
    for _node in nodes:
        assert isinstance(_node, SchedulerNode)
        assert isinstance(_node._body, LoopBody)
        body: LoopBody = _node._body
        if not body.is_memory_copy():
            self.legalize_lowp_fp_dtype_loopbody(body)

def __getitem__(self, key):
    if isinstance(key, str):
        frame = sys._getframe().f_back
        mymat = matrixlib.bmat(key, frame.f_globals, frame.f_locals)
        return mymat
    if not isinstance(key, tuple):
        key = (key,)
    trans1d = self.trans1d
    ndmin = self.ndmin
    matrix = self.matrix
    axis = self.axis
    objs = []
    result_type_objs = []
    for (k, item) in enumerate(key):
        scalar = False
        if <MASK>:
            step = item.step
            start = item.start
            stop = item.stop
            if start is None:
                start = 0
            if step is None:
                step = 1
            if isinstance(step, (_nx.complexfloating, complex)):
                size = int(abs(step))
                newobj = linspace(start, stop, num=size)
            else:
                newobj = _nx.arange(start, stop, step)
            if ndmin > 1:
                newobj = array(newobj, copy=None, ndmin=ndmin)
                if trans1d != -1:
                    newobj = newobj.swapaxes(-1, trans1d)
        elif isinstance(item, str):
            if k != 0:
                raise ValueError('special directives must be the first entry.')
            if item in ('r', 'c'):
                matrix = True
                col = item == 'c'
                continue
            if ',' in item:
                vec = item.split(',')
                try:
                    (axis, ndmin) = [int(x) for x in vec[:2]]
                    if len(vec) == 3:
                        trans1d = int(vec[2])
                    continue
                except Exception as e:
                    raise ValueError(f'unknown special directive {item!r}') from e
            try:
                axis = int(item)
                continue
            except (ValueError, TypeError) as e:
                raise ValueError('unknown special directive') from e
        elif type(item) in ScalarType:
            scalar = True
            newobj = item
        else:
            item_ndim = np.ndim(item)
            newobj = array(item, copy=None, subok=True, ndmin=ndmin)
            if trans1d != -1 and item_ndim < ndmin:
                k2 = ndmin - item_ndim
                k1 = trans1d
                if k1 < 0:
                    k1 += k2 + 1
                defaxes = list(range(ndmin))
                axes = defaxes[:k1] + defaxes[k2:] + defaxes[k1:k2]
                newobj = newobj.transpose(axes)
        objs.append(newobj)
        if scalar:
            result_type_objs.append(item)
        else:
            result_type_objs.append(newobj.dtype)
    if len(result_type_objs) != 0:
        final_dtype = _nx.result_type(*result_type_objs)
        objs = [array(obj, copy=None, subok=True, ndmin=ndmin, dtype=final_dtype) for obj in objs]
    res = self.concatenate(tuple(objs), axis=axis)
    if matrix:
        oldndim = res.ndim
        res = self.makemat(res)
        if oldndim == 1 and col:
            res = res.T
    return res

def create_tensor_descriptor_shim(tensor, block_sizes: list[int], new_api: bool=True):
    if <MASK>:
        return triton.tools.tensor_descriptor.TensorDescriptor.from_tensor(tensor, block_sizes)
    elif len(block_sizes) == 1:
        return triton.tools.experimental_descriptor.create_1d_tma_descriptor(tensor.data_ptr(), tensor.size(0), block_sizes[0], tensor.element_size())
    else:
        assert len(block_sizes) == 2
        return triton.tools.experimental_descriptor.create_2d_tma_descriptor(tensor.data_ptr(), tensor.size(0), tensor.size(1), block_sizes[0], block_sizes[1], tensor.element_size())

def _test(self, compression_type=None):
    test_filenames = self._createFiles(compression_type=compression_type)

    def dataset_fn(filenames, num_epochs, batch_size=None):
        repeat_dataset = readers.FixedLengthRecordDataset(filenames, self._record_bytes, self._header_bytes, self._footer_bytes, compression_type=compression_type).repeat(num_epochs)
        if <MASK>:
            return repeat_dataset.batch(batch_size)
        return repeat_dataset
    self.assertDatasetProduces(dataset_fn([test_filenames[0]], 1), expected_output=[self._record(0, i) for i in range(self._num_records)])
    self.assertDatasetProduces(dataset_fn([test_filenames[1]], 1), expected_output=[self._record(1, i) for i in range(self._num_records)])
    expected_output = []
    for j in range(self._num_files):
        expected_output.extend([self._record(j, i) for i in range(self._num_records)])
    self.assertDatasetProduces(dataset_fn(test_filenames, 1), expected_output=expected_output)
    get_next = self.getNext(dataset_fn(test_filenames, 10))
    for _ in range(10):
        for j in range(self._num_files):
            for i in range(self._num_records):
                self.assertEqual(self._record(j, i), self.evaluate(get_next()))
    with self.assertRaises(errors.OutOfRangeError):
        self.evaluate(get_next())
    get_next = self.getNext(dataset_fn(test_filenames, 10, self._num_records))
    for _ in range(10):
        for j in range(self._num_files):
            self.assertAllEqual([self._record(j, i) for i in range(self._num_records)], self.evaluate(get_next()))
    with self.assertRaises(errors.OutOfRangeError):
        self.evaluate(get_next())

def _isin(ar1, ar2, assume_unique=False, invert=False, *, kind=None):
    ar1 = np.asarray(ar1).ravel()
    ar2 = np.asarray(ar2).ravel()
    if ar2.dtype == object:
        ar2 = ar2.reshape(-1, 1)
    if kind not in {None, 'sort', 'table'}:
        raise ValueError(f"Invalid kind: '{kind}'. Please use None, 'sort' or 'table'.")
    is_int_arrays = all((ar.dtype.kind in ('u', 'i', 'b') for ar in (ar1, ar2)))
    use_table_method = is_int_arrays and kind in {None, 'table'}
    if use_table_method:
        if ar2.size == 0:
            if invert:
                return np.ones_like(ar1, dtype=bool)
            else:
                return np.zeros_like(ar1, dtype=bool)
        if ar1.dtype == bool:
            ar1 = ar1.astype(np.uint8)
        if <MASK>:
            ar2 = ar2.astype(np.uint8)
        ar2_min = int(np.min(ar2))
        ar2_max = int(np.max(ar2))
        ar2_range = ar2_max - ar2_min
        below_memory_constraint = ar2_range <= 6 * (ar1.size + ar2.size)
        range_safe_from_overflow = ar2_range <= np.iinfo(ar2.dtype).max
        if range_safe_from_overflow and (below_memory_constraint or kind == 'table'):
            if invert:
                outgoing_array = np.ones_like(ar1, dtype=bool)
            else:
                outgoing_array = np.zeros_like(ar1, dtype=bool)
            if invert:
                isin_helper_ar = np.ones(ar2_range + 1, dtype=bool)
                isin_helper_ar[ar2 - ar2_min] = 0
            else:
                isin_helper_ar = np.zeros(ar2_range + 1, dtype=bool)
                isin_helper_ar[ar2 - ar2_min] = 1
            basic_mask = (ar1 <= ar2_max) & (ar1 >= ar2_min)
            in_range_ar1 = ar1[basic_mask]
            if in_range_ar1.size == 0:
                return outgoing_array
            try:
                ar2_min = np.array(ar2_min, dtype=np.intp)
                dtype = np.intp
            except OverflowError:
                dtype = ar2.dtype
            out = np.empty_like(in_range_ar1, dtype=np.intp)
            outgoing_array[basic_mask] = isin_helper_ar[np.subtract(in_range_ar1, ar2_min, dtype=dtype, out=out, casting='unsafe')]
            return outgoing_array
        elif kind == 'table':
            raise RuntimeError("You have specified kind='table', but the range of values in `ar2` or `ar1` exceed the maximum integer of the datatype. Please set `kind` to None or 'sort'.")
    elif kind == 'table':
        raise ValueError("The 'table' method is only supported for boolean or integer arrays. Please select 'sort' or None for kind.")
    contains_object = ar1.dtype.hasobject or ar2.dtype.hasobject
    if len(ar2) < 10 * len(ar1) ** 0.145 or contains_object:
        if invert:
            mask = np.ones(len(ar1), dtype=bool)
            for a in ar2:
                mask &= ar1 != a
        else:
            mask = np.zeros(len(ar1), dtype=bool)
            for a in ar2:
                mask |= ar1 == a
        return mask
    if not assume_unique:
        (ar1, rev_idx) = np.unique(ar1, return_inverse=True)
        ar2 = np.unique(ar2)
    ar = np.concatenate((ar1, ar2))
    order = ar.argsort(kind='mergesort')
    sar = ar[order]
    if invert:
        bool_ar = sar[1:] != sar[:-1]
    else:
        bool_ar = sar[1:] == sar[:-1]
    flag = np.concatenate((bool_ar, [invert]))
    ret = np.empty(ar.shape, dtype=bool)
    ret[order] = flag
    if assume_unique:
        return ret[:len(ar1)]
    else:
        return ret[rev_idx]

def after_run(self, run_context, run_values):
    global_step = run_values.results + 1
    if <MASK>:
        step = run_context.session.run(self._global_step_tensor)
        if step >= self._last_step:
            run_context.request_stop()

def _print_Pow(self, expr: sympy.Expr) -> str:
    (base, exp) = expr.args
    if <MASK>:
        raise AssertionError(exp)
    exp = int(exp)
    if exp < 0:
        raise AssertionError(f'exponent must be non-negative, got {exp}')
    if exp > 0:
        return self.stringify([base] * exp, '*', PRECEDENCE['Mul'])
    return '1'

def _is_packable_linear(match):
    """
        Check if the node is supported for MKLDNN linear.
        """

    def is_const_or_cat_by_const(weight):
        if weight.op == 'get_attr':
            return True
        if weight.target != aten.cat.default:
            return False
        return all((arg.op == 'get_attr' for arg in weight.args[0]))
    linear_node = match.output_node()
    if linear_node.target == aten.addmm.default:
        alpha = linear_node.kwargs.get('alpha', 1.0)
        beta = linear_node.kwargs.get('beta', 1.0)
        if beta != 0.0 and beta != 1.0 or alpha != 1.0:
            return False
    weight_idx = 2 if linear_node.target == aten.addmm.default else 1
    if not is_const_or_cat_by_const(linear_node.args[weight_idx]):
        return False
    input_meta_value = linear_node.args[weight_idx - 1].meta.get('val')
    weight_meta_value = linear_node.args[weight_idx].meta.get('val')
    if <MASK>:
        return False
    if input_meta_value.dtype == torch.float64 or weight_meta_value.dtype == torch.float64:
        return False
    is_lp_weight = weight_meta_value.dtype in (torch.bfloat16, torch.float16)
    reduced_f32_matmul_enabled = torch.backends.mkldnn.matmul.fp32_precision in ['bf16', 'tf32']
    use_reduced_f32_for_fp32_weight = reduced_f32_matmul_enabled and weight_meta_value.dtype == torch.float32
    compute_with_lp = is_lp_weight or use_reduced_f32_for_fp32_weight
    if not compute_with_lp and (not mkldnn._is_mkldnn_acl_supported()) and (not torch._C.has_mkl):
        return False
    for meta_value in [input_meta_value, weight_meta_value]:
        if meta_value is None or meta_value.device.type != 'cpu' or meta_value.dim() != 2:
            return False
    if weight_idx == 2:
        bias_meta_value = linear_node.args[0].meta.get('val')
        if bias_meta_value is None or meta_value.device.type != 'cpu' or bias_meta_value.dim() != 1 or (bias_meta_value.size(0) != weight_meta_value.size(1)):
            return False
    device_type = input_meta_value.device.type
    if input_meta_value.dtype == torch.bfloat16 or weight_meta_value.dtype == torch.bfloat16:
        if not is_mkldnn_bf16_supported(device_type):
            return False
    if input_meta_value.dtype == torch.float16 or weight_meta_value.dtype == torch.float16:
        if not is_mkldnn_fp16_supported(device_type):
            return False
    return True

def copy(self, new_path: str) -> None:
    if <MASK>:
        return
    assert new_path.endswith('.debug'), new_path
    from filelock import FileLock
    try:
        with FileLock(f'{new_path}.lock'):
            if os.path.exists(new_path):
                shutil.rmtree(new_path)
            shutil.copytree(self._path, new_path)
    except OSError:
        log.warning('Failed to copy debug files from %s to %s', self._path, new_path)

def _wrap_results(result, dtype: np.dtype, fill_value=None):
    """wrap our results if needed"""
    if result is NaT:
        pass
    elif dtype.kind == 'M':
        if <MASK>:
            fill_value = iNaT
        if not isinstance(result, np.ndarray):
            assert not isna(fill_value), 'Expected non-null fill_value'
            if result == fill_value:
                result = np.nan
            if isna(result):
                result = np.datetime64('NaT', 'ns').astype(dtype)
            else:
                result = np.int64(result).view(dtype)
            result = result.astype(dtype, copy=False)
        else:
            result = result.astype(dtype)
    elif dtype.kind == 'm':
        if not isinstance(result, np.ndarray):
            if result == fill_value or np.isnan(result):
                result = np.timedelta64('NaT').astype(dtype)
            elif np.fabs(result) > lib.i8max:
                raise ValueError('overflow in timedelta operation')
            else:
                result = np.int64(result).astype(dtype, copy=False)
        else:
            result = result.astype('m8[ns]').view(dtype)
    return result

def _op_to_colocate_with(v, graph) -> tuple[Optional[Operation], Optional[Callable[[], None]]]:
    """Operation object corresponding to v to use for colocation constraints."""
    if <MASK>:
        return (None, None)
    if isinstance(v, Operation):
        return (v, None)
    if hasattr(v, 'handle') and isinstance(v.handle, tensor_lib.Tensor):
        device_only_candidate = lambda : None
        device_only_candidate.device = v.device
        device_only_candidate.name = v.name
        if graph.building_function:
            return (graph.capture(v.handle).op, device_only_candidate)
        else:
            return (v.handle.op, device_only_candidate)
    if isinstance(v, EagerTensor) and (not context.executing_eagerly()):
        return (convert_to_tensor(v, as_ref=True).op, None)
    elif isinstance(v, internal.NativeObject):
        return (v.op, None)
    else:
        return (convert_to_tensor(v, as_ref=True).op, None)

def swap_submodule(module: 'torch.nn.Module', name: str, submodule: 'torch.nn.Module') -> 'torch.nn.Module':
    if not isinstance(module, torch.nn.Module):
        raise TypeError(f'{module} is not an instance of torch.nn.Module')
    if not isinstance(submodule, torch.nn.Module):
        raise TypeError(f'{submodule} is not an instance of torch.nn.Module')
    if '.' in name:
        raise KeyError('submodule name can\'t contain "."')
    if name == '':
        raise KeyError('submodule name can\'t be empty string ""')
    if <MASK>:
        raise KeyError(f'submodule {name} does not exist')
    orig_submodule = module._modules[name]
    if not isinstance(orig_submodule, torch.nn.Module):
        raise TypeError(f'{name} attribute is not an instance of torch.nn.Module')
    module._modules[name] = submodule
    return orig_submodule

def _populate_recipient_maps(self):
    """Populate the map from node name to recipient(s) of its output(s).

    This method also populates the input map based on reversed ref edges.
    """
    for node in self._node_inputs:
        inputs = self._node_inputs[node]
        for inp in inputs:
            inp = get_node_name(inp)
            if inp not in self._node_recipients:
                self._node_recipients[inp] = []
            self._node_recipients[inp].append(node)
            if inp in self._ref_args:
                if inp not in self._node_reversed_ref_inputs:
                    self._node_reversed_ref_inputs[inp] = []
                self._node_reversed_ref_inputs[inp].append(node)
    for node in self._node_ctrl_inputs:
        ctrl_inputs = self._node_ctrl_inputs[node]
        for ctrl_inp in ctrl_inputs:
            if <MASK>:
                continue
            if ctrl_inp not in self._node_ctrl_recipients:
                self._node_ctrl_recipients[ctrl_inp] = []
            self._node_ctrl_recipients[ctrl_inp].append(node)

def _call(self, device, args):
    """Passes `args` to `self._func`, which is executed eagerly."""
    with context.eager_mode():
        ret = self._func(*args)
        device_name = device
        if device_name is None:
            device_name = '/job:localhost/replica:0/task:0/device:CPU:0'
        with ops.device(device):
            if isinstance(ret, (tuple, list)):
                outputs = [_maybe_copy_to_context_device(self._convert(x, dtype=dtype), device_name) for (x, dtype) in zip(ret, self._out_dtypes)]
            elif <MASK>:
                outputs = None
            else:
                outputs = _maybe_copy_to_context_device(self._convert(ret, dtype=self._out_dtypes[0]), device_name)
    return outputs

def modified_arguments(self, kwargs, requested_parameters):
    strategy = None
    for (_, v) in kwargs.items():
        if isinstance(v, NamedDistribution):
            if strategy is not None and _num_total_workers(v.has_chief, v.num_workers) > 1:
                raise ValueError('Only support one NamedDistribution for multi workertests.')
            strategy = v
    if strategy:
        has_chief = strategy.has_chief
        num_workers = strategy.num_workers
        runner = strategy.runner
        share_gpu = strategy.share_gpu
        num_ps = strategy.num_ps
        if 'has_chief' in kwargs and kwargs['has_chief'] != has_chief:
            raise ValueError('both has_chief and strategy specified but are not compatible')
        if <MASK>:
            raise ValueError('both num_workers and strategy specified but are not compatible')
    else:
        has_chief = kwargs.get('has_chief', False)
        num_workers = kwargs.get('num_workers', 1)
        runner = kwargs.get('runner', None)
        share_gpu = kwargs.get('share_gpu', True)
        num_ps = kwargs.get('num_ps', 0)
    update = {}
    if 'has_chief' in requested_parameters:
        update['has_chief'] = has_chief
    if 'num_workers' in requested_parameters:
        update['num_workers'] = num_workers
    if 'runner' in requested_parameters:
        update['runner'] = runner
    if 'share_gpu' in requested_parameters:
        update['share_gpu'] = share_gpu
    if 'num_ps' in requested_parameters:
        update['num_ps'] = num_ps
    return update

def _infer_device_type(*args):
    device_types = []

    def add_device_types(arg):
        nonlocal device_types
        if isinstance(arg, torch.Tensor) and arg.device.type != 'cpu':
            device_types.append(arg.device.type)
    tree_map(add_device_types, args)
    device_types_set = set(device_types)
    if len(device_types_set) > 1:
        warnings.warn(f'Tensor arguments, excluding CPU tensors, are detected on at least two types of devices. Device state will only be saved for devices of a single device type, and the remaining devices will be ignored. Consequently, if any checkpointed functions involve randomness, this may result in incorrect gradients. (Note that if CUDA devices are among the devices detected, it will be prioritized; otherwise, the first device encountered will be selected.)\nDevice types: {sorted(device_types_set)} first device type: {device_types[0]}')
    if len(device_types) == 0:
        return DefaultDeviceType.get_device_type()
    elif <MASK>:
        return 'cuda'
    else:
        return device_types[0]

def deconstruct(self):
    (path, args, kwargs) = super().deconstruct()
    if <MASK>:
        kwargs['fields'] = self.fields
    if self.condition:
        kwargs['condition'] = self.condition
    if self.deferrable:
        kwargs['deferrable'] = self.deferrable
    if self.include:
        kwargs['include'] = self.include
    if self.opclasses:
        kwargs['opclasses'] = self.opclasses
    if self.nulls_distinct is not None:
        kwargs['nulls_distinct'] = self.nulls_distinct
    return (path, self.expressions, kwargs)

def get_code_state() -> defaultdict[CodeId, CodeState]:
    global _CODE_STATE, _INIT_CODE_STATE
    if _CODE_STATE is not None:
        return _CODE_STATE
    _CODE_STATE = defaultdict(CodeState)
    cache_key = get_cache_key()
    if cache_key is None:
        return _CODE_STATE
    local_code_state = get_local_code_state(cache_key)
    if local_code_state is None:
        get_remote_code_state(cache_key)
    if <MASK>:
        extra_read_key = get_extra_cache_key(sticky_read)
        if extra_read_key is not None:
            get_extra_remote_code_state(extra_read_key)
    log.info('get_code_state using default')
    assert _CODE_STATE is not None
    return _CODE_STATE

def assert_input_compatibility(input_spec, inputs, layer_name):
    """Checks compatibility between the layer and provided inputs.

  This checks that the tensor(s) `inputs` verify the input assumptions
  of a layer (if any). If not, a clear and actional exception gets raised.

  Args:
      input_spec: An InputSpec instance, list of InputSpec instances, a nested
          structure of InputSpec instances, or None.
      inputs: Input tensor, list of input tensors, or a nested structure of
          input tensors.
      layer_name: String, name of the layer (for error message formatting).

  Raises:
      ValueError: in case of mismatch between
          the provided inputs and the expectations of the layer.
  """
    if not input_spec:
        return
    input_spec = nest.flatten(input_spec)
    if isinstance(inputs, dict):
        names = [spec.name for spec in input_spec]
        if all(names):
            list_inputs = []
            for name in names:
                if name not in inputs:
                    raise ValueError('Missing data for input "%s". You passed a data dictionary with keys %s. Expected the following keys: %s' % (name, list(inputs.keys()), names))
                list_inputs.append(inputs[name])
            inputs = list_inputs
    inputs = nest.flatten(inputs)
    for x in inputs:
        if not hasattr(x, 'shape'):
            raise TypeError('Inputs to a layer should be tensors. Got: %s' % (x,))
    if len(inputs) != len(input_spec):
        raise ValueError('Layer ' + layer_name + ' expects ' + str(len(input_spec)) + ' input(s), but it received ' + str(len(inputs)) + ' input tensors. Inputs received: ' + str(inputs))
    for (input_index, (x, spec)) in enumerate(zip(inputs, input_spec)):
        if spec is None:
            continue
        shape = tensor_shape.TensorShape(x.shape)
        if shape.rank is None:
            return
        if spec.ndim is not None and (not spec.allow_last_axis_squeeze):
            ndim = shape.rank
            if ndim != spec.ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected ndim=' + str(spec.ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.max_ndim is not None:
            ndim = x.shape.rank
            if ndim is not None and ndim > spec.max_ndim:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected max_ndim=' + str(spec.max_ndim) + ', found ndim=' + str(ndim))
        if spec.min_ndim is not None:
            ndim = x.shape.rank
            if <MASK>:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: : expected min_ndim=' + str(spec.min_ndim) + ', found ndim=' + str(ndim) + '. Full shape received: ' + str(tuple(shape)))
        if spec.dtype is not None:
            if x.dtype.name != spec.dtype:
                raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected dtype=' + str(spec.dtype) + ', found dtype=' + str(x.dtype))
        shape_as_list = shape.as_list()
        if spec.axes:
            for (axis, value) in spec.axes.items():
                if hasattr(value, 'value'):
                    value = value.value
                if value is not None and shape_as_list[int(axis)] not in {value, None}:
                    raise ValueError('Input ' + str(input_index) + ' of layer ' + layer_name + ' is incompatible with the layer: expected axis ' + str(axis) + ' of input shape to have value ' + str(value) + ' but received input with shape ' + display_shape(x.shape))
        if spec.shape is not None and shape.rank is not None:
            spec_shape = spec.shape
            if spec.allow_last_axis_squeeze:
                if shape_as_list and shape_as_list[-1] == 1:
                    shape_as_list = shape_as_list[:-1]
                if spec_shape and spec_shape[-1] == 1:
                    spec_shape = spec_shape[:-1]
            for (spec_dim, dim) in zip(spec_shape, shape_as_list):
                if spec_dim is not None and dim is not None:
                    if spec_dim != dim:
                        raise ValueError('Input ' + str(input_index) + ' is incompatible with layer ' + layer_name + ': expected shape=' + str(spec.shape) + ', found shape=' + display_shape(x.shape))

def _global_report_benchmark(name, iters=None, cpu_time=None, wall_time=None, throughput=None, extras=None, metrics=None):
    """Method for recording a benchmark directly.

  Args:
    name: The BenchmarkEntry name.
    iters: (optional) How many iterations were run
    cpu_time: (optional) Total cpu time in seconds
    wall_time: (optional) Total wall time in seconds
    throughput: (optional) Throughput (in MB/s)
    extras: (optional) Dict mapping string keys to additional benchmark info.
    metrics: (optional) A list of dict representing metrics generated by the
      benchmark. Each dict should contain keys 'name' and'value'. A dict
      can optionally contain keys 'min_value' and 'max_value'.

  Raises:
    TypeError: if extras is not a dict.
    IOError: if the benchmark output file already exists.
  """
    logging.info('Benchmark [%s] iters: %d, wall_time: %g, cpu_time: %g,throughput: %g, extras: %s, metrics: %s', name, iters if iters is not None else -1, wall_time if wall_time is not None else -1, cpu_time if cpu_time is not None else -1, throughput if throughput is not None else -1, str(extras) if extras else 'None', str(metrics) if metrics else 'None')
    entries = test_log_pb2.BenchmarkEntries()
    entry = entries.entry.add()
    entry.name = name
    if iters is not None:
        entry.iters = iters
    if cpu_time is not None:
        entry.cpu_time = cpu_time
    if <MASK>:
        entry.wall_time = wall_time
    if throughput is not None:
        entry.throughput = throughput
    if extras is not None:
        if not isinstance(extras, dict):
            raise TypeError('extras must be a dict')
        for (k, v) in extras.items():
            if isinstance(v, numbers.Number):
                entry.extras[k].double_value = v
            else:
                entry.extras[k].string_value = str(v)
    if metrics is not None:
        if not isinstance(metrics, list):
            raise TypeError('metrics must be a list')
        for metric in metrics:
            if 'name' not in metric:
                raise TypeError("metric must has a 'name' field")
            if 'value' not in metric:
                raise TypeError("metric must has a 'value' field")
            metric_entry = entry.metrics.add()
            metric_entry.name = metric['name']
            metric_entry.value = metric['value']
            if 'min_value' in metric:
                metric_entry.min_value.value = metric['min_value']
            if 'max_value' in metric:
                metric_entry.max_value.value = metric['max_value']
    test_env = os.environ.get(TEST_REPORTER_TEST_ENV, None)
    if test_env is None:
        print(str(entries))
        return
    serialized_entry = entries.SerializeToString()
    mangled_name = name.replace('/', '__')
    output_path = '%s%s' % (test_env, mangled_name)
    if gfile.Exists(output_path):
        raise IOError('File already exists: %s' % output_path)
    with gfile.GFile(output_path, 'wb') as out:
        out.write(serialized_entry)

def _validate_for_predict(self, X):
    check_is_fitted(self)
    if not callable(self.kernel):
        X = validate_data(self, X, accept_sparse='csr', dtype=np.float64, order='C', accept_large_sparse=False, reset=False)
    if self._sparse and (not sp.issparse(X)):
        X = sp.csr_matrix(X)
    if self._sparse:
        X.sort_indices()
    if sp.issparse(X) and (not self._sparse) and (not callable(self.kernel)):
        raise ValueError('cannot use sparse input in %r trained on dense data' % type(self).__name__)
    if self.kernel == 'precomputed':
        if X.shape[1] != self.shape_fit_[0]:
            raise ValueError('X.shape[1] = %d should be equal to %d, the number of samples at training time' % (X.shape[1], self.shape_fit_[0]))
    sv = self.support_vectors_
    if <MASK>:
        raise ValueError(f'The internal representation of {self.__class__.__name__} was altered')
    return X

@torch.library.impl(lib, 'fused_all_gather_matmul', 'Meta')
def _fused_all_gather_matmul_fallback(A_shard: torch.Tensor, Bs: list[torch.Tensor], gather_dim: int, group_name: str, *, return_A: bool=True) -> tuple[torch.Tensor | None, list[torch.Tensor]]:
    group_size = c10d._get_group_size_by_name(group_name)
    A = torch.ops._c10d_functional.all_gather_into_tensor(A_shard.contiguous(), group_size, group_name)
    A = torch.ops._c10d_functional.wait_tensor(A)
    if gather_dim == A.ndim - 1 or gather_dim == -1:
        A_splits = A.chunk(group_size)
        A_mm = torch.cat(A_splits, dim=-1)
        res = [torch.matmul(A_mm, B) for B in Bs]
        if <MASK>:
            return (A_mm, res)
        else:
            return (None, res)
    A = A.view(group_size, *A_shard.shape).movedim(gather_dim + 1, 1).flatten(0, 1)
    res = [torch.matmul(A, B).movedim(0, gather_dim) for B in Bs]
    if return_A:
        return (A.movedim(0, gather_dim), res)
    else:
        return (None, res)

@compatibility(is_backward_compatible=False)
def get_acc_ops_name(k):
    if isinstance(k, str):
        return k
    elif <MASK>:
        return f'acc_ops.{k.__name__}'
    else:
        module = k.__module__.replace('torch._ops', 'torch.ops')
        return f"{(module if module else '')}.{k.__name__}"

def constant_to_optimal_zero(self, y_true, sample_weight=None):
    if self.closs.power == 0:
        return HalfSquaredError().constant_to_optimal_zero(y_true=y_true, sample_weight=sample_weight)
    elif self.closs.power == 1:
        return HalfPoissonLoss().constant_to_optimal_zero(y_true=y_true, sample_weight=sample_weight)
    elif <MASK>:
        return HalfGammaLoss().constant_to_optimal_zero(y_true=y_true, sample_weight=sample_weight)
    else:
        p = self.closs.power
        term = np.power(np.maximum(y_true, 0), 2 - p) / (1 - p) / (2 - p)
        if sample_weight is not None:
            term *= sample_weight
        return term

def _partition_axes(self):
    if <MASK>:
        return [0]
    else:
        return [i for (i, p) in enumerate(self._partitions) if p > 1]

def _log_tensors(self, tensor_values):
    original = np.get_printoptions()
    np.set_printoptions(suppress=True)
    (elapsed_secs, _) = self._timer.update_last_triggered_step(self._iter_count)
    if <MASK>:
        logging.info(self._formatter(tensor_values))
    else:
        stats = []
        for tag in self._tag_order:
            stats.append('%s = %s' % (tag, tensor_values[tag]))
        if elapsed_secs is not None:
            logging.info('%s (%.3f sec)', ', '.join(stats), elapsed_secs)
        else:
            logging.info('%s', ', '.join(stats))
    np.set_printoptions(**original)

def _write_ninja_file_to_build_library(path, name, sources, extra_cflags, extra_cuda_cflags, extra_sycl_cflags, extra_ldflags, extra_include_paths, with_cuda, with_sycl, is_standalone) -> None:
    extra_cflags = [flag.strip() for flag in extra_cflags]
    extra_cuda_cflags = [flag.strip() for flag in extra_cuda_cflags]
    extra_sycl_cflags = [flag.strip() for flag in extra_sycl_cflags]
    extra_ldflags = [flag.strip() for flag in extra_ldflags]
    extra_include_paths = [flag.strip() for flag in extra_include_paths]
    user_includes = [os.path.abspath(file) for file in extra_include_paths]
    if with_cuda:
        system_includes = include_paths('cuda')
    else:
        system_includes = include_paths('cpu')
    python_include_path = sysconfig.get_path('include', scheme='nt' if IS_WINDOWS else 'posix_prefix')
    if python_include_path is not None:
        system_includes.append(python_include_path)
    common_cflags = []
    if not is_standalone:
        common_cflags.append(f'-DTORCH_EXTENSION_NAME={name}')
        common_cflags.append('-DTORCH_API_INCLUDE_EXTENSION_H')
    if IS_WINDOWS:
        common_cflags += [f'-I{include}' for include in user_includes + system_includes]
    else:
        common_cflags += [f'-I{shlex.quote(include)}' for include in user_includes]
        common_cflags += [f'-isystem {shlex.quote(include)}' for include in system_includes]
    if IS_WINDOWS:
        COMMON_HIP_FLAGS.extend(['-fms-runtime-lib=dll'])
        cflags = common_cflags + ['/std:c++17'] + extra_cflags
        cflags += COMMON_MSVC_FLAGS + (COMMON_HIP_FLAGS if IS_HIP_EXTENSION else [])
        cflags = _nt_quote_args(cflags)
    else:
        cflags = common_cflags + ['-fPIC', '-std=c++17'] + extra_cflags
    if with_cuda and IS_HIP_EXTENSION:
        cuda_flags = ['-DWITH_HIP'] + common_cflags + extra_cflags + COMMON_HIP_FLAGS + COMMON_HIPCC_FLAGS
        cuda_flags = cuda_flags + ['-std=c++17']
        cuda_flags += _get_rocm_arch_flags(cuda_flags)
        cuda_flags += extra_cuda_cflags
        if IS_WINDOWS:
            cuda_flags = _nt_quote_args(cuda_flags)
    elif with_cuda:
        cuda_flags = common_cflags + COMMON_NVCC_FLAGS + _get_cuda_arch_flags(extra_cuda_cflags)
        if IS_WINDOWS:
            for flag in COMMON_MSVC_FLAGS:
                cuda_flags = ['-Xcompiler', flag] + cuda_flags
            for ignore_warning in MSVC_IGNORE_CUDAFE_WARNINGS:
                cuda_flags = ['-Xcudafe', '--diag_suppress=' + ignore_warning] + cuda_flags
            cuda_flags = cuda_flags + ['-std=c++17']
            cuda_flags = _nt_quote_args(cuda_flags)
            cuda_flags += _nt_quote_args(extra_cuda_cflags)
        else:
            cuda_flags += ['--compiler-options', "'-fPIC'"]
            cuda_flags += extra_cuda_cflags
            if not any((flag.startswith('-std=') for flag in cuda_flags)):
                cuda_flags.append('-std=c++17')
            cc_env = os.getenv('CC')
            if <MASK>:
                cuda_flags = ['-ccbin', cc_env] + cuda_flags
    else:
        cuda_flags = None
    if with_sycl:
        sycl_cflags = cflags + _COMMON_SYCL_FLAGS
        sycl_cflags += extra_sycl_cflags
        _append_sycl_targets_if_missing(sycl_cflags)
        _append_sycl_std_if_no_std_present(sycl_cflags)
        host_cflags = cflags
        icpx_version = _get_icpx_version()
        if int(icpx_version) < 20250200:
            host_cflags = [item.replace('\\"', '\\\\"') for item in host_cflags]
        host_cflags = ' '.join(host_cflags)
        sycl_cflags += _wrap_sycl_host_flags(host_cflags)
        sycl_dlink_post_cflags = _SYCL_DLINK_FLAGS.copy()
        sycl_dlink_post_cflags += _get_sycl_device_flags(sycl_cflags)
    else:
        sycl_cflags = None
        sycl_dlink_post_cflags = None

    def object_file_path(source_file: str) -> str:
        file_name = os.path.splitext(os.path.basename(source_file))[0]
        if _is_cuda_file(source_file) and with_cuda:
            target = f'{file_name}.cuda.o'
        elif _is_sycl_file(source_file) and with_sycl:
            target = f'{file_name}.sycl.o'
        else:
            target = f'{file_name}.o'
        return target
    objects = [object_file_path(src) for src in sources]
    ldflags = ([] if is_standalone else [SHARED_FLAG]) + extra_ldflags
    if IS_MACOS:
        ldflags.append('-undefined dynamic_lookup')
    elif IS_WINDOWS:
        ldflags = _nt_quote_args(ldflags)
    ext = EXEC_EXT if is_standalone else LIB_EXT
    library_target = f'{name}{ext}'
    _write_ninja_file(path=path, cflags=cflags, post_cflags=None, cuda_cflags=cuda_flags, cuda_post_cflags=None, cuda_dlink_post_cflags=None, sycl_cflags=sycl_cflags, sycl_post_cflags=[], sycl_dlink_post_cflags=sycl_dlink_post_cflags, sources=sources, objects=objects, ldflags=ldflags, library_target=library_target, with_cuda=with_cuda, with_sycl=with_sycl)

def conjugate_sample_inputs(self, device, dtype, requires_grad=False, **kwargs):
    """Returns an iterable of SampleInputs but with the tensor input or first
        tensor in a sequence input conjugated.
        """
    set_seed = kwargs.pop('set_seed', True)
    use_subtests = kwargs.pop('use_subtests', False)
    samples = self.sample_inputs_func(self, device, dtype, requires_grad, **kwargs)
    conj_samples = list(samples)

    def conjugate(tensor):
        _requires_grad = tensor.requires_grad
        tensor = tensor.conj()
        return tensor.requires_grad_(_requires_grad)
    for (i, sample) in enumerate(samples):
        sample = conj_samples[i]
        if <MASK>:
            sample.input = conjugate(sample.input)
        else:
            sample.input[0] = conjugate(sample.input[0])
    return TrackedInputIter(iter(conj_samples), 'conjugate sample input', item_callback=self._sample_callback_fn(use_subtests, device), set_seed=set_seed, restrict_to_index=OPINFO_SAMPLE_INPUT_INDEX)

def _check_correct_val(val):
    if val is None:
        return True
    elif isinstance(val, (int, bool, str, float)):
        return True
    elif isinstance(val, (torch.memory_format, torch.dtype, torch.device, torch.layout)):
        return True
    elif <MASK>:
        return True
    elif isinstance(val, (SymInt, SymFloat, SymBool)):
        return True
    elif isinstance(val, CustomObjArgument):
        return True
    elif isinstance(val, Iterable):
        return all((_check_correct_val(x) for x in val))
    return False

def __init__(self, filepath, monitor='val_loss', verbose=0, save_best_only=False, save_weights_only=False, mode='auto', save_freq='epoch', options=None, **kwargs):
    super(ModelCheckpoint, self).__init__()
    self._supports_tf_logs = True
    self.monitor = monitor
    self.verbose = verbose
    self.filepath = path_to_string(filepath)
    self.save_best_only = save_best_only
    self.save_weights_only = save_weights_only
    self.save_freq = save_freq
    self.epochs_since_last_save = 0
    self._batches_seen_since_last_saving = 0
    self._last_batch_seen = 0
    if save_weights_only:
        if options is None or isinstance(options, checkpoint_options_lib.CheckpointOptions):
            self._options = options or checkpoint_options_lib.CheckpointOptions()
        else:
            raise TypeError('If save_weights_only is True, then `options` must be either None or a tf.train.CheckpointOptions')
    elif options is None or isinstance(options, save_options_lib.SaveOptions):
        self._options = options or save_options_lib.SaveOptions()
    else:
        raise TypeError('If save_weights_only is False, then `options` must beeither None or a tf.saved_model.SaveOptions')
    if <MASK>:
        self.load_weights_on_restart = kwargs['load_weights_on_restart']
        logging.warning('`load_weights_on_restart` argument is deprecated. Please use `model.load_weights()` for loading weights before the start of `model.fit()`.')
    else:
        self.load_weights_on_restart = False
    if 'period' in kwargs:
        self.period = kwargs['period']
        logging.warning('`period` argument is deprecated. Please use `save_freq` to specify the frequency in number of batches seen.')
    else:
        self.period = 1
    if mode not in ['auto', 'min', 'max']:
        logging.warning('ModelCheckpoint mode %s is unknown, fallback to auto mode.', mode)
        mode = 'auto'
    if mode == 'min':
        self.monitor_op = np.less
        self.best = np.inf
    elif mode == 'max':
        self.monitor_op = np.greater
        self.best = -np.inf
    elif 'acc' in self.monitor or self.monitor.startswith('fmeasure'):
        self.monitor_op = np.greater
        self.best = -np.inf
    else:
        self.monitor_op = np.less
        self.best = np.inf
    if self.save_freq != 'epoch' and (not isinstance(self.save_freq, int)):
        raise ValueError('Unrecognized save_freq: {}'.format(self.save_freq))
    self._chief_worker_only = False

def __le__(self, other):
    if <MASK>:
        return sympy.true
    elif other is S.IntInfinity:
        return sympy.true
    else:
        return sympy.false

def shape_div(a: IntTuple, b: IntTuple) -> IntTuple:
    if is_tuple(a):
        if <MASK>:
            assert len(a) == len(b)
            return tuple((shape_div(x, y) for (x, y) in zip(a, b)))
        else:
            r = []
            for v in a:
                r.append(shape_div(v, b))
                b = shape_div(b, product(v))
            return tuple(r)
    elif is_tuple(b):
        return shape_div(a, product(b))
    else:
        assert a % b == 0 or b % a == 0
        return (a + b - 1) // b

@classmethod
def do_bisect(cls, fn: Callable[[], bool], cli_interface: bool=False) -> Optional[BisectionResult]:
    """
        Run fn repeatedly attempting to bisect torch.compile. fn should return True on success and False on failure.
        """
    if not cli_interface:
        bisection_enabled_orig = cls.bisection_enabled
        cls.delete_bisect_status()
        cls.bisection_enabled = True
        cls.in_process_cache = tempfile.mkdtemp()

        def cleanup() -> None:
            cls.bisection_enabled = bisection_enabled_orig
            cls.delete_bisect_status()
            cls.in_process_cache = None
        cleanup_handler = atexit.register(cleanup)

        class DisableBisect:

            def __del__(self) -> None:
                cleanup()
                atexit.unregister(cleanup_handler)
        _cleanup = DisableBisect()
    curr_backend = cls.get_backend()
    curr_subsystem_name = cls.get_subsystem()
    if not curr_backend:
        cls.initialize_system()
        curr_backend = cls.get_backend()
        assert curr_backend is not None
        curr_subsystem_name = cls.get_subsystem()
    curr_subsystem = cls.get_subsystem_object(curr_backend, curr_subsystem_name) if curr_subsystem_name is not None else None
    while True:
        assert curr_backend is not None
        reset_counters()
        if curr_subsystem:
            result = cls.process_subsystem(curr_backend, curr_subsystem, fn, cli_interface=cli_interface)
            if result:
                curr_subsystem = cls.get_subsystem_object(curr_backend, cls.get_subsystem())
                if isinstance(curr_subsystem, BinarySubsystem):
                    return BisectionResult(curr_backend, curr_subsystem.name, 0, curr_subsystem.name)
                (low, _) = cls.get_bisect_range(curr_backend, curr_subsystem.name)
                return BisectionResult(curr_backend, curr_subsystem.name, low, call_counter_debug_info.get(low))
            next_subsystem = cls.advance_subsystem(curr_backend, curr_subsystem)
            if not next_subsystem:
                print(f'The issue is in the {curr_backend} system, but could not identify subsystem.')
                assert curr_backend is not None
                return BisectionResult(curr_backend)
            curr_subsystem = next_subsystem
        elif <MASK>:
            next_backend = cls.advance_backend(curr_backend)
            if not next_backend:
                print('All systems have been checked.')
                return None
            curr_backend = next_backend
        else:
            current_subsystems = BACKENDS[curr_backend]
            if current_subsystems:
                curr_subsystem = current_subsystems[0]
                cls.update_bisect_status(curr_backend, curr_subsystem.name)
                cls.update_run_state(curr_backend, curr_subsystem, 'test_disable')
                print(f'The issue is in the {curr_backend} system. Moving to the first subsystem: {curr_subsystem}')
            else:
                print(f'The issue is in the {curr_backend} system.')
                return BisectionResult(curr_backend)
        if cli_interface:
            sys.exit(0)

def cpp_scratch(self, idx: int, workspace: TritonScratchWorkspace, prefix: Optional[str]=None) -> Optional[tuple[list[str], str]]:
    prefix = f'{prefix}_' if prefix else ''
    var_name = f'{prefix}scratch_{idx}'
    if <MASK>:
        size_array = f'int64_t {var_name}_size[] = {{{workspace.size}}};'
        stride_array = f'int64_t {var_name}_stride[] = {{1}};'
        device_type = 'cached_torch_device_type_cuda'
        device_idx = 'device_idx_'
        return ([f'{size_array}', f'{stride_array}', f'AtenTensorHandle {var_name}_handle;', f'AOTI_TORCH_ERROR_CODE_CHECK(aoti_torch_empty_strided(1, {var_name}_size, {var_name}_stride, {workspace.generate_dtype_str()}, {device_type}, {device_idx}, &{var_name}_handle));', f'RAIIAtenTensorHandle {var_name}_tensor({var_name}_handle);', f'CUdeviceptr {var_name} = reinterpret_cast<CUdeviceptr>({var_name}_tensor.data_ptr());'], var_name)
    else:
        return ([f'CUdeviceptr {var_name} = 0;'], var_name)

def get_all_dtypes(include_half=True, include_bfloat16=True, include_bool=True, include_complex=True, include_complex32=False, include_qint=False) -> list[torch.dtype]:
    dtypes = get_all_int_dtypes() + get_all_fp_dtypes(include_half=include_half, include_bfloat16=include_bfloat16)
    if include_bool:
        dtypes.append(torch.bool)
    if include_complex:
        dtypes += get_all_complex_dtypes(include_complex32)
    if <MASK>:
        dtypes += get_all_qint_dtypes()
    return dtypes

def _initialize(self):
    """Resolve the Keras version to use and initialize the loader."""
    self._tfll_initialized = True
    package_name = None
    keras_version = None
    if os.environ.get('TF_USE_LEGACY_KERAS', None) in ('true', 'True', '1'):
        try:
            import tf_keras
            keras_version = 'tf_keras'
            if <MASK>:
                package_name = 'tf_keras.api._v1.keras'
            else:
                package_name = 'tf_keras.api._v2.keras'
        except ImportError:
            logging.warning('Your environment has TF_USE_LEGACY_KERAS set to True, but you do not have the tf_keras package installed. You must install it in order to use the legacy tf.keras. Install it via: `pip install tf_keras`')
    else:
        try:
            import keras
            if keras.__version__.startswith('3.'):
                keras_version = 'keras_3'
                package_name = 'keras._tf_keras.keras'
            else:
                keras_version = 'keras_2'
                if self._tfll_mode == 'v1':
                    package_name = 'keras.api._v1.keras'
                else:
                    package_name = 'keras.api._v2.keras'
        except ImportError:
            raise ImportError('Keras cannot be imported. Check that it is installed.')
    self._tfll_keras_version = keras_version
    if keras_version is not None:
        if self._tfll_submodule is not None:
            package_name += '.' + self._tfll_submodule
        super().__init__(self._tfll_name, self._tfll_parent_module_globals, package_name)
    else:
        raise ImportError('Keras cannot be imported. Check that it is installed.')

@classmethod
def generate_halide_async(cls, meta: HalideMeta, source_code: str, submit_fn: Any=None) -> Callable[[], Any]:
    dirpath = Path(get_path(code_hash(source_code, extra=repr((cls.config_hash(), meta))), 'halide')[2])
    os.makedirs(dirpath, exist_ok=True)
    wait_for_compile = None
    genfile = str(dirpath / 'generate_kernel.py')
    libfile = str(dirpath / 'halide_kernel.a')
    headerfile = str(dirpath / 'halide_kernel.h')
    donefile = str(dirpath / 'done')
    lockfile = str(dirpath / 'lock')
    need_compile = not os.path.exists(donefile)
    jobs: list[Any] = []
    if need_compile:
        write_atomic(genfile, source_code)
        cmd = [sys.executable, genfile, '-g', 'kernel', '-o', f'{dirpath}', '-f', 'halide_kernel', '-e', 'static_library,h,schedule']
        if meta.scheduler:
            cmd.extend(['-p', cls.find_libautoschedule(meta.scheduler)])
        cmd.extend(meta.args())
        jobs.append(functools.partial(subprocess.check_call, cmd))
    binding_types = [arg.bindings_type() for arg in meta.argtypes if arg.alias_of is None]
    if <MASK>:
        binding_types.append('uintptr_t')
    bindings_future = cls.load_pybinding_async(binding_types, cls._codegen_glue(meta, headerfile), extra_flags=(libfile, cls.build_standalone_runtime()), submit_fn=jobs.append if need_compile else None, device_type='cuda' if meta.is_cuda() else 'cpu')
    if need_compile:
        jobs.append(functools.partial(touch, donefile))
        task = functools.partial(_worker_task_halide, lockfile, jobs)
        if submit_fn:
            wait_for_compile = submit_fn(task).result
        else:
            task()

    def load() -> Callable[[], Any]:
        if wait_for_compile:
            wait_for_compile()
        return bindings_future()
    return load

def from_tensors(self, tensors):
    if self._placeholder_type is None:
        raise ValueError('Packing serialized Dict is not supported.')
    sorted_traversal = {key: self.mapping[key].from_tensors(tensors) for key in sorted(self.mapping)}
    if <MASK>:
        return {key: sorted_traversal[key] for key in self.mapping}
    return self._placeholder_type(((key, sorted_traversal[key]) for key in self.mapping))

def __init__(self, enabled=True, *, use_cuda=False, use_device=None, record_shapes=False, with_flops=False, profile_memory=False, with_stack=False, with_modules=False, use_kineto=False, use_cpu=True, experimental_config=None, acc_events=False, custom_trace_id_callback=None):
    self.enabled: bool = enabled
    if not self.enabled:
        return
    self.use_cuda = use_cuda
    if self.use_cuda:
        warn("The attribute `use_cuda` will be deprecated soon, please use ``use_device = 'cuda'`` instead.", FutureWarning, stacklevel=2)
        self.use_device: Optional[str] = 'cuda'
    else:
        self.use_device = use_device
    self._function_events: Optional[EventList] = None
    self._old_function_events: Optional[EventList] = None
    self._needs_processing = False
    self.entered = False
    self.record_shapes = record_shapes
    self.with_flops = with_flops
    self.record_shapes |= self.with_flops
    self.profile_memory = profile_memory
    self.with_stack = with_stack
    self.with_modules = with_modules
    self.use_cpu = use_cpu
    self.acc_events = acc_events
    if experimental_config is None:
        experimental_config = _ExperimentalConfig()
    self.experimental_config = experimental_config
    self.kineto_results: Optional[_ProfilerResult] = None
    self.profiling_start_time_ns = 0
    self.profiling_end_time_ns = 0
    self._stats = _ProfilerStats()
    self.custom_trace_id_callback = custom_trace_id_callback
    self.trace_id = ''
    if <MASK>:
        if not use_kineto:
            raise AssertionError('Device-only events supported only with Kineto (use_kineto=True)')
    if self.use_device is not None:
        VALID_DEVICE_OPTIONS = ['cuda', 'xpu', 'mtia', 'hpu']
        if _get_privateuse1_backend_name() != 'privateuseone':
            VALID_DEVICE_OPTIONS.append(_get_privateuse1_backend_name())
        if self.use_device not in VALID_DEVICE_OPTIONS:
            warn(f'The {self.use_device} is not a valid device option.')
            self.use_device = None
        if self.use_device == 'cuda' and (not torch.cuda.is_available()):
            warn('CUDA is not available, disabling CUDA profiling')
            self.use_cuda = False
            self.use_device = None
        if self.use_device == 'xpu' and (not torch.xpu.is_available()):
            warn('XPU is not available, disabling XPU profiling')
            self.use_device = None
        if self.use_device == 'hpu' and (not (hasattr(torch, 'hpu') and torch.hpu.is_available())):
            warn('HPU is not available, disabling HPU profiling')
            self.use_device = None
    self.kineto_activities = set()
    if self.use_cpu:
        self.kineto_activities.add(ProfilerActivity.CPU)
    self.profiler_kind = ProfilerState.KINETO
    if self.use_device == 'cuda':
        if not use_kineto or ProfilerActivity.CUDA not in _supported_activities():
            if not self.use_cpu:
                raise AssertionError('Legacy CUDA profiling requires use_cpu=True')
            self.profiler_kind = ProfilerState.KINETO_GPU_FALLBACK
        else:
            self.kineto_activities.add(ProfilerActivity.CUDA)
    elif self.use_device == 'xpu':
        if not (use_kineto and ProfilerActivity.XPU in _supported_activities()):
            raise AssertionError('Legacy XPU profiling is not supported. Requires use_kineto=True on XPU devices.')
        self.kineto_activities.add(ProfilerActivity.XPU)
    elif self.use_device == 'mtia':
        if not (use_kineto and ProfilerActivity.MTIA in _supported_activities()):
            raise AssertionError('Legacy MTIA profiling is not supported. Requires use_kineto=True on MTIA devices.')
        self.kineto_activities.add(ProfilerActivity.MTIA)
    elif self.use_device == 'hpu':
        if not (use_kineto and ProfilerActivity.HPU in _supported_activities()):
            raise AssertionError('Legacy HPU profiling is not supported. Requires use_kineto=True on HPU devices.')
        self.kineto_activities.add(ProfilerActivity.HPU)
    elif self.use_device is not None and self.use_device != 'privateuseone':
        if not use_kineto or ProfilerActivity.PrivateUse1 not in _supported_activities():
            if not self.use_cpu:
                raise AssertionError('Legacy custombackend profiling requires use_cpu=True')
            self.profiler_kind = ProfilerState.KINETO_PRIVATEUSE1_FALLBACK
        else:
            self.kineto_activities.add(ProfilerActivity.PrivateUse1)
    if len(self.kineto_activities) == 0:
        raise AssertionError('No activities specified for the profiler')

def _get_subgraph_relationship_type(subgraph_a: NSSubgraph, subgraph_b: NSSubgraph, gm_a: GraphModule, gm_b: GraphModule, type_a_related_to_b: set[tuple[NSNodeTargetType, NSNodeTargetType]]) -> SubgraphTypeRelationship:
    node_a = subgraph_a.base_op_node
    node_b = subgraph_b.base_op_node
    if node_a.op != node_b.op:
        if not (node_a.op in ('call_function', 'call_method') and node_b.op in ('call_function', 'call_method')):
            return SubgraphTypeRelationship.NOT_RELATED
    if node_a.op in ('call_function', 'call_method'):
        key = (node_a.target, node_b.target)
        if key not in type_a_related_to_b:
            if node_a.target == node_b.target:
                return SubgraphTypeRelationship.EQUAL_BUT_UKNOWN
            else:
                return SubgraphTypeRelationship.NOT_RELATED
        if node_a.target == node_b.target:
            node_a_has_prev = subgraph_a.base_op_node == subgraph_a.start_node
            node_b_has_prev = subgraph_b.base_op_node == subgraph_b.start_node
            if <MASK>:
                return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
            elif not node_a_has_prev and node_b_has_prev:
                return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
            elif not node_a_has_prev and (not node_b_has_prev):
                return SubgraphTypeRelationship.EQUAL
            else:
                return SubgraphTypeRelationship.EQUAL
        if key in type_a_related_to_b:
            return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
        else:
            return SubgraphTypeRelationship.NOT_RELATED
    elif node_a.op == 'call_module':
        if subgraph_a.base_op_node != subgraph_a.start_node or subgraph_b.base_op_node != subgraph_b.start_node:
            raise AssertionError('Matching call_module patterns where base_op_node != start_node is not supported yet')
        if not isinstance(node_a.target, str):
            raise AssertionError(f'Expected str, got {type(node_a.target)}')
        mod_a = getattr_from_fqn(gm_a, node_a.target)
        if not isinstance(node_b.target, str):
            raise AssertionError(f'Expected str, got {type(node_b.target)}')
        mod_b = getattr_from_fqn(gm_b, node_b.target)
        key = (type(mod_a), type(mod_b))
        if key not in type_a_related_to_b:
            if type(mod_a) is type(mod_b):
                return SubgraphTypeRelationship.EQUAL_BUT_UKNOWN
            else:
                return SubgraphTypeRelationship.NOT_RELATED
        elif type(mod_a) is type(mod_b):
            return SubgraphTypeRelationship.EQUAL
        else:
            return SubgraphTypeRelationship.RELATED_BUT_NOT_EQUAL
    return SubgraphTypeRelationship.NOT_RELATED

def assertHasLiveOut(self, node, expected):
    live_out = anno.getanno(node, anno.Static.LIVE_VARS_OUT)
    live_out_strs = set((str(v) for v in live_out))
    if not expected:
        expected = ()
    if <MASK>:
        expected = (expected,)
    self.assertSetEqual(live_out_strs, set(expected))

def __init__(self, tensor):
    self.floating_dtype = tensor.dtype.is_floating_point
    self.int_mode = True
    self.sci_mode = False
    self.max_width = 1
    with torch.no_grad():
        tensor_view = tensor.reshape(-1)
    if not self.floating_dtype:
        for value in tensor_view:
            value_str = f'{value}'
            self.max_width = max(self.max_width, len(value_str))
    else:
        if tensor.dtype == torch.float4_e2m1fn_x2:
            tensor_view = tensor_view.view(torch.uint8)
        nonzero_finite_vals = torch.masked_select(tensor_view, torch.isfinite(tensor_view) & tensor_view.ne(0))
        if nonzero_finite_vals.numel() == 0:
            return
        if tensor.dtype == torch.float8_e8m0fnu:
            nonzero_finite_vals = nonzero_finite_vals.float()
        nonzero_finite_abs = tensor_totype(nonzero_finite_vals.abs())
        nonzero_finite_min = tensor_totype(nonzero_finite_abs.min())
        nonzero_finite_max = tensor_totype(nonzero_finite_abs.max())
        for value in nonzero_finite_vals:
            if value != torch.ceil(value):
                self.int_mode = False
                break
        self.sci_mode = nonzero_finite_max / nonzero_finite_min > 1000.0 or nonzero_finite_max > 100000000.0 or nonzero_finite_min < 0.0001 if PRINT_OPTS.sci_mode is None else PRINT_OPTS.sci_mode
        if <MASK>:
            if self.sci_mode:
                for value in nonzero_finite_vals:
                    value_str = f'{{:.{PRINT_OPTS.precision}e}}'.format(value)
                    self.max_width = max(self.max_width, len(value_str))
            else:
                for value in nonzero_finite_vals:
                    value_str = f'{value:.0f}'
                    self.max_width = max(self.max_width, len(value_str) + 1)
        elif self.sci_mode:
            for value in nonzero_finite_vals:
                value_str = f'{{:.{PRINT_OPTS.precision}e}}'.format(value)
                self.max_width = max(self.max_width, len(value_str))
        else:
            for value in nonzero_finite_vals:
                value_str = f'{{:.{PRINT_OPTS.precision}f}}'.format(value)
                self.max_width = max(self.max_width, len(value_str))

def __iter__(self) -> Iterator[list[int]]:
    if self.drop_last:
        sampler_iter = iter(self.sampler)
        while True:
            try:
                batch = [next(sampler_iter) for _ in range(self.batch_size)]
                yield batch
            except StopIteration:
                break
    else:
        batch = [0] * self.batch_size
        idx_in_batch = 0
        for idx in self.sampler:
            batch[idx_in_batch] = idx
            idx_in_batch += 1
            if <MASK>:
                yield batch
                idx_in_batch = 0
                batch = [0] * self.batch_size
        if idx_in_batch > 0:
            yield batch[:idx_in_batch]

def _add_peephole_patterns(self) -> None:
    """
        Add peephole patterns for nodes where we can infer constant value even if some inputs
        of the node are unknown.
        """
    for op in itertools.chain(self.module.graph.find_nodes(op='call_function', target=torch.ops.aten.mul.Tensor), self.module.graph.find_nodes(op='call_function', target=torch.ops.aten.mul.Scalar)):
        tensor_val = op.meta.get('val', None)
        if not isinstance(tensor_val, torch.Tensor):
            continue

        def is_zero_int(arg: Any) -> bool:
            return isinstance(arg, int) and arg == 0
        if <MASK>:
            continue
        t = torch.full([1], 0, dtype=tensor_val.dtype, device=tensor_val.device, pin_memory=False)
        self.add_node_replacement(op, t)

def __init__(self, learning_rate=0.001, learning_rate_power=-0.5, initial_accumulator_value=0.1, l1_regularization_strength=0.0, l2_regularization_strength=0.0, name='Ftrl', l2_shrinkage_regularization_strength=0.0, beta=0.0, **kwargs):
    super(Ftrl, self).__init__(name, **kwargs)
    if initial_accumulator_value < 0.0:
        raise ValueError('initial_accumulator_value %f needs to be positive or zero' % initial_accumulator_value)
    if learning_rate_power > 0.0:
        raise ValueError('learning_rate_power %f needs to be negative or zero' % learning_rate_power)
    if <MASK>:
        raise ValueError('l1_regularization_strength %f needs to be positive or zero' % l1_regularization_strength)
    if l2_regularization_strength < 0.0:
        raise ValueError('l2_regularization_strength %f needs to be positive or zero' % l2_regularization_strength)
    if l2_shrinkage_regularization_strength < 0.0:
        raise ValueError('l2_shrinkage_regularization_strength %f needs to be positive or zero' % l2_shrinkage_regularization_strength)
    self._set_hyper('learning_rate', learning_rate)
    self._set_hyper('decay', self._initial_decay)
    self._set_hyper('learning_rate_power', learning_rate_power)
    self._set_hyper('l1_regularization_strength', l1_regularization_strength)
    self._set_hyper('l2_regularization_strength', l2_regularization_strength)
    self._set_hyper('beta', beta)
    self._initial_accumulator_value = initial_accumulator_value
    self._l2_shrinkage_regularization_strength = l2_shrinkage_regularization_strength

def _reduce_along_dim(self: list[int], dim: int, keepdim: bool):
    dim = maybe_wrap_dim(dim, len(self))
    out: list[int] = []
    for (i, self_dim) in enumerate(self):
        if i == dim:
            if <MASK>:
                out.append(1)
        else:
            out.append(self_dim)
    return out

