def get_metric_function(metric, output_shape=None, loss_fn=None):
    """Returns the metric function corresponding to the given metric input.

  Args:
      metric: Metric function name or reference.
      output_shape: The shape of the output that this metric will be calculated
        for.
      loss_fn: The loss function used.

  Returns:
      The metric function.
  """
    if metric not in ['accuracy', 'acc', 'crossentropy', 'ce']:
        return metrics_module.get(metric)
    is_sparse_categorical_crossentropy = isinstance(loss_fn, losses.SparseCategoricalCrossentropy) or (isinstance(loss_fn, losses.LossFunctionWrapper) and loss_fn.fn == losses.sparse_categorical_crossentropy)
    is_binary_crossentropy = isinstance(loss_fn, losses.BinaryCrossentropy) or (isinstance(loss_fn, losses.LossFunctionWrapper) and loss_fn.fn == losses.binary_crossentropy)
    if <MASK>:
        if output_shape[-1] == 1 or is_binary_crossentropy:
            return metrics_module.binary_accuracy
        elif is_sparse_categorical_crossentropy:
            return metrics_module.sparse_categorical_accuracy
        return metrics_module.categorical_accuracy
    else:
        if output_shape[-1] == 1 or is_binary_crossentropy:
            return metrics_module.binary_crossentropy
        elif is_sparse_categorical_crossentropy:
            return metrics_module.sparse_categorical_crossentropy
        return metrics_module.categorical_crossentropy

def fuzz_scalar(spec, seed: Optional[int]=None) -> Union[float, int, bool, complex]:
    """
    Create a Python scalar value from a ScalarSpec.

    Args:
        spec: ScalarSpec containing the desired dtype and optionally a constant value
        seed: Random seed for reproducibility. If None, uses current random state.

    Returns:
        Python scalar (float, int, bool, complex) matching the dtype
    """
    if spec.constant is not None:
        return spec.constant
    if seed is not None:
        local_random = random.Random(seed)
        old_random_state = random.getstate()
        try:
            random.setstate(local_random.getstate())
            if spec.dtype.is_floating_point:
                return random.uniform(-10.0, 10.0)
            elif spec.dtype in [torch.complex64, torch.complex128]:
                if <MASK>:
                    raise ValueError('Cannot generate complex values with avoid_complex=True')
                return complex(random.uniform(-10.0, 10.0), random.uniform(-10.0, 10.0))
            elif spec.dtype == torch.bool:
                return random.choice([True, False])
            else:
                return random.randint(-10, 10)
        finally:
            random.setstate(old_random_state)
    elif spec.dtype.is_floating_point:
        return random.uniform(-10.0, 10.0)
    elif spec.dtype in [torch.complex64, torch.complex128]:
        if FuzzerConfig.avoid_complex:
            raise ValueError('Cannot generate complex values with avoid_complex=True')
        return complex(random.uniform(-10.0, 10.0), random.uniform(-10.0, 10.0))
    elif spec.dtype == torch.bool:
        return random.choice([True, False])
    else:
        return random.randint(-10, 10)

def send_messages(self, email_messages):
    """
        Send one or more EmailMessage objects and return the number of email
        messages sent.
        """
    if not email_messages:
        return 0
    with self._lock:
        new_conn_created = self.open()
        if not self.connection or new_conn_created is None:
            return 0
        num_sent = 0
        try:
            for message in email_messages:
                sent = self._send(message)
                if <MASK>:
                    num_sent += 1
        finally:
            if new_conn_created:
                self.close()
    return num_sent

def register_unary_elementwise_api(func):
    """Decorator that registers a TensorFlow op as a unary elementwise API."""
    _UNARY_ELEMENTWISE_APIS.append(func)
    for (args, handler) in _ELEMENTWISE_API_HANDLERS.items():
        if <MASK>:
            _add_dispatch_for_unary_elementwise_api(func, args[0], handler)
    return func

@functools.cache
def addmm_patterns_init():
    """
    addmm related patterns.
    To avoid duplication, also includes int8 WoQ GEMM pattern without bias.
    """
    device = next((gpu for gpu in GPU_TYPES if getattr(torch, gpu).is_available()), 'cpu')
    val = functools.partial(torch.empty, (10, 10), device=device, requires_grad=False)
    scale = functools.partial(torch.empty, (10,), device=device, requires_grad=False)

    def check_int8_woq_concat_linear_weights(match):
        is_cpu = match.kwargs['inp'].meta['val'].is_cpu
        if not is_cpu or not config.cpp.enable_concat_linear:
            return False
        weight_inputs = ['w1', 'w2']
        if 'w3' in match.kwargs:
            weight_inputs.append('w3')
        if not all((match.kwargs[wgt].target == torch.ops.prims.convert_element_type.default for wgt in weight_inputs)):
            return False
        if not all((next(iter(match.kwargs[wgt]._input_nodes.keys())).meta['val'].dtype is torch.int8 for wgt in weight_inputs)):
            return False
        if <MASK>:
            return False
        return True

    def check_concat_weights(match):
        is_cpu = match.kwargs['inp'].meta['val'].is_cpu
        if is_cpu and (not config.cpp.enable_concat_linear):
            return False
        weight_inputs = ['w1', 'w2']
        if 'w3' in match.kwargs:
            weight_inputs.append('w3')
        equal_shape_inputs = [weight_inputs]
        if 'b1' in match.kwargs:
            bias_inputs = ['b1', 'b2']
            if 'b3' in match.kwargs:
                bias_inputs.append('b3')
            equal_shape_inputs.append(bias_inputs)
        for equal_shape_group in equal_shape_inputs:
            inps = [match.kwargs[name] for name in equal_shape_group]
            if not all((inp.op == 'get_attr' and inp.meta['val'].shape == inps[0].meta['val'].shape for inp in inps)):
                return False
        return True

    def int8_woq_fusion_pattern(inp, w1, w2, w3, s1, s2, s3):
        return (inp @ w1 * s1, inp @ w2 * s2, inp @ w3 * s3)

    def int8_woq_fusion_replacement(inp, w1, w2, w3, s1, s2, s3):
        cat_w = torch.cat((w1, w2, w3), dim=1)
        cat_s = torch.cat((s1, s2, s3), dim=0)
        mm = (inp @ cat_w).mul(cat_s)
        (n1, n2) = (w1.size(1), w2.size(1))
        return mm.tensor_split([n1, n1 + n2], dim=-1)
    register_replacement(int8_woq_fusion_pattern, int8_woq_fusion_replacement, [val(), val(), val(), val(), scale(), scale(), scale()], fwd_only, pass_patterns[0], extra_check=check_int8_woq_concat_linear_weights, exclusive_arg_names=('w1', 'w2', 'w3', 's1', 's2', 's3'))

    def matmul_fuse_pattern(inp, w1, w2, w3):
        return (inp @ w1, inp @ w2, inp @ w3)

    def matmul_replacement(inp, w1, w2, w3):
        cat_t = torch.cat((w1, w2, w3), dim=1)
        mm = inp @ cat_t
        return mm.chunk(3, dim=1)
    register_replacement(matmul_fuse_pattern, matmul_replacement, [val(), val(), val(), val()], fwd_only, pass_patterns[0], extra_check=check_concat_weights, exclusive_arg_names=('w1', 'w2', 'w3'))

    def matmul_fuse_pattern_two(inp, w1, w2):
        return (inp @ w1, inp @ w2)

    def matmul_replacement_two(inp, w1, w2):
        cat_t = torch.cat((w1, w2), dim=1)
        mm = inp @ cat_t
        return mm.chunk(2, dim=1)
    register_replacement(matmul_fuse_pattern_two, matmul_replacement_two, [val(), val(), val()], fwd_only, pass_patterns[0], extra_check=check_concat_weights, exclusive_arg_names=('w1', 'w2'))

    def addmm_fuse_pattern_second(inp, w1, w2, w3, b1, b2, b3):
        return (aten.addmm(b1, inp, w1), aten.addmm(b2, inp, w2), aten.addmm(b3, inp, w3))

    def addmm_fuse_replacement_second(inp, w1, w2, w3, b1, b2, b3):
        cat_w = torch.cat((w1, w2, w3), dim=1)
        cat_b = torch.cat((b1, b2, b3))
        return aten.addmm(cat_b, inp, cat_w).chunk(3, dim=1)
    register_replacement(addmm_fuse_pattern_second, addmm_fuse_replacement_second, [val() for _ in range(7)], fwd_only, pass_patterns[0], extra_check=check_concat_weights, exclusive_arg_names=('w1', 'w2', 'w3', 'b1', 'b2', 'b3'))

def get_array_op(op):
    """
    Return a binary array operation corresponding to the given operator op.

    Parameters
    ----------
    op : function
        Binary operator from operator or roperator module.

    Returns
    -------
    functools.partial
    """
    if isinstance(op, partial):
        return op
    op_name = op.__name__.strip('_').lstrip('r')
    if op_name == 'arith_op':
        return op
    if op_name in {'eq', 'ne', 'lt', 'le', 'gt', 'ge'}:
        return partial(comparison_op, op=op)
    elif <MASK>:
        return partial(logical_op, op=op)
    elif op_name in {'add', 'sub', 'mul', 'truediv', 'floordiv', 'mod', 'divmod', 'pow'}:
        return partial(arithmetic_op, op=op)
    else:
        raise NotImplementedError(op_name)

def _max_pool2d(input: Tensor, kernel_size: BroadcastingList2[int], stride: Optional[BroadcastingList2[int]]=None, padding: BroadcastingList2[int]=0, dilation: BroadcastingList2[int]=1, ceil_mode: bool=False, return_indices: bool=False) -> Tensor:
    if has_torch_function_unary(input):
        return handle_torch_function(max_pool2d, (input,), input, kernel_size, stride=stride, padding=padding, dilation=dilation, ceil_mode=ceil_mode, return_indices=return_indices)
    if <MASK>:
        stride = torch.jit.annotate(list[int], [])
    return torch.max_pool2d(input, kernel_size, stride, padding, dilation, ceil_mode)

@final
def _infer_types(self, values, na_values, no_dtype_specified, try_num_bool: bool=True) -> tuple[ArrayLike, int]:
    """
        Infer types of values, possibly casting

        Parameters
        ----------
        values : ndarray
        na_values : set
        no_dtype_specified: Specifies if we want to cast explicitly
        try_num_bool : bool, default try
           try to cast values to numeric (first preference) or boolean

        Returns
        -------
        converted : ndarray or ExtensionArray
        na_count : int
        """
    na_count = 0
    if <MASK>:
        na_values = np.array([val for val in na_values if not isinstance(val, str)])
        mask = algorithms.isin(values, na_values)
        na_count = mask.astype('uint8', copy=False).sum()
        if na_count > 0:
            if is_integer_dtype(values):
                values = values.astype(np.float64)
            np.putmask(values, mask, np.nan)
        return (values, na_count)
    dtype_backend = self.dtype_backend
    non_default_dtype_backend = no_dtype_specified and dtype_backend is not lib.no_default
    result: ArrayLike
    if try_num_bool and is_object_dtype(values.dtype):
        try:
            (result, result_mask) = lib.maybe_convert_numeric(values, na_values, False, convert_to_masked_nullable=non_default_dtype_backend)
        except (ValueError, TypeError):
            na_count = parsers.sanitize_objects(values, na_values)
            result = values
        else:
            if non_default_dtype_backend:
                if result_mask is None:
                    result_mask = np.zeros(result.shape, dtype=np.bool_)
                if result_mask.all():
                    result = IntegerArray(np.ones(result_mask.shape, dtype=np.int64), result_mask)
                elif is_integer_dtype(result):
                    result = IntegerArray(result, result_mask)
                elif is_bool_dtype(result):
                    result = BooleanArray(result, result_mask)
                elif is_float_dtype(result):
                    result = FloatingArray(result, result_mask)
                na_count = result_mask.sum()
            else:
                na_count = isna(result).sum()
    else:
        result = values
        if values.dtype == np.object_:
            na_count = parsers.sanitize_objects(values, na_values)
    if result.dtype == np.object_ and try_num_bool:
        (result, bool_mask) = libops.maybe_convert_bool(np.asarray(values), true_values=self.true_values, false_values=self.false_values, convert_to_masked_nullable=non_default_dtype_backend)
        if result.dtype == np.bool_ and non_default_dtype_backend:
            if bool_mask is None:
                bool_mask = np.zeros(result.shape, dtype=np.bool_)
            result = BooleanArray(result, bool_mask)
        elif result.dtype == np.object_ and non_default_dtype_backend:
            if not lib.is_datetime_array(result, skipna=True):
                dtype = StringDtype()
                cls = dtype.construct_array_type()
                result = cls._from_sequence(values, dtype=dtype)
    if dtype_backend == 'pyarrow':
        pa = import_optional_dependency('pyarrow')
        if isinstance(result, np.ndarray):
            result = ArrowExtensionArray(pa.array(result, from_pandas=True))
        elif isinstance(result, BaseMaskedArray):
            if result._mask.all():
                result = ArrowExtensionArray(pa.array([None] * len(result)))
            else:
                result = ArrowExtensionArray(pa.array(result._data, mask=result._mask))
        else:
            result = ArrowExtensionArray(pa.array(result.to_numpy(), from_pandas=True))
    return (result, na_count)

def rename_def(a):

    def _rename(arg_name, values):
        new_name = f'_{len(name_table)}'
        assert arg_name not in name_table
        name_table[arg_name] = new_name
        assert arg_name in values
        values[new_name] = values.pop(arg_name)
        return new_name
    if a is None:
        return
    if isinstance(a, TensorArgument):
        a.name = _rename(a.name, graph.tensor_values)
    elif isinstance(a, SymIntArgument):
        if <MASK>:
            a.as_name = _rename(a.as_name, graph.sym_int_values)
    elif isinstance(a, SymFloatArgument):
        if a.type == 'as_name':
            a.as_name = _rename(a.as_name, graph.sym_float_values)
    elif isinstance(a, SymBoolArgument):
        if a.type == 'as_name':
            a.as_name = _rename(a.as_name, graph.sym_bool_values)
    elif isinstance(a, CustomObjArgument):
        a.name = _rename(a.name, graph.custom_obj_values)
    else:
        raise AssertionError(f'Unknown argument type: {a}')

def _yield_all_checks(estimator, legacy: bool):
    name = estimator.__class__.__name__
    tags = get_tags(estimator)
    if not tags.input_tags.two_d_array:
        warnings.warn("Can't test estimator {} which requires input  of type {}".format(name, tags.input_tags), SkipTestWarning)
        return
    if tags._skip_test:
        warnings.warn('Explicit SKIP via _skip_test tag for estimator {}.'.format(name), SkipTestWarning)
        return
    for check in _yield_api_checks(estimator):
        yield check
    if not legacy:
        return
    for check in _yield_checks(estimator):
        yield check
    if is_classifier(estimator):
        for check in _yield_classifier_checks(estimator):
            yield check
    if is_regressor(estimator):
        for check in _yield_regressor_checks(estimator):
            yield check
    if hasattr(estimator, 'transform'):
        for check in _yield_transformer_checks(estimator):
            yield check
    if isinstance(estimator, ClusterMixin):
        for check in _yield_clustering_checks(estimator):
            yield check
    if is_outlier_detector(estimator):
        for check in _yield_outliers_checks(estimator):
            yield check
    yield check_parameters_default_constructible
    if not tags.non_deterministic:
        yield check_methods_sample_order_invariance
        yield check_methods_subset_invariance
    yield check_fit2d_1sample
    yield check_fit2d_1feature
    yield check_get_params_invariance
    yield check_set_params
    yield check_dict_unchanged
    yield check_fit_idempotent
    yield check_fit_check_is_fitted
    if not tags.no_validation:
        yield check_n_features_in
        yield check_fit1d
        yield check_fit2d_predict1d
        if tags.target_tags.required:
            yield check_requires_y_none
    if <MASK>:
        yield check_fit_non_negative

@functools.lru_cache(256)
def _join_dimensions_cached(expr: Expr) -> Expr:
    """
    ModularIndexing(i0, 1, 32) + 32 * ModularIndexing(i0, 32, 4)
    becomes
    ModularIndexing(i0, 1, 128)
    ModularIndexing(i0, 1, 32) + 32 * FloorDiv(i0, 32)
    becomes i0


    This type of pattern can come from view operations
    """
    assert isinstance(expr, sympy.Add)
    scale = sympy.Wild('scale', exclude=[0], integer=True)
    base = sympy.Wild('base', integer=True)
    divisor = sympy.Wild('divisor', integer=True)
    mod1 = sympy.Wild('modulus', integer=True)
    mod2 = sympy.Wild('modulus2', integer=True)
    for term1 in expr.args:
        m1 = term1.match(scale * ModularIndexing(base, divisor, mod1))
        if m1:
            for term2 in expr.args:
                m2 = term2.match(m1[scale] * m1[mod1] * ModularIndexing(m1[base], m1[divisor] * m1[mod1], mod2))
                if <MASK>:
                    expr = join_dimensions(expr - term1 - term2 + m1[scale] * ModularIndexing(m1[base], m1[divisor], m1[mod1] * m2[mod2]))
                    return expr
    for term1 in expr.args:
        m1 = term1.match(scale * ModularIndexing(base, divisor, mod1))
        if m1:
            for term2 in expr.args:
                m2 = term2.match(m1[scale] * m1[mod1] * FloorDiv(m1[base], m1[divisor] * m1[mod1]))
                if m2 is not None:
                    expr = join_dimensions(expr - term1 - term2 + m1[scale] * FloorDiv(m1[base], m1[divisor]))
                    return expr
    return expr

def determine_aoti_mmap_flags(consts_size: int) -> tuple[bool, bool]:
    """
    Decide whether we should mmap weights, and whether to store the weights with .so.

    If force_mmap_weights or package_constants_on_disk_format == "binary_blob" configs are set, respect the config.

    Returns tuple (use_external_weights, use_mmap_weights).
    """
    if config.aot_inductor.force_mmap_weights and config.aot_inductor.package_constants_on_disk_format == 'binary_blob':
        raise RuntimeError('config.aot_inductor.package_constants_on_disk_format = binary_blob and config.aot_inductor.force_mmap_weights cannot both be True.')
    if config.aot_inductor.force_mmap_weights:
        if <MASK>:
            raise RuntimeError('when cross_target_platform is windows, use_mmap_weights should not be true.')
        use_mmap_weights = True
        use_external_weights = False
        return (use_external_weights, use_mmap_weights)
    if config.aot_inductor.package_constants_on_disk_format == 'binary_blob':
        use_external_weights = True
        use_mmap_weights = False
        return (use_external_weights, use_mmap_weights)
    if consts_size <= 2000000000:
        return (False, False)
    use_external_weights = False
    use_mmap_weights = not config.is_fbcode()
    return (use_external_weights, use_mmap_weights)

def delanno(node, key, field_name='___pyct_anno'):
    annotations = getattr(node, field_name)
    del annotations[key]
    if <MASK>:
        delattr(node, field_name)
        node._fields = tuple((f for f in node._fields if f != field_name))

def _contains_has_gpu(node: ast.AST) -> bool:
    if isinstance(node, ast.Name) and node.id in ['HAS_GPU', 'RUN_GPU']:
        return True
    elif <MASK>:
        return any((_contains_has_gpu(value) for value in node.values))
    elif isinstance(node, ast.UnaryOp):
        return _contains_has_gpu(node.operand)
    elif isinstance(node, ast.Compare):
        return _contains_has_gpu(node.left) or any((_contains_has_gpu(comp) for comp in node.comparators))
    elif isinstance(node, (ast.IfExp, ast.Call)):
        return False
    return False

def is_valid_cat_splitwithsizes(match):
    cat_nodes = filter_nodes(match.nodes, aten.cat)
    split_nodes = filter_nodes(match.nodes, aten.split_with_sizes)
    if len(split_nodes) != 1 or len(cat_nodes) != 1:
        return False
    (split_node, cat_node) = (split_nodes[0], cat_nodes[0])
    if len(cat_node.users) > 1:
        return False
    dim = get_arg_value(split_node, 2, 'dim')
    if dim != get_arg_value(cat_node, 1, 'dim'):
        return False
    cat_inputs = list(get_arg_value(cat_node, 0))
    split_sizes = get_arg_value(split_node, 1, 'split_sizes')
    if len(cat_inputs) != len(split_sizes):
        return False
    for (cat_input, split_size) in zip(cat_inputs, split_sizes):
        if <MASK>:
            return False
        cat_input_size = cat_input.meta['val'].size(dim)
        if cat_input_size != split_size:
            return False
    return True

def maybe_get_static_value(x, dtype=None):
    """Helper which tries to return a static value.

  Given `x`, extract it's value statically, optionally casting to a specific
  dtype. If this is not possible, None is returned.

  Args:
    x: `Tensor` for which to extract a value statically.
    dtype: Optional dtype to cast to.

  Returns:
    Statically inferred value if possible, otherwise None.
  """
    if <MASK>:
        return x
    try:
        x_ = tensor_util.constant_value(x)
    except TypeError:
        x_ = x
    if x_ is None or dtype is None:
        return x_
    return np.array(x_, dtype)

def _verify_tf_condition(cond, tag):
    """Ensures that the condition can be used in a TF control flow."""
    extra_hint = 'to check for None, use `is not None`'
    cond = tensor_conversion.convert_to_tensor_v2(cond)
    if cond.dtype != dtypes.bool:
        raise ValueError('condition of {} expected to be `tf.bool` scalar, got {}; to use as boolean Tensor, use `tf.cast`; {}'.format(tag, cond, extra_hint))
    if cond.shape is None or cond.shape.ndims is None:
        cond = array_ops.reshape(cond, ())
    elif <MASK>:
        known_dims = [d for d in cond.shape.as_list() if d is not None]
        if np.prod(known_dims) > 1:
            raise ValueError('condition of {} expected to be `tf.bool` scalar, got {}; {}'.format(tag, cond, extra_hint))
        else:
            cond = array_ops.reshape(cond, ())
    return cond

def __init__(self, func: FunctionSchema, properties: LazyIrProperties | None=None, *, symint: bool) -> None:
    if properties:
        self.properties = properties
    self.func = func
    self.symint = symint
    positional_args: list[LazyArgument] = []
    for arg_field in ['pre_self_positional', 'self_arg', 'post_self_positional']:
        if arg_field == 'self_arg' and func.arguments.self_arg is not None:
            arg = func.arguments.self_arg.argument
            positional_args.append(LazyArgument(arg, self.properties, symint=symint))
        elif getattr(func.arguments, arg_field) is not None:
            positional_args.extend((LazyArgument(arg, self.properties, symint=symint) for arg in getattr(func.arguments, arg_field)))
    self.positional_args = tuple(positional_args)
    keyword_args: list[LazyArgument] = []
    for arg_field in ['pre_tensor_options_kwarg_only', 'tensor_options', 'post_tensor_options_kwarg_only', 'out']:
        curr_args = getattr(func.arguments, arg_field)
        if curr_args is not None:
            if isinstance(curr_args, TensorOptionsArguments):
                curr_args = curr_args.all()
            for arg in curr_args:
                if <MASK>:
                    assert self.generator_arg is None, 'We expect there is only one generator arg'
                    self.generator_arg = NamedCType(arg.name, arg.type)
            keyword_args.extend((LazyArgument(arg, self.properties, symint=symint) for arg in curr_args))
    self.keyword_args = tuple(keyword_args)
    self.name = func.name
    self.returns = func.returns

@dist_init
def _test_rref_type_with_error(self, blocking):
    dst = worker_name((self.rank + 1) % self.world_size)
    rref = rpc.remote(dst, raise_func)
    if <MASK>:
        with self.assertRaisesRegex(ValueError, 'Expected error'):
            rref._get_type(blocking=blocking)
    else:
        fut = rref._get_type(blocking=blocking)
        with self.assertRaisesRegex(ValueError, 'Expected error'):
            fut.wait()

def __dtype_from_pep3118(stream, is_subdtype):
    field_spec = {'names': [], 'formats': [], 'offsets': [], 'itemsize': 0}
    offset = 0
    common_alignment = 1
    is_padding = False
    while stream:
        value = None
        if stream.consume('}'):
            break
        shape = None
        if stream.consume('('):
            shape = stream.consume_until(')')
            shape = tuple(map(int, shape.split(',')))
        if stream.next in ('@', '=', '<', '>', '^', '!'):
            byteorder = stream.advance(1)
            if byteorder == '!':
                byteorder = '>'
            stream.byteorder = byteorder
        if stream.byteorder in ('@', '^'):
            type_map = _pep3118_native_map
            type_map_chars = _pep3118_native_typechars
        else:
            type_map = _pep3118_standard_map
            type_map_chars = _pep3118_standard_typechars
        itemsize_str = stream.consume_until(lambda c: not c.isdigit())
        if itemsize_str:
            itemsize = int(itemsize_str)
        else:
            itemsize = 1
        is_padding = False
        if stream.consume('T{'):
            (value, align) = __dtype_from_pep3118(stream, is_subdtype=True)
        elif <MASK>:
            if stream.next == 'Z':
                typechar = stream.advance(2)
            else:
                typechar = stream.advance(1)
            is_padding = typechar == 'x'
            dtypechar = type_map[typechar]
            if dtypechar in 'USV':
                dtypechar += '%d' % itemsize
                itemsize = 1
            numpy_byteorder = {'@': '=', '^': '='}.get(stream.byteorder, stream.byteorder)
            value = dtype(numpy_byteorder + dtypechar)
            align = value.alignment
        elif stream.next in _pep3118_unsupported_map:
            desc = _pep3118_unsupported_map[stream.next]
            raise NotImplementedError(f'Unrepresentable PEP 3118 data type {stream.next!r} ({desc})')
        else:
            raise ValueError(f'Unknown PEP 3118 data type specifier {stream.s!r}')
        extra_offset = 0
        if stream.byteorder == '@':
            start_padding = -offset % align
            intra_padding = -value.itemsize % align
            offset += start_padding
            if intra_padding != 0:
                if itemsize > 1 or (shape is not None and _prod(shape) > 1):
                    value = _add_trailing_padding(value, intra_padding)
                else:
                    extra_offset += intra_padding
            common_alignment = _lcm(align, common_alignment)
        if itemsize != 1:
            value = dtype((value, (itemsize,)))
        if shape is not None:
            value = dtype((value, shape))
        if stream.consume(':'):
            name = stream.consume_until(':')
        else:
            name = None
        if not (is_padding and name is None):
            if name is not None and name in field_spec['names']:
                raise RuntimeError(f"Duplicate field name '{name}' in PEP3118 format")
            field_spec['names'].append(name)
            field_spec['formats'].append(value)
            field_spec['offsets'].append(offset)
        offset += value.itemsize
        offset += extra_offset
        field_spec['itemsize'] = offset
    if stream.byteorder == '@':
        field_spec['itemsize'] += -offset % common_alignment
    if field_spec['names'] == [None] and field_spec['offsets'][0] == 0 and (field_spec['itemsize'] == field_spec['formats'][0].itemsize) and (not is_subdtype):
        ret = field_spec['formats'][0]
    else:
        _fix_names(field_spec)
        ret = dtype(field_spec)
    return (ret, common_alignment)

def __array_finalize__(self, obj):
    """
        Finalizes the masked array.

        """
    self._update_from(obj)
    if isinstance(obj, ndarray):
        if obj.dtype.names is not None:
            _mask = getmaskarray(obj)
        else:
            _mask = getmask(obj)
        if _mask is not nomask and obj.__array_interface__['data'][0] != self.__array_interface__['data'][0]:
            if self.dtype == obj.dtype:
                _mask_dtype = _mask.dtype
            else:
                _mask_dtype = make_mask_descr(self.dtype)
            if self.flags.c_contiguous:
                order = 'C'
            elif self.flags.f_contiguous:
                order = 'F'
            else:
                order = 'K'
            _mask = _mask.astype(_mask_dtype, order)
        else:
            _mask = _mask.view()
    else:
        _mask = nomask
    self._mask = _mask
    if self._mask is not nomask:
        try:
            self._mask.shape = self.shape
        except ValueError:
            self._mask = nomask
        except (TypeError, AttributeError):
            pass
    if self._fill_value is not None:
        self._fill_value = _check_fill_value(self._fill_value, self.dtype)
    elif <MASK>:
        self._fill_value = _check_fill_value(None, self.dtype)

def remove_unused_graphargs(self) -> None:
    assert self.should_exit

    def is_static_true(b_node: fx.node.Argument) -> bool:
        if b_node is True:
            return True
        if not isinstance(b_node, fx.Node):
            return False
        b = b_node.meta.get('example_value')
        if b is None:
            return False
        if b is True:
            return True
        if isinstance(b, torch.SymBool) and (r := b.node.maybe_as_bool()) is not None:
            return r
        return False

    def is_symnode_arg(a: fx.node.Argument) -> bool:
        from torch.fx.experimental.sym_node import SymTypes
        if isinstance(a, (int, float, bool)):
            return True
        if isinstance(a, fx.Node):
            return isinstance(a.meta.get('example_value'), SymTypes)
        return False

    def is_symnode_compute_node(node: fx.Node) -> bool:
        from torch.fx.experimental.sym_node import SymTypes
        if node.op != 'call_function':
            return False
        if not isinstance(node.meta.get('example_value'), SymTypes):
            return False
        if not all((is_symnode_arg(a) for a in node.args)):
            return False
        if not all((is_symnode_arg(a) for a in node.kwargs.values())):
            return False
        return True
    from torch.fx.experimental.symbolic_shapes import is_accessor_node
    for node in reversed(list(self.graph.nodes)):
        if len(list(node.users)) == 0:
            if node.op == 'get_attr' or (node.op == 'call_function' and node.target is operator.getitem) or (node.op == 'call_function' and node.target is torch._check and is_static_true(node.args[0])) or is_symnode_compute_node(node) or is_accessor_node(node):
                self.remove_node(node)

    def placeholder_binds_symbol(node: fx.Node) -> Optional[sympy.Symbol]:
        arg = node.meta['grapharg']
        example = arg.example
        if isinstance(example, torch.SymInt) and isinstance(example.node.expr, sympy.Symbol):
            return example.node.expr
        return None

    def remove_unused(node: fx.Node) -> None:
        log.debug('REMOVE UNUSED GRAPHARG %s', node.meta['grapharg'].source.name())
        del node.meta['grapharg']
        self.remove_node(node)
        self.real_value_cache.pop(node, None)
    used_symbols: set[sympy.Symbol] = set()

    def update_used_symbols(used_symbols: set[sympy.Symbol], fake: Union[torch.SymInt, torch.Tensor]) -> None:
        used_symbols |= free_symbols(fake)
    recheck_placeholders = []
    for node in self.placeholders:
        binds_symbol = placeholder_binds_symbol(node) is not None
        if binds_symbol:
            if <MASK>:
                recheck_placeholders.append(node)
        elif not node.users and (not isinstance(node.meta['grapharg'], BackwardStateGraphArg)):
            remove_unused(node)
        else:
            arg = node.meta['grapharg']
            if isinstance(arg, BackwardStateGraphArg):
                continue
            if isinstance(node.meta['grapharg'].example, torch.ScriptObject):
                real_script_obj = node.meta['grapharg'].example
                fake_script_obj = node.meta['grapharg'].example_strong_ref
                if not torch._library.fake_class_registry.tracing_with_real(real_script_obj):
                    flat_dict = dict(real_script_obj.__obj_flatten__())
                    for attr in flat_dict.keys():
                        fake_attr_val = getattr(fake_script_obj.wrapped_obj, attr)
                        pytree.tree_map_only((torch.SymInt, torch.Tensor), lambda t: update_used_symbols(used_symbols, t), fake_attr_val)
                continue
            fake = arg.fake_tensor if arg.fake_tensor is not None else arg.example
            update_used_symbols(used_symbols, fake)
    for node in recheck_placeholders:
        symbol = placeholder_binds_symbol(node)
        if symbol is not None:
            if symbol not in used_symbols:
                remove_unused(node)
            else:
                used_symbols.remove(symbol)

def jagged_torch_function(func, *args, **kwargs):
    if func is torch._C._nn.scaled_dot_product_attention:
        return jagged_scaled_dot_product_attention(*args, **kwargs)
    if func.__name__ == 'apply_':
        func(args[0]._values, *args[1:], **kwargs)
        return args[0]
    if func.__name__ == 'flatten':

        def _flatten_sig(input, start_dim=0, end_dim=-1):
            pass
        (_, new_kwargs) = normalize_function(_flatten_sig, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
        inp = new_kwargs.pop('input')
        start_dim = _wrap_jagged_dim(inp.dim(), new_kwargs['start_dim'], inp._ragged_idx, 'flatten', convert_to_inner_dim=False)
        end_dim = _wrap_jagged_dim(inp.dim(), new_kwargs['end_dim'], inp._ragged_idx, 'flatten', convert_to_inner_dim=False)
        if start_dim == end_dim:
            return inp
        product = functools.reduce(operator.mul, inp.shape[start_dim:end_dim + 1])
        new_shape = (*inp.shape[:start_dim], product, *inp.shape[end_dim + 1:])
        return inp.reshape(*new_shape)
    if func.__name__ == 'share_memory_':
        nt = args[0]
        if nt.is_cuda:
            return nt
        (names, _) = nt.__tensor_flatten__()
        with torch._C.DisableTorchFunctionSubclass():
            for name in names:
                component = getattr(nt, name, None)
                if component is not None:
                    component.share_memory_()
        return nt
    if func.__name__ == 'is_shared':
        nt = args[0]
        if nt.is_cuda:
            return False
        (names, _) = nt.__tensor_flatten__()
        if not names:
            return False
        return all((getattr(nt, name) is not None and getattr(nt, name).is_shared() for name in names))
    if <MASK>:

        def _rms_norm_sig(input, normalized_shape, weight=None, eps=None):
            pass
        (_, new_kwargs) = normalize_function(_rms_norm_sig, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
        inp = new_kwargs.pop('input')
        normalized_shape = new_kwargs.pop('normalized_shape')
        max_normalizable = inp.dim() - inp._ragged_idx - 1
        if len(normalized_shape) > max_normalizable:
            raise ValueError('rms_norm(): Normalization over the ragged dim not supported for nested tensors')
        with torch._C.DisableTorchFunctionSubclass():
            return func(*args, **kwargs)
    raise NotImplementedError(func)

def gfk_key(obj):
    ct_id = getattr(obj, ct_attname)
    if <MASK>:
        return None
    else:
        model = self.field.get_content_type(id=ct_id, using=obj._state.db).model_class()
        return (str(getattr(obj, self.field.fk_field)), model)

def _dataclass_to_dict(obj):
    if isinstance(obj, _Union):
        return {obj.type: _dataclass_to_dict(obj.value)}
    elif dataclasses.is_dataclass(obj):
        return {f.name: _dataclass_to_dict(getattr(obj, f.name)) for f in dataclasses.fields(obj)}
    elif isinstance(obj, list):
        return [_dataclass_to_dict(x) for x in obj]
    elif isinstance(obj, tuple):
        return tuple((_dataclass_to_dict(x) for x in obj))
    elif isinstance(obj, dict):
        return {k: _dataclass_to_dict(v) for (k, v) in obj.items()}
    elif isinstance(obj, float):
        if obj == math.inf:
            return 'Infinity'
        elif <MASK>:
            return '-Infinity'
        elif math.isnan(obj):
            return 'NaN'
        else:
            return obj
    else:
        return obj

@quantized_args(True, False, False)
def symbolic_fn(g, input, output_size, *args):
    (scales, align_corners) = _get_interpolate_attributes(g, interpolate_mode, args)
    align_corners = _maybe_get_scalar(align_corners)
    coordinate_transformation_mode = 'asymmetric' if interpolate_mode == 'nearest' else 'align_corners' if align_corners else 'half_pixel'
    if <MASK>:
        input_size = g.op('Shape', input)
        input_size_beg = _slice_helper(g, input_size, axes=[0], ends=[2], starts=[0])
        output_size = g.op('Cast', output_size, to_i=_C_onnx.TensorProtoDataType.INT64)
        output_size = g.op('Concat', input_size_beg, output_size, axis_i=0)
        if g.opset >= 13:
            empty_roi = _optional_input_placeholder_tensor(g)
            empty_scales = _optional_input_placeholder_tensor(g)
        else:
            empty_roi = g.op('Constant', value_t=torch.tensor([], dtype=torch.float32))
            empty_scales = g.op('Constant', value_t=torch.tensor([], dtype=torch.float32))
        return g.op('Resize', input, empty_roi, empty_scales, output_size, coordinate_transformation_mode_s=coordinate_transformation_mode, cubic_coeff_a_f=-0.75, mode_s=interpolate_mode, nearest_mode_s='floor')
    else:
        if g.opset >= 13:
            empty_roi = _optional_input_placeholder_tensor(g)
        else:
            empty_roi = g.op('Constant', value_t=torch.tensor([], dtype=torch.float32))
        return g.op('Resize', input, empty_roi, scales, coordinate_transformation_mode_s=coordinate_transformation_mode, cubic_coeff_a_f=-0.75, mode_s=interpolate_mode, nearest_mode_s='floor')

@final
def _align_series(self, other: Series, join: AlignJoin='outer', axis: Axis | None=None, level=None, fill_value=None) -> tuple[Self, Series, Index | None]:
    is_series = isinstance(self, ABCSeries)
    if not is_series and axis is None or axis not in [None, 0, 1]:
        raise ValueError('Must specify axis=0 or 1')
    if is_series and axis == 1:
        raise ValueError('cannot align series to a series other than axis 0')
    if not axis:
        if self.index.equals(other.index):
            (join_index, lidx, ridx) = (None, None, None)
        else:
            (join_index, lidx, ridx) = self.index.join(other.index, how=join, level=level, return_indexers=True)
        if is_series:
            left = self._reindex_indexer(join_index, lidx)
        elif lidx is None or join_index is None:
            left = self.copy(deep=False)
        else:
            new_mgr = self._mgr.reindex_indexer(join_index, lidx, axis=1)
            left = self._constructor_from_mgr(new_mgr, axes=new_mgr.axes)
        right = other._reindex_indexer(join_index, ridx)
    else:
        fdata = self._mgr
        join_index = self.axes[1]
        (lidx, ridx) = (None, None)
        if <MASK>:
            (join_index, lidx, ridx) = join_index.join(other.index, how=join, level=level, return_indexers=True)
        if lidx is not None:
            bm_axis = self._get_block_manager_axis(1)
            fdata = fdata.reindex_indexer(join_index, lidx, axis=bm_axis)
        left = self._constructor_from_mgr(fdata, axes=fdata.axes)
        right = other._reindex_indexer(join_index, ridx)
    fill_na = notna(fill_value)
    if fill_na:
        left = left.fillna(fill_value)
        right = right.fillna(fill_value)
    return (left, right, join_index)

def batch(self, spec: 'DynamicRaggedShape.Spec', batch_size) -> 'DynamicRaggedShape.Spec':
    if spec.num_row_partitions:
        new_head = _batch_rp_spec_head(spec._row_partitions[0], batch_size)
        new_tail = [_batch_rp_spec(rp, batch_size) for rp in spec._row_partitions]
        new_rp = [new_head] + new_tail
        new_static_inner_shape = _batch_static_inner_shape(spec._static_inner_shape, batch_size)
        return DynamicRaggedShape.Spec(row_partitions=new_rp, static_inner_shape=new_static_inner_shape, dtype=spec.dtype)
    elif <MASK>:
        if spec.inner_rank == 0:
            return DynamicRaggedShape.Spec._from_tensor_shape([None], 0, dtype=spec.dtype)
        else:
            new_head = RowPartitionSpec(uniform_row_length=spec._dimension(0), dtype=spec.dtype)
            new_static_inner_shape = _batch_static_inner_shape(spec._static_inner_shape, batch_size)
            return DynamicRaggedShape.Spec(row_partitions=[new_head], static_inner_shape=new_static_inner_shape, dtype=spec.dtype)
    else:
        return DynamicRaggedShape.Spec(row_partitions=[], static_inner_shape=_batch_tensor_shape(spec._static_inner_shape, batch_size), dtype=spec.dtype)

def _safe_repr(object, context, maxlevels, level, changed_only=False):
    """Same as the builtin _safe_repr, with added support for Estimator
    objects."""
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if issubclass(typ, dict) and r is dict.__repr__:
        if <MASK>:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if issubclass(typ, list) and r is list.__repr__ or (issubclass(typ, tuple) and r is tuple.__repr__):
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            (orepr, oreadable, orecur) = _safe_repr(o, context, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if not oreadable:
                readable = False
            if orecur:
                recursive = True
        del context[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

def _tree_map_with_path(func: Callable[..., Any], tree: Any, *dynamic_shapes: Any, tree_name: Optional[str]=None) -> Any:
    """
    Customized tree_map for mapping pytrees to dynamic_shapes.

    For built-in types (e.g., standard collections) this behaves exactly like tree_map.

    OTOH for a user-defined class C registered with pytree, we cannot assume that a C
    containing tensors can be mapped to a C containing dynamic shapes (i.e., C may not
    be a polymorphic container). In that case we use the flattened form of C instead.
    Thus a C(**tensors) that flattens to (**tensors) will map to (**dynamic_shapes).

    Args:
        func: function to apply to each (int, float, str, bool, None, torch.Tensor)
        tree: input pytree
        dynamic_shapes: zero or more (typically one) dynamic_shapes to match

    Returns:
        output pytree mapping func to each (int, float, str, bool, None, torch.Tensor)
    """

    def is_leaf(t):
        return _get_node_type(t) not in BUILTIN_TYPES

    def f(path, t, *dynamic_shapes):
        typ = _get_node_type(t)
        if typ in SUPPORTED_NODES:
            return tree_map_with_path(f, SUPPORTED_NODES[typ].flatten_fn(t)[0], *dynamic_shapes, is_leaf=is_leaf)
        else:
            return func(path, t, *dynamic_shapes)
    try:
        return tree_map_with_path(f, tree, *dynamic_shapes, is_leaf=is_leaf)
    except ValueError as e:
        if <MASK>:
            assert dynamic_shapes, 'Cannot be a mismatch if there is no dynamic_shapes'
            assert tree_name, 'Must provide a tree_name when there might be a mismatch'

            def _key(type_, context, i):
                if type_ is dict:
                    return MappingKey(context[i])
                if type_ in (list, tuple):
                    assert context is None
                    return SequenceKey(i)
                raise AssertionError(f'Did not expect type {type_}')

            def raise_mismatch_error(msg):
                from torch._dynamo.exc import UserError, UserErrorType
                raise UserError(UserErrorType.INVALID_INPUT, f'Detected mismatch between the structure of `{tree_name}` and `dynamic_shapes`: {msg}', case_name='dynamic_shapes_validation')

            def _compare(tree, dynamic_shapes, path):
                rendered_path = keystr(path)
                if isinstance(tree, LeafSpec):
                    return
                if isinstance(dynamic_shapes, LeafSpec):
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is not')
                if tree.type != dynamic_shapes.type:
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is a {dynamic_shapes.type}')
                if len(tree.children_specs) != len(dynamic_shapes.children_specs):
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` has {len(tree.children_specs)} elements, but `dynamic_shapes{rendered_path}` has {len(dynamic_shapes.children_specs)} elements')
                if tree.type is dict:
                    if sorted(tree.context) != sorted(dynamic_shapes.context):
                        raise_mismatch_error(f'`{tree_name}{rendered_path}` has keys {tree.context}, but `dynamic_shapes{rendered_path}` has keys {dynamic_shapes.context}')
                    _remap = dict(zip(dynamic_shapes.context, dynamic_shapes.children_specs))
                    dynamic_shapes_children_specs = [_remap[k] for k in tree.context]
                else:
                    dynamic_shapes_children_specs = dynamic_shapes.children_specs
                for (i, (tree_, dynamic_shapes_)) in enumerate(zip(tree.children_specs, dynamic_shapes_children_specs)):
                    _compare(tree_, dynamic_shapes_, path + [_key(tree.type, tree.context, i)])
            (_, tree_spec) = tree_flatten(tree, is_leaf=is_leaf)
            for other_tree in dynamic_shapes:
                (_, other_tree_spec) = tree_flatten(other_tree, is_leaf)
                _compare(tree_spec, other_tree_spec, [])
        raise

def _apply_native_binary(fn, *args, **kwargs):
    if <MASK>:
        return NATIVE_BINARY_MAP[fn](*args, **kwargs)
    if fn in NATIVE_INPLACE_BINARY_FNS:
        return NATIVE_INPLACE_BINARY_MAP[fn](*args, **kwargs)
    return NotImplemented

def __init__(self, value, output_field=None, *, config=None, invert=False, search_type='plain'):
    if isinstance(value, LexemeCombinable):
        search_type = 'raw'
    self.function = self.SEARCH_TYPES.get(search_type)
    if self.function is None:
        raise ValueError("Unknown search_type argument '%s'." % search_type)
    if <MASK>:
        value = Value(value)
    expressions = (value,)
    self.config = SearchConfig.from_parameter(config)
    if self.config is not None:
        expressions = [self.config, *expressions]
    self.invert = invert
    super().__init__(*expressions, output_field=output_field)

def shares_memory(left, right) -> bool:
    """
    Pandas-compat for np.shares_memory.
    """
    if isinstance(left, np.ndarray) and isinstance(right, np.ndarray):
        return np.shares_memory(left, right)
    elif isinstance(left, np.ndarray):
        return shares_memory(right, left)
    if isinstance(left, RangeIndex):
        return False
    if isinstance(left, MultiIndex):
        return shares_memory(left._codes, right)
    if isinstance(left, (Index, Series)):
        if isinstance(right, (Index, Series)):
            return shares_memory(left._values, right._values)
        return shares_memory(left._values, right)
    if isinstance(left, NDArrayBackedExtensionArray):
        return shares_memory(left._ndarray, right)
    if isinstance(left, pd.core.arrays.SparseArray):
        return shares_memory(left.sp_values, right)
    if isinstance(left, pd.core.arrays.IntervalArray):
        return shares_memory(left._left, right) or shares_memory(left._right, right)
    if isinstance(left, ArrowExtensionArray):
        if isinstance(right, ArrowExtensionArray):
            left_pa_data = left._pa_array
            right_pa_data = right._pa_array
            left_buf1 = left_pa_data.chunk(0).buffers()[1]
            right_buf1 = right_pa_data.chunk(0).buffers()[1]
            return left_buf1.address == right_buf1.address
        else:
            return np.shares_memory(left, right)
    if isinstance(left, BaseMaskedArray) and isinstance(right, BaseMaskedArray):
        return np.shares_memory(left._data, right._data) or np.shares_memory(left._mask, right._mask)
    if <MASK>:
        arr = left._mgr.blocks[0].values
        return shares_memory(arr, right)
    raise NotImplementedError(type(left), type(right))

def _check_tensorbox(nodes: Optional[_NodeOrNodes]) -> None:
    if nodes is None:
        pass
    elif <MASK>:
        for node in nodes:
            _check_tensorbox(node)
    elif isinstance(nodes, dict):
        for node in nodes.values():
            _check_tensorbox(node)
    else:
        assert isinstance(nodes, (ExpandView, DynamicScalar, AssertScalar, TensorBox, sympy.logic.boolalg.Boolean, Expr, int, EffectfulKernel, ShapeAsConstantBuffer)), f'Found {type(nodes)}, which is not a supported top level IR node. See [Note: Inductor IR]'

@ops.RegisterGradient('Reshape')
def _ReshapeGrad(op: ops.Operation, grad):
    """Defines the gradient for `array_ops.reshape()`."""
    input_shape = op.inputs[0].shape
    if <MASK>:
        input_shape_as_list = input_shape.as_list()
        undefined_dims = []
        has_zero_dim = False
        for (i, dim) in enumerate(input_shape_as_list):
            if dim is None:
                undefined_dims.append(i)
            elif dim == 0:
                has_zero_dim = True
        if len(undefined_dims) == 1 and (not has_zero_dim):
            input_shape_as_list[undefined_dims[0]] = -1
            return [array_ops.reshape(_IndexedSlicesToTensorNoWarning(grad), input_shape_as_list), None]
    return [array_ops.reshape(_IndexedSlicesToTensorNoWarning(grad), array_ops.shape(op.inputs[0])), None]

def _cumsumprod_common(func, init, a: TensorLikeType, dim: int, *, dtype: Optional[torch.dtype]=None, out: Optional[Tensor]=None) -> TensorLikeType:
    ndim = a.ndim
    dim = utils.canonicalize_dim(ndim, dim)
    if <MASK>:
        return func(a.unsqueeze(0), dim=0, dtype=dtype, out=out)
    a = a.unsqueeze(dim + 1)
    rg = torch.arange(a.shape[dim], device=a.device)
    mask = rg.unsqueeze(1) <= rg
    for _ in range(ndim - dim - 1):
        mask = mask.unsqueeze(-1)
    masked_a = torch.where(mask, a, init)
    return func(masked_a, dim=dim, dtype=dtype, out=out)

def get_operator_enum(reduce_, use_new_options=False):
    if use_new_options:
        if reduce_ == 'sum':
            return 'REDUCE_ADD'
        elif reduce_ == 'prod':
            return 'REDUCE_MULTIPLY'
        elif reduce_ == 'mean':
            return 'REDUCE_MEAN'
        elif reduce_ == 'amax':
            return 'REDUCE_MAXIMUM'
        elif reduce_ == 'amin':
            return 'REDUCE_MINIMUM'
        torch._check(False, lambda : 'reduce argument must be either sum, prod, mean, amax or amin.')
        return
    else:
        if <MASK>:
            return 'REDUCE_ADD'
        elif reduce_ == 'multiply':
            return 'REDUCE_MULTIPLY'
        torch._check(False, lambda : 'reduce argument must be either add or multiply.')
        return

def convert(self, values: np.ndarray, nan_rep, encoding: str, errors: str) -> tuple[np.ndarray, np.ndarray] | tuple[Index, Index]:
    """
        Convert the data from this selection to the appropriate pandas type.
        """
    assert isinstance(values, np.ndarray), type(values)
    if values.dtype.fields is not None:
        values = values[self.cname].copy()
    val_kind = self.kind
    values = _maybe_convert(values, val_kind, encoding, errors)
    kwargs = {}
    kwargs['name'] = self.index_name
    if <MASK>:
        kwargs['freq'] = self.freq
    factory: type[Index | DatetimeIndex] = Index
    if lib.is_np_dtype(values.dtype, 'M') or isinstance(values.dtype, DatetimeTZDtype):
        factory = DatetimeIndex
    elif values.dtype == 'i8' and 'freq' in kwargs:
        factory = lambda x, **kwds: PeriodIndex.from_ordinals(x, freq=kwds.get('freq', None))._rename(kwds['name'])
    try:
        new_pd_index = factory(values, **kwargs)
    except UnicodeEncodeError as err:
        if errors == 'surrogatepass' and get_option('future.infer_string') and str(err).endswith('surrogates not allowed') and HAS_PYARROW:
            new_pd_index = factory(values, dtype=StringDtype(storage='python', na_value=np.nan), **kwargs)
        else:
            raise
    except ValueError:
        if 'freq' in kwargs:
            kwargs['freq'] = None
        new_pd_index = factory(values, **kwargs)
    final_pd_index: Index
    if self.tz is not None and isinstance(new_pd_index, DatetimeIndex):
        final_pd_index = new_pd_index.tz_localize('UTC').tz_convert(self.tz)
    else:
        final_pd_index = new_pd_index
    return (final_pd_index, final_pd_index)

def serialize_output_spec(self, spec: ep.OutputSpec) -> OutputSpec:
    log.debug('[serialize_output_spec] %s', spec)
    if spec.kind == ep.OutputKind.USER_OUTPUT:
        return OutputSpec.create(user_output=UserOutputSpec(arg=self.serialize_argument_spec(spec.arg)))
    elif spec.kind == ep.OutputKind.LOSS_OUTPUT:
        assert isinstance(spec.arg, ep.TensorArgument)
        return OutputSpec.create(loss_output=LossOutputSpec(arg=TensorArgument(name=spec.arg.name)))
    elif spec.kind == ep.OutputKind.BUFFER_MUTATION:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return OutputSpec.create(buffer_mutation=BufferMutationSpec(arg=TensorArgument(name=spec.arg.name), buffer_name=spec.target))
    elif spec.kind == ep.OutputKind.PARAMETER_MUTATION:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return OutputSpec.create(parameter_mutation=ParameterMutationSpec(arg=TensorArgument(name=spec.arg.name), parameter_name=spec.target))
    elif spec.kind == ep.OutputKind.GRADIENT_TO_PARAMETER:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return OutputSpec.create(gradient_to_parameter=GradientToParameterSpec(arg=TensorArgument(name=spec.arg.name), parameter_name=spec.target))
    elif spec.kind == ep.OutputKind.GRADIENT_TO_USER_INPUT:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return OutputSpec.create(gradient_to_user_input=GradientToUserInputSpec(arg=TensorArgument(name=spec.arg.name), user_input_name=spec.target))
    elif spec.kind == ep.OutputKind.USER_INPUT_MUTATION:
        assert spec.target is not None
        assert isinstance(spec.arg, ep.TensorArgument)
        return OutputSpec.create(user_input_mutation=UserInputMutationSpec(arg=TensorArgument(name=spec.arg.name), user_input_name=spec.target))
    elif <MASK>:
        assert isinstance(spec.arg, ep.TokenArgument)
        return OutputSpec.create(token=OutputTokenSpec(arg=TokenArgument(name=spec.arg.name)))
    else:
        raise AssertionError(f'Unknown argument kind: {spec}')

def _join_monotonic(self, other: Index, how: JoinHow='left') -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert other.dtype == self.dtype
    assert self._can_use_libjoin and other._can_use_libjoin
    if self.equals(other):
        ret_index = other if how == 'right' else self
        return (ret_index, None, None)
    ridx: npt.NDArray[np.intp] | None
    lidx: npt.NDArray[np.intp] | None
    if how == 'left':
        if other.is_unique:
            join_index = self
            lidx = None
            ridx = self._left_indexer_unique(other)
        else:
            (join_array, lidx, ridx) = self._left_indexer(other)
            (join_index, lidx, ridx) = self._wrap_join_result(join_array, other, lidx, ridx, how)
    elif how == 'right':
        if self.is_unique:
            join_index = other
            lidx = other._left_indexer_unique(self)
            ridx = None
        else:
            (join_array, ridx, lidx) = other._left_indexer(self)
            (join_index, lidx, ridx) = self._wrap_join_result(join_array, other, lidx, ridx, how)
    elif how == 'inner':
        (join_array, lidx, ridx) = self._inner_indexer(other)
        (join_index, lidx, ridx) = self._wrap_join_result(join_array, other, lidx, ridx, how)
    elif <MASK>:
        (join_array, lidx, ridx) = self._outer_indexer(other)
        (join_index, lidx, ridx) = self._wrap_join_result(join_array, other, lidx, ridx, how)
    lidx = None if lidx is None else ensure_platform_int(lidx)
    ridx = None if ridx is None else ensure_platform_int(ridx)
    return (join_index, lidx, ridx)

def _check_supported(self, databases):
    errors = []
    for db in databases:
        if not router.allow_migrate_model(db, self.model):
            continue
        connection = connections[db]
        if self.model._meta.required_db_vendor and self.model._meta.required_db_vendor != connection.vendor:
            continue
        if <MASK>:
            errors.append(checks.Error('%s does not support JSONFields.' % connection.display_name, obj=self.model, id='fields.E180'))
    return errors

def _sample_rightmost_arg(self, opinfo, rightmost_arg_type, device, dtype, num_tensors, allow_higher_dtype_scalars, **_foreach_inputs_kwargs):
    if rightmost_arg_type == ForeachRightmostArgType.TensorList:
        return [sample_inputs_foreach(None, device, dtype, num_tensors, **_foreach_inputs_kwargs)]
    if rightmost_arg_type == ForeachRightmostArgType.Tensor:
        return [make_tensor((), device=device, dtype=dtype, noncontiguous=_foreach_inputs_kwargs['noncontiguous'], requires_grad=_foreach_inputs_kwargs.get('requires_grad', False))]
    should_use_simpler_scalars = opinfo.name == '_foreach_pow' and dtype in (torch.float16, torch.bfloat16)

    def sample_float():
        s = random.random()
        if should_use_simpler_scalars:
            return 1.0 if s > 0.5 else 2.0
        else:
            return 1.0 - s
    high = 2 if should_use_simpler_scalars else 9
    if rightmost_arg_type == ForeachRightmostArgType.ScalarList:
        scalarlist_list = []
        scalarlist_list.append([random.randint(0, high) + 1 for _ in range(num_tensors)])
        if <MASK>:
            scalarlist_list.append([sample_float() for _ in range(num_tensors)])
        if allow_higher_dtype_scalars or dtype.is_complex:
            scalarlist_list.append([complex(sample_float(), sample_float()) for _ in range(num_tensors)])
            scalarlist_list.append([1, 2.0, 3.0 + 4.5j] + [3.0 for _ in range(num_tensors - 3)])
            scalarlist_list.append([True, 1, 2.0, 3.0 + 4.5j] + [3.0 for _ in range(num_tensors - 4)])
        return scalarlist_list
    if rightmost_arg_type == ForeachRightmostArgType.Scalar:
        scalars = []
        scalars.append(random.randint(1, high + 1))
        if allow_higher_dtype_scalars or dtype.is_floating_point:
            scalars.append(sample_float())
        if allow_higher_dtype_scalars or dtype.is_complex:
            scalars.append(complex(sample_float(), sample_float()))
        scalars.append(True)
        return scalars
    raise AssertionError(f'Invalid rightmost_arg_type of {rightmost_arg_type}')

@register_lowering(torch.ops.mkl._mkl_linear)
def mkl_packed_linear(x: TensorBox, packed_w: TensorBox, orig_w: TensorBox, b: Optional[TensorBox], batch_size, *, layout=None):
    choices: list[ChoiceCaller] = []
    if config.max_autotune or config.max_autotune_gemm:
        transposed_w = permute(orig_w, [1, 0])
        (*_, layout, x, transposed_w) = mm_args(x, transposed_w, layout=layout)
        if use_cpp_gemm_template(layout, x, transposed_w):
            CppGemmTemplate.add_choices(choices, layout, [x, packed_w, orig_w], trans_w=True, input_indices=[0, 2])
    if <MASK>:
        choices.append(aten_mkl_linear.bind((x, packed_w, orig_w), layout, B=None, batch_size=batch_size))
    assert packed_w.get_name() in V.graph.constants
    assert orig_w.get_name() in V.graph.constants
    input_gen_fns = {1: lambda x: V.graph.constants[x.get_name()], 2: lambda x: V.graph.constants[x.get_name()]}
    result: TensorBox = autotune_select_algorithm('packed_linear', choices, [x, packed_w, orig_w], layout, input_gen_fns=input_gen_fns)
    if b is not None:
        result = add(result, b)
    return result

def _postprocess_flat_outputs(outputs):
    """Validates flat outputs and adds back device assignments.

  Args:
    outputs: Output from `computation` inside `xla.compile`.

  Returns:
    Tensors and Operations extracted from outputs.
  """
    if outputs is None:
        outputs = tuple()
    if not isinstance(outputs, collections_abc.Sequence):
        outputs = (outputs,)
    outputs += (control_flow_ops.no_op(),)
    try:
        outputs = [o if isinstance(o, ops.Operation) else ops.convert_to_tensor(o) for o in outputs]
    except Exception as e:
        raise ValueError('XLA computation function return values must all either be Operations or convertible to Tensors. Got error: "%s"' % str(e))
    output_operations = [o for o in outputs if isinstance(o, ops.Operation)]
    output_tensors = [o for o in outputs if not isinstance(o, ops.Operation)]
    if <MASK>:
        raise ValueError('XLA computation function must return zero or more Tensor values followed by zero or more Operations.')
    new_output_tensors = []
    for t in output_tensors:
        with ops.device(t.device if t.device else ''):
            new_output_tensors.append(array_ops.identity(t))
    return (new_output_tensors, output_operations)

def vmapify_autograd_function(autograd_function, in_dims, batch_size, randomness):

    def forward(*operands):
        (outputs, out_dims) = restore_vmap(autograd_function.forward, in_dims, batch_size, randomness)(*operands)
        if <MASK>:
            return (outputs, out_dims)
        else:
            return (*outputs, out_dims)

    def setup_context(ctx, inputs, outputs):
        (outputs, out_dims) = unpack_outputs(outputs)
        key = id(Generated)

        def inner(inputs, outputs):
            wrapped_ctx = CtxCustomSave(ctx, current_level())
            autograd_function.setup_context(wrapped_ctx, inputs, outputs)
            input_shapes = tuple((inp.shape if isinstance(inp, torch.Tensor) else None for inp in inputs))
            if not hasattr(ctx, '_pt_input_shapes'):
                ctx._pt_input_shapes = {}
            ctx._pt_input_shapes.update({key: input_shapes})
            if not hasattr(ctx, '_pt_saved_tensors_bdims_stack'):
                ctx._pt_saved_tensors_bdims_stack = {}
            ctx._pt_saved_tensors_bdims_stack.update({key: wrapped_ctx._pt_saved_tensors_bdims})
        restore_vmap(inner, (in_dims, out_dims), batch_size, randomness)(inputs, outputs)
        if not hasattr(ctx, '_pt_out_dims'):
            ctx._pt_out_dims = {}
        ctx._pt_out_dims.update({key: out_dims})

    def jvp(ctx, *tangents):
        key = id(Generated)

        def jvp_no_context(saved_tensors, tangents):
            wrapped_ctx = CtxWithSavedTensors(ctx, saved_tensors)
            return autograd_function.jvp(wrapped_ctx, *tangents)
        tangent_in_dims = get_tangents_in_dims(in_dims, tangents)
        (out_tangents, out_tangents_dims) = restore_vmap(jvp_no_context, (ctx._pt_saved_tensors_bdims_stack[key], tangent_in_dims), batch_size, randomness)(ctx.saved_tensors, tangents)
        result = reductify(out_tangents, out_tangents_dims, ctx._pt_out_dims[key], batch_size)
        if isinstance(result, torch.Tensor):
            return (result, None)
        else:
            return (*result, None)

    def backward(ctx, *grad_outputs):
        key = id(Generated)
        grad_outputs_ = grad_outputs[:-1]
        grad_outputs_in_dims = ctx._pt_out_dims[key]
        if not isinstance(grad_outputs_in_dims, tuple):
            grad_outputs_in_dims = (grad_outputs_in_dims,)
        grad_outputs_in_dims = tuple((in_dim if grad_output is not None else None for (grad_output, in_dim) in zip(grad_outputs_, grad_outputs_in_dims)))

        def backward_no_context(inputs):
            (saved_tensors, grad_outputs) = inputs
            wrapped_ctx = CtxWithSavedTensors(ctx, saved_tensors)
            return autograd_function.backward(wrapped_ctx, *grad_outputs)
        (grad_ins, grad_ins_dims) = restore_vmap(backward_no_context, ((ctx._pt_saved_tensors_bdims_stack[key], grad_outputs_in_dims),), batch_size, randomness)((ctx.saved_tensors, grad_outputs_))
        result = reductify(grad_ins, grad_ins_dims, in_dims, batch_size, ctx._pt_input_shapes[key])
        return result
    name = f'Vmapped{autograd_function.__name__}'
    Generated = type(name, (torch.autograd.Function,), {'forward': staticmethod(forward), 'backward': staticmethod(backward), 'jvp': staticmethod(jvp), 'setup_context': staticmethod(setup_context), 'generate_vmap_rule': True})
    return Generated

def shard_dim_alltoall(input, gather_dim, shard_dim, mesh, mesh_dim):
    if mesh.device_type == 'cpu' and local_tensor_mode() is None:
        warning_once(logger, 'CPU process group does not support alltoall yet, falling back with allgather + chunk!')
        out = funcol.all_gather_tensor(input, gather_dim, (mesh, mesh_dim))
        if <MASK>:
            out = out.wait()
        out = torch.chunk(out, mesh.size(mesh_dim), dim=shard_dim)[mesh.get_local_rank(mesh_dim)]
        return out.contiguous()
    group_name = funcol._resolve_group_name((mesh, mesh_dim))
    return torch.ops._dtensor.shard_dim_alltoall(input, gather_dim, shard_dim, group_name)

def length_of_indexer(indexer, target=None) -> int:
    """
    Return the expected length of target[indexer]

    Returns
    -------
    int
    """
    if target is not None and isinstance(indexer, slice):
        target_len = len(target)
        start = indexer.start
        stop = indexer.stop
        step = indexer.step
        if start is None:
            start = 0
        elif <MASK>:
            start += target_len
        if stop is None or stop > target_len:
            stop = target_len
        elif stop < 0:
            stop += target_len
        if step is None:
            step = 1
        elif step < 0:
            (start, stop) = (stop + 1, start + 1)
            step = -step
        return (stop - start + step - 1) // step
    elif isinstance(indexer, (ABCSeries, ABCIndex, np.ndarray, list)):
        if isinstance(indexer, list):
            indexer = np.array(indexer)
        if indexer.dtype == bool:
            return indexer.sum()
        return len(indexer)
    elif isinstance(indexer, range):
        return (indexer.stop - indexer.start) // indexer.step
    elif not is_list_like_indexer(indexer):
        return 1
    raise AssertionError('cannot find the length of the indexer')

def get_aggregation(self, using, aggregate_exprs):
    """
        Return the dictionary with the values of the existing aggregations.
        """
    if not aggregate_exprs:
        return {}
    refs_subquery = False
    refs_window = False
    replacements = {}
    annotation_select_mask = self.annotation_select_mask
    for (alias, aggregate_expr) in aggregate_exprs.items():
        self.check_alias(alias)
        aggregate = aggregate_expr.resolve_expression(self, allow_joins=True, reuse=None, summarize=True)
        if not aggregate.contains_aggregate:
            raise TypeError('%s is not an aggregate expression' % alias)
        self.append_annotation_mask([alias])
        aggregate_refs = aggregate.get_refs()
        refs_subquery |= any((getattr(self.annotations[ref], 'contains_subquery', False) for ref in aggregate_refs))
        refs_window |= any((getattr(self.annotations[ref], 'contains_over_clause', True) for ref in aggregate_refs))
        aggregate = aggregate.replace_expressions(replacements)
        self.annotations[alias] = aggregate
        replacements[Ref(alias, aggregate)] = aggregate
    aggregates = {alias: self.annotations.pop(alias) for alias in aggregate_exprs}
    self.set_annotation_mask(annotation_select_mask)
    (_, having, qualify) = self.where.split_having_qualify()
    has_existing_aggregation = any((getattr(annotation, 'contains_aggregate', True) for annotation in self.annotations.values())) or having
    set_returning_annotations = {alias for (alias, annotation) in self.annotation_select.items() if getattr(annotation, 'set_returning', False)}
    if isinstance(self.group_by, tuple) or self.is_sliced or has_existing_aggregation or refs_subquery or refs_window or qualify or self.distinct or self.combinator or set_returning_annotations:
        from django.db.models.sql.subqueries import AggregateQuery
        inner_query = self.clone()
        inner_query.subquery = True
        outer_query = AggregateQuery(self.model, inner_query)
        inner_query.select_for_update = False
        inner_query.select_related = False
        inner_query.set_annotation_mask(self.annotation_select)
        inner_query.clear_ordering(force=False)
        if not inner_query.distinct:
            if inner_query.default_cols and has_existing_aggregation:
                inner_query.group_by = (self.model._meta.pk.get_col(inner_query.get_initial_alias()),)
            inner_query.default_cols = False
            if <MASK>:
                annotation_mask = set()
                if isinstance(self.group_by, tuple):
                    for expr in self.group_by:
                        annotation_mask |= expr.get_refs()
                for aggregate in aggregates.values():
                    annotation_mask |= aggregate.get_refs()
                for (annotation_alias, annotation) in self.annotation_select.items():
                    if annotation.get_group_by_cols():
                        annotation_mask.add(annotation_alias)
                inner_query.set_annotation_mask(annotation_mask)
                annotation_mask |= set_returning_annotations
        col_refs = {}
        for (alias, aggregate) in aggregates.items():
            replacements = {}
            for col in self._gen_cols([aggregate], resolve_refs=False):
                if not (col_ref := col_refs.get(col)):
                    index = len(col_refs) + 1
                    col_alias = f'__col{index}'
                    col_ref = Ref(col_alias, col)
                    col_refs[col] = col_ref
                    inner_query.add_annotation(col, col_alias)
                replacements[col] = col_ref
            outer_query.annotations[alias] = aggregate.replace_expressions(replacements)
        if inner_query.select == () and (not inner_query.default_cols) and (not inner_query.annotation_select_mask):
            inner_query.select = (self.model._meta.pk.get_col(inner_query.get_initial_alias()),)
    else:
        outer_query = self
        self.select = ()
        self.selected = None
        self.default_cols = False
        self.extra = {}
        if self.annotations:
            replacements = {Ref(alias, annotation): annotation for (alias, annotation) in self.annotations.items()}
            self.annotations = {alias: aggregate.replace_expressions(replacements) for (alias, aggregate) in aggregates.items()}
        else:
            self.annotations = aggregates
        self.set_annotation_mask(aggregates)
    empty_set_result = [expression.empty_result_set_value for expression in outer_query.annotation_select.values()]
    elide_empty = not any((result is NotImplemented for result in empty_set_result))
    outer_query.clear_ordering(force=True)
    outer_query.clear_limits()
    outer_query.select_for_update = False
    outer_query.select_related = False
    compiler = outer_query.get_compiler(using, elide_empty=elide_empty)
    result = compiler.execute_sql(SINGLE)
    if result is None:
        result = empty_set_result
    else:
        cols = outer_query.annotation_select.values()
        converters = compiler.get_converters(cols)
        rows = compiler.apply_converters((result,), converters)
        if compiler.has_composite_fields(cols):
            rows = compiler.composite_fields_to_tuples(rows, cols)
        result = next(rows)
    return dict(zip(outer_query.annotation_select, result))

def _exec_func_with_dst(self, dst, exec_mode, method, *args):
    if <MASK>:
        if len(args) == 1 and isinstance(args[0], list):
            return method(*args[0])
        return method(*args)
    elif ExecMode.RPC_SYNC == exec_mode:
        return rpc.rpc_sync(worker_name(dst), method, args=args)
    elif ExecMode.REMOTE == exec_mode:
        return rpc.remote(worker_name(dst), method, args=args).to_here()
    elif ExecMode.RPC_ASYNC == exec_mode:
        fut = rpc.rpc_async(worker_name(dst), method, args=args)
        return fut.wait()
    else:
        raise ValueError(f'Unrecognized ExecMode {exec_mode}')

def add(self, kp: KeyPath, src: Source):
    assert len(kp) > 0
    (*path, leaf) = kp
    node = self.root
    for k in path:
        if <MASK>:
            node[k] = {}
        node = node[k]
    node[leaf] = src

def _create_prev_run_var(self, var_name, shape=None, initializer=None, partitioner=None):
    with ops.Graph().as_default() as g:
        with self.session(graph=g) as sess:
            var = variable_scope.get_variable(var_name, shape=shape, initializer=initializer, partitioner=partitioner)
            self._write_checkpoint(sess)
            if <MASK>:
                self.assertTrue(isinstance(var, variables.PartitionedVariable))
                var = var._get_variable_list()
            return (var, self.evaluate(var))

def remove_cookie_by_name(cookiejar, name, domain=None, path=None):
    """Unsets a cookie by name, by default over all domains and paths.

    Wraps CookieJar.clear(), is O(n).
    """
    clearables = []
    for cookie in cookiejar:
        if cookie.name != name:
            continue
        if domain is not None and domain != cookie.domain:
            continue
        if <MASK>:
            continue
        clearables.append((cookie.domain, cookie.path, cookie.name))
    for (domain, path, name) in clearables:
        cookiejar.clear(domain, path, name)

def decorator_fn(cls):
    if <MASK>:
        raise TypeError('Expected `cls` to be a TypeSpec; got %r' % (cls,))
    if cls in _TYPE_SPEC_TO_NAME:
        raise ValueError('Class %s.%s has already been registered with name %s.' % (cls.__module__, cls.__name__, _TYPE_SPEC_TO_NAME[cls]))
    if name in _NAME_TO_TYPE_SPEC:
        raise ValueError('Name %s has already been registered for class %s.%s.' % (name, _NAME_TO_TYPE_SPEC[name].__module__, _NAME_TO_TYPE_SPEC[name].__name__))
    _TYPE_SPEC_TO_NAME[cls] = name
    _NAME_TO_TYPE_SPEC[name] = cls
    return cls

@register_lowering(aten.convolution)
def convolution(x: TensorBox, weight: TensorBox, bias: Optional[TensorBox], stride: Sequence[int], padding: Sequence[int], dilation: Sequence[int], transposed: bool, output_padding: Sequence[int], groups: int):
    stride = tuple(stride)
    padding = tuple(padding)
    dilation = tuple(dilation)
    output_padding = tuple(output_padding)
    if <MASK>:
        groups = V.graph.sizevars.guard_int(groups)
    assert isinstance(groups, int)
    stride = tuple(V.graph.sizevars.guard_int_seq(stride))
    padding = tuple(V.graph.sizevars.guard_int_seq(padding))
    kwargs: ConvLayoutParams = {'stride': stride, 'padding': padding, 'dilation': dilation, 'transposed': transposed, 'output_padding': output_padding, 'groups': groups}
    device_type = ir.get_device_type(x)
    if len(x.get_size()) == len(weight.get_size()) - 1:
        return L[aten.squeeze](convolution(L[aten.expand](x, [1, *x.get_size()]), weight, bias, **kwargs), dim=0)
    (out_chan, in_chan, *kernel_shape) = V.graph.sizevars.guard_int_seq(weight.get_size())
    if len(x.get_size()) == 3 and len(kernel_shape) == 1 and (device_type == 'xpu'):
        kwargs.update({'stride': (1,) + stride, 'padding': (0,) + padding, 'dilation': (1,) + dilation, 'output_padding': (0,) + output_padding})
        x = L[aten.unsqueeze](x, dim=2)
        weight = L[aten.unsqueeze](weight, dim=2)
        return L[aten.squeeze](convolution(x, weight, bias, **kwargs), dim=2)
    ndim = len(kernel_shape)
    stride = pad_listlike(stride, ndim)
    padding = pad_listlike(padding, ndim)
    dilation = pad_listlike(dilation, ndim)
    output_padding = pad_listlike(output_padding, ndim)

    def channels_last_conv():
        if V.graph.layout_opt and ndim == 2:
            return True
        layout = conv_layout(x, weight, None, **kwargs)
        req_stride_order = ir.get_stride_order(V.graph.sizevars.size_hints(layout.stride))
        return req_stride_order == ir.NHWC_STRIDE_ORDER
    autotuning_gemm = config.max_autotune or config.max_autotune_gemm
    if (config.conv_1x1_as_mm or (autotuning_gemm and channels_last_conv())) and is_ones(kernel_shape) and is_ones(stride) and is_zeros(padding) and is_ones(dilation) and (not transposed) and is_zeros(output_padding) and (groups == 1) and V.graph.sizevars.statically_known_gt(sympy_product(x.get_size()), 0):
        return convert_1x1_conv_to_mm(x, weight, bias)
    if bias is not None and device_type != 'cpu':
        result = convolution(x, weight, None, **kwargs)
        return L[aten.add](result, L[aten.view](bias, [result.get_size()[1]] + ndim * [1]))
    x.realize()
    weight.realize()
    if V.graph.layout_opt and ndim == 2:
        V.graph.num_channels_last_conv += 1
        x = ir.ExternKernel.require_channels_last(x)
        weight = ir.ExternKernel.require_channels_last(weight)
        layout = conv_layout(x, weight, None, **kwargs)
    else:
        layout = conv_layout(x, weight, None, **kwargs)
        req_stride_order = ir.get_stride_order(V.graph.sizevars.size_hints(layout.stride))
        x = ir.ExternKernel.require_stride_order(x, req_stride_order)
        weight = ir.ExternKernel.require_stride_order(weight, req_stride_order)
    ordered_kwargs_for_cpp_kernel = ['stride', 'padding', 'dilation', 'transposed', 'output_padding', 'groups']
    if bias is None:
        args = [x, weight]
        kwargs['bias'] = None
        ordered_kwargs_for_cpp_kernel.insert(0, 'bias')
    else:
        args = [x, weight, bias]
        bias.realize()
        bias.freeze_layout()
        V.graph.sizevars.guard_int_seq(bias.get_size())
    choices = []
    if torch._inductor.utils._use_conv_autotune_backend('ATEN'):
        choices = [aten_convolution.bind(args, layout, ordered_kwargs_for_cpp_kernel, **kwargs)]
    if torch._inductor.utils._use_conv_autotune_backend('TRITON') and use_triton_template(layout) and is_ones(dilation) and (not transposed) and is_zeros(output_padding) and V.graph.sizevars.statically_known_equals(in_chan * groups, x.get_size()[1]):
        if is_ones(kernel_shape) and is_ones(stride) and is_zeros(padding) and (groups == 1):
            choices.append(aten_conv1x1_via_mm.bind(args, layout))
        conv_configs = V.choices.get_conv_configs(device_type)
        dtype_size = x.get_dtype().itemsize
        for cfg in conv_configs(sympy_product([x.get_size()[0], *x.get_size()[2:]]), out_chan, in_chan, dtype_size=dtype_size):
            if ndim == 2:
                conv2d_template.maybe_append_choice(choices, input_nodes=(x, weight), layout=layout, KERNEL_H=kernel_shape[0], KERNEL_W=kernel_shape[1], STRIDE_H=stride[0], STRIDE_W=stride[1], PADDING_H=padding[0], PADDING_W=padding[1], GROUPS=groups, UNROLL=is_ones(kernel_shape), ALLOW_TF32=torch.backends.cudnn.allow_tf32, num_stages=cfg.num_stages, num_warps=cfg.num_warps, **cfg.kwargs)
            elif ndim == 3:
                conv3d_template.maybe_append_choice(choices, input_nodes=(x, weight), layout=layout, KERNEL_D=kernel_shape[0], KERNEL_H=kernel_shape[1], KERNEL_W=kernel_shape[2], STRIDE_D=stride[0], STRIDE_H=stride[1], STRIDE_W=stride[2], PADDING_D=padding[0], PADDING_H=padding[1], PADDING_W=padding[2], GROUPS=groups, UNROLL=is_ones(kernel_shape), ALLOW_TF32=torch.backends.cudnn.allow_tf32, num_stages=cfg.num_stages, num_warps=cfg.num_warps, **cfg.kwargs)
    if use_ck_conv_template(layout):
        CKGroupedConvFwdTemplate.add_ck_conv_choices(choices, layout, input_nodes=(x, weight) + ((bias,) if bias is not None else tuple()), stride=stride, padding=padding, dilation=dilation, groups=groups, n_spatial_dimensions=ndim)
    return autotune_select_algorithm('convolution', choices, args, layout)

@staticmethod
def raise_if_triton_unavailable(evice: torch.types.Device=None) -> None:
    import triton.backends
    if <MASK>:
