def standardize_weights(y, sample_weight=None, class_weight=None, sample_weight_mode=None):
    """Performs sample weight validation and standardization.

  Everything gets normalized to a single sample-wise (or timestep-wise)
  weight array. If both `sample_weight` and `class_weight` are provided,
  the weights are multiplied.

  Args:
      y: Numpy array or Tensor of model targets to be weighted.
      sample_weight: User-provided `sample_weight` argument.
      class_weight: User-provided `class_weight` argument.
      sample_weight_mode: One of `None` or `"temporal"`. `"temporal"` indicated
        that we expect 2D weight data that will be applied to the last 2
        dimensions of the targets (i.e. we are weighting timesteps, not
        samples).

  Returns:
      A numpy array of target weights, one entry per sample to weight.

  Raises:
      ValueError: In case of invalid user-provided arguments.
  """
    if isinstance(sample_weight, tuple):
        sample_weight = sample_weight[0]
    if sample_weight_mode is not None and sample_weight_mode != 'samplewise':
        if sample_weight_mode != 'temporal':
            raise ValueError('"sample_weight_mode should be None or "temporal". Found: ' + str(sample_weight_mode))
        if len(y.shape) < 3:
            raise ValueError('Found a sample_weight array for an input with shape ' + str(y.shape) + '. Timestep-wise sample weighting (use of sample_weight_mode="temporal") is restricted to outputs that are at least 3D, i.e. that have a time dimension.')
        if sample_weight is not None and len(sample_weight.shape) != 2:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + '. In order to use timestep-wise sample weighting, you should pass a 2D sample_weight array.')
    elif sample_weight is not None and len(sample_weight.shape) != 1:
        raise ValueError('Found a sample_weight array with shape {}. In order to use timestep-wise sample weights, you should specify sample_weight_mode="temporal" in compile(); founssd "{}" instead. If you just mean to use sample-wise weights, make sure your sample_weight array is 1D.'.format(sample_weight.shape, sample_weight_mode))
    if <MASK>:
        if len(sample_weight.shape) > len(y.shape):
            raise ValueError('Found a sample_weight with shape' + str(sample_weight.shape) + '.Expected sample_weight with rank less than or equal to ' + str(len(y.shape)))
        if not tensor_util.is_tf_type(sample_weight) and y.shape[:sample_weight.ndim] != sample_weight.shape:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + ' for an input with shape ' + str(y.shape) + '. sample_weight cannot be broadcast.')
    class_sample_weight = None
    if isinstance(class_weight, dict):
        if len(y.shape) > 2:
            raise ValueError('`class_weight` not supported for 3+ dimensional targets.')
        if tensor_util.is_tf_type(y):
            keys = np.array(sorted(class_weight.keys()))
            values = np.array([class_weight[i] for i in keys])
            weight_vector = np.zeros(np.max(keys) + 1)
            weight_vector[:] = np.nan
            weight_vector[keys] = values
            y_classes = smart_cond.smart_cond(len(y.shape.as_list()) == 2 and backend.shape(y)[1] > 1, lambda : backend.argmax(y, axis=1), lambda : math_ops.cast(backend.reshape(y, (-1,)), dtypes.int64))
            class_sample_weight = array_ops.gather(weight_vector, y_classes)
            gen_array_ops.check_numerics(class_sample_weight, 'Invalid classes or class weights detected. NaN values indicate that an appropriate class weight could not be determined.')
            class_sample_weight = math_ops.cast(class_sample_weight, backend.floatx())
            if sample_weight is not None:
                sample_weight = math_ops.cast(tensor_conversion.convert_to_tensor_v2_with_dispatch(sample_weight), backend.floatx())
        else:
            y_classes = y
            if len(y.shape) == 2:
                if y.shape[1] > 1:
                    y_classes = np.argmax(y, axis=1)
                elif y.shape[1] == 1:
                    y_classes = np.reshape(y, y.shape[0])
            class_sample_weight = numpy_compat.np_asarray([class_weight[cls] for cls in y_classes if cls in class_weight])
            if len(class_sample_weight) != len(y_classes):
                existing_classes = set(y_classes)
                existing_class_weight = set(class_weight.keys())
                raise ValueError('`class_weight` must contain all classes in the data. The classes %s exist in the data but not in `class_weight`.' % (existing_classes - existing_class_weight))
    if class_sample_weight is not None and sample_weight is not None:
        return class_sample_weight * sample_weight
    if sample_weight is not None:
        return sample_weight
    if class_sample_weight is not None:
        return class_sample_weight
    return None

def split_arguments(argstr):
    arguments = []
    current_argument = []
    i = 0

    def finish_arg():
        if current_argument:
            argstr = ''.join(current_argument).strip()
            m = re.match('(.*(\\s+|\\*))(\\w+)$', argstr)
            if <MASK>:
                typename = m.group(1).strip()
                name = m.group(3)
            else:
                typename = argstr
                name = ''
            arguments.append((typename, name))
            del current_argument[:]
    while i < len(argstr):
        c = argstr[i]
        if c == ',':
            finish_arg()
        elif c == '(':
            p = skip_brackets(argstr[i:], '(', ')')
            current_argument += argstr[i:i + p]
            i += p - 1
        else:
            current_argument += c
        i += 1
    finish_arg()
    return arguments

def _dim_options(ndim):
    if <MASK>:
        return [None]
    elif ndim == 2:
        return [0, 1, None]
    elif ndim == 3:
        return [0, 1, 2, (0, 1), (0, 2), None]
    raise ValueError(f'Expected ndim in range 1-3, got {ndim}')

def _to_ort_value(input: torch.Tensor | int | float | str | bool) -> ort.OrtValue:
    """Convert a PyTorch tensor to an ONNX Runtime OrtValue."""
    import numpy as np
    import onnxruntime as ort
    from torch.onnx._internal.exporter import _core
    if isinstance(input, (int, float, str, bool)):
        dtype_mapping = {int: np.int64, float: np.float32}
        dtype = dtype_mapping.get(type(input), None)
        return ort.OrtValue.ortvalue_from_numpy(np.array(input, dtype=dtype))
    if input.dtype == torch.bfloat16 or input.dtype in _NP_UNSUPPORTED_DTYPES_8BIT:
        if hasattr(ort.OrtValue, 'ortvalue_from_numpy_with_onnx_type'):
            if <MASK>:
                uint_type = torch.uint16
            else:
                uint_type = torch.uint8
            onnx_type = _core.torch_dtype_to_onnx_dtype(input.dtype)
            input = input.contiguous()
            return ort.OrtValue.ortvalue_from_numpy_with_onnx_type(input.view(uint_type).numpy(force=True), onnx_element_type=onnx_type)
        raise RuntimeError(f"Failed to convert tensor of type '{input.dtype}' to OrtValue. Please ensure that ONNX Runtime is built with DLPack support or is the latest version")
    return ort.OrtValue.ortvalue_from_numpy(input.numpy(force=True))

def getargs(co):
    """Get information about the arguments accepted by a code object.

    Three things are returned: (args, varargs, varkw), where 'args' is
    a list of argument names (possibly containing nested lists), and
    'varargs' and 'varkw' are the names of the * and ** arguments or None.

    """
    if not iscode(co):
        raise TypeError('arg is not a code object')
    nargs = co.co_argcount
    names = co.co_varnames
    args = list(names[:nargs])
    for i in range(nargs):
        if args[i][:1] in ['', '.']:
            raise TypeError('tuple function arguments are not supported')
    varargs = None
    if <MASK>:
        varargs = co.co_varnames[nargs]
        nargs = nargs + 1
    varkw = None
    if co.co_flags & CO_VARKEYWORDS:
        varkw = co.co_varnames[nargs]
    return (args, varargs, varkw)

def getRecord(self, records, m):
    record = None
    for r in records:
        if m in r.getMessage():
            self.assertIsNone(record, msg=LazyString(lambda : f'multiple matching records: {record} and {r} among {records}'))
            record = r
    if <MASK>:
        self.fail(f'did not find record with {m} among {records}')
    return record

def generate_created_models(self):
    """
        Find all new models (both managed and unmanaged) and make create
        operations for them as well as separate operations to create any
        foreign key or M2M relationships (these are optimized later, if
        possible).

        Defer any model options that refer to collections of fields that might
        be deferred (e.g. unique_together).
        """
    old_keys = self.old_model_keys | self.old_unmanaged_keys
    added_models = self.new_model_keys - old_keys
    added_unmanaged_models = self.new_unmanaged_keys - old_keys
    all_added_models = chain(sorted(added_models, key=self.swappable_first_key, reverse=True), sorted(added_unmanaged_models, key=self.swappable_first_key, reverse=True))
    for (app_label, model_name) in all_added_models:
        model_state = self.to_state.models[app_label, model_name]
        related_fields = {}
        primary_key_rel = None
        for (field_name, field) in model_state.fields.items():
            if field.remote_field:
                if field.remote_field.model:
                    if field.primary_key:
                        primary_key_rel = field.remote_field.model
                    elif <MASK>:
                        related_fields[field_name] = field
                if getattr(field.remote_field, 'through', None):
                    related_fields[field_name] = field
        indexes = model_state.options.pop('indexes')
        constraints = model_state.options.pop('constraints')
        unique_together = model_state.options.pop('unique_together', None)
        order_with_respect_to = model_state.options.pop('order_with_respect_to', None)
        dependencies = [OperationDependency(app_label, model_name, None, OperationDependency.Type.REMOVE)]
        for base in model_state.bases:
            if isinstance(base, str) and '.' in base:
                (base_app_label, base_name) = base.split('.', 1)
                dependencies.append(OperationDependency(base_app_label, base_name, None, OperationDependency.Type.CREATE))
                old_base_model_state = self.from_state.models.get((base_app_label, base_name))
                new_base_model_state = self.to_state.models.get((base_app_label, base_name))
                if old_base_model_state and new_base_model_state:
                    removed_base_fields = set(old_base_model_state.fields).difference(new_base_model_state.fields).intersection(model_state.fields)
                    for removed_base_field in removed_base_fields:
                        dependencies.append(OperationDependency(base_app_label, base_name, removed_base_field, OperationDependency.Type.REMOVE))
        if primary_key_rel:
            dependencies.append(OperationDependency(*resolve_relation(primary_key_rel, app_label, model_name), None, OperationDependency.Type.CREATE))
        self.add_operation(app_label, operations.CreateModel(name=model_state.name, fields=[d for d in model_state.fields.items() if d[0] not in related_fields], options=model_state.options, bases=model_state.bases, managers=model_state.managers), dependencies=dependencies, beginning=True)
        if not model_state.options.get('managed', True):
            continue
        for (name, field) in sorted(related_fields.items()):
            dependencies = self._get_dependencies_for_foreign_key(app_label, model_name, field, self.to_state)
            dependencies.append(OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE))
            self.add_operation(app_label, operations.AddField(model_name=model_name, name=name, field=field), dependencies=list(set(dependencies)))
        if order_with_respect_to:
            self.add_operation(app_label, operations.AlterOrderWithRespectTo(name=model_name, order_with_respect_to=order_with_respect_to), dependencies=[OperationDependency(app_label, model_name, order_with_respect_to, OperationDependency.Type.CREATE), OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE)])
        related_dependencies = [OperationDependency(app_label, model_name, name, OperationDependency.Type.CREATE) for name in sorted(related_fields)]
        related_dependencies.append(OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE))
        for index in indexes:
            self.add_operation(app_label, operations.AddIndex(model_name=model_name, index=index), dependencies=related_dependencies)
        for constraint in constraints:
            self.add_operation(app_label, operations.AddConstraint(model_name=model_name, constraint=constraint), dependencies=related_dependencies)
        if unique_together:
            self.add_operation(app_label, operations.AlterUniqueTogether(name=model_name, unique_together=unique_together), dependencies=related_dependencies)
        relations = self.to_state.relations
        if (app_label, model_name) in self.old_proxy_keys:
            for (related_model_key, related_fields) in relations[app_label, model_name].items():
                related_model_state = self.to_state.models[related_model_key]
                for (related_field_name, related_field) in related_fields.items():
                    self.add_operation(related_model_state.app_label, operations.AlterField(model_name=related_model_state.name, name=related_field_name, field=related_field), dependencies=[OperationDependency(app_label, model_name, None, OperationDependency.Type.CREATE)])

def deserialize_inputs(self, target, serialized_node: Node):
    schema_args = _get_schema_from_target(target).arguments
    argument_kinds = {input.name: input.kind for input in serialized_node.inputs}
    actual_args = {input.name: self.deserialize_input(input.arg) for input in serialized_node.inputs}
    args = []
    kwargs: OrderedDict[str, Any] = OrderedDict()
    for schema_arg in schema_args:
        if schema_arg.name in actual_args:
            arg = actual_args[schema_arg.name]
            kind = argument_kinds[schema_arg.name]
            if kind == ArgumentKind.POSITIONAL:
                args.append(arg)
                continue
            elif kind == ArgumentKind.KEYWORD and (not keyword.iskeyword(schema_arg.name)):
                kwargs[schema_arg.name] = arg
                continue
        is_positional = not schema_arg.has_default_value() and (not schema_arg.kwarg_only)
        if is_positional:
            args.append(actual_args[schema_arg.name])
        elif keyword.iskeyword(schema_arg.name):
            assert not schema_arg.kwarg_only
            if <MASK>:
                kwargs = OrderedDict()
                args.extend(list(kwargs.values()))
            args.append(actual_args[schema_arg.name])
        elif schema_arg.name in actual_args:
            kwargs[schema_arg.name] = actual_args[schema_arg.name]
    return (tuple(args), kwargs)

def _is_array_like(obj):
    """Check if a given object is array-like."""
    if <MASK>:
        return False
    if callable(getattr(obj, '__array__', None)) or isinstance(getattr(obj, '__array_interface__', None), dict):
        return True
    try:
        memoryview(obj)
    except TypeError:
        return False
    else:
        return not isinstance(obj, bytes)

def is_namedtuple_cls(cls: Any) -> bool:
    """Test if an object is a namedtuple or a (torch.return_types|torch.autograd.forward_ad).* quasi-namedtuple"""
    try:
        if issubclass(cls, tuple):
            module = getattr(cls, '__module__', None)
            if <MASK>:
                return True
            if isinstance(getattr(cls, '_fields', None), tuple) and callable(getattr(cls, '_make', None)):
                bases = tuple((t for t in cls.__bases__ if t is not Generic))
                if bases == (tuple,):
                    return True
                if bases and any((is_namedtuple_cls(t) and cls.__new__ is t.__new__ for t in bases)):
                    return True
    except TypeError:
        pass
    return False

def build_graph(parameters):
    """Build the sparse_to_dense op testing graph."""
    dense_shape = parameters['dense_shape']
    if <MASK>:
        value = tf.compat.v1.placeholder(name='value', dtype=parameters['value_dtype'], shape=())
    else:
        value = tf.compat.v1.placeholder(name='value', dtype=parameters['value_dtype'], shape=[parameters['value_count']])
    indices = set()
    while len(indices) < parameters['value_count']:
        indices.add(generate_index(dense_shape))
    indices = tf.constant(tuple(indices), dtype=parameters['index_dtype'])
    out = tf.compat.v1.sparse_to_dense(indices, dense_shape, value, parameters['default_value'], validate_indices=False)
    return ([value], [out])

def sdpa_vector_fast_mps():
    out = q_.new_empty(q_.shape)
    if <MASK>:
        out = out.view_as(query)
    attn = q_.new_empty((batch_size, num_head, q_size, max_seq_length))
    if unsqueezed:
        if query.dim() == 3:
            attn = attn.squeeze(0)
        else:
            shape = list(query.shape[:-3]) + attn.shape[1:4]
            attn = attn.view(shape)
    return (out, attn)

