def dont_skip_tracing(fn: Optional[Any]=None) -> Any:
    """
    Context manager/decorator to trace into functions intentionally marked by developers to be skipped
    when tracing.

    This decorator will also apply to recursively invoked functions.
    """
    ctx = patch_dynamo_config(dont_skip_tracing=True)
    if <MASK>:
        return ctx(fn)
    return ctx

def convert_to_HWC(tensor, input_format):
    if len(set(input_format)) != len(input_format):
        raise AssertionError(f'You can not use the same dimension shordhand twice.             input_format: {input_format}')
    if len(tensor.shape) != len(input_format):
        raise AssertionError(f'size of input tensor and input format are different.         tensor shape: {tensor.shape}, input_format: {input_format}')
    input_format = input_format.upper()
    if len(input_format) == 4:
        index = [input_format.find(c) for c in 'NCHW']
        tensor_NCHW = tensor.transpose(index)
        tensor_CHW = make_grid(tensor_NCHW)
        return tensor_CHW.transpose(1, 2, 0)
    if <MASK>:
        index = [input_format.find(c) for c in 'HWC']
        tensor_HWC = tensor.transpose(index)
        if tensor_HWC.shape[2] == 1:
            tensor_HWC = np.concatenate([tensor_HWC, tensor_HWC, tensor_HWC], 2)
        return tensor_HWC
    if len(input_format) == 2:
        index = [input_format.find(c) for c in 'HW']
        tensor = tensor.transpose(index)
        tensor = np.stack([tensor, tensor, tensor], 2)
        return tensor

def __setitem__(self, key, value) -> None:
    if isinstance(key, tuple):
        key = tuple((com.apply_if_callable(x, self.obj) for x in key))
    else:
        key = com.apply_if_callable(key, self.obj)
    if <MASK>:
        key = _tuplify(self.ndim, key)
    key = list(self._convert_key(key))
    if len(key) != self.ndim:
        raise ValueError('Not enough indexers for scalar access (setting)!')
    self.obj._set_value(*key, value=value, takeable=self._takeable)

def _extract_signatures(self, wrapped, meta_graph_def):
    """Creates ConcreteFunctions for signatures in `meta_graph_def`."""
    signature_functions = {}
    for (signature_key, signature_def) in meta_graph_def.signature_def.items():
        if signature_def.inputs:
            input_items = sorted(signature_def.inputs.items(), key=lambda item: item[0])
            (original_input_names, input_specs) = zip(*input_items)
        else:
            original_input_names = []
            input_specs = []
        feeds = [wrap_function._get_element_from_tensor_info(input_spec, wrapped.graph) for input_spec in input_specs]
        input_names = []
        input_tensors = []
        for (original_input_name, feed) in zip(original_input_names, feeds):
            if isinstance(feed, sparse_tensor.SparseTensor):
                indices_name = '%s_indices' % original_input_name
                values_name = '%s_values' % original_input_name
                dense_shape_name = '%s_dense_shape' % original_input_name
                input_names.extend([indices_name, values_name, dense_shape_name])
                input_tensors.extend([feed.indices, feed.values, feed.dense_shape])
            elif <MASK>:
                component_tensors = nest.flatten(feed, expand_composites=True)
                input_names.extend(('%s_component_%d' % (original_input_name, n) for n in range(len(component_tensors))))
                input_tensors.extend(component_tensors)
            else:
                input_names.append(original_input_name)
                input_tensors.append(feed)
        fetches = {name: out for (name, out) in signature_def.outputs.items()}
        input_signature = ((), func_graph.convert_structure_to_signature(dict(zip(input_names, input_tensors))))
        try:
            signature_fn = wrapped.prune(feeds=feeds, fetches=fetches, input_signature=input_signature, are_keyword_args_also_positional=True)
        except lift_to_graph.UnliftableError as ex:
            args = ex.args
            if not args:
                message = ''
            else:
                message = args[0]
            message = "A SavedModel signature needs an input for each placeholder the signature's outputs use. An output for signature '{}' depends on a placeholder which is not an input (i.e. the placeholder is not fed a value).\n\n".format(signature_key) + message
            ex.args = (message,) + args[1:]
            raise
        signature_fn._arg_keywords = input_names
        if len(input_names) == 1:
            signature_fn._num_positional_args = 1
        else:
            signature_fn._num_positional_args = 0
        signature_functions[signature_key] = signature_fn
    return signature_functions

def buildapi(rout):
    (rout, wrap) = func2subr.assubr(rout)
    (args, depargs) = getargs2(rout)
    capi_maps.depargs = depargs
    var = rout['vars']
    if ismoduleroutine(rout):
        outmess('            Constructing wrapper function "%s.%s"...\n' % (rout['modulename'], rout['name']))
    else:
        outmess(f'''        Constructing wrapper function "{rout['name']}"...\n''')
    vrd = capi_maps.routsign2map(rout)
    rd = dictappend({}, vrd)
    for r in rout_rules:
        if '_check' in r and r['_check'](rout) or '_check' not in r:
            ar = applyrules(r, vrd, rout)
            rd = dictappend(rd, ar)
    (nth, nthk) = (0, 0)
    savevrd = {}
    for a in args:
        vrd = capi_maps.sign2map(a, var[a])
        if isintent_aux(var[a]):
            _rules = aux_rules
        else:
            _rules = arg_rules
            if not isintent_hide(var[a]):
                if not isoptional(var[a]):
                    nth = nth + 1
                    vrd['nth'] = repr(nth) + stnd[nth % 10] + ' argument'
                else:
                    nthk = nthk + 1
                    vrd['nth'] = repr(nthk) + stnd[nthk % 10] + ' keyword'
            else:
                vrd['nth'] = 'hidden'
        savevrd[a] = vrd
        for r in _rules:
            if '_depend' in r:
                continue
            if '_check' in r and r['_check'](var[a]) or '_check' not in r:
                ar = applyrules(r, vrd, var[a])
                rd = dictappend(rd, ar)
                if '_break' in r:
                    break
    for a in depargs:
        if isintent_aux(var[a]):
            _rules = aux_rules
        else:
            _rules = arg_rules
        vrd = savevrd[a]
        for r in _rules:
            if '_depend' not in r:
                continue
            if '_check' in r and r['_check'](var[a]) or '_check' not in r:
                ar = applyrules(r, vrd, var[a])
                rd = dictappend(rd, ar)
                if '_break' in r:
                    break
        if 'check' in var[a]:
            for c in var[a]['check']:
                vrd['check'] = c
                ar = applyrules(check_rules, vrd, var[a])
                rd = dictappend(rd, ar)
    if isinstance(rd['cleanupfrompyobj'], list):
        rd['cleanupfrompyobj'].reverse()
    if isinstance(rd['closepyobjfrom'], list):
        rd['closepyobjfrom'].reverse()
    rd['docsignature'] = stripcomma(replace('#docsign##docsignopt##docsignxa#', {'docsign': rd['docsign'], 'docsignopt': rd['docsignopt'], 'docsignxa': rd['docsignxa']}))
    optargs = stripcomma(replace('#docsignopt##docsignxa#', {'docsignxa': rd['docsignxashort'], 'docsignopt': rd['docsignoptshort']}))
    if optargs == '':
        rd['docsignatureshort'] = stripcomma(replace('#docsign#', {'docsign': rd['docsign']}))
    else:
        rd['docsignatureshort'] = replace('#docsign#[#docsignopt#]', {'docsign': rd['docsign'], 'docsignopt': optargs})
    rd['latexdocsignatureshort'] = rd['docsignatureshort'].replace('_', '\\_')
    rd['latexdocsignatureshort'] = rd['latexdocsignatureshort'].replace(',', ', ')
    cfs = stripcomma(replace('#callfortran##callfortranappend#', {'callfortran': rd['callfortran'], 'callfortranappend': rd['callfortranappend']}))
    if len(rd['callfortranappend']) > 1:
        rd['callcompaqfortran'] = stripcomma(replace('#callfortran# 0,#callfortranappend#', {'callfortran': rd['callfortran'], 'callfortranappend': rd['callfortranappend']}))
    else:
        rd['callcompaqfortran'] = cfs
    rd['callfortran'] = cfs
    if isinstance(rd['docreturn'], list):
        rd['docreturn'] = stripcomma(replace('#docreturn#', {'docreturn': rd['docreturn']})) + ' = '
    rd['docstrsigns'] = []
    rd['latexdocstrsigns'] = []
    for k in ['docstrreq', 'docstropt', 'docstrout', 'docstrcbs']:
        if <MASK>:
            rd['docstrsigns'] = rd['docstrsigns'] + rd[k]
        k = 'latex' + k
        if k in rd and isinstance(rd[k], list):
            rd['latexdocstrsigns'] = rd['latexdocstrsigns'] + rd[k][0:1] + ['\\begin{description}'] + rd[k][1:] + ['\\end{description}']
    ar = applyrules(routine_rules, rd)
    if ismoduleroutine(rout):
        outmess(f"              {ar['docshort']}\n")
    else:
        outmess(f"          {ar['docshort']}\n")
    return (ar, wrap)

def check_compiler_is_gcc(compiler):
    if not IS_LINUX:
        return False
    env = os.environ.copy()
    env['LC_ALL'] = 'C'
    try:
        version_string = subprocess.check_output([compiler, '-v'], stderr=subprocess.STDOUT, env=env).decode(*SUBPROCESS_DECODE_ARGS)
    except Exception:
        try:
            version_string = subprocess.check_output([compiler, '--version'], stderr=subprocess.STDOUT, env=env).decode(*SUBPROCESS_DECODE_ARGS)
        except Exception:
            return False
    pattern = re.compile('^COLLECT_GCC=(.*)$', re.MULTILINE)
    results = re.findall(pattern, version_string)
    if len(results) != 1:
        return False
    compiler_path = os.path.realpath(results[0].strip())
    if <MASK>:
        return True
    return False

def grab_method_and_template(in_kernel):
    pos = {'kernel_launch': {'start': in_kernel['start'], 'end': in_kernel['end']}, 'kernel_name': {'start': -1, 'end': -1}, 'template': {'start': -1, 'end': -1}}
    count = {'<>': 0}
    START = 0
    AT_TEMPLATE = 1
    AFTER_TEMPLATE = 2
    AT_KERNEL_NAME = 3
    status = START
    for i in range(pos['kernel_launch']['start'] - 1, -1, -1):
        char = string[i]
        if status in (START, AT_TEMPLATE):
            if char == '>':
                if status == START:
                    status = AT_TEMPLATE
                    pos['template']['end'] = i
                count['<>'] += 1
            if char == '<':
                count['<>'] -= 1
                if <MASK>:
                    pos['template']['start'] = i
                    status = AFTER_TEMPLATE
        if status != AT_TEMPLATE:
            if string[i].isalnum() or string[i] in {'(', ')', '_', ':', '#'}:
                if status != AT_KERNEL_NAME:
                    status = AT_KERNEL_NAME
                    pos['kernel_name']['end'] = i
                if i == 0:
                    pos['kernel_name']['start'] = 0
                    return [pos['kernel_name'], pos['template'], pos['kernel_launch']]
            elif status == AT_KERNEL_NAME:
                pos['kernel_name']['start'] = i
                return [pos['kernel_name'], pos['template'], pos['kernel_launch']]

def create_proxy(self, kind: str, target: Any, args: Any, kwargs: Any, name: Optional[str]=None, type_expr: Optional[Any]=None, proxy_factory_fn: Optional[Callable[[fx.Node], fx.Proxy]]=None) -> fx.Proxy:
    if self.parent is not None:
        (flat_args, tree_spec) = pytree.tree_flatten((args, kwargs))
        new_flat_args = []
        for arg in flat_args:
            maybe_new_arg = self.maybe_lift_tracked_freevar_to_input(arg)
            new_flat_args.append(maybe_new_arg)
        (args, kwargs) = pytree.tree_unflatten(new_flat_args, tree_spec)
    rv = super().create_proxy(kind, target, args, kwargs, name, type_expr, proxy_factory_fn)
    tx = self.output_graph.current_tx
    if sys.version_info >= (3, 11) and kind in ('call_function', 'call_method', 'call_module'):
        cur_inst = tx.current_instruction
        if <MASK>:
            tx_code = tx.f_code
            header = tx.get_line_of_code_header(lineno=cur_inst.positions.lineno)

            def get_trace_call_log_str() -> str:
                line = get_instruction_source_311(tx_code, cur_inst).rstrip()
                return f'TRACE FX call {rv.node.name} from {header}\n{line}'
            trace_call_log.debug('%s', LazyString(get_trace_call_log_str))
            self.prev_inst = cur_inst
    is_retracing = False
    if tx.f_code is not self._cur_code:
        orig_graphmodule_maybe = code_context.get_context(tx.f_code).get('orig_graphmodule', lambda : None)()
        if isinstance(orig_graphmodule_maybe, torch.fx.GraphModule):
            is_retracing = True
            self._orig_gm_meta = [nd.meta for nd in orig_graphmodule_maybe.graph.nodes]
            self._orig_gm_lineno_map = orig_graphmodule_maybe._lineno_map
            self._orig_gm_firstlineno = orig_graphmodule_maybe.forward.__code__.co_firstlineno
        else:
            self._orig_gm_meta = None
            self._orig_gm_lineno_map = None
            self._orig_gm_firstlineno = None
    nn_module_stack = tx.nn_module_stack
    if nn_module_stack:
        rv.node.meta['nn_module_stack'] = nn_module_stack.copy()
    if kind in {'call_function', 'call_method'}:
        stack = (rv.node.name, target)
        if nn_module_stack:
            current_nn_module = list(rv.node.meta['nn_module_stack'].values())[-1][1]
            if current_nn_module.__module__.startswith(('torch.nn.modules', 'torch.ao.')) and (not current_nn_module.__module__.startswith('torch.nn.modules.container')):
                stack = (rv.node.name, current_nn_module)
        rv.node.meta['source_fn_stack'] = self.source_fn_stack + [stack]
    elif kind == 'call_module':
        if self.parent is not None:
            unimplemented_v2(gb_type='Invoking an nn.Module inside a higher order operator', context=f'Higher order op name: {self.source_target}', explanation='This is not supported.', hints=[])
        rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, next((ty for (k, (_, ty)) in rv.node.meta['nn_module_stack'].items() if k.split('@')[0] == target)))]
    self._maybe_preserve_original_meta(tx, rv.node)
    if not is_retracing:
        if 'nn_module_stack' not in rv.node.meta:
            nn_module_stack = tx.nn_module_stack
            if nn_module_stack:
                rv.node.meta['nn_module_stack'] = nn_module_stack.copy()
        if 'source_fn_stack' not in rv.node.meta:
            if kind in {'call_function', 'call_method'}:
                rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, target)]
            elif kind == 'call_module':
                if self.parent is not None:
                    unimplemented_v2(gb_type='Invoking an nn.Module inside a HigherOrderOperator', context='', explanation='This is not supported.', hints=[])
                rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, rv.node.meta['nn_module_stack'][target][1])]
    if 'stack_trace' not in rv.node.meta:
        frame_summaries: list[traceback.FrameSummary] = []
        while tx:
            if not tx.is_co_filename_from_nn_modules():
                frame_summaries.append(tx.frame_summary())
            tx = getattr(tx, 'parent', None)
        filtered_frame_summaries = [frame for frame in frame_summaries if frame.filename not in uninteresting_files()]
        filtered_frame_summaries.reverse()
        msgs = traceback.StackSummary.from_list(filtered_frame_summaries).format()
        rv.node.stack_trace = ''.join(msgs)
    if torch._dynamo.config.use_graph_deduplication or torch._dynamo.config.track_nodes_for_deduplication:
        self.output_graph.region_tracker.track_node(self.output_graph.current_tx, rv.node)
    return rv

def validate_can_generate_cpp_wrapper(self) -> None:
    if config.disable_cpp_codegen:
        raise CppWrapperCodegenError('C++ codegen is disabled')
    if <MASK>:
        raise CppWrapperCodegenError(f'Unsupported platform {sys.platform}')

@staticmethod
def new(node, function, enclosing_graph):
    """Creates a new _Node base on its operation type."""
    if node.op in ['VariableV2', 'VarHandleOp', 'Placeholder']:
        return _VarHandle(node, function, enclosing_graph)
    elif <MASK>:
        return _Case(node, function, enclosing_graph)
    elif node.op == 'Merge':
        return _Merge(node, function, enclosing_graph)
    elif node.op == 'PartitionedCall':
        return _PartitionedCall(node, function, enclosing_graph)
    elif node.op == 'StatefulPartitionedCall':
        return _PartitionedCall(node, function, enclosing_graph)
    elif node.op == 'ReadVariableOp':
        return _ReadVariable(node, function, enclosing_graph)
    elif node.op == 'ResourceGather':
        return _ResourceGather(node, function, enclosing_graph)
    elif node.op == 'ResourceGatherNd':
        return _ResourceGatherNd(node, function, enclosing_graph)
    elif node.op in ['If', 'StatelessIf']:
        return _If(node, function, enclosing_graph)
    elif node.op in ['While', 'StatelessWhile']:
        return _While(node, function, enclosing_graph)
    elif node.op in ['Enter', 'Exit', 'Identity', 'NextIteration', 'Switch', '_SwitchN']:
        return _Intermediate(node, function, enclosing_graph)
    else:
        return _Node(node, function, enclosing_graph)

def _default_alldims(dim: Optional[DimsType], x: TensorLikeType) -> list[int]:
    """Convert Optional[DimsType] to a simple list, defaulting to all dimensions"""
    if dim is None:
        return list(range(x.ndim))
    elif <MASK>:
        return [dim]
    else:
        return list(dim)

def read_file(filename: Optional[str]=None) -> bool:
    """Read results from a TunableOp CSV file.

    If :attr:`filename` is not given, ``get_filename()`` is called.
    """
    if <MASK>:
        filename = get_filename()
    return torch._C._cuda_tunableop_read_file(filename)

def _list_of_series_to_arrays(data: list, columns: Index | None) -> tuple[np.ndarray, Index]:
    if columns is None:
        pass_data = [x for x in data if isinstance(x, (ABCSeries, ABCDataFrame))]
        columns = get_objs_combined_axis(pass_data, sort=False)
    indexer_cache: dict[int, np.ndarray] = {}
    aligned_values = []
    for s in data:
        index = getattr(s, 'index', None)
        if <MASK>:
            index = default_index(len(s))
        if id(index) in indexer_cache:
            indexer = indexer_cache[id(index)]
        else:
            indexer = indexer_cache[id(index)] = index.get_indexer(columns)
        values = extract_array(s, extract_numpy=True)
        aligned_values.append(algorithms.take_nd(values, indexer))
    content = np.vstack(aligned_values)
    return (content, columns)

def _should_disable_fastpath(self, opinfo, rightmost_arg, rightmost_arg_type, dtype):
    if self.arity == 1:
        if 'foreach_abs' in opinfo.name and dtype in complex_types():
            return True
        if opinfo.ref in (torch.abs, torch.neg):
            return False
        if opinfo.ref_inplace == torch.Tensor.zero_:
            return False
        return dtype in integral_types_and(torch.bool)
    if self.arity < 2 or rightmost_arg_type == ForeachRightmostArgType.Tensor:
        return None
    if 'foreach_pow' in opinfo.name and dtype in integral_types_and(torch.bool):
        return True
    if any((foreach_name in opinfo.name for foreach_name in ('foreach_clamp_max', 'foreach_clamp_min', 'foreach_maximum', 'foreach_minimum'))) and dtype in integral_types_and(torch.bool):
        return True
    if rightmost_arg_type == ForeachRightmostArgType.TensorList:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if 'foreach_add' in opinfo.name and dtype == torch.bool:
            disable_fastpath = True
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.Scalar:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if isinstance(rightmost_arg, bool):
            disable_fastpath |= dtype == torch.bool
            if opinfo.ref in (torch.add, torch.mul):
                disable_fastpath = False
        elif isinstance(rightmost_arg, int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg, float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg, complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalar of type {rightmost_arg_type} - {rightmost_arg}')
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.ScalarList:
        disable_fastpath = opinfo.ref == torch.div and dtype in integral_types_and(torch.bool)
        elmt_t = type(rightmost_arg[0])
        has_same_type = all((isinstance(v, elmt_t) for v in rightmost_arg))
        if not has_same_type:
            return dtype not in complex_types()
        if isinstance(rightmost_arg[0], bool):
            if <MASK>:
                disable_fastpath = False
        elif isinstance(rightmost_arg[0], int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg[0], float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg[0], complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalarlist of {rightmost_arg}')
        return disable_fastpath
    else:
        raise AssertionError(f'Invalid rightmost_arg_type of {rightmost_arg_type}')

def arg_name(self, name: str) -> Optional[str]:
    """
        Returns inner name of a given outer name.
        """
    inplaced = self.inplace_buffers.get(name, None)
    if <MASK>:
        return inplaced.inner_name
    output_name = self.output_buffers.get(name, None)
    if output_name is not None and (not isinstance(output_name, RemovedArg)):
        return output_name
    return self.input_buffers.get(name, None)

def expired(self) -> bool:
    if <MASK>:
        return False
    stor_count = torch._C._storage_Use_Count(self.ref.cdata)
    return stor_count - (self.extra_ref_check is not None) == 0

def AddOp(self, op: ops.Operation):
    """Create op in XLACompileContext and notifies outer context recursively."""
    if <MASK>:
        logging.error('Operation of type %s (%s) is not supported in XLA. Execution will fail if this op is used in the graph. ', op.type, op.name)
    if op.type in _UNSUPPORTED_OPS:
        self._unsupported_ops.append(op)
    if any((x.dtype._is_ref_dtype for x in op.inputs)):
        raise NotImplementedError('Non-resource Variables are not supported inside XLA computations (operator name: %s)' % op.name)
    if _XLA_COMPILE_ATTR in op.node_def.attr:
        raise ValueError('XLA compiled computations cannot be nested, (operator name: %s)' % op.name)
    op._set_attr(_XLA_COMPILE_ATTR, attr_value_pb2.AttrValue(s=self._name_as_bytes))
    op.graph.prevent_feeding(op)
    op.graph.prevent_fetching(op)
    (internal_control_inputs, external_control_inputs) = self._RemoveExternalControlEdges(op)
    if not op.inputs:
        if not internal_control_inputs:
            op._add_control_input(self._pivot)
    else:
        for index in range(len(op.inputs)):
            x = op.inputs[index]
            real_x = self.AddValue(x)
            if real_x is not x:
                op._update_input(index, real_x)
    if external_control_inputs:
        with ops.control_dependencies(None):
            self.Enter()
            external_control_inputs = [array_ops.identity(x.outputs[0]).op for x in external_control_inputs if x.outputs]
            self.Exit()
        op._add_control_inputs(external_control_inputs)
    output_names = [x.name for x in op.outputs]
    context = self
    while context is not None:
        context._values.update(output_names)
        context = context._outer_context
    if self._outer_context:
        self._outer_context.AddInnerOp(op)

def __init__(self, backup_dir):
    super(BackupAndRestore, self).__init__()
    self.backup_dir = backup_dir
    self._supports_tf_logs = True
    self._supported_strategies = (mirrored_strategy.MirroredStrategy, collective_all_reduce_strategy.CollectiveAllReduceStrategy, tpu_strategy.TPUStrategy, tpu_strategy.TPUStrategyV2, parameter_server_strategy_v2.ParameterServerStrategyV2)
    if not context.executing_eagerly():
        if <MASK>:
            raise ValueError("This Callback's method contains Python state and should be called outside of `tf.function`s.")
        else:
            raise ValueError('BackupAndRestore only supports eager mode. In graph mode, consider using ModelCheckpoint to manually save and restore weights with `model.load_weights()` and by providing `initial_epoch` in `model.fit()` for fault tolerance.')
    self._chief_worker_only = False

def database_forwards(self, app_label, schema_editor, from_state, to_state):
    new_model = to_state.apps.get_model(app_label, self.new_name)
    if <MASK>:
        old_model = from_state.apps.get_model(app_label, self.old_name)
        schema_editor.alter_db_table(new_model, old_model._meta.db_table, new_model._meta.db_table)
        for related_object in old_model._meta.related_objects:
            if related_object.related_model == old_model:
                model = new_model
                related_key = (app_label, self.new_name_lower)
            else:
                related_key = (related_object.related_model._meta.app_label, related_object.related_model._meta.model_name)
                model = to_state.apps.get_model(*related_key)
            to_field = to_state.apps.get_model(*related_key)._meta.get_field(related_object.field.name)
            schema_editor.alter_field(model, related_object.field, to_field)
        fields = zip(old_model._meta.local_many_to_many, new_model._meta.local_many_to_many)
        for (old_field, new_field) in fields:
            if new_field.model == new_field.related_model or not new_field.remote_field.through._meta.auto_created:
                continue
            schema_editor._alter_many_to_many(new_model, old_field, new_field, strict=False)

def build_err_msg(arrays, err_msg, header='Items are not equal:', verbose=True, names=('ACTUAL', 'DESIRED'), precision=8):
    msg = ['\n' + header]
    if err_msg:
        if err_msg.find('\n') == -1 and len(err_msg) < 79 - len(header):
            msg = [msg[0] + ' ' + err_msg]
        else:
            msg.append(err_msg)
    if verbose:
        for (i, a) in enumerate(arrays):
            if isinstance(a, ndarray):
                r_func = ndarray.__repr__
            else:
                r_func = repr
            try:
                r = r_func(a)
            except Exception as exc:
                r = f'[repr failed for <{type(a).__name__}>: {exc}]'
            if <MASK>:
                r = '\n'.join(r.splitlines()[:3])
                r += '...'
            msg.append(f' {names[i]}: {r}')
    return '\n'.join(msg)

def _find_reference_cycle(objects: Sequence[Any], idx: int) -> bool:

    def get_ignore_reason(obj: Any, denylist: Collection[Any]) -> Optional[str]:
        """Tests whether an object should be omitted from the dependency graph."""
        if len(denylist) > 100:
            return '<depth limit>'
        if tf_inspect.isframe(obj):
            if <MASK>:
                return '<test code>'
        for b in denylist:
            if b is obj:
                return '<test code>'
        if obj is denylist:
            return '<test code>'
        return None

    def describe(obj: Any, denylist: Collection[Any], leaves_only: bool=False) -> str:
        """Returns a custom human-readable summary of obj.

    Args:
      obj: the value to describe.
      denylist: same as denylist in get_ignore_reason.
      leaves_only: boolean flag used when calling describe recursively. Useful
        for summarizing collections.
    """
        if get_ignore_reason(obj, denylist):
            return '{}{}'.format(get_ignore_reason(obj, denylist), type(obj))
        if tf_inspect.isframe(obj):
            return 'frame: {}'.format(tf_inspect.getframeinfo(obj))
        elif tf_inspect.ismodule(obj):
            return 'module: {}'.format(obj.__name__)
        elif leaves_only:
            return '{}, {}'.format(type(obj), id(obj))
        elif isinstance(obj, list):
            return 'list({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
        elif isinstance(obj, tuple):
            return 'tuple({}): {}'.format(id(obj), [describe(e, denylist, leaves_only=True) for e in obj])
        elif isinstance(obj, dict):
            return 'dict({}): {} keys'.format(id(obj), len(obj.keys()))
        elif tf_inspect.isfunction(obj):
            return 'function({}) {}; globals ID: {}'.format(id(obj), obj.__name__, id(obj.__globals__))
        else:
            return '{}, {}'.format(type(obj), id(obj))

    def build_ref_graph(obj: Any, graph: dict[int, list[int]], reprs: dict[int, str], denylist: tuple[Any, ...]) -> None:
        """Builds a reference graph as <referrer> -> <list of referents>.

    Args:
      obj: The object to start from. The graph will be built by recursively
        adding its referrers.
      graph: Dict holding the graph to be built. To avoid creating extra
        references, the graph holds object IDs rather than actual objects.
      reprs: Auxiliary structure that maps object IDs to their human-readable
        description.
      denylist: List of objects to ignore.
    """
        referrers = gc.get_referrers(obj)
        denylist = denylist + (referrers,)
        obj_id = id(obj)
        for r in referrers:
            if get_ignore_reason(r, denylist) is None:
                r_id = id(r)
                if r_id not in graph:
                    graph[r_id] = []
                if obj_id not in graph[r_id]:
                    graph[r_id].append(obj_id)
                    build_ref_graph(r, graph, reprs, denylist)
                    reprs[r_id] = describe(r, denylist)

    def find_cycle(el: int, graph: dict[int, list[int]], reprs: dict[int, str], path: tuple[int, ...]) -> Optional[bool]:
        """Finds and prints a single cycle in the dependency graph."""
        if el not in graph:
            return
        for r in graph[el]:
            if r in path:
                logging.error('Reference cycle sample:')
                for p in path + (r,):
                    logging.error(reprs.get(p, 'unknown object ' + str(p)))
                return True
            elif find_cycle(r, graph, reprs, path + (r,)):
                return True
        return False
    obj = objects[idx]
    graph: dict[int, list[int]] = {}
    reprs: dict[int, str] = {}
    build_ref_graph(obj, graph, reprs, (objects, graph, reprs, get_ignore_reason, describe, build_ref_graph, find_cycle))
    for k in graph:
        if find_cycle(k, graph, reprs, ()):
            return True
    return False

def apply_gradients(self, grads_and_vars, name=None, experimental_aggregate_gradients=True):
    if distribute_lib.in_cross_replica_context():
        raise ValueError('apply_gradients() must be called in a replica context.')
    self._raise_if_strategy_unsupported()
    grads_and_vars = optimizer_utils.filter_empty_gradients(grads_and_vars)
    if experimental_aggregate_gradients:
        grads_and_vars = self._optimizer._transform_unaggregated_gradients(grads_and_vars)
        grads_and_vars = self._optimizer._aggregate_gradients(grads_and_vars)
    grads_and_vars = tuple(grads_and_vars)
    grads = [g for (g, _) in grads_and_vars]
    wrapped_vars = _UnwrapPreventer([v for (_, v) in grads_and_vars])

    def do_not_apply_fn():
        return self._optimizer.iterations.assign_add(1, read_value=False)

    def _if_should_apply_grads(grads):
        if isinstance(self._loss_scale, _DynamicLossScaleState):
            return self._loss_scale.update(grads)
        else:
            return (control_flow_ops.no_op(), True)
    if <MASK>:
        (loss_scale_update_op, should_apply_grads) = _if_should_apply_grads(grads)

        def apply_fn():
            return self._apply_gradients(grads, wrapped_vars, name)
        maybe_apply_op = smart_cond.smart_cond(should_apply_grads, apply_fn, do_not_apply_fn)
        return control_flow_ops.group(maybe_apply_op, loss_scale_update_op)
    else:

        def _apply_gradients_cross_replica(distribution, grads, wrapped_vars, name):
            (loss_scale_update_op, should_apply_grads) = _if_should_apply_grads(grads)

            def apply_fn():
                return distribution.extended.call_for_each_replica(self._apply_gradients, args=(grads, wrapped_vars, name))
            maybe_apply_op = smart_cond.smart_cond(should_apply_grads, apply_fn, do_not_apply_fn)
            return control_flow_ops.group(maybe_apply_op, loss_scale_update_op)
        return distribute_lib.get_replica_context().merge_call(_apply_gradients_cross_replica, args=(grads, wrapped_vars, name))

def get_conv_fun_weight(node: Node, gm: GraphModule) -> torch.Tensor:
    weight_arg_node = node.args[1]
    if not isinstance(weight_arg_node, Node):
        raise AssertionError(f'Expected Node, got {type(weight_arg_node)}')
    weight_node = return_first_non_observer_node(weight_arg_node, gm)
    if <MASK>:
        raise AssertionError(f'Expected Node, got {type(weight_node)}')
    if weight_node.op != 'get_attr':
        raise AssertionError(f'Expected get_attr, got {weight_node.op}')
    weight = getattr_from_fqn(gm, weight_node.target)
    return weight.detach()

def dot(a: ArrayLike, b: ArrayLike, out: Optional[OutArray]=None):
    dtype = _dtypes_impl.result_type_impl(a, b)
    is_bool = dtype == torch.bool
    if <MASK>:
        dtype = torch.uint8
    a = _util.cast_if_needed(a, dtype)
    b = _util.cast_if_needed(b, dtype)
    if a.ndim == 0 or b.ndim == 0:
        result = a * b
    else:
        result = torch.matmul(a, b)
    if is_bool:
        result = result.to(torch.bool)
    return result

