@def_function.function(input_signature=[tensor_spec.TensorSpec(shape=[None], dtype=input_type, name='input_tensor')])
def model(self, input_tensor: core.Tensor) -> Mapping[str, core.Tensor]:
    """Performs a gather and a 2D convolution operation.

        Args:
          input_tensor: Input tensor to perform operation on.

        Returns:
          A map of: output key -> output result.
        """
    out = array_ops.gather_v2(self.embedding_w, input_tensor)
    out = nn_ops.conv2d(out, self.conv_filters, strides=(1, 1, 2, 1), dilations=(1, 1, 1, 1), padding='SAME', data_format='NHWC')
    if <MASK>:
        out = array_ops.fake_quant_with_min_max_args(out, min=-0.1, max=0.2, num_bits=8, narrow_range=False)
        second_conv_filters = array_ops.fake_quant_with_min_max_args(self.second_conv_filters, min=-0.1, max=0.2, num_bits=8, narrow_range=True)
    else:
        second_conv_filters = self.second_conv_filters
    out = nn_ops.conv2d(out, second_conv_filters, strides=(1, 1, 2, 1), dilations=(1, 1, 1, 1), padding='SAME', data_format='NHWC')
    if is_qat_model:
        out = array_ops.fake_quant_with_min_max_args(out, min=-0.1, max=0.2, num_bits=8, narrow_range=False)
    return {'output': out}

def iter_encode(self, obj):
    """The iterative version of `arff.ArffEncoder.encode`.

        This encodes iteratively a given object and return, one-by-one, the
        lines of the ARFF file.

        :param obj: the object containing the ARFF information.
        :return: (yields) the ARFF file as strings.
        """
    if obj.get('description', None):
        for row in obj['description'].split('\n'):
            yield self._encode_comment(row)
    if <MASK>:
        raise BadObject('Relation name not found or with invalid value.')
    yield self._encode_relation(obj['relation'])
    yield ''
    if not obj.get('attributes'):
        raise BadObject('Attributes not found.')
    attribute_names = set()
    for attr in obj['attributes']:
        if not isinstance(attr, (tuple, list)) or len(attr) != 2 or (not isinstance(attr[0], str)):
            raise BadObject('Invalid attribute declaration "%s"' % str(attr))
        if isinstance(attr[1], str):
            if attr[1] not in _SIMPLE_TYPES:
                raise BadObject('Invalid attribute type "%s"' % str(attr))
        elif not isinstance(attr[1], (tuple, list)):
            raise BadObject('Invalid attribute type "%s"' % str(attr))
        if attr[0] in attribute_names:
            raise BadObject('Trying to use attribute name "%s" for the second time.' % str(attr[0]))
        else:
            attribute_names.add(attr[0])
        yield self._encode_attribute(attr[0], attr[1])
    yield ''
    attributes = obj['attributes']
    yield _TK_DATA
    if 'data' in obj:
        data = _get_data_object_for_encoding(obj.get('data'))
        yield from data.encode_data(obj.get('data'), attributes)
    yield ''

def _showwarning(self, message, category, filename, lineno, *args, use_warnmsg=None, **kwargs):
    for (cat, _, pattern, mod, rec) in (self._suppressions + self._tmp_suppressions)[::-1]:
        if issubclass(category, cat) and pattern.match(message.args[0]) is not None:
            if mod is None:
                if rec is not None:
                    msg = WarningMessage(message, category, filename, lineno, **kwargs)
                    self.log.append(msg)
                    rec.append(msg)
                return
            elif mod.__file__.startswith(filename):
                if rec is not None:
                    msg = WarningMessage(message, category, filename, lineno, **kwargs)
                    self.log.append(msg)
                    rec.append(msg)
                return
    if self._forwarding_rule == 'always':
        if use_warnmsg is None:
            self._orig_show(message, category, filename, lineno, *args, **kwargs)
        else:
            self._orig_showmsg(use_warnmsg)
        return
    if self._forwarding_rule == 'once':
        signature = (message.args, category)
    elif self._forwarding_rule == 'module':
        signature = (message.args, category, filename)
    elif <MASK>:
        signature = (message.args, category, filename, lineno)
    if signature in self._forwarded:
        return
    self._forwarded.add(signature)
    if use_warnmsg is None:
        self._orig_show(message, category, filename, lineno, *args, **kwargs)
    else:
        self._orig_showmsg(use_warnmsg)

def convert_extent(self, clob):
    if clob:
        ext_geom = GEOSGeometry(memoryview(clob.read()))
        gtype = str(ext_geom.geom_type)
        if <MASK>:
            shell = ext_geom.shell
            (ll, ur) = (shell[0][:2], shell[2][:2])
        elif gtype == 'Point':
            ll = ext_geom.coords[:2]
            ur = ll
        else:
            raise Exception('Unexpected geometry type returned for extent: %s' % gtype)
        (xmin, ymin) = ll
        (xmax, ymax) = ur
        return (xmin, ymin, xmax, ymax)
    else:
        return None

def _make_tensor(self, params, state):
    import numpy as np
    (size, steps, allocation_size) = self._get_size_and_steps(params)
    constructor = self._tensor_constructor or self.default_tensor_constructor
    raw_tensor = constructor(size=allocation_size, dtype=self._dtype, **params)
    if <MASK>:
        raw_tensor = raw_tensor.cuda()
    dim = len(size)
    order = np.arange(dim)
    if state.rand() > self._probability_contiguous:
        while dim > 1 and np.all(order == np.arange(dim)):
            order = state.permutation(raw_tensor.dim())
        raw_tensor = raw_tensor.permute(tuple(order)).contiguous()
        raw_tensor = raw_tensor.permute(tuple(np.argsort(order)))
    slices = [slice(0, size * step, step) for (size, step) in zip(size, steps)]
    tensor = raw_tensor[tuple(slices)]
    properties = {'numel': int(tensor.numel()), 'order': order, 'steps': steps, 'is_contiguous': tensor.is_contiguous(), 'dtype': str(self._dtype)}
    return (tensor, properties)

def _call(self, *args, **kwds):
    """Calls the graph function."""
    self._lock.acquire()
    bound_args = function_type_utils.canonicalize_function_inputs(args, kwds, self._function_type, self._default_values, self._is_pure)
    (args, kwds) = (bound_args.args, bound_args.kwargs)
    if self._created_variables:
        self._lock.release()
        return tracing_compilation.call_function(args, kwds, self._no_variable_creation_config)
    elif <MASK>:
        self._lock.release()
        results = tracing_compilation.call_function(args, kwds, self._variable_creation_config)
        if self._created_variables:
            raise ValueError('Creating variables on a non-first call to a function decorated with tf.function.')
        return results
    try:
        initializers = []
        self._initialize(args, kwds, add_initializers_to=initializers)
    finally:
        self._lock.release()
    if self._created_variables:
        try:
            self._initialize_uninitialized_variables(initializers)
        except lift_to_graph.UnliftableError:
            pass
        else:
            return tracing_compilation.call_function(args, kwds, self._no_variable_creation_config)
    else:
        bound_args = self._concrete_variable_creation_fn.function_type.bind(*args, **kwds)
        filtered_flat_args = self._concrete_variable_creation_fn.function_type.unpack_inputs(bound_args)
        return self._concrete_variable_creation_fn._call_flat(filtered_flat_args, self._concrete_variable_creation_fn.captured_inputs)

    def fn_with_cond(inner_args, inner_kwds):
        """Conditionally runs initialization if it's needed."""
        condition = True
        for (v, _) in initializers:
            condition = math_ops.logical_and(condition, resource_variable_ops.var_is_initialized_op(v.handle))
        return cond.cond(condition, lambda : tracing_compilation.call_function(inner_args, inner_kwds, self._no_variable_creation_config), lambda : self._concrete_variable_creation_fn(*inner_args, **inner_kwds))
    if self._jit_compile:
        raise errors.UnimplementedError(None, None, 'We failed to lift variable creations out of this tf.function, so this tf.function cannot be run on XLA. A possible workaround is to move variable creation outside of the XLA compiled function.')
    (canon_args, canon_kwds) = (bound_args.args, bound_args.kwargs)
    options = tracing_compilation.TracingOptions(fn_with_cond, 'fn_with_cond')
    return tracing_compilation.call_function((canon_args, canon_kwds), {}, options)

