def read_file(file_path: Union[str, Path]) -> str:
    try:
        if isinstance(file_path, Path):
            if file_path.is_file():
                with file_path.open('r') as f:
                    return f.read()
            else:
                print(f'::warning file {file_path} does not exist.')
        elif <MASK>:
            if os.path.isfile(file_path):
                with open(file_path) as f:
                    return f.read()
            else:
                print(f'::warning file {file_path} does not exist.')
        else:
            print(f'::warning unsupported file_path type: {type(file_path)}')
    except Exception as e:
        print(f'::warning trying to read file {file_path} failed by: {e}')
    return ''

def _add_global_state_dependencies(graph: torch.fx.Graph, node_to_additional_deps: dict[Node, OrderedSet[Node]]) -> None:
    import torch.amp
    all_nodes = list(graph.nodes)
    global_state_targets = {torch.amp._enter_autocast, torch.amp._exit_autocast}
    all_nodes_dep_on: list[Node] = []

    def prev_cur_nodes(all_nodes: list[Node]) -> Generator[tuple[list[Node], Node], None, None]:
        prev_nodes: list[Node] = []
        next_nodes = list(reversed(all_nodes))
        while next_nodes:
            cur_node = next_nodes.pop()
            yield (prev_nodes, cur_node)
            prev_nodes.append(cur_node)
    for (prev_nodes, cur_node) in prev_cur_nodes(all_nodes):
        args_unique = _get_flat_args_unique(cur_node, {})
        new_deps = [n for n in all_nodes_dep_on if n not in args_unique]
        if <MASK>:
            additional_deps = node_to_additional_deps[cur_node]
            additional_deps.update(new_deps)
        if cur_node.target in global_state_targets:
            additional_deps = node_to_additional_deps[cur_node]
            additional_deps.update((n for n in prev_nodes if n not in args_unique))
            all_nodes_dep_on.append(cur_node)

@ops.RegisterGradient('Merge')
def _MergeGrad(op, grad, _):
    """Gradients for a Merge op are calculated using a Switch op."""
    input_op = op.inputs[0].op
    graph = ops.get_default_graph()
    op_ctxt = control_flow_util.GetOutputContext(input_op)
    grad_ctxt = graph._get_control_flow_context()
    if <MASK>:
        return control_flow_ops._SwitchRefOrTensor(grad, grad_ctxt.pivot)
    elif isinstance(op_ctxt, CondContext):
        pred = op_ctxt.pred
        if grad_ctxt and grad_ctxt.grad_state:
            grad_state = grad_ctxt.grad_state
            real_pred = grad_state.history_map.get(pred.name)
            if real_pred is None:
                grad_ctxt = grad_state.grad_context
                grad_ctxt.Exit()
                history_pred = grad_state.AddForwardAccumulator(pred)
                grad_ctxt.Enter()
                real_pred = grad_state.AddBackpropAccumulatedValue(history_pred, pred)
                grad_state.history_map[pred.name] = real_pred
            pred = real_pred
        return control_flow_ops._SwitchRefOrTensor(grad, pred, name='cond_grad')
    else:
        num_inputs = len(op.inputs)
        cond = [math_ops.equal(op.outputs[1], i) for i in range(num_inputs)]
        return [control_flow_ops._SwitchRefOrTensor(grad, cond[i])[1] for i in range(num_inputs)]

@_onnx_symbolic('aten::split')
@symbolic_helper.parse_args('v', 'v', 'i', 'i')
def split(g: jit_utils.GraphContext, self, split_size_or_sizes, dim, _outputs=None):
    if <MASK>:
        return symbolic_helper._onnx_opset_unsupported_detailed('split', 9, 11, 'Dynamic number of outputs not supported', self)
    split_val = symbolic_helper._node_get(split_size_or_sizes.node(), 'value')
    if split_val.dim() > 0:
        return split_with_sizes(g, self, split_size_or_sizes, dim, _outputs)
    split_size = symbolic_helper._get_const(split_size_or_sizes, 'i', 'split_size')
    size = symbolic_helper._get_tensor_dim_size(self, dim)
    if size is None:
        if _outputs is not None:
            size = split_size * _outputs
        else:
            return symbolic_helper._onnx_opset_unsupported_detailed('split', 9, 11, 'Unknown dimension size not supported', self)
    splits = [split_size] * (size // split_size)
    leftover = size % split_size
    if leftover:
        splits.append(leftover)
    return g.op('Split', self, split_i=splits, axis_i=dim, outputs=_outputs)

