@_onnx_symbolic('aten::layer_norm')
@symbolic_helper.parse_args('v', 'is', 'v', 'v', 'f', 'none')
def layer_norm(g: jit_utils.GraphContext, input: _C.Value, normalized_shape: Sequence[int], weight: _C.Value, bias: _C.Value, eps: float, cudnn_enable: bool):
    axis = -len(normalized_shape)
    scalar_type = _type_utils.JitScalarType.from_value(input, _type_utils.JitScalarType.FLOAT)
    dtype = scalar_type.dtype()
    if symbolic_helper._is_none(weight):
        weight_value = torch.ones(normalized_shape, dtype=dtype)
        weight = g.op('Constant', value_t=weight_value)
    if <MASK>:
        bias_value = torch.zeros(normalized_shape, dtype=dtype)
        bias = g.op('Constant', value_t=bias_value)
    return g.op('LayerNormalization', input, weight, bias, epsilon_f=eps, axis_i=axis)

def _compare(self, x, reduction_axes, keepdims, use_gpu=False):
    np_ans = x
    if <MASK>:
        np_ans = np.all(np_ans, keepdims=keepdims)
    else:
        for ra in reduction_axes[::-1]:
            np_ans = np.all(np_ans, axis=ra, keepdims=keepdims)
    with self.cached_session(use_gpu=use_gpu):
        if reduction_axes is not None:
            reduction_axes = np.array(reduction_axes).astype(np.int32)
        tf_ans = math_ops.reduce_all(x, reduction_axes, keepdims)
        out = self.evaluate(tf_ans)
    self.assertAllEqual(np_ans, out)
    self.assertShapeEqual(np_ans, tf_ans)

def get_field_type(self, data_type, description):
    field_type = super().get_field_type(data_type, description)
    if 'auto_increment' in description.extra:
        if field_type == 'IntegerField':
            return 'AutoField'
        elif field_type == 'BigIntegerField':
            return 'BigAutoField'
        elif <MASK>:
            return 'SmallAutoField'
    if description.is_unsigned:
        if field_type == 'BigIntegerField':
            return 'PositiveBigIntegerField'
        elif field_type == 'IntegerField':
            return 'PositiveIntegerField'
        elif field_type == 'SmallIntegerField':
            return 'PositiveSmallIntegerField'
    if description.data_type.upper() == 'UUID':
        return 'UUIDField'
    if description.has_json_constraint:
        return 'JSONField'
    return field_type

