def cast_based_on_args(self, model, example_inputs):
    if <MASK>:
        if not self.args.float32:
            log.warning('Model %s supports float32 only', self.args.only)
        (model, example_inputs) = cast_to_fp32(model, example_inputs)
    elif self.args.float16:
        if self.args.only in self.force_amp_for_fp16_bf16_models:
            log.warning('Model %s does not support float16, running with amp instead', self.args.only)
            self.args.amp = True
            self.setup_amp()
        else:
            (model, example_inputs) = cast_to_fp16(model, example_inputs)
    elif self.args.bfloat16:
        if self.args.only in self.force_amp_for_fp16_bf16_models:
            log.warning('Model %s does not support bfloat16, running with amp instead', self.args.only)
            self.args.amp = True
            self.setup_amp()
        elif self.args.only in self.force_fp16_for_bf16_models:
            log.warning('Model %s does not support bfloat16, running with float16 instead', self.args.only)
            (model, example_inputs) = cast_to_fp16(model, example_inputs)
        else:
            (model, example_inputs) = cast_to_bf16(model, example_inputs)
    return (model, example_inputs)

def infer_limit_direction(limit_direction: Literal['backward', 'forward', 'both'] | None, method: str) -> Literal['backward', 'forward', 'both']:
    if limit_direction is None:
        if <MASK>:
            limit_direction = 'backward'
        else:
            limit_direction = 'forward'
    else:
        if method in ('pad', 'ffill') and limit_direction != 'forward':
            raise ValueError(f"`limit_direction` must be 'forward' for method `{method}`")
        if method in ('backfill', 'bfill') and limit_direction != 'backward':
            raise ValueError(f"`limit_direction` must be 'backward' for method `{method}`")
    return limit_direction

def isWrappedScalarType(typ: Type) -> bool:
    """
    Given a type, determine if it is a c10::scalar which we will wrap in a lazy Value.
    Since we literally change the type from scalarT to valueT, information is lost.
    This function helps build a list of wrapped scalars to save that information
    """
    if isinstance(typ, BaseType):
        return typ.name == BaseTy.Scalar
    elif <MASK>:
        return isWrappedScalarType(typ.elem)
    return False

