@staticmethod
def from_float(cls, mod, use_precomputed_fake_quant=False):
    if hasattr(mod, 'weight_fake_quant'):
        if <MASK>:
            (mod.weight, mod.bias) = fuse_conv_bn_weights(mod.weight, mod.bias, mod.bn.running_mean, mod.bn.running_var, mod.bn.eps, mod.bn.weight, mod.bn.bias)
        assert hasattr(mod, 'activation_post_process'), 'Input QAT module must have observer attached'
        weight_post_process = mod.weight_fake_quant
        activation_post_process = mod.activation_post_process
    else:
        assert type(mod) is cls._FLOAT_MODULE, ' nnq.' + cls.__name__ + '.from_float only works for ' + cls._FLOAT_MODULE.__name__ + ' but got:' + str(type(mod))
        assert hasattr(mod, 'qconfig'), 'Input float module must have qconfig defined.'
        activation_post_process = None if not hasattr(mod, 'activation_post_process') else mod.activation_post_process
        if type(mod) in [cls._NNI_CONV_RELU_MODULE, cls._NNI_CONV_ADD_MODULE, cls._NNI_CONV_ADD_RELU_MODULE]:
            mod = mod[0]
        weight_post_process = mod.qconfig.weight()
    return cls.get_qconv(mod, activation_post_process, weight_post_process)

