def get_tolerance_and_cosine_flag(self, is_training, current_device, name):
    cosine = self.args.cosine
    if is_training:
        from torch._inductor import config as inductor_config
        if name in self._config['tolerance']['higher_training'] or (inductor_config.max_autotune and name in self._config['tolerance']['higher_max_autotune_training']):
            return (0.02, cosine)
        else:
            return (0.01, cosine)
    else:
        if <MASK>:
            return (0.005, cosine)
        if name in self._config['tolerance']['higher_inference']:
            return (0.004, cosine)
    return (0.001, cosine)

def _make_indexed_slices_indices_types_match(op_type, branch_graphs):
    """Match dtype of IndexedSlices.indices in outputs of branch_graphs."""
    assert branch_graphs
    indexed_slice_indices = []
    current_index = 0
    branch_outputs_flat_with_composites = [nest.flatten(branch_graph.structured_outputs, expand_composites=False) for branch_graph in branch_graphs]
    outs_per_branch = [len(outs) for outs in branch_outputs_flat_with_composites]
    assert len(set(outs_per_branch)) == 1, outs_per_branch
    for (output_idx, branch_outs) in enumerate(zip(*branch_outputs_flat_with_composites)):
        if len(set((isinstance(out, indexed_slices.IndexedSlices) for out in branch_outs))) != 1:
            raise TypeError('Cannot reconcile tf.{op_name} {output_idx}-th outputs:\n  branches returned: {outputs}'.format(op_name='cond' if op_type == _COND else 'switch_case', output_idx=output_idx, outputs=branch_outs))
        if isinstance(branch_outs[0], indexed_slices.IndexedSlices):
            indexed_slice_indices.append(current_index + 1)
        if nest.is_nested_or_composite(branch_outs[0]):
            current_index += len(nest.flatten(branch_outs[0], expand_composites=True))
        elif branch_outs[0] is not None:
            current_index += 1
    if not indexed_slice_indices:
        return
    if current_index != len(branch_graphs[0].outputs):
        raise ValueError('Insufficient elements in branch_graphs[0].outputs.\nExpected: %i\nActual: %i' % (current_index, len(branch_graphs[0].outputs)))
    for index in indexed_slice_indices:
        if any((bg.outputs[index].dtype not in (dtypes.int32, dtypes.int64) for bg in branch_graphs)):
            raise TypeError('Type of IndexedSlices.indices must be int32 or int64. Found: %s' % str([bg.outputs[index].dtype for bg in branch_graphs]))
        if len(set((bg.outputs[index].dtype for bg in branch_graphs))) != 1:
            for branch_graph in branch_graphs:
                if <MASK>:
                    with branch_graph.as_default():
                        branch_graph.outputs[index] = math_ops.cast(branch_graph.outputs[index], dtypes.int64)
    for branch_graph in branch_graphs:
        branch_graph.structured_outputs = _pack_sequence_as(branch_graph.structured_outputs, branch_graph.outputs)

def handle(self, app_or_project, name, target=None, **options):
    self.app_or_project = app_or_project
    self.a_or_an = 'an' if app_or_project == 'app' else 'a'
    self.paths_to_remove = []
    self.verbosity = options['verbosity']
    self.validate_name(name)
    if target is None:
        top_dir = os.path.join(os.getcwd(), name)
        try:
            os.makedirs(top_dir)
        except FileExistsError:
            raise CommandError("'%s' already exists" % top_dir)
        except OSError as e:
            raise CommandError(e)
    else:
        top_dir = os.path.abspath(os.path.expanduser(target))
        if app_or_project == 'app':
            self.validate_name(os.path.basename(top_dir), 'directory')
        if not os.path.exists(top_dir):
            try:
                os.makedirs(top_dir)
            except OSError as e:
                raise CommandError(e)
    formatter_paths = find_formatters()
    extensions = tuple(handle_extensions(options['extensions']))
    extra_files = []
    excluded_directories = ['.git', '__pycache__']
    for file in options['files']:
        extra_files.extend(map(lambda x: x.strip(), file.split(',')))
    if (exclude := options.get('exclude')):
        for directory in exclude:
            excluded_directories.append(directory.strip())
    if self.verbosity >= 2:
        self.stdout.write('Rendering %s template files with extensions: %s' % (app_or_project, ', '.join(extensions)))
        self.stdout.write('Rendering %s template files with filenames: %s' % (app_or_project, ', '.join(extra_files)))
    base_name = '%s_name' % app_or_project
    base_subdir = '%s_template' % app_or_project
    base_directory = '%s_directory' % app_or_project
    camel_case_name = 'camel_case_%s_name' % app_or_project
    camel_case_value = ''.join((x for x in name.title() if x != '_'))
    context = Context({**options, base_name: name, base_directory: top_dir, camel_case_name: camel_case_value, 'docs_version': get_docs_version(), 'django_version': django.__version__}, autoescape=False)
    if not settings.configured:
        settings.configure()
        django.setup()
    template_dir = self.handle_template(options['template'], base_subdir)
    prefix_length = len(template_dir) + 1
    for (root, dirs, files) in os.walk(template_dir):
        path_rest = root[prefix_length:]
        relative_dir = path_rest.replace(base_name, name)
        if relative_dir:
            target_dir = os.path.join(top_dir, relative_dir)
            os.makedirs(target_dir, exist_ok=True)
        for dirname in dirs[:]:
            if 'exclude' not in options:
                if dirname.startswith('.') or dirname == '__pycache__':
                    dirs.remove(dirname)
            elif dirname in excluded_directories:
                dirs.remove(dirname)
        for filename in files:
            if filename.endswith(('.pyo', '.pyc', '.py.class')):
                continue
            old_path = os.path.join(root, filename)
            new_path = os.path.join(top_dir, relative_dir, filename.replace(base_name, name))
            for (old_suffix, new_suffix) in self.rewrite_template_suffixes:
                if new_path.endswith(old_suffix):
                    new_path = new_path.removesuffix(old_suffix) + new_suffix
                    break
            if <MASK>:
                raise CommandError("%s already exists. Overlaying %s %s into an existing directory won't replace conflicting files." % (new_path, self.a_or_an, app_or_project))
            if new_path.endswith(extensions) or filename in extra_files:
                with open(old_path, encoding='utf-8') as template_file:
                    content = template_file.read()
                template = Engine().from_string(content)
                content = template.render(context)
                with open(new_path, 'w', encoding='utf-8') as new_file:
                    new_file.write(content)
            else:
                shutil.copyfile(old_path, new_path)
            if self.verbosity >= 2:
                self.stdout.write('Creating %s' % new_path)
            try:
                self.apply_umask(old_path, new_path)
                self.make_writeable(new_path)
            except OSError:
                self.stderr.write("Notice: Couldn't set permission bits on %s. You're probably using an uncommon filesystem setup. No problem." % new_path, self.style.NOTICE)
    if self.paths_to_remove:
        if self.verbosity >= 2:
            self.stdout.write('Cleaning up temporary files.')
        for path_to_remove in self.paths_to_remove:
            if os.path.isfile(path_to_remove):
                os.remove(path_to_remove)
            else:
                shutil.rmtree(path_to_remove)
    run_formatters([top_dir], **formatter_paths, stderr=self.stderr)

def skip_if_rocm_ver_lessthan_multiprocess(version=None):
    """Skips a test for ROCm based on ROCm ver - multiprocess UTs"""

    def decorator(func):
        reason = None
        if <MASK>:
            rocm_version = str(torch.version.hip)
            rocm_version = rocm_version.split('-', maxsplit=1)[0]
            rocm_version_tuple = tuple((int(x) for x in rocm_version.split('.')))
            if rocm_version_tuple is None or version is None or rocm_version_tuple < tuple(version):
                reason = f'skip_if_rocm_ver_lessthan_multiprocess: ROCm {rocm_version_tuple} is available but {version} required'
        return unittest.skipIf(reason is not None, reason)(func)
    return decorator

def _normalize_outputs(outputs, function_name, signature_key):
    """Normalize outputs if necessary and check that they are tensors."""
    if not isinstance(outputs, collections_abc.Mapping):
        if hasattr(outputs, '_asdict'):
            outputs = outputs._asdict()
        else:
            if <MASK>:
                outputs = [outputs]
            outputs = {'output_{}'.format(output_index): output for (output_index, output) in enumerate(outputs)}
    for (key, value) in outputs.items():
        if not isinstance(key, compat.bytes_or_text_types):
            raise ValueError(f'Got a dictionary with a non-string key {key!r} in the output of the function {compat.as_str_any(function_name)} used to generate the SavedModel signature {signature_key!r}.')
        if not isinstance(value, (tensor.Tensor, composite_tensor.CompositeTensor)):
            raise ValueError(f'Got a non-Tensor value {value!r} for key {key!r} in the output of the function {compat.as_str_any(function_name)} used to generate the SavedModel signature {signature_key!r}. Outputs for functions used as signatures must be a single Tensor, a sequence of Tensors, or a dictionary from string to Tensor.')
    return outputs

def unroll(num_unrolls, IndexType, InType, OutType):

    def compute_output(num_unrolls, InType, is_main):
        code = []
        pred = 'svAll' if is_main else 'pg'
        if <MASK>:
            for i in range(num_unrolls):
                code.append(f'        output = svmla_x({pred}, output, svld1(svAll, &ip{i}[k]), wgt{i});')
        elif InType == 'at::Half':
            for i in range(num_unrolls):
                code.append(f'        auto input{i} = svcvt_f32_x({pred}, svreinterpret_f16(\n          svld1uh_u32({pred}, reinterpret_cast<const uint16_t*>(&ip{i}[k]))));')
            for i in range(num_unrolls):
                code.append(f'        output = svmla_x({pred}, output, input{i}, wgt{i});')
        elif InType == 'at::BFloat16':
            for i in range(num_unrolls):
                code.append(f'        auto input{i} = svreinterpret_f32(svlsl_x({pred},\n          svld1uh_u32({pred}, reinterpret_cast<const uint16_t*>(&ip{i}[k])), 16));')
            for i in range(num_unrolls):
                code.append(f'        output = svmla_x({pred}, output, input{i}, wgt{i});')
        elif InType == 'uint8_t':
            code.append(f'        output = svadd_x({pred}, output, bio);')
            for i in range(num_unrolls):
                code.append(f'        auto input{i} = svcvt_f32_x({pred}, svld1ub_u32({pred}, &ip{i}[k]));')
            for i in range(num_unrolls):
                code.append(f'        output = svmla_x({pred}, output, input{i}, wgt{i});')
        else:
            raise ValueError(f'Unknown datatype "{InType}"')
        return code
    code = []
    if num_unrolls == 1:
        code.append('    // tail loop')
        code.append('    if (j < end_offset) {')
    else:
        code.append(f'    // unrolling {num_unrolls} times')
        code.append(f'    while (j + {num_unrolls - 1} < end_offset) {{')
    for i in range(num_unrolls):
        code.append(f'      const auto idx{i} = indices[pos + {i}];')
    for i in range(num_unrolls):
        code.append(f'      if (idx{i} < 0 || idx{i} >= data_size) {{\n' + '        return false;\n' + '      }')
    if InType == 'uint8_t':
        for i in range(num_unrolls):
            code.append(f'      {OutType} wgt{i} = 1.f;')
        code.append(f'      {OutType} bio = 0.f;')
    else:
        for i in range(num_unrolls):
            code.append(f'      {OutType} wgt{i} = 1.f;')
    code.append('      if (weights) {')
    for i in range(num_unrolls):
        code.append(f'        wgt{i} = weights[IS_WEIGHT_POSITIONAL ? (j + {i} - start_offset) : pos + {i}];')
    code.append('      }')
    if InType == 'uint8_t':
        code.append('      if (scale_bias) {')
        for i in range(num_unrolls):
            code.append(f'        bio += wgt{i} * scale_bias[2 * idx{i} + 1];')
            code.append(f'        wgt{i} = wgt{i} * scale_bias[2 * idx{i}];')
        code.append('      }')
    for i in range(num_unrolls):
        code.append(f'      const {InType}* const ip{i} = &input[idx{i} * block_size];')
    code.append('      svbool_t pg;')
    code.append('      int64_t k = 0;')
    code.append('      while (k + vLen - 1 < block_size) {')
    code.append('        auto output = svld1(svAll, &op[k]);')
    code.extend(compute_output(num_unrolls, InType, True))
    code.append('        svst1(svAll, &op[k], output);')
    code.append('        k += vLen;')
    code.append('      }')
    code.append('      if (k < block_size) {')
    code.append('        pg = svwhilelt_b32_s64(k, block_size);')
    code.append('        auto output = svld1(pg, &op[k]);')
    code.extend(compute_output(num_unrolls, InType, False))
    code.append('        svst1(pg, &op[k], output);')
    code.append('        k += vLen;')
    code.append('      }')
    if num_unrolls == 1:
        code.append('      pos ++;')
    else:
        code.append(f'      j += {num_unrolls};')
        code.append(f'      pos += {num_unrolls};')
    code.append('    }')
    return code

def _extend_op(values, leaf_op, empty_st_op=None):
    """Extend an op from RaggedTensor and Tensor to StructuredTensor.

  Visits all children of the structured tensor, and children of children,
  applying leaf_op whenever it reaches a leaf, and empty_st_op whenever
  it reaches an internal node without children.

  Args:
    values: a list of structured tensors, ragged tensors, or tensors. All must
      have the same type. If they are structured tensors, they must have the
      same paths.
    leaf_op: an op for handling non-structured tensor.
    empty_st_op: op to create a structured tensor without fields.

  Returns:
    the result of the extended op (a StructuredTensor, RaggedTensor, or Tensor)

  Raises:
    ValueError:
      If values is not a Sequence or is empty.
  """
    if not isinstance(values, Sequence):
        raise ValueError('Expected a list')
    if not values:
        raise ValueError('List cannot be empty')
    if empty_st_op is None:
        empty_st_op = empty_st_op_like_zeros(leaf_op)
    value = values[0]
    if <MASK>:
        empty_result = empty_st_op(values)
        if not value.field_names():
            return empty_result
        new_fields = {}
        for k in value.field_names():
            new_fields[k] = _extend_op([v.field_value(k) for v in values], leaf_op, empty_st_op)
        return StructuredTensor.from_fields(new_fields, shape=empty_result.shape)
    else:
        return leaf_op(values)

def scatter_meta_impl(self, dim, index, src=None, reduce_=None, use_new_options=False):
    wrapped_dim = maybe_wrap_dim(dim, self.dim())
    scatter_gather_dtype_check('scatter', self, index, src)
    scatter_shape_check(self, wrapped_dim, index, src)
    if <MASK>:
        get_operator_enum(reduce_, use_new_options)

def isdtype(dtype: DType, kind: Union[DType, str, Tuple[Union[DType, str], ...]], *, _tuple=True) -> bool:
    """
    Returns a boolean indicating whether a provided dtype is of a specified data type ``kind``.

    Note that outside of this function, this compat library does not yet fully
    support complex numbers.

    See
    https://data-apis.org/array-api/latest/API_specification/generated/array_api.isdtype.html
    for more details
    """
    if isinstance(kind, tuple) and _tuple:
        return _builtin_any((isdtype(dtype, k, _tuple=False) for k in kind))
    elif isinstance(kind, str):
        if <MASK>:
            return dtype == torch.bool
        elif kind == 'signed integer':
            return dtype in _int_dtypes and dtype.is_signed
        elif kind == 'unsigned integer':
            return dtype in _int_dtypes and (not dtype.is_signed)
        elif kind == 'integral':
            return dtype in _int_dtypes
        elif kind == 'real floating':
            return dtype.is_floating_point
        elif kind == 'complex floating':
            return dtype.is_complex
        elif kind == 'numeric':
            return isdtype(dtype, ('integral', 'real floating', 'complex floating'))
        else:
            raise ValueError(f'Unrecognized data type kind: {kind!r}')
    else:
        return dtype == kind

def content_disposition_header(as_attachment, filename):
    """
    Construct a Content-Disposition HTTP header value from the given filename
    as specified by RFC 6266.
    """
    if <MASK>:
        disposition = 'attachment' if as_attachment else 'inline'
        try:
            filename.encode('ascii')
            is_ascii = True
        except UnicodeEncodeError:
            is_ascii = False
        quotable_characters = '^[\\t \\x21-\\x7e]*$'
        if is_ascii and re.match(quotable_characters, filename):
            file_expr = 'filename="{}"'.format(filename.replace('\\', '\\\\').replace('"', '\\"'))
        else:
            file_expr = "filename*=utf-8''{}".format(quote(filename))
        return f'{disposition}; {file_expr}'
    elif as_attachment:
        return 'attachment'
    else:
        return None

def _meshgrid(*tensors, indexing: Optional[str]):
    if <MASK>:
        return handle_torch_function(meshgrid, tensors, *tensors, indexing=indexing)
    if len(tensors) == 1 and isinstance(tensors[0], (list, tuple)):
        tensors = tensors[0]
    kwargs = {} if indexing is None else {'indexing': indexing}
    return _VF.meshgrid(tensors, **kwargs)

def is_none_layout(buf_name: str) -> bool:
    """
            Checks if buf_name is NoneLayout. Buffers with NoneLayout is not allocated
            so graph partition should not take it as inputs or outputs.
            """
    buf = self.name_to_buf.get(buf_name, None)
    if buf is None:
        return False
    if <MASK>:
        if isinstance(buf.node, ir.MutationOutput) and (real_name := self.mutation_real_name.get(buf_name, None)):
            return is_none_layout(real_name)
        return True
    return False

def _is_qconfig_supported_by_dtype_configs(qconfig: QConfig, dtype_configs: list[DTypeConfig]):
    for dtype_config in dtype_configs:
        is_dynamic = dtype_config.is_dynamic
        if is_dynamic is None:
            is_dynamic = False
        input_dtype = dtype_config.input_dtype or torch.float
        weight_dtype = dtype_config.weight_dtype or torch.float
        bias_dtype = dtype_config.bias_dtype or torch.float
        output_dtype = dtype_config.output_dtype or torch.float
        (qconfig_activation_dtype, qconfig_weight_dtype, qconfig_input_act_is_dynamic) = get_qconfig_dtypes(qconfig)
        qconfig_bias_dtype = torch.float16 if qconfig_activation_dtype == torch.float16 and qconfig_weight_dtype == torch.float16 and (not is_dynamic) else torch.float
        if is_dynamic:
            is_match = qconfig_input_act_is_dynamic and input_dtype == qconfig_activation_dtype and (output_dtype == torch.float) and (weight_dtype == qconfig_weight_dtype)
        else:
            is_match = input_dtype == qconfig_activation_dtype and output_dtype == qconfig_activation_dtype and (weight_dtype == qconfig_weight_dtype) and (bias_dtype == qconfig_bias_dtype)
        if <MASK>:
            return True
    return False

def generate_values(base, densesize):
    """Generates a tensor of shape densesize with values equal to

              base + i_1 * 10^0 + ... + i_d * 10^{d - 1}

            at indices i_1, ..., i_d (with 0 <= i_j < densesize[j] for any 1 <= j <=
            len(densesize))

            This mapping produces unique values as long as
            densesize[i] < 10 for all i in range(len(densesize)).
            """
    if <MASK>:
        return base
    if not isinstance(base, int) and base.ndim > 0:
        return torch.stack([generate_values(b, densesize) for b in base])
    if base == 0:
        return torch.zeros(densesize, dtype=torch.int64)
    r = torch.arange(densesize[0], dtype=torch.int64)
    for (i, d) in enumerate(densesize[1:]):
        y = torch.arange(d, dtype=torch.int64) * 10 ** (i + 1)
        r = r[..., None] + y[None, ...]
    r.add_(base)
    return r

def remove_node(self, node: fx.Node) -> None:
    if len(node.users) > 0:
        user_graph_nodes: list[torch.fx.Node] = []
        for user in node.users.keys():
            if <MASK>:
                user_graph_nodes.extend(reversed(list(user.graph.nodes)))
        for other_graph_node in user_graph_nodes:
            other_graph_node.graph.erase_node(other_graph_node)
    self.graph.erase_node(node)
    self.input_name_to_proxy.pop(node.name, None)

def stream_with_context(generator_or_function: t.Iterator[t.AnyStr] | t.Callable[..., t.Iterator[t.AnyStr]]) -> t.Iterator[t.AnyStr] | t.Callable[[t.Iterator[t.AnyStr]], t.Iterator[t.AnyStr]]:
    """Wrap a response generator function so that it runs inside the current
    request context. This keeps :data:`.request`, :data:`.session`, and :data:`.g`
    available, even though at the point the generator runs the request context
    will typically have ended.

    Use it as a decorator on a generator function:

    .. code-block:: python

        from flask import stream_with_context, request, Response

        @app.get("/stream")
        def streamed_response():
            @stream_with_context
            def generate():
                yield "Hello "
                yield request.args["name"]
                yield "!"

            return Response(generate())

    Or use it as a wrapper around a created generator:

    .. code-block:: python

        from flask import stream_with_context, request, Response

        @app.get("/stream")
        def streamed_response():
            def generate():
                yield "Hello "
                yield request.args["name"]
                yield "!"

            return Response(stream_with_context(generate()))

    .. versionadded:: 0.9
    """
    try:
        gen = iter(generator_or_function)
    except TypeError:

        def decorator(*args: t.Any, **kwargs: t.Any) -> t.Any:
            gen = generator_or_function(*args, **kwargs)
            return stream_with_context(gen)
        return update_wrapper(decorator, generator_or_function)

    def generator() -> t.Iterator[t.AnyStr]:
        if <MASK>:
            raise RuntimeError("'stream_with_context' can only be used when a request context is active, such as in a view function.")
        with ctx:
            yield None
            try:
                yield from gen
            finally:
                if hasattr(gen, 'close'):
                    gen.close()
    wrapped_g = generator()
    next(wrapped_g)
    return wrapped_g

def _reset_cache(self, key: str | None=None) -> None:
    """
        Reset cached properties. If ``key`` is passed, only clears that key.
        """
    if not hasattr(self, '_cache'):
        return
    if <MASK>:
        self._cache.clear()
    else:
        self._cache.pop(key, None)

def get_backend_timeout(self, timeout=DEFAULT_TIMEOUT):
    """
        Return the timeout value usable by this backend based upon the provided
        timeout.
        """
    if <MASK>:
        timeout = self.default_timeout
    elif timeout == 0:
        timeout = -1
    return None if timeout is None else time.time() + timeout

def _wrap_jagged_dim(ndim, dim, ragged_dim, op_name, convert_to_inner_dim=True, allow_ragged_dim=False, allow_batch_dim=False):
    from torch._prims_common import canonicalize_dims
    wrapped = canonicalize_dims(ndim, dim)
    if wrapped == ragged_dim and (not allow_ragged_dim):
        raise RuntimeError(f'{op_name}(): not supported for NestedTensor on ragged dim')
    elif wrapped == 0 and (not allow_batch_dim):
        raise RuntimeError(f'{op_name}(): not supported for NestedTensor on dim=0')
    ret = _outer_to_inner_dim(ndim, wrapped, ragged_dim) if convert_to_inner_dim else wrapped
    if <MASK>:
        operating_on_batch = wrapped == 0
        return (ret, operating_on_batch)
    return ret

def _reduce_pyarrow(self, name: str, *, skipna: bool=True, **kwargs) -> pa.Scalar:
    """
        Return a pyarrow scalar result of performing the reduction operation.

        Parameters
        ----------
        name : str
            Name of the function, supported values are:
            { any, all, min, max, sum, mean, median, prod,
            std, var, sem, kurt, skew }.
        skipna : bool, default True
            If True, skip NaN values.
        **kwargs
            Additional keyword arguments passed to the reduction function.
            Currently, `ddof` is the only supported kwarg.

        Returns
        -------
        pyarrow scalar

        Raises
        ------
        TypeError : subclass does not define reductions
        """
    pa_type = self._pa_array.type
    data_to_reduce = self._pa_array
    if name in ['any', 'all'] and (pa.types.is_integer(pa_type) or pa.types.is_floating(pa_type) or pa.types.is_duration(pa_type) or pa.types.is_decimal(pa_type)):
        if <MASK>:
            data_to_cmp = self._pa_array.cast(pa.int64())
        else:
            data_to_cmp = self._pa_array
        not_eq = pc.not_equal(data_to_cmp, 0)
        data_to_reduce = not_eq
    elif name in ['min', 'max', 'sum'] and pa.types.is_duration(pa_type):
        data_to_reduce = self._pa_array.cast(pa.int64())
    elif name in ['median', 'mean', 'std', 'sem'] and pa.types.is_temporal(pa_type):
        nbits = pa_type.bit_width
        if nbits == 32:
            data_to_reduce = self._pa_array.cast(pa.int32())
        else:
            data_to_reduce = self._pa_array.cast(pa.int64())
    if name == 'sem':

        def pyarrow_meth(data, skip_nulls, **kwargs):
            numerator = pc.stddev(data, skip_nulls=skip_nulls, **kwargs)
            denominator = pc.sqrt_checked(pc.count(self._pa_array))
            return pc.divide_checked(numerator, denominator)
    elif name == 'sum' and (pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type)):

        def pyarrow_meth(data, skip_nulls, min_count=0):
            mask = pc.is_null(data) if data.null_count > 0 else None
            if skip_nulls:
                if min_count > 0 and check_below_min_count((len(data),), None if mask is None else mask.to_numpy(), min_count):
                    return pa.scalar(None, type=data.type)
                if data.null_count > 0:
                    data = data.filter(pc.invert(mask))
            elif mask is not None or check_below_min_count((len(data),), None, min_count):
                return pa.scalar(None, type=data.type)
            if pa.types.is_large_string(data.type):
                data = data.cast(pa.string())
            data_list = pa.ListArray.from_arrays([0, len(data)], data.combine_chunks())[0]
            return pc.binary_join(data_list, '')
    else:
        pyarrow_name = {'median': 'quantile', 'prod': 'product', 'std': 'stddev', 'var': 'variance'}.get(name, name)
        pyarrow_meth = getattr(pc, pyarrow_name, None)
        if pyarrow_meth is None:
            return super()._reduce(name, skipna=skipna, **kwargs)
    if name in ['any', 'all'] and 'min_count' not in kwargs:
        kwargs['min_count'] = 0
    elif name == 'median':
        kwargs['q'] = 0.5
    try:
        result = pyarrow_meth(data_to_reduce, skip_nulls=skipna, **kwargs)
    except (AttributeError, NotImplementedError, TypeError) as err:
        msg = f"'{type(self).__name__}' with dtype {self.dtype} does not support operation '{name}' with pyarrow version {pa.__version__}. '{name}' may be supported by upgrading pyarrow."
        raise TypeError(msg) from err
    if name == 'median':
        result = result[0]
    if name in ['min', 'max', 'sum'] and pa.types.is_duration(pa_type):
        result = result.cast(pa_type)
    if name in ['median', 'mean'] and pa.types.is_temporal(pa_type):
        nbits = pa_type.bit_width
        if nbits == 32:
            result = result.cast(pa.int32(), safe=False)
        else:
            result = result.cast(pa.int64(), safe=False)
        result = result.cast(pa_type)
    if name in ['std', 'sem'] and pa.types.is_temporal(pa_type):
        result = result.cast(pa.int64(), safe=False)
        if pa.types.is_duration(pa_type):
            result = result.cast(pa_type)
        elif pa.types.is_time(pa_type):
            result = result.cast(pa.duration(pa_type.unit))
        elif pa.types.is_date(pa_type):
            result = result.cast(pa.duration('s'))
        else:
            result = result.cast(pa.duration(pa_type.unit))
    return result

def _get_column_indices(X, key):
    """Get feature column indices for input data X and key.

    For accepted values of `key`, see the docstring of
    :func:`_safe_indexing`.
    """
    key_dtype = _determine_key_type(key)
    if _use_interchange_protocol(X):
        return _get_column_indices_interchange(X.__dataframe__(), key, key_dtype)
    n_columns = X.shape[1]
    if <MASK>:
        return []
    elif key_dtype in ('bool', 'int'):
        return _get_column_indices_for_bool_or_int(key, n_columns)
    else:
        try:
            all_columns = X.columns
        except AttributeError:
            raise ValueError('Specifying the columns using strings is only supported for dataframes.')
        if isinstance(key, str):
            columns = [key]
        elif isinstance(key, slice):
            (start, stop) = (key.start, key.stop)
            if start is not None:
                start = all_columns.get_loc(start)
            if stop is not None:
                stop = all_columns.get_loc(stop) + 1
            else:
                stop = n_columns + 1
            return list(islice(range(n_columns), start, stop))
        else:
            columns = list(key)
        try:
            column_indices = []
            for col in columns:
                col_idx = all_columns.get_loc(col)
                if not isinstance(col_idx, numbers.Integral):
                    raise ValueError(f'Selected columns, {columns}, are not unique in dataframe')
                column_indices.append(col_idx)
        except KeyError as e:
            raise ValueError('A given column is not a column of the dataframe') from e
        return column_indices

@final
def _rename(self, mapper: Renamer | None=None, *, index: Renamer | None=None, columns: Renamer | None=None, axis: Axis | None=None, inplace: bool=False, level: Level | None=None, errors: str='ignore') -> Self | None:
    if mapper is None and index is None and (columns is None):
        raise TypeError('must pass an index to rename')
    if index is not None or columns is not None:
        if axis is not None:
            raise TypeError("Cannot specify both 'axis' and any of 'index' or 'columns'")
        if mapper is not None:
            raise TypeError("Cannot specify both 'mapper' and any of 'index' or 'columns'")
    elif axis and self._get_axis_number(axis) == 1:
        columns = mapper
    else:
        index = mapper
    self._check_inplace_and_allows_duplicate_labels(inplace)
    result = self if inplace else self.copy(deep=False)
    for (axis_no, replacements) in enumerate((index, columns)):
        if replacements is None:
            continue
        ax = self._get_axis(axis_no)
        f = common.get_rename_function(replacements)
        if level is not None:
            level = ax._get_level_number(level)
        if not callable(replacements):
            if <MASK>:
                indexer = ax.get_level_values(level).get_indexer_for(replacements)
            else:
                indexer = ax.get_indexer_for(replacements)
            if errors == 'raise' and len(indexer[indexer == -1]):
                missing_labels = [label for (index, label) in enumerate(replacements) if indexer[index] == -1]
                raise KeyError(f'{missing_labels} not found in axis')
        new_index = ax._transform_index(f, level=level)
        result._set_axis_nocheck(new_index, axis=axis_no, inplace=True)
    if inplace:
        self._update_inplace(result)
        return None
    else:
        return result.__finalize__(self, method='rename')

def combine_paths(*args, **kws):
    """ Return a list of existing paths composed by all combinations of
        items from arguments.
    """
    r = []
    for a in args:
        if not a:
            continue
        if <MASK>:
            a = [a]
        r.append(a)
    args = r
    if not args:
        return []
    if len(args) == 1:
        result = reduce(lambda a, b: a + b, map(glob, args[0]), [])
    elif len(args) == 2:
        result = []
        for a0 in args[0]:
            for a1 in args[1]:
                result.extend(glob(os.path.join(a0, a1)))
    else:
        result = combine_paths(*combine_paths(args[0], args[1]) + args[2:])
    log.debug('(paths: %s)', ','.join(result))
    return result

def model_training_evaluation(backend, train_dataloader, eval_dataloader, model, optimizer, num_epochs, evaluation):
    model.to(device)
    model.train()
    loss_history = []
    if <MASK>:
        opt_training_iter_fn = training_iter_fn
    else:
        opt_training_iter_fn = torch._dynamo.optimize(backend)(training_iter_fn)
    for epoch in range(num_epochs):
        running_loss = 0.0
        for (i, batch) in enumerate(train_dataloader, 0):
            batch = {k: v.to(device) for (k, v) in batch.items()}
            loss = opt_training_iter_fn(batch, model, optimizer)
            running_loss += loss.item()
            if i % 100 == 99:
                loss_history.append(running_loss / 100)
                running_loss = 0.0
    if evaluation:
        metric = load_metric('accuracy')
        model.eval()
        if not backend:
            opt_model = model
        else:
            opt_model = torch._dynamo.optimize(backend)(model)
        for batch in eval_dataloader:
            batch = {k: v.to(device) for (k, v) in batch.items()}
            with torch.no_grad():
                outputs = opt_model(**batch)
            logits = outputs.logits
            predictions = torch.argmax(logits, dim=-1)
            metric.add_batch(predictions=predictions, references=batch['labels'])
        return (loss_history, metric.compute())
    else:
        return (loss_history, None)

@staticmethod
def process_runtime_tangent(x, meta: Union[PlainTensorMeta, SubclassCreationMeta]):
    if not isinstance(x, torch.Tensor):
        return (x, [x])
    if isinstance(x, FakeTensor):
        assert meta.memory_format
        x = coerce_to_expected_memory_format(x, meta.memory_format)
        return (x, [x])
    expected_type: Optional[type] = torch.Tensor
    expected_meta = None
    if isinstance(meta, SubclassCreationMeta):
        expected_type = meta.original_subclass_type
        expected_meta = meta.meta
    runtime_type = type(x)
    if isinstance(x, torch._subclasses.functional_tensor.FunctionalTensor):
        runtime_type = torch.Tensor
    runtime_meta = None
    runtime_subclass_keys: Sequence[str] = []
    if <MASK>:
        (runtime_subclass_keys, runtime_meta) = x.__tensor_flatten__()

    def maybe_coerce(x):
        same_type: bool = expected_type == runtime_type
        same_meta: bool = expected_meta == runtime_meta
        if same_type and same_meta:
            return x
        if not hasattr(x, '__coerce_same_metadata_as_tangent__'):
            return None
        if same_type:
            return x.__coerce_same_metadata_as_tangent__(expected_meta)
        return x.__coerce_same_metadata_as_tangent__(expected_meta, expected_type)
    orig_x = x
    x = maybe_coerce(x)
    if x is None:
        raise RuntimeError(f'\nDuring the backward, we encountered a tensor subclass where we guessed its\nmetadata incorrectly.\n\nExpected metadata: {str(expected_meta)}, expected type: {str(expected_type)}\n\nRuntime metadata: {str(runtime_meta)}, runtime type: {str(runtime_type)}\n\nshape: {str(orig_x.shape)}\nTo fix this, your tensor subclass must implement the dunder method __force_to_same_metadata__.\n')
    assert meta.memory_format
    x = coerce_to_expected_memory_format(x, meta.memory_format)
    if not is_traceable_wrapper_subclass(x):
        return (x, [x])
    assert isinstance(meta, SubclassCreationMeta)
    if orig_x is not x:
        runtime_subclass_keys = x.__tensor_flatten__()[0]
    assert len(meta.attrs) == len(runtime_subclass_keys)
    leaves = []
    for (i, (attr, attr_meta)) in enumerate(meta.attrs.items()):
        elem = getattr(x, attr)
        (new_elem, elem_leaves) = AOTDispatchAutograd.process_runtime_tangent(elem, attr_meta)
        if new_elem is not elem:
            setattr(x, attr, new_elem)
        leaves.extend(elem_leaves)
    return (x, leaves)

def _union(self, other, sort) -> MultiIndex:
    (other, result_names) = self._convert_can_do_setop(other)
    if other.has_duplicates:
        result = super(MultiIndex, self.rename(result_names))._union(other.rename(result_names), sort)
        if isinstance(result, MultiIndex):
            return result
        return MultiIndex.from_arrays(zip(*result, strict=True), sortorder=None, names=result_names)
    else:
        right_missing = other.difference(self, sort=False)
        if len(right_missing):
            result = self.append(right_missing)
        else:
            result = self._get_reconciled_name_object(other)
        if <MASK>:
            try:
                result = result.sort_values()
            except TypeError:
                if sort is True:
                    raise
                warnings.warn('The values in the array are unorderable. Pass `sort=False` to suppress this warning.', RuntimeWarning, stacklevel=find_stack_level())
        return result

def on_batch_end(self, batch, logs=None):
    logs = logs or {}
    loss = logs.get('loss')
    if <MASK>:
        loss = tf_utils.sync_to_numpy_or_python_type(loss)
        if np.isnan(loss) or np.isinf(loss):
            print('Batch %d: Invalid loss, terminating training' % batch)
            self.model.stop_training = True

