def forward(self, input: Tensor, reduce_range: bool=True) -> Tensor:
    if len(input.shape) != 3:
        raise ValueError('Input shape must be `(N, C, L)`!')
    if <MASK>:
        _reversed_padding_repeated_twice = _reverse_repeat_padding(self.padding[:1])
        input = F.pad(input, _reversed_padding_repeated_twice, mode=self.padding_mode)
    return ops.quantized.conv1d_dynamic(input, self._packed_params, reduce_range)

def _get_dispatch(self, key: DispatchKey) -> Union[DispatchKey, Callable[_P, _T]]:
    assert key not in self._dispatch_cache, f'{self} {key}'
    if key == DispatchKey.Python:
        if not isinstance(self, TorchBindOpOverload) and (not self.python_key_table):
            self._dispatch_cache[key] = key
            add_cached_op(self)
            return key

        def handler(*args: _P.args, **kwargs: _P.kwargs) -> _T:
            from torch.utils._python_dispatch import _get_current_dispatch_mode
            curr_mode = type(_get_current_dispatch_mode())
            assert curr_mode is not None, 'Illegal invocation of dispatch on DispatchKey.Python without a mode.'
            if curr_mode not in self.python_key_table:
                if isinstance(self, TorchBindOpOverload):
                    with torch.utils._python_dispatch._pop_mode_temporarily() as mode:
                        return torch._library.utils.handle_dispatch_mode(mode, self, *args, **kwargs)
                else:
                    return self._op_dk(key, *args, **kwargs)
            with torch.utils._python_dispatch._pop_mode_temporarily() as mode:
                return self.python_key_table[curr_mode](mode, *args, **kwargs)
        self._dispatch_cache[key] = handler
        add_cached_op(self)
        return handler
    functionality_key = torch._C._to_functionality_key(key)
    if functionality_key == DispatchKey.PreDispatch:
        curr_stack_len = _len_torch_dispatch_stack_pre_dispatch()
        if curr_stack_len > 0 and (not torch._C._dispatch_tls_is_dispatch_key_excluded(DispatchKey.Python)):

            def handler(*args: _P.args, **kwargs: _P.kwargs) -> _T:

                @contextlib.contextmanager
                def _temporarily_pop_modes_from_pre_dispatch():
                    top_mode = _pop_mode_from_pre_dispatch()
                    try:
                        yield top_mode
                    finally:
                        _set_mode_pre_dispatch(top_mode)
                with _temporarily_pop_modes_from_pre_dispatch() as curr_mode:
                    return torch._library.utils.handle_dispatch_mode(curr_mode, self, *args, **kwargs)
            return handler
    final_key = resolve_key(self, key)
    cache_result = key != DispatchKey.PreDispatch
    if key == DispatchKey.Functionalize:
        import torch._dispatch.python as pydispatch
        if pydispatch.CROSSREF_FUNCTIONALIZE:
            handler = pydispatch.make_crossref_functionalize(self, final_key)
            if <MASK>:
                self._dispatch_cache[key] = handler
                add_cached_op(self)
            return handler
    r = self.py_kernels.get(final_key, final_key)
    if cache_result:
        self._dispatch_cache[key] = r
        add_cached_op(self)
    return r

def skipOps(test_case_name, base_test_name, to_skip):
    all_opinfos = op_db
    for xfail in to_skip:
        (op_name, variant_name, device_type, dtypes, expected_failure) = xfail
        matching_opinfos = [o for o in all_opinfos if o.name == op_name and o.variant_test_name == variant_name]
        assert len(matching_opinfos) >= 1, f"Couldn't find OpInfo for {xfail}"
        for op in matching_opinfos:
            decorators = list(op.decorators)
            if <MASK>:
                decorator = DecorateInfo(unittest.expectedFailure, test_case_name, base_test_name, device_type=device_type, dtypes=dtypes)
                decorators.append(decorator)
            else:
                decorator = DecorateInfo(unittest.skip('Skipped!'), test_case_name, base_test_name, device_type=device_type, dtypes=dtypes)
                decorators.append(decorator)
            op.decorators = tuple(decorators)

    def wrapped(fn):
        return fn
    return wrapped

def generate_values(base, densesize):
    """Generates a tensor of shape densesize with values equal to

              base + i_1 * 10^0 + ... + i_d * 10^{d - 1}

            at indices i_1, ..., i_d (with 0 <= i_j < densesize[j] for any 1 <= j <=
            len(densesize))

            This mapping produces unique values as long as
            densesize[i] < 10 for all i in range(len(densesize)).
            """
    if not densesize:
        return base
    if <MASK>:
        return torch.stack([generate_values(b, densesize) for b in base])
    if base == 0:
        return torch.zeros(densesize, dtype=torch.int64)
    r = torch.arange(densesize[0], dtype=torch.int64)
    for (i, d) in enumerate(densesize[1:]):
        y = torch.arange(d, dtype=torch.int64) * 10 ** (i + 1)
        r = r[..., None] + y[None, ...]
    r.add_(base)
    return r

def __post_init__(self):
    default_timeout = 900
