        logger.info('Using default numa options = %r', self.numa_options)

def codegen_input_symbol_assignment(self, name: str, value: ir.TensorBox, bound_vars: OrderedSet[sympy.Symbol]):
    code = self.prefix

    @functools.cache
    def sizeof(name):
        code.writeline(f'{name}_size = {name}.size()')
        return f'{name}_size'

    @functools.cache
    def strideof(name):
        code.writeline(f'{name}_stride = {name}.stride()')
        return f'{name}_stride'
    if <MASK>:
        if not isinstance(value, sympy.Symbol) or value in bound_vars:
            return
        code.writeline(f'{value} = {name}')
        bound_vars.add(value)
    elif isinstance(value, ir.TensorBox):
        for (dim, size) in enumerate(value.get_size()):
            if isinstance(size, sympy.Symbol) and size not in bound_vars:
                code.writeline(f'{size} = {sizeof(name)}[{dim}]')
                bound_vars.add(size)
        for (dim, stride) in enumerate(value.get_stride()):
            if isinstance(stride, sympy.Symbol) and stride not in bound_vars:
                code.writeline(f'{stride} = {strideof(name)}[{dim}]')
                bound_vars.add(stride)
    elif isinstance(value, ir.TorchBindObject):
        return
    elif isinstance(value, ir.GeneratorState):
        return
    elif torch._inductor.config.graph_partition:
        pass
    else:
        raise AssertionError(f'Unknown value type: {type(value)}')

def _sparse_fit(self, X, random_state):
    """Compute percentiles for sparse matrices.

        Parameters
        ----------
        X : sparse matrix of shape (n_samples, n_features)
            The data used to scale along the features axis. The sparse matrix
            needs to be nonnegative. If a sparse matrix is provided,
            it will be converted into a sparse ``csc_matrix``.
        """
    (n_samples, n_features) = X.shape
    references = self.references_ * 100
    self.quantiles_ = []
    for feature_idx in range(n_features):
        column_nnz_data = X.data[X.indptr[feature_idx]:X.indptr[feature_idx + 1]]
        if self.subsample is not None and len(column_nnz_data) > self.subsample:
            column_subsample = self.subsample * len(column_nnz_data) // n_samples
            if <MASK>:
                column_data = np.zeros(shape=column_subsample, dtype=X.dtype)
            else:
                column_data = np.zeros(shape=self.subsample, dtype=X.dtype)
            column_data[:column_subsample] = random_state.choice(column_nnz_data, size=column_subsample, replace=False)
        else:
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=len(column_nnz_data), dtype=X.dtype)
            else:
                column_data = np.zeros(shape=n_samples, dtype=X.dtype)
            column_data[:len(column_nnz_data)] = column_nnz_data
        if not column_data.size:
            self.quantiles_.append([0] * len(references))
        else:
            self.quantiles_.append(np.nanpercentile(column_data, references))
    self.quantiles_ = np.transpose(self.quantiles_)
    self.quantiles_ = np.maximum.accumulate(self.quantiles_)

def _collect_fake_inputs(inputs):
    from torch._subclasses.fake_tensor import FakeTensor
    inputs_fake: list[Union[FakeTensor, torch.Tensor, int]] = []
    for inp in inputs:
        if isinstance(inp, (torch.fx.proxy.Proxy, torch.fx.node.Node)):
            inp = inp.node if isinstance(inp, torch.fx.proxy.Proxy) else inp
            if <MASK>:
                val = inp.meta['example_value']
                if isinstance(val, torch.Tensor):
                    if torch._C._functorch.is_batchedtensor(val) or torch._C._functorch.is_functionaltensor(val):
                        while torch._C._functorch.is_batchedtensor(val) or torch._C._functorch.is_functionaltensor(val):
                            val = torch._C._functorch.get_unwrapped(val)
                        assert isinstance(val, FakeTensor)
                        inputs_fake.append(val)
                    else:
                        assert isinstance(val, FakeTensor)
                        inputs_fake.append(val)
                else:
                    assert not isinstance(val, torch.Tensor)
                    inputs_fake.append(val)
        else:
            assert isinstance(inp, int)
            inputs_fake.append(inp)
    return inputs_fake

def _is_match(modules, node, pattern, max_uses=sys.maxsize):
    """Matches a node in fx against a pattern"""
    if isinstance(pattern, tuple):
        (self_match, *arg_matches) = pattern
        if self_match is getattr:
            assert len(pattern) == 2, 'Expecting getattr pattern to have two elements'
            arg_matches = []
    else:
        self_match = pattern
        arg_matches = []
    if isinstance(self_match, type) and issubclass(self_match, MatchAllNode):
        return True
    if node == pattern:
        return True
    if not isinstance(node, Node) or len(node.users) > max_uses:
        return False
    if isinstance(self_match, type) and issubclass(self_match, torch.nn.Module):
        if node.op != 'call_module':
            return False
        if <MASK>:
            return False
    elif callable(self_match):
        if node.op != 'call_function' or node.target is not self_match:
            return False
        elif node.target is getattr:
            if node.args[1] != pattern[1]:
                return False
    elif isinstance(self_match, str):
        if node.op != 'call_method' or node.target != self_match:
            return False
    elif node.target != self_match:
        return False
    if not arg_matches:
        return True
    if len(arg_matches) != len(node.args):
        return False
    return all((_is_match(modules, node, arg_match, max_uses=1) for (node, arg_match) in zip(node.args, arg_matches)))

def can_safe_cast_to(*, cast_to: torch.dtype, cast_from: torch.dtype) -> bool:
    for fn in (is_complex_dtype, is_float_dtype, is_integer_dtype, is_boolean_dtype):
        if fn(cast_to):
            return True
        if <MASK>:
            return False
    raise ValueError(f'Received unknown dtypes {cast_to}, {cast_from}!')

def _write_custom_summaries(self, step, logs=None):
    """Writes metrics out as custom scalar summaries.

    Args:
        step: the global step to use for TensorBoard.
        logs: dict. Keys are scalar summary names, values are
            NumPy scalars.

    """
    logs = logs or {}
    if <MASK>:
        with self.writer.as_default(), summary_ops_v2.record_if(True):
            for (name, value) in logs.items():
                if isinstance(value, np.ndarray):
                    value = value.item()
