def _interpolate_scipy_wrapper(x: np.ndarray, y: np.ndarray, new_x: np.ndarray, method: str, fill_value=None, bounds_error: bool=False, order=None, **kwargs):
    """
    Passed off to scipy.interpolate.interp1d. method is scipy's kind.
    Returns an array interpolated at new_x.  Add any new methods to
    the list in _clean_interp_method.
    """
    extra = f'{method} interpolation requires SciPy.'
    import_optional_dependency('scipy', extra=extra)
    from scipy import interpolate
    new_x = np.asarray(new_x)
    alt_methods: dict[str, Callable[..., np.ndarray]] = {'barycentric': interpolate.barycentric_interpolate, 'krogh': interpolate.krogh_interpolate, 'from_derivatives': _from_derivatives, 'piecewise_polynomial': _from_derivatives, 'cubicspline': _cubicspline_interpolate, 'akima': _akima_interpolate, 'pchip': interpolate.pchip_interpolate}
    interp1d_methods = ['nearest', 'zero', 'slinear', 'quadratic', 'cubic', 'polynomial']
    terp: Callable[..., np.ndarray] | None
    if <MASK>:
        if method == 'polynomial':
            kind = order
        else:
            kind = method
        terp = interpolate.interp1d(x, y, kind=kind, fill_value=fill_value, bounds_error=bounds_error)
        new_y = terp(new_x)
    elif method == 'spline':
        if isna(order) or order <= 0:
            raise ValueError(f'order needs to be specified and greater than 0; got order: {order}')
        terp = interpolate.UnivariateSpline(x, y, k=order, **kwargs)
        new_y = terp(new_x)
    else:
        if not x.flags.writeable:
            x = x.copy()
        if not y.flags.writeable:
            y = y.copy()
        if not new_x.flags.writeable:
            new_x = new_x.copy()
        terp = alt_methods.get(method, None)
        if terp is None:
            raise ValueError(f'Can not interpolate with method={method}.')
        kwargs.pop('downcast', None)
        new_y = terp(x, y, new_x, **kwargs)
    return new_y

def split_having_qualify(self, negated=False, must_group_by=False):
    """
        Return three possibly None nodes: one for those parts of self that
        should be included in the WHERE clause, one for those parts of self
        that must be included in the HAVING clause, and one for those parts
        that refer to window functions.
        """
    if not self.contains_aggregate and (not self.contains_over_clause):
        return (self, None, None)
    in_negated = negated ^ self.negated
    must_remain_connected = in_negated and self.connector == AND or (not in_negated and self.connector == OR) or self.connector == XOR
    if must_remain_connected and self.contains_aggregate and (not self.contains_over_clause):
        return (None, self, None)
    where_parts = []
    having_parts = []
    qualify_parts = []
    for c in self.children:
        if <MASK>:
            (where_part, having_part, qualify_part) = c.split_having_qualify(in_negated, must_group_by)
            if where_part is not None:
                where_parts.append(where_part)
            if having_part is not None:
                having_parts.append(having_part)
            if qualify_part is not None:
                qualify_parts.append(qualify_part)
        elif c.contains_over_clause:
            qualify_parts.append(c)
        elif c.contains_aggregate:
            having_parts.append(c)
        else:
            where_parts.append(c)
    if must_remain_connected and qualify_parts:
        if not where_parts or (where_parts and (not must_group_by)):
            return (None, None, self)
        elif where_parts:
            raise NotImplementedError('Heterogeneous disjunctive predicates against window functions are not implemented when performing conditional aggregation.')
    where_node = self.create(where_parts, self.connector, self.negated) if where_parts else None
    having_node = self.create(having_parts, self.connector, self.negated) if having_parts else None
    qualify_node = self.create(qualify_parts, self.connector, self.negated) if qualify_parts else None
    return (where_node, having_node, qualify_node)

def is_variable_initialized(ref, name=None):
    """Checks whether a tensor has been initialized.

  Outputs boolean scalar indicating whether the tensor has been initialized.

  Args:
    ref: A mutable `Tensor`.
      Should be from a `Variable` node. May be uninitialized.
    name: A name for the operation (optional).

  Returns:
    A `Tensor` of type `bool`.
  """
    if <MASK>:
        return gen_state_ops.is_variable_initialized(ref=ref, name=name)
    return ref.is_initialized(name=name)

def reduce_all(self):
    masked_fn = _get_masked_fn(fn)
    data = self.get_data()
    mask = self.get_mask().values() if self.is_sparse else self.get_mask()
    if fn == 'all':
        result_data = masked_fn(data, mask=mask)
    elif <MASK>:
        sparse_idx = masked_fn(data.values(), mask=mask).to(dtype=torch.int)
        indices = data.to_sparse_coo().indices() if not self.is_sparse_coo() else data.indices()
        idx = indices.unbind(1)[sparse_idx]
        stride = data.size().numel() / torch.tensor(data.size(), device=data.device).cumprod(0)
        result_data = torch.sum(idx * stride)
    elif self.is_sparse:
        result_data = masked_fn(masked_tensor(data.values(), mask))
    else:
        result_data = masked_fn(self, mask=mask)
    return as_masked_tensor(result_data, torch.any(mask))

def step_meta_parameter(name, value, direction, meta, m=m, n=n, k=k, bm=bm, bk=bk):
    is_log = name in {'SPLIT_N', 'TILE_M', 'TILE_N', 'num_warps'}
    min_value = dict(SPLIT_N=1, TILE_M=16, TILE_N=16, num_warps=1, num_stages=1, GROUP_SIZE=1)[name]
    max_value = dict(SPLIT_N=n // meta['TILE_N'], TILE_M=bm, TILE_N=n // meta['SPLIT_N']).get(name)
    value_step = dict(SPLIT_N=2, TILE_M=2, TILE_N=2, num_warps=2, num_stages=1, GROUP_SIZE=1)[name]
    if is_log:
        next_value = value * value_step ** direction if direction > 0 else value // value_step ** abs(direction)
    else:
        next_value = value + value_step * direction
    if min_value is not None:
        next_value = max(next_value, min_value)
    if max_value is not None:
        next_value = min(next_value, max_value)
    if <MASK>:
        return value
    if (dtype, name, next_value, m, n, k, bm, bk) in {(torch.float32, 'num_warps', 32, 256, 256, 256, 16, 16), (torch.float32, 'num_warps', 16, 256, 256, 256, 32, 32), (torch.float32, 'num_warps', 16, 256, 256, 256, 64, 64), (torch.float32, 'num_warps', 16, 256, 256, 256, 128, 128), (torch.float32, 'num_warps', 16, 512, 512, 256, 128, 128)} and re.match('NVIDIA A100[^\\d]', device_name) is not None:
        return value
    return next_value

def migration_progress_callback(self, action, migration=None, fake=False):
    if self.verbosity >= 1:
        compute_time = self.verbosity > 1
        if action == 'apply_start':
            if compute_time:
                self.start = time.monotonic()
            self.stdout.write('  Applying %s...' % migration, ending='')
            self.stdout.flush()
        elif action == 'apply_success':
            elapsed = ' (%.3fs)' % (time.monotonic() - self.start) if compute_time else ''
            if fake:
                self.stdout.write(self.style.SUCCESS(' FAKED' + elapsed))
            else:
                self.stdout.write(self.style.SUCCESS(' OK' + elapsed))
        elif action == 'unapply_start':
            if compute_time:
                self.start = time.monotonic()
            self.stdout.write('  Unapplying %s...' % migration, ending='')
            self.stdout.flush()
        elif action == 'unapply_success':
            elapsed = ' (%.3fs)' % (time.monotonic() - self.start) if compute_time else ''
            if fake:
                self.stdout.write(self.style.SUCCESS(' FAKED' + elapsed))
            else:
                self.stdout.write(self.style.SUCCESS(' OK' + elapsed))
        elif <MASK>:
            if compute_time:
                self.start = time.monotonic()
            self.stdout.write('  Rendering model states...', ending='')
            self.stdout.flush()
        elif action == 'render_success':
            elapsed = ' (%.3fs)' % (time.monotonic() - self.start) if compute_time else ''
            self.stdout.write(self.style.SUCCESS(' DONE' + elapsed))

def extract_autotune_inputs(self, example_inputs: list[Union[int, float, torch.Tensor]]) -> None:
    import copy
    cloned_gm = copy.deepcopy(self.orig_gm)
    example_inputs = copy.deepcopy(example_inputs)
    triton_nodes = []
    for node in cloned_gm.graph.nodes:
        if <MASK>:
            triton_nodes.append(node)
    grid_inputs: list[torch.fx.Node] = []
    visited_grids: dict[torch.fx.Node, int] = {}
    triton_inputs: dict[str, Any] = {}
    kwargs_inputs: list[torch.fx.Node] = []
    visited_kwargs: dict[Any, int] = {}
    for node in triton_nodes:
        for grid in node.kwargs['grid']:
            for val in grid:
                if val in visited_grids:
                    continue
                if isinstance(val, torch.fx.Node):
                    visited_grids[val] = len(grid_inputs)
                    grid_inputs.append(val)
        kwargs = node.kwargs['kwargs']
        mutated = torch._higher_order_ops.triton_kernel_wrap.get_mutated_tensors(node.kwargs['kernel_idx'], node.kwargs['constant_args_idx'], {k: v.meta['val'] if isinstance(v, torch.fx.Node) else v for (k, v) in kwargs.items()}, node.kwargs['tma_descriptor_metadata'])
        new_kwargs: dict[str, int] = {}
        with cloned_gm.graph.inserting_before(node):
            for (k, v) in kwargs.items():
                if k in mutated:
                    new_node = cloned_gm.graph.call_function(torch.clone, args=(v,))
                    new_kwargs[k] = len(kwargs_inputs)
                    kwargs_inputs.append(new_node)
                    continue
                if v in visited_kwargs:
                    new_kwargs[k] = visited_kwargs[v]
                    continue
                visited_kwargs[v] = len(kwargs_inputs)
                kwargs_inputs.append(v)
                new_kwargs[k] = visited_kwargs[v]
        triton_inputs[node.name] = new_kwargs
    new_outputs = kwargs_inputs + grid_inputs
    for node in cloned_gm.graph.nodes:
        if node.op == 'output':
            node.args = (tuple(new_outputs),)
            break
    cloned_gm.recompile()
    runner = torch.fx.Interpreter(cloned_gm)
    returned_outputs = runner.run(example_inputs)
    if len(grid_inputs) > 0:
        grid_outputs = returned_outputs[len(kwargs_inputs):]
        self.autotuning_grids = {}
        for node in triton_nodes:
            dynamic_grid = False
            new_grids: list[tuple[Any]] = []
            for grid in node.kwargs['grid']:
                new_grid = []
                for val in grid:
                    if not isinstance(val, torch.fx.Node):
                        new_grid.append(val)
                        continue
                    dynamic_grid = True
                    new_grid.append(grid_outputs[visited_grids[val]])
                new_grids.append(tuple(new_grid))
            if dynamic_grid:
                self.autotuning_grids[node.name] = new_grids
    self.autotuning_inputs = returned_outputs[:len(kwargs_inputs)]
    self.autotuning_mapping = triton_inputs

def const_repr(x: Any, *, local: Any) -> str:
    from .trace_rules import is_builtin_callable
    if isinstance(x, (list, tuple)):
        elems_repr = ','.join((const_repr(s, local=local) for s in x))
        if <MASK>:
            return f'[{elems_repr}]'
        else:
            assert isinstance(x, tuple)
            if len(x) == 1:
                return f'({elems_repr},)'
            else:
                return f'({elems_repr})'
    elif isinstance(x, enum.Enum):
        return enum_repr(x, local=local).replace("'", '')
    elif is_builtin_callable(x):
        return x.__name__
    elif isinstance(x, type):

        def fullname(o: Any) -> str:
            klass = o.__class__
            module = klass.__module__
            if module == 'builtins':
                return klass.__qualname__
            return module + '.' + klass.__qualname__
        return fullname(x)
    else:
        return f'{x!r}'

@register.filter(is_safe=False)
def yesno(value, arg=None):
    """
    Given a string mapping values for true, false, and (optionally) None,
    return one of those strings according to the value:

    ==========  ======================  ==================================
    Value       Argument                Outputs
    ==========  ======================  ==================================
    ``True``    ``"yeah,no,maybe"``     ``yeah``
    ``False``   ``"yeah,no,maybe"``     ``no``
    ``None``    ``"yeah,no,maybe"``     ``maybe``
    ``None``    ``"yeah,no"``           ``"no"`` (converts None to False
                                        if no mapping for None is given.
    ==========  ======================  ==================================
    """
    if arg is None:
        arg = gettext('yes,no,maybe')
    bits = arg.split(',')
    if len(bits) < 2:
        return value
    try:
        (yes, no, maybe) = bits
    except ValueError:
        (yes, no, maybe) = (bits[0], bits[1], bits[1])
    if <MASK>:
        return maybe
    if value:
        return yes
    return no

def _max_pool_with_offsets(x, kernel_size, stride, padding, dilation, ceil_mode, *, n_dim):
    x.realize_hint()
    batch = x.shape[:-n_dim]
    dhw = x.shape[-n_dim:]
    (dhw_out, ceil_mode) = zip(*[pooling_size(dhw[d], d, kernel_size, stride, padding, ceil_mode, dilation=dilation) for d in range(n_dim)])
    dtype = x.dtype
    min_value = False if dtype is torch.bool else float('-inf') if dtype.is_floating_point else torch.iinfo(dtype).min
    new_size = list(batch) + list(dhw_out)
    if any(padding) or any(ceil_mode) or any((d > 1 for d in dilation)):
        x_loader = constant_boundary_condition(x, min_value, dim=n_dim)
    else:
        x_loader = x.make_loader()

    def fn_inner(idx, reduction_idx):
        prefix = idx[:-n_dim]
        bh = idx[-n_dim:]
        ih = [bh[i] * stride[i] + reduction_idx[i] * dilation[i] - padding[i] for i in range(n_dim)]
        return x_loader([*prefix, *ih])
    result = Reduction.create(reduction_type='max', input_node=x, device=x.get_device(), dst_dtype=dtype, src_dtype=dtype, inner_fn=fn_inner, ranges=new_size, reduction_ranges=kernel_size)
    offsets = Reduction.create(reduction_type='argmax', input_node=x, device=x.get_device(), dst_dtype=torch.int64, src_dtype=dtype, inner_fn=fn_inner, ranges=new_size, reduction_ranges=kernel_size)
    if isinstance(result.data.data, Reduction):
        result.realize()
    if <MASK>:
        offsets.realize()
    return (result, offsets)

def deconstruct(self):
    (name, path, args, kwargs) = super().deconstruct()
    if self.db_table is not None:
        kwargs['db_table'] = self.db_table
    if self.remote_field.db_constraint is not True:
        kwargs['db_constraint'] = self.remote_field.db_constraint
    if isinstance(self.remote_field.model, str):
        if '.' in self.remote_field.model:
            (app_label, model_name) = self.remote_field.model.split('.')
            kwargs['to'] = '%s.%s' % (app_label, model_name.lower())
        else:
            kwargs['to'] = self.remote_field.model.lower()
    else:
        kwargs['to'] = self.remote_field.model._meta.label_lower
    if getattr(self.remote_field, 'through', None) is not None:
        if isinstance(self.remote_field.through, str):
            kwargs['through'] = self.remote_field.through
        elif not self.remote_field.through._meta.auto_created:
            kwargs['through'] = self.remote_field.through._meta.label
    if (through_fields := getattr(self.remote_field, 'through_fields', None)):
        kwargs['through_fields'] = through_fields
    swappable_setting = self.swappable_setting
    if swappable_setting is not None:
        if <MASK>:
            if kwargs['to'].setting_name != swappable_setting:
                raise ValueError('Cannot deconstruct a ManyToManyField pointing to a model that is swapped in place of more than one model (%s and %s)' % (kwargs['to'].setting_name, swappable_setting))
        kwargs['to'] = SettingsReference(kwargs['to'], swappable_setting)
    return (name, path, args, kwargs)

def _check_p2p_op_list(p2p_op_list) -> None:
    """
    Check that the ``p2p_op_list`` is a list of P2POp instances.

    Also, check that all ops use the same group.
    """
    if not isinstance(p2p_op_list, list) or not all((isinstance(p2p_op, P2POp) for p2p_op in p2p_op_list)):
        raise ValueError('Invalid ``p2p_op_list``. Each op is expected to to be of type ``torch.distributed.P2POp``.')
    group = p2p_op_list[0].group
    if <MASK>:
        raise ValueError('All ops need to use the same group.')

def sample_inputs_logspace(op, device, dtype, requires_grad, **kwargs):
    ends = (-3, 0, 1.2, 2, 4)
    starts = (-2.0, 0, 1, 2, 4.3)
    nsteps = (0, 1, 2, 4)
    bases = (2.0, 1.1) if dtype in (torch.int8, torch.uint8) else (None, 2.0, 3.0, 1.1, 5.0)
    for (start, end, nstep, base) in product(starts, ends, nsteps, bases):
        if dtype == torch.uint8 and end < 0 or start < 0:
            continue
        if nstep == 1 and isinstance(start, float) and (not (dtype.is_complex or dtype.is_floating_point)):
            continue
        if <MASK>:
            yield SampleInput(start, args=(end, nstep), kwargs={'dtype': dtype, 'device': device})
        else:
            yield SampleInput(start, args=(end, nstep, base), kwargs={'dtype': dtype, 'device': device})
    yield SampleInput(1, args=(3, 1, 2.0))

@register_lowering(aten.cummin, type_promotion_kind=None)
def cummin(x, axis=None):
    if len(x.get_size()) == 0:
        assert axis in [0, -1]
        return (clone(x), empty_like(x, dtype=torch.int64))
    dtype = x.get_dtype()
    combine_fn = ir.get_reduction_combine_fn('argmin', dtype=dtype, arg_break_ties_left=False)
    kwargs = _make_scan_inner(x, axis=axis, dtype=dtype)
    kwargs['dtypes'] = (dtype, torch.int64)
    kwargs['inner_fns'] = (x.make_loader(), lambda idx: ops.index_expr(idx[axis], torch.int64))
    (values, indices) = ir.Scan.create(**kwargs, combine_fn=combine_fn)
    if <MASK>:
        return fallback_cummin(x, dim=axis)
    return (values, indices)

def can_fuse(self, node1: BaseSchedulerNode, node2: BaseSchedulerNode, can_reorder: bool=False) -> bool:
    """
        Determine if it is possible to combine node1 and node2 into a
        single fused node.
        """
    if node1 is node2:
        return False
    why = WhyNoFuse(node1, node2)
    if node1.is_template() and self.get_backend(node1.get_device()).can_fuse_multi_outputs_template(node1, node2):
        return True
    if isinstance(node1, GroupedSchedulerNode) or isinstance(node2, GroupedSchedulerNode):
        why('grouped node must not be fused with other nodes')
        return False
    if isinstance(node1, (ExternKernelSchedulerNode, NopKernelSchedulerNode)) and (not node1.is_template()):
        why('node1 is extern or nop')
        return False
    if isinstance(node2, (ExternKernelSchedulerNode, NopKernelSchedulerNode)) and (not node2.is_template()):
        why('node2 is extern or nop')
        return False
    if node2.get_operation_names() & node1.ancestors:
        why('node1 must go before node2')
        return False
    if node2.is_template():
        if not config.prologue_fusion:
            why('prologue fusion turned off')
            return False
        if node1.is_reduction() or node1.is_template():
            why('prologue fusion only supported for pointwise nodes')
            return False
        template = node2.get_template_node_or_throw()
        if not isinstance(template, ir.TritonTemplateBuffer):
            why('prologue fusion only supported for TritonTemplates')
            return False
        allowed_prologue_inps = template.get_allowed_prologue_inps()
        unsupported_prologue_args = OrderedSet((inp.get_name() for inp in template.inputs)) - allowed_prologue_inps
        if node1.get_buffer_names() & unsupported_prologue_args:
            why('prologue fusion not implemented for kernel for these inputs')
            return False
        if node1.has_aliasing_or_mutation() or node1.has_aliasing_or_mutation():
            why('template prologue can only fuse functional pointwise nodes')
            return False
        prologue_nodes = node1.get_nodes()
        for node in prologue_nodes[:-1]:
            node_outs = node.get_outputs()
            for out in node_outs:
                if not all((user.node in prologue_nodes for user in out.users)):
                    why('template prologue can only fuse nodes with a single use')
                    return False
        template_snodes = [node2] if not isinstance(node2, FusedSchedulerNode) else [n for n in node2.snodes if n.is_template()]
        assert len(template_snodes) == 1
        template_snode = template_snodes[0]
        if not (len(prologue_nodes[-1].outputs) == 1 and len(prologue_nodes[-1].outputs[0].users) == 1 and (prologue_nodes[-1].outputs[0].users[0].node is template_snode)):
            why('template prologue can only fuse nodes with a single use into template')
            return False
        if <MASK>:
            return False
    if node1.is_template() and (node2.has_aliasing_or_mutation() or node2.is_reduction() or (not config.epilogue_fusion)):
        why('template epilogue not satisfied')
        return False
    if node1.get_buffer_names() & V.graph.no_fuse_buffer_names or node2.get_buffer_names() & V.graph.no_fuse_buffer_names:
        why('fusion for buffer explicit disabled')
        return False
    device = node1.get_device()
    device2 = node2.get_device()
    if device != device2:
        why('device mismatch (%s vs %s)', device, device2)
        return False
    del device2
    shared_data_score = self.score_fusion_memory(node1, node2)
    if can_reorder and shared_data_score < config.score_fusion_memory_threshold and config.loop_ordering_after_fusion:
        new_shared_data_score = self.shared_data_after_reordering_loop(node1, node2)
        if new_shared_data_score >= 0:
            shared_data_score = new_shared_data_score
    if config.expand_dimension_for_pointwise_nodes and (expand_analysis := self.get_expand_dim_for_pointwise_nodes(node1, node2)):
        (expand_dim, smaller_node, expand_size) = expand_analysis
        smaller_node.expand_dimension_for_pointwise_node(expand_dim, expand_size)
        shared_data_score = self.score_fusion_memory(node1, node2)
    if loop_ordering_log.isEnabledFor(logging.DEBUG):
        loop_ordering_log.debug('%s and %s has %s shared data', node1.get_name(), node2.get_name(), shared_data_score)
    if not V.choices.can_fuse(self, node1, node2, shared_data_score):
        return False
    if node1.get_operation_names() & node2.ancestors:
        return self.can_fuse_vertical(node1, node2) and V.choices.can_fuse_vertical(self, node1, node2, shared_data_score) and self.get_backend(device).can_fuse_vertical(node1, node2)
    else:
        return V.choices.can_fuse_horizontal(self, node1, node2, shared_data_score) and self.get_backend(device).can_fuse_horizontal(node1, node2)

def get_date_list(self, queryset, date_type=None, ordering='ASC'):
    """
        Get a date list by calling `queryset.dates/datetimes()`, checking
        along the way for empty lists that aren't allowed.
        """
    date_field = self.get_date_field()
    allow_empty = self.get_allow_empty()
    if date_type is None:
        date_type = self.get_date_list_period()
    if self.uses_datetime_field:
        date_list = queryset.datetimes(date_field, date_type, ordering)
    else:
        date_list = queryset.dates(date_field, date_type, ordering)
    if <MASK>:
        raise Http404(_('No %(verbose_name_plural)s available') % {'verbose_name_plural': queryset.model._meta.verbose_name_plural})
    return date_list

def train_fn(self, unused_sess):
    self.num_calls += 1
    if <MASK>:
        self.retries_left -= 1
    if self.retries_left > 0:
        raise errors_impl.AbortedError(None, None, 'Aborted here')
    else:
        raise RuntimeError('Failed Again')

def get_dep_size_hint(self, dep: Dep) -> int:
    """
        Get the size hint for a dependency with caching to avoid expensive recomputation.
        """
    if dep not in self.dep_size_hint_cache:
        res = 0
        try:
            if <MASK>:
                res = dep.numbytes_hint()
        except KeyError:
            pass
        self.dep_size_hint_cache[dep] = res
    return self.dep_size_hint_cache[dep]

def cluster_spec(self):
    """Returns a ClusterSpec based on the SageMaker environment variables.

    Returns:
      A ClusterSpec with information from the SageMaker environment variables.
    """
    tf_config = _load_tf_config(self._port)
    if <MASK>:
        return ClusterSpec({})
    return ClusterSpec(tf_config['cluster'])

def _init_from_checkpoint(ckpt_dir_or_file, assignment_map):
    """See `init_from_checkpoint` for documentation."""
    ckpt_file = _get_checkpoint_filename(ckpt_dir_or_file)
    reader = load_checkpoint(ckpt_dir_or_file)
    variable_map = reader.get_variable_to_shape_map()
    if isinstance(assignment_map, abc.Mapping):
        assignment_map = assignment_map.items()
    sort_key = lambda pair: pair[0]
    for (tensor_name_in_ckpt, current_var_or_name) in sorted(assignment_map, key=sort_key):
        var = None
        if _is_variable(current_var_or_name) or (isinstance(current_var_or_name, list) and all((_is_variable(v) for v in current_var_or_name))):
            var = current_var_or_name
        else:
            store_vars = vs._get_default_variable_store()._vars
            var = store_vars.get(current_var_or_name, None)
            if var is None:
                var = _collect_partitioned_variable(current_var_or_name, store_vars)
        if var is not None:
            if tensor_name_in_ckpt not in variable_map:
                raise ValueError('Tensor %s is not found in %s checkpoint %s' % (tensor_name_in_ckpt, ckpt_dir_or_file, variable_map))
            if _is_variable(var):
                if not var.get_shape().is_compatible_with(variable_map[tensor_name_in_ckpt]):
                    raise ValueError("Shape of variable %s (%s) doesn't match with shape of tensor %s (%s) from checkpoint reader." % (var.name, str(var.get_shape()), tensor_name_in_ckpt, str(variable_map[tensor_name_in_ckpt])))
                var_name = var.name
            else:
                var_name = ','.join((v.name for v in var))
            _set_variable_or_list_initializer(var, ckpt_file, tensor_name_in_ckpt)
            logging.debug('Initialize variable %s from checkpoint %s with %s', var_name, ckpt_dir_or_file, tensor_name_in_ckpt)
        else:
            scopes = ''
            if '/' in current_var_or_name:
                scopes = current_var_or_name[:current_var_or_name.rindex('/')]
            if not tensor_name_in_ckpt.endswith('/'):
                raise ValueError("Assignment map with scope only name {} should map to scope only {}. Should be 'scope/': 'other_scope/'.".format(scopes, tensor_name_in_ckpt))
            scope_variables = set()
            for var_name in store_vars:
                if not scopes or var_name.startswith(scopes + '/'):
                    if '/part_' in var_name:
                        var_name = var_name[:var_name.index('/part_')]
                    scope_variables.add(var_name)
            for var_name in sorted(scope_variables):
                full_tensor_name = var_name[len(scopes):]
                if current_var_or_name != '/':
                    full_tensor_name = full_tensor_name[1:]
                if tensor_name_in_ckpt != '/':
                    full_tensor_name = tensor_name_in_ckpt + full_tensor_name
                if <MASK>:
                    full_tensor_name = full_tensor_name[:-1]
                if full_tensor_name not in variable_map:
                    raise ValueError('Tensor %s (%s in %s) is not found in %s checkpoint' % (full_tensor_name, var_name[len(scopes) + 1:], tensor_name_in_ckpt, ckpt_dir_or_file))
                var = store_vars.get(var_name, None)
                if var is None:
                    var = _collect_partitioned_variable(var_name, store_vars)
                _set_variable_or_list_initializer(var, ckpt_file, full_tensor_name)
                logging.debug('Initialize variable %s from checkpoint %s with %s', var_name, ckpt_dir_or_file, full_tensor_name)

@classmethod
def get_base_missing_value(cls, dtype: np.dtype) -> float:
    if dtype.type is np.int8:
        value = cls.BASE_MISSING_VALUES['int8']
    elif dtype.type is np.int16:
        value = cls.BASE_MISSING_VALUES['int16']
    elif <MASK>:
        value = cls.BASE_MISSING_VALUES['int32']
    elif dtype.type is np.float32:
        value = cls.BASE_MISSING_VALUES['float32']
    elif dtype.type is np.float64:
        value = cls.BASE_MISSING_VALUES['float64']
    else:
        raise ValueError('Unsupported dtype')
    return value

def _ge(lhs: Any, rhs: Any) -> bool:
    if isinstance(rhs, NestedIntNode) and isinstance(lhs, NestedIntNode):
        if lhs.t_id == rhs.t_id:
            return lhs.coeff >= rhs.coeff
        raise ValueError('ge: relation is indeterminate')
    elif isinstance(lhs, NestedIntNode):
        if rhs.is_constant() and rhs.constant_int() <= 2:
            return True
        raise ValueError('ge: relation is indeterminate')
    elif isinstance(rhs, NestedIntNode):
        if <MASK>:
            return False
        raise ValueError('ge: relation is indeterminate')
    else:
        raise ValueError('inputs unsupported')

def collect(self, objs, source=None, nullable=False, collect_related=True, source_attr=None, reverse_dependency=False, keep_parents=False, fail_on_restricted=True):
    """
        Add 'objs' to the collection of objects to be deleted as well as all
        parent instances. 'objs' must be a homogeneous iterable collection of
        model instances (e.g. a QuerySet). If 'collect_related' is True,
        related objects will be handled by their respective on_delete handler.

        If the call is the result of a cascade, 'source' should be the model
        that caused it and 'nullable' should be set to True, if the relation
        can be null.

        If 'reverse_dependency' is True, 'source' will be deleted before the
        current model, rather than after. (Needed for cascading to parent
        models, the one case in which the cascade follows the forwards
        direction of an FK rather than the reverse direction.)

        If 'keep_parents' is True, data of parent model's will be not deleted.

        If 'fail_on_restricted' is False, error won't be raised even if it's
        prohibited to delete such objects due to RESTRICT, that defers
        restricted object checking in recursive calls where the top-level call
        may need to collect more objects to determine whether restricted ones
        can be deleted.
        """
    if self.can_fast_delete(objs):
        self.fast_deletes.append(objs)
        return
    new_objs = self.add(objs, source, nullable, reverse_dependency=reverse_dependency)
    if <MASK>:
        return
    model = new_objs[0].__class__
    if not keep_parents:
        concrete_model = model._meta.concrete_model
        for ptr in concrete_model._meta.parents.values():
            if ptr:
                parent_objs = [getattr(obj, ptr.name) for obj in new_objs]
                self.collect(parent_objs, source=model, source_attr=ptr.remote_field.related_name, collect_related=False, reverse_dependency=True, fail_on_restricted=False)
    if not collect_related:
        return
    model_fast_deletes = defaultdict(list)
    protected_objects = defaultdict(list)
    for related in get_candidate_relations_to_delete(model._meta):
        if keep_parents and related.model._meta.concrete_model in model._meta.all_parents:
            continue
        field = related.field
        on_delete = field.remote_field.on_delete
        if on_delete in SKIP_COLLECTION:
            if self.force_collection and (forced_on_delete := getattr(on_delete, 'forced_collector', None)):
                on_delete = forced_on_delete
            else:
                continue
        related_model = related.related_model
        if self.can_fast_delete(related_model, from_field=field):
            model_fast_deletes[related_model].append(field)
            continue
        batches = self.get_del_batches(new_objs, [field])
        for batch in batches:
            sub_objs = self.related_objects(related_model, [field], batch)
            if not (sub_objs.query.select_related or self._has_signal_listeners(related_model)):
                referenced_fields = set(chain.from_iterable(((rf.attname for rf in rel.field.foreign_related_fields) for rel in get_candidate_relations_to_delete(related_model._meta))))
                sub_objs = sub_objs.only(*tuple(referenced_fields))
            if getattr(on_delete, 'lazy_sub_objs', False) or sub_objs:
                try:
                    on_delete(self, field, sub_objs, self.using)
                except ProtectedError as error:
                    key = "'%s.%s'" % (field.model.__name__, field.name)
                    protected_objects[key] += error.protected_objects
    if protected_objects:
        raise ProtectedError('Cannot delete some instances of model %r because they are referenced through protected foreign keys: %s.' % (model.__name__, ', '.join(protected_objects)), set(chain.from_iterable(protected_objects.values())))
    for (related_model, related_fields) in model_fast_deletes.items():
        batches = self.get_del_batches(new_objs, related_fields)
        for batch in batches:
            sub_objs = self.related_objects(related_model, related_fields, batch)
            self.fast_deletes.append(sub_objs)
    for field in model._meta.private_fields:
        if hasattr(field, 'bulk_related_objects'):
            sub_objs = field.bulk_related_objects(new_objs, self.using)
            self.collect(sub_objs, source=model, nullable=True, fail_on_restricted=False)
    if fail_on_restricted:
        for (related_model, instances) in self.data.items():
            self.clear_restricted_objects_from_set(related_model, instances)
        for qs in self.fast_deletes:
            self.clear_restricted_objects_from_queryset(qs.model, qs)
        if self.restricted_objects.values():
            restricted_objects = defaultdict(list)
            for (related_model, fields) in self.restricted_objects.items():
                for (field, objs) in fields.items():
                    if objs:
                        key = "'%s.%s'" % (related_model.__name__, field.name)
                        restricted_objects[key] += objs
            if restricted_objects:
                raise RestrictedError('Cannot delete some instances of model %r because they are referenced through restricted foreign keys: %s.' % (model.__name__, ', '.join(restricted_objects)), set(chain.from_iterable(restricted_objects.values())))

@cached_property
def import_lines(self) -> list[list[int]]:
    (froms, imports) = ([], [])
    for (i, (t, *_)) in enumerate(self.token_lines):
        if <MASK>:
            break
        if t.type == token.NAME:
            if t.string == 'from':
                froms.append(i)
            elif t.string == 'import':
                imports.append(i)
    return [froms, imports]

def _read_new_value_labels(self) -> None:
    """Reads value labels with variable length strings (108 and later format)"""
    if <MASK>:
        self._path_or_buf.seek(self._seek_value_labels)
    else:
        assert self._dtype is not None
        offset = self._nobs * self._dtype.itemsize
        self._path_or_buf.seek(self._data_location + offset)
    while True:
        if self._format_version >= 117:
            if self._path_or_buf.read(5) == b'</val':
                break
        slength = self._path_or_buf.read(4)
        if not slength:
            break
        if self._format_version == 108:
            labname = self._decode(self._path_or_buf.read(9))
        elif self._format_version <= 117:
            labname = self._decode(self._path_or_buf.read(33))
        else:
            labname = self._decode(self._path_or_buf.read(129))
        self._path_or_buf.read(3)
        n = self._read_uint32()
        txtlen = self._read_uint32()
        off = np.frombuffer(self._path_or_buf.read(4 * n), dtype=f'{self._byteorder}i4', count=n)
        val = np.frombuffer(self._path_or_buf.read(4 * n), dtype=f'{self._byteorder}i4', count=n)
        ii = np.argsort(off)
        off = off[ii]
        val = val[ii]
        txt = self._path_or_buf.read(txtlen)
        self._value_label_dict[labname] = {}
        for i in range(n):
            end = off[i + 1] if i < n - 1 else txtlen
            self._value_label_dict[labname][val[i]] = self._decode(txt[off[i]:end])
        if self._format_version >= 117:
            self._path_or_buf.read(6)

def parse_docstring(docstring):
    """
    Parse out the parts of a docstring. Return (title, body, metadata).
    """
    if not docstring:
        return ('', '', {})
    docstring = cleandoc(docstring)
    parts = re.split('\\n{2,}', docstring)
    title = parts[0]
    if len(parts) == 1:
        body = ''
        metadata = {}
    else:
        parser = HeaderParser()
        try:
            metadata = parser.parsestr(parts[-1])
        except HeaderParseError:
            metadata = {}
            body = '\n\n'.join(parts[1:])
        else:
            metadata = dict(metadata.items())
            if <MASK>:
                body = '\n\n'.join(parts[1:-1])
            else:
                body = '\n\n'.join(parts[1:])
    return (title, body, metadata)

def get_device(args, kwargs):
    if kwargs.get('device'):
        device = kwargs.get('device')
        if isinstance(device, str):
            device = torch.device(device)
        return device.type
    devices = {arg.device.type for arg in args if isinstance(arg, torch.Tensor)}
    if any((dev == 'cuda' for dev in devices)):
        return 'cuda'
    elif any((dev == 'xpu' for dev in devices)):
        return 'xpu'
    elif <MASK>:
        return 'hpu'
    elif any((dev == 'cpu' for dev in devices)):
        return 'cpu'
    return None

def extend_blocks(result, blocks=None) -> list[Block]:
    """return a new extended blocks, given the result"""
    if blocks is None:
        blocks = []
    if <MASK>:
        for r in result:
            if isinstance(r, list):
                blocks.extend(r)
            else:
                blocks.append(r)
    else:
        assert isinstance(result, Block), type(result)
        blocks.append(result)
    return blocks

@staticmethod
def handle_view(args, kwargs) -> 'LocalShardsWrapper':
    view_shape = args[1]
    res_shards_list = []
    if len(args[0].local_shards()) > 1:
        if <MASK>:
            assert args[0].storage_metadata().size[0] == view_shape[0] and args[0].storage_metadata().size[1] == view_shape[1]
            res_shards_list = [aten.view.default(shard, shard.shape, **kwargs) for shard in args[0].local_shards()]
        elif args[0].local_shards()[0].ndim == 1:
            assert args[0].storage_metadata().size[0] == view_shape[0]
            res_shards_list = [aten.view.default(shard, shard.shape, **kwargs) for shard in args[0].local_shards()]
        else:
            raise NotImplementedError('No support for view on tensors ndim > 2')
    else:
        res_shards_list = [aten.view.default(shard, args[1], **kwargs) for shard in args[0].local_shards()]
    return LocalShardsWrapper(res_shards_list, args[0].local_offsets())

def _pandas_arff_parser(gzip_file, output_arrays_type, openml_columns_info, feature_names_to_select, target_names_to_select, read_csv_kwargs=None):
    """ARFF parser using `pandas.read_csv`.

    This parser uses the metadata fetched directly from OpenML and skips the metadata
    headers of ARFF file itself. The data is loaded as a CSV file.

    Parameters
    ----------
    gzip_file : GzipFile instance
        The GZip compressed file with the ARFF formatted payload.

    output_arrays_type : {"numpy", "sparse", "pandas"}
        The type of the arrays that will be returned. The possibilities are:

        - `"numpy"`: both `X` and `y` will be NumPy arrays;
        - `"sparse"`: `X` will be sparse matrix and `y` will be a NumPy array;
        - `"pandas"`: `X` will be a pandas DataFrame and `y` will be either a
          pandas Series or DataFrame.

    openml_columns_info : dict
        The information provided by OpenML regarding the columns of the ARFF
        file.

    feature_names_to_select : list of str
        A list of the feature names to be selected to build `X`.

    target_names_to_select : list of str
        A list of the target names to be selected to build `y`.

    read_csv_kwargs : dict, default=None
        Keyword arguments to pass to `pandas.read_csv`. It allows to overwrite
        the default options.

    Returns
    -------
    X : {ndarray, sparse matrix, dataframe}
        The data matrix.

    y : {ndarray, dataframe, series}
        The target.

    frame : dataframe or None
        A dataframe containing both `X` and `y`. `None` if
        `output_array_type != "pandas"`.

    categories : list of str or None
        The names of the features that are categorical. `None` if
        `output_array_type == "pandas"`.
    """
    import pandas as pd
    for line in gzip_file:
        if line.decode('utf-8').lower().startswith('@data'):
            break
    dtypes = {}
    for name in openml_columns_info:
        column_dtype = openml_columns_info[name]['data_type']
        if column_dtype.lower() == 'integer':
            dtypes[name] = 'Int64'
        elif <MASK>:
            dtypes[name] = 'category'
    dtypes_positional = {col_idx: dtypes[name] for (col_idx, name) in enumerate(openml_columns_info) if name in dtypes}
    default_read_csv_kwargs = {'header': None, 'index_col': False, 'na_values': ['?'], 'keep_default_na': False, 'comment': '%', 'quotechar': '"', 'skipinitialspace': True, 'escapechar': '\\', 'dtype': dtypes_positional}
    read_csv_kwargs = {**default_read_csv_kwargs, **(read_csv_kwargs or {})}
    frame = pd.read_csv(gzip_file, **read_csv_kwargs)
    try:
        frame.columns = [name for name in openml_columns_info]
    except ValueError as exc:
        raise pd.errors.ParserError('The number of columns provided by OpenML does not match the number of columns inferred by pandas when reading the file.') from exc
    columns_to_select = feature_names_to_select + target_names_to_select
    columns_to_keep = [col for col in frame.columns if col in columns_to_select]
    frame = frame[columns_to_keep]
    single_quote_pattern = re.compile("^'(?P<contents>.*)'$")

    def strip_single_quotes(input_string):
        match = re.search(single_quote_pattern, input_string)
        if match is None:
            return input_string
        return match.group('contents')
    categorical_columns = [name for (name, dtype) in frame.dtypes.items() if isinstance(dtype, pd.CategoricalDtype)]
    for col in categorical_columns:
        frame[col] = frame[col].cat.rename_categories(strip_single_quotes)
    (X, y) = _post_process_frame(frame, feature_names_to_select, target_names_to_select)
    if output_arrays_type == 'pandas':
        return (X, y, frame, None)
    else:
        (X, y) = (X.to_numpy(), y.to_numpy())
    categories = {name: dtype.categories.tolist() for (name, dtype) in frame.dtypes.items() if isinstance(dtype, pd.CategoricalDtype)}
    return (X, y, None, categories)

def __init__(self, subtype=None, closed: IntervalClosedType | None=None) -> None:
    from pandas.core.dtypes.common import is_string_dtype, pandas_dtype
    if closed is not None and closed not in {'right', 'left', 'both', 'neither'}:
        raise ValueError("closed must be one of 'right', 'left', 'both', 'neither'")
    if isinstance(subtype, IntervalDtype):
        if <MASK>:
            raise ValueError("dtype.closed and 'closed' do not match. Try IntervalDtype(dtype.subtype, closed) instead.")
        self._subtype = subtype._subtype
        self._closed = subtype._closed
    elif subtype is None:
        self._subtype = None
        self._closed = closed
    elif isinstance(subtype, str) and subtype.lower() == 'interval':
        self._subtype = None
        self._closed = closed
    else:
        if isinstance(subtype, str):
            m = IntervalDtype._match.search(subtype)
            if m is not None:
                gd = m.groupdict()
                subtype = gd['subtype']
                if gd.get('closed', None) is not None:
                    if closed is not None:
                        if closed != gd['closed']:
                            raise ValueError("'closed' keyword does not match value specified in dtype string")
                    closed = gd['closed']
        try:
            subtype = pandas_dtype(subtype)
        except TypeError as err:
            raise TypeError('could not construct IntervalDtype') from err
        if CategoricalDtype.is_dtype(subtype) or is_string_dtype(subtype):
            msg = 'category, object, and string subtypes are not supported for IntervalDtype'
            raise TypeError(msg)
        self._subtype = subtype
        self._closed = closed

def _py_while_stmt(test, body, get_state, set_state, opts):
    """Overload of while_stmt that executes a Python while loop."""
    del opts, get_state, set_state
    if <MASK>:
        checker = _PythonLoopChecker()
        before_iteration = checker.before_iteration
        after_iteration = checker.after_iteration
        before_iteration()
        original_body = body

        def protected_body():
            original_body()
            after_iteration()
            before_iteration()
        body = protected_body

    def guarded_test():
        test_result = test()
        try:
            return bool(test_result)
        except errors_impl.OperatorNotAllowedInGraphError as e:
            ag_logging.log(1, 'Caught error while evaluating while loop condition', exc_info=True)
            raise NotImplementedError('The condition of while loop started as non-Tensor, then changed to Tensor. This may happen either because variables changed type, or when a break or return statement inside the loop depends on a Tensor condition. In both cases, changing to a TF loop should remove the error.\nSee https://github.com/tensorflow/tensorflow/blob/master/tensorflow/python/autograph/g3doc/reference/limitations.md#consistency-of-control-flow-types for more info.') from e
    while guarded_test():
        body()

def _get_indent(lines):
    """
    Determines the leading whitespace that could be removed from all the lines.
    """
    indent = sys.maxsize
    for line in lines:
        content = len(line.lstrip())
        if content:
            indent = min(indent, len(line) - content)
    if <MASK>:
        indent = 0
    return indent

