def all_node_args_have_no_tensors(node: Node, modules: dict[str, torch.nn.Module], cache: dict[Node, bool]) -> bool:
    """
    If we know for sure that all of this node's args have no
    tensors (are primitives), return True.  If we either
    find a tensor or are not sure, return False. Note: this
    function is not exact.
    """
    if cache and node in cache:
        return cache[node]
    result = False
    if not isinstance(node, Node):
        result = True
    elif node.op == 'placeholder':
        result = False
    elif node.op == 'call_module':
        assert isinstance(node.target, str)
        if _is_activation_post_process(modules[node.target]):
            result = all_node_args_have_no_tensors(node.args[0], modules, cache)
    elif node.op == 'call_module':
        result = False
    elif node.op == 'call_function' and node.target is operator.getitem:
        result = all_node_args_have_no_tensors(node.args[0], modules, cache)
    elif node.op == 'get_attr':
        result = False
    elif node.target is getattr and node.args[1] in ['ndim', 'shape']:
        result = True
    elif node.op == 'call_method' and node.target == 'size':
        result = True
    else:
        found_one_tensor = False
        for arg in node.args:
            if isinstance(arg, list):
                for list_el in arg:
                    if isinstance(list_el, Node):
                        this_list_el_args_have_no_tensors = all_node_args_have_no_tensors(list_el, modules, cache)
                        found_one_tensor = found_one_tensor or not this_list_el_args_have_no_tensors
                        if found_one_tensor:
                            result = not found_one_tensor
                            if <MASK>:
                                cache[node] = result
                            return result
            elif isinstance(arg, int):
                pass
            elif isinstance(arg, Node):
                this_arg_args_have_no_tensors = all_node_args_have_no_tensors(arg, modules, cache)
                found_one_tensor = found_one_tensor or not this_arg_args_have_no_tensors
                if found_one_tensor:
                    result = not found_one_tensor
                    if cache:
                        cache[node] = result
                    return result
            else:
                found_one_tensor = True
            result = not found_one_tensor
    if cache:
        cache[node] = result
    return result

def need_use_acc_helper(self, reduction_type, dtype, use_scalar):
    if reduction_type == 'welford_reduce':
        return not use_scalar
    if reduction_type == 'sum' and dtype == torch.float:
        assert self.call_ranges is not None
        reduction_size = functools.reduce(operator.mul, self.call_ranges[self.reduction_depth:])
        if config.cpp.dynamic_threads:
            rt_size = reduction_size
        else:
            rt_size = CeilDiv(reduction_size, parallel_num_threads())
        chunk_size = 2 ** 20
        try:
            rt_size_hint = V.graph.sizevars.size_hint(rt_size)
        except Exception:
            return True
        if <MASK>:
            V.graph.sizevars.check_lt(chunk_size, rt_size)
            return True
        else:
            V.graph.sizevars.check_leq(rt_size, chunk_size)
    return False

