def infer_dtype_from_scalar(val) -> tuple[DtypeObj, Any]:
    """
    Interpret the dtype from a scalar.

    Parameters
    ----------
    val : object
    """
    dtype: DtypeObj = _dtype_obj
    if isinstance(val, np.ndarray):
        if <MASK>:
            msg = 'invalid ndarray passed to infer_dtype_from_scalar'
            raise ValueError(msg)
        dtype = val.dtype
        val = lib.item_from_zerodim(val)
    elif isinstance(val, str):
        dtype = _dtype_obj
        if using_string_dtype():
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
    elif isinstance(val, (np.datetime64, dt.datetime)):
        try:
            val = Timestamp(val)
        except OutOfBoundsDatetime:
            return (_dtype_obj, val)
        if val is NaT or val.tz is None:
            val = val.to_datetime64()
            dtype = val.dtype
        else:
            dtype = DatetimeTZDtype(unit=val.unit, tz=val.tz)
    elif isinstance(val, (np.timedelta64, dt.timedelta)):
        try:
            val = Timedelta(val)
        except (OutOfBoundsTimedelta, OverflowError):
            dtype = _dtype_obj
        else:
            if val is NaT:
                val = np.timedelta64('NaT', 'ns')
            else:
                val = val.asm8
            dtype = val.dtype
    elif is_bool(val):
        dtype = np.dtype(np.bool_)
    elif is_integer(val):
        if isinstance(val, np.integer):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.int64)
        try:
            np.array(val, dtype=dtype)
        except OverflowError:
            dtype = np.array(val).dtype
    elif is_float(val):
        if isinstance(val, np.floating):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.float64)
    elif is_complex(val):
        dtype = np.dtype(np.complex128)
    if isinstance(val, Period):
        dtype = PeriodDtype(freq=val.freq)
    elif isinstance(val, Interval):
        subtype = infer_dtype_from_scalar(val.left)[0]
        dtype = IntervalDtype(subtype=subtype, closed=val.closed)
    return (dtype, val)

def configure_and_create_distributed_session(distribution_strategy):
    """Configure session config and create a session with it."""

    def _create_session(distribution_strategy):
        """Create the Distributed Strategy session."""
        session_config = get_default_session_config()
        global _SESSION
        if getattr(_SESSION, 'session', None) and _SESSION.session._config:
            session_config.MergeFrom(_SESSION.session._config)
        if is_tpu_strategy(distribution_strategy):
            distribution_strategy.configure(session_config)
            master = distribution_strategy.extended._tpu_cluster_resolver.master()
            session = session_module.Session(config=session_config, target=master)
        else:
            worker_context = dc.get_current_worker_context()
            if worker_context:
                dc_session_config = worker_context.session_config
                dc_session_config.MergeFrom(session_config)
                session = session_module.Session(config=dc_session_config, target=worker_context.master_target)
            else:
                distribution_strategy.configure(session_config)
                session = session_module.Session(config=session_config)
        set_session(session)
    if <MASK>:
        dc.run_distribute_coordinator(_create_session, distribution_strategy)
    else:
        _create_session(distribution_strategy)

def expand_bias(B: Optional[_T], X: _T) -> Optional[_T]:
    """
    Expand Bias to the same size of X.
    """
    if B is not None:
        if <MASK>:
            if not isinstance(B, ir.TensorBox):
                B = ir.TensorBox(B)
            assert hasattr(X, 'get_size')
            B = L.expand(B, (X.get_size()[0], B.get_size()[-1]))
        else:
            assert isinstance(B, torch.Tensor)
            assert isinstance(X, torch.Tensor)
            B = B.expand(X.shape[0], B.shape[-1])
    return B

def _test_input_fn_iterator(self, task_type, task_id, num_gpus, input_fn, expected_values, test_reinitialize=True, ignore_order=False, use_devices_arg=False):
    (distribution, master_target) = self._get_test_object(task_type, task_id, num_gpus, use_devices_arg=use_devices_arg)
    devices = distribution.extended.worker_devices
    with ops.Graph().as_default(), self.cached_session(target=master_target) as sess:
        iterator = distribution.make_input_fn_iterator(input_fn)
        sess.run(iterator.initializer)
        for expected_value in expected_values:
            next_element = iterator.get_next()
            computed_value = sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
            if ignore_order:
                self.assertCountEqual(list(expected_value), list(computed_value))
            else:
                self.assertEqual(list(expected_value), list(computed_value))
        with self.assertRaises(errors.OutOfRangeError):
            next_element = iterator.get_next()
            sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
        if <MASK>:
            sess.run(iterator.initializer)
            for expected_value in expected_values:
                next_element = iterator.get_next()
                computed_value = sess.run([distribute_utils.select_replica(r, next_element) for r in range(len(devices))])
                if ignore_order:
                    self.assertCountEqual(list(expected_value), list(computed_value))
                else:
                    self.assertEqual(list(expected_value), list(computed_value))

def _apply_on_tensors(self, fn, args):
    tensors_idx = []
    tensors = []
    requires_grad = False
    for (i, arg) in enumerate(args):
        if isinstance(arg, torch.Tensor):
            tensors_idx.append(i)
            tensors.append(arg)
            requires_grad |= arg.requires_grad
    if <MASK>:
        return (args, None)
    new_tensors = torch.nn.modules._functions.BackwardHookFunction.apply(*tensors)
    if len(new_tensors) == 0:
        raise RuntimeError('Cannot set Module backward hook for a Module with no input Tensors.')
    grad_fns = [t.grad_fn for t in new_tensors if t.grad_fn is not None and t.grad_fn.name() == 'BackwardHookFunctionBackward']
    if len(grad_fns) == 0:
        raise RuntimeError('Error while setting up backward hooks. Please open an issue with a code sample to reproduce this.')
    fn(grad_fns[0])
    arg_list = list(args)
    for (idx, val) in zip(tensors_idx, new_tensors):
        arg_list[idx] = val
    if type(args) is tuple:
        out = tuple(arg_list)
    else:
        out = type(args)(*arg_list)
    return (out, tensors_idx)

def isscalar(val):
    """Returns whether `val` is a scalar value or scalar Tensor."""
    if isinstance(val, np_arrays.ndarray):
        val = val.data
    if isinstance(val, core.Tensor):
        ndims = val.shape.ndims
        if <MASK>:
            return ndims == 0
        else:
            return math_ops.equal(array_ops.rank(val), 0)
    else:
        return np.isscalar(val)

def raise_assert_detail(obj, message, left, right, diff=None, first_diff=None, index_values=None) -> NoReturn:
    __tracebackhide__ = True
    msg = f'{obj} are different\n\n{message}'
    if isinstance(index_values, Index):
        index_values = np.asarray(index_values)
    if isinstance(index_values, np.ndarray):
        msg += f'\n[index]: {pprint_thing(index_values)}'
    if isinstance(left, np.ndarray):
        left = pprint_thing(left)
    elif isinstance(left, (CategoricalDtype, StringDtype, NumpyEADtype)):
        left = repr(left)
    if isinstance(right, np.ndarray):
        right = pprint_thing(right)
    elif isinstance(right, (CategoricalDtype, StringDtype, NumpyEADtype)):
        right = repr(right)
    msg += f'\n[left]:  {left}\n[right]: {right}'
    if <MASK>:
        msg += f'\n[diff]: {diff}'
    if first_diff is not None:
        msg += f'\n{first_diff}'
    raise AssertionError(msg)

def _parse_see_also(self, content):
    """
        func_name : Descriptive text
            continued text
        another_func_name : Descriptive text
        func_name1, func_name2, :meth:`func_name`, func_name3

        """
    content = dedent_lines(content)
    items = []

    def parse_item_name(text):
        """Match ':role:`name`' or 'name'."""
        m = self._func_rgx.match(text)
        if not m:
            self._error_location(f'Error parsing See Also entry {line!r}')
        role = m.group('role')
        name = m.group('name') if role else m.group('name2')
        return (name, role, m.end())
    rest = []
    for line in content:
        if not line.strip():
            continue
        line_match = self._line_rgx.match(line)
        description = None
        if <MASK>:
            description = line_match.group('desc')
            if line_match.group('trailing') and description:
                self._error_location('Unexpected comma or period after function list at index %d of line "%s"' % (line_match.end('trailing'), line), error=False)
        if not description and line.startswith(' '):
            rest.append(line.strip())
        elif line_match:
            funcs = []
            text = line_match.group('allfuncs')
            while True:
                if not text.strip():
                    break
                (name, role, match_end) = parse_item_name(text)
                funcs.append((name, role))
                text = text[match_end:].strip()
                if text and text[0] == ',':
                    text = text[1:].strip()
            rest = list(filter(None, [description]))
            items.append((funcs, rest))
        else:
            self._error_location(f'Error parsing See Also entry {line!r}')
    return items

def _predict(self, X, check_input=True):
    """Private predict method with optional input validation"""
    y_pred = self._forward_pass_fast(X, check_input=check_input)
    if <MASK>:
        y_pred = y_pred.ravel()
    return self._label_binarizer.inverse_transform(y_pred)

@_onnx_symbolic('prim::ConstantSplit')
def prim_constant_split(g: jit_utils.GraphContext, self, split_size, dim):
    size = symbolic_helper._get_tensor_dim_size(self, dim)
    if size is None:
        return symbolic_helper._unimplemented('prim::ConstantSplit', 'unknown dimension size', self)
    splits = [split_size] * (size // split_size)
    leftover = size % split_size
    if <MASK>:
        splits.append(leftover)
    return g.op('Split', self, split_i=splits, axis_i=dim, outputs=len(splits))

@property
def executable(self) -> Path:
    """Get the Python executable for the virtual environment."""
    assert self.is_venv()
    if <MASK>:
        executable = self.bindir / ('python.exe' if WINDOWS else 'python')
        assert executable.is_file() or executable.is_symlink()
        assert os.access(executable, os.X_OK), f'{executable} is not executable'
        self._executable = executable
