def skip_if_lt_x_gpu(x):

    def decorator(func):

        @wraps(func)
        def wrapper(*args, **kwargs):
            if torch.cuda.is_available() and torch.cuda.device_count() >= x:
                return func(*args, **kwargs)
            if <MASK>:
                return func(*args, **kwargs)
            if TEST_XPU and torch.xpu.device_count() >= x:
                return func(*args, **kwargs)
            test_skip = TEST_SKIPS[f'multi-gpu-{x}']
            if not _maybe_handle_skip_if_lt_x_gpu(args, test_skip.message):
                sys.exit(test_skip.exit_code)
        return wrapper
    return decorator

def _validate_unshard_params_args(state: _FSDPState, writeback: bool, rank0_only: bool, offload_to_cpu: bool, with_grads: bool) -> None:
    if with_grads and (offload_to_cpu or not state._use_orig_params):
        raise NotImplementedError(f'with_grads={with_grads}, use_orig_params={state._use_orig_params}, offload_to_cpu={offload_to_cpu} is not supported yet')
    if offload_to_cpu and state._handle and (not state._handle.uses_sharded_strategy):
        raise NotImplementedError('offload_to_cpu=True and NO_SHARD is not supported yet')
    if <MASK>:
        raise NotImplementedError('writeback=True and rank0_only=True is not supported yet')
    if offload_to_cpu and (not rank0_only):
        warnings.warn('offload_to_cpu=True and rank0_only=False may result in theunsharded parameters being redundantly copied to CPU memory for GPUs sharing the same CPU memory, which risks CPU OOM. We recommend using offload_to_cpu=True with rank0_only=True.')

@classmethod
def sym_sum(cls, args):
    if len(args) == 0:
        return 0
    if <MASK>:
        return args[0]
    acc = cls.add(args[0], args[1])
    for i in range(2, len(args)):
        acc = cls.add(acc, args[i])
    return acc

def deserialize_sym_argument(self, sym_arg):
    if isinstance(sym_arg, SymIntArgument):
        if sym_arg.type == 'as_int':
            return sym_arg.as_int
        elif <MASK>:
            return self.serialized_name_to_node[sym_arg.as_name]
    elif isinstance(sym_arg, SymFloatArgument):
        if sym_arg.type == 'as_float':
            return sym_arg.as_float
        elif sym_arg.type == 'as_name':
            return self.serialized_name_to_node[sym_arg.as_name]
    elif isinstance(sym_arg, SymBoolArgument):
        if sym_arg.type == 'as_bool':
            return sym_arg.as_bool
        elif sym_arg.type == 'as_name':
            return self.serialized_name_to_node[sym_arg.as_name]
    raise SerializeError(f'Unknown symbolic argument type: {sym_arg}')

def _create_strategy(self, num_shards):
    if <MASK>:
        strategy = parameter_server_strategy_v2.ParameterServerStrategyV2(self.cluster_resolver, variable_partitioner=sharded_variable.FixedShardsPartitioner(num_shards))
    else:
        strategy = distribute_lib._get_default_strategy()
    return strategy

def deco(fn):

    @functools.wraps(fn)
    def graph_break_as_hard_error(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except (Unsupported, ObservedException) as e:
            import sys
            if <MASK>:
                exc = UncapturedHigherOrderOpError(f'{reason} Got {e.msg}', e.real_stack)
            else:
                msg = e.msg if hasattr(e, 'msg') else type(e)
                real_stack = e.real_stack if hasattr(e, 'real_stack') else None
                exc = UncapturedHigherOrderOpError(f'{reason} Got {msg}', real_stack)
            raise exc.with_traceback(sys.exc_info()[2]) from None
    return graph_break_as_hard_error

def _check_for_seq_len_0_and_consistent_head_dim_nested_helper(param: torch.Tensor, param_name: str, debug=False) -> bool:
    assert isinstance(param, NestedTensor), 'param should be a jagged NT'
    if param._ragged_idx == 1:
        if debug:
            log.warning('Fused kernels do not support ragged num_head_dims, %s has a ragged num_heads.', param_name)
        return False
    if <MASK>:
        if debug:
            log.warning('Fused kernels do not support seq_len == 0, %s has a seq len of 0.', param_name)
        return False
    return True

def filter(logger: Union[logging.Logger, logging.PlaceHolder]) -> TypeGuard[logging.Logger]:
    if <MASK>:
        return False
    if not logger.name.startswith('torch._inductor'):
        return False
    if logger.propagate:
        return False
    return True

def _test_backward_mul_by_grad_output(outputs, inputs, masked) -> bool:
    diff_input_list: list[torch.Tensor] = list(_iter_tensors(inputs, True))
    if not diff_input_list:
        raise GradcheckError('no Tensors requiring grad found in input')
    grads_input = torch.autograd.grad(outputs, diff_input_list, [torch.zeros_like(o, memory_format=torch.legacy_contiguous_format) for o in outputs], allow_unused=True)
    for (gi, di) in zip(grads_input, diff_input_list):
        if gi is None:
            continue
        if isinstance(gi, torch.Tensor) and gi.layout != torch.strided:
            if <MASK>:
                raise GradcheckError('grad is incorrect layout (' + str(gi.layout) + ' is not ' + str(di.layout) + ')')
            if _is_sparse_any_tensor(gi):
                sparse_kind = str(gi.layout).replace('torch.', '').replace('_coo', '')
                if gi.sparse_dim() != di.sparse_dim():
                    raise GradcheckError(f'grad is {sparse_kind} tensor, but has incorrect sparse_dim {gi.sparse_dim()}, expected {di.sparse_dim()}')
                if gi.dense_dim() != di.dense_dim():
                    raise GradcheckError(f'grad is {sparse_kind} tensor, but has incorrect dense_dim {gi.dense_dim()}, expected {di.dense_dim()}')
            gi = gi.to_dense()
            di = di.to_dense()
        if masked:
            if not torch.allclose(gi, torch.zeros_like(gi)):
                raise GradcheckError('backward not multiplied by grad_output')
        elif not gi.eq(0).all():
            raise GradcheckError('backward not multiplied by grad_output')
        if gi.dtype != di.dtype:
            raise GradcheckError('grad is incorrect type')
        if gi.device != di.device:
            raise GradcheckError('grad is incorrect device')
        if gi.size() != di.size():
            raise GradcheckError('grad is incorrect size')
    return True

def get_tensors_from_tensor_names(graph, tensor_names):
    """Gets the Tensors associated with the `tensor_names` in the provided graph.

  Args:
    graph: TensorFlow Graph.
    tensor_names: List of strings that represent names of tensors in the graph.

  Returns:
    A list of Tensor objects in the same order the names are provided.

  Raises:
    ValueError:
      tensor_names contains an invalid tensor name.
  """
    tensor_name_to_tensor = {}
    for op in graph.get_operations():
        for tensor in op.values():
            tensor_name_to_tensor[get_tensor_name(tensor)] = tensor
    tensors = []
    invalid_tensors = []
    for name in tensor_names:
        if <MASK>:
            raise ValueError("Invalid type for a tensor name in the provided graph. Expected type for a tensor name is 'str', instead got type '{}' for tensor name '{}'".format(type(name), name))
        tensor = tensor_name_to_tensor.get(name)
        if tensor is None:
            invalid_tensors.append(name)
        else:
            tensors.append(tensor)
    if invalid_tensors:
        raise ValueError("Invalid tensors '{}' were found.".format(','.join(invalid_tensors)))
    return tensors

@_onnx_symbolic('aten::linalg_norm')
@symbolic_helper.parse_args('v', 'v', 'is', 'b', 'v')
def linalg_norm(g: jit_utils.GraphContext, self: torch._C.Value, ord: torch._C.Value, dim: Sequence[int] | None, keepdim: bool, dtype: torch._C.Value):
    ord_value = None
    if dim is None:
        if symbolic_helper._is_none(ord):
            self = symbolic_helper._reshape_helper(g, self, [-1])
            ord = g.op('Constant', value_t=torch.LongTensor([2]))
        self_dim = symbolic_helper._get_tensor_rank(self)
        if self_dim is None:
            return symbolic_helper._unimplemented('dim', 'Input rank must be known at export time.', self)
        if self_dim == 1:
            ord_value = symbolic_helper._parse_arg(ord, 'f')
        else:
            dim = [0, 1]
    elif <MASK>:
        if symbolic_helper._is_none(ord):
            ord = g.op('Constant', value_t=torch.LongTensor([2]))
        ord_value = symbolic_helper._parse_arg(ord, 'f')
    if ord_value:
        return linalg_vector_norm(g, self, ord_value, dim, keepdim, dtype)
    return linalg_matrix_norm(g, self, ord, dim, keepdim, dtype)

def _populate_recursive_ancestor_map(graph: torch.fx.Graph) -> dict[Node, set[Node]]:
    node_to_recursive_ancestors: dict[Node, set[Node]] = {}
    for node in graph.nodes:
        node_to_recursive_ancestors[node] = set()
    for node in graph.nodes:
        all_args = _get_flat_args_unique(node, {})
        for arg in all_args:
            if <MASK>:
                node_to_recursive_ancestors[node].update(node_to_recursive_ancestors[arg])
                node_to_recursive_ancestors[node].add(arg)
    return node_to_recursive_ancestors

def __new__(cls, *args, wrap_storage=None, dtype=None, device=None, _internal=False):
    if not _internal:
        _warn_typed_storage_removal()
    if cls == torch.storage._LegacyStorage:
        raise RuntimeError('Only child classes of _LegacyStorage can be instantiated')
    if cls == TypedStorage:
        return super().__new__(cls)
    else:
        arg_error_msg = f'{cls}.__new__ received an invalid combination of arguments. Expected one of:\n * no arguments\n * (int size)\n * (Sequence data)\n * (*, UntypedStorage wrap_storage)'
        if device is not None:
            raise RuntimeError(arg_error_msg + "\nKeyword argument 'device' cannot be specified")
        if dtype is not None:
            raise RuntimeError(arg_error_msg + "\nKeyword argument 'dtype' cannot be specified")
        if wrap_storage is None:
            if len(args) > 1:
                raise RuntimeError(arg_error_msg + '\nToo many positional arguments')
            if len(args) == 1 and (not _isint(args[0])) and (not isinstance(args[0], collections.abc.Sequence)):
                raise TypeError(arg_error_msg + f'\nArgument type not recognized: {type(args[0])}')
            return TypedStorage(*args, dtype=cls._dtype, device=_get_device_from_module(cls.__module__), _internal=True)
        else:
            if len(args) != 0:
                raise RuntimeError(arg_error_msg + "\nNo positional arguments should be given when using 'wrap_storage'")
            if <MASK>:
                raise TypeError(arg_error_msg + f"\nArgument 'wrap_storage' must be UntypedStorage, but got {type(wrap_storage)}")
            cls_device = _get_device_from_module(cls.__module__)
            if wrap_storage.device.type != cls_device:
                raise RuntimeError(arg_error_msg + f"\nDevice of 'wrap_storage' must be {cls_device}, but got {wrap_storage.device.type}")
            return TypedStorage(*args, wrap_storage=wrap_storage, dtype=cls.dtype, _internal=True)

