            else:
                _data._mask = np.logical_or(mask, _data._mask)
            _data._sharedmask = False
    if fill_value is None:
        fill_value = getattr(data, '_fill_value', None)
    if fill_value is not None:
        _data._fill_value = _check_fill_value(fill_value, _data.dtype)
    if hard_mask is None:
        _data._hardmask = getattr(data, '_hardmask', False)
    else:
        _data._hardmask = hard_mask
    _data._baseclass = _baseclass
    return _data

def admin_view(self, view, cacheable=False):
    """
        Decorator to create an admin view attached to this ``AdminSite``. This
        wraps the view and provides permission checking by calling
        ``self.has_permission``.

        You'll want to use this from within ``AdminSite.get_urls()``:

            class MyAdminSite(AdminSite):

                def get_urls(self):
                    from django.urls import path

                    urls = super().get_urls()
                    urls += [
                        path('my_view/', self.admin_view(some_view))
                    ]
                    return urls

        By default, admin_views are marked non-cacheable using the
        ``never_cache`` decorator. If the view can be safely cached, set
        cacheable=True.
        """

    def inner(request, *args, **kwargs):
        if <MASK>:
            if request.path == reverse('admin:logout', current_app=self.name):
                index_path = reverse('admin:index', current_app=self.name)
                return HttpResponseRedirect(index_path)
            from django.contrib.auth.views import redirect_to_login
            return redirect_to_login(request.get_full_path(), reverse('admin:login', current_app=self.name))
        return view(request, *args, **kwargs)
    if not cacheable:
        inner = never_cache(inner)
    if not getattr(view, 'csrf_exempt', False):
        inner = csrf_protect(inner)
    return update_wrapper(inner, view)

def _get_tensordot_tests(dtype_, rank_a_, rank_b_, num_dims_, dynamic_shape_):

    def _random_subset(m, n):
        assert m <= n
        return np.random.permutation(n)[:m].astype(np.int32)

    def _generate_random_tensors_and_dims():
        a_shape = np.random.random_integers(1, _MAXDIM, rank_a_)
        b_shape = np.random.random_integers(1, _MAXDIM, rank_b_)
        shared_shape = np.random.random_integers(1, _MAXDIM, num_dims_)
        a_dims = _random_subset(num_dims_, rank_a_)
        b_dims = _random_subset(num_dims_, rank_b_)
        for i in range(num_dims_):
            a_shape[a_dims[i]] = shared_shape[i]
            b_shape[b_dims[i]] = shared_shape[i]
        a = np.random.uniform(low=-1.0, high=1.0, size=np.prod(a_shape)).reshape(a_shape).astype(dtype_)
        b = np.random.uniform(low=-1.0, high=1.0, size=np.prod(b_shape)).reshape(b_shape).astype(dtype_)
        return (a, b, a_dims, b_dims)

    @test_util.run_in_graph_and_eager_modes(use_gpu=True)
    @test_util.run_without_tensor_float_32('Tests tensordot, which calls matmul')
    def test_tensordot(self):
        if dynamic_shape_ and context.executing_eagerly():
            self.skipTest('Placeholders not support in eager mode')
        num_trials = min(30, num_dims_ * num_dims_)
        if <MASK>:
            tol = 0.05
        elif dtype_ == np.float32 or dtype_ == np.complex64:
            tol = 1e-05
        else:
            tol = 1e-12
        for _ in range(num_trials):
            (a_np, b_np, a_dims_np, b_dims_np) = _generate_random_tensors_and_dims()
            np_ans = np.tensordot(a_np, b_np, axes=(a_dims_np, b_dims_np))
            with self.cached_session() as sess:
                if dynamic_shape_:
                    a = array_ops.placeholder(dtype_)
                    b = array_ops.placeholder(dtype_)
                    axes = array_ops.placeholder(dtypes.int32)
                    c = math_ops.tensordot(a, b, axes)
                    tf_ans = sess.run(c, feed_dict={a: a_np, b: b_np, axes: (a_dims_np, b_dims_np)})
                else:
                    tf_ans = math_ops.tensordot(a_np, b_np, (a_dims_np, b_dims_np))
            self.assertAllClose(tf_ans, np_ans, rtol=tol, atol=tol)
            self.assertAllEqual(tf_ans.shape, np_ans.shape)

    @test_util.run_in_graph_and_eager_modes(use_gpu=True)
    @test_util.run_without_tensor_float_32('Tests tensordot, which calls matmul')
    def test_tensordot_scalar_axes(self):
        if dynamic_shape_ and context.executing_eagerly():
            self.skipTest('Placeholders not support in eager mode')
        if num_dims_ < 1:
            self.skipTest('Not a test')
        if dtype_ == np.float16:
            tol = 0.05
        elif dtype_ == np.float32 or dtype_ == np.complex64:
            tol = 1e-05
        else:
            tol = 1e-12
        shape = [5] * num_dims_
        a_np = np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape)).reshape(shape).astype(dtype_)
        b_np = np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape)).reshape(shape).astype(dtype_)
        all_axes = [0, 1]
        if a_np.ndim > 2:
            all_axes.append(a_np.ndim - 1)
        for axes in all_axes:
            np_ans = np.tensordot(a_np, b_np, axes=axes)
            with self.cached_session() as sess:
                if dynamic_shape_:
                    a = array_ops.placeholder(dtype_)
                    b = array_ops.placeholder(dtype_)
                    c = math_ops.tensordot(a, b, axes=axes)
                    tf_ans = sess.run(c, feed_dict={a: a_np, b: b_np})
                else:
                    tf_ans = math_ops.tensordot(a_np, b_np, axes=axes)
            self.assertAllClose(tf_ans, np_ans, rtol=tol, atol=tol)
            self.assertAllEqual(tf_ans.shape, np_ans.shape)
    return [test_tensordot, test_tensordot_scalar_axes]

def check_against_reference(self, func, reference_func, output_func, args, kwargs=None, allow_unused=True, check_types=True, no_grad=False, no_gradgrad=False):
    """Verifies a function performs identically to some reference implementation.

    Commonly, this is used to verify that a JIT implementation
    (output_func) matches the behavior of the eager implementation
    (reference_func).
    """
    kwargs = kwargs if kwargs else {}

    def allSum(vs):
        if isinstance(vs, torch.Tensor):
            vs = (vs,)
        return sum(((i + 1) * v.sum().abs() if v.dtype.is_complex else (i + 1) * v.sum() for (i, v) in enumerate(vs) if v is not None and v.dtype in floating_and_complex_types_and(torch.half, torch.bfloat16)))

    def clone_tensor(t, preserve_requires_grad):
        require_grad = preserve_requires_grad and t.requires_grad
        return t.detach().clone().requires_grad_(require_grad)

    def clone_inputs(preserve_requires_grad: bool):
        inputs: list[Union[torch.Tensor, list[torch.Tensor]]] = []
        for arg in args:
            if isinstance(arg, torch.Tensor):
                inputs.append(clone_tensor(arg, preserve_requires_grad))
            elif <MASK>:
                inputs.append([clone_tensor(t, preserve_requires_grad) for t in arg])
            else:
                inputs.append(arg)
        return inputs

    def get_recording_tensors(args):
        recording_tensors: list[torch.Tensor] = []
        for arg in args:
            if isinstance(arg, torch.Tensor) and arg.requires_grad:
                recording_tensors.append(arg)
            elif is_iterable_of_tensors(arg):
                recording_tensors.extend(filter(lambda t: t.requires_grad, arg))
        return recording_tensors
    nograd_inputs = clone_inputs(preserve_requires_grad=False)
    outputs = self.runAndSaveRNG(reference_func, nograd_inputs, kwargs)
    with enable_profiling_mode_for_profiling_tests():
        outputs_test = self.runAndSaveRNG(func, nograd_inputs, kwargs)
    self.assertEqual(outputs, outputs_test)
    if check_types:
        check_output_types(self, func, outputs_test, nograd_inputs, kwargs)
    if no_grad:
        return
    with enable_profiling_mode_for_profiling_tests():
        recording_inputs = clone_inputs(preserve_requires_grad=True)
        recording_tensors = get_recording_tensors(recording_inputs)
        outputs = output_func(self.runAndSaveRNG(reference_func, recording_inputs, kwargs))
        grads = torch.autograd.grad(allSum(outputs), recording_tensors, allow_unused=allow_unused)
        outputs_test = output_func(self.runAndSaveRNG(func, recording_inputs, kwargs))
        grads_test = torch.autograd.grad(allSum(outputs_test), recording_tensors, allow_unused=allow_unused)
        self.assertEqual(outputs, outputs_test)
        self.assertEqual(grads, grads_test)
        if self._testMethodName in nn_functional_single_grad or no_gradgrad:
            return
        outputs = output_func(self.runAndSaveRNG(reference_func, recording_inputs, kwargs))
        l1 = allSum(outputs)
        grads = torch.autograd.grad(l1, recording_tensors, create_graph=True, allow_unused=allow_unused)
        l2 = allSum(grads) * l1
        grads2 = torch.autograd.grad(l2, recording_tensors, allow_unused=allow_unused)
        recording_inputs = clone_inputs(preserve_requires_grad=True)
        recording_tensors = get_recording_tensors(recording_inputs)
        outputs_test = output_func(self.runAndSaveRNG(func, recording_inputs, kwargs))
        l1_test = allSum(outputs_test)
        grads_test = torch.autograd.grad(l1_test, recording_tensors, create_graph=True, allow_unused=allow_unused)
        l2_test = allSum(grads_test) * l1_test
        grads2_test = torch.autograd.grad(l2_test, recording_tensors, allow_unused=allow_unused)
        self.assertEqual(outputs, outputs_test)
        self.assertEqual(grads, grads_test)
        for (g2, g2_test) in zip(grads2, grads2_test, strict=True):
            if g2 is None and g2_test is None:
                continue
            self.assertEqual(g2, g2_test, atol=0.0005, rtol=0.0001)

def mark_nodes_dislike_padding(g: Graph, user_visible_output_strides: dict[Node, tuple[int, ...]]) -> None:
    """
    Nodes like convolution/convolution_backward want its input to be dense.
    If we pad their inputs, we result in extra calls to copy kernels!  On the other hand, padding usually helps reduction.

    The pass finds nodes that dislike padding. These are nodes that can be reached
    from a convolution/convolution_backward in the backward direction without
    going thru a reduction.
    """
    if not config.comprehensive_padding:
        return
    extended_user_visible_nodes = extend_user_visible_output_strides(user_visible_output_strides)
    ops_dislike_padding = OrderedSet([aten.convolution, aten.convolution_backward, aten._scaled_mm])
    ops_like_padding = OrderedSet([aten.var_mean, aten.sum, aten.mean, aten.prod, aten.any, aten.amin, aten.amax, aten.min, aten.max, aten.argmin, aten.argmax, aten.scatter_reduce])

    def _get_overload_packet(node: torch.fx.Node) -> Optional[torch._ops.OpOverloadPacket]:
        return node.target._overloadpacket if node.op == 'call_function' and isinstance(node.target, torch._ops.OpOverload) and hasattr(node.target, '_overloadpacket') else None
    for cur in reversed(g.nodes):
        if isinstance(cur.target, torch._higher_order_ops.triton_kernel_wrap.TritonKernelWrapperMutation):
            cur.meta['dislike_padding'] = True
            continue
        if isinstance(cur.target, torch._ops.OpOverload) and get_layout_constraint_tag(cur.target) == torch._C.Tag.needs_exact_strides:
            cur.meta['dislike_padding'] = True
            continue
        op = _get_overload_packet(cur)
        if not op:
            continue
        if op in ops_dislike_padding:
            cur.meta['dislike_padding'] = True
        if cur.meta.get('dislike_padding', False):
            for prior in cur.all_input_nodes:
                prior_op = _get_overload_packet(prior)
                if <MASK>:
                    continue
                if prior_op not in ops_like_padding:
                    prior.meta['dislike_padding'] = True
        if not config.pad_outputs and cur in extended_user_visible_nodes:
            cur.meta['dislike_padding'] = True

def gen_class_ctor(self, k: SchemaKind, class_name: str, returns: int) -> str:
    if <MASK>:
        return ''
    elif k is SchemaKind.inplace:
        return f'{class_name}(Tensor& self) : outputs_{{std::ref(self)}} {{}}'
    elif k is SchemaKind.out:
        out_args = ', '.join((f'Tensor& out{i}' for i in range(returns)))
        out_refs = ', '.join((f'std::ref(out{i})' for i in range(returns)))
        return f'{class_name}({out_args}) : outputs_{{ {out_refs} }} {{}}'
    elif k is SchemaKind.mutable or k is SchemaKind.scratch:
        raise AssertionError(f'{k} structured operators are currently not supported')
    else:
        assert_never(k)

def call(self, inputs, **kwargs):
    if <MASK>:
        for layer in self._shared_input_branch:
            inputs = layer(inputs)
        a = inputs
        b = inputs
    else:
        (a, b) = inputs
    for layer in self._branch_a:
        a = layer(a)
    for layer in self._branch_b:
        b = layer(b)
    outs = (a, b)
    if self._shared_output_branch:
        for layer in self._shared_output_branch:
            outs = layer(outs)
    return outs

@classmethod
def from_object(cls, tnp: object) -> Optional[Self]:
    if not callable(tnp):
        return None
    tnp_to_np = torch._dynamo.variables.misc.get_tnp_to_np_map()
    try:
        if <MASK>:
            return None
    except TypeError:
        return None
    if not (mod := getattr(np, '__module__', None)):
        mod = 'numpy'
    if not (name := getattr(np, '__name__', None)):
        return None
    assert np == getattr(importlib.import_module(mod), name)
    return cls(mod, name)

