@tf_export.tf_export('experimental.numpy.cumprod', v1=[])
@np_utils.np_doc('cumprod')
def cumprod(a, axis=None, dtype=None):
    a = asarray(a, dtype=dtype)
    if dtype is None:
        a = _maybe_promote_to_int(a)
    if <MASK>:
        a = ravel(a)
        axis = 0
    elif axis < 0:
        axis += array_ops.rank(a)
    return math_ops.cumprod(a, axis)

def _check_large_sparse(X, accept_large_sparse=False):
    """Raise a ValueError if X has 64bit indices and accept_large_sparse=False"""
    if not accept_large_sparse:
        supported_indices = ['int32']
        if X.format == 'coo':
            index_keys = ['col', 'row']
        elif <MASK>:
            index_keys = ['indices', 'indptr']
        else:
            return
        for key in index_keys:
            indices_datatype = getattr(X, key).dtype
            if indices_datatype not in supported_indices:
                raise ValueError(f'Only sparse matrices with 32-bit integer indices are accepted. Got {indices_datatype} indices. Please do report a minimal reproducer on scikit-learn issue tracker so that support for your use-case can be studied by maintainers. See: https://scikit-learn.org/dev/developers/minimal_reproducer.html')

def is_free_format(file):
    """Check if file is in free format Fortran."""
    result = 0
    with open(file, encoding='latin1') as f:
        line = f.readline()
        n = 10000
        if <MASK>:
            n = 0
        elif _has_f90_header(line):
            n = 0
            result = 1
        while n > 0 and line:
            line = line.rstrip()
            if line and line[0] != '!':
                n -= 1
                if line[0] != '\t' and _free_f90_start(line[:5]) or line[-1:] == '&':
                    result = 1
                    break
            line = f.readline()
    return result

def maybe_downcast_to_dtype(result: ArrayLike, dtype: np.dtype) -> ArrayLike:
    """
    try to cast to the specified dtype (e.g. convert back to bool/int
    or could be an astype of float64->float32
    """
    if isinstance(result, ABCSeries):
        result = result._values
    do_round = False
    if not isinstance(dtype, np.dtype):
        raise TypeError(dtype)
    converted = maybe_downcast_numeric(result, dtype, do_round)
    if converted is not result:
        return converted
    if dtype.kind in 'mM' and result.dtype.kind in 'if':
        result = result.astype(dtype)
    elif <MASK>:
        result = cast(np.ndarray, result)
        result = array_to_timedelta64(result)
    elif dtype == np.dtype('M8[ns]') and result.dtype == _dtype_obj:
        result = cast(np.ndarray, result)
        return np.asarray(maybe_cast_to_datetime(result, dtype=dtype))
    return result

def add_fields(self, form, index):
    """Add a hidden field for the object's primary key."""
    from django.db.models import AutoField, ForeignKey, OneToOneField
    self._pk_field = pk = self.model._meta.pk

    def pk_is_not_editable(pk):
        return not pk.editable or (pk.auto_created or isinstance(pk, AutoField)) or (pk.remote_field and pk.remote_field.parent_link and pk_is_not_editable(pk.remote_field.model._meta.pk))
    if <MASK>:
        if form.is_bound:
            pk_value = None if form.instance._state.adding else form.instance.pk
        else:
            try:
                if index is not None:
                    pk_value = self.get_queryset()[index].pk
                else:
                    pk_value = None
            except IndexError:
                pk_value = None
        if isinstance(pk, (ForeignKey, OneToOneField)):
            qs = pk.remote_field.model._default_manager.get_queryset()
        else:
            qs = self.model._default_manager.get_queryset()
        qs = qs.using(form.instance._state.db)
        if form._meta.widgets:
            widget = form._meta.widgets.get(self._pk_field.name, HiddenInput)
        else:
            widget = HiddenInput
        form.fields[self._pk_field.name] = ModelChoiceField(qs, initial=pk_value, required=False, widget=widget)
    super().add_fields(form, index)

def specs_compatible(spec1: Spec, spec2: Spec) -> bool:
    """Check if two specifications are compatible (one can be used where the other is expected)."""
    if type(spec1) is not type(spec2):
        return False
    if <MASK>:
        return spec1.dtype == spec2.dtype
    elif isinstance(spec1, TensorSpec):
        assert isinstance(spec2, TensorSpec)
        return spec1.size == spec2.size and spec1.dtype == spec2.dtype
    return False

def _is_match(modules, node, pattern, max_uses=sys.maxsize):
    """Matches a node in fx against a pattern"""
    if isinstance(pattern, tuple):
        (self_match, *arg_matches) = pattern
        if self_match is getattr:
            assert len(pattern) == 2, 'Expecting getattr pattern to have two elements'
            arg_matches = []
    else:
        self_match = pattern
        arg_matches = []
    if isinstance(self_match, type) and issubclass(self_match, MatchAllNode):
        return True
    if node == pattern:
        return True
    if not isinstance(node, Node) or len(node.users) > max_uses:
        return False
    if isinstance(self_match, type) and issubclass(self_match, torch.nn.Module):
        if node.op != 'call_module':
            return False
        if type_before_parametrizations(modules[node.target]) != self_match:
            return False
    elif callable(self_match):
        if node.op != 'call_function' or node.target is not self_match:
            return False
        elif node.target is getattr:
            if <MASK>:
                return False
    elif isinstance(self_match, str):
        if node.op != 'call_method' or node.target != self_match:
            return False
    elif node.target != self_match:
        return False
    if not arg_matches:
        return True
    if len(arg_matches) != len(node.args):
        return False
    return all((_is_match(modules, node, arg_match, max_uses=1) for (node, arg_match) in zip(node.args, arg_matches)))

def update_coverage(coverage_records: list[CoverageRecord], interested_folders: list[str], platform: TestPlatform) -> None:
    for item in coverage_records:
        record = item.to_dict()
        file_path = record['filepath']
        if not is_intrested_file(file_path, interested_folders, platform):
            continue
        covered_range = record['covered_lines']
        uncovered_range = record['uncovered_lines']
        file_path = transform_file_name(file_path, interested_folders, platform)
        if file_path not in covered_lines:
            covered_lines[file_path] = set()
        if file_path not in uncovered_lines:
            uncovered_lines[file_path] = set()
        if covered_range is not None:
            covered_lines[file_path].update(covered_range)
        if <MASK>:
            uncovered_lines[file_path].update(uncovered_range)

