def handle_aliasing_and_mutation(info: torch._C.Argument, arg: Any) -> None:
    if isinstance(info.type, torch.ListType):
        assert isinstance(arg, (list, tuple)), type(arg)
    if library_utils.is_tensor_like_type(info.type):
        assert not isinstance(arg, (tuple, list))
    if arg is None:
        return
    if info.alias_info is None:
        return

    def add_alias(t: IRNode) -> None:
        self.alias_names.append(t.get_name())
        assert info.alias_info is not None
        if <MASK>:
            self.mutation_outputs.append(MutationOutput(NoneLayout(device=t.get_device()), t, self))
    if library_utils.is_tensorlist_like_type(info.type):
        if arg is not None:
            for optional_tensor_arg in arg:
                add_alias(optional_tensor_arg)
    else:
        assert library_utils.is_tensor_like_type(info.type)
        add_alias(arg)

@final
def _op_via_apply(self, name: str, *args, **kwargs):
    """Compute the result of an operation by using GroupBy's apply."""
    f = getattr(type(self._obj_with_exclusions), name)

    def curried(x):
        return f(x, *args, **kwargs)
    curried.__name__ = name
    if name in base.plotting_methods:
        return self._python_apply_general(curried, self._selected_obj)
    is_transform = name in base.transformation_kernels
    result = self._python_apply_general(curried, self._obj_with_exclusions, is_transform=is_transform, not_indexed_same=not is_transform)
    if <MASK>:
        result = self._set_result_index_ordered(result)
    return result

@multiprocessing_context.setter
def multiprocessing_context(self, multiprocessing_context):
    if multiprocessing_context is not None:
        if <MASK>:
            if isinstance(multiprocessing_context, str):
                valid_start_methods = torch.multiprocessing.get_all_start_methods()
                if multiprocessing_context not in valid_start_methods:
                    raise ValueError(f'multiprocessing_context option should specify a valid start method in {valid_start_methods!r}, but got multiprocessing_context={multiprocessing_context!r}')
                multiprocessing_context = torch.multiprocessing.get_context(multiprocessing_context)
            if not isinstance(multiprocessing_context, python_multiprocessing.context.BaseContext):
                raise TypeError(f'multiprocessing_context option should be a valid context object or a string specifying the start method, but got multiprocessing_context={multiprocessing_context}')
        else:
            raise ValueError(f'multiprocessing_context can only be used with multi-process loading (num_workers > 0), but got num_workers={self.num_workers}')
    self.__multiprocessing_context = multiprocessing_context

def _create_tensor_maps(self):
    """Creates tensor to cache id maps."""
    self.tensorname_to_cache_idx = {}
    self.cache_idx_to_tensor_idx = []
    for out_tensor in self.traced_tensors:
        tensor_name = out_tensor.name
        if <MASK>:
            raise ValueError('Tensor name {} should not be already in tensorname_to_cache_idx'.format(tensor_name))
        if tensor_name not in self.graph_order.tensor_to_idx:
            raise ValueError('Tensor name {} is not in the tensor_to_idx, tensor_to_idx={} '.format(tensor_name, self.graph_order.tensor_to_idx))
        tensor_idx = self.graph_order.tensor_to_idx[tensor_name]
        cache_idx = len(self.tensorname_to_cache_idx)
        self.tensorname_to_cache_idx[tensor_name] = cache_idx
        self.cache_idx_to_tensor_idx.append(tensor_idx)
        if len(self.tensorname_to_cache_idx) != len(self.cache_idx_to_tensor_idx):
            raise RuntimeError('len(self.tensorname_to_cache_idx) must equallen(self.cache_idx_to_tensor_idx), got len(self.tensorname_to_cache_idx)={}, len(self.cache_idx_to_tensor_idx)={}'.format(len(self.tensorname_to_cache_idx), len(self.cache_idx_to_tensor_idx)))

