def visit_Call(self, node):
    """Determine if a Call node is 'torch.jit.annotate' in __init__.

        Visit a Call node in an ``nn.Module``'s ``__init__``
        method and determine if it's ``torch.jit.annotate``. If so,
        see if it conforms to our attribute annotation rules.
        """
    if self.visiting_class_level_ann:
        return
    try:
        if node.func.value.value.id != 'torch' or node.func.value.attr != 'jit' or node.func.attr != 'annotate':
            self.generic_visit(node)
        elif <MASK>:
            self.generic_visit(node)
    except AttributeError:
        self.generic_visit(node)
    if len(node.args) != 2:
        return
    if not isinstance(node.args[0], ast.Subscript):
        return
    containers = {'List', 'Dict', 'Optional'}
    try:
        ann_type = node.args[0].value.id
    except AttributeError:
        return
    if ann_type not in containers:
        return
    if not self._is_empty_container(node.args[1], ann_type):
        return
    warnings.warn("The TorchScript type system doesn't support instance-level annotations on empty non-base types in `__init__`. Instead, either 1) use a type annotation in the class body, or 2) wrap the type in `torch.jit.Attribute`.")

def _convert_tf1_model(flags):
    """Calls function to convert the TensorFlow 1.X model into a TFLite model.

  Args:
    flags: argparse.Namespace object.

  Raises:
    ValueError: Invalid flags.
  """
    if flags.custom_opdefs:
        register_custom_opdefs(_parse_array(flags.custom_opdefs))
    converter = _get_tflite_converter(flags)
    if flags.inference_type:
        converter.inference_type = _parse_inference_type(flags.inference_type, 'inference_type')
    if flags.inference_input_type:
        converter.inference_input_type = _parse_inference_type(flags.inference_input_type, 'inference_input_type')
    if flags.output_format:
        converter.output_format = _toco_flags_pb2.FileFormat.Value(flags.output_format)
    if flags.mean_values and flags.std_dev_values:
        input_arrays = converter.get_input_arrays()
        std_dev_values = _parse_array(flags.std_dev_values, type_fn=float)
        if converter.inference_type == dtypes.float32:
            mean_values = _parse_array(flags.mean_values, type_fn=float)
        else:
            mean_values = _parse_array(flags.mean_values, type_fn=int)
        quant_stats = list(zip(mean_values, std_dev_values))
        if not flags.input_arrays and len(input_arrays) > 1 or len(input_arrays) != len(quant_stats):
            raise ValueError("Mismatching --input_arrays, --std_dev_values, and --mean_values. The flags must have the same number of items. The current input arrays are '{0}'. --input_arrays must be present when specifying --std_dev_values and --mean_values with multiple input tensors in order to map between names and values.".format(','.join(input_arrays)))
        converter.quantized_input_stats = dict(list(zip(input_arrays, quant_stats)))
    if flags.default_ranges_min is not None and flags.default_ranges_max is not None:
        converter.default_ranges_stats = (flags.default_ranges_min, flags.default_ranges_max)
    if flags.drop_control_dependency:
        converter.drop_control_dependency = flags.drop_control_dependency
    if flags.reorder_across_fake_quant:
        converter.reorder_across_fake_quant = flags.reorder_across_fake_quant
    if flags.change_concat_input_ranges:
        converter.change_concat_input_ranges = flags.change_concat_input_ranges == 'TRUE'
    if flags.allow_custom_ops:
        converter.allow_custom_ops = flags.allow_custom_ops
    if flags.target_ops:
        ops_set_options = lite.OpsSet.get_options()
        converter.target_spec.supported_ops = set()
        for option in flags.target_ops.split(','):
            if option not in ops_set_options:
                raise ValueError('Invalid value for --target_ops. Options: {0}'.format(','.join(ops_set_options)))
            converter.target_spec.supported_ops.add(lite.OpsSet(option))
    if flags.experimental_select_user_tf_ops:
        if lite.OpsSet.SELECT_TF_OPS not in converter.target_spec.supported_ops:
            raise ValueError('--experimental_select_user_tf_ops can only be set if --target_ops contains SELECT_TF_OPS.')
        user_op_set = set()
        for op_name in flags.experimental_select_user_tf_ops.split(','):
            user_op_set.add(op_name)
        converter.target_spec.experimental_select_user_tf_ops = list(user_op_set)
    if flags.post_training_quantize:
        converter.optimizations = [lite.Optimize.DEFAULT]
        if converter.inference_type != dtypes.float32:
            print('--post_training_quantize quantizes a graph of inference_type FLOAT. Overriding inference_type to FLOAT.')
            converter.inference_type = dtypes.float32
    if flags.quantize_to_float16:
        converter.target_spec.supported_types = [dtypes.float16]
        if not flags.post_training_quantize:
            print('--quantize_to_float16 will only take effect with the --post_training_quantize flag enabled.')
    if flags.dump_graphviz_dir:
        converter.dump_graphviz_dir = flags.dump_graphviz_dir
    if <MASK>:
        converter.dump_graphviz_vode = flags.dump_graphviz_video
    if flags.conversion_summary_dir:
        converter.conversion_summary_dir = flags.conversion_summary_dir
    converter.experimental_new_converter = flags.experimental_new_converter
    if flags.experimental_new_quantizer is not None:
        converter.experimental_new_quantizer = flags.experimental_new_quantizer
    output_data = converter.convert()
    with gfile.GFile(flags.output_file, 'wb') as f:
        f.write(output_data)

def find_legit_leaks_from_referrers(active_fakes: weakref.WeakSet) -> weakref.WeakSet:
    legit_leak: weakref.WeakSet = weakref.WeakSet()
    fake_list = list(active_fakes)
    fake_list_id = id(fake_list)
    for act in fake_list:
        seen = set()
        flagged = False
        for r in gc.get_referrers(act):
            rid = id(r)
            if rid in seen:
                continue
            seen.add(rid)
            if rid == fake_list_id:
                continue
            if _is_globals_or_locals(r):
                continue
            if isinstance(r, _SKIP_TYPES):
                continue
            if _is_tracked_fake(r):
                continue
            if isinstance(r, dict):
                if _is_gm_meta_like_dict(r, act):
                    continue
                if <MASK>:
                    continue
                flagged = True
                break
            flagged = True
            break
        if flagged:
            legit_leak.add(act)
    return legit_leak

def annotate_getitem_nodes(graph: torch.fx.Graph) -> None:
    """
    Annotate the type of getitem nodes, inferred from the type of sequence node.
    If sequence node is not annotated with a type, do nothing.
    Currently support getitem nodes from tuple, list, and NamedTuple sequence node.

    This is helpful since annotations on local names within function are lost during FX transforms.
    Adding back known type annotation for getitem nodes to improve jit scriptability.

    Args:
        graph (Graph): The graph to be annotated
    """
    for node in graph.nodes:
        if node.target == operator.getitem:
            (sequence_node, index_node) = node.args
            if not sequence_node.type:
                continue
            if <MASK>:
                parameterized_types = sequence_node.type.__args__
                if sequence_node.type._name == 'Tuple':
                    if len(parameterized_types) == 2 and isinstance(parameterized_types[1], type(...)):
                        node.type = parameterized_types[0]
                    else:
                        assert len(parameterized_types) > index_node
                        node_type = parameterized_types[index_node]
                        node.type = node_type
                elif sequence_node.type._name == 'List':
                    assert len(parameterized_types) == 1
                    node.type = parameterized_types[0]
            elif hasattr(sequence_node.type, '__origin__'):
                parameterized_types = sequence_node.type.__args__
                if sequence_node.type.__origin__ is tuple:
                    if len(parameterized_types) == 2 and isinstance(parameterized_types[1], type(...)):
                        node.type = parameterized_types[0]
                    else:
                        assert len(parameterized_types) > index_node
                        node_type = parameterized_types[index_node]
                        node.type = node_type
                elif sequence_node.type.__origin__ is list:
                    assert len(parameterized_types) == 1
                    node.type = parameterized_types[0]
            elif hasattr(sequence_node.type, '__annotations__'):
                if sequence_node.type == torch.Tensor:
                    continue
                sequence_node_field_types = sequence_node.type.__annotations__
                field_name = sequence_node.type._fields[index_node]
                node.type = sequence_node_field_types[field_name]

def _check_estimator_sparse_container(name, estimator_orig, sparse_type):
    rng = np.random.RandomState(0)
    X = rng.uniform(size=(40, 3))
    X[X < 0.6] = 0
    X = _enforce_estimator_tags_X(estimator_orig, X)
    y = (4 * rng.uniform(size=X.shape[0])).astype(np.int32)
    with ignore_warnings(category=FutureWarning):
        estimator = clone(estimator_orig)
    y = _enforce_estimator_tags_y(estimator, y)
    tags = get_tags(estimator_orig)
    for (matrix_format, X) in _generate_sparse_data(sparse_type(X)):
        with ignore_warnings(category=FutureWarning):
            estimator = clone(estimator_orig)
            if name in ['Scaler', 'StandardScaler']:
                estimator.set_params(with_mean=False)
        if '64' in matrix_format:
            err_msg = f"Estimator {name} doesn't seem to support {matrix_format} matrix, and is not failing gracefully, e.g. by using check_array(X, accept_large_sparse=False)."
        else:
            err_msg = f"Estimator {name} doesn't seem to fail gracefully on sparse data: error message should state explicitly that sparse input is not supported if this is not the case, e.g. by using check_array(X, accept_sparse=False)."
        with raises((TypeError, ValueError), match=['sparse', 'Sparse'], may_pass=True, err_msg=err_msg):
            with ignore_warnings(category=FutureWarning):
                estimator.fit(X, y)
            if hasattr(estimator, 'predict'):
                pred = estimator.predict(X)
                if <MASK>:
                    assert pred.shape == (X.shape[0], 1)
                else:
                    assert pred.shape == (X.shape[0],)
            if hasattr(estimator, 'predict_proba'):
                probs = estimator.predict_proba(X)
                if not tags.classifier_tags.multi_class:
                    expected_probs_shape = (X.shape[0], 2)
                else:
                    expected_probs_shape = (X.shape[0], 4)
                assert probs.shape == expected_probs_shape

def check_nondeterministic_alert(self, fn, caller_name, should_alert=True):
    """Checks that an operation produces a nondeterministic alert when
        expected while `torch.use_deterministic_algorithms(True)` is set.

        Args:
          fn (callable): Function to check for a nondeterministic alert

          caller_name (str): Name of the operation that produces the
              nondeterministic alert. This name is expected to appear at the
              beginning of the error/warning message.

          should_alert (bool, optional): If True, then the check will only pass
              if calling `fn` produces a nondeterministic error/warning with the
              expected message. If False, then the check will only pass if
              calling `fn` does not produce an error. Default: `True`.
        """
    alert_message = '^' + caller_name + ' does not have a deterministic implementation, but you set'
    with DeterministicGuard(True):
        if <MASK>:
            with self.assertRaisesRegex(RuntimeError, alert_message, msg='expected a non-deterministic error, but it was not raised'):
                fn()
        else:
            try:
                fn()
            except RuntimeError as e:
                if 'does not have a deterministic implementation' in str(e):
                    self.fail('did not expect non-deterministic error message, ' + 'but got one anyway: "' + str(e) + '"')
                raise
    with DeterministicGuard(True, warn_only=True):
        if should_alert:
            with self.assertWarnsRegex(UserWarning, alert_message):
                fn()
        else:
            with warnings.catch_warnings(record=True) as w:
                warnings.simplefilter('always')
                fn()
                for warning in w:
                    if isinstance(warning, UserWarning):
                        self.assertTrue(re.search(alert_message, str(warning)) is None)

def find_coalesced_group(pg_name: str, entries: list[dict[str, Any]], _pg_guids: dict[tuple[str, int], str], rank: int) -> list[tuple[int, dict[str, Any]]]:
    """Given a list of entries, if the collective_seq_id of the first entry matches that of subsequent ones,
    build an return a list of entries terminating in a 'coalesced' op entry all sharing a collective_seq_id
    """
    found = []
    collective_seq_id = None
    for (i, e) in enumerate(entries):
        if <MASK>:
            continue
        elif collective_seq_id is None:
            collective_seq_id = e['p2p_seq_id'] if e['is_p2p'] else e['collective_seq_id']
            found.append((i, e))
        elif not e['is_p2p'] and e['collective_seq_id'] == collective_seq_id:
            found.append((i, e))
        elif e['is_p2p'] and e['p2p_seq_id'] == collective_seq_id:
            found.append((i, e))
        else:
            break
    if len(found) > 1:
        assert found[-1][1]['profiling_name'] == 'nccl:coalesced'
        return found
    return []

def f(x):
    if x > 0:
        if <MASK>:
            return x
        else:
            return x * x
    else:
        return x * x * x

def check_set_output_transform(name, transformer_orig):
    tags = get_tags(transformer_orig)
    if not tags.input_tags.two_d_array or tags.no_validation:
        return
    rng = np.random.RandomState(0)
    transformer = clone(transformer_orig)
    X = rng.uniform(size=(20, 5))
    X = _enforce_estimator_tags_X(transformer_orig, X)
    y = rng.randint(0, 2, size=20)
    y = _enforce_estimator_tags_y(transformer_orig, y)
    set_random_state(transformer)

    def fit_then_transform(est):
        if <MASK>:
            return est.fit(X, y).transform(X, y)
        return est.fit(X, y).transform(X)

    def fit_transform(est):
        return est.fit_transform(X, y)
    transform_methods = {'transform': fit_then_transform, 'fit_transform': fit_transform}
    for (name, transform_method) in transform_methods.items():
        transformer = clone(transformer)
        if not hasattr(transformer, name):
            continue
        X_trans_no_setting = transform_method(transformer)
        if name in CROSS_DECOMPOSITION:
            X_trans_no_setting = X_trans_no_setting[0]
        transformer.set_output(transform='default')
        X_trans_default = transform_method(transformer)
        if name in CROSS_DECOMPOSITION:
            X_trans_default = X_trans_default[0]
        assert_allclose_dense_sparse(X_trans_no_setting, X_trans_default)

