def loop_fn(i):
    nonlocal run_once
    if run_once and (not self._persistent):
        if <MASK>:
            raise RuntimeError('GradientTape must be created with persistent=True to compute the batch_jacobian with parallel_iterations.')
        else:
            raise RuntimeError('GradientTape must be created with persistent=True to compute the batch_jacobian.')
    run_once = True
    with self._ensure_recording():
        y = array_ops.gather(target, i, axis=1)
    return self.gradient(y, source, unconnected_gradients=unconnected_gradients)

def __torch_dispatch__(self, func, types, args=(), kwargs=None):
    if kwargs is None:
        kwargs = {}
    unrecognized_types = [t for t in types if not issubclass(t, torch._subclasses.FakeTensor) and t not in [torch.Tensor, FunctionalTensor]]
    if unrecognized_types:
        not_implemented_log.debug('FunctionalTensor unrecognized subclass(es): %s', unrecognized_types)
        return NotImplemented

    def _can_decompose(func):
        if self.export and func == torch.ops.aten.dropout.default:
            return False
        from torch._decomp import _should_decompose_because_unsafe_op
        if _should_decompose_because_unsafe_op(func):
            return True
        alias_info_present = any((arg.alias_info for arg in func._schema.arguments))
        if alias_info_present or func._schema.is_mutable:
            return True
        if self.export:
            if self.pre_dispatch:
                if func.namespace not in ['aten', 'prim'] and func._can_decompose():
                    warnings.warn(f'At pre-dispatch tracing, we assume that any custom op marked with CompositeImplicitAutograd and have functional schema are safe to not decompose. Found {func} to be one such op.')
                return False
            return True
        return True
    if func not in FunctionalTensor.metadata_fns and _can_decompose(func) and torch._C._dispatch_has_kernel(func.name()):
        with self:
            r = func.decompose(*args, **kwargs)
            if r is not NotImplemented:
                return r

    def wrap(x):
        assert not isinstance(x, FunctionalTensor)
        if isinstance(x, torch.Tensor) and torch._is_functional_tensor(x):
            return FunctionalTensor(x, self)
        return x

    def unwrap(x):
        return x.elem
    from torch._higher_order_ops.auto_functionalize import can_auto_functionalize, do_auto_functionalize, do_auto_functionalize_v2
    if can_auto_functionalize(func) and (not torch._C._dispatch_has_kernel_for_dispatch_key(func.name(), torch._C.DispatchKey.Functionalize)):
        import torch._inductor.config as inductor_config
        if self.export or not inductor_config.enable_auto_functionalized_v2:
            return do_auto_functionalize(self, func, args, kwargs)
        else:
            return do_auto_functionalize_v2(self, func, args, kwargs)
    from torch._higher_order_ops.effects import handle_effects, has_effects
    if <MASK>:
        assert not torch._C._dispatch_has_kernel_for_dispatch_key(func.name(), torch._C.DispatchKey.Functionalize)
        return handle_effects(self._allow_token_discovery, self._tokens, func, args, kwargs)
    (args_unwrapped, kwargs_unwrapped) = pytree.tree_map_only(FunctionalTensor, unwrap, (args, kwargs))
    is_included = torch._C._dispatch_tls_is_dispatch_key_included(torch._C.DispatchKey.Functionalize)
    is_excluded = torch._C._dispatch_tls_is_dispatch_key_excluded(torch._C.DispatchKey.Functionalize)
    assert is_excluded or not is_included
    include_to_set = torch._C._dispatch_tls_local_include_set() | torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize)
    exclude_to_set = torch._C._dispatch_tls_local_exclude_set().remove(torch._C.DispatchKey.Functionalize) - FunctionalTensor._extra_dispatch_keys
    with torch._C._ForceDispatchKeyGuard(include_to_set, exclude_to_set):
        try:
            old_apply_views = torch._functionalize_enable_reapply_views(True)
            if func in FunctionalTensor.metadata_fns:
                outs_unwrapped = func(*args_unwrapped, **kwargs_unwrapped)
                outs_wrapped = pytree.tree_map_only(torch.Tensor, wrap, outs_unwrapped)
            else:
                outs_unwrapped = func._op_dk(torch._C.DispatchKey.Functionalize, *args_unwrapped, **kwargs_unwrapped)
                if self.export:
                    if func == torch.ops.aten.dropout.default:
                        torch._freeze_functional_tensor(outs_unwrapped)
                outs_wrapped = pytree.tree_map_only(torch.Tensor, wrap, outs_unwrapped)
        finally:
            torch._disable_functionalization()
            torch._functionalize_enable_reapply_views(old_apply_views)
    is_included = torch._C._dispatch_tls_is_dispatch_key_included(torch._C.DispatchKey.Functionalize)
    is_excluded = torch._C._dispatch_tls_is_dispatch_key_excluded(torch._C.DispatchKey.Functionalize)
    assert is_excluded or not is_included
    if not any((isinstance(x, FunctionalTensor) for x in pytree.tree_leaves(outs_wrapped))) or func == torch.ops.aten.lift_fresh.default:
        return outs_wrapped
    if torch.Tag.inplace_view in func.tags and func is not torch.ops.aten.set_.source_Tensor:
        with torch.utils._mode_utils.no_dispatch():
            func(*args, **kwargs)
    return return_and_correct_aliasing(func, args, kwargs, outs_wrapped)

def _wait_futures(self, scope: dict[str, Any]) -> None:
    kernels = {key: value for (key, value) in scope.items() if isinstance(value, (Future, CodeCacheFuture))}
    pbar = tqdm(total=len(kernels), desc='Inductor Compilation', disable=config.disable_progress, delay=0)
    for (key, result) in kernels.items():
        if <MASK>:
            pbar.set_postfix_str(key)
        try:
            kernel = result.result()
            scope[key] = kernel
        except BrokenProcessPool as e:
            raise RuntimeError('A compilation subprocess exited unexpectedly. This is likely due to a crash. To facilitate debugging, you can re-run with TORCHINDUCTOR_COMPILE_THREADS=1 to cause compilation to occur in the main process.') from e
        pbar.update(1)

def _build_model_with_inputs(self, inputs, targets):
    """Build the model (set model inputs/outputs), mainly for subclass model."""
    processed_inputs = []
    is_dict_inputs = False
    orig_inputs = inputs
    if isinstance(inputs, (data_types.DatasetV1, data_types.DatasetV2)):
        (inputs, targets, _) = training_utils_v1.extract_tensors_from_dataset(inputs)
    training_utils_v1.validate_input_types(inputs, orig_inputs)
    if isinstance(inputs, (list, tuple)):
        processed_inputs += list(inputs)
    elif isinstance(inputs, dict):
        is_dict_inputs = True
        keys = sorted(inputs.keys())
        processed_inputs = [inputs[k] for k in keys]
    else:
        processed_inputs.append(inputs)
    for input_tensor in processed_inputs:
        if training_utils_v1.is_composite_or_composite_value(input_tensor):
            raise ValueError('All SparseTensor and RaggedTensor inputs must be explicitly declared using a keras.Input() with sparse=True or ragged=True. We found an undeclared input %s. For Sequential models, please add a keras.Input() as your first Layer. For subclassed models, please call self._set_inputs() on your input set, which you can create using keras.Input() for each input to your model.' % (input_tensor,))
    if isinstance(orig_inputs, (data_types.DatasetV1, data_types.DatasetV2, iterator_ops.Iterator)):
        if <MASK>:
            inputs = training_utils_v1.cast_if_floating_dtype(inputs, self.dtype)

        def create_tensor_spec(t):
            return tensor_spec.TensorSpec(t.shape, t.dtype)
        cast_inputs = nest.map_structure(create_tensor_spec, inputs)
    elif training_utils_v1.has_tensors(inputs):
        cast_inputs = training_utils_v1.cast_if_floating_dtype(inputs)
    else:
        cast_inputs = inputs
    self._set_inputs(cast_inputs)
    return (processed_inputs, targets, is_dict_inputs)

def filter_op(self, op: 'cutlass_library.gemm_op.GemmOperation') -> 'cutlass_library.gemm_op.GemmOperation':
    """
        Helper method:

        Determines whether a given Cutlass GEMM op definition is suitable for the current
        input / output of the operation that this template is supposed to implement.

        Takes memory layout, dtype and support for EVT operations into account,
        and filters potentially problematic ops.

        Returns None if the op is not suitable, otherwise returns the op to be used, which might
        have been mutated.
        """
    if op.gemm_kind not in self._get_supported_ops():
        return None
    X = self.input_nodes[0]
    W = self.input_nodes[1]
    if not self._shape_match(op):
        return None
    if not self._dtype_match(op):
        return None
    if not self._alignment_match(op):
        log.debug('Skipping due to alignment mismatch. op: %s', op.configuration_name())
        return None
    if op.tile_scheduler.name == 'StreamK':
        static_shape = PythonWrapperCodegen.statically_known_list_of_ints_or_none(tuple(X.get_size()) + tuple(W.get_size()))
        if not static_shape:
            return None
    op = copy.deepcopy(op)
    self.set_layout(op.A, X.get_layout())
    self.set_layout(op.B, W.get_layout())
    op.D.layout = CUTLASSGemmTemplate.cutlass_layout(self.output_node.get_layout())
    status = self.set_alignment(X.get_layout(), op.A) and self.set_alignment(W.get_layout(), op.B) and self.set_alignment(self.output_node.get_layout(), op.D)
    if not status:
        log.debug('Skipping due to alignment setting failure. op: %s', op.configuration_name())
        return None
    if inductor_cuda_config.cutlass_tma_only and (not self._has_tma_epilogue(op)):
        return None
    op.element_epilogue = op.accumulator_type()
    if <MASK>:
        is_op_fast_accum = 'fastaccum' in op.configuration_name()
        if self.use_fast_accum ^ is_op_fast_accum:
            return None
    status = self._set_bias_layout_and_alignment(op)
    if not status:
        log.debug('Skipping due to bias layout and alignment setting failure. op: %s', op.configuration_name())
        return None
    if inductor_cuda_config.cutlass_op_allowlist_regex:
        if not re.search(inductor_cuda_config.cutlass_op_allowlist_regex, op.configuration_name()):
            return None
    if inductor_cuda_config.cutlass_op_denylist_regex is not None:
        if re.search(inductor_cuda_config.cutlass_op_denylist_regex, op.configuration_name()):
            return None
    return op

def write_view_information_to_args(mutable_arg_names: list[str], mutable_arg_types: list[torch.Type], kwargs: dict[str, Any], arg_to_base_index: dict[str, Any]):
    """
    This function writes the view information into kwargs. It reads mutable_args from kwargs.
    and uses arg_to_base_index and tensor information to write ViewInfo into kwargs.
    mutable_arg_names: mutable custom operator arg names.
    mutable_arg_types: mutable custom operator arg types.
    kwargs: the original custom operator args.
    arg_to_base_index: maps mutable_arg_name to int | [int] that refers to the base tensor that
                       corresponds to the input tensor
    """

    def write_single_view(prefix: str, tensor: Tensor, base_index: int):
        assert f'{prefix}_base_index' not in kwargs
        assert f'{prefix}_size' not in kwargs
        assert f'{prefix}_stride' not in kwargs
        assert f'{prefix}_storage_offset' not in kwargs
        assert f'{prefix}_slice_dim' not in kwargs
        assert f'{prefix}_slice_start' not in kwargs
        assert f'{prefix}_slice_end' not in kwargs

        def use_as_strided(tensor):
            kwargs[f'{prefix}_size'] = tensor.size()
            kwargs[f'{prefix}_stride'] = tensor.stride()
            kwargs[f'{prefix}_storage_offset'] = tensor.storage_offset()

        def use_slice(dim, start, end):
            kwargs[f'{prefix}_slice_dim'] = dim
            kwargs[f'{prefix}_slice_start'] = start
            kwargs[f'{prefix}_slice_end'] = end

        def use_alias():
            kwargs[f'{prefix}_alias'] = True
        if tensor is None:
            kwargs[f'{prefix}_base_index'] = None
        else:
            base = get_base(tensor)
            kwargs[f'{prefix}_base_index'] = base_index
            if base is None:
                return
            elif is_alias(base, tensor):
                use_alias()
            elif (slice_info := try_use_slice(base, tensor)) is not None:
                use_slice(*slice_info)
            else:
                use_as_strided(tensor)
    for (arg_name, arg_type) in zip(mutable_arg_names, mutable_arg_types):
        arg = kwargs[arg_name]
        if <MASK>:
            if arg is None:
                kwargs[f'_{arg_name}_length'] = None
            else:
                kwargs[f'_{arg_name}_length'] = len(arg)
                for (i, elem) in enumerate(arg):
                    write_single_view(f'_{arg_name}_{i}', elem, arg_to_base_index[arg_name][i])
        elif library_utils.is_tensor_like_type(arg_type):
            write_single_view(f'_{arg_name}', kwargs[arg_name], arg_to_base_index.get(arg_name))
        else:
            raise RuntimeError(f'Unsupported type {arg_type}')

def main() -> None:
    target = os.path.join('torch', 'masked', '_docs.py')
    try:
        import torch
    except ImportError as msg:
        print(f'Failed to import torch required to build {target}: {msg}')
        return
    if <MASK>:
        with open(target) as _f:
            current_content = _f.read()
    else:
        current_content = ''
    _new_content = []
    _new_content.append('# -*- coding: utf-8 -*-\n# This file is generated, do not modify it!\n#\n# To update this file, run the update masked docs script as follows:\n#\n#   python tools/update_masked_docs.py\n#\n# The script must be called from an environment where the development\n# version of torch package can be imported and is functional.\n#\n')
    for func_name in sorted(torch.masked._ops.__all__):
        func = getattr(torch.masked._ops, func_name)
        func_doc = torch.masked._generate_docstring(func)
        _new_content.append(f'{func_name}_docstring = """{func_doc}"""\n')
    new_content = '\n'.join(_new_content)
    if new_content == current_content:
        print(f'Nothing to update in {target}')
        return
    with open(target, 'w') as _f:
        _f.write(new_content)
    print(f'Successfully updated {target}')

def github_data(pr_number):
    query = '
    {
      repository(owner: "pytorch", name: "pytorch") {
        pullRequest(number: %s ) {
          author {
            login
          }
          reviews(last: 5, states: APPROVED) {
            nodes {
              author {
                login
              }
            }
          }
          labels(first: 10) {
            edges {
              node {
                name
              }
            }
          }
        }
      }
    }
    ' % pr_number
    query = run_query(query)
    if <MASK>:
        global _ERRORS
        _ERRORS.append(query.get('errors'))
        if len(_ERRORS) < _MAX_ERROR_LEN:
            return ([], 'None', ())
        else:
            raise Exception(f'Got {_MAX_ERROR_LEN} errors: {_ERRORS}, please check if there is something wrong')
    edges = query['data']['repository']['pullRequest']['labels']['edges']
    labels = [edge['node']['name'] for edge in edges]
    author = query['data']['repository']['pullRequest']['author']['login']
    nodes = query['data']['repository']['pullRequest']['reviews']['nodes']
    accepters = {node['author']['login'] for node in nodes}
    accepters = tuple(sorted(accepters))
    return (labels, author, accepters)

def user_defined_triton_kernel_transitive_closure_source_code(kernel) -> str:
    """
    Given a triton kernel function pointer collect the transitive closure of
    its dependencies
    """
    compile_wrapper = IndentedBuffer()
    compile_wrapper.splice(kernel.src, strip=True)
    import triton
    from triton import JITFunction
    from triton.language import constexpr
    symbols_included = OrderedSet([kernel.__name__])

    def traverse(cur_kernel):
        unqualified_loads = OrderedSet((inst.argval for inst in dis.Bytecode(cur_kernel.fn) if inst.opname == 'LOAD_GLOBAL'))
        global_annotations = cur_kernel.fn.__globals__.get('__annotations__', {})
        for symbol_name in cur_kernel.fn.__code__.co_names:
            if symbol_name in symbols_included:
                continue
            if symbol_name in cur_kernel.fn.__globals__:
                symbol = cur_kernel.fn.__globals__[symbol_name]
                if isinstance(symbol, JITFunction):
                    compile_wrapper.newline()
                    compile_wrapper.writeline('@triton.jit')
                    compile_wrapper.splice(symbol.src, strip=True)
                    symbols_included.add(symbol_name)
                    traverse(symbol)
                elif <MASK>:
                    compile_wrapper.newline()
                    compile_wrapper.writeline('@triton.constexpr_function')
                    compile_wrapper.splice(symbol.src, strip=True)
                    symbols_included.add(symbol_name)
                    traverse(symbol)
                elif isinstance(symbol, (int, str, bool, constexpr)):
                    compile_wrapper.newline()
                    if isinstance(symbol, constexpr):
                        symbol_str = f'tl.constexpr({symbol.value!r})'
                    else:
                        symbol_str = f'{symbol!r}'
                    if (annotation := global_annotations.get(symbol_name)):
                        if isinstance(annotation, type):
                            annotation_code = f': {annotation.__module__}.{annotation.__name__}'
                        else:
                            annotation_code = f': {annotation!r}'
                        compile_wrapper.writeline(f'{symbol_name}{annotation_code} = {symbol_str}')
                    else:
                        compile_wrapper.writeline(f'{symbol_name} = {symbol_str}')
                    symbols_included.add(symbol_name)
                elif symbol_name in unqualified_loads and symbol_name != 'tl' and hasattr(symbol, '__module__') and symbol.__module__.startswith('triton'):
                    compile_wrapper.writeline(f'from {symbol.__module__} import {symbol.__name__} as {symbol_name}')
                    symbols_included.add(symbol_name)
    traverse(kernel)
    return compile_wrapper.getvalue()

@def_function.function
def _fprop_cond(k, y):
    with forwardprop.ForwardAccumulator(y, 1.0) as acc:
        if <MASK>:
            ret = 3.0 * y
        else:
            ret = 0.0
    return acc.jvp(ret)

def prune(self, klass):
    if <MASK>:
        raise NotImplementedError('UnaryOp only support invert type ops')
    operand = self.operand
    operand = operand.prune(klass)
    if operand is not None and (issubclass(klass, ConditionBinOp) and operand.condition is not None or (not issubclass(klass, ConditionBinOp) and issubclass(klass, FilterBinOp) and (operand.filter is not None))):
        return operand.invert()
    return None

def __torch_dispatch__(self, func, types, args=(), kwargs=None):
    if kwargs is None:
        kwargs = {}
    unrecognized_types = [t for t in types if not issubclass(t, torch._subclasses.FakeTensor) and t not in [torch.Tensor, FunctionalTensor]]
    if unrecognized_types:
        not_implemented_log.debug('FunctionalTensor unrecognized subclass(es): %s', unrecognized_types)
        return NotImplemented

    def _can_decompose(func):
        if <MASK>:
            return False
        from torch._decomp import _should_decompose_because_unsafe_op
        if _should_decompose_because_unsafe_op(func):
            return True
        alias_info_present = any((arg.alias_info for arg in func._schema.arguments))
        if alias_info_present or func._schema.is_mutable:
            return True
        if self.export:
            if self.pre_dispatch:
                if func.namespace not in ['aten', 'prim'] and func._can_decompose():
                    warnings.warn(f'At pre-dispatch tracing, we assume that any custom op marked with CompositeImplicitAutograd and have functional schema are safe to not decompose. Found {func} to be one such op.')
                return False
            return True
        return True
    if func not in FunctionalTensor.metadata_fns and _can_decompose(func) and torch._C._dispatch_has_kernel(func.name()):
        with self:
            r = func.decompose(*args, **kwargs)
            if r is not NotImplemented:
                return r

    def wrap(x):
        assert not isinstance(x, FunctionalTensor)
        if isinstance(x, torch.Tensor) and torch._is_functional_tensor(x):
            return FunctionalTensor(x, self)
        return x

    def unwrap(x):
        return x.elem
    from torch._higher_order_ops.auto_functionalize import can_auto_functionalize, do_auto_functionalize, do_auto_functionalize_v2
    if can_auto_functionalize(func) and (not torch._C._dispatch_has_kernel_for_dispatch_key(func.name(), torch._C.DispatchKey.Functionalize)):
        import torch._inductor.config as inductor_config
        if self.export or not inductor_config.enable_auto_functionalized_v2:
            return do_auto_functionalize(self, func, args, kwargs)
        else:
            return do_auto_functionalize_v2(self, func, args, kwargs)
    from torch._higher_order_ops.effects import handle_effects, has_effects
    if has_effects(func, args, kwargs):
        assert not torch._C._dispatch_has_kernel_for_dispatch_key(func.name(), torch._C.DispatchKey.Functionalize)
        return handle_effects(self._allow_token_discovery, self._tokens, func, args, kwargs)
    (args_unwrapped, kwargs_unwrapped) = pytree.tree_map_only(FunctionalTensor, unwrap, (args, kwargs))
    is_included = torch._C._dispatch_tls_is_dispatch_key_included(torch._C.DispatchKey.Functionalize)
    is_excluded = torch._C._dispatch_tls_is_dispatch_key_excluded(torch._C.DispatchKey.Functionalize)
    assert is_excluded or not is_included
    include_to_set = torch._C._dispatch_tls_local_include_set() | torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize)
    exclude_to_set = torch._C._dispatch_tls_local_exclude_set().remove(torch._C.DispatchKey.Functionalize) - FunctionalTensor._extra_dispatch_keys
    with torch._C._ForceDispatchKeyGuard(include_to_set, exclude_to_set):
        try:
            old_apply_views = torch._functionalize_enable_reapply_views(True)
            if func in FunctionalTensor.metadata_fns:
                outs_unwrapped = func(*args_unwrapped, **kwargs_unwrapped)
                outs_wrapped = pytree.tree_map_only(torch.Tensor, wrap, outs_unwrapped)
            else:
                outs_unwrapped = func._op_dk(torch._C.DispatchKey.Functionalize, *args_unwrapped, **kwargs_unwrapped)
                if self.export:
                    if func == torch.ops.aten.dropout.default:
                        torch._freeze_functional_tensor(outs_unwrapped)
                outs_wrapped = pytree.tree_map_only(torch.Tensor, wrap, outs_unwrapped)
        finally:
            torch._disable_functionalization()
            torch._functionalize_enable_reapply_views(old_apply_views)
    is_included = torch._C._dispatch_tls_is_dispatch_key_included(torch._C.DispatchKey.Functionalize)
    is_excluded = torch._C._dispatch_tls_is_dispatch_key_excluded(torch._C.DispatchKey.Functionalize)
    assert is_excluded or not is_included
    if not any((isinstance(x, FunctionalTensor) for x in pytree.tree_leaves(outs_wrapped))) or func == torch.ops.aten.lift_fresh.default:
        return outs_wrapped
    if torch.Tag.inplace_view in func.tags and func is not torch.ops.aten.set_.source_Tensor:
        with torch.utils._mode_utils.no_dispatch():
            func(*args, **kwargs)
    return return_and_correct_aliasing(func, args, kwargs, outs_wrapped)

def get_corr_func(method: CorrelationMethod) -> Callable[[np.ndarray, np.ndarray], float]:
    if method == 'kendall':
        from scipy.stats import kendalltau

        def func(a, b):
            return kendalltau(a, b)[0]
        return func
    elif method == 'spearman':
        from scipy.stats import spearmanr

        def func(a, b):
            return spearmanr(a, b)[0]
        return func
    elif <MASK>:

        def func(a, b):
            return np.corrcoef(a, b)[0, 1]
        return func
    elif callable(method):
        return method
    raise ValueError(f"Unknown method '{method}', expected one of 'kendall', 'spearman', 'pearson', or callable")

def is_wrapped_tensor_arg(self, value):
    if <MASK>:
        return True
    if isinstance(value, (list, tuple)):
        if any((isinstance(x, WrappedTensor) for x in value)):
            return True
    return False

@skip_if_lt_x_gpu(2)
@skip_but_pass_in_sandcastle_if(BACKEND not in DistTestCases.backend_feature['ddp'], f'The {BACKEND} backend does not support DistributedDataParallel')
def test_ddp_uneven_inputs(self):
    dim = 1000
    batch = 1
    large_model = nn.Sequential(nn.Conv2d(1, 20, 5), nn.ReLU(), nn.Conv2d(20, 32, 5), nn.ReLU(), nn.Conv2d(32, 256, 5), nn.ReLU())
    small_model = nn.Linear(dim, dim, bias=False)
    bn_net = BatchNormNet()

    class UnusedParamModule(nn.Module):

        def __init__(self, unused_params_rank):
            super().__init__()
            self.t0 = Task()
            self.t1 = Task()
            self.unused_params_rank = unused_params_rank

        def task_parameters(self):
            return (self.t0.p, self.t1.p)

        def forward(self, x, rank):
            return self.t1(self.t0(x)) if rank != self.unused_params_rank else self.t1(x)
    unjoined_rank_with_unused_params_model = UnusedParamModule(1)
    joined_rank_with_unused_params_model = UnusedParamModule(0)
    rank = self.rank
    models_to_test = [DDPUnevenTestInput(name='batch_norm_net', model=bn_net, inp=torch.ones(batch, 2, device=rank), sync_interval=1), DDPUnevenTestInput(name='large_conv_model', model=large_model, inp=torch.ones(batch, batch, dim, dim, device=rank), sync_interval=1), DDPUnevenTestInput(name='small_model', model=small_model, inp=torch.ones(batch, dim, device=rank), sync_interval=1), DDPUnevenTestInput(name='unjoined_rank_with_unused_params_model', model=unjoined_rank_with_unused_params_model, inp=(torch.ones(batch, 2, device=rank), rank), sync_interval=1), DDPUnevenTestInput(name='joined_rank_with_unused_params_model', model=joined_rank_with_unused_params_model, inp=(torch.ones(batch, 2, device=rank), rank), sync_interval=1)]
    models_with_hook = [DDPUnevenTestInput(name='small_model_allreduce_hook', model=small_model, hook=default.allreduce_hook, state=None, inp=torch.ones(batch, dim, device=rank), sync_interval=1), DDPUnevenTestInput(name='small_model_power_sgd_hook', model=small_model, hook=powerSGD.powerSGD_hook, state=powerSGD.PowerSGDState(process_group=None, matrix_approximation_rank=1, start_powerSGD_iter=1, warm_start=False, use_error_feedback=False), inp=torch.ones(batch, dim, device=rank), sync_interval=1)]
    models_to_test.extend(models_with_hook)
    if HAS_TORCHVISION:
        resnet_model = torchvision.models.resnet50()
        models_to_test.append(DDPUnevenTestInput(name='resnet_model', model=resnet_model, inp=torch.ones(1, 3, 1000, 1000), sync_interval=1))
    models_with_sync = []
    for (i, test_input) in enumerate(models_to_test):
        models_with_sync.append(DDPUnevenTestInput(name=test_input.name, model=test_input.model, inp=test_input.inp, sync_interval=i + 2))
    throw_on_early_term_tests = []
    for test_input in models_to_test:
        throw_on_early_term_tests.append(DDPUnevenTestInput(name=test_input.name, model=test_input.model, inp=test_input.inp, sync_interval=test_input.sync_interval, throw_on_early_termination=True))
    models_to_test.extend(models_with_sync)
    models_to_test.extend(throw_on_early_term_tests)
    baseline_num_iters = [0, 5]
    iteration_offsets = [2, 3, 10]
    num_uneven_ranks = [1]
    if <MASK>:
        num_uneven_ranks.append(2)
    iteration_mappings = []
    for num_early_join_ranks in num_uneven_ranks:
        for baseline_iter in baseline_num_iters:
            for offset in iteration_offsets:
                mapping = dict.fromkeys(range(num_early_join_ranks), baseline_iter)
                if num_early_join_ranks > 1:
                    for rank in mapping.keys():
                        if rank > 0:
                            mapping[rank] += offset // 2
                mapping.update(dict.fromkeys(range(num_early_join_ranks, dist.get_world_size()), baseline_iter + offset))
                iteration_mappings.append(mapping)
    for (test_case, iteration_mapping) in itertools.product(models_to_test, iteration_mappings):
        if self.rank == 0:
            print(f'Running test: {test_case.name} sync interval\n                        {test_case.sync_interval} with iteration mapping\n                        {iteration_mapping}')
        self._run_uneven_inputs_test(test_case, iteration_mapping, find_unused_params='unused_params_model' in test_case.name)

def _is_of_known_loaded_module(f, module_name):
    mod = sys.modules.get(module_name, None)
