    if maybe_memo is not None:
        return maybe_memo
    if t.is_quantized:
        raise UnsupportedFakeTensorException('quantized nyi in meta tensors')
    if type(t) is torch.nn.Parameter:
        assert not make_constant
    constant = t if make_constant else None

    def mk_fake_tensor(make_meta_t: Callable[[], object], device: Union[torch.device, str]) -> FakeTensor:
        with no_dispatch():
            return FakeTensor(fake_mode, make_meta_t(), device, constant=constant)
    out = self.meta_converter(t, shape_env=shape_env, callback=mk_fake_tensor, source=source, symbolic_context=symbolic_context, trace=trace)
    if out is NotImplemented:
        raise UnsupportedFakeTensorException('meta converter nyi')
    from torch._dynamo.source import RandomValueSource
    value = None
    if not self.export and _is_plain_tensor(t) and (t.dim() == 0) and (t.device.type == 'cpu') and (t.dtype in [torch.int64, torch.int32, torch.int16, torch.int8, torch.float64]) and (source is not None) and (not isinstance(source, RandomValueSource)) and (shape_env is not None):
        from torch._dynamo.source import CallMethodItemSource, FloatTensorSource
        from torch.fx.experimental.symbolic_shapes import DimDynamic
        with no_dispatch():
            value = t.item()
        if not math.isnan(value) and (not math.isinf(value)):
            if isinstance(source, FloatTensorSource):
                item_source = source.base
            else:
                item_source = CallMethodItemSource(source)
            symbol = shape_env.create_unspecified_symbol(value, source=item_source, dynamic_dim=DimDynamic.DYNAMIC, symbolic_context=symbolic_context)
            if t.dtype == torch.int64:
                out.item_memo = shape_env.create_symintnode(symbol, hint=value, source=item_source)
            elif <MASK>:
                out.item_memo = shape_env.create_symfloatnode(symbol, hint=value, source=item_source)
    if make_constant:
        self.add_constant_storage_mapping(out)
    return out

def sign2map(a, var):
    """
    varname,ctype,atype
    init,init.r,init.i,pytype
    vardebuginfo,vardebugshowvalue,varshowvalue
    varrformat

    intent
    """
    out_a = a
    if isintent_out(var):
        for k in var['intent']:
            if k[:4] == 'out=':
                out_a = k[4:]
                break
    ret = {'varname': a, 'outvarname': out_a, 'ctype': getctype(var)}
    intent_flags = []
    for (f, s) in isintent_dict.items():
        if f(var):
            intent_flags.append(f'F2PY_{s}')
    if intent_flags:
        ret['intent'] = '|'.join(intent_flags)
    else:
        ret['intent'] = 'F2PY_INTENT_IN'
    if <MASK>:
        ret['varrformat'] = 'N'
    elif ret['ctype'] in c2buildvalue_map:
        ret['varrformat'] = c2buildvalue_map[ret['ctype']]
    else:
        ret['varrformat'] = 'O'
    (ret['init'], ret['showinit']) = getinit(a, var)
    if hasinitvalue(var) and iscomplex(var) and (not isarray(var)):
        (ret['init.r'], ret['init.i']) = markoutercomma(ret['init'][1:-1]).split('@,@')
    if isexternal(var):
        ret['cbnamekey'] = a
        if a in lcb_map:
            ret['cbname'] = lcb_map[a]
            ret['maxnofargs'] = lcb2_map[lcb_map[a]]['maxnofargs']
            ret['nofoptargs'] = lcb2_map[lcb_map[a]]['nofoptargs']
            ret['cbdocstr'] = lcb2_map[lcb_map[a]]['docstr']
            ret['cblatexdocstr'] = lcb2_map[lcb_map[a]]['latexdocstr']
        else:
            ret['cbname'] = a
            errmess('sign2map: Confused: external %s is not in lcb_map%s.\n' % (a, list(lcb_map.keys())))
    if isstring(var):
        ret['length'] = getstrlength(var)
    if isarray(var):
        ret = dictappend(ret, getarrdims(a, var))
        dim = copy.copy(var['dimension'])
    if ret['ctype'] in c2capi_map:
        ret['atype'] = c2capi_map[ret['ctype']]
        ret['elsize'] = get_elsize(var)
    if debugcapi(var):
        il = [isintent_in, 'input', isintent_out, 'output', isintent_inout, 'inoutput', isrequired, 'required', isoptional, 'optional', isintent_hide, 'hidden', iscomplex, 'complex scalar', l_and(isscalar, l_not(iscomplex)), 'scalar', isstring, 'string', isarray, 'array', iscomplexarray, 'complex array', isstringarray, 'string array', iscomplexfunction, 'complex function', l_and(isfunction, l_not(iscomplexfunction)), 'function', isexternal, 'callback', isintent_callback, 'callback', isintent_aux, 'auxiliary']
        rl = []
        for i in range(0, len(il), 2):
            if il[i](var):
                rl.append(il[i + 1])
        if isstring(var):
            rl.append(f"slen({a})={ret['length']}")
        if isarray(var):
            ddim = ','.join(map(lambda x, y: f'{x}|{y}', var['dimension'], dim))
            rl.append(f'dims({ddim})')
        if isexternal(var):
            ret['vardebuginfo'] = f"debug-capi:{a}=>{ret['cbname']}:{','.join(rl)}"
        else:
            ret['vardebuginfo'] = 'debug-capi:%s %s=%s:%s' % (ret['ctype'], a, ret['showinit'], ','.join(rl))
        if isscalar(var):
            if ret['ctype'] in cformat_map:
                ret['vardebugshowvalue'] = f"debug-capi:{a}={cformat_map[ret['ctype']]}"
        if isstring(var):
            ret['vardebugshowvalue'] = 'debug-capi:slen(%s)=%%d %s=\\"%%s\\"' % (a, a)
        if isexternal(var):
            ret['vardebugshowvalue'] = f'debug-capi:{a}=%p'
    if ret['ctype'] in cformat_map:
        ret['varshowvalue'] = f"#name#:{a}={cformat_map[ret['ctype']]}"
        ret['showvalueformat'] = f"{cformat_map[ret['ctype']]}"
    if isstring(var):
        ret['varshowvalue'] = '#name#:slen(%s)=%%d %s=\\"%%s\\"' % (a, a)
    (ret['pydocsign'], ret['pydocsignout']) = getpydocsign(a, var)
    if hasnote(var):
        ret['note'] = var['note']
    return ret

def is_gemm_like(node: Optional[Union[IRNode, Operation]]) -> bool:
    if node is None:
        return False
    if <MASK>:
        return True
    if (python_kernel_name := getattr(node, 'python_kernel_name', None)) and 'extern_kernels' in python_kernel_name:
        return True
    return False

def run_cuda_only(func: _F) -> _F:
    """Execute the decorated test only if a GPU is available.

  This function is intended to be applied to tests that require the presence
  of a CUDA GPU. If a CUDA GPU is absent, it will simply be skipped.

  Args:
    func: function to be annotated.

  Returns:
    Returns a function that will conditionally skip the decorated test method.
  """
    if tf_inspect.isclass(func):
        raise ValueError('`run_cuda_only` only supports test methods.')

    def decorated(self: 'TensorFlowTestCase', *args, **kwargs):
        if <MASK>:
            self.skipTest('Test requires CUDA GPU')
        return func(self, *args, **kwargs)
    return decorated

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name == '__getitem__':
        if <MASK>:
            raise_args_mismatch(tx, name, '1 args', f'{len(args)} args')
        if args[0] in self:
            return self.getitem_const(tx, args[0])
        elif self.default_factory is None:
            raise KeyError(f'{args[0]}')
        else:
            default_var = self.default_factory.call_function(tx, [], {})
            super().call_method(tx, '__setitem__', (args[0], default_var), kwargs)
            return default_var
    else:
        return super().call_method(tx, name, args, kwargs)

def process_ir_type(typ: Type, properties: LazyIrProperties, *, symint: bool) -> BaseCType | VectorCType | OptionalCType | ListCType:
    """
    This function takes a type from NativeFunctions and converts it for use with
    lazy tensor codegen.

    Type conversion for lazy currently consists of
     (1) changing at::Tensors into lazy::Values
     (2) wrapping everything in a BaseCType
     (3) making cpp-reference types into cpp-value types (e.g. vector instead of IntArrayRef)

    (1) converts at::Tensors to lazy::Values (which wrap lazy::Nodes, with which Lazy IR represents tensors.)
    There is special handling for Optional[Tensor] or list[Tensor], etc- hence 'tensor-like'

    This is incomplete- there are assertions in places that it's expected to need to add
    more types as the codegen is used with more operators.
    """
    if isinstance(typ, BaseType):
        if typ.name == BaseTy.Tensor:
            return BaseCType(getValueT())
        elif typ.name == BaseTy.Scalar:
            if properties.TreatScalarsAsConstants:
                return BaseCType(scalarT)
            return BaseCType(getValueT())
        elif typ.name == BaseTy.ScalarType:
            return BaseCType(scalarTypeT)
        elif typ.name == BaseTy.int:
            return BaseCType(longT)
        elif typ.name == BaseTy.SymInt:
            if symint:
                return BaseCType(getValueT())
            else:
                return BaseCType(longT)
        elif typ.name == BaseTy.bool:
            return BaseCType(boolT)
        elif typ.name == BaseTy.float:
            return BaseCType(doubleT)
        elif typ.name == BaseTy.str:
            return BaseCType(stringT)
        elif typ.name == BaseTy.Device:
            return BaseCType(deviceT)
        elif <MASK>:
            return BaseCType(generatorT)
        elif typ.name == BaseTy.Layout:
            return BaseCType(layoutT)
        elif typ.name == BaseTy.MemoryFormat:
            return BaseCType(memoryFormatT)
        else:
            raise AssertionError(f'TODO add support for type {repr(typ)}')
    elif isinstance(typ, OptionalType):
        return OptionalCType(process_ir_type(typ.elem, properties, symint=symint))
    elif isinstance(typ, ListType):
        if str(typ.elem) == 'Tensor?':
            return ListCType(OptionalCType(BaseCType(getValueT())))
        elif str(typ.elem) == 'Tensor':
            return BaseCType(tensorListValueT)
        elif typ.elem == BaseType(BaseTy.SymInt):
            return VectorCType(BaseCType(longT))
        else:
            return VectorCType(process_ir_type(typ.elem, properties, symint=symint))
    else:
        raise AssertionError(f'unrecognized type {repr(typ)}')

@register_graph_pattern(CallFunction(torch.cat, getitem_split, dim=Ignored(), _users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('mutate_cat_pass'))
def mutate_cat_node(match: Match, split_sections: list[int], dim: int):
    if not isinstance(split_sections, (list, tuple)):
        return
    graph = match.graph
    split_node = next((node for node in match.nodes if node.target == torch.split))
    (_split_input, _split_size, split_dim) = _get_split_args_default(split_node)
    next_users = find_next_users(split_node)
    for cat_user in next_users:
        if cat_user.target == torch.cat:
            cat_dim = get_arg_value(cat_user, 1, 'dim') or 0
            if split_dim != cat_dim or not has_same_parent_node(cat_user):
                continue
            (indices, idx_to_getitem) = ([], {})
            for getitem in cat_user.args[0]:
                indices.append(getitem.args[1])
                idx_to_getitem[getitem.args[1]] = getitem
            if not is_sorted_and_consecutive(indices):
                continue
            if len(split_sections) == len(cat_user.args[0]):
                cat_user.replace_all_uses_with(split_node.args[0])
                graph.erase_node(cat_user)
                counters[backend]['mutate_cat_pass'] += 1
            elif is_node_meta_valid(split_node.args[0]):
                start_fused_size = calculate_fused_tensor_size(split_node, list(range(indices[0])))
                end_fused_size = start_fused_size + calculate_fused_tensor_size(split_node, indices)
                slice_list = []
                for i in range(len(split_node.args[0].meta['example_value'].shape)):
                    if <MASK>:
                        slice_list.append(slice(None, None, None))
                    else:
                        slice_list.append(slice(start_fused_size, end_fused_size, None))
                with graph.inserting_after(split_node):
                    slice_node = graph.call_function(operator.getitem, args=(split_node.args[0], tuple(slice_list)))
                    cat_user.replace_all_uses_with(slice_node)
                    slice_node.meta.update(cat_user.meta)
                graph.erase_node(cat_user)
                counters[backend]['mutate_cat_pass'] += 1

def _save(self, name, content):
    full_path = self.path(name)
    directory = os.path.dirname(full_path)
    try:
        if self.directory_permissions_mode is not None:
            old_umask = os.umask(511 & ~self.directory_permissions_mode)
            try:
                os.makedirs(directory, self.directory_permissions_mode, exist_ok=True)
            finally:
                os.umask(old_umask)
        else:
            os.makedirs(directory, exist_ok=True)
    except FileExistsError:
        raise FileExistsError('%s exists and is not a directory.' % directory)
    while True:
        try:
            if hasattr(content, 'temporary_file_path'):
                file_move_safe(content.temporary_file_path(), full_path, allow_overwrite=self._allow_overwrite)
            else:
                open_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_BINARY', 0)
                if self._allow_overwrite:
                    open_flags = open_flags & ~os.O_EXCL | os.O_TRUNC
                fd = os.open(full_path, open_flags, 438)
                _file = None
                try:
                    locks.lock(fd, locks.LOCK_EX)
                    for chunk in content.chunks():
                        if _file is None:
                            mode = 'wb' if isinstance(chunk, bytes) else 'wt'
                            _file = os.fdopen(fd, mode)
                        _file.write(chunk)
                finally:
                    locks.unlock(fd)
                    if <MASK>:
                        _file.close()
                    else:
                        os.close(fd)
        except FileExistsError:
            name = self.get_available_name(name)
            full_path = self.path(name)
        else:
            break
    if self.file_permissions_mode is not None:
        os.chmod(full_path, self.file_permissions_mode)
    name = os.path.relpath(full_path, self.location)
    self._ensure_location_group_id(full_path)
    return str(name).replace('\\', '/')

def set_element(root_dict: STATE_DICT_TYPE, path: OBJ_PATH, value: STATE_DICT_ITEM) -> None:
    """Set ``value`` in ``root_dict`` along the ``path`` object path."""
    cur_container = cast(CONTAINER_TYPE, root_dict)

    def extend_list(lst: list[STATE_DICT_ITEM], idx: int) -> None:
        while len(lst) <= idx:
            lst.append(None)
    for i in range(1, len(path)):
        prev_key = path[i - 1]
        key = path[i]
        def_val = cast(STATE_DICT_ITEM, {} if type(key) is str else [])
        if isinstance(cur_container, Mapping):
            cur_container = cast(CONTAINER_TYPE, cur_container.setdefault(prev_key, def_val))
        else:
            extend_list(cur_container, prev_key)
            if <MASK>:
                cur_container[prev_key] = def_val
            cur_container = cur_container[prev_key]
    key = path[-1]
    if type(key) is int:
        extend_list(cast(list[STATE_DICT_ITEM], cur_container), key)
    cur_container[key] = value

def create_tensor_data(dtype, shape, min_value=-100, max_value=100):
    """Build tensor data spreading the range [min_value, max_value)."""
    if dtype in MAP_TF_TO_NUMPY_TYPE:
        dtype = MAP_TF_TO_NUMPY_TYPE[dtype]
    if dtype in (tf.float32, tf.float16, tf.float64):
        value = (max_value - min_value) * np.random.random_sample(shape) + min_value
    elif dtype in (tf.complex64, tf.complex128):
        real = (max_value - min_value) * np.random.random_sample(shape) + min_value
        imag = (max_value - min_value) * np.random.random_sample(shape) + min_value
        value = real + imag * 1j
    elif dtype in (tf.uint32, tf.int32, tf.uint8, tf.int8, tf.int64, tf.uint16, tf.int16):
        value = np.random.randint(min_value, max_value + 1, shape)
    elif dtype == tf.bool:
        value = np.random.choice([True, False], size=shape)
    elif <MASK>:
        letters = list(string.ascii_uppercase)
        return np.random.choice(letters, size=shape).astype(dtype)
    elif dtype == tf.bfloat16:
        value = (max_value - min_value) * np.random.random_sample(shape) + min_value
        dtype = ml_dtypes.bfloat16
    else:
        raise ValueError('Unsupported dtype: %s' % dtype)
    return np.dtype(dtype).type(value) if np.isscalar(value) else value.astype(dtype)

def wrap_symint(self, value, dynamism: Optional[DimDynamic]=None, context: Optional[SymIntSymbolicContext]=None):
    assert type(value) is int
    if self.name in self.tx.output.unspec_variable_map:
        return self.tx.output.unspec_variable_map[self.name]
    shape_env = self.tx.output.shape_env
    if TracingContext.get().force_unspec_int_unbacked_size_like:
        wrapped_value = shape_env.create_unbacked_symint()
        _constrain_range_for_size(wrapped_value)
        self.tx.output.tracked_fakes.append(TrackedFake(wrapped_value, self.source, None))
    elif not is_constant_source(self.get_source()):
        if dynamism is None and torch._dynamo.config.specialize_int:
            self.install_guards(GuardBuilder.CONSTANT_MATCH)
            return ConstantVariable.create(value=value, source=self.source)
        name = self.source.name()
        frame_state_entry = process_automatic_dynamic(self.tx, name, FrameStateSizeEntry.make_scalar(value), is_unspecialized_nn_module=self.source.guard_source().is_unspecialized_nn_module())
        normalized_source_name = normalize_source_name(self.source.name())
        base_source = self.source
        if isinstance(base_source, ChainedSource):
            base_source = base_source.get_base()
        if <MASK>:
            dynamic_dim = dynamism
        elif config.automatic_dynamic_shapes and frame_state_entry.scalar is auto_dynamic:
            set_feature_use('dynamo.automatic_dynamic_shapes', True)
            dynamic_dim = get_automatic_dynamic_shapes_mark_as()
        elif isinstance(base_source, LocalSource) and base_source.dynamism is not None and dict(base_source.dynamism).get(normalized_source_name, {0: False})[0] or not config.assume_static_by_default:
            dynamic_dim = DimDynamic.DYNAMIC
        else:
            if frame_state_entry.scalar is auto_dynamic:
                set_feature_use('dynamo.automatic_dynamic_shapes', False)
            self.install_guards(GuardBuilder.CONSTANT_MATCH)
            return ConstantVariable.create(value=value)
        wrapped_value = shape_env.create_unspecified_symint_and_symbol(value, source=self.source, dynamic_dim=dynamic_dim)
        self.tx.output.tracked_fakes.append(TrackedFake(wrapped_value, self.source, context))
    else:
        assert is_constant_source(self.get_source())
        self.install_guards(GuardBuilder.CONSTANT_MATCH)
        return ConstantVariable.create(value=value, source=self.source)
    assert not isinstance(self.get_source(), RandomValueSource)
    install_guard(self.get_source().make_guard(GuardBuilder.TYPE_MATCH))
    options = {'source': self.get_source()}
    proxy = self.tx.output.root_tracer.create_graph_input(re.sub('[^a-zA-Z0-9]+', '_', self.name), type(wrapped_value), wrapped_value, source=self.get_source())
    sym_expr = wrapped_value.node.expr
    assert isinstance(sym_expr, sympy.Symbol), f'{sym_expr} is not a basic Symbol.'
    self.tx.output.root_tracer.bound_symbols[sym_expr] = proxy
    unspec_var = SymNodeVariable(proxy, wrapped_value, **options)
    self.tx.output.unspec_variable_map[self.name] = unspec_var
    if not is_constant_source(self.get_source()):
        proxy.node.meta['grapharg'] = GraphArg(self.get_source(), wrapped_value, pass_arg_as_tensor=False, fake_tensor=None, is_tensor=False, example_strong_ref=wrapped_value)
    return unspec_var

def create_micro_gemm(name, m, n, k, input_dtype, input2_dtype, output_dtype=None, compute_dtype=None, alpha=1, num_threads=-1, use_ref=True, q_group_size=None) -> Optional[CppMicroGemm]:
    """
    Based on the provided info, try to find the config of the micro-kernel that would
    deliver the best performance in terms of lower latency for this case.
    """

    def create_from_config(cls, config: CppMicroGemmConfig):
        return cls(name, config.input_dtype, config.input2_dtype, config.output_dtype, config.compute_dtype, config.register_blocking, alpha)

    def skip_amx_kernel_for_woq(dynamic_M):
        if dynamic_M or input_dtype != torch.bfloat16 or input2_dtype not in [torch.int8, torch.uint8]:
            return False
        m_threshold = 5
        return m < m_threshold
    assert isinstance(n, int) or n.is_number, n
    assert isinstance(k, int) or k.is_number, k
    from ..utils import has_free_symbols
    dynamic_M = has_free_symbols((m,))
    m = V.graph.sizevars.size_hint(m, fallback=1) if dynamic_M else m
    assert isinstance(m, int) or m.is_number, m
    if output_dtype is None:
        output_dtype = input_dtype
    if compute_dtype is None:
        compute_dtype = output_dtype
    if num_threads < 0:
        num_threads = parallel_num_threads()
    vec_isa = pick_vec_isa()
    matched_configs = []
    for (cls, configs) in micro_gemm_configs.items():
        for config in configs:
            if not issubclass(vec_isa.__class__, config.vec_isa_cls):
                continue
            if config.input_dtype == input_dtype and config.compute_dtype == compute_dtype and (config.input2_dtype == input2_dtype) and (config.output_dtype == output_dtype):
                if config.extra_check is not None and (not config.extra_check(config, m, n, k, alpha, num_threads, dynamic_M=dynamic_M, q_group_size=q_group_size, vec_isa=vec_isa)):
                    continue
                (block_m, block_n, block_k) = config.register_blocking
                if <MASK>:
                    continue
                isa_score = 0
                if config.vec_isa_cls == VecAMX:
                    isa_score += 1
                dividable_score = 0
                if m % block_m == 0:
                    dividable_score += 1
                if n % block_n == 0:
                    dividable_score += 1
                if k % block_k == 0:
                    dividable_score += 1
                occupancy_score = 0
                n_blocks = (n + block_n - 1) // block_n
                total_mxn_blocks = n_blocks * ((m + block_m - 1) // block_m)
                if n_blocks >= num_threads:
                    occupancy_score += 1
                if total_mxn_blocks >= num_threads:
                    occupancy_score += 1
                register_bytes = block_m * block_n * config.compute_dtype.itemsize + (block_m * block_k + block_k * block_n) * config.input_dtype.itemsize
                size_score = register_bytes
                if occupancy_score == 0:
                    size_score = 0 - register_bytes
                matched_configs.append(((isa_score, dividable_score, occupancy_score, size_score), cls, config))
    if len(matched_configs) == 0:
        if use_ref:
            return CppMicroGemmRef(name, input_dtype, input2_dtype, output_dtype, compute_dtype, alpha)
        else:
            return None
    return create_from_config(*max(matched_configs, key=operator.itemgetter(0))[1:])

@staticmethod
def backward(ctx, grad_output):
    if dist.get_backend(group=ctx.group) is dist.Backend.NCCL:
        world_size = dist.get_world_size(group=ctx.group)
        out_size = list(grad_output.size())
        if <MASK>:
            raise RuntimeError(f'Tensor with dimensions: {out_size} does not have first dimension divisible by world_size: {world_size}')
        out_size[0] = out_size[0] // dist.get_world_size(group=ctx.group)
        gx = torch.empty(out_size, device=grad_output.device, dtype=grad_output.dtype)
        dist._reduce_scatter_base(gx, grad_output, ReduceOp.SUM, ctx.group)
    else:
        raise RuntimeError('Backend not supported!')
    return (None, gx, None)

def __iter__(self):
    db = self.queryset.db
    query = self.queryset.query
    connection = connections[db]
    compiler = connection.ops.compiler('SQLCompiler')(query, connection, db)
    query_iterator = iter(query)
    try:
        (model_init_names, model_init_pos, annotation_fields) = self.queryset.resolve_model_init_order()
        model_cls = self.queryset.model
        if <MASK>:
            raise exceptions.FieldDoesNotExist('Raw query must include the primary key')
        fields = [self.queryset.model_fields.get(c) for c in self.queryset.columns]
        cols = [f.get_col(f.model._meta.db_table) if f else None for f in fields]
        converters = compiler.get_converters(cols)
        if converters:
            query_iterator = compiler.apply_converters(query_iterator, converters)
        if compiler.has_composite_fields(cols):
            query_iterator = compiler.composite_fields_to_tuples(query_iterator, cols)
        fetch_mode = self.queryset._fetch_mode
        peers = []
        for values in query_iterator:
            model_init_values = [values[pos] for pos in model_init_pos]
            instance = model_cls.from_db(db, model_init_names, model_init_values, fetch_mode=fetch_mode)
            if fetch_mode.track_peers:
                peers.append(weak_ref(instance))
                instance._state.peers = peers
            if annotation_fields:
                for (column, pos) in annotation_fields:
                    setattr(instance, column, values[pos])
            yield instance
    finally:
        if hasattr(query, 'cursor') and query.cursor:
            query.cursor.close()

def track_tensor_tree(inner_res: T, proxy_res: _NestedProxys, *, constant: Optional[_NestedTensors], tracer: _ProxyTracer) -> T:
    _set_unbacked_bindings(inner_res, proxy_res)

    def wrap_with_proxy(e: object, proxy: _NestedProxys, constant: Optional[_NestedTensors]) -> None:
        if isinstance(e, Tensor):
            assert isinstance(proxy, Proxy)
            assert constant is None or isinstance(constant, Tensor)
            track_tensor(e, proxy, tracer=tracer, constant=constant)
            set_meta(proxy, e)
        elif <MASK>:
            assert isinstance(proxy, Proxy)
            set_meta(proxy, e)
            set_proxy_slot(e, tracer, thunkify(tracer, lambda : proxy))
        elif isinstance(e, _AnyScriptObject):
            assert isinstance(proxy, Proxy)
            set_proxy_slot(e, tracer, proxy)
            set_meta(proxy, e)
        elif isinstance(e, (tuple, list)):
            if isinstance(proxy, fx.Proxy):
                set_meta(proxy, e)

            def get_constant(c: Optional[_NestedTensors], idx: int) -> Optional[_NestedTensors]:
                if c is None:
                    return None
                else:
                    assert isinstance(c, (list, tuple))
                    return c[idx]
            for (idx, ee) in enumerate(e):
                wrap_with_proxy(ee, proxy[idx], get_constant(constant, idx))
        elif isinstance(e, dict):
            assert constant is None
            if isinstance(proxy, fx.Proxy):
                set_meta(proxy, e)
            for (key, val) in e.items():
                wrap_with_proxy(val, proxy[key], None)
        elif isinstance(e, BackwardState):
            assert isinstance(proxy, Proxy)
            set_meta(proxy, e)
            e.proxy = proxy
        else:
            pass
    wrap_with_proxy(inner_res, proxy_res, constant)
    return inner_res

def _replace_literals_with_existing_placeholders(gm: torch.fx.GraphModule, exclude_literals: Optional[list[Any]]=None, literal_to_ph_idx: Optional[dict[Union[float, int, bool, torch.dtype], int]]=None):
    """Replace the literals in the graph with **existing** placeholder nodes, so that the literal arguments
    in the graph can be matched and replaced

    To use this, all literal args in the graph should be unique and each of them should correspond
    to exactly one placeholder node

    # 1. Original Graph
    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        return torch.dequantize_per_tensor(x_i8, scale, zero_point, quant_min, quant_max)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        x_i8 = torch.clamp(x_i8, quant_min, quant_max)
        return ((x_i8.to(torch.float32) - zero_point) * scale).to(dtype=torch.float32)

    example_inputs = (
        torch.randn(1, 3, 3, 3),
        1.0,
        0,
        -128,
        127,
    )
    pattern_gm = _get_aten_graph_module_for_pattern(pattern, example_inputs)
    replacement_gm = _get_aten_graph_module_for_pattern(pattern, example_inptus)

    # 2. Before calling replace literals we'll see the following graph:
    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        return torch.dequantize_per_tensor(x_i8, 1.0, 0, -128, 127)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        x_i8 = torch.clamp(x_i8, -128, 127)
        return ((x_i8.to(torch.float32) - 0) * 1.0).to(dtype=torch.float32)

    # Note that literal args appear in different order in pattern and replacement graph, so
    # we can't use _replace_literals_with_new_placeholders

    literal_to_ph_idx = {1.0: 1, 0: 2, -128: 3, 127: 4}
    pattern_gm = _replace_literals_with_existing_placeholders(pattern_gm, literal_to_ph_idx)
    replacement_gm = _replace_literals_with_existing_placeholders(replacement_gm, literal_to_ph_idx)

    # 3. After replacing literals with existing placeholder nodes

    def pattern(self, x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        return torch.dequantize_per_tensor(x_i8, scale, zero_point, quant_min, quant_max)

    def replacement(x_i8, scale, zero_point, quant_min, quant_max):
        # scale/zero_point/quant_min/quant_max are burnt in since they are scalar values
        x_i8 = torch.clamp(x_i8, quant_min, quant_max)
        return ((x_i8.to(torch.float32) - zero_point) * scale).to(dtype=torch.float32)
    """
    if exclude_literals is None:
        exclude_literals = []
    if literal_to_ph_idx is None:
        literal_to_ph_idx = {}
    phs = [node for node in gm.graph.nodes if node.op == 'placeholder']
    for node in gm.graph.nodes:
        if node.op != 'call_function':
            continue
        new_args = []
        for arg in node.args:
            if <MASK>:
                ph_idx = literal_to_ph_idx[arg]
                ph_node = phs[ph_idx]
                new_args.append(ph_node)
            else:
                new_args.append(arg)
        new_args = tuple(new_args)
        node.args = new_args
    return gm

def standardize_weights(y, sample_weight=None, class_weight=None, sample_weight_mode=None):
    """Performs sample weight validation and standardization.

  Everything gets normalized to a single sample-wise (or timestep-wise)
  weight array. If both `sample_weight` and `class_weight` are provided,
  the weights are multiplied.

  Args:
      y: Numpy array or Tensor of model targets to be weighted.
      sample_weight: User-provided `sample_weight` argument.
      class_weight: User-provided `class_weight` argument.
      sample_weight_mode: One of `None` or `"temporal"`. `"temporal"` indicated
        that we expect 2D weight data that will be applied to the last 2
        dimensions of the targets (i.e. we are weighting timesteps, not
        samples).

  Returns:
      A numpy array of target weights, one entry per sample to weight.

  Raises:
      ValueError: In case of invalid user-provided arguments.
  """
    if isinstance(sample_weight, tuple):
        sample_weight = sample_weight[0]
    if sample_weight_mode is not None and sample_weight_mode != 'samplewise':
        if sample_weight_mode != 'temporal':
            raise ValueError('"sample_weight_mode should be None or "temporal". Found: ' + str(sample_weight_mode))
        if <MASK>:
            raise ValueError('Found a sample_weight array for an input with shape ' + str(y.shape) + '. Timestep-wise sample weighting (use of sample_weight_mode="temporal") is restricted to outputs that are at least 3D, i.e. that have a time dimension.')
        if sample_weight is not None and len(sample_weight.shape) != 2:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + '. In order to use timestep-wise sample weighting, you should pass a 2D sample_weight array.')
    elif sample_weight is not None and len(sample_weight.shape) != 1:
        raise ValueError('Found a sample_weight array with shape {}. In order to use timestep-wise sample weights, you should specify sample_weight_mode="temporal" in compile(); founssd "{}" instead. If you just mean to use sample-wise weights, make sure your sample_weight array is 1D.'.format(sample_weight.shape, sample_weight_mode))
    if sample_weight is not None:
        if len(sample_weight.shape) > len(y.shape):
            raise ValueError('Found a sample_weight with shape' + str(sample_weight.shape) + '.Expected sample_weight with rank less than or equal to ' + str(len(y.shape)))
        if not tensor_util.is_tf_type(sample_weight) and y.shape[:sample_weight.ndim] != sample_weight.shape:
            raise ValueError('Found a sample_weight array with shape ' + str(sample_weight.shape) + ' for an input with shape ' + str(y.shape) + '. sample_weight cannot be broadcast.')
    class_sample_weight = None
    if isinstance(class_weight, dict):
        if len(y.shape) > 2:
            raise ValueError('`class_weight` not supported for 3+ dimensional targets.')
        if tensor_util.is_tf_type(y):
            keys = np.array(sorted(class_weight.keys()))
            values = np.array([class_weight[i] for i in keys])
            weight_vector = np.zeros(np.max(keys) + 1)
            weight_vector[:] = np.nan
            weight_vector[keys] = values
            y_classes = smart_cond.smart_cond(len(y.shape.as_list()) == 2 and backend.shape(y)[1] > 1, lambda : backend.argmax(y, axis=1), lambda : math_ops.cast(backend.reshape(y, (-1,)), dtypes.int64))
            class_sample_weight = array_ops.gather(weight_vector, y_classes)
            gen_array_ops.check_numerics(class_sample_weight, 'Invalid classes or class weights detected. NaN values indicate that an appropriate class weight could not be determined.')
            class_sample_weight = math_ops.cast(class_sample_weight, backend.floatx())
            if sample_weight is not None:
                sample_weight = math_ops.cast(tensor_conversion.convert_to_tensor_v2_with_dispatch(sample_weight), backend.floatx())
        else:
            y_classes = y
            if len(y.shape) == 2:
                if y.shape[1] > 1:
                    y_classes = np.argmax(y, axis=1)
                elif y.shape[1] == 1:
                    y_classes = np.reshape(y, y.shape[0])
            class_sample_weight = numpy_compat.np_asarray([class_weight[cls] for cls in y_classes if cls in class_weight])
            if len(class_sample_weight) != len(y_classes):
                existing_classes = set(y_classes)
                existing_class_weight = set(class_weight.keys())
                raise ValueError('`class_weight` must contain all classes in the data. The classes %s exist in the data but not in `class_weight`.' % (existing_classes - existing_class_weight))
    if class_sample_weight is not None and sample_weight is not None:
        return class_sample_weight * sample_weight
    if sample_weight is not None:
        return sample_weight
    if class_sample_weight is not None:
        return class_sample_weight
    return None

def __eq__(self, other):
    if <MASK>:
        return True
    elif isinstance(other, VariableAggregation):
        return int(self.value) == int(other.value)
    else:
        return False

def _check_mode(mode, encoding, newline):
    """Check mode and that encoding and newline are compatible.

    Parameters
    ----------
    mode : str
        File open mode.
    encoding : str
        File encoding.
    newline : str
        Newline for text files.

    """
    if 't' in mode:
        if 'b' in mode:
            raise ValueError(f'Invalid mode: {mode!r}')
    else:
        if encoding is not None:
            raise ValueError("Argument 'encoding' not supported in binary mode")
        if <MASK>:
            raise ValueError("Argument 'newline' not supported in binary mode")

def func(*args, **kw):
    """Updates the `_metadata_request` attribute of the consumer (`instance`)
            for the parameters provided as `**kw`.

            This docstring is overwritten below.
            See REQUESTER_DOC for expected functionality.
            """
    if not _routing_enabled():
        raise RuntimeError('This method is only available when metadata routing is enabled. You can enable it using sklearn.set_config(enable_metadata_routing=True).')
    if self.validate_keys and set(kw) - set(self.keys):
        raise TypeError(f'Unexpected args: {set(kw) - set(self.keys)} in {self.name}. Accepted arguments are: {set(self.keys)}')
    if <MASK>:
        _instance = args[0]
        args = args[1:]
    else:
        _instance = instance
    if args:
        raise TypeError(f'set_{self.name}_request() takes 0 positional argument but {len(args)} were given')
    requests = _instance._get_metadata_request()
    method_metadata_request = getattr(requests, self.name)
    for (prop, alias) in kw.items():
        if alias is not UNCHANGED:
            method_metadata_request.add_request(param=prop, alias=alias)
    _instance._metadata_request = requests
    return _instance

@simple_wraps(fn)
def _functionalized_f_helper(*args: list[FxValue]) -> tuple[tuple[list[FxValue], list[Tensor]], list[Optional[AOTOutput]]]:
    with maybe_enable_thunkify():
        disable_above = torch._C._ExcludeDispatchKeyGuard(torch._C.DispatchKeySet(torch._C.DispatchKey.Functionalize))
        with disable_above:
            f_args = pytree.tree_map(to_fun, args)
            if trace_joint and has_input_mutated_in_graph and joint_fn_handle:

                def _post_forward(primals):
                    nonlocal primals_after_forward
                    primals_after_forward = pytree.tree_map(from_fun, primals)
                    nonlocal f_args_after_forward
                    f_args_after_forward = f_args[0]
                    nonlocal f_args_mutation_counters_after_forward
                    f_args_mutation_counters_after_forward = [MutationCounters(-1, -1, -1) if not inputs_mutated_in_graph[i] else _get_mutation_counters(f_arg) for (i, f_arg) in enumerate(f_args_after_forward)]
                joint_fn_handle.post_forward = _post_forward
            (f_outs, f_outs_descs) = call_and_expect_output_descs(fn, f_args)
        if trace_joint:
            assert isinstance(args, tuple) and len(args) == 2 and isinstance(args[0], (list, tuple))
            primals_before = args[0]
            primals_after = pytree.tree_map(from_fun, f_args[0])
            for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args[0], primals_before, primals_after, meta.input_info)):
                joint_mutates_data = has_data_mutation(f_inpt)
                joint_mutates_metadata = has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False)
                if <MASK>:
                    assert not joint_mutates_metadata, 'Found a graph input that had its metadata mutated in the backward. This is not supported'
                if not inpt_info.mutation_inductor_storage_resize:
                    assert not was_inductor_storage_resized(f_inpt), 'Found a graph input that had storage resizing in the backward. This is not supported'
                if joint_mutates_data and (not inpt_info.mutates_data) and (not inpt_info.mutates_storage_metadata):
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
                    meta.indices_of_inputs_that_requires_grad_with_mutations_in_bw.append(idx)
            tangents_before = args[1]
            tangents_after = pytree.tree_map(from_fun, f_args[1])
            for (f_inpt, before, after) in zip(f_args[1], tangents_before, tangents_after):
                assert not has_metadata_mutation(f_inpt, before, check_only_storage_mutation=False), 'Found an input to the backward that had metadata mutated during the backward pass. This is not supported'
                if has_data_mutation(f_inpt):
                    can_be_in_graph = _check_if_mutation_can_be_in_graph(keep_input_mutations=True, mutates_data=True, mutates_metadata=False, mutations_hidden_from_autograd=are_all_mutations_hidden_from_autograd(f_inpt), mutations_under_no_grad_or_inference_mode=are_all_mutations_under_no_grad_or_inference_mode(f_inpt), mutates_storage_metadata=False, mutation_inductor_storage_resize=was_inductor_storage_resized(f_inpt), requires_grad=f_inpt.requires_grad)
                    assert can_be_in_graph, 'a backward input that had data mutated in an autograd-aware way. This is not supported'
                    with torch.fx.traceback.preserve_node_meta():
                        assert isinstance(before, torch.Tensor) and isinstance(after, torch.Tensor)
                        before.copy_(after)
        if aot_config.keep_inference_input_mutations:
            mcs_applied: list[MutationCounters] = [MutationCounters(0, 0, 0)] * len(meta.input_info)
            if f_args_mutation_counters_after_forward is not None:
                primals_before = args[0]
                for (idx, (f_inpt, before, after, inpt_info)) in enumerate(zip(f_args_after_forward, primals_before, primals_after_forward, meta.input_info)):
                    if inpt_info.mutation_type != MutationType.MUTATED_IN_GRAPH:
                        continue
                    mcs_after_forward = f_args_mutation_counters_after_forward[idx]
                    with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_forward(), _proxy_tensor_disable_update_tensor_tracker():
                        apply_in_graph_mutations(inpt_info, before, after, f_inpt, idx, mcs_after_forward, mcs_applied[idx])
                        mcs_applied[idx] = mcs_after_forward
            for (idx, (inpt_old, f_inpt)) in enumerate(zip(args, f_args) if not trace_joint else zip(args[0], f_args[0])):
                if not isinstance(f_inpt, torch.Tensor):
                    continue
                assert is_fun(f_inpt)
                inpt_new = from_fun(f_inpt)
                if meta.input_info[idx].mutation_type != MutationType.MUTATED_IN_GRAPH:
                    continue
                mcs: Optional[MutationCounters] = None
                if f_args_mutation_counters_after_forward is not None:
                    mcs = _get_mutation_counters(f_inpt)
                    if mcs == mcs_applied[idx]:
                        continue
                with torch.fx.traceback.preserve_node_meta(), set_partitioner_tag_must_be_in_backward():
                    apply_in_graph_mutations(meta.input_info[idx], inpt_old, inpt_new, f_inpt, idx, mcs, mcs_applied[idx])
            (flat_outs, outs_spec) = pytree.tree_flatten(f_outs)
            flat_outs = [from_fun(o) for o in flat_outs]
            num_outs = len(meta.output_info)
            for i in range(num_outs):
                info = meta.output_info[i]
                if info.output_type != OutputType.is_input:
                    continue
                assert info.base_idx is not None
                if meta.input_info[info.base_idx].mutation_type == MutationType.MUTATED_IN_GRAPH:
                    fw_args = args[0] if trace_joint else args
                    flat_outs[i] = fw_args[info.base_idx]
            return (pytree.tree_unflatten(flat_outs, outs_spec), f_outs_descs)
        return (pytree.tree_map(from_fun, f_outs), f_outs_descs)

def lookup(self, keys, name=None):
    """Looks up `keys` in the table, outputs the corresponding values.

    It assigns out-of-vocabulary keys to buckets based in their hashes.

    Args:
      keys: Keys to look up. May be either a `SparseTensor` or dense `Tensor`.
      name: Optional name for the op.

    Returns:
      A `SparseTensor` if keys are sparse, a `RaggedTensor` if keys are ragged,
      otherwise a dense `Tensor`.

    Raises:
      TypeError: when `keys` doesn't match the table key data type.
    """
    if <MASK>:
        raise TypeError(f'Dtype of argument `keys` must be {self._key_dtype}, received: {keys.dtype}')
    values = keys
    if isinstance(keys, (sparse_tensor.SparseTensor, internal.RaggedTensor)):
        values = keys.values
    if self._table and self._table.key_dtype.base_dtype == dtypes.int64:
        values = math_ops.cast(values, dtypes.int64)
    with ops.name_scope(name, '%s_Lookup' % self.name):
        buckets = string_ops.string_to_hash_bucket_fast(_as_string(values), num_buckets=self._num_oov_buckets, name='hash_bucket')
        if self._table:
            ids = self._table.lookup(values)
            buckets = math_ops.add(buckets, self._table.size())
            is_id_non_default = math_ops.not_equal(ids, self._table.default_value)
            ids = array_ops.where_v2(is_id_non_default, ids, buckets)
        else:
            ids = buckets
    if isinstance(keys, sparse_tensor.SparseTensor):
        return sparse_tensor.SparseTensor(keys.indices, ids, keys.dense_shape)
    elif isinstance(keys, internal.RaggedTensor):
        return keys.with_values(ids)
    return ids

def determine_qparams(min_val: torch.Tensor, max_val: torch.Tensor, quant_min: int, quant_max: int, dtype: torch.dtype, eps: torch.Tensor, has_customized_qrange: bool, qscheme: torch.qscheme=torch.per_tensor_affine) -> tuple[torch.Tensor, torch.Tensor]:
    """Calculates the quantization parameters, given min and max
    value tensors. Works for both per tensor and per channel cases

    Args:
        min_val: Minimum values per channel
        max_val: Maximum values per channel

    Returns:
        scales: Scales tensor of shape (#channels,)
        zero_points: Zero points tensor of shape (#channels,)
    """
    if not check_min_max_valid(min_val, max_val):
        return (torch.tensor([1.0], device=min_val.device.type), torch.tensor([0], device=min_val.device.type))
    min_val_neg = torch.min(min_val, torch.zeros_like(min_val))
    max_val_pos = torch.max(max_val, torch.zeros_like(max_val))
    device = min_val_neg.device
    scale = torch.ones(min_val_neg.size(), dtype=torch.double, device=device)
    zero_point = torch.zeros(min_val_neg.size(), dtype=torch.int64, device=device)
    eps = eps.to(device)
    if qscheme == torch.per_tensor_symmetric or qscheme == torch.per_channel_symmetric:
        max_val_pos = torch.max(-min_val_neg, max_val_pos)
        scale = max_val_pos / (float(quant_max - quant_min) / 2)
        scale = torch.max(scale, eps)
        if dtype in [torch.uint8, torch.quint8]:
            if has_customized_qrange:
                zero_point = zero_point.new_full(zero_point.size(), (quant_min + quant_max) // 2)
            else:
                zero_point = zero_point.new_full(zero_point.size(), 128)
    elif <MASK>:
        scale = (max_val - min_val) / float(quant_max - quant_min)
        scale = torch.where(scale > eps, scale, torch.ones_like(scale))
        zero_point = -1 * min_val / scale
    else:
        scale = (max_val_pos - min_val_neg) / float(quant_max - quant_min)
        scale = torch.max(scale, eps)
        zero_point = quant_min - torch.round(min_val_neg / scale).to(torch.int)
        zero_point = torch.clamp(zero_point, quant_min, quant_max)
    if len(scale.shape) == 0:
        scale = torch.tensor([float(scale)], dtype=scale.dtype, device=device)
    if len(zero_point.shape) == 0:
        zero_point = torch.tensor([int(zero_point)], dtype=zero_point.dtype, device=device)
        if qscheme == torch.per_channel_affine_float_qparams:
            zero_point = torch.tensor([float(zero_point)], dtype=zero_point.dtype, device=device)
    return (scale.to(torch.double), zero_point.to(torch.int64))

def linkcode_resolve(domain, info):
    """
    Determine the URL corresponding to Python object
    """
    if domain != 'py':
        return None
    modname = info['module']
    fullname = info['fullname']
    submod = sys.modules.get(modname)
    if <MASK>:
        return None
    obj = submod
    for part in fullname.split('.'):
        try:
            obj = getattr(obj, part)
        except Exception:
            return None
    try:
        unwrap = inspect.unwrap
    except AttributeError:
        pass
    else:
        obj = unwrap(obj)
    fn = None
    lineno = None
    if isinstance(obj, type):
        if obj.__module__ == 'numpy':
            fn = _get_c_source_file(obj)
        if hasattr(obj, '_module_source'):
            (obj.__module__, obj._module_source) = (obj._module_source, obj.__module__)
    if fn is None:
        try:
            fn = inspect.getsourcefile(obj)
        except Exception:
            fn = None
        if not fn:
            return None
        module = inspect.getmodule(obj)
        if module is not None and (not module.__name__.startswith('numpy')):
            return None
        try:
            (source, lineno) = inspect.getsourcelines(obj)
        except Exception:
            lineno = None
        fn = relpath(fn, start=dirname(numpy.__file__))
    if lineno:
        linespec = '#L%d-L%d' % (lineno, lineno + len(source) - 1)
    else:
        linespec = ''
    if isinstance(obj, type) and hasattr(obj, '_module_source'):
        (obj.__module__, obj._module_source) = (obj._module_source, obj.__module__)
    if 'dev' in numpy.__version__:
        return f'https://github.com/numpy/numpy/blob/main/numpy/{fn}{linespec}'
    else:
        return 'https://github.com/numpy/numpy/blob/v%s/numpy/%s%s' % (numpy.__version__, fn, linespec)

def _bins_to_cuts(x_idx: Index, bins: Index, right: bool=True, labels=None, precision: int=3, include_lowest: bool=False, duplicates: str='raise', ordered: bool=True):
    if <MASK>:
        raise ValueError("'labels' must be provided if 'ordered = False'")
    if duplicates not in ['raise', 'drop']:
        raise ValueError("invalid value for 'duplicates' parameter, valid options are: raise, drop")
    result: Categorical | np.ndarray
    if isinstance(bins, IntervalIndex):
        ids = bins.get_indexer(x_idx)
        cat_dtype = CategoricalDtype(bins, ordered=True)
        result = Categorical.from_codes(ids, dtype=cat_dtype, validate=False)
        return (result, bins)
    unique_bins = algos.unique(bins)
    if len(unique_bins) < len(bins) and len(bins) != 2:
        if duplicates == 'raise':
            raise ValueError(f"Bin edges must be unique: {bins!r}.\nYou can drop duplicate edges by setting the 'duplicates' kwarg")
        bins = unique_bins
    side: Literal['left', 'right'] = 'left' if right else 'right'
    try:
        ids = bins.searchsorted(x_idx, side=side)
    except TypeError as err:
        if x_idx.dtype.kind == 'm':
            raise ValueError('bins must be of timedelta64 dtype') from err
        elif x_idx.dtype.kind == bins.dtype.kind == 'M':
            raise ValueError('Cannot use timezone-naive bins with timezone-aware values, or vice-versa') from err
        elif x_idx.dtype.kind == 'M':
            raise ValueError('bins must be of datetime64 dtype') from err
        else:
            raise
    ids = ensure_platform_int(ids)
    if include_lowest:
        ids[x_idx == bins[0]] = 1
    na_mask = isna(x_idx) | (ids == len(bins)) | (ids == 0)
    has_nas = na_mask.any()
    if labels is not False:
        if not (labels is None or is_list_like(labels)):
            raise ValueError('Bin labels must either be False, None or passed in as a list-like argument')
        if labels is None:
            labels = _format_labels(bins, precision, right=right, include_lowest=include_lowest)
        elif ordered and len(set(labels)) != len(labels):
            raise ValueError('labels must be unique if ordered=True; pass ordered=False for duplicate labels')
        elif len(labels) != len(bins) - 1:
            raise ValueError('Bin labels must be one fewer than the number of bin edges')
        if not isinstance(getattr(labels, 'dtype', None), CategoricalDtype):
            labels = Categorical(labels, categories=labels if len(set(labels)) == len(labels) else None, ordered=ordered)
        np.putmask(ids, na_mask, 0)
        result = algos.take_nd(labels, ids - 1)
    else:
        result = ids - 1
        if has_nas:
            result = result.astype(np.float64)
            np.putmask(result, na_mask, np.nan)
    return (result, bins)

