        for (k, predictor) in enumerate(predictors_of_ith_iteration):
            if <MASK>:
                predict = partial(predictor.predict_binned, missing_values_bin_idx=self._bin_mapper.missing_values_bin_idx_, n_threads=n_threads)
            else:
                predict = partial(predictor.predict, known_cat_bitsets=known_cat_bitsets, f_idx_map=f_idx_map, n_threads=n_threads)
            raw_predictions[:, k] += predict(X)

def most_specific_common_supertype(self, others):
    """Returns the most specific supertype of `self` and `others`.

    Args:
      others: A Sequence of `TypeSpec`.

    Returns `None` if a supertype does not exist.
    """
    if <MASK>:
        return False
    common_shape = self._element_shape.most_specific_common_supertype((other._element_shape for other in others))
    if common_shape is None:
        return None
    if not all((self._dtype == other._dtype for other in others)):
        return None
    if not all((self._dynamic_size == other._dynamic_size for other in others)):
        return None
    infer_shape = self._infer_shape and all((other._infer_shape for other in others))
    return TensorArraySpec(common_shape, self._dtype, self._dynamic_size, infer_shape)

def import_module(self, module_name: str) -> ModuleType:
    last_err = None
    for importer in self._importers:
        if not isinstance(importer, Importer):
            raise TypeError(f'{importer} is not a Importer. All importers in OrderedImporter must inherit from Importer.')
        try:
            module = importer.import_module(module_name)
            if <MASK>:
                continue
            return module
        except ModuleNotFoundError as err:
            last_err = err
    if last_err is not None:
        raise last_err
    else:
        raise ModuleNotFoundError(module_name)

def _mask_edges_weights(mask, edges, weights=None):
    """Apply a mask to edges (weighted or not)"""
    inds = np.arange(mask.size)
    inds = inds[mask.ravel()]
    ind_mask = np.logical_and(np.isin(edges[0], inds), np.isin(edges[1], inds))
    edges = edges[:, ind_mask]
    if <MASK>:
        weights = weights[ind_mask]
    if len(edges.ravel()):
        maxval = edges.max()
    else:
        maxval = 0
    order = np.searchsorted(np.flatnonzero(mask), np.arange(maxval + 1))
    edges = order[edges]
    if weights is None:
        return edges
    else:
        return (edges, weights)

def register(fn: Callable[_P, _T]) -> Callable[_P, _T]:
    if <MASK>:
        raise RuntimeError(f'Refinement rule already registered for {call_target}!')
    _REFINEMENT_RULES[call_target] = fn
    return fn

def _cast_to_stata_types(data: DataFrame) -> DataFrame:
    """
    Checks the dtypes of the columns of a pandas DataFrame for
    compatibility with the data types and ranges supported by Stata, and
    converts if necessary.

    Parameters
    ----------
    data : DataFrame
        The DataFrame to check and convert

    Notes
    -----
    Numeric columns in Stata must be one of int8, int16, int32, float32 or
    float64, with some additional value restrictions.  int8 and int16 columns
    are checked for violations of the value restrictions and upcast if needed.
    int64 data is not usable in Stata, and so it is downcast to int32 whenever
    the value are in the int32 range, and sidecast to float64 when larger than
    this range.  If the int64 values are outside of the range of those
    perfectly representable as float64 values, a warning is raised.

    bool columns are cast to int8.  uint columns are converted to int of the
    same size if there is no loss in precision, otherwise are upcast to a
    larger type.  uint64 is currently not supported since it is concerted to
    object in a DataFrame.
    """
    ws = ''
    conversion_data: tuple[tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type]] = ((np.bool_, np.int8, np.int8), (np.uint8, np.int8, np.int16), (np.uint16, np.int16, np.int32), (np.uint32, np.int32, np.int64), (np.uint64, np.int64, np.float64))
    float32_max = struct.unpack('<f', b'\xff\xff\xff~')[0]
    float64_max = struct.unpack('<d', b'\xff\xff\xff\xff\xff\xff\xdf\x7f')[0]
    for col in data:
        is_nullable_int = isinstance(data[col].dtype, ExtensionDtype) and data[col].dtype.kind in 'iub'
        orig_missing = data[col].isna()
        if is_nullable_int:
            fv = 0 if data[col].dtype.kind in 'iu' else False
            data[col] = data[col].fillna(fv).astype(data[col].dtype.numpy_dtype)
        elif isinstance(data[col].dtype, ExtensionDtype):
            if getattr(data[col].dtype, 'numpy_dtype', None) is not None:
                data[col] = data[col].astype(data[col].dtype.numpy_dtype)
            elif is_string_dtype(data[col].dtype):
                data[col] = data[col].astype('object')
                data.loc[data[col].isna(), col] = None
        dtype = data[col].dtype
        empty_df = data.shape[0] == 0
        for c_data in conversion_data:
            if dtype == c_data[0]:
                if empty_df or data[col].max() <= np.iinfo(c_data[1]).max:
                    dtype = c_data[1]
                else:
                    dtype = c_data[2]
                if c_data[2] == np.int64:
                    if data[col].max() >= 2 ** 53:
                        ws = precision_loss_doc.format('uint64', 'float64')
                data[col] = data[col].astype(dtype)
        if dtype == np.int8 and (not empty_df):
            if data[col].max() > 100 or data[col].min() < -127:
                data[col] = data[col].astype(np.int16)
        elif dtype == np.int16 and (not empty_df):
            if data[col].max() > 32740 or data[col].min() < -32767:
                data[col] = data[col].astype(np.int32)
        elif dtype == np.int64:
            if empty_df or (data[col].max() <= 2147483620 and data[col].min() >= -2147483647):
                data[col] = data[col].astype(np.int32)
            else:
                data[col] = data[col].astype(np.float64)
                if data[col].max() >= 2 ** 53 or data[col].min() <= -2 ** 53:
                    ws = precision_loss_doc.format('int64', 'float64')
        elif dtype in (np.float32, np.float64):
            if np.isinf(data[col]).any():
                raise ValueError(f'Column {col} contains infinity or -infinitywhich is outside the range supported by Stata.')
            value = data[col].max()
            if dtype == np.float32 and value > float32_max:
                data[col] = data[col].astype(np.float64)
            elif dtype == np.float64:
                if value > float64_max:
                    raise ValueError(f'Column {col} has a maximum value ({value}) outside the range supported by Stata ({float64_max})')
        if is_nullable_int:
            if <MASK>:
                sentinel = StataMissingValue.BASE_MISSING_VALUES[data[col].dtype.name]
                data.loc[orig_missing, col] = sentinel
    if ws:
        warnings.warn(ws, PossiblePrecisionLoss, stacklevel=find_stack_level())
    return data

def inverse(self, raw_prediction, out=None):
    if <MASK>:
        return softmax(raw_prediction, copy=True)
    else:
        np.copyto(out, raw_prediction)
        softmax(out, copy=False)
        return out

@bottleneck_switch()
def nanmedian(values: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, mask=None) -> float | np.ndarray:
    """
    Parameters
    ----------
    values : ndarray
    axis : int, optional
    skipna : bool, default True
    mask : ndarray[bool], optional
        nan-mask if known

    Returns
    -------
    result : float | ndarray
        Unless input is a float array, in which case use the same
        precision as the input array.

    Examples
    --------
    >>> from pandas.core import nanops
    >>> s = pd.Series([1, np.nan, 2, 2])
    >>> nanops.nanmedian(s.values)
    2.0

    >>> s = pd.Series([np.nan, np.nan, np.nan])
    >>> nanops.nanmedian(s.values)
    nan
    """
    using_nan_sentinel = values.dtype.kind == 'f' and mask is None

    def get_median(x: np.ndarray, _mask=None):
        if <MASK>:
            _mask = notna(x)
        else:
            _mask = ~_mask
        if not skipna and (not _mask.all()):
            return np.nan
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
            warnings.filterwarnings('ignore', 'Mean of empty slice', RuntimeWarning)
            res = np.nanmedian(x[_mask])
        return res
    dtype = values.dtype
    (values, mask) = _get_values(values, skipna, mask=mask, fill_value=None)
    if values.dtype.kind != 'f':
        if values.dtype == object:
            inferred = lib.infer_dtype(values)
            if inferred in ['string', 'mixed']:
                raise TypeError(f'Cannot convert {values} to numeric')
        try:
            values = values.astype('f8')
        except ValueError as err:
            raise TypeError(str(err)) from err
    if not using_nan_sentinel and mask is not None:
        if not values.flags.writeable:
            values = values.copy()
        values[mask] = np.nan
    notempty = values.size
    res: float | np.ndarray
    if values.ndim > 1 and axis is not None:
        if notempty:
            if not skipna:
                res = np.apply_along_axis(get_median, axis, values)
            else:
                with warnings.catch_warnings():
                    warnings.filterwarnings('ignore', 'All-NaN slice encountered', RuntimeWarning)
                    if values.shape[1] == 1 and axis == 0 or (values.shape[0] == 1 and axis == 1):
                        res = np.nanmedian(np.squeeze(values), keepdims=True)
                    else:
                        res = np.nanmedian(values, axis=axis)
        else:
            res = _get_empty_reduction_result(values.shape, axis)
    else:
        res = get_median(values, mask) if notempty else np.nan
    return _wrap_results(res, dtype)

@wraps(func)
def wrapped(*args, **kwargs):
    try:
        func_level = _func_increment_nesting(reapply_views)
        func_args = _wrap_all_tensors_to_functional(args, func_level)
        func_kwargs = _wrap_all_tensors_to_functional(kwargs, func_level)
        flattened_unwrapped_args = pytree.arg_tree_leaves(*args)
        flattened_wrapped_args = pytree.arg_tree_leaves(*func_args)
        flattened_unwrapped_kwargs = pytree.arg_tree_leaves(**kwargs)
        flattened_wrapped_kwargs = pytree.arg_tree_leaves(**func_kwargs)
        func_outputs = func(*func_args, **func_kwargs)
        outputs = _unwrap_all_tensors_from_functional(func_outputs, reapply_views=reapply_views)
        for a in flattened_wrapped_args + flattened_wrapped_kwargs:
            if isinstance(a, torch.Tensor):
                torch._sync(a)
        for (unwrapped, wrapped) in zip(flattened_unwrapped_args, flattened_wrapped_args):
            if <MASK>:
                _propagate_functional_input_mutation(unwrapped, wrapped)
        for (unwrapped, wrapped) in zip(flattened_unwrapped_kwargs, flattened_wrapped_kwargs):
            if isinstance(unwrapped, torch.Tensor) and isinstance(wrapped, torch.Tensor):
                _propagate_functional_input_mutation(unwrapped, wrapped)
        return outputs
    finally:
        _func_decrement_nesting()

