def database_forwards(self, app_label, schema_editor, from_state, to_state):
    new_model = to_state.apps.get_model(app_label, self.name)
    if <MASK>:
        old_model = from_state.apps.get_model(app_label, self.name)
        schema_editor.alter_db_table(new_model, old_model._meta.db_table, new_model._meta.db_table)
        for (old_field, new_field) in zip(old_model._meta.local_many_to_many, new_model._meta.local_many_to_many):
            if new_field.remote_field.through._meta.auto_created:
                schema_editor.alter_db_table(new_field.remote_field.through, old_field.remote_field.through._meta.db_table, new_field.remote_field.through._meta.db_table)

def convert(pyval):
    if <MASK>:
        if layout is not None:
            raise NotImplementedError('shape_from_pyval does not support layouts for tuple shapes')
        return Shape.tuple_shape(tuple((convert(elt) for elt in pyval)))
    else:
        return Shape.array_shape(pyval.dtype, np.shape(pyval), layout)

@tf_utils.shape_type_conversion
def build(self, input_shape):
    if self._num_constants is not None:
        constants_shape = input_shape[-self._num_constants:]
    else:
        constants_shape = None
    if <MASK>:
        input_shape = input_shape[0]
    batch_size = input_shape[0] if self.stateful else None
    self.input_spec[0] = InputSpec(shape=(batch_size, None) + input_shape[2:5])
    if isinstance(self.cell, Layer):
        step_input_shape = (input_shape[0],) + input_shape[2:]
        if constants_shape is not None:
            self.cell.build([step_input_shape] + constants_shape)
        else:
            self.cell.build(step_input_shape)
    if hasattr(self.cell.state_size, '__len__'):
        state_size = list(self.cell.state_size)
    else:
        state_size = [self.cell.state_size]
    if self.state_spec is not None:
        if self.cell.data_format == 'channels_first':
            ch_dim = 1
        elif self.cell.data_format == 'channels_last':
            ch_dim = 3
        if [spec.shape[ch_dim] for spec in self.state_spec] != state_size:
            raise ValueError('An initial_state was passed that is not compatible with `cell.state_size`. Received `state_spec`={}; However `cell.state_size` is {}'.format([spec.shape for spec in self.state_spec], self.cell.state_size))
    elif self.cell.data_format == 'channels_first':
        self.state_spec = [InputSpec(shape=(None, dim, None, None)) for dim in state_size]
    elif self.cell.data_format == 'channels_last':
        self.state_spec = [InputSpec(shape=(None, None, None, dim)) for dim in state_size]
    if self.stateful:
        self.reset_states()
    self.built = True

