@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    """
        Fit the OrdinalEncoder to X.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            The data to determine the categories of each feature.

        y : None
            Ignored. This parameter exists only for compatibility with
            :class:`~sklearn.pipeline.Pipeline`.

        Returns
        -------
        self : object
            Fitted encoder.
        """
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif <MASK>:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if self._infrequent_enabled:
        for (feature_idx, infrequent) in enumerate(self.infrequent_categories_):
            if infrequent is not None:
                cardinalities[feature_idx] -= len(infrequent)
    for (cat_idx, categories_for_idx) in enumerate(self.categories_):
        if is_scalar_nan(categories_for_idx[-1]):
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for (cat_idx, cardinality) in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

def _poll(self) -> Optional[RunProcsResult]:
    done_local_ranks: set[int] = set()
    self._capture_process_failures(done_local_ranks)
    self._running_local_ranks.difference_update(done_local_ranks)
    if <MASK>:
        self.close()
        self._capture_process_failures(done_local_ranks)
        result = RunProcsResult(failures=self._failures, stdouts=self.stdouts, stderrs=self.stderrs)
        if result.is_failed():
            first_failure = min(result.failures.values(), key=lambda f: f.timestamp)
            logger.error('failed (exitcode: %s) local_rank: %s (pid: %s) of binary: %s', first_failure.exitcode, first_failure.local_rank, first_failure.pid, self.entrypoint)
        else:
            result.return_values = dict.fromkeys(range(self.nprocs))
        return result
    else:
        return None

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    file = super().__get__(instance, cls)
    if isinstance(file, str) or file is None:
        attr = self.field.attr_class(instance, self.field, file)
        instance.__dict__[self.field.attname] = attr
    elif isinstance(file, DatabaseDefault):
        attr = self.field.attr_class(instance, self.field, self.field.db_default)
        instance.__dict__[self.field.attname] = attr
    elif isinstance(file, File) and (not isinstance(file, FieldFile)):
        file_copy = self.field.attr_class(instance, self.field, file.name)
        file_copy.file = file
        file_copy._committed = False
        instance.__dict__[self.field.attname] = file_copy
    elif isinstance(file, FieldFile) and (not hasattr(file, 'field')):
        file.instance = instance
        file.field = self.field
        file.storage = self.field.storage
    elif <MASK>:
        file.instance = instance
    return instance.__dict__[self.field.attname]

def check_block_tiles(self, op: 'CKTileGemmOperation'):
    """
        The contiguous dimension of a tensor must be divisible by the block tile size
        This helper function enforces it for the inputs and the output.
        """
    (M, N, K) = self.get_gemm_problem_size()

    def check(dim_size, tile_size, is_padded):
        if is_static_int(dim_size) and dim_size % tile_size != 0 and (is_padded == 'false'):
            return False
        return True
    if op.layout_a == 'Row':
        return True
    elif op.layout_a == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_a={op.layout_a!r}')
    if op.layout_b == 'Row':
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_b == 'Col':
        return True
    else:
        raise AssertionError(f'Invalid op.layout_b={op.layout_b!r}')
    if <MASK>:
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_c == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_c={op.layout_c!r}')
    return True

def _resource_creator_scope(self):
    with self._coordinator_creation_lock:
        if <MASK>:
            cluster_coordinator.ClusterCoordinator(strategy=self._container_strategy())

    def lookup_creator(next_creator, *args, **kwargs):
        if load_context.in_load_context():
            return ps_values.RestoredDistributedTable(self._container_strategy(), lambda : next_creator(*args, **kwargs))
        else:
            return ps_values.DistributedTable(self._container_strategy(), lambda : next_creator(*args, **kwargs))

    def restored_lookup_creator(next_creator, *args, **kwargs):
        return ps_values.RestoredDistributedTable(self._container_strategy(), lambda : next_creator(*args, **kwargs))
    return [ops.resource_creator_scope('StaticHashTable', lookup_creator), ops.resource_creator_scope('RestoredStaticHashTable', restored_lookup_creator)]

def result_headers(cl):
    """
    Generate the list column headers.
    """
    ordering_field_columns = cl.get_ordering_field_columns()
    for (i, field_name) in enumerate(cl.list_display):
        (text, attr) = label_for_field(field_name, cl.model, model_admin=cl.model_admin, return_attr=True)
        is_field_sortable = cl.sortable_by is None or field_name in cl.sortable_by
        if attr:
            field_name = _coerce_field_name(field_name, i)
            if field_name == 'action_checkbox':
                aria_label = _('Select all objects on this page for an action')
                yield {'text': mark_safe(f'<input type="checkbox" id="action-toggle" aria-label="{aria_label}">'), 'class_attrib': mark_safe(' class="action-checkbox-column"'), 'sortable': False}
                continue
            admin_order_field = getattr(attr, 'admin_order_field', None)
            if isinstance(attr, property) and hasattr(attr, 'fget'):
                admin_order_field = getattr(attr.fget, 'admin_order_field', None)
            if <MASK>:
                is_field_sortable = False
        if not is_field_sortable:
            yield {'text': text, 'class_attrib': format_html(' class="column-{}"', field_name), 'sortable': False}
            continue
        th_classes = ['sortable', 'column-{}'.format(field_name)]
        order_type = ''
        new_order_type = 'asc'
        sort_priority = 0
        is_sorted = i in ordering_field_columns
        if is_sorted:
            order_type = ordering_field_columns.get(i).lower()
            sort_priority = list(ordering_field_columns).index(i) + 1
            th_classes.append('sorted %sending' % order_type)
            new_order_type = {'asc': 'desc', 'desc': 'asc'}[order_type]
        o_list_primary = []
        o_list_remove = []
        o_list_toggle = []

        def make_qs_param(t, n):
            return ('-' if t == 'desc' else '') + str(n)
        for (j, ot) in ordering_field_columns.items():
            if j == i:
                param = make_qs_param(new_order_type, j)
                o_list_primary.insert(0, param)
                o_list_toggle.append(param)
            else:
                param = make_qs_param(ot, j)
                o_list_primary.append(param)
                o_list_toggle.append(param)
                o_list_remove.append(param)
        if i not in ordering_field_columns:
            o_list_primary.insert(0, make_qs_param(new_order_type, i))
        yield {'text': text, 'sortable': True, 'sorted': is_sorted, 'ascending': order_type == 'asc', 'sort_priority': sort_priority, 'url_primary': cl.get_query_string({ORDER_VAR: '.'.join(o_list_primary)}), 'url_remove': cl.get_query_string({ORDER_VAR: '.'.join(o_list_remove)}), 'url_toggle': cl.get_query_string({ORDER_VAR: '.'.join(o_list_toggle)}), 'class_attrib': format_html(' class="{}"', ' '.join(th_classes)) if th_classes else ''}

def speedup_by_combo_kernel(self, nodes: list[BaseSchedulerNode]) -> bool:
    """
        If config.benchmark_fusion is False, always return True.
        Otherwise, return True if fusion can brings speedup.
        """
    if not config.benchmark_combo_kernel:
        return True
    subkernel_nodes = nodes
    device = subkernel_nodes[0].get_device()
    if device is None or device.type == 'cpu':
        return True
    from triton.compiler.errors import CompilationError
    (ms1, path1_list) = (0.0, [])
    for (i, snode) in enumerate(subkernel_nodes):
        node_list = snode.get_nodes()
        if self._any_atomic_add(node_list):
            fusion_log.debug('ComboKernel: benchmarking may not accurate due to atomic_add')
        try:
            (ms, path) = self.benchmark_fused_nodes(node_list)
            if math.isinf(ms):
                fusion_log.debug('ComboKernel benchmark: register spilling of %d-th subkernel', i)
                return False
        except CompilationError as e:
            if <MASK>:
                fusion_log.debug('ComboKernel benchmark: return True because of loop-carried variable')
                return True
            else:
                raise
        ms1 += ms
        path1_list.append(path)
    try:
        (ms2, ms2_clone, _path2_list) = self.benchmark_combo_kernel(subkernel_nodes)
    except CompilationError as e:
        if 'Loop-carried variable' in str(e):
            fusion_log.debug('ComboKernel benchmark: return True because of loop-carried variable')
            return True
        else:
            raise
    small_kernel = ms2 - ms2_clone < 0.3 or ms1 < 0.3
    if fusion_log.isEnabledFor(logging.DEBUG):
        if ms1 > ms2 or small_kernel:
            fusion_log.debug('can fuse (benchmark): fusing causes %sx speedup', green_text(f'{ms1 / ms2:.3f}'))
        else:
            fusion_log.debug('cannot fuse (benchmark): fusing causes %sx slowdown', red_text(f'{ms1 / ms2:.3f}'))
    return ms2 - ms2_clone < ms1 or small_kernel

def colour_text(s, fg=None, bg=None, bold=False):
    seq = []
    if bold:
        seq.append('1')
    if <MASK>:
        fgcode = 30 + _colour_codes.get(fg.lower(), 0)
        seq.append(str(fgcode))
    if bg:
        bgcode = 40 + _colour_codes.get(bg.lower(), 7)
        seq.append(str(bgcode))
    if seq:
        return '\x1b[%sm%s\x1b[0m' % (';'.join(seq), s)
    else:
        return s

def getmethodclass(m):
    """Resolves a function's owner, e.g.

  a method's class.

  Note that this returns the object that the function was retrieved from, not
  necessarily the class where it was defined.

  This function relies on Python stack frame support in the interpreter, and
  has the same limitations that inspect.currentframe.

  Limitations. This function will only work correctly if the owned class is
  visible in the caller's global or local variables.

  Args:
    m: A user defined function

  Returns:
    The class that this function was retrieved from, or None if the function
    is not an object or class method, or the class that owns the object or
    method is not visible to m.

  Raises:
    ValueError: if the class could not be resolved for any unexpected reason.
  """
    if not hasattr(m, '__name__') and hasattr(m, '__class__') and hasattr(m, '__call__'):
        if <MASK>:
            return m.__class__
    m_self = getattr(m, '__self__', None)
    if m_self is not None:
        if inspect.isclass(m_self):
            return m_self
        return m_self.__class__
    owners = []
    caller_frame = tf_inspect.currentframe().f_back
    try:
        for v in itertools.chain(caller_frame.f_locals.values(), caller_frame.f_globals.values()):
            if hasattr(v, m.__name__):
                candidate = getattr(v, m.__name__)
                if hasattr(candidate, 'im_func'):
                    candidate = candidate.im_func
                if hasattr(m, 'im_func'):
                    m = m.im_func
                if candidate is m:
                    owners.append(v)
    finally:
        del caller_frame
    if owners:
        if len(owners) == 1:
            return owners[0]
        owner_types = tuple((o if tf_inspect.isclass(o) else type(o) for o in owners))
        for o in owner_types:
            if tf_inspect.isclass(o) and issubclass(o, tuple(owner_types)):
                return o
        raise ValueError('Found too many owners of %s: %s' % (m, owners))
    return None

@register(*dispatch_key_set_functions)
def handle_dispatch_key_set_functions(self, tx: 'InstructionTranslator', *args, **kwargs):
    assert not kwargs
    if <MASK>:
        assert len(args) == 1
        assert isinstance(args[0], variables.TensorVariable)
        example_value = args[0].proxy.node.meta['example_value']
        dks = self.value(example_value)
        if isinstance(example_value, torch._subclasses.FakeTensor):
            dks = dks - torch._C.DispatchKeySet(torch._C.DispatchKey.Python) - torch._C.DispatchKeySet(torch._C.DispatchKey.PythonTLSSnapshot)
        return DispatchKeySetVariable.create(dks)
    else:
        assert not args
        return DispatchKeySetVariable.create(self.value())

def worker_fn(self, checkpoint_dir, cluster_spec, input_arg, strategy_option, maintenance_event=None, training_finished=None, frequent_send=False, training_restarted=None, termination_config=failure_handling.TerminationConfig(grace_period=0), api_wrapping_train=True):
    if strategy_option == 'MS':
        strategy = mirrored_strategy.MirroredStrategy()
    elif strategy_option == 'OneDevice':
        if config.list_physical_devices('GPU'):
            strategy = one_device_lib.OneDeviceStrategy(device='/gpu:0')
        else:
            strategy = one_device_lib.OneDeviceStrategy(device='/cpu:0')
    else:
        strategy = collective_all_reduce_strategy.CollectiveAllReduceStrategy()

    def mock_termination_watcher_function_gce(*args, **kwargs):
        del args, kwargs
        if not frequent_send:
            time.sleep(1)
            if not maintenance_event.is_set() and random.randrange(0, 11) == 5:
                maintenance_event.set()
                logging.info('Termination notice available.')
                return True
        elif frequent_send and (not maintenance_event.is_set()):
            logging.info('Termination notice available.')
            return True
        return False
    with mock.patch.object(failure_handling_util, 'termination_watcher_function_gce', mock_termination_watcher_function_gce), mock.patch.object(failure_handling_util, 'detect_platform', lambda : failure_handling_util.PlatformDevice.GCE_GPU):

        class Model(module.Module):

            def __init__(self):
                self.v = variables_lib.Variable(0.0, synchronization=variables_lib.VariableSynchronization.ON_WRITE, aggregation=variables_lib.VariableAggregation.SUM)

            @def_function.function(input_signature=[])
            def __call__(self):
                return self.v.read_value()
        with strategy.scope():
            model = Model()
            fh_ckpt = tracking_util.Checkpoint(model=model)
            if input_arg == 'checkpoint':
                checkpoint_or_manager = fh_ckpt
            else:
                checkpoint_or_manager = _make_checkpoint_manager(fh_ckpt, checkpoint_dir, strategy.cluster_resolver)
            preemption_handler = failure_handling.PreemptionCheckpointHandler(strategy.cluster_resolver, checkpoint_or_manager, checkpoint_dir, termination_config)

        def distributed_train_step(current_epoch, current_step):

            @def_function.function
            def train_step():
                model.v.assign_add(constant_op.constant(1.0))
            strategy.run(train_step)
            if current_step == STEPS_PER_EPOCH - 1:
                logging.info('epoch %d finished', current_epoch)
        logging.info('Start training at %d', preemption_handler.total_run_calls)
        if training_restarted.is_set() and (not training_finished.is_set()):
            logging.info(gfile.ListDirectory(checkpoint_dir))
            match_group = [re.search('.*ckpt-(\\d+).index', a_file) for a_file in gfile.ListDirectory(checkpoint_dir)]
            checkpoint_index = [a_match.group(1) for a_match in match_group if a_match]
            self.assertNotEmpty(checkpoint_index)
            if api_wrapping_train:
                if termination_config.grace_period > 0:
                    self.assertEqual(max([int(ckpt_index) for ckpt_index in checkpoint_index]), 2)
                else:
                    self.assertEqual(max([int(ckpt_index) for ckpt_index in checkpoint_index]), 1)
            else:
                self.assertEqual(max([int(ckpt_index) for ckpt_index in checkpoint_index]), preemption_handler.total_run_calls)
        for epoch in range(preemption_handler.total_run_calls // STEPS_PER_EPOCH, EPOCHS_TO_RUN):
            for step in range(preemption_handler.total_run_calls % STEPS_PER_EPOCH, STEPS_PER_EPOCH):
                if api_wrapping_train:
                    preemption_handler.run(distributed_train_step, epoch, step)
                else:
                    preemption_handler.save_checkpoint_if_preempted(checkpoint_number=preemption_handler.total_run_calls)
                    distributed_train_step(epoch, step)
        logging.info('Training finished.')
        training_finished.set()
        self.assertEqual(model.v.numpy(), strategy.num_replicas_in_sync * EPOCHS_TO_RUN * STEPS_PER_EPOCH)
        running_threads = test_util.get_running_threads()
        if test_util.has_thread(_PEER_WATCHER_THREAD_PREFIX, running_threads) and test_util.has_thread(_LOCAL_WATCHER_THREAD_PREFIX, running_threads):
            try:
                preemption_handler.__del__()
                time.sleep(2)
                running_threads = test_util.get_running_threads()
                self.assertFalse(test_util.has_thread(_LOCAL_WATCHER_THREAD_PREFIX, running_threads))
                self.assertFalse(test_util.has_thread(_PEER_WATCHER_THREAD_PREFIX, running_threads))
            except urllib.error.URLError as e:
                if <MASK>:
                    logging.warning('Hit a mock issue.')
                    return

def can_produce(self, output_spec: Spec) -> bool:
    """Matmul can handle various tensor dimensions >= 1."""
    if not isinstance(output_spec, TensorSpec):
        return False
    if len(output_spec.size) < 1:
        return False
    if <MASK>:
        return False
    return True

@dispatch.add_dispatch_support
@doc_controls.do_not_generate_docs
def switch(condition, then_expression, else_expression):
    """Switches between two operations depending on a scalar value.

  Note that both `then_expression` and `else_expression`
  should be symbolic tensors of the *same shape*.

  Args:
      condition: tensor (`int` or `bool`).
      then_expression: either a tensor, or a callable that returns a tensor.
      else_expression: either a tensor, or a callable that returns a tensor.

  Returns:
      The selected tensor.

  Raises:
      ValueError: If rank of `condition` is greater than rank of expressions.
  """
    if condition.dtype != dtypes_module.bool:
        condition = math_ops.cast(condition, 'bool')
    cond_ndim = ndim(condition)
    if not cond_ndim:
        if not callable(then_expression):

            def then_expression_fn():
                return then_expression
        else:
            then_expression_fn = then_expression
        if not callable(else_expression):

            def else_expression_fn():
                return else_expression
        else:
            else_expression_fn = else_expression
        x = cond.cond(condition, then_expression_fn, else_expression_fn)
    else:
        if callable(then_expression):
            then_expression = then_expression()
        if callable(else_expression):
            else_expression = else_expression()
        expr_ndim = ndim(then_expression)
        if <MASK>:
            raise ValueError('Rank of `condition` should be less than or equal to rank of `then_expression` and `else_expression`. ndim(condition)=' + str(cond_ndim) + ', ndim(then_expression)=' + str(expr_ndim))
        if cond_ndim > 1:
            ndim_diff = expr_ndim - cond_ndim
            cond_shape = array_ops.concat([array_ops.shape(condition), [1] * ndim_diff], axis=0)
            condition = array_ops.reshape(condition, cond_shape)
            expr_shape = array_ops.shape(then_expression)
            shape_diff = expr_shape - cond_shape
            tile_shape = array_ops.where_v2(shape_diff > 0, expr_shape, array_ops.ones_like(expr_shape))
            condition = array_ops.tile(condition, tile_shape)
        x = array_ops.where_v2(condition, then_expression, else_expression)
    return x

def try_ann_to_type(ann, loc, rcb=None):
    ann_args = typing.get_args(ann)
    if ann is inspect.Signature.empty:
        return TensorType.getInferred()
    if ann is None:
        return NoneType.get()
    if inspect.isclass(ann) and is_tensor(ann):
        return TensorType.get()
    if is_tuple(ann):
        if len(ann_args) == 1 and ann_args[0] == ():
            return TupleType([])
        return TupleType([try_ann_to_type(a, loc) for a in ann_args])
    if is_list(ann):
        elem_type = try_ann_to_type(ann_args[0], loc)
        if elem_type:
            return ListType(elem_type)
    if is_dict(ann):
        key = try_ann_to_type(ann_args[0], loc)
        value = try_ann_to_type(ann_args[1], loc)
        if key is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[0]}' at {loc.highlight()}")
        if value is None:
            raise ValueError(f"Unknown type annotation: '{ann_args[1]}' at {loc.highlight()}")
        return DictType(key, value)
    if is_optional(ann):
        if issubclass(ann_args[1], type(None)):
            contained = ann_args[0]
        else:
            contained = ann_args[1]
        valid_type = try_ann_to_type(contained, loc)
        msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
        assert valid_type, msg.format(repr(ann), repr(contained), repr(loc))
        return OptionalType(valid_type)
    if is_union(ann):
        if set(ann_args) == {int, float, complex}:
            return NumberType.get()
        inner: List = []
        for a in typing.get_args(ann):
            if a is None:
                inner.append(NoneType.get())
            maybe_type = try_ann_to_type(a, loc)
            msg = 'Unsupported annotation {} could not be resolved because {} could not be resolved. At\n{}'
            assert maybe_type, msg.format(repr(ann), repr(maybe_type), repr(loc))
            inner.append(maybe_type)
        return UnionType(inner)
    if torch.distributed.rpc.is_available() and is_rref(ann):
        return RRefType(try_ann_to_type(ann_args[0], loc))
    if is_future(ann):
        return FutureType(try_ann_to_type(ann_args[0], loc))
    if is_await(ann):
        elementType = try_ann_to_type(ann_args[0], loc) if ann_args else AnyType.get()
        return AwaitType(elementType)
    if ann is float:
        return FloatType.get()
    if ann is complex:
        return ComplexType.get()
    if ann is int or ann is torch.SymInt:
        return IntType.get()
    if <MASK>:
        return StringType.get()
    if ann is bool:
        return BoolType.get()
    if ann is Any:
        return AnyType.get()
    if ann is type(None):
        return NoneType.get()
    if inspect.isclass(ann) and hasattr(ann, '__torch_script_interface__'):
        return InterfaceType(ann.__torch_script_interface__)
    if ann is torch.device:
        return DeviceObjType.get()
    if ann is torch.Generator:
        return _GeneratorType.get()
    if ann is torch.Stream:
        return StreamObjType.get()
    if ann is torch.dtype:
        return IntType.get()
    if ann is torch.qscheme:
        return IntType.get()
    if inspect.isclass(ann) and issubclass(ann, enum.Enum):
        if _get_script_class(ann) is None:
            scripted_class = torch.jit._script._recursive_compile_class(ann, loc)
            name = scripted_class.qualified_name()
        else:
            name = _qualified_name(ann)
        return EnumType(name, get_enum_value_type(ann, loc), list(ann))
    if inspect.isclass(ann):
        maybe_script_class = _get_script_class(ann)
        if maybe_script_class is not None:
            return maybe_script_class
        if torch._jit_internal.can_compile_class(ann):
            return torch.jit._script._recursive_compile_class(ann, loc)
    if rcb is None:
        rcb = _fake_rcb
    return torch._C._resolve_type_from_object(ann, loc, rcb)

def _check_iterator_valid(datapipe, iterator_id, next_method_exists=False) -> None:
    """
    Given an instance of a DataPipe and an iterator ID, check if the IDs match, and if not, raises an exception.

    In the case of ChildDataPipe, the ID gets compared to the one stored in `main_datapipe` as well.
    """
    if next_method_exists:
        if <MASK>:
            extra_msg = "\nNote that this exception is raised inside your IterDataPipe's a `__next__` method"
            raise RuntimeError(_gen_invalid_iterdatapipe_msg(datapipe) + extra_msg + _feedback_msg)
    elif hasattr(datapipe, '_is_child_datapipe') and datapipe._is_child_datapipe is True:
        if hasattr(datapipe, '_check_valid_iterator_id'):
            if not datapipe._check_valid_iterator_id(iterator_id):
                raise RuntimeError(f'This iterator has been invalidated, because a new iterator has been created from one of the ChildDataPipes of {_generate_iterdatapipe_msg(datapipe.main_datapipe)}.' + _feedback_msg)
        else:
            raise RuntimeError('ChildDataPipe must have method `_check_valid_iterator_id`.')
    elif datapipe._valid_iterator_id != iterator_id:
        raise RuntimeError(_gen_invalid_iterdatapipe_msg(datapipe) + _feedback_msg)

