def integer_or_float_list(a):
    lst = []
    for n in a.split(','):
        if n.count(':') == 1:
            (start, end) = map(int, n.split(':'))
            lst.extend(range(start, end))
        elif <MASK>:
            (start, end, step) = map(int, n.split(':'))
            lst.extend(range(start, end, step))
        elif '.' in n:
            lst.append(float(n))
        else:
            lst.append(int(n))
    return lst

