    elif inspect.isclass(proxy.node.target) and issubclass(proxy.node.target, torch.Stream) or proxy.node.target in [device_interface.current_stream for (_, device_interface) in get_registered_device_interfaces()]:
        set_example_value(proxy.node, example_value)
        return StreamVariable(proxy, example_value, example_value.device, **options)
    elif inspect.isclass(proxy.node.target) and issubclass(proxy.node.target, torch.Event) or proxy.node.target in [device_interface.Event for (_, device_interface) in get_registered_device_interfaces()]:
        set_example_value(proxy.node, example_value)
        return EventVariable(proxy, example_value, **options)
    elif proxy.node.target == 'query' and proxy.node.op == 'call_method':
        set_example_value(proxy.node, example_value)
        return ConstantVariable(example_value, **options)
    elif example_value is not None and isinstance(example_value, torch.Event) and (proxy.node.target == 'record_event') and (proxy.node.op == 'call_method'):
        set_example_value(proxy.node, example_value)
        return EventVariable(proxy, example_value, **options)
    elif isinstance(example_value, int) and (proxy.node.target in [torch.sym_int, getattr, operator.getitem, torch._utils._element_size, torch.seed, operator.mod, torch._functorch.vmap._validate_and_get_batch_size, torch._functorch.predispatch._vmap_increment_nesting, torch._functorch.predispatch._vmap_decrement_nesting, getattr(torch.distributed, 'get_rank', _missing), getattr(torch.distributed, 'get_world_size', _missing), torch._constrain_as_size] or (proxy.node.op == 'call_method' and proxy.node.target == 'bit_length')):
