    elif isinstance(example_value, bool) and proxy.node.target in [torch._C._are_functorch_transforms_active, torch._C._functorch.is_batchedtensor, torch.backends.cuda.is_flash_attention_available, torch.backends.cuda.can_use_flash_attention, torch.backends.cuda.can_use_efficient_attention, torch._C._get_cudnn_sdp_enabled, torch._C._get_flash_sdp_enabled, torch._C._get_mem_efficient_sdp_enabled, torch._C._get_math_sdp_enabled, torch._C._get_overrideable_sdp_enabled, 'is_integer'] + list(supported_const_comparison_op_values.keys()):
