def type_check_node(self, n: Node):
    """
        Type check a given fx node.
        Current operations:
        - Reshape
        - Transpose
        - Add
        - Relu
        - conv2d
        - batchnorm2d
        - flatten
        - maxpool2d
        - adaptiveavgpool2d
        - linear
        """
    if n.type is None:
        n.type = Dyn
    if n.op == 'placeholder':
        return n.type
    elif n.op == 'get_attr':
        t = get_parameter(self.traced, n.target)
        if isinstance(t.data, torch.Tensor):
            n.type = TensorType(t.data.shape)
        return n.type
    elif n.op == 'call_function':
        if n.target == getattr:
            assert getattr in _INFERENCE_RULES
            return _INFERENCE_RULES[n.target](n, self.traced)
        elif n.target in _INFERENCE_RULES:
            return _INFERENCE_RULES[n.target](n)
        else:
            raise RuntimeError(f'No inference rule registered for target {n.target}!')
    elif n.op == 'call_module':
        module_instance = self.traced.get_submodule(n.target)
        if type(module_instance) in _INFERENCE_RULES:
            return _INFERENCE_RULES[type(module_instance)](n, module_instance)
        else:
            raise RuntimeError(f'No inference rule registered for class {type(module_instance)}!')
    elif <MASK>:

        def get_node_type(a):
            return a.type
        n.type = torch.fx.node.map_arg(n.args[0], get_node_type)
        return n.type
    else:
        raise NotImplementedError(f'Method {n.op} not yet implemented')

def calculate_qmin_qmax(quant_min: int, quant_max: int, has_customized_qrange: bool, dtype: torch.dtype, reduce_range: bool) -> tuple[int, int]:
    """Calculates actual qmin and qmax based on the quantization range,
    observer datatype and if range is reduced.
    """
    if has_customized_qrange:
        if <MASK>:
            (initial_quant_min, initial_quant_max) = (0, 2 ** 32 - 1)
        else:
            (initial_quant_min, initial_quant_max) = (0, 255)
        (custom_quant_min, custom_quant_max) = (quant_min, quant_max)
        if custom_quant_min is not None and custom_quant_max is not None:
            (initial_quant_min, initial_quant_max) = (custom_quant_min, custom_quant_max)
        qrange_len = initial_quant_max - initial_quant_min + 1
        if dtype in [torch.qint8, torch.int8]:
            assert 0 < qrange_len <= 256, 'quantization range should be positive and not exceed the maximum bit range (=256).'
        elif dtype in [torch.qint32, torch.int32]:
            assert 0 < qrange_len <= 2 ** 32, 'quantization range should be positive and not exceed the maximum bit range (=4294967296).'
        if reduce_range:
            (quant_min, quant_max) = (quant_min // 2, quant_max // 2)
    elif dtype in [torch.qint8, torch.int8]:
        if reduce_range:
            (quant_min, quant_max) = (-64, 63)
        else:
            (quant_min, quant_max) = (-128, 127)
    elif dtype in [torch.quint8, torch.uint8]:
        if reduce_range:
            (quant_min, quant_max) = (0, 127)
        else:
            (quant_min, quant_max) = (0, 255)
    elif dtype in [torch.qint32, torch.int32]:
        (quant_min, quant_max) = (-1 * 2 ** 31, 2 ** 31 - 1)
    elif dtype == torch.uint16:
        (quant_min, quant_max) = (0, 2 ** 16 - 1)
    elif dtype == torch.int16:
        (quant_min, quant_max) = (-2 ** 15, 2 ** 15 - 1)
    else:
        (quant_min, quant_max) = (0, 15)
    return (quant_min, quant_max)

