def select_dispatch_strategy(self) -> None:
    if <MASK>:
        return
    if not self.mixed_sizes or any((isinstance(e, str) for e in self.x_numels_list)):
        self.dispatch_class = ComboKernel.SequentialDispatch
        return
    x_numels_list = [abs(cast(int, e)) for e in self.x_numels_list]
    total = max(x_numels_list) * len(x_numels_list)
    needed = sum(x_numels_list)
    if needed / total > BLOCK_UTILIZATION:
        self.dispatch_class = ComboKernel.RoundRobinDispatch
    else:
        self.dispatch_class = ComboKernel.SequentialDispatch

def aot_module_simplified(mod: nn.Module, args, fw_compiler: AOTDispatchCompiler, bw_compiler: Optional[AOTDispatchCompiler]=None, partition_fn: Callable=default_partition, decompositions: Optional[dict]=None, keep_inference_input_mutations=False, inference_compiler: Optional[AOTDispatchCompiler]=None, cudagraphs: Optional[BoxedBool]=None, boxed_forward_device_index: Optional[BoxedDeviceIndex]=None, ignore_shape_env: bool=False, disable_functionalization: bool=False) -> nn.Module:
    """
    This is the simplified or low overhead version of aot_module. For frontends
    like TorchDynamo, the input functions/modules to AOT are static and have
    unpacked inputs/outputs. This gives us an opportunity to remove the
        (1) pytree overhead to parse inputs/outputs,
        (2) AOT Autograd cache,
        (3) Reading of params/buffers in every forward call

    :func:`aot_module_simplified` removes these overheads.
    """
    if cudagraphs is None:
        cudagraphs = BoxedBool(torch._inductor.config.triton.cudagraphs)
    with contextlib.ExitStack() as stack:
        (functional_call, params_buffers_flat, _params_spec, _buffers_spec, fake_flat_args, full_args_descs, aot_config, fake_mode, shape_env, _in_spec, _out_spec) = prepare_aot_module_simplified(mod, args, None, decompositions, keep_inference_input_mutations, boxed_forward_device_index, ignore_shape_env, flatten=False, force_non_lazy_backward_lowering=config.force_non_lazy_backward_lowering, disable_functionalization=disable_functionalization)
        compiled_fn = None
        if isinstance(fw_compiler, SerializableAOTDispatchCompiler):
            local = should_use_local_autograd_cache()
            remote = should_use_remote_autograd_cache()
            if local or remote:
                set_feature_use('aot_autograd_remote_cache', remote)
                compiled_fn = AOTAutogradCache.try_load(mod, fake_flat_args, aot_config, cudagraphs, boxed_forward_device_index, local, remote)
        if compiled_fn is None:
            stack.enter_context(compiled_autograd._disable())
            aot_state = create_aot_state(stack, functional_call, fake_flat_args, full_args_descs, aot_config, fake_mode, shape_env)
            aot_graph_capture = aot_stage1_graph_capture(aot_state, functional_call)
            (compiled_fn, _) = aot_stage2_compile(aot_state, aot_graph_capture, partition_fn, fw_compiler, bw_compiler, inference_compiler)
    if isinstance(mod, torch._dynamo.utils.GmWrapper):

        @simple_wraps(compiled_fn)
        def forward(runtime_args: list[Any]):
            flat_args = []
            flat_args.extend(params_buffers_flat)
            flat_args.extend(runtime_args)
            runtime_args.clear()
            return compiled_fn(flat_args)
    else:

        @simple_wraps(compiled_fn)
        def forward(*runtime_args: tuple[Any]):
            full_args = []
            full_args.extend(params_buffers_flat)
            full_args.extend(runtime_args)
            return compiled_fn(full_args)
    forward.zero_grad = mod.zero_grad
    forward.named_parameters = mod.named_parameters
    forward.named_buffers = mod.named_buffers

    def grab_serialize_fn(fn):
        if <MASK>:
            return fn.serialize_fn
        elif hasattr(fn, '__wrapped__'):
            return grab_serialize_fn(fn.__wrapped__)
        else:
            return None
    forward.serialize = grab_serialize_fn(forward)
    return forward

