def track_node(self, tx: InstructionTranslatorBase, node: Node) -> None:
    """
        The main entry point for tracking a node. This function will hash the node argument and group
        nodes with the same hash together. It updates the hash_to_duplicates and node_to_duplicates dictionaries
        to track the new node.
        """
    try:
        if <MASK>:
            duplicates = self.hash_to_duplicates[self._hash_node(tx.f_code.co_filename, tx.lineno, tx.instruction_pointer, node)]
            duplicates.append(node)
            self.node_to_duplicates[node] = duplicates
    except NodeHashException as e:
        log.debug('Unable to hash node %s with exception %s', node, e)

def AddValue(self, val):
    """Add `val` to the current context and its outer context recursively."""
    result = val
    new_value = val.name not in self._values
    new_value &= val.op._control_flow_context is not self
    if new_value:
        self._values.add(val.name)
        grad_ctxt = ops.get_default_graph()._get_control_flow_context()
        if grad_ctxt:
            grad_ctxt = grad_ctxt.GetWhileContext()
            if <MASK>:
                forward_ctxt = util.GetWhileContext(val.op)
                if util.IsLoopExit(val.op):
                    forward_ctxt = forward_ctxt.outer_context
                    if forward_ctxt:
                        forward_ctxt = forward_ctxt.GetWhileContext()
                if forward_ctxt == grad_ctxt.grad_state.forward_context:
                    real_val = grad_ctxt.grad_state.GetRealValue(val)
                    self._external_values[val.name] = real_val
                    return real_val
        if self._outer_context is not None:
            result = self._outer_context.AddValue(val)
        with ops.control_dependencies(None):
            enter = _Enter(result, self._name, is_constant=True, parallel_iterations=self._parallel_iterations)
            enter.graph.prevent_feeding(enter)
            if self._outer_context:
                self._outer_context.AddInnerOp(enter.op)
        self._FixControlInputsAndContext([enter])
        self._values.add(enter.name)
        self._external_values[val.name] = enter
        result = enter
    else:
        actual_val = self._external_values.get(val.name)
        if actual_val is not None:
            result = actual_val
    return result

@staticmethod
def build_Constant(ctx, expr):
    value = expr.value
    if <MASK>:
        return ExprBuilder.build_NameConstant(ctx, expr)
    if isinstance(value, (int, float, complex)):
        return ExprBuilder.build_Num(ctx, expr)
    elif isinstance(value, str):
        return ExprBuilder.build_Str(ctx, expr)
    elif isinstance(value, type(Ellipsis)):
        return ExprBuilder.build_Ellipsis(ctx, expr)
    else:
        error_range = ctx.make_range(expr.lineno, expr.col_offset, expr.col_offset + len(str(value)))
        raise FrontendError(error_range, 'Unknown Constant expression type')

def flatten_parameters(self) -> None:
    """Reset parameter data pointer so that they can use faster code paths.

        Right now, this works only if the module is on the GPU and cuDNN is enabled.
        Otherwise, it's a no-op.
        """
    if len(self._flat_weights) != len(self._flat_weights_names):
        return
    for w in self._flat_weights:
        if not isinstance(w, Tensor):
            return
    first_fw = self._flat_weights[0]
    dtype = first_fw.dtype
    for fw in self._flat_weights:
        if <MASK>:
            return
    unique_data_ptrs = {p.data_ptr() for p in self._flat_weights}
    if len(unique_data_ptrs) != len(self._flat_weights):
        return
    with torch.cuda.device_of(first_fw):
        import torch.backends.cudnn.rnn as rnn
        with torch.no_grad():
            if torch._use_cudnn_rnn_flatten_weight():
                num_weights = 4 if self.bias else 2
                if self.proj_size > 0:
                    num_weights += 1
                torch._cudnn_rnn_flatten_weight(self._flat_weights, num_weights, self.input_size, rnn.get_cudnn_mode(self.mode), self.hidden_size, self.proj_size, self.num_layers, self.batch_first, bool(self.bidirectional))

def as_sql(self, compiler, connection):
    param = quote_lexeme(self.value)
    label = ''
    if self.prefix:
        label += '*'
    if self.weight:
        label += self.weight
    if label:
        param = f'{param}:{label}'
    if <MASK>:
        param = f'!{param}'
    return ('%s', (param,))

def make_reindexer(self) -> Callable[[Sequence[Expr]], Sequence[Expr]]:
    target = self.get_size()
    actual = self.data.get_size()
    skip = len(target) - len(actual)

    def reindex(index: Sequence[Expr]) -> Sequence[Expr]:
        index = list(index[skip:])
        assert len(index) == len(actual)
        for i in range(len(actual)):
            if <MASK>:
                index[i] = sympy.S.Zero
        return index
    return reindex

def _canonicalize_fft_shape_and_dim_args(input: TensorLikeType, shape: Optional[ShapeType], dim: Optional[DimsType]) -> _ShapeAndDims:
    """Convert the shape and dim arguments into a canonical form where neither are optional"""
    input_dim = input.ndim
    input_sizes = input.shape
    if dim is not None:
        if not isinstance(dim, Sequence):
            dim = (dim,)
        ret_dims = utils.canonicalize_dims(input_dim, dim, wrap_scalar=False)
        torch._check(len(set(ret_dims)) == len(ret_dims), lambda : 'FFT dims must be unique')
    if <MASK>:
        if not isinstance(shape, Sequence):
            shape = (shape,)
        torch._check(dim is None or len(dim) == len(shape), lambda : 'When given, dim and shape arguments must have the same length')
        transform_ndim = len(shape)
        torch._check(transform_ndim <= input_dim, lambda : f'Got shape with {transform_ndim} values but input tensor only has {input_dim} dimensions.')
        if dim is None:
            ret_dims = tuple(range(input_dim - transform_ndim, input_dim))
        ret_shape = tuple((s if s != -1 else input_sizes[d] for (s, d) in zip(shape, ret_dims)))
    elif dim is None:
        ret_dims = tuple(range(input_dim))
        ret_shape = tuple(input_sizes)
    else:
        ret_shape = tuple((input_sizes[d] for d in ret_dims))
    for n in ret_shape:
        torch._check(n > 0, lambda : f'Invalid number of data points ({n}) specified')
    return _ShapeAndDims(shape=ret_shape, dims=ret_dims)

def _collect_all_calls(dynamo_dir: Path) -> dict[str, list[tuple[dict[str, Any], Path]]]:
    """Return mapping *gb_type → list[(call_info, file_path)]* for all occurrences."""
    gb_type_calls: dict[str, list[tuple[dict[str, Any], Path]]] = {}
    for py_file in dynamo_dir.rglob('*.py'):
        for call in find_unimplemented_v2_calls(py_file, dynamo_dir):
            gb_type = call['gb_type']
            if <MASK>:
                gb_type_calls[gb_type] = []
            gb_type_calls[gb_type].append((call, py_file))
    return gb_type_calls

def update_mask(self, module, tensor_name, sparsity_level, sparse_block_shape, zeros_per_block, **kwargs):
    values_per_block = reduce(operator.mul, sparse_block_shape)
    if zeros_per_block > values_per_block:
        raise ValueError('Number of zeros per block cannot be more than the total number of elements in that block.')
    if <MASK>:
        raise ValueError('Number of zeros per block should be positive.')
    mask = getattr(module.parametrizations, tensor_name)[0].mask
    if sparsity_level <= 0 or zeros_per_block == 0:
        mask.data = torch.ones_like(mask)
    elif sparsity_level >= 1.0 and zeros_per_block == values_per_block:
        mask.data = torch.zeros_like(mask)
    else:
        ww = self.norm_fn(getattr(module, tensor_name))
        tensor_mask = self._make_tensor_mask(data=ww, input_shape=ww.shape, sparsity_level=sparsity_level, sparse_block_shape=sparse_block_shape)
        if values_per_block != zeros_per_block:
            block_mask = self._make_block_mask(data=ww, sparse_block_shape=sparse_block_shape, zeros_per_block=zeros_per_block)
            tensor_mask = torch.logical_or(tensor_mask, block_mask)
        mask.data = tensor_mask

def extract_input(node: torch.fx.Node) -> Optional[FakeTensor]:
    if 'val' in node.meta:
        fake = node.meta['val']
        if hasattr(fake, 'constant') and fake.constant is not None:
            return fake.constant
        return fake
    elif <MASK>:
        assert self.fake_tensor_mode is not None
        return FakeTensor(self.fake_tensor_mode, torch.empty(tensor_meta.shape, dtype=tensor_meta.dtype, device='meta', requires_grad=tensor_meta.requires_grad, memory_format=tensor_meta.memory_format), torch.device('cpu'))
    elif len(node.users) == 0:
        return None
    raise ExportPassBaseError(f'Cannot construct an input for graph module: {graph_module}.')

