def filter_op(self, op: 'cutlass_library.gemm_op.GemmOperation') -> 'cutlass_library.gemm_op.GemmOperation':
    """
        Helper method:

        Determines whether a given Cutlass GEMM op definition is suitable for the current
        input / output of the operation that this template is supposed to implement.

        Takes memory layout, dtype and support for EVT operations into account,
        and filters potentially problematic ops.

        Returns None if the op is not suitable, otherwise returns the op to be used, which might
        have been mutated.
        """
    if op.gemm_kind not in self._get_supported_ops():
        return None
    X = self.input_nodes[0]
    W = self.input_nodes[1]
    if not self._shape_match(op):
        return None
    if not self._dtype_match(op):
        return None
    if not self._alignment_match(op):
        log.debug('Skipping due to alignment mismatch. op: %s', op.configuration_name())
        return None
    if op.tile_scheduler.name == 'StreamK':
        static_shape = PythonWrapperCodegen.statically_known_list_of_ints_or_none(tuple(X.get_size()) + tuple(W.get_size()))
        if not static_shape:
            return None
    op = copy.deepcopy(op)
    self.set_layout(op.A, X.get_layout())
    self.set_layout(op.B, W.get_layout())
    op.D.layout = CUTLASSGemmTemplate.cutlass_layout(self.output_node.get_layout())
    status = self.set_alignment(X.get_layout(), op.A) and self.set_alignment(W.get_layout(), op.B) and self.set_alignment(self.output_node.get_layout(), op.D)
    if not status:
        log.debug('Skipping due to alignment setting failure. op: %s', op.configuration_name())
        return None
    if inductor_cuda_config.cutlass_tma_only and (not self._has_tma_epilogue(op)):
        return None
    op.element_epilogue = op.accumulator_type()
    if self.use_fast_accum is not None:
        is_op_fast_accum = 'fastaccum' in op.configuration_name()
        if self.use_fast_accum ^ is_op_fast_accum:
            return None
    status = self._set_bias_layout_and_alignment(op)
    if not status:
        log.debug('Skipping due to bias layout and alignment setting failure. op: %s', op.configuration_name())
        return None
    if inductor_cuda_config.cutlass_op_allowlist_regex:
        if not re.search(inductor_cuda_config.cutlass_op_allowlist_regex, op.configuration_name()):
            return None
    if inductor_cuda_config.cutlass_op_denylist_regex is not None:
        if <MASK>:
            return None
    return op

def call_apply(self, tx: 'InstructionTranslator', args, kwargs):
    requires_grad = False

    def visit(vt):
        nonlocal requires_grad
        if isinstance(vt, variables.TensorVariable):
            if vt.requires_grad is not False:
                requires_grad = True
        if <MASK>:
            if vt.is_training(tx):
                requires_grad = True
    VariableTracker.visit(visit, (args, kwargs))
    if requires_grad and torch.is_grad_enabled():
        if config.capture_autograd_function is False:
            warnings.warn("The config.capture_autograd_function flag is deprecated, it's now always true.")
        from torch._functorch.autograd_function import autograd_function_forward_rewritten
        from torch.autograd.function import _is_setup_context_defined
        forward_fn = self.fn_cls.forward
        is_setup_ctx_defined = _is_setup_context_defined(self.fn_cls.setup_context)
        if is_setup_ctx_defined:
            forward_fn = autograd_function_forward_rewritten(self.fn_cls.forward, self.fn_cls.setup_context)
        vjp_fn = self.fn_cls.vjp
        if vjp_fn is not torch.autograd.Function.vjp:
            unimplemented_v2(gb_type='Unsupported custom vjp', context=f'call_apply {self} {args} {kwargs}', explanation='Dynamo does not support tracing `torch.autograd.Function` subclasses that define a custom `vjp` method.', hints=['Remove the custom `vjp` method if possible.', 'Use standard `backward` instead if applicable.', *graph_break_hints.SUPPORTABLE])
        jvp_fn = self.fn_cls.jvp
        if jvp_fn is not torch.autograd.Function.jvp:
            unimplemented_v2(gb_type='Unsupported custom jvp', context=f'call_apply {self} {args} {kwargs}', explanation='Dynamo does not support tracing `torch.autograd.Function` subclasses that define a custom `jvp` method.', hints=['Remove the custom `jvp` method if possible.', *graph_break_hints.SUPPORTABLE])
        from .higher_order_ops import AutogradFunctionApplyVariable
        source = self.source
        if source is None:
            source = AttrSource(tx.import_source(self.fn_cls.__module__), self.fn_cls.__name__)
        val = AutogradFunctionApplyVariable(forward_fn, self.fn_cls.backward, source, source=AttrSource(source, member='apply')).call_function(tx, args, kwargs)
        if self.source:
            fwd_src = AttrSource(self.source, 'forward')
            install_guard(fwd_src.make_guard(GuardBuilder.FUNCTION_MATCH))
            if is_setup_ctx_defined:
                setup_ctx_src = AttrSource(self.source, 'setup_context')
                install_guard(setup_ctx_src.make_guard(GuardBuilder.FUNCTION_MATCH))
        return val
    if self.source:
        source = AttrSource(self.source, 'forward')
    else:
        source = None
    fn = self.fn_cls.forward
    ctx = AutogradFunctionContextVariable.create(tx, args, kwargs)
    args = [ctx, *args]
    if isinstance(fn, types.FunctionType):
        sig = inspect.signature(fn)
        if len(args) - 1 == len(sig._parameters):
            args = args[1:]
        return variables.UserFunctionVariable(fn, source=source).call_function(tx, args, kwargs)
    elif isinstance(fn, types.MethodType):
        return variables.UserMethodVariable(fn.__func__, variables.UserDefinedClassVariable(self.fn_cls), source=source).call_function(tx, args, kwargs)
    else:
        unimplemented_v2(gb_type='Non-function or method in subclass of torch.autograd.Function', context=f'call_apply {self} {args} {kwargs}', explanation=f'Dynamo requires the `forward` attribute of a `torch.autograd.Function` subclass to be a standard Python function or method. Found type `{type(fn).__name__}` instead.', hints=['Ensure the `forward` method is defined as a regular function or instance method.'])

def parallel_walk(node, other):
    """Walks two ASTs in parallel.

  The two trees must have identical structure.

  Args:
    node: Union[ast.AST, Iterable[ast.AST]]
    other: Union[ast.AST, Iterable[ast.AST]]
  Yields:
    Tuple[ast.AST, ast.AST]
  Raises:
    ValueError: if the two trees don't have identical structure.
  """
    if isinstance(node, (list, tuple)):
        node_stack = list(node)
    else:
        node_stack = [node]
    if isinstance(other, (list, tuple)):
        other_stack = list(other)
    else:
        other_stack = [other]
    while node_stack and other_stack:
        assert len(node_stack) == len(other_stack)
        n = node_stack.pop()
        o = other_stack.pop()
        if not isinstance(n, (ast.AST, gast.AST, str)) and n is not None or (not isinstance(o, (ast.AST, gast.AST, str)) and n is not None) or n.__class__.__name__ != o.__class__.__name__:
            raise ValueError('inconsistent nodes: {} ({}) and {} ({})'.format(n, n.__class__.__name__, o, o.__class__.__name__))
        yield (n, o)
        if isinstance(n, str):
            assert isinstance(o, str), 'The check above should have ensured this'
            continue
        if n is None:
            assert o is None, 'The check above should have ensured this'
            continue
        for f in n._fields:
            n_child = getattr(n, f, None)
            o_child = getattr(o, f, None)
            if f.startswith('__') or n_child is None or o_child is None:
                continue
            if isinstance(n_child, (list, tuple)):
                if <MASK>:
                    raise ValueError('inconsistent values for field {}: {} and {}'.format(f, n_child, o_child))
                node_stack.extend(n_child)
                other_stack.extend(o_child)
            elif isinstance(n_child, (gast.AST, ast.AST)):
                node_stack.append(n_child)
                other_stack.append(o_child)
            elif n_child != o_child:
                raise ValueError('inconsistent values for field {}: {} and {}'.format(f, n_child, o_child))

def __init__(self, num_embeddings: int, embedding_dim: int, padding_idx: Optional[int]=None, max_norm: Optional[float]=None, norm_type: float=2.0, scale_grad_by_freq: bool=False, sparse: bool=False, _weight: Optional[Tensor]=None, _freeze: bool=False, device=None, dtype=None) -> None:
    factory_kwargs = {'device': device, 'dtype': dtype}
    super().__init__()
    self.num_embeddings = num_embeddings
    self.embedding_dim = embedding_dim
    if padding_idx is not None:
        if <MASK>:
            assert padding_idx < self.num_embeddings, 'Padding_idx must be within num_embeddings'
        elif padding_idx < 0:
            assert padding_idx >= -self.num_embeddings, 'Padding_idx must be within num_embeddings'
            padding_idx = self.num_embeddings + padding_idx
    self.padding_idx = padding_idx
    self.max_norm = max_norm
    self.norm_type = norm_type
    self.scale_grad_by_freq = scale_grad_by_freq
    if _weight is None:
        self.weight = Parameter(torch.empty((num_embeddings, embedding_dim), **factory_kwargs), requires_grad=not _freeze)
        self.reset_parameters()
    else:
        assert list(_weight.shape) == [num_embeddings, embedding_dim], 'Shape of weight does not match num_embeddings and embedding_dim'
        self.weight = Parameter(_weight, requires_grad=not _freeze)
    self.sparse = sparse

