                ops.add_to_collection(ops.GraphKeys.TABLE_INITIALIZERS, init_op)

def items_for_result(cl, result, form):
    """
    Generate the actual list of data.
    """

    def link_in_col(is_first, field_name, cl):
        if cl.list_display_links is None:
            return False
        if is_first and (not cl.list_display_links):
            return True
        return field_name in cl.list_display_links
    first = True
    pk = cl.lookup_opts.pk.attname
    for (field_index, field_name) in enumerate(cl.list_display):
        empty_value_display = cl.model_admin.get_empty_value_display()
        row_classes = ['field-%s' % _coerce_field_name(field_name, field_index)]
        link_to_changelist = link_in_col(first, field_name, cl)
        try:
            (f, attr, value) = lookup_field(field_name, result, cl.model_admin)
        except ObjectDoesNotExist:
            result_repr = empty_value_display
        else:
            empty_value_display = getattr(attr, 'empty_value_display', empty_value_display)
            if isinstance(value, str) and value.strip() == '':
                value = ''
            if f is None or f.auto_created:
                if field_name == 'action_checkbox':
                    row_classes = ['action-checkbox']
                boolean = getattr(attr, 'boolean', False)
                if isinstance(attr, property) and hasattr(attr, 'fget'):
                    boolean = getattr(attr.fget, 'boolean', False)
                result_repr = display_for_value(value, empty_value_display, boolean)
                if isinstance(value, (datetime.date, datetime.time)):
                    row_classes.append('nowrap')
            else:
                if isinstance(f.remote_field, models.ManyToOneRel):
                    field_val = getattr(result, f.name)
                    if field_val is None:
                        result_repr = empty_value_display
                    else:
                        result_repr = field_val
                else:
                    result_repr = display_for_field(value, f, empty_value_display, avoid_link=link_to_changelist)
                if isinstance(f, (models.DateField, models.TimeField, models.ForeignKey)):
                    row_classes.append('nowrap')
        row_class = mark_safe(' class="%s"' % ' '.join(row_classes))
        if link_to_changelist:
            table_tag = 'th' if first else 'td'
            first = False
            try:
                url = cl.url_for_result(result)
            except NoReverseMatch:
                link_or_text = result_repr
            else:
                url = add_preserved_filters({'preserved_filters': cl.preserved_filters, 'opts': cl.opts}, url)
                if cl.to_field:
                    attr = str(cl.to_field)
                else:
                    attr = pk
                value = result.serializable_value(attr)
                link_or_text = format_html('<a href="{}"{}>{}</a>', url, format_html(' data-popup-opener="{}"', value) if cl.is_popup else '', result_repr)
            yield format_html('<{}{}>{}</{}>', table_tag, row_class, link_or_text, table_tag)
        else:
            if form and field_name in form.fields and (not (field_name == cl.model._meta.pk.name and form[cl.model._meta.pk.name].is_hidden)):
                bf = form[field_name]
                result_repr = mark_safe(str(bf.errors) + str(bf))
            yield format_html('<td{}>{}</td>', row_class, result_repr)
    if <MASK>:
        yield format_html('<td>{}</td>', form[cl.model._meta.pk.name])

def most_specific_common_supertype(self, others):
    if any((type(self) is not type(other) for other in others)):
        return None
    if self.alias_id is None and all((other.alias_id is None for other in others)):
        return super().most_specific_common_supertype(others)
    if <MASK>:
        raise NotImplementedError(f"VariableSpec.most_specific_common_supertype doesn't support alias_id=None, got self: {self} and others: {others}.")
    return super().most_specific_common_supertype(others)

def _get_amdsmi_clock_rate(device: 'Device'=None) -> int:
    handle = _get_amdsmi_handler(device)
    clock_info = amdsmi.amdsmi_get_clock_info(handle, amdsmi.AmdSmiClkType.GFX)
    if 'cur_clk' in clock_info:
        clock_rate = clock_info['cur_clk']
    else:
        clock_rate = clock_info['clk']
    if <MASK>:
        return clock_rate
    else:
        return 0

@generic_utils.default
def build(self, input_shape):
    """Builds the model based on input shapes received.

    This is to be used for subclassed models, which do not know at instantiation
    time what their inputs look like.

    This method only exists for users who want to call `model.build()` in a
    standalone way (as a substitute for calling the model on real data to
    build it). It will never be called by the framework (and thus it will
    never throw unexpected errors in an unrelated workflow).

    Args:
     input_shape: Single tuple, TensorShape, or list/dict of shapes, where
         shapes are tuples, integers, or TensorShapes.

    Raises:
      ValueError:
        1. In case of invalid user-provided data (not of type tuple,
           list, TensorShape, or dict).
        2. If the model requires call arguments that are agnostic
           to the input shapes (positional or kwarg in call signature).
        3. If not all layers were properly built.
        4. If float type inputs are not supported within the layers.

      In each of these cases, the user should build their model by calling it
      on real tensor data.
    """
    if self._is_graph_network:
        super(Model, self).build(input_shape)
        return
    if input_shape is None:
        raise ValueError('Input shape must be defined when calling build on a model subclass network.')
    valid_types = (tuple, list, tensor_shape.TensorShape, dict)
    if not isinstance(input_shape, valid_types):
        raise ValueError('Specified input shape is not one of the valid types. Please specify a batch input shape of type tuple or list of input shapes. User provided input type: {}'.format(type(input_shape)))
    if input_shape and (not self.inputs):
        if context.executing_eagerly():
            graph = func_graph.FuncGraph('build_graph')
        else:
            graph = backend.get_graph()
        with graph.as_default():
            if isinstance(input_shape, list) and all((d is None or isinstance(d, int) for d in input_shape)):
                input_shape = tuple(input_shape)
            if isinstance(input_shape, list):
                x = [base_layer_utils.generate_placeholders_from_shape(shape) for shape in input_shape]
            elif isinstance(input_shape, dict):
                x = {k: base_layer_utils.generate_placeholders_from_shape(shape) for (k, shape) in input_shape.items()}
            else:
                x = base_layer_utils.generate_placeholders_from_shape(input_shape)
            kwargs = {}
            call_signature = self._call_full_argspec
            call_args = call_signature.args
            if len(call_args) > 2:
                if call_signature.defaults:
                    call_args = call_args[2:-len(call_signature.defaults)]
                else:
                    call_args = call_args[2:]
                for arg in call_args:
                    if arg == 'training':
                        kwargs['training'] = False
                    else:
                        raise ValueError('Currently, you cannot build your model if it has positional or keyword arguments that are not inputs to the model, but are required for its `call` method. Instead, in order to instantiate and build your model, `call` your model on real tensor data with all expected call arguments.')
            elif <MASK>:
                raise ValueError('You can only call `build` on a model if its `call` method accepts an `inputs` argument.')
            try:
                self.call(x, **kwargs)
            except (errors.InvalidArgumentError, TypeError):
                raise ValueError('You cannot build your model by calling `build` if your layers do not support float type inputs. Instead, in order to instantiate and build your model, `call` your model on real tensor data (of the correct dtype).')
    super(Model, self).build(input_shape)

def forward(self, input: Tensor, hx: Optional[Tensor]=None) -> Tensor:
    if input.dim() not in (1, 2):
        raise ValueError(f'GRUCell: Expected input to be 1D or 2D, got {input.dim()}D instead')
    if hx is not None and hx.dim() not in (1, 2):
        raise ValueError(f'GRUCell: Expected hidden to be 1D or 2D, got {hx.dim()}D instead')
    is_batched = input.dim() == 2
    if <MASK>:
        input = input.unsqueeze(0)
    if hx is None:
        hx = torch.zeros(input.size(0), self.hidden_size, dtype=input.dtype, device=input.device)
    else:
        hx = hx.unsqueeze(0) if not is_batched else hx
    ret = _VF.gru_cell(input, hx, self.weight_ih, self.weight_hh, self.bias_ih, self.bias_hh)
    if not is_batched:
        ret = ret.squeeze(0)
    return ret

def call_method(self, tx, name, args: list['VariableTracker'], kwargs: dict[str, 'VariableTracker']) -> 'VariableTracker':
    if name == '__contains__':
        return self.dv_dict.call_method(tx, name, args, kwargs)
    elif name in ('__and__', '__iand__', '__or__', '__ior__', '__sub__', '__isub__', '__xor__', '__ixor__'):
        m = getattr(self.set_items, name)
        r = m(args[0].set_items)
        return SetVariable(r)
    if name in cmp_name_to_op_mapping:
        if <MASK>:
            return ConstantVariable.create(NotImplemented)
        return ConstantVariable.create(cmp_name_to_op_mapping[name](self.set_items, args[0].set_items))
    return super().call_method(tx, name, args, kwargs)

def _recode_for_new_levels(self, new_levels, *, copy: bool) -> Generator[np.ndarray]:
    if <MASK>:
        raise AssertionError(f'Length of new_levels ({len(new_levels)}) must be <= self.nlevels ({self.nlevels})')
    for i in range(len(new_levels)):
        yield recode_for_categories(self.codes[i], self.levels[i], new_levels[i], copy=copy)

