def pretty_print_buckets(buckets: list[Bucket], bucket_bytes_cap: int) -> None:
    headers = ('Index', 'Size (b)', 'Param Names')
    rows: list[tuple[Optional[int], Optional[int], str]] = []
    extended_buckets = []
    for (idx, bucket) in enumerate(reversed(buckets)):
        if len(bucket.params) > 0:
            rows.append((idx, bucket.size, bucket.params[0]))
            rows.extend(((None, None, param) for param in bucket.params[1:]))
        if bucket.opcount_increased_to_capture_external_output > 0:
            extended_buckets.append((idx, bucket.opcount_increased_to_capture_external_output, bucket.size - bucket.paramsize_before_opcount_increase))
    if rows:
        log.info('\nDDPOptimizer used bucket cap %s and created %d buckets. Enable debug logs for detailed bucket info.', bucket_bytes_cap, len(buckets))
        if <MASK>:
            log.warning('Some buckets were extended beyond their requested parameter capacities in order to ensure each subgraph has an output node, required for fx graph partitioning. This can be the case when a subgraph would have only contained nodes performing inplace mutation, and returning no logical outputs. This should not be a problem, unless it results in too few graph partitions for optimal DDP performance.')
        try:
            from tabulate import tabulate
            log.debug('\nDDPOptimizer produced the following bucket assignments:\n%s', tabulate(rows, headers=headers, tablefmt='simple_grid'))
            if extended_buckets:
                log.warning('DDPOptimizer extended these buckets to ensure per-subgraph output nodes:\n%s', tabulate(extended_buckets, headers=('Index', 'Extra Ops', 'Extra Param Size (b)'), tablefmt='simple_grid'))
        except ImportError:
            log.debug('Please `pip install tabulate` in order to display ddp bucket sizes and diagnostic information.')
    else:
        log.debug('DDPOptimizer captured no parameters and did not split this graph.')

def get_device_context(device: Optional[str]=None) -> DeviceContext:
    if device is None:
        device = torch._C._lazy._get_default_device_type()
    else:
        device = str(device)
    with DeviceContext._CONTEXTS_LOCK:
        devctx = DeviceContext._CONTEXTS.get(device, None)
        if <MASK>:
            devctx = DeviceContext(device)
            DeviceContext._CONTEXTS[device] = devctx
        return devctx

def make_sourced_prefixes(nn_module, args, kwargs) -> _KeyPathTrie:
    (kp_args, kp_kwargs) = tree_map_with_path(lambda kp, _: _KeyPath(kp), (tuple((None for _ in args)), {k: None for k in kwargs}))
    kp_combined_args = _combine_args(nn_module, kp_args, kp_kwargs)
    sourced_prefixes = _KeyPathTrie()
    for (name, struct) in kp_combined_args.items():
        src = LocalSource(name)
        if isinstance(struct, _KeyPath):
            sourced_prefixes.add(struct.kp, src)
        elif isinstance(struct, tuple):
            for (i, prefix) in enumerate(struct):
                assert isinstance(prefix, _KeyPath)
                sourced_prefixes.add(prefix.kp, GetItemSource(src, i))
        elif <MASK>:
            for (k, prefix) in struct.items():
                assert isinstance(prefix, _KeyPath)
                sourced_prefixes.add(prefix.kp, GetItemSource(src, k))
    return sourced_prefixes

def parse(self, parse_until=None):
    """
        Iterate through the parser tokens and compiles each one into a node.

        If parse_until is provided, parsing will stop once one of the
        specified tokens has been reached. This is formatted as a list of
        tokens, e.g. ['elif', 'else', 'endif']. If no matching token is
        reached, raise an exception with the unclosed block tag details.
        """
    if parse_until is None:
        parse_until = []
    nodelist = NodeList()
    while self.tokens:
        token = self.next_token()
        token_type = token.token_type.value
        if token_type == 0:
            self.extend_nodelist(nodelist, TextNode(token.contents), token)
        elif token_type == 1:
            if not token.contents:
                raise self.error(token, 'Empty variable tag on line %d' % token.lineno)
            try:
                filter_expression = self.compile_filter(token.contents)
            except TemplateSyntaxError as e:
                raise self.error(token, e)
            var_node = VariableNode(filter_expression)
            self.extend_nodelist(nodelist, var_node, token)
        elif <MASK>:
            try:
                command = token.contents.split()[0]
            except IndexError:
                raise self.error(token, 'Empty block tag on line %d' % token.lineno)
            if command in parse_until:
                self.prepend_token(token)
                return nodelist
            self.command_stack.append((command, token))
            try:
                compile_func = self.tags[command]
            except KeyError:
                self.invalid_block_tag(token, command, parse_until)
            try:
                compiled_result = compile_func(self, token)
            except Exception as e:
                raise self.error(token, e)
            self.extend_nodelist(nodelist, compiled_result, token)
            self.command_stack.pop()
    if parse_until:
        self.unclosed_block_tag(parse_until)
    return nodelist

def fit(self, X, y, sample_weight=None):
    (xp, is_array_api_compliant) = get_namespace(X, y, sample_weight)
    if self.solver == 'lbfgs' and (not self.positive):
        raise ValueError("'lbfgs' solver can be used only when positive=True. Please use another solver.")
    if self.positive:
        if self.solver not in ['auto', 'lbfgs']:
            raise ValueError(f"solver='{self.solver}' does not support positive fitting. Please set the solver to 'auto' or 'lbfgs', or set `positive=False`")
        else:
            solver = self.solver
    elif sparse.issparse(X) and self.fit_intercept:
        if self.solver not in ['auto', 'lbfgs', 'lsqr', 'sag', 'sparse_cg']:
            raise ValueError("solver='{}' does not support fitting the intercept on sparse data. Please set the solver to 'auto' or 'lsqr', 'sparse_cg', 'sag', 'lbfgs' or set `fit_intercept=False`".format(self.solver))
        if self.solver in ['lsqr', 'lbfgs']:
            solver = self.solver
        elif self.solver == 'sag' and self.max_iter is None and (self.tol > 0.0001):
            warnings.warn('"sag" solver requires many iterations to fit an intercept with sparse inputs. Either set the solver to "auto" or "sparse_cg", or set a low "tol" and a high "max_iter" (especially if inputs are not standardized).')
            solver = 'sag'
        else:
            solver = 'sparse_cg'
    else:
        solver = self.solver
    if <MASK>:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    (X, y, X_offset, y_offset, X_scale, _) = _preprocess_data(X, y, fit_intercept=self.fit_intercept, copy=self.copy_X, sample_weight=sample_weight, rescale_with_sw=False)
    if solver == 'sag' and sparse.issparse(X) and self.fit_intercept:
        (self.coef_, self.n_iter_, self.intercept_, self.solver_) = _ridge_regression(X, y, alpha=self.alpha, sample_weight=sample_weight, max_iter=self.max_iter, tol=self.tol, solver='sag', positive=self.positive, random_state=self.random_state, return_n_iter=True, return_intercept=True, return_solver=True, check_input=False)
        self.intercept_ += y_offset
    else:
        if sparse.issparse(X) and self.fit_intercept:
            params = {'X_offset': X_offset, 'X_scale': X_scale}
        else:
            params = {}
        (self.coef_, self.n_iter_, self.solver_) = _ridge_regression(X, y, alpha=self.alpha, sample_weight=sample_weight, max_iter=self.max_iter, tol=self.tol, solver=solver, positive=self.positive, random_state=self.random_state, return_n_iter=True, return_intercept=False, return_solver=True, check_input=False, fit_intercept=self.fit_intercept, **params)
        self._set_intercept(X_offset, y_offset, X_scale)
    return self

def _get_counts(values_shape: Shape, mask: npt.NDArray[np.bool_] | None, axis: AxisInt | None, dtype: np.dtype[np.floating]=np.dtype(np.float64)) -> np.floating | npt.NDArray[np.floating]:
    """
    Get the count of non-null values along an axis

    Parameters
    ----------
    values_shape : tuple of int
        shape tuple from values ndarray, used if mask is None
    mask : Optional[ndarray[bool]]
        locations in values that should be considered missing
    axis : Optional[int]
        axis to count along
    dtype : type, optional
        type to use for count

    Returns
    -------
    count : scalar or array
    """
    if axis is None:
        if <MASK>:
            n = mask.size - mask.sum()
        else:
            n = np.prod(values_shape)
        return dtype.type(n)
    if mask is not None:
        count = mask.shape[axis] - mask.sum(axis)
    else:
        count = values_shape[axis]
    if is_integer(count):
        return dtype.type(count)
    return count.astype(dtype, copy=False)

def embedding_lookup_sparse_impl(params, segment_ids, sp_weights, ids, combiner, ignore_weights, max_norm, allow_fast_lookup, partition_strategy, name):
    """Implementation of sparse embedding aggregation."""
    need_sparse_segment_gradient = False
    segment_ids = ops.convert_to_tensor(segment_ids, name='segment_ids')
    if len(params) == 1 and (not isinstance(params[0], (core.Tensor, composite_tensor.CompositeTensor))):
        params = [ops.convert_to_tensor(params[0], name='params')]
    if <MASK>:
        idx = ids
        embeddings = params[0]
        if isinstance(embeddings, resource_variable_ops.BaseResourceVariable):
            embeddings = embeddings.read_value_no_copy()
        if not allow_fast_lookup:
            need_sparse_segment_gradient = True
    else:
        (ids, idx) = array_ops.unique(ids)
        embeddings = embedding_lookup(params, ids, partition_strategy=partition_strategy, max_norm=max_norm)
    if not ignore_weights:
        if segment_ids.dtype != dtypes.int32:
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        weights = sp_weights.values
        embeddings = array_ops.gather(embeddings, idx)
        original_dtype = embeddings.dtype
        if embeddings.dtype in (dtypes.float16, dtypes.bfloat16):
            embeddings = math_ops.cast(embeddings, dtypes.float32)
        if weights.dtype != embeddings.dtype:
            weights = math_ops.cast(weights, embeddings.dtype)
        ones_shape = array_ops.expand_dims(array_ops.rank(embeddings) - 1, 0)
        weights_shape = array_ops.shape(weights)
        ones = array_ops.ones(ones_shape, dtype=weights_shape.dtype)
        bcast_weights_shape = array_ops.concat([weights_shape, ones], 0)
        orig_weights_shape = weights.get_shape()
        weights = array_ops.reshape(weights, bcast_weights_shape)
        if embeddings.get_shape().ndims is not None:
            weights.set_shape(orig_weights_shape.concatenate([1 for _ in range(embeddings.get_shape().ndims - 1)]))
        embeddings *= weights
        if combiner == 'sum':
            embeddings = math_ops.segment_sum(embeddings, segment_ids, name=name)
        elif combiner == 'mean':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weight_sum = math_ops.segment_sum(weights, segment_ids)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum, name=name)
        elif combiner == 'sqrtn':
            embeddings = math_ops.segment_sum(embeddings, segment_ids)
            weights_squared = math_ops.pow(weights, 2)
            weight_sum = math_ops.segment_sum(weights_squared, segment_ids)
            weight_sum_sqrt = math_ops.sqrt(weight_sum)
            embeddings = math_ops.div_no_nan(embeddings, weight_sum_sqrt, name=name)
        else:
            assert False, 'Unrecognized combiner'
        if embeddings.dtype != original_dtype:
            embeddings = math_ops.cast(embeddings, original_dtype)
    else:
        if segment_ids.dtype not in (dtypes.int32, dtypes.int64):
            segment_ids = math_ops.cast(segment_ids, dtypes.int32)
        assert idx is not None
        if combiner == 'sum':
            embeddings = math_ops.sparse_segment_sum(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'mean':
            embeddings = math_ops.sparse_segment_mean(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        elif combiner == 'sqrtn':
            embeddings = math_ops.sparse_segment_sqrt_n(embeddings, idx, segment_ids, name=name, sparse_gradient=need_sparse_segment_gradient)
        else:
            assert False, 'Unrecognized combiner'
    return embeddings

def any(x: Array, /, *, axis: Optional[Union[int, Tuple[int, ...]]]=None, keepdims: bool=False, **kwargs) -> Array:
    if axis == ():
        return x.to(torch.bool)
    if <MASK>:
        res = _reduce_multiple_axes(torch.any, x, axis, keepdims=keepdims, **kwargs)
        return res.to(torch.bool)
    if axis is None:
        res = torch.any(x, **kwargs)
        res = _axis_none_keepdims(res, x.ndim, keepdims)
        return res.to(torch.bool)
    return torch.any(x, axis, keepdims=keepdims).to(torch.bool)

def _align_for_op(self, other, axis: AxisInt, flex: bool | None=False, level: Level | None=None):
    """
        Convert rhs to meet lhs dims if input is list, tuple or np.ndarray.

        Parameters
        ----------
        other : Any
        axis : int
        flex : bool or None, default False
            Whether this is a flex op, in which case we reindex.
            None indicates not to check for alignment.
        level : int or level name, default None

        Returns
        -------
        left : DataFrame
        right : Any
        """
    (left, right) = (self, other)

    def to_series(right):
        msg = 'Unable to coerce to Series, length must be {req_len}: given {given_len}'
        dtype = None
        if getattr(right, 'dtype', None) == object:
            dtype = object
        if axis == 0:
            if len(left.index) != len(right):
                raise ValueError(msg.format(req_len=len(left.index), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.index, dtype=dtype)
        else:
            if len(left.columns) != len(right):
                raise ValueError(msg.format(req_len=len(left.columns), given_len=len(right)))
            right = left._constructor_sliced(right, index=left.columns, dtype=dtype)
        return right
    if isinstance(right, np.ndarray):
        if right.ndim == 1:
            right = to_series(right)
        elif right.ndim == 2:
            dtype = None
            if right.dtype == object:
                dtype = object
            if right.shape == left.shape:
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[0] == left.shape[0] and right.shape[1] == 1:
                right = np.broadcast_to(right, left.shape)
                right = left._constructor(right, index=left.index, columns=left.columns, dtype=dtype)
            elif right.shape[1] == left.shape[1] and right.shape[0] == 1:
                right = to_series(right[0, :])
            else:
                raise ValueError(f'Unable to coerce to DataFrame, shape must be {left.shape}: given {right.shape}')
        elif right.ndim > 2:
            raise ValueError(f'Unable to coerce to Series/DataFrame, dimension must be <= 2: {right.shape}')
    elif is_list_like(right) and (not isinstance(right, (Series, DataFrame))):
        if <MASK>:
            raise ValueError(f'Unable to coerce list of {type(right[0])} to Series/DataFrame')
        right = to_series(right)
    if flex is not None and isinstance(right, DataFrame):
        if not left._indexed_same(right):
            if flex:
                (left, right) = left.align(right, join='outer', level=level)
            else:
                raise ValueError('Can only compare identically-labeled (both index and columns) DataFrame objects')
    elif isinstance(right, Series):
        axis = axis if axis is not None else 1
        if not flex:
            if not left.axes[axis].equals(right.index):
                raise ValueError('Operands are not aligned. Do `left, right = left.align(right, axis=1)` before operating.')
        (left, right) = left.align(right, join='outer', axis=axis, level=level)
        right = left._maybe_align_series_as_frame(right, axis)
    return (left, right)

def _pprint_dict(seq: Mapping, _nest_lvl: int=0, max_seq_items: int | None=None, **kwds: Any) -> str:
    """
    internal. pprinter for iterables. you should probably use pprint_thing()
    rather than calling this directly.
    """
    fmt = '{{{things}}}'
    pairs = []
    pfmt = '{key}: {val}'
    if max_seq_items is False:
        nitems = len(seq)
    else:
        nitems = max_seq_items or get_option('max_seq_items') or len(seq)
    for (k, v) in list(seq.items())[:nitems]:
        pairs.append(pfmt.format(key=pprint_thing(k, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds), val=pprint_thing(v, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds)))
    if <MASK>:
        return fmt.format(things=', '.join(pairs) + ', ...')
    else:
        return fmt.format(things=', '.join(pairs))

@register_rng_decomposition(aten.rand_like)
def rand_like(x: torch.Tensor, dtype=None, layout=None, device=None, pin_memory=False, memory_format=torch.preserve_format):
    device = device or x.device
    if <MASK>:
        throw_on_non_cuda(device)
    dtype = dtype or x.dtype
    (seed, offset) = PhiloxStateTracker.get_state_as_tuple()
    (out, offset_jump) = torch.ops.rngprims.philox_rand(x.shape, seed, offset, None, device, dtype)
    PhiloxStateTracker.advance_offset(offset_jump)
    return out

def get_assignments_with_compile_ignored_comments(module: ModuleType) -> set[str]:
    source_code = inspect.getsource(module)
    assignments = set()
    tokens = tokenize.tokenize(io.BytesIO(source_code.encode('utf-8')).readline)
    current_comment = ('', -1)
    prev_name = ''
    for token in tokens:
        if token.type == tokenize.COMMENT:
            prev_name = ''
            maybe_current = token.string.strip()
            if COMPILE_IGNORED_MARKER in maybe_current:
                assert current_comment == ('', -1), f'unconsumed {COMPILE_IGNORED_MARKER}'
                current_comment = (maybe_current, token.start[0])
        elif token.type == tokenize.NAME:
            if not prev_name:
                prev_name = token.string
        elif <MASK>:
            if COMPILE_IGNORED_MARKER in current_comment[0] and current_comment[1] == token.start[0] - 1:
                assignments.add(prev_name)
                current_comment = ('', -1)
            prev_name = ''
    assert current_comment == ('', -1), f'unconsumed {COMPILE_IGNORED_MARKER}'
    return assignments

@staticmethod
def build_Print(ctx, stmt):
    r = ctx.make_range(stmt.lineno, stmt.col_offset, stmt.col_offset + len('print'))
    if <MASK>:
        raise NotSupportedError(r, "print statements with non-default destinations aren't supported")
    args = [build_expr(ctx, val) for val in stmt.values]
    return ExprStmt(Apply(Var(Ident(r, 'print')), args, []))

def _download_artifact(artifact_name: Path, artifact_url: str, workflow_run_attempt: int) -> Path:
    atoms = str(artifact_name).split('-')
    for atom in atoms:
        if <MASK>:
            found_run_attempt = int(atom[len('runattempt'):])
            if workflow_run_attempt != found_run_attempt:
                print(f'Skipping {artifact_name} as it is an invalid run attempt. Expected {workflow_run_attempt}, found {found_run_attempt}.')
    print(f'Downloading {artifact_name}')
    response = requests.get(artifact_url, headers=_get_request_headers())
    with open(artifact_name, 'wb') as f:
        f.write(response.content)
    return artifact_name

def main() -> None:
    ref = os.environ['GITHUB_REF']
    m = re.match('^refs/(\\w+)/(.*)$', ref)
    if <MASK>:
        (category, stripped) = m.groups()
        if category == 'heads':
            set_output('branch', stripped)
        elif category == 'pull':
            set_output('branch', 'pull/' + stripped.split('/')[0])
        elif category == 'tags':
            set_output('tag', stripped)

