def __or__(self, other: TestRun) -> TestRun:
    """
        To OR/Union test runs means to run all the tests that either of the two runs specify.
        """
    if self.is_empty():
        return other
    if other.is_empty():
        return copy(self)
    assert self.test_file == other.test_file, f"Can't exclude {other} from {self} because they're not the same test file"
    if self.is_full_file() or other.is_full_file():
        return TestRun(self.test_file)
    if self._included and other._included:
        return TestRun(self.test_file, included=self._included.union(other._included))
    if <MASK>:
        return TestRun(self.test_file, excluded=self._excluded.intersection(other._excluded))
    included = self._included | other._included
    excluded = self._excluded | other._excluded
    return TestRun(self.test_file, excluded=excluded - included)

def _safe_repr(object, context, maxlevels, level, changed_only=False):
    """Same as the builtin _safe_repr, with added support for Estimator
    objects."""
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if <MASK>:
        if not object:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if issubclass(typ, list) and r is list.__repr__ or (issubclass(typ, tuple) and r is tuple.__repr__):
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            (orepr, oreadable, orecur) = _safe_repr(o, context, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if not oreadable:
                readable = False
            if orecur:
                recursive = True
        del context[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for (k, v) in items:
            (krepr, kreadable, krecur) = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            (vrepr, vreadable, vrecur) = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

def fn_prepped_for_autograd(fn: TraceFn, args_descs: list[AOTInput], meta: ViewAndMutationMeta, aot_config: AOTConfig) -> PreppedForAutogradTraceFn:

    @simple_wraps(fn)
    def inner_fn(*args):
        args_maybe_cloned = [maybe_to_fresh_input(i, t, meta) for (i, t) in enumerate(args)]
        (outs, outs_descs) = call_and_expect_output_descs(fn, args_maybe_cloned)
        assert isinstance(outs, (tuple, list))
        outs = list(outs)
        assert len(meta.output_info) == len(outs)
        mutated_input_pairs = [(x, InputMutationAOTOutput(src)) for (i, (x, src)) in enumerate(zip(args_maybe_cloned, args_descs)) if i in meta.mutated_inp_runtime_indices]
        if mutated_input_pairs:
            (mutated_inputs_to_return, mutated_inputs_to_return_descs) = zip(*mutated_input_pairs)
        else:
            (mutated_inputs_to_return, mutated_inputs_to_return_descs) = ((), ())
        intermediate_bases = []
        intermediate_bases_descs = []
        for (o, info, o_desc) in zip(outs, meta.output_info, outs_descs):
            if info.output_type == OutputType.alias_of_intermediate_save_as_output:
                assert isinstance(o, torch.Tensor), f'Expected tensor for intermediate base, got {type(o)}'
                intermediate_bases.append(o._base)
                intermediate_bases_descs.append(IntermediateBaseAOTOutput(o_desc))
        assert meta.num_intermediate_bases == len(intermediate_bases)
        fw_outs_to_return = (*mutated_inputs_to_return, *outs, *intermediate_bases)
        fw_outs_to_return_descs = (*mutated_inputs_to_return_descs, *outs_descs, *intermediate_bases_descs)
        mutated_inputs_grad_mask = [meta.input_info[meta.mutated_inp_runtime_indices[i]].mutates_data and meta.input_info[meta.mutated_inp_runtime_indices[i]].requires_grad for (i, x) in enumerate(mutated_inputs_to_return)]
        output_grad_mask = [meta.output_info[i].output_type in [OutputType.non_alias, OutputType.unsafe_view_alias, OutputType.custom_function_view] and issubclass(meta.output_info[i].raw_type, Tensor) and meta.output_info[i].requires_grad for (i, x) in enumerate(outs)]
        intermediate_base_grad_mask = [True for _ in range(len(intermediate_bases))]
        out_grad_mask = mutated_inputs_grad_mask + output_grad_mask + intermediate_base_grad_mask
        assert len(out_grad_mask) == len(fw_outs_to_return)
        if not aot_config.disable_functionalization:
            for arg in args_maybe_cloned:
                if <MASK>:
                    continue
                sync_functional_tensor(arg)
        return ((fw_outs_to_return, out_grad_mask), (fw_outs_to_return_descs, out_grad_mask))
    return inner_fn

@classmethod
@functools.lru_cache(32)
def candidate_tilings(cls, node, numel, reduction_numel) -> list[CandidateTiling]:
    is_pointwise = reduction_numel == 1

    def tile_ranges(is_pointwise: bool, ranges, rw) -> list[CandidateTiling]:
        """
            Compute tiling candidates by dividing up the iteration ranges.
            """
        assert len(rw.range_vars) == len(ranges), f'rw.range_vars={rw.range_vars!r} ranges={ranges!r}'
        dep_sources = [rw.reads, rw.writes]
        assert all((isinstance(dep, (MemoryDep, StarDep)) for dep in itertools.chain.from_iterable(dep_sources)))
        deps = [dep for dep in itertools.chain.from_iterable(dep_sources) if dep.name not in V.graph.removed_buffers and isinstance(dep, MemoryDep)]
        write_names = OrderedSet([dep.name for dep in rw.writes])

        def collapse_ranges(ranges: Sequence[sympy.Expr]) -> sympy.Expr:
            return V.graph.sizevars.simplify(sympy_product(ranges))
        tilings = [CandidateTiling(tiling=cls.create_partial_tiling([collapse_ranges(ranges)], is_pointwise), name='none', score=0)]
        for dep in deps:
            strides = V.graph.sizevars.stride_hints(dep.index, rw.range_vars)
            assert len(strides) == len(ranges)
            try:
                split = strides.index(1) + 1
                if split == len(ranges):
                    continue
                if all((s == 0 for s in strides[split:])):
                    continue
            except ValueError:
                continue
            tiled_groups = (collapse_ranges(ranges[:split]), collapse_ranges(ranges[split:]))
            score = V.graph.sizevars.size_hint(sympy_product((size for (size, stride) in zip(ranges, strides) if stride != 0)))
            if dep.name in write_names:
                score *= 2
            if CandidateTiling.is_good_size(tiled_groups[0]):
                score *= 2
            if <MASK>:
                score *= 2
            if V.graph.sizevars.size_hint(score - sympy_product(itertools.chain(ranges, reduction_ranges))) >= 0:
                tilings.append(CandidateTiling(tiling=cls.create_partial_tiling([collapse_ranges(ranges[:split]), collapse_ranges(ranges[split:])], reduction_numel), score=score, name=dep.name))
        return tilings
    (pointwise_ranges, reduction_ranges) = node.get_ranges()
    if len(pointwise_ranges) <= 1 and len(reduction_ranges) <= 1 or free_unbacked_symbols(pointwise_ranges + reduction_ranges):
        return []
    (pointwise_ranges, reduction_ranges) = node.get_ranges()
    partial_tilings = tile_ranges(is_pointwise, pointwise_ranges if is_pointwise else reduction_ranges, node.pointwise_or_reduction_read_writes(is_pointwise))
    full_tilings = [CandidateTiling(tiling=cls.complete_partial_tiling(tiling.tiling, numel, reduction_numel), score=tiling.score, name=tiling.name) for tiling in partial_tilings]
    return full_tilings

def load_layers(self, compile=True):
    """Load all layer nodes from the metadata."""
    metric_list = []
    for node_metadata in self._metadata.values():
        if node_metadata.identifier == constants.METRIC_IDENTIFIER:
            metric_list.append(node_metadata)
            continue
        self.loaded_nodes[node_metadata.node_id] = self._load_layer(node_metadata.node_id, node_metadata.identifier, node_metadata.metadata)
    for node_metadata in metric_list:
        try:
            self.loaded_nodes[node_metadata.node_id] = self._load_layer(node_metadata.node_id, node_metadata.identifier, node_metadata.metadata)
        except ValueError:
            if <MASK>:
                raise
            logging.warning('Unable to restore custom metric. Please ensure that the layer implements `get_config` and `from_config` when saving. In addition, please use the `custom_objects` arg when calling `load_model()`.')

def _model_loss(model, inputs, targets, output_loss_metrics=None, sample_weights=None, training=False):
    """Calculates the loss for a given model.

  Args:
      model: The model on which metrics are being calculated.
      inputs: Either a dictionary of inputs to the model or a list of input
        arrays.
      targets: List of target arrays.
      output_loss_metrics: List of metrics that are used to aggregated output
        loss values.
      sample_weights: Optional list of sample weight arrays.
      training: Whether the model should be run in inference or training mode.

  Returns:
     Returns the model output, total loss, loss value calculated using the
     specified loss function and masks for each output. The total loss includes
     regularization losses and applies masking and sample weighting
     to the loss value.
  """
    total_loss = 0
    kwargs = {}
    if model._expects_training_arg:
        kwargs['training'] = training
    if len(inputs) == 1 and (not isinstance(inputs, dict)):
        inputs = inputs[0]
    if any((isinstance(input_t, (np.ndarray, float, int)) for input_t in nest.flatten(inputs))):
        inputs = nest.map_structure(tensor_conversion.convert_to_tensor_v2_with_dispatch, inputs)
    outs = model(inputs, **kwargs)
    outs = nest.flatten(outs)
    if targets:
        targets = training_utils_v1.cast_if_floating_dtype_and_mismatch(targets, outs)
    if <MASK>:
        new_sample_weights = []
        for val in sample_weights:
            if val is not None:
                new_sample_weights.append(training_utils_v1.cast_if_floating_dtype(tensor_conversion.convert_to_tensor_v2_with_dispatch(val)))
            else:
                new_sample_weights.append(None)
        sample_weights = new_sample_weights
    masks = [getattr(t, '_keras_mask', None) for t in outs]
    targets = nest.flatten(targets)
    output_losses = []
    with backend.name_scope('loss'):
        loss_fns = [loss_fn for loss_fn in model.loss_functions if loss_fn is not None]
        custom_losses = model.losses
        if not loss_fns and (not custom_losses):
            if training:
                raise ValueError('The model cannot be trained because it has no loss to optimize.')
            else:
                raise ValueError('The model cannot be evaluated because it has no loss to compute.')
        for (i, loss_fn) in enumerate(loss_fns):
            weights = sample_weights[i] if sample_weights else None
            mask = masks[i]
            with backend.name_scope(model.output_names[i] + '_loss'):
                if mask is not None:
                    mask = math_ops.cast(mask, outs[i].dtype)
                    if weights is None:
                        weights = mask
                    else:
                        weights = math_ops.cast(weights, outs[i].dtype)
                        (mask, _, weights) = losses_utils.squeeze_or_expand_dimensions(mask, sample_weight=weights)
                        weights *= mask
                if hasattr(loss_fn, 'reduction'):
                    per_sample_losses = loss_fn.call(targets[i], outs[i])
                    weighted_losses = losses_utils.compute_weighted_loss(per_sample_losses, sample_weight=weights, reduction=losses_utils.ReductionV2.NONE)
                    loss_reduction = loss_fn.reduction
                    if loss_reduction == losses_utils.ReductionV2.AUTO:
                        loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
                    output_loss = losses_utils.reduce_weighted_loss(weighted_losses, reduction=loss_reduction)
                else:
                    output_loss = loss_fn(targets[i], outs[i], sample_weight=weights)
                    loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
            if len(model.outputs) > 1:
                output_losses.append(output_loss_metrics[i](output_loss))
            if loss_reduction == losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE:
                output_loss = losses_utils.scale_loss_for_distribution(output_loss)
            total_loss += model._loss_weights_list[i] * output_loss
        if custom_losses:
            total_loss += losses_utils.scale_loss_for_distribution(math_ops.add_n(custom_losses))
    return (outs, total_loss, output_losses, masks)

