def _make_layer(self, block, planes, blocks, stride=1, dilate=False):
    norm_layer = self._norm_layer
    downsample = None
    previous_dilation = self.dilation
    if <MASK>:
        self.dilation *= stride
        stride = 1
    if stride != 1 or self.inplanes != planes * block.expansion:
        downsample = nn.Sequential(conv1x1(self.inplanes, planes * block.expansion, stride), norm_layer(planes * block.expansion))
    layers = []
    layers.append(block(self.inplanes, planes, stride, downsample, self.groups, self.base_width, previous_dilation, norm_layer))
    self.inplanes = planes * block.expansion
    for _ in range(1, blocks):
        layers.append(block(self.inplanes, planes, groups=self.groups, base_width=self.base_width, dilation=self.dilation, norm_layer=norm_layer))
    return nn.Sequential(*layers)

@contextmanager
def print_repro_on_failure(repro_parts):
    try:
        yield
    except unittest.SkipTest:
        raise
    except Exception as e:
        sample_isolation_prefix = ''
        tracked_input = getattr(e, '_tracked_input', None)
        if <MASK>:
            sample_isolation_prefix = f'PYTORCH_OPINFO_SAMPLE_INPUT_INDEX={tracked_input.index}'
        repro_str = ' '.join(filter(None, (sample_isolation_prefix, *repro_parts)))
        open_source_signpost(subsystem='test_repros', name='test_failure', parameters=json.dumps({'repro': ' '.join(filter(None, (sample_isolation_prefix, *repro_parts)))}))
        repro_msg = f'\nTo execute this test, run the following from the base repo dir:\n    {repro_str}\n\nThis message can be suppressed by setting PYTORCH_PRINT_REPRO_ON_FAILURE=0'
        if len(e.args) >= 1:
            e.args = (f'{e.args[0]}\n{repro_msg}', *e.args[1:])
        raise

def is_boolean_type(x):
    if <MASK>:
