def as_signature_def(self, receiver_tensors):
    if len(receiver_tensors) != 1:
        raise ValueError(f'Regression signatures can only accept a single tensor input of type tf.string. Please check to make sure that you have structured the serving_input_receiver_fn so that it creates a single string placeholder. If your model function expects multiple inputs, then use `tf.io.parse_example()` to parse the string into multiple tensors.\n Received: {receiver_tensors}')
    ((_, examples),) = receiver_tensors.items()
    if <MASK>:
        raise ValueError(f'Regression signatures can only accept a single tensor input of type tf.string. Please check to make sure that you have structured the serving_input_receiver_fn so that it creates a single string placeholder. If your model function expects multiple inputs, then use `tf.io.parse_example()` to parse the string into multiple tensors.\n Received: {receiver_tensors}')
    return signature_def_utils.regression_signature_def(examples, self.value)

def _get_setitem_indexer(self, key):
    """
        Convert a potentially-label-based key into a positional indexer.
        """
    if self.name == 'loc':
        self._ensure_listlike_indexer(key, axis=self.axis)
    if isinstance(key, tuple):
        for x in key:
            check_dict_or_set_indexers(x)
    if self.axis is not None:
        key = _tupleize_axis_indexer(self.ndim, self.axis, key)
    ax = self.obj._get_axis(0)
    if <MASK>:
        with suppress(KeyError, InvalidIndexError):
            return ax.get_loc(key)
    if isinstance(key, tuple):
        with suppress(IndexingError):
            return self._convert_tuple(key)
    if isinstance(key, range):
        key = list(key)
    return self._convert_to_indexer(key, axis=0)

def get_script_args(args):
    formals: list[str] = []
    tensors: list[Union[torch.Tensor, list[torch.Tensor]]] = []
    actuals: list[str] = []
    for arg in args:
        if isinstance(arg, torch.Tensor):
            name = f'i{len(formals)}'
            formals.append(name)
            actuals.append(name)
            tensors.append(arg)
        elif is_iterable_of_tensors(arg):
            name = f'i{len(formals)}'
            formals.append(name + ': List[torch.Tensor]')
            actuals.append(name)
            tensors.append(list(arg))
        elif <MASK>:
            actuals.append(f"'{arg}'")
        else:
            actuals.append(str(get_constant(arg)))
    return (formals, tensors, actuals)

def _handle_aggregate(ty) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:

    def dump_type(t, level: int) -> tuple[str, str, str]:
        if getattr(t, '__name__', None) in cpp_enum_defs:
            return (t.__name__, 'int64_t', t.__name__)
        elif t in _CPP_TYPE_MAP:
            return (t.__name__, _CPP_TYPE_MAP[t], _THRIFT_TYPE_MAP[t])
        elif isinstance(t, str):
            assert t in defs
            assert t not in cpp_enum_defs
            assert '[' not in t
            return (t, f'ForwardRef<{t}>', t)
        elif isinstance(t, ForwardRef):
            return (t.__forward_arg__, f'ForwardRef<{t.__forward_arg__}>', t.__forward_arg__)
        elif (o := typing.get_origin(t)):
            if <MASK>:
                (yaml_head, cpp_head, thrift_head, thrift_tail) = ('List', 'std::vector', 'list<', '>')
            elif o is dict:
                (yaml_head, cpp_head, thrift_head, thrift_tail) = ('Dict', 'std::unordered_map', 'map<', '>')
            elif o == Union:
                assert level == 0, 'Optional is only supported at the top level.'
                args = typing.get_args(t)
                assert len(args) == 2 and args[1] is type(None)
                (yaml_type, cpp_type, thrift_type) = dump_type(args[0], level + 1)
                return (f'Optional[{yaml_type}]', f'std::optional<{cpp_type}>', f'optional {thrift_type}')
            elif o == Annotated:
                return dump_type(t.__origin__, level)
            else:
                raise AssertionError(f'Type {t} is not supported in export schema.')
            (yaml_arg_types, cpp_arg_types, thrift_arg_types) = zip(*[dump_type(x, level + 1) for x in typing.get_args(t)])
            return (f"{yaml_head}[{', '.join(yaml_arg_types)}]", f"{cpp_head}<{', '.join(cpp_arg_types)}>", f"{thrift_head}{', '.join(thrift_arg_types)}{thrift_tail}")
        elif isinstance(t, type):
            return (t.__name__, t.__name__, t.__name__)
        else:
            raise AssertionError(f'Type {t} is not supported in export schema.')

    def dump_cpp_value(v) -> str:
        if v is None:
            return 'std::nullopt'
        elif v is True:
            return 'true'
        elif v is False:
            return 'false'
        elif v == {}:
            return '{}'
        elif v == []:
            return '{}'
        elif v == ():
            return '{}'
        elif isinstance(v, str):
            return f'"{v}"'
        else:
            raise AssertionError(f'Default value {v} is not supported yet in export schema.')

    def dump_field(f) -> tuple[dict[str, Any], str, Optional[str], str, int]:
        (t, cpp_type, thrift_type) = dump_type(f.type, 0)
        ret = {'type': t}
        cpp_default: Optional[str] = None
        assert typing.get_origin(f.type) == Annotated, f'Field {f.name} must be annotated with an integer id.'
        thrift_id = f.type.__metadata__[0]
        assert type(thrift_id) is int, f'Field {f.name} must be annotated with an integer id.'
        value = dataclasses.MISSING
        if f.default is not dataclasses.MISSING:
            value = f.default
        elif f.default_factory is not dataclasses.MISSING:
            value = f.default_factory()
        if value is not dataclasses.MISSING:
            default = str(value)
            ret['default'] = default
            cpp_default = dump_cpp_value(value)
            if t.startswith('Optional[') and value is not None:
                raise AssertionError(f'Optional field {ty.__name__}.{f.name} must have default value to be None.')
        return (ret, cpp_type, cpp_default, thrift_type, thrift_id)
    yaml_ret = {}
    cpp_ret = {}
    thrift_ret = {}
    thrift_ids = set()
    for f in dataclasses.fields(ty):
        (yaml_res, cpp_type, cpp_default, thrift_type, thrift_id) = dump_field(f)
        yaml_ret[f.name] = yaml_res
        cpp_ret[f.name] = {'cpp_type': cpp_type, 'cpp_default': cpp_default}
        thrift_ret[f.name] = {'thrift_type': thrift_type, 'thrift_id': thrift_id}
        if thrift_id in thrift_ids:
            raise AssertionError(f'Duplicate thrift id {thrift_id} for field {f.name} in {ty.__name__}.')
        thrift_ids.add(thrift_id)
    return (yaml_ret, cpp_ret, thrift_ret)

def test_nested(self):

    def f(x):
        v = []
        u = []
        w = []
        while x > 0:
            x -= 1
            if <MASK>:
                if x % 3 != 0:
                    u.append(x)
                else:
                    w.append(x)
                    break
            v.append(x)
        return (v, u, w)
    self.assertTransformedEquivalent(f, 0)
    self.assertTransformedEquivalent(f, 3)
    self.assertTransformedEquivalent(f, 11)

def install_subgraph_in_output_graph(self, tx, fn_vt, fn_args_vt, kwargs, body_gmod, attr_name):
    if not isinstance(fn_vt, (UnspecializedNNModuleVariable, UserFunctionVariable)):
        unimplemented_v2(gb_type='Encountered non user function variable during invoke_subgraph HOP tracing', context=str(fn_vt), explanation='invoke_subgraph does not support non user function variable', hints=[*graph_break_hints.SUPPORTABLE])
    invoke_subgraph_cache = tx.output.tracing_context.hop_dispatch_set_cache.get_cache(torch._higher_order_ops.invoke_subgraph)
    if isinstance(fn_vt, UserFunctionVariable):
        fn_id = id(fn_vt.get_function())
        fn_name = fn_vt.get_function().__name__
    else:
        assert isinstance(fn_vt, UnspecializedNNModuleVariable)
        fn_id = id(fn_vt.value.forward.__func__)
        fn_name = fn_vt.value.forward.__name__
    previously_installed_submodules = []
    if <MASK>:
        previously_installed_submodules = invoke_subgraph_cache.get_dynamo_installed_submodules(fn_id)
        current_mod = body_gmod
        for submodule_name in reversed(previously_installed_submodules):
            assert submodule_name in tx.output.nn_modules
            previous_mod = tx.output.nn_modules[submodule_name]
            if are_same_graph_modules(fn_name, previous_mod, current_mod, tx.fake_mode):
                return submodule_name
    body_name = super().install_subgraph_in_output_graph(tx, fn_vt, fn_args_vt, kwargs, body_gmod, 'subgraph')
    hc_log.debug("%s: Installing subgraph with identifier '%s', bringing total count for '%s' function to %s", fn_name, body_name, fn_name, len(previously_installed_submodules) + 1)
    if invoke_subgraph_cache:
        invoke_subgraph_cache.add_dynamo_installed_submodule(fn_id, body_name)
    return body_name

def sink_cat_after_pointwise(module: torch.fx.GraphModule) -> torch.fx.GraphModule:

    def one_user(node):
        users = list(node.users)
        return users[0] if len(users) == 1 else None

    def is_view(node):
        return node.op == 'call_method' and node.target == 'view'

    def is_pointwise_unary(node):
        ops = ('call_function', 'call_method')
        pointwise = (torch.relu, torch.tanh, 'relu', 'tanh')
        return node.op in ops and node.target in pointwise
    g = module.graph
    for node in g.nodes:
        if node.op != 'call_function' or node.target != torch.cat:
            continue
        cat_or_view = node
        while True:
            user = one_user(cat_or_view)
            if <MASK>:
                break
            cat_or_view = user
        if user and is_pointwise_unary(user):
            with g.inserting_before(node):

                def cat_args(tensors, dim=0):
                    return (tensors, dim)
                (tensors, dim) = cat_args(*node.args, **node.kwargs)
                new_kwargs = {name: val for (name, val) in user.kwargs.items() if name != 'input'}
                new_tensors = [g.create_node(user.op, user.target, args=(arg,), kwargs=new_kwargs) for arg in tensors]
                new_cat = g.create_node('call_function', torch.cat, args=(new_tensors, dim))
                user.replace_all_uses_with(cat_or_view)
                node.replace_all_uses_with(new_cat)
                g.erase_node(user)
                g.erase_node(node)
    g.lint()
    module.recompile()
    return module

def _irfftn(input_tensor, fft_length=None, axes=None, norm=None, name=None):
    """Wrapper irfft* that infers fft_length argument."""
    with _ops.name_scope(name, default_name, [input_tensor, fft_length]) as name:
        axes = _process_empty_axes(input_tensor, axes)
        fft_rank = axes.shape[0]
        input_tensor = _ops.convert_to_tensor(input_tensor, preferred_dtype=_dtypes.complex64)
        input_tensor.shape.with_rank_at_least(fft_rank)
        if input_tensor.dtype not in (_dtypes.complex64, _dtypes.complex128):
            raise ValueError('IRFFT requires tf.complex64 or tf.complex128 inputs, got: %s' % input_tensor)
        complex_dtype = input_tensor.dtype
        real_dtype = complex_dtype.real_dtype
        if fft_length is None:
            fft_length = _infer_fft_length_for_irfftn(input_tensor)
        else:
            fft_length = _ops.convert_to_tensor(fft_length, _dtypes.int32)
        input_tensor = _maybe_pad_for_rfft(input_tensor, fft_rank, fft_length, is_reverse=True)
        fft_length_static = _tensor_util.constant_value(fft_length)
        if <MASK>:
            fft_length = fft_length_static
        if norm is None:
            norm = 'backward'
        n = 1
        if norm != 'backward':
            for fft_length_i in fft_length:
                n *= fft_length_i
            if norm == 'forward':
                input_tensor *= n
            elif norm == 'ortho':
                input_tensor *= np.sqrt(n)
        return irfft_n(input_tensor, fft_length, axes, Treal=real_dtype, name=name)

def check_attribute(attribute_self, attribute_other):
    nonlocal is_subtype
    if <MASK>:
        return
    if isinstance(attribute_self, trace.TraceType):
        if not attribute_self.is_subtype_of(attribute_other):
            is_subtype = False
            return
    elif attribute_self != attribute_other:
        is_subtype = False

def _load_constants(archive_reader: PT2ArchiveReader, model_name: str) -> Union[dict[str, torch.Tensor], bytes]:
    legacy_constants_file = f'{CONSTANTS_DIR}{model_name}.pt'
    if legacy_constants_file in archive_reader.get_file_names():
        logger.warning('You are loading constant from the legacy format. Please generate a new pt2 file using torch.export.save().')
        return archive_reader.read_bytes(legacy_constants_file)
    else:
        constants_config_file = CONSTANTS_CONFIG_FILENAME_FORMAT.format(model_name)
        assert constants_config_file in archive_reader.get_file_names(), f'{constants_config_file} not found in PT2 archive'
        constants_config = _load_payload_config(archive_reader, constants_config_file)
        constant_file_map = _build_file_map(archive_reader, constants_config, CONSTANTS_DIR)
        constants: dict[str, torch.Tensor] = {}
        for (constant_fqn, payload_meta) in constants_config.config.items():
            path_name = payload_meta.path_name
            if <MASK>:
                if payload_meta.use_pickle:
                    constant_bytes = archive_reader.read_bytes(os.path.join(CONSTANTS_DIR, path_name))
                    constants[constant_fqn] = torch.load(io.BytesIO(constant_bytes), weights_only=False)
                else:
                    tensor_meta = payload_meta.tensor_meta
                    assert tensor_meta is not None
                    constant_tensor = torch.as_strided(input=constant_file_map[path_name], size=deserialize_size(tensor_meta.sizes), stride=deserialize_stride(tensor_meta.strides), storage_offset=deserialize_storage_offset(tensor_meta.storage_offset))
                    constants[constant_fqn] = constant_tensor
            elif path_name.startswith(CUSTOM_OBJ_FILENAME_PREFIX):
                constant_bytes = archive_reader.read_bytes(os.path.join(CONSTANTS_DIR, path_name))
                constants[constant_fqn] = torch._C._pickle_load_obj(constant_bytes)
            else:
                raise RuntimeError(f'Unsupported constant type: {path_name}')
        return constants

def reference_hash_tensor(tensor, dim=(), keepdim=False, mode=0):
    assert mode == 0, 'Only mode=0 (xor_sum) is supported right now'
    dtype = tensor.dtype
    if dtype.kind == 'f':
        tensor = tensor.astype(np.float64).view(np.uint64)
    else:
        tensor = tensor.astype(np.uint64)
    if <MASK>:
        result = np.bitwise_xor.reduce(tensor.flatten(), keepdims=keepdim)
    else:
        if isinstance(dim, list):
            dim = tuple(dim)
        result = np.bitwise_xor.reduce(tensor, axis=dim, keepdims=keepdim)
    return result

def load_binunicode(self):
    (strlen,) = struct.unpack('<I', self.read(4))
    if <MASK>:
        raise Exception('String too long.')
    str_bytes = self.read(strlen)
    obj: Any
    try:
        obj = str(str_bytes, 'utf-8', 'surrogatepass')
    except UnicodeDecodeError as exn:
        if not self.catch_invalid_utf8:
            raise
        obj = FakeObject('builtin', 'UnicodeDecodeError', (str(exn),))
    self.append(obj)

def run_node(self, n: Node) -> Any:
    (args, kwargs) = self.fetch_args_kwargs_from_env(n)

    def get_type(arg):
        if isinstance(arg, fx.Node):
            return n.meta.get('type')
        return type(arg)
    arg_types = map_aggregate(n.args, get_type)
    assert isinstance(arg_types, tuple)
    arg_types = tuple((create_type_hint(i) for i in arg_types))
    kwarg_types = {k: get_type(v) for (k, v) in kwargs.items()}
    if <MASK>:
        out = self.call_function(n.target, args, kwargs, arg_types, kwarg_types)
    else:
        out = super().run_node(n)
    if n.op != 'output':
        self.node_map[out] = n
        out.node.meta = n.meta
        out.node.type = n.type
    return out

def are_block_parameters_compatible(self, block_params: BlockParameters) -> bool:
    """
        Check if the block parameters are valid for TMA.
        If force, we allow relying on symbolic hints equivalent
        to what we check for Triton templates.
        """
    if self.force:
        strides = [V.graph.sizevars.symbolic_hint(st) for st in block_params.strides]
    else:
        strides = block_params.strides
    if <MASK>:
        log.debug('%s TMA API requires innermost stride to be 1.', self.failed_debug_prefix)
        return False
    element_size = self.dtype.itemsize
    for stride in strides[:-1]:
        if not V.graph.sizevars.statically_known_equals(ModularIndexing(stride * element_size, 1, sympy.Integer(16)), sympy.Integer(0)):
            log.debug('%s TMA API requires outer strides to be 16 byte aligned.', self.failed_debug_prefix)
            return False
    innermost_block_shape = block_params.block_shape[-1]
    innermost_block_type = None
    innermost_block_symt = None
    for block_type_str in innermost_block_shape.free_symbols:
        for block_symt in TritonSymbols.block_types:
            if symbol_is_type(block_type_str, block_symt):
                innermost_block_type = block_type_str
                innermost_block_symt = block_symt
                break
    assert innermost_block_type and innermost_block_symt, f'{innermost_block_shape} expr must contain a single block type from {TritonSymbols.block_types}'
    if self.kernel.persistent_reduction and (not self.for_store):
        innermost_tree_prefix = prefix_str[innermost_block_symt]
        tree_numel = None
        for t in self.kernel.range_trees:
            if t.is_reduction:
                if t.prefix == innermost_tree_prefix:
                    tree_numel = t.numel
                    break
        assert tree_numel is not None
        persistent_rblock = self.kernel._get_persistent_RBLOCK(tree_numel)
        innermost_block_bytes = innermost_block_shape.subs({innermost_block_type: persistent_rblock}) * element_size
        if not V.graph.sizevars.statically_known_geq(innermost_block_bytes, sympy.Integer(16)):
            log.debug('%s persistent reduction innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    else:
        try:
            min_block_size = next_power_of_2(int(sympy.nsolve(innermost_block_shape * element_size - 16, innermost_block_type, 1)))
            block_type_str = V.kernel.index_to_str(innermost_block_type)
            if self.kernel.fixed_config:
                if min_block_size > self.kernel.fixed_config[block_type_str]:
                    log.debug('%s For block %s, fixed config block size %d is smaller than the minimum required: %d', self.failed_debug_prefix, block_type_str, self.kernel.fixed_config[block_type_str], min_block_size)
                    return False
            else:
                self.kernel.tma_min_block_sizes[block_type_str] = max(min_block_size, self.kernel.tma_min_block_sizes.get(block_type_str, 1))
        except ValueError:
            log.debug('%s innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    return True

def visit_Call(self, node):
    if hasattr(node.func, 'id') and node.func.id == '__import__':
        try:
            name = self._grab_node_str(node.args[0])
            fromlist: list[str] = []
            level = 0
            if <MASK>:
                fromlist.extend((self._grab_node_str(v) for v in node.args[3].elts))
            elif hasattr(node, 'keywords'):
                for keyword in node.keywords:
                    if keyword.arg == 'fromlist':
                        fromlist.extend((self._grab_node_str(v) for v in keyword.value.elts))
            if len(node.args) > 4:
                level = self._grab_node_int(node.args[4])
            elif hasattr(node, 'keywords'):
                for keyword in node.keywords:
                    if keyword.arg == 'level':
                        level = self._grab_node_int(keyword.value)
            if fromlist == []:
                self.references[name, None] = True
                top_name = name.rsplit('.', maxsplit=1)[0]
                if top_name != name:
                    top_name = self._absmodule(top_name, level)
                    self.references[top_name, None] = True
            else:
                name = self._absmodule(name, level)
                for alias in fromlist:
                    if alias != '*':
                        self.references[name, alias] = True
                    else:
                        self.references[name, None] = True
        except Exception:
            return

def twist_matrix(matrix, permutation_indices):
    """Permute the rows and columns of a 2D or (batched) 3D Tensor."""
    if <MASK>:
        permutation_indices_inv = array_ops.invert_permutation(permutation_indices)
        matrix = array_ops.gather(matrix, permutation_indices_inv, axis=0)
        matrix = array_ops.gather(matrix, permutation_indices_inv, axis=1)
    elif matrix.shape.ndims == 3:
        permutation_indices_inv = map_fn.map_fn(array_ops.invert_permutation, permutation_indices)
        batch_size = matrix.shape[0]
        batch_indices = array_ops.broadcast_to(math_ops.range(batch_size)[:, None], permutation_indices.shape)
        for _ in range(2):
            matrix = array_ops.gather_nd(matrix, array_ops_stack.stack([batch_indices, permutation_indices_inv], axis=-1))
            matrix = array_ops.transpose(matrix, perm=[0, 2, 1])
    else:
        raise ValueError('Input matrix must have rank 2 or 3. Got: {}'.format(matrix.shape.ndims))
    return matrix

def parse_data(self) -> list[dict[str, str | None]]:
    from xml.etree.ElementTree import iterparse
    if self.stylesheet is not None:
        raise ValueError('To use stylesheet, you need lxml installed and selected as parser.')
    if <MASK>:
        self.xml_doc = self._parse_doc(self.path_or_buffer)
        elems = self._validate_path()
    self._validate_names()
    xml_dicts: list[dict[str, str | None]] = self._parse_nodes(elems) if self.iterparse is None else self._iterparse_nodes(iterparse)
    return xml_dicts

def sample_inputs_masked_cumops(op_info, device, dtype, requires_grad, **kwargs):
    """Sample inputs for masked cumsum and cumprod."""
    for sample_input in sample_inputs_softmax_variant(op_info, device, dtype, requires_grad, **kwargs):
        for mask in _generate_masked_op_mask(sample_input.input.shape, device, **kwargs):
            if <MASK>:
                continue
            (sample_input_args, sample_input_kwargs) = (sample_input.args, dict(mask=mask, **sample_input.kwargs))
            if 'keepdim' in sample_input_kwargs:
                sample_input_kwargs.pop('keepdim')
            if sample_input_args:
                dim = sample_input.args[0]
            else:
                if 'dim' not in sample_input_kwargs:
                    continue
                dim = sample_input_kwargs.pop('dim')
                sample_input_args = (dim,)
            yield SampleInput(sample_input.input.clone().requires_grad_(requires_grad), *sample_input_args, **sample_input_kwargs)

def shares_memory(left, right) -> bool:
    """
    Pandas-compat for np.shares_memory.
    """
    if isinstance(left, np.ndarray) and isinstance(right, np.ndarray):
        return np.shares_memory(left, right)
    elif isinstance(left, np.ndarray):
        return shares_memory(right, left)
    if isinstance(left, RangeIndex):
        return False
    if <MASK>:
        return shares_memory(left._codes, right)
    if isinstance(left, (Index, Series)):
        if isinstance(right, (Index, Series)):
            return shares_memory(left._values, right._values)
        return shares_memory(left._values, right)
    if isinstance(left, NDArrayBackedExtensionArray):
        return shares_memory(left._ndarray, right)
    if isinstance(left, pd.core.arrays.SparseArray):
        return shares_memory(left.sp_values, right)
    if isinstance(left, pd.core.arrays.IntervalArray):
        return shares_memory(left._left, right) or shares_memory(left._right, right)
    if isinstance(left, ArrowExtensionArray):
        if isinstance(right, ArrowExtensionArray):
            left_pa_data = left._pa_array
            right_pa_data = right._pa_array
            left_buf1 = left_pa_data.chunk(0).buffers()[1]
            right_buf1 = right_pa_data.chunk(0).buffers()[1]
            return left_buf1.address == right_buf1.address
        else:
            return np.shares_memory(left, right)
    if isinstance(left, BaseMaskedArray) and isinstance(right, BaseMaskedArray):
        return np.shares_memory(left._data, right._data) or np.shares_memory(left._mask, right._mask)
    if isinstance(left, DataFrame) and len(left._mgr.blocks) == 1:
        arr = left._mgr.blocks[0].values
        return shares_memory(arr, right)
    raise NotImplementedError(type(left), type(right))

def _get_dense_tensor(self, inputs, weight_collections=None, trainable=None):
    _check_invalid_cases(self._embedding_lookup_device)
    is_cpu = self._embedding_lookup_device == EmbeddingDevice.CPU
    is_cpu = is_cpu or _is_running_on_cpu()
    if is_cpu:
        return super(_TPUDeviceSpecificEmbeddingColumnV2, self)._get_dense_tensor(inputs, weight_collections, trainable)
    elif self._embedding_lookup_device == EmbeddingDevice.TPU_EMBEDDING_CORE:
        return super(_TPUDeviceSpecificEmbeddingColumnV2, self)._get_dense_tensor(inputs, weight_collections, trainable)
    if tpu.under_tpu_inference_context():
        sparse_tensor = inputs.get(self.get_feature_key_name())

        def host_computation():
            return pad_sparse_embedding_lookup_indices(sparse_tensor, self._tensor_core_shape[1])
        (values, mask) = tpu_replication.outside_compilation(host_computation)
    else:
        values = inputs.get(self.get_feature_key_name())
        mask = inputs.get(self.get_feature_key_name() + _TENSOR_CORE_MASK_KEY_SUFFIX)
    embedding_shape = (self.categorical_column._num_buckets, self.dimension)
    if <MASK>:
        weight_collections.append(ops.GraphKeys.GLOBAL_VARIABLES)
    embedding_weights = variable_scope.get_variable(name='embedding_weights', shape=embedding_shape, dtype=dtypes.float32, initializer=self.initializer, trainable=self.trainable and trainable, collections=weight_collections)
    return sparse_embedding_aggregate_slice(embedding_weights, (values, mask), self.get_combiner())

@compatibility(is_backward_compatible=True)
def create_node(self, kind: str, target: Target, args: tuple[Argument, ...], kwargs: dict[str, Argument], name: Optional[str]=None, type_expr: Optional[Any]=None) -> Node:
    """
        Inserts a graph node given target, args, kwargs, and name.

        This method can be overridden to do extra checking, validation, or
        modification of values used in node creation. For example, one might
        want to disallow in-place operations from being recorded.
        """
    if kind == 'call_function' and self.check_mutable_operations:
        check_for_mutable_operation(target, args, kwargs)
    node = self.graph.create_node(kind, target, args, kwargs, name, type_expr)
    self.node_name_to_scope[node.name] = (self.scope.module_path, self.scope.module_type)
    if fx_traceback.has_preserved_node_meta():
        current_meta: dict[str, Any] = fx_traceback.get_current_meta()
        stack_trace = current_meta.get('stack_trace')
        if <MASK>:
            node.stack_trace = stack_trace
        for field in _COPY_META_FIELDS:
            if field in current_meta:
                node.meta[field] = copy.copy(current_meta[field])
        new_seq_nr = torch.autograd._get_sequence_nr() - 1
        if current_meta.get('in_grad_fn', 0) > 0:
            annotation_log.debug('seq_nr from current_meta')
            new_seq_nr = current_meta['grad_fn_seq_nr'][-1]
        annotation_log.debug('Assigning new_seq_nr %s to %s', new_seq_nr, node.name)
        node.meta['seq_nr'] = new_seq_nr
    elif self.module_stack:
        node.meta['nn_module_stack'] = copy.copy(self.module_stack)
    if self.record_stack_traces and (not node.stack_trace):
        user_stack_summary = CapturedTraceback.extract().summary()
        if user_stack_summary:
            user_stack_summary = self._filter_traceback_frames(user_stack_summary)
            if user_stack_summary:
                node.stack_trace = ''.join(user_stack_summary.format()).strip()
    log.debug('create_node %s', node)
    return node

def _check_fix_default_value(self):
    """
        Warn that using an actual date or datetime value is probably wrong;
        it's only evaluated on server startup.
        """
    if not self.has_default():
        return []
    value = self.default
    if isinstance(value, datetime.datetime):
        now = None
    elif <MASK>:
        now = _get_naive_now()
        value = datetime.datetime.combine(now.date(), value)
    else:
        return []
    return self._check_if_value_fixed(value, now=now)

def _execute_dependency_graph(self):
    """Takes a finalized dependency graph describing how to package all
        modules and executes it, writing to the ZIP archive.
        """
    self._validate_dependency_graph()
    extern_modules = []
    for (module_name, attrs) in self.dependency_graph.nodes.items():
        action = attrs['action']
        if <MASK>:
            for hook in self._extern_hooks.values():
                hook(self, module_name)
            extern_modules.append(module_name)
        elif action == _ModuleProviderAction.MOCK:
            for hook in self._mock_hooks.values():
                hook(self, module_name)
            self._write_mock_file()
            is_package = hasattr(self._import_module(module_name), '__path__')
            self._write_source_string(module_name, _MOCK_IMPL, is_package)
        elif action == _ModuleProviderAction.INTERN:
            for hook in self._intern_hooks.values():
                hook(self, module_name)
            if 'provided' not in attrs:
                raise AssertionError(f'Module was marked `intern` but not provided: {module_name}')
            if attrs.get('is_pickle') is True:
                continue
            is_package = attrs['is_package']
            source = attrs['source']
            self._write_source_string(module_name, source, is_package)
        elif action == _ModuleProviderAction.REPACKAGED_MOCK_MODULE:
            self._write_mock_file()
        elif action == _ModuleProviderAction.SKIP:
            continue
        else:
            raise AssertionError(f'Invalid action: {module_name}, {action}. Please report a bug to PyTorch.')
    extern_file_contents = '\n'.join(extern_modules) + '\n'
    self._write('.data/extern_modules', extern_file_contents)

def used_dims_from_index(self, index: sympy.Expr):
    """Detect which range trees are used to populate HalideCSEVariable.used_dims"""
    used_dims = OrderedSet[sympy.Symbol]()
    for sym in index.free_symbols:
        assert isinstance(sym, sympy.Symbol)
        if symbol_is_type(sym, SymT.TMP):
            cse_var = self.lookup_cse_var(sym.name)
            assert isinstance(cse_var, HalideCSEVariable) and cse_var.used_dims is not None
            used_dims.update(cse_var.used_dims)
        elif <MASK>:
            used_dims.add(sym)
        elif symbol_is_type(sym, (SymT.UNBACKED_INT, SymT.SIZE, SymT.PRECOMPUTED_SIZE, SymT.INDEX)):
            pass
        else:
            raise NotImplementedError(f'unhandled symbol {sym}')
    return self.sort_used_dims(used_dims)

def pr(left, right):
    """create and return a new specialized BinOp from myself"""
    if left is None:
        return right
    elif right is None:
        return left
    k = klass
    if <MASK>:
        if isinstance(right, ConditionBinOp):
            k = JointConditionBinOp
        elif isinstance(left, k):
            return left
        elif isinstance(right, k):
            return right
    elif isinstance(left, FilterBinOp):
        if isinstance(right, FilterBinOp):
            k = JointFilterBinOp
        elif isinstance(left, k):
            return left
        elif isinstance(right, k):
            return right
    return k(self.op, left, right, queryables=self.queryables, encoding=self.encoding).evaluate()

