@staticmethod
def is_literal(obj):
    if <MASK>:
        return all((ConstantVariable.is_literal(x) for x in obj))
    return ConstantVariable.is_base_literal(obj)

def _decode_helper(obj):
    """A decoding helper that is TF-object aware."""
    if isinstance(obj, dict) and 'class_name' in obj:
        if obj['class_name'] == 'TensorShape':
            return tensor_shape.TensorShape(obj['items'])
        elif obj['class_name'] == 'TypeSpec':
            return type_spec_registry.lookup(obj['type_spec'])._deserialize(_decode_helper(obj['serialized']))
        elif obj['class_name'] == '__tuple__':
            return tuple((_decode_helper(i) for i in obj['items']))
        elif <MASK>:
            return Ellipsis
    return obj

def substitute(self, symbols_map):
    """Recursively substitute symbols with values in symbols map.

        Symbols map is a dictionary of symbol-expression pairs.
        """
    if self.op is Op.SYMBOL:
        value = symbols_map.get(self)
        if value is None:
            return self
        m = re.match('\\A(@__f2py_PARENTHESIS_(\\w+)_\\d+@)\\Z', self.data)
        if m:
            (items, paren) = m.groups()
            if paren in ['ROUNDDIV', 'SQUARE']:
                return as_array(value)
            assert paren == 'ROUND', (paren, value)
        return value
    if self.op in (Op.INTEGER, Op.REAL, Op.STRING):
        return self
    if self.op in (Op.ARRAY, Op.COMPLEX):
        return Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data)))
    if self.op is Op.CONCAT:
        return normalize(Expr(self.op, tuple((item.substitute(symbols_map) for item in self.data))))
    if self.op is Op.TERMS:
        r = None
        for (term, coeff) in self.data.items():
            if r is None:
                r = term.substitute(symbols_map) * coeff
            else:
                r += term.substitute(symbols_map) * coeff
        if r is None:
            ewarn('substitute: empty TERMS expression interpreted as int-literal 0')
            return as_number(0)
        return r
    if self.op is Op.FACTORS:
        r = None
        for (base, exponent) in self.data.items():
            if r is None:
                r = base.substitute(symbols_map) ** exponent
            else:
                r *= base.substitute(symbols_map) ** exponent
        if r is None:
            ewarn('substitute: empty FACTORS expression interpreted as int-literal 1')
            return as_number(1)
        return r
    if self.op is Op.APPLY:
        (target, args, kwargs) = self.data
        if isinstance(target, Expr):
            target = target.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in args))
        kwargs = {k: v.substitute(symbols_map) for (k, v) in kwargs.items()}
        return normalize(Expr(self.op, (target, args, kwargs)))
    if self.op is Op.INDEXING:
        func = self.data[0]
        if isinstance(func, Expr):
            func = func.substitute(symbols_map)
        args = tuple((a.substitute(symbols_map) for a in self.data[1:]))
        return normalize(Expr(self.op, (func,) + args))
    if <MASK>:
        operands = tuple((a.substitute(symbols_map) for a in self.data))
        return normalize(Expr(self.op, operands))
    if self.op in (Op.REF, Op.DEREF):
        return normalize(Expr(self.op, self.data.substitute(symbols_map)))
    if self.op is Op.RELATIONAL:
        (rop, left, right) = self.data
        left = left.substitute(symbols_map)
        right = right.substitute(symbols_map)
        return normalize(Expr(self.op, (rop, left, right)))
    raise NotImplementedError(f'substitute method for {self.op}: {self!r}')

def test_prefer_specific_trace(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')

    @def_function.function(autograph=False)
    def func(a):
        if isinstance(a, int):
            return a
        else:
            return a + 1
    self.assertAllEqual(2, func(2).numpy())
    self.assertAllEqual(3, func(constant_op.constant(2)).numpy())
    root = autotrackable.AutoTrackable()
    root.f = func
    root = cycle(root, cycles, use_cpp_bindings=use_cpp_bindings)
    self.assertAllEqual(2, root.f(2).numpy())
    self.assertAllEqual(4, root.f(3).numpy())
    self.assertAllEqual(3, root.f(constant_op.constant(2)).numpy())
    self.assertAllEqual(4, root.f(constant_op.constant(3)).numpy())

@combinations.generate(combinations.combine(num_processes=2, required_gpus=0, implementation=CommunicationImplementation.AUTO, reduce_op=ReduceOp.SUM))
def testAllReduceMixedDenseAndSparse(self, num_processes, required_gpus, implementation, reduce_op):
    if <MASK>:
        self.skipTest('Skip potential NCCL combination (AUTO) with mismatched process and GPU count. NCCL requires physical GPUs for every process.')

    def replica_fn():
        (collective, devices, _) = self.make_collective(num_processes, required_gpus)
        options = collective_util.Options(implementation=implementation)
        group_size = num_processes * (required_gpus or 1)

        @def_function.function
        def collective_batch_all_reduce():
            results = []
            for (replica_id, device) in enumerate(devices):
                with ops.device(device):
                    value = (IndexedSlices(array_ops.identity([[1.0]]), array_ops.identity([0]), array_ops.identity([5, 1])), array_ops.identity(1.0), IndexedSlices(array_ops.identity([[3.0]]), array_ops.identity([2]), array_ops.identity([5, 1])), array_ops.identity(2.0))
                    results.append(collective._all_reduce(reduce_op, value, replica_id, options))
            return results
        got = collective_batch_all_reduce()
        expect = [(IndexedSlices([[1.0 * group_size]], [0], [5, 1]), 1.0 * group_size, IndexedSlices([[3.0 * group_size]], [2], [5, 1]), 2.0 * group_size)] * len(devices)
        self.assertAllClose(nest.map_structure(ops.convert_to_tensor, got), nest.map_structure(ops.convert_to_tensor, expect))
    get_global_mpr(num_processes).run(replica_fn)

def _inference_ref(self, x, scale, offset, mean, var, epsilon, data_format):
    if data_format not in ['NHWC', 'NCHW', 'NDHWC', 'NCDHW']:
        raise ValueError('data_format must be NCHW or NHWC for 4D tensors orNCDHW or NDHWC for 5D tensors, got %s.' % data_format)
    if data_format == 'NCHW':
        x = array_ops.transpose(x, [0, 2, 3, 1])
    elif <MASK>:
        x = array_ops.transpose(x, [0, 2, 3, 4, 1])
    y = self._batch_norm(x, mean, var, offset, scale, epsilon)
    if data_format == 'NCHW':
        y = array_ops.transpose(y, [0, 3, 1, 2])
    elif data_format == 'NCDHW':
        y = array_ops.transpose(y, [0, 4, 1, 2, 3])
    return self.evaluate(y)

def _compareUnaryCpu(self, x, np_func, tf_func, grad_rtol=None, grad_atol=None):
    if grad_rtol is None:
        grad_rtol = _default_tolerance(x.dtype)
    if grad_atol is None:
        grad_atol = _default_tolerance(x.dtype)
    np_ans = np_func(x)
    with self.cached_session(use_gpu=False):
        inx = ops.convert_to_tensor(x)
        if <MASK>:
            y = 1.1 * tf_func(inx)
            np_ans *= 1.1
        else:
            y = tf_func(inx)
        tf_cpu = self.evaluate(y)
        self.assertShapeEqual(np_ans, y)
        if x.dtype == np.float16:
            self.assertAllClose(np_ans, tf_cpu, rtol=0.001, atol=0.001)
        elif x.dtype == dtypes.bfloat16.as_numpy_dtype:
            self.assertAllClose(np_ans, tf_cpu, rtol=0.01, atol=0.01)
        else:
            self.assertAllClose(np_ans, tf_cpu)
        if x.dtype in (np.complex64, np.complex128) and tf_func == math_ops.sign:
            return
        if x.dtype == np.float16:
            s = list(np.shape(x))
            (jacob_t, _) = gradient_checker.compute_gradient(inx, s, y, s, x_init_value=x)
            xf = x.astype(np.float)
            inxf = ops.convert_to_tensor(xf)
            yf = tf_func(inxf)
            (_, jacob_n) = gradient_checker.compute_gradient(inxf, s, yf, s, x_init_value=xf, delta=0.01)
            jacob_n = jacob_n.astype(np.float16)
            self.assertAllClose(jacob_t, jacob_n, rtol=grad_rtol, atol=grad_atol)
        elif x.dtype in (np.float32, np.complex64):
            s = list(np.shape(x))
            (jacob_t, jacob_n) = gradient_checker.compute_gradient(inx, s, y, s, x_init_value=x, delta=0.001)
            self.assertAllClose(jacob_t, jacob_n, rtol=grad_rtol, atol=grad_atol)
        elif x.dtype in (np.float64, np.complex128):
            s = list(np.shape(x))
            (jacob_t, jacob_n) = gradient_checker.compute_gradient(inx, s, y, s, x_init_value=x, delta=1e-05)
            self.assertAllClose(jacob_t, jacob_n, rtol=grad_rtol, atol=grad_atol)

@functools.lru_cache
def is_from_optimizer_source(source: Source) -> bool:
    if <MASK>:
        return True
    if isinstance(source, ChainedSource):
        return is_from_optimizer_source(source.base)
    return False

def compute_memory_timeline(nodes: list[BaseSchedulerNode], name_to_freeable_input_buf: dict[str, FreeableInputBuffer], graph_outputs: OrderedSet[str]) -> tuple[list[BufferInfo], dict[BaseSchedulerNode, int], dict[Union[FreeableInputBuffer, SchedulerBuffer], BaseSchedulerNode]]:
    """
    Compute buffer allocation and deallocation sizes and map their
    lifetime to the node schedule
    """
    node_to_step: dict[BaseSchedulerNode, int] = {node: step for (step, node) in enumerate(nodes)}
    buf_info_list: list[BufferInfo] = []
    buf_to_snode_last_use: dict[Union[FreeableInputBuffer, SchedulerBuffer], BaseSchedulerNode] = {}

    def _get_end_step_and_snode(buf: Union[FreeableInputBuffer, SchedulerBuffer]) -> tuple[int, Optional[BaseSchedulerNode]]:
        max_step: int = -1
        max_step_snode: Optional[BaseSchedulerNode] = None
        succ_nodes = buf.mpi_buffer.succ_nodes
        if succ_nodes:
            for succ_node in succ_nodes:
                step = node_to_step[succ_node]
                if step > max_step:
                    max_step = step
                    max_step_snode = succ_node
            assert max_step_snode is not None
        return (max_step, max_step_snode)
    for (buf_name, input_buf) in name_to_freeable_input_buf.items():
        end_step = -1
        if <MASK>:
            (end_step, end_step_snode) = _get_end_step_and_snode(input_buf)
            assert end_step_snode is not None
            buf_to_snode_last_use[input_buf] = end_step_snode
        buf_info_list.append(BufferInfo(input_buf, input_buf.mpi_buffer.size_free, input_buf.mpi_buffer.size_free, 0, end_step))
    for (step, node) in enumerate(nodes):
        for sched_buf in node.get_outputs():
            buf_name = sched_buf.get_name()
            end_step = -1
            if buf_name not in graph_outputs:
                (end_step, end_step_snode) = _get_end_step_and_snode(sched_buf)
                if end_step == -1:
                    end_step = step
                    buf_to_snode_last_use[sched_buf] = node
                else:
                    assert end_step_snode is not None
                    buf_to_snode_last_use[sched_buf] = end_step_snode
            buf_info_list.append(BufferInfo(sched_buf, sched_buf.mpi_buffer.size_alloc, sched_buf.mpi_buffer.size_free, step, end_step))
    return (buf_info_list, node_to_step, buf_to_snode_last_use)

def _get_partitioned_variable(self, var_store, name, shape=None, dtype=None, initializer=None, regularizer=None, trainable=None, collections=None, caching_device=None, partitioner=None, validate_shape=True, use_resource=None, constraint=None, synchronization=VariableSynchronization.AUTO, aggregation=VariableAggregation.NONE):
    """Gets an existing variable with this name or create a new one."""
    if <MASK>:
        initializer = self._initializer
    if regularizer is None:
        regularizer = self._regularizer
    if constraint is None:
        constraint = self._constraint
    if caching_device is None:
        caching_device = self._caching_device
    if partitioner is None:
        partitioner = self._partitioner
    if dtype is None:
        dtype = self._dtype
    if use_resource is None:
        use_resource = self._use_resource
    if self._custom_getter is not None:
        raise ValueError("Private access to _get_partitioned_variable is not allowed when a custom getter is set.  Current custom getter: %s.  It is likely that you're using create_partitioned_variables.  If so, consider instead using get_variable with a non-empty partitioner parameter instead." % self._custom_getter)
    if partitioner is None:
        raise ValueError('No partitioner was specified')
    full_name_list = []
    if self.name:
        full_name_list.append(self.name)
    if name:
        full_name_list.append(name)
    full_name = '/'.join(full_name_list)
    with ops.name_scope(None, skip_on_eager=False):
        return var_store._get_partitioned_variable(full_name, shape=shape, dtype=dtype, initializer=initializer, regularizer=regularizer, reuse=self.reuse, trainable=trainable, collections=collections, caching_device=caching_device, partitioner=partitioner, validate_shape=validate_shape, use_resource=use_resource, constraint=constraint, synchronization=synchronization, aggregation=aggregation)

def _log_survival_function(self, y):
    if <MASK>:
        raise NotImplementedError('log_survival_function is not implemented when overriding event_shape')
    if not self.bijector._is_injective:
        raise NotImplementedError('log_survival_function is not implemented when bijector is not injective.')
    x = self.bijector.inverse(y)
    return self.distribution.log_survival_function(x)

def __eq__(self, other: object) -> bool:
    if isinstance(other, str):
        try:
            other = self.construct_from_string(other)
        except TypeError:
            return False
    if <MASK>:
        subtype = self.subtype == other.subtype
        if self._is_na_fill_value or other._is_na_fill_value:
            fill_value = isinstance(self.fill_value, type(other.fill_value)) or isinstance(other.fill_value, type(self.fill_value))
        else:
            with warnings.catch_warnings():
                warnings.filterwarnings('ignore', 'elementwise comparison failed', category=DeprecationWarning)
                fill_value = self.fill_value == other.fill_value
        return subtype and fill_value
    return False

def histogramdd(sample, bins=10, range: Optional[ArrayLike]=None, normed=None, weights: Optional[ArrayLike]=None, density=None):
    if <MASK>:
        raise ValueError('normed argument is deprecated, use density= instead')
    from ._normalizations import normalize_array_like, normalize_seq_array_like
    if isinstance(sample, (list, tuple)):
        sample = normalize_array_like(sample).T
    else:
        sample = normalize_array_like(sample)
    sample = torch.atleast_2d(sample)
    if not (sample.dtype.is_floating_point or sample.dtype.is_complex):
        sample = sample.double()
    bins_is_array = not (isinstance(bins, int) or builtins.all((isinstance(b, int) for b in bins)))
    if bins_is_array:
        bins = normalize_seq_array_like(bins)
        bins_dtypes = [b.dtype for b in bins]
        bins = [_util.cast_if_needed(b, sample.dtype) for b in bins]
    if range is not None:
        range = range.flatten().tolist()
    if weights is not None:
        mm = sample.aminmax(dim=0)
        range = torch.cat(mm).reshape(2, -1).T.flatten()
        range = tuple(range.tolist())
        weights = _util.cast_if_needed(weights, sample.dtype)
        w_kwd = {'weight': weights}
    else:
        w_kwd = {}
    (h, b) = torch.histogramdd(sample, bins, range, density=bool(density), **w_kwd)
    if bins_is_array:
        b = [_util.cast_if_needed(bb, dtyp) for (bb, dtyp) in zip(b, bins_dtypes)]
    return (h, b)

def _preprocess_data(self, data, mask):
    from .._ops import _sparse_coo_where, _sparse_csr_where
    if data.layout != mask.layout:
        raise TypeError('data and mask must have the same layout.')
    if data.layout == torch.sparse_coo:
        data = data.coalesce()
        mask = mask.coalesce()
        if <MASK>:
            data = _sparse_coo_where(mask, data, torch.tensor(0))
    elif data.layout == torch.sparse_csr:
        if data._nnz() != mask._nnz():
            data = _sparse_csr_where(mask, data, torch.tensor(0))
    self._masked_data = data.clone()
    self._masked_mask = mask.clone()

