def __getitem__(self, indx):
    """
        x.__getitem__(y) <==> x[y]

        Return the item described by i, as a masked array.

        """
    dout = self.data[indx]
    _mask = self._mask

    def _is_scalar(m):
        return not isinstance(m, np.ndarray)

    def _scalar_heuristic(arr, elem):
        """
            Return whether `elem` is a scalar result of indexing `arr`, or None
            if undecidable without promoting nomask to a full mask
            """
        if not isinstance(elem, np.ndarray):
            return True
        elif arr.dtype.type is np.object_:
            if arr.dtype is not elem.dtype:
                return True
        elif type(arr).__getitem__ == ndarray.__getitem__:
            return False
        return None
    if _mask is not nomask:
        mout = _mask[indx]
        scalar_expected = _is_scalar(mout)
    else:
        mout = nomask
        scalar_expected = _scalar_heuristic(self.data, dout)
        if scalar_expected is None:
            scalar_expected = _is_scalar(getmaskarray(self)[indx])
    if scalar_expected:
        if isinstance(dout, np.void):
            return mvoid(dout, mask=mout, hardmask=self._hardmask)
        elif <MASK>:
            if mout:
                return MaskedArray(dout, mask=True)
            else:
                return dout
        elif mout:
            return masked
        else:
            return dout
    else:
        dout = dout.view(type(self))
        dout._update_from(self)
        if is_string_or_list_of_strings(indx):
            if self._fill_value is not None:
                dout._fill_value = self._fill_value[indx]
                if not isinstance(dout._fill_value, np.ndarray):
                    raise RuntimeError('Internal NumPy error.')
                if dout._fill_value.ndim > 0:
                    if not (dout._fill_value == dout._fill_value.flat[0]).all():
                        warnings.warn(f'Upon accessing multidimensional field {indx!s}, need to keep dimensionality of fill_value at 0. Discarding heterogeneous fill_value and setting all to {dout._fill_value[0]!s}.', stacklevel=2)
                    dout._fill_value = dout._fill_value.flat[0:1].squeeze(axis=0)
            dout._isfield = True
        if mout is not nomask:
            dout._mask = reshape(mout, dout.shape)
            dout._sharedmask = True
    return dout

def start_processes(fn, args=(), nprocs=1, join=True, daemon=False, start_method='spawn', numa_options: Optional[NumaOptions]=None):
    if <MASK>:
        log.info('Starting processes in parallel.')
        start_parallel = True
    else:
        start_parallel = False
    mp = multiprocessing.get_context(start_method)
    error_files = [None] * nprocs
    processes = [None] * nprocs

    def start_process(i):
        tf = tempfile.NamedTemporaryFile(prefix='pytorch-errorfile-', suffix='.pickle', delete=False)
        tf.close()
        os.unlink(tf.name)
        process = mp.Process(target=_wrap, args=(fn, i, args, tf.name), daemon=daemon)
        with maybe_temporarily_apply_numa_binding_to_current_thread(gpu_index=i, numa_options=numa_options):
            process.start()
        return (i, process, tf.name)
    if not start_parallel:
        for i in range(nprocs):
            (idx, process, tf_name) = start_process(i)
            error_files[idx] = tf_name
            processes[idx] = process
    else:
        with ThreadPoolExecutor(max_workers=nprocs) as executor:
            futures = [executor.submit(start_process, i) for i in range(nprocs)]
            for fut in as_completed(futures):
                (idx, process, tf_name) = fut.result()
                error_files[idx] = tf_name
                processes[idx] = process
    context = ProcessContext(processes, error_files)
    if not join:
        return context
    while not context.join():
        pass

def _multi_tensor_adamax(params: list[Tensor], grads: list[Tensor], exp_avgs: list[Tensor], exp_infs: list[Tensor], state_steps: list[Tensor], *, eps: float, beta1: float, beta2: float, lr: float, weight_decay: float, maximize: bool, differentiable: bool, capturable: bool, has_complex: bool):
    if differentiable:
        raise AssertionError("_foreach ops don't support autograd")
    if <MASK>:
        return
    if not torch.compiler.is_compiling() and capturable:
        capturable_supported_devices = _get_capturable_supported_devices(supports_xla=False)
        if not all((p.device.type == step.device.type and p.device.type in capturable_supported_devices for (p, step) in zip(params, state_steps))):
            raise AssertionError(f'If capturable=True, params and state_steps must be on supported devices: {capturable_supported_devices}.')
    lr = _to_scalar(lr)
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, exp_avgs, exp_infs, state_steps])
    for ((grouped_params_, grouped_grads_, grouped_exp_avgs_, grouped_exp_infs_, grouped_state_steps_), _) in grouped_tensors.values():
        grouped_params = cast(list[Tensor], grouped_params_)
        grouped_grads = cast(list[Tensor], grouped_grads_)
        grouped_exp_avgs = cast(list[Tensor], grouped_exp_avgs_)
        grouped_exp_infs = cast(list[Tensor], grouped_exp_infs_)
        grouped_state_steps = cast(list[Tensor], grouped_state_steps_)
        if has_complex:
            _view_as_real(grouped_params, grouped_grads, grouped_exp_avgs, grouped_exp_infs)
        if maximize:
            grouped_grads = torch._foreach_neg(grouped_grads)
        if not torch.compiler.is_compiling() and grouped_state_steps[0].is_cpu:
            torch._foreach_add_(grouped_state_steps, torch.tensor(1.0, device='cpu'), alpha=1.0)
        else:
            torch._foreach_add_(grouped_state_steps, 1)
        if weight_decay != 0:
            if maximize:
                torch._foreach_add_(grouped_grads, grouped_params, alpha=weight_decay)
            else:
                grouped_grads = torch._foreach_add(grouped_grads, grouped_params, alpha=weight_decay)
        torch._foreach_lerp_(grouped_exp_avgs, grouped_grads, 1 - beta1)
        torch._foreach_mul_(grouped_exp_infs, beta2)
        if not maximize and weight_decay == 0:
            grouped_grads = torch._foreach_abs(grouped_grads)
        else:
            torch._foreach_abs_(grouped_grads)
        torch._foreach_add_(grouped_grads, eps)
        torch._foreach_maximum_(grouped_exp_infs, grouped_grads)
        bias_corrections: Union[tuple[Tensor, ...], list[Tensor]]
        if capturable:
            bias_corrections = torch._foreach_pow(beta1, grouped_state_steps)
            torch._foreach_sub_(bias_corrections, 1)
            torch._foreach_div_(bias_corrections, lr)
            denom = torch._foreach_mul(grouped_exp_infs, bias_corrections)
            torch._foreach_addcdiv_(grouped_params, grouped_exp_avgs, denom)
        else:
            bias_corrections = [1 - beta1 ** _get_value(step) for step in grouped_state_steps]
            step_size = [_get_value(lr) / bc * -1 for bc in bias_corrections]
            torch._foreach_addcdiv_(grouped_params, grouped_exp_avgs, grouped_exp_infs, step_size)

