def _ridge_regression(X, y, alpha, sample_weight=None, solver='auto', max_iter=None, tol=0.0001, verbose=0, positive=False, random_state=None, return_n_iter=False, return_intercept=False, return_solver=False, X_scale=None, X_offset=None, check_input=True, fit_intercept=False):
    (xp, is_array_api_compliant, device_) = get_namespace_and_device(X, y, sample_weight, X_scale, X_offset)
    is_numpy_namespace = _is_numpy_namespace(xp)
    X_is_sparse = sparse.issparse(X)
    has_sw = sample_weight is not None
    solver = resolve_solver(solver, positive, return_intercept, X_is_sparse, xp)
    if is_numpy_namespace and (not X_is_sparse):
        X = np.asarray(X)
    if not is_numpy_namespace and solver != 'svd':
        raise ValueError(f"Array API dispatch to namespace {xp.__name__} only supports solver 'svd'. Got '{solver}'.")
    if positive and solver != 'lbfgs':
        raise ValueError(f"When positive=True, only 'lbfgs' solver can be used. Please change solver {solver} to 'lbfgs' or set positive=False.")
    if solver == 'lbfgs' and (not positive):
        raise ValueError("'lbfgs' solver can be used only when positive=True. Please use another solver.")
    if return_intercept and solver != 'sag':
        raise ValueError("In Ridge, only 'sag' solver can directly fit the intercept. Please change solver to 'sag' or set return_intercept=False.")
    if check_input:
        _dtype = [xp.float64, xp.float32]
        _accept_sparse = _get_valid_accept_sparse(X_is_sparse, solver)
        X = check_array(X, accept_sparse=_accept_sparse, dtype=_dtype, order='C')
        y = check_array(y, dtype=X.dtype, ensure_2d=False, order=None)
    check_consistent_length(X, y)
    (n_samples, n_features) = X.shape
    if y.ndim > 2:
        raise ValueError('Target y has the wrong shape %s' % str(y.shape))
    if y.ndim == 1:
        y = xp.reshape(y, (-1, 1))
    (n_samples_, n_targets) = y.shape
    if n_samples != n_samples_:
        raise ValueError('Number of samples in X and y does not correspond: %d != %d' % (n_samples, n_samples_))
    if <MASK>:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
        if solver not in ['sag', 'saga']:
            (X, y, sample_weight_sqrt) = _rescale_data(X, y, sample_weight)
    if alpha is not None and (not isinstance(alpha, type(xp.asarray([0.0])))):
        alpha = check_scalar(alpha, 'alpha', target_type=numbers.Real, min_val=0.0, include_boundaries='left')
    alpha = _ravel(xp.asarray(alpha, device=device_, dtype=X.dtype), xp=xp)
    if alpha.shape[0] not in [1, n_targets]:
        raise ValueError('Number of targets and number of penalties do not correspond: %d != %d' % (alpha.shape[0], n_targets))
    if alpha.shape[0] == 1 and n_targets > 1:
        alpha = xp.full(shape=(n_targets,), fill_value=alpha[0], dtype=alpha.dtype, device=device_)
    n_iter = None
    if solver == 'sparse_cg':
        coef = _solve_sparse_cg(X, y, alpha, max_iter=max_iter, tol=tol, verbose=verbose, X_offset=X_offset, X_scale=X_scale, sample_weight_sqrt=sample_weight_sqrt if has_sw else None)
    elif solver == 'lsqr':
        (coef, n_iter) = _solve_lsqr(X, y, alpha=alpha, fit_intercept=fit_intercept, max_iter=max_iter, tol=tol, X_offset=X_offset, X_scale=X_scale, sample_weight_sqrt=sample_weight_sqrt if has_sw else None)
    elif solver == 'cholesky':
        if n_features > n_samples:
            K = safe_sparse_dot(X, X.T, dense_output=True)
            try:
                dual_coef = _solve_cholesky_kernel(K, y, alpha)
                coef = safe_sparse_dot(X.T, dual_coef, dense_output=True).T
            except linalg.LinAlgError:
                solver = 'svd'
        else:
            try:
                coef = _solve_cholesky(X, y, alpha)
            except linalg.LinAlgError:
                solver = 'svd'
    elif solver in ['sag', 'saga']:
        max_squared_sum = row_norms(X, squared=True).max()
        coef = np.empty((y.shape[1], n_features), dtype=X.dtype)
        n_iter = np.empty(y.shape[1], dtype=np.int32)
        intercept = np.zeros((y.shape[1],), dtype=X.dtype)
        for (i, (alpha_i, target)) in enumerate(zip(alpha, y.T)):
            init = {'coef': np.zeros((n_features + int(return_intercept), 1), dtype=X.dtype)}
            (coef_, n_iter_, _) = sag_solver(X, target.ravel(), sample_weight, 'squared', alpha_i, 0, max_iter, tol, verbose, random_state, False, max_squared_sum, init, is_saga=solver == 'saga')
            if return_intercept:
                coef[i] = coef_[:-1]
                intercept[i] = coef_[-1]
            else:
                coef[i] = coef_
            n_iter[i] = n_iter_
        if intercept.shape[0] == 1:
            intercept = intercept[0]
    elif solver == 'lbfgs':
        coef = _solve_lbfgs(X, y, alpha, positive=positive, tol=tol, max_iter=max_iter, X_offset=X_offset, X_scale=X_scale, sample_weight_sqrt=sample_weight_sqrt if has_sw else None)
    if solver == 'svd':
        if X_is_sparse:
            raise TypeError('SVD solver does not support sparse inputs currently')
        coef = _solve_svd(X, y, alpha, xp)
    if n_targets == 1:
        coef = _ravel(coef)
    coef = xp.asarray(coef)
    if return_n_iter and return_intercept:
        res = (coef, n_iter, intercept)
    elif return_intercept:
        res = (coef, intercept)
    elif return_n_iter:
        res = (coef, n_iter)
    else:
        res = coef
    return (*res, solver) if return_solver else res

def lookup(self, f_name, func_def=None, optional=False):
    if f_name in self._op_defs:
        return self._op_defs[f_name]
    if isinstance(func_def, types.FunctionType):
        if not hasattr(func_def, '_tfr_op_name'):
            if optional:
                return (None, None)
            else:
                raise KeyError('OpDef does not exist: ' + f_name)
        op_name = getattr(func_def, '_tfr_op_name')
    elif not func_def:
        op_name = f_name
    else:
        compose_dec = []
        for dec in func_def.decorator_list:
            if isinstance(dec, ast.Call):
                if isinstance(dec.func, ast.Attribute) and dec.func.attr == 'Composite':
                    compose_dec.append(dec)
                if isinstance(dec.func, ast.Name) and dec.func.id == 'Composite':
                    compose_dec.append(dec)
        if not compose_dec:
            if optional:
                return (None, None)
            else:
                raise KeyError('OpDef does not exist: ' + f_name)
        elif len(compose_dec) > 1:
            raise KeyError('More than one TF ops decomposes for.')
        else:
            op_name = compose_dec[0].args[0].value
    op_def = op_def_registry.get(op_name)
    if <MASK>:
        raise ValueError('Not a registered op: ' + op_name)
    derived_attrs = _collect_derived_attrs_from_proto(op_def)
    self._op_defs[f_name] = (op_def, derived_attrs)
    return (op_def, derived_attrs)

def _should_disable_fastpath(self, opinfo, rightmost_arg, rightmost_arg_type, dtype):
    if self.arity == 1:
        if 'foreach_abs' in opinfo.name and dtype in complex_types():
            return True
        if opinfo.ref in (torch.abs, torch.neg):
            return False
        if opinfo.ref_inplace == torch.Tensor.zero_:
            return False
        return dtype in integral_types_and(torch.bool)
    if self.arity < 2 or rightmost_arg_type == ForeachRightmostArgType.Tensor:
        return None
    if 'foreach_pow' in opinfo.name and dtype in integral_types_and(torch.bool):
        return True
    if any((foreach_name in opinfo.name for foreach_name in ('foreach_clamp_max', 'foreach_clamp_min', 'foreach_maximum', 'foreach_minimum'))) and dtype in integral_types_and(torch.bool):
        return True
    if rightmost_arg_type == ForeachRightmostArgType.TensorList:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if 'foreach_add' in opinfo.name and dtype == torch.bool:
            disable_fastpath = True
        return disable_fastpath
    elif <MASK>:
        disable_fastpath = 'foreach_div' in opinfo.name and dtype in integral_types_and(torch.bool)
        if isinstance(rightmost_arg, bool):
            disable_fastpath |= dtype == torch.bool
            if opinfo.ref in (torch.add, torch.mul):
                disable_fastpath = False
        elif isinstance(rightmost_arg, int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg, float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg, complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalar of type {rightmost_arg_type} - {rightmost_arg}')
        return disable_fastpath
    elif rightmost_arg_type == ForeachRightmostArgType.ScalarList:
        disable_fastpath = opinfo.ref == torch.div and dtype in integral_types_and(torch.bool)
        elmt_t = type(rightmost_arg[0])
        has_same_type = all((isinstance(v, elmt_t) for v in rightmost_arg))
        if not has_same_type:
            return dtype not in complex_types()
        if isinstance(rightmost_arg[0], bool):
            if ('foreach_add' in opinfo.name or 'foreach_mul' in opinfo.name) and dtype == torch.bool:
                disable_fastpath = False
        elif isinstance(rightmost_arg[0], int):
            disable_fastpath |= dtype == torch.bool
        elif isinstance(rightmost_arg[0], float):
            disable_fastpath |= dtype in integral_types_and(torch.bool)
        elif isinstance(rightmost_arg[0], complex):
            disable_fastpath |= dtype not in complex_types()
        else:
            raise AssertionError(f'Invalid scalarlist of {rightmost_arg}')
        return disable_fastpath
    else:
        raise AssertionError(f'Invalid rightmost_arg_type of {rightmost_arg_type}')

def sample_inputs_nll_loss(op_info, device, dtype, requires_grad, **kwargs):
    shape = (2, 3)
    num_classes = shape[1]
    make_input = partial(make_tensor, device=device, dtype=dtype, requires_grad=requires_grad)
    make_weight = partial(make_tensor, num_classes, device=device, dtype=dtype, requires_grad=False)

    def make_target(shape, zeros=False):
        s = (shape[0], *shape[2:]) if len(shape) > 1 else ()
        if <MASK>:
            return torch.zeros(s, device=device, dtype=torch.long)
        else:
            return make_tensor(s, low=0, high=shape[1] if len(shape) > 1 else shape[0], device=device, dtype=torch.long)

    def gen_shape_kwargs():
        shapes = (shape, (num_classes,), shape + (2, 2))
        reductions = ('none', 'mean', 'sum')
        for (reduction, s) in product(reductions, shapes):
            yield (make_input(s), make_target(s), dict(reduction=reduction))
            yield (make_input(s), make_target(s), dict(weight=make_weight(), reduction=reduction))
            yield (make_input(s), make_target(s), dict(weight=make_weight(low=0), reduction=reduction))
            if dtype.is_floating_point or dtype.is_complex:
                yield (make_input(s), make_target(s), dict(weight=make_weight(high=0), reduction=reduction))
            t = make_target(s)
            ignore = num_classes // 2
            if t.eq(ignore).all() and reduction == 'mean':
                t.fill_(0)
            yield (make_input(s), t, dict(ignore_index=num_classes // 2, reduction=reduction))
            yield (make_input(s), t, dict(ignore_index=num_classes // 2, reduction=reduction, weight=make_weight()))
            if reduction != 'mean':
                yield (make_input(s), make_target(s, zeros=True), dict(ignore_index=0, reduction=reduction))
    for (input, target, kwargs) in gen_shape_kwargs():
        yield SampleInput(input, args=(target,), kwargs=kwargs)
    target = torch.tensor([-1, 2], device=device, dtype=torch.long)
    yield SampleInput(make_input(shape), args=(target,), kwargs={'ignore_index': -1})

def whichmodule(self, obj: Any, name: str) -> str:
    """Find the module name an object belongs to.

        This should be considered internal for end-users, but developers of
        an importer can override it to customize the behavior.

        Taken from pickle.py, but modified to exclude the search into sys.modules
        """
    module_name = getattr(obj, '__module__', None)
    if module_name is not None:
        return module_name
    for (module_name, module) in self.modules.copy().items():
        if <MASK>:
            continue
        try:
            if _getattribute(module, name)[0] is obj:
                return module_name
        except AttributeError:
            pass
    return '__main__'

def _check_distribution(self, distribution):
    if not isinstance(distribution, dict):
        if <MASK>:
            raise AssertionError(f'Unknown distribution: {distribution}')
    else:
        if any((i < 0 for i in distribution.values())):
            raise AssertionError('Probabilities cannot be negative')
        if not abs(sum(distribution.values()) - 1) > 1e-05:
            raise AssertionError('Distribution is not normalized')
        if self._minval is not None:
            raise AssertionError("When passing a custom distribution, 'minval' must be None")
        if self._maxval is not None:
            raise AssertionError("When passing a custom distribution, 'maxval' must be None")
    return distribution

def __call__(self, path, parent, children):
    """Visitor interface, see `traverse` for details."""
    if tf_inspect.ismodule(parent) and len(path.split('.')) > 10:
        raise RuntimeError('Modules nested too deep:\n%s.%s\n\nThis is likely a problem with an accidental public import.' % (self._root_name, path))
    full_path = '.'.join([self._root_name, path]) if path else self._root_name
    for (name, child) in list(children):
        if <MASK>:
            children.remove((name, child))
    self._visitor(path, parent, children)
    for (name, child) in list(children):
        if self._do_not_descend(full_path, name):
            children.remove((name, child))

def is_expandable_to(shape: ShapeType, desired: ShapeType) -> bool:
    """Checks if a shape can be expanded to another shape.
    This is equivalent to checking if the two shapes are broadcastable.
    """
    if len(shape) > len(desired):
        return False
    for i in range(len(shape)):
        if <MASK>:
            return False
    return True

def __init__(self, enabled=True, *, use_cuda=False, use_device=None, record_shapes=False, with_flops=False, profile_memory=False, with_stack=False, with_modules=False, use_kineto=False, use_cpu=True, experimental_config=None, acc_events=False, custom_trace_id_callback=None):
    self.enabled: bool = enabled
    if not self.enabled:
        return
    self.use_cuda = use_cuda
    if self.use_cuda:
        warn("The attribute `use_cuda` will be deprecated soon, please use ``use_device = 'cuda'`` instead.", FutureWarning, stacklevel=2)
        self.use_device: Optional[str] = 'cuda'
    else:
        self.use_device = use_device
    self._function_events: Optional[EventList] = None
    self._old_function_events: Optional[EventList] = None
    self._needs_processing = False
    self.entered = False
    self.record_shapes = record_shapes
    self.with_flops = with_flops
    self.record_shapes |= self.with_flops
    self.profile_memory = profile_memory
    self.with_stack = with_stack
    self.with_modules = with_modules
    self.use_cpu = use_cpu
    self.acc_events = acc_events
    if experimental_config is None:
        experimental_config = _ExperimentalConfig()
    self.experimental_config = experimental_config
    self.kineto_results: Optional[_ProfilerResult] = None
    self.profiling_start_time_ns = 0
    self.profiling_end_time_ns = 0
    self._stats = _ProfilerStats()
    self.custom_trace_id_callback = custom_trace_id_callback
    self.trace_id = ''
    if not self.use_cpu:
        if not use_kineto:
            raise AssertionError('Device-only events supported only with Kineto (use_kineto=True)')
    if self.use_device is not None:
        VALID_DEVICE_OPTIONS = ['cuda', 'xpu', 'mtia', 'hpu']
        if _get_privateuse1_backend_name() != 'privateuseone':
            VALID_DEVICE_OPTIONS.append(_get_privateuse1_backend_name())
        if self.use_device not in VALID_DEVICE_OPTIONS:
            warn(f'The {self.use_device} is not a valid device option.')
            self.use_device = None
        if self.use_device == 'cuda' and (not torch.cuda.is_available()):
            warn('CUDA is not available, disabling CUDA profiling')
            self.use_cuda = False
            self.use_device = None
        if self.use_device == 'xpu' and (not torch.xpu.is_available()):
            warn('XPU is not available, disabling XPU profiling')
            self.use_device = None
        if self.use_device == 'hpu' and (not (hasattr(torch, 'hpu') and torch.hpu.is_available())):
            warn('HPU is not available, disabling HPU profiling')
            self.use_device = None
    self.kineto_activities = set()
    if self.use_cpu:
        self.kineto_activities.add(ProfilerActivity.CPU)
    self.profiler_kind = ProfilerState.KINETO
    if self.use_device == 'cuda':
        if not use_kineto or ProfilerActivity.CUDA not in _supported_activities():
            if not self.use_cpu:
                raise AssertionError('Legacy CUDA profiling requires use_cpu=True')
            self.profiler_kind = ProfilerState.KINETO_GPU_FALLBACK
        else:
            self.kineto_activities.add(ProfilerActivity.CUDA)
    elif self.use_device == 'xpu':
        if not (use_kineto and ProfilerActivity.XPU in _supported_activities()):
            raise AssertionError('Legacy XPU profiling is not supported. Requires use_kineto=True on XPU devices.')
        self.kineto_activities.add(ProfilerActivity.XPU)
    elif self.use_device == 'mtia':
        if not (use_kineto and ProfilerActivity.MTIA in _supported_activities()):
            raise AssertionError('Legacy MTIA profiling is not supported. Requires use_kineto=True on MTIA devices.')
        self.kineto_activities.add(ProfilerActivity.MTIA)
    elif self.use_device == 'hpu':
        if not (use_kineto and ProfilerActivity.HPU in _supported_activities()):
            raise AssertionError('Legacy HPU profiling is not supported. Requires use_kineto=True on HPU devices.')
        self.kineto_activities.add(ProfilerActivity.HPU)
    elif self.use_device is not None and self.use_device != 'privateuseone':
        if <MASK>:
            if not self.use_cpu:
                raise AssertionError('Legacy custombackend profiling requires use_cpu=True')
            self.profiler_kind = ProfilerState.KINETO_PRIVATEUSE1_FALLBACK
        else:
            self.kineto_activities.add(ProfilerActivity.PrivateUse1)
    if len(self.kineto_activities) == 0:
        raise AssertionError('No activities specified for the profiler')

def should_use_v2():
    """Determine if v1 or v2 version should be used."""
    if <MASK>:
        return True
    elif ops.executing_eagerly_outside_functions():
        graph = ops.get_default_graph()
        if getattr(graph, 'name', False) and graph.name.startswith('wrapped_function'):
            return False
        return True
    else:
        return False

@register_meta([aten.linalg_solve_triangular.default, aten.linalg_solve_triangular.out])
def linalg_solve_triangular_meta(A: Tensor, B: Tensor, *, upper: bool, left: bool=True, unitriangular: bool=False, out: Optional[Tensor]=None) -> Tensor:
    if <MASK>:
        out = A.new_empty([0])
    assert isinstance(out, TensorLike)
    checkInputsSolver(A, B, left, 'linalg.solve_triangular')
    (B_, A_) = _linalg_broadcast_batch_dims_name(B, A, None)
    avoid_copy_A = A_.transpose(-2, -1).is_contiguous() and A_.is_conj()
    if avoid_copy_A:
        out = _maybe_resize_out(out, B_.shape)
    elif _resize_output_check(out, B_.shape):
        out.resize_(B_.transpose(-2, -1).shape)
        out.transpose_(-2, -1)
    return out

