def common_dtype_categorical_compat(objs: Sequence[Index | ArrayLike], dtype: DtypeObj) -> DtypeObj:
    """
    Update the result of find_common_type to account for NAs in a Categorical.

    Parameters
    ----------
    objs : list[np.ndarray | ExtensionArray | Index]
    dtype : np.dtype or ExtensionDtype

    Returns
    -------
    np.dtype or ExtensionDtype
    """
    if <MASK>:
        for obj in objs:
            obj_dtype = getattr(obj, 'dtype', None)
            if isinstance(obj_dtype, CategoricalDtype):
                if isinstance(obj, ABCIndex):
                    hasnas = obj.hasnans
                else:
                    hasnas = cast('Categorical', obj)._hasna
                if hasnas:
                    dtype = np.dtype(np.float64)
                    break
    return dtype

def _write_header(self, data_label: str | None=None, time_stamp: datetime | None=None) -> None:
    byteorder = self._byteorder
    self._write_bytes(struct.pack('b', 114))
    self._write(byteorder == '>' and '\x01' or '\x02')
    self._write('\x01')
    self._write('\x00')
    self._write_bytes(struct.pack(byteorder + 'h', self.nvar)[:2])
    self._write_bytes(struct.pack(byteorder + 'i', self.nobs)[:4])
    if data_label is None:
        self._write_bytes(self._null_terminate_bytes(_pad_bytes('', 80)))
    else:
        self._write_bytes(self._null_terminate_bytes(_pad_bytes(data_label[:80], 80)))
    if <MASK>:
        time_stamp = datetime.now()
    elif not isinstance(time_stamp, datetime):
        raise ValueError('time_stamp should be datetime type')
    months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    month_lookup = {i + 1: month for (i, month) in enumerate(months)}
    ts = time_stamp.strftime('%d ') + month_lookup[time_stamp.month] + time_stamp.strftime(' %Y %H:%M')
    self._write_bytes(self._null_terminate_bytes(ts))

def _get_repr(arg: Any) -> str:
    if isinstance(arg, Node):
        return repr(arg)
    elif isinstance(arg, tuple) and hasattr(arg, '_fields'):
        qualified_name = _get_qualified_name(type(arg))
        global_name = add_global(qualified_name, type(arg))
        return f'{global_name}{repr(tuple(arg))}'
    elif isinstance(arg, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)):
        qualified_name = _get_qualified_name(arg)
        global_name = add_global(qualified_name, arg)
        return f'{global_name}'
    elif isinstance(arg, enum.Enum):
        cls = arg.__class__
        clsname = add_global(cls.__name__, cls)
        return f'{clsname}.{arg.name}'
    elif isinstance(arg, torch.Tensor):
        size = list(arg.size())
        dtype = str(arg.dtype).split('.')[-1]
        return f'torch.Tensor(size={size}, dtype={dtype})'
    elif isinstance(arg, tuple):
        if len(arg) == 1:
            return f'({_get_repr(arg[0])},)'
        else:
            return '(' + ', '.join((_get_repr(a) for a in arg)) + ')'
    elif <MASK>:
        return '[' + ', '.join((_get_repr(a) for a in arg)) + ']'
    elif isinstance(arg, slice):
        return f'slice({_get_repr(arg.start)}, {_get_repr(arg.stop)}, {_get_repr(arg.step)})'
    else:
        return blue(repr(arg))

def load_tensor(dtype, numel, key, location):
    name = f'data/{key}'
    if torch._guards.detect_fake_mode(None) is not None:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes, device='meta')
        if can_calculate_storage_offsets:
            storage._checkpoint_offset = _get_offset(key, name, numel)
        else:
            storage._checkpoint_offset = zip_file.get_record_offset(name)
    elif _serialization_tls.skip_data:
        nbytes = numel * torch._utils._element_size(dtype)
        storage = torch.UntypedStorage(nbytes)
    elif overall_storage is not None:
        if can_calculate_storage_offsets and calculate_storage_offsets:
            storage_offset = _get_offset(key, name, numel)
            if run_debug_asserts:
                if storage_offset != zip_file.get_record_offset(name):
                    raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        else:
            storage_offset = zip_file.get_record_offset(name)
        storage = overall_storage[storage_offset:storage_offset + numel]
    else:
        if can_calculate_storage_offsets and run_debug_asserts:
            storage_offset = _get_offset(key, name, numel)
            if storage_offset != zip_file.get_record_offset(name):
                raise RuntimeError(f'This is a debug assert that was run as the `TORCH_SERIALIZATION_DEBUG` environment variable was set: Incorrect offset for {name}, got {storage_offset} expected {zip_file.get_record_offset(name)}')
        storage = zip_file.get_storage_from_record(name, numel, torch.UntypedStorage)._typed_storage()._untyped_storage
    if <MASK>:
        if byteorderdata.decode() != sys.byteorder:
            storage.byteswap(dtype)
    if torch._guards.detect_fake_mode(None) is None:
        wrap_storage = restore_location(storage, location)
    else:
        storage._fake_device = location
        wrap_storage = storage
    typed_storage = torch.storage.TypedStorage(wrap_storage=wrap_storage, dtype=dtype, _internal=True)
    if typed_storage._data_ptr() != 0:
        loaded_storages[key] = typed_storage
    return typed_storage

def validate_synchronization_aggregation_trainable(synchronization, aggregation, trainable, name):
    """Given user-provided variable properties, sets defaults and validates."""
    if <MASK>:
        aggregation = VariableAggregation.NONE
    elif not isinstance(aggregation, (VariableAggregation, VariableAggregationV2)):
        try:
            aggregation = VariableAggregationV2(aggregation)
        except ValueError:
            raise ValueError('Invalid variable aggregation mode: {} for variable: {}'.format(aggregation, name))
    if synchronization is None:
        synchronization = VariableSynchronization.AUTO
    else:
        try:
            synchronization = VariableSynchronization(synchronization)
        except ValueError:
            raise ValueError('Invalid variable synchronization mode: {} for variable: {}'.format(synchronization, name))
    if trainable is None:
        trainable = synchronization != VariableSynchronization.ON_READ
    return (synchronization, aggregation, trainable)

def _replace_region_with_subgraph(graph: torch.fx.Graph, region: Region, get_subgraph_node: Node, external_node_usages: Iterable[OrderedSet[UsageIndex]], node_usage_to_tuple_elems: dict[UsageIndex, OrderedSet[int]], ind_to_tuple_spec: dict[int, dict[tuple[int, ...], int]], inds_with_external_users: list[int], subgraph_name: str, node_to_additional_deps: dict[Node, OrderedSet[Node]], node_to_mutated_arg_positions: dict[Node, OrderedSet[int]]) -> None:
    sub_args = []
    flattened_getitem_nodes: OrderedSet[Node] = OrderedSet()
    for usages in external_node_usages:
        usage = next(iter(usages))
        (node_ind, usage_ind) = usage
        node = region[node_ind]
        flattened_args_kwargs = _get_flat_args(node, {})
        for (user_ind, node_usage_ind) in usages:
            user = region[user_ind]
            if user in node_to_mutated_arg_positions:
                if node_usage_ind in node_to_mutated_arg_positions[user]:
                    log.debug('NYI: Failed to substitute region %s due to mutation', region)
                    return
        if usage in node_usage_to_tuple_elems:
            tuple_elems = [region[i] for i in node_usage_to_tuple_elems[usage]]
            flattened_getitem_nodes.update(tuple_elems)
            sub_args.extend(tuple_elems)
        else:
            sub_args.append(flattened_args_kwargs[usage_ind])
    if _has_aliasing(region, sub_args, inds_with_external_users, flattened_getitem_nodes):
        return
    invoke_args = (get_subgraph_node, subgraph_name, *sub_args)
    invoke_subgraph_node = graph.create_node('call_function', torch.ops.higher_order.invoke_subgraph, invoke_args, {})
    ind = 0
    flattened_output_nodes: OrderedSet[Node] = OrderedSet()
    for external_user_ind in inds_with_external_users:
        node = region[external_user_ind]
        if _is_tuple_node(node):
            tuple_spec = ind_to_tuple_spec[external_user_ind]
            flattened_output_nodes.update(_replace_tuple_outputs(node, ind, tuple_spec, invoke_subgraph_node, graph))
            ind += len(tuple_spec)
        else:
            subgraph_output = graph.create_node('call_function', operator.getitem, (invoke_subgraph_node, ind), {})
            node.replace_all_uses_with(subgraph_output, propagate_meta=True)
            ind += 1
    for node in reversed(region):
        if node in flattened_getitem_nodes:
            continue
        if <MASK>:
            graph.erase_node(node)
        node_to_additional_deps.pop(node, None)
        for deps in node_to_additional_deps.values():
            try:
                deps.remove(node)
                deps.add(invoke_subgraph_node)
            except KeyError:
                pass
    if config.graph_deduplication_lint:
        print(_detect_cycles(graph, node_to_additional_deps))
        _stable_topological_sort(graph, node_to_additional_deps)
        graph.lint()

