    return (value, use_dill)

def create_proxy(self, kind: str, target: Any, args: Any, kwargs: Any, name: Optional[str]=None, type_expr: Optional[Any]=None, proxy_factory_fn: Optional[Callable[[fx.Node], fx.Proxy]]=None) -> fx.Proxy:
    if self.parent is not None:
        (flat_args, tree_spec) = pytree.tree_flatten((args, kwargs))
        new_flat_args = []
        for arg in flat_args:
            maybe_new_arg = self.maybe_lift_tracked_freevar_to_input(arg)
            new_flat_args.append(maybe_new_arg)
        (args, kwargs) = pytree.tree_unflatten(new_flat_args, tree_spec)
    rv = super().create_proxy(kind, target, args, kwargs, name, type_expr, proxy_factory_fn)
    tx = self.output_graph.current_tx
    if sys.version_info >= (3, 11) and kind in ('call_function', 'call_method', 'call_module'):
        cur_inst = tx.current_instruction
        if cur_inst is not self.prev_inst and cur_inst.positions is not None and (cur_inst.positions.lineno is not None):
            tx_code = tx.f_code
            header = tx.get_line_of_code_header(lineno=cur_inst.positions.lineno)

            def get_trace_call_log_str() -> str:
                line = get_instruction_source_311(tx_code, cur_inst).rstrip()
                return f'TRACE FX call {rv.node.name} from {header}\n{line}'
            trace_call_log.debug('%s', LazyString(get_trace_call_log_str))
            self.prev_inst = cur_inst
    is_retracing = False
    if tx.f_code is not self._cur_code:
        orig_graphmodule_maybe = code_context.get_context(tx.f_code).get('orig_graphmodule', lambda : None)()
        if isinstance(orig_graphmodule_maybe, torch.fx.GraphModule):
            is_retracing = True
            self._orig_gm_meta = [nd.meta for nd in orig_graphmodule_maybe.graph.nodes]
            self._orig_gm_lineno_map = orig_graphmodule_maybe._lineno_map
            self._orig_gm_firstlineno = orig_graphmodule_maybe.forward.__code__.co_firstlineno
        else:
            self._orig_gm_meta = None
            self._orig_gm_lineno_map = None
            self._orig_gm_firstlineno = None
    nn_module_stack = tx.nn_module_stack
    if <MASK>:
        rv.node.meta['nn_module_stack'] = nn_module_stack.copy()
    if kind in {'call_function', 'call_method'}:
        stack = (rv.node.name, target)
        if nn_module_stack:
            current_nn_module = list(rv.node.meta['nn_module_stack'].values())[-1][1]
            if current_nn_module.__module__.startswith(('torch.nn.modules', 'torch.ao.')) and (not current_nn_module.__module__.startswith('torch.nn.modules.container')):
                stack = (rv.node.name, current_nn_module)
        rv.node.meta['source_fn_stack'] = self.source_fn_stack + [stack]
    elif kind == 'call_module':
        if self.parent is not None:
            unimplemented_v2(gb_type='Invoking an nn.Module inside a higher order operator', context=f'Higher order op name: {self.source_target}', explanation='This is not supported.', hints=[])
        rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, next((ty for (k, (_, ty)) in rv.node.meta['nn_module_stack'].items() if k.split('@')[0] == target)))]
    self._maybe_preserve_original_meta(tx, rv.node)
    if not is_retracing:
        if 'nn_module_stack' not in rv.node.meta:
            nn_module_stack = tx.nn_module_stack
            if nn_module_stack:
                rv.node.meta['nn_module_stack'] = nn_module_stack.copy()
        if 'source_fn_stack' not in rv.node.meta:
            if kind in {'call_function', 'call_method'}:
                rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, target)]
            elif kind == 'call_module':
                if self.parent is not None:
                    unimplemented_v2(gb_type='Invoking an nn.Module inside a HigherOrderOperator', context='', explanation='This is not supported.', hints=[])
                rv.node.meta['source_fn_stack'] = self.source_fn_stack + [(rv.node.name, rv.node.meta['nn_module_stack'][target][1])]
    if 'stack_trace' not in rv.node.meta:
        frame_summaries: list[traceback.FrameSummary] = []
        while tx:
            if not tx.is_co_filename_from_nn_modules():
                frame_summaries.append(tx.frame_summary())
            tx = getattr(tx, 'parent', None)
        filtered_frame_summaries = [frame for frame in frame_summaries if frame.filename not in uninteresting_files()]
        filtered_frame_summaries.reverse()
        msgs = traceback.StackSummary.from_list(filtered_frame_summaries).format()
        rv.node.stack_trace = ''.join(msgs)
    if torch._dynamo.config.use_graph_deduplication or torch._dynamo.config.track_nodes_for_deduplication:
        self.output_graph.region_tracker.track_node(self.output_graph.current_tx, rv.node)
    return rv

@_tf_export(v1=['lite.experimental.convert_op_hints_to_stubs'])
