def _determine_output_number(signature: _schemas.OpSignature, named_attrs: Mapping[str, ValidAttributeType]) -> int:
    """Determine the number of outputs for the node with heuristics."""
    if <MASK>:
        if signature.name == 'BatchNormalization':
            if not named_attrs.get('training_mode', 0):
                return 1
        if signature.name == 'Split':
            num_outputs = named_attrs.get('num_outputs')
            if num_outputs is not None and isinstance(num_outputs, int):
                return num_outputs
            else:
                raise ValueError('Could not determine the number of outputs for Split. num_outputs must be provided')
    return len(signature.outputs)

@staticmethod
def constant(value, dtype):
    if isinstance(value, ValueRanges):
        if <MASK>:
            raise AssertionError('ValueRanges must be a singleton for constant()')
        value = value.lower
    is_python = isinstance(value, (int, float, bool))
    if not is_python and (not isinstance(value, (BooleanAtom, sympy.Integer, sympy.Number))):
        raise AssertionError(f'not a supported constant type: {type(value)}')
    if isinstance(value, SupportsFloat) and math.isnan(value):
        if dtype == torch.bool:
            return ValueRanges.unknown_bool()
        elif dtype.is_floating_point:
            return ValueRanges.unknown()
        else:
            return ValueRanges.unknown_int()
    if is_python:
        type_ = dtype_to_type(dtype)
        value = type_(value)
    elif dtype == torch.bool:
        if not isinstance(value, BooleanAtom):
            raise AssertionError('expected BooleanAtom for bool dtype')
    elif dtype.is_floating_point:
        if value.is_finite and (not value.is_real):
            raise AssertionError('expected float-like sympy value for float dtype')
    elif not getattr(value, 'is_integer', False):
        raise AssertionError('expected integer sympy value for int dtype')
    r = ValueRanges.wrap(value)
    return r

def _modify_model_input_type_per_subgraph(model, subgraph_index, signature_index, inference_input_type):
    """Modify model input type per subgraph."""
    subgraph = model.subgraphs[subgraph_index]
    tensors = subgraph.tensors
    operators = subgraph.operators
    quant_opcode_idxs = get_quantize_opcode_idx(model)
    if operators and (not quant_opcode_idxs):
        for input_idx in subgraph.inputs:
            input_type = _convert_tflite_enum_type_to_tf_type(tensors[input_idx].type)
            if input_type == dtypes.float32:
                raise ValueError('Model input is not dequantized.')
