    input_quant_ops = []
    for op in operators:
        if op.opcodeIndex in quant_opcode_idxs and op.inputs[0] in subgraph.inputs:
            (float_tensor, quant_tensor) = (tensors[op.inputs[0]], tensors[op.outputs[0]])
            float_type = _convert_tflite_enum_type_to_tf_type(float_tensor.type)
            if <MASK>:
                if float_type == inference_input_type:
                    continue
                else:
                    raise ValueError("Initial model input type must be tf.float32. Expected type for tensor with name '{}' is tf.float32, instead type is {}".format(float_tensor.name, get_tf_type_name(float_type)))
            quant_type = _convert_tflite_enum_type_to_tf_type(quant_tensor.type)
            if quant_type not in _MAP_QUANT_TO_IO_TYPES:
                raise ValueError("Initial model input is not quantized. Expected type for tensor with name '{}' should be in {}, instead type is {}".format(quant_tensor.name, tuple((get_tf_type_name(t) for t in _MAP_QUANT_TO_IO_TYPES.keys())), get_tf_type_name(quant_type)))
            else:
                inference_io_types = _MAP_QUANT_TO_IO_TYPES[quant_type]
                if inference_input_type not in inference_io_types:
                    raise ValueError('Unsupported `inference_input_type` value. Expected to be in {}, instead got {}.'.format(tuple((get_tf_type_name(t) for t in inference_io_types)), get_tf_type_name(inference_input_type)))
            input_quant_ops.append(op)
    if len(subgraph.inputs) != len(input_quant_ops):
        logging.warning('For model inputs containing unsupported operations which cannot be quantized, the `inference_input_type` attribute will default to the original type.')
    if inference_input_type == dtypes.uint8:
        for op in input_quant_ops:
            int8_quantization = tensors[op.outputs[0]].quantization
            uint8_quantization = schema_fb.QuantizationParametersT()
            uint8_quantization.scale = [int8_quantization.scale[0]]
            uint8_quantization.zeroPoint = [int8_quantization.zeroPoint[0] + 128]
            tensors[op.inputs[0]].quantization = uint8_quantization
            tensors[op.inputs[0]].type = schema_fb.TensorType.UINT8
    elif inference_input_type in _MAP_QUANT_TO_IO_TYPES:
        remove_tensors_idxs = set()
        for op in input_quant_ops:
            subgraph.inputs[subgraph.inputs == op.inputs[0]] = op.outputs[0]
            if signature_index >= 0:
                signature_def = model.signatureDefs[signature_index]
                for i in range(len(signature_def.inputs)):
                    if signature_def.inputs[i].tensorIndex == op.inputs[0]:
                        signature_def.inputs[i].tensorIndex = op.outputs[0]
            remove_tensors_idxs.add(op.inputs[0])
            operators.remove(op)
        _remove_tensors_from_model(model, remove_tensors_idxs)
    else:
        raise ValueError('Unsupported `inference_input_type` value {}.'.format(get_tf_type_name(inference_input_type)))

def _handle_object(self, obj):
    data = {}
    m2m_data = {}
    deferred_fields = {}
    try:
        Model = self._get_model_from_node(obj['model'])
    except base.DeserializationError:
        if self.ignorenonexistent:
            return
        raise
    if 'pk' in obj:
        try:
            data[Model._meta.pk.attname] = Model._meta.pk.to_python(obj.get('pk'))
        except Exception as e:
            raise base.DeserializationError.WithData(e, obj['model'], obj.get('pk'), None)
    if Model not in self.field_names_cache:
        self.field_names_cache[Model] = {f.name for f in Model._meta.get_fields()}
    field_names = self.field_names_cache[Model]
    for (field_name, field_value) in obj['fields'].items():
        if self.ignorenonexistent and field_name not in field_names:
            continue
        field = Model._meta.get_field(field_name)
        if field.remote_field and isinstance(field.remote_field, models.ManyToManyRel):
            try:
                values = self._handle_m2m_field_node(field, field_value)
                if values == base.DEFER_FIELD:
                    deferred_fields[field] = field_value
                else:
                    m2m_data[field.name] = values
            except base.M2MDeserializationError as e:
                raise base.DeserializationError.WithData(e.original_exc, obj['model'], obj.get('pk'), e.pk)
        elif field.remote_field and isinstance(field.remote_field, models.ManyToOneRel):
            try:
                value = self._handle_fk_field_node(field, field_value)
                if <MASK>:
                    deferred_fields[field] = field_value
                else:
                    data[field.attname] = value
            except Exception as e:
                raise base.DeserializationError.WithData(e, obj['model'], obj.get('pk'), field_value)
        else:
            try:
                data[field.name] = field.to_python(field_value)
            except Exception as e:
                raise base.DeserializationError.WithData(e, obj['model'], obj.get('pk'), field_value)
    model_instance = base.build_instance(Model, data, self.using)
    yield base.DeserializedObject(model_instance, m2m_data, deferred_fields)

@classmethod
def profile_compile_time(cls, func: Any, phase_name: str, *args: Any, **kwargs: Any) -> Any:

    def skip() -> Any:
        return func(*args, **kwargs)
    if not cls.enabled:
        return skip()
    if <MASK>:
        logger.error('profiler is not set')
        return
    frame_id = cls.get_frame()
    if cls.inside_profile_compile_time:
        cls.ignored_profile_runs += 1
        logger.info('profile_compile_time is requested for phase: %s, frame %s, while already in running phase: %s,frame %s, recursive call ignored', phase_name, frame_id, cls.current_phase, frame_id)
        return skip()
    if cls.frame_id_filter is not None:
        should_run = re.match(cls.frame_id_filter, frame_id) is not None
        if not should_run:
            logger.info('profiling frame %s is skipped due to frame_id_filter %s', frame_id, cls.frame_id_filter)
            return skip()
    cls.inside_profile_compile_time = True
    cls.current_phase = phase_name
    logger.info('profiling frame %s', frame_id)
    work_result = cls.profiler.profile(func, *args, **kwargs)
    if cls.profiler.profile_result is not None:
        cls.success_profile_count += 1
    else:
        cls.failed_profile_count += 1
    cls._log_stats()
    cls.inside_profile_compile_time = False
    return work_result

@register_op_strategy([aten._foreach_norm.Scalar], schema_info=RuntimeSchemaInfo(1, needs_pytree=True))
def foreach_norm_strategy(op_schema: OpSchema) -> TupleStrategy:
    args_schema = op_schema.args_schema
    input_tuple_strategy = args_schema[0]
    if <MASK>:
        raise AssertionError(f'Expected TupleStrategy, got {type(input_tuple_strategy)}')
    norm_type = args_schema[1] if len(args_schema) > 1 else 2
    if not isinstance(norm_type, (int, float, str)):
        raise AssertionError(f'Expected int, float, or str, got {type(norm_type)}')
    output_tuple_strategy_children: list[OpStrategy] = []
    for op_strategy in input_tuple_strategy.children:
        if not isinstance(op_strategy, OpStrategy):
            raise AssertionError(f'Expected OpStrategy, got {type(op_strategy)}')
        reduce_dims = list(range(op_strategy.ndim))
        output_strategy = common_reduction_strategy(op_strategy, reduce_dims, reduction_linear=True, reduction_op=NormReduction(norm_type))
        output_tuple_strategy_children.append(output_strategy)
    return TupleStrategy(output_tuple_strategy_children)

def _make_concat_multiindex(indexes, keys, levels=None, names=None) -> MultiIndex:
    if levels is None and isinstance(keys[0], tuple) or (levels is not None and len(levels) > 1):
        zipped = list(zip(*keys))
        if names is None:
            names = [None] * len(zipped)
        if levels is None:
            (_, levels) = factorize_from_iterables(zipped)
        else:
            levels = [ensure_index(x) for x in levels]
            validate_unique_levels(levels)
    else:
        zipped = [keys]
        if names is None:
            names = [None]
        if levels is None:
            levels = [ensure_index(keys).unique()]
        else:
            levels = [ensure_index(x) for x in levels]
            validate_unique_levels(levels)
    if not all_indexes_same(indexes):
        codes_list = []
        for (hlevel, level) in zip(zipped, levels):
            to_concat = []
            if isinstance(hlevel, Index) and hlevel.equals(level):
                lens = [len(idx) for idx in indexes]
                codes_list.append(np.repeat(np.arange(len(hlevel)), lens))
            else:
                for (key, index) in zip(hlevel, indexes):
                    mask = isna(level) & isna(key) | (level == key)
                    if not mask.any():
                        raise ValueError(f'Key {key} not in level {level}')
                    i = np.nonzero(mask)[0][0]
                    to_concat.append(np.repeat(i, len(index)))
                codes_list.append(np.concatenate(to_concat))
        concat_index = _concat_indexes(indexes)
        if isinstance(concat_index, MultiIndex):
            levels.extend(concat_index.levels)
            codes_list.extend(concat_index.codes)
        else:
            (codes, categories) = factorize_from_iterable(concat_index)
            levels.append(categories)
            codes_list.append(codes)
        if <MASK>:
            names = list(names)
        else:
            if not len({idx.nlevels for idx in indexes}) == 1:
                raise AssertionError('Cannot concat indices that do not have the same number of levels')
            names = list(names) + list(get_unanimous_names(*indexes))
        return MultiIndex(levels=levels, codes=codes_list, names=names, verify_integrity=False)
    new_index = indexes[0]
    n = len(new_index)
    kpieces = len(indexes)
    new_names = list(names)
    new_levels = list(levels)
    new_codes = []
    for (hlevel, level) in zip(zipped, levels):
        hlevel_index = ensure_index(hlevel)
        mapped = level.get_indexer(hlevel_index)
        mask = mapped == -1
        if mask.any():
            raise ValueError(f'Values not found in passed level: {hlevel_index[mask]!s}')
        new_codes.append(np.repeat(mapped, n))
    if isinstance(new_index, MultiIndex):
        new_levels.extend(new_index.levels)
        new_codes.extend((np.tile(lab, kpieces) for lab in new_index.codes))
    else:
        new_levels.append(new_index.unique())
        single_codes = new_index.unique().get_indexer(new_index)
        new_codes.append(np.tile(single_codes, kpieces))
    if len(new_names) < len(new_levels):
        new_names.extend(new_index.names)
    return MultiIndex(levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False)

def testMethod(self):

    class MyModel:

        def __init__(self):
            self.var = None

        @polymorphic_function.function
        def apply(self, x):
            if <MASK>:
                self.var = variables.Variable(2.0)
            return self.var * x
    m0 = MyModel()
    self.assertAllEqual(m0.apply(3.0), 6.0)
    m0.var.assign(3.0)
    self.assertAllEqual(m0.apply(3.0), 9.0)
    m1 = MyModel()
    self.assertAllEqual(m1.apply(3.0), 6.0)

@combinations.generate(combinations.combine(mode=['eager'], distribution=[strategy_combinations.one_device_strategy, strategy_combinations.mirrored_strategy_with_one_cpu, strategy_combinations.mirrored_strategy_with_gpu_and_cpu, strategy_combinations.tpu_strategy, strategy_combinations.central_storage_strategy_with_two_gpus, strategy_combinations.multi_worker_mirrored_2x2_gpu, strategy_combinations.multi_worker_mirrored_2x2_gpu_no_merge_call, strategy_combinations.multi_worker_mirrored_2x1_cpu]))
def testGetNextOptionalShapeEmpty(self, distribution):
    batch_size = 8
    dataset = dataset_ops.DatasetV2.from_tensor_slices({'feature': array_ops.ones([batch_size, 10]), 'label': array_ops.ones([batch_size])})
    dataset = dataset.batch(batch_size, drop_remainder=True)
    dataset = dataset.repeat()
    dist_dataset = distribution.experimental_distribute_dataset(dataset)
    per_replica_batch_size = batch_size // distribution.num_replicas_in_sync

    @def_function.function
    def train_fn():
        data = iter(dist_dataset).get_next_as_optional()
        feature_specs = data.element_spec['feature']._component_specs
        value_specs = data.element_spec['label']._component_specs
        if <MASK>:
            feature_specs = (feature_specs,)
            value_specs = (value_specs,)
        for replica_id in range(len(distribution.extended.worker_devices)):
            self.assertEqual([per_replica_batch_size, 10], feature_specs[replica_id].shape.as_list())
            self.assertEqual([per_replica_batch_size], value_specs[replica_id].shape.as_list())
    train_fn()

def _infer_frame_shape(signal, frame_length, frame_step, pad_end, axis):
    """Infers the shape of the return value of `frame`."""
    frame_length = tensor_util.constant_value(frame_length)
    frame_step = tensor_util.constant_value(frame_step)
    axis = tensor_util.constant_value(axis)
    if signal.shape.ndims is None:
        return None
    if axis is None:
        return [None] * (signal.shape.ndims + 1)
    signal_shape = signal.shape.as_list()
    num_frames = None
    frame_axis = signal_shape[axis]
    outer_dimensions = signal_shape[:axis]
    inner_dimensions = signal_shape[axis:][1:]
    if <MASK>:
        if frame_step is not None and pad_end:
            num_frames = max(0, -(-frame_axis // frame_step))
        elif frame_step is not None and frame_length is not None:
            assert not pad_end
            num_frames = max(0, (frame_axis - frame_length + frame_step) // frame_step)
    return outer_dimensions + [num_frames, frame_length] + inner_dimensions

@parameterized.parameters({'align_corners': False, 'half_pixel_centers': False, 'data_type': dtypes.float32}, {'align_corners': False, 'half_pixel_centers': False, 'data_type': dtypes.float64}, {'align_corners': True, 'half_pixel_centers': False, 'data_type': dtypes.float32}, {'align_corners': False, 'half_pixel_centers': True, 'data_type': dtypes.float32})
@test_util.run_in_graph_and_eager_modes
@test_util.run_gpu_only
def testDeterministicGradients(self, align_corners, half_pixel_centers, data_type):
    if not align_corners and test_util.is_xla_enabled():
        self.skipTest('align_corners==False not currently supported by XLA')
    with self.session(force_gpu=True):
        seed = hash(align_corners) % 256 + hash(half_pixel_centers) % 256 + hash(data_type) % 256
        np.random.seed(seed)
        input_shape = (1, 25, 12, 3)
        output_shape = (1, 200, 250, 3)
        input_image = self._randomDataOp(input_shape, data_type)
        repeat_count = 3
        if <MASK>:

            def resize_bilinear_gradients(local_seed):
                np.random.seed(local_seed)
                upstream_gradients = self._randomDataOp(output_shape, dtypes.float32)
                with backprop.GradientTape(persistent=True) as tape:
                    tape.watch(input_image)
                    output_image = image_ops.resize_bilinear(input_image, output_shape[1:3], align_corners=align_corners, half_pixel_centers=half_pixel_centers)
                    gradient_injector_output = output_image * upstream_gradients
                return tape.gradient(gradient_injector_output, input_image)
            for i in range(repeat_count):
                local_seed = seed + i
                result_a = resize_bilinear_gradients(local_seed)
                result_b = resize_bilinear_gradients(local_seed)
                self.assertAllEqual(result_a, result_b)
        else:
            upstream_gradients = array_ops.placeholder(dtypes.float32, shape=output_shape, name='upstream_gradients')
            output_image = image_ops.resize_bilinear(input_image, output_shape[1:3], align_corners=align_corners, half_pixel_centers=half_pixel_centers)
            gradient_injector_output = output_image * upstream_gradients
            resize_bilinear_gradients = gradients_impl.gradients(gradient_injector_output, input_image, grad_ys=None, colocate_gradients_with_ops=True)[0]
            for i in range(repeat_count):
                feed_dict = {upstream_gradients: self._randomNDArray(output_shape)}
                result_a = resize_bilinear_gradients.eval(feed_dict=feed_dict)
                result_b = resize_bilinear_gradients.eval(feed_dict=feed_dict)
                self.assertAllEqual(result_a, result_b)

def is_unaligned_buffer(arg: TensorArg):
    buf_name = arg.buffer
    if buf_name in V.graph.unaligned_buffers:
        return True
    if buf_name in V.graph.graph_inputs:
        return False
    if <MASK>:
        return False
    if V.graph.scheduler:
        layout = V.graph.scheduler.get_buffer_layout(buf_name)
    else:
        buffer = V.graph.try_get_buffer(buf_name)
        if not buffer:
            assert buf_name == V.kernel.output_node.name
            layout = V.kernel.output_node.layout
        else:
            layout = buffer.get_layout()
    if isinstance(layout, torch._inductor.ir.NonOwningLayout):
        return not layout.maybe_guard_aligned()
    else:
        return False

def _implementation():
    """Return a dict with the Python implementation and version.

    Provide both the name and the version of the Python implementation
    currently running. For example, on CPython 3.10.3 it will return
    {'name': 'CPython', 'version': '3.10.3'}.

    This function works best on CPython and PyPy: in particular, it probably
    doesn't work for Jython or IronPython. Future investigation should be done
    to work out the correct shape of the code for those platforms.
    """
    implementation = platform.python_implementation()
    if implementation == 'CPython':
        implementation_version = platform.python_version()
    elif implementation == 'PyPy':
        implementation_version = '{}.{}.{}'.format(sys.pypy_version_info.major, sys.pypy_version_info.minor, sys.pypy_version_info.micro)
        if <MASK>:
            implementation_version = ''.join([implementation_version, sys.pypy_version_info.releaselevel])
    elif implementation == 'Jython':
        implementation_version = platform.python_version()
    elif implementation == 'IronPython':
        implementation_version = platform.python_version()
    else:
        implementation_version = 'Unknown'
    return {'name': implementation, 'version': implementation_version}

def should_expand(a: ShapeType, b: ShapeType) -> bool:
    from torch.fx.experimental.symbolic_shapes import guard_or_false, sym_and, sym_or
    if len(a) != len(b):
        return True
    for (x, y) in zip(a, b):
        if guard_or_false(x != y):
            return True
        if <MASK>:
            pass
        elif guard_or_false(sym_or(x == 1, y == 1)):
            return True
        torch._check(x == y, lambda : 'sizes assumed to be the same due to unbacked broadcasting semantics')
    return False

def replace_expressions(self, replacements):
    if <MASK>:
        return self
    if (replacement := replacements.get(self)):
        return replacement
    if not (source_expressions := self.get_source_expressions()):
        return self
    clone = self.copy()
    clone.set_source_expressions([expr.replace_expressions(replacements) if expr else None for expr in source_expressions])
    return clone

def kleene_xor(left: bool | np.ndarray | libmissing.NAType, right: bool | np.ndarray | libmissing.NAType, left_mask: np.ndarray | None, right_mask: np.ndarray | None) -> tuple[npt.NDArray[np.bool_], npt.NDArray[np.bool_]]:
    """
    Boolean ``xor`` using Kleene logic.

    This is the same as ``or``, with the following adjustments

    * True, True -> False
    * True, NA   -> NA

    Parameters
    ----------
    left, right : ndarray, NA, or bool
        The values of the array.
    left_mask, right_mask : ndarray, optional
        The masks. Only one of these may be None, which implies that
        the associated `left` or `right` value is a scalar.

    Returns
    -------
    result, mask: ndarray[bool]
        The result of the logical xor, and the new mask.
    """
    if <MASK>:
        return kleene_xor(right, left, right_mask, left_mask)
    if not isinstance(left, np.ndarray):
        raise TypeError('Either `left` or `right` need to be a np.ndarray.')
    raise_for_nan(right, method='xor')
    if right is libmissing.NA:
        result = np.zeros_like(left)
    else:
        result = left ^ right
    if right_mask is None:
        if right is libmissing.NA:
            mask = np.ones_like(left_mask)
        else:
            mask = left_mask.copy()
    else:
        mask = left_mask | right_mask
    return (result, mask)

def triplet_margin_with_distance_loss(anchor: Tensor, positive: Tensor, negative: Tensor, *, distance_function: Optional[Callable[[Tensor, Tensor], Tensor]]=None, margin: float=1.0, swap: bool=False, reduction: str='mean') -> Tensor:
    """Compute the triplet margin loss for input tensors using a custom distance function.

    See :class:`~torch.nn.TripletMarginWithDistanceLoss` for details.
    """
    if torch.jit.is_scripting():
        raise NotImplementedError('F.triplet_margin_with_distance_loss does not support JIT scripting: functions requiring Callables cannot be scripted.')
    if has_torch_function_variadic(anchor, positive, negative):
        return handle_torch_function(triplet_margin_with_distance_loss, (anchor, positive, negative), anchor, positive, negative, distance_function=distance_function, margin=margin, swap=swap, reduction=reduction)
    if reduction not in ('mean', 'sum', 'none'):
        raise ValueError(f'{reduction} is not a valid value for reduction')
    if <MASK>:
        raise ValueError(f'margin must be greater than 0, got {margin}')
    a_dim = anchor.ndim
    p_dim = positive.ndim
    n_dim = negative.ndim
    if not (a_dim == p_dim and p_dim == n_dim):
        raise RuntimeError(f'The anchor, positive, and negative tensors are expected to have the same number of dimensions, but got: anchor {a_dim}D, positive {p_dim}D, and negative {n_dim}D inputs')
    if distance_function is None:
        distance_function = torch.pairwise_distance
    dist_pos = distance_function(anchor, positive)
    dist_neg = distance_function(anchor, negative)
    if swap:
        dist_swap = distance_function(positive, negative)
        dist_neg = torch.minimum(dist_neg, dist_swap)
    loss = torch.clamp_min(margin + dist_pos - dist_neg, 0)
    if reduction == 'sum':
        return torch.sum(loss)
    elif reduction == 'mean':
        return torch.mean(loss)
    else:
        return loss

@classmethod
def put(cls, filename: str, data: JsonDataTy) -> None:
    if <MASK>:
