        bundler.put(basename, data)

def get_higher_dtype(a: Optional[Union[torch.dtype, TensorLikeType, NumberType]], b: Optional[Union[torch.dtype, TensorLikeType, NumberType]]) -> Optional[torch.dtype]:
    """
    Computes the "lowest" datatype that is weakly
    "higher" than both a and b.
    """
    assert a is None or isinstance(a, (torch.dtype, TensorLike, Number))
    assert b is None or isinstance(b, (torch.dtype, TensorLike, Number))

    def _extract_dtype(x: Optional[Union[torch.dtype, TensorLikeType, NumberType]]) -> Optional[torch.dtype]:
        if x is None:
            return None
        if isinstance(x, torch.dtype):
            return x
        if isinstance(x, TensorLike):
            return x.dtype
        if isinstance(x, Number):
            return type_to_dtype(type(x))
        raise RuntimeError('Unexpected type given to _extract_dtype!')
    (a, b) = (_extract_dtype(a), _extract_dtype(b))
    if <MASK>:
        return a
    if a is None:
        return b
    if b is None:
        return a
    ordered_datatypes = ((torch.bool,), (torch.uint8, torch.int8), (torch.int16,), (torch.int32,), (torch.int64,), (torch.float16, torch.bfloat16), (torch.float32,), (torch.float64,), (torch.complex32,), (torch.complex64,), (torch.complex128,))
    for (idx, dtypes) in enumerate(ordered_datatypes):
        if a in dtypes and b in dtypes:
            return ordered_datatypes[idx + 1][0]
        if a in dtypes:
            return b
        if b in dtypes:
            return a
    raise RuntimeError('Unexpected termination!')

@_make_elementwise_binary_reference(type_promotion_kind=ELEMENTWISE_TYPE_PROMOTION_KIND.INT_TO_FLOAT, supports_lhs_python_scalar=False)
def copysign(a: Union[TensorLikeType, NumberType], b: Union[TensorLikeType, NumberType]):
    if isinstance(b, Number) and isinstance(a, Tensor):
        b = scalar_tensor(b, dtype=a.dtype, device=a.device)
    elif <MASK>:
        msg = f'Expected divisor (b) to be on the same device ({a.device}) as dividend (a), but it is found on {b.device}!'
        raise RuntimeError(msg)
    return where(signbit(b), neg(abs(a)), abs(a))

def _determine_input_dtype(param: _schemas.Parameter, arg: AllowedArgType, type_binding: Mapping[_schemas.TypeConstraintParam, ir.TypeProtocol]) -> ir.DataType:
    """Determine the dtype of the input that is a mix of Python constants and ir.Value."""
    if param.type_constraint in type_binding:
        return type_binding[param.type_constraint].dtype
    if len(param.type_constraint.allowed_types) == 1:
        return next(iter(param.type_constraint.allowed_types)).dtype
    if <MASK>:
        return ir.DataType.BOOL
    if isinstance(arg, float):
        return ir.DataType.FLOAT
    if isinstance(arg, int):
        return ir.DataType.INT64
    if isinstance(arg, str):
        return ir.DataType.STRING
    if isinstance(arg, (ir.Tensor, ir.TensorProtocol)):
        return arg.dtype
    if isinstance(arg, complex):
        return ir.DataType.FLOAT
    if arg is None:
        return ir.DataType.UNDEFINED
    if isinstance(arg, (tuple, list)):
        if len(arg) == 0:
            return ir.DataType.INT64
        for val in arg:
            if isinstance(val, ir.Value) and val.dtype is not None:
                return val.dtype
        if any((isinstance(val, float) for val in arg)):
            return ir.DataType.FLOAT
        elif any((isinstance(val, int) for val in arg)):
            return ir.DataType.INT64
    raise ValueError(f"Could not determine the dtype for the input '{param.name}'. param={param}, arg={arg}, param_type_constraint={param.type_constraint}, type_binding={type_binding}")

def decorator(arg):
    """Registers a class with the Keras serialization framework."""
    class_name = name if name is not None else arg.__name__
    registered_name = package + '>' + class_name
    if tf_inspect.isclass(arg) and (not hasattr(arg, 'get_config')):
        raise ValueError('Cannot register a class that does not have a get_config() method.')
    if <MASK>:
        raise ValueError('%s has already been registered to %s' % (registered_name, _GLOBAL_CUSTOM_OBJECTS[registered_name]))
    if arg in _GLOBAL_CUSTOM_NAMES:
        raise ValueError('%s has already been registered to %s' % (arg, _GLOBAL_CUSTOM_NAMES[arg]))
    _GLOBAL_CUSTOM_OBJECTS[registered_name] = arg
    _GLOBAL_CUSTOM_NAMES[arg] = registered_name
    return arg

def unstacked_input(self, index):
    (t, is_stacked, _) = self.input(index)
    if is_stacked:
        op_type = self.op_type
        op_def = getattr(self._op, 'op_def', None)
        if <MASK>:
            input_name = 'at index %d' % index
        else:
            input_name = '"%s"' % op_def.input_arg[index].name
        raise ConversionNotImplementedError(f"Input {input_name} of op '{op_type}' expected to be loop invariant.")
    return t

def _maybe_infer_fake(self, func: OpOverload, path: KeyPath, fake: object, real: object) -> tuple[Optional[object], bool]:
    """
        Helper to cross-check fake/real output properties & values,
        and create new fake vals if mismatched.
        Returns tuple of object & boolean, for whether or not it was overwrriten
        """
    import sympy
    from torch._subclasses.fake_utils import _check_fake_real_tensors

    def _check_fake_real_vals(fake: Any, real: Any) -> None:
        if isinstance(fake, (SymInt, SymFloat)):
            assert self.shape_env is not None
            if not fake.node.expr.free_symbols - self.shape_env.var_to_val.keys() - self.shape_env.unbacked_var_to_val.keys():
                if self.shape_env._maybe_evaluate_static(sympy.Eq(fake.node.expr, real), compute_hint=True) is not sympy.S.true:
                    raise MetadataMismatchError(f'mismatch between fake value {fake} and real value {real} ')
        elif <MASK>:
            if fake != real:
                raise MetadataMismatchError(f'mismatch between fake value {fake} and real value {real} ')
    if isinstance(fake, torch.Tensor):
        try:
            _check_fake_real_tensors(real, fake, context='Real tensor propagation found', sizes=False, strides=False, storage_offset=True, requires_grad=False)
        except MetadataMismatchError as exc:
            if torch._functorch.config.generate_fake_kernels_from_real_mismatches:
                dtrace_structured('mismatched_fake_kernel', metadata_fn=lambda : {'op': str(func), 'reason': exc.reason})
                return (_infer_fake_from_real_tensor(self, func, real), True)
            raise MetadataMismatchError(f'Real tensor propagation found a metadata mismatch between fake tensor {fake} and real tensor {real},  at output{keystr(path)}, for func: {func}') from exc
        for (j, (s_fake, s_real)) in enumerate(zip(fake.size(), real.size())):
            try:
                _check_fake_real_vals(s_fake, s_real)
            except MetadataMismatchError as exc:
                if torch._functorch.config.generate_fake_kernels_from_real_mismatches:
                    dtrace_structured('mismatched_fake_kernel', metadata_fn=lambda : {'op': str(func), 'reason': exc.reason})
                    return (_infer_fake_from_real_tensor(self, func, real), True)
                raise MetadataMismatchError(f'Real tensor propagation found an output size mismatch between fake shape {s_fake} and real shape {s_real}, at output{keystr(path)}.size({j}), for func: {func}') from exc
    elif fake is None and real is not None:
        if torch._functorch.config.generate_fake_kernels_from_real_mismatches:
            dtrace_structured('mismatched_fake_kernel', metadata_fn=lambda : {'op': str(func), 'reason': f'mismatch between fake value {fake} and real value {real}'})
            return (_infer_fake_from_real_tensor(self, func, real), True)
        raise MetadataMismatchError(f'Real tensor propagation found a metadata mismatch between fake tensor {fake} and real tensor {real},  at output{keystr(path)}, for func: {func}')
    else:
        try:
            _check_fake_real_vals(fake, real)
        except MetadataMismatchError as exc:
            raise MetadataMismatchError(f'Real tensor propagation found an output value mismatch between fake output value {fake} and real output value {real}, at output{keystr(path)}, for func: {func}') from exc
    return (fake, False)

def get_modules(pattern):
    """Given a node pattern, extract the corresponding modules
            e.g. input: (relu_node, (bn_node, conv_node))
                 output: (relu_module, (bn_module, conv_module))
            """
    if isinstance(pattern, (tuple, list)):
        (n, *args) = pattern
        modules: list[torch.nn.Module] = []
        modules.append(get_modules(n))
        modules.extend((get_modules(a) for a in args))
        return tuple(modules)
    else:
        n = pattern
        if <MASK>:
            return named_modules[n.target]
        elif n.op == 'call_function' and n.target == torch.nn.functional.relu:
            relu = torch.nn.ReLU()
            relu.training = root_module.training
            return relu
        elif n.op == 'call_function' or n.op == 'call_method':
            return n.target
        else:
            return MatchAllNode

def applyrules(rules, d, var={}):
    ret = {}
    if isinstance(rules, list):
        for r in rules:
            rr = applyrules(r, d, var)
            ret = dictappend(ret, rr)
            if '_break' in rr:
                break
        return ret
    if '_check' in rules and (not rules['_check'](var)):
        return ret
    if 'need' in rules:
        res = applyrules({'needs': rules['need']}, d, var)
        if 'needs' in res:
            cfuncs.append_needs(res['needs'])
    for k in rules.keys():
        if k == 'separatorsfor':
            ret[k] = rules[k]
            continue
        if isinstance(rules[k], str):
            ret[k] = replace(rules[k], d)
        elif isinstance(rules[k], list):
            ret[k] = []
            for i in rules[k]:
                ar = applyrules({k: i}, d, var)
                if k in ar:
                    ret[k].append(ar[k])
        elif k[0] == '_':
            continue
        elif isinstance(rules[k], dict):
            ret[k] = []
            for k1 in rules[k].keys():
                if isinstance(k1, types.FunctionType) and k1(var):
                    if isinstance(rules[k][k1], list):
                        for i in rules[k][k1]:
                            if <MASK>:
                                res = applyrules({'supertext': i}, d, var)
                                i = res.get('supertext', '')
                            ret[k].append(replace(i, d))
                    else:
                        i = rules[k][k1]
                        if isinstance(i, dict):
                            res = applyrules({'supertext': i}, d)
                            i = res.get('supertext', '')
                        ret[k].append(replace(i, d))
        else:
            errmess(f'applyrules: ignoring rule {repr(rules[k])}.\n')
        if isinstance(ret[k], list):
            if len(ret[k]) == 1:
                ret[k] = ret[k][0]
            if ret[k] == []:
                del ret[k]
    return ret

def apply_migration(self, state, migration, fake=False, fake_initial=False):
    """Run a migration forwards."""
    migration_recorded = False
    if self.progress_callback:
        self.progress_callback('apply_start', migration, fake)
    if not fake:
        if fake_initial:
            (applied, state) = self.detect_soft_applied(state, migration)
            if <MASK>:
                fake = True
        if not fake:
            with self.connection.schema_editor(atomic=migration.atomic) as schema_editor:
                state = migration.apply(state, schema_editor)
                if not schema_editor.deferred_sql:
                    self.record_migration(migration.app_label, migration.name)
                    migration_recorded = True
    if not migration_recorded:
        self.record_migration(migration.app_label, migration.name)
    if self.progress_callback:
        self.progress_callback('apply_success', migration, fake)
    return state

def get_inner_hook(idx: int) -> Callable[[torch.Tensor], None]:

    def inner_hook(grad: torch.Tensor) -> None:
        nonlocal count, nb_calls, buffer, fn
        id = torch._C._current_graph_task_id()
        if id == -1:
            raise AssertionError('expected this hook to be called inside a backward call')
        count[id] = count.get(id, 0)
        buffer[id] = buffer.get(id, [None] * len_tensors)
        with lock:
            (curr_count, count[id]) = (count[id], count[id] + 1)
            if curr_count == 0:
                nb_calls = sum(map(torch._C._will_engine_execute_node, grad_fns))
        buffer[id][idx] = grad
        if nb_calls is None:
            raise AssertionError('Expected nb_calls to be set')
        if <MASK>:
            fn = cast(Callable[[Sequence[Optional[torch.Tensor]]], None], fn)
            fn(buffer[id])
            del count[id]
            del buffer[id]
    return inner_hook

def get_nnc_type(dtype):
    if dtype == torch.float:
        return torch._C._te.Dtype.Float
    elif <MASK>:
        return torch._C._te.Dtype.Long

def _scalar_str(dtype, short):
    byteorder = _byte_order_str(dtype)
    if dtype.type == np.bool:
        if short:
            return "'?'"
        else:
            return "'bool'"
    elif dtype.type == np.object_:
        return "'O'"
    elif dtype.type == np.bytes_:
        if _isunsized(dtype):
            return "'S'"
        else:
            return "'S%d'" % dtype.itemsize
    elif dtype.type == np.str_:
        if _isunsized(dtype):
            return f"'{byteorder}U'"
        else:
            return "'%sU%d'" % (byteorder, dtype.itemsize / 4)
    elif dtype.type == str:
        return "'T'"
    elif not type(dtype)._legacy:
        return f"'{byteorder}{type(dtype).__name__}{dtype.itemsize * 8}'"
    elif issubclass(dtype.type, np.void):
        if _isunsized(dtype):
            return "'V'"
        else:
            return "'V%d'" % dtype.itemsize
    elif dtype.type == np.datetime64:
        return f"'{byteorder}M8{_datetime_metadata_str(dtype)}'"
    elif dtype.type == np.timedelta64:
        return f"'{byteorder}m8{_datetime_metadata_str(dtype)}'"
    elif dtype.isbuiltin == 2:
        return dtype.type.__name__
    elif np.issubdtype(dtype, np.number):
        if <MASK>:
            return "'%s%c%d'" % (byteorder, dtype.kind, dtype.itemsize)
        else:
            return "'%s%d'" % (_kind_name(dtype), 8 * dtype.itemsize)
    else:
        raise RuntimeError('Internal error: NumPy dtype unrecognized type number')

def _view_wrapper(request, *args, **kwargs):
    if <MASK>:
        test_pass = async_to_sync(test_func)(request.user)
    else:
        test_pass = test_func(request.user)
    if test_pass:
        return view_func(request, *args, **kwargs)
    return _redirect_to_login(request)

@classmethod
def eval(cls, p: sympy.Expr, q: sympy.Expr) -> Optional[sympy.Expr]:
    if q.is_zero:
        raise ZeroDivisionError('Modulo by zero')
    if p is S.Zero or p in (q, -q) or q == 1:
        return S.Zero
    if q.is_Number and p.is_Number:
        return p % q
    if q.is_Number and q == 2:
        if p.is_even:
            return S.Zero
        if <MASK>:
            return S.One
    r = p / q
    if r.is_integer:
        return S.Zero
    less = p < q
    if less.is_Boolean and bool(less) and r.is_positive:
        return p
    if sympy.Mod(p, q) == 0:
        return S.Zero
    return None

@combinations.generate(combinations.times(test_base.default_test_combinations(), combinations.combine(use_function=[False, True], use_legacy_map_and_batch=[False, True])))
def test_stateful_ops_map_and_batch(self, use_function, use_legacy_map_and_batch):
    with test_util.deterministic_ops():
        v = variables.Variable(0.0)

        def map_fn(x):
            v.assign_add(1.0)
            return (x, v.read_value())
        if use_function:
            map_fn = def_function.function(map_fn)
        dataset = dataset_ops.Dataset.range(5)
        if <MASK>:
            dataset = dataset.apply(batching.map_and_batch(map_fn, 2, num_parallel_calls=5))
        else:
            dataset = dataset.map(map_fn, num_parallel_calls=5)
            dataset = dataset.batch(2)
        self.evaluate(variables.global_variables_initializer())
        expected_output = [(np.array([0, 1]), np.array([1, 2])), (np.array([2, 3]), np.array([3, 4])), (np.array([4]), np.array([5]))]
        self.assertDatasetProduces(dataset, expected_output=expected_output, requires_initialization=True)

@functools.lru_cache
def is_from_defaults(source: Source) -> bool:
    if isinstance(source, DefaultsSource):
        return True
    if <MASK>:
        return True
    if isinstance(source, GetItemSource) and isinstance(source.base, AttrSource) and (source.base.member == '__defaults__'):
        return True
    if isinstance(source, ChainedSource):
        return is_from_defaults(source.base)
    return False

def _check_conv_and_broadcast_op(conv_node, other):
    if conv_node.args[1].op != 'get_attr':
        return False
    if conv_node.args[1] is not None and conv_node.args[1].op != 'get_attr':
        return False
    if not isinstance(other, int) and (not isinstance(other, float)) and (other.op != 'get_attr'):
        return False
    if len(conv_node.args[1].users) != 1:
        return False
    weight_meta_value = conv_node.args[1].meta.get('val')
    if weight_meta_value is None:
        return False
    if <MASK>:
        return False
    if isinstance(other, torch.fx.Node) and other.op == 'get_attr':
        other_meta_value = other.meta.get('val')
        if not other_meta_value.is_floating_point():
            return False
        if torch.promote_types(other_meta_value.dtype, weight_meta_value.dtype) != weight_meta_value.dtype:
            if not conv_node.meta.get('_allow_mixed_dtype_folding', False):
                return False
            if other_meta_value.dtype != torch.float and weight_meta_value.dtype not in (torch.float16, torch.bfloat16):
                return False
        if not _op_not_broadcasting_with_conv(weight_meta_value, other_meta_value):
            return False
    elif not isinstance(other, float):
        return False
    return True

