    else:
        returns = '(' + ', '.join(map(str, self.returns)) + ')'
    return f'{self.name}({all_arguments_str}) -> {returns}'

@no_type_check
def _init_process_group_state(state: _FSDPState, process_group: ProcessGroupType, sharding_strategy: ShardingStrategy, policy: Optional[_Policy], device_mesh: Optional[DeviceMesh]=None) -> _FSDPState:
    if process_group is not None and device_mesh is not None:
        raise ValueError('Cannot pass both process_group and device_mesh at the same time. Please just pass only one of them.')
    is_hybrid_strategy = sharding_strategy in HYBRID_SHARDING_STRATEGIES
    if <MASK>:
        if process_group is None and policy is None and (device_mesh is None):
            raise ValueError(f'Manual wrapping with {sharding_strategy} requires explicit specification of process group or device_mesh.')
        else:
            state = _init_process_group_state_for_hybrid_shard(state, process_group, device_mesh)
    elif device_mesh:
        state._device_mesh = device_mesh
        state.process_group = device_mesh.get_group(mesh_dim=0)
    else:
        state.process_group = process_group if process_group is not None else _get_default_group()
    state.rank = state.process_group.rank()
    state.world_size = state.process_group.size()
    data_parallel_world_size = state.world_size
    if is_hybrid_strategy:
        data_parallel_world_size *= state._inter_node_pg.size()
    state._gradient_predivide_factor = default_hooks.DefaultState._get_gradient_predivide_factor(data_parallel_world_size)
    state._gradient_postdivide_factor = data_parallel_world_size / state._gradient_predivide_factor
    return state

def sig_for_ops(opname: str) -> list[str]:
    """sig_for_ops(opname : str) -> list[str]

    Returns signatures for operator special functions (__add__ etc.)"""
    assert opname.endswith('__') and opname.startswith('__'), f'Unexpected op {opname}'
    name = opname[2:-2]
    if name == 'rpow':
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # type: ignore[has-type]']
    elif name in arithmetic_ops:
        if name.startswith('i'):
            return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # noqa: PYI034']
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...']
    elif name in logic_ops:
        return [f'def {opname}(self, other: Tensor | _int) -> Tensor: ...']
    elif <MASK>:
        return [f'def {opname}(self, other: Tensor | _int) -> Tensor: ...']
    elif name in symmetric_comparison_ops:
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...  # type: ignore[overload-overlap]', f'def {opname}(self, other: object) -> _bool: ...']
    elif name in asymmetric_comparison_ops:
        return [f'def {opname}(self, other: Tensor | Number | _complex) -> Tensor: ...']
    elif name in unary_ops:
        return [f'def {opname}(self) -> Tensor: ...']
    if name in to_py_type_ops:
        if name in {'bool', 'float', 'complex'}:
            tname = name
        elif name == 'nonzero':
            tname = 'bool'
        else:
            tname = 'int'
        if tname in {'float', 'int', 'bool', 'complex'}:
            tname = '_' + tname
        return [f'def {opname}(self) -> {tname}: ...']
    raise ValueError(f'unknown op {opname!r}')

def __init__(self, input_shape=None, batch_size=None, dtype=None, input_tensor=None, sparse=None, name=None, ragged=None, type_spec=None, **kwargs):
    self._init_input_shape = input_shape
    self._init_batch_size = batch_size
    self._init_dtype = dtype
    self._init_sparse = sparse
    self._init_ragged = ragged
    self._init_type_spec = type_spec
    strategy = distribute_lib.get_strategy()
    if strategy and batch_size is not None and distributed_training_utils.global_batch_size_supported(strategy):
        if batch_size % strategy.num_replicas_in_sync != 0:
            raise ValueError('The `batch_size` argument ({}) must be divisible by the number of replicas ({})'.format(batch_size, strategy.num_replicas_in_sync))
        batch_size = batch_size // strategy.num_replicas_in_sync
    if <MASK>:
        batch_input_shape = kwargs.pop('batch_input_shape')
        if input_shape and batch_input_shape:
            raise ValueError('Only provide the input_shape OR batch_input_shape argument to InputLayer, not both at the same time.')
        if batch_input_shape:
            batch_size = batch_input_shape[0]
            input_shape = batch_input_shape[1:]
    if kwargs:
        raise ValueError('Unrecognized keyword arguments:', kwargs.keys())
    if sparse and ragged:
        raise ValueError('Cannot set both sparse and ragged to True in a Keras input.')
    if not name:
        prefix = 'input'
        name = prefix + '_' + str(backend.get_uid(prefix))
    if not dtype:
        if input_tensor is None:
            dtype = backend.floatx()
        else:
            dtype = backend.dtype(input_tensor)
    elif input_tensor is not None and input_tensor.dtype != dtype:
        raise ValueError('`input_tensor.dtype` differs from `dtype`: %s vs. %s' % (input_tensor.dtype, dtype))
    super(InputLayer, self).__init__(dtype=dtype, name=name)
    self.built = True
    self.sparse = True if sparse else False
    self.ragged = True if ragged else False
    self.batch_size = batch_size
    self.supports_masking = True
    if isinstance(input_shape, tensor_shape.TensorShape):
        input_shape = tuple(input_shape.as_list())
    elif isinstance(input_shape, int):
        input_shape = (input_shape,)
    if type_spec is not None:
        args_that_must_be_none = [('(input_)shape', self._init_input_shape), ('batch_size', self._init_batch_size), ('dtype', self._init_dtype), ('input_tensor', input_tensor), ('sparse', self._init_sparse), ('ragged', self._init_ragged)]
        for (arg_name, arg) in args_that_must_be_none:
            _assert_other_arg_none(arg_name, arg)
        if not ops.executing_eagerly_outside_functions():
            raise ValueError('Creating Keras inputs from a type_spec is only supported when eager execution is enabled.')
        input_tensor = keras_tensor.keras_tensor_from_type_spec(type_spec)
        if isinstance(input_tensor, keras_tensor.SparseKerasTensor):
            self.sparse = True
        if isinstance(input_tensor, keras_tensor.RaggedKerasTensor):
            self.ragged = True
        self.is_placeholder = True
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    elif input_tensor is None:
        if input_shape is not None:
            batch_input_shape = (batch_size,) + tuple(input_shape)
        else:
            batch_input_shape = None
        graph = backend.get_graph()
        with graph.as_default():
            input_tensor = backend.placeholder(shape=batch_input_shape, dtype=dtype, name=self.name, sparse=sparse, ragged=ragged)
        self.is_placeholder = True
        self._batch_input_shape = batch_input_shape
    else:
        if ops.executing_eagerly_outside_functions():
            if not isinstance(input_tensor, keras_tensor.KerasTensor):
                input_tensor = keras_tensor.keras_tensor_from_tensor(input_tensor)
        elif not tf_utils.is_symbolic_tensor(input_tensor):
            raise ValueError('You should not pass an EagerTensor to `Input`. For example, instead of creating an InputLayer, you should instantiate your model and directly call it on your input.')
        self.is_placeholder = False
        try:
            self._batch_input_shape = tuple(input_tensor.shape.as_list())
        except ValueError:
            self._batch_input_shape = None
    input_tensor._keras_mask = None
    node_module.Node(layer=self, outputs=input_tensor)
    if isinstance(input_tensor, keras_tensor.KerasTensor) or tf_utils.is_extension_type(input_tensor):
        self._type_spec = input_tensor._type_spec
    else:
        self._type_spec = tensor_spec.TensorSpec(shape=input_tensor.shape, dtype=input_tensor.dtype, name=self.name)

def attach(self, filename=None, content=None, mimetype=None):
    """
        Attach a file with the given filename and content. The filename can
        be omitted and the mimetype is guessed, if not provided.

        If the first parameter is a MIMEBase subclass, insert it directly
        into the resulting message attachments.

        For a text/* mimetype (guessed or specified), when a bytes object is
        specified as content, decode it as UTF-8. If that fails, set the
        mimetype to DEFAULT_ATTACHMENT_MIME_TYPE and don't decode the content.
        """
    if isinstance(filename, email.message.MIMEPart):
        if <MASK>:
            raise ValueError('content and mimetype must not be given when a MIMEPart instance is provided.')
        self.attachments.append(filename)
    elif isinstance(filename, MIMEBase):
        warnings.warn('MIMEBase attachments are deprecated. Use an email.message.MIMEPart instead.', RemovedInDjango70Warning)
        if content is not None or mimetype is not None:
            raise ValueError('content and mimetype must not be given when a MIMEBase instance is provided.')
        self.attachments.append(filename)
    elif content is None:
        raise ValueError('content must be provided.')
    else:
        mimetype = mimetype or mimetypes.guess_type(filename)[0] or DEFAULT_ATTACHMENT_MIME_TYPE
        (basetype, subtype) = mimetype.split('/', 1)
        if basetype == 'text':
            if isinstance(content, bytes):
                try:
                    content = content.decode()
                except UnicodeDecodeError:
                    mimetype = DEFAULT_ATTACHMENT_MIME_TYPE
        self.attachments.append(EmailAttachment(filename, content, mimetype))

def _check_sated(self, raise_error):
    """Check if the object has been sated."""
    if self._sated:
        return
    creation_stack = ''.join([line.rstrip() for line in traceback.format_stack(self._stack_frame, limit=5)])
    if <MASK>:
        try:
            raise RuntimeError('Object was never used (type {}): {}.  If you want to mark it as used call its "mark_used()" method.  It was originally created here:\n{}'.format(self._type, self._repr, creation_stack))
        finally:
            self.sate()
    else:
        tf_logging.error('==================================\nObject was never used (type {}):\n{}\nIf you want to mark it as used call its "mark_used()" method.\nIt was originally created here:\n{}\n=================================='.format(self._type, self._repr, creation_stack))

def match(self, other: 'Op') -> MatchInfo:
    if self.type == 'send':
        return MatchInfo(MatchState.FULLY_MATCHED) if other.type == 'recv' and self.src == other.src and (self.dst == other.dst) and (self.input_sizes == other.output_sizes) else MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH)
    elif self.type == 'recv':
        return MatchInfo(MatchState.FULLY_MATCHED) if other.type == 'send' and self.src == other.src and (self.dst == other.dst) and (self.output_sizes == other.input_sizes) else MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH)
    elif self.type in COLLECTIVES:
        if self.type != other.type:
            return MatchInfo(MatchState.COLLECTIVE_TYPE_MISMATCH, f"Expected collective type: '{self.type}' does not match found collective type: '{other.type}'")
        if self.type not in ['all_to_all', 'scatter'] and self.input_sizes != other.input_sizes:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Expected input sizes: '{self.input_sizes}' does not match found input sizes: '{other.input_sizes}'")
        if self.type not in ['all_to_all', 'gather'] and self.output_sizes != other.output_sizes:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Expected output sizes: '{self.output_sizes}' does not match found output sizes: '{other.output_sizes}'")
        if <MASK>:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Expected input sizes: '{self.input_sizes}' does not match found output sizes: '{other.output_sizes}'")
        if self.type in ['all_gather', 'all_gather_base', 'all_gather_into_tensor_coalesced'] and math.prod(other.output_sizes[0]) != math.prod(self.input_sizes[0]) * self.pg_size:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Found input numel '{math.prod(other.input_sizes[0])} * pg size {self.pg_size}' does not match output numel '{math.prod(other.output_sizes[0])}'")
        if self.type in ['reduce_scatter', '_reduce_scatter_base', 'reduce_scatter_tensor_coalesced'] and math.prod(other.input_sizes[0]) != math.prod(self.output_sizes[0]) * self.pg_size:
            return MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH, f"Found input numel '{math.prod(other.input_sizes[0])}' does not match output numel '{math.prod(other.output_sizes[0])} * pg size {self.pg_size}'")
        if self.dtype_mismatch(other):
            return MatchInfo(MatchState.COLLECTIVE_DTYPE_MISMATCH, f"Expected dtypes: '{set(self.input_dtypes)}' does not match found dtype: '{set(self.output_dtypes)}/{set(other.input_dtypes)}/{set(other.output_dtypes)}'")
        if self.state != other.state:
            return MatchInfo(MatchState.COLLECTIVE_STATE_MISMATCH, f"Expected state: '{self.state}' does not match found state: '{other.state}'")
        if self.type == 'all_to_all':
            return MatchInfo(MatchState.UNDECIDED)
    elif self.type in ['coalesced', 'ALLGATHER_coalesced', 'REDUCE_SCATTER_coalesced']:
        return MatchInfo(MatchState.FULLY_MATCHED) if other.type == self.type else MatchInfo(MatchState.SIZE_OR_SYNTAX_MISMATCH)
    return MatchInfo(MatchState.FULLY_MATCHED)

def get_next_element_by_instance(self, instance_id: int):
    if self._datapipe_iterator is None and self._child_stop[instance_id]:
        self._datapipe_iterator = iter(self.main_datapipe)
        self._snapshot_state = _SnapshotState.Iterating
        self.main_datapipe_exhausted = False
        for i in range(self.num_instances):
            self._child_stop[i] = False
    try:
        while not self._child_stop[instance_id]:
            if self.child_buffers[instance_id]:
                self.current_buffer_usage -= 1
                yield self.child_buffers[instance_id].popleft()
            else:
                try:
                    yield self._find_next(instance_id)
                except StopIteration:
                    self._child_stop[instance_id] = True
                    self.main_datapipe_exhausted = True
                    self._datapipe_iterator = None
    finally:
        self._child_stop[instance_id] = True
        if <MASK>:
            self._datapipe_iterator = None
        if self.child_buffers[instance_id]:
            self._cleanup(instance_id)

def visit(self, node: ast.AST) -> Any:
    if isinstance(node, PyExprCSEPass.ALLOWED_NODE_TYPES):
        expr = _ast_unparse(node)
        if <MASK>:
            if expr not in self._config.expr_to_name:
                node_ = super().visit(node)
                expr_ = _ast_unparse(node_)
                var_name = self._gen_name()
                self.preface.append(f'{var_name} = {expr_}')
                self._config.expr_to_name[expr] = var_name
            else:
                var_name = self._config.expr_to_name[expr]
            return ast.Name(var_name, ast.Load())
    return super().visit(node)

def serialize(to_serialize: Serializable) -> SerializedTraceType:
    """Converts Serializable to a proto SerializedTraceType."""
    if <MASK>:
        raise ValueError('Can not serialize ' + type(to_serialize).__name__ + ' since it is not Serializable. For object ' + str(to_serialize))
    actual_proto = to_serialize.experimental_as_proto()
    if not isinstance(actual_proto, to_serialize.experimental_type_proto()):
        raise ValueError(type(to_serialize).__name__ + ' returned different type of proto than specified by ' + 'experimental_type_proto()')
    serialized = SerializedTraceType()
    serialized.representation.Pack(actual_proto)
    return serialized

def __init__(self, srs_input='', srs_type='user', axis_order=None):
    """
        Create a GDAL OSR Spatial Reference object from the given input.
        The input may be string of OGC Well Known Text (WKT), an integer
        EPSG code, a PROJ string, and/or a projection "well known" shorthand
        string (one of 'WGS84', 'WGS72', 'NAD27', 'NAD83').
        """
    if not isinstance(axis_order, (NoneType, AxisOrder)):
        raise ValueError('SpatialReference.axis_order must be an AxisOrder instance.')
    self.axis_order = axis_order or AxisOrder.TRADITIONAL
    if srs_type == 'wkt':
        self.ptr = capi.new_srs(c_char_p(b''))
        self.import_wkt(srs_input)
        if <MASK>:
            capi.set_axis_strategy(self.ptr, self.axis_order)
        return
    elif isinstance(srs_input, str):
        try:
            srid = int(srs_input)
            srs_input = 'EPSG:%d' % srid
        except ValueError:
            pass
    elif isinstance(srs_input, int):
        srs_type = 'epsg'
    elif isinstance(srs_input, self.ptr_type):
        srs = srs_input
        srs_type = 'ogr'
    else:
        raise TypeError('Invalid SRS type "%s"' % srs_type)
    if srs_type == 'ogr':
        srs = srs_input
    else:
        buf = c_char_p(b'')
        srs = capi.new_srs(buf)
    if not srs:
        raise SRSException('Could not create spatial reference from: %s' % srs_input)
    else:
        self.ptr = srs
    if self.axis_order == AxisOrder.TRADITIONAL:
        capi.set_axis_strategy(self.ptr, self.axis_order)
    if srs_type == 'user':
        self.import_user_input(srs_input)
    elif srs_type == 'epsg':
        self.import_epsg(srs_input)

def _ComputeReferenceDilatedConv(self, tensor_in_sizes, filter_in_sizes, stride, dilation, padding, data_format, use_gpu, op_name):
    total_size_tensor = np.prod(tensor_in_sizes)
    total_size_filter = np.prod(filter_in_sizes)
    x1 = [f * 1.0 for f in range(1, total_size_tensor + 1)]
    x2 = [f * 1.0 for f in range(1, total_size_filter + 1)]
    with self.cached_session(use_gpu=use_gpu):
        t1 = constant_op.constant(x1, shape=tensor_in_sizes)
        t2 = constant_op.constant(x2, shape=filter_in_sizes)
        if isinstance(stride, collections_abc.Iterable):
            strides = list(stride)
        else:
            strides = [stride, stride, stride]
        if data_format == 'NCDHW':
            t1 = test_util.NHWCToNCHW(t1)
            full_strides = [1, 1] + strides
            full_dilation = [1, 1] + dilation
        else:
            full_strides = [1] + strides + [1]
            full_dilation = [1] + dilation + [1]
        expected = nn_ops.convolution(t1, t2, padding=padding, strides=strides, dilation_rate=dilation, data_format=data_format)
        if <MASK>:
            op = nn_ops.conv3d
            conv_format = data_format
        elif op_name == 'Conv':
            op = gen_nn_ops.conv
            conv_format = 'CHANNELS_LAST' if data_format == 'NDHWC' else 'CHANNELS_FIRST'
        else:
            raise ValueError('Invalid op name: %s' % op_name)
        computed = op(t1, t2, strides=full_strides, dilations=full_dilation, padding=padding, data_format=conv_format)
        if data_format == 'NCDHW':
            expected = test_util.NCHWToNHWC(expected)
            computed = test_util.NCHWToNHWC(computed)
    return (expected, computed)

@_onnx_symbolic('aten::norm')
@symbolic_helper.parse_args('v', 't', 'is', 'i', 'v')
def norm(g: jit_utils.GraphContext, self, p, dim, keepdim, dtype=None):
    if p == 1:
        f = symbolic_helper._reduce_op_symbolic_helper('ReduceL1')
    elif <MASK>:
        f = symbolic_helper._reduce_op_symbolic_helper('ReduceL2')
    else:
        raise errors.SymbolicValueError('ONNX export only p-norms with p of 1 or 2', self)
    result = f(g, self, dim=dim, keepdim=keepdim)
    if dtype is not None:
        dtype = symbolic_helper._get_const(dtype, 'i', 'dtype')
        result = g.op('Cast', result, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    return result

