def _broadcast_shape_helper(shape_x, shape_y):
    """Helper functions for is_broadcast_compatible and broadcast_shape.

  Args:
    shape_x: A `TensorShape`
    shape_y: A `TensorShape`

  Returns:
    Returns None if the shapes are not broadcast compatible,
    a list of the broadcast dimensions otherwise.
  """
    broadcasted_dims = reversed(list(itertools.zip_longest(reversed(shape_x.dims), reversed(shape_y.dims), fillvalue=tensor_shape.Dimension(1))))
    return_dims = []
    for (dim_x, dim_y) in broadcasted_dims:
        if dim_x.value is None or dim_y.value is None:
            if dim_x.value is not None and dim_x.value > 1:
                return_dims.append(dim_x)
            elif <MASK>:
                return_dims.append(dim_y)
            else:
                return_dims.append(None)
        elif dim_x.value == 1:
            return_dims.append(dim_y)
        elif dim_y.value == 1:
            return_dims.append(dim_x)
        elif dim_x.value == dim_y.value:
            return_dims.append(dim_x.merge_with(dim_y))
        else:
            return None
    return return_dims

def _minmax(self, meth: Literal['min', 'max']) -> int | float:
    no_steps = len(self) - 1
    if no_steps == -1:
        return np.nan
    elif <MASK>:
        return self.start
    return self.start + self.step * no_steps

def prepare_alias_info_for_tensor_construction(self, out_alias_info: Optional[OutputAliasInfo], metadata: Union[dict[str, Any], int, None]) -> Union[UntypedStorage, None, int]:
    if <MASK>:
        return None
    if isinstance(out_alias_info, AliasesPriorGraphOutput):
        (depth, existing_output_index) = out_alias_info.index
        ref = self.path_weakrefs[depth][existing_output_index]
        assert ref is not None
        return torch.UntypedStorage._new_with_weak_ptr(ref())
    assert isinstance(out_alias_info, AliasesNewOutput)
    return out_alias_info.index

def alter_field(self, app_label, model_name, name, field, preserve_default):
    if not preserve_default:
        field = field.clone()
        field.default = NOT_PROVIDED
    else:
        field = field
    model_key = (app_label, model_name)
    fields = self.models[model_key].fields
    if self._relations is not None:
        old_field = fields.pop(name)
        if old_field.is_relation:
            self.resolve_model_field_relations(model_key, name, old_field)
        fields[name] = field
        if <MASK>:
            self.resolve_model_field_relations(model_key, name, field)
    else:
        fields[name] = field
    delay = not field.is_relation and (not field_is_referenced(self, model_key, (name, field)))
    self.reload_model(*model_key, delay=delay)

def getcallprotoargument(rout, cb_map={}):
    r = getmultilineblock(rout, 'callprotoargument', comment=0)
    if r:
        return r
    if hascallstatement(rout):
        outmess('warning: callstatement is defined without callprotoargument\n')
        return
    from .capi_maps import getctype
    (arg_types, arg_types2) = ([], [])
    if l_and(isstringfunction, l_not(isfunction_wrap))(rout):
        arg_types.extend(['char*', 'size_t'])
    for n in rout['args']:
        var = rout['vars'][n]
        if isintent_callback(var):
            continue
        if n in cb_map:
            ctype = cb_map[n] + '_typedef'
        else:
            ctype = getctype(var)
            if l_and(isintent_c, l_or(isscalar, iscomplex))(var):
                pass
            elif isstring(var):
                pass
            elif not isattr_value(var):
                ctype = ctype + '*'
            if <MASK>:
                arg_types2.append('size_t')
        arg_types.append(ctype)
    proto_args = ','.join(arg_types + arg_types2)
    if not proto_args:
        proto_args = 'void'
    return proto_args

def _add_batched_ragged_partition(rt, partition, tensor_dict, feature_key, validate, outer_splits=None):
    """Adds a batched ragged partition tensor to a batched ragged tensor.

  Args:
    rt: A RaggedTensor with shape [batch_size, ...].
    partition: The partition configuration object.  Specifies the key that
      should be used to look up the partition tensor (unless partition is a
      RaggedFeature.UniformRowLength, in which case there is no partition
      tensor).  The specified tensor must have shape [batch_size, ...].
    tensor_dict: The dictionary mapping keys to tensors.
    feature_key: The name of the feature being parsed (for error messages).
    validate: Whether to validate that the values form a valid RaggedTensor.
    outer_splits: If not None, then we have two batch dimensions, and this
      is the row-splits for the collapsed batch dimension.  Every partition
      tensor must have an outer row_splits that matches this value.

  Returns:
    A new RaggedTensor where each batch item `rt[i]` has been partitioned
    using the `partition_t[i]`.
  """
    if isinstance(partition, RaggedFeature.UniformRowLength):
        if rt.ragged_rank > 1:
            length = ops.convert_to_tensor(partition.length, rt.row_splits.dtype)
            return ragged_tensor.RaggedTensor.from_row_splits(ragged_tensor.RaggedTensor.from_uniform_row_length(rt.values, length, validate=validate), rt.row_splits // length, validate=validate)
        else:
            reshaped_vals = array_ops.reshape(rt.values, array_ops.concat([[-1, partition.length], array_ops.shape(rt.values)[1:]], axis=0))
            return ragged_tensor.RaggedTensor.from_row_splits(reshaped_vals, rt.row_splits // partition.length, validate=validate)
    partition_t = tensor_dict[partition.key]
    if <MASK>:
        partition_t = math_ops.cast(partition_t, rt.row_splits.dtype)
    checks = []
    if outer_splits is not None:
        if validate:
            checks.append(check_ops.assert_equal(outer_splits, partition_t.row_splits, message='Feature %s: values and partitions are not aligned' % feature_key))
        partition_t = partition_t.values
    with ops.control_dependencies(checks):
        if isinstance(partition, (RaggedFeature.RowSplits, RaggedFeature.RowLimits)):
            if isinstance(partition, RaggedFeature.RowSplits):
                partition_t = partition_t[:, 1:]
            adjusted_limits = partition_t.values + array_ops.repeat(rt.row_starts(), partition_t.row_lengths())
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_limits(rt.values, adjusted_limits, validate=validate))
        elif isinstance(partition, RaggedFeature.RowStarts):
            adjusted_starts = partition_t.values + array_ops.repeat(rt.row_starts(), partition_t.row_lengths())
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_starts(rt.values, adjusted_starts, validate=validate))
        elif isinstance(partition, RaggedFeature.RowLengths):
            return partition_t.with_values(ragged_tensor.RaggedTensor.from_row_lengths(rt.values, partition_t.values, validate=validate))
        elif isinstance(partition, RaggedFeature.ValueRowIds):
            nrows = math_ops.maximum(ragged_math_ops.reduce_max(partition_t + 1, axis=1), 0)
            adjusted_rowids = partition_t.values + array_ops.repeat(math_ops.cumsum(nrows, exclusive=True), partition_t.row_lengths())
            return ragged_tensor.RaggedTensor.from_row_lengths(ragged_tensor.RaggedTensor.from_value_rowids(rt.values, adjusted_rowids, validate=validate), nrows, validate=validate)
        raise ValueError(f'Unhandled partition type {partition!r}')

def make_gradient_clipnorm_fn(clipnorm):
    """Creates a gradient transformation function for clipping by norm."""
    if <MASK>:
        return lambda grads_and_vars: grads_and_vars

    def gradient_clipnorm_fn(grads_and_vars):
        if isinstance(distribute_lib.get_strategy(), (central_storage_strategy.CentralStorageStrategy, central_storage_strategy.CentralStorageStrategyV1)):
            raise ValueError('`clipnorm` is not supported with `CenteralStorageStrategy`')
        clipped_grads_and_vars = [(clip_ops.clip_by_norm(g, clipnorm), v) for (g, v) in grads_and_vars]
        return clipped_grads_and_vars
    return gradient_clipnorm_fn

@final
def _maybe_mask_setitem_value(self, indexer, value):
    """
        If we have obj.iloc[mask] = series_or_frame and series_or_frame has the
        same length as obj, we treat this as obj.iloc[mask] = series_or_frame[mask],
        similar to Series.__setitem__.

        Note this is only for loc, not iloc.
        """
    if isinstance(indexer, tuple) and len(indexer) == 2 and isinstance(value, (ABCSeries, ABCDataFrame)):
        (pi, icols) = indexer
        ndim = value.ndim
        if com.is_bool_indexer(pi) and len(value) == len(pi):
            newkey = pi.nonzero()[0]
            if <MASK>:
                if len(newkey) == 0:
                    value = value.iloc[:0]
                else:
                    value = self.obj.iloc._align_series(indexer, value)
                indexer = (newkey, icols)
            elif isinstance(icols, np.ndarray) and icols.dtype.kind == 'i' and (len(icols) == 1):
                if ndim == 1:
                    value = self.obj.iloc._align_series(indexer, value)
                    indexer = (newkey, icols)
                elif ndim == 2 and value.shape[1] == 1:
                    if len(newkey) == 0:
                        value = value.iloc[:0]
                    else:
                        value = self.obj.iloc._align_frame(indexer, value)
                    indexer = (newkey, icols)
    elif com.is_bool_indexer(indexer):
        indexer = indexer.nonzero()[0]
    return (indexer, value)

def serialize_tensor(e):
    if <MASK>:
        return FuncCallWrapper('T', list(e.shape), e.dtype, stride=e.stride())
    else:
        return FuncCallWrapper('T', list(e.shape), e.dtype)

def to_fullargspec(function_type: function_type_lib.FunctionType, default_values: Dict[str, Any]) -> inspect.FullArgSpec:
    """Generates backwards compatible FullArgSpec from FunctionType."""
    args = []
    varargs = None
    varkw = None
    defaults = []
    kwonlyargs = []
    kwonlydefaults = {}
    for parameter in function_type.parameters.values():
        if <MASK>:
            args.append(parameter.name)
            if parameter.default is not inspect.Parameter.empty:
                defaults.append(default_values[parameter.name])
        elif parameter.kind is inspect.Parameter.KEYWORD_ONLY:
            kwonlyargs.append(parameter.name)
            if parameter.default is not inspect.Parameter.empty:
                kwonlydefaults[parameter.name] = default_values[parameter.name]
        elif parameter.kind is inspect.Parameter.VAR_POSITIONAL:
            varargs = parameter.name
        elif parameter.kind is inspect.Parameter.VAR_KEYWORD:
            varkw = parameter.name
    return inspect.FullArgSpec(args, varargs, varkw, tuple(defaults) if defaults else None, kwonlyargs, kwonlydefaults if kwonlydefaults else None, annotations={})

def _add_dispatch_for_unary_elementwise_api(api, x_type, elementwise_api_handler):
    """Registers a unary elementwise handler as a dispatcher for a given API."""
    api_signature = tf_inspect.signature(api)
    x_name = list(api_signature.parameters)[0]
    name_index = _find_name_index(api_signature)
    need_to_bind_api_args = len(api_signature.parameters) > 2 or 'name' not in api_signature.parameters

    @dispatch_for_api(api, {x_name: x_type})
    def dispatch_target(*args, **kwargs):
        (args, kwargs, name) = _extract_name_arg(args, kwargs, name_index)
        if args:
            (x, args) = (args[0], args[1:])
        else:
            x = kwargs.pop(x_name)
        if need_to_bind_api_args:
            tensor_api = lambda v: api(v, *args, **kwargs)
        else:
            tensor_api = api
        if <MASK>:
            return elementwise_api_handler(tensor_api, x)
        else:
            with ops.name_scope(name, None, [x]):
                return elementwise_api_handler(tensor_api, x)
    dispatch_target.__name__ = 'elementwise_dispatch_target_for_' + api.__name__
    dispatch_target.__qualname__ = dispatch_target.__name__
    target_list = _ELEMENTWISE_API_TARGETS.setdefault((x_type,), [])
    target_list.append((api, dispatch_target))

def _test(self, kwargs, expected_values=None, expected_err=None):
    with self.cached_session() as sess:
        if expected_err:
            with self.assertRaisesWithPredicateMatch(expected_err[0], expected_err[1]):
                out = parsing_ops.parse_single_example(**kwargs)
                sess.run(flatten_values_tensors_or_sparse(out.values()))
            return
        else:
            out = parsing_ops.parse_single_example(**kwargs)
            tf_result = sess.run(flatten_values_tensors_or_sparse(out.values()))
            _compare_output_to_expected(self, out, expected_values, tf_result)
        for (k, f) in kwargs['features'].items():
            if <MASK>:
                self.assertEqual(tuple(out[k].get_shape()), tensor_shape.as_shape(f.shape))
            elif isinstance(f, parsing_ops.VarLenFeature):
                self.assertEqual(tuple(out[k].indices.get_shape().as_list()), (None, 1))
                self.assertEqual(tuple(out[k].values.get_shape().as_list()), (None,))
                self.assertEqual(tuple(out[k].dense_shape.get_shape().as_list()), (1,))

def _add_file(filename: str) -> None:
    try:
        with tokenize.open(filename) as f:
            tokens = list(tokenize.generate_tokens(f.readline))
    except (OSError, tokenize.TokenError):
        cache[filename] = {}
        return
    result: dict[int, str] = {}
    cur_name = ''
    cur_indent = 0
    significant_indents: list[int] = []
    for (i, token) in enumerate(tokens):
        if token.type == tokenize.INDENT:
            cur_indent += 1
        elif token.type == tokenize.DEDENT:
            cur_indent -= 1
            if significant_indents and cur_indent == significant_indents[-1]:
                significant_indents.pop()
                cur_name = cur_name.rpartition('.')[0]
        elif <MASK>:
            significant_indents.append(cur_indent)
            if cur_name:
                cur_name += '.'
            cur_name += tokens[i + 1].string
        result[token.start[0]] = cur_name
    cache[filename] = result

