def load_function_name(self, fn_name: str, push_null: bool, num_on_stack: int=0) -> list[Instruction]:
    """Load the global fn_name on the stack num_on_stack down"""
    output = []
    if push_null and sys.version_info >= (3, 11):
        output.extend(add_push_null(self.create_load_global(fn_name, add=True)))
        if <MASK>:
            output.extend([*self.rot_n(num_on_stack + 2), *self.rot_n(num_on_stack + 2)])
