        output.extend([self.create_load_global(fn_name, add=True), *self.rot_n(num_on_stack + 1)])
    return output

def operator_and_matrix(self, build_info, dtype, use_placeholder, ensure_self_adjoint_and_pd=False):
    shape = list(build_info.shape)
    tril = linear_operator_test_util.random_tril_matrix(shape, dtype=dtype, force_well_conditioned=True, remove_upper=False)
    if <MASK>:
        tril = array_ops.matrix_diag_part(tril)
        tril = math_ops.abs(tril) + 0.1
        tril = array_ops.matrix_diag(tril)
    lin_op_tril = tril
    if use_placeholder:
        lin_op_tril = array_ops.placeholder_with_default(lin_op_tril, shape=None)
    operator = linalg.LinearOperatorLowerTriangular(lin_op_tril, is_self_adjoint=True if ensure_self_adjoint_and_pd else None, is_positive_definite=True if ensure_self_adjoint_and_pd else None)
    matrix = array_ops.matrix_band_part(tril, -1, 0)
    return (operator, matrix)

def _cmp_method(self, other, op):
    if is_list_like(other):
        if len(self) != len(other):
            raise ValueError('Lengths must match to compare')
        other = pd_array(other)
    elif not isinstance(other, Interval):
        if <MASK>:
            from pandas.core.arrays import BooleanArray
            arr = np.empty(self.shape, dtype=bool)
            mask = np.ones(self.shape, dtype=bool)
            return BooleanArray(arr, mask)
        return invalid_comparison(self, other, op)
    if isinstance(other, Interval):
        other_dtype = pandas_dtype('interval')
    elif not isinstance(other.dtype, CategoricalDtype):
        other_dtype = other.dtype
    else:
        other_dtype = other.categories.dtype
        if isinstance(other_dtype, IntervalDtype):
            if self.closed != other.categories.closed:
                return invalid_comparison(self, other, op)
            other = other.categories._values.take(other.codes, allow_fill=True, fill_value=other.categories._na_value)
    if isinstance(other_dtype, IntervalDtype):
        if self.closed != other.closed:
            return invalid_comparison(self, other, op)
        elif not isinstance(other, Interval):
            other = type(self)(other)
        if op is operator.eq:
            return (self._left == other.left) & (self._right == other.right)
        elif op is operator.ne:
            return (self._left != other.left) | (self._right != other.right)
        elif op is operator.gt:
            return (self._left > other.left) | (self._left == other.left) & (self._right > other.right)
        elif op is operator.ge:
            return (self == other) | (self > other)
        elif op is operator.lt:
            return (self._left < other.left) | (self._left == other.left) & (self._right < other.right)
        else:
            return (self == other) | (self < other)
    if not is_object_dtype(other_dtype):
        return invalid_comparison(self, other, op)
    result = np.zeros(len(self), dtype=bool)
    for (i, obj) in enumerate(other):
        try:
            result[i] = op(self[i], obj)
        except TypeError:
            if obj is NA:
                result = result.astype(object)
                result[i] = NA
            else:
                raise
    return result

def _tfmw_add_deprecation_warning(self, name, attr):
    """Print deprecation warning for attr with given name if necessary."""
    if <MASK>:
        self._tfmw_deprecated_checked.add(name)
        if self._tfmw_module_name:
            full_name = 'tf.%s.%s' % (self._tfmw_module_name, name)
        else:
            full_name = 'tf.%s' % name
        rename = get_rename_v2(full_name)
        if rename and (not has_deprecation_decorator(attr)):
            call_location = _call_location()
            if not call_location.startswith('<'):
                logging.warning('From %s: The name %s is deprecated. Please use %s instead.\n', _call_location(), full_name, rename)
                self._tfmw_warning_count += 1
                return True
    return False

def __iter__(self):
    if <MASK>:
        raise RuntimeError('__iter__() is only supported inside of tf.function or when eager execution is enabled.')
    if not self._built:
        raise ValueError('To use this dataset, you need to pass this dataset to ClusterCoordinator.create_per_worker_dataset.')
    canonicalize_devices = getattr(self._strategy, '_canonicalize_devices', True)
    worker_iterators = _create_iterators_per_worker(self._cloned_datasets, self._input_workers, options=self._options, canonicalize_devices=canonicalize_devices)
    iterator = DistributedIterator(self._input_workers, worker_iterators, self._strategy, cardinality=self._cardinality, enable_get_next_as_optional=self._enable_get_next_as_optional, options=self._options, replica_order=self._replica_order)
    iterator._element_spec = self._element_spec
    if context.executing_eagerly():
        context.async_wait()
    return iterator

@doesnt_support_saved_tensors_hooks
def _vjp_with_argnums(func: Callable, *primals, argnums: Optional[argnums_t]=None, has_aux: bool=False):
    with grad_increment_nesting() as level:
        with torch.enable_grad():
            primals = _wrap_all_tensors(primals, level)
            if <MASK>:
                diff_primals = _create_differentiable(primals, level)
            else:
                diff_primals = _slice_argnums(primals, argnums, as_tuple=False)
                tree_map_(partial(_create_differentiable, level=level), diff_primals)
            primals_out = func(*primals)
            if has_aux:
                if not (isinstance(primals_out, tuple) and len(primals_out) == 2):
                    raise RuntimeError('vjp(f, *primals): output of function f should be a tuple: (output, aux) if has_aux is True')
                (primals_out, aux) = primals_out
                aux = _undo_create_differentiable(aux, level)
            (flat_primals_out, primals_out_spec) = tree_flatten(primals_out)
            assert_non_empty_tensor_output(flat_primals_out, 'vjp(f, *primals)')
            (flat_diff_primals, primals_spec) = tree_flatten(diff_primals)
            results = _undo_create_differentiable(primals_out, level)
            for primal_out in flat_primals_out:
                assert isinstance(primal_out, torch.Tensor)
                if primal_out.is_floating_point() or primal_out.is_complex():
                    continue
                raise RuntimeError(f'vjp(f, ...): All outputs of f must be floating-point or complex Tensors, got Tensor with dtype {primal_out.dtype}')

        def wrapper(cotangents, retain_graph=True, create_graph=None):
            if create_graph is None:
                create_graph = torch.is_grad_enabled()
            (flat_cotangents, cotangents_spec) = tree_flatten(cotangents)
            if primals_out_spec != cotangents_spec:
                raise RuntimeError(f'Expected pytree structure of cotangents to be the same as pytree structure of outputs to the function. cotangents: {treespec_pprint(cotangents_spec)}, primal output: {treespec_pprint(primals_out_spec)}')
            result = _autograd_grad(flat_primals_out, flat_diff_primals, flat_cotangents, retain_graph=retain_graph, create_graph=create_graph)
            return tree_unflatten(result, primals_spec)
    if has_aux:
        return (results, wrapper, aux)
    else:
        return (results, wrapper)

def _callback_from_stance(callback: DynamoCallback) -> DynamoCallback:
    if _stance.stance == 'default':
        if _stance.backend is not None and callback not in (False, None):
            callback = _create_wrapped_callback(get_compiler_fn(_stance.backend))
        return callback
    elif _stance.stance == 'eager_then_compile':
        if callback not in (False, None):
            return _create_delayed_compile_callback(callback, _stance.stance)
        return callback
    elif _stance.stance == 'aot_eager_then_compile':
        if callback not in (False, None):
            return _create_delayed_compile_callback(callback, _stance.stance)
        return callback
    elif _stance.stance == 'force_eager':
        return None
    elif _stance.stance == 'eager_on_recompile':
        return False
    elif _stance.stance == 'fail_on_recompile':
        if callback in (False, None):
            return callback

        def fail_callback(frame: DynamoFrameType, *args: Any, **kwargs: Any) -> ConvertFrameReturn:
            if trace_rules.check(frame.f_code):
                return ConvertFrameReturn()
            if not convert_frame.has_tensor_in_frame(frame):
                return ConvertFrameReturn()
            from torch._C._dynamo.eval_frame import _debug_get_cache_entry_list, _debug_get_precompile_entries
            from torch._dynamo.guards import get_and_maybe_log_recompilation_reasons
            message = "Detected recompile when torch.compile stance is 'fail_on_recompile'. " + f"filename: '{frame.f_code.co_filename}', " + f"function name: '{frame.f_code.co_name}', " + f'line number: {frame.f_lineno}'
            cache_entries = _debug_get_cache_entry_list(frame.f_code)
            if cache_entries:
                reasons = get_and_maybe_log_recompilation_reasons(cache_entries[0], frame, skip_logging=True)
                if <MASK>:
                    failures = textwrap.indent('\n'.join(reasons), '- ')
                    guard_failure_details = f'triggered by the following guard failure(s):\n{failures}'
                    message += f"\n{textwrap.indent(guard_failure_details, '    ')}"
            precompile_entries = _debug_get_precompile_entries(frame.f_code)
            if len(precompile_entries) > 0:
                message += '\nFailed on the following precompiled guards: '
                for entry in precompile_entries:
                    message += f'\n{entry.guard_manager}{entry.guard_manager.check_verbose(frame.f_locals)}'
            raise RuntimeError(message)
        fail_callback._torchdynamo_orig_backend = callback
        return fail_callback
    else:
        raise RuntimeError(f"invalid torch.compile stance '{_stance}'")

