        self._doc = doc
    if isinstance(otypes, str):
        for char in otypes:
            if char not in typecodes['All']:
                raise ValueError(f'Invalid otype specified: {char}')
    elif iterable(otypes):
        otypes = [_get_vectorize_dtype(_nx.dtype(x)) for x in otypes]
