def test_custom_gradients_with_none_grad_and_partial_shape(self, cycles, use_cpp_bindings):
    if <MASK>:
        self.skipTest('Not implemented for cpp.')

    @custom_gradient.custom_gradient
    def f(params, state):

        def grad_fn(*args):
            return args
        return ((params, state), grad_fn)

    @def_function.function(input_signature=[tensor_spec.TensorSpec(None, dtypes.float32), tensor_spec.TensorSpec(None, dtypes.int32)])
    def predict(params, state):
        return f(params, state)
    params = variables.Variable(1.0)
    state = constant_op.constant(3, dtype=dtypes.int32)
    with backprop.GradientTape() as tape:
        tape.watch(params)
        y = predict(params, state)
        expected_grads = tape.gradient(y, params)
    root = autotrackable.AutoTrackable()
    root.fn = predict
    loaded = cycle(root, cycles, save_option=save_options.SaveOptions(experimental_custom_gradients=True), use_cpp_bindings=use_cpp_bindings)
    with backprop.GradientTape() as tape:
        tape.watch(params)
        y = loaded.fn(params, state)
        grads = tape.gradient(y, params)
    self.assertAllClose(grads, expected_grads)

def pointwise_rule(op_schema: OpSchema, linearity: bool=False) -> OutputSharding:
    """
    Propagate the sharding for pointwise operations.

    Examples:
        ij,ij->ij - addition/mul
        ij,j->ij - broadcasted addition
    """
    alphabet = string.ascii_lowercase
    input_specs = op_schema.args_spec
    max_dim = max((input.ndim for input in input_specs))
    dimchars = []
    singleton_counter: list[int] = [0] * max_dim
    for input in input_specs:
        start_dim = max_dim - input.ndim
        p = alphabet[start_dim:max_dim]
        if <MASK>:
            for i in range(max_dim):
                if i < start_dim:
                    singleton_counter[i] += 1
                elif input.shape[i - start_dim] == 1:
                    singleton_counter[i] += 1
                    p = _replace_char_in_str(p, '1', i - start_dim)
        dimchars.append(p)
    out_dimchars = alphabet[:max_dim]
    for output_dim_idx in range(len(out_dimchars)):
        if singleton_counter[output_dim_idx] == len(input_specs):
            out_dimchars = _replace_char_in_str(out_dimchars, '1', output_dim_idx)
    fmt = f"{','.join((p for p in dimchars))}->{out_dimchars}"
    enforce_sharding: dict[str, int] = {}
    if op_schema.is_inplace_op():
        follow_spec = op_schema.args_spec[0]
        enforce_sharding.update(zip(out_dimchars, follow_spec.dim_map))
    elif op_schema.is_out_variant_op():
        follow_spec = cast(DTensorSpec, op_schema.kwargs_schema['out'])
        enforce_sharding.update(zip(out_dimchars, follow_spec.dim_map))
    return einop_rule(fmt, op_schema, linearity=linearity, enforce_sharding=enforce_sharding)

@_onnx_symbolic('aten::cross_entropy_loss')
def cross_entropy_loss(g: jit_utils.GraphContext, self, target, weight, reduction, ignore_index, label_smoothing):
    reduction = symbolic_helper._maybe_get_const(reduction, 'i')
    reduction_vals = ['none', 'mean', 'sum']
    reduction = reduction_vals[reduction]
    label_smoothing = symbolic_helper._maybe_get_const(label_smoothing, 'f')
    if <MASK>:
        raise errors.SymbolicValueError('Unsupported: ONNX does not support label_smoothing', self)
    ignore_index = symbolic_helper._maybe_get_const(ignore_index, 'i')
    if weight.node().mustBeNone():
        celoss = g.op('SoftmaxCrossEntropyLoss', self, target, reduction_s=reduction, ignore_index_i=ignore_index)
    else:
        celoss = g.op('SoftmaxCrossEntropyLoss', self, target, weight, reduction_s=reduction, ignore_index_i=ignore_index)
    return celoss

def in_bulk(self, id_list=None, *, field_name='pk'):
    """
        Return a dictionary mapping each of the given IDs to the object with
        that ID. If `id_list` isn't provided, evaluate the entire QuerySet.
        """
    if self.query.is_sliced:
        raise TypeError("Cannot use 'limit' or 'offset' with in_bulk().")
    if id_list is not None and (not id_list):
        return {}
    opts = self.model._meta
    unique_fields = [constraint.fields[0] for constraint in opts.total_unique_constraints if len(constraint.fields) == 1]
    if field_name != 'pk' and (not opts.get_field(field_name).unique) and (field_name not in unique_fields) and (self.query.distinct_fields != (field_name,)):
        raise ValueError("in_bulk()'s field_name must be a unique field but %r isn't." % field_name)
    qs = self

    def get_obj(obj):
        return obj
    if issubclass(self._iterable_class, ModelIterable):
