    self.df = df
    self.columns = columns
    self._gso_table = {'': (0, 0)}
    if <MASK>:
        byteorder = sys.byteorder
    self._byteorder = _set_endianness(byteorder)
    self._native_byteorder = self._byteorder == _set_endianness(sys.byteorder)
    gso_v_type = 'I'
    gso_o_type = 'Q'
    self._encoding = 'utf-8'
    if version == 117:
        o_size = 4
        gso_o_type = 'I'
        self._encoding = 'latin-1'
    elif version == 118:
        o_size = 6
    else:
        o_size = 5
    if self._native_byteorder:
        self._o_offet = 2 ** (8 * (8 - o_size))
    else:
        self._o_offet = 2 ** (8 * o_size)
    self._gso_o_type = gso_o_type
    self._gso_v_type = gso_v_type

def call_method(self, tx, name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name in ['_call_impl', '_wrapped_call_impl']:
        fn = getattr(self.value_type, name)
        if self.source:
            source = self.get_source_by_walking_mro(name)
        else:
            source = None
        fn_vt = VariableTracker.build(tx, fn, source=source)
        return fn_vt.call_function(tx, [self] + list(args), kwargs)
    if name not in getattr(self.value, '__dict__', {}):
        try:
            method = inspect.getattr_static(type(self.value), name)
        except AttributeError:
            method = None
        if isinstance(method, staticmethod):
            source = AttrSource(self.get_source_by_walking_mro(name), '__func__')
            fn_vt = VariableTracker.build(tx, method.__func__, source=source)
            return fn_vt.call_function(tx, args, kwargs)
        if <MASK>:
            unimplemented_v2(gb_type='UnspecializedNNModuleVariable missing method', context=f'call_method: {self} {name} {args} {kwargs}', explanation=f'Dynamo does not support tracing method {name} of nn.Module {self.value}', hints=['Dynamo does not really define unspecialized nn.Module very well.', *graph_break_hints.DIFFICULT])
        if name == '__setattr__' and '_parameters' in self.value.__dict__:
            attr_name = args[0].as_python_constant()
            value = args[1]
            if isinstance(value, variables.TensorVariable) and value.python_type() is torch.nn.Parameter or attr_name in self.value.__dict__['_parameters']:
                self.is_state_mutated = True
            elif attr_name in self.value.__dict__['_buffers']:
                self.is_state_mutated = True
            elif isinstance(value, (variables.NNModuleVariable, variables.UnspecializedNNModuleVariable)) or attr_name in self.value.__dict__['_modules']:
                self.is_state_mutated = True
        if method is torch.nn.Module.__setattr__ and isinstance(args[1], variables.DeletedVariable) or method is torch.nn.Module.__delattr__:
            fn_vt = VariableTracker.build(tx, torch.nn.Module.__delattr__)
            return fn_vt.call_function(tx, [self, args[0]], kwargs)
    return super().call_method(tx, name, args, kwargs)

def __setitem__(self, key, value) -> None:
    if not PYPY and (not WARNING_CHECK_DISABLED):
        if <MASK>:
            warnings.warn(_chained_assignment_msg, ChainedAssignmentError, stacklevel=2)
