                self._where(~key, value, inplace=True)
            except InvalidIndexError:
                self.iloc[key] = value
            return
        else:
            self._set_with(key, value)

def get_key(event, group_by_input_shapes, group_by_stack_n, group_by_overload_name) -> tuple[str, ...]:
