def placeholder_naming_pass(gm: torch.fx.GraphModule, export_graph_signature: 'ExportGraphSignature', mod: torch.nn.Module, fake_args, fake_kwargs, fake_params_buffers, constants: dict[str, Any]) -> None:
    """
    This pass is run at the end of _export_non_strict() to assign better placeholder node names:
        - User inputs:
            These follow the signature of mod.forward(), e.g. forward(x, y) produces nodes x, y.
            For nested inputs from dictionaries, lists, tuples, or dataclasses,
            the names are a concatenation of the path to the tensor.
                e.g. x = {
                    'a': torch.randn(),
                    'b': [torch.randn(), torch.randn()]
                }
            produces nodes x_a, x_b_0, x_b_1.
        - Parameters/buffers/constants/custom objects:
            These follow the FQN of the object, prefixed by "p", "b", "c", "obj" respectively.
                e.g. self.bar.l0.weight produces "p_bar_l0_weight".
        - Effect tokens:
            These are named token, token_1, ...
    """
    custom_meta: dict[str, Any] = {}
    if isinstance(mod, torch.fx.GraphModule):
        for node in mod.graph.nodes:
            if 'custom' in node.meta:
                custom_meta[node.name] = node.meta['custom']

    def _strip_name(x):
        if x.startswith('L__self___'):
            x = x[len('L__self___'):]
        elif x.startswith('self_'):
            x = x[len('self_'):]
        x = re.sub('[^a-zA-Z0-9]', '_', x)
        return x

    def _extract_pytree_key(x):
        if isinstance(x, MappingKey):
            x = re.sub('[^a-zA-Z0-9]', '_', str(x.key))
            return x
        elif isinstance(x, SequenceKey):
            return str(x.idx)
        elif isinstance(x, GetAttrKey):
            return x.name
        else:
            raise RuntimeError(f'Pytree key of type {type(x)} not handled for {x}')
    name_map: dict[str, str] = {}
    find_available: dict[str, int] = defaultdict(int)
    used_names: set[str] = set()
    combined_args = _bind_signature_to_inputs(mod, fake_args, fake_kwargs)
    (flat_args_with_path, _) = tree_flatten_with_path(combined_args)
    user_input_names = [spec.arg.name for spec in export_graph_signature.input_specs if spec.kind == InputKind.USER_INPUT]
    for ((arg_path, _arg), user_input_name) in zip(flat_args_with_path, user_input_names):
        if user_input_name:
            _rename_without_collisions(name_map, find_available, used_names, user_input_name, placeholder_prefixes[InputKind.USER_INPUT] + '_'.join((_extract_pytree_key(x).lower() for x in arg_path)), is_placeholder=True)
    for spec in export_graph_signature.input_specs:
        if spec.kind == InputKind.USER_INPUT:
            continue
        if spec.kind == InputKind.TOKEN:
            base_name = ''
        else:
            base_name = _strip_name(spec.target).lower()
        base_name = re.sub('[^a-zA-Z0-9]', '_', base_name)
        _rename_without_collisions(name_map, find_available, used_names, spec.arg.name, placeholder_prefixes[spec.kind] + base_name, is_placeholder=True)
        if base_name in custom_meta:
            custom_meta[name_map[spec.arg.name]] = custom_meta[base_name]
            del custom_meta[base_name]
    for node in gm.graph.nodes:
        if node.op == 'placeholder':
            continue
        _rename_without_collisions(name_map, find_available, used_names, node.name, node.name)
    for node in gm.graph.nodes:
        if node.op == 'placeholder':
            assert node.name in name_map
            node.name = node.target = name_map[node.name]
            if node.name in custom_meta:
                if node.meta.get('custom') is None:
                    node.meta['custom'] = custom_meta[node.name]
                else:
                    assert node.meta['custom'] == custom_meta[node.name]
            if isinstance(node.meta['val'], CustomObjArgument):
                node.meta['val'].name = node.name
        elif node.name in name_map:
            node.name = name_map[node.name]
    _name_hoo_subgraph_placeholders(gm)
    gm.recompile()
    for spec in export_graph_signature.input_specs:
        assert spec.arg.name in name_map
        spec.arg.name = name_map[spec.arg.name]
        if <MASK>:
            spec.target = name_map[spec.target][4:]
    for spec in export_graph_signature.output_specs:
        if spec.arg.name in name_map:
            spec.arg.name = name_map[spec.arg.name]
        if spec.kind == OutputKind.USER_INPUT_MUTATION and spec.target in name_map:
            spec.target = name_map[spec.target]
    for name in list(constants.keys()):
        constant = constants[name]
        if name in name_map and (not isinstance(constant, torch.Tensor)):
            new_name = name_map[name]
            if new_name != name and re.match('arg(\\d+)_1', name) and (new_name != placeholder_prefixes[InputKind.CUSTOM_OBJ] + name):
                constants[new_name] = constant
                del constants[name]

def CheckInputFromValidContext(op, input_op):
    """Returns whether `input_op` can be used from `op`s context.

  Conceptually, only inputs from op's while context or any ancestor while
  context (including outside of any context) are valid. In practice, there are
  many other edge cases as well.

  Args:
    op: Operation
    input_op: Operation

  Raises:
    ValueError: if input_op is from an invalid context.
  """
    op_ctxt = op._get_control_flow_context()
    input_ctxt = GetOutputContext(input_op)
    valid = False
    if <MASK>:
        valid = True
    elif op_ctxt is input_ctxt:
        valid = True
    else:
        while_ctxt = GetContainingWhileContext(op_ctxt)
        input_while_ctxt = GetContainingWhileContext(input_ctxt)
        if while_ctxt is None:
            if input_while_ctxt is None:
                valid = True
            if IsLoopEnter(op):
                valid = True
            if IsSwitch(op):
                valid = True
        elif IsContainingContext(while_ctxt, input_while_ctxt):
            valid = True
        elif while_ctxt.grad_state and IsContainingContext(while_ctxt.grad_state.forward_context, input_while_ctxt):
            valid = True
        elif while_ctxt.grad_state and while_ctxt.grad_state.forward_context is input_while_ctxt._outer_context:
            valid = True
        elif input_while_ctxt.grad_state and input_while_ctxt.grad_state.forward_context is while_ctxt:
            valid = True
        elif input_while_ctxt.grad_state and input_ctxt.grad_state.forward_context.grad_state and (input_ctxt.grad_state.forward_context.grad_state.forward_context is while_ctxt):
            valid = True
    if not valid:
        if while_ctxt:
            error_msg = f"Cannot use '{input_op.name}' as input to '{op.name}' because they are in different while loops."
        else:
            error_msg = f"Cannot use '{input_op.name}' as input to '{op.name}' because '{input_op.name}' is in a while loop."
        log_msg = error_msg
        log_msg += '\n\n%s while context: %s' % (op.name, while_ctxt)
        log_msg += '\n%s while context: %s' % (input_op.name, input_while_ctxt)
        log_msg += '\n\nTraceback for %s:\n%s\nTraceback for %s:\n%s\n' % (op.name, ''.join(traceback.format_list(op.traceback)), input_op.name, ''.join(traceback.format_list(input_op.traceback)))
        logging.info(log_msg)
        raise ValueError(error_msg + ' See info log for more details.')

def _base_set(self, mode, key, value, timeout=DEFAULT_TIMEOUT):
    timeout = self.get_backend_timeout(timeout)
    db = router.db_for_write(self.cache_model_class)
    connection = connections[db]
    quote_name = connection.ops.quote_name
    table = quote_name(self._table)
    with connection.cursor() as cursor:
        cursor.execute('SELECT COUNT(*) FROM %s' % table)
        num = cursor.fetchone()[0]
        now = tz_now()
        now = now.replace(microsecond=0)
        if timeout is None:
            exp = datetime.max
        else:
            tz = UTC if settings.USE_TZ else None
            exp = datetime.fromtimestamp(timeout, tz=tz)
        exp = exp.replace(microsecond=0)
        if num > self._max_entries:
            self._cull(db, cursor, now, num)
        pickled = pickle.dumps(value, self.pickle_protocol)
        b64encoded = base64.b64encode(pickled).decode('latin1')
        try:
            with transaction.atomic(using=db):
                cursor.execute('SELECT %s, %s FROM %s WHERE %s = %%s' % (quote_name('cache_key'), quote_name('expires'), table, quote_name('cache_key')), [key])
                result = cursor.fetchone()
                if result:
                    current_expires = result[1]
                    expression = models.Expression(output_field=models.DateTimeField())
                    for converter in connection.ops.get_db_converters(expression) + expression.get_db_converters(connection):
                        current_expires = converter(current_expires, expression, connection)
                exp = connection.ops.adapt_datetimefield_value(exp)
                if <MASK>:
                    cursor.execute('UPDATE %s SET %s = %%s WHERE %s = %%s' % (table, quote_name('expires'), quote_name('cache_key')), [exp, key])
                elif result and (mode == 'set' or (mode == 'add' and current_expires < now)):
                    cursor.execute('UPDATE %s SET %s = %%s, %s = %%s WHERE %s = %%s' % (table, quote_name('value'), quote_name('expires'), quote_name('cache_key')), [b64encoded, exp, key])
                elif mode != 'touch':
                    cursor.execute('INSERT INTO %s (%s, %s, %s) VALUES (%%s, %%s, %%s)' % (table, quote_name('cache_key'), quote_name('value'), quote_name('expires')), [key, b64encoded, exp])
                else:
                    return False
        except DatabaseError:
            return False
        else:
            return True

def _get_formatdict(data, *, precision, floatmode, suppress, sign, legacy, formatter, **kwargs):
    formatdict = {'bool': lambda : BoolFormat(data), 'int': lambda : IntegerFormat(data, sign), 'float': lambda : FloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'longfloat': lambda : FloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'complexfloat': lambda : ComplexFloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'longcomplexfloat': lambda : ComplexFloatingFormat(data, precision, floatmode, suppress, sign, legacy=legacy), 'datetime': lambda : DatetimeFormat(data, legacy=legacy), 'timedelta': lambda : TimedeltaFormat(data), 'object': lambda : _object_format, 'void': lambda : str_format, 'numpystr': lambda : repr_format}

    def indirect(x):
        return lambda : x
    if formatter is not None:
        fkeys = [k for k in formatter.keys() if formatter[k] is not None]
        if <MASK>:
            for key in formatdict.keys():
                formatdict[key] = indirect(formatter['all'])
        if 'int_kind' in fkeys:
            for key in ['int']:
                formatdict[key] = indirect(formatter['int_kind'])
        if 'float_kind' in fkeys:
            for key in ['float', 'longfloat']:
                formatdict[key] = indirect(formatter['float_kind'])
        if 'complex_kind' in fkeys:
            for key in ['complexfloat', 'longcomplexfloat']:
                formatdict[key] = indirect(formatter['complex_kind'])
        if 'str_kind' in fkeys:
            formatdict['numpystr'] = indirect(formatter['str_kind'])
        for key in formatdict.keys():
            if key in fkeys:
                formatdict[key] = indirect(formatter[key])
    return formatdict

def __new__(mcs, name, bases, attrs):
    new_class = super().__new__(mcs, name, bases, attrs)
