def run_single_backend_FA(config: ExperimentConfig, query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, out_compile: torch.Tensor, score_mod: Callable | None, block_mask: BlockMask | None, mask_kwargs, backend: str) -> ExperimentResults:
    assert backend in ['fav2', 'fav3', 'fakv']
    if backend in ['fav2', 'fav3']:
        FA = generate_FA_callable(config.attn_type, config.shape, config.dtype, backend, **mask_kwargs)
    elif backend == 'fakv':
        FA = generate_FD_callable(config.attn_type, config.shape, config.dtype)
    (q_FA, k_FA, v_FA) = query_key_value_clones(query, key, value)
    (q_FA, k_FA, v_FA) = (q_FA.transpose(1, 2), k_FA.transpose(1, 2), v_FA.transpose(1, 2))
    if <MASK>:
        q_FA = q_FA.flatten(start_dim=0, end_dim=1)
        k_FA = k_FA.flatten(start_dim=0, end_dim=1)
        v_FA = v_FA.flatten(start_dim=0, end_dim=1)
    if FA:
        out_FA = FA(q=q_FA, k=k_FA, v=v_FA)
        if config.attn_type in ['document_mask']:
            out_FA_updated = out_FA[None, :, :, :]
        else:
            out_FA_updated = out_FA
        if not (config.attn_type in ['rel', 'alibi'] and config.dtype in [torch.float16, torch.bfloat16]):
            torch.testing.assert_close(out_FA_updated, out_compile.transpose(1, 2), atol=0.01, rtol=0.01)
    if FA:
        forward_FA_time = benchmark_torch_function_in_microseconds(FA, q=q_FA, k=k_FA, v=v_FA)
    else:
        forward_FA_time = float('nan')
    if config.calculate_bwd_time:
        if FA:
            d_out = torch.randn_like(out_FA)
            backward_FA_time = benchmark_torch_function_in_microseconds(out_FA.backward, d_out, retain_graph=True)
        else:
            backward_FA_time = float('nan')
    return ExperimentResults(fwd_time=forward_FA_time, bwd_time=backward_FA_time if config.calculate_bwd_time else None)

def operand_to_template_torchscript(self, op_id, oper, shape=None):
    """Return a TorchScript expression to build a template for a given operand."""
    if shape is None:
        shape = oper.shape
    else:
        assert len(shape) == len(oper.shape)
    shape_parts = ['(']
    for (d, s) in enumerate(shape):
        if <MASK>:
            shape_parts.append(str(s))
        elif s == 0:
            shape_parts.append(flex_name(op_id, d))
        elif s == -1:
            shape_parts.append('0')
        else:
            raise Exception('Unknown dim value, dimensions should be >= -1')
        shape_parts.append(',')
    shape_parts.append(')')
    shape_code = ''.join(shape_parts)
    if oper.op_type == NNAPI_OperandCode.TENSOR_FLOAT32:
        return f'torch.zeros({shape_code}, dtype=torch.float32)'
    elif oper.op_type == NNAPI_OperandCode.TENSOR_INT32:
        return f'torch.zeros({shape_code}, dtype=torch.int32)'
    elif oper.op_type == NNAPI_OperandCode.TENSOR_QUANT8_ASYMM:
        return f'torch.quantize_per_tensor(torch.zeros(1), scale={oper.scale}, zero_point={oper.zero_point}, dtype=torch.quint8).expand({shape_code}).contiguous()'
    elif oper.op_type in (NNAPI_OperandCode.TENSOR_QUANT16_ASYMM, NNAPI_OperandCode.TENSOR_QUANT16_SYMM):
        if self.use_int16_for_qint16:
            return f'torch.zeros({shape_code}, dtype=torch.int16)'
        else:
            raise Exception("`int16` isn't supported. If you're trying to represent NNAPI qint16 with Pytorch int16, set `use_int16_for_qint16 = True`")
    raise Exception(f'Unsupported output operand type: {oper.op_type}')

def _write_to_group(self, key: str, value: DataFrame | Series, format, axes=None, index: bool | list[str]=True, append: bool=False, complib=None, complevel: int | None=None, fletcher32=None, min_itemsize: int | dict[str, int] | None=None, chunksize: int | None=None, expectedrows=None, dropna: bool=False, nan_rep=None, data_columns=None, encoding=None, errors: str='strict', track_times: bool=True) -> None:
    if getattr(value, 'empty', None) and (format == 'table' or append):
        return
    group = self._identify_group(key, append)
    s = self._create_storer(group, format, value, encoding=encoding, errors=errors)
    if append:
        if <MASK>:
            raise ValueError('Can only append to Tables')
        if not s.is_exists:
            s.set_object_info()
    else:
        s.set_object_info()
    if not s.is_table and complib:
        raise ValueError('Compression not supported on Fixed format stores')
    s.write(obj=value, axes=axes, append=append, complib=complib, complevel=complevel, fletcher32=fletcher32, min_itemsize=min_itemsize, chunksize=chunksize, expectedrows=expectedrows, dropna=dropna, nan_rep=nan_rep, data_columns=data_columns, track_times=track_times)
    if isinstance(s, Table) and index:
        s.create_index(columns=index)

def apply_mask(y_p, sw, mask):
    """Applies any mask on predictions to sample weights."""
    if mask is not None:
        mask = math_ops.cast(mask, y_p.dtype)
        if <MASK>:
            (mask, _, sw) = losses_utils.squeeze_or_expand_dimensions(mask, sample_weight=sw)
            sw *= mask
        else:
            sw = mask
    return sw

def is_out_of_place(rel_filepath):
    if os.path.isabs(rel_filepath):
        raise AssertionError('rel_filepath must be a relative path')
    if rel_filepath.startswith('torch/'):
        return False
    if <MASK>:
        return False
    if rel_filepath.startswith('tools/autograd/templates/'):
