def _get_input_shape_for_tensor(self, tensor, feature, per_replica, path) -> TensorShape:
    """Get the input shape for the dense tensor."""
    shape = tensor.shape.as_list()
    if len(shape) < 1:
        raise ValueError('Only rank 1 and above dense tensor is supported, find rank {} sparse tensor for input {}'.format(len(shape), path))
    if len(shape) > 1 and shape[-1] != 1:
        raise ValueError('Rank 2 or above dense tensor should have last dimension as 1 as the last dimension will always be reduced. Instead got dense tensor as shape {}'.format(shape))
    if <MASK>:
        shape[0] = shape[0] // self._num_cores_per_replica
    return TensorShape(shape)

def _fused_sgd(params: list[Tensor], grads: list[Tensor], momentum_buffer_list: list[Optional[Tensor]], grad_scale: Optional[Tensor], found_inf: Optional[Tensor], *, weight_decay: float, momentum: float, lr: float, dampening: float, nesterov: bool, maximize: bool, has_sparse_grad: bool) -> None:
    if <MASK>:
        return
    if has_sparse_grad:
        raise RuntimeError('`_fused_sgd` does not support sparse gradients')
    grad_scale_dict: DeviceDict = {grad_scale.device: grad_scale} if grad_scale is not None else {}
    found_inf_dict: DeviceDict = {found_inf.device: found_inf} if found_inf is not None else {}
    no_momentum_buffer = momentum == 0
    is_first_step = all((t is None for t in momentum_buffer_list)) and (not no_momentum_buffer)
    if is_first_step:
        for (i, g) in enumerate(grads):
            momentum_buffer_list[i] = torch.empty_like(g)
    grouped_tensors = Optimizer._group_tensors_by_device_and_dtype([params, grads, momentum_buffer_list], with_indices=False)
    for ((device, _), ((device_params_, device_grads_, device_momentum_buffer_list), _)) in grouped_tensors.items():
        device_params: list[Tensor] = cast(list[Tensor], device_params_)
        device_grads: list[Tensor] = cast(list[Tensor], device_grads_)
        (device_grad_scale, device_found_inf) = (None, None)
        if grad_scale is not None:
            device_grad_scale = grad_scale_dict.setdefault(device, grad_scale.to(device))
        if found_inf_dict is not None and found_inf is not None:
            device_found_inf = found_inf_dict.setdefault(device, found_inf.to(device))
        torch._fused_sgd_(device_params, device_grads, [] if no_momentum_buffer else cast(list[Tensor], device_momentum_buffer_list), weight_decay=weight_decay, momentum=momentum, lr=lr, dampening=dampening, nesterov=nesterov, maximize=maximize, is_first_step=is_first_step, grad_scale=device_grad_scale, found_inf=device_found_inf)

def _capture_helper(self, tensor, name):
    if tensor.graph is not self._forward_graph or any((tensor is t for t in self._forward_graph.inputs)) or any((tensor is t for t in self._forward_graph.outputs)):
        return super(_CondGradFuncGraph, self)._capture_helper(tensor, name)
    tensor_id = ops.tensor_id(tensor)
    if tensor_id in self._captured_constants:
        return self._captured_constants[tensor_id]
    elif constant_op.is_constant(tensor):
        self._captured_constants[tensor_id] = constant_op.constant(tensor_util.constant_value(tensor), dtype=tensor.dtype)
        return self._captured_constants[tensor_id]
    if not context.optionals_in_gradients_enabled() or control_flow_util.GraphOrParentsInXlaContext(ops.get_default_graph()):
        if all((tensor is not capture for capture in self.external_captures)):
            self.xla_intermediates.append(tensor)
            self.op_needs_rewrite = True
        return super(_CondGradFuncGraph, self)._capture_helper(tensor, name)
    captured_tensor = self._indirect_captures.get(tensor_id)
    if captured_tensor is not None:
        return captured_tensor
    if <MASK>:
        index = util.resource_input_index(tensor.name, [t.name for t in self._forward_graph.inputs], {op.name: op.node_def for op in self._forward_graph.get_operations()}, self._forward_graph._functions)
        captured_tensor = super(_CondGradFuncGraph, self)._capture_helper(self._forward_graph.inputs[index], name)
    else:
        if tensor_id not in self._wrapped_intermediates:
            for consumer in tensor.consumers():
                if consumer.type == 'OptionalFromValue' and any((consumer.outputs[0] is output for output in self._forward_graph.outputs)):
                    optional = consumer.outputs[0]
                    break
            else:
                with self._forward_graph.as_default():
                    optional = gen_optional_ops.optional_from_value([tensor])
                self.op_needs_rewrite = True
            self._wrapped_intermediates[tensor_id] = optional
        optional = self._wrapped_intermediates[tensor_id]
        captured_optional = super(_CondGradFuncGraph, self)._capture_helper(optional, name)
        captured_tensor = gen_optional_ops.optional_get_value(captured_optional, [tensor.dtype], [tensor.shape])[0]
    self._indirect_captures[tensor_id] = captured_tensor
    return captured_tensor

def _wrap_join_result(self, joined: ArrayLike, other: Self, lidx: npt.NDArray[np.intp] | None, ridx: npt.NDArray[np.intp] | None, how: JoinHow) -> tuple[Self, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert other.dtype == self.dtype
    if lidx is not None and lib.is_range_indexer(lidx, len(self)):
        lidx = None
    if ridx is not None and lib.is_range_indexer(ridx, len(other)):
        ridx = None
    if lidx is None:
        join_index = self
    elif ridx is None:
        join_index = other
    else:
        join_index = self._constructor._with_infer(joined, dtype=self.dtype)
    names = other.names if how == 'right' else self.names
    if <MASK>:
        join_index = join_index.set_names(names)
    return (join_index, lidx, ridx)

def _traverse_obj(path: OBJ_PATH, value: Any) -> None:
    if isinstance(value, Mapping):
        for (k, v) in value.items():
            _traverse_obj(path + (str(k),), v)
    elif <MASK>:
        for (i, v) in enumerate(value):
            _traverse_obj(path + (i,), v)
    else:
        visitor(path, value)

def _check_valid_event_ndims(self, min_event_ndims, event_ndims):
    """Check whether event_ndims is at least min_event_ndims."""
    event_ndims = ops.convert_to_tensor(event_ndims, name='event_ndims')
    event_ndims_ = tensor_util.constant_value(event_ndims)
    assertions = []
    if not event_ndims.dtype.is_integer:
        raise ValueError('Expected integer dtype, got dtype {}'.format(event_ndims.dtype))
    if event_ndims_ is not None:
        if <MASK>:
            raise ValueError('Expected scalar event_ndims, got shape {}'.format(event_ndims.shape))
        if min_event_ndims > event_ndims_:
            raise ValueError('event_ndims ({}) must be larger than min_event_ndims ({})'.format(event_ndims_, min_event_ndims))
    elif self.validate_args:
        assertions += [check_ops.assert_greater_equal(event_ndims, min_event_ndims)]
    if event_ndims.shape.is_fully_defined():
        if event_ndims.shape.ndims != 0:
            raise ValueError('Expected scalar shape, got ndims {}'.format(event_ndims.shape.ndims))
    elif self.validate_args:
        assertions += [check_ops.assert_rank(event_ndims, 0, message='Expected scalar.')]
    return assertions

@abstractmethod
def fit(self, X, Y, **fit_params):
    """Fit the model to data matrix X and targets Y.

        Parameters
        ----------
        X : {array-like, sparse matrix} of shape (n_samples, n_features)
            The input data.

        Y : array-like of shape (n_samples, n_classes)
            The target values.

        **fit_params : dict of string -> object
            Parameters passed to the `fit` method of each step.

            .. versionadded:: 0.23

        Returns
        -------
        self : object
            Returns a fitted instance.
        """
    (X, Y) = validate_data(self, X, Y, multi_output=True, accept_sparse=True)
    random_state = check_random_state(self.random_state)
    self.order_ = self.order
    if isinstance(self.order_, tuple):
        self.order_ = np.array(self.order_)
    if self.order_ is None:
        self.order_ = np.array(range(Y.shape[1]))
    elif isinstance(self.order_, str):
        if self.order_ == 'random':
            self.order_ = random_state.permutation(Y.shape[1])
    elif sorted(self.order_) != list(range(Y.shape[1])):
        raise ValueError('invalid order')
    self.estimators_ = [clone(self._get_estimator()) for _ in range(Y.shape[1])]
    if self.cv is None:
        Y_pred_chain = Y[:, self.order_]
        if sp.issparse(X):
            X_aug = sp.hstack((X, Y_pred_chain), format='lil')
            X_aug = X_aug.tocsr()
        else:
            X_aug = np.hstack((X, Y_pred_chain))
    elif sp.issparse(X):
        if <MASK>:
            if X.format == 'dok':
                X = sp.coo_array(X)
            Y_pred_chain = sp.coo_array((X.shape[0], Y.shape[1]))
        else:
            Y_pred_chain = sp.coo_matrix((X.shape[0], Y.shape[1]))
        X_aug = sp.hstack((X, Y_pred_chain), format='lil')
    else:
        Y_pred_chain = np.zeros((X.shape[0], Y.shape[1]))
        X_aug = np.hstack((X, Y_pred_chain))
    del Y_pred_chain
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = Bunch(estimator=Bunch(fit=fit_params))
    if hasattr(self, 'chain_method'):
        chain_method = _check_response_method(self._get_estimator(), self.chain_method).__name__
        self.chain_method_ = chain_method
    else:
        chain_method = 'predict'
    for (chain_idx, estimator) in enumerate(self.estimators_):
        message = self._log_message(estimator_idx=chain_idx + 1, n_estimators=len(self.estimators_), processing_msg=f'Processing order {self.order_[chain_idx]}')
        y = Y[:, self.order_[chain_idx]]
        with _print_elapsed_time('Chain', message):
            estimator.fit(X_aug[:, :X.shape[1] + chain_idx], y, **routed_params.estimator.fit)
        if self.cv is not None and chain_idx < len(self.estimators_) - 1:
            col_idx = X.shape[1] + chain_idx
            cv_result = cross_val_predict(self._get_estimator(), X_aug[:, :col_idx], y=y, cv=self.cv, method=chain_method)
            if cv_result.ndim > 1:
                cv_result = cv_result[:, 1]
            if sp.issparse(X_aug):
                X_aug[:, col_idx] = np.expand_dims(cv_result, 1)
            else:
                X_aug[:, col_idx] = cv_result
    return self

def custom_fwd(fwd=None, *, device_type: str, cast_inputs: Optional[_dtype]=None):
    """
    Create a helper decorator for ``forward`` methods of custom autograd functions.

    Autograd functions are subclasses of :class:`torch.autograd.Function`.
    See the :ref:`example page<amp-custom-examples>` for more detail.

    Args:
        device_type(str):  Device type to use. 'cuda', 'cpu', 'mtia', 'maia', 'xpu' and so on.
            The type is the same as the `type` attribute of a :class:`torch.device`.
            Thus, you may obtain the device type of a tensor using `Tensor.device.type`.
        cast_inputs (:class:`torch.dtype` or None, optional, default=None):  If not ``None``,
            when ``forward`` runs in an autocast-enabled region, casts incoming
            floating-point Tensors to the target dtype (non-floating-point Tensors are not affected),
            then executes ``forward`` with autocast disabled.
            If ``None``, ``forward``'s internal ops execute with the current autocast state.

    .. note::
        If the decorated ``forward`` is called outside an autocast-enabled region,
        :func:`custom_fwd<custom_fwd>` is a no-op and ``cast_inputs`` has no effect.
    """
    if <MASK>:
        raise ValueError(f'Expected `device_type` of type `str`, got: `{type(device_type)}`')
    if fwd is None:
        return functools.partial(custom_fwd, device_type=device_type, cast_inputs=cast_inputs)

    @functools.wraps(fwd)
    def decorate_fwd(*args, **kwargs):
        args[0]._dtype = torch.get_autocast_dtype(device_type)
        if cast_inputs is None:
            args[0]._fwd_used_autocast = torch.is_autocast_enabled(device_type)
            return fwd(*args, **kwargs)
        else:
            autocast_context = torch.is_autocast_enabled(device_type)
            args[0]._fwd_used_autocast = False
            if autocast_context:
                with autocast(device_type=device_type, enabled=False):
                    return fwd(*_cast(args, device_type, cast_inputs), **_cast(kwargs, device_type, cast_inputs))
            else:
                return fwd(*args, **kwargs)
    return decorate_fwd

@with_native_function
def set_up_derivatives(f: NativeFunction) -> tuple[Sequence[Derivative], Sequence[ForwardDerivative], Sequence[Binding], Sequence[str], Sequence[str]]:
    derivatives: list[Derivative] = []
    forward_derivatives: list[ForwardDerivative] = []
    non_differentiable_arg_names: list[str] = []
    args_with_derivatives_set: set[str] = set()
    all_arg_names = [a.name for a in cpp_arguments(f)]
    all_ret_names = [r.name for r in f.func.returns]
    differentiability = output_differentiability or [True] * len(f.func.returns)
    available_named_gradients = [f'grad_{ret.name}' for (ret, differentiable) in zip(f.func.returns, differentiability) if differentiable and ret.name is not None and ret.type.is_tensor_like()]
    for raw_names in sorted(defn.keys()):
        formula = defn[raw_names]
        names = split_names(raw_names)
        for name in names:
            assert not (name in all_arg_names and name in all_ret_names), f"While processing the derivative formula for '{f.func.name}' wrt '{name}', expected '{name}' to not be both an input arg and named return. "
        if is_forward_derivative_definition(all_arg_names, names):
            forward_derivatives.append(create_forward_derivative(f, formula, names))
        elif <MASK>:
            non_differentiable_arg_names += names
        else:
            derivative = create_derivative(f, formula, names, available_named_gradients)
            derivatives.append(derivative)
            args_with_derivatives_set |= set(names)
    overlap = args_with_derivatives_set.intersection(non_differentiable_arg_names)
    if overlap:
        raise RuntimeError(f'derivatives definition for {defn} have overlapped non_differentiable and differentiable variables: {overlap}')
    args_with_derivatives = [a for a in cpp_arguments(f) if a.name in args_with_derivatives_set]
    forward_derivatives = postprocess_forward_derivatives(f, defn_name, all_arg_names, derivatives, forward_derivatives, args_with_derivatives)
    check_grad_usage(defn_name, derivatives)
    return (derivatives, forward_derivatives, args_with_derivatives, non_differentiable_arg_names, available_named_gradients)

def _convert_obj(self, obj: NDFrameT) -> NDFrameT:
    obj = super()._convert_obj(obj)
    if <MASK>:
        msg = 'Resampling from level= or on= selection with a PeriodIndex is not currently supported, use .set_index(...) to explicitly set index'
        raise NotImplementedError(msg)
    return obj

def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
    """Identifies imports of decorator."""
    if <MASK>:
        for name in node.names:
            if name.name == self._decorator_symbol:
                if name.asname:
                    self._current_file_decorators.add(name.asname)
                else:
                    self._current_file_decorators.add(name.name)
    else:
        (parent, module) = self._decorator_package.rsplit('.', 1)
        if node.module == parent:
            for name in node.names:
                if name.name == module:
                    if name.asname:
                        self._current_file_decorators.add(name.asname + '.' + self._decorator_symbol)
                    else:
                        self._current_file_decorators.add(name.name + '.' + self._decorator_symbol)
    self.generic_visit(node)

def _verify_destinations_not_different_worker(self, destinations):
    if <MASK>:
        return
    if destinations is None:
        return
    for d in cross_device_ops_lib.get_devices_from(destinations):
        d_spec = tf_device.DeviceSpec.from_string(d)
        if d_spec.job == self._task_type and d_spec.task != self._task_id:
            raise ValueError('Cannot reduce to another worker: %r, current worker is %r' % (d, self._worker_device))

def as_term_coeff(obj):
    """Return expression as term-coefficient pair.
    """
    if isinstance(obj, Expr):
        obj = normalize(obj)
        if obj.op is Op.INTEGER:
            return (as_integer(1, obj.data[1]), obj.data[0])
        if <MASK>:
            return (as_real(1, obj.data[1]), obj.data[0])
        if obj.op is Op.TERMS:
            if len(obj.data) == 1:
                ((term, coeff),) = obj.data.items()
                return (term, coeff)
        if obj.op is Op.APPLY and obj.data[0] is ArithOp.DIV:
            (t, c) = as_term_coeff(obj.data[1][0])
            return (as_apply(ArithOp.DIV, t, obj.data[1][1]), c)
        return (obj, 1)
    raise OpError(f'cannot convert {type(obj)} to term and coeff')

def load_model(self, device, model_name, batch_size=None, extra_args=None):
    is_training = self.args.training
    use_eval_mode = self.args.use_eval_mode
    dtype = torch.float32
    reset_rng_state()
    if model_name in BATCH_SIZE_KNOWN_MODELS:
        batch_size_default = BATCH_SIZE_KNOWN_MODELS[model_name]
    elif <MASK>:
        batch_size_default = 16
        log.info(f'Batch size not specified for {model_name}. Setting batch_size=16')
    if batch_size is None:
        batch_size = batch_size_default
        batch_size_divisors = self._config['batch_size']['divisors']
        if model_name in batch_size_divisors:
            batch_size = max(int(batch_size / batch_size_divisors[model_name]), 1)
            log.info(f'Running smaller batch size={batch_size} for {model_name}, orig batch_size={batch_size_default}')
    if model_name in HF_LLM_MODELS:
        benchmark_cls = HF_LLM_MODELS[model_name]
        (model, example_inputs) = benchmark_cls.get_model_and_inputs(model_name, device)
        self.hf_llm = True

        def generate(self, _, example_inputs, collect_outputs=True):
            return model.generate(**example_inputs)
        self.generate = types.MethodType(generate, self)
    else:
        self.hf_llm = False
        (model_cls, config) = self._get_model_cls_and_config(model_name)
        model = self._download_model(model_name)
        model = model.to(device, dtype=dtype)
        example_inputs = generate_inputs_for_model(model_cls, model, model_name, batch_size, device, include_loss_args=True)
        for attr in dir(config):
            if 'drop' in attr and isinstance(getattr(config, attr), float):
                setattr(config, attr, 1e-30)
        if hasattr(model, 'config') and hasattr(model.config, 'use_cache'):
            model.config.use_cache = False
    if self.args.enable_activation_checkpointing:
        model.gradient_checkpointing_enable()
    if is_training and (not use_eval_mode) and (not (self.args.accuracy and model_name in self._config['only_inference'])):
        model.train()
    else:
        model.eval()
    self.validate_model(model, example_inputs)
    return (device, model_name, model, example_inputs, batch_size)

@final
def _try_convert_data(self, name: Hashable, data: Series, use_dtypes: bool=True, convert_dates: bool | list[str]=True, is_axis: bool=False) -> tuple[Series, bool]:
    """
        Try to parse a Series into a column by inferring dtype.
        """
    org_data = data
    if <MASK>:
        if not self.dtype:
            if all(notna(data)):
                return (data, False)
            filled = data.fillna(np.nan)
            return (filled, True)
        elif self.dtype is True:
            pass
        elif not _should_convert_dates(convert_dates, self.keep_default_dates, name):
            dtype = self.dtype.get(name) if isinstance(self.dtype, dict) else self.dtype
            if dtype is not None:
                try:
                    return (data.astype(dtype), True)
                except (TypeError, ValueError):
                    return (data, False)
    if convert_dates:
        new_data = self._try_convert_to_date(data)
        if new_data is not data:
            return (new_data, True)
    converted = False
    if self.dtype_backend is not lib.no_default and (not is_axis):
        return (data, True)
    elif is_string_dtype(data.dtype):
        try:
            data = data.astype('float64')
            converted = True
        except (TypeError, ValueError):
            pass
    if data.dtype.kind == 'f' and data.dtype != 'float64':
        try:
            data = data.astype('float64')
            converted = True
        except (TypeError, ValueError):
            pass
    if len(data) and data.dtype in ('float', 'object'):
        try:
            new_data = org_data.astype('int64')
            if (new_data == data).all():
                data = new_data
                converted = True
        except (TypeError, ValueError, OverflowError):
            pass
    if data.dtype == 'int' and data.dtype != 'int64':
        try:
            data = data.astype('int64')
            converted = True
        except (TypeError, ValueError):
            pass
    if name == 'index' and len(data):
        if self.orient == 'split':
            return (data, False)
    return (data, converted)

def _descendants_with_paths(self):
    """Returns a list of all nodes and its paths from self.root using a breadth first traversal."""
    bfs_sorted = []
    to_visit = collections.deque([self.root])
    node_paths = object_identity.ObjectIdentityDictionary()
    node_paths[self.root] = ()
    while to_visit:
        current_trackable = to_visit.popleft()
        bfs_sorted.append(current_trackable)
        for (name, dependency) in self.children(current_trackable).items():
            if <MASK>:
                node_paths[dependency] = node_paths[current_trackable] + (base.TrackableReference(name, dependency),)
                to_visit.append(dependency)
    return (bfs_sorted, node_paths)

def _get_bin_edges(a, bins, range, weights):
    """
    Computes the bins used internally by `histogram`.

    Parameters
    ==========
    a : ndarray
        Ravelled data array
    bins, range
        Forwarded arguments from `histogram`.
    weights : ndarray, optional
        Ravelled weights array, or None

    Returns
    =======
    bin_edges : ndarray
        Array of bin edges
    uniform_bins : (Number, Number, int):
        The upper bound, lowerbound, and number of bins, used in the optimized
        implementation of `histogram` that works on uniform bins.
    """
    n_equal_bins = None
    bin_edges = None
    if isinstance(bins, str):
        bin_name = bins
        if bin_name not in _hist_bin_selectors:
            raise ValueError(f'{bin_name!r} is not a valid estimator for `bins`')
        if weights is not None:
            raise TypeError('Automated estimation of the number of bins is not supported for weighted data')
        (first_edge, last_edge) = _get_outer_edges(a, range)
        if range is not None:
            keep = a >= first_edge
            keep &= a <= last_edge
            if not np.logical_and.reduce(keep):
                a = a[keep]
        if <MASK>:
            n_equal_bins = 1
        else:
            width = _hist_bin_selectors[bin_name](a, (first_edge, last_edge))
            if width:
                if np.issubdtype(a.dtype, np.integer) and width < 1:
                    width = 1
                delta = _unsigned_subtract(last_edge, first_edge)
                n_equal_bins = int(np.ceil(delta / width))
            else:
                n_equal_bins = 1
    elif np.ndim(bins) == 0:
        try:
            n_equal_bins = operator.index(bins)
        except TypeError as e:
            raise TypeError('`bins` must be an integer, a string, or an array') from e
        if n_equal_bins < 1:
            raise ValueError('`bins` must be positive, when an integer')
        (first_edge, last_edge) = _get_outer_edges(a, range)
    elif np.ndim(bins) == 1:
        bin_edges = np.asarray(bins)
        if np.any(bin_edges[:-1] > bin_edges[1:]):
            raise ValueError('`bins` must increase monotonically, when an array')
    else:
        raise ValueError('`bins` must be 1d, when an array')
    if n_equal_bins is not None:
        bin_type = np.result_type(first_edge, last_edge, a)
        if np.issubdtype(bin_type, np.integer):
            bin_type = np.result_type(bin_type, float)
        bin_edges = np.linspace(first_edge, last_edge, n_equal_bins + 1, endpoint=True, dtype=bin_type)
        if np.any(bin_edges[:-1] >= bin_edges[1:]):
            raise ValueError(f'Too many bins for data range. Cannot create {n_equal_bins} finite-sized bins.')
        return (bin_edges, (first_edge, last_edge, n_equal_bins))
    else:
        return (bin_edges, None)

def build_inputs(parameters, sess, inputs, outputs):
    if <MASK>:
        input_values = create_tensor_data(tf.float32, parameters['input_shape'], min_value=-1, max_value=1)
    else:
        input_values = create_tensor_data(tf.float32, parameters['input_shape'])
    return ([input_values], sess.run(outputs, feed_dict=dict(zip(inputs, [input_values]))))

def _default_formatter():
    fmt = os.environ.get(LOG_FORMAT_ENV_VAR, None)
    trace_id_filter = {item.strip() for item in os.environ.get(LOG_TRACE_ID_FILTER, '').split(',') if item.strip()}
    if fmt is None:
        return TorchLogsFormatter(trace_id_filter=trace_id_filter)
    else:
        if <MASK>:
            fmt = logging.BASIC_FORMAT
        return logging.Formatter(fmt)

def emit_node(node: Node):
    maybe_type_annotation = '' if node.type is None else f' : {type_repr(node.type)}'
    maybe_comment = ''
    if verbose:
        from torch.fx.experimental.proxy_tensor import py_sym_types
        from torch.fx.passes.shape_prop import TensorMetadata
        meta_val = node.meta.get('val', node.meta.get('tensor_meta', node.meta.get('example_value', None)))

        def _tensor_annotation(t: torch.Tensor) -> str:
            stride = stringify_shape(t.stride()) if include_stride else ''
            device = f'{t.device}' if include_device else ''
            return f'{red(dtype_abbrs[t.dtype])}{blue(stringify_shape(t.shape))}{dim_blue(stride)}{dim_green(device)}'
        if isinstance(meta_val, torch.Tensor) and meta_val.layout not in (torch.sparse_csc, torch.sparse_csr):
            is_plain = type(meta_val) is torch.Tensor or isinstance(meta_val, torch._subclasses.FakeTensor)
            core = _tensor_annotation(meta_val)
            if is_plain:
                maybe_type_annotation = f': "{core}"'
            else:
                cls = meta_val.__class__.__name__
                maybe_type_annotation = f': "{cls}({core})"'
        elif isinstance(meta_val, py_sym_types):
            val_str = CodeGen._sym_repr(meta_val)
            maybe_type_annotation = f': "Sym({val_str})"'
        elif isinstance(meta_val, TensorMetadata):
            maybe_type_annotation = f': "{dtype_abbrs[meta_val.dtype]}{stringify_shape(meta_val.shape)}"'
    desc = None
    if expanded_def:
        desc = node.meta.get('desc', None)
        if desc is not None and node.op == 'placeholder':
            maybe_comment += f'  # {desc}'
    if node.op == 'placeholder':
        assert isinstance(node.target, str)
        maybe_default_arg = '' if not node.args else f' = {_get_repr(node.args[0])}'
        free_vars.append(f'{node.target}{maybe_type_annotation}{maybe_default_arg}{maybe_comment}')
        raw_name = node.target.replace('*', '')
        if raw_name != repr(node):
            body.append(f'{repr(node)} = {raw_name}\n')
        return
    elif node.op == 'call_method':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.target)}({_format_args(node.args[1:], node.kwargs)})')
        return
    elif node.op == 'call_function':
        assert callable(node.target)
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in magic_methods:
            assert isinstance(node.args, tuple)
            body.append(f'{repr(node)}{maybe_type_annotation} = {magic_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))}')
            return
        if getattr(node.target, '__module__', '') == '_operator' and node.target.__name__ in inplace_methods:
            body.append(f'{inplace_methods[node.target.__name__].format(*(_get_repr(a) for a in node.args))};  {repr(node)}{maybe_type_annotation} = {_get_repr(node.args[0])}')
            return
        qualified_name = _get_qualified_name(node.target)
        global_name = add_global(qualified_name, node.target)
        if global_name == 'getattr' and isinstance(node.args, tuple) and isinstance(node.args[1], str) and node.args[1].isidentifier() and (len(node.args) == 2):
            body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(_get_repr(node.args[0]), node.args[1])}')
            return
        body.append(f'{repr(node)}{maybe_type_annotation} = {global_name}({_format_args(node.args, node.kwargs)})')
        if <MASK>:
            wrapped_fns.setdefault(global_name)
        return
    elif node.op == 'call_module':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}({_format_args(node.args, node.kwargs)})')
        return
    elif node.op == 'get_attr':
        assert isinstance(node.target, str)
        body.append(f'{repr(node)}{maybe_type_annotation} = {_format_target(root_module, node.target)}')
        return
    elif node.op == 'output':
        if node.type is not None:
            maybe_return_annotation[0] = f' -> {type_repr(node.type)}'
        body.append(self._call_method_with_signature_check(self.generate_output, node.args[0], descs=desc if expanded_def else None))
        return
    raise NotImplementedError(f'node: {node.op} {node.target}')

def _is_framework_filename(filename):
    """Returns whether a filename should be considered a part of the framework.

  A file is part of the framework if it does not match a pattern in
  _EXTERNAL_FILENAME_PATTERNS and it either matches a pattern in
  _FRAMEWORK_FILENAME_PATTERNS or starts with a _FRAMEWORK_PATH_PREFIXES prefix.

  Args:
    filename: A filename string.

  Returns:
    Whether the filename should be considered to be internal to the
    TensorFlow framework for the purposes of reporting errors.
  """
    for pattern in _EXTERNAL_FILENAME_PATTERNS:
        if <MASK>:
            return False
    for pattern in _FRAMEWORK_FILENAME_PATTERNS:
        if pattern.search(filename):
            return True
    for prefix in _FRAMEWORK_PATH_PREFIXES:
        if filename.startswith(prefix):
            return True
    return False

@test_util.enable_control_flow_v2
def testRemoveLowerUsingSwitchMerge(self):
    with ops.Graph().as_default():
        i = array_ops.placeholder(dtype=dtypes.int32, shape=())
        c = lambda i: math_ops.less(i, 10)
        b = lambda i: math_ops.add(i, 1)
        while_loop.while_loop(c, b, [i])
        sess = session.Session()
    new_graph_def = convert_to_constants.disable_lower_using_switch_merge(sess.graph_def)
    lower_using_switch_merge_is_removed = False
    for node in new_graph_def.node:
        if node.op == 'While' or node.op == 'StatelessWhile':
            if <MASK>:
                lower_using_switch_merge_is_removed = True
    self.assertTrue(lower_using_switch_merge_is_removed)

def add_error(self, field, error):
    """
        Update the content of `self._errors`.

        The `field` argument is the name of the field to which the errors
        should be added. If it's None, treat the errors as NON_FIELD_ERRORS.

        The `error` argument can be a single error, a list of errors, or a
        dictionary that maps field names to lists of errors. An "error" can be
        either a simple string or an instance of ValidationError with its
        message attribute set and a "list or dictionary" can be an actual
        `list` or `dict` or an instance of ValidationError with its
        `error_list` or `error_dict` attribute set.

        If `error` is a dictionary, the `field` argument *must* be None and
        errors will be added to the fields that correspond to the keys of the
        dictionary.
        """
    if not isinstance(error, ValidationError):
        error = ValidationError(error)
    if hasattr(error, 'error_dict'):
        if field is not None:
            raise TypeError('The argument `field` must be `None` when the `error` argument contains errors for multiple fields.')
        else:
            error = error.error_dict
    else:
        error = {field or NON_FIELD_ERRORS: error.error_list}
    for (field, error_list) in error.items():
        if field not in self.errors:
            if <MASK>:
                raise ValueError("'%s' has no field named '%s'." % (self.__class__.__name__, field))
            if field == NON_FIELD_ERRORS:
                self._errors[field] = self.error_class(error_class='nonfield', renderer=self.renderer)
            else:
                self._errors[field] = self.error_class(renderer=self.renderer, field_id=self[field].auto_id)
        self._errors[field].extend(error_list)
        if field in self.cleaned_data:
            del self.cleaned_data[field]

def main(argv: Sequence[str]) -> None:
    if len(argv) > 1:
        raise app.UsageError('Too many command-line arguments.')
    if SPLITTER_TESTDATA_PATH.value is None:
        raise app.UsageError("'path' flag not specified.")
    levels = 4

    def make_string_tree(string_tree: test_message_pb2.StringNode, level: int=0, label: str='0') -> test_message_pb2.StringNode:
        string_tree.val = label
        if <MASK>:
            return string_tree
        for i in range(level + 1):
            make_string_tree(string_tree.child_nodes.add(), level + 1, label + str(level + 1) + str(i))
        return string_tree

    def copy_string_tree(string_tree: test_message_pb2.StringNode):
        new_tree = test_message_pb2.StringNode()
        new_tree.CopyFrom(string_tree)
        return new_tree
    string_tree = make_string_tree(test_message_pb2.StringNode())
    logging.info('StringNode tree generated:\n%s', string_tree)
    file_io.write_string_to_file(os.path.join(SPLITTER_TESTDATA_PATH.value, 'split-tree.pbtxt'), str(string_tree))
    DFStringNodeSplitter(copy_string_tree(string_tree)).write(os.path.join(SPLITTER_TESTDATA_PATH.value, 'df-split-tree'))
    BFStringNodeSplitter(copy_string_tree(string_tree)).write(os.path.join(SPLITTER_TESTDATA_PATH.value, 'bf-split-tree'))

def _remove_effect_tokens_from_graph_helper(ep, num_tokens, input_token_names, output_token_names):
    inputs_to_lifted_custom_objs = ep.graph_signature.inputs_to_lifted_custom_objs
    output_node = None
    with_effect_nodes: list[torch.fx.Node] = []
    output_node = next(reversed(ep.graph_module.graph.find_nodes(op='output')))
    for module in ep.graph_module.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue
        for node in module.graph.nodes:
            if not (node.op == 'call_function' and node.target is with_effects):
                continue
            with_effect_nodes.append(node)
    assert output_node is not None
    output_args = output_node.args[0]
    assert len(output_args) >= num_tokens
    out_token_nodes = output_args[:num_tokens]
    output_node.args = (tuple(output_args[num_tokens:]),)
    for out_token in out_token_nodes:
        assert out_token.name in output_token_names
        out_token.users.clear()
        ep.graph.erase_node(out_token)
    for node in reversed(with_effect_nodes):
        func = node.args[1]
        assert isinstance(func, (torch._ops.OpOverload, torch._ops.HigherOrderOperator))
        if func == torch.ops.higher_order.call_torchbind:
            custom_obj_meta = node.args[2].meta['val']
            assert isinstance(custom_obj_meta, CustomObjArgument)
            if <MASK>:
                custom_obj = custom_obj_meta.fake_val
            elif node.args[2].name in inputs_to_lifted_custom_objs:
                custom_obj = ep.constants[inputs_to_lifted_custom_objs[node.args[2].name]]
            else:
                raise RuntimeError(f'Unable to find custom obj for node {node}')
            schema = _get_schema(func, (custom_obj,) + node.args[3:])
        else:
            schema = _get_schema(func, node.args[2:])
        with ep.graph.inserting_before(node):
            new_node = ep.graph.call_function(func, node.args[2:], node.kwargs)
        for (k, v) in node.meta.items():
            new_node.meta[k] = v
            if k == 'unbacked_bindings':
                old_bindings = new_node.meta[k]
                new_bindings = {k: path[1:] if path else path for (k, path) in old_bindings.items()}
                new_node.meta[k] = new_bindings
        node.replace_all_uses_with(new_node)
        for user in list(new_node.users.keys()):
            assert user.target == operator.getitem
            if user.args[1] == 0:
                ep.graph.erase_node(user)
        if len(schema.returns) == 1:
            for user in list(new_node.users.keys()):
                assert user.args[1] == 1
                user.replace_all_uses_with(new_node)
            new_node.meta['val'] = node.meta['val'][1]
        elif len(schema.returns) > 1:
            for user in list(new_node.users.keys()):
                assert user.args[1] >= 1
                user.args = (user.args[0], user.args[1] - 1)
            new_node.meta['val'] = node.meta['val'][1:]
        else:
            assert len(schema.returns) == 0
            assert len(new_node.users) == 0
            new_node.meta['val'] = None
        ep.graph.erase_node(node)
    placeholders = [node for node in ep.graph.nodes if node.op == 'placeholder']
    assert len(placeholders) >= num_tokens
    inp_token_nodes = placeholders[:num_tokens]
    for inp_token in inp_token_nodes:
        assert inp_token.name in input_token_names
        ep.graph.erase_node(inp_token)
    ep.graph.eliminate_dead_code()

def preview_type_promotion(self, args: tuple, kwargs: dict) -> TypePromotionSnapshot:
    assert len(args) >= 1, f'Reduction op torch.ops.{self.namespace}.{self.op_name} expects at least one argument'
    arg = args[0]
    assert isinstance(arg, torch.Tensor), f'type(arg)={type(arg)!r} is not torch.Tensor'
    dtype: torch.dtype | None = kwargs.get('dtype')
    if dtype is None:
        if <MASK>:
            dtype = torch.int64
        else:
            dtype = arg.dtype
    return super().preview_type_promotion(args, {'dtype': dtype})

def _tensordot_axes(a, axes):
    """Generates two sets of contraction axes for the two tensor arguments."""
    a_shape = a.get_shape()
    if isinstance(axes, compat.integral_types):
        if axes < 0:
            raise ValueError(f'`axes` must be at least 0. Received: {axes}.')
        if a_shape.ndims is not None:
            if axes > a_shape.ndims:
                raise ValueError(f'`axes` must not be larger than the number of dimensions of tensor {a}.  Received {axes}, vs tensor dimensions {a_shape.ndims}.')
            return (list(builtins.range(a_shape.ndims - axes, a_shape.ndims)), list(builtins.range(axes)))
        else:
            rank = array_ops.rank(a)
            return (range(rank - axes, rank, dtype=dtypes.int32), range(axes, dtype=dtypes.int32))
    elif <MASK>:
        if len(axes) != 2:
            raise ValueError(f'`axes` must be an integer or have length 2. Received {axes}.')
        a_axes = axes[0]
        b_axes = axes[1]
        if isinstance(a_axes, compat.integral_types) and isinstance(b_axes, compat.integral_types):
            a_axes = [a_axes]
            b_axes = [b_axes]
        if len(a_axes) != len(b_axes):
            raise ValueError(f'Different number of contraction axes `a` and `b`, {len(a_axes)} != {len(b_axes)}.')
        return (a_axes, b_axes)
    else:
        axes = ops.convert_to_tensor(axes, name='axes', dtype=dtypes.int32)
        return (axes[0], axes[1])

def _override(self, func, args, kwargs):
    if torch.distributed.is_available():
        from torch.distributed._functional_collectives import REDUCE_OP_TO_STR, traceable_collective_remaps
        if func in traceable_collective_remaps:
            mapped_func = traceable_collective_remaps[func]
            signature = inspect.signature(func)
            kwargs = dict(signature.bind(*args, **kwargs).arguments)
            args = ()
            if func in (torch.distributed.all_reduce, torch.distributed.reduce_scatter_tensor, torch.distributed._reduce_scatter_base):
                if 'op' in kwargs:
                    kwargs['op'] = REDUCE_OP_TO_STR[kwargs['op']]
            return (mapped_func, args, kwargs)
    if func is torch.tensor:
        if any((isinstance(a, (torch.SymInt, torch.SymFloat, torch.SymBool)) for a in pytree.tree_flatten(args[0])[0])):
            return (torch._refs.tensor, args, kwargs)
    if func.__name__ == '__getitem__' and isinstance(args[0], torch.Tensor):

        def rewrite(dim, item):
            if item is None:
                return (dim + 1, (torch.unsqueeze, [dim]))
            if isinstance(item, (int, torch.SymInt)):
                return (dim, (torch.select, [dim, item]))
            if isinstance(item, slice):
                step = item.step or 1
                if item.start is None and item.stop is None and (step == 1):
                    return (dim + 1, (lambda t: t, []))
                return (dim + 1, (torch.ops.aten.slice, [dim, item.start, item.stop, step]))
        items = list(args[1]) if isinstance(args[1], tuple) else [args[1]]
        has_symint = False
        index_ellipsis = None
        t = args[0]
        n_none_slices = t.ndim + 1
        for (i, item) in enumerate(items):
            if isinstance(item, torch.SymInt) or (isinstance(item, slice) and any((isinstance(s, torch.SymInt) for s in (item.start, item.stop, item.step)))):
                has_symint = True
            if item is Ellipsis:
                index_ellipsis = i
            if item is not None:
                n_none_slices -= 1
        if has_symint:
            if <MASK>:
                none_slices = [slice(None)] * n_none_slices
                items[index_ellipsis:index_ellipsis + 1] = none_slices
            dim = 0
            sequence = []
            for item in items:
                if (r := rewrite(dim, item)) is None:
                    return (func, args, kwargs)
                (dim, call_spec) = r
                sequence.append(call_spec)

            def run():
                t = args[0]
                for (_method, _args) in sequence:
                    t = _method(t, *_args)
                return t
            return (run, [], {})
    return (func, args, kwargs)

def is_literal(node):
    """Tests whether node represents a Python literal."""
    if is_constant(node):
        return True
    if <MASK>:
        return True
    return False

@register_decomposition([aten.arange.start_step, aten.arange.start_out])
@out_wrapper()
def arange(start: NumberType=0, end: Optional[NumberType]=None, step: NumberType=1, *, dtype: Optional[torch.dtype]=None, layout: torch.layout=torch.strided, device: Optional[DeviceLikeType]=None, pin_memory: bool=False, requires_grad: bool=False) -> TensorLikeType:
    utils.check_layout(layout)
    utils.check_pin_memory(pin_memory)
    device = torch.device(utils.device_or_default(device))
    assert not isinstance(start, complex)
    assert not isinstance(end, complex)
    assert not isinstance(step, complex)
    if end is None:
        end = start
        start = 0
    torch._check(step != 0, lambda : 'step must be nonzero')
    if step > 0:
        torch._check(end >= start, lambda : 'upper bound and lower bound inconsistent with step sign')
    elif <MASK>:
        torch._check(end <= start, lambda : 'upper bound and lower bound inconsistent with step sign')

    def is_finite(x):
        return not isinstance(x, FloatWithoutSymFloat) or math.isfinite(x)
    torch._check(is_finite(start) and is_finite(end), lambda : f'unsupported range: {start} -> {end}')
    torch._check(is_finite(step), lambda : f'step must be finite but got {step}')
    args = (start, end, step)
    integer_args = builtins.all((isinstance(arg, IntLike) for arg in args))
    if dtype is None:
        dtype = torch.int64 if integer_args else torch.get_default_dtype()
    is_integer = utils.is_integer_dtype(dtype)
    if is_integer or integer_args:
        xstart = sym_int(start)
        xend = sym_int(end)
        xstep = sym_int(step)
    if dtype == torch.int64 or integer_args:
        sgn = bool(xstep > 0) - bool(xstep < 0)
        length = (xend - xstart + xstep - sgn) // xstep
    else:
        length = math.ceil((end - start) / step)
    if is_integer:
        return prims.iota(length, start=xstart, step=xstep, dtype=dtype, device=device, requires_grad=requires_grad)
    index = prims.iota(length, start=0, step=1, dtype=torch.int64, device=device, requires_grad=False)
    computation_dtype = torch.long if integer_args else utils.get_acc_type(dtype, device)
    index = _maybe_convert_to_dtype(index, computation_dtype)
    result = start + step * index
    result = _maybe_convert_to_dtype(result, dtype)
    if requires_grad:
        result.requires_grad_(True)
    return result

