@register_graph_pattern(CallFunction(torch.cat, getitem_split, dim=Ignored(), _users=MULTIPLE), pass_dict=construct_pattern_matcher_pass('merge_getitem_cat_pass'))
def merge_getitem_cat(match: Match, split_sections: list[int], dim: int):
    if not isinstance(split_sections, (list, tuple)):
        return
    graph = match.graph
    split_node = next((node for node in match.nodes if node.target == torch.split))
    (split_input, _split_size, split_dim) = _get_split_args_default(split_node)
    next_users = find_next_users(split_node)
    split_sections = list(split_sections)
    for cat_user in next_users:
        if cat_user.target == torch.cat:
            cat_dim = get_arg_value(cat_user, 1, 'dim')
            if split_dim != cat_dim or not has_same_parent_node(cat_user) or (not all((len(arg.users) == 1 for arg in cat_user.args[0]))):
                continue
            indices = [arg.args[1] for arg in cat_user.args[0]]
            if <MASK>:
                continue
            cat_user.update_arg(0, cat_user.args[0][0])
            fused_tensor_size = 0
            for i in range(len(split_node.args[1])):
                if i in indices:
                    fused_tensor_size += split_node.args[1][i]
            split_sections[indices[0]] = calculate_fused_tensor_size(split_node, indices)
            for i in indices[1:]:
                split_sections[i] = 0
            (new_split_sections, index_mapping) = remove_zeros(split_sections)
            with graph.inserting_after(split_node):
                new_split_node = graph.call_function(torch.split, args=(split_input, split_sections), kwargs={'dim': split_dim})
                split_node.replace_all_uses_with(new_split_node)
                new_split_node.meta.update(split_node.meta)
                to_remove = [cat_user]
                new_split_getitem_nodes = list(new_split_node.users.keys())
                for getitem_node in new_split_getitem_nodes:
                    if getitem_node.args[1] in indices[1:]:
                        to_remove.append(getitem_node)
                    elif getitem_node.args[1] == indices[0]:
                        cat_user.replace_all_uses_with(getitem_node)
                        getitem_node.meta.update(cat_user.meta)
                    else:
                        getitem_node.update_arg(1, index_mapping[getitem_node.args[1]])
                graph.erase_node(split_node)
                for getitem_node in to_remove:
                    graph.erase_node(getitem_node)
                new_split_node.update_arg(1, new_split_sections)
                split_node = new_split_node
                split_sections = new_split_sections
                counters[backend]['merge_getitem_cat_pass'] += 1

def process_locale_dir(self, locale_dir, files):
    """
        Extract translatable literals from the specified files, creating or
        updating the POT file for a given locale directory.

        Use the xgettext GNU gettext utility.
        """
    build_files = []
    for translatable in files:
        if self.verbosity > 1:
            self.stdout.write('processing file %s in %s' % (translatable.file, translatable.dirpath))
        if self.domain not in ('djangojs', 'django'):
            continue
        build_file = self.build_file_class(self, self.domain, translatable)
        try:
            build_file.preprocess()
        except UnicodeDecodeError as e:
            self.stdout.write('UnicodeDecodeError: skipped file %s in %s (reason: %s)' % (translatable.file, translatable.dirpath, e))
            continue
        except BaseException:
            for build_file in build_files:
                build_file.cleanup()
            raise
        build_files.append(build_file)
    if self.domain == 'djangojs':
        args = ['xgettext', '-d', self.domain, '--language=JavaScript', '--keyword=gettext_noop', '--keyword=gettext_lazy', '--keyword=ngettext_lazy:1,2', '--keyword=pgettext:1c,2', '--keyword=npgettext:1c,2,3', '--output=-']
    elif <MASK>:
        args = ['xgettext', '-d', self.domain, '--language=Python', '--keyword=gettext_noop', '--keyword=gettext_lazy', '--keyword=ngettext_lazy:1,2', '--keyword=pgettext:1c,2', '--keyword=npgettext:1c,2,3', '--keyword=pgettext_lazy:1c,2', '--keyword=npgettext_lazy:1c,2,3', '--output=-']
    else:
        return
    input_files = [bf.work_path for bf in build_files]
    with NamedTemporaryFile(mode='w+') as input_files_list:
        input_files_list.write('\n'.join(input_files))
        input_files_list.flush()
        args.extend(['--files-from', input_files_list.name])
        args.extend(self.xgettext_options)
        (msgs, errors, status) = popen_wrapper(args)
    if errors:
        if status != STATUS_OK:
            for build_file in build_files:
                build_file.cleanup()
            raise CommandError('errors happened while running xgettext on %s\n%s' % ('\n'.join(input_files), errors))
        elif self.verbosity > 0:
            self.stdout.write(errors)
    if msgs:
        if locale_dir is NO_LOCALE_DIR:
            for build_file in build_files:
                build_file.cleanup()
            file_path = os.path.normpath(build_files[0].path)
            raise CommandError("Unable to find a locale path to store translations for file %s. Make sure the 'locale' directory exists in an app or LOCALE_PATHS setting is set." % file_path)
        for build_file in build_files:
            msgs = build_file.postprocess_messages(msgs)
        potfile = os.path.join(locale_dir, '%s.pot' % self.domain)
        write_pot_file(potfile, msgs)
    for build_file in build_files:
        build_file.cleanup()

def _savez(file, args, kwds, compress, allow_pickle=True, pickle_kwargs=None):
    import zipfile
    if not hasattr(file, 'write'):
        file = os.fspath(file)
        if not file.endswith('.npz'):
            file = file + '.npz'
    namedict = kwds
    for (i, val) in enumerate(args):
        key = 'arr_%d' % i
        if key in namedict.keys():
            raise ValueError(f'Cannot use un-named variables and keyword {key}')
        namedict[key] = val
    if <MASK>:
        compression = zipfile.ZIP_DEFLATED
    else:
        compression = zipfile.ZIP_STORED
    zipf = zipfile_factory(file, mode='w', compression=compression)
    try:
        for (key, val) in namedict.items():
            fname = key + '.npy'
            val = np.asanyarray(val)
            with zipf.open(fname, 'w', force_zip64=True) as fid:
                format.write_array(fid, val, allow_pickle=allow_pickle, pickle_kwargs=pickle_kwargs)
    finally:
        zipf.close()

def require_backend_is_available(backends):

    def check(backend):
        if <MASK>:
            return dist.is_gloo_available()
        if backend == dist.Backend.NCCL:
            return dist.is_nccl_available()
        if backend == dist.Backend.MPI:
            return dist.is_mpi_available()
        if backend == dist.Backend.UCC:
            return dist.is_ucc_available()
        if backend in DistTestCases.backend_feature['plugin']:
            return True
        return False
    if BACKEND not in backends:
        return skip_but_pass_in_sandcastle(f'Test requires backend {BACKEND} to be one of {backends}')
    if not check(dist.Backend(BACKEND)):
        return skip_but_pass_in_sandcastle(f'Test requires backend {BACKEND} to be available')
    return lambda func: func

def add_fields(self, form, index):
    """A hook for adding extra fields on to each form instance."""
    initial_form_count = self.initial_form_count()
    if <MASK>:
        if index is not None and index < initial_form_count:
            form.fields[ORDERING_FIELD_NAME] = IntegerField(label=_('Order'), initial=index + 1, required=False, widget=self.get_ordering_widget())
        else:
            form.fields[ORDERING_FIELD_NAME] = IntegerField(label=_('Order'), required=False, widget=self.get_ordering_widget())
    if self.can_delete and (self.can_delete_extra or (index is not None and index < initial_form_count)):
        form.fields[DELETION_FIELD_NAME] = BooleanField(label=_('Delete'), required=False, widget=self.get_deletion_widget())

def output_hash(self, user_settings, default_settings, **options):
    output = []
    for key in sorted(user_settings):
        if <MASK>:
            output.append('%s = %s  ###' % (key, user_settings[key]))
        elif user_settings[key] != default_settings[key]:
            output.append('%s = %s' % (key, user_settings[key]))
        elif options['all']:
            output.append('### %s = %s' % (key, user_settings[key]))
    return output

def guess_path(package_root):
    if 'bazel-out' in sys.argv[0] and package_root in sys.argv[0]:
        package_root_base = sys.argv[0][:sys.argv[0].rfind(package_root)]
        binary = os.environ['TEST_TARGET'][2:].replace(':', '/', 1)
        possible_path = os.path.join(package_root_base, package_root, binary)
        logging.info('Guessed test binary path: %s', possible_path)
        if <MASK>:
            return possible_path
        return None

def __eq__(self, other):
    a = self()
    b = other()
    if <MASK>:
        return hash(a) == hash(b)
    return self is other

def sample_inputs_sparse_elementwise_binary_operation(op_info, device, dtype, requires_grad, layout, **kwargs):
    """Sample inputs for elementwise binary operations on sparse tensors.

    The samples include regular, zero-sized, batched, and hybrid
    sparse tensors as well as rhs scalars. All tensors are full tensors.
    """

    def _to_sparse(tensor, **kwargs):
        return tensor.detach().to_sparse(**kwargs).requires_grad_(requires_grad)
    for sample_input in generate_elementwise_binary_tensors(op_info, device=device, dtype=dtype, requires_grad=requires_grad, exclude_zero=True, **kwargs):
        (lhs, rhs) = (sample_input.input, sample_input.args[0])
        min_dense_dim = 0
        max_dense_dim = lhs.ndim - 1
        if layout in {torch.sparse_csr, torch.sparse_csc, torch.sparse_bsr, torch.sparse_bsc}:
            if lhs.ndim < 2:
                continue
            max_dense_dim = lhs.ndim - 2
        for dense_dim in range(min_dense_dim, max_dense_dim + 1):
            if <MASK>:
                blocksizes = [(1, 1)]
                if lhs.numel() > 0:
                    blocksizes.append((lhs.shape[lhs.ndim - 2 - dense_dim], lhs.shape[lhs.ndim - 1 - dense_dim]))
            else:
                blocksizes = [None]
            for blocksize in blocksizes:
                to_sparse_kwargs = dict(layout=layout, dense_dim=dense_dim, blocksize=blocksize)
                lhs_sparse = _to_sparse(lhs, **to_sparse_kwargs)
                rhs_sparse = _to_sparse(rhs, **to_sparse_kwargs)
                yield SampleInput(lhs_sparse, args=(rhs_sparse, *sample_input.args[1:]), kwargs=sample_input.kwargs)
                yield SampleInput(lhs_sparse, args=(make_tensor((), dtype=dtype, device=device, requires_grad=requires_grad), *sample_input.args[1:]), kwargs=sample_input.kwargs)

def forward_shape(self, shape):
    if len(shape) < len(self.in_shape):
        raise ValueError('Too few dimensions on input')
    cut = len(shape) - len(self.in_shape)
    if <MASK>:
        raise ValueError(f'Shape mismatch: expected {shape[cut:]} but got {self.in_shape}')
    return shape[:cut] + self.out_shape

def gen_registration_headers(backend_index: BackendIndex, per_operator_headers: bool, rocm: bool) -> list[str]:
    if <MASK>:
        headers = ['#include <ATen/ops/as_strided_native.h>']
    else:
        headers = ['#include <ATen/NativeFunctions.h>']
    if backend_index.dispatch_key in (DispatchKey.CPU, DispatchKey.Meta):
        headers.append('#include <ATen/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.CUDA:
        if rocm:
            headers.append('#include <ATen/hip/EmptyTensor.h>')
        else:
            headers.append('#include <ATen/cuda/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.MPS:
        headers.append('#include <ATen/mps/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.XPU:
        headers.append('#include <ATen/xpu/EmptyTensor.h>')
    elif backend_index.dispatch_key == DispatchKey.MTIA:
        headers.append('#include <ATen/native/mtia/EmptyTensor.h>')
    elif per_operator_headers:
        headers += ['#include <ATen/ops/empty.h>', '#include <ATen/ops/empty_strided.h>', '#include <ATen/ops/_copy_from_and_resize.h>', '#include <ATen/ops/_copy_from.h>']
    else:
        headers.append('#include <ATen/Functions.h>')
    headers.append('#include <c10/macros/Macros.h>')
    return headers

def convert_placeholder_to_const(input_graph_def, nodes_to_convert=None):
    """Rename the PlaceHolderWithDefault node to constant

  In a frozen graph, PlaceholderWithDefault nodes can be converted to
  Constant op nodes with same value. This will help simplify the graph.

  Args:
    input_graph_def: A GraphDef containing a model.
    nodes_to_convert: A list of PlaceholderWithDefault or Placeholder nodes to
      be converted to Constants with their new value.

  Returns:
    modified graph with PlaceholderWithDefault node converted to Constant node
  """
    input_node_map = {}
    for node in input_graph_def.node:
        if node.name not in input_node_map:
            input_node_map[node.name] = node
        else:
            raise ValueError('Duplicate node names detected for ', node.name)
    dict_to_change = {}
    for key in PLACEHOLDER_WITH_DEFAULT_LIST:
        dict_to_change[key] = PLACEHOLDER_WITH_DEFAULT_LIST[key]
    if <MASK>:
        dict_list = parse_nodes_dict(nodes_to_convert)
        dict_to_change.update(dict_list)
    ph_node_list = []
    for ph_node in dict_to_change:
        if not ph_node and ph_node not in input_node_map:
            continue
        ph_node_list.append(ph_node)
    if not ph_node_list:
        tf_logging.warning('No PlaceholderWithDefault nodes found to convert to Constant. Maybe check the spellings')
        return input_graph_def
    result_graph_def = graph_pb2.GraphDef()
    for node in input_graph_def.node:
        is_replaced = False
        new_node = node_def_pb2.NodeDef()
        if node.op == 'PlaceholderWithDefault' or node.op == 'Placeholder':
            match_key = [find_key for find_key in dict_to_change.keys() if find_key in node.name]
            if len(match_key) > 0:
                if dtypes.bool.as_datatype_enum == node.attr['dtype'].type:
                    new_val_str = dict_to_change[match_key[0]]
                    new_node.op = 'Const'
                    new_node.name = node.name
                    new_node.attr['dtype'].CopyFrom(node.attr['dtype'])
                    new_node.attr['value'].CopyFrom(attr_value_pb2.AttrValue(tensor=tensor_util.make_tensor_proto(strtobool(new_val_str), dtype=dtypes.bool, shape=[])))
                    is_replaced = True
                else:
                    tf_logging.warning('Not converting to Const. Currently only bool             PlaceholderWithDefault or Placeholder can be converted to const.             current dtype = ', node.attr['dtype'])
        if not is_replaced:
            new_node.CopyFrom(node)
        result_graph_def.node.extend([new_node])
    return result_graph_def

def schedule_fn(step: int) -> ProfilerAction:
    assert step >= 0
    if step < skip_first:
        return ProfilerAction.NONE
    else:
        step -= skip_first
    if skip_first_wait != 0:
        step += wait
    num_steps = wait + warmup + active
    if <MASK>:
        return ProfilerAction.NONE
    mod_step = step % num_steps
    if mod_step < wait:
        return ProfilerAction.NONE
    elif mod_step < wait + warmup:
        return ProfilerAction.WARMUP
    else:
        return ProfilerAction.RECORD if mod_step < num_steps - 1 else ProfilerAction.RECORD_AND_SAVE

def init_optimizer(self, name, device, params):
    if device == 'cuda' and self.args.training and (name not in CI_SKIP_OPTIMIZER):
        if <MASK>:
            self.optimizer = torch.optim.SGD(params, lr=0.01, foreach=True)
            self.optimizer.step = torch._dynamo.disable(self.optimizer.step)
        else:
