    else:
        self.optimizer = None

def fit_intercept_only(self, y_true, sample_weight=None):
    """Compute raw_prediction of an intercept-only model.

        This can be used as initial estimates of predictions, i.e. before the
        first iteration in fit.

        Parameters
        ----------
        y_true : array-like of shape (n_samples,)
            Observed, true target values.
        sample_weight : None or array of shape (n_samples,)
            Sample weights.

        Returns
        -------
        raw_prediction : numpy scalar or array of shape (n_classes,)
            Raw predictions of an intercept-only model.
        """
    y_pred = np.average(y_true, weights=sample_weight, axis=0)
    eps = 10 * np.finfo(y_pred.dtype).eps
    if self.interval_y_pred.low == -np.inf:
        a_min = None
    elif self.interval_y_pred.low_inclusive:
        a_min = self.interval_y_pred.low
    else:
        a_min = self.interval_y_pred.low + eps
    if <MASK>:
        a_max = None
    elif self.interval_y_pred.high_inclusive:
        a_max = self.interval_y_pred.high
    else:
        a_max = self.interval_y_pred.high - eps
    if a_min is None and a_max is None:
        return self.link.link(y_pred)
    else:
        return self.link.link(np.clip(y_pred, a_min, a_max))

def _get_type_from_str(type_str: str) -> ir.TensorType | ir.SequenceType | ir.OptionalType:
    """Converter a type_str from ONNX Opschema to ir.TypeProtocol.

    A type str has the form of "tensor(float)" or composite type like "seq(tensor(float))".
    """
    striped = type_str.rstrip(')')
    type_parts = striped.split('(')
    dtype = ir.DataType[type_parts[-1].upper()]
    type_: ir.TypeProtocol = ir.TensorType(ir.DataType.UNDEFINED)
    for type_part in reversed(type_parts[:-1]):
        if type_part == 'tensor':
            type_ = ir.TensorType(dtype)
        elif type_part == 'seq':
            type_ = ir.SequenceType(type_)
        elif <MASK>:
            type_ = ir.OptionalType(type_)
        else:
            raise ValueError(f"Unknown type part: '{type_part}' in type '{type_str}'")
    return type_

def run_impl(self, use_fuser):
    warmups = 10
    if <MASK>:
        iters = 1000
    else:
        iters = 10
    engine = tensor_engine.get_engine()
    self.bm_jit = None
    for i in range(warmups + iters):
        if i == warmups:
            if self.device == 'cuda':
                engine.sync_cuda()
            time_start = time.time()
        if i == 0:
            if self.jit_mode == 'trace' and use_fuser:
                self.bm_jit = torch.jit.trace(self.forward, example_inputs=self.inputs, check_trace=False)
            if callable(getattr(self, 'reference', None)):
                self.check()
            else:
                print('Warning: no reference result for ', self.module())
        elif i == 1:
            if self.jit_mode == 'trace' and use_fuser and self.print_ir:
                print(self.bm_jit.graph_for(*self.inputs))
        z = self.compute()
        if self.mode == 'both':
            if self.result_grad is None:
                self.result_grad = engine.rand_like(z)
            engine.backward([z], [self.result_grad], self.grad_variables)
    if self.device == 'cuda':
        engine.sync_cuda()
    duration = time.time() - time_start
    iter_time = duration / iters
    memory_workload = self.memory_workload()
    compute_workload = self.compute_workload()
    result_dict = {'desc': self.desc(), 'us': iter_time * 1000000.0, 'sol': memory_workload['sol'] * self.dtype_to_bytes() / iter_time / 1000000000.0, 'algorithmic': memory_workload['algorithmic'] * self.dtype_to_bytes() / iter_time / 1000000000.0}
    if compute_workload:
        result_dict['compute_workload'] = compute_workload / iter_time / 1000000000.0
    self.dump_result(result_dict)

