def benchmark_compiled_module(self, output):

    def add_fake_input(name, shape, stride, device, dtype):
        output.writeline(f"{name} = rand_strided({self.codegen_python_shape_tuple(shape)}, {self.codegen_python_shape_tuple(stride)}, device='{device}', dtype={dtype})")

    def add_expr_input(name, val):
        output.writeline(f'{name} = {val}')

    def add_torchbind_input(name, value):
        import pickle
        assert isinstance(value, torch.ScriptObject)
        output.writeline(f'{name} = pickle.loads({pickle.dumps(value)!r})')
    output.writelines(['', '', 'def benchmark_compiled_module(times=10, repeat=10):'])
    with output.indent():
        output.splice('\n                from torch._dynamo.testing import rand_strided\n                from torch._inductor.utils import print_performance\n                ', strip=True)
        for (name, value) in V.graph.constants.items():
            output.writeline(f'global {name}')
            add_fake_input(name, value.size(), value.stride(), value.device, value.dtype)
        if len(V.graph.torchbind_constants) > 0:
            output.writeline('import pickle')
            for (name, torchbind_obj) in V.graph.torchbind_constants.items():
                output.writeline(f'global {name}')
                add_torchbind_input(name, torchbind_obj)
        for (name, value) in V.graph.graph_inputs.items():
            if isinstance(value, sympy.Symbol) and isinstance(V.graph.sizevars.var_to_val.get(value, None), SingletonInt):
                continue
            if <MASK>:
                if len(V.graph.torchbind_constants) == 0:
                    output.writeline('import pickle')
                output.writeline(f'global {name}')
                add_torchbind_input(name, value.get_real_obj())
            elif isinstance(value, sympy.Expr):
                add_expr_input(name, V.graph.sizevars.size_hint(value, fallback=42))
            elif isinstance(value, ir.GeneratorState):
                add_expr_input(name, f'torch.cuda.default_generators[{value.device.index}].graphsafe_get_state()')
            else:
                shape = [V.graph.sizevars.size_hint(x, fallback=42) for x in value.get_size()]
                stride = [V.graph.sizevars.size_hint(x, fallback=42) for x in value.get_stride()]
                add_fake_input(name, shape, stride, value.get_device(), value.get_dtype())
        call_str = f"call([{', '.join(V.graph.graph_inputs.keys())}])"
        output.writeline(f'fn = lambda: {call_str}')
        output.writeline('return print_performance(fn, times=times, repeat=repeat)')

def __getattr__(self, name: str) -> Any:
    REPLACEMENT = {'and_': z3.And, 'or_': z3.Or, 'not_': z3.Not, 'bitwise_and': self._ops.bitwise_and, 'bitwise_or': self._ops.bitwise_or, 'lshift': self._ops.lshift, 'rshift': self._ops.rshift, 'floor': self._ops.floor, 'ceil': self._ops.ceil, 'minimum': self._ops.min, 'maximum': self._ops.max}
    if name in REPLACEMENT:
        return REPLACEMENT[name]
    if <MASK>:
        return getattr(operator, name)
    raise AttributeError(f'unhandled operator: {name}')

def _parse_visible_devices() -> Union[list[int], list[str]]:
    """Parse CUDA_VISIBLE_DEVICES environment variable."""
    var = os.getenv('CUDA_VISIBLE_DEVICES')
    if torch.version.hip:
        hip_devices = os.getenv('HIP_VISIBLE_DEVICES')
        rocr_devices = os.getenv('ROCR_VISIBLE_DEVICES')
        if rocr_devices is not None:
            rocr_count = len(rocr_devices.split(','))
            if hip_devices is not None:
                if len(hip_devices.split(',')) > rocr_count:
                    raise RuntimeError('HIP_VISIBLE_DEVICES contains more devices than ROCR_VISIBLE_DEVICES')
                var = hip_devices
            else:
                return list(range(rocr_count))
        elif hip_devices is not None:
            var = hip_devices
    if var is None:
        return list(range(64))

    def _strtoul(s: str) -> int:
        """Return -1 or positive integer sequence string starts with."""
        if not s:
            return -1
        for (idx, c) in enumerate(s):
            if not (c.isdigit() or (idx == 0 and c in '+-')):
                break
            if idx + 1 == len(s):
                idx += 1
        return int(s[:idx]) if idx > 0 else -1

    def parse_list_with_prefix(lst: str, prefix: str) -> list[str]:
        rcs: list[str] = []
        for elem in lst.split(','):
            if elem in rcs:
                return cast(list[str], [])
            if not elem.startswith(prefix):
                break
            rcs.append(elem)
        return rcs
    if var.startswith('GPU-'):
        return parse_list_with_prefix(var, 'GPU-')
    if var.startswith('MIG-'):
        return parse_list_with_prefix(var, 'MIG-')
    rc: list[int] = []
    for elem in var.split(','):
        x = _strtoul(elem.strip())
        if x in rc:
            return cast(list[int], [])
        if <MASK>:
            break
        rc.append(x)
    return rc

def _maybe_change_to_function_call(self, parent, node, full_name):
    """Wraps node (typically, an Attribute or Expr) in a Call."""
    if full_name in self._api_change_spec.change_to_function:
        if <MASK>:
            new_node = ast.Call(node, [], [])
            pasta.ast_utils.replace_child(parent, node, new_node)
            ast.copy_location(new_node, node)
            self.add_log(INFO, node.lineno, node.col_offset, 'Changed %r to a function call' % full_name)
            return True
    return False

def call_method(self, tx: 'InstructionTranslator', name, args: 'list[VariableTracker]', kwargs: 'dict[str, VariableTracker]') -> 'VariableTracker':
    if name == '__setattr__':
        return super().call_method(tx, name, args, kwargs)
    elif name == 'mark_non_differentiable':
        if <MASK>:
            raise_args_mismatch(tx, name, '0 kwargs', f'{len(kwargs)} kwargs')
        self.non_differentiable = proxy_args_kwargs(args, {})[0]
        return variables.ConstantVariable.create(None)
    if name != 'save_for_backward':
        unimplemented_v2(gb_type='Unsupported autograd.Function context method', context=f'call_method {self} {name}', explanation=f'Dynamo does not support calling the method `{name}` on `autograd.Function` context objects. Supported methods are `__setattr__`, `save_for_backward` and `mark_non_differentiable`.', hints=[*graph_break_hints.SUPPORTABLE])
    if self.saved_tensors is None:
        unimplemented_v2(gb_type='Unsupported autograd.Function context `save_for_backward`', context=f'call_method {self} {name}', explanation='Dynamo requires the `saved_tensors` attribute to be initialized on the `autograd.Function` context object.', hints=['Ensure that the `saved_tensors` attribute is properly initialized before calling `save_for_backward`. `save_for_backward` only supported on a newly constructed `torch.autograd.function.FunctionCtx`.'])
    if not self.inference:
        if kwargs or not self.source:
            raise_type_error_exc(tx, 'save_for_backward() requires a source and no keyword arguments')
        tx.output.side_effects.track_save_for_backward(self, args)
    if len(self.saved_tensors.tensors) > 0:
        self.saved_tensors.tensors = []
    for arg in args:
        self.saved_tensors.tensors.append(arg)
    return variables.ConstantVariable.create(None)

def _extract_graph_with_inputs_outputs(joint_graph: fx.Graph, inputs: list[fx.Node], outputs: list[fx.Node], outputs_descs: list[AOTOutput], subgraph: Optional[str]=None) -> fx.Graph:
    """
    Given a graph, extracts out a subgraph that takes the specified nodes as
    inputs and returns the specified outputs.

    This includes specifying non-placeholder nodes as inputs.

    The general strategy is to initialize all inputs with proxies as we
    encounter them, and trace through the graph, only keeping values which take
    in valid proxies. Then, all dead code is eliminated.
    """
    new_graph = fx.Graph()
    env = {}
    for node in inputs:
        new_node = new_graph.placeholder(node.name)
        new_node.meta = node.meta
        env[node] = new_node
    for node in joint_graph.nodes:
        if _must_be_in_backward(node) and subgraph != 'backward' and (node not in inputs):
            env[node] = InvalidNode
            continue
        if _must_be_in_forward(node) and subgraph != 'forward' and (node not in inputs):
            env[node] = InvalidNode
            continue
        if node in env:
            continue
        elif node.op == 'placeholder':
            env[node] = InvalidNode
        elif node.op == 'call_function':
            all_args = pytree.arg_tree_leaves(*node.args, **node.kwargs)
            all_args = [isinstance(env[x], InvalidNodeBase) for x in all_args if isinstance(x, fx.Node)]
            if any(all_args):
                env[node] = InvalidNode
                continue
            env[node] = new_graph.node_copy(node, lambda x: env[x])
        elif node.op == 'get_attr':
            env[node] = new_graph.node_copy(node, lambda x: env[x])
        elif <MASK>:
            pass
    output_values = []
    for x in outputs:
        if isinstance(x, fx.Node):
            if x not in env:
                raise RuntimeError(f"Node {x} couldn't be found in env")
            assert not isinstance(env[x], InvalidNodeBase), f'Node {x} was invalid, but is output'
            output_values.append(env[x])
        else:
            output_values.append(x)
    out = new_graph.output(tuple(output_values))
    out.meta['desc'] = outputs_descs
    new_graph.eliminate_dead_code()
    new_graph.lint()
    return new_graph

def reduce(self, operation, app_label):
    if isinstance(operation, FieldOperation) and self.is_same_field_operation(operation):
        if isinstance(operation, AlterField):
            return [replace(self, name=operation.name, field=operation.field)]
        elif <MASK>:
            return []
        elif isinstance(operation, RenameField):
            return [replace(self, name=operation.new_name)]
    return super().reduce(operation, app_label)

def _maybe_make_input_output_share_observers(node: Node, model: torch.nn.Module, named_modules: dict[str, torch.nn.Module]) -> bool:
    """
    Ensures that we share an observer
    for all input arguments as well as the output argument. In detail, given
    a graph of

      x0 -> obs0 -> op -> x2
                  /
      x1 -> obs1 /

    where node obs0 points to observer instance observer0,
    obs1 points to observer1 and obs2 points to observer2, we make nodes obs1
    and ob2 point to observer0.
    Returns: whether the operation succeeded or not
    """
    first_arg = None
    for i in range(len(node.args)):
        if isinstance(node.args[i], (Node, list, tuple)):
            first_arg = node.args[i]
            break
    if first_arg is None:
        return False
    if isinstance(first_arg, (list, tuple)):
        first_arg_arg = first_arg[0]
    elif isinstance(first_arg, Node):
        first_arg_arg = first_arg
    else:
        return False
    iteration_guard = 0
    while not _is_activation_post_process_node(first_arg_arg, named_modules):
        if not isinstance(first_arg_arg, Node):
            return False
        if first_arg_arg.op == 'placeholder':
            return False
        trace_back_node = None
        for i in range(len(first_arg_arg.args)):
            trace_back_node = first_arg_arg.args[i]
            if isinstance(trace_back_node, Node):
                break
        if trace_back_node is None:
            return False
        first_arg_arg = trace_back_node
        iteration_guard += 1
        if <MASK>:
            raise AssertionError('Unable to find observer of previous node')
    assert isinstance(first_arg_arg, Node)
    target_to_use = first_arg_arg.target
    assert isinstance(target_to_use, str)
    obs_mod_to_use = named_modules[target_to_use]
    if isinstance(first_arg, (list, tuple)):
        for (input_idx, input_arg) in enumerate(first_arg):
            if input_idx == 0:
                continue
            iteration_guard = 0
            while not _is_activation_post_process_node(input_arg, named_modules):
                if len(input_arg.args) < 1:
                    return False
                input_arg = input_arg.args[0]
                iteration_guard += 1
                if iteration_guard > 10000:
                    raise AssertionError('Unable to find observer of previous node')
            (parent_name, name) = _parent_name(input_arg.target)
            setattr(named_modules[parent_name], name, obs_mod_to_use)
    for output_obs_node in node.users.keys():
        assert _is_activation_post_process_node(output_obs_node, named_modules)
        (parent_name, name) = _parent_name(output_obs_node.target)
        setattr(named_modules[parent_name], name, obs_mod_to_use)
    return True

def _deprecate_y_pred_parameter(y_score, y_pred, version):
    """Deprecate `y_pred` in favour of of `y_score`."""
    version = parse_version(version)
    version_remove = f'{version.major}.{version.minor + 2}'
    if <MASK>:
        raise ValueError(f'`y_pred` and `y_score` cannot be both specified. Please use `y_score` only as `y_pred` was deprecated in {version} and will be removed in {version_remove}.')
    if not (isinstance(y_pred, str) and y_pred == 'deprecated'):
        warnings.warn(f'y_pred was deprecated in {version} and will be removed in {version_remove}. Please use `y_score` instead.', FutureWarning)
        return y_pred
    return y_score

