def __call__(self, frame: DynamoFrameType, cache_entry: Optional[CacheEntry], frame_state: dict[str, Union[int, FrameStateSizeEntry]]) -> ConvertFrameReturn:
    assert frame_state is not None
    input_codes.add(frame.f_code)
    is_skipfile = trace_rules.check(frame.f_code)
    if sys.version_info >= (3, 13):
        has_started_execution = frame.f_lasti > first_real_inst_idx(frame.f_code)
    else:
        has_started_execution = frame.f_lasti >= first_real_inst_idx(frame.f_code)
    if has_started_execution or is_skipfile or config.disable or (should_skip_due_to_torch_dispatch_mode() and (not getattr(self._torchdynamo_orig_backend, '_export', False))):
        if log.isEnabledFor(logging.DEBUG):
            if has_started_execution:
                skip_reason = 'traced frame already'
            elif trace_rules.check(frame.f_code):
                skip_reason = 'in skipfiles'
            elif is_in_torch_dispatch_mode(include_infra_modes=False):
                skip_reason = 'non-infra torch dispatch mode present, this is not supported today in torch.compile'
            else:
                skip_reason = 'dynamo tracing is disabled'
            log.debug('skipping: %s (reason: %s, file: %s)', frame.f_code.co_name, skip_reason, frame.f_code.co_filename)
        return ConvertFrameReturn()
    if frame.f_code.co_filename == '<string>' and frame.f_code.co_name == '__new__' or (frame.f_code.co_filename.endswith('collections/__init__.py') and frame.f_code.co_name == '_make'):
        return ConvertFrameReturn()
    if <MASK>:
        ddp_module = DistributedDataParallel._get_active_ddp_module()
        if ddp_module:
            with compile_lock:
                from torch._dynamo.backends.distributed import DDPOptimizer
                ddp_optimizer = DDPOptimizer(bucket_bytes_cap=ddp_module.bucket_bytes_cap, backend_compile_fn=self._torchdynamo_orig_backend._torchdynamo_orig_backend)
                assert hasattr(self._torchdynamo_orig_backend, '_clone_with_backend'), 'DDPOptimizer only supports callback fns that know how to clone themselves.'
                hijacked_callback = self._torchdynamo_orig_backend._clone_with_backend(ddp_optimizer.compile_fn)
                return hijacked_callback(frame, cache_entry, self.hooks, frame_state)
    with compile_lock, _disable_current_modes():
        result = self._torchdynamo_orig_backend(frame, cache_entry, self.hooks, frame_state, skip=1)
        return result

def __init__(self, message, code=None, params=None):
    """
        The `message` argument can be a single error, a list of errors, or a
        dictionary that maps field names to lists of errors. What we define as
        an "error" can be either a simple string or an instance of
        ValidationError with its message attribute set, and what we define as
        list or dictionary can be an actual `list` or `dict` or an instance
        of ValidationError with its `error_list` or `error_dict` attribute set.
        """
    super().__init__(message, code, params)
    if isinstance(message, ValidationError):
        if hasattr(message, 'error_dict'):
            message = message.error_dict
        elif <MASK>:
            message = message.error_list
        else:
            (message, code, params) = (message.message, message.code, message.params)
    if isinstance(message, dict):
        self.error_dict = {}
        for (field, messages) in message.items():
            if not isinstance(messages, ValidationError):
                messages = ValidationError(messages)
            self.error_dict[field] = messages.error_list
    elif isinstance(message, list):
        self.error_list = []
        for message in message:
            if not isinstance(message, ValidationError):
                message = ValidationError(message)
            if hasattr(message, 'error_dict'):
                self.error_list.extend(sum(message.error_dict.values(), []))
            else:
                self.error_list.extend(message.error_list)
    else:
        self.message = message
        self.code = code
        self.params = params
        self.error_list = [self]

