def are_block_parameters_compatible(self, block_params: BlockParameters) -> bool:
    """
        Check if the block parameters are valid for TMA.
        If force, we allow relying on symbolic hints equivalent
        to what we check for Triton templates.
        """
    if <MASK>:
        strides = [V.graph.sizevars.symbolic_hint(st) for st in block_params.strides]
    else:
        strides = block_params.strides
    if not V.graph.sizevars.statically_known_equals(strides[-1], sympy.Integer(1)):
        log.debug('%s TMA API requires innermost stride to be 1.', self.failed_debug_prefix)
        return False
    element_size = self.dtype.itemsize
    for stride in strides[:-1]:
        if not V.graph.sizevars.statically_known_equals(ModularIndexing(stride * element_size, 1, sympy.Integer(16)), sympy.Integer(0)):
            log.debug('%s TMA API requires outer strides to be 16 byte aligned.', self.failed_debug_prefix)
            return False
    innermost_block_shape = block_params.block_shape[-1]
    innermost_block_type = None
    innermost_block_symt = None
    for block_type_str in innermost_block_shape.free_symbols:
        for block_symt in TritonSymbols.block_types:
            if symbol_is_type(block_type_str, block_symt):
                innermost_block_type = block_type_str
                innermost_block_symt = block_symt
                break
    assert innermost_block_type and innermost_block_symt, f'{innermost_block_shape} expr must contain a single block type from {TritonSymbols.block_types}'
    if self.kernel.persistent_reduction and (not self.for_store):
        innermost_tree_prefix = prefix_str[innermost_block_symt]
        tree_numel = None
        for t in self.kernel.range_trees:
            if t.is_reduction:
                if t.prefix == innermost_tree_prefix:
                    tree_numel = t.numel
                    break
        assert tree_numel is not None
        persistent_rblock = self.kernel._get_persistent_RBLOCK(tree_numel)
        innermost_block_bytes = innermost_block_shape.subs({innermost_block_type: persistent_rblock}) * element_size
        if not V.graph.sizevars.statically_known_geq(innermost_block_bytes, sympy.Integer(16)):
            log.debug('%s persistent reduction innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    else:
        try:
            min_block_size = next_power_of_2(int(sympy.nsolve(innermost_block_shape * element_size - 16, innermost_block_type, 1)))
            block_type_str = V.kernel.index_to_str(innermost_block_type)
            if self.kernel.fixed_config:
                if min_block_size > self.kernel.fixed_config[block_type_str]:
                    log.debug('%s For block %s, fixed config block size %d is smaller than the minimum required: %d', self.failed_debug_prefix, block_type_str, self.kernel.fixed_config[block_type_str], min_block_size)
                    return False
            else:
                self.kernel.tma_min_block_sizes[block_type_str] = max(min_block_size, self.kernel.tma_min_block_sizes.get(block_type_str, 1))
        except ValueError:
            log.debug('%s innermost block shape cannot load 16 bytes.', self.failed_debug_prefix)
            return False
    return True

def _add_data_for_sparse_tensor(self, tensor, weight, indices, values, weights, int_zeros, float_zeros, path, feature):
    sample_indices = math_ops.cast(tensor.indices, dtypes.int32)
    if tensor.shape.rank == 2:
        if not feature.output_shape and feature.max_sequence_length > 0:
            sample_indices = array_ops.pad(sample_indices, paddings=[[0, 0], [0, 1]])
    elif feature.max_sequence_length > 0:
        logging.warning('Input tensor is rank %d which is above 2, the max_sequence_length setting will be ignored.', tensor.shape.rank)
    indices.append(sample_indices)
    values.append(math_ops.cast(tensor.values, dtypes.int64))
    if weight is not None:
        if <MASK>:
            raise ValueError('Weight for {} is type {} which does not match type input which is SparseTensor.'.format(path, type(weight)))
        weights.append(math_ops.cast(weight.values, dtypes.float32))
    else:
        weights.append(float_zeros)

def _register_dequant_promotion_pass(pattern, pass_number, dtype=torch.float32):

    @register_freezing_graph_pattern(pattern, extra_check=_is_valid_dequant_promotion_pattern(dtype), pass_number=pass_number)
    def dequant_promotion(match: Match, *args, **kwargs):
        assert dtype in [torch.float32, torch.bfloat16]

        def clone_to_new_node(graph, source_node, user_node):
            assert source_node.op == 'call_function', 'clone_to_new_node only support node.op call_function'
            with graph.inserting_before(user_node):
                new_node = graph.call_function(source_node.target, args=source_node.args, kwargs=source_node.kwargs)
                new_node.meta = copy.copy(source_node.meta)
                user_node.replace_input_with(source_node, new_node)
            return new_node
        dequant_pattern_end_node = match.output_node()
        assert dequant_pattern_end_node.target in [quantized_decomposed.dequantize_per_tensor.default, quantized_decomposed.dequantize_per_tensor.tensor, prims.convert_element_type.default, aten.reshape.default]

        def _find_first_node_in_dequant_pattern(_node):
            if <MASK>:
                return _node
            else:
                assert len(_node.args) >= 1, 'In in dequant pattern, each node should have more than 1 arg.'
                return _find_first_node_in_dequant_pattern(_node.args[0])
        dequant_pattern_start_node = _find_first_node_in_dequant_pattern(dequant_pattern_end_node)
        assert dequant_pattern_start_node.target in [quantized_decomposed.dequantize_per_tensor.default, quantized_decomposed.dequantize_per_tensor.tensor]
        graph = match.graph
        user_node_list = list(dequant_pattern_end_node.users)
        for user_node in user_node_list[1:]:
            _source_node = dequant_pattern_end_node
            _user_node = user_node
            while _source_node != dequant_pattern_start_node.args[0]:
                _user_node = clone_to_new_node(graph, _source_node, _user_node)
                _source_node = _source_node.args[0]
        counters['inductor']['dequant_promotion_matcher_count'] += 1
        counters['inductor']['dequant_promotion_matcher_nodes'] += len(match.nodes)

@register_lowering(aten.copy, type_promotion_kind=None)
def copy(self, src, non_blocking=False):
    if not isinstance(src, ir.IRNode):
