def _wrap_optimizer(opt, loss_scale):
    """Wraps an optimizer with a LossScaleOptimizer."""
    for (_, wrapper_optimizer) in _REGISTERED_WRAPPER_OPTIMIZER_CLS.values():
        if <MASK>:
            raise ValueError('"opt" must not already be an instance of a {cls}. `enable_mixed_precision_graph_rewrite` will automatically wrap the optimizer with a {cls}.'.format(cls=wrapper_optimizer.__name__))
    for (optimizer_cls, (wrapper_fn, _)) in _REGISTERED_WRAPPER_OPTIMIZER_CLS.items():
        if isinstance(opt, optimizer_cls):
            return wrapper_fn(opt, loss_scale)
    raise ValueError('"opt" must be an instance of a tf.train.Optimizer or a tf.keras.optimizers.Optimizer, but got: %s' % opt)

def __call__(self, X, Y=None, eval_gradient=False):
    """Return the kernel k(X, Y) and optionally its gradient.

        Parameters
        ----------
        X : ndarray of shape (n_samples_X, n_features)
            Left argument of the returned kernel k(X, Y)

        Y : ndarray of shape (n_samples_Y, n_features), default=None
            Right argument of the returned kernel k(X, Y). If None, k(X, X)
            if evaluated instead.

        eval_gradient : bool, default=False
            Determines whether the gradient with respect to the log of
            the kernel hyperparameter is computed.
            Only supported when Y is None.

        Returns
        -------
        K : ndarray of shape (n_samples_X, n_samples_Y)
            Kernel k(X, Y)

        K_gradient : ndarray of shape (n_samples_X, n_samples_X, n_dims),                 optional
            The gradient of the kernel k(X, X) with respect to the log of the
            hyperparameter of the kernel. Only returned when `eval_gradient`
            is True.
        """
    X = np.atleast_2d(X)
    length_scale = _check_length_scale(X, self.length_scale)
    if Y is None:
        dists = pdist(X / length_scale, metric='euclidean')
    else:
        if <MASK>:
            raise ValueError('Gradient can only be evaluated when Y is None.')
        dists = cdist(X / length_scale, Y / length_scale, metric='euclidean')
    if self.nu == 0.5:
        K = np.exp(-dists)
    elif self.nu == 1.5:
        K = dists * math.sqrt(3)
        K = (1.0 + K) * np.exp(-K)
    elif self.nu == 2.5:
        K = dists * math.sqrt(5)
        K = (1.0 + K + K ** 2 / 3.0) * np.exp(-K)
    elif self.nu == np.inf:
        K = np.exp(-dists ** 2 / 2.0)
    else:
        K = dists
        K[K == 0.0] += np.finfo(float).eps
        tmp = math.sqrt(2 * self.nu) * K
        K.fill(2 ** (1.0 - self.nu) / gamma(self.nu))
        K *= tmp ** self.nu
        K *= kv(self.nu, tmp)
    if Y is None:
        K = squareform(K)
        np.fill_diagonal(K, 1)
    if eval_gradient:
        if self.hyperparameter_length_scale.fixed:
            K_gradient = np.empty((X.shape[0], X.shape[0], 0))
            return (K, K_gradient)
        if self.anisotropic:
            D = (X[:, np.newaxis, :] - X[np.newaxis, :, :]) ** 2 / length_scale ** 2
        else:
            D = squareform(dists ** 2)[:, :, np.newaxis]
        if self.nu == 0.5:
            denominator = np.sqrt(D.sum(axis=2))[:, :, np.newaxis]
            divide_result = np.zeros_like(D)
            np.divide(D, denominator, out=divide_result, where=denominator != 0)
            K_gradient = K[..., np.newaxis] * divide_result
        elif self.nu == 1.5:
            K_gradient = 3 * D * np.exp(-np.sqrt(3 * D.sum(-1)))[..., np.newaxis]
        elif self.nu == 2.5:
            tmp = np.sqrt(5 * D.sum(-1))[..., np.newaxis]
            K_gradient = 5.0 / 3.0 * D * (tmp + 1) * np.exp(-tmp)
        elif self.nu == np.inf:
            K_gradient = D * K[..., np.newaxis]
        else:

            def f(theta):
                return self.clone_with_theta(theta)(X, Y)
            return (K, _approx_fprime(self.theta, f, 1e-10))
        if not self.anisotropic:
            return (K, K_gradient[:, :].sum(-1)[:, :, np.newaxis])
        else:
            return (K, K_gradient)
    else:
        return K

def __repr__(self) -> str:
    p2p_info = ''
    if <MASK>:
        p2p_info = f's={self._src_g} d={self._dst_g}'
    if self.is_verbose:
        verbose_info = (f'timestamp_created={self.time_created_ns}', p2p_info, f'input_sizes={self.input_sizes}', f'output_sizes={self.output_sizes}', f'input_dtypes={self.input_dtypes}', f'output_dtypes={self.output_dtypes}', f'collective_seq_id | p2p_seq_id={(self.p2p_seq_id if self.type in P2P else self.collective_seq_id)}', f'pg_name={self.pg_name}', f'pg_description={self.pg_desc}', f'pg_size={self.pg_size}', f'stack_id={self.stack_id}', f'state={self.state}')
        return f'{self.type}(%s)' % ', '.join((s for s in verbose_info if s))
    return f'{self.type}(%sinput_sizes={self.input_sizes}, state={self.state})' % (f'{p2p_info}, ' if p2p_info else '')

def _make_mask_from_positional_indexer(self, arg: PositionalIndexer | tuple) -> np.ndarray:
    if is_list_like(arg):
        if <MASK>:
            mask = self._make_mask_from_list(cast(Iterable[int], arg))
        else:
            mask = self._make_mask_from_tuple(cast(tuple, arg))
    elif isinstance(arg, slice):
        mask = self._make_mask_from_slice(arg)
    elif is_integer(arg):
        mask = self._make_mask_from_int(cast(int, arg))
    else:
        raise TypeError(f'Invalid index {type(arg)}. Must be integer, list-like, slice or a tuple of integers and slices')
    if isinstance(mask, bool):
        if mask:
            mask = self._ascending_count >= 0
        else:
            mask = self._ascending_count < 0
    return cast(np.ndarray, mask)

