def find_test_dir() -> Optional[str]:
    from os.path import abspath, basename, dirname, exists, join, normpath
    if <MASK>:
        return None
    test_dir = normpath(join(dirname(abspath(__file__)), '../../../test'))
    if exists(join(test_dir, 'dynamo_expected_failures')):
        return test_dir
    main = sys.modules['__main__']
    file = getattr(main, '__file__', None)
    if file is None:
        return None
    test_dir = dirname(abspath(file))
    while dirname(test_dir) != test_dir:
        if basename(test_dir) == 'test' and exists(join(test_dir, 'dynamo_expected_failures')):
            return test_dir
        test_dir = dirname(test_dir)
    return None

@classmethod
def add_choices(cls, choices, layout, input_nodes, beta=1, alpha=1, has_bias=False, trans_w=False, input_indices=None, epilogue_creator: Optional[Callable[[ir.Buffer], ir.Pointwise]]=None, act_mapping: Optional[dict[int, ir.IRNode]]=None):
    """
        Add choices for the GEMM template.
        """
    use_int8_fast_compensation_path = _is_int8_gemm(input_nodes) and all((isinstance(input_nodes[idx], ir.TensorBox) and isinstance(input_nodes[idx].data.data, ir.ConstantBuffer) for idx in [1, 2, 4]))
    if input_indices is None:
        input_indices = list(range(len(input_nodes)))

    def reorder_and_filter(inputs, layout_or_out):
        if has_bias:
            assert len(input_indices) >= 3
            inp_idx = input_indices[0]
            x_idx = input_indices[1]
            w_idx = input_indices[2]
            return ([inputs[x_idx], inputs[w_idx], inputs[inp_idx], *[inputs[idx] for idx in input_indices[3:]]], layout_or_out)
        elif len(inputs) >= len(input_indices):
            assert len(input_indices) >= 2
            return ([inputs[idx] for idx in input_indices], layout_or_out)
        else:
            assert len(inputs) == 1
            return ([inputs[0]] * len(input_indices), layout_or_out)
    (new_inputs, new_layout) = reorder_and_filter(input_nodes, layout)
    is_mkldnn_wgt = new_inputs[1].get_name() in V.graph.constants and V.graph.constants[new_inputs[1].get_name()].is_mkldnn
    if is_mkldnn_wgt:
        assert not isinstance(new_inputs[1], ir.BaseView)
    view_size = new_inputs[1].layout.size
    view_stride = new_inputs[1].layout.stride
    view_offset = new_inputs[1].layout.offset

    def maybe_to_dense(inputs, layout_or_out):
        new_inputs = list(inputs)
        if isinstance(inputs[1], torch.Tensor):
            W = inputs[1]
            new_inputs[1] = W.to_dense() if W.is_mkldnn else W
        return (new_inputs, layout_or_out)

    def normalize_shapes(inputs, layout_or_out):
        new_inputs = list(inputs)
        if not is_mkldnn_wgt and isinstance(new_inputs[1], torch.Tensor):
            if <MASK>:
                assert not has_free_symbols(view_size[1:])
                view_size[:] = V.graph.sizevars.size_hints(view_size)
                view_stride[:] = V.graph.sizevars.size_hints(view_stride)
            new_inputs[1] = new_inputs[1].as_strided(view_size, view_stride, view_offset)
        if not trans_w:
            return (new_inputs, layout_or_out)
        X = new_inputs[0]
        W = new_inputs[1]
        B = new_inputs[2] if has_bias else None
        W = transpose_w(W, trans_w)
        B = expand_bias(B, X)
        new_inputs[1] = W
        if B is not None:
            new_inputs[2] = B
        return (new_inputs, layout_or_out)
    num_threads = parallel_num_threads()
    (new_inputs, _) = normalize_shapes(*maybe_to_dense(new_inputs, new_layout))
    (m, n, k, *_) = mm_args(new_inputs[0], new_inputs[1], mat2_transposed=cls.is_woq_int4(), use_4x2_dim=cls.is_woq_int4())
    (output_dtype, compute_dtype) = get_gemm_template_output_and_compute_dtype(new_inputs[0].get_dtype())
    micro_gemm = create_micro_gemm('micro_gemm', m, n, k, input_dtype=new_inputs[0].get_dtype(), input2_dtype=new_inputs[1].get_dtype(), output_dtype=output_dtype, compute_dtype=compute_dtype, alpha=alpha, num_threads=num_threads, use_ref=not cls.is_woq_int4(), q_group_size=cls.q_group_size())
    assert micro_gemm is not None
    pre_block_weights = cls.check_if_block_weight(new_inputs[1], micro_gemm)
    micro_gemm.use_local_vnni_blocking(not pre_block_weights)
    only_one_input = (input_nodes[0] == input_nodes[1] if len(input_nodes) > 1 else False) and (not pre_block_weights)

    def preprocessor(inputs, layout):
        (new_inputs, new_layout) = normalize_shapes(*maybe_to_dense(*reorder_and_filter(inputs, layout)))
        if only_one_input and isinstance(new_inputs[0], torch.Tensor):
            return (new_inputs[1:], new_layout)
        return cls.prep_weight(new_inputs, new_layout, micro_gemm, pre_block_weights, use_int8_fast_compensation_path)

    def postprocessor(output):
        if isinstance(output, ir.TensorBox):
            template_buffer = ir.InputsKernel.unwrap_storage_for_input(output)
            assert isinstance(template_buffer, ir.CppTemplateBuffer)
            (new_input_nodes, _) = reorder_and_filter(input_nodes, layout)
            W_node = new_input_nodes[1]
            if W_node.get_name() not in V.graph.constants:
                return output
            W = V.graph.constants[W_node.get_name()]
            new_input_nodes[1] = W
            (new_input_nodes, new_layout) = normalize_shapes(*maybe_to_dense(new_input_nodes, layout))
            (new_input_nodes, _) = cls.prep_weight(new_input_nodes, new_layout, micro_gemm, pre_block_weights, use_int8_fast_compensation_path, skip_int8_compensation=True)
            W_packed = new_input_nodes[1]
            W_packed_constant = V.graph.add_tensor_constant(W_packed)
            new_input_nodes[1] = W_packed_constant
            prune_tensors(input_nodes, new_input_nodes)
            template_buffer.inputs[1] = ir.InputsKernel.unwrap_storage_for_input(W_packed_constant)
        return output
    template = DataProcessorTemplateWrapper(cls, preprocessor, postprocessor, input_nodes=input_nodes, layout=layout, num_threads=num_threads, register_blocking=micro_gemm.register_blocking, beta=beta, alpha=alpha, has_bias=has_bias, epilogue_creator=epilogue_creator, should_block_weights=pre_block_weights, name=micro_gemm.__class__.__name__)
    template.maybe_append_choice(choices)
    return template

def infer_dtype_from_scalar(val) -> tuple[DtypeObj, Any]:
    """
    Interpret the dtype from a scalar.

    Parameters
    ----------
    val : object
    """
    dtype: DtypeObj = _dtype_obj
    if isinstance(val, np.ndarray):
        if val.ndim != 0:
            msg = 'invalid ndarray passed to infer_dtype_from_scalar'
            raise ValueError(msg)
        dtype = val.dtype
        val = lib.item_from_zerodim(val)
    elif isinstance(val, str):
        dtype = _dtype_obj
        if using_string_dtype():
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
    elif isinstance(val, (np.datetime64, dt.datetime)):
        try:
            val = Timestamp(val)
        except OutOfBoundsDatetime:
            return (_dtype_obj, val)
        if val is NaT or val.tz is None:
            val = val.to_datetime64()
            dtype = val.dtype
        else:
            dtype = DatetimeTZDtype(unit=val.unit, tz=val.tz)
    elif isinstance(val, (np.timedelta64, dt.timedelta)):
        try:
            val = Timedelta(val)
        except (OutOfBoundsTimedelta, OverflowError):
            dtype = _dtype_obj
        else:
            if val is NaT:
                val = np.timedelta64('NaT', 'ns')
            else:
                val = val.asm8
            dtype = val.dtype
    elif <MASK>:
        dtype = np.dtype(np.bool_)
    elif is_integer(val):
        if isinstance(val, np.integer):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.int64)
        try:
            np.array(val, dtype=dtype)
        except OverflowError:
            dtype = np.array(val).dtype
    elif is_float(val):
        if isinstance(val, np.floating):
            dtype = np.dtype(type(val))
        else:
            dtype = np.dtype(np.float64)
    elif is_complex(val):
        dtype = np.dtype(np.complex128)
    if isinstance(val, Period):
        dtype = PeriodDtype(freq=val.freq)
    elif isinstance(val, Interval):
        subtype = infer_dtype_from_scalar(val.left)[0]
        dtype = IntervalDtype(subtype=subtype, closed=val.closed)
    return (dtype, val)

def _smallest_admissible_index_dtype(arrays=(), maxval=None, check_contents=False):
    """Based on input (integer) arrays `a`, determine a suitable index data
    type that can hold the data in the arrays.

    This function returns `np.int64` if it either required by `maxval` or based on the
    largest precision of the dtype of the arrays passed as argument, or by their
    contents (when `check_contents is True`). If none of the condition requires
    `np.int64` then this function returns `np.int32`.

    Parameters
    ----------
    arrays : ndarray or tuple of ndarrays, default=()
        Input arrays whose types/contents to check.

    maxval : float, default=None
        Maximum value needed.

    check_contents : bool, default=False
        Whether to check the values in the arrays and not just their types.
        By default, check only the types.

    Returns
    -------
    dtype : {np.int32, np.int64}
        Suitable index data type (int32 or int64).
    """
    int32min = np.int32(np.iinfo(np.int32).min)
    int32max = np.int32(np.iinfo(np.int32).max)
    if maxval is not None:
        if maxval > np.iinfo(np.int64).max:
            raise ValueError(f'maxval={maxval} is to large to be represented as np.int64.')
        if maxval > int32max:
            return np.int64
    if isinstance(arrays, np.ndarray):
        arrays = (arrays,)
    for arr in arrays:
        if <MASK>:
            raise TypeError(f'Arrays should be of type np.ndarray, got {type(arr)} instead.')
        if not np.issubdtype(arr.dtype, np.integer):
            raise ValueError(f'Array dtype {arr.dtype} is not supported for index dtype. We expect integral values.')
        if not np.can_cast(arr.dtype, np.int32):
            if not check_contents:
                return np.int64
            if arr.size == 0:
                continue
            else:
                maxval = arr.max()
                minval = arr.min()
                if minval < int32min or maxval > int32max:
                    return np.int64
    return np.int32

def _resolvenameargspattern(line):
    (line, bind_cname) = parse_name_for_bind(line)
    line = markouterparen(line)
    m1 = nameargspattern.match(line)
    if <MASK>:
        return (m1.group('name'), m1.group('args'), m1.group('result'), bind_cname)
    m1 = operatorpattern.match(line)
    if m1:
        name = m1.group('scheme') + '(' + m1.group('name') + ')'
        return (name, [], None, None)
    m1 = callnameargspattern.match(line)
    if m1:
        return (m1.group('name'), m1.group('args'), None, None)
    return (None, [], None, None)

@parameterized.named_parameters(GetNamedTestParameters())
def testRoundTrip(self, dtype, shape):
    np.random.seed(42)
    if dtype == np.bool_:
        np_array = np.random.randint(0, 1, shape, np.bool_)
    else:
        np_array = np.random.randint(0, 10, shape)
    tf_tensor = array_ops.identity(constant_op.constant(np_array, dtype=dtype))
    tf_tensor_device = tf_tensor.device
    tf_tensor_dtype = tf_tensor.dtype
    dlcapsule = dlpack.to_dlpack(tf_tensor)
    del tf_tensor
    tf_tensor2 = dlpack.from_dlpack(dlcapsule)
    self.assertAllClose(np_array, tf_tensor2)
    if <MASK>:
        self.assertEqual(tf_tensor2.device, '/job:localhost/replica:0/task:0/device:CPU:0')
    else:
        self.assertEqual(tf_tensor_device, tf_tensor2.device)

def _GetSvdOpTest(dtype_, shape_, use_static_shape_, compute_uv_, full_matrices_):

    def CompareSingularValues(self, x, y, tol):
        atol = (x[0] + y[0]) * tol if len(x) else tol
        self.assertAllClose(x, y, atol=atol)

    def CompareSingularVectors(self, x, y, rank, tol):
        x = x[..., 0:rank]
        y = y[..., 0:rank]
        sum_of_ratios = np.sum(np.divide(y, x), -2, keepdims=True)
        phases = np.divide(sum_of_ratios, np.abs(sum_of_ratios))
        x *= phases
        self.assertAllClose(x, y, atol=2 * tol)

    def CheckApproximation(self, a, u, s, v, full_matrices_, tol):
        batch_shape = a.shape[:-2]
        m = a.shape[-2]
        n = a.shape[-1]
        diag_s = math_ops.cast(array_ops.matrix_diag(s), dtype=dtype_)
        if full_matrices_:
            if m > n:
                zeros = array_ops.zeros(batch_shape + (m - n, n), dtype=dtype_)
                diag_s = array_ops.concat([diag_s, zeros], a.ndim - 2)
            elif n > m:
                zeros = array_ops.zeros(batch_shape + (m, n - m), dtype=dtype_)
                diag_s = array_ops.concat([diag_s, zeros], a.ndim - 1)
        a_recon = math_ops.matmul(u, diag_s)
        a_recon = math_ops.matmul(a_recon, v, adjoint_b=True)
        self.assertAllClose(a_recon, a, rtol=tol, atol=tol)

    def CheckUnitary(self, x, tol):
        xx = math_ops.matmul(x, x, adjoint_a=True)
        identity = array_ops.matrix_band_part(array_ops.ones_like(xx), 0, 0)
        self.assertAllClose(identity, xx, atol=tol)

    @test_util.run_in_graph_and_eager_modes(use_gpu=True)
    def Test(self):
        if not use_static_shape_ and context.executing_eagerly():
            return
        is_complex = dtype_ in (np.complex64, np.complex128)
        is_single = dtype_ in (np.float32, np.complex64)
        tol = 0.0003 if is_single else 1e-12
        if test.is_gpu_available():
            tol *= 200
        np.random.seed(42)
        x_np = np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape_)).reshape(shape_).astype(dtype_)
        if is_complex:
            x_np += 1j * np.random.uniform(low=-1.0, high=1.0, size=np.prod(shape_)).reshape(shape_).astype(dtype_)
        if use_static_shape_:
            x_tf = constant_op.constant(x_np)
        else:
            x_tf = array_ops.placeholder(dtype_)
        if <MASK>:
            (s_tf, u_tf, v_tf) = linalg_ops.svd(x_tf, compute_uv=compute_uv_, full_matrices=full_matrices_)
            if use_static_shape_:
                (s_tf_val, u_tf_val, v_tf_val) = self.evaluate([s_tf, u_tf, v_tf])
            else:
                with self.session() as sess:
                    (s_tf_val, u_tf_val, v_tf_val) = sess.run([s_tf, u_tf, v_tf], feed_dict={x_tf: x_np})
        else:
            s_tf = linalg_ops.svd(x_tf, compute_uv=compute_uv_, full_matrices=full_matrices_)
            if use_static_shape_:
                s_tf_val = self.evaluate(s_tf)
            else:
                with self.session() as sess:
                    s_tf_val = sess.run(s_tf, feed_dict={x_tf: x_np})
        if compute_uv_:
            (u_np, s_np, v_np) = np.linalg.svd(x_np, compute_uv=compute_uv_, full_matrices=full_matrices_)
        else:
            s_np = np.linalg.svd(x_np, compute_uv=compute_uv_, full_matrices=full_matrices_)
        s_np = np.reshape(s_np, s_tf_val.shape)
        CompareSingularValues(self, s_np, s_tf_val, tol)
        if compute_uv_:
            CompareSingularVectors(self, u_np, u_tf_val, min(shape_[-2:]), tol)
            CompareSingularVectors(self, np.conj(np.swapaxes(v_np, -2, -1)), v_tf_val, min(shape_[-2:]), tol)
            CheckApproximation(self, x_np, u_tf_val, s_tf_val, v_tf_val, full_matrices_, tol)
            CheckUnitary(self, u_tf_val, tol)
            CheckUnitary(self, v_tf_val, tol)
    return Test

def broadcast_inplace(a: list[int], b: list[int]):
    dimsA = len(a)
    dimsB = len(b)
    if <MASK>:
        raise AssertionError(f'The dims of tensor b ({dimsB}) must be less than or equal to the dims of tensor a ({dimsA}) ')
    for dimA in range(dimsA):
        dimB = dimsB - dimsA + dimA
        sizeA = a[dimA]
        sizeB = b[dimB] if dimB >= 0 else 1
        if sizeA != sizeB and sizeB != 1:
            raise AssertionError('The size of tensor a {} must match the size of tensor b ({}) at non-singleton dimension {}'.format(sizeA, sizeB, dimA))
    return _copy(a)

def _stack(t, length):
    """stacks `t` `length` times."""
    if t.dtype == dtypes.variant:
        shapes_and_types = _parse_variant_shapes_and_types(t)
        if <MASK>:
            if len(shapes_and_types) != 1:
                raise ValueError(f'Expected handle data of length 1, got {shapes_and_types!r} of length {len(shapes_and_types)}.')
            return wrap(_stack_tensor_list(t, shapes_and_types[0].dtype, length), True)
        else:
            raise ValueError(f'Attempted to stack an unhandled variant-dtype tensor of type {shapes_and_types[0].type!r} ({t!r}).')
    shape = array_ops.shape(t)
    ones = array_ops.ones_like(shape)
    ones = array_ops.reshape(ones, [-1])
    length = array_ops.reshape(length, [-1])
    length = math_ops.cast(length, shape.dtype)
    multiples = array_ops.concat([length, ones], 0)
    t = array_ops.tile(array_ops.expand_dims(t, 0), multiples)
    return wrap(t, True)

def run_tests(needs: Union[str, tuple[str, ...]]=()) -> None:
    from torch.testing._internal.common_utils import run_tests
    if <MASK>:
        return
    if not torch.xpu.is_available() and IS_WINDOWS and (os.environ.get('TORCHINDUCTOR_WINDOWS_TESTS', '0') == '0'):
        return
    if isinstance(needs, str):
        needs = (needs,)
    for need in needs:
        if need == 'cuda':
            if not torch.cuda.is_available():
                return
        else:
            try:
                importlib.import_module(need)
            except ImportError:
                return
    run_tests()

def conditional_expression_supported_in_where_clause(self, expression):
    """
        Oracle supports only EXISTS(...) or filters in the WHERE clause, others
        must be compared with True.
        """
    if isinstance(expression, (Exists, Lookup, WhereNode)):
        return True
    if <MASK>:
        return self.conditional_expression_supported_in_where_clause(expression.expression)
    if isinstance(expression, RawSQL) and expression.conditional:
        return True
    return False

def node_ctor_arg_rvalue_string(arg: LazyArgument) -> str:
    """
    Given a LazyArgument,
    generate a c++ string for materializing an rvalue of that arg for passing into
    a lazy Node constructor.
    """
    if isValueType(arg.lazy_type):
        if isinstance(arg.lazy_type, BaseCType):
            if <MASK>:
                return f'node_{arg.name}'
            elif arg.lazy_type.type is tensorListValueT:
                return f'lazy_{arg.name}_tensorlist'
            elif arg.is_symint_or_list:
                return f'GetSymIntValue({arg.name})'
            return f'lazy_{arg.name}->GetIrValue()'
        elif isinstance(arg.lazy_type, OptionalCType):
            if arg.is_symint_or_list:
                return f'{arg.name} ? std::make_optional(GetSymIntValue(*{arg.name})) : ::std::nullopt'
            elif arg.is_wrapped_scalar:
                return f'node_{arg.name}'
            return f'lazy_{arg.name} ? std::make_optional(lazy_{arg.name}->GetIrValue()) : ::std::nullopt'
        else:
            raise AssertionError(f'TODO not sure if there are other valid types to handle here ({arg.lazy_type})')
    elif isinstance(arg.orig_type, ListType) and arg.orig_type.elem == BaseType(BaseTy.SymInt):
        if arg.symint:
            return f'GetSymIntArrayRefValue({arg.name})'
        else:
            return f'std::vector<int64_t>({arg.name}.begin(), {arg.name}.end())'
    elif isinstance(arg.lazy_type, VectorCType) and isinstance(arg.lazy_type.elem, BaseCType):
        return f'std::vector<{arg.lazy_type.elem.type}>({arg.name}.begin(), {arg.name}.end())'
    elif isinstance(arg.lazy_type, OptionalCType) and isinstance(arg.lazy_type.elem, VectorCType) and isinstance(arg.lazy_type.elem.elem, BaseCType):
        return f'torch::lazy::ToOptionalVector<{arg.lazy_type.elem.elem.type}>({arg.name})'
    else:
        return f'{arg.name}'

def _einsum(self, x, y):
    out = tensorflow.einsum(equation, x, y)
    if <MASK>:
        out = nn_ops.bias_add(out, self._bias)
    return {'output': out}

def get_aggregation(self, using, aggregate_exprs):
    """
        Return the dictionary with the values of the existing aggregations.
        """
    if not aggregate_exprs:
        return {}
    refs_subquery = False
    refs_window = False
    replacements = {}
    annotation_select_mask = self.annotation_select_mask
    for (alias, aggregate_expr) in aggregate_exprs.items():
        self.check_alias(alias)
        aggregate = aggregate_expr.resolve_expression(self, allow_joins=True, reuse=None, summarize=True)
        if <MASK>:
            raise TypeError('%s is not an aggregate expression' % alias)
        self.append_annotation_mask([alias])
        aggregate_refs = aggregate.get_refs()
        refs_subquery |= any((getattr(self.annotations[ref], 'contains_subquery', False) for ref in aggregate_refs))
        refs_window |= any((getattr(self.annotations[ref], 'contains_over_clause', True) for ref in aggregate_refs))
        aggregate = aggregate.replace_expressions(replacements)
        self.annotations[alias] = aggregate
        replacements[Ref(alias, aggregate)] = aggregate
    aggregates = {alias: self.annotations.pop(alias) for alias in aggregate_exprs}
    self.set_annotation_mask(annotation_select_mask)
    (_, having, qualify) = self.where.split_having_qualify()
    has_existing_aggregation = any((getattr(annotation, 'contains_aggregate', True) for annotation in self.annotations.values())) or having
    set_returning_annotations = {alias for (alias, annotation) in self.annotation_select.items() if getattr(annotation, 'set_returning', False)}
    if isinstance(self.group_by, tuple) or self.is_sliced or has_existing_aggregation or refs_subquery or refs_window or qualify or self.distinct or self.combinator or set_returning_annotations:
        from django.db.models.sql.subqueries import AggregateQuery
        inner_query = self.clone()
        inner_query.subquery = True
        outer_query = AggregateQuery(self.model, inner_query)
        inner_query.select_for_update = False
        inner_query.select_related = False
        inner_query.set_annotation_mask(self.annotation_select)
        inner_query.clear_ordering(force=False)
        if not inner_query.distinct:
            if inner_query.default_cols and has_existing_aggregation:
                inner_query.group_by = (self.model._meta.pk.get_col(inner_query.get_initial_alias()),)
            inner_query.default_cols = False
            if not qualify and (not self.combinator):
                annotation_mask = set()
                if isinstance(self.group_by, tuple):
                    for expr in self.group_by:
                        annotation_mask |= expr.get_refs()
                for aggregate in aggregates.values():
                    annotation_mask |= aggregate.get_refs()
                for (annotation_alias, annotation) in self.annotation_select.items():
                    if annotation.get_group_by_cols():
                        annotation_mask.add(annotation_alias)
                inner_query.set_annotation_mask(annotation_mask)
                annotation_mask |= set_returning_annotations
        col_refs = {}
        for (alias, aggregate) in aggregates.items():
            replacements = {}
            for col in self._gen_cols([aggregate], resolve_refs=False):
                if not (col_ref := col_refs.get(col)):
                    index = len(col_refs) + 1
                    col_alias = f'__col{index}'
                    col_ref = Ref(col_alias, col)
                    col_refs[col] = col_ref
                    inner_query.add_annotation(col, col_alias)
                replacements[col] = col_ref
            outer_query.annotations[alias] = aggregate.replace_expressions(replacements)
        if inner_query.select == () and (not inner_query.default_cols) and (not inner_query.annotation_select_mask):
            inner_query.select = (self.model._meta.pk.get_col(inner_query.get_initial_alias()),)
    else:
        outer_query = self
        self.select = ()
        self.selected = None
        self.default_cols = False
        self.extra = {}
        if self.annotations:
            replacements = {Ref(alias, annotation): annotation for (alias, annotation) in self.annotations.items()}
            self.annotations = {alias: aggregate.replace_expressions(replacements) for (alias, aggregate) in aggregates.items()}
        else:
            self.annotations = aggregates
        self.set_annotation_mask(aggregates)
    empty_set_result = [expression.empty_result_set_value for expression in outer_query.annotation_select.values()]
    elide_empty = not any((result is NotImplemented for result in empty_set_result))
    outer_query.clear_ordering(force=True)
    outer_query.clear_limits()
    outer_query.select_for_update = False
    outer_query.select_related = False
    compiler = outer_query.get_compiler(using, elide_empty=elide_empty)
    result = compiler.execute_sql(SINGLE)
    if result is None:
        result = empty_set_result
    else:
        cols = outer_query.annotation_select.values()
        converters = compiler.get_converters(cols)
        rows = compiler.apply_converters((result,), converters)
        if compiler.has_composite_fields(cols):
            rows = compiler.composite_fields_to_tuples(rows, cols)
        result = next(rows)
    return dict(zip(outer_query.annotation_select, result))

@RegisterPForWithArgs('XlaEinsum')
@RegisterPForWithArgs('Einsum')
def _convert_einsum(pfor_input: _PforInput, op_type):
    (inputs, input_stacked, _) = zip(*[pfor_input.input(i) for i in range(pfor_input.num_inputs)])
    equation = pfor_input.get_attr('equation').decode('utf-8')
    (input_expr, output_expr) = equation.split('->')
    input_exprs = input_expr.split(',')
    chosen_symbol = None
    for s in string.ascii_letters:
        if s in equation:
            continue
        else:
            chosen_symbol = s
            break
    if chosen_symbol is None:
        raise ValueError('Could not figure out what symbol to use for new axis.')
    assert any(input_stacked)
    for i in range(len(inputs)):
        if input_stacked[i]:
            input_exprs[i] = '{}{}'.format(chosen_symbol, input_exprs[i])
    output_expr = '{}{}'.format(chosen_symbol, output_expr)
    new_equation = '{}->{}'.format(','.join(input_exprs), output_expr)
    if op_type == 'XlaEinsum':
        if <MASK>:
            result = xla.einsum(equation=new_equation, a=inputs[0])
        else:
            result = xla.einsum(equation=new_equation, a=inputs[0], b=inputs[1])
    else:
        assert op_type == 'Einsum'
        result = special_math_ops.einsum(new_equation, *inputs)
    return wrap(result, True)

def _need_to_fix_layout(self, adjusted_choices: list[KernelTemplateChoice], op_name: str) -> bool:
    """
        Check if we need to fix the layout instead of keeping it flexible

        Args:
            ktc: KernelTemplateChoice object

        Returns:
            True if we need to fix the layout, False otherwise
        """
    if len(adjusted_choices) > 0:
        if adjusted_choices[0].inputs.device_type == 'mps' and op_name not in ['mm', 'addmm']:
            return True
    if not (config.max_autotune or config.max_autotune_gemm):
        if not config.max_autotune_allow_flexible_layouts and op_name not in ['mm', 'addmm']:
            return True
        return False
    if not config.max_autotune_allow_flexible_layouts:
        return True
    if _use_autotune_backend('CUTLASS'):
        return True
    if <MASK>:
        return True
    if _use_autotune_backend('CPP'):
        return True
    return any((not isinstance(ktc.template, ExternKernelChoice) for ktc in adjusted_choices))

def transform(self) -> torch.fx.GraphModule:
    """Perform the graph transformation and copy module metadata."""
    result_gm = super().transform()
    if hasattr(self.module, 'meta'):
        if <MASK>:
            result_gm.meta['dynamo_flat_name_to_original_fqn'] = self.module.meta['dynamo_flat_name_to_original_fqn']
        if 'dynamo_compile_id' in self.module.meta:
            result_gm.meta['dynamo_compile_id'] = self.module.meta['dynamo_compile_id']
    return result_gm

def call_str(self, tx: 'InstructionTranslator', arg):
    if <MASK>:
        return variables.ConstantVariable.create(value=str(arg.fn))
    elif isinstance(arg, variables.UserDefinedObjectVariable):
        if hasattr(arg.value, '__str__'):
            str_method = arg.value.__str__
        elif hasattr(arg.value, '__repr__'):
            str_method = arg.value.__repr__
        else:
            unimplemented_v2(gb_type='failed to call str() on user defined object', context=str(arg), explanation='User defined object has no __str__ or __repr__ method', hints=[*graph_break_hints.USER_ERROR])
        if type(arg.value).__str__ is object.__str__:
            try:
                return variables.ConstantVariable.create(value=str_method())
            except AttributeError:
                return
        elif is_wrapper_or_member_descriptor(str_method):
            unimplemented_v2(gb_type='Attempted to a str() method implemented in C/C++', context='', explanation=f'{type(arg.value)} has a C/C++ based str method. This is not supported.', hints=['Write the str method in Python'])
        else:
            bound_method = str_method.__func__
            try:
                user_func_variable = VariableTracker.build(tx, bound_method)
            except AssertionError:
                log.warning('Failed to create UserFunctionVariable', exc_info=True)
                return
            return user_func_variable.call_function(tx, [arg], {})
    elif isinstance(arg, (variables.ExceptionVariable,)):
        if len(arg.args) == 0:
            value = f'{arg.exc_type}'
        else:
            value = ', '.join((a.as_python_constant() for a in arg.args))
        return variables.ConstantVariable.create(value=value)

@no_type_check
@torch.no_grad()
def init_flat_param_attributes(self) -> None:
    """
        This initializes some attributes on the handle's ``FlatParameter``.
        This should be called during lazy initialization since it requires the
        parameter to be on the compute device if not offloading to CPU and we
        want to give users the chance to move the parameter appropriately after
        the FSDP constructor.

        For each tensor attribute on the ``FlatParameter``, see the unshard and
        reshard methods in this class for the allocation and free pattern.
        """
    flat_param = self.flat_param
    if flat_param.dtype != self._orig_param_dtype:
        if not self._low_prec_param_dtype_specified:
            self._fwd_bwd_param_dtype = flat_param.dtype
        if not self._low_prec_reduce_dtype_specified and (not self._low_prec_param_dtype_specified):
            self._reduce_dtype = flat_param.dtype
        self._orig_param_dtype = flat_param.dtype
    cpu_device = torch.device('cpu')
    if self._offload_params:
        _p_assert(flat_param.device == cpu_device, f'Expects the `FlatParameter` to be on CPU when parameter CPU offloading is enabled, not {flat_param.device}')
    else:
        self._check_on_compute_device(self.flat_param)
    flat_param._local_shard = flat_param.data
    if self._offload_params:
        flat_param._local_shard = flat_param._local_shard.pin_memory()
        flat_param._cpu_grad = torch.zeros_like(flat_param._local_shard, device=cpu_device).pin_memory()
    if <MASK>:
        flat_param._mp_shard = torch.empty_like(flat_param._local_shard, device=self.device, dtype=self._fwd_bwd_param_dtype)
        _free_storage(flat_param._mp_shard)
    if self.uses_sharded_strategy:
        unsharded_param_dtype = self._fwd_bwd_param_dtype if self._uses_param_mixed_precision else flat_param.dtype
        padded_unsharded_numel = flat_param.numel() * self.world_size
        flat_param._full_param_padded = torch.empty(padded_unsharded_numel, device=self.device, dtype=unsharded_param_dtype)
        flat_param._padded_unsharded_size = flat_param._full_param_padded.size()
        _free_storage(flat_param._full_param_padded)
        if self._uses_param_mixed_precision:
            flat_param._full_prec_full_param_padded = torch.empty(padded_unsharded_numel, device=self.device, dtype=flat_param.dtype)
            _free_storage(flat_param._full_prec_full_param_padded)

def call_method(self, tx, name, args: list[VariableTracker], kwargs: dict[str, VariableTracker]) -> VariableTracker:
    if name == '__setattr__':
        if kwargs or len(args) != 2:
            raise_args_mismatch(tx, name, '2 args and 0 kwargs', f'{len(args)} args and {len(kwargs)} kwargs')
        (attr, value) = args
        attr = attr.as_python_constant()
        if <MASK>:
            raise_observed_exception(AttributeError, tx)
        tx.output.side_effects.mutation(self)
        if self.source:
            tx.output.side_effects.store_attr(self, attr, value)
        self.dynamic_attributes[attr] = value
        return ConstantVariable.create(None)
    elif name == '_replace':
        if args:
            raise_args_mismatch(tx, name, '0 args', f'{len(args)} args')
        fields = self.fields()
        new_items = list(self.items)
        for (field_name, new_value) in kwargs.items():
            if field_name not in fields:
                raise_observed_exception(ValueError, tx, args=[ConstantVariable.create(f"Got unexpected field name: '{field_name}'")])
            field_index = fields.index(field_name)
            new_items[field_index] = new_value
        return NamedTupleVariable(new_items, self.tuple_cls)
    return super().call_method(tx, name, args, kwargs)

def SourceLines(line):
    if <MASK>:
        comments.add(line)
        return HaveCommentLines
    else:
        lines.add(line)
        return SourceLines

def _na_arithmetic_op(left: np.ndarray, right, op, is_cmp: bool=False):
    """
    Return the result of evaluating op on the passed in values.

    If native types are not compatible, try coercion to object dtype.

    Parameters
    ----------
    left : np.ndarray
    right : np.ndarray or scalar
        Excludes DataFrame, Series, Index, ExtensionArray.
    is_cmp : bool, default False
        If this a comparison operation.

    Returns
    -------
    array-like

    Raises
    ------
    TypeError : invalid operation
    """
    if isinstance(right, str):
        func = op
    else:
        func = partial(expressions.evaluate, op)
    try:
        result = func(left, right)
    except TypeError:
        if not is_cmp and (left.dtype == object or getattr(right, 'dtype', None) == object):
            result = _masked_arith_op(left, right, op)
        else:
            raise
    if <MASK>:
        return invalid_comparison(left, right, op)
    return missing.dispatch_fill_zeros(op, left, right, result)

def rewrite_signature(f_sig: inspect.Signature, graph: torch.fx.GraphModule, fake_mode: Optional[fake_tensor.FakeTensorMode], flat_args: list[Any], in_spec: pytree.TreeSpec, example_fake_inputs: list[Any], graph_captured_input: Iterable[Any], graph_captured_output: Optional[Iterable[Any]], dynamo_traced_result: Any, flat_args_dynamic_dims: list[set[int]]) -> torch.fx.GraphModule:
    (orig_args, orig_kwargs) = pytree.tree_unflatten(flat_args, in_spec)
    check_user_input_output(flat_args, UserErrorType.INVALID_INPUT)
    (flat_results_traced, out_spec_traced) = pytree.tree_flatten(dynamo_traced_result)
    check_user_input_output(flat_results_traced, UserErrorType.INVALID_OUTPUT)

    def check_optional_input_and_error(f_sig: inspect.Signature) -> None:
        for (name, param) in f_sig.parameters.items():
            if <MASK>:
                from torch._dynamo.exc import Unsupported
                log.error('Parameter %s is optional with a default value of %s', name, param.default)
                raise Unsupported('Tracing through optional input is not supported yet', case_name='optional_input')

    def produce_matching(debug_type: str, sources: Iterable[Any], candidates: Iterable[Any]) -> list[Optional[int]]:
        matched_elements_positions: list[Optional[int]] = []
        dict_of_source_vals = {}
        for (i, val) in enumerate(sources):
            dict_of_source_vals[id(val)] = i
        for (i, val) in enumerate(candidates):
            if isinstance(val, tuple(common_constant_types)):
                matched_elements_positions.append(None)
            elif id(val) not in dict_of_source_vals:
                if debug_type == 'inputs':
                    check_optional_input_and_error(f_sig)
                raise AssertionError(f'Unexpectedly found a {type(val)} in the {debug_type}.\nPlease file an issue along with a paste of the logs from TORCH_LOGS="+export"')
            else:
                matched_elements_positions.append(dict_of_source_vals[id(val)])
        return matched_elements_positions
    matched_input_elements_positions = produce_matching('inputs', flat_args, graph_captured_input)
    assert graph_captured_output is not None
    matched_output_elements_positions = produce_matching('outputs', list(graph_captured_output) + flat_args, flat_results_traced)
    new_graph = FlattenInputOutputSignature(graph, flat_args, matched_input_elements_positions, flat_results_traced, matched_output_elements_positions, example_fake_inputs, flat_args_dynamic_dims, fake_mode).transform()
    new_graph.graph._codegen = _PyTreeCodeGen(_PyTreeInfo(argument_names(f_sig, orig_args, orig_kwargs), in_spec, out_spec_traced))
    new_graph.recompile()
    return new_graph

@register_decomposition(aten.full_like)
def full_like(self: torch.Tensor, fill_value: Union[int, float], *, dtype: Optional[torch.dtype]=None, layout: Optional[torch.layout]=None, device: Optional[torch.device]=None, pin_memory: bool=False, requires_grad: bool=False, memory_format: torch.memory_format=torch.preserve_format) -> torch.Tensor:
    dtype = self.dtype if dtype is None else dtype
    layout = self.layout if layout is None else layout
    device = self.device if device is None else device
    if <MASK>:
        result = torch.full(self.shape, fill_value, dtype=dtype, layout=layout, device=device, pin_memory=pin_memory, requires_grad=requires_grad)
        return result.to(memory_format=memory_format)
    else:
        assert layout == torch.strided
        (shape, permutation) = _get_shape_permutation_like(self)
        result = torch.full(shape, fill_value, dtype=dtype, layout=layout, device=device, pin_memory=pin_memory, requires_grad=requires_grad)
        if permutation == list(range(len(permutation))):
            return result
        return result.permute(permutation).clone()

def register_decomposition(ops: Union[_GenericOperator, list[_GenericOperator]]) -> Callable[[Callable[_P, _T]], Callable[_P, _T]]:
    for op in ops if isinstance(ops, list) else [ops]:
        if <MASK>:
            log.warning('duplicate decomp: %s', ops)
    return decomp.register_decomposition(ops, decompositions)

def build_err_msg(arrays, err_msg, header='Items are not equal:', verbose=True, names=('ACTUAL', 'DESIRED'), precision=8):
    msg = ['\n' + header]
    if <MASK>:
        if err_msg.find('\n') == -1 and len(err_msg) < 79 - len(header):
            msg = [msg[0] + ' ' + err_msg]
        else:
            msg.append(err_msg)
    if verbose:
        for (i, a) in enumerate(arrays):
            if isinstance(a, ndarray):
                r_func = ndarray.__repr__
            else:
                r_func = repr
            try:
                r = r_func(a)
            except Exception as exc:
                r = f'[repr failed for <{type(a).__name__}>: {exc}]'
            if r.count('\n') > 3:
                r = '\n'.join(r.splitlines()[:3])
                r += '...'
            msg.append(f' {names[i]}: {r}')
    return '\n'.join(msg)

def record_cross_partition_use(def_node: Node, use_node: Optional[Node]):
    from torch.fx.experimental.symbolic_shapes import free_symbols
    defined = getattr(def_node, '_fx_partition', None)
    used = getattr(use_node, '_fx_partition', None)
    log.debug('record_cross_partition_use %s (%s) %s (%s)', def_node.name, defined, use_node.name if use_node is not None else '-', used)
    if defined != used:
        if <MASK>:
            def_partition = partitions[defined]
            def_partition.outputs.setdefault(def_node.name)
            if used is not None:
                def_partition.dependents.setdefault(used)
        if used is not None:
            use_partition = partitions[used]
            use_partition.inputs.setdefault(def_node.name)
            if (def_val := def_node.meta.get('example_value')) is not None:
                for s in sorted(free_symbols(def_val), key=str):
                    s_node = symbol_to_node[s]
                    use_partition.inputs.setdefault(s_node.name)
                    if symbol_to_node[s].op != 'placeholder':
                        s_defined = getattr(s_node, '_fx_partition', None)
                        if s_defined is not None:
                            s_def_partition = partitions[s_defined]
                            s_def_partition.outputs.setdefault(s_node.name)
                            s_def_partition.dependents.setdefault(used)
                            use_partition.dependencies.setdefault(s_defined)
            if defined is not None:
                use_partition.dependencies.setdefault(defined)

def _lu_solve_assertions(lower_upper, perm, rhs, validate_args):
    """Returns list of assertions related to `lu_solve` assumptions."""
    assertions = lu_reconstruct_assertions(lower_upper, perm, validate_args)
    message = 'Input `rhs` must have at least 2 dimensions.'
    if <MASK>:
        if rhs.shape.ndims < 2:
            raise ValueError(message)
    elif validate_args:
        assertions.append(check_ops.assert_rank_at_least(rhs, rank=2, message=message))
    message = '`lower_upper.shape[-1]` must equal `rhs.shape[-1]`.'
    if lower_upper.shape[-1] is not None and rhs.shape[-2] is not None:
        if lower_upper.shape[-1] != rhs.shape[-2]:
            raise ValueError(message)
    elif validate_args:
        assertions.append(check_ops.assert_equal(array_ops.shape(lower_upper)[-1], array_ops.shape(rhs)[-2], message=message))
    return assertions

def delete(self, where=None, start: int | None=None, stop: int | None=None) -> int | None:
    if where is None or not len(where):
        if start is None and stop is None:
            nrows = self.nrows
            self._handle.remove_node(self.group, recursive=True)
        else:
            if stop is None:
                stop = self.nrows
            nrows = self.table.remove_rows(start=start, stop=stop)
            self.table.flush()
        return nrows
    if <MASK>:
        return None
    table = self.table
    selection = Selection(self, where, start=start, stop=stop)
    values = selection.select_coords()
    sorted_series = Series(values, copy=False).sort_values()
    ln = len(sorted_series)
    if ln:
        diff = sorted_series.diff()
        groups = list(diff[diff > 1].index)
        if not groups:
            groups = [0]
        if groups[-1] != ln:
            groups.append(ln)
        if groups[0] != 0:
            groups.insert(0, 0)
        pg = groups.pop()
        for g in reversed(groups):
            rows = sorted_series.take(range(g, pg))
            table.remove_rows(start=rows[rows.index[0]], stop=rows[rows.index[-1]] + 1)
            pg = g
        self.table.flush()
    return ln

def call_kernel(self, name: str, node: 'ROCmTemplateBuffer') -> None:
    """
        Generates code to call the kernel through V.graph.wrapper_code.
        used from within torch._inductor.wrapper.PythonWrapperCodegen

        name: Name of kernel function.
        node: The ROCmTemplateBuffer node which contains information about the kernel, it's fused epilogue nodes
        as well as all required inputs and outputs.
        """
    wrapper = V.graph.wrapper_code
    arg_types: list[Any]
    if <MASK>:
        assert isinstance(wrapper, CppWrapperCpu)
        wrapper.initialized_kernels[name] = self
        self.signature = self.signature.replace('KERNEL_NAME', name)
        (_, call_args, arg_types) = self.args.cpp_argdefs(DTYPE_TO_ROCM_TYPE)
    else:
        (_, call_args, _, arg_types) = self.args.python_argdefs()
    kernel_args = []
    for arg in call_args:
        if V.graph.is_unspec_arg(arg):
            arg = arg + '.item()'
        elif not V.graph.cpp_wrapper:
            arg = f'c_void_p({arg}.data_ptr())'
        kernel_args.append(arg)
    size_args = [f'{V.graph.sizevars.simplify(sarg)}' for sarg in node.template.size_args()]
    if V.graph.cpp_wrapper:
        kernel_args.extend(size_args)
    else:
        kernel_args.extend((f'c_int({sarg})' for sarg in size_args))
    if V.graph.cpp_wrapper:
        arg_types.extend(['int'] * len(node.template.size_args()))
    kernel_args.extend(self.runtime_arg_values)
    for arg in self.runtime_arg_info:
        arg_types.append(arg.ty)
    kernel_args.append('nullptr' if V.graph.cpp_wrapper else 'None')
    if V.graph.cpp_wrapper:
        arg_types.append('size_t*')
    if node.get_workspace_size() > 0:
        ws = WorkspaceArg(count=node.get_workspace_size(), device=V.graph.get_current_device_or_throw(), zero_mode=WorkspaceZeroMode.UNINITIALIZED, outer_name=WorkspaceArg.unique_name())
        wrapper.generate_workspace_allocation(ws)
        data_ptr = f'{ws.outer_name}.data_ptr()'
        kernel_args.append(data_ptr if V.graph.cpp_wrapper else f'c_void_p({data_ptr})')
    else:
        ws = None
        kernel_args.append('nullptr' if V.graph.cpp_wrapper else 'None')
    if V.graph.cpp_wrapper:
        arg_types.append('uint8_t*')
    wrapper.generate_kernel_call(name, kernel_args, triton=False, arg_types=arg_types)
    if ws:
        wrapper.generate_workspace_deallocation(ws)

@classmethod
def create(cls, device: torch.device, dtype: torch.dtype, inner_fns: Sequence[Callable[..., Any]], ranges: list[Integer], reduction_ranges: list[Integer], reduction_type: ReductionType, reduction_hint: ReductionHint=ReductionHint.DEFAULT) -> Sequence[Union[TensorBox, ShapeAsConstantBuffer]]:
    assert reduction_type in ('welford_reduce', 'welford_combine')
    reduction_numel = V.graph.sizevars.simplify(sympy_product(reduction_ranges))

    def const(val: int) -> Union[TensorBox, ShapeAsConstantBuffer]:

        def inner_fn(idx: Sequence[Expr]) -> OpsValue:
            return ops.constant(val, dtype)
        return Pointwise.create(device=device, dtype=dtype, inner_fn=inner_fn, ranges=list(ranges))
    if <MASK>:
        mean = const(0)
        m2 = const(0)
        weight = const(0)
        return (mean, m2, weight)
    if reduction_numel == 1:

        def copy(loader: Callable[[Sequence[Expr], Sequence[Expr]], OpsValue]) -> Union[TensorBox, ShapeAsConstantBuffer]:

            def inner_fn(idx: Sequence[Expr]) -> OpsValue:
                reduction_index = [sympy.S.Zero for _ in reduction_ranges]
                return loader(idx, reduction_index)
            return Pointwise.create(device=device, dtype=dtype, inner_fn=inner_fn, ranges=list(ranges))
        if reduction_type == 'welford_reduce':
            return (copy(inner_fns[0]), const(0), const(1))
        else:
            return tuple((copy(fn) for fn in inner_fns))
    (hint, split) = Reduction.num_splits(device, dtype, dtype, inner_fns[0], ranges, reduction_ranges, reduction_type=reduction_type, reduction_numel=reduction_numel)
    if reduction_hint == ReductionHint.DEFAULT:
        reduction_hint = hint
    if split > 1:
        return cls.create_multilayer(device, dtype, inner_fns, ranges, reduction_ranges, reduction_type, split, reduction_hint)
    results = [TensorBox.create(WelfordReduction(device, dtype, inner_fns, ranges, reduction_ranges, reduction_type, dtype, reduction_hint, output_idx)) for output_idx in range(3)]
    for t in results:
        t.realize()
    return results

def main(_):
    buffers_to_skip = FLAGS.buffers_to_skip
    ops_to_skip = [op.upper() for op in FLAGS.ops_to_skip]
    ops_operands_to_skip = {}
    for op_operands_to_skip in FLAGS.ops_operands_to_skip:
        (op_name, indices) = op_operands_to_skip.split(':')
        op_name_upper = op_name.upper()
        if <MASK>:
            raise ValueError(f'Indices for the same op must be specified only once multiple specification for op {op_name}.')
        ops_operands_to_skip[op_name_upper] = list(map(int, indices.split(',')))
    model = flatbuffer_utils.read_model(FLAGS.input_tflite_file)
    for graph in model.subgraphs:
        for op in graph.operators:
            op_name = flatbuffer_utils.opcode_to_name(model, op.opcodeIndex)
            op_name_upper = op_name.upper()
            if op_name_upper in ops_to_skip:
                for input_idx in op.inputs:
                    buffers_to_skip.append(graph.tensors[input_idx].buffer)
            if op_name_upper in ops_operands_to_skip:
                for operand_idx in ops_operands_to_skip[op_name_upper]:
                    buffers_to_skip.append(graph.tensors[op.inputs[operand_idx]].buffer)
    flatbuffer_utils.randomize_weights(model, FLAGS.random_seed, FLAGS.buffers_to_skip)
    flatbuffer_utils.write_model(model, FLAGS.output_tflite_file)

def _plot_curve(self, x_data, *, ax=None, negate_score=False, score_name=None, score_type='test', std_display_style='fill_between', line_kw=None, fill_between_kw=None, errorbar_kw=None):
    check_matplotlib_support(f'{self.__class__.__name__}.plot')
    import matplotlib.pyplot as plt
    if <MASK>:
        (_, ax) = plt.subplots()
    if negate_score:
        (train_scores, test_scores) = (-self.train_scores, -self.test_scores)
    else:
        (train_scores, test_scores) = (self.train_scores, self.test_scores)
    if std_display_style not in ('errorbar', 'fill_between', None):
        raise ValueError(f"Unknown std_display_style: {std_display_style}. Should be one of 'errorbar', 'fill_between', or None.")
    if score_type not in ('test', 'train', 'both'):
        raise ValueError(f"Unknown score_type: {score_type}. Should be one of 'test', 'train', or 'both'.")
    if score_type == 'train':
        scores = {'Train': train_scores}
    elif score_type == 'test':
        scores = {'Test': test_scores}
    else:
        scores = {'Train': train_scores, 'Test': test_scores}
    if std_display_style in ('fill_between', None):
        if line_kw is None:
            line_kw = {}
        self.lines_ = []
        for (line_label, score) in scores.items():
            self.lines_.append(*ax.plot(x_data, score.mean(axis=1), label=line_label, **line_kw))
        self.errorbar_ = None
        self.fill_between_ = None
    if std_display_style == 'errorbar':
        if errorbar_kw is None:
            errorbar_kw = {}
        self.errorbar_ = []
        for (line_label, score) in scores.items():
            self.errorbar_.append(ax.errorbar(x_data, score.mean(axis=1), score.std(axis=1), label=line_label, **errorbar_kw))
        (self.lines_, self.fill_between_) = (None, None)
    elif std_display_style == 'fill_between':
        if fill_between_kw is None:
            fill_between_kw = {}
        default_fill_between_kw = {'alpha': 0.5}
        fill_between_kw = {**default_fill_between_kw, **fill_between_kw}
        self.fill_between_ = []
        for (line_label, score) in scores.items():
            self.fill_between_.append(ax.fill_between(x_data, score.mean(axis=1) - score.std(axis=1), score.mean(axis=1) + score.std(axis=1), **fill_between_kw))
    score_name = self.score_name if score_name is None else score_name
    ax.legend()
    if _interval_max_min_ratio(x_data) > 5:
        xscale = 'symlog' if x_data.min() <= 0 else 'log'
    else:
        xscale = 'linear'
    ax.set_xscale(xscale)
    ax.set_ylabel(f'{score_name}')
    self.ax_ = ax
    self.figure_ = ax.figure

def get_neighbour_values(self, name, orig_val, radius=1, include_self=False):
    """
        Get neighbour values in 'radius' steps. The original value is not
        returned as it's own neighbour.
        """
    assert radius >= 1

    def update(cur_val, inc=True):
        if name == 'num_stages':
            if inc:
                return cur_val + 1
            else:
                return cur_val - 1
        elif inc:
            return cur_val * 2
        else:
            return cur_val // 2
    out = []
    cur_val = orig_val
    for _ in range(radius):
        cur_val = update(cur_val, True)
        if <MASK>:
            break
        out.append(cur_val)
    cur_val = orig_val
    for _ in range(radius):
        cur_val = update(cur_val, False)
        if self.value_too_small(name, cur_val):
            break
        out.append(cur_val)
    if include_self:
        out.append(orig_val)
    return out

def call_command(command_name, *args, **options):
    """
    Call the given command, with the given options and args/kwargs.

    This is the primary API you should use for calling specific commands.

    `command_name` may be a string or a command object. Using a string is
    preferred unless the command object is required for further processing or
    testing.

    Some examples:
        call_command('migrate')
        call_command('shell', plain=True)
        call_command('sqlmigrate', 'myapp')

        from django.core.management.commands import flush
        cmd = flush.Command()
        call_command(cmd, verbosity=0, interactive=False)
        # Do something with cmd ...
    """
    if isinstance(command_name, BaseCommand):
        command = command_name
        command_name = command.__class__.__module__.split('.')[-1]
    else:
        try:
            app_name = get_commands()[command_name]
        except KeyError:
            raise CommandError('Unknown command: %r' % command_name)
        if <MASK>:
            command = app_name
        else:
            command = load_command_class(app_name, command_name)
    parser = command.create_parser('', command_name)
    opt_mapping = {min(s_opt.option_strings).lstrip('-').replace('-', '_'): s_opt.dest for s_opt in parser._actions if s_opt.option_strings}
    arg_options = {opt_mapping.get(key, key): value for (key, value) in options.items()}
    parse_args = []
    for arg in args:
        if isinstance(arg, (list, tuple)):
            parse_args += map(str, arg)
        else:
            parse_args.append(str(arg))

    def get_actions(parser):
        for opt in parser._actions:
            if isinstance(opt, _SubParsersAction):
                for sub_opt in opt.choices.values():
                    yield from get_actions(sub_opt)
            else:
                yield opt
    parser_actions = list(get_actions(parser))
    mutually_exclusive_required_options = {opt for group in parser._mutually_exclusive_groups for opt in group._group_actions if group.required}
    for opt in parser_actions:
        if opt.dest in options and (opt.required or opt in mutually_exclusive_required_options):
            opt_dest_count = sum((v == opt.dest for v in opt_mapping.values()))
            if opt_dest_count > 1:
                raise TypeError(f'Cannot pass the dest {opt.dest!r} that matches multiple arguments via **options.')
            parse_args.append(min(opt.option_strings))
            if isinstance(opt, (_AppendConstAction, _CountAction, _StoreConstAction)):
                continue
            value = arg_options[opt.dest]
            if isinstance(value, (list, tuple)):
                parse_args += map(str, value)
            else:
                parse_args.append(str(value))
    defaults = parser.parse_args(args=parse_args)
    defaults = dict(defaults._get_kwargs(), **arg_options)
    stealth_options = set(command.base_stealth_options + command.stealth_options)
    dest_parameters = {action.dest for action in parser_actions}
    valid_options = (dest_parameters | stealth_options).union(opt_mapping)
    unknown_options = set(options) - valid_options
    if unknown_options:
        raise TypeError('Unknown option(s) for %s command: %s. Valid options are: %s.' % (command_name, ', '.join(sorted(unknown_options)), ', '.join(sorted(valid_options))))
    args = defaults.pop('args', ())
    if 'skip_checks' not in options:
        defaults['skip_checks'] = True
    return command.execute(*args, **defaults)

@classmethod
def lt(cls, a, b):
    a = ValueRanges.wrap(a)
    b = ValueRanges.wrap(b)
    if a.is_bool != b.is_bool:
        raise AssertionError('operands must both be boolean ValueRanges or both non-boolean')
    if a.is_bool:
        return cls.and_(cls.not_(a), b)
    else:
        if <MASK>:
            return ValueRanges.wrap(sympy.true)
        elif a.lower >= b.upper:
            return ValueRanges.wrap(sympy.false)
        return ValueRanges(sympy.false, sympy.true)

