def _laplacian_dense_flo(graph, normed, axis, copy, form, dtype, symmetrized):
    if copy:
        m = np.array(graph)
    else:
        m = np.asarray(graph)
    if <MASK>:
        dtype = m.dtype
    graph_sum = m.sum(axis=axis)
    graph_diagonal = m.diagonal()
    diag = graph_sum - graph_diagonal
    if symmetrized:
        graph_sum += m.sum(axis=1 - axis)
        diag = graph_sum - graph_diagonal - graph_diagonal
    if normed:
        isolated_node_mask = diag == 0
        w = np.where(isolated_node_mask, 1, np.sqrt(diag))
        if symmetrized:
            md = _laplace_normed_sym(m, graph_sum, 1.0 / w)
        else:
            md = _laplace_normed(m, graph_sum, 1.0 / w)
        if form == 'function':
            return (md, w.astype(dtype, copy=False))
        elif form == 'lo':
            m = _linearoperator(md, shape=graph.shape, dtype=dtype)
            return (m, w.astype(dtype, copy=False))
        else:
            raise ValueError(f'Invalid form: {form!r}')
    else:
        if symmetrized:
            md = _laplace_sym(m, graph_sum)
        else:
            md = _laplace(m, graph_sum)
        if form == 'function':
            return (md, diag.astype(dtype, copy=False))
        elif form == 'lo':
            m = _linearoperator(md, shape=graph.shape, dtype=dtype)
            return (m, diag.astype(dtype, copy=False))
        else:
            raise ValueError(f'Invalid form: {form!r}')

@staticmethod
def __tensor_unflatten__(inner_tensors: Dict, meta, outer_size, outer_stride):
    from torch._subclasses.fake_tensor import FakeTensor
    assert len(inner_tensors) >= 2 and len(inner_tensors) <= 5
    values = inner_tensors['_values']
    offsets = inner_tensors['_offsets']
    lengths = inner_tensors.get('_lengths', None)
    min_seqlen_tensor = inner_tensors.get('_min_seqlen_tensor', None)
    max_seqlen_tensor = inner_tensors.get('_max_seqlen_tensor', None)
    metadata_cache = {}
    if <MASK>:
        metadata_cache['min_seqlen'] = min_seqlen_tensor
    if max_seqlen_tensor is not None:
        metadata_cache['max_seqlen'] = max_seqlen_tensor
    ragged_idx = meta['ragged_idx']
    ragged_source = offsets if lengths is None else lengths
    if isinstance(ragged_source, FakeTensor):
        ragged_size = outer_size[ragged_idx]
        ragged_source.nested_int_memo = ragged_size
    return NestedTensor(values, offsets=offsets, lengths=lengths, requires_grad=meta['requires_grad'], _ragged_idx=ragged_idx, _metadata_cache=metadata_cache)

@classmethod
def string_for(cls, value):
    if not isinstance(value, date):
        return value
    now = datetime.now(UTC if is_aware(value) else None)
    if value < now:
        delta = now - value
        if delta.days != 0:
            return cls.time_strings['past-day'] % {'delta': defaultfilters.timesince(value, now, time_strings=cls.past_substrings)}
        elif delta.seconds == 0:
            return cls.time_strings['now']
        elif delta.seconds < 60:
            return cls.time_strings['past-second'] % {'count': delta.seconds}
        elif <MASK>:
            count = delta.seconds // 60
            return cls.time_strings['past-minute'] % {'count': count}
        else:
            count = delta.seconds // 60 // 60
            return cls.time_strings['past-hour'] % {'count': count}
    else:
        delta = value - now
        if delta.days != 0:
            return cls.time_strings['future-day'] % {'delta': defaultfilters.timeuntil(value, now, time_strings=cls.future_substrings)}
        elif delta.seconds == 0:
            return cls.time_strings['now']
        elif delta.seconds < 60:
            return cls.time_strings['future-second'] % {'count': delta.seconds}
        elif delta.seconds // 60 < 60:
            count = delta.seconds // 60
            return cls.time_strings['future-minute'] % {'count': count}
        else:
            count = delta.seconds // 60 // 60
            return cls.time_strings['future-hour'] % {'count': count}

def wrapper(*args):
    in_args: list[torch.Tensor] = []
    for i in range(len(in_vars)):
        if not isinstance(args[i], torch.Tensor):
            raise RuntimeError('Expected Tensor argument')
        in_args.append(args[i])
    trace_inputs = _unflatten(in_args, in_desc)
    if self._return_inputs:
        ret_inputs.append(tuple((x.clone(memory_format=torch.preserve_format) for x in args)))
    if <MASK>:
        inputs_states.append(_unflatten(in_args, in_desc))
    outs.append(self.inner(*trace_inputs))
    if self._return_inputs_states:
        inputs_states[0] = (inputs_states[0], trace_inputs)
    (out_vars, _) = _flatten(outs)
    if len(out_vars) == 1:
        return out_vars[0]
    else:
        return tuple(out_vars)

@cached_property
def templates(self):
    if self._templates is None:
        self._templates = settings.TEMPLATES
    templates = {}
    backend_names = []
    for tpl in self._templates:
        try:
            default_name = tpl['BACKEND'].rsplit('.', 2)[-2]
        except Exception:
            invalid_backend = tpl.get('BACKEND', '<not defined>')
            raise ImproperlyConfigured('Invalid BACKEND for a template engine: {}. Check your TEMPLATES setting.'.format(invalid_backend))
        tpl = {'NAME': default_name, 'DIRS': [], 'APP_DIRS': False, 'OPTIONS': {}, **tpl}
        templates[tpl['NAME']] = tpl
        backend_names.append(tpl['NAME'])
    counts = Counter(backend_names)
    duplicates = [alias for (alias, count) in counts.most_common() if count > 1]
    if <MASK>:
        raise ImproperlyConfigured("Template engine aliases aren't unique, duplicates: {}. Set a unique NAME for each engine in settings.TEMPLATES.".format(', '.join(duplicates)))
    return templates

def _bincount(array, weights=None, minlength=None, xp=None):
    (xp, _) = get_namespace(array, xp=xp)
    if <MASK>:
        return xp.bincount(array, weights=weights, minlength=minlength)
    array_np = _convert_to_numpy(array, xp=xp)
    if weights is not None:
        weights_np = _convert_to_numpy(weights, xp=xp)
    else:
        weights_np = None
    bin_out = numpy.bincount(array_np, weights=weights_np, minlength=minlength)
    return xp.asarray(bin_out, device=device(array))

