def build_guards(self, sorted_guards: list[Guard], existing_diff_guard_sources: OrderedSet[str], f_code: types.CodeType, output_graph: OutputGraphGuardsState, save_guards: bool, source_get_cache: Optional[dict[str, Any]]=None) -> tuple[GuardBuilder, GuardManagerWrapper]:
    guard_manager = GuardManagerWrapper()
    guard_manager.diff_guard_sources = existing_diff_guard_sources
    w_builder = None

    def source_ref(source: Source) -> str:
        guard_source = source.guard_source()
        if guard_source is GuardSource.CONSTANT:
            return source.name()
        assert w_builder
        r_builder = w_builder()
        assert r_builder is not None
        return r_builder.arg_ref(source.name())
    builder = GuardBuilder(f_code, self.id_ref, source_ref, self.lookup_weakrefs, output_graph.local_scope, output_graph.global_scope, guard_manager, self, save_guards, runtime_global_scope=self.runtime_global_scope, source_get_cache=source_get_cache)

    def cleanup_builder(weak_b: weakref.ref[GuardBuilder]) -> None:
        b = weak_b()
        if <MASK>:
            b.scope = None
    w_builder = weakref.ref(builder, cleanup_builder)
    guard_on_nn_modules = config.guard_nn_modules and justknobs_check('pytorch/compiler:guard_nn_modules')
    for guard in sorted_guards:
        if not guard_on_nn_modules and guard.is_specialized_nn_module() and ('__defaults__' not in guard.name) and ('__kwdefaults__' not in guard.name) and (config.skip_nnmodule_hook_guards or 'hooks' not in guard.name):
            continue
        guard.create(builder)
    return (builder, guard_manager)

def _linalg_vector_norm_helper(g: jit_utils.GraphContext, self: torch._C.Value, ord: float, dim: Sequence[int] | None, keepdim: bool, dtype: torch._C.Value):
    axes = None
    if _is_none(dim):
        self = _reshape_helper(g, self, [-1])
        keepdim = False
    elif g.opset >= 18:
        axes = g.op('Constant', value_t=torch.tensor(dim, dtype=torch.long))
    if ord == math.inf:
        if g.opset < 18:
            result = g.op('ReduceMax', g.op('Abs', self), axes_i=dim, keepdims_i=keepdim)
        elif axes is None:
            result = g.op('ReduceMax', g.op('Abs', self), keepdims_i=keepdim)
        else:
            result = g.op('ReduceMax', g.op('Abs', self), axes, keepdims_i=keepdim)
    elif ord == -math.inf:
        if g.opset < 18:
            result = g.op('ReduceMin', g.op('Abs', self), axes_i=dim, keepdims_i=keepdim)
        elif axes is None:
            result = g.op('ReduceMin', g.op('Abs', self), keepdims_i=keepdim)
        else:
            result = g.op('ReduceMin', g.op('Abs', self), axes, keepdims_i=keepdim)
    elif ord == 0:
        if g.opset < 11:
            return _onnx_opset_unsupported_detailed('linalg_vector_norm', 9, 11, 'ord=0 not supported', self)
        else:
            if dim is None:
                self = _reshape_helper(g, self, g.op('Constant', value_t=torch.tensor([-1], dtype=torch.int64)))
                keepdim = False
            cond_op = g.op('Not', g.op('Equal', self, g.op('Constant', value_t=torch.LongTensor([0]))))
            cond_op = g.op('Cast', cond_op, to_i=_type_utils.JitScalarType.from_value(self).onnx_type())
            return _reducesum_helper(g, cond_op, axes_i=dim, keepdims_i=keepdim)
    elif ord == 1:
        if g.opset < 18:
            result = _reduce_op_symbolic_helper('ReduceL1')(g, self, dim=dim, keepdim=keepdim)
        elif axes is None:
            result = _reduce_op_symbolic_helper('ReduceL1')(g, self, keepdim=keepdim)
        else:
            result = _reduce_op_symbolic_helper('ReduceL1')(g, self, axes, keepdim=keepdim)
    elif <MASK>:
        if g.opset < 18:
            result = _reduce_op_symbolic_helper('ReduceL2')(g, self, dim=dim, keepdim=keepdim)
        elif axes is None:
            result = _reduce_op_symbolic_helper('ReduceL2')(g, self, keepdim=keepdim)
        else:
            result = _reduce_op_symbolic_helper('ReduceL2')(g, self, axes, keepdim=keepdim)
    else:
        ord_op = g.op('Constant', value_t=torch.tensor(ord, dtype=torch.float32))
        result = _reducesum_helper(g, g.op('Pow', g.op('Abs', self), ord_op), axes_i=dim, keepdims_i=keepdim)
        result = g.op('Pow', result, g.op('Div', g.op('Constant', value_t=torch.tensor(1, dtype=torch.float32)), ord_op))
    if not _is_none(dtype):
        dtype = _get_const(dtype, 'i', 'dtype')
        result = g.op('Cast', result, to_i=_type_utils.JitScalarType(dtype).onnx_type())
    return result

def _get_target_dtype(values, dtype=None, dtype_hint=None):
    """Gets the target dtype of a family of values."""
    if dtype is not None:
        return dtype
    for value in values:
        if isinstance(value, tensor_lib.Tensor):
            return value.dtype
    for value in values:
        if isinstance(value, np.ndarray):
            return dtypes.as_dtype(value.dtype)
    if <MASK>:
        return dtype_hint
    return dtypes.int64

def __new__(cls, data=None, dtype=None, copy: bool=False, name=None, tupleize_cols: bool=True) -> Self:
    from pandas.core.indexes.range import RangeIndex
    name = maybe_extract_name(name, data, cls)
    if dtype is not None:
        dtype = pandas_dtype(dtype)
    data_dtype = getattr(data, 'dtype', None)
    refs = None
    if not copy and isinstance(data, (ABCSeries, Index)):
        refs = data._references
    if isinstance(data, (range, RangeIndex)):
        result = RangeIndex(start=data, copy=copy, name=name)
        if dtype is not None:
            return result.astype(dtype, copy=False)
        return result
    elif is_ea_or_datetimelike_dtype(dtype):
        if isinstance(data, (set, frozenset)):
            data = list(data)
    elif is_ea_or_datetimelike_dtype(data_dtype):
        pass
    elif <MASK>:
        if isinstance(data, ABCMultiIndex):
            data = data._values
        if data.dtype.kind not in 'iufcbmM':
            data = com.asarray_tuplesafe(data, dtype=_dtype_obj)
    elif isinstance(data, (ABCSeries, Index)):
        pass
    elif is_scalar(data):
        raise cls._raise_scalar_data_error(data)
    elif hasattr(data, '__array__'):
        return cls(np.asarray(data), dtype=dtype, copy=copy, name=name)
    elif not is_list_like(data) and (not isinstance(data, memoryview)):
        raise cls._raise_scalar_data_error(data)
    else:
        if tupleize_cols:
            if is_iterator(data):
                data = list(data)
            if data and all((isinstance(e, tuple) for e in data)):
                from pandas.core.indexes.multi import MultiIndex
                return MultiIndex.from_tuples(data, names=name)
        if not isinstance(data, (list, tuple)):
            data = list(data)
        if len(data) == 0:
            data = np.array(data, dtype=object)
        if len(data) and isinstance(data[0], tuple):
            data = com.asarray_tuplesafe(data, dtype=_dtype_obj)
    try:
        arr = sanitize_array(data, None, dtype=dtype, copy=copy)
    except ValueError as err:
        if 'index must be specified when data is not list-like' in str(err):
            raise cls._raise_scalar_data_error(data) from err
        if 'Data must be 1-dimensional' in str(err):
            raise ValueError('Index data must be 1-dimensional') from err
        raise
    arr = ensure_wrapped_if_datetimelike(arr)
    klass = cls._dtype_to_subclass(arr.dtype)
    arr = klass._ensure_array(arr, arr.dtype, copy=False)
    return klass._simple_new(arr, name, refs=refs)

@parameterized.parameters((-2,), (2,), (5,))
def testCase_gradient_diffShapedIntermediates(self, bi):
    nbranches = 5
    inputs = [array_ops.constant(float(bi), shape=[bi + 1], name='br{}_in'.format(bi)) for bi in range(nbranches)]

    def make_func(bi):

        def f():
            x = inputs[bi] ** 2 * inputs[bi][:bi + 1, None]
            return math_ops.reduce_sum(x)
        return f
    branches = {bi: make_func(bi) for bi in range(nbranches)}
    branch_index = array_ops.placeholder_with_default(bi, [])
    with backprop.GradientTape() as tape:
        for x in inputs:
            tape.watch(x)
        case_out = control_flow_switch_case.switch_case(branch_index, branches, name=self.make_name())
    out_grad = 3.0
    actual_grads = tape.gradient(case_out, inputs, output_gradients=out_grad)
    used_bi = nbranches - 1 if bi < 0 or bi >= nbranches - 1 else bi
    expected_grads = []
    for input_idx in range(nbranches):
        if <MASK>:
            with backprop.GradientTape() as tape:
                tape.watch(inputs[used_bi])
                y = make_func(used_bi)()
            expected_grads.append(self.evaluate(tape.gradient(y, inputs[used_bi], output_gradients=out_grad)))
        else:
            expected_grads.append(None if context.executing_eagerly() else [0.0] * (input_idx + 1))
    self.assertEqual(len(expected_grads), len(actual_grads))
    for (expected, actual) in zip(expected_grads, actual_grads):
        if expected is None:
            self.assertIsNone(actual)
        else:
            self.assertAllEqual(expected, self.evaluate(actual))

def test_while_jacobian(self):

    @def_function.function
    def _f(x, y, use_pfor):
        (_, out) = while_loop.while_loop(lambda i, _: i < 4, lambda i, out: (i + 1, math_ops.matmul(out, y)), [0, x])

        def loop_fn(i):
            out_i = array_ops.gather(out, i, axis=1)
            grad = gradient_ops.gradients(out_i, x)
            return array_ops.reshape(grad[0], [-1])
        if <MASK>:
            return pfor_control_flow_ops.pfor(loop_fn, iters=3)
        else:
            return pfor_control_flow_ops.for_loop(loop_fn, iters=3, loop_fn_dtypes=out.dtype)
    x = constant_op.constant(np.random.uniform(size=(1, 3)))
    y = constant_op.constant(np.random.uniform(size=(3, 3)))
    self.assertAllClose(_f(x, y, True), _f(x, y, False))

