def are_strides_like_channels_last_or_false(shape: Sequence[int], strides: Sequence[int]) -> bool:
    from torch.fx.experimental.symbolic_shapes import guard_or_true, statically_known_true
    ndim = len(shape)
    if ndim == 4:
        dim_order = [1, 3, 2, 0]
    elif <MASK>:
        dim_order = [1, 4, 3, 2, 0]
    else:
        return False
    if guard_or_true(strides[1] == 0):
        return False
    min = 0
    for d in dim_order:
        if guard_or_true(shape[d] == 0):
            return False
        if guard_or_true(strides[d] < min):
            return False
        if d == 0 and min == strides[1]:
            return False
        min = strides[d]
        if guard_or_true(strides[d] > 1):
            min *= shape[d]
    return True

@staticmethod
def prepare_triton_wrapper_args(call_args: list[Any], arg_types: list[Any]) -> tuple[list[Any], list[Any]]:
    assert len(call_args) == len(arg_types), (call_args, arg_types)
    new_args = []
    new_args_types = []
    for (arg, arg_type) in zip(call_args, arg_types):
        if isinstance(arg, str):
            if isinstance(arg_type, torch_dtype) and should_unwrap_unspec_arg(arg):
                arg_type = UnwrapUnspecArg(dtype=arg_type)
            new_args.append(arg)
        elif <MASK>:
            new_args.append(str(arg).lower())
        elif isinstance(arg, (int, float, SymbolicCallArg)):
            new_args.append(str(arg))
        else:
            new_args.append(cexpr(V.graph.sizevars.simplify(arg)))
        new_args_types.append(arg_type)
    return (new_args, new_args_types)

