def interpolate(self, *, method: InterpolateOptions, axis: int, index, limit, limit_direction, limit_area, copy: bool, **kwargs) -> FloatingArray:
    """
        See NDFrame.interpolate.__doc__.
        """
    if self.dtype.kind == 'f':
        if copy:
            data = self._data.copy()
            mask = self._mask.copy()
        else:
            data = self._data
            mask = self._mask
    elif self.dtype.kind in 'iu':
        copy = True
        data = self._data.astype('f8')
        mask = self._mask.copy()
    else:
        raise NotImplementedError(f'interpolate is not implemented for dtype={self.dtype}')
    missing.interpolate_2d_inplace(data, method=method, axis=0, index=index, limit=limit, limit_direction=limit_direction, limit_area=limit_area, mask=mask, **kwargs)
    if <MASK>:
        return self
    if self.dtype.kind == 'f':
        return type(self)._simple_new(data, mask)
    else:
        from pandas.core.arrays import FloatingArray
        return FloatingArray._simple_new(data, mask)

def deserialize_graph(self, serialized_graph: Graph) -> torch.fx.Graph:
    log.debug('\n[deserialize_graph]')
    for (name, tensor_value) in serialized_graph.tensor_values.items():
        log.debug('[deserialize_tensor_meta] %s (input): %s', name, tensor_value)
        self.serialized_name_to_meta[name] = lambda v=tensor_value: self.deserialize_tensor_meta(v)
    for (name, sym_int_value) in serialized_graph.sym_int_values.items():
        log.debug('[deserialize_sym_int] %s (input): %s', name, sym_int_value)
        self.serialized_name_to_meta[name] = lambda v=sym_int_value: self.deserialize_sym_int(v)
    for (name, sym_float_value) in serialized_graph.sym_float_values.items():
        log.debug('[deserialize_sym_float] %s (input): %s', name, sym_float_value)
        self.serialized_name_to_meta[name] = lambda v=sym_float_value: self.deserialize_sym_float(v)
    for (name, sym_bool_value) in serialized_graph.sym_bool_values.items():
        log.debug('[deserialize_sym_bool] %s (input): %s', name, sym_bool_value)
        self.serialized_name_to_meta[name] = lambda v=sym_bool_value: self.deserialize_sym_bool(v)
    for (name, script_obj_meta) in serialized_graph.custom_obj_values.items():
        log.debug('[deserialize_script_obj_meta] %s', script_obj_meta)
        self.serialized_name_to_meta[name] = lambda v=script_obj_meta: self.deserialize_script_obj_meta(v)
    log.debug('\n[deserialize graph nodes]')
    for (i, input_) in enumerate(serialized_graph.inputs):
        log.debug('[deserialize input] %s', input_)
        if input_.type in ('as_tensor', 'as_custom_obj'):
            node_name = input_.value.name
            placeholder_node = self.graph.placeholder(node_name)
            placeholder_node.name = node_name
            self.sync_fx_node(node_name, placeholder_node)
        elif input_.type == 'as_sym_int':
            if input_.value.type == 'as_name':
                node_name = input_.value.as_name
                placeholder_node = self.graph.placeholder(node_name)
                placeholder_node.name = node_name
                self.sync_fx_node(node_name, placeholder_node)
            else:
                raise SerializeError(f'Deserializing a constant symint {input_.value} as an input')
        elif input_.type in ('as_int', 'as_float', 'as_bool', 'as_none', 'as_string'):
            node_name = self.signature.input_specs[i].arg.name or f'arg{i}'
            placeholder_node = self.graph.placeholder(node_name)
            placeholder_node.meta['val'] = self.deserialize_input(input_)
        else:
            raise SerializeError(f'Invalid input type {input_}')
    for serialized_node in serialized_graph.nodes:
        try:
            target = self.deserialize_operator(serialized_node.target)
            self.deserialize_node(serialized_node, target)
        except Exception as e:
            raise SerializeError(f'Failed deserializing node {serialized_node}\n Original exception {traceback.format_exc()}') from e
    outputs = []
    for output in serialized_graph.outputs:
        log.debug('[deserialize output] %s', output)
        outputs.append(self.deserialize_graph_output(output))
    if serialized_graph.is_single_tensor_return:
        assert len(outputs) == 1
        outputs = outputs[0]
    else:
        outputs = tuple(outputs)
    output_node = self.graph.output(outputs)
    if serialized_graph.is_single_tensor_return:
        output_node.meta['val'] = output_node.args[0].meta['val']
    else:
        output_node.meta['val'] = tuple((arg.meta['val'] if isinstance(arg, torch.fx.Node) else arg for arg in output_node.args[0]))
    for node in self.graph.nodes:
        if <MASK>:
            node.meta['unbacked_bindings'] = unbacked_bindings
    assert len(self.unbacked_symbols) == 0
    return self.graph

def register_frexp():
    """A pointwise function that maps ops.frexp to inputs"""
    name = 'frexp'
    frexp = ops_wrapper('frexp')

    def frexp0(*args, **kwargs):
        return frexp(*args, **kwargs)[0]

    def frexp1(*args, **kwargs):
        return frexp(*args, **kwargs)[1]
    pw_fns = [make_pointwise(frexp0), make_pointwise(frexp1, override_return_dtype=torch.int32)]

    def fn(*args, **kwargs):
        return (pw_fns[0](*args, **kwargs), pw_fns[1](*args, **kwargs))
    fn = register_lowering(aten.frexp)(fn)
    if <MASK>:
        register_lowering(getattr(prims, name), type_promotion_kind=None)(fn)
    return fn

def __eq__(self, other: Any) -> bool:
    if <MASK>:
        return NotImplemented
    if not isinstance(other, Tuple):
        return False
    return self.components == other.components

def insert(self, chunksize: int | None=None, method: Literal['multi'] | Callable | None=None) -> int | None:
    if method is None:
        exec_insert = self._execute_insert
    elif method == 'multi':
        exec_insert = self._execute_insert_multi
    elif callable(method):
        exec_insert = partial(method, self)
    else:
        raise ValueError(f'Invalid parameter `method`: {method}')
    (keys, data_list) = self.insert_data()
    nrows = len(self.frame)
    if <MASK>:
        return 0
    if chunksize is None:
        chunksize = nrows
    elif chunksize == 0:
        raise ValueError('chunksize argument should be non-zero')
    chunks = nrows // chunksize + 1
    total_inserted = None
    with self.pd_sql.run_transaction() as conn:
        for i in range(chunks):
            start_i = i * chunksize
            end_i = min((i + 1) * chunksize, nrows)
            if start_i >= end_i:
                break
            chunk_iter = zip(*(arr[start_i:end_i] for arr in data_list), strict=True)
            num_inserted = exec_insert(conn, keys, chunk_iter)
            if num_inserted is not None:
                if total_inserted is None:
                    total_inserted = num_inserted
                else:
                    total_inserted += num_inserted
    return total_inserted

def set_ticks_props(axes: Axes | Iterable[Axes], xlabelsize: int | None=None, xrot=None, ylabelsize: int | None=None, yrot=None):
    for ax in flatten_axes(axes):
        if xlabelsize is not None:
            mpl.artist.setp(ax.get_xticklabels(), fontsize=xlabelsize)
        if xrot is not None:
