        if ylabelsize is not None:
            mpl.artist.setp(ax.get_yticklabels(), fontsize=ylabelsize)
        if <MASK>:
            mpl.artist.setp(ax.get_yticklabels(), rotation=yrot)
    return axes

def _model_loss(model, inputs, targets, output_loss_metrics=None, sample_weights=None, training=False):
    """Calculates the loss for a given model.

  Args:
      model: The model on which metrics are being calculated.
      inputs: Either a dictionary of inputs to the model or a list of input
        arrays.
      targets: List of target arrays.
      output_loss_metrics: List of metrics that are used to aggregated output
        loss values.
      sample_weights: Optional list of sample weight arrays.
      training: Whether the model should be run in inference or training mode.

  Returns:
     Returns the model output, total loss, loss value calculated using the
     specified loss function and masks for each output. The total loss includes
     regularization losses and applies masking and sample weighting
     to the loss value.
  """
    total_loss = 0
    kwargs = {}
    if model._expects_training_arg:
        kwargs['training'] = training
    if len(inputs) == 1 and (not isinstance(inputs, dict)):
        inputs = inputs[0]
    if any((isinstance(input_t, (np.ndarray, float, int)) for input_t in nest.flatten(inputs))):
        inputs = nest.map_structure(tensor_conversion.convert_to_tensor_v2_with_dispatch, inputs)
    outs = model(inputs, **kwargs)
    outs = nest.flatten(outs)
    if targets:
        targets = training_utils_v1.cast_if_floating_dtype_and_mismatch(targets, outs)
    if sample_weights:
        new_sample_weights = []
        for val in sample_weights:
            if val is not None:
                new_sample_weights.append(training_utils_v1.cast_if_floating_dtype(tensor_conversion.convert_to_tensor_v2_with_dispatch(val)))
            else:
                new_sample_weights.append(None)
        sample_weights = new_sample_weights
    masks = [getattr(t, '_keras_mask', None) for t in outs]
    targets = nest.flatten(targets)
    output_losses = []
    with backend.name_scope('loss'):
        loss_fns = [loss_fn for loss_fn in model.loss_functions if loss_fn is not None]
        custom_losses = model.losses
        if not loss_fns and (not custom_losses):
            if <MASK>:
                raise ValueError('The model cannot be trained because it has no loss to optimize.')
            else:
                raise ValueError('The model cannot be evaluated because it has no loss to compute.')
        for (i, loss_fn) in enumerate(loss_fns):
            weights = sample_weights[i] if sample_weights else None
            mask = masks[i]
            with backend.name_scope(model.output_names[i] + '_loss'):
                if mask is not None:
                    mask = math_ops.cast(mask, outs[i].dtype)
                    if weights is None:
                        weights = mask
                    else:
                        weights = math_ops.cast(weights, outs[i].dtype)
                        (mask, _, weights) = losses_utils.squeeze_or_expand_dimensions(mask, sample_weight=weights)
                        weights *= mask
                if hasattr(loss_fn, 'reduction'):
                    per_sample_losses = loss_fn.call(targets[i], outs[i])
                    weighted_losses = losses_utils.compute_weighted_loss(per_sample_losses, sample_weight=weights, reduction=losses_utils.ReductionV2.NONE)
                    loss_reduction = loss_fn.reduction
                    if loss_reduction == losses_utils.ReductionV2.AUTO:
                        loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
                    output_loss = losses_utils.reduce_weighted_loss(weighted_losses, reduction=loss_reduction)
                else:
                    output_loss = loss_fn(targets[i], outs[i], sample_weight=weights)
                    loss_reduction = losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE
            if len(model.outputs) > 1:
                output_losses.append(output_loss_metrics[i](output_loss))
            if loss_reduction == losses_utils.ReductionV2.SUM_OVER_BATCH_SIZE:
                output_loss = losses_utils.scale_loss_for_distribution(output_loss)
            total_loss += model._loss_weights_list[i] * output_loss
        if custom_losses:
            total_loss += losses_utils.scale_loss_for_distribution(math_ops.add_n(custom_losses))
    return (outs, total_loss, output_losses, masks)

def create_micro_gemm(name, m, n, k, input_dtype, input2_dtype, output_dtype=None, compute_dtype=None, alpha=1, num_threads=-1, use_ref=True, q_group_size=None) -> Optional[CppMicroGemm]:
    """
    Based on the provided info, try to find the config of the micro-kernel that would
    deliver the best performance in terms of lower latency for this case.
    """

    def create_from_config(cls, config: CppMicroGemmConfig):
        return cls(name, config.input_dtype, config.input2_dtype, config.output_dtype, config.compute_dtype, config.register_blocking, alpha)

    def skip_amx_kernel_for_woq(dynamic_M):
        if dynamic_M or input_dtype != torch.bfloat16 or input2_dtype not in [torch.int8, torch.uint8]:
            return False
        m_threshold = 5
        return m < m_threshold
    assert isinstance(n, int) or n.is_number, n
    assert isinstance(k, int) or k.is_number, k
    from ..utils import has_free_symbols
    dynamic_M = has_free_symbols((m,))
    m = V.graph.sizevars.size_hint(m, fallback=1) if dynamic_M else m
    assert isinstance(m, int) or m.is_number, m
    if output_dtype is None:
        output_dtype = input_dtype
    if <MASK>:
        compute_dtype = output_dtype
    if num_threads < 0:
        num_threads = parallel_num_threads()
    vec_isa = pick_vec_isa()
    matched_configs = []
    for (cls, configs) in micro_gemm_configs.items():
        for config in configs:
            if not issubclass(vec_isa.__class__, config.vec_isa_cls):
                continue
            if config.input_dtype == input_dtype and config.compute_dtype == compute_dtype and (config.input2_dtype == input2_dtype) and (config.output_dtype == output_dtype):
                if config.extra_check is not None and (not config.extra_check(config, m, n, k, alpha, num_threads, dynamic_M=dynamic_M, q_group_size=q_group_size, vec_isa=vec_isa)):
                    continue
                (block_m, block_n, block_k) = config.register_blocking
                if config.vec_isa_cls == VecAMX and skip_amx_kernel_for_woq(dynamic_M):
                    continue
                isa_score = 0
                if config.vec_isa_cls == VecAMX:
                    isa_score += 1
                dividable_score = 0
                if m % block_m == 0:
                    dividable_score += 1
                if n % block_n == 0:
                    dividable_score += 1
                if k % block_k == 0:
                    dividable_score += 1
                occupancy_score = 0
                n_blocks = (n + block_n - 1) // block_n
                total_mxn_blocks = n_blocks * ((m + block_m - 1) // block_m)
                if n_blocks >= num_threads:
                    occupancy_score += 1
                if total_mxn_blocks >= num_threads:
                    occupancy_score += 1
                register_bytes = block_m * block_n * config.compute_dtype.itemsize + (block_m * block_k + block_k * block_n) * config.input_dtype.itemsize
                size_score = register_bytes
                if occupancy_score == 0:
                    size_score = 0 - register_bytes
                matched_configs.append(((isa_score, dividable_score, occupancy_score, size_score), cls, config))
    if len(matched_configs) == 0:
        if use_ref:
            return CppMicroGemmRef(name, input_dtype, input2_dtype, output_dtype, compute_dtype, alpha)
        else:
            return None
    return create_from_config(*max(matched_configs, key=operator.itemgetter(0))[1:])

@doc_controls.do_not_generate_docs
def normalize_batch_in_training(x, gamma, beta, reduction_axes, epsilon=0.001):
    """Computes mean and std for batch then apply batch_normalization on batch.

  Args:
      x: Input tensor or variable.
      gamma: Tensor by which to scale the input.
      beta: Tensor with which to center the input.
      reduction_axes: iterable of integers,
          axes over which to normalize.
      epsilon: Fuzz factor.

  Returns:
      A tuple length of 3, `(normalized_tensor, mean, variance)`.
  """
    if ndim(x) == 4 and list(reduction_axes) in [[0, 1, 2], [0, 2, 3]]:
        if <MASK>:
            return _broadcast_normalize_batch_in_training(x, gamma, beta, reduction_axes, epsilon=epsilon)
        return _fused_normalize_batch_in_training(x, gamma, beta, reduction_axes, epsilon=epsilon)
    elif sorted(reduction_axes) == list(range(ndim(x)))[:-1]:
        return _regular_normalize_batch_in_training(x, gamma, beta, reduction_axes, epsilon=epsilon)
    else:
        return _broadcast_normalize_batch_in_training(x, gamma, beta, reduction_axes, epsilon=epsilon)

def forbid_multi_line_headers(name, val, encoding):
    """Forbid multi-line headers to prevent header injection."""
    warnings.warn("The internal API forbid_multi_line_headers() is deprecated. Python's modern email API (with email.message.EmailMessage or email.policy.default) will reject multi-line headers.", RemovedInDjango70Warning)
    encoding = encoding or settings.DEFAULT_CHARSET
    val = str(val)
    if <MASK>:
        raise BadHeaderError("Header values can't contain newlines (got %r for header %r)" % (val, name))
    try:
        val.encode('ascii')
    except UnicodeEncodeError:
        if name.lower() in ADDRESS_HEADERS:
            val = ', '.join((sanitize_address(addr, encoding) for addr in getaddresses((val,))))
        else:
            val = Header(val, encoding).encode()
    else:
        if name.lower() == 'subject':
            val = Header(val).encode()
    return (name, val)

def convert(x):
    """Converts a function output to a Tensor."""
    if <MASK>:
        return None
    if op_return_value is not None and isinstance(x, ops.Operation):
        with ops.control_dependencies([x]):
            x = array_ops.identity(op_return_value)
    elif not isinstance(x, tensor_array_ops.TensorArray):
        try:
            x = ops.convert_to_tensor_or_composite(x)
        except (ValueError, TypeError):
            raise TypeError(f'To be compatible with tf.function, Python functions must return zero or more Tensors or ExtensionTypes or None values; in compilation of {str(python_func)}, found return value of type {type(x).__name__}, which is not a Tensor or ExtensionType.')
    if add_control_dependencies:
        x = deps_ctx.mark_as_return(x)
    return x

@staticmethod
def _pad_strides(in_strides: Sequence[int], size: Sequence[Expr], dtype: torch.dtype) -> Sequence[int]:
    """
        The padding does not change stride order but makes sure all strides larger
        than the threshold are multiple of align.
        """
    align = get_align_for_dtype(dtype)
    if len(in_strides) == 0:
        return in_strides
    if not config.pad_channels_last and Layout.is_channels_last_contiguous(size, in_strides):
        return in_strides
    current_fx_node = V.get_current_node()
    if hasattr(current_fx_node, 'meta') and current_fx_node.meta.get('dislike_padding', False):
        return in_strides
    is_dynamic = not all((isinstance(s, (int, sympy.Integer)) for s in itertools.chain(in_strides, size)))
    if <MASK>:
        return in_strides
    shape_env = V.graph._shape_env if hasattr(V.graph, '_shape_env') else None

    def contains_unbacked_symints(expr: sympy.Expr | int) -> bool:
        if shape_env is None:
            return False
        if not isinstance(expr, sympy.Expr):
            return False
        return any((shape_env.is_unbacked_symint(s) for s in expr.free_symbols))
    if shape_env and any((contains_unbacked_symints(s) for s in in_strides)):
        return in_strides
    stride_order = get_stride_order(in_strides, shape_env)
    fill_order = stride_order2fill_order(stride_order)
    new_strides = [0 for _ in range(len(in_strides))]
    new_strides[fill_order[0]] = 1
    padded = False
    for (rank, idx) in enumerate(fill_order[1:], start=1):
        prev_idx = fill_order[rank - 1]
        stride = new_strides[prev_idx] * size[prev_idx]
        require_padding = isinstance(stride, (int, sympy.Integer)) and stride > config.padding_stride_threshold and (stride % align != 0) or (isinstance(stride, sympy.Expr) and config.pad_dynamic_shapes)
        new_strides[idx] = stride
        if require_padding:
            new_strides[idx] = ceildiv(stride, align) * align
            padded = True
    if not padded:
        return in_strides
    metrics.num_comprehensive_padding += 1
    return new_strides

def _parse_arg_features(self, arg_name, req_features):
    if not isinstance(req_features, str):
        self.dist_fatal("expected a string in '%s'" % arg_name)
    final_features = set()
    tokens = list(filter(None, re.split(self._parse_regex_arg, req_features)))
    append = True
    for tok in tokens:
        if tok[0] in ('#', '$'):
            self.dist_fatal(arg_name, "target groups and policies aren't allowed from arguments, only from dispatch-able sources")
        if tok == '+':
            append = True
            continue
        if tok == '-':
            append = False
            continue
        TOK = tok.upper()
        features_to = set()
        if TOK == 'NONE':
            pass
        elif TOK == 'NATIVE':
            native = self.cc_flags['native']
            if not native:
                self.dist_fatal(arg_name, "native option isn't supported by the compiler")
            features_to = self.feature_names(force_flags=native, macros=[('DETECT_FEATURES', 1)])
        elif <MASK>:
            features_to = self.feature_supported.keys()
        elif TOK == 'MIN':
            features_to = self.feature_min
        elif TOK in self.feature_supported:
            features_to.add(TOK)
        elif not self.feature_is_exist(TOK):
            self.dist_fatal(arg_name, ", '%s' isn't a known feature or option" % tok)
        if append:
            final_features = final_features.union(features_to)
        else:
            final_features = final_features.difference(features_to)
        append = True
    return final_features

@dispatch(object, object, dict)
def unify(u, v, s):
    """Find substitution so that u == v while satisfying s
    >>> x = var("x")
    >>> unify((1, x), (1, 2), {})
    {~x: 2}
    """
    u = walk(u, s)
    v = walk(v, s)
    if u == v:
        return s
    if <MASK>:
        return assoc(s, u, v)
    if isvar(v):
        return assoc(s, v, u)
    return _unify(u, v, s)

def _ensure_initialized(self):
    """Initialize the async checkpoint internal state."""
    self._object_map = object_identity.ObjectIdentityDictionary()
    self._tpu_embedding_objects = []
    exclude_set = object_identity.ObjectIdentitySet()
    exclude_set.add(self.checkpointer())
    exclude_set.add(self.checkpointer().save_counter)
    (self._saveable_trackables, all_trackables) = _get_all_trackables(root=self.checkpointer(), exclude_set=exclude_set)
    for t in all_trackables:
        if hasattr(type(t), _TPU_EMBEDDING_ATTR):
            self._handle_tpu_embedding(t)
        if <MASK>:
            slot_names = t.get_slot_names()
            for slot_name in slot_names:
                for original_variable in all_trackables:
                    if not isinstance(original_variable, variables.Variable):
                        continue
                    try:
                        original_slot_variable = t.get_slot(original_variable, slot_name)
                    except (AttributeError, KeyError):
                        continue
                    if isinstance(original_slot_variable, base.Trackable):
                        self._saveable_trackables.append(original_slot_variable)
    save_counter = self.checkpointer().save_counter.numpy()
    logging.info("Initializing async checkpoint's save_counter: %d", save_counter)
    self.checkpointer()._saver._object_map = self._object_map
    for t in self._saveable_trackables:
        try:
            t._copy_trackable_to_cpu(object_map=self._object_map)
        except NotImplementedError as e:
            logging.warning('Trackable %s skipped due to: %s', t, e)
    for tpu_embedding in self._tpu_embedding_objects:
        tpu_embedding._retrieve_variables()
    self._async_save_thread = threading.Thread(target=self._async_save, daemon=True)
    self._async_save_thread.start()
    self._initialized = True

