def _parse_column_or_constraint_definition(self, tokens, columns):
    token = None
    is_constraint_definition = None
    field_name = None
    constraint_name = None
    unique = False
    unique_columns = []
    check = False
    check_columns = []
    braces_deep = 0
    for token in tokens:
        if token.match(sqlparse.tokens.Punctuation, '('):
            braces_deep += 1
        elif token.match(sqlparse.tokens.Punctuation, ')'):
            braces_deep -= 1
            if braces_deep < 0:
                break
        elif braces_deep == 0 and token.match(sqlparse.tokens.Punctuation, ','):
            break
        if is_constraint_definition is None:
            is_constraint_definition = token.match(sqlparse.tokens.Keyword, 'CONSTRAINT')
            if is_constraint_definition:
                continue
        if is_constraint_definition:
            if constraint_name is None:
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    constraint_name = token.value
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    constraint_name = token.value[1:-1]
            if token.match(sqlparse.tokens.Keyword, 'UNIQUE'):
                unique = True
                unique_braces_deep = braces_deep
            elif unique:
                if unique_braces_deep == braces_deep:
                    if unique_columns:
                        unique = False
                    continue
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    unique_columns.append(token.value)
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    unique_columns.append(token.value[1:-1])
        else:
            if field_name is None:
                if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                    field_name = token.value
                elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                    field_name = token.value[1:-1]
            if token.match(sqlparse.tokens.Keyword, 'UNIQUE'):
                unique_columns = [field_name]
        if token.match(sqlparse.tokens.Keyword, 'CHECK'):
            check = True
            check_braces_deep = braces_deep
        elif check:
            if <MASK>:
                if check_columns:
                    check = False
                continue
            if token.ttype in (sqlparse.tokens.Name, sqlparse.tokens.Keyword):
                if token.value in columns:
                    check_columns.append(token.value)
            elif token.ttype == sqlparse.tokens.Literal.String.Symbol:
                if token.value[1:-1] in columns:
                    check_columns.append(token.value[1:-1])
    unique_constraint = {'unique': True, 'columns': unique_columns, 'primary_key': False, 'foreign_key': None, 'check': False, 'index': False} if unique_columns else None
    check_constraint = {'check': True, 'columns': check_columns, 'primary_key': False, 'unique': False, 'foreign_key': None, 'index': False} if check_columns else None
    return (constraint_name, unique_constraint, check_constraint, token)

@_onnx_symbolic('aten::scaled_dot_product_attention')
@symbolic_helper.parse_args('v', 'v', 'v', 'v', 'f', 'b', 'v', 'b')
def scaled_dot_product_attention(g: jit_utils.GraphContext, query: torch._C.Value, key: torch._C.Value, value: torch._C.Value, attn_mask: torch._C.Value | None=None, dropout_p: float=0.0, is_causal: bool=False, scale: torch._C.Value | None=None, enable_gqa: bool=False):
    assert not is_causal or (is_causal and symbolic_helper._is_none(attn_mask)), 'is_causal and attn_mask cannot be set at the same time'
    assert not enable_gqa, 'conversion of scaled_dot_product_attention not implemented if enable_gqa is True'
    if symbolic_helper._is_none(scale):
        scale = _attention_scale(g, query)
    if <MASK>:
        attn_mask = _causal_attention_mask(g, query, key)
    key_shape_builtin = symbolic_helper._get_tensor_rank(key)
    key_transposed_axes = list(range(key_shape_builtin))
    (key_transposed_axes[-1], key_transposed_axes[-2]) = (key_transposed_axes[-2], key_transposed_axes[-1])
    key_transposed = g.op('Transpose', key, perm_i=key_transposed_axes)
    query_scaled = g.op('Mul', query, g.op('Sqrt', scale))
    key_transposed_scaled = g.op('Mul', key_transposed, g.op('Sqrt', scale))
    mul_qk = g.op('MatMul', query_scaled, key_transposed_scaled)
    if symbolic_helper._is_none(attn_mask):
        mul_qk_add = mul_qk
        attn_weight = g.op('Softmax', mul_qk_add, axis_i=-1)
    elif _type_utils.JitScalarType.from_value(attn_mask) == _type_utils.JitScalarType.BOOL:
        const_zero = g.op('Constant', value_t=torch.tensor([0.0]))
        const_neg_inf = g.op('Constant', value_t=torch.tensor([-float('inf')]))
        attn_mask = g.op('Where', attn_mask, const_zero, const_neg_inf)
        mul_qk_add = g.op('Add', mul_qk, attn_mask)
        attn_weight = g.op('Softmax', mul_qk_add, axis_i=-1)
        attn_weight = g.op('Where', g.op('IsNaN', attn_weight), const_zero, attn_weight)
    elif _type_utils.JitScalarType.from_value(attn_mask) in (_type_utils.JitScalarType.FLOAT, _type_utils.JitScalarType.HALF, _type_utils.JitScalarType.BFLOAT16):
        mul_qk_add = g.op('Add', mul_qk, attn_mask)
        attn_weight = g.op('Softmax', mul_qk_add, axis_i=-1)
    else:
        raise ValueError(f'Unsupported type for attn_mask: {_type_utils.JitScalarType.from_value(attn_mask)}')
    if dropout_p != 0:
        attn_weight = g.op('Dropout', attn_weight, g.op('Constant', value_t=torch.tensor(dropout_p, dtype=torch.float)))
    return g.op('MatMul', attn_weight, value)

