        if 'all' in fkeys:
            for key in formatdict.keys():
                formatdict[key] = indirect(formatter['all'])
        if 'int_kind' in fkeys:
            for key in ['int']:
                formatdict[key] = indirect(formatter['int_kind'])
        if 'float_kind' in fkeys:
            for key in ['float', 'longfloat']:
                formatdict[key] = indirect(formatter['float_kind'])
        if 'complex_kind' in fkeys:
            for key in ['complexfloat', 'longcomplexfloat']:
                formatdict[key] = indirect(formatter['complex_kind'])
        if 'str_kind' in fkeys:
            formatdict['numpystr'] = indirect(formatter['str_kind'])
        for key in formatdict.keys():
            if key in fkeys:
                formatdict[key] = indirect(formatter[key])
    return formatdict

def items_for_result(cl, result, form):
    """
    Generate the actual list of data.
    """

    def link_in_col(is_first, field_name, cl):
        if cl.list_display_links is None:
            return False
        if is_first and (not cl.list_display_links):
            return True
        return field_name in cl.list_display_links
    first = True
    pk = cl.lookup_opts.pk.attname
    for (field_index, field_name) in enumerate(cl.list_display):
        empty_value_display = cl.model_admin.get_empty_value_display()
        row_classes = ['field-%s' % _coerce_field_name(field_name, field_index)]
        link_to_changelist = link_in_col(first, field_name, cl)
        try:
            (f, attr, value) = lookup_field(field_name, result, cl.model_admin)
        except ObjectDoesNotExist:
            result_repr = empty_value_display
        else:
            empty_value_display = getattr(attr, 'empty_value_display', empty_value_display)
            if isinstance(value, str) and value.strip() == '':
                value = ''
            if f is None or f.auto_created:
                if field_name == 'action_checkbox':
                    row_classes = ['action-checkbox']
                boolean = getattr(attr, 'boolean', False)
                if <MASK>:
                    boolean = getattr(attr.fget, 'boolean', False)
                result_repr = display_for_value(value, empty_value_display, boolean)
                if isinstance(value, (datetime.date, datetime.time)):
                    row_classes.append('nowrap')
            else:
                if isinstance(f.remote_field, models.ManyToOneRel):
                    field_val = getattr(result, f.name)
                    if field_val is None:
                        result_repr = empty_value_display
                    else:
                        result_repr = field_val
                else:
                    result_repr = display_for_field(value, f, empty_value_display, avoid_link=link_to_changelist)
                if isinstance(f, (models.DateField, models.TimeField, models.ForeignKey)):
                    row_classes.append('nowrap')
        row_class = mark_safe(' class="%s"' % ' '.join(row_classes))
        if link_to_changelist:
            table_tag = 'th' if first else 'td'
            first = False
            try:
                url = cl.url_for_result(result)
            except NoReverseMatch:
                link_or_text = result_repr
            else:
                url = add_preserved_filters({'preserved_filters': cl.preserved_filters, 'opts': cl.opts}, url)
                if cl.to_field:
                    attr = str(cl.to_field)
                else:
                    attr = pk
                value = result.serializable_value(attr)
                link_or_text = format_html('<a href="{}"{}>{}</a>', url, format_html(' data-popup-opener="{}"', value) if cl.is_popup else '', result_repr)
            yield format_html('<{}{}>{}</{}>', table_tag, row_class, link_or_text, table_tag)
        else:
            if form and field_name in form.fields and (not (field_name == cl.model._meta.pk.name and form[cl.model._meta.pk.name].is_hidden)):
                bf = form[field_name]
                result_repr = mark_safe(str(bf.errors) + str(bf))
            yield format_html('<td{}>{}</td>', row_class, result_repr)
    if form and (not form[cl.model._meta.pk.name].is_hidden):
        yield format_html('<td>{}</td>', form[cl.model._meta.pk.name])

def get_path(basename: str, extension: str, specified_dir: str='') -> tuple[str, str, str]:
    if <MASK>:
        if os.path.isabs(specified_dir):
            subdir = specified_dir
        else:
            subdir = os.path.join(cache_dir(), specified_dir)
    else:
        subdir = os.path.join(cache_dir(), basename[1:3])
    path = os.path.join(subdir, f'{basename}.{extension}')
    return (basename, subdir, path)

def hierarchical_pickle(data):
    if isinstance(data, (bool, int, float, str, type(None))):
        return data
    if isinstance(data, list):
        return [hierarchical_pickle(d) for d in data]
    if isinstance(data, tuple):
        return {'__tuple_values__': hierarchical_pickle(list(data))}
    if isinstance(data, dict):
        return {'__is_dict__': True, 'keys': hierarchical_pickle(list(data.keys())), 'values': hierarchical_pickle(list(data.values()))}
    if isinstance(data, torch.utils.show_pickle.FakeObject):
        typename = f'{data.module}.{data.name}'
        if typename.startswith(('__torch__.', 'torch.jit.LoweredWrapper.', 'torch.jit.LoweredModule.')):
            if data.args != ():
                raise AssertionError('data.args is not ()')
            return {'__module_type__': typename, 'state': hierarchical_pickle(data.state)}
        if typename == 'torch._utils._rebuild_tensor_v2':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (storage, offset, size, stride, requires_grad, *_) = data.args
            storage_info = get_storage_info(storage)
            return {'__tensor_v2__': [storage_info, offset, size, stride, requires_grad]}
        if typename == 'torch._utils._rebuild_qtensor':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (storage, offset, size, stride, quantizer, requires_grad, *_) = data.args
            storage_info = get_storage_info(storage)
            if not isinstance(quantizer, tuple):
                raise AssertionError('quantizer is not a tuple')
            if not isinstance(quantizer[0], torch.utils.show_pickle.FakeClass):
                raise AssertionError('quantizer[0] is not a FakeClass')
            if quantizer[0].module != 'torch':
                raise AssertionError('quantizer[0].module is not torch')
            if quantizer[0].name == 'per_tensor_affine':
                if len(quantizer) != 3:
                    raise AssertionError('len(quantizer) is not 3')
                if not isinstance(quantizer[1], float):
                    raise AssertionError('quantizer[1] is not a float')
                if not isinstance(quantizer[2], int):
                    raise AssertionError('quantizer[2] is not an int')
                quantizer_extra = list(quantizer[1:3])
            else:
                quantizer_extra = []
            quantizer_json = [quantizer[0].name] + quantizer_extra
            return {'__qtensor__': [storage_info, offset, size, stride, quantizer_json, requires_grad]}
        if typename == 'torch.jit._pickle.restore_type_tag':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (obj, typ) = data.args
            if not isinstance(typ, str):
                raise AssertionError('typ is not a string')
            return hierarchical_pickle(obj)
        if re.fullmatch('torch\\.jit\\._pickle\\.build_[a-z]+list', typename):
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (ls,) = data.args
            if not isinstance(ls, list):
                raise AssertionError('ls is not a list')
            return hierarchical_pickle(ls)
        if typename == 'torch.device':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (name,) = data.args
            if not isinstance(name, str):
                raise AssertionError('name is not a string')
            return name
        if typename == 'builtin.UnicodeDecodeError':
            if data.state is not None:
                raise AssertionError('data.state is not None')
            (msg,) = data.args
            if <MASK>:
                raise AssertionError('msg is not a string')
            return {'__module_type__': typename, 'state': hierarchical_pickle((msg,))}
        raise Exception(f"Can't prepare fake object of type for JS: {typename}")
    raise Exception(f"Can't prepare data of type for JS: {type(data)}")

def _get_quantized_conv_bn_example_inputs_kwargs(is_per_channel: bool, has_bias: bool, bias_is_quantized: bool, is_cuda: bool) -> dict[str, Any]:
    """
    Optional example inputs for quantized and folded conv-bn patterns
    used in convert, expressed as kwargs.
    """
    kwargs = {}
    if <MASK>:
        kwargs['weight_scale'] = torch.tensor([1], dtype=torch.float)
        kwargs['weight_zero_point'] = torch.tensor([0], dtype=torch.int)
        if has_bias and bias_is_quantized:
            kwargs['bias_scale'] = torch.tensor([1], dtype=torch.float)
            kwargs['bias_zero_point'] = torch.tensor([0], dtype=torch.int)
    if has_bias:
        kwargs['conv_bias'] = torch.randn(1)
    if is_cuda:
        for (k, v) in kwargs.items():
            if isinstance(v, torch.Tensor):
                kwargs[k] = v.cuda()
    return kwargs

@staticmethod
def _encode_files(files, data):
    """Build the body for a multipart/form-data request.

        Will successfully encode files when passed as a dict or a list of
        tuples. Order is retained if data is a list of tuples but arbitrary
        if parameters are supplied as a dict.
        The tuples may be 2-tuples (filename, fileobj), 3-tuples (filename, fileobj, contentype)
        or 4-tuples (filename, fileobj, contentype, custom_headers).
        """
    if not files:
        raise ValueError('Files must be provided.')
    elif <MASK>:
        raise ValueError('Data must not be a string.')
    new_fields = []
    fields = to_key_val_list(data or {})
    files = to_key_val_list(files or {})
    for (field, val) in fields:
        if isinstance(val, basestring) or not hasattr(val, '__iter__'):
            val = [val]
        for v in val:
            if v is not None:
                if not isinstance(v, bytes):
                    v = str(v)
                new_fields.append((field.decode('utf-8') if isinstance(field, bytes) else field, v.encode('utf-8') if isinstance(v, str) else v))
    for (k, v) in files:
        ft = None
        fh = None
        if isinstance(v, (tuple, list)):
            if len(v) == 2:
                (fn, fp) = v
            elif len(v) == 3:
                (fn, fp, ft) = v
            else:
                (fn, fp, ft, fh) = v
        else:
            fn = guess_filename(v) or k
            fp = v
        if isinstance(fp, (str, bytes, bytearray)):
            fdata = fp
        elif hasattr(fp, 'read'):
            fdata = fp.read()
        elif fp is None:
            continue
        else:
            fdata = fp
        rf = RequestField(name=k, data=fdata, filename=fn, headers=fh)
        rf.make_multipart(content_type=ft)
        new_fields.append(rf)
    (body, content_type) = encode_multipart_formdata(new_fields)
    return (body, content_type)

@classmethod
def match_mod_div_block_expr(cls, index: Expr, index_var: Symbol, numel: Expr, num_dims: int) -> Optional[tuple[list[Expr], list[Expr], list[Expr]]]:
    """
        Matches modular indexing expressions, converting them to implied block dimensions and strides.
        See triton.py for more information.
        """
    index = cls._preprocess(index)
    wild_unsigned_int = functools.partial(cls._indexing_wild_unsigned_int, exclude=[index_var])
    wild_signed_int = functools.partial(cls._indexing_wild_signed_int, exclude=[index_var])
    dims: list[Expr] = [wild_unsigned_int(f'dim_mod{idx}') for idx in range(num_dims)]
    strides: list[Expr] = [wild_signed_int(f'stride_mod{idx}') for idx in range(num_dims)]
    slice_numels = cls.get_slice_numels(dims[:num_dims])
    block_index_exprs = [FloorDiv(index_var, slice_numels[0])] + [ModularIndexing(index_var, numel, dim) for (dim, numel) in zip(dims[1:], slice_numels[1:])]
    match_expr = sympy_dot(strides, block_index_exprs)
    if <MASK>:
        stride = sympy.symbols('stride', cls=wild_signed_int)
        (denom, other) = sympy.symbols('denominator other', cls=wild_unsigned_int)
        mod_div_pattern = stride * ModularIndexing(index_var, denom, other)
        floor_div_pattern = stride * FloorDiv(index_var, denom)
        first_dim_floor_div_matched = False
        match_failed = False
        for arg in sympy.Add.make_args(index):
            if arg.match(floor_div_pattern):
                if first_dim_floor_div_matched:
                    match_failed = True
                    break
                first_dim_floor_div_matched = True
            elif arg.match(mod_div_pattern):
                continue
            else:
                match_failed = True
                break
        if match_failed:
            return None
    match = index.match(match_expr)
    if match is None:
        return None
    for dim in dims[1:]:
        if dim not in match:
            match[dim] = sympy.S.One
    for stride in strides[1:]:
        if stride not in match:
            match[stride] = sympy.S.Zero
    sizevars = V.graph.sizevars

    def get_match(expr: Expr) -> Expr:
        return sizevars.lookup_precomputed_size(match[expr])
    dims = [dims[0]] + [get_match(dim) for dim in dims[1:]]
    strides = [get_match(stride) for stride in strides]
    slice_numels = cls.get_slice_numels(dims)
    block_index_exprs = [sympy_subs(expr, match) for expr in block_index_exprs]
    assert dims[0] not in match, 'Expected not to match the leading dimension!'
    if not sizevars.statically_known_multiple_of(numel, slice_numels[0]):
        return None
    dims[0] = numel / slice_numels[0]
    matched_index = sympy_dot(strides, block_index_exprs)
    assert sizevars.statically_known_equals(sizevars.remove_precomputed_replacements(matched_index), sizevars.remove_precomputed_replacements(index)), textwrap.dedent(f'\n            Invalid match!\n            Index: {index}\n            Matched expression: {matched_index}\n            ')
    return (dims, strides, block_index_exprs)

@staticmethod
def new(obj):
    """Returns a new SerializedAttribute object."""
    if isinstance(obj, training_lib.Model):
        return ModelAttributes()
    elif isinstance(obj, metrics.Metric):
        return MetricAttributes()
    elif isinstance(obj, recurrent.RNN):
        return RNNAttributes()
    elif <MASK>:
        return LayerAttributes()
    else:
        raise TypeError('Internal error during serialization: Expected Keras Layer object, got {} of type {}'.format(obj, type(obj)))

def check_block_tiles(self, op: 'CKTileGemmOperation'):
    """
        The contiguous dimension of a tensor must be divisible by the block tile size
        This helper function enforces it for the inputs and the output.
        """
    (M, N, K) = self.get_gemm_problem_size()

    def check(dim_size, tile_size, is_padded):
        if is_static_int(dim_size) and dim_size % tile_size != 0 and (is_padded == 'false'):
            return False
        return True
    if op.layout_a == 'Row':
        return True
    elif <MASK>:
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_a={op.layout_a!r}')
    if op.layout_b == 'Row':
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_b == 'Col':
        return True
    else:
        raise AssertionError(f'Invalid op.layout_b={op.layout_b!r}')
    if op.layout_c == 'Row':
        if not check(N, op.tile_n, op.n_is_padded):
            return False
    elif op.layout_c == 'Col':
        if not check(M, op.tile_m, op.m_is_padded):
            return False
    else:
        raise AssertionError(f'Invalid layout op.layout_c={op.layout_c!r}')
    return True

def _reduce(self, name: str, *, skipna: bool=True, keepdims: bool=False, **kwargs):
    if self.dtype.na_value is np.nan and name in ['any', 'all']:
        if not skipna:
            nas = pc.is_null(self._pa_array)
            arr = pc.or_kleene(nas, pc.not_equal(self._pa_array, ''))
        else:
            arr = pc.not_equal(self._pa_array, '')
        result = ArrowExtensionArray(arr)._reduce(name, skipna=skipna, keepdims=keepdims, **kwargs)
        if <MASK>:
            return result.astype(np.bool_)
        return result
    if name in ('min', 'max', 'sum', 'argmin', 'argmax'):
        result = self._reduce_calc(name, skipna=skipna, keepdims=keepdims, **kwargs)
    else:
        raise TypeError(f"Cannot perform reduction '{name}' with string dtype")
    if name in ('argmin', 'argmax') and isinstance(result, pa.Array):
        return self._convert_int_result(result)
    elif isinstance(result, pa.Array):
        return type(self)(result, dtype=self.dtype)
    else:
        return result

def _call_batch_hook(self, mode, hook, batch, logs=None):
    """Helper function for all batch_{begin | end} methods."""
    if <MASK>:
        return
    if hook == 'begin':
        self._call_batch_begin_hook(mode, batch, logs)
    elif hook == 'end':
        self._call_batch_end_hook(mode, batch, logs)
    else:
        raise ValueError('Unrecognized hook: {}'.format(hook))

def _add_send_recv(compute_actions: dict[int, list[_Action]], stage_to_rank: Callable[[int], int], num_stages: int) -> dict[int, list[_Action]]:
    """
    Transforms a compute-only schedule into a complete schedule with communication actions.

    For actions with sub-actions (OVERLAP_F_B) we ensure that all the subactions have been
    computed and the communication is ready
    """
    comm_actions: dict[int, list[_Action]] = {rank: [] for rank in compute_actions}
    prev_actions: dict[int, set[_Action]] = {rank: set() for rank in compute_actions}

    def _has_comms(action: _Action) -> bool:
        if action.computation_type == F:
            return action.stage_index != num_stages - 1 and stage_to_rank(action.stage_index + 1) != stage_to_rank(action.stage_index)
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD):
            return action.stage_index != 0 and stage_to_rank(action.stage_index - 1) != stage_to_rank(action.stage_index)
        return False

    def _get_comms(action: _Action) -> tuple[_Action, _Action]:
        assert _has_comms(action), f'{action} is not a valid comm action'
        stage_idx = action.stage_index
        ctype = action.computation_type
        mb_idx = action.microbatch_index
        send = _Action(stage_idx, SEND_F if ctype == F else SEND_B, mb_idx)
        recv_stage_idx = stage_idx + 1 if ctype == F else stage_idx - 1
        recv = _Action(recv_stage_idx, RECV_F if ctype == F else RECV_B, mb_idx)
        return (send, recv)

    def _ready_to_schedule(action: Optional[_Action], prev_actions: set[_Action]) -> bool:
        """We don't put our own recv ops in the schedule, we let a sender on another rank put our recv ops in place.
        This helps ensure a sane (non-hanging) ordering of sends and recvs.
        But it also means we might not be able to schedule our next compute action yet.
        """
        if action is None:
            return True
        elif <MASK>:
            if _Action(action.stage_index, RECV_F, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index - 1, F, action.microbatch_index) in prev_actions:
                return True
            return False
        elif action.computation_type in (BACKWARD_INPUT, FULL_BACKWARD) and action.stage_index != num_stages - 1:
            if _Action(action.stage_index, RECV_B, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index + 1, BACKWARD_INPUT, action.microbatch_index) in prev_actions:
                return True
            elif _Action(action.stage_index + 1, FULL_BACKWARD, action.microbatch_index) in prev_actions:
                return True
            return False
        else:
            return True
    while compute_actions:
        progress = False
        for rank in sorted(compute_actions):
            assert len(compute_actions[rank]) > 0, f'rank={rank!r}, len(compute_actions[rank])={len(compute_actions[rank])!r}'
            action = compute_actions[rank][0]
            if action is not None and action.sub_actions is not None:
                all_actions = action.sub_actions
            else:
                all_actions = (action,)
            if not all((_ready_to_schedule(a, prev_actions[rank]) for a in all_actions)):
                continue
            if action is not None:
                comm_actions[rank].append(action)
                for a in all_actions:
                    prev_actions[rank].add(a)
                    if _has_comms(a):
                        (send, recv) = _get_comms(a)
                        comm_actions[rank].append(send)
                        prev_actions[rank].add(send)
                        comm_actions[stage_to_rank(recv.stage_index)].append(recv)
                        prev_actions[stage_to_rank(recv.stage_index)].add(recv)
            compute_actions[rank].pop(0)
            if len(compute_actions[rank]) == 0:
                del compute_actions[rank]
            progress = True
        assert progress, "Malformed compute schedule, can't schedule sends/recvs"
    return comm_actions

def _maybe_null_out(result: np.ndarray | float | NaTType, axis: AxisInt | None, mask: npt.NDArray[np.bool_] | None, shape: tuple[int, ...], min_count: int=1, datetimelike: bool=False) -> np.ndarray | float | NaTType:
    """
    Returns
    -------
    Dtype
        The product of all elements on a given axis. ( NaNs are treated as 1)
    """
    if mask is None and min_count == 0:
        return result
    if <MASK>:
        if mask is not None:
            null_mask = mask.shape[axis] - mask.sum(axis) - min_count < 0
        else:
            below_count = shape[axis] - min_count < 0
            new_shape = shape[:axis] + shape[axis + 1:]
            null_mask = np.broadcast_to(below_count, new_shape)
        if np.any(null_mask):
            if datetimelike:
                result[null_mask] = iNaT
            elif is_numeric_dtype(result):
                if np.iscomplexobj(result):
                    result = result.astype('c16')
                elif not is_float_dtype(result):
                    result = result.astype('f8', copy=False)
                result[null_mask] = np.nan
            else:
                result[null_mask] = None
    elif result is not NaT:
        if check_below_min_count(shape, mask, min_count):
            result_dtype = getattr(result, 'dtype', None)
            if is_float_dtype(result_dtype):
                result = result_dtype.type('nan')
            else:
                result = np.nan
    return result

def _compare(tree, dynamic_shapes, path):
    rendered_path = keystr(path)
    if <MASK>:
        return
    if isinstance(dynamic_shapes, LeafSpec):
        raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is not')
    if tree.type != dynamic_shapes.type:
        raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {tree.type}, but `dynamic_shapes{rendered_path}` is a {dynamic_shapes.type}')
    if len(tree.children_specs) != len(dynamic_shapes.children_specs):
        raise_mismatch_error(f'`{tree_name}{rendered_path}` has {len(tree.children_specs)} elements, but `dynamic_shapes{rendered_path}` has {len(dynamic_shapes.children_specs)} elements')
    if tree.type is dict:
        if sorted(tree.context) != sorted(dynamic_shapes.context):
            raise_mismatch_error(f'`{tree_name}{rendered_path}` has keys {tree.context}, but `dynamic_shapes{rendered_path}` has keys {dynamic_shapes.context}')
        _remap = dict(zip(dynamic_shapes.context, dynamic_shapes.children_specs))
        dynamic_shapes_children_specs = [_remap[k] for k in tree.context]
    else:
        dynamic_shapes_children_specs = dynamic_shapes.children_specs
    for (i, (tree_, dynamic_shapes_)) in enumerate(zip(tree.children_specs, dynamic_shapes_children_specs)):
        _compare(tree_, dynamic_shapes_, path + [_key(tree.type, tree.context, i)])

def replace_no_op(node, replace_input_index):
    replacement = node.args[replace_input_index]
    if <MASK>:
        return
    if not fake_tensors_eq(node.meta['val'], replacement.meta['val']):
        if fake_tensors_eq(node.meta['val'], replacement.meta['val'], ('shape', 'device')):
            with graph.inserting_after(node):
                replacement = graph.call_function(torch.ops.prims.convert_element_type.default, args=(replacement, node.meta['val'].dtype))
        else:
            return
    node.replace_all_uses_with(replacement)
    replacement.meta.update(node.meta)
    graph.erase_node(node)

def getsetitem(self: Any, index: Any, tensors_have_dims: bool) -> IndexingInfo:
    from . import DimList
    can_call_original_getitem = not tensors_have_dims
    input_list = []
    if has_dims(index):
        input_list.append(index)
    else:
        is_sequence = extractIndices(index, input_list)
        if can_call_original_getitem and (not is_sequence):
            return IndexingInfo(can_call_original=True)
    dims_indexed = 0
    expanding_object = -1
    unbound_dim_list = None
    dimlists = []

    def check_expanding(i: int) -> None:
        nonlocal expanding_object
        if expanding_object != -1:
            from . import DimensionBindError
            raise DimensionBindError(f'at most one ... or unbound dimension list can exist in indexing list but found 2 at offsets {expanding_object} and {i}')
        expanding_object = i

    def is_dimpack(s: Any) -> bool:
        from . import Dim
        return isinstance(s, (tuple, list)) and len(s) > 0 and all((Dim.check_exact(item) for item in s))
    has_dimpacks_or_none = False
    for (i, s) in enumerate(input_list):
        if has_dims(s):
            can_call_original_getitem = False
            dims_indexed += 1
        elif s is ...:
            check_expanding(i)
        elif isinstance(s, DimList):
            can_call_original_getitem = False
            if not s.is_bound:
                check_expanding(i)
                unbound_dim_list = s
            else:
                dims_indexed += len(s._dims)
            dimlists.append(i)
        elif s is None:
            has_dimpacks_or_none = True
        elif is_dimpack(s):
            can_call_original_getitem = False
            has_dimpacks_or_none = True
            dims_indexed += 1
        else:
            dims_indexed += 1
    if can_call_original_getitem:
        return IndexingInfo(can_call_original=True)
    self_info = TensorInfo.create(self, False, True)
    total_dims = len(self_info.levels)
    if <MASK>:
        raise ValueError(f'at least {dims_indexed} indices were supplied but the tensor only has {total_dims} dimensions')
    expanding_dims = total_dims - dims_indexed
    if expanding_object != -1:
        if unbound_dim_list is not None:
            unbound_dim_list.bind_len(expanding_dims)
        else:
            no_slices = [slice(None)] * expanding_dims
            input_list = input_list[:expanding_object] + no_slices + input_list[expanding_object + 1:]
    for i in range(len(dimlists) - 1, -1, -1):
        idx = dimlists[i]
        if unbound_dim_list is None and expanding_object != -1 and (idx > expanding_object):
            idx += expanding_dims
        dl = input_list[idx]
        input_list = input_list[:idx] + dl._dims + input_list[idx + 1:]
    return getsetitem_flat(self_info, input_list, [], [], has_dimpacks_or_none)

def _get_sorted_col_indices(select_columns, column_names):
    """Transforms select_columns argument into sorted column indices."""
    names_to_indices = {n: i for (i, n) in enumerate(column_names)}
    num_cols = len(column_names)
    results = []
    for v in select_columns:
        if isinstance(v, int):
            if <MASK>:
                raise ValueError(f'Column index {v} specified in `select_columns` should be > 0  and <= {num_cols}, which is the number of columns.')
            results.append(v)
        elif v not in names_to_indices:
            raise ValueError(f'Column {v} specified in `select_columns` must be of one of the columns: {names_to_indices.keys()}.')
        else:
            results.append(names_to_indices[v])
    results = sorted(set(results))
    if len(results) != len(select_columns):
        sorted_names = sorted(results)
        duplicate_columns = set([a for (a, b) in zip(sorted_names[:-1], sorted_names[1:]) if a == b])
        raise ValueError(f'The `select_columns` argument contains duplicate columns: {duplicate_columns}.')
    return results

def _get_model_id(obj) -> Optional[str]:
    if <MASK>:
        return str(obj._c._type())
    elif isinstance(obj, torch.jit.ScriptFunction):
        return obj.qualified_name
    else:
        return None

def pre_compile(self, flat_fn: TraceFn, flat_args: list[FxValue], flat_args_descs: list[AOTInput], aot_config: AOTConfig, *, fw_metadata: ViewAndMutationMeta) -> tuple[Callable, list[FxValue], list[AOTInput], ViewAndMutationMeta]:
    is_inference = not self.trace_joint
    (flat_args_with_synthetic_bases, flat_args_descs_with_synthetic_bases, synthetic_base_info) = merge_view_inputs(aot_config, flat_args, flat_args_descs, fw_metadata.input_info, is_inference=is_inference)
    if synthetic_base_info is None:
        self.needs_post_compile = False
        return (flat_fn, flat_args, flat_args_descs, fw_metadata)
    if requires_subclass_dispatch(flat_args, fw_metadata):
        raise RuntimeError('        Encountered aliased inputs that are mutated in the graph, but at least one input/output\n        to the graph is a tensor subclass. This is not supported today. You can try to\n        remove the aliasing yourself as a workaround, or otherwise file an issue on github.')
    if aot_config.is_export:
        raise RuntimeError(f'        Encountered aliased inputs that are mutated in the graph you are trying to export.\n        This functionality is currently not supported. If needed, please file a github issue.\n\n        synthetic_base_info={str(synthetic_base_info)}\n\n        fw_metadata={str(fw_metadata)}\n                ')
    assert len(fw_metadata.input_info) == len(synthetic_base_info)
    (fw_metadata_updated, aliased_arg_idx_with_metadata_mutations) = create_synthetic_base_metadata(fw_metadata, synthetic_base_info, flat_args, flat_args_with_synthetic_bases, flat_args_descs_with_synthetic_bases)
    self.old_input_info = fw_metadata.input_info
    self.aliased_arg_idx_with_metadata_mutations = aliased_arg_idx_with_metadata_mutations
    replay_views = config.view_replay_for_aliased_outputs

    def _unpack_synthetic_bases(primals: tuple[Any, ...]) -> list[Any]:
        f_args_inner = []
        for inner_idx_or_tuple in synthetic_base_info:
            if isinstance(inner_idx_or_tuple, int):
                f_args_inner.append(primals[inner_idx_or_tuple])
            else:
                (inner_base_idx, view_tensor) = inner_idx_or_tuple
                base = primals[inner_base_idx]
                view_arg = gen_alias_from_base(base, view_tensor, view_tensor.requires_grad, replay_views=replay_views)
                f_args_inner.append(view_arg)
        return f_args_inner

    @simple_wraps(flat_fn)
    def wrapped_flat_fn(*args):
        unpacked_args = _unpack_synthetic_bases(args)
        aliased_args_with_metadata_mutations = [x for (i, x) in enumerate(unpacked_args) if i in self.aliased_arg_idx_with_metadata_mutations]
        (out, out_descs) = call_and_expect_output_descs(flat_fn, unpacked_args)
        if <MASK>:
            return ((*out, *aliased_args_with_metadata_mutations), (*out_descs, *[MetadataMutationAOTOutput(i) for i in range(len(self.aliased_arg_idx_with_metadata_mutations))]))
        else:
            return (out, out_descs)
    if config.debug_assert:
        ref_fw_metadata = run_functionalized_fw_and_collect_metadata(without_output_descs(wrapped_flat_fn), flat_args_descs=flat_args_descs_with_synthetic_bases, static_input_indices=aot_config.static_input_indices, keep_input_mutations=fw_metadata.keep_input_mutations, is_train=fw_metadata.is_train)(*flat_args_with_synthetic_bases)
        assert ref_fw_metadata == fw_metadata_updated, f'ref_metadata={pprint.pformat(partial_flatten_asdict(ref_fw_metadata))}, \nactual_metadata={pprint.pformat(partial_flatten_asdict(fw_metadata_updated))}'
    return (wrapped_flat_fn, flat_args_with_synthetic_bases, flat_args_descs_with_synthetic_bases, fw_metadata_updated)

