@final
def _clip_with_one_bound(self, threshold, method, axis, inplace):
    if axis is not None:
        axis = self._get_axis_number(axis)
    if <MASK>:
        if method.__name__ == 'le':
            return self._clip_with_scalar(None, threshold, inplace=inplace)
        return self._clip_with_scalar(threshold, None, inplace=inplace)
    if not isinstance(threshold, ABCSeries) and is_list_like(threshold):
        if isinstance(self, ABCSeries):
            threshold = self._constructor(threshold, index=self.index)
        else:
            threshold = self._align_for_op(threshold, axis, flex=None)[1]
    if is_list_like(threshold):
        fill_value = np.inf if method.__name__ == 'le' else -np.inf
        threshold_inf = threshold.fillna(fill_value)
    else:
        threshold_inf = threshold
    subset = method(threshold_inf, axis=axis) | isna(self)
    return self.where(subset, threshold, axis=axis, inplace=inplace)

def go(t: object, real_t: Tensor) -> None:
    if isinstance(t, FakeTensor):
        log.debug('maybe_propagate_real_tensors %s -> %s', id(t), id(real_t))
        t.real_tensor = real_t
        for (s, real_s) in zip(t.size(), real_t.size()):
            go(s, real_s)
        for (s, real_s) in zip(t.stride(), real_t.stride()):
            go(s, real_s)
        go(t.storage_offset(), real_t.storage_offset())
    elif <MASK>:
        if isinstance(t.node.expr, sympy.Symbol):
            assert self.shape_env is not None
            self.shape_env.set_unbacked_var_to_val(t.node.expr, real_t)
        elif isinstance((s := t.node.expr), sympy.Eq) and isinstance(s.lhs, sympy.Symbol) and (s.rhs == 1):
            assert self.shape_env is not None
            self.shape_env.set_unbacked_var_to_val(s, int(real_t))

def sym_ite(b, t, f):
    """SymInt-aware utility for ternary operator (``t if b else f``.)"""
    if <MASK>:
        return overrides.handle_torch_function(sym_ite, (b, t, f), b, t, f)
    assert isinstance(b, (SymBool, builtins.bool)) and type(t) is type(f)
    if isinstance(b, SymBool):
        return b.__sym_ite__(t, f)
    return t if b else f

def _clip(a, min=None, max=None, out=None, **kwargs):
    if a.dtype.kind in 'iu':
        if type(min) is int and min <= np.iinfo(a.dtype).min:
            min = None
        if type(max) is int and max >= np.iinfo(a.dtype).max:
            max = None
    if min is None and max is None:
        return um.positive(a, out=out, **kwargs)
    elif min is None:
        return um.minimum(a, max, out=out, **kwargs)
    elif <MASK>:
        return um.maximum(a, min, out=out, **kwargs)
    else:
        return um.clip(a, min, max, out=out, **kwargs)

def _backport_for_mobile_to_buffer(f_input, to_version):
    """Take a string containing a file name (file-like object).

    Args:
