@register_jagged_func(torch.ops.aten._nested_from_padded_tensor.default, 'padded: t, offsets: t, dummy: jt, ragged_idx: any?, min_seqlen: any?, max_seqlen: any?, sum_S: any?')
def _nested_from_padded_tensor_default(func, *args, **kwargs):
    (_, new_kwargs) = normalize_function(func, args=args, kwargs=kwargs, normalize_to_only_use_kwargs=True)
    (padded, offsets) = (new_kwargs['padded'], new_kwargs['offsets'])
    ragged_idx = new_kwargs.get('ragged_idx', 1)
    if <MASK>:
        padded = padded.transpose(ragged_idx, 1)
    padded_ragged_dim1_shape = padded.shape
    if padded.dim() > 3:
        padded = padded.flatten(start_dim=2)
    elif padded.dim() < 3:
        padded = padded.unsqueeze(-1)
    is_bool = padded.dtype is torch.bool
    if is_bool and padded.is_cuda:
        padded = padded.to(torch.half)
    values = torch.ops.aten._padded_dense_to_jagged_forward(padded, [offsets], new_kwargs['sum_S'])
    if is_bool and values.is_cuda:
        values = values.to(torch.bool)
    if len(padded_ragged_dim1_shape) > 3:
        values = values.unflatten(-1, padded_ragged_dim1_shape[2:])
    elif len(padded_ragged_dim1_shape) < 3:
        values = values.squeeze(-1)
    if ragged_idx > 1:
        values = values.transpose(ragged_idx - 1, 0)
    min_seqlen = new_kwargs['min_seqlen']
    max_seqlen = new_kwargs['max_seqlen']
    metadata_cache = {}
    if min_seqlen is not None:
        metadata_cache['min_seqlen'] = min_seqlen
    if max_seqlen is not None:
        metadata_cache['max_seqlen'] = max_seqlen
    return NestedTensor(values, offsets, _ragged_idx=ragged_idx, _metadata_cache=metadata_cache)

def generate_extern_kernel_args_decl_if_needed(self, op_overload: Union[torch._ops.OpOverload, torch._ops.HigherOrderOperator], raw_args: Sequence[Any], output_args: _OUTPUT_ARGS_TYPE, raw_outputs: Sequence[ir.Buffer]):
    """
        Generates declarations for external kernel arguments if needed, based on the provided
        operator and its arguments. It processes both input and output arguments, categorizing
        them into tensor and integer arguments for further code generation.
        """
    schema = None
    if isinstance(op_overload, torch._higher_order_ops.torchbind.CallTorchBind):
        obj = raw_args[0]
        method = raw_args[1]
        schema = op_overload.schema(obj, method)
    else:
        assert isinstance(op_overload, torch._ops.OpOverload), type(op_overload)
        schema = op_overload._schema
    assert schema is not None
    arg_types = [x.real_type for x in schema.arguments]
    return_types = [x.type for x in schema.returns]
    new_tensor_args = []
    new_int_args = []

    def fill_args(arg, arg_type):
        static_arg_types = (torch.FloatType, torch.BoolType, torch.StringType, torch.Type, torch.DeviceObjType)
        inductor_tensor_buffers = (ir.Buffer, ir.ReinterpretView)
        if isinstance(arg_type, torch.TensorType):
            assert isinstance(arg, inductor_tensor_buffers), f'got {type(arg)}'
            new_tensor_args.append(f'{arg.codegen_reference()}')
        elif isinstance(arg_type, torch.IntType):
            new_int_args.append(str(arg))
        elif isinstance(arg_type, torch.SymIntType):
            expr = arg.node.expr if isinstance(arg, torch.SymInt) else arg
            new_int_args.append(cexpr(expr))
        elif isinstance(arg_type, torch.NumberType):
            assert isinstance(arg, (int, float, bool))
            if isinstance(arg, int):
                new_int_args.append(str(arg))
        elif isinstance(arg, ir.TorchBindObject):
            pass
        elif isinstance(arg_type, torch.ListType):
            assert isinstance(arg, (list, tuple))
            if isinstance(arg_type.getElementType(), torch.TensorType):
                new_tensor_args.extend([f'{a.codegen_reference()}' for a in arg])
            elif isinstance(arg_type.getElementType(), torch.OptionalType) and isinstance(arg_type.getElementType().getElementType(), torch.TensorType):
                new_tensor_args.extend([f'{a.codegen_reference()}' for a in arg if a is not None])
            elif <MASK>:
                new_int_args.extend([str(a) for a in arg])
            elif isinstance(arg_type.getElementType(), torch.SymIntType):
                expressions = [a.node.expr if isinstance(a, torch.SymInt) else a for a in arg]
                new_int_args.extend([cexpr(expr) for expr in expressions])
            elif isinstance(arg_type.getElementType(), torch.NumberType):
                is_int_type = [isinstance(a, int) for a in arg]
                if any(is_int_type):
                    assert all(is_int_type), 'AOTInductor only supports int scalars of the same type'
                    new_int_args.extend([str(a) for a in arg])
            else:
                assert isinstance(arg_type.getElementType(), static_arg_types), f'Fall through arguments must be one of static_arg_types, got {type(arg_type)}'
        else:
            assert isinstance(arg_type, static_arg_types), f'Fall through arguments must be one of static_arg_types, got {type(arg_type)}'
    for (arg, arg_type) in zip(raw_args, arg_types):
        if arg is not None:
            if isinstance(arg_type, torch.OptionalType):
                fill_args(arg, arg_type.getElementType())
            else:
                fill_args(arg, arg_type)

    def fill_output_arg(arg: str, return_type: torch.JitType, is_mutated_output: bool) -> None:
        if isinstance(return_type, torch.TensorType):
            if not is_mutated_output:
                self.writeline(f'AtenTensorHandle {arg}_handle;  // output buffer')
                self.writeline(f'AOTI_TORCH_ERROR_CODE_CHECK(aoti_torch_new_uninitialized_tensor(&{arg}_handle));')
                self.writeline(f'RAIIAtenTensorHandle {arg}({arg}_handle);')
            new_tensor_args.append(f'{arg}')
        elif isinstance(return_type, torch.SymIntType):
            raise NotImplementedError('NYI support for return type: SymInt')
        elif isinstance(return_type, torch.ListType) and isinstance(return_type.getElementType(), torch.SymIntType):
            raise NotImplementedError('NYI support for return type: List[SymInt]')
        else:
            raise AssertionError(f'Unsupported return type found: {return_type}')
    for return_type in return_types:
        if isinstance(return_type, (torch.TensorType, torch.NoneType, torch.IntType)):
            pass
        elif isinstance(return_type, torch.OptionalType):
            assert isinstance(return_type.getElementType(), torch.TensorType)
        elif isinstance(return_type, torch.ListType):
            assert isinstance(return_type.getElementType(), torch.TensorType)
        else:
            raise NotImplementedError(f'return type {return_type} is not yet supported.')
    for (output_arg, raw_output_arg) in zip(output_args, raw_outputs):
        if output_arg is None:
            continue
        elif isinstance(raw_output_arg, int):
            new_int_args.append(str(raw_output_arg))
        elif isinstance(output_arg, list):
            for out in output_arg:
                assert out is not None, out
                fill_output_arg(out, torch.TensorType.get(), isinstance(raw_output_arg, ir.MutationOutput))
        else:
            fill_output_arg(output_arg, torch.TensorType.get(), isinstance(raw_output_arg, ir.MutationOutput))
    return (new_tensor_args, new_int_args)

def can_inplace(self, read_dep: dependencies.Dep) -> bool:
    if <MASK>:
        return False
    if any((out.get_aliases() for out in self.get_outputs())):
        return False
    if len(self.read_writes.writes) == 1 and isinstance(read_dep, dependencies.MemoryDep):
        write_dep = next(iter(self.read_writes.writes))
        assert isinstance(write_dep, dependencies.MemoryDep), f'type(write_dep)={type(write_dep)!r}'
        return read_dep.index == write_dep.index and read_dep.size == write_dep.size
    return False

def fn(*args):
    if self._user_post_bw_hook is not None and is_bw:
        self._user_post_bw_hook(w_mod(), args)
    if name in self.parents:
        self._active_module_cnt[name] -= 1
        if self._active_module_cnt[name] == 0:
            self.parents.remove(name)
    elif <MASK>:
        raise RuntimeError('The Module hierarchy tracking is wrong. Report a bug to PyTorch')

def l1_loss(input: Tensor, target: Tensor, size_average: Optional[bool]=None, reduce: Optional[bool]=None, reduction: str='mean', weight: Optional[Tensor]=None) -> Tensor:
    """Compute the L1 loss, with optional weighting.

    Function that takes the mean element-wise absolute value difference.

    See :class:`~torch.nn.L1Loss` for details.

    Args:
        input (Tensor): Predicted values.
        target (Tensor): Ground truth values.
        size_average (bool, optional): Deprecated (see :attr:`reduction`).
        reduce (bool, optional): Deprecated (see :attr:`reduction`).
        reduction (str, optional): Specifies the reduction to apply to the output:
                                   'none' | 'mean' | 'sum'. 'mean': the mean of the output is taken.
                                   'sum': the output will be summed. 'none': no reduction will be applied.
                                   Default: 'mean'.
        weight (Tensor, optional): Weights for each sample. Default: None.

    Returns:
        Tensor: L1 loss (optionally weighted).
    """
    if has_torch_function_variadic(input, target):
        return handle_torch_function(l1_loss, (input, target, weight), input, target, size_average=size_average, reduce=reduce, reduction=reduction)
    if target.size() != input.size():
        warnings.warn(f'Using a target size ({target.size()}) that is different to the input size ({input.size()}). This will likely lead to incorrect results due to broadcasting. Please ensure they have the same size.', stacklevel=2)
    if size_average is not None or reduce is not None:
        reduction = _Reduction.legacy_get_string(size_average, reduce)
    (expanded_input, expanded_target) = torch.broadcast_tensors(input, target)
    if <MASK>:
        if weight.size() != input.size():
            raise ValueError('Weights and input must have the same size.')
        absolute_errors = torch.abs(expanded_input - expanded_target)
        weighted_absolute_errors = absolute_errors * weight
        if reduction == 'none':
            return weighted_absolute_errors
        elif reduction == 'sum':
            return torch.sum(weighted_absolute_errors)
        elif reduction == 'mean':
            return torch.sum(weighted_absolute_errors) / torch.sum(weight)
        else:
            raise ValueError(f"Invalid reduction mode: {reduction}. Expected one of 'none', 'mean', 'sum'.")
    else:
        return torch._C._nn.l1_loss(expanded_input, expanded_target, _Reduction.get_enum(reduction))

@register.tag('localtime')
def localtime_tag(parser, token):
    """
    Force or prevent conversion of datetime objects to local time,
    regardless of the value of ``settings.USE_TZ``.

    Sample usage::

        {% localtime off %}{{ value_in_utc }}{% endlocaltime %}
    """
    bits = token.split_contents()
    if <MASK>:
        use_tz = True
    elif len(bits) > 2 or bits[1] not in ('on', 'off'):
        raise TemplateSyntaxError("%r argument should be 'on' or 'off'" % bits[0])
    else:
        use_tz = bits[1] == 'on'
    nodelist = parser.parse(('endlocaltime',))
    parser.delete_first_token()
    return LocalTimeNode(nodelist, use_tz)

@impl(quantized_decomposed_lib, 'dequantize_per_tensor.tensor', 'Meta')
def dequantize_per_tensor_tensor_meta(input: torch.Tensor, scale: torch.Tensor, zero_point: torch.Tensor, quant_min: int, quant_max: int, dtype: torch.dtype, *, out_dtype: Optional[torch.dtype]=None) -> torch.Tensor:
    if out_dtype is None:
        out_dtype = torch.float32
    assert zero_point.numel() == 1, f'Expecting zero_point tensor to be one element, but received : {zero_point.numel()}'
    assert scale.numel() == 1, f'Expecting scale tensor to be one element, but received : {scale.numel()}'
    assert input.dtype == dtype, f'Expecting input to have dtype: {dtype}'
    if <MASK>:
        return torch.empty_like(input, dtype=out_dtype)
    else:
        raise ValueError(f'Unsupported dtype in dequantize_per_tensor: {dtype}')

def var_getattr(self, tx: 'InstructionTranslator', name: str) -> 'VariableTracker':
    from . import ConstantVariable, EnumVariable
    source = AttrSource(self.source, name) if self.source is not None else None
    if name == '__name__':
        return ConstantVariable.create(self.value.__name__)
    elif name == '__qualname__':
        return ConstantVariable.create(self.value.__qualname__)
    elif name == '__dict__':
        options = {'source': source}
        return variables.GetAttrVariable(self, name, **options)
    elif name == '__mro__':
        attr_source = self.source and TypeMROSource(self.source)
        return VariableTracker.build(tx, self.value.__mro__, attr_source)
    if self.value in {collections.OrderedDict, collections.defaultdict} and name == 'fromkeys':
        return super().var_getattr(tx, name)
    try:
        obj = inspect.getattr_static(self.value, name)
    except AttributeError:
        if type(self.value) is type:
            raise_observed_exception(AttributeError, tx, msg=f"type object '{self.value.__name__}' has no attribute '{name}'")
        else:
            obj = None
    if <MASK>:
        return super().var_getattr(tx, name)
    if name in cmp_name_to_op_mapping and (not isinstance(obj, types.FunctionType)):
        return variables.GetAttrVariable(self, name, source=source)
    if isinstance(obj, staticmethod):
        return VariableTracker.build(tx, obj.__get__(self.value), source)
    elif isinstance(obj, classmethod):
        if isinstance(obj.__func__, property):
            fget_vt = VariableTracker.build(tx, obj.__func__.fget)
            return fget_vt.call_function(tx, [self], {})
        return variables.UserMethodVariable(obj.__func__, self, source=source)
    elif isinstance(obj, types.ClassMethodDescriptorType):
        func = obj.__get__(None, self.value)
        return VariableTracker.build(tx, func, source)
    elif source:
        if inspect.ismemberdescriptor(obj):
            return VariableTracker.build(tx, obj.__get__(self.value), source)
    if ConstantVariable.is_literal(obj):
        return ConstantVariable.create(obj)
    elif isinstance(obj, enum.Enum):
        return EnumVariable(obj)
    elif self.value is collections.OrderedDict:
        return variables.GetAttrVariable(self, name)
    elif name in getattr(self.value, '__dict__', {}) or (self.value.__module__.startswith('torch.') or self.value.__module__ == 'torch'):
        if source:
            return VariableTracker.build(tx, obj, source)
    if source and (not inspect.ismethoddescriptor(obj)) and (not is_wrapper_or_member_descriptor(obj)):
        return VariableTracker.build(tx, obj, source)
    return super().var_getattr(tx, name)

def _getitem_axis(self, key, axis: AxisInt):
    if key is Ellipsis:
        key = slice(None)
    elif isinstance(key, ABCDataFrame):
        raise IndexError('DataFrame indexer is not allowed for .iloc\nConsider using .loc for automatic alignment.')
    if <MASK>:
        return self._get_slice_axis(key, axis=axis)
    if is_iterator(key):
        key = list(key)
    if isinstance(key, list):
        key = np.asarray(key)
    if com.is_bool_indexer(key):
        self._validate_key(key, axis)
        return self._getbool_axis(key, axis=axis)
    elif is_list_like_indexer(key):
        return self._get_list_axis(key, axis=axis)
    else:
        key = item_from_zerodim(key)
        if not is_integer(key):
            raise TypeError('Cannot index by location index with a non-integer key')
        self._validate_integer(key, axis)
        return self.obj._ixs(key, axis=axis)

def create_functional_call(mod, params_spec, params_len, store_orig_mod=False, strict_out_tuple=True):

    @simple_wraps(mod)
    def functional_call(*args, **kwargs):
        flat_params = args[:params_len]
        if isinstance(params_spec, TreeSpec):
            params = pytree.tree_unflatten(flat_params, params_spec)
        else:
            assert isinstance(params_spec, list)
            params = dict(zip(params_spec, flat_params))
        with stateless._reparametrize_module(mod, params), maybe_disable_thunkify():
            if isinstance(mod, torch.fx.GraphModule):
                if kwargs:
                    arg_list = list(args[params_len:])
                    arg_list.extend(list(kwargs.values()))
                    args = tuple(arg_list)
                else:
                    args = args[params_len:]
                with fx_traceback.preserve_node_meta(), warnings.catch_warnings():
                    warnings.filterwarnings('ignore', 'Anomaly Detection has been enabled.')
                    with torch.autograd.detect_anomaly(check_nan=False):
                        fake_mode = detect_fake_mode()
                        assert fake_mode is not None
                        fake_mode.epoch += 1
                        out = PropagateUnbackedSymInts(mod).run(*args)
            else:
                out = mod(*args[params_len:], **kwargs)
        if strict_out_tuple and (not isinstance(out, (tuple, list))):
            raise RuntimeError('Graph output must be a (). This is so that we can avoid pytree processing of the outputs. Please change the module to have tuple outputs or use aot_module instead.')
        return out
    if <MASK>:
        functional_call._orig_mod = mod
    return functional_call

def _maybe_null_out(result: np.ndarray | float | NaTType, axis: AxisInt | None, mask: npt.NDArray[np.bool_] | None, shape: tuple[int, ...], min_count: int=1, datetimelike: bool=False) -> np.ndarray | float | NaTType:
    """
    Returns
    -------
    Dtype
        The product of all elements on a given axis. ( NaNs are treated as 1)
    """
    if mask is None and min_count == 0:
        return result
    if axis is not None and isinstance(result, np.ndarray):
        if <MASK>:
            null_mask = mask.shape[axis] - mask.sum(axis) - min_count < 0
        else:
            below_count = shape[axis] - min_count < 0
            new_shape = shape[:axis] + shape[axis + 1:]
            null_mask = np.broadcast_to(below_count, new_shape)
        if np.any(null_mask):
            if datetimelike:
                result[null_mask] = iNaT
            elif is_numeric_dtype(result):
                if np.iscomplexobj(result):
                    result = result.astype('c16')
                elif not is_float_dtype(result):
                    result = result.astype('f8', copy=False)
                result[null_mask] = np.nan
            else:
                result[null_mask] = None
    elif result is not NaT:
        if check_below_min_count(shape, mask, min_count):
            result_dtype = getattr(result, 'dtype', None)
            if is_float_dtype(result_dtype):
                result = result_dtype.type('nan')
            else:
                result = np.nan
    return result

def get_useparameters(block, param_map=None):
    global f90modulevars
    if param_map is None:
        param_map = {}
    usedict = get_usedict(block)
    if <MASK>:
        return param_map
    for (usename, mapping) in list(usedict.items()):
        usename = usename.lower()
        if usename not in f90modulevars:
            outmess('get_useparameters: no module %s info used by %s\n' % (usename, block.get('name')))
            continue
        mvars = f90modulevars[usename]
        params = get_parameters(mvars)
        if not params:
            continue
        if mapping:
            errmess(f'get_useparameters: mapping for {mapping} not impl.\n')
        for (k, v) in list(params.items()):
            if k in param_map:
                outmess('get_useparameters: overriding parameter %s with value from module %s\n' % (repr(k), repr(usename)))
            param_map[k] = v
    return param_map

@tf_export(v1=['saved_model.classification_signature_def', 'saved_model.signature_def_utils.classification_signature_def'])
@deprecation.deprecated_endpoints('saved_model.signature_def_utils.classification_signature_def')
def classification_signature_def(examples, classes, scores):
    """Creates classification signature from given examples and predictions.

  This function produces signatures intended for use with the TensorFlow Serving
  Classify API (tensorflow_serving/apis/prediction_service.proto), and so
  constrains the input and output types to those allowed by TensorFlow Serving.

  Args:
    examples: A string `Tensor`, expected to accept serialized tf.Examples.
    classes: A string `Tensor`.  Note that the ClassificationResponse message
      requires that class labels are strings, not integers or anything else.
    scores: a float `Tensor`.

  Returns:
    A classification-flavored signature_def.

  Raises:
    ValueError: If examples is `None`.
  """
    if examples is None:
        raise ValueError('Classification `examples` cannot be None.')
    if not isinstance(examples, tensor_lib.Tensor):
        raise ValueError(f'Classification `examples` must be a string Tensor. Found `examples` of type {type(examples)}.')
    if classes is None and scores is None:
        raise ValueError('Classification `classes` and `scores` cannot both be None.')
    input_tensor_info = utils.build_tensor_info(examples)
    if input_tensor_info.dtype != types_pb2.DT_STRING:
        raise ValueError(f'Classification input tensors must be of type string. Found tensors of type {input_tensor_info.dtype}')
    signature_inputs = {signature_constants.CLASSIFY_INPUTS: input_tensor_info}
    signature_outputs = {}
    if classes is not None:
        classes_tensor_info = utils.build_tensor_info(classes)
        if <MASK>:
            raise ValueError(f'Classification classes must be of type string Tensor. Found tensors of type {classes_tensor_info.dtype}.`')
        signature_outputs[signature_constants.CLASSIFY_OUTPUT_CLASSES] = classes_tensor_info
    if scores is not None:
        scores_tensor_info = utils.build_tensor_info(scores)
        if scores_tensor_info.dtype != types_pb2.DT_FLOAT:
            raise ValueError('Classification scores must be a float Tensor.')
        signature_outputs[signature_constants.CLASSIFY_OUTPUT_SCORES] = scores_tensor_info
    signature_def = build_signature_def(signature_inputs, signature_outputs, signature_constants.CLASSIFY_METHOD_NAME)
    return signature_def

@classmethod
def _check_field_name_clashes(cls):
    """Forbid field shadowing in multi-table inheritance."""
    errors = []
    used_fields = {}
    for parent in cls._meta.all_parents:
        for f in parent._meta.local_fields:
            clash = used_fields.get(f.name) or used_fields.get(f.attname) or None
            if clash:
                errors.append(checks.Error("The field '%s' from parent model '%s' clashes with the field '%s' from parent model '%s'." % (clash.name, clash.model._meta, f.name, f.model._meta), obj=cls, id='models.E005'))
            used_fields[f.name] = f
            used_fields[f.attname] = f
    for parent in cls._meta.all_parents:
        for f in parent._meta.get_fields():
            if f not in used_fields:
                used_fields[f.name] = f
    for parent_link in cls._meta.parents.values():
        if not parent_link:
            continue
        clash = used_fields.get(parent_link.name) or None
        if clash:
            errors.append(checks.Error(f"The field '{parent_link.name}' clashes with the field '{clash.name}' from model '{clash.model._meta}'.", obj=cls, id='models.E006'))
    for f in cls._meta.local_fields:
        clash = used_fields.get(f.name) or used_fields.get(f.attname) or None
        id_conflict = f.name == 'id' and clash and (clash.name == 'id') and (clash.model == cls)
        if <MASK>:
            errors.append(checks.Error("The field '%s' clashes with the field '%s' from model '%s'." % (f.name, clash.name, clash.model._meta), obj=f, id='models.E006'))
        used_fields[f.name] = f
        used_fields[f.attname] = f
    return errors

def dtensor_reduce(strategy, reduce_op, value, axis):
    """Implement dtensor based strategy.reduce()."""
    distribute_lib._require_cross_replica_or_default_context_extended(strategy.extended)
    if isinstance(reduce_op, str):
        reduce_op = reduce_util.ReduceOp(reduce_op.upper())
    distributed_input = is_distributed_value(value)
    if <MASK>:
        destinations = device_util.current() or strategy.extended._default_device or '/device:CPU:0'
        devices = cross_device_ops_lib.get_devices_from(destinations)
        with ops.device(devices[0]):
            return array_ops.identity(cross_device_ops_lib.reduce_non_distributed_value(reduce_op, value, destinations, strategy.num_replicas_in_sync))
    value = convert_inputs_to_dtensor(value, strategy._mesh)
    if reduce_op == reduce_util.ReduceOp.MEAN:
        reduce_op = math_ops.reduce_mean
    else:
        reduce_op = math_ops.reduce_sum
    if d_api.fetch_layout(value).is_fully_replicated():
        if axis is not None:
            value = reduce_op(value, axis=axis)
    else:
        new_shape = [strategy.num_replicas_in_sync, -1]
        if len(value.shape) > 1:
            new_shape.extend(array_ops.shape(value)[1:])
        value = array_ops.reshape(value, new_shape)
        if axis is not None:
            value = reduce_op(value, axis=axis + 1)
        value = reduce_op(value, axis=0)
    return value

def _get_torch_related_args(include_pytorch: bool, aot_mode: bool) -> tuple[list[str], list[str], list[str]]:
    from torch.utils.cpp_extension import include_paths, TORCH_LIB_PATH
    libraries = []
    include_dirs = include_paths()
    if <MASK>:
        libraries_dirs = [TORCH_LIB_PATH]
        if sys.platform != 'darwin' and (not config.is_fbcode()):
            libraries.extend(['torch', 'torch_cpu'])
            if not aot_mode:
                libraries.append('torch_python')
    else:
        libraries_dirs = []
        if config.aot_inductor.cross_target_platform == 'windows':
            aoti_shim_library = config.aot_inductor.aoti_shim_library
            assert aoti_shim_library, "'config.aot_inductor.aoti_shim_library' must be set when 'cross_target_platform' is 'windows'."
            if isinstance(aoti_shim_library, str):
                libraries.append(aoti_shim_library)
            else:
                assert isinstance(aoti_shim_library, list)
                libraries.extend(aoti_shim_library)
    if config.aot_inductor.cross_target_platform == 'windows':
        assert config.aot_inductor.aoti_shim_library_path, ("'config.aot_inductor.aoti_shim_library_path' must be set to the path of the AOTI shim library", " when 'cross_target_platform' is 'windows'.")
        libraries_dirs.append(config.aot_inductor.aoti_shim_library_path)
    if _IS_WINDOWS:
        libraries.append('sleef')
    return (include_dirs, libraries_dirs, libraries)

def _check_linear_and_broadcast_op(linear_node, other, has_reshape):
    weight_node = linear_node.args[2] if linear_node.target is aten.addmm.default else linear_node.args[1]
    bias_node = linear_node.args[0] if linear_node.target is aten.addmm.default else None
    if weight_node.op != 'get_attr':
        return False
    if bias_node is not None and bias_node.op != 'get_attr':
        return False
    if not isinstance(other, int) and (not isinstance(other, float)) and (other.op != 'get_attr'):
        return False
    if len(weight_node.users) != 1:
        return False
    weight_meta_value = weight_node.meta.get('val')
    if weight_meta_value is None:
        return False
    if not weight_meta_value.is_floating_point():
        return False
    if isinstance(other, torch.fx.Node) and other.op == 'get_attr':
        other_meta_value = other.meta.get('val')
        if not other_meta_value.is_floating_point():
            return False
        if <MASK>:
            if not linear_node.meta.get('_allow_mixed_dtype_folding', False):
                return False
            if other_meta_value.dtype != torch.float and weight_meta_value.dtype not in (torch.float16, torch.bfloat16):
                return False
        if not _op_not_broadcasting_with_linear(weight_meta_value, other_meta_value, has_reshape):
            return False
    elif not isinstance(other, float):
        return False
    return True

def _pprint_seq(seq: ListLike, _nest_lvl: int=0, max_seq_items: int | None=None, **kwds: Any) -> str:
    """
    internal. pprinter for iterables. you should probably use pprint_thing()
    rather than calling this directly.

    bounds length of printed sequence, depending on options
    """
    if isinstance(seq, set):
        fmt = '{{{body}}}'
    elif isinstance(seq, frozenset):
        fmt = 'frozenset({{{body}}})'
    else:
        fmt = '[{body}]' if hasattr(seq, '__setitem__') else '({body})'
    if <MASK>:
        max_items = None
    else:
        max_items = max_seq_items or get_option('max_seq_items') or len(seq)
    s = iter(seq)
    r = []
    max_items_reached = False
    for (i, item) in enumerate(s):
        if max_items is not None and i >= max_items:
            max_items_reached = True
            break
        r.append(pprint_thing(item, _nest_lvl + 1, max_seq_items=max_seq_items, **kwds))
    body = ', '.join(r)
    if max_items_reached:
        body += ', ...'
    elif isinstance(seq, tuple) and len(seq) == 1:
        body += ','
    return fmt.format(body=body)

def arg_type_tensor_or_tensor_list_like(self, arg: object) -> bool:
    is_tensor = isinstance(arg, DTensorSpec)
    if is_tensor:
        return True
    if <MASK>:
        return False
    return all((isinstance(e, DTensorSpec) or e is None for e in arg))

def method_name(self) -> str:
    if <MASK>:
        return 'size'
    elif self is TensorProperty.STRIDE:
        return 'stride'
    elif self is TensorProperty.STORAGE_OFFSET:
        return 'storage_offset'
    else:
