def __enter__(self):
    cur_stream = self.stream
    if <MASK>:
        return
    self.src_prev_stream = torch.cuda.current_stream(None)
    if self.src_prev_stream.device != cur_stream.device:
        with device(cur_stream.device):
            self.dst_prev_stream = torch.cuda.current_stream(cur_stream.device)
    torch.cuda.set_stream(cur_stream)

def get_fma_per_cycle_per_sm_tensor_cores(self, data_type: dtype) -> int:
    hardcoded_device_values = {'int8_80': 2048, 'fp16_80': 1024, 'fp32_80': 512, 'fp64_80': 64, 'int8_90': 4096, 'fp8_90': 4096, 'fp16_90': 2048, 'fp32_90': 1024, 'fp64_90': 128, 'int8_100': 8192, 'fp8_100': 8192, 'fp16_100': 4096, 'fp32_100': 2048}
    dict_key = ''
    if data_type is torch.float16:
        dict_key = f'fp16_{self.compute_capability}'
    elif data_type is torch.bfloat16:
        dict_key = f'fp16_{self.compute_capability}'
    elif data_type is torch.float32:
        dict_key = f'fp32_{self.compute_capability}'
    elif <MASK>:
        dict_key = f'int8_{self.compute_capability}'
    elif data_type is torch.float64:
        dict_key = f'fp64_{self.compute_capability}'
    else:
        dict_key = 'unknown'
    if dict_key not in hardcoded_device_values.keys():
        raise RuntimeError(f'No data for sm_{self.compute_capability} and {data_type}.')
    return hardcoded_device_values[dict_key]

def test_not_share_gpu(self):
    num_gpus = len(context.context().list_physical_devices('GPU'))
    if num_gpus != 2 and num_gpus != 4:
        self.skipTest('requires 2 or 4 GPUs')
    cluster_spec = multi_worker_test_base.create_cluster_spec(has_chief=True, num_workers=1)

    def cuda_visible_devices_fn():
        return os.getenv('CUDA_VISIBLE_DEVICES')
    runner = multi_process_runner.MultiProcessRunner(cuda_visible_devices_fn, cluster_spec, share_gpu=False)
    runner.start()
    result = runner.join()
    if <MASK>:
        self.assertAllEqual(sorted(result.return_value), ['0', '1'])
    else:
        self.assertAllEqual(sorted(result.return_value), ['0,2', '1,3'])

    def num_gpus_fn():
        return len(context.context().list_physical_devices('GPU'))
    runner = multi_process_runner.MultiProcessRunner(num_gpus_fn, cluster_spec, share_gpu=False)
    runner.start()
    result = runner.join()
    if num_gpus == 2:
        self.assertAllEqual(result.return_value, [1, 1])
    else:
        self.assertAllEqual(result.return_value, [2, 2])

def get_tolerance_and_cosine_flag(self, is_training, current_device, name):
    tolerance = 0.0001
    cosine = self.args.cosine
    if self.args.float16 or self.args.amp:
        if self.args.freezing and (freezing := self._tolerance['freezing']):
            higher_fp16 = freezing.get('higher_fp16', None)
            even_higher = freezing.get('even_higher', None)
            if <MASK>:
                return (0.01, cosine)
            elif even_higher and name in even_higher:
                return (8 * 0.01, cosine)
        if name in self._tolerance['higher_fp16']:
            return (0.01, cosine)
        elif name in self._tolerance['even_higher']:
            return (8 * 0.01, cosine)
        return (0.001, cosine)
    if self.args.bfloat16:
        if name in self._tolerance['higher_bf16']:
            return (0.01, cosine)
        elif current_device == 'xpu' and name in self._tolerance['higher_bf16_xpu']:
            return (8 * 0.01, cosine)
    if is_training and (current_device == 'cuda' or current_device == 'xpu'):
        tolerance = 0.001
        if name in self._tolerance['cosine']:
            cosine = True
        elif name in self._tolerance['higher']:
            tolerance = 0.001
        elif name in self._tolerance['even_higher']:
            tolerance = 8 * 0.01
    return (tolerance, cosine)

def filter_op(self, op: 'CKGroupedConvFwdOp'):
    metas = [T.get_layout() for T in [*self.input_nodes, self.output_node] if T is not None]
    X_meta = metas[0]
    W_meta = metas[1]
    Y_meta = metas[-1]
    if op.a_element_dtype != self._TORCH_DTYPE_TO_CK[X_meta.dtype]:
        return None
    if op.b_element_dtype != self._TORCH_DTYPE_TO_CK[W_meta.dtype]:
        return None
    if op.e_element_dtype != self._TORCH_DTYPE_TO_CK[Y_meta.dtype]:
        return None
    if <MASK>:
        return None
    if op.b_layout != torch_layout_to_ck_weight_layout(W_meta):
        return None
    if op.e_layout != torch_layout_to_ck_output_layout(Y_meta):
        return None
    if op.n_dim_spatial != self.n_spatial_dimensions:
        return None
    if 'Default' not in op.conv_forward_specialization:
        return None
    return op

def bind_symbols(self, placeholders: Sequence[FakeTensor], args: Sequence[Tensor]) -> dict[sympy.Symbol, int]:
    """
        Given a paired list of placeholders (fake tensors with
        symbolic sizes) and concrete arguments (regular tensors
        with real sizes), returns a dictionary mapping each
        symbol to its real value.  So for example, if you
        have a placeholder with size (s0, s1), binding
        (2, 4) to it will give you {s0: 2, s1: 4}.  This is
        not guaranteed to bind ALL symbols in the ShapeEnv;
        we can't bind a symbol if it doesn't occur in any placeholder,
        and symbols that already have replacements won't get bindings.

        This is a little duplicative with evaluate_guards but
        it's different enough that it seemed cleanest to make
        another copy.  This assumes the guards are already checked,
        though if it's cheap we'll check for shenanigans
        """
    bindings: dict[sympy.Symbol, int] = {}

    def bind_symint(arg: object, val: object) -> None:
        if isinstance(val, SymInt):
            assert isinstance(arg, int)
            s = val.node.expr
            if <MASK>:
                if s in bindings:
                    assert bindings[s] == arg, f'{bindings[s]} != {arg}'
                else:
                    bindings[s] = arg
            elif isinstance(-s, sympy.Symbol):
                if -s in bindings:
                    assert bindings[-s] == -arg, f'{bindings[-s]} != {-arg}'
                else:
                    bindings[-s] = -arg
    for (t, arg) in zip(placeholders, args):
        if t is None:
            continue
        if isinstance(t, SymInt):
            bind_symint(arg, t)
            continue
        assert isinstance(t, torch.Tensor)
        for (i, s) in enumerate(t.size()):
            bind_symint(arg.size(i), s)
        for (i, s) in enumerate(t.stride()):
            bind_symint(arg.stride(i), s)
        bind_symint(arg.storage_offset(), t.storage_offset())
    return bindings

def _multi_worker_session(kwargs):
    """Returns a context manager that enters a session that is configured for the MultiWorkerMirroredStrategy.

  Args:
    kwargs: a dict. Keyword arguments passed to the test.

  Returns:
    A context manager. If MultiWorkerMirroredStrategy is the  one and only one
    strategy in kwargs and it's in graph mode, it's the session that is
    configured for that strategy.  Otherwise, it's a no-op context manager.
  """
    strategy = None
    for (_, v) in kwargs.items():
        if isinstance(v, distribute_lib.StrategyBase):
            if <MASK>:
                logging.warning('The test uses multiple strategies. Skipping entering a session that is configured for the strategy.')
                return ops.NullContextmanager()
            strategy = v
    if context.executing_eagerly() or not isinstance(strategy, collective_all_reduce_strategy.CollectiveAllReduceStrategy):
        return ops.NullContextmanager()
    sess_config = copy.deepcopy(context.context().config)
    sess_config = strategy.update_config_proto(sess_config)
    target = strategy.cluster_resolver.master()
    return session.Session(config=sess_config, target=target).as_default()

def _check_params(self):
    if self.type not in (Integral, Real, RealNotInt):
        raise ValueError(f'type must be either numbers.Integral, numbers.Real or RealNotInt. Got {self.type} instead.')
    if self.closed not in ('left', 'right', 'both', 'neither'):
        raise ValueError(f"closed must be either 'left', 'right', 'both' or 'neither'. Got {self.closed} instead.")
    if self.type is Integral:
        suffix = 'for an interval over the integers.'
        if self.left is not None and (not isinstance(self.left, Integral)):
            raise TypeError(f'Expecting left to be an int {suffix}')
        if self.right is not None and (not isinstance(self.right, Integral)):
            raise TypeError(f'Expecting right to be an int {suffix}')
        if self.left is None and self.closed in ('left', 'both'):
            raise ValueError(f"left can't be None when closed == {self.closed} {suffix}")
        if self.right is None and self.closed in ('right', 'both'):
            raise ValueError(f"right can't be None when closed == {self.closed} {suffix}")
    else:
        if self.left is not None and (not isinstance(self.left, Real)):
            raise TypeError('Expecting left to be a real number.')
        if self.right is not None and (not isinstance(self.right, Real)):
            raise TypeError('Expecting right to be a real number.')
    if <MASK>:
        raise ValueError(f"right can't be less than left. Got left={self.left} and right={self.right}")

def _parse_latex_css_conversion(styles: CSSList) -> CSSList:
    """
    Convert CSS (attribute,value) pairs to equivalent LaTeX (command,options) pairs.

    Ignore conversion if tagged with `--latex` option, skipped if no conversion found.
    """

    def font_weight(value, arg) -> tuple[str, str] | None:
        if value in ('bold', 'bolder'):
            return ('bfseries', f'{arg}')
        return None

    def font_style(value, arg) -> tuple[str, str] | None:
        if value == 'italic':
            return ('itshape', f'{arg}')
        if value == 'oblique':
            return ('slshape', f'{arg}')
        return None

    def color(value, user_arg, command, comm_arg):
        """
        CSS colors have 5 formats to process:

         - 6 digit hex code: "#ff23ee"     --> [HTML]{FF23EE}
         - 3 digit hex code: "#f0e"        --> [HTML]{FF00EE}
         - rgba: rgba(128, 255, 0, 0.5)    --> [rgb]{0.502, 1.000, 0.000}
         - rgb: rgb(128, 255, 0,)          --> [rbg]{0.502, 1.000, 0.000}
         - string: red                     --> {red}

        Additionally rgb or rgba can be expressed in % which is also parsed.
        """
        arg = user_arg if user_arg != '' else comm_arg
        if value[0] == '#' and len(value) == 7:
            return (command, f'[HTML]{{{value[1:].upper()}}}{arg}')
        if value[0] == '#' and len(value) == 4:
            val = f'{value[1].upper() * 2}{value[2].upper() * 2}{value[3].upper() * 2}'
            return (command, f'[HTML]{{{val}}}{arg}')
        elif value[:3] == 'rgb':
            r = re.findall('(?<=\\()[0-9\\s%]+(?=,)', value)[0].strip()
            r = float(r[:-1]) / 100 if '%' in r else int(r) / 255
            g = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[0].strip()
            g = float(g[:-1]) / 100 if '%' in g else int(g) / 255
            if value[3] == 'a':
                b = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[1].strip()
            else:
                b = re.findall('(?<=,)[0-9\\s%]+(?=\\))', value)[0].strip()
            b = float(b[:-1]) / 100 if '%' in b else int(b) / 255
            return (command, f'[rgb]{{{r:.3f}, {g:.3f}, {b:.3f}}}{arg}')
        else:
            return (command, f'{{{value}}}{arg}')
    CONVERTED_ATTRIBUTES: dict[str, Callable] = {'font-weight': font_weight, 'background-color': partial(color, command='cellcolor', comm_arg='--lwrap'), 'color': partial(color, command='color', comm_arg=''), 'font-style': font_style}
    latex_styles: CSSList = []
    for (attribute, value) in styles:
        if isinstance(value, str) and '--latex' in value:
            latex_styles.append((attribute, value.replace('--latex', '')))
        if attribute in CONVERTED_ATTRIBUTES:
            arg = ''
            for x in ['--wrap', '--nowrap', '--lwrap', '--dwrap', '--rwrap']:
                if x in str(value):
                    (arg, value) = (x, _parse_latex_options_strip(value, x))
                    break
            latex_style = CONVERTED_ATTRIBUTES[attribute](value, arg)
            if <MASK>:
                latex_styles.extend([latex_style])
    return latex_styles

def _check_file_or_buffer(self, f, engine: CSVEngine) -> None:
    if is_file_like(f) and engine != 'c' and (not hasattr(f, '__iter__')):
        raise ValueError("The 'python' engine cannot iterate through this file buffer.")
    if hasattr(f, 'encoding'):
        file_encoding = f.encoding
        orig_reader_enc = self.orig_options.get('encoding', None)
        any_none = file_encoding is None or orig_reader_enc is None
        if <MASK>:
            file_path = getattr(f, 'name', None)
            raise ValueError(f'The specified reader encoding {orig_reader_enc} is different from the encoding {file_encoding} of file {file_path}.')

def _test_send_recv_with_tag(self, profiler_ctx):
    rank = dist.get_rank()
    world_size = dist.get_world_size()
    send_recv_size = 10
    tensor = _build_tensor(send_recv_size, value=rank)
    ctx = profiler_ctx if profiler_ctx is not None else nullcontext()
    with ctx as prof:
        for dst in range(world_size):
            if dst == rank:
                for src in range(world_size):
                    if src == rank:
                        continue
                    output_tensor = _build_tensor(send_recv_size, value=-1)
                    dist.recv(output_tensor, src, tag=src)
                    self.assertTrue(output_tensor.eq(src).all())
            else:
                dist.send(tensor, dst, tag=rank)
    if profiler_ctx is not None:
        backend = dist.get_backend()
        if <MASK>:
            for event_name in [f'{backend}:send', f'{backend}:recv']:
                events = get_profiling_event(event_name, prof)
                event_count = sum((e.count for e in events))
                expected_event_count = dist.get_world_size() - 1
                self.assertEqual(event_count, expected_event_count)
                for event in events:
                    self.assertTrue(event.is_async)
                    self.assertEqual(event.name, event_name)
                    self.assertEqual(event.input_shapes, [[send_recv_size] * 3])

