def _get_overload(qualified_name: str) -> torch._ops.OpOverload | None:
    """Obtain the torch op from <namespace>::<op_name>[.<overload>]"""
    (namespace, opname_overload) = qualified_name.split('::')
    (op_name, *maybe_overload) = opname_overload.split('.', 1)
    if namespace == '_operator':
        return getattr(operator, op_name)
    if namespace == 'math':
        return getattr(math, op_name)
    if namespace == 'torchvision':
        if importlib.util.find_spec('torchvision') is None:
            logger.warning('torchvision is not installed. Skipping %s', qualified_name)
            return None
    try:
        op_packet = getattr(getattr(torch.ops, namespace), op_name)
        if <MASK>:
            overload = maybe_overload[0]
        elif 'default' in op_packet._overload_names or '' in op_packet._overload_names:
            overload = 'default'
        else:
            logger.warning("'%s' does not have a 'default' overload. This could be an error in specifying the op name. Ignoring.", qualified_name, stacklevel=1)
            return None
        return getattr(op_packet, overload)
    except AttributeError:
        if qualified_name.endswith('getitem'):
            return None
        logger.info("'%s' is not found in this version of PyTorch.", qualified_name)
        return None
    except Exception:
        logger.exception("Failed to find torch op '%s'", qualified_name)
        return None

def infer_symbol_values(symints: list[Union[torch.SymInt, int]], init_symints: list[Union[torch.SymInt, int]], symbol_idx_dict: dict[str, int], padding_constraints: defaultdict[torch.SymInt, list[Union[sp.Expr, int]]], constraint: str) -> None:
    if constraint.find('non-singleton') != -1:
        (left_expression, right_expression) = re.findall(parentheses_pattern, constraint)
        calculate_value(left_expression, right_expression, symints, symbol_idx_dict)
    elif constraint.find('first two dimensions of batch2 tensor to be') != -1:
        matches = re.findall(square_brackets_pattern, constraint)
        (left_expression, right_expression) = (matches[i].split(',')[1].strip() for i in (0, 1))
        calculate_value(left_expression, right_expression, symints, symbol_idx_dict)
    elif constraint.find('a and b must have same reduction dim') != -1:
        matches = re.findall(square_brackets_pattern, constraint)
        left_expression = matches[0].split(',')[1].strip()
        right_expression = matches[1].split(',')[0].strip()
        calculate_value(left_expression, right_expression, symints, symbol_idx_dict)
    elif <MASK>:
        match_1 = re.search('to\\s+(.*?)\\s+but', constraint)
        extracted_value_1 = match_1.group(1) if match_1 else None
        match_2 = re.search('of\\s+(.*?)$', constraint)
        extracted_value_2 = match_2.group(1) if match_2 else None
        calculate_value(extracted_value_1, extracted_value_2, symints, symbol_idx_dict)
    elif constraint.find('is invalid for input of size') != -1:
        matches = re.findall(square_brackets_pattern, constraint)
        left_elements = matches[0].split(',')
        left_equation = sp.sympify(1)
        left_num = 1
        right_equation = sp.sympify(constraint.split('size')[1].strip())
        for left_element in left_elements:
            if sp.sympify(left_element) == sp.sympify('-1'):
                continue
            elif sp.sympify(left_element).is_number:
                left_num *= int(left_element)
            else:
                left_equation *= sp.sympify(left_element)
        right_equation = sp.cancel(right_equation / left_equation)
        right_vars = list(right_equation.free_symbols)
        for right_var in right_vars:
            if sp.sympify(right_var) == sp.sympify('s0'):
                right_equation = sp.cancel(right_equation / right_var)
                right_vars.remove(right_var)
        var = right_vars[0]
        idx = symbol_idx_dict[str(var)]
        if var not in padding_constraints:
            padding_constraints[var].append(right_equation)
        update_equation(symints, init_symints, padding_constraints, padding_constraints[var][0], left_num, var, idx)

def decorator(fit_method):

    @functools.wraps(fit_method)
    def wrapper(estimator, *args, **kwargs):
        global_skip_validation = get_config()['skip_parameter_validation']
        partial_fit_and_fitted = fit_method.__name__ == 'partial_fit' and _is_fitted(estimator)
        if <MASK>:
            estimator._validate_params()
        with config_context(skip_parameter_validation=prefer_skip_nested_validation or global_skip_validation):
            return fit_method(estimator, *args, **kwargs)
    return wrapper

def run(self):
    self._print_header()
    output_csv_filename = self.args.output_csv
    headers = ['Benchmarking Framework', 'Benchmarking Module Name', 'Case Name', 'tag', 'run_backward', 'Execution Time', 'Peak Memory (KB)']
    if self.args.output_json or self.args.output_json_for_dashboard:
        perf_list = []
    for test_metainfo in BENCHMARK_TESTER:
        for test in _build_test(*test_metainfo):
            (full_test_id, test_case) = test
            op_test_config = test_case.test_config
            if <MASK>:
                continue
            if not self._keep_test(test_case):
                continue
            np.random.seed(seed=hash(full_test_id) & (1 << 32) - 1)
            print(f'# Benchmarking {test_case.framework}: {test_case.op_bench.module_name()}')
            if op_test_config.run_backward:
                launch_func = self._launch_backward
            else:
                launch_func = self._launch_forward
            launch_func(test_case, self.args.warmup_iterations, print_per_iter=False)
            results = [self._measure_metrics(launch_func, test_case, self.iters, self.print_per_iter) for _ in range(self.num_runs)]
            result_dict = dict()
            result_dict['reported_run_time_us'] = [r[0] for r in results]
            result_dict['peak_memory'] = results[0][1]
            self._print_perf_result(results=result_dict, test_case=test_case)
            self._output_csv(output_csv_filename, headers, [test_case.framework, test_case.op_bench.module_name(), test_case.test_config.test_name + '_BACKWARD' if test_case.test_config.run_backward is True else test_case.test_config.test_name, test_case.test_config.tag, test_case.test_config.run_backward, result_dict['reported_run_time_us'][0], result_dict['peak_memory']])
            if self.args.output_json or self.args.output_json_for_dashboard:
                perf_list.append(self._perf_result_to_dict(result_dict, test_case))
    if self.args.output_json_for_dashboard:
        self._output_json(perf_list, self.args.output_json_for_dashboard, self.args.benchmark_name)
    if self.args.output_json:
        with open(self.args.output_json, 'w') as f:
            json.dump(perf_list, f)

def tensor_static_reason_to_message(reason: TensorStaticReason) -> str:
    if reason == TensorStaticReason.PARAMETER:
        return 'mark_dynamic on parameter, parameters are always static today.'
    if reason == TensorStaticReason.NOT_TENSOR:
        return 'mark_dynamic on a non tensor, how did this happen?'
    if <MASK>:
        return 'tensor is static because it is nn module associated.'
    raise AssertionError(f'Illegal reason {reason}')

