    if <MASK>:
        return array_ops.transpose(tensor, perm=perm)
    else:
        return tensor

@compatibility(is_backward_compatible=True)
def path_of_module(self, mod: torch.nn.Module) -> str:
    """
        Helper method to find the qualified name of ``mod`` in the Module hierarchy
        of ``root``. For example, if ``root`` has a submodule named ``foo``, which has
        a submodule named ``bar``, passing ``bar`` into this function will return
        the string "foo.bar".

        Args:

            mod (str): The ``Module`` to retrieve the qualified name for.
        """
    if <MASK>:
        path = self.submodule_paths.get(mod)
        if path is None:
            raise NameError('module is not installed as a submodule')
        assert isinstance(path, str)
        return path
    else:
        for (n, p) in self.root.named_modules():
            if mod is p:
                return n
        raise NameError('module is not installed as a submodule')

def copy_fn(cur_i, cand_i):
    if <MASK>:
        return cand_i
    if cur_i.shape.rank == 0:
        return cand_i
    with ops.colocate_with(cand_i):
        return array_ops.where(elements_finished, cur_i, cand_i)

def split(tensor: Any, split_size_or_sections: Any, dim: Any=None) -> tuple:
    """
    Split tensor along a dimension.

    Can handle both regular integer sizes and Dim objects for split sizes.
    When Dim objects are used, they get bound to the resulting tensor dimensions.
    """
    from ._wrap import _wrap_dim
    dim_is_object = isinstance(dim, Dim)
    if isinstance(split_size_or_sections, int):
        if dim_is_object:
            raise TypeError('when dim is specified as a Dim object, split sizes must also be dimensions.')
        return _Tensor._torch_function_fallback(torch.Tensor.split, (type(tensor),), (tensor, split_size_or_sections), {'dim': dim})
    sizes = []
    all_dims = True
    all_ints = True
    for item in split_size_or_sections:
        sizes.append(item)
        if isinstance(item, Dim):
            all_ints = False
        else:
            all_dims = False
    if all_ints:
        if dim_is_object:
            raise TypeError('when dim is specified as a Dim object, split sizes must also be dimensions.')
        return _Tensor._torch_function_fallback(torch.Tensor.split, (type(tensor),), (tensor, split_size_or_sections), {'dim': dim})
    if not all_dims:
        raise TypeError('split list must be ints or dims but got a mix')
    self_info = TensorInfo.create(tensor, ensure_batched=False, ensure_present=False)
    ndim = self_info.ndim()
    if not dim_is_object and ndim == 0:
        raise TypeError('split expects at least a 1-dimension tensor')
    dim_l = _wrap_dim(dim, ndim, False) if dim is not None else DimEntry(-ndim)
    idx = None
    for (i, level) in enumerate(self_info.levels):
        if level == dim_l:
            idx = i
            break
    if <MASK>:
        if dim is None:
            dim = 0
        raise TypeError(f'tensor does not contain dimension {dim}')
    indices = []
    total_size = 0
    unbound = []
    for (i, size_dim) in enumerate(sizes):
        if size_dim.is_bound:
            indices.append(size_dim.size)
            total_size += indices[-1]
        else:
            indices.append(0)
            unbound.append(i)
    assert self_info.tensor is not None, 'Cannot get tensor size on None tensor'
    tensor_size = self_info.tensor.size(idx)
    if unbound:
        if total_size > tensor_size:
            raise TypeError(f'sizes of target dimensions add up to more ({total_size}) than source dim ({tensor_size})')
        remaining_size = tensor_size - total_size
        chunk_size = (remaining_size + len(unbound) - 1) // len(unbound)
        for u in unbound:
            sz = min(chunk_size, remaining_size)
            sizes[u].size = sz
            indices[u] = sz
            remaining_size -= sz
    elif tensor_size != total_size:
        raise TypeError(f'sum of sizes of target dimensions ({total_size}) do not match the source dim ({tensor_size})')
    result_tensors = self_info.tensor.split_with_sizes(indices, idx)
    result = []
    new_levels = list(self_info.levels)
    for (i, (result_tensor, size_dim)) in enumerate(zip(result_tensors, sizes)):
        new_levels[idx] = DimEntry(size_dim)
        result.append(Tensor.from_positional(result_tensor, list(new_levels), self_info.has_device))
    return tuple(result)

def render_tests(testcases: list[TestCase]) -> None:
    num_passed = 0
    num_skipped = 0
    num_failed = 0
    for testcase in testcases:
        if not testcase.result:
            num_passed += 1
            continue
        for result in testcase.result:
            if <MASK>:
                icon = ':rotating_light: [white on red]ERROR[/white on red]:'
                num_failed += 1
            elif isinstance(result, Failure):
                icon = ':x: [white on red]Failure[/white on red]:'
                num_failed += 1
            else:
                num_skipped += 1
                continue
            rich.print(f'{icon} [bold red]{testcase.classname}.{testcase.name}[/bold red]')
            print(f'{result.text}')
    rich.print(f':white_check_mark: {num_passed} [green]Passed[green]')
    rich.print(f':dash: {num_skipped} [grey]Skipped[grey]')
    rich.print(f':rotating_light: {num_failed} [grey]Failed[grey]')

def _backward_simple_script_call(self, t1, t2, sparse):
    local_grads = None
    for exec_mode in [ExecMode.LOCAL, ExecMode.RPC_SYNC, ExecMode.RPC_ASYNC, ExecMode.REMOTE]:
        with dist_autograd.context() as context_id:
            forward_ret = self._exec_func(exec_mode, my_script_add, t1, t2)
            if <MASK>:
                loss = torch.sparse.sum(forward_ret)
            else:
                loss = forward_ret.sum()
            ret = self._verify_backwards(exec_mode, [loss], context_id, local_grads, t1, t2)
            local_grads = ret if ret else local_grads

@ignore_warnings(category=FutureWarning)
def check_class_weight_classifiers(name, classifier_orig):
    if get_tags(classifier_orig).classifier_tags.multi_class:
        problems = [2, 3]
    else:
        problems = [2]
    for n_centers in problems:
        (X, y) = make_blobs(centers=n_centers, random_state=0, cluster_std=20)
        (X_train, X_test, y_train, y_test) = train_test_split(X, y, test_size=0.5, random_state=0)
        if get_tags(classifier_orig).input_tags.pairwise:
            X_test = rbf_kernel(X_test, X_train)
            X_train = rbf_kernel(X_train, X_train)
        n_centers = len(np.unique(y_train))
        if n_centers == 2:
            class_weight = {0: 1000, 1: 0.0001}
        else:
            class_weight = {0: 1000, 1: 0.0001, 2: 0.0001}
        classifier = clone(classifier_orig).set_params(class_weight=class_weight)
        if <MASK>:
            classifier.set_params(n_iter=100)
        if hasattr(classifier, 'max_iter'):
            classifier.set_params(max_iter=1000)
        if hasattr(classifier, 'min_weight_fraction_leaf'):
            classifier.set_params(min_weight_fraction_leaf=0.01)
        if hasattr(classifier, 'n_iter_no_change'):
            classifier.set_params(n_iter_no_change=20)
        set_random_state(classifier)
        classifier.fit(X_train, y_train)
        y_pred = classifier.predict(X_test)
        if not get_tags(classifier_orig).classifier_tags.poor_score:
            assert np.mean(y_pred == 0) > 0.87

@RegisterPFor('TensorArrayReadV3')
def _convert_tensor_array_read_v3(pfor_input: _PforInput):
    handle = pfor_input.unstacked_input(0)
    (index, index_stacked, _) = pfor_input.input(1)
    dtype = pfor_input.get_attr('dtype')
    (flow, flow_stacked, _) = pfor_input.input(2)
    if <MASK>:
        flow = _unstack_flow(flow)
    is_inside_pfor = _handle_inside_pfor(pfor_input, pfor_input.op.inputs[0])
    if is_inside_pfor:
        all_indices = pfor_input.pfor.all_indices
        all_indices_partitioned = pfor_input.pfor.all_indices_partitioned
        if index_stacked:
            if flow_stacked:
                raise ValueError('It looks like TensorArrayReadV3 was called on a TensorArray whose values are not loop-invariant, and the read indices were also not loop invariant. This is currently unsupported.')
            value = data_flow_ops.tensor_array_gather_v3(handle, index, flow, dtype=dtype)
            return wrap(value, True)
        value = data_flow_ops.tensor_array_read_v3(handle, index, flow, dtype=dtype)
        if flow_stacked and all_indices_partitioned:
            value = array_ops.gather(value, all_indices)
        return wrap(value, flow_stacked)
    if index_stacked:
        value = data_flow_ops.tensor_array_gather_v3(handle, index, flow, dtype=dtype)
    else:
        value = data_flow_ops.tensor_array_read_v3(handle, index, flow, dtype=dtype)
    return wrap(value, index_stacked)

def select_dispatch_strategy(self) -> None:
    if self.dispatch_class is not None:
        return
    if not self.mixed_sizes or any((isinstance(e, str) for e in self.x_numels_list)):
        self.dispatch_class = ComboKernel.SequentialDispatch
        return
    x_numels_list = [abs(cast(int, e)) for e in self.x_numels_list]
    total = max(x_numels_list) * len(x_numels_list)
    needed = sum(x_numels_list)
    if <MASK>:
        self.dispatch_class = ComboKernel.RoundRobinDispatch
    else:
        self.dispatch_class = ComboKernel.SequentialDispatch

def _generate_range(start: Timestamp | None, end: Timestamp | None, periods: int | None, offset: BaseOffset, *, unit: str) -> Generator[Timestamp]:
    """
    Generates a sequence of dates corresponding to the specified time
    offset. Similar to dateutil.rrule except uses pandas DateOffset
    objects to represent time increments.

    Parameters
    ----------
    start : Timestamp or None
    end : Timestamp or None
    periods : int or None
    offset : DateOffset
    unit : str

    Notes
    -----
    * This method is faster for generating weekdays than dateutil.rrule
    * At least two of (start, end, periods) must be specified.
    * If both start and end are specified, the returned dates will
    satisfy start <= date <= end.

    Returns
    -------
    dates : generator object
    """
    offset = to_offset(offset)
    start = Timestamp(start)
    if start is not NaT:
        start = start.as_unit(unit)
    else:
        start = None
    end = Timestamp(end)
    if end is not NaT:
        end = end.as_unit(unit)
    else:
        end = None
    if start and (not offset.is_on_offset(start)):
        if offset.n >= 0:
            start = offset.rollforward(start)
        else:
            start = offset.rollback(start)
    if periods is None and end < start and (offset.n >= 0):
        end = None
        periods = 0
    if end is None:
        end = start + (periods - 1) * offset
    if <MASK>:
        start = end - (periods - 1) * offset
    start = cast(Timestamp, start)
    end = cast(Timestamp, end)
    cur = start
    if offset.n >= 0:
        while cur <= end:
            yield cur
            if cur == end:
                break
            next_date = offset._apply(cur)
            next_date = next_date.as_unit(unit)
            if next_date <= cur:
                raise ValueError(f'Offset {offset} did not increment date')
            cur = next_date
    else:
        while cur >= end:
            yield cur
            if cur == end:
                break
            next_date = offset._apply(cur)
            next_date = next_date.as_unit(unit)
            if next_date >= cur:
                raise ValueError(f'Offset {offset} did not decrement date')
            cur = next_date

def _check_dynamic_shapes(combined_args: dict[str, Any], dynamic_shapes: Union[dict[str, Any], tuple[Any], list[Any], None]):
    """
    Checks the dynamic_shapes specification for correctness,
    using combined args + kwargs as reference for inputs structure.
    """
    from torch._dynamo.exc import UserError, UserErrorType
    if dynamic_shapes is None or len(dynamic_shapes) == 0:
        return
    if isinstance(dynamic_shapes, (tuple, list)):
        combined_args = type(dynamic_shapes)(combined_args.values())
    bounds: dict[str, tuple[int, int]] = {}

    def check_same_bounds(dim):
        if <MASK>:
            (min_, max_) = bounds[dim.__name__]
            if dim.min != min_ or dim.max != max_:
                this_ = Dim._readable(dim.__name__, min_, max_)
                that_ = Dim._readable(dim.__name__, dim.min, dim.max)
                raise UserError(UserErrorType.INVALID_INPUT, f'Found different definitions {this_} and {that_} for the same symbolic dimension {dim}!')
        else:
            bounds[dim.__name__] = (dim.min, dim.max)

    def check_symbols(path, tensor, shape):
        if isinstance(shape, dict):
            for (i, dim) in shape.items():
                if isinstance(dim, Dim):
                    check_same_bounds(dim)
                elif dim is None:
                    _warn_on_None_dynamic_shape_dimension()
                elif not isinstance(dim, (int, _DimHint)):
                    raise UserError(UserErrorType.INVALID_INPUT, f'Unexpected dimension mapped to index {i} in input tensor shape {shape} specified at `dynamic_shapes{keystr(path)}` (expected None, an int, a Dim, Dim.AUTO, Dim.STATIC, or Dim.DYNAMIC,  but got {dim!r} instead)', case_name='dynamic_shapes_validation')
        elif isinstance(shape, (tuple, list)):
            if len(shape) != len(tensor.shape):
                raise UserError(UserErrorType.INVALID_INPUT, f'Expected dynamic shape spec {shape} specified at `dynamic_shapes{keystr(path)}` to have the same length as the actual tensor shape {tensor.shape} (expected {len(tensor.shape)}, but got {len(shape)} instead)', case_name='dynamic_shapes_validation')
            for (i, dim) in enumerate(shape):
                if isinstance(dim, Dim):
                    check_same_bounds(dim)
                elif dim is None:
                    _warn_on_None_dynamic_shape_dimension()
                elif not isinstance(dim, (int, _DimHint)):
                    raise UserError(UserErrorType.INVALID_INPUT, f'Unexpected dimension #{i} in input tensor shape {shape} specified at `dynamic_shapes{keystr(path)}` (expected None, an int, a Dim, Dim.AUTO, Dim.STATIC, or Dim.DYNAMIC, but got {dim!r} instead)', case_name='dynamic_shapes_validation')
        elif shape is not None:
            raise UserError(UserErrorType.INVALID_INPUT, f'Unexpected input tensor shape {shape} specified at `dynamic_shapes{keystr(path)}` (expected either a list/tuple of dimensions, or a dict mapping indices to dimensions, where each dimension is an int, a Dim, Dim.AUTO, Dim.STATIC, or Dim.DYNAMIC)', case_name='dynamic_shapes_validation')
    assert isinstance(dynamic_shapes, (dict, tuple, list))
    if isinstance(dynamic_shapes, dict):
        got_keys = list(dynamic_shapes.keys())
        expected_arg_names = list(combined_args.keys())
        if sorted(got_keys) != sorted(expected_arg_names):
            msg = f'When `dynamic_shapes` is specified as a dict, its top-level keys must be the arg names {expected_arg_names} of `inputs`, but here they are {got_keys}. '
            if len(combined_args) == 1 and expected_arg_names[0] not in got_keys and isinstance(combined_args[expected_arg_names[0]], dict):
                msg += 'Since here `inputs` is a list/tuple enclosing a single dict, maybe you just forgot to enclose `dynamic_shapes` in a list/tuple?'
            else:
                msg += 'Alternatively, you could also ignore arg names entirely and specify `dynamic_shapes` as a list/tuple matching `inputs`.'
            raise UserError(UserErrorType.INVALID_INPUT, msg, case_name='dynamic_shapes_validation')

    def check_shape(path, t, dynamic_shape):
        if isinstance(t, torch.Tensor):
            check_symbols(path, t, dynamic_shape)
        elif isinstance(t, _IntWrapper):
            if isinstance(dynamic_shape, _Dim):
                raise ValueError('Unable to specify input integers as dynamic through named Dims. Please use Dim.AUTO/DYNAMIC instead.')
            assert dynamic_shape is None or isinstance(dynamic_shape, (int, _DimHint))
        elif dynamic_shape is not None:
            rendered_path = keystr(path)
            raise UserError(UserErrorType.INVALID_INPUT, f'Cannot associate shape {dynamic_shape} specified at `dynamic_shapes{rendered_path}` to non-tensor type {type(t)} at `inputs{rendered_path}` (expected None)', case_name='dynamic_shapes_validation')
    _tree_map_with_path(check_shape, combined_args, dynamic_shapes, tree_name='inputs')

def wrapper(*args, **kwargs):
    from django.utils import translation
    saved_locale = translation.get_language()
    translation.deactivate_all()
    try:
        res = handle_func(*args, **kwargs)
    finally:
        if <MASK>:
            translation.activate(saved_locale)
    return res

def find_info(f: NativeFunction) -> tuple[dict[str, DifferentiabilityInfo] | None, bool]:
    if <MASK>:
        return (None, False)
    if f.func in differentiability_infos:
        return (differentiability_infos[f.func], True)
    f_sig = f.func.signature(strip_default=True)
    if f_sig in functional_info_by_signature and (not is_foreach_func(f)):
        return (functional_info_by_signature[f_sig], False)
    if 'generated' in f.tags and f_sig in non_functional_info_by_signature:
        info_dict = non_functional_info_by_signature[f_sig]
        assert not any((any(('self' in str(input.nctype.name) for input in info.all_saved_inputs)) for info in info_dict.values())), f'''Attempted to convert a derivative formula for a mutable operator\n to be used by automatically by its functional variant ("{str(f.func)}").\n this is not currently supported (we'd need to fix up the formula in the codegen).'''
        return (info_dict, False)
    if is_foreach_func(f):
        assert f.func not in differentiability_infos
        (diff_info, is_generated) = gen_foreach_derivativeinfo(f, functional_info_by_signature, non_functional_info_by_signature)
        if diff_info is None:
            return (None, False)
        diff_info_dict = {'Default': diff_info}
        if is_generated:
            differentiability_infos[f.func] = diff_info_dict
            functional_info_by_signature[f.func] = diff_info_dict
        return (diff_info_dict, is_generated)
    return (None, False)

