def module_fn(module, prefix, tree_level, param_to_fqns):
    for (param_name, param) in _named_parameters_with_duplicates(module, recurse=False):
        local_fqns = param._fqns if isinstance(param, flat_param_file.FlatParameter) else [param_name]
        global_fqns = [clean_tensor_name(prefix + name) for name in local_fqns]
        is_shared_param = param in param_to_fqns
        if not is_shared_param:
            param_to_fqns[param] = global_fqns
        elif isinstance(param, flat_param_file.FlatParameter):
            warnings.warn('FlatParameter is being traversed more than once. This case should only happen when using DistributedModelParallel with FullyShardedDataParallel.')
            param_to_fqns[param] = global_fqns
        elif <MASK>:
            param_to_fqns[param].extend(global_fqns)

def _check_shard_metadata_pair_overlap(shard1: ChunkStorageMetadata, shard2: ChunkStorageMetadata) -> bool:
    """Check if two shards overlap."""
    ndims = len(shard1.offsets)
    for i in range(ndims):
        if shard1.offsets[i] >= shard2.offsets[i] + shard2.sizes[i]:
            return False
        if <MASK>:
            return False
    return True

def max(self, *, axis: AxisInt | None=None, skipna: bool=True) -> IntervalOrNA:
    nv.validate_minmax_axis(axis, self.ndim)
    if not len(self):
        return self._na_value
    mask = self.isna()
    if <MASK>:
        if not skipna:
            return self._na_value
        obj = self[~mask]
    else:
        obj = self
    indexer = obj.argsort()[-1]
    return obj[indexer]

def is_tensor_evenly_shardable_on_dim(shape: Sequence[int], spec: DTensorSpec, dim: int) -> bool:
    """Check if the shape is evenly shardable according to the spec on dim."""
    dim = normalize_dim(dim, len(shape))
    num_shards = 1
    for (i, placement) in enumerate(spec.placements):
        if placement.is_shard():
            shard_dim = cast(Shard, placement).dim
            if <MASK>:
                num_shards *= spec.mesh.size(i)
    return shape[dim] % num_shards == 0

def ast(self):
    """AST representation."""
    if self.has_subscript():
        return gast.Subscript(value=self.parent.ast(), slice=self.qn[-1].ast(), ctx=CallerMustSetThis)
    if self.has_attr():
        return gast.Attribute(value=self.parent.ast(), attr=self.qn[-1], ctx=CallerMustSetThis)
    base = self.qn[0]
    if <MASK>:
        return gast.Name(base, ctx=CallerMustSetThis, annotation=None, type_comment=None)
    elif isinstance(base, Literal):
        return gast.Constant(base.value, kind=None)
    else:
        assert False, 'the constructor should prevent types other than str and Literal'

def compiled_fsdp_test(compile_compute_on_module: Optional[type]=None):

    def fully_shard_with_compiled_compute(*args, **kwargs):
        torch.distributed.fsdp.fully_shard(*args, **kwargs)
        if compile_compute_on_module is None or isinstance(args[0], compile_compute_on_module):
            args[0].compile()

    class FullyShardMode(Enum):
        EAGER = auto()
        COMPILED_COMPUTE = auto()

    def decorator(func):

        @wraps(func)
        def wrapper(*args, **kwargs):
            original_fully_shard: Any = torch.distributed.fsdp.fully_shard
            for mode in FullyShardMode:
                if mode != FullyShardMode.EAGER and (not has_triton()):
                    warnings.warn('Inductor on GPU needs Triton and recent GPU arch')
                    continue
                original_skip_fsdp_hooks = torch._dynamo.config.skip_fsdp_hooks
                original_compile_threads = torch._inductor.config.compile_threads
                torch.distributed.barrier()
                if mode == FullyShardMode.EAGER:
                    fully_shard_patch = original_fully_shard
                elif <MASK>:
                    torch._dynamo.config.skip_fsdp_hooks = True
                    torch._inductor.config.compile_threads = 1
                    fully_shard_patch = fully_shard_with_compiled_compute
                else:
                    raise NotImplementedError(f'Need to implement FullyShardMode={mode}')
                func.__globals__[original_fully_shard.__name__] = fully_shard_patch
                func(*args, **kwargs)
                torch.distributed.barrier()
                func.__globals__[original_fully_shard.__name__] = original_fully_shard
                torch._dynamo.config.skip_fsdp_hooks = original_skip_fsdp_hooks
                torch._inductor.config.compile_threads = original_compile_threads
        return wrapper
    return decorator

def codegen(self, output_name: str, input_names: list[str], output_spec: Spec) -> str:
    """Generate code for constant creation."""
    import hashlib
    var_seed = int(hashlib.md5(output_name.encode()).hexdigest()[:8], 16) % 2 ** 31
    if isinstance(output_spec, ScalarSpec):
        actual_value = fuzz_scalar(output_spec, seed=var_seed)
        if isinstance(actual_value, bool):
            value_str = str(actual_value)
        elif isinstance(actual_value, (int, float)):
            value_str = repr(actual_value)
        elif <MASK>:
            value_str = f'complex({actual_value.real}, {actual_value.imag})'
        else:
            value_str = repr(actual_value)
        return f'{output_name} = {value_str}'
    elif isinstance(output_spec, TensorSpec):
        actual_tensor = fuzz_tensor_simple(output_spec.size, output_spec.stride, output_spec.dtype, seed=var_seed)
        size_str = str(output_spec.size)
        dtype_str = f'torch.{output_spec.dtype}'.replace('torch.torch.', 'torch.')
        if actual_tensor.numel() == 0:
            import torch
            default_values = {torch.float16: 1.0, torch.float32: 1.0, torch.float64: 1.0, torch.bfloat16: 1.0, torch.int8: 1, torch.int16: 1, torch.int32: 1, torch.int64: 1, torch.bool: True, torch.complex64: 1.0, torch.complex128: 1.0}
            fill_value = default_values.get(output_spec.dtype, 1)
            tensor_creation = f'torch.full({size_str}, {fill_value}, dtype={dtype_str})'
        else:
            fill_value = actual_tensor.flatten()[0].item()
            import torch
            if output_spec.dtype in [torch.int8, torch.int16, torch.int32, torch.int64]:
                fill_value = max(0, min(3, abs(fill_value)))
            tensor_creation = f'torch.full({size_str}, {fill_value}, dtype={dtype_str})'
        if self.template == 'dtensor':
            return f"{output_name}_local = {tensor_creation}.to('cuda')\n    {output_name} = DTensor.from_local({output_name}_local, mesh, placements)"
        else:
            return f'{output_name} = {tensor_creation}'
    else:
        return f'# Unknown output spec type for constant: {type(output_spec)}'

def dtypes(self, *, device: Device | None=None, kind: str | tuple[str, ...] | None=None) -> dict[str, DType]:
    """
        The array API data types supported by NumPy.

        Note that this function only returns data types that are defined by
        the array API.

        Parameters
        ----------
        device : str, optional
            The device to get the data types for. For NumPy, only ``'cpu'`` is
            allowed.
        kind : str or tuple of str, optional
            The kind of data types to return. If ``None``, all data types are
            returned. If a string, only data types of that kind are returned.
            If a tuple, a dictionary containing the union of the given kinds
            is returned. The following kinds are supported:

            - ``'bool'``: boolean data types (i.e., ``bool``).
            - ``'signed integer'``: signed integer data types (i.e., ``int8``,
              ``int16``, ``int32``, ``int64``).
            - ``'unsigned integer'``: unsigned integer data types (i.e.,
              ``uint8``, ``uint16``, ``uint32``, ``uint64``).
            - ``'integral'``: integer data types. Shorthand for ``('signed
              integer', 'unsigned integer')``.
            - ``'real floating'``: real-valued floating-point data types
              (i.e., ``float32``, ``float64``).
            - ``'complex floating'``: complex floating-point data types (i.e.,
              ``complex64``, ``complex128``).
            - ``'numeric'``: numeric data types. Shorthand for ``('integral',
              'real floating', 'complex floating')``.

        Returns
        -------
        dtypes : dict
            A dictionary mapping the names of data types to the corresponding
            NumPy data types.

        See Also
        --------
        __array_namespace_info__.capabilities,
        __array_namespace_info__.default_device,
        __array_namespace_info__.default_dtypes,
        __array_namespace_info__.devices

        Examples
        --------
        >>> info = np.__array_namespace_info__()
        >>> info.dtypes(kind='signed integer')
        {'int8': numpy.int8,
         'int16': numpy.int16,
         'int32': numpy.int32,
         'int64': numpy.int64}

        """
    if device not in ['cpu', None]:
        raise ValueError(f'Device not understood. Only "cpu" is allowed, but received: {device}')
    if kind is None:
        return {'bool': dtype(bool), 'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'bool':
        return {'bool': dtype(bool)}
    if <MASK>:
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'integral':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'real floating':
        return {'float32': dtype(float32), 'float64': dtype(float64)}
    if kind == 'complex floating':
        return {'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'numeric':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if isinstance(kind, tuple):
        res: dict[str, DType] = {}
        for k in kind:
            res.update(self.dtypes(kind=k))
        return res
    raise ValueError(f'unsupported kind: {kind!r}')

