def redistribute_local_tensor(local_tensor: torch.Tensor, current_spec: DTensorSpec, target_spec: DTensorSpec, *, async_op: bool=False, is_backward: bool=False, use_graph_based_transform: Optional[bool]=None) -> torch.Tensor:
    """
    This redistribute the local tensor (torch.Tensor) from the current DTensorSpec to
    the target DTensorSpec, which involves the necessary collective calls to transform
    the local shard of the DTensor from its current spec to the target spec.
    """
    if current_spec.mesh != target_spec.mesh:
        raise NotImplementedError('Cross device mesh comm not supported yet!')
    new_local_tensor = local_tensor
    device_mesh = current_spec.mesh
    my_coordinate = device_mesh.get_coordinate()
    if my_coordinate is None:
        return local_tensor
    if _are_we_tracing():
        transform_infos = _gen_transform_infos_non_cached(current_spec, target_spec, use_graph_based_transform)
    else:
        transform_infos = _gen_transform_infos(current_spec, target_spec, use_graph_based_transform)
    debug_mode = get_active_debug_mode()
    redistribute_context = debug_mode.record_redistribute_calls(local_tensor, current_spec.placements, target_spec.placements, DTensorRedistributePlanner.stringify_transform_infos(device_mesh, transform_infos, current_spec.placements, current_spec.shard_order)) if debug_mode is not None else contextlib.nullcontext()
    with redistribute_context:
        for transform_info in transform_infos:
            i = transform_info.mesh_dim
            (current, target) = transform_info.src_dst_placements
            num_chunks = device_mesh.size(mesh_dim=i)
            if current == target:
                new_local_tensor = local_tensor
                continue
            if <MASK>:
                new_local_tensor = local_tensor
                continue
            if target.is_replicate():
                if current.is_partial():
                    partial_spec = cast(Partial, current)
                    new_local_tensor = partial_spec._reduce_value(local_tensor, device_mesh, i)
                elif current.is_shard():
                    current_placement = cast(Shard, current)
                    new_local_tensor = current_placement._to_replicate_tensor(local_tensor, device_mesh, i, transform_info.logical_shape)
                else:
                    raise RuntimeError(f'redistribute from {current} to {target} not supported yet')
            elif target.is_shard():
                target_placement = cast(Shard, target)
                if current.is_partial():
                    partial_spec = cast(Partial, current)
                    new_local_tensor = partial_spec._reduce_shard_value(local_tensor, device_mesh, i, target_placement)
                elif current.is_replicate():
                    new_local_tensor = target_placement._replicate_to_shard(local_tensor, device_mesh, i, my_coordinate[i])
                else:
                    assert current.is_shard(), f'Current placement should be shard but found {current}'
                    shard_spec = cast(Shard, current)
                    if shard_spec.dim != target_placement.dim:
                        new_local_tensor = shard_spec._to_new_shard_dim(local_tensor, device_mesh, i, transform_info.logical_shape, target_placement.dim)
            elif target.is_partial():
                if current.is_replicate():
                    partial_spec = cast(Partial, target)
                    new_local_tensor = partial_spec._partition_value(local_tensor, device_mesh, i) if not is_backward else local_tensor
                elif current.is_shard():
                    if not is_backward:
                        raise RuntimeError(f'redistribute from {current} to {target} not supported yet')
                    current_placement = cast(Shard, current)
                    new_local_tensor = current_placement._to_replicate_tensor(local_tensor, device_mesh, i, transform_info.logical_shape)
                else:
                    new_local_tensor = local_tensor
            if not async_op and isinstance(new_local_tensor, funcol.AsyncCollectiveTensor):
                new_local_tensor = new_local_tensor.wait()
            local_tensor = new_local_tensor
    return new_local_tensor

def fw_with_masks(*args):
    fw_out = fn(*args)
    if <MASK>:
        fw_out = pytree.tree_map_only(torch.Tensor, lambda x: x.requires_grad_(True) if x.dtype.is_floating_point else x, fw_out)

    def _query_requires_grad(t: torch.Tensor) -> bool:
        if torch._is_functional_tensor(t):
            t = torch._from_functional_tensor(t)
        return t.requires_grad
    return (fw_out, pytree.tree_map_only(torch.Tensor, _query_requires_grad, fw_out))

def _sparse_csr_segment_reduction_helper(op, mask_input: Tensor, dims: tuple[int, ...], keepdim: bool, dtype: Optional[DType]=None) -> Tensor:
    assert keepdim, 'reduction operations on CSR tensors with keepdim=False is unsupported'
    reduce = op.__name__
    valid_reductions = ['sum', 'prod', 'mean', 'amax', 'amin']
    if reduce not in valid_reductions:
        raise ValueError(f"op must be one of {' '.join(valid_reductions)}, but got {reduce} instead")
    device = mask_input.device
    output_dtype = dtype
    (values, crow_indices, col_indices) = (mask_input.values(), mask_input.crow_indices(), mask_input.col_indices())
    if values.dtype != output_dtype:
        values = values.to(output_dtype)
    if len(dims) == 0:
        return mask_input
    if len(dims) == 1:
        if <MASK>:
            (new_col_indices, scatter_indices) = torch.unique(col_indices, return_inverse=True)
            new_nnz = new_col_indices.shape[0]
            new_crow_indices = torch.tensor([0, new_nnz])
            new_values = values.new_empty(new_col_indices.shape)
            new_values.scatter_reduce_(0, scatter_indices, values, reduce, include_self=False)
            new_shape = [1, mask_input.size(1)]
        else:
            assert dims[0] == 1, 'Sparse CSR tensors are 2D and only support reduction along dim 0 or 1.'
            new_crow_indices = torch.cat((crow_indices.new_zeros(1), torch.cumsum(torch.diff(crow_indices) != 0, 0)), 0)
            new_nnz = new_crow_indices[-1]
            new_col_indices = col_indices.new_zeros(new_nnz)
            new_values = torch._segment_reduce(values, reduce, offsets=crow_indices)
            new_shape = [mask_input.size(0), 1]
    else:
        assert len(dims) == 2
        nnz = min(1, values.numel())
        if nnz == 1:
            op_kwargs = {'keepdim': True, 'dtype': output_dtype}
            if reduce in ['amax', 'amin']:
                del op_kwargs['dtype']
            new_values = op(values, 0, **op_kwargs)
        else:
            new_values = torch.empty(0, dtype=output_dtype)
        new_col_indices = col_indices.new_zeros(nnz)
        new_crow_indices = torch.tensor([0, nnz])
        new_shape = [1, nnz]
    return torch.sparse_csr_tensor(new_crow_indices, new_col_indices, new_values, new_shape, dtype=output_dtype, device=device)

