def check_schema(schema_str: str, func, *args, **kwargs) -> None:
    named_arg_types = schema_str.split(', ')
    num_optional_args = [x.endswith('?') for x in named_arg_types].count(True)
    min_args = len(named_arg_types) - num_optional_args
    if named_arg_types[-1] == '...':
        named_arg_types = named_arg_types[:-1]
    elif not (len(args) >= min_args and len(args) <= len(named_arg_types)):
        raise ValueError(f'NestedTensor {func.__name__}({schema_str}): expected at least {min_args} arguments and at most {len(named_arg_types)} arguments, but got: {len(args)} arguments')
    arg_type_check_fns = {'t': lambda x: isinstance(x, torch.Tensor) and (not isinstance(x, NestedTensor)), 'jt': lambda x: isinstance(x, NestedTensor) and x._lengths is None and (x._ragged_idx == 1), 'jt_all': lambda x: isinstance(x, NestedTensor), 'any': lambda x: True}
    for (i, named_arg_type) in enumerate(named_arg_types):
        (name, arg_type) = named_arg_type.split(': ')
        is_optional = arg_type.endswith('?')
        normalized_arg_type = arg_type[:-1] if is_optional else arg_type
        if normalized_arg_type not in arg_type_check_fns.keys():
            raise AssertionError(f'Unknown arg type: {normalized_arg_type}')
        if i >= len(args):
            if not is_optional:
                raise ValueError(f'NestedTensor {func.__name__}({schema_str}) missing required argument: {name}')
            continue
        _check_fn = arg_type_check_fns[normalized_arg_type]

        def check_fn(x, is_optional=is_optional):
            if is_optional:
                return x is None or _check_fn(x)
            else:
                return _check_fn(x)
        if <MASK>:
            type_to_desc = {'t': 'tensor', 't?': 'optional tensor', 'jt': 'contiguous jagged layout NestedTensor', 'jt_all': 'jagged layout NestedTensor', 'any': '<any type>'}
            raise ValueError(f'NestedTensor {func.__name__}({schema_str}): expected {name} to be a {type_to_desc[arg_type]}')

def _parse_target_tokens(self, tokens):
    assert isinstance(tokens, str)
    final_targets = []
    extra_flags = []
    has_baseline = False
    skipped = set()
    policies = set()
    multi_target = None
    tokens = list(filter(None, re.split(self._parse_regex_target, tokens)))
    if not tokens:
        self.dist_fatal('expected one token at least')
    for tok in tokens:
        TOK = tok.upper()
        ch = tok[0]
        if <MASK>:
            self.dist_fatal("+/- are 'not' allowed from target's groups or @targets, only from cpu_baseline and cpu_dispatch parms")
        elif ch == '$':
            if multi_target is not None:
                self.dist_fatal("policies aren't allowed inside multi-target '()', only CPU features")
            policies.add(self._parse_token_policy(TOK))
        elif ch == '#':
            if multi_target is not None:
                self.dist_fatal("target groups aren't allowed inside multi-target '()', only CPU features")
            (has_baseline, final_targets, extra_flags) = self._parse_token_group(TOK, has_baseline, final_targets, extra_flags)
        elif ch == '(':
            if multi_target is not None:
                self.dist_fatal("unclosed multi-target, missing ')'")
            multi_target = set()
        elif ch == ')':
            if multi_target is None:
                self.dist_fatal("multi-target opener '(' wasn't found")
            targets = self._parse_multi_target(multi_target)
            if targets is None:
                skipped.add(tuple(multi_target))
            else:
                if len(targets) == 1:
                    targets = targets[0]
                if targets and targets not in final_targets:
                    final_targets.append(targets)
            multi_target = None
        else:
            if TOK == 'BASELINE':
                if multi_target is not None:
                    self.dist_fatal("baseline isn't allowed inside multi-target '()'")
                has_baseline = True
                continue
            if multi_target is not None:
                multi_target.add(TOK)
                continue
            if not self.feature_is_exist(TOK):
                self.dist_fatal("invalid target name '%s'" % TOK)
            is_enabled = TOK in self.parse_baseline_names or TOK in self.parse_dispatch_names
            if is_enabled:
                if TOK not in final_targets:
                    final_targets.append(TOK)
                continue
            skipped.add(TOK)
    if multi_target is not None:
        self.dist_fatal("unclosed multi-target, missing ')'")
    if skipped:
        self.dist_log('skip targets', skipped, 'not part of baseline or dispatch-able features')
    final_targets = self.feature_untied(final_targets)
    for p in list(policies):
        (_, _, deps) = self._parse_policies[p]
        for d in deps:
            if d in policies:
                continue
            self.dist_log("policy '%s' force enables '%s'" % (p, d))
            policies.add(d)
    for (p, (have, nhave, _)) in self._parse_policies.items():
        func = None
        if p in policies:
            func = have
            self.dist_log("policy '%s' is ON" % p)
        else:
            func = nhave
        if not func:
            continue
        (has_baseline, final_targets, extra_flags) = func(has_baseline, final_targets, extra_flags)
    return (has_baseline, final_targets, extra_flags)

def maybe_k_slicing(self):
    if <MASK>:
        return False
    if self.is_dynamic_M:
        return True
    register_blocking = self.register_blocking
    k_blocks = math.ceil(self.k / register_blocking.block_k)
    thread_blocking = self.thread_blocking(self.num_threads)
    return k_blocks > thread_blocking.block_k

def true_fn():
    """Converts the body function for all but last iteration."""
    wrapped_inputs = [wrap(inp, stacked) for (inp, stacked) in zip(new_inputs, inputs_stacked)]
    while True:
        if <MASK>:
            indices = array_ops.gather(self._pfor.all_indices, new_indices)
        else:
            indices = new_indices
