        if not re.search('|'.join(args.filter), model_name, re.IGNORECASE) or re.search('|'.join(args.exclude), model_name, re.IGNORECASE) or model_name in args.exclude_exact or (model_name in self.skip_models):
            continue
        yield model_name

def prune(self) -> None:
    """
        This function will FX symbolically trace the model and then find instances of the patterns
        defined in self.patterns (by default SUPPORTED_STRUCTURED_PRUNING_PATTERNS ).

        For each pattern, it will apply to corresponding conversion function, which will modify the output
        and input size expected by the modules within the pattern
        """
    self.traced = symbolic_trace(self.model)
    modules = dict(self.traced.named_modules())
    for node in self.traced.graph.nodes:
        for (pattern, convert_fn) in self.patterns.items():
            matched = apply_match(modules, pattern, node, [])
            if matched is None:
                continue
            first_module = modules.get(node.target)
            if <MASK>:
                convert_block = []
                for node in matched:
                    if node.op == 'call_module':
                        convert_block.append(modules.get(node.target))
                    elif node.op == 'call_function':
                        convert_block.append(node.target)
                convert_fn(*convert_block)
    for module in self.traced.modules():
        if module_contains_param(module, FakeStructuredSparsity):
            raise Exception(f'Error: {module} still contains FakeStructuredSparsity parametrizations!')
    self.traced.graph.lint()
    self.traced.recompile()
    return self.traced

def _recursive_to(inputs, target_device, use_side_stream_for_tensor_copies):
    """Recursively moves input to the target_device."""

    def to_map(obj):
        if <MASK>:
            device = obj.data.device if isinstance(obj, PackedSequence) else obj.device
            if device == target_device:
                return (obj,)
            if not use_side_stream_for_tensor_copies:
                return (obj.to(target_device),)
            else:
                if device.type == 'cpu':
                    return (obj.to(target_device),)
                from torch.nn.parallel._functions import _get_stream
                stream = _get_stream(target_device)
                with stream:
                    output = obj.to(target_device)
                with torch.accelerator.device_index(target_device.index):
                    current_stream = torch.accelerator.current_stream()
                    current_stream.wait_stream(stream)
                    if isinstance(obj, PackedSequence):
                        output.data.record_stream(current_stream)
                    else:
                        assert isinstance(output, torch.Tensor)
                        output.record_stream(current_stream)
                return (output,)
        from torch.nn.parallel.scatter_gather import _is_namedtuple
        if _is_namedtuple(obj):
            return [type(obj)(*args) for args in zip(*map(to_map, obj))]
        if isinstance(obj, tuple) and len(obj) > 0:
            return list(zip(*map(to_map, obj)))
        if isinstance(obj, list) and len(obj) > 0:
            return [list(i) for i in zip(*map(to_map, obj))]
        if isinstance(obj, dict) and len(obj) > 0:
            return [type(obj)(i) for i in zip(*map(to_map, obj.items()))]
        return [obj]
    try:
        res = to_map(inputs)
    finally:
        to_map = None
    return res

def create_name_header(output_dir):
    routine_re = re.compile('^      (subroutine|.* function)\\s+(\\w+)\\(.*$', re.I)
    extern_re = re.compile('^extern [a-z]+ ([a-z0-9_]+)\\(.*$')
    symbols = {'xerbla'}
    for fn in os.listdir(output_dir):
        fn = os.path.join(output_dir, fn)
        if not fn.endswith('.f'):
            continue
        with open(fn) as f:
            for line in f:
                m = routine_re.match(line)
                if <MASK>:
                    symbols.add(m.group(2).lower())
    f2c_symbols = set()
    with open('f2c.h') as f:
        for line in f:
            m = extern_re.match(line)
            if m:
                f2c_symbols.add(m.group(1))
    with open(os.path.join(output_dir, 'lapack_lite_names.h'), 'w') as f:
        f.write(HEADER_BLURB)
        f.write("/*\n * This file renames all BLAS/LAPACK and f2c symbols to avoid\n * dynamic symbol name conflicts, in cases where e.g.\n * integer sizes do not match with 'standard' ABI.\n */\n")
        for name in sorted(symbols):
            f.write(f'#define {name}_ BLAS_FUNC({name})\n')
        f.write('\n/* Symbols exported by f2c.c */\n')
        for name in sorted(f2c_symbols):
            f.write(f'#define {name} numpy_lapack_lite_{name}\n')

def deserialize(self, binary_data, tensor_table):
    """
        Deserialize binary string + tensor table to original obj
        """
    global _thread_local_tensor_tables
    if <MASK>:
        old_recv_tables = _thread_local_tensor_tables.recv_tables
    else:
        old_recv_tables = None
    _thread_local_tensor_tables.recv_tables = tensor_table
    try:
        unpickler = _unpickler(io.BytesIO(binary_data))
        ret = unpickler.load()
    except AttributeError as e:
        except_str = str(e) + ' Default RPC pickler does not serialize\n            function code. Ensure that UDFs are defined on both caller and\n            callee modules.'
        ret = AttributeError(except_str)
        ret.__cause__ = e
    if old_recv_tables is not None:
        _thread_local_tensor_tables.recv_tables = old_recv_tables
    else:
        del _thread_local_tensor_tables.recv_tables
    return ret

def _check_mask_axis(mask, axis, keepdims=np._NoValue):
    """Check whether there are masked values along the given axis"""
    kwargs = {} if keepdims is np._NoValue else {'keepdims': keepdims}
    if <MASK>:
        return mask.all(axis=axis, **kwargs)
    return nomask

