def _fit(self, X, alpha, loss, learning_rate, coef_init=None, offset_init=None, sample_weight=None):
    if self.warm_start and hasattr(self, 'coef_'):
        if coef_init is None:
            coef_init = self.coef_
        if offset_init is None:
            offset_init = self.offset_
    else:
        self.coef_ = None
        self.offset_ = None
    self.t_ = 1.0
    self._partial_fit(X, alpha, loss, learning_rate, self.max_iter, sample_weight, coef_init, offset_init)
    if <MASK>:
        warnings.warn('Maximum number of iteration reached before convergence. Consider increasing max_iter to improve the fit.', ConvergenceWarning)
    if self.power_t < 0:
        warnings.warn('Negative values for `power_t` are deprecated in version 1.8 and will raise an error in 1.10. Use values in the range [0.0, inf) instead.', FutureWarning)
    return self

def codegen(self, output_name: str, input_names: list[str], output_spec: Spec) -> str:
    """Generate code for unsqueeze operation."""
    if not isinstance(output_spec, TensorSpec):
        raise ValueError('UnsqueezeOperator can only produce TensorSpec outputs')
    last_singleton_idx = None
    for i in range(len(output_spec.size) - 1, -1, -1):
        if <MASK>:
            last_singleton_idx = i
            break
    if last_singleton_idx is not None:
        dim = last_singleton_idx
    else:
        dim = len(output_spec.size) - 1
    return f'{output_name} = torch.unsqueeze({input_names[0]}, dim={dim})'

def _streaming_load(f: BufferedIOBase, map_location: MAP_LOCATION=None, pickle_module: Any=None, *, weights_only: bool=True, **pickle_load_args: Any) -> object:
    """
    Load the object from a file-like object in a streaming fashion compatible with
    network sockets.

    See :func:`_streaming_save` for more details about the streaming behavior.

    See :func:`torch.load` for more details on specific arguments.
    """
    if <MASK>:
        if pickle_module is not None:
            raise RuntimeError('Can not safely load weights when explicit pickle_module is specified')
        pickle_module = _weights_only_unpickler
    elif pickle_module is None:
        pickle_module = pickle
    if 'encoding' not in pickle_load_args.keys():
        pickle_load_args['encoding'] = 'utf-8'
    zip_file = _PseudoZipFile()
    zip_file.read_from(f)
    return _load(zip_file=zip_file, map_location=map_location, pickle_module=pickle_module, **pickle_load_args)

def should_skip_descriptor_setter(self, attr_name):
