        raise ValueError(f'cannot use inplace with {type(self).__name__}')
    result = attr(self._data, *args, **kwargs)
    if wrap:
        if <MASK>:
            return type(self)._simple_new(result, name=self.name)
        elif isinstance(result, ABCDataFrame):
            return result.set_index(self)
        return Index(result, name=self.name, dtype=result.dtype)
    return result

def track_symint(source: Source, val: IntLikeType, constraint: DimConstraint=None) -> None:
    log.debug('track_symint %s %s %s', LazyString(source.name), val, constraint)
    assert not isinstance(val, SymInt) or is_symbolic(val)
    if isinstance(val, SymInt) and val.node.maybe_as_int() is not None:
        val = val.node.maybe_as_int()
    if isinstance(val, SymInt):
        s = val.node.expr
        if isinstance(s, sympy.Symbol):
            symbol_to_source[s].append(source)
            if constraint is not None and (not isinstance(constraint, RelaxedUnspecConstraint)):
                symbol_to_constraints[s].add(constraint)
        else:
            constraint_violated = False
            if isinstance(constraint, StrictMinMaxConstraint):
                sym_vrs = {x: self.var_to_range.get(x, None) for x in s.free_symbols}
                if any((vr is None for vr in sym_vrs.values())):
                    constraint_violated = True
            elif isinstance(constraint, RelaxedUnspecConstraint):
                if s.is_number:
                    i = int(s)
                    if i not in (0, 1):
                        constraint_violated = True
            if constraint_violated:
                assert constraint is not None

                def hint(s: sympy.Expr) -> str:
                    sexpr = py_printer.doprint(s)
                    return f'{sexpr}.'
                var_with_range = self._render_range_for_constraint_violation(source, constraint)
                msg = f'Not all values of {var_with_range} are valid because {self._debug_name(source)} was inferred to be equal to '
                record_constraint_violation(constraint.warn_only, self._debug_name(source), msg, hint=functools.partial(hint, s))
        input_guards.append((source, s))
    else:
        s = sympy.Integer(val)
        input_guards.append((source, s))
        constraint_violated = False
        if isinstance(constraint, StrictMinMaxConstraint):
            if <MASK>:
                constraint_violated = True
        elif isinstance(constraint, RelaxedUnspecConstraint):
            if val not in (0, 1):
                constraint_violated = True
        if constraint_violated:
            assert constraint is not None
            var_with_range = self._render_range_for_constraint_violation(source, constraint)
            user_stack = self.specialization_stacks.get(source, None)
            msg = f"You marked {self._debug_name(source)} as dynamic but your code specialized it to be a constant ({val}). If you're using mark_dynamic, either remove it or use maybe_mark_dynamic. If you're using Dim.DYNAMIC, replace it with either Dim.STATIC or Dim.AUTO." + ('\n\nUser stack:\n' + ''.join(user_stack.format()) if user_stack else '')
            record_constraint_violation(constraint.warn_only, self._debug_name(source), msg)

def as_sqlite(self, compiler, connection, **extra_context):
    if <MASK>:
        extra_context['template'] = '%(function)s(%(expressions)s, %(spheroid)d)'
        extra_context['spheroid'] = True
    return self.as_sql(compiler, connection, **extra_context)

def _mark_nodes_as_annotated(nodes: list[Node]):
    for node in nodes:
        if node is not None:
            if <MASK>:
                node.meta[QUANT_ANNOTATION_KEY] = _X86InductorQuantizationAnnotation()
            node.meta[QUANT_ANNOTATION_KEY]._annotated = True

def _match(self, node: torch.fx.Node, ctx: MatchContext):
    m = super()._match(node, ctx)
    if not m:
        return m
    split_sections = node.args[1]
    if not isinstance(split_sections, (list, tuple)):
        return FailedMatch('split not normalized')
    seen_idxs = OrderedSet[int]()
    for user in node.users:
        if not CallFunction(operator.getitem, Arg(), Arg()).match(user):
            return FailedMatch(f'user of split not a getitem: {user}')
        if <MASK>:
            return FailedMatch('only integer getitems are handled')
        if user.args[1] in seen_idxs:
            return FailedMatch(f'duplicate getitem {user.args[1]}')
        if user.args[-1] < 0:
            return FailedMatch('negative index')
        seen_idxs.add(user.args[1])
    return m

def _limit_features(self, X, vocabulary, high=None, low=None, limit=None):
    """Remove too rare or too common features.

        Prune features that are non zero in more samples than high or less
        documents than low, modifying the vocabulary, and restricting it to
        at most the limit most frequent.

        This does not prune samples with zero features.
        """
    if high is None and low is None and (limit is None):
        return (X, set())
    dfs = _document_frequency(X)
    mask = np.ones(len(dfs), dtype=bool)
    if high is not None:
        mask &= dfs <= high
    if low is not None:
        mask &= dfs >= low
    if <MASK>:
        tfs = np.asarray(X.sum(axis=0)).ravel()
        mask_inds = (-tfs[mask]).argsort()[:limit]
        new_mask = np.zeros(len(dfs), dtype=bool)
        new_mask[np.where(mask)[0][mask_inds]] = True
        mask = new_mask
    new_indices = np.cumsum(mask) - 1
    for (term, old_index) in list(vocabulary.items()):
        if mask[old_index]:
            vocabulary[term] = new_indices[old_index]
        else:
            del vocabulary[term]
    kept_indices = np.where(mask)[0]
    if len(kept_indices) == 0:
        raise ValueError('After pruning, no terms remain. Try a lower min_df or a higher max_df.')
    return X[:, kept_indices]

def __setmask__(self, mask, copy=False):
    """
        Set the mask.

        """
    idtype = self.dtype
    current_mask = self._mask
    if mask is masked:
        mask = True
    if current_mask is nomask:
        if mask is nomask:
            return
        current_mask = self._mask = make_mask_none(self.shape, idtype)
    if idtype.names is None:
        if self._hardmask:
            current_mask |= mask
        elif isinstance(mask, (int, float, np.bool, np.number)):
            current_mask[...] = mask
        else:
            current_mask.flat = mask
    else:
        mdtype = current_mask.dtype
        mask = np.asarray(mask)
        if not mask.ndim:
            if mask.dtype.kind == 'b':
                mask = np.array(tuple([mask.item()] * len(mdtype)), dtype=mdtype)
            else:
                mask = mask.astype(mdtype)
        else:
            try:
                copy = None if not copy else True
                mask = np.array(mask, copy=copy, dtype=mdtype)
            except TypeError:
                mask = np.array([tuple([m] * len(mdtype)) for m in mask], dtype=mdtype)
        if self._hardmask:
            for n in idtype.names:
                current_mask[n] |= mask[n]
        elif isinstance(mask, (int, float, np.bool, np.number)):
            current_mask[...] = mask
        else:
            current_mask.flat = mask
    if <MASK>:
        current_mask.shape = self.shape
    return

def __init__(self, lhs, rhs):
    if <MASK>:
        expressions = []
        for value in rhs:
            if not hasattr(value, 'resolve_expression'):
                field = lhs.output_field
                value = Value(field.base_field.get_prep_value(value))
            expressions.append(value)
        rhs = Func(*expressions, function='ARRAY', template='%(function)s[%(expressions)s]')
    super().__init__(lhs, rhs)

def conditional_escape(text):
    """
    Similar to escape(), except that it doesn't operate on pre-escaped strings.

    This function relies on the __html__ convention used both by Django's
    SafeData class and by third-party libraries like markupsafe.
    """
    if <MASK>:
        text = str(text)
    if hasattr(text, '__html__'):
        return text.__html__()
    else:
        return escape(text)

