    return ConstantVariable.create(None)

@classmethod
def from_params(cls, wi, wh, bi=None, bh=None, split_gates=False):
    """Uses the weights and biases to create a new LSTM cell.

        Args:
            wi, wh: Weights for the input and hidden layers
            bi, bh: Biases for the input and hidden layers
        """
    assert (bi is None) == (bh is None)
    input_size = wi.shape[1]
    hidden_size = wh.shape[1]
    cell = cls(input_dim=input_size, hidden_dim=hidden_size, bias=bi is not None, split_gates=split_gates)
    if <MASK>:
        cell.igates.weight = torch.nn.Parameter(wi)
        if bi is not None:
            cell.igates.bias = torch.nn.Parameter(bi)
        cell.hgates.weight = torch.nn.Parameter(wh)
        if bh is not None:
            cell.hgates.bias = torch.nn.Parameter(bh)
    else:
        for (w, b, gates) in zip([wi, wh], [bi, bh], [cell.igates, cell.hgates]):
            for (w_chunk, gate) in zip(w.chunk(4, dim=0), gates.values()):
                gate.weight = torch.nn.Parameter(w_chunk)
            if b is not None:
                for (b_chunk, gate) in zip(b.chunk(4, dim=0), gates.values()):
                    gate.bias = torch.nn.Parameter(b_chunk)
    return cell

def build_npy_pkg_config(self):
    log.info('build_src: building npy-pkg config files')
    install_cmd = copy.copy(get_cmd('install'))
    if not install_cmd.finalized == 1:
        install_cmd.finalize_options()
    build_npkg = False
    if self.inplace == 1:
        top_prefix = '.'
        build_npkg = True
    elif <MASK>:
        top_prefix = install_cmd.install_libbase
        build_npkg = True
    if build_npkg:
        for (pkg, infos) in self.distribution.installed_pkg_config.items():
            pkg_path = self.distribution.package_dir[pkg]
            prefix = os.path.join(os.path.abspath(top_prefix), pkg_path)
            d = {'prefix': prefix}
            for info in infos:
                (install_dir, generated) = self._build_npy_pkg_config(info, d)
                self.distribution.data_files.append((install_dir, [generated]))

def testSyncOnReadVariableInput(self, strategy, tf_function):
    if not strategy_test_lib.is_mirrored_strategy(strategy) and (not strategy_test_lib.is_multi_worker_mirrored_strategy(strategy)) and (not strategy_test_lib.is_tpu_strategy(strategy)):
        self.skipTest('Skip strategies not using SyncOnReadVariables.')
    if strategy_test_lib.is_tpu_strategy(strategy) and tf_function is combinations.no_tf_function:
        self.skipTest('Skip TPUStrategy + eager combination.')
    if <MASK>:
        self.skipTest('Skip MWMS + graph combination until b/228512201 is fixed.')
    with strategy.scope():
        var = variables.Variable(0.0, synchronization=variables.VariableSynchronization.ON_READ, aggregation=variables.VariableAggregation.ONLY_FIRST_REPLICA)

    @tf_function
    def replica_fn():
        replica_context = distribute_lib.get_replica_context()
        replica_id = replica_context.replica_id_in_sync_group
        var.assign(math_ops.cast(replica_id, dtype=float) * 3.0)
        return replica_context.all_reduce(reduce_util.ReduceOp.SUM, var)
    if strategy_test_lib.is_multi_worker_mirrored_strategy(strategy):
        client_local_replica_num = strategy.extended._num_devices_per_worker
    else:
        client_local_replica_num = strategy.num_replicas_in_sync
    workers_num = strategy.num_replicas_in_sync
    expected_sum = sum(range(workers_num)) * 3.0
    result = strategy.run(replica_fn)
    if hasattr(result, 'values'):
        result = result.values
    result = nest.flatten(result)
    for i in range(client_local_replica_num):
        self.assertEqual(result[i].numpy(), expected_sum)

def visit_Return(self, node):
    values = self.visit(node.value)
    if <MASK>:
        self.emit('\nscf.yield ')
    else:
        self.emit('\ntfr.return ')
    if not values:
        return
    if isinstance(values, list):
        (vals, tys) = zip(*values)
    else:
        vals = values[0]
        tys = values[1]
    if isinstance(tys, list) or isinstance(tys, tuple):
        tys = [str(t) for t in tys]
        self._emit_with_loc('{} : {}'.format(', '.join(vals), ', '.join(tys)), node)
    elif tys != TFRTypes.NONE:
        self._emit_with_loc('{} : {}'.format(vals, tys), node)

@ignore_warnings(category=FutureWarning)
def check_estimators_data_not_an_array(name, estimator_orig, X, y, obj_type):
    if <MASK>:
        raise SkipTest('Skipping check_estimators_data_not_an_array for cross decomposition module as estimators are not deterministic.')
    estimator_1 = clone(estimator_orig)
    estimator_2 = clone(estimator_orig)
    set_random_state(estimator_1)
    set_random_state(estimator_2)
    if obj_type not in ['NotAnArray', 'PandasDataframe']:
        raise ValueError('Data type {0} not supported'.format(obj_type))
    if obj_type == 'NotAnArray':
        y_ = _NotAnArray(np.asarray(y))
        X_ = _NotAnArray(np.asarray(X))
    else:
        try:
            import pandas as pd
            y_ = np.asarray(y)
            if y_.ndim == 1:
                y_ = pd.Series(y_, copy=False)
            else:
                y_ = pd.DataFrame(y_, copy=False)
            X_ = pd.DataFrame(np.asarray(X), copy=False)
        except ImportError:
            raise SkipTest('pandas is not installed: not checking estimators for pandas objects.')
    estimator_1.fit(X_, y_)
    pred1 = estimator_1.predict(X_)
    estimator_2.fit(X, y)
    pred2 = estimator_2.predict(X)
    assert_allclose(pred1, pred2, atol=0.01, err_msg=name)

def __init__(self, ds_input, write=False):
    self._write = 1 if write else 0
    Driver.ensure_registered()
    if isinstance(ds_input, str) and json_regex.match(ds_input):
        ds_input = json.loads(ds_input)
    if isinstance(ds_input, (str, Path)):
        ds_input = str(ds_input)
        if not ds_input.startswith(VSI_FILESYSTEM_PREFIX) and (not os.path.exists(ds_input)):
            raise GDALException('Unable to read raster source input "%s".' % ds_input)
        try:
            self._ptr = capi.open_ds(force_bytes(ds_input), self._write)
        except GDALException as err:
            raise GDALException('Could not open the datasource at "{}" ({}).'.format(ds_input, err))
    elif isinstance(ds_input, bytes):
        self._write = 1
        size = sys.getsizeof(ds_input)
        self._ds_input = c_buffer(ds_input)
        vsi_path = os.path.join(VSI_MEM_FILESYSTEM_BASE_PATH, str(uuid.uuid4()))
        capi.create_vsi_file_from_mem_buffer(force_bytes(vsi_path), byref(self._ds_input), size, VSI_TAKE_BUFFER_OWNERSHIP)
        try:
            self._ptr = capi.open_ds(force_bytes(vsi_path), self._write)
        except GDALException:
            capi.unlink_vsi_file(force_bytes(vsi_path))
            raise GDALException('Failed creating VSI raster from the input buffer.')
    elif isinstance(ds_input, dict):
        self._write = 1
        driver = Driver(ds_input.get('driver', 'MEM'))
        if driver.name != 'MEM' and 'name' not in ds_input:
            raise GDALException('Specify name for creation of raster with driver "{}".'.format(driver.name))
        if 'width' not in ds_input or 'height' not in ds_input:
            raise GDALException('Specify width and height attributes for JSON or dict input.')
        if 'srid' not in ds_input:
            raise GDALException('Specify srid for JSON or dict input.')
        papsz_options = []
        for (key, val) in ds_input.get('papsz_options', {}).items():
            option = '{}={}'.format(key, val)
            papsz_options.append(option.upper().encode())
        papsz_options.append(None)
        papsz_options = (c_char_p * len(papsz_options))(*papsz_options)
        self._ptr = capi.create_ds(driver._ptr, force_bytes(ds_input.get('name', '')), ds_input['width'], ds_input['height'], ds_input.get('nr_of_bands', len(ds_input.get('bands', []))), ds_input.get('datatype', 6), byref(papsz_options))
        for (i, band_input) in enumerate(ds_input.get('bands', [])):
            band = self.bands[i]
            if 'nodata_value' in band_input:
                band.nodata_value = band_input['nodata_value']
                if band.nodata_value is not None and ('data' not in band_input or 'size' in band_input or 'shape' in band_input):
                    band.data(data=(band.nodata_value,), shape=(1, 1))
            band.data(data=band_input.get('data'), size=band_input.get('size'), shape=band_input.get('shape'), offset=band_input.get('offset'))
        self.srs = ds_input.get('srid')
        if 'origin' in ds_input:
            (self.origin.x, self.origin.y) = ds_input['origin']
        if 'scale' in ds_input:
            (self.scale.x, self.scale.y) = ds_input['scale']
        if 'skew' in ds_input:
            (self.skew.x, self.skew.y) = ds_input['skew']
    elif <MASK>:
        self._ptr = ds_input
    else:
        raise GDALException('Invalid data source input type: "{}".'.format(type(ds_input)))

def dimlists(n: Optional[int]=None, sizes: Optional[list[Optional[int]]]=None) -> Union[DimList, tuple[DimList, ...]]:
    """
    Create and return one or more DimList objects.

    Similar to dims() but creates DimList objects instead.
    """
    specified_ndims = -1
    found_ndims = 0
    if sizes is not None:
        specified_ndims = len(sizes)
    if n is not None:
        specified_ndims = n
    frame = inspect.currentframe()
    if frame is None:
        raise RuntimeError('Unable to get current frame')
    frame = frame.f_back
    try:
        if frame is None:
            raise RuntimeError('Unable to get caller frame')
        code = frame.f_code
        lasti = frame.f_lasti
        decoder = _PyInstDecoder(code, lasti)
        if sys.version_info >= (3, 11):
            if <MASK>:
                decoder.next()
        decoder.next()
        if _relevant_op(decoder.opcode()):
            found_ndims = 1
        elif decoder.opcode() == 'UNPACK_SEQUENCE':
            found_ndims = decoder.oparg()
            decoder.next()
        if specified_ndims == -1:
            if found_ndims == 0:
                raise SyntaxError('dimlists() must be assigned to a sequence of variable names or have argument n specified')
            specified_ndims = found_ndims
        if found_ndims != specified_ndims:
            found_ndims = 0

        def genobject(i: int) -> str:
            nonlocal found_ndims
            name = None
            if i < found_ndims:
                name = decoder.name()
            if not name:
                name = f'd{i}'
                found_ndims = 0
            else:
                decoder.next()
            return name
        if sizes is not None and len(sizes) != specified_ndims:
            raise ValueError(f'expected {specified_ndims} sizes but found {len(sizes)}')
        if specified_ndims == 1:
            name = genobject(0)
            return _create_dimlist(name, sizes[0] if sizes is not None else None)
        result = []
        for i in range(specified_ndims):
            name = genobject(i)
            size = sizes[i] if sizes is not None else None
            result.append(_create_dimlist(name, size))
        return tuple(result)
    finally:
        del frame
